def safe_for_serialization(value):
    """Transform a value in preparation for serializing as json

    no-op for strings, mappings and iterables have their entries made safe,
    and all other values are stringified, with a fallback value if that fails"""
    if isinstance(value, six.string_types):
        return value
    if isinstance(value, dict):
        return {safe_for_serialization(key): safe_for_serialization(val) for key, val in six.iteritems(value)}
    if isinstance(value, collections.Iterable):
        return list(map(safe_for_serialization, value))
    try:
        return six.text_type(value)
    except Exception:
        return '[__unicode__ failed]'

def serialize(exc):
    """Serialize `self.exc` into a data dictionary representing it.
    """
    return {'exc_type': type(exc).__name__, 'exc_path': get_module_path(type(exc)), 'exc_args': list(map(safe_for_serialization, exc.args)), 'value': safe_for_serialization(exc)}

def deserialize(data):
    """Deserialize `data` to an exception instance.

    If the `exc_path` value matches an exception registered as
    ``deserializable``, return an instance of that exception type.
    Otherwise, return a `RemoteError` instance describing the exception
    that occurred."""
    key = data.get('exc_path')
    if key in registry:
        exc_args = data.get('exc_args', ())
        return registry[key](*exc_args)
    exc_type = data.get('exc_type')
    value = data.get('value')
    return RemoteError(exc_type=exc_type, value=value)

def import_from_path(path):
    """Import and return the object at `path` if it exists.

    Raises an :exc:`ImportError` if the object is not found."""
    if path is None:
        return
    obj = locate(path)
    if obj is None:
        raise ImportError('`{}` could not be imported'.format(path))
    return obj

def sanitize_url(url):
    """Redact password in urls."""
    parts = urlparse(url)
    if parts.password is None:
        return url
    host_info = parts.netloc.rsplit('@', 1)[-1]
    parts = parts._replace(netloc='{}:{}@{}'.format(parts.username, REDACTED, host_info))
    return parts.geturl()

def iter_extensions(extension):
    """Depth-first iterator over sub-extensions on `extension`.
    """
    for _, ext in inspect.getmembers(extension, is_extension):
        for item in iter_extensions(ext):
            yield item
        yield ext

def requirements_from_file(filename):
    """Parses a pip requirements file into a list."""
    return [line.strip() for line in open(filename, 'r') if line.strip() and (not line.strip().startswith('--'))]

def make_qs(n, m=None):
    """Make sympy symbols q0, q1, ...

    Args:
        n(int), m(int, optional):
            If specified both n and m, returns [qn, q(n+1), ..., qm],
            Only n is specified, returns[q0, q1, ..., qn].

    Return:
        tuple(Symbol): Tuple of sympy symbols."""
    try:
        import sympy
    except ImportError:
        raise ImportError('This function requires sympy. Please install it.')
    if m is None:
        syms = sympy.symbols(' '.join((f'q{i}' for i in range(n))))
        if isinstance(syms, tuple):
            return syms
        else:
            return (syms,)
    syms = sympy.symbols(' '.join((f'q{i}' for i in range(n, m))))
    if isinstance(syms, tuple):
        return syms
    else:
        return (syms,)

def numpartition_qaoa(n_step, nums, minimizer=None, sampler=None):
    """Do the Number partition QAOA.

    :param n_step: The number of step of QAOA
    :param nums: The edges list of the graph.
    :returns Vqe object"""
    hamiltonian = pauli.Expr.zero()
    for i, x in enumerate(nums):
        hamiltonian += pauli.Z[i] * x
    hamiltonian = (hamiltonian ** 2).simplify()
    return vqe.Vqe(vqe.QaoaAnsatz(hamiltonian, n_step), minimizer, sampler)

def slicing(args, length):
    """Internally used."""
    if isinstance(args, tuple):
        for arg in args:
            yield from slicing_singlevalue(arg, length)
    else:
        yield from slicing_singlevalue(args, length)

def qubit_pairs(args, length):
    """Internally used."""
    if not isinstance(args, tuple):
        raise ValueError('Control and target qubits pair(s) are required.')
    if len(args) != 2:
        raise ValueError('Control and target qubits pair(s) are required.')
    controls = list(slicing(args[0], length))
    targets = list(slicing(args[1], length))
    if len(controls) != len(targets):
        raise ValueError('The number of control qubits and target qubits are must be same.')
    for c, z in zip(controls, targets):
        if c == z:
            raise ValueError('Control qubit and target qubit are must be different.')
    return zip(controls, targets)

def get_maximum_index(indices):
    """Internally used."""
    def _maximum_idx_single(idx):
        if isinstance(idx, slice):
            start = -1
            stop = 0
            if idx.start is not None:
                start = idx.start.__index__()
            if idx.stop is not None:
                stop = idx.stop.__index__()
            return max(start, stop - 1)
        else:
            return idx.__index__()
    if isinstance(indices, tuple):
        return max((_maximum_idx_single(i) for i in indices), default=-1)
    else:
        return _maximum_idx_single(indices)

def to_inttuple(bitstr):
    """Convert from bit string likes '01011' to int tuple likes (0, 1, 0, 1, 1)

    Args:
        bitstr (str, Counter, dict): String which is written in "0" or "1".
            If all keys are bitstr, Counter or dict are also can be converted by this function.

    Returns:
        tuple of int, Counter, dict: Converted bits.
            If bitstr is Counter or dict, returns the Counter or dict
            which contains {converted key: original value}.

    Raises:
        ValueError: If bitstr type is unexpected or bitstr contains illegal character."""
    if isinstance(bitstr, str):
        return tuple((int(b) for b in bitstr))
    if isinstance(bitstr, Counter):
        return Counter({tuple((int(b) for b in k)): v for k, v in bitstr.items()})
    if isinstance(bitstr, dict):
        return {tuple((int(b) for b in k)): v for k, v in bitstr.items()}
    raise ValueError('bitstr type shall be `str`, `Counter` or `dict`')

def expect(qubits, meas):
    """For the VQE simulation without sampling."""
    result = {}
    i = np.arange(len(qubits))
    meas = tuple(meas)
    def to_mask(n):
        return reduce(lambda acc, im: acc | (n & 1 << im[0]) << im[1] - im[0], enumerate(meas), 0)
    def to_key(k):
        return tuple((1 if k & 1 << i else 0 for i in meas))
    mask = reduce(lambda acc, v: acc | 1 << v, meas, 0)
    cnt = defaultdict(float)
    for i, v in enumerate(qubits):
        p = v.real ** 2 + v.imag ** 2
        if p != 0.0:
            cnt[i & mask] += p
    return {to_key(k): v for k, v in cnt.items()}

def non_sampling_sampler(circuit, meas):
    """Calculate the expectations without sampling."""
    meas = tuple(meas)
    n_qubits = circuit.n_qubits
    return expect(circuit.run(returns='statevector'), meas)

def get_measurement_sampler(n_sample, run_options=None):
    """Returns a function which get the expectations by sampling the measured circuit"""
    if run_options is None:
        run_options = {}
    def sampling_by_measurement(circuit, meas):
        def reduce_bits(bits, meas):
            bits = [int(x) for x in bits[::-1]]
            return tuple((bits[m] for m in meas))
        meas = tuple(meas)
        circuit.measure[meas]
        counter = circuit.run(shots=n_sample, returns='shots', **run_options)
        counts = Counter({reduce_bits(bits, meas): val for bits, val in counter.items()})
        return {k: v / n_sample for k, v in counts.items()}
    return sampling_by_measurement

def get_state_vector_sampler(n_sample):
    """Returns a function which get the expectations by sampling the state vector"""
    def sampling_by_measurement(circuit, meas):
        val = 0.0
        e = expect(circuit.run(returns='statevector'), meas)
        bits, probs = zip(*e.items())
        dists = np.random.multinomial(n_sample, probs) / n_sample
        return dict(zip(tuple(bits), dists))
    return sampling_by_measurement

def factoring_qaoa(n_step, num, minimizer=None, sampler=None, verbose=True):
    """Do the Number partition QAOA.

    :param num: The number to be factoring.
    :param n_step: The number of step of QAOA
    :param edges: The edges list of the graph.
    :returns result of QAOA"""
    def get_nbit(n):
        m = 1
        while 2 ** m < n:
            m += 1
        return m
    n1_bits = get_nbit(int(num ** 0.5)) - 1
    n2_bits = get_nbit(int(num ** 0.5))
    def mk_expr(offset, n):
        expr = pauli.Expr.from_number(1)
        for i in range(n):
            expr = expr + 2 ** (i + 1) * q(i + offset)
        return expr
    def bitseparator(bits):
        assert len(bits) == n1_bits + n2_bits
        p = 1
        m = 1
        for b in bits[:n1_bits]:
            if b:
                p += 2 ** m
            m += 1
        q = 1
        m = 1
        for b in bits[n1_bits:]:
            if b:
                q += 2 ** m
            m += 1
        return (p, q)
    hamiltonian = (num - mk_expr(0, n1_bits) * mk_expr(n1_bits, n2_bits)) ** 2
    return (vqe.Vqe(vqe.QaoaAnsatz(hamiltonian, n_step), minimizer, sampler), bitseparator)

def pauli_from_char(ch, n=0):
    """Make Pauli matrix from an character.

    Args:
        ch (str): "X" or "Y" or "Z" or "I".
        n (int, optional): Make Pauli matrix as n-th qubits.

    Returns:
        If ch is "X" => X, "Y" => Y, "Z" => Z, "I" => I

    Raises:
        ValueError: When ch is not "X", "Y", "Z" nor "I"."""
    ch = ch.upper()
    if ch == 'I':
        return I
    if ch == 'X':
        return X(n)
    if ch == 'Y':
        return Y(n)
    if ch == 'Z':
        return Z(n)
    raise ValueError('ch shall be X, Y, Z or I')

def parse_session_cookie(cookie_to_cook):
    """cookie_to_cook = http_header['cookie']
    """
    session_value = None
    tokens = cookie_to_cook.split(';')
    for tok in tokens:
        if 'remi_session=' in tok:
            try:
                session_value = int(tok.replace('remi_session=', ''))
            except:
                pass
    return session_value

def open(uri, mode, min_part_size=WEBHDFS_MIN_PART_SIZE):
    """Parameters
    ----------
    min_part_size: int, optional
        For writing only."""
    if mode == 'rb':
        return BufferedInputBase(uri)
    elif mode == 'wb':
        return BufferedOutputBase(uri, min_part_size=min_part_size)
    else:
        raise NotImplementedError('webhdfs support for mode %r not implemented' % mode)

def smart_open(uri, mode='rb', **kw):
    """Deprecated, use smart_open.open instead."""
    logger.warning('this function is deprecated, use smart_open.open instead')
    ignore_extension = kw.pop('ignore_extension', False)
    expected_kwargs = _inspect_kwargs(open)
    scrubbed_kwargs = {}
    transport_params = {}
    if 'host' in kw or 's3_upload' in kw:
        transport_params['multipart_upload_kwargs'] = {}
        transport_params['resource_kwargs'] = {}
    if 'host' in kw:
        url = kw.pop('host')
        if not url.startswith('http'):
            url = 'http://' + url
        transport_params['resource_kwargs'].update(endpoint_url=url)
    if 's3_upload' in kw and kw['s3_upload']:
        transport_params['multipart_upload_kwargs'].update(**kw.pop('s3_upload'))
    if 'profile_name' in kw and 's3_session' in kw:
        logger.error('profile_name and s3_session are mutually exclusive, ignoring the former')
    if 'profile_name' in kw:
        transport_params['session'] = boto3.Session(profile_name=kw.pop('profile_name'))
    if 's3_session' in kw:
        transport_params['session'] = kw.pop('s3_session')
    for key, value in kw.items():
        if key in expected_kwargs:
            scrubbed_kwargs[key] = value
        else:
            transport_params[key] = value
    return open(uri, mode, ignore_ext=ignore_extension, transport_params=transport_params, **scrubbed_kwargs)

def _shortcut_open(uri, mode, ignore_ext=False, buffering=-1, encoding=None, errors=None):
    """Try to open the URI using the standard library io.open function.

    This can be much faster than the alternative of opening in binary mode and
    then decoding.

    This is only possible under the following conditions:

        1. Opening a local file
        2. Ignore extension is set to True

    If it is not possible to use the built-in open for the specified URI, returns None.

    :param str uri: A string indicating what to open.
    :param str mode: The mode to pass to the open function.
    :param dict kw:
    :returns: The opened file
    :rtype: file"""
    if not isinstance(uri, six.string_types):
        return None
    parsed_uri = _parse_uri(uri)
    if parsed_uri.scheme != 'file':
        return None
    _, extension = P.splitext(parsed_uri.uri_path)
    if extension in _COMPRESSOR_REGISTRY and (not ignore_ext):
        return None
    open_kwargs = {}
    if encoding is not None:
        open_kwargs['encoding'] = encoding
        mode = mode.replace('b', '')
    if errors and 'b' not in mode:
        open_kwargs['errors'] = errors
    if six.PY3:
        return _builtin_open(parsed_uri.uri_path, mode, buffering=buffering, **open_kwargs)
    elif not open_kwargs:
        return _builtin_open(parsed_uri.uri_path, mode, buffering=buffering)
    return io.open(parsed_uri.uri_path, mode, buffering=buffering, **open_kwargs)

def _parse_uri_ssh(unt):
    """Parse a Uri from a urllib namedtuple."""
    if '@' in unt.netloc:
        user, host_port = unt.netloc.split('@', 1)
    else:
        user, host_port = (None, unt.netloc)
    if ':' in host_port:
        host, port = host_port.split(':', 1)
    else:
        host, port = (host_port, None)
    if not user:
        user = None
    if not port:
        port = smart_open_ssh.DEFAULT_PORT
    else:
        port = int(port)
    return Uri(scheme=unt.scheme, uri_path=unt.path, user=user, host=host, port=port)

def _need_to_buffer(file_obj, mode, ext):
    """Returns True if we need to buffer the whole file in memory in order to proceed."""
    try:
        is_seekable = file_obj.seekable()
    except AttributeError:
        is_seekable = hasattr(file_obj, 'seek')
    return six.PY2 and mode.startswith('r') and (ext in _COMPRESSOR_REGISTRY) and (not is_seekable)

def _compression_wrapper(file_obj, filename, mode):
    """This function will wrap the file_obj with an appropriate
    [de]compression mechanism based on the extension of the filename.

    file_obj must either be a filehandle object, or a class which behaves
        like one.

    If the filename extension isn't recognized, will simply return the original
    file_obj."""
    _, ext = os.path.splitext(filename)
    if _need_to_buffer(file_obj, mode, ext):
        warnings.warn('streaming gzip support unavailable, see %s' % _ISSUE_189_URL)
        file_obj = io.BytesIO(file_obj.read())
    if ext in _COMPRESSOR_REGISTRY and mode.endswith('+'):
        raise ValueError('transparent (de)compression unsupported for mode %r' % mode)
    try:
        callback = _COMPRESSOR_REGISTRY[ext]
    except KeyError:
        return file_obj
    else:
        return callback(file_obj, mode)

def _encoding_wrapper(fileobj, mode, encoding=None, errors=None):
    """Decode bytes into text, if necessary.

    If mode specifies binary access, does nothing, unless the encoding is
    specified.  A non-null encoding implies text mode.

    :arg fileobj: must quack like a filehandle object.
    :arg str mode: is the mode which was originally requested by the user.
    :arg str encoding: The text encoding to use.  If mode is binary, overrides mode.
    :arg str errors: The method to use when handling encoding/decoding errors.
    :returns: a file object"""
    logger.debug('encoding_wrapper: %r', locals())
    if 'b' in mode and encoding is None:
        return fileobj
    if encoding is None:
        encoding = SYSTEM_ENCODING
    kw = {'errors': errors} if errors else {}
    if mode[0] == 'r' or mode.endswith('+'):
        fileobj = codecs.getreader(encoding)(fileobj, **kw)
    if mode[0] in ('w', 'a') or mode.endswith('+'):
        fileobj = codecs.getwriter(encoding)(fileobj, **kw)
    return fileobj

def get_default(name, value):
    """return value from environment variables with name EXAMPLE_<name>
    or value"""
    return os.environ.get('EXAMPLE_{}'.format(name.upper()), value)

def build_plan(description, graph, targets=None, reverse=False):
    """Builds a plan from a list of steps.
    Args:
        description (str): an arbitrary string to
            describe the plan.
        graph (:class:`Graph`): a list of :class:`Graph` to execute.
        targets (list): an optional list of step names to filter the graph to.
            If provided, only these steps, and their transitive dependencies
            will be executed. If no targets are specified, every node in the
            graph will be executed.
        reverse (bool): If provided, the graph will be walked in reverse order
            (dependencies last)."""
    if reverse:
        graph = graph.transposed()
    if targets:
        nodes = []
        for target in targets:
            for k, step in graph.steps.items():
                if step.name == target:
                    nodes.append(step.name)
        graph = graph.filtered(nodes)
    return Plan(description=description, graph=graph)

def build_graph(steps):
    """Builds a graph of steps.
    Args:
        steps (list): a list of :class:`Step` objects to execute."""
    graph = Graph()
    for step in steps:
        graph.add_step(step)
    for step in steps:
        for dep in step.requires:
            graph.connect(step.name, dep)
        for parent in step.required_by:
            graph.connect(parent, step.name)
    return graph

def _get_val_from_ddb_data(data, keylist):
    """Given a dictionary of dynamodb data (including the datatypes) and a
    properly structured keylist, it will return the value of the lookup

    Args:
        data (dict): the raw dynamodb data
            keylist(list): a list of keys to lookup. This must include the
                datatype

    Returns:
        various: It returns the value from the dynamodb record, and casts it
            to a matching python datatype"""
    next_type = None
    for k in keylist:
        for k1 in k:
            if next_type is None:
                data = data[k[k1]]
            else:
                temp_dict = data[next_type]
                data = temp_dict[k[k1]]
            next_type = k1
    if next_type == 'L':
        return _convert_ddb_list_to_list(data[next_type])
    if next_type == 'N':
        return int(data[next_type])
    return str(data[next_type])

def _head_object(s3_conn, bucket, key):
    """Retrieve information about an object in S3 if it exists.

    Args:
        s3_conn (botocore.client.S3): S3 connection to use for operations.
        bucket (str): name of the bucket containing the key.
        key (str): name of the key to lookup.

    Returns:
        dict: S3 object information, or None if the object does not exist.
            See the AWS documentation for explanation of the contents.

    Raises:
        botocore.exceptions.ClientError: any error from boto3 other than key
            not found is passed through."""
    try:
        return s3_conn.head_object(Bucket=bucket, Key=key)
    except botocore.exceptions.ClientError as e:
        if e.response['Error']['Code'] == '404':
            return None
        else:
            raise

def dot_format(out, graph, name='digraph'):
    """Outputs the graph using the graphviz "dot" format."""
    out.write('digraph %s {\n' % name)
    for step, deps in each_step(graph):
        for dep in deps:
            out.write('  "%s" -> "%s";\n' % (step, dep))
    out.write('}\n')

def json_format(out, graph):
    """Outputs the graph in a machine readable JSON format."""
    steps = {}
    for step, deps in each_step(graph):
        steps[step.name] = {}
        steps[step.name]['deps'] = [dep.name for dep in deps]
    json.dump({'steps': steps}, out, indent=4)
    out.write('\n')

def get_cert_contents(kwargs):
    """Builds parameters with server cert file contents.

    Args:
        kwargs(dict): The keyword args passed to ensure_server_cert_exists,
            optionally containing the paths to the cert, key and chain files.

    Returns:
        dict: A dictionary containing the appropriate parameters to supply to
            upload_server_certificate. An empty dictionary if there is a
            problem."""
    paths = {'certificate': kwargs.get('path_to_certificate'), 'private_key': kwargs.get('path_to_private_key'), 'chain': kwargs.get('path_to_chain')}
    for key, value in paths.items():
        if value is not None:
            continue
        path = input('Path to %s (skip): ' % (key,))
        if path == 'skip' or not path.strip():
            continue
        paths[key] = path
    parameters = {'ServerCertificateName': kwargs.get('cert_name')}
    for key, path in paths.items():
        if not path:
            continue
        try:
            contents = path.read()
        except AttributeError:
            with open(utils.full_path(path)) as read_file:
                contents = read_file.read()
        if key == 'certificate':
            parameters['CertificateBody'] = contents
        elif key == 'private_key':
            parameters['PrivateKey'] = contents
        elif key == 'chain':
            parameters['CertificateChain'] = contents
    return parameters

def get_template_path(filename):
    """Find raw template in working directory or in sys.path.

    template_path from config may refer to templates colocated with the Stacker
    config, or files in remote package_sources. Here, we emulate python module
    loading to find the path to the template.

    Args:
        filename (str): Template filename.

    Returns:
        Optional[str]: Path to file, or None if no file found"""
    if os.path.isfile(filename):
        return os.path.abspath(filename)
    for i in sys.path:
        if os.path.isfile(os.path.join(i, filename)):
            return os.path.abspath(os.path.join(i, filename))
    return None

def create_clusters(provider, context, **kwargs):
    """Creates ECS clusters.

    Expects a "clusters" argument, which should contain a list of cluster
    names to create.

    Args:
        provider (:class:`stacker.providers.base.BaseProvider`): provider
            instance
        context (:class:`stacker.context.Context`): context instance

    Returns: boolean for whether or not the hook succeeded."""
    conn = get_session(provider.region).client('ecs')
    try:
        clusters = kwargs['clusters']
    except KeyError:
        logger.error('setup_clusters hook missing "clusters" argument')
        return False
    if isinstance(clusters, basestring):
        clusters = [clusters]
    cluster_info = {}
    for cluster in clusters:
        logger.debug('Creating ECS cluster: %s', cluster)
        r = conn.create_cluster(clusterName=cluster)
        cluster_info[r['cluster']['clusterName']] = r
    return {'clusters': cluster_info}

def _parameterize_obj(obj):
    """Recursively parameterize all strings contained in an object.

    Parameterizes all values of a Mapping, all items of a Sequence, an
    unicode string, or pass other objects through unmodified.

    Byte strings will be interpreted as UTF-8.

    Args:
        obj: data to parameterize

    Return:
        A parameterized object to be included in a CloudFormation template.
        Mappings are converted to `dict`, Sequences are converted to  `list`,
        and strings possibly replaced by compositions of function calls."""
    if isinstance(obj, Mapping):
        return dict(((key, _parameterize_obj(value)) for key, value in obj.items()))
    elif isinstance(obj, bytes):
        return _parameterize_string(obj.decode('utf8'))
    elif isinstance(obj, str):
        return _parameterize_string(obj)
    elif isinstance(obj, Sequence):
        return list((_parameterize_obj(item) for item in obj))
    else:
        return obj

def ask_for_approval(full_changeset=None, params_diff=None, include_verbose=False):
    """Prompt the user for approval to execute a change set.

    Args:
        full_changeset (list, optional): A list of the full changeset that will
            be output if the user specifies verbose.
        params_diff (list, optional): A list of DictValue detailing the
            differences between two parameters returned by
            :func:`stacker.actions.diff.diff_dictionaries`
        include_verbose (bool, optional): Boolean for whether or not to include
            the verbose option"""
    approval_options = ['y', 'n']
    if include_verbose:
        approval_options.append('v')
    approve = ui.ask('Execute the above changes? [{}] '.format('/'.join(approval_options))).lower()
    if include_verbose and approve == 'v':
        if params_diff:
            logger.info('Full changeset:\n\n%s\n%s', format_params_diff(params_diff), yaml.safe_dump(full_changeset))
        else:
            logger.info('Full changeset:\n%s', yaml.safe_dump(full_changeset))
        return ask_for_approval()
    elif approve != 'y':
        raise exceptions.CancelExecution

def resolve_lookups(variable, context, provider):
    """Resolve a set of lookups.

    Args:
        variable (:class:`stacker.variables.Variable`): The variable resolving
            it's lookups.
        context (:class:`stacker.context.Context`): stacker context
        provider (:class:`stacker.provider.base.BaseProvider`): subclass of the
            base provider

    Returns:
        dict: dict of Lookup -> resolved value"""
    resolved_lookups = {}
    for lookup in variable.lookups:
        try:
            handler = LOOKUP_HANDLERS[lookup.type]
        except KeyError:
            raise UnknownLookupType(lookup)
        try:
            resolved_lookups[lookup] = handler(value=lookup.input, context=context, provider=provider)
        except Exception as e:
            raise FailedVariableLookup(variable.name, lookup, e)
    return resolved_lookups

def extract_lookups(value):
    """Recursively extracts any stack lookups within the data structure.

    Args:
        value (one of str, list, dict): a structure that contains lookups to
            output values

    Returns:
        list: list of lookups if any"""
    lookups = set()
    if isinstance(value, basestring):
        lookups = lookups.union(extract_lookups_from_string(value))
    elif isinstance(value, list):
        for v in value:
            lookups = lookups.union(extract_lookups(v))
    elif isinstance(value, dict):
        for v in value.values():
            lookups = lookups.union(extract_lookups(v))
    return lookups

def should_update(stack):
    """Tests whether a stack should be submitted for updates to CF.

    Args:
        stack (:class:`stacker.stack.Stack`): The stack object to check.

    Returns:
        bool: If the stack should be updated, return True."""
    if stack.locked:
        if not stack.force:
            logger.debug('Stack %s locked and not in --force list. Refusing to update.', stack.name)
            return False
        else:
            logger.debug('Stack %s locked, but is in --force list.', stack.name)
    return True

def get_hosted_zone_by_name(client, zone_name):
    """Get the zone id of an existing zone by name.

    Args:
        client (:class:`botocore.client.Route53`): The connection used to
            interact with Route53's API.
        zone_name (string): The name of the DNS hosted zone to create.

    Returns:
        string: The Id of the Hosted Zone."""
    p = client.get_paginator('list_hosted_zones')
    for i in p.paginate():
        for zone in i['HostedZones']:
            if zone['Name'] == zone_name:
                return parse_zone_id(zone['Id'])
    return None

def merge_map(a, b):
    """Recursively merge elements of argument b into argument a.

    Primarly used for merging two dictionaries together, where dict b takes
    precedence over dict a. If 2 lists are provided, they are concatenated."""
    if isinstance(a, list) and isinstance(b, list):
        return a + b
    if not isinstance(a, dict) or not isinstance(b, dict):
        return b
    for key in b:
        a[key] = merge_map(a[key], b[key]) if key in a else b[key]
    return a

