        cloned_config[key] = copy(config[key])
    return cloned_config

def create_cookie(name, value, domain, httponly=None, **kwargs):
    """Creates `cookielib.Cookie` instance"""
    if domain == 'localhost':
        domain = ''
    config = dict(name=name, value=value, version=0, port=None, domain=domain, path='/', secure=False, expires=None, discard=True, comment=None, comment_url=None, rfc2109=False, rest={'HttpOnly': httponly})
    for key in kwargs:
        if key not in config:
            raise GrabMisuseError('Function `create_cookie` does not accept `%s` argument' % key)
    config.update(**kwargs)
    config['rest']['HttpOnly'] = httponly
    config['port_specified'] = bool(config['port'])
    config['domain_specified'] = bool(config['domain'])
    config['domain_initial_dot'] = (config['domain'] or '').startswith('.')
    config['path_specified'] = bool(config['path'])
    return Cookie(**config)

def integrity(integrity_func, retry_errors=(ResponseNotValid,)):
    """Args:
        :param integrity_func: couldb callable or string contains name of
            method to call"""
    def build_decorator(func):
        @functools.wraps(func)
        def func_wrapper(self, grab, task):
            if isinstance(integrity_func, (list, tuple)):
                int_funcs = integrity_func
            else:
                int_funcs = [integrity_func]
            try:
                for int_func in int_funcs:
                    if isinstance(int_func, str):
                        getattr(self, int_func)(grab)
                    else:
                        int_func(grab)
            except retry_errors as ex:
                yield task.clone(refresh_cache=True)
                error_code = ex.__class__.__name__.replace('_', '-')
                self.stat.inc('integrity:%s' % error_code)
            else:
                result = func(self, grab, task)
                if result is not None:
                    for event in result:
                        yield event
        func_wrapper._original_func = func
        return func_wrapper
    return build_decorator

def camel_case_to_underscore(name):
    """Converts camel_case into CamelCase"""
    res = RE_TOKEN1.sub('\\1_\\2', name)
    res = RE_TOKEN2.sub('\\1_\\2', res)
    return res.lower()

def deprecated(use_instead=None):
    """This is a decorator which can be used to mark functions
    as deprecated. It will result in a warning being emitted
    when the function is used."""
    def wrapped(func):
        @wraps(func)
        def new_func(*args, **kwargs):
            message = 'Call to deprecated function %s.' % func.__name__
            if use_instead:
                message += ' Use %s instead.' % use_instead
            if not DISABLE_WARNINGS:
                warn(message, stacklevel=3)
            return func(*args, **kwargs)
        return new_func
    return wrapped

def read_bom(data):
    """Read the byte order mark in the text, if present, and
    return the encoding represented by the BOM and the BOM.

    If no BOM can be detected, (None, None) is returned."""
    if data and data[0] in _FIRST_CHARS:
        for bom, encoding in _BOM_TABLE:
            if data.startswith(bom):
                return (encoding, bom)
    return (None, None)

def to_matrix(np_array):
    """Convert numpy array to MLlib Matrix
    """
    if len(np_array.shape) == 2:
        return Matrices.dense(np_array.shape[0], np_array.shape[1], np_array.ravel())
    else:
        raise Exception('An MLLib Matrix can only be created from a two-dimensional ' + 'numpy array, got {}'.format(len(np_array.shape)))

def get_nd4j_dtype(np_dtype):
    """Gets the equivalent nd4j data type
    for a given numpy data type.
    # Arguments
        np_dtype: Numpy data type. One of
            ['float64', 'float32', 'float16']"""
    if type(np_dtype) == type:
        np_dtype = np_dtype.__name__
    elif type(np_dtype) == np.dtype:
        np_dtype = np_dtype.name
    mapping = {'float64': 'double', 'float32': 'float', 'float16': 'half'}
    nd4j_dtype = mapping.get(np_dtype)
    if not nd4j_dtype:
        raise Exception('Invalid numpy data type : ' + np_dtype)
    return nd4j_dtype

def from_data_frame(df, categorical=False, nb_classes=None):
    """Convert DataFrame back to pair of numpy arrays
    """
    lp_rdd = df.rdd.map(lambda row: LabeledPoint(row.label, row.features))
    features, labels = from_labeled_point(lp_rdd, categorical, nb_classes)
    return (features, labels)

def determine_master(port=4000):
    """Determine address of master so that workers
    can connect to it. If the environment variable
    SPARK_LOCAL_IP is set, that address will be used.

    :param port: port on which the application runs
    :return: Master address

    Example usage:
        SPARK_LOCAL_IP=127.0.0.1 spark-submit --master             local[8] examples/mllib_mlp.py"""
    if os.environ.get('SPARK_LOCAL_IP'):
        return os.environ['SPARK_LOCAL_IP'] + ':' + str(port)
    else:
        return gethostbyname(gethostname()) + ':' + str(port)

def to_labeled_point(sc, features, labels, categorical=False):
    """Convert numpy arrays of features and labels into
    a LabeledPoint RDD for MLlib and ML integration.

    :param sc: Spark context
    :param features: numpy array with features
    :param labels: numpy array with labels
    :param categorical: boolean, whether labels are already one-hot encoded or not
    :return: LabeledPoint RDD with features and labels"""
    labeled_points = []
    for x, y in zip(features, labels):
        if categorical:
            lp = LabeledPoint(np.argmax(y), to_vector(x))
        else:
            lp = LabeledPoint(y, to_vector(x))
        labeled_points.append(lp)
    return sc.parallelize(labeled_points)

def from_labeled_point(rdd, categorical=False, nb_classes=None):
    """Convert a LabeledPoint RDD back to a pair of numpy arrays

    :param rdd: LabeledPoint RDD
    :param categorical: boolean, if labels should be one-hot encode when returned
    :param nb_classes: optional int, indicating the number of class labels
    :return: pair of numpy arrays, features and labels"""
    features = np.asarray(rdd.map(lambda lp: from_vector(lp.features)).collect())
    labels = np.asarray(rdd.map(lambda lp: lp.label).collect(), dtype='int32')
    if categorical:
        if not nb_classes:
            nb_classes = np.max(labels) + 1
        temp = np.zeros((len(labels), nb_classes))
        for i, label in enumerate(labels):
            temp[i, label] = 1.0
        labels = temp
    return (features, labels)

def detect_config_path():
    """Get nginx configuration file path based on `nginx -V` output
    :return: detected nginx configuration file path"""
    try:
        proc = subprocess.Popen(['nginx', '-V'], stderr=subprocess.PIPE)
    except OSError:
        error_exit('Access log file or format was not set and nginx config file cannot be detected. ' + 'Perhaps nginx is not in your PATH?')
    stdout, stderr = proc.communicate()
    version_output = stderr.decode('utf-8')
    conf_path_match = re.search('--conf-path=(\\S*)', version_output)
    if conf_path_match is not None:
        return conf_path_match.group(1)
    prefix_match = re.search('--prefix=(\\S*)', version_output)
    if prefix_match is not None:
        return prefix_match.group(1) + '/conf/nginx.conf'
    return '/etc/nginx/nginx.conf'

def get_access_logs(config):
    """Parse config for access_log directives
    :return: iterator over ('path', 'format name') tuple of found directives"""
    access_log = Literal('access_log') + ZeroOrMore(parameter) + semicolon
    access_log.ignore(pythonStyleComment)
    for directive in access_log.searchString(config).asList():
        path = directive[1]
        if path == 'off' or path.startswith('syslog:'):
            continue
        format_name = 'combined'
        if len(directive) > 2 and '=' not in directive[2]:
            format_name = directive[2]
        yield (path, format_name)

def detect_log_config(arguments):
    """Detect access log config (path and format) of nginx. Offer user to select if multiple access logs are detected.
    :return: path and format of detected / selected access log"""
    config = arguments['--config']
    if config is None:
        config = detect_config_path()
    if not os.path.exists(config):
        error_exit('Nginx config file not found: %s' % config)
    with open(config) as f:
        config_str = f.read()
    access_logs = dict(get_access_logs(config_str))
    if not access_logs:
        error_exit('Access log file is not provided and ngxtop cannot detect it from your config file (%s).' % config)
    log_formats = dict(get_log_formats(config_str))
    if len(access_logs) == 1:
        log_path, format_name = list(access_logs.items())[0]
        if format_name == 'combined':
            return (log_path, LOG_FORMAT_COMBINED)
        if format_name not in log_formats:
            error_exit('Incorrect format name set in config for access log file "%s"' % log_path)
        return (log_path, log_formats[format_name])
    print('Multiple access logs detected in configuration:')
    log_path = choose_one(list(access_logs.keys()), 'Select access log file to process: ')
    format_name = access_logs[log_path]
    if format_name not in log_formats:
        error_exit('Incorrect format name set in config for access log file "%s"' % log_path)
    return (log_path, log_formats[format_name])

def build_pattern(log_format):
    """Build regular expression to parse given format.
    :param log_format: format string to parse
    :return: regular expression to parse given format"""
    if log_format == 'combined':
        log_format = LOG_FORMAT_COMBINED
    elif log_format == 'common':
        log_format = LOG_FORMAT_COMMON
    pattern = re.sub(REGEX_SPECIAL_CHARS, '\\\\\\1', log_format)
    pattern = re.sub(REGEX_LOG_FORMAT_VARIABLE, '(?P<\\1>.*)', pattern)
    return re.compile(pattern)

def extract_variables(log_format):
    """Extract all variables from a log format string.
    :param log_format: format string to extract
    :return: iterator over all variables in given format string"""
    if log_format == 'combined':
        log_format = LOG_FORMAT_COMBINED
    for match in re.findall(REGEX_LOG_FORMAT_VARIABLE, log_format):
        yield match

def follow(the_file):
    """Follow a given file and yield new lines when they are available, like `tail -f`."""
    with open(the_file) as f:
        f.seek(0, 2)
        while True:
            line = f.readline()
            if not line:
                time.sleep(0.1)
                continue
            yield line

def map_field(field, func, dict_sequence):
    """Apply given function to value of given key in every dictionary in sequence and
    set the result as new value for that key."""
    for item in dict_sequence:
        try:
            item[field] = func(item.get(field, None))
            yield item
        except ValueError:
            pass

def add_field(field, func, dict_sequence):
    """Apply given function to the record and store result in given field of current record.
    Do nothing if record already contains given field."""
    for item in dict_sequence:
        if field not in item:
            item[field] = func(item)
        yield item

def getCanonicalRep(record_cluster):
    """Given a list of records within a duplicate cluster, constructs a
    canonical representation of the cluster by finding canonical
    values for each field"""
    canonical_rep = {}
    keys = record_cluster[0].keys()
    for key in keys:
        key_values = []
        for record in record_cluster:
            if record[key]:
                key_values.append(record[key])
        if key_values:
            canonical_rep[key] = getCentroid(key_values, comparator)
        else:
            canonical_rep[key] = ''
    return canonical_rep

def latLongGridPredicate(field, digits=1):
    """Given a lat / long pair, return the grid coordinates at the
    nearest base value.  e.g., (42.3, -5.4) returns a grid at 0.1
    degree resolution of 0.1 degrees of latitude ~ 7km, so this is
    effectively a 14km lat grid.  This is imprecise for longitude,
    since 1 degree of longitude is 0km at the poles, and up to 111km
    at the equator. But it should be reasonably precise given some
    prior logical block (e.g., country)."""
    if any(field):
        return (str([round(dim, digits) for dim in field]),)
    else:
        return ()

def randomPairs(n_records, sample_size):
    """Return random combinations of indices for a square matrix of size n
    records. For a discussion of how this works see
    http://stackoverflow.com/a/14839010/98080"""
    n = int(n_records * (n_records - 1) / 2)
    if sample_size >= n:
        random_pairs = numpy.arange(n, dtype='uint')
    else:
        try:
            random_pairs = numpy.array(random.sample(range(n), sample_size), dtype='uint')
        except OverflowError:
            return randomPairsWithReplacement(n_records, sample_size)
    b = 1 - 2 * n_records
    root = (-b - 2 * numpy.sqrt(2 * (n - random_pairs) + 0.25)) / 2
    i = numpy.floor(root).astype('uint')
    j = numpy.rint(random_pairs + i * (b + i + 2) / 2 + 1).astype('uint')
    return zip(i, j)

def randomPairsMatch(n_records_A, n_records_B, sample_size):
    """Return random combinations of indices for record list A and B"""
    n = int(n_records_A * n_records_B)
    if sample_size >= n:
        random_pairs = numpy.arange(n)
    else:
        random_pairs = numpy.array(random.sample(range(n), sample_size), dtype=int)
    i, j = numpy.unravel_index(random_pairs, (n_records_A, n_records_B))
    return zip(i, j)

def cluster(dupes, threshold=0.5, max_components=30000):
    """Takes in a list of duplicate pairs and clusters them in to a
    list records that all refer to the same entity based on a given
    threshold

    Keyword arguments:
    threshold -- number betweent 0 and 1 (default is .5). lowering the
                 number will increase precision, raising it will increase
                 recall"""
    distance_threshold = 1 - threshold
    dupe_sub_graphs = connected_components(dupes, max_components)
    for sub_graph in dupe_sub_graphs:
        if len(sub_graph) > 1:
            i_to_id, condensed_distances, N = condensedDistance(sub_graph)
            linkage = fastcluster.linkage(condensed_distances, method='centroid', preserve_input=True)
            partition = hcluster.fcluster(linkage, distance_threshold, criterion='distance')
            clusters = defaultdict(list)
            for i, cluster_id in enumerate(partition):
                clusters[cluster_id].append(i)
            for cluster in viewvalues(clusters):
                if len(cluster) > 1:
                    scores = confidences(cluster, condensed_distances, N)
                    yield (tuple((i_to_id[i] for i in cluster)), scores)
        else:
            (ids, score), = sub_graph
            if score > threshold:
                yield (tuple(ids), (score,) * 2)

def get_swagger_view(title=None, url=None, patterns=None, urlconf=None):
    """Returns schema view which renders Swagger/OpenAPI."""
    class SwaggerSchemaView(APIView):
        _ignore_model_permissions = True
        exclude_from_schema = True
        permission_classes = [AllowAny]
        renderer_classes = [CoreJSONRenderer, renderers.OpenAPIRenderer, renderers.SwaggerUIRenderer]
        def get(self, request):
            generator = SchemaGenerator(title=title, url=url, patterns=patterns, urlconf=urlconf)
            schema = generator.get_schema(request=request)
            if not schema:
                raise exceptions.ValidationError('The schema generator did not return a schema Document')
            return Response(schema)
    return SwaggerSchemaView.as_view()

