def _get_cached_mounted_points():
    """! Get the volumes present on the system
    @return List of mount points and their associated target id
      Ex. [{ 'mount_point': 'D:', 'target_id_usb_id': 'xxxx'}, ...]"""
    result = []
    try:
        mounted_devices_key = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, 'SYSTEM\\MountedDevices')
        for v in _iter_vals(mounted_devices_key):
            if 'DosDevices' not in v[0]:
                continue
            volume_string = v[1].decode('utf-16le', 'ignore')
            if not _is_mbed_volume(volume_string):
                continue
            mount_point_match = re.match('.*\\\\(.:)$', v[0])
            if not mount_point_match:
                logger.debug('Invalid disk pattern for entry %s, skipping', v[0])
                continue
            mount_point = mount_point_match.group(1)
            result.append({'mount_point': mount_point, 'volume_string': volume_string})
    except OSError:
        logger.error('Failed to open "MountedDevices" in registry')
    return result

def _vid_pid_path_to_usb_info(vid_pid_path):
    """! Provide the vendor ID and product ID of a device based on its entry in the registry
    @return Returns {'vendor_id': '<vendor ID>', 'product': '<product ID>'}
    @details If the vendor ID or product ID can't be determined, they will be returned
    as None."""
    result = {'vendor_id': None, 'product_id': None}
    for component in vid_pid_path.split('&'):
        component_part = component.lower().split('_')
        if len(component_part) != 2:
            logger.debug('Unexpected VID/PID string structure %s', component)
            break
        if component_part[0] == 'vid':
            result['vendor_id'] = component_part[1]
        elif component_part[0] == 'pid':
            result['product_id'] = component_part[1]
    return result

def _iter_keys_as_str(key):
    """! Iterate over subkeys of a key returning subkey as string
    """
    for i in range(winreg.QueryInfoKey(key)[0]):
        yield winreg.EnumKey(key, i)

def _iter_keys(key):
    """! Iterate over subkeys of a key
    """
    for i in range(winreg.QueryInfoKey(key)[0]):
        yield winreg.OpenKey(key, winreg.EnumKey(key, i))

def _iter_vals(key):
    """! Iterate over values of a key
    """
    for i in range(winreg.QueryInfoKey(key)[1]):
        yield winreg.EnumValue(key, i)

def _prune(current, keys):
    """Reduce the amount of data we have to sift through to only
    include the specified keys, and children that contain the
    specified keys"""
    pruned_current = {k: current[k] for k in keys if k in current}
    pruned_children = list(filter(None, [_prune(c, keys) for c in current.get('IORegistryEntryChildren', [])]))
    keep_current = any((k in current for k in keys)) or pruned_children
    if keep_current:
        if pruned_children:
            pruned_current['IORegistryEntryChildren'] = pruned_children
        return pruned_current
    else:
        return {}

def _dfs_usb_info(obj, parents):
    """Find all of the usb info that we can from this particular IORegistry
    tree with depth first search (and searching the parent stack....)"""
    output = {}
    if 'BSD Name' in obj and obj['BSD Name'].startswith('disk') and mbed_volume_name_match.search(obj['IORegistryEntryName']):
        disk_id = obj['BSD Name']
        usb_info = {'serial': None}
        for parent in [obj] + parents:
            if 'USB Serial Number' in parent:
                usb_info['serial'] = parent['USB Serial Number']
                break
        output[disk_id] = usb_info
    for child in obj.get('IORegistryEntryChildren', []):
        output.update(_dfs_usb_info(child, [obj] + parents))
    return output

def convert_reset_type(value):
    """! @brief Convert a reset_type session option value to the Target.ResetType enum.
    @param value The value of the reset_type session option.
    @exception ValueError Raised if an unknown reset_type value is passed."""
    value = value.lower()
    if value not in RESET_TYPE_MAP:
        raise ValueError("unexpected value for reset_type option ('%s')" % value)
    return RESET_TYPE_MAP[value]

def convert_frequency(value):
    """! @brief Applies scale suffix to frequency value string."""
    value = value.strip()
    suffix = value[-1].lower()
    if suffix in ('k', 'm'):
        value = int(value[:-1])
        if suffix == 'k':
            value *= 1000
        elif suffix == 'm':
            value *= 1000000
        return value
    else:
        return int(value)

def _get_bool_attribute(elem, name, default=False):
    """! @brief Extract an XML attribute with a boolean value.

    Supports "true"/"false" or "1"/"0" as the attribute values. Leading and trailing whitespace
    is stripped, and the comparison is case-insensitive.

    @param elem ElementTree.Element object.
    @param name String for the attribute name.
    @param default An optional default value if the attribute is missing. If not provided,
        the default is False."""
    if name not in elem.attrib:
        return default
    else:
        value = elem.attrib[name].strip().lower()
        if value in ('true', '1'):
            return True
        elif value in ('false', '0'):
            return False
        else:
            return default

def bitmask(*args):
    """! @brief Returns a mask with specified bit ranges set.

    An integer mask is generated based on the bits and bit ranges specified by the
    arguments. Any number of arguments can be provided. Each argument may be either
    a 2-tuple of integers, a list of integers, or an individual integer. The result
    is the combination of masks produced by the arguments.

    - 2-tuple: The tuple is a bit range with the first element being the MSB and the
          second element the LSB. All bits from LSB up to and included MSB are set.
    - list: Each bit position specified by the list elements is set.
    - int: The specified bit position is set.

    @return An integer mask value computed from the logical OR'ing of masks generated
      by each argument.

    Example:
    @code
      >>> hex(bitmask((23,17),1))
      0xfe0002
      >>> hex(bitmask([4,0,2],(31,24))
      0xff000015
    @endcode"""
    mask = 0
    for a in args:
        if type(a) is tuple:
            for b in range(a[1], a[0] + 1):
                mask |= 1 << b
        elif type(a) is list:
            for b in a:
                mask |= 1 << b
        elif type(a) is int:
            mask |= 1 << a
    return mask

def same(d1, d2):
    """! @brief Test whether two sequences contain the same values.

    Unlike a simple equality comparison, this function works as expected when the two sequences
    are of different types, such as a list and bytearray. The sequences must return
    compatible types from indexing."""
    if len(d1) != len(d2):
        return False
    for i in range(len(d1)):
        if d1[i] != d2[i]:
            return False
    return True

def _match_cmsis_dap_interface(interface):
    """! @brief Returns true for a CMSIS-DAP v2 interface.

    This match function performs several tests on the provided USB interface descriptor, to
    determine whether it is a CMSIS-DAPv2 interface. These requirements must be met by the
    interface:

    1. Have an interface name string containing "CMSIS-DAP".
    2. bInterfaceClass must be 0xff.
    3. bInterfaceSubClass must be 0.
    4. Must have bulk out and bulk in endpoints, with an optional extra bulk in endpoint, in
        that order."""
    try:
        interface_name = usb.util.get_string(interface.device, interface.iInterface)
        if interface_name is None or 'CMSIS-DAP' not in interface_name:
            return False
        if interface.bInterfaceClass != USB_CLASS_VENDOR_SPECIFIC or interface.bInterfaceSubClass != 0:
            return False
        if interface.bNumEndpoints not in (2, 3):
            return False
        if not _check_ep(interface, 0, usb.util.ENDPOINT_OUT, usb.util.ENDPOINT_TYPE_BULK):
            return False
        if not _check_ep(interface, 1, usb.util.ENDPOINT_IN, usb.util.ENDPOINT_TYPE_BULK):
            return False
        if interface.bNumEndpoints == 3 and (not _check_ep(interface, 2, usb.util.ENDPOINT_IN, usb.util.ENDPOINT_TYPE_BULK)):
            return False
        return True
    except (UnicodeDecodeError, IndexError):
        return False

