def log_call(call_name):
    """Log the API call to the logger."""
    def decorator(f):
        @wraps(f)
        def wrapper(*args, **kw):
            instance = args[0]
            instance.logger.info(call_name, {'content': request.get_json()})
            return f(*args, **kw)
        return wrapper
    return decorator

def error_catch(f):
    """Handle unexpected errors within the rest function."""
    @wraps(f)
    def wrapper(*args, **kw):
        instance = args[0]
        try:
            result = f(*args, **kw)
            if isinstance(result, tuple):
                return (jsonify(result[0]), result[1])
            else:
                return (jsonify(result), 200)
        except Exception as e:
            ret_dict = instance._create_ret_object(instance.FAILURE, None, True, instance.UNKNOWN_ERROR)
            log_dict = deepcopy(ret_dict)
            log_dict['error']['cause'] = e.message
            log_dict['error']['exception'] = str(e)
            log_dict['error']['ex'] = traceback.format_exc()
            instance.logger.error('Uncaught Exception Thrown', log_dict)
            return (jsonify(ret_dict), 500)
    return wrapper

def validate_json(f):
    """Validate that the call is JSON."""
    @wraps(f)
    def wrapper(*args, **kw):
        instance = args[0]
        try:
            if request.get_json() is None:
                ret_dict = instance._create_ret_object(instance.FAILURE, None, True, instance.MUST_JSON)
                instance.logger.error(instance.MUST_JSON)
                return (jsonify(ret_dict), 400)
        except BadRequest:
            ret_dict = instance._create_ret_object(instance.FAILURE, None, True, instance.MUST_JSON)
            instance.logger.error(instance.MUST_JSON)
            return (jsonify(ret_dict), 400)
        instance.logger.debug('JSON is valid')
        return f(*args, **kw)
    return wrapper

def revoke_token(token_id, user):
    """Revokes the given token. Raises a TokenNotFound error if the token does
    not exist in the database"""
    try:
        token = TokenBlacklist.query.filter_by(id=token_id, user_identity=user).one()
        token.revoked = True
        db.session.commit()
    except NoResultFound:
        raise TokenNotFound('Could not find the token {}'.format(token_id))

def verify_fresh_jwt_in_request():
    """Ensure that the requester has a valid and fresh access token. Raises an
    appropiate exception if there is no token, the token is invalid, or the
    token is not marked as fresh."""
    if request.method not in config.exempt_methods:
        jwt_data = _decode_jwt_from_request(request_type='access')
        ctx_stack.top.jwt = jwt_data
        fresh = jwt_data['fresh']
        if isinstance(fresh, bool):
            if not fresh:
                raise FreshTokenRequired('Fresh token required')
        else:
            now = timegm(datetime.utcnow().utctimetuple())
            if fresh < now:
                raise FreshTokenRequired('Fresh token required')
        verify_token_claims(jwt_data)
        _load_user(jwt_data[config.identity_claim_key])

def jwt_required(fn):
    """A decorator to protect a Flask endpoint.

    If you decorate an endpoint with this, it will ensure that the requester
    has a valid access token before allowing the endpoint to be called. This
    does not check the freshness of the access token.

    See also: :func:`~flask_jwt_extended.fresh_jwt_required`"""
    @wraps(fn)
    def wrapper(*args, **kwargs):
        verify_jwt_in_request()
        return fn(*args, **kwargs)
    return wrapper

def fresh_jwt_required(fn):
    """A decorator to protect a Flask endpoint.

    If you decorate an endpoint with this, it will ensure that the requester
    has a valid and fresh access token before allowing the endpoint to be
    called.

    See also: :func:`~flask_jwt_extended.jwt_required`"""
    @wraps(fn)
    def wrapper(*args, **kwargs):
        verify_fresh_jwt_in_request()
        return fn(*args, **kwargs)
    return wrapper

def jwt_refresh_token_required(fn):
    """A decorator to protect a Flask endpoint.

    If you decorate an endpoint with this, it will ensure that the requester
    has a valid refresh token before allowing the endpoint to be called."""
    @wraps(fn)
    def wrapper(*args, **kwargs):
        verify_jwt_refresh_token_in_request()
        return fn(*args, **kwargs)
    return wrapper

