def filter_properties_target(namespaces_iter, resource_types, properties_target):
    """Filter metadata namespaces.

    Filtering is done based ongiven resource types and a properties target.

    :param namespaces_iter: Metadata namespaces iterable.
    :param resource_types: List of resource type names.
    :param properties_target: Name of the properties target."""
    def filter_namespace(namespace):
        for asn in namespace.get('resource_type_associations'):
            if asn.get('name') in resource_types and asn.get('properties_target') == properties_target:
                return True
        return False
    return filter(filter_namespace, namespaces_iter)

def discover_files(base_path, sub_path='', ext='', trim_base_path=False):
    """Discovers all files with certain extension in given paths."""
    file_list = []
    for root, dirs, files in walk(path.join(base_path, sub_path)):
        if trim_base_path:
            root = path.relpath(root, base_path)
        file_list.extend([path.join(root, file_name) for file_name in files if file_name.endswith(ext)])
    return sorted(file_list)

def normalize_params(params):
    """Take a list of dictionaries, and tokenize/normalize."""
    fields = set()
    for p in params:
        fields.update(p)
    fields = sorted(fields)
    params2 = list(pluck(fields, params, MISSING))
    tokens = [tuple((x if isinstance(x, (int, float, str)) else id(x) for x in p)) for p in params2]
    return (fields, tokens, params2)

def check_cv(cv=3, y=None, classifier=False):
    """Dask aware version of ``sklearn.model_selection.check_cv``

    Same as the scikit-learn version, but works if ``y`` is a dask object."""
    if cv is None:
        cv = 3
    if not is_dask_collection(y) or not isinstance(cv, numbers.Integral):
        return model_selection.check_cv(cv, y, classifier)
    if classifier:
        target_type = delayed(type_of_target, pure=True)(y).compute()
        if target_type in ('binary', 'multiclass'):
            return StratifiedKFold(cv)
    return KFold(cv)

def compute_n_splits(cv, X, y=None, groups=None):
    """Return the number of splits.

    Parameters
    ----------
    cv : BaseCrossValidator
    X, y, groups : array_like, dask object, or None

    Returns
    -------
    n_splits : int"""
    if not any((is_dask_collection(i) for i in (X, y, groups))):
        return cv.get_n_splits(X, y, groups)
    if isinstance(cv, (_BaseKFold, BaseShuffleSplit)):
        return cv.n_splits
    elif isinstance(cv, PredefinedSplit):
        return len(cv.unique_folds)
    elif isinstance(cv, _CVIterableWrapper):
        return len(cv.cv)
    elif isinstance(cv, (LeaveOneOut, LeavePOut)) and (not is_dask_collection(X)):
        return cv.get_n_splits(X, None, None)
    elif isinstance(cv, (LeaveOneGroupOut, LeavePGroupsOut)) and (not is_dask_collection(groups)):
        return cv.get_n_splits(None, None, groups)
    else:
        return delayed(cv).get_n_splits(X, y, groups).compute()

def _create_model(model, ident, **params):
    """Create a model by cloning and then setting params"""
    with log_errors(pdb=True):
        model = clone(model).set_params(**params)
        return (model, {'model_id': ident, 'params': params, 'partial_fit_calls': 0})

def _first_block(dask_object):
    """Extract the first block / partition from a dask object
    """
    if isinstance(dask_object, da.Array):
        if dask_object.ndim > 1 and dask_object.numblocks[-1] != 1:
            raise NotImplementedError('IID estimators require that the array blocked only along the first axis. Rechunk your array before fitting.')
        shape = (dask_object.chunks[0][0],)
        if dask_object.ndim > 1:
            shape = shape + (dask_object.chunks[1][0],)
        return da.from_delayed(dask_object.to_delayed().flatten()[0], shape, dask_object.dtype)
    if isinstance(dask_object, dd._Frame):
        return dask_object.get_partition(0)
    else:
        return dask_object

def k_means(X, n_clusters, init='k-means||', precompute_distances='auto', n_init=1, max_iter=300, verbose=False, tol=0.0001, random_state=None, copy_x=True, n_jobs=-1, algorithm='full', return_n_iter=False, oversampling_factor=2, init_max_iter=None):
    """K-means algorithm for clustering

    Differences from scikit-learn:

    * init='k-means||'
    * oversampling_factor keyword
    * n_jobs=-1"""
    labels, inertia, centers, n_iter = _kmeans_single_lloyd(X, n_clusters, max_iter=max_iter, init=init, verbose=verbose, tol=tol, random_state=random_state, oversampling_factor=oversampling_factor, init_max_iter=init_max_iter)
    if return_n_iter:
        return (labels, centers, inertia, n_iter)
    else:
        return (labels, centers, inertia)

def predict(model, x):
    """Predict with a scikit learn model

    Parameters
    ----------
    model : scikit learn classifier
    x : dask Array

    See docstring for ``da.learn.fit``"""
    if not hasattr(x, 'chunks') and hasattr(x, 'to_dask_array'):
        x = x.to_dask_array()
    assert x.ndim == 2
    if len(x.chunks[1]) > 1:
        x = x.rechunk(chunks=(x.chunks[0], sum(x.chunks[1])))
    func = partial(_predict, model)
    xx = np.zeros((1, x.shape[1]), dtype=x.dtype)
    dt = model.predict(xx).dtype
    return x.map_blocks(func, chunks=(x.chunks[0], (1,)), dtype=dt).squeeze()

def check_matching_blocks(*arrays):
    """Check that the partitioning structure for many arrays matches.

    Parameters
    ----------
    *arrays : Sequence of array-likes
        This includes

        * Dask Array
        * Dask DataFrame
        * Dask Series"""
    if len(arrays) <= 1:
        return
    if all((isinstance(x, da.Array) for x in arrays)):
        chunks = arrays[0].chunks
        for array in arrays[1:]:
            if array.chunks != chunks:
                raise ValueError('Mismatched chunks. {} != {}'.format(chunks, array.chunks))
    elif all((isinstance(x, (dd.Series, dd.DataFrame)) for x in arrays)):
        divisions = arrays[0].divisions
        for array in arrays[1:]:
            if array.divisions != divisions:
                raise ValueError('Mismatched divisions. {} != {}'.format(divisions, array.divisions))
    else:
        raise ValueError('Unexpected types {}.'.format({type(x) for x in arrays}))

def get_scorer(scoring, compute=True):
    """Get a scorer from string

    Parameters
    ----------
    scoring : str | callable
        scoring method as string. If callable it is returned as is.

    Returns
    -------
    scorer : callable
        The scorer."""
    if isinstance(scoring, six.string_types):
        try:
            scorer, kwargs = SCORERS[scoring]
        except KeyError:
            raise ValueError('{} is not a valid scoring value. Valid options are {}'.format(scoring, sorted(SCORERS)))
    else:
        scorer = scoring
        kwargs = {}
    kwargs['compute'] = compute
    return make_scorer(scorer, **kwargs)

def to_indexable(*args, **kwargs):
    """Ensure that all args are an indexable type.

    Conversion runs lazily for dask objects, immediately otherwise.

    Parameters
    ----------
    args : array_like or scalar
    allow_scalars : bool, optional
        Whether to allow scalars in args. Default is False."""
    if kwargs.get('allow_scalars', False):
        indexable = _maybe_indexable
    else:
        indexable = _indexable
    for x in args:
        if x is None or isinstance(x, (da.Array, dd.DataFrame)):
            yield x
        elif is_dask_collection(x):
            yield delayed(indexable, pure=True)(x)
        else:
            yield indexable(x)

def _index_param_value(num_samples, v, indices):
    """Private helper function for parameter value indexing.

    This determines whether a fit parameter `v` to a SearchCV.fit
    should be indexed along with `X` and `y`. Note that this differs
    from the scikit-learn version. They pass `X` and compute num_samples.
    We pass `num_samples` instead."""
    if not _is_arraylike(v) or _num_samples(v) != num_samples:
        return v
    if sp.issparse(v):
        v = v.tocsr()
    return safe_indexing(v, indices)

def pipeline(names, steps):
    """Reconstruct a Pipeline from names and steps"""
    steps, times = zip(*map(_maybe_timed, steps))
    fit_time = sum(times)
    if any((s is FIT_FAILURE for s in steps)):
        fit_est = FIT_FAILURE
    else:
        fit_est = Pipeline(list(zip(names, steps)))
    return (fit_est, fit_time)

def feature_union(names, steps, weights):
    """Reconstruct a FeatureUnion from names, steps, and weights"""
    steps, times = zip(*map(_maybe_timed, steps))
    fit_time = sum(times)
    if any((s is FIT_FAILURE for s in steps)):
        fit_est = FIT_FAILURE
    else:
        fit_est = FeatureUnion(list(zip(names, steps)), transformer_weights=weights)
    return (fit_est, fit_time)

def feature_union_concat(Xs, nsamples, weights):
    """Apply weights and concatenate outputs from a FeatureUnion"""
    if any((x is FIT_FAILURE for x in Xs)):
        return FIT_FAILURE
    Xs = [X if w is None else X * w for X, w in zip(Xs, weights) if X is not None]
    if not Xs:
        return np.zeros((nsamples, 0))
    if any((sparse.issparse(f) for f in Xs)):
        return sparse.hstack(Xs).tocsr()
    return np.hstack(Xs)

def _store(results, key_name, array, n_splits, n_candidates, weights=None, splits=False, rank=False):
    """A small helper to store the scores/times to the cv_results_"""
    array = np.array(array, dtype=np.float64).reshape(n_splits, n_candidates).T
    if splits:
        for split_i in range(n_splits):
            results['split%d_%s' % (split_i, key_name)] = array[:, split_i]
    array_means = np.average(array, axis=1, weights=weights)
    results['mean_%s' % key_name] = array_means
    array_stds = np.sqrt(np.average((array - array_means[:, np.newaxis]) ** 2, axis=1, weights=weights))
    results['std_%s' % key_name] = array_stds
    if rank:
        results['rank_%s' % key_name] = np.asarray(rankdata(-array_means, method='min'), dtype=np.int32)

def find_local_peaks(sig, radius):
    """Find all local peaks in a signal. A sample is a local peak if it is
    the largest value within the <radius> samples on its left and right.

    In cases where it shares the max value with nearby samples, the
    middle sample is classified as the local peak.

    Parameters
    ----------
    sig : numpy array
        1d numpy array of the signal.
    radius : int
        The radius in which to search for defining local maxima."""
    if np.min(sig) == np.max(sig):
        return np.empty(0)
    peak_inds = []
    i = 0
    while i < radius + 1:
        if sig[i] == max(sig[:i + radius]):
            peak_inds.append(i)
            i += radius
        else:
            i += 1
    while i < len(sig):
        if sig[i] == max(sig[i - radius:i + radius]):
            peak_inds.append(i)
            i += radius
        else:
            i += 1
    while i < len(sig):
        if sig[i] == max(sig[i - radius:]):
            peak_inds.append(i)
            i += radius
        else:
            i += 1
    return np.array(peak_inds)

def get_plot_dims(signal, ann_samp):
    """Figure out the number of plot channels"""
    if signal is not None:
        if signal.ndim == 1:
            sig_len = len(signal)
            n_sig = 1
        else:
            sig_len = signal.shape[0]
            n_sig = signal.shape[1]
    else:
        sig_len = 0
        n_sig = 0
    if ann_samp is not None:
        n_annot = len(ann_samp)
    else:
        n_annot = 0
    return (sig_len, n_sig, n_annot, max(n_sig, n_annot))

def create_figure(n_subplots, figsize):
    """Create the plot figure and subplot axes"""
    fig = plt.figure(figsize=figsize)
    axes = []
    for i in range(n_subplots):
        axes.append(fig.add_subplot(n_subplots, 1, i + 1))
    return (fig, axes)

def plot_signal(signal, sig_len, n_sig, fs, time_units, sig_style, axes):
    """Plot signal channels"""
    if len(sig_style) == 1:
        sig_style = n_sig * sig_style
    if time_units == 'samples':
        t = np.linspace(0, sig_len - 1, sig_len)
    else:
        downsample_factor = {'seconds': fs, 'minutes': fs * 60, 'hours': fs * 3600}
        t = np.linspace(0, sig_len - 1, sig_len) / downsample_factor[time_units]
    if signal.ndim == 1:
        axes[0].plot(t, signal, sig_style[0], zorder=3)
    else:
        for ch in range(n_sig):
            axes[ch].plot(t, signal[:, ch], sig_style[ch], zorder=3)

def plot_annotation(ann_samp, n_annot, ann_sym, signal, n_sig, fs, time_units, ann_style, axes):
    """Plot annotations, possibly overlaid on signals"""
    if len(ann_style) == 1:
        ann_style = n_annot * ann_style
    if time_units == 'samples':
        downsample_factor = 1
    else:
        downsample_factor = {'seconds': float(fs), 'minutes': float(fs) * 60, 'hours': float(fs) * 3600}[time_units]
    for ch in range(n_annot):
        if ann_samp[ch] is not None and len(ann_samp[ch]):
            if n_sig > ch:
                if signal.ndim == 1:
                    y = signal[ann_samp[ch]]
                else:
                    y = signal[ann_samp[ch], ch]
            else:
                y = np.zeros(len(ann_samp[ch]))
            axes[ch].plot(ann_samp[ch] / downsample_factor, y, ann_style[ch])
            if ann_sym is not None and ann_sym[ch] is not None:
                for i, s in enumerate(ann_sym[ch]):
                    axes[ch].annotate(s, (ann_samp[ch][i] / downsample_factor, y[i]))

def plot_ecg_grids(ecg_grids, fs, units, time_units, axes):
    """Add ecg grids to the axes"""
    if ecg_grids == 'all':
        ecg_grids = range(0, len(axes))
    for ch in ecg_grids:
        auto_xlims = axes[ch].get_xlim()
        auto_ylims = axes[ch].get_ylim()
        major_ticks_x, minor_ticks_x, major_ticks_y, minor_ticks_y = calc_ecg_grids(auto_ylims[0], auto_ylims[1], units[ch], fs, auto_xlims[1], time_units)
        min_x, max_x = (np.min(minor_ticks_x), np.max(minor_ticks_x))
        min_y, max_y = (np.min(minor_ticks_y), np.max(minor_ticks_y))
        for tick in minor_ticks_x:
            axes[ch].plot([tick, tick], [min_y, max_y], c='#ededed', marker='|', zorder=1)
        for tick in major_ticks_x:
            axes[ch].plot([tick, tick], [min_y, max_y], c='#bababa', marker='|', zorder=2)
        for tick in minor_ticks_y:
            axes[ch].plot([min_x, max_x], [tick, tick], c='#ededed', marker='_', zorder=1)
        for tick in major_ticks_y:
            axes[ch].plot([min_x, max_x], [tick, tick], c='#bababa', marker='_', zorder=2)
        axes[ch].set_xlim(auto_xlims)
        axes[ch].set_ylim(auto_ylims)

def calc_ecg_grids(minsig, maxsig, sig_units, fs, maxt, time_units):
    """Calculate tick intervals for ecg grids

    - 5mm 0.2s major grids, 0.04s minor grids
    - 0.5mV major grids, 0.125 minor grids

    10 mm is equal to 1mV in voltage."""
    if time_units == 'samples':
        majorx = 0.2 * fs
        minorx = 0.04 * fs
    elif time_units == 'seconds':
        majorx = 0.2
        minorx = 0.04
    elif time_units == 'minutes':
        majorx = 0.2 / 60
        minorx = 0.04 / 60
    elif time_units == 'hours':
        majorx = 0.2 / 3600
        minorx = 0.04 / 3600
    if sig_units.lower() == 'uv':
        majory = 500
        minory = 125
    elif sig_units.lower() == 'mv':
        majory = 0.5
        minory = 0.125
    elif sig_units.lower() == 'v':
        majory = 0.0005
        minory = 0.000125
    else:
        raise ValueError('Signal units must be uV, mV, or V to plot ECG grids.')
    major_ticks_x = np.arange(0, upround(maxt, majorx) + 0.0001, majorx)
    minor_ticks_x = np.arange(0, upround(maxt, majorx) + 0.0001, minorx)
    major_ticks_y = np.arange(downround(minsig, majory), upround(maxsig, majory) + 0.0001, majory)
    minor_ticks_y = np.arange(downround(minsig, majory), upround(maxsig, majory) + 0.0001, minory)
    return (major_ticks_x, minor_ticks_x, major_ticks_y, minor_ticks_y)

def label_figure(axes, n_subplots, time_units, sig_name, sig_units, ylabel, title):
    """Add title, and axes labels"""
    if title:
        axes[0].set_title(title)
    if not ylabel:
        ylabel = []
        if not sig_name:
            sig_name = ['ch_' + str(i) for i in range(n_subplots)]
        if not sig_units:
            sig_units = n_subplots * ['NU']
        ylabel = ['/'.join(pair) for pair in zip(sig_name, sig_units)]
        n_missing_labels = n_subplots - len(ylabel)
        if n_missing_labels:
            ylabel = ylabel + ['ch_%d/NU' % i for i in range(len(ylabel), n_subplots)]
    for ch in range(n_subplots):
        axes[ch].set_ylabel(ylabel[ch])
    axes[-1].set_xlabel('/'.join(['time', time_units[:-1]]))

def make_local_dirs(dl_dir, dl_inputs, keep_subdirs):
    """Make any required local directories to prepare for downloading"""
    if not os.path.isdir(dl_dir):
        os.makedirs(dl_dir)
        print('Created local base download directory: %s' % dl_dir)
    if keep_subdirs:
        dl_dirs = set([os.path.join(dl_dir, d[1]) for d in dl_inputs])
        for d in dl_dirs:
            if not os.path.isdir(d):
                os.makedirs(d)
    return

def dl_pb_file(inputs):
    """Download a file from physiobank.

    The input args are to be unpacked for the use of multiprocessing
    map, because python2 doesn't have starmap..."""
    basefile, subdir, db, dl_dir, keep_subdirs, overwrite = inputs
    url = posixpath.join(config.db_index_url, db, subdir, basefile)
    remote_file_size = _remote_file_size(url)
    if keep_subdirs:
        dldir = os.path.join(dl_dir, subdir)
    else:
        dldir = dl_dir
    local_file = os.path.join(dldir, basefile)
    if os.path.isfile(local_file):
        if overwrite:
            dl_full_file(url, local_file)
        else:
            local_file_size = os.path.getsize(local_file)
            if local_file_size < remote_file_size:
                print('Detected partially downloaded file: %s Appending file...' % local_file)
                headers = {'Range': 'bytes=' + str(local_file_size) + '-', 'Accept-Encoding': '*'}
                r = requests.get(url, headers=headers, stream=True)
                print('headers: ', headers)
                print('r content length: ', len(r.content))
                with open(local_file, 'ba') as writefile:
                    writefile.write(r.content)
                print('Done appending.')
            elif local_file_size > remote_file_size:
                dl_full_file(url, local_file)
    else:
        dl_full_file(url, local_file)
    return

def update_extra_fields(subtype, chan, num, aux_note, update):
    """Update the field if the current annotation did not
    provide a value.

    - aux_note and sub are set to default values if missing.
    - chan and num copy over previous value if missing."""
    if update['subtype']:
        subtype.append(0)
    if update['chan']:
        if chan == []:
            chan.append(0)
        else:
            chan.append(chan[-1])
    if update['num']:
        if num == []:
            num.append(0)
        else:
            num.append(num[-1])
    if update['aux_note']:
        aux_note.append('')
    return (subtype, chan, num, aux_note)

def interpret_defintion_annotations(potential_definition_inds, aux_note):
    """Try to extract annotation definition information from annotation notes.
    Information that may be contained:
    - fs - sample=0, label_state=22, aux_note='## time resolution: XXX'
    - custom annotation label definitions"""
    fs = None
    custom_labels = []
    if len(potential_definition_inds) > 0:
        i = 0
        while i < len(potential_definition_inds):
            if aux_note[i].startswith('## '):
                if not fs:
                    search_fs = rx_fs.findall(aux_note[i])
                    if search_fs:
                        fs = float(search_fs[0])
                        if round(fs, 8) == float(int(fs)):
                            fs = int(fs)
                        i += 1
                        continue
                if aux_note[i] == '## annotation type definitions':
                    i += 1
                    while aux_note[i] != '## end of definitions':
                        label_store, symbol, description = rx_custom_label.findall(aux_note[i])[0]
                        custom_labels.append((int(label_store), symbol, description))
                        i += 1
                    i += 1
            else:
                i += 1
    if not custom_labels:
        custom_labels = None
    return (fs, custom_labels)

def _skew_sig(sig, skew, n_sig, read_len, fmt, nan_replace, samps_per_frame=None):
    """Skew the signal, insert nans and shave off end of array if needed.

    Parameters
    ----------
    sig : numpy array
        The original signal
    skew : list
        List of samples to skew for each signal
    n_sig : int
        The number of signals


    Notes
    -----
    `fmt` is just for the correct nan value.
    `samps_per_frame` is only used for skewing expanded signals."""
    if max(skew) > 0:
        if isinstance(sig, list):
            for ch in range(n_sig):
                if skew[ch] > 0:
                    sig[ch][:read_len * samps_per_frame[ch]] = sig[ch][skew[ch] * samps_per_frame[ch]:]
            for ch in range(n_sig):
                sig[ch] = sig[ch][:read_len * samps_per_frame[ch]]
            for ch in range(n_sig):
                if nan_replace[ch] > 0:
                    sig[ch][-nan_replace[ch]:] = _digi_nan(fmt)
        else:
            for ch in range(n_sig):
                if skew[ch] > 0:
                    sig[:read_len, ch] = sig[skew[ch]:, ch]
            sig = sig[:read_len, :]
            for ch in range(n_sig):
                if nan_replace[ch] > 0:
                    sig[-nan_replace[ch]:, ch] = _digi_nan(fmt)
    return sig

def _check_sig_dims(sig, read_len, n_sig, samps_per_frame):
    """Integrity check of a signal's shape after reading."""
    if isinstance(sig, np.ndarray):
        if sig.shape != (read_len, n_sig):
            raise ValueError('Samples were not loaded correctly')
    else:
        if len(sig) != n_sig:
            raise ValueError('Samples were not loaded correctly')
        for ch in range(n_sig):
            if len(sig[ch]) != samps_per_frame[ch] * read_len:
                raise ValueError('Samples were not loaded correctly')

def _digi_bounds(fmt):
    """Return min and max digital values for each format type.
    Accepts lists.

    Parmeters
    ---------
    fmt : str, or list
        The wfdb dat format, or a list of them."""
    if isinstance(fmt, list):
        return [_digi_bounds(f) for f in fmt]
    if fmt == '80':
        return (-128, 127)
    elif fmt == '212':
        return (-2048, 2047)
    elif fmt == '16':
        return (-32768, 32767)
    elif fmt == '24':
        return (-8388608, 8388607)
    elif fmt == '32':
        return (-2147483648, 2147483647)

def _digi_nan(fmt):
    """Return the wfdb digital value used to store nan for the format type.

    Parmeters
    ---------
    fmt : str, or list
        The wfdb dat format, or a list of them."""
    if isinstance(fmt, list):
        return [_digi_nan(f) for f in fmt]
    if fmt == '80':
        return -128
    if fmt == '310':
        return -512
    if fmt == '311':
        return -512
    elif fmt == '212':
        return -2048
    elif fmt == '16':
        return -32768
    elif fmt == '61':
        return -32768
    elif fmt == '160':
        return -32768
    elif fmt == '24':
        return -8388608
    elif fmt == '32':
        return -2147483648

def est_res(signals):
    """Estimate the resolution of each signal in a multi-channel signal in
    bits. Maximum of 32 bits.

    Parameters
    ----------
    signals : numpy array, or list
        A 2d numpy array representing a uniform multichannel signal, or
        a list of 1d numpy arrays representing multiple channels of
        signals with different numbers of samples per frame.

    Returns
    -------
    bit_res : list
        A list of estimated integer resolutions for each channel"""
    res_levels = np.power(2, np.arange(0, 33))
    if isinstance(signals, list):
        n_sig = len(signals)
    elif signals.ndim == 1:
        n_sig = 1
    else:
        n_sig = signals.shape[1]
    res = []
    for ch in range(n_sig):
        if isinstance(signals, list):
            sorted_sig = np.sort(np.unique(signals[ch]))
        elif signals.ndim == 1:
            sorted_sig = np.sort(np.unique(signals))
        else:
            sorted_sig = np.sort(np.unique(signals[:, ch]))
        min_inc = min(np.diff(sorted_sig))
        if min_inc == 0:
            res.append(0)
        else:
            nlevels = 1 + (sorted_sig[-1] - sorted_sig[0]) / min_inc
            if nlevels >= res_levels[-1]:
                res.append(32)
            else:
                res.append(np.where(res_levels >= nlevels)[0][0])
    return res

def _np_dtype(bit_res, discrete):
    """Given the bit resolution of a signal, return the minimum numpy dtype
    used to store it.

    Parameters
    ----------
    bit_res : int
        The bit resolution.
    discrete : bool
        Whether the dtype is to be int or float.

    Returns
    -------
    dtype : str
        String numpy dtype used to store the signal of the given
        resolution"""
    bit_res = min(bit_res, 64)
    for np_res in [8, 16, 32, 64]:
        if bit_res <= np_res:
            break
    if discrete is True:
        return 'int' + str(np_res)
    else:
        return 'float' + str(max(np_res, 16))

def wfdb_strptime(time_string):
    """Given a time string in an acceptable wfdb format, return
    a datetime.time object.

    Valid formats: SS, MM:SS, HH:MM:SS, all with and without microsec."""
    n_colons = time_string.count(':')
    if n_colons == 0:
        time_fmt = '%S'
    elif n_colons == 1:
        time_fmt = '%M:%S'
    elif n_colons == 2:
        time_fmt = '%H:%M:%S'
    if '.' in time_string:
        time_fmt += '.%f'
    return datetime.datetime.strptime(time_string, time_fmt).time()

def _read_segment_lines(segment_lines):
    """Extract fields from segment line strings into a dictionary"""
    segment_fields = {}
    for field in SEGMENT_SPECS.index:
        segment_fields[field] = [None] * len(segment_lines)
    for i in range(len(segment_lines)):
        segment_fields['seg_name'][i], segment_fields['seg_len'][i] = _rx_segment.findall(segment_lines[i])[0]
        if field == 'seg_len':
            segment_fields['seg_len'][i] = int(segment_fields['seg_len'][i])
    return segment_fields

def is_monotonic(full_list):
    """Determine whether elements in a list are monotonic. ie. unique
    elements are clustered together.

    ie. [5,5,3,4] is, [5,3,5] is not."""
    prev_elements = set({full_list[0]})
    prev_item = full_list[0]
    for item in full_list:
        if item != prev_item:
            if item in prev_elements:
                return False
            prev_item = item
            prev_elements.add(item)
    return True

def create_mcjit_compiler(module, target_machine):
    """Create a MCJIT ExecutionEngine from the given *module* and
    *target_machine*."""
    with ffi.OutputString() as outerr:
        engine = ffi.lib.LLVMPY_CreateMCJITCompiler(module, target_machine, outerr)
        if not engine:
            raise RuntimeError(str(outerr))
    target_machine._owned = True
    return ExecutionEngine(engine, module=module)

def _label_suffix(label, suffix):
    """Returns (label + suffix) or a truncated version if it's too long.
    Parameters
    ----------
    label : str
        Label name
    suffix : str
        Label suffix"""
    if len(label) > 50:
        nhead = 25
        return ''.join([label[:nhead], '..', suffix])
    else:
        return label + suffix

def sh3(cmd):
    """Execute command in a subshell, return stdout, stderr

    If anything appears in stderr, print it out to sys.stderr"""
    p = Popen(cmd, stdout=PIPE, stderr=PIPE, shell=True, env=sub_environment())
    out, err = p.communicate()
    retcode = p.returncode
    if retcode:
        raise CalledProcessError(retcode, cmd)
    else:
        return (out.rstrip(), err.rstrip())

def get_host_cpu_features():
    """Returns a dictionary-like object indicating the CPU features for current
    architecture and whether they are enabled for this CPU.  The key-value pairs
    are the feature name as string and a boolean indicating whether the feature
    is available.  The returned value is an instance of ``FeatureMap`` class,
    which adds a new method ``.flatten()`` for returning a string suitable for
    use as the "features" argument to ``Target.create_target_machine()``.

    If LLVM has not implemented this feature or it fails to get the information,
    this function will raise a RuntimeError exception."""
    with ffi.OutputString() as out:
        outdict = FeatureMap()
        if not ffi.lib.LLVMPY_GetHostCPUFeatures(out):
            raise RuntimeError('failed to get host cpu features.')
        flag_map = {'+': True, '-': False}
        content = str(out)
        if content:
            for feat in content.split(','):
                if feat:
                    outdict[feat[1:]] = flag_map[feat[0]]
        return outdict

def get_default_triple():
    """Return the default target triple LLVM is configured to produce code for."""
    with ffi.OutputString() as out:
        ffi.lib.LLVMPY_GetDefaultTargetTriple(out)
