def load_library_permanently(filename):
    """Load an external library"""
    with ffi.OutputString() as outerr:
        if ffi.lib.LLVMPY_LoadLibraryPermanently(_encode_string(filename), outerr):
            raise RuntimeError(str(outerr))

def _escape_string(text, _map={}):
    """Escape the given bytestring for safe use as a LLVM array constant."""
    if isinstance(text, str):
        text = text.encode('ascii')
    assert isinstance(text, (bytes, bytearray))
    if not _map:
        for ch in range(256):
            if ch in _VALID_CHARS:
                _map[ch] = chr(ch)
            else:
                _map[ch] = '\\%02x' % ch
            if six.PY2:
                _map[chr(ch)] = _map[ch]
    buf = [_map[ch] for ch in text]
    return ''.join(buf)

def get_function_cfg(func, show_inst=True):
    """Return a string of the control-flow graph of the function in DOT
    format. If the input `func` is not a materialized function, the module
    containing the function is parsed to create an actual LLVM module.
    The `show_inst` flag controls whether the instructions of each block
    are printed."""
    assert func is not None
    if isinstance(func, ir.Function):
        mod = parse_assembly(str(func.module))
        func = mod.get_function(func.name)
    with ffi.OutputString() as dotstr:
        ffi.lib.LLVMPY_WriteCFG(func, dotstr, show_inst)
        return str(dotstr)

def handle_onchain_secretreveal(target_state: TargetTransferState, state_change: ContractReceiveSecretReveal, channel_state: NettingChannelState) -> TransitionResult[TargetTransferState]:
    """Validates and handles a ContractReceiveSecretReveal state change."""
    valid_secret = is_valid_secret_reveal(state_change=state_change, transfer_secrethash=target_state.transfer.lock.secrethash, secret=state_change.secret)
    if valid_secret:
        channel.register_onchain_secret(channel_state=channel_state, secret=state_change.secret, secrethash=state_change.secrethash, secret_reveal_block_number=state_change.block_number)
        target_state.state = TargetTransferState.ONCHAIN_UNLOCK
        target_state.secret = state_change.secret
    return TransitionResult(target_state, list())

def handle_lock_expired(target_state: TargetTransferState, state_change: ReceiveLockExpired, channel_state: NettingChannelState, block_number: BlockNumber) -> TransitionResult[TargetTransferState]:
    """Remove expired locks from channel states."""
    result = channel.handle_receive_lock_expired(channel_state=channel_state, state_change=state_change, block_number=block_number)
    assert result.new_state, 'handle_receive_lock_expired should not delete the task'
    if not channel.get_lock(result.new_state.partner_state, target_state.transfer.lock.secrethash):
        transfer = target_state.transfer
        unlock_failed = EventUnlockClaimFailed(identifier=transfer.payment_identifier, secrethash=transfer.lock.secrethash, reason='Lock expired')
        result.events.append(unlock_failed)
        return TransitionResult(None, result.events)
    return TransitionResult(target_state, result.events)

def wrap(data):
    """Try to decode data into a message, might return None if the data is invalid."""
    try:
        cmdid = data[0]
    except IndexError:
        log.warning('data is empty')
        return None
    try:
        message_type = CMDID_MESSAGE[cmdid]
    except KeyError:
        log.error('unknown cmdid %s', cmdid)
        return None
    try:
        message = message_type(data)
    except ValueError:
        log.error('trying to decode invalid message')
        return None
    return message

def solidity_resolve_address(hex_code, library_symbol, library_address):
    """Change the bytecode to use the given library address.

    Args:
        hex_code (bin): The bytecode encoded in hexadecimal.
        library_name (str): The library that will be resolved.
        library_address (str): The address of the library.

    Returns:
        bin: The bytecode encoded in hexadecimal with the library references
            resolved."""
    if library_address.startswith('0x'):
        raise ValueError('Address should not contain the 0x prefix')
    try:
        decode_hex(library_address)
    except TypeError:
        raise ValueError('library_address contains invalid characters, it must be hex encoded.')
    if len(library_symbol) != 40 or len(library_address) != 40:
        raise ValueError('Address with wrong length')
    return hex_code.replace(library_symbol, library_address)

def solidity_library_symbol(library_name):
    """Return the symbol used in the bytecode to represent the `library_name`."""
    length = min(len(library_name), 36)
    library_piece = library_name[:length]
    hold_piece = '_' * (36 - length)
    return '__{library}{hold}__'.format(library=library_piece, hold=hold_piece)

def check_keystore_json(jsondata: Dict) -> bool:
    """Check if ``jsondata`` has the structure of a keystore file version 3.

    Note that this test is not complete, e.g. it doesn't check key derivation or cipher parameters.
    Copied from https://github.com/vbuterin/pybitcointools

    Args:
        jsondata: Dictionary containing the data from the json file

    Returns:
        `True` if the data appears to be valid, otherwise `False`"""
    if 'crypto' not in jsondata and 'Crypto' not in jsondata:
        return False
    if 'version' not in jsondata:
        return False
    if jsondata['version'] != 3:
        return False
    crypto = jsondata.get('crypto', jsondata.get('Crypto'))
    if 'cipher' not in crypto:
        return False
    if 'ciphertext' not in crypto:
        return False
    if 'kdf' not in crypto:
        return False
    if 'mac' not in crypto:
        return False
    return True

