    channel_state = None
    if token_network:
        channels = [token_network.channelidentifiers_to_channels[channel_id] for channel_id in token_network.partneraddresses_to_channelidentifiers[partner_address]]
        states = filter_channels_by_status(channels, [CHANNEL_STATE_UNUSABLE])
        if states:
            channel_state = states[-1]
    return channel_state

def get_channelstate_filter(chain_state: ChainState, payment_network_id: PaymentNetworkID, token_address: TokenAddress, filter_fn: Callable) -> List[NettingChannelState]:
    """Return the state of channels that match the condition in `filter_fn`"""
    token_network = get_token_network_by_token_address(chain_state, payment_network_id, token_address)
    result: List[NettingChannelState] = []
    if not token_network:
        return result
    for channel_state in token_network.channelidentifiers_to_channels.values():
        if filter_fn(channel_state):
            result.append(channel_state)
    return result

def get_channelstate_open(chain_state: ChainState, payment_network_id: PaymentNetworkID, token_address: TokenAddress) -> List[NettingChannelState]:
    """Return the state of open channels in a token network."""
    return get_channelstate_filter(chain_state, payment_network_id, token_address, lambda channel_state: channel.get_status(channel_state) == CHANNEL_STATE_OPENED)

def get_channelstate_closing(chain_state: ChainState, payment_network_id: PaymentNetworkID, token_address: TokenAddress) -> List[NettingChannelState]:
    """Return the state of closing channels in a token network."""
    return get_channelstate_filter(chain_state, payment_network_id, token_address, lambda channel_state: channel.get_status(channel_state) == CHANNEL_STATE_CLOSING)

def get_channelstate_closed(chain_state: ChainState, payment_network_id: PaymentNetworkID, token_address: TokenAddress) -> List[NettingChannelState]:
    """Return the state of closed channels in a token network."""
    return get_channelstate_filter(chain_state, payment_network_id, token_address, lambda channel_state: channel.get_status(channel_state) == CHANNEL_STATE_CLOSED)

def get_channelstate_settling(chain_state: ChainState, payment_network_id: PaymentNetworkID, token_address: TokenAddress) -> List[NettingChannelState]:
    """Return the state of settling channels in a token network."""
    return get_channelstate_filter(chain_state, payment_network_id, token_address, lambda channel_state: channel.get_status(channel_state) == CHANNEL_STATE_SETTLING)

def role_from_transfer_task(transfer_task: TransferTask) -> str:
    """Return the role and type for the transfer. Throws an exception on error"""
    if isinstance(transfer_task, InitiatorTask):
        return 'initiator'
    if isinstance(transfer_task, MediatorTask):
        return 'mediator'
    if isinstance(transfer_task, TargetTask):
        return 'target'
    raise ValueError('Argument to role_from_transfer_task is not a TransferTask')

def get_transfer_role(chain_state: ChainState, secrethash: SecretHash) -> Optional[str]:
    """Returns 'initiator', 'mediator' or 'target' to signify the role the node has
    in a transfer. If a transfer task is not found for the secrethash then the
    function returns None"""
    task = chain_state.payment_mapping.secrethashes_to_task.get(secrethash)
    if not task:
        return None
    return role_from_transfer_task(task)

def filter_channels_by_status(channel_states: List[NettingChannelState], exclude_states: Optional[List[str]]=None) -> List[NettingChannelState]:
    """Filter the list of channels by excluding ones
    for which the state exists in `exclude_states`."""
    if exclude_states is None:
        exclude_states = []
    states = []
    for channel_state in channel_states:
        if channel.get_status(channel_state) not in exclude_states:
            states.append(channel_state)
    return states

def connect():
    """Try to connect to the router.

    Returns:
        u (miniupnc.UPnP): the connected upnp-instance
        router (string): the connection information"""
    upnp = miniupnpc.UPnP()
    upnp.discoverdelay = 200
    providers = upnp.discover()
    if providers > 1:
        log.debug('multiple upnp providers found', num_providers=providers)
    elif providers < 1:
        log.error('no upnp providers found')
        return None
    try:
        location = upnp.selectigd()
        log.debug('connected', upnp=upnp)
    except Exception as e:
        log.error('Error when connecting to uPnP provider', exception_info=e)
        return None
    if not valid_mappable_ipv4(upnp.lanaddr):
        log.error('could not query your lanaddr', reported=upnp.lanaddr)
        return None
    try:
        if not valid_mappable_ipv4(upnp.externalipaddress()):
            log.error('could not query your externalipaddress', reported=upnp.externalipaddress())
            return None
        return (upnp, location)
    except Exception:
        log.error('error when connecting with uPnP provider', location=location)
        return None

def parity_discover_next_available_nonce(web3: Web3, address: AddressHex) -> Nonce:
    """Returns the next available nonce for `address`."""
    next_nonce_encoded = web3.manager.request_blocking('parity_nextNonce', [address])
    return Nonce(int(next_nonce_encoded, 16))

def geth_discover_next_available_nonce(web3: Web3, address: AddressHex) -> Nonce:
    """Returns the next available nonce for `address`."""
    pool = web3.txpool.inspect or {}
    address = to_checksum_address(address)
    queued = pool.get('queued', {}).get(address)
    if queued:
        return Nonce(max((int(k) for k in queued.keys())) + 1)
    pending = pool.get('pending', {}).get(address)
    if pending:
        return Nonce(max((int(k) for k in pending.keys())) + 1)
    return web3.eth.getTransactionCount(address, 'latest')

def check_address_has_code(client: 'JSONRPCClient', address: Address, contract_name: str=''):
    """Checks that the given address contains code."""
    result = client.web3.eth.getCode(to_checksum_address(address), 'latest')
    if not result:
        if contract_name:
            formated_contract_name = '[{}]: '.format(contract_name)
        else:
            formated_contract_name = ''
        raise AddressWithoutCode('{}Address {} does not contain code'.format(formated_contract_name, to_checksum_address(address)))

def dependencies_order_of_build(target_contract, dependencies_map):
    """Return an ordered list of contracts that is sufficient to successfully
    deploy the target contract.

    Note:
        This function assumes that the `dependencies_map` is an acyclic graph."""
    if not dependencies_map:
        return [target_contract]
    if target_contract not in dependencies_map:
        raise ValueError('no dependencies defined for {}'.format(target_contract))
    order = [target_contract]
    todo = list(dependencies_map[target_contract])
    while todo:
        target_contract = todo.pop(0)
        target_pos = len(order)
        for dependency in dependencies_map[target_contract]:
            if dependency in order:
                target_pos = order.index(dependency)
            else:
                todo.append(dependency)
        order.insert(target_pos, target_contract)
    order.reverse()
    return order

def check_value_error_for_parity(value_error: ValueError, call_type: ParityCallType) -> bool:
    """For parity failing calls and functions do not return None if the transaction
    will fail but instead throw a ValueError exception.

    This function checks the thrown exception to see if it's the correct one and
    if yes returns True, if not returns False"""
    try:
        error_data = json.loads(str(value_error).replace("'", '"'))
    except json.JSONDecodeError:
        return False
    if call_type == ParityCallType.ESTIMATE_GAS:
        code_checks_out = error_data['code'] == -32016
        message_checks_out = 'The execution failed due to an exception' in error_data['message']
    elif call_type == ParityCallType.CALL:
        code_checks_out = error_data['code'] == -32015
        message_checks_out = 'VM execution error' in error_data['message']
    else:
        raise ValueError('Called check_value_error_for_parity() with illegal call type')
    if code_checks_out and message_checks_out:
        return True
    return False

def patched_web3_eth_estimate_gas(self, transaction, block_identifier=None):
    """Temporary workaround until next web3.py release (5.X.X)

    Current master of web3.py has this implementation already:
    https://github.com/ethereum/web3.py/blob/2a67ea9f0ab40bb80af2b803dce742d6cad5943e/web3/eth.py#L311"""
    if 'from' not in transaction and is_checksum_address(self.defaultAccount):
        transaction = assoc(transaction, 'from', self.defaultAccount)
    if block_identifier is None:
        params = [transaction]
    else:
        params = [transaction, block_identifier]
    try:
        result = self.web3.manager.request_blocking('eth_estimateGas', params)
    except ValueError as e:
        if check_value_error_for_parity(e, ParityCallType.ESTIMATE_GAS):
            result = None
        else:
            raise e
    return result

def estimate_gas_for_function(address, web3, fn_identifier=None, transaction=None, contract_abi=None, fn_abi=None, block_identifier=None, *args, **kwargs):
    """Temporary workaround until next web3.py release (5.X.X)"""
    estimate_transaction = prepare_transaction(address, web3, fn_identifier=fn_identifier, contract_abi=contract_abi, fn_abi=fn_abi, transaction=transaction, fn_args=args, fn_kwargs=kwargs)
    try:
        gas_estimate = web3.eth.estimateGas(estimate_transaction, block_identifier)
    except ValueError as e:
        if check_value_error_for_parity(e, ParityCallType.ESTIMATE_GAS):
            gas_estimate = None
        else:
            raise e
    return gas_estimate

def patched_contractfunction_estimateGas(self, transaction=None, block_identifier=None):
    """Temporary workaround until next web3.py release (5.X.X)"""
    if transaction is None:
        estimate_gas_transaction = {}
    else:
        estimate_gas_transaction = dict(**transaction)
    if 'data' in estimate_gas_transaction:
        raise ValueError('Cannot set data in estimateGas transaction')
    if 'to' in estimate_gas_transaction:
        raise ValueError('Cannot set to in estimateGas transaction')
    if self.address:
        estimate_gas_transaction.setdefault('to', self.address)
    if self.web3.eth.defaultAccount is not empty:
        estimate_gas_transaction.setdefault('from', self.web3.eth.defaultAccount)
    if 'to' not in estimate_gas_transaction:
        if isinstance(self, type):
            raise ValueError('When using `Contract.estimateGas` from a contract factory you must provide a `to` address with the transaction')
        else:
            raise ValueError('Please ensure that this contract instance has an address.')
    return estimate_gas_for_function(self.address, self.web3, self.function_identifier, estimate_gas_transaction, self.contract_abi, self.abi, block_identifier, *self.args, **self.kwargs)

def get_db_version(db_filename: Path) -> int:
    """Return the version value stored in the db"""
    assert os.path.exists(db_filename)
    conn = sqlite3.connect(str(db_filename), detect_types=sqlite3.PARSE_DECLTYPES)
    cursor = conn.cursor()
    try:
        cursor.execute('SELECT value FROM settings WHERE name="version";')
        result = cursor.fetchone()
    except sqlite3.OperationalError:
        raise RuntimeError('Corrupted database. Database does not the settings table.')
    if not result:
        raise RuntimeError('Corrupted database. Settings table does not contain an entry the db version.')
    return int(result[0])

def mint_token_if_balance_low(token_contract: ContractProxy, target_address: str, min_balance: int, fund_amount: int, gas_limit: int, mint_msg: str, no_action_msg: str=None) -> Optional[TransactionHash]:
    """Check token balance and mint if below minimum"""
    balance = token_contract.contract.functions.balanceOf(target_address).call()
    if balance < min_balance:
        mint_amount = fund_amount - balance
        log.debug(mint_msg, address=target_address, amount=mint_amount)
        return token_contract.transact('mintFor', gas_limit, mint_amount, target_address)
    elif no_action_msg:
        log.debug(no_action_msg, balance=balance)
    return None

def decode_event(abi: ABI, log_: Dict) -> Dict:
    """Helper function to unpack event data using a provided ABI

    Args:
        abi: The ABI of the contract, not the ABI of the event
        log_: The raw event data

    Returns:
        The decoded event"""
    if isinstance(log_['topics'][0], str):
        log_['topics'][0] = decode_hex(log_['topics'][0])
    elif isinstance(log_['topics'][0], int):
        log_['topics'][0] = decode_hex(hex(log_['topics'][0]))
    event_id = log_['topics'][0]
    events = filter_by_type('event', abi)
    topic_to_event_abi = {event_abi_to_log_topic(event_abi): event_abi for event_abi in events}
    event_abi = topic_to_event_abi[event_id]
    return get_event_data(event_abi, log_)

def upgrade_v16_to_v17(storage: SQLiteStorage, old_version: int, current_version: int, **kwargs):
    """InitiatorPaymentState was changed so that the "initiator"
    attribute is renamed to "initiator_transfers" and converted to a list."""
    if old_version == SOURCE_VERSION:
        _transform_snapshots(storage)
    return TARGET_VERSION

def inplace_delete_message_queue(chain_state: ChainState, state_change: Union[ReceiveDelivered, ReceiveProcessed], queueid: QueueIdentifier) -> None:
    """Filter messages from queue, if the queue becomes empty, cleanup the queue itself."""
    queue = chain_state.queueids_to_queues.get(queueid)
    if not queue:
        return
    inplace_delete_message(message_queue=queue, state_change=state_change)
    if len(queue) == 0:
        del chain_state.queueids_to_queues[queueid]
    else:
        chain_state.queueids_to_queues[queueid] = queue

def inplace_delete_message(message_queue: List[SendMessageEvent], state_change: Union[ReceiveDelivered, ReceiveProcessed]) -> None:
    """Check if the message exists in queue with ID `queueid` and exclude if found."""
    for message in list(message_queue):
        message_found = message.message_identifier == state_change.message_identifier and message.recipient == state_change.sender
        if message_found:
            message_queue.remove(message)

def handle_delivered(chain_state: ChainState, state_change: ReceiveDelivered) -> TransitionResult[ChainState]:
    """Check if the "Delivered" message exists in the global queue and delete if found."""
    queueid = QueueIdentifier(state_change.sender, CHANNEL_IDENTIFIER_GLOBAL_QUEUE)
    inplace_delete_message_queue(chain_state, state_change, queueid)
    return TransitionResult(chain_state, [])

