    """Print version information and exit."""
    if short:
        print(get_system_spec()['raiden'])
    else:
        print(json.dumps(get_system_spec(), indent=2))

def is_safe_to_wait(lock_expiration: BlockExpiration, reveal_timeout: BlockTimeout, block_number: BlockNumber) -> SuccessOrError:
    """True if waiting is safe, i.e. there are more than enough blocks to safely
    unlock on chain."""
    assert block_number > 0
    assert reveal_timeout > 0
    assert lock_expiration > reveal_timeout
    lock_timeout = lock_expiration - block_number
    if lock_timeout > reveal_timeout:
        return (True, None)
    msg = f'lock timeout is unsafe. timeout must be larger than {reveal_timeout}, but it is {lock_timeout}. expiration: {lock_expiration} block_number: {block_number}'
    return (False, msg)

def is_send_transfer_almost_equal(send_channel: NettingChannelState, send: LockedTransferUnsignedState, received: LockedTransferSignedState) -> bool:
    """True if both transfers are for the same mediated transfer."""
    return isinstance(send, LockedTransferUnsignedState) and isinstance(received, LockedTransferSignedState) and (send.payment_identifier == received.payment_identifier) and (send.token == received.token) and (send.lock.amount == received.lock.amount - send_channel.mediation_fee) and (send.lock.expiration == received.lock.expiration) and (send.lock.secrethash == received.lock.secrethash) and (send.initiator == received.initiator) and (send.target == received.target)

def filter_reachable_routes(routes: List[RouteState], nodeaddresses_to_networkstates: NodeNetworkStateMap) -> List[RouteState]:
    """This function makes sure we use reachable routes only."""
    reachable_routes = []
    for route in routes:
        node_network_state = nodeaddresses_to_networkstates.get(route.node_address, NODE_NETWORK_UNREACHABLE)
        if node_network_state == NODE_NETWORK_REACHABLE:
            reachable_routes.append(route)
    return reachable_routes

def filter_used_routes(transfers_pair: List[MediationPairState], routes: List[RouteState]) -> List[RouteState]:
    """This function makes sure we filter routes that have already been used.

    So in a setup like this, we want to make sure that node 2, having tried to
    route the transfer through 3 will also try 5 before sending it backwards to 1

    1 -> 2 -> 3 -> 4
         v         ^
         5 -> 6 -> 7
    This function will return routes as provided in their original order."""
    channelid_to_route = {r.channel_identifier: r for r in routes}
    routes_order = {route.node_address: index for index, route in enumerate(routes)}
    for pair in transfers_pair:
        channelid = pair.payer_transfer.balance_proof.channel_identifier
        if channelid in channelid_to_route:
            del channelid_to_route[channelid]
        channelid = pair.payee_transfer.balance_proof.channel_identifier
        if channelid in channelid_to_route:
            del channelid_to_route[channelid]
    return sorted(channelid_to_route.values(), key=lambda route: routes_order[route.node_address])

def get_payer_channel(channelidentifiers_to_channels: ChannelMap, transfer_pair: MediationPairState) -> Optional[NettingChannelState]:
    """Returns the payer channel of a given transfer pair or None if it's not found"""
    payer_channel_identifier = transfer_pair.payer_transfer.balance_proof.channel_identifier
    return channelidentifiers_to_channels.get(payer_channel_identifier)

def get_lock_amount_after_fees(lock: HashTimeLockState, payee_channel: NettingChannelState) -> PaymentWithFeeAmount:
    """Return the lock.amount after fees are taken.

    Fees are taken only for the outgoing channel, which is the one with
    collateral locked from this node."""
    return PaymentWithFeeAmount(lock.amount - payee_channel.mediation_fee)

def clear_if_finalized(iteration: TransitionResult, channelidentifiers_to_channels: ChannelMap) -> TransitionResult[MediatorTransferState]:
    """Clear the mediator task if all the locks have been finalized.

    A lock is considered finalized if it has been removed from the merkle tree
    offchain, either because the transfer was unlocked or expired, or because the
    channel was settled on chain and therefore the channel is removed."""
    state = cast(MediatorTransferState, iteration.new_state)
    if state is None:
        return iteration
    secrethash = state.secrethash
    for pair in state.transfers_pair:
        payer_channel = get_payer_channel(channelidentifiers_to_channels, pair)
        if payer_channel and channel.is_lock_pending(payer_channel.partner_state, secrethash):
            return iteration
        payee_channel = get_payee_channel(channelidentifiers_to_channels, pair)
        if payee_channel and channel.is_lock_pending(payee_channel.our_state, secrethash):
            return iteration
    if state.waiting_transfer:
        waiting_transfer = state.waiting_transfer.transfer
        waiting_channel_identifier = waiting_transfer.balance_proof.channel_identifier
        waiting_channel = channelidentifiers_to_channels.get(waiting_channel_identifier)
        if waiting_channel and channel.is_lock_pending(waiting_channel.partner_state, secrethash):
            return iteration
    return TransitionResult(None, iteration.events)

def set_offchain_secret(state: MediatorTransferState, channelidentifiers_to_channels: ChannelMap, secret: Secret, secrethash: SecretHash) -> List[Event]:
    """Set the secret to all mediated transfers."""
    state.secret = secret
    for pair in state.transfers_pair:
        payer_channel = channelidentifiers_to_channels.get(pair.payer_transfer.balance_proof.channel_identifier)
        if payer_channel:
            channel.register_offchain_secret(payer_channel, secret, secrethash)
        payee_channel = channelidentifiers_to_channels.get(pair.payee_transfer.balance_proof.channel_identifier)
        if payee_channel:
            channel.register_offchain_secret(payee_channel, secret, secrethash)
    if state.waiting_transfer:
        payer_channel = channelidentifiers_to_channels.get(state.waiting_transfer.transfer.balance_proof.channel_identifier)
        if payer_channel:
            channel.register_offchain_secret(payer_channel, secret, secrethash)
        unexpected_reveal = EventUnexpectedSecretReveal(secrethash=secrethash, reason='The mediator has a waiting transfer.')
        return [unexpected_reveal]
    return list()

def set_onchain_secret(state: MediatorTransferState, channelidentifiers_to_channels: ChannelMap, secret: Secret, secrethash: SecretHash, block_number: BlockNumber) -> List[Event]:
    """Set the secret to all mediated transfers.

    The secret should have been learned from the secret registry."""
    state.secret = secret
    for pair in state.transfers_pair:
        payer_channel = channelidentifiers_to_channels.get(pair.payer_transfer.balance_proof.channel_identifier)
        if payer_channel:
            channel.register_onchain_secret(payer_channel, secret, secrethash, block_number)
        payee_channel = channelidentifiers_to_channels.get(pair.payee_transfer.balance_proof.channel_identifier)
        if payee_channel:
            channel.register_onchain_secret(channel_state=payee_channel, secret=secret, secrethash=secrethash, secret_reveal_block_number=block_number)
    if state.waiting_transfer:
        payer_channel = channelidentifiers_to_channels.get(state.waiting_transfer.transfer.balance_proof.channel_identifier)
        if payer_channel:
            channel.register_onchain_secret(channel_state=payer_channel, secret=secret, secrethash=secrethash, secret_reveal_block_number=block_number)
        unexpected_reveal = EventUnexpectedSecretReveal(secrethash=secrethash, reason='The mediator has a waiting transfer.')
        return [unexpected_reveal]
    return list()

def set_offchain_reveal_state(transfers_pair: List[MediationPairState], payee_address: Address) -> None:
    """Set the state of a transfer *sent* to a payee."""
    for pair in transfers_pair:
        if pair.payee_address == payee_address:
            pair.payee_state = 'payee_secret_revealed'

def eth_sign_sha3(data: bytes) -> bytes:
    """    eth_sign/recover compatible hasher
        Prefixes data with "\x19Ethereum Signed Message:
    <len(data)>"
    """
    prefix = b'\x19Ethereum Signed Message:\n'
    if not data.startswith(prefix):
        data = prefix + b'%d%s' % (len(data), data)
    return keccak(data)

def recover(data: bytes, signature: Signature, hasher: Callable[[bytes], bytes]=eth_sign_sha3) -> Address:
    """eth_recover address from data hash and signature"""
    _hash = hasher(data)
    if signature[-1] >= 27:
        signature = Signature(signature[:-1] + bytes([signature[-1] - 27]))
    try:
        sig = keys.Signature(signature_bytes=signature)
        public_key = keys.ecdsa_recover(message_hash=_hash, signature=sig)
    except BadSignature as e:
        raise InvalidSignature from e
    return public_key.to_canonical_address()

def clear_if_finalized(iteration: TransitionResult) -> TransitionResult[InitiatorPaymentState]:
    """Clear the initiator payment task if all transfers have been finalized
    or expired."""
    state = cast(InitiatorPaymentState, iteration.new_state)
    if state is None:
        return iteration
    if len(state.initiator_transfers) == 0:
        return TransitionResult(None, iteration.events)
    return iteration

def subdispatch_to_all_initiatortransfer(payment_state: InitiatorPaymentState, state_change: StateChange, channelidentifiers_to_channels: ChannelMap, pseudo_random_generator: random.Random) -> TransitionResult[InitiatorPaymentState]:
    events = list()
    ' Copy and iterate over the list of keys because this loop\n    will alter the `initiator_transfers` list and this is not\n    allowed if iterating over the original list.\n    '
    for secrethash in list(payment_state.initiator_transfers.keys()):
        initiator_state = payment_state.initiator_transfers[secrethash]
        sub_iteration = subdispatch_to_initiatortransfer(payment_state=payment_state, initiator_state=initiator_state, state_change=state_change, channelidentifiers_to_channels=channelidentifiers_to_channels, pseudo_random_generator=pseudo_random_generator)
        events.extend(sub_iteration.events)
    return TransitionResult(payment_state, events)

def handle_cancelpayment(payment_state: InitiatorPaymentState, channelidentifiers_to_channels: ChannelMap) -> TransitionResult[InitiatorPaymentState]:
    """Cancel the payment and all related transfers."""
    events = list()
    for initiator_state in payment_state.initiator_transfers.values():
        channel_identifier = initiator_state.channel_identifier
        channel_state = channelidentifiers_to_channels.get(channel_identifier)
        if not channel_state:
            continue
        if can_cancel(initiator_state):
            transfer_description = initiator_state.transfer_description
            cancel_events = cancel_current_route(payment_state, initiator_state)
            initiator_state.transfer_state = 'transfer_cancelled'
            cancel = EventPaymentSentFailed(payment_network_identifier=channel_state.payment_network_identifier, token_network_identifier=TokenNetworkID(channel_state.token_network_identifier), identifier=transfer_description.payment_identifier, target=transfer_description.target, reason='user canceled payment')
            cancel_events.append(cancel)
            events.extend(cancel_events)
    return TransitionResult(payment_state, events)

def http_retry_with_backoff_middleware(make_request, web3, errors: Tuple=(exceptions.ConnectionError, exceptions.HTTPError, exceptions.Timeout, exceptions.TooManyRedirects), retries: int=10, first_backoff: float=0.2, backoff_factor: float=2):
    """Retry requests with exponential backoff
    Creates middleware that retries failed HTTP requests and exponentially
    increases the backoff between retries. Meant to replace the default
    middleware `http_retry_request_middleware` for HTTPProvider."""
    def middleware(method, params):
        backoff = first_backoff
        if check_if_retry_on_failure(method):
            for i in range(retries):
                try:
                    return make_request(method, params)
                except errors:
                    if i < retries - 1:
                        gevent.sleep(backoff)
                        backoff *= backoff_factor
                        continue
                    else:
                        raise
        else:
            return make_request(method, params)
    return middleware

def get_random_service(service_registry: ServiceRegistry, block_identifier: BlockSpecification) -> Tuple[Optional[str], Optional[str]]:
    """Selects a random PFS from service_registry.

    Returns a tuple of the chosen services url and eth address.
    If there are no PFS in the given registry, it returns (None, None)."""
    count = service_registry.service_count(block_identifier=block_identifier)
    if count == 0:
        return (None, None)
    index = random.SystemRandom().randint(0, count - 1)
    address = service_registry.get_service_address(block_identifier=block_identifier, index=index)
    assert address, 'address should exist for this index'
    url = service_registry.get_service_url(block_identifier=block_identifier, service_hex_address=address)
    return (url, address)

def get_matrix_servers(url: str) -> List[str]:
    """Fetch a list of matrix servers from a text url

    '-' prefixes (YAML list) are cleaned. Comment lines /^\\s*#/ are ignored

    url: url of a text file
    returns: list of urls, default schema is https"""
    try:
        response = requests.get(url)
        if response.status_code != 200:
            raise requests.RequestException('Response: {response!r}')
    except requests.RequestException as ex:
        raise RuntimeError(f'Could not fetch matrix servers list: {url!r} => {ex!r}') from ex
    available_servers = []
    for line in response.text.splitlines():
        line = line.strip(string.whitespace + '-')
        if line.startswith('#') or not line:
            continue
        if not line.startswith('http'):
            line = 'https://' + line
        available_servers.append(line)
    return available_servers

def _redact_secret(data: Union[Dict, List]) -> Union[Dict, List]:
    """Modify `data` in-place and replace keys named `secret`."""
    if isinstance(data, dict):
        stack = [data]
    else:
        stack = []
    while stack:
        current = stack.pop()
        if 'secret' in current:
            current['secret'] = '<redacted>'
        else:
            stack.extend((value for value in current.values() if isinstance(value, dict)))
    return data

def check_transaction_threw(client, transaction_hash: bytes):
    """Check if the transaction threw/reverted or if it executed properly
    Returns None in case of success and the transaction receipt if the
    transaction's status indicator is 0x0."""
    receipt = client.get_transaction_receipt(transaction_hash)
    if 'status' not in receipt:
        raise ValueError('Transaction receipt does not contain a status field. Upgrade your client')
    if receipt['status'] == RECEIPT_FAILURE_CODE:
        return receipt
    return None

def rgb_color_picker(obj, min_luminance=None, max_luminance=None):
    """Modified version of colour.RGB_color_picker"""
    color_value = int.from_bytes(hashlib.md5(str(obj).encode('utf-8')).digest(), 'little') % 16777215
    color = Color(f'#{color_value:06x}')
    if min_luminance and color.get_luminance() < min_luminance:
        color.set_luminance(min_luminance)
    elif max_luminance and color.get_luminance() > max_luminance:
        color.set_luminance(max_luminance)
    return color

def random_secret() -> Secret:
    """Return a random 32 byte secret except the 0 secret since it's not accepted in the contracts
    """
    while True:
        secret = os.urandom(32)
        if secret != constants.EMPTY_HASH:
            return Secret(secret)

def address_checksum_and_decode(addr: str) -> Address:
    """Accepts a string address and turns it into binary.

    Makes sure that the string address provided starts is 0x prefixed and
    checksummed according to EIP55 specification"""
    if not is_0x_prefixed(addr):
        raise InvalidAddress('Address must be 0x prefixed')
    if not is_checksum_address(addr):
        raise InvalidAddress('Address must be EIP55 checksummed')
    addr_bytes = decode_hex(addr)
    assert len(addr_bytes) in (20, 0)
    return Address(addr_bytes)

def privatekey_to_publickey(private_key_bin: bytes) -> bytes:
    """Returns public key in bitcoins 'bin' encoding."""
    if not ishash(private_key_bin):
        raise ValueError('private_key_bin format mismatch. maybe hex encoded?')
    return keys.PrivateKey(private_key_bin).public_key.to_bytes()

def get_system_spec() -> Dict[str, str]:
    """Collect information about the system and installation.
    """
    import pkg_resources
    import platform
    if sys.platform == 'darwin':
        system_info = 'macOS {} {}'.format(platform.mac_ver()[0], platform.architecture()[0])
    else:
        system_info = '{} {} {}'.format(platform.system(), '_'.join((part for part in platform.architecture() if part)), platform.release())
    try:
        version = pkg_resources.require(raiden.__name__)[0].version
    except (pkg_resources.VersionConflict, pkg_resources.DistributionNotFound):
        raise RuntimeError('Cannot detect Raiden version. Did you do python setup.py?  Refer to https://raiden-network.readthedocs.io/en/latest/overview_and_guide.html#for-developers')
    system_spec = {'raiden': version, 'python_implementation': platform.python_implementation(), 'python_version': platform.python_version(), 'system': system_info, 'architecture': platform.machine(), 'distribution': 'bundled' if getattr(sys, 'frozen', False) else 'source'}
    return system_spec

def split_in_pairs(arg: Iterable) -> Iterable[Tuple]:
    """Split given iterable in pairs [a, b, c, d, e] -> [(a, b), (c, d), (e, None)]"""
    iterator = iter(arg)
    return zip_longest(iterator, iterator)

def safe_gas_limit(*estimates: int) -> int:
    """Calculates a safe gas limit for a number of gas estimates
    including a security margin"""
    assert None not in estimates, 'if estimateGas returned None it should not reach here'
    calculated_limit = max(estimates)
    return int(calculated_limit * constants.GAS_FACTOR)

def block_specification_to_number(block: BlockSpecification, web3: Web3) -> BlockNumber:
    """Converts a block specification to an actual block number"""
    if isinstance(block, str):
        msg = f"string block specification can't contain {block}"
        assert block in ('latest', 'pending'), msg
        number = web3.eth.getBlock(block)['number']
    elif isinstance(block, T_BlockHash):
        number = web3.eth.getBlock(block)['number']
    elif isinstance(block, T_BlockNumber):
        number = block
    elif __debug__:
        raise AssertionError(f'Unknown type {type(block)} given for block specification')
    return BlockNumber(number)

def next_channel_from_routes(available_routes: List[RouteState], channelidentifiers_to_channels: ChannelMap, transfer_amount: PaymentAmount) -> Optional[NettingChannelState]:
    """Returns the first channel that can be used to start the transfer.
    The routing service can race with local changes, so the recommended routes
    must be validated."""
    for route in available_routes:
        channel_identifier = route.channel_identifier
        channel_state = channelidentifiers_to_channels.get(channel_identifier)
        if not channel_state:
            continue
        if channel.get_status(channel_state) != CHANNEL_STATE_OPENED:
            continue
        pending_transfers = channel.get_number_of_pending_transfers(channel_state.our_state)
        if pending_transfers >= MAXIMUM_PENDING_TRANSFERS:
            continue
        distributable = channel.get_distributable(channel_state.our_state, channel_state.partner_state)
        if transfer_amount > distributable:
            continue
        if channel.is_valid_amount(channel_state.our_state, transfer_amount):
            return channel_state
    return None

def is_deposit_confirmed(channel_state: NettingChannelState, block_number: BlockNumber) -> bool:
    """True if the block which mined the deposit transaction has been
    confirmed."""
    if not channel_state.deposit_transaction_queue:
        return False
    return is_transaction_confirmed(channel_state.deposit_transaction_queue[0].block_number, block_number)

def is_lock_expired(end_state: NettingChannelEndState, lock: LockType, block_number: BlockNumber, lock_expiration_threshold: BlockNumber) -> SuccessOrError:
    """Determine whether a lock has expired.

    The lock has expired if both:

        - The secret was not registered on-chain in time.
        - The current block exceeds lock's expiration + confirmation blocks."""
    secret_registered_on_chain = lock.secrethash in end_state.secrethashes_to_onchain_unlockedlocks
    if secret_registered_on_chain:
        return (False, 'lock has been unlocked on-chain')
    if block_number < lock_expiration_threshold:
        msg = f'current block number ({block_number}) is not larger than lock.expiration + confirmation blocks ({lock_expiration_threshold})'
        return (False, msg)
    return (True, None)

def is_secret_known(end_state: NettingChannelEndState, secrethash: SecretHash) -> bool:
    """True if the `secrethash` is for a lock with a known secret."""
    return secrethash in end_state.secrethashes_to_unlockedlocks or secrethash in end_state.secrethashes_to_onchain_unlockedlocks

def get_secret(end_state: NettingChannelEndState, secrethash: SecretHash) -> Optional[Secret]:
    """Returns `secret` if the `secrethash` is for a lock with a known secret."""
    partial_unlock_proof = end_state.secrethashes_to_unlockedlocks.get(secrethash)
    if partial_unlock_proof is None:
        partial_unlock_proof = end_state.secrethashes_to_onchain_unlockedlocks.get(secrethash)
    if partial_unlock_proof is not None:
        return partial_unlock_proof.secret
    return None

def get_lock(end_state: NettingChannelEndState, secrethash: SecretHash) -> Optional[HashTimeLockState]:
    """Return the lock correspoding to `secrethash` or None if the lock is
    unknown."""
    lock = end_state.secrethashes_to_lockedlocks.get(secrethash)
    if not lock:
        partial_unlock = end_state.secrethashes_to_unlockedlocks.get(secrethash)
        if not partial_unlock:
            partial_unlock = end_state.secrethashes_to_onchain_unlockedlocks.get(secrethash)
        if partial_unlock:
            lock = partial_unlock.lock
    assert isinstance(lock, HashTimeLockState) or lock is None
    return lock

def lock_exists_in_either_channel_side(channel_state: NettingChannelState, secrethash: SecretHash) -> bool:
    """Check if the lock with `secrethash` exists in either our state or the partner's state"""
    lock = get_lock(channel_state.our_state, secrethash)
    if not lock:
        lock = get_lock(channel_state.partner_state, secrethash)
    return lock is not None

def hexbytes_to_str(map_: Dict):
    """Converts values that are of type `HexBytes` to strings."""
    for k, v in map_.items():
        if isinstance(v, HexBytes):
            map_[k] = encode_hex(v)

def encode_byte_values(map_: Dict):
    """Converts values that are of type `bytes` to strings."""
    for k, v in map_.items():
        if isinstance(v, bytes):
            map_[k] = encode_hex(v)

def setup_network_id_or_exit(config: Dict[str, Any], given_network_id: int, web3: Web3) -> Tuple[int, bool]:
    """Takes the given network id and checks it against the connected network

    If they don't match, exits the program with an error. If they do adds it
    to the configuration and then returns it and whether it is a known network"""
    node_network_id = int(web3.version.network)
    known_given_network_id = given_network_id in ID_TO_NETWORKNAME
    known_node_network_id = node_network_id in ID_TO_NETWORKNAME
    if node_network_id != given_network_id:
        if known_given_network_id and known_node_network_id:
            click.secho(f"The chosen ethereum network '{ID_TO_NETWORKNAME[given_network_id]}' differs from the ethereum client '{ID_TO_NETWORKNAME[node_network_id]}'. Please update your settings.", fg='red')
        else:
            click.secho(f"The chosen ethereum network id '{given_network_id}' differs from the ethereum client '{node_network_id}'. Please update your settings.", fg='red')
        sys.exit(1)
    config['chain_id'] = given_network_id
    return (given_network_id, known_node_network_id)

def setup_environment(config: Dict[str, Any], environment_type: Environment) -> None:
    """Sets the config depending on the environment type"""
    if environment_type == Environment.PRODUCTION:
        config['transport']['matrix']['private_rooms'] = True
    config['environment_type'] = environment_type
    print(f'Raiden is running in {environment_type.value.lower()} mode')

def setup_contracts_or_exit(config: Dict[str, Any], network_id: int) -> Dict[str, Any]:
    """Sets the contract deployment data depending on the network id and environment type

    If an invalid combination of network id and environment type is provided, exits
    the program with an error"""
    environment_type = config['environment_type']
    not_allowed = network_id == 1 and environment_type == Environment.DEVELOPMENT
    if not_allowed:
        click.secho(f'The chosen network ({ID_TO_NETWORKNAME[network_id]}) is not a testnet, but the "development" environment was selected.\nThis is not allowed. Please start again with a safe environment setting (--environment production).', fg='red')
        sys.exit(1)
    contracts = dict()
    contracts_version = environment_type_to_contracts_version(environment_type)
    config['contracts_path'] = contracts_precompiled_path(contracts_version)
    if network_id in ID_TO_NETWORKNAME and ID_TO_NETWORKNAME[network_id] != 'smoketest':
        try:
            deployment_data = get_contracts_deployment_info(chain_id=network_id, version=contracts_version)
        except ValueError:
            return (contracts, False)
        contracts = deployment_data['contracts']
    return contracts

def wait_for_participant_newbalance(raiden: 'RaidenService', payment_network_id: PaymentNetworkID, token_address: TokenAddress, partner_address: Address, target_address: Address, target_balance: TokenAmount, retry_timeout: float) -> None:
    """Wait until a given channels balance exceeds the target balance.

    Note:
        This does not time out, use gevent.Timeout."""
    if target_address == raiden.address:
        balance = lambda channel_state: channel_state.our_state.contract_balance
    elif target_address == partner_address:
        balance = lambda channel_state: channel_state.partner_state.contract_balance
    else:
        raise ValueError('target_address must be one of the channel participants')
    channel_state = views.get_channelstate_for(views.state_from_raiden(raiden), payment_network_id, token_address, partner_address)
    while balance(channel_state) < target_balance:
        gevent.sleep(retry_timeout)
        channel_state = views.get_channelstate_for(views.state_from_raiden(raiden), payment_network_id, token_address, partner_address)

def wait_for_payment_balance(raiden: 'RaidenService', payment_network_id: PaymentNetworkID, token_address: TokenAddress, partner_address: Address, target_address: Address, target_balance: TokenAmount, retry_timeout: float) -> None:
    """Wait until a given channel's balance exceeds the target balance.

    Note:
        This does not time out, use gevent.Timeout."""
    def get_balance(end_state):
        if end_state.balance_proof:
            return end_state.balance_proof.transferred_amount
        else:
            return 0
    if target_address == raiden.address:
        balance = lambda channel_state: get_balance(channel_state.partner_state)
    elif target_address == partner_address:
        balance = lambda channel_state: get_balance(channel_state.our_state)
    else:
        raise ValueError('target_address must be one of the channel participants')
    channel_state = views.get_channelstate_for(views.state_from_raiden(raiden), payment_network_id, token_address, partner_address)
    while balance(channel_state) < target_balance:
        log.critical('wait', b=balance(channel_state), t=target_balance)
        gevent.sleep(retry_timeout)
        channel_state = views.get_channelstate_for(views.state_from_raiden(raiden), payment_network_id, token_address, partner_address)

def wait_for_close(raiden: 'RaidenService', payment_network_id: PaymentNetworkID, token_address: TokenAddress, channel_ids: List[ChannelID], retry_timeout: float) -> None:
    """Wait until all channels are closed.

    Note:
        This does not time out, use gevent.Timeout."""
    return wait_for_channel_in_states(raiden=raiden, payment_network_id=payment_network_id, token_address=token_address, channel_ids=channel_ids, retry_timeout=retry_timeout, target_states=CHANNEL_AFTER_CLOSE_STATES)

def wait_for_settle(raiden: 'RaidenService', payment_network_id: PaymentNetworkID, token_address: TokenAddress, channel_ids: List[ChannelID], retry_timeout: float) -> None:
    """Wait until all channels are settled.

    Note:
        This does not time out, use gevent.Timeout."""
    return wait_for_channel_in_states(raiden=raiden, payment_network_id=payment_network_id, token_address=token_address, channel_ids=channel_ids, retry_timeout=retry_timeout, target_states=(CHANNEL_STATE_SETTLED,))

def wait_for_transfer_success(raiden: 'RaidenService', payment_identifier: PaymentID, amount: PaymentAmount, retry_timeout: float) -> None:
    """Wait until a transfer with a specific identifier and amount
    is seen in the WAL.

    Note:
        This does not time out, use gevent.Timeout."""
    found = False
    while not found:
        state_events = raiden.wal.storage.get_events()
        for event in state_events:
            found = isinstance(event, EventPaymentReceivedSuccess) and event.identifier == payment_identifier and (event.amount == amount)
            if found:
                break
        gevent.sleep(retry_timeout)

def validate_userid_signature(user: User) -> Optional[Address]:
    """Validate a userId format and signature on displayName, and return its address"""
    match = USERID_RE.match(user.user_id)
    if not match:
        return None
    encoded_address = match.group(1)
    address: Address = to_canonical_address(encoded_address)
    try:
        displayname = user.get_display_name()
        recovered = recover(data=user.user_id.encode(), signature=decode_hex(displayname))
        if not (address and recovered and (recovered == address)):
            return None
    except (DecodeError, TypeError, InvalidSignature, MatrixRequestError, json.decoder.JSONDecodeError):
        return None
    return address

def make_client(servers: Sequence[str], *args, **kwargs) -> GMatrixClient:
    """Given a list of possible servers, chooses the closest available and create a GMatrixClient

    Params:
        servers: list of servers urls, with scheme (http or https)
        Rest of args and kwargs are forwarded to GMatrixClient constructor
    Returns:
        GMatrixClient instance for one of the available servers"""
    if len(servers) > 1:
        sorted_servers = [server_url for server_url, _ in sort_servers_closest(servers)]
        log.info('Automatically selecting matrix homeserver based on RTT', sorted_servers=sorted_servers)
    elif len(servers) == 1:
        sorted_servers = servers
    else:
        raise TransportError('No valid servers list given')
    last_ex = None
    for server_url in sorted_servers:
        server_url: str = server_url
        client = GMatrixClient(server_url, *args, **kwargs)
        try:
            client.api._send('GET', '/versions', api_path='/_matrix/client')
        except MatrixError as ex:
            log.warning('Selected server not usable', server_url=server_url, _exception=ex)
            last_ex = ex
        else:
            break
    else:
        raise TransportError('Unable to find a reachable Matrix server. Please check your network connectivity.') from last_ex
    return client

def check_version(current_version: str):
    """Check periodically for a new release"""
    app_version = parse_version(current_version)
    while True:
        try:
            _do_check_version(app_version)
        except requests.exceptions.HTTPError as herr:
            click.secho('Error while checking for version', fg='red')
            print(herr)
        except ValueError as verr:
            click.secho('Error while checking the version', fg='red')
            print(verr)
        finally:
            gevent.sleep(CHECK_VERSION_INTERVAL)

def check_gas_reserve(raiden):
    """Check periodically for gas reserve in the account"""
    while True:
        has_enough_balance, estimated_required_balance = gas_reserve.has_enough_gas_reserve(raiden, channels_to_open=1)
        estimated_required_balance_eth = Web3.fromWei(estimated_required_balance, 'ether')
        if not has_enough_balance:
            log.info('Missing gas reserve', required_wei=estimated_required_balance)
            click.secho(f"WARNING\nYour account's balance is below the estimated gas reserve of {estimated_required_balance_eth} eth. This may lead to a loss of of funds because your account will be unable to perform on-chain transactions. Please add funds to your account as soon as possible.", fg='red')
        gevent.sleep(CHECK_GAS_RESERVE_INTERVAL)

def check_rdn_deposits(raiden, user_deposit_proxy: UserDeposit):
    """Check periodically for RDN deposits in the user-deposits contract"""
    while True:
        rei_balance = user_deposit_proxy.effective_balance(raiden.address, 'latest')
        rdn_balance = to_rdn(rei_balance)
        if rei_balance < MIN_REI_THRESHOLD:
            click.secho(f"WARNING\nYour account's RDN balance of {rdn_balance} is below the minimum threshold. Provided that you have either a monitoring service or a path finding service activated, your node is not going to be able to pay those services which may lead to denial of service or loss of funds.", fg='red')
        gevent.sleep(CHECK_RDN_MIN_DEPOSIT_INTERVAL)

def check_network_id(network_id, web3: Web3):
    """Check periodically if the underlying ethereum client's network id has changed"""
    while True:
        current_id = int(web3.version.network)
        if network_id != current_id:
            raise RuntimeError(f'Raiden was running on network with id {network_id} and it detected that the underlying ethereum client network id changed to {current_id}. Changing the underlying blockchain while the Raiden node is running is not supported.')
        gevent.sleep(CHECK_NETWORK_ID_INTERVAL)

def pack_data(abi_types, values) -> bytes:
    """Normalize data and pack them into a byte array"""
    if len(abi_types) != len(values):
        raise ValueError('Length mismatch between provided abi types and values.  Got {0} types and {1} values.'.format(len(abi_types), len(values)))
    normalized_values = map_abi_data([abi_address_to_hex], abi_types, values)
    return decode_hex(''.join((remove_0x_prefix(hex_encode_abi_type(abi_type, value)) for abi_type, value in zip(abi_types, normalized_values))))

def _check_workflows_align(config):
    """Ensure that the common shared jobs in the `raiden-default` and `nightly` workflows are
    identical."""
    jobs_default = config['workflows']['raiden-default']['jobs']
    jobs_nightly = config['workflows']['nightly']['jobs']
    if jobs_default == jobs_nightly[:len(jobs_default)]:
        return (True, [])
    job_diff = unified_diff([f'{line}\n' for line in jobs_default], [f'{line}\n' for line in jobs_nightly[:len(jobs_default)]], 'raiden-default', 'nightly')
    message = [_yellow("Mismatch in common items of workflow definitions 'raiden-default' and 'nightly':\n")]
    for line in job_diff:
        if line.startswith('-'):
            message.append(_red(line))
        elif line.startswith('+'):
            message.append(_green(line))
        else:
            message.append(line)
    return (False, ''.join(message))

def geth_commands(ctx, geth_hosts, datadir):
    """This is helpful to setup a private cluster of geth nodes that won't need discovery
    (because they can use the content of `static_nodes` as `static-nodes.json`)."""
    pretty = ctx.obj['pretty']
    nodes = []
    for i, host in enumerate(geth_hosts):
        nodes.append(create_node_configuration(host=host, node_key_seed=i))
    for node in nodes:
        node.pop('unlock')
        node.pop('rpcport')
    config = {'{host}'.format(**node): ' '.join(to_cmd(node, datadir=datadir)) for node in nodes}
    config['static_nodes'] = [node['enode'] for node in nodes]
    indent = None
    if pretty:
        indent = 2
    print(json.dumps(config, indent=indent))

def dict_deep_merge(a, b, path=None):
    """Deep-merge dictionary `b` into dictionary `a`.

    Kudos to http://stackoverflow.com/a/7205107/145400"""
    if path is None:
        path = []
    for key in b:
        if key in a:
            if isinstance(a[key], dict) and isinstance(b[key], dict):
                dict_deep_merge(a[key], b[key], path + [str(key)])
            elif a[key] == b[key]:
                pass
            else:
                a[key] = b[key]
        else:
            a[key] = b[key]
    return a

def return_false_on_exception(func):
    """Decorator. When applied to a function, it will, by default, suppress any exceptions
    raised by that function and return False. It may be overridden by passing a
    "raise_exceptions" keyword argument when calling the wrapped function."""
    @wraps(func)
    def exceptfalse(*args, **kwargs):
        if not kwargs.pop('raise_exceptions', False):
            try:
                return func(*args, **kwargs)
            except Exception:
                return False
        else:
            return func(*args, **kwargs)
    return exceptfalse

def loads(s, key=None, salt='django.core.signing', serializer=JSONSerializer, max_age=None):
    """Reverse of dumps(), raise BadSignature if signature fails.

    The serializer is expected to accept a bytestring."""
    base64d = force_bytes(TimestampSigner(key, salt=salt).unsign(s, max_age=max_age))
    decompress = False
    if base64d[:1] == b'.':
        base64d = base64d[1:]
        decompress = True
    data = b64_decode(base64d)
    if decompress:
        data = zlib.decompress(data)
    return serializer().loads(data)

def get_broker(list_key=Conf.PREFIX):
    """Gets the configured broker type
    :param list_key: optional queue name
    :type list_key: str
    :return:"""
    if Conf.BROKER_CLASS:
        module, func = Conf.BROKER_CLASS.rsplit('.', 1)
        m = importlib.import_module(module)
        broker = getattr(m, func)
        return broker(list_key=list_key)
    elif Conf.DISQUE_NODES:
        from django_q.brokers import disque
        return disque.Disque(list_key=list_key)
    elif Conf.IRON_MQ:
        from django_q.brokers import ironmq
        return ironmq.IronMQBroker(list_key=list_key)
    elif Conf.SQS:
        from django_q.brokers import aws_sqs
        return aws_sqs.Sqs(list_key=list_key)
    elif Conf.ORM:
        from django_q.brokers import orm
        return orm.ORM(list_key=list_key)
    elif Conf.MONGO:
        from django_q.brokers import mongo
        return mongo.Mongo(list_key=list_key)
    else:
        from django_q.brokers import redis_broker
        return redis_broker.Redis(list_key=list_key)

def async_task(func, *args, **kwargs):
    """Queue a task for the cluster."""
    keywords = kwargs.copy()
    opt_keys = ('hook', 'group', 'save', 'sync', 'cached', 'ack_failure', 'iter_count', 'iter_cached', 'chain', 'broker')
    q_options = keywords.pop('q_options', {})
    tag = uuid()
    task = {'id': tag[1], 'name': keywords.pop('task_name', None) or q_options.pop('task_name', None) or tag[0], 'func': func, 'args': args}
    for key in opt_keys:
        if q_options and key in q_options:
            task[key] = q_options[key]
        elif key in keywords:
            task[key] = keywords.pop(key)
    broker = task.pop('broker', get_broker())
    if 'cached' not in task and Conf.CACHED:
        task['cached'] = Conf.CACHED
    if 'sync' not in task and Conf.SYNC:
        task['sync'] = Conf.SYNC
    if 'ack_failure' not in task and Conf.ACK_FAILURES:
        task['ack_failure'] = Conf.ACK_FAILURES
    task['kwargs'] = keywords
    task['started'] = timezone.now()
    pre_enqueue.send(sender='django_q', task=task)
    pack = SignedPackage.dumps(task)
    if task.get('sync', False):
        return _sync(pack)
    enqueue_id = broker.enqueue(pack)
    logger.info('Enqueued {}'.format(enqueue_id))
    logger.debug('Pushed {}'.format(tag))
    return task['id']

def result(task_id, wait=0, cached=Conf.CACHED):
    """Return the result of the named task.

    :type task_id: str or uuid
    :param task_id: the task name or uuid
    :type wait: int
    :param wait: number of milliseconds to wait for a result
    :param bool cached: run this against the cache backend
    :return: the result object of this task
    :rtype: object"""
    if cached:
        return result_cached(task_id, wait)
    start = time()
    while True:
        r = Task.get_result(task_id)
        if r:
            return r
        if (time() - start) * 1000 >= wait >= 0:
            break
        sleep(0.01)

def result_cached(task_id, wait=0, broker=None):
    """Return the result from the cache backend"""
    if not broker:
        broker = get_broker()
    start = time()
    while True:
        r = broker.cache.get('{}:{}'.format(broker.list_key, task_id))
        if r:
            return SignedPackage.loads(r)['result']
        if (time() - start) * 1000 >= wait >= 0:
            break
        sleep(0.01)

def result_group(group_id, failures=False, wait=0, count=None, cached=Conf.CACHED):
    """Return a list of results for a task group.

    :param str group_id: the group id
    :param bool failures: set to True to include failures
    :param int count: Block until there are this many results in the group
    :param bool cached: run this against the cache backend
    :return: list or results"""
    if cached:
        return result_group_cached(group_id, failures, wait, count)
    start = time()
    if count:
        while True:
            if count_group(group_id) == count or (wait and (time() - start) * 1000 >= wait >= 0):
                break
            sleep(0.01)
    while True:
        r = Task.get_result_group(group_id, failures)
        if r:
            return r
        if (time() - start) * 1000 >= wait >= 0:
            break
        sleep(0.01)

def result_group_cached(group_id, failures=False, wait=0, count=None, broker=None):
    """Return a list of results for a task group from the cache backend"""
    if not broker:
        broker = get_broker()
    start = time()
    if count:
        while True:
            if count_group_cached(group_id) == count or (wait and (time() - start) * 1000 >= wait > 0):
                break
            sleep(0.01)
    while True:
        group_list = broker.cache.get('{}:{}:keys'.format(broker.list_key, group_id))
        if group_list:
            result_list = []
            for task_key in group_list:
                task = SignedPackage.loads(broker.cache.get(task_key))
                if task['success'] or failures:
                    result_list.append(task['result'])
            return result_list
        if (time() - start) * 1000 >= wait >= 0:
            break
        sleep(0.01)

