def retry_failed(FailAdmin, request, queryset):
    """Submit selected tasks back to the queue."""
    for task in queryset:
        async_task(task.func, *(task.args or ()), hook=task.hook, **task.kwargs or {})
        task.delete()

def pusher(task_queue, event, broker=None):
    """Pulls tasks of the broker and puts them in the task queue
    :type task_queue: multiprocessing.Queue
    :type event: multiprocessing.Event"""
    if not broker:
        broker = get_broker()
    logger.info(_('{} pushing tasks at {}').format(current_process().name, current_process().pid))
    while True:
        try:
            task_set = broker.dequeue()
        except Exception as e:
            logger.error(e, traceback.format_exc())
            sleep(10)
            break
        if task_set:
            for task in task_set:
                ack_id = task[0]
                try:
                    task = SignedPackage.loads(task[1])
                except (TypeError, BadSignature) as e:
                    logger.error(e, traceback.format_exc())
                    broker.fail(ack_id)
                    continue
                task['ack_id'] = ack_id
                task_queue.put(task)
            logger.debug(_('queueing from {}').format(broker.list_key))
        if event.is_set():
            break
    logger.info(_('{} stopped pushing tasks').format(current_process().name))

def monitor(result_queue, broker=None):
    """Gets finished tasks from the result queue and saves them to Django
    :type result_queue: multiprocessing.Queue"""
    if not broker:
        broker = get_broker()
    name = current_process().name
    logger.info(_('{} monitoring at {}').format(name, current_process().pid))
    for task in iter(result_queue.get, 'STOP'):
        if task.get('cached', False):
            save_cached(task, broker)
        else:
            save_task(task, broker)
        ack_id = task.pop('ack_id', False)
        if ack_id and (task['success'] or task.get('ack_failure', False)):
            broker.acknowledge(ack_id)
        if task['success']:
            logger.info(_('Processed [{}]').format(task['name']))
        else:
            logger.error(_('Failed [{}] - {}').format(task['name'], task['result']))
    logger.info(_('{} stopped monitoring results').format(name))

def save_task(task, broker):
    """Saves the task package to Django or the cache"""
    if not task.get('save', Conf.SAVE_LIMIT >= 0) and task['success']:
        return
    if task.get('chain', None):
        django_q.tasks.async_chain(task['chain'], group=task['group'], cached=task['cached'], sync=task['sync'], broker=broker)
    db.close_old_connections()
    try:
        if task['success'] and 0 < Conf.SAVE_LIMIT <= Success.objects.count():
            Success.objects.last().delete()
        if Task.objects.filter(id=task['id'], name=task['name']).exists():
            existing_task = Task.objects.get(id=task['id'], name=task['name'])
            if not existing_task.success:
                existing_task.stopped = task['stopped']
                existing_task.result = task['result']
                existing_task.success = task['success']
                existing_task.save()
        else:
            Task.objects.create(id=task['id'], name=task['name'], func=task['func'], hook=task.get('hook'), args=task['args'], kwargs=task['kwargs'], started=task['started'], stopped=task['stopped'], result=task['result'], group=task.get('group'), success=task['success'])
    except Exception as e:
        logger.error(e)

def set_cpu_affinity(n, process_ids, actual=not Conf.TESTING):
    """Sets the cpu affinity for the supplied processes.
    Requires the optional psutil module.
    :param int n: affinity
    :param list process_ids: a list of pids
    :param bool actual: Test workaround for Travis not supporting cpu affinity"""
    if not psutil:
        logger.warning('Skipping cpu affinity because psutil was not found.')
        return
    if actual and (not hasattr(psutil.Process(process_ids[0]), 'cpu_affinity')):
        logger.warning('Faking cpu affinity because it is not supported on this platform')
        actual = False
    cpu_list = list(range(psutil.cpu_count()))
    if not n or n >= len(cpu_list):
        return
    index = 0
    for pid in process_ids:
        affinity = []
        for k in range(n):
            if index == len(cpu_list):
                index = 0
            affinity.append(cpu_list[index])
            index += 1
        if psutil.pid_exists(pid):
            p = psutil.Process(pid)
            if actual:
                p.cpu_affinity(affinity)
            logger.info(_('{} will use cpu {}').format(pid, affinity))

def InterfaceMatcher(clazz, subclass, protocol):
    """Returns a matcher that returns the setting with the given interface."""
    interface = (clazz, subclass, protocol)
    def Matcher(device):
        for setting in device.iterSettings():
            if GetInterface(setting) == interface:
                return setting
    return Matcher

def _DocToArgs(doc):
    """Converts a docstring documenting arguments into a dict."""
    m = None
    offset = None
    in_arg = False
    out = {}
    for l in doc.splitlines():
        if l.strip() == 'Args:':
            in_arg = True
        elif in_arg:
            if not l.strip():
                break
            if offset is None:
                offset = len(l) - len(l.lstrip())
            l = l[offset:]
            if l[0] == ' ' and m:
                out[m.group(1)] += ' ' + l.lstrip()
            else:
                m = re.match('^([a-z_]+): (.+)$', l.strip())
                out[m.group(1)] = m.group(2)
    return out

def _RunMethod(dev, args, extra):
    """Runs a method registered via MakeSubparser."""
    logging.info('%s(%s)', args.method.__name__, ', '.join(args.positional))
    result = args.method(dev, *args.positional, **extra)
    if result is not None:
        if isinstance(result, io.StringIO):
            sys.stdout.write(result.getvalue())
        elif isinstance(result, (list, types.GeneratorType)):
            r = ''
            for r in result:
                r = str(r)
                sys.stdout.write(r)
            if not r.endswith('\n'):
                sys.stdout.write('\n')
        else:
            result = str(result)
            sys.stdout.write(result)
            if not result.endswith('\n'):
                sys.stdout.write('\n')
    return 0

def StartCli(args, adb_commands, extra=None, **device_kwargs):
    """Starts a common CLI interface for this usb path and protocol."""
    try:
        dev = adb_commands()
        dev.ConnectDevice(port_path=args.port_path, serial=args.serial, default_timeout_ms=args.timeout_ms, **device_kwargs)
    except usb_exceptions.DeviceNotFoundError as e:
        print('No device found: {}'.format(e), file=sys.stderr)
        return 1
    except usb_exceptions.CommonUsbError as e:
        print('Could not connect to device: {}'.format(e), file=sys.stderr)
        return 1
    try:
        return _RunMethod(dev, args, extra or {})
    except Exception as e:
        sys.stdout.write(str(e))
        return 1
    finally:
        dev.Close()

def Devices(args):
    """Lists the available devices.

    Mimics 'adb devices' output:
      List of devices attached
      015DB7591102001A        device        1,2"""
    for d in adb_commands.AdbCommands.Devices():
        if args.output_port_path:
            print('%s\tdevice\t%s' % (d.serial_number, ','.join((str(p) for p in d.port_path))))
        else:
            print('%s\tdevice' % d.serial_number)
    return 0

def Shell(device, *command):
    """Runs a command on the device and prints the stdout.

    Args:
      command: Command to run on the target."""
    if command:
        return device.StreamingShell(' '.join(command))
    else:
        terminal_prompt = device.InteractiveShell()
        print(terminal_prompt.decode('utf-8'))
        while True:
            cmd = input('> ')
            if not cmd:
                continue
            elif cmd == 'exit':
                break
            else:
                stdout = device.InteractiveShell(cmd, strip_cmd=True, delim=terminal_prompt, strip_delim=True)
                if stdout:
                    if isinstance(stdout, bytes):
                        stdout = stdout.decode('utf-8')
                        print(stdout)
        device.Close()

def _load_rsa_private_key(pem):
    """PEM encoded PKCS#8 private key -> rsa.PrivateKey."""
    try:
        der = rsa.pem.load_pem(pem, 'PRIVATE KEY')
        keyinfo, _ = decoder.decode(der)
        if keyinfo[1][0] != univ.ObjectIdentifier('1.2.840.113549.1.1.1'):
            raise ValueError('Not a DER-encoded OpenSSL private RSA key')
        private_key_der = keyinfo[2].asOctets()
    except IndexError:
        raise ValueError('Not a DER-encoded OpenSSL private RSA key')
    return rsa.PrivateKey.load_pkcs1(private_key_der, format='DER')

