def _keep(word_freq: int, min_freq: int, min_len: int, max_len: int, dict_filter: Callable[[str], bool]):
    """Keep only Thai words with at least min_freq frequency
    and has length between min_len and max_len characters"""
    if not word_freq or word_freq[1] < min_freq:
        return False
    word = word_freq[0]
    if not word or len(word) < min_len or len(word) > max_len or (word[0] == '.'):
        return False
    return dict_filter(word)

def _edits2(word: str) -> Set[str]:
    """Return a set of words with edit distance of 2 from the input word"""
    return set((e2 for e1 in _edits1(word) for e2 in _edits1(e1)))

def tcc(text: str) -> str:
    """TCC generator, generates Thai Character Clusters
    :param str text: text to be tokenized to character clusters
    :return: subword (character cluster)"""
    if not text or not isinstance(text, str):
        return ''
    p = 0
    while p < len(text):
        m = PAT_TCC.match(text[p:])
        if m:
            n = m.span()[1]
        else:
            n = 1
        yield text[p:p + n]
        p += n

def tcc_pos(text: str) -> Set[int]:
    """TCC positions
    :param str text: text to be tokenized to character clusters
    :return: list of the end of subwords"""
    if not text or not isinstance(text, str):
        return set()
    p_set = set()
    p = 0
    for w in tcc(text):
        p += len(w)
        p_set.add(p)
    return p_set

def sent_tokenize(text: str, engine: str='whitespace+newline') -> List[str]:
    """This function does not yet automatically recognize when a sentence actually ends. Rather it helps split text where white space and a new line is found.

    :param str text: the text to be tokenized
    :param str engine: choose between 'whitespace' or 'whitespace+newline'

    :return: list of sentences"""
    if not text or not isinstance(text, str):
        return []
    sentences = []
    if engine == 'whitespace':
        sentences = re.split(' +', text, re.U)
    else:
        sentences = text.split()
    return sentences

def subword_tokenize(text: str, engine: str='tcc') -> List[str]:
    """:param str text: text to be tokenized
    :param str engine: subword tokenizer
    :return: list of subwords

    **Options for engine**
        * tcc (default) -  Thai Character Cluster (Theeramunkong et al. 2000)
        * etcc - Enhanced Thai Character Cluster (Inrut et al. 2001) [In development]"""
    if not text or not isinstance(text, str):
        return []
    if engine == 'etcc':
        from .etcc import segment
    else:
        from .tcc import segment
    return segment(text)

def syllable_tokenize(text: str) -> List[str]:
    """:param str text: input string to be tokenized
    :return: list of syllables"""
    if not text or not isinstance(text, str):
        return []
    tokens = []
    if text:
        words = word_tokenize(text)
        trie = dict_trie(dict_source=thai_syllables())
        for word in words:
            tokens.extend(word_tokenize(text=word, custom_dict=trie))
    return tokens

def deletetone(text: str) -> str:
    """Remove tonemarks

    :param str text: thai text
    :return: thai text"""
    chars = [ch for ch in text if ch not in thai_tonemarks]
    return ''.join(chars)

def soundex(text: str, engine: str='udom83') -> str:
    """Thai Soundex

    :param string text: word
    :param str engine: soundex engine
    :Parameters for engine:
        * udom83 (default)
        * lk82
        * metasound
    :return: soundex code"""
    if engine == 'lk82':
        _soundex = lk82
    elif engine == 'metasound':
        _soundex = metasound
    else:
        _soundex = udom83
    return _soundex(text)

def find_all_segment(text: str, custom_dict: Trie=None) -> List[str]:
    """Get all possible segment variations

    :param str text: input string to be tokenized
    :return: returns list of segment variations"""
    if not text or not isinstance(text, str):
        return []
    ww = list(_multicut(text, custom_dict=custom_dict))
    return list(_combine(ww))

def reign_year_to_ad(reign_year: int, reign: int) -> int:
    """Reign year of Chakri dynasty, Thailand"""
    if int(reign) == 10:
        ad = int(reign_year) + 2015
    elif int(reign) == 9:
        ad = int(reign_year) + 1945
    elif int(reign) == 8:
        ad = int(reign_year) + 1928
    elif int(reign) == 7:
        ad = int(reign_year) + 1924
    return ad

def sentence_vectorizer(text: str, use_mean: bool=True):
    """Get sentence vector from text
    If a word is not in the vocabulary, KeyError will be raised.

    :param string text: text input
    :param boolean use_mean: if `True` use mean of all word vectors else use summation

    :return: sentence vector of given input text"""
    words = word_tokenize(text, engine='ulmfit')
    vec = np.zeros((1, WV_DIM))
    for word in words:
        if word == ' ':
            word = 'xxspace'
        elif word == '\n':
            word = 'xxeol'
        if word in _MODEL.wv.index2word:
            vec += _MODEL.wv.word_vec(word)
        else:
            pass
    if use_mean:
        vec /= len(words)
    return vec

def countthai(text: str, ignore_chars: str=_DEFAULT_IGNORE_CHARS) -> float:
    """:param str text: input text
    :return: float, proportion of characters in the text that is Thai character"""
    if not text or not isinstance(text, str):
        return 0
    if not ignore_chars:
        ignore_chars = ''
    num_thai = 0
    num_ignore = 0
    for ch in text:
        if ch in ignore_chars:
            num_ignore += 1
        elif isthaichar(ch):
            num_thai += 1
    num_count = len(text) - num_ignore
    return num_thai / num_count * 100

def rank(words: List[str], exclude_stopwords: bool=False) -> Counter:
    """Sort words by frequency

    :param list words: a list of words
    :param bool exclude_stopwords: exclude stopwords
    :return: Counter"""
    if not words:
        return None
    if exclude_stopwords:
        words = [word for word in words if word not in _STOPWORDS]
    return Counter(words)

def find_keyword(word_list: List[str], min_len: int=3) -> Dict[str, int]:
    """:param list word_list: a list of words
    :param int min_len: a mininum length of keywords to look for
    :return: dict"""
    word_list = rank(word_list, exclude_stopwords=True)
    return {k: v for k, v in word_list.items() if v >= min_len}

def segment(text: str, custom_dict: Trie=None) -> List[str]:
    """Dictionary-based word segmentation, using maximal matching algorithm and Thai Character Cluster
    :param str text: text to be tokenized to words
    :return: list of words, tokenized from the text"""
    if not text or not isinstance(text, str):
        return []
    if not custom_dict:
        custom_dict = DEFAULT_DICT_TRIE
    return list(_onecut(text, custom_dict))

def replace_rep_after(text: str) -> str:
    """Replace repetitions at the character level in `text` after the repetition"""
    def _replace_rep(m):
        c, cc = m.groups()
        return f'{c}{TK_REP}{len(cc) + 1}'
    re_rep = re.compile('(\\S)(\\1{2,})')
    return re_rep.sub(_replace_rep, text)

def ungroup_emoji(toks):
    """Ungroup emojis"""
    res = []
    for tok in toks:
        if emoji.emoji_count(tok) == len(tok):
            for char in tok:
                res.append(char)
        else:
            res.append(tok)
    return res

def _calc_validation_statistics(validation_results):
    """Calculate summary statistics for the validation results and
    return ``ExpectationStatistics``."""
    successful_expectations = sum((exp['success'] for exp in validation_results))
    evaluated_expectations = len(validation_results)
    unsuccessful_expectations = evaluated_expectations - successful_expectations
    success = successful_expectations == evaluated_expectations
    try:
        success_percent = successful_expectations / evaluated_expectations * 100
    except ZeroDivisionError:
        success_percent = float('nan')
    return ValidationStatistics(successful_expectations=successful_expectations, evaluated_expectations=evaluated_expectations, unsuccessful_expectations=unsuccessful_expectations, success=success, success_percent=success_percent)

def is_valid_categorical_partition_object(partition_object):
    """Tests whether a given object is a valid categorical partition object.
    :param partition_object: The partition_object to evaluate
    :return: Boolean"""
    if partition_object is None or 'weights' not in partition_object or 'values' not in partition_object:
        return False
    if len(partition_object['values']) == len(partition_object['weights']) and np.allclose(np.sum(partition_object['weights']), 1):
        return True
    return False

def is_valid_continuous_partition_object(partition_object):
    """Tests whether a given object is a valid continuous partition object.
    :param partition_object: The partition_object to evaluate
    :return: Boolean"""
    if partition_object is None or 'weights' not in partition_object or 'bins' not in partition_object:
        return False
    if 'tail_weights' in partition_object:
        if len(partition_object['tail_weights']) != 2:
            return False
        comb_weights = partition_object['tail_weights'] + partition_object['weights']
    else:
        comb_weights = partition_object['weights']
    if len(partition_object['bins']) == len(partition_object['weights']) + 1 and np.all(np.diff(partition_object['bins']) > 0) and np.allclose(np.sum(comb_weights), 1):
        return True
    return False

def continuous_partition_data(data, bins='auto', n_bins=10):
    """Convenience method for building a partition object on continuous data

    Args:
        data (list-like): The data from which to construct the estimate.
        bins (string): One of 'uniform' (for uniformly spaced bins), 'ntile' (for percentile-spaced bins), or 'auto' (for automatically spaced bins)
        n_bins (int): Ignored if bins is auto.

    Returns:
        A new partition_object::

        {
            "bins": (list) The endpoints of the partial partition of reals,
            "weights": (list) The densities of the bins implied by the partition.
        }"""
    if bins == 'uniform':
        bins = np.linspace(start=np.min(data), stop=np.max(data), num=n_bins + 1)
    elif bins == 'ntile':
        bins = np.percentile(data, np.linspace(start=0, stop=100, num=n_bins + 1))
    elif bins != 'auto':
        raise ValueError('Invalid parameter for bins argument')
    hist, bin_edges = np.histogram(data, bins, density=False)
    return {'bins': bin_edges, 'weights': hist / len(data)}

def _scipy_distribution_positional_args_from_dict(distribution, params):
    """Helper function that returns positional arguments for a scipy distribution using a dict of parameters.

    See the `cdf()` function here https://docs.scipy.org/doc/scipy/reference/generated/scipy.stats.beta.html#Methods       to see an example of scipy's positional arguments. This function returns the arguments specified by the        scipy.stat.distribution.cdf() for tha distribution.

    Args:
        distribution (string):                The scipy distribution name.
        params (dict):                A dict of named parameters.

    Raises:
        AttributeError:                If an unsupported distribution is provided."""
    params['loc'] = params.get('loc', 0)
    if 'scale' not in params:
        params['scale'] = 1
    if distribution == 'norm':
        return (params['mean'], params['std_dev'])
    elif distribution == 'beta':
        return (params['alpha'], params['beta'], params['loc'], params['scale'])
    elif distribution == 'gamma':
        return (params['alpha'], params['loc'], params['scale'])
    elif distribution == 'uniform':
        return (params['min'], params['max'])
    elif distribution == 'chi2':
        return (params['df'], params['loc'], params['scale'])
    elif distribution == 'expon':
        return (params['loc'], params['scale'])

def columns_exist(inspect_dataset):
    """This function will take a dataset and add expectations that each column present exists.

    Args:
        inspect_dataset (great_expectations.dataset): The dataset to inspect and to which to add expectations."""
    if not hasattr(inspect_dataset, 'columns'):
