def flatten(value, prefix=None):
    """Takes an arbitrary JSON(ish) object and 'flattens' it into a dict
    with values consisting of either simple types or lists of simple
    types."""
    def issimple(value):
        for item in value:
            if isinstance(item, dict) or isinstance(item, list):
                return False
        return True
    if isinstance(value, six.text_type):
        return value.encode('utf8')
    if isinstance(value, list):
        if issimple(value):
            return value
        offset = 0
        result = {}
        prefix = '%d' if prefix is None else '%s_%%d' % prefix
        for item in value:
            k = prefix % offset
            v = flatten(item, k)
            if not isinstance(v, dict):
                v = {k: v}
            result.update(v)
            offset += 1
        return result
    if isinstance(value, dict):
        result = {}
        prefix = '%s' if prefix is None else '%s_%%s' % prefix
        for k, v in six.iteritems(value):
            k = prefix % str(k)
            v = flatten(v, k)
            if not isinstance(v, dict):
                v = {k: v}
            result.update(v)
        return result
    return value

def main(argv):
    """main entry"""
    usage = 'usage: %prog --help for options'
    opts = utils.parse(argv, RULES, '.splunkrc', usage=usage)
    context = binding.connect(**opts.kwargs)
    operation = None
    kwargs = {}
    for key in RULES.keys():
        if key in opts.kwargs:
            if key == 'operation':
                operation = opts.kwargs[key]
            else:
                kwargs[key] = opts.kwargs[key]
    if not operation:
        if 'name' in kwargs:
            operation = 'list'
        else:
            operation = 'list-all'
    if operation != 'list' and operation != 'create' and (operation != 'delete') and (operation != 'list-all'):
        print('operation %s not one of list-all, list, create, delete' % operation)
        sys.exit(0)
    if 'name' not in kwargs and operation != 'list-all':
        print('operation requires a name')
        sys.exit(0)
    if operation != 'create' and operation != 'list-all':
        name = kwargs['name']
        kwargs.pop('name')
    if operation == 'list-all':
        result = context.get('saved/searches', **kwargs)
    elif operation == 'list':
        result = context.get('saved/searches/%s' % name, **kwargs)
    elif operation == 'create':
        result = context.post('saved/searches', **kwargs)
    else:
        result = context.delete('saved/searches/%s' % name, **kwargs)
    print('HTTP STATUS: %d' % result.status)
    xml_data = result.body.read().decode('utf-8')
    sys.stdout.write(xml_data)

def handler(ca_file=None):
    """Returns an HTTP request handler configured with the given ca_file."""
    def request(url, message, **kwargs):
        scheme, host, port, path = spliturl(url)
        if scheme != 'https':
            ValueError('unsupported scheme: %s' % scheme)
        connection = HTTPSConnection(host, port, ca_file)
        try:
            body = message.get('body', '')
            headers = dict(message.get('headers', []))
            connection.request(message['method'], path, body, headers)
            response = connection.getresponse()
        finally:
            connection.close()
        return {'status': response.status, 'reason': response.reason, 'headers': response.getheaders(), 'body': BytesIO(response.read())}
    return request

def get_csv_next_event_start(location, event_buffer):
    """determin the event start and end of *any* valid event"""
    start = -1
    end = -1
    event_start = event_buffer.find('\n', location + 1)
    event_end = event_buffer.find('"\n', event_start + 1)
    while event_end > 0:
        parts = event_buffer[event_start:event_end].split(',')
        try:
            int(parts[0].replace('\n', ''))
            timestamp = parts[1].replace('"', '')
            timeparts = timestamp.split('.')
            int(timeparts[0])
            int(timeparts[1])
            return (event_start, event_end)
        except:
            event_start = event_buffer.find('\n', event_end + 2)
            event_end = event_buffer.find('"\n', event_start + 1)
    return (start, end)

def get_csv_event_start(event_buffer):
    """get the event start of an event that is different (in time)from the
    adjoining event, in CSV format"""
    start, end = get_csv_next_event_start(0, event_buffer)
    if start < 0:
        return (-1, -1, '')
    print(event_buffer[start:end])
    tstart = event_buffer.find(',', start)
    tend = event_buffer.find(',', tstart + 1)
    print(event_buffer[tstart:tend])
    last_time = event_buffer[tstart + 1:tend].replace('"', '')
    while end > 0:
        start, end = get_csv_next_event_start(start, event_buffer)
        if end < 0:
            return (-1, -1, '')
        tstart = event_buffer.find(',', start)
        tend = event_buffer.find(',', tstart + 1)
        this_time = event_buffer[tstart + 1:tend].replace('"', '')
        if this_time != last_time:
            return (start, end + 1, last_time)
    return (-1, -1, '')

def get_event_start(event_buffer, event_format):
    """dispatch event start method based on event format type"""
    if event_format == 'csv':
        return get_csv_event_start(event_buffer)
    elif event_format == 'xml':
        return get_xml_event_start(event_buffer)
    else:
        return get_json_event_start(event_buffer)

def cleanup_tail(options):
    """cleanup the tail of a recovery"""
    if options.kwargs['omode'] == 'csv':
        options.kwargs['fd'].write('\n')
    elif options.kwargs['omode'] == 'xml':
        options.kwargs['fd'].write('\n</results>\n')
    else:
        options.kwargs['fd'].write('\n]\n')

def export(options, service):
    """main export method: export any number of indexes"""
    start = options.kwargs['start']
    end = options.kwargs['end']
    fixtail = options.kwargs['fixtail']
    once = True
    squery = options.kwargs['search']
    squery = squery + ' index=%s' % options.kwargs['index']
    if start != '':
        squery = squery + ' earliest_time=%s' % start
    if end != '':
        squery = squery + ' latest_time=%s' % end
    success = False
    while not success:
        result = service.get('search/jobs/export', search=squery, output_mode=options.kwargs['omode'], timeout=60, earliest_time='0.000', time_format='%s.%Q', count=0)
        if result.status != 200:
            print('warning: export job failed: %d, sleep/retry' % result.status)
            time.sleep(60)
        else:
            success = True
    while True:
        if fixtail and once:
            cleanup_tail(options)
            once = False
        content = result.body.read()
        if len(content) == 0:
            break
        options.kwargs['fd'].write(content)
        options.kwargs['fd'].write('\n')
    options.kwargs['fd'].flush()

def main():
    """main entry"""
    options = parse(sys.argv[1:], CLIRULES, '.splunkrc')
    if options.kwargs['omode'] not in OUTPUT_MODES:
        print('output mode must be one of %s, found %s' % (OUTPUT_MODES, options.kwargs['omode']))
        sys.exit(1)
    service = connect(**options.kwargs)
    if path.exists(options.kwargs['output']):
        if not options.kwargs['recover']:
            print('Export file %s exists, and recover option nor specified' % options.kwargs['output'])
