def _reloader_observer(server, app, interval):
    """Start a child process with identical commandline arguments and restart
    it as long as it exists with status code 3. Also create a lockfile and
    touch it (update mtime) every interval seconds."""
    fd, lockfile = tempfile.mkstemp(prefix='bottle-reloader.', suffix='.lock')
    os.close(fd)
    try:
        while os.path.exists(lockfile):
            args = [sys.executable] + sys.argv
            environ = os.environ.copy()
            environ['BOTTLE_CHILD'] = 'true'
            environ['BOTTLE_LOCKFILE'] = lockfile
            p = subprocess.Popen(args, env=environ)
            while p.poll() is None:
                os.utime(lockfile, None)
                time.sleep(interval)
            if p.poll() != 3:
                if os.path.exists(lockfile):
                    os.unlink(lockfile)
                sys.exit(p.poll())
            elif not server.quiet:
                print('Reloading server...')
    except KeyboardInterrupt:
        pass
    if os.path.exists(lockfile):
        os.unlink(lockfile)

def template(*args, **kwargs):
    """Get a rendered template as a string iterator.
    You can use a name, a filename or a template string as first parameter.
    Template rendering arguments can be passed as dictionaries
    or directly (as keyword arguments)."""
    tpl = args[0] if args else None
    template_adapter = kwargs.pop('template_adapter', SimpleTemplate)
    if tpl not in TEMPLATES or DEBUG:
        settings = kwargs.pop('template_settings', {})
        lookup = kwargs.pop('template_lookup', TEMPLATE_PATH)
        if isinstance(tpl, template_adapter):
            TEMPLATES[tpl] = tpl
            if settings:
                TEMPLATES[tpl].prepare(**settings)
        elif '\n' in tpl or '{' in tpl or '%' in tpl or ('$' in tpl):
            TEMPLATES[tpl] = template_adapter(source=tpl, lookup=lookup, **settings)
        else:
            TEMPLATES[tpl] = template_adapter(name=tpl, lookup=lookup, **settings)
    if not TEMPLATES[tpl]:
        abort(500, 'Template (%s) not found' % tpl)
    for dictarg in args[1:]:
        kwargs.update(dictarg)
    return TEMPLATES[tpl].render(kwargs)

def load(text, match=None):
    """This function reads a string that contains the XML of an Atom Feed, then
    returns the
    data in a native Python structure (a ``dict`` or ``list``). If you also
    provide a tag name or path to match, only the matching sub-elements are
    loaded.

    :param text: The XML text to load.
    :type text: ``string``
    :param match: A tag name or path to match (optional).
    :type match: ``string``"""
    if text is None:
        return None
    text = text.strip()
    if len(text) == 0:
        return None
    nametable = {'namespaces': [], 'names': {}}
    if sys.version_info < (3, 0, 0) and isinstance(text, unicode):
        text = text.encode('utf-8')
    root = XML(text)
    items = [root] if match is None else root.findall(match)
    count = len(items)
    if count == 0:
        return None
    elif count == 1:
        return load_root(items[0], nametable)
    else:
        return [load_root(item, nametable) for item in items]

def read_input(buf, has_header=True):
    """Read the input from the given buffer (or stdin if no buffer)
    is supplied. An optional header may be present as well"""
    if buf is None:
        buf = sys.stdin
    header = {}
    if has_header:
        last_attr = None
        while True:
            line = buf.readline()
            line = line[:-1]
            if len(line) == 0:
                break
            colon = line.find(':')
            if colon < 0:
                if last_attr:
                    header[last_attr] = header[last_attr] + '\n' + urllib.parse.unquote(line)
                else:
                    continue
            last_attr = attr = line[:colon]
            val = urllib.parse.unquote(line[colon + 1:])
            header[attr] = val
    return (buf, header)

def encode_mv(vals):
    """For multivalues, values are wrapped in '$' and separated using ';'
    Literal '$' values are represented with '$$'"""
    s = ''
    for val in vals:
        val = val.replace('$', '$$')
        if len(s) > 0:
            s += ';'
        s += '$' + val + '$'
    return s

def status_log(func, message, *args, **kwargs):
    """Emits header message, executes a callable, and echoes the return strings."""
    click.echo(message)
    log = func(*args, **kwargs)
    if log:
        out = []
        for line in log.split('\n'):
            if not line.startswith('#'):
                out.append(line)
        click.echo(black('\n'.join(out)))

