def cli(ctx, verbose, fake, install, uninstall, config):
    """legit command line interface"""
    ctx.obj = SCMRepo()
    ctx.obj.fake = fake
    ctx.obj.verbose = fake or verbose
    if install:
        do_install(ctx, verbose, fake)
        ctx.exit()
    elif uninstall:
