def itemize(data):
    """The xmltodict.unparse requires we modify the shape of the input dictionary slightly. Instead of a dict of the form:
        {'key': ['value1', 'value2']}
    We must provide:
        {'key': {'item': ['value1', 'value2']}}"""
    if isinstance(data, dict):
        ret = {}
        for key in data:
            ret[key] = itemize(data[key])
        return ret
    elif isinstance(data, list):
        return {'item': [itemize(value) for value in data]}
    else:
        return data

def daterange(start, stop, step=timedelta(days=1), inclusive=False):
    """This method will iterate from `start` to `stop` datetimes with a timedelta step of `step`
    (supports iteration forwards or backwards in time)

    :param start: start datetime
    :param stop: end datetime
    :param step: step size as a timedelta
    :param inclusive: if True, last item returned will be as step closest to `end` (or `end` if no remainder)."""
    total_step_secs = step.total_seconds()
    assert total_step_secs != 0
    if total_step_secs > 0:
        while start < stop:
            yield start
            start = start + step
    else:
        while stop < start:
            yield start
            start = start + step
    if inclusive and start == stop:
        yield start

def api_version_elb_backend(*args, **kwargs):
    """ELB and ELBV2 (Classic and Application load balancers) use the same
    hostname and url space. To differentiate them we must read the
    `Version` parameter out of the url-encoded request body. TODO: There
    has _got_ to be a better way to do this. Please help us think of
    one."""
    request = args[0]
    if hasattr(request, 'values'):
        version = request.values.get('Version')
    elif isinstance(request, AWSPreparedRequest):
        version = parse_qs(request.body).get('Version')[0]
    else:
        request.parse_request()
        version = request.querystring.get('Version')[0]
    if '2012-06-01' == version:
        return ELBResponse.dispatch(*args, **kwargs)
    elif '2015-12-01' == version:
        return ELBV2Response.dispatch(*args, **kwargs)
    else:
        raise Exception('Unknown ELB API version: {}'.format(version))

def from_buffer(string, serverEndpoint=ServerEndpoint, xmlContent=False, headers=None, config_path=None):
    """Parses the content from buffer
    :param string: Buffer value
    :param serverEndpoint: Server endpoint. This is optional
    :param xmlContent: Whether or not XML content be requested.
                    Default is 'False', which results in text content.
    :param headers: Request headers to be sent to the tika reset server, should
                    be a dictionary. This is optional
    :return:"""
    headers = headers or {}
    headers.update({'Accept': 'application/json'})
    if not xmlContent:
        status, response = callServer('put', serverEndpoint, '/rmeta/text', string, headers, False, config_path=config_path)
    else:
        status, response = callServer('put', serverEndpoint, '/rmeta/xml', string, headers, False, config_path=config_path)
    return _parse((status, response))

def _parse(jsonOutput):
    """Parses JSON response from Tika REST API server
    :param jsonOutput: JSON output from Tika Server
    :return: a dictionary having 'metadata' and 'content' values"""
    parsed = {}
    if not jsonOutput:
        return parsed
    parsed['status'] = jsonOutput[0]
    if jsonOutput[1] == None or jsonOutput[1] == '':
        return parsed
    realJson = json.loads(jsonOutput[1])
    content = ''
    for js in realJson:
        if 'X-TIKA:content' in js:
            content += js['X-TIKA:content']
    if content == '':
        content = None
    parsed['content'] = content
    parsed['metadata'] = {}
    for js in realJson:
        for n in js:
            if n != 'X-TIKA:content':
                if n in parsed['metadata']:
                    if not isinstance(parsed['metadata'][n], list):
                        parsed['metadata'][n] = [parsed['metadata'][n]]
                    parsed['metadata'][n].append(js[n])
                else:
                    parsed['metadata'][n] = js[n]
    return parsed

def runCommand(cmd, option, urlOrPaths, port, outDir=None, serverHost=ServerHost, tikaServerJar=TikaServerJar, verbose=Verbose, encode=EncodeUtf8):
    """Run the Tika command by calling the Tika server and return results in JSON format (or plain text).
    :param cmd: a command from set ``{'parse', 'detect', 'language', 'translate', 'config'}``
    :param option:
    :param urlOrPaths:
    :param port:
    :param outDir:
    :param serverHost:
    :param tikaServerJar:
    :param verbose:
    :param encode:
    :return: response for the command, usually a ``dict``"""
    if (cmd in 'parse' or cmd in 'detect') and (urlOrPaths == [] or urlOrPaths == None):
        log.exception('No URLs/paths specified.')
        raise TikaException('No URLs/paths specified.')
    serverEndpoint = 'http://' + serverHost + ':' + port
    if cmd == 'parse':
        return parseAndSave(option, urlOrPaths, outDir, serverEndpoint, verbose, tikaServerJar)
    elif cmd == 'detect':
        return detectType(option, urlOrPaths, serverEndpoint, verbose, tikaServerJar)
    elif cmd == 'language':
        return detectLang(option, urlOrPaths, serverEndpoint, verbose, tikaServerJar)
    elif cmd == 'translate':
        return doTranslate(option, urlOrPaths, serverEndpoint, verbose, tikaServerJar)
    elif cmd == 'config':
        status, resp = getConfig(option, serverEndpoint, verbose, tikaServerJar)
        return resp
    else:
        log.exception('Bad args')
        raise TikaException('Bad args')

def getPaths(urlOrPaths):
    """Determines if the given URL in urlOrPaths is a URL or a file or directory. If it's
    a directory, it walks the directory and then finds all file paths in it, and ads them
    too. If it's a file, it adds it to the paths. If it's a URL it just adds it to the path.
    :param urlOrPaths: the url or path to be scanned
    :return: ``list`` of paths"""
    if isinstance(urlOrPaths, basestring):
        urlOrPaths = [urlOrPaths]
    paths = []
    for eachUrlOrPaths in urlOrPaths:
        if os.path.isdir(eachUrlOrPaths):
            for root, directories, filenames in walk(eachUrlOrPaths):
                for filename in filenames:
                    paths.append(os.path.join(root, filename))
        else:
            paths.append(eachUrlOrPaths)
    return paths

def detectType1(option, urlOrPath, serverEndpoint=ServerEndpoint, verbose=Verbose, tikaServerJar=TikaServerJar, responseMimeType='text/plain', services={'type': '/detect/stream'}, config_path=None):
