def compile(stream_spec, cmd='ffmpeg', overwrite_output=False):
    """Build command-line for invoking ffmpeg.

    The :meth:`run` function uses this to build the commnad line
    arguments and should work in most cases, but calling this function
    directly is useful for debugging or if you need to invoke ffmpeg
    manually for whatever reason.

    This is the same as calling :meth:`get_args` except that it also
    includes the ``ffmpeg`` command as the first argument."""
    if isinstance(cmd, basestring):
        cmd = [cmd]
    elif type(cmd) != list:
        cmd = list(cmd)
    return cmd + get_args(stream_spec, overwrite_output=overwrite_output)

def input(filename, **kwargs):
    """Input file URL (ffmpeg ``-i`` option)

    Any supplied kwargs are passed to ffmpeg verbatim (e.g. ``t=20``,
    ``f='mp4'``, ``acodec='pcm'``, etc.).

    To tell ffmpeg to read from stdin, use ``pipe:`` as the filename.

    Official documentation: `Main options <https://ffmpeg.org/ffmpeg.html#Main-options>`__"""
    kwargs['filename'] = filename
    fmt = kwargs.pop('f', None)
    if fmt:
        if 'format' in kwargs:
            raise ValueError("Can't specify both `format` and `f` kwargs")
        kwargs['format'] = fmt
    return InputNode(input.__name__, kwargs=kwargs).stream()

def show_progress(total_duration):
    """Create a unix-domain socket to watch progress and render tqdm
    progress bar."""
    with tqdm(total=round(total_duration, 2)) as bar:
        def handler(key, value):
            if key == 'out_time_ms':
                time = round(float(value) / 1000000.0, 2)
                bar.update(time - bar.n)
            elif key == 'progress' and value == 'end':
                bar.update(bar.total - bar.n)
        with _watch_progress(handler) as socket_filename:
            yield socket_filename

def filter_(stream_spec, filter_name, *args, **kwargs):
    """Alternate name for ``filter``, so as to not collide with the
    built-in python ``filter`` operator."""
    return filter(stream_spec, filter_name, *args, **kwargs)

def setpts(stream, expr):
    """Change the PTS (presentation timestamp) of the input frames.

    Args:
        expr: The expression which is evaluated for each frame to construct its timestamp.

    Official documentation: `setpts, asetpts <https://ffmpeg.org/ffmpeg-filters.html#setpts_002c-asetpts>`__"""
    return FilterNode(stream, setpts.__name__, args=[expr]).stream()

def colorchannelmixer(stream, *args, **kwargs):
    """Adjust video input frames by re-mixing color channels.

    Official documentation: `colorchannelmixer <https://ffmpeg.org/ffmpeg-filters.html#colorchannelmixer>`__"""
    return FilterNode(stream, colorchannelmixer.__name__, kwargs=kwargs).stream()

def _recursive_repr(item):
    """Hack around python `repr` to deterministically represent dictionaries.

    This is able to represent more things than json.dumps, since it does not require things to be JSON serializable
    (e.g. datetimes)."""
    if isinstance(item, basestring):
        result = str(item)
    elif isinstance(item, list):
        result = '[{}]'.format(', '.join([_recursive_repr(x) for x in item]))
    elif isinstance(item, dict):
        kv_pairs = ['{}: {}'.format(_recursive_repr(k), _recursive_repr(item[k])) for k in sorted(item)]
        result = '{' + ', '.join(kv_pairs) + '}'
    else:
        result = repr(item)
    return result

def escape_chars(text, chars):
    """Helper function to escape uncomfortable characters."""
    text = str(text)
    chars = list(set(chars))
    if '\\' in chars:
        chars.remove('\\')
        chars.insert(0, '\\')
    for ch in chars:
        text = text.replace(ch, '\\' + ch)
    return text

def convert_kwargs_to_cmd_line_args(kwargs):
    """Helper function to build command line arguments out of dict."""
    args = []
    for k in sorted(kwargs.keys()):
        v = kwargs[k]
        args.append('-{}'.format(k))
        if v is not None:
            args.append('{}'.format(v))
    return args

def flatten_dictionary(input, sep='.', prefix=None):
    """Produces iterator of pairs where the first value is
    the joined key names and the second value is the value
    associated with the lowest level key. For example::

      {'a': {'b': 10},
       'c': 20,
       }

    produces::

      [('a.b', 10), ('c', 20)]"""
    for name, value in sorted(input.items()):
        fullname = sep.join(filter(None, [prefix, name]))
        if isinstance(value, dict):
            for result in flatten_dictionary(value, sep, fullname):
                yield result
        else:
            yield (fullname, value)

def match_process(pid, name, cmdline, exe, cfg):
    """Decides whether a process matches with a given process descriptor

    :param pid: process pid
    :param exe: process executable
    :param name: process name
    :param cmdline: process cmdline
    :param cfg: the dictionary from processes that describes with the
        process group we're testing for
    :return: True if it matches
    :rtype: bool"""
    if cfg['selfmon'] and pid == os.getpid():
        return True
    for exe_re in cfg['exe']:
        if exe_re.search(exe):
            return True
    for name_re in cfg['name']:
        if name_re.search(name):
            return True
    for cmdline_re in cfg['cmdline']:
        if cmdline_re.search(' '.join(cmdline)):
            return True
    return False

def signal_to_exception(signum, frame):
    """Called by the timeout alarm during the collector run time"""
    if signum == signal.SIGALRM:
        raise SIGALRMException()
    if signum == signal.SIGHUP:
        raise SIGHUPException()
    if signum == signal.SIGUSR1:
        raise SIGUSR1Exception()
    if signum == signal.SIGUSR2:
        raise SIGUSR2Exception()
    raise SignalException(signum)

def load_modules_from_path(path):
    """Import all modules from the given directory"""
    if path[-1:] != '/':
        path += '/'
    if not os.path.exists(path):
        raise OSError('Directory does not exist: %s' % path)
    sys.path.append(path)
    for f in os.listdir(path):
        if len(f) > 3 and f[-3:] == '.py':
            modname = f[:-3]
            __import__(modname, globals(), locals(), ['*'])

def sanitize_word(s):
    """Remove non-alphanumerical characters from metric word.
    And trim excessive underscores."""
    s = re.sub('[^\\w-]+', '_', s)
    s = re.sub('__+', '_', s)
    return s.strip('_')

def str_to_bool(value):
    """Converts string truthy/falsey strings to a bool
    Empty strings are false"""
    if isinstance(value, basestring):
        value = value.strip().lower()
        if value in ['true', 't', 'yes', 'y']:
            return True
        elif value in ['false', 'f', 'no', 'n', '']:
            return False
        else:
            raise NotImplementedError('Unknown bool %s' % value)
    return value

def parse_slab_stats(slab_stats):
    """Convert output from memcached's `stats slabs` into a Python dict.

        Newlines are returned by memcached along with carriage returns
        (i.e. '
    ').

        >>> parse_slab_stats(
                "STAT 1:chunk_size 96
    STAT 1:chunks_per_page 10922
    STAT "
                "active_slabs 1
    STAT total_malloced 1048512
    END
    ")
        {
            'slabs': {
                1: {
                    'chunk_size': 96,
                    'chunks_per_page': 10922,
                    # ...
                },
            },
            'active_slabs': 1,
            'total_malloced': 1048512,
        }
    """
    stats_dict = {'slabs': defaultdict(lambda: {})}
    for line in slab_stats.splitlines():
        if line == 'END':
            break
        cmd, key, value = line.split(' ')
        if cmd != 'STAT':
            continue
        if ':' not in key:
            stats_dict[key] = int(value)
            continue
        slab, key = key.split(':')
        stats_dict['slabs'][int(slab)][key] = int(value)
    return stats_dict

def dict_to_paths(dict_):
    """Convert a dict to metric paths.

    >>> dict_to_paths({'foo': {'bar': 1}, 'baz': 2})
    {
        'foo.bar': 1,
        'baz': 2,
    }"""
    metrics = {}
    for k, v in dict_.iteritems():
        if isinstance(v, dict):
            submetrics = dict_to_paths(v)
            for subk, subv in submetrics.iteritems():
                metrics['.'.join([str(k), str(subk)])] = subv
        else:
            metrics[k] = v
    return metrics

def pkgPath(root, path, rpath='/'):
    """Package up a path recursively"""
    global data_files
    if not os.path.exists(path):
        return
    files = []
    for spath in os.listdir(path):
        if spath == 'test':
            continue
        subpath = os.path.join(path, spath)
        spath = os.path.join(rpath, spath)
        if os.path.isfile(subpath):
            files.append(subpath)
        if os.path.isdir(subpath):
            pkgPath(root, subpath, spath)
    data_files.append((root + rpath, files))

def load_include_path(paths):
    """Scan for and add paths to the include path"""
    for path in paths:
        if not os.path.isdir(path):
            continue
        if path not in sys.path:
            sys.path.insert(1, path)
        for f in os.listdir(path):
            fpath = os.path.join(path, f)
            if os.path.isdir(fpath):
                load_include_path([fpath])

def load_dynamic_class(fqn, subclass):
    """Dynamically load fqn class and verify it's a subclass of subclass"""
    if not isinstance(fqn, basestring):
        return fqn
    cls = load_class_from_name(fqn)
    if cls == subclass or not issubclass(cls, subclass):
        raise TypeError('%s is not a valid %s' % (fqn, subclass.__name__))
    return cls

def load_handlers(config, handler_names):
    """Load handlers"""
    handlers = []
    if isinstance(handler_names, basestring):
        handler_names = [handler_names]
    for handler in handler_names:
        logger.debug('Loading Handler %s', handler)
        try:
            cls = load_dynamic_class(handler, Handler)
            cls_name = cls.__name__
            handler_config = configobj.ConfigObj()
            handler_config.merge(config['handlers']['default'])
            if cls_name in config['handlers']:
                handler_config.merge(config['handlers'][cls_name])
            if 'handlers_config_path' in config['server']:
                configfile = os.path.join(config['server']['handlers_config_path'], cls_name) + '.conf'
                if os.path.exists(configfile):
                    handler_config.merge(configobj.ConfigObj(configfile))
            h = cls(handler_config)
            handlers.append(h)
        except (ImportError, SyntaxError):
            logger.warning('Failed to load handler %s. %s', handler, traceback.format_exc())
            continue
    return handlers

def load_collectors_from_entry_point(path):
    """Load collectors that were installed into an entry_point."""
    collectors = {}
    for ep in pkg_resources.iter_entry_points(path):
        try:
            mod = ep.load()
        except Exception:
            logger.error('Failed to import entry_point: %s. %s', ep.name, traceback.format_exc())
        else:
            collectors.update(get_collectors_from_module(mod))
    return collectors

def get_collectors_from_module(mod):
    """Locate all of the collector classes within a given module"""
    for attrname in dir(mod):
        attr = getattr(mod, attrname)
        if inspect.isclass(attr) and issubclass(attr, Collector) and (attr != Collector):
            if attrname.startswith('parent_'):
                continue
            fqcn = '.'.join([mod.__name__, attrname])
            try:
                cls = load_dynamic_class(fqcn, Collector)
                yield (cls.__name__, cls)
            except Exception:
                logger.error('Failed to load Collector: %s. %s', fqcn, traceback.format_exc())
                continue

def initialize_collector(cls, name=None, configfile=None, handlers=[]):
    """Initialize collector"""
    collector = None
    try:
        collector = cls(name=name, configfile=configfile, handlers=handlers)
    except Exception:
        logger.error('Failed to initialize Collector: %s. %s', cls.__name__, traceback.format_exc())
    return collector

def to_xml(ele, encoding='UTF-8', pretty_print=False):
    """Convert and return the XML for an *ele* (:class:`~xml.etree.ElementTree.Element`) with specified *encoding*."""
    xml = etree.tostring(ele, encoding=encoding, pretty_print=pretty_print)
    if sys.version < '3':
        return xml if xml.startswith('<?xml') else '<?xml version="1.0" encoding="%s"?>%s' % (encoding, xml)
    else:
        return xml.decode('UTF-8') if xml.startswith(b'<?xml') else '<?xml version="1.0" encoding="%s"?>%s' % (encoding, xml.decode('UTF-8'))

def to_ele(x):
    """Convert and return the :class:`~xml.etree.ElementTree.Element` for the XML document *x*. If *x* is already an :class:`~xml.etree.ElementTree.Element` simply returns that."""
    if sys.version < '3':
        return x if etree.iselement(x) else etree.fromstring(x, parser=parser)
    else:
        return x if etree.iselement(x) else etree.fromstring(x.encode('UTF-8'), parser=parser)

def parse_root(raw):
    """Efficiently parses the root element of a *raw* XML document, returning a tuple of its qualified name and attribute dictionary."""
    if sys.version < '3':
        fp = StringIO(raw)
    else:
        fp = BytesIO(raw.encode('UTF-8'))
    for event, element in etree.iterparse(fp, events=('start',)):
        return (element.tag, element.attrib)

def validated_element(x, tags=None, attrs=None):
    """Checks if the root element of an XML document or Element meets the supplied criteria.

    *tags* if specified is either a single allowable tag name or sequence of allowable alternatives

    *attrs* if specified is a sequence of required attributes, each of which may be a sequence of several allowable alternatives

    Raises :exc:`XMLError` if the requirements are not met."""
    ele = to_ele(x)
    if tags:
        if isinstance(tags, (str, bytes)):
            tags = [tags]
        if ele.tag not in tags:
            raise XMLError('Element [%s] does not meet requirement' % ele.tag)
    if attrs:
        for req in attrs:
            if isinstance(req, (str, bytes)):
                req = [req]
            for alt in req:
                if alt in ele.attrib:
                    break
            else:
                raise XMLError('Element [%s] does not have required attributes' % ele.tag)
    return ele

def _get_valid_with_defaults_modes(capabilities):
    """Reference: https://tools.ietf.org/html/rfc6243#section-4.3"""
    capability = capabilities[':with-defaults']
    try:
        valid_modes = [capability.parameters['basic-mode']]
    except KeyError:
        raise WithDefaultsError("Invalid 'with-defaults' capability URI advertised by the server; missing 'basic-mode' parameter")
    try:
        also_supported = capability.parameters['also-supported']
    except KeyError:
        return valid_modes
    valid_modes.extend(also_supported.split(','))
    return valid_modes

def one_of(*args):
    """Verifies that only one of the arguments is not None"""
    for i, arg in enumerate(args):
        if arg is not None:
            for argh in args[i + 1:]:
                if argh is not None:
                    raise OperationError('Too many parameters')
            else:
                return
    raise OperationError('Insufficient parameters')

def create_design_matrix_2(Z, data, Y_len, lag_no):
    """For Python 2.7 - cythonized version only works for 3.5"""
    row_count = 1
    for lag in range(1, lag_no + 1):
        for reg in range(Y_len):
            Z[row_count, :] = data[reg][lag_no - lag:-lag]
            row_count += 1
    return Z

def version(package, encoding='utf-8'):
    """Obtain the packge version from a python file e.g. pkg/__init__.py
    See <https://packaging.python.org/en/latest/single_source_version.html>."""
    path = os.path.join(os.path.dirname(__file__), package, '__init__.py')
    with io.open(path, encoding=encoding) as fp:
        version_info = fp.read()
    version_match = re.search('^__version__ = [\'"]([^\'"]*)[\'"]', version_info, re.M)
    if not version_match:
        raise RuntimeError('Unable to find version string.')
    return version_match.group(1)

def load_hashes(filename):
    """Load the hashes dict from the hashfile"""
    hashes = {}
    try:
        with open(filename, 'r') as cython_hash_file:
            for hash_record in cython_hash_file:
                filename, header_hash, cython_hash, gen_file_hash = hash_record.split()
                hashes[filename] = (header_hash, cython_hash, gen_file_hash)
    except (KeyError, ValueError, AttributeError, IOError):
        hashes = {}
    return hashes

def save_hashes(hashes, filename):
    """Save the hashes dict to the hashfile"""
    with open(filename, 'w') as cython_hash_file:
        for key, value in hashes.items():
            cython_hash_file.write('%s %s %s %s\n' % (key, value[0], value[1], value[2]))

def clean_path(path):
    """Clean the path"""
    path = path.replace(os.sep, '/')
    if path.startswith('./'):
        path = path[2:]
    return path

def get_hash_tuple(header_path, cython_path, gen_file_path):
    """Get the hashes from the given files"""
    header_hash = sha1_of_file(header_path) if os.path.exists(header_path) else 'NA'
    from_hash = sha1_of_file(cython_path)
    to_hash = sha1_of_file(gen_file_path) if os.path.exists(gen_file_path) else 'NA'
    return (header_hash, from_hash, to_hash)

def standard_reader_routine(reader, filename, attrs=None):
    """Use a given reader from the ``READERS`` mapping in the common VTK reading
    pipeline routine.

    Parameters
    ----------
    reader : vtkReader
        Any instantiated VTK reader class

    filename : str
        The string filename to the data file to read.

    attrs : dict, optional
        A dictionary of attributes to call on the reader. Keys of dictionary are
        the attribute/method names and values are the arguments passed to those
        calls. If you do not have any attributes to call, pass ``None`` as the
        value."""
    if attrs is None:
        attrs = {}
    if not isinstance(attrs, dict):
        raise TypeError('Attributes must be a dictionary of name and arguments.')
    reader.SetFileName(filename)
    for name, args in attrs.items():
        attr = getattr(reader, name)
        if args is not None:
            if not isinstance(args, (list, tuple)):
                args = [args]
            attr(*args)
        else:
            attr()
    reader.Update()
    return vtki.wrap(reader.GetOutputDataObject(0))

def read_texture(filename, attrs=None):
    """Loads a ``vtkTexture`` from an image file."""
    filename = os.path.abspath(os.path.expanduser(filename))
    try:
        reader = get_reader(filename)
        image = standard_reader_routine(reader, filename, attrs=attrs)
        return vtki.image_to_texture(image)
    except KeyError:
        pass
    return vtki.numpy_to_texture(imageio.imread(filename))

def read_exodus(filename, animate_mode_shapes=True, apply_displacements=True, displacement_magnitude=1.0, enabled_sidesets=None):
    """Read an ExodusII file (``'.e'`` or ``'.exo'``)"""
    reader = vtk.vtkExodusIIReader()
    reader.SetFileName(filename)
    reader.UpdateInformation()
    reader.SetAnimateModeShapes(animate_mode_shapes)
    reader.SetApplyDisplacements(apply_displacements)
    reader.SetDisplacementMagnitude(displacement_magnitude)
    if enabled_sidesets is None:
        enabled_sidesets = list(range(reader.GetNumberOfSideSetArrays()))
    for sideset in enabled_sidesets:
        if isinstance(sideset, int):
            name = reader.GetSideSetArrayName(sideset)
        elif isinstance(sideset, str):
            name = sideset
        else:
            raise ValueError('Could not parse sideset ID/name: {}'.format(sideset))
        reader.SetSideSetArrayStatus(name, 1)
    reader.Update()
    return vtki.wrap(reader.GetOutput())

def _remove_mapper_from_plotter(plotter, actor, reset_camera):
    """removes this actor's mapper from the given plotter's _scalar_bar_mappers"""
    try:
        mapper = actor.GetMapper()
    except AttributeError:
        return
    for name in list(plotter._scalar_bar_mappers.keys()):
        try:
            plotter._scalar_bar_mappers[name].remove(mapper)
        except ValueError:
            pass
        if len(plotter._scalar_bar_mappers[name]) < 1:
            slot = plotter._scalar_bar_slot_lookup.pop(name)
            plotter._scalar_bar_mappers.pop(name)
            plotter._scalar_bar_ranges.pop(name)
            plotter.remove_actor(plotter._scalar_bar_actors.pop(name), reset_camera=reset_camera)
            plotter._scalar_bar_slots.add(slot)
    return

def point_scalar(mesh, name):
    """Returns point scalars of a vtk object"""
    vtkarr = mesh.GetPointData().GetArray(name)
    if vtkarr:
        if isinstance(vtkarr, vtk.vtkBitArray):
            vtkarr = vtk_bit_array_to_char(vtkarr)
        return vtk_to_numpy(vtkarr)

def cell_scalar(mesh, name):
    """Returns cell scalars of a vtk object"""
    vtkarr = mesh.GetCellData().GetArray(name)
    if vtkarr:
        if isinstance(vtkarr, vtk.vtkBitArray):
            vtkarr = vtk_bit_array_to_char(vtkarr)
        return vtk_to_numpy(vtkarr)

def trans_from_matrix(matrix):
    """Convert a vtk matrix to a numpy.ndarray"""
    t = np.zeros((4, 4))
    for i in range(4):
        for j in range(4):
            t[i, j] = matrix.GetElement(i, j)
    return t

def wrap(vtkdataset):
    """This is a convenience method to safely wrap any given VTK data object
    to its appropriate ``vtki`` data object."""
    wrappers = {'vtkUnstructuredGrid': vtki.UnstructuredGrid, 'vtkRectilinearGrid': vtki.RectilinearGrid, 'vtkStructuredGrid': vtki.StructuredGrid, 'vtkPolyData': vtki.PolyData, 'vtkImageData': vtki.UniformGrid, 'vtkStructuredPoints': vtki.UniformGrid, 'vtkMultiBlockDataSet': vtki.MultiBlock}
    key = vtkdataset.GetClassName()
    try:
        wrapped = wrappers[key](vtkdataset)
    except:
        logging.warning('VTK data type ({}) is not currently supported by vtki.'.format(key))
        return vtkdataset
    return wrapped

def numpy_to_texture(image):
    """Convert a NumPy image array to a vtk.vtkTexture"""
    if not isinstance(image, np.ndarray):
        raise TypeError('Unknown input type ({})'.format(type(image)))
    if image.ndim != 3 or image.shape[2] != 3:
        raise AssertionError('Input image must be nn by nm by RGB')
    grid = vtki.UniformGrid((image.shape[1], image.shape[0], 1))
    grid.point_arrays['Image'] = np.flip(image.swapaxes(0, 1), axis=1).reshape((-1, 3), order='F')
    grid.set_active_scalar('Image')
    return image_to_texture(grid)

def is_inside_bounds(point, bounds):
    """Checks if a point is inside a set of bounds. This is implemented
    through recursion so that this is N-dimensional."""
    if isinstance(point, (int, float)):
        point = [point]
    if isinstance(point, collections.Iterable) and (not isinstance(point, collections.deque)):
        if len(bounds) < 2 * len(point) or len(bounds) % 2 != 0:
            raise AssertionError('Bounds mismatch point dimensionality')
        point = collections.deque(point)
        bounds = collections.deque(bounds)
        return is_inside_bounds(point, bounds)
    if not isinstance(point, collections.deque):
        raise TypeError('Unknown input data type ({}).'.format(type(point)))
    if len(point) < 1:
        return True
    p = point.popleft()
    lower, upper = (bounds.popleft(), bounds.popleft())
    if lower <= p <= upper:
        return is_inside_bounds(point, bounds)
    return False

def close_all():
    """Close all open/active plotters"""
    for key, p in _ALL_PLOTTERS.items():
        p.close()
    _ALL_PLOTTERS.clear()
    return True

def opacity_transfer_function(key, n_colors):
    """Get the opacity transfer function results: range from 0 to 255
    """
    transfer_func = {'linear': np.linspace(0, 255, n_colors, dtype=np.uint8), 'linear_r': np.linspace(0, 255, n_colors, dtype=np.uint8)[::-1], 'geom': np.geomspace(1e-06, 255, n_colors, dtype=np.uint8), 'geom_r': np.geomspace(255, 1e-06, n_colors, dtype=np.uint8)}
    try:
        return transfer_func[key]
    except KeyError:
        raise KeyError('opactiy transfer function ({}) unknown.'.format(key))

def system_supports_plotting():
    """Check if x server is running

    Returns
    -------
    system_supports_plotting : bool
        True when on Linux and running an xserver.  Returns None when
        on a non-linux platform."""
    try:
        if os.environ['ALLOW_PLOTTING'].lower() == 'true':
            return True
    except KeyError:
        pass
    try:
        p = Popen(['xset', '-q'], stdout=PIPE, stderr=PIPE)
        p.communicate()
        return p.returncode == 0
    except:
        return False

def parse_color(color):
    """Parses color into a vtk friendly rgb list"""
    if color is None:
        color = rcParams['color']
    if isinstance(color, str):
        return vtki.string_to_rgb(color)
    elif len(color) == 3:
        return color
    else:
        raise Exception("\n    Invalid color input\n    Must ba string, rgb list, or hex color string.  For example:\n        color='white'\n        color='w'\n        color=[1, 1, 1]\n        color='#FFFFFF'")

def plot_compare_four(data_a, data_b, data_c, data_d, disply_kwargs=None, plotter_kwargs=None, show_kwargs=None, screenshot=None, camera_position=None, outline=None, outline_color='k', labels=('A', 'B', 'C', 'D')):
    """Plot a 2 by 2 comparison of data objects. Plotting parameters and camera
    positions will all be the same."""
    datasets = [[data_a, data_b], [data_c, data_d]]
    labels = [labels[0:2], labels[2:4]]
    if plotter_kwargs is None:
        plotter_kwargs = {}
    if disply_kwargs is None:
        disply_kwargs = {}
    if show_kwargs is None:
        show_kwargs = {}
    p = vtki.Plotter(shape=(2, 2), **plotter_kwargs)
    for i in range(2):
        for j in range(2):
            p.subplot(i, j)
            p.add_mesh(datasets[i][j], **disply_kwargs)
            p.add_text(labels[i][j])
            if is_vtki_obj(outline):
                p.add_mesh(outline, color=outline_color)
            if camera_position is not None:
                p.camera_position = camera_position
    return p.show(screenshot=screenshot, **show_kwargs)

def hex_to_rgb(h):
    """Returns 0 to 1 rgb from a hex list or tuple"""
    h = h.lstrip('#')
    return tuple((int(h[i:i + 2], 16) / 255.0 for i in (0, 2, 4)))

def string_to_rgb(string):
    """Converts a literal color string (i.e. white) to a color rgb.  Also accepts
    hex strings or single characters from the following list.

        b: blue
        g: green
        r: red
        c: cyan
        m: magenta
        y: yellow
        k: black
        w: white"""
    if len(string) == 1:
        if string.lower() not in color_char_to_word:
            raise ValueError('Single character string must be one of the following:\n%s' % str(color_char_to_word.keys()))
        colorhex = hexcolors[color_char_to_word[string.lower()]]
    elif string.lower() in hexcolors:
        colorhex = hexcolors[string.lower()]
    else:
        try:
            return hex_to_rgb(string)
        except:
            raise ValueError('Invalid color string or hex string.')
    return hex_to_rgb(colorhex)

def get_object_id(obj):
    """Get object identifier"""
    try:
        idx = objIds.index(obj)
        return idx + 1
    except ValueError:
        objIds.append(obj)
        return len(objIds)

def dump_color_array(dataset_dir, data_dir, color_array_info, root=None, compress=True):
    """Dump vtkjs color array"""
    if root is None:
        root = {}
    root['pointData'] = {'vtkClass': 'vtkDataSetAttributes', 'activeGlobalIds': -1, 'activeNormals': -1, 'activePedigreeIds': -1, 'activeScalars': -1, 'activeTCoords': -1, 'activeTensors': -1, 'activeVectors': -1, 'arrays': []}
    root['cellData'] = {'vtkClass': 'vtkDataSetAttributes', 'activeGlobalIds': -1, 'activeNormals': -1, 'activePedigreeIds': -1, 'activeScalars': -1, 'activeTCoords': -1, 'activeTensors': -1, 'activeVectors': -1, 'arrays': []}
    root['fieldData'] = {'vtkClass': 'vtkDataSetAttributes', 'activeGlobalIds': -1, 'activeNormals': -1, 'activePedigreeIds': -1, 'activeScalars': -1, 'activeTCoords': -1, 'activeTensors': -1, 'activeVectors': -1, 'arrays': []}
