def axis_rotation(points, angle, inplace=False, deg=True, axis='z'):
    """Rotates points angle ang (in deg) about an axis"""
    axis = axis.lower()
    if not inplace:
        points = points.copy()
    if deg:
        angle *= np.pi / 180
    if axis == 'x':
        y = points[:, 1] * np.cos(angle) - points[:, 2] * np.sin(angle)
        z = points[:, 1] * np.sin(angle) + points[:, 2] * np.cos(angle)
        points[:, 1] = y
        points[:, 2] = z
    elif axis == 'y':
        x = points[:, 0] * np.cos(angle) + points[:, 2] * np.sin(angle)
        z = -points[:, 0] * np.sin(angle) + points[:, 2] * np.cos(angle)
        points[:, 0] = x
        points[:, 2] = z
    elif axis == 'z':
        x = points[:, 0] * np.cos(angle) - points[:, 1] * np.sin(angle)
        y = points[:, 0] * np.sin(angle) + points[:, 1] * np.cos(angle)
        points[:, 0] = x
        points[:, 1] = y
    else:
        raise Exception('invalid axis.  Must be either "x", "y", or "z"')
    if not inplace:
        return points

def transaction_retry(max_retries=1):
    """Decorator for methods doing database operations.

    If the database operation fails, it will retry the operation
    at most ``max_retries`` times."""
    def _outer(fun):
        @wraps(fun)
        def _inner(*args, **kwargs):
            _max_retries = kwargs.pop('exception_retry_count', max_retries)
            for retries in count(0):
                try:
                    return fun(*args, **kwargs)
                except Exception:
                    if retries >= _max_retries:
                        raise
                    try:
                        rollback_unless_managed()
                    except Exception:
                        pass
        return _inner
    return _outer

def respect_language(language):
    """Context manager that changes the current translation language for
    all code inside the following block.

    Can e.g. be used inside tasks like this::

        from celery import task
        from djcelery.common import respect_language

        @task
        def my_task(language=None):
            with respect_language(language):
                pass"""
    if language:
        prev = translation.get_language()
        translation.activate(language)
        try:
            yield
        finally:
            translation.activate(prev)
    else:
        yield

def autodiscover():
    """Include tasks for all applications in ``INSTALLED_APPS``."""
    global _RACE_PROTECTION
    if _RACE_PROTECTION:
        return
    _RACE_PROTECTION = True
    try:
        return filter(None, [find_related_module(app, 'tasks') for app in settings.INSTALLED_APPS])
    finally:
        _RACE_PROTECTION = False

def find_related_module(app, related_name):
    """Given an application name and a module name, tries to find that
    module in the application."""
    try:
        app_path = importlib.import_module(app).__path__
    except ImportError as exc:
        warn('Autodiscover: Error importing %s.%s: %r' % (app, related_name, exc))
        return
    except AttributeError:
        return
    try:
        f, _, _ = imp.find_module(related_name, app_path)
        f and f.close()
    except ImportError:
        return
    return importlib.import_module('{0}.{1}'.format(app, related_name))

def python_2_unicode_compatible(cls):
    """Taken from Django project (django/utils/encoding.py) & modified a bit to
    always have __unicode__ method available."""
    if '__str__' not in cls.__dict__:
        raise ValueError("@python_2_unicode_compatible cannot be applied to %s because it doesn't define __str__()." % cls.__name__)
    cls.__unicode__ = cls.__str__
    if PY2:
        cls.__str__ = lambda self: self.__unicode__().encode('utf-8')
    return cls

def naturaldate(date, include_seconds=False):
    """Convert datetime into a human natural date string."""
    if not date:
        return ''
    right_now = now()
    today = datetime(right_now.year, right_now.month, right_now.day, tzinfo=right_now.tzinfo)
    delta = right_now - date
    delta_midnight = today - date
    days = delta.days
    hours = delta.seconds // 3600
    minutes = delta.seconds // 60
    seconds = delta.seconds
    if days < 0:
        return _('just now')
    if days == 0:
        if hours == 0:
            if minutes > 0:
                return ungettext(_('{minutes} minute ago'), _('{minutes} minutes ago'), minutes).format(minutes=minutes)
            else:
                if include_seconds and seconds:
                    return ungettext(_('{seconds} second ago'), _('{seconds} seconds ago'), seconds).format(seconds=seconds)
                return _('just now')
        else:
            return ungettext(_('{hours} hour ago'), _('{hours} hours ago'), hours).format(hours=hours)
    if delta_midnight.days == 0:
        return _('yesterday at {time}').format(time=date.strftime('%H:%M'))
    count = 0
    for chunk, pluralizefun in OLDER_CHUNKS:
        if days >= chunk:
            count = int(round((delta_midnight.days + 1) / chunk, 0))
            fmt = pluralizefun(count)
            return fmt.format(num=count)

def task_view(task):
    """Decorator turning any task into a view that applies the task
    asynchronously. Keyword arguments (via URLconf, etc.) will
    supercede GET or POST parameters when there are conflicts.

    Returns a JSON dictionary containing the keys ``ok``, and
        ``task_id``."""
    def _applier(request, **options):
        kwargs = request.POST if request.method == 'POST' else request.GET
        kwargs = {k: v for k, v in items(kwargs)}
        if options:
            kwargs.update(options)
        result = task.apply_async(kwargs=kwargs)
        return JsonResponse({'ok': 'true', 'task_id': result.task_id})
    return _applier

def apply(request, task_name):
    """View applying a task.

    **Note:** Please use this with caution. Preferably you shouldn't make this
        publicly accessible without ensuring your code is safe!"""
    try:
        task = tasks[task_name]
    except KeyError:
        raise Http404('apply: no such task')
    return task_view(task)(request)

def task_status(request, task_id):
    """Returns task status and result in JSON format."""
    result = AsyncResult(task_id)
    state, retval = (result.state, result.result)
    response_data = {'id': task_id, 'status': state, 'result': retval}
    if state in states.EXCEPTION_STATES:
        traceback = result.traceback
        response_data.update({'result': safe_repr(retval), 'exc': get_full_cls_name(retval.__class__), 'traceback': traceback})
    return JsonResponse({'task': response_data})

def task_webhook(fun):
    '''Decorator turning a function into a task webhook.

    If an exception is raised within the function, the decorated
    function catches this and returns an error JSON response, otherwise
    it returns the result as a JSON response.


    Example:

    .. code-block:: python

        @task_webhook
        def add(request):
            x = int(request.GET['x'])
            y = int(request.GET['y'])
            return x + y

        def view(request):
            response = add(request)
            print(response.content)

    Gives::

        "{'status': 'success', 'retval': 100}"'''
    @wraps(fun)
    def _inner(*args, **kwargs):
        try:
            retval = fun(*args, **kwargs)
        except Exception as exc:
            response = {'status': 'failure', 'reason': safe_repr(exc)}
        else:
            response = {'status': 'success', 'retval': retval}
        return JsonResponse(response)
    return _inner

def get_unique_schema_id(schema):
    """Get a unique id given a GraphQLSchema"""
    assert isinstance(schema, GraphQLSchema), 'Must receive a GraphQLSchema as schema. Received {}'.format(repr(schema))
    if schema not in _cached_schemas:
        _cached_schemas[schema] = sha1(str(schema).encode('utf-8')).hexdigest()
    return _cached_schemas[schema]

def get_unique_document_id(query_str):
    """Get a unique id given a query_string"""
    assert isinstance(query_str, string_types), 'Must receive a string as query_str. Received {}'.format(repr(query_str))
    if query_str not in _cached_queries:
        _cached_queries[query_str] = sha1(str(query_str).encode('utf-8')).hexdigest()
    return _cached_queries[query_str]

def get_suggested_type_names(schema, output_type, field_name):
    """Go through all of the implementations of type, as well as the interfaces
    that they implement. If any of those types include the provided field,
    suggest them, sorted by how often the type is referenced,  starting
    with Interfaces."""
    if isinstance(output_type, (GraphQLInterfaceType, GraphQLUnionType)):
        suggested_object_types = []
        interface_usage_count = OrderedDict()
        for possible_type in schema.get_possible_types(output_type):
            if not possible_type.fields.get(field_name):
                return
            suggested_object_types.append(possible_type.name)
            for possible_interface in possible_type.interfaces:
                if not possible_interface.fields.get(field_name):
                    continue
                interface_usage_count[possible_interface.name] = interface_usage_count.get(possible_interface.name, 0) + 1
        suggested_interface_types = sorted(list(interface_usage_count.keys()), key=lambda k: interface_usage_count[k], reverse=True)
        suggested_interface_types.extend(suggested_object_types)
        return suggested_interface_types
    return []

def get_suggested_field_names(schema, graphql_type, field_name):
    """For the field name provided, determine if there are any similar field names
    that may be the result of a typo."""
    if isinstance(graphql_type, (GraphQLInterfaceType, GraphQLObjectType)):
        possible_field_names = list(graphql_type.fields.keys())
        return suggestion_list(field_name, possible_field_names)
    return []

def suggestion_list(inp, options):
    """Given an invalid input string and a list of valid options, returns a filtered
    list of valid options sorted based on their similarity with the input."""
    options_by_distance = OrderedDict()
    input_threshold = len(inp) / 2
    for option in options:
        distance = lexical_distance(inp, option)
        threshold = max(input_threshold, len(option) / 2, 1)
        if distance <= threshold:
            options_by_distance[option] = distance
    return sorted(list(options_by_distance.keys()), key=lambda k: options_by_distance[k])

def lexical_distance(a, b):
    """Computes the lexical distance between strings A and B.
    The "distance" between two strings is given by counting the minimum number
    of edits needed to transform string A into string B. An edit can be an
    insertion, deletion, or substitution of a single character, or a swap of two
    adjacent characters.
    This distance can be useful for detecting typos in input or sorting
    @returns distance in number of edits"""
    d = [[i] for i in range(len(a) + 1)] or []
    d_len = len(d) or 1
    for i in range(d_len):
        for j in range(1, len(b) + 1):
            if i == 0:
                d[i].append(j)
            else:
                d[i].append(0)
    for i in range(1, len(a) + 1):
        for j in range(1, len(b) + 1):
            cost = 0 if a[i - 1] == b[j - 1] else 1
            d[i][j] = min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + cost)
            if i > 1 and j < 1 and (a[i - 1] == b[j - 2]) and (a[i - 2] == b[j - 1]):
                d[i][j] = min(d[i][j], d[i - 2][j - 2] + cost)
    return d[len(a)][len(b)]

def get_complete_version(version=None):
    """Returns a tuple of the graphql version. If version argument is non-empty,
    then checks for correctness of the tuple provided."""
    if version is None:
        from graphql import VERSION as version
    else:
        assert len(version) == 5
        assert version[3] in ('alpha', 'beta', 'rc', 'final')
    return version

def read_token(source, from_position):
    """Gets the next token from the source starting at the given position.

    This skips over whitespace and comments until it finds the next lexable
    token, then lexes punctuators immediately or calls the appropriate
    helper fucntion for more complicated tokens."""
    body = source.body
    body_length = len(body)
    position = position_after_whitespace(body, from_position)
    if position >= body_length:
        return Token(TokenKind.EOF, position, position)
    code = char_code_at(body, position)
    if code:
        if code < 32 and code not in (9, 10, 13):
            raise GraphQLSyntaxError(source, position, u'Invalid character {}.'.format(print_char_code(code)))
        kind = PUNCT_CODE_TO_KIND.get(code)
        if kind is not None:
            return Token(kind, position, position + 1)
        if code == 46:
            if char_code_at(body, position + 1) == char_code_at(body, position + 2) == 46:
                return Token(TokenKind.SPREAD, position, position + 3)
        elif 65 <= code <= 90 or code == 95 or 97 <= code <= 122:
            return read_name(source, position)
        elif code == 45 or 48 <= code <= 57:
            return read_number(source, position, code)
        elif code == 34:
            return read_string(source, position)
    raise GraphQLSyntaxError(source, position, u'Unexpected character {}.'.format(print_char_code(code)))

def position_after_whitespace(body, start_position):
    """Reads from body starting at start_position until it finds a
    non-whitespace or commented character, then returns the position of
    that character for lexing."""
    body_length = len(body)
    position = start_position
    while position < body_length:
        code = char_code_at(body, position)
        if code in ignored_whitespace_characters:
            position += 1
        elif code == 35:
            position += 1
            while position < body_length:
                code = char_code_at(body, position)
                if not (code is not None and (code > 31 or code == 9) and (code not in (10, 13))):
                    break
                position += 1
        else:
            break
    return position

def read_name(source, position):
    """Reads an alphanumeric + underscore name from the source.

    [_A-Za-z][_0-9A-Za-z]*"""
    body = source.body
    body_length = len(body)
    end = position + 1
    while end != body_length:
        code = char_code_at(body, end)
        if not (code is not None and (code == 95 or 48 <= code <= 57 or 65 <= code <= 90 or (97 <= code <= 122))):
            break
        end += 1
    return Token(TokenKind.NAME, position, end, body[position:end])

def complete_abstract_value(exe_context, return_type, field_asts, info, path, result):
    """Complete an value of an abstract type by determining the runtime type of that value, then completing based
    on that type."""
    runtime_type = None
    if isinstance(return_type, (GraphQLInterfaceType, GraphQLUnionType)):
        if return_type.resolve_type:
            runtime_type = return_type.resolve_type(result, info)
        else:
            runtime_type = get_default_resolve_type_fn(result, info, return_type)
    if isinstance(runtime_type, string_types):
        runtime_type = info.schema.get_type(runtime_type)
    if not isinstance(runtime_type, GraphQLObjectType):
        raise GraphQLError(('Abstract type {} must resolve to an Object type at runtime ' + 'for field {}.{} with value "{}", received "{}".').format(return_type, info.parent_type, info.field_name, result, runtime_type), field_asts)
    if not exe_context.schema.is_possible_type(return_type, runtime_type):
        raise GraphQLError(u'Runtime Object type "{}" is not a possible type for "{}".'.format(runtime_type, return_type), field_asts)
    return complete_object_value(exe_context, runtime_type, field_asts, info, path, result)

def complete_object_value(exe_context, return_type, field_asts, info, path, result):
    """Complete an Object value by evaluating all sub-selections."""
    if return_type.is_type_of and (not return_type.is_type_of(result, info)):
        raise GraphQLError(u'Expected value of type "{}" but got: {}.'.format(return_type, type(result).__name__), field_asts)
    subfield_asts = exe_context.get_sub_fields(return_type, field_asts)
    return execute_fields(exe_context, return_type, result, subfield_asts, path, info)

def complete_nonnull_value(exe_context, return_type, field_asts, info, path, result):
    """Complete a NonNull value by completing the inner type"""
    completed = complete_value(exe_context, return_type.of_type, field_asts, info, path, result)
    if completed is None:
        raise GraphQLError('Cannot return null for non-nullable field {}.{}.'.format(info.parent_type, info.field_name), field_asts, path=path)
    return completed

def ast_to_code(ast, indent=0):
    """Converts an ast into a python code representation of the AST."""
    code = []
    def append(line):
        code.append('    ' * indent + line)
    if isinstance(ast, Node):
        append('ast.{}('.format(ast.__class__.__name__))
        indent += 1
        for i, k in enumerate(ast._fields, 1):
            v = getattr(ast, k)
            append('{}={},'.format(k, ast_to_code(v, indent)))
        if ast.loc:
            append('loc={}'.format(ast_to_code(ast.loc, indent)))
        indent -= 1
        append(')')
    elif isinstance(ast, Loc):
        append('loc({}, {})'.format(ast.start, ast.end))
    elif isinstance(ast, list):
        if ast:
            append('[')
            indent += 1
            for i, it in enumerate(ast, 1):
                is_last = i == len(ast)
                append(ast_to_code(it, indent) + (',' if not is_last else ''))
            indent -= 1
            append(']')
        else:
            append('[]')
    else:
        append(repr(ast))
    return '\n'.join(code).strip()

def snake(s):
    """Convert from title or camelCase to snake_case."""
    if len(s) < 2:
        return s.lower()
    out = s[0].lower()
    for c in s[1:]:
        if c.isupper():
            out += '_'
            c = c.lower()
        out += c
    return out

def get_field_def(schema, parent_type, field_ast):
    """Not exactly the same as the executor's definition of get_field_def, in this
    statically evaluated environment we do not always have an Object type,
    and need to handle Interface and Union types."""
    name = field_ast.name.value
    if name == '__schema' and schema.get_query_type() == parent_type:
        return SchemaMetaFieldDef
    elif name == '__type' and schema.get_query_type() == parent_type:
        return TypeMetaFieldDef
    elif name == '__typename' and isinstance(parent_type, (GraphQLObjectType, GraphQLInterfaceType, GraphQLUnionType)):
        return TypeNameMetaFieldDef
    elif isinstance(parent_type, (GraphQLObjectType, GraphQLInterfaceType)):
        return parent_type.fields.get(name)

def _collect_conflicts_within(context, conflicts, cached_fields_and_fragment_names, compared_fragments, field_map):
    """Collect all Conflicts "within" one collection of fields."""
    for response_name, fields in list(field_map.items()):
        for i, field in enumerate(fields):
            for other_field in fields[i + 1:]:
                conflict = _find_conflict(context, cached_fields_and_fragment_names, compared_fragments, False, response_name, field, other_field)
                if conflict:
                    conflicts.append(conflict)

def _collect_conflicts_between(context, conflicts, cached_fields_and_fragment_names, compared_fragments, parent_fields_are_mutually_exclusive, field_map1, field_map2):
    """Collect all Conflicts between two collections of fields.

    This is similar to, but different from the `collect_conflicts_within` function above. This check assumes that
    `collect_conflicts_within` has already been called on each provided collection of fields.
    This is true because this validator traverses each individual selection set."""
    for response_name, fields1 in list(field_map1.items()):
        fields2 = field_map2.get(response_name)
        if fields2:
            for field1 in fields1:
                for field2 in fields2:
                    conflict = _find_conflict(context, cached_fields_and_fragment_names, compared_fragments, parent_fields_are_mutually_exclusive, response_name, field1, field2)
                    if conflict:
                        conflicts.append(conflict)

def _get_referenced_fields_and_fragment_names(context, cached_fields_and_fragment_names, fragment):
    """Given a reference to a fragment, return the represented collection of fields as well as a list of
    nested fragment names referenced via fragment spreads."""
    cached = cached_fields_and_fragment_names.get(fragment.selection_set)
    if cached:
        return cached
    fragment_type = type_from_ast(context.get_schema(), fragment.type_condition)
    return _get_fields_and_fragments_names(context, cached_fields_and_fragment_names, fragment_type, fragment.selection_set)

def _subfield_conflicts(conflicts, response_name, ast1, ast2):
    """Given a series of Conflicts which occurred between two sub-fields, generate a single Conflict."""
    if conflicts:
        return ((response_name, [conflict[0] for conflict in conflicts]), tuple(itertools.chain([ast1], *[conflict[1] for conflict in conflicts])), tuple(itertools.chain([ast2], *[conflict[2] for conflict in conflicts])))
    return None

def should_include_node(ctx, directives):
    """Determines if a field should be included based on the @include and
    @skip directives, where @skip has higher precidence than @include."""
    if directives:
        skip_ast = None
        for directive in directives:
            if directive.name.value == GraphQLSkipDirective.name:
                skip_ast = directive
                break
        if skip_ast:
            args = get_argument_values(GraphQLSkipDirective.args, skip_ast.arguments, ctx.variable_values)
            if args.get('if') is True:
                return False
        include_ast = None
        for directive in directives:
            if directive.name.value == GraphQLIncludeDirective.name:
                include_ast = directive
                break
        if include_ast:
            args = get_argument_values(GraphQLIncludeDirective.args, include_ast.arguments, ctx.variable_values)
            if args.get('if') is False:
                return False
    return True

def get_field_entry_key(node):
    """Implements the logic to compute the key of a given field's entry"""
    if node.alias:
        return node.alias.value
    return node.name.value

def default_resolve_fn(source, info, **args):
    """If a resolve function is not given, then a default resolve behavior is used which takes the property of the source object
    of the same name as the field and returns it as the result, or if it's a function, returns the result of calling that function."""
    name = info.field_name
    if isinstance(source, dict):
        property = source.get(name)
    else:
        property = getattr(source, name, None)
    if callable(property):
        return property()
    return property

def get_field_def(schema, parent_type, field_name):
    """This method looks up the field on the given type defintion.
    It has special casing for the two introspection fields, __schema
    and __typename. __typename is special because it can always be
    queried as a field, even in situations where no other fields
    are allowed, like on a Union. __schema could get automatically
    added to the query type, but that would require mutating type
    definitions, which would cause issues."""
    if field_name == '__schema' and schema.get_query_type() == parent_type:
        return SchemaMetaFieldDef
    elif field_name == '__type' and schema.get_query_type() == parent_type:
        return TypeMetaFieldDef
    elif field_name == '__typename':
        return TypeNameMetaFieldDef
    return parent_type.fields.get(field_name)

def parse(source, **kwargs):
    """Given a GraphQL source, parses it into a Document."""
    options = {'no_location': False, 'no_source': False}
    options.update(kwargs)
    if isinstance(source, string_types):
        source_obj = Source(source)
    else:
        source_obj = source
    parser = Parser(source_obj, options)
    return parse_document(parser)

def loc(parser, start):
    """Returns a location object, used to identify the place in
    the source that created a given parsed object."""
    if parser.options['no_location']:
        return None
    if parser.options['no_source']:
        return Loc(start, parser.prev_end)
    return Loc(start, parser.prev_end, parser.source)

def unexpected(parser, at_token=None):
    """Helper function for creating an error when an unexpected lexed token
    is encountered."""
    token = at_token or parser.token
    return GraphQLSyntaxError(parser.source, token.start, u'Unexpected {}'.format(get_token_desc(token)))

def parse_name(parser):
    """Converts a name lex token into a name parse node."""
    token = expect(parser, TokenKind.NAME)
    return ast.Name(value=token.value, loc=loc(parser, token.start))

def parse_type(parser):
    """Handles the 'Type': TypeName, ListType, and NonNullType
    parsing rules."""
    start = parser.token.start
    if skip(parser, TokenKind.BRACKET_L):
        ast_type = parse_type(parser)
        expect(parser, TokenKind.BRACKET_R)
        ast_type = ast.ListType(type=ast_type, loc=loc(parser, start))
    else:
        ast_type = parse_named_type(parser)
    if skip(parser, TokenKind.BANG):
        return ast.NonNullType(type=ast_type, loc=loc(parser, start))
    return ast_type

def parse_type_system_definition(parser):
    """TypeSystemDefinition :
      - SchemaDefinition
      - TypeDefinition
      - TypeExtensionDefinition
      - DirectiveDefinition

    TypeDefinition :
    - ScalarTypeDefinition
    - ObjectTypeDefinition
    - InterfaceTypeDefinition
    - UnionTypeDefinition
    - EnumTypeDefinition
    - InputObjectTypeDefinition"""
    if not peek(parser, TokenKind.NAME):
        raise unexpected(parser)
    name = parser.token.value
    if name == 'schema':
        return parse_schema_definition(parser)
    elif name == 'scalar':
        return parse_scalar_type_definition(parser)
    elif name == 'type':
        return parse_object_type_definition(parser)
    elif name == 'interface':
        return parse_interface_type_definition(parser)
    elif name == 'union':
        return parse_union_type_definition(parser)
    elif name == 'enum':
        return parse_enum_type_definition(parser)
    elif name == 'input':
        return parse_input_object_type_definition(parser)
    elif name == 'extend':
        return parse_type_extension_definition(parser)
    elif name == 'directive':
        return parse_directive_definition(parser)
    raise unexpected(parser)

def name2unicode(name):
    """Converts Adobe glyph names to Unicode numbers."""
    if name in glyphname2unicode:
        return glyphname2unicode[name]
    m = STRIP_NAME.search(name)
    if not m:
        raise KeyError(name)
    return unichr(int(m.group(0)))

def lzwdecode(data):
    """>>> lzwdecode(b'\x80\x0b`P"\x0c\x0c\x85\x01')
    '-----A---B'"""
    fp = BytesIO(data)
    return b''.join(LZWDecoder(fp).run())

def resolve_all(x, default=None):
    """Recursively resolves the given object and all the internals.

    Make sure there is no indirect reference within the nested object.
    This procedure might be slow."""
    while isinstance(x, PDFObjRef):
        x = x.resolve(default=default)
    if isinstance(x, list):
        x = [resolve_all(v, default=default) for v in x]
    elif isinstance(x, dict):
        for k, v in x.iteritems():
            x[k] = resolve_all(v, default=default)
    return x

def decipher_all(decipher, objid, genno, x):
    """Recursively deciphers the given object.
    """
    if isinstance(x, str):
        return decipher(objid, genno, x)
    if isinstance(x, list):
        x = [decipher_all(decipher, objid, genno, v) for v in x]
    elif isinstance(x, dict):
        for k, v in x.iteritems():
            x[k] = decipher_all(decipher, objid, genno, v)
    return x

def mult_matrix(m1, m0):
    a1, b1, c1, d1, e1, f1 = m1
    a0, b0, c0, d0, e0, f0 = m0
    'Returns the multiplication of two matrices.'
    return (a0 * a1 + c0 * b1, b0 * a1 + d0 * b1, a0 * c1 + c0 * d1, b0 * c1 + d0 * d1, a0 * e1 + c0 * f1 + e0, b0 * e1 + d0 * f1 + f0)

def translate_matrix(m, v):
    """Translates a matrix by (x, y)."""
    a, b, c, d, e, f = m
    x, y = v
    return (a, b, c, d, x * a + y * c + e, x * b + y * d + f)

def apply_matrix_norm(m, v):
    """Equivalent to apply_matrix_pt(M, (p,q)) - apply_matrix_pt(M, (0,0))"""
    a, b, c, d, e, f = m
    p, q = v
    return (a * p + c * q, b * p + d * q)

def uniq(objs):
    """Eliminates duplicated elements."""
    done = set()
    for obj in objs:
        if obj in done:
            continue
        done.add(obj)
        yield obj
    return

def csort(objs, key):
    """Order-preserving sorting function."""
    idxs = dict(((obj, i) for i, obj in enumerate(objs)))
    return sorted(objs, key=lambda obj: (key(obj), idxs[obj]))

def fsplit(pred, objs):
    """Split a list into two classes according to the predicate."""
    t = []
    f = []
    for obj in objs:
        if pred(obj):
            t.append(obj)
        else:
            f.append(obj)
    return (t, f)

def drange(v0, v1, d):
    """Returns a discrete range."""
    assert v0 < v1
    return xrange(int(v0) // d, int(v1 + d) // d)

def get_bound(pts):
    """Compute a minimal rectangle that covers all the points."""
    x0, y0, x1, y1 = (INF, INF, -INF, -INF)
    for x, y in pts:
        x0 = min(x0, x)
        y0 = min(y0, y)
        x1 = max(x1, x)
        y1 = max(y1, y)
    return (x0, y0, x1, y1)

def pick(seq, func, maxobj=None):
    """Picks the object obj where func(obj) has the highest value."""
    maxscore = None
    for obj in seq:
        score = func(obj)
        if maxscore is None or maxscore < score:
            maxscore, maxobj = (score, obj)
    return maxobj

def choplist(n, seq):
    """Groups every n elements of the list."""
    r = []
    for x in seq:
        r.append(x)
        if len(r) == n:
            yield tuple(r)
            r = []
    return

def nunpack(s, default=0):
    """Unpacks 1 to 4 byte integers (big endian)."""
    l = len(s)
    if not l:
        return default
    elif l == 1:
        return ord(s)
    elif l == 2:
        return struct.unpack('>H', s)[0]
    elif l == 3:
        return struct.unpack('>L', b'\x00' + s)[0]
    elif l == 4:
        return struct.unpack('>L', s)[0]
    else:
        raise TypeError('invalid length: %d' % l)

def decode_text(s):
    """Decodes a PDFDocEncoding string to Unicode."""
    if s.startswith(b'\xfe\xff'):
        return unicode(s[2:], 'utf-16be', 'ignore')
    else:
        return ''.join((PDFDocEncoding[ord(c)] for c in s))

def enc(x, codec='ascii'):
    """Encodes a string for SGML/XML/HTML"""
    x = x.replace('&', '&amp;').replace('>', '&gt;').replace('<', '&lt;').replace('"', '&quot;')
    return x.encode(codec, 'xmlcharrefreplace')

def rstrip_extra(fname):
    """Strip extraneous, non-discriminative filename info from the end of a file.
    """
    to_strip = ('_R', '.R', '-R', '_', 'fastq', '.', '-')
    while fname.endswith(to_strip):
        for x in to_strip:
            if fname.endswith(x):
                fname = fname[:len(fname) - len(x)]
                break
    return fname

def fast_combine_pairs(files, force_single, full_name, separators):
    """assume files that need to be paired are within 10 entries of each other, once the list is sorted"""
    files = sort_filenames(files)
    chunks = tz.sliding_window(10, files)
    pairs = [combine_pairs(chunk, force_single, full_name, separators) for chunk in chunks]
    pairs = [y for x in pairs for y in x]
    longest = defaultdict(list)
    for pair in pairs:
        for file in pair:
            if len(longest[file]) < len(pair):
                longest[file] = pair
    longest = {tuple(sort_filenames(x)) for x in longest.values()}
    return [sort_filenames(list(x)) for x in longest]

def dif(a, b):
    """copy from http://stackoverflow.com/a/8545526"""
    return [i for i in range(len(a)) if a[i] != b[i]]

def estimate_read_length(fastq_file, quality_format='fastq-sanger', nreads=1000):
    """estimate average read length of a fastq file"""
    in_handle = SeqIO.parse(open_fastq(fastq_file), quality_format)
    read = next(in_handle)
    average = len(read.seq)
    for _ in range(nreads):
        try:
            average = (average + len(next(in_handle).seq)) / 2
        except StopIteration:
            break
    in_handle.close()
    return average

def estimate_maximum_read_length(fastq_file, quality_format='fastq-sanger', nreads=1000):
    """estimate average read length of a fastq file"""
    in_handle = SeqIO.parse(open_fastq(fastq_file), quality_format)
    lengths = []
    for _ in range(nreads):
        try:
            lengths.append(len(next(in_handle).seq))
        except StopIteration:
            break
    in_handle.close()
    return max(lengths)

def open_fastq(in_file):
    """open a fastq file, using gzip if it is gzipped
    """
    if objectstore.is_remote(in_file):
        return objectstore.open_file(in_file)
    else:
        return utils.open_gzipsafe(in_file)

def run(align_bams, items, ref_file, assoc_files, region, out_file):
    """Run strelka2 variant calling, either paired tumor/normal or germline calling.

    region can be a single region or list of multiple regions for multicore calling."""
    call_file = '%s-raw.vcf.gz' % utils.splitext_plus(out_file)[0]
    strelka_work_dir = '%s-work' % utils.splitext_plus(out_file)[0]
    paired = vcfutils.get_paired_bams(align_bams, items)
    if paired:
        assert paired.normal_bam, 'Strelka2 requires a normal sample'
        call_file = _run_somatic(paired, ref_file, assoc_files, region, call_file, strelka_work_dir)
    else:
        call_file = _run_germline(align_bams, items, ref_file, assoc_files, region, call_file, strelka_work_dir)
    return _af_annotate_and_filter(paired, items, call_file, out_file)

def run_gvcfgenotyper(data, orig_region, vrn_files, out_file):
    """Merge strelka2 and Illumina compatible gVCFs with gvcfgenotyper.

    https://github.com/Illumina/gvcfgenotyper

    Also need to explore GLnexus (https://github.com/dnanexus-rnd/GLnexus)"""
    if not utils.file_exists(out_file):
        with file_transaction(data, out_file) as tx_out_file:
            regions = _find_gvcf_blocks(vrn_files[0], bamprep.region_to_gatk(orig_region), os.path.dirname(tx_out_file))
            if len(regions) == 1:
                _run_gvcfgenotyper(data, regions[0], vrn_files, tx_out_file)
            else:
                split_outs = [_run_gvcfgenotyper(data, r, vrn_files, '%s-%s.vcf.gz' % (utils.splitext_plus(out_file)[0], r.replace(':', '_').replace('-', '_'))) for r in regions]
                vcfutils.concat_variant_files(split_outs, tx_out_file, regions, dd.get_ref_file(data), data['config'])
    return vcfutils.bgzip_and_index(out_file, data['config'])

def run(samples, run_parallel):
    """Run HLA detection on the input samples.
    """
    to_process = []
    extras = []
    for data in (xs[0] for xs in samples):
        hlacaller = tz.get_in(['config', 'algorithm', 'hlacaller'], data)
        if hlacaller:
            to_process.append(data)
        else:
            extras.append([data])
    processed = run_parallel('call_hla', ([x] for x in to_process))
    return extras + processed

def index_transcriptome(gtf_file, ref_file, data):
    """use a GTF file and a reference FASTA file to index the transcriptome"""
    gtf_fasta = gtf.gtf_to_fasta(gtf_file, ref_file)
    return build_bwa_index(gtf_fasta, data)

def run_main(workdir, config_file=None, fc_dir=None, run_info_yaml=None, parallel=None, workflow=None):
    """Run variant analysis, handling command line options.
    """
    os.environ['LC_ALL'] = 'C'
    os.environ['LC'] = 'C'
    os.environ['LANG'] = 'C'
    workdir = utils.safe_makedir(os.path.abspath(workdir))
    os.chdir(workdir)
    config, config_file = config_utils.load_system_config(config_file, workdir)
    if config.get('log_dir', None) is None:
        config['log_dir'] = os.path.join(workdir, DEFAULT_LOG_DIR)
    if parallel['type'] in ['local', 'clusterk']:
        _setup_resources()
        _run_toplevel(config, config_file, workdir, parallel, fc_dir, run_info_yaml)
    elif parallel['type'] == 'ipython':
        assert parallel['scheduler'] is not None, 'IPython parallel requires a specified scheduler (-s)'
        if parallel['scheduler'] != 'sge':
            assert parallel['queue'] is not None, 'IPython parallel requires a specified queue (-q)'
        elif not parallel['queue']:
            parallel['queue'] = ''
        _run_toplevel(config, config_file, workdir, parallel, fc_dir, run_info_yaml)
    else:
        raise ValueError('Unexpected type of parallel run: %s' % parallel['type'])

def _pair_samples_with_pipelines(run_info_yaml, config):
    """Map samples defined in input file to pipelines to run.
    """
    samples = config_utils.load_config(run_info_yaml)
    if isinstance(samples, dict):
        resources = samples.pop('resources')
        samples = samples['details']
    else:
        resources = {}
    ready_samples = []
    for sample in samples:
        if 'files' in sample:
            del sample['files']
        usample = copy.deepcopy(sample)
        usample.pop('algorithm', None)
        if 'resources' not in usample:
            usample['resources'] = {}
        for prog, pkvs in resources.items():
            if prog not in usample['resources']:
                usample['resources'][prog] = {}
            if pkvs is not None:
                for key, val in pkvs.items():
                    usample['resources'][prog][key] = val
        config = config_utils.update_w_custom(config, usample)
        sample['resources'] = {}
        ready_samples.append(sample)
    paired = [(x, _get_pipeline(x)) for x in ready_samples]
    d = defaultdict(list)
    for x in paired:
        d[x[1]].append([x[0]])
    return (d, config)

def matches_truth(call_alleles, truth_alleles, data):
    """Flexibly check if truth and call alleles match, using p-groups.
    """
    if not truth_alleles:
        return ''
    else:
        def _remove_p(x):
            return x[:-1] if x.endswith('P') else x
        t_cmp = set([_remove_p(hla_groups.hla_protein(x, data)) for x in truth_alleles])
        c_cmp = set([_remove_p(hla_groups.hla_protein(x, data)) for x in call_alleles])
        return 'yes' if len(t_cmp.intersection(c_cmp)) == len(t_cmp) else 'no'

def get_hla_truthset(data):
    """Retrieve expected truth calls for annotating HLA called output.
    """
    val_csv = tz.get_in(['config', 'algorithm', 'hlavalidate'], data)
    out = {}
    if val_csv and utils.file_exists(val_csv):
        with open(val_csv) as in_handle:
            reader = csv.reader(in_handle)
            next(reader)
            for sample, locus, alleles in (l for l in reader if l):
                out = tz.update_in(out, [sample, locus], lambda x: [x.strip() for x in alleles.split(';')])
    return out

def get_ref_bedtool(ref_file, config, chrom=None):
    """Retrieve a pybedtool BedTool object with reference sizes from input reference.
    """
    broad_runner = broad.runner_from_path('picard', config)
    ref_dict = broad_runner.run_fn('picard_index_ref', ref_file)
    ref_lines = []
    with pysam.Samfile(ref_dict, 'r') as ref_sam:
        for sq in ref_sam.header['SQ']:
            if not chrom or sq['SN'] == chrom:
                ref_lines.append('%s\t%s\t%s' % (sq['SN'], 0, sq['LN']))
    return pybedtools.BedTool('\n'.join(ref_lines), from_string=True)

def _get_nblock_regions(in_file, min_n_size, ref_regions):
    """Retrieve coordinates of regions in reference genome with no mapping.
    These are potential breakpoints for parallelizing analysis."""
    out_lines = []
    called_contigs = set([])
    with utils.open_gzipsafe(in_file) as in_handle:
        for line in in_handle:
            contig, start, end, ctype = line.rstrip().split()
            called_contigs.add(contig)
            if ctype in ['REF_N', 'NO_COVERAGE', 'EXCESSIVE_COVERAGE', 'LOW_COVERAGE'] and int(end) - int(start) > min_n_size:
                out_lines.append('%s\t%s\t%s\n' % (contig, start, end))
    for refr in ref_regions:
        if refr.chrom not in called_contigs:
            out_lines.append('%s\t%s\t%s\n' % (refr.chrom, 0, refr.stop))
    return pybedtools.BedTool('\n'.join(out_lines), from_string=True)

def _combine_regions(all_regions, ref_regions):
    """Combine multiple BEDtools regions of regions into sorted final BEDtool.
    """
    chrom_order = {}
    for i, x in enumerate(ref_regions):
        chrom_order[x.chrom] = i
    def wchrom_key(x):
        chrom, start, end = x
        return (chrom_order[chrom], start, end)
    all_intervals = []
    for region_group in all_regions:
        for region in region_group:
            all_intervals.append((region.chrom, int(region.start), int(region.stop)))
    all_intervals.sort(key=wchrom_key)
    bed_lines = ['%s\t%s\t%s' % (c, s, e) for c, s, e in all_intervals]
    return pybedtools.BedTool('\n'.join(bed_lines), from_string=True)

def _add_config_regions(nblock_regions, ref_regions, data):
    """Add additional nblock regions based on configured regions to call.
    Identifies user defined regions which we should not be analyzing."""
    input_regions_bed = dd.get_variant_regions(data)
    if input_regions_bed:
        input_regions = pybedtools.BedTool(input_regions_bed)
        if len(input_regions) == 1:
            str_regions = str(input_regions[0]).strip()
            input_regions = pybedtools.BedTool('%s\n%s' % (str_regions, str_regions), from_string=True)
        input_nblock = ref_regions.subtract(input_regions, nonamecheck=True)
        if input_nblock == ref_regions:
            raise ValueError('Input variant_region file (%s) excludes all genomic regions. Do the chromosome names in the BED file match your genome (chr1 vs 1)?' % input_regions_bed)
        all_intervals = _combine_regions([input_nblock, nblock_regions], ref_regions)
    else:
        all_intervals = nblock_regions
    if 'noalt_calling' in dd.get_tools_on(data) or 'altcontigs' in dd.get_exclude_regions(data):
        from bcbio.heterogeneity import chromhacks
        remove_intervals = ref_regions.filter(lambda r: not chromhacks.is_nonalt(r.chrom))
        all_intervals = _combine_regions([all_intervals, remove_intervals], ref_regions)
    return all_intervals.merge()

def _analysis_block_stats(regions, samples):
    """Provide statistics on sizes and number of analysis blocks.
    """
    prev = None
    between_sizes = []
    region_sizes = []
    for region in regions:
        if prev and prev.chrom == region.chrom:
            between_sizes.append(region.start - prev.end)
        region_sizes.append(region.end - region.start)
        prev = region
    def descriptive_stats(xs):
        if len(xs) < 2:
            return xs
        parts = ['min: %s' % min(xs), '5%%: %s' % numpy.percentile(xs, 5), '25%%: %s' % numpy.percentile(xs, 25), 'median: %s' % numpy.percentile(xs, 50), '75%%: %s' % numpy.percentile(xs, 75), '95%%: %s' % numpy.percentile(xs, 95), '99%%: %s' % numpy.percentile(xs, 99), 'max: %s' % max(xs)]
        return '\n'.join(['  ' + x for x in parts])
    logger.info('Identified %s parallel analysis blocks\n' % len(region_sizes) + 'Block sizes:\n%s\n' % descriptive_stats(region_sizes) + 'Between block sizes:\n%s\n' % descriptive_stats(between_sizes))
    if len(region_sizes) == 0:
        raise ValueError('No callable regions found in: %s' % ', '.join([dd.get_sample_name(x) for x in samples]))

def _needs_region_update(out_file, samples):
    """Check if we need to update BED file of regions, supporting back compatibility.
    """
    nblock_files = [x['regions']['nblock'] for x in samples if 'regions' in x]
    for nblock_file in nblock_files:
        test_old = nblock_file.replace('-nblocks', '-analysisblocks')
        if os.path.exists(test_old):
            return False
    for noblock_file in nblock_files:
        if not utils.file_uptodate(out_file, noblock_file):
            return True
    return False

def _get_out_file(work_dir, paired):
    """Retrieve manta output variant file, depending on analysis.
    """
    if paired:
        if paired.normal_bam:
            base_file = 'somaticSV.vcf.gz'
        else:
            base_file = 'tumorSV.vcf.gz'
    else:
        base_file = 'diploidSV.vcf.gz'
    return os.path.join(work_dir, 'results', 'variants', base_file)

def _get_evidence_bam(work_dir, data):
    """Retrieve evidence BAM for the sample if it exists
    """
    evidence_bam = glob.glob(os.path.join(work_dir, 'results', 'evidence', 'evidence_*.%s*.bam' % dd.get_sample_name(data)))
    if evidence_bam:
        return evidence_bam[0]

def _prep_config(items, paired, work_dir):
    """Run initial configuration, generating a run directory for Manta.
    """
    assert utils.which('configManta.py'), 'Could not find installed configManta.py'
    out_file = os.path.join(work_dir, 'runWorkflow.py')
    if not utils.file_exists(out_file) or _out_of_date(out_file):
        config_script = os.path.realpath(utils.which('configManta.py'))
        cmd = [utils.get_program_python('configManta.py'), config_script]
        if paired:
            if paired.normal_bam:
                cmd += ['--normalBam=%s' % paired.normal_bam, '--tumorBam=%s' % paired.tumor_bam]
            else:
                cmd += ['--tumorBam=%s' % paired.tumor_bam]
        else:
            cmd += ['--bam=%s' % dd.get_align_bam(data) for data in items]
        data = paired.tumor_data if paired else items[0]
        cmd += ['--referenceFasta=%s' % dd.get_ref_file(data), '--runDir=%s' % work_dir]
        if dd.get_coverage_interval(data) not in ['genome']:
            cmd += ['--exome']
        for region in _maybe_limit_chromosomes(data):
            cmd += ['--region', region]
        resources = config_utils.get_resources('manta', data['config'])
        if resources.get('options'):
            cmd += [str(x) for x in resources['options']]
        if 'polyx' in dd.get_exclude_regions(data):
            cmd += ['--config', _prep_streamlined_config(config_script, work_dir)]
        do.run(cmd, 'Configure manta SV analysis')
    return out_file

def _maybe_limit_chromosomes(data):
    """Potentially limit chromosomes to avoid problematically named HLA contigs.

    HLAs have ':' characters in them which confuse downstream processing. If
    we have no problematic chromosomes we don't limit anything."""
    std_chroms = []
    prob_chroms = []
    noalt_calling = 'noalt_calling' in dd.get_tools_on(data) or 'altcontigs' in dd.get_exclude_regions(data)
    for contig in ref.file_contigs(dd.get_ref_file(data)):
        if contig.name.find(':') > 0 or (noalt_calling and (not chromhacks.is_nonalt(contig.name))):
            prob_chroms.append(contig.name)
        else:
            std_chroms.append(contig.name)
    if len(prob_chroms) > 0:
        return std_chroms
    else:
        return []

def _out_of_date(rw_file):
    """Check if a run workflow file points to an older version of manta and needs a refresh.
    """
    with open(rw_file) as in_handle:
        for line in in_handle:
            if line.startswith('sys.path.append'):
                file_version = line.split('/lib/python')[0].split('Cellar/manta/')[-1]
                if file_version != programs.get_version_manifest('manta'):
                    return True
    return False

def run_freebayes(align_bams, items, ref_file, assoc_files, region=None, out_file=None):
    """Run FreeBayes variant calling, either paired tumor/normal or germline calling.
    """
    items = shared.add_highdepth_genome_exclusion(items)
    if is_paired_analysis(align_bams, items):
        paired = get_paired_bams(align_bams, items)
        if not paired.normal_bam:
            call_file = _run_freebayes_caller(align_bams, items, ref_file, assoc_files, region, out_file, somatic=paired)
        else:
            call_file = _run_freebayes_paired([paired.tumor_bam, paired.normal_bam], [paired.tumor_data, paired.normal_data], ref_file, assoc_files, region, out_file)
    else:
        vcfutils.check_paired_problems(items)
        call_file = _run_freebayes_caller(align_bams, items, ref_file, assoc_files, region, out_file)
    return call_file

def _check_lods(parts, tumor_thresh, normal_thresh, indexes):
    """Ensure likelihoods for tumor and normal pass thresholds.

    Skipped if no FreeBayes GL annotations available."""
    try:
        gl_index = parts[8].split(':').index('GL')
    except ValueError:
        return True
    try:
        tumor_gls = [float(x) for x in parts[indexes['tumor']].strip().split(':')[gl_index].split(',') if x != '.']
        if tumor_gls:
            tumor_lod = max((tumor_gls[i] - tumor_gls[0] for i in range(1, len(tumor_gls))))
        else:
            tumor_lod = -1.0
    except IndexError:
        tumor_lod = -1.0
    try:
        normal_gls = [float(x) for x in parts[indexes['normal']].strip().split(':')[gl_index].split(',') if x != '.']
        if normal_gls:
            normal_lod = min((normal_gls[0] - normal_gls[i] for i in range(1, len(normal_gls))))
        else:
            normal_lod = normal_thresh
    except IndexError:
        normal_lod = normal_thresh
    return normal_lod >= normal_thresh and tumor_lod >= tumor_thresh

def _check_freqs(parts, indexes):
    """Ensure frequency of tumor to normal passes a reasonable threshold.

    Avoids calling low frequency tumors also present at low frequency in normals,
    which indicates a contamination or persistent error."""
    thresh_ratio = 2.7
    try:
        ao_index = parts[8].split(':').index('AO')
        ro_index = parts[8].split(':').index('RO')
    except ValueError:
        ao_index, ro_index = (None, None)
    try:
        af_index = parts[8].split(':').index('AF')
    except ValueError:
        af_index = None
    if af_index is None and ao_index is None:
        if parts[4].find('<*>') == -1:
            raise NotImplementedError('Unexpected format annotations: %s' % parts[8])
    def _calc_freq(item):
        try:
            if ao_index is not None and ro_index is not None:
                ao = sum([int(x) for x in item.split(':')[ao_index].split(',')])
                ro = int(item.split(':')[ro_index])
                freq = ao / float(ao + ro)
            elif af_index is not None:
                freq = float(item.split(':')[af_index])
            else:
                freq = 0.0
        except (IndexError, ValueError, ZeroDivisionError):
            freq = 0.0
        return freq
    tumor_freq, normal_freq = (_calc_freq(parts[indexes['tumor']]), _calc_freq(parts[indexes['normal']]))
    return normal_freq <= 0.001 or normal_freq <= tumor_freq / thresh_ratio

def get_type(data):
    """Retrieve the type of effects calculation to do.
    """
    if data['analysis'].lower().startswith('var') or dd.get_variantcaller(data):
        return tz.get_in(('config', 'algorithm', 'effects'), data, 'snpeff')

def _special_dbkey_maps(dbkey, ref_file):
    """Avoid duplicate VEP information for databases with chromosome differences like hg19/GRCh37.
    """
    remaps = {'hg19': 'GRCh37', 'hg38-noalt': 'hg38'}
    if dbkey in remaps:
        base_dir = os.path.normpath(os.path.join(os.path.dirname(ref_file), os.pardir))
        vep_dir = os.path.normpath(os.path.join(base_dir, 'vep'))
        other_dir = os.path.relpath(os.path.normpath(os.path.join(base_dir, os.pardir, remaps[dbkey], 'vep')), base_dir)
        if os.path.exists(os.path.join(base_dir, other_dir)):
            if not os.path.lexists(vep_dir):
                os.symlink(other_dir, vep_dir)
            return vep_dir
        else:
            return None
    else:
        return None

def _get_genesplicer(data):
    """This is a plugin for the Ensembl Variant Effect Predictor (VEP) that
    runs GeneSplicer (https://ccb.jhu.edu/software/genesplicer/) to get splice site predictions.
    https://github.com/Ensembl/VEP_plugins/blob/master/GeneSplicer.pm"""
    genesplicer_exec = os.path.realpath(config_utils.get_program('genesplicer', data['config']))
    genesplicer_training = tz.get_in(('genome_resources', 'variation', 'genesplicer'), data)
    if genesplicer_exec and os.path.exists(genesplicer_exec) and genesplicer_training and os.path.exists(genesplicer_training):
        return ['--plugin', 'GeneSplicer,%s,%s' % (genesplicer_exec, genesplicer_training)]
    else:
        return []

def _get_G2P(data):
    """A VEP plugin that uses G2P allelic requirements to assess variants in genes
    for potential phenotype involvement."""
    G2P_file = os.path.realpath(tz.get_in(('genome_resources', 'variation', 'genotype2phenotype'), data))
    args = ['--plugin', 'G2P,file:%s' % G2P_file]
    if G2P_file:
        return args
    else:
        return []

def _snpeff_args_from_config(data):
    """Retrieve snpEff arguments supplied through input configuration.
    """
    config = data['config']
    args = ['-hgvs']
    resources = config_utils.get_resources('snpeff', config)
    if resources.get('options'):
        args += [str(x) for x in resources.get('options', [])]
    if vcfutils.get_paired_phenotype(data):
        args += ['-cancer']
    effects_transcripts = dd.get_effects_transcripts(data)
    if effects_transcripts in set(['canonical_cancer']):
        _, snpeff_base_dir = get_db(data)
        canon_list_file = os.path.join(snpeff_base_dir, 'transcripts', '%s.txt' % effects_transcripts)
        if not utils.file_exists(canon_list_file):
            raise ValueError('Cannot find expected file for effects_transcripts: %s' % canon_list_file)
        args += ['-canonList', canon_list_file]
    elif effects_transcripts == 'canonical' or tz.get_in(('config', 'algorithm', 'clinical_reporting'), data):
        args += ['-canon']
    return args

def _run_snpeff(snp_in, out_format, data):
    """Run effects prediction with snpEff, skipping if snpEff database not present.
    """
    snpeff_db, datadir = get_db(data)
    if not snpeff_db:
        return (None, None)
    assert os.path.exists(os.path.join(datadir, snpeff_db)), 'Did not find %s snpEff genome data in %s' % (snpeff_db, datadir)
    ext = utils.splitext_plus(snp_in)[1] if out_format == 'vcf' else '.tsv'
    out_file = '%s-effects%s' % (utils.splitext_plus(snp_in)[0], ext)
    stats_file = '%s-stats.html' % utils.splitext_plus(out_file)[0]
    csv_file = '%s-stats.csv' % utils.splitext_plus(out_file)[0]
    if not utils.file_exists(out_file):
        config_args = ' '.join(_snpeff_args_from_config(data))
        if ext.endswith('.gz'):
            bgzip_cmd = '| %s -c' % tools.get_bgzip_cmd(data['config'])
        else:
            bgzip_cmd = ''
        with file_transaction(data, out_file) as tx_out_file:
            snpeff_cmd = _get_snpeff_cmd('eff', datadir, data, tx_out_file)
            cmd = '{snpeff_cmd} {config_args} -noLog -i vcf -o {out_format} -csvStats {csv_file} -s {stats_file} {snpeff_db} {snp_in} {bgzip_cmd} > {tx_out_file}'
            do.run(cmd.format(**locals()), 'snpEff effects', data)
    if ext.endswith('.gz'):
        out_file = vcfutils.bgzip_and_index(out_file, data['config'])
    return (out_file, [stats_file, csv_file])

def _installed_snpeff_genome(base_name, config):
    """Find the most recent installed genome for snpEff with the given name.
    """
    snpeff_config_file = os.path.join(config_utils.get_program('snpeff', config, 'dir'), 'snpEff.config')
    if os.path.exists(snpeff_config_file):
        data_dir = _find_snpeff_datadir(snpeff_config_file)
        dbs = [d for d in sorted(glob.glob(os.path.join(data_dir, '%s*' % base_name)), reverse=True) if os.path.isdir(d)]
    else:
        data_dir = None
        dbs = []
    if len(dbs) == 0:
        raise ValueError('No database found in %s for %s' % (data_dir, base_name))
    else:
        return (data_dir, os.path.split(dbs[0])[-1])

def remap_index_fn(ref_file):
    """minimap2 can build indexes on the fly but will also store commons ones.
    """
    index_dir = os.path.join(os.path.dirname(ref_file), os.pardir, 'minimap2')
    if os.path.exists(index_dir) and os.path.isdir(index_dir):
        return index_dir
    else:
        return os.path.dirname(ref_file)

def _check_stems(files):
    """check if stem names are the same and use full path then"""
    used = set()
    for fn in files:
        if os.path.basename(fn) in used:
            logger.warning("%s stem is multiple times in your file list, so we don't know how to assign it to the sample data in the CSV. We are gonna use full path to make a difference, that means paired files should be in the same folder. If this is a problem, you should rename the files you want to merge. Sorry, no possible magic here." % os.path.basename(fn))
            return True
        used.add(os.path.basename(fn))
    return False

def _check_paired(files, force_single, separators):
    """check if files are fastq(.gz) and paired"""
    full_name = _check_stems(files)
    if files[0].endswith('.bam'):
        return files
    elif is_gsm(files[0]):
        return files
    return combine_pairs(files, force_single, full_name, separators)

def get_cluster_view(p):
    """get ipython running"""
    from cluster_helper import cluster as ipc
    return ipc.cluster_view(p['scheduler'], p['queue'], p['num_jobs'], p['cores_per_job'], start_wait=p['timeout'], extra_params={'resources': p['resources'], 'mem': p['mem'], 'tag': p['tag'], 'run_local': False})

def from_sample(sample):
    """Upload results of processing from an analysis pipeline sample.
    """
    upload_config = sample.get('upload')
    if upload_config:
        approach = _approaches[upload_config.get('method', 'filesystem')]
        for finfo in _get_files(sample):
            approach.update_file(finfo, sample, upload_config)
    return [[sample]]

def _get_files(sample):
    """Retrieve files for the sample, dispatching by analysis type.

    Each file is a dictionary containing the path plus associated
    metadata about the file and pipeline versions."""
    analysis = sample.get('analysis')
    if analysis.lower() in ['variant', 'snp calling', 'variant2', 'standard']:
        return _get_files_variantcall(sample)
    elif analysis.lower() in ['rna-seq', 'fastrna-seq']:
        return _get_files_rnaseq(sample)
    elif analysis.lower() in ['smallrna-seq']:
        return _get_files_srnaseq(sample)
    elif analysis.lower() in ['chip-seq']:
        return _get_files_chipseq(sample)
    elif analysis.lower() in ['scrna-seq']:
        return _get_files_scrnaseq(sample)
    else:
        return []

def _add_meta(xs, sample=None, config=None):
    """Add top level information about the sample or flowcell to output.

    Sorts outputs into sample names (sample input) and project (config input)."""
    out = []
    for x in xs:
        if not isinstance(x['path'], six.string_types) or not os.path.exists(x['path']):
            raise ValueError('Unexpected path for upload: %s' % x)
        x['mtime'] = shared.get_file_timestamp(x['path'])
        if sample:
            sample_name = dd.get_sample_name(sample)
            if 'sample' not in x:
                x['sample'] = sample_name
            elif x['sample'] != sample_name:
                x['run'] = sample_name
        if config:
            fc_name = config.get('fc_name') or 'project'
            fc_date = config.get('fc_date') or datetime.datetime.now().strftime('%Y-%m-%d')
            x['run'] = '%s_%s' % (fc_date, fc_name)
        out.append(x)
    return out

def _maybe_add_callable(data, out):
    """Add callable and depth regions to output folder.
    """
    callable_bed = dd.get_sample_callable(data)
    if callable_bed:
        out.append({'path': callable_bed, 'type': 'bed', 'ext': 'callable'})
    perbase_bed = tz.get_in(['depth', 'variant_regions', 'per_base'], data)
    if perbase_bed:
        out.append({'path': perbase_bed, 'type': 'bed.gz', 'ext': 'depth-per-base'})
    return out

def _get_variant_file(x, key, suffix='', sample=None, ignore_do_upload=False):
    """Retrieve VCF file with the given key if it exists, handling bgzipped.
    """
    out = []
    fname = utils.get_in(x, key)
    upload_key = list(key)
    upload_key[-1] = 'do_upload'
    do_upload = tz.get_in(tuple(upload_key), x, True)
    if fname and (ignore_do_upload or do_upload):
        if fname.endswith('.vcf.gz'):
            out.append({'path': fname, 'type': 'vcf.gz', 'ext': '%s%s' % (x['variantcaller'], suffix), 'variantcaller': x['variantcaller']})
            if utils.file_exists(fname + '.tbi'):
                out.append({'path': fname + '.tbi', 'type': 'vcf.gz.tbi', 'index': True, 'ext': '%s%s' % (x['variantcaller'], suffix), 'variantcaller': x['variantcaller']})
        elif fname.endswith(('.vcf', '.bed', '.bedpe', '.bedgraph', '.cnr', '.cns', '.cnn', '.txt', '.tsv')):
            ftype = utils.splitext_plus(fname)[-1][1:]
            if ftype == 'txt':
                extended_ftype = fname.split('-')[-1]
                if '/' not in extended_ftype:
                    ftype = extended_ftype
            out.append({'path': fname, 'type': ftype, 'ext': '%s%s' % (x['variantcaller'], suffix), 'variantcaller': x['variantcaller']})
    if sample:
        out_sample = []
        for x in out:
            x['sample'] = sample
            out_sample.append(x)
        return out_sample
    else:
        return out

def _flatten_file_with_secondary(input, out_dir):
    """Flatten file representation with secondary indices (CWL-like)
    """
    out = []
    orig_dir = os.path.dirname(input['base'])
    for finfo in [input['base']] + input.get('secondary', []):
        cur_dir = os.path.dirname(finfo)
        if cur_dir != orig_dir and cur_dir.startswith(orig_dir):
            cur_out_dir = os.path.join(out_dir, cur_dir.replace(orig_dir + '/', ''))
        else:
            cur_out_dir = out_dir
        out.append({'path': finfo, 'dir': cur_out_dir})
    return out

def _add_batch(x, sample):
    """Potentially add batch name to an upload file.
    """
    added = False
    for batch in sorted(dd.get_batches(sample) or [], key=len, reverse=True):
        if batch and os.path.basename(x['path']).startswith(('%s-' % batch, '%s.vcf' % batch)):
            x['batch'] = batch
            added = True
            break
    if not added:
        x['batch'] = dd.get_sample_name(sample)
    return x

def _get_project_vcf(x, suffix=''):
    """Get our project VCF, either from the population or the variant batch file.
    """
    vcfs = _get_variant_file(x, ('population', 'vcf'), suffix=suffix)
    if not vcfs:
        vcfs = _get_variant_file(x, ('vrn_file_batch',), suffix=suffix, ignore_do_upload=True)
        if not vcfs and x.get('variantcaller') == 'ensemble':
            vcfs = _get_variant_file(x, ('vrn_file',), suffix=suffix)
    return vcfs

def _id_remapper(orig, new):
    """Provide a dictionary remapping original read indexes to new indexes.

    When re-ordering the header, the individual read identifiers need to be
    updated as well."""
    new_chrom_to_index = {}
    for i_n, (chr_n, _) in enumerate(new):
        new_chrom_to_index[chr_n] = i_n
    remap_indexes = {}
    for i_o, (chr_o, _) in enumerate(orig):
        if chr_o in new_chrom_to_index.keys():
            remap_indexes[i_o] = new_chrom_to_index[chr_o]
    remap_indexes[None] = None
    return remap_indexes

def _clean_rec_name(rec):
    """Clean illegal characters in input fasta file which cause problems downstream.
    """
    out_id = []
    for char in list(rec.id):
        if char in ALLOWED_CONTIG_NAME_CHARS:
            out_id.append(char)
        else:
            out_id.append('_')
    rec.id = ''.join(out_id)
    rec.description = ''
    return rec

def _summarize_kraken(fn):
    """get the value at species level"""
    kraken = {}
    list_sp, list_value = ([], [])
    with open(fn) as handle:
        for line in handle:
            cols = line.strip().split('\t')
            sp = cols[5].strip()
            if len(sp.split(' ')) > 1 and (not sp.startswith('cellular')):
                list_sp.append(sp)
                list_value.append(cols[0])
    kraken = {'kraken_sp': list_sp, 'kraken_value': list_value}
    return kraken

def _run_tool(cmd, use_container=True, work_dir=None, log_file=None):
    """Run with injection of bcbio path.

    Place at end for runs without containers to avoid overriding other
    bcbio installations."""
    if isinstance(cmd, (list, tuple)):
        cmd = ' '.join([str(x) for x in cmd])
    cmd = utils.local_path_export(at_start=use_container) + cmd
    if log_file:
        cmd += ' 2>&1 | tee -a %s' % log_file
    try:
        print('Running: %s' % cmd)
        subprocess.check_call(cmd, shell=True)
    finally:
        if use_container and work_dir:
            _chown_workdir(work_dir)

def _chown_workdir(work_dir):
    """Ensure work directory files owned by original user.

    Docker runs can leave root owned files making cleanup difficult.
    Skips this if it fails, avoiding errors where we run remotely
    and don't have docker locally."""
    cmd = "docker run --rm -v %s:%s quay.io/bcbio/bcbio-base /bin/bash -c 'chown -R %s %s'" % (work_dir, work_dir, os.getuid(), work_dir)
    try:
        subprocess.check_call(cmd, shell=True)
    except subprocess.CalledProcessError:
        pass

def _run_wes(args):
    """Run CWL using a Workflow Execution Service (WES) endpoint
    """
    main_file, json_file, project_name = _get_main_and_json(args.directory)
    main_file = _pack_cwl(main_file)
    if args.host and 'stratus' in args.host:
        _run_wes_stratus(args, main_file, json_file)
    else:
        opts = ['--no-wait']
        if args.host:
            opts += ['--host', args.host]
        if args.auth:
            opts += ['--auth', args.auth]
        cmd = ['wes-client'] + opts + [main_file, json_file]
        _run_tool(cmd)

def _estimate_runner_memory(json_file):
    """Estimate Java memory requirements based on number of samples.

    A rough approach to selecting correct allocated memory for Cromwell."""
    with open(json_file) as in_handle:
        sinfo = json.load(in_handle)
    num_parallel = 1
    for key in ['config__algorithm__variantcaller', 'description']:
        item_counts = []
        n = 0
        for val in sinfo.get(key) or []:
            n += 1
            if val:
                if isinstance(val, (list, tuple)):
                    item_counts.append(len(val))
                else:
                    item_counts.append(1)
        print(key, n, item_counts)
        if n and item_counts:
            num_parallel = n * max(item_counts)
            break
    if num_parallel < 25:
        return '3g'
    if num_parallel < 150:
        return '6g'
    elif num_parallel < 500:
        return '12g'
    else:
        return '24g'

def _cromwell_debug(metadata):
    """Format Cromwell failures to make debugging easier.
    """
    def get_failed_calls(cur, key=None):
        if key is None:
            key = []
        out = []
        if isinstance(cur, dict) and 'failures' in cur and ('callRoot' in cur):
            out.append((key, cur))
        elif isinstance(cur, dict):
            for k, v in cur.items():
                out.extend(get_failed_calls(v, key + [k]))
        elif isinstance(cur, (list, tuple)):
            for i, v in enumerate(cur):
                out.extend(get_failed_calls(v, key + [i]))
        return out
    print('Failed bcbio Cromwell run')
    print('-------------------------')
    for fail_k, fail_call in get_failed_calls(metadata['calls']):
        root_dir = os.path.join('cromwell_work', os.path.relpath(fail_call['callRoot']))
        print('Failure in step: %s' % '.'.join([str(x) for x in fail_k]))
        print('  bcbio log file     : %s' % os.path.join(root_dir, 'execution', 'log', 'bcbio-nextgen-debug.log'))
        print('  bcbio commands file: %s' % os.path.join(root_dir, 'execution', 'log', 'bcbio-nextgen-commands.log'))
        print('  Cromwell directory : %s' % root_dir)
        print()

def _parse_qualimap_metrics(report_file, data):
    """Extract useful metrics from the qualimap HTML report file.
    """
    if not utils.file_exists(report_file):
        return {}
    from bs4 import BeautifulSoup
    out = {}
    parsers = {'Globals': _parse_qualimap_globals, 'Globals (inside of regions)': _parse_qualimap_globals_inregion, 'Coverage': _parse_qualimap_coverage, 'Coverage (inside of regions)': _parse_qualimap_coverage, 'Insert size': _parse_qualimap_insertsize, 'Insert size (inside of regions)': _parse_qualimap_insertsize}
    with open(report_file) as in_handle:
        root = BeautifulSoup(in_handle.read(), 'html.parser')
    for table in root.find_all('div', class_='table-summary'):
        h3 = table.find('h3')
        if h3.text in parsers:
            out.update(parsers[h3.text](table.find('table')))
    new_names = []
    for metric in out:
        if 'qualimap_full' not in tz.get_in(('config', 'algorithm', 'tools_on'), data, []):
            metric += '_qualimap_1e7reads_est'
        new_names.append(metric)
    out = dict(zip(new_names, out.values()))
    return out

def _parse_qualimap_globals(table):
    """Retrieve metrics of interest from globals table.
    """
    out = {}
    want = {'Mapped reads': _parse_num_pct, 'Duplication rate': lambda k, v: {k: v}}
    for row in table.find_all('tr'):
        col, val = [x.text for x in row.find_all('td')]
        if col in want:
            out.update(want[col](col, val))
    return out

def _parse_qualimap_globals_inregion(table):
    """Retrieve metrics from the global targeted region table.
    """
    out = {}
    for row in table.find_all('tr'):
        col, val = [x.text for x in row.find_all('td')]
        if col == 'Mapped reads':
            out.update(_parse_num_pct('%s (in regions)' % col, val))
    return out

def _parse_qualimap_coverage(table):
    """Parse summary qualimap coverage metrics.
    """
    out = {}
    for row in table.find_all('tr'):
        col, val = [x.text for x in row.find_all('td')]
        if col == 'Mean':
            out['Coverage (Mean)'] = val
    return out

def _transform_browser_coor(rRNA_interval, rRNA_coor):
    """transform interval format to browser coord: chr:start-end"""
    with open(rRNA_coor, 'w') as out_handle:
        with open(rRNA_interval, 'r') as in_handle:
            for line in in_handle:
                c, bio, source, s, e = line.split('\t')[:5]
                if bio.startswith('rRNA'):
                    out_handle.write('{0}:{1}-{2}\n'.format(c, s, e))

def _parse_qualimap_rnaseq(table):
    """Retrieve metrics of interest from globals table."""
    out = {}
    for row in table.find_all('tr'):
        col, val = [x.text for x in row.find_all('td')]
        col = col.replace(':', '').strip()
        val = val.replace(',', '')
        m = {col: val}
        if val.find('/') > -1:
            m = _parse_num_pct(col, val.replace('%', ''))
        out.update(m)
    return out

def _parse_rnaseq_qualimap_metrics(report_file):
    """Extract useful metrics from the qualimap HTML report file.
    """
    from bs4 import BeautifulSoup
    out = {}
    parsers = ['Reads alignment', 'Reads genomic origin', 'Transcript coverage profile']
    with open(report_file) as in_handle:
        root = BeautifulSoup(in_handle.read(), 'html.parser')
    for table in root.find_all('div', class_='table-summary'):
        h3 = table.find('h3')
        if h3.text in parsers:
            out.update(_parse_qualimap_rnaseq(table.find('table')))
    return out

def classifyplot_from_plotfiles(plot_files, out_csv, outtype='png', title=None, size=None):
    """Create a plot from individual summary csv files with classification metrics.
    """
    dfs = [pd.read_csv(x) for x in plot_files]
    samples = []
    for df in dfs:
        for sample in df['sample'].unique():
            if sample not in samples:
                samples.append(sample)
    df = pd.concat(dfs)
    df.to_csv(out_csv, index=False)
    return classifyplot_from_valfile(out_csv, outtype, title, size, samples)

def _calculate_fnr_fdr(group):
    """Calculate the false negative rate (1 - sensitivity) and false discovery rate (1 - precision).
    """
    data = {k: d['value'] for k, d in group.set_index('metric').T.to_dict().items()}
    return pd.DataFrame([{'fnr': data['fn'] / float(data['tp'] + data['fn']) * 100.0 if data['tp'] > 0 else 0.0, 'fdr': data['fp'] / float(data['tp'] + data['fp']) * 100.0 if data['tp'] > 0 else 0.0, 'tpr': 'TP: %s FN: %s' % (data['tp'], data['fn']), 'spc': 'FP: %s' % data['fp']}])

def _check_cats(cats, vtypes, df, prep, callers):
    """Only include categories in the final output if they have values.
    """
    out = []
    for cat in cats:
        all_vals = []
        for vtype in vtypes:
            vals, labels, maxval = _get_chart_info(df, vtype, cat, prep, callers)
            all_vals.extend(vals)
        if sum(all_vals) / float(len(all_vals)) > 2:
            out.append(cat)
    if len(out) == 0:
        return cats
    else:
        return out

def _get_chart_info(df, vtype, cat, prep, callers):
    """Retrieve values for a specific variant type, category and prep method.
    """
    maxval_raw = max(list(df['value.floor']))
    curdf = df[(df['variant.type'] == vtype) & (df['category'] == cat) & (df['bamprep'] == prep)]
    vals = []
    labels = []
    for c in callers:
        row = curdf[df['caller'] == c]
        if len(row) > 0:
            vals.append(list(row['value.floor'])[0])
            labels.append(list(row['value'])[0])
        else:
            vals.append(1)
            labels.append('')
    return (vals, labels, maxval_raw)

def _annotate(ax, annotate, height, left, width):
    """Annotate axis with labels.
    """
    annotate_yrange_factor = 0.01
    xticks = np.array(left) + width / 2.0
    ymin, ymax = ax.get_ylim()
    yrange = ymax - ymin
    if ymax > 0:
        ymax += yrange * 0.15
    if ymin < 0:
        ymin -= yrange * 0.15
    ax.set_ylim(ymin, ymax)
    yrange = ymax - ymin
    offset_ = yrange * annotate_yrange_factor
    if isinstance(annotate, collections.Iterable):
        annotations = map(str, annotate)
    else:
        annotations = ['%.3f' % h if type(h) is np.float_ else str(h) for h in height]
    for x, h, annotation in zip(xticks, height, annotations):
        offset = offset_ if h >= 0 else -1 * offset_
        verticalalignment = 'bottom' if h >= 0 else 'top'
        if len(str(annotation)) > 6:
            size = 7
        elif len(str(annotation)) > 5:
            size = 8
        else:
            size = 10
        ax.annotate(annotation, (x, h + offset), verticalalignment=verticalalignment, horizontalalignment='center', size=size)

def get_group_floors(df, cat_labels):
    """Retrieve the floor for a given row of comparisons, creating a normalized set of differences.

    We need to set non-zero floors so large numbers (like concordance) don't drown out small
    numbers (like discordance). This defines the height for a row of comparisons as either
    the minimum height of any sub-plot, or the maximum difference between higher and lower
    (plus 10%)."""
    group_maxes = collections.defaultdict(list)
    group_diffs = collections.defaultdict(list)
    diff_pad = 0.1
    for name, group in df.groupby(['category', 'variant.type']):
        label, stype = name
        if label in cat_labels:
            diff = max(group['value']) - min(group['value'])
            group_diffs[stype].append(diff + int(diff_pad * diff))
            group_maxes[stype].append(max(group['value']))
        group_maxes[name].append(max(group['value']))
    out = {}
    for k, vs in group_maxes.items():
        if k in group_diffs:
            out[k] = max(max(group_diffs[stype]), min(vs))
        else:
            out[k] = min(vs)
    return out

def _sanity_check_args(args):
    """Ensure dependent arguments are correctly specified
    """
    if 'scheduler' in args and 'queue' in args:
        if args.scheduler and (not args.queue):
            if args.scheduler != 'sge':
                return 'IPython parallel scheduler (-s) specified. This also requires a queue (-q).'
        elif args.queue and (not args.scheduler):
            return 'IPython parallel queue (-q) supplied. This also requires a scheduler (-s).'
        elif args.paralleltype == 'ipython' and (not args.queue or not args.scheduler):
            return 'IPython parallel requires queue (-q) and scheduler (-s) arguments.'

def _add_commas(s, sep=','):
    """Add commas to output counts.

    From: http://code.activestate.com/recipes/498181"""
    if len(s) <= 3:
        return s
    return _add_commas(s[:-3], sep) + sep + s[-3:]

def standard_cl_params(items):
    """Shared command line parameters for GATK programs.

    Handles no removal of duplicate reads for amplicon or
    non mark duplicate experiments. If we have pre-aligned inputs we
    ignore the value or mark duplicates (since they may already be
    marked in the input BAM)."""
    out = []
    def _skip_duplicates(data):
        return dd.get_coverage_interval(data) == 'amplicon' or (dd.get_aligner(data) and (not dd.get_mark_duplicates(data)))
    if any((_skip_duplicates(d) for d in items)):
        broad_runner = broad.runner_from_config(items[0]['config'])
        gatk_type = broad_runner.gatk_type()
        if gatk_type == 'gatk4':
            out += ['--disable-read-filter', 'NotDuplicateReadFilter']
        elif LooseVersion(broad_runner.gatk_major_version()) >= LooseVersion('3.5'):
            out += ['-drf', 'DuplicateRead']
    return out

def _shared_gatk_call_prep(align_bams, items, ref_file, region, out_file, num_cores=1):
    """Shared preparation work for GATK variant calling.
    """
    data = items[0]
    config = data['config']
    broad_runner = broad.runner_from_config(config)
    gatk_type = broad_runner.gatk_type()
    for x in align_bams:
        bam.index(x, config)
    picard_runner = broad.runner_from_path('picard', config)
    picard_runner.run_fn('picard_index_ref', ref_file)
    params = ['-R', ref_file]
    coverage_depth_min = tz.get_in(['algorithm', 'coverage_depth_min'], config)
    if coverage_depth_min and coverage_depth_min < 4:
        confidence = '4.0'
        params += ['--standard_min_confidence_threshold_for_calling', confidence]
    for a in annotation.get_gatk_annotations(config):
        params += ['--annotation', a]
    for x in align_bams:
        params += ['-I', x]
    variant_regions = bedutils.population_variant_regions(items)
    region = subset_variant_regions(variant_regions, region, out_file, items)
    if region:
        if gatk_type == 'gatk4':
            params += ['-L', bamprep.region_to_gatk(region), '--interval-set-rule', 'INTERSECTION']
        else:
            params += ['-L', bamprep.region_to_gatk(region), '--interval_set_rule', 'INTERSECTION']
    params += standard_cl_params(items)
    return (broad_runner, params)

def unified_genotyper(align_bams, items, ref_file, assoc_files, region=None, out_file=None):
    """Perform SNP genotyping on the given alignment file.
    """
    if out_file is None:
        out_file = '%s-variants.vcf.gz' % utils.splitext_plus(align_bams[0])[0]
    if not utils.file_exists(out_file):
        broad_runner, params = _shared_gatk_call_prep(align_bams, items, ref_file, region, out_file)
        with file_transaction(items[0], out_file) as tx_out_file:
            params += ['-T', 'UnifiedGenotyper', '-o', tx_out_file, '-ploidy', str(ploidy.get_ploidy(items, region)) if broad_runner.gatk_type() == 'restricted' else '2', '--genotype_likelihoods_model', 'BOTH']
            resources = config_utils.get_resources('gatk', items[0]['config'])
            if 'options' in resources:
                params += [str(x) for x in resources.get('options', [])]
            broad_runner.run_gatk(params)
    return vcfutils.bgzip_and_index(out_file, items[0]['config'])

def _supports_avx():
    """Check for support for Intel AVX acceleration."""
    if os.path.exists('/proc/cpuinfo'):
        with open('/proc/cpuinfo') as in_handle:
            for line in in_handle:
                if line.startswith('flags') and line.find('avx') > 0:
                    return True

def jar_versioner(program_name, jar_name):
    """Retrieve version information based on jar file.
    """
    def get_version(config):
        try:
            pdir = config_utils.get_program(program_name, config, 'dir')
        except ValueError:
            return ''
        jar = os.path.basename(config_utils.get_jar(jar_name, pdir))
        for to_remove in [jar_name, '.jar', '-standalone']:
            jar = jar.replace(to_remove, '')
        if jar.startswith(('-', '.')):
            jar = jar[1:]
        if not jar:
            logger.warn("Unable to determine version for program '{}' from jar file {}".format(program_name, config_utils.get_jar(jar_name, pdir)))
        return jar
    return get_version

def _get_cl_version(p, config):
    """Retrieve version of a single commandline program.
    """
    if not p.get('has_cl_version', True):
        return ''
    try:
        prog = config_utils.get_program(p['cmd'], config)
    except config_utils.CmdNotFound:
        localpy_cmd = os.path.join(os.path.dirname(sys.executable), p['cmd'])
        if os.path.exists(localpy_cmd):
            prog = localpy_cmd
        else:
            return ''
    args = p.get('args', '')
    cmd = '{prog} {args}'
    subp = subprocess.Popen(cmd.format(**locals()), stdout=subprocess.PIPE, stderr=subprocess.STDOUT, shell=True)
    with contextlib.closing(subp.stdout) as stdout:
        if p.get('stdout_flag'):
            v = _parse_from_stdoutflag(stdout, p['stdout_flag'])
        elif p.get('paren_flag'):
            v = _parse_from_parenflag(stdout, p['paren_flag'])
        else:
            lines = [l.strip() for l in str(stdout.read()).split('\n') if l.strip()]
            v = lines[-1]
    if v.endswith('.'):
        v = v[:-1]
    return v

def _get_brew_versions():
    """Retrieve versions of tools installed via brew.
    """
    from bcbio import install
    tooldir = install.get_defaults().get('tooldir')
    brew_cmd = os.path.join(tooldir, 'bin', 'brew') if tooldir else 'brew'
    try:
        vout = subprocess.check_output([brew_cmd, 'list', '--versions'])
    except OSError:
        vout = ''
    out = {}
    for vstr in vout.split('\n'):
        if vstr.strip():
            parts = vstr.rstrip().split()
            name = parts[0]
            v = parts[-1]
            out[name] = v
    return out

def _get_versions(config=None):
    """Retrieve details on all programs available on the system.
    """
    try:
        from bcbio.pipeline import version
        if hasattr(version, '__version__'):
            bcbio_version = '%s-%s' % (version.__version__, version.__git_revision__) if version.__git_revision__ else version.__version__
        else:
            bcbio_version = ''
    except ImportError:
        bcbio_version = ''
    out = [{'program': 'bcbio-nextgen', 'version': bcbio_version}]
    manifest_dir = _get_manifest_dir(config)
    manifest_vs = _get_versions_manifest(manifest_dir) if manifest_dir else []
    if manifest_vs:
        out += manifest_vs
    else:
        assert config is not None, 'Need configuration to retrieve from non-manifest installs'
        brew_vs = _get_brew_versions()
        for p in _cl_progs:
            out.append({'program': p['cmd'], 'version': brew_vs[p['cmd']] if p['cmd'] in brew_vs else _get_cl_version(p, config)})
        for p in _alt_progs:
            out.append({'program': p['name'], 'version': brew_vs[p['name']] if p['name'] in brew_vs else p['version_fn'](config)})
    out.sort(key=lambda x: x['program'])
    return out

def _get_manifest_dir(data=None, name=None):
    """get manifest directory from the data dictionary, falling back on alternatives
    it prefers, in order:
    1. locating it from the bcbio_system.yaml file
    2. locating it from the galaxy directory
    3. location it from the python executable.

    it can accept either the data or config dictionary"""
    manifest_dir = None
    if data:
        bcbio_system = tz.get_in(['config', 'bcbio_system'], data, None)
        bcbio_system = bcbio_system if bcbio_system else data.get('bcbio_system', None)
        if bcbio_system:
            sibling_dir = os.path.normpath(os.path.dirname(bcbio_system))
        else:
            sibling_dir = dd.get_galaxy_dir(data)
        if sibling_dir:
            manifest_dir = os.path.normpath(os.path.join(sibling_dir, os.pardir, 'manifest'))
    if not manifest_dir or not os.path.exists(manifest_dir):
        manifest_dir = os.path.join(config_utils.get_base_installdir(), 'manifest')
        if not os.path.exists(manifest_dir) and name:
            manifest_dir = os.path.join(config_utils.get_base_installdir(name), 'manifest')
    return manifest_dir

def _get_versions_manifest(manifest_dir):
    """Retrieve versions from a pre-existing manifest of installed software.
    """
    all_pkgs = _manifest_progs + [p.get('name', p['cmd']) for p in _cl_progs] + [p['name'] for p in _alt_progs]
    if os.path.exists(manifest_dir):
        out = []
        for plist in ['toolplus', 'python', 'r', 'debian', 'custom']:
            pkg_file = os.path.join(manifest_dir, '%s-packages.yaml' % plist)
            if os.path.exists(pkg_file):
                with open(pkg_file) as in_handle:
                    pkg_info = yaml.safe_load(in_handle)
                if not pkg_info:
                    continue
                added = []
                for pkg in all_pkgs:
                    if pkg in pkg_info:
                        added.append(pkg)
                        out.append({'program': pkg, 'version': pkg_info[pkg]['version']})
                for x in added:
                    all_pkgs.remove(x)
        out.sort(key=lambda x: x['program'])
        for pkg in all_pkgs:
            out.append({'program': pkg, 'version': ''})
        return out

def write_versions(dirs, config=None, is_wrapper=False):
    """Write CSV file with versions used in analysis pipeline.
    """
    out_file = _get_program_file(dirs)
    if is_wrapper:
        assert utils.file_exists(out_file), 'Failed to create program versions from VM'
    elif out_file is None:
        for p in _get_versions(config):
            print('{program},{version}'.format(**p))
    else:
        with open(out_file, 'w') as out_handle:
            for p in _get_versions(config):
                out_handle.write('{program},{version}\n'.format(**p))
    return out_file

def get_version_manifest(name, data=None, required=False):
    """Retrieve a version from the currently installed manifest.
    """
    manifest_dir = _get_manifest_dir(data, name)
    manifest_vs = _get_versions_manifest(manifest_dir) or []
    for x in manifest_vs:
        if x['program'] == name:
            v = x.get('version', '')
            if v:
                return v
    if required:
        raise ValueError('Did not find %s in install manifest. Could not check version.' % name)
    return ''

def get_version(name, dirs=None, config=None):
    """Retrieve the current version of the given program from cached names.
    """
    if dirs:
        p = _get_program_file(dirs)
    else:
        p = tz.get_in(['resources', 'program_versions'], config)
    if p:
        with open(p) as in_handle:
            for line in in_handle:
                prog, version = line.rstrip().split(',')
                if prog == name and version:
                    return version
        raise KeyError('Version information not found for %s in %s' % (name, p))

def hla_choices(orig_hla, min_parts=2):
    """Provide a range of options for HLA type, with decreasing resolution.
    """
    yield orig_hla
    try:
        int(orig_hla[-1])
    except ValueError:
        yield orig_hla[:-1]
    hla_parts = orig_hla.split(':')
    for sub_i in range(len(hla_parts) - min_parts + 1):
        yield ':'.join(hla_parts[:len(hla_parts) - sub_i])

def read_pgroups(in_file):
    """Read HLAs and the pgroups they fall in.
    """
    out = {}
    with open(in_file) as in_handle:
        for line in (l for l in in_handle if not l.startswith('#')):
            locus, alleles, group = line.strip().split(';')
            for allele in alleles.split('/'):
                out['HLA-%s%s' % (locus, allele)] = group
    return out

def read_hlas(fasta_fai):
    """Get HLA alleles from the hg38 fasta fai file.
    """
    out = []
    with open(fasta_fai) as in_handle:
        for line in in_handle:
            if line.startswith('HLA'):
                out.append(line.split()[0])
    return out

def apply_recal(data):
    """Apply recalibration tables to the sorted aligned BAM, producing recalibrated BAM.
    """
    orig_bam = dd.get_align_bam(data) or dd.get_work_bam(data)
    had_work_bam = 'work_bam' in data
    if dd.get_recalibrate(data) in [True, 'gatk']:
        if data.get('prep_recal'):
            logger.info('Applying BQSR recalibration with GATK: %s ' % str(dd.get_sample_name(data)))
            data['work_bam'] = _gatk_apply_bqsr(data)
    elif dd.get_recalibrate(data) == 'sentieon':
        if data.get('prep_recal'):
            logger.info('Applying BQSR recalibration with sentieon: %s ' % str(dd.get_sample_name(data)))
            data['work_bam'] = sentieon.apply_bqsr(data)
    elif dd.get_recalibrate(data):
        raise NotImplementedError('Unsupported recalibration type: %s' % dd.get_recalibrate(data))
    if not had_work_bam and dd.get_work_bam(data):
        data['align_bam'] = dd.get_work_bam(data)
    if orig_bam != dd.get_work_bam(data) and orig_bam != dd.get_align_bam(data):
        utils.save_diskspace(orig_bam, 'BAM recalibrated to %s' % dd.get_work_bam(data), data['config'])
    return data

def setup_local_logging(config=None, parallel=None):
    """Setup logging for a local context, directing messages to appropriate base loggers.

    Handles local, multiprocessing and distributed setup, connecting
    to handlers created by the base logger."""
    if config is None:
        config = {}
    if parallel is None:
        parallel = {}
    parallel_type = parallel.get('type', 'local')
    cores = parallel.get('cores', 1)
    wrapper = parallel.get('wrapper', None)
    if parallel_type == 'ipython':
        from bcbio.log import logbook_zmqpush
        handler = logbook_zmqpush.ZeroMQPushHandler(parallel['log_queue'])
    elif cores > 1:
        handler = logbook.queues.MultiProcessingHandler(mpq)
    else:
        handler = _create_log_handler(config, direct_hostname=wrapper is not None, write_toterm=wrapper is None)
    handler.push_thread()
    return handler

def _wf_to_dict(wf, records):
    """Parse a workflow into cwl2wdl style dictionaries for base and sub-workflows.
    """
    inputs, outputs, records = _get_wf_inout(wf, records)
    out = {'name': _id_to_name(_clean_id(wf.tool['id'])), 'inputs': inputs, 'outputs': outputs, 'steps': [], 'subworkflows': [], 'requirements': []}
    for step in wf.steps:
        is_subworkflow = isinstance(step.embedded_tool, cwltool.workflow.Workflow)
        inputs, outputs, remapped, prescatter = _get_step_inout(step)
        inputs, scatter = _organize_step_scatter(step, inputs, remapped)
        if is_subworkflow:
            wf_def, records = _wf_to_dict(step.embedded_tool, records)
            out['subworkflows'].append({'id': '%s.%s' % (wf_def['name'], wf_def['name']), 'definition': wf_def, 'inputs': inputs, 'outputs': outputs, 'scatter': scatter, 'prescatter': prescatter})
        else:
            task_def, records = _tool_to_dict(step.embedded_tool, records, remapped)
            out['steps'].append({'task_id': task_def['name'], 'task_definition': task_def, 'inputs': inputs, 'outputs': outputs, 'scatter': scatter, 'prescatter': prescatter})
    return (out, records)

def _get_step_inout(step):
    """Retrieve set of inputs and outputs connecting steps.
    """
    inputs = []
    outputs = []
    prescatter = collections.defaultdict(list)
    remapped = {}
    assert step.outputs_record_schema['type'] == 'record'
    output_names = set([])
    for outp in step.outputs_record_schema['fields']:
        outputs.append({'id': outp['name']})
        output_names.add(outp['name'])
    assert step.inputs_record_schema['type'] == 'record'
    for inp in step.inputs_record_schema['fields']:
        source = inp['source'].split('#')[-1].replace('/', '.')
        if 'valueFrom' in inp:
            attr_access = "['%s']" % inp['name']
            if inp['valueFrom'].find(attr_access) > 0:
                source += '.%s' % inp['name']
                if isinstance(inp['type'], dict) and isinstance(inp['type'].get('items'), dict):
                    if inp['type']['items'].get('type') == 'array' and 'inputBinding' in inp['type']:
                        source, prescatter = _unpack_object_array(inp, source, prescatter)
        if inp['name'] in output_names:
            new_name = inp['name'] + '_input'
            remapped[inp['name']] = new_name
            inp['name'] = new_name
        inputs.append({'id': inp['name'], 'value': source})
    return (inputs, outputs, remapped, dict(prescatter))

def _organize_step_scatter(step, inputs, remapped):
    """Add scattering information from inputs, remapping input variables.
    """
    def extract_scatter_id(inp):
        _, ns_var = inp.split('#')
        _, var = ns_var.split('/')
        return var
    scatter_local = {}
    if 'scatter' in step.tool:
        assert step.tool['scatterMethod'] == 'dotproduct', 'Only support dotproduct scattering in conversion to WDL'
        inp_val = collections.OrderedDict()
        for x in inputs:
            inp_val[x['id']] = x['value']
        for scatter_key in [extract_scatter_id(x) for x in step.tool['scatter']]:
            scatter_key = remapped.get(scatter_key) or scatter_key
            val = inp_val[scatter_key]
            if len(val.split('.')) in [1, 2]:
                base_key = val
                attr = None
            elif len(val.split('.')) == 3:
                orig_location, record, attr = val.split('.')
                base_key = '%s.%s' % (orig_location, record)
            else:
                raise ValueError('Unexpected scatter input: %s' % val)
            local_ref = base_key.split('.')[-1] + '_local'
            scatter_local[base_key] = local_ref
            if attr:
                local_ref += '.%s' % attr
            inp_val[scatter_key] = local_ref
            inputs = [{'id': iid, 'value': ival} for iid, ival in inp_val.items()]
    return (inputs, [(v, k) for k, v in scatter_local.items()])

def _record_to_struct(cur_rec, records):
    """Convert a CWL record into a WDL struct/Object.

    Work in progress to support changes to WDL Objects to
    be defined in structs."""
    def to_camel_case(x):
        def uppercase_word(w):
            return w[0].upper() + w[1:]
        return ''.join((uppercase_word(w) for w in x.split('_')))
    struct_name = to_camel_case(cur_rec['name'].split('/')[-1])
    if struct_name not in records:
        records[struct_name] = collections.OrderedDict()
        for field in cur_rec['fields']:
            field_type, records = _to_variable_type(field['type'], records)
            records[struct_name][field['name'].split('/')[-1]] = field_type
    return (struct_name, records)

def _to_variable_type(x, records):
    """Convert CWL variables to WDL variables, handling nested arrays.
    """
    var_mapping = {'string': 'String', 'File': 'File', 'null': 'String', 'long': 'Float', 'double': 'Float', 'int': 'Int'}
    if isinstance(x, dict):
        if x['type'] == 'record':
            struct_name, records = _record_to_struct(x, records)
            return (struct_name, records)
        else:
            assert x['type'] == 'array', x
            cur_type, records = _to_variable_type(x['items'], records)
            return ('Array[%s]' % cur_type, records)
    elif isinstance(x, (list, tuple)):
        vars = [v for v in x if v != 'null']
        return (var_mapping[vars[0]], records)
    else:
        return (var_mapping[x], records)

def _input_to_dict(i, records, remapped=None):
    """Convert CWL input into dictionary required for a cwl2wdl Input object.
    """
    if not remapped:
        remapped = {}
    var_type, records = _to_variable_type(i['type'], records)
    if var_type.startswith('Array') and 'inputBinding' in i.get('type', {}):
        ib = i['type']['inputBinding']
    elif 'inputBinding' in i:
        ib = i['inputBinding']
    else:
        ib = {'prefix': None, 'itemSeparator': ';;', 'position': None}
    name = _id_to_localname(i['id']) if 'id' in i else i['name']
    return ({'name': remapped.get(name) or name, 'variable_type': var_type, 'prefix': ib['prefix'], 'separator': ib['itemSeparator'], 'position': ib['position'], 'is_required': True, 'default': i.get('default', None), 'separate': ib.get('separate', True)}, records)

def _tool_to_dict(tool, records, remapped):
    """Parse a tool definition into a cwl2wdl style dictionary.
    """
    requirements = _requirements_to_dict(tool.requirements + tool.hints)
    inputs = []
    outputs = []
    for inp in tool.tool['inputs']:
        ready_inp, records = _input_to_dict(inp, records, remapped)
        inputs.append(ready_inp)
    for outp in tool.tool['outputs']:
        ready_outp, records = _output_to_dict(outp, records)
        outputs.append(ready_outp)
    out = {'name': _id_to_name(tool.tool['id']), 'baseCommand': ' '.join(tool.tool['baseCommand']), 'arguments': [_arg_to_dict(a, requirements) for a in tool.tool['arguments']], 'inputs': inputs, 'outputs': outputs, 'requirements': requirements, 'stdin': None, 'stdout': None}
    return (out, records)

def _requirements_to_dict(rs):
    """Convert supported requirements into dictionary for output.
    """
    out = []
    added = set([])
    for r in rs:
        if r['class'] == 'DockerRequirement' and 'docker' not in added:
            added.add('docker')
            out.append({'requirement_type': 'docker', 'value': r['dockerImageId']})
        elif r['class'] == 'ResourceRequirement':
            if 'coresMin' in r and 'cpu' not in added:
                added.add('cpu')
                out.append({'requirement_type': 'cpu', 'value': r['coresMin']})
            if 'ramMin' in r and 'memory' not in added:
                added.add('memory')
                out.append({'requirement_type': 'memory', 'value': '%s MB' % r['ramMin']})
            if 'tmpdirMin' in r and 'disks' not in added:
                added.add('disks')
                out.append({'requirement_type': 'disks', 'value': 'local-disk %s HDD' % r['tmpdirMin']})
    return out

def _export_to_vcf(cur):
    """Convert PURPLE custom output into VCF.
    """
    if float(cur['copyNumber']) > 2.0:
        svtype = 'DUP'
    elif float(cur['copyNumber']) < 2.0:
        svtype = 'DEL'
    else:
        svtype = None
    if svtype:
        info = ['END=%s' % cur['end'], 'SVLEN=%s' % (int(cur['end']) - int(cur['start'])), 'SVTYPE=%s' % svtype, 'CN=%s' % cur['copyNumber'], 'PROBES=%s' % cur['depthWindowCount']]
        return [cur['chromosome'], cur['start'], '.', 'N', '<%s>' % svtype, '.', '.', ';'.join(info), 'GT', '0/1']

def _comparison_stats_from_merge(in_file, stats, svcaller, data):
    """Extract true/false positive/negatives from a merged SURIVOR VCF.
    """
    truth_stats = {'tp': [], 'fn': [], 'fp': []}
    samples = ['truth' if x.endswith('-truth') else 'eval' for x in vcfutils.get_samples(in_file)]
    with open(in_file) as in_handle:
        for call in (l.rstrip().split('\t') for l in in_handle if not l.startswith('#')):
            supp_vec_str = [x for x in call[7].split(';') if x.startswith('SUPP_VEC=')][0]
            _, supp_vec = supp_vec_str.split('=')
            calls = dict(zip(samples, [int(x) for x in supp_vec]))
            if calls['truth'] and calls['eval']:
                metric = 'tp'
            elif calls['truth']:
                metric = 'fn'
            else:
                metric = 'fp'
            truth_stats[metric].append(_summarize_call(call))
    return _to_csv(truth_stats, stats, dd.get_sample_name(data), svcaller)

def _get_start_end(parts, index=7):
    """Retrieve start and end for a VCF record, skips BNDs without END coords
    """
    start = parts[1]
    end = [x.split('=')[-1] for x in parts[index].split(';') if x.startswith('END=')]
    if end:
        end = end[0]
        return (start, end)
    return (None, None)

def _get_anns_to_remove(in_file):
    """Find larger annotations, if present in VCF, that slow down processing.
    """
    to_remove = ['ANN', 'LOF']
    to_remove_str = tuple(['##INFO=<ID=%s' % x for x in to_remove])
    cur_remove = []
    with utils.open_gzipsafe(in_file) as in_handle:
        for line in in_handle:
            if not line.startswith('#'):
                break
            elif line.startswith(to_remove_str):
                cur_id = line.split('ID=')[-1].split(',')[0]
                cur_remove.append('INFO/%s' % cur_id)
    return ','.join(cur_remove)

def cnv_to_event(name, data):
    """Convert a CNV to an event name.
    """
    cur_ploidy = ploidy.get_ploidy([data])
    if name.startswith('cnv'):
        num = max([int(x) for x in name.split('_')[0].replace('cnv', '').split(';')])
        if num < cur_ploidy:
            return 'DEL'
        elif num > cur_ploidy:
            return 'DUP'
        else:
            return name
    else:
        return name

def _evaluate_one(caller, svtype, size_range, ensemble, truth, data):
    """Compare a ensemble results for a caller against a specific caller and SV type.
    """
    def cnv_matches(name):
        return cnv_to_event(name, data) == svtype
    def is_breakend(name):
        return name.startswith('BND')
    def in_size_range(max_buffer=0):
        def _work(feat):
            minf, maxf = size_range
            buffer = min(max_buffer, int((maxf + minf) / 2.0 / 10.0))
            size = feat.end - feat.start
            return size >= max([0, minf - buffer]) and size < maxf + buffer
        return _work
    def is_caller_svtype(feat):
        for name in feat.name.split(','):
            if (name.startswith(svtype) or cnv_matches(name) or is_breakend(name)) and (caller == 'sv-ensemble' or name.endswith(caller)):
                return True
        return False
    minf, maxf = size_range
    efeats = pybedtools.BedTool(ensemble).filter(in_size_range(0)).filter(is_caller_svtype).saveas().sort().merge()
    tfeats = pybedtools.BedTool(truth).filter(in_size_range(0)).sort().merge().saveas()
    etotal = efeats.count()
    ttotal = tfeats.count()
    match = efeats.intersect(tfeats, u=True).sort().merge().saveas().count()
    return {'sensitivity': _stat_str(match, ttotal), 'precision': _stat_str(match, etotal)}

def evaluate(data):
    """Provide evaluations for multiple callers split by structural variant type.
    """
    work_dir = utils.safe_makedir(os.path.join(data['dirs']['work'], 'structural', dd.get_sample_name(data), 'validate'))
    truth_sets = tz.get_in(['config', 'algorithm', 'svvalidate'], data)
    if truth_sets and data.get('sv'):
        if isinstance(truth_sets, dict):
            val_summary, df_csv = _evaluate_multi(data['sv'], truth_sets, work_dir, data)
            summary_plots = _plot_evaluation(df_csv)
            data['sv-validate'] = {'csv': val_summary, 'plot': summary_plots, 'df': df_csv}
        else:
            assert isinstance(truth_sets, six.string_types) and utils.file_exists(truth_sets), truth_sets
            val_summary = _evaluate_vcf(data['sv'], truth_sets, work_dir, data)
            title = '%s structural variants' % dd.get_sample_name(data)
            summary_plots = validateplot.classifyplot_from_valfile(val_summary, outtype='png', title=title)
            data['sv-validate'] = {'csv': val_summary, 'plot': summary_plots[0] if len(summary_plots) > 0 else None}
    return data

def _add_tumor_params(paired, items, gatk_type):
    """Add tumor/normal BAM input parameters to command line.
    """
    params = []
    if not paired:
        raise ValueError("Specified MuTect2 calling but 'tumor' phenotype not present in batch\nhttps://bcbio-nextgen.readthedocs.org/en/latest/contents/pipelines.html#cancer-variant-calling\nfor samples: %s" % ', '.join([dd.get_sample_name(x) for x in items]))
    if gatk_type == 'gatk4':
        params += ['-I', paired.tumor_bam]
        params += ['--tumor-sample', paired.tumor_name]
    else:
        params += ['-I:tumor', paired.tumor_bam]
    if paired.normal_bam is not None:
        if gatk_type == 'gatk4':
            params += ['-I', paired.normal_bam]
            params += ['--normal-sample', paired.normal_name]
        else:
            params += ['-I:normal', paired.normal_bam]
    if paired.normal_panel is not None:
        panel_dir = utils.safe_makedir(os.path.join(dd.get_work_dir(items[0]), 'mutect2', 'panels'))
        normal_panel = vcfutils.bgzip_and_index(paired.normal_panel, items[0]['config'], out_dir=panel_dir)
        if gatk_type == 'gatk4':
            params += ['--panel-of-normals', normal_panel]
        else:
            params += ['--normal_panel', normal_panel]
    return params

def _add_region_params(region, out_file, items, gatk_type):
    """Add parameters for selecting by region to command line.
    """
    params = []
    variant_regions = bedutils.population_variant_regions(items)
    region = subset_variant_regions(variant_regions, region, out_file, items)
    if region:
        if gatk_type == 'gatk4':
            params += ['-L', bamprep.region_to_gatk(region), '--interval-set-rule', 'INTERSECTION']
        else:
            params += ['-L', bamprep.region_to_gatk(region), '--interval_set_rule', 'INTERSECTION']
    params += gatk.standard_cl_params(items)
    return params

def _af_filter(data, in_file, out_file):
    """Soft-filter variants with AF below min_allele_fraction (appends "MinAF" to FILTER)
    """
    min_freq = float(utils.get_in(data['config'], ('algorithm', 'min_allele_fraction'), 10)) / 100.0
    logger.debug('Filtering MuTect2 calls with allele fraction threshold of %s' % min_freq)
    ungz_out_file = '%s.vcf' % utils.splitext_plus(out_file)[0]
    if not utils.file_exists(ungz_out_file) and (not utils.file_exists(ungz_out_file + '.gz')):
        with file_transaction(data, ungz_out_file) as tx_out_file:
            vcf = cyvcf2.VCF(in_file)
            vcf.add_filter_to_header({'ID': 'MinAF', 'Description': 'Allele frequency is lower than %s%% ' % (min_freq * 100) + ('(configured in bcbio as min_allele_fraction)' if utils.get_in(data['config'], ('algorithm', 'min_allele_fraction')) else '(default threshold in bcbio; override with min_allele_fraction in the algorithm section)')})
            w = cyvcf2.Writer(tx_out_file, vcf)
            try:
                tumor_index = vcf.samples.index(dd.get_sample_name(data))
            except ValueError:
                tumor_index = None
            for rec in vcf:
                if tumor_index is not None and np.all(rec.format('AF')[tumor_index] < min_freq):
                    vcfutils.cyvcf_add_filter(rec, 'MinAF')
                w.write_record(rec)
            w.close()
    return vcfutils.bgzip_and_index(ungz_out_file, data['config'])

def _get_callers(items, stage, special_cases=False):
    """Retrieve available callers for the provided stage.

    Handles special cases like CNVkit that can be in initial or standard
    depending on if fed into Lumpy analysis."""
    callers = utils.deepish_copy(_CALLERS[stage])
    if special_cases and 'cnvkit' in callers:
        has_lumpy = any(('lumpy' in get_svcallers(d) or 'lumpy' in d['config']['algorithm'].get('svcaller_orig', []) for d in items))
        if has_lumpy and any(('lumpy_usecnv' in dd.get_tools_on(d) for d in items)):
            if stage != 'initial':
                del callers['cnvkit']
        elif stage != 'standard':
            del callers['cnvkit']
    return callers

def _handle_multiple_svcallers(data, stage):
    """Retrieve configured structural variation caller, handling multiple.
    """
    svs = get_svcallers(data)
    if stage == 'ensemble' and dd.get_svprioritize(data):
        svs.append('prioritize')
    out = []
    for svcaller in svs:
        if svcaller in _get_callers([data], stage):
            base = copy.deepcopy(data)
            final_svs = []
            for sv in data.get('sv', []):
                if stage == 'ensemble' or sv['variantcaller'] == svcaller or sv['variantcaller'] not in svs or (svcaller not in _get_callers([data], stage, special_cases=True)):
                    final_svs.append(sv)
            base['sv'] = final_svs
            base['config']['algorithm']['svcaller'] = svcaller
            base['config']['algorithm']['svcaller_orig'] = svs
            out.append(base)
    return out

def _add_supplemental(data):
    """Add additional supplemental files to CWL sv output, give useful names.
    """
    if 'supplemental' not in data['sv']:
        data['sv']['supplemental'] = []
    if data['sv'].get('variantcaller'):
        cur_name = _useful_basename(data)
        for k in ['cns', 'vrn_bed']:
            if data['sv'].get(k) and os.path.exists(data['sv'][k]):
                dname, orig = os.path.split(data['sv'][k])
                orig_base, orig_ext = utils.splitext_plus(orig)
                orig_base = _clean_name(orig_base, data)
                if orig_base:
                    fname = '%s-%s%s' % (cur_name, orig_base, orig_ext)
                else:
                    fname = '%s%s' % (cur_name, orig_ext)
                sup_out_file = os.path.join(dname, fname)
                utils.symlink_plus(data['sv'][k], sup_out_file)
                data['sv']['supplemental'].append(sup_out_file)
    return data

def _clean_name(fname, data):
    """Remove standard prefixes from a filename before renaming with useful names.
    """
    for to_remove in dd.get_batches(data) + [dd.get_sample_name(data), data['sv']['variantcaller']]:
        for ext in ('-', '_'):
            if fname.startswith('%s%s' % (to_remove, ext)):
                fname = fname[len(to_remove) + len(ext):]
        if fname.startswith(to_remove):
            fname = fname[len(to_remove):]
    return fname

def _useful_basename(data):
    """Provide a useful file basename for outputs, referencing batch/sample and caller.
    """
    names = dd.get_batches(data)
    if not names:
        names = [dd.get_sample_name(data)]
    batch_name = names[0]
    return '%s-%s' % (batch_name, data['sv']['variantcaller'])

def standardize_cnv_reference(data):
    """Standardize cnv_reference background to support multiple callers.
    """
    out = tz.get_in(['config', 'algorithm', 'background', 'cnv_reference'], data, {})
    cur_callers = set(data['config']['algorithm'].get('svcaller')) & _CNV_REFERENCE
    if isinstance(out, six.string_types):
        if not len(cur_callers) == 1:
            raise ValueError('Multiple CNV callers and single background reference for %s: %s' % data['description'], list(cur_callers))
        else:
            out = {cur_callers.pop(): out}
    return out

def parallel_multiplier(items):
    """Use more resources (up to available limits) if we have multiple QC samples/svcallers.
    """
    machines = []
    for data in (xs[0] for xs in items):
        machines.append(max(1, len(get_svcallers(data)), len(dd.get_algorithm_qc(data))))
    return sum(machines)

def _bowtie2_args_from_config(config, curcl):
    """Configurable high level options for bowtie2.
    """
    qual_format = config['algorithm'].get('quality_format', '')
    if qual_format.lower() == 'illumina':
        qual_flags = ['--phred64-quals']
    else:
        qual_flags = []
    num_cores = config['algorithm'].get('num_cores', 1)
    core_flags = ['-p', str(num_cores)] if num_cores > 1 else []
    user_opts = config_utils.get_resources('bowtie2', config).get('options', [])
    for flag_opt in (o for o in user_opts if str(o).startswith('-')):
        if flag_opt in curcl:
            raise ValueError('Duplicate option %s in resources and bcbio commandline: %s %s' % flag_opt, user_opts, curcl)
    return core_flags + qual_flags + user_opts

def _get_file_paths(cur):
    """Retrieve a list of file paths, recursively traversing the
    """
    out = []
    if isinstance(cur, (list, tuple)):
        for x in cur:
            new = _get_file_paths(x)
            if new:
                out.extend(new)
    elif isinstance(cur, dict):
        if 'class' in cur:
            out.append(cur['path'])
        else:
            for k, v in cur.items():
                new = _get_file_paths(v)
                if new:
                    out.extend(new)
    return out

def _load_custom_config(run_config):
    """Load custom configuration input HOCON file for cromwell.
    """
    from pyhocon import ConfigFactory, HOCONConverter, ConfigTree
    conf = ConfigFactory.parse_file(run_config)
    out = {}
    if 'database' in conf:
        out['database'] = HOCONConverter.to_hocon(ConfigTree({'database': conf.get_config('database')}))
    return out

def _get_filesystem_types(args, sample_file):
    """Retrieve the types of inputs and staging based on sample JSON and arguments.
    """
    out = set([])
    ext = '' if args.no_container else '_container'
    with open(sample_file) as in_handle:
        for f in _get_file_paths(json.load(in_handle)):
            if f.startswith('gs:'):
                out.add('gcp%s' % ext)
            elif f.startswith('s3:'):
                out.add('s3%s' % ext)
            elif f.startswith(('https:', 'http:')):
                out.add('http%s' % ext)
            else:
                out.add('local%s' % ext)
    return out

def _get_filesystem_config(file_types):
    """Retrieve filesystem configuration, including support for specified file types.
    """
    out = '     filesystems {\n'
    for file_type in sorted(list(file_types)):
        if file_type in _FILESYSTEM_CONFIG:
            out += _FILESYSTEM_CONFIG[file_type]
    out += '      }\n'
    return out

def _get_engine_filesystem_config(file_types, args, conf_args):
    """Retriever authorization and engine filesystem configuration.
    """
    file_types = [x.replace('_container', '') for x in list(file_types)]
    out = ''
    if 'gcp' in file_types:
        out += _AUTH_CONFIG_GOOGLE
    if 's3' in file_types:
        out += _AUTH_CONFIG_AWS % conf_args['cloud_region']
    if 'gcp' in file_types or 'http' in file_types or 's3' in file_types:
        out += 'engine {\n'
        out += '  filesystems {\n'
        if 'gcp' in file_types:
            out += '    gcs {\n'
            out += '      auth = "gcp-auth"\n'
            if args.cloud_project:
                out += '      project = "%s"\n' % args.cloud_project
            out += '    }\n'
        if 'http' in file_types:
            out += '    http {}\n'
        if 's3' in file_types:
            out += '    s3 { auth = "default" }'
        out += '  }\n'
        out += '}\n'
    return out

def run_scalpel(align_bams, items, ref_file, assoc_files, region=None, out_file=None):
    """Run Scalpel indel calling, either paired tumor/normal or germline calling.
    """
    if region is None:
        message = 'A region must be provided for Scalpel'
        raise ValueError(message)
    if is_paired_analysis(align_bams, items):
        call_file = _run_scalpel_paired(align_bams, items, ref_file, assoc_files, region, out_file)
    else:
        call_file = _run_scalpel_caller(align_bams, items, ref_file, assoc_files, region, out_file)
    return call_file

def normalize(in_file, data, passonly=False, normalize_indels=True, split_biallelic=True, rerun_effects=True, remove_oldeffects=False, nonrefonly=False, work_dir=None):
    """Normalizes variants and reruns SnpEFF for resulting VCF
    """
    if remove_oldeffects:
        out_file = '%s-noeff-nomultiallelic%s' % utils.splitext_plus(in_file)
    else:
        out_file = '%s-nomultiallelic%s' % utils.splitext_plus(in_file)
    if work_dir:
        out_file = os.path.join(work_dir, os.path.basename(out_file))
    if not utils.file_exists(out_file):
        if vcfutils.vcf_has_variants(in_file):
            ready_ma_file = _normalize(in_file, data, passonly=passonly, normalize_indels=normalize_indels, split_biallelic=split_biallelic, remove_oldeffects=remove_oldeffects, nonrefonly=nonrefonly, work_dir=work_dir)
            if rerun_effects:
                ann_ma_file, _ = effects.add_to_vcf(ready_ma_file, data)
                if ann_ma_file:
                    ready_ma_file = ann_ma_file
            utils.symlink_plus(ready_ma_file, out_file)
        else:
            utils.symlink_plus(in_file, out_file)
    return vcfutils.bgzip_and_index(out_file, data['config'])

def sleuthify_sailfish(sailfish_dir):
    """if installed, use wasabi to create abundance.h5 output for use with
    sleuth"""
    if not R_package_path('wasabi'):
        return None
    else:
        rscript = Rscript_cmd()
        cmd = '{rscript} --no-environ -e \'library("wasabi"); prepare_fish_for_sleuth(c("{sailfish_dir}"))\''
        do.run(cmd.format(**locals()), 'Converting Sailfish to Sleuth format.')
    return os.path.join(sailfish_dir, 'abundance.h5')

def pick_kmersize(fq):
    """pick an appropriate kmer size based off of https://www.biostars.org/p/201474/
    tl;dr version: pick 31 unless the reads are very small, if not then guess
    that readlength / 2 is about right."""
    if bam.is_bam(fq):
        readlength = bam.estimate_read_length(fq)
    else:
        readlength = fastq.estimate_read_length(fq)
    halfread = int(round(readlength / 2))
    if halfread >= 31:
        kmersize = 31
    else:
        kmersize = halfread
    if kmersize % 2 == 0:
        kmersize += 1
    return kmersize

def _prep_sample_and_config(ldetail_group, fastq_dir, fastq_final_dir):
    """Prepare output fastq file and configuration for a single sample.

    Only passes non-empty files through for processing."""
    files = []
    print('->', ldetail_group[0]['name'], len(ldetail_group))
    for read in ['R1', 'R2']:
        fastq_inputs = sorted(list(set(reduce(operator.add, (_get_fastq_files(x, read, fastq_dir) for x in ldetail_group)))))
        if len(fastq_inputs) > 0:
            files.append(_concat_bgzip_fastq(fastq_inputs, fastq_final_dir, read, ldetail_group[0]))
    if len(files) > 0:
        if _non_empty(files[0]):
            out = ldetail_group[0]
            out['files'] = files
            return out

def _prepare_sample(data, run_folder):
    """Extract passed keywords from input LIMS information.
    """
    want = set(['description', 'files', 'genome_build', 'name', 'analysis', 'upload', 'algorithm'])
    out = {}
    for k, v in data.items():
        if k in want:
            out[k] = _relative_paths(v, run_folder)
    if 'algorithm' not in out:
        analysis, algorithm = _select_default_algorithm(out.get('analysis'))
        out['algorithm'] = algorithm
        out['analysis'] = analysis
    description = '%s-%s' % (out['name'], clean_name(out['description']))
    out['name'] = [out['name'], description]
    out['description'] = description
    return out

def _select_default_algorithm(analysis):
    """Provide default algorithm sections from templates or standard
    """
    if not analysis or analysis == 'Standard':
        return ('Standard', {'aligner': 'bwa', 'platform': 'illumina', 'quality_format': 'Standard', 'recalibrate': False, 'realign': False, 'mark_duplicates': True, 'variantcaller': False})
    elif 'variant' in analysis:
        try:
            config, _ = template.name_to_config(analysis)
        except ValueError:
            config, _ = template.name_to_config('freebayes-variant')
        return ('variant', config['details'][0]['algorithm'])
    else:
        return (analysis, {})

def _relative_paths(xs, base_path):
    """Adjust paths to be relative to the provided base path.
    """
    if isinstance(xs, six.string_types):
        if xs.startswith(base_path):
            return xs.replace(base_path + '/', '', 1)
        else:
            return xs
    elif isinstance(xs, (list, tuple)):
        return [_relative_paths(x, base_path) for x in xs]
    elif isinstance(xs, dict):
        out = {}
        for k, v in xs.items():
            out[k] = _relative_paths(v, base_path)
        return out
    else:
        return xs

def _get_fastq_files(ldetail, read, fastq_dir):
    """Retrieve fastq files corresponding to the sample and read number.
    """
    return glob.glob(os.path.join(fastq_dir, 'Project_%s' % ldetail['project_name'], 'Sample_%s' % ldetail['name'], '%s_*_%s_*.fastq.gz' % (ldetail['name'], read)))

def _group_same_samples(ldetails):
    """Move samples into groups -- same groups have identical names.
    """
    sample_groups = collections.defaultdict(list)
    for ldetail in ldetails:
        sample_groups[ldetail['name']].append(ldetail)
    return sorted(sample_groups.values(), key=lambda xs: xs[0]['name'])

def get_runinfo(galaxy_url, galaxy_apikey, run_folder, storedir):
    """Retrieve flattened run information for a processed directory from Galaxy nglims API.
    """
    galaxy_api = GalaxyApiAccess(galaxy_url, galaxy_apikey)
    fc_name, fc_date = flowcell.parse_dirname(run_folder)
    galaxy_info = galaxy_api.run_details(fc_name, fc_date)
    if 'error' in galaxy_info:
        return galaxy_info
    if not galaxy_info['run_name'].startswith(fc_date) and (not galaxy_info['run_name'].endswith(fc_name)):
        raise ValueError('Galaxy NGLIMS information %s does not match flowcell %s %s' % (galaxy_info['run_name'], fc_date, fc_name))
    ldetails = _flatten_lane_details(galaxy_info)
    out = []
    for item in ldetails:
        if item['description'] != 'control' or item['project_name'] != 'control':
            item['upload'] = {'method': 'galaxy', 'run_id': galaxy_info['run_id'], 'fc_name': fc_name, 'fc_date': fc_date, 'dir': storedir, 'galaxy_url': galaxy_url, 'galaxy_api_key': galaxy_apikey}
            for k in ['lab_association', 'private_libs', 'researcher', 'researcher_id', 'sample_id', 'galaxy_library', 'galaxy_role']:
                item['upload'][k] = item.pop(k, '')
        out.append(item)
    return out

def use_general_sv_bins(data):
    """Check if we should use a general binning approach for a sample.

    Checks if CNVkit is enabled and we haven't already run CNVkit."""
    if any([c in dd.get_svcaller(data) for c in ['cnvkit', 'titancna', 'purecn', 'gatk-cnv']]):
        if not _get_original_coverage(data):
            return True
    return False

def bin_approach(data):
    """Check for binning approach from configuration or normalized file.
    """
    for approach in ['cnvkit', 'gatk-cnv']:
        if approach in dd.get_svcaller(data):
            return approach
    norm_file = tz.get_in(['depth', 'bins', 'normalized'], data)
    if norm_file.endswith(('-crstandardized.tsv', '-crdenoised.tsv')):
        return 'gatk-cnv'
    if norm_file.endswith('.cnr'):
        return 'cnvkit'

def _cnvkit_by_type(items, background):
    """Dispatch to specific CNVkit functionality based on input type.
    """
    if len(items + background) == 1:
        return _run_cnvkit_single(items[0])
    elif vcfutils.get_paired_phenotype(items[0]):
        return _run_cnvkit_cancer(items, background)
    else:
        return _run_cnvkit_population(items, background)

def _run_cnvkit_single(data, background=None):
    """Process a single input file with BAM or uniform background.
    """
    if not background:
        background = []
    ckouts = _run_cnvkit_shared([data], background)
    if not ckouts:
        return [data]
    else:
        assert len(ckouts) == 1
        return _associate_cnvkit_out(ckouts, [data])

def _run_cnvkit_population(items, background):
    """Run CNVkit on a population of samples.

    Tries to calculate background based on case/controls, otherwise
    uses samples from the same batch as background."""
    if background and len(background) > 0:
        inputs = items
    else:
        inputs, background = shared.find_case_control(items)
    if len(inputs) == 1 or len(background) > 0:
        ckouts = _run_cnvkit_shared(inputs, background)
        return _associate_cnvkit_out(ckouts, inputs) + background
    else:
        out = []
        for cur_input in items:
            background = [d for d in items if dd.get_sample_name(d) != dd.get_sample_name(cur_input)]
            ckouts = _run_cnvkit_shared([cur_input], background)
            out.extend(_associate_cnvkit_out(ckouts, [cur_input]))
        return out

def _prep_cmd(cmd, tx_out_file):
    """Wrap CNVkit commands ensuring we use local temporary directories.
    """
    cmd = ' '.join(cmd) if isinstance(cmd, (list, tuple)) else cmd
    return 'export TMPDIR=%s && %s' % (os.path.dirname(tx_out_file), cmd)

def _run_cnvkit_shared(inputs, backgrounds):
    """Shared functionality to run CNVkit, parallelizing over multiple BAM files.

    Handles new style cases where we have pre-normalized inputs and
    old cases where we run CNVkit individually."""
    if tz.get_in(['depth', 'bins', 'normalized'], inputs[0]):
        ckouts = []
        for data in inputs:
            cnr_file = tz.get_in(['depth', 'bins', 'normalized'], data)
            cns_file = os.path.join(_sv_workdir(data), '%s.cns' % dd.get_sample_name(data))
            cns_file = _cnvkit_segment(cnr_file, dd.get_coverage_interval(data), data, inputs + backgrounds, cns_file)
            ckouts.append({'cnr': cnr_file, 'cns': cns_file, 'background': tz.get_in(['depth', 'bins', 'background'], data)})
        return ckouts
    else:
        return _run_cnvkit_shared_orig(inputs, backgrounds)

def _get_original_targets(data):
    """Back compatible: get pre-existing target BEDs.
    """
    work_dir = os.path.join(_sv_workdir(data), 'raw')
    batch = dd.get_batch(data) or dd.get_sample_name(data)
    return (glob.glob(os.path.join(work_dir, '*-%s.target.bed' % batch))[0], glob.glob(os.path.join(work_dir, '*-%s.antitarget.bed' % batch))[0])

def cnvkit_background(background_cnns, out_file, items, target_bed=None, antitarget_bed=None):
    """Calculate background reference, handling flat case with no normal sample.
    """
    if not utils.file_exists(out_file):
        with file_transaction(items[0], out_file) as tx_out_file:
            cmd = [_get_cmd(), 'reference', '-f', dd.get_ref_file(items[0]), '-o', tx_out_file]
            gender = _get_batch_gender(items)
            if gender:
                cmd += ['--sample-sex', gender]
            if len(background_cnns) == 0:
                assert target_bed and antitarget_bed, 'Missing CNNs and target BEDs for flat background'
                cmd += ['-t', target_bed, '-a', antitarget_bed]
            else:
                cmd += background_cnns
            do.run(_prep_cmd(cmd, tx_out_file), 'CNVkit background')
    return out_file

def _get_batch_gender(items):
    """Retrieve gender for a batch of items if consistent.

    Better not to specify for mixed populations, CNVkit will work
    it out
    https://github.com/bcbio/bcbio-nextgen/commit/1a0e217c8a4d3cee10fa890fb3cfd4db5034281d#r26279752"""
    genders = set([population.get_gender(x) for x in items])
    if len(genders) == 1:
        gender = genders.pop()
        if gender != 'unknown':
            return gender

