def _cnx_is_empty(in_file):
    """Check if cnr or cns files are empty (only have a header)
    """
    with open(in_file) as in_handle:
        for i, line in enumerate(in_handle):
            if i > 0:
                return False
    return True

def update_file(finfo, sample_info, config, pass_uptodate=False):
    """Update the file in local filesystem storage.
    """
    storage_dir = utils.safe_makedir(_get_storage_dir(finfo, config))
    if finfo.get('type') == 'directory':
        return _copy_finfo_directory(finfo, storage_dir)
    else:
        return _copy_finfo(finfo, storage_dir, pass_uptodate=pass_uptodate)

def get_upload_path(finfo, sample_info, config):
    """"Dry" update the file: only return the upload path
    """
    try:
        storage_dir = _get_storage_dir(finfo, config)
    except ValueError:
        return None
    if finfo.get('type') == 'directory':
        return _get_dir_upload_path(finfo, storage_dir)
    else:
        return _get_file_upload_path(finfo, storage_dir)

def _copy_finfo(finfo, storage_dir, pass_uptodate=False):
    """Copy a file into the output storage directory.
    """
    out_file = _get_file_upload_path(finfo, storage_dir)
    if not shared.up_to_date(out_file, finfo):
        logger.info('Storing in local filesystem: %s' % out_file)
        shutil.copy(finfo['path'], out_file)
        return out_file
    if pass_uptodate:
        return out_file

def _copy_finfo_directory(finfo, out_dir):
    """Copy a directory into the final output directory.
    """
    out_dir = _get_dir_upload_path(finfo, out_dir)
    if not shared.up_to_date(out_dir, finfo):
        logger.info('Storing directory in local filesystem: %s' % out_dir)
        if os.path.exists(out_dir):
            shutil.rmtree(out_dir)
        shutil.copytree(finfo['path'], out_dir)
        for tmpdir in ['tx', 'tmp']:
            if os.path.exists(os.path.join(out_dir, tmpdir)):
                shutil.rmtree(os.path.join(out_dir, tmpdir))
        os.utime(out_dir, None)
    return out_dir

def handle_synonyms(in_file, ref_file, genome_build, work_dir, data):
    """Potentially handle remapping synonymous chromosome names between builds.

    Handles tab delimited file formats like BED and VCF where the contig
    is in the first column."""
    if genome_build in GMAP and ref_file:
        mappings = GMAP[genome_build]
        contigs = set([c.name for c in ref.file_contigs(ref_file)])
        out_file = os.path.join(work_dir, '%s-fixed_contigs%s' % utils.splitext_plus(os.path.basename(in_file)))
        if not utils.file_exists(out_file):
            if out_file.endswith('.gz'):
                out_file = out_file.replace('.gz', '')
                needs_bgzip = True
            else:
                needs_bgzip = False
            checked_file = '%s.checked' % utils.splitext_plus(out_file)[0]
            if not _matches_contigs(in_file, contigs, checked_file):
                with file_transaction(data, out_file) as tx_out_file:
                    _write_newname_file(in_file, tx_out_file, mappings)
                if needs_bgzip:
                    out_file = vcfutils.bgzip_and_index(out_file, data['config'])
                return out_file
    return in_file

def _write_newname_file(in_file, out_file, mappings):
    """Re-write an input file with contigs matching the correct reference.
    """
    with utils.open_gzipsafe(in_file) as in_handle:
        with open(out_file, 'w') as out_handle:
            for line in in_handle:
                if line.startswith('#'):
                    out_handle.write(line)
                else:
                    parts = line.split('\t')
                    new_contig = mappings.get(parts[0])
                    if new_contig:
                        parts[0] = new_contig
                        out_handle.write('\t'.join(parts))

def _matches_contigs(in_file, contigs, checked_file):
    """Check if the contigs in the input file match the defined contigs in the reference genome.
    """
    tocheck_contigs = 2
    if utils.file_exists(checked_file):
        with open(checked_file) as in_handle:
            return in_handle.read().strip() == 'match'
    else:
        with utils.open_gzipsafe(in_file) as in_handle:
            to_check = set([])
            for line in in_handle:
                if not line.startswith('#'):
                    to_check.add(line.split()[0])
                if len(to_check) >= tocheck_contigs:
                    break
        with open(checked_file, 'w') as out_handle:
            if any([c not in contigs for c in to_check]):
                out_handle.write('different')
                return False
            else:
                out_handle.write('match')
                return True

def _novoalign_args_from_config(config, need_quality=True):
    """Select novoalign options based on configuration parameters.
    """
    if need_quality:
        qual_format = config['algorithm'].get('quality_format', '').lower()
        qual_flags = ['-F', 'ILMFQ' if qual_format == 'illumina' else 'STDFQ']
    else:
        qual_flags = []
    multi_mappers = config['algorithm'].get('multiple_mappers')
    if multi_mappers is True:
        multi_flag = 'Random'
    elif isinstance(multi_mappers, six.string_types):
        multi_flag = multi_mappers
    else:
        multi_flag = 'None'
    multi_flags = ['-r'] + multi_flag.split()
    resources = config_utils.get_resources('novoalign', config)
    if resources.get('options') is None:
        extra_args = ['-o', 'FullNW', '-k']
    else:
        extra_args = [str(x) for x in resources.get('options', [])]
    return qual_flags + multi_flags + extra_args

def remap_index_fn(ref_file):
    """Map sequence references to equivalent novoalign indexes.
    """
    checks = [os.path.splitext(ref_file)[0].replace('/seq/', '/novoalign/'), os.path.splitext(ref_file)[0] + '.ndx', ref_file + '.bs.ndx', ref_file + '.ndx']
    for check in checks:
        if os.path.exists(check):
            return check
    return checks[0]

def license_export(data):
    """Retrieve export statement for sentieon license server.
    """
    resources = config_utils.get_resources('sentieon', data['config'])
    server = resources.get('keyfile')
    if not server:
        server = tz.get_in(['resources', 'sentieon', 'keyfile'], data)
    if not server:
        raise ValueError('Need to set resources keyfile with URL:port of license server, local license file or environmental variables to export \nhttp://bcbio-nextgen.readthedocs.io/en/latest/contents/configuration.html#resources\nConfiguration: %s' % pprint.pformat(data))
    if isinstance(server, six.string_types):
        return 'export SENTIEON_LICENSE=%s && ' % server
    else:
        assert isinstance(server, dict), server
        exports = ''
        for key, val in server.items():
            exports += 'export %s=%s && ' % (key.upper(), val)
        return exports

def _get_interval(variant_regions, region, out_file, items):
    """Retrieve interval to run analysis in. Handles no targets, BED and regions

    region can be a single region or list of multiple regions for multicore calling."""
    target = shared.subset_variant_regions(variant_regions, region, out_file, items)
    if target:
        if isinstance(target, six.string_types) and os.path.isfile(target):
            return '--interval %s' % target
        else:
            return '--interval %s' % bamprep.region_to_gatk(target)
    else:
        return ''

def to_fastq_apipe_cl(sdf_file, start=None, end=None):
    """Return a command lines to provide streaming fastq input.

    For paired end, returns a forward and reverse command line. For
    single end returns a single command line and None for the pair."""
    cmd = ['rtg', 'sdf2fastq', '--no-gzip', '-o', '-']
    if start is not None:
        cmd += ['--start-id=%s' % start]
    if end is not None:
        cmd += ['--end-id=%s' % end]
    if is_paired(sdf_file):
        out = []
        for ext in ['left', 'right']:
            out.append('<(%s)' % _rtg_cmd(cmd + ['-i', os.path.join(sdf_file, ext)]))
        return out
    else:
        cmd += ['-i', sdf_file]
        return ['<(%s)' % _rtg_cmd(cmd), None]

def get_tabix_cmd(config):
    """Retrieve tabix command, handling new bcftools tabix and older tabix.
    """
    try:
        bcftools = config_utils.get_program('bcftools', config)
        bcftools_tabix = subprocess.check_output('{bcftools} 2>&1; echo $?'.format(**locals()), shell=True).decode().find('tabix') >= 0
    except config_utils.CmdNotFound:
        bcftools_tabix = False
    if bcftools_tabix:
        return '{0} tabix'.format(bcftools)
    else:
        tabix = config_utils.get_program('tabix', config)
        return tabix

def fai_from_bam(ref_file, bam_file, out_file, data):
    """Create a fai index with only contigs in the input BAM file.
    """
    contigs = set([x.contig for x in idxstats(bam_file, data)])
    if not utils.file_uptodate(out_file, bam_file):
        with open(ref.fasta_idx(ref_file, data['config'])) as in_handle:
            with file_transaction(data, out_file) as tx_out_file:
                with open(tx_out_file, 'w') as out_handle:
                    for line in (l for l in in_handle if l.strip()):
                        if line.split()[0] in contigs:
                            out_handle.write(line)
    return out_file

def get_maxcov_downsample_cl(data, in_pipe=None):
    """Retrieve command line for max coverage downsampling, fitting into bamsormadup output.
    """
    max_cov = _get_maxcov_downsample(data) if dd.get_aligner(data) not in ['snap'] else None
    if max_cov:
        if in_pipe == 'bamsormadup':
            prefix = 'level=0'
        elif in_pipe == 'samtools':
            prefix = '-l 0'
        else:
            prefix = ''
        core_arg = ''
        return '%s | variant - -b %s --mark-as-qc-fail --max-coverage %s' % (prefix, core_arg, max_cov)
    else:
        if in_pipe == 'bamsormadup':
            prefix = 'indexfilename={tx_out_file}.bai'
        else:
            prefix = ''
        return prefix

def _check_sample(in_bam, rgnames):
    """Ensure input sample name matches expected run group names.
    """
    with pysam.Samfile(in_bam, 'rb') as bamfile:
        rg = bamfile.header.get('RG', [{}])
    msgs = []
    warnings = []
    if len(rg) > 1:
        warnings.append('Multiple read groups found in input BAM. Expect single RG per BAM.')
    if len(rg) == 0:
        msgs.append('No read groups found in input BAM. Expect single RG per BAM.')
    if len(rg) > 0 and any((x.get('SM') != rgnames['sample'] for x in rg)):
        msgs.append('Read group sample name (SM) does not match configuration `description`: %s vs %s' % (rg[0].get('SM'), rgnames['sample']))
    if len(msgs) > 0:
        raise ValueError('Problems with pre-aligned input BAM file: %s\n' % in_bam + '\n'.join(msgs) + '\nSetting `bam_clean: fixrg`\nin the configuration can often fix this issue.')
    if warnings:
        print('*** Potential problems in input BAM compared to reference:\n%s\n' % '\n'.join(warnings))

def aligner_from_header(in_bam):
    """Identify aligner from the BAM header; handling pre-aligned inputs.
    """
    from bcbio.pipeline.alignment import TOOLS
    with pysam.Samfile(in_bam, 'rb') as bamfile:
        for pg in bamfile.header.get('PG', []):
            for ka in TOOLS.keys():
                if pg.get('PN', '').lower().find(ka) >= 0:
                    return ka

def sample_name(in_bam):
    """Get sample name from BAM file.
    """
    with pysam.AlignmentFile(in_bam, 'rb', check_sq=False) as in_pysam:
        try:
            if 'RG' in in_pysam.header:
                return in_pysam.header['RG'][0]['SM']
        except ValueError:
            return None

def estimate_read_length(bam_file, nreads=1000):
    """estimate median read length of a SAM/BAM file"""
    with open_samfile(bam_file) as bam_handle:
        reads = tz.itertoolz.take(nreads, bam_handle)
        lengths = [len(x.seq) for x in reads]
    return int(numpy.median(lengths))

def estimate_fragment_size(bam_file, nreads=5000):
    """estimate median fragment size of a SAM/BAM file"""
    with open_samfile(bam_file) as bam_handle:
        reads = tz.itertoolz.take(nreads, bam_handle)
        lengths = [x.template_length for x in reads if x.template_length > 0]
    if not lengths:
        return 0
    return int(numpy.median(lengths))

def estimate_max_mapq(in_bam, nreads=1000000.0):
    """Guess maximum MAPQ in a BAM file of reads with alignments
    """
    with pysam.Samfile(in_bam, 'rb') as work_bam:
        reads = tz.take(int(nreads), work_bam)
        return max([x.mapq for x in reads if not x.is_unmapped])

def convert_cufflinks_mapq(in_bam, out_bam=None):
    """Cufflinks expects the not-valid 255 MAPQ for uniquely mapped reads.
    This detects the maximum mapping quality in a BAM file and sets
    reads with that quality to be 255"""
    CUFFLINKSMAPQ = 255
    if not out_bam:
        out_bam = os.path.splitext(in_bam)[0] + '-cufflinks.bam'
    if utils.file_exists(out_bam):
        return out_bam
    maxmapq = estimate_max_mapq(in_bam)
    if maxmapq == CUFFLINKSMAPQ:
        return in_bam
    logger.info('Converting MAPQ scores in %s to be Cufflinks compatible.' % in_bam)
    with pysam.Samfile(in_bam, 'rb') as in_bam_fh:
        with pysam.Samfile(out_bam, 'wb', template=in_bam_fh) as out_bam_fh:
            for read in in_bam_fh:
                if read.mapq == maxmapq and (not read.is_unmapped):
                    read.mapq = CUFFLINKSMAPQ
                out_bam_fh.write(read)
    return out_bam

def get_gatk_annotations(config, include_depth=True, include_baseqranksum=True, gatk_input=True):
    """Retrieve annotations to use for GATK VariantAnnotator.

    If include_depth is false, we'll skip annotating DP. Since GATK downsamples
    this will undercount on high depth sequencing and the standard outputs
    from the original callers may be preferable.

    BaseQRankSum can cause issues with some MuTect2 and other runs, so we
    provide option to skip it."""
    broad_runner = broad.runner_from_config(config)
    anns = ['MappingQualityRankSumTest', 'MappingQualityZero', 'QualByDepth', 'ReadPosRankSumTest', 'RMSMappingQuality']
    if include_baseqranksum:
        anns += ['BaseQualityRankSumTest']
    if gatk_input or broad_runner.gatk_type() == 'gatk4':
        anns += ['FisherStrand']
    if broad_runner.gatk_type() == 'gatk4':
        anns += ['MappingQuality']
    else:
        anns += ['GCContent', 'HaplotypeScore', 'HomopolymerRun']
    if include_depth:
        anns += ['DepthPerAlleleBySample']
        if broad_runner.gatk_type() in ['restricted', 'gatk4']:
            anns += ['Coverage']
        else:
            anns += ['DepthOfCoverage']
    return anns

def finalize_vcf(in_file, variantcaller, items):
    """Perform cleanup and dbSNP annotation of the final VCF.

    - Adds contigs to header for bcftools compatibility
    - adds sample information for tumor/normal"""
    out_file = '%s-annotated%s' % utils.splitext_plus(in_file)
    if not utils.file_uptodate(out_file, in_file):
        header_cl = _add_vcf_header_sample_cl(in_file, items, out_file)
        contig_cl = _add_contig_cl(in_file, items, out_file)
        cls = [x for x in (contig_cl, header_cl) if x]
        if cls:
            post_cl = ' | '.join(cls) + ' | '
        else:
            post_cl = None
        dbsnp_file = tz.get_in(('genome_resources', 'variation', 'dbsnp'), items[0])
        if dbsnp_file:
            out_file = _add_dbsnp(in_file, dbsnp_file, items[0], out_file, post_cl)
    if utils.file_exists(out_file):
        return vcfutils.bgzip_and_index(out_file, items[0]['config'])
    else:
        return in_file

def _fix_generic_tn_names(paired):
    """Convert TUMOR/NORMAL names in output into sample IDs.
    """
    def run(line):
        parts = line.rstrip('\n\r').split('\t')
        if 'TUMOR' in parts:
            parts[parts.index('TUMOR')] = paired.tumor_name
        if 'TUMOUR' in parts:
            parts[parts.index('TUMOUR')] = paired.tumor_name
        if 'NORMAL' in parts:
            assert paired.normal_name
            parts[parts.index('NORMAL')] = paired.normal_name
        return '\t'.join(parts) + '\n'
    return run

def _add_vcf_header_sample_cl(in_file, items, base_file):
    """Add phenotype information to a VCF header.

    Encode tumor/normal relationships in VCF header.
    Could also eventually handle more complicated pedigree information if useful."""
    paired = vcfutils.get_paired(items)
    if paired:
        toadd = ['##SAMPLE=<ID=%s,Genomes=Tumor>' % paired.tumor_name]
        if paired.normal_name:
            toadd.append('##SAMPLE=<ID=%s,Genomes=Germline>' % paired.normal_name)
            toadd.append('##PEDIGREE=<Derived=%s,Original=%s>' % (paired.tumor_name, paired.normal_name))
        new_header = _update_header(in_file, base_file, toadd, _fix_generic_tn_names(paired))
        if vcfutils.vcf_has_variants(in_file):
            cmd = 'bcftools reheader -h {new_header} | bcftools view '
            return cmd.format(**locals())

def _update_header(orig_vcf, base_file, new_lines, chrom_process_fn=None):
    """Fix header with additional lines and remapping of generic sample names.
    """
    new_header = '%s-sample_header.txt' % utils.splitext_plus(base_file)[0]
    with open(new_header, 'w') as out_handle:
        chrom_line = None
        with utils.open_gzipsafe(orig_vcf) as in_handle:
            for line in in_handle:
                if line.startswith('##'):
                    out_handle.write(line)
                else:
                    chrom_line = line
                    break
        assert chrom_line is not None
        for line in new_lines:
            out_handle.write(line + '\n')
        if chrom_process_fn:
            chrom_line = chrom_process_fn(chrom_line)
        out_handle.write(chrom_line)
    return new_header

def get_context_files(data):
    """Retrieve pre-installed annotation files for annotating genome context.
    """
    ref_file = dd.get_ref_file(data)
    all_files = []
    for ext in ['.bed.gz']:
        all_files += sorted(glob.glob(os.path.normpath(os.path.join(os.path.dirname(ref_file), os.pardir, 'coverage', 'problem_regions', '*', '*%s' % ext))))
    return sorted(all_files)

def _submit_and_wait(cmd, cores, config, output_dir):
    """Submit command with batch script specified in configuration, wait until finished
    """
    batch_script = 'submit_bcl2fastq.sh'
    if not os.path.exists(batch_script + '.finished'):
        if os.path.exists(batch_script + '.failed'):
            os.remove(batch_script + '.failed')
        with open(batch_script, 'w') as out_handle:
            out_handle.write(config['process']['bcl2fastq_batch'].format(cores=cores, bcl2fastq_cmd=' '.join(cmd), batch_script=batch_script))
        submit_cmd = utils.get_in(config, ('process', 'submit_cmd'))
        subprocess.check_call(submit_cmd.format(batch_script=batch_script), shell=True)
        while 1:
            if os.path.exists(batch_script + '.finished'):
                break
            if os.path.exists(batch_script + '.failed'):
                raise ValueError('bcl2fastq batch script failed: %s' % os.path.join(output_dir, batch_script))
            time.sleep(5)

def _prep_items_from_base(base, in_files, metadata, separators, force_single=False):
    """Prepare a set of configuration items for input files.
    """
    details = []
    in_files = _expand_dirs(in_files, KNOWN_EXTS)
    in_files = _expand_wildcards(in_files)
    ext_groups = collections.defaultdict(list)
    for ext, files in itertools.groupby(in_files, lambda x: KNOWN_EXTS.get(utils.splitext_plus(x)[-1].lower())):
        ext_groups[ext].extend(list(files))
    for ext, files in ext_groups.items():
        if ext == 'bam':
            for f in files:
                details.append(_prep_bam_input(f, base))
        elif ext in ['fastq', 'fq', 'fasta']:
            files, glob_files = _find_glob_matches(files, metadata)
            for fs in glob_files:
                details.append(_prep_fastq_input(fs, base))
            for fs in fastq.combine_pairs(files, force_single, separators=separators):
                details.append(_prep_fastq_input(fs, base))
        elif ext in ['vcf']:
            for f in files:
                details.append(_prep_vcf_input(f, base))
        else:
            print('Ignoring unexpected input file types %s: %s' % (ext, list(files)))
    return details

def _find_glob_matches(in_files, metadata):
    """Group files that match by globs for merging, rather than by explicit pairs.
    """
    reg_files = copy.deepcopy(in_files)
    glob_files = []
    for glob_search in [x for x in metadata.keys() if '*' in x]:
        cur = []
        for fname in in_files:
            if fnmatch.fnmatch(fname, '*/%s' % glob_search):
                cur.append(fname)
                reg_files.remove(fname)
        assert cur, 'Did not find file matches for %s' % glob_search
        glob_files.append(cur)
    return (reg_files, glob_files)

def _write_config_file(items, global_vars, template, project_name, out_dir, remotes):
    """Write configuration file, adding required top level attributes.
    """
    config_dir = utils.safe_makedir(os.path.join(out_dir, 'config'))
    out_config_file = os.path.join(config_dir, '%s.yaml' % project_name)
    out = {'fc_name': project_name, 'upload': {'dir': '../final'}, 'details': items}
    if remotes.get('base'):
        r_base = objectstore.parse_remote(remotes.get('base'))
        out['upload']['method'] = r_base.store
        out['upload']['bucket'] = r_base.bucket
        out['upload']['folder'] = os.path.join(r_base.key, 'final') if r_base.key else 'final'
        if r_base.region:
            out['upload']['region'] = r_base.region
    if global_vars:
        out['globals'] = global_vars
    for k, v in template.items():
        if k not in ['details']:
            out[k] = v
    if os.path.exists(out_config_file):
        shutil.move(out_config_file, out_config_file + '.bak%s' % datetime.datetime.now().strftime('%Y-%m-%d-%H-%M-%S'))
    with open(out_config_file, 'w') as out_handle:
        yaml.safe_dump(out, out_handle, default_flow_style=False, allow_unicode=False)
    return out_config_file

def _set_global_vars(metadata):
    """Identify files used multiple times in metadata and replace with global variables
    """
    fnames = collections.defaultdict(list)
    for sample in metadata.keys():
        for k, v in metadata[sample].items():
            if isinstance(v, six.string_types) and os.path.isfile(v):
                v = _expand_file(v)
                metadata[sample][k] = v
                fnames[v].append(k)
    global_vars = {}
    return (metadata, global_vars)

def _clean_string(v, sinfo):
    """Test for and clean unicode present in template CSVs.
    """
    if isinstance(v, (list, tuple)):
        return [_clean_string(x, sinfo) for x in v]
    else:
        assert isinstance(v, six.string_types), v
        try:
            if hasattr(v, 'decode'):
                return str(v.decode('ascii'))
            else:
                return str(v.encode('ascii').decode('ascii'))
        except UnicodeDecodeError as msg:
            raise ValueError('Found unicode character in template CSV line %s:\n%s' % (sinfo, str(msg)))

def _parse_metadata(in_handle):
    """Reads metadata from a simple CSV structured input file.

    samplename,batch,phenotype
    ERR256785,batch1,normal"""
    metadata = {}
    reader = csv.reader(in_handle)
    while 1:
        header = next(reader)
        if not header[0].startswith('#'):
            break
    keys = [x.strip() for x in header[1:]]
    for sinfo in (x for x in reader if x and (not x[0].startswith('#'))):
        sinfo = [_strip_and_convert_lists(x) for x in sinfo]
        sample = sinfo[0]
        if isinstance(sample, list):
            sample = tuple(sample)
        if sample in metadata:
            raise ValueError('Sample %s present multiple times in metadata file.\nIf you need to specify multiple attributes as a list use a semi-colon to separate them on a single line.\nhttps://bcbio-nextgen.readthedocs.org/en/latest/contents/configuration.html#automated-sample-configuration\nDuplicate line is %s' % (sample, sinfo))
        vals = [_clean_string(v, sinfo) for v in sinfo[1:]]
        metadata[sample] = dict(zip(keys, vals))
    metadata, global_vars = _set_global_vars(metadata)
    return (metadata, global_vars)

def _pname_and_metadata(in_file):
    """Retrieve metadata and project name from the input metadata CSV file.

    Uses the input file name for the project name and for back compatibility,
    accepts the project name as an input, providing no metadata."""
    if os.path.isfile(in_file):
        with open(in_file) as in_handle:
            md, global_vars = _parse_metadata(in_handle)
        base = os.path.splitext(os.path.basename(in_file))[0]
        md_file = in_file
    elif objectstore.is_remote(in_file):
        with objectstore.open_file(in_file) as in_handle:
            md, global_vars = _parse_metadata(in_handle)
        base = os.path.splitext(os.path.basename(in_file))[0]
        md_file = None
    else:
        if in_file.endswith('.csv'):
            raise ValueError('Did not find input metadata file: %s' % in_file)
        base, md, global_vars = (_safe_name(os.path.splitext(os.path.basename(in_file))[0]), {}, {})
        md_file = None
    return (_safe_name(base), md, global_vars, md_file)

def _handle_special_yaml_cases(v):
    """Handle values that pass integer, boolean, list or dictionary values.
    """
    if '::' in v:
        out = {}
        for part in v.split('::'):
            k_part, v_part = part.split(':')
            out[k_part] = v_part.split(';')
        v = out
    elif ';' in v:
        v = [x for x in v.split(';') if x != '']
    elif isinstance(v, list):
        v = v
    else:
        try:
            v = int(v)
        except ValueError:
            if v.lower() == 'true':
                v = True
            elif v.lower() == 'false':
                v = False
    return v

def _add_ped_metadata(name, metadata):
    """Add standard PED file attributes into metadata if not present.

    http://pngu.mgh.harvard.edu/~purcell/plink/data.shtml#ped"""
    ignore = set(['-9', 'undefined', 'unknown', '.'])
    def _ped_mapping(x, valmap):
        try:
            x = int(x)
        except ValueError:
            x = -1
        for k, v in valmap.items():
            if k == x:
                return v
        return None
    def _ped_to_gender(x):
        return _ped_mapping(x, {1: 'male', 2: 'female'})
    def _ped_to_phenotype(x):
        known_phenotypes = set(['unaffected', 'affected', 'tumor', 'normal'])
        if x in known_phenotypes:
            return x
        else:
            return _ped_mapping(x, {1: 'unaffected', 2: 'affected'})
    def _ped_to_batch(x):
        if x not in ignore and x != '0':
            return x
    with open(metadata['ped']) as in_handle:
        for line in in_handle:
            parts = line.split('\t')[:6]
            if parts[1] == str(name):
                for index, key, convert_fn in [(4, 'sex', _ped_to_gender), (0, 'batch', _ped_to_batch), (5, 'phenotype', _ped_to_phenotype)]:
                    val = convert_fn(parts[index])
                    if val is not None and key not in metadata:
                        metadata[key] = val
                break
    return metadata

def _retrieve_remote(fnames):
    """Retrieve remote inputs found in the same bucket as the template or metadata files.
    """
    for fname in fnames:
        if objectstore.is_remote(fname):
            inputs = []
            regions = []
            remote_base = os.path.dirname(fname)
            for rfname in objectstore.list(remote_base):
                if rfname.endswith(tuple(KNOWN_EXTS.keys())):
                    inputs.append(rfname)
                elif rfname.endswith(('.bed', '.bed.gz')):
                    regions.append(rfname)
            return {'base': remote_base, 'inputs': inputs, 'region': regions[0] if len(regions) == 1 else None}
    return {}

def _convert_to_relpaths(data, work_dir):
    """Convert absolute paths in the input data to relative paths to the work directory.
    """
    work_dir = os.path.abspath(work_dir)
    data['files'] = [os.path.relpath(f, work_dir) for f in data['files']]
    for topk in ['metadata', 'algorithm']:
        for k, v in data[topk].items():
            if isinstance(v, six.string_types) and os.path.isfile(v) and os.path.isabs(v):
                data[topk][k] = os.path.relpath(v, work_dir)
    return data

def _check_all_metadata_found(metadata, items):
    """Print warning if samples in CSV file are missing in folder"""
    for name in metadata:
        seen = False
        for sample in items:
            check_file = sample['files'][0] if sample.get('files') else sample['vrn_file']
            if isinstance(name, (tuple, list)):
                if check_file.find(name[0]) > -1:
                    seen = True
            elif check_file.find(name) > -1:
                seen = True
            elif '*' in name and fnmatch.fnmatch(check_file, '*/%s' % name):
                seen = True
        if not seen:
            print('WARNING: sample not found %s' % str(name))

def _copy_to_configdir(items, out_dir, args):
    """Copy configuration files like PED inputs to working config directory.
    """
    out = []
    for item in items:
        ped_file = tz.get_in(['metadata', 'ped'], item)
        if ped_file and os.path.exists(ped_file):
            ped_config_file = os.path.join(out_dir, 'config', os.path.basename(ped_file))
            if not os.path.exists(ped_config_file):
                shutil.copy(ped_file, ped_config_file)
            item['metadata']['ped'] = ped_config_file
        out.append(item)
    if hasattr(args, 'systemconfig') and args.systemconfig:
        shutil.copy(args.systemconfig, os.path.join(out_dir, 'config', os.path.basename(args.systemconfig)))
    return out

def update_w_custom(config, lane_info):
    """Update the configuration for this lane if a custom analysis is specified.
    """
    name_remaps = {'variant': ['SNP calling', 'variant', 'variant2'], 'SNP calling': ['SNP calling', 'variant', 'variant2'], 'variant2': ['SNP calling', 'variant', 'variant2']}
    config = copy.deepcopy(config)
    base_name = lane_info.get('analysis')
    if 'algorithm' not in config:
        config['algorithm'] = {}
    for analysis_type in name_remaps.get(base_name, [base_name]):
        custom = config.get('custom_algorithms', {}).get(analysis_type)
        if custom:
            for key, val in custom.items():
                config['algorithm'][key] = val
    for key, val in lane_info.get('algorithm', {}).items():
        config['algorithm'][key] = val
    for prog, pkvs in lane_info.get('resources', {}).items():
        if prog not in config['resources']:
            config['resources'][prog] = {}
        for key, val in pkvs.items():
            config['resources'][prog][key] = val
    return config

def load_system_config(config_file=None, work_dir=None, allow_missing=False):
    """Load bcbio_system.yaml configuration file, handling standard defaults.

    Looks for configuration file in default location within
    final base directory from a standard installation. Handles both standard
    installs (galaxy/bcbio_system.yaml) and docker installs (config/bcbio_system.yaml)."""
    docker_config = _get_docker_config()
    if config_file is None:
        config_file = 'bcbio_system.yaml'
    if not os.path.exists(config_file):
        base_dir = get_base_installdir()
        test_config = os.path.join(base_dir, 'galaxy', config_file)
        if os.path.exists(test_config):
            config_file = test_config
        elif allow_missing:
            config_file = None
        else:
            raise ValueError('Could not find input system configuration file %s, including inside standard directory %s' % (config_file, os.path.join(base_dir, 'galaxy')))
    config = load_config(config_file) if config_file else {}
    if docker_config:
        assert work_dir is not None, 'Need working directory to merge docker config'
        config_file = os.path.join(work_dir, '%s-merged%s' % os.path.splitext(os.path.basename(config_file)))
        config = _merge_system_configs(config, docker_config, config_file)
    if 'algorithm' not in config:
        config['algorithm'] = {}
    config['bcbio_system'] = config_file
    return (config, config_file)

def _merge_system_configs(host_config, container_config, out_file=None):
    """Create a merged system configuration from external and internal specification.
    """
    out = copy.deepcopy(container_config)
    for k, v in host_config.items():
        if k in set(['galaxy_config']):
            out[k] = v
        elif k == 'resources':
            for pname, resources in v.items():
                if not isinstance(resources, dict) and pname not in out[k]:
                    out[k][pname] = resources
                else:
                    for rname, rval in resources.items():
                        if rname in set(['cores', 'jvm_opts', 'memory']) or pname in set(['gatk', 'mutect']):
                            if pname not in out[k]:
                                out[k][pname] = {}
                            out[k][pname][rname] = rval
    if 'bcbio_system' in out and ('galaxy_config' not in out or not os.path.isabs(out['galaxy_config'])):
        out['galaxy_config'] = os.path.normpath(os.path.join(os.path.dirname(out['bcbio_system']), os.pardir, 'galaxy', 'universe_wsgi.ini'))
    if out_file:
        with open(out_file, 'w') as out_handle:
            yaml.safe_dump(out, out_handle, default_flow_style=False, allow_unicode=False)
    return out

def merge_resources(args):
    """Merge docker local resources and global resource specification in a set of arguments.

    Finds the `data` object within passed arguments and updates the resources
    from a local docker configuration if present."""
    docker_config = _get_docker_config()
    if not docker_config:
        return args
    else:
        def _update_resources(config):
            config['resources'] = _merge_system_configs(config, docker_config)['resources']
            return config
        return _update_config(args, _update_resources, allow_missing=True)

def load_config(config_file):
    """Load YAML config file, replacing environmental variables.
    """
    with open(config_file) as in_handle:
        config = yaml.safe_load(in_handle)
    config = _expand_paths(config)
    if 'resources' not in config:
        config['resources'] = {}
    newr = {}
    for k, v in config['resources'].items():
        if k.lower() != k:
            newr[k.lower()] = v
    config['resources'].update(newr)
    return config

def get_resources(name, config):
    """Retrieve resources for a program, pulling from multiple config sources.
    """
    return tz.get_in(['resources', name], config, tz.get_in(['resources', 'default'], config, {}))

def get_program(name, config, ptype='cmd', default=None):
    """Retrieve program information from the configuration.

    This handles back compatible location specification in input
    YAML. The preferred location for program information is in
    `resources` but the older `program` tag is also supported."""
    config = config.get('config', config)
    try:
        pconfig = config.get('resources', {})[name]
    except KeyError:
        pconfig = {}
    old_config = config.get('program', {}).get(name, None)
    if old_config:
        for key in ['dir', 'cmd']:
            if not key in pconfig:
                pconfig[key] = old_config
    if ptype == 'cmd':
        return _get_program_cmd(name, pconfig, config, default)
    elif ptype == 'dir':
        return _get_program_dir(name, pconfig)
    else:
        raise ValueError("Don't understand program type: %s" % ptype)

def _get_program_cmd(name, pconfig, config, default):
    """Retrieve commandline of a program.
    """
    if pconfig is None:
        return name
    elif isinstance(pconfig, six.string_types):
        return pconfig
    elif 'cmd' in pconfig:
        return pconfig['cmd']
    elif default is not None:
        return default
    else:
        return name

def _get_program_dir(name, config):
    """Retrieve directory for a program (local installs/java jars).
    """
    if config is None:
        raise ValueError('Could not find directory in config for %s' % name)
    elif isinstance(config, six.string_types):
        return config
    elif 'dir' in config:
        return expand_path(config['dir'])
    else:
        raise ValueError('Could not find directory in config for %s' % name)

def get_jar(base_name, dname):
    """Retrieve a jar in the provided directory
    """
    jars = glob.glob(os.path.join(expand_path(dname), '%s*.jar' % base_name))
    if len(jars) == 1:
        return jars[0]
    elif len(jars) > 1:
        raise ValueError('Found multiple jars for %s in %s. Need single jar: %s' % (base_name, dname, jars))
    else:
        raise ValueError('Could not find java jar %s in %s' % (base_name, dname))

def get_algorithm_config(xs):
    """Flexibly extract algorithm configuration for a sample from any function arguments.
    """
    if isinstance(xs, dict):
        xs = [xs]
    for x in xs:
        if is_std_config_arg(x):
            return x['algorithm']
        elif is_nested_config_arg(x):
            return x['config']['algorithm']
        elif isinstance(x, (list, tuple)) and is_nested_config_arg(x[0]):
            return x[0]['config']['algorithm']
    raise ValueError('Did not find algorithm configuration in items: {0}'.format(pprint.pformat(xs)))

def get_dataarg(args):
    """Retrieve the world 'data' argument from a set of input parameters.
    """
    for i, arg in enumerate(args):
        if is_nested_config_arg(arg):
            return (i, arg)
        elif is_std_config_arg(arg):
            return (i, {'config': arg})
        elif isinstance(arg, (list, tuple)) and is_nested_config_arg(arg[0]):
            return (i, arg[0])
    raise ValueError('Did not find configuration or data object in arguments: %s' % args)

def add_cores_to_config(args, cores_per_job, parallel=None):
    """Add information about available cores for a job to configuration.
    Ugly hack to update core information in a configuration dictionary."""
    def _update_cores(config):
        config['algorithm']['num_cores'] = int(cores_per_job)
        if parallel:
            parallel.pop('view', None)
            config['parallel'] = parallel
        return config
    return _update_config(args, _update_cores)

def _update_config(args, update_fn, allow_missing=False):
    """Update configuration, nested in argument list, with the provided update function.
    """
    new_i = None
    for i, arg in enumerate(args):
        if is_std_config_arg(arg) or is_nested_config_arg(arg) or (isinstance(arg, (list, tuple)) and is_nested_config_arg(arg[0])):
            new_i = i
            break
    if new_i is None:
        if allow_missing:
            return args
        else:
            raise ValueError('Could not find configuration in args: %s' % str(args))
    new_arg = args[new_i]
    if is_nested_config_arg(new_arg):
        new_arg['config'] = update_fn(copy.deepcopy(new_arg['config']))
    elif is_std_config_arg(new_arg):
        new_arg = update_fn(copy.deepcopy(new_arg))
    elif isinstance(arg, (list, tuple)) and is_nested_config_arg(new_arg[0]):
        new_arg_first = new_arg[0]
        new_arg_first['config'] = update_fn(copy.deepcopy(new_arg_first['config']))
        new_arg = [new_arg_first] + new_arg[1:]
    else:
        raise ValueError('Unexpected configuration dictionary: %s' % new_arg)
    args = list(args)[:]
    args[new_i] = new_arg
    return args

def convert_to_bytes(mem_str):
    """Convert a memory specification, potentially with M or G, into bytes.
    """
    if str(mem_str)[-1].upper().endswith('G'):
        return int(round(float(mem_str[:-1]) * 1024 * 1024))
    elif str(mem_str)[-1].upper().endswith('M'):
        return int(round(float(mem_str[:-1]) * 1024))
    else:
        return int(round(float(mem_str)))

def adjust_cores_to_mb_target(target_mb, mem_str, cores):
    """Scale core usage to match a Mb/core target.

    Useful for memory dependent programs where we don't have control
    over memory usage so need to scale cores."""
    cur_mb = convert_to_bytes(mem_str) / 1024.0
    scale = target_mb / cur_mb
    if scale >= 1:
        return cores
    else:
        return max(1, int(math.ceil(scale * cores)))

def use_vqsr(algs, call_file=None):
    """Processing uses GATK's Variant Quality Score Recalibration.
    """
    from bcbio.variation import vcfutils
    vqsr_callers = set(['gatk', 'gatk-haplotype'])
    vqsr_sample_thresh = 50
    vqsr_supported = collections.defaultdict(int)
    coverage_intervals = set([])
    for alg in algs:
        callers = alg.get('variantcaller')
        if isinstance(callers, six.string_types):
            callers = [callers]
        if not callers:
            continue
        if 'vqsr' in (alg.get('tools_off') or []):
            continue
        for c in callers:
            if c in vqsr_callers:
                if 'vqsr' in (alg.get('tools_on') or []):
                    vqsr_supported[c] += 1
                    coverage_intervals.add('genome')
                elif call_file and vcfutils.is_gvcf_file(call_file):
                    pass
                else:
                    coverage_intervals.add(alg.get('coverage_interval', 'exome').lower())
                    vqsr_supported[c] += 1
    if len(vqsr_supported) > 0:
        num_samples = max(vqsr_supported.values())
        if 'genome' in coverage_intervals or num_samples >= vqsr_sample_thresh:
            return True
    return False

def use_bcbio_variation_recall(algs):
    """Processing uses bcbio-variation-recall. Avoids core requirement if not used.
    """
    for alg in algs:
        jointcaller = alg.get('jointcaller', [])
        if not isinstance(jointcaller, (tuple, list)):
            jointcaller = [jointcaller]
        for caller in jointcaller:
            if caller not in set(['gatk-haplotype-joint', None, False]):
                return True
    return False

def program_installed(program, data):
    """returns True if the path to a program can be found"""
    try:
        path = get_program(program, data)
    except CmdNotFound:
        return False
    return True

def _needs_java(data):
    """Check if a caller needs external java for MuTect.

    No longer check for older GATK (<3.6) versions because of time cost; this
    won't be relevant to most runs so we skip the sanity check."""
    vc = dd.get_variantcaller(data)
    if isinstance(vc, dict):
        out = {}
        for k, v in vc.items():
            if not isinstance(v, (list, tuple)):
                v = [v]
            out[k] = v
        vc = out
    elif not isinstance(vc, (list, tuple)):
        vc = [vc]
    if 'mutect' in vc or ('somatic' in vc and 'mutect' in vc['somatic']):
        return True
    if 'gatk' in vc or 'gatk-haplotype' in vc or ('germline' in vc and 'gatk-haplotype' in vc['germline']):
        pass
    return False

def java(items):
    """Check for presence of external Java 1.7 for tools that require it.
    """
    if any([_needs_java(d) for d in items]):
        min_version = '1.7'
        max_version = '1.8'
        with setpath.orig_paths():
            java = utils.which('java')
            if not java:
                return 'java not found on PATH. Java %s required for MuTect and GATK < 3.6.' % min_version
            p = subprocess.Popen([java, '-Xms250m', '-Xmx250m', '-version'], stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
            output, _ = p.communicate()
            p.stdout.close()
        version = ''
        for line in output.split('\n'):
            if line.startswith(('java version', 'openjdk version')):
                version = line.strip().split()[-1]
                if version.startswith('"'):
                    version = version[1:]
                if version.endswith('"'):
                    version = version[:-1]
        if not version or LooseVersion(version) >= LooseVersion(max_version) or LooseVersion(version) < LooseVersion(min_version):
            return "java version %s required for running MuTect and GATK < 3.6.\nIt needs to be first on your PATH so running 'java -version' give the correct version.\nFound version %s at %s" % (min_version, version, java)

def _pip_safe_ssl(cmds, anaconda_dir):
    """Run pip, retrying with conda SSL certificate if global certificate fails.
    """
    try:
        for cmd in cmds:
            subprocess.check_call(cmd)
    except subprocess.CalledProcessError:
        _set_pip_ssl(anaconda_dir)
        for cmd in cmds:
            subprocess.check_call(cmd)

def _set_pip_ssl(anaconda_dir):
    """Set PIP SSL certificate to installed conda certificate to avoid SSL errors
    """
    if anaconda_dir:
        cert_file = os.path.join(anaconda_dir, 'ssl', 'cert.pem')
        if os.path.exists(cert_file):
            os.environ['PIP_CERT'] = cert_file

def _set_matplotlib_default_backend():
    """matplotlib will try to print to a display if it is available, but don't want
    to run it in interactive mode. we tried setting the backend to 'Agg'' before
    importing, but it was still resulting in issues. we replace the existing
    backend with 'agg' in the default matplotlibrc. This is a hack until we can
    find a better solution"""
    if _matplotlib_installed():
        import matplotlib
        matplotlib.use('Agg', force=True)
        config = matplotlib.matplotlib_fname()
        if os.access(config, os.W_OK):
            with file_transaction(config) as tx_out_file:
                with open(config) as in_file, open(tx_out_file, 'w') as out_file:
                    for line in in_file:
                        if line.split(':')[0].strip() == 'backend':
                            out_file.write('backend: agg\n')
                        else:
                            out_file.write(line)

def _symlink_bcbio(args, script='bcbio_nextgen.py', env_name=None, prefix=None):
    """Ensure a bcbio-nextgen script symlink in final tool directory.
    """
    if env_name:
        bcbio_anaconda = os.path.join(os.path.dirname(os.path.dirname(os.path.realpath(sys.executable))), 'envs', env_name, 'bin', script)
    else:
        bcbio_anaconda = os.path.join(os.path.dirname(os.path.realpath(sys.executable)), script)
    bindir = os.path.join(args.tooldir, 'bin')
    if not os.path.exists(bindir):
        os.makedirs(bindir)
    if prefix:
        script = '%s_%s' % (prefix, script)
    bcbio_final = os.path.join(bindir, script)
    if not os.path.exists(bcbio_final):
        if os.path.lexists(bcbio_final):
            subprocess.check_call(['rm', '-f', bcbio_final])
        subprocess.check_call(['ln', '-s', bcbio_anaconda, bcbio_final])

def _install_container_bcbio_system(datadir):
    """Install limited bcbio_system.yaml file for setting core and memory usage.

    Adds any non-specific programs to the exposed bcbio_system.yaml file, only
    when upgrade happening inside a docker container."""
    base_file = os.path.join(datadir, 'config', 'bcbio_system.yaml')
    if not os.path.exists(base_file):
        return
    expose_file = os.path.join(datadir, 'galaxy', 'bcbio_system.yaml')
    expose = set(['memory', 'cores', 'jvm_opts'])
    with open(base_file) as in_handle:
        config = yaml.safe_load(in_handle)
    if os.path.exists(expose_file):
        with open(expose_file) as in_handle:
            expose_config = yaml.safe_load(in_handle)
    else:
        expose_config = {'resources': {}}
    for pname, vals in config['resources'].items():
        expose_vals = {}
        for k, v in vals.items():
            if k in expose:
                expose_vals[k] = v
        if len(expose_vals) > 0 and pname not in expose_config['resources']:
            expose_config['resources'][pname] = expose_vals
    if expose_file and os.path.exists(os.path.dirname(expose_file)):
        with open(expose_file, 'w') as out_handle:
            yaml.safe_dump(expose_config, out_handle, default_flow_style=False, allow_unicode=False)
    return expose_file

def _check_for_conda_problems():
    """Identify post-install conda problems and fix.

    - libgcc upgrades can remove libquadmath, which moved to libgcc-ng"""
    conda_bin = _get_conda_bin()
    channels = _get_conda_channels(conda_bin)
    lib_dir = os.path.join(os.path.dirname(conda_bin), os.pardir, 'lib')
    for l in ['libgomp.so.1', 'libquadmath.so']:
        if not os.path.exists(os.path.join(lib_dir, l)):
            subprocess.check_call([conda_bin, 'install', '-f', '--yes'] + channels + ['libgcc-ng'])

def _get_conda_channels(conda_bin):
    """Retrieve default conda channels, checking if they are pre-specified in config.

    This allows users to override defaults with specific mirrors in their .condarc"""
    channels = ['bioconda', 'conda-forge']
    out = []
    config = yaml.safe_load(subprocess.check_output([conda_bin, 'config', '--show']))
    for c in channels:
        present = False
        for orig_c in config.get('channels') or []:
            if orig_c.endswith((c, '%s/' % c)):
                present = True
                break
        if not present:
            out += ['-c', c]
    return out

def get_genome_dir(gid, galaxy_dir, data):
    """Return standard location of genome directories.
    """
    if galaxy_dir:
        refs = genome.get_refs(gid, None, galaxy_dir, data)
        seq_file = tz.get_in(['fasta', 'base'], refs)
        if seq_file and os.path.exists(seq_file):
            return os.path.dirname(os.path.dirname(seq_file))
    else:
        gdirs = glob.glob(os.path.join(_get_data_dir(), 'genomes', '*', gid))
        if len(gdirs) == 1 and os.path.exists(gdirs[0]):
            return gdirs[0]

def _prepare_cwl_tarballs(data_dir):
    """Create CWL ready tarballs for complex directories.

    Avoids need for CWL runners to pass and serialize complex directories
    of files, which is inconsistent between runners."""
    for dbref_dir in filter(os.path.isdir, glob.glob(os.path.join(data_dir, 'genomes', '*', '*'))):
        base_dir, dbref = os.path.split(dbref_dir)
        for indexdir in TARBALL_DIRECTORIES:
            cur_target = os.path.join(dbref_dir, indexdir)
            if os.path.isdir(cur_target):
                subdirs = [x for x in os.listdir(cur_target) if os.path.isdir(os.path.join(cur_target, x))]
                if len(subdirs) == 1:
                    cur_target = os.path.join(cur_target, subdirs[0])
                create.directory_tarball(cur_target)

def _upgrade_genome_resources(galaxy_dir, base_url):
    """Retrieve latest version of genome resource YAML configuration files.
    """
    import requests
    for dbkey, ref_file in genome.get_builds(galaxy_dir):
        remote_url = base_url % dbkey
        requests.packages.urllib3.disable_warnings()
        r = requests.get(remote_url, verify=False)
        if r.status_code == requests.codes.ok:
            local_file = os.path.join(os.path.dirname(ref_file), os.path.basename(remote_url))
            if os.path.exists(local_file):
                with open(local_file) as in_handle:
                    local_config = yaml.safe_load(in_handle)
                remote_config = yaml.safe_load(r.text)
                needs_update = remote_config['version'] > local_config.get('version', 0)
                if needs_update:
                    shutil.move(local_file, local_file + '.old%s' % local_config.get('version', 0))
            else:
                needs_update = True
            if needs_update:
                print('Updating %s genome resources configuration' % dbkey)
                with open(local_file, 'w') as out_handle:
                    out_handle.write(r.text)

def _setup_genome_annotations(g, args, ann_groups):
    """Configure genome annotations to install based on datatarget.
    """
    available_anns = g.get('annotations', []) + g.pop('annotations_available', [])
    anns = []
    for orig_target in args.datatarget:
        if orig_target in ann_groups:
            targets = ann_groups[orig_target]
        else:
            targets = [orig_target]
        for target in targets:
            if target in available_anns:
                anns.append(target)
    g['annotations'] = anns
    if 'variation' not in args.datatarget and 'validation' in g:
        del g['validation']
    return g

def upgrade_thirdparty_tools(args, remotes):
    """Install and update third party tools used in the pipeline.

    Creates a manifest directory with installed programs on the system."""
    cbl = get_cloudbiolinux(remotes)
    if args.toolconf and os.path.exists(args.toolconf):
        package_yaml = args.toolconf
    else:
        package_yaml = os.path.join(cbl['dir'], 'contrib', 'flavor', 'ngs_pipeline_minimal', 'packages-conda.yaml')
    sys.path.insert(0, cbl['dir'])
    cbl_conda = __import__('cloudbio.package.conda', fromlist=['conda'])
    cbl_conda.install_in(_get_conda_bin(), args.tooldir, package_yaml)
    manifest_dir = os.path.join(_get_data_dir(), 'manifest')
    print('Creating manifest of installed packages in %s' % manifest_dir)
    cbl_manifest = __import__('cloudbio.manifest', fromlist=['manifest'])
    if os.path.exists(manifest_dir):
        for fname in os.listdir(manifest_dir):
            if not fname.startswith('toolplus'):
                os.remove(os.path.join(manifest_dir, fname))
    cbl_manifest.create(manifest_dir, args.tooldir)

def _install_toolplus(args):
    """Install additional tools we cannot distribute, updating local manifest.
    """
    manifest_dir = os.path.join(_get_data_dir(), 'manifest')
    toolplus_manifest = os.path.join(manifest_dir, 'toolplus-packages.yaml')
    system_config = os.path.join(_get_data_dir(), 'galaxy', 'bcbio_system.yaml')
    if not os.path.exists(system_config):
        docker_system_config = os.path.join(_get_data_dir(), 'config', 'bcbio_system.yaml')
        if os.path.exists(docker_system_config):
            system_config = docker_system_config
    toolplus_dir = os.path.join(_get_data_dir(), 'toolplus')
    for tool in args.toolplus:
        if tool.name in set(['gatk', 'mutect']):
            print('Installing %s' % tool.name)
            _install_gatk_jar(tool.name, tool.fname, toolplus_manifest, system_config, toolplus_dir)
        else:
            raise ValueError('Unexpected toolplus argument: %s %s' % (tool.name, tool.fname))

def _update_manifest(manifest_file, name, version):
    """Update the toolplus manifest file with updated name and version
    """
    if os.path.exists(manifest_file):
        with open(manifest_file) as in_handle:
            manifest = yaml.safe_load(in_handle)
    else:
        manifest = {}
    manifest[name] = {'name': name, 'version': version}
    with open(manifest_file, 'w') as out_handle:
        yaml.safe_dump(manifest, out_handle, default_flow_style=False, allow_unicode=False)

def _update_system_file(system_file, name, new_kvs):
    """Update the bcbio_system.yaml file with new resource information.
    """
    if os.path.exists(system_file):
        bak_file = system_file + '.bak%s' % datetime.datetime.now().strftime('%Y-%m-%d-%H-%M-%S')
        shutil.copyfile(system_file, bak_file)
        with open(system_file) as in_handle:
            config = yaml.safe_load(in_handle)
    else:
        utils.safe_makedir(os.path.dirname(system_file))
        config = {}
    new_rs = {}
    added = False
    for rname, r_kvs in config.get('resources', {}).items():
        if rname == name:
            for k, v in new_kvs.items():
                r_kvs[k] = v
            added = True
        new_rs[rname] = r_kvs
    if not added:
        new_rs[name] = new_kvs
    config['resources'] = new_rs
    with open(system_file, 'w') as out_handle:
        yaml.safe_dump(config, out_handle, default_flow_style=False, allow_unicode=False)

def _get_install_config():
    """Return the YAML configuration file used to store upgrade information.
    """
    try:
        data_dir = _get_data_dir()
    except ValueError:
        return None
    config_dir = utils.safe_makedir(os.path.join(data_dir, 'config'))
    return os.path.join(config_dir, 'install-params.yaml')

def save_install_defaults(args):
    """Save installation information to make future upgrades easier.
    """
    install_config = _get_install_config()
    if install_config is None:
        return
    if utils.file_exists(install_config):
        with open(install_config) as in_handle:
            cur_config = yaml.safe_load(in_handle)
    else:
        cur_config = {}
    if args.tooldir:
        cur_config['tooldir'] = args.tooldir
    cur_config['isolate'] = args.isolate
    for attr in ['genomes', 'aligners', 'datatarget']:
        if not cur_config.get(attr):
            cur_config[attr] = []
        for x in getattr(args, attr):
            if x not in cur_config[attr]:
                cur_config[attr].append(x)
    attr = 'toolplus'
    if not cur_config.get(attr):
        cur_config[attr] = []
    for x in getattr(args, attr):
        if not x.fname:
            if x.name not in cur_config[attr]:
                cur_config[attr].append(x.name)
    with open(install_config, 'w') as out_handle:
        yaml.safe_dump(cur_config, out_handle, default_flow_style=False, allow_unicode=False)

def add_install_defaults(args):
    """Add any saved installation defaults to the upgrade.
    """
    if len(args.genomes) > 0 or len(args.aligners) > 0 or len(args.datatarget) > 0:
        args.install_data = True
    install_config = _get_install_config()
    if install_config is None or not utils.file_exists(install_config):
        default_args = {}
    else:
        with open(install_config) as in_handle:
            default_args = yaml.safe_load(in_handle)
    if args.upgrade in ['development'] and (args.tooldir or 'tooldir' in default_args):
        args.tools = True
    if args.tools and args.tooldir is None:
        if 'tooldir' in default_args:
            args.tooldir = str(default_args['tooldir'])
        else:
            raise ValueError("Default tool directory not yet saved in config defaults. Specify the '--tooldir=/path/to/tools' to upgrade tools. After a successful upgrade, the '--tools' parameter will work for future upgrades.")
    for attr in ['genomes', 'aligners']:
        if attr == 'genomes' and len(args.genomes) > 0:
            continue
        for x in default_args.get(attr, []):
            x = str(x)
            new_val = getattr(args, attr)
            if x not in getattr(args, attr):
                new_val.append(x)
            setattr(args, attr, new_val)
    args = _datatarget_defaults(args, default_args)
    if 'isolate' in default_args and args.isolate is not True:
        args.isolate = default_args['isolate']
    return args

def _datatarget_defaults(args, default_args):
    """Set data installation targets, handling defaults.

    Sets variation, rnaseq, smallrna as default targets if we're not
    isolated to a single method.

    Provides back compatibility for toolplus specifications."""
    default_data = default_args.get('datatarget', [])
    for x in default_args.get('toolplus', []):
        val = None
        if x == 'data':
            val = 'gemini'
        elif x in ['cadd', 'dbnsfp', 'dbscsnv', 'kraken', 'gnomad']:
            val = x
        if val and val not in default_data:
            default_data.append(val)
    new_val = getattr(args, 'datatarget')
    for x in default_data:
        if x not in new_val:
            new_val.append(x)
    has_std_target = False
    std_targets = ['variation', 'rnaseq', 'smallrna']
    for target in std_targets:
        if target in new_val:
            has_std_target = True
            break
    if not has_std_target:
        new_val = new_val + std_targets
    setattr(args, 'datatarget', new_val)
    return args

def _check_toolplus(x):
    """Parse options for adding non-standard/commercial tools like GATK and MuTecT.
    """
    if '=' in x and len(x.split('=')) == 2:
        name, fname = x.split('=')
        fname = os.path.normpath(os.path.realpath(fname))
        if not os.path.exists(fname):
            raise argparse.ArgumentTypeError('Unexpected --toolplus argument for %s. File does not exist: %s' % (name, fname))
        return Tool(name, fname)
    else:
        raise argparse.ArgumentTypeError('Unexpected --toolplus argument. Expect toolname=filename.')

def _merge_wf_inputs(new, out, wf_outputs, to_ignore, parallel, nested_inputs):
    """Merge inputs for a sub-workflow, adding any not present inputs in out.

    Skips inputs that are internally generated or generated and ignored, keeping
    only as inputs those that we do not generate internally."""
    internal_generated_ids = []
    for vignore in to_ignore:
        vignore_id = _get_string_vid(vignore)
        if vignore_id not in [v['id'] for v in wf_outputs]:
            internal_generated_ids.append(vignore_id)
    ignore_ids = set(internal_generated_ids + [v['id'] for v in wf_outputs])
    cur_ids = set([v['id'] for v in out])
    remapped_new = []
    for v in new:
        remapped_v = copy.deepcopy(v)
        outv = copy.deepcopy(v)
        outv['id'] = get_base_id(v['id'])
        outv['source'] = v['id']
        if outv['id'] not in cur_ids and outv['id'] not in ignore_ids:
            if nested_inputs and v['id'] in nested_inputs:
                outv = _flatten_nested_input(outv)
            out.append(outv)
        if remapped_v['id'] in set([v['source'] for v in out]):
            remapped_v['source'] = get_base_id(remapped_v['id'])
        remapped_new.append(remapped_v)
    return (out, remapped_new)

def _merge_wf_outputs(new, cur, parallel):
    """Merge outputs for a sub-workflow, replacing variables changed in later steps.

    ignore_ids are those used internally in a sub-workflow but not exposed to subsequent steps"""
    new_ids = set([])
    out = []
    for v in new:
        outv = {}
        outv['source'] = v['id']
        outv['id'] = '%s' % get_base_id(v['id'])
        outv['type'] = v['type']
        if 'secondaryFiles' in v:
            outv['secondaryFiles'] = v['secondaryFiles']
        if tz.get_in(['outputBinding', 'secondaryFiles'], v):
            outv['secondaryFiles'] = tz.get_in(['outputBinding', 'secondaryFiles'], v)
        new_ids.add(outv['id'])
        out.append(outv)
    for outv in cur:
        if outv['id'] not in new_ids:
            out.append(outv)
    return out

def _extract_from_subworkflow(vs, step):
    """Remove internal variable names when moving from sub-workflow to main.
    """
    substep_ids = set([x.name for x in step.workflow])
    out = []
    for var in vs:
        internal = False
        parts = var['id'].split('/')
        if len(parts) > 1:
            if parts[0] in substep_ids:
                internal = True
        if not internal:
            var.pop('source', None)
            out.append(var)
    return out

def is_cwl_record(d):
    """Check if an input is a CWL record, from any level of nesting.
    """
    if isinstance(d, dict):
        if d.get('type') == 'record':
            return d
        else:
            recs = list(filter(lambda x: x is not None, [is_cwl_record(v) for v in d.values()]))
            return recs[0] if recs else None
    else:
        return None

def _flatten_nested_input(v):
    """Flatten a parallel scatter input -- we only get one of them to tools.
    """
    v = copy.deepcopy(v)
    if isinstance(v['type'], dict) and v['type']['type'] == 'array':
        v['type'] = v['type']['items']
    else:
        assert isinstance(v['type'], (list, tuple)), v
        new_type = None
        want_null = False
        for x in v['type']:
            if isinstance(x, dict) and x['type'] == 'array':
                new_type = x['items']
            elif isinstance(x, six.string_types) and x == 'null':
                want_null = True
            else:
                new_type = x
        if want_null:
            if not isinstance(new_type, (list, tuple)):
                new_type = [new_type] if new_type is not None else []
            for toadd in ['null', 'string']:
                if toadd not in new_type:
                    new_type.append(toadd)
        assert new_type, v
        v['type'] = new_type
    return v

def _nest_variable(v, check_records=False):
    """Nest a variable when moving from scattered back to consolidated.

    check_records -- avoid re-nesting a record input if it comes from a previous
    step and is already nested, don't need to re-array."""
    if check_records and is_cwl_record(v) and (len(v['id'].split('/')) > 1) and (v.get('type', {}).get('type') == 'array'):
        return v
    else:
        v = copy.deepcopy(v)
        v['type'] = {'type': 'array', 'items': v['type']}
        return v

def _get_variable(vid, variables):
    """Retrieve an input variable from our existing pool of options.
    """
    if isinstance(vid, six.string_types):
        vid = get_base_id(vid)
    else:
        vid = _get_string_vid(vid)
    for v in variables:
        if vid == get_base_id(v['id']):
            return copy.deepcopy(v)
    raise ValueError('Did not find variable %s in \n%s' % (vid, pprint.pformat(variables)))

def _create_record(name, field_defs, step_name, inputs, unlist, file_vs, std_vs, parallel):
    """Create an output record by rearranging inputs.

    Batching processes create records that reformat the inputs for
    parallelization."""
    if field_defs:
        fields = []
        inherit = []
        inherit_all = False
        inherit_exclude = []
        for fdef in field_defs:
            if not fdef.get('type'):
                if fdef['id'] == 'inherit':
                    inherit_all = True
                    inherit_exclude = fdef.get('exclude', [])
                else:
                    inherit.append(fdef['id'])
            else:
                cur = {'name': _get_string_vid(fdef['id']), 'type': fdef['type']}
                fields.append(_add_secondary_to_rec_field(fdef, cur))
        if inherit_all:
            fields.extend(_infer_record_outputs(inputs, unlist, file_vs, std_vs, parallel, exclude=inherit_exclude))
        elif inherit:
            fields.extend(_infer_record_outputs(inputs, unlist, file_vs, std_vs, parallel, inherit))
    else:
        fields = _infer_record_outputs(inputs, unlist, file_vs, std_vs, parallel)
    out = {'id': '%s/%s' % (step_name, name), 'type': {'name': name, 'type': 'record', 'fields': fields}}
    if parallel in ['batch-single', 'multi-batch']:
        out = _nest_variable(out)
    return out

def _infer_record_outputs(inputs, unlist, file_vs, std_vs, parallel, to_include=None, exclude=None):
    """Infer the outputs of a record from the original inputs
    """
    fields = []
    unlist = set([_get_string_vid(x) for x in unlist])
    input_vids = set([_get_string_vid(v) for v in _handle_special_inputs(inputs, file_vs)])
    to_include = set([_get_string_vid(x) for x in to_include]) if to_include else None
    to_exclude = tuple(set([_get_string_vid(x) for x in exclude])) if exclude else None
    added = set([])
    for raw_v in std_vs + [v for v in file_vs if get_base_id(v['id']) in input_vids]:
        cur_record = is_cwl_record(raw_v)
        if cur_record:
            nested_vs = [{'id': field['name'], 'type': field['type']} for field in cur_record['fields']]
        else:
            nested_vs = [raw_v]
        for orig_v in nested_vs:
            if get_base_id(orig_v['id']) not in added and (not to_include or get_base_id(orig_v['id']) in to_include):
                if to_exclude is None or not get_base_id(orig_v['id']).startswith(to_exclude):
                    cur_v = {}
                    cur_v['name'] = get_base_id(orig_v['id'])
                    cur_v['type'] = orig_v['type']
                    if cur_v['name'] in unlist:
                        cur_v = _flatten_nested_input(cur_v)
                    fields.append(_add_secondary_to_rec_field(orig_v, cur_v))
                    added.add(get_base_id(orig_v['id']))
    return fields

def _create_variable(orig_v, step, variables):
    """Create a new output variable, potentially over-writing existing or creating new.
    """
    try:
        v = _get_variable(orig_v['id'], variables)
    except ValueError:
        v = copy.deepcopy(orig_v)
        if not isinstance(v['id'], six.string_types):
            v['id'] = _get_string_vid(v['id'])
    for key, val in orig_v.items():
        if key not in ['id', 'type']:
            v[key] = val
    if orig_v.get('type') != 'null':
        v['type'] = orig_v['type']
    v['id'] = '%s/%s' % (step.name, get_base_id(v['id']))
    return v

def _merge_variables(new, cur):
    """Add any new variables to the world representation in cur.

    Replaces any variables adjusted by previous steps."""
    new_added = set([])
    out = []
    for cur_var in cur:
        updated = False
        for new_var in new:
            if get_base_id(new_var['id']) == get_base_id(cur_var['id']):
                out.append(new_var)
                new_added.add(new_var['id'])
                updated = True
                break
        if not updated:
            out.append(cur_var)
    for new_var in new:
        if new_var['id'] not in new_added:
            out.append(new_var)
    return out

def _split_variables(variables):
    """Split variables into always passed (std) and specified (file).

    We always pass some variables to each step but need to
    explicitly define file and algorithm variables so they can
    be linked in as needed."""
    file_vs = []
    std_vs = []
    for v in variables:
        cur_type = v['type']
        while isinstance(cur_type, dict):
            if 'items' in cur_type:
                cur_type = cur_type['items']
            else:
                cur_type = cur_type['type']
        if cur_type in ['File', 'null', 'record'] or (isinstance(cur_type, (list, tuple)) and ('File' in cur_type or {'items': 'File', 'type': 'array'} in cur_type)):
            file_vs.append(v)
        elif v['id'] in ALWAYS_AVAILABLE:
            std_vs.append(v)
        else:
            file_vs.append(v)
    return (file_vs, std_vs)

def resolve(items, run_parallel):
    """Combine aligned and split samples into final set of disambiguated reads.
    """
    out = []
    to_process = collections.defaultdict(list)
    for data in [x[0] for x in items]:
        if 'disambiguate' in data:
            split_part = tuple([int(x) for x in data['align_split'].split('-')]) if data.get('combine') else None
            to_process[dd.get_sample_name(data), split_part].append(data)
        else:
            out.append([data])
    if len(to_process) > 0:
        dis1 = run_parallel('run_disambiguate', [(xs, xs[0]['config']) for xs in to_process.values()])
        disambigs_by_name = collections.defaultdict(list)
        print(len(dis1))
        for xs in dis1:
            assert len(xs) == 1
            data = xs[0]
            disambigs_by_name[dd.get_sample_name(data)].append(data)
        dis2 = run_parallel('disambiguate_merge_extras', [(xs, xs[0]['config']) for xs in disambigs_by_name.values()])
    else:
        dis2 = []
    return out + dis2

def merge_extras(items, config):
    """Merge extra disambiguated reads into a final BAM file.
    """
    final = {}
    for extra_name in items[0]['disambiguate'].keys():
        in_files = []
        for data in items:
            in_files.append(data['disambiguate'][extra_name])
        out_file = '%s-allmerged%s' % os.path.splitext(in_files[0])
        if in_files[0].endswith('.bam'):
            merged_file = merge.merge_bam_files(in_files, os.path.dirname(out_file), items[0], out_file=out_file)
        else:
            assert extra_name == 'summary', extra_name
            merged_file = _merge_summary(in_files, out_file, items[0])
        final[extra_name] = merged_file
    out = []
    for data in items:
        data['disambiguate'] = final
        out.append([data])
    return out

def _merge_summary(in_files, out_file, data):
    """Create one big summary file for disambiguation from multiple splits.
    """
    if not utils.file_exists(out_file):
        with file_transaction(data, out_file) as tx_out_file:
            with open(tx_out_file, 'w') as out_handle:
                for i, in_file in enumerate(in_files):
                    with open(in_file) as in_handle:
                        for j, line in enumerate(in_handle):
                            if j == 0:
                                if i == 0:
                                    out_handle.write(line)
                            else:
                                out_handle.write(line)
    return out_file

def regions_coverage(bed_file, target_name, data):
    """Generate coverage over regions of interest using mosdepth.
    """
    ready_bed = tz.get_in(['depth', target_name, 'regions'], data)
    if ready_bed:
        return ready_bed
    else:
        return run_mosdepth(data, target_name, bed_file).regions

def get_coords(data):
    """Retrieve coordinates of genes of interest for prioritization.

    Can read from CIViC input data or a supplied BED file of chrom, start, end
    and gene information."""
    for category, vtypes in [('LOH', {'LOSS', 'HETEROZYGOSITY'}), ('amplification', {'AMPLIFICATION'})]:
        out = tz.get_in([category, dd.get_genome_build(data)], _COORDS, {})
        priority_file = dd.get_svprioritize(data)
        if priority_file:
            if os.path.basename(priority_file).find('civic') >= 0:
                for chrom, start, end, gene in _civic_regions(priority_file, vtypes, dd.get_disease(data)):
                    out[gene] = (chrom, start, end)
            elif os.path.basename(priority_file).find('.bed') >= 0:
                for line in utils.open_gzipsafe(priority_file):
                    parts = line.strip().split('\t')
                    if len(parts) >= 4:
                        chrom, start, end, gene = parts[:4]
                        out[gene] = (chrom, int(start), int(end))
        yield (category, out)

def _civic_regions(civic_file, variant_types=None, diseases=None, drugs=None):
    """Retrieve gene regions and names filtered by variant_types and diseases.
    """
    if isinstance(diseases, six.string_types):
        diseases = [diseases]
    with utils.open_gzipsafe(civic_file) as in_handle:
        reader = csv.reader(in_handle, delimiter='\t')
        for chrom, start, end, info_str in reader:
            info = edn_loads(info_str)
            if not variant_types or _matches(info['support']['variants'], variant_types):
                if not diseases or _matches(info['support']['diseases'], diseases):
                    if not drugs or _matches(info['support']['drugs'], drugs):
                        yield (chrom, int(start), int(end), list(info['name'])[0])

def summary_status(call, data):
    """Retrieve status in regions of interest, along with heterogeneity metrics.

    Provides output with overall purity and ploidy, along with region
    specific calls."""
    out_file = None
    if call.get('vrn_file') and os.path.exists(call.get('vrn_file')):
        out_file = os.path.join(os.path.dirname(call['vrn_file']), '%s-%s-lohsummary.yaml' % (dd.get_sample_name(data), call['variantcaller']))
        if not utils.file_uptodate(out_file, call['vrn_file']):
            out = {}
            if call['variantcaller'] == 'titancna':
                out.update(_titancna_summary(call, data))
                pass
            elif call['variantcaller'] == 'purecn':
                out.update(_purecn_summary(call, data))
            if out:
                out['description'] = dd.get_sample_name(data)
                out['variantcaller'] = call['variantcaller']
                with file_transaction(data, out_file) as tx_out_file:
                    with open(tx_out_file, 'w') as out_handle:
                        yaml.safe_dump(out, out_handle, default_flow_style=False, allow_unicode=False)
    return out_file if out_file and os.path.exists(out_file) else None

def _check_copy_number_changes(svtype, cn, minor_cn, data):
    """Check if copy number changes match the expected svtype.
    """
    if svtype == 'LOH' and minor_cn == 0:
        return svtype
    elif svtype == 'amplification' and cn > dd.get_ploidy(data):
        return svtype
    else:
        return 'std'

def _titancna_summary(call, data):
    """Summarize purity, ploidy and LOH for TitanCNA.
    """
    out = {}
    for svtype, coords in get_coords(data):
        cur_calls = {k: collections.defaultdict(int) for k in coords.keys()}
        with open(call['subclones']) as in_handle:
            header = in_handle.readline().strip().split()
            for line in in_handle:
                val = dict(zip(header, line.strip().split()))
                start = int(val['Start_Position.bp.'])
                end = int(val['End_Position.bp.'])
                for region, cur_coords in coords.items():
                    if val['Chromosome'] == cur_coords[0] and are_overlapping((start, end), cur_coords[1:]):
                        cur_calls[region][_check_copy_number_changes(svtype, _to_cn(val['Copy_Number']), _to_cn(val['MinorCN']), data)] += 1
        out[svtype] = {r: _merge_cn_calls(c, svtype) for r, c in cur_calls.items()}
    with open(call['hetsummary']) as in_handle:
        vals = dict(zip(in_handle.readline().strip().split('\t'), in_handle.readline().strip().split('\t')))
    out['purity'] = vals['purity']
    out['ploidy'] = vals['ploidy']
    return out

def _purecn_summary(call, data):
    """Summarize purity, ploidy and LOH for PureCN.
    """
    out = {}
    for svtype, coords in get_coords(data):
        cur_calls = {k: collections.defaultdict(int) for k in coords.keys()}
        with open(call['loh']) as in_handle:
            in_handle.readline()
            for line in in_handle:
                _, chrom, start, end, _, cn, minor_cn = line.split(',')[:7]
                start = int(start)
                end = int(end)
                for region, cur_coords in coords.items():
                    if chrom == cur_coords[0] and are_overlapping((start, end), cur_coords[1:]):
                        cur_calls[region][_check_copy_number_changes(svtype, _to_cn(cn), _to_cn(minor_cn), data)] += 1
        out[svtype] = {r: _merge_cn_calls(c, svtype) for r, c in cur_calls.items()}
    with open(call['hetsummary']) as in_handle:
        vals = dict(zip(in_handle.readline().strip().replace('"', '').split(','), in_handle.readline().strip().split(',')))
    out['purity'] = vals['Purity']
    out['ploidy'] = vals['Ploidy']
    return out

def fix_line_problems(parts):
    """Fix problem alleles and reference/variant bases in VCF line.
    """
    varinfo = parts[:9]
    genotypes = []
    for x in parts[9:]:
        if len(x) == 1:
            x = './.'
        genotypes.append(x)
    if varinfo[3] == '0':
        varinfo[3] = 'N'
    if varinfo[4] == '0':
        varinfo[4] = 'N'
    return (varinfo, genotypes)

def _prep_sample_cnvs(cnv_file, data):
    """Convert a multiple sample CNV file into a single BED file for a sample.

    Handles matching and fixing names where R converts numerical IDs (1234) into
    strings by adding an X (X1234), and converts other characters into '.'s.
    http://stat.ethz.ch/R-manual/R-devel/library/base/html/make.names.html"""
    import pybedtools
    sample_name = tz.get_in(['rgnames', 'sample'], data)
    def make_names(name):
        return re.sub('[^\\w.]', '.', name)
    def matches_sample_name(feat):
        return feat.name == sample_name or feat.name == 'X%s' % sample_name or feat.name == make_names(sample_name)
    def update_sample_name(feat):
        feat.name = sample_name
        return feat
    sample_file = os.path.join(os.path.dirname(cnv_file), '%s-cnv.bed' % sample_name)
    if not utils.file_exists(sample_file):
        with file_transaction(data, sample_file) as tx_out_file:
            with shared.bedtools_tmpdir(data):
                pybedtools.BedTool(cnv_file).filter(matches_sample_name).each(update_sample_name).saveas(tx_out_file)
    return sample_file

def _population_load_script(work_bams, names, chrom, pairmode, items):
