def _check_umi_type(bam_file):
    """Determine the type of UMI from BAM tags: standard or paired.
    """
    with pysam.Samfile(bam_file, 'rb') as in_bam:
        for read in in_bam:
            cur_umi = None
            for tag in ['RX', 'XC']:
                try:
                    cur_umi = read.get_tag(tag)
                    break
                except KeyError:
                    pass
            if cur_umi:
                if '-' in cur_umi and len(cur_umi.split('-')) == 2:
                    return ('paired', tag)
                else:
                    return ('adjacency', tag)

def _should_run(het_file):
    """Check for enough input data to proceed with analysis.
    """
    has_hets = False
    with open(het_file) as in_handle:
        for i, line in enumerate(in_handle):
            if i > 1:
                has_hets = True
                break
    return has_hets

def nf_io_to_process(ios, def_ios, scatter_ios=None):
    """Convert CWL input/output into a nextflow process definition.

    Needs to handle scattered/parallel variables."""
    scatter_names = {k: v for k, v in scatter_ios} if scatter_ios else {}
    var_types = {}
    for def_io in def_ios:
        var_types[def_io['name']] = nf_type(def_io['variable_type'])
    out = []
    for io in ios:
        cur_id = io['id']
        if scatter_names:
            input_id = scatter_names[io['value']]
        else:
            input_id = io.get('value')
        vtype = var_types[cur_id]
        if input_id and cur_id != input_id:
            out.append('%s %s as %s' % (vtype, input_id, cur_id))
        else:
            out.append('%s %s' % (vtype, cur_id))
    return out

def nf_input_to_cl(inp):
    """Convert an input description into command line argument.
    """
    sep = ' ' if inp.get('separate') else ''
    val = "'%s'" % inp.get('default') if inp.get('default') else '$%s' % inp['name']
    return '%s%s%s' % (inp['prefix'], sep, val)

def _wf_to_dict(wf):
    """Parse a workflow into cwl2wdl style dictionary.
    """
    inputs, outputs = _get_wf_inout(wf)
    out = {'name': _id_to_name(wf.tool['id']).replace('-', '_'), 'inputs': inputs, 'outputs': outputs, 'steps': [], 'subworkflows': [], 'requirements': []}
    for step in wf.steps:
        inputs, outputs = _get_step_inout(step)
        inputs, scatter = _organize_step_scatter(step, inputs)
        if isinstance(step.embedded_tool, cwltool.workflow.Workflow):
            wf_def = _wf_to_dict(step.embedded_tool)
            out['subworkflows'].append({'id': wf_def['name'], 'definition': wf_def, 'inputs': inputs, 'outputs': outputs, 'scatter': scatter})
        else:
            task_def = _tool_to_dict(step.embedded_tool)
            out['steps'].append({'task_id': task_def['name'], 'task_definition': task_def, 'inputs': inputs, 'outputs': outputs, 'scatter': scatter})
    return out

def _get_step_inout(step):
    """Retrieve set of inputs and outputs connecting steps.
    """
    inputs = []
    outputs = []
    assert step.inputs_record_schema['type'] == 'record'
    for inp in step.inputs_record_schema['fields']:
        source = inp['source'].split('#')[-1].replace('/', '.')
        if 'valueFrom' in inp:
            attr_access = "['%s']" % inp['name']
            if inp['valueFrom'].find(attr_access) > 0:
                source += '.%s' % inp['name']
        inputs.append({'id': inp['name'], 'value': source})
    assert step.outputs_record_schema['type'] == 'record'
    for outp in step.outputs_record_schema['fields']:
        outputs.append({'id': outp['name']})
    return (inputs, outputs)

def _to_variable_type(x):
    """Convert CWL variables to WDL variables, handling nested arrays.
    """
    var_mapping = {'string': 'String', 'File': 'File', 'null': 'String', 'long': 'Float', 'int': 'Int'}
    if isinstance(x, dict):
        if x['type'] == 'record':
            return 'Object'
        else:
            assert x['type'] == 'array', x
            return 'Array[%s]' % _to_variable_type(x['items'])
    elif isinstance(x, (list, tuple)):
        vars = [v for v in x if v != 'null']
        assert len(vars) == 1, vars
        return var_mapping[vars[0]]
    else:
        return var_mapping[x]

def _input_to_dict(i):
    """Convert CWL input into dictionary required for a cwl2wdl Input object.
    """
    var_type = _to_variable_type(i['type'])
    if var_type.startswith('Array') and 'inputBinding' in i.get('type', {}):
        ib = i['type']['inputBinding']
    elif 'inputBinding' in i:
        ib = i['inputBinding']
    else:
        ib = {'prefix': None, 'itemSeparator': None, 'position': None}
    return {'name': _id_to_localname(i['id']) if 'id' in i else i['name'], 'variable_type': var_type, 'prefix': ib['prefix'], 'separator': ib['itemSeparator'], 'position': ib['position'], 'is_required': True, 'default': i.get('default', None), 'separate': ib.get('separate', True)}

def _tool_to_dict(tool):
    """Parse a tool definition into a cwl2wdl style dictionary.
    """
    out = {'name': _id_to_name(tool.tool['id']), 'baseCommand': ' '.join(tool.tool['baseCommand']), 'arguments': [], 'inputs': [_input_to_dict(i) for i in tool.tool['inputs']], 'outputs': [_output_to_dict(o) for o in tool.tool['outputs']], 'requirements': _requirements_to_dict(tool.requirements + tool.hints), 'stdin': None, 'stdout': None}
    return out

def _get_validate(data):
    """Retrieve items to validate, from single samples or from combined joint calls.
    """
    if data.get('vrn_file') and tz.get_in(['config', 'algorithm', 'validate'], data):
        return utils.deepish_copy(data)
    elif 'group_orig' in data:
        for sub in multi.get_orig_items(data):
            if 'validate' in sub['config']['algorithm']:
                sub_val = utils.deepish_copy(sub)
                sub_val['vrn_file'] = data['vrn_file']
                return sub_val
    return None

def normalize_input_path(x, data):
    """Normalize path for input files, handling relative paths.
    Looks for non-absolute paths in local and fastq directories"""
    if x is None:
        return None
    elif os.path.isabs(x):
        return os.path.normpath(x)
    else:
        for d in [data['dirs'].get('fastq'), data['dirs'].get('work')]:
            if d:
                cur_x = os.path.normpath(os.path.join(d, x))
                if os.path.exists(cur_x):
                    return cur_x
        raise IOError('Could not find validation file %s' % x)

def _get_caller_supplement(caller, data):
    """Some callers like MuTect incorporate a second caller for indels.
    """
    if caller == 'mutect':
        icaller = tz.get_in(['config', 'algorithm', 'indelcaller'], data)
        if icaller:
            caller = '%s/%s' % (caller, icaller)
