def _read_call_freqs(in_file, sample_name):
    """Identify frequencies for calls in the input file.
    """
    from bcbio.heterogeneity import bubbletree
    out = {}
    with VariantFile(in_file) as call_in:
        for rec in call_in:
            if rec.filter.keys() == ['PASS']:
                for name, sample in rec.samples.items():
                    if name == sample_name:
                        alt, depth, freq = bubbletree.sample_alt_and_depth(rec, sample)
                        if freq is not None:
                            out[_get_key(rec)] = freq
    return out

def _read_truth_freqs(in_file):
    """Read frequency of calls from truth VCF.

    Currently handles DREAM data, needs generalization for other datasets."""
    out = {}
    with VariantFile(in_file) as bcf_in:
        for rec in bcf_in:
            freq = float(rec.info.get('VAF', 1.0))
            out[_get_key(rec)] = freq
    return out

def normalize_missing(xs):
    """Normalize missing values to avoid string 'None' inputs.
    """
    if isinstance(xs, dict):
        for k, v in xs.items():
            xs[k] = normalize_missing(v)
    elif isinstance(xs, (list, tuple)):
        xs = [normalize_missing(x) for x in xs]
    elif isinstance(xs, six.string_types):
        if xs.lower() in ['none', 'null']:
            xs = None
        elif xs.lower() == 'true':
            xs = True
        elif xs.lower() == 'false':
            xs = False
    return xs

def unpack_tarballs(xs, data, use_subdir=True):
    """Unpack workflow tarballs into ready to use directories.
    """
    if isinstance(xs, dict):
        for k, v in xs.items():
            xs[k] = unpack_tarballs(v, data, use_subdir)
    elif isinstance(xs, (list, tuple)):
        xs = [unpack_tarballs(x, data, use_subdir) for x in xs]
    elif isinstance(xs, six.string_types):
        if os.path.isfile(xs.encode('utf-8', 'ignore')) and xs.endswith('-wf.tar.gz'):
            if use_subdir:
                tarball_dir = utils.safe_makedir(os.path.join(dd.get_work_dir(data), 'wf-inputs'))
            else:
                tarball_dir = dd.get_work_dir(data)
            out_dir = os.path.join(tarball_dir, os.path.basename(xs).replace('-wf.tar.gz', '').replace('--', os.path.sep))
            if not os.path.exists(out_dir):
                with utils.chdir(tarball_dir):
                    with tarfile.open(xs, 'r:gz') as tar:
                        tar.extractall()
            assert os.path.exists(out_dir), out_dir
            xs = out_dir
            for fname in os.listdir(out_dir):
                if fname.endswith(DIR_TARGETS):
                    xs = os.path.join(out_dir, fname)
                    break
                elif fname.endswith(BASENAME_TARGETS):
                    base = os.path.join(out_dir, utils.splitext_plus(os.path.basename(fname))[0])
                    xs = glob.glob('%s*' % base)
                    break
    return xs

def _get_all_cwlkeys(items, default_keys=None):
    """Retrieve cwlkeys from inputs, handling defaults which can be null.

    When inputs are null in some and present in others, this creates unequal
    keys in each sample, confusing decision making about which are primary and extras."""
    if default_keys:
        default_keys = set(default_keys)
    else:
        default_keys = set(['metadata__batch', 'config__algorithm__validate', 'config__algorithm__validate_regions', 'config__algorithm__validate_regions_merged', 'config__algorithm__variant_regions', 'validate__summary', 'validate__tp', 'validate__fp', 'validate__fn', 'config__algorithm__coverage', 'config__algorithm__coverage_merged', 'genome_resources__variation__cosmic', 'genome_resources__variation__dbsnp', 'genome_resources__variation__clinvar'])
    all_keys = set([])
    for data in items:
        all_keys.update(set(data['cwl_keys']))
    all_keys.update(default_keys)
    return all_keys

def split_data_cwl_items(items, default_keys=None):
    """Split a set of CWL output dictionaries into data samples and CWL items.

    Handles cases where we're arrayed on multiple things, like a set of regional
    VCF calls and data objects."""
    key_lens = set([])
    for data in items:
        key_lens.add(len(_get_all_cwlkeys([data], default_keys)))
    extra_key_len = min(list(key_lens)) if len(key_lens) > 1 else None
    data_out = []
    extra_out = []
    for data in items:
        if extra_key_len and len(_get_all_cwlkeys([data], default_keys)) == extra_key_len:
            extra_out.append(data)
        else:
            data_out.append(data)
    if len(extra_out) == 0:
        return (data_out, {})
    else:
        cwl_keys = extra_out[0]['cwl_keys']
        for extra in extra_out[1:]:
            cur_cwl_keys = extra['cwl_keys']
            assert cur_cwl_keys == cwl_keys, pprint.pformat(extra_out)
        cwl_extras = collections.defaultdict(list)
        for data in items:
            for key in cwl_keys:
                cwl_extras[key].append(data[key])
        data_final = []
        for data in data_out:
            for key in cwl_keys:
                data.pop(key)
            data_final.append(data)
        return (data_final, dict(cwl_extras))

def samples_to_records(samples, default_keys=None):
    """Convert samples into output CWL records.
    """
    from bcbio.pipeline import run_info
    RECORD_CONVERT_TO_LIST = set(['config__algorithm__tools_on', 'config__algorithm__tools_off', 'reference__genome_context'])
    all_keys = _get_all_cwlkeys(samples, default_keys)
    out = []
    for data in samples:
        for raw_key in sorted(list(all_keys)):
            key = raw_key.split('__')
            if tz.get_in(key, data) is None:
                data = tz.update_in(data, key, lambda x: None)
            if raw_key not in data['cwl_keys']:
                data['cwl_keys'].append(raw_key)
            if raw_key in RECORD_CONVERT_TO_LIST:
                val = tz.get_in(key, data)
                if not val:
                    val = []
                elif not isinstance(val, (list, tuple)):
                    val = [val]
                data = tz.update_in(data, key, lambda x: val)
            if isinstance(tz.get_in(key, data), bool):
                data = tz.update_in(data, key, lambda x: str(tz.get_in(key, data)))
        data['metadata'] = run_info.add_metadata_defaults(data.get('metadata', {}))
        out.append(data)
    return out

def assign_complex_to_samples(items):
    """Assign complex inputs like variants and align outputs to samples.

    Handles list inputs to record conversion where we have inputs from multiple
    locations and need to ensure they are properly assigned to samples in many
    environments.

    The unpleasant approach here is to use standard file naming to match
    with samples so this can work in environments where we don't download/stream
    the input files (for space/time savings)."""
    extract_fns = {('variants', 'samples'): _get_vcf_samples, ('align_bam',): _get_bam_samples}
    complex = {k: {} for k in extract_fns.keys()}
    for data in items:
        for k in complex:
            v = tz.get_in(k, data)
            if v is not None:
                for s in extract_fns[k](v, items):
                    if s:
                        complex[k][s] = v
    out = []
    for data in items:
        for k in complex:
            newv = tz.get_in([k, dd.get_sample_name(data)], complex)
            if newv:
                data = tz.update_in(data, k, lambda x: newv)
        out.append(data)
    return out

def _normalize_vc_input(data):
    """Normalize different types of variant calling inputs.

    Handles standard and ensemble inputs."""
    if data.get('ensemble'):
        for k in ['batch_samples', 'validate', 'vrn_file']:
            data[k] = data['ensemble'][k]
        data['config']['algorithm']['variantcaller'] = 'ensemble'
        data['metadata'] = {'batch': data['ensemble']['batch_id']}
    return data

def _get_orig_items(data):
    """Retrieve original items in a batch, handling CWL and standard cases.
    """
    if isinstance(data, dict):
        if dd.get_align_bam(data) and tz.get_in(['metadata', 'batch'], data) and ('group_orig' in data):
            return vmulti.get_orig_items(data)
        else:
            return [data]
    else:
        return data

def _get_batch_representative(items, key):
    """Retrieve a representative data item from a batch.

    Handles standard bcbio cases (a single data item) and CWL cases with
    batches that have a consistent variant file."""
    if isinstance(items, dict):
        return (items, items)
    else:
        vals = set([])
        out = []
        for data in items:
            if key in data:
                vals.add(data[key])
                out.append(data)
        if len(vals) != 1:
            raise ValueError('Incorrect values for %s: %s' % (key, list(vals)))
        return (out[0], items)

def _get_storage_manager(resource):
    """Return a storage manager which can process this resource."""
    for manager in (AmazonS3, ArvadosKeep, SevenBridges, DNAnexus, AzureBlob, GoogleCloud, RegularServer):
        if manager.check_resource(resource):
            return manager()
    raise ValueError('Unexpected object store  %(resource)s' % {'resource': resource})

def default_region(fname):
    """Return the default region for the received resource.

    Note:
        This feature is available only for AmazonS3 storage manager."""
    manager = _get_storage_manager(fname)
    if hasattr(manager, 'get_region'):
        return manager.get_region()
    raise NotImplementedError('Unexpected object store %s' % fname)

def download(fname, input_dir, dl_dir=None):
    """Download the resource from the storage."""
    try:
        manager = _get_storage_manager(fname)
    except ValueError:
        return fname
    return manager.download(fname, input_dir, dl_dir)

def cl_input(fname, unpack=True, anonpipe=True):
    """Return command line input for a file, handling streaming
    remote cases."""
    try:
        manager = _get_storage_manager(fname)
    except ValueError:
        return fname
    return manager.cl_input(fname, unpack, anonpipe)

def get_fastq_files(directory, lane, fc_name):
    """Retrieve fastq files for the given lane, ready to process.
    """
    files = glob.glob(os.path.join(directory, '%s_*%s*txt*' % (lane, fc_name)))
    files.sort()
    if len(files) > 2 or len(files) == 0:
        raise ValueError('Did not find correct files for %s %s %s %s' % (directory, lane, fc_name, files))
    ready_files = []
    for fname in files:
        if fname.endswith('.gz'):
            cl = ['gunzip', fname]
            subprocess.check_call(cl)
            ready_files.append(os.path.splitext(fname)[0])
        else:
            ready_files.append(fname)
    return (ready_files[0], ready_files[1] if len(ready_files) > 1 else None)

def get_genome_ref(genome_build, aligner, galaxy_base):
    """Retrieve the reference genome file location from galaxy configuration.
    """
    ref_files = dict(bowtie='bowtie_indices.loc', bwa='bwa_index.loc', samtools='sam_fa_indices.loc', maq='bowtie_indices.loc')
    remap_fns = dict(maq=_remap_to_maq)
    out_info = []
    for ref_get in [aligner, 'samtools']:
        ref_file = os.path.join(galaxy_base, 'tool-data', ref_files[ref_get])
        with open(ref_file) as in_handle:
            for line in in_handle:
                if not line.startswith('#'):
                    parts = line.strip().split()
                    if parts[0] == 'index':
                        parts = parts[1:]
                    if parts[0] == genome_build:
                        out_info.append(parts[-1])
                        break
        try:
            out_info[-1] = remap_fns[ref_get](out_info[-1])
        except KeyError:
            pass
        except IndexError:
            raise IndexError('Genome %s not found in %s' % (genome_build, ref_file))
    if len(out_info) != 2:
        raise ValueError('Did not find genome reference for %s %s' % (genome_build, aligner))
    else:
        return tuple(out_info)

def _update_config_w_custom(config, lane_info):
    """Update the configuration for this lane if a custom analysis is specified.
    """
    config = copy.deepcopy(config)
    custom = config['custom_algorithms'].get(lane_info.get('analysis', None), None)
    if custom:
        for key, val in custom.iteritems():
            config['algorithm'][key] = val
    return config

def run(items, background=None):
    """Detect copy number variations from tumor/normal samples using Battenberg.
    """
    paired = vcfutils.get_paired_bams([x['align_bam'] for x in items], items)
    if not paired or not paired.normal_bam:
        logger.warn('Battenberg only works on paired tumor/normal inputs, skipping %s' % dd.get_sample_name(items[0]))
        batout = None
    elif not tz.get_in(['genome_resources', 'aliases', 'human'], paired.tumor_data):
        logger.warn('Battenberg only works on human data, skipping %s' % dd.get_sample_name(items[0]))
        batout = None
    else:
        batout = _do_run(paired)
        batout['variantcaller'] = 'battenberg'
    out = []
    for data in items:
        if batout and dd.get_sample_name(data) == paired.tumor_name:
            if 'sv' not in data:
                data['sv'] = []
            data['sv'].append(batout)
        out.append(data)
    return out

def _make_ignore_file(work_dir, ref_file, ignore_file, impute_file):
    """Create input files with chromosomes to ignore and gender loci.
    """
    gl_file = os.path.join(work_dir, 'gender_loci.txt')
    chroms = set([])
    with open(impute_file) as in_handle:
        for line in in_handle:
            chrom = line.split()[0]
            chroms.add(chrom)
            if not chrom.startswith('chr'):
                chroms.add('chr%s' % chrom)
    with open(ignore_file, 'w') as out_handle:
        for contig in ref.file_contigs(ref_file):
            if contig.name not in chroms:
                out_handle.write('%s\n' % contig.name)
    with open(gl_file, 'w') as out_handle:
        for contig in ref.file_contigs(ref_file):
            if contig.name in ['Y', 'chrY']:
                positions = [2934912, 4546684, 4549638, 4550107]
                for pos in positions:
                    out_handle.write('%s\t%s\n' % (contig.name, pos))
    return (ignore_file, gl_file)

def _umis_cmd(data):
    """Return umis command line argument, with correct python and locale.
    """
    return '%s %s %s' % (utils.locale_export(), utils.get_program_python('umis'), config_utils.get_program('umis', data['config'], default='umis'))

def is_transformed(fastq):
    """check the first 100 reads to see if a FASTQ file has already been transformed
    by umis"""
    with open_fastq(fastq) as in_handle:
        for line in islice(in_handle, 400):
            if 'UMI_' in line:
                return True
    return False

def _mirtop(input_fn, sps, db, out_dir, config):
    """Convert to GFF3 standard format"""
    hairpin = os.path.join(db, 'hairpin.fa')
    gtf = os.path.join(db, 'mirbase.gff3')
    if not file_exists(hairpin) or not file_exists(gtf):
        logger.warning('%s or %s are not installed. Skipping.' % (hairpin, gtf))
        return None
    out_gtf_fn = '%s.gtf' % utils.splitext_plus(os.path.basename(input_fn))[0]
    out_gff_fn = '%s.gff' % utils.splitext_plus(os.path.basename(input_fn))[0]
    export = _get_env()
    cmd = '{export} mirtop gff  --sps {sps} --hairpin {hairpin} --gtf {gtf} --format seqbuster -o {out_tx} {input_fn}'
    if not file_exists(os.path.join(out_dir, out_gtf_fn)) and (not file_exists(os.path.join(out_dir, out_gff_fn))):
        with tx_tmpdir() as out_tx:
            do.run(cmd.format(**locals()), 'Do miRNA annotation for %s' % input_fn)
            with utils.chdir(out_tx):
                out_fn = out_gtf_fn if utils.file_exists(out_gtf_fn) else out_gff_fn
                if utils.file_exists(out_fn):
                    shutil.move(os.path.join(out_tx, out_fn), os.path.join(out_dir, out_fn))
    out_fn = out_gtf_fn if utils.file_exists(os.path.join(out_dir, out_gtf_fn)) else os.path.join(out_dir, out_gff_fn)
    if utils.file_exists(os.path.join(out_dir, out_fn)):
        return os.path.join(out_dir, out_fn)

def sequence_length(fasta):
    """return a dict of the lengths of sequences in a fasta file"""
    sequences = SeqIO.parse(fasta, 'fasta')
    records = {record.id: len(record) for record in sequences}
    return records

def strip_transcript_versions(fasta, out_file):
    """strip transcript versions from a FASTA file. these appear like this:
    >ENST00000434970.2 cdna chromosome:GRCh38:14:22439007:22439015:1 etc"""
    if file_exists(out_file):
        return out_file
    with file_transaction(out_file) as tx_out_file:
        with open(tx_out_file, 'w') as out_handle:
            with open(fasta) as in_handle:
                for line in in_handle:
                    if line.startswith('>'):
                        out_handle.write(line.split(' ')[0].split('.')[0] + '\n')
                    else:
                        out_handle.write(line)
    return out_file

def _genotype_in_background(rec, base_name, back_samples):
    """Check if the genotype in the record of interest is present in the background records.
    """
    def passes(rec):
        return not rec.FILTER or len(rec.FILTER) == 0
    return passes(rec) and any((rec.genotype(base_name).gt_alleles == rec.genotype(back_name).gt_alleles for back_name in back_samples))

def _bedpes_from_cnv_caller(data, work_dir):
    """Retrieve BEDPEs deletion and duplications from CNV callers.

    Currently integrates with CNVkit."""
    supported = set(['cnvkit'])
    cns_file = None
    for sv in data.get('sv', []):
        if sv['variantcaller'] in supported and 'cns' in sv and ('lumpy_usecnv' in dd.get_tools_on(data)):
            cns_file = sv['cns']
            break
    if not cns_file:
        return (None, None)
    else:
        out_base = os.path.join(work_dir, utils.splitext_plus(os.path.basename(cns_file))[0])
        out_dels = out_base + '-dels.bedpe'
        out_dups = out_base + '-dups.bedpe'
        if not os.path.exists(out_dels) or not os.path.exists(out_dups):
            with file_transaction(data, out_dels, out_dups) as (tx_out_dels, tx_out_dups):
                try:
                    cnvanator_path = config_utils.get_program('cnvanator_to_bedpes.py', data)
                except config_utils.CmdNotFound:
                    return (None, None)
                cmd = [cnvanator_path, '-c', cns_file, '--cnvkit', '--del_o=%s' % tx_out_dels, '--dup_o=%s' % tx_out_dups, '-b', '250']
                do.run(cmd, 'Prepare CNVkit as input for lumpy', data)
        return (out_dels, out_dups)

def prepend_bcbiopath():
    """Prepend paths in the BCBIOPATH environment variable (if any) to PATH.

    Uses either a pre-sent global environmental variable (BCBIOPATH) or the
    local anaconda directory."""
    if os.environ.get('BCBIOPATH'):
        os.environ['PATH'] = _prepend(os.environ.get('PATH', ''), os.environ.get('BCBIOPATH', None))
    else:
        os.environ['PATH'] = _prepend(os.environ.get('PATH', ''), utils.get_bcbio_bin())

def _calculate_sv_bins_gatk(data, cnv_group, size_calc_fn):
    """Calculate structural variant bins using GATK4 CNV callers region or even intervals approach.
    """
    if dd.get_background_cnv_reference(data, 'gatk-cnv'):
        target_bed = gatkcnv.pon_to_bed(dd.get_background_cnv_reference(data, 'gatk-cnv'), cnv_group.work_dir, data)
    else:
        target_bed = gatkcnv.prepare_intervals(data, cnv_group.region_file, cnv_group.work_dir)
    gc_annotated_tsv = gatkcnv.annotate_intervals(target_bed, data)
    return (target_bed, None, gc_annotated_tsv)

def _calculate_sv_bins_cnvkit(data, cnv_group, size_calc_fn):
    """Calculate structural variant bins using target/anti-target approach from CNVkit.
    """
    from bcbio.structural import cnvkit
    if dd.get_background_cnv_reference(data, 'cnvkit'):
        target_bed, anti_bed = cnvkit.targets_from_background(dd.get_background_cnv_reference(data, 'cnvkit'), cnv_group.work_dir, data)
    else:
        target_bed, anti_bed = cnvkit.targets_w_bins(cnv_group.region_file, cnv_group.access_file, size_calc_fn, cnv_group.work_dir, data)
    return (target_bed, anti_bed, None)

def calculate_sv_coverage(data):
    """Calculate coverage within bins for downstream CNV calling.

    Creates corrected cnr files with log2 ratios and depths."""
    calcfns = {'cnvkit': _calculate_sv_coverage_cnvkit, 'gatk-cnv': _calculate_sv_coverage_gatk}
    from bcbio.structural import cnvkit
    data = utils.to_single_data(data)
    if not cnvkit.use_general_sv_bins(data):
        out_target_file, out_anti_file = (None, None)
    else:
        work_dir = utils.safe_makedir(os.path.join(dd.get_work_dir(data), 'structural', dd.get_sample_name(data), 'bins'))
        out_target_file, out_anti_file = calcfns[cnvkit.bin_approach(data)](data, work_dir)
        if not os.path.exists(out_target_file):
            out_target_file, out_anti_file = (None, None)
    if 'seq2c' in dd.get_svcaller(data):
        from bcbio.structural import seq2c
        seq2c_target = seq2c.precall(data)
    else:
        seq2c_target = None
    if not tz.get_in(['depth', 'bins'], data):
        data = tz.update_in(data, ['depth', 'bins'], lambda x: {})
    data['depth']['bins'] = {'target': out_target_file, 'antitarget': out_anti_file, 'seq2c': seq2c_target}
    return [[data]]

def normalize_sv_coverage(*items):
    """Normalize CNV coverage, providing flexible point for multiple methods.
    """
    calcfns = {'cnvkit': _normalize_sv_coverage_cnvkit, 'gatk-cnv': _normalize_sv_coverage_gatk}
    from bcbio.structural import cnvkit
    from bcbio.structural import shared as sshared
    items = [utils.to_single_data(x) for x in cwlutils.handle_combined_input(items)]
    if all((not cnvkit.use_general_sv_bins(x) for x in items)):
        return [[d] for d in items]
    out_files = {}
    back_files = {}
    for group_id, gitems in itertools.groupby(items, lambda x: tz.get_in(['regions', 'bins', 'group'], x)):
        if group_id is None:
            continue
        inputs, backgrounds = sshared.find_case_control(list(gitems))
        assert inputs, 'Did not find inputs for sample batch: %s' % ' '.join((dd.get_sample_name(x) for x in items))
        work_dir = utils.safe_makedir(os.path.join(dd.get_work_dir(inputs[0]), 'structural', dd.get_sample_name(inputs[0]), 'bins'))
        back_files, out_files = calcfns[cnvkit.bin_approach(inputs[0])](group_id, inputs, backgrounds, work_dir, back_files, out_files)
    out = []
    for data in items:
        if dd.get_sample_name(data) in out_files:
            data['depth']['bins']['background'] = back_files[dd.get_sample_name(data)]
            data['depth']['bins']['normalized'] = out_files[dd.get_sample_name(data)]
        out.append([data])
    return out

def _normalize_sv_coverage_gatk(group_id, inputs, backgrounds, work_dir, back_files, out_files):
    """Normalize CNV coverage using panel of normals with GATK's de-noise approaches.
    """
    input_backs = set(filter(lambda x: x is not None, [dd.get_background_cnv_reference(d, 'gatk-cnv') for d in inputs]))
    if input_backs:
        assert len(input_backs) == 1, 'Multiple backgrounds in group: %s' % list(input_backs)
        pon = list(input_backs)[0]
    elif backgrounds:
        pon = gatkcnv.create_panel_of_normals(backgrounds, group_id, work_dir)
    else:
        pon = None
    for data in inputs:
        work_dir = utils.safe_makedir(os.path.join(dd.get_work_dir(data), 'structural', dd.get_sample_name(data), 'bins'))
        denoise_file = gatkcnv.denoise(data, pon, work_dir)
        out_files[dd.get_sample_name(data)] = denoise_file
        back_files[dd.get_sample_name(data)] = pon
    return (back_files, out_files)

def get_base_cnv_regions(data, work_dir, genome_default='transcripts1e4', include_gene_names=True):
    """Retrieve set of target regions for CNV analysis.

    Subsets to extended transcript regions for WGS experiments to avoid
    long runtimes."""
    cov_interval = dd.get_coverage_interval(data)
    base_regions = get_sv_bed(data, include_gene_names=include_gene_names)
    if not base_regions:
        if cov_interval == 'genome':
            base_regions = get_sv_bed(data, genome_default, work_dir, include_gene_names=include_gene_names)
            if base_regions:
                base_regions = remove_exclude_regions(base_regions, base_regions, [data])
        if not base_regions:
            base_regions = dd.get_variant_regions(data) or dd.get_sample_callable(data)
    return bedutils.clean_file(base_regions, data)

def remove_exclude_regions(orig_bed, base_file, items, remove_entire_feature=False):
    """Remove centromere and short end regions from an existing BED file of regions to target.
    """
    from bcbio.structural import shared as sshared
    out_bed = os.path.join('%s-noexclude.bed' % utils.splitext_plus(base_file)[0])
    if not utils.file_uptodate(out_bed, orig_bed):
        exclude_bed = sshared.prepare_exclude_file(items, base_file)
        with file_transaction(items[0], out_bed) as tx_out_bed:
            pybedtools.BedTool(orig_bed).subtract(pybedtools.BedTool(exclude_bed), A=remove_entire_feature, nonamecheck=True).saveas(tx_out_bed)
    if utils.file_exists(out_bed):
        return out_bed
    else:
        return orig_bed

def get_sv_bed(data, method=None, out_dir=None, include_gene_names=True):
    """Retrieve a BED file of regions for SV and heterogeneity calling using the provided method.

    method choices:
      - exons: Raw BED file of exon regions
      - transcripts: Full collapsed regions with the min and max of each transcript.
      - transcriptsXXXX: Collapsed regions around transcripts with a window size of
        XXXX.
      - A custom BED file of regions"""
    if method is None:
        method = tz.get_in(['config', 'algorithm', 'sv_regions'], data) or dd.get_variant_regions(data) or dd.get_sample_callable(data)
    gene_file = dd.get_gene_bed(data)
    if method and os.path.isfile(method):
        return method
    elif not gene_file or not method:
        return None
    elif method == 'exons':
        return gene_file
    elif method.startswith('transcripts'):
        window = method.split('transcripts')[-1]
        window = int(float(window)) if window else 0
        return _collapse_transcripts(gene_file, window, data, out_dir, include_gene_names=include_gene_names)
    else:
        raise ValueError('Unexpected transcript retrieval method: %s' % method)

def _group_coords(rs):
    """Organize coordinate regions into groups for each transcript.

    Avoids collapsing very large introns or repetitive genes spread across
    the chromosome by limiting the intron size to 100kb for creating a single transcript"""
    max_intron_size = 100000.0
    coords = []
    for r in rs:
        coords.append(r.start)
        coords.append(r.end)
    coord_groups = []
    cur_group = []
    for coord in sorted(coords):
        if not cur_group or coord - cur_group[-1] < max_intron_size:
            cur_group.append(coord)
        else:
            coord_groups.append(cur_group)
            cur_group = [coord]
    if cur_group:
        coord_groups.append(cur_group)
    return coord_groups

def phmmer(**kwargs):
    """Search a protein sequence against a HMMER sequence database.

    Arguments:
      seq - The sequence to search -- a Fasta string.
      seqdb -- Sequence database to search against.
      range -- A string range of results to return (ie. 1,10 for the first ten)
      output -- The output format (defaults to JSON)."""
    logging.debug(kwargs)
    args = {'seq': kwargs.get('seq'), 'seqdb': kwargs.get('seqdb')}
    args2 = {'output': kwargs.get('output', 'json'), 'range': kwargs.get('range')}
    return _hmmer('http://hmmer.janelia.org/search/phmmer', args, args2)

def rnaseq_variant_calling(samples, run_parallel):
    """run RNA-seq variant calling using GATK"""
    samples = run_parallel('run_rnaseq_variant_calling', samples)
    variantcaller = dd.get_variantcaller(to_single_data(samples[0]))
    if variantcaller and 'gatk-haplotype' in variantcaller:
        out = []
        for d in joint.square_off(samples, run_parallel):
            out.extend([[to_single_data(xs)] for xs in multi.split_variants_by_sample(to_single_data(d))])
        samples = out
    if variantcaller:
        samples = run_parallel('run_rnaseq_ann_filter', samples)
    if variantcaller and 'gatk-haplotype' in variantcaller:
        out = []
        for data in (to_single_data(xs) for xs in samples):
            if 'variants' not in data:
                data['variants'] = []
            data['variants'].append({'variantcaller': 'gatk-haplotype', 'vcf': data['vrn_file_orig'], 'population': {'vcf': data['vrn_file']}})
            data['vrn_file'] = data.pop('vrn_file_orig')
            out.append([data])
        samples = out
    return samples

def run_rnaseq_variant_calling(data):
    """run RNA-seq variant calling, variation file is stored in `vrn_file`
    in the datadict"""
    variantcaller = dd.get_variantcaller(data)
    if isinstance(variantcaller, list) and len(variantcaller) > 1:
        logger.error('Only one variantcaller can be run for RNA-seq at this time. Post an issue here (https://github.com/bcbio/bcbio-nextgen/issues) if this is something you need to do.')
        sys.exit(1)
    if variantcaller:
        if 'gatk-haplotype' in variantcaller:
            data = variation.rnaseq_gatk_variant_calling(data)
        if vardict.get_vardict_command(data):
            data = variation.rnaseq_vardict_variant_calling(data)
        vrn_file = dd.get_vrn_file(data)
    return [[data]]

def quantitate_expression_noparallel(samples, run_parallel):
    """run transcript quantitation for algorithms that don't run in parallel"""
    data = samples[0][0]
    if 'express' in dd.get_expression_caller(data):
        samples = run_parallel('run_express', samples)
    if 'dexseq' in dd.get_expression_caller(data):
        samples = run_parallel('run_dexseq', samples)
    return samples

def generate_transcript_counts(data):
    """Generate counts per transcript and per exon from an alignment"""
    data['count_file'] = featureCounts.count(data)
    if dd.get_fusion_mode(data, False) and (not dd.get_fusion_caller(data)):
        oncofuse_file = oncofuse.run(data)
        if oncofuse_file:
            data = dd.set_oncofuse_file(data, oncofuse_file)
    if dd.get_transcriptome_align(data):
        if dd.get_disambiguate(data):
            logger.info('Aligning to the transcriptome with bowtie2 using the disambiguated reads.')
            bam_path = data['work_bam']
            fastq_paths = alignprep._bgzip_from_bam(bam_path, data['dirs'], data, is_retry=False, output_infix='-transcriptome')
            if len(fastq_paths) == 2:
                file1, file2 = fastq_paths
            else:
                file1, file2 = (fastq_paths[0], None)
            ref_file = dd.get_ref_file(data)
            data = bowtie2.align_transcriptome(file1, file2, ref_file, data)
        else:
            file1, file2 = dd.get_input_sequence_files(data)
        if not dd.get_transcriptome_bam(data):
            ref_file = dd.get_ref_file(data)
            logger.info('Transcriptome alignment was flagged to run, but the transcriptome BAM file was not found. Aligning to the transcriptome with bowtie2.')
            data = bowtie2.align_transcriptome(file1, file2, ref_file, data)
    data = spikein.counts_spikein(data)
    return [[data]]

def run_dexseq(data):
    """Quantitate exon-level counts with DEXSeq"""
    if dd.get_dexseq_gff(data, None):
        data = dexseq.bcbio_run(data)
    return [[data]]

def assemble_transcripts(run_parallel, samples):
    """assembly strategy rationale implemented as suggested in
    http://www.nature.com/nprot/journal/v7/n3/full/nprot.2012.016.html

    run Cufflinks in without a reference GTF for each individual sample
    merge the assemblies with Cuffmerge using a reference GTF"""
    assembler = dd.get_in_samples(samples, dd.get_transcript_assembler)
    data = samples[0][0]
    if assembler:
        if 'cufflinks' in assembler:
            samples = run_parallel('cufflinks_assemble', samples)
        if 'stringtie' in assembler:
            samples = run_parallel('run_stringtie_expression', samples)
        if 'stringtie' in assembler and stringtie.supports_merge(data):
            samples = run_parallel('stringtie_merge', [samples])
        else:
            samples = run_parallel('cufflinks_merge', [samples])
    return samples

def _prepare_bam_file(bam_file, tmp_dir, config):
    """Pipe sort by name cmd in case sort by coordinates"""
    sort_mode = _get_sort_order(bam_file, config)
    if sort_mode != 'queryname':
        bam_file = sort(bam_file, config, 'queryname')
    return bam_file

def shared_variantcall(call_fn, name, align_bams, ref_file, items, assoc_files, region=None, out_file=None):
    """Provide base functionality for prepping and indexing for variant calling.
    """
    config = items[0]['config']
    if out_file is None:
        if vcfutils.is_paired_analysis(align_bams, items):
            out_file = '%s-paired-variants.vcf.gz' % config['metdata']['batch']
        else:
            out_file = '%s-variants.vcf.gz' % os.path.splitext(align_bams[0])[0]
    if not file_exists(out_file):
        logger.debug('Genotyping with {name}: {region} {fname}'.format(name=name, region=region, fname=os.path.basename(align_bams[0])))
        variant_regions = bedutils.population_variant_regions(items, merged=True)
        target_regions = subset_variant_regions(variant_regions, region, out_file, items=items)
        if variant_regions is not None and isinstance(target_regions, six.string_types) and (not os.path.isfile(target_regions)):
            vcfutils.write_empty_vcf(out_file, config)
        else:
            with file_transaction(config, out_file) as tx_out_file:
                call_fn(align_bams, ref_file, items, target_regions, tx_out_file)
    if out_file.endswith('.gz'):
        out_file = vcfutils.bgzip_and_index(out_file, config)
    return out_file

def run_samtools(align_bams, items, ref_file, assoc_files, region=None, out_file=None):
    """Detect SNPs and indels with samtools mpileup and bcftools.
    """
    return shared_variantcall(_call_variants_samtools, 'samtools', align_bams, ref_file, items, assoc_files, region, out_file)

def _convert_fastq(srafn, outdir, single=False):
    """convert sra to fastq"""
    cmd = 'fastq-dump --split-files --gzip {srafn}'
    cmd = '%s %s' % (utils.local_path_export(), cmd)
    sraid = os.path.basename(utils.splitext_plus(srafn)[0])
    if not srafn:
        return None
    if not single:
        out_file = [os.path.join(outdir, '%s_1.fastq.gz' % sraid), os.path.join(outdir, '%s_2.fastq.gz' % sraid)]
        if not utils.file_exists(out_file[0]):
            with utils.chdir(outdir):
                do.run(cmd.format(**locals()), 'Covert to fastq %s' % sraid)
        if not utils.file_exists(out_file[0]):
            raise IOError("SRA %s didn't convert, something happened." % srafn)
        return [out for out in out_file if utils.file_exists(out)]
    else:
        raise ValueError('Not supported single-end sra samples for now.')

def _remap_dirname(local, remote):
    """Remap directory names from local to remote.
    """
    def do(x):
        return x.replace(local, remote, 1)
    return do

def _find_unprocessed(config):
    """Find any finished directories that have not been processed.
    """
    reported = _read_reported(config['msg_db'])
    for dname in _get_directories(config):
        if os.path.isdir(dname) and dname not in reported:
            if _is_finished_dumping(dname):
                yield dname

def _expected_reads(run_info_file):
    """Parse the number of expected reads from the RunInfo.xml file.
    """
    reads = []
    if os.path.exists(run_info_file):
        tree = ElementTree()
        tree.parse(run_info_file)
        read_elem = tree.find('Run/Reads')
        reads = read_elem.findall('Read')
    return len(reads)

def _read_reported(msg_db):
    """Retrieve a list of directories previous reported.
    """
    reported = []
    if os.path.exists(msg_db):
        with open(msg_db) as in_handle:
            for line in in_handle:
                reported.append(line.strip())
    return reported

def get_files(data):
    """Retrieve pre-installed viral reference files.
    """
    all_files = glob.glob(os.path.normpath(os.path.join(os.path.dirname(dd.get_ref_file(data)), os.pardir, 'viral', '*')))
    return sorted(all_files)

def _setup_variant_regions(data, out_dir):
    """Ensure we have variant regions for calling, using transcript if not present.

    Respects noalt_calling by removing additional contigs to improve
    speeds."""
    vr_file = dd.get_variant_regions(data)
    if not vr_file:
        vr_file = regions.get_sv_bed(data, 'transcripts', out_dir=out_dir)
    contigs = set([c.name for c in ref.file_contigs(dd.get_ref_file(data))])
    out_file = os.path.join(utils.safe_makedir(os.path.join(dd.get_work_dir(data), 'bedprep')), '%s-rnaseq_clean.bed' % utils.splitext_plus(os.path.basename(vr_file))[0])
    if not utils.file_uptodate(out_file, vr_file):
        with file_transaction(data, out_file) as tx_out_file:
            with open(tx_out_file, 'w') as out_handle:
                with shared.bedtools_tmpdir(data):
                    for r in pybedtools.BedTool(vr_file):
                        if r.chrom in contigs:
                            if chromhacks.is_nonalt(r.chrom):
                                out_handle.write(str(r))
    data = dd.set_variant_regions(data, out_file)
    return data

def _clean_args(sys_argv, args):
    """Remove data directory from arguments to pass to upgrade function.
    """
    base = [x for x in sys_argv if x.startswith('-') or not args.datadir == os.path.abspath(os.path.expanduser(x))]
    base = [x for x in base if x not in set(['--minimize-disk'])]
    if '--nodata' in base:
        base.remove('--nodata')
    else:
        base.append('--data')
    return base

def install_anaconda_python(args):
    """Provide isolated installation of Anaconda python for running bcbio-nextgen.
    http://docs.continuum.io/anaconda/index.html"""
    anaconda_dir = os.path.join(args.datadir, 'anaconda')
    bindir = os.path.join(anaconda_dir, 'bin')
    conda = os.path.join(bindir, 'conda')
    if not os.path.exists(anaconda_dir) or not os.path.exists(conda):
        if os.path.exists(anaconda_dir):
            shutil.rmtree(anaconda_dir)
        dist = args.distribution if args.distribution else _guess_distribution()
        url = REMOTES['anaconda'] % ('MacOSX' if dist.lower() == 'macosx' else 'Linux')
        if not os.path.exists(os.path.basename(url)):
            subprocess.check_call(['wget', '--progress=dot:mega', '--no-check-certificate', url])
        subprocess.check_call('bash %s -b -p %s' % (os.path.basename(url), anaconda_dir), shell=True)
    return {'conda': conda, 'pip': os.path.join(bindir, 'pip'), 'dir': anaconda_dir}

def setup_manifest(datadir):
    """Create barebones manifest to be filled in during update
    """
    manifest_dir = os.path.join(datadir, 'manifest')
    if not os.path.exists(manifest_dir):
        os.makedirs(manifest_dir)

def check_dependencies():
    """Ensure required tools for installation are present.
    """
    print('Checking required dependencies')
    for dep, msg in [(['git', '--version'], 'Git (http://git-scm.com/)'), (['wget', '--version'], 'wget'), (['bzip2', '-h'], 'bzip2')]:
        try:
            p = subprocess.Popen(dep, stderr=subprocess.STDOUT, stdout=subprocess.PIPE)
            out, code = p.communicate()
        except OSError:
            out = 'Executable not found'
            code = 127
        if code == 127:
            raise OSError('bcbio-nextgen installer requires %s\n%s' % (msg, out))

def _check_toolplus(x):
    """Parse options for adding non-standard/commercial tools like GATK and MuTecT.
    """
    import argparse
    Tool = collections.namedtuple('Tool', ['name', 'fname'])
    std_choices = set(['data', 'cadd', 'dbnsfp', 'ericscript'])
    if x in std_choices:
        return Tool(x, None)
    elif '=' in x and len(x.split('=')) == 2:
        name, fname = x.split('=')
        fname = os.path.normpath(os.path.realpath(fname))
        if not os.path.exists(fname):
            raise argparse.ArgumentTypeError('Unexpected --toolplus argument for %s. File does not exist: %s' % (name, fname))
        return Tool(name, fname)
    else:
        raise argparse.ArgumentTypeError('Unexpected --toolplus argument. Expect toolname=filename.')

def _cwlvar_to_wdl(var):
    """Convert a CWL output object into a WDL output.

    This flattens files and other special CWL outputs that are
    plain strings in WDL."""
    if isinstance(var, (list, tuple)):
        return [_cwlvar_to_wdl(x) for x in var]
    elif isinstance(var, dict):
        assert var.get('class') == 'File', var
        return var.get('path') or var['value']
    else:
        return var

def _get_record_attrs(out_keys):
    """Check for records, a single key plus output attributes.
    """
    if len(out_keys) == 1:
        attr = list(out_keys.keys())[0]
        if out_keys[attr]:
            return (attr, out_keys[attr])
    return (None, None)

def _add_resources(data, runtime):
    """Merge input resources with current CWL runtime parameters.
    """
    if 'config' not in data:
        data['config'] = {}
    resources = data.get('resources', {}) or {}
    if isinstance(resources, six.string_types) and resources.startswith(('{', '[')):
        resources = json.loads(resources)
        data['resources'] = resources
    assert isinstance(resources, dict), (resources, data)
    data['config']['resources'] = resources
    memory = int(float(runtime['ram']) / float(runtime['cores']))
    data['config']['resources'].update({'default': {'cores': int(runtime['cores']), 'memory': '%sM' % memory, 'jvm_opts': ['-Xms%sm' % min(1000, memory // 2), '-Xmx%sm' % memory]}})
    data['config']['algorithm']['num_cores'] = int(runtime['cores'])
    return data

def _parse_output_keys(val):
    """Parse expected output keys from string, handling records.
    """
    out = {}
    for k in val.split(','):
        if ':' in k:
            name, attrs = k.split(':')
            out[name] = attrs.split(';')
        else:
            out[k] = None
    return out

def _find_input_files(var, out):
    """Find input files within the given CWL object.
    """
    if isinstance(var, (list, tuple)):
        for x in var:
            out = _find_input_files(x, out)
    elif isinstance(var, dict):
        if var.get('class') == 'File':
            out.append(var['path'])
            out = _find_input_files(var.get('secondaryFiles', []), out)
        for key, val in var.items():
            out = _find_input_files(val, out)
    return out

def _read_from_cwlinput(in_file, work_dir, runtime, parallel, input_order, output_cwl_keys):
    """Read data records from a JSON dump of inputs. Avoids command line flattening of records.
    """
    with open(in_file) as in_handle:
        inputs = json.load(in_handle)
    items_by_key = {}
    input_files = []
    passed_keys = set([])
    for key, input_val in ((k, v) for k, v in inputs.items() if not k.startswith(('sentinel', 'ignore'))):
        if key.endswith('_toolinput'):
            key = key.replace('_toolinput', '')
        if input_order[key] == 'record':
            cur_keys, items = _read_cwl_record(input_val)
            passed_keys |= cur_keys
            items_by_key[key] = items
        else:
            items_by_key[tuple(key.split('__'))] = _cwlvar_to_wdl(input_val)
        input_files = _find_input_files(input_val, input_files)
    prepped = _merge_cwlinputs(items_by_key, input_order, parallel)
    out = []
    for data in prepped:
        if isinstance(data, (list, tuple)):
            out.append([_finalize_cwl_in(utils.to_single_data(x), work_dir, list(passed_keys), output_cwl_keys, runtime) for x in data])
        else:
            out.append(_finalize_cwl_in(data, work_dir, list(passed_keys), output_cwl_keys, runtime))
    return (out, input_files)

def _maybe_nest_bare_single(items_by_key, parallel):
    """Nest single inputs to avoid confusing single items and lists like files.
    """
    if parallel == 'multi-parallel' and sum([1 for x in items_by_key.values() if not _is_nested_item(x)]) >= sum([1 for x in items_by_key.values() if _is_nested_item(x)]):
        out = {}
        for k, v in items_by_key.items():
            out[k] = [v]
        return out
    else:
        return items_by_key

def _check_for_single_nested(target, items_by_key, input_order):
    """Check for single nested inputs that match our target count and unnest.

    Handles complex var inputs where some have an extra layer of nesting."""
    out = utils.deepish_copy(items_by_key)
    for k, t in input_order.items():
        if t == 'var':
            v = items_by_key[tuple(k.split('__'))]
            if _is_nested_single(v, target):
                out[tuple(k.split('__'))] = v[0]
    return out

def _concat_records(items_by_key, input_order):
    """Concatenate records into a single key to avoid merging.

    Handles heterogeneous records that will then be sorted out in
    the processing fuction."""
    all_records = []
    for k, t in input_order.items():
        if t == 'record':
            all_records.append(k)
    out_items_by_key = utils.deepish_copy(items_by_key)
    out_input_order = utils.deepish_copy(input_order)
    if len(all_records) > 1:
        final_k = all_records[0]
        final_v = items_by_key[final_k]
        for k in all_records[1:]:
            final_v += items_by_key[k]
            del out_items_by_key[k]
            del out_input_order[k]
        out_items_by_key[final_k] = final_v
    return (out_items_by_key, out_input_order)

def _nest_vars_in_rec(var_items, rec_items, input_order, items_by_key, parallel):
    """Nest multiple variable inputs into a single record or list of batch records.

    Custom CWL implementations extract and merge these."""
    num_items = var_items
    var_items = list(var_items)[0]
    if rec_items:
        rec_items = list(rec_items)[0]
        if rec_items == 1 and var_items > 1 or parallel.startswith('batch'):
            num_items = set([rec_items])
            for var_key in (k for k, t in input_order.items() if t != 'record'):
                var_key = tuple(var_key.split('__'))
                items_by_key[var_key] = [items_by_key[var_key]] * rec_items
        else:
            assert var_items == rec_items, (var_items, rec_items)
    return (items_by_key, num_items)

def _expand_rec_to_vars(var_items, rec_items, input_order, items_by_key, parallel):
    """Expand record to apply to number of variants.

    Alternative approach to _nest_vars_in_rec
    to combining a single record with multiple variants."""
    num_items = var_items
    var_items = list(var_items)[0]
    if rec_items:
        for rec_key in (k for k, t in input_order.items() if t == 'record'):
            rec_vals = items_by_key[rec_key]
            if len(rec_vals) == 1 and var_items > 1:
                items_by_key[rec_key] = rec_vals * var_items
            else:
                assert var_items == len(rec_vals), (var_items, rec_vals)
    return (items_by_key, num_items)

def _read_cwl_record(rec):
    """Read CWL records, handling multiple nesting and batching cases.
    """
    keys = set([])
    out = []
    if isinstance(rec, dict):
        is_batched = all([isinstance(v, (list, tuple)) for v in rec.values()])
        cur = [{} for _ in range(len(rec.values()[0]) if is_batched else 1)]
        for k in rec.keys():
            keys.add(k)
            val = rec[k]
            val = val if is_batched else [val]
            for i, v in enumerate(val):
                v = _cwlvar_to_wdl(v)
                cur[i] = _update_nested(k.split('__'), v, cur[i])
        if is_batched:
            out.append(cur)
        else:
            assert len(cur) == 1
            out.append(cur[0])
    else:
        assert isinstance(rec, (list, tuple))
        for sub_rec in rec:
            sub_keys, sub_out = _read_cwl_record(sub_rec)
            keys |= sub_keys
            out.append(sub_out)
    return (keys, out)

def _finalize_cwl_in(data, work_dir, passed_keys, output_cwl_keys, runtime):
    """Finalize data object with inputs from CWL.
    """
    data['dirs'] = {'work': work_dir}
    if not tz.get_in(['config', 'algorithm'], data):
        if 'config' not in data:
            data['config'] = {}
        data['config']['algorithm'] = {}
    if 'rgnames' not in data and 'description' in data:
        data['rgnames'] = {'sample': data['description']}
    data['cwl_keys'] = passed_keys
    data['output_cwl_keys'] = output_cwl_keys
    data = _add_resources(data, runtime)
    data = cwlutils.normalize_missing(data)
    data = run_info.normalize_world(data)
    return data

def _convert_value(val):
    """Handle multiple input type values.
    """
    def _is_number(x, op):
        try:
            op(x)
            return True
        except ValueError:
            return False
    if isinstance(val, (list, tuple)):
        return [_convert_value(x) for x in val]
    elif val is None:
        return val
    elif _is_number(val, int):
        return int(val)
    elif _is_number(val, float):
        return float(val)
    elif val.find(';;') >= 0:
        return [_convert_value(v) for v in val.split(';;')]
    elif val.startswith(('{', '[')):
        return json.loads(val.replace("u'", "'").replace("'", '"'))
    elif val.lower() == 'true':
        return True
    elif val.lower() == 'false':
        return False
    else:
        return val

def _convert_to_cwl_json(data, fnargs, input_files):
    """Convert world data object (or list of data objects) into outputs for CWL ingestion.
    """
    out = {}
    for outvar in _get_output_cwl_keys(fnargs):
        keys = []
        for key in outvar.split('__'):
            try:
                key = int(key)
            except ValueError:
                pass
            keys.append(key)
        if isinstance(data, dict):
            out[outvar] = _to_cwl(tz.get_in(keys, data), input_files)
        else:
            out[outvar] = [_to_cwl(tz.get_in(keys, x), input_files) for x in data]
    return out

def _get_output_cwl_keys(fnargs):
    """Retrieve output_cwl_keys from potentially nested input arguments.
    """
    for d in utils.flatten(fnargs):
        if isinstance(d, dict) and d.get('output_cwl_keys'):
            return d['output_cwl_keys']
    raise ValueError('Did not find output_cwl_keys in %s' % pprint.pformat(fnargs))

def _combine_cwl_records(recs, record_name, parallel):
    """Provide a list of nexted CWL records keyed by output key.

    Handles batches, where we return a list of records, and single items
    where we return one record."""
    if parallel not in ['multi-batch', 'single-split', 'multi-combined', 'batch-single']:
        assert len(recs) == 1, pprint.pformat(recs)
        return {record_name: recs[0]}
    else:
        return {record_name: recs}

def _collapse_to_cwl_record_single(data, want_attrs, input_files):
    """Convert a single sample into a CWL record.
    """
    out = {}
    for key in want_attrs:
        key_parts = key.split('__')
        out[key] = _to_cwl(tz.get_in(key_parts, data), input_files)
    return out

def _nested_cwl_record(xs, want_attrs, input_files):
    """Convert arbitrarily nested samples into a nested list of dictionaries.

    nests only at the record level, rather than within records. For batching
    a top level list is all of the batches and sub-lists are samples within the
    batch."""
    if isinstance(xs, (list, tuple)):
        return [_nested_cwl_record(x, want_attrs, input_files) for x in xs]
    else:
        assert isinstance(xs, dict), pprint.pformat(xs)
        return _collapse_to_cwl_record_single(xs, want_attrs, input_files)

def _collapse_to_cwl_record(samples, want_attrs, input_files):
    """Convert nested samples from batches into a CWL record, based on input keys.
    """
    input_keys = sorted(list(set().union(*[d['cwl_keys'] for d in samples])), key=lambda x: (-len(x), tuple(x)))
    out = {}
    for key in input_keys:
        if key in want_attrs:
            key_parts = key.split('__')
            vals = []
            cur = []
            for d in samples:
                vals.append(_to_cwl(tz.get_in(key_parts, d), input_files))
                cur.append(_dissoc_in(d, key_parts) if len(key_parts) > 1 else d)
            samples = cur
            out[key] = vals
    return out

def _remove_duplicate_files(xs):
    """Remove files specified multiple times in a list.
    """
    seen = set([])
    out = []
    for x in xs:
        if x['path'] not in seen:
            out.append(x)
            seen.add(x['path'])
    return out

def _update_nested(key, val, data, allow_overwriting=False):
    """Update the data object, avoiding over-writing with nested dictionaries.
    """
    if isinstance(val, dict):
        for sub_key, sub_val in val.items():
            data = _update_nested(key + [sub_key], sub_val, data, allow_overwriting=allow_overwriting)
    else:
        already_there = tz.get_in(key, data) is not None
        if already_there and val:
            if not allow_overwriting:
                raise ValueError('Duplicated key %s: %s and %s' % (key, val, tz.get_in(key, data)))
            else:
                already_there = False
        if val or not already_there:
            data = tz.update_in(data, key, lambda x: val)
    return data

def write_versions(dirs, items):
    """Write data versioning for genomes present in the configuration.
    """
    genomes = {}
    for d in items:
        genomes[d['genome_build']] = d.get('reference', {}).get('versions')
    out_file = _get_out_file(dirs)
    found_versions = False
    if genomes and out_file:
        with open(out_file, 'w') as out_handle:
            writer = csv.writer(out_handle)
            writer.writerow(['genome', 'resource', 'version'])
            for genome, version_file in genomes.items():
                if not version_file:
                    genome_dir = install.get_genome_dir(genome, dirs.get('galaxy'), items[0])
                    if genome_dir:
                        version_file = os.path.join(genome_dir, 'versions.csv')
                if version_file and os.path.exists(version_file):
                    found_versions = True
                    with open(version_file) as in_handle:
                        reader = csv.reader(in_handle)
                        for parts in reader:
                            if len(parts) >= 2:
                                resource, version = parts[:2]
                                writer.writerow([genome, resource, version])
    if found_versions:
        return out_file

def batch(samples):
    """CWL: batch together per sample, joint and germline calls for ensemble combination.

    Sets up groups of same sample/batch variant calls for ensemble calling, as
    long as we have more than one caller per group."""
    samples = [utils.to_single_data(x) for x in samples]
    sample_order = [dd.get_sample_name(x) for x in samples]
    batch_groups = collections.defaultdict(list)
    for data in samples:
        batch_samples = tuple(data.get('batch_samples', [dd.get_sample_name(data)]))
        batch_groups[batch_samples, dd.get_phenotype(data)].append(data)
    out = []
    for (batch_samples, phenotype), gsamples in batch_groups.items():
        if len(gsamples) > 1:
            batches = set([])
            for d in gsamples:
                batches |= set(dd.get_batches(d))
            gsamples.sort(key=dd.get_variantcaller_order)
            cur = copy.deepcopy(gsamples[0])
            cur.update({'batch_id': sorted(list(batches))[0] if batches else '_'.join(batch_samples), 'batch_samples': batch_samples, 'variants': {'variantcallers': [dd.get_variantcaller(d) for d in gsamples], 'calls': [d.get('vrn_file') for d in gsamples]}})
            out.append(cur)
    def by_original_order(d):
        return min([sample_order.index(s) for s in d['batch_samples'] if s in sample_order])
    return sorted(out, key=by_original_order)

def combine_calls_parallel(samples, run_parallel):
    """Combine calls using batched Ensemble approach.
    """
    batch_groups, extras = _group_by_batches(samples, _has_ensemble)
    out = []
    if batch_groups:
        processed = run_parallel('combine_calls', ((b, xs, xs[0]) for b, xs in batch_groups.items()))
        for batch_id, callinfo in processed:
            for data in batch_groups[batch_id]:
                data['variants'].insert(0, callinfo)
                out.append([data])
    return out + extras

def _group_by_batches(samples, check_fn):
    """Group calls by batches, processing families together during ensemble calling.
    """
    batch_groups = collections.defaultdict(list)
    extras = []
    for data in [x[0] for x in samples]:
        if check_fn(data):
            batch_groups[multi.get_batch_for_key(data)].append(data)
        else:
            extras.append([data])
    return (batch_groups, extras)

def _organize_variants(samples, batch_id):
    """Retrieve variant calls for all samples, merging batched samples into single VCF.
    """
    caller_names = [x['variantcaller'] for x in samples[0]['variants']]
    calls = collections.defaultdict(list)
    for data in samples:
        for vrn in data['variants']:
            calls[vrn['variantcaller']].append(vrn['vrn_file'])
    data = samples[0]
    vrn_files = []
    for caller in caller_names:
        fnames = calls[caller]
        if len(fnames) == 1:
            vrn_files.append(fnames[0])
        else:
            vrn_files.append(population.get_multisample_vcf(fnames, batch_id, caller, data))
    return (caller_names, vrn_files)

def _run_ensemble(batch_id, vrn_files, config_file, base_dir, ref_file, data):
    """Run an ensemble call using merging and SVM-based approach in bcbio.variation
    """
    out_vcf_file = os.path.join(base_dir, '{0}-ensemble.vcf'.format(batch_id))
    out_bed_file = os.path.join(base_dir, '{0}-callregions.bed'.format(batch_id))
    work_dir = '%s-work' % os.path.splitext(out_vcf_file)[0]
    if not utils.file_exists(out_vcf_file):
        _bcbio_variation_ensemble(vrn_files, out_vcf_file, ref_file, config_file, base_dir, data)
        if not utils.file_exists(out_vcf_file):
            base_vcf = glob.glob(os.path.join(work_dir, 'prep', '*-cfilter.vcf'))[0]
            utils.symlink_plus(base_vcf, out_vcf_file)
    if not utils.file_exists(out_bed_file):
        multi_beds = glob.glob(os.path.join(work_dir, 'prep', '*-multicombine.bed'))
        if len(multi_beds) > 0:
            utils.symlink_plus(multi_beds[0], out_bed_file)
    return {'variantcaller': 'ensemble', 'vrn_file': out_vcf_file, 'bed_file': out_bed_file if os.path.exists(out_bed_file) else None}

def _get_num_pass(data, n):
    """Calculate the number of samples needed to pass ensemble calling.
    """
    numpass = tz.get_in(['config', 'algorithm', 'ensemble', 'numpass'], data)
    if numpass:
        return int(numpass)
    trusted_pct = tz.get_in(['config', 'algorithm', 'ensemble', 'trusted_pct'], data)
    if trusted_pct:
        return int(math.ceil(float(trusted_pct) * n))
    return 2

def get_genome_refs(loc_file, loc_type):
    """get dictionary of genome: location for all genomes of type in a .loc file
    for example: {'hg19': '/genomedir/Hsapiens/hg19/seq/hg19.fa'}"""
    if not file_exists(loc_file):
        return None
    refs = {}
    with open(loc_file) as in_handle:
        for line in in_handle:
            if not line.startswith('#'):
                parts = line.strip().split()
                if loc_type in ['bowtie2', 'samtools', 'alignseq']:
                    refs[parts[1]] = parts[-1]
                else:
                    refs[parts[0]] = parts[-1]
    return refs

def _get_callable_regions(data):
    """Retrieve regions to parallelize by from callable regions or chromosomes.
    """
    import pybedtools
    callable_files = data.get('callable_regions')
    if callable_files:
        assert len(callable_files) == 1
        regions = [(r.chrom, int(r.start), int(r.stop)) for r in pybedtools.BedTool(callable_files[0])]
    else:
        work_bam = list(tz.take(1, filter(lambda x: x and x.endswith('.bam'), data['work_bams'])))
        if work_bam:
            with pysam.Samfile(work_bam[0], 'rb') as pysam_bam:
                regions = [(chrom, 0, length) for chrom, length in zip(pysam_bam.references, pysam_bam.lengths)]
        else:
            regions = [(r.name, 0, r.size) for r in ref.file_contigs(dd.get_ref_file(data), data['config'])]
    return regions

def square_off(samples, run_parallel):
    """Perform joint calling at all variants within a batch.
    """
    to_process = []
    extras = []
    for data in [utils.to_single_data(x) for x in samples]:
        added = False
        if tz.get_in(('metadata', 'batch'), data):
            for add in genotype.handle_multiple_callers(data, 'jointcaller', require_bam=False):
                if _is_jointcaller_compatible(add):
                    added = True
                    to_process.append([add])
        if not added:
            extras.append([data])
    processed = grouped_parallel_split_combine(to_process, _split_by_callable_region, multi.group_batches_joint, run_parallel, 'square_batch_region', 'concat_variant_files', 'vrn_file', ['region', 'sam_ref', 'config'])
    return _combine_to_jointcaller(processed) + extras

def square_batch_region(data, region, bam_files, vrn_files, out_file):
    """Perform squaring of a batch in a supplied region, with input BAMs
    """
    from bcbio.variation import sentieon, strelka2
    if not utils.file_exists(out_file):
        jointcaller = tz.get_in(('config', 'algorithm', 'jointcaller'), data)
        if jointcaller in ['%s-joint' % x for x in SUPPORTED['general']]:
            _square_batch_bcbio_variation(data, region, bam_files, vrn_files, out_file, 'square')
        elif jointcaller in ['%s-merge' % x for x in SUPPORTED['general']]:
            _square_batch_bcbio_variation(data, region, bam_files, vrn_files, out_file, 'merge')
        elif jointcaller in ['%s-joint' % x for x in SUPPORTED['gatk']]:
            gatkjoint.run_region(data, region, vrn_files, out_file)
        elif jointcaller in ['%s-joint' % x for x in SUPPORTED['gvcf']]:
            strelka2.run_gvcfgenotyper(data, region, vrn_files, out_file)
        elif jointcaller in ['%s-joint' % x for x in SUPPORTED['sentieon']]:
            sentieon.run_gvcftyper(vrn_files, out_file, region, data)
        else:
            raise ValueError('Unexpected joint calling approach: %s.' % jointcaller)
    if region:
        data['region'] = region
    data = _fix_orig_vcf_refs(data)
    data['vrn_file'] = out_file
    return [data]

def _fix_orig_vcf_refs(data):
    """Supply references to initial variantcalls if run in addition to batching.
    """
    variantcaller = tz.get_in(('config', 'algorithm', 'variantcaller'), data)
    if variantcaller:
        data['vrn_file_orig'] = data['vrn_file']
    for i, sub in enumerate(data.get('group_orig', [])):
        sub_vrn = sub.pop('vrn_file', None)
        if sub_vrn:
            sub['vrn_file_orig'] = sub_vrn
            data['group_orig'][i] = sub
    return data

def _get_seq2c_options(data):
    """Get adjustable, through resources, or default options for seq2c.
    """
    cov2lr_possible_opts = ['-F']
    defaults = {}
    ropts = config_utils.get_resources('seq2c', data['config']).get('options', [])
    assert len(ropts) % 2 == 0, 'Expect even number of options for seq2c' % ropts
    defaults.update(dict(tz.partition(2, ropts)))
    cov2lr_out, lr2gene_out = ([], [])
    for k, v in defaults.items():
        if k in cov2lr_possible_opts:
            cov2lr_out += [str(k), str(v)]
        else:
            lr2gene_out += [str(k), str(v)]
    return (cov2lr_out, lr2gene_out)

def to_vcf(in_tsv, data):
    """Convert seq2c output file into BED output.
    """
    call_convert = {'Amp': 'DUP', 'Del': 'DEL'}
    out_file = '%s.vcf' % utils.splitext_plus(in_tsv)[0]
    if not utils.file_uptodate(out_file, in_tsv):
        with file_transaction(data, out_file) as tx_out_file:
            with open(in_tsv) as in_handle:
                with open(tx_out_file, 'w') as out_handle:
                    out_handle.write(VCF_HEADER + '#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\tFORMAT\t%s\n' % dd.get_sample_name(data))
                    header = in_handle.readline().split('\t')
                    for cur in (dict(zip(header, l.split('\t'))) for l in in_handle):
                        if cur['Amp_Del'] in call_convert:
                            svtype = call_convert[cur['Amp_Del']]
                            info = 'SVTYPE=%s;END=%s;SVLEN=%s;FOLD_CHANGE_LOG=%s;PROBES=%s;GENE=%s' % (svtype, cur['End'], int(cur['End']) - int(cur['Start']), cur['Log2ratio'], cur['Ab_Seg'], cur['Gene'])
                            out_handle.write('\t'.join([cur['Chr'], cur['Start'], '.', 'N', '<%s>' % svtype, '.', '.', info, 'GT', '1/1']) + '\n')
    return vcfutils.sort_by_ref(out_file, data)

def _combine_coverages(items, work_dir, input_backs=None):
    """Combine coverage cnns calculated for individual inputs into single file.

    Optionally moves over pre-calculated coverage samples from a background file."""
    out_file = os.path.join(work_dir, 'sample_coverages.txt')
    if not utils.file_exists(out_file):
        with file_transaction(items[0], out_file) as tx_out_file:
            with open(tx_out_file, 'w') as out_f:
                for data in items:
                    cov_file = tz.get_in(['depth', 'bins', 'seq2c'], data)
                    with open(cov_file) as cov_f:
                        out_f.write(cov_f.read())
                if input_backs:
                    for input_back in input_backs:
                        with open(input_back) as in_handle:
                            for line in in_handle:
                                if len(line.split()) >= 4:
                                    out_f.write(line)
    return out_file

def _calculate_mapping_reads(items, work_dir, input_backs=None):
    """Calculate read counts from samtools idxstats for each sample.

    Optionally moves over pre-calculated mapping counts from a background file."""
    out_file = os.path.join(work_dir, 'mapping_reads.txt')
    if not utils.file_exists(out_file):
        lines = []
        for data in items:
            count = 0
            for line in subprocess.check_output(['samtools', 'idxstats', dd.get_align_bam(data)]).decode().split('\n'):
                if line.strip():
                    count += int(line.split('\t')[2])
            lines.append('%s\t%s' % (dd.get_sample_name(data), count))
        with file_transaction(items[0], out_file) as tx_out_file:
            with open(tx_out_file, 'w') as out_handle:
                out_handle.write('\n'.join(lines) + '\n')
                if input_backs:
                    for input_back in input_backs:
                        with open(input_back) as in_handle:
                            for line in in_handle:
                                if len(line.split()) == 2:
                                    out_handle.write(line)
    return out_file

def get_resources(genome, ref_file, data):
    """Retrieve genome information from a genome-references.yaml file.
    """
    base_dir = os.path.normpath(os.path.dirname(ref_file))
    resource_file = os.path.join(base_dir, '%s-resources.yaml' % genome.replace('-test', ''))
    if not os.path.exists(resource_file):
        raise IOError('Did not find resource file for %s: %s\nTo update bcbio_nextgen.py with genome resources for standard builds, run:\nbcbio_nextgen.py upgrade -u skip' % (genome, resource_file))
    with open(resource_file) as in_handle:
        resources = yaml.safe_load(in_handle)
    def resource_file_path(x):
        if isinstance(x, six.string_types) and os.path.exists(os.path.join(base_dir, x)):
            return os.path.normpath(os.path.join(base_dir, x))
        return x
    cleaned = utils.dictapply(resources, resource_file_path)
    return ensure_annotations(cleaned, data)

def add_required_resources(resources):
    """Add default or empty values for required resources referenced in CWL
    """
    required = [['variation', 'cosmic'], ['variation', 'clinvar'], ['variation', 'dbsnp'], ['variation', 'lcr'], ['variation', 'polyx'], ['variation', 'encode_blacklist'], ['variation', 'gc_profile'], ['variation', 'germline_het_pon'], ['variation', 'train_hapmap'], ['variation', 'train_indels'], ['variation', 'editing'], ['variation', 'exac'], ['variation', 'esp'], ['variation', 'gnomad_exome'], ['variation', '1000g'], ['aliases', 'human']]
    for key in required:
        if not tz.get_in(key, resources):
            resources = tz.update_in(resources, key, lambda x: None)
    return resources

def _get_galaxy_loc_file(name, galaxy_dt, ref_dir, galaxy_base):
    """Retrieve Galaxy *.loc file for the given reference/aligner name.

    First tries to find an aligner specific *.loc file. If not defined
    or does not exist, then we need to try and remap it from the
    default reference file"""
    if 'file' in galaxy_dt and os.path.exists(os.path.join(galaxy_base, galaxy_dt['file'])):
        loc_file = os.path.join(galaxy_base, galaxy_dt['file'])
        need_remap = False
    elif alignment.TOOLS[name].galaxy_loc_file is None:
        loc_file = os.path.join(ref_dir, alignment.BASE_LOCATION_FILE)
        need_remap = True
    else:
        loc_file = os.path.join(ref_dir, alignment.TOOLS[name].galaxy_loc_file)
        need_remap = False
    if not os.path.exists(loc_file):
        loc_file = os.path.join(ref_dir, alignment.BASE_LOCATION_FILE)
        need_remap = True
    return (loc_file, need_remap)

def _galaxy_loc_iter(loc_file, galaxy_dt, need_remap=False):
    """Iterator returning genome build and references from Galaxy *.loc file.
    """
    if 'column' in galaxy_dt:
        dbkey_i = galaxy_dt['column'].index('dbkey')
        path_i = galaxy_dt['column'].index('path')
    else:
        dbkey_i = None
    if os.path.exists(loc_file):
        with open(loc_file) as in_handle:
            for line in in_handle:
                if line.strip() and (not line.startswith('#')):
                    parts = [x.strip() for x in line.strip().split('\t')]
                    if len(parts) == 1:
                        parts = [x.strip() for x in line.strip().split(' ') if x.strip()]
                        if len(parts) > 1:
                            raise IOError('Galaxy location file uses spaces instead of tabs to separate fields: %s' % loc_file)
                    if dbkey_i is not None and (not need_remap):
                        dbkey = parts[dbkey_i]
                        cur_ref = parts[path_i]
                    else:
                        if parts[0] == 'index':
                            parts = parts[1:]
                        dbkey = parts[0]
                        cur_ref = parts[-1]
                    yield (dbkey, cur_ref)

def _get_galaxy_tool_info(galaxy_base):
    """Retrieve Galaxy tool-data information from defaults or galaxy config file.
    """
    ini_file = os.path.join(galaxy_base, 'universe_wsgi.ini')
    info = {'tool_data_table_config_path': os.path.join(galaxy_base, 'tool_data_table_conf.xml'), 'tool_data_path': os.path.join(galaxy_base, 'tool-data')}
    config = configparser.ConfigParser()
    config.read(ini_file)
    if 'app:main' in config.sections():
        for option in config.options('app:main'):
            if option in info:
                info[option] = os.path.join(galaxy_base, config.get('app:main', option))
    return info

def _get_galaxy_data_table(name, dt_config_file):
    """Parse data table config file for details on tool *.loc location and columns.
    """
    out = {}
    if os.path.exists(dt_config_file):
        tdtc = ElementTree.parse(dt_config_file)
        for t in tdtc.getiterator('table'):
            if t.attrib.get('name', '') in [name, '%s_indexes' % name]:
                out['column'] = [x.strip() for x in t.find('columns').text.split(',')]
                out['file'] = t.find('file').attrib.get('path', '')
    return out

def spv_freq_filter(line, tumor_index):
    """Filter VarScan calls based on the SPV value and frequency.

    Removes calls with SPV < 0.05 and a tumor FREQ > 0.35.

    False positives dominate these higher frequency, low SPV calls. They appear
    to be primarily non-somatic/germline variants not removed by other filters."""
    if line.startswith('#CHROM'):
        headers = ['##FILTER=<ID=SpvFreq,Description="High frequency (tumor FREQ > 0.35) and low p-value for somatic (SPV < 0.05)">']
        return '\n'.join(headers) + '\n' + line
    elif line.startswith('#'):
        return line
    else:
        parts = line.split('\t')
        sample_ft = {a: v for a, v in zip(parts[8].split(':'), parts[9 + tumor_index].split(':'))}
        freq = utils.safe_to_float(sample_ft.get('FREQ'))
        spvs = [x for x in parts[7].split(';') if x.startswith('SPV=')]
        spv = utils.safe_to_float(spvs[0].split('=')[-1] if spvs else None)
        fname = None
        if spv is not None and freq is not None:
            if spv < 0.05 and freq > 0.35:
                fname = 'SpvFreq'
        if fname:
            if parts[6] in set(['.', 'PASS']):
                parts[6] = fname
            else:
                parts[6] += ';%s' % fname
        line = '\t'.join(parts)
        return line

def _create_sample_list(in_bams, vcf_file):
    """Pull sample names from input BAMs and create input sample list.
    """
    out_file = '%s-sample_list.txt' % os.path.splitext(vcf_file)[0]
    with open(out_file, 'w') as out_handle:
        for in_bam in in_bams:
            with pysam.Samfile(in_bam, 'rb') as work_bam:
                for rg in work_bam.header.get('RG', []):
                    out_handle.write('%s\n' % rg['SM'])
    return out_file

def apply(object, args=None, kwargs=None):
    """Python3 apply replacement for double unpacking of inputs during apply.

    Thanks to: https://github.com/stefanholek/apply"""
    if args is None:
        args = ()
    if kwargs is None:
        kwargs = {}
    return object(*args, **kwargs)

def add_genes(in_file, data, max_distance=10000, work_dir=None):
    """Add gene annotations to a BED file from pre-prepared RNA-seq data.

    max_distance -- only keep annotations within this distance of event"""
    gene_file = regions.get_sv_bed(data, 'exons', out_dir=os.path.dirname(in_file))
    if gene_file and utils.file_exists(in_file):
        out_file = '%s-annotated.bed' % utils.splitext_plus(in_file)[0]
        if work_dir:
            out_file = os.path.join(work_dir, os.path.basename(out_file))
        if not utils.file_uptodate(out_file, in_file):
            fai_file = ref.fasta_idx(dd.get_ref_file(data))
            with file_transaction(data, out_file) as tx_out_file:
                _add_genes_to_bed(in_file, gene_file, fai_file, tx_out_file, data, max_distance)
        return out_file
    else:
        return in_file

def gene_one_per_line(in_file, data):
    """Split comma-separated gene annotations (after add_genes). Leads to duplicated records.
    Input:
       chr1 100 200 F1,F2
    Output:
       chr1 100 200 F1
       chr1 100 200 F2"""
    if in_file:
        one_per_line_file = '%s-opl.bed' % utils.splitext_plus(in_file)[0]
        if not utils.file_uptodate(one_per_line_file, in_file):
            with file_transaction(data, one_per_line_file) as tx_out_file:
                with open(tx_out_file, 'w') as out:
                    for r in pybedtools.BedTool(in_file):
                        for g in r.name.split(','):
                            out.write('\t'.join(map(str, [r.chrom, r.start, r.end, g])) + '\n')
        return one_per_line_file

def create(parallel):
    """Create a queue based on the provided parallel arguments.

    TODO Startup/tear-down. Currently using default queue for testing"""
    queue = {k: v for k, v in parallel.items() if k in ['queue', 'cores_per_job', 'mem']}
    yield queue

def runner(queue, parallel):
    """Run individual jobs on an existing queue.
    """
    def run(fn_name, items):
        logger.info('clusterk: %s' % fn_name)
        assert 'wrapper' in parallel, 'Clusterk requires bcbio-nextgen-vm wrapper'
        fn = getattr(__import__('{base}.clusterktasks'.format(base=parallel['module']), fromlist=['clusterktasks']), parallel['wrapper'])
        wrap_parallel = {k: v for k, v in parallel.items() if k in set(['fresources', 'pack'])}
        out = []
        for data in [fn(fn_name, queue, parallel.get('wrapper_args'), wrap_parallel, x) for x in items]:
            if data:
                out.extend(data)
        return out
    return run

def is_gene_list(bed_file):
    """Check if the file is only a list of genes, not a BED
    """
    with utils.open_gzipsafe(bed_file) as in_handle:
        for line in in_handle:
            if not line.startswith('#'):
                if len(line.split()) == 1:
                    return True
                else:
                    return False

def _find_gene_list_from_bed(bed_file, base_file, data):
    """Retrieve list of gene names from input BED file.
    """
    if is_gene_list(bed_file):
        return bed_file
    out_file = '%s-genes.txt' % utils.splitext_plus(base_file)[0]
    if not os.path.exists(out_file):
        genes = set([])
        import pybedtools
        with utils.open_gzipsafe(bed_file) as in_handle:
            for r in pybedtools.BedTool(in_handle):
                if r.name:
                    if not r.name.startswith('{'):
                        genes.add(r.name)
        with file_transaction(data, out_file) as tx_out_file:
            with open(tx_out_file, 'w') as out_handle:
                if len(genes) > 0:
                    out_handle.write('\n'.join(sorted(list(genes))) + '\n')
    if utils.file_exists(out_file):
        return out_file

def _get_gatk_opts(config, names, tmp_dir=None, memscale=None, include_gatk=True, parallel_gc=False):
    """Retrieve GATK memory specifications, moving down a list of potential specifications.
    """
    if include_gatk and 'gatk4' in dd.get_tools_off({'config': config}):
        opts = ['-U', 'LENIENT_VCF_PROCESSING', '--read_filter', 'BadCigar', '--read_filter', 'NotPrimaryAlignment']
    else:
        opts = []
    jvm_opts = ['-Xms750m', '-Xmx2g']
    for n in names:
        resources = config_utils.get_resources(n, config)
        if resources and resources.get('jvm_opts'):
            jvm_opts = resources.get('jvm_opts')
            break
    if memscale:
        jvm_opts = config_utils.adjust_opts(jvm_opts, {'algorithm': {'memory_adjust': memscale}})
    jvm_opts += get_default_jvm_opts(tmp_dir, parallel_gc=parallel_gc)
    return jvm_opts + opts

def _clean_java_out(version_str):
    """Remove extra environmental information reported in java when querying for versions.

    Java will report information like _JAVA_OPTIONS environmental variables in the output."""
    out = []
    for line in version_str.decode().split('\n'):
        if line.startswith('Picked up'):
            pass
        if line.find('setlocale') > 0:
            pass
        else:
            out.append(line)
    return '\n'.join(out)

def get_mutect_version(mutect_jar):
    """Retrieves version from input jar name since there is not an easy way to get MuTect version.
    Check mutect jar for SomaticIndelDetector, which is an Appistry feature"""
    cl = ['java', '-Xms128m', '-Xmx256m'] + get_default_jvm_opts() + ['-jar', mutect_jar, '-h']
    with closing(subprocess.Popen(cl, stdout=subprocess.PIPE, stderr=subprocess.STDOUT).stdout) as stdout:
        if 'SomaticIndelDetector' in stdout.read().strip():
            mutect_type = '-appistry'
        else:
            mutect_type = ''
    version = os.path.basename(mutect_jar).lower()
    for to_remove in ['.jar', '-standalone', 'mutect']:
        version = version.replace(to_remove, '')
    if version.startswith(('-', '.')):
        version = version[1:]
    if not version:
        raise ValueError('Unable to determine MuTect version from jar file. Need to have version contained in jar (ie. muTect-1.1.5.jar): %s' % mutect_jar)
    _check_for_bad_version(version, 'MuTect')
    return version + mutect_type

def fix_missing_spark_user(cl, prog, params):
    """Adjust /etc/passwd and GATK parameters if current username missing.

    Set Spark user to avoid lookup errors on environments like Docker where
    we run as a user id that is not present in /etc/passwd

    https://stackoverflow.com/questions/45198252/apache-spark-standalone-for-anonymous-uid-without-user-name/45361221#45361221
    https://github.com/jaceklaskowski/mastering-apache-spark-book/blob/master/spark-sparkcontext-creating-instance-internals.adoc#-utilsgetcurrentusername
    https://blog.openshift.com/jupyter-on-openshift-part-6-running-as-an-assigned-user-id/"""
    if prog.find('Spark') >= 0 or '--spark-master' in params:
        user = None
        try:
            user = getpass.getuser()
        except KeyError:
            if os.access('/etc/passwd', os.W_OK):
                with open('/etc/passwd', 'a') as out_handle:
                    out_handle.write('sparkanon:x:{uid}:{uid}:sparkanon:/nonexistent:/usr/sbin/nologin\n'.format(uid=os.getuid()))
                try:
                    user = getpass.getuser()
                except KeyError:
                    pass
        if user:
            cl = 'export SPARK_USER=%s && ' % user + cl
    return cl

def gatk_cmd(name, jvm_opts, params, config=None):
    """Retrieve PATH to gatk using locally installed java.
    """
    if name == 'gatk':
        if isinstance(config, dict) and 'config' not in config:
            data = {'config': config}
        else:
            data = config
        if not data or 'gatk4' not in dd.get_tools_off(data):
            return _gatk4_cmd(jvm_opts, params, data)
        else:
            name = 'gatk3'
    gatk_cmd = utils.which(os.path.join(os.path.dirname(os.path.realpath(sys.executable)), name))
    if not gatk_cmd:
        gatk_cmd = utils.which(name)
    if gatk_cmd:
        return '%s && export PATH=%s:"$PATH" && %s %s %s' % (utils.clear_java_home(), utils.get_java_binpath(gatk_cmd), gatk_cmd, ' '.join(jvm_opts), ' '.join([str(x) for x in params]))

def _gatk4_cmd(jvm_opts, params, data):
    """Retrieve unified command for GATK4, using 'gatk'. GATK3 is 'gatk3'.
    """
    gatk_cmd = utils.which(os.path.join(os.path.dirname(os.path.realpath(sys.executable)), 'gatk'))
    return '%s && export PATH=%s:"$PATH" && gatk --java-options \'%s\' %s' % (utils.clear_java_home(), utils.get_java_binpath(gatk_cmd), ' '.join(jvm_opts), ' '.join([str(x) for x in params]))

def runner_from_path(cmd, config):
    """Simple command line runner that expects a bash cmd in the PATH.

    This makes Picard tools back compatible with new approach of a single
    jar + bash script."""
    if cmd.endswith('picard'):
        return PicardCmdRunner(cmd, config)
    else:
        raise ValueError('Do not support PATH running for %s' % cmd)

def cpmap(cores=1):
    """Configurable parallel map context manager.

    Returns appropriate map compatible function based on configuration:
    - Local single core (the default)
    - Multiple local cores"""
    if int(cores) == 1:
        yield itertools.imap
    else:
        if futures is None:
            raise ImportError('concurrent.futures not available')
        pool = futures.ProcessPoolExecutor(cores)
        yield pool.map
        pool.shutdown()

def map_wrap(f):
    """Wrap standard function to easily pass into 'map' processing.
    """
    @functools.wraps(f)
    def wrapper(*args, **kwargs):
        return f(*args, **kwargs)
    return wrapper

def to_single_data(input):
    """Convert an input to a single bcbio data/world object.

    Handles both single sample cases (CWL) and all sample cases (standard bcbio)."""
    if isinstance(input, (list, tuple)) and len(input) == 1:
        return input[0]
    else:
        assert isinstance(input, dict), input
        return input

def unpack_worlds(items):
    """Handle all the ways we can pass multiple samples for back-compatibility.
    """
    if isinstance(items[0], (list, tuple)) and len(items[0]) == 1:
        out = []
        for d in items:
            assert len(d) == 1 and isinstance(d[0], dict), len(d)
            out.append(d[0])
    elif isinstance(items, (list, tuple)) and len(items) == 1 and isinstance(items[0], (list, tuple)):
        out = items[0]
    else:
        out = items
    return out

def safe_makedir(dname):
    """Make a directory if it doesn't exist, handling concurrent race conditions.
    """
    if not dname:
        return dname
    num_tries = 0
    max_tries = 5
    while not os.path.exists(dname):
        try:
            os.makedirs(dname)
        except OSError:
            if num_tries > max_tries:
                raise
            num_tries += 1
            time.sleep(2)
    return dname

def chdir(new_dir):
    """Context manager to temporarily change to a new directory.

    http://lucentbeing.com/blog/context-managers-and-the-with-statement-in-python/"""
    num_tries = 0
    max_tries = 5
    cur_dir = None
    while cur_dir is None:
        try:
            cur_dir = os.getcwd()
        except OSError:
            if num_tries > max_tries:
                raise
            num_tries += 1
            time.sleep(2)
    safe_makedir(new_dir)
    os.chdir(new_dir)
    try:
        yield
    finally:
        os.chdir(cur_dir)

def tmpfile(*args, **kwargs):
    """Make a tempfile, safely cleaning up file descriptors on completion.
    """
    fd, fname = tempfile.mkstemp(*args, **kwargs)
    try:
        yield fname
    finally:
        os.close(fd)
        if os.path.exists(fname):
            os.remove(fname)

def file_exists(fname):
    """Check if a file exists and is non-empty.
    """
    try:
        return fname and os.path.exists(fname) and (os.path.getsize(fname) > 0)
    except OSError:
        return False

def get_size(path):
    """Returns the size in bytes if `path` is a file,
    or the size of all files in `path` if it's a directory.
    Analogous to `du -s`."""
    if os.path.isfile(path):
        return os.path.getsize(path)
    return sum((get_size(os.path.join(path, f)) for f in os.listdir(path)))

def file_uptodate(fname, cmp_fname):
    """Check if a file exists, is non-empty and is more recent than cmp_fname.
    """
    try:
        return file_exists(fname) and file_exists(cmp_fname) and (os.path.getmtime(fname) >= os.path.getmtime(cmp_fname))
    except OSError:
        return False

def save_diskspace(fname, reason, config):
    """Overwrite a file in place with a short message to save disk.

    This keeps files as a sanity check on processes working, but saves
    disk by replacing them with a short message."""
    if config['algorithm'].get('save_diskspace', False):
        for ext in ['', '.bai']:
            if os.path.exists(fname + ext):
                with open(fname + ext, 'w') as out_handle:
                    out_handle.write('File removed to save disk space: %s' % reason)

def read_galaxy_amqp_config(galaxy_config, base_dir):
    """Read connection information on the RabbitMQ server from Galaxy config.
    """
    galaxy_config = add_full_path(galaxy_config, base_dir)
    config = six.moves.configparser.ConfigParser()
    config.read(galaxy_config)
    amqp_config = {}
    for option in config.options('galaxy_amqp'):
        amqp_config[option] = config.get('galaxy_amqp', option)
    return amqp_config

def splitext_plus(f):
    """Split on file extensions, allowing for zipped extensions.
    """
    base, ext = os.path.splitext(f)
    if ext in ['.gz', '.bz2', '.zip']:
        base, ext2 = os.path.splitext(base)
        ext = ext2 + ext
    return (base, ext)

def move_safe(origin, target):
    """Move file, skip if exists"""
    if origin == target:
        return origin
    if file_exists(target):
        return target
    shutil.move(origin, target)
    return target

def file_plus_index(fname):
    """Convert a file name into the file plus required indexes.
    """
    exts = {'.vcf': '.idx', '.bam': '.bai', '.vcf.gz': '.tbi', '.bed.gz': '.tbi', '.fq.gz': '.gbi'}
    ext = splitext_plus(fname)[-1]
    if ext in exts:
        return [fname, fname + exts[ext]]
    else:
        return [fname]

def remove_plus(orig):
    """Remove a fils, including biological index files.
    """
    for ext in ['', '.idx', '.gbi', '.tbi', '.bai']:
        if os.path.exists(orig + ext):
            remove_safe(orig + ext)

def copy_plus(orig, new):
    """Copy a fils, including biological index files.
    """
    for ext in ['', '.idx', '.gbi', '.tbi', '.bai']:
        if os.path.exists(orig + ext) and (not os.path.lexists(new + ext) or not os.path.exists(new + ext)):
            shutil.copyfile(orig + ext, new + ext)

def symlink_plus(orig, new):
    """Create relative symlinks and handle associated biological index files.
    """
    orig = os.path.abspath(orig)
    if not os.path.exists(orig):
        raise RuntimeError('File not found: %s' % orig)
    for ext in ['', '.idx', '.gbi', '.tbi', '.bai', '.fai']:
        if os.path.exists(orig + ext) and (not os.path.lexists(new + ext) or not os.path.exists(new + ext)):
            with chdir(os.path.dirname(new)):
                remove_safe(new + ext)
                try:
                    os.symlink(os.path.relpath(orig + ext), os.path.basename(new + ext))
                except OSError:
                    if not os.path.exists(new + ext) or not os.path.lexists(new + ext):
                        remove_safe(new + ext)
                        shutil.copyfile(orig + ext, new + ext)
    orig_noext = splitext_plus(orig)[0]
    new_noext = splitext_plus(new)[0]
    for sub_ext in ['.bai', '.dict']:
        if os.path.exists(orig_noext + sub_ext) and (not os.path.lexists(new_noext + sub_ext)):
            with chdir(os.path.dirname(new_noext)):
                os.symlink(os.path.relpath(orig_noext + sub_ext), os.path.basename(new_noext + sub_ext))

def append_stem(to_transform, word):
    '''renames a filename or list of filenames with 'word' appended to the stem
    of each one:
    example: append_stem("/path/to/test.sam", "_filtered") ->
    "/path/to/test_filtered.sam"'''
    if is_sequence(to_transform):
        return [append_stem(f, word) for f in to_transform]
    elif is_string(to_transform):
        base, ext = splitext_plus(to_transform)
        return ''.join([base, word, ext])
    else:
        raise ValueError('append_stem takes a single filename as a string or a list of filenames to transform.')

def replace_suffix(to_transform, suffix):
    '''replaces the suffix on a filename or list of filenames
    example: replace_suffix("/path/to/test.sam", ".bam") ->
    "/path/to/test.bam"'''
    if is_sequence(to_transform):
        transformed = []
        for f in to_transform:
            base, _ = os.path.splitext(f)
            transformed.append(base + suffix)
        return transformed
    elif is_string(to_transform):
        base, _ = os.path.splitext(to_transform)
        return base + suffix
    else:
        raise ValueError('replace_suffix takes a single filename as a string or a list of filenames to transform.')

def partition_all(n, iterable):
    """Partition a list into equally sized pieces, including last smaller parts
    http://stackoverflow.com/questions/5129102/python-equivalent-to-clojures-partition-all"""
    it = iter(iterable)
    while True:
        chunk = list(itertools.islice(it, n))
        if not chunk:
            break
        yield chunk

def partition(pred, iterable, tolist=False):
    """Use a predicate to partition entries into false entries and true entries"""
    t1, t2 = itertools.tee(iterable)
    ifalse = six.moves.filterfalse(pred, t1)
    itrue = six.moves.filter(pred, t2)
    if tolist:
        return (list(ifalse), list(itrue))
    else:
        return (ifalse, itrue)

def merge_config_files(fnames):
    """Merge configuration files, preferring definitions in latter files.
    """
    def _load_yaml(fname):
        with open(fname) as in_handle:
            config = yaml.safe_load(in_handle)
        return config
    out = _load_yaml(fnames[0])
    for fname in fnames[1:]:
        cur = _load_yaml(fname)
        for k, v in cur.items():
            if k in out and isinstance(out[k], dict):
                out[k].update(v)
            else:
                out[k] = v
    return out

def deepish_copy(org):
    """Improved speed deep copy for dictionaries of simple python types.

    Thanks to Gregg Lind:
    http://writeonly.wordpress.com/2009/05/07/deepcopy-is-a-pig-for-simple-data/"""
    out = dict().fromkeys(org)
    for k, v in org.items():
        if isinstance(v, dict):
            out[k] = deepish_copy(v)
        else:
            try:
                out[k] = v.copy()
            except AttributeError:
                try:
                    out[k] = v[:]
                except TypeError:
                    out[k] = v
    return out

def replace_directory(out_files, dest_dir):
    """change the output directory to dest_dir
    can take a string (single file) or a list of files"""
    if is_sequence(out_files):
        filenames = map(os.path.basename, out_files)
        return [os.path.join(dest_dir, x) for x in filenames]
    elif is_string(out_files):
        return os.path.join(dest_dir, os.path.basename(out_files))
    else:
        raise ValueError('in_files must either be a sequence of filenames or a string')

def reservoir_sample(stream, num_items, item_parser=lambda x: x):
    """samples num_items from the stream keeping each with equal probability"""
    kept = []
    for index, item in enumerate(stream):
        if index < num_items:
            kept.append(item_parser(item))
        else:
            r = random.randint(0, index)
            if r < num_items:
                kept[r] = item_parser(item)
    return kept

def dictapply(d, fn):
    """apply a function to all non-dict values in a dictionary"""
    for k, v in d.items():
        if isinstance(v, dict):
            v = dictapply(v, fn)
        else:
            d[k] = fn(v)
    return d

def Rscript_cmd():
    """Retrieve path to locally installed Rscript or first in PATH.

    Prefers Rscript version installed via conda to a system version."""
    rscript = which(os.path.join(get_bcbio_bin(), 'Rscript'))
    if rscript:
        return rscript
    else:
        return which('Rscript')

def R_package_path(package):
    """return the path to an installed R package"""
    local_sitelib = R_sitelib()
    rscript = Rscript_cmd()
    cmd = '{rscript} --no-environ -e \'.libPaths(c("{local_sitelib}")); find.package("{package}")\''
    try:
        output = subprocess.check_output(cmd.format(**locals()), shell=True)
    except subprocess.CalledProcessError as e:
        return None
    for line in output.decode().split('\n'):
        if '[1]' not in line:
            continue
        dirname = line.split('[1]')[1].replace('"', '').strip()
        if os.path.exists(dirname):
            return dirname
    return None

def R_package_resource(package, resource):
    """return a path to an R package resource, if it is available"""
    package_path = R_package_path(package)
    if not package_path:
        return None
    package_resource = os.path.join(package_path, resource)
    if not file_exists(package_resource):
        return None
    else:
        return package_resource

def get_java_binpath(cmd=None):
    """Retrieve path for java to use, handling custom BCBIO_JAVA_HOME

    Defaults to the dirname of cmd, or local anaconda directory"""
    if os.environ.get('BCBIO_JAVA_HOME'):
        test_cmd = os.path.join(os.environ['BCBIO_JAVA_HOME'], 'bin', 'java')
        if os.path.exists(test_cmd):
            cmd = test_cmd
    if not cmd:
        cmd = Rscript_cmd()
    return os.path.dirname(cmd)

def clear_java_home():
    """Clear JAVA_HOME environment or reset to BCBIO_JAVA_HOME.

    Avoids accidental java injection but respects custom BCBIO_JAVA_HOME
    command."""
    if os.environ.get('BCBIO_JAVA_HOME'):
        test_cmd = os.path.join(os.environ['BCBIO_JAVA_HOME'], 'bin', 'java')
        if os.path.exists(test_cmd):
            return 'export JAVA_HOME=%s' % os.environ['BCBIO_JAVA_HOME']
    return 'unset JAVA_HOME'

def perl_cmd():
    """Retrieve path to locally installed conda Perl or first in PATH.
    """
    perl = which(os.path.join(get_bcbio_bin(), 'perl'))
    if perl:
        return perl
    else:
        return which('perl')

def get_all_conda_bins():
    """Retrieve all possible conda bin directories, including environments.
    """
    bcbio_bin = get_bcbio_bin()
    conda_dir = os.path.dirname(bcbio_bin)
    if os.path.join('anaconda', 'envs') in conda_dir:
        conda_dir = os.path.join(conda_dir[:conda_dir.rfind(os.path.join('anaconda', 'envs'))], 'anaconda')
    return [bcbio_bin] + list(glob.glob(os.path.join(conda_dir, 'envs', '*', 'bin')))

def get_program_python(cmd):
    """Get the full path to a python version linked to the command.

    Allows finding python based programs in python 2 versus python 3
    environments."""
    full_cmd = os.path.realpath(which(cmd))
    cmd_python = os.path.join(os.path.dirname(full_cmd), 'python')
    env_python = None
    if 'envs' in cmd_python:
        parts = cmd_python.split(os.sep)
        env_python = os.path.join(os.sep.join(parts[:parts.index('envs') + 2]), 'bin', 'python')
    if os.path.exists(cmd_python):
        return cmd_python
    elif env_python and os.path.exists(env_python):
        return env_python
    else:
        return os.path.realpath(sys.executable)

def local_path_export(at_start=True, env_cmd=None):
    """Retrieve paths to local install, also including environment paths if env_cmd included.
    """
    paths = [get_bcbio_bin()]
    if env_cmd:
        env_path = os.path.dirname(get_program_python(env_cmd))
        if env_path not in paths:
            paths.insert(0, env_path)
    if at_start:
        return 'export PATH=%s:"$PATH" && ' % ':'.join(paths)
    else:
        return 'export PATH="$PATH":%s && ' % ':'.join(paths)

def locale_export():
    """Exports for dealing with Click-based programs and ASCII/Unicode errors.

    RuntimeError: Click will abort further execution because Python 3 was
    configured to use ASCII as encoding for the environment.
    Consult https://click.palletsprojects.com/en/7.x/python3/ for mitigation steps.

    Looks up available locales on the system to find an appropriate one to pick,
    defaulting to C.UTF-8 which is globally available on newer systems."""
    locale_to_use = 'C.UTF-8'
    try:
        locales = subprocess.check_output(['locale', '-a']).decode(errors='ignore').split('\n')
    except subprocess.CalledProcessError:
        locales = []
    for locale in locales:
        if locale.lower().endswith(('utf-8', 'utf8')):
            locale_to_use = locale
            break
    return 'export LC_ALL=%s && export LANG=%s && ' % (locale_to_use, locale_to_use)

def rbind(dfs):
    """acts like rbind for pandas dataframes"""
    if len(dfs) == 1:
        return dfs[0]
    df = dfs[0]
    for d in dfs[1:]:
        df = df.append(d)
    return df

def walk_json(d, func):
    """Walk over a parsed JSON nested structure `d`, apply `func` to each leaf element and replace it with result
    """
    if isinstance(d, Mapping):
        return OrderedDict(((k, walk_json(v, func)) for k, v in d.items()))
    elif isinstance(d, list):
        return [walk_json(v, func) for v in d]
    else:
        return func(d)

def trim_sample(data):
    """Trim from a sample with the provided trimming method.
    Support methods: read_through."""
    data = utils.to_single_data(data)
    trim_reads = dd.get_trim_reads(data)
    if not trim_reads:
        logger.info('Skipping trimming of %s.' % dd.get_sample_name(data))
    else:
        if 'skewer' in dd.get_tools_on(data) or trim_reads == 'skewer':
            trim_adapters = skewer.trim_adapters
        else:
            trim_adapters = trim.trim_adapters
        out_files = trim_adapters(data)
        data['files'] = out_files
    return [[data]]

def _link_bam_file(in_file, new_dir, data):
    """Provide symlinks of BAM file and existing indexes if needed.
    """
    new_dir = utils.safe_makedir(new_dir)
    out_file = os.path.join(new_dir, os.path.basename(in_file))
    if not utils.file_exists(out_file):
        out_file = os.path.join(new_dir, '%s-prealign.bam' % dd.get_sample_name(data))
    if data.get('cwl_keys'):
        if utils.file_exists(in_file + '.bai'):
            out_file = in_file
        else:
            utils.copy_plus(in_file, out_file)
    else:
        utils.symlink_plus(in_file, out_file)
    return out_file

def _add_supplemental_bams(data):
    """Add supplemental files produced by alignment, useful for structural
    variant calling."""
    file_key = 'work_bam'
    if data.get(file_key):
        for supext in ['disc', 'sr']:
            base, ext = os.path.splitext(data[file_key])
            test_file = '%s-%s%s' % (base, supext, ext)
            if os.path.exists(test_file):
                sup_key = file_key + '_plus'
                if sup_key not in data:
                    data[sup_key] = {}
                data[sup_key][supext] = test_file
    return data

def _add_hla_files(data):
    """Add extracted fastq files of HLA alleles for typing.
    """
    if 'hla' not in data:
        data['hla'] = {}
    align_file = dd.get_align_bam(data)
    hla_dir = os.path.join(os.path.dirname(align_file), 'hla')
    if not os.path.exists(hla_dir):
        hla_files = None
    else:
        hla_files = sorted(list(glob.glob(os.path.join(hla_dir, '%s.*.fq' % os.path.basename(align_file)))))
    data['hla']['fastq'] = hla_files
    return data

def _merge_out_from_infiles(in_files):
    """Generate output merged file name from set of input files.

    Handles non-shared filesystems where we don't know output path when setting
    up split parts."""
    fname = os.path.commonprefix([os.path.basename(f) for f in in_files])
    while fname.endswith(('-', '_', '.')):
        fname = fname[:-1]
    ext = os.path.splitext(in_files[0])[-1]
    dirname = os.path.dirname(in_files[0])
    while dirname.endswith(('split', 'merge')):
        dirname = os.path.dirname(dirname)
    return os.path.join(dirname, '%s%s' % (fname, ext))

def _merge_align_bams(data):
    """Merge multiple alignment BAMs, including split and discordant reads.
    """
    for key in (['work_bam'], ['work_bam_plus', 'disc'], ['work_bam_plus', 'sr'], ['umi_bam']):
        in_files = tz.get_in(key, data, [])
        if not isinstance(in_files, (list, tuple)):
            in_files = [in_files]
        in_files = [x for x in in_files if x and x != 'None']
        if in_files:
            ext = '-%s' % key[-1] if len(key) > 1 else ''
            out_file = os.path.join(dd.get_work_dir(data), 'align', dd.get_sample_name(data), '%s-sort%s.bam' % (dd.get_sample_name(data), ext))
            merged_file = merge_bam_files(in_files, utils.safe_makedir(os.path.dirname(out_file)), data, out_file=out_file)
            data = tz.update_in(data, key, lambda x: merged_file)
        else:
            data = tz.update_in(data, key, lambda x: None)
    if 'align_bam' in data and 'work_bam' in data:
        data['align_bam'] = data['work_bam']
    return data

def prepare_bcbio_samples(sample):
    """Function that will use specific function to merge input files"""
    logger.info('Preparing %s files %s to merge into %s.' % (sample['name'], sample['files'], sample['out_file']))
    if sample['fn'] == 'fq_merge':
        out_file = fq_merge(sample['files'], sample['out_file'], sample['config'])
    elif sample['fn'] == 'bam_merge':
        out_file = bam_merge(sample['files'], sample['out_file'], sample['config'])
    elif sample['fn'] == 'query_gsm':
        out_file = query_gsm(sample['files'], sample['out_file'], sample['config'])
    elif sample['fn'] == 'query_srr':
        out_file = query_srr(sample['files'], sample['out_file'], sample['config'])
    sample['out_file'] = out_file
    return [sample]

def _get_calls(data, cnv_only=False):
    """Retrieve calls, organized by name, to use for heterogeneity analysis.
    """
    cnvs_supported = set(['cnvkit', 'battenberg'])
    out = {}
    for sv in data.get('sv', []):
        if not cnv_only or sv['variantcaller'] in cnvs_supported:
            out[sv['variantcaller']] = sv
    return out

def get_variants(data, include_germline=False):
    """Retrieve set of variant calls to use for heterogeneity analysis.
    """
    data = utils.deepish_copy(data)
    supported = ['precalled', 'vardict', 'vardict-java', 'vardict-perl', 'freebayes', 'octopus', 'strelka2']
    if include_germline:
        supported.insert(1, 'gatk-haplotype')
    out = []
    if isinstance(data.get('variants'), dict) and 'samples' in data['variants']:
        cur_vs = []
        if isinstance(data['variants']['samples'], (list, tuple)) and len(data['variants']['samples']) == 1 and isinstance(data['variants']['samples'][0], (list, tuple)):
            data['variants']['samples'] = data['variants']['samples'][0]
        for fname in data['variants']['samples']:
            variantcaller = utils.splitext_plus(os.path.basename(fname))[0]
            variantcaller = variantcaller.replace(dd.get_sample_name(data) + '-', '')
            for batch in dd.get_batches(data):
                variantcaller = variantcaller.replace(batch + '-', '')
            cur_vs.append({'vrn_file': fname, 'variantcaller': variantcaller})
        data['variants'] = cur_vs
    for v in data.get('variants', []):
        if v['variantcaller'] in supported and v.get('vrn_file'):
            out.append((supported.index(v['variantcaller']), v))
    out.sort()
    return [xs[1] for xs in out]

def _ready_for_het_analysis(items):
    """Check if a sample has input information for heterogeneity analysis.

    We currently require a tumor/normal sample containing both CNV and variant calls."""
    paired = vcfutils.get_paired_bams([dd.get_align_bam(d) for d in items], items)
    has_het = any((dd.get_hetcaller(d) for d in items))
    if has_het and paired:
        return get_variants(paired.tumor_data) and _get_calls(paired.tumor_data, cnv_only=True)

def estimate(items, batch, config):
    """Estimate heterogeneity for a pair of tumor/normal samples. Run in parallel.
    """
    hetcallers = {'theta': theta.run, 'phylowgs': phylowgs.run, 'bubbletree': bubbletree.run}
    paired = vcfutils.get_paired_bams([dd.get_align_bam(d) for d in items], items)
    calls = _get_calls(paired.tumor_data)
    variants = get_variants(paired.tumor_data)
    het_info = []
    for hetcaller in _get_hetcallers(items):
        try:
            hetfn = hetcallers[hetcaller]
        except KeyError:
            hetfn = None
            print('%s not yet implemented' % hetcaller)
        if hetfn:
            hetout = hetfn(variants[0], calls, paired)
            if hetout:
                het_info.append(hetout)
    out = []
    for data in items:
        if batch == _get_batches(data)[0]:
            if dd.get_sample_name(data) == paired.tumor_name:
                if het_info:
                    data['heterogeneity'] = het_info
            out.append([data])
    return out

def run(items, run_parallel):
    """Top level entry point for calculating heterogeneity, handles organization and job distribution.
    """
    to_process = []
    extras = []
    for batch, cur_items in _group_by_batches(items).items():
        if _ready_for_het_analysis(cur_items):
            to_process.append((batch, cur_items))
        else:
            for data in cur_items:
                extras.append([data])
    processed = run_parallel('heterogeneity_estimate', ([xs, b, xs[0]['config']] for b, xs in to_process))
    return _group_by_sample_and_batch(extras + processed)

def _set_align_split_size(data):
    """Set useful align_split_size, generating an estimate if it doesn't exist.

    We try to split on larger inputs and avoid too many pieces, aiming for size
    chunks of 5Gb or at most 50 maximum splits.

    The size estimate used in calculations is 20 million reads for ~5Gb.

    For UMI calculations we skip splitting since we're going to align and
    re-align after consensus.

    For CWL runs, we pick larger split sizes to avoid overhead of staging each chunk."""
    if cwlutils.is_cwl_run(data):
        target_size = 20
        target_size_reads = 80
    else:
        target_size = 5
        target_size_reads = 20
    max_splits = 100
    val = dd.get_align_split_size(data)
    umi_consensus = dd.get_umi_consensus(data)
    if val is None:
        if not umi_consensus:
            total_size = 0
            input_files = data.get('files_orig', []) if dd.get_save_diskspace(data) else data.get('files', [])
            for fname in input_files:
                if os.path.exists(fname):
                    total_size += os.path.getsize(fname) / (1024.0 * 1024.0 * 1024.0)
            if total_size > target_size:
                data['config']['algorithm']['align_split_size'] = int(1000000.0 * _pick_align_split_size(total_size, target_size, target_size_reads, max_splits))
    elif val:
        assert not umi_consensus, 'Cannot set align_split_size to %s with UMI conensus specified' % val
    return data

def _pick_align_split_size(total_size, target_size, target_size_reads, max_splits):
    """Do the work of picking an alignment split size for the given criteria.
    """
    if total_size // target_size > max_splits:
        piece_size = total_size // max_splits
        return int(piece_size * target_size_reads / target_size)
    else:
        return int(target_size_reads)

def split_namedpipe_cls(pair1_file, pair2_file, data):
    """Create a commandline suitable for use as a named pipe with reads in a given region.
    """
    if 'align_split' in data:
        start, end = [int(x) for x in data['align_split'].split('-')]
    else:
        start, end = (None, None)
    if pair1_file.endswith('.sdf'):
        assert not pair2_file, pair2_file
        return rtg.to_fastq_apipe_cl(pair1_file, start, end)
    else:
        out = []
        for in_file in (pair1_file, pair2_file):
            if in_file:
                assert _get_grabix_index(in_file), 'Need grabix index for %s' % in_file
                out.append('<(grabix grab {in_file} {start} {end})'.format(**locals()))
            else:
                out.append(None)
        return out

def _seqtk_fastq_prep_cl(data, in_file=None, read_num=0):
    """Provide a commandline for prep of fastq inputs with seqtk.

    Handles fast conversion of fastq quality scores and trimming."""
    needs_convert = dd.get_quality_format(data).lower() == 'illumina'
    trim_ends = dd.get_trim_ends(data)
    seqtk = config_utils.get_program('seqtk', data['config'])
    if in_file:
        in_file = objectstore.cl_input(in_file)
    else:
        in_file = '/dev/stdin'
    cmd = ''
    if needs_convert:
        cmd += '{seqtk} seq -Q64 -V {in_file}'.format(**locals())
    if trim_ends:
        left_trim, right_trim = trim_ends[0:2] if data.get('read_num', read_num) == 0 else trim_ends[2:4]
        if left_trim or right_trim:
            trim_infile = '/dev/stdin' if needs_convert else in_file
            pipe = ' | ' if needs_convert else ''
            cmd += '{pipe}{seqtk} trimfq -b {left_trim} -e {right_trim} {trim_infile}'.format(**locals())
    return cmd

def parallel_multiplier(items):
    """Determine if we will be parallelizing items during processing.
    """
    multiplier = 1
    for data in (x[0] for x in items):
        if tz.get_in(['config', 'algorithm', 'align_split_size'], data) is not False and tz.get_in(['algorithm', 'align_split_size'], data) is not False:
            multiplier += 50
    return multiplier

def setup_combine(final_file, data):
    """Setup the data and outputs to allow merging data back together.
    """
    if 'align_split' not in data:
        return (final_file, data)
    align_dir = os.path.dirname(final_file)
    base, ext = os.path.splitext(os.path.basename(final_file))
    start, end = [int(x) for x in data['align_split'].split('-')]
    out_file = os.path.join(utils.safe_makedir(os.path.join(align_dir, 'split')), '%s-%s_%s%s' % (base, start, end, ext))
    data['combine'] = {'work_bam': {'out': final_file, 'extras': []}}
    return (out_file, data)

def _save_fastq_space(items):
    """Potentially save fastq space prior to merging, since alignments done.
    """
    to_cleanup = {}
    for data in (utils.to_single_data(x) for x in items):
        for fname in data.get('files', []):
            if os.path.realpath(fname).startswith(dd.get_work_dir(data)):
                to_cleanup[fname] = data['config']
    for fname, config in to_cleanup.items():
        utils.save_diskspace(fname, 'Cleanup prep files after alignment finished', config)

def _ready_gzip_fastq(in_files, data, require_bgzip=False):
    """Check if we have gzipped fastq and don't need format conversion or splitting.

    Avoid forcing bgzip if we don't need indexed files."""
    all_gzipped = all([not x or x.endswith('.gz') for x in in_files])
    if require_bgzip and all_gzipped:
        all_gzipped = all([not x or not _check_gzipped_input(x, data)[0] for x in in_files])
    needs_convert = dd.get_quality_format(data).lower() == 'illumina'
    needs_trim = dd.get_trim_ends(data)
    do_splitting = dd.get_align_split_size(data) is not False
    return all_gzipped and (not needs_convert) and (not do_splitting) and (not objectstore.is_remote(in_files[0])) and (not needs_trim) and (not get_downsample_params(data))

def prep_fastq_inputs(in_files, data):
    """Prepare bgzipped fastq inputs
    """
    if len(in_files) == 1 and _is_bam_input(in_files):
        out = _bgzip_from_bam(in_files[0], data['dirs'], data)
    elif len(in_files) == 1 and _is_cram_input(in_files):
        out = _bgzip_from_cram(in_files[0], data['dirs'], data)
    elif len(in_files) in [1, 2] and _ready_gzip_fastq(in_files, data):
        out = _symlink_in_files(in_files, data)
    else:
        if len(in_files) > 2:
            fpairs = fastq.combine_pairs(in_files)
            pair_types = set([len(xs) for xs in fpairs])
            assert len(pair_types) == 1
            fpairs.sort(key=lambda x: os.path.basename(x[0]))
            organized = [[xs[0] for xs in fpairs]]
            if len(fpairs[0]) > 1:
                organized.append([xs[1] for xs in fpairs])
            in_files = organized
        parallel = {'type': 'local', 'num_jobs': len(in_files), 'cores_per_job': max(1, data['config']['algorithm']['num_cores'] // len(in_files))}
        inputs = [{'in_file': x, 'read_num': i, 'dirs': data['dirs'], 'config': data['config'], 'is_cwl': 'cwl_keys' in data, 'rgnames': data['rgnames']} for i, x in enumerate(in_files) if x]
        out = run_multicore(_bgzip_from_fastq_parallel, [[d] for d in inputs], data['config'], parallel)
    return out

def _symlink_or_copy_grabix(in_file, out_file, data):
    """We cannot symlink in CWL, but may be able to use inputs or copy
    """
    if cwlutils.is_cwl_run(data):
        if utils.file_exists(in_file + '.gbi'):
            out_file = in_file
        else:
            utils.copy_plus(in_file, out_file)
    else:
        utils.symlink_plus(in_file, out_file)
    return out_file

def _prep_grabix_indexes(in_files, data):
    """Parallel preparation of grabix indexes for files.
    """
    if _ready_gzip_fastq(in_files, data) and (not _ready_gzip_fastq(in_files, data, require_bgzip=True) or dd.get_align_split_size(data) is False):
        for in_file in in_files:
            if not utils.file_exists(in_file + '.gbi'):
                with file_transaction(data, in_file + '.gbi') as tx_gbi_file:
                    with open(tx_gbi_file, 'w') as out_handle:
                        out_handle.write('Not grabix indexed; index added for compatibility.\n')
    else:
        items = [[{'bgzip_file': x, 'config': copy.deepcopy(data['config'])}] for x in in_files if x]
        run_multicore(_grabix_index, items, data['config'])
    return data

def _cram_to_fastq_regions(regions, cram_file, dirs, data):
    """Convert CRAM files to fastq, potentially within sub regions.

    Returns multiple fastq files that can be merged back together."""
    base_name = utils.splitext_plus(os.path.basename(cram_file))[0]
    work_dir = utils.safe_makedir(os.path.join(dirs['work'], 'align_prep', '%s-parts' % base_name))
    fnames = run_multicore(_cram_to_fastq_region, [(cram_file, work_dir, base_name, region, data) for region in regions], data['config'])
    if any((not _is_gzip_empty(p1) for p1, p2, s in fnames)):
        out = [[p1, p2] for p1, p2, s in fnames]
    else:
        out = [[s] for p1, p2, s in fnames]
    return (out, work_dir)

def _is_partial_index(gbi_file):
    """Check for truncated output since grabix doesn't write to a transactional directory.
    """
    with open(gbi_file) as in_handle:
        for i, _ in enumerate(in_handle):
            if i > 2:
                return False
    return True

def _check_gzipped_input(in_file, data):
    """Determine if a gzipped input file is blocked gzip or standard.
    """
    grabix = config_utils.get_program('grabix', data['config'])
    is_bgzip = subprocess.check_output([grabix, 'check', in_file])
    if is_bgzip.strip() == 'yes':
        return (False, False)
    else:
        return (True, True)

def get_fc_date(out_config_file):
    """Retrieve flowcell date, reusing older dates if refreshing a present workflow.
    """
    if os.path.exists(out_config_file):
        with open(out_config_file) as in_handle:
            old_config = yaml.safe_load(in_handle)
            fc_date = old_config['fc_date']
    else:
        fc_date = datetime.datetime.now().strftime('%y%m%d')
    return fc_date

def _chunks(l, n):
    """Yield successive n-sized chunks from l.

    http://stackoverflow.com/questions/312443/how-do-you-split-a-list-into-evenly-sized-chunks-in-python"""
    for i in xrange(0, len(l), n):
        yield l[i:i + n]

def _counts_at_position(positions, orig_reader, cmp_reader):
    """Combine orignal and new qualities at each position, generating counts.
    """
    pos_counts = collections.defaultdict(lambda: collections.defaultdict(lambda: collections.defaultdict(int)))
    for orig_parts in orig_reader:
        cmp_parts = next(cmp_reader)
        for pos in positions:
            try:
                pos_counts[pos][int(orig_parts[pos + 1])][int(cmp_parts[pos + 1])] += 1
            except IndexError:
                pass
    for pos, count_dict in pos_counts.iteritems():
        for orig_val, cmp_dict in count_dict.iteritems():
            for cmp_val, count in cmp_dict.iteritems():
                yield (pos + 1, orig_val, cmp_val, count)

def group_by_batch(items, require_bam=True):
    """Group a set of sample items by batch (or singleton) name.

    Items in multiple batches cause two batches to be merged together."""
    out = collections.defaultdict(list)
    batch_groups = _get_representative_batch(_merge_batches(_find_all_groups(items, require_bam)))
    for data in items:
        batches = _get_batches(data, require_bam)
        batch = batch_groups[batches[0]]
        out[batch].append(utils.deepish_copy(data))
    return dict(out)

def bam_needs_processing(data):
    """Check if a work input needs processing for parallelization.
    """
    return (data.get('work_bam') or data.get('align_bam')) and (any((tz.get_in(['config', 'algorithm', x], data) for x in ['variantcaller', 'mark_duplicates', 'recalibrate', 'realign', 'svcaller', 'jointcaller', 'variant_regions'])) or any((k in data for k in ['cwl_keys', 'output_cwl_keys'])))

def get_batch_for_key(data):
    """Retrieve batch information useful as a unique key for the sample.
    """
    batches = _get_batches(data, require_bam=False)
    if len(batches) == 1:
        return batches[0]
    else:
        return tuple(batches)

def _merge_batches(all_groups):
    """Merge batches with overlapping groups. Uses merge approach from:

    http://stackoverflow.com/a/4842897/252589"""
    merged = []
    while len(all_groups) > 0:
        first, rest = (all_groups[0], all_groups[1:])
        first = set(first)
        lf = -1
        while len(first) > lf:
            lf = len(first)
            rest2 = []
            for r in rest:
                if len(first.intersection(set(r))) > 0:
                    first |= set(r)
                else:
                    rest2.append(r)
            rest = rest2
        merged.append(first)
        all_groups = rest
    return merged

def _get_representative_batch(merged):
    """Prepare dictionary matching batch items to a representative within a group.
    """
    out = {}
    for mgroup in merged:
        mgroup = sorted(list(mgroup))
        for x in mgroup:
            out[x] = mgroup[0]
    return out

def group_batches_joint(samples):
    """Perform grouping by batches for joint calling/squaring off.
    """
    def _caller_batches(data):
        jointcaller = tz.get_in(('config', 'algorithm', 'jointcaller'), data)
        batch = tz.get_in(('metadata', 'batch'), data) if jointcaller else None
        return (jointcaller, batch)
    def _prep_data(data, items):
        for r in ['callable_regions', 'variant_regions']:
            data[r] = list(set(filter(lambda x: x is not None, [tz.get_in(('config', 'algorithm', r), d) for d in items])))
        data['work_bams'] = [dd.get_align_bam(x) or dd.get_work_bam(x) for x in items]
        data['vrn_files'] = [x['vrn_file'] for x in items]
        return data
    return _group_batches_shared(samples, _caller_batches, _prep_data)

def _diff_dict(orig, new):
    """Diff a nested dictionary, returning only key/values that differ.
    """
    final = {}
    for k, v in new.items():
        if isinstance(v, dict):
            v = _diff_dict(orig.get(k, {}), v)
            if len(v) > 0:
                final[k] = v
        elif v != orig.get(k):
            final[k] = v
    for k, v in orig.items():
        if k not in new:
            final[k] = None
    return final

def _pick_lead_item(items):
    """Pick single representative sample for batch calling to attach calls to.

    For cancer samples, attach to tumor."""
    if vcfutils.is_paired_analysis([dd.get_align_bam(x) for x in items], items):
        for data in items:
            if vcfutils.get_paired_phenotype(data) == 'tumor':
                return data
        raise ValueError('Did not find tumor sample in paired tumor/normal calling')
    else:
        return items[0]

def _patch_dict(diff, base):
    """Patch a dictionary, substituting in changed items from the nested diff.
    """
    for k, v in diff.items():
        if isinstance(v, dict):
            base[k] = _patch_dict(v, base.get(k, {}))
        elif not v:
            base.pop(k, None)
        else:
            base[k] = v
    return base

def split_variants_by_sample(data):
    """Split a multi-sample call file into inputs for individual samples.

    For tumor/normal paired analyses, do not split the final file and attach
    it to the tumor input."""
    if 'group_orig' not in data:
        return [[data]]
    elif vcfutils.get_paired_phenotype(data) and 'tumor' in [vcfutils.get_paired_phenotype(d) for d in get_orig_items(data)]:
        out = []
        for i, sub_data in enumerate(get_orig_items(data)):
            if vcfutils.get_paired_phenotype(sub_data) == 'tumor':
                cur_batch = tz.get_in(['metadata', 'batch'], data)
                if cur_batch:
                    sub_data['metadata']['batch'] = cur_batch
                sub_data['vrn_file'] = data['vrn_file']
            else:
                sub_data.pop('vrn_file', None)
            out.append([sub_data])
        return out
    else:
        out = []
        for sub_data in get_orig_items(data):
            cur_batch = tz.get_in(['metadata', 'batch'], data)
            if cur_batch:
                sub_data['metadata']['batch'] = cur_batch
            sub_data['vrn_file_batch'] = data['vrn_file']
            sub_data['vrn_file'] = data['vrn_file']
            out.append([sub_data])
        return out

def _cnn_filter(in_file, vrn_files, data):
    """Perform CNN filtering on input VCF using pre-trained models.
    """
    tensor_type = 'read_tensor'
    score_file = _cnn_score_variants(in_file, tensor_type, data)
    return _cnn_tranch_filtering(score_file, vrn_files, tensor_type, data)

def _cnn_tranch_filtering(in_file, vrn_files, tensor_type, data):
    """Filter CNN scored VCFs in tranches using standard SNP and Indel truth sets.
    """
    out_file = '%s-filter.vcf.gz' % utils.splitext_plus(in_file)[0]
    if not utils.file_uptodate(out_file, in_file):
        runner = broad.runner_from_config(data['config'])
        gatk_type = runner.gatk_type()
        assert gatk_type == 'gatk4', 'CNN filtering requires GATK4'
        if 'train_hapmap' not in vrn_files:
            raise ValueError('CNN filtering requires HapMap training inputs: %s' % vrn_files)
        with file_transaction(data, out_file) as tx_out_file:
            params = ['-T', 'FilterVariantTranches', '--variant', in_file, '--output', tx_out_file, '--snp-truth-vcf', vrn_files['train_hapmap'], '--indel-truth-vcf', vrn_files['train_indels']]
            if tensor_type == 'reference':
                params += ['--info-key', 'CNN_1D', '--tranche', '99']
            else:
                assert tensor_type == 'read_tensor'
                params += ['--info-key', 'CNN_2D', '--tranche', '99']
            runner.run_gatk(params)
    return vcfutils.bgzip_and_index(out_file, data['config'])

def _get_training_data(vrn_files):
    """Retrieve training data, returning an empty set of information if not available.
    """
    out = {'SNP': [], 'INDEL': []}
    for name, train_info in [('train_hapmap', 'known=false,training=true,truth=true,prior=15.0'), ('train_omni', 'known=false,training=true,truth=true,prior=12.0'), ('train_1000g', 'known=false,training=true,truth=false,prior=10.0'), ('dbsnp', 'known=true,training=false,truth=false,prior=2.0')]:
        if name not in vrn_files:
            return {}
        else:
            out['SNP'].append((name.replace('train_', ''), train_info, vrn_files[name]))
    if 'train_indels' in vrn_files:
        out['INDEL'].append(('mills', 'known=true,training=true,truth=true,prior=12.0', vrn_files['train_indels']))
    else:
        return {}
    return out

def _get_vqsr_training(filter_type, vrn_files, gatk_type):
    """Return parameters for VQSR training, handling SNPs and Indels.
    """
    params = []
    for name, train_info, fname in _get_training_data(vrn_files)[filter_type]:
        if gatk_type == 'gatk4':
            params.extend(['--resource:%s,%s' % (name, train_info), fname])
            if filter_type == 'INDEL':
                params.extend(['--max-gaussians', '4'])
        else:
            params.extend(['-resource:%s,VCF,%s' % (name, train_info), fname])
            if filter_type == 'INDEL':
                params.extend(['--maxGaussians', '4'])
    return params

def _already_cutoff_filtered(in_file, filter_type):
    """Check if we have a pre-existing cutoff-based filter file from previous VQSR failure.
    """
    filter_file = '%s-filter%s.vcf.gz' % (utils.splitext_plus(in_file)[0], filter_type)
    return utils.file_exists(filter_file)

def _variant_filtration(in_file, ref_file, vrn_files, data, filter_type, hard_filter_fn):
    """Filter SNP and indel variant calls using GATK best practice recommendations.

    Use cutoff-based soft filters if configuration indicates too little data or
    already finished a cutoff-based filtering step, otherwise try VQSR."""
    algs = [data['config']['algorithm']] * len(data.get('vrn_files', [1]))
    if not config_utils.use_vqsr(algs, in_file) or _already_cutoff_filtered(in_file, filter_type):
        logger.info("Skipping VQSR, using cutoff-based filers: we don't have whole genome input data")
        return hard_filter_fn(in_file, data)
    elif not _have_training_data(vrn_files):
        logger.info('Skipping VQSR, using cutoff-based filers: genome build does not have sufficient training data')
        return hard_filter_fn(in_file, data)
    else:
        sensitivities = {'INDEL': '98.0', 'SNP': '99.97'}
        recal_file, tranches_file = _run_vqsr(in_file, ref_file, vrn_files, sensitivities[filter_type], filter_type, data)
        if recal_file is None:
            logger.info('VQSR failed due to lack of training data. Using cutoff-based soft filtering.')
            return hard_filter_fn(in_file, data)
        else:
            return _apply_vqsr(in_file, ref_file, recal_file, tranches_file, sensitivities[filter_type], filter_type, data)

def gatk_remove_missingalt(in_file, data):
    """GATK 4.1.0.0 outputs variants that have missing ALTs, which breaks downstream
    tools, this filters those out."""
    base = in_file.split('.vcf.gz')[0]
    out_file = '%s-nomissingalt%s' % (base, '.vcf.gz')
    if utils.file_exists(out_file):
        return out_file
    no_gzip_out = out_file.replace('.vcf.gz', '.vcf')
    with file_transaction(no_gzip_out) as tx_out_file:
        with utils.open_gzipsafe(in_file) as in_handle, open(tx_out_file, 'w') as out_handle:
            for line in in_handle:
                line = remove_missingalt(line)
                if line:
                    out_handle.write(line)
    return vcfutils.bgzip_and_index(no_gzip_out, data['config'])

def clean_assembly(gtf_file, clean=None, dirty=None):
    """clean the likely garbage transcripts from the GTF file including:
    1. any novel single-exon transcripts
    2. any features with an unknown strand"""
    base, ext = os.path.splitext(gtf_file)
    db = gtf.get_gtf_db(gtf_file, in_memory=True)
    clean = clean if clean else base + '.clean' + ext
    dirty = dirty if dirty else base + '.dirty' + ext
    if file_exists(clean):
        return (clean, dirty)
    logger.info('Cleaning features with an unknown strand from the assembly.')
    with open(clean, 'w') as clean_handle, open(dirty, 'w') as dirty_handle:
        for gene in db.features_of_type('gene'):
            for transcript in db.children(gene, level=1):
                if is_likely_noise(db, transcript):
                    write_transcript(db, dirty_handle, transcript)
                else:
                    write_transcript(db, clean_handle, transcript)
    return (clean, dirty)

def strand_unknown(db, transcript):
    """for unstranded data with novel transcripts single exon genes
    will have no strand information. single exon novel genes are also
    a source of noise in the Cufflinks assembly so this removes them"""
    features = list(db.children(transcript))
    strand = features[0].strand
    if strand == '.':
        return True
    else:
        return False

def _vcf_alt(base, other_chr, other_pos, isrc, is_first):
    """Create ALT allele line in VCF 4.1 format associating with other paired end.
    """
    if is_first:
        pipe = '[' if isrc else ']'
        out_str = '{base}{pipe}{chr}:{pos}{pipe}'
    else:
        pipe = ']' if isrc else '['
        out_str = '{pipe}{chr}:{pos}{pipe}{base}'
    return out_str.format(pipe=pipe, chr=other_chr, pos=other_pos + 1, base=base)

def _breakend_orientation(strand1, strand2):
    """Convert BEDPE strand representation of breakpoints into VCF.

    | strand1  |  strand2 |     VCF      |
    +----------+----------+--------------+
    |   +      |     -    | t[p[ ]p]t    |
    |   +      |     +    | t]p] t]p]    |
    |   -      |     -    | [p[t [p[t    |
    |   -      |     +    | ]p]t t[p[    |"""
    EndOrientation = namedtuple('EndOrientation', ['is_first1', 'is_rc1', 'is_first2', 'is_rc2'])
    if strand1 == '+' and strand2 == '-':
        return EndOrientation(True, True, False, True)
    elif strand1 == '+' and strand2 == '+':
        return EndOrientation(True, False, True, False)
    elif strand1 == '-' and strand2 == '-':
        return EndOrientation(False, False, False, False)
    elif strand1 == '-' and strand2 == '+':
        return EndOrientation(False, True, True, True)
    else:
        raise ValueError('Unexpected strand pairing: {0} {1}'.format(strand1, strand2))

def build_vcf_deletion(x, genome_2bit):
    """Provide representation of deletion from BedPE breakpoints.
    """
    base1 = genome_2bit[x.chrom1].get(x.start1, x.start1 + 1).upper()
    id1 = 'hydra{0}'.format(x.name)
    return VcfLine(x.chrom1, x.start1, id1, base1, '<DEL>', _vcf_single_end_info(x, 'DEL', True))

def hydra_parser(in_file, options=None):
    """Parse hydra input file into namedtuple of values.
    """
    if options is None:
        options = {}
    BedPe = namedtuple('BedPe', ['chrom1', 'start1', 'end1', 'chrom2', 'start2', 'end2', 'name', 'strand1', 'strand2', 'support'])
    with open(in_file) as in_handle:
        reader = csv.reader(in_handle, dialect='excel-tab')
        for line in reader:
            cur = BedPe(line[0], int(line[1]), int(line[2]), line[3], int(line[4]), int(line[5]), line[6], line[8], line[9], float(line[18]))
            if cur.support >= options.get('min_support', 0):
                yield cur

def _cluster_by(end_iter, attr1, attr2, cluster_distance):
    """Cluster breakends by specified attributes.
    """
    ClusterInfo = namedtuple('ClusterInfo', ['chroms', 'clusters', 'lookup'])
    chr_clusters = {}
    chroms = []
    brends_by_id = {}
    for brend in end_iter:
        if not chr_clusters.has_key(brend.chrom1):
            chroms.append(brend.chrom1)
            chr_clusters[brend.chrom1] = ClusterTree(cluster_distance, 1)
        brends_by_id[int(brend.name)] = brend
        chr_clusters[brend.chrom1].insert(getattr(brend, attr1), getattr(brend, attr2), int(brend.name))
    return ClusterInfo(chroms, chr_clusters, brends_by_id)

def group_hydra_breakends(end_iter):
    """Group together hydra breakends with overlapping ends.

    This provides a way to identify inversions, translocations
    and insertions present in hydra break point ends. We cluster together the
    endpoints and return together any items with closely oriented pairs.
    This helps in describing more complex rearrangement events."""
    cluster_distance, all_ends = _calculate_cluster_distance(end_iter)
    first_cluster = _cluster_by(all_ends, 'start1', 'end1', cluster_distance)
    for chrom in first_cluster.chroms:
        for _, _, brends in first_cluster.clusters[chrom].getregions():
            if len(brends) == 1:
                yield [first_cluster.lookup[brends[0]]]
            else:
                second_cluster = _cluster_by([first_cluster.lookup[x] for x in brends], 'start2', 'end2', cluster_distance)
                for chrom2 in second_cluster.chroms:
                    for _, _, brends in second_cluster.clusters[chrom].getregions():
                        yield [second_cluster.lookup[x] for x in brends]

def _get_vcf_breakends(hydra_file, genome_2bit, options=None):
    """Parse BEDPE input, yielding VCF ready breakends.
    """
    if options is None:
        options = {}
    for features in group_hydra_breakends(hydra_parser(hydra_file, options)):
        if len(features) == 1 and is_deletion(features[0], options):
            yield build_vcf_deletion(features[0], genome_2bit)
        elif len(features) == 1 and is_tandem_dup(features[0], options):
            yield build_tandem_deletion(features[0], genome_2bit)
        elif len(features) == 2 and is_inversion(*features):
            yield build_vcf_inversion(features[0], features[1], genome_2bit)
        elif len(features) == 2 and is_translocation(*features):
            info = get_translocation_info(features[0], features[1])
            for feature in features:
                for brend in build_vcf_parts(feature, genome_2bit, info):
                    yield brend
        else:
            for feature in features:
                for brend in build_vcf_parts(feature, genome_2bit):
                    yield brend

def parse_dirname(fc_dir):
    """Parse the flow cell ID and date from a flow cell directory.
    """
    _, fc_dir = os.path.split(fc_dir)
    parts = fc_dir.split('_')
    name = None
    date = None
    for p in parts:
        if p.endswith(('XX', 'xx', 'XY', 'X2')):
            name = p
        elif len(p) == 6:
            try:
                int(p)
                date = p
            except ValueError:
                pass
    if name is None or date is None:
        raise ValueError('Did not find flowcell name: %s' % fc_dir)
    return (name, date)

def get_qseq_dir(fc_dir):
    """Retrieve the qseq directory within Solexa flowcell output.
    """
    machine_bc = os.path.join(fc_dir, 'Data', 'Intensities', 'BaseCalls')
    if os.path.exists(machine_bc):
        return machine_bc
    else:
        return fc_dir

def get_fastq_dir(fc_dir):
    """Retrieve the fastq directory within Solexa flowcell output.
    """
    full_goat_bc = glob.glob(os.path.join(fc_dir, 'Data', '*Firecrest*', 'Bustard*'))
    bustard_bc = glob.glob(os.path.join(fc_dir, 'Data', 'Intensities', '*Bustard*'))
    machine_bc = os.path.join(fc_dir, 'Data', 'Intensities', 'BaseCalls')
    if os.path.exists(machine_bc):
        return os.path.join(machine_bc, 'fastq')
    elif len(full_goat_bc) > 0:
        return os.path.join(full_goat_bc[0], 'fastq')
    elif len(bustard_bc) > 0:
        return os.path.join(bustard_bc[0], 'fastq')
    else:
        return fc_dir

def this_and_prev(iterable):
    """Walk an iterable, returning the current and previous items
    as a two-tuple."""
    try:
        item = next(iterable)
        while True:
            next_item = next(iterable)
            yield (item, next_item)
            item = next_item
    except StopIteration:
        return

def remove_outliers(series, stddev):
    """Remove the outliers from a series."""
    return series[(series - series.mean()).abs() < stddev * series.std()]

def prep_for_graph(data_frame, series=None, delta_series=None, smoothing=None, outlier_stddev=None):
    """Prepare a dataframe for graphing by calculating deltas for
    series that need them, resampling, and removing outliers."""
    series = series or []
    delta_series = delta_series or []
    graph = calc_deltas(data_frame, delta_series)
    for s in series + delta_series:
        if smoothing:
            graph[s] = graph[s].resample(smoothing)
        if outlier_stddev:
            graph[s] = remove_outliers(graph[s], outlier_stddev)
    return graph[series + delta_series]

def rawfile_within_timeframe(rawfile, timeframe):
    """Checks whether the given raw filename timestamp falls within [start, end] timeframe.
    """
    matches = re.search('-(\\d{8})-', rawfile)
    if matches:
        ftime = datetime.strptime(matches.group(1), '%Y%m%d')
        ftime = pytz.utc.localize(ftime)
    return ftime.date() >= timeframe[0].date() and ftime.date() <= timeframe[1].date()

def get_ploidy(items, region=None):
    """Retrieve ploidy of a region, handling special cases.
    """
    chrom = chromosome_special_cases(region[0] if isinstance(region, (list, tuple)) else None)
    ploidy = _configured_ploidy(items)
    sexes = _configured_genders(items)
    if chrom == 'mitochondrial':
        return ploidy.get('mitochondrial', 1)
    elif chrom == 'X':
        if 'female' in sexes or 'f' in sexes:
            return ploidy.get('female', ploidy['default'])
        elif 'male' in sexes or 'm' in sexes:
            return ploidy.get('male', 1)
        else:
            return ploidy.get('female', ploidy['default'])
    elif chrom == 'Y':
        return 1
    else:
        return ploidy['default']

def filter_vcf_by_sex(vcf_file, items):
    """Post-filter a single sample VCF, handling sex chromosomes.

    Removes Y chromosomes from batches with all female samples."""
    out_file = '%s-ploidyfix%s' % utils.splitext_plus(vcf_file)
    if not utils.file_exists(out_file):
        genders = list(_configured_genders(items))
        is_female = len(genders) == 1 and genders[0] and (genders[0] in ['female', 'f'])
        if is_female:
            orig_out_file = out_file
            out_file = orig_out_file.replace('.vcf.gz', '.vcf')
            with file_transaction(items[0], out_file) as tx_out_file:
                with open(tx_out_file, 'w') as out_handle:
                    with utils.open_gzipsafe(vcf_file) as in_handle:
                        for line in in_handle:
                            if line.startswith('#'):
                                out_handle.write(line)
                            else:
                                chrom = chromosome_special_cases(line.split('\t'))
                                if chrom != 'Y':
                                    out_handle.write(line)
            if orig_out_file.endswith('.gz'):
                out_file = vcfutils.bgzip_and_index(out_file, items[0]['config'])
        else:
            out_file = vcf_file
    return out_file

def variant_filtration(call_file, ref_file, vrn_files, data, items):
    """Filter variant calls using Variant Quality Score Recalibration.

    Newer GATK with Haplotype calling has combined SNP/indel filtering."""
    caller = data['config']['algorithm'].get('variantcaller')
    if 'gvcf' not in dd.get_tools_on(data):
        call_file = ploidy.filter_vcf_by_sex(call_file, items)
    if caller in ['freebayes']:
        return vfilter.freebayes(call_file, ref_file, vrn_files, data)
    elif caller in ['platypus']:
        return vfilter.platypus(call_file, data)
    elif caller in ['samtools']:
        return vfilter.samtools(call_file, data)
    elif caller in ['gatk', 'gatk-haplotype', 'haplotyper']:
        if dd.get_analysis(data).lower().find('rna-seq') >= 0:
            from bcbio.rnaseq import variation as rnaseq_variation
            return rnaseq_variation.gatk_filter_rnaseq(call_file, data)
        else:
            return gatkfilter.run(call_file, ref_file, vrn_files, data)
    else:
        return call_file

def _collapse_by_bam_variantcaller(samples):
    """Collapse regions to a single representative by BAM input, variant caller and batch.
    """
    by_bam = collections.OrderedDict()
    for data in (x[0] for x in samples):
        work_bam = utils.get_in(data, ('combine', 'work_bam', 'out'), data.get('align_bam'))
        variantcaller = get_variantcaller(data)
        if isinstance(work_bam, list):
            work_bam = tuple(work_bam)
        key = (multi.get_batch_for_key(data), work_bam, variantcaller)
        try:
            by_bam[key].append(data)
        except KeyError:
            by_bam[key] = [data]
    out = []
    for grouped_data in by_bam.values():
        cur = grouped_data[0]
        cur.pop('region', None)
        region_bams = cur.pop('region_bams', None)
        if region_bams and len(region_bams[0]) > 1:
            cur.pop('work_bam', None)
        out.append([cur])
    return out

def vc_output_record(samples):
    """Prepare output record from variant calling to feed into downstream analysis.

    Prep work handles reformatting so we return generated dictionaries.

    For any shared keys that are calculated only once for a batch, like variant calls
    for the batch, we assign to every sample."""
    shared_keys = [['vrn_file'], ['validate', 'summary'], ['validate', 'tp'], ['validate', 'fp'], ['validate', 'fn']]
    raw = cwlutils.samples_to_records([utils.to_single_data(x) for x in samples])
    shared = {}
    for key in shared_keys:
        cur = list(set([x for x in [tz.get_in(key, d) for d in raw] if x]))
        if len(cur) > 0:
            assert len(cur) == 1, (key, cur)
            shared[tuple(key)] = cur[0]
        else:
            shared[tuple(key)] = None
    out = []
    for d in raw:
        for key, val in shared.items():
            d = tz.update_in(d, key, lambda x: val)
        out.append([d])
    return out

def batch_for_variantcall(samples):
    """Prepare a set of samples for parallel variant calling.

    CWL input target that groups samples into batches and variant callers
    for parallel processing.

    If doing joint calling, with `tools_on: [gvcf]`, split the sample into
    individuals instead of combining into a batch."""
    sample_order = [dd.get_sample_name(utils.to_single_data(x)) for x in samples]
    to_process, extras = _dup_samples_by_variantcaller(samples, require_bam=False)
    batch_groups = collections.defaultdict(list)
    to_process = [utils.to_single_data(x) for x in to_process]
    for data in cwlutils.samples_to_records(to_process):
        vc = get_variantcaller(data, require_bam=False)
        batches = dd.get_batches(data) or dd.get_sample_name(data)
        if not isinstance(batches, (list, tuple)):
            batches = [batches]
        for b in batches:
            batch_groups[b, vc].append(utils.deepish_copy(data))
    batches = []
    for cur_group in batch_groups.values():
        joint_calling = any([is_joint(d) for d in cur_group])
        if joint_calling:
            for d in cur_group:
                batches.append([d])
        else:
            batches.append(cur_group)
    def by_original_order(xs):
        return (min([sample_order.index(dd.get_sample_name(x)) for x in xs]), min([dd.get_variantcaller_order(x) for x in xs]))
    return sorted(batches + extras, key=by_original_order)

def handle_multiple_callers(data, key, default=None, require_bam=True):
    """Split samples that potentially require multiple variant calling approaches.
    """
    callers = get_variantcaller(data, key, default, require_bam=require_bam)
    if isinstance(callers, six.string_types):
        return [data]
    elif not callers:
        return []
    else:
        out = []
        for caller in callers:
            base = copy.deepcopy(data)
            if not base['config']['algorithm'].get('orig_%s' % key):
                base['config']['algorithm']['orig_%s' % key] = base['config']['algorithm'][key]
            base['config']['algorithm'][key] = caller
            if key == 'variantcaller':
                jcallers = get_variantcaller(data, 'jointcaller', [])
                if isinstance(jcallers, six.string_types):
                    jcallers = [jcallers]
                if jcallers:
                    base['config']['algorithm']['orig_jointcaller'] = jcallers
                    jcallers = [x for x in jcallers if x.startswith(caller)]
                    if jcallers:
                        base['config']['algorithm']['jointcaller'] = jcallers[0]
                    else:
                        base['config']['algorithm']['jointcaller'] = False
            out.append(base)
        return out

def variantcall_sample(data, region=None, align_bams=None, out_file=None):
    """Parallel entry point for doing genotyping of a region of a sample.
    """
    if out_file is None or not os.path.exists(out_file) or (not os.path.lexists(out_file)):
        utils.safe_makedir(os.path.dirname(out_file))
        ref_file = dd.get_ref_file(data)
        config = data['config']
        caller_fns = get_variantcallers()
        caller_fn = caller_fns[config['algorithm'].get('variantcaller')]
        if len(align_bams) == 1:
            items = [data]
        else:
            items = multi.get_orig_items(data)
            assert len(items) == len(align_bams)
        assoc_files = tz.get_in(('genome_resources', 'variation'), data, {})
        if not assoc_files:
            assoc_files = {}
        for bam_file in align_bams:
            bam.index(bam_file, data['config'], check_timestamp=False)
        out_file = caller_fn(align_bams, items, ref_file, assoc_files, region, out_file)
    if region:
        data['region'] = region
    data['vrn_file'] = out_file
    return [data]

def concat_batch_variantcalls(items, region_block=True, skip_jointcheck=False):
    """CWL entry point: combine variant calls from regions into single VCF.
    """
    items = [utils.to_single_data(x) for x in items]
    batch_name = _get_batch_name(items, skip_jointcheck)
    variantcaller = _get_batch_variantcaller(items)
    if not variantcaller and all((d.get('vrn_file') for d in items)):
        return {'vrn_file': items[0]['vrn_file']}
    out_file = os.path.join(dd.get_work_dir(items[0]), variantcaller, '%s.vcf.gz' % batch_name)
    utils.safe_makedir(os.path.dirname(out_file))
    if region_block:
        regions = [_region_to_coords(rs[0]) for rs in items[0]['region_block']]
    else:
        regions = [_region_to_coords(r) for r in items[0]['region']]
    vrn_file_regions = items[0]['vrn_file_region']
    out_file = vcfutils.concat_variant_files(vrn_file_regions, out_file, regions, dd.get_ref_file(items[0]), items[0]['config'])
    return {'vrn_file': out_file}

def _region_to_coords(region):
    """Split GATK region specification (chr1:1-10) into a tuple of chrom, start, end
    """
    chrom, coords = region.split(':')
    start, end = coords.split('-')
    return (chrom, int(start), int(end))

def _get_batch_name(items, skip_jointcheck=False):
    """Retrieve the shared batch name for a group of items.
    """
    batch_names = collections.defaultdict(int)
    has_joint = any([is_joint(d) for d in items])
    for data in items:
        if has_joint and (not skip_jointcheck):
            batches = dd.get_sample_name(data)
        else:
            batches = dd.get_batches(data) or dd.get_sample_name(data)
        if not isinstance(batches, (list, tuple)):
            batches = [batches]
        for b in batches:
            batch_names[b] += 1
    return sorted(batch_names.items(), key=lambda x: x[-1], reverse=True)[0][0]

def per_machine_target_cores(cores, num_jobs):
    """Select target cores on larger machines to leave room for batch script and controller.

    On resource constrained environments, we want to pack all bcbio submissions onto a specific
    number of machines. This gives up some cores to enable sharing cores with the controller
    and batch script on larger machines."""
    if cores >= 32 and num_jobs == 1:
        cores = cores - 2
    elif cores >= 16 and num_jobs in [1, 2]:
        cores = cores - 1
    return cores

def _get_common_cores(resources):
    """Retrieve the most common configured number of cores in the input file.
    """
    all_cores = []
    for vs in resources.values():
        cores = vs.get('cores')
        if cores:
            all_cores.append(int(vs['cores']))
    return collections.Counter(all_cores).most_common(1)[0][0]

def zip_args(args, config=None):
    """Compress arguments using msgpack.
    """
    if msgpack:
        return [msgpack.packb(x, use_single_float=True, use_bin_type=True) for x in args]
    else:
        return args

def runner(view, parallel, dirs, config):
    """Run a task on an ipython parallel cluster, allowing alternative queue types.

    view provides map-style access to an existing Ipython cluster."""
    def run(fn_name, items):
        setpath.prepend_bcbiopath()
        out = []
        fn, fn_name = (fn_name, fn_name.__name__) if callable(fn_name) else (_get_ipython_fn(fn_name, parallel), fn_name)
        items = [x for x in items if x is not None]
        items = diagnostics.track_parallel(items, fn_name)
        logger.info('ipython: %s' % fn_name)
        if len(items) > 0:
            items = [config_utils.add_cores_to_config(x, parallel['cores_per_job'], parallel) for x in items]
            if 'wrapper' in parallel:
                wrap_parallel = {k: v for k, v in parallel.items() if k in set(['fresources'])}
                items = [[fn_name] + parallel.get('wrapper_args', []) + [wrap_parallel] + list(x) for x in items]
            items = zip_args([args for args in items])
            for data in view.map_sync(fn, items, track=False):
                if data:
                    out.extend(unzip_args(data))
        return out
    return run

def peakcall_prepare(data, run_parallel):
    """Entry point for doing peak calling"""
    caller_fns = get_callers()
    to_process = []
    for sample in data:
        mimic = copy.copy(sample[0])
        callers = dd.get_peakcaller(sample[0])
        if not isinstance(callers, list):
            callers = [callers]
        for caller in callers:
            if caller in caller_fns:
                mimic['peak_fn'] = caller
                name = dd.get_sample_name(mimic)
                mimic = _check(mimic, data)
                if mimic:
                    to_process.append(mimic)
                else:
                    logger.info('Skipping peak calling. No input sample for %s' % name)
    if to_process:
        after_process = run_parallel('peakcalling', to_process)
        data = _sync(data, after_process)
    return data

def _sync(original, processed):
    """Add output to data if run sucessfully.
    For now only macs2 is available, so no need
    to consider multiple callers."""
    for original_sample in original:
        original_sample[0]['peaks_files'] = {}
        for process_sample in processed:
            if dd.get_sample_name(original_sample[0]) == dd.get_sample_name(process_sample[0]):
                for key in ['peaks_files']:
                    if process_sample[0].get(key):
                        original_sample[0][key] = process_sample[0][key]
    return original

def _check(sample, data):
    """Get input sample for each chip bam file."""
    if dd.get_chip_method(sample).lower() == 'atac':
        return [sample]
    if dd.get_phenotype(sample) == 'input':
        return None
    for origin in data:
        if dd.get_batch(sample) in (dd.get_batches(origin[0]) or []) and dd.get_phenotype(origin[0]) == 'input':
            sample['work_bam_input'] = origin[0].get('work_bam')
            return [sample]
    return [sample]

def _get_multiplier(samples):
    """Get multiplier to get jobs
    only for samples that have input"""
    to_process = 1.0
    to_skip = 0
    for sample in samples:
        if dd.get_phenotype(sample[0]) == 'chip':
            to_process += 1.0
        elif dd.get_chip_method(sample[0]).lower() == 'atac':
            to_process += 1.0
        else:
            to_skip += 1.0
    mult = (to_process - to_skip) / len(samples)
    if mult <= 0:
        mult = 1 / len(samples)
    return max(mult, 1)

def greylisting(data):
    """Run ChIP-seq greylisting"""
    input_bam = data.get('work_bam_input', None)
    if not input_bam:
        logger.info('No input BAM file detected, skipping greylisting.')
        return None
    try:
        greylister = config_utils.get_program('chipseq-greylist', data)
    except config_utils.CmdNotFound:
        logger.info('No greylister found, skipping greylisting.')
        return None
    greylistdir = os.path.join(os.path.dirname(input_bam), 'greylist')
    if os.path.exists(greylistdir):
        return greylistdir
    cmd = '{greylister} --outdir {txgreylistdir} {input_bam}'
    message = 'Running greylisting on %s.' % input_bam
    with file_transaction(greylistdir) as txgreylistdir:
        utils.safe_makedir(txgreylistdir)
        try:
            do.run(cmd.format(**locals()), message)
        except subprocess.CalledProcessError as msg:
            if str(msg).find("Cannot take a larger sample than population when 'replace=False'") >= 0:
                logger.info('Skipping chipseq greylisting because of small sample size: %s' % dd.get_sample_name(data))
                return None
    return greylistdir

def _get_cores_and_type(numcores, paralleltype, scheduler):
    """Return core and parallelization approach from command line providing sane defaults.
    """
    if scheduler is not None:
        paralleltype = 'ipython'
    if paralleltype is None:
        paralleltype = 'local'
    if not numcores or int(numcores) < 1:
        numcores = 1
    return (paralleltype, int(numcores))

def _estimate_paired_innerdist(fastq_file, pair_file, ref_file, out_base, out_dir, data):
    """Use Bowtie to estimate the inner distance of paired reads.
    """
    mean, stdev = _bowtie_for_innerdist('100000', fastq_file, pair_file, ref_file, out_base, out_dir, data, True)
    if not mean or not stdev:
        mean, stdev = _bowtie_for_innerdist('1', fastq_file, pair_file, ref_file, out_base, out_dir, data, True)
    if not mean or not stdev:
        mean, stdev = (200, 50)
    return (mean, stdev)

def _filter_to_info(in_file, data):
    """Move DKFZ filter information into INFO field.
    """
    header = '##INFO=<ID=DKFZBias,Number=.,Type=String,Description="Bias estimation based on unequal read support from DKFZBiasFilterVariant Depth">\n'
    out_file = '%s-ann.vcf' % utils.splitext_plus(in_file)[0]
    if not utils.file_uptodate(out_file, in_file) and (not utils.file_uptodate(out_file + '.gz', in_file)):
        with file_transaction(data, out_file) as tx_out_file:
            with utils.open_gzipsafe(in_file) as in_handle:
                with open(tx_out_file, 'w') as out_handle:
                    for line in in_handle:
                        if line.startswith('#CHROM'):
                            out_handle.write(header + line)
                        elif line.startswith('#'):
                            out_handle.write(line)
                        else:
                            out_handle.write(_rec_filter_to_info(line))
    return vcfutils.bgzip_and_index(out_file, data['config'])

def _rec_filter_to_info(line):
    """Move a DKFZBias filter to the INFO field, for a record.
    """
    parts = line.rstrip().split('\t')
    move_filters = {'bSeq': 'strand', 'bPcr': 'damage'}
    new_filters = []
    bias_info = []
    for f in parts[6].split(';'):
        if f in move_filters:
            bias_info.append(move_filters[f])
        elif f not in ['.']:
            new_filters.append(f)
    if bias_info:
        parts[7] += ';DKFZBias=%s' % ','.join(bias_info)
    parts[6] = ';'.join(new_filters or ['PASS'])
    return '\t'.join(parts) + '\n'

def should_filter(items):
    """Check if we should do damage filtering on somatic calling with low frequency events.
    """
    return vcfutils.get_paired(items) is not None and any(('damage_filter' in dd.get_tools_on(d) for d in items))

