def _parse_impact_header(hdr_dict):
    """Parse fields for impact, taken from vcf2db
    """
    desc = hdr_dict['Description']
    if hdr_dict['ID'] == 'ANN':
        parts = [x.strip('"\'') for x in re.split('\\s*\\|\\s*', desc.split(':', 1)[1].strip('" '))]
    elif hdr_dict['ID'] == 'EFF':
        parts = [x.strip(' [])\'("') for x in re.split('\\||\\(', desc.split(':', 1)[1].strip())]
    elif hdr_dict['ID'] == 'CSQ':
        parts = [x.strip(' [])\'("') for x in re.split('\\||\\(', desc.split(':', 1)[1].strip())]
    elif hdr_dict['ID'] == 'BCSQ':
        parts = desc.split(']', 1)[1].split(']')[0].replace('[', '').split('|')
    else:
        raise Exception("don't know how to use %s as annotation" % hdr_dict['ID'])
    return parts

def _prepare_vcf_rec(rec, pops, known, impact_info):
    """Parse a vcfanno output into a dictionary of useful attributes.
    """
    out = {}
    for k in pops + known:
        out[k] = rec.INFO.get(k)
    if impact_info:
        cur_info = rec.INFO.get(impact_info.id)
        if cur_info:
            cur_impacts = [impact_info.gclass(e, impact_info.header) for e in _from_bytes(cur_info).split(',')]
            top = geneimpacts.Effect.top_severity(cur_impacts)
            if isinstance(top, list):
                top = top[0]
            out['impact_severity'] = top.effect_severity
    return out

def _known_populations(row, pops):
    """Find variants present in substantial frequency in population databases.
    """
    cutoff = 0.01
    out = set([])
    for pop, base in [('esp', 'af_esp_all'), ('1000g', 'af_1kg_all'), ('exac', 'af_exac_all'), ('anypop', 'max_aaf_all')]:
        for key in [x for x in pops if x.startswith(base)]:
            val = row[key]
            if val and val > cutoff:
                out.add(pop)
    return sorted(list(out))

def _find_known(row):
    """Find variant present in known pathogenic databases.
    """
    out = []
    clinvar_no = set(['unknown', 'untested', 'non-pathogenic', 'probable-non-pathogenic', 'uncertain_significance', 'uncertain_significance', 'not_provided', 'benign', 'likely_benign'])
    if row['cosmic_ids'] or row['cosmic_id']:
        out.append('cosmic')
    if row['clinvar_sig'] and (not row['clinvar_sig'].lower() in clinvar_no):
        out.append('clinvar')
    return out

def _do_prioritize(items):
    """Determine if we should perform prioritization.

    Currently done on tumor-only input samples and feeding into PureCN
    which needs the germline annotations."""
    if not any(('tumoronly-prioritization' in dd.get_tools_off(d) for d in items)):
        if vcfutils.get_paired_phenotype(items[0]):
            has_tumor = False
            has_normal = False
            for sub_data in items:
                if vcfutils.get_paired_phenotype(sub_data) == 'tumor':
                    has_tumor = True
                elif vcfutils.get_paired_phenotype(sub_data) == 'normal':
                    has_normal = True
            return has_tumor and (not has_normal)

def _remap_cortex_out(cortex_out, region, out_file):
    """Remap coordinates in local cortex variant calls to the original global region.
    """
    def _remap_vcf_line(line, contig, start):
        parts = line.split('\t')
        if parts[0] == '' or parts[1] == '':
            return None
        parts[0] = contig
        try:
            parts[1] = str(int(parts[1]) + start)
        except ValueError:
            raise ValueError('Problem in {0} with \n{1}'.format(cortex_out, parts))
        return '\t'.join(parts)
    def _not_filtered(line):
        parts = line.split('\t')
        return parts[6] == 'PASS'
    contig, start, _ = region
    start = int(start)
    with open(cortex_out) as in_handle:
        with open(out_file, 'w') as out_handle:
            for line in in_handle:
                if line.startswith('##fileDate'):
                    pass
                elif line.startswith('#'):
                    out_handle.write(line)
                elif _not_filtered(line):
                    update_line = _remap_vcf_line(line, contig, start)
                    if update_line:
                        out_handle.write(update_line)

def _count_fastq_reads(in_fastq, min_reads):
    """Count the number of fastq reads in a file, stopping after reaching min_reads.
    """
    with open(in_fastq) as in_handle:
        items = list(itertools.takewhile(lambda i: i <= min_reads, (i for i, _ in enumerate(FastqGeneralIterator(in_handle)))))
    return len(items)

def file_transaction(*data_and_files):
    """Wrap file generation in a transaction, moving to output if finishes.

    The initial argument can be the world descriptive `data` dictionary, or
    a `config` dictionary. This is used to identify global settings for
    temporary directories to create transactional files in."""
    with _flatten_plus_safe(data_and_files) as (safe_names, orig_names):
        map(utils.remove_safe, safe_names)
        if len(safe_names) == 1:
            yield safe_names[0]
        else:
            yield tuple(safe_names)
        for safe, orig in zip(safe_names, orig_names):
            if os.path.exists(safe):
                _move_tmp_files(safe, orig)

def _gatk_extract_reads_cl(data, region, prep_params, tmp_dir):
    """Use GATK to extract reads from full BAM file.
    """
    args = ['PrintReads', '-L', region_to_gatk(region), '-R', dd.get_ref_file(data), '-I', data['work_bam']]
    if 'gatk4' in dd.get_tools_off(data):
        args = ['--analysis_type'] + args
    runner = broad.runner_from_config(data['config'])
    return runner.cl_gatk(args, tmp_dir)

def _piped_input_cl(data, region, tmp_dir, out_base_file, prep_params):
    """Retrieve the commandline for streaming input into preparation step.
    """
    return (data['work_bam'], _gatk_extract_reads_cl(data, region, prep_params, tmp_dir))

def _get_prep_params(data):
    """Retrieve configuration parameters with defaults for preparing BAM files.
    """
    realign_param = dd.get_realign(data)
    realign_param = 'gatk' if realign_param is True else realign_param
    return {'realign': realign_param}

def _piped_bamprep_region(data, region, out_file, tmp_dir):
    """Do work of preparing BAM input file on the selected region.
    """
    if _need_prep(data):
        prep_params = _get_prep_params(data)
        _piped_bamprep_region_gatk(data, region, prep_params, out_file, tmp_dir)
    else:
        raise ValueError('No realignment specified')

def piped_bamprep(data, region=None, out_file=None):
    """Perform full BAM preparation using pipes to avoid intermediate disk IO.

    Handles realignment of original BAMs."""
    data['region'] = region
    if not _need_prep(data):
        return [data]
    else:
        utils.safe_makedir(os.path.dirname(out_file))
        if region[0] == 'nochrom':
            prep_bam = shared.write_nochr_reads(data['work_bam'], out_file, data['config'])
        elif region[0] == 'noanalysis':
            prep_bam = shared.write_noanalysis_reads(data['work_bam'], region[1], out_file, data['config'])
        else:
            if not utils.file_exists(out_file):
                with tx_tmpdir(data) as tmp_dir:
                    _piped_bamprep_region(data, region, out_file, tmp_dir)
            prep_bam = out_file
        bam.index(prep_bam, data['config'])
        data['work_bam'] = prep_bam
        return [data]

def update_file(finfo, sample_info, config):
    """Update file in Galaxy data libraries.
    """
    if GalaxyInstance is None:
        raise ImportError('Could not import bioblend.galaxy')
    if 'dir' not in config:
        raise ValueError('Galaxy upload requires `dir` parameter in config specifying the shared filesystem path to move files to.')
    if 'outputs' in config:
        _galaxy_tool_copy(finfo, config['outputs'])
    else:
        _galaxy_library_upload(finfo, sample_info, config)

def _galaxy_tool_copy(finfo, outputs):
    """Copy information directly to pre-defined outputs from a Galaxy tool.

    XXX Needs generalization"""
    tool_map = {'align': 'bam', 'variants': 'vcf.gz'}
    for galaxy_key, finfo_type in tool_map.items():
        if galaxy_key in outputs and finfo.get('type') == finfo_type:
            shutil.copy(finfo['path'], outputs[galaxy_key])

def _galaxy_library_upload(finfo, sample_info, config):
    """Upload results to galaxy library.
    """
    folder_name = '%s_%s' % (config['fc_date'], config['fc_name'])
    storage_dir = utils.safe_makedir(os.path.join(config['dir'], folder_name))
    if finfo.get('type') == 'directory':
        storage_file = None
        if finfo.get('ext') == 'qc':
            pdf_file = qcsummary.prep_pdf(finfo['path'], config)
            if pdf_file:
                finfo['path'] = pdf_file
                finfo['type'] = 'pdf'
                storage_file = filesystem.copy_finfo(finfo, storage_dir, pass_uptodate=True)
    else:
        storage_file = filesystem.copy_finfo(finfo, storage_dir, pass_uptodate=True)
    if 'galaxy_url' in config and 'galaxy_api_key' in config:
        galaxy_url = config['galaxy_url']
        if not galaxy_url.endswith('/'):
            galaxy_url += '/'
        gi = GalaxyInstance(galaxy_url, config['galaxy_api_key'])
    else:
        raise ValueError('Galaxy upload requires `galaxy_url` and `galaxy_api_key` in config')
    if storage_file and sample_info and (not finfo.get('index', False)) and (not finfo.get('plus', False)):
        _to_datalibrary_safe(storage_file, gi, folder_name, sample_info, config)

def _to_datalibrary_safe(fname, gi, folder_name, sample_info, config):
    """Upload with retries for intermittent JSON failures.
    """
    num_tries = 0
    max_tries = 5
    while 1:
        try:
            _to_datalibrary(fname, gi, folder_name, sample_info, config)
            break
        except (simplejson.scanner.JSONDecodeError, bioblend.galaxy.client.ConnectionError) as e:
            num_tries += 1
            if num_tries > max_tries:
                raise
            print('Retrying upload, failed with:', str(e))
            time.sleep(5)

def _file_to_folder(gi, fname, sample_info, libitems, library, folder):
    """Check if file exists on Galaxy, if not upload to specified folder.
    """
    full_name = os.path.join(folder['name'], os.path.basename(fname))
    file_type = 'vcf_bgzip' if full_name.endswith('.vcf.gz') else 'auto'
    if full_name.endswith('.vcf.gz'):
        full_name = full_name.replace('.vcf.gz', '.vcf')
    for item in libitems:
        if item['name'] == full_name:
            return item
    logger.info("Uploading to Galaxy library '%s': %s" % (library.name, full_name))
    return gi.libraries.upload_from_galaxy_filesystem(str(library.id), fname, folder_id=str(folder['id']), link_data_only='link_to_files', dbkey=sample_info['genome_build'], file_type=file_type, roles=str(library.roles) if library.roles else None)

def _get_folder(gi, folder_name, library, libitems):
    """Retrieve or create a folder inside the library with the specified name.
    """
    for item in libitems:
        if item['type'] == 'folder' and item['name'] == '/%s' % folder_name:
            return item
    return gi.libraries.create_folder(library.id, folder_name)[0]

def _get_library(gi, sample_info, config):
    """Retrieve the appropriate data library for the current user.
    """
    galaxy_lib = sample_info.get('galaxy_library', config.get('galaxy_library'))
    role = sample_info.get('galaxy_role', config.get('galaxy_role'))
    if galaxy_lib:
        return _get_library_from_name(gi, galaxy_lib, role, sample_info, create=True)
    elif config.get('private_libs') or config.get('lab_association') or config.get('researcher'):
        return _library_from_nglims(gi, sample_info, config)
    else:
        raise ValueError('No Galaxy library specified for sample: %s' % sample_info['description'])

def _library_from_nglims(gi, sample_info, config):
    """Retrieve upload library from nglims specified user libraries.
    """
    names = [config.get(x, '').strip() for x in ['lab_association', 'researcher'] if config.get(x)]
    for name in names:
        for ext in ['sequencing', 'lab']:
            check_name = '%s %s' % (name.split()[0], ext)
            try:
                return _get_library_from_name(gi, check_name, None, sample_info)
            except ValueError:
                pass
    check_names = set([x.lower() for x in names])
    for libname, role in config['private_libs']:
        if libname.lower() in check_names:
            return _get_library_from_name(gi, libname, role, sample_info)
    if len(config.get('private_libs', [])) > 0:
        libname, role = config['private_libs'][0]
        return _get_library_from_name(gi, libname, role, sample_info)
    elif len(names) > 0:
        return _get_library_from_name(gi, names[0], None, sample_info, create=True)
    else:
        raise ValueError('Could not find Galaxy library for sample %s' % sample_info['description'])

def _get_input_args(bam_file, data, out_base, background):
    """Retrieve input args, depending on genome build.

    VerifyBamID2 only handles GRCh37 (1, 2, 3) not hg19, so need to generate
    a pileup for hg19 and fix chromosome naming."""
    if dd.get_genome_build(data) in ['hg19']:
        return ['--PileupFile', _create_pileup(bam_file, data, out_base, background)]
    else:
        return ['--BamFile', bam_file]

def _cnvbed_to_bed(in_file, caller, out_file):
    """Convert cn_mops CNV based bed files into flattened BED
    """
    with open(out_file, 'w') as out_handle:
        for feat in pybedtools.BedTool(in_file):
            out_handle.write('\t'.join([feat.chrom, str(feat.start), str(feat.end), 'cnv%s_%s' % (feat.score, caller)]) + '\n')

def to_bed(call, sample, work_dir, calls, data):
    """Create a simplified BED file from caller specific input.
    """
    out_file = os.path.join(work_dir, '%s-%s-flat.bed' % (sample, call['variantcaller']))
    if call.get('vrn_file') and (not utils.file_uptodate(out_file, call['vrn_file'])):
        with file_transaction(data, out_file) as tx_out_file:
            convert_fn = CALLER_TO_BED.get(call['variantcaller'])
            if convert_fn:
                vrn_file = call['vrn_file']
                if call['variantcaller'] in SUBSET_BY_SUPPORT:
                    ecalls = [x for x in calls if x['variantcaller'] in SUBSET_BY_SUPPORT[call['variantcaller']]]
                    if len(ecalls) > 0:
                        vrn_file = _subset_by_support(call['vrn_file'], ecalls, data)
                convert_fn(vrn_file, call['variantcaller'], tx_out_file)
    if utils.file_exists(out_file):
        return out_file

def _subset_by_support(orig_vcf, cmp_calls, data):
    """Subset orig_vcf to calls also present in any of the comparison callers.
    """
    cmp_vcfs = [x['vrn_file'] for x in cmp_calls]
    out_file = '%s-inensemble.vcf.gz' % utils.splitext_plus(orig_vcf)[0]
    if not utils.file_uptodate(out_file, orig_vcf):
        with file_transaction(data, out_file) as tx_out_file:
            cmd = 'bedtools intersect -header -wa -f 0.5 -r -a {orig_vcf} -b '
            for cmp_vcf in cmp_vcfs:
                cmd += "<(bcftools view -f 'PASS,.' %s) " % cmp_vcf
            cmd += '| bgzip -c > {tx_out_file}'
            do.run(cmd.format(**locals()), 'Subset calls by those present in Ensemble output')
    return vcfutils.bgzip_and_index(out_file, data['config'])

def picard_merge(picard, in_files, out_file=None, merge_seq_dicts=False):
    """Merge multiple BAM files together with Picard.
    """
    if out_file is None:
        out_file = '%smerge.bam' % os.path.commonprefix(in_files)
    if not file_exists(out_file):
        with tx_tmpdir(picard._config) as tmp_dir:
            with file_transaction(picard._config, out_file) as tx_out_file:
                opts = [('OUTPUT', tx_out_file), ('SORT_ORDER', 'coordinate'), ('MERGE_SEQUENCE_DICTIONARIES', 'true' if merge_seq_dicts else 'false'), ('USE_THREADING', 'true'), ('TMP_DIR', tmp_dir)]
                for in_file in in_files:
                    opts.append(('INPUT', in_file))
                picard.run('MergeSamFiles', opts)
    return out_file

def picard_bam_to_fastq(picard, in_bam, fastq_one, fastq_two=None):
    """Convert BAM file to fastq.
    """
    if not file_exists(fastq_one):
        with tx_tmpdir(picard._config) as tmp_dir:
            with file_transaction(picard._config, fastq_one) as tx_out1:
                opts = [('INPUT', in_bam), ('FASTQ', tx_out1), ('TMP_DIR', tmp_dir)]
                if fastq_two is not None:
                    opts += [('SECOND_END_FASTQ', fastq_two)]
                picard.run('SamToFastq', opts)
    return (fastq_one, fastq_two)

def picard_idxstats(picard, align_bam):
    """Retrieve alignment stats from picard using BamIndexStats.
    """
    opts = [('INPUT', align_bam)]
    stdout = picard.run('BamIndexStats', opts, get_stdout=True)
    out = []
    AlignInfo = collections.namedtuple('AlignInfo', ['contig', 'length', 'aligned', 'unaligned'])
    for line in stdout.split('\n'):
        if line:
            parts = line.split()
            if len(parts) == 2:
                _, unaligned = parts
                out.append(AlignInfo('nocontig', 0, 0, int(unaligned)))
            elif len(parts) == 7:
                contig, _, length, _, aligned, _, unaligned = parts
                out.append(AlignInfo(contig, int(length), int(aligned), int(unaligned)))
            else:
                raise ValueError('Unexpected output from BamIndexStats: %s' % line)
    return out

def _enforce_max_region_size(in_file, data):
    """Ensure we don't have any chunks in the region greater than 20kb.

    VarDict memory usage depends on size of individual windows in the input
    file. This breaks regions into 20kb chunks with 250bp overlaps. 20kb gives
    ~1Gb/core memory usage and the overlaps avoid missing indels spanning a
    gap. Downstream VarDict merging sorts out any variants across windows.

    https://github.com/AstraZeneca-NGS/VarDictJava/issues/64"""
    max_size = 20000
    overlap_size = 250
    def _has_larger_regions(f):
        return any((r.stop - r.start > max_size for r in pybedtools.BedTool(f)))
    out_file = '%s-regionlimit%s' % utils.splitext_plus(in_file)
    if not utils.file_exists(out_file):
        if _has_larger_regions(in_file):
            with file_transaction(data, out_file) as tx_out_file:
                pybedtools.BedTool().window_maker(w=max_size, s=max_size - overlap_size, b=pybedtools.BedTool(in_file)).saveas(tx_out_file)
        else:
            utils.symlink_plus(in_file, out_file)
    return out_file

def run_vardict(align_bams, items, ref_file, assoc_files, region=None, out_file=None):
    """Run VarDict variant calling.
    """
    items = shared.add_highdepth_genome_exclusion(items)
    if vcfutils.is_paired_analysis(align_bams, items):
        call_file = _run_vardict_paired(align_bams, items, ref_file, assoc_files, region, out_file)
    else:
        vcfutils.check_paired_problems(items)
        call_file = _run_vardict_caller(align_bams, items, ref_file, assoc_files, region, out_file)
    return call_file

def _get_jvm_opts(data, out_file):
    """Retrieve JVM options when running the Java version of VarDict.
    """
    if get_vardict_command(data) == 'vardict-java':
        resources = config_utils.get_resources('vardict', data['config'])
        jvm_opts = resources.get('jvm_opts', ['-Xms750m', '-Xmx4g'])
        jvm_opts += broad.get_default_jvm_opts(os.path.dirname(out_file))
        return "export VAR_DICT_OPTS='%s' && " % ' '.join(jvm_opts)
    else:
        return ''

def add_db_germline_flag(line):
    """Adds a DB flag for Germline filters, allowing downstream compatibility with PureCN.
    """
    if line.startswith('#CHROM'):
        headers = ['##INFO=<ID=DB,Number=0,Type=Flag,Description="Likely germline variant">']
        return '\n'.join(headers) + '\n' + line
    elif line.startswith('#'):
        return line
    else:
        parts = line.split('\t')
        if parts[7].find('STATUS=Germline') >= 0:
            parts[7] += ';DB'
        return '\t'.join(parts)

def get_vardict_command(data):
    """convert variantcaller specification to proper vardict command, handling
    string or list specification"""
    vcaller = dd.get_variantcaller(data)
    if isinstance(vcaller, list):
        vardict = [x for x in vcaller if 'vardict' in x]
        if not vardict:
            return None
        vardict = vardict[0]
    elif not vcaller:
        return None
    else:
        vardict = vcaller
    vardict = 'vardict-java' if not vardict.endswith('-perl') else 'vardict'
    return vardict

def run(vrn_info, calls_by_name, somatic_info, do_plots=True, handle_failures=True):
    """Run BubbleTree given variant calls, CNVs and somatic
    """
    if 'seq2c' in calls_by_name:
        cnv_info = calls_by_name['seq2c']
    elif 'cnvkit' in calls_by_name:
        cnv_info = calls_by_name['cnvkit']
    else:
        raise ValueError('BubbleTree only currently support CNVkit and Seq2c: %s' % ', '.join(calls_by_name.keys()))
    work_dir = _cur_workdir(somatic_info.tumor_data)
    class OutWriter:
        def __init__(self, out_handle):
            self.writer = csv.writer(out_handle)
        def write_header(self):
            self.writer.writerow(['chrom', 'start', 'end', 'freq'])
        def write_row(self, rec, stats):
            self.writer.writerow([_to_ucsc_style(rec.chrom), rec.start, rec.stop, stats['tumor']['freq']])
    vcf_csv = prep_vrn_file(vrn_info['vrn_file'], vrn_info['variantcaller'], work_dir, somatic_info, OutWriter, cnv_info['cns'])
    cnv_csv = _prep_cnv_file(cnv_info['cns'], cnv_info['variantcaller'], work_dir, somatic_info.tumor_data)
    wide_lrr = cnv_info['variantcaller'] == 'cnvkit' and somatic_info.normal_bam is None
    return _run_bubbletree(vcf_csv, cnv_csv, somatic_info.tumor_data, wide_lrr, do_plots, handle_failures)

def max_normal_germline_depth(in_file, params, somatic_info):
    """Calculate threshold for excluding potential heterozygotes based on normal depth.
    """
    bcf_in = pysam.VariantFile(in_file)
    depths = []
    for rec in bcf_in:
        stats = _is_possible_loh(rec, bcf_in, params, somatic_info)
        if tz.get_in(['normal', 'depth'], stats):
            depths.append(tz.get_in(['normal', 'depth'], stats))
    if depths:
        return np.median(depths) * NORMAL_FILTER_PARAMS['max_depth_percent']

def _identify_heterogeneity_blocks_seg(in_file, seg_file, params, work_dir, somatic_info):
    """Identify heterogeneity blocks corresponding to segmentation from CNV input file.
    """
    def _segment_by_cns(target_chrom, freqs, coords):
        with open(seg_file) as in_handle:
            reader = csv.reader(in_handle, dialect='excel-tab')
            next(reader)
            for cur_chrom, start, end in (xs[:3] for xs in reader):
                if cur_chrom == target_chrom:
                    block_freqs = []
                    for i, (freq, coord) in enumerate(zip(freqs, coords)):
                        if coord >= int(start) and coord < int(end):
                            block_freqs.append(freq)
                        elif coord >= int(end):
                            break
                    coords = coords[max(0, i - 1):]
                    freqs = freqs[max(0, i - 1):]
                    if len(block_freqs) > params['hetblock']['min_alleles']:
                        yield (start, end)
    return _identify_heterogeneity_blocks_shared(in_file, _segment_by_cns, params, work_dir, somatic_info)

def _identify_heterogeneity_blocks_hmm(in_file, params, work_dir, somatic_info):
    """Use a HMM to identify blocks of heterogeneity to use for calculating allele frequencies.

    The goal is to subset the genome to a more reasonable section that contains potential
    loss of heterogeneity or other allele frequency adjustment based on selection."""
    def _segment_by_hmm(chrom, freqs, coords):
        cur_coords = []
        for j, state in enumerate(_predict_states(freqs)):
            if state == 0:
                if len(cur_coords) == 0:
                    num_misses = 0
                cur_coords.append(coords[j])
            else:
                num_misses += 1
            if num_misses > params['hetblock']['allowed_misses']:
                if len(cur_coords) >= params['hetblock']['min_alleles']:
                    yield (min(cur_coords), max(cur_coords))
                cur_coords = []
        if len(cur_coords) >= params['hetblock']['min_alleles']:
            yield (min(cur_coords), max(cur_coords))
    return _identify_heterogeneity_blocks_shared(in_file, _segment_by_hmm, params, work_dir, somatic_info)

def _freqs_by_chromosome(in_file, params, somatic_info):
    """Retrieve frequencies across each chromosome as inputs to HMM.
    """
    freqs = []
    coords = []
    cur_chrom = None
    with pysam.VariantFile(in_file) as bcf_in:
        for rec in bcf_in:
            if _is_biallelic_snp(rec) and _passes_plus_germline(rec) and chromhacks.is_autosomal(rec.chrom):
                if cur_chrom is None or rec.chrom != cur_chrom:
                    if cur_chrom and len(freqs) > 0:
                        yield (cur_chrom, freqs, coords)
                    cur_chrom = rec.chrom
                    freqs = []
                    coords = []
                stats = _tumor_normal_stats(rec, somatic_info)
                if tz.get_in(['tumor', 'depth'], stats, 0) > params['min_depth']:
                    if len(rec.samples) == 0 or sum(rec.samples[somatic_info.tumor_name].allele_indices) > 0:
                        freqs.append(tz.get_in(['tumor', 'freq'], stats))
                        coords.append(rec.start)
        if cur_chrom and len(freqs) > 0:
            yield (cur_chrom, freqs, coords)

def is_info_germline(rec):
    """Check if a variant record is germline based on INFO attributes.

    Works with VarDict's annotation of STATUS."""
    if hasattr(rec, 'INFO'):
        status = rec.INFO.get('STATUS', '').lower()
    else:
        status = rec.info.get('STATUS', '').lower()
    return status == 'germline' or status.find('loh') >= 0

def _passes_plus_germline(rec, use_status=False):
    """Check if a record passes filters (but might be germline -- labelled with REJECT).
    """
    if use_status and is_info_germline(rec):
        return True
    allowed = set(['PASS', 'REJECT', '.'])
    if hasattr(rec, 'FILTER'):
        if not rec.FILTER:
            filters = []
        else:
            filters = [x for x in rec.FILTER.split(';') if x not in allowed]
    else:
        filters = [x for x in rec.filter.keys() if x not in allowed]
    return len(filters) == 0

def _tumor_normal_stats(rec, somatic_info, vcf_rec):
    """Retrieve depth and frequency of tumor and normal samples.
    """
    out = {'normal': {'alt': None, 'depth': None, 'freq': None}, 'tumor': {'alt': 0, 'depth': 0, 'freq': None}}
    if hasattr(vcf_rec, 'samples'):
        samples = [(s, {}) for s in vcf_rec.samples]
        for fkey in ['AD', 'AO', 'RO', 'AF', 'DP']:
            try:
                for i, v in enumerate(rec.format(fkey)):
                    samples[i][1][fkey] = v
            except KeyError:
                pass
    elif len(rec.samples) == 0:
        samples = [(somatic_info.tumor_name, None)]
    else:
        samples = rec.samples.items()
    for name, sample in samples:
        alt, depth, freq = sample_alt_and_depth(rec, sample)
        if depth is not None and freq is not None:
            if name == somatic_info.normal_name:
                key = 'normal'
            elif name == somatic_info.tumor_name:
                key = 'tumor'
            out[key]['freq'] = freq
            out[key]['depth'] = depth
            out[key]['alt'] = alt
    return out

def _is_possible_loh(rec, vcf_rec, params, somatic_info, use_status=False, max_normal_depth=None):
    """Check if the VCF record is a het in the normal with sufficient support.

    Only returns SNPs, since indels tend to have less precise frequency measurements."""
    if _is_biallelic_snp(rec) and _passes_plus_germline(rec, use_status=use_status):
        stats = _tumor_normal_stats(rec, somatic_info, vcf_rec)
        depths = [tz.get_in([x, 'depth'], stats) for x in ['normal', 'tumor']]
        depths = [d for d in depths if d is not None]
        normal_freq = tz.get_in(['normal', 'freq'], stats)
        tumor_freq = tz.get_in(['tumor', 'freq'], stats)
        if all([d > params['min_depth'] for d in depths]):
            if max_normal_depth and tz.get_in(['normal', 'depth'], stats, 0) > max_normal_depth:
                return None
            if normal_freq is not None:
                if normal_freq >= params['min_freq'] and normal_freq <= params['max_freq']:
                    return stats
            elif tumor_freq >= params['tumor_only']['min_freq'] and tumor_freq <= params['tumor_only']['max_freq']:
                if vcf_rec and (not _has_population_germline(vcf_rec)) or is_population_germline(rec):
                    return stats

def _has_population_germline(rec):
    """Check if header defines population annotated germline samples for tumor only.
    """
    for k in population_keys:
        if k in rec.header.info:
            return True
    return False

def is_population_germline(rec):
    """Identify a germline calls based on annoations with ExAC or other population databases.
    """
    min_count = 50
    for k in population_keys:
        if k in rec.info:
            val = rec.info.get(k)
            if ',' in val:
                val = val.split(',')[0]
            if isinstance(val, (list, tuple)):
                val = max(val)
            if int(val) > min_count:
                return True
    return False

def sample_alt_and_depth(rec, sample):
    """Flexibly get ALT allele and depth counts, handling FreeBayes, MuTect and other cases.
    """
    if sample and 'AD' in sample:
        all_counts = [int(x) for x in sample['AD']]
        alt_counts = sum(all_counts[1:])
        depth = sum(all_counts)
    elif sample and 'AO' in sample and (sample.get('RO') is not None):
        alts = sample['AO']
        if not isinstance(alts, (list, tuple)):
            alts = [alts]
        alt_counts = sum([int(x) for x in alts])
        depth = alt_counts + int(sample['RO'])
    elif 'DP' in rec.info and 'AF' in rec.info:
        af = rec.info['AF'][0] if isinstance(rec.info['AF'], (tuple, list)) else rec.info['AF']
        return (None, rec.info['DP'], af)
    else:
        alt_counts = None
    if alt_counts is None or depth is None or depth == 0:
        return (None, None, None)
    else:
        freq = float(alt_counts) / float(depth)
        return (alt_counts, depth, freq)

def get_max_counts(samples):
    """Retrieve number of regions that can be processed in parallel from current samples.
    """
    counts = []
    for data in (x[0] for x in samples):
        count = tz.get_in(['config', 'algorithm', 'callable_count'], data, 1)
        vcs = tz.get_in(['config', 'algorithm', 'variantcaller'], data, [])
        if isinstance(vcs, six.string_types):
            vcs = [vcs]
        if vcs:
            count *= len(vcs)
        counts.append(count)
    return max(counts)

def parallel_prep_region(samples, run_parallel):
    """Perform full pre-variant calling BAM prep work on regions.
    """
    file_key = 'work_bam'
    split_fn = _split_by_regions('bamprep', '-prep.bam', file_key)
    extras = []
    torun = []
    for data in [x[0] for x in samples]:
        if data.get('work_bam'):
            data['align_bam'] = data['work_bam']
        if not dd.get_realign(data) and (not dd.get_variantcaller(data)):
            extras.append([data])
        elif not data.get(file_key):
            extras.append([data])
        else:
            data['config']['algorithm']['orig_markduplicates'] = dd.get_mark_duplicates(data)
            data = dd.set_mark_duplicates(data, False)
            torun.append([data])
    return extras + parallel_split_combine(torun, split_fn, run_parallel, 'piped_bamprep', _add_combine_info, file_key, ['config'])

def delayed_bamprep_merge(samples, run_parallel):
    """Perform a delayed merge on regional prepared BAM files.
    """
    if any(('combine' in data[0] for data in samples)):
        return run_parallel('delayed_bam_merge', samples)
    else:
        return samples

def clean_sample_data(samples):
    """Clean unnecessary information from sample data, reducing size for message passing.
    """
    out = []
    for data in (utils.to_single_data(x) for x in samples):
        if 'dirs' in data:
            data['dirs'] = {'work': data['dirs']['work'], 'galaxy': data['dirs']['galaxy'], 'fastq': data['dirs'].get('fastq')}
        data['config'] = {'algorithm': data['config']['algorithm'], 'resources': data['config']['resources']}
        for remove_attr in ['config_file', 'algorithm']:
            data.pop(remove_attr, None)
        out.append([data])
    return out

def _add_sj_index_commands(fq1, ref_file, gtf_file):
    """newer versions of STAR can generate splice junction databases on thephfly
    this is preferable since we can tailor it to the read lengths"""
    if _has_sj_index(ref_file):
        return ''
    else:
        rlength = fastq.estimate_maximum_read_length(fq1)
        cmd = ' --sjdbGTFfile %s ' % gtf_file
        cmd += ' --sjdbOverhang %s ' % str(rlength - 1)
        return cmd

def _has_sj_index(ref_file):
    """this file won't exist if we can do on the fly splice junction indexing"""
    return file_exists(os.path.join(ref_file, 'sjdbInfo.txt')) and file_exists(os.path.join(ref_file, 'transcriptInfo.tab'))

def remap_index_fn(ref_file):
    """Map sequence references to equivalent star indexes
    """
    return os.path.join(os.path.dirname(os.path.dirname(ref_file)), 'star')

def get_splicejunction_file(out_dir, data):
    """locate the splicejunction file starting from the alignment directory"""
    samplename = dd.get_sample_name(data)
    sjfile = os.path.join(out_dir, os.pardir, '{0}SJ.out.tab').format(samplename)
    if file_exists(sjfile):
        return sjfile
    else:
        return None

def run(data):
    """HLA typing with OptiType, parsing output from called genotype files.
    """
    hlas = []
    for hla_fq in tz.get_in(['hla', 'fastq'], data, []):
        hla_type = re.search('[.-](?P<hlatype>HLA-[\\w-]+).fq', hla_fq).group('hlatype')
        if hla_type in SUPPORTED_HLAS:
            if utils.file_exists(hla_fq):
                hlas.append((hla_type, hla_fq))
    if len(hlas) > 0:
        out_dir = utils.safe_makedir(os.path.join(dd.get_work_dir(data), 'align', dd.get_sample_name(data), 'hla', 'OptiType-HLA-A_B_C'))
        if len(hlas) > len(SUPPORTED_HLAS):
            hlas = [x for x in hlas if os.path.basename(x[1]).find('-cumi') == -1]
        if len(hlas) == len(SUPPORTED_HLAS):
            hla_fq = combine_hla_fqs(hlas, out_dir + '-input.fq', data)
            if utils.file_exists(hla_fq):
                out_file = glob.glob(os.path.join(out_dir, '*', '*_result.tsv'))
                if len(out_file) > 0:
                    out_file = out_file[0]
                else:
                    out_file = _call_hla(hla_fq, out_dir, data)
                out_file = _prepare_calls(out_file, os.path.dirname(out_dir), data)
                data['hla'].update({'call_file': out_file, 'hlacaller': 'optitype'})
    return data

def combine_hla_fqs(hlas, out_file, data):
    """OptiType performs best on a combination of all extracted HLAs.
    """
    if not utils.file_exists(out_file):
        with file_transaction(data, out_file) as tx_out_file:
            with open(tx_out_file, 'w') as out_handle:
                for hla_type, hla_fq in hlas:
                    if utils.file_exists(hla_fq):
                        with open(hla_fq) as in_handle:
                            shutil.copyfileobj(in_handle, out_handle)
    return out_file

def _prepare_calls(result_file, out_dir, data):
    """Write summary file of results of HLA typing by allele.
    """
    sample = dd.get_sample_name(data)
    out_file = os.path.join(out_dir, '%s-optitype.csv' % sample)
    if not utils.file_uptodate(out_file, result_file):
        hla_truth = bwakit.get_hla_truthset(data)
        with file_transaction(data, out_file) as tx_out_file:
            with open(tx_out_file, 'w') as out_handle:
                writer = csv.writer(out_handle)
                allele_info = _parse_result_file(result_file)
                if len(allele_info) == 1:
                    writer.writerow(['sample', 'locus', 'alleles', 'expected', 'validates'])
                else:
                    writer.writerow(['sample', 'local', 'index', 'alleles', 'score'])
                for j, (alleles, score) in enumerate(allele_info):
                    for hla_locus, call_alleles in alleles:
                        truth_alleles = tz.get_in([sample, hla_locus], hla_truth, [])
                        if len(allele_info) == 1:
                            writer.writerow([sample, hla_locus, ';'.join(call_alleles), ';'.join(truth_alleles), bwakit.matches_truth(call_alleles, truth_alleles, data)])
                        else:
                            writer.writerow([sample, hla_locus, j, ';'.join(call_alleles), score])
    return out_file

def is_autosomal(chrom):
    """Keep chromosomes that are a digit 1-22, or chr prefixed digit chr1-chr22
    """
    try:
        int(chrom)
        return True
    except ValueError:
        try:
            int(str(chrom.lower().replace('chr', '').replace('_', '').replace('-', '')))
            return True
        except ValueError:
            return False

def run(_, data, out_dir):
    """Prepare variants QC analysis: bcftools stats and snpEff output.
    """
    out = []
    vcinfo = get_active_vcinfo(data)
    if vcinfo:
        if dd.get_phenotype(data) == 'normal' and 'germline' in vcinfo:
            out.append(_bcftools_stats(data, out_dir, 'germline', germline=True))
        elif dd.get_phenotype(data) != 'germline':
            out.append(_bcftools_stats(data, out_dir))
            if 'germline' in vcinfo:
                out.append(_bcftools_stats(data, out_dir, 'germline', germline=True))
        else:
            out.append(_bcftools_stats(data, out_dir, germline=True))
    out.append(_snpeff_stats(data, out_dir))
    out = [item for item in out if item]
    if out:
        return {'base': out[0], 'secondary': out[1:]}

def _add_filename_details(full_f):
    """Add variant callers and germline information standard CWL filenames.

    This is an ugly way of working around not having metadata with calls."""
    out = {'vrn_file': full_f}
    f = os.path.basename(full_f)
    for vc in list(genotype.get_variantcallers().keys()) + ['ensemble']:
        if f.find('-%s.vcf' % vc) > 0:
            out['variantcaller'] = vc
    if f.find('-germline-') >= 0:
        out['germline'] = full_f
    return out

def _get_variants(data):
    """Retrieve variants from CWL and standard inputs for organizing variants.
    """
    active_vs = []
    if 'variants' in data:
        variants = data['variants']
        if isinstance(variants, dict) and 'samples' in variants:
            variants = variants['samples']
        for v in variants:
            if isinstance(v, six.string_types) and os.path.exists(v):
                active_vs.append(_add_filename_details(v))
            elif isinstance(v, (list, tuple)) and len(v) > 0 and isinstance(v[0], six.string_types) and os.path.exists(v[0]):
                for subv in v:
                    active_vs.append(_add_filename_details(subv))
            elif isinstance(v, dict):
                if v.get('vrn_file'):
                    active_vs.append(v)
                elif v.get('population'):
                    vrnfile = v.get('population').get('vcf')
                    active_vs.append(_add_filename_details(vrnfile))
                elif v.get('vcf'):
                    active_vs.append(_add_filename_details(v.get('vcf')))
    return active_vs

def get_active_vcinfo(data, use_ensemble=True):
    """Use first caller if ensemble is not active
    """
    active_vs = _get_variants(data)
    if len(active_vs) > 0:
        e_active_vs = []
        if use_ensemble:
            e_active_vs = [v for v in active_vs if v.get('variantcaller') == 'ensemble']
        if len(e_active_vs) == 0:
            e_active_vs = [v for v in active_vs if v.get('variantcaller') != 'ensemble']
        if len(e_active_vs) > 0:
            return e_active_vs[0]

def extract_germline_vcinfo(data, out_dir):
    """Extract germline VCFs from existing tumor inputs.
    """
    supported_germline = set(['vardict', 'octopus', 'freebayes'])
    if dd.get_phenotype(data) in ['tumor']:
        for v in _get_variants(data):
            if v.get('variantcaller') in supported_germline:
                if v.get('germline'):
                    return v
                else:
                    d = utils.deepish_copy(data)
                    d['vrn_file'] = v['vrn_file']
                    gd = germline.extract(d, [d], out_dir)
                    v['germline'] = gd['vrn_file_plus']['germline']
                    return v

def _merge_outfile_fname(out_file, bam_files, work_dir, batch):
    """Derive correct name of BAM file based on batching.
    """
    if out_file is None:
        out_file = os.path.join(work_dir, os.path.basename(sorted(bam_files)[0]))
    if batch is not None:
        base, ext = os.path.splitext(out_file)
        out_file = '%s-b%s%s' % (base, batch, ext)
    return out_file

def _finalize_merge(out_file, bam_files, config):
    """Handle indexes and cleanups of merged BAM and input files.
    """
    for ext in ['', '.bai']:
        if os.path.exists(out_file + ext):
            subprocess.check_call(['touch', out_file + ext])
    for b in bam_files:
        utils.save_diskspace(b, 'BAM merged to %s' % out_file, config)

def _cwl_workflow_template(inputs, top_level=False):
    """Retrieve CWL inputs shared amongst different workflows.
    """
    ready_inputs = []
    for inp in inputs:
        cur_inp = copy.deepcopy(inp)
        for attr in ['source', 'valueFrom', 'wf_duplicate']:
            cur_inp.pop(attr, None)
        if top_level:
            cur_inp = workflow._flatten_nested_input(cur_inp)
        cur_inp = _clean_record(cur_inp)
        ready_inputs.append(cur_inp)
    return {'class': 'Workflow', 'cwlVersion': 'v1.0', 'hints': [], 'requirements': [{'class': 'EnvVarRequirement', 'envDef': [{'envName': 'MPLCONFIGDIR', 'envValue': '.'}]}, {'class': 'ScatterFeatureRequirement'}, {'class': 'SubworkflowFeatureRequirement'}], 'inputs': ready_inputs, 'outputs': [], 'steps': []}

def _add_current_quay_tag(repo, container_tags):
    """Lookup the current quay tag for the repository, adding to repo string.

    Enables generation of CWL explicitly tied to revisions."""
    if ':' in repo:
        return (repo, container_tags)
    try:
        latest_tag = container_tags[repo]
    except KeyError:
        repo_id = repo[repo.find('/') + 1:]
        tags = requests.request('GET', 'https://quay.io/api/v1/repository/' + repo_id).json()['tags']
        latest_tag = None
        latest_modified = None
        for tag, info in tags.items():
            if latest_tag:
                if dateutil.parser.parse(info['last_modified']) > dateutil.parser.parse(latest_modified) and tag != 'latest':
                    latest_modified = info['last_modified']
                    latest_tag = tag
            else:
                latest_modified = info['last_modified']
                latest_tag = tag
        container_tags[repo] = str(latest_tag)
    latest_pull = repo + ':' + str(latest_tag)
    return (latest_pull, container_tags)

def _write_expressiontool(step_dir, name, inputs, outputs, expression, parallel):
    """Create an ExpressionTool output for the given inputs
    """
    out_file = os.path.join(step_dir, '%s.cwl' % name)
    out = {'class': 'ExpressionTool', 'cwlVersion': 'v1.0', 'requirements': [{'class': 'InlineJavascriptRequirement'}], 'inputs': [], 'outputs': [], 'expression': expression}
    out = _add_inputs_to_tool(inputs, out, parallel)
    out = _add_outputs_to_tool(outputs, out)
    _tool_to_file(out, out_file)
    return os.path.join('steps', os.path.basename(out_file))

def _clean_record(rec):
    """Remove secondary files from record fields, which are currently not supported.

    To be removed later when secondaryFiles added to records."""
    if workflow.is_cwl_record(rec):
        def _clean_fields(d):
            if isinstance(d, dict):
                if 'fields' in d:
                    out = []
                    for f in d['fields']:
                        f = utils.deepish_copy(f)
                        f.pop('secondaryFiles', None)
                        out.append(f)
                    d['fields'] = out
                    return d
                else:
                    out = {}
                    for k, v in d.items():
                        out[k] = _clean_fields(v)
                    return out
            else:
                return d
        return _clean_fields(rec)
    else:
        return rec

def _get_record_fields(d):
    """Get field names from a potentially nested record.
    """
    if isinstance(d, dict):
        if 'fields' in d:
            return d['fields']
        else:
            for v in d.values():
                fields = _get_record_fields(v)
                if fields:
                    return fields

def _place_input_binding(inp_tool, inp_binding, parallel):
    """Check nesting of variables to determine where to place the input binding.

    We want to allow having multiple files together (like fasta_indices), combined
    with the itemSeparator, but also support having multiple samples where we pass
    things independently."""
    if parallel in ['multi-combined', 'multi-batch', 'batch-split', 'batch-parallel', 'batch-merge', 'batch-single'] and tz.get_in(['type', 'type'], inp_tool) == 'array':
        inp_tool['type']['inputBinding'] = inp_binding
    else:
        inp_tool['inputBinding'] = inp_binding
    return inp_tool

def _place_secondary_files(inp_tool, inp_binding=None):
    """Put secondaryFiles at the level of the File item to ensure indexes get passed.
    """
    def _is_file(val):
        return val == 'File' or (isinstance(val, (list, tuple)) and ('File' in val or any(isinstance(x, dict) and _is_file(val)) for x in val))
    secondary_files = inp_tool.pop('secondaryFiles', None)
    if secondary_files:
        key = []
        while not _is_file(tz.get_in(key + ['type'], inp_tool)) and (not _is_file(tz.get_in(key + ['items'], inp_tool))) and (not _is_file(tz.get_in(key + ['items', 'items'], inp_tool))):
            key.append('type')
        if tz.get_in(key, inp_tool):
            inp_tool['secondaryFiles'] = secondary_files
        elif inp_binding:
            nested_inp_binding = copy.deepcopy(inp_binding)
            nested_inp_binding['prefix'] = 'ignore='
            nested_inp_binding['secondaryFiles'] = secondary_files
            inp_tool = tz.update_in(inp_tool, key, lambda x: nested_inp_binding)
    return inp_tool

def _do_scatter_var(v, parallel):
    """Logic for scattering a variable.
    """
    if parallel.startswith('batch') and workflow.is_cwl_record(v):
        return tz.get_in(['type', 'type'], v) == 'array' and tz.get_in(['type', 'type', 'type'], v) == 'array'
    else:
        return tz.get_in(['type', 'type'], v) == 'array'

def _step_template(name, run_file, inputs, outputs, parallel, step_parallelism, scatter=None):
    """Templating function for writing a step to avoid repeating namespaces.
    """
    scatter_inputs = []
    sinputs = []
    for inp in inputs:
        step_inp = {'id': workflow.get_base_id(inp['id']), 'source': inp['id']}
        if inp.get('wf_duplicate'):
            step_inp['id'] += '_toolinput'
        for attr in ['source', 'valueFrom']:
            if attr in inp:
                step_inp[attr] = inp[attr]
        sinputs.append(step_inp)
        if parallel == 'multi-parallel' and (not step_parallelism or step_parallelism.get(workflow.get_step_prefix(inp['id'])) == 'multi-parallel'):
            scatter_inputs.append(step_inp['id'])
        elif _is_scatter_parallel(parallel) and (_do_scatter_var(inp, parallel) or (scatter and inp['id'] in scatter)):
            scatter_inputs.append(step_inp['id'])
    out = {'run': run_file, 'id': name, 'in': sinputs, 'out': [{'id': workflow.get_base_id(output['id'])} for output in outputs]}
    if _is_scatter_parallel(parallel):
        assert scatter_inputs, 'Did not find items to scatter on: %s' % name
        out.update({'scatterMethod': 'dotproduct', 'scatter': scatter_inputs})
    return out

def _get_cur_remotes(path):
    """Retrieve remote references defined in the CWL.
    """
    cur_remotes = set([])
    if isinstance(path, (list, tuple)):
        for v in path:
            cur_remotes |= _get_cur_remotes(v)
    elif isinstance(path, dict):
        for v in path.values():
            cur_remotes |= _get_cur_remotes(v)
    elif path and isinstance(path, six.string_types):
        if path.startswith(tuple(INTEGRATION_MAP.keys())):
            cur_remotes.add(INTEGRATION_MAP.get(path.split(':')[0] + ':'))
    return cur_remotes

def _flatten_samples(samples, base_file, get_retriever):
    """Create a flattened JSON representation of data from the bcbio world map.
    """
    flat_data = []
    for data in samples:
        data['reference'] = _indexes_to_secondary_files(data['reference'], data['genome_build'])
        cur_flat = {}
        for key_path in [['analysis'], ['description'], ['rgnames'], ['config', 'algorithm'], ['metadata'], ['genome_build'], ['resources'], ['files'], ['reference'], ['genome_resources'], ['vrn_file']]:
            cur_key = '__'.join(key_path)
            for flat_key, flat_val in _to_cwldata(cur_key, tz.get_in(key_path, data), get_retriever):
                cur_flat[flat_key] = flat_val
        flat_data.append(cur_flat)
    out = {}
    for key in sorted(list(set(reduce(operator.add, [list(d.keys()) for d in flat_data])))):
        clean_key = key.replace('.', '_')
        out[clean_key] = []
        for cur_flat in flat_data:
            out[clean_key].append(cur_flat.get(key))
    if 'reference__fasta__base' not in out and 'reference__fasta' in out:
        out['reference__fasta__base'] = out['reference__fasta']
        del out['reference__fasta']
    return (_samplejson_to_inputs(out), out)

def _indexes_to_secondary_files(gresources, genome_build):
    """Convert a list of genome indexes into a single file plus secondary files.

    This ensures that all indices are staged together in a single directory."""
    out = {}
    for refname, val in gresources.items():
        if isinstance(val, dict) and 'indexes' in val:
            if len(val.keys()) == 1:
                indexes = sorted(val['indexes'])
                if len(indexes) == 0:
                    if refname not in alignment.allow_noindices():
                        raise ValueError('Did not find indexes for %s: %s' % (refname, val))
                elif len(indexes) == 1:
                    val = {'indexes': indexes[0]}
                else:
                    val = {'indexes': {'base': indexes[0], 'indexes': indexes[1:]}}
            elif 'base' in val and os.path.isdir(val['base']) and (len(val['indexes']) > 0):
                indexes = val['indexes']
                val = {'base': indexes[0], 'indexes': indexes[1:]}
        elif isinstance(val, dict) and genome_build in val:
            val = _indexes_to_secondary_files(val, genome_build)
        out[refname] = val
    return out

def _get_secondary_files(val):
    """Retrieve associated secondary files.

    Normalizes input values into definitions of available secondary files.
    Requires indices to be present in all files, since declared CWL secondary
    files are not optional. So if we have a mix of BAM (bai) and fastq (gbi) we
    ignore the existing indices and will have to regenerate during processing."""
    out = []
    if isinstance(val, (tuple, list)):
        s_counts = collections.defaultdict(int)
        for x in val:
            for s in _get_secondary_files(x):
                s_counts[s] += 1
        for s, count in s_counts.items():
            if s and s not in out and (count == len([x for x in val if x])):
                out.append(s)
    elif isinstance(val, dict) and (val.get('class') == 'File' or 'File' in val.get('class')):
        if 'secondaryFiles' in val:
            for sf in [x['path'] for x in val['secondaryFiles']]:
                rext = _get_relative_ext(val['path'], sf)
                if rext and rext not in out:
                    out.append(rext)
    return out

def _get_relative_ext(of, sf):
    """Retrieve relative extension given the original and secondary files.
    """
    def half_finished_trim(orig, prefix):
        return os.path.basename(prefix).count('.') > 0 and os.path.basename(orig).count('.') == os.path.basename(prefix).count('.')
    if of.find(':') > 0:
        of = os.path.basename(of.split(':')[-1])
    if sf.find(':') > 0:
        sf = os.path.basename(sf.split(':')[-1])
    prefix = os.path.commonprefix([sf, of])
    while prefix.endswith('.') or (half_finished_trim(sf, prefix) and half_finished_trim(of, prefix)):
        prefix = prefix[:-1]
    exts_to_remove = of.replace(prefix, '')
    ext_to_add = sf.replace(prefix, '')
    if not exts_to_remove or exts_to_remove.startswith('.'):
        return str('^' * exts_to_remove.count('.') + ext_to_add)
    else:
        raise ValueError('No cross platform way to reference complex extension: %s %s' % (sf, of))

def _avoid_duplicate_arrays(types):
    """Collapse arrays when we have multiple types.
    """
    arrays = [t for t in types if isinstance(t, dict) and t['type'] == 'array']
    others = [t for t in types if not (isinstance(t, dict) and t['type'] == 'array')]
    if arrays:
        items = set([])
        for t in arrays:
            if isinstance(t['items'], (list, tuple)):
                items |= set(t['items'])
            else:
                items.add(t['items'])
        if len(items) == 1:
            items = items.pop()
        else:
            items = sorted(list(items))
        arrays = [{'type': 'array', 'items': items}]
    return others + arrays

def _to_cwlfile_with_indexes(val, get_retriever):
    """Convert reads with ready to go indexes into the right CWL object.

    Identifies the top level directory and creates a tarball, avoiding
    trying to handle complex secondary setups which are not cross platform.

    Skips doing this for reference files and standard setups like bwa, which
    take up too much time and space to unpack multiple times."""
    val['indexes'] = _index_blacklist(val['indexes'])
    tval = {'base': _remove_remote_prefix(val['base']), 'indexes': [_remove_remote_prefix(f) for f in val['indexes']]}
    cp_dir, cp_base = os.path.split(os.path.commonprefix([tval['base']] + tval['indexes']))
    if cp_base and cp_dir == os.path.dirname(tval['base']) and (not ('/snpeff/' in cp_dir or '/hisat2' in cp_dir)):
        return _item_to_cwldata(val['base'], get_retriever, val['indexes'])
    else:
        dirname = os.path.dirname(tval['base'])
        assert all([x.startswith(dirname) for x in tval['indexes']])
        return {'class': 'File', 'path': directory_tarball(dirname)}

def _file_local_or_remote(f, get_retriever):
    """Check for presence of a local or remote file.
    """
    if os.path.exists(f):
        return f
    integration, config = get_retriever.integration_and_config(f)
    if integration:
        return integration.file_exists(f, config)

def _adjust_files(xs, adjust_fn):
    """Walk over key/value, tuples applying adjust_fn to files.
    """
    if isinstance(xs, dict):
        if 'path' in xs:
            out = {}
            out['path'] = adjust_fn(xs['path'])
            for k, vs in xs.items():
                if k != 'path':
                    out[k] = _adjust_files(vs, adjust_fn)
            return out
        else:
            out = {}
            for k, vs in xs.items():
                out[k] = _adjust_files(vs, adjust_fn)
            return out
    elif isinstance(xs, (list, tuple)):
        return [_adjust_files(x, adjust_fn) for x in xs]
    else:
        return xs

def _calc_input_estimates(keyvals, get_retriever):
    """Calculate estimations of input file sizes for disk usage approximation.

    These are current dominated by fastq/BAM sizes, so estimate based on that."""
    out = {}
    for key, val in keyvals.items():
        size = _calc_file_size(val, 0, get_retriever)
        if size:
            out[key] = size
    return out

def _get_file_size(path, get_retriever):
    """Return file size in megabytes, including querying remote integrations
    """
    integration, config = get_retriever.integration_and_config(path)
    if integration:
        return integration.file_size(path, config)
    elif os.path.exists(path):
        return os.path.getsize(path) / (1024.0 * 1024.0)

def runner(parallel, config):
    """Run functions, provided by string name, on multiple cores on the current machine.
    """
    def run_parallel(fn_name, items):
        items = [x for x in items if x is not None]
        if len(items) == 0:
            return []
        items = diagnostics.track_parallel(items, fn_name)
        fn, fn_name = (fn_name, fn_name.__name__) if callable(fn_name) else (get_fn(fn_name, parallel), fn_name)
        logger.info('multiprocessing: %s' % fn_name)
        if 'wrapper' in parallel:
            wrap_parallel = {k: v for k, v in parallel.items() if k in set(['fresources', 'checkpointed'])}
            items = [[fn_name] + parallel.get('wrapper_args', []) + [wrap_parallel] + list(x) for x in items]
        return run_multicore(fn, items, config, parallel=parallel)
    return run_parallel

def zeromq_aware_logging(f):
    """Ensure multiprocessing logging uses ZeroMQ queues.

    ZeroMQ and local stdout/stderr do not behave nicely when intertwined. This
    ensures the local logging uses existing ZeroMQ logging queues."""
    @functools.wraps(f)
    def wrapper(*args, **kwargs):
        config = None
        for arg in args:
            if config_utils.is_std_config_arg(arg):
                config = arg
                break
            elif config_utils.is_nested_config_arg(arg):
                config = arg['config']
            elif isinstance(arg, (list, tuple)) and config_utils.is_nested_config_arg(arg[0]):
                config = arg[0]['config']
                break
        assert config, 'Could not find config dictionary in function arguments.'
        if config.get('parallel', {}).get('log_queue') and (not config.get('parallel', {}).get('wrapper')):
            handler = setup_local_logging(config, config['parallel'])
        else:
            handler = None
        try:
            out = f(*args, **kwargs)
        finally:
            if handler and hasattr(handler, 'close'):
                handler.close()
        return out
    return wrapper

def run_multicore(fn, items, config, parallel=None):
    """Run the function using multiple cores on the given items to process.
    """
    if len(items) == 0:
        return []
    if parallel is None or 'num_jobs' not in parallel:
        if parallel is None:
            parallel = {'type': 'local', 'cores': config['algorithm'].get('num_cores', 1)}
        sysinfo = system.get_info({}, parallel)
        parallel = resources.calculate(parallel, items, sysinfo, config, parallel.get('multiplier', 1), max_multicore=int(parallel.get('max_multicore', sysinfo['cores'])))
    items = [config_utils.add_cores_to_config(x, parallel['cores_per_job']) for x in items]
    if joblib is None:
        raise ImportError('Need joblib for multiprocessing parallelization')
    out = []
    for data in joblib.Parallel(parallel['num_jobs'], batch_size=1, backend='multiprocessing')((joblib.delayed(fn)(*x) for x in items)):
        if data:
            out.extend(data)
    return out

def _find_umi(files):
    """Find UMI file using different naming schemes.

    R1/R2/R3 => R1/R3 with R2 UMI
    R1/R2/I1 => R1/R2 with I1 UMI"""
    base = os.path.basename(_commonprefix(files))
    def _file_ext(f):
        exts = utils.splitext_plus(os.path.basename(f).replace(base, ''))[0].split('_')
        exts = [x for x in exts if x]
        return exts[0]
    exts = dict([(_file_ext(f), f) for f in files])
    if 'I1' in exts:
        return (exts['R1'], exts['R2'], exts['I1'])
    else:
        assert 'R3' in exts, exts
        return (exts['R1'], exts['R3'], exts['R2'])

def cutoff_w_expression(vcf_file, expression, data, name='+', filterext='', extra_cmd='', limit_regions='variant_regions'):
    """Perform cutoff-based soft filtering using bcftools expressions like %QUAL < 20 || DP < 4.
    """
    base, ext = utils.splitext_plus(vcf_file)
    out_file = '{base}-filter{filterext}{ext}'.format(**locals())
    if not utils.file_exists(out_file):
        with file_transaction(data, out_file) as tx_out_file:
            if vcfutils.vcf_has_variants(vcf_file):
                bcftools = config_utils.get_program('bcftools', data['config'])
                bgzip_cmd = '| bgzip -c' if out_file.endswith('.gz') else ''
                intervals = ''
                if limit_regions == 'variant_regions':
                    variant_regions = dd.get_variant_regions(data)
                    if variant_regions:
                        intervals = '-T %s' % vcfutils.bgzip_and_index(variant_regions, data['config'])
                cmd = "{bcftools} filter -O v {intervals} --soft-filter '{name}' -e '{expression}' -m '+' {vcf_file} {extra_cmd} {bgzip_cmd} > {tx_out_file}"
                do.run(cmd.format(**locals()), 'Cutoff-based soft filtering %s with %s' % (vcf_file, expression), data)
            else:
                shutil.copy(vcf_file, out_file)
    if out_file.endswith('.vcf.gz'):
        out_file = vcfutils.bgzip_and_index(out_file, data['config'])
    return out_file

def _do_high_depth_filter(data):
    """Check if we should do high depth filtering -- only on germline non-regional calls.
    """
    is_genome = tz.get_in(['config', 'algorithm', 'coverage_interval'], data, '').lower() == 'genome'
    is_paired = vcfutils.get_paired_phenotype(data)
    return is_genome and (not is_paired)

def _calc_vcf_stats(in_file):
    """Calculate statistics on VCF for filtering, saving to a file for quick re-runs.
    """
    out_file = '%s-stats.yaml' % utils.splitext_plus(in_file)[0]
    if not utils.file_exists(out_file):
        stats = {'avg_depth': _average_called_depth(in_file)}
        with open(out_file, 'w') as out_handle:
            yaml.safe_dump(stats, out_handle, default_flow_style=False, allow_unicode=False)
        return stats
    else:
        with open(out_file) as in_handle:
            stats = yaml.safe_load(in_handle)
        return stats

def _average_called_depth(in_file):
    """Retrieve the average depth of called reads in the provided VCF.
    """
    import cyvcf2
    depths = []
    for rec in cyvcf2.VCF(str(in_file)):
        d = rec.INFO.get('DP')
        if d is not None:
            depths.append(int(d))
    if len(depths) > 0:
        return int(math.ceil(numpy.mean(depths)))
    else:
        return 0

def run(vrn_info, cnvs_by_name, somatic_info):
    """Run PhyloWGS given variant calls, CNVs and tumor/normal information.
    """
    config = {'sample_size': 5000}
    work_dir = _cur_workdir(somatic_info.tumor_data)
    if 'battenberg' not in cnvs_by_name:
        logger.warn('PhyloWGS requires Battenberg CNV calls, skipping %s' % dd.get_sample_name(somatic_info.tumor_data))
    else:
        ssm_file, cnv_file = _prep_inputs(vrn_info, cnvs_by_name['battenberg'], somatic_info, work_dir, config)
        evolve_file = _run_evolve(ssm_file, cnv_file, work_dir, somatic_info.tumor_data)
        summary_file = _prepare_summary(evolve_file, ssm_file, cnv_file, work_dir, somatic_info)
        print(summary_file)

def _gids_to_genes(gids, ssm_locs, cnv_ssms, data):
    """Convert support ids for SNPs and SSMs into associated genes.
    """
    locs = collections.defaultdict(set)
    for gid in gids:
        cur_locs = []
        try:
            cur_locs.append(ssm_locs[gid])
        except KeyError:
            for ssm_loc in cnv_ssms.get(gid, []):
                cur_locs.append(ssm_locs[ssm_loc])
        for chrom, pos in cur_locs:
            locs[chrom].add(pos)
    genes = set([])
    with tx_tmpdir(data) as tmpdir:
        chrom_prefix = 'chr' if next(ref.file_contigs(dd.get_ref_file(data))).name.startswith('chr') else ''
        loc_file = os.path.join(tmpdir, 'battenberg_find_genes.bed')
        with open(loc_file, 'w') as out_handle:
            for chrom in sorted(locs.keys()):
                for loc in sorted(list(locs[chrom])):
                    out_handle.write('%s%s\t%s\t%s\n' % (chrom_prefix, chrom, loc - 1, loc))
        ann_file = annotate.add_genes(loc_file, data, max_distance=10000)
        for r in pybedtools.BedTool(ann_file):
            for gene in r.name.split(','):
                if gene != '.':
                    genes.add(gene)
    return sorted(list(genes))

def _evolve_reader(in_file):
    """Generate a list of region IDs and trees from a top_k_trees evolve.py file.
    """
    cur_id_list = None
    cur_tree = None
    with open(in_file) as in_handle:
        for line in in_handle:
            if line.startswith('id,'):
                if cur_id_list:
                    yield (cur_id_list, cur_tree)
                cur_id_list = []
                cur_tree = None
            elif cur_tree is not None:
                if line.strip() and (not line.startswith('Number of non-empty')):
                    cur_tree.append(line.rstrip())
            elif not line.strip() and cur_id_list and (len(cur_id_list) > 0):
                cur_tree = []
            elif line.strip():
                parts = []
                for part in line.strip().split('\t'):
                    if part.endswith(','):
                        part = part[:-1]
                    parts.append(part)
                if len(parts) > 4:
                    nid, freq, _, _, support = parts
                    cur_id_list.append((nid, freq, support.split('; ')))
    if cur_id_list:
        yield (cur_id_list, cur_tree)

def _read_cnv_ssms(in_file):
    """Map CNVs to associated SSMs
    """
    out = {}
    with open(in_file) as in_handle:
        in_handle.readline()
        for line in in_handle:
            parts = line.strip().split()
            if len(parts) > 3:
                cnvid, _, _, ssms = parts
                out[cnvid] = [x.split(',')[0] for x in ssms.split(';')]
    return out

def _cluster(bam_file, ma_file, out_dir, reference, annotation_file=None):
    """Connect to seqcluster to run cluster with python directly"""
    seqcluster = op.join(get_bcbio_bin(), 'seqcluster')
    if annotation_file:
        annotation_file = '-g ' + annotation_file
    else:
        annotation_file = ''
    if not file_exists(op.join(out_dir, 'counts.tsv')):
        cmd = '{seqcluster} cluster -o {out_dir} -m {ma_file} -a {bam_file} -r {reference} {annotation_file}'
        do.run(cmd.format(**locals()), 'Running seqcluster.')
    counts = op.join(out_dir, 'counts.tsv')
    stats = op.join(out_dir, 'read_stats.tsv')
    json = op.join(out_dir, 'seqcluster.json')
    return {'out_dir': out_dir, 'count_file': counts, 'stat_file': stats, 'json': json}

def _guess_header(info):
    """Add the first group to get report with some factor"""
    value = 'group'
    if 'metadata' in info:
        if info['metadata']:
            return ','.join(map(str, info['metadata'].keys()))
    return value

def _guess_group(info):
    """Add the first group to get report with some factor"""
    value = 'fake'
    if 'metadata' in info:
        if info['metadata']:
            return ','.join(map(str, info['metadata'].values()))
    return value

def _make_isomir_counts(data, srna_type='seqbuster', out_dir=None, stem=''):
    """Parse miraligner files to create count matrix."""
    work_dir = dd.get_work_dir(data[0][0])
    if not out_dir:
        out_dir = op.join(work_dir, 'mirbase')
    out_novel_isomir = append_stem(op.join(out_dir, 'counts.tsv'), stem)
    out_novel_mirna = append_stem(op.join(out_dir, 'counts_mirna.tsv'), stem)
    logger.debug('Create %s count data at %s.' % (srna_type, out_dir))
    if file_exists(out_novel_mirna):
        return [out_novel_mirna, out_novel_isomir]
    out_dts = []
    for sample in data:
        if sample[0].get(srna_type):
            miraligner_fn = sample[0][srna_type]
            reads = _read_miraligner(miraligner_fn)
            if reads:
                out_file, dt, dt_pre = _tab_output(reads, miraligner_fn + '.back', dd.get_sample_name(sample[0]))
                out_dts.append(dt)
            else:
                logger.debug('WARNING::%s has NOT miRNA annotated for %s. Check if fasta files is small or species value.' % (dd.get_sample_name(sample[0]), srna_type))
    if out_dts:
        out_files = _create_counts(out_dts, out_dir)
        out_files = [move_safe(out_files[0], out_novel_isomir), move_safe(out_files[1], out_novel_mirna)]
        return out_files
    else:
        logger.debug('WARNING::any samples have miRNA annotated for %s. Check if fasta files is small or species value.' % srna_type)

def _split_regions(chrom, start, end):
    """Split regions longer than 100kb into smaller sections.
    """
    window_size = 100000.0
    if end - start < window_size * 5:
        return [(chrom, start, end)]
    else:
        out = []
        for r in pybedtools.BedTool().window_maker(w=window_size, b=pybedtools.BedTool('%s\t%s\t%s' % (chrom, start, end), from_string=True)):
            out.append((r.chrom, r.start, r.end))
        return out

def _config_params(base_config, assoc_files, region, out_file, items):
    """Add parameters based on configuration variables, associated files and genomic regions.
    """
    params = []
    dbsnp = assoc_files.get('dbsnp')
    if dbsnp:
        params += ['--dbsnp', dbsnp]
    cosmic = assoc_files.get('cosmic')
    if cosmic:
        params += ['--cosmic', cosmic]
    variant_regions = bedutils.population_variant_regions(items)
    region = subset_variant_regions(variant_regions, region, out_file, items)
    if region:
        params += ['-L', bamprep.region_to_gatk(region), '--interval_set_rule', 'INTERSECTION']
    min_af = tz.get_in(['algorithm', 'min_allele_fraction'], base_config)
    if min_af:
        params += ['--minimum_mutation_cell_fraction', '%.2f' % (min_af / 100.0)]
    resources = config_utils.get_resources('mutect', base_config)
    if resources.get('options') is not None:
        params += [str(x) for x in resources.get('options', [])]
    if '--enable_qscore_output' not in params:
        params.append('--enable_qscore_output')
    return params

def _back_compatible_gemini(conf_files, data):
    """Provide old install directory for configuration with GEMINI supplied tidy VCFs.

    Handles new style (bcbio installed) and old style (GEMINI installed)
    configuration and data locations."""
    if vcfanno.is_human(data, builds=['37']):
        for f in conf_files:
            if f and os.path.basename(f) == 'gemini.conf' and os.path.exists(f):
                with open(f) as in_handle:
                    for line in in_handle:
                        if line.startswith('file'):
                            fname = line.strip().split('=')[-1].replace('"', '').strip()
                            if fname.find('.tidy.') > 0:
                                return install.get_gemini_dir(data)
    return None

def create_gemini_db(gemini_vcf, data, gemini_db=None, ped_file=None):
    """Generalized vcfanno/vcf2db workflow for loading variants into a GEMINI database.
    """
    if not gemini_db:
        gemini_db = '%s.db' % utils.splitext_plus(gemini_vcf)[0]
    if not vcfutils.vcf_has_variants(gemini_vcf):
        return None
    if not utils.file_exists(gemini_db):
        with file_transaction(data, gemini_db) as tx_gemini_db:
            vcf2db = config_utils.get_program('vcf2db.py', data)
            if 'vcf2db_expand' in dd.get_tools_on(data):
                vcf2db_args = ['--expand', 'gt_types', '--expand', 'gt_ref_depths', '--expand', 'gt_alt_depths']
            else:
                vcf2db_args = []
            cmd = [vcf2db, gemini_vcf, ped_file, tx_gemini_db] + vcf2db_args
            do.run(cmd, 'GEMINI: create database with vcf2db')
    return gemini_db

def get_affected_status(data):
    """Retrieve the affected/unaffected status of sample.

    Uses unaffected (1), affected (2), unknown (0) coding from PED files:

    http://pngu.mgh.harvard.edu/~purcell/plink/data.shtml#ped"""
    affected = set(['tumor', 'affected', '2'])
    unaffected = set(['normal', 'unaffected', '1'])
    phenotype = str(tz.get_in(['metadata', 'phenotype'], data, '')).lower()
    if dd.get_svclass(data) == 'control':
        return 1
    elif phenotype in affected:
        return 2
    elif phenotype in unaffected:
        return 1
    else:
        return 0

def get_gender(data):
    """Retrieve gender from metadata, codified as male/female/unknown.
    """
    g = str(dd.get_gender(data))
    if g and str(g).lower() in ['male', 'm', '1']:
        return 'male'
    elif g and str(g).lower() in ['female', 'f', '2']:
        return 'female'
    else:
        return 'unknown'

def get_ped_info(data, samples):
    """Retrieve all PED info from metadata
    """
    family_id = tz.get_in(['metadata', 'family_id'], data, None)
    if not family_id:
        family_id = _find_shared_batch(samples)
    return {'gender': {'male': 1, 'female': 2, 'unknown': 0}.get(get_gender(data)), 'individual_id': dd.get_sample_name(data), 'family_id': family_id, 'maternal_id': tz.get_in(['metadata', 'maternal_id'], data, -9), 'paternal_id': tz.get_in(['metadata', 'paternal_id'], data, -9), 'affected': get_affected_status(data), 'ethnicity': tz.get_in(['metadata', 'ethnicity'], data, -9)}

def _is_small_vcf(vcf_file):
    """Check for small VCFs which we want to analyze quicker.
    """
    count = 0
    small_thresh = 250
    with utils.open_gzipsafe(vcf_file) as in_handle:
        for line in in_handle:
            if not line.startswith('#'):
                count += 1
            if count > small_thresh:
                return False
    return True

def get_multisample_vcf(fnames, name, caller, data):
    """Retrieve a multiple sample VCF file in a standard location.

    Handles inputs with multiple repeated input files from batches."""
    unique_fnames = []
    for f in fnames:
        if f not in unique_fnames:
            unique_fnames.append(f)
    out_dir = utils.safe_makedir(os.path.join(data['dirs']['work'], 'gemini'))
    if len(unique_fnames) > 1:
        gemini_vcf = os.path.join(out_dir, '%s-%s.vcf.gz' % (name, caller))
        vrn_file_batch = None
        for variant in data.get('variants', []):
            if variant['variantcaller'] == caller and variant.get('vrn_file_batch'):
                vrn_file_batch = variant['vrn_file_batch']
        if vrn_file_batch:
            utils.symlink_plus(vrn_file_batch, gemini_vcf)
            return gemini_vcf
        else:
            return vcfutils.merge_variant_files(unique_fnames, gemini_vcf, dd.get_ref_file(data), data['config'])
    else:
        gemini_vcf = os.path.join(out_dir, '%s-%s%s' % (name, caller, utils.splitext_plus(unique_fnames[0])[1]))
        utils.symlink_plus(unique_fnames[0], gemini_vcf)
        return gemini_vcf

def _get_build_type(fnames, samples, caller):
    """Confirm we should build a gemini database: need gemini in tools_on.

    Checks for valid conditions for running a database and gemini or gemini_orig
    configured in tools on."""
    build_type = set()
    if any((vcfutils.vcf_has_variants(f) for f in fnames)) and caller not in NO_DB_CALLERS:
        for data in samples:
            if any([x in dd.get_tools_on(data) for x in ['gemini', 'gemini_orig', 'gemini_allvariants', 'vcf2db_expand']]):
                if vcfanno.annotate_gemini(data):
                    build_type.add('gemini_orig' if 'gemini_orig' in dd.get_tools_on(data) else 'gemini')
                else:
                    logger.info('Not running gemini, input data not found: %s' % dd.get_sample_name(data))
            else:
                logger.info('Not running gemini, not configured in tools_on: %s' % dd.get_sample_name(data))
    else:
        logger.info('Not running gemini, no samples with variants found: %s' % ', '.join([dd.get_sample_name(d) for d in samples]))
    return build_type

def get_gemini_files(data):
    """Enumerate available gemini data files in a standard installation.
    """
    try:
        from gemini import annotations, config
    except ImportError:
