def get_cur_batch(items):
    """Retrieve name of the batch shared between all items in a group.
    """
    batches = []
    for data in items:
        batch = tz.get_in(['metadata', 'batch'], data, [])
        batches.append(set(batch) if isinstance(batch, (list, tuple)) else set([batch]))
    combo_batches = reduce(lambda b1, b2: b1.intersection(b2), batches)
    if len(combo_batches) == 1:
        return combo_batches.pop()
    elif len(combo_batches) == 0:
        return None
    else:
        raise ValueError('Found multiple overlapping batches: %s -- %s' % (combo_batches, batches))

def calc_paired_insert_stats(in_bam, nsample=1000000):
    """Retrieve statistics for paired end read insert distances.
    """
    dists = []
    n = 0
    with pysam.Samfile(in_bam, 'rb') as in_pysam:
        for read in in_pysam:
            if read.is_proper_pair and read.is_read1:
                n += 1
                dists.append(abs(read.isize))
                if n >= nsample:
                    break
    return insert_size_stats(dists)

def calc_paired_insert_stats_save(in_bam, stat_file, nsample=1000000):
    """Calculate paired stats, saving to a file for re-runs.
    """
    if utils.file_exists(stat_file):
        with open(stat_file) as in_handle:
            return yaml.safe_load(in_handle)
    else:
        stats = calc_paired_insert_stats(in_bam, nsample)
        with open(stat_file, 'w') as out_handle:
            yaml.safe_dump(stats, out_handle, default_flow_style=False, allow_unicode=False)
        return stats

def _accumulate_remotes(synapse_parent_id, syn):
    """Retrieve references to all remote directories and files.
    """
    remotes = {}
    s_base_folder = syn.get(synapse_parent_id)
    for (s_dirpath, s_dirpath_id), _, s_filenames in synapseutils.walk(syn, synapse_parent_id):
        remotes[s_dirpath] = s_dirpath_id
        if s_filenames:
            for s_filename, s_filename_id in s_filenames:
                remotes[os.path.join(s_dirpath, s_filename)] = s_filename_id
    return (s_base_folder, remotes)

def _remote_folder(dirpath, remotes, syn):
    """Retrieve the remote folder for files, creating if necessary.
    """
    if dirpath in remotes:
        return (remotes[dirpath], remotes)
    else:
        parent_dir, cur_dir = os.path.split(dirpath)
        parent_folder, remotes = _remote_folder(parent_dir, remotes, syn)
        s_cur_dir = syn.store(synapseclient.Folder(cur_dir, parent=parent_folder))
        remotes[dirpath] = s_cur_dir.id
        return (s_cur_dir.id, remotes)

def run_region(data, region, vrn_files, out_file):
    """Perform variant calling on gVCF inputs in a specific genomic region.
    """
    broad_runner = broad.runner_from_config(data['config'])
    if broad_runner.gatk_type() == 'gatk4':
        genomics_db = _run_genomicsdb_import(vrn_files, region, out_file, data)
        return _run_genotype_gvcfs_genomicsdb(genomics_db, region, out_file, data)
    else:
        vrn_files = _batch_gvcfs(data, region, vrn_files, dd.get_ref_file(data), out_file)
        return _run_genotype_gvcfs_gatk3(data, region, vrn_files, dd.get_ref_file(data), out_file)

def _incomplete_genomicsdb(dbdir):
    """Check if a GenomicsDB output is incomplete and we should regenerate.

    Works around current inability to move GenomicsDB outputs and support
    transactional directories."""
    for test_file in ['callset.json', 'vidmap.json', 'genomicsdb_array/genomicsdb_meta.json']:
        if not os.path.exists(os.path.join(dbdir, test_file)):
            return True
    return False

def _run_genotype_gvcfs_gatk3(data, region, vrn_files, ref_file, out_file):
    """Performs genotyping of gVCFs into final VCF files.
    """
    if not utils.file_exists(out_file):
        broad_runner = broad.runner_from_config(data['config'])
        with file_transaction(data, out_file) as tx_out_file:
            assoc_files = tz.get_in(('genome_resources', 'variation'), data, {})
            if not assoc_files:
                assoc_files = {}
            params = ['-T', 'GenotypeGVCFs', '-R', ref_file, '-o', tx_out_file, '-L', bamprep.region_to_gatk(region), '--max_alternate_alleles', '4']
            for vrn_file in vrn_files:
                params += ['--variant', vrn_file]
            if assoc_files.get('dbsnp'):
                params += ['--dbsnp', assoc_files['dbsnp']]
            broad_runner.new_resources('gatk-haplotype')
            cores = dd.get_cores(data)
            if cores > 1:
                memscale = {'magnitude': 0.9 * cores, 'direction': 'increase'}
            else:
                memscale = None
            broad_runner.run_gatk(params, memscale=memscale, parallel_gc=True)
    return vcfutils.bgzip_and_index(out_file, data['config'])

def _batch_gvcfs(data, region, vrn_files, ref_file, out_file=None):
    """Perform batching of gVCF files if above recommended input count.
    """
    if out_file is None:
        out_file = vrn_files[0]
    max_batch = int(dd.get_joint_group_size(data))
    if len(vrn_files) > max_batch:
        out = []
        num_batches = int(math.ceil(float(len(vrn_files)) / max_batch))
        for i, batch_vrn_files in enumerate(tz.partition_all(num_batches, vrn_files)):
            base, ext = utils.splitext_plus(out_file)
            batch_out_file = '%s-b%s%s' % (base, i, ext)
            out.append(run_combine_gvcfs(batch_vrn_files, region, ref_file, batch_out_file, data))
        return _batch_gvcfs(data, region, out, ref_file)
    else:
        return vrn_files

def _clean_flat_variantcaller(data):
    """Convert flattened dictionary from CWL representation into dictionary.

    CWL flattens somatic/germline tags into a set of strings, which we
    reconstitute as a dictionary."""
    vc = dd.get_variantcaller(data)
    if isinstance(vc, (list, tuple)) and all([x.count(':') == 1 for x in vc]):
        out = {}
        for v in vc:
            k, v = v.split(':')
            if k in out:
                out[k].append(v)
            else:
                out[k] = [v]
        data = dd.set_variantcaller(data, out)
    return data

def extract(data, items, out_dir=None):
    """Extract germline calls for the given sample, if tumor only.
    """
    if vcfutils.get_paired_phenotype(data):
        if len(items) == 1:
            germline_vcf = _remove_prioritization(data['vrn_file'], data, out_dir)
            germline_vcf = vcfutils.bgzip_and_index(germline_vcf, data['config'])
            data['vrn_file_plus'] = {'germline': germline_vcf}
    return data

def _remove_germline_filter(rec, name):
    """Check if germline based on STATUS/SS and REJECT flag.

    Handles VarDict, FreeBayes, MuTect, MuTect2 and VarScan."""
    if _is_germline(rec):
        if rec.FILTER and name in rec.FILTER:
            return vcfutils.cyvcf_remove_filter(rec, name)
    elif not _is_somatic(rec):
        if rec.FILTER and name in rec.FILTER:
            return vcfutils.cyvcf_remove_filter(rec, name)
    return rec

def _is_somatic(rec):
    """Handle somatic classifications from MuTect, MuTect2, VarDict and VarScan
    """
    if _has_somatic_flag(rec):
        return True
    if _is_mutect2_somatic(rec):
        return True
    ss_flag = rec.INFO.get('SS')
    if ss_flag is not None:
        if str(ss_flag) == '2':
            return True
    status_flag = rec.INFO.get('STATUS')
    if status_flag is not None:
        if str(status_flag).lower() in ['somatic', 'likelysomatic', 'strongsomatic', 'samplespecific']:
            return True
    epr = rec.INFO.get('EPR', '').split(',')
    if epr and all([p == 'pass' for p in epr]):
        return True
    return False

def _is_germline(rec):
    """Handle somatic INFO classifications from MuTect, MuTect2, VarDict, VarScan and Octopus.
    """
    if _has_somatic_flag(rec):
        return False
    if _is_mutect2_somatic(rec):
        return False
    ss_flag = rec.INFO.get('SS')
    if ss_flag is not None:
        if str(ss_flag) == '1':
            return True
    pp = rec.INFO.get('PP')
    if pp and float(pp) / float(rec.QUAL) >= 0.5:
        return True
    status_flag = rec.INFO.get('STATUS')
    if status_flag is not None:
        if str(status_flag).lower() in ['germline', 'likelyloh', 'strongloh', 'afdiff', 'deletion']:
            return True
    return False

def check_bed_contigs(in_file, data):
    """Ensure BED file contigs match the reference genome.
    """
    if not dd.get_ref_file(data):
        return
    contigs = set([])
    with utils.open_gzipsafe(in_file) as in_handle:
        for line in in_handle:
            if not line.startswith(('#', 'track', 'browser', '@')) and line.strip():
                contigs.add(line.split()[0])
    ref_contigs = set([x.name for x in ref.file_contigs(dd.get_ref_file(data))])
    if contigs and len(contigs - ref_contigs) / float(len(contigs)) > 0.25:
        raise ValueError('Contigs in BED file %s not in reference genome:\n %s\n' % (in_file, list(contigs - ref_contigs)) + 'This is typically due to chr1 versus 1 differences in BED file and reference.')

def check_bed_coords(in_file, data):
    """Ensure BED file coordinates match reference genome.

    Catches errors like using a hg38 BED file for an hg19 genome run."""
    if dd.get_ref_file(data):
        contig_sizes = {}
        for contig in ref.file_contigs(dd.get_ref_file(data)):
            contig_sizes[contig.name] = contig.size
        with utils.open_gzipsafe(in_file) as in_handle:
            for line in in_handle:
                if not line.startswith(('#', 'track', 'browser', '@')) and line.strip():
                    parts = line.split()
                    if len(parts) > 3:
                        try:
                            end = int(parts[2])
                        except ValueError:
                            continue
                        contig = parts[0]
                        check_size = contig_sizes.get(contig)
                        if check_size and end > check_size:
                            raise ValueError('Found BED coordinate off the end of the chromosome:\n%s%s\nIs the input BED from the right genome build?' % (line, in_file))

def remove_bad():
    """Remove non-increasing BED lines which will cause variant callers to choke.

    Also fixes space separated BED inputs."""
    for line in sys.stdin:
        parts = line.strip().split('\t')
        if len(parts) == 1 and len(line.strip().split()) > 1:
            parts = line.strip().split()
        if line.strip() and len(parts) > 2 and (int(parts[2]) > int(parts[1])):
            sys.stdout.write('\t'.join(parts) + '\n')

def population_variant_regions(items, merged=False):
    """Retrieve the variant region BED file from a population of items.

    If tumor/normal, return the tumor BED file. If a population, return
    the BED file covering the most bases."""
    def _get_variant_regions(data):
        out = dd.get_variant_regions(data) or dd.get_sample_callable(data)
        if merged and dd.get_variant_regions(data):
            merged_out = dd.get_variant_regions_merged(data)
            if merged_out:
                out = merged_out
            else:
                out = merge_overlaps(out, data)
        return out
    import pybedtools
    if len(items) == 1:
        return _get_variant_regions(items[0])
    else:
        paired = vcfutils.get_paired(items)
        if paired:
            return _get_variant_regions(paired.tumor_data)
        else:
            vrs = []
            for data in items:
                vr_bed = _get_variant_regions(data)
                if vr_bed:
                    vrs.append((pybedtools.BedTool(vr_bed).total_coverage(), vr_bed))
            vrs.sort(reverse=True)
            if vrs:
                return vrs[0][1]

def combine(in_files, out_file, config):
    """Combine multiple BED files into a single output.
    """
    if not utils.file_exists(out_file):
        with file_transaction(config, out_file) as tx_out_file:
            with open(tx_out_file, 'w') as out_handle:
                for in_file in in_files:
                    with open(in_file) as in_handle:
                        shutil.copyfileobj(in_handle, out_handle)
    return out_file

def intersect_two(f1, f2, work_dir, data):
    """Intersect two regions, handling cases where either file is not present.
    """
    bedtools = config_utils.get_program('bedtools', data, default='bedtools')
    f1_exists = f1 and utils.file_exists(f1)
    f2_exists = f2 and utils.file_exists(f2)
    if not f1_exists and (not f2_exists):
        return None
    elif f1_exists and (not f2_exists):
        return f1
    elif f2_exists and (not f1_exists):
        return f2
    else:
        out_file = os.path.join(work_dir, '%s-merged.bed' % utils.splitext_plus(os.path.basename(f1))[0])
        if not utils.file_exists(out_file):
            with file_transaction(data, out_file) as tx_out_file:
                cmd = '{bedtools} intersect -a {f1} -b {f2} > {tx_out_file}'
                do.run(cmd.format(**locals()), 'Intersect BED files', data)
        return out_file

def subset_to_genome(in_file, out_file, data):
    """Subset a BED file to only contain contigs present in the reference genome.
    """
    if not utils.file_uptodate(out_file, in_file):
        contigs = set([x.name for x in ref.file_contigs(dd.get_ref_file(data))])
        with utils.open_gzipsafe(in_file) as in_handle:
            with file_transaction(data, out_file) as tx_out_file:
                with open(tx_out_file, 'w') as out_handle:
                    for line in in_handle:
                        parts = line.split()
                        if parts and parts[0] in contigs:
                            out_handle.write(line)
    return out_file

def run(align_bams, items, ref_file, assoc_files, region, out_file):
    """Run octopus variant calling, handling both somatic and germline calling.
    """
    if not utils.file_exists(out_file):
        paired = vcfutils.get_paired_bams(align_bams, items)
        vrs = bedutils.population_variant_regions(items)
        target = shared.subset_variant_regions(vrs, region, out_file, items=items, do_merge=True)
        if paired:
            return _run_somatic(paired, ref_file, target, out_file)
        else:
            return _run_germline(align_bams, items, ref_file, target, out_file)
    return out_file

def _covert_to_diploid(in_file, data):
    """Converts non-diploid somatic outputs into diploid.

    https://github.com/luntergroup/octopus/wiki/Case-study:-Tumour-only-UMI#evaluate-variant-calls"""
    sample = dd.get_sample_name(data)
    out_file = '%s-diploid.vcf' % utils.splitext_plus(in_file)[0]
    in_vcf = pysam.VariantFile(in_file)
    out_vcf = pysam.VariantFile(out_file, 'w', header=in_vcf.header)
    for record in in_vcf:
        gt = list(record.samples[sample]['GT'])
        if 'SOMATIC' in record.info:
            for allele in set(gt):
                if allele != gt[0]:
                    record.samples[sample]['GT'] = (gt[0], allele)
                    out_vcf.write(record)
        else:
            if len(gt) == 1:
                record.samples[sample]['GT'] = gt
            else:
                record.samples[sample]['GT'] = (gt[0], gt[1])
            out_vcf.write(record)
    in_vcf.close()
    out_vcf.close()
    return vcfutils.bgzip_and_index(out_file, data['config'])

def _upload_file_aws_cli(local_fname, bucket, keyname, config=None, mditems=None):
    """Streaming upload via the standard AWS command line interface.
    """
    s3_fname = 's3://%s/%s' % (bucket, keyname)
    args = ['--sse', '--expected-size', str(os.path.getsize(local_fname))]
    if config:
        if config.get('region'):
            args += ['--region', config.get('region')]
        if config.get('reduced_redundancy'):
            args += ['--storage-class', 'REDUCED_REDUNDANCY']
    cmd = [os.path.join(os.path.dirname(sys.executable), 'aws'), 's3', 'cp'] + args + [local_fname, s3_fname]
    do.run(cmd, 'Upload to s3: %s %s' % (bucket, keyname))

def upload_file_boto(fname, remote_fname, mditems=None):
    """Upload a file using boto instead of external tools.
    """
    r_fname = objectstore.parse_remote(remote_fname)
    conn = objectstore.connect(remote_fname)
    bucket = conn.lookup(r_fname.bucket)
    if not bucket:
        bucket = conn.create_bucket(r_fname.bucket, location=objectstore.get_region(remote_fname))
    key = bucket.get_key(r_fname.key, validate=False)
    if mditems is None:
        mditems = {}
    if 'x-amz-server-side-encryption' not in mditems:
        mditems['x-amz-server-side-encryption'] = 'AES256'
    for name, val in mditems.items():
        key.set_metadata(name, val)
    key.set_contents_from_filename(fname, encrypt_key=True)

def run(bam_file, sample, out_dir):
    """Standard QC metrics for chipseq"""
    out = {}
    peaks = sample.get('peaks_files', {}).get('main')
    if peaks:
        out.update(_reads_in_peaks(bam_file, peaks, sample))
    return out

def _reads_in_peaks(bam_file, peaks_file, sample):
    """Calculate number of reads in peaks"""
    if not peaks_file:
        return {}
    rip = number_of_mapped_reads(sample, bam_file, bed_file=peaks_file)
    return {'metrics': {'RiP': rip}}

def chipqc(bam_file, sample, out_dir):
    """Attempt code to run ChIPQC bioconductor packate in one sample"""
    sample_name = dd.get_sample_name(sample)
    logger.warning('ChIPQC is unstable right now, if it breaks, turn off the tool.')
    if utils.file_exists(out_dir):
        return _get_output(out_dir)
    with tx_tmpdir() as tmp_dir:
        rcode = _sample_template(sample, tmp_dir)
        if rcode:
            rscript = utils.Rscript_cmd()
            do.run([rscript, '--no-environ', rcode], 'ChIPQC in %s' % sample_name, log_error=False)
            shutil.move(tmp_dir, out_dir)
    return _get_output(out_dir)

def _strand_flag(data):
    """0: unstranded 1: stranded 2: reverse stranded"""
    strand_flag = {'unstranded': '0', 'firststrand': '2', 'secondstrand': '1'}
    stranded = dd.get_strandedness(data)
    assert stranded in strand_flag, "%s is not a valid strandedness value. Valid values are 'firststrand', 'secondstrand', and 'unstranded"
    return strand_flag[stranded]

def run_qc(_, data, out_dir):
    """Run quality control in QC environment on a single sample.

    Enables peddy integration with CWL runs."""
    if cwlutils.is_cwl_run(data):
        qc_data = run_peddy([data], out_dir)
        if tz.get_in(['summary', 'qc', 'peddy'], qc_data):
            return tz.get_in(['summary', 'qc', 'peddy'], qc_data)

def _macs2_cmd(method='chip'):
    """Main command for macs2 tool."""
    if method.lower() == 'chip':
        cmd = '{macs2} callpeak -t {chip_bam} -c {input_bam} {paired}  {genome_size} -n {name} -B {options}'
    elif method.lower() == 'atac':
        cmd = '{macs2} callpeak -t {chip_bam} --nomodel  {paired} {genome_size} -n {name} -B {options} --nolambda --keep-dup all'
    else:
        raise ValueError('chip_method should be chip or atac.')
    return cmd

def compress(samples, run_parallel):
    """Perform compression of output files for long term storage.
    """
    to_cram = []
    finished = []
    for data in [x[0] for x in samples]:
        if 'cram' in dd.get_archive(data) or 'cram-lossless' in dd.get_archive(data):
            to_cram.append([data])
        else:
            finished.append([data])
    crammed = run_parallel('archive_to_cram', to_cram)
    return finished + crammed

def _descr_str(descr, data, region):
    """Add additional useful information from data to description string.
    """
    if data:
        name = dd.get_sample_name(data)
        if name:
            descr = '{0} : {1}'.format(descr, name)
        elif 'work_bam' in data:
            descr = '{0} : {1}'.format(descr, os.path.basename(data['work_bam']))
    if region:
        descr = '{0} : {1}'.format(descr, region)
    return descr

def _normalize_cmd_args(cmd):
    """Normalize subprocess arguments to handle list commands, string and pipes.
    Piped commands set pipefail and require use of bash to help with debugging
    intermediate errors."""
    if isinstance(cmd, six.string_types):
        if cmd.find(' | ') > 0 or cmd.find('>(') or cmd.find('<('):
            return ('set -o pipefail; ' + cmd, True, find_bash())
        else:
            return (cmd, True, None)
    else:
        return ([str(x) for x in cmd], False, None)

def somatic_batches(items):
    """Group items into somatic calling batches (tumor-only or tumor/normal).

    Returns batches, where a data item may be in pairs, and somatic and non_somatic
    (which are the original list of items)."""
    non_somatic = []
    somatic = []
    data_by_batches = defaultdict(list)
    for data in items:
        if not get_paired_phenotype(data):
            non_somatic.append(data)
        else:
            somatic.append(data)
            batches = dd.get_batches(data)
            if batches:
                for batch in batches:
                    data_by_batches[batch].append(data)
    return (data_by_batches.values(), somatic, non_somatic)

def get_paired_bams(align_bams, items):
    """Split aligned bams into tumor / normal pairs if this is a paired analysis.
    Allows cases with only tumor BAMs to handle callers that can work without
    normal BAMs or with normal VCF panels."""
    tumor_bam, tumor_name, normal_bam, normal_name, normal_panel, tumor_config, normal_data = (None,) * 7
    for bamfile, item in zip(align_bams, items):
        phenotype = get_paired_phenotype(item)
        if phenotype == 'normal':
            normal_bam = bamfile
            normal_name = dd.get_sample_name(item)
            normal_data = item
        elif phenotype == 'tumor':
            tumor_bam = bamfile
            tumor_name = dd.get_sample_name(item)
            tumor_data = item
            tumor_config = item['config']
            normal_panel = dd.get_background_variant(item)
    if tumor_bam or tumor_name:
        return PairedData(tumor_bam, tumor_name, normal_bam, normal_name, normal_panel, tumor_config, tumor_data, normal_data)

def check_paired_problems(items):
    """Check for incorrectly paired tumor/normal samples in a batch.
    """
    if not get_paired(items):
        return
    num_tumor = len([x for x in items if dd.get_phenotype(x).lower() == 'tumor'])
    if num_tumor > 1:
        raise ValueError('Unsupported configuration: found multiple tumor samples in batch %s: %s' % (tz.get_in(['metadata', 'batch'], items[0]), [dd.get_sample_name(data) for data in items]))
    elif num_tumor == 0 and any((dd.get_phenotype(data).lower() == 'normal' for data in items)):
        raise ValueError('Found normal sample without tumor in batch %s: %s' % (tz.get_in(['metadata', 'batch'], items[0]), [dd.get_sample_name(data) for data in items]))
    else:
        vcs = get_somatic_variantcallers(items)
        if 'mutect' in vcs or 'mutect2' in vcs or 'strelka2' in vcs:
            paired = get_paired(items)
            if not (paired.normal_data or paired.normal_panel):
                raise ValueError('MuTect, MuTect2 and Strelka2 somatic calling requires normal sample or panel: %s' % [dd.get_sample_name(data) for data in items])

def get_indelcaller(d_or_c):
    """Retrieve string for indelcaller to use, or empty string if not specified.
    """
    config = d_or_c if isinstance(d_or_c, dict) and 'config' in d_or_c else d_or_c
    indelcaller = config['algorithm'].get('indelcaller', '')
    if not indelcaller:
        indelcaller = ''
    if isinstance(indelcaller, (list, tuple)):
        indelcaller = indelcaller[0] if len(indelcaller) > 0 else ''
    return indelcaller

def split_snps_indels(orig_file, ref_file, config):
    """Split a variant call file into SNPs and INDELs for processing.
    """
    base, ext = utils.splitext_plus(orig_file)
    snp_file = '{base}-snp{ext}'.format(base=base, ext=ext)
    indel_file = '{base}-indel{ext}'.format(base=base, ext=ext)
    for out_file, select_arg in [(snp_file, '--types snps'), (indel_file, '--exclude-types snps')]:
        if not utils.file_exists(out_file):
            with file_transaction(config, out_file) as tx_out_file:
                bcftools = config_utils.get_program('bcftools', config)
                output_type = 'z' if out_file.endswith('.gz') else 'v'
                cmd = '{bcftools} view -O {output_type} {orig_file} {select_arg} > {tx_out_file}'
                do.run(cmd.format(**locals()), 'Subset to SNPs and indels')
        if out_file.endswith('.gz'):
            bgzip_and_index(out_file, config)
    return (snp_file, indel_file)

def get_normal_sample(in_file):
    """Retrieve normal sample if normal/turmor
    """
    with utils.open_gzipsafe(in_file) as in_handle:
        for line in in_handle:
            if line.startswith('##PEDIGREE'):
                parts = line.strip().split('Original=')[1][:-1]
                return parts

def get_samples(in_file):
    """Retrieve samples present in a VCF file
    """
    with utils.open_gzipsafe(in_file) as in_handle:
        for line in in_handle:
            if line.startswith('#CHROM'):
                parts = line.strip().split('\t')
                return parts[9:]
    raise ValueError('Did not find sample header in VCF file %s' % in_file)

def _get_exclude_samples(in_file, to_exclude):
    """Identify samples in the exclusion list which are actually in the VCF.
    """
    include, exclude = ([], [])
    to_exclude = set(to_exclude)
    for s in get_samples(in_file):
        if s in to_exclude:
            exclude.append(s)
        else:
            include.append(s)
    return (include, exclude)

def select_sample(in_file, sample, out_file, config, filters=None):
    """Select a single sample from the supplied multisample VCF file.
    """
    if not utils.file_exists(out_file):
        with file_transaction(config, out_file) as tx_out_file:
            if len(get_samples(in_file)) == 1:
                shutil.copy(in_file, tx_out_file)
            else:
                if in_file.endswith('.gz'):
                    bgzip_and_index(in_file, config)
                bcftools = config_utils.get_program('bcftools', config)
                output_type = 'z' if out_file.endswith('.gz') else 'v'
                filter_str = '-f %s' % filters if filters is not None else ''
                cmd = '{bcftools} view -O {output_type} {filter_str} {in_file} -s {sample} > {tx_out_file}'
                do.run(cmd.format(**locals()), 'Select sample: %s' % sample)
    if out_file.endswith('.gz'):
        bgzip_and_index(out_file, config)
    return out_file

def _check_samples_nodups(fnames):
    """Ensure a set of input VCFs do not have duplicate samples.
    """
    counts = defaultdict(int)
    for f in fnames:
        for s in get_samples(f):
            counts[s] += 1
    duplicates = [s for s, c in counts.items() if c > 1]
    if duplicates:
        raise ValueError('Duplicate samples found in inputs %s: %s' % (duplicates, fnames))

def _sort_by_region(fnames, regions, ref_file, config):
    """Sort a set of regionally split files by region for ordered output.
    """
    contig_order = {}
    for i, sq in enumerate(ref.file_contigs(ref_file, config)):
        contig_order[sq.name] = i
    sitems = []
    assert len(regions) == len(fnames), (regions, fnames)
    added_fnames = set([])
    for region, fname in zip(regions, fnames):
        if fname not in added_fnames:
            if isinstance(region, (list, tuple)):
                c, s, e = region
            elif isinstance(region, six.string_types) and region.find(':') >= 0:
                c, coords = region.split(':')
                s, e = [int(x) for x in coords.split('-')]
            else:
                c = region
                s, e = (0, 0)
            sitems.append(((contig_order[c], s, e), c, fname))
            added_fnames.add(fname)
    sitems.sort()
    return [(x[1], x[2]) for x in sitems]

def concat_variant_files(orig_files, out_file, regions, ref_file, config):
    """Concatenate multiple variant files from regions into a single output file.

    Uses GATK4's GatherVcfs, falling back to bcftools concat --naive if it fails.
    These both only combine samples and avoid parsing, allowing scaling to large
    file sizes."""
    if not utils.file_exists(out_file):
        input_file_list = _get_file_list(orig_files, out_file, regions, ref_file, config)
        try:
            out_file = _run_concat_variant_files_gatk4(input_file_list, out_file, config)
        except subprocess.CalledProcessError as msg:
            if 'We require all VCFs to have complete VCF headers' in str(msg) or 'Features added out of order' in str(msg) or 'The reference allele cannot be missing' in str(msg):
                out_file = _run_concat_variant_files_bcftools(input_file_list, out_file, config, naive=True)
            else:
                raise
    if out_file.endswith('.gz'):
        bgzip_and_index(out_file, config)
    return out_file

def _run_concat_variant_files_bcftools(in_list, out_file, config, naive=False):
    """Concatenate variant files using bcftools concat, potentially using the fast naive option.
    """
    if not utils.file_exists(out_file):
        with file_transaction(config, out_file) as tx_out_file:
            bcftools = config_utils.get_program('bcftools', config)
            output_type = 'z' if out_file.endswith('.gz') else 'v'
            if naive:
                args = '--naive'
            else:
                args = '--allow-overlaps'
            cmd = '{bcftools} concat {args} -O {output_type} --file-list {in_list} -o {tx_out_file}'
            do.run(cmd.format(**locals()), 'bcftools concat variants')
    if out_file.endswith('.gz'):
        bgzip_and_index(out_file, config)
    return out_file

def add_contig_to_header(line, ref_file):
    """Streaming target to add contigs to a VCF file header.
    """
    if line.startswith('##fileformat=VCF'):
        out = [line]
        for region in ref.file_contigs(ref_file):
            out.append('##contig=<ID=%s,length=%s>' % (region.name, region.size))
        return '\n'.join(out)
    else:
        return line

def move_vcf(orig_file, new_file):
    """Move a VCF file with associated index.
    """
    for ext in ['', '.idx', '.tbi']:
        to_move = orig_file + ext
        if os.path.exists(to_move):
            shutil.move(to_move, new_file + ext)

def cyvcf_add_filter(rec, name):
    """Add a FILTER value to a cyvcf2 record
    """
    if rec.FILTER:
        filters = rec.FILTER.split(';')
    else:
        filters = []
    if name not in filters:
        filters.append(name)
        rec.FILTER = filters
    return rec

def cyvcf_remove_filter(rec, name):
    """Remove filter with the given name from a cyvcf2 record
    """
    if rec.FILTER:
        filters = rec.FILTER.split(';')
    else:
        filters = []
    new_filters = [x for x in filters if not str(x) == name]
    if len(new_filters) == 0:
        new_filters = ['PASS']
    rec.FILTER = new_filters
    return rec

def align_to_sort_bam(fastq1, fastq2, aligner, data):
    """Align to the named genome build, returning a sorted BAM file.
    """
    names = data['rgnames']
    align_dir_parts = [data['dirs']['work'], 'align', names['sample']]
    if data.get('disambiguate'):
        align_dir_parts.append(data['disambiguate']['genome_build'])
    aligner_index = _get_aligner_index(aligner, data)
    align_dir = utils.safe_makedir(os.path.join(*align_dir_parts))
    ref_file = tz.get_in(('reference', 'fasta', 'base'), data)
    if fastq1.endswith('.bam'):
        data = _align_from_bam(fastq1, aligner, aligner_index, ref_file, names, align_dir, data)
    else:
        data = _align_from_fastq(fastq1, fastq2, aligner, aligner_index, ref_file, names, align_dir, data)
    if data['work_bam'] and utils.file_exists(data['work_bam']):
        if data.get('align_split') and dd.get_mark_duplicates(data):
            bam.fake_index(data['work_bam'], data)
        else:
            bam.index(data['work_bam'], data['config'])
        for extra in ['-sr', '-disc']:
            extra_bam = utils.append_stem(data['work_bam'], extra)
            if utils.file_exists(extra_bam):
                bam.index(extra_bam, data['config'])
    return data

def get_aligner_with_aliases(aligner, data):
    """Retrieve aligner index retriever, including aliases for shared.

    Handles tricky cases like gridss where we need bwa indices even with
    no aligner specified since they're used internally within GRIDSS."""
    aligner_aliases = {'sentieon-bwa': 'bwa'}
    from bcbio import structural
    if not aligner and 'gridss' in structural.get_svcallers(data):
        aligner = 'bwa'
    return aligner_aliases.get(aligner) or aligner

def _get_aligner_index(aligner, data):
    """Handle multiple specifications of aligner indexes, returning value to pass to aligner.

    Original bcbio case -- a list of indices.
    CWL case: a single file with secondaryFiles staged in the same directory."""
    aligner_indexes = tz.get_in(('reference', get_aligner_with_aliases(aligner, data), 'indexes'), data)
    if aligner_indexes and isinstance(aligner_indexes, (list, tuple)):
        aligner_index = os.path.commonprefix(aligner_indexes)
        if aligner_index.endswith('.'):
            aligner_index = aligner_index[:-1]
        return aligner_index
    elif aligner_indexes and os.path.exists(aligner_indexes):
        aligner_dir = os.path.dirname(aligner_indexes)
        aligner_prefix = os.path.splitext(aligner_indexes)[0]
        if len(glob.glob('%s.*' % aligner_prefix)) > 0:
            return aligner_prefix
        else:
            return aligner_dir
    if aligner not in allow_noindices():
        raise ValueError('Did not find reference indices for aligner %s in genome: %s' % (aligner, data['reference']))

def _add_versions(samples):
    """Add tool and data versions to the summary.
    """
    samples[0]['versions'] = {'tools': programs.write_versions(samples[0]['dirs'], samples[0]['config']), 'data': provenancedata.write_versions(samples[0]['dirs'], samples)}
    return samples

def _save_uploaded_file_list(samples, file_list_work, out_dir):
    """Fixes all absolute work-rooted paths to relative final-rooted paths

    For CWL, prepare paths relative to output directory."""
    if not utils.file_exists(file_list_work):
        return None
    if any([cwlutils.is_cwl_run(d) for d in samples]):
        upload_paths = []
        with open(file_list_work) as f:
            for p in (l.strip() for l in f.readlines() if os.path.exists(l.strip())):
                if p.startswith(out_dir):
                    upload_paths.append(p.replace(out_dir + '/', ''))
    else:
        upload_path_mapping = dict()
        for sample in samples:
            upload_path_mapping.update(get_all_upload_paths_from_sample(sample))
        if not upload_path_mapping:
            return None
        with open(file_list_work) as f:
            paths = [l.strip() for l in f.readlines() if os.path.exists(l.strip())]
        upload_paths = [p for p in [_work_path_to_rel_final_path(path, upload_path_mapping, samples[0]['upload']['dir']) for path in paths] if p]
        if not upload_paths:
            return None
    file_list_final = os.path.join(out_dir, 'list_files_final.txt')
    with open(file_list_final, 'w') as f:
        for path in upload_paths:
            f.write(path + '\n')
    return file_list_final

def _work_path_to_rel_final_path(path, upload_path_mapping, upload_base_dir):
    """Check if `path` is a work-rooted path, and convert to a relative final-rooted path
    """
    if not path or not isinstance(path, str):
        return path
    upload_path = None
    if upload_path_mapping.get(path) is not None and os.path.isfile(path):
        upload_path = upload_path_mapping[path]
    else:
        paths_to_check = [key for key in upload_path_mapping if path.startswith(key)]
        if paths_to_check:
            for work_path in paths_to_check:
                if os.path.isdir(work_path):
                    final_path = upload_path_mapping[work_path]
                    upload_path = path.replace(work_path, final_path)
                    break
    if upload_path is not None:
        return os.path.relpath(upload_path, upload_base_dir)
    else:
        return None

def _one_exists(input_files):
    """at least one file must exist for multiqc to run properly"""
    for f in input_files:
        if os.path.exists(f):
            return True
    return False

def _has_bcftools_germline_stats(data):
    """Check for the presence of a germline stats file, CWL compatible.
    """
    stats_file = tz.get_in(['summary', 'qc'], data)
    if isinstance(stats_file, dict):
        stats_file = tz.get_in(['variants', 'base'], stats_file)
    if not stats_file:
        stats_file = ''
    return stats_file.find('bcftools_stats_germline') > 0

def _is_good_file_for_multiqc(fpath):
    """Returns False if the file is binary or image."""
    ftype, encoding = mimetypes.guess_type(fpath)
    if encoding is not None:
        return False
    if ftype is not None and ftype.startswith('image'):
        return False
    return True

def _parse_disambiguate(disambiguatestatsfilename):
    """Parse disambiguation stats from given file.
    """
    disambig_stats = [0, 0, 0]
    with open(disambiguatestatsfilename, 'r') as in_handle:
        for i, line in enumerate(in_handle):
            fields = line.strip().split('\t')
            if i == 0:
                assert fields == ['sample', 'unique species A pairs', 'unique species B pairs', 'ambiguous pairs']
            else:
                disambig_stats = [x + int(y) for x, y in zip(disambig_stats, fields[1:])]
    return disambig_stats

def _merge_fastqc(samples):
    """merge all fastqc samples into one by module"""
    fastqc_list = collections.defaultdict(list)
    seen = set()
    for data in samples:
        name = dd.get_sample_name(data)
        if name in seen:
            continue
        seen.add(name)
        fns = glob.glob(os.path.join(dd.get_work_dir(data), 'qc', dd.get_sample_name(data), 'fastqc') + '/*')
        for fn in fns:
            if fn.endswith('tsv'):
                metric = os.path.basename(fn)
                fastqc_list[metric].append([name, fn])
    for metric in fastqc_list:
        dt_by_sample = []
        for fn in fastqc_list[metric]:
            dt = pd.read_csv(fn[1], sep='\t')
            dt['sample'] = fn[0]
            dt_by_sample.append(dt)
        dt = utils.rbind(dt_by_sample)
        dt.to_csv(metric, sep='\t', index=False, mode='w')
    return samples

def _get_cromwell_execution_dir(base_dir, target_glob):
    """Retrieve the baseline directory with cromwell output files.

    Handles Cromwell restarts where there are multiple work directories and
    we traverse symlinks back to the original."""
    cur_dir = glob.glob(os.path.join(base_dir, target_glob))[0]
    if os.path.exists(os.path.join(cur_dir, 'cwl.output.json')):
        return base_dir
    else:
        symlink_dir = os.path.dirname(os.path.realpath(os.path.join(cur_dir, 'script')))
        ref_base = os.path.dirname(base_dir)
        new_guid = symlink_dir[symlink_dir.find(ref_base) + len(ref_base) + 1:].split('/')[0]
        return _get_cromwell_execution_dir(os.path.join(ref_base, new_guid), target_glob)

def prep_bam_inputs(out_dir, sample, call_file, bam_file):
    """Prepare expected input BAM files from pre-aligned.
    """
    base = utils.splitext_plus(os.path.basename(bam_file))[0]
    with open(call_file) as in_handle:
        for cur_hla in (x.strip() for x in in_handle):
            out_file = os.path.join(utils.safe_makedir(os.path.join(out_dir, base)), '%s.type.%s.filtered.bam' % (base, cur_hla))
            if not os.path.exists(out_file):
                cmd = ['samtools', 'view', '-b', '-o', out_file, bam_file, cur_hla]
                subprocess.check_call(cmd)

def get_hla_choice(h, hlas, normal_bam, tumor_bam):
    """Retrieve matching HLA with best read support in both tumor and normal
    """
    def get_counts(bam_file):
        counts = {}
        for line in subprocess.check_output(['samtools', 'idxstats', bam_file]).split('\n'):
            if line.startswith(h):
                name, _, count, _ = line.split()
                counts[name] = int(count)
        return counts
    tcounts = get_counts(tumor_bam)
    ncounts = get_counts(normal_bam)
    check_hlas = [x for x in hlas if x.startswith(h) and tcounts.get(x, 0) > 0 and (ncounts.get(x, 0) > 0)]
    cur_hlas = sorted(check_hlas, key=lambda x: ncounts[x], reverse=True)
    return cur_hlas[0]

def run(vrn_info, cnvs_by_name, somatic_info):
    """Run THetA analysis given output from CNV caller on a tumor/normal pair.
    """
    cmd = _get_cmd('RunTHeTA.py')
    if not cmd:
        logger.info('THetA scripts not found in current PATH. Skipping.')
    else:
        from bcbio.structural import cnvkit
        work_dir = _sv_workdir(somatic_info.tumor_data)
        assert 'cnvkit' in cnvs_by_name, 'THetA requires CNVkit calls'
        cnv_info = cnvkit.export_theta(cnvs_by_name['cnvkit'], somatic_info.tumor_data)
        cnv_info['theta_input'] = subset_by_supported(cnv_info['theta_input'], _theta_to_coords, cnvs_by_name, work_dir, somatic_info.tumor_data)
        return _run_theta(cnv_info, somatic_info.tumor_data, work_dir, run_n3=False)

def _select_model(n2_bounds, n2_result, n3_result, out_dir, data):
    """Run final model selection from n=2 and n=3 options.
    """
    n2_out_file = n2_result.replace('.n2.results', '.BEST.results')
    n3_out_file = n3_result.replace('.n3.results', '.BEST.results')
    if not utils.file_exists(n2_out_file) and (not utils.file_exists(n3_out_file)):
        cmd = _get_cmd('ModelSelection.py') + [n2_bounds, n2_result, n3_result]
        do.run(cmd, 'Select best THetA model')
    if utils.file_exists(n2_out_file):
        return n2_out_file
    else:
        assert utils.file_exists(n3_out_file)
        return n3_out_file

def _safe_run_theta(input_file, out_dir, output_ext, args, data):
    """Run THetA, catching and continuing on any errors.
    """
    out_file = os.path.join(out_dir, _split_theta_ext(input_file) + output_ext)
    skip_file = out_file + '.skipped'
    if utils.file_exists(skip_file):
        return None
    if not utils.file_exists(out_file):
        with file_transaction(data, out_dir) as tx_out_dir:
            utils.safe_makedir(tx_out_dir)
            cmd = _get_cmd('RunTHetA.py') + args + [input_file, '--NUM_PROCESSES', dd.get_cores(data), '--FORCE', '-d', tx_out_dir]
            try:
                do.run(cmd, 'Run THetA to calculate purity', log_error=False)
            except subprocess.CalledProcessError as msg:
                if 'Number of intervals must be greater than 1' in str(msg) or "This sample isn't a good candidate for THetA analysis" in str(msg):
                    with open(os.path.join(tx_out_dir, os.path.basename(skip_file)), 'w') as out_handle:
                        out_handle.write('Expected TheTA failure, skipping')
                    return None
                else:
                    raise
    return out_file

def _get_cmd(cmd):
    """Retrieve required commands for running THetA with our local bcbio python.
    """
    check_cmd = 'RunTHetA.py'
    try:
        local_cmd = subprocess.check_output(['which', check_cmd]).strip()
    except subprocess.CalledProcessError:
        return None
    return [sys.executable, '%s/%s' % (os.path.dirname(os.path.realpath(local_cmd)), cmd)]

def _find_lib(data):
    """Find mirge libs"""
    options = ' '.join(data.get('resources', {}).get('mirge', {}).get('options', ''))
    if options.find('-lib') > -1 and utils.file_exists(options.split()[1]):
        return options
    if not options:
        logger.warning('miRge libraries not found. Follow these instructions to install them:')
        logger.warning('https://github.com/mhalushka/miRge#download-libraries')
        logger.warning('Then, pass -lib LIB_PATH with resourcces:mirge:options:[...]')
        logger.warning('More information: https://bcbio-nextgen.readthedocs.io/en/latest/contents/pipelines.html#smallrna-seq')

def get_input_sequence_files(data, default=None):
    """returns the input sequencing files, these can be single or paired FASTQ
    files or BAM files"""
    if 'files' not in data or data.get('files') is None:
        file1, file2 = (None, None)
    elif len(data['files']) == 2:
        file1, file2 = data['files']
    else:
        assert len(data['files']) == 1, data['files']
        file1, file2 = (data['files'][0], None)
    return (file1, file2)

def get_dexseq_gff(config, default=None):
    """some older versions of the genomes have the DEXseq gff file as
    gff instead of gff3, so this handles that by looking for either one"""
    dexseq_gff = tz.get_in(tz.get_in(['dexseq_gff', 'keys'], LOOKUPS, {}), config, None)
    if not dexseq_gff:
        return None
    gtf_file = get_gtf_file(config)
    if gtf_file:
        base_dir = os.path.dirname(gtf_file)
    else:
        base_dir = os.path.dirname(dexseq_gff)
    base, _ = os.path.splitext(dexseq_gff)
    gff_file = os.path.join(base_dir, base + '.gff')
    if file_exists(gff_file):
        return gff_file
    gtf_file = os.path.join(base_dir, base + '.gff3')
    if file_exists(gtf_file):
        return gtf_file
    else:
        return None

def get_in_samples(samples, fn):
    """for a list of samples, return the value of a global option"""
    for sample in samples:
        sample = to_single_data(sample)
        if fn(sample, None):
            return fn(sample)
    return None

def update_summary_qc(data, key, base=None, secondary=None):
    """updates summary_qc with a new section, keyed by key.
    stick files into summary_qc if you want them propagated forward
    and available for multiqc"""
    summary = get_summary_qc(data, {})
    if base and secondary:
        summary[key] = {'base': base, 'secondary': secondary}
    elif base:
        summary[key] = {'base': base}
    elif secondary:
        summary[key] = {'secondary': secondary}
    data = set_summary_qc(data, summary)
    return data

def estimate_library_complexity(df, algorithm='RNA-seq'):
    """estimate library complexity from the number of reads vs.
    number of unique start sites. returns "NA" if there are
    not enough data points to fit the line"""
    DEFAULT_CUTOFFS = {'RNA-seq': (0.25, 0.4)}
    cutoffs = DEFAULT_CUTOFFS[algorithm]
    if len(df) < 5:
        return {'unique_starts_per_read': 'nan', 'complexity': 'NA'}
    model = sm.ols(formula='starts ~ reads', data=df)
    fitted = model.fit()
    slope = fitted.params['reads']
    if slope <= cutoffs[0]:
        complexity = 'LOW'
    elif slope <= cutoffs[1]:
        complexity = 'MEDIUM'
    else:
        complexity = 'HIGH'
    return {'Unique Starts Per Read': float(slope)}

def _target_chroms_and_header(bam_file, data):
    """Get a list of chromosomes to target and new updated ref_file header.

    Could potentially handle remapping from chr1 -> 1 but currently disabled due
    to speed issues."""
    special_remaps = {'chrM': 'MT', 'MT': 'chrM'}
    target_chroms = dict([(x.name, i) for i, x in enumerate(ref.file_contigs(dd.get_ref_file(data))) if chromhacks.is_autosomal_or_sex(x.name)])
    out_chroms = []
    with pysam.Samfile(bam_file, 'rb') as bamfile:
        for bami, bam_contig in enumerate([c['SN'] for c in bamfile.header['SQ']]):
            if bam_contig in target_chroms:
                target_chrom = bam_contig
            elif bam_contig in special_remaps and special_remaps[bam_contig] in target_chroms:
                target_chrom = special_remaps[bam_contig]
            elif bam_contig.startswith('chr') and bam_contig.replace('chr', '') in target_chroms:
                target_chrom = bam_contig.replace('chr', '')
            elif 'chr%s' % bam_contig in target_chroms:
                target_chrom = 'chr%s' % bam_contig
            else:
                target_chrom = None
            if target_chrom and target_chrom == bam_contig:
                out_chroms.append(target_chrom)
    assert out_chroms, 'remove_extracontigs: Did not find any chromosomes in reference file: %s %s' % (bam_file, target_chroms)
    return out_chroms

def pipeline_summary(data):
    """Provide summary information on processing sample.

    Handles standard and CWL (single QC output) cases."""
    data = utils.to_single_data(data)
    work_bam = dd.get_align_bam(data) or dd.get_work_bam(data)
    if not work_bam or not work_bam.endswith('.bam'):
        work_bam = None
    if dd.get_ref_file(data):
        if work_bam or tz.get_in(['config', 'algorithm', 'kraken'], data):
            logger.info('QC: %s %s' % (dd.get_sample_name(data), ', '.join(dd.get_algorithm_qc(data))))
            work_data = cwlutils.unpack_tarballs(utils.deepish_copy(data), data)
            data['summary'] = _run_qc_tools(work_bam, work_data)
            if len(dd.get_algorithm_qc(data)) == 1 and 'output_cwl_keys' in data:
                data['summary']['qc'] = data['summary']['qc'].get(dd.get_algorithm_qc(data)[0])
    return [[data]]

def _split_samples_by_qc(samples):
    """Split data into individual quality control steps for a run.
    """
    to_process = []
    extras = []
    for data in [utils.to_single_data(x) for x in samples]:
        qcs = dd.get_algorithm_qc(data)
        if qcs and (dd.get_align_bam(data) or dd.get_work_bam(data) or tz.get_in(['config', 'algorithm', 'kraken'], data)):
            for qc in qcs:
                add = copy.deepcopy(data)
                add['config']['algorithm']['qc'] = [qc]
                to_process.append([add])
        else:
            extras.append([data])
    return (to_process, extras)

def _merge_metadata(samples):
    """Merge all metadata into CSV file"""
    samples = list(utils.flatten(samples))
    out_dir = dd.get_work_dir(samples[0])
    logger.info('summarize metadata')
    out_file = os.path.join(out_dir, 'metadata.csv')
    sample_metrics = collections.defaultdict(dict)
    for s in samples:
        m = tz.get_in(['metadata'], s)
        if isinstance(m, six.string_types):
            m = json.loads(m)
        if m:
            for me in list(m.keys()):
                if isinstance(m[me], list) or isinstance(m[me], dict) or isinstance(m[me], tuple):
                    m.pop(me, None)
            sample_metrics[dd.get_sample_name(s)].update(m)
    pd.DataFrame(sample_metrics).transpose().to_csv(out_file)
    return out_file

def _other_pipeline_samples(summary_file, cur_samples):
    """Retrieve samples produced previously by another pipeline in the summary output.
    """
    cur_descriptions = set([s[0]['description'] for s in cur_samples])
    out = []
    if utils.file_exists(summary_file):
        with open(summary_file) as in_handle:
            for s in yaml.safe_load(in_handle).get('samples', []):
                if s['description'] not in cur_descriptions:
                    out.append(s)
    return out

def _add_researcher_summary(samples, summary_yaml):
    """Generate summary files per researcher if organized via a LIMS.
    """
    by_researcher = collections.defaultdict(list)
    for data in (x[0] for x in samples):
        researcher = utils.get_in(data, ('upload', 'researcher'))
        if researcher:
            by_researcher[researcher].append(data['description'])
    out_by_researcher = {}
    for researcher, descrs in by_researcher.items():
        out_by_researcher[researcher] = _summary_csv_by_researcher(summary_yaml, researcher, set(descrs), samples[0][0])
    out = []
    for data in (x[0] for x in samples):
        researcher = utils.get_in(data, ('upload', 'researcher'))
        if researcher:
            data['summary']['researcher'] = out_by_researcher[researcher]
        out.append([data])
    return out

def _run_purecn_dx(out, paired):
    """Extract signatures and mutational burdens from PureCN rds file.
    """
    out_base, out, all_files = _get_purecn_dx_files(paired, out)
    if not utils.file_uptodate(out['mutation_burden'], out['rds']):
        with file_transaction(paired.tumor_data, out_base) as tx_out_base:
            cmd = ['PureCN_Dx.R', '--rds', out['rds'], '--callable', dd.get_sample_callable(paired.tumor_data), '--signatures', '--out', tx_out_base]
            do.run(cmd, 'PureCN Dx mutational burden and signatures')
            for f in all_files:
                if os.path.exists(os.path.join(os.path.dirname(tx_out_base), f)):
                    shutil.move(os.path.join(os.path.dirname(tx_out_base), f), os.path.join(os.path.dirname(out_base), f))
    return out

def _get_purecn_dx_files(paired, out):
    """Retrieve files generated by PureCN_Dx
    """
    out_base = '%s-dx' % utils.splitext_plus(out['rds'])[0]
    all_files = []
    for key, ext in [[('mutation_burden',), '_mutation_burden.csv'], [('plot', 'signatures'), '_signatures.pdf'], [('signatures',), '_signatures.csv']]:
        cur_file = '%s%s' % (out_base, ext)
        out = tz.update_in(out, key, lambda x: cur_file)
        all_files.append(os.path.basename(cur_file))
    return (out_base, out, all_files)

def _get_purecn_files(paired, work_dir, require_exist=False):
    """Retrieve organized structure of PureCN output files.
    """
    out_base = os.path.join(work_dir, '%s-purecn' % dd.get_sample_name(paired.tumor_data))
    out = {'plot': {}}
    all_files = []
    for plot in ['chromosomes', 'local_optima', 'segmentation', 'summary']:
        if plot == 'summary':
            cur_file = '%s.pdf' % out_base
        else:
            cur_file = '%s_%s.pdf' % (out_base, plot)
        if not require_exist or os.path.exists(cur_file):
            out['plot'][plot] = cur_file
            all_files.append(os.path.basename(cur_file))
    for key, ext in [['hetsummary', '.csv'], ['dnacopy', '_dnacopy.seg'], ['genes', '_genes.csv'], ['log', '.log'], ['loh', '_loh.csv'], ['rds', '.rds'], ['variants', '_variants.csv']]:
        cur_file = '%s%s' % (out_base, ext)
        if not require_exist or os.path.exists(cur_file):
            out[key] = cur_file
            all_files.append(os.path.basename(cur_file))
    return (out_base, out, all_files)

def _loh_to_vcf(cur):
    """Convert LOH output into standardized VCF.
    """
    cn = int(float(cur['C']))
    minor_cn = int(float(cur['M']))
    if cur['type'].find('LOH'):
        svtype = 'LOH'
    elif cn > 2:
        svtype = 'DUP'
    elif cn < 1:
        svtype = 'DEL'
    else:
        svtype = None
    if svtype:
        info = ['SVTYPE=%s' % svtype, 'END=%s' % cur['end'], 'SVLEN=%s' % (int(cur['end']) - int(cur['start'])), 'CN=%s' % cn, 'MajorCN=%s' % (cn - minor_cn), 'MinorCN=%s' % minor_cn]
        return [cur['chr'], cur['start'], '.', 'N', '<%s>' % svtype, '.', '.', ';'.join(info), 'GT', '0/1']

def run(items, background=None):
    """Detect copy number variations from batched set of samples using GATK4 CNV calling.

    TODO: implement germline calling with DetermineGermlineContigPloidy and GermlineCNVCaller"""
    if not background:
        background = []
    paired = vcfutils.get_paired(items + background)
    if paired:
        out = _run_paired(paired)
    else:
        out = items
        logger.warn('GATK4 CNV calling currently only available for somatic samples: %s' % ', '.join([dd.get_sample_name(d) for d in items + background]))
    return out

def model_segments(copy_file, work_dir, paired):
    """Perform segmentation on input copy number log2 ratio file.
    """
    out_file = os.path.join(work_dir, '%s.cr.seg' % dd.get_sample_name(paired.tumor_data))
    tumor_counts, normal_counts = heterogzygote_counts(paired)
    if not utils.file_exists(out_file):
        with file_transaction(paired.tumor_data, out_file) as tx_out_file:
            params = ['-T', 'ModelSegments', '--denoised-copy-ratios', copy_file, '--allelic-counts', tumor_counts, '--output-prefix', dd.get_sample_name(paired.tumor_data), '-O', os.path.dirname(tx_out_file)]
            if normal_counts:
                params += ['--normal-allelic-counts', normal_counts]
            _run_with_memory_scaling(params, tx_out_file, paired.tumor_data)
            for tx_fname in glob.glob(os.path.join(os.path.dirname(tx_out_file), '%s*' % dd.get_sample_name(paired.tumor_data))):
                shutil.copy(tx_fname, os.path.join(work_dir, os.path.basename(tx_fname)))
    return {'seg': out_file, 'tumor_hets': out_file.replace('.cr.seg', '.hets.tsv'), 'final_seg': out_file.replace('.cr.seg', '.modelFinal.seg')}

def prepare_intervals(data, region_file, work_dir):
    """Prepare interval regions for targeted and gene based regions.
    """
    target_file = os.path.join(work_dir, '%s-target.interval_list' % dd.get_sample_name(data))
    if not utils.file_uptodate(target_file, region_file):
        with file_transaction(data, target_file) as tx_out_file:
            params = ['-T', 'PreprocessIntervals', '-R', dd.get_ref_file(data), '--interval-merging-rule', 'OVERLAPPING_ONLY', '-O', tx_out_file]
            if dd.get_coverage_interval(data) == 'genome':
                params += ['--bin-length', '1000', '--padding', '0']
            else:
                params += ['-L', region_file, '--bin-length', '0', '--padding', '250']
            _run_with_memory_scaling(params, tx_out_file, data)
    return target_file

def _seg_to_vcf(vals):
    """Convert GATK CNV calls seg output to a VCF line.
    """
    call_to_cn = {'+': 3, '-': 1}
    call_to_type = {'+': 'DUP', '-': 'DEL'}
    if vals['CALL'] not in ['0']:
        info = ['FOLD_CHANGE_LOG=%s' % vals['MEAN_LOG2_COPY_RATIO'], 'PROBES=%s' % vals['NUM_POINTS_COPY_RATIO'], 'SVTYPE=%s' % call_to_type[vals['CALL']], 'SVLEN=%s' % (int(vals['END']) - int(vals['START'])), 'END=%s' % vals['END'], 'CN=%s' % call_to_cn[vals['CALL']]]
        return [vals['CONTIG'], vals['START'], '.', 'N', '<%s>' % call_to_type[vals['CALL']], '.', '.', ';'.join(info), 'GT', '0/1']

def create_load_string(upload_dir, groups=None, organism=None):
    """create the code necessary to load the bcbioRNAseq object"""
    libraryline = 'library(bcbioRNASeq)'
    load_template = Template('bcb <- bcbioRNASeq(uploadDir="$upload_dir",interestingGroups=$groups,organism="$organism")')
    load_noorganism_template = Template('bcb <- bcbioRNASeq(uploadDir="$upload_dir",interestingGroups=$groups,organism=NULL)')
    flatline = 'flat <- flatFiles(bcb)'
    saveline = 'saveData(bcb, flat, dir="data")'
    if groups:
        groups = _list2Rlist(groups)
    else:
        groups = _quotestring('sampleName')
    if organism:
        load_bcbio = load_template.substitute(upload_dir=upload_dir, groups=groups, organism=organism)
    else:
        load_bcbio = load_noorganism_template.substitute(upload_dir=upload_dir, groups=groups)
    return ';\n'.join([libraryline, load_bcbio, flatline, saveline])

def _list2Rlist(xs):
    """convert a python list to an R list"""
    if isinstance(xs, six.string_types):
        xs = [xs]
    rlist = ','.join([_quotestring(x) for x in xs])
    return 'c(' + rlist + ')'

def run_qsnp(align_bams, items, ref_file, assoc_files, region=None, out_file=None):
    """Run qSNP calling on paired tumor/normal.
    """
    if utils.file_exists(out_file):
        return out_file
    paired = get_paired_bams(align_bams, items)
    if paired.normal_bam:
        region_files = []
        regions = _clean_regions(items, region)
        if regions:
            for region in regions:
                out_region_file = out_file.replace('.vcf.gz', _to_str(region) + '.vcf.gz')
                region_file = _run_qsnp_paired(align_bams, items, ref_file, assoc_files, region, out_region_file)
                region_files.append(region_file)
            out_file = combine_variant_files(region_files, out_file, ref_file, items[0]['config'])
        if not region:
            out_file = _run_qsnp_paired(align_bams, items, ref_file, assoc_files, region, out_file)
        return out_file
    else:
        raise ValueError('qSNP only works on paired samples')

def _clean_regions(items, region):
    """Intersect region with target file if it exists"""
    variant_regions = bedutils.population_variant_regions(items, merged=True)
    with utils.tmpfile() as tx_out_file:
        target = subset_variant_regions(variant_regions, region, tx_out_file, items)
        if target:
            if isinstance(target, six.string_types) and os.path.isfile(target):
                target = _load_regions(target)
            else:
                target = [target]
            return target

def _load_regions(target):
    """Get list of tupples from bed file"""
    regions = []
    with open(target) as in_handle:
        for line in in_handle:
            if not line.startswith('#'):
                c, s, e = line.strip().split('\t')
                regions.append((c, s, e))
    return regions

def _set_reject(line):
    """Set REJECT in VCF line, or add it if there is something else."""
    if line.startswith('#'):
        return line
    parts = line.split('\t')
    if parts[6] == 'PASS':
        parts[6] = 'REJECT'
    else:
        parts[6] += ';REJECT'
    return '\t'.join(parts)

def svevent_reader(in_file):
    """Lazy generator of SV events, returned as dictionary of parts.
    """
    with open(in_file) as in_handle:
        while 1:
            line = next(in_handle)
            if line.startswith('>'):
                break
        header = line[1:].rstrip().split('\t')
        reader = csv.reader(in_handle, dialect='excel-tab')
        for parts in reader:
            out = {}
            for h, p in zip(header, parts):
                out[h] = p
            yield out

def get_gtf_db(gtf, in_memory=False):
    """create a gffutils DB, in memory if we don't have write permissions"""
    db_file = gtf + '.db'
    if file_exists(db_file):
        return gffutils.FeatureDB(db_file)
    if not os.access(os.path.dirname(db_file), os.W_OK | os.X_OK):
        in_memory = True
    db_file = ':memory:' if in_memory else db_file
    if in_memory or not file_exists(db_file):
        infer_extent = guess_infer_extent(gtf)
        disable_extent = not infer_extent
        db = gffutils.create_db(gtf, dbfn=db_file, disable_infer_genes=disable_extent, disable_infer_transcripts=disable_extent)
    if in_memory:
        return db
    else:
        return gffutils.FeatureDB(db_file)

def complete_features(db):
    """iterator returning features which are complete (have a 'gene_id' and a
    'transcript_id')"""
    for feature in db.all_features():
        gene_id = feature.attributes.get('gene_id', [None])[0]
        transcript_id = feature.attributes.get('transcript_id', [None])[0]
        if gene_id and transcript_id and (feature.featuretype != 'transcript'):
            yield feature

def partition_gtf(gtf, coding=False, out_file=False):
    """return a GTF file of all non-coding or coding transcripts. the GTF must be annotated
    with gene_biotype = "protein_coding" or to have the source column set to the
    biotype for all coding transcripts. set coding to
    True to get only the coding, false to get only the non-coding"""
    if out_file and file_exists(out_file):
        return out_file
    if not out_file:
        out_file = tempfile.NamedTemporaryFile(delete=False, suffix='.gtf').name
    if coding:
        pred = lambda biotype: biotype and biotype == 'protein_coding'
    else:
        pred = lambda biotype: biotype and biotype != 'protein_coding'
    biotype_lookup = _biotype_lookup_fn(gtf)
    db = get_gtf_db(gtf)
    with file_transaction(out_file) as tx_out_file:
        with open(tx_out_file, 'w') as out_handle:
            for feature in db.all_features():
                biotype = biotype_lookup(feature)
                if pred(biotype):
                    out_handle.write(str(feature) + '\n')
    return out_file

def split_gtf(gtf, sample_size=None, out_dir=None):
    """split a GTF file into two equal parts, randomly selecting genes.
    sample_size will select up to sample_size genes in total"""
    if out_dir:
        part1_fn = os.path.basename(os.path.splitext(gtf)[0]) + '.part1.gtf'
        part2_fn = os.path.basename(os.path.splitext(gtf)[0]) + '.part2.gtf'
        part1 = os.path.join(out_dir, part1_fn)
        part2 = os.path.join(out_dir, part2_fn)
        if file_exists(part1) and file_exists(part2):
            return (part1, part2)
    else:
        part1 = tempfile.NamedTemporaryFile(delete=False, suffix='.part1.gtf').name
        part2 = tempfile.NamedTemporaryFile(delete=False, suffix='.part2.gtf').name
    db = get_gtf_db(gtf)
    gene_ids = set([x['gene_id'][0] for x in db.all_features()])
    if not sample_size or (sample_size and sample_size > len(gene_ids)):
        sample_size = len(gene_ids)
    gene_ids = set(random.sample(gene_ids, sample_size))
    part1_ids = set(random.sample(gene_ids, sample_size / 2))
    part2_ids = gene_ids.difference(part1_ids)
    with open(part1, 'w') as part1_handle:
        for gene in part1_ids:
            for feature in db.children(gene):
                part1_handle.write(str(feature) + '\n')
    with open(part2, 'w') as part2_handle:
        for gene in part2_ids:
            for feature in db.children(gene):
                part2_handle.write(str(feature) + '\n')
    return (part1, part2)

def get_gene_source_set(gtf):
    """get a dictionary of the set of all sources for a gene"""
    gene_to_source = {}
    db = get_gtf_db(gtf)
    for feature in complete_features(db):
        gene_id = feature['gene_id'][0]
        sources = gene_to_source.get(gene_id, set([])).union(set([feature.source]))
        gene_to_source[gene_id] = sources
    return gene_to_source

def get_transcript_source_set(gtf):
    """get a dictionary of the set of all sources of the gene for a given
    transcript"""
    gene_to_source = get_gene_source_set(gtf)
    transcript_to_source = {}
    db = get_gtf_db(gtf)
    for feature in complete_features(db):
        gene_id = feature['gene_id'][0]
        transcript_to_source[feature['transcript_id'][0]] = gene_to_source[gene_id]
    return transcript_to_source

def _biotype_lookup_fn(gtf):
    """return a function that will look up the biotype of a feature
    this checks for either gene_biotype or biotype being set or for the source
    column to have biotype information"""
    db = get_gtf_db(gtf)
    sources = set([feature.source for feature in db.all_features()])
    gene_biotypes = set([feature.attributes.get('gene_biotype', [None])[0] for feature in db.all_features()])
    biotypes = set([feature.attributes.get('biotype', [None])[0] for feature in db.all_features()])
    if 'protein_coding' in sources:
        return lambda feature: feature.source
    elif 'protein_coding' in biotypes:
        return lambda feature: feature.attributes.get('biotype', [None])[0]
    elif 'protein_coding' in gene_biotypes:
        return lambda feature: feature.attributes.get('gene_biotype', [None])[0]
    else:
        return None

def tx2genedict(gtf, keep_version=False):
    """produce a tx2gene dictionary from a GTF file"""
    d = {}
    with open_gzipsafe(gtf) as in_handle:
        for line in in_handle:
            if 'gene_id' not in line or 'transcript_id' not in line:
                continue
            geneid = line.split('gene_id')[1].split(' ')[1]
            geneid = _strip_non_alphanumeric(geneid)
            txid = line.split('transcript_id')[1].split(' ')[1]
            txid = _strip_non_alphanumeric(txid)
            if keep_version and 'transcript_version' in line:
                txversion = line.split('transcript_version')[1].split(' ')[1]
                txversion = _strip_non_alphanumeric(txversion)
                txid += '.' + txversion
            if has_transcript_version(line) and (not keep_version):
                txid = _strip_feature_version(txid)
                geneid = _strip_feature_version(geneid)
            d[txid] = geneid
    return d

def _strip_feature_version(featureid):
    """some feature versions are encoded as featureid.version, this strips those off, if they exist"""
    version_detector = re.compile('(?P<featureid>.*)(?P<version>\\.\\d+)')
    match = version_detector.match(featureid)
    if match:
        return match.groupdict()['featureid']
    else:
        return featureid

def tx2genefile(gtf, out_file=None, data=None, tsv=True, keep_version=False):
    """write out a file of transcript->gene mappings."""
    if tsv:
        extension = '.tsv'
        sep = '\t'
    else:
        extension = '.csv'
        sep = ','
    if file_exists(out_file):
        return out_file
    with file_transaction(data, out_file) as tx_out_file:
        with open(tx_out_file, 'w') as out_handle:
            for k, v in tx2genedict(gtf, keep_version).items():
                out_handle.write(sep.join([k, v]) + '\n')
    logger.info('tx2gene file %s created from %s.' % (out_file, gtf))
    return out_file

def is_qualimap_compatible(gtf):
    """Qualimap needs a very specific GTF format or it fails, so skip it if
    the GTF is not in that format"""
    if not gtf:
        return False
    db = get_gtf_db(gtf)
    def qualimap_compatible(feature):
        gene_id = feature.attributes.get('gene_id', [None])[0]
        transcript_id = feature.attributes.get('transcript_id', [None])[0]
        gene_biotype = feature.attributes.get('gene_biotype', [None])[0]
        return gene_id and transcript_id and gene_biotype
    for feature in db.all_features():
        if qualimap_compatible(feature):
            return True
    return False

def canonical_transcripts(gtf, out_file):
    """given a GTF file, produce a new GTF file with only the longest transcript
    for each gene
    function lifted from:
    https://pythonhosted.org/gffutils/_modules/gffutils/helpers.html"""
    if file_exists(out_file):
        return out_file
    db = get_gtf_db(gtf)
    with file_transaction(out_file) as tx_out_file:
        with open(tx_out_file, 'w') as out_handle:
            for gene in db.features_of_type('gene'):
                exon_list = []
                for ti, transcript in enumerate(db.children(gene, level=1)):
                    cds_len = 0
                    total_len = 0
                    exons = list(db.children(transcript, level=1))
                    for exon in exons:
                        exon_length = len(exon)
                        if exon.featuretype == 'CDS':
                            cds_len += exon_length
                        total_len += exon_length
                    exon_list.append((cds_len, total_len, transcript, exons))
                if max((i[0] for i in exon_list)) > 0:
                    best = sorted(exon_list)[0]
                else:
                    best = sorted(exon_list, key=lambda x: x[1])[0]
                for exon in db.children(best[2], level=1):
                    out_handle.write(str(exon) + '\n')
    return out_file

def is_cpat_compatible(gtf):
    """CPAT needs some transcripts annotated with protein coding status to work
    properly"""
    if not gtf:
        return False
    db = get_gtf_db(gtf)
    pred = lambda biotype: biotype and biotype == 'protein_coding'
    biotype_lookup = _biotype_lookup_fn(gtf)
    if not biotype_lookup:
        return False
    db = get_gtf_db(gtf)
    for feature in db.all_features():
        biotype = biotype_lookup(feature)
        if pred(biotype):
            return True
    return False

