def _fill_validation_targets(data):
    """Fill validation targets pointing to globally installed truth sets.
    """
    ref_file = dd.get_ref_file(data)
    sv_truth = tz.get_in(['config', 'algorithm', 'svvalidate'], data, {})
    sv_targets = zip(itertools.repeat('svvalidate'), sv_truth.keys()) if isinstance(sv_truth, dict) else [['svvalidate']]
    for vtarget in [list(xs) for xs in [['validate'], ['validate_regions'], ['variant_regions']] + list(sv_targets)]:
        val = tz.get_in(['config', 'algorithm'] + vtarget, data)
        if val and (not os.path.exists(val)) and (not objectstore.is_remote(val)):
            installed_val = os.path.normpath(os.path.join(os.path.dirname(ref_file), os.pardir, 'validation', val))
            if os.path.exists(installed_val):
                data = tz.update_in(data, ['config', 'algorithm'] + vtarget, lambda x: installed_val)
            else:
                raise ValueError('Configuration problem. Validation file not found for %s: %s' % (vtarget, val))
    return data

def _fill_capture_regions(data):
    """Fill short-hand specification of BED capture regions.
    """
    special_targets = {'sv_regions': ('exons', 'transcripts')}
    ref_file = dd.get_ref_file(data)
    for target in ['variant_regions', 'sv_regions', 'coverage']:
        val = tz.get_in(['config', 'algorithm', target], data)
        if val and (not os.path.exists(val)) and (not objectstore.is_remote(val)):
            installed_vals = []
            for ext in ['.bed', '.bed.gz']:
                installed_vals += glob.glob(os.path.normpath(os.path.join(os.path.dirname(ref_file), os.pardir, 'coverage', val + ext)))
            if len(installed_vals) == 0:
                if target not in special_targets or not val.startswith(special_targets[target]):
                    raise ValueError('Configuration problem. BED file not found for %s: %s' % (target, val))
            else:
                assert len(installed_vals) == 1, installed_vals
                data = tz.update_in(data, ['config', 'algorithm', target], lambda x: installed_vals[0])
    return data

def _clean_algorithm(data):
    """Clean algorithm keys, handling items that can be specified as lists or single items.
    """
    for key in ['variantcaller', 'jointcaller', 'svcaller']:
        val = tz.get_in(['algorithm', key], data)
        if val:
            if not isinstance(val, (list, tuple)) and isinstance(val, six.string_types):
                val = [val]
            if isinstance(val, (list, tuple)):
                if len(val) == 1 and (not val[0]) or (isinstance(val[0], six.string_types) and val[0].lower() in ['none', 'false']):
                    val = False
            data['algorithm'][key] = val
    return data

def _organize_tools_on(data, is_cwl):
    """Ensure tools_on inputs match items specified elsewhere.
    """
    if is_cwl:
        if tz.get_in(['algorithm', 'jointcaller'], data):
            val = tz.get_in(['algorithm', 'tools_on'], data)
            if not val:
                val = []
            if not isinstance(val, (list, tuple)):
                val = [val]
            if 'gvcf' not in val:
                val.append('gvcf')
            data['algorithm']['tools_on'] = val
    return data

def _clean_background(data):
    """Clean up background specification, remaining back compatible.
    """
    allowed_keys = set(['variant', 'cnv_reference'])
    val = tz.get_in(['algorithm', 'background'], data)
    errors = []
    if val:
        out = {}
        if isinstance(val, six.string_types):
            out['variant'] = _file_to_abs(val, [os.getcwd()])
        elif isinstance(val, dict):
            for k, v in val.items():
                if k in allowed_keys:
                    if isinstance(v, six.string_types):
                        out[k] = _file_to_abs(v, [os.getcwd()])
                    else:
                        assert isinstance(v, dict)
                        for ik, iv in v.items():
                            v[ik] = _file_to_abs(iv, [os.getcwd()])
                        out[k] = v
                else:
                    errors.append('Unexpected key: %s' % k)
        else:
            errors.append('Unexpected input: %s' % val)
        if errors:
            raise ValueError('Problematic algorithm background specification for %s:\n %s' % (data['description'], '\n'.join(errors)))
        out['cnv_reference'] = structural.standardize_cnv_reference({'config': data, 'description': data['description']})
        data['algorithm']['background'] = out
    return data

def _clean_characters(x):
    """Clean problem characters in sample lane or descriptions.
    """
    if not isinstance(x, six.string_types):
        x = str(x)
    elif not all((ord(char) < 128 for char in x)):
        msg = 'Found unicode character in input YAML (%s)' % x
        raise ValueError(repr(msg))
    for problem in [' ', '.', '/', '\\', '[', ']', '&', ';', '#', '+', ':', ')', '(']:
        x = x.replace(problem, '_')
    return x

def prep_rg_names(item, config, fc_name, fc_date):
    """Generate read group names from item inputs.
    """
    if fc_name and fc_date:
        lane_name = '%s_%s_%s' % (item['lane'], fc_date, fc_name)
    else:
        lane_name = item['description']
    return {'rg': item['description'], 'sample': item['description'], 'lane': lane_name, 'pl': (tz.get_in(['algorithm', 'platform'], item) or tz.get_in(['algorithm', 'platform'], item, 'illumina')).lower(), 'lb': tz.get_in(['metadata', 'library'], item), 'pu': tz.get_in(['metadata', 'platform_unit'], item) or lane_name}

def _check_for_duplicates(xs, attr, check_fn=None):
    """Identify and raise errors on duplicate items.
    """
    dups = []
    for key, vals in itertools.groupby((x[attr] for x in xs)):
        if len(list(vals)) > 1:
            dups.append(key)
    if len(dups) > 0:
        psamples = []
        for x in xs:
            if x[attr] in dups:
                psamples.append(x)
        if check_fn and check_fn(psamples):
            return
        descrs = [x['description'] for x in psamples]
        raise ValueError("Duplicate '%s' found in input sample configuration.\nRequired to be unique for a project: %s\nProblem found in these samples: %s" % (attr, dups, descrs))

def _check_for_batch_clashes(xs):
    """Check that batch names do not overlap with sample names.
    """
    names = set([x['description'] for x in xs])
    dups = set([])
    for x in xs:
        batches = tz.get_in(('metadata', 'batch'), x)
        if batches:
            if not isinstance(batches, (list, tuple)):
                batches = [batches]
            for batch in batches:
                if batch in names:
                    dups.add(batch)
    if len(dups) > 0:
        raise ValueError('Batch names must be unique from sample descriptions.\nClashing batch names: %s' % sorted(list(dups)))

def _check_for_problem_somatic_batches(items, config):
    """Identify problem batch setups for somatic calling.

    We do not support multiple tumors in a single batch and VarDict(Java) does not
    handle pooled calling, only tumor/normal."""
    to_check = []
    for data in items:
        data = copy.deepcopy(data)
        data['config'] = config_utils.update_w_custom(config, data)
        to_check.append(data)
    data_by_batches = collections.defaultdict(list)
    for data in to_check:
        batches = dd.get_batches(data)
        if batches:
            for batch in batches:
                data_by_batches[batch].append(data)
    for batch, items in data_by_batches.items():
        if vcfutils.get_paired(items):
            vcfutils.check_paired_problems(items)
        elif len(items) > 1:
            vcs = vcfutils.get_somatic_variantcallers(items)
            if 'vardict' in vcs:
                raise ValueError('VarDict does not support pooled non-tumor/normal calling, in batch %s: %s' % (batch, [dd.get_sample_name(data) for data in items]))
            elif 'mutect' in vcs or 'mutect2' in vcs:
                raise ValueError("MuTect and MuTect2 require a 'phenotype: tumor' sample for calling, in batch %s: %s" % (batch, [dd.get_sample_name(data) for data in items]))

def _check_for_misplaced(xs, subkey, other_keys):
    """Ensure configuration keys are not incorrectly nested under other keys.
    """
    problems = []
    for x in xs:
        check_dict = x.get(subkey, {})
        for to_check in other_keys:
            if to_check in check_dict:
                problems.append((x['description'], to_check, subkey))
    if len(problems) > 0:
        raise ValueError('\n'.join(['Incorrectly nested keys found in sample YAML. These should be top level:', ' sample         |   key name      |   nested under ', '----------------+-----------------+----------------'] + ['% 15s | % 15s | % 15s' % (a, b, c) for a, b, c in problems]))

def _check_for_degenerate_interesting_groups(items):
    """Make sure interesting_groups specify existing metadata and that
    the interesting_group is not all of the same for all of the samples"""
    igkey = ('algorithm', 'bcbiornaseq', 'interesting_groups')
    interesting_groups = tz.get_in(igkey, items[0], [])
    if isinstance(interesting_groups, str):
        interesting_groups = [interesting_groups]
    for group in interesting_groups:
        values = [tz.get_in(('metadata', group), x, None) for x in items]
        if all((x is None for x in values)):
            raise ValueError('group %s is labelled as an interesting group, but does not appear in the metadata.' % group)
        if len(list(tz.unique(values))) == 1:
            raise ValueError('group %s is marked as an interesting group, but all samples have the same value.' % group)

def _check_algorithm_values(item):
    """Check for misplaced inputs in the algorithms.

    - Identify incorrect boolean values where a choice is required."""
    problems = []
    for k, v in item.get('algorithm', {}).items():
        if v is True and k not in ALG_ALLOW_BOOLEANS:
            problems.append('%s set as true' % k)
        elif v is False and (k not in ALG_ALLOW_BOOLEANS and k not in ALG_ALLOW_FALSE):
            problems.append('%s set as false' % k)
    if len(problems) > 0:
        raise ValueError("Incorrect settings in 'algorithm' section for %s:\n%s\nSee configuration documentation for supported options:\n%s\n" % (item['description'], '\n'.join(problems), ALG_DOC_URL))

def _check_toplevel_misplaced(item):
    """Check for algorithm keys accidentally placed at the top level.
    """
    problem_keys = [k for k in item.keys() if k in ALGORITHM_KEYS]
    if len(problem_keys) > 0:
        raise ValueError("Unexpected configuration keywords found in top level of %s: %s\nThis should be placed in the 'algorithm' section." % (item['description'], problem_keys))
    problem_keys = [k for k in item.keys() if k not in TOPLEVEL_KEYS]
    if len(problem_keys) > 0:
        raise ValueError('Unexpected configuration keywords found in top level of %s: %s\n' % (item['description'], problem_keys))

def _check_quality_format(items):
    """Check if quality_format="standard" and fastq_format is not sanger"""
    SAMPLE_FORMAT = {'illumina_1.3+': 'illumina', 'illumina_1.5+': 'illumina', 'illumina_1.8+': 'standard', 'solexa': 'solexa', 'sanger': 'standard'}
    fastq_extensions = ['fq.gz', 'fastq.gz', '.fastq', '.fq']
    for item in items:
        specified_format = item['algorithm'].get('quality_format', 'standard').lower()
        if specified_format not in SAMPLE_FORMAT.values():
            raise ValueError('Quality format specified in the YAML fileis not supported. Supported values are %s.' % SAMPLE_FORMAT.values())
        fastq_file = next((f for f in item.get('files') or [] if f.endswith(tuple(fastq_extensions))), None)
        if fastq_file and specified_format and (not objectstore.is_remote(fastq_file)):
            fastq_format = _detect_fastq_format(fastq_file)
            detected_encodings = set([SAMPLE_FORMAT[x] for x in fastq_format])
            if detected_encodings:
                if specified_format not in detected_encodings:
                    raise ValueError("Quality format specified in the YAML file might be a different encoding. '%s' was specified but possible formats detected were %s." % (specified_format, ', '.join(detected_encodings)))

def _check_aligner(item):
    """Ensure specified aligner is valid choice.
    """
    allowed = set(list(alignment.TOOLS.keys()) + [None, False])
    if item['algorithm'].get('aligner') not in allowed:
        raise ValueError("Unexpected algorithm 'aligner' parameter: %s\nSupported options: %s\n" % (item['algorithm'].get('aligner'), sorted(list(allowed))))

def _check_variantcaller(item):
    """Ensure specified variantcaller is a valid choice.
    """
    allowed = set(list(genotype.get_variantcallers().keys()) + [None, False])
    vcs = item['algorithm'].get('variantcaller')
    if not isinstance(vcs, dict):
        vcs = {'variantcaller': vcs}
    for vc_set in vcs.values():
        if not isinstance(vc_set, (tuple, list)):
            vc_set = [vc_set]
        problem = [x for x in vc_set if x not in allowed]
        if len(problem) > 0:
            raise ValueError("Unexpected algorithm 'variantcaller' parameter: %s\nSupported options: %s\n" % (problem, sorted(list(allowed))))
    if 'germline' in vcs or 'somatic' in vcs:
        paired = vcfutils.get_paired_phenotype(item)
        if not paired:
            raise ValueError("%s: somatic/germline calling in 'variantcaller' but tumor/normal metadata phenotype not specified" % dd.get_sample_name(item))

def _check_svcaller(item):
    """Ensure the provide structural variant caller is valid.
    """
    allowed = set(reduce(operator.add, [list(d.keys()) for d in structural._CALLERS.values()]) + [None, False])
    svs = item['algorithm'].get('svcaller')
    if not isinstance(svs, (list, tuple)):
        svs = [svs]
    problem = [x for x in svs if x not in allowed]
    if len(problem) > 0:
        raise ValueError("Unexpected algorithm 'svcaller' parameters: %s\nSupported options: %s\n" % (' '.join(["'%s'" % x for x in problem]), sorted(list(allowed))))

def _check_hetcaller(item):
    """Ensure upstream SV callers requires to heterogeneity analysis are available.
    """
    svs = _get_as_list(item, 'svcaller')
    hets = _get_as_list(item, 'hetcaller')
    if hets or any([x in svs for x in ['titancna', 'purecn']]):
        if not any([x in svs for x in ['cnvkit', 'gatk-cnv']]):
            raise ValueError('Heterogeneity caller used but need CNV calls. Add `gatk4-cnv` or `cnvkit` to `svcaller` in sample: %s' % item['description'])

def _check_jointcaller(data):
    """Ensure specified jointcaller is valid.
    """
    allowed = set(joint.get_callers() + [None, False])
    cs = data['algorithm'].get('jointcaller', [])
    if not isinstance(cs, (tuple, list)):
        cs = [cs]
    problem = [x for x in cs if x not in allowed]
    if len(problem) > 0:
        raise ValueError("Unexpected algorithm 'jointcaller' parameter: %s\nSupported options: %s\n" % (problem, sorted(list(allowed), key=lambda x: x or '')))

def _check_realign(data):
    """Check for realignment, which is not supported in GATK4
    """
    if 'gatk4' not in data['algorithm'].get('tools_off', []) and (not 'gatk4' == data['algorithm'].get('tools_off')):
        if data['algorithm'].get('realign'):
            raise ValueError('In sample %s, realign specified but it is not supported for GATK4. Realignment is generally not necessary for most variant callers.' % dd.get_sample_name(data))

def _check_trim(data):
    """Check for valid values for trim_reads.
    """
    trim = data['algorithm'].get('trim_reads')
    if trim:
        if trim == 'fastp' and data['algorithm'].get('align_split_size') is not False:
            raise ValueError('In sample %s, `trim_reads: fastp` currently requires `align_split_size: false`' % dd.get_sample_name(data))

def _file_to_abs(x, dnames, makedir=False):
    """Make a file absolute using the supplied base directory choices.
    """
    if x is None or os.path.isabs(x):
        return x
    elif isinstance(x, six.string_types) and objectstore.is_remote(x):
        return x
    elif isinstance(x, six.string_types) and x.lower() == 'none':
        return None
    else:
        for dname in dnames:
            if dname:
                normx = os.path.normpath(os.path.join(dname, x))
                if os.path.exists(normx):
                    return normx
                elif makedir:
                    utils.safe_makedir(normx)
                    return normx
        raise ValueError('Did not find input file %s in %s' % (x, dnames))

def _sanity_check_files(item, files):
    """Ensure input files correspond with supported approaches.

    Handles BAM, fastqs, plus split fastqs."""
    msg = None
    file_types = set(['bam' if x.endswith('.bam') else 'fastq' for x in files if x])
    if len(file_types) > 1:
        msg = 'Found multiple file types (BAM and fastq)'
    file_type = file_types.pop()
    if file_type == 'bam':
        if len(files) != 1:
            msg = 'Expect a single BAM file input as input'
    elif file_type == 'fastq':
        if len(files) not in [1, 2] and item['analysis'].lower() != 'scrna-seq':
            pair_types = set([len(xs) for xs in fastq.combine_pairs(files)])
            if len(pair_types) != 1 or pair_types.pop() not in [1, 2]:
                msg = 'Expect either 1 (single end) or 2 (paired end) fastq inputs'
        if len(files) == 2 and files[0] == files[1]:
            msg = 'Expect both fastq files to not be the same'
    if msg:
        raise ValueError('%s for %s: %s' % (msg, item.get('description', ''), files))

def validate_yaml(yaml_in, yaml_fn):
    """Check with yamllint the yaml syntaxes
    Looking for duplicate keys."""
    try:
        import yamllint.linter as linter
        from yamllint.config import YamlLintConfig
    except ImportError:
        return
    conf = '{"extends": "relaxed",\n               "rules": {"trailing-spaces": {"level": "warning"},\n                         "new-lines": {"level": "warning"},\n                         "new-line-at-end-of-file": {"level": "warning"}}}'
    if utils.file_exists(yaml_in):
        with open(yaml_in) as in_handle:
            yaml_in = in_handle.read()
    out = linter.run(yaml_in, YamlLintConfig(conf))
    for problem in out:
        msg = '%(fn)s:%(line)s:%(col)s: [%(level)s] %(msg)s' % {'fn': yaml_fn, 'line': problem.line, 'col': problem.column, 'level': problem.level, 'msg': problem.message}
        if problem.level == 'error':
            raise ValueError(msg)

def add_metadata_defaults(md):
    """Central location for defaults for algorithm inputs.
    """
    defaults = {'batch': None, 'phenotype': ''}
    for k, v in defaults.items():
        if k not in md:
            md[k] = v
    return md

def _replace_global_vars(xs, global_vars):
    """Replace globally shared names from input header with value.

    The value of the `algorithm` item may be a pointer to a real
    file specified in the `global` section. If found, replace with
    the full value."""
    if isinstance(xs, (list, tuple)):
        return [_replace_global_vars(x) for x in xs]
    elif isinstance(xs, dict):
        final = {}
        for k, v in xs.items():
            if isinstance(v, six.string_types) and v in global_vars:
                v = global_vars[v]
            final[k] = v
        return final
    else:
        return xs

def _subset_regions(region, base_file, items):
    """Subset to a BED file (or genomic region) for calling.
    """
    variant_regions = bedutils.population_variant_regions(items, merged=True)
    target = pshared.subset_variant_regions(variant_regions, region, base_file, items)
    if isinstance(target, six.string_types) and os.path.isfile(target):
        return target
    else:
        return bamprep.region_to_gatk(target)

def run(bam_file, data, out_dir):
    """Create several log files"""
    m = {'base': None, 'secondary': []}
    m.update(_mirbase_stats(data, out_dir))
    m['secondary'].append(_seqcluster_stats(data, out_dir))

def _mirbase_stats(data, out_dir):
    """Create stats from miraligner"""
    utils.safe_makedir(out_dir)
    out_file = os.path.join(out_dir, '%s_bcbio_mirbase.txt' % dd.get_sample_name(data))
    out_file_novel = os.path.join(out_dir, '%s_bcbio_mirdeeep2.txt' % dd.get_sample_name(data))
    mirbase_fn = data.get('seqbuster', None)
    if mirbase_fn:
        _get_stats_from_miraligner(mirbase_fn, out_file, 'seqbuster')
    mirdeep_fn = data.get('seqbuster_novel', None)
    if mirdeep_fn:
        _get_stats_from_miraligner(mirdeep_fn, out_file_novel, 'mirdeep2')
    return {'base': out_file, 'secondary': [out_file_novel]}

def _generate_barcode_ids(info_iter):
    """Create unique barcode IDs assigned to sequences
    """
    bc_type = 'SampleSheet'
    barcodes = list(set([x[-1] for x in info_iter]))
    barcodes.sort()
    barcode_ids = {}
    for i, bc in enumerate(barcodes):
        barcode_ids[bc] = (bc_type, i + 1)
    return barcode_ids

def _read_input_csv(in_file):
    """Parse useful details from SampleSheet CSV file.
    """
    with io.open(in_file, newline=None) as in_handle:
        reader = csv.reader(in_handle)
        next(reader)
        for line in reader:
            if line:
                fc_id, lane, sample_id, genome, barcode = line[:5]
                yield (fc_id, lane, sample_id, genome, barcode)

def _get_flowcell_id(in_file, require_single=True):
    """Retrieve the unique flowcell id represented in the SampleSheet.
    """
    fc_ids = set([x[0] for x in _read_input_csv(in_file)])
    if require_single and len(fc_ids) > 1:
        raise ValueError('There are several FCIDs in the same samplesheet file: %s' % in_file)
    else:
        return fc_ids

def run_has_samplesheet(fc_dir, config, require_single=True):
    """Checks if there's a suitable SampleSheet.csv present for the run
    """
    fc_name, _ = flowcell.parse_dirname(fc_dir)
    sheet_dirs = config.get('samplesheet_directories', [])
    fcid_sheet = {}
    for ss_dir in (s for s in sheet_dirs if os.path.exists(s)):
        with utils.chdir(ss_dir):
            for ss in glob.glob('*.csv'):
                fc_ids = _get_flowcell_id(ss, require_single)
                for fcid in fc_ids:
                    if fcid:
                        fcid_sheet[fcid] = os.path.join(ss_dir, ss)
    potential_fcids = difflib.get_close_matches(fc_name, fcid_sheet.keys(), 1, 0.85)
    if len(potential_fcids) > 0 and potential_fcids[0] in fcid_sheet:
        return fcid_sheet[potential_fcids[0]]
    else:
        return None

def get_noalt_contigs(data):
    """Retrieve contigs without alternatives as defined in bwa *.alts files.

    If no alt files present (when we're not aligning with bwa), work around
    with standard set of alts based on hg38 -- anything with HLA, _alt or
    _decoy in the name."""
    alts = set([])
    alt_files = [f for f in tz.get_in(['reference', 'bwa', 'indexes'], data, []) if f.endswith('alt')]
    if alt_files:
        for alt_file in alt_files:
            with open(alt_file) as in_handle:
                for line in in_handle:
                    if not line.startswith('@'):
                        alts.add(line.split()[0].strip())
    else:
        for contig in ref.file_contigs(dd.get_ref_file(data)):
            if '_alt' in contig.name or '_decoy' in contig.name or contig.name.startswith('HLA-') or (':' in contig.name):
                alts.add(contig.name)
    return [c for c in ref.file_contigs(dd.get_ref_file(data)) if c.name not in alts]

def subset_bam_by_region(in_file, region, config, out_file_base=None):
    """Subset BAM files based on specified chromosome region.
    """
    if out_file_base is not None:
        base, ext = os.path.splitext(out_file_base)
    else:
        base, ext = os.path.splitext(in_file)
    out_file = '%s-subset%s%s' % (base, region, ext)
    if not file_exists(out_file):
        with pysam.Samfile(in_file, 'rb') as in_bam:
            target_tid = in_bam.gettid(region)
            assert region is not None, 'Did not find reference region %s in %s' % (region, in_file)
            with file_transaction(config, out_file) as tx_out_file:
                with pysam.Samfile(tx_out_file, 'wb', template=in_bam) as out_bam:
                    for read in in_bam:
                        if read.tid == target_tid:
                            out_bam.write(read)
    return out_file

def remove_lcr_regions(orig_bed, items):
    """If configured and available, update a BED file to remove low complexity regions.
    """
    lcr_bed = tz.get_in(['genome_resources', 'variation', 'lcr'], items[0])
    if lcr_bed and os.path.exists(lcr_bed) and ('lcr' in get_exclude_regions(items)):
        return _remove_regions(orig_bed, [lcr_bed], 'nolcr', items[0])
    else:
        return orig_bed

def remove_polyx_regions(in_file, items):
    """Remove polyX stretches, contributing to long variant runtimes.
    """
    ex_bed = tz.get_in(['genome_resources', 'variation', 'polyx'], items[0])
    if ex_bed and os.path.exists(ex_bed):
        return _remove_regions(in_file, [ex_bed], 'nopolyx', items[0])
    else:
        return in_file

def add_highdepth_genome_exclusion(items):
    """Add exclusions to input items to avoid slow runtimes on whole genomes.
    """
    out = []
    for d in items:
        d = utils.deepish_copy(d)
        if dd.get_coverage_interval(d) == 'genome':
            e = dd.get_exclude_regions(d)
            if 'highdepth' not in e:
                e.append('highdepth')
                d = dd.set_exclude_regions(d, e)
        out.append(d)
    return out

def remove_highdepth_regions(in_file, items):
    """Remove high depth regions from a BED file for analyzing a set of calls.

    Tries to avoid spurious errors and slow run times in collapsed repeat regions.

    Also adds ENCODE blacklist regions which capture additional collapsed repeats
    around centromeres."""
    encode_bed = tz.get_in(['genome_resources', 'variation', 'encode_blacklist'], items[0])
    if encode_bed and os.path.exists(encode_bed):
        return _remove_regions(in_file, [encode_bed], 'glimit', items[0])
    else:
        return in_file

def get_exclude_regions(items):
    """Retrieve regions to exclude from a set of items.

    Includes back compatibility for older custom ways of specifying different
    exclusions."""
    def _get_sample_excludes(d):
        excludes = dd.get_exclude_regions(d)
        if tz.get_in(('config', 'algorithm', 'remove_lcr'), d, False):
            excludes.append('lcr')
        return excludes
    out = reduce(operator.add, [_get_sample_excludes(d) for d in items])
    return sorted(list(set(out)))

def remove_exclude_regions(f):
    """Remove regions to exclude based on configuration: polyA, LCR, high depth.
    """
    exclude_fns = {'lcr': remove_lcr_regions, 'highdepth': remove_highdepth_regions, 'polyx': remove_polyx_regions}
    @functools.wraps(f)
    def wrapper(variant_regions, region, out_file, items=None, do_merge=True, data=None):
        region_bed = f(variant_regions, region, out_file, items, do_merge, data)
        if region_bed and isinstance(region_bed, six.string_types) and os.path.exists(region_bed) and items:
            for e in get_exclude_regions(items):
                if e in exclude_fns:
                    region_bed = exclude_fns[e](region_bed, items)
        return region_bed
    return wrapper

def to_multiregion(region):
    """Convert a single region or multiple region specification into multiregion list.

    If a single region (chrom, start, end), returns [(chrom, start, end)]
    otherwise returns multiregion."""
    assert isinstance(region, (list, tuple)), region
    if isinstance(region[0], (list, tuple)):
        return region
    else:
        assert len(region) == 3
        return [tuple(region)]

def subset_variant_regions(variant_regions, region, out_file, items=None, do_merge=True, data=None):
    """Return BED file subset by a specified chromosome region.

    variant_regions is a BED file, region is a chromosome name or tuple
    of (name, start, end) for a genomic region."""
    if region is None:
        return variant_regions
    elif variant_regions is None:
        return region
    elif not isinstance(region, (list, tuple)) and region.find(':') > 0:
        raise ValueError('Partial chromosome regions not supported')
    else:
        merge_text = '-unmerged' if not do_merge else ''
        subset_file = '{0}'.format(utils.splitext_plus(out_file)[0])
        subset_file += '%s-regions.bed' % merge_text
        if not os.path.exists(subset_file):
            data = items[0] if items else data
            with file_transaction(data, subset_file) as tx_subset_file:
                if isinstance(region, (list, tuple)):
                    _subset_bed_by_region(variant_regions, tx_subset_file, to_multiregion(region), dd.get_ref_file(data), do_merge=do_merge)
                else:
                    _rewrite_bed_with_chrom(variant_regions, tx_subset_file, region)
        if os.path.getsize(subset_file) == 0:
            return region
        else:
            return subset_file

def _run_delly(bam_files, chrom, ref_file, work_dir, items):
    """Run delly, calling structural variations for the specified type.
    """
    batch = sshared.get_cur_batch(items)
    ext = '-%s-svs' % batch if batch else '-svs'
    out_file = os.path.join(work_dir, '%s%s-%s.bcf' % (os.path.splitext(os.path.basename(bam_files[0]))[0], ext, chrom))
    final_file = '%s.vcf.gz' % utils.splitext_plus(out_file)[0]
    cores = min(utils.get_in(items[0], ('config', 'algorithm', 'num_cores'), 1), len(bam_files))
    if not utils.file_exists(out_file) and (not utils.file_exists(final_file)):
        with file_transaction(items[0], out_file) as tx_out_file:
            if sshared.has_variant_regions(items, out_file, chrom):
                exclude = ['-x', _delly_exclude_file(items, out_file, chrom)]
                cmd = ['delly', 'call', '-g', ref_file, '-o', tx_out_file] + exclude + bam_files
                multi_cmd = 'export OMP_NUM_THREADS=%s && export LC_ALL=C && ' % cores
                try:
                    do.run(multi_cmd + ' '.join(cmd), 'delly structural variant')
                except subprocess.CalledProcessError as msg:
                    if 'Sample has not enough data to estimate library parameters' in str(msg):
                        pass
                    elif 'No structural variants found' not in str(msg):
                        raise
    return [_bgzip_and_clean(out_file, items)]

def _bgzip_and_clean(bcf_file, items):
    """Create a clean bgzipped VCF output file from bcf for downstream processing.

    Also corrects problems with missing likelihoods: https://github.com/dellytools/delly/issues/37
    GATK does not like missing GLs like '.,.,.'. This converts them to the recognized '.'"""
    out_file = '%s.vcf.gz' % utils.splitext_plus(bcf_file)[0]
    if not utils.file_exists(out_file):
        with file_transaction(items[0], out_file) as tx_out_file:
            if not utils.file_exists(bcf_file):
                vcfutils.write_empty_vcf(tx_out_file, samples=[dd.get_sample_name(d) for d in items])
            else:
                cmd = "bcftools view {bcf_file} | sed 's/\\.,\\.,\\././' | bgzip -c > {tx_out_file}"
                do.run(cmd.format(**locals()), 'Convert and clean delly output')
    return vcfutils.bgzip_and_index(out_file, items[0]['config'])

def _disambiguate_star_fusion_junctions(star_junction_file, contamination_bam, disambig_out_file, data):
    """Disambiguate detected fusions based on alignments to another species.
    """
    out_file = disambig_out_file
    fusiondict = {}
    with open(star_junction_file, 'r') as in_handle:
        for my_line in in_handle:
            my_line_split = my_line.strip().split('\t')
            if len(my_line_split) < 10:
                continue
            fusiondict[my_line_split[9]] = my_line.strip('\n')
    with pysam.Samfile(contamination_bam, 'rb') as samfile:
        for my_read in samfile:
            if my_read.is_unmapped or my_read.is_secondary:
                continue
            if my_read.qname in fusiondict:
                fusiondict.pop(my_read.qname)
    with file_transaction(data, out_file) as tx_out_file:
        with open(tx_out_file, 'w') as myhandle:
            for my_key in fusiondict:
                print(fusiondict[my_key], file=myhandle)
    return out_file

def adjust(cols, light):
