def _create_pairwise_gaussian_2d(sx, sy, shape):
    """A simple reference implementation for the 2D case. The ND implementation
    is faster."""
    feat_size = 2
    feats = np.zeros((feat_size, shape[0], shape[1]), dtype=np.float32)
    for i in range(shape[0]):
        for j in range(shape[1]):
            feats[0, i, j] = i / sx
            feats[1, i, j] = j / sy
    return feats.reshape([feat_size, -1])

def _create_pairwise_bilateral_2d(sx, sy, sr, sg, sb, img):
    """A simple reference implementation for the 2D case. The ND implementation
    is faster."""
    feat_size = 5
    feats = np.zeros((feat_size, img.shape[0], img.shape[1]), dtype=np.float32)
    for i in range(img.shape[0]):
        for j in range(img.shape[1]):
            feats[0, i, j] = i / sx
            feats[1, i, j] = j / sy
            feats[2, i, j] = img[i, j, 0] / sr
            feats[3, i, j] = img[i, j, 1] / sg
            feats[4, i, j] = img[i, j, 2] / sb
    return feats.reshape([feat_size, -1])

def process(filename, encoding=DEFAULT_ENCODING, extension=None, **kwargs):
    """This is the core function used for extracting text. It routes the
    ``filename`` to the appropriate parser and returns the extracted
    text as a byte-string encoded with ``encoding``."""
    if not os.path.exists(filename):
        raise exceptions.MissingFileError(filename)
    if extension:
        ext = extension
        if not ext.startswith('.'):
            ext = '.' + ext
        ext = ext.lower()
    else:
        _, ext = os.path.splitext(filename)
        ext = ext.lower()
    ext = EXTENSION_SYNONYMS.get(ext, ext)
    rel_module = ext + _FILENAME_SUFFIX
    try:
        filetype_module = importlib.import_module(rel_module, 'textract.parsers')
    except ImportError:
        raise exceptions.ExtensionNotSupported(ext)
    parser = filetype_module.Parser()
    return parser.process(filename, encoding, **kwargs)

def parse_requirements(requirements_filename):
    """read in the dependencies from the requirements files
    """
    dependencies, dependency_links = ([], [])
    requirements_dir = os.path.dirname(requirements_filename)
    with open(requirements_filename, 'r') as stream:
        for line in stream:
            line = line.strip()
            if line.startswith('-r'):
                filename = os.path.join(requirements_dir, line[2:].strip())
                _dependencies, _dependency_links = parse_requirements(filename)
                dependencies.extend(_dependencies)
                dependency_links.extend(_dependency_links)
            elif line.startswith('http'):
                dependency_links.append(line)
            else:
                package = line.split('#')[0]
                if package:
                    dependencies.append(package)
    return (dependencies, dependency_links)

