def get_movielens_item_metadata(use_item_ids):
    """Build a matrix of genre features (no_items, no_features).

    If use_item_ids is True, per-item features will also be used."""
    features = {}
    genre_set = set()
    for line in _get_movie_raw_metadata():
        if not line:
            continue
        splt = line.split('|')
        item_id = int(splt[0])
        genres = [idx for idx, val in zip(range(len(splt[5:])), splt[5:]) if int(val) > 0]
        if use_item_ids:
            genres.append(item_id)
        for genre_id in genres:
            genre_set.add(genre_id)
        features[item_id] = genres
    mat = sp.lil_matrix((len(features) + 1, len(genre_set)), dtype=np.int32)
    for item_id, genre_ids in features.items():
        for genre_id in genre_ids:
            mat[item_id, genre_id] = 1
    return mat

def _to_pandas(ob):
    """Convert an array-like to a pandas object.

    Parameters
    ----------
    ob : array-like
        The object to convert.

    Returns
    -------
    pandas_structure : pd.Series or pd.DataFrame
        The correct structure based on the dimensionality of the data."""
    if isinstance(ob, (pd.Series, pd.DataFrame)):
        return ob
    if ob.ndim == 1:
        return pd.Series(ob)
    elif ob.ndim == 2:
        return pd.DataFrame(ob)
    else:
        raise ValueError('cannot convert array of dim > 2 to a pandas structure')

