def _normalize(obj):
    """Normalize dicts and lists

    :param obj:
    :return: normalized object"""
    if isinstance(obj, list):
        return [_normalize(item) for item in obj]
    elif isinstance(obj, dict):
        return {k: _normalize(v) for k, v in obj.items() if v is not None}
    elif hasattr(obj, 'to_python'):
        return obj.to_python()
    return obj

def prepare_arg(value):
    """Stringify dicts/lists and convert datetime/timedelta to unix-time

    :param value:
    :return:"""
    if value is None:
        return value
    elif isinstance(value, (list, dict)) or hasattr(value, 'to_python'):
        return json.dumps(_normalize(value))
    elif isinstance(value, datetime.timedelta):
        now = datetime.datetime.now()
        return int((now + value).timestamp())
    elif isinstance(value, datetime.datetime):
        return round(value.timestamp())
    elif isinstance(value, LazyProxy):
        return str(value)
    return value

def check_token(token: str) -> bool:
    """Validate BOT token

    :param token:
    :return:"""
    if any((x.isspace() for x in token)):
        raise exceptions.ValidationError('Token is invalid!')
    left, sep, right = token.partition(':')
    if not sep or not left.isdigit() or len(left) < 3:
        raise exceptions.ValidationError('Token is invalid!')
    return True

def compose_data(params=None, files=None):
    """Prepare request data

    :param params:
    :param files:
    :return:"""
    data = aiohttp.formdata.FormData(quote_fields=False)
    if params:
        for key, value in params.items():
            data.add_field(key, str(value))
    if files:
        for key, f in files.items():
            if isinstance(f, tuple):
                if len(f) == 2:
                    filename, fileobj = f
                else:
                    raise ValueError('Tuple must have exactly 2 elements: filename, fileobj')
            elif isinstance(f, types.InputFile):
                filename, fileobj = (f.filename, f.file)
            else:
                filename, fileobj = (guess_filename(f) or key, f)
            data.add_field(key, fileobj, filename=filename)
    return data

