def _geom_points(geom):
    """GeoJSON geometry to a sequence of point tuples
    """
    if geom['type'] == 'Point':
        yield tuple(geom['coordinates'])
    elif geom['type'] in ('MultiPoint', 'LineString'):
        for position in geom['coordinates']:
            yield tuple(position)
    else:
        raise InvalidFeatureError('Unsupported geometry type:{0}'.format(geom['type']))

def read_points(features):
    """Iterable of features to a sequence of point tuples
    Where "features" can be either GeoJSON mappings
    or objects implementing the geo_interface"""
    for feature in features:
        if isinstance(feature, (tuple, list)) and len(feature) == 2:
            yield feature
        elif hasattr(feature, '__geo_interface__'):
            try:
                geom = feature.__geo_interface__['geometry']
                for pt in _geom_points(geom):
                    yield pt
            except KeyError:
                for pt in _geom_points(feature.__geo_interface__):
                    yield pt
        elif 'type' in feature and feature['type'] == 'Feature':
            geom = feature['geometry']
            for pt in _geom_points(geom):
                yield pt
        elif 'coordinates' in feature:
            geom = feature
            for pt in _geom_points(geom):
                yield pt
        else:
            raise InvalidFeatureError('Unknown object: Not a GeoJSON Point feature or an object with __geo_interface__:\n{0}'.format(feature))

def encode_waypoints(features, min_limit=None, max_limit=None, precision=6):
    """Given an iterable of features
    return a string encoded in waypoint-style used by certain mapbox APIs
    ("lon,lat" pairs separated by ";")"""
    coords = ['{lon},{lat}'.format(lon=float(round(lon, precision)), lat=float(round(lat, precision))) for lon, lat in read_points(features)]
    if min_limit is not None and len(coords) < min_limit:
        raise InvalidFeatureError('Not enough features to encode coordinates, need at least {0}'.format(min_limit))
    if max_limit is not None and len(coords) > max_limit:
        raise InvalidFeatureError('Too many features to encode coordinates, need at most {0}'.format(max_limit))
    return ';'.join(coords)

def encode_polyline(features):
    """Encode and iterable of features as a polyline
    """
    points = list(read_points(features))
    latlon_points = [(x[1], x[0]) for x in points]
    return polyline.encode(latlon_points)

def normalize_geojson_featurecollection(obj):
    """Takes a geojson-like mapping representing
    geometry, Feature or FeatureCollection (or a sequence of such objects)
    and returns a FeatureCollection-like dict"""
    if not isinstance(obj, Sequence):
        obj = [obj]
    features = []
    for x in obj:
        if not isinstance(x, Mapping) or 'type' not in x:
            raise ValueError('Expecting a geojson-like mapping or sequence of them')
        if 'features' in x:
            features.extend(x['features'])
        elif 'geometry' in x:
            features.append(x)
        elif 'coordinates' in x:
            feat = {'type': 'Feature', 'properties': {}, 'geometry': x}
            features.append(feat)
        else:
            raise ValueError('Expecting a geojson-like mapping or sequence of them')
    return {'type': 'FeatureCollection', 'features': features}

def set_werkzeug_log_color():
    """Try to set color to the werkzeug log."""
    from django.core.management.color import color_style
    from werkzeug.serving import WSGIRequestHandler
    from werkzeug._internal import _log
    _style = color_style()
    _orig_log = WSGIRequestHandler.log
    def werk_log(self, type, message, *args):
        try:
            msg = '%s - - [%s] %s' % (self.address_string(), self.log_date_time_string(), message % args)
            http_code = str(args[1])
        except Exception:
            return _orig_log(type, message, *args)
        if http_code[0] == '2':
            msg = _style.HTTP_SUCCESS(msg)
        elif http_code[0] == '1':
            msg = _style.HTTP_INFO(msg)
        elif http_code == '304':
            msg = _style.HTTP_NOT_MODIFIED(msg)
        elif http_code[0] == '3':
            msg = _style.HTTP_REDIRECT(msg)
        elif http_code == '404':
            msg = _style.HTTP_NOT_FOUND(msg)
        elif http_code[0] == '4':
            msg = _style.HTTP_BAD_REQUEST(msg)
        else:
            msg = _style.HTTP_SERVER_ERROR(msg)
        _log(type, msg)
    WSGIRequestHandler.log = werk_log

def _make_writeable(filename):
    """Make sure that the file is writeable. Useful if our source is
    read-only."""
    import stat
    if sys.platform.startswith('java'):
        return
    if not os.access(filename, os.W_OK):
        st = os.stat(filename)
        new_permissions = stat.S_IMODE(st.st_mode) | stat.S_IWUSR
        os.chmod(filename, new_permissions)

