def GetMatchingShape(pattern_poly, trip, matches, max_distance, verbosity=0):
    """Tries to find a matching shape for the given pattern Poly object,
    trip, and set of possibly matching Polys from which to choose a match."""
    if len(matches) == 0:
        print('No matching shape found within max-distance %d for trip %s ' % (max_distance, trip.trip_id))
        return None
    if verbosity >= 1:
        for match in matches:
            print('match: size %d' % match.GetNumPoints())
    scores = [(pattern_poly.GreedyPolyMatchDist(match), match) for match in matches]
    scores.sort()
    if scores[0][0] > max_distance:
        print('No matching shape found within max-distance %d for trip %s (min score was %f)' % (max_distance, trip.trip_id, scores[0][0]))
        return None
    return scores[0][1]

def LoadWithoutErrors(path, memory_db):
    """"Return a Schedule object loaded from path; sys.exit for any error."""
    accumulator = transitfeed.ExceptionProblemAccumulator()
    loading_problem_handler = MergeProblemReporter(accumulator)
    try:
        schedule = transitfeed.Loader(path, memory_db=memory_db, problems=loading_problem_handler, extra_validation=True).Load()
    except transitfeed.ExceptionWithContext as e:
        print('\n\nFeeds to merge must load without any errors.\nWhile loading %s the following error was found:\n%s\n%s\n' % (path, e.FormatContext(), transitfeed.EncodeUnicode(e.FormatProblem())), file=sys.stderr)
        sys.exit(1)
    return schedule

