def MakeExpandedTrace(frame_records):
    """Return a list of text lines for the given list of frame records."""
    dump = []
    for frame_obj, filename, line_num, fun_name, context_lines, context_index in frame_records:
        dump.append('File "%s", line %d, in %s\n' % (filename, line_num, fun_name))
        if context_lines:
            for i, line in enumerate(context_lines):
                if i == context_index:
                    dump.append(' --> %s' % line)
                else:
                    dump.append('     %s' % line)
        for local_name, local_val in frame_obj.f_locals.items():
            try:
                local_type_name = type(local_val).__name__
            except Exception as e:
                local_type_name = '    Exception in type({}).__name__: {}'.format(local_name, e)
            try:
                truncated_val = repr(local_val)[0:500]
            except Exception as e:
                dump.append('    Exception in repr({}): {}\n'.format(local_name, e))
            else:
                if len(truncated_val) >= 500:
                    truncated_val = '%s...' % truncated_val[0:499]
                dump.append('    {} = {} ({})\n'.format(local_name, truncated_val, local_type_name))
        dump.append('\n')
    return dump

def choose_location_ids(gtfs, stop_ids=None):
    """Chooses a set of location ids (stations and their children) for
    rendering a pathway graph.

    If stop_ids is None, then all stations that have pathways are chosen.

    If stop_ids is not None, then the station with this stop_id (or
    with a child with this stop_id) is chosen."""
    if not stop_ids:
        return [location.gtfs_id for location in gtfs.locations if location.station().self_or_children_have_pathways()]
    station_ids = set()
    try:
        for stop_id in stop_ids.split(','):
            station = gtfs.get_location(stop_id).station()
            station_ids.add(station.gtfs_id)
            print('Visualizing station %s' % station.gtfs_id)
    except KeyError:
        raise Exception('Cannot find location with stop_id=%s' % stop_id)
    location_ids = station_ids.copy()
    for station_id in station_ids:
        for child_id in gtfs.get_location(station_id).children:
            location_ids.add(child_id)
            for boarding_area_id in gtfs.get_location(child_id).children:
                location_ids.add(gtfs.get_location(boarding_area_id).gtfs_id)
    return location_ids

def gas_price_strategy_middleware(make_request, web3):
    """Includes a gas price using the gas price strategy"""
    def middleware(method, params):
        if method == 'eth_sendTransaction':
            transaction = params[0]
            if 'gasPrice' not in transaction:
                generated_gas_price = web3.eth.generateGasPrice(transaction)
                if generated_gas_price is not None:
                    transaction = assoc(transaction, 'gasPrice', generated_gas_price)
                    return make_request(method, [transaction])
        return make_request(method, params)
    return middleware

def fill_transaction_defaults(web3, transaction):
    """if web3 is None, fill as much as possible while offline"""
    defaults = {}
    for key, default_getter in TRANSACTION_DEFAULTS.items():
        if key not in transaction:
            if callable(default_getter):
                if web3 is not None:
                    default_val = default_getter(web3, transaction)
                else:
                    raise ValueError('You must specify %s in the transaction' % key)
            else:
                default_val = default_getter
            defaults[key] = default_val
    return merge(defaults, transaction)

def _compute_gas_price(probabilities, desired_probability):
    """Given a sorted range of ``Probability`` named-tuples returns a gas price
    computed based on where the ``desired_probability`` would fall within the
    range.

    :param probabilities: An iterable of `Probability` named-tuples sorted in reverse order.
    :param desired_probability: An floating point representation of the desired
        probability. (e.g. ``85% -> 0.85``)"""
    first = probabilities[0]
    last = probabilities[-1]
    if desired_probability >= first.prob:
        return int(first.gas_price)
    elif desired_probability <= last.prob:
        return int(last.gas_price)
    for left, right in sliding_window(2, probabilities):
        if desired_probability < right.prob:
            continue
        elif desired_probability > left.prob:
            raise Exception('Invariant')
        adj_prob = desired_probability - right.prob
        window_size = left.prob - right.prob
        position = adj_prob / window_size
        gas_window_size = left.gas_price - right.gas_price
        gas_price = int(math.ceil(right.gas_price + gas_window_size * position))
        return gas_price
    else:
        raise Exception('Invariant')

def make_stalecheck_middleware(allowable_delay, skip_stalecheck_for_methods=SKIP_STALECHECK_FOR_METHODS):
    """Use to require that a function will run only of the blockchain is recently updated.

    This middleware takes an argument, so unlike other middleware, you must make the middleware
    with a method call.
    For example: `make_stalecheck_middleware(60*5)`

    If the latest block in the chain is older than 5 minutes in this example, then the
    middleware will raise a StaleBlockchain exception."""
    if allowable_delay <= 0:
        raise ValueError('You must set a positive allowable_delay in seconds for this middleware')
    def stalecheck_middleware(make_request, web3):
        cache = {'latest': None}
        def middleware(method, params):
            if method not in skip_stalecheck_for_methods:
                if _isfresh(cache['latest'], allowable_delay):
                    pass
                else:
                    latest = web3.eth.getBlock('latest')
                    if _isfresh(latest, allowable_delay):
                        cache['latest'] = latest
                    else:
                        raise StaleBlockchain(latest, allowable_delay)
            return make_request(method, params)
        return middleware
    return stalecheck_middleware

def construct_fixture_middleware(fixtures):
    """Constructs a middleware which returns a static response for any method
    which is found in the provided fixtures."""
    def fixture_middleware(make_request, web3):
        def middleware(method, params):
            if method in fixtures:
                result = fixtures[method]
                return {'result': result}
            else:
                return make_request(method, params)
        return middleware
    return fixture_middleware

def construct_result_generator_middleware(result_generators):
    """Constructs a middleware which intercepts requests for any method found in
    the provided mapping of endpoints to generator functions, returning
    whatever response the generator function returns.  Callbacks must be
    functions with the signature `fn(method, params)`."""
    def result_generator_middleware(make_request, web3):
        def middleware(method, params):
            if method in result_generators:
                result = result_generators[method](method, params)
                return {'result': result}
            else:
                return make_request(method, params)
        return middleware
    return result_generator_middleware

def construct_error_generator_middleware(error_generators):
    """Constructs a middleware which intercepts requests for any method found in
    the provided mapping of endpoints to generator functions, returning
    whatever error message the generator function returns.  Callbacks must be
    functions with the signature `fn(method, params)`."""
    def error_generator_middleware(make_request, web3):
        def middleware(method, params):
            if method in error_generators:
                error_msg = error_generators[method](method, params)
                return {'error': error_msg}
            else:
                return make_request(method, params)
        return middleware
    return error_generator_middleware

def combine_middlewares(middlewares, web3, provider_request_fn):
    """Returns a callable function which will call the provider.provider_request
    function wrapped with all of the middlewares."""
    return functools.reduce(lambda request_fn, middleware: middleware(request_fn, web3), reversed(middlewares), provider_request_fn)

def exception_retry_middleware(make_request, web3, errors, retries=5):
    """Creates middleware that retries failed HTTP requests. Is a default
    middleware for HTTPProvider."""
    def middleware(method, params):
        if check_if_retry_on_failure(method):
            for i in range(retries):
                try:
                    return make_request(method, params)
                except errors:
                    if i < retries - 1:
                        continue
                    else:
                        raise
        else:
            return make_request(method, params)
    return middleware

def iso13616Prepare(iban):
    """Prepare an IBAN for mod 97 computation by moving the first
    4 chars to the end and transforming the letters to numbers
    (A = 10, B = 11, ..., Z = 35), as specified in ISO13616.

    @method iso13616Prepare
    @param {String} iban the IBAN
    @returns {String} the prepared IBAN"""
    A = ord('A')
    Z = ord('Z')
    iban = iban.upper()
    iban = iban[4:] + iban[:4]
    def charfunc(n):
        code = ord(n)
        if code >= A and code <= Z:
            return str(code - A + 10)
        else:
            return str(n)
    return ''.join(map(charfunc, list(iban)))

def mod9710(iban):
    """Calculates the MOD 97 10 of the passed IBAN as specified in ISO7064.

    @method mod9710
    @param {String} iban
    @returns {Number}"""
    remainder = iban
    block = None
    while len(remainder) > 2:
        block = remainder[:9]
        remainder = str(int(block) % 97) + remainder[len(block):]
    return int(remainder) % 97

def baseN(num, b, numerals='0123456789abcdefghijklmnopqrstuvwxyz'):
    """This prototype should be used to create
    an iban object from iban correct string

    @param {String} iban"""
    return num == 0 and numerals[0] or baseN(num // b, b, numerals).lstrip(numerals[0]) + numerals[num % b]

def block_ranges(start_block, last_block, step=5):
    """Returns 2-tuple ranges describing ranges of block from start_block to last_block

    Ranges do not overlap to facilitate use as ``toBlock``, ``fromBlock``
    json-rpc arguments, which are both inclusive."""
    if last_block is not None and start_block > last_block:
        raise TypeError('Incompatible start and stop arguments.', 'Start must be less than or equal to stop.')
    return ((from_block, to_block - 1) for from_block, to_block in segment_count(start_block, last_block + 1, step))

def get_logs_multipart(w3, startBlock, stopBlock, address, topics, max_blocks):
    """Used to break up requests to ``eth_getLogs``

    The getLog request is partitioned into multiple calls of the max number of blocks
    ``max_blocks``."""
    _block_ranges = block_ranges(startBlock, stopBlock, max_blocks)
    for from_block, to_block in _block_ranges:
        params = {'fromBlock': from_block, 'toBlock': to_block, 'address': address, 'topics': topics}
        yield w3.eth.getLogs(drop_items_with_none_value(params))

def generate_cache_key(value):
    """Generates a cache key for the *args and **kwargs"""
    if is_bytes(value):
        return hashlib.md5(value).hexdigest()
    elif is_text(value):
        return generate_cache_key(to_bytes(text=value))
    elif is_boolean(value) or is_null(value) or is_number(value):
        return generate_cache_key(repr(value))
    elif is_dict(value):
        return generate_cache_key(((key, value[key]) for key in sorted(value.keys())))
    elif is_list_like(value) or isinstance(value, collections.abc.Generator):
        return generate_cache_key(''.join((generate_cache_key(item) for item in value)))
    else:
        raise TypeError('Cannot generate cache key for value {0} of type {1}'.format(value, type(value)))

def hex_encode_abi_type(abi_type, value, force_size=None):
    """Encodes value into a hex string in format of abi_type"""
    validate_abi_type(abi_type)
    validate_abi_value(abi_type, value)
    data_size = force_size or size_of_type(abi_type)
    if is_array_type(abi_type):
        sub_type = sub_type_of_array_type(abi_type)
        return ''.join([remove_0x_prefix(hex_encode_abi_type(sub_type, v, 256)) for v in value])
    elif is_bool_type(abi_type):
        return to_hex_with_size(value, data_size)
    elif is_uint_type(abi_type):
        return to_hex_with_size(value, data_size)
    elif is_int_type(abi_type):
        return to_hex_twos_compliment(value, data_size)
    elif is_address_type(abi_type):
        return pad_hex(value, data_size)
    elif is_bytes_type(abi_type):
        if is_bytes(value):
            return encode_hex(value)
        else:
            return value
    elif is_string_type(abi_type):
        return to_hex(text=value)
    else:
        raise ValueError('Unsupported ABI type: {0}'.format(abi_type))

def to_hex_twos_compliment(value, bit_size):
    """Converts integer value to twos compliment hex representation with given bit_size"""
    if value >= 0:
        return to_hex_with_size(value, bit_size)
    value = (1 << bit_size) + value
    hex_value = hex(value)
    hex_value = hex_value.rstrip('L')
    return hex_value

def pad_hex(value, bit_size):
    """Pads a hex string up to the given bit_size"""
    value = remove_0x_prefix(value)
    return add_0x_prefix(value.zfill(int(bit_size / 4)))

def to_int(value=None, hexstr=None, text=None):
    """Converts value to it's integer representation.

    Values are converted this way:

     * value:
       * bytes: big-endian integer
       * bool: True => 1, False => 0
     * hexstr: interpret hex as integer
     * text: interpret as string of digits, like '12' => 12"""
    assert_one_val(value, hexstr=hexstr, text=text)
    if hexstr is not None:
        return int(hexstr, 16)
    elif text is not None:
        return int(text)
    elif isinstance(value, bytes):
        return big_endian_to_int(value)
    elif isinstance(value, str):
        raise TypeError('Pass in strings with keyword hexstr or text')
    else:
        return int(value)

def text_if_str(to_type, text_or_primitive):
    """Convert to a type, assuming that strings can be only unicode text (not a hexstr)

    @param to_type is a function that takes the arguments (primitive, hexstr=hexstr, text=text),
        eg~ to_bytes, to_text, to_hex, to_int, etc
    @param hexstr_or_primitive in bytes, str, or int."""
    if isinstance(text_or_primitive, str):
        primitive, text = (None, text_or_primitive)
    else:
        primitive, text = (text_or_primitive, None)
    return to_type(primitive, text=text)

def hexstr_if_str(to_type, hexstr_or_primitive):
    """Convert to a type, assuming that strings can be only hexstr (not unicode text)

    @param to_type is a function that takes the arguments (primitive, hexstr=hexstr, text=text),
        eg~ to_bytes, to_text, to_hex, to_int, etc
    @param text_or_primitive in bytes, str, or int."""
    if isinstance(hexstr_or_primitive, str):
        primitive, hexstr = (None, hexstr_or_primitive)
        if remove_0x_prefix(hexstr) and (not is_hex(hexstr)):
            raise ValueError('when sending a str, it must be a hex string. Got: {0!r}'.format(hexstr_or_primitive))
    else:
        primitive, hexstr = (hexstr_or_primitive, None)
    return to_type(primitive, hexstr=hexstr)

def normalize_data_values(type_string, data_value):
    """Decodes utf-8 bytes to strings for abi string values.

    eth-abi v1 returns utf-8 bytes for string values.
    This can be removed once eth-abi v2 is required."""
    _type = parse_type_string(type_string)
    if _type.base == 'string':
        if _type.arrlist is not None:
            return tuple((normalize_to_text(value) for value in data_value))
        else:
            return normalize_to_text(data_value)
    return data_value

def match_fn(match_values_and_abi, data):
    """Match function used for filtering non-indexed event arguments.

    Values provided through the match_values_and_abi parameter are
    compared to the abi decoded log data."""
    abi_types, all_match_values = zip(*match_values_and_abi)
    decoded_values = decode_abi(abi_types, HexBytes(data))
    for data_value, match_values, abi_type in zip(decoded_values, all_match_values, abi_types):
        if match_values is None:
            continue
        normalized_data = normalize_data_values(abi_type, data_value)
        for value in match_values:
            if not is_encodable(abi_type, value):
                raise ValueError('Value {0} is of the wrong abi type. Expected {1} typed value.'.format(value, abi_type))
            if value == normalized_data:
                break
        else:
            return False
    return True

def attrdict_middleware(make_request, web3):
    """Converts any result which is a dictionary into an a"""
    def middleware(method, params):
        response = make_request(method, params)
        if 'result' in response:
            result = response['result']
            if is_dict(result) and (not isinstance(result, AttributeDict)):
                return assoc(response, 'result', AttributeDict.recursive(result))
            else:
                return response
        else:
            return response
    return middleware

def dict_copy(func):
    """copy dict keyword args, to avoid modifying caller's copy"""
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        copied_kwargs = copy.deepcopy(kwargs)
        return func(*args, **copied_kwargs)
    return wrapper

def normalize_name(name):
    """Clean the fully qualified name, as defined in ENS `EIP-137
    <https://github.com/ethereum/EIPs/blob/master/EIPS/eip-137.md#name-syntax>`_

    This does *not* enforce whether ``name`` is a label or fully qualified domain.

    :param str name: the dot-separated ENS name
    :raises InvalidName: if ``name`` has invalid syntax"""
    if not name:
        return name
    elif isinstance(name, (bytes, bytearray)):
        name = name.decode('utf-8')
    try:
        return idna.decode(name, uts46=True, std3_rules=True)
    except idna.IDNAError as exc:
        raise InvalidName('%s is an invalid name, because %s' % (name, exc)) from exc

def dot_eth_label(name):
    """Convert from a name, like 'ethfinex.eth', to a label, like 'ethfinex'
    If name is already a label, this should be a noop, except for converting to a string
    and validating the name syntax."""
    label = name_to_label(name, registrar='eth')
    if len(label) < MIN_ETH_LABEL_LENGTH:
        raise InvalidLabel('name %r is too short' % label)
    else:
        return label

def map_collection(func, collection):
    """Apply func to each element of a collection, or value of a dictionary.
    If the value is not a collection, return it unmodified"""
    datatype = type(collection)
    if isinstance(collection, Mapping):
        return datatype(((key, func(val)) for key, val in collection.items()))
    if is_string(collection):
        return collection
    elif isinstance(collection, Iterable):
        return datatype(map(func, collection))
    else:
        return collection

def recursive_map(func, data):
    """Apply func to data, and any collection items inside data (using map_collection).
    Define func so that it only applies to the type of value that you want it to apply to."""
    def recurse(item):
        return recursive_map(func, item)
    items_mapped = map_collection(recurse, data)
    return func(items_mapped)

def percentile(values=None, percentile=None):
    """Calculates a simplified weighted average percentile
    """
    if values in [None, tuple(), []] or len(values) < 1:
        raise InsufficientData('Expected a sequence of at least 1 integers, got {0!r}'.format(values))
    if percentile is None:
        raise ValueError('Expected a percentile choice, got {0}'.format(percentile))
    sorted_values = sorted(values)
    rank = len(values) * percentile / 100
    if rank > 0:
        index = rank - 1
        if index < 0:
            return sorted_values[0]
    else:
        index = rank
    if index % 1 == 0:
        return sorted_values[int(index)]
    else:
        fractional = index % 1
        integer = int(index - fractional)
        lower = sorted_values[integer]
        higher = sorted_values[integer + 1]
        return lower + fractional * (higher - lower)

def parse_basic_type_str(old_normalizer):
    """Modifies a normalizer to automatically parse the incoming type string.  If
    that type string does not represent a basic type (i.e. non-tuple type) or is
    not parsable, the normalizer does nothing."""
    @functools.wraps(old_normalizer)
    def new_normalizer(type_str, data):
        try:
            abi_type = parse(type_str)
        except ParseError:
            return (type_str, data)
        if not isinstance(abi_type, BasicType):
            return (type_str, data)
        return old_normalizer(abi_type, type_str, data)
    return new_normalizer

def construct_sign_and_send_raw_middleware(private_key_or_account):
    """Capture transactions sign and send as raw transactions


    Keyword arguments:
    private_key_or_account -- A single private key or a tuple,
    list or set of private keys. Keys can be any of the following formats:
      - An eth_account.LocalAccount object
      - An eth_keys.PrivateKey object
      - A raw private key as a hex string or byte string"""
    accounts = gen_normalized_accounts(private_key_or_account)
    def sign_and_send_raw_middleware(make_request, w3):
        format_and_fill_tx = compose(format_transaction, fill_transaction_defaults(w3), fill_nonce(w3))
        def middleware(method, params):
            if method != 'eth_sendTransaction':
                return make_request(method, params)
            else:
                transaction = format_and_fill_tx(params[0])
            if 'from' not in transaction:
                return make_request(method, params)
            elif transaction.get('from') not in accounts:
                return make_request(method, params)
            account = accounts[transaction['from']]
            raw_tx = account.signTransaction(transaction).rawTransaction
            return make_request('eth_sendRawTransaction', [raw_tx])
        return middleware
    return sign_and_send_raw_middleware

def validate_abi(abi):
    """Helper function for validating an ABI"""
    if not is_list_like(abi):
        raise ValueError("'abi' is not a list")
    if not all((is_dict(e) for e in abi)):
        raise ValueError("'abi' is not a list of dictionaries")
    functions = filter_by_type('function', abi)
    selectors = groupby(compose(encode_hex, function_abi_to_4byte_selector), functions)
    duplicates = valfilter(lambda funcs: len(funcs) > 1, selectors)
    if duplicates:
        raise ValueError('Abi contains functions with colliding selectors. Functions {0}'.format(_prepare_selector_collision_msg(duplicates)))

def validate_address(value):
    """Helper function for validating an address"""
    if is_bytes(value):
        if not is_binary_address(value):
            raise InvalidAddress('Address must be 20 bytes when input type is bytes', value)
        return
    if not isinstance(value, str):
        raise TypeError('Address {} must be provided as a string'.format(value))
    if not is_hex_address(value):
        raise InvalidAddress('Address must be 20 bytes, as a hex string with a 0x prefix', value)
    if not is_checksum_address(value):
        if value == value.lower():
            raise InvalidAddress('Web3.py only accepts checksum addresses. The software that gave you this non-checksum address should be considered unsafe, please file it as a bug on their platform. Try using an ENS name instead. Or, if you must accept lower safety, use Web3.toChecksumAddress(lower_case_address).', value)
        else:
            raise InvalidAddress('Address has an invalid EIP-55 checksum. After looking up the address from the original source, try again.', value)

def construct_simple_cache_middleware(cache_class, rpc_whitelist=SIMPLE_CACHE_RPC_WHITELIST, should_cache_fn=_should_cache):
    """Constructs a middleware which caches responses based on the request
    ``method`` and ``params``

    :param cache: Any dictionary-like object
    :param rpc_whitelist: A set of RPC methods which may have their responses cached.
    :param should_cache_fn: A callable which accepts ``method`` ``params`` and
        ``response`` and returns a boolean as to whether the response should be
        cached."""
    def simple_cache_middleware(make_request, web3):
        cache = cache_class()
        lock = threading.Lock()
        def middleware(method, params):
            lock_acquired = lock.acquire(blocking=False)
            try:
                if lock_acquired and method in rpc_whitelist:
                    cache_key = generate_cache_key((method, params))
                    if cache_key not in cache:
                        response = make_request(method, params)
                        if should_cache_fn(method, params, response):
                            cache[cache_key] = response
                        return response
                    return cache[cache_key]
                else:
                    return make_request(method, params)
            finally:
                if lock_acquired:
                    lock.release()
        return middleware
    return simple_cache_middleware

def get_tuple_type_str_parts(s: str) -> Optional[Tuple[str, Optional[str]]]:
    """Takes a JSON ABI type string.  For tuple type strings, returns the separated
    prefix and array dimension parts.  For all other strings, returns ``None``."""
    match = TUPLE_TYPE_STR_RE.match(s)
    if match is not None:
        tuple_prefix = match.group(1)
        tuple_dims = match.group(2)
        return (tuple_prefix, tuple_dims)
    return None

def _align_abi_input(arg_abi, arg):
    """Aligns the values of any mapping at any level of nesting in ``arg``
    according to the layout of the corresponding abi spec."""
    tuple_parts = get_tuple_type_str_parts(arg_abi['type'])
    if tuple_parts is None:
        return arg
    tuple_prefix, tuple_dims = tuple_parts
    if tuple_dims is None:
        sub_abis = arg_abi['components']
    else:
        new_abi = copy.copy(arg_abi)
        new_abi['type'] = tuple_prefix
        sub_abis = itertools.repeat(new_abi)
    if isinstance(arg, abc.Mapping):
        aligned_arg = tuple((arg[abi['name']] for abi in sub_abis))
    else:
        aligned_arg = arg
    if not is_list_like(aligned_arg):
        raise TypeError('Expected non-string sequence for "{}" component type: got {}'.format(arg_abi['type'], aligned_arg))
    return type(aligned_arg)((_align_abi_input(sub_abi, sub_arg) for sub_abi, sub_arg in zip(sub_abis, aligned_arg)))

def size_of_type(abi_type):
    """Returns size in bits of abi_type"""
    if 'string' in abi_type:
        return None
    if 'byte' in abi_type:
        return None
    if '[' in abi_type:
        return None
    if abi_type == 'bool':
        return 8
    if abi_type == 'address':
        return 160
    return int(re.sub('\\D', '', abi_type))

def data_tree_map(func, data_tree):
    """Map func to every ABITypedData element in the tree. func will
    receive two args: abi_type, and data"""
    def map_to_typed_data(elements):
        if isinstance(elements, ABITypedData) and elements.abi_type is not None:
            return ABITypedData(func(*elements))
        else:
            return elements
    return recursive_map(map_to_typed_data, data_tree)

def prepare_transaction(address, web3, fn_identifier, contract_abi=None, fn_abi=None, transaction=None, fn_args=None, fn_kwargs=None):
    """:parameter `is_function_abi` is used to distinguish  function abi from contract abi
    Returns a dictionary of the transaction that could be used to call this
    TODO: make this a public API
    TODO: add new prepare_deploy_transaction API"""
    if fn_abi is None:
        fn_abi = find_matching_fn_abi(contract_abi, fn_identifier, fn_args, fn_kwargs)
    validate_payable(transaction, fn_abi)
    if transaction is None:
        prepared_transaction = {}
    else:
        prepared_transaction = dict(**transaction)
    if 'data' in prepared_transaction:
        raise ValueError("Transaction parameter may not contain a 'data' key")
    if address:
        prepared_transaction.setdefault('to', address)
    prepared_transaction['data'] = encode_transaction_data(web3, fn_identifier, contract_abi, fn_abi, fn_args, fn_kwargs)
    return prepared_transaction

def distance(a, b, metric='cosine'):
    """Calculate distance between two vectors based on a Metric

    Metrics:
    1. cosine distance. Note that in word2vec all the norms are 1 so the dot product is the same as cosine distance"""
    if metric == 'cosine':
        return np.dot(a, b.T)
    raise Exception("Unknown metric '{metric}'".format(metric=metric))

def load(fname, kind='auto', *args, **kwargs):
    """Loads a word vectors file"""
    if kind == 'auto':
        if fname.endswith('.bin'):
            kind = 'bin'
        elif fname.endswith('.txt'):
            kind = 'txt'
        else:
            raise Exception('Could not identify kind')
    if kind == 'bin':
        return word2vec.WordVectors.from_binary(fname, *args, **kwargs)
    elif kind == 'txt':
        return word2vec.WordVectors.from_text(fname, *args, **kwargs)
    elif kind == 'mmap':
        return word2vec.WordVectors.from_mmap(fname, *args, **kwargs)
    else:
        raise Exception('Unknown kind')

def do_uni_form(parser, token):
    """You need to pass in at least the form/formset object, and can also pass in the
    optional `crispy_forms.helpers.FormHelper` object.

    helper (optional): A `crispy_forms.helper.FormHelper` object.

    Usage::

        {% load crispy_tags %}
        {% crispy form form.helper %}

    You can also provide the template pack as the third argument::

        {% crispy form form.helper 'bootstrap' %}

    If the `FormHelper` attribute is named `helper` you can simply do::

        {% crispy form %}
        {% crispy form 'bootstrap' %}"""
    token = token.split_contents()
    form = token.pop(1)
    helper = None
    template_pack = "'%s'" % get_template_pack()
    try:
        helper = token.pop(1)
    except IndexError:
        pass
    try:
        template_pack = token.pop(1)
    except IndexError:
        pass
    if helper is not None and isinstance(helper, string_types) and ("'" in helper or '"' in helper):
        template_pack = helper
        helper = None
    if template_pack is not None:
        template_pack = template_pack[1:-1]
        ALLOWED_TEMPLATE_PACKS = getattr(settings, 'CRISPY_ALLOWED_TEMPLATE_PACKS', ('bootstrap', 'uni_form', 'bootstrap3', 'bootstrap4'))
        if template_pack not in ALLOWED_TEMPLATE_PACKS:
            raise template.TemplateSyntaxError("crispy tag's template_pack argument should be in %s" % str(ALLOWED_TEMPLATE_PACKS))
    return CrispyFormNode(form, helper, template_pack=template_pack)

def crispy_field(parser, token):
    """{% crispy_field field attrs %}"""
    token = token.split_contents()
    field = token.pop(1)
    attrs = {}
    token.pop(0)
    for attribute_name, value in pairwise(token):
        attrs[attribute_name] = value
    return CrispyFieldNode(field, attrs)

def crispy_addon(field, append='', prepend='', form_show_labels=True):
    """Renders a form field using bootstrap's prepended or appended text::

        {% crispy_addon form.my_field prepend="$" append=".00" %}

    You can also just prepend or append like so

        {% crispy_addon form.my_field prepend="$" %}
        {% crispy_addon form.my_field append=".00" %}"""
    if field:
        context = Context({'field': field, 'form_show_errors': True, 'form_show_labels': form_show_labels})
        template = loader.get_template('%s/layout/prepended_appended_text.html' % get_template_pack())
        context['crispy_prepended_text'] = prepend
        context['crispy_appended_text'] = append
        if not prepend and (not append):
            raise TypeError('Expected a prepend and/or append argument')
        context = context.flatten()
    return template.render(context)

def as_crispy_errors(form, template_pack=TEMPLATE_PACK):
    """Renders only form errors the same way as django-crispy-forms::

        {% load crispy_forms_tags %}
        {{ form|as_crispy_errors }}

    or::

        {{ form|as_crispy_errors:"bootstrap" }}"""
    if isinstance(form, BaseFormSet):
        template = get_template('%s/errors_formset.html' % template_pack)
        c = Context({'formset': form}).flatten()
    else:
        template = get_template('%s/errors.html' % template_pack)
        c = Context({'form': form}).flatten()
    return template.render(c)

def as_crispy_field(field, template_pack=TEMPLATE_PACK, label_class='', field_class=''):
    """Renders a form field like a django-crispy-forms field::

        {% load crispy_forms_tags %}
        {{ form.field|as_crispy_field }}

    or::

        {{ form.field|as_crispy_field:"bootstrap" }}"""
    if not isinstance(field, forms.BoundField) and settings.DEBUG:
        raise CrispyError('|as_crispy_field got passed an invalid or inexistent field')
    attributes = {'field': field, 'form_show_errors': True, 'form_show_labels': True, 'label_class': label_class, 'field_class': field_class}
    helper = getattr(field.form, 'helper', None)
    template_path = None
    if helper is not None:
        attributes.update(helper.get_attributes(template_pack))
        template_path = helper.field_template
    if not template_path:
        template_path = '%s/field.html' % template_pack
    template = get_template(template_path)
    c = Context(attributes).flatten()
    return template.render(c)

