def list_difference(left, right):
    """Take the not-in-place difference of two lists (left - right), similar to sets but preserving order."""
    blocked = set(right)
    difference = []
    for item in left:
        if item not in blocked:
            blocked.add(item)
            difference.append(item)
    return difference

def import_string(dotted_path):
    """Import a dotted module path and return the attribute/class designated by the
    last name in the path. Raise ImportError if the import failed.

    Args:
        dotted_path: The path to attempt importing

    Returns:
        Imported class/attribute"""
    try:
        module_path, class_name = dotted_path.rsplit('.', 1)
    except ValueError as err:
        raise ImportError("%s doesn't look like a module path" % dotted_path) from err
    module = import_module(module_path)
    try:
        return getattr(module, class_name)
    except AttributeError as err:
        raise ImportError('Module "%s" does not define a "%s" attribute/class' % (module_path, class_name)) from err

def detect_format(program, attributes) -> str:
    """Detect format for vertex attributes.
    The format returned does not contain padding.

    Args:
        program (Program): The program.
        attributes (list): A list of attribute names.

    Returns:
        str"""
    def fmt(attr):
        """For internal use only."""
        return (attr.array_length * attr.dimension, attr.shape)
    return ' '.join(('%d%s' % fmt(program[a]) for a in attributes))

