def _parse_line(sep, line):
    """Parse a grub commands/config with format: cmd{sep}opts
    Returns: (name, value): value can be None"""
    strs = line.split(sep, 1)
    return (strs[0].strip(), None) if len(strs) == 1 else (strs[0].strip(), strs[1].strip())

def _parse_script(list, line, line_iter):
    """Eliminate any bash script contained in the grub v2 configuration"""
    ifIdx = 0
    while True:
        line = next(line_iter)
        if line.startswith('fi'):
            if ifIdx == 0:
                return
            ifIdx -= 1
        elif line.startswith('if'):
            ifIdx += 1

def _parse_menu_entry(line_iter, cur_line, conf):
    """Parse each `menuentry` that the grub v2 configuration contains
    * Uses "_parse_script" to eliminate bash scripts"""
    menu = []
    conf['menuentry'].append(menu)
    n, entry = _parse_line('menuentry', cur_line)
    entry_name, v = _parse_line('{', entry)
    if not entry_name:
        raise Exception('Cannot parse menuentry line: {0}'.format(cur_line))
    menu.append(('menuentry_name', entry_name))
    if v:
        menu.append(_parse_cmd(v))
    while True:
        line = next(line_iter)
        if '{' in line:
            n, v = _parse_line('{', line)
            if v:
                menu.append(_parse_cmd(v))
        elif '}' in line:
            n, v = _parse_line('}', line)
            if n:
                menu.append(_parse_cmd(n))
            return
        elif line.startswith('if'):
            _parse_script(menu, line, line_iter)
        else:
            menu.append(_parse_cmd(line))

def map_keys(pvs, keys):
    """Add human readable key names to dictionary while leaving any existing key names."""
    rs = []
    for pv in pvs:
        r = dict(((v, None) for k, v in keys.items()))
        for k, v in pv.items():
            if k in keys:
                r[keys[k]] = v
            r[k] = v
        rs.append(r)
    return rs

def find_warnings(content):
    """Look for lines containing warning/error/info strings instead of data."""
    keywords = [k.lower() for k in ['WARNING', "Couldn't find device", 'Configuration setting', 'read failed', 'Was device resized?', 'Invalid argument', 'leaked on lvs', 'Checksum error', 'is exported', 'failed.', 'Invalid metadata', 'response failed', 'unknown device', 'duplicate', 'not found', 'Missing device', 'Internal error', 'Input/output error', 'Incorrect metadata', 'Cannot process volume', 'No such file or directory', 'Logging initialised', 'changed sizes', 'vsnprintf failed', 'write failed', 'correction failed', 'Failed to write', "Couldn't read", 'marked missing', 'Attempt to close device', 'Ignoring supplied major', 'not match metadata']]
    for l in content:
        lower = l.strip().lower()
        if not lower.startswith('lvm2'):
            if any((k in lower for k in keywords)):
                yield l

def from_dict(dct):
    """Convert a dictionary into a configtree."""
    def inner(d):
        results = []
        for name, v in d.items():
            if isinstance(v, dict):
                results.append(Section(name=name, children=from_dict(v)))
            elif isinstance(v, list):
                if not any((isinstance(i, dict) for i in v)):
                    results.append(Directive(name=name, attrs=v))
                else:
                    for i in v:
                        if isinstance(i, dict):
                            results.append(Section(name=name, children=from_dict(i)))
                        elif isinstance(i, list):
                            results.append(Directive(name=name, attrs=i))
                        else:
                            results.append(Directive(name=name, attrs=[i]))
            else:
                results.append(Directive(name, attrs=[v]))
        return results
    return Root(children=inner(dct))

def BinaryBool(pred):
    """Lifts predicates that take an argument into the DSL."""
    class Predicate(Bool):
        def __init__(self, value, ignore_case=False):
            self.value = caseless(value) if ignore_case else value
            self.ignore_case = ignore_case
        def __call__(self, data):
            if not isinstance(data, list):
                data = [data]
            for d in data:
                try:
                    if pred(caseless(d) if self.ignore_case else d, self.value):
                        return True
                except:
                    pass
            return False
    return Predicate

def pad_version(left, right):
    """Returns two sequences of the same length so that they can be compared.
    The shorter of the two arguments is lengthened by inserting extra zeros
    before non-integer components.  The algorithm attempts to align character
    components."""
    pair = (vcmp(left), vcmp(right))
    mn, mx = (min(pair, key=len), max(pair, key=len))
    for idx, c in enumerate(mx):
        try:
            a = mx[idx]
            b = mn[idx]
            if type(a) != type(b):
                mn.insert(idx, 0)
        except IndexError:
            if type(c) is int:
                mn.append(0)
            elif isinstance(c, six.string_types):
                mn.append('')
            else:
                raise Exception('pad_version failed (%s) (%s)' % (left, right))
    return pair

def _resolve_name(name, package, level):
    """Return the absolute name of the module to be imported."""
    if not hasattr(package, 'rindex'):
        raise ValueError("'package' not set to a string")
    dot = len(package)
    for x in xrange(level, 1, -1):
        try:
            dot = package.rindex('.', 0, dot)
        except ValueError:
            raise ValueError('attempted relative import beyond top-level package')
    return '%s.%s' % (package[:dot], name)

def import_module(name, package=None):
    """Import a module.

    The 'package' argument is required when performing a relative import. It
    specifies the package to use as the anchor point from which to resolve the
    relative import to an absolute import."""
    if name.startswith('.'):
        if not package:
            raise TypeError("relative imports require the 'package' argument")
        level = 0
        for character in name:
            if character != '.':
                break
            level += 1
        name = _resolve_name(name[level:], package, level)
    __import__(name)
    return sys.modules[name]

def _handle_key_value(t_dict, key, value):
    """Function to handle key has multi value, and return the values as list."""
    if key in t_dict:
