def get_to_persist(persisters):
    """Given a specification of what to persist, generates the corresponding set
    of components."""
    def specs():
        for p in persisters:
            if isinstance(p, dict):
                yield (p['name'], p.get('enabled', True))
            else:
                yield (p, True)
    components = sorted(dr.DELEGATES, key=dr.get_name)
    names = dict(((c, dr.get_name(c)) for c in components))
    results = set()
    for p, e in specs():
        for c in components:
            if names[c].startswith(p):
                if e:
                    results.add(c)
                elif c in results:
                    results.remove(c)
    return results

def get_pool(parallel, kwargs):
    """Yields:
        a ThreadPoolExecutor if parallel is True and `concurrent.futures` exists.
        `None` otherwise."""
    if parallel:
        try:
            from concurrent.futures import ThreadPoolExecutor
            with ThreadPoolExecutor(thread_name_prefix='insights-collector-pool', **kwargs) as pool:
                yield pool
        except ImportError:
            yield None
    else:
        yield None

def _run(broker, graph=None, root=None, context=None, inventory=None):
    """run is a general interface that is meant for stand alone scripts to use
    when executing insights components.

    Args:
        root (str): None will causes a host collection in which command and
            file specs are run. A directory or archive path will cause
            collection from the directory or archive, and only file type specs
            or those that depend on `insights.core.context.HostArchiveContext`
            will execute.
        component (function or class): The component to execute. Will only execute
            the component and its dependency graph. If None, all components with
            met dependencies will execute.

    Returns:
        broker: object containing the result of the evaluation."""
    if not root:
        context = context or HostContext
        broker[context] = context()
        return dr.run(graph, broker=broker)
    if os.path.isdir(root):
        return process_dir(broker, root, graph, context, inventory=inventory)
    else:
        with extract(root) as ex:
            return process_dir(broker, ex.tmp_dir, graph, context, inventory=inventory)

def determine_hostname(display_name=None):
    """Find fqdn if we can"""
    if display_name:
        return display_name
    else:
        socket_gethostname = socket.gethostname()
        socket_fqdn = socket.getfqdn()
        try:
            socket_ex = socket.gethostbyname_ex(socket_gethostname)[0]
        except (LookupError, socket.gaierror):
            socket_ex = ''
        gethostname_len = len(socket_gethostname)
        fqdn_len = len(socket_fqdn)
        ex_len = len(socket_ex)
        if fqdn_len > gethostname_len or ex_len > gethostname_len:
            if 'localhost' not in socket_ex and len(socket_ex):
                return socket_ex
            if 'localhost' not in socket_fqdn:
                return socket_fqdn
        return socket_gethostname

def write_unregistered_file(date=None):
    """Write .unregistered out to disk"""
    delete_registered_file()
    if date is None:
        date = get_time()
    for f in constants.unregistered_files:
        if os.path.lexists(f):
            if os.path.islink(f):
                os.remove(f)
                write_to_disk(f, content=str(date))
        else:
            write_to_disk(f, content=str(date))

def write_to_disk(filename, delete=False, content=get_time()):
    """Write filename out to disk"""
    if not os.path.exists(os.path.dirname(filename)):
        return
    if delete:
        if os.path.lexists(filename):
            os.remove(filename)
    else:
        with open(filename, 'wb') as f:
            f.write(content.encode('utf-8'))

def _expand_paths(path):
    """Expand wildcarded paths"""
    dir_name = os.path.dirname(path)
    paths = []
    logger.debug('Attempting to expand %s', path)
    if os.path.isdir(dir_name):
        files = os.listdir(dir_name)
        match = os.path.basename(path)
        for file_path in files:
            if re.match(match, file_path):
                expanded_path = os.path.join(dir_name, file_path)
                paths.append(expanded_path)
        logger.debug('Expanded paths %s', paths)
        return paths
    else:
        logger.debug('Could not expand %s', path)

