def _convert_hex_str_to_int(val):
    """Convert hexadecimal formatted ids to signed int64"""
    if val is None:
        return None
    hex_num = int(val, 16)
    if hex_num > 9223372036854775807:
        hex_num -= 18446744073709551616
    assert -9223372036854775808 <= hex_num <= 9223372036854775807
    return hex_num

def _convert_attribute_to_tag(key, attr):
    """Convert the attributes to jaeger tags."""
    if isinstance(attr, bool):
        return jaeger.Tag(key=key, vBool=attr, vType=jaeger.TagType.BOOL)
    if isinstance(attr, str):
        return jaeger.Tag(key=key, vStr=attr, vType=jaeger.TagType.STRING)
    if isinstance(attr, int):
        return jaeger.Tag(key=key, vLong=attr, vType=jaeger.TagType.LONG)
    if isinstance(attr, float):
        return jaeger.Tag(key=key, vDouble=attr, vType=jaeger.TagType.DOUBLE)
    logging.warn('Could not serialize attribute             {}:{} to tag'.format(key, attr))
    return None

def wrap_httplib_request(request_func):
    """Wrap the httplib request function to trace. Create a new span and update
    and close the span in the response later."""
    def call(self, method, url, body, headers, *args, **kwargs):
        _tracer = execution_context.get_opencensus_tracer()
        blacklist_hostnames = execution_context.get_opencensus_attr('blacklist_hostnames')
        dest_url = '{}:{}'.format(self._dns_host, self.port)
        if utils.disable_tracing_hostname(dest_url, blacklist_hostnames):
            return request_func(self, method, url, body, headers, *args, **kwargs)
        _span = _tracer.start_span()
        _span.span_kind = span_module.SpanKind.CLIENT
        _span.name = '[httplib]{}'.format(request_func.__name__)
        _tracer.add_attribute_to_current_span(HTTP_URL, url)
        _tracer.add_attribute_to_current_span(HTTP_METHOD, method)
        execution_context.set_opencensus_attr('httplib/current_span_id', _span.span_id)
        try:
            headers = headers.copy()
            headers.update(_tracer.propagator.to_headers(_span.context_tracer.span_context))
        except Exception:
            pass
        return request_func(self, method, url, body, headers, *args, **kwargs)
    return call

