def multidim_measurement_to_attachment(name, measurement):
    """Convert a multi-dim measurement to an `openhtf.test_record.Attachment`."""
    dimensions = list(measurement.dimensions)
    if measurement.units:
        dimensions.append(measurements.Dimension.from_unit_descriptor(measurement.units))
    dims = []
    for d in dimensions:
        if d.suffix is None:
            suffix = u''
        elif isinstance(d.suffix, unicode):
            suffix = d.suffix
        else:
            suffix = d.suffix.decode('utf8')
        dims.append({'uom_suffix': suffix, 'uom_code': d.code, 'name': d.name})
    dimensioned_measured_value = measurement.measured_value
    value = sorted(dimensioned_measured_value.value, key=lambda x: x[0]) if dimensioned_measured_value.is_value_set else None
    outcome_str = MEASUREMENT_OUTCOME_TO_TEST_RUN_STATUS_NAME[measurement.outcome]
    data = _convert_object_to_json({'outcome': outcome_str, 'name': name, 'dimensions': dims, 'value': value})
    attachment = htf_test_record.Attachment(data, test_runs_pb2.MULTIDIM_JSON)
    return attachment

def _wait_for_any_event(events, timeout_s):
    """Wait for any in a list of threading.Event's to be set.

    Args:
      events: List of threading.Event's.
      timeout_s: Max duration in seconds to wait before returning.

    Returns:
        True if at least one event was set before the timeout expired, else False."""
    def any_event_set():
        return any((event.is_set() for event in events))
    result = timeouts.loop_until_timeout_or_true(timeout_s, any_event_set, sleep_s=_WAIT_FOR_ANY_EVENT_POLL_S)
    return result or any_event_set()

def loop(_=None, force=False):
    """Causes a function to loop indefinitely."""
    if not force:
        raise AttributeError('threads.loop() is DEPRECATED.  If you really like this and want to keep it, file an issue at https://github.com/google/openhtf/issues and use it as @loop(force=True) for now.')
    def real_loop(fn):
        @functools.wraps(fn)
        def _proc(*args, **kwargs):
            """Wrapper to return."""
            while True:
                fn(*args, **kwargs)
        _proc.once = fn
        return _proc
    return real_loop

def synchronized(func):
    """Hold self._lock while executing func."""
    @functools.wraps(func)
    def synchronized_method(self, *args, **kwargs):
        """Wrapper to return."""
        if not hasattr(self, '_lock'):
            if func.__name__ in type(self).__dict__:
                hint = ''
            else:
                hint = ' Might be missing call to super in %s.__init__?' % type(self).__name__
            raise RuntimeError("Can't synchronize method `%s` of %s without attribute `_lock`.%s" % (func.__name__, type(self).__name__, hint))
        with self._lock:
            return func(self, *args, **kwargs)
    return synchronized_method

