def init_cao(X, n_clusters, dissim):
    """Initialize centroids according to method by Cao et al. [2009].

    Note: O(N * attr * n_clusters**2), so watch out with large n_clusters"""
    n_points, n_attrs = X.shape
    centroids = np.empty((n_clusters, n_attrs), dtype='object')
    dens = np.zeros(n_points)
    for iattr in range(n_attrs):
        freq = defaultdict(int)
        for val in X[:, iattr]:
            freq[val] += 1
        for ipoint in range(n_points):
            dens[ipoint] += freq[X[ipoint, iattr]] / float(n_points) / float(n_attrs)
    centroids[0] = X[np.argmax(dens)]
    if n_clusters > 1:
        for ik in range(1, n_clusters):
            dd = np.empty((ik, n_points))
            for ikk in range(ik):
                dd[ikk] = dissim(X, centroids[ikk]) * dens
            centroids[ik] = X[np.argmax(np.min(dd, axis=0))]
    return centroids

def _k_modes_iter(X, centroids, cl_attr_freq, membship, dissim, random_state):
    """Single iteration of k-modes clustering algorithm"""
    moves = 0
    for ipoint, curpoint in enumerate(X):
        clust = np.argmin(dissim(centroids, curpoint, X=X, membship=membship))
        if membship[clust, ipoint]:
            continue
        moves += 1
        old_clust = np.argwhere(membship[:, ipoint])[0][0]
        cl_attr_freq, membship, centroids = move_point_cat(curpoint, ipoint, clust, old_clust, cl_attr_freq, membship, centroids)
        if not membship[old_clust, :].any():
            from_clust = membship.sum(axis=1).argmax()
            choices = [ii for ii, ch in enumerate(membship[from_clust, :]) if ch]
            rindx = random_state.choice(choices)
            cl_attr_freq, membship, centroids = move_point_cat(X[rindx], rindx, old_clust, from_clust, cl_attr_freq, membship, centroids)
    return (centroids, moves)

def get_max_value_key(dic):
    """Gets the key for the maximum value in a dict."""
    v = np.array(list(dic.values()))
    k = np.array(list(dic.keys()))
    maxima = np.where(v == np.max(v))[0]
    if len(maxima) == 1:
        return k[maxima[0]]
    else:
        return k[maxima[np.argmin(k[maxima])]]

def encode_features(X, enc_map=None):
    """Converts categorical values in each column of X to integers in the range
    [0, n_unique_values_in_column - 1], if X is not already of integer type.

    If mapping is not provided, it is calculated based on the values in X.

    Unknown values during prediction get a value of -1. np.NaNs are ignored
    during encoding, and get treated as unknowns during prediction."""
    if enc_map is None:
        fit = True
        enc_map = []
    else:
        fit = False
    Xenc = np.zeros(X.shape).astype('int')
    for ii in range(X.shape[1]):
        if fit:
            col_enc = {val: jj for jj, val in enumerate(np.unique(X[:, ii])) if not (isinstance(val, float) and np.isnan(val))}
            enc_map.append(col_enc)
        Xenc[:, ii] = np.array([enc_map[ii].get(x, -1) for x in X[:, ii]])
    return (Xenc, enc_map)

def decode_centroids(encoded, mapping):
    """Decodes the encoded centroids array back to the original data
    labels using a list of mappings."""
    decoded = []
    for ii in range(encoded.shape[1]):
        inv_mapping = {v: k for k, v in mapping[ii].items()}
        decoded.append(np.vectorize(inv_mapping.__getitem__)(encoded[:, ii]))
    return np.atleast_2d(np.array(decoded)).T

def move_point_num(point, to_clust, from_clust, cl_attr_sum, cl_memb_sum):
    """Move point between clusters, numerical attributes."""
    for iattr, curattr in enumerate(point):
        cl_attr_sum[to_clust][iattr] += curattr
        cl_attr_sum[from_clust][iattr] -= curattr
    cl_memb_sum[to_clust] += 1
    cl_memb_sum[from_clust] -= 1
    return (cl_attr_sum, cl_memb_sum)

def euclidean_dissim(a, b, **_):
    """Euclidean distance dissimilarity function"""
    if np.isnan(a).any() or np.isnan(b).any():
        raise ValueError('Missing values detected in numerical columns.')
    return np.sum((a - b) ** 2, axis=1)

def app(environ, start_response):
    """The WSGI Application Server.

    Arguments:
        environ {dict} -- The WSGI environ dictionary
        start_response {WSGI callable}

    Returns:
        WSGI Response"""
    from wsgi import container
    'Add Environ To Service Container\n    Add the environ to the service container. The environ is generated by the\n    the WSGI server above and used by a service provider to manipulate the\n    incoming requests\n    '
    container.bind('Environ', environ)
    'Execute All Service Providers That Require The WSGI Server\n    Run all service provider boot methods if the wsgi attribute is true.\n    '
    try:
        for provider in container.make('WSGIProviders'):
            container.resolve(provider.boot)
    except Exception as e:
        container.make('ExceptionHandler').load_exception(e)
    "We Are Ready For Launch\n    If we have a solid response and not redirecting then we need to return\n    a 200 status code along with the data. If we don't, then we'll have\n    to return a 302 redirection to where ever the user would like go\n    to next.\n    "
    start_response(container.make('Request').get_status_code(), container.make('Request').get_and_reset_headers())
    'Final Step\n    This will take the data variable from the Service Container and return\n    it to the WSGI server.\n    '
    return iter([bytes(container.make('Response'), 'utf-8')])

def gelman_rubin(mcmc):
    """Args:
        mcmc (MCMCResults): Pre-sliced MCMC samples to compute diagnostics for."""
    if mcmc.n_chains < 2:
        raise ValueError('Gelman-Rubin diagnostic requires multiple chains of the same length.')
    Vhat, W = _vhat_w(mcmc)
    Rhat = np.sqrt(Vhat / W)
    return pd.DataFrame({'gelman_rubin': Rhat}, index=mcmc.levels)

def shell_safe_json_parse(json_or_dict_string, preserve_order=False):
    """Allows the passing of JSON or Python dictionary strings. This is needed because certain
    JSON strings in CMD shell are not received in main's argv. This allows the user to specify
    the alternative notation, which does not have this problem (but is technically not JSON)."""
    try:
        if not preserve_order:
            return json.loads(json_or_dict_string)
        from collections import OrderedDict
        return json.loads(json_or_dict_string, object_pairs_hook=OrderedDict)
    except ValueError:
        import ast
        return ast.literal_eval(json_or_dict_string)

def _get_default_arg(args, defaults, arg_index):
    """Method that determines if an argument has default value or not,
    and if yes what is the default value for the argument

    :param args: array of arguments, eg: ['first_arg', 'second_arg', 'third_arg']
    :param defaults: array of default values, eg: (42, 'something')
    :param arg_index: index of the argument in the argument array for which,
    this function checks if a default value exists or not. And if default value
    exists it would return the default value. Example argument: 1
    :return: Tuple of whether there is a default or not, and if yes the default
    value, eg: for index 2 i.e. for "second_arg" this function returns (True, 42)"""
    if not defaults:
        return DefaultArgSpec(False, None)
    args_with_no_defaults = len(args) - len(defaults)
    if arg_index < args_with_no_defaults:
        return DefaultArgSpec(False, None)
    else:
        value = defaults[arg_index - args_with_no_defaults]
        if type(value) is str:
            value = '"%s"' % value
        return DefaultArgSpec(True, value)

def get_method_sig(method):
    '''Given a function, it returns a string that pretty much looks how the
    function signature would be written in python.

    :param method: a python method
    :return: A string similar describing the pythong method signature.
    eg: "my_method(first_argArg, second_arg=42, third_arg='something')"'''
    argspec = inspect.getargspec(method)
    arg_index = 0
    args = []
    for arg in argspec.args:
        default_arg = _get_default_arg(argspec.args, argspec.defaults, arg_index)
        if default_arg.has_default:
            val = default_arg.default_value
            if isinstance(val, basestring):
                val = '"' + val + '"'
            args.append('%s=%s' % (arg, val))
        else:
            args.append(arg)
        arg_index += 1
    if argspec.varargs:
        args.append('*' + argspec.varargs)
    if argspec.keywords:
        args.append('**' + argspec.keywords)
    return '%s(%s)' % (method.__name__, ', '.join(args[1:]))

def escape(value, quote=True):
    """If the value is a string, escapes any special characters and optionally
    surrounds it with single quotes. If the value is not a string (e.g. a number),
    converts it to one."""
    def escape_one(match):
        return SPECIAL_CHARS[match.group(0)]
    if isinstance(value, string_types):
        value = SPECIAL_CHARS_REGEX.sub(escape_one, value)
        if quote:
            value = "'" + value + "'"
    return text_type(value)

def parse_array(array_string):
    """Parse an array string as returned by clickhouse. For example:
        "['hello', 'world']" ==> ["hello", "world"]
        "[1,2,3]"            ==> [1, 2, 3]"""
    if len(array_string) < 2 or array_string[0] != '[' or array_string[-1] != ']':
        raise ValueError('Invalid array string: "%s"' % array_string)
    array_string = array_string[1:]
    values = []
    while True:
        if array_string == ']':
            return values
        elif array_string[0] in ', ':
            array_string = array_string[1:]
        elif array_string[0] == "'":
            match = re.search("[^\\\\]'", array_string)
            if match is None:
                raise ValueError('Missing closing quote: "%s"' % array_string)
            values.append(array_string[1:match.start() + 1])
            array_string = array_string[match.end():]
        else:
            match = re.search(',|\\]', array_string)
            values.append(array_string[0:match.start()])
            array_string = array_string[match.end() - 1:]

def import_submodules(package_name):
    """Import all submodules of a module."""
    import importlib, pkgutil
    package = importlib.import_module(package_name)
    return {name: importlib.import_module(package_name + '.' + name) for _, name, _ in pkgutil.iter_modules(package.__path__)}

