def get_spacegroup_type(hall_number):
    """Translate Hall number to space group type information.

    If it fails, None is returned."""
    _set_no_error()
    keys = ('number', 'international_short', 'international_full', 'international', 'schoenflies', 'hall_symbol', 'choice', 'pointgroup_schoenflies', 'pointgroup_international', 'arithmetic_crystal_class_number', 'arithmetic_crystal_class_symbol')
    spg_type_list = spg.spacegroup_type(hall_number)
    _set_error_message()
    if spg_type_list is not None:
        spg_type = dict(zip(keys, spg_type_list))
        for key in spg_type:
            if key != 'number' and key != 'arithmetic_crystal_class_number':
                spg_type[key] = spg_type[key].strip()
        return spg_type
    else:
        return None

def find_primitive(cell, symprec=1e-05, angle_tolerance=-1.0):
    """Primitive cell is searched in the input cell.

    The primitive cell is returned by a tuple of (lattice, positions, numbers).
    If it fails, None is returned."""
    _set_no_error()
    lattice, positions, numbers, _ = _expand_cell(cell)
    if lattice is None:
        return None
    num_atom_prim = spg.primitive(lattice, positions, numbers, symprec, angle_tolerance)
    _set_error_message()
    if num_atom_prim > 0:
        return (np.array(lattice.T, dtype='double', order='C'), np.array(positions[:num_atom_prim], dtype='double', order='C'), np.array(numbers[:num_atom_prim], dtype='intc'))
    else:
        return None

