def rotational_invariance(force_constants, supercell, primitive, symprec=1e-05):
    """*** Under development ***

    Just show how force constant is close to the condition of
    rotational invariance."""
    print('Check rotational invariance ...')
    fc = force_constants
    p2s = primitive.get_primitive_to_supercell_map()
    smallest_vectors, multiplicity = primitive.get_smallest_vectors()
    abc = 'xyz'
    for pi, p in enumerate(p2s):
        for i in range(3):
            mat = np.zeros((3, 3), dtype='double')
            for s in range(supercell.get_number_of_atoms()):
                m = multiplicity[s, pi]
                vecs = smallest_vectors[s, pi, :m]
                v = np.dot(vecs.sum(axis=0) / m, primitive.get_cell())
                for j in range(3):
                    for k in range(3):
                        mat[j, k] += fc[p, s, i, j] * v[k] - fc[p, s, i, k] * v[j]
            print('Atom %d %s' % (p + 1, abc[i]))
            for vec in mat:
                print('%10.5f %10.5f %10.5f' % tuple(vec))

def similarity_transformation(rot, mat):
    """R x M x R^-1"""
    return np.dot(rot, np.dot(mat, np.linalg.inv(rot)))

def read_aims(filename):
    """Method to read FHI-aims geometry files in phonopy context."""
    lines = open(filename, 'r').readlines()
    cell = []
    is_frac = []
    positions = []
    symbols = []
    magmoms = []
    for line in lines:
        fields = line.split()
        if not len(fields):
            continue
        if fields[0] == 'lattice_vector':
            vec = lmap(float, fields[1:4])
            cell.append(vec)
        elif fields[0][0:4] == 'atom':
            if fields[0] == 'atom':
                frac = False
            elif fields[0] == 'atom_frac':
                frac = True
            pos = lmap(float, fields[1:4])
            sym = fields[4]
            is_frac.append(frac)
            positions.append(pos)
            symbols.append(sym)
            magmoms.append(None)
        elif fields[0] == 'initial_moment':
            magmoms[-1] = float(fields[1])
    for n, frac in enumerate(is_frac):
        if frac:
            pos = [sum([positions[n][l] * cell[l][i] for l in range(3)]) for i in range(3)]
            positions[n] = pos
    if None in magmoms:
        atoms = Atoms(cell=cell, symbols=symbols, positions=positions)
    else:
        atoms = Atoms(cell=cell, symbols=symbols, positions=positions, magmoms=magmoms)
    return atoms

def find_primitive(cell, symprec=1e-05):
    """A primitive cell is searched in the input cell. When a primitive
    cell is found, an object of Atoms class of the primitive cell is
    returned. When not, None is returned."""
    lattice, positions, numbers = spg.find_primitive(cell.totuple(), symprec)
    if lattice is None:
        return None
    else:
        return Atoms(numbers=numbers, scaled_positions=positions, cell=lattice, pbc=True)

def get_lattice_vector_equivalence(point_symmetry):
    """Return (b==c, c==a, a==b)"""
    equivalence = [False, False, False]
    for r in point_symmetry:
        if (np.abs(r[:, 0]) == [0, 1, 0]).all():
            equivalence[2] = True
        if (np.abs(r[:, 0]) == [0, 0, 1]).all():
            equivalence[1] = True
        if (np.abs(r[:, 1]) == [1, 0, 0]).all():
            equivalence[2] = True
        if (np.abs(r[:, 1]) == [0, 0, 1]).all():
            equivalence[0] = True
        if (np.abs(r[:, 2]) == [1, 0, 0]).all():
            equivalence[1] = True
        if (np.abs(r[:, 2]) == [0, 1, 0]).all():
            equivalence[0] = True
    return equivalence

def http_auth_required(realm):
    """Decorator that protects endpoints using Basic HTTP authentication.

    :param realm: optional realm name"""
    def decorator(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            if _check_http_auth():
                return fn(*args, **kwargs)
            if _security._unauthorized_callback:
                return _security._unauthorized_callback()
            else:
                r = _security.default_http_auth_realm if callable(realm) else realm
                h = {'WWW-Authenticate': 'Basic realm="%s"' % r}
                return _get_unauthorized_response(headers=h)
        return wrapper
    if callable(realm):
        return decorator(realm)
    return decorator

def auth_token_required(fn):
    """Decorator that protects endpoints using token authentication. The token
    should be added to the request by the client by using a query string
    variable with a name equal to the configuration value of
    `SECURITY_TOKEN_AUTHENTICATION_KEY` or in a request header named that of
    the configuration value of `SECURITY_TOKEN_AUTHENTICATION_HEADER`"""
    @wraps(fn)
    def decorated(*args, **kwargs):
        if _check_token():
            return fn(*args, **kwargs)
        if _security._unauthorized_callback:
            return _security._unauthorized_callback()
        else:
            return _get_unauthorized_response()
    return decorated

def auth_required(*auth_methods):
    """Decorator that protects enpoints through multiple mechanisms
    Example::

        @app.route('/dashboard')
        @auth_required('token', 'session')
        def dashboard():
            return 'Dashboard'

    :param auth_methods: Specified mechanisms."""
    login_mechanisms = {'token': lambda: _check_token(), 'basic': lambda: _check_http_auth(), 'session': lambda: current_user.is_authenticated}
    def wrapper(fn):
        @wraps(fn)
        def decorated_view(*args, **kwargs):
            h = {}
            mechanisms = [(method, login_mechanisms.get(method)) for method in auth_methods]
            for method, mechanism in mechanisms:
                if mechanism and mechanism():
                    return fn(*args, **kwargs)
                elif method == 'basic':
                    r = _security.default_http_auth_realm
                    h['WWW-Authenticate'] = 'Basic realm="%s"' % r
            if _security._unauthorized_callback:
                return _security._unauthorized_callback()
            else:
                return _get_unauthorized_response(headers=h)
        return decorated_view
    return wrapper

def roles_required(*roles):
    """Decorator which specifies that a user must have all the specified roles.
    Example::

        @app.route('/dashboard')
        @roles_required('admin', 'editor')
        def dashboard():
            return 'Dashboard'

    The current user must have both the `admin` role and `editor` role in order
    to view the page.

    :param args: The required roles."""
    def wrapper(fn):
        @wraps(fn)
        def decorated_view(*args, **kwargs):
            perms = [Permission(RoleNeed(role)) for role in roles]
            for perm in perms:
                if not perm.can():
                    if _security._unauthorized_callback:
                        return _security._unauthorized_callback()
                    else:
                        return _get_unauthorized_view()
            return fn(*args, **kwargs)
        return decorated_view
    return wrapper

def generate_confirmation_token(user):
    """Generates a unique confirmation token for the specified user.

    :param user: The user to work with"""
    data = [str(user.id), hash_data(user.email)]
    return _security.confirm_serializer.dumps(data)

def confirm_email_token_status(token):
    """Returns the expired status, invalid status, and user of a confirmation
    token. For example::

        expired, invalid, user = confirm_email_token_status('...')

    :param token: The confirmation token"""
    expired, invalid, user, token_data = get_token_status(token, 'confirm', 'CONFIRM_EMAIL', return_data=True)
    if not invalid and user:
        user_id, token_email_hash = token_data
        invalid = not verify_hash(token_email_hash, user.email)
    return (expired, invalid, user)

def send_password_reset_notice(user):
    """Sends the password reset notice email for the specified user.

    :param user: The user to send the notice to"""
    if config_value('SEND_PASSWORD_RESET_NOTICE_EMAIL'):
        _security.send_mail(config_value('EMAIL_SUBJECT_PASSWORD_NOTICE'), user.email, 'reset_notice', user=user)

def generate_reset_password_token(user):
    """Generates a unique reset password token for the specified user.

    :param user: The user to work with"""
    password_hash = hash_data(user.password) if user.password else None
    data = [str(user.id), password_hash]
    return _security.reset_serializer.dumps(data)

def login():
    """View function for login view"""
    form_class = _security.login_form
    if request.is_json:
        form = form_class(MultiDict(request.get_json()))
    else:
        form = form_class(request.form)
    if form.validate_on_submit():
        login_user(form.user, remember=form.remember.data)
        after_this_request(_commit)
        if not request.is_json:
            return redirect(get_post_login_redirect(form.next.data))
    if request.is_json:
        return _render_json(form, include_auth_token=True)
    return _security.render_template(config_value('LOGIN_USER_TEMPLATE'), login_user_form=form, **_ctx('login'))

def register():
    """View function which handles a registration request."""
    if _security.confirmable or request.is_json:
        form_class = _security.confirm_register_form
    else:
        form_class = _security.register_form
    if request.is_json:
        form_data = MultiDict(request.get_json())
    else:
        form_data = request.form
    form = form_class(form_data)
    if form.validate_on_submit():
        user = register_user(**form.to_dict())
        form.user = user
        if not _security.confirmable or _security.login_without_confirmation:
            after_this_request(_commit)
            login_user(user)
        if not request.is_json:
            if 'next' in form:
                redirect_url = get_post_register_redirect(form.next.data)
            else:
                redirect_url = get_post_register_redirect()
            return redirect(redirect_url)
        return _render_json(form, include_auth_token=True)
    if request.is_json:
        return _render_json(form)
    return _security.render_template(config_value('REGISTER_USER_TEMPLATE'), register_user_form=form, **_ctx('register'))

