def create_blueprint(state, import_name):
    """Creates the security extension blueprint"""
    bp = Blueprint(state.blueprint_name, import_name, url_prefix=state.url_prefix, subdomain=state.subdomain, template_folder='templates')
    bp.route(state.logout_url, endpoint='logout')(logout)
    if state.passwordless:
        bp.route(state.login_url, methods=['GET', 'POST'], endpoint='login')(send_login)
        bp.route(state.login_url + slash_url_suffix(state.login_url, '<token>'), endpoint='token_login')(token_login)
    else:
        bp.route(state.login_url, methods=['GET', 'POST'], endpoint='login')(login)
    if state.registerable:
        bp.route(state.register_url, methods=['GET', 'POST'], endpoint='register')(register)
    if state.recoverable:
        bp.route(state.reset_url, methods=['GET', 'POST'], endpoint='forgot_password')(forgot_password)
        bp.route(state.reset_url + slash_url_suffix(state.reset_url, '<token>'), methods=['GET', 'POST'], endpoint='reset_password')(reset_password)
    if state.changeable:
        bp.route(state.change_url, methods=['GET', 'POST'], endpoint='change_password')(change_password)
    if state.confirmable:
        bp.route(state.confirm_url, methods=['GET', 'POST'], endpoint='send_confirmation')(send_confirmation)
        bp.route(state.confirm_url + slash_url_suffix(state.confirm_url, '<token>'), methods=['GET', 'POST'], endpoint='confirm_email')(confirm_email)
    return bp

def get_hmac(password):
    """Returns a Base64 encoded HMAC+SHA512 of the password signed with
    the salt specified by ``SECURITY_PASSWORD_SALT``.

    :param password: The password to sign"""
    salt = _security.password_salt
    if salt is None:
        raise RuntimeError('The configuration value `SECURITY_PASSWORD_SALT` must not be None when the value of `SECURITY_PASSWORD_HASH` is set to "%s"' % _security.password_hash)
    h = hmac.new(encode_string(salt), encode_string(password), hashlib.sha512)
    return base64.b64encode(h.digest())

def verify_password(password, password_hash):
    """Returns ``True`` if the password matches the supplied hash.

    :param password: A plaintext password to verify
    :param password_hash: The expected hash value of the password
                          (usually from your database)"""
    if use_double_hash(password_hash):
        password = get_hmac(password)
    return _pwd_context.verify(password, password_hash)

def hash_password(password):
    """Hash the specified plaintext password.

    It uses the configured hashing options.

    .. versionadded:: 2.0.2

    :param password: The plaintext password to hash"""
    if use_double_hash():
        password = get_hmac(password).decode('ascii')
    return _pwd_context.hash(password, **config_value('PASSWORD_HASH_OPTIONS', default={}).get(_security.password_hash, {}))

def get_token_status(token, serializer, max_age=None, return_data=False):
    """Get the status of a token.

    :param token: The token to check
    :param serializer: The name of the seriailzer. Can be one of the
                       following: ``confirm``, ``login``, ``reset``
    :param max_age: The name of the max age config option. Can be on of
                    the following: ``CONFIRM_EMAIL``, ``LOGIN``,
                    ``RESET_PASSWORD``"""
    serializer = getattr(_security, serializer + '_serializer')
    max_age = get_max_age(max_age)
    user, data = (None, None)
    expired, invalid = (False, False)
    try:
        data = serializer.loads(token, max_age=max_age)
    except SignatureExpired:
        d, data = serializer.loads_unsafe(token)
        expired = True
    except (BadSignature, TypeError, ValueError):
        invalid = True
    if data:
        user = _datastore.find_user(id=data[0])
    expired = expired and user is not None
    if return_data:
        return (expired, invalid, user, data)
    else:
        return (expired, invalid, user)

def use_double_hash(password_hash=None):
    """Return a bool indicating whether a password should be hashed twice."""
    single_hash = config_value('PASSWORD_SINGLE_HASH') or {'plaintext'}
    if password_hash is None:
        scheme = _security.password_hash
    else:
        scheme = _pwd_context.identify(password_hash)
    return not (single_hash is True or scheme in single_hash)

def roles_add(user, role):
    """Add user to role."""
    user, role = _datastore._prepare_role_modify_args(user, role)
    if user is None:
        raise click.UsageError('Cannot find user.')
    if role is None:
        raise click.UsageError('Cannot find role.')
