def after_log(logger, log_level, sec_format='%0.3f'):
    """After call strategy that logs to some logger the finished attempt."""
    log_tpl = "Finished call to '%s' after " + str(sec_format) + '(s), this was the %s time calling it.'
    def log_it(retry_state):
        logger.log(log_level, log_tpl, _utils.get_callback_name(retry_state.fn), retry_state.seconds_since_start, _utils.to_ordinal(retry_state.attempt_number))
    return log_it

def retry(*dargs, **dkw):
    """Wrap a function with a new `Retrying` object.

    :param dargs: positional arguments passed to Retrying object
    :param dkw: keyword arguments passed to the Retrying object"""
    if len(dargs) == 1 and callable(dargs[0]):
        return retry()(dargs[0])
    else:
        def wrap(f):
            if asyncio and asyncio.iscoroutinefunction(f):
                r = AsyncRetrying(*dargs, **dkw)
            elif tornado and hasattr(tornado.gen, 'is_coroutine_function') and tornado.gen.is_coroutine_function(f):
                r = TornadoRetrying(*dargs, **dkw)
            else:
                r = Retrying(*dargs, **dkw)
            return r.wraps(f)
        return wrap

def before_sleep_log(logger, log_level):
    """Before call strategy that logs to some logger the attempt."""
    def log_it(retry_state):
        if retry_state.outcome.failed:
            verb, value = ('raised', retry_state.outcome.exception())
        else:
            verb, value = ('returned', retry_state.outcome.result())
        logger.log(log_level, 'Retrying %s in %s seconds as it %s %s.', _utils.get_callback_name(retry_state.fn), getattr(retry_state.next_action, 'sleep'), verb, value)
    return log_it

def before_log(logger, log_level):
    """Before call strategy that logs to some logger the attempt."""
    def log_it(retry_state):
        logger.log(log_level, "Starting call to '%s', this is the %s time calling it.", _utils.get_callback_name(retry_state.fn), _utils.to_ordinal(retry_state.attempt_number))
    return log_it

def get_callback_name(cb):
    """Get a callback fully-qualified name.

    If no name can be produced ``repr(cb)`` is called and returned."""
    segments = []
    try:
        segments.append(cb.__qualname__)
    except AttributeError:
        try:
            segments.append(cb.__name__)
            if inspect.ismethod(cb):
                try:
                    segments.insert(0, cb.im_class.__name__)
                except AttributeError:
                    pass
        except AttributeError:
            pass
    if not segments:
        return repr(cb)
    else:
        try:
            if cb.__module__:
                segments.insert(0, cb.__module__)
        except AttributeError:
            pass
        return '.'.join(segments)

def func_takes_last_result(waiter):
    """Check if function has a "last_result" parameter.

    Needed to provide backward compatibility for wait functions that didn't
    take "last_result" in the beginning."""
    if not six.callable(waiter):
        return False
    if not inspect.isfunction(waiter) and (not inspect.ismethod(waiter)):
        waiter = waiter.__call__
    waiter_spec = _utils.getargspec(waiter)
    return 'last_result' in waiter_spec.args

def stop_dunder_call_accept_old_params(fn):
    """Decorate cls.__call__ method to accept old "stop" signature."""
    @_utils.wraps(fn)
    def new_fn(self, previous_attempt_number=_unset, delay_since_first_attempt=_unset, retry_state=None):
        if retry_state is None:
            from tenacity import RetryCallState
            retry_state_passed_as_non_kwarg = previous_attempt_number is not _unset and isinstance(previous_attempt_number, RetryCallState)
            if retry_state_passed_as_non_kwarg:
                retry_state = previous_attempt_number
            else:
                warn_about_dunder_non_retry_state_deprecation(fn, stacklevel=2)
                retry_state = make_retry_state(previous_attempt_number=previous_attempt_number, delay_since_first_attempt=delay_since_first_attempt)
        return fn(self, retry_state=retry_state)
    return new_fn

def stop_func_accept_retry_state(stop_func):
    """Wrap "stop" function to accept "retry_state" parameter."""
    if not six.callable(stop_func):
