def radang(x, y):
    """return (radius, angle) of a vector(x, y)"""
    if x == 0:
        if y == 0:
            return (0, 0)
        return (abs(y), 90 + 180 * (y < 0))
    if y == 0:
        return (abs(x), 180 * (x < 0))
    r = math.sqrt(x * x + y * y)
    a = math.degrees(math.atan(y / x))
    if x < 0:
        a += 180
    elif y < 0:
        a += 360
    return (r, a)

def run_once(f):
    """Decorator: Make sure function only call once
    not thread safe

    @run_once
    def foo():
        print 'bar'
        return 1+2
    foo()
    foo() # 'bar' only print once"""
    def wrapper(*args, **kwargs):
        if not wrapper.has_run:
            wrapper.result = f(*args, **kwargs)
            wrapper.has_run = True
        return wrapper.result
    wrapper.has_run = False
    return wrapper

