def filename_match(fsearch, filename, width, height):
    """<nickname>@({width}x{height}|auto).(png|jpg|jpeg)"""
    fsearch = clean_path(fsearch)
    filename = clean_path(filename)
    if fsearch == filename:
        return True
    if fsearch.find('@') == -1:
        return False
    basename, fileext = os.path.splitext(fsearch)
    nickname, extinfo = basename.split('@', 1)
    if extinfo == 'auto':
        valid_names = {}.fromkeys([nickname + '@{}x{}'.format(width, height) + fileext, nickname + '@{}x{}'.format(height, width) + fileext, nickname + '.{}x{}'.format(width, height) + fileext, nickname + '.{}x{}'.format(height, width) + fileext])
        if filename in valid_names:
            return True
    return False

def nameddict(name, props):
    """Point = nameddict('Point', ['x', 'y'])
    pt = Point(x=1, y=2)
    pt.y = 3
    print pt"""
    class NamedDict(object):
        def __init__(self, *args, **kwargs):
            self.__store = {}.fromkeys(props)
            if args:
                for i, k in enumerate(props[:len(args)]):
                    self[k] = args[i]
            for k, v in kwargs.items():
                self[k] = v
        def __getattr__(self, key):
            if key.startswith('_NamedDict__'):
                return self.__dict__[key]
            else:
                return self.__store[key]
        def __setattr__(self, key, value):
            if key.startswith('_NamedDict__'):
                object.__setattr__(self, key, value)
            else:
                self.__setitem__(key, value)
        def __getitem__(self, key):
            return self.__store[key]
        def __setitem__(self, key, value):
            if key not in props:
                raise AttributeError('NamedDict(%s) has no attribute %s, avaliables are %s' % (name, key, props))
            self.__store[key] = value
        def __dict__(self):
            return self.__store
        def __str__(self):
            return 'NamedDict(%s: %s)' % (name, str(self.__store))
    return NamedDict

