def diff_rect(img1, img2, pos=None):
    """find counters include pos in differences between img1 & img2 (cv2 images)"""
    diff = cv2.absdiff(img1, img2)
    diff = cv2.GaussianBlur(diff, (3, 3), 0)
    edges = cv2.Canny(diff, 100, 200)
    _, thresh = cv2.threshold(edges, 0, 255, cv2.THRESH_BINARY)
    contours, _ = cv2.findContours(thresh, cv2.RETR_TREE, cv2.CHAIN_APPROX_NONE)
    if not contours:
        return None
    contours.sort(key=lambda c: len(c))
    if pos is None:
        cnt = contours[-1]
        x0, y0, w, h = cv2.boundingRect(cnt)
        x1, y1 = (x0 + w, y0 + h)
        return (x0, y0, x1, y1)
    x, y = pos
    for i in range(len(contours)):
        cnt = contours[-1 - i]
        x0, y0, w, h = cv2.boundingRect(cnt)
        x1, y1 = (x0 + w, y0 + h)
        if x0 <= x <= x1 and y0 <= y <= y1:
            return (x0, y0, x1, y1)

def touch2screen(w, h, o, x, y):
    """convert touch position"""
    if o == 0:
        return (x, y)
    elif o == 1:
        return (y, w - x)
    elif o == 2:
        return (w - x, h - y)
    elif o == 3:
        return (h - y, x)
    return (x, y)

