def adafactor_optimizer_from_hparams(hparams, lr):
    """Create an Adafactor optimizer based on model hparams.

    Args:
      hparams: model hyperparameters
      lr: learning rate scalar.
    Returns:
      an AdafactorOptimizer
    Raises:
      ValueError: on illegal values"""
    if hparams.optimizer_adafactor_decay_type == 'Adam':
        decay_rate = adafactor_decay_rate_adam(hparams.optimizer_adafactor_beta2)
    elif hparams.optimizer_adafactor_decay_type == 'pow':
        decay_rate = adafactor_decay_rate_pow(hparams.optimizer_adafactor_memory_exponent)
    else:
        raise ValueError('unknown optimizer_adafactor_decay_type')
    return AdafactorOptimizer(multiply_by_parameter_scale=hparams.optimizer_adafactor_multiply_by_parameter_scale, learning_rate=lr, decay_rate=decay_rate, beta1=hparams.optimizer_adafactor_beta1, clipping_threshold=hparams.optimizer_adafactor_clipping_threshold, factored=hparams.optimizer_adafactor_factored)

def run_mnist():
    """Run MNIST training and eval loop."""
    mnist_classifier = tf.estimator.Estimator(model_fn=model_fn, model_dir=FLAGS.model_dir)
    def train_input_fn():
        """Prepare data for training."""
        ds = dataset.train(FLAGS.data_dir)
        ds_batched = ds.cache().shuffle(buffer_size=50000).batch(FLAGS.batch_size)
        ds = ds_batched.repeat(FLAGS.epochs_between_evals)
        return ds
    def eval_input_fn():
        return dataset.test(FLAGS.data_dir).batch(FLAGS.batch_size).make_one_shot_iterator().get_next()
    for _ in range(FLAGS.train_epochs // FLAGS.epochs_between_evals):
        mnist_classifier.train(input_fn=train_input_fn, hooks=None)
        eval_results = mnist_classifier.evaluate(input_fn=eval_input_fn)
        print('\nEvaluation results:\n\t%s\n' % eval_results)

def encode_dataset(dataset, vocabulary):
    """Encode from strings to token ids.

    Args:
      dataset: a tf.data.Dataset with string values.
      vocabulary: a mesh_tensorflow.transformer.Vocabulary
    Returns:
      a tf.data.Dataset with integer-vector values ending in EOS=1"""
    def encode(features):
        return {k: vocabulary.encode_tf(v) for k, v in features.items()}
    return dataset.map(encode, num_parallel_calls=tf.data.experimental.AUTOTUNE)

def pretokenized_tfds_dataset(dataset_name=gin.REQUIRED, text2self=gin.REQUIRED, tfds_data_dir=gin.REQUIRED, dataset_split=gin.REQUIRED, batch_size=gin.REQUIRED, sequence_length=gin.REQUIRED, vocabulary=None):
    """Reads a tensorflow_datasets dataset.

    Args:
      dataset_name: a string
      text2self: a boolean
      tfds_data_dir: a boolean
      dataset_split: a string
      batch_size: an integer
      sequence_length: an integer
      vocabulary: ignored
    Returns:
      a tf.data.Dataset of batches"""
    del vocabulary
    dataset = tfds.load(dataset_name, split=dataset_split, as_supervised=True, data_dir=tfds_data_dir)
    if dataset_split == 'train':
        dataset = dataset.repeat()
        dataset = dataset.shuffle(1000)
    def shift_and_append_eos(t):
        return tf.concat([t + 1, [1]], 0)
    def feature_map(inputs, targets):
        if text2self:
            return {'targets': shift_and_append_eos(targets)}
        else:
            return {'inputs': shift_and_append_eos(inputs), 'targets': shift_and_append_eos(targets)}
    dataset = dataset.map(feature_map, num_parallel_calls=tf.data.experimental.AUTOTUNE)
    return pack_and_batch(dataset, batch_size, sequence_length)

def packed_parallel_tsv_dataset(filenames=gin.REQUIRED, dataset_split=gin.REQUIRED, batch_size=gin.REQUIRED, sequence_length=gin.REQUIRED, vocabulary=gin.REQUIRED, append_eos=True, shuffle_buffer_size=10000, eos_id=1):
    """Reads parallel tab-separated text file. One example per line."""
    dataset = tf.data.TextLineDataset(filenames)
    if dataset_split == 'train':
        dataset = dataset.repeat()
        dataset = dataset.shuffle(shuffle_buffer_size)
    def _parse_fn(record):
        tokens = tf.decode_csv(record, record_defaults=[''] * 2, field_delim='\t', use_quote_delim=False)
        return {'inputs': tokens[0], 'targets': tokens[1]}
    def _encode_fn(features):
        inputs_vocabulary = vocabulary[0] if isinstance(vocabulary, tuple) else vocabulary
        targets_vocabulary = vocabulary[1] if isinstance(vocabulary, tuple) else vocabulary
        inputs_enc = inputs_vocabulary.encode_tf(features['inputs'])
        targets_enc = targets_vocabulary.encode_tf(features['targets'])
        if append_eos:
            inputs_enc = tf.concat([tf.to_int64(inputs_enc), [eos_id]], 0)
            targets_enc = tf.concat([tf.to_int64(targets_enc), [eos_id]], 0)
        return {'inputs': inputs_enc, 'targets': targets_enc}
    dataset = dataset.map(_parse_fn)
    dataset = dataset.map(_encode_fn)
    return pack_and_batch(dataset, batch_size, sequence_length)

def supervised_to_dict(dataset, text2self):
    """Turns a supervised dataset into a dataset with a feature dictionary.

    if text2self, then the features dictionary contains a "targets" key.
    else, the features dictionary contains "inputs" and "targets" keys.

    Args:
      dataset: a tf.data.Dataset
      text2self: a boolean
    Returns:
      a tf.data.Dataset"""
    def my_fn(inputs, targets):
        if text2self:
            return {'targets': targets}
        else:
            return {'inputs': inputs, 'targets': targets}
    return dataset.map(my_fn, num_parallel_calls=tf.data.experimental.AUTOTUNE)

def encode_all_features(dataset, vocabulary):
    """Encode all features.

    Args:
      dataset: a tf.data.Dataset
      vocabulary: a vocabulary.Vocabulary
    Returns:
      a tf.data.Dataset"""
    def my_fn(features):
        ret = {}
        for k, v in features.items():
            v = vocabulary.encode_tf(v)
            v = tf.concat([tf.to_int64(v), [1]], 0)
            ret[k] = v
        return ret
    return dataset.map(my_fn, num_parallel_calls=tf.data.experimental.AUTOTUNE)

def trim_and_pad_all_features(features, length):
    """Trim and pad first dimension of all features to size length."""
