def _reduction_output_shape(x, output_shape, reduced_dim):
    """Helper function to reduce_sum, etc."""
    if output_shape is None:
        if reduced_dim is None:
            return Shape([])
        else:
            if reduced_dim not in x.shape.dims:
                raise ValueError('reduced_dim=%s not in x.shape.dims=%s' % (reduced_dim, x.shape))
            return x.shape - reduced_dim
    if reduced_dim is not None:
        if [reduced_dim] != [d for d in x.shape.dims if d not in output_shape.dims]:
            raise ValueError('reduced_dim contradicts output_shape:x=%s output_shape=%s reduced_dim=%s' % (x, output_shape, reduced_dim))
    return output_shape

def gradients(ys, xs, grad_ys=None):
    """Compute gradients in dtf.

    Args:
      ys: a list of Tensors
      xs: a list of Tensors
      grad_ys: an optional list of Tensors

    Returns:
      grad_xs: a list of Tensors"""
    graph = ys[0].graph
    if not grad_ys:
        grad_ys = [Constant(y.mesh, 1.0, y.shape, y.dtype).outputs[0] for y in ys]
    downstream = set(xs)
    for op in graph.operations:
        if op.has_gradient:
            if set(op.inputs) & downstream:
                downstream |= set(op.outputs)
    tensor_to_gradient = dict(zip(ys, grad_ys))
    for op in graph.operations[::-1]:
        grad_outputs = [tensor_to_gradient.get(out) for out in op.outputs]
        if op.has_gradient and any(grad_outputs) and set(op.inputs) & downstream:
            with tf.variable_scope(op.name + '/gradients'):
                input_grads = op.gradient(grad_outputs)
                for inp, grad in zip(op.inputs, input_grads):
                    if inp in downstream and grad is not None:
                        if inp in tensor_to_gradient:
                            tensor_to_gradient[inp] += grad
                        else:
                            tensor_to_gradient[inp] = grad
    return [tensor_to_gradient.get(x, None) for x in xs]

def _einsum_equation(input_shapes, output_shape):
    """Turn shapes into an einsum equation.

    e.g. "ij,jk->ik"

    Args:
      input_shapes: a list of Shapes
      output_shape: a Shape
    Returns:
      a string"""
    ret = []
    next_letter = ord('a')
    dim_to_letter = {}
    for shape_num, shape in enumerate(input_shapes + [output_shape]):
        if shape_num == len(input_shapes):
            ret.append('->')
        elif shape_num > 0:
            ret.append(',')
        for d in shape.dims:
            if d not in dim_to_letter:
                dim_to_letter[d] = chr(next_letter)
                next_letter += 1
            ret.append(dim_to_letter[d])
    return ''.join(ret)

def is_subsequence(short_seq, long_seq):
    """Is short_seq a subsequence of long_seq."""
    if not short_seq:
        return True
    pos = 0
    for x in long_seq:
        if pos == len(short_seq):
            return True
        if short_seq[pos] == x:
            pos += 1
    if pos == len(short_seq):
        return True
    return False

def log_variable_sizes(var_list, tag, verbose=True, mesh_to_impl=None):
    """Log the sizes and shapes of variables, and the total size.

    Args:
      var_list: a list of variables; defaults to trainable_variables
      tag: a string; defaults to "Trainable Variables"
      verbose: bool, if True, log every weight; otherwise, log total size only.
      mesh_to_impl: an optional map from Mesh to MeshImpl"""
    if not var_list:
        return
    name_to_var = {v.name: v for v in var_list}
    total_size = 0
    total_slice_size = 0
    for v_name in sorted(list(name_to_var)):
        v = name_to_var[v_name]
        v_size = v.shape.size
        if mesh_to_impl is not None:
            slice_size = mesh_to_impl[v.mesh].slice_size(v.shape)
        else:
            slice_size = 0
        total_slice_size += slice_size
        if verbose:
            tf.logging.info('Variable %s size %s slice_size %s %s', v.name.ljust(60), str(v_size).ljust(12), str(slice_size).ljust(12), str(v.shape).ljust(60))
            if isinstance(v, StackedVariable):
                for n in v.original_names:
                    tf.logging.info('    ' + n)
        total_size += v_size
    tf.logging.info('%s count: %s  Total size: %s  Total slice_size: %s', tag.ljust(30), str(len(var_list)).ljust(6), str(total_size).ljust(15), str(total_slice_size).ljust(15))

def _ring_2d(m, n):
    """Ring-order of a mxn mesh.

    Args:
      m: an integer
      n: an integer
    Returns:
      a list of mxn pairs"""
    if m == 1:
        return [(0, i) for i in range(n)]
    if n == 1:
        return [(i, 0) for i in range(m)]
    if m % 2 != 0:
        tf.logging.warning('Odd dimension')
        return [(i % m, i // m) for i in range(n * m)]
    ret = [(0, 0)]
    for i in range(m // 2):
        for j in range(1, n):
            ret.append((2 * i, j))
        for j in range(n - 1, 0, -1):
            ret.append((2 * i + 1, j))
    for i in range(m - 1, 0, -1):
        ret.append((i, 0))
    return ret

def sample_discrete(distn, size=[], dtype=np.int32):
    """samples from a one-dimensional finite pmf"""
    distn = np.atleast_1d(distn)
    assert (distn >= 0).all() and distn.ndim == 1
    if (0 == distn).all():
        return np.random.randint(distn.shape[0], size=size)
    cumvals = np.cumsum(distn)
    return np.sum(np.array(random(size))[..., na] * cumvals[-1] > cumvals, axis=-1, dtype=dtype)

