def create_variable(descriptor):
    """Creates a variable from a dictionary descriptor"""
    if descriptor['type'] == 'continuous':
        return ContinuousVariable(descriptor['name'], descriptor['domain'], descriptor.get('dimensionality', 1))
    elif descriptor['type'] == 'bandit':
        return BanditVariable(descriptor['name'], descriptor['domain'], descriptor.get('dimensionality', None))
    elif descriptor['type'] == 'discrete':
        return DiscreteVariable(descriptor['name'], descriptor['domain'], descriptor.get('dimensionality', 1))
    elif descriptor['type'] == 'categorical':
        return CategoricalVariable(descriptor['name'], descriptor['domain'], descriptor.get('dimensionality', 1))
    else:
        raise InvalidConfigError('Unknown variable type ' + descriptor['type'])

def check_notebooks_for_errors(notebooks_directory):
    """Evaluates all notebooks in given directory and prints errors, if any"""
    print('Checking notebooks in directory {} for errors'.format(notebooks_directory))
    failed_notebooks_count = 0
    for file in os.listdir(notebooks_directory):
        if file.endswith('.ipynb'):
            print('Checking notebook ' + file)
            full_file_path = os.path.join(notebooks_directory, file)
            output, errors = run_notebook(full_file_path)
            if errors is not None and len(errors) > 0:
                failed_notebooks_count += 1
                print('Errors in notebook ' + file)
                print(errors)
    if failed_notebooks_count == 0:
        print('No errors found in notebooks under ' + notebooks_directory)

def run_notebook(notebook_path):
    """Execute a notebook via nbconvert and collect output.
    :returns (parsed nb object, execution errors)"""
    dirname, __ = os.path.split(notebook_path)
    os.chdir(dirname)
    with tempfile.NamedTemporaryFile(suffix='.ipynb') as fout:
        args = ['jupyter-nbconvert', '--to', 'notebook', '--execute', '--allow-errors', '--ExecutePreprocessor.timeout=300', '--output', fout.name, notebook_path]
        try:
            subprocess.check_call(args)
        except subprocess.CalledProcessError as e:
            if e.returncode == 1:
                print(e.output)
                pass
            else:
                raise
        fout.seek(0)
        nb = nbformat.read(fout, nbformat.current_nbformat)
    errors = [output for cell in nb.cells if 'outputs' in cell for output in cell['outputs'] if output.output_type == 'error']
    return (nb, errors)

def log_relative_gauss(z):
    """log_relative_gauss"""
    if z < -6:
        return (1, -1000000000000.0, -1)
    if z > 6:
        return (0, 0, 1)
    else:
        logphi = -0.5 * (z * z + l2p)
        logPhi = np.log(0.5 * special.erfc(-z / sq2))
        e = np.exp(logphi - logPhi)
    return (e, logPhi, 0)

def update_config(config_new, config_default):
    """Updates the loaded method configuration with default values."""
    if any([isinstance(v, dict) for v in list(config_new.values())]):
        for k, v in list(config_new.items()):
            if isinstance(v, dict) and k in config_default:
                update_config(config_new[k], config_default[k])
            else:
                config_default[k] = v
    else:
        config_default.update(config_new)
    return config_default

def make_naive(dt):
    """Makes an aware datetime.datetime naive in local time zone."""
    tt = dt.utctimetuple()
    ts = calendar.timegm(tt)
    local_tt = time.localtime(ts)
    return datetime.datetime(*local_tt[:6])

def close_db(fn):
    """Decorator to be used with tasks that may operate on the database."""
    @wraps(fn)
    def inner(*args, **kwargs):
        try:
            return fn(*args, **kwargs)
        finally:
            if not HUEY.immediate:
                close_old_connections()
    return inner

def find_ask():
    """Find our instance of Ask, navigating Local's and possible blueprints.

    Note: This only supports returning a reference to the first instance
    of Ask found."""
    if hasattr(current_app, 'ask'):
        return getattr(current_app, 'ask')
    elif hasattr(current_app, 'blueprints'):
        blueprints = getattr(current_app, 'blueprints')
        for blueprint_name in blueprints:
            if hasattr(blueprints[blueprint_name], 'ask'):
                return getattr(blueprints[blueprint_name], 'ask')

def top_stream(cache, user_id):
    """Peek at the top of the stack in the cache.

    :param cache: werkzeug BasicCache-like object
    :param user_id: id of user, used as key in cache

    :return: top item in user's cached stack, otherwise None"""
    if not user_id:
        return None
    stack = cache.get(user_id)
    if stack is None:
        return None
    return stack.pop()

def get_auth_instance(credentials, auth_type):
    """Returns an *Auth instance suitable for the requests package"""
    model = AUTH_TYPE_MAP[auth_type]
    if model is None:
        return None
    username = credentials.username
    if auth_type == NTLM and credentials.type == credentials.EMAIL:
        username = '\\' + username
    if auth_type == GSSAPI:
        return model()
    return model(username=username, password=credentials.password)

def split_field_path(field_path):
    """Return the individual parts of a field path that may, apart from the fieldname, have label and subfield parts.
    Examples:
        'start' -> ('start', None, None)
        'phone_numbers__PrimaryPhone' -> ('phone_numbers', 'PrimaryPhone', None)
        'physical_addresses__Home__street' -> ('physical_addresses', 'Home', 'street')"""
    if not isinstance(field_path, string_types):
        raise ValueError('Field path %r must be a string' % field_path)
    search_parts = field_path.split('__')
    field = search_parts[0]
    try:
        label = search_parts[1]
    except IndexError:
        label = None
    try:
        subfield = search_parts[2]
    except IndexError:
        subfield = None
    return (field, label, subfield)

def is_iterable(value, generators_allowed=False):
    """Checks if value is a list-like object. Don't match generators and generator-like objects here by default, because
    callers don't necessarily guarantee that they only iterate the value once. Take care to not match string types and
    bytes.

    :param value: any type of object
    :param generators_allowed: if True, generators will be treated as iterable
    :return: True or False"""
    if generators_allowed:
        if not isinstance(value, string_types + (bytes,)) and hasattr(value, '__iter__'):
            return True
    elif isinstance(value, (tuple, list, set)):
        return True
    return False

def chunkify(iterable, chunksize):
    """Splits an iterable into chunks of size ``chunksize``. The last chunk may be smaller than ``chunksize``."""
    from .queryset import QuerySet
    if hasattr(iterable, '__getitem__') and (not isinstance(iterable, QuerySet)):
        for i in range(0, len(iterable), chunksize):
            yield iterable[i:i + chunksize]
    else:
        chunk = []
        for i in iterable:
            chunk.append(i)
            if len(chunk) == chunksize:
                yield chunk
                chunk = []
        if chunk:
            yield chunk

def peek(iterable):
    """Checks if an iterable is empty and returns status and the rewinded iterable"""
    from .queryset import QuerySet
    if isinstance(iterable, QuerySet):
        raise ValueError('Cannot peek on a QuerySet')
    if hasattr(iterable, '__len__'):
        return (not iterable, iterable)
    try:
        first = next(iterable)
    except StopIteration:
        return (True, iterable)
    return (False, itertools.chain([first], iterable))

def xml_to_str(tree, encoding=None, xml_declaration=False):
    """Serialize an XML tree. Returns unicode if 'encoding' is None. Otherwise, we return encoded 'bytes'."""
    if xml_declaration and (not encoding):
        raise ValueError("'xml_declaration' is not supported when 'encoding' is None")
    if encoding:
        return tostring(tree, encoding=encoding, xml_declaration=True)
    return tostring(tree, encoding=text_type, xml_declaration=False)

def is_xml(text):
    """Helper function. Lightweight test if response is an XML doc"""
    bom_len = len(BOM_UTF8)
    if text[:bom_len] == BOM_UTF8:
        return text[bom_len:bom_len + 5] == b'<?xml'
    return text[:5] == b'<?xml'

def generate_map(timeout=10):
    """Helper method to update the map if the CLDR database is updated"""
    r = requests.get(CLDR_WINZONE_URL, timeout=timeout)
    if r.status_code != 200:
        raise ValueError('Unexpected response: %s' % r)
    tz_map = {}
    for e in to_xml(r.content).find('windowsZones').find('mapTimezones').findall('mapZone'):
        for location in e.get('type').split(' '):
            if e.get('territory') == DEFAULT_TERRITORY or location not in tz_map:
                tz_map[location] = (e.get('other'), e.get('territory'))
    return tz_map

