def wr_tsv(fout_tsv, tsv_data, **kws):
    """Write a file of tab-separated table data"""
    items_str = 'items' if 'items' not in kws else kws['items']
    if tsv_data:
        ifstrm = sys.stdout if fout_tsv is None else open(fout_tsv, 'w')
        num_items = prt_tsv(ifstrm, tsv_data, **kws)
        if fout_tsv is not None:
            sys.stdout.write('  {N:>5} {ITEMS} WROTE: {FOUT}\n'.format(N=num_items, ITEMS=items_str, FOUT=fout_tsv))
            ifstrm.close()
    else:
        sys.stdout.write('      0 {ITEMS}. NOT WRITING {FOUT}\n'.format(ITEMS=items_str, FOUT=fout_tsv))

def prt_tsv(prt, data_nts, **kws):
    """Print tab-separated table headers and data"""
    prt_tsv_hdr(prt, data_nts, **kws)
    return prt_tsv_dat(prt, data_nts, **kws)

def prt_tsv_dat(prt, data_nts, **kws):
    """Print tab-separated table data"""
    sep = '\t' if 'sep' not in kws else kws['sep']
    fld2fmt = None if 'fld2fmt' not in kws else kws['fld2fmt']
    if 'sort_by' in kws:
        data_nts = sorted(data_nts, key=kws['sort_by'])
    prt_if = kws['prt_if'] if 'prt_if' in kws else None
    prt_flds = kws['prt_flds'] if 'prt_flds' in kws else data_nts[0]._fields
    items = 0
    for nt_data_row in data_nts:
        if prt_if is None or prt_if(nt_data_row):
            if fld2fmt is not None:
                row_fld_vals = [(fld, getattr(nt_data_row, fld)) for fld in prt_flds]
                row_vals = _fmt_fields(row_fld_vals, fld2fmt)
            else:
                row_vals = [getattr(nt_data_row, fld) for fld in prt_flds]
            prt.write('{}\n'.format(sep.join((str(d) for d in row_vals))))
            items += 1
    return items

def _fmt_fields(fld_vals, fld2fmt):
    """Optional user-formatting of specific fields, eg, pval: '{:8.2e}'."""
    vals = []
    for fld, val in fld_vals:
        if fld in fld2fmt:
            val = fld2fmt[fld].format(val)
        vals.append(val)
    return vals

def mk_fmtfld(nt_item, joinchr=' ', eol='\n'):
    """Given a namedtuple, return a format_field string."""
    fldstrs = []
    fld2fmt = {'hdrgo': lambda f: '{{{FLD}:1,}}'.format(FLD=f), 'dcnt': lambda f: '{{{FLD}:6,}}'.format(FLD=f), 'level': lambda f: 'L{{{FLD}:02,}}'.format(FLD=f), 'depth': lambda f: 'D{{{FLD}:02,}}'.format(FLD=f)}
    for fld in nt_item._fields:
        if fld in fld2fmt:
            val = fld2fmt[fld](fld)
        else:
            val = '{{{FLD}}}'.format(FLD=fld)
        fldstrs.append(val)
    return '{LINE}{EOL}'.format(LINE=joinchr.join(fldstrs), EOL=eol)

def get_most_specific_dcnt(goids, go2nt):
    """Get the GO ID with the lowest descendants count."""
    return min(_get_go2nt(goids, go2nt), key=lambda t: t[1].dcnt)[0]

def get_most_specific_tinfo(goids, go2nt):
    """Get the GO ID with the highest GO term annotation information value."""
    return max(_get_go2nt(goids, go2nt), key=lambda t: t[1].tinfo)[0]

def get_most_specific_tinfo_dcnt(goids, go2nt):
    """Get the GO ID with the highest GO term annotation information value."""
    return max(_get_go2nt(goids, go2nt), key=lambda t: [t[1].tinfo, t[1].dcnt])[0]

def get_paths_goobjs(go_objs, go_top=None, go2obj=None):
    """Given a list of GO objects, return: paths, user GOs as ints, all GO terms paths."""
    go_paths = []
    go_all = set()
    pathobj = GoPaths()
    for go_obj in go_objs:
        if go_obj.id not in go_all:
            paths_curr = pathobj.get_paths_from_to(go_obj, go_top, True)
            if paths_curr:
                for path_goobjs in paths_curr:
                    for path_goobj in path_goobjs:
                        goid = path_goobj.id
                        if goid not in go_all:
                            go_all.add(goid)
                            go2obj[goid] = path_goobj
                go_paths.extend((path for path in paths_curr))
    return (go_paths, go_all)

def paths2edges(paths):
    """[8079, 8135, 3723, 3676, 1901363, 5488, 3674]"""
    edges_all = set()
    for path in paths:
        for edge in path2edges(path):
            edges_all.add(edge)
    return edges_all

def path2edges(path):
    """Given: [2000343, 32722, 1819]   Return: set([(2000343, 32722), (32722, 1819)])."""
    node_a, node_b = tee(path)
    next(node_b, None)
    return zip(node_a, node_b)

