    return flds_all

def resnik_sim(go_id1, go_id2, godag, termcounts):
    """Computes Resnik's similarity measure."""
    goterm1 = godag[go_id1]
    goterm2 = godag[go_id2]
    if goterm1.namespace == goterm2.namespace:
        msca_goid = deepest_common_ancestor([go_id1, go_id2], godag)
        return get_info_content(msca_goid, termcounts)

def lin_sim(goid1, goid2, godag, termcnts):
    """Computes Lin's similarity measure."""
    sim_r = resnik_sim(goid1, goid2, godag, termcnts)
    return lin_sim_calc(goid1, goid2, sim_r, termcnts)

def lin_sim_calc(goid1, goid2, sim_r, termcnts):
    """Computes Lin's similarity measure using pre-calculated Resnik's similarities."""
    if sim_r is not None:
        info = get_info_content(goid1, termcnts) + get_info_content(goid2, termcnts)
        if info != 0:
            return 2 * sim_r / info

def deepest_common_ancestor(goterms, godag):
    """This function gets the nearest common ancestor
    using the above function.
    Only returns single most specific - assumes unique exists."""
    return max(common_parent_go_ids(goterms, godag), key=lambda t: godag[t].depth)

def semantic_distance(go_id1, go_id2, godag, branch_dist=None):
    """Finds the semantic distance (minimum number of connecting branches)
    between two GO terms."""
    return min_branch_length(go_id1, go_id2, godag, branch_dist)

def semantic_similarity(go_id1, go_id2, godag, branch_dist=None):
    """Finds the semantic similarity (inverse of the semantic distance)
    between two GO terms."""
    dist = semantic_distance(go_id1, go_id2, godag, branch_dist)
    if dist is not None:
        return 1.0 / float(dist)

def get_all_parents(go_objs):
    """Return a set containing all GO Term parents of multiple GOTerm objects."""
    go_parents = set()
    for go_obj in go_objs:
        go_parents |= go_obj.get_all_parents()
    return go_parents

def get_objanno(fin_anno, anno_type=None, **kws):
    """Read annotations in GAF, GPAD, Entrez gene2go, or text format."""
    anno_type = get_anno_desc(fin_anno, anno_type)
    if anno_type is not None:
        if anno_type == 'gene2go':
            return Gene2GoReader(fin_anno, **kws)
        if anno_type == 'gaf':
            return GafReader(fin_anno, hdr_only=kws.get('hdr_only', False), prt=kws.get('prt', sys.stdout), allow_missing_symbol=kws.get('allow_missing_symbol', False))
        if anno_type == 'gpad':
            hdr_only = kws.get('hdr_only', False)
            return GpadReader(fin_anno, hdr_only)
        if anno_type == 'id2gos':
            return IdToGosReader(fin_anno)
    raise RuntimeError('UNEXPECTED ANNOTATION FILE FORMAT: {F} {D}'.format(F=fin_anno, D=anno_type))

def update_association(assc_gene2gos, go2obj):
    """Add the GO parents of a gene's associated GO IDs to the gene's association."""
    goids_avail = set(go2obj)
    goid_sets = assc_gene2gos.values()
    goids_assoc_all = set.union(*goid_sets)
    goids_assoc_cur = goids_assoc_all.intersection(goids_avail)
    go2obj_assc = {go: go2obj[go] for go in goids_assoc_cur}
    go2parents = get_go2parents_go2obj(go2obj_assc)
    for goids_cur in goid_sets:
        parents = set()
        for goid in goids_cur.intersection(goids_avail):
            parents.update(go2parents[goid])
        goids_cur.update(parents)
    goids_bad = goids_assoc_all.difference(goids_avail)
    if goids_bad:
        sys.stderr.write('{N} GO IDs NOT FOUND IN ASSOCIATION: {GOs}\n'.format(N=len(goids_bad), GOs=' '.join(goids_bad)))

def get_go2obj_unique(go2obj):
    """If GO keys point to the same GOTerm, return new go2obj w/no duplicates."""
    goid2gokeys = cx.defaultdict(set)
    for goid, goobj in go2obj.items():
        goid2gokeys[goobj.id].add(goid)
    go_unique = set()
    for goid, gos_seen in goid2gokeys.items():
        if goid in gos_seen:
            go_unique.add(goid)
        else:
            go_unique.add(next(iter(gos_seen)))
    return go_unique

def get_goobjs_altgo2goobj(go2obj):
    """Separate alt GO IDs and key GO IDs."""
    goobjs = set()
    altgo2goobj = {}
    for goid, goobj in go2obj.items():
        goobjs.add(goobj)
        if goid != goobj.id:
            altgo2goobj[goid] = goobj
    return (goobjs, altgo2goobj)

def add_alt_goids(go2values, altgo2goobj):
    """Add alternate source GO IDs."""
    for goobj_key in altgo2goobj.values():
        values_curr = go2values[goobj_key.id]
        for goid_alt in goobj_key.alt_ids:
            go2values[goid_alt] = values_curr
    return go2values

def fill_altgoids(go2obj):
    """Given a go2obj containing key GO IDs, fill with all alternate GO IDs."""
    alt2obj = {altgo: goobj for goobj in go2obj.values() for altgo in goobj.alt_ids}
    for goid, goobj in alt2obj.items():
        go2obj[goid] = goobj

def fill_relationshipobjs(go2obj, relationships):
    """Add GO IDs to go2obj that are involved in relationships."""
    obj = RelationshipFill(go2obj, relationships)
    for goobj in go2obj.values():
        if goobj.relationship:
            obj.fill_relationshipgo2obj(goobj)
        if goobj.relationship_rev:
            obj.fill_relationshiprevgo2obj(goobj)

def fill_childgoid2obj(childgoid2obj, parent_obj):
    """Fill childgoid2obj with all child key GO IDs and their objects."""
    for child_obj in parent_obj.children:
        if child_obj.id not in childgoid2obj:
            childgoid2obj[child_obj.id] = child_obj
            fill_childgoid2obj(childgoid2obj, child_obj)

def get_leaf_children(gos_user, go2obj_arg):
    """Find all the GO descendants under all user GO IDs. Return leaf-level GO IDs."""
    childgoid2obj = {}
    for goid_usr in gos_user:
        goobj_usr = go2obj_arg[goid_usr]
        fill_childgoid2obj(childgoid2obj, goobj_usr)
    return set((go for go, o in childgoid2obj.items() if not o.children))

def chk_goids(goids, msg=None, raise_except=True):
    """check that all GO IDs have the proper format."""
    for goid in goids:
        if not goid_is_valid(goid):
            if raise_except:
                raise RuntimeError('BAD GO({GO}): {MSG}'.format(GO=goid, MSG=msg))
            else:
                return goid

def read_sections(sections_file, exclude_ungrouped=False, prt=sys.stdout):
    """Get sections and GO grouping hdrgos from file, if sections exist."""
    if sections_file is None:
        return None
    assert isinstance(sections_file, str), 'BAD SECTIONS FILENAME({S})'.format(S=sections_file)
    if os.path.exists(sections_file):
        return ReadGoids().read_sections(sections_file, False, exclude_ungrouped)
    if '/' not in sections_file and '\\\\' not in sections_file and (pkgutil.find_loader(sections_file) is not None):
        mod = importlib.import_module(sections_file)
        var = getattr(mod, 'SECTIONS', None)
        if var is not None:
            dat = SummarySec2dHdrGos().summarize_sec2hdrgos(var)
            print(Grouper.fmtsum.format(GO_DESC='hdr', SECs=len(dat['S']), GOs=len(dat['G']), UNGRP='N/A', undesc='unused', ACTION='IMPORTED: ', FILE=sections_file))
            return var
        raise RuntimeError("NO 'SECTIONS' VARIABLE FOUND IN MODULE({M})".format(M=sections_file))
    if prt:
        prt.write('CANNOT READ: {SEC}\n'.format(SEC=sections_file))

