def extract_kwargs(args, exp_keys, exp_elems):
    """Return user-specified keyword args in a dictionary and a set (for True/False items)."""
    arg_dict = {}
    arg_set = set()
    for key, val in args.items():
        if exp_keys is not None and key in exp_keys and val:
            arg_dict[key] = val
        elif exp_elems is not None and key in exp_elems and val:
            arg_set.add(key)
    return {'dict': arg_dict, 'set': arg_set}

def get_kwargs_set(args, exp_elem2dflt):
    """Return user-specified keyword args in a dictionary and a set (for True/False items)."""
    arg_set = set()
    for key, val in args.items():
        if exp_elem2dflt is not None and key in exp_elem2dflt and val:
            arg_set.add(key)
    for key, dfltval in exp_elem2dflt.items():
        if dfltval and key not in arg_set:
            arg_set.add(key)
    return arg_set

def get_kwargs(args, exp_keys, exp_elems):
    """Return user-specified keyword args in a dictionary and a set (for True/False items)."""
    arg_dict = {}
    for key, val in args.items():
        if exp_keys is not None and key in exp_keys and val:
            if isinstance(val, str):
                val = val.strip()
            arg_dict[key] = val
        elif exp_elems is not None and key in exp_elems and val:
            arg_dict[key] = True
    return arg_dict

def count_terms(geneset, assoc, obo_dag):
    """count the number of terms in the study group
    """
    term_cnt = Counter()
    for gene in (g for g in geneset if g in assoc):
        for goid in assoc[gene]:
            if goid in obo_dag:
                term_cnt[obo_dag[goid].id] += 1
    return term_cnt

def get_terms(desc, geneset, assoc, obo_dag, log):
    """Get the terms in the study group
    """
    _chk_gene2go(assoc)
    term2itemids = defaultdict(set)
    genes = [g for g in geneset if g in assoc]
    for gene in genes:
        for goid in assoc[gene]:
            if goid in obo_dag:
                term2itemids[obo_dag[goid].id].add(gene)
    if log is not None:
        num_stu = len(genes)
        num_pop = len(geneset)
        perc = 100.0 * num_stu / num_pop if num_pop != 0 else 0.0
        log.write('{P:3.0f}% {N:>6,} of {M:>6,} {DESC} items found in association\n'.format(DESC=desc, N=num_stu, M=num_pop, P=perc))
    return term2itemids

def is_ratio_different(min_ratio, study_go, study_n, pop_go, pop_n):
    """check if the ratio go /n is different between the study group and
    the population"""
    if min_ratio is None:
        return True
    stu_ratio = float(study_go) / study_n
    pop_ratio = float(pop_go) / pop_n
    if stu_ratio == 0.0:
        stu_ratio = 1e-07
    if pop_ratio == 0.0:
        pop_ratio = 1e-07
    if stu_ratio > pop_ratio:
        return stu_ratio / pop_ratio > min_ratio
    return pop_ratio / stu_ratio > min_ratio

def add_to_typedef(typedef_curr, obo_line):
    """Add new fields to the current typedef."""
    if obo_line[:4] == 'id: ':
        assert not typedef_curr.item_id
        item_id = obo_line[4:]
        typedef_curr.item_id = item_id
    elif obo_line[:6] == 'name: ':
        assert not typedef_curr.name
        typedef_curr.name = obo_line[6:]
    elif obo_line[:11] == 'namespace: ':
        assert not typedef_curr.namespace
        typedef_curr.namespace = obo_line[11:]
    elif obo_line[17:] == 'transitive_over: ':
        field_value = obo_line[17:].split('!')[0].rstrip()
        typedef_curr.transitive_over.append(field_value)
    elif obo_line[12:] == 'inverse_of':
        assert not typedef_curr.inverse_of
        field_value = obo_line[12:].split('!')[0].rstrip()
        typedef_curr.inverse_of = field_value

def get_unique_fields(fld_lists):
    """Get unique namedtuple fields, despite potential duplicates in lists of fields."""
    flds = []
    fld_set = set([f for flst in fld_lists for f in flst])
    fld_seen = set()
    for fld_list in fld_lists:
        for fld in fld_list:
            if fld not in fld_seen:
                flds.append(fld)
                fld_seen.add(fld)
    assert len(flds) == len(fld_set)
    return flds

def _combine_nt_vals(lst0_lstn, flds, dflt_null):
    """Given a list of lists of nts, return a single namedtuple."""
    vals = []
    for fld in flds:
        fld_seen = False
        for nt_curr in lst0_lstn:
            if hasattr(nt_curr, fld):
                vals.append(getattr(nt_curr, fld))
                fld_seen = True
                break
        if fld_seen is False:
            vals.append(dflt_null)
    return vals

def no_duplicates_sections2d(sections2d, prt=None):
    """Check for duplicate header GO IDs in the 2-D sections variable."""
    no_dups = True
    ctr = cx.Counter()
    for _, hdrgos in sections2d:
        for goid in hdrgos:
            ctr[goid] += 1
    for goid, cnt in ctr.most_common():
        if cnt == 1:
            break
        no_dups = False
        if prt is not None:
            prt.write('**SECTIONS WARNING FOUND: {N:3} {GO}\n'.format(N=cnt, GO=goid))
    return no_dups

