def convert_parameter_shape(pb):
    """Convert the shape of some parameters so they fit NNabla's requirements.
    We do this as a post conversion because in the future we may be able to
    delete the whole conversion if NNabla's code gets changed"""
    if len(pb.network) != 1:
        raise ValueError('NNP with more then a single network is currently not supported')
    net = pb.network[0]
    batch_norm_constants = []
    for f in net.function:
        if f.type == 'BatchNormalization':
            batch_norm_constants.extend(f.input[1:5])
    for c in batch_norm_constants:
        for v in net.variable:
            if v.name == c:
                size = v.shape.dim[0]
                del v.shape.dim[:]
                v.shape.dim.extend([1, size, 1, 1])
                break
        for p in pb.parameter:
            if p.variable_name == c:
                size = p.shape.dim[0]
                del p.shape.dim[:]
                p.shape.dim.extend([1, size, 1, 1])
                break

def resolve_reshape_params(inputs, function_proto, batch_size):
    """Resolve shape parameter and returns shape.
    """
    f = function_proto
    negative_count = 0
    for d in f.reshape_param.shape.dim:
        if d < 0:
            negative_count += 1
    if negative_count > 1:
        raise ValueError('Reshape: shape has multiple negative number.')
    shape = tuple([d if d >= 0 else batch_size for d in f.reshape_param.shape.dim])
    if numpy.prod(shape) != numpy.prod(inputs[0].shape):
        shape = (batch_size,) + shape
        if numpy.prod(shape) != numpy.prod(inputs[0].shape):
            raise ValueError('Shape after filling batch dimension does not match the input shape. prod({}) != prod({})'.format(shape, inputs[0].shape))
    return shape

def resolve_broadcast_params(inputs, function_proto, batch_size):
    """Resolve shape parameter and returns shape.
    """
    f = function_proto
    negative_count = 0
    for d in f.broadcast_param.shape.dim:
        if d < 0:
            negative_count += 1
    if negative_count > 1:
        raise ValueError('Reshape: shape has multiple negative number.')
    shape = tuple([d if d >= 0 else batch_size for d in f.broadcast_param.shape.dim])
    return shape

def replace_negative_size_with_batch_size(shape, batch_size):
    """Replace all dimensions with negative values to batch size"""
    sl = []
    for d in shape.dim:
        if d < 0:
            sl.append(batch_size)
        else:
            sl.append(d)
    out_shape = nnabla_pb2.Shape()
    out_shape.dim.extend(sl)
    return out_shape

def _get_variable_name_or_register(var, variables, names, params, prefix):
    """Args:
        var (~nnabla.Variable)
        variables (OrderedDict)
        names (dict): Force name table, Variable -> str
        params (dict): NdArray -> str
        prefix(str)"""
    if var not in variables.values():
        vname = prefix
        if var.data in params:
            vname = params[var.data]
        elif var in names:
            vname = names[var]
        vname = _get_unique_variable_name(vname, variables)
        variables[vname] = var
    else:
        vname = list(variables.keys())[list(variables.values()).index(var)]
    return vname

