def decode_response(response):
    """If the response is compressed with gzip or deflate:
      1. decompress the response body
      2. delete the content-encoding header
      3. update content-length header to decompressed length"""
    def is_compressed(headers):
        encoding = headers.get('content-encoding', [])
        return encoding and encoding[0] in ('gzip', 'deflate')
    def decompress_body(body, encoding):
        """Returns decompressed body according to encoding using zlib.
        to (de-)compress gzip format, use wbits = zlib.MAX_WBITS | 16"""
        if encoding == 'gzip':
            return zlib.decompress(body, zlib.MAX_WBITS | 16)
        else:
            return zlib.decompress(body)
    response = copy.deepcopy(response)
    headers = CaseInsensitiveDict(response['headers'])
    if is_compressed(headers):
        encoding = headers['content-encoding'][0]
        headers['content-encoding'].remove(encoding)
        if not headers['content-encoding']:
            del headers['content-encoding']
        new_body = decompress_body(response['body']['string'], encoding)
        response['body']['string'] = new_body
        headers['content-length'] = [str(len(new_body))]
        response['headers'] = dict(headers)
    return response

def register_layouts(layouts, app, url='/api/props/', brand='Pyxley'):
    """register UILayout with the flask app

    create a function that will send props for each UILayout

    Args:
        layouts (dict): dict of UILayout objects by name
        app (object): flask app
        url (string): address of props; default is /api/props/"""
    def props(name):
        if name not in layouts:
            name = list(layouts.keys())[0]
        return jsonify({'layouts': layouts[name]['layout']})
    def apps():
        paths = []
        for i, k in enumerate(layouts.keys()):
            if i == 0:
                paths.append({'path': '/', 'label': layouts[k].get('title', k)})
            paths.append({'path': '/' + k, 'label': layouts[k].get('title', k)})
        return jsonify({'brand': brand, 'navlinks': paths})
    app.add_url_rule(url + '<string:name>/', view_func=props)
    app.add_url_rule(url, view_func=apps)

