def use_setuptools(version=DEFAULT_VERSION, download_base=DEFAULT_URL, to_dir=DEFAULT_SAVE_DIR, download_delay=15):
    """Ensure that a setuptools version is installed.

    Return None. Raise SystemExit if the requested version
    or later cannot be installed."""
    to_dir = os.path.abspath(to_dir)
    rep_modules = ('pkg_resources', 'setuptools')
    imported = set(sys.modules).intersection(rep_modules)
    try:
        import pkg_resources
        pkg_resources.require('setuptools>=' + version)
        return
    except ImportError:
        pass
    except pkg_resources.DistributionNotFound:
        pass
    except pkg_resources.VersionConflict as VC_err:
        if imported:
            _conflict_bail(VC_err, version)
        del pkg_resources
        _unload_pkg_resources()
    return _do_download(version, download_base, to_dir, download_delay)

def _download_args(options):
    """Return args for download_setuptools function from cmdline args."""
    return dict(version=options.version, download_base=options.download_base, downloader_factory=options.downloader_factory, to_dir=options.to_dir)

def main():
    """Install or upgrade setuptools and EasyInstall."""
    options = _parse_args()
    archive = download_setuptools(**_download_args(options))
    return _install(archive, _build_install_args(options))

