def config(show, reset, **params):
    """Inspect and configure parameters in your local sentinelhub configuration file

    \x08
    Example:
      sentinelhub.config --show
      sentinelhub.config --instance_id <new instance id>
      sentinelhub.config --max_download_attempts 5 --download_sleep_time 20 --download_timeout_seconds 120"""
    sh_config = SHConfig()
    if reset:
        sh_config.reset()
    for param, value in params.items():
        if value is not None:
            try:
                value = int(value)
            except ValueError:
                if value.lower() == 'true':
                    value = True
                elif value.lower() == 'false':
                    value = False
            if getattr(sh_config, param) != value:
                setattr(sh_config, param, value)
    old_config = SHConfig()
    sh_config.save()
    for param in sh_config.get_params():
        if sh_config[param] != old_config[param]:
            value = sh_config[param]
            if isinstance(value, str):
                value = "'{}'".format(value)
            click.echo("The value of parameter '{}' was updated to {}".format(param, value))
    if show:
        click.echo(str(sh_config))
        click.echo('Configuration file location: {}'.format(sh_config.get_config_location()))

def make_folder(path):
    """Create folder at input path recursively

    Create a folder specified by input path if one
    does not exist already

    :param path: input path to folder to be created
    :type path: str
    :raises: os.error if folder cannot be created"""
    if not os.path.exists(path):
        try:
            os.makedirs(path)
        except OSError as exception:
            if exception.errno != errno.EEXIST:
                raise ValueError('Specified folder is not writable: %s\nPlease check permissions or set a new valid folder.' % path)

def size(pathname):
    """Returns size of a file or folder in Bytes

    :param pathname: path to file or folder to be sized
    :type pathname: str
    :return: size of file or folder in Bytes
    :rtype: int
    :raises: os.error if file is not accessible"""
    if os.path.isfile(pathname):
        return os.path.getsize(pathname)
    return sum([size('{}/{}'.format(pathname, name)) for name in get_content_list(pathname)])

def read_data(filename, data_format=None):
    """Read image data from file

    This function reads input data from file. The format of the file
    can be specified in ``data_format``. If not specified, the format is
    guessed from the extension of the filename.

    :param filename: filename to read data from
    :type filename: str
    :param data_format: format of filename. Default is ``None``
    :type data_format: MimeType
    :return: data read from filename
    :raises: exception if filename does not exist"""
    if not os.path.exists(filename):
        raise ValueError('Filename {} does not exist'.format(filename))
    if not isinstance(data_format, MimeType):
        data_format = get_data_format(filename)
    if data_format.is_tiff_format():
        return read_tiff_image(filename)
    if data_format is MimeType.JP2:
        return read_jp2_image(filename)
    if data_format.is_image_format():
        return read_image(filename)
    try:
        return {MimeType.TXT: read_text, MimeType.CSV: read_csv, MimeType.JSON: read_json, MimeType.XML: read_xml, MimeType.GML: read_xml, MimeType.SAFE: read_xml}[data_format](filename)
    except KeyError:
        raise ValueError('Reading data format .{} is not supported'.format(data_format.value))

def write_tiff_image(filename, image, compress=False):
    """Write image data to TIFF file

    :param filename: name of file to write data to
    :type filename: str
    :param image: image data to write to file
    :type image: numpy array
    :param compress: whether to compress data. If ``True``, lzma compression is used. Default is ``False``
    :type compress: bool"""
    if compress:
        return tiff.imsave(filename, image, compress='lzma')
    return tiff.imsave(filename, image)

def write_image(filename, image):
    """Write image data to PNG, JPG file

    :param filename: name of PNG or JPG file to write data to
    :type filename: str
    :param image: image data to write to file
    :type image: numpy array"""
    data_format = get_data_format(filename)
    if data_format is MimeType.JPG:
        LOGGER.warning('Warning: jpeg is a lossy format therefore saved data will be modified.')
    return Image.fromarray(image).save(filename)

def _do_request(request):
    """Executes download request
    :param request: A request
    :type request: DownloadRequest
    :return: Response of the request
    :rtype: requests.Response"""
    if request.request_type is RequestType.GET:
        return requests.get(request.url, headers=request.headers)
    if request.request_type is RequestType.POST:
        return requests.post(request.url, data=json.dumps(request.post_values), headers=request.headers)
    raise ValueError('Invalid request type {}'.format(request.request_type))

def _is_temporal_problem(exception):
    """Checks if the obtained exception is temporal and if download attempt should be repeated

    :param exception: Exception raised during download
    :type exception: Exception
    :return: True if exception is temporal and False otherwise
    :rtype: bool"""
    try:
        return isinstance(exception, (requests.ConnectionError, requests.Timeout))
    except AttributeError:
        return isinstance(exception, requests.ConnectionError)

def _create_download_failed_message(exception, url):
    """Creates message describing why download has failed

    :param exception: Exception raised during download
    :type exception: Exception
    :param url: An URL from where download was attempted
    :type url: str
    :return: Error message
    :rtype: str"""
    message = 'Failed to download from:\n{}\nwith {}:\n{}'.format(url, exception.__class__.__name__, exception)
    if _is_temporal_problem(exception):
        if isinstance(exception, requests.ConnectionError):
            message += '\nPlease check your internet connection and try again.'
        else:
            message += '\nThere might be a problem in connection or the server failed to process your request. Please try again.'
    elif isinstance(exception, requests.HTTPError):
        try:
            server_message = ''
            for elem in decode_data(exception.response.content, MimeType.XML):
                if 'ServiceException' in elem.tag or 'Message' in elem.tag:
                    server_message += elem.text.strip('\n\t ')
        except ElementTree.ParseError:
            server_message = exception.response.text
        message += '\nServer response: "{}"'.format(server_message)
    return message

def decode_data(response_content, data_type, entire_response=None):
    """Interprets downloaded data and returns it.

    :param response_content: downloaded data (i.e. json, png, tiff, xml, zip, ... file)
    :type response_content: bytes
    :param data_type: expected downloaded data type
    :type data_type: constants.MimeType
    :param entire_response: A response obtained from execution of download request
    :type entire_response: requests.Response or dict or None
    :return: downloaded data
    :rtype: numpy array in case of image data type, or other possible data type
    :raises: ValueError"""
    LOGGER.debug('data_type=%s', data_type)
    if data_type is MimeType.JSON:
        if isinstance(entire_response, requests.Response):
            return entire_response.json()
        return json.loads(response_content.decode('utf-8'))
    if MimeType.is_image_format(data_type):
        return decode_image(response_content, data_type)
    if data_type is MimeType.XML or data_type is MimeType.GML or data_type is MimeType.SAFE:
        return ElementTree.fromstring(response_content)
    try:
        return {MimeType.RAW: response_content, MimeType.TXT: response_content, MimeType.REQUESTS_RESPONSE: entire_response, MimeType.ZIP: BytesIO(response_content)}[data_type]
    except KeyError:
        raise ValueError('Unknown response data type {}'.format(data_type))

def gpp(V, E):
    """gpp -- model for the graph partitioning problem
    Parameters:
        - V: set/list of nodes in the graph
        - E: set/list of edges in the graph
    Returns a model, ready to be solved."""
    model = Model('gpp')
    x = {}
    y = {}
    for i in V:
        x[i] = model.addVar(vtype='B', name='x(%s)' % i)
    for i, j in E:
        y[i, j] = model.addVar(vtype='B', name='y(%s,%s)' % (i, j))
    model.addCons(quicksum((x[i] for i in V)) == len(V) / 2, 'Partition')
    for i, j in E:
        model.addCons(x[i] - x[j] <= y[i, j], 'Edge(%s,%s)' % (i, j))
        model.addCons(x[j] - x[i] <= y[i, j], 'Edge(%s,%s)' % (j, i))
    model.setObjective(quicksum((y[i, j] for i, j in E)), 'minimize')
    model.data = x
    return model

def maxflow(V, M, source, sink):
    """maxflow: maximize flow from source to sink, taking into account arc capacities M
    Parameters:
        - V: set of vertices
        - M[i,j]: dictionary or capacity for arcs (i,j)
        - source: flow origin
        - sink: flow target
    Returns a model, ready to be solved.
    """
    model = Model('maxflow')
    f = {}
    for i, j in M:
        f[i, j] = model.addVar(lb=-M[i, j], ub=M[i, j], name='flow(%s,%s)' % (i, j))
    cons = {}
    for i in V:
        if i != source and i != sink:
            cons[i] = model.addCons(quicksum((f[i, j] for j in V if i < j and (i, j) in M)) - quicksum((f[j, i] for j in V if i > j and (j, i) in M)) == 0, 'FlowCons(%s)' % i)
    model.setObjective(quicksum((f[i, j] for i, j in M if i == source)), 'maximize')
    model.data = (f, cons)
    return model

def permutation_flow_shop(n, m, p):
    """gpp -- model for the graph partitioning problem
    Parameters:
        - n: number of jobs
        - m: number of machines
        - p[i,j]: processing time of job i on machine j
    Returns a model, ready to be solved."""
    model = Model('permutation flow shop')
    x, s, f = ({}, {}, {})
    for j in range(1, n + 1):
        for k in range(1, n + 1):
            x[j, k] = model.addVar(vtype='B', name='x(%s,%s)' % (j, k))
    for i in range(1, m + 1):
        for k in range(1, n + 1):
            s[i, k] = model.addVar(vtype='C', name='start(%s,%s)' % (i, k))
            f[i, k] = model.addVar(vtype='C', name='finish(%s,%s)' % (i, k))
    for j in range(1, n + 1):
        model.addCons(quicksum((x[j, k] for k in range(1, n + 1))) == 1, 'Assign1(%s)' % j)
        model.addCons(quicksum((x[k, j] for k in range(1, n + 1))) == 1, 'Assign2(%s)' % j)
    for i in range(1, m + 1):
        for k in range(1, n + 1):
            if k != n:
                model.addCons(f[i, k] <= s[i, k + 1], 'FinishStart(%s,%s)' % (i, k))
            if i != m:
                model.addCons(f[i, k] <= s[i + 1, k], 'Machine(%s,%s)' % (i, k))
            model.addCons(s[i, k] + quicksum((p[i, j] * x[j, k] for j in range(1, n + 1))) <= f[i, k], 'StartFinish(%s,%s)' % (i, k))
    model.setObjective(f[m, n], 'minimize')
    model.data = (x, s, f)
    return model

