def tsp(V, c):
    """tsp -- model for solving the traveling salesman problem with callbacks
       - start with assignment model
       - add cuts until there are no sub-cycles
    Parameters:
        - V: set/list of nodes in the graph
        - c[i,j]: cost for traversing edge (i,j)
    Returns the optimum objective value and the list of edges used."""
    model = Model('TSP_lazy')
    conshdlr = TSPconshdlr()
    x = {}
    for i in V:
        for j in V:
            if j > i:
                x[i, j] = model.addVar(vtype='B', name='x(%s,%s)' % (i, j))
    for i in V:
        model.addCons(quicksum((x[j, i] for j in V if j < i)) + quicksum((x[i, j] for j in V if j > i)) == 2, 'Degree(%s)' % i)
    model.setObjective(quicksum((c[i, j] * x[i, j] for i in V for j in V if j > i)), 'minimize')
    model.data = x
    return (model, conshdlr)

def tsptw2(n, c, e, l):
    """tsptw2: model for the traveling salesman problem with time windows
    (based on Miller-Tucker-Zemlin's formulation, two-index potential)
    Parameters:
        - n: number of nodes
        - c[i,j]: cost for traversing arc (i,j)
        - e[i]: earliest date for visiting node i
        - l[i]: latest date for visiting node i
    Returns a model, ready to be solved."""
    model = Model('tsptw2')
    x, u = ({}, {})
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i != j:
                x[i, j] = model.addVar(vtype='B', name='x(%s,%s)' % (i, j))
                u[i, j] = model.addVar(vtype='C', name='u(%s,%s)' % (i, j))
    for i in range(1, n + 1):
        model.addCons(quicksum((x[i, j] for j in range(1, n + 1) if j != i)) == 1, 'Out(%s)' % i)
        model.addCons(quicksum((x[j, i] for j in range(1, n + 1) if j != i)) == 1, 'In(%s)' % i)
    for j in range(2, n + 1):
        model.addCons(quicksum((u[i, j] + c[i, j] * x[i, j] for i in range(1, n + 1) if i != j)) - quicksum((u[j, k] for k in range(1, n + 1) if k != j)) <= 0, 'Relate(%s)' % j)
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i != j:
                model.addCons(e[i] * x[i, j] <= u[i, j], 'LB(%s,%s)' % (i, j))
                model.addCons(u[i, j] <= l[i] * x[i, j], 'UB(%s,%s)' % (i, j))
    model.setObjective(quicksum((c[i, j] * x[i, j] for i, j in x)), 'minimize')
    model.data = (x, u)
    return model

def make_data(n, width):
    """make_data: compute matrix distance and time windows."""
    x = dict([(i, 100 * random.random()) for i in range(1, n + 1)])
    y = dict([(i, 100 * random.random()) for i in range(1, n + 1)])
    c = {}
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if j != i:
                c[i, j] = distance(x[i], y[i], x[j], y[j])
    e = {1: 0}
    l = {1: 0}
    start = 0
    delta = int(76.0 * math.sqrt(n) / n * width) + 1
    for i in range(1, n):
        j = i + 1
        start += c[i, j]
        e[j] = max(start - delta, 0)
        l[j] = start + delta
    return (c, x, y, e, l)

def distLinf(x1, y1, x2, y2):
    """Compute the Linfty distance between two points (see TSPLIB documentation)"""
    return int(max(abs(x2 - x1), abs(y2 - y1)))

def distATT(x1, y1, x2, y2):
    """Compute the ATT distance between two points (see TSPLIB documentation)"""
    xd = x2 - x1
    yd = y2 - y1
    rij = math.sqrt((xd * xd + yd * yd) / 10.0)
    tij = int(rij + 0.5)
    if tij < rij:
        return tij + 1
    else:
        return tij

def distCEIL2D(x1, y1, x2, y2):
    """returns smallest integer not less than the distance of two points"""
    xdiff = x2 - x1
    ydiff = y2 - y1
    return int(math.ceil(math.sqrt(xdiff * xdiff + ydiff * ydiff)))

def read_atsplib(filename):
    """basic function for reading a ATSP problem on the TSPLIB format"""
    'NOTE: only works for explicit matrices'
    if filename[-3:] == '.gz':
        f = gzip.open(filename, 'r')
        data = f.readlines()
    else:
        f = open(filename, 'r')
        data = f.readlines()
    for line in data:
        if line.find('DIMENSION') >= 0:
            n = int(line.split()[1])
            break
    else:
        raise IOError("'DIMENSION' keyword not found in file '%s'" % filename)
    for line in data:
        if line.find('EDGE_WEIGHT_TYPE') >= 0:
            if line.split()[1] == 'EXPLICIT':
                break
    else:
        raise IOError("'EDGE_WEIGHT_TYPE' is not 'EXPLICIT' in file '%s'" % filename)
    for k, line in enumerate(data):
        if line.find('EDGE_WEIGHT_SECTION') >= 0:
            break
    else:
        raise IOError("'EDGE_WEIGHT_SECTION' not found in file '%s'" % filename)
    c = {}
    dist = []
    for line in data[k + 1:]:
        if line.find('EOF') >= 0:
            break
        for val in line.split():
            dist.append(int(val))
    k = 0
    for i in range(n):
        for j in range(n):
            c[i + 1, j + 1] = dist[k]
            k += 1
    return (n, c)

def bpp(s, B):
    """bpp: Martello and Toth's model to solve the bin packing problem.
    Parameters:
        - s: list with item widths
        - B: bin capacity
    Returns a model, ready to be solved."""
    n = len(s)
    U = len(FFD(s, B))
    model = Model('bpp')
    x, y = ({}, {})
    for i in range(n):
        for j in range(U):
            x[i, j] = model.addVar(vtype='B', name='x(%s,%s)' % (i, j))
    for j in range(U):
        y[j] = model.addVar(vtype='B', name='y(%s)' % j)
    for i in range(n):
        model.addCons(quicksum((x[i, j] for j in range(U))) == 1, 'Assign(%s)' % i)
    for j in range(U):
        model.addCons(quicksum((s[i] * x[i, j] for i in range(n))) <= B * y[j], 'Capac(%s)' % j)
    for j in range(U):
        for i in range(n):
            model.addCons(x[i, j] <= y[j], 'Strong(%s,%s)' % (i, j))
    for j in range(U - 1):
        model.addCons(y[j] >= y[j + 1], 'TieBrk(%s)' % j)
    for i in range(n):
        model.addConsSOS1([x[i, j] for j in range(U)])
    model.setObjective(quicksum((y[j] for j in range(U))), 'minimize')
    model.data = (x, y)
    return model

def DiscreteUniform(n=10, LB=1, UB=99, B=100):
    """DiscreteUniform: create random, uniform instance for the bin packing problem."""
    B = 100
    s = [0] * n
    for i in range(n):
        s[i] = random.randint(LB, UB)
    return (s, B)

def make_data():
    """creates example data set"""
    n = 30
    z = 1.65
    sigma = 100
    h = {}
    T = {}
    h[n] = 1
    for i in range(n - 1, 0, -1):
        h[i] = h[i + 1] + random.randint(30, 50)
    K = 0
    for i in range(1, n + 1):
