def multidict(D):
    """creates a multidictionary"""
    keys = list(D.keys())
    if len(keys) == 0:
        return [[]]
    try:
        N = len(D[keys[0]])
        islist = True
    except:
        N = 1
        islist = False
    dlist = [dict() for d in range(N)]
    for k in keys:
        if islist:
            for i in range(N):
                dlist[i][k] = D[k][i]
        else:
            dlist[0][k] = D[k]
    return [keys] + dlist

def gcp_fixed_k(V, E, K):
    """gcp_fixed_k -- model for minimizing number of bad edges in coloring a graph
    Parameters:
        - V: set/list of nodes in the graph
        - E: set/list of edges in the graph
        - K: number of colors to be used
    Returns a model, ready to be solved."""
    model = Model('gcp - fixed k')
    x, z = ({}, {})
    for i in V:
        for k in range(K):
            x[i, k] = model.addVar(vtype='B', name='x(%s,%s)' % (i, k))
    for i, j in E:
        z[i, j] = model.addVar(vtype='B', name='z(%s,%s)' % (i, j))
    for i in V:
        model.addCons(quicksum((x[i, k] for k in range(K))) == 1, 'AssignColor(%s)' % i)
    for i, j in E:
        for k in range(K):
            model.addCons(x[i, k] + x[j, k] <= 1 + z[i, j], 'BadEdge(%s,%s,%s)' % (i, j, k))
    model.setObjective(quicksum((z[i, j] for i, j in E)), 'minimize')
    model.data = (x, z)
    return model

def solve_gcp(V, E):
    """solve_gcp -- solve the graph coloring problem with bisection and fixed-k model
    Parameters:
        - V: set/list of nodes in the graph
        - E: set/list of edges in the graph
    Returns tuple with number of colors used, and dictionary mapping colors to vertices"""
    LB = 0
    UB = len(V)
    color = {}
    while UB - LB > 1:
        K = int((UB + LB) / 2)
        gcp = gcp_fixed_k(V, E, K)
        gcp.setObjlimit(0.1)
        gcp.optimize()
        status = gcp.getStatus()
        if status == 'optimal':
            x, z = gcp.data
            for i in V:
                for k in range(K):
                    if gcp.getVal(x[i, k]) > 0.5:
                        color[i] = k
                        break
            UB = K
        else:
            LB = K
    return (UB, color)

def register_plugin_module(mod):
    """Find plugins in given module"""
    for k, v in load_plugins_from_module(mod).items():
        if k:
            if isinstance(k, (list, tuple)):
