def format_(blocks):
    """Produce Python module from blocks of tests

    Arguments:
        blocks (list): Blocks of tests from func:`parse()`"""
    tests = list()
    function_count = 0
    for block in blocks:
        if not any((line[:3] == '>>>' for line in block['body'])):
            block['body'].insert(0, ">>> assert False, 'Body must be in docstring format'\n")
        if not block['binding'] in ('PySide', 'PySide2', 'PyQt5', 'PyQt4'):
            block['body'].insert(0, ">>> assert False, 'Invalid binding'\n")
        if sys.version_info > (3, 4) and block['binding'] in 'PySide':
            continue
        else:
            function_count += 1
            block['header'] = block['header']
            block['count'] = str(function_count)
            block['body'] = '    '.join(block['body'])
            tests.append('\ndef test_{count}_{header}():\n    \'\'\'Test {header}\n\n    >>> import os, sys\n    >>> PYTHON = sys.version_info[0]\n    >>> long = int if PYTHON == 3 else long\n    >>> _ = os.environ.pop("QT_VERBOSE", None)  # Disable debug output\n    >>> os.environ["QT_PREFERRED_BINDING"] = "{binding}"\n    {body}\n    \'\'\'\n\n    '.format(**block))
    return tests

def _qInstallMessageHandler(handler):
    """Install a message handler that works in all bindings

    Args:
        handler: A function that takes 3 arguments, or None"""
    def messageOutputHandler(*args):
        if len(args) == 3:
            msgType, logContext, msg = args
        elif len(args) == 2:
            msgType, msg = args
            logContext = None
        else:
            raise TypeError('handler expected 2 or 3 arguments, got {0}'.format(len(args)))
        if isinstance(msg, bytes):
            msg = msg.decode()
        handler(msgType, logContext, msg)
    passObject = messageOutputHandler if handler else handler
    if Qt.IsPySide or Qt.IsPyQt4:
        return Qt._QtCore.qInstallMsgHandler(passObject)
    elif Qt.IsPySide2 or Qt.IsPyQt5:
        return Qt._QtCore.qInstallMessageHandler(passObject)

def _import_sub_module(module, name):
    """import_sub_module will mimic the function of importlib.import_module"""
    module = __import__(module.__name__ + '.' + name)
    for level in name.split('.'):
        module = getattr(module, level)
    return module

def _setup(module, extras):
    """Install common submodules"""
    Qt.__binding__ = module.__name__
    for name in list(_common_members) + extras:
        try:
            submodule = _import_sub_module(module, name)
        except ImportError:
            try:
                submodule = __import__(name)
            except ImportError:
                continue
        setattr(Qt, '_' + name, submodule)
        if name not in extras:
            setattr(Qt, name, _new_module(name))

def _pyside2():
    """Initialise PySide2

    These functions serve to test the existence of a binding
    along with set it up in such a way that it aligns with
    the final step; adding members from the original binding
    to Qt.py"""
    import PySide2 as module
    extras = ['QtUiTools']
    try:
        try:
            import shiboken2
        except ImportError:
            from PySide2 import shiboken2
        extras.append('shiboken2')
    except ImportError:
        pass
    _setup(module, extras)
    Qt.__binding_version__ = module.__version__
    if hasattr(Qt, '_shiboken2'):
        Qt.QtCompat.wrapInstance = _wrapinstance
        Qt.QtCompat.getCppPointer = _getcpppointer
        Qt.QtCompat.delete = shiboken2.delete
    if hasattr(Qt, '_QtUiTools'):
        Qt.QtCompat.loadUi = _loadUi
    if hasattr(Qt, '_QtCore'):
        Qt.__qt_version__ = Qt._QtCore.qVersion()
    if hasattr(Qt, '_QtWidgets'):
        Qt.QtCompat.setSectionResizeMode = Qt._QtWidgets.QHeaderView.setSectionResizeMode
    _reassign_misplaced_members('PySide2')
    _build_compatibility_members('PySide2')

def load_ui_wrapper(uifile, base_instance=None):
    """Load a Qt Designer .ui file and returns an instance of the user interface

    Args:
        uifile (str): Absolute path to .ui file
        base_instance (QWidget): The widget into which UI widgets are loaded

    Returns:
        function: pyside_load_ui or uic.loadUi"""
    if 'PySide' in __binding__:
        return pyside_load_ui(uifile, base_instance)
    elif 'PyQt' in __binding__:
        uic = __import__(__binding__ + '.uic').uic
        return uic.loadUi(uifile, base_instance)

def GetResourceIdOrFullNameFromLink(resource_link):
    """Gets resource id or full name from resource link.

    :param str resource_link:

    :return:
        The resource id or full name from the resource link.
    :rtype: str"""
    if IsNameBased(resource_link):
        return TrimBeginningAndEndingSlashes(resource_link)
    if resource_link[-1] != '/':
        resource_link = resource_link + '/'
    if resource_link[0] != '/':
        resource_link = '/' + resource_link
    path_parts = resource_link.split('/')
    if len(path_parts) % 2 == 0:
        return str(path_parts[-2])
    return None

def IsNameBased(link):
    """Finds whether the link is name based or not

    :param str link:

    :return:
        True if link is name-based; otherwise, False.
    :rtype: boolean"""
    if not link:
        return False
    if link.startswith('/') and len(link) > 1:
        link = link[1:]
    parts = link.split('/')
    if len(parts) == 0 or not parts[0] or (not parts[0].lower() == 'dbs'):
        return False
    if len(parts) < 2 or not parts[1]:
        return False
    databaseID = parts[1]
    if len(databaseID) != 8:
        return True
    return not IsValidBase64String(str(databaseID))

def IsValidBase64String(string_to_validate):
    """Verifies if a string is a valid Base64 encoded string, after replacing '-' with '/'

    :param string string_to_validate:
        String to validate.

    :return:
        Whether given string is a valid base64 string or not.
    :rtype: str"""
    try:
        buffer = base64.standard_b64decode(string_to_validate.replace('-', '/'))
        if len(buffer) != 4:
            return False
    except Exception as e:
        if six.PY2:
            e = e.message
        if type(e) == binascii.Error:
            return False
        else:
            raise e
    return True

def _RequestBodyFromData(data):
    """Gets request body from data.

    When `data` is dict and list into unicode string; otherwise return `data`
    without making any change.

    :param (str, unicode, file-like stream object, dict, list or None) data:

    :rtype:
        str, unicode, file-like stream object, or None"""
    if isinstance(data, six.string_types) or _IsReadableStream(data):
        return data
    elif isinstance(data, (dict, list, tuple)):
        json_dumped = json.dumps(data, separators=(',', ':'))
        if six.PY2:
            return json_dumped.decode('utf-8')
        else:
            return json_dumped
    return None

def GetAuthorizationHeader(cosmos_client, verb, path, resource_id_or_fullname, is_name_based, resource_type, headers):
    """Gets the authorization header.

    :param cosmos_client.CosmosClient cosmos_client:
    :param str verb:
    :param str path:
    :param str resource_id_or_fullname:
    :param str resource_type:
    :param dict headers:

    :return:
        The authorization headers.
    :rtype: dict"""
    if resource_id_or_fullname is not None and (not is_name_based):
        resource_id_or_fullname = resource_id_or_fullname.lower()
    if cosmos_client.master_key:
        return __GetAuthorizationTokenUsingMasterKey(verb, resource_id_or_fullname, resource_type, headers, cosmos_client.master_key)
    elif cosmos_client.resource_tokens:
        return __GetAuthorizationTokenUsingResourceTokens(cosmos_client.resource_tokens, path, resource_id_or_fullname)

def __GetAuthorizationTokenUsingResourceTokens(resource_tokens, path, resource_id_or_fullname):
    """Get the authorization token using `resource_tokens`.

    :param dict resource_tokens:
    :param str path:
    :param str resource_id_or_fullname:

    :return:
        The authorization token.
    :rtype: dict"""
    if resource_tokens and len(resource_tokens) > 0:
        if not path and (not resource_id_or_fullname):
            return next(six.itervalues(resource_tokens))
        if resource_tokens.get(resource_id_or_fullname):
            return resource_tokens[resource_id_or_fullname]
        else:
            path_parts = []
            if path:
                path_parts = path.split('/')
            resource_types = ['dbs', 'colls', 'docs', 'sprocs', 'udfs', 'triggers', 'users', 'permissions', 'attachments', 'media', 'conflicts', 'offers']
            for one_part in reversed(path_parts):
                if not one_part in resource_types and one_part in resource_tokens:
                    return resource_tokens[one_part]
    return None

def row_to_geojson(row, lon, lat, precision, date_format='epoch'):
    """Convert a pandas dataframe row to a geojson format object.  Converts all datetimes to epoch seconds.
    """
    row_json = json.loads(row.to_json(date_format=date_format, date_unit='s'))
    return geojson.Feature(geometry=geojson.Point((round(row_json[lon], precision), round(row_json[lat], precision))), properties={key: row_json[key] for key in row_json.keys() if key not in [lon, lat]})

def df_to_geojson(df, properties=None, lat='lat', lon='lon', precision=6, date_format='epoch', filename=None):
    """Serialize a Pandas dataframe to a geojson format Python dictionary / file
    """
    if not properties:
        properties = [c for c in df.columns if c not in [lon, lat]]
    for prop in properties:
        if prop not in list(df.columns):
            raise ValueError('properties must be a valid list of column names from dataframe')
        if prop in [lon, lat]:
            raise ValueError('properties cannot be the geometry longitude or latitude column')
    df = convert_date_columns(df, date_format)
    if filename:
        with open(filename, 'w') as f:
            pass
        with open(filename, 'a+') as f:
            f.write('{"type": "FeatureCollection", "features": [\n')
            for i, (index, row) in enumerate(df[[lon, lat] + properties].iterrows()):
                if i == 0:
                    f.write(geojson.dumps(row_to_geojson(row, lon, lat, precision, date_format)) + '\n')
                else:
                    f.write(',' + geojson.dumps(row_to_geojson(row, lon, lat, precision, date_format)) + '\n')
            f.write(']}')
            return {'type': 'file', 'filename': filename, 'feature_count': df.shape[0]}
    else:
        features = []
        df[[lon, lat] + properties].apply(lambda x: features.append(row_to_geojson(x, lon, lat, precision, date_format)), axis=1)
        return geojson.FeatureCollection(features)

def geojson_to_dict_list(data):
    """Parse GeoJSON-formatted information in <data> to list of Python dicts"""
    if type(data) in (list, dict):
        return data
    try:
        with open(data, 'r') as f:
            features = json.load(f)['features']
    except IOError:
        features = requests.get(data).json()['features']
    except:
        raise SourceDataError('MapViz data must be valid GeoJSON or JSON.  Please check your <data> parameter.')
    return [feature['properties'] for feature in features]

def gdf_to_geojson(gdf, date_format='epoch', properties=None, filename=None):
    """Serialize a GeoPandas dataframe to a geojson format Python dictionary / file
    """
    gdf = convert_date_columns(gdf, date_format)
    gdf_out = gdf[['geometry'] + properties or []]
    geojson_str = gdf_out.to_json()
    if filename:
        with codecs.open(filename, 'w', 'utf-8-sig') as f:
            f.write(geojson_str)
        return None
    else:
        return json.loads(geojson_str)

def convert_date_columns(df, date_format='epoch'):
    """Convert dates/datetimes to preferred string format if specified
    i.e. '%Y-%m-%d', 'epoch', 'iso'"""
    if date_format not in ['epoch', 'iso']:
        if '%' in date_format:
            try:
                datetime.datetime.now().strftime(date_format)
            except:
                raise DateConversionError('Error serializing dates in DataFrame using format {}.'.format(date_format))
            finally:
                for column, data_type in df.dtypes.to_dict().items():
                    if 'date' in str(data_type):
                        df[column] = df[column].dt.strftime(date_format)
        else:
            raise DateConversionError('Error serializing dates in DataFrame using format {}.'.format(date_format))
    return df

def scale_between(minval, maxval, numStops):
    """Scale a min and max value to equal interval domain with
    numStops discrete values"""
    scale = []
    if numStops < 2:
        return [minval, maxval]
    elif maxval < minval:
        raise ValueError()
    else:
        domain = maxval - minval
        interval = float(domain) / float(numStops)
        for i in range(numStops):
            scale.append(round(minval + interval * i, 2))
        return scale

def create_color_stops(breaks, colors='RdYlGn', color_ramps=color_ramps):
    """Convert a list of breaks into color stops using colors from colorBrewer
    or a custom list of color values in RGB, RGBA, HSL, CSS text, or HEX format.
    See www.colorbrewer2.org for a list of color options to pass"""
    num_breaks = len(breaks)
    stops = []
    if isinstance(colors, list):
        if len(colors) == 0 or len(colors) != num_breaks:
            raise ValueError('custom color list must be of same length as breaks list')
        for color in colors:
            try:
                Colour(color)
            except:
                raise ValueError('The color code {color} is in the wrong format'.format(color=color))
        for i, b in enumerate(breaks):
            stops.append([b, colors[i]])
    elif colors not in color_ramps.keys():
        raise ValueError('color does not exist in colorBrewer!')
    else:
        try:
            ramp = color_ramps[colors][num_breaks]
        except KeyError:
            raise ValueError('Color ramp {} does not have a {} breaks'.format(colors, num_breaks))
        for i, b in enumerate(breaks):
            stops.append([b, ramp[i]])
    return stops

def rgb_tuple_from_str(color_string):
    """Convert color in format 'rgb(RRR,GGG,BBB)', 'rgba(RRR,GGG,BBB,alpha)',
    '#RRGGBB', or limited English color name (eg 'red') to tuple (RRR, GGG, BBB)"""
    try:
        rgb_string = common_html_colors[color_string]
        return tuple([float(x) for x in re.findall('\\d{1,3}', rgb_string)])
    except KeyError:
        try:
            hex_string = color_string.lstrip('#')
            return tuple((int(hex_string[i:i + 2], 16) for i in (0, 2, 4)))
        except ValueError:
            return tuple([int(x) if float(x) > 1 else float(x) for x in re.findall('[-+]?\\d*\\.*\\d+', color_string)])

def unicode_compact(func):
    """Make sure the first parameter of the decorated method to be a unicode
    object."""
    @wraps(func)
    def wrapped(self, text, *a, **kw):
        if not isinstance(text, six.text_type):
            text = text.decode('utf-8')
        return func(self, text, *a, **kw)
    return wrapped

def catch_conn_reset(f):
    """A decorator to handle connection reset errors even ones from pyOpenSSL
    until https://github.com/edsu/twarc/issues/72 is resolved"""
    try:
        import OpenSSL
        ConnectionError = OpenSSL.SSL.SysCallError
    except:
        ConnectionError = None
    def new_f(self, *args, **kwargs):
        if ConnectionError:
            try:
                return f(self, *args, **kwargs)
            except ConnectionError as e:
                log.warning('caught connection reset error: %s', e)
                self.connect()
                return f(self, *args, **kwargs)
        else:
            return f(self, *args, **kwargs)
    return new_f

def catch_timeout(f):
    """A decorator to handle read timeouts from Twitter."""
    def new_f(self, *args, **kwargs):
        try:
            return f(self, *args, **kwargs)
        except (requests.exceptions.ReadTimeout, requests.packages.urllib3.exceptions.ReadTimeoutError) as e:
            log.warning('caught read timeout: %s', e)
            self.connect()
            return f(self, *args, **kwargs)
    return new_f

def catch_gzip_errors(f):
    """A decorator to handle gzip encoding errors which have been known to
    happen during hydration."""
    def new_f(self, *args, **kwargs):
        try:
            return f(self, *args, **kwargs)
        except requests.exceptions.ContentDecodingError as e:
            log.warning('caught gzip error: %s', e)
            self.connect()
            return f(self, *args, **kwargs)
    return new_f

def interruptible_sleep(t, event=None):
    """Sleeps for a specified duration, optionally stopping early for event.

    Returns True if interrupted"""
    log.info('sleeping %s', t)
    if event is None:
        time.sleep(t)
        return False
    else:
        return not event.wait(t)

def filter_protected(f):
    """filter_protected will filter out protected tweets and users unless
    explicitly requested not to."""
    def new_f(self, *args, **kwargs):
        for obj in f(self, *args, **kwargs):
            if self.protected == False:
                if 'user' in obj and obj['user']['protected']:
                    continue
                elif 'protected' in obj and obj['protected']:
                    continue
            yield obj
    return new_f

