def extract(json_object, args, csv_writer):
    """Extract and write found attributes."""
    found = [[]]
    for attribute in args.attributes:
        item = attribute.getElement(json_object)
        if len(item) == 0:
            for row in found:
                row.append('NA')
        else:
            found1 = []
            for value in item:
                if value is None:
                    value = 'NA'
                new = copy.deepcopy(found)
                for row in new:
                    row.append(value)
                found1.extend(new)
            found = found1
    for row in found:
        csv_writer.writerow(row)
    return len(found)

def friendships(user_id, level=2):
    """Pass in a user_id and you will be returned a generator of friendship
    tuples (user_id, friend_id). By default it will return the friend
    of a friend network (level=2), but you can expand this by settings the
    level parameter to either another number. But beware, it could run for a
    while!"""
    logging.info('getting friends for user %s', user_id)
    level -= 1
    try:
        for friend_id in t.friend_ids(user_id):
            yield (user_id, friend_id)
            if level > 0:
                yield from friendships(friend_id, level)
    except requests.exceptions.HTTPError as e:
        if e.response.status_code == 401:
            logging.error("can't get friends for protected user %s", user_id)
        else:
            raise e

def object_merge(old, new, unique=False):
    """Recursively merge two data structures.

    :param unique: When set to True existing list items are not set."""
    if isinstance(old, list) and isinstance(new, list):
        if old == new:
            return
        for item in old[::-1]:
            if unique and item in new:
                continue
            new.insert(0, item)
    if isinstance(old, dict) and isinstance(new, dict):
        for key, value in old.items():
            if key not in new:
                new[key] = value
            else:
                object_merge(value, new[key])

def compat_kwargs(kwargs):
    """To keep backwards compat change the kwargs to new names"""
    warn_deprecations(kwargs)
    for old, new in RENAMED_VARS.items():
        if old in kwargs:
            kwargs[new] = kwargs[old]
            for c_old, c_new in RENAMED_VARS.items():
                if c_new == new:
                    kwargs[c_old] = kwargs[new]

def trimmed_split(s, seps=(';', ',')):
    """Given a string s, split is by one of one of the seps."""
    for sep in seps:
        if sep not in s:
            continue
        data = [item.strip() for item in s.strip().split(sep)]
        return data
    return [s]

def ensure_a_list(data):
    """Ensure data is a list or wrap it in a list"""
    if not data:
        return []
    if isinstance(data, (list, tuple, set)):
        return list(data)
    if isinstance(data, str):
        data = trimmed_split(data)
        return data
    return [data]

def load(obj, env=None, silent=True, key=None):
    """Reads and loads in to "settings" a single key or all keys from redis

    :param obj: the settings instance
    :param env: settings env default='DYNACONF'
    :param silent: if errors should raise
    :param key: if defined load a single key, else load all in env
    :return: None"""
    redis = StrictRedis(**obj.get('REDIS_FOR_DYNACONF'))
    holder = obj.get('ENVVAR_PREFIX_FOR_DYNACONF')
    try:
        if key:
            value = redis.hget(holder.upper(), key)
            if value:
                obj.logger.debug('redis_loader: loading by key: %s:%s (%s:%s)', key, value, IDENTIFIER, holder)
            if value:
                parsed_value = parse_conf_data(value, tomlfy=True)
                if parsed_value:
                    obj.set(key, parsed_value)
        else:
            data = {key: parse_conf_data(value, tomlfy=True) for key, value in redis.hgetall(holder.upper()).items()}
            if data:
                obj.logger.debug('redis_loader: loading: %s (%s:%s)', data, IDENTIFIER, holder)
                obj.update(data, loader_identifier=IDENTIFIER)
    except Exception as e:
        if silent:
            if hasattr(obj, 'logger'):
                obj.logger.error(str(e))
            return False
        raise

def load(obj, settings_module, identifier='py', silent=False, key=None):
    """Tries to import a python module"""
    mod, loaded_from = get_module(obj, settings_module, silent)
    if mod and loaded_from:
        obj.logger.debug('py_loader: {}'.format(mod))
    else:
        obj.logger.debug('py_loader: %s (Ignoring, Not Found)', settings_module)
        return
    for setting in dir(mod):
        if setting.isupper():
            if key is None or key == setting:
                setting_value = getattr(mod, setting)
                obj.logger.debug('py_loader: loading %s: %s (%s)', setting, '*****' if 'secret' in settings_module else setting_value, identifier)
                obj.set(setting, setting_value, loader_identifier=identifier)
    obj._loaded_files.append(mod.__file__)

def import_from_filename(obj, filename, silent=False):
    """If settings_module is a filename path import it."""
    if filename in [item.filename for item in inspect.stack()]:
        raise ImportError('Looks like you are loading dynaconf from inside the {} file and then it is trying to load itself entering in a circular reference problem. To solve it you have to invoke your program from another root folder or rename your program file.'.format(filename))
    _find_file = getattr(obj, 'find_file', find_file)
    if not filename.endswith('.py'):
        filename = '{0}.py'.format(filename)
    if filename in default_settings.SETTINGS_FILE_FOR_DYNACONF:
        silent = True
    mod = types.ModuleType(filename.rstrip('.py'))
    mod.__file__ = filename
    mod._is_error = False
    try:
        with io.open(_find_file(filename), encoding=default_settings.ENCODING_FOR_DYNACONF) as config_file:
            exec(compile(config_file.read(), filename, 'exec'), mod.__dict__)
    except IOError as e:
        e.strerror = 'py_loader: error loading file (%s %s)\n' % (e.strerror, filename)
        if silent and e.errno in (errno.ENOENT, errno.EISDIR):
            return
        raw_logger().debug(e.strerror)
        mod._is_error = True
    return mod

def load(obj, env=None, silent=None, key=None):
    """Reads and loads in to "settings" a single key or all keys from vault

    :param obj: the settings instance
    :param env: settings env default='DYNACONF'
    :param silent: if errors should raise
    :param key: if defined load a single key, else load all in env
    :return: None"""
    client = get_client(obj)
    env_list = _get_env_list(obj, env)
    for env in env_list:
        path = '/'.join([obj.VAULT_PATH_FOR_DYNACONF, env]).replace('//', '/')
        data = client.read(path)
        if data:
            data = data.get('data', {}).get('data', {})
        try:
            if data and key:
                value = parse_conf_data(data.get(key), tomlfy=True)
                if value:
                    obj.logger.debug('vault_loader: loading by key: %s:%s (%s:%s)', key, '****', IDENTIFIER, path)
                    obj.set(key, value)
            elif data:
                obj.logger.debug('vault_loader: loading: %s (%s:%s)', list(data.keys()), IDENTIFIER, path)
                obj.update(data, loader_identifier=IDENTIFIER, tomlfy=True)
        except Exception as e:
            if silent:
                if hasattr(obj, 'logger'):
                    obj.logger.error(str(e))
                return False
            raise

def set_settings(instance=None):
    """Pick correct settings instance and set it to a global variable."""
    global settings
    settings = None
    if instance:
        settings = import_settings(instance)
    elif 'INSTANCE_FOR_DYNACONF' in os.environ:
        settings = import_settings(os.environ['INSTANCE_FOR_DYNACONF'])
    elif 'FLASK_APP' in os.environ:
        with suppress(ImportError, click.UsageError):
            from flask.cli import ScriptInfo
            flask_app = ScriptInfo().load_app()
            settings = flask_app.config
            click.echo(click.style('Flask app detected', fg='white', bg='bright_black'))
    elif 'DJANGO_SETTINGS_MODULE' in os.environ:
        sys.path.insert(0, os.path.abspath(os.getcwd()))
        try:
            from django.conf import settings
            settings.DYNACONF.configure()
        except (ImportError, AttributeError):
            import dynaconf.contrib.django_dynaconf
            from django.conf import settings as django_settings
            django_settings.configure()
            settings = django_settings
        if settings is not None:
            click.echo(click.style('Django app detected', fg='white', bg='bright_black'))
    if settings is None:
        settings = LazySettings()

def import_settings(dotted_path):
    """Import settings instance from python dotted path.

    Last item in dotted path must be settings instace.

    Example: import_settings('path.to.settings')"""
    if '.' in dotted_path:
        module, name = dotted_path.rsplit('.', 1)
    else:
        raise click.UsageError('invalid path to settings instance: {}'.format(dotted_path))
    try:
        module = importlib.import_module(module)
    except ImportError as e:
        raise click.UsageError(e)
    try:
        return getattr(module, name)
    except AttributeError as e:
        raise click.UsageError(e)

