def uniform(start, end=None, periods=None, freq=None, sc=None):
    """Instantiates a uniform DateTimeIndex.

    Either end or periods must be specified.

    Parameters
    ----------
        start : string, long (nanos from epoch), or Pandas Timestamp
        end : string, long (nanos from epoch), or Pandas Timestamp
        periods : int
        freq : a frequency object
        sc : SparkContext"""
    dtmodule = sc._jvm.com.cloudera.sparkts.__getattr__('DateTimeIndex$').__getattr__('MODULE$')
    if freq is None:
        raise ValueError('Missing frequency')
    elif end is None and periods == None:
        raise ValueError('Need an end date or number of periods')
    elif end is not None:
        return DateTimeIndex(dtmodule.uniformFromInterval(datetime_to_nanos(start), datetime_to_nanos(end), freq._jfreq))
    else:
        return DateTimeIndex(dtmodule.uniform(datetime_to_nanos(start), periods, freq._jfreq))

def main(argv=None):
    """Validate text parsed with FSM or validate an FSM via command line."""
    if argv is None:
        argv = sys.argv
    try:
        opts, args = getopt.getopt(argv[1:], 'h', ['help'])
    except getopt.error as msg:
        raise Usage(msg)
    for opt, _ in opts:
        if opt in ('-h', '--help'):
            print(__doc__)
            print(help_msg)
            return 0
    if not args or len(args) > 4:
        raise Usage('Invalid arguments.')
    with open(args[0], 'r') as template:
        fsm = TextFSM(template)
        print('FSM Template:\n%s\n' % fsm)
        if len(args) > 1:
            with open(args[1], 'r') as f:
                cli_input = f.read()
            table = fsm.ParseText(cli_input)
            print('FSM Table:')
            result = str(fsm.header) + '\n'
            for line in table:
                result += str(line) + '\n'
            print(result, end='')
    if len(args) > 2:
        with open(args[2], 'r') as f:
            ref_table = f.read()
        if ref_table != result:
            print('Data mis-match!')
            return 1
        else:
            print('Data match!')

def _AnsiCmd(command_list):
    """Takes a list of SGR values and formats them as an ANSI escape sequence.

    Args:
      command_list: List of strings, each string represents an SGR value.
          e.g. 'fg_blue', 'bg_yellow'

    Returns:
      The ANSI escape sequence.

    Raises:
      ValueError: if a member of command_list does not map to a valid SGR value."""
    if not isinstance(command_list, list):
        raise ValueError('Invalid list: %s' % command_list)
    for sgr in command_list:
        if sgr.lower() not in SGR:
            raise ValueError('Invalid or unsupported SGR name: %s' % sgr)
    command_str = [str(SGR[x.lower()]) for x in command_list]
    return '\x1b[%sm' % ';'.join(command_str)

def AnsiText(text, command_list=None, reset=True):
    """Wrap text in ANSI/SGR escape codes.

    Args:
      text: String to encase in sgr escape sequence.
      command_list: List of strings, each string represents an sgr value.
        e.g. 'fg_blue', 'bg_yellow'
      reset: Boolean, if to add a reset sequence to the suffix of the text.

    Returns:
      String with sgr characters added."""
    command_list = command_list or ['reset']
    if reset:
        return '%s%s%s' % (_AnsiCmd(command_list), text, _AnsiCmd(['reset']))
    else:
        return '%s%s' % (_AnsiCmd(command_list), text)

def EncloseAnsiText(text):
    """Enclose ANSI/SGR escape sequences with ANSI_START and ANSI_END."""
    return sgr_re.sub(lambda x: ANSI_START + x.group(1) + ANSI_END, text)

def TerminalSize():
    """Returns terminal length and width as a tuple."""
    try:
        with open(os.ctermid(), 'r') as tty_instance:
            length_width = struct.unpack('hh', fcntl.ioctl(tty_instance.fileno(), termios.TIOCGWINSZ, '1234'))
    except (IOError, OSError):
        try:
            length_width = (int(os.environ['LINES']), int(os.environ['COLUMNS']))
        except (ValueError, KeyError):
            length_width = (24, 80)
    return length_width

def main(argv=None):
    """Routine to page text or determine window size via command line."""
    if argv is None:
        argv = sys.argv
    try:
        opts, args = getopt.getopt(argv[1:], 'dhs', ['nodelay', 'help', 'size'])
    except getopt.error as msg:
        raise Usage(msg)
    for opt, _ in opts:
        if opt in ('-h', '--help'):
            print(__doc__)
            print(help_msg)
            return 0
    isdelay = False
    for opt, _ in opts:
        if opt in ('-s', '--size'):
            print('Length: %d, Width: %d' % TerminalSize())
            return 0
        elif opt in ('-d', '--delay'):
            isdelay = True
        else:
            raise Usage('Invalid arguments.')
    if len(args) == 1:
        with open(args[0]) as f:
            fd = f.read()
    else:
        fd = sys.stdin.read()
    Pager(fd, delay=isdelay).Page()

def _center(code, segment_dict):
    """Starting with `code`, follow segments from target to center."""
    while code in segment_dict:
        segment = segment_dict[code]
        yield segment
        code = segment.center

def _search(mapping, filename):
    """Search a Loader data structure for a filename."""
    result = mapping.get(filename)
    if result is not None:
        return result
    name, ext = os.path.splitext(filename)
    result = mapping.get(ext)
    if result is not None:
        for pattern, result2 in result:
            if fnmatch(filename, pattern):
                return result2
    return None

def _to_array(value):
    """When `value` is a plain Python sequence, return it as a NumPy array."""
    if hasattr(value, 'shape'):
        return value
    elif hasattr(value, '__len__'):
        return array(value)
    else:
        return float_(value)

def julian_date(year, month=1, day=1, hour=0, minute=0, second=0.0):
    """Given a proleptic Gregorian calendar date, return a Julian date float."""
    return julian_day(year, month, day) - 0.5 + (second + minute * 60.0 + hour * 3600.0) / DAY_S

