def get_model_field(schema, field):
    """Get the model field of a schema field

    :param Schema schema: a marshmallow schema
    :param str field: the name of the schema field
    :return str: the name of the field in the model"""
    if schema._declared_fields.get(field) is None:
        raise Exception('{} has no attribute {}'.format(schema.__name__, field))
    if schema._declared_fields[field].attribute is not None:
        return schema._declared_fields[field].attribute
    return field

def get_nested_fields(schema, model_field=False):
    """Return nested fields of a schema to support a join

    :param Schema schema: a marshmallow schema
    :param boolean model_field: whether to extract the model field for the nested fields
    :return list: list of nested fields of the schema"""
    nested_fields = []
    for key, value in schema._declared_fields.items():
        if isinstance(value, List) and isinstance(value.container, Nested):
            nested_fields.append(key)
        elif isinstance(value, Nested):
            nested_fields.append(key)
    if model_field is True:
        nested_fields = [get_model_field(schema, key) for key in nested_fields]
    return nested_fields

def get_schema_from_type(resource_type):
    """Retrieve a schema from the registry by his type

    :param str type_: the type of the resource
    :return Schema: the schema class"""
    for cls_name, cls in class_registry._registry.items():
        try:
            if cls[0].opts.type_ == resource_type:
                return cls[0]
        except Exception:
            pass
    raise Exception("Couldn't find schema for type: {}".format(resource_type))

def get_schema_field(schema, field):
    """Get the schema field of a model field

    :param Schema schema: a marshmallow schema
    :param str field: the name of the model field
    :return str: the name of the field in the schema"""
    schema_fields_to_model = {key: get_model_field(schema, key) for key, value in schema._declared_fields.items()}
    for key, value in schema_fields_to_model.items():
        if value == field:
            return key
    raise Exception("Couldn't find schema field from {}".format(field))

def check_method_requirements(func):
    """Check methods requirements

    :param callable func: the function to decorate
    :return callable: the wrapped function"""
    @wraps(func)
    def wrapper(*args, **kwargs):
        error_message = 'You must provide {error_field} in {cls} to get access to the default {method} method'
        error_data = {'cls': args[0].__class__.__name__, 'method': request.method.lower()}
        if request.method != 'DELETE':
            if not hasattr(args[0], 'schema'):
                error_data.update({'error_field': 'a schema class'})
                raise Exception(error_message.format(**error_data))
        return func(*args, **kwargs)
    return wrapper

def new_transaction(vm: VM, from_: Address, to: Address, amount: int=0, private_key: PrivateKey=None, gas_price: int=10, gas: int=100000, data: bytes=b'') -> BaseTransaction:
    """Create and return a transaction sending amount from <from_> to <to>.

    The transaction will be signed with the given private key."""
    nonce = vm.state.get_nonce(from_)
    tx = vm.create_unsigned_transaction(nonce=nonce, gas_price=gas_price, gas=gas, to=to, value=amount, data=data)
    return tx.as_signed_transaction(private_key)

def idfn(fixture_params: Iterable[Any]) -> str:
    """Function for pytest to produce uniform names for fixtures."""
    return ':'.join((str(item) for item in fixture_params))

def get_fixtures_file_hash(all_fixture_paths: Iterable[str]) -> str:
    """Returns the MD5 hash of the fixture files.  Used for cache busting."""
    hasher = hashlib.md5()
    for fixture_path in sorted(all_fixture_paths):
        with open(fixture_path, 'rb') as fixture_file:
            hasher.update(fixture_file.read())
    return hasher.hexdigest()

def mod(computation: BaseComputation) -> None:
    """Modulo"""
    value, mod = computation.stack_pop(num_items=2, type_hint=constants.UINT256)
    if mod == 0:
        result = 0
    else:
        result = value % mod
    computation.stack_push(result)

def smod(computation: BaseComputation) -> None:
    """Signed Modulo"""
    value, mod = map(unsigned_to_signed, computation.stack_pop(num_items=2, type_hint=constants.UINT256))
    pos_or_neg = -1 if value < 0 else 1
    if mod == 0:
        result = 0
    else:
        result = abs(value) % abs(mod) * pos_or_neg & constants.UINT_256_MAX
    computation.stack_push(signed_to_unsigned(result))

def mulmod(computation: BaseComputation) -> None:
    """Modulo Multiplication"""
    left, right, mod = computation.stack_pop(num_items=3, type_hint=constants.UINT256)
    if mod == 0:
        result = 0
    else:
        result = left * right % mod
    computation.stack_push(result)

def div(computation: BaseComputation) -> None:
    """Division"""
    numerator, denominator = computation.stack_pop(num_items=2, type_hint=constants.UINT256)
    if denominator == 0:
        result = 0
    else:
        result = numerator // denominator & constants.UINT_256_MAX
    computation.stack_push(result)

def exp(computation: BaseComputation, gas_per_byte: int) -> None:
    """Exponentiation"""
    base, exponent = computation.stack_pop(num_items=2, type_hint=constants.UINT256)
    bit_size = exponent.bit_length()
    byte_size = ceil8(bit_size) // 8
    if exponent == 0:
        result = 1
    elif base == 0:
        result = 0
    else:
        result = pow(base, exponent, constants.UINT_256_CEILING)
    computation.consume_gas(gas_per_byte * byte_size, reason='EXP: exponent bytes')
    computation.stack_push(result)

def signextend(computation: BaseComputation) -> None:
    """Signed Extend"""
    bits, value = computation.stack_pop(num_items=2, type_hint=constants.UINT256)
    if bits <= 31:
        testbit = bits * 8 + 7
        sign_bit = 1 << testbit
        if value & sign_bit:
            result = value | constants.UINT_256_CEILING - sign_bit
        else:
            result = value & sign_bit - 1
    else:
        result = value
    computation.stack_push(result)

def shl(computation: BaseComputation) -> None:
    """Bitwise left shift"""
    shift_length, value = computation.stack_pop(num_items=2, type_hint=constants.UINT256)
    if shift_length >= 256:
        result = 0
    else:
        result = value << shift_length & constants.UINT_256_MAX
    computation.stack_push(result)

def sar(computation: BaseComputation) -> None:
    """Arithmetic bitwise right shift"""
    shift_length, value = computation.stack_pop(num_items=2, type_hint=constants.UINT256)
    value = unsigned_to_signed(value)
    if shift_length >= 256:
        result = 0 if value >= 0 else constants.UINT_255_NEGATIVE_ONE
    else:
        result = value >> shift_length & constants.UINT_256_MAX
    computation.stack_push(result)

def compute_frontier_difficulty(parent_header: BlockHeader, timestamp: int) -> int:
    """Computes the difficulty for a frontier block based on the parent block."""
    validate_gt(timestamp, parent_header.timestamp, title='Header timestamp')
    offset = parent_header.difficulty // DIFFICULTY_ADJUSTMENT_DENOMINATOR
    difficulty_minimum = min(parent_header.difficulty, DIFFICULTY_MINIMUM)
    if timestamp - parent_header.timestamp < FRONTIER_DIFFICULTY_ADJUSTMENT_CUTOFF:
        base_difficulty = max(parent_header.difficulty + offset, difficulty_minimum)
    else:
        base_difficulty = max(parent_header.difficulty - offset, difficulty_minimum)
    num_bomb_periods = (parent_header.block_number + 1) // BOMB_EXPONENTIAL_PERIOD - BOMB_EXPONENTIAL_FREE_PERIODS
    if num_bomb_periods >= 0:
        difficulty = max(base_difficulty + 2 ** num_bomb_periods, DIFFICULTY_MINIMUM)
    else:
        difficulty = base_difficulty
    return difficulty

def compute_gas_limit_bounds(parent: BlockHeader) -> Tuple[int, int]:
    """Compute the boundaries for the block gas limit based on the parent block."""
    boundary_range = parent.gas_limit // GAS_LIMIT_ADJUSTMENT_FACTOR
    upper_bound = parent.gas_limit + boundary_range
    lower_bound = max(GAS_LIMIT_MINIMUM, parent.gas_limit - boundary_range)
    return (lower_bound, upper_bound)

def compute_gas_limit(parent_header: BlockHeader, gas_limit_floor: int) -> int:
    """A simple strategy for adjusting the gas limit.

    For each block:

    - decrease by 1/1024th of the gas limit from the previous block
    - increase by 50% of the total gas used by the previous block

    If the value is less than the given `gas_limit_floor`:

    - increase the gas limit by 1/1024th of the gas limit from the previous block.

    If the value is less than the GAS_LIMIT_MINIMUM:

    - use the GAS_LIMIT_MINIMUM as the new gas limit."""
    if gas_limit_floor < GAS_LIMIT_MINIMUM:
        raise ValueError('The `gas_limit_floor` value must be greater than the GAS_LIMIT_MINIMUM.  Got {0}.  Must be greater than {1}'.format(gas_limit_floor, GAS_LIMIT_MINIMUM))
    decay = parent_header.gas_limit // GAS_LIMIT_EMA_DENOMINATOR
    if parent_header.gas_used:
        usage_increase = parent_header.gas_used * GAS_LIMIT_USAGE_ADJUSTMENT_NUMERATOR // GAS_LIMIT_USAGE_ADJUSTMENT_DENOMINATOR // GAS_LIMIT_EMA_DENOMINATOR
    else:
        usage_increase = 0
    gas_limit = max(GAS_LIMIT_MINIMUM, parent_header.gas_limit - decay + usage_increase)
    if gas_limit < GAS_LIMIT_MINIMUM:
        return GAS_LIMIT_MINIMUM
    elif gas_limit < gas_limit_floor:
        return parent_header.gas_limit + decay
    else:
        return gas_limit

def generate_header_from_parent_header(compute_difficulty_fn: Callable[[BlockHeader, int], int], parent_header: BlockHeader, coinbase: Address, timestamp: Optional[int]=None, extra_data: bytes=b'') -> BlockHeader:
    """Generate BlockHeader from state_root and parent_header"""
    if timestamp is None:
        timestamp = max(int(time.time()), parent_header.timestamp + 1)
    elif timestamp <= parent_header.timestamp:
        raise ValueError('header.timestamp ({}) should be higher thanparent_header.timestamp ({})'.format(timestamp, parent_header.timestamp))
    header = BlockHeader(difficulty=compute_difficulty_fn(parent_header, timestamp), block_number=parent_header.block_number + 1, gas_limit=compute_gas_limit(parent_header, gas_limit_floor=GENESIS_GAS_LIMIT), timestamp=timestamp, parent_hash=parent_header.hash, state_root=parent_header.state_root, coinbase=coinbase, extra_data=extra_data)
    return header

def normalize_int(value: IntConvertible) -> int:
    """Robust to integer conversion, handling hex values, string representations,
    and special cases like `0x`."""
    if is_integer(value):
        return cast(int, value)
    elif is_bytes(value):
        return big_endian_to_int(value)
    elif is_hex(value) and is_0x_prefixed(value):
        value = cast(str, value)
        if len(value) == 2:
            return 0
        else:
            return int(value, 16)
    elif is_string(value):
        return int(value)
    else:
        raise TypeError('Unsupported type: Got `{0}`'.format(type(value)))

def to_int(value: str) -> int:
    """Robust to integer conversion, handling hex values, string representations,
    and special cases like `0x`."""
    if is_0x_prefixed(value):
        if len(value) == 2:
            return 0
        else:
            return int(value, 16)
    else:
        return int(value)

def collect_touched_accounts(computation: BaseComputation) -> Iterable[bytes]:
    """Collect all of the accounts that *may* need to be deleted based on
    `EIP-161 <https://eips.ethereum.org/EIPS/eip-161>`_.

    Checking whether they *do* need to be deleted happens in the caller.

    See also: https://github.com/ethereum/EIPs/issues/716"""
    if computation.is_origin_computation and computation.transaction_context.gas_price == 0:
        yield computation.state.coinbase
    for beneficiary in sorted(set(computation.accounts_to_delete.values())):
        if computation.is_error and computation.is_origin_computation:
            if beneficiary == THREE:
                yield beneficiary
            continue
        else:
            yield beneficiary
    if computation.msg.to != constants.CREATE_CONTRACT_ADDRESS:
        if computation.is_error and computation.is_origin_computation:
            if computation.msg.to == THREE:
                yield computation.msg.to
        else:
            yield computation.msg.to
    if not computation.is_error:
        for child in computation.children:
            yield from collect_touched_accounts(child)

def FQP_point_to_FQ2_point(pt: Tuple[FQP, FQP, FQP]) -> Tuple[FQ2, FQ2, FQ2]:
    """Transform FQP to FQ2 for type hinting."""
    return (FQ2(pt[0].coeffs), FQ2(pt[1].coeffs), FQ2(pt[2].coeffs))

def extcodehash(computation: BaseComputation) -> None:
    """Return the code hash for a given address.
    EIP: https://github.com/ethereum/EIPs/blob/master/EIPS/eip-1052.md"""
    account = force_bytes_to_address(computation.stack_pop(type_hint=constants.BYTES))
    state = computation.state
    if state.account_is_empty(account):
        computation.stack_push(constants.NULL_BYTE)
    else:
        computation.stack_push(state.get_code_hash(account))

def clamp(inclusive_lower_bound: int, inclusive_upper_bound: int, value: int) -> int:
    """Bound the given ``value`` between ``inclusive_lower_bound`` and
    ``inclusive_upper_bound``."""
    if value <= inclusive_lower_bound:
        return inclusive_lower_bound
    elif value >= inclusive_upper_bound:
        return inclusive_upper_bound
    else:
        return value

def integer_squareroot(value: int) -> int:
    """Return the integer square root of ``value``.

    Uses Python's decimal module to compute the square root of ``value`` with
    a precision of 128-bits. The value 128 is chosen since the largest square
    root of a 256-bit integer is a 128-bit integer."""
    if not isinstance(value, int) or isinstance(value, bool):
        raise ValueError('Value must be an integer: Got: {0}'.format(type(value)))
    if value < 0:
        raise ValueError('Value cannot be negative: Got: {0}'.format(value))
    with decimal.localcontext() as ctx:
        ctx.prec = 128
        return int(decimal.Decimal(value).sqrt())

def lt(computation: BaseComputation) -> None:
    """Lesser Comparison"""
    left, right = computation.stack_pop(num_items=2, type_hint=constants.UINT256)
    if left < right:
        result = 1
    else:
        result = 0
    computation.stack_push(result)

def slt(computation: BaseComputation) -> None:
    """Signed Lesser Comparison"""
    left, right = map(unsigned_to_signed, computation.stack_pop(num_items=2, type_hint=constants.UINT256))
    if left < right:
        result = 1
    else:
        result = 0
    computation.stack_push(signed_to_unsigned(result))

def iszero(computation: BaseComputation) -> None:
    """Not"""
    value = computation.stack_pop(type_hint=constants.UINT256)
    if value == 0:
        result = 1
    else:
        result = 0
    computation.stack_push(result)

def import_string(dotted_path: str) -> ModuleType:
    """Source: django.utils.module_loading
    Import a dotted module path and return the attribute/class designated by the
    last name in the path. Raise ImportError if the import failed."""
    try:
        module_path, class_name = dotted_path.rsplit('.', 1)
    except ValueError:
        msg = "%s doesn't look like a module path" % dotted_path
        raise ImportError(msg)
    module = import_module(module_path)
    try:
        return getattr(module, class_name)
    except AttributeError:
        msg = 'Module "%s" does not define a "%s" attribute/class' % (module_path, class_name)
        raise ImportError(msg)

def build(obj: Any, *applicators: Callable[..., Any]) -> Any:
    """Run the provided object through the series of applicator functions.

    If ``obj`` is an instances of :class:`~eth.chains.base.BaseChain` the
    applicators will be run on a copy of the chain and thus will not mutate the
    provided chain instance."""
    if isinstance(obj, BaseChain):
        return pipe(obj, copy(), *applicators)
    else:
        return pipe(obj, *applicators)

def name(class_name: str, chain_class: Type[BaseChain]) -> Type[BaseChain]:
    """Assign the given name to the chain class."""
    return chain_class.configure(__name__=class_name)

def chain_id(chain_id: int, chain_class: Type[BaseChain]) -> Type[BaseChain]:
    """Set the ``chain_id`` for the chain class."""
    return chain_class.configure(chain_id=chain_id)

def disable_dao_fork(chain_class: Type[BaseChain]) -> Type[BaseChain]:
    """Set the ``support_dao_fork`` flag to ``False`` on the
    :class:`~eth.vm.forks.homestead.HomesteadVM`.  Requires that presence of
    the :class:`~eth.vm.forks.homestead.HomesteadVM`  in the
    ``vm_configuration``"""
    homstead_vms_found = any((_is_homestead(vm_class) for _, vm_class in chain_class.vm_configuration))
    if not homstead_vms_found:
        raise ValidationError('No HomesteadVM found in vm_configuration.')
    vm_configuration = _set_vm_dao_support_false(chain_class.vm_configuration)
    return chain_class.configure(vm_configuration=vm_configuration)

def dao_fork_at(dao_fork_block_number: BlockNumber, chain_class: Type[BaseChain]) -> Type[BaseChain]:
    """Set the block number on which the DAO fork will happen.  Requires that a
    version of the :class:`~eth.vm.forks.homestead.HomesteadVM` is present in
    the chain's ``vm_configuration``"""
    homstead_vms_found = any((_is_homestead(vm_class) for _, vm_class in chain_class.vm_configuration))
    if not homstead_vms_found:
        raise ValidationError('No HomesteadVM found in vm_configuration.')
    vm_configuration = _set_vm_dao_fork_block_number(dao_fork_block_number, chain_class.vm_configuration)
    return chain_class.configure(vm_configuration=vm_configuration)

def enable_pow_mining(chain_class: Type[BaseChain]) -> Type[BaseChain]:
    """Inject on demand generation of the proof of work mining seal on newly
    mined blocks into each of the chain's vms."""
    if not chain_class.vm_configuration:
        raise ValidationError('Chain class has no vm_configuration')
    vm_configuration = _mix_in_pow_mining(chain_class.vm_configuration)
    return chain_class.configure(vm_configuration=vm_configuration)

def disable_pow_check(chain_class: Type[BaseChain]) -> Type[BaseChain]:
    """Disable the proof of work validation check for each of the chain's vms.
    This allows for block mining without generation of the proof of work seal.

    .. note::

        blocks mined this way will not be importable on any chain that does not
        have proof of work disabled."""
    if not chain_class.vm_configuration:
        raise ValidationError('Chain class has no vm_configuration')
    if issubclass(chain_class, NoChainSealValidationMixin):
        chain_class_without_seal_validation = chain_class
    else:
        chain_class_without_seal_validation = type(chain_class.__name__, (chain_class, NoChainSealValidationMixin), {})
    return chain_class_without_seal_validation.configure(vm_configuration=_mix_in_disable_seal_validation(chain_class_without_seal_validation.vm_configuration))

def genesis(chain_class: BaseChain, db: BaseAtomicDB=None, params: Dict[str, HeaderParams]=None, state: GeneralState=None) -> BaseChain:
    """Initialize the given chain class with the given genesis header parameters
    and chain state."""
    if state is None:
        genesis_state = {}
    else:
        genesis_state = _fill_and_normalize_state(state)
    genesis_params_defaults = _get_default_genesis_params(genesis_state)
    if params is None:
        genesis_params = genesis_params_defaults
    else:
        genesis_params = merge(genesis_params_defaults, params)
    if db is None:
        base_db = AtomicDB()
    else:
        base_db = db
    return chain_class.from_genesis(base_db, genesis_params, genesis_state)

def mine_blocks(num_blocks: int, chain: MiningChain) -> MiningChain:
    """Variadic argument version of :func:`~eth.tools.builder.chain.mine_block`"""
    if not isinstance(chain, MiningChain):
        raise ValidationError('`mine_block` may only be used on MiningChain instances')
    for _ in range(num_blocks):
        chain.mine_block()
    return chain

def import_blocks(*blocks: BaseBlock) -> Callable[[BaseChain], BaseChain]:
    """Variadic argument version of :func:`~eth.tools.builder.chain.import_block`"""
    @functools.wraps(import_blocks)
    def _import_blocks(chain: BaseChain) -> BaseChain:
        for block in blocks:
            chain.import_block(block)
        return chain
    return _import_blocks

def copy(chain: MiningChain) -> MiningChain:
    """Make a copy of the chain at the given state.  Actions performed on the
    resulting chain will not affect the original chain."""
    if not isinstance(chain, MiningChain):
        raise ValidationError("`at_block_number` may only be used with 'MiningChain")
    base_db = chain.chaindb.db
    if not isinstance(base_db, AtomicDB):
        raise ValidationError('Unsupported database type: {0}'.format(type(base_db)))
    if isinstance(base_db.wrapped_db, MemoryDB):
        db = AtomicDB(MemoryDB(base_db.wrapped_db.kv_store.copy()))
    else:
        raise ValidationError('Unsupported wrapped database: {0}'.format(type(base_db.wrapped_db)))
    chain_copy = type(chain)(db, chain.header)
    return chain_copy

def chain_split(*splits: Iterable[Callable[..., Any]]) -> Callable[[BaseChain], Iterable[BaseChain]]:
    """Construct and execute multiple concurrent forks of the chain.

    Any number of forks may be executed.  For each fork, provide an iterable of
    commands.

    Returns the resulting chain objects for each fork.


    .. code-block:: python

        chain_a, chain_b = build(
            mining_chain,
            chain_split(
                (mine_block(extra_data=b'chain-a'), mine_block()),
                (mine_block(extra_data=b'chain-b'), mine_block(), mine_block()),
            ),
        )"""
    if not splits:
        raise ValidationError('Cannot use `chain_split` without providing at least one split')
    @functools.wraps(chain_split)
    @to_tuple
    def _chain_split(chain: BaseChain) -> Iterable[BaseChain]:
        for split_fns in splits:
            result = build(chain, *split_fns)
            yield result
    return _chain_split

def find_fixtures(fixtures_base_dir: str) -> Iterable[Tuple[str, str]]:
    """Finds all of the (fixture_path, fixture_key) pairs for a given path under
    the JSON test fixtures directory."""
    all_fixture_paths = find_fixture_files(fixtures_base_dir)
    for fixture_path in sorted(all_fixture_paths):
        with open(fixture_path) as fixture_file:
            fixtures = json.load(fixture_file)
        for fixture_key in sorted(fixtures.keys()):
            yield (fixture_path, fixture_key)

def filter_fixtures(all_fixtures: Iterable[Any], fixtures_base_dir: str, mark_fn: Callable[[str, str], bool]=None, ignore_fn: Callable[..., bool]=None) -> Any:
    """Helper function for filtering test fixtures.

    - `fixtures_base_dir` should be the base directory that the fixtures were collected from.
    - `mark_fn` should be a function which either returns `None` or a `pytest.mark` object.
    - `ignore_fn` should be a function which returns `True` for any fixture
       which should be ignored."""
    import pytest
    for fixture_data in all_fixtures:
        fixture_path = fixture_data[0]
        fixture_relpath = os.path.relpath(fixture_path, fixtures_base_dir)
        if ignore_fn:
            if ignore_fn(fixture_relpath, *fixture_data[1:]):
                continue
        if mark_fn is not None:
            mark = mark_fn(fixture_relpath, *fixture_data[1:])
            if mark:
                yield pytest.param((fixture_path, *fixture_data[1:]), marks=mark)
                continue
        yield fixture_data

def apply_fixture_block_to_chain(block_fixture: Dict[str, Any], chain: BaseChain, perform_validation: bool=True) -> Tuple[BaseBlock, BaseBlock, BaseBlock]:
    """:return: (premined_block, mined_block, rlp_encoded_mined_block)"""
    if 'blockHeader' in block_fixture:
        block_number = block_fixture['blockHeader']['number']
        block_class = chain.get_vm_class_for_block_number(block_number).get_block_class()
    else:
        block_class = chain.get_vm().get_block_class()
    block = rlp.decode(block_fixture['rlp'], sedes=block_class)
    mined_block, _, _ = chain.import_block(block, perform_validation=perform_validation)
    rlp_encoded_mined_block = rlp.encode(mined_block, sedes=block_class)
    return (block, mined_block, rlp_encoded_mined_block)

def construct_evm_runtime_identifier() -> str:
    """Constructs the EVM runtime identifier string

    e.g. 'Py-EVM/v1.2.3/darwin-amd64/python3.6.5'"""
    return 'Py-EVM/{0}/{platform}/{imp.name}{v.major}.{v.minor}.{v.micro}'.format(__version__, platform=sys.platform, v=sys.version_info, imp=sys.implementation)

def compute_homestead_difficulty(parent_header: BlockHeader, timestamp: int) -> int:
    """Computes the difficulty for a homestead block based on the parent block."""
    parent_tstamp = parent_header.timestamp
    validate_gt(timestamp, parent_tstamp, title='Header.timestamp')
    offset = parent_header.difficulty // DIFFICULTY_ADJUSTMENT_DENOMINATOR
    sign = max(1 - (timestamp - parent_tstamp) // HOMESTEAD_DIFFICULTY_ADJUSTMENT_CUTOFF, -99)
    difficulty = int(max(parent_header.difficulty + offset * sign, min(parent_header.difficulty, DIFFICULTY_MINIMUM)))
    num_bomb_periods = (parent_header.block_number + 1) // BOMB_EXPONENTIAL_PERIOD - BOMB_EXPONENTIAL_FREE_PERIODS
    if num_bomb_periods >= 0:
        return max(difficulty + 2 ** num_bomb_periods, DIFFICULTY_MINIMUM)
    else:
        return difficulty

def get_env_value(name: str, required: bool=False, default: Any=empty) -> str:
    """Core function for extracting the environment variable.

    Enforces mutual exclusivity between `required` and `default` keywords.

    The `empty` sentinal value is used as the default `default` value to allow
    other function to handle default/empty logic in the appropriate way."""
    if required and default is not empty:
        raise ValueError('Using `default` with `required=True` is invalid')
    elif required:
        try:
            value = os.environ[name]
        except KeyError:
            raise KeyError('Must set environment variable {0}'.format(name))
    else:
        value = os.environ.get(name, default)
    return value

def is_cleanly_mergable(*dicts: Dict[Any, Any]) -> bool:
    """Check that nothing will be overwritten when dictionaries are merged using `deep_merge`.

    Examples:

        >>> is_cleanly_mergable({"a": 1}, {"b": 2}, {"c": 3})
        True
        >>> is_cleanly_mergable({"a": 1}, {"b": 2}, {"a": 0, c": 3})
        False
        >>> is_cleanly_mergable({"a": 1, "b": {"ba": 2}}, {"c": 3, {"b": {"bb": 4}})
        True
        >>> is_cleanly_mergable({"a": 1, "b": {"ba": 2}}, {"b": {"ba": 4}})
        False"""
    if len(dicts) <= 1:
        return True
    elif len(dicts) == 2:
        if not all((isinstance(d, Mapping) for d in dicts)):
            return False
        else:
            shared_keys = set(dicts[0].keys()) & set(dicts[1].keys())
            return all((is_cleanly_mergable(dicts[0][key], dicts[1][key]) for key in shared_keys))
    else:
        dict_combinations = itertools.combinations(dicts, 2)
        return all((is_cleanly_mergable(*combination) for combination in dict_combinations))

def wait_for_host(port, interval=1, timeout=30, to_start=True, queue=None, ssl_pymongo_options=None):
    """Ping server and wait for response.

    Ping a mongod or mongos every `interval` seconds until it responds, or
    `timeout` seconds have passed. If `to_start` is set to False, will wait for
    the node to shut down instead. This function can be called as a separate
    thread.

    If queue is provided, it will place the results in the message queue and
    return, otherwise it will just return the result directly."""
    host = 'localhost:%i' % port
    start_time = time.time()
    while True:
        if time.time() - start_time > timeout:
            if queue:
                queue.put_nowait((port, False))
            return False
        try:
            con = MongoConnection(host, **ssl_pymongo_options or {})
            con.admin.command('ping')
            if to_start:
                if queue:
                    queue.put_nowait((port, True))
                return True
            else:
                time.sleep(interval)
        except Exception:
            if to_start:
                time.sleep(interval)
            else:
                if queue:
                    queue.put_nowait((port, True))
                return True

def shutdown_host(port, username=None, password=None, authdb=None):
    """Send the shutdown command to a mongod or mongos on given port.

    This function can be called as a separate thread."""
    host = 'localhost:%i' % port
    try:
        mc = MongoConnection(host)
        try:
            if username and password and authdb:
                if authdb != 'admin':
                    raise RuntimeError('given username/password is not for admin database')
                else:
                    try:
                        mc.admin.authenticate(name=username, password=password)
                    except OperationFailure:
                        pass
            mc.admin.command('shutdown', force=True)
        except AutoReconnect:
            pass
        except OperationFailure:
            print('Error: cannot authenticate to shut down %s.' % host)
            return
    except ConnectionFailure:
        pass
    else:
        mc.close()

def import_l2c_db():
    """Static import helper function.

    Checks if the log2code.pickle exists first, otherwise raises ImportError."""
    data_path = os.path.join(os.path.dirname(mtools.__file__), 'data')
    if os.path.exists(os.path.join(data_path, 'log2code.pickle')):
        av, lv, lbw, lcl = cPickle.load(open(os.path.join(data_path, 'log2code.pickle'), 'rb'))
        return (av, lv, lbw, lcl)
    else:
        raise ImportError('log2code.pickle not found in %s.' % data_path)

def shell2json(s):
    """Convert shell syntax to json."""
    replace = {'BinData\\(.+?\\)': '1', '(new )?Date\\(.+?\\)': '1', 'Timestamp\\(.+?\\)': '1', 'ObjectId\\(.+?\\)': '1', 'DBRef\\(.+?\\)': '1', 'undefined': '1', 'MinKey': '1', 'MaxKey': '1', 'NumberLong\\(.+?\\)': '1', '/.+?/\\w*': '1'}
    for key, value in replace.items():
        s = re.sub(key, value, s)
    return s

def json2pattern(s):
    """Convert JSON format to a query pattern.

    Includes even mongo shell notation without quoted key names."""
    s, _ = re.subn('([{,])\\s*([^,{\\s\\\'"]+)\\s*:', ' \\1 "\\2" : ', s)
    s = shell2json(s)
    s, n = re.subn('([:,\\[])\\s*([^{}\\[\\]"]+?)\\s*([,}\\]])', '\\1 1 \\3', s)
    try:
        doc = json.loads(s, object_hook=_decode_pattern_dict)
        return json.dumps(doc, sort_keys=True, separators=(', ', ': '))
    except ValueError as ex:
        return None

def print_table(rows, override_headers=None, uppercase_headers=True):
    """All rows need to be a list of dictionaries, all with the same keys."""
    if len(rows) == 0:
        return
    keys = list(rows[0].keys())
    headers = override_headers or keys
    if uppercase_headers:
        rows = [dict(zip(keys, map(lambda x: x.upper(), headers))), None] + rows
    else:
        rows = [dict(zip(keys, headers)), None] + rows
    lengths = [max((len(str(row[k])) for row in rows if hasattr(row, '__iter__'))) for k in keys]
    tmp = ['{%s:%i}' % (h, l) for h, l in zip(keys[:-1], lengths[:-1])]
    tmp.append('{%s}' % keys[-1])
    template = (' ' * 4).join(tmp)
    for row in rows:
        if type(row) == str:
            print(row)
        elif row is None:
            print()
        elif isinstance(row, dict):
            row = {k: v if v is not None else 'None' for k, v in row.items()}
            print(template.format(**row))
        else:
            print('Unhandled row type:', row)

