def vector_cross(vector1, vector2):
    """Computes the cross-product of the input vectors.

    :param vector1: input vector 1
    :type vector1: list, tuple
    :param vector2: input vector 2
    :type vector2: list, tuple
    :return: result of the cross product
    :rtype: tuple"""
    try:
        if vector1 is None or len(vector1) == 0 or vector2 is None or (len(vector2) == 0):
            raise ValueError('Input vectors cannot be empty')
    except TypeError as e:
        print('An error occurred: {}'.format(e.args[-1]))
        raise TypeError('Input must be a list or tuple')
    except Exception:
        raise
    if not 1 < len(vector1) <= 3 or not 1 < len(vector2) <= 3:
        raise ValueError('The input vectors should contain 2 or 3 elements')
    if len(vector1) == 2:
        v1 = [float(v) for v in vector1] + [0.0]
    else:
        v1 = vector1
    if len(vector2) == 2:
        v2 = [float(v) for v in vector2] + [0.0]
    else:
        v2 = vector2
    vector_out = [v1[1] * v2[2] - v1[2] * v2[1], v1[2] * v2[0] - v1[0] * v2[2], v1[0] * v2[1] - v1[1] * v2[0]]
    return vector_out

def vector_dot(vector1, vector2):
    """Computes the dot-product of the input vectors.

    :param vector1: input vector 1
    :type vector1: list, tuple
    :param vector2: input vector 2
    :type vector2: list, tuple
    :return: result of the dot product
    :rtype: float"""
    try:
        if vector1 is None or len(vector1) == 0 or vector2 is None or (len(vector2) == 0):
            raise ValueError('Input vectors cannot be empty')
    except TypeError as e:
        print('An error occurred: {}'.format(e.args[-1]))
        raise TypeError('Input must be a list or tuple')
    except Exception:
        raise
    prod = 0.0
    for v1, v2 in zip(vector1, vector2):
        prod += v1 * v2
    return prod

def vector_normalize(vector_in, decimals=18):
    """Generates a unit vector from the input.

    :param vector_in: vector to be normalized
    :type vector_in: list, tuple
    :param decimals: number of significands
    :type decimals: int
    :return: the normalized vector (i.e. the unit vector)
    :rtype: list"""
    try:
        if vector_in is None or len(vector_in) == 0:
            raise ValueError('Input vector cannot be empty')
    except TypeError as e:
        print('An error occurred: {}'.format(e.args[-1]))
        raise TypeError('Input must be a list or tuple')
    except Exception:
        raise
    magnitude = vector_magnitude(vector_in)
    if magnitude > 0:
        vector_out = []
        for vin in vector_in:
            vector_out.append(vin / magnitude)
        return [float(('{:.' + str(decimals) + 'f}').format(vout)) for vout in vector_out]
    else:
        raise ValueError('The magnitude of the vector is zero')

def vector_magnitude(vector_in):
    """Computes the magnitude of the input vector.

    :param vector_in: input vector
    :type vector_in: list, tuple
    :return: magnitude of the vector
    :rtype: float"""
    sq_sum = 0.0
    for vin in vector_in:
        sq_sum += vin ** 2
    return math.sqrt(sq_sum)

def vector_is_zero(vector_in, tol=1e-07):
    """Checks if the input vector is a zero vector.

    :param vector_in: input vector
    :type vector_in: list, tuple
    :param tol: tolerance value
    :type tol: float
    :return: True if the input vector is zero, False otherwise
    :rtype: bool"""
    if not isinstance(vector_in, (list, tuple)):
        raise TypeError('Input vector must be a list or a tuple')
    res = [False for _ in range(len(vector_in))]
    for idx in range(len(vector_in)):
        if abs(vector_in[idx]) < tol:
            res[idx] = True
    return all(res)

def convex_hull(points):
    """Returns points on convex hull in counterclockwise order according to Graham's scan algorithm.

    Reference: https://gist.github.com/arthur-e/5cf52962341310f438e96c1f3c3398b8

    .. note:: This implementation only works in 2-dimensional space.

    :param points: list of 2-dimensional points
    :type points: list, tuple
    :return: convex hull of the input points
    :rtype: list"""
    turn_left, turn_right, turn_none = (1, -1, 0)
    def cmp(a, b):
        return (a > b) - (a < b)
    def turn(p, q, r):
        return cmp((q[0] - p[0]) * (r[1] - p[1]) - (r[0] - p[0]) * (q[1] - p[1]), 0)
    def keep_left(hull, r):
        while len(hull) > 1 and turn(hull[-2], hull[-1], r) != turn_left:
            hull.pop()
        if not len(hull) or hull[-1] != r:
            hull.append(r)
        return hull
    points = sorted(points)
    l = reduce(keep_left, points, [])
    u = reduce(keep_left, reversed(points), [])
    return l.extend((u[i] for i in range(1, len(u) - 1))) or l

def wn_poly(point, vertices):
    """Winding number test for a point in a polygon.

    Ported from the C++ version: http://geomalgorithms.com/a03-_inclusion.html

    .. note:: This implementation only works in 2-dimensional space.

    :param point: point to be tested
    :type point: list, tuple
    :param vertices: vertex points of a polygon vertices[n+1] with vertices[n] = vertices[0]
    :type vertices: list, tuple
    :return: True if the point is inside the input polygon, False otherwise
    :rtype: bool"""
    wn = 0
    v_size = len(vertices) - 1
    for i in range(v_size):
        if vertices[i][1] <= point[1]:
            if vertices[i + 1][1] > point[1]:
                if is_left(vertices[i], vertices[i + 1], point) > 0:
                    wn += 1
        elif vertices[i + 1][1] <= point[1]:
            if is_left(vertices[i], vertices[i + 1], point) < 0:
                wn -= 1
    return bool(wn)

def fix_trim_curves(obj):
    """Fixes direction, connectivity and similar issues of the trim curves.

    This function works for surface trim curves consisting of a single curve.

    :param obj: input surface
    :type obj: abstract.Surface"""
    if obj.pdimension != 2:
        raise GeomdlException('Input geometry must be a surface')
    for o in obj:
        trims = o.trims
        if not trims:
            continue
        parbox = get_par_box(o.domain, True)
        updated_trims = []
        for trim in trims:
            flag, trm = check_trim_curve(trim, parbox)
            if flag:
                if trm:
                    cont = shortcuts.generate_container_curve()
                    cont.add(trm)
                    updated_trims.append(cont)
                else:
                    updated_trims.append(trim)
        obj.trims = updated_trims

def detect_sense(curve, tol):
    """Detects the sense, i.e. clockwise or counter-clockwise, of the curve.

    :param curve: 2-dimensional trim curve
    :type curve: abstract.Curve
    :param tol: tolerance value
    :type tol: float
    :return: True if detection is successful, False otherwise
    :rtype: bool"""
    if curve.opt_get('reversed') is None:
        pts = curve.evalpts
        num_pts = len(pts)
        for idx in range(1, num_pts - 1):
            sense = detect_ccw(pts[idx - 1], pts[idx], pts[idx + 1], tol)
            if sense < 0:
                curve.opt = ['reversed', 0]
                return True
            elif sense > 0:
                curve.opt = ['reversed', 1]
                return True
            else:
                continue
        sense = detect_ccw(pts[int(num_pts / 3)], pts[int(2 * num_pts / 3)], pts[-int(num_pts / 3)], tol)
        if sense < 0:
            curve.opt = ['reversed', 0]
            return True
        elif sense > 0:
            curve.opt = ['reversed', 1]
            return True
        else:
            return False
    else:
        return True

def evaluate_bounding_box(ctrlpts):
    """Computes the minimum bounding box of the point set.

    The (minimum) bounding box is the smallest enclosure in which all the input points lie.

    :param ctrlpts: points
    :type ctrlpts: list, tuple
    :return: bounding box in the format [min, max]
    :rtype: tuple"""
    dimension = len(ctrlpts[0])
    bbmin = [float('inf') for _ in range(0, dimension)]
    bbmax = [float('-inf') for _ in range(0, dimension)]
    for cpt in ctrlpts:
        for i, arr in enumerate(zip(cpt, bbmin)):
            if arr[0] < arr[1]:
                bbmin[i] = arr[0]
        for i, arr in enumerate(zip(cpt, bbmax)):
            if arr[0] > arr[1]:
                bbmax[i] = arr[0]
    return (tuple(bbmin), tuple(bbmax))

def target_message(conn, payload):
    """Distibuted payload (message) to one connection
    :param conn: connection
    :param payload: payload(json dumpable)
    :return:"""
    try:
        yield from conn.send(json.dumps(payload))
    except Exception as e:
        logger.debug('could not send', e)

def fanout_message(connections, payload):
    """Distributes payload (message) to all connected ws clients"""
    for conn in connections:
        try:
            yield from conn.send(json.dumps(payload))
        except Exception as e:
            logger.debug('could not send', e)

def gone_online(stream):
    """Distributes the users online status to everyone he has dialog with"""
    while True:
        packet = (yield from stream.get())
        session_id = packet.get('session_key')
        if session_id:
            user_owner = get_user_from_session(session_id)
            if user_owner:
                logger.debug('User ' + user_owner.username + ' gone online')
                online_opponents = list(filter(lambda x: x[1] == user_owner.username, ws_connections))
                online_opponents_sockets = [ws_connections[i] for i in online_opponents]
                yield from fanout_message(online_opponents_sockets, {'type': 'gone-online', 'usernames': [user_owner.username]})
            else:
                pass
        else:
            pass

def check_online(stream):
    """Used to check user's online opponents and show their online/offline status on page on init"""
    while True:
        packet = (yield from stream.get())
        session_id = packet.get('session_key')
        opponent_username = packet.get('username')
        if session_id and opponent_username:
            user_owner = get_user_from_session(session_id)
            if user_owner:
                online_opponents = list(filter(lambda x: x[1] == user_owner.username, ws_connections))
                logger.debug('User ' + user_owner.username + ' has ' + str(len(online_opponents)) + ' opponents online')
                socket = ws_connections.get((user_owner.username, opponent_username))
                if socket:
                    online_opponents_usernames = [i[0] for i in online_opponents]
                    yield from target_message(socket, {'type': 'gone-online', 'usernames': online_opponents_usernames})
                else:
                    pass
            else:
                pass
        else:
            pass

def users_changed_handler(stream):
    """Sends connected client list of currently active users in the chatroom"""
    while True:
        yield from stream.get()
        users = [{'username': username, 'uuid': uuid_str} for username, uuid_str in ws_connections.values()]
        packet = {'type': 'users-changed', 'value': sorted(users, key=lambda i: i['username'])}
        logger.debug(packet)
        yield from fanout_message(ws_connections.keys(), packet)

def is_typing_handler(stream):
    """Show message to opponent if user is typing message"""
    while True:
        packet = (yield from stream.get())
        session_id = packet.get('session_key')
        user_opponent = packet.get('username')
        typing = packet.get('typing')
        if session_id and user_opponent and (typing is not None):
            user_owner = get_user_from_session(session_id)
            if user_owner:
                opponent_socket = ws_connections.get((user_opponent, user_owner.username))
                if typing and opponent_socket:
                    yield from target_message(opponent_socket, {'type': 'opponent-typing', 'username': user_opponent})
            else:
                pass
        else:
            pass

def read_message_handler(stream):
    """Send message to user if the opponent has read the message"""
    while True:
        packet = (yield from stream.get())
        session_id = packet.get('session_key')
        user_opponent = packet.get('username')
        message_id = packet.get('message_id')
        if session_id and user_opponent and (message_id is not None):
            user_owner = get_user_from_session(session_id)
            if user_owner:
                message = models.Message.objects.filter(id=message_id).first()
                if message:
                    message.read = True
                    message.save()
                    logger.debug('Message ' + str(message_id) + ' is now read')
                    opponent_socket = ws_connections.get((user_opponent, user_owner.username))
                    if opponent_socket:
                        yield from target_message(opponent_socket, {'type': 'opponent-read-message', 'username': user_opponent, 'message_id': message_id})
                else:
                    pass
            else:
                pass
        else:
            pass

def main_handler(websocket, path):
    """An Asyncio Task is created for every new websocket client connection
    that is established. This coroutine listens to messages from the connected
    client and routes the message to the proper queue.

    This coroutine can be thought of as a producer."""
    path = path.split('/')
    username = path[2]
    session_id = path[1]
    user_owner = get_user_from_session(session_id)
    if user_owner:
        user_owner = user_owner.username
        ws_connections[user_owner, username] = websocket
        try:
            while websocket.open:
                data = (yield from websocket.recv())
                if not data:
                    continue
                logger.debug(data)
                try:
                    yield from router.MessageRouter(data)()
                except Exception as e:
                    logger.error('could not route msg', e)
        except websockets.exceptions.InvalidState:
            pass
        finally:
            del ws_connections[user_owner, username]
    else:
        logger.info('Got invalid session_id attempt to connect ' + session_id)

def get_dialogs_with_user(user_1, user_2):
    """gets the dialog between user_1 and user_2
    :param user_1: the first user in dialog (owner or opponent)
    :param user_2: the second user in dialog (owner or opponent)
    :return: queryset which include dialog between user_1 and user_2 (queryset can be empty)"""
    return Dialog.objects.filter(Q(owner=user_1, opponent=user_2) | Q(opponent=user_1, owner=user_2))

def constant(interval=1):
    """Generator for constant intervals.

    Args:
        interval: A constant value to yield or an iterable of such values."""
    try:
        itr = iter(interval)
    except TypeError:
        itr = itertools.repeat(interval)
    for val in itr:
        yield val

def run(wrapped):
    """Special decorator encapsulating query method."""
    @wraps(wrapped)
    def _run(self, query, bindings=None, *args, **kwargs):
        self._reconnect_if_missing_connection()
        start = time.time()
        try:
            result = wrapped(self, query, bindings, *args, **kwargs)
        except Exception as e:
            result = self._try_again_if_caused_by_lost_connection(e, query, bindings, wrapped)
        t = self._get_elapsed_time(start)
        self.log_query(query, bindings, t)
        return result
    return _run

def deprecated(func):
    """This is a decorator which can be used to mark functions
    as deprecated. It will result in a warning being emitted
    when the function is used."""
    @functools.wraps(func)
    def new_func(*args, **kwargs):
        if PY3K:
            func_code = func.__code__
        else:
            func_code = func.func_code
        warnings.warn_explicit('Call to deprecated function {}.'.format(func.__name__), category=DeprecationWarning, filename=func_code.co_filename, lineno=func_code.co_firstlineno + 1)
        return func(*args, **kwargs)
    return new_func

def load(template):
    """Try to guess the input format"""
    try:
        data = load_json(template)
        return (data, 'json')
    except ValueError as e:
        try:
            data = load_yaml(template)
            return (data, 'yaml')
        except Exception:
            raise e

def dump_yaml(data, clean_up=False, long_form=False):
    """Output some YAML"""
    return yaml.dump(data, Dumper=get_dumper(clean_up, long_form), default_flow_style=False, allow_unicode=True)

def to_json(template, clean_up=False):
    """Assume the input is YAML and convert to JSON"""
    data = load_yaml(template)
    if clean_up:
        data = clean(data)
    return dump_json(data)

def to_yaml(template, clean_up=False, long_form=False):
    """Assume the input is JSON and convert to YAML"""
    data = load_json(template)
    if clean_up:
        data = clean(data)
    return dump_yaml(data, clean_up, long_form)

def flip(template, in_format=None, out_format=None, clean_up=False, no_flip=False, long_form=False):
    """Figure out the input format and convert the data to the opposing output format"""
    if not in_format:
        if out_format == 'json' and no_flip or (out_format == 'yaml' and (not no_flip)):
            in_format = 'json'
        elif out_format == 'yaml' and no_flip or (out_format == 'json' and (not no_flip)):
            in_format = 'yaml'
    if in_format == 'json':
        data = load_json(template)
    elif in_format == 'yaml':
        data = load_yaml(template)
    else:
        data, in_format = load(template)
    if clean_up:
        data = clean(data)
    if not out_format:
        if in_format == 'json' and no_flip or (in_format == 'yaml' and (not no_flip)):
            out_format = 'json'
        else:
            out_format = 'yaml'
    if out_format == 'json':
        if sys.version[0] == '3':
            return dump_json(data)
        else:
            return dump_json(data).encode('utf-8')
    return dump_yaml(data, clean_up, long_form)

def clean(source):
    """Clean up the source:
    * Replace use of Fn::Join with Fn::Sub"""
    if isinstance(source, dict):
        for key, value in source.items():
            if key == 'Fn::Join':
                return convert_join(value)
            else:
                source[key] = clean(value)
    elif isinstance(source, list):
        return [clean(item) for item in source]
    return source

def map_representer(dumper, value):
    """Deal with !Ref style function format and OrderedDict"""
    value = ODict(value.items())
    if len(value.keys()) == 1:
        key = list(value.keys())[0]
        if key in CONVERTED_SUFFIXES:
            return fn_representer(dumper, key, value[key])
        if key.startswith(FN_PREFIX):
            return fn_representer(dumper, key[4:], value[key])
    return dumper.represent_mapping(TAG_MAP, value, flow_style=False)

def multi_constructor(loader, tag_suffix, node):
    """Deal with !Ref style function format"""
    if tag_suffix not in UNCONVERTED_SUFFIXES:
        tag_suffix = '{}{}'.format(FN_PREFIX, tag_suffix)
    constructor = None
    if tag_suffix == 'Fn::GetAtt':
        constructor = construct_getatt
    elif isinstance(node, yaml.ScalarNode):
        constructor = loader.construct_scalar
    elif isinstance(node, yaml.SequenceNode):
        constructor = loader.construct_sequence
    elif isinstance(node, yaml.MappingNode):
        constructor = loader.construct_mapping
    else:
        raise Exception('Bad tag: !{}'.format(tag_suffix))
    return ODict(((tag_suffix, constructor(node)),))

def construct_getatt(node):
    """Reconstruct !GetAtt into a list"""
    if isinstance(node.value, six.text_type):
        return node.value.split('.', 1)
    elif isinstance(node.value, list):
        return [s.value for s in node.value]
    else:
        raise ValueError('Unexpected node type: {}'.format(type(node.value)))

def main(ctx, **kwargs):
    """AWS CloudFormation Template Flip is a tool that converts
    AWS CloudFormation templates between JSON and YAML formats,
    making use of the YAML format's short function syntax where possible."""
    in_format = kwargs.pop('in_format')
    out_format = kwargs.pop('out_format') or kwargs.pop('out_flag')
    no_flip = kwargs.pop('no_flip')
    clean = kwargs.pop('clean')
    long_form = kwargs.pop('long')
    input_file = kwargs.pop('input')
    output_file = kwargs.pop('output')
    if not in_format:
        if input_file.name.endswith('.json'):
            in_format = 'json'
        elif input_file.name.endswith('.yaml') or input_file.name.endswith('.yml'):
            in_format = 'yaml'
    if input_file.name == '<stdin>' and sys.stdin.isatty():
        click.echo(ctx.get_help())
        ctx.exit()
    try:
        output_file.write(flip(input_file.read(), in_format=in_format, out_format=out_format, clean_up=clean, no_flip=no_flip, long_form=long_form))
    except Exception as e:
        raise click.ClickException('{}'.format(e))

def clean_fail(func):
    """A decorator to cleanly exit on a failed call to AWS.
    catch a `botocore.exceptions.ClientError` raised from an action.
    This sort of error is raised if you are targeting a region that
    isn't set up (see, `credstash setup`."""
    def func_wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except botocore.exceptions.ClientError as e:
            print(str(e), file=sys.stderr)
            sys.exit(1)
    return func_wrapper

def putSecret(name, secret, version='', kms_key='alias/credstash', region=None, table='credential-store', context=None, digest=DEFAULT_DIGEST, comment='', **kwargs):
    """put a secret called `name` into the secret-store,
    protected by the key kms_key"""
    if not context:
        context = {}
    session = get_session(**kwargs)
    kms = session.client('kms', region_name=region)
    key_service = KeyService(kms, kms_key, context)
    sealed = seal_aes_ctr_legacy(key_service, secret, digest_method=digest)
    dynamodb = session.resource('dynamodb', region_name=region)
    secrets = dynamodb.Table(table)
    data = {'name': name, 'version': paddedInt(version)}
    if comment:
        data['comment'] = comment
    data.update(sealed)
    return secrets.put_item(Item=data, ConditionExpression=Attr('name').not_exists())

def getAllSecrets(version='', region=None, table='credential-store', context=None, credential=None, session=None, **kwargs):
    """fetch and decrypt all secrets"""
    if session is None:
        session = get_session(**kwargs)
    dynamodb = session.resource('dynamodb', region_name=region)
    kms = session.client('kms', region_name=region)
    secrets = listSecrets(region, table, **kwargs)
    if credential and WILDCARD_CHAR in credential:
        names = set(expand_wildcard(credential, [x['name'] for x in secrets]))
    else:
        names = set((x['name'] for x in secrets))
    pool = ThreadPool(min(len(names), THREAD_POOL_MAX_SIZE))
    results = pool.map(lambda credential: getSecret(credential, version, region, table, context, dynamodb, kms, **kwargs), names)
    pool.close()
    pool.join()
    return dict(zip(names, results))

def getSecret(name, version='', region=None, table='credential-store', context=None, dynamodb=None, kms=None, **kwargs):
    """fetch and decrypt the secret called `name`"""
    if not context:
        context = {}
    if dynamodb is None or kms is None:
        session = get_session(**kwargs)
        if dynamodb is None:
            dynamodb = session.resource('dynamodb', region_name=region)
        if kms is None:
            kms = session.client('kms', region_name=region)
    secrets = dynamodb.Table(table)
    if version == '':
        response = secrets.query(Limit=1, ScanIndexForward=False, ConsistentRead=True, KeyConditionExpression=boto3.dynamodb.conditions.Key('name').eq(name))
        if response['Count'] == 0:
            raise ItemNotFound("Item {'name': '%s'} couldn't be found." % name)
        material = response['Items'][0]
    else:
        response = secrets.get_item(Key={'name': name, 'version': version})
        if 'Item' not in response:
            raise ItemNotFound("Item {'name': '%s', 'version': '%s'} couldn't be found." % (name, version))
        material = response['Item']
    key_service = KeyService(kms, None, context)
    return open_aes_ctr_legacy(key_service, material)

def open_aes_ctr_legacy(key_service, material):
    """Decrypts secrets stored by `seal_aes_ctr_legacy`.
    Assumes that the plaintext is unicode (non-binary)."""
    key = key_service.decrypt(b64decode(material['key']))
    digest_method = material.get('digest', DEFAULT_DIGEST)
    ciphertext = b64decode(material['contents'])
    if hasattr(material['hmac'], 'value'):
        hmac = codecs.decode(material['hmac'].value, 'hex')
    else:
        hmac = codecs.decode(material['hmac'], 'hex')
    return _open_aes_ctr(key, LEGACY_NONCE, ciphertext, hmac, digest_method).decode('utf-8')

def seal_aes_ctr_legacy(key_service, secret, digest_method=DEFAULT_DIGEST):
    """Encrypts `secret` using the key service.
    You can decrypt with the companion method `open_aes_ctr_legacy`."""
    key, encoded_key = key_service.generate_key_data(64)
    ciphertext, hmac = _seal_aes_ctr(secret, key, LEGACY_NONCE, digest_method)
    return {'key': b64encode(encoded_key).decode('utf-8'), 'contents': b64encode(ciphertext).decode('utf-8'), 'hmac': codecs.encode(hmac, 'hex_codec'), 'digest': digest_method}

def convert_to_timezone_naive(time_to_freeze):
    """Converts a potentially timezone-aware datetime to be a naive UTC datetime"""
    if time_to_freeze.tzinfo:
        time_to_freeze -= time_to_freeze.utcoffset()
        time_to_freeze = time_to_freeze.replace(tzinfo=None)
    return time_to_freeze

def _parse_time_to_freeze(time_to_freeze_str):
    """Parses all the possible inputs for freeze_time
    :returns: a naive ``datetime.datetime`` object"""
    if time_to_freeze_str is None:
        time_to_freeze_str = datetime.datetime.utcnow()
    if isinstance(time_to_freeze_str, datetime.datetime):
        time_to_freeze = time_to_freeze_str
    elif isinstance(time_to_freeze_str, datetime.date):
        time_to_freeze = datetime.datetime.combine(time_to_freeze_str, datetime.time())
    elif isinstance(time_to_freeze_str, datetime.timedelta):
        time_to_freeze = datetime.datetime.utcnow() + time_to_freeze_str
    else:
        time_to_freeze = parser.parse(time_to_freeze_str)
    return convert_to_timezone_naive(time_to_freeze)

def add_validation_phase(phase, before=None, after=None):
    """Add a validation phase to the framework.

    Can be used by plugins to do special validation of extensions."""
    idx = 0
    for x in _validation_phases:
        if x == before:
            _validation_phases.insert(idx, phase)
            return
        elif x == after:
            _validation_phases.insert(idx + 1, phase)
            return
        idx = idx + 1
    _validation_phases.append(phase)

def add_validation_fun(phase, keywords, f):
    """Add a validation function to some phase in the framework.

    Function `f` is called for each valid occurance of each keyword in
    `keywords`.
    Can be used by plugins to do special validation of extensions."""
    for keyword in keywords:
        if (phase, keyword) in _validation_map:
            oldf = _validation_map[phase, keyword]
            def newf(ctx, s):
                oldf(ctx, s)
                f(ctx, s)
            _validation_map[phase, keyword] = newf
        else:
            _validation_map[phase, keyword] = f

def add_refinement_element(keyword, element, merge=False, v_fun=None):
    """Add an element to the <keyword>'s list of refinements"""
    for key, valid_keywords, m, v_fun in _refinements:
        if key == keyword:
            valid_keywords.append(element)
            return
    _refinements.append((keyword, [element], merge, v_fun))

def add_deviation_element(keyword, element):
    """Add an element to the <keyword>'s list of deviations.

    Can be used by plugins that add support for specific extension
    statements."""
    if keyword in _valid_deviations:
        _valid_deviations[keyword].append(element)
    else:
        _valid_deviations[keyword] = [element]

def v_grammar_unique_defs(ctx, stmt):
    """Verify that all typedefs and groupings are unique
    Called for every statement.
    Stores all typedefs in stmt.i_typedef, groupings in stmt.i_grouping"""
    defs = [('typedef', 'TYPE_ALREADY_DEFINED', stmt.i_typedefs), ('grouping', 'GROUPING_ALREADY_DEFINED', stmt.i_groupings)]
    if stmt.parent is None:
        defs.extend([('feature', 'FEATURE_ALREADY_DEFINED', stmt.i_features), ('identity', 'IDENTITY_ALREADY_DEFINED', stmt.i_identities), ('extension', 'EXTENSION_ALREADY_DEFINED', stmt.i_extensions)])
    for keyword, errcode, dict in defs:
        for definition in stmt.search(keyword):
            if definition.arg in dict:
                other = dict[definition.arg]
                err_add(ctx.errors, definition.pos, errcode, (definition.arg, other.pos))
            else:
                dict[definition.arg] = definition

def v_type_extension(ctx, stmt):
    """verify that the extension matches the extension definition"""
    modulename, identifier = stmt.keyword
    revision = stmt.i_extension_revision
    module = modulename_to_module(stmt.i_module, modulename, revision)
    if module is None:
        return
    if identifier not in module.i_extensions:
        if module.i_modulename == stmt.i_orig_module.i_modulename:
            if identifier not in stmt.i_orig_module.i_extensions:
                err_add(ctx.errors, stmt.pos, 'EXTENSION_NOT_DEFINED', (identifier, module.arg))
                return
            else:
                stmt.i_extension = stmt.i_orig_module.i_extensions[identifier]
        else:
            err_add(ctx.errors, stmt.pos, 'EXTENSION_NOT_DEFINED', (identifier, module.arg))
            return
    else:
        stmt.i_extension = module.i_extensions[identifier]
    ext_arg = stmt.i_extension.search_one('argument')
    if stmt.arg is not None and ext_arg is None:
        err_add(ctx.errors, stmt.pos, 'EXTENSION_ARGUMENT_PRESENT', identifier)
    elif stmt.arg is None and ext_arg is not None:
        err_add(ctx.errors, stmt.pos, 'EXTENSION_NO_ARGUMENT_PRESENT', identifier)

def v_type_base(ctx, stmt, no_error_report=False):
    """verify that the referenced identity exists."""
    name = stmt.arg
    stmt.i_identity = None
    if name.find(':') == -1:
        prefix = None
    else:
        [prefix, name] = name.split(':', 1)
    if prefix is None or stmt.i_module.i_prefix == prefix:
        pmodule = stmt.i_module
    else:
        pmodule = prefix_to_module(stmt.i_module, prefix, stmt.pos, ctx.errors)
        if pmodule is None:
            return
    if name in pmodule.i_identities:
        i = pmodule.i_identities[name]
        if prefix is None and (not is_submodule_included(stmt, i)):
            pass
        else:
            stmt.i_identity = i
            v_type_identity(ctx, stmt.i_identity)
    if stmt.i_identity is None and no_error_report == False:
        err_add(ctx.errors, stmt.pos, 'IDENTITY_NOT_FOUND', (name, pmodule.arg))

def v_unique_name_defintions(ctx, stmt):
    """Make sure that all top-level definitions in a module are unique"""
    defs = [('typedef', 'TYPE_ALREADY_DEFINED', stmt.i_typedefs), ('grouping', 'GROUPING_ALREADY_DEFINED', stmt.i_groupings)]
    def f(s):
        for keyword, errcode, dict in defs:
            if s.keyword == keyword and s.arg in dict:
                err_add(ctx.errors, dict[s.arg].pos, errcode, (s.arg, s.pos))
    for i in stmt.search('include'):
        submodulename = i.arg
        subm = ctx.get_module(submodulename)
        if subm is not None:
            for s in subm.substmts:
                for ss in s.substmts:
                    iterate_stmt(ss, f)

def v_unique_name_children(ctx, stmt):
    """Make sure that each child of stmt has a unique name"""
    def sort_pos(p1, p2):
        if p1.line < p2.line:
            return (p1, p2)
        else:
            return (p2, p1)
    dict = {}
    chs = stmt.i_children
    def check(c):
        key = (c.i_module.i_modulename, c.arg)
        if key in dict:
            dup = dict[key]
            minpos, maxpos = sort_pos(c.pos, dup.pos)
            pos = chk_uses_pos(c, maxpos)
            err_add(ctx.errors, pos, 'DUPLICATE_CHILD_NAME', (stmt.arg, stmt.pos, c.arg, minpos))
        else:
            dict[key] = c
        if c.keyword == 'choice':
            for case in c.i_children:
                for cc in case.i_children:
                    check(cc)
    for c in chs:
        check(c)

def v_unique_name_leaf_list(ctx, stmt):
    """Make sure config true leaf-lists do nothave duplicate defaults"""
    if not stmt.i_config:
        return
    seen = []
    for defval in stmt.i_default:
        if defval in seen:
            err_add(ctx.errors, stmt.pos, 'DUPLICATE_DEFAULT', defval)
        else:
            seen.append(defval)

def v_reference_choice(ctx, stmt):
    """Make sure that the default case exists"""
    d = stmt.search_one('default')
    if d is not None:
        m = stmt.search_one('mandatory')
        if m is not None and m.arg == 'true':
            err_add(ctx.errors, stmt.pos, 'DEFAULT_AND_MANDATORY', ())
        ptr = attrsearch(d.arg, 'arg', stmt.i_children)
        if ptr is None:
            err_add(ctx.errors, d.pos, 'DEFAULT_CASE_NOT_FOUND', d.arg)
        else:
            def chk_no_defaults(s):
                for c in s.i_children:
                    if c.keyword in ('leaf', 'choice'):
                        m = c.search_one('mandatory')
                        if m is not None and m.arg == 'true':
                            err_add(ctx.errors, c.pos, 'MANDATORY_NODE_IN_DEFAULT_CASE', ())
                    elif c.keyword in ('list', 'leaf-list'):
                        m = c.search_one('min-elements')
                        if m is not None and int(m.arg) > 0:
                            err_add(ctx.errors, c.pos, 'MANDATORY_NODE_IN_DEFAULT_CASE', ())
                    elif c.keyword == 'container':
                        p = c.search_one('presence')
                        if p == None or p.arg == 'false':
                            chk_no_defaults(c)
            chk_no_defaults(ptr)

def has_type(type, names):
    """Return type with name if `type` has name as one of its base types,
    and name is in the `names` list.  otherwise, return None."""
    if type.arg in names:
        return type
    for t in type.search('type'):
        r = has_type(t, names)
        if r is not None:
            return r
    if not hasattr(type, 'i_typedef'):
        return None
    if type.i_typedef is not None and hasattr(type.i_typedef, 'i_is_circular') and (type.i_typedef.i_is_circular == False):
        t = type.i_typedef.search_one('type')
        if t is not None:
            return has_type(t, names)
    return None

def search_typedef(stmt, name):
    """Search for a typedef in scope
    First search the hierarchy, then the module and its submodules."""
    mod = stmt.i_orig_module
    while stmt is not None:
        if name in stmt.i_typedefs:
            t = stmt.i_typedefs[name]
            if mod is not None and mod != t.i_orig_module and (t.i_orig_module.keyword == 'submodule'):
                if mod.search_one('include', t.i_orig_module.arg) is None:
                    return None
            return t
        stmt = stmt.parent
    return None

def search_grouping(stmt, name):
    """Search for a grouping in scope
    First search the hierarchy, then the module and its submodules."""
    mod = stmt.i_orig_module
    while stmt is not None:
        if name in stmt.i_groupings:
            g = stmt.i_groupings[name]
            if mod is not None and mod != g.i_orig_module and (g.i_orig_module.keyword == 'submodule'):
                if mod.search_one('include', g.i_orig_module.arg) is None:
                    return None
            return g
        stmt = stmt.parent
    return None

def is_submodule_included(src, tgt):
    """Check that the tgt's submodule is included by src, if they belong
    to the same module."""
    if tgt is None or not hasattr(tgt, 'i_orig_module'):
        return True
    if tgt.i_orig_module.keyword == 'submodule' and src.i_orig_module != tgt.i_orig_module and (src.i_orig_module.i_modulename == tgt.i_orig_module.i_modulename):
        if src.i_orig_module.search_one('include', tgt.i_orig_module.arg) is None:
            return False
    return True

def mk_path_list(stmt):
    """Derives a list of tuples containing
    (module name, prefix, xpath)
    per node in the statement."""
    resolved_names = []
    def resolve_stmt(stmt, resolved_names):
        if stmt.keyword in ['choice', 'case']:
            resolve_stmt(stmt.parent, resolved_names)
            return
        def qualified_name_elements(stmt):
            """(module name, prefix, name)"""
            return (stmt.i_module.arg, stmt.i_module.i_prefix, stmt.arg)
        if stmt.parent.keyword in ['module', 'submodule']:
            resolved_names.append(qualified_name_elements(stmt))
            return
        else:
            resolve_stmt(stmt.parent, resolved_names)
            resolved_names.append(qualified_name_elements(stmt))
            return
    resolve_stmt(stmt, resolved_names)
    return resolved_names

def get_qualified_type(stmt):
    """Gets the qualified, top-level type of the node.
    This enters the typedef if defined instead of using the prefix
    to ensure absolute distinction."""
    type_obj = stmt.search_one('type')
    fq_type_name = None
    if type_obj:
        if getattr(type_obj, 'i_typedef', None):
            type_obj = type_obj.i_typedef
        type_name = type_obj.arg
        if check_primitive_type(type_obj):
            fq_type_name = type_name
        else:
            type_module = type_obj.i_orig_module.arg
            fq_type_name = '%s:%s' % (type_module, type_name)
    return fq_type_name

def add_prefix(prefix, s):
    """Add `prefix` to all unprefixed names in `s`"""
    toks = xpath_lexer.scan(s)
    toks2 = [_add_prefix(prefix, tok) for tok in toks]
    ls = [x.value for x in toks2]
    return ''.join(ls)

def chk_date_arg(s):
    """Checks if the string `s` is a valid date string.

    Return True of False."""
    if re_date.search(s) is None:
        return False
    comp = s.split('-')
    try:
        dt = datetime.date(int(comp[0]), int(comp[1]), int(comp[2]))
        return True
    except Exception as e:
        return False

def chk_enum_arg(s):
    """Checks if the string `s` is a valid enum string.

    Return True or False."""
    if len(s) == 0 or s[0].isspace() or s[-1].isspace():
        return False
    else:
        return True

def chk_fraction_digits_arg(s):
    """Checks if the string `s` is a valid fraction-digits argument.

    Return True or False."""
    try:
        v = int(s)
        if v >= 1 and v <= 18:
            return True
        else:
            return False
    except ValueError:
        return False

def add_to_stmts_rules(stmts, rules):
    """Use by plugins to add extra rules to the existing rules for
    a statement."""
    def is_rule_less_than(ra, rb):
        rka = ra[0]
        rkb = rb[0]
        if not util.is_prefixed(rkb):
            return False
        if not util.is_prefixed(rka):
            return True
        return rka[0] < rkb[0]
    for s in stmts:
        arg, rules0 = stmt_map[s]
        for r in rules:
            i = 0
            while i < len(rules0):
                if is_rule_less_than(r, rules0[i]):
                    rules0.insert(i, r)
                    break
                i += 1
            if i == len(rules0):
                rules0.insert(i, r)

def chk_module_statements(ctx, module_stmt, canonical=False):
    """Validate the statement hierarchy according to the grammar.

    Return True if module is valid, False otherwise."""
    return chk_statement(ctx, module_stmt, top_stmts, canonical)

def chk_statement(ctx, stmt, grammar, canonical=False):
    """Validate `stmt` according to `grammar`.

    Marks each statement in the hierearchy with stmt.is_grammatically_valid,
    which is a boolean.

    Return True if stmt is valid, False otherwise."""
    n = len(ctx.errors)
    if canonical == True:
        canspec = grammar
    else:
        canspec = []
    _chk_stmts(ctx, stmt.pos, [stmt], None, (grammar, canspec), canonical)
    return n == len(ctx.errors)

def sort_canonical(keyword, stmts):
    """Sort all `stmts` in the canonical order defined by `keyword`.
    Return the sorted list.  The `stmt` list is not modified.
    If `keyword` does not have a canonical order, the list is returned
    as is."""
    try:
        _arg_type, subspec = stmt_map[keyword]
    except KeyError:
        return stmts
    res = []
    keep = [s[0] for s in data_def_stmts] + ['case']
    for kw, _spec in flatten_spec(subspec):
        comments = []
        for s in stmts:
            if s.keyword == '_comment':
                comments.append(s)
            elif s.keyword == kw and kw not in keep:
                res.extend(comments)
                comments = []
                res.append(s)
            else:
                comments = []
    res.extend([stmt for stmt in stmts if stmt not in res])
    return res

def p_step_7(p):
    """Step : AbbreviatedStep PredicateList"""
    if p[1][1] == 'self':
        a = '.'
        x = 'self::node()'
    else:
        a = '..'
        x = 'parent::node()'
    msg = '%s[<pred>] is illegal syntax.  use %s[<pred>] instead,' % (a, x)
    raise xpath_lexer.XPathError(msg, 1, 1)

def guess_format(text):
    """Guess YANG/YIN format

    If the first non-whitespace character is '<' then it is XML.
    Return 'yang' or 'yin'"""
    format = 'yang'
    i = 0
    while i < len(text) and text[i].isspace():
        i += 1
    if i < len(text):
        if text[i] == '<':
            format = 'yin'
    return format

def unique_prefixes(context):
    """Return a dictionary with unique prefixes for modules in `context`.

    Keys are 'module' statements and values are prefixes,
    disambiguated where necessary."""
    res = {}
    for m in context.modules.values():
        if m.keyword == 'submodule':
            continue
        prf = new = m.i_prefix
        suff = 0
        while new in res.values():
            suff += 1
            new = '%s%x' % (prf, suff)
        res[m] = new
    return res

def slugify(value, separator='-', max_length=0, word_boundary=False, entities=True, decimal=True, hexadecimal=True):
    """Normalizes string, removes non-alpha characters,
    and converts spaces to ``separator`` character"""
    value = normalize('NFKD', to_string(value, 'utf-8', 'ignore'))
    if unidecode:
        value = unidecode(value)
    if entities:
        value = CHAR_ENTITY_REXP.sub(lambda m: chr(name2codepoint[m.group(1)]), value)
    if decimal:
        try:
            value = DECIMAL_REXP.sub(lambda m: chr(int(m.group(1))), value)
        except Exception:
            pass
    if hexadecimal:
        try:
            value = HEX_REXP.sub(lambda m: chr(int(m.group(1), 16)), value)
        except Exception:
            pass
    value = value.lower()
    value = REPLACE1_REXP.sub('', value)
    value = REPLACE2_REXP.sub('-', value)
    value = REMOVE_REXP.sub('-', value).strip('-')
    if max_length > 0:
        value = smart_truncate(value, max_length, word_boundary, '-')
    if separator != '-':
        value = value.replace('-', separator)
    return value

def smart_truncate(value, max_length=0, word_boundaries=False, separator=' '):
    """Truncate a string"""
    value = value.strip(separator)
    if not max_length:
        return value
    if len(value) < max_length:
        return value
    if not word_boundaries:
        return value[:max_length].strip(separator)
    if separator not in value:
        return value[:max_length]
    truncated = ''
    for word in value.split(separator):
        if word:
            next_len = len(truncated) + len(word) + len(separator)
            if next_len <= max_length:
                truncated += '{0}{1}'.format(word, separator)
    if not truncated:
        truncated = value[:max_length]
    return truncated.strip(separator)

def is_mainthread(thread=None):
    """Check if thread is the main thread.

    If ``thread`` is not supplied check the current thread"""
    thread = thread if thread is not None else current_thread()
    return isinstance(thread, threading._MainThread)

def process_data(name=None):
    """Fetch the current process local data dictionary.

    If ``name`` is not ``None`` it returns the value at``name``,
    otherwise it return the process data dictionary"""
    ct = current_process()
    if not hasattr(ct, '_pulsar_local'):
        ct._pulsar_local = {}
    loc = ct._pulsar_local
    return loc.get(name) if name else loc

def thread_data(name, value=NOTHING, ct=None):
    """Set or retrieve an attribute ``name`` from thread ``ct``.

    If ``ct`` is not given used the current thread. If ``value``
    is None, it will get the value otherwise it will set the value."""
    ct = ct or current_thread()
    if is_mainthread(ct):
        loc = process_data()
    elif not hasattr(ct, '_pulsar_local'):
        ct._pulsar_local = loc = {}
    else:
        loc = ct._pulsar_local
    if value is not NOTHING:
        if name in loc:
            if loc[name] is not value:
                raise RuntimeError('%s is already available on this thread' % name)
        else:
            loc[name] = value
    return loc.get(name)

def parse_address(netloc, default_port=8000):
    """Parse an internet address ``netloc`` and return a tuple with
    ``host`` and ``port``."""
    if isinstance(netloc, tuple):
        if len(netloc) != 2:
            raise ValueError('Invalid address %s' % str(netloc))
        return netloc
    netloc = native_str(netloc)
    auth = None
    if '@' in netloc:
        auth, netloc = netloc.split('@')
    if netloc.startswith('unix:'):
        host = netloc.split('unix:')[1]
        return '%s@%s' % (auth, host) if auth else host
    if '[' in netloc and ']' in netloc:
        host = netloc.split(']')[0][1:].lower()
    elif ':' in netloc:
        host = netloc.split(':')[0].lower()
    elif netloc == '':
        host = '0.0.0.0'
    else:
        host = netloc.lower()
    netloc = netloc.split(']')[-1]
    if ':' in netloc:
        port = netloc.split(':', 1)[1]
        if not port.isdigit():
            raise ValueError('%r is not a valid port number.' % port)
        port = int(port)
    else:
        port = default_port
    return ('%s@%s' % (auth, host) if auth else host, port)

def parse_connection_string(connection_string, default_port=8000):
    """Converts the ``connection_string`` into a three elements tuple
    ``(scheme, host, params)`` where ``scheme`` is a string, ``host`` could
    be a string or a two elements tuple (for a tcp address) and ``params`` a
    dictionary of parameters. The ``default_port`` parameter can be used to
    set the port if a port is not available in the ``connection_string``.

    For example::

        >>> parse_connection_string('http://127.0.0.1:9080')
        ('http', ('127.0.0.1', 9080), {})

    and this example::

        >>> parse_connection_string('redis://127.0.0.1:6379?db=3&password=bla')
        ('redis', ('127.0.0.1', 6379), {'db': '3', 'password': 'bla'})"""
    if '://' not in connection_string:
        connection_string = 'dummy://%s' % connection_string
    scheme, host, path, query, fragment = urlsplit(connection_string)
    if not scheme and (not host):
        host, path = (path, '')
    elif path and (not query):
        query, path = (path, '')
        if query:
            if query.find('?'):
                path = query
            else:
                query = query[1:]
    if path:
        raise ValueError("Address must not have a path. Found '%s'" % path)
    if query:
        params = dict(parse_qsl(query))
    else:
        params = {}
    if scheme == 'dummy':
        scheme = ''
    return (scheme, parse_address(host, default_port), params)

def is_socket_closed(sock):
    """Check if socket ``sock`` is closed."""
    if not sock:
        return True
    try:
        if not poll:
            if not select:
                return False
            try:
                return bool(select([sock], [], [], 0.0)[0])
            except socket.error:
                return True
        p = poll()
        p.register(sock, POLLIN)
        for fno, ev in p.poll(0.0):
            if fno == sock.fileno():
                return True
    except Exception:
        return True

def close_socket(sock):
    """Shutdown and close the socket."""
    if sock:
        try:
            sock.shutdown(socket.SHUT_RDWR)
        except Exception:
            pass
        try:
            sock.close()
        except Exception:
            pass

def parse_close(data):
    """Parse the body of a close :class:`Frame`.

    Returns a tuple (``code``, ``reason``) if successful otherwise
    raise :class:`.ProtocolError`."""
    length = len(data)
    if length == 0:
        return (1005, '')
    elif length == 1:
        raise ProtocolError('Close frame too short')
    else:
        code, = unpack('!H', data[:2])
        if not (code in CLOSE_CODES or 3000 <= code < 5000):
            raise ProtocolError('Invalid status code for websocket')
        reason = data[2:].decode('utf-8')
        return (code, reason)

def render_error(request, exc):
    """Default renderer for errors."""
    cfg = request.get('pulsar.cfg')
    debug = cfg.debug if cfg else False
    response = request.response
    if not response.content_type:
        content_type = request.get('default.content_type')
        response.content_type = request.content_types.best_match(as_tuple(content_type or DEFAULT_RESPONSE_CONTENT_TYPES))
    content_type = None
    if response.content_type:
        content_type = response.content_type.split(';')[0]
    is_html = content_type == 'text/html'
    if debug:
        msg = render_error_debug(request, exc, is_html)
    else:
        msg = escape(error_messages.get(response.status_code) or exc)
        if is_html:
            msg = textwrap.dedent('\n                <h1>{0[reason]}</h1>\n                {0[msg]}\n                <h3>{0[version]}</h3>\n            ').format({'reason': response.status, 'msg': msg, 'version': request.environ['SERVER_SOFTWARE']})
    if content_type == 'text/html':
        doc = HtmlDocument(title=response.status)
        doc.head.embedded_css.append(error_css)
        doc.body.append(Html('div', msg, cn='pulsar-error'))
        return doc.to_bytes(request)
    elif content_type in JSON_CONTENT_TYPES:
        return json.dumps({'status': response.status_code, 'message': msg})
    else:
        return '\n'.join(msg) if isinstance(msg, (list, tuple)) else msg

def render_error_debug(request, exception, is_html):
    """Render the ``exception`` traceback
    """
    error = Html('div', cn='well well-lg') if is_html else []
    for trace in format_traceback(exception):
        counter = 0
        for line in trace.split('\n'):
            if line.startswith('  '):
                counter += 1
                line = line[2:]
            if line:
                if is_html:
                    line = Html('p', escape(line), cn='text-danger')
                    if counter:
                        line.css({'margin-left': '%spx' % (20 * counter)})
                error.append(line)
    if is_html:
        error = Html('div', Html('h1', request.response.status), error)
    return error

def arbiter(**params):
    """Obtain the ``arbiter``.

    It returns the arbiter instance only if we are on the arbiter
    context domain, otherwise it returns nothing."""
    arbiter = get_actor()
    if arbiter is None:
        return set_actor(_spawn_actor('arbiter', None, **params))
    elif arbiter.is_arbiter():
        return arbiter

def response_error(response):
    """Parse an error response"""
    response = response.split(' ')
    error_code = response[0]
    if error_code not in EXCEPTION_CLASSES:
        error_code = 'ERR'
    response = ' '.join(response[1:])
    return EXCEPTION_CLASSES[error_code](response)

def parse_authorization_header(value, charset='utf-8'):
    """Parse an HTTP basic/digest authorisation header.

    :param value: the authorisation header to parse.
    :return: either `None` if the header was invalid or
        not given, otherwise an :class:`Auth` object."""
    if not value:
        return
    try:
        auth_type, auth_info = value.split(None, 1)
        auth_type = auth_type.lower()
    except ValueError:
        return
    if auth_type == 'basic':
        try:
            up = b64decode(auth_info.encode(CHARSET)).decode(charset)
            username, password = up.split(':', 1)
        except Exception:
            return
        return BasicAuth(username, password)
    elif auth_type == 'digest':
        auth_map = parse_dict_header(auth_info)
        if not digest_parameters.difference(auth_map):
            return DigestAuth(auth_map.pop('username'), options=auth_map)

def add_errback(future, callback, loop=None):
    """Add a ``callback`` to a ``future`` executed only if an exception
    or cancellation has occurred."""
    def _error_back(fut):
        if fut._exception:
            callback(fut.exception())
        elif fut.cancelled():
            callback(CancelledError())
    future = ensure_future(future, loop=None)
    future.add_done_callback(_error_back)
    return future

def run(request, callable, *args, **kwargs):
    """Execute a python *callable*."""
    return callable(request.actor, *args, **kwargs)

def sort_return_tuples(response, groups=None, **options):
    """If ``groups`` is specified, return the response as a list of
    n-element tuples with n being the value found in options['groups']"""
    if not response or not groups:
        return response
    return list(zip(*[response[i::groups] for i in range(groups)]))

def server(name=None, description=None, **kwargs):
    """Create the :class:`.SocketServer` with :class:`EchoServerProtocol`
    as protocol factory."""
    name = name or 'echoserver'
    description = description or 'Echo Server'
    return SocketServer(EchoServerProtocol, name=name, description=description, **kwargs)

def num2eng(num):
    """English representation of a number up to a trillion.
    """
    num = str(int(num))
    if len(num) / 3 >= len(_PRONOUNCE):
        return num
    elif num == '0':
        return 'zero'
    pron = []
    first = True
    for pr, bits in zip(_PRONOUNCE, grouper(3, reversed(num), '')):
        num = ''.join(reversed(bits))
        n = int(num)
        bits = []
        if n > 99:
            bits.append('%s hundred' % _SMALL[num[0]])
            num = num[1:]
            n = int(num)
            num = str(n)
        if n > 20 and n != n // 10 * 10:
            bits.append('%s %s' % (_SMALL[num[0] + '0'], _SMALL[num[1]]))
        elif n:
            bits.append(_SMALL[num])
        if len(bits) == 2 and first:
            first = False
            p = ' and '.join(bits)
        else:
            p = ' '.join(bits)
        if p and pr:
            p = '%s %s' % (p, pr)
        pron.append(p)
    return ', '.join(reversed(pron))

