    return command

def remote_call(request, cls, method, args, kw):
    """Command for executing remote calls on a remote object
    """
    actor = request.actor
    name = 'remote_%s' % cls.__name__
    if not hasattr(actor, name):
        object = cls(actor)
        setattr(actor, name, object)
    else:
        object = getattr(actor, name)
    method_name = '%s%s' % (PREFIX, method)
    return getattr(object, method_name)(request, *args, **kw)

def convert_bytes(b):
    """Convert a number of bytes into a human readable memory usage, bytes,
    kilo, mega, giga, tera, peta, exa, zetta, yotta"""
    if b is None:
        return '#NA'
    for s in reversed(memory_symbols):
        if b >= memory_size[s]:
            value = float(b) / memory_size[s]
            return '%.1f%sB' % (value, s)
    return '%sB' % b

def process_info(pid=None):
    """Returns a dictionary of system information for the process ``pid``.

    It uses the psutil_ module for the purpose. If psutil_ is not available
    it returns an empty dictionary.

    .. _psutil: http://code.google.com/p/psutil/"""
    if psutil is None:
        return {}
    pid = pid or os.getpid()
    try:
        p = psutil.Process(pid)
    except psutil.NoSuchProcess:
        return {}
    else:
        mem = p.memory_info()
        return {'memory': convert_bytes(mem.rss), 'memory_virtual': convert_bytes(mem.vms), 'cpu_percent': p.cpu_percent(), 'nice': p.nice(), 'num_threads': p.num_threads()}

def guess_filename(obj):
    """Tries to guess the filename of the given object."""
    name = getattr(obj, 'name', None)
    if name and name[0] != '<' and (name[-1] != '>'):
        return os.path.basename(name)

def set_owner_process(uid, gid):
    """set user and group of workers processes"""
    if gid:
        try:
            os.setgid(gid)
        except OverflowError:
            os.setgid(-ctypes.c_int(-gid).value)
    if uid:
        os.setuid(uid)

def daemonize(enable_stdio_inheritance=False, auto_close_fds=True, keep_fds=None):
    """Standard daemonization of a process.
    http://www.svbug.com/documentation/comp.unix.programmer-FAQ/faq_2.html#SEC16"""
    if os.fork():
        os._exit(0)
    os.setsid()
    if os.fork():
        os._exit(0)
    os.umask(18)
    if not enable_stdio_inheritance:
        if keep_fds:
            keep_fds = set(keep_fds)
            for fd in range(0, 3):
                if fd not in keep_fds:
                    try:
                        os.close(fd)
                    except OSError:
                        pass
        else:
            os.closerange(0, 3)
        fd_null = os.open(REDIRECT_TO, os.O_RDWR)
        if fd_null != 0:
            os.dup2(fd_null, 0)
        os.dup2(fd_null, 1)
        os.dup2(fd_null, 2)
    else:
        fd_null = os.open(REDIRECT_TO, os.O_RDWR)
        if fd_null != 0:
            os.close(0)
            os.dup2(fd_null, 0)
        def redirect(stream, fd_expect):
            try:
                fd = stream.fileno()
                if fd == fd_expect and stream.isatty():
                    os.close(fd)
                    os.dup2(fd_null, fd)
            except AttributeError:
                pass
        redirect(sys.stdout, 1)
        redirect(sys.stderr, 2)

def to_bytes(s, encoding=None, errors=None):
    """Convert *s* into bytes"""
    if not isinstance(s, bytes):
        return ('%s' % s).encode(encoding or 'utf-8', errors or 'strict')
    elif not encoding or encoding == 'utf-8':
        return s
    else:
        d = s.decode('utf-8')
        return d.encode(encoding, errors or 'strict')

def to_string(s, encoding=None, errors='strict'):
    """Inverse of to_bytes"""
    if isinstance(s, bytes):
        return s.decode(encoding or 'utf-8', errors)
    elif not isinstance(s, str):
        return str(s)
    else:
        return s

def run_in_greenlet(callable):
    """Decorator to run a ``callable`` on a new greenlet.

    A ``callable`` decorated with this decorator returns a coroutine"""
    @wraps(callable)
    async def _(*args, **kwargs):
        green = greenlet(callable)
        result = green.switch(*args, **kwargs)
        while isawaitable(result):
            try:
                result = green.switch(await result)
            except Exception:
                exc_info = sys.exc_info()
                result = green.throw(*exc_info)
        return green.switch(result)
    return _

def hydrate_point(srid, *coordinates):
    """Create a new instance of a Point subclass from a raw
    set of fields. The subclass chosen is determined by the
    given SRID; a ValueError will be raised if no such
    subclass can be found."""
    try:
        point_class, dim = __srid_table[srid]
    except KeyError:
        point = Point(coordinates)
        point.srid = srid
        return point
    else:
        if len(coordinates) != dim:
            raise ValueError('SRID %d requires %d coordinates (%d provided)' % (srid, dim, len(coordinates)))
        return point_class(coordinates)

def dehydrate_point(value):
    """Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:"""
    dim = len(value)
    if dim == 2:
        return Structure(b'X', value.srid, *value)
    elif dim == 3:
        return Structure(b'Y', value.srid, *value)
    else:
        raise ValueError('Cannot dehydrate Point with %d dimensions' % dim)

def iter_items(iterable):
    """Iterate through all items (key-value pairs) within an iterable
    dictionary-like object. If the object has a `keys` method, this is
    used along with `__getitem__` to yield each pair in turn. If no
    `keys` method exists, each iterable element is assumed to be a
    2-tuple of key and value."""
    if hasattr(iterable, 'keys'):
        for key in iterable.keys():
            yield (key, iterable[key])
    else:
        for key, value in iterable:
            yield (key, value)

def _make_plan(plan_dict):
    """Construct a Plan or ProfiledPlan from a dictionary of metadata values.

    :param plan_dict:
    :return:"""
    operator_type = plan_dict['operatorType']
    identifiers = plan_dict.get('identifiers', [])
    arguments = plan_dict.get('args', [])
    children = [_make_plan(child) for child in plan_dict.get('children', [])]
    if 'dbHits' in plan_dict or 'rows' in plan_dict:
        db_hits = plan_dict.get('dbHits', 0)
        rows = plan_dict.get('rows', 0)
        return ProfiledPlan(operator_type, identifiers, arguments, children, db_hits, rows)
    else:
        return Plan(operator_type, identifiers, arguments, children)

def unit_of_work(metadata=None, timeout=None):
    """This function is a decorator for transaction functions that allows
    extra control over how the transaction is carried out.

    For example, a timeout (in seconds) may be applied::

        @unit_of_work(timeout=25.0)
        def count_people(tx):
            return tx.run("MATCH (a:Person) RETURN count(a)").single().value()"""
    def wrapper(f):
        def wrapped(*args, **kwargs):
            return f(*args, **kwargs)
        wrapped.metadata = metadata
        wrapped.timeout = timeout
        return wrapped
    return wrapper

def deprecated(message):
    """Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass"""
    def f__(f):
        def f_(*args, **kwargs):
            from warnings import warn
            warn(message, category=DeprecationWarning, stacklevel=2)
            return f(*args, **kwargs)
        f_.__name__ = f.__name__
        f_.__doc__ = f.__doc__
        f_.__dict__.update(f.__dict__)
        return f_
    return f__

def experimental(message):
    """Decorator for tagging experimental functions and methods.

    ::

        @experimental("'foo' is an experimental function and may be "
                      "removed in a future release")
        def foo(x):
            pass"""
    def f__(f):
        def f_(*args, **kwargs):
            from warnings import warn
            warn(message, category=ExperimentalWarning, stacklevel=2)
            return f(*args, **kwargs)
        f_.__name__ = f.__name__
        f_.__doc__ = f.__doc__
        f_.__dict__.update(f.__dict__)
        return f_
    return f__

def dehydrate_time(value):
    """Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:"""
    if isinstance(value, Time):
        nanoseconds = int(value.ticks * 1000000000)
    elif isinstance(value, time):
        nanoseconds = 3600000000000 * value.hour + 60000000000 * value.minute + 1000000000 * value.second + 1000 * value.microsecond
    else:
        raise TypeError('Value must be a neotime.Time or a datetime.time')
    if value.tzinfo:
        return Structure(b'T', nanoseconds, value.tzinfo.utcoffset(value).seconds)
    else:
        return Structure(b't', nanoseconds)

def dehydrate_datetime(value):
    """Dehydrator for `datetime` values.

    :param value:
    :type value: datetime
    :return:"""
    def seconds_and_nanoseconds(dt):
        if isinstance(dt, datetime):
            dt = DateTime.from_native(dt)
        zone_epoch = DateTime(1970, 1, 1, tzinfo=dt.tzinfo)
        t = dt.to_clock_time() - zone_epoch.to_clock_time()
        return (t.seconds, t.nanoseconds)
    tz = value.tzinfo
    if tz is None:
        value = utc.localize(value)
        seconds, nanoseconds = seconds_and_nanoseconds(value)
        return Structure(b'd', seconds, nanoseconds)
    elif hasattr(tz, 'zone') and tz.zone:
        seconds, nanoseconds = seconds_and_nanoseconds(value)
        return Structure(b'f', seconds, nanoseconds, tz.zone)
    else:
        seconds, nanoseconds = seconds_and_nanoseconds(value)
        return Structure(b'F', seconds, nanoseconds, tz.utcoffset(value).seconds)

def dehydrate_duration(value):
    """Dehydrator for `duration` values.

    :param value:
    :type value: Duration
    :return:"""
    return Structure(b'E', value.months, value.days, value.seconds, int(1000000000 * value.subseconds))

def cleaned_date(day, keep_datetime=False):
    """Return a "clean" date type.

    * keep a `date` unchanged
    * convert a datetime into a date,
    * convert any "duck date" type into a date using its `date()` method."""
    if not isinstance(day, (date, datetime)):
        raise UnsupportedDateType('`{}` is of unsupported type ({})'.format(day, type(day)))
    if not keep_datetime:
        if hasattr(day, 'date') and callable(day.date):
            day = day.date()
    return day

def read_relative_file(filename):
    """Return the contents of the given file.

    Its path is supposed relative to this module."""
    path = join(dirname(abspath(__file__)), filename)
    with io.open(path, encoding='utf-8') as f:
        return f.read()

def _set_k8s_attribute(obj, attribute, value):
    """Set a specific value on a kubernetes object's attribute

    obj
        an object from Kubernetes Python API client
    attribute
        Should be a Kubernetes API style attribute (with camelCase)
    value
        Can be anything (string, list, dict, k8s objects) that can be
        accepted by the k8s python client"""
    current_value = None
    attribute_name = None
    for python_attribute, json_attribute in obj.attribute_map.items():
        if json_attribute == attribute:
            attribute_name = python_attribute
            break
    else:
        raise ValueError('Attribute must be one of {}'.format(obj.attribute_map.values()))
    if hasattr(obj, attribute_name):
        current_value = getattr(obj, attribute_name)
    if current_value is not None:
        current_value = SERIALIZATION_API_CLIENT.sanitize_for_serialization(current_value)
    if isinstance(current_value, dict):
        setattr(obj, attribute_name, merge_dictionaries(current_value, value))
    elif isinstance(current_value, list):
        setattr(obj, attribute_name, current_value + value)
    else:
        setattr(obj, attribute_name, value)

def clean_pod_template(pod_template):
    """Normalize pod template and check for type errors"""
    if isinstance(pod_template, str):
        msg = 'Expected a kubernetes.client.V1Pod object, got %sIf trying to pass a yaml filename then use KubeCluster.from_yaml'
        raise TypeError(msg % pod_template)
    if isinstance(pod_template, dict):
        msg = 'Expected a kubernetes.client.V1Pod object, got %sIf trying to pass a dictionary specification then use KubeCluster.from_dict'
        raise TypeError(msg % str(pod_template))
    pod_template = copy.deepcopy(pod_template)
    if pod_template.metadata is None:
        pod_template.metadata = client.V1ObjectMeta()
    if pod_template.metadata.labels is None:
        pod_template.metadata.labels = {}
    if pod_template.spec.containers[0].env is None:
        pod_template.spec.containers[0].env = []
    return pod_template

def _cleanup_pods(namespace, labels):
    """Remove all pods with these labels in this namespace"""
    api = kubernetes.client.CoreV1Api()
    pods = api.list_namespaced_pod(namespace, label_selector=format_labels(labels))
    for pod in pods.items:
        try:
            api.delete_namespaced_pod(pod.metadata.name, namespace)
            logger.info('Deleted pod: %s', pod.metadata.name)
        except kubernetes.client.rest.ApiException as e:
