    return len(y)

def compute_svd(X, n_components, n_iter, random_state, engine):
    """Computes an SVD with k components."""
    if engine == 'auto':
        engine = 'sklearn'
    if engine == 'fbpca':
        if FBPCA_INSTALLED:
            U, s, V = fbpca.pca(X, k=n_components, n_iter=n_iter)
        else:
            raise ValueError('fbpca is not installed; please install it if you want to use it')
    elif engine == 'sklearn':
        U, s, V = extmath.randomized_svd(X, n_components=n_components, n_iter=n_iter, random_state=random_state)
    else:
        raise ValueError("engine has to be one of ('auto', 'fbpca', 'sklearn')")
    U, V = extmath.svd_flip(U, V)
    return (U, s, V)

def extract_auth_vars(request):
    """raven-js will pass both Authorization and X-Sentry-Auth depending on the browser
    and server configurations."""
    if request.META.get('HTTP_X_SENTRY_AUTH', '').startswith('Sentry'):
        return request.META['HTTP_X_SENTRY_AUTH']
    elif request.META.get('HTTP_AUTHORIZATION', '').startswith('Sentry'):
        return request.META['HTTP_AUTHORIZATION']
    else:
        args = ['%s=%s' % i for i in request.GET.items() if i[0].startswith('sentry_') and i[0] != 'sentry_data']
        if args:
            return 'Sentry %s' % ', '.join(args)
    return None

def record(message=None, timestamp=None, level=None, category=None, data=None, type=None, processor=None):
    """Records a breadcrumb for all active clients.  This is what integration
    code should use rather than invoking the `captureBreadcrumb` method
    on a specific client."""
    if timestamp is None:
        timestamp = time()
    for ctx in raven.context.get_active_contexts():
        ctx.breadcrumbs.record(timestamp, level, message, category, data, type, processor)

def ignore_logger(name_or_logger, allow_level=None):
    """Ignores a logger during breadcrumb recording.
    """
    def handler(logger, level, msg, args, kwargs):
        if allow_level is not None and level >= allow_level:
            return False
        return True
    register_special_log_handler(name_or_logger, handler)

def install_sql_hook():
    """If installed this causes Django's queries to be captured."""
    try:
        from django.db.backends.utils import CursorWrapper
    except ImportError:
        from django.db.backends.util import CursorWrapper
    try:
        real_execute = CursorWrapper.execute
        real_executemany = CursorWrapper.executemany
    except AttributeError:
        return
    def record_many_sql(vendor, alias, start, sql, param_list):
        duration = time.time() - start
        for params in param_list:
            record_sql(vendor, alias, start, duration, sql, params)
    def execute(self, sql, params=None):
        start = time.time()
        try:
            return real_execute(self, sql, params)
        finally:
            record_sql(self.db.vendor, getattr(self.db, 'alias', None), start, time.time() - start, sql, params)
    def executemany(self, sql, param_list):
        start = time.time()
        try:
            return real_executemany(self, sql, param_list)
        finally:
            record_many_sql(self.db.vendor, getattr(self.db, 'alias', None), start, sql, param_list)
    CursorWrapper.execute = execute
    CursorWrapper.executemany = executemany
    breadcrumbs.ignore_logger('django.db.backends')

def to_dict(dictish):
    """Given something that closely resembles a dictionary, we attempt
    to coerce it into a propery dictionary."""
    if hasattr(dictish, 'iterkeys'):
        m = dictish.iterkeys
    elif hasattr(dictish, 'keys'):
        m = dictish.keys
    else:
        raise ValueError(dictish)
    return dict(((k, dictish[k]) for k in m()))

def iter_traceback_frames(tb):
    """Given a traceback object, it will iterate over all
    frames that do not contain the ``__traceback_hide__``
    local variable."""
    while tb and hasattr(tb, 'tb_frame'):
        f_locals = getattr(tb.tb_frame, 'f_locals', {})
        if not _getitem_from_frame(f_locals, '__traceback_hide__'):
            yield (tb.tb_frame, getattr(tb, 'tb_lineno', None))
        tb = tb.tb_next

def iter_stack_frames(frames=None):
    """Given an optional list of frames (defaults to current stack),
    iterates over all frames that do not contain the ``__traceback_hide__``
    local variable."""
    if not frames:
        frames = inspect.stack()[1:]
    for frame, lineno in ((f[0], f[2]) for f in reversed(frames)):
        f_locals = getattr(frame, 'f_locals', {})
        if not _getitem_from_frame(f_locals, '__traceback_hide__'):
            yield (frame, lineno)

