def get_host(request):
    """A reimplementation of Django's get_host, without the
    SuspiciousOperation check."""
    if settings.USE_X_FORWARDED_HOST and 'HTTP_X_FORWARDED_HOST' in request.META:
        host = request.META['HTTP_X_FORWARDED_HOST']
    elif 'HTTP_HOST' in request.META:
        host = request.META['HTTP_HOST']
    else:
        host = request.META['SERVER_NAME']
        server_port = str(request.META['SERVER_PORT'])
        if server_port != (request.is_secure() and '443' or '80'):
            host = '%s:%s' % (host, server_port)
    return host

def install_middleware(middleware_name, lookup_names=None):
    """Install specified middleware"""
    if lookup_names is None:
        lookup_names = (middleware_name,)
    middleware_attr = 'MIDDLEWARE' if getattr(settings, 'MIDDLEWARE', None) is not None else 'MIDDLEWARE_CLASSES'
    middleware = getattr(settings, middleware_attr, ()) or ()
    if set(lookup_names).isdisjoint(set(middleware)):
        setattr(settings, middleware_attr, type(middleware)((middleware_name,)) + middleware)

def _api_scrape(json_inp, ndx):
    """Internal method to streamline the getting of data from the json

    Args:
        json_inp (json): json input from our caller
        ndx (int): index where the data is located in the api

    Returns:
        If pandas is present:
            DataFrame (pandas.DataFrame): data set from ndx within the
            API's json
        else:
            A dictionary of both headers and values from the page"""
    try:
        headers = json_inp['resultSets'][ndx]['headers']
        values = json_inp['resultSets'][ndx]['rowSet']
    except KeyError:
        try:
            headers = json_inp['resultSet'][ndx]['headers']
            values = json_inp['resultSet'][ndx]['rowSet']
        except KeyError:
            headers = json_inp['resultSet']['headers']
            values = json_inp['resultSet']['rowSet']
    if HAS_PANDAS:
        return DataFrame(values, columns=headers)
    else:
        return [dict(zip(headers, value)) for value in values]

def read_bytes(fo, writer_schema=None, reader_schema=None):
    """Bytes are encoded as a long followed by that many bytes of data."""
    size = read_long(fo)
    return fo.read(size)

def read_array(fo, writer_schema, reader_schema=None):
    """Arrays are encoded as a series of blocks.

    Each block consists of a long count value, followed by that many array
    items.  A block with count zero indicates the end of the array.  Each item
    is encoded per the array's item schema.

    If a block's count is negative, then the count is followed immediately by a
    long block size, indicating the number of bytes in the block.  The actual
    count in this case is the absolute value of the count written."""
    if reader_schema:
        def item_reader(fo, w_schema, r_schema):
            return read_data(fo, w_schema['items'], r_schema['items'])
    else:
        def item_reader(fo, w_schema, _):
            return read_data(fo, w_schema['items'])
    read_items = []
    block_count = read_long(fo)
    while block_count != 0:
        if block_count < 0:
            block_count = -block_count
            read_long(fo)
        for i in xrange(block_count):
            read_items.append(item_reader(fo, writer_schema, reader_schema))
        block_count = read_long(fo)
    return read_items

def read_map(fo, writer_schema, reader_schema=None):
    """Maps are encoded as a series of blocks.

    Each block consists of a long count value, followed by that many key/value
    pairs.  A block with count zero indicates the end of the map.  Each item is
    encoded per the map's value schema.

    If a block's count is negative, then the count is followed immediately by a
    long block size, indicating the number of bytes in the block.  The actual
    count in this case is the absolute value of the count written."""
    if reader_schema:
        def item_reader(fo, w_schema, r_schema):
            return read_data(fo, w_schema['values'], r_schema['values'])
    else:
        def item_reader(fo, w_schema, _):
            return read_data(fo, w_schema['values'])
    read_items = {}
    block_count = read_long(fo)
    while block_count != 0:
        if block_count < 0:
            block_count = -block_count
            read_long(fo)
        for i in xrange(block_count):
            key = read_utf8(fo)
            read_items[key] = item_reader(fo, writer_schema, reader_schema)
        block_count = read_long(fo)
    return read_items

def read_union(fo, writer_schema, reader_schema=None):
    """A union is encoded by first writing a long value indicating the
    zero-based position within the union of the schema of its value.

    The value is then encoded per the indicated schema within the union."""
    index = read_long(fo)
    if reader_schema:
        if not isinstance(reader_schema, list):
            if match_types(writer_schema[index], reader_schema):
                return read_data(fo, writer_schema[index], reader_schema)
        else:
            for schema in reader_schema:
                if match_types(writer_schema[index], schema):
                    return read_data(fo, writer_schema[index], schema)
        msg = 'schema mismatch: %s not found in %s' % (writer_schema, reader_schema)
        raise SchemaResolutionError(msg)
    else:
        return read_data(fo, writer_schema[index])

def read_data(fo, writer_schema, reader_schema=None):
    """Read data from file object according to schema."""
    record_type = extract_record_type(writer_schema)
    logical_type = extract_logical_type(writer_schema)
    if reader_schema and record_type in AVRO_TYPES:
        if writer_schema == reader_schema:
            reader_schema = None
        else:
            match_schemas(writer_schema, reader_schema)
    reader_fn = READERS.get(record_type)
    if reader_fn:
        try:
            data = reader_fn(fo, writer_schema, reader_schema)
        except StructError:
            raise EOFError('cannot read %s from %s' % (record_type, fo))
        if 'logicalType' in writer_schema:
            fn = LOGICAL_READERS.get(logical_type)
            if fn:
                return fn(data, writer_schema, reader_schema)
        if reader_schema is not None:
            return maybe_promote(data, record_type, extract_record_type(reader_schema))
        else:
            return data
    else:
        return read_data(fo, SCHEMA_DEFS[record_type], SCHEMA_DEFS.get(reader_schema))

def _iter_avro_records(fo, header, codec, writer_schema, reader_schema):
    """Return iterator over avro records."""
    sync_marker = header['sync']
    read_block = BLOCK_READERS.get(codec)
    if not read_block:
        raise ValueError('Unrecognized codec: %r' % codec)
    block_count = 0
    while True:
        try:
            block_count = read_long(fo)
        except StopIteration:
            return
        block_fo = read_block(fo)
        for i in xrange(block_count):
            yield read_data(block_fo, writer_schema, reader_schema)
        skip_sync(fo, sync_marker)

def _iter_avro_blocks(fo, header, codec, writer_schema, reader_schema):
    """Return iterator over avro blocks."""
    sync_marker = header['sync']
    read_block = BLOCK_READERS.get(codec)
    if not read_block:
        raise ValueError('Unrecognized codec: %r' % codec)
    while True:
        offset = fo.tell()
        try:
            num_block_records = read_long(fo)
        except StopIteration:
            return
        block_bytes = read_block(fo)
        skip_sync(fo, sync_marker)
        size = fo.tell() - offset
        yield Block(block_bytes, num_block_records, codec, reader_schema, writer_schema, offset, size)

def prepare_timestamp_millis(data, schema):
    """Converts datetime.datetime object to int timestamp with milliseconds
    """
    if isinstance(data, datetime.datetime):
        if data.tzinfo is not None:
            delta = data - epoch
            return int(delta.total_seconds() * MLS_PER_SECOND)
        t = int(time.mktime(data.timetuple())) * MLS_PER_SECOND + int(data.microsecond / 1000)
        return t
    else:
        return data

def prepare_timestamp_micros(data, schema):
    """Converts datetime.datetime to int timestamp with microseconds"""
    if isinstance(data, datetime.datetime):
        if data.tzinfo is not None:
            delta = data - epoch
            return int(delta.total_seconds() * MCS_PER_SECOND)
        t = int(time.mktime(data.timetuple())) * MCS_PER_SECOND + data.microsecond
        return t
    else:
        return data

def prepare_date(data, schema):
    """Converts datetime.date to int timestamp"""
    if isinstance(data, datetime.date):
        return data.toordinal() - DAYS_SHIFT
    else:
        return data

def prepare_uuid(data, schema):
    """Converts uuid.UUID to
    string formatted UUID xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx"""
    if isinstance(data, uuid.UUID):
        return str(data)
    else:
        return data

def prepare_time_millis(data, schema):
    """Convert datetime.time to int timestamp with milliseconds"""
    if isinstance(data, datetime.time):
        return int(data.hour * MLS_PER_HOUR + data.minute * MLS_PER_MINUTE + data.second * MLS_PER_SECOND + int(data.microsecond / 1000))
    else:
        return data

def prepare_time_micros(data, schema):
    """Convert datetime.time to int timestamp with microseconds"""
    if isinstance(data, datetime.time):
        return long(data.hour * MCS_PER_HOUR + data.minute * MCS_PER_MINUTE + data.second * MCS_PER_SECOND + data.microsecond)
    else:
        return data

def prepare_bytes_decimal(data, schema):
    """Convert decimal.Decimal to bytes"""
    if not isinstance(data, decimal.Decimal):
        return data
    scale = schema.get('scale', 0)
    sign, digits, exp = data.as_tuple()
    if -exp > scale:
        raise ValueError('Scale provided in schema does not match the decimal')
    delta = exp + scale
    if delta > 0:
        digits = digits + (0,) * delta
    unscaled_datum = 0
    for digit in digits:
        unscaled_datum = unscaled_datum * 10 + digit
    bits_req = unscaled_datum.bit_length() + 1
    if sign:
        unscaled_datum = (1 << bits_req) - unscaled_datum
    bytes_req = bits_req // 8
    padding_bits = ~((1 << bits_req) - 1) if sign else 0
    packed_bits = padding_bits | unscaled_datum
    bytes_req += 1 if bytes_req << 3 < bits_req else 0
    tmp = MemoryIO()
    for index in range(bytes_req - 1, -1, -1):
        bits_to_write = packed_bits >> 8 * index
        tmp.write(mk_bits(bits_to_write & 255))
    return tmp.getvalue()

def write_record(fo, datum, schema):
    """A record is encoded by encoding the values of its fields in the order
    that they are declared. In other words, a record is encoded as just the
    concatenation of the encodings of its fields.  Field values are encoded per
    their schema."""
    for field in schema['fields']:
        name = field['name']
        if name not in datum and 'default' not in field and ('null' not in field['type']):
            raise ValueError('no value and no default for %s' % name)
        write_data(fo, datum.get(name, field.get('default')), field['type'])

def write_data(fo, datum, schema):
    """Write a datum of data to output stream.

    Paramaters
    ----------
    fo: file-like
        Output file
    datum: object
        Data to write
    schema: dict
        Schemda to use"""
    record_type = extract_record_type(schema)
    logical_type = extract_logical_type(schema)
    fn = WRITERS.get(record_type)
    if fn:
        if logical_type:
            prepare = LOGICAL_WRITERS.get(logical_type)
            if prepare:
                datum = prepare(datum, schema)
        return fn(fo, datum, schema)
    else:
        return write_data(fo, datum, SCHEMA_DEFS[record_type])

def validate_union(datum, schema, parent_ns=None, raise_errors=True):
    """Check that the data is a list type with possible options to
    validate as True.

    Parameters
    ----------
    datum: Any
        Data being validated
    schema: dict
        Schema
    parent_ns: str
        parent namespace
    raise_errors: bool
        If true, raises ValidationError on invalid data"""
    if isinstance(datum, tuple):
        name, datum = datum
        for candidate in schema:
            if extract_record_type(candidate) == 'record':
                if name == candidate['name']:
                    return validate(datum, schema=candidate, field=parent_ns, raise_errors=raise_errors)
        else:
            return False
    errors = []
    for s in schema:
        try:
            ret = validate(datum, schema=s, field=parent_ns, raise_errors=raise_errors)
            if ret:
                return True
        except ValidationError as e:
            errors.extend(e.errors)
    if raise_errors:
        raise ValidationError(*errors)
    return False

def login(request):
    """Logs in the user via given login and password."""
    serializer_class = registration_settings.LOGIN_SERIALIZER_CLASS
    serializer = serializer_class(data=request.data)
    serializer.is_valid(raise_exception=True)
    user = serializer.get_authenticated_user()
    if not user:
        raise BadRequest('Login or password invalid.')
    extra_data = perform_login(request, user)
    return get_ok_response('Login successful', extra_data=extra_data)

def logout(request):
    """Logs out the user. returns an error if the user is not
    authenticated."""
    user = request.user
    serializer = LogoutSerializer(data=request.data)
    serializer.is_valid(raise_exception=True)
    data = serializer.validated_data
    if should_authenticate_session():
        auth.logout(request)
    if should_retrieve_token() and data['revoke_token']:
        try:
            user.auth_token.delete()
        except Token.DoesNotExist:
            raise BadRequest('Cannot remove non-existent token')
    return get_ok_response('Logout successful')

def get_object_or_404(queryset, *filter_args, **filter_kwargs):
    """Same as Django's standard shortcut, but make sure to also raise 404
    if the filter_kwargs don't match the required types.

    This function was copied from rest_framework.generics because of issue #36."""
    try:
        return _get_object_or_404(queryset, *filter_args, **filter_kwargs)
    except (TypeError, ValueError, ValidationError):
        raise Http404

def profile(request):
    """Get or set user profile."""
    serializer_class = registration_settings.PROFILE_SERIALIZER_CLASS
    if request.method in ['POST', 'PUT', 'PATCH']:
        partial = request.method == 'PATCH'
        serializer = serializer_class(instance=request.user, data=request.data, partial=partial)
        serializer.is_valid(raise_exception=True)
        serializer.save()
    else:
        serializer = serializer_class(instance=request.user)
    return Response(serializer.data)

def verify_registration(request):
    """Verify registration via signature."""
    user = process_verify_registration_data(request.data)
    extra_data = None
    if registration_settings.REGISTER_VERIFICATION_AUTO_LOGIN:
        extra_data = perform_login(request, user)
    return get_ok_response('User verified successfully', extra_data=extra_data)

def send_reset_password_link(request):
    """Send email with reset password link."""
    if not registration_settings.RESET_PASSWORD_VERIFICATION_ENABLED:
        raise Http404()
    serializer = SendResetPasswordLinkSerializer(data=request.data)
    serializer.is_valid(raise_exception=True)
    login = serializer.validated_data['login']
    user = None
    for login_field in get_login_fields():
        user = get_user_by_lookup_dict({login_field: login}, default=None, require_verified=False)
        if user:
            break
    if not user:
        raise UserNotFound()
    signer = ResetPasswordSigner({'user_id': user.pk}, request=request)
    template_config = registration_settings.RESET_PASSWORD_VERIFICATION_EMAIL_TEMPLATES
    send_verification_notification(user, signer, template_config)
    return get_ok_response('Reset link sent')

def _is_colorbar_heuristic(obj):
    """Find out if the object is in fact a color bar.
    """
    try:
        aspect = float(obj.get_aspect())
    except ValueError:
        return False
    limit_ratio = 5.0
    return aspect >= limit_ratio and len(obj.get_xticks()) == 0 or (aspect <= 1.0 / limit_ratio and len(obj.get_yticks()) == 0)

def _mpl_cmap2pgf_cmap(cmap, data):
    """Converts a color map as given in matplotlib to a color map as
    represented in PGFPlots."""
    if isinstance(cmap, mpl.colors.LinearSegmentedColormap):
        return _handle_linear_segmented_color_map(cmap, data)
    assert isinstance(cmap, mpl.colors.ListedColormap), 'Only LinearSegmentedColormap and ListedColormap are supported'
    return _handle_listed_color_map(cmap, data)

def _scale_to_int(X, max_val=None):
    """Scales the array X such that it contains only integers."""
    if max_val is None:
        X = X / _gcd_array(X)
    else:
        X = X / max(1 / max_val, _gcd_array(X))
    return [int(entry) for entry in X]

def _linear_interpolation(x, X, Y):
    """Given two data points [X,Y], linearly interpolate those at x.
    """
    return (Y[1] * (x - X[0]) + Y[0] * (X[1] - x)) / (X[1] - X[0])

def _find_associated_colorbar(obj):
    """A rather poor way of telling whether an axis has a colorbar associated:
    Check the next axis environment, and see if it is de facto a color bar;
    if yes, return the color bar object."""
    for child in obj.get_children():
        try:
            cbar = child.colorbar
        except AttributeError:
            continue
        if cbar is not None:
            return cbar
    return None

def get_draw_options(data, obj, ec, fc, style, width):
    """Get the draw options for a given (patch) object.
    """
    draw_options = []
    if ec is not None:
        data, col, ec_rgba = color.mpl_color2xcolor(data, ec)
        if ec_rgba[3] != 0.0:
            draw_options.append('draw={}'.format(col))
    if fc is not None:
        data, col, fc_rgba = color.mpl_color2xcolor(data, fc)
        if fc_rgba[3] != 0.0:
            draw_options.append('fill={}'.format(col))
    ff = data['float format']
    if ec is not None and fc is not None and (ec_rgba[3] != 1.0) and (ec_rgba[3] == fc_rgba[3]):
        draw_options.append(('opacity=' + ff).format(ec[3]))
    else:
        if ec is not None and ec_rgba[3] != 1.0:
            draw_options.append(('draw opacity=' + ff).format(ec_rgba[3]))
        if fc is not None and fc_rgba[3] != 1.0:
            draw_options.append(('fill opacity=' + ff).format(fc_rgba[3]))
    if width is not None:
        w = mpl_linewidth2pgfp_linewidth(data, width)
        if w:
            draw_options.append(w)
    if style is not None:
        ls = mpl_linestyle2pgfplots_linestyle(style)
        if ls is not None and ls != 'solid':
            draw_options.append(ls)
    return (data, draw_options)

def mpl_linestyle2pgfplots_linestyle(line_style, line=None):
    """Translates a line style of matplotlib to the corresponding style
    in PGFPlots."""
    if isinstance(line_style, tuple):
        if line_style[0] is None:
            return None
        if len(line_style[1]) == 2:
            return 'dash pattern=on {}pt off {}pt'.format(*line_style[1])
        assert len(line_style[1]) == 4
        return 'dash pattern=on {}pt off {}pt on {}pt off {}pt'.format(*line_style[1])
    if isinstance(line, mpl.lines.Line2D) and line.is_dashed():
        default_dashOffset, default_dashSeq = mpl.lines._get_dash_pattern(line_style)
        dashSeq = line._us_dashSeq
        dashOffset = line._us_dashOffset
        lst = list()
        if dashSeq != default_dashSeq:
            format_string = ' '.join(len(dashSeq) // 2 * ['on {}pt off {}pt'])
            lst.append('dash pattern=' + format_string.format(*dashSeq))
        if dashOffset != default_dashOffset:
            lst.append('dash phase={}pt'.format(dashOffset))
        if len(lst) > 0:
            return ', '.join(lst)
    return {'': None, 'None': None, 'none': None, '-': 'solid', 'solid': 'solid', ':': 'dotted', '--': 'dashed', '-.': 'dash pattern=on 1pt off 3pt on 3pt off 3pt'}[line_style]

def draw_patch(data, obj):
    """Return the PGFPlots code for patches.
    """
    data, draw_options = mypath.get_draw_options(data, obj, obj.get_edgecolor(), obj.get_facecolor(), obj.get_linestyle(), obj.get_linewidth())
    if isinstance(obj, mpl.patches.Rectangle):
        return _draw_rectangle(data, obj, draw_options)
    elif isinstance(obj, mpl.patches.Ellipse):
        return _draw_ellipse(data, obj, draw_options)
    data, path_command, _, _ = mypath.draw_path(data, obj.get_path(), draw_options=draw_options)
    return (data, path_command)

def draw_patchcollection(data, obj):
    """Returns PGFPlots code for a number of patch objects.
    """
    content = []
    try:
        ec = obj.get_edgecolor()[0]
    except IndexError:
        ec = None
    try:
        fc = obj.get_facecolor()[0]
    except IndexError:
        fc = None
    try:
        ls = obj.get_linestyle()[0]
    except IndexError:
        ls = None
    try:
        w = obj.get_linewidth()[0]
    except IndexError:
        w = None
    data, draw_options = mypath.get_draw_options(data, obj, ec, fc, ls, w)
    paths = obj.get_paths()
    for path in paths:
        data, cont, draw_options, is_area = mypath.draw_path(data, path, draw_options=draw_options)
        content.append(cont)
    if _is_in_legend(obj):
        tpe = 'area legend' if is_area else 'line legend'
        do = ', '.join([tpe] + draw_options) if draw_options else ''
        content += ['\\addlegendimage{{{}}}\n'.format(do), '\\addlegendentry{{{}}}\n\n'.format(obj.get_label())]
    else:
        content.append('\n')
    return (data, content)

def _draw_rectangle(data, obj, draw_options):
    """Return the PGFPlots code for rectangles.
    """
    label = obj.get_label()
    if label == '':
        return (data, [])
    handles, labels = obj.axes.get_legend_handles_labels()
    labelsFound = [label for h, label in zip(handles, labels) if obj in h.get_children()]
    if len(labelsFound) == 1:
        label = labelsFound[0]
    left_lower_x = obj.get_x()
    left_lower_y = obj.get_y()
    ff = data['float format']
    cont = ('\\draw[{}] (axis cs:' + ff + ',' + ff + ') rectangle (axis cs:' + ff + ',' + ff + ');\n').format(','.join(draw_options), left_lower_x, left_lower_y, left_lower_x + obj.get_width(), left_lower_y + obj.get_height())
    if label != '_nolegend_' and label not in data['rectangle_legends']:
        data['rectangle_legends'].add(label)
        cont += '\\addlegendimage{{ybar,ybar legend,{}}};\n'.format(','.join(draw_options))
        cont += '\\addlegendentry{{{}}}\n\n'.format(label)
    return (data, cont)

def _draw_ellipse(data, obj, draw_options):
    """Return the PGFPlots code for ellipses.
    """
    if isinstance(obj, mpl.patches.Circle):
        return _draw_circle(data, obj, draw_options)
    x, y = obj.center
    ff = data['float format']
    if obj.angle != 0:
        fmt = 'rotate around={{' + ff + ':(axis cs:' + ff + ',' + ff + ')}}'
        draw_options.append(fmt.format(obj.angle, x, y))
    cont = ('\\draw[{}] (axis cs:' + ff + ',' + ff + ') ellipse (' + ff + ' and ' + ff + ');\n').format(','.join(draw_options), x, y, 0.5 * obj.width, 0.5 * obj.height)
    return (data, cont)

def _mpl_marker2pgfp_marker(data, mpl_marker, marker_face_color):
    """Translates a marker style of matplotlib to the corresponding style
    in PGFPlots."""
    try:
        pgfplots_marker = _MP_MARKER2PGF_MARKER[mpl_marker]
    except KeyError:
        pass
    else:
        if marker_face_color is not None and pgfplots_marker == 'o':
            pgfplots_marker = '*'
            data['tikz libs'].add('plotmarks')
        marker_options = None
        return (data, pgfplots_marker, marker_options)
    try:
        data['tikz libs'].add('plotmarks')
        pgfplots_marker, marker_options = _MP_MARKER2PLOTMARKS[mpl_marker]
    except KeyError:
        pass
    else:
        if marker_face_color is not None and (not isinstance(marker_face_color, str) or marker_face_color.lower() != 'none') and (pgfplots_marker not in ['|', '-', 'asterisk', 'star']):
            pgfplots_marker += '*'
        return (data, pgfplots_marker, marker_options)
    return (data, None, None)

def _transform_positioning(ha, va):
    """Converts matplotlib positioning to pgf node positioning.
    Not quite accurate but the results are equivalent more or less."""
    if ha == 'center' and va == 'center':
        return None
    ha_mpl_to_tikz = {'right': 'east', 'left': 'west', 'center': ''}
    va_mpl_to_tikz = {'top': 'north', 'bottom': 'south', 'center': '', 'baseline': 'base'}
    return 'anchor={} {}'.format(va_mpl_to_tikz[va], ha_mpl_to_tikz[ha]).strip()

def get_k8s_model(model_type, model_dict):
    """Returns an instance of type specified model_type from an model instance or
    represantative dictionary."""
    model_dict = copy.deepcopy(model_dict)
    if isinstance(model_dict, model_type):
        return model_dict
    elif isinstance(model_dict, dict):
        model_dict = _map_dict_keys_to_model_attributes(model_type, model_dict)
        return model_type(**model_dict)
    else:
        raise AttributeError("Expected object of type 'dict' (or '{}') but got '{}'.".format(model_type.__name__, type(model_dict).__name__))

def _get_k8s_model_dict(model_type, model):
    """Returns a dictionary representation of a provided model type"""
    model = copy.deepcopy(model)
    if isinstance(model, model_type):
        return model.to_dict()
    elif isinstance(model, dict):
        return _map_dict_keys_to_model_attributes(model_type, model)
    else:
        raise AttributeError("Expected object of type '{}' (or 'dict') but got '{}'.".format(model_type.__name__, type(model).__name__))

def _map_dict_keys_to_model_attributes(model_type, model_dict):
    """Maps a dict's keys to the provided models attributes using its attribute_map
    attribute. This is (always?) the same as converting camelCase to snake_case.
    Note that the function will not influence nested object's keys."""
    new_dict = {}
    for key, value in model_dict.items():
        new_dict[_get_k8s_model_attribute(model_type, key)] = value
    return new_dict

def duration_expired(start_time, duration_seconds):
    """Return True if ``duration_seconds`` have expired since ``start_time``"""
    if duration_seconds is not None:
        delta_seconds = datetime_delta_to_seconds(dt.datetime.now() - start_time)
        if delta_seconds >= duration_seconds:
            return True
    return False

def available():
    """Returns list of available font names."""
    font_dir = os.path.dirname(__file__)
    names = [os.path.basename(os.path.splitext(f)[0]) for f in glob(os.path.join(font_dir, '*.pil'))]
    return sorted(names)

def load(name):
    """Loads the font specified by name and returns it as an instance of
    `PIL.ImageFont <http://pillow.readthedocs.io/en/latest/reference/ImageFont.html>`_
    class."""
    try:
        font_dir = os.path.dirname(__file__)
        pil_file = os.path.join(font_dir, '{}.pil'.format(name))
        pbm_file = os.path.join(font_dir, '{}.pbm'.format(name))
        return ImageFont.load(pil_file)
    except FileNotFoundError:
        raise Exception('Failed to load font "{}". '.format(name) + 'Check ev3dev.fonts.available() for the list of available fonts')

def _make_scales(notes):
    """Utility function used by Sound class for building the note frequencies table"""
    res = dict()
    for note, freq in notes:
        freq = round(freq)
        for n in note.split('/'):
            res[n] = freq
    return res

def get_current_platform():
    """Look in /sys/class/board-info/ to determine the platform type.

    This can return 'ev3', 'evb', 'pistorms', 'brickpi', 'brickpi3' or 'fake'."""
    board_info_dir = '/sys/class/board-info/'
    if not os.path.exists(board_info_dir) or os.environ.get('FAKE_SYS'):
        return 'fake'
    for board in os.listdir(board_info_dir):
        uevent_filename = os.path.join(board_info_dir, board, 'uevent')
        if os.path.exists(uevent_filename):
            with open(uevent_filename, 'r') as fh:
                for line in fh.readlines():
                    key, value = line.strip().split('=')
                    if key == 'BOARD_INFO_MODEL':
                        if value == 'LEGO MINDSTORMS EV3':
                            return 'ev3'
                        elif value in ('FatcatLab EVB', 'QuestCape'):
                            return 'evb'
                        elif value == 'PiStorms':
                            return 'pistorms'
                        elif value == 'Dexter Industries BrickPi':
                            return 'brickpi'
                        elif value == 'Dexter Industries BrickPi3':
                            return 'brickpi3'
                        elif value == 'FAKE-SYS':
                            return 'fake'
    return None

def list_device_names(class_path, name_pattern, **kwargs):
    """This is a generator function that lists names of all devices matching the
    provided parameters.

    Parameters:
        class_path: class path of the device, a subdirectory of /sys/class.
            For example, '/sys/class/tacho-motor'.
        name_pattern: pattern that device name should match.
            For example, 'sensor*' or 'motor*'. Default value: '*'.
        keyword arguments: used for matching the corresponding device
            attributes. For example, address='outA', or
            driver_name=['lego-ev3-us', 'lego-nxt-us']. When argument value
            is a list, then a match against any entry of the list is
            enough."""
    if not os.path.isdir(class_path):
        return
    def matches(attribute, pattern):
        try:
            with io.FileIO(attribute) as f:
                value = f.read().strip().decode()
        except:
            return False
        if isinstance(pattern, list):
            return any([value.find(p) >= 0 for p in pattern])
        else:
            return value.find(pattern) >= 0
    for f in os.listdir(class_path):
        if fnmatch.fnmatch(f, name_pattern):
            path = class_path + '/' + f
            if all([matches(path + '/' + k, kwargs[k]) for k in kwargs]):
                yield f

def _orted_process():
    """Waits maximum of 5 minutes for orted process to start"""
    for i in range(5 * 60):
        procs = [p for p in psutil.process_iter(attrs=['name']) if p.info['name'] == 'orted']
        if procs:
            return procs
        time.sleep(1)

def _parse_custom_mpi_options(custom_mpi_options):
    """Parse custom MPI options provided by user. Known options default value will be overridden
    and unknown options would be identified separately."""
    parser = argparse.ArgumentParser()
    parser.add_argument('--NCCL_DEBUG', default='INFO', type=str)
    return parser.parse_known_args(custom_mpi_options.split())

def _timestamp():
    """Return a timestamp with microsecond precision."""
    moment = time.time()
    moment_us = repr(moment).split('.')[1]
    return time.strftime('%Y-%m-%d-%H-%M-%S-{}'.format(moment_us), time.gmtime(moment))

def to_env_vars(mapping):
    """Transform a dictionary in a dictionary of env vars.
    Example:
        >>>env_vars = mapping.to_env_vars({'model_dir': '/opt/ml/model', 'batch_size': 25})
        >>>
        >>>print(args)
        ['MODEL_DIR', '/opt/ml/model', 'BATCH_SIZE', 25]
    Args:
        mapping (dict[str, object]): A Python mapping.
    Returns:
        (dict): Dictionary of env vars"""
    def format_key(key):
        """Decode a key, adds a SM_ prefix to the key and upper case it"""
        if key:
            decoded_name = 'SM_%s' % str(key).upper()
            return decoded_name
        else:
            return ''
    def format_value(_mapping):
        if six.PY3 and isinstance(_mapping, six.binary_type):
            return _mapping.decode('latin1')
        elif _mapping is None:
            return ''
        elif isinstance(_mapping, six.string_types):
            return str(_mapping)
        else:
            return json.dumps(_mapping, sort_keys=True, separators=(',', ':'), ensure_ascii=True)
    return {format_key(k): format_value(v) for k, v in mapping.items()}

def _decode(obj):
    """Decode an object to unicode.
    Args:
        obj (bytes or str or unicode or anything serializable): object to be decoded
    Returns:
        object decoded in unicode."""
    if obj is None:
        return u''
    if six.PY3 and isinstance(obj, six.binary_type):
        return obj.decode('latin1')
    elif six.PY3:
        return str(obj)
    elif isinstance(obj, six.text_type):
        return obj
    else:
        return str(obj).decode('utf-8')

