        try:
            sys.stdout.write('Running: %s\n' % fn.__name__)
            fn()
            sys.stdout.write('\n')
        except KeyboardInterrupt:
            sys.stdout.write('\nSkipping example.\n\n')
            time.sleep(0.2)
    examples.append(wrapped)
    return wrapped

def inner(tensor0: BKTensor, tensor1: BKTensor) -> BKTensor:
    """Return the inner product between two states"""
    N = rank(tensor0)
    axes = list(range(N))
    return tf.tensordot(tf.math.conj(tensor0), tensor1, axes=(axes, axes))

def qubo_circuit(graph: nx.Graph, steps: int, beta: Sequence, gamma: Sequence) -> Circuit:
    """A QAOA circuit for the Quadratic Unconstrained Binary Optimization
    problem (i.e. an Ising model).

    Args:
        graph : a networkx graph instance with optional edge and node weights
        steps : number of QAOA steps
        beta  : driver parameters (One per step)
        gamma : cost parameters (One per step)"""
    qubits = list(graph.nodes())
    circ = Circuit()
    for q0 in qubits:
        circ += H(q0)
    for p in range(0, steps):
        for q0, q1 in graph.edges():
            weight = graph[q0][q1].get('weight', 1.0)
            circ += ZZ(-weight * gamma[p] / np.pi, q0, q1)
        for q0 in qubits:
            node_weight = graph.nodes[q0].get('weight', None)
            if node_weight is not None:
                circ += RZ(node_weight, q0)
        for q0 in qubits:
            circ += RX(beta[p], q0)
    return circ

def graph_cuts(graph: nx.Graph) -> np.ndarray:
    """For the given graph, return the cut value for all binary assignments
    of the graph."""
    N = len(graph)
    diag_hamiltonian = np.zeros(shape=[2] * N, dtype=np.double)
    for q0, q1 in graph.edges():
        for index, _ in np.ndenumerate(diag_hamiltonian):
            if index[q0] != index[q1]:
                weight = graph[q0][q1].get('weight', 1)
                diag_hamiltonian[index] += weight
    return diag_hamiltonian

def zero_state(qubits: Union[int, Qubits]) -> State:
    """Return the all-zero state on N qubits"""
    N, qubits = qubits_count_tuple(qubits)
    ket = np.zeros(shape=[2] * N)
    ket[(0,) * N] = 1
    return State(ket, qubits)

def w_state(qubits: Union[int, Qubits]) -> State:
    """Return a W state on N qubits"""
    N, qubits = qubits_count_tuple(qubits)
    ket = np.zeros(shape=[2] * N)
    for n in range(N):
        idx = np.zeros(shape=N, dtype=int)
        idx[n] += 1
        ket[tuple(idx)] = 1 / sqrt(N)
    return State(ket, qubits)

def random_state(qubits: Union[int, Qubits]) -> State:
    """Return a random state from the space of N qubits"""
    N, qubits = qubits_count_tuple(qubits)
    ket = np.random.normal(size=[2] * N) + 1j * np.random.normal(size=[2] * N)
    return State(ket, qubits).normalize()

def join_states(*states: State) -> State:
    """Join two state vectors into a larger qubit state"""
    vectors = [ket.vec for ket in states]
    vec = reduce(outer_product, vectors)
    return State(vec.tensor, vec.qubits)

def print_state(state: State, file: TextIO=None) -> None:
    """Print a state vector"""
    state = state.vec.asarray()
    for index, amplitude in np.ndenumerate(state):
        ket = ''.join([str(n) for n in index])
        print(ket, ':', amplitude, file=file)

def mixed_density(qubits: Union[int, Qubits]) -> Density:
    """Returns the completely mixed density matrix"""
    N, qubits = qubits_count_tuple(qubits)
    matrix = np.eye(2 ** N) / 2 ** N
    return Density(matrix, qubits)

def join_densities(*densities: Density) -> Density:
    """Join two mixed states into a larger qubit state"""
    vectors = [rho.vec for rho in densities]
    vec = reduce(outer_product, vectors)
    memory = dict(ChainMap(*[rho.memory for rho in densities]))
    return Density(vec.tensor, vec.qubits, memory)

def sX(qubit: Qubit, coefficient: complex=1.0) -> Pauli:
    """Return the Pauli sigma_X operator acting on the given qubit"""
    return Pauli.sigma(qubit, 'X', coefficient)

def sY(qubit: Qubit, coefficient: complex=1.0) -> Pauli:
    """Return the Pauli sigma_Y operator acting on the given qubit"""
    return Pauli.sigma(qubit, 'Y', coefficient)

def sZ(qubit: Qubit, coefficient: complex=1.0) -> Pauli:
    """Return the Pauli sigma_Z operator acting on the given qubit"""
    return Pauli.sigma(qubit, 'Z', coefficient)

def sI(qubit: Qubit, coefficient: complex=1.0) -> Pauli:
    """Return the Pauli sigma_I (identity) operator. The qubit is irrelevant,
    but kept as an  argument for consistency"""
    return Pauli.sigma(qubit, 'I', coefficient)

def pauli_sum(*elements: Pauli) -> Pauli:
    """Return the sum of elements of the Pauli algebra"""
    terms = []
    key = itemgetter(0)
    for term, grp in groupby(heapq.merge(*elements, key=key), key=key):
        coeff = sum((g[1] for g in grp))
        if not isclose(coeff, 0.0):
            terms.append((term, coeff))
    return Pauli(tuple(terms))

def pauli_product(*elements: Pauli) -> Pauli:
    """Return the product of elements of the Pauli algebra"""
    result_terms = []
    for terms in product(*elements):
        coeff = reduce(mul, [term[1] for term in terms])
        ops = (term[0] for term in terms)
        out = []
        key = itemgetter(0)
        for qubit, qops in groupby(heapq.merge(*ops, key=key), key=key):
            res = next(qops)[1]
            for op in qops:
                pair = res + op[1]
                res, rescoeff = PAULI_PROD[pair]
                coeff *= rescoeff
            if res != 'I':
                out.append((qubit, res))
        p = Pauli(((tuple(out), coeff),))
        result_terms.append(p)
    return pauli_sum(*result_terms)

def pauli_pow(pauli: Pauli, exponent: int) -> Pauli:
    """Raise an element of the Pauli algebra to a non-negative integer power."""
    if not isinstance(exponent, int) or exponent < 0:
        raise ValueError('The exponent must be a non-negative integer.')
    if exponent == 0:
        return Pauli.identity()
    if exponent == 1:
        return pauli
    y = Pauli.identity()
    x = pauli
    n = exponent
    while n > 1:
        if n % 2 == 0:
            x = x * x
            n = n // 2
        else:
            y = x * y
            x = x * x
            n = (n - 1) // 2
    return x * y

def pauli_commuting_sets(element: Pauli) -> Tuple[Pauli, ...]:
    """Gather the terms of a Pauli polynomial into commuting sets.

    Uses the algorithm defined in (Raeisi, Wiebe, Sanders,
    arXiv:1108.4318, 2011) to find commuting sets. Except uses commutation
    check from arXiv:1405.5749v2"""
    if len(element) < 2:
        return (element,)
    groups: List[Pauli] = []
    for term in element:
        pterm = Pauli((term,))
        assigned = False
        for i, grp in enumerate(groups):
            if paulis_commute(grp, pterm):
                groups[i] = grp + pterm
                assigned = True
                break
        if not assigned:
            groups.append(pterm)
    return tuple(groups)

def inner(tensor0: BKTensor, tensor1: BKTensor) -> BKTensor:
    """Return the inner product between two tensors"""
    return np.vdot(tensor0, tensor1)

def invert_map(mapping: dict, one_to_one: bool=True) -> dict:
    """Invert a dictionary. If not one_to_one then the inverted
    map will contain lists of former keys as values."""
    if one_to_one:
        inv_map = {value: key for key, value in mapping.items()}
    else:
        inv_map = {}
        for key, value in mapping.items():
            inv_map.setdefault(value, set()).add(key)
    return inv_map

def bitlist_to_int(bitlist: Sequence[int]) -> int:
    """Converts a sequence of bits to an integer.

    >>> from quantumflow.utils import bitlist_to_int
    >>> bitlist_to_int([1, 0, 0])
    4"""
    return int(''.join([str(d) for d in bitlist]), 2)

def deprecated(func: Callable) -> Callable:
    """This is a decorator which can be used to mark functions
    as deprecated. It will result in a warning being emitted
    when the function is used."""
    @functools.wraps(func)
    def _new_func(*args: Any, **kwargs: Any) -> Any:
        warnings.simplefilter('always', DeprecationWarning)
        warnings.warn('Call to deprecated function {}.'.format(func.__name__), category=DeprecationWarning, stacklevel=2)
        warnings.simplefilter('default', DeprecationWarning)
        return func(*args, **kwargs)
    return _new_func

def octagonal_tiling_graph(M: int, N: int) -> nx.Graph:
    """Return the octagonal tiling graph (4.8.8, truncated square tiling,
    truncated quadrille) of MxNx8 nodes

    The 'positions' node attribute gives node coordinates for the octagonal
    tiling. (Nodes are located on a square lattice, and edge lengths are
    uneven)"""
    grp = nx.Graph()
    octogon = [[(1, 0), (0, 1)], [(0, 1), (0, 2)], [(0, 2), (1, 3)], [(1, 3), (2, 3)], [(2, 3), (3, 2)], [(3, 2), (3, 1)], [(3, 1), (2, 0)], [(2, 0), (1, 0)]]
    left = [[(1, 0), (1, -1)], [(2, 0), (2, -1)]]
    up = [[(0, 1), (-1, 1)], [(0, 2), (-1, 2)]]
    for m in range(M):
        for n in range(N):
            edges = octogon
            if n != 0:
                edges = edges + left
            if m != 0:
                edges = edges + up
            for (x0, y0), (x1, y1) in edges:
                grp.add_edge((m * 4 + x0, n * 4 + y0), (m * 4 + x1, n * 4 + y1))
    positions = {node: node for node in grp}
    nx.set_node_attributes(grp, positions, 'positions')
    return grp

def cis(x: float) -> complex:
    """Implements Euler's formula
    :math:`\\text{cis}(x) = e^{i \\pi x} = \\cos(x) + i \\sin(x)`"""
    return np.cos(x) + 1j * np.sin(x)

def circuit_to_pyquil(circuit: Circuit) -> pyquil.Program:
    """Convert a QuantumFlow circuit to a pyQuil program"""
    prog = pyquil.Program()
    for elem in circuit.elements:
        if isinstance(elem, Gate) and elem.name in QUIL_GATES:
            params = list(elem.params.values()) if elem.params else []
            prog.gate(elem.name, params, elem.qubits)
        elif isinstance(elem, Measure):
            prog.measure(elem.qubit, elem.cbit)
        else:
            raise ValueError('Cannot convert operation to pyquil')
    return prog

def pyquil_to_circuit(program: pyquil.Program) -> Circuit:
    """Convert a protoquil pyQuil program to a QuantumFlow Circuit"""
    circ = Circuit()
    for inst in program.instructions:
        if isinstance(inst, pyquil.Declare):
            continue
        if isinstance(inst, pyquil.Halt):
            continue
        if isinstance(inst, pyquil.Pragma):
            continue
        elif isinstance(inst, pyquil.Measurement):
            circ += Measure(inst.qubit.index)
        elif isinstance(inst, pyquil.Gate):
            defgate = STDGATES[inst.name]
            gate = defgate(*inst.params)
            qubits = [q.index for q in inst.qubits]
            gate = gate.relabel(qubits)
            circ += gate
        else:
            raise ValueError('PyQuil program is not protoquil')
    return circ

def quil_to_program(quil: str) -> Program:
    """Parse a quil program and return a Program object"""
    pyquil_instructions = pyquil.parser.parse(quil)
    return pyquil_to_program(pyquil_instructions)

def state_to_wavefunction(state: State) -> pyquil.Wavefunction:
    """Convert a QuantumFlow state to a pyQuil Wavefunction"""
    amplitudes = state.vec.asarray()
    amplitudes = amplitudes.transpose()
    amplitudes = amplitudes.reshape([amplitudes.size])
    return pyquil.Wavefunction(amplitudes)

def evaluate(tensor: BKTensor) -> TensorLike:
    """Return the value of a tensor"""
    if isinstance(tensor, _DTYPE):
        if torch.numel(tensor) == 1:
            return tensor.item()
        if tensor.numel() == 2:
            return tensor[0].cpu().numpy() + 1j * tensor[1].cpu().numpy()
        return tensor[0].cpu().numpy() + 1j * tensor[1].cpu().numpy()
    return tensor

def rank(tensor: BKTensor) -> int:
    """Return the number of dimensions of a tensor"""
    if isinstance(tensor, np.ndarray):
        return len(tensor.shape)
    return len(tensor[0].size())

def state_angle(ket0: State, ket1: State) -> bk.BKTensor:
    """The Fubini-Study angle between states.

    Equal to the Burrs angle for pure states."""
    return fubini_study_angle(ket0.vec, ket1.vec)

def states_close(state0: State, state1: State, tolerance: float=TOLERANCE) -> bool:
    """Returns True if states are almost identical.

    Closeness is measured with the metric Fubini-Study angle."""
    return vectors_close(state0.vec, state1.vec, tolerance)

def bures_angle(rho0: Density, rho1: Density) -> float:
    """Return the Bures angle between mixed quantum states

    Note: Bures angle cannot be calculated within the tensor backend."""
    return np.arccos(np.sqrt(fidelity(rho0, rho1)))

def inner_product(vec0: QubitVector, vec1: QubitVector) -> bk.BKTensor:
    """Hilbert-Schmidt inner product between qubit vectors

    The tensor rank and qubits must match."""
    if vec0.rank != vec1.rank or vec0.qubit_nb != vec1.qubit_nb:
        raise ValueError('Incompatibly vectors. Qubits and rank must match')
    vec1 = vec1.permute(vec0.qubits)
    return bk.inner(vec0.tensor, vec1.tensor)

def qubits_count_tuple(qubits: Union[int, Qubits]) -> Tuple[int, Qubits]:
    """Utility method for unraveling 'qubits: Union[int, Qubits]' arguments"""
    if isinstance(qubits, int):
        return (qubits, tuple(range(qubits)))
    return (len(qubits), qubits)

def fcast(value: float) -> TensorLike:
    """Cast to float tensor"""
    newvalue = tf.cast(value, FTYPE)
    if DEVICE == 'gpu':
        newvalue = newvalue.gpu()
    return newvalue

def count_operations(elements: Iterable[Operation]) -> Dict[Type[Operation], int]:
    """Return a count of different operation types given a colelction of
    operations, such as a Circuit or DAGCircuit"""
    op_count: Dict[Type[Operation], int] = defaultdict(int)
    for elem in elements:
        op_count[type(elem)] += 1
    return dict(op_count)

def join_channels(*channels: Channel) -> Channel:
    """Join two channels acting on different qubits into a single channel
    acting on all qubits"""
    vectors = [chan.vec for chan in channels]
    vec = reduce(outer_product, vectors)
    return Channel(vec.tensor, vec.qubits)

def _latex_format(obj: Any) -> str:
    """Format an object as a latex string."""
    if isinstance(obj, float):
        try:
            return sympy.latex(symbolize(obj))
        except ValueError:
            return '{0:.4g}'.format(obj)
    return str(obj)

def identity_gate(qubits: Union[int, Qubits]) -> Gate:
    """Returns the K-qubit identity gate"""
    _, qubits = qubits_count_tuple(qubits)
    return I(*qubits)

def join_gates(*gates: Gate) -> Gate:
    """Direct product of two gates. Qubit count is the sum of each gate's
    bit count."""
    vectors = [gate.vec for gate in gates]
    vec = reduce(outer_product, vectors)
    return Gate(vec.tensor, vec.qubits)

def almost_unitary(gate: Gate) -> bool:
    """Return true if gate tensor is (almost) unitary"""
    res = (gate @ gate.H).asoperator()
    N = gate.qubit_nb
    return np.allclose(asarray(res), np.eye(2 ** N), atol=TOLERANCE)

def almost_identity(gate: Gate) -> bool:
    """Return true if gate tensor is (almost) the identity"""
    N = gate.qubit_nb
    return np.allclose(asarray(gate.asoperator()), np.eye(2 ** N))

def almost_hermitian(gate: Gate) -> bool:
    """Return true if gate tensor is (almost) Hermitian"""
    return np.allclose(asarray(gate.asoperator()), asarray(gate.H.asoperator()))

def snapshot_folder():
    """Use the commit date in UTC as folder name"""
    logger.info('Snapshot folder')
    try:
        stdout = subprocess.check_output(['git', 'show', '-s', '--format=%cI', 'HEAD'])
    except subprocess.CalledProcessError as e:
        logger.error('Error: {}'.format(e.output.decode('ascii', 'ignore').strip()))
        sys.exit(2)
    except FileNotFoundError as e:
        logger.error('Error: {}'.format(e))
        sys.exit(2)
    ds = stdout.decode('ascii', 'ignore').strip()
    dt = datetime.fromisoformat(ds)
    utc = dt - dt.utcoffset()
    return utc.strftime('%Y%m%d_%H%M%S')

def decode_html_entities(s):
    """Replaces html entities with the character they represent.

        >>> print(decode_html_entities("&lt;3 &amp;"))
        <3 &"""
    parser = HTMLParser.HTMLParser()
    def unesc(m):
        return parser.unescape(m.group())
    return re.sub('(&[^;]+;)', unesc, ensure_unicode(s))

