            return False
        if i < 0:
            return False
    return True

def matrix_check(table):
    """Check input matrix format.

    :param table: input matrix
    :type table : dict
    :return: bool"""
    try:
        if len(table.keys()) == 0:
            return False
        for i in table.keys():
            if table.keys() != table[i].keys() or vector_check(list(table[i].values())) is False:
                return False
        return True
    except Exception:
        return False

def class_check(vector):
