def coords(obj):
    """Yields the coordinates from a Feature or Geometry.

    :param obj: A geometry or feature to extract the coordinates from.
    :type obj: Feature, Geometry
    :return: A generator with coordinate tuples from the geometry or feature.
    :rtype: generator"""
    if 'features' in obj:
        for f in obj['features']:
            for c in coords(f):
                yield c
    else:
        if isinstance(obj, (tuple, list)):
            coordinates = obj
        elif 'geometry' in obj:
            coordinates = obj['geometry']['coordinates']
        else:
            coordinates = obj.get('coordinates', obj)
        for e in coordinates:
            if isinstance(e, (float, int)):
                yield tuple(coordinates)
                break
            for f in coords(e):
                yield f

def map_tuples(func, obj):
    """Returns the mapped coordinates from a Geometry after applying the provided
    function to each coordinate.

    :param func: Function to apply to tuples
    :type func: function
    :param obj: A geometry or feature to extract the coordinates from.
    :type obj: Point, LineString, MultiPoint, MultiLineString, Polygon,
    MultiPolygon
    :return: The result of applying the function to each dimension in the
    array.
    :rtype: list
    :raises ValueError: if the provided object is not GeoJSON."""
    if obj['type'] == 'Point':
        coordinates = tuple(func(obj['coordinates']))
    elif obj['type'] in ['LineString', 'MultiPoint']:
        coordinates = [tuple(func(c)) for c in obj['coordinates']]
    elif obj['type'] in ['MultiLineString', 'Polygon']:
        coordinates = [[tuple(func(c)) for c in curve] for curve in obj['coordinates']]
    elif obj['type'] == 'MultiPolygon':
        coordinates = [[[tuple(func(c)) for c in curve] for curve in part] for part in obj['coordinates']]
    elif obj['type'] in ['Feature', 'FeatureCollection', 'GeometryCollection']:
        return map_geometries(lambda g: map_tuples(func, g), obj)
    else:
        raise ValueError('Invalid geometry object %s' % repr(obj))
    return {'type': obj['type'], 'coordinates': coordinates}

def map_geometries(func, obj):
    """Returns the result of passing every geometry in the given geojson object
    through func.

    :param func: Function to apply to tuples
    :type func: function
    :param obj: A geometry or feature to extract the coordinates from.
    :type obj: GeoJSON
    :return: The result of applying the function to each geometry
    :rtype: list
    :raises ValueError: if the provided object is not geojson."""
    simple_types = ['Point', 'LineString', 'MultiPoint', 'MultiLineString', 'Polygon', 'MultiPolygon']
    if obj['type'] in simple_types:
        return func(obj)
    elif obj['type'] == 'GeometryCollection':
        geoms = [func(geom) if geom else None for geom in obj['geometries']]
        return {'type': obj['type'], 'geometries': geoms}
    elif obj['type'] == 'Feature':
        geom = func(obj['geometry']) if obj['geometry'] else None
        return {'type': obj['type'], 'geometry': geom, 'properties': obj['properties']}
    elif obj['type'] == 'FeatureCollection':
        feats = [map_geometries(func, feat) for feat in obj['features']]
        return {'type': obj['type'], 'features': feats}
    else:
        raise ValueError('Invalid GeoJSON object %s' % repr(obj))

def _load_symbol(name):
    """Load a symbol by name.

    :param str name: The name to load, specified by `module.attr`.
    :returns: The attribute value. If the specified module does not contain
              the requested attribute then `None` is returned."""
    module_name, key = name.rsplit('.', 1)
    try:
        module = importlib.import_module(module_name)
    except ImportError as err:
        module_name, class_name = module_name.rsplit('.', 1)
        module = importlib.import_module(module_name)
        cls = getattr(module, class_name, None)
        if cls:
            attr = getattr(cls, key, None)
        else:
            raise err
    else:
        attr = getattr(module, key, None)
    if not callable(attr):
        raise ValueError('%s is not callable (was %r)' % (name, attr))
    return attr

def func_span(func, tags=None, require_active_trace=False):
    """Creates a new local span for execution of the given `func`.
    The returned span is best used as a context manager, e.g.

    .. code-block:: python

        with func_span('my_function'):
            return my_function(...)

    At this time the func should be a string name. In the future this code
    can be enhanced to accept a real function and derive its qualified name.

    :param func: name of the function or method
    :param tags: optional tags to add to the child span
    :param require_active_trace: controls what to do when there is no active
        trace. If require_active_trace=True, then no span is created.
        If require_active_trace=False, a new trace is started.
    :return: new child span, or a dummy context manager if there is no
        active/current parent span"""
    current_span = get_current_span()
    if current_span is None and require_active_trace:
        @contextlib2.contextmanager
        def empty_ctx_mgr():
            yield None
        return empty_ctx_mgr()
    operation_name = str(func)
    return utils.start_child_span(operation_name=operation_name, parent=current_span, tags=tags)

def before_request(request, tracer=None):
    """Attempts to extract a tracing span from incoming request.
    If no tracing context is passed in the headers, or the data
    cannot be parsed, a new root span is started.

    :param request: HTTP request with `.headers` property exposed
        that satisfies a regular dictionary interface
    :param tracer: optional tracer instance to use. If not specified
        the global opentracing.tracer will be used.
    :return: returns a new, already started span."""
    if tracer is None:
        tracer = opentracing.tracer
    tags_dict = {tags.SPAN_KIND: tags.SPAN_KIND_RPC_SERVER, tags.HTTP_URL: request.full_url}
    remote_ip = request.remote_ip
    if remote_ip:
        tags_dict[tags.PEER_HOST_IPV4] = remote_ip
    caller_name = request.caller_name
    if caller_name:
        tags_dict[tags.PEER_SERVICE] = caller_name
    remote_port = request.remote_port
    if remote_port:
        tags_dict[tags.PEER_PORT] = remote_port
    operation = request.operation
    try:
        carrier = {}
        for key, value in six.iteritems(request.headers):
            carrier[key] = value
        parent_ctx = tracer.extract(format=Format.HTTP_HEADERS, carrier=carrier)
    except Exception as e:
        logging.exception('trace extract failed: %s' % e)
        parent_ctx = None
    span = tracer.start_span(operation_name=operation, child_of=parent_ctx, tags=tags_dict)
    return span

def before_http_request(request, current_span_extractor):
    """A hook to be executed before HTTP request is executed.
    It returns a Span object that can be used as a context manager around
    the actual HTTP call implementation, or in case of async callback,
    it needs its `finish()` method to be called explicitly.

    :param request: request must match API defined by AbstractRequestWrapper
    :param current_span_extractor: function that extracts current span
        from some context
    :return: returns child tracing span encapsulating this request"""
    span = utils.start_child_span(operation_name=request.operation, parent=current_span_extractor())
    span.set_tag(tags.SPAN_KIND, tags.SPAN_KIND_RPC_CLIENT)
    span.set_tag(tags.HTTP_URL, request.full_url)
    service_name = request.service_name
    host, port = request.host_port
    if service_name:
        span.set_tag(tags.PEER_SERVICE, service_name)
    if host:
        span.set_tag(tags.PEER_HOST_IPV4, host)
    if port:
        span.set_tag(tags.PEER_PORT, port)
    for interceptor in ClientInterceptors.get_interceptors():
        interceptor.process(request=request, span=span)
    try:
        carrier = {}
        opentracing.tracer.inject(span_context=span.context, format=Format.HTTP_HEADERS, carrier=carrier)
        for key, value in six.iteritems(carrier):
            request.add_header(key, value)
    except opentracing.UnsupportedFormatException:
        pass
    return span

def quantile(image, q, nonzero=True):
    """Get the quantile values from an ANTsImage"""
    img_arr = image.numpy()
    if isinstance(q, (list, tuple)):
        q = [qq * 100.0 if qq <= 1.0 else qq for qq in q]
        if nonzero:
            img_arr = img_arr[img_arr > 0]
        vals = [np.percentile(img_arr, qq) for qq in q]
        return tuple(vals)
    elif isinstance(q, (float, int)):
        if q <= 1.0:
            q = q * 100.0
        if nonzero:
            img_arr = img_arr[img_arr > 0]
        return np.percentile(img_arr[img_arr > 0], q)
    else:
        raise ValueError('q argument must be list/tuple or float/int')

def _int_antsProcessArguments(args):
    """Needs to be better validated."""
    p_args = []
    if isinstance(args, dict):
        for argname, argval in args.items():
            if '-MULTINAME-' in argname:
                argname = argname[:argname.find('-MULTINAME-')]
            if argval is not None:
                if len(argname) > 1:
                    p_args.append('--%s' % argname)
                else:
                    p_args.append('-%s' % argname)
                if isinstance(argval, iio.ANTsImage):
                    p_args.append(_ptrstr(argval.pointer))
                elif isinstance(argval, list):
                    for av in argval:
                        if isinstance(av, iio.ANTsImage):
                            av = _ptrstr(av.pointer)
                        p_args.append(av)
                else:
                    p_args.append(str(argval))
    elif isinstance(args, list):
        for arg in args:
            if isinstance(arg, iio.ANTsImage):
                pointer_string = _ptrstr(arg.pointer)
                p_arg = pointer_string
            elif arg is None:
                pass
            else:
                p_arg = str(arg)
            p_args.append(p_arg)
    return p_args

def image_type_cast(image_list, pixeltype=None):
    """Cast a list of images to the highest pixeltype present in the list
    or all to a specified type

    ANTsR function: `antsImageTypeCast`

    Arguments
    ---------
    image_list : list/tuple
        images to cast

    pixeltype : string (optional)
        pixeltype to cast to. If None, images will be cast to the highest
        precision pixeltype found in image_list

    Returns
    -------
    list of ANTsImages
        given images casted to new type"""
    if not isinstance(image_list, (list, tuple)):
        raise ValueError('image_list must be list of ANTsImage types')
    pixtypes = []
    for img in image_list:
        pixtypes.append(img.pixeltype)
    if pixeltype is None:
        pixeltype = 'unsigned char'
        for p in pixtypes:
            if p == 'double':
                pixeltype = 'double'
            elif p == 'float' and pixeltype != 'double':
                pixeltype = 'float'
            elif p == 'unsigned int' and pixeltype != 'float' and (pixeltype != 'double'):
                pixeltype = 'unsigned int'
    out_images = []
    for img in image_list:
        if img.pixeltype == pixeltype:
            out_images.append(img)
        else:
            out_images.append(img.clone(pixeltype))
    return out_images

