def parse_date(string, force_datetime=False):
    """Takes a Xero formatted date, e.g. /Date(1426849200000+1300)/"""
    matches = DATE.match(string)
    if not matches:
        return None
    values = dict([(k, v if v[0] in '+-' else int(v)) for k, v in matches.groupdict().items() if v and int(v)])
    if 'timestamp' in values:
        value = datetime.datetime.utcfromtimestamp(0) + datetime.timedelta(hours=int(values.get('offset_h', 0)), minutes=int(values.get('offset_m', 0)), seconds=int(values['timestamp']) / 1000.0)
        return value
    if len(values) > 3 or force_datetime:
        return datetime.datetime(**values)
    if not values:
        return None
    return datetime.date(**values)

