def poll_for_exceptionless_callable(callable, attempts, interval):
    """Poll with a given callable for a specified number of times.

    :param callable: callable to invoke in loop -- if no exception is raised
                    the call is considered succeeded
    :param attempts: number of iterations to attempt
    :param interval: seconds to wait before next attempt"""
    @wraps(callable)
    def poll(*args, **kwargs):
        for attempt in range(attempts):
            try:
                return callable(*args, **kwargs)
            except Exception as ex:
                if attempt == attempts - 1:
                    raise MaximumAttemptsReached(ex)
                time.sleep(interval)
                continue
    return poll

def exit_cleanly(errnum=None):
    """exit_cleanly

    Exits the runtime cleanly using SystemExit.  This is the official, handling
    exception here as this is mostly meant to be a standalone script.
    """
    default = 'An Unknown Error has Occurred!'
    cases = {errno.EINVAL: 'Improper or invalid input value', errno.ESPIPE: 'Could not complete action due to a broken' + ' dependency', errno.ENOSYS: 'Could not complete action due to unexpected setup', errno.EIO: 'Could not access an expected file', errno.EPERM: 'Could not access an item due to permissions issues', -1: default}
    help_stmt = "\n%s [--opt [option]]\n    With opts:\n        working_directory - ONLY use this if you're overwriting `pwd`!\n    " % sys.argv[0]
    if not errnum:
        errnum = 0
    elif not isinstance(errnum, int) and hasattr(errno, errnum):
        errnum = getattr(errno, errnum)
    try:
        errnum = int(errnum)
    except TypeError:
        errnum = -1
    if errnum == 0:
        help_stmt = ''
        stmt = 'Successful in configuration!'
    elif errnum in cases:
        stmt = cases[errnum]
    else:
        stmt = default
    print('%s\n\n%s' % (stmt, help_stmt))

