def _find_from_file(full_doc, from_file_keyword):
    """Finds a line in <full_doc> like

        <from_file_keyword> <colon> <path>

    and return path"""
    path = None
    for line in full_doc.splitlines():
        if from_file_keyword in line:
            parts = line.strip().split(':')
            if len(parts) == 2 and parts[0].strip() == from_file_keyword:
                path = parts[1].strip()
                break
    return path

def _extract_definitions(alist, level=None):
    """Since we couldn't be bothered to register models elsewhere
    our definitions need to be extracted from the parameters.
    We require an 'id' field for the schema to be correctly
    added to the definitions list."""
    def _extract_array_defs(source):
        ret = []
        items = source.get('items')
        if items is not None and 'schema' in items:
            ret += _extract_definitions([items], level + 1)
        return ret
    if level is None:
        level = 0
    defs = list()
    if alist is not None:
        for item in alist:
            schema = item.get('schema')
            if schema is not None:
                schema_id = schema.get('id')
                if schema_id is not None:
                    defs.append(schema)
                    ref = {'$ref': '#/definitions/{}'.format(schema_id)}
                    if level == 0:
                        item['schema'] = ref
                    else:
                        item.update(ref)
                        del item['schema']
                properties = schema.get('properties')
                if properties is not None:
                    defs += _extract_definitions(properties.values(), level + 1)
                defs += _extract_array_defs(schema)
            defs += _extract_array_defs(item)
    return defs

def wave_infochunk(path):
    """Returns a bytearray of the WAVE RIFF header and fmt
    chunk for a `WAVEDescriptor` `Summary`"""
    with open(path, 'rb') as file:
        if file.read(4) != b'RIFF':
            return None
        data_size = file.read(4)
        if file.read(4) != b'WAVE':
            return None
        while True:
            chunkid = file.read(4)
            sizebuf = file.read(4)
            if len(sizebuf) < 4 or len(chunkid) < 4:
                return None
            size = struct.unpack(b'<L', sizebuf)[0]
            if chunkid[0:3] != b'fmt':
                if size % 2 == 1:
                    seek = size + 1
                else:
                    seek = size
                file.seek(size, 1)
            else:
                return bytearray(b'RIFF' + data_size + b'WAVE' + chunkid + sizebuf + file.read(size))

def add2set(self, pid, key, value):
    """low level add to StrongRefSetProperty"""
    prop = self.property_entries[pid]
    current = prop.objects.get(key, None)
    current_local_key = prop.references.get(key, None)
    if current and current is not value:
        current.detach()
    if current_local_key is None:
        prop.references[key] = prop.next_free_key
        prop.next_free_key += 1
    prop.objects[key] = value
    if prop.parent.dir:
        ref = prop.index_ref_name(key)
        dir_entry = prop.parent.dir.get(ref)
        if dir_entry is None:
            dir_entry = prop.parent.dir.makedir(ref)
        if value.dir != dir_entry:
            value.attach(dir_entry)
        prop.mark_modified()

