def better(old_value, new_value, mode):
    """Check if new value is better than the old value"""
    if (old_value is None or np.isnan(old_value)) and (new_value is not None and (not np.isnan(new_value))):
        return True
    if mode == 'min':
        return new_value < old_value
    elif mode == 'max':
        return new_value > old_value
    else:
        raise RuntimeError(f"Mode '{mode}' value is not supported")

def discount_bootstrap_gae(rewards_buffer, dones_buffer, values_buffer, final_values, discount_factor, gae_lambda, number_of_steps):
    """Calculate state values bootstrapping off the following state values - Generalized Advantage Estimation
    https://arxiv.org/abs/1506.02438"""
    advantage_buffer = torch.zeros_like(rewards_buffer)
    sum_accumulator = 0
    for i in reversed(range(number_of_steps)):
        if i == number_of_steps - 1:
            next_value = final_values
        else:
            next_value = values_buffer[i + 1]
        bellman_delta = rewards_buffer[i] + discount_factor * next_value * (1.0 - dones_buffer[i]) - values_buffer[i]
        advantage_buffer[i] = sum_accumulator = bellman_delta + discount_factor * gae_lambda * sum_accumulator * (1.0 - dones_buffer[i])
    return advantage_buffer

def env_maker(environment_id, seed, serial_id, monitor=False, allow_early_resets=False, normalize_observations=False, normalize_returns=False, normalize_gamma=0.99):
    """Create a relatively raw atari environment"""
    env = gym.make(environment_id)
    env.seed(seed + serial_id)
    if monitor:
        logdir = logger.get_dir() and os.path.join(logger.get_dir(), str(serial_id))
    else:
        logdir = None
    env = Monitor(env, logdir, allow_early_resets=allow_early_resets)
    if normalize_observations or normalize_returns:
        env = EnvNormalize(env, normalize_observations=normalize_observations, normalize_returns=normalize_returns, gamma=normalize_gamma)
    return env

def benchmark_method(f):
    """decorator to turn f into a factory of benchmarks"""
    @wraps(f)
    def inner(name, *args, **kwargs):
        return Benchmark(name, f, args, kwargs)
    return inner

def bench(participants=participants, benchmarks=benchmarks, bench_time=BENCH_TIME):
    """Do you even lift?"""
    mcs = [p.factory() for p in participants]
    means = [[] for p in participants]
    stddevs = [[] for p in participants]
    last_fn = None
    for benchmark_name, fn, args, kwargs in benchmarks:
        logger.info('')
        logger.info('%s', benchmark_name)
        for i, (participant, mc) in enumerate(zip(participants, mcs)):
            if 'get' in fn.__name__:
                last_fn(mc, *args, **kwargs)
            sw = Stopwatch()
            while sw.total() < bench_time:
                with sw.timing():
                    fn(mc, *args, **kwargs)
            means[i].append(sw.mean())
            stddevs[i].append(sw.stddev())
            logger.info(u'%76s: %s', participant.name, sw)
        last_fn = fn
    return (means, stddevs)

