def check_specs(specs, renamings, types):
    """Does nothing but raising PythranSyntaxError if specs
    are incompatible with the actual code"""
    from pythran.types.tog import unify, clone, tr
    from pythran.types.tog import Function, TypeVariable, InferenceError
    functions = {renamings.get(k, k): v for k, v in specs.functions.items()}
    for fname, signatures in functions.items():
        ftype = types[fname]
        for signature in signatures:
            sig_type = Function([tr(p) for p in signature], TypeVariable())
            try:
                unify(clone(sig_type), clone(ftype))
            except InferenceError:
                raise PythranSyntaxError('Specification for `{}` does not match inferred type:\nexpected `{}`\ngot `Callable[[{}], ...]`'.format(fname, ftype, ', '.join(map(str, sig_type.types[:-1]))))

def check_exports(mod, specs, renamings):
    """Does nothing but raising PythranSyntaxError if specs
    references an undefined global"""
    functions = {renamings.get(k, k): v for k, v in specs.functions.items()}
    mod_functions = {node.name: node for node in mod.body if isinstance(node, ast.FunctionDef)}
    for fname, signatures in functions.items():
        try:
            fnode = mod_functions[fname]
        except KeyError:
            raise PythranSyntaxError('Invalid spec: exporting undefined function `{}`'.format(fname))
        for signature in signatures:
            args_count = len(fnode.args.args)
            if len(signature) > args_count:
                raise PythranSyntaxError('Too many arguments when exporting `{}`'.format(fname))
            elif len(signature) < args_count - len(fnode.args.defaults):
                raise PythranSyntaxError('Not enough arguments when exporting `{}`'.format(fname))

def interleave(inter, f, seq):
    """Call f on each item in seq, calling inter() in between.
    """
    seq = iter(seq)
    try:
        f(next(seq))
    except StopIteration:
        pass
    else:
        for x in seq:
            inter()
            f(x)

def get_type(name, env, non_generic):
    """Get the type of identifier name from the type environment env.

    Args:
        name: The identifier name
        env: The type environment mapping from identifier names to types
        non_generic: A set of non-generic TypeVariables

    Raises:
        ParseError: Raised if name is an undefined symbol in the type
            environment."""
    if name in env:
        if isinstance(env[name], MultiType):
            return clone(env[name])
        return fresh(env[name], non_generic)
    else:
        print('W: Undefined symbol {0}'.format(name))
        return TypeVariable()

def fresh(t, non_generic):
    """Makes a copy of a type expression.

    The type t is copied. The generic variables are duplicated and the
    non_generic variables are shared.

    Args:
        t: A type to be copied.
        non_generic: A set of non-generic TypeVariables"""
    mappings = {}
    def freshrec(tp):
        p = prune(tp)
        if isinstance(p, TypeVariable):
            if is_generic(p, non_generic):
                if p not in mappings:
                    mappings[p] = TypeVariable()
                return mappings[p]
            else:
                return p
        elif isinstance(p, dict):
            return p
        elif isinstance(p, Collection):
            return Collection(*[freshrec(x) for x in p.types])
        elif isinstance(p, Scalar):
            return Scalar([freshrec(x) for x in p.types])
        elif isinstance(p, TypeOperator):
            return TypeOperator(p.name, [freshrec(x) for x in p.types])
        elif isinstance(p, MultiType):
            return MultiType([freshrec(x) for x in p.types])
        else:
            assert False, 'missing freshrec case {}'.format(type(p))
    return freshrec(t)

def save_function_effect(module):
    """Recursively save function effect for pythonic functions."""
    for intr in module.values():
        if isinstance(intr, dict):
            save_function_effect(intr)
        else:
            fe = FunctionEffects(intr)
            IntrinsicArgumentEffects[intr] = fe
            if isinstance(intr, intrinsic.Class):
                save_function_effect(intr.fields)

def pytype_to_deps_hpp(t):
    """python -> pythonic type hpp filename."""
    if isinstance(t, List):
        return {'list.hpp'}.union(pytype_to_deps_hpp(t.__args__[0]))
    elif isinstance(t, Set):
        return {'set.hpp'}.union(pytype_to_deps_hpp(t.__args__[0]))
    elif isinstance(t, Dict):
        tkey, tvalue = t.__args__
        return {'dict.hpp'}.union(pytype_to_deps_hpp(tkey), pytype_to_deps_hpp(tvalue))
    elif isinstance(t, Tuple):
        return {'tuple.hpp'}.union(*[pytype_to_deps_hpp(elt) for elt in t.__args__])
    elif isinstance(t, NDArray):
        out = {'ndarray.hpp'}
        if t.__args__[1].start == -1:
            out.add('numpy_texpr.hpp')
        return out.union(pytype_to_deps_hpp(t.__args__[0]))
    elif isinstance(t, Pointer):
        return {'pointer.hpp'}.union(pytype_to_deps_hpp(t.__args__[0]))
    elif isinstance(t, Fun):
        return {'cfun.hpp'}.union(*[pytype_to_deps_hpp(a) for a in t.__args__])
    elif t in PYTYPE_TO_CTYPE_TABLE:
        return {'{}.hpp'.format(t.__name__)}
    else:
        raise NotImplementedError('{0}:{1}'.format(type(t), t))

def run(xmin, ymin, xmax, ymax, step, range_, range_x, range_y, t):
    pt = numpy.zeros((range_x, range_y))
    'omp parallel for private(i,j,k,tmp)'
    for i in xrange(range_x):
        for j in xrange(range_y):
            xi, yj = (xmin + step * i, ymin + step * j)
            for k in xrange(t.shape[0]):
                tmp = 6368.0 * math.acos(math.cos(xi) * math.cos(t[k, 0]) * math.cos(yj - t[k, 1]) + math.sin(xi) * math.sin(t[k, 0]))
                if tmp < range_:
                    pt[i, j] += t[k, 2] / (1 + tmp)
    return pt

def _extract_specs_dependencies(specs):
    """Extract types dependencies from specs for each exported signature."""
    deps = set()
    for signatures in specs.functions.values():
        for signature in signatures:
            for t in signature:
                deps.update(pytype_to_deps(t))
    for signature in specs.capsules.values():
        for t in signature:
            deps.update(pytype_to_deps(t))
    return sorted(deps, key=lambda x: 'include' not in x)

def _parse_optimization(optimization):
    """Turns an optimization of the form
    my_optim
    my_package.my_optim
    into the associated symbol"""
    splitted = optimization.split('.')
    if len(splitted) == 1:
        splitted = ['pythran', 'optimizations'] + splitted
    return reduce(getattr, splitted[1:], __import__(splitted[0]))

def front_middle_end(module_name, code, optimizations=None, module_dir=None):
    """Front-end and middle-end compilation steps"""
    pm = PassManager(module_name, module_dir)
    ir, renamings, docstrings = frontend.parse(pm, code)
    if optimizations is None:
        optimizations = cfg.get('pythran', 'optimizations').split()
    optimizations = [_parse_optimization(opt) for opt in optimizations]
    refine(pm, ir, optimizations)
    return (pm, ir, renamings, docstrings)

def generate_py(module_name, code, optimizations=None, module_dir=None):
    """python + pythran spec -> py code

    Prints and returns the optimized python code."""
    pm, ir, _, _ = front_middle_end(module_name, code, optimizations, module_dir)
    return pm.dump(Python, ir)

def compile_cxxcode(module_name, cxxcode, output_binary=None, keep_temp=False, **kwargs):
    """c++ code (string) -> temporary file -> native module.
    Returns the generated .so."""
    fdpath = _write_temp(cxxcode, '.cpp')
    output_binary = compile_cxxfile(module_name, fdpath, output_binary, **kwargs)
    if not keep_temp:
        os.remove(fdpath)
    else:
        logger.warn('Keeping temporary generated file:' + fdpath)
    return output_binary

def pairwise(X):
    M = X.shape[0]
    N = X.shape[1]
    D = numpy.zeros((M, N))
    'omp parallel for private(i,j,d,k,tmp)'
    for i in xrange(M):
        for j in xrange(M):
            d = 0.0
            for k in xrange(N):
                tmp = X[i, k] - X[j, k]
                d += tmp * tmp
            D[i, j] = math.sqrt(d)
    return D

def matrix_multiply(m0, m1):
    new_matrix = numpy.zeros((m0.shape[0], m1.shape[1]))
    'omp parallel for private(i,j,k,r)'
    for i in xrange(m0.shape[0]):
        for j in xrange(m1.shape[1]):
            r = 0
            for k in xrange(m1.shape[0]):
                r += m0[i, k] * m1[k, j]
            new_matrix[i, j] = r
    return new_matrix

def fbcorr(imgs, filters):
    n_imgs, n_rows, n_cols, n_channels = imgs.shape
    n_filters, height, width, n_ch2 = filters.shape
    output = numpy.zeros((n_imgs, n_filters, n_rows - height + 1, n_cols - width + 1))
    'omp parallel for private(rr,cc,hh,ww,jj,ff,imgval, filterval)'
    for ii in xrange(n_imgs):
        for rr in xrange(n_rows - height + 1):
            for cc in xrange(n_cols - width + 1):
                for hh in xrange(height):
                    for ww in xrange(width):
                        for jj in xrange(n_channels):
                            for ff in xrange(n_filters):
                                imgval = imgs[ii, rr + hh, cc + ww, jj]
                                filterval = filters[ff, hh, ww, jj]
                                output[ii, ff, rr, cc] += imgval * filterval
    return output

def compile_flags(args):
    """Build a dictionnary with an entry for cppflags, ldflags, and cxxflags.

    These options are filled according to the command line defined options"""
    compiler_options = {'define_macros': args.defines, 'undef_macros': args.undefs, 'include_dirs': args.include_dirs, 'extra_compile_args': args.extra_flags, 'library_dirs': args.libraries_dir, 'extra_link_args': args.extra_flags}
    for param in ('opts',):
        val = getattr(args, param, None)
        if val:
            compiler_options[param] = val
    return compiler_options

def run(xmin, ymin, xmax, ymax, step, range_, range_x, range_y, t):
    X, Y = t.shape
    pt = np.zeros((X, Y))
    'omp parallel for'
    for i in range(X):
        for j in range(Y):
            for k in t:
                tmp = 6368.0 * np.arccos(np.cos(xmin + step * i) * np.cos(k[0]) * np.cos(ymin + step * j - k[1]) + np.sin(xmin + step * i) * np.sin(k[0]))
                if tmp < range_:
                    pt[i][j] += k[2] / (1 + tmp)
    return pt

def range_values(args):
    """Function used to compute returned range value of [x]range function."""
    if len(args) == 1:
        return Interval(0, args[0].high)
    elif len(args) == 2:
        return Interval(args[0].low, args[1].high)
    elif len(args) == 3:
        is_neg = args[2].low < 0
        is_pos = args[2].high > 0
        if is_neg and is_pos:
            return UNKNOWN_RANGE
        elif is_neg:
            return Interval(args[1].low, args[0].high)
        else:
            return Interval(args[0].low, args[1].high)

def max_values(args):
    """Return possible range for max function."""
    return Interval(max((x.low for x in args)), max((x.high for x in args)))

def min_values(args):
    """Return possible range for min function."""
    return Interval(min((x.low for x in args)), min((x.high for x in args)))

def calculate_u(dt, dx, dy, u, um, k):
    up = numpy.zeros((u.shape[0], u.shape[1]))
    'omp parallel for private(i,j)'
    for i in xrange(1, u.shape[0] - 1):
        for j in xrange(1, u.shape[1] - 1):
            up[i, j] = 2 * u[i, j] - um[i, j] + (dt / dx) ** 2 * (0.5 * (k[i + 1, j] + k[i, j]) * (u[i + 1, j] - u[i, j]) - 0.5 * (k[i, j] + k[i - 1, j]) * (u[i, j] - u[i - 1, j])) + (dt / dy) ** 2 * (0.5 * (k[i, j + 1] + k[i, j]) * (u[i, j + 1] - u[i, j]) - 0.5 * (k[i, j] + k[i, j - 1]) * (u[i, j] - u[i, j - 1]))
    return up

def save_arguments(module_name, elements):
    """Recursively save arguments name and default value."""
    for elem, signature in elements.items():
        if isinstance(signature, dict):
            save_arguments(module_name + (elem,), signature)
        else:
            try:
                themodule = __import__('.'.join(module_name))
                obj = getattr(themodule, elem)
                spec = getfullargspec(obj)
                if signature.args.args:
                    logger.warn('Overriding pythran description with argspec information for: {}'.format('.'.join(module_name + (elem,))))
                args = [ast.Name(arg, ast.Param(), None) for arg in spec.args]
                defaults = list(spec.defaults or [])
                if sys.version_info.major == 3:
                    args += [ast.Name(arg, ast.Param(), None) for arg in spec.kwonlyargs]
                    defaults += [spec.kwonlydefaults[kw] for kw in spec.kwonlyargs]
                signature.args.args = args[:-len(defaults)]
                signature.args.defaults = []
                for arg, value in zip(args[-len(defaults):], defaults):
                    signature.args.defaults.append(to_ast(value))
                    signature.args.args.append(arg)
            except (AttributeError, ImportError, TypeError, ToNotEval):
                pass

def fill_constants_types(module_name, elements):
    """Recursively save arguments name and default value."""
    for elem, intrinsic in elements.items():
        if isinstance(intrinsic, dict):
            fill_constants_types(module_name + (elem,), intrinsic)
        elif isinstance(intrinsic, ConstantIntr):
            cst = getattr(__import__('.'.join(module_name)), elem)
            intrinsic.signature = type(cst)

def save_method(elements, module_path):
    """Recursively save methods with module name and signature."""
    for elem, signature in elements.items():
        if isinstance(signature, dict):
            save_method(signature, module_path + (elem,))
        elif isinstance(signature, Class):
            save_method(signature.fields, module_path + (elem,))
        elif signature.ismethod():
            if elem in methods and module_path[0] != '__dispatch__':
                assert elem in MODULES['__dispatch__']
                path = ('__dispatch__',)
                methods[elem] = (path, MODULES['__dispatch__'][elem])
            else:
                methods[elem] = (module_path, signature)

def save_function(elements, module_path):
    """Recursively save functions with module name and signature."""
    for elem, signature in elements.items():
        if isinstance(signature, dict):
            save_function(signature, module_path + (elem,))
        elif signature.isstaticfunction():
            functions.setdefault(elem, []).append((module_path, signature))
        elif isinstance(signature, Class):
            save_function(signature.fields, module_path + (elem,))

def save_attribute(elements, module_path):
    """Recursively save attributes with module name and signature."""
    for elem, signature in elements.items():
        if isinstance(signature, dict):
            save_attribute(signature, module_path + (elem,))
        elif signature.isattribute():
            assert elem not in attributes
            attributes[elem] = (module_path, signature)
        elif isinstance(signature, Class):
            save_attribute(signature.fields, module_path + (elem,))

def size_container_folding(value):
    """Convert value to ast expression if size is not too big.

    Converter for sized container."""
    if len(value) < MAX_LEN:
        if isinstance(value, list):
            return ast.List([to_ast(elt) for elt in value], ast.Load())
        elif isinstance(value, tuple):
            return ast.Tuple([to_ast(elt) for elt in value], ast.Load())
        elif isinstance(value, set):
            return ast.Set([to_ast(elt) for elt in value])
        elif isinstance(value, dict):
            keys = [to_ast(elt) for elt in value.keys()]
            values = [to_ast(elt) for elt in value.values()]
            return ast.Dict(keys, values)
        elif isinstance(value, np.ndarray):
            return ast.Call(func=ast.Attribute(ast.Name(mangle('numpy'), ast.Load(), None), 'array', ast.Load()), args=[to_ast(totuple(value.tolist())), ast.Attribute(ast.Name(mangle('numpy'), ast.Load(), None), value.dtype.name, ast.Load())], keywords=[])
        else:
            raise ConversionError()
    else:
        raise ToNotEval()

def builtin_folding(value):
    """Convert builtin function to ast expression."""
    if isinstance(value, (type(None), bool)):
        name = str(value)
    elif value.__name__ in ('bool', 'float', 'int'):
        name = value.__name__ + '_'
    else:
        name = value.__name__
    return ast.Attribute(ast.Name('__builtin__', ast.Load(), None), name, ast.Load())

def to_ast(value):
    """Turn a value into ast expression.

    >>> a = 1
    >>> print(ast.dump(to_ast(a)))
    Num(n=1)
    >>> a = [1, 2, 3]
    >>> print(ast.dump(to_ast(a)))
    List(elts=[Num(n=1), Num(n=2), Num(n=3)], ctx=Load())"""
    if isinstance(value, (type(None), bool)):
        return builtin_folding(value)
    if sys.version_info[0] == 2 and isinstance(value, long):
        from pythran.syntax import PythranSyntaxError
        raise PythranSyntaxError('constant folding results in big int')
    if any((value is t for t in (bool, int, float))):
        iinfo = np.iinfo(int)
        if isinstance(value, int) and (not iinfo.min <= value <= iinfo.max):
            from pythran.syntax import PythranSyntaxError
            raise PythranSyntaxError('constant folding results in big int')
        return builtin_folding(value)
    elif isinstance(value, np.generic):
        return to_ast(np.asscalar(value))
    elif isinstance(value, numbers.Number):
        return ast.Num(value)
    elif isinstance(value, str):
        return ast.Str(value)
    elif isinstance(value, (list, tuple, set, dict, np.ndarray)):
        return size_container_folding(value)
    elif hasattr(value, '__module__') and value.__module__ == '__builtin__':
        return builtin_folding(value)
    elif sys.version_info.major == 3:
        if isinstance(value, (filter, map, zip)):
            return to_ast(list(value))
    raise ToNotEval()

def run(xmin, ymin, xmax, ymax, step, range_, range_x, range_y, t):
    pt = zeros((range_x, range_y, 3))
    'omp parallel for private(i,j,k,tmp)'
    for i in xrange(range_x):
        for j in xrange(range_y):
            pt[i, j, 0], pt[i, j, 1] = ((xmin + step * i) * 180 / math.pi, (ymin + step * j) * 180 / math.pi)
            for k in xrange(t.shape[0]):
                tmp = 6368.0 * math.acos(math.cos(xmin + step * i) * math.cos(t[k, 0]) * math.cos(ymin + step * j - t[k, 1]) + math.sin(xmin + step * i) * math.sin(t[k, 0]))
                if tmp < range_:
                    pt[i, j, 2] += t[k, 2] / (1 + tmp)
    return pt

def attr_to_path(node):
    """Compute path and final object for an attribute node"""
    def get_intrinsic_path(modules, attr):
        """Get function path and intrinsic from an ast.Attribute."""
        if isinstance(attr, ast.Name):
            return (modules[demangle(attr.id)], (demangle(attr.id),))
        elif isinstance(attr, ast.Attribute):
            module, path = get_intrinsic_path(modules, attr.value)
            return (module[attr.attr], path + (attr.attr,))
    obj, path = get_intrinsic_path(MODULES, node)
    if not obj.isliteral():
        path = path[:-1] + ('functor', path[-1])
    return (obj, ('pythonic',) + path)

def save_intrinsic_alias(module):
    """Recursively save default aliases for pythonic functions."""
    for v in module.values():
        if isinstance(v, dict):
            save_intrinsic_alias(v)
        else:
            IntrinsicAliases[v] = frozenset((v,))
            if isinstance(v, Class):
                save_intrinsic_alias(v.fields)

def assert_angle(name, q):
    """Check that ``q`` is an angular `~astropy.units.Quantity`."""
    if isinstance(q, u.Quantity):
        if q.unit.physical_type == 'angle':
            pass
        else:
            raise ValueError('{0} should have angular units'.format(name))
    else:
        raise TypeError('{0} should be a Quantity instance'.format(name))

def sdot(U, V):
    """Computes the tensorproduct reducing last dimensoin of U with first dimension of V.
    For matrices, it is equal to regular matrix product."""
    nu = U.ndim
    return np.tensordot(U, V, axes=(nu - 1, 0))

def deprecated(func):
    """This is a decorator which can be used to mark functions
    as deprecated. It will result in a warning being emitted
    when the function is used."""
    import warnings
    @functools.wraps(func)
    def new_func(*args, **kwargs):
        if is_python_3:
            code = func.__code__
        else:
            code = func.func_code
        warnings.warn_explicit('Call to deprecated function {}.'.format(func.__name__), category=Warning, filename=code.co_filename, lineno=code.co_firstlineno + 1)
        return func(*args, **kwargs)
    return new_func

def def_variables(s):
    """blabla"""
    frame = inspect.currentframe().f_back
    try:
        if isinstance(s, str):
            s = re.split('\\s|,', s)
        res = []
        for t in s:
            if not t:
                continue
            if t.count('@') > 0:
                sym = IndexedSymbol(t, Variable)
                t = t.strip('@')
            else:
                sym = Variable(t)
            frame.f_globals[t] = sym
            res.append(sym)
        if frame.f_globals.get('variables_order'):
            frame.f_globals['variables_order'].extend(res)
        else:
            frame.f_globals['variables_order'] = res
        return res
    finally:
        del frame

def clear_all():
    """Clears all parameters, variables, and shocks defined previously"""
    frame = inspect.currentframe().f_back
    try:
        if frame.f_globals.get('variables_order'):
            del frame.f_globals['variables_order']
        if frame.f_globals.get('parameters_order'):
            del frame.f_globals['parameters_order']
    finally:
        del frame

def ast_to_sympy(expr):
    """Converts an AST expression to a sympy expression (STUPID)"""
    from dolang import to_source
    s = to_source(expr)
    not_to_be_treated_as_functions = ['alpha', 'beta', 'gamma', 'zeta', 'Chi']
    d = {v: sympy.Symbol(v) for v in not_to_be_treated_as_functions}
    return sympy.sympify(s, locals=d)

def non_decreasing_series(n, size):
    """Lists all combinations of 0,...,n-1 in increasing order"""
    if size == 1:
        return [[a] for a in range(n)]
    else:
        lc = non_decreasing_series(n, size - 1)
        ll = []
        for l in lc:
            last = l[-1]
            for i in range(last, n):
                e = l + [i]
                ll.append(e)
        return ll

def groot(path=''):
    """Changes current directory to the root of the project (looks for README.md)."""
    def check_filelist(l):
        if 'README.md' in l or 'README' in l:
            return True
        else:
            return False
    import os, copy
    cwd = os.getcwd()
    cwd0 = copy.copy(cwd)
    cwd_init = copy.copy(cwd)
    found = False
    sysroot = False
    while not found and (not sysroot):
        found = check_filelist(os.listdir())
        if not found:
            os.chdir(os.path.join(cwd, os.pardir))
            cwd = os.getcwd()
            if cwd == cwd0:
                sysroot = True
            else:
                cwd0 = cwd
        else:
            os.chdir(os.path.join(cwd0, path))
    if sysroot:
        os.chdir(cwd_init)
        raise Exception('Root directory not found.')

def _filter_file(src, dest, subst):
    """Copy src to dest doing substitutions on the fly.
    """
    substre = re.compile('\\$(%s)' % '|'.join(subst.keys()))
    def repl(m):
        return subst[m.group(1)]
    with open(src, 'rt') as sf, open(dest, 'wt') as df:
        while True:
            l = sf.readline()
            if not l:
                break
            df.write(re.sub(substre, repl, l))

def _create_non_null_wrapper(name, t):
    """creates type wrapper for non-null of given type"""
    def __new__(cls, json_data, selection_list=None):
        if json_data is None:
            raise ValueError(name + ' received null value')
        return t(json_data, selection_list)
    def __to_graphql_input__(value, indent=0, indent_string='  '):
        return t.__to_graphql_input__(value, indent, indent_string)
    return type(name, (t,), {'__new__': __new__, '_%s__auto_register' % name: False, '__to_graphql_input__': __to_graphql_input__})

def _create_list_of_wrapper(name, t):
    """creates type wrapper for list of given type"""
    def __new__(cls, json_data, selection_list=None):
        if json_data is None:
            return None
        return [t(v, selection_list) for v in json_data]
    def __to_graphql_input__(value, indent=0, indent_string='  '):
        r = []
        for v in value:
            r.append(t.__to_graphql_input__(v, indent, indent_string))
        return '[' + ', '.join(r) + ']'
    def __to_json_value__(value):
        if value is None:
            return None
        return [t.__to_json_value__(v) for v in value]
    return type(name, (t,), {'__new__': __new__, '_%s__auto_register' % name: False, '__to_graphql_input__': __to_graphql_input__, '__to_json_value__': __to_json_value__})

def add_query_to_url(url, extra_query):
    """Adds an extra query to URL, returning the new URL.

    Extra query may be a dict or a list as returned by
    :func:`urllib.parse.parse_qsl()` and :func:`urllib.parse.parse_qs()`."""
    split = urllib.parse.urlsplit(url)
    merged_query = urllib.parse.parse_qsl(split.query)
    if isinstance(extra_query, dict):
        for k, v in extra_query.items():
            if not isinstance(v, (tuple, list)):
                merged_query.append((k, v))
            else:
                for cv in v:
                    merged_query.append((k, cv))
    else:
        merged_query.extend(extra_query)
    merged_split = urllib.parse.SplitResult(split.scheme, split.netloc, split.path, urllib.parse.urlencode(merged_query), split.fragment)
    return merged_split.geturl()

def psit(t, x, xf):
    """A function of t, X_t and X_{t+1} (f=future)"""
    if t == 0:
        return psi0(x) + psit(1, x, xf)
    else:
        return -0.5 / sigma0 ** 2 + 0.5 / sigma0 ** 4 * (xf - mu0 - phi0 * (x - mu0)) ** 2

def log_sum_exp_ab(a, b):
    """log_sum_exp for two scalars.

    Parameters
    ----------
    a, b: float

    Returns
    -------
    c: float
        c = log(e^a + e^b)"""
    if a > b:
        return a + np.log(1.0 + np.exp(b - a))
    else:
        return b + np.log(1.0 + np.exp(a - b))

def resampling_scheme(func):
    """Decorator for resampling schemes."""
    @functools.wraps(func)
    def modif_func(W, M=None):
        M = W.shape[0] if M is None else M
        return func(W, M)
    rs_funcs[func.__name__] = modif_func
    modif_func.__doc__ = rs_doc % func.__name__.capitalize()
    return modif_func

def distinct_seeds(k):
    """returns k distinct seeds for random number generation
    """
    seeds = []
    for _ in range(k):
        while True:
            s = random.randint(2 ** 32 - 1)
            if s not in seeds:
                break
        seeds.append(s)
    return seeds

def psit(t, xp, x):
    """score of the model (gradient of log-likelihood at theta=theta_0)
    """
    if t == 0:
        return -0.5 / sigma0 ** 2 + 0.5 * (1.0 - phi0 ** 2) / sigma0 ** 4 * (x - mu0) ** 2
    else:
        return -0.5 / sigma0 ** 2 + 0.5 / sigma0 ** 4 * (x - mu0 - phi0 * (xp - mu0)) ** 2

def parse_date(string):
    """Return a timestamp for the provided datestring, described by RFC 7231."""
    parsed = email.utils.parsedate_tz(string)
    if parsed is None:
        raise ValueError('Invalid time.')
    parsed = list(parsed)
    parsed[9] = 0 if parsed[9] is None else parsed[9]
    return email.utils.mktime_tz(parsed)

def add_behave_arguments(parser):
    """Additional command line arguments extracted directly from behave"""
    conflicts = ['--no-color', '--version', '-c', '-k', '-v', '-S', '--simple']
    parser.add_argument('paths', action='store', nargs='*', help='Feature directory, file or file location (FILE:LINE).')
    for fixed, keywords in behave_options:
