def load_registered_fixtures(context):
    """Apply fixtures that are registered with the @fixtures decorator."""
    runner = context._runner
    step_registry = getattr(runner, 'step_registry', None)
    if not step_registry:
        step_registry = module_step_registry.registry
    for step in context.scenario.all_steps:
        match = step_registry.find_match(step)
        if match and hasattr(match.func, 'registered_fixtures'):
            if not context.test.fixtures:
                context.test.fixtures = []
            context.test.fixtures.extend(match.func.registered_fixtures)

def monkey_patch_behave(django_test_runner):
    """Integrate behave_django in behave via before/after scenario hooks"""
    behave_run_hook = ModelRunner.run_hook
    def run_hook(self, name, context, *args):
        if name == 'before_all':
            django_test_runner.patch_context(context)
        behave_run_hook(self, name, context, *args)
        if name == 'before_scenario':
            django_test_runner.setup_testclass(context)
            django_test_runner.setup_fixtures(context)
            django_test_runner.setup_test(context)
            behave_run_hook(self, 'django_ready', context)
        if name == 'after_scenario':
            django_test_runner.teardown_test(context)
    ModelRunner.run_hook = run_hook

def identify_denonavr_receivers():
    """Identify DenonAVR using SSDP and SCPD queries.

    Returns a list of dictionaries which includes all discovered Denon AVR
    devices with keys "host", "modelName", "friendlyName", "presentationURL"."""
    devices = send_ssdp_broadcast()
    receivers = []
    for device in devices:
        try:
            receiver = evaluate_scpd_xml(device['URL'])
        except ConnectionError:
            continue
        if receiver:
            receivers.append(receiver)
    return receivers

def send_ssdp_broadcast():
    """Send SSDP broadcast message to discover UPnP devices.

    Returns a list of dictionaries with "address" (IP, PORT) and "URL"
    of SCPD XML for all discovered devices."""
    for i, ssdp_query in enumerate(SSDP_QUERIES):
        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM, socket.IPPROTO_UDP)
        sock.settimeout(2)
        sock.sendto(ssdp_query.encode(), (SSDP_ADDR, SSDP_PORT))
        res = []
        try:
            while True:
                res.append(sock.recvfrom(10240))
        except socket.timeout:
            sock.close()
        if res:
            _LOGGER.debug('Got results after %s SSDP queries', i + 1)
            sock.close()
            break
    devices = {}
    device = {}
    for entry in res:
        device['address'] = entry[1]
        en_decoded = entry[0].decode('utf-8')
        try:
            device['URL'] = en_decoded[en_decoded.lower().index('location:') + 10:en_decoded.index('\r\n', en_decoded.lower().index('location:'))]
        except ValueError:
            continue
        devices[device['address']] = device.copy()
    _LOGGER.debug('Following devices found: %s', list(devices.values()))
    return list(devices.values())

def parse_auto_sub(text):
    """Parses webvtt and returns timestamps for words and lines
    Tested on automatically generated subtitles from YouTube"""
    pat = '<(\\d\\d:\\d\\d:\\d\\d(\\.\\d+)?)>'
    out = []
    lines = []
    data = text.split('\n')
    data = [d for d in data if re.search('\\d\\d:\\d\\d:\\d\\d', d) is not None]
    for i, d in enumerate(data):
        if re.search(pat, d):
            lines.append((data[i - 1], d))
    if len(lines) > 0:
        out = parse_cued(lines)
    else:
        out = parse_uncued(text)
    return out

def get_ngrams(inputfile, n=1, use_transcript=False, use_vtt=False):
    """Get ngrams from a text
    Sourced from:
    https://gist.github.com/dannguyen/93c2c43f4e65328b85af"""
    words = []
    if use_transcript:
        for s in audiogrep.convert_timestamps(inputfile):
            for w in s['words']:
                words.append(w[0])
    elif use_vtt:
        vtts = get_vtt_files(inputfile)
        for vtt in vtts:
            with open(vtt['vtt'], 'r') as infile:
                sentences = parse_auto_sub(infile.read())
            for s in sentences:
                for w in s['words']:
                    words.append(w['word'])
    else:
        text = ''
        srts = get_subtitle_files(inputfile)
        for srt in srts:
            lines = clean_srt(srt)
            if lines:
                for timespan in lines.keys():
                    line = lines[timespan].strip()
                    text += line + ' '
        words = re.split('[.?!,:\\"]+\\s*|\\s+', text)
    ngrams = zip(*[words[i:] for i in range(n)])
    return ngrams

def convert_timespan(timespan):
    """Convert an srt timespan into a start and end timestamp."""
    start, end = timespan.split('-->')
    start = convert_timestamp(start)
    end = convert_timestamp(end)
    return (start, end)

