def search_line(line, search, searchtype):
    """Return True if search term is found in given line, False otherwise."""
    if searchtype == 're' or searchtype == 'word':
        return re.search(search, line)
    elif searchtype == 'pos':
        return searcher.search_out(line, search)
    elif searchtype == 'hyper':
        return searcher.hypernym_search(line, search)

def get_subtitle_files(inputfile):
    """Return a list of subtitle files."""
    srts = []
    for f in inputfile:
        filename = f.split('.')
        filename[-1] = 'srt'
        srt = '.'.join(filename)
        if os.path.isfile(srt):
            srts.append(srt)
    if len(srts) == 0:
        print('[!] No subtitle files were found.')
        return False
    return srts

def compose_from_transcript(files, search, searchtype):
    """Takes transcripts created by audiogrep/pocketsphinx, a search and search type
    and returns a list of timestamps for creating a supercut"""
    final_segments = []
    if searchtype in ['re', 'word', 'franken', 'fragment']:
        if searchtype == 're':
            searchtype = 'sentence'
        segments = audiogrep.search(search, files, mode=searchtype, regex=True)
        for seg in segments:
            seg['file'] = seg['file'].replace('.transcription.txt', '')
            seg['line'] = seg['words']
            final_segments.append(seg)
    elif searchtype in ['hyper', 'pos']:
        for s in audiogrep.convert_timestamps(files):
            for w in s['words']:
                if search_line(w[0], search, searchtype):
                    seg = {'file': s['file'].replace('.transcription.txt', ''), 'line': w[0], 'start': float(w[1]), 'end': float(w[2])}
                    final_segments.append(seg)
    return final_segments

def basic_color(code):
    """16 colors supported"""
    def inner(text, rl=False):
        """Every raw_input with color sequences should be called with
        rl=True to avoid readline messed up the length calculation"""
        c = code
        if rl:
            return '\x01\x1b[%sm\x02%s\x01\x1b[0m\x02' % (c, text)
        else:
            return '\x1b[%sm%s\x1b[0m' % (c, text)
    return inner

def term_color(code):
    """256 colors supported"""
    def inner(text, rl=False):
        """Every raw_input with color sequences should be called with
        rl=True to avoid readline messed up the length calculation"""
        c = code
        if rl:
            return '\x01\x1b[38;5;%sm\x02%s\x01\x1b[0m\x02' % (c, text)
        else:
            return '\x1b[38;5;%sm%s\x1b[0m' % (c, text)
    return inner

def color_func(func_name):
    """Call color function base on name"""
    if str(func_name).isdigit():
        return term_color(int(func_name))
    return globals()[func_name]

def get_extract_value_function(column_identifier):
    """returns a function that extracts the value for a column."""
    def extract_value(run_result):
        pos = None
        for i, column in enumerate(run_result.columns):
            if column.title == column_identifier:
                pos = i
                break
        if pos is None:
            sys.exit('CPU time missing for task {0}.'.format(run_result.task_id[0]))
        return Util.to_decimal(run_result.values[pos])
    return extract_value

def get_memory_banks_per_run(coreAssignment, cgroups):
    """Get an assignment of memory banks to runs that fits to the given coreAssignment,
    i.e., no run is allowed to use memory that is not local (on the same NUMA node)
    to one of its CPU cores."""
    try:
        allMems = set(cgroups.read_allowed_memory_banks())
        result = []
        for cores in coreAssignment:
            mems = set()
            for core in cores:
                coreDir = '/sys/devices/system/cpu/cpu{0}/'.format(core)
                mems.update(_get_memory_banks_listed_in_dir(coreDir))
            allowedMems = sorted(mems.intersection(allMems))
            logging.debug('Memory banks for cores %s are %s, of which we can use %s.', cores, list(mems), allowedMems)
            result.append(allowedMems)
        assert len(result) == len(coreAssignment)
        if any(result) and os.path.isdir('/sys/devices/system/node/'):
            return result
        else:
            return None
    except ValueError as e:
        sys.exit('Could not read memory information from kernel: {0}'.format(e))

def add_container_output_args(argument_parser):
    """Define command-line arguments for output of a container (result files).
    @param argument_parser: an argparse parser instance"""
    argument_parser.add_argument('--output-directory', metavar='DIR', default='output.files', help="target directory for result files (default: './output.files')")
    argument_parser.add_argument('--result-files', metavar='PATTERN', action='append', default=[], help="pattern for specifying which result files should be copied to the output directory (default: '.')")

def handle_container_output_args(options, parser):
    """Handle the options specified by add_container_output_args().
    @return: a dict that can be used as kwargs for the ContainerExecutor.execute_run()"""
    if options.result_files:
        result_files_patterns = [os.path.normpath(p) for p in options.result_files if p]
        for pattern in result_files_patterns:
            if pattern.startswith('..'):
                parser.error("Invalid relative result-files pattern '{}'.".format(pattern))
    else:
        result_files_patterns = ['.']
    output_dir = options.output_directory
    if os.path.exists(output_dir) and (not os.path.isdir(output_dir)):
        parser.error("Output directory '{}' must not refer to an existing file.".format(output_dir))
    return {'output_dir': output_dir, 'result_files_patterns': result_files_patterns}

def parse_table_definition_file(file):
    """Read an parse the XML of a table-definition file.
    @return: an ElementTree object for the table definition"""
    logging.info("Reading table definition from '%s'...", file)
    if not os.path.isfile(file):
        logging.error("File '%s' does not exist.", file)
        exit(1)
    try:
        tableGenFile = ElementTree.ElementTree().parse(file)
    except IOError as e:
        logging.error('Could not read result file %s: %s', file, e)
        exit(1)
    except ElementTree.ParseError as e:
        logging.error('Table file %s is invalid: %s', file, e)
        exit(1)
    if 'table' != tableGenFile.tag:
        logging.error("Table file %s is invalid: It's root element is not named 'table'.", file)
        exit(1)
    return tableGenFile

def load_results_from_table_definition(table_definition, table_definition_file, options):
    """Load all results in files that are listed in the given table-definition file.
    @return: a list of RunSetResult objects"""
    default_columns = extract_columns_from_table_definition_file(table_definition, table_definition_file)
    columns_relevant_for_diff = _get_columns_relevant_for_diff(default_columns)
    results = []
    for tag in table_definition:
        if tag.tag == 'result':
            columns = extract_columns_from_table_definition_file(tag, table_definition_file) or default_columns
            run_set_id = tag.get('id')
            for resultsFile in get_file_list_from_result_tag(tag, table_definition_file):
                results.append(parallel.submit(load_result, resultsFile, options, run_set_id, columns, columns_relevant_for_diff))
        elif tag.tag == 'union':
            results.append(parallel.submit(handle_union_tag, tag, table_definition_file, options, default_columns, columns_relevant_for_diff))
    return [future.result() for future in results]

def load_results_with_table_definition(result_files, table_definition, table_definition_file, options):
    """Load results from given files with column definitions taken from a table-definition file.
    @return: a list of RunSetResult objects"""
    columns = extract_columns_from_table_definition_file(table_definition, table_definition_file)
    columns_relevant_for_diff = _get_columns_relevant_for_diff(columns)
    return load_results(result_files, options=options, columns=columns, columns_relevant_for_diff=columns_relevant_for_diff)

def extract_columns_from_table_definition_file(xmltag, table_definition_file):
    """Extract all columns mentioned in the result tag of a table definition file."""
    def handle_path(path):
        """Convert path from a path relative to table-definition file."""
        if not path or path.startswith('http://') or path.startswith('https://'):
            return path
        return os.path.join(os.path.dirname(table_definition_file), path)
    columns = list()
    for c in xmltag.findall('column'):
        scale_factor = c.get('scaleFactor')
        display_unit = c.get('displayUnit')
        source_unit = c.get('sourceUnit')
        new_column = Column(c.get('title'), c.text, c.get('numberOfDigits'), handle_path(c.get('href')), None, display_unit, source_unit, scale_factor, c.get('relevantForDiff'), c.get('displayTitle'))
        columns.append(new_column)
    return columns

def _get_columns_relevant_for_diff(columns_to_show):
    """Extract columns that are relevant for the diff table.

    @param columns_to_show: (list) A list of columns that should be shown
    @return: (set) Set of columns that are relevant for the diff table. If
             none is marked relevant, the column named "status" will be
             returned in the set."""
    cols = set([col.title for col in columns_to_show if col.relevant_for_diff])
    if len(cols) == 0:
        return set([col.title for col in columns_to_show if col.title == 'status'])
    else:
        return cols

def get_task_id(task, base_path_or_url):
    """Return a unique identifier for a given task.
    @param task: the XML element that represents a task
    @return a tuple with filename of task as first element"""
    name = task.get('name')
    if base_path_or_url:
        if Util.is_url(base_path_or_url):
            name = urllib.parse.urljoin(base_path_or_url, name)
        else:
            name = os.path.normpath(os.path.join(os.path.dirname(base_path_or_url), name))
    task_id = [name, task.get('properties'), task.get('runset')]
    return tuple(task_id)

def load_tool(result):
    """Load the module with the tool-specific code."""
    def load_tool_module(tool_module):
        if not tool_module:
            logging.warning('Cannot extract values from log files for benchmark results %s (missing attribute "toolmodule" on tag "result").', Util.prettylist(result.attributes['name']))
            return None
        try:
            logging.debug('Loading %s', tool_module)
            return __import__(tool_module, fromlist=['Tool']).Tool()
        except ImportError as ie:
            logging.warning('Missing module "%s", cannot extract values from log files (ImportError: %s).', tool_module, ie)
        except AttributeError:
            logging.warning('The module "%s" does not define the necessary class Tool, cannot extract values from log files.', tool_module)
        return None
    tool_module = result.attributes['toolmodule'][0] if 'toolmodule' in result.attributes else None
    if tool_module in loaded_tools:
        return loaded_tools[tool_module]
    else:
        result = load_tool_module(tool_module)
        loaded_tools[tool_module] = result
        return result

def load_results(result_files, options, run_set_id=None, columns=None, columns_relevant_for_diff=set()):
    """Version of load_result for multiple input files that will be loaded concurrently."""
    return parallel.map(load_result, result_files, itertools.repeat(options), itertools.repeat(run_set_id), itertools.repeat(columns), itertools.repeat(columns_relevant_for_diff))

def load_result(result_file, options, run_set_id=None, columns=None, columns_relevant_for_diff=set()):
    """Completely handle loading a single result file.
    @param result_file the file to parse
    @param options additional options
    @param run_set_id the identifier of the run set
    @param columns the list of columns
    @param columns_relevant_for_diff a set of columns that is relevant for
                                     the diff table
    @return a fully ready RunSetResult instance or None"""
    xml = parse_results_file(result_file, run_set_id=run_set_id, ignore_errors=options.ignore_errors)
    if xml is None:
        return None
    result = RunSetResult.create_from_xml(result_file, xml, columns=columns, all_columns=options.all_columns, columns_relevant_for_diff=columns_relevant_for_diff)
    result.collect_data(options.correct_only)
    return result

def merge_tasks(runset_results):
    """This function merges the results of all RunSetResult objects.
    If necessary, it can merge lists of names: [A,C] + [A,B] --> [A,B,C]
    and add dummy elements to the results.
    It also ensures the same order of tasks."""
    task_list = []
    task_set = set()
    for runset in runset_results:
        index = -1
        currentresult_taskset = set()
        for task in runset.get_tasks():
            if task in currentresult_taskset:
                logging.warning("Task '%s' is present twice, skipping it.", task[0])
            else:
                currentresult_taskset.add(task)
                if task not in task_set:
                    task_list.insert(index + 1, task)
                    task_set.add(task)
                    index += 1
                else:
                    index = task_list.index(task)
    merge_task_lists(runset_results, task_list)

def merge_task_lists(runset_results, tasks):
    """Set the filelists of all RunSetResult elements so that they contain the same files
    in the same order. For missing files a dummy element is inserted."""
    for runset in runset_results:
        dic = dict([(run_result.task_id, run_result) for run_result in reversed(runset.results)])
        runset.results = []
        for task in tasks:
            run_result = dic.get(task)
            if run_result is None:
                logging.info("    No result for task '%s' in '%s'.", task[0], Util.prettylist(runset.attributes['filename']))
                run_result = RunResult(task, None, result.CATEGORY_MISSING, None, None, runset.columns, [None] * len(runset.columns))
            runset.results.append(run_result)

def get_rows(runSetResults):
    """Create list of rows with all data. Each row consists of several RunResults."""
    rows = []
    for task_results in zip(*[runset.results for runset in runSetResults]):
        rows.append(Row(task_results))
    return rows

def select_relevant_id_columns(rows):
    """Find out which of the entries in Row.id are equal for all given rows.
    @return: A list of True/False values according to whether the i-th part of the id is always equal."""
    relevant_id_columns = [True]
    if rows:
        prototype_id = rows[0].id
        for column in range(1, len(prototype_id)):
            def id_equal_to_prototype(row):
                return row.id[column] == prototype_id[column]
            relevant_id_columns.append(not all(map(id_equal_to_prototype, rows)))
    return relevant_id_columns

def get_stats_of_rows(rows):
    """Calculcate number of true/false tasks and maximum achievable score."""
    count_true = count_false = max_score = 0
    for row in rows:
        if not row.properties:
            logging.info('Missing property for %s.', row.filename)
            continue
        if len(row.properties) > 1:
            count_true = count_false = max_score = 0
            break
        expected_result = row.expected_results.get(row.properties[0].name)
        if not expected_result:
            continue
        if expected_result.result is True:
            count_true += 1
        elif expected_result.result is False:
            count_false += 1
        for prop in row.properties:
            max_score += prop.max_score(expected_result)
    return (max_score, count_true, count_false)

def get_regression_count(rows, ignoreFlappingTimeouts):
    """Count the number of regressions, i.e., differences in status of the two right-most results
    where the new one is not "better" than the old one.
    Any change in status between error, unknown, and wrong result is a regression.
    Different kind of errors or wrong results are also a regression."""
    def status_is(run_result, status):
        return run_result.status and run_result.status.startswith(status)
    def any_status_is(run_results, status):
        for run_result in run_results:
            if status_is(run_result, status):
                return True
        return False
    regressions = 0
    for row in rows:
        if len(row.results) < 2:
            return 0
        new = row.results[-1]
        old = row.results[-2]
        if new.category == result.CATEGORY_CORRECT:
            continue
        if new.status == old.status:
            continue
        if status_is(new, 'TIMEOUT') and status_is(old, 'TIMEOUT'):
            continue
        if status_is(new, 'OUT OF MEMORY') and status_is(old, 'OUT OF MEMORY'):
            continue
        if ignoreFlappingTimeouts and status_is(new, 'TIMEOUT') and any_status_is(row.results[:-2], 'TIMEOUT'):
            continue
        regressions += 1
    return regressions

def _get_user_account_info(user):
    """Get the user account info from the passwd database. Only works on Linux.
    @param user The name of a user account or a numeric uid prefixed with '#'
    @return a tuple that corresponds to the members of the passwd structure
    @raise KeyError: If user account is unknown
    @raise ValueError: If uid is not a valid number"""
    import pwd
    if user[0] == '#':
        return pwd.getpwuid(int(user[1:]))
    else:
        return pwd.getpwnam(user)

def _try_join_cancelled_thread(thread):
    """Join a thread, but if the thread doesn't terminate for some time, ignore it
    instead of waiting infinitely."""
    thread.join(10)
    if thread.is_alive():
        logging.warning('Thread %s did not terminate within grace period after cancellation', thread.name)

def main(argv=None):
    """A simple command-line interface for the cgroups check of BenchExec."""
    if argv is None:
        argv = sys.argv
    parser = argparse.ArgumentParser(fromfile_prefix_chars='@', description='Check whether cgroups are available and can be used for BenchExec.\n           Part of BenchExec: https://github.com/sosy-lab/benchexec/')
    parser.add_argument('--wait', type=int, default=1, metavar='SECONDS', help='wait some time to ensure no process interferes with cgroups in the meantime (default: 1s)')
    parser.add_argument('--no-thread', action='store_true', help='run check on the main thread instead of a separate thread' + '(behavior of cgrulesengd differs depending on this)')
    options = parser.parse_args(argv[1:])
    if options.no_thread:
        check_cgroup_availability(options.wait)
    else:
        check_cgroup_availability_in_thread(options)

def is_code(filename):
    """This function returns True, if  a line of the file contains bracket '{'."""
    with open(filename, 'r') as file:
        for line in file:
            if not is_comment(line) and '{' in line:
                if '${' not in line:
                    return True
    return False

def get_list_from_xml(elem, tag='option', attributes=['name']):
    """This function searches for all "option"-tags and returns a list with all attributes and texts."""
    return flatten(([option.get(attr) for attr in attributes] + [option.text] for option in elem.findall(tag)), exclude=[None])

def get_single_child_from_xml(elem, tag):
    """Get a single child tag from an XML element.
    Similar to "elem.find(tag)", but warns if there are multiple child tags with the given name."""
    children = elem.findall(tag)
    if not children:
        return None
    if len(children) > 1:
        logging.warning('Tag "%s" has more than one child tags with name "%s" in input file, ignoring all but the first.', elem.tag, tag)
    return children[0]

def parse_int_list(s):
    """Parse a comma-separated list of strings.
    The list may additionally contain ranges such as "1-5",
    which will be expanded into "1,2,3,4,5"."""
    result = []
    for item in s.split(','):
        item = item.strip().split('-')
        if len(item) == 1:
            result.append(int(item[0]))
        elif len(item) == 2:
            start, end = item
            result.extend(range(int(start), int(end) + 1))
        else:
            raise ValueError("invalid range: '{0}'".format(s))
    return result

def split_number_and_unit(s):
    """Parse a string that consists of a integer number and an optional unit.
    @param s a non-empty string that starts with an int and is followed by some letters
    @return a triple of the number (as int) and the unit"""
    if not s:
        raise ValueError('empty value')
    s = s.strip()
    pos = len(s)
    while pos and (not s[pos - 1].isdigit()):
        pos -= 1
    number = int(s[:pos])
    unit = s[pos:].strip()
    return (number, unit)

def parse_memory_value(s):
    """Parse a string that contains a number of bytes, optionally with a unit like MB.
    @return the number of bytes encoded by the string"""
    number, unit = split_number_and_unit(s)
    if not unit or unit == 'B':
        return number
    elif unit == 'kB':
        return number * _BYTE_FACTOR
    elif unit == 'MB':
        return number * _BYTE_FACTOR * _BYTE_FACTOR
    elif unit == 'GB':
        return number * _BYTE_FACTOR * _BYTE_FACTOR * _BYTE_FACTOR
    elif unit == 'TB':
        return number * _BYTE_FACTOR * _BYTE_FACTOR * _BYTE_FACTOR * _BYTE_FACTOR
    else:
        raise ValueError('unknown unit: {} (allowed are B, kB, MB, GB, and TB)'.format(unit))

def parse_timespan_value(s):
    """Parse a string that contains a time span, optionally with a unit like s.
    @return the number of seconds encoded by the string"""
    number, unit = split_number_and_unit(s)
    if not unit or unit == 's':
        return number
    elif unit == 'min':
        return number * 60
    elif unit == 'h':
        return number * 60 * 60
    elif unit == 'd':
        return number * 24 * 60 * 60
    else:
        raise ValueError('unknown unit: {} (allowed are s, min, h, and d)'.format(unit))

def expand_filename_pattern(pattern, base_dir):
    """Expand a file name pattern containing wildcards, environment variables etc.

    @param pattern: The pattern string to expand.
    @param base_dir: The directory where relative paths are based on.
    @return: A list of file names (possibly empty)."""
    pattern = os.path.normpath(os.path.join(base_dir, pattern))
    pattern = os.path.expandvars(os.path.expanduser(pattern))
    fileList = glob.glob(pattern)
    return fileList

def substitute_vars(template, replacements):
    """Replace certain keys with respective values in a string.
    @param template: the string in which replacements should be made
    @param replacements: a dict or a list of pairs of keys and values"""
    result = template
    for key, value in replacements:
        result = result.replace('${' + key + '}', value)
    if '${' in result:
        logging.warning("A variable was not replaced in '%s'.", result)
    return result

def log_rmtree_error(func, arg, exc_info):
    """Suited as onerror handler for (sh)util.rmtree() that logs a warning."""
    logging.warning("Failure during '%s(%s)': %s", func.__name__, arg, exc_info[1])

def rmtree(path, ignore_errors=False, onerror=None):
    """Same as shutil.rmtree, but supports directories without write or execute permissions."""
    if ignore_errors:
        def onerror(*args):
            pass
    elif onerror is None:
        def onerror(*args):
            raise
    for root, dirs, unused_files in os.walk(path):
        for directory in dirs:
            try:
                abs_directory = os.path.join(root, directory)
                os.chmod(abs_directory, stat.S_IRWXU)
            except EnvironmentError as e:
                onerror(os.chmod, abs_directory, e)
    shutil.rmtree(path, ignore_errors=ignore_errors, onerror=onerror)

def copy_all_lines_from_to(inputFile, outputFile):
    """Copy all lines from an input file object to an output file object."""
    currentLine = inputFile.readline()
    while currentLine:
        outputFile.write(currentLine)
        currentLine = inputFile.readline()

def write_file(content, *path):
    """Simply write some content to a file, overriding the file if necessary."""
    with open(os.path.join(*path), 'w') as file:
        return file.write(content)

def read_file(*path):
    """Read the full content of a file."""
    with open(os.path.join(*path)) as f:
        return f.read().strip()

def read_key_value_pairs_from_file(*path):
    """Read key value pairs from a file (each pair on a separate line).
    Key and value are separated by ' ' as often used by the kernel.
    @return a generator of tuples"""
    with open(os.path.join(*path)) as f:
        for line in f:
            yield line.split(' ', 1)

def is_turbo_boost_enabled():
    """Check whether Turbo Boost (scaling CPU frequency beyond nominal frequency)
    is active on this system.
    @return: A bool, or None if Turbo Boost is not supported."""
    try:
        if os.path.exists(_TURBO_BOOST_FILE):
            boost_enabled = int(util.read_file(_TURBO_BOOST_FILE))
            if not 0 <= boost_enabled <= 1:
                raise ValueError('Invalid value {} for turbo boost activation'.format(boost_enabled))
            return boost_enabled != 0
        if os.path.exists(_TURBO_BOOST_FILE_PSTATE):
            boost_disabled = int(util.read_file(_TURBO_BOOST_FILE_PSTATE))
            if not 0 <= boost_disabled <= 1:
                raise ValueError('Invalid value {} for turbo boost activation'.format(boost_enabled))
            return boost_disabled != 1
    except ValueError as e:
        sys.exit('Could not read turbo-boost information from kernel: {0}'.format(e))

def handle_basic_executor_options(options, parser):
    """Handle the options specified by add_basic_executor_options()."""
    logLevel = logging.INFO
    if options.debug:
        logLevel = logging.DEBUG
    elif options.quiet:
        logLevel = logging.WARNING
    util.setup_logging(level=logLevel)

def xml_to_string(elem, qualified_name=None, public_id=None, system_id=None):
    """Return a pretty-printed XML string for the Element.
    Also allows setting a document type."""
    from xml.dom import minidom
    rough_string = ET.tostring(elem, 'utf-8')
    reparsed = minidom.parseString(rough_string)
    if qualified_name:
        doctype = minidom.DOMImplementation().createDocumentType(qualified_name, public_id, system_id)
        reparsed.insertBefore(doctype, reparsed.documentElement)
    return reparsed.toprettyxml(indent='  ')

def load_task_definition_file(task_def_file):
    """Open and parse a task-definition file in YAML format."""
    try:
        with open(task_def_file) as f:
            task_def = yaml.safe_load(f)
    except OSError as e:
        raise BenchExecException('Cannot open task-definition file: ' + str(e))
    except yaml.YAMLError as e:
        raise BenchExecException('Invalid task definition: ' + str(e))
    if str(task_def.get('format_version')) not in ['0.1', '1.0']:
        raise BenchExecException("Task-definition file {} specifies invalid format_version '{}'.".format(task_def_file, task_def.get('format_version')))
    return task_def

def load_tool_info(tool_name):
    """Load the tool-info class.
    @param tool_name: The name of the tool-info module.
    Either a full Python package name or a name within the benchexec.tools package.
    @return: A tuple of the full name of the used tool-info module and an instance of the tool-info class."""
    tool_module = tool_name if '.' in tool_name else 'benchexec.tools.' + tool_name
    try:
        tool = __import__(tool_module, fromlist=['Tool']).Tool()
    except ImportError as ie:
        sys.exit('Unsupported tool "{0}" specified. ImportError: {1}'.format(tool_name, ie))
    except AttributeError:
        sys.exit('The module "{0}" does not define the necessary class "Tool", it cannot be used as tool info for BenchExec.'.format(tool_module))
    return (tool_module, tool)

def expected_results_of_file(filename):
    """Create a dict of property->ExpectedResult from information encoded in a filename."""
    results = {}
    for filename_part, (expected_result, for_properties) in _FILE_RESULTS.items():
        if filename_part in filename:
            expected_result_class = get_result_classification(expected_result)
            assert expected_result_class in {RESULT_CLASS_TRUE, RESULT_CLASS_FALSE}
            expected_result = expected_result_class == RESULT_CLASS_TRUE
            subproperty = None
            if len(for_properties) > 1:
                assert for_properties == _MEMSAFETY_SUBPROPERTIES and expected_result
                property = _PROP_MEMSAFETY
            else:
                property = next(iter(for_properties))
                if property in _MEMSAFETY_SUBPROPERTIES and (not expected_result):
                    subproperty = property
                    property = _PROP_MEMSAFETY
            if property in results:
                raise BenchExecException('Duplicate property {} in filename {}'.format(property, filename))
            results[property] = ExpectedResult(expected_result, subproperty)
    return results

def _svcomp_score(category, result):
    """Return the achieved score of a task according to the SV-COMP scoring scheme.
    @param category: result category as determined by get_result_category
    @param result: the result given by the tool"""
    assert result is not None
    result_class = get_result_classification(result)
    if category == CATEGORY_CORRECT_UNCONFIRMED:
        if result_class == RESULT_CLASS_TRUE:
            return _SCORE_CORRECT_UNCONFIRMED_TRUE
        elif result_class == RESULT_CLASS_FALSE:
            return _SCORE_CORRECT_UNCONFIRMED_FALSE
        else:
            assert False
    elif category == CATEGORY_CORRECT:
        if result_class == RESULT_CLASS_TRUE:
            return _SCORE_CORRECT_TRUE
        elif result_class == RESULT_CLASS_FALSE:
            return _SCORE_CORRECT_FALSE
        else:
            assert False, result
    elif category == CATEGORY_WRONG:
        if result_class == RESULT_CLASS_TRUE:
            return _SCORE_WRONG_TRUE
        elif result_class == RESULT_CLASS_FALSE:
            return _SCORE_WRONG_FALSE
        else:
            assert False
    else:
        return _SCORE_UNKNOWN

def score_for_task(properties, category, result):
    """Return the possible score of task, depending on whether the result is correct or not."""
    assert result is not None
    if properties and Property.create_from_names(properties).is_svcomp:
        return _svcomp_score(category, result)
    return None

def get_result_classification(result):
    """Classify the given result into "true" (property holds),
    "false" (property does not hold), "unknown", and "error".
    @param result: The result given by the tool (needs to be one of the RESULT_* strings to be recognized).
    @return One of RESULT_CLASS_* strings"""
    if result not in RESULT_LIST:
        if result and result.startswith(RESULT_FALSE_PROP + '(') and result.endswith(')'):
            return RESULT_CLASS_FALSE
        return RESULT_CLASS_OTHER
    if result == RESULT_TRUE_PROP or result == RESULT_SAT:
        return RESULT_CLASS_TRUE
    else:
        return RESULT_CLASS_FALSE

def get_file_list(shortFile):
    """The function get_file_list expands a short filename to a sorted list
    of filenames. The short filename can contain variables and wildcards."""
    if '://' in shortFile:
        return [shortFile]
    expandedFile = os.path.expandvars(os.path.expanduser(shortFile))
    fileList = glob.glob(expandedFile)
    if len(fileList) != 0:
        fileList.sort()
    else:
        logging.warning("No file matches '%s'.", shortFile)
    return fileList

def open_url_seekable(path_url, mode='rt'):
    """Open a URL and ensure that the result is seekable,
    copying it into a buffer if necessary."""
    logging.debug("Making request to '%s'", path_url)
    response = urllib.request.urlopen(path_url)
    logging.debug('Got response %s', response.info())
    try:
        response.seek(0)
    except (IOError, AttributeError):
        response = io.BytesIO(response.read())
    if 'b' in mode:
        return response
    else:
        return io.TextIOWrapper(response)

def split_string_at_suffix(s, numbers_into_suffix=False):
    """Split a string into two parts: a prefix and a suffix. Splitting is done from the end,
    so the split is done around the position of the last digit in the string
    (that means the prefix may include any character, mixing digits and chars).
    The flag 'numbers_into_suffix' determines whether the suffix consists of digits or non-digits."""
    if not s:
        return (s, '')
    pos = len(s)
    while pos and numbers_into_suffix == s[pos - 1].isdigit():
        pos -= 1
    return (s[:pos], s[pos:])

def format_options(options):
    """Helper function for formatting the content of the options line"""
    lines = ['']
    for token in re.split('( -|\\[\\[|\\]\\])', options):
        if token in ['[[', ']]']:
            lines.append(token)
            lines.append('')
        elif token == ' -':
            lines.append(token)
        else:
            lines[-1] += token
    return '<span style="display:block">' + '</span><span style="display:block">'.join((line for line in lines if line.strip())) + '</span>'

def prettylist(list_):
    """Filter out duplicate values while keeping order."""
    if not list_:
        return ''
    values = set()
    uniqueList = []
    for entry in list_:
        if not entry in values:
            values.add(entry)
            uniqueList.append(entry)
    return uniqueList[0] if len(uniqueList) == 1 else '[' + '; '.join(uniqueList) + ']'

def get_column_type(column, column_values):
    """Returns the type of the given column based on its row values on the given RunSetResult.
    @param column: the column to return the correct ColumnType for
    @param column_values: the column values to consider
    @return: a tuple of a type object describing the column - the concrete ColumnType is stored in the attribute 'type',
        the display unit of the column, which may be None,
        the source unit of the column, which may be None,
        and the scale factor to convert from the source unit to the display unit.
        If no scaling is necessary for conversion, this value is 1."""
    try:
        return _get_column_type_heur(column, column_values)
    except util.TableDefinitionError as e:
        logging.error("Column type couldn't be determined: {}".format(e.message))
        return (ColumnType.text, None, None, 1)

def find_my_cgroups(cgroup_paths=None):
    """Return a Cgroup object with the cgroups of the current process.
    Note that it is not guaranteed that all subsystems are available
    in the returned object, as a subsystem may not be mounted.
    Check with "subsystem in <instance>" before using.
    A subsystem may also be present but we do not have the rights to create
    child cgroups, this can be checked with require_subsystem().
    @param cgroup_paths: If given, use this instead of reading /proc/self/cgroup."""
    logging.debug('Analyzing /proc/mounts and /proc/self/cgroup for determining cgroups.')
    if cgroup_paths is None:
        my_cgroups = dict(_find_own_cgroups())
    else:
        my_cgroups = dict(_parse_proc_pid_cgroup(cgroup_paths))
    cgroupsParents = {}
    for subsystem, mount in _find_cgroup_mounts():
        if os.access(mount, os.F_OK):
            cgroupPath = os.path.join(mount, my_cgroups[subsystem])
            if not os.access(cgroupPath, os.W_OK) and os.access(os.path.join(cgroupPath, CGROUP_FALLBACK_PATH), os.W_OK):
                cgroupPath = os.path.join(cgroupPath, CGROUP_FALLBACK_PATH)
            cgroupsParents[subsystem] = cgroupPath
    return Cgroup(cgroupsParents)

def _find_cgroup_mounts():
    """Return the information which subsystems are mounted where.
    @return a generator of tuples (subsystem, mountpoint)"""
    try:
        with open('/proc/mounts', 'rt') as mountsFile:
            for mount in mountsFile:
                mount = mount.split(' ')
                if mount[2] == 'cgroup':
                    mountpoint = mount[1]
                    options = mount[3]
                    for option in options.split(','):
                        if option in ALL_KNOWN_SUBSYSTEMS:
                            yield (option, mountpoint)
    except IOError:
        logging.exception('Cannot read /proc/mounts')

def _find_own_cgroups():
    """For all subsystems, return the information in which (sub-)cgroup this process is in.
    (Each process is in exactly cgroup in each hierarchy.)
    @return a generator of tuples (subsystem, cgroup)"""
    try:
        with open('/proc/self/cgroup', 'rt') as ownCgroupsFile:
            for cgroup in _parse_proc_pid_cgroup(ownCgroupsFile):
                yield cgroup
    except IOError:
        logging.exception('Cannot read /proc/self/cgroup')

def _parse_proc_pid_cgroup(content):
    """Parse a /proc/*/cgroup file into tuples of (subsystem,cgroup).
    @param content: An iterable over the lines of the file.
    @return: a generator of tuples"""
    for ownCgroup in content:
        ownCgroup = ownCgroup.strip().split(':')
        try:
            path = ownCgroup[2][1:]
        except IndexError:
            raise IndexError('index out of range for ' + str(ownCgroup))
        for subsystem in ownCgroup[1].split(','):
            yield (subsystem, path)

def _register_process_with_cgrulesengd(pid):
    """Tell cgrulesengd daemon to not move the given process into other cgroups,
    if libcgroup is available."""
    from ctypes import cdll
    try:
        libcgroup = cdll.LoadLibrary('libcgroup.so.1')
        failure = libcgroup.cgroup_init()
        if failure:
            pass
        else:
            CGROUP_DAEMON_UNCHANGE_CHILDREN = 1
            failure = libcgroup.cgroup_register_unchanged_process(pid, CGROUP_DAEMON_UNCHANGE_CHILDREN)
            if failure:
                pass
    except OSError:
        pass

def parse_time_arg(s):
    """Parse a time stamp in the "year-month-day hour-minute" format."""
    try:
        return time.strptime(s, '%Y-%m-%d %H:%M')
    except ValueError as e:
        raise argparse.ArgumentTypeError(e)

def main(benchexec=None, argv=None):
    """The main method of BenchExec for use in a command-line script.
    In addition to calling benchexec.start(argv),
    it also handles signals and keyboard interrupts.
    It does not return but calls sys.exit().
    @param benchexec: An instance of BenchExec for executing benchmarks.
    @param argv: optionally the list of command-line options to use"""
    if sys.version_info < (3,):
        sys.exit('benchexec needs Python 3 to run.')
    signal.signal(signal.SIGTERM, signal_handler_ignore)
    try:
        if not benchexec:
            benchexec = BenchExec()
        sys.exit(benchexec.start(argv or sys.argv))
    except BenchExecException as e:
        sys.exit('Error: ' + str(e))
    except KeyboardInterrupt:
        benchexec.stop()
        util.printOut('\n\nScript was interrupted by user, some runs may not be done.')

def allocate_stack(size=DEFAULT_STACK_SIZE):
    """Allocate some memory that can be used as a stack.
    @return: a ctypes void pointer to the *top* of the stack."""
    base = libc.mmap(None, size + GUARD_PAGE_SIZE, libc.PROT_READ | libc.PROT_WRITE, libc.MAP_PRIVATE | libc.MAP_ANONYMOUS | libc.MAP_GROWSDOWN | libc.MAP_STACK, -1, 0)
    try:
        libc.mprotect(base, GUARD_PAGE_SIZE, libc.PROT_NONE)
        yield ctypes.c_void_p(base + size + GUARD_PAGE_SIZE)
    finally:
        libc.munmap(base, size + GUARD_PAGE_SIZE)

def execute_in_namespace(func, use_network_ns=True):
    """Execute a function in a child process in separate namespaces.
    @param func: a parameter-less function returning an int (which will be the process' exit value)
    @return: the PID of the created child process"""
    flags = signal.SIGCHLD | libc.CLONE_NEWNS | libc.CLONE_NEWUTS | libc.CLONE_NEWIPC | libc.CLONE_NEWUSER | libc.CLONE_NEWPID
    if use_network_ns:
        flags |= libc.CLONE_NEWNET
    def child_func():
        ctypes.pythonapi.PyOS_AfterFork()
        return func()
    with allocate_stack() as stack:
        pid = libc.clone(ctypes.CFUNCTYPE(ctypes.c_int)(child_func), stack, flags, None)
    return pid

def setup_user_mapping(pid, uid=os.getuid(), gid=os.getgid()):
    """Write uid_map and gid_map in /proc to create a user mapping
    that maps our user from outside the container to the same user inside the container
    (and no other users are mapped).
    @see: http://man7.org/linux/man-pages/man7/user_namespaces.7.html
    @param pid: The PID of the process in the container."""
    proc_child = os.path.join('/proc', str(pid))
    try:
        uid_map = '{0} {1} 1'.format(uid, os.getuid())
        util.write_file(uid_map, proc_child, 'uid_map')
    except IOError as e:
        logging.warning('Creating UID mapping into container failed: %s', e)
    try:
        util.write_file('deny', proc_child, 'setgroups')
    except IOError as e:
        if e.errno != errno.ENOENT:
            logging.warning('Could not write to setgroups file in /proc: %s', e)
    try:
        gid_map = '{0} {1} 1'.format(gid, os.getgid())
        util.write_file(gid_map, proc_child, 'gid_map')
    except IOError as e:
        logging.warning('Creating GID mapping into container failed: %s', e)

def get_mount_points():
    """Get all current mount points of the system.
    Changes to the mount points during iteration may be reflected in the result.
    @return a generator of (source, target, fstype, options),
    where options is a list of bytes instances, and the others are bytes instances
    (this avoids encoding problems with mount points with problematic characters)."""
    def decode_path(path):
        return path.replace(b'\\011', b'\t').replace(b'\\040', b' ').replace(b'\\012', b'\n').replace(b'\\134', b'\\')
    with open('/proc/self/mounts', 'rb') as mounts:
        for mount in mounts:
            source, target, fstype, options, unused1, unused2 = mount.split(b' ')
            options = set(options.split(b','))
            yield (decode_path(source), decode_path(target), fstype, options)

def remount_with_additional_flags(mountpoint, existing_options, mountflags):
    """Remount an existing mount point with additional flags.
    @param mountpoint: the mount point as bytes
    @param existing_options: dict with current mount existing_options as bytes
    @param mountflags: int with additional mount existing_options (cf. libc.MS_* constants)"""
    mountflags |= libc.MS_REMOUNT | libc.MS_BIND
    for option, flag in libc.MOUNT_FLAGS.items():
        if option in existing_options:
            mountflags |= flag
    libc.mount(None, mountpoint, None, mountflags, None)

def make_bind_mount(source, target, recursive=False, private=False, read_only=False):
    """Make a bind mount.
    @param source: the source directory as bytes
    @param target: the target directory as bytes
    @param recursive: whether to also recursively bind mount all mounts below source
    @param private: whether to mark the bind as private, i.e., changes to the existing mounts
        won't propagate and vice-versa (changes to files/dirs will still be visible)."""
    flags = libc.MS_BIND
    if recursive:
        flags |= libc.MS_REC
    if private:
        flags |= libc.MS_PRIVATE
    if read_only:
        flags |= libc.MS_RDONLY
    libc.mount(source, target, None, flags, None)

def drop_capabilities(keep=[]):
    """Drop all capabilities this process has.
    @param keep: list of capabilities to not drop"""
    capdata = (libc.CapData * 2)()
    for cap in keep:
        capdata[0].effective |= 1 << cap
        capdata[0].permitted |= 1 << cap
    libc.capset(ctypes.byref(libc.CapHeader(version=libc.LINUX_CAPABILITY_VERSION_3, pid=0)), ctypes.byref(capdata))

def forward_all_signals_async(target_pid, process_name):
    """Install all signal handler that forwards all signals to the given process."""
    def forwarding_signal_handler(signum):
        _forward_signal(signum, process_name, forwarding_signal_handler.target_pid)
    forwarding_signal_handler.target_pid = target_pid
    for signum in _FORWARDABLE_SIGNALS:
        libc.signal(signum, forwarding_signal_handler)
    reset_signal_handling()

def wait_for_child_and_forward_all_signals(child_pid, process_name):
    """Wait for a child to terminate and in the meantime forward all signals the current process
    receives to this child.
    @return a tuple of exit code and resource usage of the child as given by os.waitpid"""
    assert _HAS_SIGWAIT
    block_all_signals()
    while True:
        logging.debug('Waiting for signals')
        signum = signal.sigwait(_ALL_SIGNALS)
        if signum == signal.SIGCHLD:
            pid, exitcode, ru_child = os.wait4(-1, os.WNOHANG)
            while pid != 0:
                if pid == child_pid:
                    return (exitcode, ru_child)
                else:
                    logging.debug('Received unexpected SIGCHLD for PID %s', pid)
                pid, exitcode, ru_child = os.wait4(-1, os.WNOHANG)
        else:
            _forward_signal(signum, child_pid, process_name)

def close_open_fds(keep_files=[]):
    """Close all open file descriptors except those in a given set.
    @param keep_files: an iterable of file descriptors or file-like objects."""
    keep_fds = set()
    for file in keep_files:
        if isinstance(file, int):
            keep_fds.add(file)
        else:
            try:
                keep_fds.add(file.fileno())
            except Exception:
                pass
    for fd in os.listdir('/proc/self/fd'):
        fd = int(fd)
        if fd not in keep_fds:
            try:
                os.close(fd)
            except OSError:
                pass

def setup_container_system_config(basedir, mountdir=None):
    """Create a minimal system configuration for use in a container.
    @param basedir: The directory where the configuration files should be placed as bytes.
    @param mountdir: If present, bind mounts to the configuration files will be added below
        this path (given as bytes)."""
    etc = os.path.join(basedir, b'etc')
    if not os.path.exists(etc):
        os.mkdir(etc)
    for file, content in CONTAINER_ETC_FILE_OVERRIDE.items():
        util.write_file(content, etc, file)
        if mountdir:
            make_bind_mount(os.path.join(etc, file), os.path.join(mountdir, b'etc', file), private=True)
    os.symlink(b'/proc/self/mounts', os.path.join(etc, b'mtab'))

def is_container_system_config_file(file):
    """Determine whether a given file is one of the files created by setup_container_system_config().
    @param file: Absolute file path as string."""
    if not file.startswith('/etc/'):
        return False
    return file in [os.path.join('/etc', f.decode()) for f in CONTAINER_ETC_FILE_OVERRIDE]

def format_energy_results(energy):
    """Take the result of an energy measurement and return a flat dictionary that contains all values."""
    if not energy:
        return {}
    result = {}
    cpuenergy = Decimal(0)
    for pkg, domains in energy.items():
        for domain, value in domains.items():
            if domain == DOMAIN_PACKAGE:
                cpuenergy += value
                result['cpuenergy-pkg{}'.format(pkg)] = value
            else:
                result['cpuenergy-pkg{}-{}'.format(pkg, domain)] = value
    result['cpuenergy'] = cpuenergy
    result = collections.OrderedDict(sorted(result.items()))
    return result

def unpivot_frame(frame, x=None, y=None, var_name='variable', value_name='value'):
    """Unpivot a dataframe for use with Vega/Vega-Lite

    The input is a frame with any number of columns,
    output is a frame with three columns: x value, y values,
    and variable names."""
    if x is None:
        cols = frame.columns
        frame = frame.reset_index()
        x = (set(frame.columns) - set(cols)).pop()
    if isinstance(x, tuple):
        x = list(x)
    if isinstance(y, tuple):
        y = list(y)
    if x is not None:
        _ = frame[x]
    if y is not None:
        _ = frame[y]
    return frame.melt(id_vars=x, value_vars=y, var_name=var_name, value_name=value_name)

def version(path):
    """Obtain the packge version from a python file e.g. pkg/__init__.py
    See <https://packaging.python.org/en/latest/single_source_version.html>."""
    version_file = read(path)
    version_match = re.search('^__version__ = [\'"]([^\'"]*)[\'"]', version_file, re.M)
    if version_match:
        return version_match.group(1)
    raise RuntimeError('Unable to find version string.')

def dict_hash(dct):
    """Return a hash of the contents of a dictionary"""
    dct_s = json.dumps(dct, sort_keys=True)
    try:
        m = md5(dct_s)
    except TypeError:
        m = md5(dct_s.encode())
    return m.hexdigest()

def exec_then_eval(code, namespace=None):
    """Exec a code block & return evaluation of the last line"""
    namespace = namespace or {}
    block = ast.parse(code, mode='exec')
    last = ast.Expression(block.body.pop().value)
    exec(compile(block, '<string>', mode='exec'), namespace)
    return eval(compile(last, '<string>', mode='eval'), namespace)

def import_obj(clsname, default_module=None):
    """Import the object given by clsname.
    If default_module is specified, import from this module."""
    if default_module is not None:
        if not clsname.startswith(default_module + '.'):
            clsname = '{0}.{1}'.format(default_module, clsname)
    mod, clsname = clsname.rsplit('.', 1)
    mod = importlib.import_module(mod)
    try:
        obj = getattr(mod, clsname)
    except AttributeError:
        raise ImportError('Cannot import {0} from {1}'.format(clsname, mod))
    return obj

def strip_vl_extension(filename):
    """Strip the vega-lite extension (either vl.json or json) from filename"""
    for ext in ['.vl.json', '.json']:
        if filename.endswith(ext):
            return filename[:-len(ext)]
    else:
        return filename

def prev_this_next(it, sentinel=None):
    """Utility to return (prev, this, next) tuples from an iterator"""
    i1, i2, i3 = tee(it, 3)
    next(i3, None)
    return zip(chain([sentinel], i1), i2, chain(i3, [sentinel]))

def get_scheme_cartocss(column, scheme_info):
    """Get TurboCARTO CartoCSS based on input parameters"""
    if 'colors' in scheme_info:
        color_scheme = '({})'.format(','.join(scheme_info['colors']))
    else:
        color_scheme = 'cartocolor({})'.format(scheme_info['name'])
    if not isinstance(scheme_info['bins'], int):
        bins = ','.join((str(i) for i in scheme_info['bins']))
    else:
        bins = scheme_info['bins']
    bin_method = scheme_info['bin_method']
    comparison = ', {}'.format(BinMethod.mapping.get(bin_method, '>='))
    return 'ramp([{column}], {color_scheme}, {bin_method}({bins}){comparison})'.format(column=column, color_scheme=color_scheme, bin_method=bin_method, bins=bins, comparison=comparison)

def _get_bounds_local(layers):
    """Aggregates bounding boxes of all local layers

    return: dict of bounding box of all bounds in layers"""
    if not layers:
        return {'west': None, 'south': None, 'east': None, 'north': None}
    bounds = layers[0].bounds
    for layer in layers[1:]:
        bounds = np.concatenate((np.minimum(bounds[:2], layer.bounds[:2]), np.maximum(bounds[2:], layer.bounds[2:])))
    return dict(zip(['west', 'south', 'east', 'north'], bounds))

def _combine_bounds(bbox1, bbox2):
    """Takes two bounding boxes dicts and gives a new bbox that encompasses
    them both"""
    WORLD = {'west': -180, 'south': -85.1, 'east': 180, 'north': 85.1}
    ALL_KEYS = set(WORLD.keys())
    def dict_all_nones(bbox_dict):
        """Returns True if all dict values are None"""
        return all((v is None for v in bbox_dict.values()))
    if not bbox1 and (not bbox2):
        return WORLD
    if dict_all_nones(bbox1) and dict_all_nones(bbox2):
        return WORLD
    assert ALL_KEYS == set(bbox1.keys()) and ALL_KEYS == set(bbox2.keys()), 'Input bounding boxes must have the same dictionary keys'
    outbbox = dict.fromkeys(['west', 'south', 'east', 'north'])
    def conv2nan(val):
        """convert Nones to np.nans"""
        return np.nan if val is None else val
    for coord in ('north', 'east'):
        outbbox[coord] = np.nanmax([conv2nan(bbox1[coord]), conv2nan(bbox2[coord])])
    for coord in ('south', 'west'):
        outbbox[coord] = np.nanmin([conv2nan(bbox1[coord]), conv2nan(bbox2[coord])])
    return outbbox

def cssify(css_dict):
    """Function to get CartoCSS from Python dicts"""
    css = ''
    for key, value in dict_items(css_dict):
        css += '{key} {{ '.format(key=key)
        for field, field_value in dict_items(value):
            css += ' {field}: {field_value};'.format(field=field, field_value=field_value)
        css += '} '
    return css.strip()

def safe_quotes(text, escape_single_quotes=False):
    """htmlify string"""
    if isinstance(text, str):
        safe_text = text.replace('"', '&quot;')
        if escape_single_quotes:
            safe_text = safe_text.replace("'", "&#92;'")
        return safe_text.replace('True', 'true')
    return text

