def _wifi_connect():
    """Connects to WIFI"""
    if not wlan.isconnected():
        wlan.active(True)
        print('NETWORK: connecting to network %s...' % settings.WIFI_SSID)
        wlan.connect(settings.WIFI_SSID, secret)
        while not wlan.isconnected():
            print('NETWORK: waiting for connection...')
            utime.sleep(1)
        print('NETWORK: Connected, network config: %s' % repr(wlan.ifconfig()))

def shipping_cost(request):
    """Returns the shipping cost for a given country
    If the shipping cost for the given country has not been set, it will
    fallback to the default shipping cost if it has been enabled in the app
    settings"""
    try:
        code = request.query_params.get('country_code')
    except AttributeError:
        return Response(data={'message': 'No country code supplied'}, status=status.HTTP_400_BAD_REQUEST)
    option = request.query_params.get('shipping_rate_name', 'standard')
    try:
        settings = Configuration.for_site(request.site)
        data = utils.get_shipping_cost(settings, code, option)
        response = Response(data=data, status=status.HTTP_200_OK)
    except utils.InvalidShippingRate:
        response = Response(data={'message': 'Shipping option {} is invalid'.format(option)}, status=status.HTTP_400_BAD_REQUEST)
