def constraint_to_si(expr):
    """Convert a constraint to SI if possible.

    :param expr:
    :return:"""
    satisfiable = True
    replace_list = []
    satisfiable, replace_list = backends.vsa.constraint_to_si(expr)
    for i in xrange(len(replace_list)):
        ori, new = replace_list[i]
        if not isinstance(new, Base):
            new = BVS(new.name, new._bits, min=new._lower_bound, max=new._upper_bound, stride=new._stride, explicit_name=True)
            replace_list[i] = (ori, new)
    return (satisfiable, replace_list)

def _d(h, cls, state):
    """This function is the deserializer for ASTs.
    It exists to work around the fact that pickle will (normally) call __new__() with no arguments during deserialization.
    For ASTs, this does not work."""
    op, args, length, variables, symbolic, annotations = state
    return cls.__new__(cls, op, args, length=length, variables=variables, symbolic=symbolic, annotations=annotations, hash=h)

def _normalize_arguments(expr_left, expr_rigth):
    """Since we decided to emulate integer with bitvector, this method transform their
    concrete value (if any) in the corresponding integer"""
    if expr_left.is_str_op() and expr_rigth.is_bv_constant():
        return (expr_left, Int(expr_rigth.bv_signed_value()))
    elif expr_left.is_bv_constant() and expr_rigth.is_str_op():
        return (expr_rigth, Int(expr_left.bv_signed_value()))
    return (expr_left, expr_rigth)

def StringV(value, length=None, **kwargs):
    """Create a new Concrete string (analogous to z3.StringVal())

    :param value: The constant value of the concrete string

    :returns:                    The String object representing the concrete string"""
    if length is None:
        length = len(value)
    if length < len(value):
        raise ValueError("Can't make a concrete string value longer than the specified length!")
    result = String('StringV', (value, len(value)), length=length, **kwargs)
    return result

def StrConcat(*args):
    """Create a concrete version of the concatenated string
    :param args: List of string that has to be concatenated

    :return : a concrete version of the concatenated string"""
    new_value = ''.join([arg.value for arg in args])
    return StringV(new_value)

def StrIndexOf(input_string, substring, startIndex, bitlength):
    """Return True if the concrete value of the input_string ends with suffix
    otherwise false.

    :param input_string: the string we want to check
    :param substring: the substring we want to find the index
    :param startIndex: the index to start searching at
    :param bitlength: bitlength of the bitvector representing the index of the substring

    :return BVV: index of the substring in bit-vector representation or -1 in bitvector representation"""
    try:
        s = input_string.value
        t = substring.value
        i = startIndex.value
        return BVV(i + s[i:].index(t), bitlength)
    except ValueError:
        return BVV(-1, bitlength)

def StrToInt(input_string, bitlength):
    """Return True if the concrete value of the input_string ends with suffix
    otherwise false.

    :param input_string: the string we want to transform in an integer
    :param bitlength: bitlength of the bitvector representing the index of the substring

    :return BVV: bit-vector representation of the integer resulting from ythe string or -1 in bitvector representation
                 if the string cannot be transformed into an integer"""
    try:
        return BVV(int(input_string.value), bitlength)
    except ValueError:
        return BVV(-1, bitlength)

def BVV(value, size=None, **kwargs):
    """Creates a bit-vector value (i.e., a concrete value).

    :param value:   The value. Either an integer or a string. If it's a string, it will be interpreted as the bytes of
                    a big-endian constant.
    :param size:    The size (in bits) of the bit-vector. Optional if you provide a string, required for an integer.

    :returns:       A BV object representing this value."""
    if type(value) in (bytes, str):
        if type(value) is str:
            l.warning('BVV value is a unicode string, encoding as utf-8')
            value = value.encode('utf-8')
        if size is None:
            size = len(value) * 8
        elif type(size) is not int:
            raise TypeError('Bitvector size  must be either absent (implicit) or an integer')
        elif size != len(value) * 8:
            raise ClaripyValueError('string/size mismatch for BVV creation')
        value = int(binascii.hexlify(value), 16) if value != b'' else 0
    elif size is None or (type(value) is not int and value is not None):
        raise TypeError('BVV() takes either an integer value and a size or a string of bytes')
    if value is not None:
        value &= (1 << size) - 1
    if not kwargs:
        try:
            return _bvv_cache[value, size]
        except KeyError:
            pass
    result = BV('BVV', (value, size), length=size, **kwargs)
    _bvv_cache[value, size] = result
    return result

def styled_plot(*style_sheets):
    """Return a decorator that will apply matplotlib style sheets to a plot.

    ``style_sheets`` is a base set of styles, which will be ignored if
    ``no_base_style`` is set in the decorated function arguments.

    The style will further be overwritten by any styles in the ``style``
    optional argument of the decorated function.

    Args:
        style_sheets (:obj:`list`, :obj:`str`, or :obj:`dict`): Any matplotlib
            supported definition of a style sheet. Can be a list of style of
            style sheets."""
    def decorator(get_plot):
        def wrapper(*args, fonts=None, style=None, no_base_style=False, **kwargs):
            if no_base_style:
                list_style = []
            else:
                list_style = list(style_sheets)
            if style is not None:
                if isinstance(style, list):
                    list_style += style
                else:
                    list_style += [style]
            if fonts is not None:
                list_style += [{'font.family': 'sans-serif', 'font.sans-serif': fonts}]
            matplotlib.pyplot.style.use(list_style)
            return get_plot(*args, **kwargs)
        return wrapper
    return decorator

def power_tick(val, pos, times_sign='\\times'):
    """Custom power ticker function."""
    if val == 0:
        return '$\\mathregular{0}$'
    elif val < 0:
        exponent = int(np.log10(-val))
    else:
        exponent = int(np.log10(val))
    coeff = val / 10 ** exponent
    return '$\\mathregular{{{:.1f} {} 10^{:2d}}}$'.format(coeff, times_sign, exponent)

def which(cmd, path='PATH'):
    """Find cmd on PATH."""
    if os.path.exists(cmd):
        return cmd
    if cmd[0] == '/':
        return None
    for segment in os.getenv(path).split(':'):
        program = os.path.normpath(os.path.join(segment, cmd))
        if os.path.exists(program):
            return program
    return None

def validate_sha(sha):
    """Validate that a hexdigest sha is a valid commit in the repo

    raises ValueError if the sha does not reference a commit within the repo"""
    cmd = ['git', 'log', '-r', sha]
    try:
        subprocess.check_output(cmd, stderr=subprocess.STDOUT)
    except subprocess.SubprocessError:
        raise ValueError(f'The sha listed in the branch name, {sha}, is not present in the repository')

def version_from_branch(branch):
    """return version information from a git branch name"""
    try:
        return tuple(map(int, re.match('^.*(?P<version>\\d+(\\.\\d+)+).*$', branch).groupdict()['version'].split('.')))
    except AttributeError as attr_err:
        raise ValueError(f'Branch {branch} seems to not have a version in its name.') from attr_err

