def en(item):
    """Use msgpack to serialize a compatible python object.

    Args:
        item (obj): The object to serialize

    Notes:
        String objects are encoded using utf8 encoding.  In order to handle
        potentially malformed input, ``unicode_errors='surrogatepass'`` is set
        to allow encoding bad input strings.

    Returns:
        bytes: The serialized bytes in msgpack format."""
    if pakr is None:
        return msgpack.packb(item, use_bin_type=True, unicode_errors='surrogatepass')
    try:
        return pakr.pack(item)
    except Exception:
        pakr.reset()
        raise

def imeicsum(text):
    """Calculate the imei check byte."""
    digs = []
    for i in range(14):
        v = int(text[i])
        if i % 2:
            v *= 2
        [digs.append(int(x)) for x in str(v)]
    chek = 0
    valu = sum(digs)
    remd = valu % 10
    if remd != 0:
        chek = 10 - remd
    return str(chek)

def varinit(task=None):
    """Initializes (or re-initializes for testing purposes) all of a task's task-local variables

    Precondition:
        If task is None, this must be called from task context"""
    if task is None:
        task = asyncio.current_task()
    taskvars = {}
    task._syn_taskvars = taskvars
    return taskvars

def _taskdict(task):
    """Note: No locking is provided.  Under normal circumstances, like the other task is not running (e.g. this is running
    from the same event loop as the task) or task is the current task, this is fine."""
    if task is None:
        task = asyncio.current_task()
    assert task
    taskvars = getattr(task, '_syn_taskvars', None)
    if taskvars is None:
        taskvars = varinit(task)
    return taskvars

