def hashitem(item):
    """Generate a uniq hash for the JSON compatible primitive data structure."""
    norm = normitem(item)
    byts = s_msgpack.en(norm)
    return hashlib.md5(byts).hexdigest()

def nom(txt, off, cset, trim=True):
    """Consume chars in set from the string and return (subtxt,offset).

    Example:

        text = "foo(bar)"
        chars = set('abcdefghijklmnopqrstuvwxyz')

        name,off = nom(text,0,chars)"""
    if trim:
        while len(txt) > off and txt[off] in whites:
            off += 1
    r = ''
    while len(txt) > off and txt[off] in cset:
        r += txt[off]
        off += 1
    if trim:
        while len(txt) > off and txt[off] in whites:
            off += 1
    return (r, off)

def parse_cmd_string(text, off, trim=True):
    """Parse in a command line string which may be quoted."""
    if trim:
        _, off = nom(text, off, whites)
    if isquote(text, off):
        return parse_string(text, off, trim=trim)
    if nextchar(text, off, '('):
        return parse_list(text, off)
    return meh(text, off, whites)

def parse_valu(text, off=0):
    """Special syntax for the right side of equals in a macro"""
    _, off = nom(text, off, whites)
    if nextchar(text, off, '('):
        return parse_list(text, off)
    if isquote(text, off):
        return parse_string(text, off)
    valu, off = meh(text, off, valmeh)
    try:
        valu = int(valu, 0)
    except ValueError:
        pass
    return (valu, off)

def parse_cmd_kwarg(text, off=0):
    """Parse a foo:bar=<valu> kwarg into (prop,valu),off"""
    _, off = nom(text, off, whites)
    prop, off = nom(text, off, varset)
    _, off = nom(text, off, whites)
    if not nextchar(text, off, '='):
        raise s_exc.BadSyntax(expected='= for kwarg ' + prop, at=off)
    _, off = nom(text, off + 1, whites)
    valu, off = parse_cmd_string(text, off)
    return ((prop, valu), off)

def parse_cmd_kwlist(text, off=0):
    """Parse a foo:bar=<valu>[,...] kwarg list into (prop,valu),off"""
    kwlist = []
    _, off = nom(text, off, whites)
    while off < len(text):
        (p, v), off = parse_cmd_kwarg(text, off=off)
        kwlist.append((p, v))
        _, off = nom(text, off, whites)
        if not nextchar(text, off, ','):
            break
    _, off = nom(text, off, whites)
    return (kwlist, off)

def parse(text, base=None, chop=False):
    """Parse a time string into an epoch millis value."""
    text = text.strip().lower()
    text = ''.join([c for c in text if c.isdigit()])
    if chop:
        text = text[:17]
    tlen = len(text)
    if tlen == 4:
        dt = datetime.datetime.strptime(text, '%Y')
    elif tlen == 6:
        dt = datetime.datetime.strptime(text, '%Y%m')
    elif tlen == 8:
        dt = datetime.datetime.strptime(text, '%Y%m%d')
    elif tlen == 10:
        dt = datetime.datetime.strptime(text, '%Y%m%d%H')
    elif tlen == 12:
        dt = datetime.datetime.strptime(text, '%Y%m%d%H%M')
    elif tlen == 14:
        dt = datetime.datetime.strptime(text, '%Y%m%d%H%M%S')
    elif tlen in (15, 16, 17):
        dt = datetime.datetime.strptime(text, '%Y%m%d%H%M%S%f')
    else:
        raise s_exc.BadTypeValu(valu=text, name='time', mesg='Unknown time format')
    epoch = datetime.datetime(1970, 1, 1)
    return int((dt - epoch).total_seconds() * 1000)

def repr(tick, pack=False):
    """Return a date string for an epoch-millis timestamp.

    Args:
        tick (int): The timestamp in milliseconds since the epoch.

    Returns:
        (str):  A date time string"""
    if tick == 9223372036854775807:
        return '?'
    dt = datetime.datetime(1970, 1, 1) + datetime.timedelta(milliseconds=tick)
    millis = dt.microsecond / 1000
    if pack:
        return '%d%.2d%.2d%.2d%.2d%.2d%.3d' % (dt.year, dt.month, dt.day, dt.hour, dt.minute, dt.second, millis)
    return '%d/%.2d/%.2d %.2d:%.2d:%.2d.%.3d' % (dt.year, dt.month, dt.day, dt.hour, dt.minute, dt.second, millis)

def fold(*vals):
    """Initialize a new (min,max) tuple interval from values.

    Args:
        *vals ([int,...]):  A list of values (or Nones)

    Returns:
        ((int,int)):    A (min,max) interval tuple or None"""
    vals = [v for v in vals if v is not None]
    if not vals:
        return None
    return (min(vals), max(vals))

