def make_iterable(value):
    """Converts the supplied value to a list object

    This function will inspect the supplied value and return an
    iterable in the form of a list.

    Args:
        value (object): An valid Python object

    Returns:
        An iterable object of type list"""
    if sys.version_info <= (3, 0):
        if isinstance(value, unicode):
            value = str(value)
    if isinstance(value, str) or isinstance(value, dict):
        value = [value]
    if not isinstance(value, collections.Iterable):
        raise TypeError('value must be an iterable object')
    return value

def collapse_range(arg, value_delimiter=',', range_delimiter='-'):
    """Collapses a list of values into a range set

    :param arg: The list of values to collapse
    :param value_delimiter: The delimiter that separates values
    :param range_delimiter: The delimiter that separates a value range

    :return: An array of collapsed string values
    :rtype: list"""
    values = list()
    expanded = arg.split(value_delimiter)
    range_start = None
    for v1, v2 in lookahead(expanded):
        if v2:
            v1 = int(v1)
            v2 = int(v2)
            if v1 + 1 == v2:
                if not range_start:
                    range_start = v1
            elif range_start:
                item = '{}{}{}'.format(range_start, range_delimiter, v1)
                values.extend([item])
                range_start = None
            else:
                values.extend([v1])
        elif range_start:
            item = '{}{}{}'.format(range_start, range_delimiter, v1)
            values.extend([item])
            range_start = None
        else:
            values.extend([v1])
    return [str(x) for x in values]

def as_2d(self):
    """get a 2D representation of x.  If not self.isdiagonal, simply
    return reference to self.x, otherwise, constructs and returns
    a 2D, diagonal ndarray

    Returns
    -------
    numpy.ndarray : numpy.ndarray"""
    if not self.isdiagonal:
        return self.x
    return np.diag(self.x.flatten())

def shape(self):
    """get the implied, 2D shape of self

    Returns
    -------
    tuple : tuple
        length 2 tuple of ints"""
    if self.__x is not None:
        if self.isdiagonal:
            return (max(self.__x.shape), max(self.__x.shape))
        if len(self.__x.shape) == 1:
            raise Exception('Matrix.shape: Matrix objects must be 2D')
        return self.__x.shape
    return None

def transpose(self):
    """transpose operation of self

    Returns
    -------
    Matrix : Matrix
        transpose of self"""
    if not self.isdiagonal:
        return type(self)(x=self.__x.copy().transpose(), row_names=self.col_names, col_names=self.row_names, autoalign=self.autoalign)
    else:
        return type(self)(x=self.__x.copy(), row_names=self.row_names, col_names=self.col_names, isdiagonal=True, autoalign=self.autoalign)

def inv(self):
    """inversion operation of self

    Returns
    -------
    Matrix : Matrix
        inverse of self"""
    if self.isdiagonal:
        inv = 1.0 / self.__x
        if np.any(~np.isfinite(inv)):
            idx = np.isfinite(inv)
            np.savetxt('testboo.dat', idx)
            invalid = [self.row_names[i] for i in range(idx.shape[0]) if idx[i] == 0.0]
            raise Exception('Matrix.inv has produced invalid floating points ' + ' for the following elements:' + ','.join(invalid))
        return type(self)(x=inv, isdiagonal=True, row_names=self.row_names, col_names=self.col_names, autoalign=self.autoalign)
    else:
        return type(self)(x=la.inv(self.__x), row_names=self.row_names, col_names=self.col_names, autoalign=self.autoalign)

def sqrt(self):
    """square root operation

    Returns
    -------
    Matrix : Matrix
        square root of self"""
    if self.isdiagonal:
        return type(self)(x=np.sqrt(self.__x), isdiagonal=True, row_names=self.row_names, col_names=self.col_names, autoalign=self.autoalign)
    elif self.shape[1] == 1:
        return type(self)(x=np.sqrt(self.__x), isdiagonal=False, row_names=self.row_names, col_names=self.col_names, autoalign=self.autoalign)
    else:
        return type(self)(x=la.sqrtm(self.__x), row_names=self.row_names, col_names=self.col_names, autoalign=self.autoalign)

def zero2d(self):
    """get an 2D instance of self with all zeros

    Returns
    -------
    Matrix : Matrix"""
    return type(self)(x=np.atleast_2d(np.zeros((self.shape[0], self.shape[1]))), row_names=self.row_names, col_names=self.col_names, isdiagonal=False)

def _read_variogram(f):
    """Function to instantiate a Vario2d from a PEST-style structure file

    Parameters
    ----------
    f : (file handle)
        file handle opened for reading

    Returns
    -------
    Vario2d : Vario2d
        Vario2d derived type"""
    line = ''
    vartype = None
    bearing = 0.0
    a = None
    anisotropy = 1.0
    while 'end variogram' not in line:
        line = f.readline()
        if line == '':
            raise Exception('EOF while read variogram')
        line = line.strip().lower().split()
        if line[0].startswith('#'):
            continue
        if line[0] == 'vartype':
            vartype = int(line[1])
        elif line[0] == 'bearing':
            bearing = float(line[1])
        elif line[0] == 'a':
            a = float(line[1])
        elif line[0] == 'anisotropy':
            anisotropy = float(line[1])
        elif line[0] == 'end':
            break
        else:
            raise Exception('unrecognized arg in variogram:{0}'.format(line[0]))
    return (vartype, bearing, a, anisotropy)

def _sortValue_isItalic(font):
    """Returns 0 if the font is italic.
    Returns 1 if the font is not italic."""
    info = font.info
    styleMapStyleName = info.styleMapStyleName
    if styleMapStyleName is not None and 'italic' in styleMapStyleName:
        return 0
    if info.italicAngle not in (None, 0):
        return 0
    return 1

def _sortValue_isMonospace(font):
    """Returns 0 if the font is monospace.
    Returns 1 if the font is not monospace."""
    if font.info.postscriptIsFixedPitch:
        return 0
    if not len(font):
        return 1
    testWidth = None
    for glyph in font:
        if testWidth is None:
            testWidth = glyph.width
        elif testWidth != glyph.width:
            return 1
    return 0

def normalizeLayerOrder(value, font):
    """Normalizes layer order.

    ** **value** must be a ``tuple`` or ``list``.
    * **value** items must normalize as layer names with
      :func:`normalizeLayerName`.
    * **value** must contain layers that exist in **font**.
    * **value** must not contain duplicate layers.
    * Returned ``tuple`` will be unencoded ``unicode`` strings
      for each layer name."""
    if not isinstance(value, (tuple, list)):
        raise TypeError('Layer order must be a list, not %s.' % type(value).__name__)
    for v in value:
        normalizeLayerName(v)
    fontLayers = [layer.name for layer in font.layers]
    for name in value:
        if name not in fontLayers:
            raise ValueError('Layer must exist in font. %s does not exist in font.layers.' % name)
    duplicates = [v for v, count in Counter(value).items() if count > 1]
    if len(duplicates) != 0:
        raise ValueError("Duplicate layers are not allowed. Layer name(s) '%s' are duplicate(s)." % ', '.join(duplicates))
    return tuple([unicode(v) for v in value])

def normalizeDefaultLayerName(value, font):
    """Normalizes default layer name.

    * **value** must normalize as layer name with
      :func:`normalizeLayerName`.
    * **value** must be a layer in **font**.
    * Returned value will be an unencoded ``unicode`` string."""
    value = normalizeLayerName(value)
    if value not in font.layerOrder:
        raise ValueError("No layer with the name '%s' exists." % value)
    return unicode(value)

def normalizeGlyphOrder(value):
    """Normalizes glyph order.

    ** **value** must be a ``tuple`` or ``list``.
    * **value** items must normalize as glyph names with
      :func:`normalizeGlyphName`.
    * **value** must not repeat glyph names.
    * Returned value will be a ``tuple`` of unencoded ``unicode`` strings."""
    if not isinstance(value, (tuple, list)):
        raise TypeError('Glyph order must be a list, not %s.' % type(value).__name__)
    for v in value:
        normalizeGlyphName(v)
    duplicates = sorted((v for v, count in Counter(value).items() if count > 1))
    if len(duplicates) != 0:
        raise ValueError("Duplicate glyph names are not allowed. Glyph name(s) '%s' are duplicate." % ', '.join(duplicates))
    return tuple([unicode(v) for v in value])

def normalizeKerningKey(value):
    """Normalizes kerning key.

    * **value** must be a ``tuple`` or ``list``.
    * **value** must contain only two members.
    * **value** items must be :ref:`type-string`.
    * **value** items must be at least one character long.
    * Returned value will be a two member ``tuple`` of unencoded
      ``unicode`` strings."""
    if not isinstance(value, (tuple, list)):
        raise TypeError('Kerning key must be a tuple instance, not %s.' % type(value).__name__)
    if len(value) != 2:
        raise ValueError('Kerning key must be a tuple containing two items, not %d.' % len(value))
    for v in value:
        if not isinstance(v, basestring):
            raise TypeError('Kerning key items must be strings, not %s.' % type(v).__name__)
        if len(v) < 1:
            raise ValueError('Kerning key items must be one character long')
    if value[0].startswith('public.') and (not value[0].startswith('public.kern1.')):
        raise ValueError('Left Kerning key group must start with public.kern1.')
    if value[1].startswith('public.') and (not value[1].startswith('public.kern2.')):
        raise ValueError('Right Kerning key group must start with public.kern2.')
    return tuple([unicode(v) for v in value])

def normalizeGroupValue(value):
    """Normalizes group value.

    * **value** must be a ``list``.
    * **value** items must normalize as glyph names with
      :func:`normalizeGlyphName`.
    * Returned value will be a ``tuple`` of unencoded ``unicode`` strings."""
    if not isinstance(value, (tuple, list)):
        raise TypeError('Group value must be a list, not %s.' % type(value).__name__)
    value = [normalizeGlyphName(v) for v in value]
    return tuple([unicode(v) for v in value])

def normalizeFeatureText(value):
    """Normalizes feature text.

    * **value** must be a :ref:`type-string`.
    * Returned value will be an unencoded ``unicode`` string."""
    if not isinstance(value, basestring):
        raise TypeError('Feature text must be a string, not %s.' % type(value).__name__)
    return unicode(value)

def normalizeLibValue(value):
    """Normalizes lib value.

    * **value** must not be ``None``.
    * Returned value is the same type as the input value."""
    if value is None:
        raise ValueError('Lib value must not be None.')
    if isinstance(value, (list, tuple)):
        for v in value:
            normalizeLibValue(v)
    elif isinstance(value, dict):
        for k, v in value.items():
            normalizeLibKey(k)
            normalizeLibValue(v)
    elif isinstance(value, basestring):
        value = unicode(value)
    return value

def normalizeGlyphUnicode(value):
    """Normalizes glyph unicode.

    * **value** must be an int or hex (represented as a string).
    * **value** must be in a unicode range.
    * Returned value will be an ``int``."""
    if not isinstance(value, (int, basestring)) or isinstance(value, bool):
        raise TypeError('Glyph unicode must be a int or hex string, not %s.' % type(value).__name__)
    if isinstance(value, basestring):
        try:
            value = int(value, 16)
        except ValueError:
            raise ValueError('Glyph unicode hex must be a valid hex string.')
    if value < 0 or value > 1114111:
        raise ValueError('Glyph unicode must be in the Unicode range.')
    return value

def normalizeGlyphFormatVersion(value):
    """Normalizes glyph format version for saving to XML string.

    * **value** must be a :ref:`type-int-float` of either 1 or 2.
    * Returned value will be an int."""
    if not isinstance(value, (int, float)):
        raise TypeError('Glyph Format Version must be an :ref:`type-int-float`, not %s.' % type(value).__name__)
    value = int(value)
    if value not in (1, 2):
        raise ValueError('Glyph Format Version must be either 1 or 2, not %s.' % value)
    return value

def normalizePointName(value):
    """Normalizes point name.

    * **value** must be a :ref:`type-string`.
    * **value** must be at least one character long.
    * Returned value will be an unencoded ``unicode`` string."""
    if not isinstance(value, basestring):
        raise TypeError('Point names must be strings, not %s.' % type(value).__name__)
    if len(value) < 1:
        raise ValueError('Point names must be at least one character long.')
    return unicode(value)

def normalizeBoolean(value):
    """Normalizes a boolean.

    * **value** must be an ``int`` with value of 0 or 1, or a ``bool``.
    * Returned value will be a boolean."""
    if isinstance(value, int) and value in (0, 1):
        value = bool(value)
    if not isinstance(value, bool):
        raise ValueError("Boolean values must be True or False, not '%s'." % value)
    return value

def normalizeIndex(value):
    """Normalizes index.

    * **value** must be an ``int`` or ``None``.
    * Returned value is the same type as the input value."""
    if value is not None:
        if not isinstance(value, int):
            raise TypeError('Indexes must be None or integers, not %s.' % type(value).__name__)
    return value

def normalizeIdentifier(value):
    """Normalizes identifier.

    * **value** must be an :ref:`type-string` or `None`.
    * **value** must not be longer than 100 characters.
    * **value** must not contain a character out the range of 0x20 - 0x7E.
    * Returned value is an unencoded ``unicode`` string."""
    if value is None:
        return value
    if not isinstance(value, basestring):
        raise TypeError('Identifiers must be strings, not %s.' % type(value).__name__)
    if len(value) == 0:
        raise ValueError('The identifier string is empty.')
    if len(value) > 100:
        raise ValueError('The identifier string has a length (%d) greater than the maximum allowed (100).' % len(value))
    for c in value:
        v = ord(c)
        if v < 32 or v > 126:
            raise ValueError("The identifier string ('%s') contains a character out size of the range 0x20 - 0x7E." % value)
    return unicode(value)

def normalizeArea(value):
    """Normalizes area.

    * **value** must be a positive :ref:`type-int-float`."""
    if not isinstance(value, (int, float)):
        raise TypeError('Area must be an instance of :ref:`type-int-float`, not %s.' % type(value).__name__)
    if value < 0:
        raise ValueError('Area must be a positive :ref:`type-int-float`, not %s.' % repr(value))
    return float(value)

def normalizeRotationAngle(value):
    """Normalizes an angle.

    * Value must be a :ref:`type-int-float`.
    * Value must be between -360 and 360.
    * If the value is negative, it is normalized by adding it to 360
    * Returned value is a ``float`` between 0 and 360."""
    if not isinstance(value, (int, float)):
        raise TypeError('Angle must be instances of :ref:`type-int-float`, not %s.' % type(value).__name__)
    if abs(value) > 360:
        raise ValueError('Angle must be between -360 and 360.')
    if value < 0:
        value = value + 360
    return float(value)

def normalizeColor(value):
    """Normalizes :ref:`type-color`.

    * **value** must be an ``tuple`` or ``list``.
    * **value** must have exactly four items.
    * **value** color components must be between 0 and 1.
    * Returned value is a ``tuple`` containing four ``float`` values."""
    from fontParts.base.color import Color
    if not isinstance(value, (tuple, list, Color)):
        raise TypeError('Colors must be tuple instances, not %s.' % type(value).__name__)
    if not len(value) == 4:
        raise ValueError('Colors must contain four values, not %d.' % len(value))
    for component, v in zip('rgba', value):
        if not isinstance(v, (int, float)):
            raise TypeError('The value for the %s component (%s) is not an int or float.' % (component, v))
        if v < 0 or v > 1:
            raise ValueError('The value for the %s component (%s) is not between 0 and 1.' % (component, v))
    return tuple([float(v) for v in value])

def normalizeGlyphNote(value):
    """Normalizes Glyph Note.

    * **value** must be a :ref:`type-string`.
    * Returned value is an unencoded ``unicode`` string"""
    if not isinstance(value, basestring):
        raise TypeError('Note must be a string, not %s.' % type(value).__name__)
    return unicode(value)

def normalizeFilePath(value):
    """Normalizes file path.

    * **value** must be a :ref:`type-string`.
    * Returned value is an unencoded ``unicode`` string"""
    if not isinstance(value, basestring):
        raise TypeError('File paths must be strings, not %s.' % type(value).__name__)
    return unicode(value)

def normalizeInterpolationFactor(value):
    """Normalizes interpolation factor.

    * **value** must be an :ref:`type-int-float`, ``tuple`` or ``list``.
    * If **value** is a ``tuple`` or ``list``, it must have exactly two items.
      These items must be instances of :ref:`type-int-float`.
    * Returned value is a ``tuple`` of two ``float``."""
    if not isinstance(value, (int, float, list, tuple)):
        raise TypeError('Interpolation factor must be an int, float, or tuple instances, not %s.' % type(value).__name__)
    if isinstance(value, (int, float)):
        value = (float(value), float(value))
    else:
        if not len(value) == 2:
            raise ValueError('Interpolation factor tuple must contain two values, not %d.' % len(value))
        for v in value:
            if not isinstance(v, (int, float)):
                raise TypeError('Interpolation factor tuple values must be an :ref:`type-int-float`, not %s.' % type(value).__name__)
        value = tuple([float(v) for v in value])
    return value

def normalizeRounding(value):
    """Normalizes rounding.

    Python 2 and Python 3 handing the rounding of halves (0.5, 1.5, etc)
    differently. This normalizes rounding to be the same (Python 3 style)
    in both environments.

    * **value** must be an :ref:`type-int-float`
    * Returned value is a ``int``"""
    if not isinstance(value, (int, float)):
        raise TypeError('Value to round must be an int or float, not %s.' % type(value).__name__)
    return round3(value)

def _get_version():
    """Fetches the version number from the package's __init__.py file"""
    with open('Lib/fontParts/__init__.py', 'r', encoding='utf-8') as f:
        for line in f:
            if line.startswith(u'__version__'):
                return ast.parse(line).body[0].value.s
        raise RuntimeError('No __version__ string found!')

def split_len(s, length):
    """split string *s* into list of strings no longer than *length*"""
    return [s[i:i + length] for i in range(0, len(s), length)]

def to_mixed_case(s):
    """convert upper snake case string to mixed case, e.g. MIXED_CASE becomes
    MixedCase"""
    out = ''
    last_c = ''
    for c in s:
        if c == '_':
            pass
        elif last_c in ('', '_'):
            out += c.upper()
        else:
            out += c.lower()
        last_c = c
    return out

def _child_list(element, child_tagname):
    """Return list containing the direct children of *element* having
    *child_tagname*."""
    xpath = './%s' % child_tagname
    return element.xpath(xpath, namespaces=nsmap)

def _required_attribute(element, name, default):
    """Add attribute with default value to element if it doesn't already exist."""
    if element.get(name) is None:
        element.set(name, default)

def _required_child(parent, tag):
    """Add child element with *tag* to *parent* if it doesn't already exist."""
    if _child(parent, tag) is None:
        parent.append(_Element(tag))

def pfxdtag(tag):
    """Return short-form prefixed tag from fully qualified (Clark notation)
    tagname."""
    uri, tagroot = tag[1:].split('}')
    prefix = reverse_nsmap[uri]
    return '%s:%s' % (prefix, tagroot)

def qtag(tag):
    """Return fully qualified (Clark notation) tagname corresponding to
    short-form prefixed tagname *tag*."""
    prefix, tagroot = tag.split(':')
    uri = nsmap[prefix]
    return '{%s}%s' % (uri, tagroot)

def _TableFactory(tag, stream, offset, length):
    """Return an instance of |Table| appropriate to *tag*, loaded from
    *font_file* with content of *length* starting at *offset*."""
    TableClass = {'head': _HeadTable, 'name': _NameTable}.get(tag, _BaseTable)
    return TableClass(tag, stream, offset, length)

def _SeriesFactory(ser):
    """Return an instance of the appropriate subclass of _BaseSeries based on the
    xChart element *ser* appears in."""
    xChart_tag = ser.getparent().tag
    try:
        SeriesCls = {qn('c:areaChart'): AreaSeries, qn('c:barChart'): BarSeries, qn('c:bubbleChart'): BubbleSeries, qn('c:doughnutChart'): PieSeries, qn('c:lineChart'): LineSeries, qn('c:pieChart'): PieSeries, qn('c:radarChart'): RadarSeries, qn('c:scatterChart'): XySeries}[xChart_tag]
    except KeyError:
        raise NotImplementedError('series class for %s not yet implemented' % xChart_tag)
    return SeriesCls(ser)

def namespaces(*prefixes):
    """Return a dict containing the subset namespace prefix mappings specified by
    *prefixes*. Any number of namespace prefixes can be supplied, e.g.
    namespaces('a', 'r', 'p')."""
    namespaces = {}
    for prefix in prefixes:
        namespaces[prefix] = _nsmap[prefix]
    return namespaces

def SeriesXmlRewriterFactory(chart_type, chart_data):
    """Return a |_BaseSeriesXmlRewriter| subclass appropriate to *chart_type*."""
    XL_CT = XL_CHART_TYPE
    RewriterCls = {XL_CT.BUBBLE: _BubbleSeriesXmlRewriter, XL_CT.BUBBLE_THREE_D_EFFECT: _BubbleSeriesXmlRewriter, XL_CT.XY_SCATTER: _XySeriesXmlRewriter, XL_CT.XY_SCATTER_LINES: _XySeriesXmlRewriter, XL_CT.XY_SCATTER_LINES_NO_MARKERS: _XySeriesXmlRewriter, XL_CT.XY_SCATTER_SMOOTH: _XySeriesXmlRewriter, XL_CT.XY_SCATTER_SMOOTH_NO_MARKERS: _XySeriesXmlRewriter}.get(chart_type, _CategorySeriesXmlRewriter)
    return RewriterCls(chart_data)

def to_unicode(text):
    """Return *text* as a unicode string. *text* can be a 7-bit ASCII string,
    a UTF-8 encoded 8-bit string, or unicode. String values are converted to
    unicode assuming UTF-8 encoding. Unicode values are returned unchanged."""
    if not isinstance(text, basestring):
        tmpl = 'expected UTF-8 encoded string or unicode, got %s value %s'
        raise TypeError(tmpl % (type(text), text))
    if isinstance(text, unicode):
        return text
    return unicode(text, 'utf-8')

def BaseShapeFactory(shape_elm, parent):
    """Return an instance of the appropriate shape proxy class for *shape_elm*."""
    tag = shape_elm.tag
    if tag == qn('p:pic'):
        videoFiles = shape_elm.xpath('./p:nvPicPr/p:nvPr/a:videoFile')
        if videoFiles:
            return Movie(shape_elm, parent)
        return Picture(shape_elm, parent)
    shape_cls = {qn('p:cxnSp'): Connector, qn('p:grpSp'): GroupShape, qn('p:sp'): Shape, qn('p:graphicFrame'): GraphicFrame}.get(tag, BaseShape)
    return shape_cls(shape_elm, parent)

def _LayoutShapeFactory(shape_elm, parent):
    """Return an instance of the appropriate shape proxy class for *shape_elm*
    on a slide layout."""
    tag_name = shape_elm.tag
    if tag_name == qn('p:sp') and shape_elm.has_ph_elm:
        return LayoutPlaceholder(shape_elm, parent)
    return BaseShapeFactory(shape_elm, parent)

def _MasterShapeFactory(shape_elm, parent):
    """Return an instance of the appropriate shape proxy class for *shape_elm*
    on a slide master."""
    tag_name = shape_elm.tag
    if tag_name == qn('p:sp') and shape_elm.has_ph_elm:
        return MasterPlaceholder(shape_elm, parent)
    return BaseShapeFactory(shape_elm, parent)

def _NotesSlideShapeFactory(shape_elm, parent):
    """Return an instance of the appropriate shape proxy class for *shape_elm*
    on a notes slide."""
    tag_name = shape_elm.tag
    if tag_name == qn('p:sp') and shape_elm.has_ph_elm:
        return NotesSlidePlaceholder(shape_elm, parent)
    return BaseShapeFactory(shape_elm, parent)

def _SlidePlaceholderFactory(shape_elm, parent):
    """Return a placeholder shape of the appropriate type for *shape_elm*."""
    tag = shape_elm.tag
    if tag == qn('p:sp'):
        Constructor = {PP_PLACEHOLDER.BITMAP: PicturePlaceholder, PP_PLACEHOLDER.CHART: ChartPlaceholder, PP_PLACEHOLDER.PICTURE: PicturePlaceholder, PP_PLACEHOLDER.TABLE: TablePlaceholder}.get(shape_elm.ph_type, SlidePlaceholder)
    elif tag == qn('p:graphicFrame'):
        Constructor = PlaceholderGraphicFrame
    elif tag == qn('p:pic'):
        Constructor = PlaceholderPicture
    else:
        Constructor = BaseShapeFactory
    return Constructor(shape_elm, parent)

def SlideShapeFactory(shape_elm, parent):
    """Return an instance of the appropriate shape proxy class for *shape_elm*
    on a slide."""
    if shape_elm.has_ph_elm:
        return _SlidePlaceholderFactory(shape_elm, parent)
    return BaseShapeFactory(shape_elm, parent)

def PlotFactory(xChart, chart):
    """Return an instance of the appropriate subclass of _BasePlot based on the
    tagname of *xChart*."""
    try:
        PlotCls = {qn('c:areaChart'): AreaPlot, qn('c:area3DChart'): Area3DPlot, qn('c:barChart'): BarPlot, qn('c:bubbleChart'): BubblePlot, qn('c:doughnutChart'): DoughnutPlot, qn('c:lineChart'): LinePlot, qn('c:pieChart'): PiePlot, qn('c:radarChart'): RadarPlot, qn('c:scatterChart'): XyPlot}[xChart.tag]
    except KeyError:
        raise ValueError('unsupported plot type %s' % xChart.tag)
    return PlotCls(xChart, chart)

def _default_pptx_path():
    """Return the path to the built-in default .pptx package."""
    _thisdir = os.path.split(__file__)[0]
    return os.path.join(_thisdir, 'templates', 'default.pptx')

def print_ldamodel_distribution(distrib, row_labels, val_labels, top_n=10):
    """Print `n_top` top values from a LDA model's distribution `distrib`. Can be used for topic-word distributions and
    document-topic distributions."""
    df_values = top_n_from_distribution(distrib, top_n=top_n, row_labels=row_labels, val_labels=None)
    df_labels = top_n_from_distribution(distrib, top_n=top_n, row_labels=row_labels, val_labels=val_labels)
    for i, (ind, row) in enumerate(df_labels.iterrows()):
        print(ind)
        for j, label in enumerate(row):
            val = df_values.iloc[i, j]
            print('> #%d. %s (%f)' % (j + 1, label, val))

def print_ldamodel_topic_words(topic_word_distrib, vocab, n_top=10, row_labels=DEFAULT_TOPIC_NAME_FMT):
    """Print `n_top` values from a LDA model's topic-word distributions."""
    print_ldamodel_distribution(topic_word_distrib, row_labels=row_labels, val_labels=vocab, top_n=n_top)

def print_ldamodel_doc_topics(doc_topic_distrib, doc_labels, n_top=3, val_labels=DEFAULT_TOPIC_NAME_FMT):
    """Print `n_top` values from a LDA model's document-topic distributions."""
    print_ldamodel_distribution(doc_topic_distrib, row_labels=doc_labels, val_labels=val_labels, top_n=n_top)

