        return pickle.load(f, **kwargs)

def simplified_pos(pos, tagset=None):
    """Return a simplified POS tag for a full POS tag `pos` belonging to a tagset `tagset`. By default the WordNet
    tagset is assumed.
    Does the following conversion by default:
    - all N... (noun) tags to 'N'
    - all V... (verb) tags to 'V'
    - all ADJ... (adjective) tags to 'ADJ'
    - all ADV... (adverb) tags to 'ADV'
    - all other to None
    Does the following conversion by with `tagset=='penn'`:
    - all N... (noun) tags to 'N'
    - all V... (verb) tags to 'V'
    - all JJ... (adjective) tags to 'ADJ'
    - all RB... (adverb) tags to 'ADV'
    - all other to None"""
    if tagset == 'penn':
        if pos.startswith('N') or pos.startswith('V'):
            return pos[0]
        elif pos.startswith('JJ'):
            return 'ADJ'
        elif pos.startswith('RB'):
            return 'ADV'
        else:
            return None
    elif pos.startswith('N') or pos.startswith('V'):
        return pos[0]
    elif pos.startswith('ADJ') or pos.startswith('ADV'):
        return pos[:3]
    else:
        return None

def mat2d_window_from_indices(mat, row_indices=None, col_indices=None, copy=False):
    """Select an area/"window" inside of a 2D array/matrix `mat` specified by either a sequence of
    row indices `row_indices` and/or a sequence of column indices `col_indices`.
    Returns the specified area as a *view* of the data if `copy` is False, else it will return a copy."""
    if not isinstance(mat, np.ndarray) or mat.ndim != 2:
        raise ValueError('`mat` must be a 2D NumPy array')
    if mat.shape[0] == 0 or mat.shape[1] == 0:
        raise ValueError('invalid shape for `mat`: %s' % mat.shape)
    if row_indices is None:
        row_indices = slice(None)
    elif len(row_indices) == 0:
        raise ValueError('`row_indices` must be non-empty')
    if col_indices is None:
        col_indices = slice(None)
    elif len(col_indices) == 0:
        raise ValueError('`col_indices` must be non-empty')
    view = mat[row_indices, :][:, col_indices]
    if copy:
        return view.copy()
    else:
        return view

def greedy_partitioning(elems_dict, k, return_only_labels=False):
    """Implementation of greed partitioning algorithm as explained in https://stackoverflow.com/a/6670011
    for a dict `elems_dict` containing elements with label -> weight mapping. The elements are placed in
    `k` bins such that the difference of sums of weights in each bin is minimized. The algorithm
    does not always find the optimal solution.
    If `return_only_labels` is False, returns a list of `k` dicts with label -> weight mapping,
    else returns a list of `k` lists containing only the labels."""
    if k <= 0:
        raise ValueError('`k` must be at least 1')
    elif k == 1:
        return elems_dict
    elif k >= len(elems_dict):
        if return_only_labels:
            return [[k] for k in elems_dict.keys()]
        else:
            return [{k: v} for k, v in elems_dict.items()]
    sorted_elems = sorted(elems_dict.items(), key=lambda x: x[1], reverse=True)
    bins = [[sorted_elems.pop(0)] for _ in range(k)]
    bin_sums = [sum((x[1] for x in b)) for b in bins]
    for pair in sorted_elems:
        argmin = min(enumerate(bin_sums), key=lambda x: x[1])[0]
        bins[argmin].append(pair)
        bin_sums[argmin] += pair[1]
    if return_only_labels:
        return [[x[1] for x in b] for b in bins]
    else:
        return [dict(b) for b in bins]

def token_match(pattern, tokens, match_type='exact', ignore_case=False, glob_method='match'):
    """Return a NumPy array signaling matches between `pattern` and `tokens`. `pattern` is a string that will be
    compared with each element in sequence `tokens` either as exact string equality (`match_type` is 'exact') or
    regular expression (`match_type` is 'regex') or glob pattern (`match_type` is 'glob')."""
    if match_type not in {'exact', 'regex', 'glob'}:
        raise ValueError("`match_type` must be one of `'exact', 'regex', 'glob'`")
    if not isinstance(tokens, np.ndarray):
        tokens = np.array(tokens)
    if match_type == 'exact':
        return np.char.lower(tokens) == pattern.lower() if ignore_case else tokens == pattern
    elif match_type == 'regex':
        if isinstance(pattern, str):
            pattern = re.compile(pattern, flags=re.IGNORECASE)
        vecmatch = np.vectorize(lambda x: bool(pattern.search(x)))
        return vecmatch(tokens)
    else:
        if glob_method not in {'search', 'match'}:
            raise ValueError("`glob_method` must be one of `'search', 'match'`")
        if isinstance(pattern, str):
            pattern = globre.compile(pattern, flags=re.IGNORECASE)
        if glob_method == 'search':
            vecmatch = np.vectorize(lambda x: bool(pattern.search(x)))
        else:
            vecmatch = np.vectorize(lambda x: bool(pattern.match(x)))
        return vecmatch(tokens)

def dyndoc_insert(src):
    """docstring_insert - a decorator to insert API-docparts dynamically."""
    import json
    import re
    def mkblock(d, flag=0):
        v = json.dumps(d, indent=2)
        if flag == 1:
            nw = re.findall('.*?\\[(.*)\\]', v, flags=re.S)
            v = nw[0]
        return '\n{}'.format(''.join(['{0:>16}{1}\n'.format('', L) for L in v.split('\n')]))
    def dec(obj):
        allSlots = re.findall('\\{(_v3.*?)\\}', obj.__doc__)
        docsub = {}
        sub = {}
        for k in allSlots:
            p = re.findall('^(_v3.*)_(.*)', k)
            p = list(*p)
            sub.update({p[1]: p[0]})
        for v in sub.values():
            for k in sub.keys():
                docsub['{}_url'.format(v)] = '{}'.format(src[v]['url'])
                if 'resp' == k:
                    docsub.update({'{}_resp'.format(v): mkblock(src[v]['response'])})
                if 'body' == k:
                    docsub.update({'{}_body'.format(v): mkblock(src[v]['body'])})
                if 'params' == k:
                    docsub.update({'{}_params'.format(v): mkblock(src[v]['params'])})
                if 'ciresp' == k:
                    docsub.update({'{}_ciresp'.format(v): mkblock(src[v]['response'], 1)})
        obj.__doc__ = obj.__doc__.format(**docsub)
        return obj
    return dec

def abstractclass(cls):
    """abstractclass - class decorator.

    make sure the class is abstract and cannot be used on it's own.

    @abstractclass
    class A(object):
        def __init__(self, *args, **kwargs):
            # logic
            pass

    class B(A):
        pass

    a = A()   # results in an AssertionError
    b = B()   # works fine"""
    setattr(cls, '_ISNEVER', cls.__bases__[0].__name__)
    origInit = cls.__dict__['__init__']
    def wrapInit(self, *args, **kwargs):
        try:
            assert self.__class__.__bases__[-1].__name__ != self._ISNEVER
            origInit(self, *args, **kwargs)
        except AssertionError:
            raise TypeError('Use of abstract base class')
    setattr(wrapInit, '__doc__', getattr(origInit, '__doc__'))
    setattr(origInit, '__doc__', '')
    setattr(cls, '__init__', wrapInit)
    return cls

def granularity_to_time(s):
    """convert a named granularity into seconds.

    get value in seconds for named granularities: M1, M5 ... H1 etc.

    >>> print(granularity_to_time("M5"))
    300"""
    mfact = {'S': 1, 'M': 60, 'H': 3600, 'D': 86400, 'W': 604800}
    try:
        f, n = re.match('(?P<f>[SMHDW])(?:(?P<n>\\d+)|)', s).groups()
        n = n if n else 1
        return mfact[f] * int(n)
    except Exception as e:
        raise ValueError(e)

def get_classes(modName):
    """return a list of all classes in a module."""
    classNames = []
    for name, obj in inspect.getmembers(sys.modules[modName]):
        if inspect.isclass(obj):
            classNames.append(name)
    return classNames

def _fix_integrity_error(f):
    """Ensure raising of IntegrityError on unique constraint violations.

    In earlier versions of hdbcli it doesn't raise the hdbcli.dbapi.IntegrityError
    exception for unique constraint violations. To support also older versions
    of hdbcli this decorator inspects the raised exception and will rewrite the
    exception based on HANA's error code."""
    @wraps(f)
    def wrapper(dialect, *args, **kwargs):
        try:
            return f(dialect, *args, **kwargs)
        except dialect.dbapi.Error as exc:
            if exc.errorcode == 301 and (not isinstance(exc, dialect.dbapi.IntegrityError)):
                raise dialect.dbapi.IntegrityError(exc)
            raise
    return wrapper

def pp_xml(body):
    """Pretty print format some XML so it's readable."""
    pretty = xml.dom.minidom.parseString(body)
    return pretty.toprettyxml(indent='  ')

def _return_value(content, ns):
    """Find the return value in a CIM response.

    The xmlns is needed because everything in CIM is a million levels
    of namespace indirection."""
    doc = ElementTree.fromstring(content)
    query = './/{%(ns)s}%(item)s' % {'ns': ns, 'item': 'ReturnValue'}
    rv = doc.find(query)
    return int(rv.text)

def loads(s, encoding=None, cls=None, object_hook=None, parse_float=None, parse_int=None, parse_constant=None, object_pairs_hook=None):
    """Deserialize ``s`` (a ``str`` or ``unicode`` instance containing a
    JSON5 document) to a Python object."""
    assert cls is None, 'Custom decoders are not supported'
    if sys.version_info[0] < 3:
        decodable_type = type('')
    else:
        decodable_type = type(b'')
    if isinstance(s, decodable_type):
        encoding = encoding or 'utf-8'
        s = s.decode(encoding)
    if not s:
        raise ValueError('Empty strings are not legal JSON5')
    parser = Parser(s, '<string>')
    ast, err, newpos = parser.parse()
    if err:
        raise ValueError(err)
    def _fp_constant_parser(s):
        return float(s.replace('Infinity', 'inf').replace('NaN', 'nan'))
    if object_pairs_hook:
        dictify = object_pairs_hook
    elif object_hook:
        dictify = lambda pairs: object_hook(dict(pairs))
    else:
        dictify = dict
    parse_float = parse_float or float
    parse_int = parse_int or int
    parse_constant = parse_constant or _fp_constant_parser
    return _walk_ast(ast, dictify, parse_float, parse_int, parse_constant)

def dumps(obj, **kwargs):
    """Serialize ``obj`` to a JSON5-formatted ``str``."""
    t = type(obj)
    if obj is True:
        return u'true'
    elif obj is False:
        return u'false'
    elif obj == None:
        return u'null'
    elif t == type('') or t == type(u''):
        single = "'" in obj
        double = '"' in obj
        if single and double:
            return json.dumps(obj)
        elif single:
            return '"' + obj + '"'
        else:
            return "'" + obj + "'"
    elif t is float or t is int:
        return str(obj)
    elif t is dict:
        return u'{' + u','.join([_dumpkey(k) + u':' + dumps(v) for k, v in obj.items()]) + '}'
    elif t is list:
        return u'[' + ','.join([dumps(el) for el in obj]) + u']'
    else:
        return u''

def _convert_py_number(value):
    """Convert a Python integer value into equivalent C object.
    Will attempt to use the smallest possible conversion, starting with int, then long
    then double."""
    try:
        return c_uamqp.int_value(value)
    except OverflowError:
        pass
    try:
        return c_uamqp.long_value(value)
    except OverflowError:
        pass
    return c_uamqp.double_value(value)

def quick_url(comment):
    """Return the URL for the comment without fetching its submission."""
    def to_id(fullname):
        return fullname.split('_', 1)[1]
    return 'http://www.reddit.com/r/{}/comments/{}/_/{}?context=3'.format(comment.subreddit.display_name, to_id(comment.link_id), comment.id)

def load_env_from_file(filename):
    """Read an env file into a collection of (name, value) tuples."""
    if not os.path.exists(filename):
        raise FileNotFoundError('Environment file {} does not exist.'.format(filename))
    with open(filename) as f:
        for lineno, line in enumerate(f):
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            if '=' not in line:
                raise SyntaxError('Invalid environment file syntax in {} at line {}.'.format(filename, lineno + 1))
            name, value = parse_var(line)
            yield (name, value)

def _open_url(url):
    """Open a HTTP connection to the URL and return a file-like object."""
    response = requests.get(url, stream=True)
    if response.status_code != 200:
        raise IOError('Unable to download {}, HTTP {}'.format(url, response.status_code))
    return response

def _parse_option(option):
    """Parse a 'key=val' option string into a python (key, val) pair

    :param option: str
    :return: tuple"""
    try:
        key, val = option.split('=', 1)
    except ValueError:
        return (option, True)
    try:
        val = json.loads(val)
    except json.JSONDecodeError:
        pass
    return (key, val)

def _resolve_transformations(transformations):
    """Resolve a collection of strings into the matching python objects, defaulting to bonobo namespace if no package is provided.

    Syntax for each string is path.to.package:attribute

    :param transformations: tuple(str)
    :return: tuple(object)"""
    registry = _ModulesRegistry()
    transformations = transformations or []
    for t in transformations:
        try:
            mod, attr = t.split(':', 1)
            yield getattr(registry.require(mod), attr)
        except ValueError:
            yield getattr(bonobo, t)

def OrderFields(fields):
    """Transformation factory to reorder fields in a data stream.

    :param fields:
    :return: callable"""
    fields = list(fields)
    @use_context
    @use_raw_input
    def _OrderFields(context, row):
        nonlocal fields
        context.setdefault('remaining', None)
        if not context.output_type:
            context.remaining = list(sorted(set(context.get_input_fields()) - set(fields)))
            context.set_output_fields(fields + context.remaining)
        yield tuple((row.get(field) for field in context.get_output_fields()))
    return _OrderFields

def SetFields(fields):
    """Transformation factory that sets the field names on first iteration, without touching the values.

    :param fields:
    :return: callable"""
    @use_context
    @use_no_input
    def _SetFields(context):
        nonlocal fields
        if not context.output_type:
            context.set_output_fields(fields)
        return NOT_MODIFIED
    return _SetFields

def UnpackItems(*items, fields=None, defaults=None):
    """>>> UnpackItems(0)

    :param items:
    :param fields:
    :param defaults:
    :return: callable"""
    defaults = defaults or {}
    @use_context
    @use_raw_input
    def _UnpackItems(context, bag):
        nonlocal fields, items, defaults
        if fields is None:
            fields = ()
            for item in items:
                fields += tuple(bag[item].keys())
            context.set_output_fields(fields)
        values = ()
        for item in items:
            values += tuple((bag[item].get(field, defaults.get(field)) for field in fields))
        return values
    return _UnpackItems

def MapFields(function, key=True):
    """Transformation factory that maps `function` on the values of a row.
    It can be applied either to
    1. all columns (`key=True`),
    2. no column (`key=False`), or
    3. a subset of columns by passing a callable, which takes column name and returns `bool`
     (same as the parameter `function` in `filter`).

    :param function: callable
    :param key: bool or callable
    :return: callable"""
    @use_raw_input
    def _MapFields(bag):
        try:
            factory = type(bag)._make
        except AttributeError:
            factory = type(bag)
        if callable(key):
            try:
                fields = bag._fields
            except AttributeError as e:
                raise UnrecoverableAttributeError('This transformation works only on objects with named fields (namedtuple, BagType, ...).') from e
            return factory((function(value) if key(key_) else value for key_, value in zip(fields, bag)))
        elif key:
            return factory((function(value) for value in bag))
        else:
            return NOT_MODIFIED
    return _MapFields

def split_token(output):
    """Split an output into token tuple, real output tuple.

    :param output:
    :return: tuple, tuple"""
    output = ensure_tuple(output)
    flags, i, len_output, data_allowed = (set(), 0, len(output), True)
    while i < len_output and isflag(output[i]):
        if output[i].must_be_first and i:
            raise ValueError('{} flag must be first.'.format(output[i]))
        if i and output[i - 1].must_be_last:
            raise ValueError('{} flag must be last.'.format(output[i - 1]))
        if output[i] in flags:
            raise ValueError('Duplicate flag {}.'.format(output[i]))
        flags.add(output[i])
        data_allowed &= output[i].allows_data
        i += 1
    output = output[i:]
    if not data_allowed and len(output):
        raise ValueError('Output data provided after a flag that does not allow data.')
    return (flags, output)

def create_strategy(name=None):
    """Create a strategy, or just returns it if it's already one.

    :param name:
    :return: Strategy"""
    import logging
    from bonobo.execution.strategies.base import Strategy
    if isinstance(name, Strategy):
        return name
    if name is None:
        name = DEFAULT_STRATEGY
    logging.debug('Creating execution strategy {!r}...'.format(name))
    try:
        factory = STRATEGIES[name]
    except KeyError as exc:
        raise RuntimeError('Invalid strategy {}. Available choices: {}.'.format(repr(name), ', '.join(sorted(STRATEGIES.keys())))) from exc
    return factory()

def isconfigurabletype(mixed, *, strict=False):
    """Check if the given argument is an instance of :class:`bonobo.config.ConfigurableMeta`, meaning it has all the
    plumbery necessary to build :class:`bonobo.config.Configurable`-like instances.

    :param mixed:
    :param strict: should we consider partially configured objects?
    :return: bool"""
    from bonobo.config.configurables import ConfigurableMeta, PartiallyConfigured
    if isinstance(mixed, ConfigurableMeta):
        return True
    if strict:
        return False
    if isinstance(mixed, PartiallyConfigured):
        return True
    if hasattr(mixed, '_partial') and mixed._partial:
        return True
    return False

def inspect_node(mixed, *, _partial=None):
    """If the given argument is somehow a :class:`bonobo.config.Configurable` object (either a subclass, an instance, or
    a partially configured instance), then it will return a :class:`ConfigurableInspection` namedtuple, used to inspect
    the configurable metadata (options). If you want to get the option values, you don't need this, it is only usefull
    to perform introspection on a configurable.

    If it's not looking like a configurable, it will raise a :class:`TypeError`.

    :param mixed:
    :return: ConfigurableInspection

    :raise: TypeError"""
    if isconfigurabletype(mixed, strict=True):
        inst, typ = (None, mixed)
    elif isconfigurable(mixed):
        inst, typ = (mixed, type(mixed))
    elif hasattr(mixed, 'func'):
        return inspect_node(mixed.func, _partial=(mixed.args, mixed.keywords))
    else:
        raise TypeError('Not a Configurable, nor a Configurable instance and not even a partially configured Configurable. Check your inputs.')
    return ConfigurableInspection(typ, inst, list(typ.__options__), list(typ.__processors__), _partial)

