def create_or_update(model, *, defaults=None, save=True, **kwargs):
    """Create or update a django model instance.

    :param model:
    :param defaults:
    :param kwargs:
    :return: object, created, updated"""
    obj, created = model._default_manager.get_or_create(defaults=defaults, **kwargs)
    updated = False
    if not created:
        if defaults:
            for k, v in defaults.items():
                if getattr(obj, k) != v:
                    setattr(obj, k, v)
                    updated = True
        if updated and save:
            obj.save()
    return (obj, created, updated)

def ensure_tuple(tuple_or_mixed, *, cls=None):
    """If it's not a tuple, let's make a tuple of one item.
    Otherwise, not changed.

    :param tuple_or_mixed:
    :return: tuple"""
    if cls is None:
        cls = tuple
    if isinstance(tuple_or_mixed, cls):
        return tuple_or_mixed
    if tuple_or_mixed is None:
        return tuple.__new__(cls, ())
    if isinstance(tuple_or_mixed, tuple):
        return tuple.__new__(cls, tuple_or_mixed)
    return tuple.__new__(cls, (tuple_or_mixed,))

def is_authenticated(user):
    """Return whether or not a User is authenticated.

    Function provides compatibility following deprecation of method call to
    `is_authenticated()` in Django 2.0.

    This is *only* required to support Django < v1.10 (i.e. v1.9 and earlier),
    as `is_authenticated` was introduced as a property in v1.10.s"""
    if not hasattr(user, 'is_authenticated'):
        return False
    if callable(user.is_authenticated):
        return user.is_authenticated()
    else:
        return user.is_authenticated

def log_update(sender, instance, **kwargs):
    """Signal receiver that creates a log entry when a model instance is changed and saved to the database.

    Direct use is discouraged, connect your model through :py:func:`auditlog.registry.register` instead."""
    if instance.pk is not None:
        try:
            old = sender.objects.get(pk=instance.pk)
        except sender.DoesNotExist:
            pass
        else:
            new = instance
            changes = model_instance_diff(old, new)
            if changes:
                log_entry = LogEntry.objects.log_create(instance, action=LogEntry.Action.UPDATE, changes=json.dumps(changes))

def log_delete(sender, instance, **kwargs):
    """Signal receiver that creates a log entry when a model instance is deleted from the database.

    Direct use is discouraged, connect your model through :py:func:`auditlog.registry.register` instead."""
    if instance.pk is not None:
        changes = model_instance_diff(instance, None)
        log_entry = LogEntry.objects.log_create(instance, action=LogEntry.Action.DELETE, changes=json.dumps(changes))

