def get_barcode_read_id(read, cell_barcode=False, sep='_'):
    """extract the umi +/- cell barcode from the read id using the
    specified separator"""
    try:
        if cell_barcode:
            umi = read.qname.split(sep)[-1].encode('utf-8')
            cell = read.qname.split(sep)[-2].encode('utf-8')
        else:
            umi = read.qname.split(sep)[-1].encode('utf-8')
            cell = None
        return (umi, cell)
    except:
        raise ValueError('Could not extract UMI +/- cell barcode from the readID, please check UMI is encoded in the read name')

def get_barcode_tag(read, cell_barcode=False, umi_tag='RX', cell_tag=None, umi_tag_split=None, umi_tag_delim=None, cell_tag_split='-', cell_tag_delim=None):
    """extract the umi +/- cell barcode from the specified tag"""
    try:
        if cell_barcode:
            umi = read.get_tag(umi_tag)
            cell = read.get_tag(cell_tag)
        else:
            umi = read.get_tag(umi_tag)
            cell = None
        if umi_tag_split:
            umi = umi.split(umi_tag_split)[0]
        if umi_tag_delim:
            umi = ''.join(umi.split(umi_tag_delim))
        if cell and cell_tag_split:
            cell = cell.split(cell_tag_split)[0]
        if cell and cell_tag_delim:
            cell = ''.join(cell.split(cell_tag_delim))
        if cell:
            cell = cell.encode('utf-8')
        return (umi.encode('utf-8'), cell)
    except IndexError:
        raise ValueError('Could not extract UMI +/- cell barcode from the read tag')

def get_cell_umi_read_string(read_id, sep='_'):
    """extract the umi and cell barcode from the read id (input as a
    string) using the specified separator"""
    try:
        return (read_id.split(sep)[-1].encode('utf-8'), read_id.split(sep)[-2].encode('utf-8'))
    except IndexError:
        raise ValueError('Could not extract UMI or CB from the read ID, pleasecheck UMI and CB are encoded in the read name:%s' % read_id)

def get_barcode_umis(read, cell_barcode=False):
    """extract the umi +/- cell barcode from the read name where the barcodes
    were extracted using umis"""
    umi, cell = (None, None)
    try:
        read_name_elements = read.qname.split(':')
        for element in read_name_elements:
            if element.startswith('UMI_'):
                umi = element[4:].encode('utf-8')
            elif element.startswith('CELL_') and cell_barcode:
                cell = element[5:].encode('utf-8')
        if umi is None:
            raise ValueError()
        return (umi, cell)
    except:
        raise ValueError('Could not extract UMI +/- cell barcode from the read tag')

def metafetcher(bamfile, metacontig2contig, metatag):
    """return reads in order of metacontigs"""
    for metacontig in metacontig2contig:
        for contig in metacontig2contig[metacontig]:
            for read in bamfile.fetch(contig):
                read.set_tag(metatag, metacontig)
                yield read

def find_splice(cigar):
    """Takes a cigar string and finds the first splice position as
    an offset from the start. To find the 5' end (read coords) of
    the junction for a reverse read, pass in the reversed cigar tuple"""
    offset = 0
    if cigar[0][0] == 4:
        offset = cigar[0][1]
        cigar = cigar[1:]
    for op, bases in cigar:
        if op in (3, 4):
            return offset
        elif op in (0, 2, 7, 8):
            offset += bases
        elif op in (1, 5, 6):
            continue
        else:
            raise ValueError('Bad Cigar operation: %i' % op)
    return False

def get_read_position(read, soft_clip_threshold):
    """get the read position (taking account of clipping)"""
    is_spliced = False
    if read.is_reverse:
        pos = read.aend
        if read.cigar[-1][0] == 4:
            pos = pos + read.cigar[-1][1]
        start = read.pos
        if 'N' in read.cigarstring or (read.cigar[0][0] == 4 and read.cigar[0][1] > soft_clip_threshold):
            cigar = read.cigar[::-1]
            is_spliced = find_splice(cigar)
    else:
        pos = read.pos
        if read.cigar[0][0] == 4:
            pos = pos - read.cigar[0][1]
        start = pos
        if 'N' in read.cigarstring or (read.cigar[-1][0] == 4 and read.cigar[-1][1] > soft_clip_threshold):
            is_spliced = find_splice(read.cigar)
    return (start, pos, is_spliced)

def getErrorCorrectMapping(cell_barcodes, whitelist, threshold=1):
    """Find the mappings between true and false cell barcodes based
    on an edit distance threshold.

    Any cell barcode within the threshold to more than one whitelist
    barcode will be excluded"""
    true_to_false = collections.defaultdict(set)
    whitelist = set([str(x).encode('utf-8') for x in whitelist])
    for cell_barcode in cell_barcodes:
        match = None
        barcode_in_bytes = str(cell_barcode).encode('utf-8')
        for white_cell in whitelist:
            if barcode_in_bytes in whitelist:
                continue
            if edit_distance(barcode_in_bytes, white_cell) <= threshold:
                if match is not None:
                    match = None
                    break
                else:
                    match = white_cell.decode('utf-8')
        if match is not None:
            true_to_false[match].add(cell_barcode)
    return true_to_false

def checkError(barcode, whitelist, errors=1):
    """Check for errors (substitutions, insertions, deletions) between a barcode
    and a set of whitelist barcodes.

    Returns the whitelist barcodes which match the input barcode
    allowing for errors. Returns as soon as two are identified."""
    near_matches = []
    comp_regex = regex.compile('(%s){e<=%i}' % (barcode, errors))
    b_length = len(barcode)
    for whitelisted_barcode in whitelist:
        w_length = len(whitelisted_barcode)
        if barcode == whitelisted_barcode:
            continue
        if max(b_length, w_length) > min(b_length, w_length) + errors:
            continue
        if comp_regex.match(whitelisted_barcode):
            near_matches.append(whitelisted_barcode)
            if len(near_matches) > 1:
                return near_matches
    return near_matches

def fastqIterate(infile):
    """iterate over contents of fastq file."""
    def convert2string(b):
        if type(b) == str:
            return b
        else:
            return b.decode('utf-8')
    while 1:
        line1 = convert2string(infile.readline())
        if not line1:
            break
        if not line1.startswith('@'):
            U.error("parsing error: expected '@' in line %s" % line1)
        line2 = convert2string(infile.readline())
        line3 = convert2string(infile.readline())
        if not line3.startswith('+'):
            U.error("parsing error: expected '+' in line %s" % line3)
        line4 = convert2string(infile.readline())
        if not line4:
            U.error('incomplete entry for %s' % line1)
        yield Record(line1[1:-1], line2[:-1], line4[:-1])

def addBarcodesToIdentifier(read, UMI, cell):
    """extract the identifier from a read and append the UMI and
    cell barcode before the first space"""
    read_id = read.identifier.split(' ')
    if cell == '':
        read_id[0] = read_id[0] + '_' + UMI
    else:
        read_id[0] = read_id[0] + '_' + cell + '_' + UMI
    identifier = ' '.join(read_id)
    return identifier

def extractSeqAndQuals(seq, quals, umi_bases, cell_bases, discard_bases, retain_umi=False):
    """Remove selected bases from seq and quals
    """
    new_seq = ''
    new_quals = ''
    umi_quals = ''
    cell_quals = ''
    ix = 0
    for base, qual in zip(seq, quals):
        if ix not in discard_bases and ix not in cell_bases:
            if retain_umi:
                new_quals += qual
                new_seq += base
                umi_quals += qual
            elif ix not in umi_bases:
                new_quals += qual
                new_seq += base
            else:
                umi_quals += qual
        elif ix in cell_bases:
            cell_quals += qual
        ix += 1
    return (new_seq, new_quals, umi_quals, cell_quals)

def umi_below_threshold(umi_quals, quality_encoding, quality_filter_threshold):
    """return true if any of the umi quals is below the threshold"""
    below_threshold = get_below_threshold(umi_quals, quality_encoding, quality_filter_threshold)
    return any(below_threshold)

def mask_umi(umi, umi_quals, quality_encoding, quality_filter_threshold):
    '''Mask all positions where quals < threshold with "N"'''
    below_threshold = get_below_threshold(umi_quals, quality_encoding, quality_filter_threshold)
    new_umi = ''
    for base, test in zip(umi, below_threshold):
        if test:
            new_umi += 'N'
        else:
            new_umi += base
    return new_umi

def detect_bam_features(bamfile, n_entries=1000):
    """read the first n entries in the bam file and identify the tags
    available detecting multimapping"""
    inbam = pysam.Samfile(bamfile)
    inbam = inbam.fetch(until_eof=True)
    tags = ['NH', 'X0', 'XT']
    available_tags = {x: 1 for x in tags}
    for n, read in enumerate(inbam):
        if n > n_entries:
            break
        if read.is_unmapped:
            continue
        else:
            for tag in tags:
                if not read.has_tag(tag):
                    available_tags[tag] = 0
    return available_tags

def istriu(am):
    """Returns ``True`` is the sparse adjacency matrix is upper triangular"""
    if am.shape[0] != am.shape[1]:
        print('Matrix is not square, triangularity is irrelevant')
        return False
    if am.format != 'coo':
        am = am.tocoo(copy=False)
    return sp.all(am.row <= am.col)

def istriangular(am):
    """Returns ``True`` is the sparse adjacency matrix is either upper or lower
    triangular"""
    if am.format != 'coo':
        am = am.tocoo(copy=False)
    return istril(am) or istriu(am)

def issymmetric(am):
    """A method to check if a square matrix is symmetric
    Returns ``True`` if the sparse adjacency matrix is symmetric"""
    if am.shape[0] != am.shape[1]:
        logger.warning('Matrix is not square, symmetrical is irrelevant')
        return False
    if am.format != 'coo':
        am = am.tocoo(copy=False)
    if istril(am) or istriu(am):
        return False
    sym = (am != am.T).size == 0
    return sym

def im_to_am(im):
    """Convert an incidence matrix into an adjacency matrix"""
    if im.shape[0] == im.shape[1]:
        print('Warning: Received matrix is square which is unlikely')
    if im.shape[0] > im.shape[1]:
        print('Warning: Received matrix has more sites than bonds')
    if im.format != 'coo':
        im = im.tocoo(copy=False)

def _get_key_props(phase=None, diameter='throat.diameter', surface_tension='pore.surface_tension', contact_angle='pore.contact_angle'):
    """Many of the methods are generic to pores and throats. Some information may
    be stored on either the pore or throat and needs to be interpolated.
    This is a helper method to return the properties in the correct format.
    To do:
        Check for method to convert throat to pore data"""
    element = diameter.split('.')[0]
    if element == 'pore':
        if 'throat' in surface_tension:
            sigma = phase.interpolate_data(propname=surface_tension)
        else:
            sigma = phase[surface_tension]
        if 'throat' in contact_angle:
            theta = phase.interpolate_data(propname=contact_angle)
        else:
            theta = phase[contact_angle]
    if element == 'throat':
        if 'pore' in surface_tension:
            sigma = phase.interpolate_data(propname=surface_tension)
        else:
            sigma = phase[surface_tension]
        if 'pore' in contact_angle:
            theta = phase.interpolate_data(propname=contact_angle)
        else:
            theta = phase[contact_angle]
    return (element, sigma, theta)

def unique_list(input_list):
    """For a given list (of points) remove any duplicates"""
    output_list = []
    if len(input_list) > 0:
        dim = _sp.shape(input_list)[1]
        for i in input_list:
            match = False
            for j in output_list:
                if dim == 3:
                    if i[0] == j[0] and i[1] == j[1] and (i[2] == j[2]):
                        match = True
                elif dim == 2:
                    if i[0] == j[0] and i[1] == j[1]:
                        match = True
                elif dim == 1:
                    if i[0] == j[0]:
                        match = True
            if match is False:
                output_list.append(i)
    return output_list

def flat_list(input_list):
    """Given a list of nested lists of arbitrary depth, returns a single level or
    'flat' list."""
    x = input_list
    if isinstance(x, list):
        return [a for i in x for a in flat_list(i)]
    else:
        return [x]

def sanitize_dict(input_dict):
    """Given a nested dictionary, ensures that all nested dicts are normal
    Python dicts.  This is necessary for pickling, or just converting
    an 'auto-vivifying' dict to something that acts normal."""
    plain_dict = dict()
    for key in input_dict.keys():
        value = input_dict[key]
        if hasattr(value, 'keys'):
            plain_dict[key] = sanitize_dict(value)
        else:
            plain_dict[key] = value
    return plain_dict

def conduit_lengths(network, throats=None, mode='pore'):
    """Return the respective lengths of the conduit components defined by the throat
    conns P1 T P2
    mode = 'pore' - uses pore coordinates
    mode = 'centroid' uses pore and throat centroids"""
    if throats is None:
        throats = network.throats()
    Ps = network['throat.conns']
    pdia = network['pore.diameter']
    if mode == 'centroid':
        try:
            pcentroids = network['pore.centroid']
            tcentroids = network['throat.centroid']
            if _sp.sum(_sp.isnan(pcentroids)) + _sp.sum(_sp.isnan(tcentroids)) > 0:
                mode = 'pore'
            else:
                plen1 = _sp.sqrt(_sp.sum(_sp.square(pcentroids[Ps[:, 0]] - tcentroids), 1)) - network['throat.length'] / 2
                plen2 = _sp.sqrt(_sp.sum(_sp.square(pcentroids[Ps[:, 1]] - tcentroids), 1)) - network['throat.length'] / 2
        except KeyError:
            mode = 'pore'
    if mode == 'pore':
        pcoords = network['pore.coords']
        lengths = _sp.sqrt(_sp.sum(_sp.square(pcoords[Ps[:, 0]] - pcoords[Ps[:, 1]]), 1)) - network['throat.length']
        lengths[lengths < 0.0] = 2e-09
        try:
            fractions = pdia[Ps[:, 0]] / (pdia[Ps[:, 0]] + pdia[Ps[:, 1]])
        except:
            fractions = 0.5
        plen1 = lengths * fractions
        plen2 = lengths * (1 - fractions)
    return _sp.vstack((plen1, network['throat.length'], plen2)).T[throats]

def get_time_offset():
    """Get time offset from steam server time via WebAPI

    :return: time offset (``None`` when Steam WebAPI fails to respond)
    :rtype: :class:`int`, :class:`None`"""
    try:
        resp = webapi.post('ITwoFactorService', 'QueryTime', 1, params={'http_timeout': 10})
    except:
        return None
    ts = int(time())
    return int(resp.get('response', {}).get('server_time', ts)) - ts

def proto_to_dict(message):
    """Converts protobuf message instance to dict

    :param message: protobuf message instance
    :return: parameters and their values
    :rtype: dict
    :raises: :class:`.TypeError` if ``message`` is not a proto message"""
    if not isinstance(message, _ProtoMessageType):
        raise TypeError('Expected `message` to be a instance of protobuf message')
    data = {}
    for desc, field in message.ListFields():
        if desc.type == desc.TYPE_MESSAGE:
            if desc.label == desc.LABEL_REPEATED:
                data[desc.name] = list(map(proto_to_dict, field))
            else:
                data[desc.name] = proto_to_dict(field)
        else:
            data[desc.name] = list(field) if desc.label == desc.LABEL_REPEATED else field
    return data

def steam3_to_tuple(value):
    """:param value: steam3 (e.g. ``[U:1:1234]``)
    :type value: :class:`str`
    :return: (accountid, type, universe, instance)
    :rtype: :class:`tuple` or :class:`None`"""
    match = re.match('^\\[(?P<type>[i%s]):(?P<universe>[0-4]):(?P<id>\\d{1,10})(:(?P<instance>\\d+))?\\]$' % ETypeChars, value)
    if not match:
        return None
    steam32 = int(match.group('id'))
    universe = EUniverse(int(match.group('universe')))
    typechar = match.group('type').replace('i', 'I')
    etype = EType(ETypeChar[typechar])
    instance = match.group('instance')
    if typechar in 'gT':
        instance = 0
    elif instance is not None:
        instance = int(instance)
    elif typechar == 'L':
        instance = EInstanceFlag.Lobby
    elif typechar == 'c':
        instance = EInstanceFlag.Clan
    elif etype in (EType.Individual, EType.GameServer):
        instance = 1
    else:
        instance = 0
    instance = int(instance)
    return (steam32, etype, universe, instance)

def get_cmsg(emsg):
    """Get protobuf for a given EMsg

    :param emsg: EMsg
    :type emsg: :class:`steam.enums.emsg.EMsg`, :class:`int`
    :return: protobuf message"""
    if not isinstance(emsg, EMsg):
        emsg = EMsg(emsg)
    if emsg in cmsg_lookup_predefined:
        return cmsg_lookup_predefined[emsg]
    else:
        enum_name = emsg.name.lower()
        if enum_name.startswith('econ'):
            enum_name = enum_name[4:]
        cmsg_name = 'cmsg' + enum_name
    return cmsg_lookup.get(cmsg_name, None)

def xisabs(filename):
    """Cross-platform version of `os.path.isabs()`
    Returns True if `filename` is absolute on
    Linux, OS X or Windows."""
    if filename.startswith(b'/'):
        return True
    elif filename.startswith(b'\\'):
        return True
    elif re.match(b'\\w:[\\\\/]', filename):
        return True
    return False

def xnormpath(path):
    """Cross-platform version of os.path.normpath"""
    normalized = posixpath.normpath(path).replace(b'\\', b'/')
    return posixpath.normpath(normalized)

def xstrip(filename):
    """Make relative path out of absolute by stripping
    prefixes used on Linux, OS X and Windows.

    This function is critical for security."""
    while xisabs(filename):
        if re.match(b'\\w:[\\\\/]', filename):
            filename = re.sub(b'^\\w+:[\\\\/]+', b'', filename)
        elif re.match(b'[\\\\/]', filename):
            filename = re.sub(b'^[\\\\/]+', b'', filename)
    return filename

def pathstrip(path, n):
    """Strip n leading components from the given path"""
    pathlist = [path]
    while os.path.dirname(pathlist[0]) != b'':
        pathlist[0:1] = os.path.split(pathlist[0])
    return b'/'.join(pathlist[n:])

def get_binary_path(executable, logging_level='INFO'):
    """Gets the software name and returns the path of the binary."""
    if sys.platform == 'win32':
        if executable == 'start':
            return executable
        executable = executable + '.exe'
        if executable in os.listdir('.'):
            binary = os.path.join(os.getcwd(), executable)
        else:
            binary = next((os.path.join(path, executable) for path in os.environ['PATH'].split(os.pathsep) if os.path.isfile(os.path.join(path, executable))), None)
    else:
        venv_parent = get_venv_parent_path()
        venv_bin_path = os.path.join(venv_parent, '.venv', 'bin')
        if not venv_bin_path in os.environ.get('PATH'):
            if logging_level == 'DEBUG':
                print(f'Adding path {venv_bin_path} to environment PATH variable')
            os.environ['PATH'] = os.pathsep.join([os.environ['PATH'], venv_bin_path])
        binary = shutil.which(executable)
    return binary if binary else None

def check_in(request, action):
    """This function checks for missing properties in the request dict
    for the corresponding action."""
    if not request:
        req_str = ''
        for idx, val in enumerate(actions[action]):
            req_str += '\n' + val
        erstr = 'Provide a request dict with the following properties: %s' % req_str
        raise ValueError(erstr)
    required_fields = actions[action]
    missing = []
    for field in required_fields:
        if not is_key_present(request, field):
            missing.append(field)
    if missing:
        missing_string = ''
        for idx, val in enumerate(missing):
            missing_string += '\n' + val
        erstr = 'Provide the required request parameters to complete this request: %s' % missing_string
        raise ValueError(erstr)
    return True

def round_to_n(x, n):
    """Round to sig figs"""
    return round(x, -int(np.floor(np.log10(x))) + (n - 1))

def sharey(axes):
    """Shared axes limits without shared locators, ticks, etc.

    By Joe Kington"""
    linker = Linker(axes)
    for ax in axes:
        ax._linker = linker

def fix_ticks(ax):
    """Center ticklabels and hide any outside axes limits.

    By Joe Kington"""
    plt.setp(ax.get_yticklabels(), ha='center', x=0.5, transform=ax._yaxis_transform)
    limits = ax.get_ylim()
    for label, loc in zip(ax.yaxis.get_ticklabels(), ax.yaxis.get_ticklocs()):
        if loc < min(limits) or loc > max(limits):
            label.set(visible=False)
        else:
            label.set(visible=True)

def parabolic(f, x):
    """Interpolation. From ageobot, from somewhere else."""
    xv = 1 / 2.0 * (f[x - 1] - f[x + 1]) / (f[x - 1] - 2 * f[x] + f[x + 1]) + x
    yv = f[x] - 1 / 4.0 * (f[x - 1] - f[x + 1]) * (xv - x)
    return (xv, yv)

def get_lines(handle, line):
    """Get zero-indexed line from an open file-like."""
    for i, l in enumerate(handle):
        if i == line:
            return l

def find_file(pattern, path):
    """A bit like grep. Finds a pattern, looking in path. Returns the filename."""
    for fname in glob.iglob(path):
        with open(fname) as f:
            if re.search(pattern, f.read()):
                return fname
    return

def write_row(dictionary, card, log):
    """Processes a single row from the file."""
    rowhdr = {'card': card, 'log': log}
    row = [' '] * 80
    for e in ['log', 'card']:
        strt, stop, item = _put_field(cols(0), e, rowhdr[e])
        if item is not None:
            row[strt:stop] = list(item)
    for field in cols(card):
        strt, stop, item = _put_field(cols(card), field, dictionary.get(field))
        if item is not None:
            row[strt:stop] = list(item)
    return ''.join(row) + '\n'

def no_gaps(curve):
    """Check for gaps, after ignoring any NaNs at the top and bottom."""
    tnt = utils.top_and_tail(curve)
    return not any(np.isnan(tnt))

def no_spikes(tolerance):
    """Arg ``tolerance`` is the number of spiky samples allowed."""
    def no_spikes(curve):
        diff = np.abs(curve - curve.despike())
        return np.count_nonzero(diff) < tolerance
    return no_spikes

def fraction_not_nans(curve):
    """Returns the fraction of the curve extents that are good (non-nan data)."""
    return 1 - len(np.extract(np.isnan(curve), curve)) / len(curve)

def similarity_by_path(sense1: 'wn.Synset', sense2: 'wn.Synset', option: str='path') -> float:
    """Returns maximum path similarity between two senses.

    :param sense1: A synset.
    :param sense2: A synset.
    :param option: String, one of ('path', 'wup', 'lch').
    :return: A float, similarity measurement."""
    if option.lower() in ['path', 'path_similarity']:
        return max(wn.path_similarity(sense1, sense2, if_none_return=0), wn.path_similarity(sense2, sense1, if_none_return=0))
    elif option.lower() in ['wup', 'wupa', 'wu-palmer', 'wu-palmer']:
        return max(wn.wup_similarity(sense1, sense2, if_none_return=0), wn.wup_similarity(sense2, sense1, if_none_return=0))
    elif option.lower() in ['lch', 'leacock-chordorow']:
        if sense1.pos != sense2.pos:
            return 0
        return wn.lch_similarity(sense1, sense2, if_none_return=0)

def similarity_by_infocontent(sense1: 'wn.Synset', sense2: 'wn.Synset', option: str) -> float:
    """Returns similarity scores by information content.

    :param sense1: A synset.
    :param sense2: A synset.
    :param option: String, one of ('res', 'jcn', 'lin').
    :return: A float, similarity measurement."""
    if sense1.pos != sense2.pos:
        return 0
    if option in ['res', 'resnik']:
        if sense1.pos not in wnic_bnc_resnik_add1.ic:
            return 0
        return wn.res_similarity(sense1, sense2, wnic_bnc_resnik_add1)
    elif option in ['jcn', 'jiang-conrath']:
        if sense1.pos not in wnic_bnc_add1.ic:
            return 0
        return wn.jcn_similarity(sense1, sense2, wnic_bnc_add1)
    elif option in ['lin']:
        if sense1.pos not in wnic_bnc_add1.ic:
            return 0
        return wn.lin_similarity(sense1, sense2, wnic_bnc_add1)

def sim(sense1: 'wn.Synset', sense2: 'wn.Synset', option: str='path') -> float:
    """Calculates similarity based on user's choice.

    :param sense1: A synset.
    :param sense2: A synset.
    :param option: String, one of ('path', 'wup', 'lch', 'res', 'jcn', 'lin').
    :return: A float, similarity measurement."""
    option = option.lower()
    if option.lower() in ['path', 'path_similarity', 'wup', 'wupa', 'wu-palmer', 'wu-palmer', 'lch', 'leacock-chordorow']:
        return similarity_by_path(sense1, sense2, option)
    elif option.lower() in ['res', 'resnik', 'jcn', 'jiang-conrath', 'lin']:
        return similarity_by_infocontent(sense1, sense2, option)

def max_similarity(context_sentence: str, ambiguous_word: str, option='path', lemma=True, context_is_lemmatized=False, pos=None, best=True) -> 'wn.Synset':
    """Perform WSD by maximizing the sum of maximum similarity between possible
    synsets of all words in the context sentence and the possible synsets of the
    ambiguous words (see http://goo.gl/XMq2BI):
    {argmax}_{synset(a)}(\\sum_{i}^{n}{{max}_{synset(i)}(sim(i,a))}

    :param context_sentence: String, a sentence.
    :param ambiguous_word: String, a single word.
    :return: If best, returns only the best Synset, else returns a dict."""
    ambiguous_word = lemmatize(ambiguous_word)
    if not wn.synsets(ambiguous_word):
        return None
    if context_is_lemmatized:
        context_sentence = word_tokenize(context_sentence)
    else:
        context_sentence = [lemmatize(w) for w in word_tokenize(context_sentence)]
    result = {}
    for i in wn.synsets(ambiguous_word, pos=pos):
        result[i] = 0
        for j in context_sentence:
            _result = [0]
            for k in wn.synsets(j):
                _result.append(sim(i, k, option))
            result[i] += max(_result)
    if option in ['res', 'resnik']:
        result = sorted([(v, k) for k, v in result.items()])
    else:
        result = sorted([(v, k) for k, v in result.items()], reverse=True)
    return result[0][1] if best else result

def remove_tags(text: str) -> str:
    """Removes <tags> in angled brackets from text."""
    tags = {i: ' ' for i in re.findall('(<[^>\n]*>)', text.strip())}
    no_tag_text = reduce(lambda x, kv: x.replace(*kv), tags.iteritems(), text)
    return ' '.join(no_tag_text.split())

def lemmatize(ambiguous_word: str, pos: str=None, neverstem=False, lemmatizer=wnl, stemmer=porter) -> str:
    """Tries to convert a surface word into lemma, and if lemmatize word is not in
    wordnet then try and convert surface word into its stem.

    This is to handle the case where users input a surface word as an ambiguous
    word and the surface word is a not a lemma."""
    pos = pos if pos else penn2morphy(pos_tag([ambiguous_word])[0][1], default_to_noun=True)
    lemma = lemmatizer.lemmatize(ambiguous_word, pos=pos)
    stem = stemmer.stem(ambiguous_word)
    if not wn.synsets(lemma):
        if neverstem:
            return ambiguous_word
        if not wn.synsets(stem):
            return ambiguous_word
        else:
            return stem
    else:
        return lemma

def penn2morphy(penntag, returnNone=False, default_to_noun=False) -> str:
    """Converts tags from Penn format (input: single string) to Morphy."""
    morphy_tag = {'NN': 'n', 'JJ': 'a', 'VB': 'v', 'RB': 'r'}
    try:
        return morphy_tag[penntag[:2]]
    except:
        if returnNone:
            return None
        elif default_to_noun:
            return 'n'
        else:
            return ''

def synset_properties(synset: 'wn.Synset', parameter: str):
    """Making from NLTK's WordNet Synset's properties to function.
    Note: This is for compatibility with NLTK 2.x"""
    return_type = SS_PARAMETERS_TYPE_MAP[parameter]
    func = 'synset.' + parameter
    return eval(func) if isinstance(eval(func), return_type) else eval(func)()

def has_synset(word: str) -> list:
    """" Returns a list of synsets of a word after lemmatization."""
    return wn.synsets(lemmatize(word, neverstem=True))

def synset_signatures(ss: 'wn.Synset', hyperhypo=True, adapted=False, remove_stopwords=True, to_lemmatize=True, remove_numbers=True, lowercase=True, original_lesk=False, from_cache=True) -> set:
    """Takes a Synset and returns its signature words.

    :param ss: An instance of wn.Synset.
    :return: A set of signature strings"""
    if from_cache:
        return synset_signatures_from_cache(ss, hyperhypo, adapted, original_lesk)
    signature = []
    signature += word_tokenize(ss.definition())
    if original_lesk:
        return set(signature)
    signature += chain(*[word_tokenize(eg) for eg in ss.examples()])
    signature += ss.lemma_names()
    if hyperhypo:
        hyperhyponyms = set(ss.hyponyms() + ss.hypernyms() + ss.instance_hyponyms() + ss.instance_hypernyms())
        signature += set(chain(*[i.lemma_names() for i in hyperhyponyms]))
    if adapted:
        related_senses = set(ss.member_holonyms() + ss.part_holonyms() + ss.substance_holonyms() + ss.member_meronyms() + ss.part_meronyms() + ss.substance_meronyms() + ss.similar_tos())
        signature += set(chain(*[i.lemma_names() for i in related_senses]))
    signature = set((s.lower() for s in signature)) if lowercase else signature
    signature = set(signature).difference(EN_STOPWORDS) if remove_stopwords else signature
    if to_lemmatize:
        signature = [lemmatize(s) if lowercase else lemmatize(s) for s in signature if not (remove_numbers and s.isdigit())]
    return set(signature)

def signatures(ambiguous_word: str, pos: str=None, hyperhypo=True, adapted=False, remove_stopwords=True, to_lemmatize=True, remove_numbers=True, lowercase=True, to_stem=False, original_lesk=False, from_cache=True) -> dict:
    """Takes an ambiguous word and optionally its Part-Of-Speech and returns
    a dictionary where keys are the synsets and values are sets of signatures.

    :param ambiguous_word: String, a single word.
    :param pos: String, one of 'a', 'r', 's', 'n', 'v', or None.
    :return: dict(synset:{signatures})."""
    pos = pos if pos in ['a', 'r', 's', 'n', 'v', None] else None
    if not wn.synsets(ambiguous_word, pos) and wn.synsets(ambiguous_word):
        pos = None
    ss_sign = {}
    for ss in wn.synsets(ambiguous_word, pos):
        ss_sign[ss] = synset_signatures(ss, hyperhypo=hyperhypo, adapted=adapted, remove_stopwords=remove_stopwords, to_lemmatize=to_lemmatize, remove_numbers=remove_numbers, lowercase=lowercase, original_lesk=original_lesk, from_cache=from_cache)
    if to_stem == True:
        ss_sign = {ss: [porter.stem(s) for s in signature] for ss, signature in ss_sign.items()}
    return ss_sign

def random_sense(ambiguous_word: str, pos=None) -> 'wn.Synset':
    """Returns a random sense.

    :param ambiguous_word: String, a single word.
    :param pos: String, one of 'a', 'r', 's', 'n', 'v', or None.
    :return: A random Synset."""
    if pos is None:
        return custom_random.choice(wn.synsets(ambiguous_word))
    else:
        return custom_random.choice(wn.synsets(ambiguous_word, pos))

def first_sense(ambiguous_word: str, pos: str=None) -> 'wn.Synset':
    """Returns the first sense.

    :param ambiguous_word: String, a single word.
    :param pos: String, one of 'a', 'r', 's', 'n', 'v', or None.
    :return: The first Synset in the wn.synsets(word) list."""
    if pos is None:
        return wn.synsets(ambiguous_word)[0]
    else:
        return wn.synsets(ambiguous_word, pos)[0]

def max_lemma_count(ambiguous_word: str) -> 'wn.Synset':
    """Returns the sense with the highest lemma_name count.
    The max_lemma_count() can be treated as a rough gauge for the
    Most Frequent Sense (MFS), if no other sense annotated corpus is available.
    NOTE: The lemma counts are from the Brown Corpus

    :param ambiguous_word: String, a single word.
    :return: The estimated most common Synset."""
    sense2lemmacounts = {}
    for i in wn.synsets(ambiguous_word, pos=None):
        sense2lemmacounts[i] = sum((j.count() for j in i.lemmas()))
    return max(sense2lemmacounts, key=sense2lemmacounts.get)

def estimate_gaussian(X):
    """Returns the mean and the variance of a data set of X points assuming that
    the points come from a gaussian distribution X."""
    mean = np.mean(X, 0)
    variance = np.var(X, 0)
    return Gaussian(mean, variance)

def dict_max(dic):
    """Returns maximum value of a dictionary."""
    aux = dict(map(lambda item: (item[1], item[0]), dic.items()))
    if aux.keys() == []:
        return 0
    max_value = max(aux.keys())
    return (max_value, aux[max_value])

def l2norm_squared(a):
    """L2 normalize squared"""
    value = 0
    for i in xrange(a.shape[1]):
        value += np.dot(a[:, i], a[:, i])
    return value

def log_normalize(data):
    """Perform log transform log(x + 1).

    Parameters
    ----------
    data : array_like"""
    if sp.issparse(data):
        data = data.copy()
        data.data = np.log2(data.data + 1)
        return data
    return np.log2(data.astype(np.float64) + 1)

def weighted_minkowski(x, y, w=_mock_identity, p=2):
    """A weighted version of Minkowski distance.

    ..math::
        D(x, y) = \\left(\\sum_i w_i |x_i - y_i|^p\right)^{\x0crac{1}{p}}

    If weights w_i are inverse standard deviations of data in each dimension
    then this represented a standardised Minkowski distance (and is
    equivalent to standardised Euclidean distance for p=1)."""
    result = 0.0
    for i in range(x.shape[0]):
        result += (w[i] * np.abs(x[i] - y[i])) ** p
    return result ** (1.0 / p)

def _handle_nice_params(optim_params: dict) -> None:
    """Convert the user friendly params into something the optimizer can
    understand."""
    optim_params['callbacks'] = _check_callbacks(optim_params.get('callbacks'))
    optim_params['use_callbacks'] = optim_params['callbacks'] is not None
    negative_gradient_method = optim_params.pop('negative_gradient_method')
    if callable(negative_gradient_method):
        negative_gradient_method = negative_gradient_method
    elif negative_gradient_method in {'bh', 'BH', 'barnes-hut'}:
        negative_gradient_method = kl_divergence_bh
    elif negative_gradient_method in {'fft', 'FFT', 'interpolation'}:
        negative_gradient_method = kl_divergence_fft
    else:
        raise ValueError('Unrecognized gradient method. Please choose one of the supported methods or provide a valid callback.')
    optim_params['objective_function'] = negative_gradient_method
    n_jobs = optim_params.get('n_jobs', 1)
    if n_jobs < 0:
        n_cores = multiprocessing.cpu_count()
        n_jobs = n_cores + n_jobs + 1
    if n_jobs <= 0:
        log.warning('`n_jobs` receieved value %d but only %d cores are available. Defaulting to single job.' % (optim_params['n_jobs'], n_cores))
        n_jobs = 1
    optim_params['n_jobs'] = n_jobs

def find_frequent_patterns(transactions, support_threshold):
    """Given a set of transactions, find the patterns in it
    over the specified support threshold."""
    tree = FPTree(transactions, support_threshold, None, None)
    return tree.mine_patterns(support_threshold)

def generate_association_rules(patterns, confidence_threshold):
    """Given a set of frequent itemsets, return a dict
    of association rules in the form
    {(left): ((right), confidence)}"""
    rules = {}
    for itemset in patterns.keys():
        upper_support = patterns[itemset]
        for i in range(1, len(itemset)):
            for antecedent in itertools.combinations(itemset, i):
                antecedent = tuple(sorted(antecedent))
                consequent = tuple(sorted(set(itemset) - set(antecedent)))
                if antecedent in patterns:
                    lower_support = patterns[antecedent]
                    confidence = float(upper_support) / lower_support
                    if confidence >= confidence_threshold:
                        rules[antecedent] = (consequent, confidence)
    return rules

def mv_videos(path):
    """move videos in sub-directory of path to path.
    """
    count = 0
    for f in os.listdir(path):
        f = os.path.join(path, f)
        if os.path.isdir(f):
            for sf in os.listdir(f):
                sf = os.path.join(f, sf)
                if os.path.isfile(sf):
                    new_name = os.path.join(path, os.path.basename(sf))
                    try:
                        os.rename(sf, new_name)
                    except (WindowsError, OSError) as e:
                        print('mv {} happens error: {}'.format(sf, e))
                    else:
                        count += 1
                        print('mv {} to {}'.format(sf, new_name))
    return count

def register_subsearcher(name, subsearcher_cls):
    """register a subsearcher, the `name` is a key used for searching subsearchers.
    if the subsearcher named `name` already exists, then it's will overrite the old subsearcher."""
    if not issubclass(subsearcher_cls, BaseSubSearcher):
        raise ValueError('{} is not a subclass of BaseSubSearcher'.format(subsearcher_cls))
    registered_subsearchers[name] = subsearcher_cls

def connect(database: Union[str, Path], *, loop: asyncio.AbstractEventLoop=None, **kwargs: Any) -> Connection:
    """Create and return a connection proxy to the sqlite database."""
    if loop is None:
        loop = asyncio.get_event_loop()
    def connector() -> sqlite3.Connection:
        if isinstance(database, str):
            loc = database
        elif isinstance(database, bytes):
            loc = database.decode('utf-8')
        else:
            loc = str(database)
        return sqlite3.connect(loc, **kwargs)
    return Connection(connector, loop)

def limit_unit(timestr, num=2):
    """DocTests:
    >>> limit_unit('1m2s', 1) == '1m'
    True
    >>> limit_unit('1m2s') == '1m2s'
    True
    >>> limit_unit('1m2s', 4) == '1m2s'
    True
    >>> limit_unit('1d2h3m2s') == '1d2h'
    True
    >>> limit_unit('1d2h3m2s', 1) == '1d'
    True"""
    l = len(timestr)
    i = 0
    p = 0
    while i < num and p <= l:
        at = 0
        while p < l:
            c = timestr[p]
            if at == 0:
                if c.isdigit():
                    p += 1
                else:
                    at += 1
            elif at == 1:
                if not c.isdigit():
                    p += 1
                else:
                    at += 1
            else:
                break
        i += 1
    return timestr[:p]

def _log_multivariate_normal_density_spherical(X, means, covars):
    """Compute Gaussian log-density at X for a spherical model."""
    cv = covars.copy()
    if covars.ndim == 1:
        cv = cv[:, np.newaxis]
    if cv.shape[1] == 1:
        cv = np.tile(cv, (1, X.shape[-1]))
    return _log_multivariate_normal_density_diag(X, means, cv)

def _log_multivariate_normal_density_tied(X, means, covars):
    """Compute Gaussian log-density at X for a tied model."""
    cv = np.tile(covars, (means.shape[0], 1, 1))
    return _log_multivariate_normal_density_full(X, means, cv)

def _log_multivariate_normal_density_full(X, means, covars, min_covar=1e-07):
    """Log probability for full covariance matrices."""
    n_samples, n_dim = X.shape
    nmix = len(means)
    log_prob = np.empty((n_samples, nmix))
    for c, (mu, cv) in enumerate(zip(means, covars)):
        try:
            cv_chol = linalg.cholesky(cv, lower=True)
        except linalg.LinAlgError:
            try:
                cv_chol = linalg.cholesky(cv + min_covar * np.eye(n_dim), lower=True)
            except linalg.LinAlgError:
                raise ValueError("'covars' must be symmetric, positive-definite")
        cv_log_det = 2 * np.sum(np.log(np.diagonal(cv_chol)))
        cv_sol = linalg.solve_triangular(cv_chol, (X - mu).T, lower=True).T
        log_prob[:, c] = -0.5 * (np.sum(cv_sol ** 2, axis=1) + n_dim * np.log(2 * np.pi) + cv_log_det)
    return log_prob

def distribute_covar_matrix_to_match_covariance_type(tied_cv, covariance_type, n_components):
    """Create all the covariance matrices from a given template."""
    if covariance_type == 'spherical':
        cv = np.tile(tied_cv.mean() * np.ones(tied_cv.shape[1]), (n_components, 1))
    elif covariance_type == 'tied':
        cv = tied_cv
    elif covariance_type == 'diag':
        cv = np.tile(np.diag(tied_cv), (n_components, 1))
    elif covariance_type == 'full':
        cv = np.tile(tied_cv, (n_components, 1, 1))
    else:
        raise ValueError('covariance_type must be one of ' + "'spherical', 'tied', 'diag', 'full'")
    return cv

