def tree_to_stream(entries, write):
    """Write the give list of entries into a stream using its write method
    :param entries: **sorted** list of tuples with (binsha, mode, name)
    :param write: write method which takes a data string"""
    ord_zero = ord('0')
    bit_mask = 7
    for binsha, mode, name in entries:
        mode_str = b''
        for i in xrange(6):
            mode_str = bchr((mode >> i * 3 & bit_mask) + ord_zero) + mode_str
        if byte_ord(mode_str[0]) == ord_zero:
            mode_str = mode_str[1:]
        if isinstance(name, text_type):
            name = name.encode(defenc)
        write(b''.join((mode_str, b' ', name, b'\x00', binsha)))

def _find_by_name(tree_data, name, is_dir, start_at):
    """return data entry matching the given name and tree mode
    or None.
    Before the item is returned, the respective data item is set
    None in the tree_data list to mark it done"""
    try:
        item = tree_data[start_at]
        if item and item[2] == name and (S_ISDIR(item[1]) == is_dir):
            tree_data[start_at] = None
            return item
    except IndexError:
        pass
    for index, item in enumerate(tree_data):
        if item and item[2] == name and (S_ISDIR(item[1]) == is_dir):
            tree_data[index] = None
            return item
    return None

def needs_values(func):
    """Returns method assuring we read values (on demand) before we try to access them"""
    @wraps(func)
    def assure_data_present(self, *args, **kwargs):
        self.read()
        return func(self, *args, **kwargs)
    return assure_data_present

def stat_mode_to_index_mode(mode):
    """Convert the given mode from a stat call to the corresponding index mode
    and return it"""
    if S_ISLNK(mode):
        return S_IFLNK
    if S_ISDIR(mode) or S_IFMT(mode) == S_IFGITLINK:
        return S_IFGITLINK
    return S_IFREG | 420 | mode & 73

def read_header(stream):
    """Return tuple(version_long, num_entries) from the given stream"""
    type_id = stream.read(4)
    if type_id != b'DIRC':
        raise AssertionError('Invalid index file header: %r' % type_id)
    version, num_entries = unpack('>LL', stream.read(4 * 2))
    assert version in (1, 2)
    return (version, num_entries)

