def verify_utctz(offset):
    """:raise ValueError: if offset is incorrect
    :return: offset"""
    fmt_exc = ValueError('Invalid timezone offset format: %s' % offset)
    if len(offset) != 5:
        raise fmt_exc
    if offset[0] not in '+-':
        raise fmt_exc
    if offset[1] not in digits or offset[2] not in digits or offset[3] not in digits or (offset[4] not in digits):
        raise fmt_exc
    return offset

def from_timestamp(timestamp, tz_offset):
    """Converts a timestamp + tz_offset into an aware datetime instance."""
    utc_dt = datetime.fromtimestamp(timestamp, utc)
    try:
        local_dt = utc_dt.astimezone(tzoffset(tz_offset))
        return local_dt
    except ValueError:
        return utc_dt

