    """Open the specified URL, using HTTP basic authentication to provide
    the specified credentials to the server as part of the request.
    Returns the response as a file-like object."""
    return requests.get(url, auth=HTTPBasicAuth(user, pwd), verify=False)

def OpenPathWithStub(path, stub):
    """Open the specified path using HTTP, using the host/port/protocol
    associated with the specified stub.  If the stub has a session cookie,
    it is included with the HTTP request.  Returns the response as a
    file-like object."""
    from six.moves import http_client
    if not hasattr(stub, 'scheme'):
        raise vmodl.fault.NotSupported()
    elif stub.scheme == http_client.HTTPConnection:
        protocol = 'http'
    elif stub.scheme == http_client.HTTPSConnection:
        protocol = 'https'
    else:
        raise vmodl.fault.NotSupported()
    hostPort = stub.host
    url = '%s://%s%s' % (protocol, hostPort, path)
    headers = {}
    if stub.cookie:
        headers['Cookie'] = stub.cookie
    return requests.get(url, headers=headers, verify=False)

def IsPrimitiveType(obj):
    """See if the passed in type is a Primitive Type"""
    return isinstance(obj, types.bool) or isinstance(obj, types.byte) or isinstance(obj, types.short) or isinstance(obj, six.integer_types) or isinstance(obj, types.double) or isinstance(obj, types.float) or isinstance(obj, six.string_types) or isinstance(obj, types.PropertyPath) or isinstance(obj, types.ManagedMethod) or isinstance(obj, types.datetime) or isinstance(obj, types.URI) or isinstance(obj, type)

def DiffAnys(obj1, obj2, looseMatch=False, ignoreArrayOrder=True):
    """Diff any two objects. Objects can either be primitive type
    or DataObjects"""
    differ = Differ(looseMatch=looseMatch, ignoreArrayOrder=ignoreArrayOrder)
    return differ.DiffAnyObjects(obj1, obj2)

def Cache(fn):
    """Function cache decorator"""
    def fnCache(*args, **kwargs):
        """Cache function"""
        key = (args and tuple(args) or None, kwargs and frozenset(kwargs.items()) or None)
        if key not in fn.__cached__:
            fn.__cached__[key] = cache = fn(*args, **kwargs)
        else:
            cache = fn.__cached__[key]
        return cache
    def ResetCache():
        """Reset cache"""
        fn.__cached__ = {}
    setattr(fn, '__cached__', {})
    setattr(fn, '__resetcache__', ResetCache)
    fnCache.__name__ = fn.__name__
    fnCache.__doc__ = fn.__doc__
    fnCache.__dict__.update(fn.__dict__)
    return fnCache

def ISO8601Format(dt):
    """Python datetime isoformat() has the following problems:
    - leave trailing 0 at the end of microseconds (violates XMLSchema rule)
    - tz print +00:00 instead of Z
    - Missing timezone offset for datetime without tzinfo"""
    isoStr = dt.strftime('%Y-%m-%dT%H:%M:%S')
    if dt.microsecond:
        isoStr += ('.%06d' % dt.microsecond).rstrip('0')
    if dt.tzinfo:
        tz = dt.strftime('%z')
    else:
        if time.daylight and time.localtime().tm_isdst:
            utcOffset_minutes = -time.altzone / 60
        else:
            utcOffset_minutes = -time.timezone / 60
        tz = '%+.2d%.2d' % (utcOffset_minutes / 60, abs(utcOffset_minutes) % 60)
    if tz == '+0000':
        return isoStr + 'Z'
    elif tz:
        return isoStr + tz[:3] + ':' + tz[3:]
    else:
        return isoStr + '-00:00'

def CreateTasksFilter(pc, tasks):
    """Create property collector filter for tasks"""
    if not tasks:
        return None
    objspecs = [vmodl.query.PropertyCollector.ObjectSpec(obj=task) for task in tasks]
    propspec = vmodl.query.PropertyCollector.PropertySpec(type=vim.Task, pathSet=[], all=True)
    filterspec = vmodl.query.PropertyCollector.FilterSpec()
    filterspec.objectSet = objspecs
    filterspec.propSet = [propspec]
    return pc.CreateFilter(filterspec, True)

def CheckForQuestionPending(task):
    """Check to see if VM needs to ask a question, throw exception"""
    vm = task.info.entity
    if vm is not None and isinstance(vm, vim.VirtualMachine):
        qst = vm.runtime.question
        if qst is not None:
            raise TaskBlocked('Task blocked, User Intervention required')

def unpack_hyperopt_vals(vals):
    """Unpack values from a hyperopt return dictionary where values are wrapped in a list.
    :param vals: dict
    :return: dict
        copy of the dictionary with unpacked values"""
    assert isinstance(vals, dict), 'Parameter must be given as dict.'
    ret = {}
    for k, v in list(vals.items()):
        try:
            ret[k] = v[0]
        except (TypeError, IndexError):
            ret[k] = v
    return ret

def _zlib_no_compress(data):
    """Compress data with zlib level 0."""
    cobj = zlib.compressobj(0)
    return b''.join([cobj.compress(data), cobj.flush()])

def _parse_codec_options(options):
    """Parse BSON codec options."""
    return CodecOptions(document_class=options.get('document_class', DEFAULT_CODEC_OPTIONS.document_class), tz_aware=options.get('tz_aware', DEFAULT_CODEC_OPTIONS.tz_aware), uuid_representation=options.get('uuidrepresentation', DEFAULT_CODEC_OPTIONS.uuid_representation), unicode_decode_error_handler=options.get('unicode_decode_error_handler', DEFAULT_CODEC_OPTIONS.unicode_decode_error_handler), tzinfo=options.get('tzinfo', DEFAULT_CODEC_OPTIONS.tzinfo), type_registry=options.get('type_registry', DEFAULT_CODEC_OPTIONS.type_registry))

def _merge_command(run, full_result, offset, result):
    """Merge a write command result into the full bulk result.
    """
    affected = result.get('n', 0)
    if run.op_type == _INSERT:
        full_result['nInserted'] += affected
    elif run.op_type == _DELETE:
        full_result['nRemoved'] += affected
    elif run.op_type == _UPDATE:
        upserted = result.get('upserted')
        if upserted:
            n_upserted = len(upserted)
            for doc in upserted:
                doc['index'] = run.index(doc['index'] + offset)
            full_result['upserted'].extend(upserted)
            full_result['nUpserted'] += n_upserted
            full_result['nMatched'] += affected - n_upserted
        else:
            full_result['nMatched'] += affected
        full_result['nModified'] += result['nModified']
    write_errors = result.get('writeErrors')
    if write_errors:
        for doc in write_errors:
            replacement = doc.copy()
            idx = doc['index'] + offset
            replacement['index'] = run.index(idx)
            replacement[_UOP] = run.ops[idx]
            full_result['writeErrors'].append(replacement)
    wc_error = result.get('writeConcernError')
    if wc_error:
        full_result['writeConcernErrors'].append(wc_error)

def _raise_bulk_write_error(full_result):
    """Raise a BulkWriteError from the full bulk api result.
    """
    if full_result['writeErrors']:
        full_result['writeErrors'].sort(key=lambda error: error['index'])
    raise BulkWriteError(full_result)

def _compress(operation, data, ctx):
    """Takes message data, compresses it, and adds an OP_COMPRESSED header."""
    compressed = ctx.compress(data)
    request_id = _randint()
    header = _pack_compression_header(_COMPRESSION_HEADER_SIZE + len(compressed), request_id, 0, 2012, operation, len(data), ctx.compressor_id)
    return (request_id, header + compressed)

def __pack_message(operation, data):
    """Takes message data and adds a message header based on the operation.

    Returns the resultant message string."""
    rid = _randint()
    message = _pack_header(16 + len(data), rid, 0, operation)
    return (rid, message + data)

def _insert(collection_name, docs, check_keys, flags, opts):
    """Get an OP_INSERT message"""
    encode = _dict_to_bson
    if len(docs) == 1:
        encoded = encode(docs[0], check_keys, opts)
        return (b''.join([b'\x00\x00\x00\x00', _make_c_string(collection_name), encoded]), len(encoded))
    encoded = [encode(doc, check_keys, opts) for doc in docs]
    if not encoded:
        raise InvalidOperation('cannot do an empty bulk insert')
    return (b''.join([_pack_int(flags), _make_c_string(collection_name), b''.join(encoded)]), max(map(len, encoded)))

def _insert_compressed(collection_name, docs, check_keys, continue_on_error, opts, ctx):
    """Internal compressed unacknowledged insert message helper."""
    op_insert, max_bson_size = _insert(collection_name, docs, check_keys, continue_on_error, opts)
    rid, msg = _compress(2002, op_insert, ctx)
    return (rid, msg, max_bson_size)

def insert(collection_name, docs, check_keys, safe, last_error_args, continue_on_error, opts, ctx=None):
    """Get an **insert** message."""
    if ctx:
        return _insert_compressed(collection_name, docs, check_keys, continue_on_error, opts, ctx)
    return _insert_uncompressed(collection_name, docs, check_keys, safe, last_error_args, continue_on_error, opts)

def _update(collection_name, upsert, multi, spec, doc, check_keys, opts):
    """Get an OP_UPDATE message."""
    flags = 0
    if upsert:
        flags += 1
    if multi:
        flags += 2
    encode = _dict_to_bson
    encoded_update = encode(doc, check_keys, opts)
    return (b''.join([_ZERO_32, _make_c_string(collection_name), _pack_int(flags), encode(spec, False, opts), encoded_update]), len(encoded_update))

def _update_compressed(collection_name, upsert, multi, spec, doc, check_keys, opts, ctx):
    """Internal compressed unacknowledged update message helper."""
    op_update, max_bson_size = _update(collection_name, upsert, multi, spec, doc, check_keys, opts)
    rid, msg = _compress(2001, op_update, ctx)
    return (rid, msg, max_bson_size)

def _update_uncompressed(collection_name, upsert, multi, spec, doc, safe, last_error_args, check_keys, opts):
    """Internal update message helper."""
    op_update, max_bson_size = _update(collection_name, upsert, multi, spec, doc, check_keys, opts)
    rid, msg = __pack_message(2001, op_update)
    if safe:
        rid, gle, _ = __last_error(collection_name, last_error_args)
        return (rid, msg + gle, max_bson_size)
    return (rid, msg, max_bson_size)

def update(collection_name, upsert, multi, spec, doc, safe, last_error_args, check_keys, opts, ctx=None):
    """Get an **update** message."""
    if ctx:
        return _update_compressed(collection_name, upsert, multi, spec, doc, check_keys, opts, ctx)
    return _update_uncompressed(collection_name, upsert, multi, spec, doc, safe, last_error_args, check_keys, opts)

def _op_msg_compressed(flags, command, identifier, docs, check_keys, opts, ctx):
    """Internal OP_MSG message helper."""
    msg, total_size, max_bson_size = _op_msg_no_header(flags, command, identifier, docs, check_keys, opts)
    rid, msg = _compress(2013, msg, ctx)
    return (rid, msg, total_size, max_bson_size)

def _op_msg_uncompressed(flags, command, identifier, docs, check_keys, opts):
    """Internal compressed OP_MSG message helper."""
    data, total_size, max_bson_size = _op_msg_no_header(flags, command, identifier, docs, check_keys, opts)
    request_id, op_message = __pack_message(2013, data)
    return (request_id, op_message, total_size, max_bson_size)

def _op_msg(flags, command, dbname, read_preference, slave_ok, check_keys, opts, ctx=None):
    """Get a OP_MSG message."""
    command['$db'] = dbname
    if '$readPreference' not in command:
        if slave_ok and (not read_preference.mode):
            command['$readPreference'] = ReadPreference.PRIMARY_PREFERRED.document
        else:
            command['$readPreference'] = read_preference.document
    name = next(iter(command))
    try:
        identifier = _FIELD_MAP.get(name)
        docs = command.pop(identifier)
    except KeyError:
        identifier = ''
        docs = None
    try:
        if ctx:
            return _op_msg_compressed(flags, command, identifier, docs, check_keys, opts, ctx)
        return _op_msg_uncompressed(flags, command, identifier, docs, check_keys, opts)
    finally:
        if identifier:
            command[identifier] = docs

def _query(options, collection_name, num_to_skip, num_to_return, query, field_selector, opts, check_keys):
    """Get an OP_QUERY message."""
    encoded = _dict_to_bson(query, check_keys, opts)
    if field_selector:
        efs = _dict_to_bson(field_selector, False, opts)
    else:
        efs = b''
    max_bson_size = max(len(encoded), len(efs))
    return (b''.join([_pack_int(options), _make_c_string(collection_name), _pack_int(num_to_skip), _pack_int(num_to_return), encoded, efs]), max_bson_size)

def _query_compressed(options, collection_name, num_to_skip, num_to_return, query, field_selector, opts, check_keys=False, ctx=None):
    """Internal compressed query message helper."""
    op_query, max_bson_size = _query(options, collection_name, num_to_skip, num_to_return, query, field_selector, opts, check_keys)
    rid, msg = _compress(2004, op_query, ctx)
    return (rid, msg, max_bson_size)

def _query_uncompressed(options, collection_name, num_to_skip, num_to_return, query, field_selector, opts, check_keys=False):
    """Internal query message helper."""
    op_query, max_bson_size = _query(options, collection_name, num_to_skip, num_to_return, query, field_selector, opts, check_keys)
    rid, msg = __pack_message(2004, op_query)
    return (rid, msg, max_bson_size)

def query(options, collection_name, num_to_skip, num_to_return, query, field_selector, opts, check_keys=False, ctx=None):
    """Get a **query** message."""
    if ctx:
        return _query_compressed(options, collection_name, num_to_skip, num_to_return, query, field_selector, opts, check_keys, ctx)
    return _query_uncompressed(options, collection_name, num_to_skip, num_to_return, query, field_selector, opts, check_keys)

def _get_more(collection_name, num_to_return, cursor_id):
    """Get an OP_GET_MORE message."""
    return b''.join([_ZERO_32, _make_c_string(collection_name), _pack_int(num_to_return), _pack_long_long(cursor_id)])

def _get_more_compressed(collection_name, num_to_return, cursor_id, ctx):
    """Internal compressed getMore message helper."""
    return _compress(2005, _get_more(collection_name, num_to_return, cursor_id), ctx)

def get_more(collection_name, num_to_return, cursor_id, ctx=None):
    """Get a **getMore** message."""
    if ctx:
        return _get_more_compressed(collection_name, num_to_return, cursor_id, ctx)
    return _get_more_uncompressed(collection_name, num_to_return, cursor_id)

def _delete(collection_name, spec, opts, flags):
    """Get an OP_DELETE message."""
    encoded = _dict_to_bson(spec, False, opts)
    return (b''.join([_ZERO_32, _make_c_string(collection_name), _pack_int(flags), encoded]), len(encoded))

def _delete_compressed(collection_name, spec, opts, flags, ctx):
    """Internal compressed unacknowledged delete message helper."""
    op_delete, max_bson_size = _delete(collection_name, spec, opts, flags)
    rid, msg = _compress(2006, op_delete, ctx)
    return (rid, msg, max_bson_size)

def _delete_uncompressed(collection_name, spec, safe, last_error_args, opts, flags=0):
    """Internal delete message helper."""
    op_delete, max_bson_size = _delete(collection_name, spec, opts, flags)
    rid, msg = __pack_message(2006, op_delete)
    if safe:
        rid, gle, _ = __last_error(collection_name, last_error_args)
        return (rid, msg + gle, max_bson_size)
    return (rid, msg, max_bson_size)

def delete(collection_name, spec, safe, last_error_args, opts, flags=0, ctx=None):
    """Get a **delete** message.

    `opts` is a CodecOptions. `flags` is a bit vector that may contain
    the SingleRemove flag or not:

    http://docs.mongodb.org/meta-driver/latest/legacy/mongodb-wire-protocol/#op-delete"""
    if ctx:
        return _delete_compressed(collection_name, spec, opts, flags, ctx)
    return _delete_uncompressed(collection_name, spec, safe, last_error_args, opts, flags)

def _raise_document_too_large(operation, doc_size, max_size):
    """Internal helper for raising DocumentTooLarge."""
    if operation == 'insert':
        raise DocumentTooLarge('BSON document too large (%d bytes) - the connected server supports BSON document sizes up to %d bytes.' % (doc_size, max_size))
    else:
        raise DocumentTooLarge('%r command document too large' % (operation,))

def _encode_batched_op_msg(operation, command, docs, check_keys, ack, opts, ctx):
    """Encode the next batched insert, update, or delete operation
    as OP_MSG."""
    buf = StringIO()
    to_send, _ = _batched_op_msg_impl(operation, command, docs, check_keys, ack, opts, ctx, buf)
    return (buf.getvalue(), to_send)

def _batched_op_msg_compressed(operation, command, docs, check_keys, ack, opts, ctx):
    """Create the next batched insert, update, or delete operation
    with OP_MSG, compressed."""
    data, to_send = _encode_batched_op_msg(operation, command, docs, check_keys, ack, opts, ctx)
    request_id, msg = _compress(2013, data, ctx.sock_info.compression_context)
    return (request_id, msg, to_send)

def _do_batched_op_msg(namespace, operation, command, docs, check_keys, opts, ctx):
    """Create the next batched insert, update, or delete operation
    using OP_MSG."""
    command['$db'] = namespace.split('.', 1)[0]
    if 'writeConcern' in command:
        ack = bool(command['writeConcern'].get('w', 1))
    else:
        ack = True
    if ctx.sock_info.compression_context:
        return _batched_op_msg_compressed(operation, command, docs, check_keys, ack, opts, ctx)
    return _batched_op_msg(operation, command, docs, check_keys, ack, opts, ctx)

def _batched_write_command_compressed(namespace, operation, command, docs, check_keys, opts, ctx):
    """Create the next batched insert, update, or delete command, compressed.
    """
    data, to_send = _encode_batched_write_command(namespace, operation, command, docs, check_keys, opts, ctx)
    request_id, msg = _compress(2004, data, ctx.sock_info.compression_context)
    return (request_id, msg, to_send)

def _encode_batched_write_command(namespace, operation, command, docs, check_keys, opts, ctx):
    """Encode the next batched insert, update, or delete command.
    """
    buf = StringIO()
    to_send, _ = _batched_write_command_impl(namespace, operation, command, docs, check_keys, opts, ctx, buf)
    return (buf.getvalue(), to_send)

def _do_batched_write_command(namespace, operation, command, docs, check_keys, opts, ctx):
    """Batched write commands entry point."""
    if ctx.sock_info.compression_context:
        return _batched_write_command_compressed(namespace, operation, command, docs, check_keys, opts, ctx)
    return _batched_write_command(namespace, operation, command, docs, check_keys, opts, ctx)

def _do_bulk_write_command(namespace, operation, command, docs, check_keys, opts, ctx):
    """Bulk write commands entry point."""
    if ctx.sock_info.max_wire_version > 5:
        return _do_batched_op_msg(namespace, operation, command, docs, check_keys, opts, ctx)
    return _do_batched_write_command(namespace, operation, command, docs, check_keys, opts, ctx)

def _parse_options(opts, delim):
    """Helper method for split_options which creates the options dict.
    Also handles the creation of a list for the URI tag_sets/
    readpreferencetags portion and the use of the tlsInsecure option."""
    options = _CaseInsensitiveDictionary()
    for uriopt in opts.split(delim):
        key, value = uriopt.split('=')
        if key.lower() == 'readpreferencetags':
            options.setdefault(key, []).append(value)
        else:
            if key in options:
                warnings.warn("Duplicate URI option '%s'." % (key,))
            options[key] = unquote_plus(value)
    if 'tlsInsecure' in options:
        for implicit_option in _IMPLICIT_TLSINSECURE_OPTS:
            if implicit_option in options:
                warn_msg = "URI option '%s' overrides value implied by '%s'."
                warnings.warn(warn_msg % (options.cased_key(implicit_option), options.cased_key('tlsInsecure')))
                continue
            options[implicit_option] = options['tlsInsecure']
    return options

def _normalize_options(options):
    """Renames keys in the options dictionary to their internally-used
    names."""
    normalized_options = {}
    for key, value in iteritems(options):
        optname = str(key).lower()
        intname = INTERNAL_URI_OPTION_NAME_MAP.get(optname, key)
        normalized_options[intname] = options[key]
    return normalized_options

def split_options(opts, validate=True, warn=False, normalize=True):
    """Takes the options portion of a MongoDB URI, validates each option
    and returns the options in a dictionary.

    :Parameters:
        - `opt`: A string representing MongoDB URI options.
        - `validate`: If ``True`` (the default), validate and normalize all
          options.
        - `warn`: If ``False`` (the default), suppress all warnings raised
          during validation of options.
        - `normalize`: If ``True`` (the default), renames all options to their
          internally-used names."""
    and_idx = opts.find('&')
    semi_idx = opts.find(';')
    try:
        if and_idx >= 0 and semi_idx >= 0:
            raise InvalidURI("Can not mix '&' and ';' for option separators.")
        elif and_idx >= 0:
            options = _parse_options(opts, '&')
        elif semi_idx >= 0:
            options = _parse_options(opts, ';')
        elif opts.find('=') != -1:
            options = _parse_options(opts, None)
        else:
            raise ValueError
    except ValueError:
        raise InvalidURI('MongoDB URI options are key=value pairs.')
    options = _handle_option_deprecations(options)
    if validate:
        options = validate_options(options, warn)
    if normalize:
        options = _normalize_options(options)
    return options

def _configured_socket(address, options):
    """Given (host, port) and PoolOptions, return a configured socket.

    Can raise socket.error, ConnectionFailure, or CertificateError.

    Sets socket's SSL and timeout options."""
    sock = _create_connection(address, options)
    ssl_context = options.ssl_context
    if ssl_context is not None:
        host = address[0]
        try:
            if _HAVE_SNI and (not is_ip_address(host) or _PY37PLUS):
                sock = ssl_context.wrap_socket(sock, server_hostname=host)
            else:
                sock = ssl_context.wrap_socket(sock)
        except _SSLCertificateError:
            sock.close()
            raise
        except IOError as exc:
            sock.close()
            _raise_connection_failure(address, exc, 'SSL handshake failed: ')
        if ssl_context.verify_mode and (not getattr(ssl_context, 'check_hostname', False)) and options.ssl_match_hostname:
            try:
                match_hostname(sock.getpeercert(), hostname=host)
            except CertificateError:
                sock.close()
                raise
    sock.settimeout(options.socket_timeout)
    return sock

def receive_message(sock, request_id, max_message_size=MAX_MESSAGE_SIZE):
    """Receive a raw BSON message or raise socket.error."""
    length, _, response_to, op_code = _UNPACK_HEADER(_receive_data_on_socket(sock, 16))
    if request_id is not None:
        if request_id != response_to:
            raise ProtocolError('Got response id %r but expected %r' % (response_to, request_id))
    if length <= 16:
        raise ProtocolError('Message length (%r) not longer than standard message header size (16)' % (length,))
    if length > max_message_size:
        raise ProtocolError('Message length (%r) is larger than server max message size (%r)' % (length, max_message_size))
    if op_code == 2012:
        op_code, _, compressor_id = _UNPACK_COMPRESSION_HEADER(_receive_data_on_socket(sock, 9))
        data = decompress(_receive_data_on_socket(sock, length - 25), compressor_id)
    else:
        data = _receive_data_on_socket(sock, length - 16)
    try:
        unpack_reply = _UNPACK_REPLY[op_code]
    except KeyError:
        raise ProtocolError('Got opcode %r but expected %r' % (op_code, _UNPACK_REPLY.keys()))
    return unpack_reply(data)

def _get_object_size(data, position, obj_end):
    """Validate and return a BSON document's size."""
    try:
        obj_size = _UNPACK_INT(data[position:position + 4])[0]
    except struct.error as exc:
        raise InvalidBSON(str(exc))
    end = position + obj_size - 1
    if data[end:end + 1] != b'\x00':
        raise InvalidBSON('bad eoo')
    if end >= obj_end:
        raise InvalidBSON('invalid object length')
    if position == 0 and obj_size != obj_end:
        raise InvalidBSON('invalid object length')
    return (obj_size, end)

def _get_object(data, position, obj_end, opts, dummy):
    """Decode a BSON subdocument to opts.document_class or bson.dbref.DBRef."""
    obj_size, end = _get_object_size(data, position, obj_end)
    if _raw_document_class(opts.document_class):
        return (opts.document_class(data[position:end + 1], opts), position + obj_size)
    obj = _elements_to_dict(data, position + 4, end, opts)
    position += obj_size
    if '$ref' in obj:
        return (DBRef(obj.pop('$ref'), obj.pop('$id', None), obj.pop('$db', None), obj), position)
    return (obj, position)

def _get_array(data, position, obj_end, opts, element_name):
    """Decode a BSON array to python list."""
    size = _UNPACK_INT(data[position:position + 4])[0]
    end = position + size - 1
    if data[end:end + 1] != b'\x00':
        raise InvalidBSON('bad eoo')
    position += 4
    end -= 1
    result = []
    append = result.append
    index = data.index
    getter = _ELEMENT_GETTER
    decoder_map = opts.type_registry._decoder_map
    while position < end:
        element_type = data[position:position + 1]
        position = index(b'\x00', position) + 1
        try:
            value, position = getter[element_type](data, position, obj_end, opts, element_name)
        except KeyError:
            _raise_unknown_type(element_type, element_name)
        if decoder_map:
            custom_decoder = decoder_map.get(type(value))
            if custom_decoder is not None:
                value = custom_decoder(value)
        append(value)
    if position != end + 1:
        raise InvalidBSON('bad array length')
    return (result, position + 1)

def _element_to_dict(data, position, obj_end, opts):
    """Decode a single key, value pair."""
    element_type = data[position:position + 1]
    position += 1
    element_name, position = _get_c_string(data, position, opts)
    try:
        value, position = _ELEMENT_GETTER[element_type](data, position, obj_end, opts, element_name)
    except KeyError:
        _raise_unknown_type(element_type, element_name)
    if opts.type_registry._decoder_map:
        custom_decoder = opts.type_registry._decoder_map.get(type(value))
        if custom_decoder is not None:
            value = custom_decoder(value)
    return (element_name, value, position)

def _elements_to_dict(data, position, obj_end, opts, result=None):
    """Decode a BSON document into result."""
    if result is None:
        result = opts.document_class()
    end = obj_end - 1
    while position < end:
        key, value, position = _element_to_dict(data, position, obj_end, opts)
        result[key] = value
    if position != obj_end:
        raise InvalidBSON('bad object or element length')
    return result

def _bson_to_dict(data, opts):
    """Decode a BSON string to document_class."""
    try:
        if _raw_document_class(opts.document_class):
            return opts.document_class(data, opts)
        _, end = _get_object_size(data, 0, len(data))
        return _elements_to_dict(data, 4, end, opts)
    except InvalidBSON:
        raise
    except Exception:
        _, exc_value, exc_tb = sys.exc_info()
        reraise(InvalidBSON, exc_value, exc_tb)

def _name_value_to_bson(name, value, check_keys, opts, in_custom_call=False, in_fallback_call=False):
    """Encode a single name, value pair."""
    try:
        return _ENCODERS[type(value)](name, value, check_keys, opts)
    except KeyError:
        pass
    marker = getattr(value, '_type_marker', None)
    if isinstance(marker, int) and marker in _MARKERS:
        func = _MARKERS[marker]
        _ENCODERS[type(value)] = func
        return func(name, value, check_keys, opts)
    if not in_custom_call and opts.type_registry._encoder_map:
        custom_encoder = opts.type_registry._encoder_map.get(type(value))
        if custom_encoder is not None:
            return _name_value_to_bson(name, custom_encoder(value), check_keys, opts, in_custom_call=True)
    for base in _BUILT_IN_TYPES:
        if isinstance(value, base):
            func = _ENCODERS[base]
            _ENCODERS[type(value)] = func
            return func(name, value, check_keys, opts)
    fallback_encoder = opts.type_registry._fallback_encoder
    if not in_fallback_call and fallback_encoder is not None:
        return _name_value_to_bson(name, fallback_encoder(value), check_keys, opts, in_fallback_call=True)
    raise InvalidDocument('cannot encode object: %r, of type: %r' % (value, type(value)))

def _datetime_to_millis(dtm):
    """Convert datetime to milliseconds since epoch UTC."""
    if dtm.utcoffset() is not None:
        dtm = dtm - dtm.utcoffset()
    return int(calendar.timegm(dtm.timetuple()) * 1000 + dtm.microsecond // 1000)

def _validate_session_write_concern(session, write_concern):
    """Validate that an explicit session is not used with an unack'ed write.

    Returns the session to use for the next operation."""
    if session:
        if write_concern is not None and (not write_concern.acknowledged):
            if session._implicit:
                return None
            else:
                raise ConfigurationError('Explicit sessions are incompatible with unacknowledged write concern: %r' % (write_concern,))
    return session

def _parse_ssl_options(options):
    """Parse ssl options."""
    use_ssl = options.get('ssl')
    if use_ssl is not None:
        validate_boolean('ssl', use_ssl)
    certfile = options.get('ssl_certfile')
    keyfile = options.get('ssl_keyfile')
    passphrase = options.get('ssl_pem_passphrase')
    ca_certs = options.get('ssl_ca_certs')
    cert_reqs = options.get('ssl_cert_reqs')
    match_hostname = options.get('ssl_match_hostname', True)
    crlfile = options.get('ssl_crlfile')
    ssl_kwarg_keys = [k for k in options if k.startswith('ssl_') and options[k]]
    if use_ssl == False and ssl_kwarg_keys:
        raise ConfigurationError('ssl has not been enabled but the following ssl parameters have been set: %s. Please set `ssl=True` or remove.' % ', '.join(ssl_kwarg_keys))
    if ssl_kwarg_keys and use_ssl is None:
        use_ssl = True
    if use_ssl is True:
        ctx = get_ssl_context(certfile, keyfile, passphrase, ca_certs, cert_reqs, crlfile, match_hostname)
        return (ctx, match_hostname)
    return (None, match_hostname)

def _index_document(index_list):
    """Helper to generate an index specifying document.

    Takes a list of (key, direction) pairs."""
    if isinstance(index_list, abc.Mapping):
        raise TypeError('passing a dict to sort/create_index/hint is not allowed - use a list of tuples instead. did you mean %r?' % list(iteritems(index_list)))
    elif not isinstance(index_list, (list, tuple)):
        raise TypeError('must use a list of (key, direction) pairs, not: ' + repr(index_list))
    if not len(index_list):
        raise ValueError('key_or_list must not be the empty list')
    index = SON()
    for key, value in index_list:
        if not isinstance(key, string_type):
            raise TypeError('first item in each key pair must be a string')
        if not isinstance(value, (string_type, int, abc.Mapping)):
            raise TypeError("second item in each key pair must be 1, -1, '2d', 'geoHaystack', or another valid MongoDB index specifier.")
        index[key] = value
    return index

def _check_gle_response(result):
    """Return getlasterror response as a dict, or raise OperationFailure."""
    _check_command_response(result)
    if result.get('wtimeout', False):
        raise WTimeoutError(result.get('errmsg', result.get('err')), result.get('code'), result)
    error_msg = result.get('err', '')
    if error_msg is None:
        return result
    if error_msg.startswith('not master'):
        raise NotMasterError(error_msg, result)
    details = result
    if 'errObjects' in result:
        for errobj in result['errObjects']:
            if errobj.get('err') == error_msg:
                details = errobj
                break
    code = details.get('code')
    if code in (11000, 11001, 12582):
        raise DuplicateKeyError(details['err'], code, result)
    raise OperationFailure(details['err'], code, result)

def _check_write_command_response(result):
    """Backward compatibility helper for write command error handling.
    """
    write_errors = result.get('writeErrors')
    if write_errors:
        _raise_last_write_error(write_errors)
    error = result.get('writeConcernError')
    if error:
        _raise_write_concern_error(error)

def _clear_entity_type_registry(entity, **kwargs):
    """Clear the given database/collection object's type registry."""
    codecopts = entity.codec_options.with_options(type_registry=None)
    return entity.with_options(codec_options=codecopts, **kwargs)

def _password_digest(username, password):
    """Get a password digest to use for authentication.
    """
    if not isinstance(password, string_type):
        raise TypeError('password must be an instance of %s' % (string_type.__name__,))
    if len(password) == 0:
        raise ValueError("password can't be empty")
    if not isinstance(username, string_type):
        raise TypeError('password must be an instance of  %s' % (string_type.__name__,))
    md5hash = hashlib.md5()
    data = '%s:mongo:%s' % (username, password)
    md5hash.update(data.encode('utf-8'))
    return _unicode(md5hash.hexdigest())

def validate_integer(option, value):
    """Validates that 'value' is an integer (or basestring representation).
    """
    if isinstance(value, integer_types):
        return value
    elif isinstance(value, string_type):
        try:
            return int(value)
        except ValueError:
            raise ValueError('The value of %s must be an integer' % (option,))
    raise TypeError('Wrong type for %s, value must be an integer' % (option,))

def validate_non_negative_int_or_basestring(option, value):
    """Validates that 'value' is an integer or string.
    """
    if isinstance(value, integer_types):
        return value
    elif isinstance(value, string_type):
        try:
            val = int(value)
        except ValueError:
            return value
        return validate_non_negative_integer(option, val)
    raise TypeError('Wrong type for %s, value must be an non negative integer or a string' % (option,))

def validate_document_class(option, value):
    """Validate the document_class option."""
    if not issubclass(value, (abc.MutableMapping, RawBSONDocument)):
        raise TypeError('%s must be dict, bson.son.SON, bson.raw_bson.RawBSONDocument, or a sublass of collections.MutableMapping' % (option,))
    return value

def validate_type_registry(option, value):
    """Validate the type_registry option."""
    if value is not None and (not isinstance(value, TypeRegistry)):
        raise TypeError('%s must be an instance of %s' % (option, TypeRegistry))
    return value

def validate_is_document_type(option, value):
    """Validate the type of method arguments that expect a MongoDB document."""
    if not isinstance(value, (abc.MutableMapping, RawBSONDocument)):
        raise TypeError('%s must be an instance of dict, bson.son.SON, bson.raw_bson.RawBSONDocument, or a type that inherits from collections.MutableMapping' % (option,))

def validate_driver_or_none(option, value):
    """Validate the driver keyword arg."""
    if value is None:
        return value
    if not isinstance(value, DriverInfo):
        raise TypeError('%s must be an instance of DriverInfo' % (option,))
    return value

def validate_is_callable_or_none(option, value):
    """Validates that 'value' is a callable."""
    if value is None:
        return value
    if not callable(value):
        raise ValueError('%s must be a callable' % (option,))
    return value

def run(cmd, *args, **kwargs):
    """Echo a command before running it.  Defaults to repo as cwd"""
    log.info('> ' + list2cmdline(cmd))
    kwargs.setdefault('cwd', here)
    kwargs.setdefault('shell', sys.platform == 'win32')
    if not isinstance(cmd, list):
        cmd = cmd.split()
    return check_call(cmd, *args, **kwargs)

def is_stale(target, source):
    """Test whether the target file/directory is stale based on the source
    file/directory."""
    if not os.path.exists(target):
        return True
    target_mtime = recursive_mtime(target) or 0
    return compare_recursive_mtime(source, cutoff=target_mtime)

def combine_commands(*commands):
    """Return a Command that combines several commands."""
    class CombinedCommand(Command):
        def initialize_options(self):
            self.commands = []
            for C in commands:
                self.commands.append(C(self.distribution))
            for c in self.commands:
                c.initialize_options()
        def finalize_options(self):
            for c in self.commands:
                c.finalize_options()
        def run(self):
            for c in self.commands:
                c.run()
    return CombinedCommand

def compare_recursive_mtime(path, cutoff, newest=True):
    """Compare the newest/oldest mtime for all files in a directory.
    Cutoff should be another mtime to be compared against. If an mtime that is
    newer/older than the cutoff is found it will return True.
    E.g. if newest=True, and a file in path is newer than the cutoff, it will
    return True."""
    if os.path.isfile(path):
        mt = mtime(path)
        if newest:
            if mt > cutoff:
                return True
        elif mt < cutoff:
            return True
    for dirname, _, filenames in os.walk(path, topdown=False):
        for filename in filenames:
            mt = mtime(os.path.join(dirname, filename))
            if newest:
                if mt > cutoff:
                    return True
            elif mt < cutoff:
                return True
    return False

def recursive_mtime(path, newest=True):
    """Gets the newest/oldest mtime for all files in a directory."""
    if os.path.isfile(path):
        return mtime(path)
    current_extreme = None
    for dirname, _, filenames in os.walk(path, topdown=False):
        for filename in filenames:
            mt = mtime(os.path.join(dirname, filename))
            if newest:
                if mt >= (current_extreme or mt):
                    current_extreme = mt
            elif mt <= (current_extreme or mt):
                current_extreme = mt
    return current_extreme

def run_gradle(path=kernel_path, cmd='build', skip_tests=False):
    """Return a Command for running gradle scripts.

    Parameters
    ----------
    path: str, optional
        The base path of the node package.  Defaults to the repo root.
    cmd: str, optional
        The command to run with gradlew."""
    class Gradle(BaseCommand):
        description = 'Run gradle script'
        def skip_test_option(self, skip):
            if skip:
                return '-Dskip.tests=True'
            else:
                return '-Dskip.tests=False'
        def run(self):
            run([('' if sys.platform == 'win32' else './') + 'gradlew', '--no-daemon', cmd, self.skip_test_option(skip_tests)], cwd=path)
    return Gradle

def wrap_command(cmds, data_dirs, cls, strict=True):
    """Wrap a setup command
    Parameters
    ----------
    cmds: list(str)
        The names of the other commands to run prior to the command.
    strict: boolean, optional
        Wether to raise errors when a pre-command fails."""
    class WrappedCommand(cls):
        def run(self):
            if not getattr(self, 'uninstall', None):
                try:
                    [self.run_command(cmd) for cmd in cmds]
                except Exception:
                    if strict:
                        raise
                    else:
                        pass
            result = cls.run(self)
            data_files = []
            for dname in data_dirs:
                data_files.extend(get_data_files(dname))
            self.distribution.data_files = data_files
            update_package_data(self.distribution)
            return result
    return WrappedCommand

def get_token_from_env():
    """Get the token from env var, VAULT_TOKEN. If not set, attempt to get the token from, ~/.vault-token

    :return: The vault token if set, else None
    :rtype: str | None"""
    token = os.getenv('VAULT_TOKEN')
    if not token:
        token_file_path = os.path.expanduser('~/.vault-token')
        if os.path.exists(token_file_path):
            with open(token_file_path, 'r') as f_in:
                token = f_in.read().strip()
    if not token:
        return None
    return token

def comma_delimited_to_list(list_param):
    """Convert comma-delimited list / string into a list of strings

    :param list_param: Comma-delimited string
    :type list_param: str | unicode
    :return: A list of strings
    :rtype: list"""
    if isinstance(list_param, list):
        return list_param
    if isinstance(list_param, str):
        return list_param.split(',')
    else:
        return []

def handle_cancellation(session: CommandSession):
    """If the input is a string of cancellation word, finish the command session."""
    def control(value):
        if _is_cancellation(value) is True:
            session.finish(render_expression(session.bot.config.SESSION_CANCEL_EXPRESSION))
        return value
    return control

def run(host: Optional[str]=None, port: Optional[int]=None, *args, **kwargs) -> None:
