def context_id(ctx: Context_T, *, mode: str='default', use_hash: bool=False) -> str:
    """Calculate a unique id representing the current context.

    mode:
      default: one id for one context
      group: one id for one group or discuss
      user: one id for one user

    :param ctx: the context dict
    :param mode: unique id mode: "default", "group", or "user"
    :param use_hash: use md5 to hash the id or not"""
    ctx_id = ''
    if mode == 'default':
        if ctx.get('group_id'):
            ctx_id = f"/group/{ctx['group_id']}"
        elif ctx.get('discuss_id'):
            ctx_id = f"/discuss/{ctx['discuss_id']}"
        if ctx.get('user_id'):
            ctx_id += f"/user/{ctx['user_id']}"
    elif mode == 'group':
        if ctx.get('group_id'):
            ctx_id = f"/group/{ctx['group_id']}"
        elif ctx.get('discuss_id'):
            ctx_id = f"/discuss/{ctx['discuss_id']}"
        elif ctx.get('user_id'):
            ctx_id = f"/user/{ctx['user_id']}"
    elif mode == 'user':
        if ctx.get('user_id'):
            ctx_id = f"/user/{ctx['user_id']}"
    if ctx_id and use_hash:
        ctx_id = hashlib.md5(ctx_id.encode('ascii')).hexdigest()
    return ctx_id

def render_expression(expr: Expression_T, *args, escape_args: bool=True, **kwargs) -> str:
    """Render an expression to message string.

    :param expr: expression to render
    :param escape_args: should escape arguments or not
    :param args: positional arguments used in str.format()
    :param kwargs: keyword arguments used in str.format()
    :return: the rendered message"""
    if isinstance(expr, Callable):
        expr = expr(*args, **kwargs)
    elif isinstance(expr, Sequence) and (not isinstance(expr, str)):
        expr = random.choice(expr)
    if escape_args:
        for k, v in kwargs.items():
            if isinstance(v, str):
                kwargs[k] = escape(v)
    return expr.format(*args, **kwargs)

def load_plugins(plugin_dir: str, module_prefix: str) -> int:
    """Find all non-hidden modules or packages in a given directory,
    and import them with the given module prefix.

    :param plugin_dir: plugin directory to search
    :param module_prefix: module prefix used while importing
    :return: number of plugins successfully loaded"""
    count = 0
    for name in os.listdir(plugin_dir):
        path = os.path.join(plugin_dir, name)
        if os.path.isfile(path) and (name.startswith('_') or not name.endswith('.py')):
            continue
        if os.path.isdir(path) and (name.startswith('_') or not os.path.exists(os.path.join(path, '__init__.py'))):
            continue
        m = re.match('([_A-Z0-9a-z]+)(.py)?', name)
        if not m:
            continue
        if load_plugin(f'{module_prefix}.{m.group(1)}'):
            count += 1
    return count

def load_builtin_plugins() -> int:
    """Load built-in plugins distributed along with "nonebot" package."""
    plugin_dir = os.path.join(os.path.dirname(__file__), 'plugins')
    return load_plugins(plugin_dir, 'nonebot.plugins')

def _extract_numbers(arg: Message_T) -> List[float]:
    """Extract all numbers (integers and floats) from a message-like object."""
    s = str(arg)
    return list(map(float, re.findall('[+-]?(\\d*\\.?\\d+|\\d+\\.?\\d*)', s)))

def on_natural_language(keywords: Union[Optional[Iterable], Callable]=None, *, permission: int=perm.EVERYBODY, only_to_me: bool=True, only_short_message: bool=True, allow_empty_message: bool=False) -> Callable:
    """Decorator to register a function as a natural language processor.

    :param keywords: keywords to respond to, if None, respond to all messages
    :param permission: permission required by the processor
    :param only_to_me: only handle messages to me
    :param only_short_message: only handle short messages
    :param allow_empty_message: handle empty messages"""
    def deco(func: Callable) -> Callable:
        nl_processor = NLProcessor(func=func, keywords=keywords, permission=permission, only_to_me=only_to_me, only_short_message=only_short_message, allow_empty_message=allow_empty_message)
        _nl_processors.add(nl_processor)
        return func
    if isinstance(keywords, Callable):
        return on_natural_language()(keywords)
    else:
        return deco

def not_empty(message=None) -> Filter_T:
    """Validate any object to ensure it's not empty (is None or has no elements)."""
    def validate(value):
        if value is None:
            _raise_failure(message)
        if hasattr(value, '__len__') and value.__len__() == 0:
            _raise_failure(message)
        return value
    return validate

def fit_size(min_length: int=0, max_length: int=None, message=None) -> Filter_T:
    """Validate any sized object to ensure the size/length
    is in a given range [min_length, max_length]."""
    def validate(value):
        length = len(value) if value is not None else 0
        if length < min_length or (max_length is not None and length > max_length):
            _raise_failure(message)
        return value
    return validate

def match_regex(pattern: str, message=None, *, flags=0, fullmatch: bool=False) -> Filter_T:
    """Validate any string object to ensure it matches a given pattern."""
    pattern = re.compile(pattern, flags)
    def validate(value):
        if fullmatch:
            if not re.fullmatch(pattern, value):
                _raise_failure(message)
        elif not re.match(pattern, value):
            _raise_failure(message)
        return value
    return validate

def ensure_true(bool_func: Callable[[Any], bool], message=None) -> Filter_T:
    """Validate any object to ensure the result of applying
    a boolean function to it is True."""
    def validate(value):
        if bool_func(value) is not True:
            _raise_failure(message)
        return value
    return validate

def between_inclusive(start=None, end=None, message=None) -> Filter_T:
    """Validate any comparable object to ensure it's between
    `start` and `end` inclusively."""
    def validate(value):
        if start is not None and value < start:
            _raise_failure(message)
        if end is not None and end < value:
            _raise_failure(message)
        return value
    return validate

def check_docstring_first(src, filename='<unknown>'):
    """Returns nonzero if the source has what looks like a docstring that is
    not at the beginning of the source.

    A string will be considered a docstring if it is a STRING token with a
    col offset of 0."""
    found_docstring_line = None
    found_code_line = None
    tok_gen = tokenize_tokenize(io.BytesIO(src).readline)
    for tok_type, _, (sline, scol), _, _ in tok_gen:
        if tok_type == tokenize.STRING and scol == 0:
            if found_docstring_line is not None:
                print('{}:{} Multiple module docstrings (first docstring on line {}).'.format(filename, sline, found_docstring_line))
                return 1
            elif found_code_line is not None:
                print('{}:{} Module docstring appears after code (code seen on line {}).'.format(filename, sline, found_code_line))
                return 1
            else:
                found_docstring_line = sline
        elif tok_type not in NON_CODE_TOKENS and found_code_line is None:
            found_code_line = sline
    return 0

def get_aws_secrets_from_env():
    """Extract AWS secrets from environment variables."""
    keys = set()
    for env_var in ('AWS_SECRET_ACCESS_KEY', 'AWS_SECURITY_TOKEN', 'AWS_SESSION_TOKEN'):
        if env_var in os.environ:
            keys.add(os.environ[env_var])
    return keys

def get_aws_secrets_from_file(credentials_file):
    """Extract AWS secrets from configuration files.

    Read an ini-style configuration file and return a set with all found AWS
    secret access keys."""
    aws_credentials_file_path = os.path.expanduser(credentials_file)
    if not os.path.exists(aws_credentials_file_path):
        return set()
    parser = configparser.ConfigParser()
    try:
        parser.read(aws_credentials_file_path)
    except configparser.MissingSectionHeaderError:
        return set()
    keys = set()
    for section in parser.sections():
        for var in ('aws_secret_access_key', 'aws_security_token', 'aws_session_token'):
            try:
                key = parser.get(section, var).strip()
                if key:
                    keys.add(key)
            except configparser.NoOptionError:
                pass
    return keys

def check_file_for_aws_keys(filenames, keys):
    """Check if files contain AWS secrets.

    Return a list of all files containing AWS secrets and keys found, with all
    but the first four characters obfuscated to ease debugging."""
    bad_files = []
    for filename in filenames:
        with open(filename, 'r') as content:
            text_body = content.read()
            for key in keys:
                if key in text_body:
                    bad_files.append({'filename': filename, 'key': key[:4] + '*' * 28})
    return bad_files

def parse_blocks(lines):
    """Parse and return all possible blocks, popping off the start of `lines`.

    :param lines: list of lines
    :return: list of blocks, where each block is a list of lines"""
    blocks = []
    while lines:
        if lines[0] == '':
            lines.pop(0)
        else:
            blocks.append(parse_block(lines))
    return blocks

def encode_command(*args, buf=None):
    """Encodes arguments into redis bulk-strings array.

    Raises TypeError if any of args not of bytearray, bytes, float, int, or str
    type."""
    if buf is None:
        buf = bytearray()
    buf.extend(b'*%d\r\n' % len(args))
    try:
        for arg in args:
            barg = _converters[type(arg)](arg)
            buf.extend(b'$%d\r\n%s\r\n' % (len(barg), barg))
    except KeyError:
        raise TypeError('Argument {!r} expected to be of bytearray, bytes, float, int, or str type'.format(arg))
    return buf

def fields_to_dict(fields, type_=OrderedDict):
    """Convert a flat list of key/values into an OrderedDict"""
    fields_iterator = iter(fields)
    return type_(zip(fields_iterator, fields_iterator))

def parse_messages_by_stream(messages_by_stream):
    """Parse messages returned by stream

    Messages returned by XREAD arrive in the form:
        [stream_name,
            [
                [message_id, [key1, value1, key2, value2, ...]],
                ...
            ],
            ...
        ]

    Here we parse this into (with the help of the above parse_messages()
    function):

        [
            [stream_name, message_id, OrderedDict(
                (key1, value1),
                (key2, value2),.
                ...
            )],
            ...
        ]"""
    if messages_by_stream is None:
        return []
    parsed = []
    for stream, messages in messages_by_stream:
        for message_id, fields in parse_messages(messages):
            parsed.append((stream, message_id, fields))
    return parsed

def load_schema(name):
    """Load a schema from ./schemas/``name``.json and return it."""
    data = pkgutil.get_data('jsonschema', 'schemas/{0}.json'.format(name))
    return json.loads(data.decode('utf-8'))

def extras_msg(extras):
    """Create an error message for extra items or properties."""
    if len(extras) == 1:
        verb = 'was'
    else:
        verb = 'were'
    return (', '.join((repr(extra) for extra in extras)), verb)

def types_msg(instance, types):
    """Create an error message for a failure to match the given types.

    If the ``instance`` is an object and contains a ``name`` property, it will
    be considered to be a description of that object and used as its type.

    Otherwise the message is simply the reprs of the given ``types``."""
    reprs = []
    for type in types:
        try:
            reprs.append(repr(type['name']))
        except Exception:
            reprs.append(repr(type))
    return '%r is not of type %s' % (instance, ', '.join(reprs))

def flatten(suitable_for_isinstance):
    """isinstance() can accept a bunch of really annoying different types:
        * a single type
        * a tuple of types
        * an arbitrary nested tree of tuples

    Return a flattened tuple of the given argument."""
    types = set()
    if not isinstance(suitable_for_isinstance, tuple):
        suitable_for_isinstance = (suitable_for_isinstance,)
    for thing in suitable_for_isinstance:
        if isinstance(thing, tuple):
            types.update(flatten(thing))
        else:
            types.add(thing)
    return tuple(types)

def uniq(container):
    """Check if all of a container's elements are unique.

    Successively tries first to rely that the elements are hashable, then
    falls back on them being sortable, and finally falls back on brute
    force."""
    try:
        return len(set((unbool(i) for i in container))) == len(container)
    except TypeError:
        try:
            sort = sorted((unbool(i) for i in container))
            sliced = itertools.islice(sort, 1, None)
            for i, j in zip(sort, sliced):
                if i == j:
                    return False
        except (NotImplementedError, TypeError):
            seen = []
            for e in container:
                e = unbool(e)
                if e in seen:
                    return False
                seen.append(e)
    return True

def _generate_legacy_type_checks(types=()):
    """Generate newer-style type checks out of JSON-type-name-to-type mappings.

    Arguments:

        types (dict):

            A mapping of type names to their Python types

    Returns:

        A dictionary of definitions to pass to `TypeChecker`"""
    types = dict(types)
    def gen_type_check(pytypes):
        pytypes = _utils.flatten(pytypes)
        def type_check(checker, instance):
            if isinstance(instance, bool):
                if bool not in pytypes:
                    return False
            return isinstance(instance, pytypes)
        return type_check
    definitions = {}
    for typename, pytypes in iteritems(types):
        definitions[typename] = gen_type_check(pytypes)
    return definitions

def fetch_or_load(spec_path):
    """Fetch a new specification or use the cache if it's current.

    Arguments:

        cache_path:

            the path to a cached specification"""
    headers = {}
    try:
        modified = datetime.utcfromtimestamp(os.path.getmtime(spec_path))
        date = modified.strftime('%a, %d %b %Y %I:%M:%S UTC')
        headers['If-Modified-Since'] = date
    except OSError as error:
        if error.errno != errno.ENOENT:
            raise
    request = urllib.Request(VALIDATION_SPEC, headers=headers)
    response = urllib.urlopen(request, cafile=certifi.where())
    if response.code == 200:
        with open(spec_path, 'w+b') as spec:
            spec.writelines(response)
            spec.seek(0)
            return html.parse(spec)
    with open(spec_path) as spec:
        return html.parse(spec)

def _importAndCheckStack(importName):
    """Import the given name as a module, then walk the stack to determine whether
    the failure was the module not existing, or some code in the module (for
    example a dependent import) failing.  This can be helpful to determine
    whether any actual application code was run.  For example, to distiguish
    administrative error (entering the wrong module name), from programmer
    error (writing buggy code in a module that fails to import).

    @param importName: The name of the module to import.
    @type importName: C{str}
    @raise Exception: if something bad happens.  This can be any type of
        exception, since nobody knows what loading some arbitrary code might
        do.
    @raise _NoModuleFound: if no module was found."""
    try:
        return __import__(importName)
    except ImportError:
        excType, excValue, excTraceback = sys.exc_info()
        while excTraceback:
            execName = excTraceback.tb_frame.f_globals['__name__']
            if execName is None or execName == importName:
                reraise(excValue, excTraceback)
            excTraceback = excTraceback.tb_next
        raise _NoModuleFound()

def connected_edges(G, nodes):
    """Given graph G and list of nodes, return the list of edges that
    are connected to nodes"""
    nodes_in_G = collections.deque()
    for node in nodes:
        if not G.has_node(node):
            continue
        nodes_in_G.extend(nx.node_connected_component(G, node))
    edges = G.subgraph(nodes_in_G).edges()
    return edges

def kwargs_to_matrix(**kwargs):
    """Turn a set of keyword arguments into a transformation matrix."""
    matrix = np.eye(4)
    if 'matrix' in kwargs:
        matrix = kwargs['matrix']
    elif 'quaternion' in kwargs:
        matrix = transformations.quaternion_matrix(kwargs['quaternion'])
    elif 'axis' in kwargs and 'angle' in kwargs:
        matrix = transformations.rotation_matrix(kwargs['angle'], kwargs['axis'])
    else:
        raise ValueError("Couldn't update transform!")
    if 'translation' in kwargs:
        matrix[0:3, 3] += kwargs['translation']
    return matrix

def boolean(meshes, operation='difference'):
    """Run an operation on a set of meshes"""
    script = operation + '(){'
    for i in range(len(meshes)):
        script += 'import("$mesh_' + str(i) + '");'
    script += '}'
    return interface_scad(meshes, script)

def parse_mtl(mtl):
    """Parse a loaded MTL file.

    Parameters
    -------------
    mtl : str or bytes
      Data from an MTL file

    Returns
    ------------
    mtllibs : list of dict
      Each dict has keys: newmtl, map_Kd, Kd"""
    if hasattr(mtl, 'decode'):
        mtl = mtl.decode('utf-8')
    mtllib = None
    mtllibs = []
    for line in str.splitlines(str(mtl).strip()):
        line_split = line.strip().split()
        if len(line_split) <= 1:
            continue
        key = line_split[0]
        if key == 'newmtl':
            if mtllib:
                mtllibs.append(mtllib)
            mtllib = {'newmtl': line_split[1], 'map_Kd': None, 'Kd': None}
        elif key == 'map_Kd':
            mtllib[key] = line_split[1]
        elif key == 'Kd':
            mtllib[key] = [float(x) for x in line_split[1:]]
    if mtllib:
        mtllibs.append(mtllib)
    return mtllibs

def units_from_metadata(obj, guess=True):
    """Try to extract hints from metadata and if that fails
    guess based on the object scale.


    Parameters
    ------------
    obj: object
        Has attributes 'metadata' (dict) and 'scale' (float)
    guess : bool
        If metadata doesn't indicate units, guess from scale

    Returns
    ------------
    units: str
        A guess of what the units might be"""
    for key in ['file_name', 'name']:
        if key not in obj.metadata:
            continue
        hints = obj.metadata[key].lower()
        if 'unit' in hints:
            for delim in '_-.':
                hints = hints.replace(delim, ' ')
            for hint in hints.strip().split():
                if 'unit' not in hint:
                    continue
                hint = hint.replace('units', '').replace('unit', '').strip()
                if hint in TO_INCH:
                    return hint
    if not guess:
        raise ValueError('no units and not allowed to guess')
    log.warning('no units: guessing from scale')
    if float(obj.scale) > 100.0:
        return 'millimeters'
    else:
        return 'inches'

def export_dict(path):
    """Export a path as a dict of kwargs for the Path constructor."""
    export_entities = [e.to_dict() for e in path.entities]
    export_object = {'entities': export_entities, 'vertices': path.vertices.tolist()}
    return export_object

def _write_export(export, file_obj=None):
    """Write a string to a file.
    If file_obj isn't specified, return the string

    Parameters
    ---------
    export: a string of the export data
    file_obj: a file-like object or a filename"""
    if file_obj is None:
        return export
    if hasattr(file_obj, 'write'):
        out_file = file_obj
    else:
        out_file = open(file_obj, 'wb')
    try:
        out_file.write(export)
    except TypeError:
        out_file.write(export.encode('utf-8'))
    out_file.close()
    return export

def _unparse_material(material):
    """Turn a trimesh material into a COLLADA material."""
    if isinstance(material, visual.texture.PBRMaterial):
        diffuse = material.baseColorFactor
        if diffuse is not None:
            diffuse = list(diffuse)
        emission = material.emissiveFactor
        if emission is not None:
            emission = [float(emission[0]), float(emission[1]), float(emission[2]), 1.0]
        shininess = material.roughnessFactor
        if shininess is not None:
            shininess = 2.0 / shininess ** 2 - 2.0
        effect = collada.material.Effect(uuid.uuid4().hex, params=[], shadingtype='phong', diffuse=diffuse, emission=emission, specular=[1.0, 1.0, 1.0], shininess=float(shininess))
        material = collada.material.Material(uuid.uuid4().hex, 'pbrmaterial', effect)
    else:
        effect = collada.material.Effect(uuid.uuid4().hex, params=[], shadingtype='phong')
        material = collada.material.Material(uuid.uuid4().hex, 'defaultmaterial', effect)
    return material

def binomial(n):
    """Return all binomial coefficients for a given order.

    For n > 5, scipy.special.binom is used, below we hardcode
    to avoid the scipy.special dependency.

    Parameters
    --------------
    n : int
      Order

    Returns
    ---------------
    binom : (n + 1,) int
      Binomial coefficients of a given order"""
    if n == 1:
        return [1, 1]
    elif n == 2:
        return [1, 2, 1]
    elif n == 3:
        return [1, 3, 3, 1]
    elif n == 4:
        return [1, 4, 6, 4, 1]
    elif n == 5:
        return [1, 5, 10, 10, 5, 1]
    else:
        from scipy.special import binom
        return binom(n, np.arange(n + 1))

def get_meshes(path='../../../models', cutoff=None):
    """Get a list of single- body meshes to test identifiers on.

    Parameters
    ------------
    path:   str, location of models
    cutoff: int, number of meshes to stop loading at

    Returns
    ------------
    meshes: (n,) list of Trimesh objects"""
    bodies = collections.deque()
    for file_name in os.listdir(path):
        try:
            mesh = trimesh.load(os.path.join(path, file_name))
            split = mesh.split()
            bodies.extend(split)
            if len(split) > 1:
                bodies.append(mesh)
        except BaseException:
            continue
        if cutoff is not None and len(bodies) > cutoff:
            return np.array(bodies)
    for i in range(100):
        cylinder = trimesh.creation.cylinder(radius=np.random.random() * 100, height=np.random.random() * 1000, sections=int(np.clip(np.random.random() * 720, 20, 720)))
        capsule = trimesh.creation.capsule(radius=np.random.random() * 100, height=np.random.random() * 1000, count=np.clip(np.random.random(2) * 720, 20, 720).astype(int))
        bodies.append(cylinder)
        bodies.append(capsule)
    for i in range(10):
        bodies.append(trimesh.creation.random_soup(int(np.clip(np.random.random() * 1000, 20, 1000))))
    bodies.append(trimesh.creation.icosphere())
    bodies.append(trimesh.creation.uv_sphere())
    bodies.append(trimesh.creation.icosahedron())
    return np.array(bodies)

def to_rgba(colors, dtype=np.uint8):
    """Convert a single or multiple RGB colors to RGBA colors.

    Parameters
    ----------
    colors: (n,[3|4]) list of RGB or RGBA colors

    Returns
    ----------
    colors: (n,4) list of RGBA colors
            (4,)  single RGBA color"""
    if not util.is_sequence(colors):
        return
    colors = np.asanyarray(colors)
    opaque = np.iinfo(dtype).max
    if colors.dtype.kind == 'f' and colors.max() < 1.0 + 1e-08:
        colors = (colors * opaque).astype(dtype)
    elif colors.max() <= opaque:
        colors = colors.astype(dtype)
    else:
        raise ValueError('colors non- convertible!')
    if util.is_shape(colors, (-1, 3)):
        colors = np.column_stack((colors, opaque * np.ones(len(colors)))).astype(dtype)
    elif util.is_shape(colors, (3,)):
        colors = np.append(colors, opaque)
    if not (util.is_shape(colors, (4,)) or util.is_shape(colors, (-1, 4))):
        raise ValueError('Colors not of appropriate shape!')
    return colors

def fix_inversion(mesh, multibody=False):
    """Check to see if a mesh has normals pointing "out."

    Parameters
    -------------
    mesh:      Trimesh object
    multibody: bool, if True will try to fix normals on every body

    Alters
    -------------
    mesh.face: may reverse faces"""
    if multibody:
        groups = graph.connected_components(mesh.face_adjacency)
        if len(groups) == 1:
            if mesh.volume < 0.0:
                mesh.invert()
            return
        flip = np.zeros(len(mesh.faces), dtype=np.bool)
        tri = mesh.triangles
        cross = mesh.triangles_cross
        for faces in groups:
            volume = triangles.mass_properties(tri[faces], crosses=cross[faces], skip_inertia=True)['volume']
            if volume < 0.0:
                flip[faces] = True
        if flip.any():
            with mesh._cache:
                if 'face_normals' in mesh._cache:
                    mesh.face_normals[flip] *= -1.0
                mesh.faces[flip] = np.fliplr(mesh.faces[flip])
            mesh._cache.clear(exclude=['face_normals'])
    elif mesh.volume < 0.0:
        mesh.invert()

def quaternion_imag(quaternion):
    """Return imaginary part of quaternion.

    >>> quaternion_imag([3, 0, 1, 2])
    array([0., 1., 2.])"""
    return np.array(quaternion[1:4], dtype=np.float64, copy=True)

def arcball_constrain_to_axis(point, axis):
    """Return sphere point perpendicular to axis."""
    v = np.array(point, dtype=np.float64, copy=True)
    a = np.array(axis, dtype=np.float64, copy=True)
    v -= a * np.dot(a, v)
    n = vector_norm(v)
    if n > _EPS:
        if v[2] < 0.0:
            np.negative(v, v)
        v /= n
        return v
    if a[2] == 1.0:
        return np.array([1.0, 0.0, 0.0])
    return unit_vector([-a[1], a[0], 0.0])

def is_same_quaternion(q0, q1):
    """Return True if two quaternions are equal."""
    q0 = np.array(q0)
    q1 = np.array(q1)
    return np.allclose(q0, q1) or np.allclose(q0, -q1)

def unique_float(data, return_index=False, return_inverse=False, digits=None):
    """Identical to the numpy.unique command, except evaluates floating point
    numbers, using a specified number of digits.

    If digits isn't specified, the library default TOL_MERGE will be used."""
    data = np.asanyarray(data)
    as_int = float_to_int(data, digits)
    _junk, unique, inverse = np.unique(as_int, return_index=True, return_inverse=True)
    if not return_index and (not return_inverse):
        return data[unique]
    result = [data[unique]]
    if return_index:
        result.append(unique)
    if return_inverse:
        result.append(inverse)
    return tuple(result)

def convert_to_vertexlist(geometry, **kwargs):
    """Try to convert various geometry objects to the constructor
    args for a pyglet indexed vertex list.

    Parameters
    ------------
    obj : Trimesh, Path2D, Path3D, (n,2) float, (n,3) float
      Object to render

    Returns
    ------------
    args : tuple
      Args to be passed to pyglet indexed vertex list
      constructor."""
    if util.is_instance_named(geometry, 'Trimesh'):
        return mesh_to_vertexlist(geometry, **kwargs)
    elif util.is_instance_named(geometry, 'Path'):
        return path_to_vertexlist(geometry, **kwargs)
    elif util.is_instance_named(geometry, 'PointCloud'):
        return points_to_vertexlist(geometry.vertices, colors=geometry.colors, **kwargs)
    elif util.is_instance_named(geometry, 'ndarray'):
        return points_to_vertexlist(geometry, **kwargs)
    else:
        raise ValueError('Geometry passed is not a viewable type!')

def is_binary_file(file_obj):
    """Returns True if file has non-ASCII characters (> 0x7F, or 127)
    Should work in both Python 2 and 3"""
    start = file_obj.tell()
    fbytes = file_obj.read(1024)
    file_obj.seek(start)
    is_str = isinstance(fbytes, str)
    for fbyte in fbytes:
        if is_str:
            code = ord(fbyte)
        else:
            code = fbyte
        if code > 127:
            return True
    return False

def type_bases(obj, depth=4):
    """Return the bases of the object passed."""
    bases = collections.deque([list(obj.__class__.__bases__)])
    for i in range(depth):
        bases.append([i.__base__ for i in bases[-1] if i is not None])
    try:
        bases = np.hstack(bases)
    except IndexError:
        bases = []
    bases = [i for i in bases if hasattr(i, '__name__')]
    return np.array(bases)

def zero_pad(data, count, right=True):
    """Parameters
    --------
    data : (n,)
      1D array
    count : int
      Minimum length of result array

    Returns
    --------
    padded : (m,)
      1D array where m >= count"""
    if len(data) == 0:
        return np.zeros(count)
    elif len(data) < count:
        padded = np.zeros(count)
        if right:
            padded[-len(data):] = data
        else:
            padded[:len(data)] = data
        return padded
    else:
        return np.asanyarray(data)

def jsonify(obj, **kwargs):
    """A version of json.dumps that can handle numpy arrays
    by creating a custom encoder for numpy dtypes.

    Parameters
    --------------
    obj : JSON- serializable blob
    **kwargs :
        Passed to json.dumps

    Returns
    --------------
    dumped : str
      JSON dump of obj"""
    class NumpyEncoder(json.JSONEncoder):
        def default(self, obj):
            if hasattr(obj, 'tolist'):
                return obj.tolist()
            return json.JSONEncoder.default(self, obj)
    dumped = json.dumps(obj, cls=NumpyEncoder, **kwargs)
    return dumped

def wrap_as_stream(item):
    """Wrap a string or bytes object as a file object.

    Parameters
    ----------
    item: str or bytes
      Item to be wrapped

    Returns
    ---------
    wrapped: file-like object"""
    if not PY3:
        return StringIO(item)
    if isinstance(item, str):
        return StringIO(item)
    elif isinstance(item, bytes):
        return BytesIO(item)
    raise ValueError('{} is not wrappable!'.format(type(item).__name__))

def decompress(file_obj, file_type):
    """Given an open file object and a file type, return all components
    of the archive as open file objects in a dict.

    Parameters
    -----------
    file_obj : file-like
      Containing compressed data
    file_type : str
      File extension, 'zip', 'tar.gz', etc

    Returns
    ---------
    decompressed : dict
      Data from archive in format {file name : file-like}"""
    def is_zip():
        archive = zipfile.ZipFile(file_obj)
        result = {name: wrap_as_stream(archive.read(name)) for name in archive.namelist()}
        return result
    def is_tar():
        import tarfile
        archive = tarfile.open(fileobj=file_obj, mode='r')
        result = {name: archive.extractfile(name) for name in archive.getnames()}
        return result
    file_type = str(file_type).lower()
    if isinstance(file_obj, bytes):
        file_obj = wrap_as_stream(file_obj)
    if file_type[-3:] == 'zip':
        return is_zip()
    if 'tar' in file_type[-6:]:
        return is_tar()
    raise ValueError('Unsupported type passed!')

def vstack_empty(tup):
    """A thin wrapper for numpy.vstack that ignores empty lists.

    Parameters
    ------------
    tup: tuple or list of arrays with the same number of columns

    Returns
    ------------
    stacked: (n,d) array, with same number of columns as
              constituent arrays."""
    stackable = [i for i in tup if len(i) > 0]
    if len(stackable) == 1:
        return np.asanyarray(stackable[0])
    elif len(stackable) == 0:
        return np.array([])
    return np.vstack(stackable)

def polygons_obb(polygons):
    """Find the OBBs for a list of shapely.geometry.Polygons"""
    rectangles = [None] * len(polygons)
    transforms = [None] * len(polygons)
    for i, p in enumerate(polygons):
        transforms[i], rectangles[i] = polygon_obb(p)
    return (np.array(transforms), np.array(rectangles))

def export_mesh(mesh, file_obj, file_type=None, **kwargs):
    """Export a Trimesh object to a file- like object, or to a filename

    Parameters
    ---------
    file_obj : str, file-like
      Where should mesh be exported to
    file_type : str or None
      Represents file type (eg: 'stl')

    Returns
    ----------
    exported : bytes or str
      Result of exporter"""
    was_opened = False
    if util.is_string(file_obj):
        if file_type is None:
            file_type = str(file_obj).split('.')[-1].lower()
        if file_type in _mesh_exporters:
            was_opened = True
            file_obj = open(file_obj, 'wb')
    file_type = str(file_type).lower()
    if not file_type in _mesh_exporters:
        raise ValueError('%s exporter not available!', file_type)
    if isinstance(mesh, (list, tuple, set, np.ndarray)):
        faces = 0
        for m in mesh:
            faces += len(m.faces)
        log.debug('Exporting %d meshes with a total of %d faces as %s', len(mesh), faces, file_type.upper())
    else:
        log.debug('Exporting %d faces as %s', len(mesh.faces), file_type.upper())
    export = _mesh_exporters[file_type](mesh, **kwargs)
    if hasattr(file_obj, 'write'):
        result = util.write_encoded(file_obj, export)
    else:
        result = export
    if was_opened:
        file_obj.close()
    return result

def export_dict(mesh, encoding=None):
    """Export a mesh to a dict

    Parameters
    ------------
    mesh : Trimesh object
             Mesh to be exported
    encoding : str, or None
                 'base64'

    Returns
    -------------"""
    def encode(item, dtype=None):
        if encoding is None:
            return item.tolist()
        else:
            if dtype is None:
                dtype = item.dtype
            return util.array_to_encoded(item, dtype=dtype, encoding=encoding)
    meta_keys = ['units', 'file_name', 'file_path']
    metadata = {k: v for k, v in mesh.metadata.items() if k in meta_keys}
    export = {'metadata': metadata, 'faces': encode(mesh.faces), 'face_normals': encode(mesh.face_normals), 'vertices': encode(mesh.vertices)}
    if mesh.visual.kind == 'face':
        export['face_colors'] = encode(mesh.visual.face_colors)
    elif mesh.visual.kind == 'vertex':
        export['vertex_colors'] = encode(mesh.visual.vertex_colors)
    return export

def minify(path):
    """Load a javascript file and minify.

    Parameters
    ------------
    path: str, path of resource"""
    if 'http' in path:
        data = requests.get(path).content.decode('ascii', errors='ignore')
    else:
        with open(path, 'rb') as f:
            data = f.read().decode('ascii', errors='ignore')
    if '.min.' in path:
        return data
    try:
        return jsmin.jsmin(data)
    except BaseException:
        return data

def replace_whitespace(text, SAFE_SPACE='|<^>|', insert=True):
    """Replace non-strippable whitepace in a string with a safe space"""
    if insert:
        args = (' ', SAFE_SPACE)
    else:
        args = (SAFE_SPACE, ' ')
    return '\n'.join((line.strip().replace(*args) for line in str.splitlines(text)))

def write_files(template, destination='./dxf'):
    """For a dict, write each value to destination/key"""
    os.makedirs(destination)
    for key, value in template.items():
        with open(os.path.join(destination, key), 'w') as f:
            f.write(replace_whitespace(value, insert=False))

def read_files(path):
    """For a directory full of files, retrieve it
    as a dict with file_name:text"""
    template = {}
    for file_name in os.listdir(path):
        with open(os.path.join(path, file_name), 'r') as f:
            template[file_name] = replace_whitespace(f.read(), insert=True)
    return template

def split_scene(geometry):
    """Given a geometry, list of geometries, or a Scene
    return them as a single Scene object.

    Parameters
    ----------
    geometry : splittable

    Returns
    ---------
    scene: trimesh.Scene"""
    if util.is_instance_named(geometry, 'Scene'):
        return geometry
    if util.is_sequence(geometry):
        metadata = {}
        for g in geometry:
            try:
                metadata.update(g.metadata)
            except BaseException:
                continue
        return Scene(geometry, metadata=metadata)
    split = collections.deque()
    metadata = {}
    for g in util.make_sequence(geometry):
        split.extend(g.split())
        metadata.update(g.metadata)
    if len(split) == 1 and 'file_name' in metadata:
        split = {metadata['file_name']: split[0]}
    scene = Scene(split, metadata=metadata)
    return scene

def deaccent(text):
    """Remove accentuation from the given string."""
    norm = unicodedata.normalize('NFD', text)
    result = ''.join((ch for ch in norm if unicodedata.category(ch) != 'Mn'))
    return unicodedata.normalize('NFC', result)

def tokenize(text, lowercase=False, deacc=False):
    """Iteratively yield tokens as unicode strings, optionally also lowercasing them
    and removing accent marks."""
    if lowercase:
        text = text.lower()
    if deacc:
        text = deaccent(text)
    for match in PAT_ALPHABETIC.finditer(text):
        yield match.group()

def clean_text_by_word(text, language='english', deacc=False, additional_stopwords=None):
    """Tokenizes a given text into words, applying filters and lemmatizing them.
    Returns a dict of word -> syntacticUnit."""
    init_textcleanner(language, additional_stopwords)
    text_without_acronyms = replace_with_separator(text, '', [AB_ACRONYM_LETTERS])
    original_words = list(tokenize(text_without_acronyms, lowercase=True, deacc=deacc))
    filtered_words = filter_words(original_words)
    if HAS_PATTERN:
        tags = tag(' '.join(original_words))
    else:
        tags = None
    units = merge_syntactic_units(original_words, filtered_words, tags)
    return {unit.text: unit for unit in units}

def _get_keywords_with_score(extracted_lemmas, lemma_to_word):
    """:param extracted_lemmas:list of tuples
    :param lemma_to_word: dict of {lemma:list of words}
    :return: dict of {keyword:score}"""
    keywords = {}
    for score, lemma in extracted_lemmas:
        keyword_list = lemma_to_word[lemma]
        for keyword in keyword_list:
            keywords[keyword] = score
    return keywords

def _get_combined_keywords(_keywords, split_text):
    """:param keywords:dict of keywords:scores
    :param split_text: list of strings
    :return: combined_keywords:list"""
    result = []
    _keywords = _keywords.copy()
    len_text = len(split_text)
    for i in range(len_text):
        word = _strip_word(split_text[i])
        if word in _keywords:
            combined_word = [word]
            if i + 1 == len_text:
                result.append(word)
            for j in range(i + 1, len_text):
                other_word = _strip_word(split_text[j])
                if other_word in _keywords and other_word == split_text[j] and (other_word not in combined_word):
                    combined_word.append(other_word)
                else:
                    for keyword in combined_word:
                        _keywords.pop(keyword)
                    result.append(' '.join(combined_word))
                    break
    return result

def _format_results(_keywords, combined_keywords, split, scores):
    """:param keywords:dict of keywords:scores
    :param combined_keywords:list of word/s"""
    combined_keywords.sort(key=lambda w: _get_average_score(w, _keywords), reverse=True)
    if scores:
        return [(word, _get_average_score(word, _keywords)) for word in combined_keywords]
    if split:
        return combined_keywords
    return '\n'.join(combined_keywords)

def pagerank_weighted(graph, initial_value=None, damping=0.85):
    """Calculates PageRank for an undirected graph"""
    if initial_value == None:
        initial_value = 1.0 / len(graph.nodes())
    scores = dict.fromkeys(graph.nodes(), initial_value)
    iteration_quantity = 0
    for iteration_number in range(100):
        iteration_quantity += 1
        convergence_achieved = 0
        for i in graph.nodes():
            rank = 1 - damping
            for j in graph.neighbors(i):
                neighbors_sum = sum((graph.edge_weight((j, k)) for k in graph.neighbors(j)))
                rank += damping * scores[j] * graph.edge_weight((j, i)) / neighbors_sum
            if abs(scores[i] - rank) <= CONVERGENCE_THRESHOLD:
                convergence_achieved += 1
            scores[i] = rank
        if convergence_achieved == len(graph.nodes()):
            break
    return scores

