    return lookup

def open_as_needed(filename):
    """Return a file-object given either a filename or an object.

    Handles opening with the right class based on the file extension."""
    if hasattr(filename, 'read'):
        return filename
    if filename.endswith('.bz2'):
        return bz2.BZ2File(filename, 'rb')
    elif filename.endswith('.gz'):
        return gzip.GzipFile(filename, 'rb')
    else:
        return open(filename, 'rb')

def _check_and_flip(arr):
    """Transpose array or list of arrays if they are 2D."""
    if hasattr(arr, 'ndim'):
        if arr.ndim >= 2:
            return arr.T
        else:
            return arr
    elif not is_string_like(arr) and iterable(arr):
        return tuple((_check_and_flip(a) for a in arr))
    else:
        return arr

def ensure_yx_order(func):
    """Wrap a function to ensure all array arguments are y, x ordered, based on kwarg."""
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        dim_order = kwargs.pop('dim_order', None)
        x_first = _is_x_first_dim(dim_order)
        if x_first:
            args = tuple((_check_and_flip(arr) for arr in args))
            for k, v in kwargs:
                kwargs[k] = _check_and_flip(v)
        ret = func(*args, **kwargs)
        if x_first:
            return _check_and_flip(ret)
        else:
            return ret
    dim_order_doc = "\n    dim_order : str or ``None``, optional\n        The ordering of dimensions in passed in arrays. Can be one of ``None``, ``'xy'``,\n        or ``'yx'``. ``'xy'`` indicates that the dimension corresponding to x is the leading\n        dimension, followed by y. ``'yx'`` indicates that x is the last dimension, preceded\n        by y. ``None`` indicates that the default ordering should be assumed,\n        which is 'yx'. Can only be passed as a keyword argument, i.e.\n        func(..., dim_order='xy')."
    params = wrapper.__doc__.find('Parameters')
    blank = wrapper.__doc__.find('\n\n', params)
    wrapper.__doc__ = wrapper.__doc__[:blank] + dim_order_doc + wrapper.__doc__[blank:]
    return wrapper

def broadcast_indices(x, minv, ndim, axis):
    """Calculate index values to properly broadcast index array within data array.

    See usage in interp."""
    ret = []
    for dim in range(ndim):
        if dim == axis:
            ret.append(minv)
        else:
            broadcast_slice = [np.newaxis] * ndim
            broadcast_slice[dim] = slice(None)
            dim_inds = np.arange(x.shape[dim])
            ret.append(dim_inds[tuple(broadcast_slice)])
    return tuple(ret)

def bzip_blocks_decompress_all(data):
    """Decompress all of the bzip2-ed blocks.

    Returns the decompressed data as a `bytearray`."""
    frames = bytearray()
    offset = 0
    while offset < len(data):
        size_bytes = data[offset:offset + 4]
        offset += 4
        block_cmp_bytes = abs(Struct('>l').unpack(size_bytes)[0])
        try:
            frames.extend(bz2.decompress(data[offset:offset + block_cmp_bytes]))
            offset += block_cmp_bytes
        except IOError:
            if frames:
                logging.warning('Error decompressing bz2 block stream at offset: %d', offset - 4)
                break
            else:
                raise ValueError('Not a bz2 stream.')
    return frames

def nexrad_to_datetime(julian_date, ms_midnight):
    """Convert NEXRAD date time format to python `datetime.datetime`."""
    return datetime.datetime.utcfromtimestamp((julian_date - 1) * day + ms_midnight * milli)

def remap_status(val):
    """Convert status integer value to appropriate bitmask."""
    status = 0
    bad = BAD_DATA if val & 240 else 0
    val &= 15
    if val == 0:
        status = START_ELEVATION
    elif val == 1:
        status = 0
    elif val == 2:
        status = END_ELEVATION
    elif val == 3:
        status = START_ELEVATION | START_VOLUME
    elif val == 4:
        status = END_ELEVATION | END_VOLUME
    elif val == 5:
        status = START_ELEVATION | LAST_ELEVATION
    return status | bad

def reduce_lists(d):
    """Replace single item lists in a dictionary with the single item."""
    for field in d:
        old_data = d[field]
        if len(old_data) == 1:
            d[field] = old_data[0]

def float16(val):
    """Convert a 16-bit floating point value to a standard Python float."""
    frac = val & 1023
    exp = val >> 10 & 31
    sign = val >> 15
    if exp:
        value = 2 ** (exp - 16) * (1 + float(frac) / 2 ** 10)
    else:
        value = float(frac) / 2 ** 9
    if sign:
        value *= -1
    return value

def date_elem(ind_days, ind_minutes):
    """Create a function to parse a datetime from the product-specific blocks."""
    def inner(seq):
        return nexrad_to_datetime(seq[ind_days], seq[ind_minutes] * 60 * 1000)
    return inner

def combine_elem(ind1, ind2):
    """Create a function to combine two specified product-specific blocks into a single int."""
    def inner(seq):
        shift = 2 ** 16
        if seq[ind1] < 0:
            seq[ind1] += shift
        if seq[ind2] < 0:
            seq[ind2] += shift
        return seq[ind1] << 16 | seq[ind2]
    return inner

def _parcel_profile_helper(pressure, temperature, dewpt):
    """Help calculate parcel profiles.

    Returns the temperature and pressure, above, below, and including the LCL. The
    other calculation functions decide what to do with the pieces."""
    press_lcl, temp_lcl = lcl(pressure[0], temperature, dewpt)
    press_lcl = press_lcl.to(pressure.units)
    press_lower = concatenate((pressure[pressure >= press_lcl], press_lcl))
    temp_lower = dry_lapse(press_lower, temperature)
    if _greater_or_close(np.nanmin(pressure), press_lcl.m):
        return (press_lower[:-1], press_lcl, np.array([]) * press_lower.units, temp_lower[:-1], temp_lcl, np.array([]) * temp_lower.units)
    press_upper = concatenate((press_lcl, pressure[pressure < press_lcl]))
    temp_upper = moist_lapse(press_upper, temp_lower[-1]).to(temp_lower.units)
    return (press_lower[:-1], press_lcl, press_upper[1:], temp_lower[:-1], temp_lcl, temp_upper[1:])

