def get_default_algorithms():
    """Returns the algorithms that are implemented by the library."""
    default_algorithms = {'none': NoneAlgorithm(), 'HS256': HMACAlgorithm(HMACAlgorithm.SHA256), 'HS384': HMACAlgorithm(HMACAlgorithm.SHA384), 'HS512': HMACAlgorithm(HMACAlgorithm.SHA512)}
    if has_crypto:
        default_algorithms.update({'RS256': RSAAlgorithm(RSAAlgorithm.SHA256), 'RS384': RSAAlgorithm(RSAAlgorithm.SHA384), 'RS512': RSAAlgorithm(RSAAlgorithm.SHA512), 'ES256': ECAlgorithm(ECAlgorithm.SHA256), 'ES384': ECAlgorithm(ECAlgorithm.SHA384), 'ES521': ECAlgorithm(ECAlgorithm.SHA512), 'ES512': ECAlgorithm(ECAlgorithm.SHA512), 'PS256': RSAPSSAlgorithm(RSAPSSAlgorithm.SHA256), 'PS384': RSAPSSAlgorithm(RSAPSSAlgorithm.SHA384), 'PS512': RSAPSSAlgorithm(RSAPSSAlgorithm.SHA512)})
    return default_algorithms

def info():
    """Generate information for a bug report.
    Based on the requests package help utility module."""
    try:
        platform_info = {'system': platform.system(), 'release': platform.release()}
    except IOError:
        platform_info = {'system': 'Unknown', 'release': 'Unknown'}
    implementation = platform.python_implementation()
    if implementation == 'CPython':
        implementation_version = platform.python_version()
    elif implementation == 'PyPy':
        implementation_version = '%s.%s.%s' % (sys.pypy_version_info.major, sys.pypy_version_info.minor, sys.pypy_version_info.micro)
        if sys.pypy_version_info.releaselevel != 'final':
            implementation_version = ''.join([implementation_version, sys.pypy_version_info.releaselevel])
    else:
        implementation_version = 'Unknown'
    return {'platform': platform_info, 'implementation': {'name': implementation, 'version': implementation_version}, 'cryptography': {'version': getattr(cryptography, '__version__', '')}, 'pyjwt': {'version': pyjwt_version}}

def find_providers():
    """Find all providers registered in Lexicon, and their availability"""
    providers_list = sorted({modname for _, modname, _ in pkgutil.iter_modules(providers.__path__) if modname != 'base'})
    try:
        distribution = pkg_resources.get_distribution('dns-lexicon')
    except pkg_resources.DistributionNotFound:
        return {provider: True for provider in providers_list}
    else:
        return {provider: _resolve_requirements(provider, distribution) for provider in providers_list}

def generate_list_table_result(lexicon_logger, output=None, without_header=None):
    """Convert returned data from list actions into a nice table for command line usage"""
    if not isinstance(output, list):
        lexicon_logger.debug('Command output is not a list, and then cannot be printed with --quiet parameter not enabled.')
        return None
    array = [[row.get('id', ''), row.get('type', ''), row.get('name', ''), row.get('content', ''), row.get('ttl', '')] for row in output]
    if not without_header:
        headers = ['ID', 'TYPE', 'NAME', 'CONTENT', 'TTL']
        array.insert(0, headers)
    column_widths = [0, 0, 0, 0, 0]
    for row in array:
        for idx, col in enumerate(row):
            width = len(str(col))
            if width > column_widths[idx]:
                column_widths[idx] = width
    if not without_header:
        array.insert(1, ['-' * column_widths[idx] for idx in range(len(column_widths))])
    table = []
    for row in array:
        row_list = []
        for idx, col in enumerate(row):
            row_list.append(str(col).ljust(column_widths[idx]))
        table.append(' '.join(row_list))
    return os.linesep.join(table)

def generate_table_results(output=None, without_header=None):
    """Convert returned data from non-list actions into a nice table for command line usage"""
    array = []
    str_output = str(output)
    if not without_header:
        array.append('RESULT')
        array.append('-' * max(6, len(str_output)))
    array.append(str_output)
    return os.linesep.join(array)

def handle_output(results, output_type, action):
    """Print the relevant output for given output_type"""
    if output_type == 'QUIET':
        return
    if not output_type == 'JSON':
        if action == 'list':
            table = generate_list_table_result(logger, results, output_type == 'TABLE-NO-HEADER')
        else:
            table = generate_table_results(results, output_type == 'TABLE-NO-HEADER')
        if table:
            print(table)
    else:
        try:
            json_str = json.dumps(results)
            if json_str:
                print(json_str)
        except TypeError:
            logger.debug('Output is not JSON serializable, and then cannot be printed with --output=JSON parameter.')

def get_model(app, model):
    """Wrapper around django's get_model."""
    if 'get_model' not in _LAZY_LOADS:
        _lazy_load_get_model()
    _get_model = _LAZY_LOADS['get_model']
    return _get_model(app, model)

def _lazy_load_get_model():
    """Lazy loading of get_model.

    get_model loads django.conf.settings, which may fail if
    the settings haven't been configured yet."""
    if django is None:
        def _get_model(app, model):
            raise import_failure
    else:
        from django import apps as django_apps
        _get_model = django_apps.apps.get_model
    _LAZY_LOADS['get_model'] = _get_model

def resolve_attribute(name, bases, default=None):
    """Find the first definition of an attribute according to MRO order."""
    for base in bases:
        if hasattr(base, name):
            return getattr(base, name)
    return default

