def deepgetattr(obj, name, default=_UNSPECIFIED):
    """Try to retrieve the given attribute of an object, digging on '.'.

    This is an extended getattr, digging deeper if '.' is found.

    Args:
        obj (object): the object of which an attribute should be read
        name (str): the name of an attribute to look up.
        default (object): the default value to use if the attribute wasn't found

    Returns:
        the attribute pointed to by 'name', splitting on '.'.

    Raises:
        AttributeError: if obj has no 'name' attribute."""
    try:
        if '.' in name:
            attr, subname = name.split('.', 1)
            return deepgetattr(getattr(obj, attr), subname, default)
        else:
            return getattr(obj, name)
    except AttributeError:
        if default is _UNSPECIFIED:
            raise
        else:
            return default

def wait_for_server(host, port, cancel_event=None):
    """Blocks until a local server is listening on the specified
    host and port. Set cancel_event to cancel the wait.

    This is intended to be used in conjunction with running
    the Flask server."""
    while not is_server_running(host, port):
        if cancel_event and cancel_event.is_set():
            return False
        time.sleep(0.1)
    return True

def wait_and_start_browser(host, port=None, cancel_event=None):
    """Waits for the server to run and then opens the specified address in
    the browser. Set cancel_event to cancel the wait."""
    if host == '0.0.0.0':
        host = 'localhost'
    if port is None:
        port = 80
    if wait_for_server(host, port, cancel_event):
        start_browser('http://{0}:{1}/'.format(host, port))

def create_app(path=None, user_content=False, context=None, username=None, password=None, render_offline=False, render_wide=False, render_inline=False, api_url=None, title=None, text=None, autorefresh=None, quiet=None, grip_class=None):
    """Creates a Grip application with the specified overrides."""
    if grip_class is None:
        grip_class = Grip
    if text is not None:
        display_filename = DirectoryReader(path, True).filename_for(None)
        source = TextReader(text, display_filename)
    elif path == '-':
        source = StdinReader()
    else:
        source = DirectoryReader(path)
    if render_offline:
        renderer = OfflineRenderer(user_content, context)
    elif user_content or context or api_url:
        renderer = GitHubRenderer(user_content, context, api_url)
    else:
        renderer = None
    auth = (username, password) if username or password else None
    return grip_class(source, auth, renderer, None, render_wide, render_inline, title, autorefresh, quiet)

def render_page(path=None, user_content=False, context=None, username=None, password=None, render_offline=False, render_wide=False, render_inline=False, api_url=None, title=None, text=None, quiet=None, grip_class=None):
    """Renders the specified markup text to an HTML page and returns it."""
    return create_app(path, user_content, context, username, password, render_offline, render_wide, render_inline, api_url, title, text, False, quiet, grip_class).render()

def render_content(text, user_content=False, context=None, username=None, password=None, render_offline=False, api_url=None):
    """Renders the specified markup and returns the result."""
    renderer = GitHubRenderer(user_content, context, api_url) if not render_offline else OfflineRenderer(user_content, context)
    auth = (username, password) if username or password else None
    return renderer.render(text, auth)

def export(path=None, user_content=False, context=None, username=None, password=None, render_offline=False, render_wide=False, render_inline=True, out_filename=None, api_url=None, title=None, quiet=False, grip_class=None):
    """Exports the rendered HTML to a file."""
    export_to_stdout = out_filename == '-'
    if out_filename is None:
        if path == '-':
            export_to_stdout = True
        else:
            filetitle, _ = os.path.splitext(os.path.relpath(DirectoryReader(path).root_filename))
            out_filename = '{0}.html'.format(filetitle)
    if not export_to_stdout and (not quiet):
        print('Exporting to', out_filename, file=sys.stderr)
    page = render_page(path, user_content, context, username, password, render_offline, render_wide, render_inline, api_url, title, None, quiet, grip_class)
    if export_to_stdout:
        try:
            print(page)
        except IOError as ex:
            if ex.errno != 0 and ex.errno != errno.EPIPE:
                raise
    else:
        with io.open(out_filename, 'w', encoding='utf-8') as f:
            f.write(page)

def fix_val(value):
    """Make a FIX value from a string, bytes, or number."""
    if type(value) == bytes:
        return value
    if sys.version_info[0] == 2:
        return bytes(value)
    elif type(value) == str:
        return bytes(value, 'UTF-8')
    else:
        return bytes(str(value), 'ASCII')

def fix_tag(value):
    """Make a FIX tag value from string, bytes, or integer."""
    if sys.version_info[0] == 2:
        return bytes(value)
    else:
        if type(value) == bytes:
            return value
        elif type(value) == str:
            return value.encode('ASCII')
        return str(value).encode('ASCII')

def is_suspicious(pe):
    """unusual locations of import tables
    non recognized section names
    presence of long ASCII strings"""
    relocations_overlap_entry_point = False
    sequential_relocs = 0
    if hasattr(pe, 'DIRECTORY_ENTRY_BASERELOC'):
        for base_reloc in pe.DIRECTORY_ENTRY_BASERELOC:
            last_reloc_rva = None
            for reloc in base_reloc.entries:
                if reloc.rva <= pe.OPTIONAL_HEADER.AddressOfEntryPoint <= reloc.rva + 4:
                    relocations_overlap_entry_point = True
                if last_reloc_rva is not None and last_reloc_rva <= reloc.rva <= last_reloc_rva + 4:
                    sequential_relocs += 1
                last_reloc_rva = reloc.rva
    warnings_while_parsing = False
    warnings = pe.get_warnings()
    if warnings:
        warnings_while_parsing
    pass

def _read_doc():
    """Parse docstring from file 'pefile.py' and avoid importing
    this module directly."""
    if sys.version_info.major == 2:
        with open('pefile.py', 'r') as f:
            tree = ast.parse(f.read())
    else:
        with open('pefile.py', 'r', encoding='utf-8') as f:
            tree = ast.parse(f.read())
    return ast.get_docstring(tree)

def _read_attr(attr_name):
    """Parse attribute from file 'pefile.py' and avoid importing
    this module directly.

    __version__, __author__, __contact__,"""
    regex = attr_name + "\\s+=\\s+'(.+)'"
    if sys.version_info.major == 2:
        with open('pefile.py', 'r') as f:
            match = re.search(regex, f.read())
    else:
        with open('pefile.py', 'r', encoding='utf-8') as f:
            match = re.search(regex, f.read())
    return match.group(1)

def ordLookup(libname, ord_val, make_name=False):
    """Lookup a name for the given ordinal if it's in our
    database."""
    names = ords.get(libname.lower())
    if names is None:
        if make_name is True:
            return formatOrdString(ord_val)
        return None
    name = names.get(ord_val)
    if name is None:
        return formatOrdString(ord_val)
    return name

def smart_unicode(s, encoding='utf-8', strings_only=False, errors='strict'):
    """Returns a unicode object representing 's'. Treats bytestrings using the
    'encoding' codec.

    If strings_only is True, don't convert (some) non-string-like objects."""
    return force_unicode(s, encoding, strings_only, errors)

def is_protected_type(obj):
    """Determine if the object instance is of a protected type.

    Objects of protected types are preserved as-is when passed to
    force_unicode(strings_only=True)."""
    return isinstance(obj, (types.NoneType, int, long, datetime.datetime, datetime.date, datetime.time, float, Decimal))

def smart_str(s, encoding='utf-8', strings_only=False, errors='strict'):
    """Returns a bytestring version of 's', encoded as specified in 'encoding'.

    If strings_only is True, don't convert (some) non-string-like objects."""
    if strings_only and isinstance(s, (types.NoneType, int)):
        return s
    if not isinstance(s, basestring):
        try:
            return str(s)
        except UnicodeEncodeError:
            if isinstance(s, Exception):
                return ' '.join([smart_str(arg, encoding, strings_only, errors) for arg in s])
            return unicode(s).encode(encoding, errors)
    elif isinstance(s, unicode):
        return s.encode(encoding, errors)
    elif s and encoding != 'utf-8':
        return s.decode('utf-8', errors).encode(encoding, errors)
    else:
        return s

def _weighted_pearson(y, y_pred, w):
    """Calculate the weighted Pearson correlation coefficient."""
    with np.errstate(divide='ignore', invalid='ignore'):
        y_pred_demean = y_pred - np.average(y_pred, weights=w)
        y_demean = y - np.average(y, weights=w)
        corr = np.sum(w * y_pred_demean * y_demean) / np.sum(w) / np.sqrt(np.sum(w * y_pred_demean ** 2) * np.sum(w * y_demean ** 2) / np.sum(w) ** 2)
    if np.isfinite(corr):
        return np.abs(corr)
    return 0.0

def _weighted_spearman(y, y_pred, w):
    """Calculate the weighted Spearman correlation coefficient."""
    y_pred_ranked = np.apply_along_axis(rankdata, 0, y_pred)
    y_ranked = np.apply_along_axis(rankdata, 0, y)
    return _weighted_pearson(y_pred_ranked, y_ranked, w)

def _mean_absolute_error(y, y_pred, w):
    """Calculate the mean absolute error."""
    return np.average(np.abs(y_pred - y), weights=w)

def _mean_square_error(y, y_pred, w):
    """Calculate the mean square error."""
    return np.average((y_pred - y) ** 2, weights=w)

def _root_mean_square_error(y, y_pred, w):
    """Calculate the root mean square error."""
    return np.sqrt(np.average((y_pred - y) ** 2, weights=w))

def _protected_division(x1, x2):
    """Closure of division (x1/x2) for zero denominator."""
    with np.errstate(divide='ignore', invalid='ignore'):
        return np.where(np.abs(x2) > 0.001, np.divide(x1, x2), 1.0)

def _protected_log(x1):
    """Closure of log for zero arguments."""
    with np.errstate(divide='ignore', invalid='ignore'):
        return np.where(np.abs(x1) > 0.001, np.log(np.abs(x1)), 0.0)

def _protected_inverse(x1):
    """Closure of log for zero arguments."""
    with np.errstate(divide='ignore', invalid='ignore'):
        return np.where(np.abs(x1) > 0.001, 1.0 / x1, 0.0)

def _sim_colour(r1, r2):
    """calculate the sum of histogram intersection of colour"""
    return sum([min(a, b) for a, b in zip(r1['hist_c'], r2['hist_c'])])

def _sim_texture(r1, r2):
    """calculate the sum of histogram intersection of texture"""
    return sum([min(a, b) for a, b in zip(r1['hist_t'], r2['hist_t'])])

def _enforce_width(text, width, unicode_aware=True):
    """Enforce a displayed piece of text to be a certain number of cells wide.  This takes into
    account double-width characters used in CJK languages.

    :param text: The text to be truncated
    :param width: The screen cell width to enforce
    :return: The resulting truncated text"""
    if 2 * len(text) < width:
        return text
    if unicode_aware:
        size = 0
        for i, c in enumerate(text):
            w = wcwidth(c) if ord(c) >= 256 else 1
            if size + w > width:
                return text[0:i]
            size += w
    elif len(text) + 1 > width:
        return text[0:width]
    return text

def _get_offset(text, visible_width, unicode_aware=True):
    """Find the character offset within some text for a given visible offset (taking into account the
    fact that some character glyphs are double width).

    :param text: The text to analyze
    :param visible_width: The required location within that text (as seen on screen).
    :return: The offset within text (as a character offset within the string)."""
    result = 0
    width = 0
    if unicode_aware:
        for c in text:
            if visible_width - width <= 0:
                break
            result += 1
            width += wcwidth(c)
        if visible_width - width < 0:
            result -= 1
    else:
        result = min(len(text), visible_width)
    return result

def _split_text(text, width, height, unicode_aware=True):
    """Split text to required dimensions.

    This will first try to split the text into multiple lines, then put a "..." on the last
    3 characters of the last line if this still doesn't fit.

    :param text: The text to split.
    :param width: The maximum width for any line.
    :param height: The maximum height for the resulting text.
    :return: A list of strings of the broken up text."""
    tokens = text.split(' ')
    result = []
    current_line = ''
    string_len = wcswidth if unicode_aware else len
    for token in tokens:
        for i, line_token in enumerate(token.split('\n')):
            if string_len(current_line + line_token) > width or i > 0:
                if len(current_line) > 0:
                    result.append(current_line.rstrip())
                current_line = line_token + ' '
            else:
                current_line += line_token + ' '
    current_line = current_line.rstrip()
    while string_len(current_line) > 0:
        new_line = _enforce_width(current_line, width, unicode_aware)
        result.append(new_line)
        current_line = current_line[len(new_line):]
    if len(result) > height:
        result = result[:height]
        result[height - 1] = result[height - 1][:width - 3] + '...'
    for i, line in enumerate(result):
        if len(line) > width:
            result[i] = line[:width - 3] + '...'
    return result

def readable_mem(mem):
    """:param mem: An integer number of bytes to convert to human-readable form.
    :return: A human-readable string representation of the number."""
    for suffix in ['', 'K', 'M', 'G', 'T']:
        if mem < 10000:
            return '{}{}'.format(int(mem), suffix)
        mem /= 1024
    return '{}P'.format(int(mem))

def readable_timestamp(stamp):
    """:param stamp: A floating point number representing the POSIX file timestamp.
    :return: A short human-readable string representation of the timestamp."""
    if date.fromtimestamp(stamp) == date.today():
        return str(datetime.fromtimestamp(stamp).strftime('%I:%M:%S%p'))
    else:
        return str(date.fromtimestamp(stamp))

def cli(location, **kwargs):
    """Geocode an arbitrary number of strings from Command Line."""
    locations = []
    try:
        for line in fileinput.input():
            locations.append(line.strip())
    except:
        pass
    for item in location:
        if os.path.exists(item):
            with open(item, 'rb') as f:
                locations += f.read().splitlines()
        else:
            locations.append(item)
    if kwargs['distance']:
        d = geocoder.distance(locations, **kwargs)
        click.echo(d)
        return
    for location in locations:
        g = geocoder.get(location.strip(), **kwargs)
        try:
            click.echo(json.dumps(getattr(g, kwargs['output'])))
        except IOError:
            return

def get(location, **kwargs):
    """Get Geocode

    :param ``location``: Your search location you want geocoded.
    :param ``provider``: The geocoding engine you want to use.

    :param ``method``: Define the method (geocode, method)."""
    provider = kwargs.get('provider', 'bing').lower().strip()
    method = kwargs.get('method', 'geocode').lower().strip()
    if isinstance(location, (list, dict)) and method == 'geocode':
        raise ValueError('Location should be a string')
    if provider not in options:
        raise ValueError('Invalid provider')
    elif method not in options[provider]:
        raise ValueError('Invalid method')
    return options[provider][method](location, **kwargs)

def modelresource_factory(model, resource_class=ModelResource):
    """Factory for creating ``ModelResource`` class for given Django model."""
    attrs = {'model': model}
    Meta = type(str('Meta'), (object,), attrs)
    class_name = model.__name__ + str('Resource')
    class_attrs = {'Meta': Meta}
    metaclass = ModelDeclarativeMetaclass
    return metaclass(class_name, (resource_class,), class_attrs)

