def validate_schema(sconf):
    """Return True if config schema is correct.

    Parameters
    ----------
    sconf : dict
        session configuration

    Returns
    -------
    bool"""
    if 'session_name' not in sconf:
        raise exc.ConfigError('config requires "session_name"')
    if 'windows' not in sconf:
        raise exc.ConfigError('config requires list of "windows"')
    for window in sconf['windows']:
        if 'window_name' not in window:
            raise exc.ConfigError('config window is missing "window_name"')
        if 'panes' not in window:
            raise exc.ConfigError('config window %s requires list of panes' % window['window_name'])
    return True

def inline(sconf):
    """Return config in inline form, opposite of :meth:`config.expand`.

    Parameters
    ----------
    sconf : dict

    Returns
    -------
    dict
        configuration with optional inlined configs."""
    if 'shell_command' in sconf and isinstance(sconf['shell_command'], list) and (len(sconf['shell_command']) == 1):
        sconf['shell_command'] = sconf['shell_command'][0]
        if len(sconf.keys()) == int(1):
            sconf = sconf['shell_command']
    if 'shell_command_before' in sconf and isinstance(sconf['shell_command_before'], list) and (len(sconf['shell_command_before']) == 1):
        sconf['shell_command_before'] = sconf['shell_command_before'][0]
    if 'windows' in sconf:
        sconf['windows'] = [inline(window) for window in sconf['windows']]
    if 'panes' in sconf:
        sconf['panes'] = [inline(pane) for pane in sconf['panes']]
    return sconf

def run_before_script(script_file, cwd=None):
    """Function to wrap try/except for subprocess.check_call()."""
    try:
        proc = subprocess.Popen(shlex.split(str(script_file)), stderr=subprocess.PIPE, stdout=subprocess.PIPE, cwd=cwd)
        for line in iter(proc.stdout.readline, b''):
            sys.stdout.write(console_to_str(line))
        proc.wait()
        if proc.returncode:
            stderr = proc.stderr.read()
            proc.stderr.close()
            stderr = console_to_str(stderr).split('\n')
            stderr = '\n'.join(list(filter(None, stderr)))
            raise exc.BeforeLoadScriptError(proc.returncode, os.path.abspath(script_file), stderr)
        return proc.returncode
    except OSError as e:
        if e.errno == 2:
            raise exc.BeforeLoadScriptNotExists(e, os.path.abspath(script_file))
        else:
            raise e

