        context = econtext.router._connect(klass=stream_by_method_name(method_name), name=name, **kwargs)
    except mitogen.core.StreamError:
        return {u'id': None, u'name': None, u'msg': 'error occurred on host %s: %s' % (socket.gethostname(), sys.exc_info()[1])}
