def parse_script_interpreter(source):
    """Parse the script interpreter portion of a UNIX hashbang using the rules
    Linux uses.

    :param str source: String like "/usr/bin/env python".

    :returns:
        Tuple of `(interpreter, arg)`, where `intepreter` is the script
        interpreter and `arg` is its sole argument if present, otherwise
        :py:data:`None`."""
    nl = source.find(b'\n', 0, 128)
    if nl == -1:
        nl = min(128, len(source))
    bits = source[0:nl].strip().split(None, 1)
    if len(bits) == 1:
        return (mitogen.core.to_text(bits[0]), None)
    return (mitogen.core.to_text(bits[0]), mitogen.core.to_text(bits[1]))

def pack_rgb(rgb):
    """Packs a 24-bit RGB triples into a single integer,
    works on both arrays and tuples."""
    orig_shape = None
    if isinstance(rgb, np.ndarray):
        assert rgb.shape[-1] == 3
        orig_shape = rgb.shape[:-1]
    else:
        assert len(rgb) == 3
        rgb = np.array(rgb)
    rgb = rgb.astype(int).reshape((-1, 3))
    packed = rgb[:, 0] << 16 | rgb[:, 1] << 8 | rgb[:, 2]
    if orig_shape is None:
        return packed
    else:
        return packed.reshape(orig_shape)

def unpack_rgb(packed):
    """Unpacks a single integer or array of integers into one or more
    24-bit RGB values.

    """
    orig_shape = None
    if isinstance(packed, np.ndarray):
        assert packed.dtype == int
        orig_shape = packed.shape
        packed = packed.reshape((-1, 1))
    rgb = (packed >> 16 & 255, packed >> 8 & 255, packed & 255)
    if orig_shape is None:
        return rgb
    else:
        return np.hstack(rgb).reshape(orig_shape + (3,))

def load(input_filename):
    """Load an image with Pillow and convert it to numpy array. Also
    returns the image DPI in x and y as a tuple."""
    try:
        pil_img = Image.open(input_filename)
    except IOError:
        sys.stderr.write('warning: error opening {}\n'.format(input_filename))
        return (None, None)
    if pil_img.mode != 'RGB':
        pil_img = pil_img.convert('RGB')
    if 'dpi' in pil_img.info:
        dpi = pil_img.info['dpi']
    else:
        dpi = (300, 300)
    img = np.array(pil_img)
    return (img, dpi)

def get_palette(samples, options, return_mask=False, kmeans_iter=40):
    """Extract the palette for the set of sampled RGB values. The first
    palette entry is always the background color; the rest are determined
    from foreground pixels by running K-means clustering. Returns the
    palette, as well as a mask corresponding to the foreground pixels.

    """
    if not options.quiet:
        print('  getting palette...')
    bg_color = get_bg_color(samples, 6)
    fg_mask = get_fg_mask(bg_color, samples, options)
    centers, _ = kmeans(samples[fg_mask].astype(np.float32), options.num_colors - 1, iter=kmeans_iter)
    palette = np.vstack((bg_color, centers)).astype(np.uint8)
    if not return_mask:
        return palette
    else:
        return (palette, fg_mask)

def emit_pdf(outputs, options):
    """Runs the PDF conversion command to generate the PDF."""
    cmd = options.pdf_cmd
    cmd = cmd.replace('%o', options.pdfname)
    if len(outputs) > 2:
        cmd_print = cmd.replace('%i', ' '.join(outputs[:2] + ['...']))
    else:
        cmd_print = cmd.replace('%i', ' '.join(outputs))
    cmd = cmd.replace('%i', ' '.join(outputs))
    if not options.quiet:
        print('running PDF command "{}"...'.format(cmd_print))
    try:
        result = subprocess.call(shlex.split(cmd))
    except OSError:
        result = -1
    if result == 0:
        if not options.quiet:
            print('  wrote', options.pdfname)
    else:
        sys.stderr.write('warning: PDF command failed\n')

def notescan_main(options):
    """Main function for this program when run as script."""
    filenames = get_filenames(options)
    outputs = []
    do_global = options.global_palette and len(filenames) > 1
    if do_global:
        filenames, palette = get_global_palette(filenames, options)
    do_postprocess = bool(options.postprocess_cmd)
    for input_filename in filenames:
        img, dpi = load(input_filename)
        if img is None:
            continue
        output_filename = '{}{:04d}.png'.format(options.basename, len(outputs))
        if not options.quiet:
            print('opened', input_filename)
        if not do_global:
            samples = sample_pixels(img, options)
            palette = get_palette(samples, options)
        labels = apply_palette(img, palette, options)
        save(output_filename, labels, palette, dpi, options)
        if do_postprocess:
            post_filename = postprocess(output_filename, options)
            if post_filename:
                output_filename = post_filename
            else:
                do_postprocess = False
        outputs.append(output_filename)
        if not options.quiet:
            print('  done\n')
    emit_pdf(outputs, options)

def generic_type_name(v):
    """Return a descriptive type name that isn't Python specific. For example, an
    int type will return 'integer' rather than 'int'."""
    if isinstance(v, AstExampleRef):
        return 'reference'
    elif isinstance(v, numbers.Integral):
        return 'integer'
    elif isinstance(v, numbers.Real):
        return 'float'
    elif isinstance(v, (tuple, list)):
        return 'list'
    elif isinstance(v, six.string_types):
        return 'string'
    elif v is None:
        return 'null'
    else:
        return type(v).__name__

def doc_unwrap(raw_doc):
    """Applies two transformations to raw_doc:
    1. N consecutive newlines are converted into N-1 newlines.
    2. A lone newline is converted to a space, which basically unwraps text.

    Returns a new string, or None if the input was None."""
    if raw_doc is None:
        return None
    docstring = ''
    consecutive_newlines = 0
    for c in raw_doc.strip():
        if c == '\n':
            consecutive_newlines += 1
            if consecutive_newlines > 1:
                docstring += c
        else:
            if consecutive_newlines == 1:
                docstring += ' '
            consecutive_newlines = 0
            docstring += c
    return docstring

def get_custom_annotations_recursive(data_type):
    """Given a Stone data type, returns all custom annotations applied to any of
    its memebers, as well as submembers, ..., to an arbitrary depth."""
    data_types_seen = set()
    def recurse(data_type):
        if data_type in data_types_seen:
            return
        data_types_seen.add(data_type)
        dt, _, _ = unwrap(data_type)
        if is_struct_type(dt) or is_union_type(dt):
            for field in dt.fields:
                for annotation in recurse(field.data_type):
                    yield annotation
                for annotation in field.custom_annotations:
                    yield annotation
        elif is_list_type(dt):
            for annotation in recurse(dt.data_type):
                yield annotation
        elif is_map_type(dt):
            for annotation in recurse(dt.value_data_type):
                yield annotation
        for annotation in get_custom_annotations_for_alias(data_type):
            yield annotation
    return recurse(data_type)

def check_route_name_conflict(namespace):
    """Check name conflicts among generated route definitions. Raise a runtime exception when a
    conflict is encountered."""
    route_by_name = {}
    for route in namespace.routes:
        route_name = fmt_func(route.name, version=route.version)
        if route_name in route_by_name:
            other_route = route_by_name[route_name]
            raise RuntimeError('There is a name conflict between {!r} and {!r}'.format(other_route, route))
        route_by_name[route_name] = route

def prefix_with_ns_if_necessary(name, name_ns, source_ns):
    """Returns a name that can be used to reference `name` in namespace `name_ns`
    from `source_ns`.

    If `source_ns` and `name_ns` are the same, that's just `name`. Otherwise
    it's `name_ns`.`name`."""
    if source_ns == name_ns:
        return name
    return '{}.{}'.format(fmt_namespace(name_ns.name), name)

def class_name_for_annotation_type(annotation_type, ns=None):
    """Same as class_name_for_data_type, but works with annotation types."""
    assert isinstance(annotation_type, AnnotationType)
    name = fmt_class(annotation_type.name)
    if ns:
        return prefix_with_ns_if_necessary(name, annotation_type.namespace, ns)
    return name

def fmt_type_name(data_type):
    """Returns the JSDoc name for the given data type.
    (Does not attempt to enumerate subtypes.)"""
    if is_user_defined_type(data_type):
        return fmt_pascal('%s%s' % (data_type.namespace.name, data_type.name))
    else:
        fmted_type = _base_type_table.get(data_type.__class__, 'Object')
        if is_list_type(data_type):
            fmted_type += '.<' + fmt_type(data_type.data_type) + '>'
        return fmted_type

def fmt_type(data_type):
    """Returns a JSDoc annotation for a data type.
    May contain a union of enumerated subtypes."""
    if is_struct_type(data_type) and data_type.has_enumerated_subtypes():
        possible_types = []
        possible_subtypes = data_type.get_all_subtypes_with_tags()
        for _, subtype in possible_subtypes:
            possible_types.append(fmt_type_name(subtype))
        if data_type.is_catch_all():
            possible_types.append(fmt_type_name(data_type))
        return fmt_jsdoc_union(possible_types)
    else:
        return fmt_type_name(data_type)

def fmt_type_name(data_type, inside_namespace=None):
    """Produces a TypeScript type name for the given data type.
    inside_namespace should be set to the namespace that the reference
    occurs in, or None if this parameter is not relevant."""
    if is_user_defined_type(data_type) or is_alias(data_type):
        if data_type.namespace == inside_namespace:
            return data_type.name
        else:
            return '%s.%s' % (data_type.namespace.name, data_type.name)
    else:
        fmted_type = _base_type_table.get(data_type.__class__, 'Object')
        if is_list_type(data_type):
            fmted_type += '<' + fmt_type(data_type.data_type, inside_namespace) + '>'
        return fmted_type

def fmt_type(data_type, inside_namespace=None):
    """Returns a TypeScript type annotation for a data type.
    May contain a union of enumerated subtypes.
    inside_namespace should be set to the namespace that the type reference
    occurs in, or None if this parameter is not relevant."""
    if is_struct_type(data_type) and data_type.has_enumerated_subtypes():
        possible_types = []
        possible_subtypes = data_type.get_all_subtypes_with_tags()
        for _, subtype in possible_subtypes:
            possible_types.append(fmt_polymorphic_type_reference(subtype, inside_namespace))
        if data_type.is_catch_all():
            possible_types.append(fmt_polymorphic_type_reference(data_type, inside_namespace))
        return fmt_union(possible_types)
    else:
        return fmt_type_name(data_type, inside_namespace)

def fmt_tag(cur_namespace, tag, val):
    """Processes a documentation reference."""
    if tag == 'type':
        fq_val = val
        if '.' not in val and cur_namespace is not None:
            fq_val = cur_namespace.name + '.' + fq_val
        return fq_val
    elif tag == 'route':
        if ':' in val:
            val, version = val.split(':', 1)
            version = int(version)
        else:
            version = 1
        return fmt_func(val, version) + '()'
    elif tag == 'link':
        anchor, link = val.rsplit(' ', 1)
        return '[%s]{@link %s}' % (anchor, link)
    elif tag == 'val':
        return val
    elif tag == 'field':
        return val
    else:
        raise RuntimeError('Unknown doc ref tag %r' % tag)

def parse_data_types_from_doc_ref(api, doc, namespace_context, ignore_missing_entries=False):
    """Given a documentation string, parse it and return all references to other
    data types. If there are references to routes, include also the data types of
    those routes.

    Args:
    - api: The API containing this doc ref.
    - doc: The documentation string to parse.
    - namespace_context: The namespace name relative to this documentation.
    - ignore_missing_entries: If set, this will skip references to nonexistent data types instead
                              of raising an exception.

    Returns:
    - a list of referenced data types"""
    output = []
    data_types, routes_by_ns = parse_data_types_and_routes_from_doc_ref(api, doc, namespace_context, ignore_missing_entries=ignore_missing_entries)
    for d in data_types:
        output.append(d)
    for ns_name, routes in routes_by_ns.items():
        try:
            ns = api.namespaces[ns_name]
            for r in routes:
                for d in ns.get_route_io_data_types_for_route(r):
                    output.append(d)
        except KeyError:
            if not ignore_missing_entries:
                raise
    return output

def parse_route_name_and_version(route_repr):
    """Parse a route representation string and return the route name and version number.

    :param route_repr: Route representation string.

    :return: A tuple containing route name and version number."""
    if ':' in route_repr:
        route_name, version = route_repr.split(':', 1)
        try:
            version = int(version)
        except ValueError:
            raise ValueError('Invalid route representation: {}'.format(route_repr))
    else:
        route_name = route_repr
        version = 1
    return (route_name, version)

def get_zip_class():
    """Supplement ZipFile class to support context manager for Python 2.6"""
    class ContextualZipFile(zipfile.ZipFile):
        def __enter__(self):
            return self
        def __exit__(self, type, value, traceback):
            self.close
    return zipfile.ZipFile if hasattr(zipfile.ZipFile, '__exit__') else ContextualZipFile

