def _reflect_all(exclude_tables=None, admin=None, read_only=False, schema=None):
    """Register all tables in the given database as services.

    :param list exclude_tables: A list of tables to exclude from the API
                                service"""
    AutomapModel.prepare(db.engine, reflect=True, schema=schema)
    for cls in AutomapModel.classes:
        if exclude_tables and cls.__table__.name in exclude_tables:
            continue
        if read_only:
            cls.__methods__ = {'GET'}
        register_model(cls, admin)

def register_model(cls, admin=None):
    """Register *cls* to be included in the API service

    :param cls: Class deriving from :class:`sandman2.models.Model`"""
    cls.__url__ = '/{}'.format(cls.__name__.lower())
    service_class = type(cls.__name__ + 'Service', (Service,), {'__model__': cls})
    cols = list(cls().__table__.primary_key.columns)
    primary_key_type = 'string'
    if len(cols) == 1:
        col_type = cols[0].type
        if isinstance(col_type, sqltypes.String):
            primary_key_type = 'string'
        elif isinstance(col_type, sqltypes.Integer):
            primary_key_type = 'int'
        elif isinstance(col_type, sqltypes.Numeric):
            primary_key_type = 'float'
    register_service(service_class, primary_key_type)
    if admin is not None:
        admin.add_view(CustomAdminView(cls, db.session))

def is_valid_method(model, resource=None):
    """Return the error message to be sent to the client if the current
    request passes fails any user-defined validation."""
    validation_function_name = 'is_valid_{}'.format(request.method.lower())
    if hasattr(model, validation_function_name):
        return getattr(model, validation_function_name)(request, resource)

def validate_fields(func):
    """A decorator to automatically detect missing required fields from
    json data."""
    @functools.wraps(func)
    def decorated(instance, *args, **kwargs):
        """The decorator function."""
        data = request.get_json(force=True, silent=True)
        if not data:
            raise BadRequestException('No data received from request')
        for key in data:
            if key not in instance.__model__.required() + instance.__model__.optional():
                raise BadRequestException('Unknown field [{}]'.format(key))
        missing = set(instance.__model__.required()) - set(data)
        if missing:
            message = 'The following required fields are missing: ' + ', '.join(missing)
            raise BadRequestException(message)
        return func(instance, *args, **kwargs)
    return decorated

def merge_record_extra(record, target, reserved):
    """Merges extra attributes from LogRecord object into target dictionary

    :param record: logging.LogRecord
    :param target: dict to update
    :param reserved: dict or list with reserved keys to skip"""
    for key, value in record.__dict__.items():
        if key not in reserved and (not (hasattr(key, 'startswith') and key.startswith('_'))):
            target[key] = value
    return target

def to_array_list(df, length=None, by_id=True):
    """Converts a dataframe to a list of arrays, with one array for every unique index entry.
    Index is assumed to be 0-based contiguous. If there is a missing index entry, an empty
    numpy array is returned for it.
    Elements in the arrays are sorted by their id.
    :param df:
    :param length:
    :return:"""
    if by_id:
        assert 'id' in df.columns
        if len(df.columns) == 1:
            by_id = False
    idx = df.index.unique()
    if length is None:
        length = max(idx) + 1
    l = [np.empty(0) for _ in xrange(length)]
    for i in idx:
        a = df.loc[i]
        if by_id:
            if isinstance(a, pd.Series):
                a = a[1:]
            else:
                a = a.copy().set_index('id').sort_index()
        l[i] = a.values.reshape((-1, a.shape[-1]))
    return np.asarray(l)

def rotx(t):
    """Rotation about the x-axis."""
    c = np.cos(t)
    s = np.sin(t)
    return np.array([[1, 0, 0], [0, c, -s], [0, s, c]])

def roty(t):
    """Rotation about the y-axis."""
    c = np.cos(t)
    s = np.sin(t)
    return np.array([[c, 0, s], [0, 1, 0], [-s, 0, c]])

def rotz(t):
    """Rotation about the z-axis."""
    c = np.cos(t)
    s = np.sin(t)
    return np.array([[c, -s, 0], [s, c, 0], [0, 0, 1]])

def transform_from_rot_trans(R, t):
    """Transforation matrix from rotation matrix and translation vector."""
    R = R.reshape(3, 3)
    t = t.reshape(3, 1)
    return np.vstack((np.hstack([R, t]), [0, 0, 0, 1]))

def read_calib_file(filepath):
    """Read in a calibration file and parse into a dictionary."""
    data = {}
    with open(filepath, 'r') as f:
        for line in f.readlines():
            key, value = line.split(':', 1)
            try:
                data[key] = np.array([float(x) for x in value.split()])
            except ValueError:
                pass
    return data

def load_velo_scan(file):
    """Load and parse a velodyne binary file."""
    scan = np.fromfile(file, dtype=np.float32)
    return scan.reshape((-1, 4))

def determine_file_type(filename):
    """:param filename: str

    :rtype: FileType"""
    if filename.endswith('.cls'):
        return FileType.CLS
    elif filename.endswith('.go'):
        return FileType.GO
    elif filename.endswith('.java'):
        return FileType.JAVA
    elif filename.endswith('.js'):
        return FileType.JAVASCRIPT
    elif filename.endswith('.php'):
        return FileType.PHP
    elif filename.endswith('.py'):
        return FileType.PYTHON
    elif filename.endswith(('.yaml', '.yml')):
        return FileType.YAML
    return FileType.OTHER

def raise_exception_if_baseline_file_is_unstaged(filename):
    """We want to make sure that if there are changes to the baseline
    file, they will be included in the commit. This way, we can keep
    our baselines up-to-date.

    :raises: ValueError"""
    try:
        files_changed_but_not_staged = subprocess.check_output(['git', 'diff', '--name-only']).split()
    except subprocess.CalledProcessError:
        raise ValueError
    if filename.encode() in files_changed_but_not_staged:
        log.error('Your baseline file ({}) is unstaged.\n`git add {}` to fix this.'.format(filename, filename))
        raise ValueError

def _secret_generator(baseline):
    """Generates secrets to audit, from the baseline"""
    for filename, secrets in baseline['results'].items():
        for secret in secrets:
            yield (filename, secret)

def _get_user_decision(prompt_secret_decision=True, can_step_back=False):
    """:type prompt_secret_decision: bool
    :param prompt_secret_decision: if False, won't ask to label secret."""
    allowable_user_input = ['s', 'q']
    if prompt_secret_decision:
        allowable_user_input.extend(['y', 'n'])
    if can_step_back:
        allowable_user_input.append('b')
    user_input = None
    while user_input not in allowable_user_input:
        if user_input:
            print('Invalid input.')
        if 'y' in allowable_user_input:
            user_input_string = 'Is this a valid secret? i.e. not a false-positive (y)es, (n)o, '
        else:
            user_input_string = 'What would you like to do? '
        if 'b' in allowable_user_input:
            user_input_string += '(b)ack, '
        user_input_string += '(s)kip, (q)uit: '
        user_input = input(user_input_string)
        if user_input:
            user_input = user_input[0].lower()
    return user_input

def raw_secret_generator(plugin, secret_line, filetype):
    """Generates raw secrets by re-scanning the line, with the specified plugin

    :type plugin: BasePlugin
    :type secret_line: str
    :type filetype: FileType"""
    for raw_secret in plugin.secret_generator(secret_line, filetype=filetype):
        yield raw_secret
    if issubclass(plugin.__class__, HighEntropyStringsPlugin):
        with plugin.non_quoted_string_regex(strict=False):
            for raw_secret in plugin.secret_generator(secret_line):
                yield raw_secret

def _set_debug_level(self, debug_level):
    """:type debug_level: int, between 0-2
    :param debug_level: configure verbosity of log"""
    mapping = {0: logging.ERROR, 1: logging.INFO, 2: logging.DEBUG}
    self.setLevel(mapping[min(debug_level, 2)])

def get_secrets_not_in_baseline(results, baseline):
    """:type results: SecretsCollection
    :param results: SecretsCollection of current results

    :type baseline: SecretsCollection
    :param baseline: SecretsCollection of baseline results.
                     This will be updated accordingly (by reference)

    :rtype: SecretsCollection
    :returns: SecretsCollection of new results (filtering out baseline)"""
    exclude_files_regex = None
    if baseline.exclude_files:
        exclude_files_regex = re.compile(baseline.exclude_files, re.IGNORECASE)
    new_secrets = SecretsCollection()
    for filename in results.data:
        if exclude_files_regex and exclude_files_regex.search(filename):
            continue
        if filename not in baseline.data:
            new_secrets.data[filename] = results.data[filename]
            continue
        filtered_results = {secret: secret for secret in results.data[filename] if secret not in baseline.data[filename]}
        if filtered_results:
            new_secrets.data[filename] = filtered_results
    return new_secrets

def merge_results(old_results, new_results):
    """Update results in baseline with latest information.

    :type old_results: dict
    :param old_results: results of status quo

    :type new_results: dict
    :param new_results: results to replace status quo

    :rtype: dict"""
    for filename, old_secrets in old_results.items():
        if filename not in new_results:
            continue
        old_secrets_mapping = dict()
        for old_secret in old_secrets:
            old_secrets_mapping[old_secret['hashed_secret']] = old_secret
        for new_secret in new_results[filename]:
            if new_secret['hashed_secret'] not in old_secrets_mapping:
                continue
            old_secret = old_secrets_mapping[new_secret['hashed_secret']]
            if 'is_secret' in old_secret and 'is_secret' not in new_secret:
                new_secret['is_secret'] = old_secret['is_secret']
    return new_results

def format_baseline_for_output(baseline):
    """:type baseline: dict
    :rtype: str"""
    for filename, secret_list in baseline['results'].items():
        baseline['results'][filename] = sorted(secret_list, key=lambda x: (x['line_number'], x['hashed_secret']))
    return json.dumps(baseline, indent=2, sort_keys=True, separators=(',', ': '))

def _get_files_recursively(rootdir):
    """Sometimes, we want to use this tool with non-git repositories.
    This function allows us to do so."""
    output = []
    for root, dirs, files in os.walk(rootdir):
        for filename in files:
            output.append(os.path.join(root, filename))
    return output

def _perform_scan(args, plugins):
    """:param args: output of `argparse.ArgumentParser.parse_args`
    :param plugins: tuple of initialized plugins

    :rtype: dict"""
    old_baseline = _get_existing_baseline(args.import_filename)
    if old_baseline:
        plugins = initialize.merge_plugin_from_baseline(_get_plugin_from_baseline(old_baseline), args)
    if old_baseline:
        if not args.exclude_files:
            args.exclude_files = _get_exclude_files(old_baseline)
        if not args.exclude_lines and old_baseline.get('exclude'):
            args.exclude_lines = old_baseline['exclude']['lines']
    if args.import_filename:
        _add_baseline_to_exclude_files(args)
    new_baseline = baseline.initialize(plugins=plugins, exclude_files_regex=args.exclude_files, exclude_lines_regex=args.exclude_lines, path=args.path, scan_all_files=args.all_files).format_for_baseline_output()
    if old_baseline:
        new_baseline = baseline.merge_baseline(old_baseline, new_baseline)
    return new_baseline

def _add_baseline_to_exclude_files(args):
    """Modifies args.exclude_files in-place."""
    baseline_name_regex = '^{}$'.format(args.import_filename[0])
    if not args.exclude_files:
        args.exclude_files = baseline_name_regex
    elif baseline_name_regex not in args.exclude_files:
        args.exclude_files += '|{}'.format(baseline_name_regex)

def from_parser_builder(plugins_dict, exclude_lines_regex=None):
    """:param plugins_dict: plugins dictionary received from ParserBuilder.
        See example in tests.core.usage_test.

    :type exclude_lines_regex: str|None
    :param exclude_lines_regex: optional regex for ignored lines.

    :returns: tuple of initialized plugins"""
    output = []
    for plugin_name in plugins_dict:
        output.append(from_plugin_classname(plugin_name, exclude_lines_regex=exclude_lines_regex, **plugins_dict[plugin_name]))
    return tuple(output)

def _get_prioritized_parameters(plugins_dict, is_using_default_value_map, prefer_default=True):
    """:type plugins_dict: dict(plugin_name => plugin_params)
    :param plugin_dict: mapping of plugin name to all plugin params

    :type is_using_default_value_map: dict(str => bool)
    :param is_using_default_value_map: mapping of parameter name to whether its value is derived
        from a default value.

    :param prefer_default: if True, will yield if plugin parameters are from default values.
        Otherwise, will yield if plugin parameters are *not* from default values."""
    for plugin_name, plugin_params in plugins_dict.items():
        for param_name, param_value in plugin_params.items():
            is_using_default = is_using_default_value_map.get(param_name, False)
            if is_using_default == prefer_default:
                yield (plugin_name, param_name, param_value)

def from_secret_type(secret_type, settings):
    """Note: Only called from audit.py

    :type secret_type: str
    :param secret_type: unique identifier for plugin type

    :type settings: list
    :param settings: output of "plugins_used" in baseline. e.g.
        >>> [
        ...     {
        ...         'name': 'Base64HighEntropyString',
        ...         'base64_limit': 4.5,
        ...     },
        ... ]"""
    mapping = _get_mapping_from_secret_type_to_class_name()
    try:
        classname = mapping[secret_type]
    except KeyError:
        return None
    for plugin in settings:
        if plugin['name'] == classname:
            plugin_init_vars = plugin.copy()
            plugin_init_vars.pop('name')
            return from_plugin_classname(classname, **plugin_init_vars)

def _get_mapping_from_secret_type_to_class_name():
    """Returns secret_type => plugin classname"""
    mapping = {}
    for key, value in globals().items():
        try:
            if issubclass(value, BasePlugin) and value != BasePlugin:
                mapping[value.secret_type] = key
        except TypeError:
            pass
    return mapping

def do_find(lookup, term):
    """Matches term glob against short-name, keywords and categories."""
    space = defaultdict(list)
    for name in lookup.keys():
        space[name].append(name)
    try:
        iter_lookup = lookup.iteritems()
    except AttributeError:
        iter_lookup = lookup.items()
    for name, definition in iter_lookup:
        for keyword in definition['keywords']:
            space[keyword].append(name)
        space[definition['category']].append(name)
    matches = fnmatch.filter(space.keys(), term)
    results = set()
    for match in matches:
        results.update(space[match])
    return [(r, translate(lookup, r)) for r in results]

def compile(expr, params=None):
    """Force compilation of expression for the SQLite target"""
    from ibis.sql.alchemy import to_sqlalchemy
    return to_sqlalchemy(expr, dialect.make_context(params=params))

def _warn_if_deprecated(key):
    """Checks if `key` is a deprecated option and if so, prints a warning.
    Returns
    -------
    bool - True if `key` is deprecated, False otherwise."""
    d = _get_deprecated_option(key)
    if d:
        if d.msg:
            print(d.msg)
            warnings.warn(d.msg, DeprecationWarning)
        else:
            msg = "'%s' is deprecated" % key
            if d.removal_ver:
                msg += ' and will be removed in %s' % d.removal_ver
            if d.rkey:
                msg += ", please use '%s' instead." % d.rkey
            else:
                msg += ', please refrain from using it.'
            warnings.warn(msg, DeprecationWarning)
        return True
    return False

def _build_option_description(k):
    """Builds a formatted description of a registered option and prints it."""
    o = _get_registered_option(k)
    d = _get_deprecated_option(k)
    buf = ['{} '.format(k)]
    if o.doc:
        doc = '\n'.join(o.doc.strip().splitlines())
    else:
        doc = 'No description available.'
    buf.append(doc)
    if o:
        buf.append('\n    [default: {}] [currently: {}]'.format(o.defval, _get_option(k, True)))
    if d:
        buf.append('\n    (Deprecated{})'.format(', use `{}` instead.'.format(d.rkey) if d.rkey else ''))
    buf.append('\n\n')
    return ''.join(buf)

def pp_options_list(keys, width=80, _print=False):
    """Builds a concise listing of available options, grouped by prefix"""
    from textwrap import wrap
    from itertools import groupby
    def pp(name, ks):
        pfx = '- ' + name + '.[' if name else ''
        ls = wrap(', '.join(ks), width, initial_indent=pfx, subsequent_indent='  ', break_long_words=False)
        if ls and ls[-1] and name:
            ls[-1] = ls[-1] + ']'
        return ls
    ls = []
    singles = [x for x in sorted(keys) if x.find('.') < 0]
    if singles:
        ls += pp('', singles)
    keys = [x for x in keys if x.find('.') >= 0]
    for k, g in groupby(sorted(keys), lambda x: x[:x.rfind('.')]):
        ks = [x[len(k) + 1:] for x in list(g)]
        ls += pp(k, ks)
    s = '\n'.join(ls)
    if _print:
        print(s)
    else:
        return s

def all_equal(left, right, cache=None):
    """Check whether two objects `left` and `right` are equal.

    Parameters
    ----------
    left : Union[object, Expr, Node]
    right : Union[object, Expr, Node]
    cache : Optional[Dict[Tuple[Node, Node], bool]]
        A dictionary indicating whether two Nodes are equal"""
    if cache is None:
        cache = {}
    if util.is_iterable(left):
        return util.is_iterable(right) and len(left) == len(right) and all(itertools.starmap(functools.partial(all_equal, cache=cache), zip(left, right)))
    if hasattr(left, 'equals'):
        return left.equals(right, cache=cache)
    return left == right

def load(data, udf, data_dir, overwrite):
    """Load Ibis test data and build/upload UDFs"""
    con = make_ibis_client(ENV)
    if not can_write_to_hdfs(con):
        raise IbisError('Failed to write to HDFS; check your settings')
    if udf and (not can_build_udfs()):
        raise IbisError('Build environment does not support building UDFs')
    if data:
        load_impala_data(con, str(data_dir), overwrite)
    else:
        logger.info('Skipping Ibis test data load (--no-data)')
    if udf:
        already_loaded = is_udf_loaded(con)
        logger.info('Attempting to build and load test UDFs')
        if already_loaded and (not overwrite):
            logger.info('UDFs already loaded and not overwriting; moving on')
        else:
            if already_loaded:
                logger.info('UDFs already loaded; attempting to overwrite')
            logger.info('Building UDFs')
            build_udfs()
            logger.info('Uploading UDFs')
            upload_udfs(con)
    else:
        logger.info('Skipping UDF build/load (--no-udf)')

def cleanup(test_data, udfs, tmp_data, tmp_db):
    """Cleanup Ibis test data and UDFs"""
    con = make_ibis_client(ENV)
    if udfs:
        con.hdfs.rmdir(os.path.join(ENV.test_data_dir, 'udf'))
    if test_data:
        con.drop_database(ENV.test_data_db, force=True)
        con.hdfs.rmdir(ENV.test_data_dir)
    if tmp_data:
        con.hdfs.rmdir(ENV.tmp_dir)
    if tmp_db:
        con.drop_database(ENV.tmp_db, force=True)

def has_reduction(expr):
    """Does `expr` contain a reduction?

    Parameters
    ----------
    expr : ibis.expr.types.Expr
        An ibis expression

    Returns
    -------
    truth_value : bool
        Whether or not there's at least one reduction in `expr`

    Notes
    -----
    The ``isinstance(op, ops.TableNode)`` check in this function implies
    that we only examine every non-table expression that precedes the first
    table expression."""
    def fn(expr):
        op = expr.op()
        if isinstance(op, ops.TableNode):
            return (lin.halt, None)
        if isinstance(op, ops.Reduction):
            return (lin.halt, True)
        return (lin.proceed, None)
    reduction_status = lin.traverse(fn, expr)
    return any(reduction_status)

def semicolon(f):
    """Add a semicolon to the result of a visit_* call.

    Parameters
    ----------
    f : callable"""
    @functools.wraps(f)
    def wrapper(*args, **kwargs):
        return f(*args, **kwargs) + ';'
    return wrapper

def ibis_dtype_to_pandas(ibis_dtype):
    """Convert ibis dtype to the pandas / numpy alternative"""
    assert isinstance(ibis_dtype, dt.DataType)
    if isinstance(ibis_dtype, dt.Timestamp) and ibis_dtype.timezone:
        return DatetimeTZDtype('ns', ibis_dtype.timezone)
    elif isinstance(ibis_dtype, dt.Interval):
        return np.dtype('timedelta64[{}]'.format(ibis_dtype.unit))
    elif isinstance(ibis_dtype, dt.Category):
        return CategoricalDtype()
    elif type(ibis_dtype) in _ibis_dtypes:
        return _ibis_dtypes[type(ibis_dtype)]
    else:
        return np.dtype(np.object_)

def convert_timezone(obj, timezone):
    """Convert `obj` to the timezone `timezone`.

    Parameters
    ----------
    obj : datetime.date or datetime.datetime

    Returns
    -------
    type(obj)"""
    if timezone is None:
        return obj.replace(tzinfo=None)
    return pytz.timezone(timezone).localize(obj)

def infer_struct(value: Mapping[str, GenericAny]) -> Struct:
    """Infer the :class:`~ibis.expr.datatypes.Struct` type of `value`."""
    if not value:
        raise TypeError('Empty struct type not supported')
    return Struct(list(value.keys()), list(map(infer, value.values())))

def infer_map(value: Mapping[GenericAny, GenericAny]) -> Map:
    """Infer the :class:`~ibis.expr.datatypes.Map` type of `value`."""
    if not value:
        return Map(null, null)
    return Map(highest_precedence(map(infer, value.keys())), highest_precedence(map(infer, value.values())))

def infer_list(values: List[GenericAny]) -> Array:
    """Infer the :class:`~ibis.expr.datatypes.Array` type of `values`."""
    if not values:
        return Array(null)
    return Array(highest_precedence(map(infer, values)))

def infer_set(values: GenericSet) -> Set:
    """Infer the :class:`~ibis.expr.datatypes.Set` type of `values`."""
    if not values:
        return Set(null)
    return Set(highest_precedence(map(infer, values)))

def cast(source: Union[DataType, str], target: Union[DataType, str], **kwargs) -> DataType:
    """Attempts to implicitly cast from source dtype to target dtype"""
    source, result_target = (dtype(source), dtype(target))
    if not castable(source, result_target, **kwargs):
        raise com.IbisTypeError('Datatype {} cannot be implicitly casted to {}'.format(source, result_target))
    return result_target

def verify(expr, params=None):
    """Determine if expression can be successfully translated to execute on
    MapD"""
    try:
        compile(expr, params=params)
        return True
    except com.TranslationError:
        return False

def _sign(translator, expr):
    """Workaround for missing sign function"""
    op = expr.op()
    arg, = op.args
    arg_ = translator.translate(arg)
    return 'intDivOrZero({0}, abs({0}))'.format(arg_)

def _replace_interval_with_scalar(expr):
    """Good old Depth-First Search to identify the Interval and IntervalValue
    components of the expression and return a comparable scalar expression.

    Parameters
    ----------
    expr : float or expression of intervals
        For example, ``ibis.interval(days=1) + ibis.interval(hours=5)``

    Returns
    -------
    preceding : float or ir.FloatingScalar, depending upon the expr"""
    try:
        expr_op = expr.op()
    except AttributeError:
        expr_op = None
    if not isinstance(expr, (dt.Interval, ir.IntervalValue)):
        if isinstance(expr_op, ops.Literal):
            return expr_op.value
        else:
            return expr
    elif isinstance(expr, dt.Interval):
        try:
            microseconds = _map_interval_to_microseconds[expr.unit]
            return microseconds
        except KeyError:
            raise ValueError('Expected preceding values of week(), ' + 'day(), hour(), minute(), second(), millisecond(), ' + 'microseconds(), nanoseconds(); got {}'.format(expr))
    elif expr_op.args and isinstance(expr, ir.IntervalValue):
        if len(expr_op.args) > 2:
            raise com.NotImplementedError("'preceding' argument cannot be parsed.")
        left_arg = _replace_interval_with_scalar(expr_op.args[0])
        right_arg = _replace_interval_with_scalar(expr_op.args[1])
        method = _map_interval_op_to_op[type(expr_op)]
        return method(left_arg, right_arg)

def _get_args(op, name):
    """Hack to get relevant arguments for lineage computation.

    We need a better way to determine the relevant arguments of an expression."""
    if isinstance(op, ops.Selection):
        assert name is not None, 'name is None'
        result = op.selections
        return [col for col in result if col._name == name]
    elif isinstance(op, ops.Aggregation):
        assert name is not None, 'name is None'
        return [col for col in itertools.chain(op.by, op.metrics) if col._name == name]
    else:
        return op.args

def consume(iterator: Iterator[T], n: Optional[int]=None) -> None:
    """Advance the iterator n-steps ahead. If n is None, consume entirely."""
    if n is None:
        collections.deque(iterator, maxlen=0)
    else:
        next(itertools.islice(iterator, n, n), None)

def schema_from_table(table, schema=None):
    """Retrieve an ibis schema from a SQLAlchemy ``Table``.

    Parameters
    ----------
    table : sa.Table

    Returns
    -------
    schema : ibis.expr.datatypes.Schema
        An ibis schema corresponding to the types of the columns in `table`."""
    schema = schema if schema is not None else {}
    pairs = []
    for name, column in table.columns.items():
        if name in schema:
            dtype = dt.dtype(schema[name])
        else:
            dtype = dt.dtype(getattr(table.bind, 'dialect', SQLAlchemyDialect()), column.type, nullable=column.nullable)
        pairs.append((name, dtype))
    return sch.schema(pairs)

def convert_to_database_compatible_value(value):
    """Pandas 0.23 broke DataFrame.to_sql, so we workaround it by rolling our
    own extremely low-tech conversion routine"""
    if pd.isnull(value):
        return None
    if isinstance(value, pd.Timestamp):
        return value.to_pydatetime()
    try:
        return value.item()
    except AttributeError:
        return value

def castable(source, target):
    """Return whether source ir type is implicitly castable to target

    Based on the underlying datatypes and the value in case of Literals"""
    op = source.op()
    value = getattr(op, 'value', None)
    return dt.castable(source.type(), target.type(), value=value)

def cast(source, target):
    """Currently Literal to *Scalar implicit casts are allowed"""
    import ibis.expr.operations as ops
    if not castable(source, target):
        raise com.IbisTypeError('Source is not castable to target type!')
    op = source.op()
    if not isinstance(op, ops.Literal):
        raise com.IbisTypeError('Only able to implicitly cast literals!')
    out_type = target.type().scalar_type()
    return out_type(op)

def one_of(inners, arg):
    """At least one of the inner validators must pass"""
    for inner in inners:
        with suppress(com.IbisTypeError, ValueError):
            return inner(arg)
    rules_formatted = ', '.join(map(repr, inners))
    raise com.IbisTypeError('Arg passes neither of the following rules: {}'.format(rules_formatted))

def instance_of(klass, arg):
    """Require that a value has a particular Python type."""
    if not isinstance(arg, klass):
        raise com.IbisTypeError('Given argument with type {} is not an instance of {}'.format(type(arg), klass))
    return arg

def desc(expr):
    """Create a sort key (when used in sort_by) by the passed array expression or
    column name.

    Parameters
    ----------
    expr : array expression or string
      Can be a column name in the table being sorted

    Examples
    --------
    >>> import ibis
    >>> t = ibis.table([('g', 'string')])
    >>> result = t.group_by('g').size('count').sort_by(ibis.desc('count'))"""
    if not isinstance(expr, Expr):
        return ops.DeferredSortKey(expr, ascending=False)
    else:
        return ops.SortKey(expr, ascending=False).to_expr()

def timestamp(value, timezone=None):
    """Returns a timestamp literal if value is likely coercible to a timestamp

    Parameters
    ----------
    value : timestamp value as string
    timezone: timezone as string
        defaults to None

    Returns
    --------
    result : TimestampScalar"""
    if isinstance(value, str):
        try:
            value = pd.Timestamp(value, tz=timezone)
        except pd.errors.OutOfBoundsDatetime:
            value = dateutil.parser.parse(value)
    if isinstance(value, numbers.Integral):
        raise TypeError('Passing an integer to ibis.timestamp is not supported. Use ibis.literal({value:d}).to_timestamp() to create a timestamp expression from an integer.'.format(value=value))
    return literal(value, type=dt.Timestamp(timezone=timezone))

def notin(arg, values):
    """Like isin, but checks whether this expression's value(s) are not
    contained in the passed values. See isin docs for full usage."""
    op = ops.NotContains(arg, values)
    return op.to_expr()

def substitute(arg, value, replacement=None, else_=None):
    """Substitute (replace) one or more values in a value expression

    Parameters
    ----------
    value : expr-like or dict
    replacement : expr-like, optional
      If an expression is passed to value, this must be passed
    else_ : expr, optional

    Returns
    -------
    replaced : case statement (for now!)"""
    expr = arg.case()
    if isinstance(value, dict):
        for k, v in sorted(value.items()):
            expr = expr.when(k, v)
    else:
        expr = expr.when(value, replacement)
    if else_ is not None:
        expr = expr.else_(else_)
    else:
        expr = expr.else_(arg)
    return expr.end()

def cases(arg, case_result_pairs, default=None):
    """Create a case expression in one shot.

    Returns
    -------
    case_expr : SimpleCase"""
    builder = arg.case()
    for case, result in case_result_pairs:
        builder = builder.when(case, result)
    if default is not None:
        builder = builder.else_(default)
    return builder.end()

def topk(arg, k, by=None):
    """Returns
    -------
    topk : TopK filter expression"""
    op = ops.TopK(arg, k, by=by)
    return op.to_expr()

def _integer_to_interval(arg, unit='s'):
    """Convert integer interval with the same inner type

    Parameters
    ----------
    unit : {'Y', 'M', 'W', 'D', 'h', 'm', s', 'ms', 'us', 'ns'}

    Returns
    -------
    interval : interval value expression"""
    op = ops.IntervalFromInteger(arg, unit)
    return op.to_expr()

def ifelse(arg, true_expr, false_expr):
    """Shorthand for implementing ternary expressions

    bool_expr.ifelse(0, 1)
    e.g., in SQL: CASE WHEN bool_expr THEN 0 else 1 END"""
    case = ops.SearchedCaseBuilder()
    return case.when(arg, true_expr).else_(false_expr).end()

def _table_materialize(table):
    """Force schema resolution for a joined table, selecting all fields from
    all tables."""
    if table._is_materialized():
        return table
    op = ops.MaterializedJoin(table)
    return op.to_expr()

def _table_relabel(table, substitutions, replacements=None):
    """Change table column names, otherwise leaving table unaltered

    Parameters
    ----------
    substitutions

    Returns
    -------
    relabeled : TableExpr"""
    if replacements is not None:
        raise NotImplementedError
    observed = set()
    exprs = []
    for c in table.columns:
        expr = table[c]
        if c in substitutions:
            expr = expr.name(substitutions[c])
            observed.add(c)
        exprs.append(expr)
    for c in substitutions:
        if c not in observed:
            raise KeyError('{0!r} is not an existing column'.format(c))
    return table.projection(exprs)

def bigquery_schema(table):
    """Infer the schema of a BigQuery `table` object."""
    fields = OrderedDict(((el.name, dt.dtype(el)) for el in table.schema))
    partition_info = table._properties.get('timePartitioning', None)
    if partition_info is not None:
        partition_field = partition_info.get('field', NATIVE_PARTITION_COL)
        fields.setdefault(partition_field, dt.timestamp)
    return sch.schema(fields)

def execute_cast_simple_literal_to_timestamp(op, data, type, **kwargs):
    """Cast integer and strings to timestamps"""
    return pd.Timestamp(data, tz=type.timezone)

def execute_cast_timestamp_to_timestamp(op, data, type, **kwargs):
    """Cast timestamps to other timestamps including timezone if necessary"""
    input_timezone = data.tz
    target_timezone = type.timezone
    if input_timezone == target_timezone:
        return data
    if input_timezone is None or target_timezone is None:
        return data.tz_localize(target_timezone)
    return data.tz_convert(target_timezone)

def install_scripts(distributions):
    """Regenerate the entry_points console_scripts for the named distribution."""
    try:
        if '__PEX_UNVENDORED__' in __import__('os').environ:
            from setuptools.command import easy_install
        else:
            from pex.third_party.setuptools.command import easy_install
        if '__PEX_UNVENDORED__' in __import__('os').environ:
            import pkg_resources
        else:
            import pex.third_party.pkg_resources as pkg_resources
    except ImportError:
        raise RuntimeError("'wheel install_scripts' needs setuptools.")
    for dist in distributions:
        pkg_resources_dist = pkg_resources.get_distribution(dist)
        install = get_install_command(dist)
        command = easy_install.easy_install(install.distribution)
        command.args = ['wheel']
        command.finalize_options()
        command.install_egg_scripts(pkg_resources_dist)

def get_install_paths(name):
    """Return the (distutils) install paths for the named dist.

    A dict with ('purelib', 'platlib', 'headers', 'scripts', 'data') keys."""
    paths = {}
    i = get_install_command(name)
    for key in install.SCHEME_KEYS:
        paths[key] = getattr(i, 'install_' + key)
    if hasattr(sys, 'real_prefix'):
        paths['headers'] = os.path.join(sys.prefix, 'include', 'site', 'python' + sys.version[:3], name)
    return paths

def iter_pth_paths(filename):
    """Given a .pth file, extract and yield all inner paths without honoring imports. This shadows
    python's site.py behavior, which is invoked at interpreter startup."""
    try:
        f = open(filename, 'rU')
    except IOError:
        return
    dirname = os.path.dirname(filename)
    known_paths = set()
    with f:
        for line in f:
            line = line.rstrip()
            if not line or line.startswith('#'):
                continue
            elif line.startswith(('import ', 'import\t')):
                try:
                    exec_function(line, globals_map={})
                    continue
                except Exception:
                    return
            else:
                extras_dir, extras_dir_case_insensitive = makepath(dirname, line)
                if extras_dir_case_insensitive not in known_paths and os.path.exists(extras_dir):
                    yield extras_dir
                    known_paths.add(extras_dir_case_insensitive)

def distribution_compatible(dist, supported_tags=None):
    """Is this distribution compatible with the given interpreter/platform combination?

    :param supported_tags: A list of tag tuples specifying which tags are supported
      by the platform in question.
    :returns: True if the distribution is compatible, False if it is unrecognized or incompatible."""
    if supported_tags is None:
        supported_tags = get_supported()
    package = Package.from_href(dist.location)
    if not package:
        return False
    return package.compatible(supported_tags)

def _add_finder(importer, finder):
    """Register a new pkg_resources path finder that does not replace the existing finder."""
    existing_finder = _get_finder(importer)
    if not existing_finder:
        pkg_resources.register_finder(importer, finder)
    else:
        pkg_resources.register_finder(importer, ChainedFinder.of(existing_finder, finder))

def _remove_finder(importer, finder):
    """Remove an existing finder from pkg_resources."""
    existing_finder = _get_finder(importer)
    if not existing_finder:
        return
    if isinstance(existing_finder, ChainedFinder):
        try:
            existing_finder.finders.remove(finder)
        except ValueError:
            return
        if len(existing_finder.finders) == 1:
            pkg_resources.register_finder(importer, existing_finder.finders[0])
        elif len(existing_finder.finders) == 0:
            pkg_resources.register_finder(importer, pkg_resources.find_nothing)
    else:
        pkg_resources.register_finder(importer, pkg_resources.find_nothing)

def unregister_finders():
    """Unregister finders necessary for PEX to function properly."""
    global __PREVIOUS_FINDER
    if not __PREVIOUS_FINDER:
        return
    pkg_resources.register_finder(zipimport.zipimporter, __PREVIOUS_FINDER)
    _remove_finder(pkgutil.ImpImporter, find_wheels_on_path)
    if importlib_machinery is not None:
        _remove_finder(importlib_machinery.FileFinder, find_wheels_on_path)
    __PREVIOUS_FINDER = None

