def convert_requirements(requirements):
    """Yield Requires-Dist: strings for parsed requirements strings."""
    for req in requirements:
        parsed_requirement = pkg_resources.Requirement.parse(req)
        spec = requires_to_requires_dist(parsed_requirement)
        extras = ','.join(parsed_requirement.extras)
        if extras:
            extras = '[%s]' % extras
        yield (parsed_requirement.project_name + extras + spec)

def generate_requirements(extras_require):
    """Convert requirements from a setup()-style dictionary to ('Requires-Dist', 'requirement')
    and ('Provides-Extra', 'extra') tuples.

    extras_require is a dictionary of {extra: [requirements]} as passed to setup(),
    using the empty extra {'': [requirements]} to hold install_requires."""
    for extra, depends in extras_require.items():
        condition = ''
        if extra and ':' in extra:
            extra, condition = extra.split(':', 1)
            extra = pkg_resources.safe_extra(extra)
        if extra:
            yield ('Provides-Extra', extra)
            if condition:
                condition = '(' + condition + ') and '
            condition += "extra == '%s'" % extra
        if condition:
            condition = '; ' + condition
        for new_req in convert_requirements(depends):
            yield ('Requires-Dist', new_req + condition)

def pkginfo_to_metadata(egg_info_path, pkginfo_path):
    """Convert .egg-info directory with PKG-INFO to the Metadata 2.1 format"""
    pkg_info = read_pkg_info(pkginfo_path)
    pkg_info.replace_header('Metadata-Version', '2.1')
    requires_path = os.path.join(egg_info_path, 'requires.txt')
    if os.path.exists(requires_path):
        with open(requires_path) as requires_file:
            requires = requires_file.read()
        for extra, reqs in sorted(pkg_resources.split_sections(requires), key=lambda x: x[0] or ''):
            for item in generate_requirements({extra: reqs}):
                pkg_info[item[0]] = item[1]
    description = pkg_info['Description']
    if description:
        pkg_info.set_payload(dedent_description(pkg_info))
        del pkg_info['Description']
    return pkg_info

def pkginfo_unicode(pkg_info, field):
    """Hack to coax Unicode out of an email Message() - Python 3.3+"""
    text = pkg_info[field]
    field = field.lower()
    if not isinstance(text, str):
        if not hasattr(pkg_info, 'raw_items'):
            return str(text)
        for item in pkg_info.raw_items():
            if item[0].lower() == field:
                text = item[1].encode('ascii', 'surrogateescape').decode('utf-8')
                break
    return text

def get_abi_tag():
    """Return the ABI tag based on SOABI (if available) or emulate SOABI
    (CPython 2, PyPy)."""
    soabi = get_config_var('SOABI')
    impl = get_abbr_impl()
    if not soabi and impl in {'cp', 'pp'} and hasattr(sys, 'maxunicode'):
        d = ''
        m = ''
        u = ''
        if get_flag('Py_DEBUG', lambda: hasattr(sys, 'gettotalrefcount'), warn=impl == 'cp'):
            d = 'd'
        if get_flag('WITH_PYMALLOC', lambda: impl == 'cp', warn=impl == 'cp'):
            m = 'm'
        PY2 = sys.version_info[0] == 2
        if get_flag('Py_UNICODE_SIZE', lambda: sys.maxunicode == 1114111, expected=4, warn=impl == 'cp' and PY2) and PY2:
            u = 'u'
        abi = '%s%s%s%s%s' % (impl, get_impl_ver(), d, m, u)
    elif soabi and soabi.startswith('cpython-'):
        abi = 'cp' + soabi.split('-')[1]
    elif soabi:
        abi = soabi.replace('.', '_').replace('-', '_')
    else:
        abi = None
    return abi

def resolvables_from_iterable(iterable, builder, interpreter=None):
    """Given an iterable of resolvable-like objects, return list of Resolvable objects.

    :param iterable: An iterable of :class:`Resolvable`, :class:`Requirement`, :class:`Package`,
        or `str` to map into an iterable of :class:`Resolvable` objects.
    :returns: A list of :class:`Resolvable` objects."""
    def translate(obj):
        if isinstance(obj, Resolvable):
            return obj
        elif isinstance(obj, Requirement):
            return ResolvableRequirement(obj, builder.build(obj.key))
        elif isinstance(obj, Package):
            return ResolvablePackage(obj, builder.build(obj.name))
        elif isinstance(obj, compatibility_string):
            return Resolvable.get(obj, builder, interpreter=interpreter)
        else:
            raise ValueError('Do not know how to resolve %s' % type(obj))
    return list(map(translate, iterable))

