def open_with_auth(url, opener=urllib.request.urlopen):
    """Open a urllib2 request, handling HTTP authentication"""
    scheme, netloc, path, params, query, frag = urllib.parse.urlparse(url)
    if netloc.endswith(':'):
        raise http_client.InvalidURL("nonnumeric port: ''")
    if scheme in ('http', 'https'):
        auth, host = urllib.parse.splituser(netloc)
    else:
        auth = None
    if not auth:
        cred = PyPIConfig().find_credential(url)
        if cred:
            auth = str(cred)
            info = (cred.username, url)
            log.info('Authenticating as %s for %s (from .pypirc)', *info)
    if auth:
        auth = 'Basic ' + _encode_auth(auth)
        parts = (scheme, host, path, params, query, frag)
        new_url = urllib.parse.urlunparse(parts)
        request = urllib.request.Request(new_url)
        request.add_header('Authorization', auth)
    else:
        request = urllib.request.Request(url)
    request.add_header('User-Agent', user_agent)
    fp = opener(request)
    if auth:
        s2, h2, path2, param2, query2, frag2 = urllib.parse.urlparse(fp.url)
        if s2 == scheme and h2 == host:
            parts = (s2, netloc, path2, param2, query2, frag2)
            fp.url = urllib.parse.urlunparse(parts)
    return fp

def get_abbr_impl():
    """Return abbreviated implementation name."""
    impl = platform.python_implementation()
    if impl == 'PyPy':
        return 'pp'
    elif impl == 'Jython':
        return 'jy'
    elif impl == 'IronPython':
        return 'ip'
    elif impl == 'CPython':
        return 'cp'
    raise LookupError('Unknown Python implementation: ' + impl)

def get_flag(var, fallback, expected=True, warn=True):
    """Use a fallback method for determining SOABI flags if the needed config
    var is unset or unavailable."""
    val = get_config_var(var)
    if val is None:
        if warn:
            warnings.warn("Config variable '{0}' is unset, Python ABI tag may be incorrect".format(var), RuntimeWarning, 2)
        return fallback()
    return val == expected

def get_platform():
    """Return our platform name 'win32', 'linux_x86_64'"""
    result = distutils.util.get_platform().replace('.', '_').replace('-', '_')
    if result == 'linux_x86_64' and sys.maxsize == 2147483647:
        result = 'linux_i686'
    return result

def safe_mkdir(directory, clean=False):
    """Safely create a directory.

    Ensures a directory is present.  If it's not there, it is created.  If it
    is, it's a no-op. If clean is True, ensures the directory is empty."""
    if clean:
        safe_rmtree(directory)
    try:
        os.makedirs(directory)
    except OSError as e:
        if e.errno != errno.EEXIST:
            raise

def safe_open(filename, *args, **kwargs):
    """Safely open a file.

    ``safe_open`` ensures that the directory components leading up the
    specified file have been created first."""
    safe_mkdir(os.path.dirname(filename))
    return open(filename, *args, **kwargs)

def safe_delete(filename):
    """Delete a file safely. If it's not present, no-op."""
    try:
        os.unlink(filename)
    except OSError as e:
        if e.errno != errno.ENOENT:
            raise

def safe_rmtree(directory):
    """Delete a directory if it's present. If it's not present, no-op."""
    if os.path.exists(directory):
        shutil.rmtree(directory, True)

def rename_if_empty(src, dest, allowable_errors=(errno.EEXIST, errno.ENOTEMPTY)):
    """Rename `src` to `dest` using `os.rename()`.

    If an `OSError` with errno in `allowable_errors` is encountered during the rename, the `dest`
    dir is left unchanged and the `src` directory will simply be removed."""
    try:
        os.rename(src, dest)
    except OSError as e:
        if e.errno in allowable_errors:
            safe_rmtree(src)
        else:
            raise

def chmod_plus_x(path):
    """Equivalent of unix `chmod a+x path`"""
    path_mode = os.stat(path).st_mode
    path_mode &= int('777', 8)
    if path_mode & stat.S_IRUSR:
        path_mode |= stat.S_IXUSR
    if path_mode & stat.S_IRGRP:
        path_mode |= stat.S_IXGRP
    if path_mode & stat.S_IROTH:
        path_mode |= stat.S_IXOTH
    os.chmod(path, path_mode)

def touch(file, times=None):
    """Equivalent of unix `touch path`.

    :file The file to touch.
    :times Either a tuple of (atime, mtime) or else a single time to use for both.  If not
    specified both atime and mtime are updated to the current time."""
    if times:
        if len(times) > 2:
            raise ValueError('times must either be a tuple of (atime, mtime) or else a single time value to use for both.')
        if len(times) == 1:
            times = (times, times)
    with safe_open(file, 'a'):
        os.utime(file, times)

def urlsafe_b64decode(data):
    """urlsafe_b64decode without padding"""
    pad = b'=' * (4 - (len(data) & 3))
    return base64.urlsafe_b64decode(data + pad)

def crypto_sign_keypair(seed=None):
    """Return (verifying, secret) key from a given seed, or os.urandom(32)"""
    if seed is None:
        seed = os.urandom(PUBLICKEYBYTES)
    else:
        warnings.warn('ed25519ll should choose random seed.', RuntimeWarning)
    if len(seed) != 32:
        raise ValueError('seed must be 32 random bytes or None.')
    skbytes = seed
    vkbytes = djbec.publickey(skbytes)
    return Keypair(vkbytes, skbytes + vkbytes)

def crypto_sign_open(signed, vk):
    """Return message given signature+message and the verifying key."""
    if len(vk) != PUBLICKEYBYTES:
        raise ValueError('Bad verifying key length %d' % len(vk))
    rc = djbec.checkvalid(signed[:SIGNATUREBYTES], signed[SIGNATUREBYTES:], vk)
    if not rc:
        raise ValueError('rc != True', rc)
    return signed[SIGNATUREBYTES:]

def find_compatible_interpreters(pex_python_path=None, compatibility_constraints=None):
    """Find all compatible interpreters on the system within the supplied constraints and use
    PEX_PYTHON_PATH if it is set. If not, fall back to interpreters on $PATH."""
    if pex_python_path:
        interpreters = []
        for binary in pex_python_path.split(os.pathsep):
            try:
                interpreters.append(PythonInterpreter.from_binary(binary))
            except Executor.ExecutionError:
                print('Python interpreter %s in PEX_PYTHON_PATH failed to load properly.' % binary, file=sys.stderr)
        if not interpreters:
            die('PEX_PYTHON_PATH was defined, but no valid interpreters could be identified. Exiting.')
    else:
        interpreters = OrderedSet([PythonInterpreter.get()])
        interpreters.update(PythonInterpreter.all())
    return list(matched_interpreters(interpreters, compatibility_constraints) if compatibility_constraints else interpreters)

