    validation_options = ('verify_signature', 'retrieve_event')
    if djstripe_settings.WEBHOOK_VALIDATION is None:
        messages.append(checks.Warning('Webhook validation is disabled, this is a security risk if the webhook view is enabled', hint='Set DJSTRIPE_WEBHOOK_VALIDATION to one of {}'.format(', '.join(validation_options)), id='djstripe.W004'))
    elif djstripe_settings.WEBHOOK_VALIDATION == 'verify_signature':
