def GetUnicodeString(value):
    """Attempts to convert the argument to a Unicode string.

    Args:
      value (list|int|bytes|str): value to convert.

    Returns:
      str: string representation of the argument."""
    if isinstance(value, list):
        value = [GetUnicodeString(item) for item in value]
        return ''.join(value)
    if isinstance(value, py2to3.INTEGER_TYPES):
        value = '{0:d}'.format(value)
    if not isinstance(value, py2to3.UNICODE_TYPE):
        return codecs.decode(value, 'utf8', 'ignore')
    return value

def geosearch(latitude, longitude, title=None, results=10, radius=1000):
    """Do a wikipedia geo search for `latitude` and `longitude`
    using HTTP API described in http://www.mediawiki.org/wiki/Extension:GeoData

    Arguments:

    * latitude (float or decimal.Decimal)
    * longitude (float or decimal.Decimal)

    Keyword arguments:

    * title - The title of an article to search for
    * results - the maximum number of results returned
    * radius - Search radius in meters. The value must be between 10 and 10000"""
    search_params = {'list': 'geosearch', 'gsradius': radius, 'gscoord': '{0}|{1}'.format(latitude, longitude), 'gslimit': results}
    if title:
        search_params['titles'] = title
    raw_results = _wiki_request(search_params)
    if 'error' in raw_results:
        if raw_results['error']['info'] in ('HTTP request timed out.', 'Pool queue is full'):
            raise HTTPTimeoutError('{0}|{1}'.format(latitude, longitude))
        else:
            raise WikipediaException(raw_results['error']['info'])
    search_pages = raw_results['query'].get('pages', None)
    if search_pages:
        search_results = (v['title'] for k, v in search_pages.items() if k != '-1')
    else:
        search_results = (d['title'] for d in raw_results['query']['geosearch'])
    return list(search_results)

def suggest(query):
    """Get a Wikipedia search suggestion for `query`.
    Returns a string or None if no suggestion was found."""
    search_params = {'list': 'search', 'srinfo': 'suggestion', 'srprop': ''}
    search_params['srsearch'] = query
    raw_result = _wiki_request(search_params)
    if raw_result['query'].get('searchinfo'):
        return raw_result['query']['searchinfo']['suggestion']
    return None

def page(title=None, pageid=None, auto_suggest=True, redirect=True, preload=False):
    """Get a WikipediaPage object for the page with title `title` or the pageid
    `pageid` (mutually exclusive).

    Keyword arguments:

    * title - the title of the page to load
    * pageid - the numeric pageid of the page to load
    * auto_suggest - let Wikipedia find a valid page title for the query
    * redirect - allow redirection without raising RedirectError
    * preload - load content, summary, images, references, and links during initialization"""
    if title is not None:
        if auto_suggest:
            results, suggestion = search(title, results=1, suggestion=True)
            try:
                title = suggestion or results[0]
            except IndexError:
                raise PageError(title)
        return WikipediaPage(title, redirect=redirect, preload=preload)
    elif pageid is not None:
        return WikipediaPage(pageid=pageid, preload=preload)
    else:
        raise ValueError('Either a title or a pageid must be specified')

def _wiki_request(params):
    """Make a request to the Wikipedia API using the given search parameters.
    Returns a parsed dict of the JSON response."""
    global RATE_LIMIT_LAST_CALL
    global USER_AGENT
    params['format'] = 'json'
    if not 'action' in params:
        params['action'] = 'query'
    headers = {'User-Agent': USER_AGENT}
    if RATE_LIMIT and RATE_LIMIT_LAST_CALL and (RATE_LIMIT_LAST_CALL + RATE_LIMIT_MIN_WAIT > datetime.now()):
        wait_time = RATE_LIMIT_LAST_CALL + RATE_LIMIT_MIN_WAIT - datetime.now()
        time.sleep(int(wait_time.total_seconds()))
    r = requests.get(API_URL, params=params, headers=headers)
    if RATE_LIMIT:
        RATE_LIMIT_LAST_CALL = datetime.now()
    return r.json()

def check_arg_compatibility(args: argparse.Namespace):
    """Check if some arguments are incompatible with each other.

    :param args: Arguments as returned by argparse."""
    if args.lhuc is not None:
        check_condition(args.encoder != C.CONVOLUTION_TYPE or args.decoder != C.CONVOLUTION_TYPE, 'LHUC is not supported for convolutional models yet.')
        check_condition(args.decoder != C.TRANSFORMER_TYPE or C.LHUC_STATE_INIT not in args.lhuc, 'The %s options only applies to RNN models' % C.LHUC_STATE_INIT)
    if args.decoder_only:
        check_condition(args.decoder != C.TRANSFORMER_TYPE and args.decoder != C.CONVOLUTION_TYPE, 'Decoder pre-training currently supports RNN decoders only.')

def use_shared_vocab(args: argparse.Namespace) -> bool:
    """True if arguments entail a shared source and target vocabulary.

    :param: args: Arguments as returned by argparse."""
    weight_tying = args.weight_tying
    weight_tying_type = args.weight_tying_type
    shared_vocab = args.shared_vocab
    decoder_only = args.decoder_only
    if weight_tying and C.WEIGHT_TYING_SRC in weight_tying_type and (C.WEIGHT_TYING_TRG in weight_tying_type):
        if not shared_vocab:
            logger.info('A shared source/target vocabulary will be used as weight tying source/target weight tying is enabled')
        shared_vocab = True
    if decoder_only:
        if not shared_vocab:
            logger.info('A shared source/target vocabulary will be used for pre-training the decoder.')
        shared_vocab = True
    return shared_vocab

def check_encoder_decoder_args(args) -> None:
    """Check possible encoder-decoder argument conflicts.

    :param args: Arguments as returned by argparse."""
    encoder_embed_dropout, decoder_embed_dropout = args.embed_dropout
    encoder_rnn_dropout_inputs, decoder_rnn_dropout_inputs = args.rnn_dropout_inputs
    encoder_rnn_dropout_states, decoder_rnn_dropout_states = args.rnn_dropout_states
    if encoder_embed_dropout > 0 and encoder_rnn_dropout_inputs > 0:
        logger.warning('Setting encoder RNN AND source embedding dropout > 0 leads to two dropout layers on top of each other.')
    if decoder_embed_dropout > 0 and decoder_rnn_dropout_inputs > 0:
        logger.warning('Setting encoder RNN AND source embedding dropout > 0 leads to two dropout layers on top of each other.')
    encoder_rnn_dropout_recurrent, decoder_rnn_dropout_recurrent = args.rnn_dropout_recurrent
    if encoder_rnn_dropout_recurrent > 0 or decoder_rnn_dropout_recurrent > 0:
        check_condition(args.rnn_cell_type == C.LSTM_TYPE, 'Recurrent dropout without memory loss only supported for LSTMs right now.')

