def extract(param_path: str, param_names: List[str], list_all: bool) -> Dict[str, np.ndarray]:
    """Extract specific parameters given their names.

    :param param_path: Path to the parameter file.
    :param param_names: Names of parameters to be extracted.
    :param list_all: List names of all available parameters.
    :return: Extracted parameter dictionary."""
    logger.info("Loading parameters from '%s'", param_path)
    arg_params, aux_params = utils.load_params(param_path)
    ext_params = {}
    param_names = _extract(param_names, arg_params, ext_params)
    param_names = _extract(param_names, aux_params, ext_params)
    if len(param_names) > 0:
        logger.info('The following parameters were not found:')
        for name in param_names:
            logger.info('\t%s', name)
        logger.info('Check the following availabilities')
        list_all = True
    if list_all:
        if arg_params:
            logger.info('Available arg parameters:')
            for name in arg_params:
                logger.info('\t%s: shape=%s', name, str(arg_params[name].shape))
        if aux_params:
            logger.info('Available aux parameters:')
            for name in aux_params:
                logger.info('\t%s: shape=%s', name, str(aux_params[name].shape))
    return ext_params

def are_none(sequences: Sequence[Sized]) -> bool:
    """Returns True if all sequences are None."""
    if not sequences:
        return True
    return all((s is None for s in sequences))

def are_token_parallel(sequences: Sequence[Sized]) -> bool:
    """Returns True if all sequences in the list have the same length."""
    if not sequences or len(sequences) == 1:
        return True
    return all((len(s) == len(sequences[0]) for s in sequences))

def describe_data_and_buckets(data_statistics: DataStatistics, bucket_batch_sizes: List[BucketBatchSize]):
    """Describes statistics across buckets"""
    check_condition(len(bucket_batch_sizes) == len(data_statistics.buckets), 'Number of bucket batch sizes (%d) does not match number of buckets in statistics (%d).' % (len(bucket_batch_sizes), len(data_statistics.buckets)))
    if data_statistics.length_ratio_stats_per_bucket:
        for bucket_batch_size, num_seq, (lr_mean, lr_std) in zip(bucket_batch_sizes, data_statistics.num_sents_per_bucket, data_statistics.length_ratio_stats_per_bucket):
            if num_seq > 0:
                logger.info('Bucket %s: %d samples in %d batches of %d, ~%.1f tokens/batch, trg/src length ratio: %.2f (+-%.2f)', bucket_batch_size.bucket, num_seq, math.ceil(num_seq / bucket_batch_size.batch_size), bucket_batch_size.batch_size, bucket_batch_size.average_words_per_batch, lr_mean, lr_std)
    else:
        for bucket_batch_size, num_seq in zip(bucket_batch_sizes, data_statistics.num_sents_per_bucket):
            if num_seq > 0:
                logger.info('Bucket %s: %d samples in %d batches of %d, ~%.1f tokens/batch, ', bucket_batch_size.bucket, num_seq, math.ceil(num_seq / bucket_batch_size.batch_size), bucket_batch_size.batch_size, bucket_batch_size.average_words_per_batch)

def read_content(path: str, limit: Optional[int]=None) -> Iterator[List[str]]:
    """Returns a list of tokens for each line in path up to a limit.

    :param path: Path to files containing sentences.
    :param limit: How many lines to read from path.
    :return: Iterator over lists of words."""
    with smart_open(path) as indata:
        for i, line in enumerate(indata):
            if limit is not None and i == limit:
                break
            yield list(get_tokens(line))

def strids2ids(tokens: Iterable[str]) -> List[int]:
