def _slugify(text, delim=u'-'):
    """Generates an ASCII-only slug."""
    result = []
    for word in _punct_re.split(text.lower()):
        word = word.encode('utf-8')
        if word:
            result.append(word)
    slugified = delim.join([i.decode('utf-8') for i in result])
    return re.sub('[^a-zA-Z0-9\\s\\-]{1}', replace_char, slugified).lower()

def _regex_from_encoded_pattern(s):
    """'foo'    -> re.compile(re.escape('foo'))
    '/foo/'  -> re.compile('foo')
    '/foo/i' -> re.compile('foo', re.I)"""
    if s.startswith('/') and s.rfind('/') != 0:
        idx = s.rfind('/')
        pattern, flags_str = (s[1:idx], s[idx + 1:])
        flag_from_char = {'i': re.IGNORECASE, 'l': re.LOCALE, 's': re.DOTALL, 'm': re.MULTILINE, 'u': re.UNICODE}
        flags = 0
        for char in flags_str:
            try:
                flags |= flag_from_char[char]
            except KeyError:
                raise ValueError("unsupported regex flag: '%s' in '%s' (must be one of '%s')" % (char, s, ''.join(list(flag_from_char.keys()))))
        return re.compile(s[1:idx], flags)
    else:
        return re.compile(re.escape(s))

def get_worker_class(worker_class=None):
    """Return worker class from RQ settings, otherwise return Worker.
    If `worker_class` is not None, it is used as an override (can be
    python import path as string)."""
    RQ = getattr(settings, 'RQ', {})
    if worker_class is None:
        worker_class = Worker
        if 'WORKER_CLASS' in RQ:
            worker_class = RQ.get('WORKER_CLASS')
    if isinstance(worker_class, six.string_types):
        worker_class = import_attribute(worker_class)
    return worker_class

def get_job_class(job_class=None):
    """Return job class from RQ settings, otherwise return Job.
    If `job_class` is not None, it is used as an override (can be
    python import path as string)."""
    RQ = getattr(settings, 'RQ', {})
    if job_class is None:
        job_class = RQ.get('JOB_CLASS', Job)
    if isinstance(job_class, six.string_types):
        job_class = import_attribute(job_class)
    return job_class

def commit(*args, **kwargs):
    """Processes all jobs in the delayed queue."""
    delayed_queue = get_queue()
    try:
        while delayed_queue:
            queue, args, kwargs = delayed_queue.pop(0)
            queue.original_enqueue_call(*args, **kwargs)
    finally:
        clear()

def get_redis_connection(config, use_strict_redis=False):
    """Returns a redis connection from a connection config"""
    redis_cls = redis.StrictRedis if use_strict_redis else redis.Redis
    if 'URL' in config:
        return redis_cls.from_url(config['URL'], db=config.get('DB'))
    if 'USE_REDIS_CACHE' in config.keys():
        try:
            from django_redis import get_redis_connection as get_redis
            return get_redis(config['USE_REDIS_CACHE'])
        except ImportError:
            pass
        from django.core.cache import caches
        cache = caches[config['USE_REDIS_CACHE']]
        try:
            return cache._client
        except AttributeError:
            return cache.get_master_client()
    if 'UNIX_SOCKET_PATH' in config:
        return redis_cls(unix_socket_path=config['UNIX_SOCKET_PATH'], db=config['DB'])
    if 'SENTINELS' in config:
        sentinel_kwargs = {'db': config.get('DB'), 'password': config.get('PASSWORD'), 'socket_timeout': config.get('SOCKET_TIMEOUT')}
        sentinel_kwargs.update(config.get('CONNECTION_KWARGS', {}))
        sentinel = Sentinel(config['SENTINELS'], **sentinel_kwargs)
        return sentinel.master_for(service_name=config['MASTER_NAME'], redis_class=redis_cls)
    return redis_cls(host=config['HOST'], port=config['PORT'], db=config['DB'], password=config.get('PASSWORD'), ssl=config.get('SSL', False))

def get_connection(name='default', use_strict_redis=False):
    """Returns a Redis connection to use based on parameters in settings.RQ_QUEUES"""
    from .settings import QUEUES
    return get_redis_connection(QUEUES[name], use_strict_redis)

def get_queue(name='default', default_timeout=None, is_async=None, autocommit=None, connection=None, queue_class=None, job_class=None, **kwargs):
    """Returns an rq Queue using parameters defined in ``RQ_QUEUES``"""
    from .settings import QUEUES
    if kwargs.get('async') is not None:
        is_async = kwargs['async']
        warnings.warn('The `async` keyword is deprecated. Use `is_async` instead', DeprecationWarning)
    if is_async is None:
        is_async = QUEUES[name].get('ASYNC', True)
    job_class = get_job_class(job_class)
    if default_timeout is None:
        default_timeout = QUEUES[name].get('DEFAULT_TIMEOUT')
    if connection is None:
        connection = get_connection(name)
    queue_class = get_queue_class(QUEUES[name], queue_class)
    return queue_class(name, default_timeout=default_timeout, connection=connection, is_async=is_async, job_class=job_class, autocommit=autocommit, **kwargs)

def get_queue_by_index(index):
    """Returns an rq Queue using parameters defined in ``QUEUES_LIST``"""
    from .settings import QUEUES_LIST
    config = QUEUES_LIST[int(index)]
    return get_queue_class(config)(config['name'], connection=get_redis_connection(config['connection_config']), is_async=config.get('ASYNC', True))

def filter_connection_params(queue_params):
    """Filters the queue params to keep only the connection related params."""
    CONNECTION_PARAMS = ('URL', 'DB', 'USE_REDIS_CACHE', 'UNIX_SOCKET_PATH', 'HOST', 'PORT', 'PASSWORD', 'SENTINELS', 'MASTER_NAME', 'SOCKET_TIMEOUT', 'SSL', 'CONNECTION_KWARGS')
    return dict(((p, v) for p, v in queue_params.items() if p in CONNECTION_PARAMS))

def get_unique_connection_configs(config=None):
    """Returns a list of unique Redis connections from config"""
    if config is None:
        from .settings import QUEUES
        config = QUEUES
    connection_configs = []
    for key, value in config.items():
        value = filter_connection_params(value)
        if value not in connection_configs:
            connection_configs.append(value)
    return connection_configs

def enqueue_job(request, queue_index, job_id):
    """Enqueue deferred jobs
    """
    queue_index = int(queue_index)
    queue = get_queue_by_index(queue_index)
    job = Job.fetch(job_id, connection=queue.connection)
    if request.method == 'POST':
        queue.enqueue_job(job)
        if job.get_status() == JobStatus.DEFERRED:
            registry = DeferredJobRegistry(queue.name, queue.connection)
            registry.remove(job)
        elif job.get_status() == JobStatus.FINISHED:
            registry = FinishedJobRegistry(queue.name, queue.connection)
            registry.remove(job)
        messages.info(request, 'You have successfully enqueued %s' % job.id)
        return redirect('rq_job_detail', queue_index, job_id)
    context_data = {'queue_index': queue_index, 'job': job, 'queue': queue}
    return render(request, 'django_rq/delete_job.html', context_data)

def job(func_or_queue, connection=None, *args, **kwargs):
    """The same as RQ's job decorator, but it automatically works out
    the ``connection`` argument from RQ_QUEUES.

    And also, it allows simplified ``@job`` syntax to put job into
    default queue.

    If RQ.DEFAULT_RESULT_TTL setting is set, it is used as default
    for ``result_ttl`` kwarg."""
    if callable(func_or_queue):
        func = func_or_queue
        queue = 'default'
    else:
        func = None
        queue = func_or_queue
    if isinstance(queue, six.string_types):
        try:
            queue = get_queue(queue)
            if connection is None:
                connection = queue.connection
        except KeyError:
            pass
    RQ = getattr(settings, 'RQ', {})
    default_result_ttl = RQ.get('DEFAULT_RESULT_TTL')
    if default_result_ttl:
        kwargs.setdefault('result_ttl', default_result_ttl)
    decorator = _rq_job(queue, *args, connection=connection, **kwargs)
    if func:
        return decorator(func)
    return decorator

def to_localtime(time):
    """Converts naive datetime to localtime based on settings"""
    utc_time = time.replace(tzinfo=timezone.utc)
    to_zone = timezone.get_default_timezone()
    return utc_time.astimezone(to_zone)

def ignore_copy(func):
    """Decorator for wrapping the __getattr__ function for classes that are copied via deepcopy.  This prevents infinite
    recursion caused by deepcopy looking for magic functions in the class. Any class implementing __getattr__ that is
    meant to be deepcopy'd should use this decorator.

    deepcopy is used by pypika in builder functions (decorated by @builder) to make the results immutable.  Any data
    model type class (stored in the Query instance) is copied."""
    def _getattr(self, name):
        if name in ['__copy__', '__deepcopy__', '__getstate__', '__setstate__', '__getnewargs__']:
            raise AttributeError("'%s' object has no attribute '%s'" % (self.__class__.__name__, name))
        return func(self, name)
    return _getattr

def resolve_is_aggregate(values):
    """Resolves the is_aggregate flag for an expression that contains multiple terms.  This works like a voter system,
    each term votes True or False or abstains with None.

    :param values: A list of booleans (or None) for each term in the expression
    :return: If all values are True or None, True is returned.  If all values are None, None is returned. Otherwise,
        False is returned."""
    result = [x for x in values if x is not None]
    if result:
        return all(result)
    return None

def native_contracts(address: int, data: BaseCalldata) -> List[int]:
    """Takes integer address 1, 2, 3, 4.

    :param address:
    :param data:
    :return:"""
    functions = (ecrecover, sha256, ripemd160, identity)
    if isinstance(data, ConcreteCalldata):
        concrete_data = data.concrete(None)
    else:
        raise NativeContractException()
    return functions[address - 1](concrete_data)

def get_call_data(global_state: GlobalState, memory_start: Union[int, BitVec], memory_size: Union[int, BitVec]):
    """Gets call_data from the global_state.

    :param global_state: state to look in
    :param memory_start: Start index
    :param memory_size: Size
    :return: Tuple containing: call_data array from memory or empty array if symbolic, type found"""
    state = global_state.mstate
    transaction_id = '{}_internalcall'.format(global_state.current_transaction.id)
    memory_start = cast(BitVec, symbol_factory.BitVecVal(memory_start, 256) if isinstance(memory_start, int) else memory_start)
    memory_size = cast(BitVec, symbol_factory.BitVecVal(memory_size, 256) if isinstance(memory_size, int) else memory_size)
    uses_entire_calldata = simplify(memory_size - global_state.environment.calldata.calldatasize == 0)
    if uses_entire_calldata is True:
        return global_state.environment.calldata
    try:
        calldata_from_mem = state.memory[util.get_concrete_int(memory_start):util.get_concrete_int(memory_start + memory_size)]
        return ConcreteCalldata(transaction_id, calldata_from_mem)
    except TypeError:
        log.debug('Unsupported symbolic calldata offset')
        return SymbolicCalldata(transaction_id)

def And(*args: Union[Bool, bool]) -> Bool:
    """Create an And expression."""
    union = []
    args_list = [arg if isinstance(arg, Bool) else Bool(arg) for arg in args]
    for arg in args_list:
        union.append(arg.annotations)
    return Bool(z3.And([a.raw for a in args_list]), union)

def Not(a: Bool) -> Bool:
    """Create a Not expression.

    :param a:
    :return:"""
    return Bool(z3.Not(a.raw), a.annotations)

def exit_with_error(format_, message):
    """:param format_:
    :param message:"""
    if format_ == 'text' or format_ == 'markdown':
        log.error(message)
    elif format_ == 'json':
        result = {'success': False, 'error': str(message), 'issues': []}
        print(json.dumps(result))
    else:
        result = [{'issues': [], 'sourceType': '', 'sourceFormat': '', 'sourceList': [], 'meta': {'logs': [{'level': 'error', 'hidden': 'true', 'msg': message}]}}]
        print(json.dumps(result))
    sys.exit()

def parse_args(parser: argparse.ArgumentParser, args: argparse.Namespace) -> None:
    """Parses the arguments
    :param parser: The parser
    :param args: The args"""
    if args.epic:
        path = os.path.dirname(os.path.realpath(__file__))
        sys.argv.remove('--epic')
        os.system(' '.join(sys.argv) + ' | python3 ' + path + '/epic.py')
        sys.exit()
    if args.version:
        if args.outform == 'json':
            print(json.dumps({'version_str': VERSION}))
        else:
            print('Mythril version {}'.format(VERSION))
        sys.exit()
    validate_args(parser, args)
    try:
        quick_commands(args)
        config = set_config(args)
        leveldb_search(config, args)
        disassembler = MythrilDisassembler(eth=config.eth, solc_version=args.solv, solc_args=args.solc_args, enable_online_lookup=args.query_signature)
        if args.truffle:
            try:
                disassembler.analyze_truffle_project(args)
            except FileNotFoundError:
                print("Build directory not found. Make sure that you start the analysis from the project root, and that 'truffle compile' has executed successfully.")
            sys.exit()
        address = get_code(disassembler, args)
        execute_command(disassembler=disassembler, address=address, parser=parser, args=args)
    except CriticalError as ce:
        exit_with_error(args.outform, str(ce))
    except Exception:
        exit_with_error(args.outform, traceback.format_exc())

def get_opcode_from_name(operation_name: str) -> int:
    """Get an op code based on its name.

    :param operation_name:
    :return:"""
    for op_code, value in opcodes.items():
        if operation_name == value[0]:
            return op_code
    raise RuntimeError('Unknown opcode')

def find_op_code_sequence(pattern: list, instruction_list: list) -> Generator:
    """Returns all indices in instruction_list that point to instruction
    sequences following a pattern.

    :param pattern: The pattern to look for, e.g. [["PUSH1", "PUSH2"], ["EQ"]] where ["PUSH1", "EQ"] satisfies pattern
    :param instruction_list: List of instructions to look in
    :return: Indices to the instruction sequences"""
    for i in range(0, len(instruction_list) - len(pattern) + 1):
        if is_sequence_match(pattern, instruction_list, i):
            yield i

def is_sequence_match(pattern: list, instruction_list: list, index: int) -> bool:
    """Checks if the instructions starting at index follow a pattern.

    :param pattern: List of lists describing a pattern, e.g. [["PUSH1", "PUSH2"], ["EQ"]] where ["PUSH1", "EQ"] satisfies pattern
    :param instruction_list: List of instructions
    :param index: Index to check for
    :return: Pattern matched"""
    for index, pattern_slot in enumerate(pattern, start=index):
        try:
            if not instruction_list[index]['opcode'] in pattern_slot:
                return False
        except IndexError:
            return False
    return True

def get_code_hash(code: str) -> str:
    """:param code: bytecode
    :return: Returns hash of the given bytecode"""
    code = code[2:] if code[:2] == '0x' else code
    try:
        keccak = sha3.keccak_256()
        keccak.update(bytes.fromhex(code))
        return '0x' + keccak.hexdigest()
    except ValueError:
        log.debug('Unable to change the bytecode to bytes. Bytecode: {}'.format(code))
        return ''

def stat_smt_query(func: Callable):
    """Measures statistics for annotated smt query check function"""
    stat_store = SolverStatistics()
    def function_wrapper(*args, **kwargs):
        if not stat_store.enabled:
            return func(*args, **kwargs)
        stat_store.query_count += 1
        begin = time()
        result = func(*args, **kwargs)
        end = time()
        stat_store.solver_time += end - begin
        return result
    return function_wrapper

def _arithmetic_helper(a: 'BitVecFunc', b: Union[BitVec, int], operation: Callable) -> 'BitVecFunc':
    """Helper function for arithmetic operations on BitVecFuncs.

    :param a: The BitVecFunc to perform the operation on.
    :param b: A BitVec or int to perform the operation on.
    :param operation: The arithmetic operation to perform.
    :return: The resulting BitVecFunc"""
    if isinstance(b, int):
        b = BitVec(z3.BitVecVal(b, a.size()))
    raw = operation(a.raw, b.raw)
    union = a.annotations + b.annotations
    if isinstance(b, BitVecFunc):
        return BitVecFunc(raw=raw, func_name=None, input_=None, annotations=union)
    return BitVecFunc(raw=raw, func_name=a.func_name, input_=a.input_, annotations=union)

def _comparison_helper(a: 'BitVecFunc', b: Union[BitVec, int], operation: Callable, default_value: bool, inputs_equal: bool) -> Bool:
    """Helper function for comparison operations with BitVecFuncs.

    :param a: The BitVecFunc to compare.
    :param b: A BitVec or int to compare to.
    :param operation: The comparison operation to perform.
    :return: The resulting Bool"""
    if isinstance(b, int):
        b = BitVec(z3.BitVecVal(b, a.size()))
    union = a.annotations + b.annotations
    if not a.symbolic and (not b.symbolic):
        return Bool(z3.BoolVal(operation(a.value, b.value)), annotations=union)
    if not isinstance(b, BitVecFunc) or not a.func_name or (not a.input_) or (not a.func_name == b.func_name):
        return Bool(z3.BoolVal(default_value), annotations=union)
    return And(Bool(cast(z3.BoolRef, operation(a.raw, b.raw)), annotations=union), a.input_ == b.input_ if inputs_equal else a.input_ != b.input_)

def detect_mode(term_hint='xterm-256color'):
    """Poor-mans color mode detection."""
    if 'ANSICON' in os.environ:
        return 16
    elif os.environ.get('ConEmuANSI', 'OFF') == 'ON':
        return 256
    else:
        term = os.environ.get('TERM', term_hint)
        if term.endswith('-256color') or term in ('xterm', 'screen'):
            return 256
        elif term.endswith('-color') or term in ('rxvt',):
            return 16
        else:
            return 256

def If(a: Union[Bool, bool], b: Union[BitVec, int], c: Union[BitVec, int]) -> BitVec:
    """Create an if-then-else expression.

    :param a:
    :param b:
    :param c:
    :return:"""
    if not isinstance(a, Bool):
        a = Bool(z3.BoolVal(a))
    if not isinstance(b, BitVec):
        b = BitVec(z3.BitVecVal(b, 256))
    if not isinstance(c, BitVec):
        c = BitVec(z3.BitVecVal(c, 256))
    union = a.annotations + b.annotations + c.annotations
    return BitVec(z3.If(a.raw, b.raw, c.raw), union)

def UGT(a: BitVec, b: BitVec) -> Bool:
    """Create an unsigned greater than expression.

    :param a:
    :param b:
    :return:"""
    return _comparison_helper(a, b, z3.UGT, default_value=False, inputs_equal=False)

def ULE(a: BitVec, b: BitVec) -> Bool:
    """Create an unsigned less than expression.

    :param a:
    :param b:
    :return:"""
    return Or(ULT(a, b), a == b)

def Concat(*args: Union[BitVec, List[BitVec]]) -> BitVec:
    """Create a concatenation expression.

    :param args:
    :return:"""
    if len(args) == 1 and isinstance(args[0], list):
        bvs = args[0]
    else:
        bvs = cast(List[BitVec], args)
    nraw = z3.Concat([a.raw for a in bvs])
    annotations = []
    bitvecfunc = False
    for bv in bvs:
        annotations += bv.annotations
        if isinstance(bv, BitVecFunc):
            bitvecfunc = True
    if bitvecfunc:
        return BitVecFunc(raw=nraw, func_name=None, input_=None, annotations=annotations)
    return BitVec(nraw, annotations)

def URem(a: BitVec, b: BitVec) -> BitVec:
    """Create an unsigned remainder expression.

    :param a:
    :param b:
    :return:"""
    return _arithmetic_helper(a, b, z3.URem)

def SRem(a: BitVec, b: BitVec) -> BitVec:
    """Create a signed remainder expression.

    :param a:
    :param b:
    :return:"""
    return _arithmetic_helper(a, b, z3.SRem)

def UDiv(a: BitVec, b: BitVec) -> BitVec:
    """Create an unsigned division expression.

    :param a:
    :param b:
    :return:"""
    return _arithmetic_helper(a, b, z3.UDiv)

def BVAddNoOverflow(a: Union[BitVec, int], b: Union[BitVec, int], signed: bool) -> Bool:
    """Creates predicate that verifies that the addition doesn't overflow.

    :param a:
    :param b:
    :param signed:
    :return:"""
    if not isinstance(a, BitVec):
        a = BitVec(z3.BitVecVal(a, 256))
    if not isinstance(b, BitVec):
        b = BitVec(z3.BitVecVal(b, 256))
    return Bool(z3.BVAddNoOverflow(a.raw, b.raw, signed))

def build_xoauth_string(url, consumer, token=None):
    """Build an XOAUTH string for use in SMTP/IMPA authentication."""
    request = Request.from_consumer_and_token(consumer, token, 'GET', url)
    signing_method = SignatureMethod_HMAC_SHA1()
    request.sign_request(signing_method, consumer, token)
    params = []
    for k, v in sorted(request.items()):
        if v is not None:
            params.append('%s="%s"' % (k, escape(v)))
    return '%s %s %s' % ('GET', url, ','.join(params))

def to_unicode_optional_iterator(x):
    """Raise TypeError if x is a str containing non-utf8 bytes or if x is
    an iterable which contains such a str."""
    if isinstance(x, STRING_TYPES):
        return to_unicode(x)
    try:
        l = list(x)
    except TypeError as e:
        assert 'is not iterable' in str(e)
        return x
    else:
        return [to_unicode(e) for e in l]

def to_utf8_optional_iterator(x):
    """Raise TypeError if x is a str or if x is an iterable which
    contains a str."""
    if isinstance(x, STRING_TYPES):
        return to_utf8(x)
    try:
        l = list(x)
    except TypeError as e:
        assert 'is not iterable' in str(e)
        return x
    else:
        return [to_utf8_if_string(e) for e in l]

def escape(s):
    """Escape a URL including any /."""
    if not isinstance(s, bytes):
        s = s.encode('utf-8')
    return quote(s, safe='~')

def generate_nonce(length=8):
    """Generate pseudorandom number."""
    return ''.join([str(random.SystemRandom().randint(0, 9)) for i in range(length)])

def _safe_timezone(obj):
    """Creates a timezone instance
    from a string, Timezone, TimezoneInfo or integer offset."""
    if isinstance(obj, _Timezone):
        return obj
    if obj is None or obj == 'local':
        return local_timezone()
    if isinstance(obj, (int, float)):
        obj = int(obj * 60 * 60)
    elif isinstance(obj, _datetime.tzinfo):
        if hasattr(obj, 'localize'):
            obj = obj.zone
        else:
            offset = obj.utcoffset(None)
            if offset is None:
                offset = _datetime.timedelta(0)
            obj = int(offset.total_seconds())
    return timezone(obj)

def datetime(year, month, day, hour=0, minute=0, second=0, microsecond=0, tz=UTC, dst_rule=POST_TRANSITION):
    """Creates a new DateTime instance from a specific date and time."""
    if tz is not None:
        tz = _safe_timezone(tz)
    if not _HAS_FOLD:
        dt = naive(year, month, day, hour, minute, second, microsecond)
    else:
        dt = _datetime.datetime(year, month, day, hour, minute, second, microsecond)
    if tz is not None:
        dt = tz.convert(dt, dst_rule=dst_rule)
    return DateTime(dt.year, dt.month, dt.day, dt.hour, dt.minute, dt.second, dt.microsecond, tzinfo=dt.tzinfo, fold=dt.fold)

def local(year, month, day, hour=0, minute=0, second=0, microsecond=0):
    """Return a DateTime in the local timezone."""
    return datetime(year, month, day, hour, minute, second, microsecond, tz=local_timezone())

def naive(year, month, day, hour=0, minute=0, second=0, microsecond=0):
    """Return a naive DateTime."""
    return DateTime(year, month, day, hour, minute, second, microsecond)

def time(hour, minute=0, second=0, microsecond=0):
    """Create a new Time instance."""
    return Time(hour, minute, second, microsecond)

def instance(dt, tz=UTC):
    """Create a DateTime instance from a datetime one."""
    if not isinstance(dt, _datetime.datetime):
        raise ValueError('instance() only accepts datetime objects.')
    if isinstance(dt, DateTime):
        return dt
    tz = dt.tzinfo or tz
    if isinstance(tz, _datetime.tzinfo) and (not isinstance(tz, _Timezone)):
        if hasattr(tz, 'localize') and tz.zone:
            tz = tz.zone
        else:
            tz = tz.utcoffset(dt).total_seconds() / 3600
    return datetime(dt.year, dt.month, dt.day, dt.hour, dt.minute, dt.second, dt.microsecond, tz=tz)

def now(tz=None):
    """Get a DateTime instance for the current date and time."""
    if has_test_now():
        test_instance = get_test_now()
        _tz = _safe_timezone(tz)
        if tz is not None and _tz != test_instance.timezone:
            test_instance = test_instance.in_tz(_tz)
        return test_instance
    if tz is None or tz == 'local':
        dt = _datetime.datetime.now(local_timezone())
    elif tz is UTC or tz == 'UTC':
        dt = _datetime.datetime.now(UTC)
    else:
        dt = _datetime.datetime.now(UTC)
        tz = _safe_timezone(tz)
        dt = tz.convert(dt)
    return instance(dt, tz)

def from_format(string, fmt, tz=UTC, locale=None):
    """Creates a DateTime instance from a specific format."""
    parts = _formatter.parse(string, fmt, now(), locale=locale)
    if parts['tz'] is None:
        parts['tz'] = tz
    return datetime(**parts)

def duration(days=0, seconds=0, microseconds=0, milliseconds=0, minutes=0, hours=0, weeks=0, years=0, months=0):
    """Create a Duration instance."""
    return Duration(days=days, seconds=seconds, microseconds=microseconds, milliseconds=milliseconds, minutes=minutes, hours=hours, weeks=weeks, years=years, months=months)

def period(start, end, absolute=False):
    """Create a Period instance."""
    return Period(start, end, absolute=absolute)

def timezone(name, extended=True):
    """Return a Timezone instance given its name."""
    if isinstance(name, int):
        return fixed_timezone(name)
    if name.lower() == 'utc':
        return UTC
    if name in _tz_cache:
        return _tz_cache[name]
    tz = _Timezone(name, extended=extended)
    _tz_cache[name] = tz
    return tz

def _normalize(parsed, **options):
    """Normalizes the parsed element.

    :param parsed: The parsed elements.
    :type parsed: Parsed

    :rtype: Parsed"""
    if options.get('exact'):
        return parsed
    if isinstance(parsed, time):
        now = options['now'] or datetime.now()
        return datetime(now.year, now.month, now.day, parsed.hour, parsed.minute, parsed.second, parsed.microsecond)
    elif isinstance(parsed, date) and (not isinstance(parsed, datetime)):
        return datetime(parsed.year, parsed.month, parsed.day)
    return parsed

def sec_to_public_pair(sec, generator=None, strict=True):
    """Convert a public key in sec binary format to a public pair."""
    byte_count = generator.p().bit_length() + 7 >> 3 if generator else len(sec) - 1
    x = from_bytes_32(sec[1:1 + byte_count])
    sec0 = sec[:1]
    if len(sec) == 1 + byte_count * 2:
        isok = sec0 == b'\x04'
        if not strict:
            isok = isok or sec0 in [b'\x06', b'\x07']
        if isok:
            y = from_bytes_32(sec[1 + byte_count:1 + 2 * byte_count])
            return (x, y)
    elif len(sec) == 1 + byte_count:
        if not strict or sec0 in (b'\x02', b'\x03'):
            is_y_odd = sec0 != b'\x02'
            return generator.points_for_x(x)[is_y_odd]
    raise EncodingError('bad sec encoding for public key')

def _from_bytes(bytes, byteorder='big', signed=False):
    """This is the same functionality as ``int.from_bytes`` in python 3"""
    return int.from_bytes(bytes, byteorder=byteorder, signed=signed)

def groestlHash(data):
    """Groestl-512 compound hash."""
    try:
        import groestlcoin_hash
    except ImportError:
        t = 'Groestlcoin requires the groestlcoin_hash package ("pip install groestlcoin_hash").'
        print(t)
        raise ImportError(t)
    return bytes_as_revhex(groestlcoin_hash.getHash(data, len(data)))

def merkle(hashes, hash_f=double_sha256):
    """Take a list of hashes, and return the root merkle hash."""
    while len(hashes) > 1:
        hashes = merkle_pair(hashes, hash_f)
    return hashes[0]

def merkle_pair(hashes, hash_f):
    """Take a list of hashes, and return the parent row in the tree of merkle hashes."""
    if len(hashes) % 2 == 1:
        hashes = list(hashes)
        hashes.append(hashes[-1])
    items = []
    for i in range(0, len(hashes), 2):
        items.append(hash_f(hashes[i] + hashes[i + 1]))
    return items

def crack_secret_exponent_from_k(generator, signed_value, sig, k):
    """Given a signature of a signed_value and a known k, return the secret exponent."""
    r, s = sig
    return (s * k - signed_value) * generator.inverse(r) % generator.order()

def crack_k_from_sigs(generator, sig1, val1, sig2, val2):
    """Given two signatures with the same secret exponent and K value, return that K value."""
    r1, s1 = sig1
    r2, s2 = sig2
    if r1 != r2:
        raise ValueError('r values of signature do not match')
    k = (r2 * val1 - r1 * val2) * generator.inverse(r2 * s1 - r1 * s2)
    return k % generator.order()

def subpaths_for_path_range(path_range, hardening_chars="'pH"):
    """Return an iterator of paths

        # examples:
        #   0/1H/0-4 => ['0/1H/0', '0/1H/1', '0/1H/2', '0/1H/3', '0/1H/4']
        #   0/2,5,9-11 => ['0/2', '0/5', '0/9', '0/10', '0/11']
        #   3H/2/5/15-20p => ['3H/2/5/15p', '3H/2/5/16p', '3H/2/5/17p', '3H/2/5/18p',
        #          '3H/2/5/19p', '3H/2/5/20p']
        #   5-6/7-8p,15/1-2 => ['5/7H/1', '5/7H/2', '5/8H/1', '5/8H/2',
        #         '5/15/1', '5/15/2', '6/7H/1', '6/7H/2', '6/8H/1', '6/8H/2', '6/15/1', '6/15/2']"""
    if path_range == '':
        yield ''
        return
    def range_iterator(the_range):
        for r in the_range.split(','):
            is_hardened = r[-1] in hardening_chars
            hardened_char = hardening_chars[-1] if is_hardened else ''
            if is_hardened:
                r = r[:-1]
            if '-' in r:
                low, high = [int(x) for x in r.split('-', 1)]
                for t in range(low, high + 1):
                    yield ('%d%s' % (t, hardened_char))
            else:
                yield ('%s%s' % (r, hardened_char))
    components = path_range.split('/')
    iterators = [range_iterator(c) for c in components]
    for v in itertools.product(*iterators):
        yield '/'.join(v)

def spendables_for_address(address, netcode, format=None):
    """Return a list of Spendable objects for the
    given bitcoin address.

    Set format to "text" or "dict" to transform return value
    from an object to a string or dict.

    This is intended to be a convenience function. There is no way to know that
    the list returned is a complete list of spendables for the address in question.

    You can verify that they really do come from the existing transaction
    by calling tx_utils.validate_unspents."""
    if format:
        method = 'as_%s' % format
    for m in service_provider_methods('spendables_for_address', get_default_providers_for_netcode(netcode)):
        try:
            spendables = m(address)
            if format:
                spendables = [getattr(s, method)() for s in spendables]
            return spendables
        except Exception:
            pass
    return []

def double_sha256(data):
    """A standard compound hash."""
    return bytes_as_revhex(hashlib.sha256(hashlib.sha256(data).digest()).digest())

def make_const_handler(data):
    """Create a handler for a data opcode that returns a constant."""
    data = bytes_as_hex(data)
    def constant_data_opcode_handler(script, pc, verify_minimal_data=False):
        return (pc + 1, data)
    return constant_data_opcode_handler

def make_sized_handler(size, const_values, non_minimal_data_handler):
    """Create a handler for a data opcode that returns literal data of a fixed size."""
    const_values = list(const_values)
    def constant_size_opcode_handler(script, pc, verify_minimal_data=False):
        pc += 1
        data = bytes_as_hex(script[pc:pc + size])
        if len(data) < size:
            return (pc + 1, None)
        if verify_minimal_data and data in const_values:
            non_minimal_data_handler('not minimal push of %s' % repr(data))
        return (pc + size, data)
    return constant_size_opcode_handler

def make_variable_handler(dec_f, sized_values, min_size, non_minimal_data_handler):
    """Create a handler for a data opcode that returns literal data of a variable size
    that's fetched and decoded by the function dec_f."""
    sized_values = list(sized_values)
    def f(script, pc, verify_minimal_data=False):
        size, pc = dec_f(script, pc)
        data = bytes_as_hex(script[pc:pc + size])
        if len(data) < size:
            return (pc + 1, None)
        if verify_minimal_data:
            if size in sized_values or size <= min_size:
                non_minimal_data_handler('not minimal push of data with size %d' % size)
        return (pc + size, data)
    return f

def initial_key_to_master_key(initial_key):
    """initial_key:
        a hex string of length 32"""
    b = initial_key.encode('utf8')
    orig_input = b
    for i in range(100000):
        b = hashlib.sha256(b + orig_input).digest()
    return from_bytes_32(b)

def _make_parser(streamer, the_struct):
    """Return a function that parses the given structure into a dict"""
    struct_items = [s.split(':') for s in the_struct.split()]
    names = [s[0] for s in struct_items]
    types = ''.join((s[1] for s in struct_items))
    def f(message_stream):
        return streamer.parse_as_dict(names, types, message_stream)
    return f

def iterate_symbols():
    """Return an iterator yielding registered netcodes."""
    for prefix in search_prefixes():
        package = importlib.import_module(prefix)
        for importer, modname, ispkg in pkgutil.walk_packages(path=package.__path__, onerror=lambda x: None):
            network = network_for_netcode(modname)
            if network:
                yield network.symbol.upper()

def b2a_base58(s):
    """Convert binary to base58 using BASE58_ALPHABET. Like Bitcoin addresses."""
    v, prefix = to_long(256, lambda x: x, iterbytes(s))
    s = from_long(v, prefix, BASE58_BASE, lambda v: BASE58_ALPHABET[v])
    return s.decode('utf8')

def a2b_base58(s):
    """Convert base58 to binary using BASE58_ALPHABET."""
    v, prefix = to_long(BASE58_BASE, lambda c: BASE58_LOOKUP[c], s.encode('utf8'))
    return from_long(v, prefix, 256, lambda x: x)

