def html_format(value):
    """Returns the value formatted in HTML,
    depends on MARKUP_LANGUAGE setting."""
    if not value:
        return ''
    elif MARKUP_LANGUAGE == 'markdown':
        return markdown(value)
    elif MARKUP_LANGUAGE == 'textile':
        return textile(value)
    elif MARKUP_LANGUAGE == 'restructuredtext':
        return restructuredtext(value)
    elif '</p>' not in value:
        return linebreaks(value)
    return value

def union_q(token):
    """Appends all the Q() objects."""
    query = Q()
    operation = 'and'
    negation = False
    for t in token:
        if type(t) is ParseResults:
            query &= union_q(t)
        elif t in ('or', 'and'):
            operation = t
        elif t == '-':
            negation = True
        else:
            if negation:
                t = ~t
            if operation == 'or':
                query |= t
            else:
                query &= t
    return query

