def zinnia_pagination(context, page, begin_pages=1, end_pages=1, before_pages=2, after_pages=2, template='zinnia/tags/pagination.html'):
    """Return a Digg-like pagination,
    by splitting long list of page into 3 blocks of pages."""
    get_string = ''
    for key, value in context['request'].GET.items():
        if key != 'page':
            get_string += '&%s=%s' % (key, value)
    page_range = list(page.paginator.page_range)
    begin = page_range[:begin_pages]
    end = page_range[-end_pages:]
    middle = page_range[max(page.number - before_pages - 1, 0):page.number + after_pages]
    if set(begin) & set(middle):
        begin = sorted(set(begin + middle))
        middle = []
    elif begin[-1] + 1 == middle[0]:
        begin += middle
        middle = []
    elif middle[-1] + 1 == end[0]:
        end = middle + end
        middle = []
    elif set(middle) & set(end):
        end = sorted(set(middle + end))
        middle = []
    if set(begin) & set(end):
        begin = sorted(set(begin + end))
        middle, end = ([], [])
    elif begin[-1] + 1 == end[0]:
        begin += end
        middle, end = ([], [])
    return {'template': template, 'page': page, 'begin': begin, 'middle': middle, 'end': end, 'GET_string': get_string}

def get_gravatar(email, size=80, rating='g', default=None, protocol=PROTOCOL):
    """Return url for a Gravatar."""
    gravatar_protocols = {'http': 'http://www', 'https': 'https://secure'}
    url = '%s.gravatar.com/avatar/%s' % (gravatar_protocols[protocol], md5(email.strip().lower().encode('utf-8')).hexdigest())
    options = {'s': size, 'r': rating}
    if default:
        options['d'] = default
    url = '%s?%s' % (url, urlencode(options))
    return url.replace('&', '&amp;')

