def _new_java_obj(sc, java_class, *args):
    """Construct a new Java object."""
    java_obj = _jvm()
    for name in java_class.split('.'):
        java_obj = getattr(java_obj, name)
    java_args = [_py2java(sc, arg) for arg in args]
    return java_obj(*java_args)

