    m = getattr(java_obj, name)
    java_args = [_py2java(sc, arg) for arg in args]
    return _java2py(sc, m(*java_args))

def archiver_for_path(path_name):
    """Returns an Archiver for the given path name.

    :API: public

    :param string path_name: The path name of the archive - need not exist.
    :raises: :class:`ValueError` If the path name does not uniquely identify a supported archive type."""
    if path_name.endswith('.tar.gz'):
        return TGZ
    elif path_name.endswith('.tar.bz2'):
        return TBZ2
    else:
        _, ext = os.path.splitext(path_name)
        if ext:
            ext = ext[1:]
        if not ext:
            raise ValueError('Could not determine archive type of path {}'.format(path_name))
        return create_archiver(ext)

def teardown_socket(s):
    """Shuts down and closes a socket."""
    try:
        s.shutdown(socket.SHUT_WR)
    except socket.error:
        pass
    finally:
        s.close()

def _get_runner(classpath, main, jvm_options, args, executor, cwd, distribution, create_synthetic_jar, synthetic_jar_dir):
    """Gets the java runner for execute_java and execute_java_async."""
    executor = executor or SubprocessExecutor(distribution)
    safe_cp = classpath
    if create_synthetic_jar:
        safe_cp = safe_classpath(classpath, synthetic_jar_dir)
        logger.debug('Bundling classpath {} into {}'.format(':'.join(classpath), safe_cp))
    return executor.runner(safe_cp, main, args=args, jvm_options=jvm_options, cwd=cwd)

def find_paths_breadth_first(from_target, to_target, log):
    """Yields the paths between from_target to to_target if they exist.

    The paths are returned ordered by length, shortest first.
    If there are cycles, it checks visited edges to prevent recrossing them."""
    log.debug('Looking for all paths from {} to {}'.format(from_target.address.reference(), to_target.address.reference()))
    if from_target == to_target:
        yield [from_target]
        return
    visited_edges = set()
    to_walk_paths = deque([[from_target]])
    while len(to_walk_paths) > 0:
        cur_path = to_walk_paths.popleft()
        target = cur_path[-1]
        if len(cur_path) > 1:
            prev_target = cur_path[-2]
        else:
            prev_target = None
        current_edge = (prev_target, target)
        if current_edge not in visited_edges:
            for dep in target.dependencies:
                dep_path = cur_path + [dep]
                if dep == to_target:
                    yield dep_path
                else:
                    to_walk_paths.append(dep_path)
            visited_edges.add(current_edge)

def invert_dependencies(targets):
    """:API: public

    :return: the full graph of dependencies for `targets` and the list of roots."""
    roots = set()
    inverted_deps = defaultdict(OrderedSet)
    visited = set()
    path = OrderedSet()
    def invert(tgt):
        if tgt in path:
            path_list = list(path)
            cycle_head = path_list.index(tgt)
            cycle = path_list[cycle_head:] + [tgt]
            raise CycleException(cycle)
        path.add(tgt)
        if tgt not in visited:
            visited.add(tgt)
            if tgt.dependencies:
                for dependency in tgt.dependencies:
                    inverted_deps[dependency].add(tgt)
                    invert(dependency)
            else:
                roots.add(tgt)
        path.remove(tgt)
    for target in targets:
        invert(target)
    return (roots, inverted_deps)

def sort_targets(targets):
    """:API: public

    :return: the targets that `targets` depend on sorted from most dependent to least."""
    roots, inverted_deps = invert_dependencies(targets)
    ordered = []
    visited = set()
    def topological_sort(target):
        if target not in visited:
            visited.add(target)
            if target in inverted_deps:
                for dep in inverted_deps[target]:
                    topological_sort(dep)
            ordered.append(target)
    for root in roots:
        topological_sort(root)
    return ordered

def is_builtin_name(name):
    """For example, __foo__ or __bar__."""
    if name.startswith('__') and name.endswith('__'):
        return ALL_LOWER_CASE_RE.match(name[2:-2]) is not None
    return False

def check_header(filename, is_newly_created=False):
    """Raises `HeaderCheckFailure` if the header doesn't match."""
    try:
        with open(filename, 'r') as pyfile:
            buf = ''
            for lineno in range(1, 7):
                line = pyfile.readline()
                if lineno == 1 and line.startswith('#!'):
                    line = pyfile.readline()
                if line.startswith('# Copyright'):
                    year = line[12:16]
                    if is_newly_created:
                        if not year == _current_year:
                            raise HeaderCheckFailure('{}: copyright year must be {} (was {})'.format(filename, _current_year, year))
                    elif not _current_century_regex.match(year):
                        raise HeaderCheckFailure("{}: copyright year must match '{}' (was {}): current year is {}".format(filename, _current_century_regex.pattern, year, _current_year))
                    line = '# Copyright YYYY' + line[16:]
                buf += line
            if buf != EXPECTED_HEADER:
                raise HeaderCheckFailure('{}: failed to parse header at all'.format(filename))
    except IOError as e:
        raise HeaderCheckFailure('{}: error while reading input ({})'.format(filename, str(e)))

def check_dir(directory, newly_created_files):
    """Returns list of files that fail the check."""
    header_parse_failures = []
    for root, dirs, files in os.walk(directory):
        for f in files:
            if f.endswith('.py') and os.path.basename(f) != '__init__.py':
                filename = os.path.join(root, f)
                try:
                    check_header(filename, filename in newly_created_files)
                except HeaderCheckFailure as e:
                    header_parse_failures.append(e.message)
    return header_parse_failures

def load_soups(config):
    """Generate BeautifulSoup AST for each page listed in config."""
    soups = {}
    for page, path in config['sources'].items():
        with open(path, 'r') as orig_file:
            soups[page] = beautiful_soup(orig_file.read(), features='html.parser')
    return soups

def precompute(config, soups):
    """Return info we want to compute (and preserve) before we mutate things."""
    show_toc = config.get('show_toc', {})
    page = {}
    pantsrefs = precompute_pantsrefs(soups)
    for p, soup in soups.items():
        title = get_title(soup) or p
        page[p] = PrecomputedPageInfo(title=title, show_toc=show_toc.get(p, True))
    return Precomputed(page=page, pantsref=pantsrefs)

def fixup_internal_links(config, soups):
    """Find href="..." links that link to pages in our docset; fix them up.

    We don't preserve relative paths between files as we copy-transform them
    from source to dest. So adjust the paths to work with new locations."""
    reverse_directory = {}
    for d, s in config['sources'].items():
        reverse_directory[s] = d
    for name, soup in soups.items():
        old_src_dir = os.path.dirname(config['sources'][name])
        for tag in soup.find_all(True):
            if not 'href' in tag.attrs:
                continue
            old_rel_path = tag['href'].split('#')[0]
            old_dst = os.path.normpath(os.path.join(old_src_dir, old_rel_path))
            if not old_dst in reverse_directory:
                continue
            new_dst = reverse_directory[old_dst] + '.html'
            new_rel_path = rel_href(name, new_dst)
            tag['href'] = tag['href'].replace(old_rel_path, new_rel_path, 1)

def rel_href(src, dst):
    """For src='foo/bar.html', dst='garply.html#frotz' return relative link '../garply.html#frotz'.
    """
    src_dir = os.path.dirname(src)
    return os.path.relpath(dst, src_dir)

def find_existing_anchors(soup):
    """Return existing ids (and names) from a soup."""
    existing_anchors = set()
    for tag in soup.find_all(True):
        for attr in ['id', 'name']:
            if tag.has_attr(attr):
                existing_anchors.add(tag.get(attr))
    return existing_anchors

def link_pantsrefs(soups, precomputed):
    """Transorm soups: <a pantsref="foo"> becomes <a href="../foo_page.html#foo">"""
    for page, soup in soups.items():
        for a in soup.find_all('a'):
            if not a.has_attr('pantsref'):
                continue
            pantsref = a['pantsref']
            if not pantsref in precomputed.pantsref:
                raise TaskError('Page {} has pantsref "{}" and I cannot find pantsmark for it'.format(page, pantsref))
            a['href'] = rel_href(page, precomputed.pantsref[pantsref])

def get_title(soup):
    """Given a soup, pick out a title"""
    if soup.title:
        return soup.title.string
    if soup.h1:
        return soup.h1.string
    return ''

def hdepth(tag):
    """Compute an h tag's "outline depth".

    E.g., h1 at top level is 1, h1 in a section is 2, h2 at top level is 2."""
    if not _heading_re.search(tag.name):
        raise TaskError("Can't compute heading depth of non-heading {}".format(tag))
    depth = int(tag.name[1], 10)
    cursor = tag
    while cursor:
        if cursor.name == 'section':
            depth += 1
        cursor = cursor.parent
    return depth

def generate_page_toc(soup):
    """Return page-level (~list of headings) TOC template data for soup"""
    found_depth_counts = collections.defaultdict(int)
    for tag in soup.find_all(_heading_re):
        if tag.get('id') or tag.get('name'):
            found_depth_counts[hdepth(tag)] += 1
    depth_list = [i for i in range(100) if 1 < found_depth_counts[i]]
    depth_list = depth_list[:4]
    toc = []
    for tag in soup.find_all(_heading_re):
        depth = hdepth(tag)
        if depth in depth_list:
            toc.append(dict(depth=depth_list.index(depth) + 1, link=tag.get('id') or tag.get('name'), text=tag.text))
    return toc

def copy_extras(config):
    """copy over "extra" files named in config json: stylesheets, logos, ..."""
    outdir = config['outdir']
    for dst, src in config['extras'].items():
        dst_path = os.path.join(outdir, dst)
        dst_dir = os.path.dirname(dst_path)
        if not os.path.isdir(dst_dir):
            os.makedirs(dst_dir)
        shutil.copy(src, dst_path)

def create_legacy_graph_tasks():
    """Create tasks to recursively parse the legacy graph."""
    return [transitive_hydrated_targets, transitive_hydrated_target, hydrated_targets, hydrate_target, find_owners, hydrate_sources, hydrate_bundles, RootRule(OwnersRequest)]

def _make_target_adaptor(base_class, target_type):
    """Look up the default source globs for the type, and apply them to parsing through the engine."""
    if not target_type.supports_default_sources() or target_type.default_sources_globs is None:
        return base_class
    globs = _tuplify(target_type.default_sources_globs)
    excludes = _tuplify(target_type.default_sources_exclude_globs)
    class GlobsHandlingTargetAdaptor(base_class):
        @property
        def default_sources_globs(self):
            if globs is None:
                return super(GlobsHandlingTargetAdaptor, self).default_sources_globs
            else:
                return globs
        @property
        def default_sources_exclude_globs(self):
            if excludes is None:
                return super(GlobsHandlingTargetAdaptor, self).default_sources_exclude_globs
            else:
                return excludes
    return GlobsHandlingTargetAdaptor

def default_subsystem_for_plugin(plugin_type):
    """Create a singleton PluginSubsystemBase subclass for the given plugin type.

    The singleton enforcement is useful in cases where dependent Tasks are installed multiple times,
    to avoid creating duplicate types which would have option scope collisions.

    :param plugin_type: A CheckstylePlugin subclass.
    :type: :class:`pants.contrib.python.checks.checker.common.CheckstylePlugin`
    :rtype: :class:`pants.contrib.python.checks.tasks.checkstyle.plugin_subsystem_base.PluginSubsystemBase`"""
    if not issubclass(plugin_type, CheckstylePlugin):
        raise ValueError('Can only create a default plugin subsystem for subclasses of {}, given: {}'.format(CheckstylePlugin, plugin_type))
    return type(str('{}Subsystem'.format(plugin_type.__name__)), (PluginSubsystemBase,), {str('options_scope'): 'pycheck-{}'.format(plugin_type.name()), str('plugin_type'): classmethod(lambda cls: plugin_type), str('register_plugin_options'): classmethod(lambda cls, register: None)})

def combined_dict(*dicts):
    """Combine one or more dicts into a new, unified dict (dicts to the right take precedence)."""
    return {k: v for d in dicts for k, v in d.items()}

def factory_dict(value_factory, *args, **kwargs):
    """A dict whose values are computed by `value_factory` when a `__getitem__` key is missing.

    Note that values retrieved by any other method will not be lazily computed; eg: via `get`.

    :param value_factory:
    :type value_factory: A function from dict key to value.
    :param *args: Any positional args to pass through to `dict`.
    :param **kwrags: Any kwargs to pass through to `dict`.
    :rtype: dict"""
    class FactoryDict(collections.defaultdict):
        @staticmethod
        def __never_called():
            raise AssertionError('The default factory should never be called since we override __missing__.')
        def __init__(self):
            super(FactoryDict, self).__init__(self.__never_called, *args, **kwargs)
        def __missing__(self, key):
            value = value_factory(key)
            self[key] = value
            return value
    return FactoryDict()

def recursively_update(d, d2):
    """dict.update but which merges child dicts (dict2 takes precedence where there's conflict)."""
    for k, v in d2.items():
        if k in d:
            if isinstance(v, dict):
                recursively_update(d[k], v)
                continue
        d[k] = v

def equal_args(*args, **kwargs):
    """A memoized key factory that compares the equality (`==`) of a stable sort of the parameters."""
    key = args
    if kwargs:
        key += _kwargs_separator + tuple(sorted(kwargs.items()))
    return key

def _replace_file(path, content):
    """Writes a file if it doesn't already exist with the same content.

    This is useful because cargo uses timestamps to decide whether to compile things."""
    if os.path.exists(path):
        with open(path, 'r') as f:
            if content == f.read():
                print('Not overwriting {} because it is unchanged'.format(path), file=sys.stderr)
                return
    with open(path, 'w') as f:
        f.write(content)

def rewrite_record_file(workspace, src_record_file, mutated_file_tuples):
    """Given a RECORD file and list of mutated file tuples, update the RECORD file in place.

    The RECORD file should always be a member of the mutated files, due to both containing
    versions, and having a version in its filename."""
    mutated_files = set()
    dst_record_file = None
    for src, dst in mutated_file_tuples:
        if src == src_record_file:
            dst_record_file = dst
        else:
            mutated_files.add(dst)
    if not dst_record_file:
        raise Exception('Malformed whl or bad globs: `{}` was not rewritten.'.format(src_record_file))
    output_records = []
    file_name = os.path.join(workspace, dst_record_file)
    for line in read_file(file_name).splitlines():
        filename, fingerprint_str, size_str = line.rsplit(',', 3)
        if filename in mutated_files:
            fingerprint_str, size_str = fingerprint_file(workspace, filename)
            output_line = ','.join((filename, fingerprint_str, size_str))
        else:
            output_line = line
        output_records.append(output_line)
    safe_file_dump(file_name, '\r\n'.join(output_records) + '\r\n')

def ui_open(*files):
    """Attempts to open the given files using the preferred desktop viewer or editor.

    :raises :class:`OpenError`: if there is a problem opening any of the files."""
    if files:
        osname = get_os_name()
        opener = _OPENER_BY_OS.get(osname)
        if opener:
            opener(files)
        else:
            raise OpenError('Open currently not supported for ' + osname)

def environment_as(**kwargs):
    """Update the environment to the supplied values, for example:

    with environment_as(PYTHONPATH='foo:bar:baz',
                        PYTHON='/usr/bin/python2.7'):
      subprocess.Popen(foo).wait()"""
    new_environment = kwargs
    old_environment = {}
    def setenv(key, val):
        if val is not None:
            os.environ[key] = val if PY3 else _os_encode(val)
        elif key in os.environ:
            del os.environ[key]
    for key, val in new_environment.items():
        old_environment[key] = os.environ.get(key)
        setenv(key, val)
    try:
        yield
    finally:
        for key, val in old_environment.items():
            setenv(key, val)

def safe_file(path, suffix=None, cleanup=True):
    """A with-context that copies a file, and copies the copy back to the original file on success.

    This is useful for doing work on a file but only changing its state on success.

    :param str suffix: Use this suffix to create the copy. Otherwise use a random string.
    :param bool cleanup: Whether or not to clean up the copy."""
    safe_path = '{0}.{1}'.format(path, suffix or uuid.uuid4())
    if os.path.exists(path):
        shutil.copy(path, safe_path)
    try:
        yield safe_path
        if cleanup:
            shutil.move(safe_path, path)
        else:
            shutil.copy(safe_path, path)
    finally:
        if cleanup:
            safe_delete(safe_path)

def safe_shlex_split(text_or_binary):
    """Split a string using shell-like syntax.

    Safe even on python versions whose shlex.split() method doesn't accept unicode."""
    value = ensure_text(text_or_binary) if PY3 else ensure_binary(text_or_binary)
    return shlex.split(value)

def create_path_env_var(new_entries, env=None, env_var='PATH', delimiter=':', prepend=False):
    """Join path entries, combining with an environment variable if specified."""
    if env is None:
        env = {}
    prev_path = env.get(env_var, None)
    if prev_path is None:
        path_dirs = list()
    else:
        path_dirs = list(prev_path.split(delimiter))
    new_entries_list = list(new_entries)
    if prepend:
        path_dirs = new_entries_list + path_dirs
    else:
        path_dirs += new_entries_list
    return delimiter.join(path_dirs)

def pluralize(count, item_type):
    """Pluralizes the item_type if the count does not equal one.

    For example `pluralize(1, 'apple')` returns '1 apple',
    while `pluralize(0, 'apple') returns '0 apples'.

    :return The count and inflected item_type together as a string
    :rtype string"""
    def pluralize_string(x):
        if x.endswith('s'):
            return x + 'es'
        else:
            return x + 's'
    text = '{} {}'.format(count, item_type if count == 1 else pluralize_string(item_type))
    return text

def target_internal_dependencies(target):
    """Returns internal Jarable dependencies that were "directly" declared.

    Directly declared deps are those that are explicitly listed in the definition of a
    target, rather than being depended on transitively. But in order to walk through
    aggregator targets such as `target`, `dependencies`, or `jar_library`, this recursively
    descends the dep graph and stops at Jarable instances."""
    for dep in target.dependencies:
        if isinstance(dep, Jarable):
            yield dep
        else:
            for childdep in target_internal_dependencies(dep):
                yield childdep

def longest_dir_prefix(path, prefixes):
    """Given a list of prefixes, return the one that is the longest prefix to the given path.

    Returns None if there are no matches."""
    longest_match, longest_prefix = (0, None)
    for prefix in prefixes:
        if fast_relpath_optional(path, prefix) is not None and len(prefix) > longest_match:
            longest_match, longest_prefix = (len(prefix), prefix)
    return longest_prefix

def fast_relpath(path, start):
    """A prefix-based relpath, with no normalization or support for returning `..`."""
    relpath = fast_relpath_optional(path, start)
    if relpath is None:
        raise ValueError('{} is not a directory containing {}'.format(start, path))
    return relpath

def fast_relpath_optional(path, start):
    """A prefix-based relpath, with no normalization or support for returning `..`.

    Returns None if `start` is not a directory-aware prefix of `path`."""
    if len(start) == 0:
        return path
    pref_end = len(start) - 1 if start[-1] == '/' else len(start)
    if pref_end > len(path):
        return None
    elif path[:pref_end] == start[:pref_end] and (len(path) == pref_end or path[pref_end] == '/'):
        return path[pref_end + 1:]

def safe_mkdtemp(cleaner=_mkdtemp_atexit_cleaner, **kw):
    """Create a temporary directory that is cleaned up on process exit.

    Arguments are as to tempfile.mkdtemp.

    :API: public"""
    with _MKDTEMP_LOCK:
        return register_rmtree(tempfile.mkdtemp(**kw), cleaner=cleaner)

def safe_rmtree(directory):
    """Delete a directory if it's present. If it's not present, no-op.

    Note that if the directory argument is a symlink, only the symlink will
    be deleted.

    :API: public"""
    if os.path.islink(directory):
        safe_delete(directory)
    else:
        shutil.rmtree(directory, ignore_errors=True)

def safe_open(filename, *args, **kwargs):
    """Open a file safely, ensuring that its directory exists.

    :API: public"""
    safe_mkdir_for(filename)
    return open(filename, *args, **kwargs)

def safe_concurrent_rename(src, dst):
    """Rename src to dst, ignoring errors due to dst already existing.

    Useful when concurrent processes may attempt to create dst, and it doesn't matter who wins."""
    if os.path.isdir(src):
        safe_rmtree(dst)
    else:
        safe_delete(dst)
    try:
        shutil.move(src, dst)
    except IOError as e:
        if e.errno != errno.EEXIST:
            raise

def safe_rm_oldest_items_in_dir(root_dir, num_of_items_to_keep, excludes=frozenset()):
    """Keep `num_of_items_to_keep` newly modified items besides `excludes` in `root_dir` then remove the rest.
    :param root_dir: the folder to examine
    :param num_of_items_to_keep: number of files/folders/symlinks to keep after the cleanup
    :param excludes: absolute paths excluded from removal (must be prefixed with `root_dir`)
    :return: none"""
    if os.path.isdir(root_dir):
        found_files = []
        for old_file in os.listdir(root_dir):
            full_path = os.path.join(root_dir, old_file)
            if full_path not in excludes:
                found_files.append((full_path, os.path.getmtime(full_path)))
        found_files = sorted(found_files, key=lambda x: x[1], reverse=True)
        for cur_file, _ in found_files[num_of_items_to_keep:]:
            rm_rf(cur_file)

def safe_concurrent_creation(target_path):
    """A contextmanager that yields a temporary path and renames it to a final target path when the
    contextmanager exits.

    Useful when concurrent processes may attempt to create a file, and it doesn't matter who wins.

    :param target_path: The final target path to rename the temporary path to.
    :yields: A temporary path containing the original path with a unique (uuid4) suffix."""
    safe_mkdir_for(target_path)
    tmp_path = '{}.tmp.{}'.format(target_path, uuid.uuid4().hex)
    try:
        yield tmp_path
    except Exception:
        rm_rf(tmp_path)
        raise
    else:
        if os.path.exists(tmp_path):
            safe_concurrent_rename(tmp_path, target_path)

def absolute_symlink(source_path, target_path):
    """Create a symlink at target pointing to source using the absolute path.

    :param source_path: Absolute path to source file
    :param target_path: Absolute path to intended symlink
    :raises ValueError if source_path or link_path are not unique, absolute paths
    :raises OSError on failure UNLESS file already exists or no such file/directory"""
    if not os.path.isabs(source_path):
        raise ValueError('Path for source : {} must be absolute'.format(source_path))
    if not os.path.isabs(target_path):
        raise ValueError('Path for link : {} must be absolute'.format(target_path))
    if source_path == target_path:
        raise ValueError('Path for link is identical to source : {}'.format(source_path))
    try:
        if os.path.lexists(target_path):
            if os.path.islink(target_path) or os.path.isfile(target_path):
                os.unlink(target_path)
            else:
                shutil.rmtree(target_path)
        safe_mkdir_for(target_path)
        os.symlink(source_path, target_path)
    except OSError as e:
        if not (e.errno == errno.EEXIST or e.errno == errno.ENOENT):
            raise

def relative_symlink(source_path, link_path):
    """Create a symlink at link_path pointing to relative source

    :param source_path: Absolute path to source file
    :param link_path: Absolute path to intended symlink
    :raises ValueError if source_path or link_path are not unique, absolute paths
    :raises OSError on failure UNLESS file already exists or no such file/directory"""
    if not os.path.isabs(source_path):
        raise ValueError('Path for source:{} must be absolute'.format(source_path))
    if not os.path.isabs(link_path):
        raise ValueError('Path for link:{} must be absolute'.format(link_path))
    if source_path == link_path:
        raise ValueError('Path for link is identical to source:{}'.format(source_path))
    if os.path.isdir(link_path) and (not os.path.islink(link_path)):
        raise ValueError('Path for link would overwrite an existing directory: {}'.format(link_path))
    try:
        if os.path.lexists(link_path):
            os.unlink(link_path)
        rel_path = os.path.relpath(source_path, os.path.dirname(link_path))
        safe_mkdir_for(link_path)
        os.symlink(rel_path, link_path)
    except OSError as e:
        if not (e.errno == errno.EEXIST or e.errno == errno.ENOENT):
            raise

def rm_rf(name):
    """Remove a file or a directory similarly to running `rm -rf <name>` in a UNIX shell.

    :param str name: the name of the file or directory to remove.
    :raises: OSError on error."""
    if not os.path.exists(name):
        return
    try:
        shutil.rmtree(name)
    except OSError as e:
        if e.errno == errno.ENOTDIR:
            safe_delete(name)
        elif e.errno != errno.ENOENT:
            raise

def is_executable(path):
    """Returns whether a path names an existing executable file."""
    return os.path.isfile(path) and os.access(path, os.X_OK)

def check_no_overlapping_paths(paths):
    """Given a list of paths, ensure that all are unique and do not have the same prefix."""
    for path in paths:
        list_copy_without_path = list(paths)
        list_copy_without_path.remove(path)
        if path in list_copy_without_path:
            raise ValueError('{} appeared more than once. All paths must be unique.'.format(path))
        for p in list_copy_without_path:
            if path in p:
                raise ValueError('{} and {} have the same prefix. All paths must be unique and cannot overlap.'.format(path, p))

def is_readable_dir(path):
    """Returns whether a path names an existing directory we can list and read files from."""
    return os.path.isdir(path) and os.access(path, os.R_OK) and os.access(path, os.X_OK)

def generate_travis_yml():
    """Generates content for a .travis.yml file from templates."""
    def get_mustache_file(file_name):
        return pkg_resources.resource_string(__name__, file_name).decode('utf-8')
    template = get_mustache_file('travis.yml.mustache')
    before_install_linux = get_mustache_file('before_install_linux.mustache')
    before_install_osx = get_mustache_file('before_install_osx.mustache')
    env_osx_with_pyenv = get_mustache_file('env_osx_with_pyenv.mustache')
    docker_build_image = get_mustache_file('docker_build_image.mustache')
    docker_run_image = get_mustache_file('docker_run_image.mustache')
    context = {'header': HEADER, 'integration_shards': range(0, num_integration_shards), 'integration_shards_length': num_integration_shards}
    renderer = pystache.Renderer(partials={'before_install_linux': before_install_linux, 'before_install_osx': before_install_osx, 'env_osx_with_pyenv': env_osx_with_pyenv, 'docker_build_image': docker_build_image, 'docker_run_image': docker_run_image})
    print(renderer.render(template, context))

def command_gen(tool_installations, tool_executable, args=None, node_paths=None):
    """Generate a Command object with required tools installed and paths set up.

    :param list tool_installations: A list of functions to install required tools.  Those functions
      should take no parameter and return an installation path to be included in the runtime path.
    :param tool_executable: Name of the tool to be executed.
    :param list args: A list of arguments to be passed to the executable
    :param list node_paths: A list of path to node_modules.  node_modules/.bin will be appended
      to the run time path.
    :rtype: class: `Command`"""
    node_module_bin_dir = 'node_modules/.bin'
    extra_paths = []
    for t in tool_installations:
        extra_paths.append(t())
    if node_paths:
        for node_path in node_paths:
            if not node_path.endswith(node_module_bin_dir):
                node_path = os.path.join(node_path, node_module_bin_dir)
            extra_paths.append(node_path)
    return Command(executable=tool_executable, args=args, extra_paths=extra_paths)

def _spec_to_globs(address_mapper, specs):
    """Given a Specs object, return a PathGlobs object for the build files that it matches."""
    patterns = set()
    for spec in specs:
        patterns.update(spec.make_glob_patterns(address_mapper))
    return PathGlobs(include=patterns, exclude=address_mapper.build_ignore_patterns)

def create_graph_rules(address_mapper):
    """Creates tasks used to parse Structs from BUILD files.

    :param address_mapper_key: The subject key for an AddressMapper instance.
    :param symbol_table: A SymbolTable instance to provide symbols for Address lookups."""
    @rule(AddressMapper, [])
    def address_mapper_singleton():
        return address_mapper
    return [address_mapper_singleton, hydrate_struct, parse_address_family, addresses_from_address_families, RootRule(Address), RootRule(BuildFileAddress), RootRule(BuildFileAddresses), RootRule(Specs)]

def retry_on_exception(func, max_retries, exception_types, backoff_func=lambda n: 0):
    """Retry a callable against a set of exceptions, optionally sleeping between retries.

    :param callable func: The callable to retry.
    :param int max_retries: The maximum number of times to attempt running the function.
    :param tuple exception_types: The types of exceptions to catch for retry.
    :param callable backoff_func: A callable that will be called with the current attempt count to
                                  determine the amount of time to sleep between retries. E.g. a
                                  max_retries=4 with a backoff_func=lambda n: n * n will result in
                                  sleeps of [1, 4, 9] between retries. Defaults to no backoff."""
    for i in range(0, max_retries):
        if i:
            time.sleep(backoff_func(i))
        try:
            return func()
        except exception_types as e:
            logger.debug('encountered exception on retry #{}: {!r}'.format(i, e))
            if i == max_retries - 1:
                raise

def create_size_estimators():
    """Create a dict of name to a function that returns an estimated size for a given target.

    The estimated size is used to build the largest targets first (subject to dependency constraints).
    Choose 'random' to choose random sizes for each target, which may be useful for distributed
    builds.
    :returns: Dict of a name to a function that returns an estimated size."""
    def line_count(filename):
        with open(filename, 'rb') as fh:
            return sum((1 for line in fh))
    return {'linecount': lambda srcs: sum((line_count(src) for src in srcs)), 'filecount': lambda srcs: len(srcs), 'filesize': lambda srcs: sum((os.path.getsize(src) for src in srcs)), 'nosize': lambda srcs: 0, 'random': lambda srcs: random.randint(0, 10000)}

def fallible_to_exec_result_or_raise(fallible_result, request):
    """Converts a FallibleExecuteProcessResult to a ExecuteProcessResult or raises an error."""
    if fallible_result.exit_code == 0:
        return ExecuteProcessResult(fallible_result.stdout, fallible_result.stderr, fallible_result.output_directory_digest)
    else:
        raise ProcessExecutionFailure(fallible_result.exit_code, fallible_result.stdout, fallible_result.stderr, request.description)

def _extract_variants(address, variants_str):
    """Return the variants (if any) represented by the given variants_str.

    :returns: The variants or else `None` if there are none.
    :rtype: tuple of tuples (key, value) strings"""
    def entries():
        for entry in variants_str.split(','):
            key, _, value = entry.partition('=')
            if not key or not value:
                raise ValueError('Invalid variants after the @ in: {}'.format(address))
            yield (key, value)
    return tuple(entries())

def hash_all(strs, digest=None):
    """Returns a hash of the concatenation of all the strings in strs.

    If a hashlib message digest is not supplied a new sha1 message digest is used."""
    digest = digest or hashlib.sha1()
    for s in strs:
        s = ensure_binary(s)
        digest.update(s)
    return digest.hexdigest() if PY3 else digest.hexdigest().decode('utf-8')

def hash_file(path, digest=None):
    """Hashes the contents of the file at the given path and returns the hash digest in hex form.

    If a hashlib message digest is not supplied a new sha1 message digest is used."""
    digest = digest or hashlib.sha1()
    with open(path, 'rb') as fd:
        s = fd.read(8192)
        while s:
            digest.update(s)
            s = fd.read(8192)
    return digest.hexdigest() if PY3 else digest.hexdigest().decode('utf-8')

def get_pants_cachedir():
    """Return the pants global cache directory."""
    cache_home = os.environ.get('XDG_CACHE_HOME')
    if not cache_home:
        cache_home = '~/.cache'
    return os.path.expanduser(os.path.join(cache_home, 'pants'))

def get_pants_configdir():
    """Return the pants global config directory."""
    config_home = os.environ.get('XDG_CONFIG_HOME')
    if not config_home:
        config_home = '~/.config'
    return os.path.expanduser(os.path.join(config_home, 'pants'))

def get_scm():
    """Returns the pants Scm if any.

    :API: public"""
    global _SCM
    if not _SCM:
        from pants.scm.git import Git
        worktree = Git.detect_worktree()
        if worktree and os.path.isdir(worktree):
            git = Git(worktree=worktree)
            try:
                logger.debug('Detected git repository at {} on branch {}'.format(worktree, git.branch_name))
                set_scm(git)
            except git.LocalException as e:
                logger.info('Failed to load git repository at {}: {}'.format(worktree, e))
    return _SCM

def set_scm(scm):
    """Sets the pants Scm."""
    if scm is not None:
        if not isinstance(scm, Scm):
            raise ValueError('The scm must be an instance of Scm, given {}'.format(scm))
        global _SCM
        _SCM = scm

def all_enclosing_scopes(scope, allow_global=True):
    """Utility function to return all scopes up to the global scope enclosing a
    given scope."""
    _validate_full_scope(scope)
    def scope_within_range(tentative_scope):
        if tentative_scope is None:
            return False
        if not allow_global and tentative_scope == GLOBAL_SCOPE:
            return False
        return True
    while scope_within_range(scope):
        yield scope
        scope = None if scope == GLOBAL_SCOPE else enclosing_scope(scope)

def _get_starting_indent(source):
    """Remove leading indentation from `source` so ast.parse() doesn't raise an exception."""
    if source.startswith(' '):
        return sum((1 for _ in itertools.takewhile(lambda c: c in {' ', b' '}, source)))
    return 0

def expand_path(path):
    """Returns ``path`` as an absolute path with ~user and env var expansion applied.

    :API: public"""
    return os.path.abspath(os.path.expandvars(os.path.expanduser(path)))

def call_insert(tup):
    """Importable helper for multi-proc calling of ArtifactCache.insert on an ArtifactCache instance.

    See docstring on call_use_cached_files explaining why this is useful.

    :param tup: A 4-tuple of an ArtifactCache and the 3 args passed to ArtifactCache.insert:
                eg (some_cache_instance, cache_key, [some_file, another_file], False)"""
    try:
        cache, key, files, overwrite = tup
        return cache.insert(key, files, overwrite)
    except NonfatalArtifactCacheError as e:
        logger.warn('Error while inserting into artifact cache: {0}'.format(e))
        return False

def wrap_filters(filters):
    """Returns a single filter that short-circuit ANDs the specified filters.

    :API: public"""
    def combined_filter(x):
        for filt in filters:
            if not filt(x):
                return False
        return True
    return combined_filter

def _convert(val, acceptable_types):
    """Ensure that val is one of the acceptable types, converting it if needed.

    :param val: The value we're parsing (either a string or one of the acceptable types).
    :param acceptable_types: A tuple of expected types for val.
    :returns: The parsed value.
    :raises :class:`pants.options.errors.ParseError`: if there was a problem parsing the val as an
                                                      acceptable type."""
    if isinstance(val, acceptable_types):
        return val
    return parse_expression(val, acceptable_types, raise_type=ParseError)

def normalize_os_name(os_name):
    """:API: public"""
    if os_name not in OS_ALIASES:
        for proper_name, aliases in OS_ALIASES.items():
            if os_name in aliases:
                return proper_name
        logger.warning('Unknown operating system name: {bad}, known names are: {known}'.format(bad=os_name, known=', '.join(sorted(known_os_names()))))
    return os_name

def safe_kill(pid, signum):
    """Kill a process with the specified signal, catching nonfatal errors."""
    assert isinstance(pid, IntegerForPid)
    assert isinstance(signum, int)
    try:
        os.kill(pid, signum)
    except (IOError, OSError) as e:
        if e.errno in [errno.ESRCH, errno.EPERM]:
            pass
        elif e.errno == errno.EINVAL:
            raise ValueError('Invalid signal number {}: {}'.format(signum, e), e)
        else:
            raise

def get_closest_mac_host_platform_pair(darwin_version_upper_bound, platform_name_map=SUPPORTED_PLATFORM_NORMALIZED_NAMES):
    """Return the (host, platform) pair for the highest known darwin version less than the bound."""
    darwin_versions = [int(x[1]) for x in platform_name_map if x[0] == 'darwin']
    bounded_darwin_versions = [v for v in darwin_versions if v <= int(darwin_version_upper_bound)]
    if not bounded_darwin_versions:
        return (None, None)
    max_darwin_version = str(max(bounded_darwin_versions))
    return platform_name_map['darwin', max_darwin_version]

def _normalize_utf8_keys(kwargs):
    """When kwargs are passed literally in a source file, their keys are ascii: normalize."""
    if any((type(key) is binary_type for key in kwargs.keys())):
        dict_type = type(kwargs)
        return dict_type([(text_type(k), v) for k, v in kwargs.items()])
    return kwargs

def compile_function(node, globals_=None):
    """Convert an AST or string into a function with inspectable source.

    This function uses `compile_file` internally, but instead of returning the
    entire module it will return the function only.

    Args:
      node: A `FunctionDef` node or a `Module` node which contains at least one
          `FunctionDef` node. If a module contains multiple functions, a handle
          to the first one will be returned.
      globals_: See `compile_file`

    Returns:
      A handle to the compiled function.

    Raises:
      TypeError: If the input is not a string or AST.
      ValueError: If no function can be found."""
    if not isinstance(node, gast.AST):
        if not isinstance(node, six.string_types):
            raise TypeError
        node = gast.parse(node)
    if isinstance(node, gast.Module):
        for succ in node.body:
            if isinstance(succ, gast.FunctionDef):
                name = succ.name
                break
        else:
            raise ValueError('no function found')
    elif isinstance(node, gast.FunctionDef):
        name = node.name
    else:
        raise TypeError
    module = compile_file(node, globals_)
    return getattr(module, name)

def vjp(func, wrt=(0,), optimized=True, check_dims=True, preserve_result=False, verbose=0):
    """Convenience function to produce vector-Jacobian products.

    See `autodiff` for function arguments.
    Uses reverse-mode joint-motion autodiff to produce the VJP."""
    return autodiff(func, wrt=wrt, motion='joint', mode='reverse', optimized=optimized, preserve_result=preserve_result, input_derivative=INPUT_DERIVATIVE.Required, check_dims=check_dims, verbose=verbose)

def forward(node, analysis):
    """Perform a given analysis on all functions within an AST."""
    if not isinstance(analysis, Forward):
        raise TypeError('not a valid forward analysis object')
    for succ in gast.walk(node):
        if isinstance(succ, gast.FunctionDef):
            cfg_obj = CFG.build_cfg(succ)
            analysis.visit(cfg_obj.entry)
    return node

def unreduce_tensor(tensor, shape, axis, keepdims):
    """Reverse summing over a dimension.

    See utils.py.

    Args:
      tensor: The tensor that was reduced.
      shape: A list, the original shape of the tensor before reduction.
      axis: The axis or axes that were summed.
      keepdims: Whether these axes were kept as singleton axes.

    Returns:
      A tensor with axes broadcast to match the shape of the original tensor."""
    if not keepdims:
        if axis is None:
            axis = range(len(shape))
        elif isinstance(axis, int):
            axis = (axis,)
        for ax in sorted(axis):
            tensor = tf.expand_dims(tensor, ax)
    tile_shape = np.array(shape) / np.array(shape_as_list(tensor))
    return tf.tile(tensor, tile_shape)

def matmul_adjoint_x(dz, x, y, transpose_a, transpose_b):
    """Implementation of dtfmatmul wrt x, separate for readability."""
    if not transpose_a and (not transpose_b):
        return tf.matmul(dz, y, transpose_b=True)
    elif not transpose_a and transpose_b:
        return tf.matmul(dz, y)
    elif transpose_a and (not transpose_b):
        return tf.matmul(y, dz, transpose_b=True)
    else:
        return tf.matmul(y, dz, transpose_a=True, transpose_b=True)

def matmul_adjoint_y(dz, x, y, transpose_a, transpose_b):
    """Implementation of dtfmatmul, separate for readability."""
    if not transpose_a and (not transpose_b):
        return tf.matmul(x, dz, transpose_a=True)
    elif not transpose_a and transpose_b:
        return tf.matmul(dz, x, transpose_a=True)
    elif transpose_a and (not transpose_b):
        return tf.matmul(x, dz)
    else:
        return tf.matmul(dz, x, transpose_a=True, transpose_b=True)

def primal_name(func, wrt):
    """Name for the primal of a function."""
    if not isinstance(func, types.FunctionType):
        raise TypeError(func)
    varnames = six.get_function_code(func).co_varnames
    return PRIMAL_NAME.format(func.__name__, ''.join((varnames[i] for i in wrt)))

def uniqify(func):
    """Make sure that a method returns a unique name."""
    @six.wraps(func)
    def unique(self, *args, **kwargs):
        return self.unique(func(self, *args, **kwargs))
    return unique

def uniqify_once(func):
    """Make sure that a method returns a unique name."""
    @six.wraps(func)
    def unique_once(self, *args, **kwargs):
        return self.unique_once(func(self, *args, **kwargs))
    return unique_once

def array_size(x, axis):
    """Calculate the size of `x` along `axis` dimensions only."""
    axis_shape = x.shape if axis is None else tuple((x.shape[a] for a in axis))
    return max(numpy.prod(axis_shape), 1)

def unreduce_array(array, shape, axis, keepdims):
    """Reverse summing over a dimension, NumPy implementation.

    Args:
      array: The array that was reduced.
      shape: The original shape of the array before reduction.
      axis: The axis or axes that were summed.
      keepdims: Whether these axes were kept as singleton axes.

    Returns:
      An array with axes broadcast to match the shape of the original array."""
    if axis is not None and (not keepdims or keepdims is numpy._NoValue):
        if isinstance(axis, int):
            axis = (axis,)
        for ax in sorted(axis):
            array = numpy.expand_dims(array, ax)
    return numpy.broadcast_to(array, shape)

def astype(array, y):
    """A functional form of the `astype` method.

    Args:
      array: The array or number to cast.
      y: An array or number, as the input, whose type should be that of array.

    Returns:
      An array or number with the same dtype as `y`."""
    if isinstance(y, autograd.core.Node):
        return array.astype(numpy.array(y.value).dtype)
    return array.astype(numpy.array(y).dtype)

def init_grad(obj, allow_lazy_initializer=False):
    """Initialize the gradient for an object.

    Args:
      obj: The object to initialize the gradient for, can be either a number,
        array, tuple, list, or dictionary.
      allow_lazy_initializer: Whether to allow using the ZeroGradient wrapper,
        for efficiency.

    Returns:
      An object of the same type, shape, etc. but with all numeric values set to
      zero. If the type is unknown, a zero is returned."""
    if obj is None:
        return 0.0
    initializer, supports_lazy_initializer = grad_initializers[type(obj)]
    if supports_lazy_initializer:
        if isinstance(obj, ZeroGradient):
            if allow_lazy_initializer:
                return ZeroGradient(obj.like)
            else:
                return obj.instantiate()
        elif allow_lazy_initializer:
            return ZeroGradient(obj)
    else:
        assert not isinstance(obj, ZeroGradient)
    return initializer(obj)

def shapes_match(a, b):
    """Recursively check if shapes of object `a` and `b` match.

    Will walk lists, tuples and dicts.

    Args:
      a: object of type (numpy.ndarray,tf.Tensor,list,tuple,dict)
          to check for matching shapes against `b`.
      b: object to check for matching shape against `a`.

    Returns:
      A boolean indicating whether the shapes of `a` and `b` match."""
    if isinstance(a, (tuple, list)) and isinstance(b, (tuple, list)):
        if len(a) != len(b):
            return False
        return all([shapes_match(ia, ib) for ia, ib in zip(a, b)])
    elif isinstance(a, dict) and isinstance(b, dict):
        if len(a) != len(b):
            return False
        match = True
        for (ak, av), (bk, bv) in zip(a.items(), b.items()):
            match = match and all([ak == bk and shapes_match(av, bv)])
        return match
    else:
        shape_checker = shape_checkers[type(a), type(b)]
        return shape_checker(a, b)

def push(stack, x, op_id):
    """Push a value onto the stack (i.e. record it on the tape).

    Args:
      stack: The stack object, which must support appending values.
      x: The value to append. If it is a mutable object like an array or list, it
          will be copied before being added onto the stack.
      op_id: A unique variable that is also passed into the corresponding pop.
          Allows optimization passes to track pairs of pushes and pops."""
    if isinstance(x, numpy.ndarray):
        x = x.copy()
    elif isinstance(x, list):
        x = x[:]
    if __debug__:
        stack.append((x, op_id))
    else:
        stack.append(x)

def trace_grad(fn, args):
    """Trace a function, and return a VJP and the function's output."""
    from tensorflow.python.eager.backprop import make_vjp
    result, vjp = make_vjp(fn)(*args)
    return (result, vjp)

def get_name(node):
    """Get the name of a variable.

    Args:
      node: A `Name`, `Subscript` or `Attribute` node.

    Returns:
      The name of the variable e.g. `'x'` for `x`, `x.i` and `x[i]`."""
    if isinstance(node, gast.Name):
        return node.id
    elif isinstance(node, (gast.Subscript, gast.Attribute)):
        return get_name(node.value)
    else:
        raise TypeError

def get_updated(node):
    """Return the variable names created or mutated by this statement.

    This function considers assign statements, augmented assign statements, and
    the targets of for loops, as well as function arguments.

    For example, `x[0] = 2` will return `x`, `x, y = 3, 4` will return `x` and
    `y`, `for i in range(x)` will return `i`, etc.

    Args:
      node: An AST node

    Returns:
      A set of variable names (strings) of all the variables created or mutated."""
    if isinstance(node, gast.Assign):
        return set.union(*(_get_target(target) for target in node.targets))
    elif isinstance(node, (gast.For, gast.AugAssign)):
        return _get_target(node.target)
    elif isinstance(node, gast.arguments):
        targets = set((arg.id for arg in node.args + node.kwonlyargs))
        if node.vararg:
            targets.add(node.vararg.id)
        if node.kwarg:
            targets.add(node.kwarg.id)
        return targets
    else:
        return set()

def to_source(node, indentation=' ' * 4):
    """Return source code of a given AST."""
    if isinstance(node, gast.AST):
        node = gast.gast_to_ast(node)
    generator = SourceWithCommentGenerator(indentation, False, astor.string_repr.pretty_string)
    generator.visit(node)
    generator.result.append('\n')
    return astor.source_repr.pretty_source(generator.result).lstrip()

def parse_function(fn):
    """Get the source of a function and return its AST."""
    try:
        return parse_string(inspect.getsource(fn))
    except (IOError, OSError) as e:
        raise ValueError('Cannot differentiate function: %s. Tangent must be able to access the source code of the function. Functions defined in a Python interpreter and functions backed by C extension modules do not have accessible source code.' % e)

def get_tesseract_version():
    """Try to extract version from tesseract otherwise default min version."""
    config = {'libraries': ['tesseract', 'lept']}
    try:
        p = subprocess.Popen(['tesseract', '-v'], stderr=subprocess.PIPE, stdout=subprocess.PIPE)
        stdout_version, version = p.communicate()
        version = _read_string(version).strip()
        if version == '':
            version = _read_string(stdout_version).strip()
        version_match = re.search('^tesseract ((?:\\d+\\.)+\\d+).*', version, re.M)
        if version_match:
            version = version_match.group(1)
        else:
            _LOGGER.warn('Failed to extract tesseract version number from: {}'.format(version))
            version = _TESSERACT_MIN_VERSION
    except OSError as e:
        _LOGGER.warn('Failed to extract tesseract version from executable: {}'.format(e))
        version = _TESSERACT_MIN_VERSION
    _LOGGER.info('Supporting tesseract v{}'.format(version))
    version = version_to_int(version)
    config['cython_compile_time_env'] = {'TESSERACT_VERSION': version}
    _LOGGER.info('Building with configs: {}'.format(config))
    return config

def get_build_args():
    """Return proper build parameters."""
    try:
        build_args = package_config()
    except Exception as e:
        if isinstance(e, OSError):
            if e.errno != errno.ENOENT:
                _LOGGER.warn('Failed to run pkg-config: {}'.format(e))
        else:
            _LOGGER.warn('pkg-config failed to find tesseract/lept libraries: {}'.format(e))
        build_args = get_tesseract_version()
    if build_args['cython_compile_time_env']['TESSERACT_VERSION'] >= 50659840:
        _LOGGER.debug('tesseract >= 03.05.02 requires c++11 compiler support')
        build_args['extra_compile_args'] = ['-std=c++11', '-DUSE_STD_NAMESPACE']
    _LOGGER.debug('build parameters: {}'.format(build_args))
    return build_args

def on_loop(notifier, counter):
    """Dummy function called after each event loop, this method only
    ensures the child process eventually exits (after 5 iterations)."""
    if counter.count > 4:
        sys.stdout.write('Exit\n')
        notifier.stop()
        sys.exit(0)
    else:
        sys.stdout.write('Loop %d\n' % counter.count)
        counter.plusone()

def time2isoz(t=None):
    """Return a string representing time in seconds since epoch, t.

    If the function is called without an argument, it will use the current
    time.

    The format of the returned string is like "YYYY-MM-DD hh:mm:ssZ",
    representing Universal Time (UTC, aka GMT).  An example of this format is:

    1994-11-24 08:49:37Z"""
    if t is None:
        dt = datetime.datetime.utcnow()
    else:
        dt = datetime.datetime.utcfromtimestamp(t)
    return '%04d-%02d-%02d %02d:%02d:%02dZ' % (dt.year, dt.month, dt.day, dt.hour, dt.minute, dt.second)

def time2netscape(t=None):
    """Return a string representing time in seconds since epoch, t.

    If the function is called without an argument, it will use the current
    time.

    The format of the returned string is like this:

    Wed, DD-Mon-YYYY HH:MM:SS GMT"""
    if t is None:
        dt = datetime.datetime.utcnow()
    else:
        dt = datetime.datetime.utcfromtimestamp(t)
    return '%s %02d-%s-%04d %02d:%02d:%02d GMT' % (DAYS[dt.weekday()], dt.day, MONTHS[dt.month - 1], dt.year, dt.hour, dt.minute, dt.second)

def join_header_words(lists):
    """Do the inverse (almost) of the conversion done by split_header_words.

    Takes a list of lists of (key, value) pairs and produces a single header
    value.  Attribute values are quoted if needed.

    >>> join_header_words([[("text/plain", None), ("charset", "iso-8859/1")]])
    'text/plain; charset="iso-8859/1"'
    >>> join_header_words([[("text/plain", None)], [("charset", "iso-8859/1")]])
    'text/plain, charset="iso-8859/1"'"""
    headers = []
    for pairs in lists:
        attr = []
        for k, v in pairs:
            if v is not None:
                if not re.search('^\\w+$', v):
                    v = HEADER_JOIN_ESCAPE_RE.sub('\\\\\\1', v)
                    v = '"%s"' % v
                k = '%s=%s' % (k, v)
            attr.append(k)
        if attr:
            headers.append('; '.join(attr))
    return ', '.join(headers)

def request_host(request):
    """Return request-host, as defined by RFC 2965.

    Variation from RFC: returned value is lowercased, for convenient
    comparison."""
    url = request.get_full_url()
    host = urlparse(url)[1]
    if host == '':
        host = request.get_header('Host', '')
    host = cut_port_re.sub('', host, 1)
    return host.lower()

def eff_request_host(request):
    """Return a tuple (request-host, effective request-host name).

    As defined by RFC 2965, except both are lowercased."""
    erhn = req_host = request_host(request)
    if req_host.find('.') == -1 and (not IPV4_RE.search(req_host)):
        erhn = req_host + '.local'
    return (req_host, erhn)

def deepvalues(mapping):
    """Iterates over nested mapping, depth-first, in sorted order by key."""
    values = vals_sorted_by_key(mapping)
    for obj in values:
        mapping = False
        try:
            obj.items
        except AttributeError:
            pass
        else:
            mapping = True
            for subobj in deepvalues(obj):
                yield subobj
        if not mapping:
            yield obj

def lwp_cookie_str(cookie):
    """Return string representation of Cookie in an the LWP cookie file format.

    Actually, the format is extended a bit -- see module docstring."""
    h = [(cookie.name, cookie.value), ('path', cookie.path), ('domain', cookie.domain)]
    if cookie.port is not None:
        h.append(('port', cookie.port))
    if cookie.path_specified:
        h.append(('path_spec', None))
    if cookie.port_specified:
        h.append(('port_spec', None))
    if cookie.domain_initial_dot:
        h.append(('domain_dot', None))
    if cookie.secure:
        h.append(('secure', None))
    if cookie.expires:
        h.append(('expires', time2isoz(float(cookie.expires))))
    if cookie.discard:
        h.append(('discard', None))
    if cookie.comment:
        h.append(('comment', cookie.comment))
    if cookie.comment_url:
        h.append(('commenturl', cookie.comment_url))
    keys = sorted(cookie._rest.keys())
    for k in keys:
        h.append((k, str(cookie._rest[k])))
    h.append(('version', str(cookie.version)))
    return join_header_words([h])

def _url_collapse_path(path):
    """Given a URL path, remove extra '/'s and '.' path elements and collapse
    any '..' references and returns a colllapsed path.

    Implements something akin to RFC-2396 5.2 step 6 to parse relative paths.
    The utility of this function is limited to is_cgi method and helps
    preventing some security attacks.

    Returns: A tuple of (head, tail) where tail is everything after the final /
    and head is everything before it.  Head will always start with a '/' and,
    if it contains anything else, never have a trailing '/'.

    Raises: IndexError if too many '..' occur within the path."""
    path_parts = path.split('/')
    head_parts = []
    for part in path_parts[:-1]:
        if part == '..':
            head_parts.pop()
        elif part and part != '.':
            head_parts.append(part)
    if path_parts:
        tail_part = path_parts.pop()
        if tail_part:
            if tail_part == '..':
                head_parts.pop()
                tail_part = ''
            elif tail_part == '.':
                tail_part = ''
    else:
        tail_part = ''
    splitpath = ('/' + '/'.join(head_parts), tail_part)
    collapsed_path = '/'.join(splitpath)
    return collapsed_path

def build_opener(*handlers):
    """Create an opener object from a list of handlers.

    The opener will use several default handlers, including support
    for HTTP, FTP and when applicable HTTPS.

    If any of the handlers passed as arguments are subclasses of the
    default handlers, the default handlers will not be used."""
    def isclass(obj):
        return isinstance(obj, type) or hasattr(obj, '__bases__')
    opener = OpenerDirector()
    default_classes = [ProxyHandler, UnknownHandler, HTTPHandler, HTTPDefaultErrorHandler, HTTPRedirectHandler, FTPHandler, FileHandler, HTTPErrorProcessor]
    if hasattr(http_client, 'HTTPSConnection'):
        default_classes.append(HTTPSHandler)
    skip = set()
    for klass in default_classes:
        for check in handlers:
            if isclass(check):
                if issubclass(check, klass):
                    skip.add(klass)
            elif isinstance(check, klass):
                skip.add(klass)
    for klass in skip:
        default_classes.remove(klass)
    for klass in default_classes:
        opener.add_handler(klass())
    for h in handlers:
        if isclass(h):
            h = h()
        opener.add_handler(h)
    return opener

def getproxies_environment():
    """Return a dictionary of scheme -> proxy server URL mappings.

    Scan the environment for variables named <scheme>_proxy;
    this seems to be the standard convention.  If you need a
    different way, you can pass a proxies dictionary to the
    [Fancy]URLopener constructor."""
    proxies = {}
    for name, value in os.environ.items():
        name = name.lower()
        if value and name[-6:] == '_proxy':
            proxies[name[:-6]] = value
    return proxies

def proxy_bypass_environment(host):
    """Test if proxies should not be used for a particular host.

    Checks the environment for a variable named no_proxy, which should
    be a list of DNS suffixes separated by commas, or '*' for all hosts."""
    no_proxy = os.environ.get('no_proxy', '') or os.environ.get('NO_PROXY', '')
    if no_proxy == '*':
        return 1
    hostonly, port = splitport(host)
    no_proxy_list = [proxy.strip() for proxy in no_proxy.split(',')]
    for name in no_proxy_list:
        if name and (hostonly.endswith(name) or host.endswith(name)):
            return 1
    return 0

def match_division(node):
    u"""__future__.division redefines the meaning of a single slash for division,
    so we match that and only that."""
    slash = token.SLASH
    return node.type == slash and (not node.next_sibling.type == slash) and (not node.prev_sibling.type == slash)

def newround(number, ndigits=None):
    """See Python 3 documentation: uses Banker's Rounding.

    Delegates to the __round__ method if for some reason this exists.

    If not, rounds a number to a given precision in decimal digits (default
    0 digits). This returns an int when called with one argument,
    otherwise the same type as the number. ndigits may be negative.

    See the test_round method in future/tests/test_builtins.py for
    examples."""
    return_int = False
    if ndigits is None:
        return_int = True
        ndigits = 0
    if hasattr(number, '__round__'):
        return number.__round__(ndigits)
    if ndigits < 0:
        raise NotImplementedError('negative ndigits not supported yet')
    exponent = Decimal('10') ** (-ndigits)
    if PYPY:
        if 'numpy' in repr(type(number)):
            number = float(number)
    if not PY26:
        d = Decimal.from_float(number).quantize(exponent, rounding=ROUND_HALF_EVEN)
    else:
        d = from_float_26(number).quantize(exponent, rounding=ROUND_HALF_EVEN)
    if return_int:
        return int(d)
    else:
        return float(d)

def getfqdn(name=''):
    """Get fully qualified domain name from name.

    An empty argument is interpreted as meaning the local host.

    First the hostname returned by gethostbyaddr() is checked, then
    possibly existing aliases. In case no FQDN is available, hostname
    from gethostname() is returned."""
    name = name.strip()
    if not name or name == '0.0.0.0':
        name = gethostname()
    try:
        hostname, aliases, ipaddrs = gethostbyaddr(name)
    except error:
        pass
    else:
        aliases.insert(0, hostname)
        for name in aliases:
            if '.' in name:
                break
        else:
            name = hostname
    return name

def maybe_2to3(filename, modname=None):
    """Returns a python3 version of filename."""
    need_2to3 = False
    filename = os.path.abspath(filename)
    if any((filename.startswith(d) for d in DIRS)):
        need_2to3 = True
    elif modname is not None and any((modname.startswith(p) for p in PACKAGES)):
        need_2to3 = True
    if not need_2to3:
        return filename
    outfilename = '/_auto2to3_'.join(os.path.split(filename))
    if not os.path.exists(outfilename) or os.stat(filename).st_mtime > os.stat(outfilename).st_mtime:
        try:
            with open(filename) as file:
                contents = file.read()
            contents = rt.refactor_docstring(contents, filename)
            tree = rt.refactor_string(contents, filename)
        except Exception as err:
            raise ImportError("2to3 couldn't convert %r" % filename)
        outfile = open(outfilename, 'wb')
        outfile.write(str(tree).encode('utf8'))
        outfile.close()
    return outfilename

def walk(self):
    """Walk over the message tree, yielding each subpart.

    The walk is performed in depth-first order.  This method is a
    generator."""
    yield self
    if self.is_multipart():
        for subpart in self.get_payload():
            for subsubpart in subpart.walk():
                yield subsubpart

def body_line_iterator(msg, decode=False):
    """Iterate over the parts, returning string payloads line-by-line.

    Optional decode (default False) is passed through to .get_payload()."""
    for subpart in msg.walk():
        payload = subpart.get_payload(decode=decode)
        if isinstance(payload, str):
            for line in StringIO(payload):
                yield line

def remove_params(raw_params, kwargs_default=_kwargs_default_name):
    u"""Removes all keyword-only args from the params list and a bare star, if any.
    Does not add the kwargs dict if needed.
    Returns True if more action is needed, False if not
    (more action is needed if no kwargs dict exists)"""
    assert raw_params[0].type == token.STAR
    if raw_params[1].type == token.COMMA:
        raw_params[0].remove()
        raw_params[1].remove()
        kw_params = raw_params[2:]
    else:
        kw_params = raw_params[3:]
    for param in kw_params:
        if param.type != token.DOUBLESTAR:
            param.remove()
        else:
            return False
    else:
        return True

def needs_fixing(raw_params, kwargs_default=_kwargs_default_name):
    u"""Returns string with the name of the kwargs dict if the params after the first star need fixing
    Otherwise returns empty string"""
    found_kwargs = False
    needs_fix = False
    for t in raw_params[2:]:
        if t.type == token.COMMA:
            continue
        elif t.type == token.NAME and (not found_kwargs):
            needs_fix = True
        elif t.type == token.NAME and found_kwargs:
            return t.value if needs_fix else u''
        elif t.type == token.DOUBLESTAR:
            found_kwargs = True
    else:
        return kwargs_default if needs_fix else u''

def common_substring(s1, s2):
    """Returns the longest common substring to the two strings, starting from the
    left."""
    chunks = []
    path1 = splitall(s1)
    path2 = splitall(s2)
    for dir1, dir2 in zip(path1, path2):
        if dir1 != dir2:
            break
        chunks.append(dir1)
    return os.path.join(*chunks)

def detect_python2(source, pathname):
    """Returns a bool indicating whether we think the code is Py2"""
    RTs.setup_detect_python2()
    try:
        tree = RTs._rt_py2_detect.refactor_string(source, pathname)
    except ParseError as e:
        if e.msg != 'bad input' or e.value != '=':
            raise
        tree = RTs._rtp.refactor_string(source, pathname)
    if source != str(tree)[:-1]:
        logger.debug('Detected Python 2 code: {0}'.format(pathname))
        with open('/tmp/original_code.py', 'w') as f:
            f.write('### Original code (detected as py2): %s\n%s' % (pathname, source))
        with open('/tmp/py2_detection_code.py', 'w') as f:
            f.write('### Code after running py3 detection (from %s)\n%s' % (pathname, str(tree)[:-1]))
        return True
    else:
        logger.debug('Detected Python 3 code: {0}'.format(pathname))
        with open('/tmp/original_code.py', 'w') as f:
            f.write('### Original code (detected as py3): %s\n%s' % (pathname, source))
        try:
            os.remove('/tmp/futurize_code.py')
        except OSError:
            pass
        return False

def escape(s, quote=True):
    """Replace special characters "&", "<" and ">" to HTML-safe sequences.
    If the optional flag quote is true (the default), the quotation mark
    characters, both double quote (") and single quote (') characters are also
    translated."""
    assert not isinstance(s, bytes), 'Pass a unicode string'
    if quote:
        return s.translate(_escape_map_full)
    return s.translate(_escape_map)

def indentation(node):
    """Returns the indentation for this node
    Iff a node is in a suite, then it has indentation."""
    while node.parent is not None and node.parent.type != syms.suite:
        node = node.parent
    if node.parent is None:
        return u''
    if node.type == token.INDENT:
        return node.value
    elif node.prev_sibling is not None and node.prev_sibling.type == token.INDENT:
        return node.prev_sibling.value
    elif node.prev_sibling is None:
        return u''
    else:
        return node.prefix

def indentation_step(node):
    """Dirty little trick to get the difference between each indentation level
    Implemented by finding the shortest indentation string
    (technically, the "least" of all of the indentation strings, but
    tabs and spaces mixed won't get this far, so those are synonymous.)"""
    r = find_root(node)
    all_indents = set((i.value for i in r.pre_order() if i.type == token.INDENT))
    if not all_indents:
        return u'    '
    else:
        return min(all_indents)

def suitify(parent):
    """Turn the stuff after the first colon in parent's children
    into a suite, if it wasn't already"""
    for node in parent.children:
        if node.type == syms.suite:
            return
    for i, node in enumerate(parent.children):
        if node.type == token.COLON:
            break
    else:
        raise ValueError(u"No class suite and no ':'!")
    suite = Node(syms.suite, [Newline(), Leaf(token.INDENT, indentation(node) + indentation_step(node))])
    one_node = parent.children[i + 1]
    one_node.remove()
    one_node.prefix = u''
    suite.append_child(one_node)
    parent.append_child(suite)

def NameImport(package, as_name=None, prefix=None):
    """Accepts a package (Name node), name to import it as (string), and
    optional prefix and returns a node:
    import <package> [as <as_name>]"""
    if prefix is None:
        prefix = u''
    children = [Name(u'import', prefix=prefix), package]
    if as_name is not None:
        children.extend([Name(u'as', prefix=u' '), Name(as_name, prefix=u' ')])
    return Node(syms.import_name, children)

def import_binding_scope(node):
    """Generator yields all nodes for which a node (an import_stmt) has scope
    The purpose of this is for a call to _find() on each of them"""
    assert node.type in _import_stmts
    test = node.next_sibling
    while test.type == token.SEMI:
        nxt = test.next_sibling
        if nxt.type == token.NEWLINE:
            break
        else:
            yield nxt
        test = nxt.next_sibling
    parent = node.parent
    assert parent.type == syms.simple_stmt
    test = parent.next_sibling
    while test is not None:
        yield test
        test = test.next_sibling
    context = parent.parent
    if context.type in _compound_stmts:
        c = context
        while c.next_sibling is not None:
            yield c.next_sibling
            c = c.next_sibling
        context = context.parent
    p = context.parent
    if p is None:
        return
    while p.type in _compound_stmts:
        if context.type == syms.suite:
            yield context
        context = context.next_sibling
        if context is None:
            context = p.parent
            p = context.parent
            if p is None:
                break

def is_docstring(node):
    """Returns True if the node appears to be a docstring"""
    return node.type == syms.simple_stmt and len(node.children) > 0 and (node.children[0].type == token.STRING)

def future_import(feature, node):
    """This seems to work"""
    root = find_root(node)
    if does_tree_import(u'__future__', feature, node):
        return
    shebang_encoding_idx = None
    for idx, node in enumerate(root.children):
        if is_shebang_comment(node) or is_encoding_comment(node):
            shebang_encoding_idx = idx
        if is_docstring(node):
            continue
        names = check_future_import(node)
        if not names:
            break
        if feature in names:
            return
    import_ = FromImport(u'__future__', [Leaf(token.NAME, feature, prefix=' ')])
    if shebang_encoding_idx == 0 and idx == 0:
        import_.prefix = root.children[0].prefix
        root.children[0].prefix = u''
    children = [import_, Newline()]
    root.insert_child(idx, Node(syms.simple_stmt, children))

def future_import2(feature, node):
    """An alternative to future_import() which might not work ..."""
    root = find_root(node)
    if does_tree_import(u'__future__', feature, node):
        return
    insert_pos = 0
    for idx, node in enumerate(root.children):
        if node.type == syms.simple_stmt and node.children and (node.children[0].type == token.STRING):
            insert_pos = idx + 1
            break
    for thing_after in root.children[insert_pos:]:
        if thing_after.type == token.NEWLINE:
            insert_pos += 1
            continue
        prefix = thing_after.prefix
        thing_after.prefix = u''
        break
    else:
        prefix = u''
    import_ = FromImport(u'__future__', [Leaf(token.NAME, feature, prefix=u' ')])
    children = [import_, Newline()]
    root.insert_child(insert_pos, Node(syms.simple_stmt, children, prefix=prefix))

def parse_args(arglist, scheme):
    u"""Parse a list of arguments into a dict"""
    arglist = [i for i in arglist if i.type != token.COMMA]
    ret_mapping = dict([(k, None) for k in scheme])
    for i, arg in enumerate(arglist):
        if arg.type == syms.argument and arg.children[1].type == token.EQUAL:
            slot = arg.children[0].value
            ret_mapping[slot] = arg.children[2]
        else:
            slot = scheme[i]
            ret_mapping[slot] = arg
    return ret_mapping

def check_future_import(node):
    """If this is a future import, return set of symbols that are imported,
    else return None."""
    savenode = node
    if not (node.type == syms.simple_stmt and node.children):
        return set()
    node = node.children[0]
    if not (node.type == syms.import_from and hasattr(node.children[1], 'value') and (node.children[1].value == u'__future__')):
        return set()
    if node.children[3].type == token.LPAR:
        node = node.children[4]
    else:
        node = node.children[3]
    if node.type == syms.import_as_names:
        result = set()
        for n in node.children:
            if n.type == token.NAME:
                result.add(n.value)
            elif n.type == syms.import_as_name:
                n = n.children[0]
                assert n.type == token.NAME
                result.add(n.value)
        return result
    elif node.type == syms.import_as_name:
        node = node.children[0]
        assert node.type == token.NAME
        return set([node.value])
    elif node.type == token.NAME:
        return set([node.value])
    else:
        assert False, 'strange import: %s' % savenode

def newnext(iterator, default=_SENTINEL):
    """next(iterator[, default])

    Return the next item from the iterator. If default is given and the iterator
    is exhausted, it is returned instead of raising StopIteration."""
    try:
        try:
            return iterator.__next__()
        except AttributeError:
            try:
                return iterator.next()
            except AttributeError:
                raise TypeError("'{0}' object is not an iterator".format(iterator.__class__.__name__))
    except StopIteration as e:
        if default is _SENTINEL:
            raise e
        else:
            return default

