def _fetchAzureAccountKey(accountName):
    """Find the account key for a given Azure storage account.

    The account key is taken from the AZURE_ACCOUNT_KEY_<account> environment variable if it
    exists, then from plain AZURE_ACCOUNT_KEY, and then from looking in the file
    ~/.toilAzureCredentials. That file has format:

    [AzureStorageCredentials]
    accountName1=ACCOUNTKEY1==
    accountName2=ACCOUNTKEY2=="""
    try:
        return os.environ['AZURE_ACCOUNT_KEY_' + accountName]
    except KeyError:
        try:
            return os.environ['AZURE_ACCOUNT_KEY']
        except KeyError:
            configParser = RawConfigParser()
            configParser.read(os.path.expanduser(credential_file_path))
            try:
                return configParser.get('AzureStorageCredentials', accountName)
            except NoOptionError:
                raise RuntimeError("No account key found for '%s', please provide it in '%s'" % (accountName, credential_file_path))

def dockerPredicate(e):
    """Used to ensure Docker exceptions are retried if appropriate

    :param e: Exception
    :return: True if e retriable, else False"""
    if not isinstance(e, subprocess.CalledProcessError):
        return False
    if e.returncode == 125:
        return True

def dockerKill(container_name, client, gentleKill=False):
    """Immediately kills a container.  Equivalent to "docker kill":
    https://docs.docker.com/engine/reference/commandline/kill/
    :param container_name: Name of the container being killed.
    :param client: The docker API client object to call."""
    try:
        this_container = client.containers.get(container_name)
        while this_container.status == 'running':
            if gentleKill is False:
                client.containers.get(container_name).kill()
            else:
                client.containers.get(container_name).stop()
            this_container = client.containers.get(container_name)
    except NotFound:
        logger.debug('Attempted to stop container, but container != exist: ', container_name)
    except requests.exceptions.HTTPError as e:
        logger.debug('Attempted to stop container, but server gave an error: ', container_name)
        raise create_api_error_from_http_exception(e)

def containerIsRunning(container_name):
    """Checks whether the container is running or not.
    :param container_name: Name of the container being checked.
    :returns: True if status is 'running', False if status is anything else,
    and None if the container does not exist."""
    client = docker.from_env(version='auto')
    try:
        this_container = client.containers.get(container_name)
        if this_container.status == 'running':
            return True
        else:
            return False
    except NotFound:
        return None
    except requests.exceptions.HTTPError as e:
        logger.debug('Server error attempting to call container: ', container_name)
        raise create_api_error_from_http_exception(e)

def getContainerName(job):
    """Create a random string including the job name, and return it."""
    return '--'.join([str(job), base64.b64encode(os.urandom(9), b'-_').decode('utf-8')]).replace("'", '').replace('"', '').replace('_', '')

def _resolve_indirect_inner(maybe_idict):
    """Resolve the contents an indirect dictionary (containing promises) to produce
    a dictionary actual values, including merging multiple sources into a
    single input."""
    if isinstance(maybe_idict, IndirectDict):
        result = {}
        for key, value in list(maybe_idict.items()):
            if isinstance(value, (MergeInputs, DefaultWithSource)):
                result[key] = value.resolve()
            else:
                result[key] = value[1].get(value[0])
        return result
    return maybe_idict

def resolve_indirect(pdict):
    """Resolve the contents an indirect dictionary (containing promises) and
    evaluate expressions to produce the dictionary of actual values."""
    inner = IndirectDict() if isinstance(pdict, IndirectDict) else {}
    needs_eval = False
    for k, value in iteritems(pdict):
        if isinstance(value, StepValueFrom):
            inner[k] = value.inner
            needs_eval = True
        else:
            inner[k] = value
    res = _resolve_indirect_inner(inner)
    if needs_eval:
        ev = {}
        for k, value in iteritems(pdict):
            if isinstance(value, StepValueFrom):
                ev[k] = value.do_eval(res, res[k])
            else:
                ev[k] = res[k]
        return ev
    return res

def simplify_list(maybe_list):
    """Turn a length one list loaded by cwltool into a scalar.
    Anything else is passed as-is, by reference."""
    if isinstance(maybe_list, MutableSequence):
        is_list = aslist(maybe_list)
        if len(is_list) == 1:
            return is_list[0]
    return maybe_list

def toil_make_tool(toolpath_object, loading_context):
    """Factory function passed to load_tool() which creates instances of the
    custom ToilCommandLineTool."""
    if isinstance(toolpath_object, Mapping) and toolpath_object.get('class') == 'CommandLineTool':
        return ToilCommandLineTool(toolpath_object, loading_context)
    return cwltool.workflow.default_make_tool(toolpath_object, loading_context)

def toil_get_file(file_store, index, existing, file_store_id):
    """Get path to input file from Toil jobstore."""
    if not file_store_id.startswith('toilfs:'):
        return file_store.jobStore.getPublicUrl(file_store.jobStore.importFile(file_store_id))
    src_path = file_store.readGlobalFile(file_store_id[7:])
    index[src_path] = file_store_id
    existing[file_store_id] = src_path
    return schema_salad.ref_resolver.file_uri(src_path)

def write_file(writeFunc, index, existing, x):
    """Write a file into the Toil jobstore.

    'existing' is a set of files retrieved as inputs from toil_get_file. This
    ensures they are mapped back as the same name if passed through."""
    if x.startswith('toilfs:'):
        return x
    elif x.startswith('_:'):
        return x
    else:
        x = existing.get(x, x)
        if x not in index:
            if not urlparse.urlparse(x).scheme:
                rp = os.path.realpath(x)
            else:
                rp = x
            try:
                index[x] = 'toilfs:' + writeFunc(rp)
                existing[index[x]] = x
            except Exception as e:
                cwllogger.error("Got exception '%s' while copying '%s'", e, x)
                raise
        return index[x]

def uploadFile(uploadfunc, fileindex, existing, uf, skip_broken=False):
    """Update a file object so that the location is a reference to the toil file
    store, writing it to the file store if necessary."""
    if uf['location'].startswith('toilfs:') or uf['location'].startswith('_:'):
        return
    if uf['location'] in fileindex:
        uf['location'] = fileindex[uf['location']]
        return
    if not uf['location'] and uf['path']:
        uf['location'] = schema_salad.ref_resolver.file_uri(uf['path'])
    if uf['location'].startswith('file://') and (not os.path.isfile(uf['location'][7:])):
        if skip_broken:
            return
        else:
            raise cwltool.errors.WorkflowException('File is missing: %s' % uf['location'])
    uf['location'] = write_file(uploadfunc, fileindex, existing, uf['location'])

def makeJob(tool, jobobj, step_inputs, runtime_context):
    """Create the correct Toil Job object for the CWL tool (workflow, job, or job
    wrapper for dynamic resource requirements.)"""
    if tool.tool['class'] == 'Workflow':
        wfjob = CWLWorkflow(tool, jobobj, runtime_context)
        followOn = ResolveIndirect(wfjob.rv())
        wfjob.addFollowOn(followOn)
        return (wfjob, followOn)
    else:
        resourceReq, _ = tool.get_requirement('ResourceRequirement')
        if resourceReq:
            for req in ('coresMin', 'coresMax', 'ramMin', 'ramMax', 'tmpdirMin', 'tmpdirMax', 'outdirMin', 'outdirMax'):
                r = resourceReq.get(req)
                if isinstance(r, string_types) and ('$(' in r or '${' in r):
                    job = CWLJobWrapper(tool, jobobj, runtime_context)
                    return (job, job)
        job = CWLJob(tool, jobobj, runtime_context)
        return (job, job)

def remove_pickle_problems(obj):
    """doc_loader does not pickle correctly, causing Toil errors, remove from
    objects."""
    if hasattr(obj, 'doc_loader'):
        obj.doc_loader = None
    if hasattr(obj, 'embedded_tool'):
        obj.embedded_tool = remove_pickle_problems(obj.embedded_tool)
    if hasattr(obj, 'steps'):
        obj.steps = [remove_pickle_problems(s) for s in obj.steps]
    return obj

def cleanTempDirs(job):
    """Remove temporarly created directories."""
    if job is CWLJob and job._succeeded:
        for tempDir in job.openTempDirs:
            if os.path.exists(tempDir):
                shutil.rmtree(tempDir)
        job.openTempDirs = []

def tokenize_conf_stream(conf_handle):
    """convert the key=val pairs in a LSF config stream to tuples of tokens"""
    for line in conf_handle:
        if line.startswith('#'):
            continue
        tokens = line.split('=')
        if len(tokens) != 2:
            continue
        yield (tokens[0].strip(), tokens[1].strip())

def apply_bparams(fn):
    """apply fn to each line of bparams, returning the result"""
    cmd = ['bparams', '-a']
    try:
        output = subprocess.check_output(cmd).decode('utf-8')
    except:
        return None
    return fn(output.split('\n'))

