    except:
        return None
    return fn(output.split('\n'))

def get_lsf_units(resource=False):
    """check if we can find LSF_UNITS_FOR_LIMITS in lsadmin and lsf.conf
    files, preferring the value in bparams, then lsadmin, then the lsf.conf file"""
    lsf_units = apply_bparams(get_lsf_units_from_stream)
    if lsf_units:
        return lsf_units
    lsf_units = apply_lsadmin(get_lsf_units_from_stream)
    if lsf_units:
        return lsf_units
    lsf_units = apply_conf_file(get_lsf_units_from_stream, LSF_CONF_FILENAME)
    if lsf_units:
        return lsf_units
    if resource:
        return DEFAULT_RESOURCE_UNITS
    else:
        return DEFAULT_LSF_UNITS

def parse_memory(mem, resource):
    """Parse memory parameter"""
    lsf_unit = get_lsf_units(resource=resource)
    return convert_mb(float(mem) * 1024, lsf_unit)

def per_core_reservation():
    """returns True if the cluster is configured for reservations to be per core,
    False if it is per job"""
    per_core = apply_bparams(per_core_reserve_from_stream)
    if per_core:
        if per_core.upper() == 'Y':
            return True
        else:
            return False
    per_core = apply_lsadmin(per_core_reserve_from_stream)
    if per_core:
        if per_core.upper() == 'Y':
            return True
        else:
            return False
    per_core = apply_conf_file(per_core_reserve_from_stream, LSB_PARAMS_FILENAME)
    if per_core and per_core.upper() == 'Y':
        return True
    else:
        return False
    return False

def addOptions(parser, config=Config()):
    """Adds toil options to a parser object, either optparse or argparse."""
    addLoggingOptions(parser)
    if isinstance(parser, ArgumentParser):
        def addGroup(headingString, bodyString):
            return parser.add_argument_group(headingString, bodyString).add_argument
        parser.register('type', 'bool', lambda v: v.lower() == 'true')
        _addOptions(addGroup, config)
    else:
        raise RuntimeError('Unanticipated class passed to addOptions(), %s. Expecting argparse.ArgumentParser' % parser.__class__)

def parseSetEnv(l):
    """Parses a list of strings of the form "NAME=VALUE" or just "NAME" into a dictionary. Strings
    of the latter from will result in dictionary entries whose value is None.

    :type l: list[str]
    :rtype: dict[str,str]

    >>> parseSetEnv([])
    {}
    >>> parseSetEnv(['a'])
    {'a': None}
    >>> parseSetEnv(['a='])
    {'a': ''}
    >>> parseSetEnv(['a=b'])
    {'a': 'b'}
    >>> parseSetEnv(['a=a', 'a=b'])
    {'a': 'b'}
    >>> parseSetEnv(['a=b', 'c=d'])
    {'a': 'b', 'c': 'd'}
    >>> parseSetEnv(['a=b=c'])
    {'a': 'b=c'}
    >>> parseSetEnv([''])
    Traceback (most recent call last):
    ...
    ValueError: Empty name
    >>> parseSetEnv(['=1'])
    Traceback (most recent call last):
    ...
    ValueError: Empty name"""
    d = dict()
    for i in l:
        try:
            k, v = i.split('=', 1)
        except ValueError:
            k, v = (i, None)
        if not k:
            raise ValueError('Empty name')
        d[k] = v
    return d

def zoneToRegion(zone):
    """Get a region (e.g. us-west-2) from a zone (e.g. us-west-1c)."""
    from toil.lib.context import Context
    return Context.availability_zone_re.match(zone).group(1)

def checkOptions(options, parser):
    """Check options, throw parser.error() if something goes wrong
    """
    if options.jobStore == None:
        parser.error('Specify --jobStore')
    defaultCategories = ['time', 'clock', 'wait', 'memory']
    if options.categories is None:
        options.categories = defaultCategories
    else:
        options.categories = [x.lower() for x in options.categories.split(',')]
    for c in options.categories:
        if c not in defaultCategories:
            parser.error('Unknown category %s. Must be from %s' % (c, str(defaultCategories)))
    extraSort = ['count', 'alpha']
    if options.sortCategory is not None:
        if options.sortCategory not in defaultCategories and options.sortCategory not in extraSort:
            parser.error('Unknown --sortCategory %s. Must be from %s' % (options.sortCategory, str(defaultCategories + extraSort)))
    sortFields = ['min', 'med', 'ave', 'max', 'total']
    if options.sortField is not None:
        if options.sortField not in sortFields:
            parser.error('Unknown --sortField %s. Must be from %s' % (options.sortField, str(sortFields)))

def padStr(s, field=None):
    """Pad the begining of a string with spaces, if necessary.
    """
    if field is None:
        return s
    elif len(s) >= field:
        return s
    else:
        return ' ' * (field - len(s)) + s

def prettyMemory(k, field=None, isBytes=False):
    """Given input k as kilobytes, return a nicely formatted string.
    """
    if isBytes:
        k /= 1024
    if k < 1024:
        return padStr('%gK' % k, field)
    if k < 1024 * 1024:
        return padStr('%.1fM' % old_div(k, 1024.0), field)
    if k < 1024 * 1024 * 1024:
        return padStr('%.1fG' % (k / 1024.0 / 1024.0), field)
    if k < 1024 * 1024 * 1024 * 1024:
        return padStr('%.1fT' % (k / 1024.0 / 1024.0 / 1024.0), field)
    if k < 1024 * 1024 * 1024 * 1024 * 1024:
        return padStr('%.1fP' % (k / 1024.0 / 1024.0 / 1024.0 / 1024.0), field)

def prettyTime(t, field=None):
    """Given input t as seconds, return a nicely formatted string.
    """
    from math import floor
    pluralDict = {True: 's', False: ''}
    if t < 120:
        return padStr('%ds' % t, field)
    if t < 120 * 60:
        m = floor(old_div(t, 60.0))
        s = t % 60
        return padStr('%dm%ds' % (m, s), field)
    if t < 25 * 60 * 60:
        h = floor(t / 60.0 / 60.0)
        m = floor(old_div(t - h * 60.0 * 60.0, 60.0))
        s = t % 60
        return padStr('%dh%gm%ds' % (h, m, s), field)
    if t < 7 * 24 * 60 * 60:
        d = floor(t / 24.0 / 60.0 / 60.0)
        h = floor((t - d * 24.0 * 60.0 * 60.0) / 60.0 / 60.0)
        m = floor(old_div(t - d * 24.0 * 60.0 * 60.0 - h * 60.0 * 60.0, 60.0))
        s = t % 60
        dPlural = pluralDict[d > 1]
        return padStr('%dday%s%dh%dm%ds' % (d, dPlural, h, m, s), field)
    w = floor(t / 7.0 / 24.0 / 60.0 / 60.0)
    d = floor((t - w * 7 * 24 * 60 * 60) / 24.0 / 60.0 / 60.0)
    h = floor((t - w * 7.0 * 24.0 * 60.0 * 60.0 - d * 24.0 * 60.0 * 60.0) / 60.0 / 60.0)
    m = floor(old_div(t - w * 7.0 * 24.0 * 60.0 * 60.0 - d * 24.0 * 60.0 * 60.0 - h * 60.0 * 60.0, 60.0))
    s = t % 60
    wPlural = pluralDict[w > 1]
    dPlural = pluralDict[d > 1]
    return padStr('%dweek%s%dday%s%dh%dm%ds' % (w, wPlural, d, dPlural, h, m, s), field)

def reportTime(t, options, field=None):
    """Given t seconds, report back the correct format as string.
    """
    if options.pretty:
        return prettyTime(t, field=field)
    elif field is not None:
        return '%*.2f' % (field, t)
    else:
        return '%.2f' % t

def reportMemory(k, options, field=None, isBytes=False):
    """Given k kilobytes, report back the correct format as string.
    """
    if options.pretty:
        return prettyMemory(int(k), field=field, isBytes=isBytes)
    else:
        if isBytes:
            k /= 1024.0
        if field is not None:
            return '%*dK' % (field - 1, k)
        else:
            return '%dK' % int(k)

def refineData(root, options):
    """walk down from the root and gather up the important bits.
    """
    worker = root.worker
    job = root.jobs
    jobTypesTree = root.job_types
    jobTypes = []
    for childName in jobTypesTree:
        jobTypes.append(jobTypesTree[childName])
    return (root, worker, job, jobTypes)

def decorateSubHeader(title, columnWidths, options):
    """Add a marker to the correct field if the TITLE is sorted on.
    """
    title = title.lower()
    if title != options.sortCategory:
        s = '| %*s%*s%*s%*s%*s ' % (columnWidths.getWidth(title, 'min'), 'min', columnWidths.getWidth(title, 'med'), 'med', columnWidths.getWidth(title, 'ave'), 'ave', columnWidths.getWidth(title, 'max'), 'max', columnWidths.getWidth(title, 'total'), 'total')
        return s
    else:
        s = '| '
        for field, width in [('min', columnWidths.getWidth(title, 'min')), ('med', columnWidths.getWidth(title, 'med')), ('ave', columnWidths.getWidth(title, 'ave')), ('max', columnWidths.getWidth(title, 'max')), ('total', columnWidths.getWidth(title, 'total'))]:
            if options.sortField == field:
                s += '%*s*' % (width - 1, field)
            else:
                s += '%*s' % (width, field)
        s += ' '
        return s

def get(tree, name):
    """Return a float value attribute NAME from TREE.
    """
    if name in tree:
        value = tree[name]
    else:
        return float('nan')
    try:
        a = float(value)
    except ValueError:
        a = float('nan')
    return a

def sortJobs(jobTypes, options):
    """Return a jobTypes all sorted.
    """
    longforms = {'med': 'median', 'ave': 'average', 'min': 'min', 'total': 'total', 'max': 'max'}
    sortField = longforms[options.sortField]
    if options.sortCategory == 'time' or options.sortCategory == 'clock' or options.sortCategory == 'wait' or (options.sortCategory == 'memory'):
        return sorted(jobTypes, key=lambda tag: getattr(tag, '%s_%s' % (sortField, options.sortCategory)), reverse=options.sortReverse)
    elif options.sortCategory == 'alpha':
        return sorted(jobTypes, key=lambda tag: tag.name, reverse=options.sortReverse)
    elif options.sortCategory == 'count':
        return sorted(jobTypes, key=lambda tag: tag.total_number, reverse=options.sortReverse)

def updateColumnWidths(tag, cw, options):
    """Update the column width attributes for this tag's fields.
    """
    longforms = {'med': 'median', 'ave': 'average', 'min': 'min', 'total': 'total', 'max': 'max'}
    for category in ['time', 'clock', 'wait', 'memory']:
        if category in options.categories:
            for field in ['min', 'med', 'ave', 'max', 'total']:
                t = getattr(tag, '%s_%s' % (longforms[field], category))
                if category in ['time', 'clock', 'wait']:
                    s = reportTime(t, options, field=cw.getWidth(category, field)).strip()
                else:
                    s = reportMemory(t, options, field=cw.getWidth(category, field), isBytes=True).strip()
                if len(s) >= cw.getWidth(category, field):
                    cw.setWidth(category, field, len(s) + 1)

def getStats(jobStore):
    """Collect and return the stats and config data.
    """
    def aggregateStats(fileHandle, aggregateObject):
        try:
            stats = json.load(fileHandle, object_hook=Expando)
            for key in list(stats.keys()):
                if key in aggregateObject:
                    aggregateObject[key].append(stats[key])
                else:
                    aggregateObject[key] = [stats[key]]
        except ValueError:
            logger.critical('File %s contains corrupted json. Skipping file.' % fileHandle)
            pass
    aggregateObject = Expando()
    callBack = partial(aggregateStats, aggregateObject=aggregateObject)
    jobStore.readStatsAndLogging(callBack, readAll=True)
    return aggregateObject

def _put_attributes_using_post(self, domain_or_name, item_name, attributes, replace=True, expected_value=None):
    """Monkey-patched version of SDBConnection.put_attributes that uses POST instead of GET

    The GET version is subject to the URL length limit which kicks in before the 256 x 1024 limit
    for attribute values. Using POST prevents that.

    https://github.com/BD2KGenomics/toil/issues/502"""
    domain, domain_name = self.get_domain_and_name(domain_or_name)
    params = {'DomainName': domain_name, 'ItemName': item_name}
    self._build_name_value_list(params, attributes, replace)
    if expected_value:
        self._build_expected_value(params, expected_value)
    return self.get_status('PutAttributes', params, verb='POST')

def setLoggingFromOptions(options):
