def absSymPath(path):
    """like os.path.abspath except it doesn't dereference symlinks
    """
    curr_path = os.getcwd()
    return os.path.normpath(os.path.join(curr_path, path))

def bytes2human(n, fmt='%(value).1f %(symbol)s', symbols='customary'):
    """Convert n bytes into a human readable string based on format.
    symbols can be either "customary", "customary_ext", "iec" or "iec_ext",
    see: http://goo.gl/kTQMs"""
    n = int(n)
    if n < 0:
        raise ValueError('n < 0')
    symbols = SYMBOLS[symbols]
    prefix = {}
    for i, s in enumerate(symbols[1:]):
        prefix[s] = 1 << (i + 1) * 10
    for symbol in reversed(symbols[1:]):
        if n >= prefix[symbol]:
            value = old_div(float(n), prefix[symbol])
            return fmt % locals()
    return fmt % dict(symbol=symbols[0], value=n)

def adjustEndingReservationForJob(reservation, jobShape, wallTime):
    """Add a job to an ending reservation that ends at wallTime, splitting
    the reservation if the job doesn't fill the entire timeslice."""
    if jobShape.wallTime - wallTime < reservation.shape.wallTime:
        reservation.shape, nS = split(reservation.shape, jobShape, jobShape.wallTime - wallTime)
        nS.nReservation = reservation.nReservation
        reservation.nReservation = nS
    else:
        reservation.subtract(jobShape)

def parseStorage(storageData):
    """Parses EC2 JSON storage param string into a number.

    Examples:
        "2 x 160 SSD"
        "3 x 2000 HDD"
        "EBS only"
        "1 x 410"
        "8 x 1.9 NVMe SSD"

    :param str storageData: EC2 JSON storage param string.
    :return: Two floats representing: (# of disks), and (disk_capacity in GiB of each disk)."""
    if storageData == 'EBS only':
        return [0, 0]
    else:
        specs = storageData.strip().split()
        if isNumber(specs[0]) and specs[1] == 'x' and isNumber(specs[2]):
            return (float(specs[0].replace(',', '')), float(specs[2].replace(',', '')))
        else:
            raise RuntimeError('EC2 JSON format has likely changed.  Error parsing disk specs.')

def parseMemory(memAttribute):
    """Returns EC2 'memory' string as a float.

    Format should always be '#' GiB (example: '244 GiB' or '1,952 GiB').
    Amazon loves to put commas in their numbers, so we have to accommodate that.
    If the syntax ever changes, this will raise.

    :param memAttribute: EC2 JSON memory param string.
    :return: A float representing memory in GiB."""
    mem = memAttribute.replace(',', '').split()
    if mem[1] == 'GiB':
        return float(mem[0])
    else:
        raise RuntimeError('EC2 JSON format has likely changed.  Error parsing memory.')

def fetchEC2InstanceDict(regionNickname=None):
    """Fetches EC2 instances types by region programmatically using the AWS pricing API.

    See: https://aws.amazon.com/blogs/aws/new-aws-price-list-api/

    :return: A dict of InstanceType objects, where the key is the string:
             aws instance name (example: 't2.micro'), and the value is an
             InstanceType object representing that aws instance name."""
    ec2Source = 'https://pricing.us-east-1.amazonaws.com/offers/v1.0/aws/AmazonEC2/current/index.json'
    if regionNickname is None:
        regionNickname = 'us-west-2'
    region = EC2Regions[regionNickname]
    ec2InstanceList = []
    response = requests.get(ec2Source)
    if response.ok:
        ec2InstanceList = parseEC2Json2List(jsontext=response.text, region=region)
    if ec2InstanceList:
        return dict(((_.name, _) for _ in ec2InstanceList))
    else:
        from toil.lib import generatedEC2Lists as defaultEC2
        return dict(((_.name, _) for _ in defaultEC2.ec2InstancesByRegion[regionNickname]))

def parseEC2Json2List(jsontext, region):
    """Takes a JSON and returns a list of InstanceType objects representing EC2 instance params.

    :param jsontext:
    :param region:
    :return:"""
    currentList = json.loads(jsontext)
    ec2InstanceList = []
    for k, v in iteritems(currentList['products']):
        if 'location' in v['attributes'] and v['attributes']['location'] == region:
            if 'tenancy' in v['attributes'] and v['attributes']['tenancy'] == 'Shared':
                if v['attributes']['operatingSystem'] == 'Linux':
                    if v['attributes']['operation'] == 'RunInstances':
                        disks, disk_capacity = parseStorage(v['attributes']['storage'])
                        memory = parseMemory(v['attributes']['memory'])
                        instance = InstanceType(name=v['attributes']['instanceType'], cores=v['attributes']['vcpu'], memory=memory, disks=disks, disk_capacity=disk_capacity)
                        if instance not in ec2InstanceList:
                            ec2InstanceList.append(instance)
                        else:
                            raise RuntimeError('EC2 JSON format has likely changed.  Duplicate instance {} found.'.format(instance))
    return ec2InstanceList

def retryable_http_error(e):
    """Determine if an error encountered during an HTTP download is likely to go away if we try again."""
    if isinstance(e, urllib.error.HTTPError) and e.code in ('503', '408', '500'):
        return True
    if isinstance(e, BadStatusLine):
        return True
    return False

def import_object(object_name):
    """Import an object from its Fully Qualified Name."""
    package, name = object_name.rsplit('.', 1)
    return getattr(importlib.import_module(package), name)

def get_qualified_name(_object):
    """Return the Fully Qualified Name from an instance or class."""
    module = _object.__module__
    if hasattr(_object, '__name__'):
        _class = _object.__name__
    else:
        _class = _object.__class__.__name__
    return module + '.' + _class

def check_valid_values(function):
    """Raises an exception if the given values are not supported.

    Args:
        function(callable): Method whose unique argument is a numpy.array-like object.

    Returns:
        callable: Decorated function

    Raises:
        ValueError: If there are missing or invalid values or if the dataset is empty."""
    def decorated(self, X, *args, **kwargs):
        if isinstance(X, pd.DataFrame):
            W = X.values
        else:
            W = X
        if not len(W):
            raise ValueError('Your dataset is empty.')
        if W.dtype not in [np.dtype('float64'), np.dtype('int64')]:
            raise ValueError('There are non-numerical values in your data.')
        if np.isnan(W).any().any():
            raise ValueError('There are nan values in your data.')
        return function(self, X, *args, **kwargs)
    return decorated

def missing_method_scipy_wrapper(function):
    """Raises a detailed exception when a method is not available."""
    def decorated(self, *args, **kwargs):
        message = 'Your tried to access `{method_name}` from {class_name}, but its not available.\n There can be multiple factors causing this, please feel free to open an issue in https://github.com/DAI-Lab/Copulas/issues/new'
        params = {'method_name': function.__name__, 'class_name': get_qualified_name(function.__self__.__class__)}
        raise NotImplementedError(message.format(**params))
    return decorated

def iso8601_date(d):
    """Return a string representation of a date that the Twilio API understands
    Format is YYYY-MM-DD. Returns None if d is not a string, datetime, or date"""
    if d == values.unset:
        return d
    elif isinstance(d, datetime.datetime):
        return str(d.date())
    elif isinstance(d, datetime.date):
        return str(d)
    elif isinstance(d, str):
        return d

def iso8601_datetime(d):
    """Return a string representation of a date that the Twilio API understands
    Format is YYYY-MM-DD. Returns None if d is not a string, datetime, or date"""
    if d == values.unset:
        return d
    elif isinstance(d, datetime.datetime) or isinstance(d, datetime.date):
        return d.strftime('%Y-%m-%dT%H:%M:%SZ')
    elif isinstance(d, str):
        return d

def prefixed_collapsible_map(m, prefix):
    """Return a dict of params corresponding to those in m with the added prefix"""
    if m == values.unset:
        return {}
    def flatten_dict(d, result={}, prv_keys=[]):
        for k, v in d.items():
            if isinstance(v, dict):
                flatten_dict(v, result, prv_keys + [k])
            else:
                result['.'.join(prv_keys + [k])] = v
        return result
    if isinstance(m, dict):
        flattened = flatten_dict(m)
        return {'{}.{}'.format(prefix, k): v for k, v in flattened.items()}
    return {}

def object(obj):
    """Return a jsonified string represenation of obj if obj is jsonifiable else
    return obj untouched"""
    if isinstance(obj, dict) or isinstance(obj, list):
        return json.dumps(obj)
    return obj

def map(lst, serialize_func):
    """Applies serialize_func to every element in lst"""
    if not isinstance(lst, list):
        return lst
    return [serialize_func(e) for e in lst]

def obsolete_client(func):
    """This is a decorator which can be used to mark Client classes as
    obsolete. It will result in an error being emitted when the class is
    instantiated."""
    @functools.wraps(func)
    def new_func(*args, **kwargs):
        raise ObsoleteException('{} has been removed from this version of the library. Please refer to current documentation for guidance.'.format(func.__name__))
    return new_func

def of(d):
    """Remove unset values from a dict.

    :param dict d: A dict to strip.
    :return dict: A dict with unset values removed."""
    return {k: v for k, v in iteritems(d) if v != unset}

def iso8601_date(s):
    """Parses an ISO 8601 date string and returns a UTC date object or the string
    if the parsing failed.
    :param s: ISO 8601-formatted date string (2015-01-25)
    :return:"""
    try:
        return datetime.datetime.strptime(s, ISO8601_DATE_FORMAT).replace(tzinfo=pytz.utc).date()
    except (TypeError, ValueError):
        return s

def iso8601_datetime(s):
    """Parses an ISO 8601 datetime string and returns a UTC datetime object,
    or the string if parsing failed.
    :param s: ISO 8601-formatted datetime string (2015-01-25T12:34:56Z)
    :return: datetime or str"""
    try:
        return datetime.datetime.strptime(s, ISO8601_DATETIME_FORMAT).replace(tzinfo=pytz.utc)
    except (TypeError, ValueError):
        return s

def rfc2822_datetime(s):
    """Parses an RFC 2822 date string and returns a UTC datetime object,
    or the string if parsing failed.
    :param s: RFC 2822-formatted string date
    :return: datetime or str"""
    date_tuple = parsedate(s)
    if date_tuple is None:
        return None
    return datetime.datetime(*date_tuple[:6]).replace(tzinfo=pytz.utc)

def format_language(language):
    """Attempt to format language parameter as 'ww-WW'.

    :param string language: language parameter"""
    if not language:
        return language
    if not re.match('^[a-zA-Z]{2}[_-][a-zA-Z]{2}$', language):
        raise TwiMLException('Invalid value for language parameter.')
    return language[0:2].lower() + '-' + language[3:5].upper()

def _open(file, mode='r', buffering=-1, encoding=None, errors=None, newline=None, closefd=True, opener=None, *, loop=None, executor=None):
    """Open an asyncio file."""
    if loop is None:
        loop = asyncio.get_event_loop()
    cb = partial(sync_open, file, mode=mode, buffering=buffering, encoding=encoding, errors=errors, newline=newline, closefd=closefd, opener=opener)
    f = (yield from loop.run_in_executor(executor, cb))
    return wrap(f, loop=loop, executor=executor)

def short_repr(item, max_length=15):
    """Short representation of item if it is too long"""
    item = repr(item)
    if len(item) > max_length:
        item = '{}...{}'.format(item[:max_length - 3], item[-1])
    return item

def number_to_string(number, significant_digits, number_format_notation='f'):
    """Convert numbers to string considering significant digits."""
    try:
        using = number_formatting[number_format_notation]
    except KeyError:
        raise ValueError("number_format_notation got invalid value of {}. The valid values are 'f' and 'e'".format(number_format_notation)) from None
    if isinstance(number, Decimal):
        tup = number.as_tuple()
        with localcontext() as ctx:
            ctx.prec = len(tup.digits) + tup.exponent + significant_digits
            number = number.quantize(Decimal('0.' + '0' * significant_digits))
    result = (using % significant_digits).format(number)
    if set(result) <= ZERO_DECIMAL_CHARACTERS:
        result = '0.00'
    if number_format_notation == 'e' and isinstance(number, float):
        result = result.replace('+0', '+')
    return result

def prepare_string_for_hashing(obj, ignore_string_type_changes=False, ignore_string_case=False):
    """Clean type conversions"""
    original_type = obj.__class__.__name__
    if isinstance(obj, bytes):
        obj = obj.decode('utf-8')
    if not ignore_string_type_changes:
        obj = KEY_TO_VAL_STR.format(original_type, obj)
    if ignore_string_case:
        obj = obj.lower()
    return obj

def get_headers(server):
    """Retrieve all HTTP headers"""
    try:
        response = requests.head(server, allow_redirects=False, verify=False, timeout=5)
    except requests.exceptions.ConnectionError:
        return False
    return dict(response.headers)

def get_options(server):
    """Retrieve the available HTTP verbs"""
    try:
        response = requests.options(server, allow_redirects=False, verify=False, timeout=5)
    except (requests.exceptions.ConnectionError, requests.exceptions.MissingSchema):
        return 'Server {} is not available!'.format(server)
    try:
        return {'allowed': response.headers['Allow']}
    except KeyError:
        return 'Unable to get HTTP methods'

