def _distill_params(multiparams, params):
    """Given arguments from the calling form *multiparams, **params,
    return a list of bind parameter structures, usually a list of
    dictionaries.

    In the case of 'raw' execution which accepts positional parameters,
    it may be a list of tuples or lists."""
    if not multiparams:
        if params:
            return [params]
        else:
            return []
    elif len(multiparams) == 1:
        zero = multiparams[0]
        if isinstance(zero, (list, tuple)):
            if not zero or (hasattr(zero[0], '__iter__') and (not hasattr(zero[0], 'strip'))):
                return zero
            else:
                return [zero]
        elif hasattr(zero, 'keys'):
            return [zero]
        else:
            return [[zero]]
    elif hasattr(multiparams[0], '__iter__') and (not hasattr(multiparams[0], 'strip')):
        return multiparams
    else:
        return [multiparams]

def create_engine(minsize=1, maxsize=10, loop=None, dialect=_dialect, pool_recycle=-1, compiled_cache=None, **kwargs):
    """A coroutine for Engine creation.

    Returns Engine instance with embedded connection pool.

    The pool has *minsize* opened connections to MySQL server."""
    deprecated_cursor_classes = [DeserializationCursor, DictCursor, SSCursor, SSDictCursor]
    cursorclass = kwargs.get('cursorclass', Cursor)
    if not issubclass(cursorclass, Cursor) or any((issubclass(cursorclass, cursor_class) for cursor_class in deprecated_cursor_classes)):
        raise ArgumentError('SQLAlchemy engine does not support this cursor class')
    coro = _create_engine(minsize=minsize, maxsize=maxsize, loop=loop, dialect=dialect, pool_recycle=pool_recycle, compiled_cache=compiled_cache, **kwargs)
    return _EngineContextManager(coro)

def _sanitize_dates(start, end):
    """Return (datetime_start, datetime_end) tuple
    if start is None - default is 2015/01/01
    if end is None - default is today"""
    if isinstance(start, int):
        start = datetime(start, 1, 1)
    start = to_datetime(start)
    if isinstance(end, int):
        end = datetime(end, 1, 1)
    end = to_datetime(end)
    if start is None:
        start = datetime(2015, 1, 1)
    if end is None:
        end = datetime.today()
    if start > end:
        raise ValueError('start must be an earlier date than end')
    return (start, end)

