def _http(method, url, headers=None, **kw):
    """Send http request and return response text."""
    params = None
    boundary = None
    if method == 'UPLOAD':
        params, boundary = _encode_multipart(**kw)
    else:
        params = _encode_params(**kw)
    http_url = '%s?%s' % (url, params) if method == _HTTP_GET else url
    http_body = None if method == 'GET' else params
    logging.error('%s: %s' % (method, http_url))
    req = urllib2.Request(http_url, data=http_body)
    req.add_header('Accept-Encoding', 'gzip')
    if headers:
        for k, v in headers.iteritems():
            req.add_header(k, v)
    if boundary:
        req.add_header('Content-Type', 'multipart/form-data; boundary=%s' % boundary)
    try:
        resp = urllib2.urlopen(req, timeout=5)
        return _read_http_body(resp)
    finally:
        pass

def _parse_json(s):
    """parse str into JsonDict"""
    def _obj_hook(pairs):
        """convert json object to python object"""
        o = JsonDict()
        for k, v in pairs.iteritems():
            o[str(k)] = v
        return o
    return json.loads(s, object_hook=_obj_hook)

def _http_call(the_url, method, authorization, **kw):
    """send an http request and return a json object if no error occurred."""
    params = None
    boundary = None
    if method == _HTTP_UPLOAD:
        the_url = the_url.replace('https://api.', 'https://upload.api.')
        params, boundary = _encode_multipart(**kw)
    else:
        params = _encode_params(**kw)
        if '/remind/' in the_url:
            the_url = the_url.replace('https://api.', 'https://rm.api.')
    http_url = '%s?%s' % (the_url, params) if method == _HTTP_GET else the_url
    http_body = None if method == _HTTP_GET else params
    req = urllib2.Request(http_url, data=http_body)
    req.add_header('Accept-Encoding', 'gzip')
    if authorization:
        req.add_header('Authorization', 'OAuth2 %s' % authorization)
    if boundary:
        req.add_header('Content-Type', 'multipart/form-data; boundary=%s' % boundary)
    try:
        resp = urllib2.urlopen(req, timeout=5)
        body = _read_body(resp)
        r = _parse_json(body)
        if hasattr(r, 'error_code'):
            raise APIError(r.error_code, r.get('error', ''), r.get('request', ''))
        return r
    except urllib2.HTTPError as e:
        try:
            r = _parse_json(_read_body(e))
        except:
            r = None
        if hasattr(r, 'error_code'):
            raise APIError(r.error_code, r.get('error', ''), r.get('request', ''))
        raise e

def notify_handler(verb, **kwargs):
    """Handler function to create Notification instance upon action signal call."""
    kwargs.pop('signal', None)
    recipient = kwargs.pop('recipient')
    actor = kwargs.pop('sender')
    optional_objs = [(kwargs.pop(opt, None), opt) for opt in ('target', 'action_object')]
    public = bool(kwargs.pop('public', True))
    description = kwargs.pop('description', None)
    timestamp = kwargs.pop('timestamp', timezone.now())
    level = kwargs.pop('level', Notification.LEVELS.info)
    if isinstance(recipient, Group):
        recipients = recipient.user_set.all()
    elif isinstance(recipient, (QuerySet, list)):
        recipients = recipient
    else:
        recipients = [recipient]
    new_notifications = []
    for recipient in recipients:
        newnotify = Notification(recipient=recipient, actor_content_type=ContentType.objects.get_for_model(actor), actor_object_id=actor.pk, verb=text_type(verb), public=public, description=description, timestamp=timestamp, level=level)
        for obj, opt in optional_objs:
            if obj is not None:
                setattr(newnotify, '%s_object_id' % opt, obj.pk)
                setattr(newnotify, '%s_content_type' % opt, ContentType.objects.get_for_model(obj))
        if kwargs and EXTRA_DATA:
            newnotify.data = kwargs
        newnotify.save()
        new_notifications.append(newnotify)
    return new_notifications

def char2hex(a: str):
    """Convert a hex character to its integer value.

    '0' becomes 0, '9' becomes 9
    'A' becomes 10, 'F' becomes 15
    'a' becomes 10, 'f' becomes 15

    Returns -1 on error."""
    if '0' <= a <= '9':
        return ord(a) - 48
    elif 'A' <= a <= 'F':
        return ord(a) - 55
    elif 'a' <= a <= 'f':
        return ord(a) - 87
    return -1

def assert_valid_execution_arguments(schema: GraphQLSchema, document: DocumentNode, raw_variable_values: Dict[str, Any]=None) -> None:
    """Check that the arguments are acceptable.

    Essential assertions before executing to provide developer feedback for improper use
    of the GraphQL library."""
    if not document:
        raise TypeError('Must provide document')
    assert_valid_schema(schema)
    if not (raw_variable_values is None or isinstance(raw_variable_values, dict)):
        raise TypeError('Variables must be provided as a dictionary where each property is a variable value. Perhaps look to see if an unparsed JSON string was provided.')

def add_path(prev: Optional[ResponsePath], key: Union[str, int]) -> ResponsePath:
    """Add a key to a response path.

    Given a ResponsePath and a key, return a new ResponsePath containing the new key."""
    return ResponsePath(prev, key)

def get_field_def(schema: GraphQLSchema, parent_type: GraphQLObjectType, field_name: str) -> GraphQLField:
    """Get field definition.

    This method looks up the field on the given type definition. It has special casing
    for the two introspection fields, `__schema` and `__typename`. `__typename` is
    special because it can always be queried as a field, even in situations where no
    other fields are allowed, like on a Union. `__schema` could get automatically
    added to the query type, but that would require mutating type definitions, which
    would cause issues."""
    if field_name == '__schema' and schema.query_type == parent_type:
        return SchemaMetaFieldDef
    elif field_name == '__type' and schema.query_type == parent_type:
        return TypeMetaFieldDef
    elif field_name == '__typename':
        return TypeNameMetaFieldDef
    return parent_type.fields.get(field_name)

def get_field_entry_key(node: FieldNode) -> str:
    """Implements the logic to compute the key of a given field's entry"""
    return node.alias.value if node.alias else node.name.value

def invalid_return_type_error(return_type: GraphQLObjectType, result: Any, field_nodes: List[FieldNode]) -> GraphQLError:
    """Create a GraphQLError for an invalid return type."""
    return GraphQLError(f"Expected value of type '{return_type.name}' but got: {inspect(result)}.", field_nodes)

def get_operation_root_type(schema: GraphQLSchema, operation: Union[OperationDefinitionNode, OperationTypeDefinitionNode]) -> GraphQLObjectType:
    """Extract the root type of the operation from the schema."""
    operation_type = operation.operation
    if operation_type == OperationType.QUERY:
        query_type = schema.query_type
        if not query_type:
            raise GraphQLError('Schema does not define the required query root type.', operation)
        return query_type
    elif operation_type == OperationType.MUTATION:
        mutation_type = schema.mutation_type
        if not mutation_type:
            raise GraphQLError('Schema is not configured for mutations.', operation)
        return mutation_type
    elif operation_type == OperationType.SUBSCRIPTION:
        subscription_type = schema.subscription_type
        if not subscription_type:
            raise GraphQLError('Schema is not configured for subscriptions.', operation)
        return subscription_type
    else:
        raise GraphQLError('Can only have query, mutation and subscription operations.', operation)

def is_specified_directive(directive: GraphQLDirective):
    """Check whether the given directive is one of the specified directives."""
    return isinstance(directive, GraphQLDirective) and any((specified_directive.name == directive.name for specified_directive in specified_directives))

def print_error(error: 'GraphQLError') -> str:
    """Print a GraphQLError to a string.

    The printed string will contain useful location information about the
    error's position in the source."""
    printed_locations: List[str] = []
    print_location = printed_locations.append
    if error.nodes:
        for node in error.nodes:
            if node.loc:
                print_location(highlight_source_at_location(node.loc.source, node.loc.source.get_location(node.loc.start)))
    elif error.source and error.locations:
        source = error.source
        for location in error.locations:
            print_location(highlight_source_at_location(source, location))
    if printed_locations:
        return '\n\n'.join([error.message] + printed_locations) + '\n'
    return error.message

def print_prefixed_lines(lines: List[Tuple[str, Optional[str]]]) -> str:
    """Print lines specified like this: ["prefix", "string"]"""
    existing_lines = [line for line in lines if line[1] is not None]
    pad_len = reduce(lambda pad, line: max(pad, len(line[0])), existing_lines, 0)
    return '\n'.join(map(lambda line: line[0].rjust(pad_len) + line[1], existing_lines))

def quoted_or_list(items: List[str]) -> Optional[str]:
    """Given [A, B, C] return "'A', 'B', or 'C'".

    Note: We use single quotes here, since these are also used by repr()."""
    return or_list([f"'{item}'" for item in items])

def dedent_block_string_value(raw_string: str) -> str:
    """Produce the value of a block string from its parsed raw value.

    Similar to CoffeeScript's block string, Python's docstring trim or Ruby's
    strip_heredoc.

    This implements the GraphQL spec's BlockStringValue() static algorithm."""
    lines = raw_string.splitlines()
    common_indent = None
    for line in lines[1:]:
        indent = leading_whitespace(line)
        if indent < len(line) and (common_indent is None or indent < common_indent):
            common_indent = indent
        if common_indent == 0:
            break
    if common_indent:
        lines[1:] = [line[common_indent:] for line in lines[1:]]
    while lines and (not lines[0].strip()):
        lines = lines[1:]
    while lines and (not lines[-1].strip()):
        lines = lines[:-1]
    return '\n'.join(lines)

def is_equal_type(type_a: GraphQLType, type_b: GraphQLType):
    """Check whether two types are equal.

    Provided two types, return true if the types are equal (invariant)."""
    if type_a is type_b:
        return True
    if is_non_null_type(type_a) and is_non_null_type(type_b):
        return is_equal_type(type_a.of_type, type_b.of_type)
    if is_list_type(type_a) and is_list_type(type_b):
        return is_equal_type(type_a.of_type, type_b.of_type)
    return False

def is_type_sub_type_of(schema: GraphQLSchema, maybe_subtype: GraphQLType, super_type: GraphQLType) -> bool:
    """Check whether a type is subtype of another type in a given schema.

    Provided a type and a super type, return true if the first type is either equal or
    a subset of the second super type (covariant)."""
    if maybe_subtype is super_type:
        return True
    if is_non_null_type(super_type):
        if is_non_null_type(maybe_subtype):
            return is_type_sub_type_of(schema, cast(GraphQLNonNull, maybe_subtype).of_type, cast(GraphQLNonNull, super_type).of_type)
        return False
    elif is_non_null_type(maybe_subtype):
        return is_type_sub_type_of(schema, cast(GraphQLNonNull, maybe_subtype).of_type, super_type)
    if is_list_type(super_type):
        if is_list_type(maybe_subtype):
            return is_type_sub_type_of(schema, cast(GraphQLList, maybe_subtype).of_type, cast(GraphQLList, super_type).of_type)
        return False
    elif is_list_type(maybe_subtype):
        return False
    if is_abstract_type(super_type) and is_object_type(maybe_subtype) and schema.is_possible_type(cast(GraphQLAbstractType, super_type), cast(GraphQLObjectType, maybe_subtype)):
        return True
    return False

def do_types_overlap(schema, type_a, type_b):
    """Check whether two types overlap in a given schema.

    Provided two composite types, determine if they "overlap". Two composite types
    overlap when the Sets of possible concrete types for each intersect.

    This is often used to determine if a fragment of a given type could possibly be
    visited in a context of another type.

    This function is commutative."""
    if type_a is type_b:
        return True
    if is_abstract_type(type_a):
        if is_abstract_type(type_b):
            return any((schema.is_possible_type(type_b, type_) for type_ in schema.get_possible_types(type_a)))
        return schema.is_possible_type(type_a, type_b)
    if is_abstract_type(type_b):
        return schema.is_possible_type(type_b, type_a)
    return False

def concat_ast(asts: Sequence[DocumentNode]) -> DocumentNode:
    """Concat ASTs.

    Provided a collection of ASTs, presumably each from different files, concatenate
    the ASTs together into batched AST, useful for validating many GraphQL source files
    which together represent one conceptual application."""
    return DocumentNode(definitions=list(chain.from_iterable((document.definitions for document in asts))))

def suggestion_list(input_: str, options: Collection[str]):
    """Get list with suggestions for a given input.

    Given an invalid input string and list of valid options, returns a filtered list
    of valid options sorted based on their similarity with the input."""
    options_by_distance = {}
    input_threshold = len(input_) // 2
    for option in options:
        distance = lexical_distance(input_, option)
        threshold = max(input_threshold, len(option) // 2, 1)
        if distance <= threshold:
            options_by_distance[option] = distance
    return sorted(options_by_distance, key=options_by_distance.get)

def lexical_distance(a_str: str, b_str: str) -> int:
    """Computes the lexical distance between strings A and B.

    The "distance" between two strings is given by counting the minimum number of edits
    needed to transform string A into string B. An edit can be an insertion, deletion,
    or substitution of a single character, or a swap of two adjacent characters.

    This distance can be useful for detecting typos in input or sorting."""
    if a_str == b_str:
        return 0
    a, b = (a_str.lower(), b_str.lower())
    a_len, b_len = (len(a), len(b))
    if a == b:
        return 1
    d = [[j for j in range(0, b_len + 1)]]
    for i in range(1, a_len + 1):
        d.append([i] + [0] * b_len)
    for i in range(1, a_len + 1):
        for j in range(1, b_len + 1):
            cost = 0 if a[i - 1] == b[j - 1] else 1
            d[i][j] = min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + cost)
            if i > 1 and j > 1 and (a[i - 1] == b[j - 2]) and (a[i - 2] == b[j - 1]):
                d[i][j] = min(d[i][j], d[i - 2][j - 2] + cost)
    return d[a_len][b_len]

def get_operation_ast(document_ast: DocumentNode, operation_name: Optional[str]=None) -> Optional[OperationDefinitionNode]:
    """Get operation AST node.

    Returns an operation AST given a document AST and optionally an operation
    name. If a name is not provided, an operation is only returned if only one
    is provided in the document."""
    operation = None
    for definition in document_ast.definitions:
        if isinstance(definition, OperationDefinitionNode):
            if not operation_name:
                if operation:
                    return None
                operation = definition
            elif definition.name and definition.name.value == operation_name:
                return definition
    return operation

def format_error(error: 'GraphQLError') -> dict:
    """Format a GraphQL error

    Given a GraphQLError, format it according to the rules described by the "Response
    Format, Errors" section of the GraphQL Specification."""
    if not error:
        raise ValueError('Received null or undefined error.')
    formatted: Dict[str, Any] = dict(message=error.message or 'An unknown error occurred.', locations=error.locations, path=error.path)
    if error.extensions:
        formatted.update(extensions=error.extensions)
    return formatted

def graphql_impl(schema, source, root_value, context_value, variable_values, operation_name, field_resolver, type_resolver, middleware, execution_context_class) -> AwaitableOrValue[ExecutionResult]:
    """Execute a query, return asynchronously only if necessary."""
    schema_validation_errors = validate_schema(schema)
    if schema_validation_errors:
        return ExecutionResult(data=None, errors=schema_validation_errors)
    try:
        document = parse(source)
    except GraphQLError as error:
        return ExecutionResult(data=None, errors=[error])
    except Exception as error:
        error = GraphQLError(str(error), original_error=error)
        return ExecutionResult(data=None, errors=[error])
    from .validation import validate
    validation_errors = validate(schema, document)
    if validation_errors:
        return ExecutionResult(data=None, errors=validation_errors)
    return execute(schema, document, root_value, context_value, variable_values, operation_name, field_resolver, type_resolver, middleware, execution_context_class)

def get_named_type(type_):
    """Unwrap possible wrapping type"""
    if type_:
        unwrapped_type = type_
        while is_wrapping_type(unwrapped_type):
            unwrapped_type = cast(GraphQLWrappingType, unwrapped_type)
            unwrapped_type = unwrapped_type.of_type
        return cast(GraphQLNamedType, unwrapped_type)
    return None

def get_nullable_type(type_):
    """Unwrap possible non-null type"""
    if is_non_null_type(type_):
        type_ = cast(GraphQLNonNull, type_)
        type_ = type_.of_type
    return cast(Optional[GraphQLNullableType], type_)

def located_error(original_error: Union[Exception, GraphQLError], nodes: Sequence['Node'], path: Sequence[Union[str, int]]) -> GraphQLError:
    """Located GraphQL Error

    Given an arbitrary Error, presumably thrown while attempting to execute a GraphQL
    operation, produce a new GraphQLError aware of the location in the document
    responsible for the original Error."""
    if original_error:
        try:
            if isinstance(original_error.path, list):
                return original_error
        except AttributeError:
            pass
    try:
        message = original_error.message
    except AttributeError:
        message = str(original_error)
    try:
        source = original_error.source
    except AttributeError:
        source = None
    try:
        positions = original_error.positions
    except AttributeError:
        positions = None
    try:
        nodes = original_error.nodes or nodes
    except AttributeError:
        pass
    return GraphQLError(message, nodes, source, positions, path, original_error)

def assert_valid_name(name: str) -> str:
    """Uphold the spec rules about naming."""
    error = is_valid_name_error(name)
    if error:
        raise error
    return name

def is_valid_name_error(name: str, node: Node=None) -> Optional[GraphQLError]:
    """Return an Error if a name is invalid."""
    if not isinstance(name, str):
        raise TypeError('Expected string')
    if name.startswith('__'):
        return GraphQLError(f"Name {name!r} must not begin with '__', which is reserved by GraphQL introspection.", node)
    if not re_name.match(name):
        return GraphQLError(f'Names must match /^[_a-zA-Z][_a-zA-Z0-9]*$/ but {name!r} does not.', node)
    return None

def or_list(items: Sequence[str]) -> Optional[str]:
    """Given [A, B, C] return 'A, B, or C'."""
    if not items:
        raise ValueError
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return items[0] + ' or ' + items[1]
    *selected, last_item = items[:MAX_LENGTH]
    return ', '.join(selected) + ' or ' + last_item

def assert_valid_schema(schema: GraphQLSchema) -> None:
    """Utility function which asserts a schema is valid.

    Throws a TypeError if the schema is invalid."""
    errors = validate_schema(schema)
    if errors:
        raise TypeError('\n\n'.join((error.message for error in errors)))

def collect_transitive_dependencies(collected: Set[str], dep_graph: DepGraph, from_name: str) -> None:
    """Collect transitive dependencies.

    From a dependency graph, collects a list of transitive dependencies by recursing
    through a dependency graph."""
    immediate_deps = dep_graph[from_name]
    for to_name in immediate_deps:
        if to_name not in collected:
            collected.add(to_name)
            collect_transitive_dependencies(collected, dep_graph, to_name)

def get_directive_values(directive_def: GraphQLDirective, node: NodeWithDirective, variable_values: Dict[str, Any]=None) -> Optional[Dict[str, Any]]:
    """Get coerced argument values based on provided nodes.

    Prepares a dict of argument values given a directive definition and an AST node
    which may contain directives. Optionally also accepts a dict of variable values.

    If the directive does not exist on the node, returns None."""
    directives = node.directives
    if directives:
        directive_name = directive_def.name
        for directive in directives:
            if directive.name.value == directive_name:
                return get_argument_values(directive_def, directive, variable_values)
    return None

def build_schema(source: Union[str, Source], assume_valid=False, assume_valid_sdl=False, no_location=False, experimental_fragment_variables=False) -> GraphQLSchema:
    """Build a GraphQLSchema directly from a source document."""
    return build_ast_schema(parse(source, no_location=no_location, experimental_fragment_variables=experimental_fragment_variables), assume_valid=assume_valid, assume_valid_sdl=assume_valid_sdl)

def type_from_ast(schema, type_node):
    """Get the GraphQL type definition from an AST node.

    Given a Schema and an AST node describing a type, return a GraphQLType definition
    which applies to that type. For example, if provided the parsed AST node for
    `[User]`, a GraphQLList instance will be returned, containing the type called
    "User" found in the schema. If a type called "User" is not found in the schema,
    then None will be returned."""
    if isinstance(type_node, ListTypeNode):
        inner_type = type_from_ast(schema, type_node.type)
        return GraphQLList(inner_type) if inner_type else None
    if isinstance(type_node, NonNullTypeNode):
        inner_type = type_from_ast(schema, type_node.type)
        return GraphQLNonNull(inner_type) if inner_type else None
    if isinstance(type_node, NamedTypeNode):
        return schema.get_type(type_node.name.value)
    raise TypeError(f"Unexpected type node: '{inspect(type_node)}'.")

def get_suggested_field_names(type_: GraphQLOutputType, field_name: str) -> List[str]:
    """Get a list of suggested field names.

    For the field name provided, determine if there are any similar field names that may
    be the result of a typo."""
    if is_object_type(type_) or is_interface_type(type_):
        possible_field_names = list(type_.fields)
        return suggestion_list(field_name, possible_field_names)
    return []

def parse(source: SourceType, no_location=False, experimental_fragment_variables=False) -> DocumentNode:
    """Given a GraphQL source, parse it into a Document.

    Throws GraphQLError if a syntax error is encountered.

    By default, the parser creates AST nodes that know the location in the source that
    they correspond to. The `no_location` option disables that behavior for performance
    or testing.

    Experimental features:

    If `experimental_fragment_variables` is set to True, the parser will understand
    and parse variable definitions contained in a fragment definition. They'll be
    represented in the `variable_definitions` field of the `FragmentDefinitionNode`.

    The syntax is identical to normal, query-defined variables. For example::

        fragment A($var: Boolean = false) on T  {
          ...
        }"""
    if isinstance(source, str):
        source = Source(source)
    elif not isinstance(source, Source):
        raise TypeError(f'Must provide Source. Received: {inspect(source)}')
    lexer = Lexer(source, no_location=no_location, experimental_fragment_variables=experimental_fragment_variables)
    return parse_document(lexer)

def parse_name(lexer: Lexer) -> NameNode:
    """Convert a name lex token into a name parse node."""
    token = expect_token(lexer, TokenKind.NAME)
    return NameNode(value=token.value, loc=loc(lexer, token))

def parse_document(lexer: Lexer) -> DocumentNode:
    """Document: Definition+"""
    start = lexer.token
    return DocumentNode(definitions=many_nodes(lexer, TokenKind.SOF, parse_definition, TokenKind.EOF), loc=loc(lexer, start))

def parse_definition(lexer: Lexer) -> DefinitionNode:
    """Definition: ExecutableDefinition or TypeSystemDefinition"""
    if peek(lexer, TokenKind.NAME):
        func = _parse_definition_functions.get(cast(str, lexer.token.value))
        if func:
            return func(lexer)
    elif peek(lexer, TokenKind.BRACE_L):
        return parse_executable_definition(lexer)
    elif peek_description(lexer):
        return parse_type_system_definition(lexer)
    raise unexpected(lexer)

def parse_executable_definition(lexer: Lexer) -> ExecutableDefinitionNode:
    """ExecutableDefinition: OperationDefinition or FragmentDefinition"""
    if peek(lexer, TokenKind.NAME):
        func = _parse_executable_definition_functions.get(cast(str, lexer.token.value))
        if func:
            return func(lexer)
    elif peek(lexer, TokenKind.BRACE_L):
        return parse_operation_definition(lexer)
    raise unexpected(lexer)

def parse_operation_definition(lexer: Lexer) -> OperationDefinitionNode:
    """OperationDefinition"""
    start = lexer.token
    if peek(lexer, TokenKind.BRACE_L):
        return OperationDefinitionNode(operation=OperationType.QUERY, name=None, variable_definitions=[], directives=[], selection_set=parse_selection_set(lexer), loc=loc(lexer, start))
    operation = parse_operation_type(lexer)
    name = parse_name(lexer) if peek(lexer, TokenKind.NAME) else None
    return OperationDefinitionNode(operation=operation, name=name, variable_definitions=parse_variable_definitions(lexer), directives=parse_directives(lexer, False), selection_set=parse_selection_set(lexer), loc=loc(lexer, start))

def parse_operation_type(lexer: Lexer) -> OperationType:
    """OperationType: one of query mutation subscription"""
    operation_token = expect_token(lexer, TokenKind.NAME)
    try:
        return OperationType(operation_token.value)
    except ValueError:
        raise unexpected(lexer, operation_token)

def parse_variable_definitions(lexer: Lexer) -> List[VariableDefinitionNode]:
    """VariableDefinitions: (VariableDefinition+)"""
    return cast(List[VariableDefinitionNode], many_nodes(lexer, TokenKind.PAREN_L, parse_variable_definition, TokenKind.PAREN_R)) if peek(lexer, TokenKind.PAREN_L) else []

def parse_variable(lexer: Lexer) -> VariableNode:
    """Variable: $Name"""
    start = lexer.token
    expect_token(lexer, TokenKind.DOLLAR)
    return VariableNode(name=parse_name(lexer), loc=loc(lexer, start))

def parse_selection_set(lexer: Lexer) -> SelectionSetNode:
    """SelectionSet: {Selection+}"""
    start = lexer.token
    return SelectionSetNode(selections=many_nodes(lexer, TokenKind.BRACE_L, parse_selection, TokenKind.BRACE_R), loc=loc(lexer, start))

def parse_selection(lexer: Lexer) -> SelectionNode:
    """Selection: Field or FragmentSpread or InlineFragment"""
    return (parse_fragment if peek(lexer, TokenKind.SPREAD) else parse_field)(lexer)

def parse_field(lexer: Lexer) -> FieldNode:
    """Field: Alias? Name Arguments? Directives? SelectionSet?"""
    start = lexer.token
    name_or_alias = parse_name(lexer)
    if expect_optional_token(lexer, TokenKind.COLON):
        alias: Optional[NameNode] = name_or_alias
        name = parse_name(lexer)
    else:
        alias = None
        name = name_or_alias
    return FieldNode(alias=alias, name=name, arguments=parse_arguments(lexer, False), directives=parse_directives(lexer, False), selection_set=parse_selection_set(lexer) if peek(lexer, TokenKind.BRACE_L) else None, loc=loc(lexer, start))

def parse_argument(lexer: Lexer) -> ArgumentNode:
    """Argument: Name : Value"""
    start = lexer.token
    name = parse_name(lexer)
    expect_token(lexer, TokenKind.COLON)
    return ArgumentNode(name=name, value=parse_value_literal(lexer, False), loc=loc(lexer, start))

def parse_const_argument(lexer: Lexer) -> ArgumentNode:
    """Argument[Const]: Name : Value[?Const]"""
    start = lexer.token
    return ArgumentNode(name=parse_name(lexer), value=expect_token(lexer, TokenKind.COLON) and parse_const_value(lexer), loc=loc(lexer, start))

def parse_fragment(lexer: Lexer) -> Union[FragmentSpreadNode, InlineFragmentNode]:
    """Corresponds to both FragmentSpread and InlineFragment in the spec.

    FragmentSpread: ... FragmentName Directives?
    InlineFragment: ... TypeCondition? Directives? SelectionSet"""
    start = lexer.token
    expect_token(lexer, TokenKind.SPREAD)
    has_type_condition = expect_optional_keyword(lexer, 'on')
    if not has_type_condition and peek(lexer, TokenKind.NAME):
        return FragmentSpreadNode(name=parse_fragment_name(lexer), directives=parse_directives(lexer, False), loc=loc(lexer, start))
    return InlineFragmentNode(type_condition=parse_named_type(lexer) if has_type_condition else None, directives=parse_directives(lexer, False), selection_set=parse_selection_set(lexer), loc=loc(lexer, start))

def parse_fragment_definition(lexer: Lexer) -> FragmentDefinitionNode:
    """FragmentDefinition"""
    start = lexer.token
    expect_keyword(lexer, 'fragment')
    if lexer.experimental_fragment_variables:
        return FragmentDefinitionNode(name=parse_fragment_name(lexer), variable_definitions=parse_variable_definitions(lexer), type_condition=parse_type_condition(lexer), directives=parse_directives(lexer, False), selection_set=parse_selection_set(lexer), loc=loc(lexer, start))
    return FragmentDefinitionNode(name=parse_fragment_name(lexer), type_condition=parse_type_condition(lexer), directives=parse_directives(lexer, False), selection_set=parse_selection_set(lexer), loc=loc(lexer, start))

def parse_fragment_name(lexer: Lexer) -> NameNode:
    """FragmentName: Name but not `on`"""
    if lexer.token.value == 'on':
        raise unexpected(lexer)
    return parse_name(lexer)

def parse_list(lexer: Lexer, is_const: bool) -> ListValueNode:
    """ListValue[Const]"""
    start = lexer.token
    item = parse_const_value if is_const else parse_value_value
    return ListValueNode(values=any_nodes(lexer, TokenKind.BRACKET_L, item, TokenKind.BRACKET_R), loc=loc(lexer, start))

def parse_object(lexer: Lexer, is_const: bool) -> ObjectValueNode:
    """ObjectValue[Const]"""
    start = lexer.token
    item = cast(Callable[[Lexer], Node], partial(parse_object_field, is_const=is_const))
    return ObjectValueNode(fields=any_nodes(lexer, TokenKind.BRACE_L, item, TokenKind.BRACE_R), loc=loc(lexer, start))

def parse_directive(lexer: Lexer, is_const: bool) -> DirectiveNode:
    """Directive[Const]: @ Name Arguments[?Const]?"""
    start = lexer.token
    expect_token(lexer, TokenKind.AT)
    return DirectiveNode(name=parse_name(lexer), arguments=parse_arguments(lexer, is_const), loc=loc(lexer, start))

def parse_type_reference(lexer: Lexer) -> TypeNode:
    """Type: NamedType or ListType or NonNullType"""
    start = lexer.token
    if expect_optional_token(lexer, TokenKind.BRACKET_L):
        type_ = parse_type_reference(lexer)
        expect_token(lexer, TokenKind.BRACKET_R)
        type_ = ListTypeNode(type=type_, loc=loc(lexer, start))
    else:
        type_ = parse_named_type(lexer)
    if expect_optional_token(lexer, TokenKind.BANG):
        return NonNullTypeNode(type=type_, loc=loc(lexer, start))
    return type_

def parse_named_type(lexer: Lexer) -> NamedTypeNode:
    """NamedType: Name"""
    start = lexer.token
    return NamedTypeNode(name=parse_name(lexer), loc=loc(lexer, start))

def parse_type_system_definition(lexer: Lexer) -> TypeSystemDefinitionNode:
    """TypeSystemDefinition"""
    keyword_token = lexer.lookahead() if peek_description(lexer) else lexer.token
    func = _parse_type_system_definition_functions.get(cast(str, keyword_token.value))
    if func:
        return func(lexer)
    raise unexpected(lexer, keyword_token)

def parse_type_system_extension(lexer: Lexer) -> TypeSystemExtensionNode:
    """TypeSystemExtension"""
    keyword_token = lexer.lookahead()
    if keyword_token.kind == TokenKind.NAME:
        func = _parse_type_extension_functions.get(cast(str, keyword_token.value))
        if func:
            return func(lexer)
    raise unexpected(lexer, keyword_token)

def parse_implements_interfaces(lexer: Lexer) -> List[NamedTypeNode]:
    """ImplementsInterfaces"""
    types: List[NamedTypeNode] = []
    if expect_optional_keyword(lexer, 'implements'):
        expect_optional_token(lexer, TokenKind.AMP)
        append = types.append
        while True:
            append(parse_named_type(lexer))
            if not expect_optional_token(lexer, TokenKind.AMP):
                break
    return types

def parse_fields_definition(lexer: Lexer) -> List[FieldDefinitionNode]:
    """FieldsDefinition: {FieldDefinition+}"""
    return cast(List[FieldDefinitionNode], many_nodes(lexer, TokenKind.BRACE_L, parse_field_definition, TokenKind.BRACE_R)) if peek(lexer, TokenKind.BRACE_L) else []

def parse_argument_defs(lexer: Lexer) -> List[InputValueDefinitionNode]:
    """ArgumentsDefinition: (InputValueDefinition+)"""
    return cast(List[InputValueDefinitionNode], many_nodes(lexer, TokenKind.PAREN_L, parse_input_value_def, TokenKind.PAREN_R)) if peek(lexer, TokenKind.PAREN_L) else []

def parse_union_member_types(lexer: Lexer) -> List[NamedTypeNode]:
    """UnionMemberTypes"""
    types: List[NamedTypeNode] = []
    if expect_optional_token(lexer, TokenKind.EQUALS):
        expect_optional_token(lexer, TokenKind.PIPE)
        append = types.append
        while True:
            append(parse_named_type(lexer))
            if not expect_optional_token(lexer, TokenKind.PIPE):
                break
    return types

def parse_enum_values_definition(lexer: Lexer) -> List[EnumValueDefinitionNode]:
    """EnumValuesDefinition: {EnumValueDefinition+}"""
    return cast(List[EnumValueDefinitionNode], many_nodes(lexer, TokenKind.BRACE_L, parse_enum_value_definition, TokenKind.BRACE_R)) if peek(lexer, TokenKind.BRACE_L) else []

def parse_input_fields_definition(lexer: Lexer) -> List[InputValueDefinitionNode]:
    """InputFieldsDefinition: {InputValueDefinition+}"""
    return cast(List[InputValueDefinitionNode], many_nodes(lexer, TokenKind.BRACE_L, parse_input_value_def, TokenKind.BRACE_R)) if peek(lexer, TokenKind.BRACE_L) else []

def parse_schema_extension(lexer: Lexer) -> SchemaExtensionNode:
    """SchemaExtension"""
    start = lexer.token
    expect_keyword(lexer, 'extend')
    expect_keyword(lexer, 'schema')
    directives = parse_directives(lexer, True)
    operation_types = many_nodes(lexer, TokenKind.BRACE_L, parse_operation_type_definition, TokenKind.BRACE_R) if peek(lexer, TokenKind.BRACE_L) else []
    if not directives and (not operation_types):
        raise unexpected(lexer)
    return SchemaExtensionNode(directives=directives, operation_types=operation_types, loc=loc(lexer, start))

def parse_scalar_type_extension(lexer: Lexer) -> ScalarTypeExtensionNode:
    """ScalarTypeExtension"""
    start = lexer.token
    expect_keyword(lexer, 'extend')
    expect_keyword(lexer, 'scalar')
    name = parse_name(lexer)
    directives = parse_directives(lexer, True)
    if not directives:
        raise unexpected(lexer)
    return ScalarTypeExtensionNode(name=name, directives=directives, loc=loc(lexer, start))

def parse_directive_locations(lexer: Lexer) -> List[NameNode]:
    """DirectiveLocations"""
    expect_optional_token(lexer, TokenKind.PIPE)
    locations: List[NameNode] = []
    append = locations.append
    while True:
        append(parse_directive_location(lexer))
        if not expect_optional_token(lexer, TokenKind.PIPE):
            break
    return locations

def loc(lexer: Lexer, start_token: Token) -> Optional[Location]:
    """Return a location object.

    Used to identify the place in the source that created a given parsed object."""
    if not lexer.no_location:
        end_token = lexer.last_token
        source = lexer.source
        return Location(start_token.start, end_token.end, start_token, end_token, source)
    return None

def unexpected(lexer: Lexer, at_token: Token=None) -> GraphQLError:
    """Create an error when an unexpected lexed token is encountered."""
    token = at_token or lexer.token
    return GraphQLSyntaxError(lexer.source, token.start, f'Unexpected {token.desc}')

def coercion_error(message: str, blame_node: Node=None, path: Path=None, sub_message: str=None, original_error: Exception=None) -> GraphQLError:
    """Return a GraphQLError instance"""
    if path:
        path_str = print_path(path)
        message += f' at {path_str}'
    message += f'; {sub_message}' if sub_message else '.'
    return GraphQLError(message, blame_node, None, None, None, original_error)

def parse_int_literal(ast, _variables=None):
    """Parse an integer value node in the AST."""
    if isinstance(ast, IntValueNode):
        num = int(ast.value)
        if MIN_INT <= num <= MAX_INT:
            return num
    return INVALID

def parse_float_literal(ast, _variables=None):
    """Parse a float value node in the AST."""
    if isinstance(ast, (FloatValueNode, IntValueNode)):
        return float(ast.value)
    return INVALID

def parse_id_literal(ast, _variables=None):
    """Parse an ID value node in the AST."""
    if isinstance(ast, (StringValueNode, IntValueNode)):
        return ast.value
    return INVALID

def find_types_removed_from_unions(old_schema: GraphQLSchema, new_schema: GraphQLSchema) -> List[BreakingChange]:
    """Find types removed from unions.

    Given two schemas, returns a list containing descriptions of any breaking changes
    in the new_schema related to removing types from a union type."""
    old_type_map = old_schema.type_map
    new_type_map = new_schema.type_map
    types_removed_from_union = []
    for old_type_name, old_type in old_type_map.items():
        new_type = new_type_map.get(old_type_name)
        if not (is_union_type(old_type) and is_union_type(new_type)):
            continue
        old_type = cast(GraphQLUnionType, old_type)
        new_type = cast(GraphQLUnionType, new_type)
        type_names_in_new_union = {type_.name for type_ in new_type.types}
        for type_ in old_type.types:
            type_name = type_.name
            if type_name not in type_names_in_new_union:
                types_removed_from_union.append(BreakingChange(BreakingChangeType.TYPE_REMOVED_FROM_UNION, f'{type_name} was removed from union type {old_type_name}.'))
    return types_removed_from_union

def find_types_added_to_unions(old_schema: GraphQLSchema, new_schema: GraphQLSchema) -> List[DangerousChange]:
    """Find types added to union.

    Given two schemas, returns a list containing descriptions of any dangerous changes
    in the new_schema related to adding types to a union type."""
    old_type_map = old_schema.type_map
    new_type_map = new_schema.type_map
    types_added_to_union = []
    for new_type_name, new_type in new_type_map.items():
        old_type = old_type_map.get(new_type_name)
        if not (is_union_type(old_type) and is_union_type(new_type)):
            continue
        old_type = cast(GraphQLUnionType, old_type)
        new_type = cast(GraphQLUnionType, new_type)
        type_names_in_old_union = {type_.name for type_ in old_type.types}
        for type_ in new_type.types:
            type_name = type_.name
            if type_name not in type_names_in_old_union:
                types_added_to_union.append(DangerousChange(DangerousChangeType.TYPE_ADDED_TO_UNION, f'{type_name} was added to union type {new_type_name}.'))
    return types_added_to_union

def is_finite(value: Any) -> bool:
    """Return true if a value is a finite number."""
    return isinstance(value, int) or (isinstance(value, float) and isfinite(value))

def collect_conflicts_between_fields_and_fragment(context: ValidationContext, conflicts: List[Conflict], cached_fields_and_fragment_names: Dict, compared_fragments: Set[str], compared_fragment_pairs: 'PairSet', are_mutually_exclusive: bool, field_map: NodeAndDefCollection, fragment_name: str) -> None:
    """Collect conflicts between fields and fragment.

    Collect all conflicts found between a set of fields and a fragment reference
    including via spreading in any nested fragments."""
    if fragment_name in compared_fragments:
        return
    compared_fragments.add(fragment_name)
    fragment = context.get_fragment(fragment_name)
    if not fragment:
        return None
    field_map2, fragment_names2 = get_referenced_fields_and_fragment_names(context, cached_fields_and_fragment_names, fragment)
    if field_map is field_map2:
        return
    collect_conflicts_between(context, conflicts, cached_fields_and_fragment_names, compared_fragment_pairs, are_mutually_exclusive, field_map, field_map2)
    for fragment_name2 in fragment_names2:
        collect_conflicts_between_fields_and_fragment(context, conflicts, cached_fields_and_fragment_names, compared_fragments, compared_fragment_pairs, are_mutually_exclusive, field_map, fragment_name2)

def collect_conflicts_within(context: ValidationContext, conflicts: List[Conflict], cached_fields_and_fragment_names: Dict, compared_fragment_pairs: 'PairSet', field_map: NodeAndDefCollection) -> None:
    """Collect all Conflicts "within" one collection of fields."""
    for response_name, fields in field_map.items():
        if len(fields) > 1:
            for i, field in enumerate(fields):
                for other_field in fields[i + 1:]:
                    conflict = find_conflict(context, cached_fields_and_fragment_names, compared_fragment_pairs, False, response_name, field, other_field)
                    if conflict:
                        conflicts.append(conflict)

def collect_conflicts_between(context: ValidationContext, conflicts: List[Conflict], cached_fields_and_fragment_names: Dict, compared_fragment_pairs: 'PairSet', parent_fields_are_mutually_exclusive: bool, field_map1: NodeAndDefCollection, field_map2: NodeAndDefCollection) -> None:
    """Collect all Conflicts between two collections of fields.

    This is similar to, but different from the `collectConflictsWithin` function above.
    This check assumes that `collectConflictsWithin` has already been called on each
    provided collection of fields. This is true because this validator traverses each
    individual selection set."""
    for response_name, fields1 in field_map1.items():
        fields2 = field_map2.get(response_name)
        if fields2:
            for field1 in fields1:
                for field2 in fields2:
                    conflict = find_conflict(context, cached_fields_and_fragment_names, compared_fragment_pairs, parent_fields_are_mutually_exclusive, response_name, field1, field2)
                    if conflict:
                        conflicts.append(conflict)

def do_types_conflict(type1: GraphQLOutputType, type2: GraphQLOutputType) -> bool:
    """Check whether two types conflict

    Two types conflict if both types could not apply to a value simultaneously.
    Composite types are ignored as their individual field types will be compared later
    recursively. However List and Non-Null types must match."""
    if is_list_type(type1):
        return do_types_conflict(cast(GraphQLList, type1).of_type, cast(GraphQLList, type2).of_type) if is_list_type(type2) else True
    if is_list_type(type2):
        return True
    if is_non_null_type(type1):
        return do_types_conflict(cast(GraphQLNonNull, type1).of_type, cast(GraphQLNonNull, type2).of_type) if is_non_null_type(type2) else True
    if is_non_null_type(type2):
        return True
    if is_leaf_type(type1) or is_leaf_type(type2):
        return type1 is not type2
    return False

def get_fields_and_fragment_names(context: ValidationContext, cached_fields_and_fragment_names: Dict, parent_type: Optional[GraphQLNamedType], selection_set: SelectionSetNode) -> Tuple[NodeAndDefCollection, List[str]]:
    """Get fields and referenced fragment names

    Given a selection set, return the collection of fields (a mapping of response name
    to field nodes and definitions) as well as a list of fragment names referenced via
    fragment spreads."""
    cached = cached_fields_and_fragment_names.get(selection_set)
    if not cached:
        node_and_defs: NodeAndDefCollection = {}
        fragment_names: Dict[str, bool] = {}
        collect_fields_and_fragment_names(context, parent_type, selection_set, node_and_defs, fragment_names)
        cached = (node_and_defs, list(fragment_names))
        cached_fields_and_fragment_names[selection_set] = cached
    return cached

def get_referenced_fields_and_fragment_names(context: ValidationContext, cached_fields_and_fragment_names: Dict, fragment: FragmentDefinitionNode) -> Tuple[NodeAndDefCollection, List[str]]:
    """Get referenced fields and nested fragment names

    Given a reference to a fragment, return the represented collection of fields as well
    as a list of nested fragment names referenced via fragment spreads."""
    cached = cached_fields_and_fragment_names.get(fragment.selection_set)
    if cached:
        return cached
    fragment_type = type_from_ast(context.schema, fragment.type_condition)
    return get_fields_and_fragment_names(context, cached_fields_and_fragment_names, fragment_type, fragment.selection_set)

def subfield_conflicts(conflicts: List[Conflict], response_name: str, node1: FieldNode, node2: FieldNode) -> Optional[Conflict]:
    """Check whether there are conflicts between sub-fields.

    Given a series of Conflicts which occurred between two sub-fields, generate a single
    Conflict."""
    if conflicts:
        return ((response_name, [conflict[0] for conflict in conflicts]), list(chain([node1], *[conflict[1] for conflict in conflicts])), list(chain([node2], *[conflict[2] for conflict in conflicts])))
    return None

def get_field_def(schema: GraphQLSchema, parent_type: GraphQLType, field_node: FieldNode) -> Optional[GraphQLField]:
    """Get field definition.

    Not exactly the same as the executor's definition of `get_field_def()`, in this
    statically evaluated environment we do not always have an Object type, and need
    to handle Interface and Union types."""
    name = field_node.name.value
    if name == '__schema' and schema.query_type is parent_type:
        return SchemaMetaFieldDef
    if name == '__type' and schema.query_type is parent_type:
        return TypeMetaFieldDef
    if name == '__typename' and is_composite_type(parent_type):
        return TypeNameMetaFieldDef
    if is_object_type(parent_type) or is_interface_type(parent_type):
        parent_type = cast(Union[GraphQLObjectType, GraphQLInterfaceType], parent_type)
        return parent_type.fields.get(name)
    return None

def is_missing_variable(value_node: ValueNode, variables: Dict[str, Any]=None) -> bool:
    """Check if `value_node` is a variable not defined in the `variables` dict."""
    return isinstance(value_node, VariableNode) and (not variables or is_invalid(variables.get(value_node.name.value, INVALID)))

def is_integer(value: Any) -> bool:
    """Return true if a value is an integer number."""
    return isinstance(value, int) and (not isinstance(value, bool)) or (isinstance(value, float) and isfinite(value) and (int(value) == value))

def allowed_variable_usage(schema: GraphQLSchema, var_type: GraphQLType, var_default_value: Optional[ValueNode], location_type: GraphQLType, location_default_value: Any) -> bool:
    """Check for allowed variable usage.

    Returns True if the variable is allowed in the location it was found, which includes
    considering if default values exist for either the variable or the location at which
    it is located."""
    if is_non_null_type(location_type) and (not is_non_null_type(var_type)):
        has_non_null_variable_default_value = var_default_value and (not isinstance(var_default_value, NullValueNode))
        has_location_default_value = location_default_value is not INVALID
        if not has_non_null_variable_default_value and (not has_location_default_value):
            return False
        location_type = cast(GraphQLNonNull, location_type)
        nullable_location_type = location_type.of_type
        return is_type_sub_type_of(schema, var_type, nullable_location_type)
    return is_type_sub_type_of(schema, var_type, location_type)

def is_schema_of_common_names(schema: GraphQLSchema) -> bool:
    """Check whether this schema uses the common naming convention.

    GraphQL schema define root types for each type of operation. These types are the
    same as any other type and can be named in any manner, however there is a common
    naming convention:

    schema {
      query: Query
      mutation: Mutation
    }

    When using this naming convention, the schema description can be omitted."""
    query_type = schema.query_type
    if query_type and query_type.name != 'Query':
        return False
    mutation_type = schema.mutation_type
    if mutation_type and mutation_type.name != 'Mutation':
        return False
    subscription_type = schema.subscription_type
    if subscription_type and subscription_type.name != 'Subscription':
        return False
    return True

def print_value(value: Any, type_: GraphQLInputType) -> str:
    """Convenience function for printing a Python value"""
    return print_ast(ast_from_value(value, type_))

def add_description(method):
    """Decorator adding the description to the output of a visitor method."""
    @wraps(method)
    def wrapped(self, node, *args):
        return join([node.description, method(self, node, *args)], '\n')
    return wrapped

def has_multiline_items(maybe_list: Optional[Sequence[str]]):
    """Check whether one of the items in the list has multiple lines."""
    return maybe_list and any((is_multiline(item) for item in maybe_list))

def get_middleware_resolvers(middlewares: Tuple[Any, ...]) -> Iterator[Callable]:
    """Get a list of resolver functions from a list of classes or functions."""
    for middleware in middlewares:
        if isfunction(middleware):
            yield middleware
        else:
            resolver_func = getattr(middleware, 'resolve', None)
            if resolver_func is not None:
                yield resolver_func

def type_map_reducer(map_: TypeMap, type_: GraphQLNamedType=None) -> TypeMap:
    """Reducer function for creating the type map from given types."""
    if not type_:
        return map_
    if is_wrapping_type(type_):
        return type_map_reducer(map_, cast(GraphQLWrappingType[GraphQLNamedType], type_).of_type)
    name = type_.name
    if name in map_:
        if map_[name] is not type_:
            raise TypeError(f'Schema must contain uniquely named types but contains multiple types named {name!r}.')
        return map_
    map_[name] = type_
    if is_union_type(type_):
        type_ = cast(GraphQLUnionType, type_)
        map_ = type_map_reduce(type_.types, map_)
    if is_object_type(type_):
        type_ = cast(GraphQLObjectType, type_)
        map_ = type_map_reduce(type_.interfaces, map_)
    if is_object_type(type_) or is_interface_type(type_):
        for field in cast(GraphQLInterfaceType, type_).fields.values():
            args = field.args
            if args:
                types = [arg.type for arg in args.values()]
                map_ = type_map_reduce(types, map_)
            map_ = type_map_reducer(map_, field.type)
    if is_input_object_type(type_):
        for field in cast(GraphQLInputObjectType, type_).fields.values():
            map_ = type_map_reducer(map_, field.type)
    return map_

def type_map_directive_reducer(map_: TypeMap, directive: GraphQLDirective=None) -> TypeMap:
    """Reducer function for creating the type map from given directives."""
    if not is_directive(directive):
        return map_
    directive = cast(GraphQLDirective, directive)
    return reduce(lambda prev_map, arg: type_map_reducer(prev_map, arg.type), directive.args.values(), map_)

def respond(request, code):
    """Responds to the request with the given response code.
    If ``next`` is in the form, it will redirect instead."""
    redirect = request.GET.get('next', request.POST.get('next'))
    if redirect:
        return HttpResponseRedirect(redirect)
    return type('Response%d' % code, (HttpResponse,), {'status_code': code})()

def follow_unfollow(request, content_type_id, object_id, flag, do_follow=True, actor_only=True):
    """Creates or deletes the follow relationship between ``request.user`` and the
    actor defined by ``content_type_id``, ``object_id``."""
    ctype = get_object_or_404(ContentType, pk=content_type_id)
    instance = get_object_or_404(ctype.model_class(), pk=object_id)
    flag = flag or ''
    if do_follow:
        actions.follow(request.user, instance, actor_only=actor_only, flag=flag)
        return respond(request, 201)
    actions.unfollow(request.user, instance, flag=flag)
    return respond(request, 204)

