def get_action_manager():
    """Returns the class of the action manager to use from ACTSTREAM_SETTINGS['MANAGER']"""
    mod = SETTINGS.get('MANAGER', 'actstream.managers.ActionManager')
    mod_path = mod.split('.')
    try:
        return getattr(__import__('.'.join(mod_path[:-1]), {}, {}, [mod_path[-1]]), mod_path[-1])()
    except ImportError:
        raise ImportError('Cannot import %s try fixing ACTSTREAM_SETTINGS[MANAGER]setting.' % mod)

def stream(func):
    """Stream decorator to be applied to methods of an ``ActionManager`` subclass

    Syntax::

        from actstream.decorators import stream
        from actstream.managers import ActionManager

        class MyManager(ActionManager):
            @stream
            def foobar(self, ...):
                ..."""
    @wraps(func)
    def wrapped(manager, *args, **kwargs):
        offset, limit = (kwargs.pop('_offset', None), kwargs.pop('_limit', None))
        qs = func(manager, *args, **kwargs)
        if isinstance(qs, dict):
            qs = manager.public(**qs)
        elif isinstance(qs, (list, tuple)):
            qs = manager.public(*qs)
        if offset or limit:
            qs = qs[offset:limit]
        return qs.fetch_generic_relations()
    return wrapped

def follow_url(parser, token):
    """Renders the URL of the follow view for a particular actor instance

    ::

        <a href="{% follow_url other_user %}">
            {% if request.user|is_following:other_user %}
                stop following
            {% else %}
                follow
            {% endif %}
        </a>

        <a href="{% follow_url other_user 'watching' %}">
            {% is_following user group "watching" as is_watching %}
            {% if is_watching %}
                stop watching
            {% else %}
                watch
            {% endif %}
        </a>"""
    bits = token.split_contents()
    if len(bits) > 3:
        raise TemplateSyntaxError('Accepted format {% follow_url [instance] %} or {% follow_url [instance] [flag] %}')
    elif len(bits) == 2:
        return DisplayActivityFollowUrl(bits[1])
    else:
        flag = bits[2][1:-1]
        return DisplayActivityFollowUrl(bits[1], flag=flag)

def follow_all_url(parser, token):
    """Renders the URL to follow an object as both actor and target

    ::

        <a href="{% follow_all_url other_user %}">
            {% if request.user|is_following:other_user %}
                stop following
            {% else %}
                follow
            {% endif %}
        </a>

        <a href="{% follow_all_url other_user 'watching' %}">
            {% is_following user group "watching" as is_watching %}
            {% if is_watching %}
                stop watching
            {% else %}
                watch
            {% endif %}
        </a>"""
    bits = token.split_contents()
    if len(bits) > 3:
        raise TemplateSyntaxError('Accepted format {% follow_all_url [instance] %} or {% follow_url [instance] [flag] %}')
    elif len(bits) == 2:
        return DisplayActivityFollowUrl(bits[1], actor_only=False)
    else:
        flag = bits[2][1:-1]
        return DisplayActivityFollowUrl(bits[1], actor_only=False, flag=flag)

def activity_stream(context, stream_type, *args, **kwargs):
    """Renders an activity stream as a list into the template's context.
    Streams loaded by stream_type can be the default ones (eg user, actor, etc.) or a user defined stream.
    Extra args/kwargs are passed into the stream call.

    ::

        {% activity_stream 'actor' user %}
        {% for action in stream %}
            {% display_action action %}
        {% endfor %}"""
    if stream_type == 'model':
        stream_type = 'model_actions'
    if not hasattr(Action.objects, stream_type):
        raise TemplateSyntaxError('Action manager has no attribute: %s' % stream_type)
    ctxvar = kwargs.pop('as', 'stream')
    context[ctxvar] = getattr(Action.objects, stream_type)(*args, **kwargs)
    return ''

def categories_for_actions(actions):
    """Given an iterable of actions, return a mapping of action groups.

    actions: {'ec2:authorizesecuritygroupingress', 'iam:putrolepolicy', 'iam:listroles'}

    Returns:
        {
            'ec2': {'Write'},
            'iam': {'Permissions', 'List'})
        }"""
    groups = defaultdict(set)
    for action in actions:
        service = action.split(':')[0]
        groups[service].add(_action_categories.get(action))
    return groups

def actions_for_category(category):
    """Returns set of actions containing each group passed in.

    Param:
        category must be in {'Permissions', 'List', 'Read', 'Write'}

    Returns:
        set of matching actions"""
    actions = set()
    for action, action_category in _action_categories.items():
        if action_category == category:
            actions.add(action)
    return actions

def _expand_wildcard_action(action):
    """:param action: 'autoscaling:*'
    :return: A list of all autoscaling permissions matching the wildcard"""
    if isinstance(action, list):
        expanded_actions = []
        for item in action:
            expanded_actions.extend(_expand_wildcard_action(item))
        return expanded_actions
    else:
        if '*' in action:
            expanded = [expanded_action.lower() for expanded_action in all_permissions if fnmatch.fnmatchcase(expanded_action.lower(), action.lower())]
            if not expanded:
                return [action.lower()]
            return expanded
        return [action.lower()]

def extract_audioclip_samples(d) -> dict:
    """Extract all the sample data from an AudioClip and
    convert it from FSB5 if needed."""
    ret = {}
    if not d.data:
        return {}
    try:
        from fsb5 import FSB5
    except ImportError as e:
        raise RuntimeError('python-fsb5 is required to extract AudioClip')
    af = FSB5(d.data)
    for i, sample in enumerate(af.samples):
        if i > 0:
            filename = '%s-%i.%s' % (d.name, i, af.get_sample_extension())
        else:
            filename = '%s.%s' % (d.name, af.get_sample_extension())
        try:
            sample = af.rebuild_sample(sample)
        except ValueError as e:
            print('WARNING: Could not extract %r (%s)' % (d, e))
            continue
        ret[filename] = sample
    return ret

def get_available_FIELD_transitions(instance, field):
    """List of transitions available in current model state
    with all conditions met"""
    curr_state = field.get_state(instance)
    transitions = field.transitions[instance.__class__]
    for name, transition in transitions.items():
        meta = transition._django_fsm
        if meta.has_transition(curr_state) and meta.conditions_met(instance, curr_state):
            yield meta.get_transition(curr_state)

def get_available_user_FIELD_transitions(instance, user, field):
    """List of transitions available in current model state
    with all conditions met and user have rights on it"""
    for transition in get_available_FIELD_transitions(instance, field):
        if transition.has_perm(instance, user):
            yield transition

def transition(field, source='*', target=None, on_error=None, conditions=[], permission=None, custom={}):
    """Method decorator to mark allowed transitions.

    Set target to None if current state needs to be validated and
    has not changed after the function call."""
    def inner_transition(func):
        wrapper_installed, fsm_meta = (True, getattr(func, '_django_fsm', None))
        if not fsm_meta:
            wrapper_installed = False
            fsm_meta = FSMMeta(field=field, method=func)
            setattr(func, '_django_fsm', fsm_meta)
        if isinstance(source, (list, tuple, set)):
            for state in source:
                func._django_fsm.add_transition(func, state, target, on_error, conditions, permission, custom)
        else:
            func._django_fsm.add_transition(func, source, target, on_error, conditions, permission, custom)
        @wraps(func)
        def _change_state(instance, *args, **kwargs):
            return fsm_meta.field.change_state(instance, func, *args, **kwargs)
        if not wrapper_installed:
            return _change_state
        return func
    return inner_transition

def has_transition_perm(bound_method, user):
    """Returns True if model in state allows to call bound_method and user have rights on it"""
    if not hasattr(bound_method, '_django_fsm'):
        im_func = getattr(bound_method, 'im_func', getattr(bound_method, '__func__'))
        raise TypeError('%s method is not transition' % im_func.__name__)
    meta = bound_method._django_fsm
    im_self = getattr(bound_method, 'im_self', getattr(bound_method, '__self__'))
    current_state = meta.field.get_state(im_self)
    return meta.has_transition(current_state) and meta.conditions_met(im_self, current_state) and meta.has_transition_perm(im_self, current_state, user)

def ExportMigrations():
    """Exports counts of unapplied migrations.

    This is meant to be called during app startup, ideally by
    django_prometheus.apps.AppConfig."""
    from django.db.migrations.executor import MigrationExecutor
    if 'default' in connections and type(connections['default']) == DatabaseWrapper:
        return
    for alias in connections.databases:
        executor = MigrationExecutor(connections[alias])
        ExportMigrationsForDatabase(alias, executor)

def ExportingCursorWrapper(cursor_class, alias, vendor):
    """Returns a CursorWrapper class that knows its database's alias and
    vendor name."""
    class CursorWrapper(cursor_class):
        """Extends the base CursorWrapper to count events."""
        def execute(self, *args, **kwargs):
            execute_total.labels(alias, vendor).inc()
            with ExceptionCounterByType(errors_total, extra_labels={'alias': alias, 'vendor': vendor}):
                return super(CursorWrapper, self).execute(*args, **kwargs)
        def executemany(self, query, param_list, *args, **kwargs):
            execute_total.labels(alias, vendor).inc(len(param_list))
            execute_many_total.labels(alias, vendor).inc(len(param_list))
            with ExceptionCounterByType(errors_total, extra_labels={'alias': alias, 'vendor': vendor}):
                return super(CursorWrapper, self).executemany(query, param_list, *args, **kwargs)
    return CursorWrapper

def ExportModelOperationsMixin(model_name):
    """Returns a mixin for models to export counters for lifecycle operations.

    Usage:
      class User(ExportModelOperationsMixin('user'), Model):
          ..."""
    model_inserts.labels(model_name)
    model_updates.labels(model_name)
    model_deletes.labels(model_name)
    class Mixin(object):
        def _do_insert(self, *args, **kwargs):
            model_inserts.labels(model_name).inc()
            return super(Mixin, self)._do_insert(*args, **kwargs)
        def _do_update(self, *args, **kwargs):
            model_updates.labels(model_name).inc()
            return super(Mixin, self)._do_update(*args, **kwargs)
        def delete(self, *args, **kwargs):
            model_deletes.labels(model_name).inc()
            return super(Mixin, self).delete(*args, **kwargs)
    return Mixin

def PowersOf(logbase, count, lower=0, include_zero=True):
    """Returns a list of count powers of logbase (from logbase**lower)."""
    if not include_zero:
        return [logbase ** i for i in range(lower, count + lower)]
    else:
        return [0] + [logbase ** i for i in range(lower, count + lower)]

