def _character_matches(name1, name2):
    """Yield the number of characters that match the beginning of each string.
    """
    if name1[0] == '*':
        for i in range(len(name2) + 1):
            yield (1, i)
    if name2[0] == '*':
        for i in range(len(name1) + 1):
            yield (i, 1)
    if name1[0] == name2[0]:
        yield (1, 1)

def wildcards_overlap(name1, name2):
    """Return true if two wildcard patterns can match the same string."""
    if not name1 and (not name2):
        return True
    if not name1 or not name2:
        return False
    for matched1, matched2 in _character_matches(name1, name2):
        if wildcards_overlap(name1[matched1:], name2[matched2:]):
            return True
    return False

def match_replace_regex(regex, src_namespace, dest_namespace):
    """Return the new mapped namespace if the src_namespace matches the
    regex."""
    match = regex.match(src_namespace)
    if match:
        return dest_namespace.replace('*', match.group(1))
    return None

def namespace_to_regex(namespace):
    """Create a RegexObject from a wildcard namespace."""
    db_name, coll_name = namespace.split('.', 1)
    db_regex = re.escape(db_name).replace('\\*', '([^.]*)')
    coll_regex = re.escape(coll_name).replace('\\*', '(.*)')
    return re.compile('\\A' + db_regex + '\\.' + coll_regex + '\\Z')

def str_cast(maybe_bytes, encoding='utf-8'):
    """Converts any bytes-like input to a string-like output, with respect to
    python version

    Parameters
    ----------
    maybe_bytes : if this is a bytes-like object, it will be converted to a string
    encoding  : str, default='utf-8'
        encoding to be used when decoding bytes"""
    if isinstance(maybe_bytes, bytes_):
        return maybe_bytes.decode(encoding)
    else:
        return maybe_bytes

def bytes_cast(maybe_str, encoding='utf-8'):
    """Converts any string-like input to a bytes-like output, with respect to
    python version

    Parameters
    ----------
    maybe_str : if this is a string-like object, it will be converted to bytes
    encoding  : str, default='utf-8'
        encoding to be used when encoding string"""
    if isinstance(maybe_str, unicode_):
        return maybe_str.encode(encoding)
    else:
        return maybe_str

def get_feature(name):
    """Get an instance of a ``Features`` class by ``name`` (str)."""
    if name == 'css':
        return CSSFeatures()
    elif name == 'kohlschuetter':
        return KohlschuetterFeatures()
    elif name == 'readability':
        return ReadabilityFeatures()
    elif name == 'weninger':
        return WeningerFeatures()
    elif name == 'clustered_weninger':
        return ClusteredWeningerFeatures()
    else:
        raise ValueError('invalid feature name: "{}"'.format(name))

def evaluation_metrics(predicted, actual, bow=True):
    """Input:
        predicted, actual = lists of the predicted and actual tokens
        bow: if true use bag of words assumption
    Returns:
        precision, recall, F1, Levenshtein distance"""
    if bow:
        p = set(predicted)
        a = set(actual)
        true_positive = 0
        for token in p:
            if token in a:
                true_positive += 1
    else:
        from collections import defaultdict
        act = defaultdict(lambda: 0)
        for token in actual:
            act[token] += 1
        true_positive = 0
        for token in predicted:
            if act[token] > 0:
                true_positive += 1
                act[token] -= 1
        p = predicted
        a = actual
    try:
        precision = true_positive / len(p)
    except ZeroDivisionError:
        precision = 0.0
    try:
        recall = true_positive / len(a)
    except ZeroDivisionError:
        recall = 0.0
    try:
        f1 = 2.0 * (precision * recall) / (precision + recall)
    except ZeroDivisionError:
        f1 = 0.0
    return (precision, recall, f1)

def get_and_union_features(features):
    """Get and combine features in a :class:`FeatureUnion`.

    Args:
        features (str or List[str], ``Features`` or List[``Features``], or List[Tuple[str, ``Features``]]):
            One or more features to be used to transform blocks into a matrix of
            numeric values. If more than one, a :class:`FeatureUnion` is
            automatically constructed. Example inputs::

                features = 'weninger'
                features = ['weninger', 'kohlschuetter']
                features = WeningerFeatures()
                features = [WeningerFeatures(), KohlschuetterFeatures()]
                features = [('weninger', WeningerFeatures()), ('kohlschuetter', KohlschuetterFeatures())]

    Returns:
        :class:`FeatureUnion` or ``Features``"""
    if not features:
        raise ValueError('invalid `features`: may not be null')
    if isinstance(features, (list, tuple)):
        if isinstance(features[0], tuple):
            return FeatureUnion(features)
        elif isinstance(features[0], string_):
            return FeatureUnion([(feature, get_feature(feature)) for feature in features])
        else:
            return make_union(*features)
    elif isinstance(features, string_):
        return get_feature(features)
    else:
        return features

