def _aicc(model_results, nobs):
    """Compute the corrected Akaike Information Criterion"""
    aic = model_results.aic
    df_model = model_results.df_model + 1
    return aic + 2.0 * df_model * (nobs / (nobs - df_model - 1.0) - 1.0)

def parse_function_call(expression):
    """Parse an expression looking for a function call
    return a dictionary with function name, args and kwargs
    e.g:
    {
        'func': 'display',
        'args': ['df'],
        'kwargs': {
            'aggregation': "'SUM'",
            'nostore_cw': "'1098'",
            'rowCount': "'500'"
        }
    }"""
    class Walker(ast.NodeVisitor):
        """ast NodeVisition helper class"""
        def __init__(self):
            self.results = {'func': None, 'args': [], 'kwargs': {}}
        def resolveName(self, node):
            if isinstance(node, ast.Name):
                self.results['func'] += node.id
            elif isinstance(node, ast.Attribute):
                self.resolveName(node.value)
                self.results['func'] += '.' + node.attr
        def visit_Call(self, node):
            """Visit the first call function"""
            if self.results['func'] is not None:
                return
            self.results['func'] = ''
            self.resolveName(node.func)
            self.results['args'] = [unparse(arg).strip() for arg in node.args]
            self.results['kwargs'] = {kw.arg: unparse(kw.value).strip().strip('\'"') for kw in node.keywords}
    walker = Walker()
    walker.visit(ast.parse(expression))
    return walker.results

def get_matches_lineno(code, fn_name):
    """Return a list of line number corresponding to the definition of function with the name fn_name"""
    class Walker(ast.NodeVisitor):
        def __init__(self):
            self._hits = set()
        def onvisit(fn):
            def wrap(self, node):
                fn(self, node)
                super(Walker, self).generic_visit(node)
            return wrap
        @onvisit
        def visit_FunctionDef(self, node):
            if node.name == fn_name:
                self._hits.add(node)
            return node
        @property
        def hits(self):
            return list(sorted([n.lineno + 1 for n in self._hits]))
    walker = Walker()
    walker.visit(ast.parse(code))
    return walker.hits

def get_the_board(layout=BOARDS['arduino'], base_dir='/dev/', identifier='tty.usbserial'):
    """Helper function to get the one and only board connected to the computer
    running this. It assumes a normal arduino layout, but this can be
    overriden by passing a different layout dict as the ``layout`` parameter.
    ``base_dir`` and ``identifier`` are overridable as well. It will raise an
    IOError if it can't find a board, on a serial, or if it finds more than
    one."""
    from .pyfirmata import Board
    boards = []
    for device in os.listdir(base_dir):
        if device.startswith(identifier):
            try:
                board = Board(os.path.join(base_dir, device), layout)
            except serial.SerialException:
                pass
            else:
                boards.append(board)
    if len(boards) == 0:
        raise IOError('No boards found in {0} with identifier {1}'.format(base_dir, identifier))
    elif len(boards) > 1:
        raise IOError('More than one board found!')
    return boards[0]

def from_two_bytes(bytes):
    """Return an integer from two 7 bit bytes."""
    lsb, msb = bytes
    try:
        return msb << 7 | lsb
    except TypeError:
        try:
            lsb = ord(lsb)
        except TypeError:
            pass
        try:
            msb = ord(msb)
        except TypeError:
            pass
        return msb << 7 | lsb

def two_byte_iter_to_str(bytes):
    """Return a string made from a list of two byte chars."""
    bytes = list(bytes)
    chars = bytearray()
    while bytes:
        lsb = bytes.pop(0)
        try:
            msb = bytes.pop(0)
        except IndexError:
            msb = 0
        chars.append(from_two_bytes([lsb, msb]))
    return chars.decode()

def break_to_bytes(value):
    """Breaks a value into values of less than 255 that form value when multiplied.
    (Or almost do so with primes)
    Returns a tuple"""
    if value < 256:
        return (value,)
    c = 256
    least = (0, 255)
    for i in range(254):
        c -= 1
        rest = value % c
        if rest == 0 and value / c < 256:
            return (c, int(value / c))
        elif rest == 0 and value / c > 255:
            parts = list(break_to_bytes(value / c))
            parts.insert(0, c)
            return tuple(parts)
        elif rest < least[1]:
            least = (c, rest)
    return (c, int(value / c))

def pin_list_to_board_dict(pinlist):
    """Capability Response codes:
        INPUT:  0, 1
        OUTPUT: 1, 1
        ANALOG: 2, 10
        PWM:    3, 8
        SERV0:  4, 14
        I2C:    6, 1"""
    board_dict = {'digital': [], 'analog': [], 'pwm': [], 'servo': [], 'disabled': []}
    for i, pin in enumerate(pinlist):
        pin.pop()
        if not pin:
            board_dict['disabled'] += [i]
            board_dict['digital'] += [i]
            continue
        for j, _ in enumerate(pin):
            if j % 2 == 0:
                if pin[j:j + 4] == [0, 1, 1, 1]:
                    board_dict['digital'] += [i]
                if pin[j:j + 2] == [2, 10]:
                    board_dict['analog'] += [i]
                if pin[j:j + 2] == [3, 8]:
                    board_dict['pwm'] += [i]
                if pin[j:j + 2] == [4, 14]:
                    board_dict['servo'] += [i]
                if pin[j:j + 2] == [6, 1]:
                    pass
    diff = set(board_dict['digital']) - set(board_dict['analog'])
    board_dict['analog'] = [n for n, _ in enumerate(board_dict['analog'])]
    board_dict['digital'] = [n for n, _ in enumerate(diff)]
    board_dict['servo'] = board_dict['digital']
    board_dict = dict([(key, tuple(value)) for key, value in board_dict.items()])
    return board_dict

