        if result:
            yield (name, result)

def get_language(query: str) -> str:
    """Tries to work out the highlight.js language of a given file name or
    shebang. Returns an empty string if none match."""
    query = query.lower()
    for language in LANGUAGES:
        if query.endswith(language):
            return language
    return ''

def resolve_extensions(bot: commands.Bot, name: str) -> list:
    """Tries to resolve extension queries into a list of extension names."""
    if name.endswith('.*'):
        module_parts = name[:-2].split('.')
        path = pathlib.Path(module_parts.pop(0))
        for part in module_parts:
            path = path / part
        return find_extensions_in(path)
    if name == '~':
        return list(bot.extensions.keys())
    return [name]

def package_version(package_name: str) -> typing.Optional[str]:
    """Returns package version as a string, or None if it couldn't be found."""
    try:
        return pkg_resources.get_distribution(package_name).version
    except (pkg_resources.DistributionNotFound, AttributeError):
        return None

def safe_format(format_string, *args, **kwargs):
    """Helper: formats string with any combination of bytestrings/unicode
    strings without raising exceptions"""
    try:
        if not args and (not kwargs):
            return format_string
        else:
            return format_string.format(*args, **kwargs)
    except (UnicodeEncodeError, UnicodeDecodeError):
        format_string = to_utf8(format_string)
        args = [to_utf8(p) for p in args]
        kwargs = {k: to_utf8(v) for k, v in six.iteritems(kwargs)}
        return format_string.format(*args, **kwargs)
    except:
        return u''

def detect_encoding(string):
    """Tries to detect the encoding of the passed string.

    Defaults to UTF-8."""
    assert isinstance(string, bytes)
    try:
        detected = chardet.detect(string)
        if detected:
            return detected.get('encoding') or 'utf-8'
    except Exception as e:
        pass
    return 'utf-8'

def quick_detect_encoding(string):
    """Tries to detect the encoding of the passed string.

    Uses cchardet. Fallbacks to detect_encoding."""
    assert isinstance(string, bytes)
    try:
        detected = cchardet.detect(string)
        if detected:
            return detected.get('encoding') or detect_encoding(string)
    except Exception as e:
        pass
    return detect_encoding(string)

def to_utf8(str_or_unicode):
    """Safely returns a UTF-8 version of a given string
    >>> utils.to_utf8(u'hi')
        'hi'"""
    if not isinstance(str_or_unicode, six.text_type):
        return str_or_unicode.encode('utf-8', 'ignore')
    return str(str_or_unicode)

def html_fromstring(s):
    """Parse html tree from string. Return None if the string can't be parsed.
    """
    if isinstance(s, six.text_type):
        s = s.encode('utf8')
    try:
        if html_too_big(s):
            return None
        return html5parser.fromstring(s, parser=_html5lib_parser())
    except Exception:
        pass

def html_document_fromstring(s):
    """Parse html tree from string. Return None if the string can't be parsed.
    """
    if isinstance(s, six.text_type):
        s = s.encode('utf8')
    try:
        if html_too_big(s):
            return None
        return html5parser.document_fromstring(s, parser=_html5lib_parser())
    except Exception:
