def stops(freq, interval=1, count=None, wkst=None, bysetpos=None, bymonth=None, bymonthday=None, byyearday=None, byeaster=None, byweekno=None, byweekday=None, byhour=None, byminute=None, bysecond=None, timezone='UTC', start=None, stop=None):
    """This will create a list of delorean objects the apply to
    setting possed in."""
    if all([start is None or is_datetime_naive(start), stop is None or is_datetime_naive(stop)]):
        pass
    else:
        raise DeloreanInvalidDatetime('Provide a naive datetime object')
    if start is None:
        start = datetime_timezone(timezone)
    for dt in rrule(freq, interval=interval, count=count, wkst=wkst, bysetpos=bysetpos, bymonth=bymonth, bymonthday=bymonthday, byyearday=byyearday, byeaster=byeaster, byweekno=byweekno, byweekday=byweekday, byhour=byhour, byminute=byminute, bysecond=bysecond, until=stop, dtstart=start):
        dt = dt.replace(tzinfo=None)
        d = Delorean(datetime=dt, timezone=timezone)
        yield d

def _move_datetime(dt, direction, delta):
    """Move datetime given delta by given direction"""
    if direction == 'next':
        dt = dt + delta
    elif direction == 'last':
        dt = dt - delta
    else:
        pass
    return dt

def move_datetime_month(dt, direction, num_shifts):
    """Move datetime 1 month in the chosen direction.
    unit is a no-op, to keep the API the same as the day case"""
    delta = relativedelta(months=+num_shifts)
    return _move_datetime(dt, direction, delta)

def move_datetime_week(dt, direction, num_shifts):
    """Move datetime 1 week in the chosen direction.
    unit is a no-op, to keep the API the same as the day case"""
    delta = relativedelta(weeks=+num_shifts)
    return _move_datetime(dt, direction, delta)

def move_datetime_year(dt, direction, num_shifts):
    """Move datetime 1 year in the chosen direction.
    unit is a no-op, to keep the API the same as the day case"""
    delta = relativedelta(years=+num_shifts)
    return _move_datetime(dt, direction, delta)

def localize(dt, tz):
    """Given a naive datetime object this method will return a localized
    datetime object"""
    if not isinstance(tz, tzinfo):
        tz = pytz.timezone(tz)
    return tz.localize(dt)

def mask_phone_number(number):
    """Masks a phone number, only first 3 and last 2 digits visible.

    Examples:

    * `+31 * ******58`

    :param number: str or phonenumber object
    :return: str"""
    if isinstance(number, phonenumbers.PhoneNumber):
        number = format_phone_number(number)
    return phone_mask.sub('*', number)

def format_phone_number(number):
    """Formats a phone number in international notation.
    :param number: str or phonenumber object
    :return: str"""
    if not isinstance(number, phonenumbers.PhoneNumber):
