def get_redirect_url(request):
    """Redirects to referring page, or CAS_REDIRECT_URL if no referrer is
    set."""
    next_ = request.GET.get(REDIRECT_FIELD_NAME)
    if not next_:
        redirect_url = resolve_url(django_settings.CAS_REDIRECT_URL)
        if django_settings.CAS_IGNORE_REFERER:
            next_ = redirect_url
        else:
            next_ = request.META.get('HTTP_REFERER', redirect_url)
        prefix = urllib_parse.urlunparse((get_protocol(request), request.get_host(), '', '', '', ''))
        if next_.startswith(prefix):
            next_ = next_[len(prefix):]
    return next_

def get_service_url(request, redirect_to=None):
    """Generates application django service URL for CAS"""
    if hasattr(django_settings, 'CAS_ROOT_PROXIED_AS'):
        service = django_settings.CAS_ROOT_PROXIED_AS + request.path
    else:
        protocol = get_protocol(request)
        host = request.get_host()
        service = urllib_parse.urlunparse((protocol, host, request.path, '', '', ''))
    if not django_settings.CAS_STORE_NEXT:
        if '?' in service:
            service += '&'
        else:
            service += '?'
        service += urllib_parse.urlencode({REDIRECT_FIELD_NAME: redirect_to or get_redirect_url(request)})
    return service

def get_cas_client(service_url=None, request=None):
    """initializes the CASClient according to
    the CAS_* settigs"""
    server_url = django_settings.CAS_SERVER_URL
    if server_url and request and server_url.startswith('/'):
        scheme = request.META.get('X-Forwarded-Proto', request.scheme)
        server_url = scheme + '://' + request.META['HTTP_HOST'] + server_url
    if not django_settings.CAS_VERIFY_SSL_CERTIFICATE:
        warnings.warn('`CAS_VERIFY_SSL_CERTIFICATE` is disabled, meaning that SSL certificates are not being verified by a certificate authority. This can expose your system to various attacks and should _never_ be disabled in a production environment.')
    return CASClient(service_url=service_url, version=django_settings.CAS_VERSION, server_url=server_url, extra_login_params=django_settings.CAS_EXTRA_LOGIN_PARAMS, renew=django_settings.CAS_RENEW, username_attribute=django_settings.CAS_USERNAME_ATTRIBUTE, proxy_callback=django_settings.CAS_PROXY_CALLBACK, verify_ssl_certificate=django_settings.CAS_VERIFY_SSL_CERTIFICATE)

