def scrypt(password, salt='', n=2 ** 20, r=8, p=1, maxmem=2 ** 25, dklen=64):
    """Derive a cryptographic key using the scrypt KDF.

    Implements the same signature as the ``hashlib.scrypt`` implemented
    in cpython version 3.6"""
    return nacl.bindings.crypto_pwhash_scryptsalsa208sha256_ll(password, salt, n, r, p, maxmem=maxmem, dklen=dklen)

def verify(password_hash, password):
    """Takes a modular crypt encoded stored password hash derived using one
    of the algorithms supported by `libsodium` and checks if the user provided
    password will hash to the same string when using the parameters saved
    in the stored hash"""
    if password_hash.startswith(argon2id.STRPREFIX):
        return argon2id.verify(password_hash, password)
    elif password_hash.startswith(argon2i.STRPREFIX):
        return argon2id.verify(password_hash, password)
    elif password_hash.startswith(scrypt.STRPREFIX):
        return scrypt.verify(password_hash, password)
    else:
        raise CryptPrefixError('given password_hash is not in a supported format')

def nacl_bindings_pick_scrypt_params(opslimit, memlimit):
    """Python implementation of libsodium's pickparams"""
    if opslimit < 32768:
        opslimit = 32768
    r = 8
    if opslimit < memlimit // 32:
        p = 1
        maxn = opslimit // (4 * r)
        for n_log2 in range(1, 63):
            if 2 ** n_log2 > maxn // 2:
                break
    else:
        maxn = memlimit // (r * 128)
        for n_log2 in range(1, 63):
            if 2 ** n_log2 > maxn // 2:
                break
        maxrp = opslimit // 4 // 2 ** n_log2
        if maxrp > 1073741823:
            maxrp = 1073741823
        p = maxrp // r
    return (n_log2, r, p)

def _get_param_types_maxint(params):
    """Returns characteristics of parameters
    :param params: dictionary of pairs
        it must have parameter_name:list of possible values:
        params = {"kernel": ["rbf"],
                 "C"     : [1,2,3,4,5,6,7,8],
                 "gamma" : np.logspace(-9, 9, num=25, base=10)}
    :return: name_values pairs - list of (name,possible_values) tuples for each parameter
             types - list of types for each parameter
             maxints - list of maximum integer for each particular gene in chromosome"""
    name_values = list(params.items())
    types = []
    for _, possible_values in name_values:
        if isinstance(possible_values[0], float):
            types.append(param_types.Numerical)
        else:
            types.append(param_types.Categorical)
    maxints = [len(possible_values) - 1 for _, possible_values in name_values]
    return (name_values, types, maxints)

def _decode_jwt_segment(encoded_section):
    """Decodes a single JWT segment."""
    section_bytes = _helpers.padded_urlsafe_b64decode(encoded_section)
    try:
        return json.loads(section_bytes.decode('utf-8'))
    except ValueError as caught_exc:
        new_exc = ValueError("Can't parse segment: {0}".format(section_bytes))
        six.raise_from(new_exc, caught_exc)

def _get_gcloud_sdk_credentials():
    """Gets the credentials and project ID from the Cloud SDK."""
    from google.auth import _cloud_sdk
    credentials_filename = _cloud_sdk.get_application_default_credentials_path()
    if not os.path.isfile(credentials_filename):
        return (None, None)
    credentials, project_id = _load_credentials_from_file(credentials_filename)
    if not project_id:
        project_id = _cloud_sdk.get_project_id()
