def _get_gae_credentials():
    """Gets Google App Engine App Identity credentials and project ID."""
    try:
        import google.auth.app_engine as app_engine
    except ImportError:
        return (None, None)
    try:
        credentials = app_engine.Credentials()
        project_id = app_engine.get_project_id()
        return (credentials, project_id)
    except EnvironmentError:
        return (None, None)

def _get_gce_credentials(request=None):
    """Gets credentials and project ID from the GCE Metadata Service."""
    try:
        from google.auth import compute_engine
        from google.auth.compute_engine import _metadata
    except ImportError:
        return (None, None)
    if request is None:
        request = google.auth.transport._http_client.Request()
    if _metadata.ping(request=request):
        try:
            project_id = _metadata.get_project_id(request=request)
        except exceptions.TransportError:
            project_id = None
        return (compute_engine.Credentials(), project_id)
    else:
        return (None, None)

def _parse_expiry(response_data):
    """Parses the expiry field from a response into a datetime.

    Args:
        response_data (Mapping): The JSON-parsed response data.

    Returns:
        Optional[datetime]: The expiration or ``None`` if no expiration was
            specified."""
    expires_in = response_data.get('expires_in', None)
    if expires_in is not None:
        return _helpers.utcnow() + datetime.timedelta(seconds=expires_in)
    else:
        return None

def get_config_path():
    """Returns the absolute path the the Cloud SDK's configuration directory.

    Returns:
        str: The Cloud SDK config path."""
    try:
        return os.environ[environment_vars.CLOUD_SDK_CONFIG_DIR]
    except KeyError:
        pass
    if os.name != 'nt':
        return os.path.join(os.path.expanduser('~'), '.config', _CONFIG_DIRECTORY)
    else:
        try:
            return os.path.join(os.environ[_WINDOWS_CONFIG_ROOT_ENV_VAR], _CONFIG_DIRECTORY)
        except KeyError:
            drive = os.environ.get('SystemDrive', 'C:')
            return os.path.join(drive, '\\', _CONFIG_DIRECTORY)

def get_project_id():
    """Gets the project ID from the Cloud SDK.

    Returns:
        Optional[str]: The project ID."""
    if os.name == 'nt':
        command = _CLOUD_SDK_WINDOWS_COMMAND
    else:
        command = _CLOUD_SDK_POSIX_COMMAND
    try:
        output = subprocess.check_output((command,) + _CLOUD_SDK_CONFIG_COMMAND, stderr=subprocess.STDOUT)
    except (subprocess.CalledProcessError, OSError, IOError):
        return None
    try:
        configuration = json.loads(output.decode('utf-8'))
    except ValueError:
        return None
    try:
        return configuration['configuration']['properties']['core']['project']
    except KeyError:
        return None

