def scan_directory_for_bot_configs(root_dir) -> Set[BotConfigBundle]:
    """Recursively scans a directory for all valid bot configs.
    :param root_dir: Directory to scan.
    :return: The set of bot configs that were found."""
    configs = set()
    for filename in glob.iglob(os.path.join(root_dir, '**/*.cfg'), recursive=True):
        try:
            bundle = get_bot_config_bundle(filename)
            configs.add(bundle)
        except (NoSectionError, MissingSectionHeaderError, NoOptionError, AttributeError, ParsingError, FileNotFoundError):
            pass
    return configs

def _wait_until_good_ticks(game_interface: GameInterface, required_new_ticks: int=3):
    """Blocks until we're getting new packets, indicating that the match is ready."""
    rate_limit = rate_limiter.RateLimiter(120)
    last_tick_game_time = None
    packet = GameTickPacket()
    seen_times = 0
    while seen_times < required_new_ticks:
        game_interface.update_live_data_packet(packet)
        def is_good_tick():
            if packet.game_info.seconds_elapsed == last_tick_game_time:
                return False
            if not packet.game_info.is_round_active:
                return False
            if any((car.is_demolished for car in packet.game_cars)):
                return False
            return True
        if is_good_tick():
            seen_times += 1
        last_tick_game_time = packet.game_info.seconds_elapsed
        rate_limit.acquire()

def _setup_exercise(game_interface: GameInterface, ex: Exercise, seed: int) -> Optional[Result]:
    """Set the game state.
    Only returns a result if there was an error in ex.setup()"""
    rng = random.Random()
    rng.seed(seed)
    try:
        game_state = ex.setup(rng)
    except Exception as e:
        return Result(ex, seed, FailDueToExerciseException(e, traceback.format_exc()))
    game_interface.set_game_state(game_state)

def register_for_quick_chat(queue_holder, called_func, quit_event):
    """Registers a function to be called anytime this queue gets a quick chat.
    :param queue_holder:  This holds the queues for the bots
    :param called_func: This is the function that is called when a quick chat is received
    :param quit_event: This event will be set when rlbot is trying to shut down
    :return: The newly created thread."""
    def threaded_func(chat_queue, called_func, quit_event):
        while not quit_event.is_set():
            try:
                next_message = chat_queue.get(timeout=0.1)
                index, team, chat = next_message
                called_func(index, team, chat)
            except queue.Empty:
                pass
            except EOFError as e:
                get_logger('chats').debug('quick_chat queue terminated. %s', e)
                return
    thread = Thread(target=threaded_func, args=(queue_holder['input'], called_func, quit_event), daemon=True)
    thread.start()

def ensureUtf(s, encoding='utf8'):
    """Converts input to unicode if necessary.
    If `s` is bytes, it will be decoded using the `encoding` parameters.
    This function is used for preprocessing /source/ and /filename/ arguments
    to the builtin function `compile`."""
    if type(s) == bytes:
        return s.decode(encoding, 'ignore')
    else:
        return s

def convert_to_dict(obj):
    """Converts a StripeObject back to a regular dict.

    Nested StripeObjects are also converted back to regular dicts.

    :param obj: The StripeObject to convert.

    :returns: The StripeObject as a dict."""
    if isinstance(obj, list):
        return [convert_to_dict(i) for i in obj]
    elif isinstance(obj, dict):
        return {k: convert_to_dict(v) for k, v in six.iteritems(obj)}
    else:
        return obj

def Browser(driver_name='firefox', *args, **kwargs):
    """Returns a driver instance for the given name.

    When working with ``firefox``, it's possible to provide a profile name
    and a list of extensions.

    If you don't provide any driver_name, then ``firefox`` will be used.

    If there is no driver registered with the provided ``driver_name``, this
    function will raise a :class:`splinter.exceptions.DriverNotFoundError`
    exception."""
    try:
        driver = _DRIVERS[driver_name]
    except KeyError:
        raise DriverNotFoundError('No driver for %s' % driver_name)
    return driver(*args, **kwargs)

def force_unicode(value):
    """Forces a bytestring to become a Unicode string."""
    if IS_PY3:
        if isinstance(value, bytes):
            value = value.decode('utf-8', errors='replace')
        elif not isinstance(value, str):
            value = str(value)
    elif isinstance(value, str):
        value = value.decode('utf-8', 'replace')
    elif not isinstance(value, basestring):
        value = unicode(value)
    return value

def force_bytes(value):
    """Forces a Unicode string to become a bytestring."""
    if IS_PY3:
        if isinstance(value, str):
            value = value.encode('utf-8', 'backslashreplace')
    elif isinstance(value, unicode):
        value = value.encode('utf-8')
    return value

def unescape_html(text):
    """Removes HTML or XML character references and entities from a text string.

    @param text The HTML (or XML) source text.
    @return The plain text, as a Unicode string, if necessary.

    Source: http://effbot.org/zone/re-sub.htm#unescape-html"""
    def fixup(m):
        text = m.group(0)
        if text[:2] == '&#':
            try:
                if text[:3] == '&#x':
                    return unicode_char(int(text[3:-1], 16))
                else:
                    return unicode_char(int(text[2:-1]))
            except ValueError:
                pass
        else:
            try:
                text = unicode_char(htmlentities.name2codepoint[text[1:-1]])
            except KeyError:
                pass
        return text
    return re.sub('&#?\\w+;', fixup, text)

def safe_urlencode(params, doseq=0):
    """UTF-8-safe version of safe_urlencode

    The stdlib safe_urlencode prior to Python 3.x chokes on UTF-8 values
    which can't fail down to ascii."""
    if IS_PY3:
        return urlencode(params, doseq)
    if hasattr(params, 'items'):
        params = params.items()
    new_params = []
    for k, v in params:
        k = k.encode('utf-8')
        if isinstance(v, (list, tuple)):
            new_params.append((k, [force_bytes(i) for i in v]))
        else:
            new_params.append((k, force_bytes(v)))
    return urlencode(new_params, doseq)

def rule_variable(field_type, label=None, options=None):
    """Decorator to make a function into a rule variable
    """
    options = options or []
    def wrapper(func):
        if not (type(field_type) == type and issubclass(field_type, BaseType)):
            raise AssertionError('{0} is not instance of BaseType in rule_variable field_type'.format(field_type))
        func.field_type = field_type
        func.is_rule_variable = True
        func.label = label or fn_name_to_pretty_label(func.__name__)
        func.options = options
        return func
    return wrapper

def _validate_action_parameters(func, params):
    """Verifies that the parameters specified are actual parameters for the
    function `func`, and that the field types are FIELD_* types in fields."""
    if params is not None:
        valid_fields = [getattr(fields, f) for f in dir(fields) if f.startswith('FIELD_')]
        for param in params:
            param_name, field_type = (param['name'], param['fieldType'])
            if param_name not in func.__code__.co_varnames:
                raise AssertionError('Unknown parameter name {0} specified for action {1}'.format(param_name, func.__name__))
            if field_type not in valid_fields:
                raise AssertionError('Unknown field type {0} specified for action {1} param {2}'.format(field_type, func.__name__, param_name))

def rule_action(label=None, params=None):
    """Decorator to make a function into a rule action
    """
    def wrapper(func):
        params_ = params
        if isinstance(params, dict):
            params_ = [dict(label=fn_name_to_pretty_label(name), name=name, fieldType=field_type) for name, field_type in params.items()]
        _validate_action_parameters(func, params_)
        func.is_rule_action = True
        func.label = label or fn_name_to_pretty_label(func.__name__)
        func.params = params_
        return func
    return wrapper

def _get_variable_value(defined_variables, name):
    """Call the function provided on the defined_variables object with the
    given name (raise exception if that doesn't exist) and casts it to the
    specified type.

    Returns an instance of operators.BaseType"""
    def fallback(*args, **kwargs):
        raise AssertionError('Variable {0} is not defined in class {1}'.format(name, defined_variables.__class__.__name__))
    method = getattr(defined_variables, name, fallback)
    val = method()
    return method.field_type(val)

def _do_operator_comparison(operator_type, operator_name, comparison_value):
    """Finds the method on the given operator_type and compares it to the
    given comparison_value.

    operator_type should be an instance of operators.BaseType
    comparison_value is whatever python type to compare to
    returns a bool"""
    def fallback(*args, **kwargs):
        raise AssertionError('Operator {0} does not exist for type {1}'.format(operator_name, operator_type.__class__.__name__))
    method = getattr(operator_type, operator_name, fallback)
    if getattr(method, 'input_type', '') == FIELD_NO_INPUT:
        return method()
    return method(comparison_value)

def captcha_refresh(request):
