def default():
    """Configures the default connection to localhost, using the driver defaults
    (except for row_factory)"""
    try:
        conn = get_connection()
        if conn.session:
            log.warning('configuring new default connection for cqlengine when one was already set')
    except:
        pass
    register_connection('default', hosts=None, default=True)
    log.debug('cqlengine connection initialized with default session to localhost')

def set_session(s):
    """Configures the default connection with a preexisting :class:`cassandra.cluster.Session`

    Note: the mapper presently requires a Session :attr:`~.row_factory` set to ``dict_factory``.
    This may be relaxed in the future"""
    try:
        conn = get_connection()
    except CQLEngineException:
        register_connection('default', session=s, default=True)
        conn = get_connection()
    if conn.session:
        log.warning('configuring new default connection for cqlengine when one was already set')
    if s.row_factory is not dict_factory:
        raise CQLEngineException("Failed to initialize: 'Session.row_factory' must be 'dict_factory'.")
    conn.session = s
    conn.cluster = s.cluster
    if conn.session.keyspace:
        from cassandra.cqlengine import models
        models.DEFAULT_KEYSPACE = conn.session.keyspace
    conn.setup_session()
    log.debug('cqlengine default connection initialized with %s', s)

def _future_completed(future):
    """Helper for run_in_executor()"""
    exc = future.exception()
    if exc:
        log.debug('Failed to run task on executor', exc_info=exc)

def run_in_executor(f):
    """A decorator to run the given method in the ThreadPoolExecutor."""
    @wraps(f)
    def new_f(self, *args, **kwargs):
        if self.is_shutdown:
            return
        try:
            future = self.executor.submit(f, self, *args, **kwargs)
            future.add_done_callback(_future_completed)
        except Exception:
            log.exception('Failed to submit task to executor')
    return new_f

def _addrinfo_or_none(contact_point, port):
    """A helper function that wraps socket.getaddrinfo and returns None
    when it fails to, e.g. resolve one of the hostnames. Used to address
    PYTHON-895."""
    try:
        return socket.getaddrinfo(contact_point, port, socket.AF_UNSPEC, socket.SOCK_STREAM)
    except socket.gaierror:
        log.debug('Could not resolve hostname "{}" with port {}'.format(contact_point, port))
        return None

def get_client_ip_address(request: HttpRequest) -> str:
    """Get client IP address as configured by the user.

    The django-ipware package is used for address resolution
    and parameters can be configured in the Axes package."""
    client_ip_address, _ = ipware.ip2.get_client_ip(request, proxy_order=settings.AXES_PROXY_ORDER, proxy_count=settings.AXES_PROXY_COUNT, proxy_trusted_ips=settings.AXES_PROXY_TRUSTED_IPS, request_header_order=settings.AXES_META_PRECEDENCE_ORDER)
    return str(ip_address(client_ip_address))

def get_client_parameters(username: str, ip_address: str, user_agent: str) -> dict:
    """Get query parameters for filtering AccessAttempt queryset.

    This method returns a dict that guarantees iteration order for keys and values,
    and can so be used in e.g. the generation of hash keys or other deterministic functions."""
    filter_kwargs = dict()
    if settings.AXES_ONLY_USER_FAILURES:
        filter_kwargs['username'] = username
    else:
        if settings.AXES_LOCK_OUT_BY_COMBINATION_USER_AND_IP:
            filter_kwargs['username'] = username
            filter_kwargs['ip_address'] = ip_address
        else:
            filter_kwargs['ip_address'] = ip_address
        if settings.AXES_USE_USER_AGENT:
            filter_kwargs['user_agent'] = user_agent
    return filter_kwargs

def get_client_str(username: str, ip_address: str, user_agent: str, path_info: str) -> str:
    """Get a readable string that can be used in e.g. logging to distinguish client requests.

    Example log format would be ``{username: "example", ip_address: "127.0.0.1", path_info: "/example/"}``"""
    client_dict = dict()
    if settings.AXES_VERBOSE:
        client_dict['username'] = username
        client_dict['ip_address'] = ip_address
        client_dict['user_agent'] = user_agent
    else:
        client_dict = get_client_parameters(username, ip_address, user_agent)
    if path_info and isinstance(path_info, (tuple, list)):
        path_info = path_info[0]
    client_dict['path_info'] = path_info
    template = ', '.join((f'{key}: "{value}"' for key, value in client_dict.items()))
    template = '{{' + template + '}}'
    return template.format(client_dict)

def is_client_ip_address_whitelisted(request: AxesHttpRequest):
