def download_file(url, path, session=None, params=None):
    """Download an individual file."""
    if url[0:2] == '//':
        url = 'https://' + url[2:]
    tmp_path = path + '.tmp'
    if session and params:
        r = session.get(url, params=params, stream=True)
    elif session and (not params):
        r = session.get(url, stream=True)
    else:
        r = requests.get(url, stream=True)
    with open(tmp_path, 'wb') as f:
        total_length = int(r.headers.get('content-length', 0))
        for chunk in progress.bar(r.iter_content(chunk_size=1024), expected_size=total_length / 1024 + 1):
            if chunk:
                f.write(chunk)
                f.flush()
    os.rename(tmp_path, path)
    return path

def fileish_open(fileish, mode):
    """Convert file-ish object to BytesIO like object.
    :param fileish: the file-ihs object (str, BytesIO, bytes, file contents)
    :param str mode: mode for the open function.
    :rtype: BytesIO"""
    if mode is not None and any((m in mode for m in ['+', 'w', 'a', 'x'])):
        attr = 'write'
    else:
        attr = 'read'
    if hasattr(fileish, attr) and hasattr(fileish, 'seek'):
        return fileish
    elif isinstance(fileish, str):
        try:
            return open(fileish, mode)
        except TypeError:
            return io.BytesIO(fileish)
    else:
        return io.BytesIO(fileish)

def clock(seg, seconds):
    """Display current time on device."""
    interval = 0.5
    for i in range(int(seconds / interval)):
        now = datetime.now()
        seg.text = now.strftime('%H-%M-%S')
        if i % 2 == 0:
            seg.text = now.strftime('%H-%M-%S')
        else:
            seg.text = now.strftime('%H %M %S')
        time.sleep(interval)

def mix_wave(src, dst):
    """Mix two wave body into one."""
    if len(src) > len(dst):
        dst, src = (src, dst)
    for i, sv in enumerate(src):
        dv = dst[i]
        if sv < 128 and dv < 128:
            dst[i] = int(sv * dv / 128)
        else:
            dst[i] = int(2 * (sv + dv) - sv * dv / 128 - 256)
    return dst

