def delimiter_groups(line, begin_delim=begin_delim, end_delim=end_delim):
    """Split a line into alternating groups.
    The first group cannot have a line feed inserted,
    the next one can, etc."""
    text = []
    line = iter(line)
    while True:
        for item in line:
            text.append(item)
            if item in begin_delim:
                break
        if not text:
            break
        yield text
        level = 0
        text = []
        for item in line:
            if item in begin_delim:
                level += 1
            elif item in end_delim:
                level -= 1
                if level < 0:
                    yield text
                    text = [item]
                    break
            text.append(item)
        else:
            assert not text, text
            break

def add_parens(line, maxline, indent, statements=statements, count=count):
    """Attempt to add parentheses around the line
    in order to make it splittable."""
    if line[0] in statements:
        index = 1
        if not line[0].endswith(' '):
            index = 2
            assert line[1] == ' '
        line.insert(index, '(')
        if line[-1] == ':':
            line.insert(-1, ')')
        else:
            line.append(')')
    groups = list(get_assign_groups(line))
    if len(groups) == 1:
        return line
    counts = list((count(x) for x in groups))
    didwrap = False
    if sum(counts[:-1]) >= maxline - indent - 4:
        for group in groups[:-1]:
            didwrap = False
            if len(group) > 1:
                group.insert(0, '(')
                group.insert(-1, ')')
                didwrap = True
    if not didwrap or counts[-1] > maxline - indent - 10:
        groups[-1].insert(0, '(')
        groups[-1].append(')')
    return [item for group in groups for item in group]

def get_assign_groups(line, ops=ops):
    """Split a line into groups by assignment (including
    augmented assignment)"""
    group = []
    for item in line:
        group.append(item)
        if item in ops:
            yield group
            group = []
    yield group

def _prep_triple_quotes(s, mysplit=mysplit, replacements=replacements):
    """Split the string up and force-feed some replacements
    to make sure it will round-trip OK"""
    s = mysplit(s)
    s[1::2] = (replacements[x] for x in s[1::2])
    return ''.join(s)

def pretty_string(s, embedded, current_line, uni_lit=False, min_trip_str=20, max_line=100):
    """There are a lot of reasons why we might not want to or
    be able to return a triple-quoted string.  We can always
    punt back to the default normal string."""
    default = repr(s)
    if isinstance(s, special_unicode) or not isinstance(s, basestring):
        return default
    if uni_lit and isinstance(s, bytes):
        return 'b' + default
    len_s = len(default)
    if current_line.strip():
        len_current = len(current_line)
        second_line_start = s.find('\n') + 1
        if embedded > 1 and (not second_line_start):
            return default
        if len_s < min_trip_str:
            return default
        line_indent = len_current - len(current_line.lstrip())
        if embedded and (not second_line_start):
            return default
        total_len = len_current + len_s
        if total_len < max_line and (not _properly_indented(s, line_indent)):
            return default
    fancy = string_triplequote_repr(s)
    try:
        if eval(fancy) == s and '\r' not in fancy:
            return fancy
    except:
        pass
    return default

def iter_node(node, name='', unknown=None, list=list, getattr=getattr, isinstance=isinstance, enumerate=enumerate, missing=NonExistent):
    """Iterates over an object:

    - If the object has a _fields attribute,
      it gets attributes in the order of this
      and returns name, value pairs.

    - Otherwise, if the object is a list instance,
      it returns name, value pairs for each item
      in the list, where the name is passed into
      this function (defaults to blank).

    - Can update an unknown set with information about
      attributes that do not exist in fields."""
    fields = getattr(node, '_fields', None)
    if fields is not None:
        for name in fields:
            value = getattr(node, name, missing)
            if value is not missing:
                yield (value, name)
        if unknown is not None:
            unknown.update(set(vars(node)) - set(fields))
    elif isinstance(node, list):
        for value in node:
            yield (value, name)

def dump_tree(node, name=None, initial_indent='', indentation='    ', maxline=120, maxmerged=80, iter_node=iter_node, special=ast.AST, list=list, isinstance=isinstance, type=type, len=len):
    """Dumps an AST or similar structure:

    - Pretty-prints with indentation
    - Doesn't print line/column/ctx info"""
    def dump(node, name=None, indent=''):
        level = indent + indentation
        name = name and name + '=' or ''
        values = list(iter_node(node))
        if isinstance(node, list):
            prefix, suffix = ('%s[' % name, ']')
        elif values:
            prefix, suffix = ('%s%s(' % (name, type(node).__name__), ')')
        elif isinstance(node, special):
            prefix, suffix = (name + type(node).__name__, '')
        else:
            return '%s%s' % (name, repr(node))
        node = [dump(a, b, level) for a, b in values if b != 'ctx']
        oneline = '%s%s%s' % (prefix, ', '.join(node), suffix)
        if len(oneline) + len(indent) < maxline:
            return '%s' % oneline
        if node and len(prefix) + len(node[0]) < maxmerged:
            prefix = '%s%s,' % (prefix, node.pop(0))
        node = (',\n%s' % level).join(node).lstrip()
        return '%s\n%s%s%s' % (prefix, level, node, suffix)
    return dump(node, name, initial_indent)

def strip_tree(node, iter_node=iter_node, special=ast.AST, list=list, isinstance=isinstance, type=type, len=len):
    """Strips an AST by removing all attributes not in _fields.

    Returns a set of the names of all attributes stripped.

    This canonicalizes two trees for comparison purposes."""
    stripped = set()
    def strip(node, indent):
        unknown = set()
        leaf = True
        for subnode, _ in iter_node(node, unknown=unknown):
            leaf = False
            strip(subnode, indent + '    ')
        if leaf:
            if isinstance(node, special):
                unknown = set(vars(node))
        stripped.update(unknown)
        for name in unknown:
            delattr(node, name)
        if hasattr(node, 'ctx'):
            delattr(node, 'ctx')
            if 'ctx' in node._fields:
                mylist = list(node._fields)
                mylist.remove('ctx')
                node._fields = mylist
    strip(node, '')
    return stripped

def allow_ast_comparison():
    """This ugly little monkey-patcher adds in a helper class
    to all the AST node types.  This helper class allows
    eq/ne comparisons to work, so that entire trees can
    be easily compared by Python's comparison machinery.
    Used by the anti8 functions to compare old and new ASTs.
    Could also be used by the test library."""
    class CompareHelper(object):
        def __eq__(self, other):
            return type(self) == type(other) and vars(self) == vars(other)
        def __ne__(self, other):
            return type(self) != type(other) or vars(self) != vars(other)
    for item in vars(ast).values():
        if type(item) != type:
            continue
        if issubclass(item, ast.AST):
            try:
                item.__bases__ = tuple(list(item.__bases__) + [CompareHelper])
            except TypeError:
                pass

def precedence_setter(AST=ast.AST, get_op_precedence=get_op_precedence, isinstance=isinstance, list=list):
    """This only uses a closure for performance reasons,
    to reduce the number of attribute lookups.  (set_precedence
    is called a lot of times.)"""
    def set_precedence(value, *nodes):
        """Set the precedence (of the parent) into the children.
        """
        if isinstance(value, AST):
            value = get_op_precedence(value)
        for node in nodes:
            if isinstance(node, AST):
                node._pp = value
            elif isinstance(node, list):
                set_precedence(value, *node)
            else:
                assert node is None, node
    return set_precedence

def validate_token_age(callback_token):
    """Returns True if a given token is within the age expiration limit."""
    try:
        token = CallbackToken.objects.get(key=callback_token, is_active=True)
        seconds = (timezone.now() - token.created_at).total_seconds()
        token_expiry_time = api_settings.PASSWORDLESS_TOKEN_EXPIRE_TIME
        if seconds <= token_expiry_time:
            return True
        else:
            token.is_active = False
            token.save()
            return False
    except CallbackToken.DoesNotExist:
        return False

def verify_user_alias(user, token):
    """Marks a user's contact point as verified depending on accepted token type."""
    if token.to_alias_type == 'EMAIL':
        if token.to_alias == getattr(user, api_settings.PASSWORDLESS_USER_EMAIL_FIELD_NAME):
            setattr(user, api_settings.PASSWORDLESS_USER_EMAIL_VERIFIED_FIELD_NAME, True)
    elif token.to_alias_type == 'MOBILE':
        if token.to_alias == getattr(user, api_settings.PASSWORDLESS_USER_MOBILE_FIELD_NAME):
            setattr(user, api_settings.PASSWORDLESS_USER_MOBILE_VERIFIED_FIELD_NAME, True)
    else:
        return False
    user.save()
    return True

def invalidate_previous_tokens(sender, instance, **kwargs):
    """Invalidates all previously issued tokens as a post_save signal."""
    active_tokens = None
    if isinstance(instance, CallbackToken):
        active_tokens = CallbackToken.objects.active().filter(user=instance.user).exclude(id=instance.id)
    if active_tokens:
        for token in active_tokens:
            token.is_active = False
            token.save()

def check_unique_tokens(sender, instance, **kwargs):
    """Ensures that mobile and email tokens are unique or tries once more to generate."""
    if isinstance(instance, CallbackToken):
        if CallbackToken.objects.filter(key=instance.key, is_active=True).exists():
            instance.key = generate_numeric_token()

def assert_port_exists(port_name, compound):
    """Ensure that a Port label exists in a Compound."""
    if port_name in compound.labels:
        return True
    else:
        from mbuild.port import Port
        available_ports = [name for name in compound.labels if isinstance(compound.labels[name], Port)]
        compound_name = compound.__class__.__name__
        raise ValueError("No port named '{port_name}' in {compound_name}'s labels. Labeled Ports in {compound_name} are: {available_ports}".format(**locals()))

def angle(u, v, w=None):
    """Returns the angle in radians between two vectors."""
    if w is not None:
        u = u - v
        v = w - v
    c = np.dot(u, v) / norm(u) / norm(v)
    return np.arccos(np.clip(c, -1, 1))

def extract_files_from_dict(d):
    """Return any file objects from the provided dict.

    >>> extract_files_from_dict({
    ... 'oauth_token': 'foo',
    ... 'track': {
    ...   'title': 'bar',
    ...   'asset_data': open('setup.py', 'rb')
    ...  }})  # doctest:+ELLIPSIS
    {'track': {'asset_data': <...}}"""
    files = {}
    for key, value in six.iteritems(d):
        if isinstance(value, dict):
            files[key] = extract_files_from_dict(value)
        elif is_file_like(value):
            files[key] = value
    return files

def remove_files_from_dict(d):
    """Return the provided dict with any file objects removed.

    >>> remove_files_from_dict({
    ...   'oauth_token': 'foo',
    ...   'track': {
    ...       'title': 'bar',
    ...       'asset_data': open('setup.py', 'rb')
    ...   }
    ... }) == {'track': {'title': 'bar'}, 'oauth_token': 'foo'}
    ... # doctest:+ELLIPSIS
    True"""
    file_free = {}
    for key, value in six.iteritems(d):
        if isinstance(value, dict):
            file_free[key] = remove_files_from_dict(value)
        elif not is_file_like(value):
            if hasattr(value, '__iter__'):
                file_free[key] = value
            elif hasattr(value, 'encode'):
                file_free[key] = value.encode('utf-8')
            else:
                file_free[key] = str(value)
    return file_free

def namespaced_query_string(d, prefix=''):
    """Transform a nested dict into a string with namespaced query params.

    >>> namespaced_query_string({
    ...  'oauth_token': 'foo',
    ...  'track': {'title': 'bar', 'sharing': 'private'}}) == {
    ...      'track[sharing]': 'private',
    ...      'oauth_token': 'foo',
    ...      'track[title]': 'bar'}  # doctest:+ELLIPSIS
    True"""
    qs = {}
    prefixed = lambda k: prefix and '%s[%s]' % (prefix, k) or k
    for key, value in six.iteritems(d):
        if isinstance(value, dict):
            qs.update(namespaced_query_string(value, prefix=key))
        else:
            qs[prefixed(key)] = value
    return qs

def wrapped_resource(response):
    """Return a response wrapped in the appropriate wrapper type.

    Lists will be returned as a ```ResourceList``` instance,
    dicts will be returned as a ```Resource``` instance."""
    response_content = response.content.decode(response.encoding or 'utf-8')
    try:
        content = json.loads(response_content)
    except ValueError:
        content = response_content
    if isinstance(content, list):
        result = ResourceList(content)
    else:
        result = Resource(content)
        if hasattr(result, 'collection'):
            result.collection = ResourceList(result.collection)
    result.raw_data = response_content
    for attr in ('encoding', 'url', 'status_code', 'reason'):
        setattr(result, attr, getattr(response, attr))
    return result

def get_color_mode(mode):
    """Convert PIL mode to ColorMode."""
    name = mode.upper()
    name = name.rstrip('A')
    name = {'1': 'BITMAP', 'L': 'GRAYSCALE'}.get(name, name)
    return getattr(ColorMode, name)

def get_pil_mode(value, alpha=False):
    """Get PIL mode from ColorMode."""
    name = {'GRAYSCALE': 'L', 'BITMAP': '1', 'DUOTONE': 'L', 'INDEXED': 'P'}.get(value, value)
    if alpha and name in ('L', 'RGB'):
        name += 'A'
    return name

def convert_image_data_to_pil(psd, apply_icc=True, **kwargs):
    """Convert ImageData to PIL Image.

    .. note:: Image resources contain extra alpha channels in these keys:
        `ALPHA_NAMES_UNICODE`, `ALPHA_NAMES_PASCAL`, `ALPHA_IDENTIFIERS`."""
    from PIL import Image, ImageOps
    header = psd.header
    size = (header.width, header.height)
    channels = []
    for channel_data in psd.image_data.get_data(header):
        channels.append(_create_channel(size, channel_data, header.depth))
    alpha = _get_alpha_use(psd)
    mode = get_pil_mode(header.color_mode.name)
    if mode == 'P':
        image = Image.merge('L', channels[:get_pil_channels(mode)])
        image.putpalette(psd.color_mode_data.interleave())
    elif mode == 'MULTICHANNEL':
        image = channels[0]
    else:
        image = Image.merge(mode, channels[:get_pil_channels(mode)])
    if mode == 'CMYK':
        image = image.point(lambda x: 255 - x)
    if apply_icc and 'ICC_PROFILE' in psd.image_resources:
        image = _apply_icc(image, psd.image_resources.get_data('ICC_PROFILE'))
    if alpha and mode in ('L', 'RGB'):
        image.putalpha(channels[-1])
    return _remove_white_background(image)

def convert_layer_to_pil(layer, apply_icc=True, **kwargs):
    """Convert Layer to PIL Image."""
    from PIL import Image
    header = layer._psd._record.header
    if header.color_mode == ColorMode.BITMAP:
        raise NotImplementedError
    width, height = (layer.width, layer.height)
    channels, alpha = ([], None)
    for ci, cd in zip(layer._record.channel_info, layer._channels):
        if ci.id in (ChannelID.USER_LAYER_MASK, ChannelID.REAL_USER_LAYER_MASK):
            continue
        channel = cd.get_data(width, height, header.depth, header.version)
        channel_image = _create_channel((width, height), channel, header.depth)
        if ci.id == ChannelID.TRANSPARENCY_MASK:
            alpha = channel_image
        else:
            channels.append(channel_image)
    mode = get_pil_mode(header.color_mode.name)
    channels = _check_channels(channels, header.color_mode)
    image = Image.merge(mode, channels)
    if mode == 'CMYK':
        image = image.point(lambda x: 255 - x)
    if alpha is not None:
        if mode in ('RGB', 'L'):
            image.putalpha(alpha)
        else:
            logger.debug('Alpha channel is not supported in %s' % mode)
    if apply_icc and 'ICC_PROFILE' in layer._psd.image_resources:
        image = _apply_icc(image, layer._psd.image_resources.get_data('ICC_PROFILE'))
    return image

def convert_pattern_to_pil(pattern, version=1):
    """Convert Pattern to PIL Image."""
    from PIL import Image
    mode = get_pil_mode(pattern.image_mode.name, False)
    size = (pattern.data.rectangle[3], pattern.data.rectangle[2])
    channels = [_create_channel(size, c.get_data(version), c.pixel_depth).convert('L') for c in pattern.data.channels if c.is_written]
    if len(channels) == len(mode) + 1:
        mode += 'A'
    if mode == 'P':
        image = channels[0]
        image.putpalette([x for rgb in pattern.color_table for x in rgb])
    else:
        image = Image.merge(mode, channels)
    if mode == 'CMYK':
        image = image.point(lambda x: 255 - x)
    return image

def convert_thumbnail_to_pil(thumbnail, mode='RGB'):
    """Convert thumbnail resource."""
    from PIL import Image
    if thumbnail.fmt == 0:
        size = (thumbnail.width, thumbnail.height)
        stride = thumbnail.widthbytes
        return Image.frombytes('RGBX', size, thumbnail.data, 'raw', mode, stride)
    elif thumbnail.fmt == 1:
        return Image.open(io.BytesIO(thumbnail.data))
    else:
        raise ValueError('Unknown thumbnail format %d' % thumbnail.fmt)

def _apply_icc(image, icc_profile):
    """Apply ICC Color profile."""
    from io import BytesIO
    try:
        from PIL import ImageCms
    except ImportError:
        logger.debug('ICC profile found but not supported. Install little-cms.')
        return image
    if image.mode not in ('RGB',):
        logger.debug('%s ICC profile is not supported.' % image.mode)
        return image
    try:
        in_profile = ImageCms.ImageCmsProfile(BytesIO(icc_profile))
        out_profile = ImageCms.createProfile('sRGB')
        return ImageCms.profileToProfile(image, in_profile, out_profile)
    except ImageCms.PyCMSError as e:
        logger.warning('PyCMSError: %s' % e)
    return image

def _remove_white_background(image):
    """Remove white background in the preview image."""
    from PIL import ImageMath, Image
    if image.mode == 'RGBA':
        bands = image.split()
        a = bands[3]
        rgb = [ImageMath.eval('convert(float(x + a - 255) * 255.0 / float(max(a, 1)) * float(min(a, 1)) + float(x) * float(1 - min(a, 1)), "L")', x=x, a=a) for x in bands[:3]]
        return Image.merge(bands=rgb + [a], mode='RGBA')
    return image

def _shuffled_order(w, h):
    """Generator for the order of 4-byte values.

    32bit channels are also encoded using delta encoding,
    but it make no sense to apply delta compression to bytes.
    It is possible to apply delta compression to 2-byte or 4-byte
    words, but it seems it is not the best way either.
    In PSD, each 4-byte item is split into 4 bytes and these
    bytes are packed together: "123412341234" becomes "111222333444";
    delta compression is applied to the packed data.

    So we have to (a) decompress data from the delta compression
    and (b) recombine data back to 4-byte values."""
    rowsize = 4 * w
    for row in range(0, rowsize * h, rowsize):
        for offset in range(row, row + w):
            for x in range(offset, offset + rowsize, w):
                yield x

def extract_bbox(layers):
    """Returns a bounding box for ``layers`` or (0, 0, 0, 0) if the layers
    have no bounding box."""
    if not hasattr(layers, '__iter__'):
        layers = [layers]
    bboxes = [layer.bbox for layer in layers if layer.is_visible() and (not layer.bbox == (0, 0, 0, 0))]
    if len(bboxes) == 0:
        return (0, 0, 0, 0)
    lefts, tops, rights, bottoms = zip(*bboxes)
    return (min(lefts), min(tops), max(rights), max(bottoms))

def _make_linear_gradient(width, height, angle=90.0):
    """Generates index map for linear gradients."""
    import numpy as np
    X, Y = np.meshgrid(np.linspace(0, 1, width), np.linspace(0, 1, height))
    theta = np.radians(angle % 360)
    c, s = (np.cos(theta), np.sin(theta))
    if 0 <= theta and theta < 0.5 * np.pi:
        Z = np.abs(c * X + s * Y)
    elif 0.5 * np.pi <= theta and theta < np.pi:
        Z = np.abs(c * (X - width) + s * Y)
    elif np.pi <= theta and theta < 1.5 * np.pi:
        Z = np.abs(c * (X - width) + s * (Y - height))
    elif 1.5 * np.pi <= theta and theta < 2.0 * np.pi:
        Z = np.abs(c * X + s * (Y - height))
    return (Z - Z.min()) / (Z.max() - Z.min())

def read_padding(fp, size, divisor=2):
    """Read padding bytes for the given byte size.

    :param fp: file-like object
    :param divisor: divisor of the byte alignment
    :return: read byte size"""
    remainder = size % divisor
    if remainder:
        return fp.read(divisor - remainder)
    return b''

def write_padding(fp, size, divisor=2):
    """Writes padding bytes given the currently written size.

    :param fp: file-like object
    :param divisor: divisor of the byte alignment
    :return: written byte size"""
    remainder = size % divisor
    if remainder:
        return write_bytes(fp, struct.pack('%dx' % (divisor - remainder)))
    return 0

def read_be_array(fmt, count, fp):
    """Reads an array from a file with big-endian data."""
    arr = array.array(str(fmt))
    if hasattr(arr, 'frombytes'):
        arr.frombytes(fp.read(count * arr.itemsize))
    else:
        arr.fromstring(fp.read(count * arr.itemsize))
    return fix_byteorder(arr)

def be_array_from_bytes(fmt, data):
    """Reads an array from bytestring with big-endian data."""
    arr = array.array(str(fmt), data)
    return fix_byteorder(arr)

def be_array_to_bytes(arr):
    """Writes an array to bytestring with big-endian data."""
    data = fix_byteorder(arr)
    if hasattr(arr, 'tobytes'):
        return data.tobytes()
    else:
        return data.tostring()

def new_registry(attribute=None):
    """Returns an empty dict and a @register decorator."""
    registry = {}
    def register(key):
        def decorator(func):
            registry[key] = func
            if attribute:
                setattr(func, attribute, key)
            return func
        return decorator
    return (registry, register)

def json_encoder_default(obj):
    """JSON encoder function that handles some numpy types."""
    if isinstance(obj, numbers.Integral) and (obj < min_safe_integer or obj > max_safe_integer):
        return str(obj)
    if isinstance(obj, np.integer):
        return str(obj)
    elif isinstance(obj, np.floating):
        return float(obj)
    elif isinstance(obj, np.ndarray):
        return list(obj)
    elif isinstance(obj, (set, frozenset)):
        return list(obj)
    raise TypeError

def run_on_new_thread(func, daemon=True):
    """Calls `func()` from a new thread.

    :param daemon: Specifies whether the thread should be in daemon mode.

    :returns: A concurrent.futures.Future object representing the result."""
    f = concurrent.futures.Future()
    def wrapper():
        if not f.set_running_or_notify_cancel():
            return
        try:
            f.set_result(func())
        except Exception as e:
            f.set_exception(e)
    t = threading.Thread(target=wrapper)
    t.daemon = daemon
    t.start()
    return f

def downsample_with_averaging(array, factor):
    """Downsample x by factor using averaging.

    @return: The downsampled array, of the same type as x."""
    factor = tuple(factor)
    output_shape = tuple((int(math.ceil(s / f)) for s, f in zip(array.shape, factor)))
    temp = np.zeros(output_shape, dtype=np.float32)
    counts = np.zeros(output_shape, np.int)
    for offset in np.ndindex(factor):
        part = array[tuple((np.s_[o::f] for o, f in zip(offset, factor)))]
        indexing_expr = tuple((np.s_[:s] for s in part.shape))
        temp[indexing_expr] += part
        counts[indexing_expr] += 1
    return np.cast[array.dtype](temp / counts)

def downsample_with_striding(array, factor):
    """Downsample x by factor using striding.

    @return: The downsampled array, of the same type as x."""
    return array[tuple((np.s_[::f] for f in factor))]

