def _bqschema_to_nullsafe_dtypes(schema_fields):
    """Specify explicit dtypes based on BigQuery schema.

    This function only specifies a dtype when the dtype allows nulls.
    Otherwise, use pandas's default dtype choice.

    See: http://pandas.pydata.org/pandas-docs/dev/missing_data.html
    #missing-data-casting-rules-and-indexing"""
    dtype_map = {'FLOAT': np.dtype(float), 'TIMESTAMP': 'datetime64[ns]', 'TIME': 'datetime64[ns]', 'DATE': 'datetime64[ns]', 'DATETIME': 'datetime64[ns]'}
    dtypes = {}
    for field in schema_fields:
        name = str(field['name'])
        if field['mode'].upper() == 'REPEATED':
            continue
        dtype = dtype_map.get(field['type'].upper())
        if dtype:
            dtypes[name] = dtype
    return dtypes

def _cast_empty_df_dtypes(schema_fields, df):
    """Cast any columns in an empty dataframe to correct type.

    In an empty dataframe, pandas cannot choose a dtype unless one is
    explicitly provided. The _bqschema_to_nullsafe_dtypes() function only
    provides dtypes when the dtype safely handles null values. This means
    that empty int64 and boolean columns are incorrectly classified as
    ``object``."""
    if not df.empty:
        raise ValueError('DataFrame must be empty in order to cast non-nullsafe dtypes')
    dtype_map = {'BOOLEAN': bool, 'INTEGER': np.int64}
    for field in schema_fields:
        column = str(field['name'])
        if field['mode'].upper() == 'REPEATED':
            continue
        dtype = dtype_map.get(field['type'].upper())
        if dtype:
            df[column] = df[column].astype(dtype)
    return df

def _localize_df(schema_fields, df):
    """Localize any TIMESTAMP columns to tz-aware type.

    In pandas versions before 0.24.0, DatetimeTZDtype cannot be used as the
    dtype in Series/DataFrame construction, so localize those columns after
    the DataFrame is constructed."""
    for field in schema_fields:
        column = str(field['name'])
        if field['mode'].upper() == 'REPEATED':
            continue
        if field['type'].upper() == 'TIMESTAMP' and df[column].dt.tz is None:
            df[column] = df[column].dt.tz_localize('UTC')
    return df

def update_schema(schema_old, schema_new):
    """Given an old BigQuery schema, update it with a new one.

    Where a field name is the same, the new will replace the old. Any
    new fields not present in the old schema will be added.

    Arguments:
        schema_old: the old schema to update
        schema_new: the new schema which will overwrite/extend the old"""
    old_fields = schema_old['fields']
    new_fields = schema_new['fields']
    output_fields = list(old_fields)
    field_indices = {field['name']: i for i, field in enumerate(output_fields)}
    for field in new_fields:
        name = field['name']
        if name in field_indices:
            output_fields[field_indices[name]] = field
        else:
            output_fields.append(field)
    return {'fields': output_fields}

def split_stable_id(stable_id):
    """Split stable id, returning:

        * Document (root) stable ID
        * Context polymorphic type
        * Character offset start, end *relative to document start*

    Returns tuple of four values."""
    split1 = stable_id.split('::')
    if len(split1) == 2:
        split2 = split1[1].split(':')
        if len(split2) == 3:
            return (split1[0], split2[0], int(split2[1]), int(split2[2]))
    raise ValueError(f'Malformed stable_id:\t{stable_id}')

def vizlib_unary_features(span):
    """Visual-related features for a single span"""
    if not span.sentence.is_visual():
        return
    for f in get_visual_aligned_lemmas(span):
        yield (f'ALIGNED_{f}', DEF_VALUE)
    for page in set(span.get_attrib_tokens('page')):
        yield (f'PAGE_[{page}]', DEF_VALUE)

def vizlib_binary_features(span1, span2):
    """Visual-related features for a pair of spans"""
    if same_page((span1, span2)):
        yield ('SAME_PAGE', DEF_VALUE)
        if is_horz_aligned((span1, span2)):
            yield ('HORZ_ALIGNED', DEF_VALUE)
        if is_vert_aligned((span1, span2)):
            yield ('VERT_ALIGNED', DEF_VALUE)
        if is_vert_aligned_left((span1, span2)):
            yield ('VERT_ALIGNED_LEFT', DEF_VALUE)
        if is_vert_aligned_right((span1, span2)):
            yield ('VERT_ALIGNED_RIGHT', DEF_VALUE)
        if is_vert_aligned_center((span1, span2)):
            yield ('VERT_ALIGNED_CENTER', DEF_VALUE)

def corenlp_to_xmltree(s, prune_root=True):
    """Transforms an object with CoreNLP dep_path and dep_parent attributes into
    an XMLTree. Will include elements of any array having the same dimensiion
    as dep_* as node attributes. Also adds special word_idx attribute
    corresponding to original sequence order in sentence."""
    s = get_as_dict(s)
    if not ('dep_parents' in s and isinstance(s['dep_parents'], list)):
        raise ValueError("Input CoreNLP object must have a 'dep_parents' attribute which is a list")
    try:
        dep_parents = list(map(int, s['dep_parents']))
    except Exception:
        raise ValueError("'dep_parents' attribute must be a list of ints")
    b = min(dep_parents)
    if b != 0:
        dep_parents = list(map(lambda j: j - b, dep_parents))
    root = corenlp_to_xmltree_sub(s, dep_parents, 0)
    if prune_root:
        for c in root:
            if len(c) == 0:
                root.remove(c)
        if len(root) == 1:
            root = root.findall('./*')[0]
    return XMLTree(root, words=s['words'])

def strlib_unary_features(span):
    """Structural-related features for a single span"""
    if not span.sentence.is_structural():
        return
    yield (f'TAG_{get_tag(span)}', DEF_VALUE)
    for attr in get_attributes(span):
        yield (f'HTML_ATTR_{attr}', DEF_VALUE)
    yield (f'PARENT_TAG_{get_parent_tag(span)}', DEF_VALUE)
    prev_tags = get_prev_sibling_tags(span)
    if len(prev_tags):
        yield (f'PREV_SIB_TAG_{prev_tags[-1]}', DEF_VALUE)
        yield (f'NODE_POS_{len(prev_tags) + 1}', DEF_VALUE)
    else:
        yield ('FIRST_NODE', DEF_VALUE)
    next_tags = get_next_sibling_tags(span)
    if len(next_tags):
        yield (f'NEXT_SIB_TAG_{next_tags[0]}', DEF_VALUE)
    else:
        yield ('LAST_NODE', DEF_VALUE)
    yield (f"ANCESTOR_CLASS_[{' '.join(get_ancestor_class_names(span))}]", DEF_VALUE)
    yield (f"ANCESTOR_TAG_[{' '.join(get_ancestor_tag_names(span))}]", DEF_VALUE)
    yield (f"ANCESTOR_ID_[{' '.join(get_ancestor_id_names(span))}]", DEF_VALUE)

def get_between_ngrams(c, attrib='words', n_min=1, n_max=1, lower=True):
    """Return the ngrams *between* two unary Mentions of a binary-Mention Candidate.

    Get the ngrams *between* two unary Mentions of a binary-Mention Candidate,
    where both share the same sentence Context.

    :param c: The binary-Mention Candidate to evaluate.
    :param attrib: The token attribute type (e.g. words, lemmas, poses)
    :param n_min: The minimum n of the ngrams that should be returned
    :param n_max: The maximum n of the ngrams that should be returned
    :param lower: If 'True', all ngrams will be returned in lower case
    :rtype: a *generator* of ngrams"""
    if len(c) != 2:
        raise ValueError('Only applicable to binary Candidates')
    span0 = _to_span(c[0])
    span1 = _to_span(c[1])
    if span0.sentence != span1.sentence:
        raise ValueError('Only applicable to Candidates where both spans are                           from the same immediate Context.')
    distance = abs(span0.get_word_start_index() - span1.get_word_start_index())
    if span0.get_word_start_index() < span1.get_word_start_index():
        for ngram in get_right_ngrams(span0, window=distance - 1, attrib=attrib, n_min=n_min, n_max=n_max, lower=lower):
            yield ngram
    else:
        for ngram in get_right_ngrams(span1, window=distance - 1, attrib=attrib, n_min=n_min, n_max=n_max, lower=lower):
            yield ngram

def _to_span(x, idx=0):
    """Convert a Candidate, Mention, or Span to a span."""
    if isinstance(x, Candidate):
        return x[idx].context
    elif isinstance(x, Mention):
        return x.context
    elif isinstance(x, TemporarySpanMention):
        return x
    else:
        raise ValueError(f'{type(x)} is an invalid argument type')

def _to_spans(x):
    """Convert a Candidate, Mention, or Span to a list of spans."""
    if isinstance(x, Candidate):
        return [_to_span(m) for m in x]
    elif isinstance(x, Mention):
        return [x.context]
    elif isinstance(x, TemporarySpanMention):
        return [x]
    else:
        raise ValueError(f'{type(x)} is an invalid argument type')

def _merge(x, y):
    """Merge two nested dictionaries. Overwrite values in x with values in y."""
    merged = {**x, **y}
    xkeys = x.keys()
    for key in xkeys:
        if isinstance(x[key], dict) and key in y:
            merged[key] = _merge(x[key], y[key])
    return merged

def set_custom_boundary(doc):
    """Set the sentence boundaries based on the already separated sentences.
    :param doc: doc.user_data should have a list of Sentence.
    :return doc:"""
    if doc.user_data == {}:
        raise AttributeError('A list of Sentence is not attached to doc.user_data.')
    for token_nr, token in enumerate(doc):
        doc[token_nr].is_sent_start = False
    token_nr = 0
    for sentence in doc.user_data:
        doc[token_nr].is_sent_start = True
        token_nr += len(sentence.words)
    return doc

def pad_batch(batch, max_len=0, type='int'):
    """Pad the batch into matrix

    :param batch: The data for padding.
    :type batch: list of word index sequences
    :param max_len: Max length of sequence of padding.
    :type max_len: int
    :param type: mask value type.
    :type type: str
    :return: The padded matrix and correspoing mask matrix.
    :rtype: pair of torch.Tensors with shape (batch_size, max_sent_len)"""
    batch_size = len(batch)
    max_sent_len = int(np.max([len(x) for x in batch]))
    if max_len > 0 and max_len < max_sent_len:
        max_sent_len = max_len
    if type == 'float':
        idx_matrix = np.zeros((batch_size, max_sent_len), dtype=np.float32)
    else:
        idx_matrix = np.zeros((batch_size, max_sent_len), dtype=np.int)
    for idx1, i in enumerate(batch):
        for idx2, j in enumerate(i):
            if idx2 >= max_sent_len:
                break
            idx_matrix[idx1, idx2] = j
    idx_matrix = torch.tensor(idx_matrix)
    mask_matrix = torch.tensor(torch.eq(idx_matrix.data, 0))
    return (idx_matrix, mask_matrix)

def get_as_dict(x):
    """Return an object as a dictionary of its attributes."""
    if isinstance(x, dict):
        return x
    else:
        try:
            return x._asdict()
        except AttributeError:
            return x.__dict__

def same_document(c):
    """Return True if all Mentions in the given candidate are from the same Document.

    :param c: The candidate whose Mentions are being compared
    :rtype: boolean"""
    return all((_to_span(c[i]).sentence.document is not None and _to_span(c[i]).sentence.document == _to_span(c[0]).sentence.document for i in range(len(c))))

def same_table(c):
    """Return True if all Mentions in the given candidate are from the same Table.

    :param c: The candidate whose Mentions are being compared
    :rtype: boolean"""
    return all((_to_span(c[i]).sentence.is_tabular() and _to_span(c[i]).sentence.table == _to_span(c[0]).sentence.table for i in range(len(c))))

def same_row(c):
    """Return True if all Mentions in the given candidate are from the same Row.

    :param c: The candidate whose Mentions are being compared
    :rtype: boolean"""
    return same_table(c) and all((is_row_aligned(_to_span(c[i]).sentence, _to_span(c[0]).sentence) for i in range(len(c))))

def same_col(c):
    """Return True if all Mentions in the given candidate are from the same Col.

    :param c: The candidate whose Mentions are being compared
    :rtype: boolean"""
    return same_table(c) and all((is_col_aligned(_to_span(c[i]).sentence, _to_span(c[0]).sentence) for i in range(len(c))))

def is_tabular_aligned(c):
    """Return True if all Mentions in the given candidate are from the same Row or Col.

    :param c: The candidate whose Mentions are being compared
    :rtype: boolean"""
    return same_table(c) and (is_col_aligned(_to_span(c[i]).sentence, _to_span(c[0]).sentence) or is_row_aligned(_to_span(c[i]).sentence, _to_span(c[0]).sentence) for i in range(len(c)))

def same_cell(c):
    """Return True if all Mentions in the given candidate are from the same Cell.

    :param c: The candidate whose Mentions are being compared
    :rtype: boolean"""
    return all((_to_span(c[i]).sentence.cell is not None and _to_span(c[i]).sentence.cell == _to_span(c[0]).sentence.cell for i in range(len(c))))

def same_sentence(c):
    """Return True if all Mentions in the given candidate are from the same Sentence.

    :param c: The candidate whose Mentions are being compared
    :rtype: boolean"""
    return all((_to_span(c[i]).sentence is not None and _to_span(c[i]).sentence == _to_span(c[0]).sentence for i in range(len(c))))

def get_max_col_num(mention):
    """Return the largest column number that a Mention occupies.

    :param mention: The Mention to evaluate. If a candidate is given, default
        to its last Mention.
    :rtype: integer or None"""
    span = _to_span(mention, idx=-1)
    if span.sentence.is_tabular():
        return span.sentence.cell.col_end
    else:
        return None

def get_min_col_num(mention):
    """Return the lowest column number that a Mention occupies.

    :param mention: The Mention to evaluate. If a candidate is given, default
        to its first Mention.
    :rtype: integer or None"""
    span = _to_span(mention)
    if span.sentence.is_tabular():
        return span.sentence.cell.col_start
    else:
        return None

def get_min_row_num(mention):
    """Return the lowest row number that a Mention occupies.

    :param mention: The Mention to evaluate. If a candidate is given, default
        to its first Mention.
    :rtype: integer or None"""
    span = _to_span(mention)
    if span.sentence.is_tabular():
        return span.sentence.cell.row_start
    else:
        return None

def get_cell_ngrams(mention, attrib='words', n_min=1, n_max=1, lower=True):
    """Get the ngrams that are in the Cell of the given mention, not including itself.

    Note that if a candidate is passed in, all of its Mentions will be searched.

    :param mention: The Mention whose Cell is being searched
    :param attrib: The token attribute type (e.g. words, lemmas, poses)
    :param n_min: The minimum n of the ngrams that should be returned
    :param n_max: The maximum n of the ngrams that should be returned
    :param lower: If True, all ngrams will be returned in lower case
    :rtype: a *generator* of ngrams"""
    spans = _to_spans(mention)
    for span in spans:
        for ngram in get_sentence_ngrams(span, attrib=attrib, n_min=n_min, n_max=n_max, lower=lower):
            yield ngram
        if span.sentence.is_tabular():
            for ngram in chain.from_iterable([tokens_to_ngrams(getattr(sentence, attrib), n_min=n_min, n_max=n_max, lower=lower) for sentence in _get_table_cells(span.sentence.table)[span.sentence.cell] if sentence != span.sentence]):
                yield ngram

def get_head_ngrams(mention, axis=None, attrib='words', n_min=1, n_max=1, lower=True):
    """Get the ngrams from the cell in the head of the row or column.

    More specifically, this returns the ngrams in the leftmost cell in a row and/or the
    ngrams in the topmost cell in the column, depending on the axis parameter.

    Note that if a candidate is passed in, all of its Mentions will be searched.

    :param mention: The Mention whose head Cells are being returned
    :param axis: Which axis {'row', 'col'} to search. If None, then both row
        and col are searched.
    :param attrib: The token attribute type (e.g. words, lemmas, poses)
    :param n_min: The minimum n of the ngrams that should be returned
    :param n_max: The maximum n of the ngrams that should be returned
    :param lower: If True, all ngrams will be returned in lower case
    :rtype: a *generator* of ngrams"""
    spans = _to_spans(mention)
    axes = (axis,) if axis else ('row', 'col')
    for span in spans:
        if span.sentence.is_tabular():
            for axis in axes:
                if getattr(span.sentence, _other_axis(axis) + '_start') == 0:
                    return
                for sentence in getattr(_get_head_cell(span.sentence.cell, axis), 'sentences', []):
                    for ngram in tokens_to_ngrams(getattr(sentence, attrib), n_min=n_min, n_max=n_max, lower=lower):
                        yield ngram

def bbox_horz_aligned(box1, box2):
    """Returns true if the vertical center point of either span is within the
    vertical range of the other"""
    if not (box1 and box2):
        return False
    box1_top = box1.top + 1.5
    box2_top = box2.top + 1.5
    box1_bottom = box1.bottom - 1.5
    box2_bottom = box2.bottom - 1.5
    return not (box1_top > box2_bottom or box2_top > box1_bottom)

def bbox_vert_aligned(box1, box2):
    """Returns true if the horizontal center point of either span is within the
    horizontal range of the other"""
    if not (box1 and box2):
        return False
    box1_left = box1.left + 1.5
    box2_left = box2.left + 1.5
    box1_right = box1.right - 1.5
    box2_right = box2.right - 1.5
    return not (box1_left > box2_right or box2_left > box1_right)

def bbox_vert_aligned_left(box1, box2):
    """Returns true if the left boundary of both boxes is within 2 pts"""
    if not (box1 and box2):
        return False
    return abs(box1.left - box2.left) <= 2

def bbox_vert_aligned_right(box1, box2):
    """Returns true if the right boundary of both boxes is within 2 pts"""
    if not (box1 and box2):
        return False
    return abs(box1.right - box2.right) <= 2

def bbox_vert_aligned_center(box1, box2):
    """Returns true if the center of both boxes is within 5 pts"""
    if not (box1 and box2):
        return False
    return abs((box1.right + box1.left) / 2.0 - (box2.right + box2.left) / 2.0) <= 5

def get_ddlib_feats(span, context, idxs):
    """Minimalist port of generic mention features from ddlib"""
    if span.stable_id not in unary_ddlib_feats:
        unary_ddlib_feats[span.stable_id] = set()
        for seq_feat in _get_seq_features(context, idxs):
            unary_ddlib_feats[span.stable_id].add(seq_feat)
        for window_feat in _get_window_features(context, idxs):
            unary_ddlib_feats[span.stable_id].add(window_feat)
    for f in unary_ddlib_feats[span.stable_id]:
        yield f

def _get_cand_values(candidate, key_table):
    """Get the corresponding values for the key_table."""
    from fonduer.features.models import FeatureKey
    from fonduer.supervision.models import GoldLabelKey, LabelKey
    if key_table == FeatureKey:
        return candidate.features
    elif key_table == LabelKey:
        return candidate.labels
    elif key_table == GoldLabelKey:
        return candidate.gold_labels
    else:
        raise ValueError(f'{key_table} is not a valid key table.')

def get_sparse_matrix_keys(session, key_table):
    """Return a list of keys for the sparse matrix."""
    return session.query(key_table).order_by(key_table.name).all()

def batch_upsert_records(session, table, records):
    """Batch upsert records into postgresql database."""
    if not records:
        return
    for record_batch in _batch_postgres_query(table, records):
        stmt = insert(table.__table__)
        stmt = stmt.on_conflict_do_update(constraint=table.__table__.primary_key, set_={'keys': stmt.excluded.get('keys'), 'values': stmt.excluded.get('values')})
        session.execute(stmt, record_batch)
        session.commit()

def get_sparse_matrix(session, key_table, cand_lists, key=None):
    """Load sparse matrix of GoldLabels for each candidate_class."""
    result = []
    cand_lists = cand_lists if isinstance(cand_lists, (list, tuple)) else [cand_lists]
    for cand_list in cand_lists:
        if len(cand_list) == 0:
            raise ValueError('cand_lists contain empty cand_list.')
        candidate_class = cand_list[0].__tablename__
        if key:
            keys_map = {key: 0}
            key_size = len(keys_map)
        else:
            all_keys = get_sparse_matrix_keys(session, key_table)
            key_size = len(all_keys)
            keys_map = {}
            for i, k in enumerate(all_keys):
                if candidate_class in k.candidate_classes:
                    keys_map[k.name] = i
        indptr = [0]
        indices = []
        data = []
        for cand in cand_list:
            values = _get_cand_values(cand, key_table)
            if values:
                for cand_key, cand_value in zip(values[0].keys, values[0].values):
                    if cand_key in keys_map:
                        indices.append(keys_map[cand_key])
                        data.append(cand_value)
            indptr.append(len(indices))
        result.append(csr_matrix((data, indices, indptr), shape=(len(cand_list), key_size)))
    return result

def get_mapping(session, table, candidates, generator, key_map):
    """Generate map of keys and values for the candidate from the generator.

    :param session: The database session.
    :param table: The table we will be inserting into (i.e. Feature or Label).
    :param candidates: The candidates to get mappings for.
    :param generator: A generator yielding (candidate_id, key, value) tuples.
    :param key_map: A mutable dict which values will be added to as {key:
        [relations]}.
    :type key_map: Dict
    :return: Generator of dictionaries of {"candidate_id": _, "keys": _, "values": _}
    :rtype: generator of dict"""
    for cand in candidates:
        try:
            temp = session.query(table).filter(table.candidate_id == cand.id).one()
            cand_map = dict(zip(temp.keys, temp.values))
        except NoResultFound:
            cand_map = {}
        map_args = {'candidate_id': cand.id}
        for cid, key, value in generator(cand):
            if value == 0:
                continue
            cand_map[key] = value
        map_args['keys'] = [*cand_map.keys()]
        map_args['values'] = [*cand_map.values()]
        for key in map_args['keys']:
            try:
                key_map[key].add(cand.__class__.__tablename__)
            except KeyError:
                key_map[key] = {cand.__class__.__tablename__}
        yield map_args

def upsert_keys(session, key_table, keys):
    """Bulk add annotation keys to the specified table.

    :param key_table: The sqlalchemy class to insert into.
    :param keys: A map of {name: [candidate_classes]}."""
    if not keys:
        return
    for key_batch in _batch_postgres_query(key_table, [{'name': k[0], 'candidate_classes': k[1]} for k in keys.items()]):
        stmt = insert(key_table.__table__)
        stmt = stmt.on_conflict_do_update(constraint=key_table.__table__.primary_key, set_={'name': stmt.excluded.get('name'), 'candidate_classes': stmt.excluded.get('candidate_classes')})
        while True:
            try:
                session.execute(stmt, key_batch)
                session.commit()
                break
            except Exception as e:
                logger.debug(e)

def get_short_module_name(module_name, obj_name):
    """Get the shortest possible module name"""
    scope = {}
    try:
        exec('from %s import %s' % (module_name, obj_name), scope, scope)
        real_obj = scope[obj_name]
    except Exception:
        return module_name
    parts = module_name.split('.')
    short_name = module_name
    for i in range(len(parts) - 1, 0, -1):
        short_name = '.'.join(parts[:i])
        scope = {}
        try:
            exec('from %s import %s' % (short_name, obj_name), scope, scope)
            assert real_obj is scope[obj_name]
        except Exception:
            short_name = '.'.join(parts[:i + 1])
            break
    return short_name

def identify_names(filename):
    """Builds a codeobj summary by identifying and resolving used names."""
    node, _ = parse_source_file(filename)
    if node is None:
        return {}
    finder = NameFinder()
    finder.visit(node)
    names = list(finder.get_mapping())
    names += extract_object_names_from_docs(filename)
    example_code_obj = collections.OrderedDict()
    for name, full_name in names:
        if name in example_code_obj:
            continue
        splitted = full_name.rsplit('.', 1)
        if len(splitted) == 1:
            continue
        module, attribute = splitted
        module_short = get_short_module_name(module, attribute)
        cobj = {'name': attribute, 'module': module, 'module_short': module_short}
        example_code_obj[name] = cobj
    return example_code_obj

def finalize_backreferences(seen_backrefs, gallery_conf):
    """Replace backref files only if necessary."""
    logger = sphinx_compatibility.getLogger('sphinx-gallery')
    if gallery_conf['backreferences_dir'] is None:
        return
    for backref in seen_backrefs:
        path = os.path.join(gallery_conf['src_dir'], gallery_conf['backreferences_dir'], '%s.examples.new' % backref)
        if os.path.isfile(path):
            _replace_md5(path)
        else:
            level = gallery_conf['log_level'].get('backreference_missing', 'warning')
            func = getattr(logger, level)
            func('Could not find backreferences file: %s' % (path,))
            func('The backreferences are likely to be erroneous due to file system case insensitivity.')

def jupyter_notebook_skeleton():
    """Returns a dictionary with the elements of a Jupyter notebook"""
    py_version = sys.version_info
    notebook_skeleton = {'cells': [], 'metadata': {'kernelspec': {'display_name': 'Python ' + str(py_version[0]), 'language': 'python', 'name': 'python' + str(py_version[0])}, 'language_info': {'codemirror_mode': {'name': 'ipython', 'version': py_version[0]}, 'file_extension': '.py', 'mimetype': 'text/x-python', 'name': 'python', 'nbconvert_exporter': 'python', 'pygments_lexer': 'ipython' + str(py_version[0]), 'version': '{0}.{1}.{2}'.format(*sys.version_info[:3])}}, 'nbformat': 4, 'nbformat_minor': 0}
    return notebook_skeleton

def directive_fun(match, directive):
    """Helper to fill in directives"""
    directive_to_alert = dict(note='info', warning='danger')
    return '<div class="alert alert-{0}"><h4>{1}</h4><p>{2}</p></div>'.format(directive_to_alert[directive], directive.capitalize(), match.group(1).strip())

def fill_notebook(work_notebook, script_blocks):
    """Writes the Jupyter notebook cells

    Parameters
    ----------
    script_blocks : list
        Each list element should be a tuple of (label, content, lineno)."""
    for blabel, bcontent, lineno in script_blocks:
        if blabel == 'code':
            add_code_cell(work_notebook, bcontent)
        else:
            add_markdown_cell(work_notebook, bcontent + '\n')

def layers(n, m):
    """Return *n* random Gaussian mixtures, each of length *m*."""
    def bump(a):
        x = 1 / (0.1 + np.random.random())
        y = 2 * np.random.random() - 0.3
        z = 13 / (0.1 + np.random.random())
        for i in range(m):
            w = (i / float(m) - y) * z
            a[i] += x * np.exp(-w * w)
    a = np.zeros((m, n))
    for i in range(n):
        for j in range(12):
            bump(a[:, i])
    return np.abs(a)

def _import_matplotlib():
    """Import matplotlib safely."""
    import matplotlib
    matplotlib.use('agg')
    matplotlib_backend = matplotlib.get_backend().lower()
    if matplotlib_backend != 'agg':
        raise ValueError("Sphinx-Gallery relies on the matplotlib 'agg' backend to render figures and write them to files. You are currently using the {} backend. Sphinx-Gallery will terminate the build now, because changing backends is not well supported by matplotlib. We advise you to move sphinx_gallery imports before any matplotlib-dependent import. Moving sphinx_gallery imports at the top of your conf.py file should fix this issue".format(matplotlib_backend))
    import matplotlib.pyplot as plt
    return (matplotlib, plt)

def _find_image_ext(path, number=None):
    """Find an image, tolerant of different file extensions."""
    if number is not None:
        path = path.format(number)
    path = os.path.splitext(path)[0]
    for ext in _KNOWN_IMG_EXTS:
        this_path = '%s.%s' % (path, ext)
        if os.path.isfile(this_path):
            break
    else:
        ext = 'png'
    return ('%s.%s' % (path, ext), ext)

