def codestr2rst(codestr, lang='python', lineno=None):
    """Return reStructuredText code block from code string"""
    if lineno is not None:
        if LooseVersion(sphinx.__version__) >= '1.3':
            blank_lines = codestr.count('\n', 0, -len(codestr.lstrip()))
            lineno = '   :lineno-start: {0}\n'.format(lineno + blank_lines)
        else:
            lineno = '   :linenos:\n'
    else:
        lineno = ''
    code_directive = '\n.. code-block:: {0}\n{1}\n'.format(lang, lineno)
    indented_block = indent(codestr, ' ' * 4)
    return code_directive + indented_block

def extract_intro_and_title(filename, docstring):
    """Extract the first paragraph of module-level docstring. max:95 char"""
    paragraphs = docstring.lstrip().split('\n\n')
    paragraphs = [p for p in paragraphs if not p.startswith('.. ') and len(p) > 0]
    if len(paragraphs) == 0:
        raise ValueError('Example docstring should have a header for the example title. Please check the example file:\n {}\n'.format(filename))
    title_paragraph = paragraphs[0]
    match = re.search('([\\w ]+)', title_paragraph)
    if match is None:
        raise ValueError('Could not find a title in first paragraph:\n{}'.format(title_paragraph))
    title = match.group(1).strip()
    intro_paragraph = title if len(paragraphs) < 2 else paragraphs[1]
    intro = re.sub('\n', ' ', intro_paragraph)
    if len(intro) > 95:
        intro = intro[:95] + '...'
    return (intro, title)

def _memory_usage(func, gallery_conf):
    """Get memory usage of a function call."""
    if gallery_conf['show_memory']:
        from memory_profiler import memory_usage
        assert callable(func)
        mem, out = memory_usage(func, max_usage=True, retval=True, multiprocess=True)
        mem = mem[0]
    else:
        out = func()
        mem = 0
    return (out, mem)

def _get_data(url):
    """Helper function to get data over http(s) or from a local file"""
    if urllib_parse.urlparse(url).scheme in ('http', 'https'):
        resp = urllib_request.urlopen(url)
        encoding = resp.headers.get('content-encoding', 'plain')
        data = resp.read()
        if encoding == 'plain':
            data = data.decode('utf-8')
        elif encoding == 'gzip':
            data = BytesIO(data)
            data = gzip.GzipFile(fileobj=data).read().decode('utf-8')
        else:
            raise RuntimeError('unknown encoding')
    else:
        with codecs.open(url, mode='r', encoding='utf-8') as fid:
            data = fid.read()
    return data

def get_data(url, gallery_dir):
    """Persistent dictionary usage to retrieve the search indexes"""
    if sys.version_info[0] == 2 and isinstance(url, unicode):
        url = url.encode('utf-8')
    cached_file = os.path.join(gallery_dir, 'searchindex')
    search_index = shelve.open(cached_file)
    if url in search_index:
        data = search_index[url]
    else:
        data = _get_data(url)
        search_index[url] = data
    search_index.close()
    return data

def embed_code_links(app, exception):
    """Embed hyperlinks to documentation into example code"""
    if exception is not None:
        return
    if not app.builder.config.plot_gallery:
        return
    if app.builder.name not in ['html', 'readthedocs']:
        return
    logger.info('embedding documentation hyperlinks...', color='white')
    gallery_conf = app.config.sphinx_gallery_conf
    gallery_dirs = gallery_conf['gallery_dirs']
    if not isinstance(gallery_dirs, list):
        gallery_dirs = [gallery_dirs]
    for gallery_dir in gallery_dirs:
