def drange(start, stop, step=1.0, include_stop=False):
    """Generate between 2 numbers w/ optional step, optionally include upper bound"""
    if step == 0:
        step = 0.01
    r = start
    if include_stop:
        while r <= stop:
            yield r
            r += step
            r = round(r, 10)
    else:
        while r < stop:
            yield r
            r += step
            r = round(r, 10)

def abbreviate(labels, rfill=' '):
    """Abbreviate labels without introducing ambiguities."""
    max_len = max((len(l) for l in labels))
    for i in range(1, max_len):
        abbrev = [l[:i].ljust(i, rfill) for l in labels]
        if len(abbrev) == len(set(abbrev)):
            break
    return abbrev

def calc_bins(n, min_val, max_val, h=None, binwidth=None):
    """Calculate number of bins for the histogram"""
    if not h:
        h = max(10, math.log(n + 1, 2))
    if binwidth == 0:
        binwidth = 0.1
    if binwidth is None:
        binwidth = (max_val - min_val) / h
    for b in drange(min_val, max_val, step=binwidth, include_stop=True):
        if b.is_integer():
            yield int(b)
        else:
            yield b

def read_numbers(numbers):
    """Read the input data in the most optimal way"""
    if isiterable(numbers):
        for number in numbers:
            yield float(str(number).strip())
    else:
        with open(numbers) as fh:
            for number in fh:
                yield float(number.strip())

def merge_elisions(elided: List[str]) -> str:
    """Given a list of strings with different space swapping elisions applied, merge the elisions,
    taking the most without compounding the omissions.

    :param elided:
    :return:

    >>> merge_elisions([
    ... "ignavae agua multum hiatus", "ignav   agua multum hiatus" ,"ignavae agua mult   hiatus"])
    'ignav   agua mult   hiatus'"""
    results = list(elided[0])
    for line in elided:
        for idx, car in enumerate(line):
            if car == ' ':
                results[idx] = ' '
    return ''.join(results)

def remove_blank_spaces(syllables: List[str]) -> List[str]:
    """Given a list of letters, remove any blank spaces or empty strings.

    :param syllables:
    :return:

    >>> remove_blank_spaces(['', 'a', ' ', 'b', ' ', 'c', ''])
    ['a', 'b', 'c']"""
    cleaned = []
    for syl in syllables:
        if syl == ' ' or syl == '':
            pass
        else:
            cleaned.append(syl)
    return cleaned

