def stemmer_middle_high_german(text_l, rem_umlauts=True, exceptions=exc_dict):
    """text_l: text in string format
    rem_umlauts: choose whether to remove umlauts from string
    exceptions: hard-coded dictionary for the cases the algorithm fails"""
    text_l = normalize_middle_high_german(text_l, to_lower_all=False, to_lower_beginning=True)
    word_tokenizer = WordTokenizer('middle_high_german')
    text_l = word_tokenizer.tokenize(text_l)
    text = []
    for word in text_l:
        try:
            text.append(exceptions[word])
        except:
            if word[0].isupper():
                text.append(word)
            elif word in MHG_STOPS:
                text.append(word)
            else:
                text.append(stem_helper(word, rem_umlaut=rem_umlauts))
    return text

def _regex_span(_regex, _str, case_insensitive=True):
    """Return all matches in an input string.
    :rtype : regex.match.span
    :param _regex: A regular expression pattern.
    :param _str: Text on which to run the pattern."""
    if case_insensitive:
        flags = regex.IGNORECASE | regex.FULLCASE | regex.VERSION1
    else:
        flags = regex.VERSION1
    comp = regex.compile(_regex, flags=flags)
    matches = comp.finditer(_str)
    for match in matches:
        yield match

def _sentence_context(match, language='latin', case_insensitive=True):
    """Take one incoming regex match object and return the sentence in which
     the match occurs.

    :rtype : str
    :param match: regex.match
    :param language: str"""
    language_punct = {'greek': '\\.|;', 'latin': '\\.|\\?|!'}
    assert language in language_punct.keys(), 'Available punctuation schemes: {}'.format(language_punct.keys())
    start = match.start()
    end = match.end()
    window = 1000
    snippet_left = match.string[start - window:start + 1]
    snippet_right = match.string[end:end + window]
    re_match = match.string[match.start():match.end()]
    comp_sent_boundary = regex.compile(language_punct[language], flags=regex.VERSION1)
    left_punct = []
    for punct in comp_sent_boundary.finditer(snippet_left):
        end = punct.end()
        left_punct.append(end)
    try:
        last_period = left_punct.pop() + 1
    except IndexError:
        last_period = 0
    right_punct = []
    for punct in comp_sent_boundary.finditer(snippet_right):
        end = punct.end()
        right_punct.append(end)
    try:
        first_period = right_punct.pop(0)
    except IndexError:
        first_period = 0
    sentence = snippet_left[last_period:-1] + '*' + re_match + '*' + snippet_right[0:first_period]
    return sentence

def _paragraph_context(match):
    """Take one incoming regex match object and return the paragraph in which
    the match occurs.
    :rtype : str
    :param match: regex.match
    :param language: str"""
    start = match.start()
    end = match.end()
    window = 100000
    snippet_left = match.string[start - window:start + 1]
    snippet_right = match.string[end:end + window]
    re_match = match.string[match.start():match.end()]
    para_break_pattern = '\\s*?\\n\\s*?'
    comp_sent_boundary = regex.compile(para_break_pattern, flags=regex.VERSION1)
    left_punct = []
    for punct in comp_sent_boundary.finditer(snippet_left):
        end = punct.end()
        left_punct.append(end)
    try:
        last_period = left_punct.pop()
    except IndexError:
        last_period = 0
    right_punct = []
    for punct in comp_sent_boundary.finditer(snippet_right):
        end = punct.end()
        right_punct.append(end)
    try:
        first_period = right_punct.pop(0)
    except IndexError:
        first_period = 0
    sentence = snippet_left[last_period:-1] + '*' + re_match + '*' + snippet_right[0:first_period - 1]
    return sentence

def match_regex(input_str, pattern, language, context, case_insensitive=True):
    """Take input string and a regex pattern, then yield generator of matches
     in desired format.

     TODO: Rename this `match_pattern` and incorporate the keyword expansion
      code currently in search_corpus.

    :param input_str:
    :param pattern:
    :param language:
    :param context: Integer or 'sentence' 'paragraph'
    :rtype : str"""
    if type(context) is str:
        contexts = ['sentence', 'paragraph']
        assert context in contexts or type(context) is int, 'Available contexts: {}'.format(contexts)
    else:
        context = int(context)
    for match in _regex_span(pattern, input_str, case_insensitive=case_insensitive):
        if context == 'sentence':
            yield _sentence_context(match, language)
        elif context == 'paragraph':
            yield _paragraph_context(match)
        else:
            yield _window_match(match, context)

def walk_trie(dicts, w, q, A):
    """Helper function for traversing the word trie. It simultaneously keeps
    track of the active Automaton state, producing the intersection of the
    given Automaton and the trie (which is equivalent to a DFA). Once an
    invalid "terminating" state is reached, the children nodes are immediately
    dismissed from the recursive stack"""
    if q in A.F and '__end__' in dicts:
        yield w
    for key in dicts.keys():
        if key == '__end__':
            continue
        if A.transition_function(q, key) is None:
            return
        try:
            yield from walk_trie(dicts[key], w + key, A.transition_function(q, key), A)
        except:
            return

def long_substring(str_a, str_b):
    """Looks for a longest common string between any two given strings passed
    :param str_a: str
    :param str_b: str

    Big Thanks to Pulkit Kathuria(@kevincobain2000) for the function
    The function is derived from jProcessing toolkit suite"""
    data = [str_a, str_b]
    substr = ''
    if len(data) > 1 and len(data[0]) > 0:
        for i in range(len(data[0])):
            for j in range(len(data[0]) - i + 1):
                if j > len(substr) and all((data[0][i:i + j] in x for x in data)):
                    substr = data[0][i:i + j]
    return substr.strip()

def open_pickle(path: str):
    """Open a pickle and return loaded pickle object.
    :type path: str
    :param : path: File path to pickle file to be opened.
    :rtype : object"""
    try:
        with open(path, 'rb') as opened_pickle:
            try:
                return pickle.load(opened_pickle)
            except Exception as pickle_error:
                logger.error(pickle_error)
                raise
    except FileNotFoundError as fnf_error:
        logger.error(fnf_error)
        raise
    except IOError as io_err:
        logger.error(io_err)
        raise
    except EOFError as eof_error:
        logger.error(eof_error)
        raise
    except pickle.UnpicklingError as unp_error:
        logger.error(unp_error)
        raise

def expand_iota_subscript(input_str, lowercase=False):
    """Find characters with iota subscript and replace w/ char + iota added."""
    new_list = []
    for char in input_str:
        new_char = MAP_SUBSCRIPT_NO_SUB.get(char)
        if not new_char:
            new_char = char
        new_list.append(new_char)
    new_str = ''.join(new_list)
    if lowercase:
        new_str = new_str.lower()
    return new_str

def write_concordance_from_string(text: str, name: str) -> None:
    """A reworkinng of write_concordance_from_file(). Refactor these."""
    list_of_lists = build_concordance(text)
    user_data_rel = '~/cltk_data/user_data'
    user_data = os.path.expanduser(user_data_rel)
    if not os.path.isdir(user_data):
        os.makedirs(user_data)
    file_path = os.path.join(user_data, 'concordance_' + name + '.txt')
    concordance_output = ''
    for word_list in list_of_lists:
        for line in word_list:
            concordance_output += line + '\n'
    try:
        with open(file_path, 'w') as open_file:
            open_file.write(concordance_output)
            logger.info("Wrote concordance to '%s'.", file_path)
    except IOError as io_error:
        logger.error("Failed to write concordance to '%s'. Error: %s", file_path, io_error)

def is_vocalized(word):
    """Checks if the arabic word is vocalized.
    the word musn't  have any spaces and pounctuations.
    @param word: arabic unicode char
    @type word: unicode
    @return: if the word is vocalized
    @rtype:Boolean"""
    if word.isalpha():
        return False
    for char in word:
        if is_tashkeel(char):
            return True
    else:
        return False

def strip_harakat(text):
    """Strip Harakat from arabic word except Shadda.
    The striped marks are :
        - FATHA,  DAMMA,  KASRA
        - SUKUN
        - FATHATAN,  DAMMATAN,  KASRATAN,


    @param text: arabic text.
    @type text: unicode.
    @return: return a striped text.
    @rtype: unicode."""
    if not text:
        return text
    elif is_vocalized(text):
        for char in HARAKAT:
            text = text.replace(char, '')
    return text

def strip_lastharaka(text):
    """Strip the last Haraka from arabic word except Shadda.
    The striped marks are :
        - FATHA,  DAMMA,  KASRA
        - SUKUN
        - FATHATAN,  DAMMATAN,  KASRATAN

    @param text: arabic text.
    @type text: unicode.
    @return: return a striped text.
    @rtype: unicode."""
    if text:
        if is_vocalized(text):
            return re.sub(LASTHARAKA_PATTERN, u'', text)
    return text

def strip_tashkeel(text):
    """Strip vowels from a text,  include Shadda.
    The striped marks are :
        - FATHA,  DAMMA,  KASRA
        - SUKUN
        - SHADDA
        - FATHATAN,  DAMMATAN,  KASRATAN,  ,  ,  .

    @param text: arabic text.
    @type text: unicode.
    @return: return a striped text.
    @rtype: unicode."""
    if not text:
        return text
    elif is_vocalized(text):
        for char in TASHKEEL:
            text = text.replace(char, '')
    return text

def normalize_hamza(word):
    """Standardize the Hamzat into one form of hamza,
    replace Madda by hamza and alef.
    Replace the LamAlefs by simplified letters.

    @param word: arabic text.
    @type word: unicode.
    @return: return a converted text.
    @rtype: unicode."""
    if word.startswith(ALEF_MADDA):
        if len(word) >= 3 and word[1] not in HARAKAT and (word[2] == SHADDA or len(word) == 3):
            word = HAMZA + ALEF + word[1:]
        else:
            word = HAMZA + HAMZA + word[1:]
    word = word.replace(ALEF_MADDA, HAMZA + HAMZA)
    word = HAMZAT_PATTERN.sub(HAMZA, word)
    return word

def separate(word, extract_shadda=False):
    """separate the letters from the vowels,  in arabic word,
    if a letter hasn't a haraka,  the not definited haraka is attributed.
    return ( letters, vowels)
    @param word: the input word
    @type word: unicode
    @param extract_shadda: extract shadda as seperate text
    @type extract_shadda: Boolean
    @return: ( letters, vowels)
    @rtype:couple of unicode"""
    stack1 = stack.Stack(word)
    stack1.items.reverse()
    letters = stack.Stack()
    marks = stack.Stack()
    vowels = HARAKAT
    last1 = stack1.pop()
    while last1 in vowels:
        last1 = stack1.pop()
    while last1 != None:
        if last1 in vowels:
            marks.pop()
            marks.push(last1)
        elif last1 == SHADDA:
            marks.pop()
            marks.push(SUKUN)
            marks.push(NOT_DEF_HARAKA)
            letters.push(SHADDA)
        else:
            marks.push(NOT_DEF_HARAKA)
            letters.push(last1)
        last1 = stack1.pop()
    if extract_shadda:
        wordletters = u''.join(letters.items)
        shaddaplaces = re.sub(u'[^%s]' % SHADDA, TATWEEL, wordletters)
        shaddaplaces = re.sub(u'%s%s' % (TATWEEL, SHADDA), SHADDA, shaddaplaces)
        wordletters = strip_shadda(wordletters)
        return (wordletters, u''.join(marks.items), shaddaplaces)
    else:
        return (u''.join(letters.items), u''.join(marks.items))

def joint(letters, marks):
    """joint the letters with the marks
    the length ot letters and marks must be equal
    return word
    @param letters: the word letters
    @type letters: unicode
    @param marks: the word marks
    @type marks: unicode
    @return: word
    @rtype: unicode"""
    if len(letters) != len(marks):
        return ''
    stack_letter = stack.Stack(letters)
    stack_letter.items.reverse()
    stack_mark = stack.Stack(marks)
    stack_mark.items.reverse()
    word_stack = stack.Stack()
    last_letter = stack_letter.pop()
    last_mark = stack_mark.pop()
    vowels = HARAKAT
    while last_letter != None and last_mark != None:
        if last_letter == SHADDA:
            top = word_stack.pop()
            if top not in vowels:
                word_stack.push(top)
            word_stack.push(last_letter)
            if last_mark != NOT_DEF_HARAKA:
                word_stack.push(last_mark)
        else:
            word_stack.push(last_letter)
            if last_mark != NOT_DEF_HARAKA:
                word_stack.push(last_mark)
        last_letter = stack_letter.pop()
        last_mark = stack_mark.pop()
    if not (stack_letter.is_empty() and stack_mark.is_empty()):
        return False
    else:
        return ''.join(word_stack.items)

def shaddalike(partial, fully):
    """If the two words has the same letters and the same harakats,  this fuction return True.
    The first word is partially vocalized, the second is fully
    if the partially contians a shadda, it must be at the same place in the fully


    @param partial: the partially vocalized word
    @type partial: unicode
    @param fully: the fully vocalized word
    @type fully: unicode
    @return: if contains shadda
    @rtype: Boolean"""
    if not has_shadda(partial):
        return True
    elif not has_shadda(fully) and has_shadda(partial):
        return False
    partial = strip_harakat(partial)
    fully = strip_harakat(fully)
    pstack = stack.Stack(partial)
    vstack = stack.Stack(fully)
    plast = pstack.pop()
    vlast = vstack.pop()
    while plast != None and vlast != None:
        if plast == vlast:
            plast = pstack.pop()
            vlast = vstack.pop()
        elif plast == SHADDA and vlast != SHADDA:
            break
        elif plast != SHADDA and vlast == SHADDA:
            vlast = vstack.pop()
        else:
            break
    if not (pstack.is_empty() and vstack.is_empty()):
        return False
    else:
        return True

def reduce_tashkeel(text):
    """Reduce the Tashkeel,  by deleting evident cases.

    @param text: the input text fully vocalized.
    @type text: unicode.
    @return : partially vocalized text.
    @rtype: unicode."""
    patterns = [u'(?<!(%s|%s))(%s|%s)' % (WAW, YEH, SUKUN, FATHA), u'%s(?=%s)' % (DAMMA, WAW), u'%s(?=%s)' % (KASRA, YEH), u'%s(?=%s)' % (FATHA, ALEF), u'(?<=\\s(%s|%s))%s' % (WAW, YEH, FATHA), u'(?<=%s)%s' % (ALEF_HAMZA_BELOW, KASRA)]
    reduced = text
    for pat in patterns:
        reduced = re.sub(pat, '', reduced)
    return reduced

def vocalized_similarity(word1, word2):
    """if the two words has the same letters and the same harakats,  this function return True.
    The two words can be full vocalized, or partial vocalized

    @param word1: first word
    @type word1: unicode
    @param word2: second word
    @type word2: unicode
    @return: return if words are similar, else return negative number of errors
    @rtype: Boolean / int"""
    stack1 = stack.Stack(word1)
    stack2 = stack.Stack(word2)
    last1 = stack1.pop()
    last2 = stack2.pop()
    err_count = 0
    vowels = HARAKAT
    while last1 != None and last2 != None:
        if last1 == last2:
            last1 = stack1.pop()
            last2 = stack2.pop()
        elif last1 in vowels and last2 not in vowels:
            last1 = stack1.pop()
        elif last1 not in vowels and last2 in vowels:
            last2 = stack2.pop()
        elif last1 == SHADDA:
            last1 = stack1.pop()
        elif last2 == SHADDA:
            last2 = stack2.pop()
        else:
            last1 = stack1.pop()
            last2 = stack2.pop()
            err_count += 1
    if err_count > 0:
        return -err_count
    else:
        return True

def tokenize(text=''):
    """Tokenize text into words.

    @param text: the input text.
    @type text: unicode.
    @return: list of words.
    @rtype: list."""
    if text == '':
        return []
    else:
        mylist = TOKEN_PATTERN.split(text)
        mylist = [TOKEN_REPLACE.sub('', x) for x in mylist if x]
        mylist = [x for x in mylist if x]
        return mylist

def tokenize_arabic_words(text):
    """Tokenize text into words
    @param text: the input text.
    @type text: unicode.
    @return: list of words.
    @rtype: list."""
    specific_tokens = []
    if not text:
        return specific_tokens
    else:
        specific_tokens = araby.tokenize(text)
        return specific_tokens

def drop_edge_punct(word: str) -> str:
    """Remove edge punctuation.
    :param word: a single string
    >>> drop_edge_punct("'fieri")
    'fieri'
    >>> drop_edge_punct('sedes.')
    'sedes'"""
    if not word:
        return word
    try:
        if not word[0].isalpha():
            word = word[1:]
        if not word[-1].isalpha():
            word = word[:-1]
    except:
        pass
    return word

def divide_separate_words(string_matrix: List[List[str]]) -> List[List[str]]:
    """As part of processing, some words obviously need to be separated.
    :param string_matrix: a data matrix: a list wrapping a list of strings, with each sublist being a sentence.
    :return:
    >>> divide_separate_words([['ita vero'], ['quid', 'est', 'veritas']])
    [['ita', 'vero'], ['quid', 'est', 'veritas']]"""
    new_X = []
    for sentence in string_matrix:
        data_row = []
        for word in sentence:
            if ' ' in word:
                data_row += word.split()
            else:
                data_row.append(word)
        new_X.append(data_row)
    return new_X

def _unrecognised(achr):
    """Handle unrecognised characters."""
    if options['handleUnrecognised'] == UNRECOGNISED_ECHO:
        return achr
    elif options['handleUnrecognised'] == UNRECOGNISED_SUBSTITUTE:
        return options['substituteChar']
    else:
        raise KeyError(achr)

def tonos_oxia_converter(text, reverse=False):
    """For the Ancient Greek language. Converts characters accented with the
    tonos (meant for Modern Greek) into the oxia equivalent. Without this
    normalization, string comparisons will fail."""
    for char_tonos, char_oxia in TONOS_OXIA.items():
        if not reverse:
            text = text.replace(char_tonos, char_oxia)
        else:
            text = text.replace(char_oxia, char_tonos)
    return text

def transliterate(mode, string, ignore='', reverse=False):
    """encode & decode different  romanization systems
    :param mode:
    :param string:
    :param ignore:
    :param reverse:
    :return:"""
    if mode in available_transliterate_systems():
        MAPPING = ROMANIZATION_SYSTEMS_MAPPINGS[mode]
    else:
        print(mode + '  not supported! \n')
        MAPPING = {}
    if reverse:
        mapping = {}
        for k, v in MAPPING.items():
            mapping[v] = k
    else:
        mapping = MAPPING
    result = ''
    for char in string:
        if char in mapping.keys() and char not in ignore:
            result += mapping[char]
        else:
            result += char
    return result

def eval_str_to_list(input_str: str) -> List[str]:
    """Turn str into str or tuple."""
    inner_cast = ast.literal_eval(input_str)
    if isinstance(inner_cast, list):
        return inner_cast
    else:
        raise ValueError

def scantree(path: str) -> Generator:
    """Recursively yield DirEntry objects for given directory."""
    for entry in os.scandir(path):
        if entry.is_dir(follow_symlinks=False):
            yield from scantree(entry.path)
        elif entry.name.endswith('.py'):
            yield entry

def sort_def_dict(def_dict: Dict[str, List[str]]) -> Dict[str, List[str]]:
    """Sort values of the lists of a defaultdict(list)."""
    for _, dd_list in def_dict.items():
        dd_list.sort()
    return def_dict

def find_write_contribs() -> None:
    """Look for files, find authors, sort, write file."""
    map_file_auth = {}
    for filename in scantree('cltk'):
        filepath = filename.path
        authors_list = get_authors(filepath)
        if authors_list:
            map_file_auth[filepath] = authors_list
    map_auth_file = defaultdict(list)
    for file, authors_file in map_file_auth.items():
        for author in authors_file:
            map_auth_file[author].append(file)
    map_auth_file = sort_def_dict(map_auth_file)
    map_auth_file_sorted = sorted(map_auth_file.items())
    map_auth_file = OrderedDict(map_auth_file_sorted)
    write_contribs(map_auth_file)

def get_paths(src):
    """Generates root-to-leaf paths, given a treebank in string format. Note that
    get_path is an iterator and does not return all the paths simultaneously.

    :param src: str: treebank

    Examples:
        >>> st = "((IP-MAT-SPE (' ') (INTJ Yes) (, ,) (' ') (IP-MAT-PRN (NP-SBJ (PRO he)) (VBD seyde)) (, ,) (' ') (NP-SBJ (PRO I)) (MD shall)  (VB promyse) (NP-OB2 (PRO you)) (IP-INF (TO to) (VB fullfylle) (NP-OB1 (PRO$ youre) (N desyre))) (. .) (' '))"

        Get the sixth generated path:

        >>> list(get_paths(st))[5]
        ['IP-MAT-SPE', 'IP-MAT-PRN', 'VBD', 'seyde']"""
    st = list()
    tmp = ''
    for let in src:
        if let == '(':
            if tmp != '':
                st.append(tmp)
                tmp = ''
        elif let == ')':
            if tmp != '':
                st.append(tmp)
                yield st
            st = st[:-1 - (tmp != '')]
            tmp = ''
        elif let == ' ':
            if tmp != '':
                st.append(tmp)
                tmp = ''
        else:
            tmp += let

def _get_size(size, size_max, size_min, default_max, default_min):
    """Helper method for providing a size,
    or a range to randomize from"""
    if len(default_max) != len(default_min):
        raise ValueError('default_max = {} and default_min = {}'.format(str(default_max), str(default_min)) + ' have different lengths')
    if size is not None:
        if size_max is not None or size_min is not None:
            raise ValueError('size = {} overrides size_max = {}, size_min = {}'.format(size, size_max, size_min))
    else:
        if size_max is None:
            size_max = default_max
        if size_min is None:
            size_min = default_min
        size = np.array([np.random.uniform(size_min[i], size_max[i]) for i in range(len(default_max))])
    return size

def _get_randomized_range(val, provided_range, default_range):
    """Helper to initialize by either value or a range
    Returns a range to randomize from"""
    if val is None:
        if provided_range is None:
            return default_range
        else:
            return provided_range
    else:
        if provided_range is not None:
            raise ValueError('Value {} overrides range {}'.format(str(val), str(provided_range)))
        return [val]

