    raise ValueError('Unkown gripper name {}'.format(name))

def xml_path_completion(xml_path):
    """Takes in a local xml path and returns a full path.
        if @xml_path is absolute, do nothing
        if @xml_path is not absolute, load xml that is shipped by the package"""
    if xml_path.startswith('/'):
        full_path = xml_path
    else:
        full_path = os.path.join(robosuite.models.assets_root, xml_path)
    return full_path

def quat2mat(quaternion):
    """Converts given quaternion (x, y, z, w) to matrix.

    Args:
        quaternion: vec4 float angles

    Returns:
        3x3 rotation matrix"""
    q = np.array(quaternion, dtype=np.float32, copy=True)[[3, 0, 1, 2]]
    n = np.dot(q, q)
    if n < EPS:
        return np.identity(3)
    q *= math.sqrt(2.0 / n)
    q = np.outer(q, q)
    return np.array([[1.0 - q[2, 2] - q[3, 3], q[1, 2] - q[3, 0], q[1, 3] + q[2, 0]], [q[1, 2] + q[3, 0], 1.0 - q[1, 1] - q[3, 3], q[2, 3] - q[1, 0]], [q[1, 3] - q[2, 0], q[2, 3] + q[1, 0], 1.0 - q[1, 1] - q[2, 2]]])

def _skew_symmetric_translation(pos_A_in_B):
    """Helper function to get a skew symmetric translation matrix for converting quantities
    between frames."""
    return np.array([0.0, -pos_A_in_B[2], pos_A_in_B[1], pos_A_in_B[2], 0.0, -pos_A_in_B[0], -pos_A_in_B[1], pos_A_in_B[0], 0.0]).reshape((3, 3))

def make(env_name, *args, **kwargs):
    """Try to get the equivalent functionality of gym.make in a sloppy way."""
    if env_name not in REGISTERED_ENVS:
        raise Exception('Environment {} not found. Make sure it is a registered environment among: {}'.format(env_name, ', '.join(REGISTERED_ENVS)))
    return REGISTERED_ENVS[env_name](*args, **kwargs)

def default(request):
    """Adds additional context variables to the default context."""
    protocol = request.is_secure() and 'wss://' or 'ws://'
    heartbeat_msg = settings.WS4REDIS_HEARTBEAT and '"{0}"'.format(settings.WS4REDIS_HEARTBEAT) or 'null'
    context = {'WEBSOCKET_URI': protocol + request.get_host() + settings.WEBSOCKET_URL, 'WS4REDIS_HEARTBEAT': mark_safe(heartbeat_msg)}
    return context

def store_groups_in_session(sender, user, request, **kwargs):
    """When a user logs in, fetch its groups and store them in the users session.
    This is required by ws4redis, since fetching groups accesses the database, which is a blocking
    operation and thus not allowed from within the websocket loop."""
    if hasattr(user, 'groups'):
        request.session['ws4redis:memberof'] = [g.name for g in user.groups.all()]

def _wrap_users(users, request):
    """Returns a list with the given list of users and/or the currently logged in user, if the list
    contains the magic item SELF."""
    result = set()
    for u in users:
        if u is SELF and is_authenticated(request):
            result.add(request.user.get_username())
        else:
            result.add(u)
    return result

def _wrap_sessions(sessions, request):
    """Returns a list of session keys for the given lists of sessions and/or the session key of the
    current logged in user, if the list contains the magic item SELF."""
    result = set()
    for s in sessions:
        if s is SELF and request:
            result.add(request.session.session_key)
        else:
            result.add(s)
    return result

def field_type(field):
    """Template filter that returns field class name (in lower case).
    E.g. if field is CharField then {{ field|field_type }} will
    return 'charfield'."""
    if hasattr(field, 'field') and field.field:
        return field.field.__class__.__name__.lower()
    return ''

def widget_type(field):
    """Template filter that returns field widget class name (in lower case).
    E.g. if field's widget is TextInput then {{ field|widget_type }} will
    return 'textinput'."""
    if hasattr(field, 'field') and hasattr(field.field, 'widget') and field.field.widget:
        return field.field.widget.__class__.__name__.lower()
    return ''

def import_from_str(value):
    """Attempt to import a class from a string representation."""
    try:
        parts = value.split('.')
        module_path, class_name = ('.'.join(parts[:-1]), parts[-1])
        module = importlib.import_module(module_path)
        return getattr(module, class_name)
    except ImportError as e:
        msg = 'Could not import %s for settings. %s: %s.' % (value, e.__class__.__name__, e)
        raise ImportError(msg)

def get(name, import_str=False):
    """Helper function to use inside the package."""
    value = None
    default_value = getattr(default_settings, name)
    try:
        value = getattr(settings, name)
    except AttributeError:
        if name in default_settings.required_attrs:
            raise Exception('You must set ' + name + ' in your settings.')
    if isinstance(default_value, dict) and value:
        default_value.update(value)
        value = default_value
    else:
        if value is None:
            value = default_value
        value = import_from_str(value) if import_str else value
    return value

def strip_prompt_login(path):
    """Strips 'login' from the 'prompt' query parameter."""
    uri = urlsplit(path)
    query_params = parse_qs(uri.query)
    prompt_list = query_params.get('prompt', '')[0].split()
    if 'login' in prompt_list:
        prompt_list.remove('login')
        query_params['prompt'] = ' '.join(prompt_list)
    if not query_params['prompt']:
        del query_params['prompt']
    uri = uri._replace(query=urlencode(query_params, doseq=True))
    return urlunsplit(uri)

def extract_client_auth(request):
    """Get client credentials using HTTP Basic Authentication method.
    Or try getting parameters via POST.
    See: http://tools.ietf.org/html/rfc6750#section-2.1

    Return a tuple `(client_id, client_secret)`."""
    auth_header = request.META.get('HTTP_AUTHORIZATION', '')
    if re.compile('^Basic\\s{1}.+$').match(auth_header):
        b64_user_pass = auth_header.split()[1]
        try:
            user_pass = b64decode(b64_user_pass).decode('utf-8').split(':')
            client_id, client_secret = tuple(user_pass)
        except Exception:
            client_id = client_secret = ''
    else:
        client_id = request.POST.get('client_id', '')
        client_secret = request.POST.get('client_secret', '')
    return (client_id, client_secret)

def protected_resource_view(scopes=None):
    """View decorator. The client accesses protected resources by presenting the
    access token to the resource server.
    https://tools.ietf.org/html/rfc6749#section-7"""
    if scopes is None:
        scopes = []
    def wrapper(view):
        def view_wrapper(request, *args, **kwargs):
            access_token = extract_access_token(request)
            try:
                try:
                    kwargs['token'] = Token.objects.get(access_token=access_token)
                except Token.DoesNotExist:
                    logger.debug('[UserInfo] Token does not exist: %s', access_token)
                    raise BearerTokenError('invalid_token')
                if kwargs['token'].has_expired():
                    logger.debug('[UserInfo] Token has expired: %s', access_token)
                    raise BearerTokenError('invalid_token')
                if not set(scopes).issubset(set(kwargs['token'].scope)):
                    logger.debug('[UserInfo] Missing openid scope.')
                    raise BearerTokenError('insufficient_scope')
            except BearerTokenError as error:
                response = HttpResponse(status=error.status)
                response['WWW-Authenticate'] = 'error="{0}", error_description="{1}"'.format(error.code, error.description)
                return response
            return view(request, *args, **kwargs)
        return view_wrapper
    return wrapper

def get_site_url(site_url=None, request=None):
    """Construct the site url.

    Orders to decide site url:
        1. valid `site_url` parameter
        2. valid `SITE_URL` in settings
        3. construct from `request` object"""
    site_url = site_url or settings.get('SITE_URL')
    if site_url:
        return site_url
    elif request:
        return '{}://{}'.format(request.scheme, request.get_host())
    else:
        raise Exception('Either pass `site_url`, or set `SITE_URL` in settings, or pass `request` object.')

def get_browser_state_or_default(request):
    """Determine value to use as session state."""
    key = request.session.session_key or settings.get('OIDC_UNAUTHENTICATED_SESSION_MANAGEMENT_KEY')
    return sha224(key.encode('utf-8')).hexdigest()

def encode_id_token(payload, client):
    """Represent the ID Token as a JSON Web Token (JWT).
    Return a hash."""
    keys = get_client_alg_keys(client)
    _jws = JWS(payload, alg=client.jwt_alg)
    return _jws.sign_compact(keys)

def decode_id_token(token, client):
    """Represent the ID Token as a JSON Web Token (JWT).
    Return a hash."""
    keys = get_client_alg_keys(client)
    return JWS().verify_compact(token, keys=keys)

def client_id_from_id_token(id_token):
    """Extracts the client id from a JSON Web Token (JWT).
    Returns a string or None."""
    payload = JWT().unpack(id_token).payload()
    aud = payload.get('aud', None)
    if aud is None:
        return None
    if isinstance(aud, list):
        return aud[0]
    return aud

def get_client_alg_keys(client):
    """Takes a client and returns the set of keys associated with it.
    Returns a list of keys."""
    if client.jwt_alg == 'RS256':
        keys = []
        for rsakey in RSAKey.objects.all():
            keys.append(jwk_RSAKey(key=importKey(rsakey.key), kid=rsakey.kid))
        if not keys:
            raise Exception('You must add at least one RSA Key.')
    elif client.jwt_alg == 'HS256':
        keys = [SYMKey(key=client.client_secret, alg=client.jwt_alg)]
    else:
        raise Exception('Unsupported key algorithm.')
    return keys

def get_all_filelist(data_dir):
    """Returns a tuple containing the following (as lists)

    0. All metadata files
    1. All table basis files
    2. All element basis files
    3. All component basis files

    The paths to all the files are returned as paths relative to data_dir"""
    all_meta = []
    all_table = []
    all_element = []
    all_component = []
    special = ['METADATA.json', 'REFERENCES.json']
    for root, dirs, files in os.walk(data_dir):
        for basename in files:
            if basename in special:
                continue
            fpath = os.path.join(root, basename)
            fpath = os.path.relpath(fpath, data_dir)
            if basename.endswith('.metadata.json'):
                all_meta.append(fpath)
            elif basename.endswith('.table.json'):
                all_table.append(fpath)
            elif basename.endswith('.element.json'):
                all_element.append(fpath)
            elif basename.endswith('.json'):
                all_component.append(fpath)
    return (all_meta, all_table, all_element, all_component)

def read_notes_file(file_path):
    """Returns the contents of a notes file.

    If the notes file does not exist, None is returned"""
    if not os.path.isfile(file_path):
        return None
    with open(file_path, 'r', encoding=_default_encoding) as f:
        return f.read()

def _whole_basis_types(basis):
    """Get a list of all the types of features in this basis set."""
    all_types = set()
    for v in basis['elements'].values():
        if 'electron_shells' in v:
            for sh in v['electron_shells']:
                all_types.add(sh['function_type'])
        if 'ecp_potentials' in v:
            for pot in v['ecp_potentials']:
                all_types.add(pot['ecp_type'])
    return sorted(list(all_types))

def compose_elemental_basis(file_relpath, data_dir):
    """Creates an 'elemental' basis from an elemental json file

    This function reads the info from the given file, and reads all the component
    basis set information from the files listed therein. It then composes all the
    information together into one 'elemental' basis dictionary"""
    el_bs = fileio.read_json_basis(os.path.join(data_dir, file_relpath))
    component_files = set()
    for k, v in el_bs['elements'].items():
        component_files.update(set(v['components']))
    component_map = {k: fileio.read_json_basis(os.path.join(data_dir, k)) for k in component_files}
    for k, v in component_map.items():
        for el, el_data in v['elements'].items():
            el_data['references'] = [{'reference_description': v['description'], 'reference_keys': el_data['references']}]
    for k, v in el_bs['elements'].items():
        components = v.pop('components')
        el_comp_data = []
        for c in components:
            centry = component_map[c]['elements']
            if k not in centry:
                raise RuntimeError('File {} does not contain element {}'.format(c, k))
            el_comp_data.append(centry[k])
        v = manip.merge_element_data(None, el_comp_data)
        el_bs['elements'][k] = v
    return el_bs

def create_skel(role):
    """Create the skeleton of a dictionary or JSON file

    A dictionary is returned that contains the "molssi_bse_schema"
    key and other required keys, depending on the role

    role can be either 'component', 'element', or 'table'"""
    role = role.lower()
    if not role in _skeletons:
        raise RuntimeError("Role {} not found. Should be 'component', 'element', 'table', or 'metadata'")
    return copy.deepcopy(_skeletons[role])

def _validate_extra_component(bs_data):
    """Extra checks for component basis files"""
    assert len(bs_data['elements']) > 0
    for el in bs_data['elements'].values():
        if not 'electron_shells' in el:
            continue
        for s in el['electron_shells']:
            nprim = len(s['exponents'])
            if nprim <= 0:
                raise RuntimeError('Invalid number of primitives: {}'.format(nprim))
            for g in s['coefficients']:
                if nprim != len(g):
                    raise RuntimeError("Number of coefficients doesn't match number of primitives ({} vs {}".format(len(g), nprim))
            nam = len(s['angular_momentum'])
            if nam > 1:
                ngen = len(s['coefficients'])
                if ngen != nam:
                    raise RuntimeError("Number of general contractions doesn't match combined AM ({} vs {}".format(ngen, nam))

def validate_data_dir(data_dir):
    """Validates all files in a data_dir"""
    all_meta, all_table, all_element, all_component = fileio.get_all_filelist(data_dir)
    for f in all_meta:
        full_path = os.path.join(data_dir, f)
        validate_file('metadata', full_path)
    for f in all_table:
        full_path = os.path.join(data_dir, f)
        validate_file('table', full_path)
    for f in all_element:
        full_path = os.path.join(data_dir, f)
        validate_file('element', full_path)
    for f in all_component:
        full_path = os.path.join(data_dir, f)
        validate_file('component', full_path)

def sort_basis_dict(bs):
    """Sorts a basis set dictionary into a standard order

    This, for example, allows the written file to be more easily read by humans by,
    for example, putting the name and description before more detailed fields.

    This is generally for cosmetic reasons. However, users will generally like things
    in a consistent order"""
    _keyorder = ['molssi_bse_schema', 'schema_type', 'schema_version', 'jkfit', 'jfit', 'rifit', 'admmfit', 'dftxfit', 'dftjfit', 'name', 'names', 'aliases', 'flags', 'family', 'description', 'role', 'auxiliaries', 'notes', 'function_types', 'reference_description', 'reference_keys', 'version', 'revision_description', 'data_source', 'elements', 'references', 'ecp_electrons', 'electron_shells', 'ecp_potentials', 'components', 'function_type', 'region', 'angular_momentum', 'exponents', 'coefficients', 'ecp_type', 'angular_momentum', 'r_exponents', 'gaussian_exponents', 'coefficients']
    _keyorder.extend([str(x) for x in range(150)])
    bs_sorted = sorted(bs.items(), key=lambda x: _keyorder.index(x[0]))
    if _use_odict:
        bs_sorted = OrderedDict(bs_sorted)
    else:
        bs_sorted = dict(bs_sorted)
    for k, v in bs_sorted.items():
        if isinstance(v, dict):
            bs_sorted[k] = sort_basis_dict(v)
        elif isinstance(v, list):
            bs_sorted[k] = [sort_basis_dict(x) if isinstance(x, dict) else x for x in v]
    return bs_sorted

def sort_shells(shells, use_copy=True):
    """Sort a list of basis set shells into a standard order

    The order within a shell is by decreasing value of the exponent.

    The order of the shell list is in increasing angular momentum, and then
    by decreasing number of primitives, then decreasing value of the largest exponent.

    If use_copy is True, the input shells are not modified."""
    if use_copy:
        shells = copy.deepcopy(shells)
    shells = [sort_shell(sh, False) for sh in shells]
    return list(sorted(shells, key=lambda x: (max(x['angular_momentum']), -len(x['exponents']), -len(x['coefficients']), -float(max(x['exponents'])))))

def sort_basis(basis, use_copy=True):
    """Sorts all the information in a basis set into a standard order

    If use_copy is True, the input basis set is not modified."""
    if use_copy:
        basis = copy.deepcopy(basis)
    for k, el in basis['elements'].items():
        if 'electron_shells' in el:
            el['electron_shells'] = sort_shells(el['electron_shells'], False)
        if 'ecp_potentials' in el:
            el['ecp_potentials'] = sort_potentials(el['ecp_potentials'], False)
    return sort_basis_dict(basis)

def sort_references_dict(refs):
    """Sorts a reference dictionary into a standard order

    The keys of the references are also sorted, and the keys for the data for each
    reference are put in a more canonical order."""
    if _use_odict:
        refs_sorted = OrderedDict()
    else:
        refs_sorted = dict()
    refs_sorted['molssi_bse_schema'] = refs['molssi_bse_schema']
    for k, v in sorted(refs.items()):
        refs_sorted[k] = sort_single_reference(v)
    return refs_sorted

def _ref_bib(key, ref):
    """Convert a single reference to bibtex format
    """
    s = ''
    s += '@{}{{{},\n'.format(ref['type'], key)
    entry_lines = []
    for k, v in ref.items():
        if k == 'type':
            continue
        if k == 'authors':
            entry_lines.append('    author = {{{}}}'.format(' and '.join(v)))
        elif k == 'editors':
            entry_lines.append('    editor = {{{}}}'.format(' and '.join(v)))
        else:
            entry_lines.append('    {} = {{{}}}'.format(k, v))
    s += ',\n'.join(entry_lines)
    s += '\n}'
    return s

def write_bib(refs):
    """Converts references to bibtex
    """
    full_str = ''
    lib_citation_desc, lib_citations = get_library_citation()
    full_str += '%' * 80 + '\n'
    full_str += textwrap.indent(lib_citation_desc, '% ')
    full_str += '%' * 80 + '\n\n'
    for k, r in lib_citations.items():
        full_str += _ref_bib(k, r) + '\n\n'
    full_str += '%' * 80 + '\n'
    full_str += '% References for the basis set\n'
    full_str += '%' * 80 + '\n'
    unique_refs = {}
    for ref in refs:
        full_str += '% {}\n'.format(compact_elements(ref['elements']))
        for ri in ref['reference_info']:
            full_str += '%     {}\n'.format(ri['reference_description'])
            refdata = ri['reference_data']
            if len(refdata) == 0:
                full_str += '%     (...no reference...)\n%\n'
            else:
                rkeys = [x[0] for x in ri['reference_data']]
                full_str += '%         {}\n%\n'.format(' '.join(rkeys))
            for k, r in refdata:
                unique_refs[k] = r
    full_str += '\n\n'
    for k, r in sorted(unique_refs.items(), key=lambda x: x[0]):
        full_str += '{}\n\n'.format(_ref_bib(k, r))
    return full_str

def component_basis_str(basis, elements=None):
    """Print a component basis set

    If elements is not None, only the specified elements will be printed
    (see :func:`bse.misc.expand_elements`)"""
    s = 'Description: ' + basis['description'] + '\n'
    eldata = basis['elements']
    if elements is None:
        elements = list(eldata.keys())
    else:
        elements = expand_elements(elements, True)
    for z in elements:
        s += element_data_str(z, eldata[z]) + '\n'
    return s

def get_formats(function_types=None):
    """Returns the available formats mapped to display name.

    This is returned as an ordered dictionary, with the most common
    at the top, followed by the rest in alphabetical order

    If a list is specified for function_types, only those formats
    supporting the given function types will be returned."""
    if function_types is None:
        return {k: v['display'] for k, v in _converter_map.items()}
    ftypes = [x.lower() for x in function_types]
    ftypes = set(ftypes)
    ret = []
    for fmt, v in _converter_map.items():
        if v['valid'] is None or ftypes <= v['valid']:
            ret.append(fmt)
    return ret

def get_format_extension(fmt):
    """Returns the recommended extension for a given format"""
    if fmt is None:
        return 'dict'
    fmt = fmt.lower()
    if fmt not in _converter_map:
        raise RuntimeError('Unknown basis set format "{}"'.format(fmt))
    return _converter_map[fmt]['extension']

def get_library_citation():
    """Return a descriptive string and reference data for what users of the library should cite"""
    all_ref_data = api.get_reference_data()
    lib_refs_data = {k: all_ref_data[k] for k in _lib_refs}
    return (_lib_refs_desc, lib_refs_data)

def contraction_string(element):
    """Forms a string specifying the contractions for an element

    ie, (16s,10p) -> [4s,3p]"""
    if 'electron_shells' not in element:
        return ''
    cont_map = dict()
    for sh in element['electron_shells']:
        nprim = len(sh['exponents'])
        ngeneral = len(sh['coefficients'])
        is_spdf = len(sh['angular_momentum']) > 1
        for am in sh['angular_momentum']:
            ncont = ngeneral if not is_spdf else 1
            if am not in cont_map:
                cont_map[am] = (nprim, ncont)
            else:
                cont_map[am] = (cont_map[am][0] + nprim, cont_map[am][1] + ncont)
    primstr = ''
    contstr = ''
    for am in sorted(cont_map.keys()):
        nprim, ncont = cont_map[am]
        if am != 0:
            primstr += ','
            contstr += ','
        primstr += str(nprim) + lut.amint_to_char([am])
        contstr += str(ncont) + lut.amint_to_char([am])
    return '({}) -> [{}]'.format(primstr, contstr)

def compact_elements(elements):
    '''Create a string (with ranges) given a list of element numbers

    For example, [1, 2, 3, 6, 7, 8, 10] will return "H-Li,C-O,Ne"'''
    if len(elements) == 0:
        return
    elements = [int(el) for el in elements]
    el = sorted(set(elements))
    ranges = []
    i = 0
    while i < len(el):
        start_el = el[i]
        end_el = start_el
        i += 1
        while i < len(el):
            if el[i] != end_el + 1:
                break
            end_el += 1
            i += 1
        if start_el == end_el:
            ranges.append([start_el])
        else:
            ranges.append([start_el, end_el])
    range_strs = []
    for r in ranges:
        sym = lut.element_sym_from_Z(r[0], True)
        if len(r) == 1:
            range_strs.append(sym)
        elif len(r) == 2 and r[1] == r[0] + 1:
            sym2 = lut.element_sym_from_Z(r[1], True)
            range_strs.append(sym + ',' + sym2)
        else:
            sym2 = lut.element_sym_from_Z(r[1], True)
            range_strs.append(sym + '-' + sym2)
    return ','.join(range_strs)

def component_file_refs(filelist):
    """Get a list of what elements/refrences exist in component JSON files

    Parameters
    ----------
    filelist : list
        A list of paths to json files

    Returns
    -------
    dict
        Keys are the file path, value is a list of tuples (compacted element string, refs tuple)"""
    ret = {}
    for fpath in filelist:
        filedata = fileio.read_json_basis(fpath)
        refdict = {}
        for el, eldata in filedata['elements'].items():
            refs = tuple(eldata['references'])
            if not refs in refdict:
                refdict[refs] = [el]
            else:
                refdict[refs].append(el)
        entry = []
        for k, v in refdict.items():
            entry.append((misc.compact_elements(v), k))
        ret[fpath] = entry
    return ret

def _fix_uncontracted(basis):
    """Forces the contraction coefficient of uncontracted shells to 1.0"""
    for el in basis['elements'].values():
        if 'electron_shells' not in el:
            continue
        for sh in el['electron_shells']:
            if len(sh['coefficients']) == 1 and len(sh['coefficients'][0]) == 1:
                sh['coefficients'][0][0] = '1.0000000'
            if len(sh['coefficients']) == 0:
                sh['coefficients'].append(['1.0000000'])
    return basis

