def merge_element_data(dest, sources, use_copy=True):
    """Merges the basis set data for an element from multiple sources
    into dest.

    The destination is not modified, and a (shallow) copy of dest is returned
    with the data from sources added.

    If use_copy is True, then the data merged into dest will be a (deep)
    copy of that found in sources. Otherwise, data may be shared between dest
    and sources"""
    if dest is not None:
        ret = dest.copy()
    else:
        ret = {}
    if use_copy:
        sources = copy.deepcopy(sources)
    for s in sources:
        if 'electron_shells' in s:
            if 'electron_shells' not in ret:
                ret['electron_shells'] = []
            ret['electron_shells'].extend(s['electron_shells'])
        if 'ecp_potentials' in s:
            if 'ecp_potentials' in ret:
                raise RuntimeError('Cannot overwrite existing ECP')
            ret['ecp_potentials'] = s['ecp_potentials']
            ret['ecp_electrons'] = s['ecp_electrons']
        if 'references' in s:
            if 'references' not in ret:
                ret['references'] = []
            for ref in s['references']:
                if not ref in ret['references']:
                    ret['references'].append(ref)
    return ret

def prune_basis(basis, use_copy=True):
    """Removes primitives that have a zero coefficient, and
    removes duplicate primitives and shells

    This only finds EXACT duplicates, and is meant to be used
    after other manipulations

    If use_copy is True, the input basis set is not modified."""
    if use_copy:
        basis = copy.deepcopy(basis)
    for k, el in basis['elements'].items():
        if not 'electron_shells' in el:
            continue
        shells = el.pop('electron_shells')
        shells = [prune_shell(sh, False) for sh in shells]
        el['electron_shells'] = []
        for sh in shells:
            if sh not in el['electron_shells']:
                el['electron_shells'].append(sh)
    return basis

def uncontract_general(basis, use_copy=True):
    """Removes the general contractions from a basis set

    The input basis set is not modified. The returned basis
    may have functions with coefficients of zero and may have duplicate
    shells.

    If use_copy is True, the input basis set is not modified."""
    if use_copy:
        basis = copy.deepcopy(basis)
    for k, el in basis['elements'].items():
        if not 'electron_shells' in el:
            continue
        newshells = []
        for sh in el['electron_shells']:
            if len(sh['coefficients']) == 1 or len(sh['angular_momentum']) > 1:
                newshells.append(sh)
            elif len(sh['angular_momentum']) == 1:
                for c in sh['coefficients']:
                    newsh = sh.copy()
                    newsh['coefficients'] = [c]
                    newshells.append(newsh)
        el['electron_shells'] = newshells
    return prune_basis(basis, False)

def _reldiff(a, b):
    """Computes the relative difference of two floating-point numbers

    rel = abs(a-b)/min(abs(a), abs(b))

    If a == 0 and b == 0, then 0.0 is returned
    Otherwise if a or b is 0.0, inf is returned."""
    a = float(a)
    b = float(b)
    aa = abs(a)
    ba = abs(b)
    if a == 0.0 and b == 0.0:
        return 0.0
    elif a == 0 or b == 0.0:
        return float('inf')
    return abs(a - b) / min(aa, ba)

def _compare_matrix(mat1, mat2, rel_tol):
    """Compares two matrices (nested python lists) for approximate equality.

    Each matrix contains floats or strings convertible to floats

    This function returns True if both matrices are of the same dimensions
    and each value is within the given relative tolerance."""
    length = len(mat1)
    if len(mat2) != length:
        return False
    for i in range(length):
        if _compare_vector(mat1[i], mat2[i], rel_tol) is False:
            return False
    return True

def compare_electron_shells(shell1, shell2, compare_meta=False, rel_tol=0.0):
    """Compare two electron shells for approximate equality
    (exponents/coefficients are within a tolerance)

    If compare_meta is True, the metadata is also compared for exact equality."""
    if shell1['angular_momentum'] != shell2['angular_momentum']:
        return False
    tmp1 = list(zip(shell1['exponents'], *shell1['coefficients']))
    tmp2 = list(zip(shell2['exponents'], *shell2['coefficients']))
    tmp1 = sorted(tmp1)
    tmp2 = sorted(tmp2)
    if not _compare_matrix(tmp1, tmp2, rel_tol):
        return False
    if compare_meta:
        if shell1['region'] != shell2['region']:
            return False
        if shell1['function_type'] != shell2['function_type']:
            return False
        return True
    else:
        return True

def electron_shells_are_subset(subset, superset, compare_meta=False, rel_tol=0.0):
    """Determine if a list of electron shells is a subset of another

    If 'subset' is a subset of the 'superset', True is returned.

    The shells are compared approximately (exponents/coefficients are
    within a tolerance)

    If compare_meta is True, the metadata is also compared for exact equality."""
    for item1 in subset:
        for item2 in superset:
            if compare_electron_shells(item1, item2, compare_meta, rel_tol):
                break
        else:
            return False
    return True

def electron_shells_are_equal(shells1, shells2, compare_meta=False, rel_tol=0.0):
    """Determine if a list of electron shells is the same as another

    The shells are compared approximately (exponents/coefficients are
    within a tolerance)

    If compare_meta is True, the metadata is also compared for exact equality."""
    if len(shells1) != len(shells2):
        return False
    return electron_shells_are_subset(shells1, shells2, compare_meta, rel_tol) and electron_shells_are_subset(shells2, shells1, compare_meta, rel_tol)

def compare_ecp_pots(potential1, potential2, compare_meta=False, rel_tol=0.0):
    """Compare two ecp potentials for approximate equality
    (exponents/coefficients are within a tolerance)

    If compare_meta is True, the metadata is also compared for exact equality."""
    if potential1['angular_momentum'] != potential2['angular_momentum']:
        return False
    rexponents1 = potential1['r_exponents']
    rexponents2 = potential2['r_exponents']
    gexponents1 = potential1['gaussian_exponents']
    gexponents2 = potential2['gaussian_exponents']
    coefficients1 = potential1['coefficients']
    coefficients2 = potential2['coefficients']
    if rexponents1 != rexponents2:
        return False
    if not _compare_vector(gexponents1, gexponents2, rel_tol):
        return False
    if not _compare_matrix(coefficients1, coefficients2, rel_tol):
        return False
    if compare_meta:
        if potential1['ecp_type'] != potential2['ecp_type']:
            return False
        return True
    else:
        return True

def ecp_pots_are_subset(subset, superset, compare_meta=False, rel_tol=0.0):
    """Determine if a list of ecp potentials is a subset of another

    If 'subset' is a subset of the 'superset', True is returned.

    The potentials are compared approximately (exponents/coefficients are
    within a tolerance)

    If compare_meta is True, the metadata is also compared for exact equality."""
    for item1 in subset:
        for item2 in superset:
            if compare_ecp_pots(item1, item2, compare_meta, rel_tol):
                break
        else:
            return False
    return True

def ecp_pots_are_equal(pots1, pots2, compare_meta=False, rel_tol=0.0):
    """Determine if a list of electron shells is the same as another

    The potentials are compared approximately (exponents/coefficients are
    within a tolerance)

    If compare_meta is True, the metadata is also compared for exact equality."""
    return ecp_pots_are_subset(pots1, pots2, compare_meta) and ecp_pots_are_subset(pots2, pots1, compare_meta)

def subtract_electron_shells(s1, s2, rel_tol=0.0):
    """Returns the difference between two lists of electron shells (s1 - s2)

    This will remove any shells from s1 that are also in s2, within a tolerance"""
    diff_shells = []
    for sh1 in s1:
        for sh2 in s2:
            if compare_electron_shells(sh1, sh2, rel_tol=rel_tol):
                break
        else:
            diff_shells.append(copy.deepcopy(sh1))
    return diff_shells

