def httpdo(url, method='GET', data=None):
    """Do HTTP Request"""
    start = time.time()
    if isinstance(data, dict):
        data = json.dumps(data)
    if DEBUG:
        print("Shell: curl -X {method} -d '{data}' '{url}'".format(method=method.upper(), data=data or '', url=url))
    try:
        response = requests.request(method, url, data=data, timeout=HTTP_TIMEOUT)
    except (requests.exceptions.ConnectionError, requests.exceptions.ReadTimeout):
        time.sleep(1.0)
        response = requests.request(method, url, data=data, timeout=HTTP_TIMEOUT)
    if DEBUG:
        ms = (time.time() - start) * 1000
        print('Return ({:.0f}ms): {}'.format(ms, response.text))
    try:
        retjson = response.json()
    except ValueError as e:
        raise ValueError(e, response.text)
    r = convert(retjson)
    if r.status != 0:
        raise WDAError(r.status, r.value)
    return r

def get_version():
    """Parse current version number from __init__.py"""
    version = None
    init_py = os.path.join(os.path.dirname(__file__), 'asv', '__init__.py')
    with open(init_py, 'r') as f:
        source = f.read()
    tree = ast.parse(source)
    for statement in tree.body:
        if isinstance(statement, ast.Assign) and len(statement.targets) == 1 and (statement.targets[0].id == '__version__'):
            version = statement.value.s
            break
    if not version:
        raise RuntimeError('Failed to parse version from {}'.format(init_py))
    if 'dev' in version and (not version.endswith('.dev')):
        raise RuntimeError("Dev version string in {} doesn't end in .dev".format(init_py))
    return version

def get_git_hash():
    """Get version from asv/__init__.py and generate asv/_version.py"""
    githash = ''
    if os.path.isdir(os.path.join(basedir, '.git')):
        try:
            proc = subprocess.Popen(['git', '-C', basedir, 'rev-parse', 'HEAD'], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            rev, err = proc.communicate()
            if proc.returncode == 0:
                githash = rev.strip().decode('ascii')
        except OSError:
            pass
    return githash

def solve_potts_approx(y, w, gamma=None, min_size=1, **kw):
    """Fit penalized stepwise constant function (Potts model) to data
    approximatively, in linear time.

    Do this by running the exact solver using a small maximum interval
    size, and then combining consecutive intervals together if it
    decreases the cost function."""
    n = len(y)
    if n == 0:
        return ([], [], [])
    mu_dist = kw.get('mu_dist')
    if mu_dist is None:
        mu_dist = get_mu_dist(y, w)
        kw['mu_dist'] = mu_dist
    if gamma is None:
        mu, dist = (mu_dist.mu, mu_dist.dist)
        gamma = 3 * dist(0, n - 1) * math.log(n) / n
    if min_size < 10:
        max_size = 20
    else:
        max_size = min_size + 50
    right, values, dists = solve_potts(y, w, gamma, min_size=min_size, max_size=max_size, **kw)
    return merge_pieces(gamma, right, values, dists, mu_dist, max_size=max_size)

def weighted_median(y, w):
    """Compute weighted median of `y` with weights `w`."""
    items = sorted(zip(y, w))
    midpoint = sum(w) / 2
    yvals = []
    wsum = 0
    for yy, ww in items:
        wsum += ww
        if wsum > midpoint:
            yvals.append(yy)
            break
        elif wsum == midpoint:
            yvals.append(yy)
    else:
        yvals = y
    return sum(yvals) / len(yvals)

def _calcsize(fmt):
    """struct.calcsize() handling 'z' for Py_ssize_t.
    """
    if _sizeof_Clong < _sizeof_Cvoidp:
        z = 'P'
    else:
        z = 'L'
    return calcsize(fmt.replace('z', z))

def _basicsize(t, base=0, heap=False, obj=None):
    """Get non-zero basicsize of type,
    including the header sizes."""
    s = max(getattr(t, '__basicsize__', 0), base)
    if t != _Type_type:
        h = getattr(t, '__flags__', 0) & _Py_TPFLAGS_HAVE_GC
    elif heap:
        h = True
    else:
        h = getattr(obj, '__flags__', 0) & _Py_TPFLAGS_HEAPTYPE
    if h:
        s += _sizeof_CPyGC_Head
    return s + _sizeof_Crefcounts

def _dir2(obj, pref='', excl=(), slots=None, itor=''):
    """Return an attribute name, object 2-tuple for certain
    attributes or for the ``__slots__`` attributes of the
    given object, but not both.  Any iterator referent
    objects are returned with the given name if the
    latter is non-empty."""
    if slots:
        if hasattr(obj, slots):
            s = {}
            for c in type(obj).mro():
                for a in getattr(c, slots, ()):
                    if hasattr(obj, a):
                        s.setdefault(a, getattr(obj, a))
            yield (slots, _Slots(s))
            for t in _items(s):
                yield t
    elif itor:
        for o in obj:
            yield (itor, o)
    else:
        for a in dir(obj):
            if a.startswith(pref) and a not in excl and hasattr(obj, a):
                yield (a, getattr(obj, a))

def _infer_dict(obj):
    """Return True for likely dict object.
    """
    for ats in (('__len__', 'get', 'has_key', 'items', 'keys', 'values'), ('__len__', 'get', 'has_key', 'iteritems', 'iterkeys', 'itervalues')):
        for a in ats:
            if not _callable(getattr(obj, a, None)):
                break
        else:
            return True
    return False

def _issubclass(sub, sup):
    """Safe issubclass().
    """
    if sup is not object:
        try:
            return issubclass(sub, sup)
        except TypeError:
            pass
    return False

def _lengstr(obj):
    """Object length as a string.
    """
    n = leng(obj)
    if n is None:
        r = ''
    elif n > _len(obj):
        r = ' leng %d!' % n
    else:
        r = ' leng %d' % n
    return r

def _objs_opts(objs, all=None, **opts):
    """Return given or 'all' objects
    and the remaining options."""
    if objs:
        t = objs
    elif all in (False, None):
        t = ()
    elif all is True:
        t = tuple(_values(sys.modules)) + (globals(), stack(sys.getrecursionlimit())[2:])
    else:
        raise ValueError('invalid option: %s=%r' % ('all', all))
    return (t, opts)

def _p100(part, total, prec=1):
    """Return percentage as string.
    """
    r = float(total)
    if r:
        r = part * 100.0 / r
        return '%.*f%%' % (prec, r)
    return 'n/a'

def _printf(fmt, *args, **print3opts):
    """Formatted print.
    """
    if print3opts:
        f = print3opts.get('file', None) or sys.stdout
        if args:
            f.write(fmt % args)
        else:
            f.write(fmt)
        f.write(print3opts.get('end', linesep))
    elif args:
        print(fmt % args)
    else:
        print(fmt)

def _refs(obj, named, *ats, **kwds):
    """Return specific attribute objects of an object.
    """
    if named:
        for a in ats:
            if hasattr(obj, a):
                yield _NamedRef(a, getattr(obj, a))
        if kwds:
            for a, o in _dir2(obj, **kwds):
                yield _NamedRef(a, o)
    else:
        for a in ats:
            if hasattr(obj, a):
                yield getattr(obj, a)
        if kwds:
            for _, o in _dir2(obj, **kwds):
                yield o

def _repr(obj, clip=80):
    """Clip long repr() string.
    """
    try:
        r = repr(obj)
    except TypeError:
        r = 'N/A'
    if 0 < clip < len(r):
        h = clip // 2 - 2
        if h > 0:
            r = r[:h] + '....' + r[-h:]
    return r

def _SI(size, K=1024, i='i'):
    """Return size as SI string.
    """
    if 1 < K < size:
        f = float(size)
        for si in iter('KMGPTE'):
            f /= K
            if f < K:
                return ' or %.1f %s%sB' % (f, si, i)
    return ''

def _dict_refs(obj, named):
    """Return key and value objects of a dict/proxy.
    """
    if named:
        for k, v in _items(obj):
            s = str(k)
            yield _NamedRef('[K] ' + s, k)
            yield _NamedRef('[V] ' + s + ': ' + _repr(v), v)
    else:
        for k, v in _items(obj):
            yield k
            yield v

def _iter_refs(obj, named):
    """Return the referent(s) of an iterator object.
    """
    r = _getreferents(obj)
    return _refs(r, named, itor=_nameof(obj) or 'iteref')

def _module_refs(obj, named):
    """Return specific referents of a module object.
    """
    if obj.__name__ == __name__:
        return ()
    return _dict_refs(obj.__dict__, named)

def _len_dict(obj):
    """Dict length in items (estimate).
    """
    n = len(obj)
    if n < 6:
        n = 0
    else:
        n = _power2(n + 1)
    return n

def _len_frame(obj):
    """Length of a frame object.
    """
    c = getattr(obj, 'f_code', None)
    if c:
        n = _len_code(c)
    else:
        n = 0
    return n

def _len_int(obj):
    """Length of multi-precision int (aka long) in digits.
    """
    if obj:
        n, i = (1, abs(obj))
        if i > _digitmax:
            n += int(log(i) * _digitlog)
    else:
        n = 0
    return n

def _len_iter(obj):
    """Length (hint) of an iterator.
    """
    n = getattr(obj, '__length_hint__', None)
    if n:
        n = n()
    else:
        n = _len(obj)
    return n

def _len_list(obj):
    """Length of list (estimate).
    """
    n = len(obj)
    if n > 8:
        n += 6 + (n >> 3)
    elif n:
        n += 4
    return n

def _len_set(obj):
    """Length of frozen/set (estimate).
    """
    n = len(obj)
    if n > 8:
        n = _power2(n + n - 2)
    elif n:
        n = 8
    return n

def _len_slice(obj):
    """Slice length.
    """
    try:
        return (obj.stop - obj.start + 1) // obj.step
    except (AttributeError, TypeError):
        return 0

def adict(*classes):
    """Install one or more classes to be handled as dict.
    """
    a = True
    for c in classes:
        if isclass(c) and _infer_dict(c):
            t = _dict_classes.get(c.__module__, ())
            if c.__name__ not in t:
                _dict_classes[c.__module__] = t + (c.__name__,)
        else:
            a = False
    return a

def _typedefof(obj, save=False, **opts):
    """Get the typedef for an object.
    """
    k = _objkey(obj)
    v = _typedefs.get(k, None)
    if not v:
        v = _typedef(obj, **opts)
        if save:
            _typedefs[k] = v
    return v

def flatsize(obj, align=0, **opts):
    """Return the flat size of an object (in bytes),
    optionally aligned to a given power of 2.

    See function **basicsize** for a description of
    the other options.  See the documentation of
    this module for the definition of flat size."""
    v = _typedefof(obj, **opts)
    if v:
        if align > 1:
            m = align - 1
            if align & m != 0:
                raise ValueError('invalid option: %s=%r' % ('align', align))
        else:
            m = 0
        v = v.flat(obj, m)
    return v

def leng(obj, **opts):
    """Return the length of an object (in items).

    See function **basicsize** for a description of
    the options."""
    v = _typedefof(obj, **opts)
    if v:
        v = v.leng
        if v and _callable(v):
            v = v(obj)
    return v

def named_refs(obj):
    """Return all named referents of `obj`. Reuse functionality from asizeof.
    Does not return referents without a name, e.g. objects in a list."""
    refs = []
    v = _typedefof(obj)
    if v:
        v = v.refs
        if v and _callable(v):
            for ref in v(obj, True):
                try:
                    refs.append((ref.name, ref.ref))
                except AttributeError:
                    pass
    return refs

def recvall(sock, size):
    """Receive data of given size from a socket connection"""
    data = b''
    while len(data) < size:
        s = sock.recv(size - len(data))
        data += s
        if not s:
            raise RuntimeError('did not receive data from socket (size {}, got only {!r})'.format(size, data))
    return data

def get_source_code(items):
    """Extract source code of given items, and concatenate and dedent it."""
    sources = []
    prev_class_name = None
    for func in items:
        try:
            lines, lineno = inspect.getsourcelines(func)
        except TypeError:
            continue
        if not lines:
            continue
        src = '\n'.join((line.rstrip() for line in lines))
        src = textwrap.dedent(src)
        class_name = None
        if inspect.ismethod(func):
            if hasattr(func, 'im_class'):
                class_name = func.im_class.__name__
            elif hasattr(func, '__qualname__'):
                names = func.__qualname__.split('.')
                if len(names) > 1:
                    class_name = names[-2]
        if class_name and prev_class_name != class_name:
            src = 'class {0}:\n    {1}'.format(class_name, src.replace('\n', '\n    '))
        elif class_name:
            src = '    {1}'.format(class_name, src.replace('\n', '\n    '))
        sources.append(src)
        prev_class_name = class_name
    return '\n\n'.join(sources).rstrip()

def disc_modules(module_name, ignore_import_errors=False):
    """Recursively import a module and all sub-modules in the package

    Yields
    ------
    module
        Imported module in the package tree"""
    if not ignore_import_errors:
        module = import_module(module_name)
    else:
        try:
            module = import_module(module_name)
        except BaseException:
            traceback.print_exc()
            return
    yield module
    if getattr(module, '__path__', None):
        for _, name, _ in pkgutil.iter_modules(module.__path__, module_name + '.'):
            for item in disc_modules(name, ignore_import_errors=ignore_import_errors):
                yield item

def disc_benchmarks(root, ignore_import_errors=False):
    """Discover all benchmarks in a given directory tree, yielding Benchmark
    objects

    For each class definition, looks for any methods with a
    special name.

    For each free function, yields all functions with a special
    name."""
    root_name = os.path.basename(root)
    for module in disc_modules(root_name, ignore_import_errors=ignore_import_errors):
        for attr_name, module_attr in ((k, v) for k, v in module.__dict__.items() if not k.startswith('_')):
            if inspect.isclass(module_attr):
                for name, class_attr in inspect.getmembers(module_attr):
                    if inspect.isfunction(class_attr) or inspect.ismethod(class_attr):
                        benchmark = _get_benchmark(name, module, module_attr, class_attr)
                        if benchmark is not None:
                            yield benchmark
            elif inspect.isfunction(module_attr):
                benchmark = _get_benchmark(attr_name, module, None, module_attr)
                if benchmark is not None:
                    yield benchmark

def _etree_py26_write(f, tree):
    """Compatibility workaround for ElementTree shipped with py2.6"""
    f.write("<?xml version='1.0' encoding='utf-8'?>\n".encode('utf-8'))
    if etree.VERSION[:3] == '1.2':
        def fixtag(tag, namespaces):
            if tag == XML_NS + 'lang':
                return ('xml:lang', '')
            if '}' in tag:
                j = tag.index('}') + 1
                tag = tag[j:]
                xmlns = ''
            if tag == 'feed':
                xmlns = ('xmlns', str('http://www.w3.org/2005/Atom'))
                namespaces['http://www.w3.org/2005/Atom'] = 'xmlns'
            return (tag, xmlns)
    else:
        fixtag = etree.fixtag
    old_fixtag = etree.fixtag
    etree.fixtag = fixtag
    try:
        tree.write(f, encoding=str('utf-8'))
    finally:
        etree.fixtag = old_fixtag

def _get_id(owner, date, content):
    """Generate an unique Atom id for the given content"""
    h = hashlib.sha256()
    h.update('github.com/spacetelescope/asv'.encode('utf-8'))
    for x in content:
        if x is None:
            h.update(','.encode('utf-8'))
        else:
            h.update(x.encode('utf-8'))
        h.update(','.encode('utf-8'))
    if date is None:
        date = datetime.datetime(1970, 1, 1)
    return 'tag:{0},{1}:/{2}'.format(owner, date.strftime('%Y-%m-%d'), h.hexdigest())

def _EvaluateExpression(frame, expression):
    """Compiles and evaluates watched expression.

    Args:
      frame: evaluation context.
      expression: watched expression to compile and evaluate.

    Returns:
      (False, status) on error or (True, value) on success."""
    try:
        code = compile(expression, '<watched_expression>', 'eval')
    except (TypeError, ValueError) as e:
        return (False, {'isError': True, 'refersTo': 'VARIABLE_NAME', 'description': {'format': 'Invalid expression', 'parameters': [str(e)]}})
    except SyntaxError as e:
        return (False, {'isError': True, 'refersTo': 'VARIABLE_NAME', 'description': {'format': 'Expression could not be compiled: $0', 'parameters': [e.msg]}})
    try:
        return (True, native.CallImmutable(frame, code))
    except BaseException as e:
        return (False, {'isError': True, 'refersTo': 'VARIABLE_VALUE', 'description': {'format': 'Exception occurred: $0', 'parameters': [str(e)]}})

def _FormatMessage(template, parameters):
    """Formats the message. Unescapes '$$' with '$'.

    Args:
      template: message template (e.g. 'a = $0, b = $1').
      parameters: substitution parameters for the format.

    Returns:
      Formatted message with parameters embedded in template placeholders."""
    def GetParameter(m):
        try:
            return parameters[int(m.group(0)[1:])]
        except IndexError:
            return INVALID_EXPRESSION_INDEX
    parts = template.split('$$')
    return '$'.join((re.sub('\\$\\d+', GetParameter, part) for part in parts))

def Read(f):
    """Reads and returns Config data from a yaml file.

    Args:
      f: Yaml file to parse.

    Returns:
      Config object as defined in this file.

    Raises:
      Error (some subclass): If there is a problem loading or parsing the file."""
    try:
        yaml_data = yaml.load(f)
    except yaml.YAMLError as e:
        raise ParseError('%s' % e)
    except IOError as e:
        raise YAMLLoadError('%s' % e)
    _CheckData(yaml_data)
    try:
        return Config(yaml_data.get('blacklist', ()), yaml_data.get('whitelist', '*'))
    except UnicodeDecodeError as e:
        raise YAMLLoadError('%s' % e)

def _CheckData(yaml_data):
    """Checks data for illegal keys and formatting."""
    legal_keys = set(('blacklist', 'whitelist'))
    unknown_keys = set(yaml_data) - legal_keys
    if unknown_keys:
        raise UnknownConfigKeyError('Unknown keys in configuration: %s' % unknown_keys)
    for key, data in six.iteritems(yaml_data):
        _AssertDataIsList(key, data)

def _AssertDataIsList(key, lst):
    """Assert that lst contains list data and is not structured."""
    if not isinstance(lst, list) and (not isinstance(lst, tuple)):
        raise NotAListError('%s must be a list' % key)
    for element in lst:
        if not isinstance(element, str):
            raise ElementNotAStringError('Unsupported list element %s found in %s', (element, lst))

def _NormalizePath(path):
    """Removes surrounding whitespace, leading separator and normalize."""
    return os.path.normpath(path.strip().lstrip(os.sep))

def _GetVisibilityPolicy():
    """If a debugger configuration is found, create a visibility policy."""
    try:
        visibility_config = yaml_data_visibility_config_reader.OpenAndRead()
    except yaml_data_visibility_config_reader.Error as err:
        return error_data_visibility_policy.ErrorDataVisibilityPolicy('Could not process debugger config: %s' % err)
    if visibility_config:
        return glob_data_visibility_policy.GlobDataVisibilityPolicy(visibility_config.blacklist_patterns, visibility_config.whitelist_patterns)
    return None

def PrettyPrinter(obj):
    """Pretty printers for AppEngine objects."""
    if ndb and isinstance(obj, ndb.Model):
        return (six.iteritems(obj.to_dict()), 'ndb.Model(%s)' % type(obj).__name__)
    if messages and isinstance(obj, messages.Enum):
        return ([('name', obj.name), ('number', obj.number)], type(obj).__name__)
    return None

def GetCodeObjectAtLine(module, line):
    """Searches for a code object at the specified line in the specified module.

    Args:
      module: module to explore.
      line: 1-based line number of the statement.

    Returns:
      (True, Code object) on success or (False, (prev_line, next_line)) on
      failure, where prev_line and next_line are the closest lines with code above
      and below the specified line, or None if they do not exist."""
    if not hasattr(module, '__file__'):
        return (False, (None, None))
    prev_line = 0
    next_line = six.MAXSIZE
    for code_object in _GetModuleCodeObjects(module):
        for co_line_number in _GetLineNumbers(code_object):
            if co_line_number == line:
                return (True, code_object)
            elif co_line_number < line:
                prev_line = max(prev_line, co_line_number)
            elif co_line_number > line:
                next_line = min(next_line, co_line_number)
                break
    prev_line = None if prev_line == 0 else prev_line
    next_line = None if next_line == six.MAXSIZE else next_line
    return (False, (prev_line, next_line))

def _IncrementNestLevel():
    """Increments the per thread nest level of imports."""
    if getattr(_import_local, 'nest_level', None) is None:
        _import_local.nest_level = 0
    if _import_local.nest_level == 0:
        _import_local.names = set()
    _import_local.nest_level += 1

def _ImportModuleHookBySuffix(name, package=None):
    """Callback when a module is imported through importlib.import_module."""
    _IncrementNestLevel()
    try:
        module = _real_import_module(name, package)
    finally:
        if name.startswith('.'):
            if package:
                name = _ResolveRelativeImport(name, package)
            else:
                name = None
        if name:
            _ProcessImportBySuffix(name, None, None)
    return module

