def _split(string, splitters):
    """Splits a string into parts at multiple characters"""
    part = ''
    for character in string:
        if character in splitters:
            yield part
            part = ''
        else:
            part += character
    yield part

def _hash(number, alphabet):
    """Hashes `number` using the given `alphabet` sequence."""
    hashed = ''
    len_alphabet = len(alphabet)
    while True:
        hashed = alphabet[number % len_alphabet] + hashed
        number //= len_alphabet
        if not number:
            return hashed

def _deprecated(func):
    """A decorator that warns about deprecation when the passed-in function is
    invoked."""
    @wraps(func)
    def with_warning(*args, **kwargs):
        warnings.warn('The %s method is deprecated and will be removed in v2.*.*' % func.__name__, DeprecationWarning)
        return func(*args, **kwargs)
    return with_warning

def TriArea(v_init, f, normalize):
    """Returns a Ch object whose only attribute "v" represents the flattened vertices."""
    if normalize:
        nm = lambda x: NormalizedNx3(x)
    else:
        nm = lambda x: x
    result = Ch(lambda v: Sum3xN(CrossProduct(TriEdges(f, 1, 0, nm(v)), TriEdges(f, 2, 0, nm(v))) ** 2.0) ** 0.5 * 0.5)
    result.v = v_init
    return result

def AcosTriAngles(v, f, normalize):
    """Returns a Ch object whose only attribute "v" represents the flattened vertices."""
    if normalize:
        nm = lambda x: NormalizedNx3(x)
    else:
        nm = lambda x: x
    return Ch(lambda v: Sum3xN(NormalizedNx3(TriEdges(f, 1, 0, nm(v))) * NormalizedNx3(TriEdges(f, 2, 0, nm(v)))) & Sum3xN(NormalizedNx3(TriEdges(f, 2, 1, nm(v))) * NormalizedNx3(TriEdges(f, 0, 1, nm(v)))) & Sum3xN(NormalizedNx3(TriEdges(f, 0, 2, nm(v))) * NormalizedNx3(TriEdges(f, 1, 2, nm(v)))))

def get_vert_opposites_per_edge(mesh_v, mesh_f):
    """Returns a dictionary from vertidx-pairs to opposites.
    For example, a key consist of [4,5)] meaning the edge between
    vertices 4 and 5, and a value might be [10,11] which are the indices
    of the vertices opposing this edge."""
    result = {}
    for f in mesh_f:
        for i in range(3):
            key = [f[i], f[(i + 1) % 3]]
            key.sort()
            key = tuple(key)
            val = f[(i + 2) % 3]
            if key in result:
                result[key].append(val)
            else:
                result[key] = [val]
    return result

def js_map_loader(url):
    """Load map data from a .js source. It is designed for using highcharts' map collection:
    https://code.highcharts.com/mapdata/. Map data from other sources are not guaranteed"""
    hdr = {'User-Agent': 'Mozilla/5.0 (Windows NT 6.1) AppleWebKit/535.7 (KHTML, like Gecko) Chrome/16.0.912.77 Safari/535.7'}
    req = urllib.request.Request(url, headers=hdr)
    page = urlopen(req)
    result = page.read().decode('utf-8')
    result = result[len(re.search('^.* = ', result).group()):]
    return json.loads(result)

def _safe_attr(attr, camel_killer=False, replacement_char='x'):
    """Convert a key into something that is accessible as an attribute"""
    allowed = string.ascii_letters + string.digits + '_'
    attr = _safe_key(attr)
    if camel_killer:
        attr = _camel_killer(attr)
    attr = attr.replace(' ', '_')
    out = ''
    for character in attr:
        out += character if character in allowed else '_'
    out = out.strip('_')
    try:
        int(out[0])
    except (ValueError, IndexError):
        pass
    else:
        out = '{0}{1}'.format(replacement_char, out)
    if out in kwlist:
        out = '{0}{1}'.format(replacement_char, out)
    return re.sub('_+', '_', out)

def _camel_killer(attr):
    """CamelKiller, qu'est-ce que c'est?

    Taken from http://stackoverflow.com/a/1176023/3244542"""
    try:
        attr = str(attr)
    except UnicodeEncodeError:
        attr = attr.encode('utf-8', 'ignore')
    s1 = _first_cap_re.sub('\\1_\\2', attr)
    s2 = _all_cap_re.sub('\\1_\\2', s1)
    return re.sub('_+', '_', s2.casefold() if hasattr(s2, 'casefold') else s2.lower())

def send_command():
    """Run a remote command. This is called via py3-cmd utility.

    We look for any uds sockets with the correct name prefix and send our
    command to all that we find.  This allows us to communicate with multiple
    py3status instances."""
    def verbose(msg):
        """print output if verbose is set."""
        if options.verbose:
            print(msg)
    options = command_parser()
    msg = json.dumps(vars(options)).encode('utf-8')
    if len(msg) > MAX_SIZE:
        verbose('Message length too long, max length (%s)' % MAX_SIZE)
    uds_list = glob.glob('{}.[0-9]*'.format(SERVER_ADDRESS))
    verbose('message "%s"' % msg)
    for uds in uds_list:
        sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        verbose('connecting to %s' % uds)
        try:
            sock.connect(uds)
        except socket.error:
            verbose('stale socket deleting')
            try:
                os.unlink(uds)
            except OSError:
                pass
            continue
        try:
            verbose('sending')
            sock.sendall(msg)
        finally:
            verbose('closing socket')
            sock.close()

def contains_bad_glyph(glyph_data, data):
    """Pillow only looks for glyphs in the font used so we need to make sure our
    font has the glygh.  Although we could substitute a glyph from another font
    eg symbola but this adds more complexity and is of limited value."""
    def check_glyph(char):
        for cmap in glyph_data['cmap'].tables:
            if cmap.isUnicode():
                if char in cmap.cmap:
                    return True
        return False
    for part in data:
        text = part.get('full_text', '')
        try:
            text = text.decode('utf8')
        except AttributeError:
            pass
        for char in text:
            if not check_glyph(ord(char)):
                print(u'%s (%s) missing' % (char, ord(char)))
                return True
    return False

def parse_sample_data(sample_data, module_name):
    """Parse sample output definitions and return a dict
    {screenshot_name: sample_output}"""
    samples = {}
    for index, chunk in enumerate(sample_data.split('\n\n')):
        chunk = '{}-{}-{}'.format(module_name, index, chunk)
        name, sample = re.split('-?\n', chunk, 1)
        try:
            samples[name] = ast.literal_eval(sample)
        except SyntaxError:
            samples[name] = SAMPLE_DATA_ERROR
    return samples

def get_samples():
    """Look in all core modules and get any samples from the docstrings.
    return a dict {screenshot_name: sample_output}"""
    samples = {}
    module_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'modules')
    for file in sorted(os.listdir(module_dir)):
        if file.endswith('.py') and file != '__init__.py':
            module_name = file[:-3]
            with open(os.path.join(module_dir, file), 'r') as f:
                try:
                    module = ast.parse(f.read())
                except SyntaxError:
                    continue
                raw_docstring = ast.get_docstring(module)
                if raw_docstring is None:
                    continue
                parts = re.split('^SAMPLE OUTPUT$', raw_docstring, flags=re.M)
                if len(parts) == 1:
                    continue
                sample_data = parts[1]
                samples.update(parse_sample_data(sample_data, module_name))
    return samples

def process(name, path, data, module=True):
    """Process data to create a screenshot which will be saved in
    docs/screenshots/<name>.png
    If module is True the screenshot will include the name and py3status."""
    try:
        os.makedirs(path)
    except OSError:
        pass
    global font, glyph_data
    if font is None:
        font = ImageFont.truetype(FONT, FONT_SIZE * SCALE)
    if glyph_data is None:
        glyph_data = TTFont(font.path)
    if not isinstance(data, list):
        data = [data]
    if contains_bad_glyph(glyph_data, data):
        print('** %s has characters not in %s **' % (name, font.getname()[0]))
    else:
        create_screenshot(name, data, path, font=font, is_module=module)

def create_screenshots(quiet=False):
    """create screenshots for all core modules.
    The screenshots directory will have all .png files deleted before new shots
    are created."""
    if os.environ.get('READTHEDOCS') == 'True':
        path = '../doc/screenshots'
    else:
        path = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), 'doc/screenshots')
    print('Creating screenshots...')
    samples = get_samples()
    for name, data in sorted(samples.items()):
        process(name, path, data)

def catch_factory(attr):
    """Factory returning a catch function"""
    def _catch(s, *args, **kw):
        """This is used to catch and process all calls."""
        def process(value):
            """return the actual value after processing"""
            if attr.startswith('__'):
                return getattr(value, attr)(*args, **kw)
            else:
                return getattr(u''.__class__, attr)(value, *args, **kw)
        stack = inspect.stack()
        mod = inspect.getmodule(stack[1][0])
        if mod.__name__.split('.')[-1] == s._module_name:
            return process(s._value)
        if len(stack) < 3:
            return process(s._private)
        remote = not inspect.getmodule(stack[2][0]).__name__.startswith('py3status')
        valid = False
        for frame in stack[2:]:
            mod = inspect.getmodule(frame[0])
            if remote and mod.__name__.split('.')[-1] == s._module_name:
                valid = True
                break
            if mod.__name__ == 'py3status.py3' and frame[3] == 'request':
                valid = True
                break
            if mod.__name__.startswith('py3status'):
                return process(s._private)
        if valid:
            return process(s._value)
        return process(s._private)
    return _catch

def get_backends():
    """Get backends info so that we can find the correct one.
    We just look in the directory structure to find modules."""
    IGNORE_DIRS = ['core', 'tools', 'utils']
    global backends
    if backends is None:
        backends = {}
        i3pystatus_dir = os.path.dirname(i3pystatus.__file__)
        subdirs = [x for x in next(os.walk(i3pystatus_dir))[1] if not x.startswith('_') and x not in IGNORE_DIRS]
        for subdir in subdirs:
            dirs = next(os.walk(os.path.join(i3pystatus_dir, subdir)))[2]
            backends.update({x[:-3]: 'i3pystatus.%s.%s' % (subdir, x[:-3]) for x in dirs if not x.startswith('_') and x.endswith('.py')})
    return backends

def markdown_2_rst(lines):
    """Convert markdown to restructured text"""
    out = []
    code = False
    for line in lines:
        if line.strip() == '```':
            code = not code
            space = ' ' * (len(line.rstrip()) - 3)
            if code:
                out.append('\n\n%s.. code-block:: none\n\n' % space)
            else:
                out.append('\n')
        else:
            if code and line.strip():
                line = '    ' + line
            else:
                line = line.replace('\\', '\\\\')
            out.append(line)
    return out

def screenshots(screenshots_data, module_name):
    """Create .rst output for any screenshots a module may have."""
    shots = screenshots_data.get(module_name)
    if not shots:
        return ''
    out = []
    for shot in file_sort(shots):
        if not os.path.exists('../doc/screenshots/%s.png' % shot):
            continue
        out.append(u'\n.. image:: screenshots/{}.png\n\n'.format(shot))
    return u''.join(out)

