def get_variable_docstrings(filename):
    """Go through the file and find all documented variables.
    That is ones that have a literal expression following them.

    Also get a dict of assigned values so that we can substitute constants."""
    def walk_node(parent, values=None, prefix=''):
        """walk the ast searching for docstrings/values"""
        docstrings = {}
        if values is None:
            values = {}
        key = None
        for node in ast.iter_child_nodes(parent):
            if isinstance(node, ast.ClassDef):
                docs = walk_node(node, values, prefix + node.name + '.')[0]
                docstrings[node.name] = docs
            elif isinstance(node, ast.Assign):
                key = node.targets[0].id
                if isinstance(node.value, ast.Num):
                    values[key] = node.value.n
                if isinstance(node.value, ast.Str):
                    values[key] = node.value.s
                if isinstance(node.value, ast.Name):
                    if node.value.id in values:
                        values[prefix + key] = values[node.value.id]
            elif isinstance(node, ast.Expr) and key:
                docstrings[key] = node.value.s
            else:
                key = None
        return (docstrings, values)
    with open(filename, 'r') as f:
        source = f.read()
    return walk_node(ast.parse(source))

def auto_undent(string):
    """Unindent a docstring."""
    lines = string.splitlines()
    while lines[0].strip() == '':
        lines = lines[1:]
        if not lines:
            return []
    spaces = len(lines[0]) - len(lines[0].lstrip(' '))
    out = []
    for line in lines:
        num_spaces = len(line) - len(line.lstrip(' '))
        out.append(line[min(spaces, num_spaces):])
    return out

def modules_directory():
    """Get the core modules directory."""
    return os.path.join(os.path.dirname(os.path.abspath(__file__)), 'modules')

def parse_readme():
    """Crude parsing of modules/README.md
    returns a dict of {<module_name>: <documentation>}"""
    name = None
    re_mod = re.compile('^\\#\\#\\# <a name="(?P<name>[a-z_0-9]+)"></a>')
    readme_file = os.path.join(modules_directory(), 'README.md')
    modules_dict = {}
    with open(readme_file) as f:
        for row in f.readlines():
            match = re_mod.match(row)
            if match:
                name = match.group('name')
                modules_dict[name] = []
                continue
            if row.startswith('---'):
                name = None
                continue
            if name:
                modules_dict[name].append(row)
    return modules_dict

def _reformat_docstring(doc, format_fn, code_newline=''):
    """Go through lines of file and reformat using format_fn"""
    out = []
    status = {'listing': False, 'add_line': False, 'eat_line': False}
    code = False
    for line in doc:
        if status['add_line']:
            out.append('\n')
        status['add_line'] = False
        if status['eat_line']:
            status['eat_line'] = False
            if line.strip() == '':
                continue
        if line.strip() == '```':
            code = not code
            out.append(line + code_newline)
            continue
        if not code:
            if line.rstrip() == '':
                status['listing'] = False
            line = format_fn(line, status)
            if re_listing.match(line):
                status['listing'] = True
        out.append(line.rstrip() + '\n')
    return out

def _to_docstring(doc):
    """format from Markdown to docstring"""
    def format_fn(line, status):
        """format function"""
        line = re_to_tag.sub('<\\1>', line)
        if re_to_data.match(line):
            line = re_to_data.sub('@\\1 ', line)
            status['eat_line'] = True
        line = re_to_defaults.sub('\\1', line)
        if status['listing']:
            if re_to_param.match(line):
                line = re_to_param.sub('    \\1: ', line)
            elif re_to_status.match(line):
                line = re_to_status.sub('    \\1 ', line)
            elif re_to_item.match(line):
                line = re_to_item.sub('    -', line)
            else:
                line = ' ' * 8 + line.lstrip()
        return line
    return _reformat_docstring(doc, format_fn)

def _from_docstring_md(doc):
    """format from docstring to Markdown"""
    def format_fn(line, status):
        """format function"""
        def fix_tags(line):
            def fn(match):
                found = match.group(1)
                if found == '<':
                    return '&lt;'
                if found == '>':
                    return '&gt;'
                if found == '&':
                    return '&amp;'
                return match.group(0)
            return re_from_tag.sub(fn, line)
        if re_from_data.match(line):
            line = re_from_data.sub('**\\1** ', line)
            status['add_line'] = True
        line = re_from_defaults.sub('*\\1*', line)
        if status['listing']:
            if re_from_param.match(line):
                m = re_from_param.match(line)
                line = '  - `{}` {}'.format(m.group(1), fix_tags(m.group(3)))
            elif re_from_status.match(line):
                m = re_from_status.match(line)
                line = '  - `{}` {}'.format(m.group(1), fix_tags(m.group(3)))
            elif re_from_item.match(line):
                line = re_from_item.sub('  -', fix_tags(line))
            else:
                line = fix_tags(line)
                line = ' ' * 4 + line.lstrip()
        else:
            line = fix_tags(line)
        return line
    return _reformat_docstring(doc, format_fn, code_newline='\n')

def _from_docstring_rst(doc):
    """format from docstring to ReStructured Text"""
    def format_fn(line, status):
        """format function"""
        if re_from_data.match(line):
            line = re_from_data.sub('**\\1** ', line)
            status['add_line'] = True
        line = re_from_defaults.sub('*\\1*', line)
        if status['listing']:
            if re_from_param.match(line):
                m = re_from_param.match(line)
                line = '  - ``{}`` {}'.format(m.group(1), m.group(3))
            elif re_from_status.match(line):
                m = re_from_status.match(line)
                line = '  - ``{}`` {}'.format(m.group(1), m.group(3))
            elif re_from_item.match(line):
                line = re_from_item.sub('  -', line)
            else:
                line = ' ' * 4 + line.lstrip()
        line = re_lone_backtick.sub('``', line)
        return line
    return _reformat_docstring(doc, format_fn, code_newline='\n')

def update_docstrings():
    """update the docstring of each module using info in the
    modules/README.md file"""
    modules_dict = parse_readme()
    files = {}
    for mod in modules_dict:
        mod_file = os.path.join(modules_directory(), mod + '.py')
        with open(mod_file) as f:
            files[mod] = f.readlines()
    for mod in files:
        replaced = False
        done = False
        lines = False
        out = []
        quotes = None
        for row in files[mod]:
            if not quotes:
                if row.strip().startswith('"""'):
                    quotes = '"""'
                if row.strip().startswith("'''"):
                    quotes = "'''"
            if quotes and row.strip().startswith(quotes) and (not done):
                out.append(row)
                if not replaced:
                    out = out + [''.join(_to_docstring(modules_dict[mod])).strip() + '\n']
                    replaced = True
                if lines:
                    done = True
                if not done and (not lines):
                    lines = True
                continue
            if not lines or done:
                out.append(row)
        mod_file = os.path.join(modules_directory(), mod + '.py')
        with open(mod_file, 'w') as f:
            f.writelines(out)
    print_stderr('Modules updated from README.md')

def check_docstrings(show_diff=False, config=None, mods=None):
    """Check docstrings in module match the README.md"""
    readme = parse_readme()
    modules_readme = core_module_docstrings(config=config)
    warned = False
    if create_readme(readme) != create_readme(modules_readme):
        for module in sorted(readme):
            if mods and module not in mods:
                continue
            err = None
            if module not in modules_readme:
                err = 'Module {} in README but not in /modules'.format(module)
            elif ''.join(readme[module]).strip() != ''.join(modules_readme[module]).strip():
                err = 'Module {} docstring does not match README'.format(module)
            if err:
                if not warned:
                    print_stderr('Documentation does not match!\n')
                    warned = True
                print_stderr(err)
        for module in modules_readme:
            if mods and module not in mods:
                continue
            if module not in readme:
                print_stderr('Module {} in /modules but not in README'.format(module))
        if show_diff:
            print_stderr('\n'.join(difflib.unified_diff(create_readme(readme).split('\n'), create_readme(modules_readme).split('\n'))))
        elif warned:
            print_stderr('\nUse `py3-cmd docstring --diff` to view diff.')

def update_readme_for_modules(modules):
    """Update README.md updating the sections for the module names listed."""
    readme = parse_readme()
    module_docstrings = core_module_docstrings()
    if modules == ['__all__']:
        modules = core_module_docstrings().keys()
    for module in modules:
        if module in module_docstrings:
            print_stderr('Updating README.md for module {}'.format(module))
            readme[module] = module_docstrings[module]
        else:
            print_stderr('Module {} not in core modules'.format(module))
    readme_file = os.path.join(modules_directory(), 'README.md')
    with open(readme_file, 'w') as f:
        f.write(create_readme(readme))

def show_modules(config, modules_list):
    """List modules available optionally with details."""
    details = config['full']
    core_mods = not config['user']
    user_mods = not config['core']
    modules = core_module_docstrings(include_core=core_mods, include_user=user_mods, config=config)
    new_modules = []
    if modules_list:
        from fnmatch import fnmatch
        for _filter in modules_list:
            for name in modules.keys():
                if fnmatch(name, _filter):
                    if name not in new_modules:
                        new_modules.append(name)
    else:
        new_modules = modules.keys()
    for name in sorted(new_modules):
        module = _to_docstring(modules[name])
        desc = module[0][:-1]
        if details:
            dash_len = len(name) + 4
            print('#' * dash_len)
            print('# {} #'.format(name))
            print('#' * dash_len)
            for description in module:
                print(description[:-1])
        else:
            print('%-22s %s' % (name, desc))

def get_overall_binding_key_to_binding_maps(bindings_lists):
    """bindings_lists from lowest to highest priority.  Last item in
    bindings_lists is assumed explicit."""
    binding_key_to_binding = {}
    collided_binding_key_to_bindings = {}
    for index, bindings in enumerate(bindings_lists):
        is_final_index = index == len(bindings_lists) - 1
        handle_binding_collision_fn = {True: _handle_explicit_binding_collision, False: _handle_implicit_binding_collision}[is_final_index]
        this_binding_key_to_binding, this_collided_binding_key_to_bindings = _get_binding_key_to_binding_maps(bindings, handle_binding_collision_fn)
        for good_binding_key in this_binding_key_to_binding:
            collided_binding_key_to_bindings.pop(good_binding_key, None)
        binding_key_to_binding.update(this_binding_key_to_binding)
        collided_binding_key_to_bindings.update(this_collided_binding_key_to_bindings)
    return (binding_key_to_binding, collided_binding_key_to_bindings)

def get_provider_fn_decorations(provider_fn, default_arg_names):
    """Retrieves the provider method-relevant info set by decorators.

    If any info wasn't set by decorators, then defaults are returned.

    Args:
      provider_fn: a (possibly decorated) provider function
      default_arg_names: the (possibly empty) arg names to use if none were
          specified via @provides()
    Returns:
      a sequence of ProviderDecoration"""
    if hasattr(provider_fn, _IS_WRAPPER_ATTR):
        provider_decorations = getattr(provider_fn, _PROVIDER_DECORATIONS_ATTR)
        if provider_decorations:
            expanded_provider_decorations = []
            for provider_decoration in provider_decorations:
                if provider_decoration.in_scope_id is None:
                    provider_decoration.in_scope_id = scoping.DEFAULT_SCOPE
                if provider_decoration.arg_name is not None:
                    expanded_provider_decorations.append(provider_decoration)
                else:
                    expanded_provider_decorations.extend([ProviderDecoration(default_arg_name, provider_decoration.annotated_with, provider_decoration.in_scope_id) for default_arg_name in default_arg_names])
            return expanded_provider_decorations
    return [ProviderDecoration(default_arg_name, annotated_with=None, in_scope_id=scoping.DEFAULT_SCOPE) for default_arg_name in default_arg_names]

def new(arg_name, annotated_with=None):
    """Creates a BindingKey.

    Args:
      arg_name: the name of the bound arg
      annotation: an Annotation, or None to create an unannotated binding key
    Returns:
      a new BindingKey"""
    if annotated_with is not None:
        annotation = annotations.Annotation(annotated_with)
    else:
        annotation = annotations.NO_ANNOTATION
    return BindingKey(arg_name, annotation)

def __setkey(key):
    """Set up the key schedule from the encryption key."""
    global C, D, KS, E
    shifts = (1, 1, 2, 2, 2, 2, 2, 2, 1, 2, 2, 2, 2, 2, 2, 1)
    for i in range(28):
        C[i] = key[PC1_C[i] - 1]
        D[i] = key[PC1_D[i] - 1]
    for i in range(16):
        for k in range(shifts[i]):
            temp = C[0]
            for j in range(27):
                C[j] = C[j + 1]
            C[27] = temp
            temp = D[0]
            for j in range(27):
                D[j] = D[j + 1]
            D[27] = temp
        for j in range(24):
            KS[i][j] = C[PC2_C[j] - 1]
            KS[i][j + 24] = D[PC2_D[j] - 28 - 1]
    for i in range(48):
        E[i] = e2[i]

def date_parse(s):
    """Parses value of a DATE type.
    :param s: string to parse into date
    :return: an instance of datetime.date
    :raises NotSupportedError when a date Before Christ is encountered"""
    s = as_str(s)
    if s.endswith(' BC'):
        raise errors.NotSupportedError('Dates Before Christ are not supported. Got: {0}'.format(s))
    return date(*map(lambda x: min(int(x), 9999), s.split('-')))

def as_bytes(bytes_or_text, encoding='utf-8'):
    """Converts either bytes or unicode to `bytes`, using utf-8 encoding for text.
    Args:
      bytes_or_text: A `bytes`, `str`, or `unicode` object.
      encoding: A string indicating the charset for encoding unicode.
    Returns:
      A `bytes` object.
    Raises:
      TypeError: If `bytes_or_text` is not a binary or unicode string."""
    if isinstance(bytes_or_text, _six.text_type):
        return bytes_or_text.encode(encoding)
    elif isinstance(bytes_or_text, bytes):
        return bytes_or_text
    else:
        raise TypeError('Expected binary or unicode string, got %r' % (bytes_or_text,))

def as_text(bytes_or_text, encoding='utf-8'):
    """Returns the given argument as a unicode string.
    Args:
      bytes_or_text: A `bytes`, `str, or `unicode` object.
      encoding: A string indicating the charset for decoding unicode.
    Returns:
      A `unicode` (Python 2) or `str` (Python 3) object.
    Raises:
      TypeError: If `bytes_or_text` is not a binary or unicode string."""
    if isinstance(bytes_or_text, _six.text_type):
        return bytes_or_text
    elif isinstance(bytes_or_text, bytes):
        return bytes_or_text.decode(encoding)
    else:
        raise TypeError('Expected binary or unicode string, got %r' % bytes_or_text)

def getTypeName(data_type_oid, type_modifier):
    """Returns the base type name according to data_type_oid and type_modifier"""
    if data_type_oid == VerticaType.BOOL:
        return 'Boolean'
    elif data_type_oid == VerticaType.INT8:
        return 'Integer'
    elif data_type_oid == VerticaType.FLOAT8:
        return 'Float'
    elif data_type_oid == VerticaType.CHAR:
        return 'Char'
    elif data_type_oid in (VerticaType.VARCHAR, VerticaType.UNKNOWN):
        return 'Varchar'
    elif data_type_oid == VerticaType.LONGVARCHAR:
        return 'Long Varchar'
    elif data_type_oid == VerticaType.DATE:
        return 'Date'
    elif data_type_oid == VerticaType.TIME:
        return 'Time'
    elif data_type_oid == VerticaType.TIMETZ:
        return 'TimeTz'
    elif data_type_oid == VerticaType.TIMESTAMP:
        return 'Timestamp'
    elif data_type_oid == VerticaType.TIMESTAMPTZ:
        return 'TimestampTz'
    elif data_type_oid in (VerticaType.INTERVAL, VerticaType.INTERVALYM):
        return 'Interval ' + getIntervalRange(data_type_oid, type_modifier)
    elif data_type_oid == VerticaType.BINARY:
        return 'Binary'
    elif data_type_oid == VerticaType.VARBINARY:
        return 'Varbinary'
    elif data_type_oid == VerticaType.LONGVARBINARY:
        return 'Long Varbinary'
    elif data_type_oid == VerticaType.NUMERIC:
        return 'Numeric'
    elif data_type_oid == VerticaType.UUID:
        return 'Uuid'
    else:
        return 'Unknown'

def getIntervalLeadingPrecision(data_type_oid, type_modifier):
    """Returns the leading precision for an interval, which is the largest number
    of digits that can fit in the leading field of the interval.

    All Year/Month intervals are defined in terms of months, even if the
    type_modifier forbids months to be specified (i.e. INTERVAL YEAR).
    Similarly, all Day/Time intervals are defined as a number of microseconds.
    Because of this, interval types with shorter ranges will have a larger
    leading precision.

    For example, an INTERVAL DAY's leading precision is
    ((2^63)-1)/MICROSECS_PER_DAY, while an INTERVAL HOUR's leading precision
    is ((2^63)-1)/MICROSECS_PER_HOUR"""
    interval_range = getIntervalRange(data_type_oid, type_modifier)
    if interval_range in ('Year', 'Year to Month'):
        return 18
    elif interval_range == 'Month':
        return 19
    elif interval_range in ('Day', 'Day to Hour', 'Day to Minute', 'Day to Second'):
        return 9
    elif interval_range in ('Hour', 'Hour to Minute', 'Hour to Second'):
        return 10
    elif interval_range in ('Minute', 'Minute to Second'):
        return 12
    elif interval_range == 'Second':
        return 13
    else:
        raise ValueError('Invalid interval range: {}'.format(interval_range))

def getPrecision(data_type_oid, type_modifier):
    """Returns the precision for the given Vertica type with consideration of
    the type modifier.

    For numerics, precision is the total number of digits (in base 10) that can
    fit in the type.

    For intervals, time and timestamps, precision is the number of digits to the
    right of the decimal point in the seconds portion of the time.

    The type modifier of -1 is used when the size of a type is unknown. In those
    cases we assume the maximum possible size."""
    if data_type_oid == VerticaType.NUMERIC:
        if type_modifier == -1:
            return 1024
        return type_modifier - 4 >> 16 & 65535
    elif data_type_oid in (VerticaType.TIME, VerticaType.TIMETZ, VerticaType.TIMESTAMP, VerticaType.TIMESTAMPTZ, VerticaType.INTERVAL, VerticaType.INTERVALYM):
        if type_modifier == -1:
            return 6
        return type_modifier & 15
    else:
        return None

def to_unicode(value):
    """Converts a string argument to a unicode string.
    If the argument is already a unicode string or None, it is returned
    unchanged.  Otherwise it must be a byte string and is decoded as utf8."""
    if isinstance(value, _TO_UNICODE_TYPES):
        return value
    if not isinstance(value, bytes):
        raise TypeError('Expected bytes, unicode, or None; got %r' % type(value))
    return value.decode('utf-8')

def __remove_internal_loggers(logger_to_update, disableStderrLogger=True):
    """Remove the internal loggers (e.g. stderr logger and file logger) from the specific logger
    :param logger_to_update: the logger to remove internal loggers from
    :param disableStderrLogger: should the default stderr logger be disabled? defaults to True"""
    for handler in list(logger_to_update.handlers):
        if hasattr(handler, LOGZERO_INTERNAL_LOGGER_ATTR):
            if isinstance(handler, RotatingFileHandler):
                logger_to_update.removeHandler(handler)
            elif isinstance(handler, SysLogHandler):
                logger_to_update.removeHandler(handler)
            elif isinstance(handler, logging.StreamHandler) and disableStderrLogger:
                logger_to_update.removeHandler(handler)

def autodiscover():
    """Auto-discover INSTALLED_APPS translation.py modules and fail silently when
    not present. This forces an import on them to register.
    Also import explicit modules."""
    import os
    import sys
    import copy
    from django.utils.module_loading import module_has_submodule
    from modeltranslation.translator import translator
    from modeltranslation.settings import TRANSLATION_FILES, DEBUG
    from importlib import import_module
    from django.apps import apps
    mods = [(app_config.name, app_config.module) for app_config in apps.get_app_configs()]
    for app, mod in mods:
        module = '%s.translation' % app
        before_import_registry = copy.copy(translator._registry)
        try:
            import_module(module)
        except:
            translator._registry = before_import_registry
            if module_has_submodule(mod, 'translation'):
                raise
    for module in TRANSLATION_FILES:
        import_module(module)
    if DEBUG:
        try:
            if sys.argv[1] in ('runserver', 'runserver_plus'):
                models = translator.get_registered_models()
                names = ', '.join((m.__name__ for m in models))
                print('modeltranslation: Registered %d models for translation (%s) [pid: %d].' % (len(models), names, os.getpid()))
        except IndexError:
            pass

def register(model_or_iterable, **options):
    """Registers the given model(s) with the given translation options.

    The model(s) should be Model classes, not instances.

    Fields declared for translation on a base class are inherited by
    subclasses. If the model or one of its subclasses is already
    registered for translation, this will raise an exception.

    @register(Author)
    class AuthorTranslation(TranslationOptions):
        pass"""
    from modeltranslation.translator import translator, TranslationOptions
    def wrapper(opts_class):
        if not issubclass(opts_class, TranslationOptions):
            raise ValueError('Wrapped class must subclass TranslationOptions.')
        translator.register(model_or_iterable, opts_class, **options)
        return opts_class
    return wrapper

def get_language():
    """Return an active language code that is guaranteed to be in
    settings.LANGUAGES (Django does not seem to guarantee this for us)."""
    lang = _get_language()
    if lang is None:
        return settings.DEFAULT_LANGUAGE
    if lang not in settings.AVAILABLE_LANGUAGES and '-' in lang:
        lang = lang.split('-')[0]
    if lang in settings.AVAILABLE_LANGUAGES:
        return lang
    return settings.DEFAULT_LANGUAGE

def build_css_class(localized_fieldname, prefix=''):
    """Returns a css class based on ``localized_fieldname`` which is easily
    splitable and capable of regionalized language codes.

    Takes an optional ``prefix`` which is prepended to the returned string."""
    bits = localized_fieldname.split('_')
    css_class = ''
    if len(bits) == 1:
        css_class = str(localized_fieldname)
    elif len(bits) == 2:
        css_class = '-'.join(bits)
    elif len(bits) > 2:
        css_class = _join_css_class(bits, 2)
        if not css_class:
            css_class = _join_css_class(bits, 1)
    return '%s-%s' % (prefix, css_class) if prefix else css_class

def resolution_order(lang, override=None):
    """Return order of languages which should be checked for parameter language.
    First is always the parameter language, later are fallback languages.
    Override parameter has priority over FALLBACK_LANGUAGES."""
    if not settings.ENABLE_FALLBACKS:
        return (lang,)
    if override is None:
        override = {}
    fallback_for_lang = override.get(lang, settings.FALLBACK_LANGUAGES.get(lang, ()))
    fallback_def = override.get('default', settings.FALLBACK_LANGUAGES['default'])
    order = (lang,) + fallback_for_lang + fallback_def
    return tuple(unique(order))

def parse_field(setting, field_name, default):
    """Extract result from single-value or dict-type setting like fallback_values."""
    if isinstance(setting, dict):
        return setting.get(field_name, default)
    else:
        return setting

def append_translated(model, fields):
    """If translated field is encountered, add also all its translation fields."""
    fields = set(fields)
    from modeltranslation.translator import translator
    opts = translator.get_options_for_model(model)
    for key, translated in opts.fields.items():
        if key in fields:
            fields = fields.union((f.name for f in translated))
    return fields

def append_lookup_key(model, lookup_key):
    """Transform spanned__lookup__key into all possible translation versions, on all levels"""
    pieces = lookup_key.split('__', 1)
    fields = append_translated(model, (pieces[0],))
    if len(pieces) > 1:
        fields_to_trans_models = get_fields_to_translatable_models(model)
        if pieces[0] in fields_to_trans_models:
            transmodel = fields_to_trans_models[pieces[0]]
            rest = append_lookup_key(transmodel, pieces[1])
            fields = set(('__'.join(pr) for pr in itertools.product(fields, rest)))
        else:
            fields = set(('%s__%s' % (f, pieces[1]) for f in fields))
    return fields

def add_translation_fields(model, opts):
    """Monkey patches the original model class to provide additional fields for
    every language.

    Adds newly created translation fields to the given translation options."""
    model_empty_values = getattr(opts, 'empty_values', NONE)
    for field_name in opts.local_fields.keys():
        field_empty_value = parse_field(model_empty_values, field_name, NONE)
        for l in mt_settings.AVAILABLE_LANGUAGES:
            translation_field = create_translation_field(model=model, field_name=field_name, lang=l, empty_value=field_empty_value)
            localized_field_name = build_localized_fieldname(field_name, l)
            if hasattr(model, localized_field_name):
                for cls in model.__mro__:
                    if hasattr(cls, '_meta') and cls.__dict__.get(localized_field_name, None):
                        cls_opts = translator._get_options_for_model(cls)
                        if not cls._meta.abstract or field_name not in cls_opts.local_fields:
                            raise ValueError("Error adding translation field. Model '%s' already contains a field named '%s'." % (model._meta.object_name, localized_field_name))
            model.add_to_class(localized_field_name, translation_field)
            opts.add_translation_field(field_name, translation_field)
    if len(opts.local_fields) == 0:
        model._meta._expire_cache()
        model._meta.get_fields()

def patch_clean_fields(model):
    """Patch clean_fields method to handle different form types submission."""
    old_clean_fields = model.clean_fields
    def new_clean_fields(self, exclude=None):
        if hasattr(self, '_mt_form_pending_clear'):
            for field_name, value in self._mt_form_pending_clear.items():
                field = self._meta.get_field(field_name)
                orig_field_name = field.translated_field.name
                if orig_field_name in exclude:
                    field.save_form_data(self, value, check=False)
            delattr(self, '_mt_form_pending_clear')
        old_clean_fields(self, exclude)
    model.clean_fields = new_clean_fields

def patch_get_deferred_fields(model):
    """Django >= 1.8: patch detecting deferred fields. Crucial for only/defer to work."""
    if not hasattr(model, 'get_deferred_fields'):
        return
    old_get_deferred_fields = model.get_deferred_fields
    def new_get_deferred_fields(self):
        sup = old_get_deferred_fields(self)
        if hasattr(self, '_fields_were_deferred'):
            sup.update(self._fields_were_deferred)
        return sup
    model.get_deferred_fields = new_get_deferred_fields

def patch_refresh_from_db(model):
    """Django >= 1.10: patch refreshing deferred fields. Crucial for only/defer to work."""
    if not hasattr(model, 'refresh_from_db'):
        return
    old_refresh_from_db = model.refresh_from_db
    def new_refresh_from_db(self, using=None, fields=None):
        if fields is not None:
            fields = append_translated(self.__class__, fields)
        return old_refresh_from_db(self, using, fields)
    model.refresh_from_db = new_refresh_from_db

def patch_related_object_descriptor_caching(ro_descriptor):
    """Patch SingleRelatedObjectDescriptor or ReverseSingleRelatedObjectDescriptor to use
    language-aware caching."""
    class NewSingleObjectDescriptor(LanguageCacheSingleObjectDescriptor, ro_descriptor.__class__):
        pass
    if django.VERSION[0] == 2:
        ro_descriptor.related.get_cache_name = partial(NewSingleObjectDescriptor.get_cache_name, ro_descriptor)
    ro_descriptor.accessor = ro_descriptor.related.get_accessor_name()
    ro_descriptor.__class__ = NewSingleObjectDescriptor

def get_version(version=None):
    """Returns a PEP 386-compliant version number from VERSION."""
    if version is None:
        from modeltranslation import VERSION as version
    else:
        assert len(version) == 5
        assert version[3] in ('alpha', 'beta', 'rc', 'final')
    parts = 2 if version[2] == 0 else 3
    main = '.'.join((str(x) for x in version[:parts]))
    sub = ''
    if version[3] == 'alpha' and version[4] == 0:
        git_changeset = get_git_changeset()
        if git_changeset:
            sub = '.dev%s' % git_changeset
    elif version[3] != 'final':
        mapping = {'alpha': 'a', 'beta': 'b', 'rc': 'rc'}
        sub = mapping[version[3]] + str(version[4])
    return str(main + sub)

def docs(**kwargs):
    """Annotate the decorated view function with the specified Swagger
    attributes.

    Usage:

    .. code-block:: python

        from aiohttp import web

        @docs(tags=['my_tag'],
              summary='Test method summary',
              description='Test method description',
              parameters=[{
                      'in': 'header',
                      'name': 'X-Request-ID',
                      'schema': {'type': 'string', 'format': 'uuid'},
                      'required': 'true'
                  }]
              )
        async def index(request):
            return web.json_response({'msg': 'done', 'data': {}})"""
    def wrapper(func):
        kwargs['produces'] = ['application/json']
        if not hasattr(func, '__apispec__'):
            func.__apispec__ = {'parameters': [], 'responses': {}}
        extra_parameters = kwargs.pop('parameters', [])
        extra_responses = kwargs.pop('responses', {})
        func.__apispec__['parameters'].extend(extra_parameters)
        func.__apispec__['responses'].update(extra_responses)
        func.__apispec__.update(kwargs)
        return func
    return wrapper

def response_schema(schema, code=200, required=False, description=None):
    """Add response info into the swagger spec

    Usage:

    .. code-block:: python

        from aiohttp import web
        from marshmallow import Schema, fields


        class ResponseSchema(Schema):
            msg = fields.Str()
            data = fields.Dict()

        @response_schema(ResponseSchema(), 200)
        async def index(request):
            return web.json_response({'msg': 'done', 'data': {}})

    :param str description: response description
    :param bool required:
    :param schema: :class:`Schema <marshmallow.Schema>` class or instance
    :param int code: HTTP response code"""
    if callable(schema):
        schema = schema()
    def wrapper(func):
        if not hasattr(func, '__apispec__'):
            func.__apispec__ = {'parameters': [], 'responses': {}}
        func.__apispec__['responses']['%s' % code] = {'schema': schema, 'required': required, 'description': description}
        return func
    return wrapper

def new_job_file(frontier, job_conf_file):
    """Returns new Job."""
    logging.info('loading %s', job_conf_file)
    with open(job_conf_file) as f:
        job_conf = yaml.safe_load(f)
