def read_config():
    """Attempts to read the application configuration file and will raise a `FileNotFoundError` if the
    configuration file is not found. Returns the folder where the configuration file was loaded from, and
    a `Munch` (dict-like object) containing the configuration

    Configuration file paths searched, in order:
        * ~/.cinq/config.json'
        * ./config.json
        * /usr/local/etc/cloud-inquisitor/config.json

    Returns:
        `str`, `dict`"""
    def __recursive_update(old, new):
        out = deepcopy(old)
        for k, v in new.items():
            if issubclass(type(v), dict):
                if k in old:
                    out[k] = __recursive_update(old[k], v)
                else:
                    out[k] = v
            else:
                out[k] = v
        return out
    for fpath in CONFIG_FILE_PATHS:
        if os.path.exists(fpath):
            data = munch.munchify(json.load(open(fpath, 'r')))
            return (os.path.dirname(fpath), munch.munchify(__recursive_update(DEFAULT_CONFIG, data)))
    raise FileNotFoundError('Configuration file not found')

def flatten(data):
    """Returns a flattened version of a list.

    Courtesy of https://stackoverflow.com/a/12472564

    Args:
        data (`tuple` or `list`): Input data

    Returns:
        `list`"""
    if not data:
        return data
    if type(data[0]) in (list, tuple):
        return list(flatten(data[0])) + list(flatten(data[1:]))
    return list(data[:1]) + list(flatten(data[1:]))

def parse_geometry(geometry, ratio=None):
    """Parses a geometry string syntax and returns a (width, height) tuple"""
    m = geometry_pat.match(geometry)
    def syntax_error():
        return ThumbnailParseError('Geometry does not have the correct syntax: %s' % geometry)
    if not m:
        raise syntax_error()
    x = m.group('x')
    y = m.group('y')
    if x is None and y is None:
        raise syntax_error()
    if x is not None:
        x = int(x)
    if y is not None:
        y = int(y)
    if ratio is not None:
        ratio = float(ratio)
        if x is None:
            x = toint(y * ratio)
        elif y is None:
            y = toint(x / ratio)
    return (x, y)

def parse_crop(crop, xy_image, xy_window):
    """Returns x, y offsets for cropping. The window area should fit inside
    image but it works out anyway"""
    x_alias_percent = {'left': '0%', 'center': '50%', 'right': '100%'}
    y_alias_percent = {'top': '0%', 'center': '50%', 'bottom': '100%'}
    xy_crop = crop.split(' ')
    if len(xy_crop) == 1:
        if crop in x_alias_percent:
            x_crop = x_alias_percent[crop]
            y_crop = '50%'
        elif crop in y_alias_percent:
            y_crop = y_alias_percent[crop]
            x_crop = '50%'
        else:
            x_crop, y_crop = (crop, crop)
    elif len(xy_crop) == 2:
        x_crop, y_crop = xy_crop
        x_crop = x_alias_percent.get(x_crop, x_crop)
        y_crop = y_alias_percent.get(y_crop, y_crop)
    else:
        raise ThumbnailParseError('Unrecognized crop option: %s' % crop)
    def get_offset(crop, epsilon):
        m = bgpos_pat.match(crop)
        if not m:
            raise ThumbnailParseError('Unrecognized crop option: %s' % crop)
        value = int(m.group('value'))
        unit = m.group('unit')
        if unit == '%':
            value = epsilon * value / 100.0
        return int(max(0, min(value, epsilon)))
    offset_x = get_offset(x_crop, xy_image[0] - xy_window[0])
    offset_y = get_offset(y_crop, xy_image[1] - xy_window[1])
    return (offset_x, offset_y)

def parse_cropbox(cropbox):
    """Returns x, y, x2, y2 tuple for cropping."""
    if isinstance(cropbox, six.text_type):
        return tuple([int(x.strip()) for x in cropbox.split(',')])
    else:
        return tuple(cropbox)

def toint(number):
    """Helper to return rounded int for a float or just the int it self."""
    if isinstance(number, float):
        if number > 1:
            number = round(number, 0)
        else:
            number = round(math.ceil(number), 0)
    return int(number)

def tokey(*args):
    """Computes a unique key from arguments given."""
    salt = '||'.join([force_text(arg) for arg in args])
    hash_ = hashlib.md5(encode(salt))
    return hash_.hexdigest()

def get_module_class(class_path):
    """imports and returns module class from ``path.to.module.Class``
    argument"""
    mod_name, cls_name = class_path.rsplit('.', 1)
    try:
        mod = import_module(mod_name)
    except ImportError as e:
        raise ImproperlyConfigured('Error importing module %s: "%s"' % (mod_name, e))
    return getattr(mod, cls_name)

