def safe_filter(error_output=''):
    """A safe filter decorator only raising errors when ``THUMBNAIL_DEBUG`` is
    ``True`` otherwise returning ``error_output``."""
    def inner(f):
        @wraps(f)
        def wrapper(*args, **kwargs):
            try:
                return f(*args, **kwargs)
            except Exception as err:
                if sorl_settings.THUMBNAIL_DEBUG:
                    raise
                logger.error('Thumbnail filter failed: %s' % str(err), exc_info=sys.exc_info())
                return error_output
        return wrapper
    return inner

def resolution(file_, resolution_string):
    """A filter to return the URL for the provided resolution of the thumbnail."""
    if sorl_settings.THUMBNAIL_DUMMY:
        dummy_source = sorl_settings.THUMBNAIL_DUMMY_SOURCE
        source = dummy_source.replace('%(width)s', '(?P<width>[0-9]+)')
        source = source.replace('%(height)s', '(?P<height>[0-9]+)')
        source = re.compile(source)
        try:
            resolution = decimal.Decimal(resolution_string.strip('x'))
            info = source.match(file_).groupdict()
            info = {dimension: int(int(size) * resolution) for dimension, size in info.items()}
            return dummy_source % info
        except (AttributeError, TypeError, KeyError):
            return file_
    filename, extension = os.path.splitext(file_)
    return '%s@%s%s' % (filename, resolution_string, extension)

def is_portrait(file_):
    """A very handy filter to determine if an image is portrait or landscape."""
    if sorl_settings.THUMBNAIL_DUMMY:
        return sorl_settings.THUMBNAIL_DUMMY_RATIO < 1
    if not file_:
        return False
    image_file = default.kvstore.get_or_set(ImageFile(file_))
    return image_file.is_portrait()

def text_filter(regex_base, value):
    """Helper method to regex replace images with captions in different markups"""
    regex = regex_base % {'re_cap': '[a-zA-Z0-9\\.\\,:;/_ \\(\\)\\-\\!\\?"]+', 're_img': '[a-zA-Z0-9\\.:/_\\-\\% ]+'}
    images = re.findall(regex, value)
    for i in images:
        image = i[1]
        if image.startswith(settings.MEDIA_URL):
            image = image[len(settings.MEDIA_URL):]
        im = get_thumbnail(image, str(sorl_settings.THUMBNAIL_FILTER_WIDTH))
        value = value.replace(i[1], im.url)
    return value

def value_str(sc):
    """Returns the value part ("[*]", "<M>", "(foo)" etc.) of a menu entry.

    sc: Symbol or Choice."""
    if sc.type in (STRING, INT, HEX):
        return '({})'.format(sc.str_value)
    if isinstance(sc, Symbol) and sc.choice and (sc.visibility == 2):
        return '-->' if sc.choice.selection is sc else '   '
    tri_val_str = (' ', 'M', '*')[sc.tri_value]
    if len(sc.assignable) == 1:
        return '-{}-'.format(tri_val_str)
    if sc.type == BOOL:
        return '[{}]'.format(tri_val_str)
    if sc.type == TRISTATE:
        if sc.assignable == (1, 2):
            return '{' + tri_val_str + '}'
        return '<{}>'.format(tri_val_str)

def node_str(node):
    """Returns the complete menu entry text for a menu node, or "" for invisible
    menu nodes. Invisible menu nodes are those that lack a prompt or that do
    not have a satisfied prompt condition.

    Example return value: "[*] Bool symbol (BOOL)"

    The symbol name is printed in parentheses to the right of the prompt."""
    if not node.prompt:
        return ''
    prompt, prompt_cond = node.prompt
    if not expr_value(prompt_cond):
        return ''
    if node.item == MENU:
        return '    ' + prompt
    if node.item == COMMENT:
        return '    *** {} ***'.format(prompt)
    sc = node.item
    if sc.type == UNKNOWN:
        return ''
    if WITH_HELP_DESC:
        prompt += ' - ' + str(node.help).replace('\n', ' ').replace('\r', '')
    res = '{:3} {}'.format(value_str(sc), prompt)
    if sc.name is not None:
        res += ' ({})'.format(sc.name)
    return res

def print_menuconfig_nodes(node, indent):
    """Prints a tree with all the menu entries rooted at 'node'. Child menu
    entries are indented."""
    while node:
        string = node_str(node)
        if string:
            indent_print(string, indent)
        if node.list:
            print_menuconfig_nodes(node.list, indent + 8)
        node = node.next

def expr_value(expr):
    """Evaluates the expression 'expr' to a tristate value. Returns 0 (n), 1 (m),
    or 2 (y).

    'expr' must be an already-parsed expression from a Symbol, Choice, or
    MenuNode property. To evaluate an expression represented as a string, use
    Kconfig.eval_string().

    Passing subexpressions of expressions to this function works as expected."""
    if expr.__class__ is not tuple:
        return expr.tri_value
    if expr[0] is AND:
        v1 = expr_value(expr[1])
        return 0 if not v1 else min(v1, expr_value(expr[2]))
    if expr[0] is OR:
        v1 = expr_value(expr[1])
        return 2 if v1 == 2 else max(v1, expr_value(expr[2]))
    if expr[0] is NOT:
        return 2 - expr_value(expr[1])
    rel, v1, v2 = expr
    if v1.orig_type is STRING and v2.orig_type is STRING:
        comp = _strcmp(v1.str_value, v2.str_value)
    else:
        try:
            comp = _sym_to_num(v1) - _sym_to_num(v2)
        except ValueError:
            comp = _strcmp(v1.str_value, v2.str_value)
    if rel is EQUAL:
        return 2 * (comp == 0)
    if rel is UNEQUAL:
        return 2 * (comp != 0)
    if rel is LESS:
        return 2 * (comp < 0)
    if rel is LESS_EQUAL:
        return 2 * (comp <= 0)
    if rel is GREATER:
        return 2 * (comp > 0)
    return 2 * (comp >= 0)

def expr_str(expr, sc_expr_str_fn=standard_sc_expr_str):
    """Returns the string representation of the expression 'expr', as in a Kconfig
    file.

    Passing subexpressions of expressions to this function works as expected.

    sc_expr_str_fn (default: standard_sc_expr_str):
      This function is called for every symbol/choice (hence "sc") appearing in
      the expression, with the symbol/choice as the argument. It is expected to
      return a string to be used for the symbol/choice.

      This can be used e.g. to turn symbols/choices into links when generating
      documentation, or for printing the value of each symbol/choice after it.

      Note that quoted values are represented as constants symbols
      (Symbol.is_constant == True)."""
    if expr.__class__ is not tuple:
        return sc_expr_str_fn(expr)
    if expr[0] is AND:
        return '{} && {}'.format(_parenthesize(expr[1], OR, sc_expr_str_fn), _parenthesize(expr[2], OR, sc_expr_str_fn))
    if expr[0] is OR:
        return '{} || {}'.format(_parenthesize(expr[1], AND, sc_expr_str_fn), _parenthesize(expr[2], AND, sc_expr_str_fn))
    if expr[0] is NOT:
        if expr[1].__class__ is tuple:
            return '!({})'.format(expr_str(expr[1], sc_expr_str_fn))
        return '!' + sc_expr_str_fn(expr[1])
    return '{} {} {}'.format(sc_expr_str_fn(expr[1]), _REL_TO_STR[expr[0]], sc_expr_str_fn(expr[2]))

def expr_items(expr):
    """Returns a set() of all items (symbols and choices) that appear in the
    expression 'expr'."""
    res = set()
    def rec(subexpr):
        if subexpr.__class__ is tuple:
            rec(subexpr[1])
            if subexpr[0] is not NOT:
                rec(subexpr[2])
        else:
            res.add(subexpr)
    rec(expr)
    return res

def standard_kconfig():
    """Helper for tools. Loads the top-level Kconfig specified as the first
    command-line argument, or "Kconfig" if there are no command-line arguments.
    Returns the Kconfig instance.

    Exits with sys.exit() (which raises a SystemExit exception) and prints a
    usage note to stderr if more than one command-line argument is passed."""
    if len(sys.argv) > 2:
        sys.exit('usage: {} [Kconfig]'.format(sys.argv[0]))
    try:
        return Kconfig('Kconfig' if len(sys.argv) < 2 else sys.argv[1])
    except (IOError, KconfigError) as e:
        sys.exit(str(e).strip())

def node_str(node):
    """Returns the complete menu entry text for a menu node, or "" for invisible
    menu nodes. Invisible menu nodes are those that lack a prompt or that do
    not have a satisfied prompt condition.

    Example return value: "[*] Bool symbol (BOOL)"

    The symbol name is printed in parentheses to the right of the prompt. This
    is so that symbols can easily be referred to in the configuration
    interface."""
    if not node.prompt:
        return ''
    prompt, prompt_cond = node.prompt
    if not expr_value(prompt_cond):
        return ''
    if node.item == MENU:
        return '    ' + prompt
    if node.item == COMMENT:
        return '    *** {} ***'.format(prompt)
    sc = node.item
    if sc.type == UNKNOWN:
        return ''
    res = '{:3} {}'.format(value_str(sc), prompt)
    if sc.name is not None:
        res += ' ({})'.format(sc.name)
    return res

def get_value_from_user(sc):
    """Prompts the user for a value for the symbol or choice 'sc'. For
    bool/tristate symbols and choices, provides a list of all the assignable
    values."""
    if not sc.visibility:
        print(sc.name + ' is not currently visible')
        return False
    prompt = 'Value for {}'.format(sc.name)
    if sc.type in (BOOL, TRISTATE):
        prompt += ' (available: {})'.format(', '.join((TRI_TO_STR[val] for val in sc.assignable)))
    prompt += ': '
    val = input(prompt)
    if sc.type == HEX and (not val.startswith(('0x', '0X'))):
        val = '0x' + val
    return sc.set_value(val)

def aget(dct, key):
    """Allow to get values deep in a dict with iterable keys

    Accessing leaf values is quite straightforward:

        >>> dct = {'a': {'x': 1, 'b': {'c': 2}}}
        >>> aget(dct, ('a', 'x'))
        1
        >>> aget(dct, ('a', 'b', 'c'))
        2

    If key is empty, it returns unchanged the ``dct`` value.

        >>> aget({'x': 1}, ())
        {'x': 1}"""
    key = iter(key)
    try:
        head = next(key)
    except StopIteration:
        return dct
    if isinstance(dct, list):
        try:
            idx = int(head)
        except ValueError:
            raise IndexNotIntegerError('non-integer index %r provided on a list.' % head)
        try:
            value = dct[idx]
        except IndexError:
            raise IndexOutOfRange('index %d is out of range (%d elements in list).' % (idx, len(dct)))
    else:
        try:
            value = dct[head]
        except KeyError:
            raise MissingKeyError('missing key %r in dict.' % (head,))
        except Exception:
            raise NonDictLikeTypeError("can't query subvalue %r of a leaf%s." % (head, ' (leaf value is %r)' % dct if len(repr(dct)) < 15 else ''))
    return aget(value, key)

def type_name(value):
    """Returns pseudo-YAML type name of given value."""
    return type(value).__name__ if isinstance(value, EncapsulatedNode) else 'struct' if isinstance(value, dict) else 'sequence' if isinstance(value, (tuple, list)) else type(value).__name__

def decode(s):
    """Decode a folder name from IMAP modified UTF-7 encoding to unicode.

    Despite the function's name, the input may still be a unicode
    string. If the input is bytes, it's first decoded to unicode."""
    if isinstance(s, binary_type):
        s = s.decode('latin-1')
    if not isinstance(s, text_type):
        return s
    r = []
    _in = []
    for c in s:
        if c == '&' and (not _in):
            _in.append('&')
        elif c == '-' and _in:
            if len(_in) == 1:
                r.append('&')
            else:
                r.append(modified_deutf7(''.join(_in[1:])))
            _in = []
        elif _in:
            _in.append(c)
        else:
            r.append(c)
    if _in:
        r.append(modified_deutf7(''.join(_in[1:])))
    return ''.join(r)

def check_empty_dict(GET_dict):
    """Returns True if the GET querstring contains on values, but it can contain
    empty keys.
    This is better than doing not bool(request.GET) as an empty key will return
    True"""
    empty = True
    for k, v in GET_dict.items():
        if v and k != 'p' and (k != 'all'):
            empty = False
    return empty

