    try:
        with open(cmd_file, 'a') as cmd_file:
            cmd_file.write(status_file.read())
    except IOError:
        exit("Fatal error: Unable to write to Nagios external command file '%s'.\nMake sure that the file exists and is writable." % (cmd_file,))

