def autoparams(*selected_args):
    """Return a decorator that will inject args into a function using type annotations, Python >= 3.5 only.

    For example::

        @inject.autoparams()
        def refresh_cache(cache: RedisCache, db: DbInterface):
            pass

    There is an option to specify which arguments we want to inject without attempts of injecting everything:

    For example::

        @inject.autoparams('cache', 'db')
        def sign_up(name, email, cache, db):
            pass"""
    def autoparams_decorator(func):
        if sys.version_info[:2] < (3, 5):
            raise InjectorException('autoparams are supported from Python 3.5 onwards')
        full_args_spec = inspect.getfullargspec(func)
        annotations_items = full_args_spec.annotations.items()
        all_arg_names = frozenset(full_args_spec.args + full_args_spec.kwonlyargs)
        args_to_check = frozenset(selected_args) or all_arg_names
        args_annotated_types = {arg_name: annotated_type for arg_name, annotated_type in annotations_items if arg_name in args_to_check}
        return _ParametersInjection(**args_annotated_types)(func)
    return autoparams_decorator

def read_umi_tools(filename: PathLike, dtype: str='float32') -> AnnData:
    """Read a gzipped condensed count matrix from umi_tools.

    Parameters
    ----------
    filename
        File name to read from."""
    import gzip
    from pandas import DataFrame
    dod = {}
    fh = gzip.open(fspath(filename))
    header = fh.readline()
    for line in fh:
        t = line.decode('ascii').split('\t')
        try:
            dod[t[1]].update({t[0]: int(t[2])})
        except KeyError:
            dod[t[1]] = {t[0]: int(t[2])}
    df = DataFrame.from_dict(dod, orient='index')
    df.fillna(value=0.0, inplace=True)
    return AnnData(np.array(df), {'obs_names': df.index}, {'var_names': df.columns}, dtype=dtype)

def read_text(filename: Union[PathLike, Iterator[str]], delimiter: Optional[str]=None, first_column_names: Optional[bool]=None, dtype: str='float32') -> AnnData:
    """Read ``.txt``, ``.tab``, ``.data`` (text) file.

    Same as :func:`~anndata.read_csv` but with default delimiter ``None``.

    Parameters
    ----------
    filename
        Data file, filename or stream.
    delimiter
        Delimiter that separates data within text file. If ``None``, will split at
        arbitrary number of white spaces, which is different from enforcing
        splitting at single white space ``' '``.
    first_column_names
        Assume the first column stores row names.
    dtype
        Numpy data type."""
    if not isinstance(filename, (PathLike, str, bytes)):
        return _read_text(filename, delimiter, first_column_names, dtype)
    filename = Path(filename)
    if filename.suffix == '.gz':
        with gzip.open(str(filename), mode='rt') as f:
            return _read_text(f, delimiter, first_column_names, dtype)
    elif filename.suffix == '.bz2':
        with bz2.open(str(filename), mode='rt') as f:
            return _read_text(f, delimiter, first_column_names, dtype)
    else:
        with filename.open() as f:
            return _read_text(f, delimiter, first_column_names, dtype)

