    Parameters
    ----------
    store
        The filename, a :class:`~typing.MutableMapping`, or a Zarr storage class."""
    if isinstance(store, Path):
        store = str(store)
    import zarr
    f = zarr.open(store, mode='r')
    d = {}
    for key in f.keys():
        _read_key_value_from_zarr(f, d, key)
    return AnnData(*AnnData._args_from_dict(d))

def _read_args_from_h5ad(adata: AnnData=None, filename: Optional[PathLike]=None, mode: Optional[str]=None, chunk_size: int=6000):
    """Return a tuple with the parameters for initializing AnnData.

    Parameters
    ----------
    filename
        Defaults to the objects filename if ``None``."""
    if filename is None and (adata is None or adata.filename is None):
        raise ValueError('Need either a filename or an AnnData object with file backing')
    backed = mode is not None
    if filename is None and (not backed):
        filename = adata.filename
    d = {}
    if backed:
        f = adata.file._file
    else:
        f = h5py.File(filename, 'r')
    for key in f.keys():
        if backed and key in AnnData._BACKED_ATTRS:
            d[key] = None
        else:
            _read_key_value_from_h5(f, d, key, chunk_size=chunk_size)
    if 'X' not in d:
        if backed == 'r+':
            for key in AnnData._H5_ALIASES['X']:
                if key in d:
                    del f[key]
                    f.create_dataset('X', data=d[key])
                    break
    csr_keys = [key.replace('_csr_data', '') for key in d if '_csr_data' in key]
    for key in csr_keys:
        d = load_sparse_csr(d, key=key)
    if not backed:
        f.close()
    return AnnData._args_from_dict(d)

def _get_chunk_indices(za):
    """Return all the indices (coordinates) for the chunks in a zarr array, even empty ones."""
    return [(i, j) for i in range(int(math.ceil(float(za.shape[0]) / za.chunks[0]))) for j in range(int(math.ceil(float(za.shape[1]) / za.chunks[1])))]

def deprecated(new_name: str):
    """This is a decorator which can be used to mark functions
    as deprecated. It will result in a warning being emitted
    when the function is used."""
    def decorator(func):
        @wraps(func)
        def new_func(*args, **kwargs):
            warnings.simplefilter('always', DeprecationWarning)
            warnings.warn('Use {0} instead of {1}, {1} will be removed in the future.'.format(new_name, func.__name__), category=DeprecationWarning, stacklevel=2)
            warnings.simplefilter('default', DeprecationWarning)
            return func(*args, **kwargs)
        setattr(new_func, '__deprecated', True)
        return new_func
    return decorator

