def _stage_from_version(version):
    """return "prd", "stg", or "dev" for the given version string.  A value is always returned"""
    if version:
        m = re.match('^(?P<xyz>\\d+\\.\\d+\\.\\d+)(?P<extra>.*)', version)
        if m:
            return 'stg' if m.group('extra') else 'prd'
    return 'dev'

def build_tx_cigar(exons, strand):
    """builds a single CIGAR string representing an alignment of the
    transcript sequence to a reference sequence, including introns.
    The input exons are expected to be in transcript order, and the
    resulting CIGAR is also in transcript order.

    >>> build_tx_cigar([], 1) is None
    True"""
    cigarelem_re = re.compile('\\d+[=DIMNX]')
    def _reverse_cigar(c):
        return ''.join(reversed(cigarelem_re.findall(c)))
    if len(exons) == 0:
        return None
    if strand == -1:
        cigars = [_reverse_cigar(e['cigar']) for e in exons]
    else:
        cigars = [e['cigar'] for e in exons]
    tx_cigar = [cigars[0]]
    for i in range(1, len(cigars)):
        intron = str(exons[i]['alt_start_i'] - exons[i - 1]['alt_end_i']) + 'N'
        tx_cigar += [intron, cigars[i]]
    tx_cigar_str = ''.join(tx_cigar)
    return tx_cigar_str

def _ci_to_hgvs_coord(s, e):
    """Convert continuous interbase (right-open) coordinates (..,-2,-1,0,1,..) to
    discontinuous HGVS coordinates (..,-2,-1,1,2,..)"""
    def _ci_to_hgvs(c):
        return c + 1 if c >= 0 else c
    return (None if s is None else _ci_to_hgvs(s), None if e is None else _ci_to_hgvs(e) - 1)

def _hgvs_coord_to_ci(s, e):
    """convert start,end interval in inclusive, discontinuous HGVS coordinates
    (..,-2,-1,1,2,..) to continuous interbase (right-open) coordinates
    (..,-2,-1,0,1,..)"""
    def _hgvs_to_ci(c):
        assert c != 0, 'received CDS coordinate 0; expected ..,-2,-1,1,1,...'
        return c - 1 if c > 0 else c
    return (None if s is None else _hgvs_to_ci(s), None if e is None else _hgvs_to_ci(e) + 1)

def _make_key(func, args, kwds, typed, kwd_mark=(object(),), fasttypes={int, str, frozenset, type(None)}, sorted=sorted, tuple=tuple, type=type, len=len):
    """Make a cache key from optionally typed positional and keyword arguments"""
    key = args
    key += kwd_mark
    key += ('__func__', func)
    if kwds:
        sorted_items = sorted(kwds.items())
        for item in sorted_items:
            key += item
    if typed:
        key += tuple((type(v) for v in args))
        if kwds:
            key += tuple((type(v) for k, v in sorted_items))
    elif len(key) == 1 and type(key[0]) in fasttypes:
        return key[0]
    return _HashedSeq(key)

def trim_common_suffixes(strs, min_len=0):
    """trim common suffixes

    >>> trim_common_suffixes('A', 1)
    (0, 'A')"""
    if len(strs) < 2:
        return (0, strs)
    rev_strs = [s[::-1] for s in strs]
    trimmed, rev_strs = trim_common_prefixes(rev_strs, min_len)
    if trimmed:
        strs = [s[::-1] for s in rev_strs]
    return (trimmed, strs)

def trim_common_prefixes(strs, min_len=0):
    """trim common prefixes"""
    trimmed = 0
    if len(strs) > 1:
        s1 = min(strs)
        s2 = max(strs)
        for i in range(len(s1) - min_len):
            if s1[i] != s2[i]:
                break
            trimmed = i + 1
    if trimmed > 0:
        strs = [s[trimmed:] for s in strs]
    return (trimmed, strs)

def validate_type_ac_pair(type, ac):
    """validate that accession is correct for variant type AND that
    accession is fully specified."""
    assert type in valid_pairs, 'Unknown variant type ' + type
    if valid_pairs[type].match(ac):
        return (ValidationLevel.VALID, 'Accession ({ac}) is compatible with variant type {type}'.format(ac=ac, type=type))
    elif invalid_pairs[type].match(ac):
        return (ValidationLevel.ERROR, 'Accession ({ac}) is not compatible with variant type {type}'.format(ac=ac, type=type))
    else:
        return (ValidationLevel.WARNING, 'Accession ({ac}) is not known to be compatible with variant type {type}'.format(ac=ac, type=type))

def unique_slug(manager, slug_field, slug):
    """Ensure slug is unique for the given manager, appending a digit
    if it isn't."""
    max_length = manager.model._meta.get_field(slug_field).max_length
    slug = slug[:max_length]
    i = 0
    while True:
        if i > 0:
            if i > 1:
                slug = slug.rsplit('-', 1)[0]
            slug = '%s-%s' % (slug[:max_length - len(str(i)) - 1], i)
        if not manager.filter(**{slug_field: slug}):
            break
        i += 1
    return slug

