def render_built_form(parser, token):
    """render_build_form takes one argument in one of the following formats:

    {% render_build_form form_instance %}
    {% render_build_form form=form_instance %}
    {% render_build_form id=form_instance.id %}
    {% render_build_form slug=form_instance.slug %}"""
    try:
        _, arg = token.split_contents()
        if '=' not in arg:
            arg = 'form=' + arg
        name, value = arg.split('=', 1)
        if name not in ('form', 'id', 'slug'):
            raise ValueError
    except ValueError:
        e = ()
        raise template.TemplateSyntaxError(render_built_form.__doc__)
    return BuiltFormNode(name, value)

def get_input_key():
    """Input API key and validate"""
    click.secho('No API key found!', fg='yellow', bold=True)
    click.secho('Please visit {} and get an API token.'.format(RequestHandler.BASE_URL), fg='yellow', bold=True)
    while True:
        confkey = click.prompt(click.style('Enter API key', fg='yellow', bold=True))
        if len(confkey) == 32:
            try:
                int(confkey, 16)
            except ValueError:
                click.secho('Invalid API key', fg='red', bold=True)
            else:
                break
        else:
            click.secho('Invalid API key', fg='red', bold=True)
    return confkey

def load_config_key():
    """Load API key from config file, write if needed"""
    global api_token
    try:
        api_token = os.environ['SOCCER_CLI_API_TOKEN']
    except KeyError:
        home = os.path.expanduser('~')
        config = os.path.join(home, '.soccer-cli.ini')
        if not os.path.exists(config):
            with open(config, 'w') as cfile:
                key = get_input_key()
                cfile.write(key)
        else:
            with open(config, 'r') as cfile:
                key = cfile.read()
        if key:
            api_token = key
        else:
            os.remove(config)
            click.secho('No API Token detected. Please visit {0} and get an API Token, which will be used by Soccer CLI to get access to the data.'.format(RequestHandler.BASE_URL), fg='red', bold=True)
            sys.exit(1)
    return api_token

