def get_dependencies(primary_type, types):
    """Perform DFS to get all the dependencies of the primary_type"""
    deps = set()
    struct_names_yet_to_be_expanded = [primary_type]
    while len(struct_names_yet_to_be_expanded) > 0:
        struct_name = struct_names_yet_to_be_expanded.pop()
        deps.add(struct_name)
        fields = types[struct_name]
        for field in fields:
            if field['type'] not in types:
                continue
            elif field['type'] in deps:
                continue
            else:
                struct_names_yet_to_be_expanded.append(field['type'])
    deps.remove(primary_type)
    return tuple(deps)

def is_valid_abi_type(type_name):
    """This function is used to make sure that the ``type_name`` is a valid ABI Type.

    Please note that this is a temporary function and should be replaced by the corresponding
    ABI function, once the following issue has been resolved.
    https://github.com/ethereum/eth-abi/issues/125"""
    valid_abi_types = {'address', 'bool', 'bytes', 'int', 'string', 'uint'}
    is_bytesN = type_name.startswith('bytes') and 1 <= int(type_name[5:]) <= 32
    is_intN = type_name.startswith('int') and 8 <= int(type_name[3:]) <= 256 and (int(type_name[3:]) % 8 == 0)
    is_uintN = type_name.startswith('uint') and 8 <= int(type_name[4:]) <= 256 and (int(type_name[4:]) % 8 == 0)
    if type_name in valid_abi_types:
        return True
    elif is_bytesN:
        return True
    elif is_intN:
        return True
    elif is_uintN:
        return True
    return False

def get_depths_and_dimensions(data, depth):
    """Yields 2-length tuples of depth and dimension of each element at that depth"""
    if not isinstance(data, (list, tuple)):
        return ()
    yield (depth, len(data))
    for item in data:
        yield from get_depths_and_dimensions(item, depth + 1)

def extract_chain_id(raw_v):
    """Extracts chain ID, according to EIP-155
    @return (chain_id, v)"""
    above_id_offset = raw_v - CHAIN_ID_OFFSET
    if above_id_offset < 0:
        if raw_v in {0, 1}:
            return (None, raw_v + V_OFFSET)
        elif raw_v in {27, 28}:
            return (None, raw_v)
        else:
            raise ValueError('v %r is invalid, must be one of: 0, 1, 27, 28, 35+')
    else:
        chain_id, v_bit = divmod(above_id_offset, 2)
        return (chain_id, v_bit + V_OFFSET)

def get_occurrence(event_id, occurrence_id=None, year=None, month=None, day=None, hour=None, minute=None, second=None, tzinfo=None):
    """Because occurrences don't have to be persisted, there must be two ways to
    retrieve them. both need an event, but if its persisted the occurrence can
    be retrieved with an id. If it is not persisted it takes a date to
    retrieve it.  This function returns an event and occurrence regardless of
    which method is used."""
    if occurrence_id:
        occurrence = get_object_or_404(Occurrence, id=occurrence_id)
        event = occurrence.event
    elif None not in (year, month, day, hour, minute, second):
        event = get_object_or_404(Event, id=event_id)
        date = timezone.make_aware(datetime.datetime(int(year), int(month), int(day), int(hour), int(minute), int(second)), tzinfo)
        occurrence = event.get_occurrence(date)
        if occurrence is None:
            raise Http404
    else:
        raise Http404
    return (event, occurrence)

def coerce_date_dict(date_dict):
    """given a dictionary (presumed to be from request.GET) it returns a tuple
    that represents a date. It will return from year down to seconds until one
    is not found.  ie if year, month, and seconds are in the dictionary, only
    year and month will be returned, the rest will be returned as min. If none
    of the parts are found return an empty tuple."""
    keys = ['year', 'month', 'day', 'hour', 'minute', 'second']
    ret_val = {'year': 1, 'month': 1, 'day': 1, 'hour': 0, 'minute': 0, 'second': 0}
    modified = False
    for key in keys:
        try:
            ret_val[key] = int(date_dict[key])
            modified = True
        except KeyError:
            break
    return modified and ret_val or {}

def to_bytes(s):
    """Convert an item into bytes.
    """
    if isinstance(s, bytes):
        return s
    if isinstance(s, str) or is_unicode(s):
        return s.encode('utf-8')
    try:
        return unicode(s).encode('utf-8')
    except NameError:
        return str(s).encode('utf-8')

def cmd2args(cmd):
