def dot(src, **kw):
    """Execute the dot command to create an svg output.
    """
    cmd = 'dot -T%s' % kw.pop('T', 'svg')
    for k, v in list(kw.items()):
        if v is True:
            cmd += ' -%s' % k
        else:
            cmd += ' -%s%s' % (k, v)
    return pipe(cmd, to_bytes(src))

