def single_import(path, imp_as):
    """Generate import statements from a fully qualified import and the name to bind it to."""
    out = []
    parts = path.split('./')
    if len(parts) == 1:
        imp_from, imp = (None, parts[0])
    else:
        imp_from, imp = parts
    if imp == imp_as:
        imp_as = None
    elif imp.endswith('.' + imp_as):
        if imp_from is None:
            imp_from = ''
        imp_from += imp.rsplit('.' + imp_as, 1)[0]
        imp, imp_as = (imp_as, None)
    if imp_from is None and imp == 'sys':
        out.append((imp_as if imp_as is not None else imp) + ' = _coconut_sys')
    elif imp_as is not None and '.' in imp_as:
        fake_mods = imp_as.split('.')
        out.append(import_stmt(imp_from, imp, import_as_var))
        for i in range(1, len(fake_mods)):
            mod_name = '.'.join(fake_mods[:i])
            out.extend(('try:', openindent + mod_name, closeindent + 'except:', openindent + mod_name + ' = _coconut.types.ModuleType("' + mod_name + '")', closeindent + 'else:', openindent + 'if not _coconut.isinstance(' + mod_name + ', _coconut.types.ModuleType):', openindent + mod_name + ' = _coconut.types.ModuleType("' + mod_name + '")' + closeindent * 2))
        out.append('.'.join(fake_mods) + ' = ' + import_as_var)
    else:
        out.append(import_stmt(imp_from, imp, imp_as))
    return out

def match_case_tokens(loc, tokens, check_var, top):
    """Build code for matching the given case."""
    if len(tokens) == 2:
        matches, stmts = tokens
        cond = None
    elif len(tokens) == 3:
        matches, cond, stmts = tokens
    else:
        raise CoconutInternalException('invalid case match tokens', tokens)
    matching = Matcher(loc, check_var)
    matching.match(matches, match_to_var)
    if cond:
        matching.add_guard(cond)
    return matching.build(stmts, set_check_var=top)

def get_match_names(match):
    """Gets keyword names for the given match."""
    names = []
    if 'paren' in match:
        match, = match
        names += get_match_names(match)
    elif 'var' in match:
        setvar, = match
        if setvar != wildcard:
            names.append(setvar)
    elif 'trailer' in match:
        match, trailers = (match[0], match[1:])
        for i in range(0, len(trailers), 2):
            op, arg = (trailers[i], trailers[i + 1])
            if op == 'as':
                names.append(arg)
        names += get_match_names(match)
    return names

def _indent(code, by=1):
    """Indents every nonempty line of the given code."""
    return ''.join((('    ' * by if line else '') + line for line in code.splitlines(True)))

def clean(inputline, strip=True, rem_indents=True, encoding_errors='replace'):
    """Clean and strip a line."""
    stdout_encoding = get_encoding(sys.stdout)
    inputline = str(inputline)
    if rem_indents:
        inputline = inputline.replace(openindent, '').replace(closeindent, '')
    if strip:
        inputline = inputline.strip()
    return inputline.encode(stdout_encoding, encoding_errors).decode(stdout_encoding)

def displayable(inputstr, strip=True):
    """Make a string displayable with minimal loss of information."""
    return clean(str(inputstr), strip, rem_indents=False, encoding_errors='backslashreplace')

def internal_assert(condition, message=None, item=None, extra=None):
    """Raise InternalException if condition is False.
    If condition is a function, execute it on DEVELOP only."""
    if DEVELOP and callable(condition):
        condition = condition()
    if not condition:
        if message is None:
            message = 'assertion failed'
            if item is None:
                item = condition
        raise CoconutInternalException(message, item, extra)

def memoized_parse_block(code):
    """Memoized version of parse_block."""
    success, result = parse_block_memo.get(code, (None, None))
    if success is None:
        try:
            parsed = COMPILER.parse_block(code)
        except Exception as err:
            success, result = (False, err)
        else:
            success, result = (True, parsed)
        parse_block_memo[code] = (success, result)
    if success:
        return result
    else:
        raise result

def load_ipython_extension(ipython):
    """Loads Coconut as an IPython extension."""
    from coconut import __coconut__
    newvars = {}
    for var, val in vars(__coconut__).items():
        if not var.startswith('__'):
            newvars[var] = val
    ipython.push(newvars)
    from coconut.convenience import cmd, parse, CoconutException
    from coconut.terminal import logger
    def magic(line, cell=None):
        """Provides %coconut and %%coconut magics."""
        try:
            if cell is None:
                code = line
            else:
                line = line.strip()
                if line:
                    cmd(line, interact=False)
                code = cell
            compiled = parse(code)
        except CoconutException:
            logger.display_exc()
        else:
            ipython.run_cell(compiled, shell_futures=False)
    ipython.register_magic_function(magic, 'line_cell', 'coconut')

def attach(item, action, greedy=False, ignore_no_tokens=None, ignore_one_token=None):
    """Set the parse action for the given item to create a node in the computation graph."""
    if use_computation_graph:
        if ignore_no_tokens is None:
            ignore_no_tokens = getattr(action, 'ignore_no_tokens', False)
        if ignore_one_token is None:
            ignore_one_token = getattr(action, 'ignore_one_token', False)
        kwargs = {}
        if greedy:
            kwargs['greedy'] = greedy
        if ignore_no_tokens:
            kwargs['ignore_no_tokens'] = ignore_no_tokens
        if ignore_one_token:
            kwargs['ignore_one_token'] = ignore_one_token
        action = partial(ComputationNode, action, **kwargs)
    return add_action(item, action)

def unpack(tokens):
    """Evaluate and unpack the given computation graph."""
    logger.log_tag('unpack', tokens)
    if use_computation_graph:
        tokens = evaluate_tokens(tokens)
    if isinstance(tokens, ParseResults) and len(tokens) == 1:
        tokens = tokens[0]
    return tokens

def all_matches(grammar, text):
    """Find all matches for grammar in text."""
    for tokens, start, stop in grammar.parseWithTabs().scanString(text):
        yield (unpack(tokens), start, stop)

def match_in(grammar, text):
    """Determine if there is a match for grammar in text."""
    for result in grammar.parseWithTabs().scanString(text):
        return True
    return False

def get_vers_for_target(target):
    """Gets a list of the versions supported by the given target."""
    target_info = get_target_info(target)
    if not target_info:
        return py2_vers + py3_vers
    elif len(target_info) == 1:
        if target_info == (2,):
            return py2_vers
        elif target_info == (3,):
            return py3_vers
        else:
            raise CoconutInternalException('invalid target info', target_info)
    elif target_info == (3, 3):
        return [(3, 3), (3, 4)]
    else:
        return [target_info[:2]]

def get_target_info_len2(target, mode='lowest'):
    """Converts target into a length 2 Python version tuple.

    Modes:
    - "lowest" (default): Gets the lowest version supported by the target.
    - "highest": Gets the highest version supported by the target.
    - "nearest": If the current version is supported, returns that, otherwise gets the highest."""
    supported_vers = get_vers_for_target(target)
    if mode == 'lowest':
        return supported_vers[0]
    elif mode == 'highest':
        return supported_vers[-1]
    elif mode == 'nearest':
        if sys.version_info[:2] in supported_vers:
            return sys.version_info[:2]
        else:
            return supported_vers[-1]
    else:
        raise CoconutInternalException('unknown get_target_info_len2 mode', mode)

def addskip(skips, skip):
    """Add a line skip to the skips."""
    if skip < 1:
        complain(CoconutInternalException('invalid skip of line ' + str(skip)))
    else:
        skips.append(skip)
    return skips

def paren_change(inputstring, opens=opens, closes=closes):
    """Determine the parenthetical change of level (num closes - num opens)."""
    count = 0
    for c in inputstring:
        if c in opens:
            count -= 1
        elif c in closes:
            count += 1
    return count

def maybeparens(lparen, item, rparen):
    """Wrap an item in optional parentheses, only applying them if necessary."""
    return item | lparen.suppress() + item + rparen.suppress()

def tokenlist(item, sep, suppress=True):
    """Create a list of tokens matching the item."""
    if suppress:
        sep = sep.suppress()
    return item + ZeroOrMore(sep + item) + Optional(sep)

def itemlist(item, sep, suppress_trailing=True):
    """Create a list of items seperated by seps."""
    return condense(item + ZeroOrMore(addspace(sep + item)) + Optional(sep.suppress() if suppress_trailing else sep))

def split_leading_comment(inputstring):
    """Split into leading comment and rest."""
    if inputstring.startswith('#'):
        comment, rest = inputstring.split('\n', 1)
        return (comment + '\n', rest)
    else:
        return ('', inputstring)

def split_leading_indent(line, max_indents=None):
    """Split line into leading indent and main."""
    indent = ''
    while (max_indents is None or max_indents > 0) and line.startswith((openindent, closeindent)) or line.lstrip() != line:
        if max_indents is not None and line.startswith((openindent, closeindent)):
            max_indents -= 1
        indent += line[0]
        line = line[1:]
    return (indent, line)

def split_trailing_indent(line, max_indents=None):
    """Split line into leading indent and main."""
    indent = ''
    while (max_indents is None or max_indents > 0) and line.endswith((openindent, closeindent)) or line.rstrip() != line:
        if max_indents is not None and (line.endswith(openindent) or line.endswith(closeindent)):
            max_indents -= 1
        indent = line[-1] + indent
        line = line[:-1]
    return (line, indent)

def split_leading_trailing_indent(line, max_indents=None):
    """Split leading and trailing indent."""
    leading_indent, line = split_leading_indent(line, max_indents)
    line, trailing_indent = split_trailing_indent(line, max_indents)
    return (leading_indent, line, trailing_indent)

def collapse_indents(indentation):
    """Removes all openindent-closeindent pairs."""
    change_in_level = ind_change(indentation)
    if change_in_level == 0:
        indents = ''
    elif change_in_level < 0:
        indents = closeindent * -change_in_level
    else:
        indents = openindent * change_in_level
    return indentation.replace(openindent, '').replace(closeindent, '') + indents

def transform(grammar, text):
    """Transform text by replacing matches to grammar."""
    results = []
    intervals = []
    for result, start, stop in all_matches(grammar, text):
        if result is not ignore_transform:
            internal_assert(isinstance(result, str), 'got non-string transform result', result)
            if start == 0 and stop == len(text):
                return result
            results.append(result)
            intervals.append((start, stop))
    if not results:
        return None
    split_indices = [0]
    split_indices.extend((start for start, _ in intervals))
    split_indices.extend((stop for _, stop in intervals))
    split_indices.sort()
    split_indices.append(None)
    out = []
    for i in range(len(split_indices) - 1):
        if i % 2 == 0:
            start, stop = (split_indices[i], split_indices[i + 1])
            out.append(text[start:stop])
        else:
            out.append(results[i // 2])
    if i // 2 < len(results) - 1:
        raise CoconutInternalException('unused transform results', results[i // 2 + 1:])
    if stop is not None:
        raise CoconutInternalException('failed to properly split text to be transformed')
    return ''.join(out)

def disable_inside(item, *elems, **kwargs):
    """Prevent elems from matching inside of item.

    Returns (item with elem disabled, *new versions of elems)."""
    _invert = kwargs.get('_invert', False)
    internal_assert(set(kwargs.keys()) <= set(('_invert',)), 'excess keyword arguments passed to disable_inside')
    level = [0]
    @contextmanager
    def manage_item(self, instring, loc):
        level[0] += 1
        try:
            yield
        finally:
            level[0] -= 1
    yield Wrap(item, manage_item)
    @contextmanager
    def manage_elem(self, instring, loc):
        if level[0] == 0 if not _invert else level[0] > 0:
            yield
        else:
            raise ParseException(instring, loc, self.errmsg, self)
    for elem in elems:
        yield Wrap(elem, manage_elem)

def gethash(compiled):
    """Retrieve a hash from a header."""
    lines = compiled.splitlines()
    if len(lines) < 3 or not lines[2].startswith(hash_prefix):
        return None
    else:
        return lines[2][len(hash_prefix):]

def get_template(template):
    """Read the given template file."""
    with open(os.path.join(template_dir, template) + template_ext, 'r') as template_file:
        return template_file.read()

def fixpath(path):
    """Uniformly format a path."""
    return os.path.normpath(os.path.realpath(os.path.expanduser(path)))

def ver_str_to_tuple(ver_str):
    """Convert a version string into a version tuple."""
    out = []
    for x in ver_str.split('.'):
        try:
            x = int(x)
        except ValueError:
            pass
        out.append(x)
    return tuple(out)

def mypy_run(args):
    """Runs mypy with given arguments and shows the result."""
    logger.log_cmd(['mypy'] + args)
    try:
        stdout, stderr, exit_code = run(args)
    except BaseException:
        traceback.print_exc()
    else:
        for line in stdout.splitlines():
            yield (line, False)
        for line in stderr.splitlines():
            yield (line, True)

def add_coconut_to_path():
    """Adds coconut to sys.path if it isn't there already."""
    try:
        import coconut
    except ImportError:
        sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

def showpath(path):
    """Format a path for displaying."""
    if logger.verbose:
        return os.path.abspath(path)
    else:
        path = os.path.relpath(path)
        if path.startswith(os.curdir + os.sep):
            path = path[len(os.curdir + os.sep):]
        return path

def rem_encoding(code):
    """Remove encoding declarations from compiled code so it can be passed to exec."""
    old_lines = code.splitlines()
    new_lines = []
    for i in range(min(2, len(old_lines))):
        line = old_lines[i]
        if not (line.lstrip().startswith('#') and 'coding' in line):
            new_lines.append(line)
    new_lines += old_lines[2:]
    return '\n'.join(new_lines)

def exec_func(code, glob_vars, loc_vars=None):
    """Wrapper around exec."""
    if loc_vars is None:
        exec(code, glob_vars)
    else:
        exec(code, glob_vars, loc_vars)

def interpret(code, in_vars):
    """Try to evaluate the given code, otherwise execute it."""
    try:
        result = eval(code, in_vars)
    except SyntaxError:
        pass
    else:
        if result is not None:
            print(ascii(result))
        return
    exec_func(code, in_vars)

def kill_children():
    """Terminate all child processes."""
    try:
        import psutil
    except ImportError:
        logger.warn('missing psutil; --jobs may not properly terminate', extra="run 'pip install coconut[jobs]' to fix")
    else:
        master = psutil.Process()
        children = master.children(recursive=True)
        while children:
            for child in children:
                try:
                    child.terminate()
                except psutil.NoSuchProcess:
                    pass
            children = master.children(recursive=True)

def splitname(path):
    """Split a path into a directory, name, and extensions."""
    dirpath, filename = os.path.split(path)
    name, exts = filename.split(os.extsep, 1)
    return (dirpath, name, exts)

def run_file(path):
    """Run a module from a path and return its variables."""
    if PY26:
        dirpath, name, _ = splitname(path)
        found = imp.find_module(name, [dirpath])
        module = imp.load_module('__main__', *found)
        return vars(module)
    else:
        return runpy.run_path(path, run_name='__main__')

def call_output(cmd, stdin=None, encoding_errors='replace', **kwargs):
    """Run command and read output."""
    p = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, **kwargs)
    stdout, stderr, retcode = ([], [], None)
    while retcode is None:
        if stdin is not None:
            logger.log_prefix('<0 ', stdin.rstrip())
        raw_out, raw_err = p.communicate(stdin)
        stdin = None
        out = raw_out.decode(get_encoding(sys.stdout), encoding_errors) if raw_out else ''
        if out:
            logger.log_prefix('1> ', out.rstrip())
        stdout.append(out)
        err = raw_err.decode(get_encoding(sys.stderr), encoding_errors) if raw_err else ''
        if err:
            logger.log_prefix('2> ', err.rstrip())
        stderr.append(err)
        retcode = p.poll()
    return (stdout, stderr, retcode)

def run_cmd(cmd, show_output=True, raise_errs=True, **kwargs):
    """Run a console command.

    When show_output=True, prints output and returns exit code, otherwise returns output.
    When raise_errs=True, raises a subprocess.CalledProcessError if the command fails."""
    internal_assert(cmd and isinstance(cmd, list), 'console commands must be passed as non-empty lists')
    try:
        from shutil import which
    except ImportError:
        pass
    else:
        cmd[0] = which(cmd[0]) or cmd[0]
    logger.log_cmd(cmd)
    try:
        if show_output and raise_errs:
            return subprocess.check_call(cmd, **kwargs)
        elif show_output:
            return subprocess.call(cmd, **kwargs)
        else:
            stdout, stderr, retcode = call_output(cmd, **kwargs)
            output = ''.join(stdout + stderr)
            if retcode and raise_errs:
                raise subprocess.CalledProcessError(retcode, cmd, output=output)
            return output
    except OSError:
        logger.log_exc()
        if raise_errs:
            raise subprocess.CalledProcessError(oserror_retcode, cmd)
        elif show_output:
            return oserror_retcode
        else:
            return ''

def set_mypy_path(mypy_path):
    """Prepend to MYPYPATH."""
    original = os.environ.get(mypy_path_env_var)
    if original is None:
        new_mypy_path = mypy_path
    elif not original.startswith(mypy_path):
        new_mypy_path = mypy_path + os.pathsep + original
    else:
        new_mypy_path = None
    if new_mypy_path is not None:
        logger.log(mypy_path_env_var + ':', new_mypy_path)
        os.environ[mypy_path_env_var] = new_mypy_path

def stdin_readable():
    """Determine whether stdin has any data to read."""
    if not WINDOWS:
        try:
            return bool(select([sys.stdin], [], [], 0)[0])
        except Exception:
            logger.log_exc()
    try:
        return not sys.stdin.isatty()
    except Exception:
        logger.log_exc()
    return False

def set_recursion_limit(limit):
    """Set the Python recursion limit."""
    if limit < minimum_recursion_limit:
        raise CoconutException('--recursion-limit must be at least ' + str(minimum_recursion_limit))
    sys.setrecursionlimit(limit)

def canparse(argparser, args):
    """Determines if argparser can parse args."""
    old_error_method = argparser.error
    argparser.error = _raise_ValueError
    try:
        argparser.parse_args(args)
    except ValueError:
        return False
    else:
        return True
    finally:
        argparser.error = old_error_method

def get_reqs(which='main'):
    """Gets requirements from all_reqs with versions."""
    reqs = []
    for req in all_reqs[which]:
        req_str = req + '>=' + ver_tuple_to_str(min_versions[req])
        if req in version_strictly:
            req_str += ',<' + ver_tuple_to_str(min_versions[req][:-1]) + '.' + str(min_versions[req][-1] + 1)
        reqs.append(req_str)
    return reqs

def uniqueify_all(init_reqs, *other_reqs):
    """Find the union of all the given requirements."""
    union = set(init_reqs)
    for reqs in other_reqs:
        union.update(reqs)
    return list(union)

def all_versions(req):
    """Get all versions of req from PyPI."""
    import requests
    url = 'https://pypi.python.org/pypi/' + req + '/json'
    return tuple(requests.get(url).json()['releases'].keys())

def newer(new_ver, old_ver, strict=False):
    """Determines if the first version tuple is newer than the second.
    True if newer, False if older, None if difference is after specified version parts."""
    if old_ver == new_ver or old_ver + (0,) == new_ver:
        return False
    for n, o in zip(new_ver, old_ver):
        if not isinstance(n, int):
            o = str(o)
        if o < n:
            return True
        elif o > n:
            return False
    return not strict

def print_new_versions(strict=False):
    """Prints new requirement versions."""
    new_updates = []
    same_updates = []
    for req in everything_in(all_reqs):
        new_versions = []
        same_versions = []
        for ver_str in all_versions(req):
            if newer(ver_str_to_tuple(ver_str), min_versions[req], strict=True):
                new_versions.append(ver_str)
            elif not strict and newer(ver_str_to_tuple(ver_str), min_versions[req]):
                same_versions.append(ver_str)
        update_str = req + ': ' + ver_tuple_to_str(min_versions[req]) + ' -> ' + ', '.join(new_versions + ['(' + v + ')' for v in same_versions])
        if new_versions:
            new_updates.append(update_str)
        elif same_versions:
            same_updates.append(update_str)
    print('\n'.join(new_updates + same_updates))

def format_error(err_type, err_value, err_trace=None):
    """Properly formats the specified error."""
    if err_trace is None:
        err_parts = ''.join(traceback.format_exception_only(err_type, err_value)).strip().split(': ', 1)
        if len(err_parts) == 1:
            err_name, err_msg = (err_parts[0], '')
        else:
            err_name, err_msg = err_parts
        err_name = err_name.split('.')[-1]
        return err_name + ': ' + err_msg
    else:
        return ''.join(traceback.format_exception(err_type, err_value, err_trace)).strip()

def complain(error):
    """Raises in develop; warns in release."""
    if callable(error):
        if DEVELOP:
            raise error()
    elif DEVELOP:
        raise error
    else:
        logger.warn_err(error)

def lenient_add_filter(self, *args, **kwargs):
    """Disables the raiseonerror filter."""
    if args and args[0] != 'raiseonerror':
        self.original_add_filter(*args, **kwargs)

def split_function_call(tokens, loc):
    """Split into positional arguments and keyword arguments."""
    pos_args = []
    star_args = []
    kwd_args = []
    dubstar_args = []
    for arg in tokens:
        argstr = ''.join(arg)
        if len(arg) == 1:
            if star_args or kwd_args or dubstar_args:
                raise CoconutDeferredSyntaxError('positional arguments must come first', loc)
            pos_args.append(argstr)
        elif len(arg) == 2:
            if arg[0] == '*':
                if kwd_args or dubstar_args:
                    raise CoconutDeferredSyntaxError('star unpacking must come before keyword arguments', loc)
                star_args.append(argstr)
            elif arg[0] == '**':
                dubstar_args.append(argstr)
            else:
                kwd_args.append(argstr)
        else:
            raise CoconutInternalException('invalid function call argument', arg)
    return (pos_args, star_args, kwd_args, dubstar_args)

def attrgetter_atom_split(tokens):
    """Split attrgetter_atom_tokens into (attr_or_method_name, method_args_or_none_if_attr)."""
    if len(tokens) == 1:
        return (tokens[0], None)
    elif len(tokens) >= 2 and tokens[1] == '(':
        if len(tokens) == 2:
            return (tokens[0], '')
        elif len(tokens) == 3:
            return (tokens[0], tokens[2])
        else:
            raise CoconutInternalException('invalid methodcaller literal tokens', tokens)
    else:
        raise CoconutInternalException('invalid attrgetter literal tokens', tokens)

def pipe_item_split(tokens, loc):
    """Process a pipe item, which could be a partial, an attribute access, a method call, or an expression.
    Return (type, split) where split is
        - (expr,) for expression,
        - (func, pos_args, kwd_args) for partial,
        - (name, args) for attr/method, and
        - (op, args) for itemgetter."""
    if isinstance(tokens, list) or 'expr' in tokens:
        internal_assert(len(tokens) == 1, 'invalid expr pipe item tokens', tokens)
        return ('expr', (tokens[0],))
    elif 'partial' in tokens:
        func, args = tokens
        pos_args, star_args, kwd_args, dubstar_args = split_function_call(args, loc)
        return ('partial', (func, join_args(pos_args, star_args), join_args(kwd_args, dubstar_args)))
    elif 'attrgetter' in tokens:
        name, args = attrgetter_atom_split(tokens)
        return ('attrgetter', (name, args))
    elif 'itemgetter' in tokens:
        op, args = tokens
        return ('itemgetter', (op, args))
    else:
        raise CoconutInternalException('invalid pipe item tokens', tokens)

def comp_pipe_info(op):
    """Returns (direction, star) where direction is 'forwards' or 'backwards'."""
    if op == '..>':
        return ('forwards', False)
    elif op == '<..':
        return ('backwards', False)
    elif op == '..*>':
        return ('forwards', True)
    elif op == '<*..':
        return ('backwards', True)
    else:
        raise CoconutInternalException('invalid function composition pipe operator', op)

def none_coalesce_handle(tokens):
    """Process the None-coalescing operator."""
    if len(tokens) == 1:
        return tokens[0]
    elif tokens[0].isalnum():
        return '({b} if {a} is None else {a})'.format(a=tokens[0], b=none_coalesce_handle(tokens[1:]))
    else:
        return '(lambda {x}: {b} if {x} is None else {x})({a})'.format(x=none_coalesce_var, a=tokens[0], b=none_coalesce_handle(tokens[1:]))

def attrgetter_atom_handle(loc, tokens):
    """Process attrgetter literals."""
    name, args = attrgetter_atom_split(tokens)
    if args is None:
        return '_coconut.operator.attrgetter("' + name + '")'
    elif '.' in name:
        raise CoconutDeferredSyntaxError('cannot have attribute access in implicit methodcaller partial', loc)
    elif args == '':
        return '_coconut.operator.methodcaller("' + tokens[0] + '")'
    else:
        return '_coconut.operator.methodcaller("' + tokens[0] + '", ' + tokens[2] + ')'

def lazy_list_handle(tokens):
    """Process lazy lists."""
    if len(tokens) == 0:
        return '_coconut.iter(())'
    else:
        return '(%s() for %s in (' % (func_var, func_var) + 'lambda: ' + ', lambda: '.join(tokens) + (',' if len(tokens) == 1 else '') + '))'

def infix_handle(tokens):
    """Process infix calls."""
    func, args = get_infix_items(tokens, callback=infix_handle)
    return '(' + func + ')(' + ', '.join(args) + ')'

def op_funcdef_handle(tokens):
    """Process infix defs."""
    func, base_args = get_infix_items(tokens)
    args = []
    for arg in base_args[:-1]:
        rstrip_arg = arg.rstrip()
        if not rstrip_arg.endswith(unwrapper):
            if not rstrip_arg.endswith(','):
                arg += ', '
            elif arg.endswith(','):
                arg += ' '
        args.append(arg)
    last_arg = base_args[-1]
    if last_arg.rstrip().endswith(','):
        last_arg = last_arg.rsplit(',')[0]
    args.append(last_arg)
    return func + '(' + ''.join(args) + ')'

def typedef_callable_handle(tokens):
    """Process -> to Callable inside type annotations."""
    if len(tokens) == 1:
        return '_coconut.typing.Callable[..., ' + tokens[0] + ']'
    elif len(tokens) == 2:
        return '_coconut.typing.Callable[[' + tokens[0] + '], ' + tokens[1] + ']'
    else:
        raise CoconutInternalException('invalid Callable typedef tokens', tokens)

def decorator_handle(tokens):
    """Process decorators."""
    defs = []
    decorates = []
    for i, tok in enumerate(tokens):
        if 'simple' in tok and len(tok) == 1:
            decorates.append('@' + tok[0])
        elif 'test' in tok and len(tok) == 1:
            varname = decorator_var + '_' + str(i)
            defs.append(varname + ' = ' + tok[0])
            decorates.append('@' + varname)
        else:
            raise CoconutInternalException('invalid decorator tokens', tok)
    return '\n'.join(defs + decorates) + '\n'

def match_handle(loc, tokens):
    """Process match blocks."""
    if len(tokens) == 4:
        matches, match_type, item, stmts = tokens
        cond = None
    elif len(tokens) == 5:
        matches, match_type, item, cond, stmts = tokens
    else:
        raise CoconutInternalException('invalid match statement tokens', tokens)
    if match_type == 'in':
        invert = False
    elif match_type == 'not in':
        invert = True
    else:
        raise CoconutInternalException('invalid match type', match_type)
    matching = Matcher(loc, match_check_var)
    matching.match(matches, match_to_var)
    if cond:
        matching.add_guard(cond)
    return match_to_var + ' = ' + item + '\n' + matching.build(stmts, invert=invert)

def except_handle(tokens):
    """Process except statements."""
    if len(tokens) == 1:
        errs, asname = (tokens[0], None)
    elif len(tokens) == 2:
        errs, asname = tokens
    else:
        raise CoconutInternalException('invalid except tokens', tokens)
    out = 'except '
    if 'list' in tokens:
        out += '(' + errs + ')'
    else:
        out += errs
    if asname is not None:
        out += ' as ' + asname
    return out

def subscriptgroup_handle(tokens):
    """Process subscriptgroups."""
    internal_assert(0 < len(tokens) <= 3, 'invalid slice args', tokens)
    args = []
    for arg in tokens:
        if not arg:
            arg = 'None'
        args.append(arg)
    if len(args) == 1:
        return args[0]
    else:
        return '_coconut.slice(' + ', '.join(args) + ')'

def itemgetter_handle(tokens):
    """Process implicit itemgetter partials."""
    internal_assert(len(tokens) == 2, 'invalid implicit itemgetter args', tokens)
    op, args = tokens
    if op == '[':
        return '_coconut.operator.itemgetter(' + args + ')'
    elif op == '$[':
        return '_coconut.functools.partial(_coconut_igetitem, index=' + args + ')'
    else:
        raise CoconutInternalException('invalid implicit itemgetter type', op)

def namelist_handle(tokens):
    """Process inline nonlocal and global statements."""
    if len(tokens) == 1:
        return tokens[0]
    elif len(tokens) == 2:
        return tokens[0] + '\n' + tokens[0] + ' = ' + tokens[1]
    else:
        raise CoconutInternalException('invalid in-line nonlocal / global tokens', tokens)

def compose_item_handle(tokens):
    """Process function composition."""
    if len(tokens) < 1:
        raise CoconutInternalException('invalid function composition tokens', tokens)
    elif len(tokens) == 1:
        return tokens[0]
    else:
        return '_coconut_forward_compose(' + ', '.join(reversed(tokens)) + ')'

def tco_return_handle(tokens):
    """Process tail-call-optimizable return statements."""
    internal_assert(len(tokens) == 2, 'invalid tail-call-optimizable return statement tokens', tokens)
    if tokens[1].startswith('()'):
        return 'return _coconut_tail_call(' + tokens[0] + ')' + tokens[1][2:]
    else:
        return 'return _coconut_tail_call(' + tokens[0] + ', ' + tokens[1][1:]

def split_func_name_args_params_handle(tokens):
    """Process splitting a function into name, params, and args."""
    internal_assert(len(tokens) == 2, 'invalid function definition splitting tokens', tokens)
    func_name = tokens[0]
    func_args = []
    func_params = []
    for arg in tokens[1]:
        if len(arg) > 1 and arg[0] in ('*', '**'):
            func_args.append(arg[1])
        elif arg[0] != '*':
            func_args.append(arg[0])
        func_params.append(''.join(arg))
    return [func_name, ', '.join(func_args), '(' + ', '.join(func_params) + ')']

def join_match_funcdef(tokens):
    """Join the pieces of a pattern-matching function together."""
    if len(tokens) == 2:
        (func, insert_after_docstring), body = tokens
        docstring = None
    elif len(tokens) == 3:
        (func, insert_after_docstring), docstring, body = tokens
    else:
        raise CoconutInternalException('invalid docstring insertion tokens', tokens)
    insert_after_docstring, dedent = split_trailing_indent(insert_after_docstring)
    indent, body = split_leading_indent(body)
    indentation = collapse_indents(dedent + indent)
    return func + (docstring if docstring is not None else '') + insert_after_docstring + indentation + body

def set_grammar_names():
    """Set names of grammar elements to their variable names."""
    for varname, val in vars(Grammar).items():
        if isinstance(val, ParserElement):
            setattr(Grammar, varname, val.setName(varname))

def cmd(args, interact=False):
    """Process command-line arguments."""
    if isinstance(args, (str, bytes)):
        args = args.split()
    return CLI.cmd(args=args, interact=interact)

def version(which='num'):
    """Get the Coconut version."""
    if which in VERSIONS:
        return VERSIONS[which]
    else:
        raise CoconutException('invalid version type ' + ascii(which), extra='valid versions are ' + ', '.join(VERSIONS))

def parse(code='', mode='sys'):
    """Compile Coconut code."""
    if CLI.comp is None:
        setup()
    if mode in PARSERS:
        return PARSERS[mode](CLI.comp)(code)
    else:
        raise CoconutException('invalid parse mode ' + ascii(mode), extra='valid modes are ' + ', '.join(PARSERS))

def auto_compilation(on=True):
    """Turn automatic compilation of Coconut files on or off."""
    if on:
        if coconut_importer not in sys.meta_path:
            sys.meta_path.insert(0, coconut_importer)
    else:
        try:
            sys.meta_path.remove(coconut_importer)
        except ValueError:
            pass

def clean_params(params, drop_nones=True, recursive=True):
    """Clean up a dict of API parameters to be sent to the Coinbase API.

    Some endpoints require boolean options to be represented as integers. By
    default, will remove all keys whose value is None, so that they will not be
    sent to the API endpoint at all."""
    cleaned = {}
    for key, value in six.iteritems(params):
        if drop_nones and value is None:
            continue
        if recursive and isinstance(value, dict):
            value = clean_params(value, drop_nones, recursive)
        cleaned[key] = value
    return cleaned

def encode_params(params, **kwargs):
    """Clean and JSON-encode a dict of parameters."""
    cleaned = clean_params(params, **kwargs)
    return json.dumps(cleaned)

def check_uri_security(uri):
    """Warns if the URL is insecure."""
    if urlparse(uri).scheme != 'https':
        warning_message = 'WARNING: this client is sending a request to an insecure API endpoint. Any API request you make may expose your API key and secret to third parties. Consider using the default endpoint:\n\n  %s\n' % uri
        warnings.warn(warning_message, UserWarning)
    return uri

def build_api_error(response, blob=None):
    """Helper method for creating errors and attaching HTTP response/request
    details to them."""
    try:
        blob = blob or response.json()
    except json.JSONDecodeError:
        blob = {}
    error_list = blob.get('errors', None)
    error = error_list[0] if error_list else {}
    if error:
        error_id = error.get('id', '')
        error_message = error.get('message', '')
    else:
        error_id = blob.get('error')
        error_message = blob.get('error_description')
    error_class = _error_id_to_class.get(error_id, None) or _status_code_to_class.get(response.status_code, APIError)
    return error_class(response, error_id, error_message, error_list)

def _remove_non_methods():
    """Removes any object in dict that is not a registered method."""
    cur_module = sys.modules[__name__]
    my_globals = dict(globals())
    from prettytensor.pretty_tensor_class import PrettyTensor
    for name, _ in six.iteritems(my_globals):
        if not hasattr(PrettyTensor, name):
            delattr(cur_module, name)
    if hasattr(cur_module, 'bookkeeper'):
        delattr(cur_module, 'bookkeeper')

def l2_regularizer(decay, name_filter='weights'):
    """Create an l2 regularizer."""
    return regularizer('l2_regularizer', lambda x: tf.nn.l2_loss(x) * decay, name_filter=name_filter)

def l1_regularizer(decay, name_filter='weights'):
    """Create an l1 regularizer."""
    return regularizer('l1_regularizer', lambda x: tf.reduce_sum(tf.abs(x)) * decay, name_filter=name_filter)

def _last_index(x, default_dim):
    """Returns the last dimension's index or default_dim if x has no shape."""
    if x.get_shape().ndims is not None:
        return len(x.get_shape()) - 1
    else:
        return default_dim

def _all_dims(x, default_dims=None):
    """Returns a list of dims in x or default_dims if the rank is unknown."""
    if x.get_shape().ndims is not None:
        return list(xrange(x.get_shape().ndims))
    else:
        return default_dims

def he_init(n_inputs, n_outputs, activation_fn, uniform=True):
    """Sets the parameter initialization using the method described.

    This method is designed to keep the scale of the gradients roughly the same
    in all layers with ReLU activations.

    He et al. (2015):
             Delving deep into rectifiers: surpassing human-level performance on
             imageNet classification. International Conference on Computer Vision.

    For activations other than ReLU and ReLU6, this method uses Xavier
    initialization as in xavier_init().

    Args:
      n_inputs: The number of input nodes into each output.
      n_outputs: The number of output nodes for each input.
      activation_fn: Activation function used in this layer.
      uniform: If uniform distribution will be used for Xavier initialization.
               Normal distribution will be used if False.
    Returns:
      An initializer."""
    def in_relu_family(activation_fn):
        if isinstance(activation_fn, collections.Sequence):
            activation_fn = activation_fn[0]
        return activation_fn in (tf.nn.relu, tf.nn.relu6)
    if in_relu_family(activation_fn):
        stddev = math.sqrt(2.0 / n_inputs)
        return tf.random_normal_initializer(stddev=stddev)
    else:
        return xavier_init(n_inputs, n_outputs, uniform)

def spatial_slice_zeros(x):
    """Experimental summary that shows how many planes are unused for a batch."""
    return tf.cast(tf.reduce_all(tf.less_equal(x, 0.0), [0, 1, 2]), tf.float32)

def _pool(input_layer, pool_fn, kernel, stride, edges, name):
    """Applies a pooling function."""
    input_layer.get_shape().assert_has_rank(4)
    if input_layer.get_shape().ndims not in (None, 4):
        raise ValueError('Pooling requires a rank 4 tensor: %s' % input_layer.get_shape())
    kernel = _kernel(kernel)
    stride = _stride(stride)
    size = [1, kernel[0], kernel[1], 1]
    new_head = pool_fn(input_layer.tensor, size, stride, edges, name=name)
    return input_layer.with_tensor(new_head)

def _set_shape_on_tensor(tensor, shape):
    """Convenience to set a shape or check it."""
    if shape is not None:
        try:
            tensor.set_shape(shape)
        except ValueError:
            raise ValueError("Requested shape does not match tensor's shape: %s vs %s" % (shape, tensor.get_shape()))
    elif tensor.get_shape().ndims is None:
        raise ValueError('Unknown shape on tensor: %s' % tensor)

def wrap(tensor, books=None, tensor_shape=None):
    """Creates an input layer representing the given tensor.

    Args:
      tensor: The tensor.
      books: The bookkeeper; this is usually not required unless you are building
        multiple `tf.Graphs.`
      tensor_shape: An optional shape that will be set on the Tensor or verified
        to match the tensor.
    Returns:
      A layer."""
    if books is None:
        books = bookkeeper.for_default_graph()
    if isinstance(tensor, PrettyTensor):
        return tensor.as_layer()
    elif isinstance(tensor, UnboundVariable):
        def set_input_from_unbound_var(data):
            """Sets the input from the given unbound_var."""
            if data is not None:
                return wrap(data, books)
            else:
                return None
        return _DeferredLayer(books, set_input_from_unbound_var, [tensor], {})
    else:
        tensor = tf.convert_to_tensor(tensor, name='input')
        if tensor_shape:
            _set_shape_on_tensor(tensor, tensor_shape)
        return Layer(books, tensor=tensor, name=tensor.name)

def join_pretty_tensors(tensors, output, join_function=None, name='join'):
    """Joins the list of pretty_tensors and sets head of output_pretty_tensor.

    Args:
      tensors: A sequence of Layers or SequentialLayerBuilders to join.
      output: A pretty_tensor to set the head with the result.
      join_function: A function to join the tensors, defaults to concat on the
        last dimension.
      name: A name that is used for the name_scope
    Returns:
      The result of calling with_tensor on output
    Raises:
      ValueError: if pretty_tensors is None or empty."""
    if not tensors:
        raise ValueError('pretty_tensors must be a non-empty sequence.')
    with output.g.name_scope(name):
        if join_function is None:
            last_dim = len(tensors[0].shape) - 1
            return output.with_tensor(tf.concat(tensors, last_dim))
        else:
            return output.with_tensor(join_function(tensors))

def _merge_unbound_var_dicts(src, dst):
    """Merges src into dst and throws an exception if a value is incompatible."""
    for k, v in six.iteritems(src):
        if dst.get(k, v) != v:
            trace1 = ''.join(scopes.skip_common_stack_elements(v.stacktrace, dst[k].stacktrace))
            trace2 = ''.join(scopes.skip_common_stack_elements(dst[k].stacktrace, v.stacktrace))
            raise ValueError('Key conflict: %s\nDefined At:\n%s\nand\n%s' % (k, trace1, trace2))
        else:
            dst[k] = v

def _assign_values_to_unbound_vars(unbound_vars, unbound_var_values):
    """Assigns values to the vars and raises ValueError if one is missing."""
    context = {}
    for key, value in six.iteritems(unbound_var_values):
        if key not in unbound_vars:
            raise ValueError('unexpected key: %s. Legal values are: %s' % (key, list(six.iterkeys(unbound_vars))))
        context[unbound_vars[key]] = value
    unspecified = []
    for unbound_var in six.itervalues(unbound_vars):
        if unbound_var not in context:
            if unbound_var.has_default():
                context[unbound_var] = unbound_var.default
            else:
                unspecified.append(unbound_var.key)
    if unspecified:
        raise ValueError('Unspecified keys: %s' % unspecified)
    return context

def construct_all(templates, **unbound_var_values):
    """Constructs all the given templates in a single pass without redundancy.

    This is useful when the templates have a common substructure and you want the
    smallest possible graph.

    Args:
      templates: A sequence of templates.
      **unbound_var_values: The unbound_var values to replace.
    Returns:
      A list of results corresponding to templates.
    Raises:
      TypeError: If any value in templates is unsupported.
      ValueError: If the unbound_var values specified are not complete or contain
        unknown values."""
    def _merge_dicts(src, dst):
        for k, v in six.iteritems(src):
            if dst.get(k, v) != v:
                raise ValueError('Conflicting values bound for %s: %s and %s' % (k, v, dst[k]))
            else:
                dst[k] = v
    all_unbound_vars = {}
    context = {}
    for x in templates:
        if isinstance(x, _DeferredLayer):
            _merge_unbound_var_dicts(x.unbound_vars, all_unbound_vars)
            _merge_dicts(x._partial_context, context)
        else:
            raise TypeError('Unexpected type: %s' % type(x))
    _merge_dicts(_assign_values_to_unbound_vars(all_unbound_vars, unbound_var_values), context)
    result = list(templates)
    for i, x in enumerate(result):
        if isinstance(x, _DeferredLayer):
            result[i] = x._construct(context)
    return result

def _strip_unnecessary_contents_from_stack(result, processed):
    """Remove the distracting lines from the stored tracebacks.

    This also reduces memory overhead by removing the frame contents. This is very
    important when doing long unrolls.

    Args:
      result: The result to process.
      processed: A set of already processed nodes, used to stop early."""
    if isinstance(result, (PrettyTensor, Loss)):
        if result.is_sequence():
            for tensor in result.sequence:
                _strip_unnecessary_contents_from_stack(tensor, processed)
                return
        else:
            result = result.tensor
    if hasattr(result, 'op'):
        result = result.op
    if result in processed:
        return
    else:
        processed.add(result)
    trace = []
    found = False
    for f, line_no, method, _ in result._traceback:
        if method in ('_replace_deferred', '_construct') and f.endswith('pretty_tensor_class.py'):
            found = True
            continue
        trace.append((f, line_no, method, {}))
    result._traceback = trace
    if not found:
        return
    for inp in result.inputs:
        _strip_unnecessary_contents_from_stack(inp, processed)

def _should_defer(input_layer, args, kwargs):
    """Checks to see if any of the args are templates."""
    for arg in itertools.chain([input_layer], args, six.itervalues(kwargs)):
        if isinstance(arg, (_DeferredLayer, UnboundVariable)):
            return True
        elif isinstance(arg, collections.Sequence) and (not isinstance(arg, six.string_types)):
            if _should_defer(None, arg, {}):
                return True
        elif isinstance(arg, collections.Mapping):
            if _should_defer(None, (), arg):
                return True
    return False

def _make_tuple(x):
    """TF has an obnoxious habit of being lenient with single vs tuple."""
    if isinstance(x, prettytensor.PrettyTensor):
        if x.is_sequence():
            return tuple(x.sequence)
        else:
            return (x.tensor,)
    elif isinstance(x, tuple):
        return x
    elif isinstance(x, collections.Sequence) and (not isinstance(x, six.string_types)):
        return tuple(x)
    else:
        return (x,)

def maybe_download(url, filename):
    """Download the data from Yann's website, unless it's already here."""
    if not os.path.exists(WORK_DIRECTORY):
        os.mkdir(WORK_DIRECTORY)
    filepath = os.path.join(WORK_DIRECTORY, filename)
    if not os.path.exists(filepath):
        filepath, _ = request.urlretrieve(url + filename, filepath)
        statinfo = os.stat(filepath)
        print('Successfully downloaded', filename, statinfo.st_size, 'bytes.')
    return filepath

def permute_data(arrays, random_state=None):
    """Permute multiple numpy arrays with the same order."""
    if any((len(a) != len(arrays[0]) for a in arrays)):
        raise ValueError('All arrays must be the same length.')
    if not random_state:
        random_state = np.random
    order = random_state.permutation(len(arrays[0]))
    return [a[order] for a in arrays]

def mnist(training):
    """Downloads MNIST and loads it into numpy arrays."""
    if training:
        data_filename = 'train-images-idx3-ubyte.gz'
        labels_filename = 'train-labels-idx1-ubyte.gz'
        count = 60000
    else:
        data_filename = 't10k-images-idx3-ubyte.gz'
        labels_filename = 't10k-labels-idx1-ubyte.gz'
        count = 10000
    data_filename = maybe_download(MNIST_URL, data_filename)
    labels_filename = maybe_download(MNIST_URL, labels_filename)
    return (mnist_extract_data(data_filename, count), mnist_extract_labels(labels_filename, count))

def get_current_name_scope():
    """Gets the current name scope."""
    g = tf.get_default_graph()
    if isinstance(g._name_stack, tuple):
        return g._name_stack[0] + '/'
    else:
        return g._name_stack + '/'

def make_template(name, func, *args, **kwargs):
    """Given an arbitrary function, wrap it so that it does parameter sharing."""
    if args or kwargs:
        func = functools.partial(func, *args, **kwargs)
    return Template(name, func)

def skip_common_stack_elements(stacktrace, base_case):
    """Skips items that the target stacktrace shares with the base stacktrace."""
    for i, (trace, base) in enumerate(zip(stacktrace, base_case)):
        if trace != base:
            return stacktrace[i:]
    return stacktrace[-1:]

def flatten(input_layer, preserve_batch=True):
    """Flattens this.

    If preserve_batch is True, the result is rank 2 and the first dim (batch) is
    unchanged. Otherwise the result is rank 1.

    Args:
      input_layer: The Pretty Tensor object, supplied.
      preserve_batch: If True (the default), then preserve the first dimension.
    Returns:
      A LayerWrapper with the flattened tensor."""
    if preserve_batch:
        return reshape(input_layer, [DIM_SAME, -1])
    else:
        return reshape(input_layer, [-1])

def stop_gradient(input_layer):
    """Cuts off the gradient at this point.

    This works on both sequence and regular Pretty Tensors.

    Args:
      input_layer: The input.
    Returns:
      A new Pretty Tensor of the same type with stop_gradient applied."""
    if input_layer.is_sequence():
        result = [tf.stop_gradient(t) for t in input_layer.sequence]
        return input_layer.with_sequence(result)
    else:
        return tf.stop_gradient(input_layer)

def dropout(input_layer, keep_prob, phase=Phase.train, name=PROVIDED):
    """Aplies dropout if this is in the train phase."""
    if phase == Phase.train:
        return tf.nn.dropout(input_layer, keep_prob, name=name)
    else:
        return input_layer

def concat(input_layer, concat_dim, other_tensors=None):
    """Concatenates input PrettyTensor with other_tensors along the specified dim.

    This adds the Pretty Tensor passed via input_layer to the front of the list of
    tensors to concat.

    Args:
      input_layer: The input layer.
      concat_dim: The dimension along which to concat.
      other_tensors: The tensors to concatenate with as an iterable or None if
        this is called on a sequence.
    Returns:
      A new PrettyTensor.
    Raises:
      ValueError: If other_tensors is None and this is not a sequence."""
    if input_layer.is_sequence():
        all_tensors = input_layer.sequence
        all_tensors.extend(other_tensors or [])
    else:
        all_tensors = [input_layer]
        if other_tensors is None:
            raise ValueError('Other Tensors must be supplied.')
        all_tensors.extend(other_tensors)
    if not all_tensors:
        return prettytensor.wrap_sequence([])
    else:
        return tf.concat(all_tensors, concat_dim)

def _zip_with_scalars(args):
    """Zips across args in order and replaces non-iterables with repeats."""
    zipped = []
    for arg in args:
        if isinstance(arg, prettytensor.PrettyTensor):
            zipped.append(arg if arg.is_sequence() else itertools.repeat(arg))
        elif isinstance(arg, collections.Sequence) and (not isinstance(arg, tf.compat.bytes_or_text_types)):
            zipped.append(arg)
        else:
            zipped.append(itertools.repeat(arg))
    assert len(args) == len(zipped)
    return zip(*zipped)

def _convert_and_assert_per_example_weights_compatible(input_, per_example_weights, dtype):
    """Converts per_example_weights to a tensor and validates the shape."""
    per_example_weights = tf.convert_to_tensor(per_example_weights, name='per_example_weights', dtype=dtype)
    if input_.get_shape().ndims:
        expected_length = input_.get_shape().dims[0]
        message = 'per_example_weights must have rank 1 and length %s, but was: %s' % (expected_length, per_example_weights.get_shape())
    else:
        expected_length = None
        message = 'per_example_weights must have rank 1 and length equal to the first dimension of inputs (unknown), but was: %s' % per_example_weights.get_shape()
    if per_example_weights.get_shape().ndims not in (1, None):
        raise ValueError(message)
    if not per_example_weights.get_shape().is_compatible_with((expected_length,)):
        raise ValueError(message)
    return per_example_weights

def l2_regression(input_, target, name=PROVIDED, loss_weight=None, per_example_weights=None):
    """Applies an L2 Regression (Sum of Squared Error) to the target."""
    target = _convert_and_assert_tensors_compatible(input_, target)
    return apply_regression(input_, functions.l2_regression_sq_loss, target, [], name='%s_loss' % name, loss_weight=loss_weight, per_example_weights=per_example_weights)

def l1_regression(input_, target, name=PROVIDED, loss_weight=None, per_example_weights=None):
    """Applies an L1 Regression (Sum of Absolute Error) to the target."""
    target = _convert_and_assert_tensors_compatible(input_, target)
    return apply_regression(input_, functions.l1_regression_loss, target, [], name='%s_loss' % name, loss_weight=loss_weight, per_example_weights=per_example_weights)

def _compute_average_correct(input_, labels, per_example_weights, topk=1):
    """Returns the numerator and denominator of classifier accuracy."""
    return _compute_sparse_average_correct(input_, tf.reshape(tf.argmax(labels, 1), [-1, 1]), per_example_weights, topk=topk)

def _compute_sparse_average_correct(input_, labels, per_example_weights, topk=1):
    """Returns the numerator and denominator of classifier accuracy."""
    labels = tf.to_int64(labels)
    labels.get_shape().assert_is_compatible_with([input_.get_shape()[0], None])
    if topk == 1:
        predictions = tf.reshape(tf.argmax(input_, 1), [-1, 1])
        in_topk = tf.reduce_any(tf.equal(labels, predictions), reduction_indices=[1])
    else:
        predictions = tf.reshape(tf.nn.top_k(input_, topk)[1], [-1, 1, topk])
        labels = tf.expand_dims(labels, [-1])
        in_topk = tf.reduce_any(tf.equal(tf.cast(labels, predictions.dtype), predictions), reduction_indices=[1, 2])
    correct_predictions = tf.to_float(in_topk)
    if per_example_weights is not None:
        per_example_weights = _convert_and_assert_per_example_weights_compatible(input_, per_example_weights, dtype=None)
        float_weights = tf.to_float(per_example_weights)
        correct_predictions *= float_weights
        num_examples = tf.reduce_sum(float_weights)
    else:
        num_examples = tf.to_float(tf.gather(tf.shape(input_), 0))
    return (tf.reduce_sum(correct_predictions), num_examples)

def lstm_state_tuples(num_nodes, name):
    """Convenience so that the names of the vars are defined in the same file."""
    if not isinstance(num_nodes, tf.compat.integral_types):
        raise ValueError('num_nodes must be an integer: %s' % num_nodes)
    return [(STATE_NAME % name + '_0', tf.float32, num_nodes), (STATE_NAME % name + '_1', tf.float32, num_nodes)]

def gru_state_tuples(num_nodes, name):
    """Convenience so that the names of the vars are defined in the same file."""
    if not isinstance(num_nodes, tf.compat.integral_types):
        raise ValueError('num_nodes must be an integer: %s' % num_nodes)
    return [(STATE_NAME % name + '_0', tf.float32, num_nodes)]

def adjustFiles(rec, op):
    """Apply a mapping function to each File path in the object `rec`."""
    if isinstance(rec, MutableMapping):
        if rec.get('class') == 'File':
            rec['path'] = op(rec['path'])
        for d in rec:
            adjustFiles(rec[d], op)
    if isinstance(rec, MutableSequence):
        for d in rec:
            adjustFiles(d, op)

def check_types(srctype, sinktype, linkMerge, valueFrom):
    """Check if the source and sink types are "pass", "warning", or "exception".
    """
    if valueFrom is not None:
        return 'pass'
    if linkMerge is None:
        if can_assign_src_to_sink(srctype, sinktype, strict=True):
            return 'pass'
        if can_assign_src_to_sink(srctype, sinktype, strict=False):
            return 'warning'
        return 'exception'
    if linkMerge == 'merge_nested':
        return check_types({'items': _get_type(srctype), 'type': 'array'}, _get_type(sinktype), None, None)
    if linkMerge == 'merge_flattened':
        return check_types(merge_flatten_type(_get_type(srctype)), _get_type(sinktype), None, None)
    raise WorkflowException(u"Unrecognized linkMerge enum '{}'".format(linkMerge))

def merge_flatten_type(src):
    """Return the merge flattened type of the source type
    """
    if isinstance(src, MutableSequence):
        return [merge_flatten_type(t) for t in src]
    if isinstance(src, MutableMapping) and src.get('type') == 'array':
        return src
    return {'items': src, 'type': 'array'}

def _compare_records(src, sink, strict=False):
    """Compare two records, ensuring they have compatible fields.

    This handles normalizing record names, which will be relative to workflow
    step, so that they can be compared."""
    def _rec_fields(rec):
        out = {}
        for field in rec['fields']:
            name = shortname(field['name'])
            out[name] = field['type']
        return out
    srcfields = _rec_fields(src)
    sinkfields = _rec_fields(sink)
    for key in six.iterkeys(sinkfields):
        if not can_assign_src_to_sink(srcfields.get(key, 'null'), sinkfields.get(key, 'null'), strict) and sinkfields.get(key) is not None:
            _logger.info('Record comparison failure for %s and %s\nDid not match fields for %s: %s and %s', src['name'], sink['name'], key, srcfields.get(key), sinkfields.get(key))
            return False
    return True

def check_all_types(src_dict, sinks, sourceField):
    """Given a list of sinks, check if their types match with the types of their sources.
    """
    validation = {'warning': [], 'exception': []}
    for sink in sinks:
        if sourceField in sink:
            valueFrom = sink.get('valueFrom')
            if isinstance(sink[sourceField], MutableSequence):
                srcs_of_sink = [src_dict[parm_id] for parm_id in sink[sourceField]]
                linkMerge = sink.get('linkMerge', 'merge_nested' if len(sink[sourceField]) > 1 else None)
            else:
                parm_id = sink[sourceField]
                srcs_of_sink = [src_dict[parm_id]]
                linkMerge = None
            for src in srcs_of_sink:
                check_result = check_types(src, sink, linkMerge, valueFrom)
                if check_result == 'warning':
                    validation['warning'].append(SrcSink(src, sink, linkMerge))
                elif check_result == 'exception':
                    validation['exception'].append(SrcSink(src, sink, linkMerge))
    return validation

def make_relative(base, obj):
    """Relativize the location URI of a File or Directory object."""
    uri = obj.get('location', obj.get('path'))
    if ':' in uri.split('/')[0] and (not uri.startswith('file://')):
        pass
    elif uri.startswith('file://'):
        uri = uri_file_path(uri)
        obj['location'] = os.path.relpath(uri, base)

def printdeps(obj, document_loader, stdout, relative_deps, uri, basedir=None, nestdirs=True):
    """Print a JSON representation of the dependencies of the CWL document."""
    deps = find_deps(obj, document_loader, uri, basedir=basedir, nestdirs=nestdirs)
    if relative_deps == 'primary':
        base = basedir if basedir else os.path.dirname(uri_file_path(str(uri)))
    elif relative_deps == 'cwd':
        base = os.getcwd()
    visit_class(deps, ('File', 'Directory'), functools.partial(make_relative, base))
    stdout.write(json_dumps(deps, indent=4))

def find_deps(obj, document_loader, uri, basedir=None, nestdirs=True):
    """Find the dependencies of the CWL document."""
    deps = {'class': 'File', 'location': uri, 'format': CWL_IANA}
    def loadref(base, uri):
        return document_loader.fetch(document_loader.fetcher.urljoin(base, uri))
    sfs = scandeps(basedir if basedir else uri, obj, {'$import', 'run'}, {'$include', '$schemas', 'location'}, loadref, nestdirs=nestdirs)
    if sfs is not None:
        deps['secondaryFiles'] = sfs
    return deps

def print_pack(document_loader, processobj, uri, metadata):
    """Return a CWL serialization of the CWL document in JSON."""
    packed = pack(document_loader, processobj, uri, metadata)
    if len(packed['$graph']) > 1:
        return json_dumps(packed, indent=4)
    return json_dumps(packed['$graph'][0], indent=4)

