    return default_container

def _whoami():
    """Return the current operating system account as (username, fullname)."""
    username = getuser()
    try:
        if onWindows():
            get_user_name = ctypes.windll.secur32.GetUserNameExW
            size = ctypes.pointer(ctypes.c_ulong(0))
            get_user_name(3, None, size)
            name_buffer = ctypes.create_unicode_buffer(size.contents.value)
            get_user_name(3, name_buffer, size)
            fullname = str(name_buffer.value)
        else:
            fullname = pwd.getpwuid(os.getuid())[4].split(',')[0]
    except (KeyError, IndexError):
        fullname = username
    return (username, fullname)

def copy_job_order(job, job_order_object):
    """Create copy of job object for provenance."""
    if not hasattr(job, 'tool'):
        return job_order_object
    customised_job = {}
    for each, i in enumerate(job.tool['inputs']):
        with SourceLine(job.tool['inputs'], each, WorkflowException, _logger.isEnabledFor(logging.DEBUG)):
            iid = shortname(i['id'])
            if iid in job_order_object:
                customised_job[iid] = copy.deepcopy(job_order_object[iid])
            elif 'default' in i:
                customised_job[iid] = copy.deepcopy(i['default'])
            else:
                pass
    return customised_job

def printrdf(wflow, ctx, style):
    """Serialize the CWL document into a string, ready for printing."""
    rdf = gather(wflow, ctx).serialize(format=style, encoding='utf-8')
    if not rdf:
        return u''
    return rdf.decode('utf-8')

def check_output_and_strip(cmd):
    """Passes a command list to subprocess.check_output, returning None
    if an expected exception is raised
    :param cmd: The command to execute
    :return: Stripped string output of the command, or None if error"""
    try:
        result = subprocess.check_output(cmd, stderr=subprocess.STDOUT)
        return result.strip()
    except (OSError, subprocess.CalledProcessError, TypeError, AttributeError):
        return None

def docker_machine_id():
    """Asks docker-machine for active machine and gets the UID of the docker user
    inside the vm
    :return: tuple (UID, GID), or (None, None) if error (e.g. docker-machine not present or stopped)"""
    machine_name = docker_machine_name()
    if not machine_name:
        return (None, None)
    uid = cmd_output_to_int(['docker-machine', 'ssh', machine_name, 'id -u'])
    gid = cmd_output_to_int(['docker-machine', 'ssh', machine_name, 'id -g'])
