def fetch_document(argsworkflow, loadingContext=None):
    """Retrieve a CWL document."""
    if loadingContext is None:
        loadingContext = LoadingContext()
        loadingContext.loader = default_loader()
    else:
        loadingContext = loadingContext.copy()
        if loadingContext.loader is None:
            loadingContext.loader = default_loader(loadingContext.fetcher_constructor)
    if isinstance(argsworkflow, string_types):
        uri, fileuri = resolve_tool_uri(argsworkflow, resolver=loadingContext.resolver, document_loader=loadingContext.loader)
        workflowobj = loadingContext.loader.fetch(fileuri)
        return (loadingContext, workflowobj, uri)
    if isinstance(argsworkflow, dict):
        uri = argsworkflow['id'] if argsworkflow.get('id') else '_:' + Text(uuid.uuid4())
        workflowobj = cast(CommentedMap, cmap(argsworkflow, fn=uri))
        loadingContext.loader.idx[uri] = workflowobj
        return (loadingContext, workflowobj, uri)
    raise ValidationException("Must be URI or object: '%s'" % argsworkflow)

def make_tool(uri, loadingContext):
    """Make a Python CWL object."""
    if loadingContext.loader is None:
        raise ValueError('loadingContext must have a loader')
    resolveduri, metadata = loadingContext.loader.resolve_ref(uri)
    processobj = None
    if isinstance(resolveduri, MutableSequence):
        for obj in resolveduri:
            if obj['id'].endswith('#main'):
                processobj = obj
                break
        if not processobj:
            raise WorkflowException(u'Tool file contains graph of multiple objects, must specify one of #%s' % ', #'.join((urllib.parse.urldefrag(i['id'])[1] for i in resolveduri if 'id' in i)))
    elif isinstance(resolveduri, MutableMapping):
        processobj = resolveduri
    else:
        raise Exception('Must resolve to list or dict')
    tool = loadingContext.construct_tool_object(processobj, loadingContext)
    if loadingContext.jobdefaults:
        jobobj = loadingContext.jobdefaults
        for inp in tool.tool['inputs']:
            if shortname(inp['id']) in jobobj:
                inp['default'] = jobobj[shortname(inp['id'])]
    return tool

def check_adjust(builder, file_o):
    """Map files to assigned path inside a container.

    We need to also explicitly walk over input, as implicit reassignment
    doesn't reach everything in builder.bindings"""
    if not builder.pathmapper:
        raise ValueError("Do not call check_adjust using a builder that doesn't have a pathmapper.")
    file_o['path'] = docker_windows_path_adjust(builder.pathmapper.mapper(file_o['location'])[1])
    dn, bn = os.path.split(file_o['path'])
    if file_o.get('dirname') != dn:
        file_o['dirname'] = Text(dn)
    if file_o.get('basename') != bn:
        file_o['basename'] = Text(bn)
    if file_o['class'] == 'File':
        nr, ne = os.path.splitext(file_o['basename'])
        if file_o.get('nameroot') != nr:
            file_o['nameroot'] = Text(nr)
        if file_o.get('nameext') != ne:
            file_o['nameext'] = Text(ne)
    if not ACCEPTLIST_RE.match(file_o['basename']):
        raise WorkflowException("Invalid filename: '{}' contains illegal characters".format(file_o['basename']))
    return file_o

def _flat_crossproduct_scatter(process, joborder, scatter_keys, callback, startindex, runtimeContext):
    """Inner loop."""
    scatter_key = scatter_keys[0]
    jobl = len(joborder[scatter_key])
    steps = []
    put = startindex
    for index in range(0, jobl):
        sjob = copy.copy(joborder)
        sjob[scatter_key] = joborder[scatter_key][index]
        if len(scatter_keys) == 1:
            if runtimeContext.postScatterEval is not None:
                sjob = runtimeContext.postScatterEval(sjob)
            steps.append(process.job(sjob, functools.partial(callback.receive_scatter_output, put), runtimeContext))
            put += 1
        else:
            add, _ = _flat_crossproduct_scatter(process, sjob, scatter_keys[1:], callback, put, runtimeContext)
            put += len(add)
            steps.extend(add)
    return (steps, put)

def formatSubclassOf(fmt, cls, ontology, visited):
    """Determine if `fmt` is a subclass of `cls`."""
    if URIRef(fmt) == URIRef(cls):
        return True
    if ontology is None:
        return False
    if fmt in visited:
        return False
    visited.add(fmt)
    uriRefFmt = URIRef(fmt)
    for s, p, o in ontology.triples((uriRefFmt, RDFS.subClassOf, None)):
        if formatSubclassOf(o, cls, ontology, visited):
            return True
    for s, p, o in ontology.triples((uriRefFmt, OWL.equivalentClass, None)):
        if formatSubclassOf(o, cls, ontology, visited):
            return True
    for s, p, o in ontology.triples((None, OWL.equivalentClass, uriRefFmt)):
        if formatSubclassOf(s, cls, ontology, visited):
            return True
    return False

def check_format(actual_file, input_formats, ontology):
    """Confirms that the format present is valid for the allowed formats."""
    for afile in aslist(actual_file):
        if not afile:
            continue
        if 'format' not in afile:
            raise validate.ValidationException(u"File has no 'format' defined: {}".format(json_dumps(afile, indent=4)))
        for inpf in aslist(input_formats):
            if afile['format'] == inpf or formatSubclassOf(afile['format'], inpf, ontology, set()):
                return
        raise validate.ValidationException(u'File has an incompatible format: {}'.format(json_dumps(afile, indent=4)))

def checkversion(doc, metadata, enable_dev):
    """Checks the validity of the version of the give CWL document.

    Returns the document and the validated version string."""
    cdoc = None
    if isinstance(doc, CommentedSeq):
        if not isinstance(metadata, CommentedMap):
            raise Exception('Expected metadata to be CommentedMap')
        lc = metadata.lc
        metadata = copy.deepcopy(metadata)
        metadata.lc.data = copy.copy(lc.data)
        metadata.lc.filename = lc.filename
        metadata[u'$graph'] = doc
        cdoc = metadata
    elif isinstance(doc, CommentedMap):
        cdoc = doc
    else:
        raise Exception('Expected CommentedMap or CommentedSeq')
    version = metadata[u'cwlVersion']
    cdoc['cwlVersion'] = version
    if version not in UPDATES:
        if version in DEVUPDATES:
            if enable_dev:
                pass
            else:
                raise validate.ValidationException(u"Version '%s' is a development or deprecated version.\n Update your document to a stable version (%s) or use --enable-dev to enable support for development and deprecated versions." % (version, ', '.join(list(UPDATES.keys()))))
        else:
            raise validate.ValidationException(u'Unrecognized version %s' % version)
    return (cdoc, version)

def avroize_type(field_type, name_prefix=''):
    """adds missing information to a type so that CWL types are valid in schema_salad."""
    if isinstance(field_type, MutableSequence):
        for field in field_type:
            avroize_type(field, name_prefix)
    elif isinstance(field_type, MutableMapping):
        if field_type['type'] in ('enum', 'record'):
            if 'name' not in field_type:
                field_type['name'] = name_prefix + Text(uuid.uuid4())
        if field_type['type'] == 'record':
            avroize_type(field_type['fields'], name_prefix)
        if field_type['type'] == 'array':
            avroize_type(field_type['items'], name_prefix)
        if isinstance(field_type['type'], MutableSequence):
            for ctype in field_type['type']:
                avroize_type(ctype, name_prefix)
    return field_type

def var_spool_cwl_detector(obj, item=None, obj_key=None):
    """Detects any textual reference to /var/spool/cwl."""
    r = False
    if isinstance(obj, string_types):
        if 'var/spool/cwl' in obj and obj_key != 'dockerOutputDirectory':
            _logger.warning(SourceLine(item=item, key=obj_key, raise_type=Text).makeError(_VAR_SPOOL_ERROR.format(obj)))
            r = True
    elif isinstance(obj, MutableMapping):
        for key, value in iteritems(obj):
            r = var_spool_cwl_detector(value, obj, key) or r
    elif isinstance(obj, MutableSequence):
        for key, value in enumerate(obj):
            r = var_spool_cwl_detector(value, obj, key) or r
    return r

def versionstring():
