def get_SHA1_bin(word):
    """Return SHA1 hash of any string

    :param word:
    :return:"""
    from hashlib import sha1
    if PY3 and isinstance(word, str):
        word = word.encode('utf-8')
    hash_s = sha1()
    hash_s.update(word)
    return bin(int(hash_s.hexdigest(), 16))[2:].zfill(160)

def _pprint_seq(seq, _nest_lvl=0, max_seq_items=None, **kwds):
    """internal. pprinter for iterables. you should probably use pprint_thing()
    rather then calling this directly.

    bounds length of printed sequence, depending on options"""
    if isinstance(seq, set):
        fmt = u('set([%s])')
    else:
        fmt = u('[%s]') if hasattr(seq, '__setitem__') else u('(%s)')
    if max_seq_items is False:
        nitems = len(seq)
    else:
        nitems = max_seq_items or options.display.max_seq_items or len(seq)
    s = iter(seq)
    r = []
    for i in range(min(nitems, len(seq))):
        r.append(pprint_thing(next(s), _nest_lvl + 1, max_seq_items=max_seq_items, **kwds))
    body = ', '.join(r)
    if nitems < len(seq):
        body += ', ...'
    elif isinstance(seq, tuple) and len(seq) == 1:
        body += ','
    return fmt % body

def _pprint_dict(seq, _nest_lvl=0, max_seq_items=None, **kwds):
    """internal. pprinter for iterables. you should probably use pprint_thing()
    rather then calling this directly."""
    fmt = u('{%s}')
    pairs = []
    pfmt = u('%s: %s')
    if max_seq_items is False:
        nitems = len(seq)
    else:
        nitems = max_seq_items or options.display.max_seq_items or len(seq)
    for k, v in list(seq.items())[:nitems]:
        pairs.append(pfmt % (pprint_thing(k, _nest_lvl + 1, max_seq_items=max_seq_items, **kwds), pprint_thing(v, _nest_lvl + 1, max_seq_items=max_seq_items, **kwds)))
    if nitems < len(seq):
        return fmt % (', '.join(pairs) + ', ...')
    else:
        return fmt % ', '.join(pairs)

def _justify(texts, max_len, mode='right'):
    """Perform ljust, center, rjust against string or list-like"""
    if mode == 'left':
        return [x.ljust(max_len) for x in texts]
    elif mode == 'center':
        return [x.center(max_len) for x in texts]
    else:
        return [x.rjust(max_len) for x in texts]

def _trim_zeros(str_floats, na_rep='NaN'):
    """Trims zeros and decimal points."""
    trimmed = str_floats
    def _cond(values):
        non_na = [x for x in values if x != na_rep]
        return len(non_na) > 0 and all([x.endswith('0') for x in non_na]) and (not any(['e' in x or 'E' in x for x in non_na]))
    while _cond(trimmed):
        trimmed = [x[:-1] if x != na_rep else x for x in trimmed]
    return [x[:-1] if x.endswith('.') and x != na_rep else x for x in trimmed]

def _contains(expr, pat, case=True, flags=0, regex=True):
    """Return boolean sequence whether given pattern/regex is contained in each string in the sequence

    :param expr: sequence or scalar
    :param pat: Character sequence or regular expression
    :param case: If True, case sensitive
    :type case: bool
    :param flags: re module flags, e.g. re.IGNORECASE
    :param regex: If True use regex, otherwise use string finder
    :return: sequence or scalar"""
    if regex and isinstance(pat, six.string_types):
        import re
        try:
            re.compile(pat, flags=flags)
        except:
            raise ValueError('Failed to compile regular expression, please check re.compile("{0}")'.format(pat))
    return _string_op(expr, Contains, output_type=types.boolean, _pat=pat, _case=case, _flags=flags, _regex=regex)

def _list_tables_model(self, prefix='', project=None):
    """List all TablesModel in the given project.

    :param prefix: model prefix
    :param str project: project name, if you want to look up in another project
    :rtype: list[str]"""
    tset = set()
    if prefix.startswith(TEMP_TABLE_PREFIX):
        prefix = TEMP_TABLE_MODEL_PREFIX + prefix[len(TEMP_TABLE_PREFIX):]
        it = self.list_tables(project=project, prefix=prefix)
    else:
        it = self.list_tables(project=project, prefix=TABLE_MODEL_PREFIX + prefix)
        if TEMP_TABLE_PREFIX.startswith(prefix):
            new_iter = self.list_tables(project=project, prefix=TEMP_TABLE_MODEL_PREFIX)
            it = itertools.chain(it, new_iter)
    for table in it:
        if TABLE_MODEL_SEPARATOR not in table.name:
            continue
        if not table.name.startswith(TEMP_TABLE_MODEL_PREFIX) and (not table.name.startswith(TABLE_MODEL_PREFIX)):
            continue
        model_name, _ = table.name.rsplit(TABLE_MODEL_SEPARATOR, 1)
        if model_name.startswith(TEMP_TABLE_MODEL_PREFIX):
            model_name = TEMP_TABLE_PREFIX + model_name[len(TEMP_TABLE_MODEL_PREFIX):]
        else:
            model_name = model_name[len(TABLE_MODEL_PREFIX):]
        if model_name not in tset:
            tset.add(model_name)
            yield TablesModelObject(_odps=self, name=model_name, project=project)

