def accuracy_score(df, col_true=None, col_pred=None, normalize=True):
    """Compute accuracy of a predicted DataFrame.

    Note that this method will trigger the defined flow to execute.

    :param df: predicted data frame
    :type df: DataFrame
    :param col_true: column name of true label
    :type col_true: str
    :param col_true: column name of predicted label, 'prediction_result' by default.
    :type col_pred: str
    :param normalize: denoting if the output is normalized between [0, 1]
    :type normalize: bool
    :return: Accuracy value
    :rtype: float"""
    if not col_pred:
        col_pred = get_field_name_by_role(df, FieldRole.PREDICTED_CLASS)
    mat, _ = _run_cm_node(df, col_true, col_pred)
    if np is not None:
        acc_count = np.sum(np.diag(mat))
        if not normalize:
            return acc_count
        else:
            return acc_count * 1.0 / np.sum(mat)
    else:
        diag_sum = mat_sum = 0
        mat_size = len(mat)
        for i in compat.irange(mat_size):
            for j in compat.irange(mat_size):
                if i == j:
                    diag_sum += mat[i][j]
                mat_sum += mat[i][j]
        if not normalize:
            return diag_sum
        else:
            return diag_sum * 1.0 / mat_sum

def _var_uint64_byte_size_no_tag(uint64):
    """Returns the bytes required to serialize a single varint.
    uint64 must be unsigned."""
    if uint64 > UINT64_MAX:
        raise errors.EncodeError('Value out of range: %d' % uint64)
    bytes = 1
    while uint64 > 127:
        bytes += 1
        uint64 >>= 7
    return bytes

def _make_skel_func(code, cell_count, base_globals=None):
    """Creates a skeleton function object that contains just the provided
    code and the correct number of cells in func_closure.  All other
    func attributes (e.g. func_globals) are empty."""
    if base_globals is None:
        base_globals = {}
    elif isinstance(base_globals, string_types):
        base_globals_name = base_globals
        try:
            if importlib is not None:
                base_globals = vars(importlib.import_module(base_globals))
            elif sys.modules.get(base_globals, None) is not None:
                base_globals = vars(sys.modules[base_globals])
            else:
                raise ImportError
        except ImportError:
            base_globals = _dynamic_modules_globals.get(base_globals_name, None)
            if base_globals is None:
                base_globals = _DynamicModuleFuncGlobals()
            _dynamic_modules_globals[base_globals_name] = base_globals
    base_globals['__builtins__'] = __builtins__
    closure = tuple((_make_empty_cell() for _ in range(cell_count))) if cell_count >= 0 else None
    return types.FunctionType(code, base_globals, None, None, closure)

