    :param expr: collection
    :param by: columns to group
    :param bys: columns to group
    :return: GroupBy instance
    :rtype: :class:`odps.df.expr.groupby.GroupBy`"""
    if not isinstance(by, list):
        by = [by]
    if len(bys) > 0:
        by = by + list(bys)
    return GroupBy(_input=expr, _by=by)

def concat(left, rights, distinct=False, axis=0):
    """Concat collections.

    :param left: left collection
    :param rights: right collections, can be a DataFrame object or a list of DataFrames
    :param distinct: whether to remove duplicate entries. only available when axis == 0
    :param axis: when axis == 0, the DataFrames are merged vertically, otherwise horizontally.
    :return: collection

    Note that axis==1 can only be used under Pandas DataFrames or XFlow.

    :Example:
    >>> df['name', 'id'].concat(df2['score'], axis=1)"""
    from ..utils import to_collection
    if isinstance(rights, Node):
        rights = [rights]
    if not rights:
        raise ValueError('At least one DataFrame should be provided.')
    if axis == 0:
        for right in rights:
            left = union(left, right, distinct=distinct)
        return left
    else:
        rights = [to_collection(r) for r in rights]
    ConcatCollectionExpr.validate_input(left, *rights)
    if hasattr(left, '_xflow_concat'):
        return left._xflow_concat(rights)
    else:
        return __horz_concat(left, rights)

def auth_required(method):
    """This decorator is used to ensure that a user is authenticated before
    being able to access a flask route. It also adds the current user to the
    current flask context."""
    @functools.wraps(method)
    def wrapper(*args, **kwargs):
        _verify_and_add_jwt()
        try:
            return method(*args, **kwargs)
        finally:
            remove_jwt_data_from_app_context()
    return wrapper

def roles_required(*required_rolenames):
    """This decorator ensures that any uses accessing the decorated route have all
    the needed roles to access it. If an @auth_required decorator is not
    supplied already, this decorator will implicitly check @auth_required first"""
    def decorator(method):
        @functools.wraps(method)
        def wrapper(*args, **kwargs):
            role_set = set([str(n) for n in required_rolenames])
            _verify_and_add_jwt()
            try:
                MissingRoleError.require_condition(current_rolenames().issuperset(role_set), 'This endpoint requires all the following roles: {}', [', '.join(role_set)])
                return method(*args, **kwargs)
            finally:
                remove_jwt_data_from_app_context()
        return wrapper
    return decorator

def roles_accepted(*accepted_rolenames):
    """This decorator ensures that any uses accessing the decorated route have one
    of the needed roles to access it. If an @auth_required decorator is not
    supplied already, this decorator will implicitly check @auth_required first"""
    def decorator(method):
        @functools.wraps(method)
        def wrapper(*args, **kwargs):
            role_set = set([str(n) for n in accepted_rolenames])
            _verify_and_add_jwt()
            try:
                MissingRoleError.require_condition(not current_rolenames().isdisjoint(role_set), 'This endpoint requires one of the following roles: {}', [', '.join(role_set)])
                return method(*args, **kwargs)
            finally:
                remove_jwt_data_from_app_context()
        return wrapper
    return decorator

def refresh():
    '''Refreshes an existing JWT by creating a new one that is a copy of the old
    except that it has a refrehsed access expiration.

    .. example::
       $ curl http://localhost:5000/refresh -X GET          -H "Authorization: Bearer <your_token>"'''
    old_token = guard.read_token_from_header()
    new_token = guard.refresh_jwt_token(old_token)
    ret = {'access_token': new_token}
    return (flask.jsonify(ret), 200)

def current_rolenames():
