def discover() -> List[Tuple[str, str]]:
    """Scan for connected modules and instantiate handler classes
    """
    if IS_ROBOT and os.path.isdir('/dev/modules'):
        devices = os.listdir('/dev/modules')
    else:
        devices = []
    discovered_modules = []
    module_port_regex = re.compile('|'.join(MODULE_TYPES.keys()), re.I)
    for port in devices:
        match = module_port_regex.search(port)
        if match:
            name = match.group().lower()
            if name not in MODULE_TYPES:
                log.warning('Unexpected module connected: {} on {}'.format(name, port))
                continue
            absolute_port = '/dev/modules/{}'.format(port)
            discovered_modules.append((absolute_port, name))
    log.info('Discovered modules: {}'.format(discovered_modules))
    return discovered_modules

def find_active_sysroot() -> str:
    """Parse /proc/cmdline to find the active sysroot. Return the path"""
    cmdline = _get_proc_cmdline()
    match = re.search(b'root=([/a-zA-Z0-9.]+)', cmdline)
    if not match:
        raise RuntimeError(f"Couldn't find bootpart from {cmdline}")
    return match.group(1).decode()

def _set_flow_rate(pipette, params) -> None:
    """Set flow rate in uL/mm, to value obtained from command's params."""
    flow_rate_param = params['flowRate']
    if not flow_rate_param > 0:
        raise RuntimeError('Positive flowRate param required')
    pipette.flow_rate = {'aspirate': flow_rate_param, 'dispense': flow_rate_param}

def infer_config_base_dir() -> Path:
    """Return the directory to store data in.

    Defaults are ~/.opentrons if not on a pi; OT_API_CONFIG_DIR is
    respected here.

    When this module is imported, this function is called automatically
    and the result stored in :py:attr:`APP_DATA_DIR`.

    This directory may not exist when the module is imported. Even if it
    does exist, it may not contain data, or may require data to be moved
    to it.

    :return pathlib.Path: The path to the desired root settings dir."""
    if 'OT_API_CONFIG_DIR' in os.environ:
        return Path(os.environ['OT_API_CONFIG_DIR'])
    elif IS_ROBOT:
        return Path('/data')
    else:
        search = (Path.cwd(), Path.home() / '.opentrons')
        for path in search:
            if (path / _CONFIG_FILENAME).exists():
                return path
        else:
            return search[-1]

def _load_with_overrides(base) -> Dict[str, str]:
    """Load an config or write its defaults"""
    should_write = False
    overrides = _get_environ_overrides()
    try:
        index = json.load((base / _CONFIG_FILENAME).open())
    except (OSError, json.JSONDecodeError) as e:
        sys.stderr.write('Error loading config from {}: {}\nRewriting...\n'.format(str(base), e))
        should_write = True
        index = generate_config_index(overrides)
    for key in CONFIG_ELEMENTS:
        if key.name not in index:
            sys.stderr.write(f'New config index key {key.name}={key.default}\nRewriting...\n')
            if key.kind in (ConfigElementType.DIR, ConfigElementType.FILE):
                index[key.name] = base / key.default
            else:
                index[key.name] = key.default
            should_write = True
    if should_write:
        try:
            write_config(index, path=base)
        except Exception as e:
            sys.stderr.write('Error writing config to {}: {}\nProceeding memory-only\n'.format(str(base), e))
    index.update(overrides)
    return index

def _ensure_paths_and_types(index: Dict[str, str]) -> Dict[str, Path]:
    """Take the direct results of loading the config and make sure
    the filesystem reflects them."""
    configs_by_name = {ce.name: ce for ce in CONFIG_ELEMENTS}
    correct_types: Dict[str, Path] = {}
    for key, item in index.items():
        if key not in configs_by_name:
            continue
        if configs_by_name[key].kind == ConfigElementType.FILE:
            it = Path(item)
            it.parent.mkdir(parents=True, exist_ok=True)
            correct_types[key] = it
        elif configs_by_name[key].kind == ConfigElementType.DIR:
            it = Path(item)
            it.mkdir(parents=True, exist_ok=True)
            correct_types[key] = it
        else:
            raise RuntimeError(f'unhandled kind in ConfigElements: {key}: {configs_by_name[key].kind}')
    return correct_types

def _get_environ_overrides() -> Dict[str, str]:
    """Pull any overrides for the config elements from the environ and return
    a mapping from the names to the values (as strings). Config elements that
    are not overridden will not be in the mapping."""
    return {ce.name: os.environ['OT_API_' + ce.name.upper()] for ce in CONFIG_ELEMENTS if 'OT_API_' + ce.name.upper() in os.environ}

def _legacy_index() -> Union[None, Dict[str, str]]:
    """Try and load an index file from the various places it might exist.

    If the legacy file cannot be found or cannot be parsed, return None.

    This method should only be called on a robot."""
    for index in _LEGACY_INDICES:
        if index.exists():
            try:
                return json.load(open(index))
            except (OSError, json.JSONDecodeError):
                return None
    return None

def _find_most_recent_backup(normal_path: Optional[str]) -> Optional[str]:
    """Find the most recent old settings to migrate.

    The input is the path to an unqualified settings file - e.g.
    /mnt/usbdrive/config/robotSettings.json

    This will return
    - None if the input is None (to support chaining from dict.get())
    - The input if it exists, or
    - The file named normal_path-TIMESTAMP.json with the highest timestamp
      if one can be found, or
    - None"""
    if normal_path is None:
        return None
    if os.path.exists(normal_path):
        return normal_path
    dirname, basename = os.path.split(normal_path)
    root, ext = os.path.splitext(basename)
    backups = [fi for fi in os.listdir(dirname) if fi.startswith(root) and fi.endswith(ext)]
    ts_re = re.compile('.*-([0-9]+)' + ext + '$')
    def ts_compare(filename):
        match = ts_re.match(filename)
        if not match:
            return -1
        else:
            return int(match.group(1))
    backups_sorted = sorted(backups, key=ts_compare)
    if not backups_sorted:
        return None
    return os.path.join(dirname, backups_sorted[-1])

def find_config(prefix: str) -> str:
    """Find the most recent config matching `prefix`"""
    matches = [conf for conf in config_models if conf.startswith(prefix)]
    if not matches:
        raise KeyError('No match found for prefix {}'.format(prefix))
    if prefix in matches:
        return prefix
    else:
        return sorted(matches)[0]

def _get_ignored_version():
    """:return: Most recently ignored API version"""
    if os.path.exists(filepath):
        with open(filepath) as data_file:
            data = json.load(data_file)
            version = data.get('version')
    else:
        version = None
    return version

def get_serial_ports_list():
    """Lists serial port names

    :raises EnvironmentError:
        On unsupported or unknown platforms
    :returns:
        A list of the serial ports available on the system"""
    if sys.platform.startswith('win'):
        ports = ['COM%s' % (i + 1) for i in range(256)]
    elif sys.platform.startswith('linux') or sys.platform.startswith('cygwin'):
        ports = glob.glob('/dev/tty*')
    elif sys.platform.startswith('darwin'):
        ports = glob.glob('/dev/tty.*')
    else:
        raise EnvironmentError('Unsupported platform')
    result = []
    port_filter = {'usbmodem', 'usbserial', 'COM', 'ACM', 'USB'}
    for port in ports:
        try:
            if any([f in port for f in port_filter]):
                s = serial.Serial()
                c = connection.Connection(s, port=port, baudrate=115200, timeout=0.01)
                c.open()
                result.append(port)
        except Exception as e:
            log.debug('Exception in testing port {}'.format(port))
            log.debug(e)
    return result

def ensure_value(config: dict, name: Union[str, Tuple[str, ...]], mutable_config_list: List[str]):
    """Pull value of config data from file. Shape can either be a dictionary with
    a value key -- indicating that it can be changed -- or another
    data structure such as an array."""
    if not isinstance(name, tuple):
        path: Tuple[str, ...] = (name,)
    else:
        path = name
    for element in path[:-1]:
        config = config[element]
    value = config[path[-1]]
    if path[-1] in mutable_config_list:
        value = value['value']
    return value

