def quirks_from_any_parent(loc: Union[Labware, Well, str, ModuleGeometry, None]) -> List[str]:
    """Walk the tree of wells and labwares and extract quirks"""
    def recursive_get_quirks(obj, found):
        if isinstance(obj, Labware):
            return found + obj.quirks
        elif isinstance(obj, Well):
            return recursive_get_quirks(obj.parent, found)
        else:
            return found
    return recursive_get_quirks(loc, [])

def require_linklocal(handler):
    """Ensure the decorated is only called if the request is linklocal.

    The host ip address should be in the X-Host-IP header (provided by nginx)"""
    @functools.wraps(handler)
    async def decorated(request: web.Request) -> web.Response:
        ipaddr_str = request.headers.get('x-host-ip')
        invalid_req_data = {'error': 'bad-interface', 'message': f'The endpoint {request.url} can only be used from local connections'}
        if not ipaddr_str:
            return web.json_response(data=invalid_req_data, status=403)
        try:
            addr = ipaddress.ip_address(ipaddr_str)
        except ValueError:
            LOG.exception(f"Couldn't parse host ip address {ipaddr_str}")
            raise
        if not addr.is_link_local:
            return web.json_response(data=invalid_req_data, status=403)
        return await handler(request)
    return decorated

def remove_by_hash(hashval: str):
    """Remove the key whose md5 sum matches hashval.

    :raises: KeyError if the hashval wasn't found"""
    key_details = get_keys()
    with authorized_keys('w') as ak:
        for keyhash, key in key_details:
            if keyhash != hashval:
                ak.write(f'{key}\n')
                break
        else:
            raise KeyError(hashval)

def run(**kwargs):
    """This function was necessary to separate from main() to accommodate for
    server startup path on system 3.0, which is server.main. In the case where
    the api is on system 3.0, server.main will redirect to this function with
    an additional argument of 'patch_old_init'. kwargs are hence used to allow
    the use of different length args"""
    log_init()
    loop = asyncio.get_event_loop()
    log.info('API server version:  {}'.format(__version__))
    if not os.environ.get('ENABLE_VIRTUAL_SMOOTHIE'):
        initialize_robot(loop)
        if ff.use_protocol_api_v2():
            loop.run_until_complete(hardware.cache_instruments())
        if not ff.disable_home_on_boot():
            log.info('Homing Z axes')
            if ff.use_protocol_api_v2():
                loop.run_until_complete(hardware.home_z())
            else:
                hardware.home_z()
        try:
            udev.setup_rules_file()
        except Exception:
            log.exception('Could not setup udev rules, modules may not be detected')
    resin.unlock_updates()
    server.run(kwargs.get('hostname'), kwargs.get('port'), kwargs.get('path'), loop)

def apply_reverse(t: Union[List[List[float]], np.ndarray], pos: Tuple[float, float, float], with_offsets=True) -> Tuple[float, float, float]:
    """Like apply_transform but inverts the transform first
    """
    return apply_transform(inv(t), pos)

def reset():
    """Unmount and remove the sqlite database (used in robot reset)"""
    if os.path.exists(database_path):
        os.remove(database_path)
    journal_path = database_path + '-journal'
    if os.path.exists(journal_path):
        os.remove(journal_path)

def _set_flow_rate(pipette_name, pipette, command_type, params, default_values):
    """Set flow rate in uL/mm, to value obtained from command's params,
    or if unspecified in command params, then from protocol's "default-values"."""
    default_aspirate = default_values.get('aspirate-flow-rate', {}).get(pipette_name)
    default_dispense = default_values.get('dispense-flow-rate', {}).get(pipette_name)
    flow_rate_param = params.get('flow-rate')
    if flow_rate_param is not None:
        if command_type == 'aspirate':
            pipette.flow_rate = {'aspirate': flow_rate_param, 'dispense': default_dispense}
            return
        if command_type == 'dispense':
            pipette.flow_rate = {'aspirate': default_aspirate, 'dispense': flow_rate_param}
            return
    pipette.flow_rate = {'aspirate': default_aspirate, 'dispense': default_dispense}

def _switch_partition() -> RootPartitions:
    """Switch the active boot partition using the switch script"""
    res = subprocess.check_output(['ot-switch-partitions'])
    for line in res.split(b'\n'):
        matches = re.match(b'Current boot partition: ([23]), setting to ([23])', line)
        if matches:
            return {b'2': RootPartitions.TWO, b'3': RootPartitions.THREE}[matches.group(2)]
    else:
        raise RuntimeError(f'Bad output from ot-switch-partitions: {res}')

def commit_update():
    """Switch the target boot partition."""
    unused = _find_unused_partition()
    new = _switch_partition()
    if new != unused:
        msg = f'Bad switch: switched to {new} when {unused} was unused'
        LOG.error(msg)
        raise RuntimeError(msg)
    else:
        LOG.info(f'commit_update: committed to booting {new}')

def parse_string_value_from_substring(substring) -> str:
    """Returns the ascii value in the expected string "N:aa11bb22", where "N" is
    the key, and "aa11bb22" is string value to be returned"""
    try:
        value = substring.split(':')[1]
        return str(value)
    except (ValueError, IndexError, TypeError, AttributeError):
        log.exception('Unexpected arg to parse_string_value_from_substring:')
        raise ParseError('Unexpected arg to parse_string_value_from_substring: {}'.format(substring))

def parse_number_from_substring(substring) -> Optional[float]:
    """Returns the number in the expected string "N:12.3", where "N" is the
    key, and "12.3" is a floating point value

    For the temp-deck or thermocycler's temperature response, one expected
    input is something like "T:none", where "none" should return a None value"""
    try:
        value = substring.split(':')[1]
        if value.strip().lower() == 'none':
            return None
        return round(float(value), GCODE_ROUNDING_PRECISION)
    except (ValueError, IndexError, TypeError, AttributeError):
        log.exception('Unexpected argument to parse_number_from_substring:')
        raise ParseError('Unexpected argument to parse_number_from_substring: {}'.format(substring))

def parse_temperature_response(temperature_string: str) -> Mapping[str, Optional[float]]:
    '''Example input: "T:none C:25"'''
    err_msg = 'Unexpected argument to parse_temperature_response: {}'.format(temperature_string)
    if not temperature_string or not isinstance(temperature_string, str):
        raise ParseError(err_msg)
    parsed_values = temperature_string.strip().split(' ')
    if len(parsed_values) < 2:
        log.error(err_msg)
        raise ParseError(err_msg)
    data = {parse_key_from_substring(s): parse_number_from_substring(s) for s in parsed_values[:2]}
    if 'C' not in data or 'T' not in data:
        raise ParseError(err_msg)
    data = {'current': data['C'], 'target': data['T']}
    return data

def parse_device_information(device_info_string: str) -> Mapping[str, str]:
    '''Parse the modules's device information response.

    Example response from temp-deck: "serial:aa11 model:bb22 version:cc33"'''
    error_msg = 'Unexpected argument to parse_device_information: {}'.format(device_info_string)
    if not device_info_string or not isinstance(device_info_string, str):
        raise ParseError(error_msg)
    parsed_values = device_info_string.strip().split(' ')
    if len(parsed_values) < 3:
        log.error(error_msg)
        raise ParseError(error_msg)
    res = {parse_key_from_substring(s): parse_string_value_from_substring(s) for s in parsed_values[:3]}
    for key in ['model', 'version', 'serial']:
        if key not in res:
            raise ParseError(error_msg)
    return res

def format_runlog(runlog: List[Mapping[str, Any]]) -> str:
    """Format a run log (return value of :py:meth:`simulate``) into a
    human-readable string

    :param runlog: The output of a call to :py:func:`simulate`"""
    to_ret = []
    for command in runlog:
        to_ret.append('\t' * command['level'] + command['payload'].get('text', '').format(**command['payload']))
        if command['logs']:
            to_ret.append('\t' * command['level'] + 'Logs from this command:')
            to_ret.extend(['\t' * command['level'] + f'{l.levelname} ({l.module}): {l.msg}' % l.args for l in command['logs']])
    return '\n'.join(to_ret)

def _version_less(version_a, version_b):
    """Takes two version as (major, minor, patch) tuples and returns a <= b.
    """
    if version_a[0] > version_b[0]:
        return False
    elif version_a[0] < version_b[0]:
        return True
    elif version_a[1] > version_b[1]:
        return False
    elif version_a[1] < version_b[1]:
        return True
    else:
        return version_a[2] < version_b[2]

def _eap_check_option_ok(opt: Dict[str, str], config: Dict[str, Any]):
    """Check that a given EAP option is in the user config (if required)
     and, if specified, is the right type.

    ``opt`` should be an options dict from EAP_CONFIG_SHAPE.
    ``config`` should be the user config dict.

    Before this method is called, the validity of the eapType key should be
    established."""
    if opt['name'] not in config:
        if opt['required']:
            raise ConfigureArgsError('Required argument {} for eap method {} not present'.format(opt['displayName'], config['eapType']))
        else:
            return
    name = opt['name']
    o_type = opt['type']
    arg = config[name]
    if name in config:
        if o_type in ('string', 'password') and (not isinstance(arg, str)):
            raise ConfigureArgsError('Option {} should be a str'.format(name))
        elif o_type == 'file' and (not isinstance(arg, str)):
            raise ConfigureArgsError('Option {} must be a str'.format(name))

def _eap_check_config(eap_config: Dict[str, Any]) -> Dict[str, Any]:
    """Check the eap specific args, and replace values where needed.

    Similar to _check_configure_args but for only EAP."""
    eap_type = eap_config.get('eapType')
    for method in EAP_CONFIG_SHAPE['options']:
        if method['name'] == eap_type:
            options = method['options']
            break
    else:
        raise ConfigureArgsError('EAP method {} is not valid'.format(eap_type))
    _eap_check_no_extra_args(eap_config, options)
    for opt in options:
        _eap_check_option_ok(opt, eap_config)
        if opt['type'] == 'file' and opt['name'] in eap_config:
            eap_config[opt['name']] = _get_key_file(eap_config[opt['name']])
    return eap_config

def _deduce_security(kwargs) -> nmcli.SECURITY_TYPES:
    """Make sure that the security_type is known, or throw."""
    sec_translation = {'wpa-psk': nmcli.SECURITY_TYPES.WPA_PSK, 'none': nmcli.SECURITY_TYPES.NONE, 'wpa-eap': nmcli.SECURITY_TYPES.WPA_EAP}
    if not kwargs.get('securityType'):
        if kwargs.get('psk') and kwargs.get('eapConfig'):
            raise ConfigureArgsError('Cannot deduce security type: psk and eap both passed')
        elif kwargs.get('psk'):
            kwargs['securityType'] = 'wpa-psk'
        elif kwargs.get('eapConfig'):
            kwargs['securityType'] = 'wpa-eap'
        else:
            kwargs['securityType'] = 'none'
    try:
        return sec_translation[kwargs['securityType']]
    except KeyError:
        raise ConfigureArgsError('securityType must be one of {}'.format(','.join(sec_translation.keys())))

def _check_configure_args(configure_args: Dict[str, Any]) -> Dict[str, Any]:
    """Check the arguments passed to configure.

    Raises an exception on failure. On success, returns a dict of
    configure_args with any necessary mutations."""
    if not configure_args.get('ssid') or not isinstance(configure_args['ssid'], str):
        raise ConfigureArgsError('SSID must be specified')
    if not configure_args.get('hidden'):
        configure_args['hidden'] = False
    elif not isinstance(configure_args['hidden'], bool):
        raise ConfigureArgsError('If specified, hidden must be a bool')
    configure_args['securityType'] = _deduce_security(configure_args)
    if configure_args['securityType'] == nmcli.SECURITY_TYPES.WPA_PSK:
        if not configure_args.get('psk'):
            raise ConfigureArgsError('If securityType is wpa-psk, psk must be specified')
        return configure_args
    if configure_args['securityType'] == nmcli.SECURITY_TYPES.WPA_EAP:
        if not configure_args.get('eapConfig'):
            raise ConfigureArgsError('If securityType is wpa-eap, eapConfig must be specified')
        configure_args['eapConfig'] = _eap_check_config(configure_args['eapConfig'])
        return configure_args
    return configure_args

def do_publish(broker, cmd, f, when, res, meta, *args, **kwargs):
    """Implement the publish so it can be called outside the decorator"""
    publish_command = functools.partial(broker.publish, topic=command_types.COMMAND)
    call_args = _get_args(f, args, kwargs)
    if when == 'before':
        broker.logger.info('{}: {}'.format(f.__qualname__, {k: v for k, v in call_args.items() if str(k) != 'self'}))
    command_args = dict(zip(reversed(inspect.getfullargspec(cmd).args), reversed(inspect.getfullargspec(cmd).defaults or [])))
    if 'instrument' in inspect.getfullargspec(cmd).args:
        if 'self' in call_args and 'instrument' not in call_args:
            call_args['instrument'] = call_args['self']
    command_args.update({key: call_args[key] for key in set(inspect.getfullargspec(cmd).args) & call_args.keys()})
    if meta:
        command_args['meta'] = meta
    payload = cmd(**command_args)
    message = {**payload, '$': when}
    if when == 'after':
        message['return'] = res
    publish_command(message={**payload, '$': when})

def position(axis, hardware, cp=None):
    """Read position from driver into a tuple and map 3-rd value
    to the axis of a pipette currently used"""
    if not ff.use_protocol_api_v2():
        p = hardware._driver.position
        return (p['X'], p['Y'], p[axis])
    else:
        p = hardware.gantry_position(axis, critical_point=cp)
        return (p.x, p.y, p.z)

def _update_pretty_hostname(new_val: str):
    """Write a new value for the pretty hostname.

    :raises OSError: If the new value could not be written."""
    try:
        with open('/etc/machine-info') as emi:
            contents = emi.read()
    except OSError:
        LOG.exception("Couldn't read /etc/machine-info")
        contents = ''
    new_contents = ''
    for line in contents.split('\n'):
        if not line.startswith('PRETTY_HOSTNAME'):
            new_contents += f'{line}\n'
    new_contents += f'PRETTY_HOSTNAME={new_val}\n'
    with open('/etc/machine-info', 'w') as emi:
        emi.write(new_contents)

def get_name(default: str='no name set'):
    """Get the currently-configured name of the machine"""
    try:
        with open('/etc/machine-info') as emi:
            contents = emi.read()
    except OSError:
        LOG.exception("Couldn't read /etc/machine-info")
        contents = ''
    for line in contents.split('\n'):
        if line.startswith('PRETTY_HOSTNAME='):
            return '='.join(line.split('=')[1:])
    LOG.warning(f'No PRETTY_HOSTNAME in {contents}, defaulting to {default}')
    try:
        _update_pretty_hostname(default)
    except OSError:
        LOG.exception('Could not write new pretty hostname!')
    return default

def get_custom_container_files():
    """Traverses environment.get_path('CONTAINERS_DIR') to retrieve
    all .json files"""
    def is_special_file(name):
        return name.startswith('.')
    res = []
    top = infer_config_base_dir() / 'containers'
    for root, dirnames, files in os.walk(top):
        for name in filter(is_special_file, dirnames):
            dirnames.remove(name)
        res.extend([os.path.join(root, name) for name in files if not is_special_file(name) and name.endswith('.json')])
    return res

def _setup_container(container_name):
    """Try and find a container in a variety of methods"""
    for meth in (database.load_container, load_new_labware, _load_weird_container):
        log.debug(f'Trying to load container {container_name} via {meth.__name__}')
        try:
            container = meth(container_name)
            if meth == _load_weird_container:
                container.properties['type'] = container_name
            log.info(f'Loaded {container_name} from {meth.__name__}')
            break
        except (ValueError, KeyError):
            log.info(f'{container_name} not in {meth.__name__}')
    else:
        raise KeyError(f'Unknown labware {container_name}')
    container_x, container_y, container_z = container._coordinates
    if container_z == 0 and 'height' in container[0].properties:
        container_z = container[0].properties['height']
    from opentrons.util.vector import Vector
    container._coordinates = Vector(container_x, container_y, container_z)
    return container

def _begin_write(session: UpdateSession, loop: asyncio.AbstractEventLoop, rootfs_file_path: str):
    """Start the write process."""
    session.set_progress(0)
    session.set_stage(Stages.WRITING)
    write_future = asyncio.ensure_future(loop.run_in_executor(None, file_actions.write_update, rootfs_file_path, session.set_progress))
    def write_done(fut):
        exc = fut.exception()
        if exc:
            session.set_error(getattr(exc, 'short', str(type(exc))), str(exc))
        else:
            session.set_stage(Stages.DONE)
    write_future.add_done_callback(write_done)

def from_list(commands):
    """Given a list of tuples of form (depth, text)
    that represents a DFS traversal of a command tree,
    returns a dictionary representing command tree."""
    def subtrees(commands, level):
        if not commands:
            return
        acc = []
        parent, *commands = commands
        for command in commands:
            if command['level'] > level:
                acc.append(command)
            else:
                yield (parent, acc)
                parent = command
                acc.clear()
        yield (parent, acc)
    def walk(commands, level=0):
        return [{'description': key['description'], 'children': walk(subtree, level + 1), 'id': key['id']} for key, subtree in subtrees(commands, level)]
    return walk(commands)

def _find_protocol_error(tb, proto_name):
    """Return the FrameInfo for the lowest frame in the traceback from the
    protocol."""
    tb_info = traceback.extract_tb(tb)
    for frame in reversed(tb_info):
        if frame.filename == proto_name:
            return frame
    else:
        raise KeyError

def connect(device_name=None, port=None, baudrate=115200):
    """Creates a serial connection
    :param device_name: defaults to 'Smoothieboard'
    :param baudrate: integer frequency for serial communication
    :return: serial.Serial connection"""
    if not port:
        port = get_ports_by_name(device_name=device_name)[0]
    log.debug('Device name: {}, Port: {}'.format(device_name, port))
    return _connect(port_name=port, baudrate=baudrate)

def _build_con_add_cmd(ssid: str, security_type: SECURITY_TYPES, psk: Optional[str], hidden: bool, eap_args: Optional[Dict[str, Any]]) -> List[str]:
    """Build the nmcli connection add command to configure the new network.

    The parameters are the same as configure but without the defaults; this
    should be called only by configure."""
    configure_cmd = ['connection', 'add', 'save', 'yes', 'autoconnect', 'yes', 'ifname', 'wlan0', 'type', 'wifi', 'con-name', ssid, 'wifi.ssid', ssid]
    if hidden:
        configure_cmd += ['wifi.hidden', 'true']
    if security_type == SECURITY_TYPES.WPA_PSK:
        configure_cmd += ['wifi-sec.key-mgmt', security_type.value]
        if psk is None:
            raise ValueError('wpa-psk security type requires psk')
        configure_cmd += ['wifi-sec.psk', psk]
    elif security_type == SECURITY_TYPES.WPA_EAP:
        if eap_args is None:
            raise ValueError('wpa-eap security type requires eap_args')
        configure_cmd += _add_eap_args(eap_args)
    elif security_type == SECURITY_TYPES.NONE:
        pass
    else:
        raise ValueError('Bad security_type {}'.format(security_type))
    return configure_cmd

def sanitize_args(cmd: List[str]) -> List[str]:
    """Filter the command so that it no longer contains passwords
    """
    sanitized = []
    for idx, fieldname in enumerate(cmd):
        def _is_password(cmdstr):
            return 'wifi-sec.psk' in cmdstr or 'password' in cmdstr.lower()
        if idx > 0 and _is_password(cmd[idx - 1]):
            sanitized.append('****')
        else:
            sanitized.append(fieldname)
    return sanitized

def _compress_for_repeater(max_vol, plan, **kwargs):
    """Reduce size of transfer plan, if mode is distribute or consolidate"""
    max_vol = float(max_vol)
    mode = kwargs.get('mode', 'transfer')
    if mode == 'distribute':
        return _compress_for_distribute(max_vol, plan, **kwargs)
    if mode == 'consolidate':
        return _compress_for_consolidate(max_vol, plan, **kwargs)
    else:
        return plan

def get_all_adv_settings() -> Dict[str, Dict[str, Union[str, bool, None]]]:
    ''':return: a dict of settings keyed by setting ID, where each value is a
        dict with keys "id", "title", "description", and "value"'''
    settings_file = CONFIG['feature_flags_file']
    values, _ = _read_settings_file(settings_file)
    return {key: {**settings_by_id[key].__dict__, 'value': value} for key, value in values.items()}

def _migrate0to1(previous: Mapping[str, Any]) -> SettingsMap:
    """Migrate to version 1 of the feature flags file. Replaces old IDs with new
    IDs and sets any False values to None"""
    next: SettingsMap = {}
    for s in settings:
        id = s.id
        old_id = s.old_id
        if previous.get(id) is True:
            next[id] = True
        elif previous.get(old_id) is True:
            next[id] = True
        else:
            next[id] = None
    return next

def _migrate(data: Mapping[str, Any]) -> SettingsData:
    """Check the version integer of the JSON file data a run any necessary
    migrations to get us to the latest file format. Returns dictionary of
    settings and version migrated to"""
    next = dict(data)
    version = next.pop('_version', 0)
    target_version = len(_MIGRATIONS)
    migrations = _MIGRATIONS[version:]
    if len(migrations) > 0:
        log.info('Migrating advanced settings from version {} to {}'.format(version, target_version))
    for m in migrations:
        next = m(next)
    return (next, target_version)

def _ensure_values(data: Mapping[str, Any]) -> Tuple[Dict[str, Any], bool]:
    """Make sure we have appropriate keys and say if we should write"""
    to_return = {}
    should_write = False
    for keyname, typekind, default in REQUIRED_DATA:
        if keyname not in data:
            LOG.debug(f'Defaulted config value {keyname} to {default}')
            to_return[keyname] = default
            should_write = True
        elif not isinstance(data[keyname], typekind):
            LOG.warning(f'Config value {keyname} was {type(data[keyname])} not {typekind}, defaulted to {default}')
            to_return[keyname] = default
            should_write = True
        else:
            to_return[keyname] = data[keyname]
    return (to_return, should_write)

def load_from_path(path: str) -> Config:
    """Load a config from a file and ensure its structure.
    Writes a default if necessary"""
    data = _ensure_load(path)
    if not data:
        data = {}
    values, should_write = _ensure_values(data)
    values.update({'path': path})
    config = Config(**values)
    if config.signature_required:
        if not os.path.exists(config.update_cert_path):
            LOG.warning(f'No signing cert is present in {config.update_cert_path}, code signature checking disabled')
            config = config._replace(signature_required=False)
            config = config._replace(update_cert_path=DEFAULT_CERT_PATH)
    if should_write:
        save_to_path(path, config)
    return config

def _get_path(args_path: Optional[str]) -> str:
    """Find the valid path from args then env then default"""
    env_path = os.getenv(PATH_ENVIRONMENT_VARIABLE)
    for path, source in ((args_path, 'arg'), (env_path, 'env')):
        if not path:
            LOG.debug(f'config.load: skipping {source} (path None)')
            continue
        else:
            LOG.debug(f'config.load: using config path {path} from {source}')
            return path
    return DEFAULT_PATH

def descendants(state, obj, level=0):
    """Returns a flattened list tuples of DFS traversal of subtree
    from object that contains descendant object and it's depth"""
    return sum([[(child, level)] + descendants(state, child, level + 1) for child in state[obj].children], [])

def _parse_number_from_substring(smoothie_substring):
    """Returns the number in the expected string "N:12.3", where "N" is the
    axis, and "12.3" is a floating point value for the axis' position"""
    try:
        return round(float(smoothie_substring.split(':')[1]), GCODE_ROUNDING_PRECISION)
    except (ValueError, IndexError, TypeError, AttributeError):
        log.exception('Unexpected argument to _parse_number_from_substring:')
        raise ParseError('Unexpected argument to _parse_number_from_substring: {}'.format(smoothie_substring))

def _parse_axis_from_substring(smoothie_substring):
    """Returns the axis in the expected string "N:12.3", where "N" is the
    axis, and "12.3" is a floating point value for the axis' position"""
    try:
        return smoothie_substring.split(':')[0].title()
    except (ValueError, IndexError, TypeError, AttributeError):
        log.exception('Unexpected argument to _parse_axis_from_substring:')
        raise ParseError('Unexpected argument to _parse_axis_from_substring: {}'.format(smoothie_substring))

def load(robot, container_name, slot, label=None, share=False):
    """Examples
    --------
    >>> from opentrons import containers
    >>> containers.load('96-flat', '1')
    <Deck>/<Slot 1>/<Container 96-flat>
    >>> containers.load('96-flat', '4', 'plate')
    <Deck>/<Slot 4>/<Container plate>
    >>> containers.load('non-existent-type', '4') # doctest: +ELLIPSIS
    Exception: Container type "non-existent-type" not found in file ..."""
    def is_ot_one_slot_name(s):
        return isinstance(s, str) and len(s) == 2 and (s[0] in 'ABCD')
    def convert_ot_one_slot_names(s):
        col = 'ABCD'.index(slot[0])
        row = int(slot[1]) - 1
        slot_number = col + row * robot.get_max_robot_cols() + 1
        log.warning('Changing deprecated slot name "{}" to "{}"'.format(slot, slot_number))
        return slot_number
    if isinstance(slot, str):
        try:
            slot = int(slot)
        except (ValueError, TypeError):
            if is_ot_one_slot_name(slot):
                slot = convert_ot_one_slot_names(slot)
    if helpers.is_number(slot):
        if not 1 <= slot <= len(robot.deck):
            raise ValueError('Unknown slot: {}'.format(slot))
        slot = str(slot)
    return robot.add_container(container_name, slot, label, share)

def get_android_hierarchy(d):
    """Returns:
        JSON object"""
    page_xml = d.dump_hierarchy(compressed=False, pretty=False).encode('utf-8')
    dom = xml.dom.minidom.parseString(page_xml)
    root = dom.documentElement
    def travel(node):
        if node.attributes is None:
            return
        json_node = parse_uiautomator_node(node)
        json_node['id'] = str(uuid.uuid4())
        if node.childNodes:
            children = []
            for n in node.childNodes:
                sub_hierarchy = travel(n)
                if sub_hierarchy:
                    children.append(sub_hierarchy)
            json_node['children'] = children
        return json_node
    return travel(root)

def new_as_dict(self, raw=True, vars=None):
    """Convert an INI file to a dictionary"""
    result = {}
    for section in self.sections():
        if section not in result:
            result[section] = {}
        for option in self.options(section):
            value = self.get(section, option, raw=raw, vars=vars)
            try:
                value = cherrypy.lib.reprconf.unrepr(value)
            except Exception:
                x = sys.exc_info()[1]
                msg = 'Config error in section: %r, option: %r, value: %r. Config values must be valid Python.' % (section, option, value)
                raise ValueError(msg, x.__class__.__name__, x.args)
            result[section][option] = value
    return result

def get_loglevel(level):
    """return logging level object
    corresponding to a given level passed as
    a string
    @str level: name of a syslog log level
    @rtype: logging, logging level from logging module"""
    if level == 'debug':
        return logging.DEBUG
    elif level == 'notice':
        return logging.INFO
    elif level == 'info':
        return logging.INFO
    elif level == 'warning' or level == 'warn':
        return logging.WARNING
    elif level == 'error' or level == 'err':
        return logging.ERROR
    elif level == 'critical' or level == 'crit':
        return logging.CRITICAL
    elif level == 'alert':
        return logging.CRITICAL
    elif level == 'emergency' or level == 'emerg':
        return logging.CRITICAL
    else:
        return logging.INFO

def toggle_favorite(request):
    """Add/remove an object to the user's favorites. Checks for existance and adds if not, else removes.
    This is the underlying mechanism for adding items to the user 'scrapbook' and favorite scripts.

    :param request:
    :param file_id:
    :return:"""
    if not request.is_ajax():
        return HttpResponseForbidden()
    try:
        app, model, pk = (request.POST['app'], request.POST['model'], int(request.POST['pk']))
    except ValueError:
        return HttpResponseBadRequest()
    try:
        ctype = ContentType.objects.get(app_label=app, model=model)
        obj = ctype.get_object_for_this_type(id=pk)
    except Favorite.DoesNotExist:
        return HttpResponseNotFound()
    try:
        fave = Favorite.objects.get(content_type=ctype, object_id=obj.id, user=request.user)
    except Favorite.DoesNotExist:
        fave = Favorite(content_object=obj, user=request.user)
        fave.save()
        is_favorite = True
    else:
        fave.delete()
        is_favorite = False
    favorites_count = Favorite.objects.filter(content_type=ctype, user=request.user).count()
    return JsonResponse({'app': app, 'model': model, 'pk': pk, 'is_favorite': is_favorite, 'count': favorites_count})

def cleanup_dead_jobs():
    """This cleans up jobs that have been marked as ran, but are not queue'd in celery. It is meant
    to cleanup jobs that have been lost due to a server crash or some other reason a job is
    in limbo."""
    from .models import WooeyJob
    inspect = celery_app.control.inspect()
    active_tasks = {task['id'] for worker, tasks in six.iteritems(inspect.active()) for task in tasks}
    active_jobs = WooeyJob.objects.filter(status=WooeyJob.RUNNING)
    to_disable = set()
    for job in active_jobs:
        if job.celery_id not in active_tasks:
            to_disable.add(job.pk)
    WooeyJob.objects.filter(pk__in=to_disable).update(status=WooeyJob.FAILED)

