def jinja_filter_param_value_str(value, str_quote_style='', bool_is_str=False):
    """Convert a parameter value to string suitable to be passed to an EDA tool

    Rules:
    - Booleans are represented as 0/1 or "true"/"false" depending on the
      bool_is_str argument
    - Strings are either passed through or enclosed in the characters specified
      in str_quote_style (e.g. '"' or '\\"')
    - Everything else (including int, float, etc.) are converted using the str()
      function."""
    if type(value) == bool and (not bool_is_str):
        if value == True:
            return '1'
        else:
            return '0'
    elif type(value) == str or (type(value) == bool and bool_is_str):
        return str_quote_style + str(value) + str_quote_style
    else:
        return str(value)

def infer_operands_size(operands):
    """Infer x86 instruction operand size based on other operands.
    """
    size = None
    for oprnd in operands:
        if oprnd.size:
            size = oprnd.size
            break
    if size:
        for oprnd in operands:
            if not oprnd.size:
                oprnd.size = size
    else:
        for oprnd in operands:
            if isinstance(oprnd, X86ImmediateOperand) and (not oprnd.size):
                oprnd.size = arch_info.architecture_size

def load_symbols_elf(filename):
    """Load the symbol tables contained in the file
    """
    f = open(filename, 'rb')
    elffile = ELFFile(f)
    symbols = []
    for section in elffile.iter_sections():
        if not isinstance(section, SymbolTableSection):
            continue
        if section['sh_entsize'] == 0:
            logger.warn('Symbol table {} has a sh_entsize of zero.'.format(section.name))
            continue
        logger.info('Symbol table {} contains {} entries.'.format(section.name, section.num_symbols()))
        for _, symbol in enumerate(section.iter_symbols()):
            if describe_symbol_shndx(symbol['st_shndx']) != 'UND' and describe_symbol_type(symbol['st_info']['type']) == 'FUNC':
                symbols.append((symbol['st_value'], symbol['st_size'], symbol.name))
    f.close()
    symbols_by_addr = {addr: (name, size, True) for addr, size, name in symbols}
    return symbols_by_addr

def bb_get_instr_max_width(basic_block):
    """Get maximum instruction mnemonic width
    """
    asm_mnemonic_max_width = 0
    for instr in basic_block:
        if len(instr.mnemonic) > asm_mnemonic_max_width:
            asm_mnemonic_max_width = len(instr.mnemonic)
    return asm_mnemonic_max_width

def parse_operand(string, location, tokens):
    """Parse instruction operand.
    """
    sizes = {'dqword': 128, 'pointer': 72, 'qword': 64, 'pointer': 40, 'dword': 32, 'word': 16, 'byte': 8, 'bit': 1}
    if 'immediate' in tokens:
        imm_str = ''.join(tokens['immediate'])
        base = 16 if imm_str.startswith('0x') or imm_str.startswith('-0x') else 10
        imm = int(imm_str, base)
        oprnd = ReilImmediateOperand(imm)
    if 'register' in tokens:
        if tokens['register'] in ['e', 'empty']:
            oprnd = ReilEmptyOperand()
            oprnd.size = 0
        else:
            name = tokens['register']
            oprnd = ReilRegisterOperand(name)
    if 'size' in tokens:
        oprnd.size = int(sizes[tokens['size']])
    return [oprnd]

def parse_instruction(string, location, tokens):
    """Parse an ARM instruction.
    """
    mnemonic_str = tokens.get('mnemonic')
    operands = [op for op in tokens.get('operands', [])]
    instr = ArmInstruction(string, mnemonic_str['ins'], operands, arch_info.architecture_mode)
    if 'cc' in mnemonic_str:
        instr.condition_code = cc_mapper[mnemonic_str['cc']]
    if 'uf' in mnemonic_str:
        instr.update_flags = True
    if 'ldm_stm_addr_mode' in mnemonic_str:
        instr.ldm_stm_addr_mode = ldm_stm_am_mapper[mnemonic_str['ldm_stm_addr_mode']]
    return instr

def extract_path_arguments(path):
    """Extracts a swagger path arguments from the given flask path.
    This /path/<parameter> extracts [{name: 'parameter'}]
    And this /<string(length=2):lang_code>/<string:id>/<float:probability>
    extracts: [
      {name: 'lang_code', dataType: 'string'},
      {name: 'id', dataType: 'string'}
      {name: 'probability', dataType: 'float'}]"""
    path = re.sub('\\([^\\)]*\\)', '', path)
    args = re.findall('<([^>]+)>', path)
    def split_arg(arg):
        spl = arg.split(':')
        if len(spl) == 1:
            return {'name': spl[0], 'dataType': 'string', 'paramType': 'path'}
        else:
            return {'name': spl[1], 'dataType': spl[0], 'paramType': 'path'}
    return list(map(split_arg, args))

