def rationalize_until(until=None):
    """Rationalizes the `until` argument used by other functions. This function
    accepts datetime and timedelta instances as well as integers representing
    epoch values."""
    if until is None:
        until = '+inf'
    elif isinstance(until, datetime):
        until = to_unix(until)
    elif isinstance(until, timedelta):
        until = to_unix(datetime.utcnow() + until)
    return until

def _checkDimensionsListLike(arrays):
    """Check that each array in a list of arrays has the same size.

    """
    dim1 = len(arrays)
    dim2, dim3 = arrays[0].shape
    for aa in range(1, dim1):
        dim2_aa, dim3_aa = arrays[aa].shape
        if dim2_aa != dim2 or dim3_aa != dim3:
            raise _error.InvalidError(_MDPERR['obj_square'])
    return (dim1, dim2, dim3)

def _checkRewardsListLike(reward, n_actions, n_states):
    """Check that a list-like reward input is valid.

    """
    try:
        lenR = len(reward)
        if lenR == n_actions:
            dim1, dim2, dim3 = _checkDimensionsListLike(reward)
        elif lenR == n_states:
            dim1 = n_actions
            dim2 = dim3 = lenR
        else:
            raise _error.InvalidError(_MDPERR['R_shape'])
    except AttributeError:
        raise _error.InvalidError(_MDPERR['R_shape'])
    return (dim1, dim2, dim3)

def isSquare(matrix):
    """Check that ``matrix`` is square.

    Returns
    =======
    is_square : bool
        ``True`` if ``matrix`` is square, ``False`` otherwise."""
    try:
        try:
            dim1, dim2 = matrix.shape
        except AttributeError:
            dim1, dim2 = _np.array(matrix).shape
    except ValueError:
        return False
    if dim1 == dim2:
        return True
    return False

def isStochastic(matrix):
    """Check that ``matrix`` is row stochastic.

    Returns
    =======
    is_stochastic : bool
        ``True`` if ``matrix`` is row stochastic, ``False`` otherwise."""
    try:
        absdiff = _np.abs(matrix.sum(axis=1) - _np.ones(matrix.shape[0]))
    except AttributeError:
        matrix = _np.array(matrix)
        absdiff = _np.abs(matrix.sum(axis=1) - _np.ones(matrix.shape[0]))
    return absdiff.max() <= 10 * _np.spacing(_np.float64(1))

def isNonNegative(matrix):
    """Check that ``matrix`` is row non-negative.

    Returns
    =======
    is_stochastic : bool
        ``True`` if ``matrix`` is non-negative, ``False`` otherwise."""
    try:
        if (matrix >= 0).all():
            return True
    except (NotImplementedError, AttributeError, TypeError):
        try:
            if (matrix.data >= 0).all():
                return True
        except AttributeError:
            matrix = _np.array(matrix)
            if (matrix.data >= 0).all():
                return True
    return False

def getTransitionProbabilities(state, action):
    """Parameters
    ----------
    state : tuple
        The state
    action : int
        The action

    Returns
    -------
    s1, p, r : tuple of two lists and an int
        s1 are the next states, p are the probabilities, and r is the reward"""
    assert 0 <= action < ACTIONS
    if not isLegal(state, action):
        s1 = [convertTupleToIndex(state)]
        return (s1, [1], -10)
    state = list(state)
    state[action] = PLAYER
    if isWon(state, PLAYER):
        s1 = [convertTupleToIndex(state)]
        return (s1, [1], 1)
    elif isDraw(state):
        s1 = [convertTupleToIndex(state)]
        return (s1, [1], 0)
    s1 = []
    p = []
    legal_a = getLegalActions(state)
    for a in legal_a:
        state[a] = OPPONENT
        if isWon(state, OPPONENT):
            s1 = [convertTupleToIndex(state)]
            return (s1, [1], -1)
        elif isDraw(state):
            s1 = [convertTupleToIndex(state)]
            return (s1, [1], 0)
        s1.append(convertTupleToIndex(state))
        p.append(1.0 / len(legal_a))
        state[a] = 0
    return (s1, p, 0)

def _randDense(states, actions, mask):
    """Generate random dense ``P`` and ``R``. See ``rand`` for details.

    """
    P = _np.zeros((actions, states, states))
    R = _np.zeros((actions, states, states))
    for action in range(actions):
        for state in range(states):
            if mask is None:
                m = _np.random.random(states)
                r = _np.random.random()
                m[m <= r] = 0
                m[m > r] = 1
            elif mask.shape == (actions, states, states):
                m = mask[action][state]
            else:
                m = mask[state]
            if m.sum() == 0:
                m[_np.random.randint(0, states)] = 1
            P[action][state] = m * _np.random.random(states)
            P[action][state] = P[action][state] / P[action][state].sum()
            R[action][state] = m * (2 * _np.random.random(states) - _np.ones(states, dtype=int))
    return (P, R)

def get_base_url(config, url):
    """Look through config and try to find best matching base for 'url'

    config - result of read_config() or read_global_config()
    url - artifactory url to search the base for"""
    if not config:
        return None
    for item in config:
        if url.startswith(item):
            return item
    for item in config:
        if without_http_prefix(url).startswith(without_http_prefix(item)):
            return item

