def sha1sum(filename):
    """Calculates sha1 hash of a file"""
    sha1 = hashlib.sha1()
    with open(filename, 'rb') as f:
        for chunk in iter(lambda: f.read(128 * sha1.block_size), b''):
            sha1.update(chunk)
    return sha1.hexdigest()

def chunks(data, size):
    """Get chink for dict, copy as-is from https://stackoverflow.com/a/8290508/6753144"""
    it = iter(data)
    for i in range(0, len(data), size):
        yield {k: data[k] for k in islice(it, size)}

def encode_matrix_parameters(parameters):
    """Performs encoding of url matrix parameters from dictionary to
    a string.
    See http://www.w3.org/DesignIssues/MatrixURIs.html for specs."""
    result = []
    for param in iter(sorted(parameters)):
        if isinstance(parameters[param], (list, tuple)):
            value = (';%s=' % param).join(parameters[param])
        else:
            value = parameters[param]
        result.append('%s=%s' % (param, value))
    return ';'.join(result)

def walk(pathobj, topdown=True):
    """os.walk like function to traverse the URI like a file system.

    The only difference is that this function takes and returns Path objects
    in places where original implementation will return strings"""
    dirs, nondirs = ([], [])
    for child in pathobj:
        relpath = str(child.relative_to(str(pathobj)))
        if relpath.startswith('/'):
            relpath = relpath[1:]
        if relpath.endswith('/'):
            relpath = relpath[:-1]
        if child.is_dir():
            dirs.append(relpath)
        else:
            nondirs.append(relpath)
    if topdown:
        yield (pathobj, dirs, nondirs)
    for dir in dirs:
        for result in walk(pathobj / dir):
            yield result
    if not topdown:
        yield (pathobj, dirs, nondirs)

def query_more(fn, offset, size, batch_size, *args):
    """list all data using the fn
    """
    if size < 0:
        expected_total_size = six.MAXSIZE
    else:
        expected_total_size = size
        batch_size = min(size, batch_size)
    response = None
    total_count_got = 0
    complete = False
    while True:
        ret = fn(*args, offset=offset, size=batch_size)
        if response is None:
            response = ret
        else:
            response.merge(ret)
        if not ret.is_completed():
            break
        count = ret.get_count()
        offset += count
        total_count_got += count
        batch_size = min(batch_size, expected_total_size - total_count_got)
        if count == 0 or total_count_got >= expected_total_size:
            break
    return response

def _parse_shard_list(shard_list, current_shard_list):
    """parse shard list
    :param shard_list: format like: 1,5-10,20
    :param current_shard_list: current shard list
    :return:"""
    if not shard_list:
        return current_shard_list
    target_shards = []
    for n in shard_list.split(','):
        n = n.strip()
        if n.isdigit() and n in current_shard_list:
            target_shards.append(n)
        elif n:
            rng = n.split('-')
            if len(rng) == 2:
                s = rng[0].strip()
                e = rng[1].strip()
                if s.isdigit() and e.isdigit():
                    for x in range(int(s), int(e) + 1):
                        if str(x) in current_shard_list:
                            target_shards.append(str(x))
    logger.info("parse_shard, shard_list: '{0}' current shard '{1}' result: '{2}'".format(shard_list, current_shard_list, target_shards))
    if not target_shards:
        raise LogException('InvalidParameter', "There's no available shard with settings {0}".format(shard_list))
    return target_shards

