def can_use_widgets():
    """Expanded from from http://stackoverflow.com/a/34092072/1958900
    """
    if 'IPython' not in sys.modules:
        return False
    from IPython import get_ipython
    if getattr(get_ipython(), 'kernel', None) is None:
        return False
    try:
        import ipywidgets as ipy
        import traitlets
    except ImportError:
        return False
    if int(ipy.__version__.split('.')[0]) < 6:
        print('WARNING: widgets require ipywidgets 6.0 or later')
        return False
    return True

def support_event_list_simple(fn):
    """enable __call__ to accept event_list.
    :param fn:
    :return:"""
    @wraps(fn)
    def _wrapped(self, event, *args, **kwargs):
        if _is_event_list(event):
            result = []
            for e in event:
                ret = fn(self, e, *args, **kwargs)
                if ret is None:
                    continue
                if isinstance(ret, (tuple, list)):
                    result.extend(ret)
                else:
                    result.append(ret)
            if result:
                if len(result) == 1:
                    return result[0]
                return result
            return None
        else:
            return fn(self, event, *args, **kwargs)
    return _wrapped

def u(d):
    """convert string, string container or unicode
    :param d:
    :return:"""
    if six.PY2:
        if isinstance(d, six.binary_type):
            return d.decode('utf8', 'ignore')
        elif isinstance(d, list):
            return [u(x) for x in d]
        elif isinstance(d, tuple):
            return tuple((u(x) for x in d))
        elif isinstance(d, dict):
            return dict(((u(k), u(v)) for k, v in six.iteritems(d)))
    return d

def consumer_process_task(processor, log_groups, check_point_tracker):
    """return TaskResult if failed,
    return ProcessTaskResult if succeed
