    :param cursor_position:
    :param cursor_start_time:
    :return:"""
    try:
        processor.initialize(shard_id)
        is_cursor_persistent = False
        check_point = consumer_client.get_check_point(shard_id)
        if check_point['checkpoint'] and len(check_point['checkpoint']) > 0:
            is_cursor_persistent = True
            cursor = check_point['checkpoint']
        elif cursor_position == CursorPosition.BEGIN_CURSOR:
            cursor = consumer_client.get_begin_cursor(shard_id)
        elif cursor_position == CursorPosition.END_CURSOR:
            cursor = consumer_client.get_end_cursor(shard_id)
        else:
            cursor = consumer_client.get_cursor(shard_id, cursor_start_time)
        end_cursor = None
        if cursor_end_time is not None:
            end_cursor = consumer_client.get_cursor(shard_id, cursor_end_time)
        return InitTaskResult(cursor, is_cursor_persistent, end_cursor)
    except Exception as e:
        return TaskResult(e)

def consumer_shutdown_task(processor, check_point_tracker):
    """:param processor:
    :param check_point_tracker:
    :return:"""
    exception = None
    try:
        processor.shutdown(check_point_tracker)
    except Exception as e:
        print(e)
        exception = None
    try:
        check_point_tracker.get_check_point()
    except Exception:
        logger.error('Failed to flush check point', exc_info=True)
    return TaskResult(exception)

def nCk(n, k):
    """http://blog.plover.com/math/choose.html"""
    if k > n:
        return 0
    if k == 0:
        return 1
    r = 1
    for d in range(1, k + 1):
        r *= n
        r /= d
        n -= 1
    return r

def command2str(num):
    """Turn command number into name"""
    for attr in SLOT.__dict__.keys():
        if not attr.startswith('_') and attr == attr.upper():
            if getattr(SLOT, attr) == num:
                return 'SLOT_%s' % attr
    return '0x%02x' % num

def _get_flag(which, flags):
    """Find 'which' entry in 'flags'."""
    res = [this for this in flags if this.is_equal(which)]
    if len(res) == 0:
        return None
    if len(res) == 1:
        return res[0]
    assert ()

def crc16(data):
    """Calculate an ISO13239 CRC checksum of the input buffer (bytestring)."""
    m_crc = 65535
    for this in data:
        m_crc ^= ord_byte(this)
        for _ in range(8):
            j = m_crc & 1
            m_crc >>= 1
            if j:
                m_crc ^= 33800
    return m_crc

def hexdump(src, length=8, colorize=False):
    """Produce a string hexdump of src, for debug output.

    Input: bytestring; output: text string"""
    if not src:
        return str(src)
    if type(src) is not bytes:
        raise yubico_exception.InputError("Hexdump 'src' must be bytestring (got %s)" % type(src))
    offset = 0
    result = ''
    for this in group(src, length):
        if colorize:
            last, this = (this[-1], this[:-1])
            colors = DumpColors()
            color = colors.get('RESET')
            if ord_byte(last) & yubikey_defs.RESP_PENDING_FLAG:
                color = colors.get('BLUE')
            elif ord_byte(last) & yubikey_defs.SLOT_WRITE_FLAG:
                color = colors.get('GREEN')
            hex_s = color + ' '.join(['%02x' % ord_byte(x) for x in this]) + colors.get('RESET')
            hex_s += ' %02x' % ord_byte(last)
        else:
            hex_s = ' '.join(['%02x' % ord_byte(x) for x in this])
        result += '%04X   %s\n' % (offset, hex_s)
        offset += length
    return result

def modhex_decode(data):
    """Convert a modhex bytestring to ordinary hex."""
    try:
        maketrans = string.maketrans
    except AttributeError:
        maketrans = bytes.maketrans
    t_map = maketrans(b'cbdefghijklnrtuv', b'0123456789abcdef')
    return data.translate(t_map)

def tlv_parse(data):
    """Parses a bytestring of TLV values into a dict with the tags as keys."""
    parsed = {}
    while data:
        t, l, data = (ord_byte(data[0]), ord_byte(data[1]), data[2:])
        parsed[t], data = (data[:l], data[l:])
    return parsed

def get_version():
    """Return the current version as defined by yubico/yubico_version.py."""
    with open('yubico/yubico_version.py', 'r') as f:
        match = VERSION_PATTERN.search(f.read())
        return match.group(1)

def find_key(debug=False, skip=0):
    """Locate a connected YubiKey. Throws an exception if none is found.

    This function is supposed to be possible to extend if any other YubiKeys
    appear in the future.

    Attributes :
        skip  -- number of YubiKeys to skip
        debug -- True or False"""
    try:
        hid_device = YubiKeyHIDDevice(debug, skip)
        yk_version = hid_device.status().ykver()
        if (2, 1, 4) <= yk_version <= (2, 1, 9):
            return YubiKeyNEO_USBHID(debug, skip, hid_device)
        if yk_version < (3, 0, 0):
            return YubiKeyUSBHID(debug, skip, hid_device)
        if yk_version < (4, 0, 0):
            return YubiKeyNEO_USBHID(debug, skip, hid_device)
        return YubiKey4_USBHID(debug, skip, hid_device)
    except YubiKeyUSBHIDError as inst:
        if 'No USB YubiKey found' in str(inst):
            raise YubiKeyError('No YubiKey found')
        else:
            raise

def norm_package_version(version):
    """Normalize a version by removing extra spaces and parentheses."""
    if version:
        version = ','.join((v.strip() for v in version.split(','))).strip()
        if version.startswith('(') and version.endswith(')'):
            version = version[1:-1]
        version = ''.join((v for v in version if v.strip()))
    else:
        version = ''
    return version

def split_spec(spec, sep):
    """Split a spec by separator and return stripped start and end parts."""
    parts = spec.rsplit(sep, 1)
    spec_start = parts[0].strip()
    spec_end = ''
    if len(parts) == 2:
        spec_end = parts[-1].strip()
    return (spec_start, spec_end)

def get_header_description(filedata):
    """Get description from metadata file and remove any empty lines at end."""
    python_version = sys.version_info.major
    if python_version == 3:
        filedata = Parser().parsestr(filedata)
    else:
        filedata = Parser().parsestr(filedata.encode('UTF-8', 'replace'))
    payload = filedata.get_payload()
    lines = payload.split('\n')
    while True:
        if lines and lines[-1] == '':
            lines.pop()
        else:
            break
    return '\n'.join(lines)

def parse(handle):
    """>>> parse("user/notebook")
    ('user', 'notebook')
    >>> parse("notebook")
    (None, 'notebook')

    :param handle: String
    :return: username, notebooks"""
    components = handle.split('/', 1)
    if len(components) == 1:
        return (None, components[0])
    elif len(components) == 2:
        return (components[0], components[1])
    else:
        raise BinstarError("{} can't be parsed".format(handle))

def try_replace_token(authenticate, **kwargs):
    """Authenticates using the given *authenticate*, retrying if the token needs
    to be replaced."""
    try:
        return authenticate(**kwargs)
    except errors.BinstarError as err:
        if kwargs.get('fail_if_already_exists') and len(err.args) > 1 and (err.args[1] == 400):
            logger.warning('It appears you are already logged in from host %s' % socket.gethostname())
            logger.warning('Logging in again will remove the previous token. (This could cause troubles with virtual machines with the same hostname)')
            logger.warning('Otherwise you can login again and specify a different hostname with "--hostname"')
            if bool_input('Would you like to continue'):
                kwargs['fail_if_already_exists'] = False
                return authenticate(**kwargs)
        raise

def transform_conda_deps(deps):
    """Format dependencies into a common binstar format"""
    depends = []
    for dep in deps:
        dep = dep.strip()
        name_spec = dep.split(' ', 1)
        if len(name_spec) == 1:
            name, = name_spec
            depends.append({'name': name, 'specs': []})
        elif len(name_spec) == 2:
            name, spec = name_spec
            if spec.endswith('*'):
                spec = spec[:-1]
            match = specs_re.match(spec)
            if match:
                op, spec = match.groups()
            else:
                op = '=='
            depends.append({'name': name, 'specs': [[op, spec]]})
        elif len(name_spec) == 3:
            name, spec, build_str = name_spec
            if spec.endswith('*'):
                spec = spec[:-1]
            match = specs_re.match(spec)
            if match:
                op, spec = match.groups()
            else:
                op = '=='
            depends.append({'name': name, 'specs': [['==', '%s+%s' % (spec, build_str)]]})
    return {'depends': depends}

def get_subdir(index):
    """Return the sub-directory given the index dictionary.  The return
    value is obtained in the following order:

    1. when the 'subdir' key exists, it's value is returned
    2. if the 'arch' is None, or does not exist, 'noarch' is returned
    3. otherwise, the return value is constructed from the 'platform' key
       and the 'arch' key (where 'x86' is replaced by '32',
       and 'x86_64' by '64')"""
    try:
        return index['subdir']
    except KeyError:
        arch = index.get('arch')
        if arch is None:
            return 'noarch'
        intel_map = {'x86': '32', 'x86_64': '64'}
        return '%s-%s' % (index.get('platform'), intel_map.get(arch, arch))

def file_or_token(value):
    """If value is a file path and the file exists its contents are stripped and returned,
    otherwise value is returned."""
    if isfile(value):
        with open(value) as fd:
            return fd.read().strip()
    if any((char in value for char in '/\\.')):
        raise ValueError()
    return value

def get_server_api(token=None, site=None, cls=None, config=None, **kwargs):
    """Get the anaconda server api class"""
    if not cls:
        from binstar_client import Binstar
        cls = Binstar
    config = config if config is not None else get_config(site=site)
    url = config.get('url', DEFAULT_URL)
