def group_spec(spec):
    """<organization>/<group_name>/<member>"""
    org = spec
    group = member = None
    if '/' in org:
        org, group = org.split('/', 1)
    if group and '/' in group:
        group, member = group.split('/', 1)
    if member and '/' in member:
        raise UserError('Invalid group specification "%s" (unexpected "/" in %s)' % member)
    return GroupSpec(org, group, member, spec)

def split_into_segments(data):
    """Slices JPEG meta data into a list from JPEG binary data.
    """
    if data[0:2] != b'\xff\xd8':
        raise InvalidImageDataError("Given data isn't JPEG.")
    head = 2
    segments = [b'\xff\xd8']
    while 1:
        if data[head:head + 2] == b'\xff\xda':
            segments.append(data[head:])
            break
        else:
            length = struct.unpack('>H', data[head + 2:head + 4])[0]
            endPoint = head + length + 2
            seg = data[head:endPoint]
            segments.append(seg)
            head = endPoint
        if head >= len(data):
            raise InvalidImageDataError('Wrong JPEG data.')
    return segments

def merge_segments(segments, exif=b''):
    """Merges Exif with APP0 and APP1 manipulations.
    """
    if segments[1][0:2] == b'\xff\xe0' and segments[2][0:2] == b'\xff\xe1' and (segments[2][4:10] == b'Exif\x00\x00'):
        if exif:
            segments[2] = exif
            segments.pop(1)
        elif exif is None:
            segments.pop(2)
        else:
            segments.pop(1)
    elif segments[1][0:2] == b'\xff\xe0':
        if exif:
            segments[1] = exif
    elif segments[1][0:2] == b'\xff\xe1' and segments[1][4:10] == b'Exif\x00\x00':
        if exif:
            segments[1] = exif
        elif exif is None:
            segments.pop(1)
    elif exif:
        segments.insert(1, exif)
    return b''.join(segments)

def read_config():
    """Reads and preprocesses the pydoc-markdown configuration file."""
    with open(PYDOCMD_CONFIG) as fp:
        config = yaml.load(fp)
    return default_config(config)

def copy_source_files(config, pages_required=True):
    """Copies all files from the `docs_dir` to the `gens_dir` defined in the
    *config*. It also takes the MkDocs `pages` configuration into account
    and converts the special `<< INFILE` syntax by copying them to the
    `gens_dir` as well."""
    for path in config['additional_search_paths']:
        path = os.path.abspath(path)
        sys.path.append(path)
    log('Started copying source files...')
    for root, dirs, files in os.walk(config['docs_dir']):
        rel_root = os.path.relpath(root, config['docs_dir'])
        for fname in files:
            dest_fname = os.path.join(config['gens_dir'], rel_root, fname)
            makedirs(os.path.dirname(dest_fname))
            shutil.copyfile(os.path.join(root, fname), dest_fname)
    if 'pages' not in config:
        if pages_required:
            raise RuntimeError('pydocmd.yml does not have defined pages!')
        return
    for page in config['pages']:
        process_pages(page, config['gens_dir'])

def import_object_with_scope(name):
    """Imports a Python object by an absolute identifier.

    # Arguments
    name (str): The name of the Python object to import.

    # Returns
    (any, Module): The object and the module that contains it. Note that
      for plain modules loaded with this function, both elements of the
      tuple may be the same object."""
    parts = name.split('.')
    current_name = parts[0]
    obj = import_module(current_name)
    scope = None
    for part in parts[1:]:
        current_name += '.' + part
        try:
            if hasattr(obj, '__dict__'):
                sub_obj = obj.__dict__[part]
            else:
                sub_obj = getattr(obj, part)
            scope, obj = (obj, sub_obj)
        except (AttributeError, KeyError):
            try:
                obj = scope = import_module(current_name)
            except ImportError as exc:
                if 'named {}'.format(part) in str(exc):
                    raise ImportError(current_name)
                raise
    return (obj, scope)

def force_lazy_import(name):
    """Import any modules off of "name" by iterating a new list rather than a generator so that this
    library works with lazy imports."""
    obj = import_object(name)
    module_items = list(getattr(obj, '__dict__', {}).items())
    for key, value in module_items:
        if getattr(value, '__module__', None):
            import_object(name + '.' + key)

def slugify(value):
    """Converts to lowercase, removes non-word characters (alphanumerics and
    underscores) and converts spaces to hyphens. Also strips leading and
    trailing whitespace."""
    value = re.sub('[^\\w\\s-]', '', value).strip()
    return re.sub('[-\\s]+', '-', value)

def get_assign_value(node):
    """Get the name and value of the assignment of the given node.

    Assignments to multiple names are ignored, as per PEP 257.

    :param node: The node to get the assignment value from.
    :type node: astroid.nodes.Assign or astroid.nodes.AnnAssign

    :returns: The name that is assigned to,
        and the value assigned to the name (if it can be converted).
    :rtype: tuple(str, object or None) or None"""
    try:
        targets = node.targets
    except AttributeError:
        targets = [node.target]
    if len(targets) == 1:
        target = targets[0]
        if isinstance(target, astroid.nodes.AssignName):
            name = target.name
        elif isinstance(target, astroid.nodes.AssignAttr):
            name = target.attrname
        else:
            return None
        return (name, _get_const_values(node.value))
    return None

def get_assign_annotation(node):
    """Get the type annotation of the assignment of the given node.

    :param node: The node to get the annotation for.
    :type node: astroid.nodes.Assign or astroid.nodes.AnnAssign

    :returns: The type annotation as a string, or None if one does not exist.
    :type: str or None"""
    annotation = None
    annotation_node = None
    try:
        annotation_node = node.annotation
    except AttributeError:
        annotation_node = getattr(node, 'type_annotation', None)
    if annotation_node:
        if isinstance(annotation_node, astroid.nodes.Const):
            annotation = node.value
        else:
            annotation = annotation_node.as_string()
    return annotation

def is_decorated_with_property(node):
    """Check if the function is decorated as a property.

    :param node: The node to check.
    :type node: astroid.nodes.FunctionDef

    :returns: True if the function is a property, False otherwise.
    :rtype: bool"""
    if not node.decorators:
        return False
    for decorator in node.decorators.nodes:
        if not isinstance(decorator, astroid.Name):
            continue
        try:
            if _is_property_decorator(decorator):
                return True
        except astroid.InferenceError:
            pass
    return False

def is_decorated_with_property_setter(node):
    """Check if the function is decorated as a property setter.

    :param node: The node to check.
    :type node: astroid.nodes.FunctionDef

    :returns: True if the function is a property setter, False otherwise.
    :rtype: bool"""
    if not node.decorators:
        return False
    for decorator in node.decorators.nodes:
        if isinstance(decorator, astroid.nodes.Attribute) and decorator.attrname == 'setter':
            return True
    return False

def is_exception(node):
    """Check if a class is an exception.

    :param node: The node to check.
    :type node: astroid.nodes.ClassDef

    :returns: True if the class is an exception, False otherwise.
    :rtype: bool"""
    if node.name in ('Exception', 'BaseException') and node.root().name == _EXCEPTIONS_MODULE:
        return True
    if not hasattr(node, 'ancestors'):
        return False
    return any((is_exception(parent) for parent in node.ancestors(recurs=True)))

def get_module_all(node):
    """Get the contents of the ``__all__`` variable from a module.

    :param node: The module to get ``__all__`` from.
    :type node: astroid.nodes.Module

    :returns: The contents of ``__all__`` if defined. Otherwise None.
    :rtype: list(str) or None"""
    all_ = None
    if '__all__' in node.locals:
        assigned = next(node.igetattr('__all__'))
        if assigned is not astroid.Uninferable:
            all_ = []
            for elt in getattr(assigned, 'elts', ()):
                try:
                    elt_name = next(elt.infer())
                except astroid.InferenceError:
                    continue
                if elt_name is astroid.Uninferable:
                    continue
                if isinstance(elt_name, astroid.Const) and isinstance(elt_name.value, _STRING_TYPES):
                    all_.append(elt_name.value)
    return all_

def doctree_read(app, doctree):
    """Inject AutoAPI into the TOC Tree dynamically."""
    if app.env.docname == 'index':
        all_docs = set()
        insert = True
        nodes = doctree.traverse(toctree)
        toc_entry = '%s/index' % app.config.autoapi_root
        add_entry = nodes and app.config.autoapi_generate_api_docs and app.config.autoapi_add_toctree_entry
        if not add_entry:
            return
        for node in nodes:
            for entry in node['entries']:
                all_docs.add(entry[1])
        for doc in all_docs:
            if doc.find(app.config.autoapi_root) != -1:
                insert = False
        if insert and app.config.autoapi_add_toctree_entry:
            nodes[-1]['entries'].append((None, u'%s/index' % app.config.autoapi_root))
            nodes[-1]['includefiles'].append(u'%s/index' % app.config.autoapi_root)
            message_prefix = bold('[AutoAPI] ')
            message = darkgreen('Adding AutoAPI TOCTree [{0}] to index.rst'.format(toc_entry))
            LOGGER.info(message_prefix + message)

def _traverse_parent(node, objtypes):
    """Traverse up the node's parents until you hit the ``objtypes`` referenced.

    Can either be a single type,
    or a tuple of types."""
    curr_node = node.parent
    while curr_node is not None:
        if isinstance(curr_node, objtypes):
            return curr_node
        curr_node = curr_node.parent
    return None

def _find_toc_node(toc, ref_id, objtype):
    """Find the actual TOC node for a ref_id.

    Depends on the object type:
    * Section - First section (refuri) or 2nd+ level section (anchorname)
    * Desc - Just use the anchor name"""
    for check_node in toc.traverse(nodes.reference):
        if objtype == nodes.section and (check_node.attributes['refuri'] == ref_id or check_node.attributes['anchorname'] == '#' + ref_id):
            return check_node
        if objtype == addnodes.desc and check_node.attributes['anchorname'] == '#' + ref_id:
            return check_node
    return None

def _get_toc_reference(app, node, toc, docname):
    """Logic that understands maps a specific node to it's part of the toctree.

    It takes a specific incoming ``node``,
    and returns the actual TOC Tree node that is said reference."""
    if isinstance(node, nodes.section) and isinstance(node.parent, nodes.document):
        ref_id = docname
        toc_reference = _find_toc_node(toc, ref_id, nodes.section)
    elif isinstance(node, nodes.section):
        ref_id = node.attributes['ids'][0]
        toc_reference = _find_toc_node(toc, ref_id, nodes.section)
    else:
        try:
            ref_id = node.children[0].attributes['ids'][0]
            toc_reference = _find_toc_node(toc, ref_id, addnodes.desc)
        except (KeyError, IndexError) as e:
            LOGGER.warning('Invalid desc node: %s' % e)
            toc_reference = None
    return toc_reference

def humanize_duration(duration):
    """Returns a humanized string representing time difference

    For example: 2 days 1 hour 25 minutes 10 seconds"""
    days = duration.days
    hours = int(duration.seconds / 3600)
    minutes = int(duration.seconds % 3600 / 60)
    seconds = int(duration.seconds % 3600 % 60)
    parts = []
    if days > 0:
        parts.append(u'%s %s' % (days, pluralize(days, _('day,days'))))
    if hours > 0:
        parts.append(u'%s %s' % (hours, pluralize(hours, _('hour,hours'))))
    if minutes > 0:
        parts.append(u'%s %s' % (minutes, pluralize(minutes, _('minute,minutes'))))
    if seconds > 0:
        parts.append(u'%s %s' % (seconds, pluralize(seconds, _('second,seconds'))))
    return ', '.join(parts) if len(parts) != 0 else _('< 1 second')

