def parse_content_type(ct: str) -> Tuple[str, str, Mapping[str, str]]:
    """Decompose the value of HTTP "Content-Type" header into
    the main/sub MIME types and other extra options as a dictionary.
    All parsed values are lower-cased automatically."""
    pieces = ct.split(';')
    try:
        main_type, sub_type = pieces[0].split('/')
    except ValueError:
        msg = 'Invalid mime-type component: "{0}"'.format(pieces[0])
        raise ValueError(msg)
    if len(pieces) > 1:
        options = {}
        for opt in pieces[1:]:
            opt = opt.strip()
            if not opt:
                continue
            try:
                k, v = opt.split('=', 1)
            except ValueError:
                msg = 'Invalid option component: "{0}"'.format(opt)
                raise ValueError(msg)
            else:
                options[k.lower()] = v.lower()
    else:
        options = {}
    return (main_type.lower(), sub_type.lower(), options)

def clean_map(obj: Mapping[Any, Any]) -> Mapping[Any, Any]:
    """Return a new copied dictionary without the keys with ``None`` values from
    the given Mapping object."""
    return {k: v for k, v in obj.items() if v is not None}

def format_env(key, value: Union[None, bytes, str]) -> str:
    """Formats envs from {key:value} to ['key=value']"""
    if value is None:
        return key
    if isinstance(value, bytes):
        value = value.decode('utf-8')
    return '{key}={value}'.format(key=key, value=value)

def clean_networks(networks: Iterable[str]=None) -> Optional[Iterable[str]]:
    """Cleans the values inside `networks`
    Returns a new list"""
    if not networks:
        return networks
    if not isinstance(networks, list):
        raise TypeError('networks parameter must be a list.')
    result = []
    for n in networks:
        if isinstance(n, str):
            n = {'Target': n}
        result.append(n)
    return result

def clean_filters(filters: Mapping=None) -> str:
    """Checks the values inside `filters`
    https://docs.docker.com/engine/api/v1.29/#operation/ServiceList
    Returns a new dictionary in the format `map[string][]string` jsonized"""
    if filters and isinstance(filters, dict):
        for k, v in filters.items():
            if not isinstance(v, list):
                v = [v]
            filters[k] = v
    return json.dumps(filters)

def compose_auth_header(auth: Union[MutableMapping, str, bytes], registry_addr: str=None) -> str:
    """Validate and compose base64-encoded authentication header
    with an optional support for parsing legacy-style "user:password"
    strings.

    Args:
        auth: Authentication information
        registry_addr: An address of the registry server

    Returns:
        A base64-encoded X-Registry-Auth header value"""
    if isinstance(auth, Mapping):
        if 'identitytoken' in auth:
            pass
        elif 'auth' in auth:
            return compose_auth_header(auth['auth'], registry_addr)
        elif registry_addr:
            auth['serveraddress'] = registry_addr
        auth_json = json.dumps(auth).encode('utf-8')
    elif isinstance(auth, (str, bytes)):
        if isinstance(auth, bytes):
            auth = auth.decode('utf-8')
        s = base64.b64decode(auth)
        username, passwd = s.split(b':', 1)
        config = {'username': username.decode('utf-8'), 'password': passwd.decode('utf-8'), 'email': None, 'serveraddress': registry_addr}
        auth_json = json.dumps(config).encode('utf-8')
    else:
        raise TypeError('auth must be base64 encoded string/bytes or a dictionary')
    auth = base64.b64encode(auth_json).decode('ascii')
    return auth

def unitvec(vec):
    """Scale a vector to unit length. The only exception is the zero vector, which
    is returned back unchanged."""
    if scipy.sparse.issparse(vec):
        vec = vec.tocsr()
        veclen = numpy.sqrt(numpy.sum(vec.data ** 2))
        if veclen > 0.0:
            return vec / veclen
        else:
            return vec
    if isinstance(vec, numpy.ndarray):
        vec = numpy.asarray(vec, dtype=float)
        veclen = numpy.linalg.norm(vec)
        if veclen > 0.0:
            return vec / veclen
        else:
            return vec

def perform_pca(A):
    """Computes eigenvalues and eigenvectors of covariance matrix of A.
    The rows of a correspond to observations, the columns to variables."""
    M = (A - numpy.mean(A.T, axis=1)).T
    return numpy.linalg.eig(numpy.cov(M))

def run_rc_file(editor, rc_file):
    """Run rc file."""
    assert isinstance(editor, Editor)
    assert isinstance(rc_file, six.string_types)
    rc_file = os.path.expanduser(rc_file)
    if not os.path.exists(rc_file):
        print('Impossible to read %r' % rc_file)
        _press_enter_to_continue()
        return
    try:
        namespace = {}
        with open(rc_file, 'r') as f:
            code = compile(f.read(), rc_file, 'exec')
            six.exec_(code, namespace, namespace)
        if 'configure' in namespace:
            namespace['configure'](editor)
    except Exception as e:
        traceback.print_exc()
        _press_enter_to_continue()

def _try_char(character, backup, encoding=sys.stdout.encoding):
    """Return `character` if it can be encoded using sys.stdout, else return the
    backup character."""
    if character.encode(encoding, 'replace') == b'?':
        return backup
    else:
        return character

def _bufferlist_overlay_visible(editor):
    """True when the buffer list overlay should be displayed.
    (This is when someone starts typing ':b' or ':buffer' in the command line.)"""
    @Condition
    def overlay_is_visible():
        app = get_app()
        text = editor.command_buffer.text.lstrip()
        return app.layout.has_focus(editor.command_buffer) and any((text.startswith(p) for p in ['b ', 'b! ', 'buffer', 'buffer!']))
    return overlay_is_visible

def handle_command(editor, input_string):
    """Handle commands entered on the Vi command line."""
    m = COMMAND_GRAMMAR.match(input_string)
    if m is None:
        return
    variables = m.variables()
    command = variables.get('command')
    go_to_line = variables.get('go_to_line')
    shell_command = variables.get('shell_command')
    if go_to_line is not None:
        _go_to_line(editor, go_to_line)
    elif shell_command is not None:
        editor.application.run_system_command(shell_command)
    elif has_command_handler(command):
        call_command_handler(command, editor, variables)
    else:
        editor.show_message('Not an editor command: %s' % input_string)
        return
    editor.sync_with_prompt_toolkit()

def report(location, document):
    """Run reporter on document and return list of ReporterError instances.
    (Depending on the location it will or won't run anything.)

    Returns a list of `ReporterError`."""
    assert isinstance(location, six.string_types)
    if location.endswith('.py'):
        return report_pyflakes(document)
    else:
        return []

def report_pyflakes(document):
    """Run pyflakes on document and return list of ReporterError instances."""
    reporter = _FlakesReporter()
    pyflakes.api.check(document.text, '', reporter=reporter)
    def format_flake_message(message):
        return [('class:flakemessage.prefix', 'pyflakes:'), ('', ' '), ('class:flakemessage', message.message % message.message_args)]
    def message_to_reporter_error(message):
        """Turn pyflakes message into ReporterError."""
        start_index = document.translate_row_col_to_index(message.lineno - 1, message.col)
        end_index = start_index
        while end_index < len(document.text) and document.text[end_index] in WORD_CHARACTERS:
            end_index += 1
        return ReporterError(lineno=message.lineno - 1, start_column=message.col, end_column=message.col + end_index - start_index, formatted_text=format_flake_message(message))
    return [message_to_reporter_error(m) for m in reporter.messages]

def get_editor_style_by_name(name):
