def _check_file(parameters):
    """Return list of errors."""
    filename, args = parameters
    if filename == '-':
        contents = sys.stdin.read()
    else:
        with contextlib.closing(docutils.io.FileInput(source_path=filename)) as input_file:
            contents = input_file.read()
    args = load_configuration_from_file(os.path.dirname(os.path.realpath(filename)), args)
    ignore_directives_and_roles(args.ignore_directives, args.ignore_roles)
    for substitution in args.ignore_substitutions:
        contents = contents.replace('|{}|'.format(substitution), 'None')
    ignore = {'languages': args.ignore_language, 'messages': args.ignore_messages}
    all_errors = []
    for error in check(contents, filename=filename, report_level=args.report, ignore=ignore, debug=args.debug):
        all_errors.append(error)
    return (filename, all_errors)

def check_json(code):
    """Yield errors."""
    try:
        json.loads(code)
    except ValueError as exception:
        message = '{}'.format(exception)
        line_number = 0
        found = re.search(': line\\s+([0-9]+)[^:]*$', message)
        if found:
            line_number = int(found.group(1))
        yield (int(line_number), message)

def check_xml(code):
    """Yield errors."""
    try:
        xml.etree.ElementTree.fromstring(code)
    except xml.etree.ElementTree.ParseError as exception:
        message = '{}'.format(exception)
        line_number = 0
        found = re.search(': line\\s+([0-9]+)[^:]*$', message)
        if found:
            line_number = int(found.group(1))
        yield (int(line_number), message)

def check_rst(code, ignore):
    """Yield errors in nested RST code."""
    filename = '<string>'
    for result in check(code, filename=filename, ignore=ignore):
        yield result

def _get_directives_and_roles_from_sphinx():
    """Return a tuple of Sphinx directive and roles."""
    if SPHINX_INSTALLED:
        sphinx_directives = list(sphinx.domains.std.StandardDomain.directives)
        sphinx_roles = list(sphinx.domains.std.StandardDomain.roles)
        for domain in [sphinx.domains.c.CDomain, sphinx.domains.cpp.CPPDomain, sphinx.domains.javascript.JavaScriptDomain, sphinx.domains.python.PythonDomain]:
            sphinx_directives += list(domain.directives) + ['{}:{}'.format(domain.name, item) for item in list(domain.directives)]
            sphinx_roles += list(domain.roles) + ['{}:{}'.format(domain.name, item) for item in list(domain.roles)]
    else:
        sphinx_roles = ['abbr', 'command', 'dfn', 'doc', 'download', 'envvar', 'file', 'guilabel', 'kbd', 'keyword', 'mailheader', 'makevar', 'manpage', 'menuselection', 'mimetype', 'newsgroup', 'option', 'program', 'py:func', 'ref', 'regexp', 'samp', 'term', 'token']
        sphinx_directives = ['autosummary', 'currentmodule', 'centered', 'c:function', 'c:type', 'include', 'deprecated', 'envvar', 'glossary', 'index', 'no-code-block', 'literalinclude', 'hlist', 'option', 'productionlist', 'py:function', 'seealso', 'toctree', 'todo', 'versionadded', 'versionchanged']
    return (sphinx_directives, sphinx_roles)

def find_config(directory_or_file, debug=False):
    """Return configuration filename.

    If `directory_or_file` is a file, return the real-path of that file. If it
    is a directory, find the configuration (any file name in CONFIG_FILES) in
    that directory or its ancestors."""
    directory_or_file = os.path.realpath(directory_or_file)
    if os.path.isfile(directory_or_file):
        if debug:
            print('using config file {}'.format(directory_or_file), file=sys.stderr)
        return directory_or_file
    directory = directory_or_file
    while directory:
        for filename in CONFIG_FILES:
            candidate = os.path.join(directory, filename)
            if os.path.exists(candidate):
                if debug:
                    print('using config file {}'.format(candidate), file=sys.stderr)
                return candidate
        parent_directory = os.path.dirname(directory)
        if parent_directory == directory:
            break
        else:
            directory = parent_directory

def ignore_directives_and_roles(directives, roles):
    """Ignore directives/roles in docutils."""
    for directive in directives:
        docutils.parsers.rst.directives.register_directive(directive, IgnoredDirective)
    for role in roles:
        docutils.parsers.rst.roles.register_local_role(role, _ignore_role)

def bash_checker(code, working_directory):
    """Return checker."""
    run = run_in_subprocess(code, '.bash', ['bash', '-n'], working_directory=working_directory)
    def run_check():
        """Yield errors."""
        result = run()
        if result:
            output, filename = result
            prefix = filename + ': line '
            for line in output.splitlines():
                if not line.startswith(prefix):
                    continue
                message = line[len(prefix):]
                split_message = message.split(':', 1)
                yield (int(split_message[0]) - 1, split_message[1].strip())
    return run_check

def cpp_checker(code, working_directory):
    """Return checker."""
    return gcc_checker(code, '.cpp', [os.getenv('CXX', 'g++'), '-std=c++0x'] + INCLUDE_FLAGS, working_directory=working_directory)

def gcc_checker(code, filename_suffix, arguments, working_directory):
    """Return checker."""
    run = run_in_subprocess(code, filename_suffix, arguments + ['-pedantic', '-fsyntax-only'], working_directory=working_directory)
    def run_check():
        """Yield errors."""
        result = run()
        if result:
            output, filename = result
            for line in output.splitlines():
                try:
                    yield parse_gcc_style_error_message(line, filename=filename)
                except ValueError:
                    continue
    return run_check

def run_in_subprocess(code, filename_suffix, arguments, working_directory):
    """Return None on success."""
    temporary_file = tempfile.NamedTemporaryFile(mode='wb', suffix=filename_suffix)
    temporary_file.write(code.encode('utf-8'))
    temporary_file.flush()
    process = subprocess.Popen(arguments + [temporary_file.name], stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=working_directory)
    def run():
        """Yield errors."""
        raw_result = process.communicate()
        if process.returncode != 0:
            return (raw_result[1].decode(get_encoding()), temporary_file.name)
    return run

def beginning_of_code_block(node, line_number, full_contents, is_code_node):
    """Return line number of beginning of code block."""
    if SPHINX_INSTALLED and (not is_code_node):
        delta = len(node.non_default_attributes())
        current_line_contents = full_contents.splitlines()[line_number:]
        blank_lines = next((i for i, x in enumerate(current_line_contents) if x), 0)
        return line_number + delta - 1 + blank_lines - 1 + SPHINX_CODE_BLOCK_DELTA
    else:
        lines = full_contents.splitlines()
        code_block_length = len(node.rawsource.splitlines())
        try:
            if lines[line_number - 1].strip():
                return line_number - code_block_length + 1
        except IndexError:
            pass
        for line_number in range(line_number, 1, -1):
            if lines[line_number - 2].strip():
                break
        return line_number - code_block_length

def output_message(text, file=sys.stderr):
    """Output message to terminal."""
    if file.encoding is None:
        text = text.encode('utf-8')
    print(text, file=file)

def enable_sphinx_if_possible():
    """Register Sphinx directives and roles."""
    if SPHINX_INSTALLED:
        srcdir = tempfile.mkdtemp()
        outdir = os.path.join(srcdir, '_build')
        try:
            sphinx.application.Sphinx(srcdir=srcdir, confdir=None, outdir=outdir, doctreedir=outdir, buildername='dummy', status=None)
            yield
        finally:
            shutil.rmtree(srcdir)
    else:
        yield

def match_file(filename):
    """Return True if file is okay for modifying/recursing."""
    base_name = os.path.basename(filename)
    if base_name.startswith('.'):
        return False
    if not os.path.isdir(filename) and (not filename.lower().endswith('.rst')):
        return False
    return True

def main():
    """Return 0 on success."""
    args = parse_args()
    if not args.files:
        return 0
    with enable_sphinx_if_possible():
        status = 0
        pool = multiprocessing.Pool(multiprocessing.cpu_count())
        try:
            if len(args.files) > 1:
                results = pool.map(_check_file, [(name, args) for name in args.files])
            else:
                results = [_check_file((args.files[0], args))]
            for filename, errors in results:
                for error in errors:
                    line_number = error[0]
                    message = error[1]
                    if not re.match('\\([A-Z]+/[0-9]+\\)', message):
                        message = '(ERROR/3) ' + message
                    output_message('{}:{}: {}'.format(filename, line_number, message))
                    status = 1
        except (IOError, UnicodeError) as exception:
            output_message(exception)
            status = 1
        return status

def parse_url(url):
    """Parse the argument url and return a redis connection.
    Two patterns of url are supported:
        * redis://host:port[/db][?options]
        * redis+socket:///path/to/redis.sock[?options]
    A ValueError is raised if the URL is not recognized."""
    parsed = urlparse(url)
    kwargs = parse_qsl(parsed.query)
    if parsed.scheme == 'redis':
        details = {'host': parsed.hostname}
        if parsed.port:
            details['port'] = parsed.port
        if parsed.password:
            details['password'] = parsed.password
        db = parsed.path.lstrip('/')
        if db and db.isdigit():
            details['db'] = db
    elif parsed.scheme == 'redis+socket':
        details = {'unix_socket_path': parsed.path}
    else:
        raise ValueError('Unsupported protocol %s' % parsed.scheme)
    details.update(kwargs)
    if 'socket_timeout' in details:
        details['socket_timeout'] = float(details['socket_timeout'])
    if 'db' in details:
        details['db'] = int(details['db'])
    return details

def force_string(kwargs):
    """Force key in dict or list to a string.
    Fixes: https://github.com/cameronmaske/celery-once/issues/11"""
    if isinstance(kwargs, dict):
        return order_dict_to_string(OrderedDict(((force_string(key), force_string(value)) for key, value in items_sorted_by_key(kwargs))))
    elif isinstance(kwargs, list):
        return [force_string(element) for element in kwargs]
    elif six.PY2 and isinstance(kwargs, unicode):
        return kwargs.encode('utf-8')
    return kwargs

def kwargs_to_list(kwargs):
    """Turns {'a': 1, 'b': 2} into ["a-1", "b-2"]"""
    kwargs_list = []
    for k, v in items_sorted_by_key(kwargs):
        kwargs_list.append(str(k) + '-' + str(force_string(v)))
    return kwargs_list

def queue_once_key(name, kwargs, restrict_to=None):
    """Turns a list the name of the task, the kwargs and allowed keys
    into a redis key."""
    keys = ['qo', force_string(name)]
    if restrict_to is not None:
        restrict_kwargs = {key: kwargs[key] for key in restrict_to}
        keys += kwargs_to_list(restrict_kwargs)
    else:
        keys += kwargs_to_list(kwargs)
    key = '_'.join(keys)
    return key

def _parse_header_id(line):
    """Pull the transcript or protein identifier from the header line
    which starts with '>'"""
    if type(line) is not binary_type:
        raise TypeError('Expected header line to be of type %s but got %s' % (binary_type, type(line)))
    if len(line) <= 1:
        raise ValueError('No identifier on FASTA line')
    space_index = line.find(b' ')
    if space_index >= 0:
        identifier = line[1:space_index]
    else:
        identifier = line[1:]
    dot_index = identifier.find(b'.')
    if dot_index >= 0:
        identifier = identifier[:dot_index]
    return identifier.decode('ascii')

def normalize_reference_name(name):
    """Search the dictionary of species-specific references to find a reference
    name that matches aside from capitalization.

    If no matching reference is found, raise an exception."""
    lower_name = name.strip().lower()
    for reference in Species._reference_names_to_species.keys():
        if reference.lower() == lower_name:
            return reference
    raise ValueError("Reference genome '%s' not found" % name)

def genome_for_reference_name(reference_name, allow_older_downloaded_release=True):
    """Given a genome reference name, such as "GRCh38", returns the
    corresponding Ensembl Release object.

    If `allow_older_downloaded_release` is True, and some older releases have
    been downloaded, then return the most recent locally available release.


    Otherwise, return the newest release of Ensembl (even if its data hasn't
    already been downloaded)."""
    reference_name = normalize_reference_name(reference_name)
    species = find_species_by_reference(reference_name)
    min_ensembl_release, max_ensembl_release = species.reference_assemblies[reference_name]
    if allow_older_downloaded_release:
        for release in reversed(range(min_ensembl_release, max_ensembl_release + 1)):
            candidate = EnsemblRelease.cached(release=release, species=species)
            if candidate.required_local_files_exist():
                return candidate
    return EnsemblRelease.cached(release=max_ensembl_release, species=species)

def normalize_species_name(name):
    """If species name was "Homo sapiens" then replace spaces with underscores
    and return "homo_sapiens". Also replace common names like "human" with
    "homo_sapiens"."""
    lower_name = name.lower().strip()
    if lower_name in Species._common_names_to_species:
        return Species._common_names_to_species[lower_name].latin_name
    return lower_name.replace(' ', '_')

def check_species_object(species_name_or_object):
    """Helper for validating user supplied species names or objects."""
    if isinstance(species_name_or_object, Species):
        return species_name_or_object
    elif isinstance(species_name_or_object, str):
        return find_species_by_name(species_name_or_object)
    else:
        raise ValueError('Unexpected type for species: %s : %s' % (species_name_or_object, type(species_name_or_object)))

def _memoize_cache_key(args, kwargs):
    """Turn args tuple and kwargs dictionary into a hashable key.

    Expects that all arguments to a memoized function are either hashable
    or can be uniquely identified from type(arg) and repr(arg)."""
    cache_key_list = []
    for arg in args:
        if type(arg) is list:
            cache_key_list.append(tuple(arg))
        else:
            cache_key_list.append(arg)
    for k, v in sorted(kwargs.items()):
        if type(v) is list:
            cache_key_list.append((k, tuple(v)))
        else:
            cache_key_list.append((k, v))
    return tuple(cache_key_list)

def cache_subdirectory(reference_name=None, annotation_name=None, annotation_version=None):
    """Which cache subdirectory to use for a given annotation database
    over a particular reference. All arguments can be omitted to just get
    the base subdirectory for all pyensembl cached datasets."""
    if reference_name is None:
        reference_name = ''
    if annotation_name is None:
        annotation_name = ''
    if annotation_version is None:
        annotation_version = ''
    reference_dir = join(CACHE_BASE_SUBDIR, reference_name)
    annotation_dir = '%s%s' % (annotation_name, annotation_version)
    return join(reference_dir, annotation_dir)

def check_release_number(release):
    """Check to make sure a release is in the valid range of
    Ensembl releases."""
    try:
        release = int(release)
    except:
        raise ValueError('Invalid Ensembl release: %s' % release)
    if release < MIN_ENSEMBL_RELEASE or release > MAX_ENSEMBL_RELEASE:
        raise ValueError('Invalid Ensembl releases %d, must be between %d and %d' % (release, MIN_ENSEMBL_RELEASE, MAX_ENSEMBL_RELEASE))
    return release

def _species_subdir(ensembl_release, species='homo_sapiens', filetype='gtf', server=ENSEMBL_FTP_SERVER):
    """Assume ensembl_release has already been normalize by calling function
    but species might be either a common name or latin name."""
    return SPECIES_SUBDIR_TEMPLATE % {'release': ensembl_release, 'filetype': filetype, 'species': species}

def normalize_release_properties(ensembl_release, species):
    """Make sure a given release is valid, normalize it to be an integer,
    normalize the species name, and get its associated reference."""
    ensembl_release = check_release_number(ensembl_release)
    if not isinstance(species, Species):
        species = find_species_by_name(species)
    reference_name = species.which_reference(ensembl_release)
    return (ensembl_release, species.latin_name, reference_name)

def make_gtf_filename(ensembl_release, species):
    """Return GTF filename expect on Ensembl FTP server for a specific
    species/release combination"""
    ensembl_release, species, reference_name = normalize_release_properties(ensembl_release, species)
    return GTF_FILENAME_TEMPLATE % {'Species': species.capitalize(), 'reference': reference_name, 'release': ensembl_release}

def find_nearest_locus(start, end, loci):
    """Finds nearest locus (object with method `distance_to_interval`) to the
    interval defined by the given `start` and `end` positions.
    Returns the distance to that locus, along with the locus object itself."""
    best_distance = float('inf')
    best_locus = None
    for locus in loci:
        distance = locus.distance_to_interval(start, end)
        if best_distance > distance:
            best_distance = distance
            best_locus = locus
    return (best_distance, best_locus)

def clone_bs4_elem(el):
    """Clone a bs4 tag before modifying it.

    Code from `http://stackoverflow.com/questions/23057631/clone-element-with
    -beautifulsoup`"""
    if isinstance(el, NavigableString):
        return type(el)(el)
    copy = Tag(None, el.builder, el.name, el.namespace, el.nsprefix)
    copy.attrs = dict(el.attrs)
    for attr in ('can_be_empty_element', 'hidden'):
        setattr(copy, attr, getattr(el, attr))
    for child in el.contents:
        copy.append(clone_bs4_elem(child))
    return copy

def parse_arg(arg):
    """Parses arguments for convenience. Argument can be a
    csv list ('a,b,c'), a string, a list, a tuple.

    Returns a list."""
    if type(arg) == str:
        arg = arg.strip()
        if ',' in arg:
            arg = arg.split(',')
            arg = [x.strip() for x in arg]
        else:
            arg = [arg]
    return arg

def as_format(item, format_str='.2f'):
    """Map a format string over a pandas object."""
    if isinstance(item, pd.Series):
        return item.map(lambda x: format(x, format_str))
    elif isinstance(item, pd.DataFrame):
        return item.applymap(lambda x: format(x, format_str))

def calc_stats(prices):
    """Calculates performance stats of a given object.

    If object is Series, a PerformanceStats object is
    returned. If object is DataFrame, a GroupStats object
    is returned.

    Args:
        * prices (Series, DataFrame): Set of prices"""
    if isinstance(prices, pd.Series):
        return PerformanceStats(prices)
    elif isinstance(prices, pd.DataFrame):
        return GroupStats(*[prices[x] for x in prices.columns])
    else:
        raise NotImplementedError('Unsupported type')

def drawdown_details(drawdown, index_type=pd.DatetimeIndex):
    """Returns a data frame with start, end, days (duration) and
    drawdown for each drawdown in a drawdown series.

    .. note::

        days are actual calendar days, not trading days

    Args:
        * drawdown (pandas.Series): A drawdown Series
            (can be obtained w/ drawdown(prices).
    Returns:
        * pandas.DataFrame -- A data frame with the following
            columns: start, end, days, drawdown."""
    is_zero = drawdown == 0
    start = ~is_zero & is_zero.shift(1)
    start = list(start[start == True].index)
    end = is_zero & (~is_zero).shift(1)
    end = list(end[end == True].index)
    if len(start) is 0:
        return None
    if len(end) is 0:
        end.append(drawdown.index[-1])
    if start[0] > end[0]:
        start.insert(0, drawdown.index[0])
    if start[-1] > end[-1]:
        end.append(drawdown.index[-1])
    result = pd.DataFrame(columns=('Start', 'End', 'Length', 'drawdown'), index=range(0, len(start)))
    for i in range(0, len(start)):
        dd = drawdown[start[i]:end[i]].min()
        if index_type is pd.DatetimeIndex:
            result.iloc[i] = (start[i], end[i], (end[i] - start[i]).days, dd)
        else:
            result.iloc[i] = (start[i], end[i], end[i] - start[i], dd)
    return result

def calc_information_ratio(returns, benchmark_returns):
    """Calculates the `Information ratio <https://www.investopedia.com/terms/i/informationratio.asp>`_ (or `from Wikipedia <http://en.wikipedia.org/wiki/Information_ratio>`_)."""
    diff_rets = returns - benchmark_returns
    diff_std = np.std(diff_rets, ddof=1)
    if np.isnan(diff_std) or diff_std == 0:
        return 0.0
    return np.divide(diff_rets.mean(), diff_std)

def to_monthly(series, method='ffill', how='end'):
    """Convenience method that wraps asfreq_actual
    with 'M' param (method='ffill', how='end')."""
    return series.asfreq_actual('M', method=method, how=how)

def _winsorize_wrapper(x, limits):
    """Wraps scipy winsorize function to drop na's"""
    if isinstance(x, pd.Series):
        if x.count() == 0:
            return x
        notnanx = ~np.isnan(x)
        x[notnanx] = scipy.stats.mstats.winsorize(x[notnanx], limits=limits)
        return x
    else:
        return scipy.stats.mstats.winsorize(x, limits=limits)

def winsorize(x, axis=0, limits=0.01):
    """`Winsorize <https://en.wikipedia.org/wiki/Winsorizing>`_ values based on limits"""
    x = x.copy()
    if isinstance(x, pd.DataFrame):
        return x.apply(_winsorize_wrapper, axis=axis, args=(limits,))
    else:
        return pd.Series(_winsorize_wrapper(x, limits).values, index=x.index)

def rescale(x, min=0.0, max=1.0, axis=0):
    """Rescale values to fit a certain range [min, max]"""
    def innerfn(x, min, max):
        return np.interp(x, [np.min(x), np.max(x)], [min, max])
    if isinstance(x, pd.DataFrame):
        return x.apply(innerfn, axis=axis, args=(min, max))
    else:
        return pd.Series(innerfn(x, min, max), index=x.index)

def web(ticker, field=None, start=None, end=None, mrefresh=False, source='yahoo'):
    """Data provider wrapper around pandas.io.data provider. Provides
    memoization."""
    if source == 'yahoo' and field is None:
        field = 'Adj Close'
    tmp = _download_web(ticker, data_source=source, start=start, end=end)
    if tmp is None:
        raise ValueError('failed to retrieve data for %s:%s' % (ticker, field))
    if field:
        return tmp[field]
    else:
