def csv(ticker, path='data.csv', field='', mrefresh=False, **kwargs):
    """Data provider wrapper around pandas' read_csv. Provides memoization."""
    if 'index_col' not in kwargs:
        kwargs['index_col'] = 0
    if 'parse_dates' not in kwargs:
        kwargs['parse_dates'] = True
    df = pd.read_csv(path, **kwargs)
    tf = ticker
    if field is not '' and field is not None:
        tf = '%s:%s' % (tf, field)
    if tf not in df:
        raise ValueError('Ticker(field) not present in csv file!')
    return df[tf]

def see(table, limit=0, vrepr=None, index_header=None):
    """Format a portion of a table as text in a column-oriented layout for
    inspection in an interactive session. E.g.::

        >>> import petl as etl
        >>> table = [['foo', 'bar'], ['a', 1], ['b', 2]]
        >>> etl.see(table)
        foo: 'a', 'b'
        bar: 1, 2

    Useful for tables with a larger number of fields."""
    if limit == 0:
        limit = config.see_limit
    if vrepr is None:
        vrepr = config.see_vrepr
    if index_header is None:
        index_header = config.see_index_header
    return See(table, limit=limit, vrepr=vrepr, index_header=index_header)

def toxlsx(tbl, filename, sheet=None, encoding=None):
    """Write a table to a new Excel .xlsx file."""
    import openpyxl
    if encoding is None:
        encoding = locale.getpreferredencoding()
    wb = openpyxl.Workbook(write_only=True)
    ws = wb.create_sheet(title=sheet)
    for row in tbl:
        ws.append(row)
    wb.save(filename)

def fromxls(filename, sheet=None, use_view=True):
    """Extract a table from a sheet in an Excel .xls file.

    Sheet is identified by its name or index number.

    N.B., the sheet name is case sensitive."""
    return XLSView(filename, sheet=sheet, use_view=use_view)

def toxls(tbl, filename, sheet, encoding=None, style_compression=0, styles=None):
    """Write a table to a new Excel .xls file."""
    import xlwt
    if encoding is None:
        encoding = locale.getpreferredencoding()
    wb = xlwt.Workbook(encoding=encoding, style_compression=style_compression)
    ws = wb.add_sheet(sheet)
    if styles is None:
        for r, row in enumerate(tbl):
            for c, v in enumerate(row):
                ws.write(r, c, label=v)
    else:
        it = iter(tbl)
        hdr = next(it)
        flds = list(map(str, hdr))
        for c, f in enumerate(flds):
            ws.write(0, c, label=f)
            if f not in styles or styles[f] is None:
                styles[f] = xlwt.Style.default_style
        styles = [styles[f] for f in flds]
        for r, row in enumerate(it):
            for c, (v, style) in enumerate(izip_longest(row, styles, fillvalue=None)):
                ws.write(r + 1, c, label=v, style=style)
    wb.save(filename)

def asindices(hdr, spec):
    """Convert the given field `spec` into a list of field indices."""
    flds = list(map(text_type, hdr))
    indices = list()
    if not isinstance(spec, (list, tuple)):
        spec = (spec,)
    for s in spec:
        if isinstance(s, int) and s < len(hdr):
            indices.append(s)
        elif s in flds:
            indices.append(flds.index(s))
        else:
            raise FieldSelectionError(s)
    return indices

def expr(s):
    """Construct a function operating on a table record.

    The expression string is converted into a lambda function by prepending
    the string with ``'lambda rec: '``, then replacing anything enclosed in
    curly braces (e.g., ``"{foo}"``) with a lookup on the record (e.g.,
    ``"rec['foo']"``), then finally calling :func:`eval`.

    So, e.g., the expression string ``"{foo} * {bar}"`` is converted to the
    function ``lambda rec: rec['foo'] * rec['bar']``"""
    prog = re.compile('\\{([^}]+)\\}')
    def repl(matchobj):
        return "rec['%s']" % matchobj.group(1)
    return eval('lambda rec: ' + prog.sub(repl, s))

def fromtsv(source=None, encoding=None, errors='strict', header=None, **csvargs):
    """Convenience function, as :func:`petl.io.csv.fromcsv` but with different
    default dialect (tab delimited)."""
    csvargs.setdefault('dialect', 'excel-tab')
    return fromcsv(source, encoding=encoding, errors=errors, **csvargs)

def coalesce(*fields, **kwargs):
    """Return a function which accepts a row and returns the first non-missing
    value from the specified fields. Intended for use with
    :func:`petl.transform.basics.addfield`."""
    missing = kwargs.get('missing', None)
    default = kwargs.get('default', None)
    def _coalesce(row):
        for f in fields:
            v = row[f]
            if v is not missing:
                return v
        return default
    return _coalesce

def dateparser(fmt, strict=True):
    """Return a function to parse strings as :class:`datetime.date` objects
    using a given format. E.g.::

        >>> from petl import dateparser
        >>> isodate = dateparser('%Y-%m-%d')
        >>> isodate('2002-12-25')
        datetime.date(2002, 12, 25)
        >>> try:
        ...     isodate('2002-02-30')
        ... except ValueError as e:
        ...     print(e)
        ...
        day is out of range for month

    If ``strict=False`` then if an error occurs when parsing, the original
    value will be returned as-is, and no error will be raised."""
    def parser(value):
        try:
            return datetime.datetime.strptime(value.strip(), fmt).date()
        except Exception as e:
            if strict:
                raise e
            else:
                return value
    return parser

def load(param):
    """If the supplied parameter is a string, assum it's a simple
    pattern."""
    return Pattern(param) if isinstance(param, str) else param if param is not None else Null()

def simple_cache(func):
    """Save results for the :meth:'path.using_module' classmethod.
    When Python 3.2 is available, use functools.lru_cache instead."""
    saved_results = {}
    def wrapper(cls, module):
        if module in saved_results:
            return saved_results[module]
        saved_results[module] = func(cls, module)
        return saved_results[module]
    return wrapper

def only_newer(copy_func):
    """Wrap a copy function (like shutil.copy2) to return
    the dst if it's newer than the source."""
    @functools.wraps(copy_func)
    def wrapper(src, dst, *args, **kwargs):
        is_newer_dst = dst.exists() and dst.getmtime() >= src.getmtime()
        if is_newer_dst:
            return dst
        return copy_func(src, dst, *args, **kwargs)
    return wrapper

def _multi_permission_mask(mode):
    """Support multiple, comma-separated Unix chmod symbolic modes.

    >>> _multi_permission_mask('a=r,u+w')(0) == 0o644
    True"""
    def compose(f, g):
        return lambda *args, **kwargs: g(f(*args, **kwargs))
    return functools.reduce(compose, map(_permission_mask, mode.split(',')))

def markdown(iterable, renderer=HTMLRenderer):
    """Output HTML with default settings.
    Enables inline and block-level HTML tags."""
    with renderer() as renderer:
        return renderer.render(Document(iterable))

def get_ast(token):
    """Recursively unrolls token attributes into dictionaries (token.children
    into lists).

    Returns:
        a dictionary of token's attributes."""
    node = {}
    node['type'] = token.__class__.__name__
    node.update({key: token.__dict__[key] for key in token.__dict__})
    if 'header' in node:
        node['header'] = get_ast(node['header'])
    if 'children' in node:
        node['children'] = [get_ast(child) for child in node['children']]
    return node

def tokenize_block(iterable, token_types):
    """Returns a list of pairs (token_type, read_result).

    Footnotes are parsed here, but span-level parsing has not
    started yet."""
    lines = FileWrapper(iterable)
    parse_buffer = ParseBuffer()
    line = lines.peek()
    while line is not None:
        for token_type in token_types:
            if token_type.start(line):
                result = token_type.read(lines)
                if result is not None:
                    parse_buffer.append((token_type, result))
                    break
        else:
            next(lines)
            parse_buffer.loose = True
        line = lines.peek()
    return parse_buffer

def convert_file(filename, renderer):
    """Parse a Markdown file and dump the output to stdout."""
    try:
        with open(filename, 'r') as fin:
            rendered = mistletoe.markdown(fin, renderer)
            print(rendered, end='')
    except OSError:
        sys.exit('Cannot open file "{}".'.format(filename))

def eeg_microstates_relabel(method, results, microstates_labels, reverse_microstates=None):
    """Relabel the microstates."""
    microstates = list(method['microstates'])
    for index, microstate in enumerate(method['microstates']):
        if microstate in list(reverse_microstates.keys()):
            microstates[index] = reverse_microstates[microstate]
            method['data'][index] = -1 * method['data'][index]
        if microstate in list(microstates_labels.keys()):
            microstates[index] = microstates_labels[microstate]
    method['microstates'] = np.array(microstates)
    return (results, method)

