def namespace_to_dict(obj):
    """If obj is argparse.Namespace or optparse.Values we'll return
      a dict representation of it, else return the original object.

    Redefine this method if using other parsers.

    :param obj: *
    :return:
    :rtype: dict or *"""
    if isinstance(obj, (argparse.Namespace, optparse.Values)):
        return vars(obj)
    return obj

def _package_path(name):
    """Returns the path to the package containing the named module or
    None if the path could not be identified (e.g., if
    ``name == "__main__"``)."""
    loader = pkgutil.get_loader(name)
    if loader is None or name == '__main__':
        return None
    if hasattr(loader, 'get_filename'):
        filepath = loader.get_filename(name)
    else:
        __import__(name)
        filepath = sys.modules[name].__file__
    return os.path.dirname(os.path.abspath(filepath))

def load_yaml(filename):
    """Read a YAML document from a file. If the file cannot be read or
    parsed, a ConfigReadError is raised."""
    try:
        with open(filename, 'rb') as f:
            return yaml.load(f, Loader=Loader)
    except (IOError, yaml.error.YAMLError) as exc:
        raise ConfigReadError(filename, exc)

def restore_yaml_comments(data, default_data):
    """Scan default_data for comments (we include empty lines in our
    definition of comments) and place them before the same keys in data.
    Only works with comments that are on one or more own lines, i.e.
    not next to a yaml mapping."""
    comment_map = dict()
    default_lines = iter(default_data.splitlines())
    for line in default_lines:
        if not line:
            comment = '\n'
        elif line.startswith('#'):
            comment = '{0}\n'.format(line)
        else:
            continue
        while True:
            line = next(default_lines)
            if line and (not line.startswith('#')):
                break
            comment += '{0}\n'.format(line)
        key = line.split(':')[0].strip()
        comment_map[key] = comment
    out_lines = iter(data.splitlines())
    out_data = ''
    for line in out_lines:
        key = line.split(':')[0].strip()
        if key in comment_map:
            out_data += comment_map[key]
        out_data += '{0}\n'.format(line)
    return out_data

def as_template(value):
    """Convert a simple "shorthand" Python value to a `Template`.
    """
    if isinstance(value, Template):
        return value
    elif isinstance(value, abc.Mapping):
        return MappingTemplate(value)
    elif value is int:
        return Integer()
    elif isinstance(value, int):
        return Integer(value)
    elif isinstance(value, type) and issubclass(value, BASESTRING):
        return String()
    elif isinstance(value, BASESTRING):
        return String(value)
    elif isinstance(value, set):
        return Choice(list(value))
    elif SUPPORTS_ENUM and isinstance(value, type) and issubclass(value, enum.Enum):
        return Choice(value)
    elif isinstance(value, list):
        return OneOf(value)
    elif value is float:
        return Number()
    elif value is None:
        return Template()
    elif value is dict:
        return TypeTemplate(abc.Mapping)
    elif value is list:
        return TypeTemplate(abc.Sequence)
    elif isinstance(value, type):
        return TypeTemplate(value)
    else:
        raise ValueError(u'cannot convert to template: {0!r}'.format(value))

def get_from_environment():
    """Return the JavaScript runtime that is specified in EXECJS_RUNTIME environment variable.
    If EXECJS_RUNTIME environment variable is empty or invalid, return None."""
    name = os.environ.get('EXECJS_RUNTIME', '')
    if not name:
        return None
    try:
        return _find_runtime_by_name(name)
    except exceptions.RuntimeUnavailableError:
        return None

def encode_unicode_codepoints(str):
    """>>> encode_unicode_codepoints("a") == 'a'
    True
    >>> ascii = ''.join(chr(i) for i in range(0x80))
    >>> encode_unicode_codepoints(ascii) == ascii
    True
    >>> encode_unicode_codepoints('\\u4e16\\u754c') == '\\\\u4e16\\\\u754c'
    True"""
    codepoint_format = '\\u{0:04x}'.format
    def codepoint(m):
        return codepoint_format(ord(m.group(0)))
    return re.sub('[^\x00-\x7f]', codepoint, str)

def _decode_if_not_text(s):
    """protected"""
    if isinstance(s, six.text_type):
        return s
    return s.decode(sys.getfilesystemencoding())

def _find_executable(prog, pathext=('',)):
    """protected"""
    pathlist = _decode_if_not_text(os.environ.get('PATH', '')).split(os.pathsep)
    for dir in pathlist:
        for ext in pathext:
            filename = os.path.join(dir, prog + ext)
            try:
                st = os.stat(filename)
            except os.error:
                continue
            if stat.S_ISREG(st.st_mode) and stat.S_IMODE(st.st_mode) & 73:
                return filename
    return None

def _which(command):
    """protected"""
    if isinstance(command, str):
        command = [command]
    command = list(command)
    name = command[0]
    args = command[1:]
    if _is_windows():
        pathext = _decode_if_not_text(os.environ.get('PATHEXT', ''))
        path = _find_executable(name, pathext.split(os.pathsep))
    else:
        path = _find_executable(name)
    if not path:
        return None
    return [path] + args

def _json_safe_float(number):
    """JSON serialization for infinity can be problematic.
    See https://docs.python.org/2/library/json.html#basic-usage
    This function returns None if `number` is infinity or negative infinity.

    If the `number` cannot be converted to float, this will raise an exception."""
    if number is None:
        return None
    if isinstance(number, float):
        return None if np.isinf(number) or np.isnan(number) else number
    return float(number)

def temperature_data_to_csv(temperature_data, path_or_buf):
    """Write temperature data to CSV. See also :any:`pandas.DataFrame.to_csv`.

    Parameters
    ----------
    temperature_data : :any:`pandas.Series`
        Temperature data series with :any:`pandas.DatetimeIndex`.
    path_or_buf : :any:`str` or file handle, default None
        File path or object, if None is provided the result is returned as a string."""
    if temperature_data.index.name is None:
        temperature_data.index.name = 'dt'
    if temperature_data.name is None:
        temperature_data.name = 'temperature'
    return temperature_data.to_frame().to_csv(path_or_buf, index=True)

def json_conversion(obj: Any) -> JSON:
    """Encode additional objects to JSON."""
    try:
        import numpy as np
        if isinstance(obj, (np.ndarray, np.generic)):
            return obj.tolist()
    except ImportError:
        pass
    try:
        import pandas as pd
        if isinstance(obj, pd.DatetimeIndex):
            return [x.isoformat() for x in obj.to_pydatetime()]
        if isinstance(obj, pd.Index):
            return obj.tolist()
        if isinstance(obj, pd.Series):
            try:
                return [x.isoformat() for x in obj.dt.to_pydatetime()]
            except AttributeError:
                return obj.tolist()
    except ImportError:
        pass
    if isinstance(obj, (datetime, time, date)):
        return obj.isoformat()
    raise TypeError('Not sure how to serialize {} of type {}'.format(obj, type(obj)))

def pack(x: Any) -> bytes:
    """Encode ``x`` into msgpack with additional encoders."""
    try:
        return msgpack.packb(x, default=encoders)
    except TypeError as exc:
        message = 'Serialization error, check the data passed to a do_ command. Cannot serialize this object:\n' + str(exc)[16:]
        raise SerializationError(message)

def make_event(event: Callable) -> Callable:
    """Create an event from a method signature."""
    @property
    @wraps(event)
    def actualevent(self):
        name = event.__name__[3:]
        try:
            getter = event(self).__name__
        except AttributeError:
            getter = None
        return Event(name, self._uuid, getter)
    return actualevent

def make_command(command: Callable) -> Callable:
    """Create an command from a method signature."""
    @wraps(command)
    def actualcommand(self, *args, **kwds):
        data = command(self, *args, **kwds)
        name = command.__name__[3:]
        signal = '{uuid}{sep}{event}'.format(uuid=self._uuid, sep=SEPARATOR, event=name)
        if flask.has_request_context():
            emit(signal, {'data': pack(data)})
        else:
            sio = flask.current_app.extensions['socketio']
            sio.emit(signal, {'data': pack(data)})
        eventlet.sleep()
    return actualcommand

def make_getter(getter: Callable) -> Callable:
    """Create an command from a method signature."""
    def get(self, timeout=10):
        name = getter.__name__
        signal = '{uuid}{sep}{event}'.format(uuid=self._uuid, sep=SEPARATOR, event=name)
        event = LightQueue(1)
        if flask.has_request_context():
            emit(signal, callback=lambda x: event.put(unpack(x)))
        else:
            sio = flask.current_app.extensions['socketio']
            sio.emit(signal, callback=lambda x: event.put(unpack(x)))
        data = event.get(timeout=timeout)
        return getter(self, data)
    get.__doc__ = getter.__doc__
    return get

def node_version():
