def trimNs(seq, line, newagp):
    """Test if the sequences contain dangling N's on both sides. This component
    needs to be adjusted to the 'actual' sequence range."""
    start, end = (line.component_beg, line.component_end)
    size = end - start + 1
    leftNs, rightNs = (0, 0)
    lid, lo = (line.component_id, line.orientation)
    for s in seq:
        if s in 'nN':
            leftNs += 1
        else:
            break
    for s in seq[::-1]:
        if s in 'nN':
            rightNs += 1
        else:
            break
    if lo == '-':
        trimstart = start + rightNs
        trimend = end - leftNs
    else:
        trimstart = start + leftNs
        trimend = end - rightNs
    trimrange = (trimstart, trimend)
    oldrange = (start, end)
    if trimrange != oldrange:
        logging.debug("{0} trimmed of N's: {1} => {2}".format(lid, oldrange, trimrange))
        if leftNs:
            print('\t'.join((str(x) for x in (line.object, 0, 0, 0, 'N', leftNs, 'fragment', 'yes', ''))), file=newagp)
        if trimend > trimstart:
            print('\t'.join((str(x) for x in (line.object, 0, 0, 0, line.component_type, lid, trimstart, trimend, lo))), file=newagp)
        if rightNs and rightNs != size:
            print('\t'.join((str(x) for x in (line.object, 0, 0, 0, 'N', rightNs, 'fragment', 'yes', ''))), file=newagp)
    else:
        print(line, file=newagp)

def tracedb(args):
    """%prog tracedb <xml|lib|frg>

    Run `tracedb-to-frg.pl` within current folder."""
    p = OptionParser(tracedb.__doc__)
    opts, args = p.parse_args(args)
    if len(args) != 1:
        sys.exit(p.print_help())
    action, = args
    assert action in ('xml', 'lib', 'frg')
    CMD = 'tracedb-to-frg.pl'
    xmls = glob('xml*')
    if action == 'xml':
        for xml in xmls:
            cmd = CMD + ' -xml {0}'.format(xml)
            sh(cmd, outfile='/dev/null', errfile='/dev/null', background=True)
    elif action == 'lib':
        cmd = CMD + ' -lib {0}'.format(' '.join(xmls))
        sh(cmd)
    elif action == 'frg':
        for xml in xmls:
            cmd = CMD + ' -frg {0}'.format(xml)
            sh(cmd, background=True)

def decode_name(name, barcodemap):
    """rename seq/taxon name, typically for a tree display,
    according to a barcode map given in a dictionary

    By definition barcodes should be distinctive."""
    for barcode in barcodemap:
        if barcode in name:
            return barcodemap[barcode]
    return name

def draw_geoscale(ax, minx=0, maxx=175):
    """Draw geological epoch on million year ago (mya) scale."""
    a, b = (0.1, 0.6)
    def cv(x):
        return b - (x - b) / (maxx - minx) * (b - a)
    ax.plot((a, b), (0.5, 0.5), 'k-')
    tick = 0.015
    for mya in xrange(maxx - 25, 0, -25):
        p = cv(mya)
        ax.plot((p, p), (0.5, 0.5 - tick), 'k-')
        ax.text(p, 0.5 - 2.5 * tick, str(mya), ha='center', va='center')
    ax.text((a + b) / 2, 0.5 - 5 * tick, 'Time before present (million years)', ha='center', va='center')
    Geo = (('Neogene', 2.6, 23.0, '#fee400'), ('Paleogene', 23.0, 65.5, '#ff9a65'), ('Cretaceous', 65.5, 145.5, '#80ff40'), ('Jurassic', 145.5, 201.6, '#33fff3'))
    h = 0.05
    for era, start, end, color in Geo:
        start, end = (cv(start), cv(end))
        end = max(a, end)
        p = Rectangle((end, 0.5 + tick / 2), abs(start - end), h, lw=1, ec='w', fc=color)
        ax.text((start + end) / 2, 0.5 + (tick + h) / 2, era, ha='center', va='center', size=9)
        ax.add_patch(p)

