def inspect(object):
    """A better dir() showing attributes and values
    """
    for k in dir(object):
        try:
            details = getattr(object, k)
        except Exception as e:
            details = e
        try:
            details = str(details)
        except Exception as e:
            details = e
        print('{}: {}'.format(k, details), file=sys.stderr)

def get_shred_id(id):
    """>>> get_shred_id("ca-bacs.5638.frag11.22000-23608")
    ("ca-bacs.5638", 11)"""
    try:
        parts = id.split('.')
        aid = '.'.join(parts[:2])
        fid = int(parts[2].replace('frag', ''))
    except:
        aid, fid = (None, None)
    return (aid, fid)

def counter_mean_and_median(counter):
    """Calculate the mean and median value of a counter
    """
    if not counter:
        return (np.nan, np.nan)
    total = sum((v for k, v in counter.items()))
    mid = total / 2
    weighted_sum = 0
    items_seen = 0
    median_found = False
    for k, v in sorted(counter.items()):
        weighted_sum += k * v
        items_seen += v
        if not median_found and items_seen >= mid:
            median = k
            median_found = True
    mean = weighted_sum * 1.0 / total
    return (mean, median)

def counter_format(counter):
    """Pretty print a counter so that it appears as: "2:200,3:100,4:20"
    """
    if not counter:
        return 'na'
    return ','.join(('{}:{}'.format(*z) for z in sorted(counter.items())))

def isPlantOrigin(taxid):
    """Given a taxid, this gets the expanded tree which can then be checked to
    see if the organism is a plant or not

    >>> isPlantOrigin(29760)
    True"""
    assert isinstance(taxid, int)
    t = TaxIDTree(taxid)
    try:
        return 'Viridiplantae' in str(t)
    except AttributeError:
        raise ValueError('{0} is not a valid ID'.format(taxid))

def print_edges(G, bed, families):
    """Instead of going through the graph construction, just print the edges."""
    symbols = {'+': '>', '-': '<'}
    for seqid, bs in bed.sub_beds():
        prev_node, prev_strand = (None, '+')
        for b in bs:
            accn = b.accn
            strand = b.strand
            node = '='.join(families[accn])
            if prev_node:
                print('{}{}--{}{}'.format(prev_node, symbols[prev_strand], symbols[strand], node))
            prev_node, prev_strand = (node, strand)

def _number_finder(s, regex, numconv):
    """Helper to split numbers"""
    s = regex.split(s)
    if len(s) == 1:
        return tuple(s)
    s = remove_empty(s)
    for i in range(len(s)):
        try:
            s[i] = numconv(s[i])
        except ValueError:
            pass
    if not isinstance(s[0], six.string_types):
        return [''] + s
    else:
        return s

def print_locus_quals(locus_tag, locus, quals_ftypes):
    '''Given a locus_tag and dict of feaures, print out 3-column output:
        locus_tag, qualifier, value

    Replace locus_tag with protein_id if processing an "mRNA" or "CDS"'''
    prot_id = None
    for ftype in quals_ftypes:
        for i, quals in enumerate(locus[locus_tag][ftype]):
            for elem in quals:
                elem_id = elem[0]
                if len(locus[locus_tag]['protein_id']) > 0 and ftype in ('mRNA', 'CDS'):
                    elem_id = locus[locus_tag]['protein_id'][i]
                if ftype == 'misc_RNA':
                    ftype = 'ncRNA'
                print('\t'.join((str(x) for x in (elem_id, elem[1], elem[2], ftype))))

def consume(iterator, n):
    """Advance the iterator n-steps ahead. If n is none, consume entirely."""
    if n is None:
        collections.deque(iterator, maxlen=0)
    else:
        next(islice(iterator, n, n), None)

def random_combination(iterable, r):
    """Random selection from itertools.combinations(iterable, r)"""
    pool = tuple(iterable)
    n = len(pool)
    indices = sorted(random.sample(xrange(n), r))
    return tuple((pool[i] for i in indices))

def random_combination_with_replacement(iterable, r):
    """Random selection from itertools.combinations_with_replacement(iterable, r)"""
    pool = tuple(iterable)
    n = len(pool)
    indices = sorted((random.randrange(n) for i in xrange(r)))
    return tuple((pool[i] for i in indices))

def fasta(args):
    """%prog fasta fastqfiles

    Convert fastq to fasta and qual file."""
    p = OptionParser(fasta.__doc__)
    p.add_option('--seqtk', default=False, action='store_true', help='Use seqtk to convert')
    p.set_outdir()
    p.set_outfile(outfile=None)
    opts, args = p.parse_args(args)
    if len(args) < 1:
        sys.exit(not p.print_help())
    fastqfiles = args
    outdir = opts.outdir
    if outdir and outdir != '.':
        mkdir(outdir)
    fastqfile = fastqfiles[0]
    pf = op.basename(fastqfile)
    gzinput = pf.endswith('.gz')
    if gzinput:
        pf = pf.rsplit('.', 1)[0]
    pf, sf = pf.rsplit('.', 1)
    if sf not in ('fq', 'fastq'):
        logging.debug('Assumed FASTA: suffix not `fq` or `fastq`')
        return (fastqfile, None)
    fastafile, qualfile = (pf + '.fasta', pf + '.qual')
    outfile = opts.outfile or fastafile
    outfile = op.join(outdir, outfile)
    if opts.seqtk:
        if need_update(fastqfiles, outfile):
            for i, fastqfile in enumerate(fastqfiles):
                cmd = 'seqtk seq -A {0} -L 30 -l 70'.format(fastqfile)
                sh(cmd, outfile=outfile, append=i)
        else:
            logging.debug('Outfile `{0}` already exists.'.format(outfile))
        return (outfile, None)
    for fastqfile in fastqfiles:
        SeqIO.convert(fastqfile, 'fastq', fastafile, 'fasta')
        SeqIO.convert(fastqfile, 'fastq', qualfile, 'qual')
    return (fastafile, qualfile)

def size(args):
    """%prog size fastqfile

    Find the total base pairs in a list of fastq files"""
    p = OptionParser(size.__doc__)
    opts, args = p.parse_args(args)
    if len(args) < 1:
        sys.exit(not p.print_help())
    total_size = total_numrecords = 0
    for f in args:
        cur_size = cur_numrecords = 0
        for rec in iter_fastq(f):
            if not rec:
                break
            cur_numrecords += 1
            cur_size += len(rec)
        print(' '.join((str(x) for x in (op.basename(f), cur_numrecords, cur_size))))
        total_numrecords += cur_numrecords
        total_size += cur_size
    if len(args) > 1:
        print(' '.join((str(x) for x in ('Total', total_numrecords, total_size))))

def batch_taxonomy(list_of_taxids):
    """Convert list of taxids to Latin names"""
    for taxid in list_of_taxids:
        handle = Entrez.efetch(db='Taxonomy', id=taxid, retmode='xml')
        records = Entrez.read(handle)
        yield records[0]['ScientificName']

def inspect(item, maxchar=80):
    """Inspect the attributes of an item."""
    for i in dir(item):
        try:
            member = str(getattr(item, i))
            if maxchar and len(member) > maxchar:
                member = member[:maxchar] + '...'
        except:
            member = '[ERROR]'
        print('{}: {}'.format(i, member), file=sys.stderr)

def depends(func):
    """Decorator to perform check on infile and outfile. When infile is not present, issue
    warning, and when outfile is present, skip function calls."""
    from jcvi.apps.base import need_update, listify
    infile = 'infile'
    outfile = 'outfile'
    def wrapper(*args, **kwargs):
        assert outfile in kwargs, 'You need to specify `outfile=` on function call'
        if infile in kwargs:
            infilename = listify(kwargs[infile])
            for x in infilename:
                assert op.exists(x), 'The specified infile `{0}` does not exist'.format(x)
        outfilename = kwargs[outfile]
        if need_update(infilename, outfilename):
            return func(*args, **kwargs)
        else:
            msg = 'File `{0}` exists. Computation skipped.'.format(outfilename)
            logging.debug(msg)
        outfilename = listify(outfilename)
        for x in outfilename:
            assert op.exists(x), 'Something went wrong, `{0}` not found'.format(x)
        return outfilename
    return wrapper

def enumerate_reversed(sequence):
    """Perform reverse enumeration, returning an iterator with decrementing
    index/position values

    Source: http://stackoverflow.com/questions/529424/traverse-a-list-in-reverse-order-in-python"""
    for index in reversed(xrange(len(sequence))):
        yield (index, sequence[index])

def percentage(a, b, precision=1, mode=0):
    """>>> percentage(100, 200)
    '100 of 200 (50.0%)'"""
    _a, _b = (a, b)
    pct = '{0:.{1}f}%'.format(a * 100.0 / b, precision)
    a, b = (thousands(a), thousands(b))
    if mode == 0:
        return '{0} of {1} ({2})'.format(a, b, pct)
    elif mode == 1:
        return '{0} ({1})'.format(a, pct)
    elif mode == 2:
        return _a * 100.0 / _b
    return pct

def thousands(x):
    """>>> thousands(12345)
    '12,345'"""
    import locale
    try:
        locale.setlocale(locale.LC_ALL, 'en_US.utf8')
    except Exception:
        locale.setlocale(locale.LC_ALL, 'en_US.UTF-8')
    finally:
        s = '%d' % x
        groups = []
        while s and s[-1].isdigit():
            groups.append(s[-3:])
            s = s[:-3]
        return s + ','.join(reversed(groups))
    return locale.format('%d', x, True)

def gene_name(st, exclude=('ev',), sep='.'):
    """Helper functions in the BLAST filtering to get rid alternative splicings.
    This is ugly, but different annotation groups are inconsistent with respect
    to how the alternative splicings are named. Mostly it can be done by removing
    the suffix, except for ones in the exclude list."""
    if any((st.startswith(x) for x in exclude)):
        sep = None
    st = st.split('|')[0]
    if sep and sep in st:
        name, suffix = st.rsplit(sep, 1)
    else:
        name, suffix = (st, '')
    if len(suffix) != 1:
        name = st
    return name

def fill(text, delimiter='', width=70):
    """Wrap text with width per line"""
    texts = []
    for i in xrange(0, len(text), width):
        t = delimiter.join(text[i:i + width])
        texts.append(t)
    return '\n'.join(texts)

def uniqify(L):
    """Uniqify a list, maintains order (the first occurrence will be kept)."""
    seen = set()
    nL = []
    for a in L:
        if a in seen:
            continue
        nL.append(a)
        seen.add(a)
    return nL

def normalize_lms_axis(ax, xlim=None, ylim=None, xfactor=1e-06, yfactor=1, xlabel=None, ylabel='Map (cM)'):
    """Normalize the axis limits and labels to beautify axis.
    """
    if xlim:
        ax.set_xlim(0, xlim)
    if ylim:
        ax.set_ylim(0, ylim)
    if xlabel:
        xticklabels = [int(round(x * xfactor)) for x in ax.get_xticks()]
        ax.set_xticklabels(xticklabels, family='Helvetica')
        ax.set_xlabel(xlabel)
    else:
        ax.set_xticks([])
    if ylabel:
        yticklabels = [int(round(x * yfactor)) for x in ax.get_yticks()]
        ax.set_yticklabels(yticklabels, family='Helvetica')
        ax.set_ylabel(ylabel)
    else:
        ax.set_yticks([])

def make_sequence(seq, name='S'):
    """Make unique nodes for sequence graph."""
    return ['{}_{}_{}'.format(name, i, x) for i, x in enumerate(seq)]

def sequence_to_graph(G, seq, color='black'):
    """Automatically construct graph given a sequence of characters."""
    for x in seq:
        if x.endswith('_1'):
            G.node(x, color=color, width='0.1', shape='circle', label='')
        else:
            G.node(x, color=color)
    for a, b in pairwise(seq):
        G.edge(a, b, color=color)

def zip_sequences(G, allseqs, color='white'):
    """Fuse certain nodes together, if they contain same data except for the
    sequence name."""
    for s in zip(*allseqs):
        groups = defaultdict(list)
        for x in s:
            part = x.split('_', 1)[1]
            groups[part].append(x)
        for part, g in groups.items():
            with G.subgraph(name='cluster_' + part) as c:
                for x in g:
                    c.node(x)
                c.attr(style='invis')

def check_exists(filename, oappend=False):
    """Avoid overwriting some files accidentally."""
    if op.exists(filename):
        if oappend:
            return oappend
        logging.error('`{0}` found, overwrite (Y/N)?'.format(filename))
        overwrite = raw_input() == 'Y'
    else:
        overwrite = True
    return overwrite

def get_number(s, cast=int):
    """Try to get a number out of a string, and cast it."""
    import string
    d = ''.join((x for x in str(s) if x in string.digits))
    return cast(d)

def _reversedict(d):
    """Internal helper for generating reverse mappings; given a
    dictionary, returns a new dictionary with keys and values swapped."""
    return dict(list(zip(list(d.values()), list(d.keys()))))

def _percent_to_integer(percent):
    """Internal helper for converting a percentage value to an integer
    between 0 and 255 inclusive."""
    num = float(percent.split('%')[0]) / 100.0 * 255
    e = num - math.floor(num)
    return e < 0.5 and int(math.floor(num)) or int(math.ceil(num))

def convert_to_int(value):
    """Attempts to convert a specified value to an integer

    :param value: Content to be converted into an integer
    :type value: string or int"""
    if not value:
        return None
    if isinstance(value, str):
        value = value.strip(' px')
    try:
        return int(value)
    except (TypeError, ValueError):
        return None

def parse_oembed_data(oembed_data, data):
    """Parse OEmbed resposne data to inject into lassie's response dict.

    :param oembed_data: OEmbed response data.
    :type oembed_data: dict
    :param data: Refrence to data variable being updated.
    :type data: dict"""
    data.update({'oembed': oembed_data})
    _type = oembed_data.get('type')
    provider_name = oembed_data.get('provider_name')
    if not _type:
        return data
    if oembed_data.get('title'):
        data.update({'title': oembed_data.get('title')})
    if _type == 'video':
        try:
            item = {'width': convert_to_int(oembed_data.get('width')), 'height': convert_to_int(oembed_data.get('height'))}
            if provider_name in ['YouTube']:
                item['src'] = HYPERLINK_PATTERN.search(oembed_data.get('html')).group(0)
            data['videos'].append(item)
        except Exception:
            pass
        if oembed_data.get('thumbnail_url'):
            item = {'width': convert_to_int(oembed_data.get('thumbnail_width')), 'height': convert_to_int(oembed_data.get('thumbnail_height')), 'src': oembed_data.get('thumbnail_url')}
            data['images'].append(item)
    return data

def decode_mail_header(value, default_charset='us-ascii'):
    """Decode a header value into a unicode string."""
    try:
        headers = decode_header(value)
    except email.errors.HeaderParseError:
        return str_decode(str_encode(value, default_charset, 'replace'), default_charset)
    else:
        for index, (text, charset) in enumerate(headers):
            logger.debug('Mail header no. {index}: {data} encoding {charset}'.format(index=index, data=str_decode(text, charset or 'utf-8', 'replace'), charset=charset))
            try:
                headers[index] = str_decode(text, charset or default_charset, 'replace')
            except LookupError:
                headers[index] = str_decode(text, default_charset, 'replace')
        return ''.join(headers)

def get_mail_addresses(message, header_name):
    """Retrieve all email addresses from one message header."""
    headers = [h for h in message.get_all(header_name, [])]
    addresses = email.utils.getaddresses(headers)
    for index, (address_name, address_email) in enumerate(addresses):
        addresses[index] = {'name': decode_mail_header(address_name), 'email': address_email}
        logger.debug('{} Mail address in message: <{}> {}'.format(header_name.upper(), address_name, address_email))
    return addresses

def parse_flags(headers):
    """Copied from https://github.com/girishramnani/gmail/blob/master/gmail/message.py"""
    if len(headers) == 0:
        return []
    if sys.version_info[0] == 3:
        headers = bytes(headers, 'ascii')
    return list(imaplib.ParseFlags(headers))

def set_preferences(request, dashboard_id):
    """This view serves and validates a preferences form."""
    try:
        preferences = DashboardPreferences.objects.get(user=request.user, dashboard_id=dashboard_id)
    except DashboardPreferences.DoesNotExist:
        preferences = None
    if request.method == 'POST':
        form = DashboardPreferencesForm(user=request.user, dashboard_id=dashboard_id, data=request.POST, instance=preferences)
        if form.is_valid():
            preferences = form.save()
            if request.is_ajax():
                return HttpResponse('true')
            messages.success(request, 'Preferences saved')
        elif request.is_ajax():
            return HttpResponse('false')
    else:
        form = DashboardPreferencesForm(user=request.user, dashboard_id=dashboard_id, instance=preferences)
    return render_to_response('admin_tools/dashboard/preferences_form.html', {'form': form})

