def add_bookmark(request):
    """This view serves and validates a bookmark form.
    If requested via ajax it also returns the drop bookmark form to replace the
    add bookmark form."""
    if request.method == 'POST':
        form = BookmarkForm(user=request.user, data=request.POST)
        if form.is_valid():
            bookmark = form.save()
            if not request.is_ajax():
                messages.success(request, 'Bookmark added')
                if request.POST.get('next'):
                    return HttpResponseRedirect(request.POST.get('next'))
                return HttpResponse('Added')
            return render_to_response('admin_tools/menu/remove_bookmark_form.html', {'bookmark': bookmark, 'url': bookmark.url})
    else:
        form = BookmarkForm(user=request.user)
    return render_to_response('admin_tools/menu/form.html', {'form': form, 'title': 'Add Bookmark'})

def remove_bookmark(request, id):
    """This view deletes a bookmark.
    If requested via ajax it also returns the add bookmark form to replace the
    drop bookmark form."""
    bookmark = get_object_or_404(Bookmark, id=id, user=request.user)
    if request.method == 'POST':
        bookmark.delete()
        if not request.is_ajax():
            messages.success(request, 'Bookmark removed')
            if request.POST.get('next'):
                return HttpResponseRedirect(request.POST.get('next'))
            return HttpResponse('Deleted')
        return render_to_response('admin_tools/menu/add_bookmark_form.html', {'url': request.POST.get('next'), 'title': '**title**'})
    return render_to_response('admin_tools/menu/delete_confirm.html', {'bookmark': bookmark, 'title': 'Delete Bookmark'})

def autodiscover(blacklist=[]):
    """Automagically discover custom dashboards and menus for installed apps.
    Optionally you can pass a ``blacklist`` of apps that you don't want to
    provide their own app index dashboard."""
    import imp
    from django.conf import settings
    try:
        from importlib import import_module
    except ImportError:
        from django.utils.importlib import import_module
    blacklist.append('admin_tools.dashboard')
    blacklist.append('admin_tools.menu')
    blacklist.append('admin_tools.theming')
    for app in settings.INSTALLED_APPS:
        if app in blacklist:
            continue
        try:
            app_path = import_module(app).__path__
        except AttributeError:
            continue
        try:
            imp.find_module('dashboard', app_path)
        except ImportError:
            continue
        import_module('%s.dashboard' % app)

def get_dashboard(context, location):
    """Returns the dashboard that match the given ``location``
    (index or app_index)."""
    if location == 'index':
        return get_index_dashboard(context)
    elif location == 'app_index':
        return get_app_index_dashboard(context)
    raise ValueError('Invalid dashboard location: "%s"' % location)

def get_app_index_dashboard(context):
    """Returns the admin dashboard defined by the user or the default one."""
    app = context['app_list'][0]
    model_list = []
    app_label = None
    app_title = app['name']
    admin_site = get_admin_site(context=context)
    for model, model_admin in admin_site._registry.items():
        if app['app_label'] == model._meta.app_label:
            split = model.__module__.find(model._meta.app_label)
            app_label = model.__module__[0:split] + model._meta.app_label
            for m in app['models']:
                if m['name'] == capfirst(model._meta.verbose_name_plural):
                    mod = '%s.%s' % (model.__module__, model.__name__)
                    model_list.append(mod)
    if app_label is not None and app_label in Registry.registry:
        return Registry.registry[app_label](app_title, model_list)
    return _get_dashboard_cls(getattr(settings, 'ADMIN_TOOLS_APP_INDEX_DASHBOARD', 'admin_tools.dashboard.dashboards.DefaultAppIndexDashboard'), context)(app_title, model_list)

def get_app_template_dir(app_name):
    """Get the template directory for an application

    Uses apps interface available in django 1.7+

    Returns a full path, or None if the app was not found."""
    if app_name in _cache:
        return _cache[app_name]
    template_dir = None
    for app in apps.get_app_configs():
        if app.label == app_name:
            template_dir = join(app.path, 'templates')
            break
    _cache[app_name] = template_dir
    return template_dir

def get_avail_models(request):
    """Returns (model, perm,) for all models user can possibly see"""
    items = []
    admin_site = get_admin_site(request=request)
    for model, model_admin in admin_site._registry.items():
        perms = model_admin.get_model_perms(request)
        if True not in perms.values():
            continue
        items.append((model, perms))
    return items

def filter_models(request, models, exclude):
    """Returns (model, perm,) for all models that match models/exclude patterns
    and are visible by current user."""
    items = get_avail_models(request)
    included = []
    def full_name(model):
        return '%s.%s' % (model.__module__, model.__name__)
    if len(models) == 0:
        included = items
    else:
        for pattern in models:
            wildcard_models = []
            for item in items:
                model, perms = item
                model_str = full_name(model)
                if model_str == pattern:
                    included.append(item)
                elif fnmatch(model_str, pattern) and item not in wildcard_models:
                    wildcard_models.append(item)
            if wildcard_models:
                wildcard_models.sort(key=lambda x: x[0]._meta.verbose_name_plural)
                included += wildcard_models
    result = included[:]
    for pattern in exclude:
        for item in included:
            model, perms = item
            if fnmatch(full_name(model), pattern):
                try:
                    result.remove(item)
                except ValueError:
                    pass
    return result

def run_add_system(name, token, org, system, prompt):
    """Adds a new system to the repo."""
    repo = get_repo(token=token, org=org, name=name)
    try:
        repo.create_label(name=system.strip(), color=SYSTEM_LABEL_COLOR)
        click.secho('Successfully added new system {}'.format(system), fg='green')
        if prompt and click.confirm('Run update to re-generate the page?'):
            run_update(name=name, token=token, org=org)
    except GithubException as e:
        if e.status == 422:
            click.secho('Unable to add new system {}, it already exists.'.format(system), fg='yellow')
            return
        raise

def run_remove_system(name, token, org, system, prompt):
    """Removes a system from the repo."""
    repo = get_repo(token=token, org=org, name=name)
    try:
        label = repo.get_label(name=system.strip())
        label.delete()
        click.secho('Successfully deleted {}'.format(system), fg='green')
        if prompt and click.confirm('Run update to re-generate the page?'):
            run_update(name=name, token=token, org=org)
    except UnknownObjectException:
        click.secho('Unable to remove system {}, it does not exist.'.format(system), fg='yellow')

def get_config(repo):
    """Get the config for the repo, merged with the default config. Returns the default config if
    no config file is found."""
    files = get_files(repo)
    config = DEFAULT_CONFIG
    if 'config.json' in files:
        config_file = repo.get_file_contents('/config.json', ref='gh-pages')
        try:
            repo_config = json.loads(config_file.decoded_content.decode('utf-8'))
            config.update(repo_config)
        except ValueError:
            click.secho('WARNING: Unable to parse config file. Using defaults.', fg='yellow')
    return config

def validate_confusables(value):
    """Validator which disallows 'dangerous' usernames likely to
    represent homograph attacks.

    A username is 'dangerous' if it is mixed-script (as defined by
    Unicode 'Script' property) and contains one or more characters
    appearing in the Unicode Visually Confusable Characters file."""
    if not isinstance(value, six.text_type):
        return
    if confusables.is_dangerous(value):
        raise ValidationError(CONFUSABLE, code='invalid')

def timestamp_with_timezone(dt=None):
    """Return a timestamp with a timezone for the configured locale.  If all else
    fails, consider localtime to be UTC."""
    dt = dt or datetime.now()
    if timezone is None:
        return dt.strftime('%Y-%m-%d %H:%M%z')
    if not dt.tzinfo:
        tz = timezone.get_current_timezone()
        if not tz:
            tz = timezone.utc
        dt = dt.replace(tzinfo=timezone.get_current_timezone())
    return dt.strftime('%Y-%m-%d %H:%M%z')

def get_access_control_function():
    """Return a predicate for determining if a user can
    access the Rosetta views"""
    fn_path = getattr(settings, 'ROSETTA_ACCESS_CONTROL_FUNCTION', None)
    if fn_path is None:
        return is_superuser_staff_or_in_translators_group
    perm_module, perm_func = fn_path.rsplit('.', 1)
    perm_module = importlib.import_module(perm_module)
    return getattr(perm_module, perm_func)

def get_video_duration(video_file):
    """Get video duration in seconds"""
    try:
        return float(FFProbe(video_file).video[0].duration)
    except Exception as e:
        print('could not extract duration from video {} due to {}'.format(video_file, e))
        return None

def get_video_end_time(video_file):
    """Get video end time in seconds"""
    if not os.path.isfile(video_file):
        print('Error, video file {} does not exist'.format(video_file))
        return None
    try:
        time_string = FFProbe(video_file).video[0].creation_time
        try:
            creation_time = datetime.datetime.strptime(time_string, TIME_FORMAT)
        except:
            creation_time = datetime.datetime.strptime(time_string, TIME_FORMAT_2)
    except:
        return None
    return creation_time

def get_video_start_time(video_file):
    """Get start time in seconds"""
    if not os.path.isfile(video_file):
        print('Error, video file {} does not exist'.format(video_file))
        return None
    video_end_time = get_video_end_time(video_file)
    duration = get_video_duration(video_file)
    if video_end_time == None or duration == None:
        return None
    else:
        video_start_time = video_end_time - datetime.timedelta(seconds=duration)
        return video_start_time

def get_lat_lon_time_from_gpx(gpx_file, local_time=True):
    """Read location and time stamps from a track in a GPX file.

    Returns a list of tuples (time, lat, lon).

    GPX stores time in UTC, by default we assume your camera used the local time
    and convert accordingly."""
    with open(gpx_file, 'r') as f:
        gpx = gpxpy.parse(f)
    points = []
    if len(gpx.tracks) > 0:
        for track in gpx.tracks:
            for segment in track.segments:
                for point in segment.points:
                    t = utc_to_localtime(point.time) if local_time else point.time
                    points.append((t, point.latitude, point.longitude, point.elevation))
    if len(gpx.waypoints) > 0:
        for point in gpx.waypoints:
            t = utc_to_localtime(point.time) if local_time else point.time
            points.append((t, point.latitude, point.longitude, point.elevation))
    points.sort()
    return points

def dms_to_decimal(degrees, minutes, seconds, hemisphere):
    """Convert from degrees, minutes, seconds to decimal degrees.
    @author: mprins"""
    dms = float(degrees) + float(minutes) / 60 + float(seconds) / 3600
    if hemisphere in 'WwSs':
        dms = -1 * dms
    return dms

def decimal_to_dms(value, precision):
    """Convert decimal position to degrees, minutes, seconds in a fromat supported by EXIF"""
    deg = math.floor(value)
    min = math.floor((value - deg) * 60)
    sec = math.floor((value - deg - min / 60) * 3600 * precision)
    return ((deg, 1), (min, 1), (sec, precision))

def interpolate_timestamp(capture_times):
    """Interpolate time stamps in case of identical timestamps"""
    timestamps = []
    num_file = len(capture_times)
    time_dict = OrderedDict()
    if num_file < 2:
        return capture_times
    time_dict = OrderedDict()
    for i, t in enumerate(capture_times):
        if t not in time_dict:
            time_dict[t] = {'count': 0, 'pointer': 0}
            interval = 0
            if i != 0:
                interval = (t - capture_times[i - 1]).total_seconds()
                time_dict[capture_times[i - 1]]['interval'] = interval
        time_dict[t]['count'] += 1
    if len(time_dict) >= 2:
        time_dict[time_dict.keys()[-1]]['interval'] = time_dict[time_dict.keys()[-2]]['interval']
    else:
        time_dict[time_dict.keys()[0]]['interval'] = time_dict[time_dict.keys()[0]]['count'] * 1.0
    for t in capture_times:
        d = time_dict[t]
        s = datetime.timedelta(seconds=d['pointer'] * d['interval'] / float(d['count']))
        updated_time = t + s
        time_dict[t]['pointer'] += 1
        timestamps.append(updated_time)
    return timestamps

