def decode_file(fname):
    """Given the name of a pcap file, open it, decode the contents and yield each packet."""
    if _debug:
        decode_file._debug('decode_file %r', fname)
    if not pcap:
        raise RuntimeError('failed to import pcap')
    p = pcap.pcap(fname)
    for i, (timestamp, data) in enumerate(p):
        try:
            pkt = decode_packet(data)
            if not pkt:
                continue
        except Exception as err:
            if _debug:
                decode_file._debug('    - exception decoding packet %d: %r', i + 1, err)
            continue
        pkt._number = i + 1
        pkt._timestamp = timestamp
        yield pkt

def stop(*args):
    """Call to stop running, may be called with a signum and frame
    parameter if called as a signal handler."""
    if _debug:
        stop._debug('stop')
    global running, taskManager
    if args:
        sys.stderr.write('===== TERM Signal, %s\n' % time.strftime('%d-%b-%Y %H:%M:%S'))
        sys.stderr.flush()
    running = False
    if taskManager and taskManager.trigger:
        if _debug:
            stop._debug('    - trigger')
        taskManager.trigger.set()

def compose_capability(base, *classes):
    """Create a new class starting with the base and adding capabilities."""
    if _debug:
        compose_capability._debug('compose_capability %r %r', base, classes)
    if not issubclass(base, Collector):
        raise TypeError('base must be a subclass of Collector')
    for cls in classes:
        if not issubclass(cls, Capability):
            raise TypeError('%s is not a Capability subclass' % (cls,))
    bases = (base,) + classes
    name = base.__name__
    for cls in classes:
        name += '+' + cls.__name__
    return type(name, bases, {})

def add_capability(base, *classes):
    """Add capabilites to an existing base, all objects get the additional
    functionality, but don't get inited.  Use with great care!"""
    if _debug:
        add_capability._debug('add_capability %r %r', base, classes)
    if not issubclass(base, Collector):
        raise TypeError('base must be a subclass of Collector')
    for cls in classes:
        if not issubclass(cls, Capability):
            raise TypeError('%s is not a Capability subclass' % (cls,))
    base.__bases__ += classes
    for cls in classes:
        base.__name__ += '+' + cls.__name__

def _merge(*args):
    """Create a composite pattern and compile it."""
    return re.compile('^' + '[/-]'.join(args) + '(?:\\s+' + _dow + ')?$')

def key_value_contents(use_dict=None, as_class=dict, key_values=()):
    """Return the contents of an object as a dict."""
    if _debug:
        key_value_contents._debug('key_value_contents use_dict=%r as_class=%r key_values=%r', use_dict, as_class, key_values)
    if use_dict is None:
        use_dict = as_class()
    for k, v in key_values:
        if v is not None:
            if hasattr(v, 'dict_contents'):
                v = v.dict_contents(as_class=as_class)
            use_dict.__setitem__(k, v)
    return use_dict

def match_date(date, date_pattern):
    """Match a specific date, a four-tuple with no special values, with a date
    pattern, four-tuple possibly having special values."""
    year, month, day, day_of_week = date
    year_p, month_p, day_p, day_of_week_p = date_pattern
    if year_p == 255:
        pass
    elif year != year_p:
        return False
    if month_p == 255:
        pass
    elif month_p == 13:
        if month % 2 == 0:
            return False
    elif month_p == 14:
        if month % 2 == 1:
            return False
    elif month != month_p:
        return False
    if day_p == 255:
        pass
    elif day_p == 32:
        last_day = calendar.monthrange(year + 1900, month)[1]
        if day != last_day:
            return False
    elif day_p == 33:
        if day % 2 == 0:
            return False
    elif day_p == 34:
        if day % 2 == 1:
            return False
    elif day != day_p:
        return False
    if day_of_week_p == 255:
        pass
    elif day_of_week != day_of_week_p:
        return False
    return True

def datetime_to_time(date, time):
    """Take the date and time 4-tuples and return the time in seconds since
    the epoch as a floating point number."""
    if 255 in date or 255 in time:
        raise RuntimeError('specific date and time required')
    time_tuple = (date[0] + 1900, date[1], date[2], time[0], time[1], time[2], 0, 0, -1)
    return _mktime(time_tuple)

