def pack_ip_addr(addr):
    """Given an IP address tuple like ('1.2.3.4', 47808) return the six-octet string
    useful for a BACnet address."""
    addr, port = addr
    return socket.inet_aton(addr) + struct.pack('!H', port & _short_mask)

def unpack_ip_addr(addr):
    """Given a six-octet BACnet address, return an IP address tuple."""
    if isinstance(addr, bytearray):
        addr = bytes(addr)
    return (socket.inet_ntoa(addr[0:4]), struct.unpack('!H', addr[4:6])[0])

def btox(data, sep=''):
    """Return the hex encoding of a blob (string)."""
    hex_str = binascii.hexlify(data)
    if sep:
        hex_str = sep.join((hex_str[i:i + 2] for i in range(0, len(hex_str), 2)))
    return hex_str

def xtob(data, sep=''):
    """Interpret the hex encoding of a blob (string)."""
    data = re.sub('[^0-9a-fA-F]', '', data)
    return binascii.unhexlify(data)

def encode_max_segments_accepted(arg):
    """Encode the maximum number of segments the device will accept, Section
    20.1.2.4, and if the device says it can only accept one segment it shouldn't
    say that it supports segmentation!"""
    if not arg:
        return 0
    if arg > 64:
        return 7
    for i in range(6, 0, -1):
        if _max_segments_accepted_encoding[i] <= arg:
            return i
    raise ValueError('invalid max max segments accepted: %r' % (arg,))

def encode_max_apdu_length_accepted(arg):
    """Return the encoding of the highest encodable value less than the
    value of the arg."""
    for i in range(5, -1, -1):
        if arg >= _max_apdu_length_encoding[i]:
            return i
    raise ValueError('invalid max APDU length accepted: %r' % (arg,))

def ConsoleLogHandler(loggerRef='', handler=None, level=logging.DEBUG, color=None):
    """Add a handler to stderr with our custom formatter to a logger."""
    if isinstance(loggerRef, logging.Logger):
        pass
    elif isinstance(loggerRef, str):
        if not loggerRef:
            loggerRef = _log
        elif loggerRef not in logging.Logger.manager.loggerDict:
            raise RuntimeError('not a valid logger name: %r' % (loggerRef,))
        loggerRef = logging.getLogger(loggerRef)
    else:
        raise RuntimeError('not a valid logger reference: %r' % (loggerRef,))
    if hasattr(loggerRef, 'globs'):
        loggerRef.globs['_debug'] += 1
    elif hasattr(loggerRef.parent, 'globs'):
        loggerRef.parent.globs['_debug'] += 1
    if not handler:
        handler = logging.StreamHandler()
        handler.setLevel(level)
    handler.setFormatter(LoggingFormatter(color))
    loggerRef.addHandler(handler)
    loggerRef.setLevel(level)

def run_once():
    """Make a pass through the scheduled tasks and deferred functions just
    like the run() function but without the asyncore call (so there is no
    socket IO actviity) and the timers."""
    if _debug:
        run_once._debug('run_once')
    global taskManager, deferredFns
    taskManager = TaskManager()
    try:
        delta = 0.0
        while delta == 0.0:
            task, delta = taskManager.get_next_task()
            if _debug:
                run_once._debug('    - task, delta: %r, %r', task, delta)
            if task:
                taskManager.process_task(task)
            while deferredFns:
                fnlist = deferredFns
                deferredFns = []
                for fn, args, kwargs in fnlist:
                    if _debug:
                        run_once._debug('    - call: %r %r %r', fn, args, kwargs)
                    fn(*args, **kwargs)
                del fnlist
    except KeyboardInterrupt:
        if _debug:
            run_once._info('keyboard interrupt')
    except Exception as err:
        if _debug:
            run_once._exception('an error has occurred: %s', err)

