def pingable_ws_connect(request=None, on_message_callback=None, on_ping_callback=None):
    """A variation on websocket_connect that returns a PingableWSClientConnection
    with on_ping_callback."""
    request.headers = httputil.HTTPHeaders(request.headers)
    request = httpclient._RequestProxy(request, httpclient.HTTPRequest._DEFAULTS)
    if version_info[0] == 4:
        conn = PingableWSClientConnection(io_loop=ioloop.IOLoop.current(), request=request, on_message_callback=on_message_callback, on_ping_callback=on_ping_callback)
    else:
        conn = PingableWSClientConnection(request=request, on_message_callback=on_message_callback, on_ping_callback=on_ping_callback, max_message_size=getattr(websocket, '_default_max_message_size', 10 * 1024 * 1024))
    return conn.connect_future

def call_with_asked_args(callback, args):
    """Call callback with only the args it wants from args

    Example
    >>> def cb(a):
    ...    return a * 5

    >>> print(call_with_asked_args(cb, {'a': 4, 'b': 8}))
    20"""
    asked_arg_names = callback.__code__.co_varnames[:callback.__code__.co_argcount]
    asked_arg_values = []
    missing_args = []
    for asked_arg_name in asked_arg_names:
        if asked_arg_name in args:
            asked_arg_values.append(args[asked_arg_name])
        else:
            missing_args.append(asked_arg_name)
    if missing_args:
        raise TypeError('{}() missing required positional argument: {}'.format(callback.__code__.co_name, ', '.join(missing_args)))
    return callback(*asked_arg_values)

