    swag_opts = {}
    if ctx.type == 'file':
        swag_opts = {'swag.type': 'file', 'swag.data_dir': ctx.data_dir, 'swag.data_file': ctx.data_file}
    elif ctx.type == 's3':
        swag_opts = {'swag.type': 's3', 'swag.bucket_name': ctx.bucket_name, 'swag.data_file': ctx.data_file, 'swag.region': ctx.region}
    elif ctx.type == 'dynamodb':
        swag_opts = {'swag.type': 'dynamodb', 'swag.region': ctx.region}
    return SWAGManager(**parse_swag_config_options(swag_opts))

def file(ctx, data_dir, data_file):
    """Use the File SWAG Backend"""
    if not ctx.file:
        ctx.data_file = data_file
    if not ctx.data_dir:
        ctx.data_dir = data_dir
    ctx.type = 'file'

def s3(ctx, bucket_name, data_file, region):
    """Use the S3 SWAG backend."""
    if not ctx.data_file:
        ctx.data_file = data_file
    if not ctx.bucket_name:
        ctx.bucket_name = bucket_name
    if not ctx.region:
        ctx.region = region
    ctx.type = 's3'

def migrate(ctx, start_version, end_version):
    """Transition from one SWAG schema to another."""
    if ctx.type == 'file':
        if ctx.data_file:
            file_path = ctx.data_file
        else:
            file_path = os.path.join(ctx.data_file, ctx.namespace + '.json')
        with open(file_path, 'r') as f:
            data = json.loads(f.read())
        data = run_migration(data, start_version, end_version)
        with open(file_path, 'w') as f:
            f.write(json.dumps(data))

def propagate(ctx):
    """Transfers SWAG data from one backend to another"""
    data = []
    if ctx.type == 'file':
        if ctx.data_file:
            file_path = ctx.data_file
        else:
            file_path = os.path.join(ctx.data_dir, ctx.namespace + '.json')
        with open(file_path, 'r') as f:
            data = json.loads(f.read())
    swag_opts = {'swag.type': 'dynamodb'}
    swag = SWAGManager(**parse_swag_config_options(swag_opts))
    for item in data:
        time.sleep(2)
        swag.create(item, dry_run=ctx.dry_run)

def create(ctx, data):
    """Create a new SWAG item."""
    swag = create_swag_from_ctx(ctx)
    data = json.loads(data.read())
    for account in data:
        swag.create(account, dry_run=ctx.dry_run)

def deploy_service(ctx, path, name, regions, disabled):
    """Deploys a new service JSON to multiple accounts. NAME is the service name you wish to deploy."""
    enabled = False if disabled else True
    swag = create_swag_from_ctx(ctx)
    accounts = swag.get_all(search_filter=path)
    log.debug('Searching for accounts. Found: {} JMESPath: `{}`'.format(len(accounts), path))
    for a in accounts:
        try:
            if not swag.get_service(name, search_filter="[?id=='{id}']".format(id=a['id'])):
                log.info('Found an account to update. AccountName: {name} AccountNumber: {number}'.format(name=a['name'], number=a['id']))
                status = []
                for region in regions:
                    status.append({'enabled': enabled, 'region': region})
                a['services'].append({'name': name, 'status': status})
                swag.update(a, dry_run=ctx.dry_run)
        except InvalidSWAGDataException as e:
            log.warning('Found a data quality issue. AccountName: {name} AccountNumber: {number}'.format(name=a['name'], number=a['id']))
    log.info('Service has been deployed to all matching accounts.')

def seed_aws_data(ctx, data):
    """Seeds SWAG from a list of known AWS accounts."""
    swag = create_swag_from_ctx(ctx)
    for k, v in json.loads(data.read()).items():
        for account in v['accounts']:
            data = {'description': 'This is an AWS owned account used for {}'.format(k), 'id': account['account_id'], 'contacts': [], 'owner': 'aws', 'provider': 'aws', 'sensitive': False, 'email': 'support@amazon.com', 'name': k + '-' + account['region']}
            click.echo(click.style('Seeded Account. AccountName: {}'.format(data['name']), fg='green'))
            swag.create(data, dry_run=ctx.dry_run)

def seed_aws_organization(ctx, owner):
    """Seeds SWAG from an AWS organziation."""
    swag = create_swag_from_ctx(ctx)
    accounts = swag.get_all()
    _ids = [result.get('id') for result in accounts]
    client = boto3.client('organizations')
    paginator = client.get_paginator('list_accounts')
    response_iterator = paginator.paginate()
    count = 0
    for response in response_iterator:
        for account in response['Accounts']:
            if account['Id'] in _ids:
                click.echo(click.style('Ignoring Duplicate Account.  AccountId: {} already exists in SWAG'.format(account['Id']), fg='yellow'))
                continue
            if account['Status'] == 'SUSPENDED':
                status = 'deprecated'
            else:
                status = 'created'
            data = {'id': account['Id'], 'name': account['Name'], 'description': 'Account imported from AWS organization.', 'email': account['Email'], 'owner': owner, 'provider': 'aws', 'contacts': [], 'sensitive': False, 'status': [{'region': 'all', 'status': status}]}
            click.echo(click.style('Seeded Account. AccountName: {}'.format(data['name']), fg='green'))
            count += 1
            swag.create(data, dry_run=ctx.dry_run)
    click.echo('Seeded {} accounts to SWAG.'.format(count))

def load_file(client, bucket, data_file):
    """Tries to load JSON data from S3."""
    logger.debug('Loading item from s3. Bucket: {bucket} Key: {key}'.format(bucket=bucket, key=data_file))
    try:
        data = _get_from_s3(client, bucket, data_file)
    except ClientError as ce:
        if ce.response['Error']['Code'] == 'NoSuchKey':
            return {}
        else:
            raise ce
    if sys.version_info > (3,):
        data = data.decode('utf-8')
    return json.loads(data)

def save_file(client, bucket, data_file, items, dry_run=None):
    """Tries to write JSON data to data file in S3."""
    logger.debug('Writing {number_items} items to s3. Bucket: {bucket} Key: {key}'.format(number_items=len(items), bucket=bucket, key=data_file))
    if not dry_run:
        return _put_to_s3(client, bucket, data_file, json.dumps(items))

def parse_swag_config_options(config):
    """Ensures that options passed to the backend are valid."""
    options = {}
    for key, val in config.items():
        if key.startswith('swag.backend.'):
            options[key[12:]] = val
        if key.startswith('swag.'):
            options[key[5:]] = val
    if options.get('type') == 's3':
        return S3OptionsSchema(strict=True).load(options).data
    elif options.get('type') == 'dynamodb':
        return DynamoDBOptionsSchema(strict=True).load(options).data
    else:
        return FileOptionsSchema(strict=True).load(options).data

def deprecated(message):
    """Deprecated function decorator."""
    def wrapper(fn):
        def deprecated_method(*args, **kargs):
            warnings.warn(message, DeprecationWarning, 2)
            return fn(*args, **kargs)
        deprecated_method.__name__ = fn.__name__
        deprecated_method.__doc__ = '%s\n\n%s' % (message, fn.__doc__)
        return deprecated_method
    return wrapper

def is_sub_dict(sub_dict, dictionary):
    """Legacy filter for determining if a given dict is present."""
    for key in sub_dict.keys():
        if key not in dictionary:
            return False
        if type(sub_dict[key]) is not dict and sub_dict[key] != dictionary[key]:
            return False
        if type(sub_dict[key]) is dict and (not is_sub_dict(sub_dict[key], dictionary[key])):
            return False
    return True

def get_by_name(account_name, bucket, region='us-west-2', json_path='accounts.json', alias=None):
    """Given an account name, attempts to retrieve associated account info."""
    for account in get_all_accounts(bucket, region, json_path)['accounts']:
        if 'aws' in account['type']:
            if account['name'] == account_name:
                return account
            elif alias:
                for a in account['alias']:
                    if a == account_name:
                        return account

def get_by_aws_account_number(account_number, bucket, region='us-west-2', json_path='accounts.json'):
    """Given an account number (or ID), attempts to retrieve associated account info."""
    for account in get_all_accounts(bucket, region, json_path)['accounts']:
        if 'aws' in account['type']:
            if account['metadata']['account_number'] == account_number:
                return account

def get_all_accounts(bucket, region='us-west-2', json_path='accounts.json', **filters):
    """Fetches all the accounts from SWAG."""
    swag_opts = {'swag.type': 's3', 'swag.bucket_name': bucket, 'swag.bucket_region': region, 'swag.data_file': json_path, 'swag.schema_version': 1}
    swag = SWAGManager(**parse_swag_config_options(swag_opts))
    accounts = swag.get_all()
    accounts = [account for account in accounts['accounts'] if is_sub_dict(filters, account)]
    return {'accounts': accounts}

def save_file(data_file, data, dry_run=None):
    """Writes JSON data to data file."""
    if dry_run:
        return
    with open(data_file, 'w', encoding='utf-8') as f:
        if sys.version_info > (3, 0):
            f.write(json.dumps(data))
        else:
            f.write(json.dumps(data).decode('utf-8'))

def run_migration(data, version_start, version_end):
    """Runs migration against a data set."""
    items = []
    if version_start == 1 and version_end == 2:
        for item in data['accounts']:
            items.append(v2.upgrade(item))
    if version_start == 2 and version_end == 1:
        for item in data:
            items.append(v2.downgrade(item))
        items = {'accounts': items}
    return items

def coord_to_dimension(coord):
    """Converts an iris coordinate to a HoloViews dimension."""
    kwargs = {}
    if coord.units.is_time_reference():
        kwargs['value_format'] = get_date_format(coord)
    else:
        kwargs['unit'] = str(coord.units)
    return Dimension(coord.name(), **kwargs)

def sort_coords(coord):
    """Sorts a list of DimCoords trying to ensure that
    dates and pressure levels appear first and the
    longitude and latitude appear last in the correct
    order."""
    import iris
    order = {'T': -2, 'Z': -1, 'X': 1, 'Y': 2}
    axis = iris.util.guess_coord_axis(coord)
    return (order.get(axis, 0), coord and coord.name())

def convert_to_geotype(element, crs=None):
    """Converts a HoloViews element type to the equivalent GeoViews
    element if given a coordinate reference system."""
    geotype = getattr(gv_element, type(element).__name__, None)
    if crs is None or geotype is None or isinstance(element, _Element):
        return element
    return geotype(element, crs=crs)

def find_crs(op, element):
    """Traverses the supplied object looking for coordinate reference
    systems (crs). If multiple clashing reference systems are found
    it will throw an error."""
    crss = [crs for crs in element.traverse(lambda x: x.crs, [_Element]) if crs is not None]
    if not crss:
        return {}
    crs = crss[0]
    if any((crs != ocrs for ocrs in crss[1:])):
        raise ValueError('Cannot %s Elements in different coordinate reference systems.' % type(op).__name__)
    return {'crs': crs}

def add_crs(op, element, **kwargs):
    """Converts any elements in the input to their equivalent geotypes
    if given a coordinate reference system."""
    return element.map(lambda x: convert_to_geotype(x, kwargs.get('crs')), Element)

def is_geographic(element, kdims=None):
    """Utility to determine whether the supplied element optionally
    a subset of its key dimensions represent a geographic coordinate
    system."""
    if isinstance(element, (Overlay, NdOverlay)):
        return any(element.traverse(is_geographic, [_Element]))
    if kdims:
        kdims = [element.get_dimension(d) for d in kdims]
    else:
        kdims = element.kdims
    if len(kdims) != 2 and (not isinstance(element, (Graph, Nodes))):
        return False
    if isinstance(element.data, geographic_types) or isinstance(element, (WMTS, Feature)):
        return True
    elif isinstance(element, _Element):
        return kdims == element.kdims and element.crs
    else:
        return False

def get_cb_plot(cb, plot=None):
    """Finds the subplot with the corresponding stream."""
    plot = plot or cb.plot
    if isinstance(plot, GeoOverlayPlot):
        plots = [get_cb_plot(cb, p) for p in plot.subplots.values()]
        plots = [p for p in plots if any((s in cb.streams and getattr(s, '_triggering', False) for s in p.streams))]
        if plots:
            plot = plots[0]
    return plot

def skip(cb, msg, attributes):
    """Skips applying transforms if data is not geographic."""
    if not all((a in msg for a in attributes)):
        return True
    plot = get_cb_plot(cb)
    return not getattr(plot, 'geographic', False) or not hasattr(plot.current_frame, 'crs')

def project_ranges(cb, msg, attributes):
    """Projects ranges supplied by a callback."""
    if skip(cb, msg, attributes):
        return msg
    plot = get_cb_plot(cb)
    x0, x1 = msg.get('x_range', (0, 1000))
    y0, y1 = msg.get('y_range', (0, 1000))
    extents = (x0, y0, x1, y1)
    x0, y0, x1, y1 = project_extents(extents, plot.projection, plot.current_frame.crs)
    coords = {'x_range': (x0, x1), 'y_range': (y0, y1)}
    return {k: v for k, v in coords.items() if k in attributes}

def project_point(cb, msg, attributes=('x', 'y')):
    """Projects a single point supplied by a callback"""
    if skip(cb, msg, attributes):
        return msg
    plot = get_cb_plot(cb)
    x, y = (msg.get('x', 0), msg.get('y', 0))
    crs = plot.current_frame.crs
    coordinates = crs.transform_points(plot.projection, np.array([x]), np.array([y]))
    msg['x'], msg['y'] = coordinates[0, :2]
    return {k: v for k, v in msg.items() if k in attributes}

def geom_dict_to_array_dict(geom_dict, coord_names=['Longitude', 'Latitude']):
    """Converts a dictionary containing an geometry key to a dictionary
    of x- and y-coordinate arrays and if present a list-of-lists of
    hole array."""
    x, y = coord_names
    geom = geom_dict['geometry']
    new_dict = {k: v for k, v in geom_dict.items() if k != 'geometry'}
    array = geom_to_array(geom)
    new_dict[x] = array[:, 0]
    new_dict[y] = array[:, 1]
    if geom.geom_type == 'Polygon':
        holes = []
        for interior in geom.interiors:
            holes.append(geom_to_array(interior))
        if holes:
            new_dict['holes'] = [holes]
    elif geom.geom_type == 'MultiPolygon':
        outer_holes = []
        for g in geom:
            holes = []
            for interior in g.interiors:
                holes.append(geom_to_array(interior))
            outer_holes.append(holes)
        if any((hs for hs in outer_holes)):
            new_dict['holes'] = outer_holes
    return new_dict

def path_to_geom_dicts(path, skip_invalid=True):
    """Converts a Path element into a list of geometry dictionaries,
    preserving all value dimensions."""
    interface = path.interface.datatype
    if interface == 'geodataframe':
        return [row.to_dict() for _, row in path.data.iterrows()]
    elif interface == 'geom_dictionary':
        return path.data
    geoms = []
    invalid = False
    xdim, ydim = path.kdims
    for i, path in enumerate(path.split(datatype='columns')):
        array = np.column_stack([path.pop(xdim.name), path.pop(ydim.name)])
        splits = np.where(np.isnan(array[:, :2].astype('float')).sum(axis=1))[0]
        arrays = np.split(array, splits + 1) if len(splits) else [array]
        subpaths = []
        for j, arr in enumerate(arrays):
            if j != len(arrays) - 1:
                arr = arr[:-1]
            if len(arr) == 0:
                continue
            elif len(arr) == 1:
                if skip_invalid:
                    continue
                g = Point(arr[0])
                invalid = True
            else:
                g = LineString(arr)
            subpaths.append(g)
        if invalid:
            geoms += [dict(path, geometry=sp) for sp in subpaths]
            continue
        elif len(subpaths) == 1:
            geom = subpaths[0]
        elif subpaths:
            geom = MultiLineString(subpaths)
        path['geometry'] = geom
        geoms.append(path)
    return geoms

def to_ccw(geom):
    """Reorients polygon to be wound counter-clockwise."""
    if isinstance(geom, sgeom.Polygon) and (not geom.exterior.is_ccw):
        geom = sgeom.polygon.orient(geom)
    return geom

def geom_length(geom):
    """Calculates the length of coordinates in a shapely geometry."""
    if geom.geom_type == 'Point':
        return 1
    if hasattr(geom, 'exterior'):
        geom = geom.exterior
    if not geom.geom_type.startswith('Multi') and hasattr(geom, 'array_interface_base'):
        return len(geom.array_interface_base['data']) // 2
    else:
        length = 0
        for g in geom:
            length += geom_length(g)
        return length

def geo_mesh(element):
    """Get mesh data from a 2D Element ensuring that if the data is
    on a cylindrical coordinate system and wraps globally that data
    actually wraps around."""
    if len(element.vdims) > 1:
        xs, ys = (element.dimension_values(i, False, False) for i in range(2))
        zs = np.dstack([element.dimension_values(i, False, False) for i in range(2, 2 + len(element.vdims))])
    else:
        xs, ys, zs = (element.dimension_values(i, False, False) for i in range(3))
    lon0, lon1 = element.range(0)
    if isinstance(element.crs, ccrs._CylindricalProjection) and lon1 - lon0 == 360:
        xs = np.append(xs, xs[0:1] + 360, axis=0)
        zs = np.ma.concatenate([zs, zs[:, 0:1]], axis=1)
    return (xs, ys, zs)

def process_crs(crs):
    """Parses cartopy CRS definitions defined in one of a few formats:

      1. EPSG codes:   Defined as string of the form "EPSG: {code}" or an integer
      2. proj.4 string: Defined as string of the form "{proj.4 string}"
      3. cartopy.crs.CRS instance
      4. None defaults to crs.PlateCaree"""
    try:
        import cartopy.crs as ccrs
        import geoviews as gv
        import pyproj
    except:
        raise ImportError('Geographic projection support requires GeoViews and cartopy.')
    if crs is None:
        return ccrs.PlateCarree()
    if isinstance(crs, basestring) and crs.lower().startswith('epsg'):
        try:
            crs = ccrs.epsg(crs[5:].lstrip().rstrip())
        except:
            raise ValueError("Could not parse EPSG code as CRS, must be of the format 'EPSG: {code}.'")
    elif isinstance(crs, int):
        crs = ccrs.epsg(crs)
    elif isinstance(crs, (basestring, pyproj.Proj)):
        try:
            crs = proj_to_cartopy(crs)
        except:
            raise ValueError("Could not parse EPSG code as CRS, must be of the format 'proj4: {proj4 string}.'")
    elif not isinstance(crs, ccrs.CRS):
        raise ValueError('Projection must be defined as a EPSG code, proj4 string, cartopy CRS or pyproj.Proj.')
    return crs

def find_geom(geom, geoms):
    """Returns the index of a geometry in a list of geometries avoiding
    expensive equality checks of `in` operator."""
    for i, g in enumerate(geoms):
        if g is geom:
            return i

