def get_task_class(tasks, task_args):
    """Reads in a list of tasks provided by the user,
    loads the appropiate task, and returns two lists,
    pre_stop_tasks and post_stop_tasks
    :param tasks: list of strings locating tasks to load
    :type tasks: list
    :param task_args: list of strings to be used as args
    :type task_args: list"""
    pre_stop_tasks = []
    post_stop_tasks = []
    task_to_task_args = dict(list(zip(tasks, task_args)))
    tasks_classes = [PreStopTask, PostStopTask]
    for func, task_args in task_to_task_args.items():
        for task_class in tasks_classes:
            imported_class = dynamic_import(func, task_class)
            if imported_class:
                if task_class is PreStopTask:
                    pre_stop_tasks.append(imported_class(task_args))
                elif task_class is PostStopTask:
                    post_stop_tasks.append(imported_class(task_args))
                else:
                    print('ERROR: Class is not a type of Pre/Post StopTask:' + func)
                    sys.exit(1)
    return (pre_stop_tasks, post_stop_tasks)

def get_topic_partition_metadata(hosts):
    """Returns topic-partition metadata from Kafka broker.

    kafka-python 1.3+ doesn't include partition metadata information in
    topic_partitions so we extract it from metadata ourselves."""
    kafka_client = KafkaToolClient(hosts, timeout=10)
    kafka_client.load_metadata_for_topics()
    topic_partitions = kafka_client.topic_partitions
    resp = kafka_client.send_metadata_request()
    for _, topic, partitions in resp.topics:
        for partition_error, partition, leader, replicas, isr in partitions:
            if topic_partitions.get(topic, {}).get(partition) is not None:
                topic_partitions[topic][partition] = PartitionMetadata(topic, partition, leader, replicas, isr, partition_error)
    return topic_partitions

def get_topic_partition_with_error(cluster_config, error, fetch_unavailable_brokers=False):
    """Fetches the metadata from the cluster and returns the set of
    (topic, partition) tuples containing all the topic-partitions
    currently affected by the specified error. It also fetches unavailable-broker list
    if required."""
    metadata = get_topic_partition_metadata(cluster_config.broker_list)
    affected_partitions = set()
    if fetch_unavailable_brokers:
        unavailable_brokers = set()
    with ZK(cluster_config) as zk:
        for partitions in metadata.values():
            for partition_metadata in partitions.values():
                if int(partition_metadata.error) == error:
                    if fetch_unavailable_brokers:
                        unavailable_brokers |= get_unavailable_brokers(zk, partition_metadata)
                    affected_partitions.add((partition_metadata.topic, partition_metadata.partition))
    if fetch_unavailable_brokers:
        return (affected_partitions, unavailable_brokers)
    else:
        return affected_partitions

def nullify_offsets(offsets):
    """Modify offsets metadata so that the partition offsets
    have null payloads.

    :param offsets: dict {<topic>: {<partition>: <offset>}}
    :returns: a dict topic: partition: offset"""
    result = {}
    for topic, partition_offsets in six.iteritems(offsets):
        result[topic] = _nullify_partition_offsets(partition_offsets)
    return result

def variance(data, data_mean=None):
    """Return variance of a sequence of numbers.
    :param data_mean: Precomputed mean of the sequence."""
    data_mean = data_mean or mean(data)
    return sum(((x - data_mean) ** 2 for x in data)) / len(data)

def stdevp(data, data_mean=None, data_variance=None):
    """Return standard deviation of a sequence of numbers.
    :param data_mean: Precomputed mean of the sequence.
    :param data_variance: Precomputed variance of the sequence."""
    data_variance = data_variance or variance(data, data_mean)
    return sqrt(data_variance)

def get_replication_group_imbalance_stats(rgs, partitions):
    """Calculate extra replica count replica count over each replication-group
    and net extra-same-replica count."""
    tot_rgs = len(rgs)
    extra_replica_cnt_per_rg = defaultdict(int)
    for partition in partitions:
        opt_replica_cnt, extra_replicas_allowed = compute_optimum(tot_rgs, partition.replication_factor)
        for rg in rgs:
            replica_cnt_rg = rg.count_replica(partition)
            extra_replica_cnt, extra_replicas_allowed = get_extra_element_count(replica_cnt_rg, opt_replica_cnt, extra_replicas_allowed)
            extra_replica_cnt_per_rg[rg.id] += extra_replica_cnt
    net_imbalance = sum(extra_replica_cnt_per_rg.values())
    return (net_imbalance, extra_replica_cnt_per_rg)

def _read_generated_broker_id(meta_properties_path):
    """reads broker_id from meta.properties file.

    :param string meta_properties_path: path for meta.properties file
    :returns int: broker_id from meta_properties_path"""
    try:
        with open(meta_properties_path, 'r') as f:
            broker_id = _parse_meta_properties_file(f)
    except IOError:
        raise IOError('Cannot open meta.properties file: {path}'.format(path=meta_properties_path))
    except ValueError:
        raise ValueError('Broker id not valid')
    if broker_id is None:
        raise ValueError('Autogenerated broker id missing from data directory')
    return broker_id

def merge_partition_offsets(*partition_offsets):
    """Merge the partition offsets of a single topic from multiple responses.

    :param partition_offsets: list of dict partition: offset
    :returns: dict partition: offset"""
    output = dict()
    for partition_offset in partition_offsets:
        for partition, offset in six.iteritems(partition_offset):
            prev_offset = output.get(partition, 0)
            output[partition] = max(prev_offset, offset)
    return output

def tuple_replace(tup, *pairs):
    """Return a copy of a tuple with some elements replaced.

    :param tup: The tuple to be copied.
    :param pairs: Any number of (index, value) tuples where index is the index
        of the item to replace and value is the new value of the item."""
    tuple_list = list(tup)
    for index, value in pairs:
        tuple_list[index] = value
    return tuple(tuple_list)

def tuple_alter(tup, *pairs):
    """Return a copy of a tuple with some elements altered.

    :param tup: The tuple to be copied.
    :param pairs: Any number of (index, func) tuples where index is the index
        of the item to alter and the new value is func(tup[index])."""
    tuple_list = list(tup)
    for i, f in pairs:
        tuple_list[i] = f(tuple_list[i])
    return tuple(tuple_list)

def tuple_remove(tup, *items):
    """Return a copy of a tuple with some items removed.

    :param tup: The tuple to be copied.
    :param items: Any number of items. The first instance of each item will
        be removed from the tuple."""
    tuple_list = list(tup)
    for item in items:
        tuple_list.remove(item)
    return tuple(tuple_list)

def positive_int(string):
    """Convert string to positive integer."""
    error_msg = 'Positive integer required, {string} given.'.format(string=string)
    try:
        value = int(string)
    except ValueError:
        raise ArgumentTypeError(error_msg)
    if value < 0:
        raise ArgumentTypeError(error_msg)
    return value

def positive_nonzero_int(string):
    """Convert string to positive integer greater than zero."""
    error_msg = 'Positive non-zero integer required, {string} given.'.format(string=string)
    try:
        value = int(string)
    except ValueError:
        raise ArgumentTypeError(error_msg)
    if value <= 0:
        raise ArgumentTypeError(error_msg)
    return value

def positive_float(string):
    """Convert string to positive float."""
    error_msg = 'Positive float required, {string} given.'.format(string=string)
    try:
        value = float(string)
    except ValueError:
        raise ArgumentTypeError(error_msg)
    if value < 0:
        raise ArgumentTypeError(error_msg)
    return value

def dict_merge(set1, set2):
    """Joins two dictionaries."""
    return dict(list(set1.items()) + list(set2.items()))

def to_h(num, suffix='B'):
    """Converts a byte value in human readable form."""
    if num is None:
        return 'None'
    for unit in ['', 'Ki', 'Mi', 'Gi', 'Ti', 'Pi', 'Ei', 'Zi']:
        if abs(num) < 1024.0:
            return '%3.1f%s%s' % (num, unit, suffix)
        num /= 1024.0
    return '%.1f%s%s' % (num, 'Yi', suffix)

def format_to_json(data):
    """Converts `data` into json
    If stdout is a tty it performs a pretty print."""
    if sys.stdout.isatty():
        return json.dumps(data, indent=4, separators=(',', ': '))
    else:
        return json.dumps(data)

def plan_to_assignment(plan):
    """Convert the plan to the format used by cluster-topology."""
    assignment = {}
    for elem in plan['partitions']:
        assignment[elem['topic'], elem['partition']] = elem['replicas']
    return assignment

def assignment_to_plan(assignment):
    """Convert an assignment to the format used by Kafka to
    describe a reassignment plan."""
    return {'version': 1, 'partitions': [{'topic': t_p[0], 'partition': t_p[1], 'replicas': replica} for t_p, replica in six.iteritems(assignment)]}

def _prepare_output(partitions, verbose):
    """Returns dict with 'raw' and 'message' keys filled."""
    out = {}
    partitions_count = len(partitions)
    out['raw'] = {'offline_count': partitions_count}
    if partitions_count == 0:
        out['message'] = 'No offline partitions.'
    else:
        out['message'] = '{count} offline partitions.'.format(count=partitions_count)
        if verbose:
            lines = ('{}:{}'.format(topic, partition) for topic, partition in partitions)
            out['verbose'] = 'Partitions:\n' + '\n'.join(lines)
        else:
            cmdline = sys.argv[:]
            cmdline.insert(1, '-v')
            out['message'] += '\nTo see all offline partitions run: ' + ' '.join(cmdline)
    if verbose:
        out['raw']['partitions'] = [{'topic': topic, 'partition': partition} for topic, partition in partitions]
    return out

def preprocess_topics(source_groupid, source_topics, dest_groupid, topics_dest_group):
    """Pre-process the topics in source and destination group for duplicates."""
    common_topics = [topic for topic in topics_dest_group if topic in source_topics]
    if common_topics:
        print('Error: Consumer Group ID: {groupid} is already subscribed to following topics: {topic}.\nPlease delete this topics from new group before re-running the command.'.format(groupid=dest_groupid, topic=', '.join(common_topics)), file=sys.stderr)
        sys.exit(1)
    if topics_dest_group:
        in_str = 'New Consumer Group: {dest_groupid} already exists.\nTopics subscribed to by the consumer groups are listed below:\n{source_groupid}: {source_group_topics}\n{dest_groupid}: {dest_group_topics}\nDo you intend to copy intoexisting consumer destination-group? (y/n)'.format(source_groupid=source_groupid, source_group_topics=source_topics, dest_groupid=dest_groupid, dest_group_topics=topics_dest_group)
        prompt_user_input(in_str)

def create_offsets(zk, consumer_group, offsets):
    """Create path with offset value for each topic-partition of given consumer
    group.

    :param zk: Zookeeper client
    :param consumer_group: Consumer group id for given offsets
    :type consumer_group: int
    :param offsets: Offsets of all topic-partitions
    :type offsets: dict(topic, dict(partition, offset))"""
    for topic, partition_offsets in six.iteritems(offsets):
        for partition, offset in six.iteritems(partition_offsets):
            new_path = '/consumers/{groupid}/offsets/{topic}/{partition}'.format(groupid=consumer_group, topic=topic, partition=partition)
            try:
                zk.create(new_path, value=offset, makepath=True)
            except NodeExistsError:
                print('Error: Path {path} already exists. Please re-run the command.'.format(path=new_path), file=sys.stderr)
                raise

def get_offset_topic_partition_count(kafka_config):
    """Given a kafka cluster configuration, return the number of partitions
    in the offset topic. It will raise an UnknownTopic exception if the topic
    cannot be found."""
    metadata = get_topic_partition_metadata(kafka_config.broker_list)
    if CONSUMER_OFFSET_TOPIC not in metadata:
        raise UnknownTopic('Consumer offset topic is missing.')
    return len(metadata[CONSUMER_OFFSET_TOPIC])

def get_group_partition(group, partition_count):
    """Given a group name, return the partition number of the consumer offset
    topic containing the data associated to that group."""
    def java_string_hashcode(s):
        h = 0
        for c in s:
            h = 31 * h + ord(c) & 4294967295
        return (h + 2147483648 & 4294967295) - 2147483648
    return abs(java_string_hashcode(group)) % partition_count

def consumer_commit_for_times(consumer, partition_to_offset, atomic=False):
    """Commits offsets to Kafka using the given KafkaConsumer and offsets, a mapping
    of TopicPartition to Unix Epoch milliseconds timestamps.

    Arguments:
        consumer (KafkaConsumer): an initialized kafka-python consumer.
        partitions_to_offset (dict TopicPartition: OffsetAndTimestamp): Map of TopicPartition to OffsetAndTimestamp. Return value of offsets_for_times.
        atomic (bool): Flag to specify whether the commit should fail if offsets are not found for some
            TopicPartition: timestamp pairs."""
    no_offsets = set()
    for tp, offset in six.iteritems(partition_to_offset):
        if offset is None:
            logging.error('No offsets found for topic-partition {tp}. Either timestamps not supported for the topic {tp}, or no offsets found after timestamp specified, or there is no data in the topic-partition.'.format(tp=tp))
            no_offsets.add(tp)
    if atomic and len(no_offsets) > 0:
        logging.error('Commit aborted; offsets were not found for timestamps in topics {}'.format(','.join([str(tp) for tp in no_offsets])))
        return
    offsets_metadata = {tp: OffsetAndMetadata(partition_to_offset[tp].offset, metadata=None) for tp in six.iterkeys(partition_to_offset) if tp not in no_offsets}
    if len(offsets_metadata) != 0:
        consumer.commit(offsets_metadata)

def get_cluster_config(cluster_type, cluster_name=None, kafka_topology_base_path=None):
    """Return the cluster configuration.
    Use the local cluster if cluster_name is not specified.

    :param cluster_type: the type of the cluster
    :type cluster_type: string
    :param cluster_name: the name of the cluster
    :type cluster_name: string
    :param kafka_topology_base_path: base path to look for <cluster_type>.yaml
    :type cluster_name: string
    :returns: the cluster
    :rtype: ClusterConfig"""
    if not kafka_topology_base_path:
        config_dirs = get_conf_dirs()
    else:
        config_dirs = [kafka_topology_base_path]
    topology = None
    for config_dir in config_dirs:
        try:
            topology = TopologyConfiguration(cluster_type, config_dir)
        except MissingConfigurationError:
            pass
    if not topology:
        raise MissingConfigurationError('No available configuration for type {0}'.format(cluster_type))
    if cluster_name:
        return topology.get_cluster_by_name(cluster_name)
    else:
        return topology.get_local_cluster()

def iter_configurations(kafka_topology_base_path=None):
    """Cluster topology iterator.
    Iterate over all the topologies available in config."""
    if not kafka_topology_base_path:
        config_dirs = get_conf_dirs()
    else:
        config_dirs = [kafka_topology_base_path]
    types = set()
    for config_dir in config_dirs:
        new_types = [x for x in map(lambda x: os.path.basename(x)[:-5], glob.glob('{0}/*.yaml'.format(config_dir))) if x not in types]
        for cluster_type in new_types:
            try:
                topology = TopologyConfiguration(cluster_type, config_dir)
            except ConfigurationError:
                continue
            types.add(cluster_type)
            yield topology

def convert_to_broker_id(string):
    """Convert string to kafka broker_id."""
    error_msg = 'Positive integer or -1 required, {string} given.'.format(string=string)
    try:
        value = int(string)
    except ValueError:
        raise argparse.ArgumentTypeError(error_msg)
    if value <= 0 and value != -1:
        raise argparse.ArgumentTypeError(error_msg)
    return value

def run():
    """Verify command-line arguments and run commands"""
    args = parse_args()
    logging.basicConfig(level=logging.WARN)
    logging.getLogger('kafka').setLevel(logging.CRITICAL)
    if args.controller_only and args.first_broker_only:
        terminate(status_code.WARNING, prepare_terminate_message('Only one of controller_only and first_broker_only should be used'), args.json)
    if args.controller_only or args.first_broker_only:
        if args.broker_id is None:
            terminate(status_code.WARNING, prepare_terminate_message('broker_id is not specified'), args.json)
        elif args.broker_id == -1:
            try:
                args.broker_id = get_broker_id(args.data_path)
            except Exception as e:
                terminate(status_code.WARNING, prepare_terminate_message('{}'.format(e)), args.json)
    try:
        cluster_config = config.get_cluster_config(args.cluster_type, args.cluster_name, args.discovery_base_path)
        code, msg = args.command(cluster_config, args)
    except ConfigurationError as e:
        terminate(status_code.CRITICAL, prepare_terminate_message('ConfigurationError {0}'.format(e)), args.json)
    terminate(code, msg, args.json)

def exception_logger(exc_type, exc_value, exc_traceback):
    """Log unhandled exceptions"""
    if not issubclass(exc_type, KeyboardInterrupt):
        _log.critical('Uncaught exception:', exc_info=(exc_type, exc_value, exc_traceback))
    sys.__excepthook__(exc_type, exc_value, exc_traceback)

def _find_topics_with_wrong_rp(topics, zk, default_min_isr):
    """Returns topics with wrong replication factor."""
    topics_with_wrong_rf = []
    for topic_name, partitions in topics.items():
        min_isr = get_min_isr(zk, topic_name) or default_min_isr
        replication_factor = len(partitions[0].replicas)
        if replication_factor >= min_isr + 1:
            continue
        topics_with_wrong_rf.append({'replication_factor': replication_factor, 'min_isr': min_isr, 'topic': topic_name})
    return topics_with_wrong_rf

def _prepare_output(topics_with_wrong_rf, verbose):
    """Returns dict with 'raw' and 'message' keys filled."""
    out = {}
    topics_count = len(topics_with_wrong_rf)
    out['raw'] = {'topics_with_wrong_replication_factor_count': topics_count}
    if topics_count == 0:
        out['message'] = 'All topics have proper replication factor.'
    else:
        out['message'] = '{0} topic(s) have replication factor lower than specified min ISR + 1.'.format(topics_count)
        if verbose:
            lines = ('replication_factor={replication_factor} is lower than min_isr={min_isr} + 1 for {topic}'.format(min_isr=topic['min_isr'], topic=topic['topic'], replication_factor=topic['replication_factor']) for topic in topics_with_wrong_rf)
            out['verbose'] = 'Topics:\n' + '\n'.join(lines)
    if verbose:
        out['raw']['topics'] = topics_with_wrong_rf
    return out

def parse_args():
    """Parse the arguments."""
    parser = argparse.ArgumentParser(description='Show available clusters.')
    parser.add_argument('-v', '--version', action='version', version='%(prog)s {0}'.format(__version__))
    parser.add_argument('--discovery-base-path', dest='discovery_base_path', type=str, help='Path of the directory containing the <cluster_type>.yaml config. Default try: $KAFKA_DISCOVERY_DIR, $HOME/.kafka_discovery, /etc/kafka_discovery')
    return parser.parse_args()

def _prepare_output(partitions, unavailable_brokers, verbose):
    """Returns dict with 'raw' and 'message' keys filled."""
    partitions_count = len(partitions)
    out = {}
    out['raw'] = {'replica_unavailability_count': partitions_count}
    if partitions_count == 0:
        out['message'] = 'All replicas available for communication.'
    else:
        out['message'] = '{replica_unavailability} replicas unavailable for communication. Unavailable Brokers: {unavailable_brokers}'.format(replica_unavailability=partitions_count, unavailable_brokers=', '.join([str(e) for e in unavailable_brokers]))
        if verbose:
            lines = ('{}:{}'.format(topic, partition) for topic, partition in partitions)
            out['verbose'] = 'Partitions:\n' + '\n'.join(lines)
    if verbose:
        out['raw']['partitions'] = [{'topic': topic, 'partition': partition} for topic, partition in partitions]
    return out

def get_min_isr(zk, topic):
    """Return the min-isr for topic, or None if not specified"""
    ISR_CONF_NAME = 'min.insync.replicas'
    try:
        config = zk.get_topic_config(topic)
    except NoNodeError:
        return None
    if ISR_CONF_NAME in config['config']:
        return int(config['config'][ISR_CONF_NAME])
    else:
        return None

def _process_metadata_response(topics, zk, default_min_isr):
    """Returns not in sync partitions."""
    not_in_sync_partitions = []
    for topic_name, partitions in topics.items():
        min_isr = get_min_isr(zk, topic_name) or default_min_isr
        if min_isr is None:
            continue
        for metadata in partitions.values():
            cur_isr = len(metadata.isr)
            if cur_isr < min_isr:
                not_in_sync_partitions.append({'isr': cur_isr, 'min_isr': min_isr, 'topic': metadata.topic, 'partition': metadata.partition})
    return not_in_sync_partitions

def _prepare_output(partitions, verbose):
