def find_files_cmd(data_path, minutes, start_time, end_time):
    """Find the log files depending on their modification time.

    :param data_path: the path to the Kafka data directory
    :type data_path: str
    :param minutes: check the files modified in the last N minutes
    :type minutes: int
    :param start_time: check the files modified after start_time
    :type start_time: str
    :param end_time: check the files modified before end_time
    :type end_time: str
    :returns: the find command
    :rtype: str"""
    if minutes:
        return FIND_MINUTES_COMMAND.format(data_path=data_path, minutes=minutes)
    if start_time:
        if end_time:
            return FIND_RANGE_COMMAND.format(data_path=data_path, start_time=start_time, end_time=end_time)
        else:
            return FIND_START_COMMAND.format(data_path=data_path, start_time=start_time)

def parse_output(host, output):
    """Parse the output of the dump tool and print warnings or error messages
    accordingly.

    :param host: the source
    :type host: str
    :param output: the output of the script on host
    :type output: list of str"""
    current_file = None
    for line in output.readlines():
        file_name_search = FILE_PATH_REGEX.search(line)
        if file_name_search:
            current_file = file_name_search.group(1)
            continue
        if INVALID_MESSAGE_REGEX.match(line) or INVALID_BYTES_REGEX.match(line):
            print_line(host, current_file, line, 'ERROR')
        elif VALID_MESSAGE_REGEX.match(line) or line.startswith('Starting offset:'):
            continue
        else:
            print_line(host, current_file, line, 'UNEXPECTED OUTPUT')

def merge_result(res):
    """Merge all items in `res` into a list.

    This command is used when sending a command to multiple nodes
    and they result from each node should be merged into a single list."""
    if not isinstance(res, dict):
        raise ValueError('Value should be of dict type')
    result = set([])
    for _, v in res.items():
        for value in v:
            result.add(value)
    return list(result)

def first_key(res):
    """Returns the first result for the given command.

    If more then 1 result is returned then a `RedisClusterException` is raised."""
    if not isinstance(res, dict):
        raise ValueError('Value should be of dict type')
    if len(res.keys()) != 1:
        raise RedisClusterException('More then 1 result from command')
    return list(res.values())[0]

def clusterdown_wrapper(func):
    """Wrapper for CLUSTERDOWN error handling.

    If the cluster reports it is down it is assumed that:
     - connection_pool was disconnected
     - connection_pool was reseted
     - refereh_table_asap set to True

    It will try 3 times to rerun the command and raises ClusterDownException if it continues to fail."""
    @wraps(func)
    async def inner(*args, **kwargs):
        for _ in range(0, 3):
            try:
                return await func(*args, **kwargs)
            except ClusterDownError:
                pass
        raise ClusterDownError('CLUSTERDOWN error. Unable to rebuild the cluster')
    return inner

def parse_debug_object(response):
    """Parse the results of Redis's DEBUG OBJECT command into a Python dict"""
    response = nativestr(response)
    response = 'type:' + response
    response = dict([kv.split(':') for kv in response.split()])
    int_fields = ('refcount', 'serializedlength', 'lru', 'lru_seconds_idle')
    for field in int_fields:
        if field in response:
            response[field] = int(response[field])
    return response

def parse_info(response):
    """Parse the result of Redis's INFO command into a Python dict"""
    info = {}
    response = nativestr(response)
    def get_value(value):
        if ',' not in value or '=' not in value:
            try:
                if '.' in value:
                    return float(value)
                else:
                    return int(value)
            except ValueError:
                return value
        else:
            sub_dict = {}
            for item in value.split(','):
                k, v = item.rsplit('=', 1)
                sub_dict[k] = get_value(v)
            return sub_dict
    for line in response.splitlines():
        if line and (not line.startswith('#')):
            if line.find(':') != -1:
                key, value = line.split(':', 1)
                info[key] = get_value(value)
            else:
                info.setdefault('__raw__', []).append(line)
    return info

def parse_cluster_pubsub_channels(res, **options):
    """Result callback, handles different return types
    switchable by the `aggregate` flag."""
    aggregate = options.get('aggregate', True)
    if not aggregate:
        return res
    return merge_result(res)

def parse_cluster_pubsub_numpat(res, **options):
    """Result callback, handles different return types
    switchable by the `aggregate` flag."""
    aggregate = options.get('aggregate', True)
    if not aggregate:
        return res
    numpat = 0
    for node, node_numpat in res.items():
        numpat += node_numpat
    return numpat

def parse_cluster_pubsub_numsub(res, **options):
    """Result callback, handles different return types
    switchable by the `aggregate` flag."""
    aggregate = options.get('aggregate', True)
    if not aggregate:
        return res
    numsub_d = dict()
    for _, numsub_tups in res.items():
        for channel, numsubbed in numsub_tups:
            try:
                numsub_d[channel] += numsubbed
            except KeyError:
                numsub_d[channel] = numsubbed
    ret_numsub = []
    for channel, numsub in numsub_d.items():
        ret_numsub.append((channel, numsub))
    return ret_numsub

def block_pipeline_command(func):
    """Prints error because some pipelined commands should be blocked when running in cluster-mode"""
    def inner(*args, **kwargs):
        raise RedisClusterException('ERROR: Calling pipelined function {0} is blocked when running redis in cluster mode...'.format(func.__name__))
    return inner

def zset_score_pairs(response, **options):
    """If ``withscores`` is specified in the options, return the response as
    a list of (value, score) pairs"""
    if not response or not options['withscores']:
        return response
    score_cast_func = options.get('score_cast_func', float)
    it = iter(response)
    return list(zip(it, map(score_cast_func, it)))

def sort_return_tuples(response, **options):
    """If ``groups`` is specified, return the response as a list of
    n-element tuples with n being the value found in options['groups']"""
    if not response or not options['groups']:
        return response
    n = options['groups']
    return list(zip(*[response[i::n] for i in range(n)]))

def get_long_docs(*filenames):
    """Build rst description from a set of files."""
    docs = []
    for filename in filenames:
        with open(filename, 'r') as f:
            docs.append(f.read())
    return '\n\n'.join(docs)

def centerize(src, dst_shape, margin_color=None):
    """Centerize image for specified image size

    @param src: image to centerize
    @param dst_shape: image shape (height, width) or (height, width, channel)"""
    if src.shape[:2] == dst_shape[:2]:
        return src
    centerized = np.zeros(dst_shape, dtype=src.dtype)
    if margin_color:
        centerized[:, :] = margin_color
    pad_vertical, pad_horizontal = (0, 0)
    h, w = src.shape[:2]
    dst_h, dst_w = dst_shape[:2]
    if h < dst_h:
        pad_vertical = (dst_h - h) // 2
    if w < dst_w:
        pad_horizontal = (dst_w - w) // 2
    centerized[pad_vertical:pad_vertical + h, pad_horizontal:pad_horizontal + w] = src
    return centerized

def _tile_images(imgs, tile_shape, concatenated_image):
    """Concatenate images whose sizes are same.

    @param imgs: image list which should be concatenated
    @param tile_shape: shape for which images should be concatenated
    @param concatenated_image: returned image.
        if it is None, new image will be created."""
    y_num, x_num = tile_shape
    one_width = imgs[0].shape[1]
    one_height = imgs[0].shape[0]
    if concatenated_image is None:
        if len(imgs[0].shape) == 3:
            n_channels = imgs[0].shape[2]
            assert all((im.shape[2] == n_channels for im in imgs))
            concatenated_image = np.zeros((one_height * y_num, one_width * x_num, n_channels), dtype=np.uint8)
        else:
            concatenated_image = np.zeros((one_height * y_num, one_width * x_num), dtype=np.uint8)
    for y in six.moves.range(y_num):
        for x in six.moves.range(x_num):
            i = x + y * x_num
            if i >= len(imgs):
                pass
            else:
                concatenated_image[y * one_height:(y + 1) * one_height, x * one_width:(x + 1) * one_width] = imgs[i]
    return concatenated_image

def _get_upsampling_filter(size):
    """Make a 2D bilinear kernel suitable for upsampling"""
    factor = (size + 1) // 2
    if size % 2 == 1:
        center = factor - 1
    else:
        center = factor - 0.5
    og = np.ogrid[:size, :size]
    filter = (1 - abs(og[0] - center) / factor) * (1 - abs(og[1] - center) / factor)
    return filter

def unquote_unreserved(uri):
    """Un-escape any percent-escape sequences in a URI that are unreserved
    characters. This leaves all reserved, illegal and non-ASCII bytes encoded.
    :rtype: str"""
    parts = uri.split('%')
    for i in range(1, len(parts)):
        h = parts[i][0:2]
        if len(h) == 2 and h.isalnum():
            try:
                c = chr(int(h, 16))
            except ValueError:
                raise ValueError("Invalid percent-escape sequence: '%s'" % h)
            if c in UNRESERVED_SET:
                parts[i] = c + parts[i][2:]
            else:
                parts[i] = '%' + parts[i]
        else:
            parts[i] = '%' + parts[i]
    return ''.join(parts)

def requote_uri(uri):
    """Re-quote the given URI.
    This function passes the given URI through an unquote/quote cycle to
    ensure that it is fully and consistently quoted.
    :rtype: str"""
    safe_with_percent = "!#$%&'()*+,/:;=?@[]~"
    safe_without_percent = "!#$&'()*+,/:;=?@[]~"
    try:
        return quote(unquote_unreserved(uri), safe=safe_with_percent)
    except ValueError:
        return quote(uri, safe=safe_without_percent)

def parse_cookies(response, host):
    """Sticks cookies to a response."""
    cookie_pie = []
    try:
        for cookie in response.headers['set-cookie']:
            cookie_jar = {}
            name_val, *rest = cookie.split(';')
            name, value = name_val.split('=', 1)
            cookie_jar['name'] = name.strip()
            cookie_jar['value'] = value
            for item in rest:
                try:
                    name, value = item.split('=')
                    if value.startswith('.'):
                        value = value[1:]
                    cookie_jar[name.lower().lstrip()] = value
                except ValueError:
                    cookie_jar[item.lower().lstrip()] = True
            cookie_pie.append(cookie_jar)
        response.cookies = [Cookie(host, x) for x in cookie_pie]
    except KeyError:
        pass

