def mss(**kwargs):
    """Factory returning a proper MSS class instance.

    It detects the plateform we are running on
    and choose the most adapted mss_class to take
    screenshots.

    It then proxies its arguments to the class for
    instantiation."""
    os_ = platform.system().lower()
    if os_ == 'darwin':
        from . import darwin
        return darwin.MSS(**kwargs)
    if os_ == 'linux':
        from . import linux
        return linux.MSS(**kwargs)
    if os_ == 'windows':
        from . import windows
        return windows.MSS(**kwargs)
    raise ScreenShotError('System {!r} not (yet?) implemented.'.format(os_))

def _hue2rgb(v1, v2, vH):
    """Private helper function (Do not call directly)

    :param vH: rotation around the chromatic circle (between 0..1)"""
    while vH < 0:
        vH += 1
    while vH > 1:
        vH -= 1
    if 6 * vH < 1:
        return v1 + (v2 - v1) * 6 * vH
    if 2 * vH < 1:
        return v2
    if 3 * vH < 2:
        return v1 + (v2 - v1) * (2.0 / 3 - vH) * 6
    return v1

