def profile(ctx, filepath, calltree=False):
    """Run and profile a given Python script.

    :param str filepath: The filepath of the script to profile"""
    filepath = pathlib.Path(filepath)
    if not filepath.is_file():
        log('profile', f'no such script {filepath!s}', LogLevel.ERROR)
    elif calltree:
        log('profile', f'profiling script {filepath!s} calltree')
        ctx.run(f'python -m cProfile -o .profile.cprof {filepath!s} && pyprof2calltree -k -i .profile.cprof && rm -rf .profile.cprof')
    else:
        log('profile', f'profiling script {filepath!s}')
        ctx.run(f'vprof -c cmhp {filepath!s}')

def _strip_marker_elem(elem_name, elements):
    """Remove the supplied element from the marker.

    This is not a comprehensive implementation, but relies on an important
    characteristic of metadata generation: The element's operand is always
    associated with an "and" operator. This means that we can simply remove the
    operand and the "and" operator associated with it."""
    extra_indexes = []
    preceding_operators = ['and'] if elem_name == 'extra' else ['and', 'or']
    for i, element in enumerate(elements):
        if isinstance(element, list):
            cancelled = _strip_marker_elem(elem_name, element)
            if cancelled:
                extra_indexes.append(i)
        elif isinstance(element, tuple) and element[0].value == elem_name:
            extra_indexes.append(i)
    for i in reversed(extra_indexes):
        del elements[i]
        if i > 0 and elements[i - 1] in preceding_operators:
            del elements[i - 1]
        elif elements:
            del elements[0]
    return not elements

def _get_stripped_marker(marker, strip_func):
    """Build a new marker which is cleaned according to `strip_func`"""
    if not marker:
        return None
    marker = _ensure_marker(marker)
    elements = marker._markers
    strip_func(elements)
    if elements:
        return marker
    return None

def get_contained_extras(marker):
    """Collect "extra == ..." operands from a marker.

    Returns a list of str. Each str is a speficied extra in this marker."""
    if not marker:
        return set()
    extras = set()
    marker = _ensure_marker(marker)
    _markers_collect_extras(marker._markers, extras)
    return extras

def get_contained_pyversions(marker):
    """Collect all `python_version` operands from a marker.
    """
    collection = []
    if not marker:
        return set()
    marker = _ensure_marker(marker)
    _markers_collect_pyversions(marker._markers, collection)
    marker_str = ' and '.join(sorted(collection))
    if not marker_str:
        return set()
    marker_dict = distlib.markers.parse_marker(marker_str)[0]
    version_set = set()
    pyversions, _ = parse_marker_dict(marker_dict)
    if isinstance(pyversions, set):
        version_set.update(pyversions)
    elif pyversions is not None:
        version_set.add(pyversions)
    versions = set()
    if version_set:
        versions = reduce(lambda x, y: x & y, version_set)
    return versions

def contains_extra(marker):
    """Check whehter a marker contains an "extra == ..." operand.
    """
    if not marker:
        return False
    marker = _ensure_marker(marker)
    return _markers_contains_extra(marker._markers)

def contains_pyversion(marker):
    """Check whether a marker contains a python_version operand.
    """
    if not marker:
        return False
    marker = _ensure_marker(marker)
    return _markers_contains_pyversion(marker._markers)

def rewrite_file_imports(item, vendored_libs, vendor_dir):
    """Rewrite 'import xxx' and 'from xxx import' for vendored_libs"""
    text = item.read_text(encoding='utf-8')
    renames = LIBRARY_RENAMES
    for k in LIBRARY_RENAMES.keys():
        if k not in vendored_libs:
            vendored_libs.append(k)
    for lib in vendored_libs:
        to_lib = lib
        if lib in renames:
            to_lib = renames[lib]
        text = re.sub('([\\n\\s]*)import %s([\\n\\s\\.]+)' % lib, '\\1import %s\\2' % to_lib, text)
        text = re.sub('([\\n\\s]*)from %s([\\s\\.])+' % lib, '\\1from %s\\2' % to_lib, text)
        text = re.sub("(\\n\\s*)__import__\\('%s([\\s'\\.])+" % lib, "\\1__import__('%s\\2" % to_lib, text)
    item.write_text(text, encoding='utf-8')

def round_figures(x, n):
    """Returns x rounded to n significant figures."""
    return round(x, int(n - math.ceil(math.log10(abs(x)))))

def diff_trees(left, right, diff_options=None, formatter=None):
    """Takes two lxml root elements or element trees"""
    if formatter is not None:
        formatter.prepare(left, right)
    if diff_options is None:
        diff_options = {}
    differ = diff.Differ(**diff_options)
    diffs = differ.diff(left, right)
    if formatter is None:
        return list(diffs)
    return formatter.format(diffs, left)

def diff_texts(left, right, diff_options=None, formatter=None):
    """Takes two Unicode strings containing XML"""
    return _diff(etree.fromstring, left, right, diff_options=diff_options, formatter=formatter)

def patch_tree(actions, tree):
    """Takes an lxml root element or element tree, and a list of actions"""
    patcher = patch.Patcher()
    return patcher.patch(actions, tree)

def patch_text(actions, tree):
    """Takes a string with XML and a string with actions"""
    tree = etree.fromstring(tree)
    actions = patch.DiffParser().parse(actions)
    tree = patch_tree(actions, tree)
    return etree.tounicode(tree)

def patch_file(actions, tree):
    """Takes two filenames or streams, one with XML the other a diff"""
    tree = etree.parse(tree)
    if isinstance(actions, six.string_types):
        with open(actions) as f:
            actions = f.read()
    else:
        actions = actions.read()
    actions = patch.DiffParser().parse(actions)
    tree = patch_tree(actions, tree)
    return etree.tounicode(tree)

