def is_valid_interval(interval):
    """Checks if the given interval is valid. A valid interval
    is always a positive, non-zero integer value."""
    if not isinstance(interval, (int, long)):
        return False
    if interval <= 0:
        return False
    return True

def is_valid_requeue_limit(requeue_limit):
    """Checks if the given requeue limit is valid.
    A valid requeue limit is always greater than
    or equal to -1."""
    if not isinstance(requeue_limit, (int, long)):
        return False
    if requeue_limit <= -2:
        return False
    return True

def get_search_names(name):
    """Return a list of values to search on when we are looking for a package
    with the given name.

    This is required to search on both pyramid_debugtoolbar and
    pyramid-debugtoolbar."""
    parts = re.split('[-_.]', name)
    if len(parts) == 1:
        return parts
    result = set()
    for i in range(len(parts) - 1, 0, -1):
        for s1 in '-_.':
            prefix = s1.join(parts[:i])
            for s2 in '-_.':
                suffix = s2.join(parts[i:])
                for s3 in '-_.':
                    result.add(s3.join([prefix, suffix]))
    return list(result)

def delete_files(sender, **kwargs):
    """Signal callback for deleting old files when database item is deleted"""
    instance = kwargs['instance']
    if not hasattr(instance.distribution, 'path'):
        return
    if not os.path.exists(instance.distribution.path):
        return
    is_referenced = instance.__class__.objects.filter(distribution=instance.distribution).exclude(pk=instance._get_pk_val()).exists()
    if is_referenced:
        return
    try:
        instance.distribution.storage.delete(instance.distribution.path)
    except Exception:
        logger.exception('Error when trying to delete file %s of package %s:' % (instance.pk, instance.distribution.path))

def md5_hash_file(fh):
    """Return the md5 hash of the given file-object"""
    md5 = hashlib.md5()
    while True:
        data = fh.read(8192)
        if not data:
            break
        md5.update(data)
    return md5.hexdigest()

def get_versio_versioning_scheme(full_class_path):
    """Return a class based on it's full path"""
    module_path = '.'.join(full_class_path.split('.')[0:-1])
    class_name = full_class_path.split('.')[-1]
    try:
        module = importlib.import_module(module_path)
    except ImportError:
        raise RuntimeError('Invalid specified Versio schema {}'.format(full_class_path))
    try:
        return getattr(module, class_name)
    except AttributeError:
        raise RuntimeError('Could not find Versio schema class {!r} inside {!r} module.'.format(class_name, module_path))

def credentials_required(view_func):
    """This decorator should be used with views that need simple authentication
    against Django's authentication framework."""
    @wraps(view_func, assigned=available_attrs(view_func))
    def decorator(request, *args, **kwargs):
        if settings.LOCALSHOP_USE_PROXIED_IP:
            try:
                ip_addr = request.META['HTTP_X_FORWARDED_FOR']
            except KeyError:
                return HttpResponseForbidden('No permission')
            else:
                ip_addr = ip_addr.split(',')[0].strip()
        else:
            ip_addr = request.META['REMOTE_ADDR']
        if CIDR.objects.has_access(ip_addr, with_credentials=False):
            return view_func(request, *args, **kwargs)
        if not CIDR.objects.has_access(ip_addr, with_credentials=True):
            return HttpResponseForbidden('No permission')
        if request.user.is_authenticated():
            return view_func(request, *args, **kwargs)
        user = authenticate_user(request)
        if user is not None:
            login(request, user)
            return view_func(request, *args, **kwargs)
        return HttpResponseUnauthorized(content='Authorization Required')
    return decorator

def no_duplicates(function, *args, **kwargs):
    """Makes sure that no duplicated tasks are enqueued."""
    @wraps(function)
    def wrapper(self, *args, **kwargs):
        key = generate_key(function, *args, **kwargs)
        try:
            function(self, *args, **kwargs)
        finally:
            logging.info('Removing key %s', key)
            cache.delete(key)
    return wrapper

def dispatch_queue(loader):
    """Given the current state of a Loader instance, perform a batch load
    from its current queue."""
    queue = loader._queue
    loader._queue = []
    max_batch_size = loader.max_batch_size
    if max_batch_size and max_batch_size < len(queue):
        chunks = get_chunks(queue, max_batch_size)
        for chunk in chunks:
            dispatch_queue_batch(loader, chunk)
    else:
        dispatch_queue_batch(loader, queue)

def failed_dispatch(loader, queue, error):
    """Do not cache individual loads if the entire batch dispatch fails,
    but still reject each request so they do not hang."""
    for l in queue:
        loader.clear(l.key)
        l.reject(error)

def get_complete_version(version=None):
    """Returns a tuple of the promise version. If version argument is non-empty,
    then checks for correctness of the tuple provided."""
    if version is None:
        from promise import VERSION
        return VERSION
    else:
        assert len(version) == 5
        assert version[3] in ('alpha', 'beta', 'rc', 'final')
    return version

def dependencies(project_name):
    """Get the dependencies for a project."""
    log = logging.getLogger('ciu')
    log.info('Locating dependencies for {}'.format(project_name))
    located = distlib.locators.locate(project_name, prereleases=True)
    if not located:
        log.warning('{0} not found'.format(project_name))
        return None
    return {packaging.utils.canonicalize_name(pypi.just_name(dep)) for dep in located.run_requires}

def projects_from_requirements(requirements):
    """Extract the project dependencies from a Requirements specification."""
    log = logging.getLogger('ciu')
    valid_reqs = []
    for requirements_path in requirements:
        with io.open(requirements_path) as file:
            requirements_text = file.read()
        requirements_text = re.sub('\\\\s*', '', requirements_text)
        requirements_text = re.sub('#.*', '', requirements_text)
        reqs = []
        for line in requirements_text.splitlines():
            if not line:
                continue
            try:
                reqs.append(packaging.requirements.Requirement(line))
            except packaging.requirements.InvalidRequirement:
                log.warning('Skipping {0!r}: could not parse requirement'.format(line))
        for req in reqs:
            if not req.name:
                log.warning('A requirement lacks a name (e.g. no `#egg` on a `file:` path)')
            elif req.url:
                log.warning('Skipping {0}: URL-specified projects unsupported'.format(req.name))
            else:
                valid_reqs.append(req.name)
    return frozenset(map(packaging.utils.canonicalize_name, valid_reqs))

def projects_from_metadata(metadata):
    """Extract the project dependencies from a metadata spec."""
    projects = []
    for data in metadata:
        meta = distlib.metadata.Metadata(fileobj=io.StringIO(data))
        projects.extend((pypi.just_name(project) for project in meta.run_requires))
    return frozenset(map(packaging.utils.canonicalize_name, projects))

def locateOnScreen(image, minSearchTime=0, **kwargs):
    """minSearchTime - amount of time in seconds to repeat taking
    screenshots and trying to locate a match.  The default of 0 performs
    a single search."""
    start = time.time()
    while True:
        try:
            screenshotIm = screenshot(region=None)
            retVal = locate(image, screenshotIm, **kwargs)
            try:
                screenshotIm.fp.close()
            except AttributeError:
                pass
            if retVal or time.time() - start > minSearchTime:
                return retVal
        except ImageNotFoundException:
            if time.time() - start > minSearchTime:
                if USE_IMAGE_NOT_FOUND_EXCEPTION:
                    raise
                else:
                    return None

def normalize_url(url: 'Union[URL, str]') -> 'URL':
    """Normalize url to make comparisons."""
    url = URL(url)
    return url.with_query(urlencode(sorted(parse_qsl(url.query_string))))

def normalize_url(node):
    """Normalizes the given node url"""
    if not node:
        node = DEFAULT_NODE
    elif '://' not in node:
        node = '//{}'.format(node)
    parts = urlparse(node, scheme='http', allow_fragments=False)
    port = parts.port if parts.port else _get_default_port(parts.scheme)
    netloc = '{}:{}'.format(parts.hostname, port)
    return urlunparse((parts.scheme, netloc, parts.path, '', '', ''))

def normalize_node(node, headers=None):
    """Normalizes given node as str or dict with headers"""
    headers = {} if headers is None else headers
    if isinstance(node, str):
        url = normalize_url(node)
        return {'endpoint': url, 'headers': headers}
    url = normalize_url(node['endpoint'])
    node_headers = node.get('headers', {})
    return {'endpoint': url, 'headers': {**headers, **node_headers}}

def normalize_nodes(*nodes, headers=None):
    """Normalizes given dict or array of driver nodes"""
    if not nodes:
        return (normalize_node(DEFAULT_NODE, headers),)
    normalized_nodes = ()
    for node in nodes:
        normalized_nodes += (normalize_node(node, headers),)
    return normalized_nodes

def dict2query(dictionary):
    """We want post vars of form:
    {'foo': 'bar', 'nested': {'a': 'b', 'c': 'd'}}
    to become:
    foo=bar&nested[a]=b&nested[c]=d"""
    query = []
    encoders = {dict: _dictionary_encoder}
    for k, v in dictionary.iteritems():
        if v.__class__ in encoders:
            nested_query = encoders[v.__class__](k, v)
            query += nested_query
        else:
            key = to_utf8(k)
            value = to_utf8(v)
            query.append('{}={}'.format(key, value))
    return '&'.join(query)

