def intercept(work_db):
    """Look for WorkItems in `work_db` that should not be mutated due to spor metadata.

    For each WorkItem, find anchors for the item's file/line/columns. If an
    anchor exists with metadata containing `{mutate: False}` then the WorkItem
    is marked as SKIPPED."""
    @lru_cache()
    def file_contents(file_path):
        """A simple cache of file contents."""
        with file_path.open(mode='rt') as handle:
            return handle.readlines()
    for item in work_db.work_items:
        try:
            repo = open_repository(item.module_path)
        except ValueError:
            log.info('No spor repository for %s', item.module_path)
            continue
        for _, anchor in repo.items():
            if anchor.file_path != item.module_path.absolute():
                continue
            metadata = anchor.metadata
            lines = file_contents(item.module_path)
            if _item_in_context(lines, item, anchor.context) and (not metadata.get('mutate', True)):
                log.info('spor skipping %s %s %s %s %s %s', item.job_id, item.operator_name, item.occurrence, item.module_path, item.start_pos, item.end_pos)
                work_db.set_result(item.job_id, WorkResult(output=None, test_outcome=None, diff=None, worker_outcome=WorkerOutcome.SKIPPED))

def get_tu(source, lang='c', all_warnings=False, flags=None):
    """Obtain a translation unit from source and language.

    By default, the translation unit is created from source file "t.<ext>"
    where <ext> is the default file extension for the specified language. By
    default it is C, so "t.c" is the default file name.

    Supported languages are {c, cpp, objc}.

    all_warnings is a convenience argument to enable all compiler warnings."""
    args = list(flags or [])
    name = 't.c'
    if lang == 'cpp':
        name = 't.cpp'
        args.append('-std=c++11')
    elif lang == 'objc':
        name = 't.m'
    elif lang != 'c':
        raise Exception('Unknown language: %s' % lang)
    if all_warnings:
        args += ['-Wall', '-Wextra']
    return TranslationUnit.from_source(name, args, unsaved_files=[(name, source)])

def get_cursor(source, spelling):
    """Obtain a cursor from a source object.

    This provides a convenient search mechanism to find a cursor with specific
    spelling within a source. The first argument can be either a
    TranslationUnit or Cursor instance.

    If the cursor is not found, None is returned."""
    children = []
    if isinstance(source, Cursor):
        children = source.get_children()
    else:
        children = source.cursor.get_children()
    for cursor in children:
        if cursor.spelling == spelling:
            return cursor
        result = get_cursor(cursor, spelling)
        if result is not None:
            return result
    return None

def _shtools_status_message(status):
    """Determine error message to print when a SHTOOLS Fortran 95 routine exits
    improperly."""
    if status == 1:
        errmsg = 'Improper dimensions of input array.'
    elif status == 2:
        errmsg = 'Improper bounds for input variable.'
    elif status == 3:
        errmsg = 'Error allocating memory.'
    elif status == 4:
        errmsg = 'File IO error.'
    else:
        errmsg = 'Unhandled Fortran 95 error.'
    return errmsg

def _iscomment(line):
    """Determine if a line is a comment line. A valid line contains at least three
    words, with the first two being integers. Note that Python 2 and 3 deal
    with strings differently."""
    if line.isspace():
        return True
    elif len(line.split()) >= 3:
        try:
            if line.split()[0].isdecimal() and line.split()[1].isdecimal():
                return False
        except:
            if line.decode().split()[0].isdecimal() and line.split()[1].decode().isdecimal():
                return False
        return True
    else:
        return True

def get_compiler_flags():
