def expand_path(path):
    """Given a compressed path, return a new path that has all the segments
    in it interpolated."""
    expanded = []
    if len(path) < 2:
        return expanded
    for i in range(len(path) - 1):
        expanded += bresenham(path[i], path[i + 1])
    expanded += [path[:-1]]
    return expanded

