def _lstree(files, dirs):
    """Make git ls-tree like output."""
    for f, sha1 in files:
        yield '100644 blob {}\t{}\x00'.format(sha1, f)
    for d, sha1 in dirs:
        yield '040000 tree {}\t{}\x00'.format(sha1, d)

def hash_dir(path):
    """Write directory at path to Git index, return its SHA1 as a string."""
    dir_hash = {}
    for root, dirs, files in os.walk(path, topdown=False):
        f_hash = ((f, hash_file(join(root, f))) for f in files)
        d_hash = ((d, dir_hash[join(root, d)]) for d in dirs)
        dir_hash[join(*split(root))] = _mktree(f_hash, d_hash)
    return dir_hash[path]

def features(sentence, i):
    """Features for i'th token in sentence.

    Currently baseline named-entity recognition features, but these can
    easily be changed to do POS tagging or chunking."""
    word = sentence[i]
    yield ('word:{}' + word.lower())
    if word[0].isupper():
        yield 'CAP'
    if i > 0:
        yield ('word-1:{}' + sentence[i - 1].lower())
        if i > 1:
            yield ('word-2:{}' + sentence[i - 2].lower())
    if i + 1 < len(sentence):
        yield ('word+1:{}' + sentence[i + 1].lower())
        if i + 2 < len(sentence):
            yield ('word+2:{}' + sentence[i + 2].lower())

def whole_sequence_accuracy(y_true, y_pred, lengths):
    """Average accuracy measured on whole sequences.

    Returns the fraction of sequences in y_true that occur in y_pred without a
    single error."""
    lengths = np.asarray(lengths)
    end = np.cumsum(lengths)
    start = end - lengths
    bounds = np.vstack([start, end]).T
    errors = sum((1.0 for i, j in bounds if np.any(y_true[i:j] != y_pred[i:j])))
    return 1 - errors / len(lengths)

def array2d(X, dtype=None, order=None, copy=False):
    """Returns at least 2-d array with data from X"""
    if sp.issparse(X):
        raise TypeError('A sparse matrix was passed, but dense data is required. Use X.toarray() to convert to dense.')
    X_2d = np.asarray(np.atleast_2d(X), dtype=dtype, order=order)
    _assert_all_finite(X_2d)
    if X is X_2d and copy:
        X_2d = safe_copy(X_2d)
    return X_2d

def atleast2d_or_csr(X, dtype=None, order=None, copy=False):
    """Like numpy.atleast_2d, but converts sparse matrices to CSR format

    Also, converts np.matrix to np.ndarray."""
    return _atleast2d_or_sparse(X, dtype, order, copy, sp.csr_matrix, 'tocsr', sp.isspmatrix_csr)

