def find_isolated_tile_indices(hand_34):
    """Tiles that don't have -1, 0 and +1 neighbors
    :param hand_34: array of tiles in 34 tile format
    :return: array of isolated tiles indices"""
    isolated_indices = []
    for x in range(0, CHUN + 1):
        if is_honor(x) and hand_34[x] == 0:
            isolated_indices.append(x)
        else:
            simplified = simplify(x)
            if simplified == 0:
                if hand_34[x] == 0 and hand_34[x + 1] == 0:
                    isolated_indices.append(x)
            elif simplified == 8:
                if hand_34[x] == 0 and hand_34[x - 1] == 0:
                    isolated_indices.append(x)
            elif hand_34[x] == 0 and hand_34[x - 1] == 0 and (hand_34[x + 1] == 0):
                isolated_indices.append(x)
    return isolated_indices

def is_tile_strictly_isolated(hand_34, tile_34):
    """Tile is strictly isolated if it doesn't have -2, -1, 0, +1, +2 neighbors
    :param hand_34: array of tiles in 34 tile format
    :param tile_34: int
    :return: bool"""
    hand_34 = copy.copy(hand_34)
    hand_34[tile_34] -= 1
    if hand_34[tile_34] < 0:
        hand_34[tile_34] = 0
    indices = []
    if is_honor(tile_34):
        return hand_34[tile_34] == 0
    else:
        simplified = simplify(tile_34)
        if simplified == 0:
            indices = [tile_34, tile_34 + 1, tile_34 + 2]
        elif simplified == 1:
            indices = [tile_34 - 1, tile_34, tile_34 + 1, tile_34 + 2]
        elif simplified == 7:
            indices = [tile_34 - 2, tile_34 - 1, tile_34, tile_34 + 1]
        elif simplified == 8:
            indices = [tile_34 - 2, tile_34 - 1, tile_34]
        else:
            indices = [tile_34 - 2, tile_34 - 1, tile_34, tile_34 + 1, tile_34 + 2]
    return all([hand_34[x] == 0 for x in indices])

def count_tiles_by_suits(tiles_34):
    """Separate tiles by suits and count them
    :param tiles_34: array of tiles to count
    :return: dict"""
    suits = [{'count': 0, 'name': 'sou', 'function': is_sou}, {'count': 0, 'name': 'man', 'function': is_man}, {'count': 0, 'name': 'pin', 'function': is_pin}, {'count': 0, 'name': 'honor', 'function': is_honor}]
    for x in range(0, 34):
        tile = tiles_34[x]
        if not tile:
            continue
        for item in suits:
            if item['function'](x):
                item['count'] += tile
    return suits

def _rolling_lstsq(x, y):
    """Finds solution for the rolling case.  Matrix formulation."""
    if x.ndim == 2:
        x = x[:, :, None]
    elif x.ndim <= 1:
        raise np.AxisError('x should have ndmi >= 2')
    return np.squeeze(np.matmul(np.linalg.inv(np.matmul(x.swapaxes(1, 2), x)), np.matmul(x.swapaxes(1, 2), np.atleast_3d(y))))

def _confirm_constant(a):
    """Confirm `a` has volumn vector of 1s."""
    a = np.asanyarray(a)
    return np.isclose(a, 1.0).all(axis=0).any()

def _check_constant_params(a, has_const=False, use_const=True, rtol=1e-05, atol=1e-08):
    """Helper func to interaction between has_const and use_const params.

    has_const   use_const   outcome
    ---------   ---------   -------
    True        True        Confirm that a has constant; return a
    False       False       Confirm that a doesn't have constant; return a
    False       True        Confirm that a doesn't have constant; add constant
    True        False       ValueError"""
    if all((has_const, use_const)):
        if not _confirm_constant(a):
            raise ValueError('Data does not contain a constant; specify has_const=False')
        k = a.shape[-1] - 1
    elif not any((has_const, use_const)):
        if _confirm_constant(a):
            raise ValueError('Data already contains a constant; specify has_const=True')
        k = a.shape[-1]
    elif not has_const and use_const:
        c1 = np.allclose(a.mean(axis=0), b=0.0, rtol=rtol, atol=atol)
        c2 = np.allclose(a.std(axis=0), b=1.0, rtol=rtol, atol=atol)
        if c1 and c2:
            raise ValueError('Data appears to be ~N(0,1).  Specify use_constant=False.')
        try:
            a = add_constant(a, has_constant='raise')
        except ValueError as e:
            raise ValueError('X data already contains a constant; please specify has_const=True') from e
        k = a.shape[-1] - 1
    else:
        raise ValueError('`use_const` == False implies has_const is False.')
    return (k, a)

def ewm_params(param, param_value):
    """Corresponding parameter values for exponentially weighted functions.

    Parameters
    ----------
    param : {'alpha', 'com', 'span', 'halflife'}
    param_value : float or int
        The parameter value.

    Returns
    -------
    result : dict
        Layout/index of corresponding parameters."""
    if param not in ['alpha', 'com', 'span', 'halflife']:
        raise NameError('`param` must be one of {alpha, com, span, halflife}')
    def input_alpha(a):
        com = 1.0 / a - 1.0
        span = 2.0 / a - 1.0
        halflife = np.log(0.5) / np.log(1.0 - a)
        return {'com': com, 'span': span, 'halflife': halflife}
    def output_alpha(param, p):
        eqs = {'com': 1.0 / (1.0 + p), 'span': 2.0 / (p + 1.0), 'halflife': 1.0 - np.exp(np.log(0.5) / p)}
        return eqs[param]
    if param == 'alpha':
        dct = input_alpha(a=param_value)
        alpha = param_value
    else:
        alpha = output_alpha(param=param, p=param_value)
        dct = input_alpha(a=alpha)
    dct.update({'alpha': alpha})
    return dct

def _try_to_squeeze(obj, raise_=False):
    """Attempt to squeeze to 1d Series.

    Parameters
    ----------
    obj : {pd.Series, pd.DataFrame}
    raise_ : bool, default False"""
    if isinstance(obj, pd.Series):
        return obj
    elif isinstance(obj, pd.DataFrame) and obj.shape[-1] == 1:
        return obj.squeeze()
    else:
        if raise_:
            raise ValueError('Input cannot be squeezed.')
        return obj

def _uniquewords(*args):
    """Dictionary of words to their indices.  Helper function to `encode.`"""
    words = {}
    n = 0
    for word in itertools.chain(*args):
        if word not in words:
            words[word] = n
            n += 1
    return words

def superReadCSV(filepath, first_codec='UTF_8', usecols=None, low_memory=False, dtype=None, parse_dates=True, sep=',', chunksize=None, verbose=False, **kwargs):
    """A wrap to pandas read_csv with mods to accept a dataframe or
    filepath. returns dataframe untouched, reads filepath and returns
    dataframe based on arguments."""
    if isinstance(filepath, pd.DataFrame):
        return filepath
    assert isinstance(first_codec, str), 'first_codec must be a string'
    codecs = ['UTF_8', 'ISO-8859-1', 'ASCII', 'UTF_16', 'UTF_32']
    try:
        codecs.remove(first_codec)
    except ValueError as not_in_list:
        pass
    codecs.insert(0, first_codec)
    errors = []
    for c in codecs:
        try:
            return pd.read_csv(filepath, usecols=usecols, low_memory=low_memory, encoding=c, dtype=dtype, parse_dates=parse_dates, sep=sep, chunksize=chunksize, **kwargs)
        except (UnicodeError, UnboundLocalError) as e:
            errors.append(e)
        except Exception as e:
            errors.append(e)
            if 'tokenizing' in str(e):
                pass
            else:
                raise
    if verbose:
        [print(e) for e in errors]
    raise UnicodeDecodeError('Tried {} codecs and failed on all: \n CODECS: {} \n FILENAME: {}'.format(len(codecs), codecs, os.path.basename(filepath)))

def identify_sep(filepath):
    """Identifies the separator of data in a filepath.
    It reads the first line of the file and counts supported separators.
    Currently supported separators: ['|', ';', ',','    ',':']"""
    ext = os.path.splitext(filepath)[1].lower()
    allowed_exts = ['.csv', '.txt', '.tsv']
    assert ext in ['.csv', '.txt'], 'Unexpected file extension {}.                                     Supported extensions {}\n filename: {}'.format(ext, allowed_exts, os.path.basename(filepath))
    maybe_seps = ['|', ';', ',', '\t', ':']
    with open(filepath, 'r') as fp:
        header = fp.__next__()
    count_seps_header = {sep: _count(sep, header) for sep in maybe_seps}
    count_seps_header = {sep: count for sep, count in count_seps_header.items() if count > 0}
    if count_seps_header:
        return max(count_seps_header.__iter__(), key=lambda key: count_seps_header[key])
    else:
        raise Exception("Couldn't identify the sep from the header... here's the information:\n HEADER: {}\n SEPS SEARCHED: {}".format(header, maybe_seps))

def superReadText(filepath, **kwargs):
    """A wrapper to superReadCSV which wraps pandas.read_csv().
    The benefit of using this function is that it automatically identifies the
    column separator.
    .tsv files are assumed to have a     (tab) separation
    .csv files are assumed to have a comma separation.
    .txt (or any other type) get the first line of the file opened
    and get tested for various separators as defined in the identify_sep
    function."""
    if isinstance(filepath, pd.DataFrame):
        return filepath
    sep = kwargs.get('sep', None)
    ext = os.path.splitext(filepath)[1].lower()
    if sep is None:
        if ext == '.tsv':
            kwargs['sep'] = '\t'
        elif ext == '.csv':
            kwargs['sep'] = ','
        else:
            found_sep = identify_sep(filepath)
            print(found_sep)
            kwargs['sep'] = found_sep
    return superReadCSV(filepath, **kwargs)

def superReadFile(filepath, **kwargs):
    """Uses pandas.read_excel (on excel files) and returns a dataframe of the
    first sheet (unless sheet is specified in kwargs)
    Uses superReadText (on .txt,.tsv, or .csv files) and returns a dataframe of
    the data. One function to read almost all types of data files."""
    if isinstance(filepath, pd.DataFrame):
        return filepath
    ext = os.path.splitext(filepath)[1].lower()
    if ext in ['.xlsx', '.xls']:
        df = pd.read_excel(filepath, **kwargs)
    elif ext in ['.pkl', '.p', '.pickle', '.pk']:
        df = pd.read_pickle(filepath)
    else:
        try:
            df = superReadText(filepath, **kwargs)
        except Exception as e:
            raise Exception('Error reading file: {}'.format(e))
    return df

def dedupe_cols(frame):
    """Need to dedupe columns that have the same name."""
    cols = list(frame.columns)
    for i, item in enumerate(frame.columns):
        if item in frame.columns[:i]:
            cols[i] = 'toDROP'
    frame.columns = cols
    return frame.drop('toDROP', 1, errors='ignore')

def rename_dupe_cols(cols):
    """Takes a list of strings and appends 2,3,4 etc to duplicates. Never
    appends a 0 or 1. Appended #s are not always in order...but if you wrap
    this in a dataframe.to_sql function you're guaranteed to not have dupe
    column name errors importing data to SQL...you'll just have to check
    yourself to see which fields were renamed."""
    counts = {}
    positions = {pos: fld for pos, fld in enumerate(cols)}
    for c in cols:
        if c in counts.keys():
            counts[c] += 1
        else:
            counts[c] = 1
    fixed_cols = {}
    for pos, col in positions.items():
        if counts[col] > 1:
            fix_cols = {pos: fld for pos, fld in positions.items() if fld == col}
            keys = [p for p in fix_cols.keys()]
            min_pos = min(keys)
            cnt = 1
            for p, c in fix_cols.items():
                if not p == min_pos:
                    cnt += 1
                    c = c + str(cnt)
                    fixed_cols.update({p: c})
    positions.update(fixed_cols)
    cols = [x for x in positions.values()]
    return cols

def exception_format():
    """Convert exception info into a string suitable for display."""
    return ''.join(traceback.format_exception(sys.exc_info()[0], sys.exc_info()[1], sys.exc_info()[2]))

def uniquify_list_of_strings(input_list):
    """Ensure that every string within input_list is unique.
    :param list input_list: List of strings
    :return: New list with unique names as needed."""
    output_list = list()
    for i, item in enumerate(input_list):
        tempList = input_list[:i] + input_list[i + 1:]
        if item not in tempList:
            output_list.append(item)
        else:
            output_list.append('{0}_{1}'.format(item, i))
    return output_list

def load_tk_image(filename):
    """Load in an image file and return as a tk Image.

    :param filename: image filename to load
    :return: tk Image object"""
    if filename is None:
        return None
    if not os.path.isfile(filename):
        raise ValueError('Image file {} does not exist.'.format(filename))
    tk_image = None
    filename = os.path.normpath(filename)
    _, ext = os.path.splitext(filename)
    try:
        pil_image = PILImage.open(filename)
        tk_image = PILImageTk.PhotoImage(pil_image)
    except:
        try:
            tk_image = tk.PhotoImage(file=filename)
        except:
            msg = 'Cannot load {}.  Check to make sure it is an image file.'.format(filename)
            try:
                _ = PILImage
            except:
                msg += "\nPIL library isn't installed.  If it isn't installed, only .gif files can be used."
            raise ValueError(msg)
    return tk_image

def getFileDialogTitle(msg, title):
    """Create nicely-formatted string based on arguments msg and title
    :param msg: the msg to be displayed
    :param title: the window title
    :return: None"""
    if msg and title:
        return '%s - %s' % (title, msg)
    if msg and (not title):
        return str(msg)
    if title and (not msg):
        return str(title)
    return None

def generate_epochs_info(epoch_list):
    """use epoch_list to generate epoch_info defined below

    Parameters
    ----------
    epoch_list: list of 3D (binary) array in shape [condition, nEpochs, nTRs]
        Contains specification of epochs and conditions, assuming
        1. all subjects have the same number of epochs;
        2. len(epoch_list) equals the number of subjects;
        3. an epoch is always a continuous time course.

    Returns
    -------
    epoch_info: list of tuple (label, sid, start, end).
        label is the condition labels of the epochs;
        sid is the subject id, corresponding to the index of raw_data;
        start is the start TR of an epoch (inclusive);
        end is the end TR of an epoch(exclusive).
        Assuming len(labels) labels equals the number of epochs and
        the epochs of the same sid are adjacent in epoch_info"""
    time1 = time.time()
    epoch_info = []
    for sid, epoch in enumerate(epoch_list):
        for cond in range(epoch.shape[0]):
            sub_epoch = epoch[cond, :, :]
            for eid in range(epoch.shape[1]):
                r = np.sum(sub_epoch[eid, :])
                if r > 0:
                    start = np.nonzero(sub_epoch[eid, :])[0][0]
                    epoch_info.append((cond, sid, start, start + r))
    time2 = time.time()
    logger.debug('epoch separation done, takes %.2f s' % (time2 - time1))
    return epoch_info

def usable_cpu_count():
    """Get number of CPUs usable by the current process.

    Takes into consideration cpusets restrictions.

    Returns
    -------
    int"""
    try:
        result = len(os.sched_getaffinity(0))
    except AttributeError:
        try:
            result = len(psutil.Process().cpu_affinity())
        except AttributeError:
            result = os.cpu_count()
    return result

def _cross_validation_for_one_voxel(clf, vid, num_folds, subject_data, labels):
    """Score classifier on data using cross validation."""
    skf = model_selection.StratifiedKFold(n_splits=num_folds, shuffle=False)
    scores = model_selection.cross_val_score(clf, subject_data, y=labels, cv=skf, n_jobs=1)
    logger.debug('cross validation for voxel %d is done' % vid)
    return (vid, scores.mean())

def _singlenode_searchlight(l, msk, mysl_rad, bcast_var, extra_params):
    """Run searchlight function on block data in parallel.

    `extra_params` contains:

    - Searchlight function.
    - `Shape` mask.
    - Minimum active voxels proportion required to run the searchlight
      function."""
    voxel_fn = extra_params[0]
    shape_mask = extra_params[1]
    min_active_voxels_proportion = extra_params[2]
    outmat = np.empty(msk.shape, dtype=np.object)[mysl_rad:-mysl_rad, mysl_rad:-mysl_rad, mysl_rad:-mysl_rad]
    for i in range(0, outmat.shape[0]):
        for j in range(0, outmat.shape[1]):
            for k in range(0, outmat.shape[2]):
                if msk[i + mysl_rad, j + mysl_rad, k + mysl_rad]:
                    searchlight_slice = np.s_[i:i + 2 * mysl_rad + 1, j:j + 2 * mysl_rad + 1, k:k + 2 * mysl_rad + 1]
                    voxel_fn_mask = msk[searchlight_slice] * shape_mask
                    if min_active_voxels_proportion == 0 or np.count_nonzero(voxel_fn_mask) / voxel_fn_mask.size > min_active_voxels_proportion:
                        outmat[i, j, k] = voxel_fn([ll[searchlight_slice] for ll in l], msk[searchlight_slice] * shape_mask, mysl_rad, bcast_var)
    return outmat

def chain_getattr(obj, attr, value=None):
    """Get chain attribute for an object.
    """
    try:
        return _resolve_value(safe_chain_getattr(obj, attr))
    except AttributeError:
        return value

def trim_iterable(iterable, limit, *, split=None, prefix='', postfix=''):
    """trim the list to make total length no more than limit.If split specified,a string is return.
    :return:"""
    if split is None:
        sl = 0
        join = False
    else:
        sl = len(split)
        join = True
    result = []
    rl = 0
    for element in iterable:
        element = prefix + element + postfix
        el = len(element)
        if len(result) > 0:
            el += sl
        rl += el
        if rl <= limit:
            result.append(element)
        else:
            break
    if join:
        result = split.join(result)
    return result

def flatten(iterable):
    """flat a iterable. https://stackoverflow.com/a/2158532
    """
    for el in iterable:
        if isinstance(el, collections.Iterable) and (not isinstance(el, (str, bytes))):
            yield from flatten(el)
        else:
            yield el

