def _iter_year_month(year_info):
    """Iter the month days in a lunar year.
    """
    leap_month, leap_days = _parse_leap(year_info)
    months = [(i, 0) for i in range(1, 13)]
    if leap_month > 0:
        months.insert(leap_month, (leap_month, 1))
    for month, leap in months:
        if leap:
            days = leap_days
        else:
            days = (year_info >> 16 - month) % 2 + 29
        yield (month, days, leap)

def ifetch_single(iterable, key, default=EMPTY, getter=None):
    """getter() g(item, key):pass"""
    def _getter(item):
        if getter:
            custom_getter = partial(getter, key=key)
            return custom_getter(item)
        else:
            return partial(bget, key=key, default=default)(item)
    return map(_getter, iterable)

def actual_age_solar(birthday, today=None):
    """See more at https://stackoverflow.com/questions/2217488/age-from-birthdate-in-python/9754466#9754466
    :param birthday:
    :param today:
    :return:"""
    birthday = LCalendars.cast_date(birthday, date)
    if today:
        today = LCalendars.cast_date(today, date)
    else:
        today = date.today()
    return today.year - birthday.year - ((today.month, today.day) < (birthday.month, birthday.day))

def model_typedefs(vk, model):
    """Fill the model with typedefs

    model['typedefs'] = {'name': 'type', ...}"""
    model['typedefs'] = {}
    bitmasks = [x for x in vk['registry']['types']['type'] if x.get('@category') == 'bitmask']
    basetypes = [x for x in vk['registry']['types']['type'] if x.get('@category') == 'basetype']
    for typedef in bitmasks + basetypes:
        if not typedef.get('type'):
            continue
        model['typedefs'][typedef['name']] = typedef['type']
    handles = [x for x in vk['registry']['types']['type'] if x.get('@category') == 'handle']
    for handle in handles:
        if 'name' not in handle or 'type' not in handle:
            continue
        n = handle['name']
        t = handle['type']
        if t == 'VK_DEFINE_HANDLE':
            model['typedefs']['struct %s_T' % n] = '*%s' % n
        if t == 'VK_DEFINE_HANDLE':
            model['typedefs'][n] = 'uint64_t'
    for name in ['Display', 'xcb_connection_t', 'wl_display', 'wl_surface', 'MirConnection', 'MirSurface', 'ANativeWindow', 'SECURITY_ATTRIBUTES']:
        model['typedefs'][name] = 'struct %s' % name
    model['typedefs'].update({'Window': 'uint32_t', 'VisualID': 'uint32_t', 'xcb_window_t': 'uint32_t', 'xcb_visualid_t': 'uint32_t'})

def model_macros(vk, model):
    """Fill the model with macros

    model['macros'] = {'name': value, ...}"""
    model['macros'] = {}
    macros = [x for x in vk['registry']['enums'] if x.get('@type') not in ('bitmask', 'enum')]
    special_values = {'1000.0f': '1000.0', '(~0U)': 4294967295, '(~0ULL)': -1, '(~0U-1)': 4294967294, '(~0U-2)': 4294967293}
    for macro in macros[0]['enum']:
        if '@name' not in macro or '@value' not in macro:
            continue
        name = macro['@name']
        value = macro['@value']
        if value in special_values:
            value = special_values[value]
        model['macros'][name] = value
    for ext in get_extensions_filtered(vk):
        model['macros'][ext['@name']] = 1
        for req in ext['require']:
            for enum in req['enum']:
                ename = enum['@name']
                evalue = parse_constant(enum, int(ext['@number']))
                if enum.get('@extends') == 'VkResult':
                    model['enums']['VkResult'][ename] = evalue
                else:
                    model['macros'][ename] = evalue

def model_funcpointers(vk, model):
    """Fill the model with function pointer

    model['funcpointers'] = {'pfn_name': 'struct_name'}"""
    model['funcpointers'] = {}
    funcs = [x for x in vk['registry']['types']['type'] if x.get('@category') == 'funcpointer']
    structs = [x for x in vk['registry']['types']['type'] if x.get('@category') == 'struct']
    for f in funcs:
        pfn_name = f['name']
        for s in structs:
            if 'member' not in s:
                continue
            for m in s['member']:
                if m['type'] == pfn_name:
                    struct_name = s['@name']
        model['funcpointers'][pfn_name] = struct_name

def model_exceptions(vk, model):
    """Fill the model with exceptions and errors

    model['exceptions'] = {val: 'name',...}
    model['errors'] = {val: 'name',...}"""
    model['exceptions'] = {}
    model['errors'] = {}
    all_codes = model['enums']['VkResult']
    success_names = set()
    error_names = set()
    commands = [x for x in vk['registry']['commands']['command']]
    for command in commands:
        successes = command.get('@successcodes', '').split(',')
        errors = command.get('@errorcodes', '').split(',')
        success_names.update(successes)
        error_names.update(errors)
    for key, value in all_codes.items():
        if key.startswith('VK_RESULT') or key == 'VK_SUCCESS':
            continue
        name = inflection.camelize(key.lower())
        if key in success_names:
            model['exceptions'][value] = name
        elif key in error_names:
            model['errors'][value] = name
        else:
            print('Warning: return code %s unused' % key)

def model_constructors(vk, model):
    """Fill the model with constructors

    model['constructors'] = [{'name': 'x', 'members': [{'name': 'y'}].}]"""
    model['constructors'] = []
    structs = [x for x in vk['registry']['types']['type'] if x.get('@category') in {'struct', 'union'}]
    def parse_len(member):
        mlen = member.get('@len')
        if not mlen:
            return None
        if ',' in mlen:
            mlen = mlen.split(',')[0]
        if 'latex' in mlen or 'null-terminated' in mlen:
            return None
        return mlen
    for struct in structs:
        if 'member' not in struct:
            continue
        model['constructors'].append({'name': struct['@name'], 'members': [{'name': x['name'], 'type': x['type'], 'default': x.get('@values'), 'len': parse_len(x)} for x in struct['member']]})

def model_ext_functions(vk, model):
    """Fill the model with extensions functions"""
    model['ext_functions'] = {'instance': {}, 'device': {}}
    alias = {v: k for k, v in model['alias'].items()}
    for extension in get_extensions_filtered(vk):
        for req in extension['require']:
            if not req.get('command'):
                continue
            ext_type = extension['@type']
            for x in req['command']:
                name = x['@name']
                if name in alias.keys():
                    model['ext_functions'][ext_type][name] = alias[name]
                else:
                    model['ext_functions'][ext_type][name] = name

def model_alias(vk, model):
    """Fill the model with alias since V1"""
    model['alias'] = {}
    for s in vk['registry']['types']['type']:
        if s.get('@category', None) == 'handle' and s.get('@alias'):
            model['alias'][s['@alias']] = s['@name']
    for c in vk['registry']['commands']['command']:
        if c.get('@alias'):
            model['alias'][c['@alias']] = c['@name']

def format_vk(vk):
    """Format vk before using it"""
    for ext in get_extensions_filtered(vk):
        req = ext['require']
        if not isinstance(req, list):
            ext['require'] = [req]

def find_all_models(models):
    """Yield all models and their parents."""
    for model in models:
        yield model
        for parent in model._meta.parents.keys():
            for parent_model in find_all_models((parent,)):
                yield parent_model

def mocked_relations(*models):
    """Mock all related field managers to make pure unit tests possible.

    The resulting patcher can be used just like one from the mock module:
    As a test method decorator, a test class decorator, a context manager,
    or by just calling start() and stop().

    @mocked_relations(Dataset):
    def test_dataset(self):
        dataset = Dataset()
        check = dataset.content_checks.create()  # returns a ContentCheck object"""
    patchers = []
    for model in find_all_models(models):
        if isinstance(model.save, Mock):
            continue
        model_name = model._meta.object_name
        patchers.append(_patch_save(model, model_name))
        if hasattr(model, 'objects'):
            patchers.append(_patch_objects(model, model_name))
        for related_object in chain(model._meta.related_objects, model._meta.many_to_many):
            name = related_object.name
            if name not in model.__dict__ and related_object.one_to_many:
                name += '_set'
            if name in model.__dict__:
                if getattr(model, name, None):
                    patchers.append(_patch_relation(model, name, related_object))
    return PatcherChain(patchers, pass_mocks=False)

def _zero_on_type_error(column_fn):
    """Wrap a function on an np.ndarray to return 0 on a type error."""
    if not column_fn:
        return column_fn
    if not callable(column_fn):
        raise TypeError('column functions must be callable')
    @functools.wraps(column_fn)
    def wrapped(column):
        try:
            return column_fn(column)
        except TypeError:
            if isinstance(column, np.ndarray):
                return column.dtype.type()
            else:
                raise
    return wrapped

def _fill_with_zeros(partials, rows, zero=None):
    """Find and return values from rows for all partials. In cases where no
    row matches a partial, zero is assumed as value. For a row, the first
    (n-1) fields are assumed to be the partial, and the last field,
    the value, where n is the total number of fields in each row. It is
    assumed that there is a unique row for each partial.
    partials -- single field values or tuples of field values
    rows -- table rows
    zero -- value used when no rows match a particular partial"""
    assert len(rows) > 0
    if not _is_non_string_iterable(partials):
        partials = [(partial,) for partial in partials]
    mapping = {}
    for row in rows:
        mapping[tuple(row[:-1])] = row[-1]
    if zero is None:
        array = np.array(tuple(mapping.values()))
        if len(array.shape) == 1:
            zero = array.dtype.type()
    return np.array([mapping.get(partial, zero) for partial in partials])

def _varargs_labels_as_list(label_list):
    """Return a list of labels for a list of labels or singleton list of list
    of labels."""
    if len(label_list) == 0:
        return []
    elif not _is_non_string_iterable(label_list[0]):
        return label_list
    elif len(label_list) == 1:
        return label_list[0]
    else:
        raise ValueError('Labels {} contain more than list.'.format(label_list), 'Pass just one list of labels.')

def _collected_label(collect, label):
    """Label of a collected column."""
    if not collect.__name__.startswith('<'):
