def _is_non_string_iterable(value):
    """Whether a value is iterable."""
    if isinstance(value, str):
        return False
    if hasattr(value, '__iter__'):
        return True
    if isinstance(value, collections.abc.Sequence):
        return True
    return False

def _vertical_x(axis, ticks=None, max_width=5):
    """Switch labels to vertical if they are long."""
    if ticks is None:
        ticks = axis.get_xticks()
    if (np.array(ticks) == np.rint(ticks)).all():
        ticks = np.rint(ticks).astype(np.int)
    if max([len(str(tick)) for tick in ticks]) > max_width:
        axis.set_xticklabels(ticks, rotation='vertical')

def percentile(p, arr=None):
    """Returns the pth percentile of the input array (the value that is at
    least as great as p% of the values in the array).

    If arr is not provided, percentile returns itself curried with p

    >>> percentile(74.9, [1, 3, 5, 9])
    5
    >>> percentile(75, [1, 3, 5, 9])
    5
    >>> percentile(75.1, [1, 3, 5, 9])
    9
    >>> f = percentile(75)
    >>> f([1, 3, 5, 9])
    5"""
    if arr is None:
        return lambda arr: percentile(p, arr)
    if hasattr(p, '__iter__'):
        return np.array([percentile(x, arr) for x in p])
    if p == 0:
        return min(arr)
    assert 0 < p <= 100, 'Percentile requires a percent'
    i = p / 100 * len(arr)
    return sorted(arr)[math.ceil(i) - 1]

def minimize(f, start=None, smooth=False, log=None, array=False, **vargs):
    """Minimize a function f of one or more arguments.

    Args:
        f: A function that takes numbers and returns a number

        start: A starting value or list of starting values

        smooth: Whether to assume that f is smooth and use first-order info

        log: Logging function called on the result of optimization (e.g. print)

        vargs: Other named arguments passed to scipy.optimize.minimize

    Returns either:
        (a) the minimizing argument of a one-argument function
        (b) an array of minimizing arguments of a multi-argument function"""
    if start is None:
        assert not array, 'Please pass starting values explicitly when array=True'
        arg_count = f.__code__.co_argcount
        assert arg_count > 0, 'Please pass starting values explicitly for variadic functions'
        start = [0] * arg_count
    if not hasattr(start, '__len__'):
        start = [start]
    if array:
        objective = f
    else:
        @functools.wraps(f)
        def objective(args):
            return f(*args)
    if not smooth and 'method' not in vargs:
        vargs['method'] = 'Powell'
    result = optimize.minimize(objective, start, **vargs)
    if log is not None:
        log(result)
    if len(start) == 1:
        return result.x.item(0)
    else:
        return result.x

def _lat_lons_from_geojson(s):
    """Return a latitude-longitude pairs from nested GeoJSON coordinates.

    GeoJSON coordinates are always stored in (longitude, latitude) order."""
    if len(s) >= 2 and isinstance(s[0], _number) and isinstance(s[0], _number):
        lat, lon = (s[1], s[0])
        return [(lat, lon)]
    else:
        return [lat_lon for sub in s for lat_lon in _lat_lons_from_geojson(sub)]

def decode(bstr):
    """Decodes an ASCII encoded binary MAC address tring into a number."""
    bstr = bstr.replace(b':', b'')
    if len(bstr) != 12:
        raise ValueError('not a valid MAC address: {!r}'.format(bstr))
    try:
        return int(bstr, 16)
    except ValueError:
        raise ValueError('not a valid MAC address: {!r}'.format(bstr))

def init(lib_name=None, bin_path=None, sdk_path=None):
    """Initialize the Myo SDK by loading the libmyo shared library. With no
    arguments, libmyo must be on your `PATH` or `LD_LIBRARY_PATH`.

    You can specify the exact path to libmyo with *lib_name*. Alternatively,
    you can specify the binaries directory that contains libmyo with *bin_path*.
    Finally, you can also pass the path to the Myo SDK root directory and it
    will figure out the path to libmyo by itself."""
    if sum((bool(x) for x in [lib_name, bin_path, sdk_path])) > 1:
        raise ValueError('expected zero or one arguments')
    if sdk_path:
        if sys.platform.startswith('win32'):
            bin_path = os.path.join(sdk_path, 'bin')
        elif sys.platform.startswith('darwin'):
            bin_path = os.path.join(sdk_path, 'myo.framework')
        else:
            raise RuntimeError('unsupported platform: {!r}'.format(sys.platform))
    if bin_path:
        lib_name = os.path.join(bin_path, _getdlname())
    if not lib_name:
        lib_name = _getdlname()
    global libmyo
    libmyo = ffi.dlopen(lib_name)

def find_first_tag(tags, entity_type, after_index=-1):
    """Searches tags for entity type after given index

    Args:
        tags(list): a list of tags with entity types to be compaired too entity_type
        entity_type(str): This is he entity type to be looking for in tags
        after_index(int): the start token must be greaterthan this.

    Returns:
        ( tag, v, confidence ):
            tag(str): is the tag that matched
            v(str): ? the word that matched?
            confidence(float): is a mesure of accuacy.  1 is full confidence and 0 is none."""
    for tag in tags:
        for entity in tag.get('entities'):
            for v, t in entity.get('data'):
                if t.lower() == entity_type.lower() and tag.get('start_token', 0) > after_index:
                    return (tag, v, entity.get('confidence'))
    return (None, None, None)

def choose_1_from_each(lists):
    """Takes a list of lists and returns a list of lists with one item
    from each list.  This new list should be the length of each list multiplied
    by the others.  18 for an list with lists of 3, 2 and 3.  Also the lenght
    of each sub list should be same as the length of lists passed in.

    Args:
        lists(list of Lists):  A list of lists

    Returns:
        list of lists: returns a list of lists constructions of one item from each
            list in lists."""
    if len(lists) == 0:
        yield []
    else:
        for el in lists[0]:
            for next_list in choose_1_from_each(lists[1:]):
                yield ([el] + next_list)

def resolve_one_of(tags, at_least_one):
    """This searches tags for Entites in at_least_one and returns any match

    Args:
        tags(list): List of tags with Entities to search for Entities
        at_least_one(list): List of Entities to find in tags

    Returns:
        object: returns None if no match is found but returns any match as an object"""
    if len(tags) < len(at_least_one):
        return None
    for possible_resolution in choose_1_from_each(at_least_one):
        resolution = {}
        pr = possible_resolution[:]
        for entity_type in pr:
            last_end_index = -1
            if entity_type in resolution:
                last_end_index = resolution.get[entity_type][-1].get('end_token')
            tag, value, c = find_first_tag(tags, entity_type, after_index=last_end_index)
            if not tag:
                break
            else:
                if entity_type not in resolution:
                    resolution[entity_type] = []
                resolution[entity_type].append(tag)
        if len(resolution) == len(possible_resolution):
            return resolution
    return None

def rdfgraph_to_ontol(rg):
