def load_gpi(self, gpi_path):
    """Loads a GPI as a file from the `config.gpi_authority_path`"""
    if self.config.gpi_authority_path is not None:
        gpis = dict()
        parser = entityparser.GpiParser()
        with open(self.config.gpi_authority_path) as gpi_f:
            entities = parser.parse(file=gpi_f)
            for entity in entities:
                gpis[entity['id']] = {'symbol': entity['label'], 'name': entity['full_name'], 'synonyms': entitywriter.stringify(entity['synonyms']), 'type': entity['type']}
        return gpis
    return None

def get_digraph(ont, relations=None, writecache=False):
    """Creates a basic graph object corresponding to a remote ontology"""
    digraph = networkx.MultiDiGraph()
    logging.info('Getting edges (may be cached)')
    for s, p, o in get_edges(ont):
        p = map_legacy_pred(p)
        if relations is None or p in relations:
            digraph.add_edge(o, s, pred=p)
    logging.info('Getting labels (may be cached)')
    for n, label in fetchall_labels(ont):
        digraph.add_node(n, **{'label': label})
    return digraph

def get_xref_graph(ont):
    """Creates a basic graph object corresponding to a remote ontology"""
    g = networkx.MultiGraph()
    for c, x in fetchall_xrefs(ont):
        g.add_edge(c, x, source=c)
    return g

def get_terms_in_subset(ont, subset):
    """Find all nodes in a subset.

    We assume the oboInOwl encoding of subsets, and subset IDs are IRIs"""
    namedGraph = get_named_graph(ont)
    query = "
    prefix oboInOwl: <http://www.geneontology.org/formats/oboInOwl#>
    SELECT ?c ? WHERE {{
    GRAPH <{g}>  {{
    ?c oboInOwl:inSubset ?s ;
       rdfs:label ?l
    FILTER regex(?s,'#{s}$','i')
    }}
    }}
    ".format(s=subset, g=namedGraph)
    bindings = run_sparql(query)
    return [(r['c']['value'], r['l']['value']) for r in bindings]

def fetchall_textdefs(ont):
    """fetch all text defs for an ontology"""
    logging.info('fetching text defs for: ' + ont)
    namedGraph = get_named_graph(ont)
    query = '
    prefix IAO: <http://purl.obolibrary.org/obo/IAO_>
    SELECT * WHERE {{
    GRAPH <{g}>  {{
      ?c IAO:0000115 ?d
    }}
    FILTER (!isBlank(?c))
    }}
    '.format(g=namedGraph)
    bindings = run_sparql(query)
    rows = [(r['c']['value'], r['d']['value']) for r in bindings]
    return rows

def batch_fetch_labels(ids):
    """fetch all rdfs:label assertions for a set of CURIEs"""
    m = {}
    for id in ids:
        label = anyont_fetch_label(id)
        if label is not None:
            m[id] = label
    return m

def transform(data, keysToSplit=[]):
    """Transform a SPARQL json result by:
    1) outputing only { key : value }, removing datatype
    2) for some keys, transform them into array based on SEPARATOR"""
    transformed = {}
    for key in data:
        if key in keysToSplit:
            transformed[key] = data[key]['value'].split(SEPARATOR)
        else:
            transformed[key] = data[key]['value']
    return transformed

def transformArray(data, keysToSplit=[]):
    """Transform a SPARQL json array based on the rules of transform"""
    transformed = []
    for item in data:
        transformed.append(transform(item, keysToSplit))
    return transformed

def get_checksum(file):
    """Get SHA256 hash from the contents of a given file"""
    with open(file, 'rb') as FH:
        contents = FH.read()
    return hashlib.sha256(contents).hexdigest()

def convert_to_path(name):
    """Converts ".module" to "./module", "..module" to "../module", etc."""
    if name.startswith('.'):
        remainder = name.lstrip('.')
        dot_count = len(name) - len(remainder)
        prefix = '../' * (dot_count - 1)
    else:
        remainder = name
        dot_count = 0
        prefix = ''
    filename = prefix + os.path.join(*remainder.split('.'))
    return (filename, dot_count)

def infer_module_name(filename, fspath):
    """Convert a python filename to a module relative to pythonpath."""
    filename, _ = os.path.splitext(filename)
    for f in fspath:
        short_name = f.relative_path(filename)
        if short_name:
            if short_name.endswith(os.path.sep + '__init__'):
                short_name = short_name[:short_name.rfind(os.path.sep)]
            return short_name.replace(os.path.sep, '.')
    return ''

def path_from_pythonpath(pythonpath):
    """Create an fs.Path object from a pythonpath string."""
    path = fs.Path()
    for p in pythonpath.split(os.pathsep):
        path.add_path(utils.expand_path(p), 'os')
    return path

def format_file_node(import_graph, node, indent):
    """Prettyprint nodes based on their provenance."""
    f = import_graph.provenance[node]
    if isinstance(f, resolve.Direct):
        out = '+ ' + f.short_path
    elif isinstance(f, resolve.Local):
        out = '  ' + f.short_path
    elif isinstance(f, resolve.System):
        out = ':: ' + f.short_path
    elif isinstance(f, resolve.Builtin):
        out = '(%s)' % f.module_name
    else:
        out = '%r' % node
    return '  ' * indent + out

def format_node(import_graph, node, indent):
    """Helper function for print_tree"""
    if isinstance(node, graph.NodeSet):
        ind = '  ' * indent
        out = [ind + 'cycle {'] + [format_file_node(import_graph, n, indent + 1) for n in node.nodes] + [ind + '}']
        return '\n'.join(out)
    else:
        return format_file_node(import_graph, node, indent)

def _find_package(parts):
    """Helper function for _resolve_import_versioned."""
    for i in range(len(parts), 0, -1):
        prefix = '.'.join(parts[0:i])
        if prefix in sys.modules:
            return (i, sys.modules[prefix])
    return (0, None)

def _resolve_import(name):
    """Helper function for resolve_import."""
    if name in sys.modules:
        return getattr(sys.modules[name], '__file__', name + '.so')
    return _resolve_import_versioned(name)

def resolve_import(name, is_from, is_star):
    """Use python to resolve an import.

    Args:
      name: The fully qualified module name.

    Returns:
      The path to the module source file or None."""
    if name.startswith('.') or is_builtin(name):
        return None
    ret = _resolve_import(name)
    if ret is None and is_from and (not is_star):
        package, _ = name.rsplit('.', 1)
        ret = _resolve_import(package)
    return ret

def strip_suffix(string, suffix):
    """Remove a suffix from a string if it exists."""
    if string.endswith(suffix):
        return string[:-len(suffix)]
    return string

def unread(thread, user):
    """Check whether there are any unread messages for a particular thread for a user."""
    return bool(thread.userthread_set.filter(user=user, unread=True))

def xml_equal(xml_file1, xml_file2):
    """Parse xml and convert to a canonical string representation so we don't
    have to worry about semantically meaningless differences"""
    def canonical(xml_file):
        s = et.tostring(et.parse(xml_file).getroot()).decode('UTF-8')
        s = re.sub('[\n|\t]*', '', s)
        s = re.sub('\\s+', ' ', s)
        s = ''.join(sorted(s)).strip()
        return s
    return canonical(xml_file1) == canonical(xml_file2)

def list_files(dir_path, recursive=True):
    """Return a list of files in dir_path."""
    for root, dirs, files in os.walk(dir_path):
        file_list = [os.path.join(root, f) for f in files]
        if recursive:
            for dir in dirs:
                dir = os.path.join(root, dir)
                file_list.extend(list_files(dir, recursive=True))
        return file_list

