def colorize(target, color, use_escape=True):
    """Colorize target string. Set use_escape to false when text will not be
    interpreted by readline, such as in intro message."""
    def escape(code):
        """Escape character"""
        return '\x01%s\x02' % code
    if color == 'purple':
        color_code = '\x1b[95m'
    elif color == 'cyan':
        color_code = '\x1b[96m'
    elif color == 'darkcyan':
        color_code = '\x1b[36m'
    elif color == 'blue':
        color_code = '\x1b[93m'
    elif color == 'green':
        color_code = '\x1b[92m'
    elif color == 'yellow':
        color_code = '\x1b[93m'
    elif color == 'red':
        color_code = '\x1b[91m'
    elif color == 'white':
        color_code = '\x1b[37m'
    elif color == 'bold':
        color_code = '\x1b[1m'
    elif color == 'underline':
        color_code = '\x1b[4m'
    else:
        color_code = ''
    if use_escape:
        return escape(color_code) + target + escape('\x1b[0m')
    else:
        return color_code + target + '\x1b[m'

def duration_to_number(duration, units='seconds'):
    """If duration is already a numeric type, then just return
    duration. If duration is a timedelta, return a duration in
    seconds.

    TODO: allow for multiple types of units."""
    if isinstance(duration, (int, float, long)):
        return duration
    elif isinstance(duration, (datetime.timedelta,)):
        if units == 'seconds':
            return duration.total_seconds()
        else:
            msg = 'unit "%s" is not supported' % units
            raise NotImplementedError(msg)
    elif duration == inf or duration == -inf:
        msg = "Can't convert infinite duration to number"
        raise ValueError(msg)
    else:
        msg = 'duration is an unknown type (%s)' % duration
        raise TypeError(msg)

def convert_args_to_list(args):
    """Convert all iterable pairs of inputs into a list of list"""
    list_of_pairs = []
    if len(args) == 0:
        return []
    if any((isinstance(arg, (list, tuple)) for arg in args)):
        if len(args) == 1 and any((isinstance(arg, (list, tuple)) for arg in args[0])):
            for item in args[0]:
                list_of_pairs.append(list(item))
        else:
            for item in args:
                list_of_pairs.append(list(item))
    elif len(args) == 2:
        list_of_pairs.append(list(args))
    else:
        msg = 'The argument type is invalid. '.format(args)
        raise TypeError(msg)
    return list_of_pairs

def datetime_range(start_dt, end_dt, unit, n_units=1, inclusive_end=False):
    """A range of datetimes/dates."""
    def done(a, b, inclusive_end):
        if inclusive_end:
            return a <= b
        else:
            return a < b
    current = start_dt
    while done(current, end_dt, inclusive_end):
        yield current
        current += datetime.timedelta(**{unit: n_units})

def read_init(key):
    """Parse the package __init__ file to find a variable so that it's not
    in multiple places."""
    filename = os.path.join('traces', '__init__.py')
    result = None
    with open(filename) as stream:
        for line in stream:
            if key in line:
                result = line.split('=')[-1].strip().replace("'", '')
    if result is None:
        raise ValueError('must define %s in %s' % (key, filename))
    return result

def read_dependencies(filename):
    """Read in the dependencies from the virtualenv requirements file.

    """
    dependencies = []
    filepath = os.path.join('requirements', filename)
    with open(filepath, 'r') as stream:
        for line in stream:
            package = line.strip().split('#')[0].strip()
            if package and package.split(' ')[0] != '-r':
                dependencies.append(package)
    return dependencies

def load_confirm_exit_bindings(python_input):
    """Handle yes/no key presses when the exit confirmation is shown."""
    bindings = KeyBindings()
    handle = bindings.add
    confirmation_visible = Condition(lambda: python_input.show_exit_confirmation)
    @handle('y', filter=confirmation_visible)
    @handle('Y', filter=confirmation_visible)
    @handle('enter', filter=confirmation_visible)
    @handle('c-d', filter=confirmation_visible)
    def _(event):
        """Really quit."""
        event.app.exit(exception=EOFError, style='class:exiting')
    @handle(Keys.Any, filter=confirmation_visible)
    def _(event):
        """Cancel exit."""
        python_input.show_exit_confirmation = False
    return bindings

def auto_newline(buffer):
    """Insert \\n at the cursor position. Also add necessary padding."""
    insert_text = buffer.insert_text
    if buffer.document.current_line_after_cursor:
        insert_text('\n')
    else:
        current_line = buffer.document.current_line_before_cursor.rstrip()
        insert_text('\n')
        unindent = current_line.rstrip().endswith(' pass')
        current_line2 = current_line[4:] if unindent else current_line
        for c in current_line2:
            if c.isspace():
                insert_text(c)
            else:
                break
        if current_line[-1:] == ':':
            for x in range(4):
                insert_text(' ')

def _inputhook_tk(inputhook_context):
    """Inputhook for Tk.
    Run the Tk eventloop until prompt-toolkit needs to process the next input."""
    import _tkinter
    from six.moves import tkinter
    root = tkinter._default_root
    def wait_using_filehandler():
        """Run the TK eventloop until the file handler that we got from the
        inputhook becomes readable."""
        stop = [False]
        def done(*a):
            stop[0] = True
        root.createfilehandler(inputhook_context.fileno(), _tkinter.READABLE, done)
        while root.dooneevent(_tkinter.ALL_EVENTS):
            if stop[0]:
                break
        root.deletefilehandler(inputhook_context.fileno())
    def wait_using_polling():
        """Windows TK doesn't support 'createfilehandler'.
        So, run the TK eventloop and poll until input is ready."""
        while not inputhook_context.input_is_ready():
            while root.dooneevent(_tkinter.ALL_EVENTS | _tkinter.DONT_WAIT):
                pass
            time.sleep(0.01)
    if root is not None:
        if hasattr(root, 'createfilehandler'):
            wait_using_filehandler()
        else:
            wait_using_polling()

def run_config(repl, config_file='~/.ptpython/config.py'):
    """Execute REPL config file.

    :param repl: `PythonInput` instance.
    :param config_file: Path of the configuration file."""
    assert isinstance(repl, PythonInput)
    assert isinstance(config_file, six.text_type)
    config_file = os.path.expanduser(config_file)
    def enter_to_continue():
        six.moves.input('\nPress ENTER to continue...')
    if not os.path.exists(config_file):
        print('Impossible to read %r' % config_file)
        enter_to_continue()
        return
    try:
        namespace = {}
        with open(config_file, 'rb') as f:
            code = compile(f.read(), config_file, 'exec')
            six.exec_(code, namespace, namespace)
        if 'configure' in namespace:
            namespace['configure'](repl)
    except Exception:
        traceback.print_exc()
        enter_to_continue()

