def download_from_url(url, destination_path, force=False, aspera=False, silent=False):
    """Download file from remote server.

    If the file is already downloaded and  ``force`` flag is on the file will
    be removed.

    Args:
        url (:obj:`str`): Path to the file on remote server (including file
            name)
        destination_path (:obj:`str`): Path to the file on local machine
            (including file name)
        force (:obj:`bool`): If file exist force to overwrite it. Defaults to
            False.
        aspera (:obj:`bool`): Download with Aspera Connect. Defaults to False.
        silent (:obj:`bool`): Do not print any message. Defaults to False."""
    if aspera and url.startswith('http'):
        logger.warn('Aspera Connect allows only FTP servers - falling back to normal download')
        aspera = False
    try:
        fn = Downloader(url, outdir=os.path.dirname(destination_path))
        if aspera:
            fn.download_aspera(user='anonftp', host='ftp-trace.ncbi.nlm.nih.gov', silent=silent)
        else:
            fn.download(silent=silent, force=force)
    except URLError:
        logger.error('Cannot find file %s' % url)

def smart_open(filepath):
    """Open file intelligently depending on the source and python version.

    Args:
        filepath (:obj:`str`): Path to the file.

    Yields:
        Context manager for file handle."""
    if filepath[-2:] == 'gz':
        mode = 'rt'
        fopen = gzip.open
    else:
        mode = 'r'
        fopen = open
    if sys.version_info[0] < 3:
        fh = fopen(filepath, mode)
    else:
        fh = fopen(filepath, mode, errors='ignore')
    try:
        yield fh
    except IOError:
        fh.close()
    finally:
        fh.close()

def rosenbrock(x, y, a=1, b=100):
    """Bigger is better; global optimum at x=a, y=a**2"""
    return -1 * ((a - x) ** 2 + b * (y - x ** 2) ** 2)

def parse_query_value(combined_value):
    """Parse value in form of '>value' to a lambda and a value."""
    split = len(combined_value) - len(combined_value.lstrip('<>='))
    operator = combined_value[:split]
    if operator == '':
        operator = '='
    try:
        operator_func = search_operators[operator]
    except KeyError:
        raise ValueError('Numeric query should start with operator, choose from %s' % ', '.join(search_operators.keys()))
    value = combined_value[split:].strip()
    return (operator_func, value)

