def _parse_values(s):
    """(INTERNAL) Split a line into a list of values"""
    if not _RE_NONTRIVIAL_DATA.search(s):
        return [None if s in ('?', '') else s for s in next(csv.reader([s]))]
    values, errors = zip(*_RE_DENSE_VALUES.findall(',' + s))
    if not any(errors):
        return [_unquote(v) for v in values]
    if _RE_SPARSE_LINE.match(s):
        try:
            return {int(k): _unquote(v) for k, v in _RE_SPARSE_KEY_VALUES.findall(s)}
        except ValueError as exc:
            for match in _RE_SPARSE_KEY_VALUES.finditer(s):
                if not match.group(1):
                    raise BadLayout('Error parsing %r' % match.group())
            raise BadLayout('Unknown parsing error')
    else:
        for match in _RE_DENSE_VALUES.finditer(s):
            if match.group(2):
                raise BadLayout('Error parsing %r' % match.group())
        raise BadLayout('Unknown parsing error')

def _add_logging(dsk, ignore=None):
    """Add logging to a Dask graph.

    @param dsk: The Dask graph.

    @return: New Dask graph."""
    ctx = current_action()
    result = {}
    keys = toposort(dsk)
    def simplify(k):
        if isinstance(k, str):
            return k
        return '-'.join((str(o) for o in k))
    key_names = {}
    for key in keys:
        value = dsk[key]
        if not callable(value) and value in keys:
            key_names[key] = key_names[value]
        else:
            key_names[key] = simplify(key)
    key_to_action_id = {key: str(ctx.serialize_task_id(), 'utf-8') for key in keys}
    for key in keys:
        func = dsk[key][0]
        args = dsk[key][1:]
        if not callable(func):
            result[key] = dsk[key]
            continue
        wrapped_func = _RunWithEliotContext(task_id=key_to_action_id[key], func=func, key=key_names[key], dependencies=[key_names[k] for k in get_dependencies(dsk, key)])
        result[key] = (wrapped_func,) + tuple(args)
    assert result.keys() == dsk.keys()
    return result

def eliot_friendly_generator_function(original):
    """Decorate a generator function so that the Eliot action context is
    preserved across ``yield`` expressions."""
    @wraps(original)
    def wrapper(*a, **kw):
        ok = True
        value_in = None
        gen = original(*a, **kw)
        context = copy_context()
        while True:
            try:
                def go():
                    if ok:
                        value_out = gen.send(value_in)
                    else:
                        value_out = gen.throw(*value_in)
                    if wrapper.debug:
                        Message.log(message_type=u'yielded')
                    return value_out
                value_out = context.run(go)
            except StopIteration:
                break
            else:
                try:
                    value_in = (yield value_out)
                except:
                    ok = False
                    value_in = exc_info()
                else:
                    ok = True
    wrapper.debug = False
    return wrapper

def sd_journal_send(**kwargs):
    """Send a message to the journald log.

    @param kwargs: Mapping between field names to values, both as bytes.

    @raise IOError: If the operation failed."""
    fields = [_ffi.new('char[]', key.encode('ascii') + b'=' + value.replace(b'%', b'%%')) for key, value in kwargs.items()]
    fields.append(_ffi.NULL)
    result = _journald.sd_journal_send(*fields)
    if result != 0:
        raise IOError(-result, strerror(-result))

def inline_callbacks(original, debug=False):
    """Decorate a function like ``inlineCallbacks`` would but in a more
    Eliot-friendly way.  Use it just like ``inlineCallbacks`` but where you
    want Eliot action contexts to Do The Right Thing inside the decorated
    function."""
    f = eliot_friendly_generator_function(original)
    if debug:
        f.debug = True
    return inlineCallbacks(f)

def _loads(s):
    """Support decoding bytes."""
    if isinstance(s, bytes):
        s = s.decode('utf-8')
    return pyjson.loads(s)

def _dumps(obj, cls=pyjson.JSONEncoder):
    """Encode to bytes, and presume bytes in inputs are UTF-8 encoded strings."""
    class WithBytes(cls):
        """JSON encoder that supports L{bytes}."""
        def default(self, o):
            if isinstance(o, bytes):
                warnings.warn('Eliot will soon stop supporting encoding bytes in JSON on Python 3', DeprecationWarning)
                return o.decode('utf-8')
            return cls.default(self, o)
    return pyjson.dumps(obj, cls=WithBytes).encode('utf-8')

def load_module(name, original_module):
    """Load a copy of a module, distinct from what you'd get if you imported
    it directly.

    @param str name: The name of the new module.
    @param original_module: The original module we're recreating.

    @return: A new, distinct module."""
    module = ModuleType(name)
    if PY3:
        import importlib.util
        spec = importlib.util.find_spec(original_module.__name__)
        source = spec.loader.get_code(original_module.__name__)
    else:
        if getattr(sys, 'frozen', False):
            raise NotImplementedError("Can't load modules on Python 2 with PyInstaller")
        path = original_module.__file__
        if path.endswith('.pyc') or path.endswith('.pyo'):
            path = path[:-1]
        with open(path) as f:
            source = f.read()
    exec_(source, module.__dict__, module.__dict__)
    return module

def _writeTracebackMessage(logger, typ, exception, traceback):
    """Write a traceback to the log.

    @param typ: The class of the exception.

    @param exception: The L{Exception} instance.

    @param traceback: The traceback, a C{str}."""
    msg = TRACEBACK_MESSAGE(reason=exception, traceback=traceback, exception=typ)
    msg = msg.bind(**_error_extraction.get_fields_for_exception(logger, exception))
    msg.write(logger)

def write_traceback(logger=None, exc_info=None):
    """Write the latest traceback to the log.

    This should be used inside an C{except} block. For example:

         try:
             dostuff()
         except:
             write_traceback(logger)

    Or you can pass the result of C{sys.exc_info()} to the C{exc_info}
    parameter."""
    if exc_info is None:
        exc_info = sys.exc_info()
    typ, exception, tb = exc_info
    traceback = ''.join(_traceback_no_io.format_exception(typ, exception, tb))
    _writeTracebackMessage(logger, typ, exception, traceback)

def exclusively(f):
    """Decorate a function to make it thread-safe by serializing invocations
    using a per-instance lock."""
    @wraps(f)
    def exclusively_f(self, *a, **kw):
        with self._lock:
            return f(self, *a, **kw)
    return exclusively_f

def to_file(output_file, encoder=EliotJSONEncoder):
    """Add a destination that writes a JSON message per line to the given file.

    @param output_file: A file-like object."""
    Logger._destinations.add(FileDestination(file=output_file, encoder=encoder))

def decode(tai64n):
    """Convert TAI64N string to seconds since epoch.

    Note that dates before 2013 may not decode accurately due to leap second
    issues. If you need correct decoding for earlier dates you can try the
    tai64n package available from PyPI (U{https://pypi.python.org/pypi/tai64n}).

    @param tai64n: TAI64N-encoded time, as C{unicode}.

    @return: Seconds since UTC Unix epoch as C{float}."""
    seconds, nanoseconds = struct.unpack(_STRUCTURE, a2b_hex(tai64n[1:]))
    seconds -= _OFFSET
    return seconds + nanoseconds / 1000000000.0

def startTask(logger=None, action_type=u'', _serializers=None, **fields):
    """Like L{action}, but creates a new top-level L{Action} with no parent.

    @param logger: The L{eliot.ILogger} to which to write messages, or
        C{None} to use the default one.

    @param action_type: The type of this action,
        e.g. C{"yourapp:subsystem:dosomething"}.

    @param _serializers: Either a L{eliot._validation._ActionSerializers}
        instance or C{None}. In the latter case no validation or serialization
        will be done for messages generated by the L{Action}.

    @param fields: Additional fields to add to the start message.

    @return: A new L{Action}."""
    action = Action(logger, unicode(uuid4()), TaskLevel(level=[]), action_type, _serializers)
    action._start(fields)
    return action

def preserve_context(f):
    """Package up the given function with the current Eliot context, and then
    restore context and call given function when the resulting callable is
    run. This allows continuing the action context within a different thread.

    The result should only be used once, since it relies on
    L{Action.serialize_task_id} whose results should only be deserialized
    once.

    @param f: A callable.

    @return: One-time use callable that calls given function in context of
        a child of current Eliot action."""
    action = current_action()
    if action is None:
        return f
    task_id = action.serialize_task_id()
    called = threading.Lock()
    def restore_eliot_context(*args, **kwargs):
        if not called.acquire(False):
            raise TooManyCalls(f)
        with Action.continue_task(task_id=task_id):
            return f(*args, **kwargs)
    return restore_eliot_context

def fields(*fields, **keys):
    """Factory for for L{MessageType} and L{ActionType} field definitions.

    @param *fields: A L{tuple} of L{Field} instances.

    @param **keys: A L{dict} mapping key names to the expected type of the
        field's values.

    @return: A L{list} of L{Field} instances."""
    return list(fields) + [Field.forTypes(key, [value], '') for key, value in keys.items()]

def pretty_format(message):
    """Convert a message dictionary into a human-readable string.

    @param message: Message to parse, as dictionary.

    @return: Unicode string."""
    skip = {TIMESTAMP_FIELD, TASK_UUID_FIELD, TASK_LEVEL_FIELD, MESSAGE_TYPE_FIELD, ACTION_TYPE_FIELD, ACTION_STATUS_FIELD}
    def add_field(previous, key, value):
        value = unicode(pprint.pformat(value, width=40)).replace('\\n', '\n ').replace('\\t', '\t')
        lines = value.split('\n')
        indent = '{}| '.format(' ' * (2 + len(key)))
        value = '\n'.join([lines[0]] + [indent + l for l in lines[1:]])
        return '  %s: %s\n' % (key, value)
    remaining = ''
    for field in [ACTION_TYPE_FIELD, MESSAGE_TYPE_FIELD, ACTION_STATUS_FIELD]:
        if field in message:
            remaining += add_field(remaining, field, message[field])
    for key, value in sorted(message.items()):
        if key not in skip:
            remaining += add_field(remaining, key, value)
    level = '/' + '/'.join(map(unicode, message[TASK_LEVEL_FIELD]))
    return '%s -> %s\n%sZ\n%s' % (message[TASK_UUID_FIELD], level, datetime.utcfromtimestamp(message[TIMESTAMP_FIELD]).isoformat(sep=str(' ')), remaining)

def _main():
    """Command-line program that reads in JSON from stdin and writes out
    pretty-printed messages to stdout."""
    if argv[1:]:
        stdout.write(_CLI_HELP)
        raise SystemExit()
    for line in stdin:
        try:
            message = loads(line)
        except ValueError:
            stdout.write('Not JSON: {}\n\n'.format(line.rstrip(b'\n')))
            continue
        if REQUIRED_FIELDS - set(message.keys()):
            stdout.write('Not an Eliot message: {}\n\n'.format(line.rstrip(b'\n')))
            continue
        result = pretty_format(message) + '\n'
        if PY2:
            result = result.encode('utf-8')
        stdout.write(result)

def main(sys=sys):
    """Run the program.

    Accept arguments from L{sys.argv}, read from L{sys.stdin}, write to
    L{sys.stdout}.

    @param sys: An object with same interface and defaulting to the L{sys}
        module."""
    if len(sys.argv) != 2:
        sys.stderr.write(USAGE)
        return 1
    EliotFilter(sys.argv[1], sys.stdin, sys.stdout).run()
    return 0

def parse_wsgi_bind_location(bind_addr_string):
    """Convert bind address string to a BindLocation."""
    match = six.moves.urllib.parse.urlparse('//{}'.format(bind_addr_string))
    try:
        addr = match.hostname
        port = match.port
        if addr is not None or port is not None:
            return TCPSocket(addr, port)
    except ValueError:
        pass
    if bind_addr_string.startswith('@'):
        return AbstractSocket(bind_addr_string[1:])
    return UnixSocket(path=bind_addr_string)

def _assert_ssl_exc_contains(exc, *msgs):
    """Check whether SSL exception contains either of messages provided."""
    if len(msgs) < 1:
        raise TypeError('_assert_ssl_exc_contains() requires at least one message to be passed.')
    err_msg_lower = str(exc).lower()
    return any((m.lower() in err_msg_lower for m in msgs))

def extract_bytes(mv):
    """Retrieve bytes out of memoryview/buffer or bytes."""
    if isinstance(mv, memoryview):
        return mv.tobytes() if six.PY3 else bytes(mv)
    if isinstance(mv, bytes):
        return mv
    raise ValueError

def get_ssl_adapter_class(name='builtin'):
    """Return an SSL adapter class for the given name."""
    adapter = ssl_adapters[name.lower()]
    if isinstance(adapter, six.string_types):
        last_dot = adapter.rfind('.')
        attr_name = adapter[last_dot + 1:]
        mod_path = adapter[:last_dot]
        try:
            mod = sys.modules[mod_path]
            if mod is None:
                raise KeyError()
        except KeyError:
            mod = __import__(mod_path, globals(), locals(), [''])
        try:
            adapter = getattr(mod, attr_name)
        except AttributeError:
            raise AttributeError("'%s' object has no attribute '%s'" % (mod_path, attr_name))
    return adapter

def _get_last_child_with_lineno(node):
    """Return the last direct child of `node` that has a lineno attribute,
    or None if `node` has no such children.

    Almost all node._field lists are sorted by the order in which they
    appear in source code. For some nodes however, we have to skip some
    fields that either don't have line numbers (e.g., "ctx" and "names")
    or that are in the wrong position (e.g., "decorator_list" and
    "returns"). Then we choose the first field (i.e., the field with the
    highest line number) that actually contains a node. If it contains a
    list of nodes, we return the last one."""
    ignored_fields = set(['ctx', 'decorator_list', 'names', 'returns'])
    fields = node._fields
    if isinstance(node, ast.Call):
        fields = ('func', 'args', 'starargs', 'keywords', 'kwargs')
    for name in reversed(fields):
        if name in ignored_fields:
            continue
        try:
            last_field = getattr(node, name)
        except AttributeError:
            continue
        if isinstance(last_field, ast.AST):
            return last_field
        elif isinstance(last_field, list) and last_field:
            return last_field[-1]
    return None

def _safe_eval(node, default):
    """Safely evaluate the Boolean expression under the given AST node.

    Substitute `default` for all sub-expressions that cannot be
    evaluated (because variables or functions are undefined).

    We could use eval() to evaluate more sub-expressions. However, this
    function is not safe for arbitrary Python code. Even after
    overwriting the "__builtins__" dictionary, the original dictionary
    can be restored
    (https://nedbatchelder.com/blog/201206/eval_really_is_dangerous.html)."""
    if isinstance(node, ast.BoolOp):
        results = [_safe_eval(value, default) for value in node.values]
        if isinstance(node.op, ast.And):
            return all(results)
        else:
            return any(results)
    elif isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Not):
        return not _safe_eval(node.operand, not default)
    else:
        try:
            return ast.literal_eval(node)
        except ValueError:
            return default

def get_modules(paths, toplevel=True):
    """Take files from the command line even if they don't end with .py."""
    modules = []
    for path in paths:
        path = os.path.abspath(path)
        if toplevel and path.endswith('.pyc'):
            sys.exit('.pyc files are not supported: {0}'.format(path))
        if os.path.isfile(path) and (path.endswith('.py') or toplevel):
            modules.append(path)
        elif os.path.isdir(path):
            subpaths = [os.path.join(path, filename) for filename in sorted(os.listdir(path))]
            modules.extend(get_modules(subpaths, toplevel=False))
        elif toplevel:
            sys.exit('Error: {0} could not be found.'.format(path))
    return modules

def _ignore_variable(filename, varname):
    """Ignore _ (Python idiom), _x (pylint convention) and
    __x__ (special variable or method), but not __x."""
    return varname in IGNORED_VARIABLE_NAMES or (varname.startswith('_') and (not varname.startswith('__'))) or _is_special_name(varname)

