def get_hit_count_from_obj_variable(context, obj_variable, tag_name):
    """Helper function to return a HitCount for a given template object variable.

    Raises TemplateSyntaxError if the passed object variable cannot be parsed."""
    error_to_raise = template.TemplateSyntaxError("'%(a)s' requires a valid individual model variable in the form of '%(a)s for [model_obj]'.\nGot: %(b)s" % {'a': tag_name, 'b': obj_variable})
    try:
        obj = obj_variable.resolve(context)
    except template.VariableDoesNotExist:
        raise error_to_raise
    try:
        ctype = ContentType.objects.get_for_model(obj)
    except AttributeError:
        raise error_to_raise
    hit_count, created = HitCount.objects.get_or_create(content_type=ctype, object_pk=obj.pk)
    return hit_count

def return_period_from_string(arg):
    """Takes a string such as "days=1,seconds=30" and strips the quotes
    and returns a dictionary with the key/value pairs"""
    period = {}
    if arg[0] == '"' and arg[-1] == '"':
        opt = arg[1:-1]
    else:
        opt = arg
    for o in opt.split(','):
        key, value = o.split('=')
        period[str(key)] = int(value)
    return period

def py_to_couch_validate(key, val):
    """Validates the individual parameter key and value."""
    if key not in RESULT_ARG_TYPES:
        raise CloudantArgumentError(116, key)
    if not isinstance(val, RESULT_ARG_TYPES[key]) or (type(val) is bool and int in RESULT_ARG_TYPES[key]):
        raise CloudantArgumentError(117, key, RESULT_ARG_TYPES[key])
    if key == 'keys':
        for key_list_val in val:
            if not isinstance(key_list_val, RESULT_ARG_TYPES['key']) or type(key_list_val) is bool:
                raise CloudantArgumentError(134, RESULT_ARG_TYPES['key'])
    if key == 'stale':
        if val not in ('ok', 'update_after'):
            raise CloudantArgumentError(135, val)

def _py_to_couch_translate(key, val):
    """Performs the conversion of the Python parameter value to its CouchDB
    equivalent."""
    try:
        if key in ['keys', 'endkey_docid', 'startkey_docid', 'stale', 'update']:
            return {key: val}
        if val is None:
            return {key: None}
        arg_converter = TYPE_CONVERTERS.get(type(val))
        return {key: arg_converter(val)}
    except Exception as ex:
        raise CloudantArgumentError(136, key, ex)

def response_to_json_dict(response, **kwargs):
    """Standard place to convert responses to JSON.

    :param response: requests response object
    :param **kwargs: arguments accepted by json.loads

    :returns: dict of JSON response"""
    if response.encoding is None:
        response.encoding = 'utf-8'
    return json.loads(response.text, **kwargs)

def apply_kwargs(func, **kwargs):
    """Call *func* with kwargs, but only those kwargs that it accepts.
    """
    new_kwargs = {}
    params = signature(func).parameters
    for param_name in params.keys():
        if param_name in kwargs:
            new_kwargs[param_name] = kwargs[param_name]
    return func(**new_kwargs)

def args_from_config(func):
    """Decorator that injects parameters from the configuration.
    """
    func_args = signature(func).parameters
    @wraps(func)
    def wrapper(*args, **kwargs):
        config = get_config()
        for i, argname in enumerate(func_args):
            if len(args) > i or argname in kwargs:
                continue
            elif argname in config:
                kwargs[argname] = config[argname]
        try:
            getcallargs(func, *args, **kwargs)
        except TypeError as exc:
            msg = '{}\n{}'.format(exc.args[0], PALLADIUM_CONFIG_ERROR)
            exc.args = (msg,)
            raise exc
        return func(*args, **kwargs)
    wrapper.__wrapped__ = func
    return wrapper

def Partial(func, **kwargs):
    """Allows the use of partially applied functions in the
    configuration."""
    if isinstance(func, str):
        func = resolve_dotted_name(func)
    partial_func = partial(func, **kwargs)
    update_wrapper(partial_func, func)
    return partial_func

def error_message(e, message=None, cause=None):
    """Formats exception message + cause
    :param e:
    :param message:
    :param cause:
    :return: formatted message, includes cause if any is set"""
    if message is None and cause is None:
        return None
    elif message is None:
        return '%s, caused by %r' % (e.__class__, cause)
    elif cause is None:
        return message
    else:
        return '%s, caused by %r' % (message, cause)

def format_pgp_key(key):
    """Formats PGP key in 16hex digits
    :param key:
    :return:"""
    if key is None:
        return None
    if isinstance(key, (int, long)):
        return '%016x' % key
    elif isinstance(key, list):
        return [format_pgp_key(x) for x in key]
    else:
        key = key.strip()
        key = strip_hex_prefix(key)
        return format_pgp_key(int(key, 16))

def add_res(acc, elem):
    """Adds results to the accumulator
    :param acc:
    :param elem:
    :return:"""
    if not isinstance(elem, list):
        elem = [elem]
    if acc is None:
        acc = []
    for x in elem:
        acc.append(x)
    return acc

def flatten(iterable):
    """Non-recursive flatten.
    :param iterable:
    :return:"""
    try:
        iterator, sentinel, stack = (iter(iterable), object(), [])
    except TypeError:
        yield iterable
        return
    while True:
        value = next(iterator, sentinel)
        if value is sentinel:
            if not stack:
                break
            iterator = stack.pop()
        elif isinstance(value, str):
            yield value
        else:
            try:
                new_iterator = iter(value)
            except TypeError:
                yield value
            else:
                stack.append(iterator)
                iterator = new_iterator

def try_get_dn_part(subject, oid=None):
    """Tries to extracts the OID from the X500 name.
    :param subject:
    :param oid:
    :return:"""
    try:
        if subject is None:
            return None
        if oid is None:
            return None
        for sub in subject:
            if oid is not None and sub.oid == oid:
                return sub.value
    except:
        pass
    return None

def startswith(haystack, prefix):
    """py3 comp startswith
    :param haystack:
    :param prefix:
    :return:"""
    if haystack is None:
        return None
    if sys.version_info[0] < 3:
        return haystack.startswith(prefix)
    return to_bytes(haystack).startswith(to_bytes(prefix))

def to_string(x):
    """Utf8 conversion
    :param x:
    :return:"""
    if isinstance(x, bytes):
        return x.decode('utf-8')
    if isinstance(x, basestring):
        return x

def to_bytes(x):
    """Byte conv
    :param x:
    :return:"""
    if isinstance(x, bytes):
        return x
    if isinstance(x, basestring):
        return x.encode('utf-8')

def contains(haystack, needle):
    """py3 contains
    :param haystack:
    :param needle:
    :return:"""
    if sys.version_info[0] < 3:
        return needle in haystack
    else:
        return to_bytes(needle) in to_bytes(haystack)

def _unique_rows_numpy(a):
    """return unique rows"""
    a = np.ascontiguousarray(a)
    unique_a = np.unique(a.view([('', a.dtype)] * a.shape[1]))
    return unique_a.view(a.dtype).reshape((unique_a.shape[0], a.shape[1]))

def random_pairs_with_replacement(n, shape, random_state=None):
    """make random record pairs"""
    if not isinstance(random_state, np.random.RandomState):
        random_state = np.random.RandomState(random_state)
    n_max = max_pairs(shape)
    if n_max <= 0:
        raise ValueError('n_max must be larger than 0')
    indices = random_state.randint(0, n_max, n)
    if len(shape) == 1:
        return _map_tril_1d_on_2d(indices, shape[0])
    else:
        return np.unravel_index(indices, shape)

def random_pairs_without_replacement_large_frames(n, shape, random_state=None):
    """Make a sample of random pairs with replacement"""
    n_max = max_pairs(shape)
    sample = np.array([])
    while len(sample) < n:
        n_sample_size = (n - len(sample)) * 2
        sample = random_state.randint(n_max, size=n_sample_size)
        pairs_non_unique = np.append(sample, sample)
        sample = _unique_rows_numpy(pairs_non_unique)
    if len(shape) == 1:
        return _map_tril_1d_on_2d(sample[0:n], shape[0])
    else:
        return np.unravel_index(sample[0:n], shape)

def max_pairs(shape):
    """[DEPRECATED] Compute the maximum number of record pairs possible."""
    if not isinstance(shape, (tuple, list)):
        x = get_length(shape)
        n = int(x * (x - 1) / 2)
    elif isinstance(shape, (tuple, list)) and len(shape) == 1:
        x = get_length(shape[0])
        n = int(x * (x - 1) / 2)
    else:
        n = numpy.prod([get_length(xi) for xi in shape])
    return n

def _parallel_compare_helper(class_obj, pairs, x, x_link=None):
    """Internal function to overcome pickling problem in python2."""
    return class_obj._compute(pairs, x, x_link)

def chunk_pandas(frame_or_series, chunksize=None):
    """Chunk a frame into smaller, equal parts."""
    if not isinstance(chunksize, int):
        raise ValueError('argument chunksize needs to be integer type')
    bins = np.arange(0, len(frame_or_series), step=chunksize)
    for b in bins:
        yield frame_or_series[b:b + chunksize]

def is_label_dataframe(label, df):
    """check column label existance"""
    setdiff = set(label) - set(df.columns.tolist())
    if len(setdiff) == 0:
        return True
    else:
        return False

def listify(x, none_value=[]):
    """Make a list of the argument if it is not a list."""
    if isinstance(x, list):
        return x
    elif isinstance(x, tuple):
        return list(x)
    elif x is None:
        return none_value
    else:
        return [x]

def multi_index_to_frame(index):
    """Replicates MultiIndex.to_frame, which was introduced in pandas 0.21,
    for the sake of backwards compatibility."""
    return pandas.DataFrame(index.tolist(), index=index, columns=index.names)

def get_related_model(field):
    """Gets the related model from a related field"""
    model = None
    if hasattr(field, 'related_model') and field.related_model:
        model = field.related_model
    elif hasattr(field, 'rel') and field.rel:
        model = field.rel.to
    return model

