def model_field_attr(model, model_field, attr):
    """Returns the specified attribute for the specified field on the model class."""
    fields = dict([(field.name, field) for field in model._meta.fields])
    return getattr(fields[model_field], attr)

def find_fragments(base_directory, sections, fragment_directory, definitions):
    """Sections are a dictonary of section names to paths."""
    content = OrderedDict()
    fragment_filenames = []
    for key, val in sections.items():
        if fragment_directory is not None:
            section_dir = os.path.join(base_directory, val, fragment_directory)
        else:
            section_dir = os.path.join(base_directory, val)
        files = os.listdir(section_dir)
        file_content = {}
        for basename in files:
            parts = basename.split(u'.')
            counter = 0
            if len(parts) == 1:
                continue
            else:
                ticket, category = parts[:2]
            if len(parts) > 2:
                try:
                    counter = int(parts[2])
                except ValueError:
                    pass
            if category not in definitions:
                continue
            full_filename = os.path.join(section_dir, basename)
            fragment_filenames.append(full_filename)
            with open(full_filename, 'rb') as f:
                data = f.read().decode('utf8', 'replace')
            if (ticket, category, counter) in file_content:
                raise ValueError('multiple files for {}.{} in {}'.format(ticket, category, section_dir))
            file_content[ticket, category, counter] = data
        content[key] = file_content
    return (content, fragment_filenames)

def indent(text, prefix):
    """Adds `prefix` to the beginning of non-empty lines in `text`."""
    def prefixed_lines():
        for line in text.splitlines(True):
            yield (prefix + line if line.strip() else line)
    return u''.join(prefixed_lines())

def render_fragments(template, issue_format, fragments, definitions, underlines, wrap):
    """Render the fragments into a news file."""
    jinja_template = Template(template, trim_blocks=True)
    data = OrderedDict()
    for section_name, section_value in fragments.items():
        data[section_name] = OrderedDict()
        for category_name, category_value in section_value.items():
            entries = []
            for text, issues in category_value.items():
                entries.append((text, sorted(issues, key=issue_key)))
            entries.sort(key=entry_key)
            categories = OrderedDict()
            for text, issues in entries:
                rendered = [render_issue(issue_format, i) for i in issues]
                categories[text] = rendered
            data[section_name][category_name] = categories
    done = []
    res = jinja_template.render(sections=data, definitions=definitions, underlines=underlines)
    for line in res.split(u'\n'):
        if wrap:
            done.append(textwrap.fill(line, width=79, subsequent_indent=u'  ', break_long_words=False, break_on_hyphens=False))
        else:
            done.append(line)
    return u'\n'.join(done).rstrip() + u'\n'

def stringify_values(data):
    """Coerce iterable values to 'val1,val2,valN'

    Example:
        fields=['nickname', 'city', 'can_see_all_posts']
        --> fields='nickname,city,can_see_all_posts'

    :param data: dict
    :return: converted values dict"""
    if not isinstance(data, dict):
        raise ValueError('Data must be dict. %r is passed' % data)
    values_dict = {}
    for key, value in data.items():
        items = []
        if isinstance(value, six.string_types):
            items.append(value)
        elif isinstance(value, Iterable):
            for v in value:
                if isinstance(v, int):
                    v = str(v)
                try:
                    item = six.u(v)
                except TypeError:
                    item = v
                items.append(item)
            value = ','.join(items)
        values_dict[key] = value
    return values_dict

def parse_form_action_url(html, parser=None):
    """Parse <form action="(.+)"> url

    :param html: str: raw html text
    :param parser: bs4.BeautifulSoup: html parser
    :return: url str: for example: /login.php?act=security_check&to=&hash=12346"""
    if parser is None:
        parser = bs4.BeautifulSoup(html, 'html.parser')
    forms = parser.find_all('form')
    if not forms:
        raise VkParseError('Action form is not found in the html \n%s' % html)
    if len(forms) > 1:
        raise VkParseError('Find more than 1 forms to handle:\n%s', forms)
    form = forms[0]
    return form.get('action')

def parse_masked_phone_number(html, parser=None):
    """Get masked phone number from security check html

    :param html: str: raw html text
    :param parser: bs4.BeautifulSoup: html parser
    :return: tuple of phone prefix and suffix, for example: ('+1234', '89')
    :rtype : tuple"""
    if parser is None:
        parser = bs4.BeautifulSoup(html, 'html.parser')
    fields = parser.find_all('span', {'class': 'field_prefix'})
    if not fields:
        raise VkParseError('No <span class="field_prefix">...</span> in the \n%s' % html)
    result = []
    for f in fields:
        value = f.get_text().replace(six.u('\xa0'), '')
        result.append(value)
    return tuple(result)

def load_json(filename: str) -> Union[List, Dict]:
    """Load JSON data from a file and return as dict or list.

    Defaults to returning empty dict if file is not found."""
    try:
        with open(filename, encoding='utf-8') as fdesc:
            return json.loads(fdesc.read())
    except FileNotFoundError:
        _LOGGER.debug('JSON file not found: %s', filename)
    except ValueError as error:
        _LOGGER.exception('Could not parse JSON content: %s', filename)
        raise PytradfriError(error)
    except OSError as error:
        _LOGGER.exception('JSON file reading failed: %s', filename)
        raise PytradfriError(error)
    return {}

def _process_output(output, parse_json=True):
    """Process output."""
    output = output.strip()
    _LOGGER.debug('Received: %s', output)
    if not output:
        return None
    elif 'decrypt_verify' in output:
        raise RequestError('Please compile coap-client without debug output. See instructions at https://github.com/ggravlingen/pytradfri#installation')
    elif output.startswith(CLIENT_ERROR_PREFIX):
        raise ClientError(output)
    elif output.startswith(SERVER_ERROR_PREFIX):
        raise ServerError(output)
    elif not parse_json:
        return output
    return json.loads(output)

def retry_timeout(api, retries=3):
    """Retry API call when a timeout occurs."""
    @wraps(api)
    def retry_api(*args, **kwargs):
        """Retrying API."""
        for i in range(1, retries + 1):
            try:
                return api(*args, **kwargs)
            except RequestTimeout:
                if i == retries:
                    raise
    return retry_api

def _process_output(res, parse_json=True):
    """Process output."""
    res_payload = res.payload.decode('utf-8')
    output = res_payload.strip()
    _LOGGER.debug('Status: %s, Received: %s', res.code, output)
    if not output:
        return None
    if not res.code.is_successful():
        if 128 <= res.code < 160:
            raise ClientError(output)
        elif 160 <= res.code < 192:
            raise ServerError(output)
    if not parse_json:
        return output
    return json.loads(output)

