def _join(*args):
    """Join S3 bucket args together.

    Remove empty entries and strip left-leading ``/``"""
    return delimiter.join(filter(lambda s: s != '', map(lambda s: s.lstrip(delimiter), args)))

def process_has_args(cls, kwargs):
    """loop through has parameters check they correspond to class rels defined"""
    rel_definitions = cls.defined_properties(properties=False, rels=True, aliases=False)
    match, dont_match = ({}, {})
    for key, value in kwargs.items():
        if key not in rel_definitions:
            raise ValueError('No such relation {0} defined on a {1}'.format(key, cls.__name__))
        rhs_ident = key
        rel_definitions[key]._lookup_node_class()
        if value is True:
            match[rhs_ident] = rel_definitions[key].definition
        elif value is False:
            dont_match[rhs_ident] = rel_definitions[key].definition
        elif isinstance(value, NodeSet):
            raise NotImplementedError('Not implemented yet')
        else:
            raise ValueError('Expecting True / False / NodeSet got: ' + repr(value))
    return (match, dont_match)

def install_labels(cls, quiet=True, stdout=None):
    """Setup labels with indexes and constraints for a given class

    :param cls: StructuredNode class
    :type: class
    :param quiet: (default true) enable standard output
    :param stdout: stdout stream
    :type: bool
    :return: None"""
    if not hasattr(cls, '__label__'):
        if not quiet:
            stdout.write(' ! Skipping class {0}.{1} is abstract\n'.format(cls.__module__, cls.__name__))
        return
    for name, property in cls.defined_properties(aliases=False, rels=False).items():
        db_property = property.db_property or name
        if property.index:
            if not quiet:
                stdout.write(' + Creating index {0} on label {1} for class {2}.{3}\n'.format(name, cls.__label__, cls.__module__, cls.__name__))
            db.cypher_query('CREATE INDEX on :{0}({1}); '.format(cls.__label__, db_property))
        elif property.unique_index:
            if not quiet:
                stdout.write(' + Creating unique constraint for {0} on label {1} for class {2}.{3}\n'.format(name, cls.__label__, cls.__module__, cls.__name__))
            db.cypher_query('CREATE CONSTRAINT on (n:{0}) ASSERT n.{1} IS UNIQUE; '.format(cls.__label__, db_property))

def deprecated(will_be=None, on_version=None, name=None):
    """Function decorator that warns about deprecation upon function invocation.
    :param will_be: str representing the target action on the deprecated function
    :param on_version: tuple representing a SW version
    :param name: name of the entity to be deprecated (useful when decorating
    __init__ methods so you can specify the deprecated class name)
    :return: callable"""
    def outer_function(function):
        if name is None:
            _name = function.__name__
        else:
            _name = name
        warning_msg = '"%s" is deprecated.' % _name
        if will_be is not None and on_version is not None:
            warning_msg += ' It will be %s on version %s' % (will_be, '.'.join(map(str, on_version)))
        @wraps(function)
        def inner_function(*args, **kwargs):
            warnings.warn(warning_msg, category=DeprecationWarning, stacklevel=2)
            return function(*args, **kwargs)
        return inner_function
    return outer_function

def kelvin_dict_to(d, target_temperature_unit):
    """Converts all the values in a dict from Kelvin temperatures to the
    specified temperature format.

    :param d: the dictionary containing Kelvin temperature values
    :type d: dict
    :param target_temperature_unit: the target temperature unit, may be:
        'celsius' or 'fahrenheit'
    :type target_temperature_unit: str
    :returns: a dict with the same keys as the input dict and converted
        temperature values as values
    :raises: *ValueError* when unknown target temperature units are provided"""
    if target_temperature_unit == 'kelvin':
        return d
    elif target_temperature_unit == 'celsius':
        return {key: kelvin_to_celsius(d[key]) for key in d}
    elif target_temperature_unit == 'fahrenheit':
        return {key: kelvin_to_fahrenheit(d[key]) for key in d}
    else:
        raise ValueError('Invalid value for target temperature conversion                          unit')

def kelvin_to_celsius(kelvintemp):
    """Converts a numeric temperature from Kelvin degrees to Celsius degrees

    :param kelvintemp: the Kelvin temperature
    :type kelvintemp: int/long/float
    :returns: the float Celsius temperature
    :raises: *TypeError* when bad argument types are provided"""
    if kelvintemp < 0:
        raise ValueError(__name__ + ': negative temperature values not allowed')
    celsiustemp = kelvintemp - KELVIN_OFFSET
    return float('{0:.2f}'.format(celsiustemp))

def kelvin_to_fahrenheit(kelvintemp):
    """Converts a numeric temperature from Kelvin degrees to Fahrenheit degrees

    :param kelvintemp: the Kelvin temperature
    :type kelvintemp: int/long/float
    :returns: the float Fahrenheit temperature

    :raises: *TypeError* when bad argument types are provided"""
    if kelvintemp < 0:
        raise ValueError(__name__ + ': negative temperature values not allowed')
    fahrenheittemp = (kelvintemp - KELVIN_OFFSET) * FAHRENHEIT_DEGREE_SCALE + FAHRENHEIT_OFFSET
    return float('{0:.2f}'.format(fahrenheittemp))

def timeformat(timeobject, timeformat):
    """Formats the specified time object to the target format type.

    :param timeobject: the object conveying the time value
    :type timeobject: int, ``datetime.datetime`` or ISO8601-formatted
        string with pattern ``YYYY-MM-DD HH:MM:SS+00``
    :param timeformat: the target format for the time conversion. May be:
        '*unix*' (outputs an int UNIXtime), '*date*' (outputs a
        ``datetime.datetime`` object) or '*iso*' (outputs an ISO8601-formatted
        string with pattern ``YYYY-MM-DD HH:MM:SS+00``)
    :type timeformat: str
    :returns: the formatted time
    :raises: ValueError when unknown timeformat switches are provided or
        when negative time values are provided"""
    if timeformat == 'unix':
        return to_UNIXtime(timeobject)
    elif timeformat == 'iso':
        return to_ISO8601(timeobject)
    elif timeformat == 'date':
        return to_date(timeobject)
    else:
        raise ValueError('Invalid value for timeformat parameter')

def to_date(timeobject):
    """Returns the ``datetime.datetime`` object corresponding to the time value
    conveyed by the specified object, which can be either a UNIXtime, a
    ``datetime.datetime`` object or an ISO8601-formatted string in the format
    `YYYY-MM-DD HH:MM:SS+00``.

    :param timeobject: the object conveying the time value
    :type timeobject: int, ``datetime.datetime`` or ISO8601-formatted
        string
    :returns: a ``datetime.datetime`` object
    :raises: *TypeError* when bad argument types are provided, *ValueError*
        when negative UNIXtimes are provided"""
    if isinstance(timeobject, int):
        if timeobject < 0:
            raise ValueError('The time value is a negative number')
        return datetime.utcfromtimestamp(timeobject).replace(tzinfo=UTC())
    elif isinstance(timeobject, datetime):
        return timeobject.replace(tzinfo=UTC())
    elif isinstance(timeobject, str):
        return datetime.strptime(timeobject, '%Y-%m-%d %H:%M:%S+00').replace(tzinfo=UTC())
    else:
        raise TypeError('The time value must be expressed either by an int UNIX time, a datetime.datetime object or an ISO8601-formatted string')

def to_UNIXtime(timeobject):
    """Returns the UNIXtime corresponding to the time value conveyed by the
    specified object, which can be either a UNIXtime, a
    ``datetime.datetime`` object or an ISO8601-formatted string in the format
    `YYYY-MM-DD HH:MM:SS+00``.

    :param timeobject: the object conveying the time value
    :type timeobject: int, ``datetime.datetime`` or ISO8601-formatted
        string
    :returns: an int UNIXtime
    :raises: *TypeError* when bad argument types are provided, *ValueError*
        when negative UNIXtimes are provided"""
    if isinstance(timeobject, int):
        if timeobject < 0:
            raise ValueError('The time value is a negative number')
        return timeobject
    elif isinstance(timeobject, datetime):
        return _datetime_to_UNIXtime(timeobject)
    elif isinstance(timeobject, str):
        return _ISO8601_to_UNIXtime(timeobject)
    else:
        raise TypeError('The time value must be expressed either by an int UNIX time, a datetime.datetime object or an ISO8601-formatted string')

def mul(left, right):
    """Distribution multiplication.

    Args:
        left (Dist, numpy.ndarray) : left hand side.
        right (Dist, numpy.ndarray) : right hand side."""
    from .mv_mul import MvMul
    length = max(left, right)
    if length == 1:
        return Mul(left, right)
    return MvMul(left, right)

def identify_core(core):
    """Identify the polynomial argument."""
    for datatype, identifier in {int: _identify_scaler, numpy.int8: _identify_scaler, numpy.int16: _identify_scaler, numpy.int32: _identify_scaler, numpy.int64: _identify_scaler, float: _identify_scaler, numpy.float16: _identify_scaler, numpy.float32: _identify_scaler, numpy.float64: _identify_scaler, chaospy.poly.base.Poly: _identify_poly, dict: _identify_dict, numpy.ndarray: _identify_iterable, list: _identify_iterable, tuple: _identify_iterable}.items():
        if isinstance(core, datatype):
            return identifier(core)
    raise TypeError("Poly arg: 'core' is not a valid type " + repr(core))

def _identify_poly(core):
    """Specification for a polynomial."""
    return (core.A, core.dim, core.shape, core.dtype)

def _identify_dict(core):
    """Specification for a dictionary."""
    if not core:
        return ({}, 1, (), int)
    core = core.copy()
    key = sorted(core.keys(), key=chaospy.poly.base.sort_key)[0]
    shape = numpy.array(core[key]).shape
    dtype = numpy.array(core[key]).dtype
    dim = len(key)
    return (core, dim, shape, dtype)

def _identify_iterable(core):
    """Specification for a list, tuple, numpy.ndarray."""
    if isinstance(core, numpy.ndarray) and (not core.shape):
        return ({(0,): core}, 1, (), core.dtype)
    core = [chaospy.poly.base.Poly(a) for a in core]
    shape = (len(core),) + core[0].shape
    dtype = chaospy.poly.typing.dtyping(*[_.dtype for _ in core])
    dims = numpy.array([a.dim for a in core])
    dim = numpy.max(dims)
    if dim != numpy.min(dims):
        core = [chaospy.poly.dimension.setdim(a, dim) for a in core]
    out = {}
    for idx, core_ in enumerate(core):
        for key in core_.keys:
            if not key in out:
                out[key] = numpy.zeros(shape, dtype=dtype)
            out[key][idx] = core_.A[key]
    return (out, dim, shape, dtype)

def rollaxis(vari, axis, start=0):
    """Roll the specified axis backwards, until it lies in a given position.

    Args:
        vari (chaospy.poly.base.Poly, numpy.ndarray):
            Input array or polynomial.
        axis (int):
            The axis to roll backwards. The positions of the other axes do not
            change relative to one another.
        start (int):
            The axis is rolled until it lies before thes position."""
    if isinstance(vari, Poly):
        core_old = vari.A.copy()
        core_new = {}
        for key in vari.keys:
            core_new[key] = rollaxis(core_old[key], axis, start)
        return Poly(core_new, vari.dim, None, vari.dtype)
    return numpy.rollaxis(vari, axis, start)

def swapaxes(vari, ax1, ax2):
    """Interchange two axes of a polynomial."""
    if isinstance(vari, Poly):
        core = vari.A.copy()
        for key in vari.keys:
            core[key] = swapaxes(core[key], ax1, ax2)
        return Poly(core, vari.dim, None, vari.dtype)
    return numpy.swapaxes(vari, ax1, ax2)

def roll(vari, shift, axis=None):
    """Roll array elements along a given axis."""
    if isinstance(vari, Poly):
        core = vari.A.copy()
        for key in vari.keys:
            core[key] = roll(core[key], shift, axis)
        return Poly(core, vari.dim, None, vari.dtype)
    return numpy.roll(vari, shift, axis)

def preprocess(core, dim, shape, dtype):
    """Constructor function for the Poly class."""
    core, dim_, shape_, dtype_ = chaospy.poly.constructor.identify_core(core)
    core, shape = chaospy.poly.constructor.ensure_shape(core, shape, shape_)
    core, dtype = chaospy.poly.constructor.ensure_dtype(core, dtype, dtype_)
    core, dim = chaospy.poly.constructor.ensure_dim(core, dim, dim_)
    for key in list(core.keys()):
        if np.all(core[key] == 0):
            del core[key]
    assert isinstance(dim, int), "not recognised type for dim: '%s'" % repr(type(dim))
    assert isinstance(shape, tuple), str(shape)
    assert dtype is not None, str(dtype)
    if not core:
        core = {(0,) * dim: np.zeros(shape, dtype=dtype)}
    else:
        core = {key: np.asarray(value, dtype) for key, value in core.items()}
    return (core, dim, shape, dtype)

def cleanup(arg):
    """Clean up the input variable."""
    arg = numpy.asarray(arg)
    if len(arg.shape) <= 1:
        arg = arg.reshape(arg.size, 1)
    elif len(arg.shape) > 2:
        raise ValueError('shapes must be smaller than 3')
    return arg

def ensure_shape(core, shape, shape_):
    """Ensure shape is correct."""
    core = core.copy()
    if shape is None:
        shape = shape_
    elif isinstance(shape, int):
        shape = (shape,)
    if tuple(shape) == tuple(shape_):
        return (core, shape)
    ones = np.ones(shape, dtype=int)
    for key, val in core.items():
        core[key] = val * ones
    return (core, shape)

def ensure_dtype(core, dtype, dtype_):
    """Ensure dtype is correct."""
    core = core.copy()
    if dtype is None:
        dtype = dtype_
    if dtype_ == dtype:
        return (core, dtype)
    for key, val in {int: chaospy.poly.typing.asint, float: chaospy.poly.typing.asfloat, np.float32: chaospy.poly.typing.asfloat, np.float64: chaospy.poly.typing.asfloat}.items():
        if dtype == key:
            converter = val
            break
    else:
        raise ValueError('dtype not recognised (%s)' % str(dtype))
    for key, val in core.items():
        core[key] = converter(val)
    return (core, dtype)

def ensure_dim(core, dim, dim_):
    """Ensure that dim is correct."""
    if dim is None:
        dim = dim_
    if not dim:
        return (core, 1)
    if dim_ == dim:
        return (core, int(dim))
    if dim > dim_:
        key_convert = lambda vari: vari[:dim_]
    else:
        key_convert = lambda vari: vari + (0,) * (dim - dim_)
    new_core = {}
    for key, val in core.items():
        key_ = key_convert(key)
        if key_ in new_core:
            new_core[key_] += val
        else:
            new_core[key_] = val
    return (new_core, int(dim))

def sort_key(val):
    """Sort key for sorting keys in grevlex order."""
    return numpy.sum((max(val) + 1) ** numpy.arange(len(val) - 1, -1, -1) * val)

def deprecation_warning(func, name):
    """Add a deprecation warning do each distribution."""
    @wraps(func)
    def caller(*args, **kwargs):
        """Docs to be replaced."""
        logger = logging.getLogger(__name__)
        instance = func(*args, **kwargs)
        logger.warning('Distribution `chaospy.{}` has been renamed to '.format(name) + '`chaospy.{}` and will be deprecated next release.'.format(instance.__class__.__name__))
        return instance
    return caller

def dtyping(*args):
    """Find least common denominator dtype.

    Examples:
        >>> str(dtyping(int, float)) in ("<class 'float'>", "<type 'float'>")
        True
        >>> print(dtyping(int, Poly))
        <class 'chaospy.poly.base.Poly'>"""
    args = list(args)
    for idx, arg in enumerate(args):
        if isinstance(arg, Poly):
            args[idx] = Poly
        elif isinstance(arg, numpy.generic):
            args[idx] = numpy.asarray(arg).dtype
        elif isinstance(arg, (float, int)):
            args[idx] = type(arg)
    for type_ in DATATYPES:
        if type_ in args:
            return type_
    raise ValueError('dtypes not recognised ' + str([str(_) for _ in args]))

def asfloat(vari, limit=None):
    """Convert dtype of polynomial coefficients to float.

    Example:
        >>> poly = 2*cp.variable()+1
        >>> print(poly)
        2q0+1
        >>> print(cp.asfloat(poly))
        2.0q0+1.0"""
    if limit is None:
        limit = 10 ** 300
    if isinstance(vari, Poly):
        core = vari.A.copy()
        for key in vari.keys:
            core[key] = core[key] * 1.0
        return Poly(core, vari.dim, vari.shape, float)
    return numpy.asfarray(vari)

def asint(vari):
    """Convert dtype of polynomial coefficients to float.

    Example:
        >>> poly = 1.5*cp.variable()+2.25
        >>> print(poly)
        1.5q0+2.25
        >>> print(cp.asint(poly))
        q0+2"""
    if isinstance(vari, Poly):
        core = vari.A.copy()
        for key in vari.keys:
            core[key] = numpy.asarray(core[key], dtype=int)
        return Poly(core, vari.dim, vari.shape, int)
    return numpy.asarray(vari, dtype=int)

def _gill_king(mat, beta, delta):
    """Backend function for the Gill-King algorithm."""
    size = mat.shape[0]
    if scipy.sparse.issparse(mat):
        lowtri = scipy.sparse.eye(*mat.shape)
    else:
        lowtri = numpy.eye(size)
    d_vec = numpy.zeros(size, dtype=float)
    for idx in range(size):
        if idx == 0:
            idz = []
        else:
            idz = numpy.s_[:idx]
        djtemp = mat[idx, idx] - numpy.dot(lowtri[idx, idz], d_vec[idz] * lowtri[idx, idz].T)
        if idx < size - 1:
            idy = numpy.s_[idx + 1:size]
            ccol = mat[idy, idx] - numpy.dot(lowtri[idy, idz], d_vec[idz] * lowtri[idx, idz].T)
            theta = abs(ccol).max()
            d_vec[idx] = max(abs(djtemp), (theta / beta) ** 2, delta)
            lowtri[idy, idx] = ccol / d_vec[idx]
        else:
            d_vec[idx] = max(abs(djtemp), delta)
    for idx in range(size):
        lowtri[:, idx] = lowtri[:, idx] * numpy.sqrt(d_vec[idx])
    return lowtri

def _stieltjes_analytical(dist, order, normed):
    """Stieltjes' method with analytical recurrence coefficients."""
    dimensions = len(dist)
    mom_order = numpy.arange(order + 1).repeat(dimensions)
    mom_order = mom_order.reshape(order + 1, dimensions).T
    coeff1, coeff2 = dist.ttr(mom_order)
    coeff2[:, 0] = 1.0
    poly = chaospy.poly.collection.core.variable(dimensions)
    if normed:
        orth = [poly ** 0 * numpy.ones(dimensions), (poly - coeff1[:, 0]) / numpy.sqrt(coeff2[:, 1])]
        for order_ in range(1, order):
            orth.append((orth[-1] * (poly - coeff1[:, order_]) - orth[-2] * numpy.sqrt(coeff2[:, order_])) / numpy.sqrt(coeff2[:, order_ + 1]))
        norms = numpy.ones(coeff2.shape)
    else:
        orth = [poly - poly, poly ** 0 * numpy.ones(dimensions)]
        for order_ in range(order):
            orth.append(orth[-1] * (poly - coeff1[:, order_]) - orth[-2] * coeff2[:, order_])
        orth = orth[1:]
        norms = numpy.cumprod(coeff2, 1)
    return (orth, norms, coeff1, coeff2)

def set_state(seed_value=None, step=None):
    """Set random seed."""
    global RANDOM_SEED
    if seed_value is not None:
        RANDOM_SEED = seed_value
    if step is not None:
        RANDOM_SEED += step

def create_mv_rule(tensorprod_rule, dim):
    """Convert tensor product rule into a multivariate quadrature generator."""
    def mv_rule(order, sparse=False, part=None):
        """Multidimensional integration rule.

        Args:
            order (int, numpy.ndarray) : order of integration rule. If numpy.ndarray,
                order along each axis.
            sparse (bool) : use Smolyak sparse grid.

        Returns:
            (numpy.ndarray, numpy.ndarray) abscissas and weights."""
        if sparse:
            order = numpy.ones(dim, dtype=int) * order
            tensorprod_rule_ = lambda order, part=part: tensorprod_rule(order, part=part)
            return chaospy.quad.sparse_grid(tensorprod_rule_, order)
        return tensorprod_rule(order, part=part)
    return mv_rule

def differential(P, Q):
    """Polynomial differential operator.

    Args:
        P (Poly):
            Polynomial to be differentiated.
        Q (Poly):
            Polynomial to differentiate by. Must be decomposed. If polynomial
            array, the output is the Jacobian matrix."""
    P, Q = (Poly(P), Poly(Q))
    if not chaospy.poly.is_decomposed(Q):
        differential(chaospy.poly.decompose(Q)).sum(0)
    if Q.shape:
        return Poly([differential(P, q) for q in Q])
    if Q.dim > P.dim:
        P = chaospy.poly.setdim(P, Q.dim)
    else:
        Q = chaospy.poly.setdim(Q, P.dim)
    qkey = Q.keys[0]
    A = {}
    for key in P.keys:
        newkey = numpy.array(key) - numpy.array(qkey)
        if numpy.any(newkey < 0):
            continue
        A[tuple(newkey)] = P.A[key] * numpy.prod([fac(key[i], exact=True) / fac(newkey[i], exact=True) for i in range(P.dim)])
    return Poly(B, P.dim, P.shape, P.dtype)

def tril(P, k=0):
    """Lower triangle of coefficients."""
    A = P.A.copy()
    for key in P.keys:
        A[key] = numpy.tril(P.A[key])
    return Poly(A, dim=P.dim, shape=P.shape)

def tricu(P, k=0):
    """Cross-diagonal upper triangle."""
    tri = numpy.sum(numpy.mgrid[[slice(0, _, 1) for _ in P.shape]], 0)
    tri = tri < len(tri) + k
    if isinstance(P, Poly):
        A = P.A.copy()
        B = {}
        for key in P.keys:
            B[key] = A[key] * tri
        return Poly(B, shape=P.shape, dim=P.dim, dtype=P.dtype)
    out = P * tri
    return out

def all(A, ax=None):
    """Test if all values in A evaluate to True"""
    if isinstance(A, Poly):
        out = numpy.zeros(A.shape, dtype=bool)
        B = A.A
        for key in A.keys:
            out += all(B[key], ax)
        return out
    return numpy.all(A, ax)

def diag(A, k=0):
    """Extract or construct a diagonal polynomial array."""
    if isinstance(A, Poly):
        core, core_new = (A.A, {})
        for key in A.keys:
            core_new[key] = numpy.diag(core[key], k)
        return Poly(core_new, A.dim, None, A.dtype)
    return numpy.diag(A, k)

def remove_prohibited_element(tag_name, document_element):
