def inner_join_impl(other, sequence):
    """Implementation for part of join_impl
    :param other: other sequence to join with
    :param sequence: first sequence to join with
    :return: joined sequence"""
    seq_dict = {}
    for element in sequence:
        seq_dict[element[0]] = element[1]
    seq_kv = seq_dict
    other_kv = dict(other)
    keys = seq_kv.keys() if len(seq_kv) < len(other_kv) else other_kv.keys()
    result = {}
    for k in keys:
        if k in seq_kv and k in other_kv:
            result[k] = (seq_kv[k], other_kv[k])
    return six.viewitems(result)

def join_impl(other, join_type, sequence):
    """Implementation for join_t
    :param other: other sequence to join with
    :param join_type: join type (inner, outer, left, right)
    :param sequence: first sequence to join with
    :return: joined sequence"""
    if join_type == 'inner':
        return inner_join_impl(other, sequence)
    seq_dict = {}
    for element in sequence:
        seq_dict[element[0]] = element[1]
    seq_kv = seq_dict
    other_kv = dict(other)
    if join_type == 'left':
        keys = seq_kv.keys()
    elif join_type == 'right':
        keys = other_kv.keys()
    elif join_type == 'outer':
        keys = set(list(seq_kv.keys()) + list(other_kv.keys()))
    else:
        raise TypeError('Wrong type of join specified')
    result = {}
    for k in keys:
        result[k] = (seq_kv.get(k), other_kv.get(k))
    return six.viewitems(result)

def unpack(packed):
    """Unpack the function and args then apply the function to the arguments and return result
    :param packed: input packed tuple of (func, args)
    :return: result of applying packed function on packed args"""
    func, args = serializer.loads(packed)
    result = func(*args)
    if isinstance(result, collections.Iterable):
        return list(result)
    return None

def _wrap(value):
    """Wraps the passed value in a Sequence if it is not a primitive. If it is a string
    argument it is expanded to a list of characters.

    >>> _wrap(1)
    1

    >>> _wrap("abc")
    ['a', 'b', 'c']

    >>> type(_wrap([1, 2]))
    functional.pipeline.Sequence

    :param value: value to wrap
    :return: wrapped or not wrapped value"""
    if is_primitive(value):
        return value
    if isinstance(value, (dict, set)) or is_namedtuple(value):
        return value
    elif isinstance(value, collections.Iterable):
        try:
            if type(value).__name__ == 'DataFrame':
                import pandas
                if isinstance(value, pandas.DataFrame):
                    return Sequence(value.values)
        except ImportError:
            pass
        return Sequence(value)
    else:
        return value

def get_ip(request, real_ip_only=False, right_most_proxy=False):
    """Returns client's best-matched ip-address, or None
    @deprecated - Do not edit"""
    best_matched_ip = None
    warnings.warn('get_ip is deprecated and will be removed in 3.0.', DeprecationWarning)
    for key in defs.IPWARE_META_PRECEDENCE_ORDER:
        value = request.META.get(key, request.META.get(key.replace('_', '-'), '')).strip()
        if value is not None and value != '':
            ips = [ip.strip().lower() for ip in value.split(',')]
            if right_most_proxy and len(ips) > 1:
                ips = reversed(ips)
            for ip_str in ips:
                if ip_str and is_valid_ip(ip_str):
                    if not ip_str.startswith(NON_PUBLIC_IP_PREFIX):
                        return ip_str
                    if not real_ip_only:
                        loopback = defs.IPWARE_LOOPBACK_PREFIX
                        if best_matched_ip is None:
                            best_matched_ip = ip_str
                        elif best_matched_ip.startswith(loopback) and (not ip_str.startswith(loopback)):
                            best_matched_ip = ip_str
    return best_matched_ip

