def docker_run(ctx, docker_run_args, help):
    """Simple docker wrapper that adds WANDB_API_KEY and WANDB_DOCKER to any docker run command.
    This will also set the runtime to nvidia if the nvidia-docker executable is present on the system
    and --runtime wasn't set."""
    args = list(docker_run_args)
    if len(args) > 0 and args[0] == 'run':
        args.pop(0)
    if help or len(args) == 0:
        wandb.termlog('This commands adds wandb env variables to your docker run calls')
        subprocess.call(['docker', 'run'] + args + ['--help'])
        exit()
    if len([a for a in args if a.startswith('--runtime')]) == 0 and find_executable('nvidia-docker'):
        args = ['--runtime', 'nvidia'] + args
    image = util.image_from_docker_args(args)
    resolved_image = None
    if image:
        resolved_image = wandb.docker.image_id(image)
    if resolved_image:
        args = ['-e', 'WANDB_DOCKER=%s' % resolved_image] + args
    else:
        wandb.termlog("Couldn't detect image argument, running command without the WANDB_DOCKER env variable")
    if api.api_key:
        args = ['-e', 'WANDB_API_KEY=%s' % api.api_key] + args
    else:
        wandb.termlog('Not logged in, run `wandb login` from the host machine to enable result logging')
    subprocess.call(['docker', 'run'] + args)

def _bisearch(ucs, table):
    """Auxiliary function for binary search in interval table.

    :arg int ucs: Ordinal value of unicode character.
    :arg list table: List of starting and ending ranges of ordinal values,
        in form of ``[(start, end), ...]``.
    :rtype: int
    :returns: 1 if ordinal value ucs is found within lookup table, else 0."""
    lbound = 0
    ubound = len(table) - 1
    if ucs < table[0][0] or ucs > table[ubound][1]:
        return 0
    while ubound >= lbound:
        mid = (lbound + ubound) // 2
        if ucs > table[mid][1]:
            lbound = mid + 1
        elif ucs < table[mid][0]:
            ubound = mid - 1
        else:
            return 1
    return 0

def token_list_len(tokenlist):
    """Return the amount of characters in this token list.

    :param tokenlist: List of (token, text) or (token, text, mouse_handler)
                      tuples."""
    ZeroWidthEscape = Token.ZeroWidthEscape
    return sum((len(item[1]) for item in tokenlist if item[0] != ZeroWidthEscape))

def token_list_to_text(tokenlist):
    """Concatenate all the text parts again."""
    ZeroWidthEscape = Token.ZeroWidthEscape
    return ''.join((item[1] for item in tokenlist if item[0] != ZeroWidthEscape))

def iter_token_lines(tokenlist):
    """Iterator that yields tokenlists for each line."""
    line = []
    for token, c in explode_tokens(tokenlist):
        line.append((token, c))
        if c == '\n':
            yield line
            line = []
    yield line

def split_lines(tokenlist):
    """Take a single list of (Token, text) tuples and yield one such list for each
    line. Just like str.split, this will yield at least one item.

    :param tokenlist: List of (token, text) or (token, text, mouse_handler)
                      tuples."""
    line = []
    for item in tokenlist:
        if len(item) == 2:
            token, string = item
            parts = string.split('\n')
            for part in parts[:-1]:
                if part:
                    line.append((token, part))
                yield line
                line = []
            line.append((token, parts[-1]))
        else:
            token, string, mouse_handler = item
            parts = string.split('\n')
            for part in parts[:-1]:
                if part:
                    line.append((token, part, mouse_handler))
                yield line
                line = []
            line.append((token, parts[-1], mouse_handler))
    yield line

def explode_tokens(tokenlist):
    """Turn a list of (token, text) tuples into another list where each string is
    exactly one character.

    It should be fine to call this function several times. Calling this on a
    list that is already exploded, is a null operation.

    :param tokenlist: List of (token, text) tuples."""
    if getattr(tokenlist, 'exploded', False):
        return tokenlist
    result = []
    for token, string in tokenlist:
        for c in string:
            result.append((token, c))
    return _ExplodedList(result)

def find_window_for_buffer_name(cli, buffer_name):
    """Look for a :class:`~prompt_toolkit.layout.containers.Window` in the Layout
    that contains the :class:`~prompt_toolkit.layout.controls.BufferControl`
    for the given buffer and return it. If no such Window is found, return None."""
    from prompt_toolkit.interface import CommandLineInterface
    assert isinstance(cli, CommandLineInterface)
    from .containers import Window
    from .controls import BufferControl
    for l in cli.layout.walk(cli):
        if isinstance(l, Window) and isinstance(l.content, BufferControl):
            if l.content.buffer_name == buffer_name:
                return l

def scroll_forward(event, half=False):
    """Scroll window down."""
    w = _current_window_for_event(event)
    b = event.cli.current_buffer
    if w and w.render_info:
        info = w.render_info
        ui_content = info.ui_content
        scroll_height = info.window_height
        if half:
            scroll_height //= 2
        y = b.document.cursor_position_row + 1
        height = 0
        while y < ui_content.line_count:
            line_height = info.get_height_for_line(y)
            if height + line_height < scroll_height:
                height += line_height
                y += 1
            else:
                break
        b.cursor_position = b.document.translate_row_col_to_index(y, 0)

def scroll_one_line_down(event):
    """scroll_offset += 1"""
    w = find_window_for_buffer_name(event.cli, event.cli.current_buffer_name)
    b = event.cli.current_buffer
    if w:
        if w.render_info:
            info = w.render_info
            if w.vertical_scroll < info.content_height - info.window_height:
                if info.cursor_position.y <= info.configured_scroll_offsets.top:
                    b.cursor_position += b.document.get_cursor_down_position()
                w.vertical_scroll += 1

def scroll_one_line_up(event):
    """scroll_offset -= 1"""
    w = find_window_for_buffer_name(event.cli, event.cli.current_buffer_name)
    b = event.cli.current_buffer
    if w:
        if w.render_info:
            info = w.render_info
            if w.vertical_scroll > 0:
                first_line_height = info.get_height_for_line(info.first_visible_line())
                cursor_up = info.cursor_position.y - (info.window_height - 1 - first_line_height - info.configured_scroll_offsets.bottom)
                for _ in range(max(0, cursor_up)):
                    b.cursor_position += b.document.get_cursor_up_position()
                w.vertical_scroll -= 1

def _trim_text(text, max_width):
    """Trim the text to `max_width`, append dots when the text is too long.
    Returns (text, width) tuple."""
    width = get_cwidth(text)
    if width > max_width:
        if len(text) == width:
            trimmed_text = (text[:max(1, max_width - 3)] + '...')[:max_width]
            return (trimmed_text, len(trimmed_text))
        else:
            trimmed_text = ''
            for c in text:
                if get_cwidth(trimmed_text + c) <= max_width - 3:
                    trimmed_text += c
            trimmed_text += '...'
            return (trimmed_text, get_cwidth(trimmed_text))
    else:
        return (text, width)

def split_token_in_parts(token):
    """Take a Token, and turn it in a list of tokens, by splitting
    it on ':' (taking that as a separator.)"""
    result = []
    current = []
    for part in token + (':',):
        if part == ':':
            if current:
                result.append(tuple(current))
                current = []
        else:
            current.append(part)
    return result

def vendor_import(name):
    """This enables us to use the vendor directory for packages we don't depend on"""
    parent_dir = os.path.abspath(os.path.dirname(__file__))
    vendor_dir = os.path.join(parent_dir, 'vendor')
    sys.path.insert(1, vendor_dir)
    return import_module(name)

def get_module(name, required=None):
    """Return module or None. Absolute import is required.
    :param (str) name: Dot-separated module path. E.g., 'scipy.stats'.
    :param (str) required: A string to raise a ValueError if missing
    :return: (module|None) If import succeeds, the module will be returned."""
    if name not in _not_importable:
        try:
            return import_module(name)
        except ImportError:
            _not_importable.add(name)
            if required:
                raise ValueError(required)
        except Exception as e:
            _not_importable.add(name)
            msg = 'Error importing optional module {}'.format(name)
            logger.exception(msg)

def get_full_typename(o):
    """We determine types based on type names so we don't have to import
    (and therefore depend on) PyTorch, TensorFlow, etc."""
    instance_name = o.__class__.__module__ + '.' + o.__class__.__name__
    if instance_name in ['builtins.module', '__builtin__.module']:
        return o.__name__
    else:
        return instance_name

def ensure_matplotlib_figure(obj):
    """Extract the current figure from a matplotlib object or return the object if it's a figure.
    raises ValueError if the object can't be converted."""
    import matplotlib
    from matplotlib.figure import Figure
    if obj == matplotlib.pyplot:
        obj = obj.gcf()
    elif not isinstance(obj, Figure):
        if hasattr(obj, 'figure'):
            obj = obj.figure
            if not isinstance(obj, Figure):
                raise ValueError('Only matplotlib.pyplot or matplotlib.pyplot.Figure objects are accepted.')
    if not obj.gca().has_data():
        raise ValueError("You attempted to log an empty plot, pass a figure directly or ensure the global plot isn't closed.")
    return obj

def json_friendly(obj):
    """Convert an object into something that's more becoming of JSON"""
    converted = True
    typename = get_full_typename(obj)
    if is_tf_tensor_typename(typename):
        obj = obj.eval()
    elif is_pytorch_tensor_typename(typename):
        try:
            if obj.requires_grad:
                obj = obj.detach()
        except AttributeError:
            pass
        try:
            obj = obj.data
        except RuntimeError:
            pass
        if obj.size():
            obj = obj.numpy()
        else:
            return (obj.item(), True)
    if np and isinstance(obj, np.ndarray):
        if obj.size == 1:
            obj = obj.flatten()[0]
        elif obj.size <= 32:
            obj = obj.tolist()
    elif np and isinstance(obj, np.generic):
        obj = obj.item()
    elif isinstance(obj, bytes):
        obj = obj.decode('utf-8')
    elif isinstance(obj, (datetime, date)):
        obj = obj.isoformat()
    else:
        converted = False
    if getsizeof(obj) > VALUE_BYTES_LIMIT:
        logger.warning('Object %s is %i bytes', obj, getsizeof(obj))
    return (obj, converted)

def launch_browser(attempt_launch_browser=True):
    """Decide if we should launch a browser"""
    _DISPLAY_VARIABLES = ['DISPLAY', 'WAYLAND_DISPLAY', 'MIR_SOCKET']
    _WEBBROWSER_NAMES_BLACKLIST = ['www-browser', 'lynx', 'links', 'elinks', 'w3m']
    import webbrowser
    launch_browser = attempt_launch_browser
    if launch_browser:
        if 'linux' in sys.platform and (not any((os.getenv(var) for var in _DISPLAY_VARIABLES))):
            launch_browser = False
        try:
            browser = webbrowser.get()
            if hasattr(browser, 'name') and browser.name in _WEBBROWSER_NAMES_BLACKLIST:
                launch_browser = False
        except webbrowser.Error:
            launch_browser = False
    return launch_browser

