def image_id_from_k8s():
    """Pings the k8s metadata service for the image id"""
    token_path = '/var/run/secrets/kubernetes.io/serviceaccount/token'
    if os.path.exists(token_path):
        k8s_server = 'https://{}:{}/api/v1/namespaces/default/pods/{}'.format(os.getenv('KUBERNETES_SERVICE_HOST'), os.getenv('KUBERNETES_PORT_443_TCP_PORT'), os.getenv('HOSTNAME'))
        try:
            res = requests.get(k8s_server, verify='/var/run/secrets/kubernetes.io/serviceaccount/ca.crt', timeout=3, headers={'Authorization': 'Bearer {}'.format(open(token_path).read())})
            res.raise_for_status()
        except requests.RequestException:
            return None
        try:
            return res.json()['status']['containerStatuses'][0]['imageID'].strip('docker-pullable://')
        except (ValueError, KeyError, IndexError):
            logger.exception('Error checking kubernetes for image id')
            return None

def async_call(target, timeout=None):
    """Accepts a method and optional timeout.
    Returns a new method that will call the original with any args, waiting for upto timeout seconds.
    This new method blocks on the original and returns the result or None
    if timeout was reached, along with the thread.
    You can check thread.isAlive() to determine if a timeout was reached.
    If an exception is thrown in the thread, we reraise it."""
    q = queue.Queue()
    def wrapped_target(q, *args, **kwargs):
        try:
            q.put(target(*args, **kwargs))
        except Exception as e:
            q.put(e)
    def wrapper(*args, **kwargs):
        thread = threading.Thread(target=wrapped_target, args=(q,) + args, kwargs=kwargs)
        thread.daemon = True
        thread.start()
        try:
            result = q.get(True, timeout)
            if isinstance(result, Exception):
                six.reraise(type(result), result, sys.exc_info()[2])
            return (result, thread)
        except queue.Empty:
            return (None, thread)
    return wrapper

def stopwatch_now():
    """Get a timevalue for interval comparisons

    When possible it is a monotonic clock to prevent backwards time issues."""
    if six.PY2:
        now = time.time()
    else:
        now = time.monotonic()
    return now

def normalize_exceptions(func):
    """Function decorator for catching common errors and re-raising as wandb.Error"""
    @wraps(func)
    def wrapper(*args, **kwargs):
        message = 'Whoa, you found a bug.'
        try:
            return func(*args, **kwargs)
        except requests.HTTPError as err:
            raise CommError(err.response, err)
        except RetryError as err:
            if 'response' in dir(err.last_exception) and err.last_exception.response is not None:
                try:
                    message = err.last_exception.response.json().get('errors', [{'message': message}])[0]['message']
                except ValueError:
                    message = err.last_exception.response.text
            else:
                message = err.last_exception
            six.reraise(CommError, CommError(message, err.last_exception), sys.exc_info()[2])
        except Exception as err:
            if len(err.args) > 0:
                payload = err.args[0]
            else:
                payload = err
            if str(payload).startswith('{'):
                message = ast.literal_eval(str(payload))['message']
            else:
                message = str(err)
            if wandb.env.is_debug():
                six.reraise(*sys.exc_info())
            else:
                six.reraise(CommError, CommError(message, err), sys.exc_info()[2])
    return wrapper

def wandb_pty(resize=True):
    """Get a PTY set to raw mode and registered to hear about window size changes.
    """
    master_fd, slave_fd = pty.openpty()
    try:
        tty.setraw(master_fd)
    except termios.error:
        pass
    if resize:
        if SIGWINCH_HANDLER is not None:
            SIGWINCH_HANDLER.add_fd(master_fd)
    return (master_fd, slave_fd)

def monitor(options={}):
    """Starts syncing with W&B if you're in Jupyter.  Displays your W&B charts live in a Jupyter notebook.
    It's currently a context manager for legacy reasons."""
    try:
        from IPython.display import display
    except ImportError:
        def display(stuff):
            return None
    class Monitor:
        def __init__(self, options={}):
            if os.getenv('WANDB_JUPYTER'):
                display(jupyter.Run())
            else:
                self.rm = False
                termerror('wandb.monitor is only functional in Jupyter notebooks')
        def __enter__(self):
            termlog('DEPRECATED: with wandb.monitor(): is deprecated, just call wandb.monitor() to see live results.')
            pass
        def __exit__(self, *args):
            pass
    return Monitor(options)

def log(row=None, commit=True, *args, **kargs):
    """Log a dict to the global run's history.  If commit is false, enables multiple calls before commiting.

    Eg.

    wandb.log({'train-loss': 0.5, 'accuracy': 0.9})"""
    if run is None:
        raise ValueError('You must call `wandb.init` in the same process before calling log')
    if row is None:
        row = {}
    if commit:
        run.history.add(row, *args, **kargs)
    else:
        run.history.update(row, *args, **kargs)

def reset_env(exclude=[]):
