def patch_network_latency(seconds=0.01):
    """Add random latency to all I/O operations"""
    def sleep():
        if isinstance(seconds, float):
            time.sleep(seconds)
        elif isinstance(seconds, basestring):
            if '-' in seconds:
                time.sleep(random.uniform(float(seconds.split('-')[0]), float(seconds.split('-')[1])))
            else:
                time.sleep(float(seconds))
    def _patched_method(old_method, *args, **kwargs):
        sleep()
        return old_method(*args, **kwargs)
    socket_methods = ['send', 'sendall', 'sendto', 'recv', 'recvfrom', 'recvfrom_into', 'recv_into', 'connect', 'connect_ex', 'close']
    from socket import socket as _socketmodule
    from gevent.socket import socket as _geventmodule
    from gevent.ssl import SSLSocket as _sslmodule
    for method in socket_methods:
        patch_method(_socketmodule, method, _patched_method)
        patch_method(_geventmodule, method, _patched_method)
        patch_method(_sslmodule, method, _patched_method)

def array_stack(arrays):
    """Stack arrays"""
    shapes = np.array([a.shape for a in arrays])
    if not np.all(np.roll(shapes[:, 1:], 1, axis=0) == shapes[:, 1:]):
        raise ValueError('All input arrays must have the same height and width for this mode')
    width = arrays[0].shape[-1]
    height = arrays[0].shape[-2]
    return np.array([a for subarray in arrays for a in subarray]).reshape(shapes[:, 0].sum(), height, width)

def tb_capture(func):
