def _wrapped_call(wrap_controller, func):
    """Wrap calling to a function with a generator which needs to yield
    exactly once.  The yield point will trigger calling the wrapped function
    and return its ``_Result`` to the yield point.  The generator then needs
    to finish (raise StopIteration) in order for the wrapped call to complete."""
    try:
        next(wrap_controller)
    except StopIteration:
        _raise_wrapfail(wrap_controller, 'did not yield')
    call_outcome = _Result.from_call(func)
    try:
        wrap_controller.send(call_outcome)
        _raise_wrapfail(wrap_controller, 'has second yield')
    except StopIteration:
        pass
    return call_outcome.get_result()

def varnames(func):
    """Return tuple of positional and keywrord argument names for a function,
    method, class or callable.

    In case of a class, its ``__init__`` method is considered.
    For methods the ``self`` parameter is not included."""
    cache = getattr(func, '__dict__', {})
    try:
        return cache['_varnames']
    except KeyError:
        pass
    if inspect.isclass(func):
        try:
            func = func.__init__
        except AttributeError:
            return ((), ())
    elif not inspect.isroutine(func):
        try:
            func = getattr(func, '__call__', func)
        except Exception:
            return ()
    try:
        spec = _getargspec(func)
    except TypeError:
        return ((), ())
    args, defaults = (tuple(spec.args), spec.defaults)
    if defaults:
        index = -len(defaults)
        args, defaults = (args[:index], tuple(args[index:]))
    else:
        defaults = ()
    implicit_names = ('self',) if not _PYPY3 else ('self', 'obj')
    if args:
        if inspect.ismethod(func) or ('.' in getattr(func, '__qualname__', ()) and args[0] in implicit_names):
            args = args[1:]
    try:
        cache['_varnames'] = (args, defaults)
    except TypeError:
        pass
    return (args, defaults)

def set_version(new_version_number=None, old_version_number=''):
