def generate_permutations(elements, n):
    """Heap's algorithm for generating all n! permutations in a list
    https://en.wikipedia.org/wiki/Heap%27s_algorithm"""
    c = [0] * n
    yield elements
    i = 0
    while i < n:
        if c[i] < i:
            if i % 2 == 0:
                elements[0], elements[i] = (elements[i], elements[0])
            else:
                elements[c[i]], elements[i] = (elements[i], elements[c[i]])
            yield elements
            c[i] += 1
            i = 0
        else:
            c[i] = 0
            i += 1

def APFSContainerPathSpecGetVolumeIndex(path_spec):
    """Retrieves the volume index from the path specification.

    Args:
      path_spec (PathSpec): path specification.

    Returns:
      int: volume index or None if the index cannot be determined."""
    volume_index = getattr(path_spec, 'volume_index', None)
    if volume_index is not None:
        return volume_index
    location = getattr(path_spec, 'location', None)
    if location is None or not location.startswith('/apfs'):
        return None
    try:
        volume_index = int(location[5:], 10) - 1
    except (TypeError, ValueError):
        volume_index = None
    if volume_index is None or volume_index < 0 or volume_index > 99:
        volume_index = None
    return volume_index

def VShadowPathSpecGetStoreIndex(path_spec):
