def _robust_rmtree(path, logger=None, max_retries=5):
    """Try to delete paths robustly .
    Retries several times (with increasing delays) if an OSError
    occurs.  If the final attempt fails, the Exception is propagated
    to the caller. Taken from https://github.com/hashdist/hashdist/pull/116"""
    for i in range(max_retries):
        try:
            shutil.rmtree(path)
            return
        except OSError as e:
            if logger:
                info('Unable to remove path: %s' % path)
                info('Retrying after %d seconds' % i)
            time.sleep(i)
    shutil.rmtree(path)

def kill(arg1, arg2):
    """Stops a proces that contains arg1 and is filtered by arg2
    """
    from subprocess import Popen, PIPE
    t0 = time.time()
    time_out = 30
    running = True
    while running and time.time() - t0 < time_out:
        if os.name == 'nt':
            p = Popen('tasklist | find "%s"' % arg1, shell=True, stdin=PIPE, stdout=PIPE, stderr=PIPE, close_fds=False)
        else:
            p = Popen('ps aux | grep %s' % arg1, shell=True, stdin=PIPE, stdout=PIPE, stderr=PIPE, close_fds=True)
        lines = p.stdout.readlines()
        running = False
        for line in lines:
            if '%s' % arg2 in line or (os.name == 'nt' and '%s' % arg1 in line):
                running = True
                fields = line.strip().split()
                info('Stopping %s (process number %s)' % (arg1, fields[1]))
                if os.name == 'nt':
                    kill = 'taskkill /F /PID "%s"' % fields[1]
                else:
                    kill = 'kill -9 %s 2> /dev/null' % fields[1]
                os.system(kill)
        time.sleep(1)
    else:
        pass
    if running:
        raise Exception('Could not stop %s: Running processes are\n%s' % (arg1, '\n'.join([l.strip() for l in lines])))

def login_required(fn):
    """auth decorator

    call function(request, user: <aioauth_client User object>)"""
    async def wrapped(request, **kwargs):
        session = await get_session(request)
        if 'token' not in session:
            return web.HTTPFound(cfg.oauth_redirect_path)
        client = GoogleClient(client_id=cfg.client_id, client_secret=cfg.client_secret, access_token=session['token'])
        try:
            user, info = await client.user_info()
        except Exception:
            return web.HTTPFound(cfg.oauth_redirect_path)
        return await fn(request, user, **kwargs)
    return wrapped

