def get_version():
    """Read version from __init__.py"""
    version_regex = re.compile('__version__\\s*=\\s*(?P<q>[\'"])(?P<version>\\d+(\\.\\d+)*(-(alpha|beta|rc)(\\.\\d+)?)?)(?P=q)')
    here = path.abspath(path.dirname(__file__))
    init_location = path.join(here, 'CHAID/__init__.py')
    with open(init_location) as init_file:
        for line in init_file:
            match = version_regex.search(line)
    if not match:
        raise Exception("Couldn't read version information from '{0}'".format(init_location))
    return match.group('version')

def three_partition(x):
    """partition a set of integers in 3 parts of same total value

    :param x: table of non negative values
    :returns: triplet of the integers encoding the sets, or None otherwise
    :complexity: :math:`O(2^{2n})`"""
    f = [0] * (1 << len(x))
    for i in range(len(x)):
        for S in range(1 << i):
            f[S | 1 << i] = f[S] + x[i]
    for A in range(1 << len(x)):
        for B in range(1 << len(x)):
            if A & B == 0 and f[A] == f[B] and (3 * f[A] == f[-1]):
                return (A, B, (1 << len(x)) - 1 ^ A ^ B)
    return None

def knapsack2(p, v, cmax):
    """Knapsack problem: select maximum value set of items if total size not more than capacity.
    alternative implementation with same behavior.

    :param p: table with size of items
    :param v: table with value of items
    :param cmax: capacity of bag
    :requires: number of items non-zero
    :returns: value optimal solution, list of item indexes in solution
    :complexity: O(n * cmax), for n = number of items"""
    n = len(p)
    pgv = [[0] * (cmax + 1) for _ in range(n)]
    for c in range(cmax + 1):
        pgv[0][c] = v[0] if c >= p[0] else 0
    pred = {}
    for i in range(1, n):
        for c in range(cmax + 1):
            pgv[i][c] = pgv[i - 1][c]
            pred[i, c] = (i - 1, c)
            if c >= p[i] and pgv[i - 1][c - p[i]] + v[i] > pgv[i][c]:
                pgv[i][c] = pgv[i - 1][c - p[i]] + v[i]
                pred[i, c] = (i - 1, c - p[i])
    cursor = (n - 1, cmax)
    chosen = []
    while cursor in pred:
        if pred[cursor][1] < cursor[1]:
            chosen.append(cursor[0])
        cursor = pred[cursor]
    if cursor[1] > 0:
        chosen.append(cursor[0])
    return (pgv[n - 1][cmax], chosen)

def dancing_links(size_universe, sets):
    """Exact set cover by the dancing links algorithm

    :param size_universe: universe = {0, 1, ..., size_universe - 1}
    :param sets: list of sets
    :returns: list of set indices partitioning the universe, or None
    :complexity: huge"""
    header = Cell(None, None, 0, None)
    col = []
    for j in range(size_universe):
        col.append(Cell(header, None, 0, None))
    for i in range(len(sets)):
        row = None
        for j in sets[i]:
            col[j].S += 1
            row = Cell(row, col[j], i, col[j])
    sol = []
    if solve(header, sol):
        return sol
    else:
        return None

def sudoku(G):
    """Solving Sudoku

    :param G: integer matrix with 0 at empty cells
    :returns bool: True if grid could be solved
    :modifies: G will contain the solution
    :complexity: huge, but linear for usual published 9x9 grids"""
    global N, N2, N4
    if len(G) == 16:
        N, N2, N4 = (4, 16, 256)
    e = 4 * N4
    universe = e + 1
    S = [[rc(a), rv(a), cv(a), bv(a)] for a in range(N4 * N2)]
    A = [e]
    for r in range(N2):
        for c in range(N2):
            if G[r][c] != 0:
                a = assignation(r, c, G[r][c] - 1)
                A += S[a]
    sol = dancing_links(universe, S + [A])
    if sol:
        for a in sol:
            if a < len(S):
                G[row(a)][col(a)] = val(a) + 1
        return True
    else:
        return False

def bellman_ford(graph, weight, source=0):
    """Single source shortest paths by Bellman-Ford

    :param graph: directed graph in listlist or listdict format
    :param weight: can be negative.
                   in matrix format or same listdict graph
    :returns: distance table, precedence table, bool
    :explanation: bool is True if a negative circuit is
                  reachable from the source, circuits
                  can have length 2.
    :complexity: `O(|V|*|E|)`"""
    n = len(graph)
    dist = [float('inf')] * n
    prec = [None] * n
    dist[source] = 0
    for nb_iterations in range(n):
        changed = False
        for node in range(n):
            for neighbor in graph[node]:
                alt = dist[node] + weight[node][neighbor]
                if alt < dist[neighbor]:
                    dist[neighbor] = alt
                    prec[neighbor] = node
                    changed = True
        if not changed:
            return (dist, prec, False)
    return (dist, prec, True)

def manacher(s):
    """Longest palindrome in a string by Manacher

    :param s: string
    :requires: s is not empty
    :returns: i,j such that s[i:j] is the longest palindrome in s
    :complexity: O(len(s))"""
    assert set.isdisjoint({'$', '^', '#'}, s)
    if s == '':
        return (0, 1)
    t = '^#' + '#'.join(s) + '#$'
    c = 1
    d = 1
    p = [0] * len(t)
    for i in range(2, len(t) - 1):
        mirror = 2 * c - i
        p[i] = max(0, min(d - i, p[mirror]))
        while t[i + 1 + p[i]] == t[i - 1 - p[i]]:
            p[i] += 1
        if i + p[i] > d:
            c = i
            d = i + p[i]
    k, i = max(((p[i], i) for i in range(1, len(t) - 1)))
    return ((i - k) // 2, (i + k) // 2)

def add_reverse_arcs(graph, capac=None):
    """Utility function for flow algorithms that need for every arc (u,v),
    the existence of an (v,u) arc, by default with zero capacity.
    graph can be in adjacency list, possibly with capacity matrix capac.
    or graph can be in adjacency dictionary, then capac parameter is ignored.

    :param capac: arc capacity matrix
    :param graph: in listlist representation, or in listdict representation, in this case capac is ignored
    :complexity: linear
    :returns: nothing, but graph is modified"""
    for u in range(len(graph)):
        for v in graph[u]:
            if u not in graph[v]:
                if type(graph[v]) is list:
                    graph[v].append(u)
                    if capac:
                        capac[v][u] = 0
                else:
                    assert type(graph[v]) is dict
                    graph[v][u] = 0

def dictdict_to_listdict(dictgraph):
    """Transforms a dict-dict graph representation into a
    adjacency dictionary representation (list-dict)

    :param dictgraph: dictionary mapping vertices to dictionary
           such that dictgraph[u][v] is weight of arc (u,v)
    :complexity: linear
    :returns: tuple with graph (listdict), name_to_node (dict), node_to_name (list)"""
    n = len(dictgraph)
    node_to_name = [name for name in dictgraph]
    node_to_name.sort()
    name_to_node = {}
    for i in range(n):
        name_to_node[node_to_name[i]] = i
    sparse = [{} for _ in range(n)]
    for u in dictgraph:
        for v in dictgraph[u]:
            sparse[name_to_node[u]][name_to_node[v]] = dictgraph[u][v]
    return (sparse, name_to_node, node_to_name)

def _augment(graph, capacity, flow, val, u, target, visit):
    """Find an augmenting path from u to target with value at most val"""
    visit[u] = True
    if u == target:
        return val
    for v in graph[u]:
        cuv = capacity[u][v]
        if not visit[v] and cuv > flow[u][v]:
            res = min(val, cuv - flow[u][v])
            delta = _augment(graph, capacity, flow, res, v, target, visit)
            if delta > 0:
                flow[u][v] += delta
                flow[v][u] -= delta
                return delta
    return 0

def bezout(a, b):
    """Bezout coefficients for a and b

    :param a,b: non-negative integers
    :complexity: O(log a + log b)"""
    if b == 0:
        return (1, 0)
    else:
        u, v = bezout(b, a % b)
        return (v, u - a // b * v)

def predictive_text(dic):
    """Predictive text for mobile phones

    :param dic: associates weights to words from [a-z]*
    :returns: a dictionary associating to words from [2-9]*
             a corresponding word from the dictionary with highest weight
    :complexity: linear in total word length"""
    freq = {}
    for word, weight in dic:
        prefix = ''
        for x in word:
            prefix += x
            if prefix in freq:
                freq[prefix] += weight
            else:
                freq[prefix] = weight
    prop = {}
    for prefix in freq:
        code = code_word(prefix)
        if code not in prop or freq[prop[code]] < freq[prefix]:
            prop[code] = prefix
    return prop

def rectangles_from_points(S):
    """How many rectangles can be formed from a set of points

    :param S: list of points, as coordinate pairs
    :returns: the number of rectangles
    :complexity: :math:`O(n^2)`"""
    answ = 0
    pairs = {}
    for j in range(len(S)):
        for i in range(j):
            px, py = S[i]
            qx, qy = S[j]
            center = (px + qx, py + qy)
            dist = (px - qx) ** 2 + (py - qy) ** 2
            sign = (center, dist)
            if sign in pairs:
                answ += len(pairs[sign])
                pairs[sign].append((i, j))
            else:
                pairs[sign] = [(i, j)]
    return answ

def find_cycle(graph):
    """find a cycle in an undirected graph

    :param graph: undirected graph in listlist or listdict format
    :returns: list of vertices in a cycle or None
    :complexity: `O(|V|+|E|)`"""
    n = len(graph)
    prec = [None] * n
    for u in range(n):
        if prec[u] is None:
            S = [u]
            prec[u] = u
            while S:
                u = S.pop()
                for v in graph[u]:
                    if v != prec[u]:
                        if prec[v] is not None:
                            cycle = [v, u]
                            while u != prec[v] and u != prec[u]:
                                u = prec[u]
                                cycle.append(u)
                            return cycle
                        else:
                            prec[v] = u
                            S.append(v)
    return None

def arithm_expr_eval(cell, expr):
    """Evaluates a given expression

    :param expr: expression
    :param cell: dictionary variable name -> expression

    :returns: numerical value of expression

    :complexity: linear"""
    if isinstance(expr, tuple):
        left, op, right = expr
        lval = arithm_expr_eval(cell, left)
        rval = arithm_expr_eval(cell, right)
        if op == '+':
            return lval + rval
        if op == '-':
            return lval - rval
        if op == '*':
            return lval * rval
        if op == '/':
            return lval // rval
    elif isinstance(expr, int):
        return expr
    else:
        cell[expr] = arithm_expr_eval(cell, cell[expr])
        return cell[expr]

def arithm_expr_parse(line):
    """Constructs an arithmetic expression tree

    :param line: list of token strings containing the expression
    :returns: expression tree

    :complexity:     linear"""
    vals = []
    ops = []
    for tok in line + [';']:
        if tok in priority:
            while tok != '(' and ops and (priority[ops[-1]] >= priority[tok]):
                right = vals.pop()
                left = vals.pop()
                vals.append((left, ops.pop(), right))
            if tok == ')':
                ops.pop()
            else:
                ops.append(tok)
        elif tok.isdigit():
            vals.append(int(tok))
        else:
            vals.append(tok)
    return vals.pop()

def _augment(graph, capacity, flow, source, target):
    """find a shortest augmenting path
    """
    n = len(graph)
    A = [0] * n
    augm_path = [None] * n
    Q = deque()
    Q.append(source)
    augm_path[source] = source
    A[source] = float('inf')
    while Q:
        u = Q.popleft()
        for v in graph[u]:
            cuv = capacity[u][v]
            residual = cuv - flow[u][v]
            if residual > 0 and augm_path[v] is None:
                augm_path[v] = u
                A[v] = min(A[u], residual)
                if v == target:
                    break
                else:
                    Q.append(v)
    return (augm_path, A[target])

def matches(s, t, i, j, k):
    """tests if s[i:i + k] equals t[j:j + k]"""
    for d in range(k):
        if s[i + d] != t[j + d]:
            return False
    return True

def consecutive_ones_property(sets, universe=None):
    """Check the consecutive ones property.

    :param list sets: is a list of subsets of the ground set.
    :param groundset: is the set of all elements,
                by default it is the union of the given sets
    :returns: returns a list of the ordered ground set where
              every given set is consecutive,
              or None if there is no solution.
    :complexity: O(len(groundset) * len(sets))
    :disclaimer: an optimal implementation would have complexity
                 O(len(groundset) + len(sets) + sum(map(len,sets))),
                 and there are more recent easier algorithms for this problem."""
    if universe is None:
        universe = set()
        for S in sets:
            universe |= set(S)
    tree = PQ_tree(universe)
    try:
        for S in sets:
            tree.reduce(S)
        return tree.border()
    except IsNotC1P:
        return None

def powerstring_by_border(u):
    """Power string by Knuth-Morris-Pratt

    :param x: string
    :returns: largest k such that there is a string y with x = y^k
    :complexity: O(len(x))"""
    f = maximum_border_length(u)
    n = len(u)
    if n % (n - f[-1]) == 0:
        return n // (n - f[-1])
    return 1

def random_eulerien_graph(n):
    """Generates some random eulerian graph

    :param int n: number of vertices
    :returns: undirected graph in listlist representation
    :complexity: linear"""
    graphe = [[] for _ in range(n)]
    for v in range(n - 1):
        noeuds = random.sample(range(v + 1, n), random.choice(range(0 if len(graphe[v]) % 2 == 0 else 1, n - v, 2)))
        graphe[v].extend(noeuds)
        for w in graphe[v]:
            if w > v:
                graphe[w].append(v)
    return graphe

def arithm_expr_target(x, target):
    """Create arithmetic expression approaching target value
    :param x: allowed constants
    :param target: target value
    :returns: string in form 'expression=value'
    :complexity: huge"""
    n = len(x)
    expr = [{} for _ in range(1 << n)]
    for i in range(n):
        expr[1 << i] = {x[i]: str(x[i])}
    all_ = (1 << n) - 1
    for S in range(3, all_ + 1):
        if expr[S] != {}:
            continue
        for L in range(1, S):
            if L & S == L:
                R = S ^ L
                for vL in expr[L]:
                    for vR in expr[R]:
                        eL = expr[L][vL]
                        eR = expr[R][vR]
                        expr[S][vL] = eL
                        if vL > vR:
                            expr[S][vL - vR] = '(%s-%s)' % (eL, eR)
                        if L < R:
                            expr[S][vL + vR] = '(%s+%s)' % (eL, eR)
                            expr[S][vL * vR] = '(%s*%s)' % (eL, eR)
                        if vR != 0 and vL % vR == 0:
                            expr[S][vL // vR] = '(%s/%s)' % (eL, eR)
    for dist in range(target + 1):
        for sign in [-1, +1]:
            val = target + sign * dist
            if val in expr[all_]:
                return '%s=%i' % (expr[all_][val], val)
    pass

def anagrams(w):
    """group a list of words into anagrams

    :param w: list of strings
    :returns: list of lists

    :complexity:
        :math:`O(n k \\log k)` in average, for n words of length at most k.
        :math:`O(n^2 k \\log k)` in worst case due to the usage of a dictionary."""
    w = list(set(w))
    d = {}
    for i in range(len(w)):
        s = ''.join(sorted(w[i]))
        if s in d:
            d[s].append(i)
        else:
            d[s] = [i]
    answer = []
    for s in d:
        if len(d[s]) > 1:
            answer.append([w[i] for i in d[s]])
    return answer

def part_sum(x, i=0):
    """All subsetsums from x[i:]

    :param x: table of values
    :param int i: index defining suffix of x to be considered
    :iterates: over all values, in arbitrary order
    :complexity: :math:`O(2^{len(x)-i})`"""
    if i == len(x):
        yield 0
    else:
        for s in part_sum(x, i + 1):
            yield s
            yield (s + x[i])

def reverse(graph):
    """replace all arcs (u, v) by arcs (v, u) in a graph"""
    rev_graph = [[] for node in graph]
    for node in range(len(graph)):
        for neighbor in graph[node]:
            rev_graph[neighbor].append(node)
    return rev_graph

def get_parent_dir(base_dir, level=1):
    """Get the directory $level levels above $base_dir."""
    while level > 0:
        base_dir = os.path.dirname(base_dir)
        level -= 1
    return base_dir

def get_template_dirs():
    """Return a set of all template directories."""
    temp_glob = rel_to_cwd('templates', '**', 'templates', 'config.yaml')
    temp_groups = glob(temp_glob)
    temp_groups = [get_parent_dir(path, 2) for path in temp_groups]
    return set(temp_groups)

def get_scheme_dirs():
    """Return a set of all scheme directories."""
    scheme_glob = rel_to_cwd('schemes', '**', '*.yaml')
    scheme_groups = glob(scheme_glob)
    scheme_groups = [get_parent_dir(path) for path in scheme_groups]
    return set(scheme_groups)

def slugify(scheme_file):
    """Format $scheme_file_name to be used as a slug variable."""
    scheme_file_name = os.path.basename(scheme_file)
    if scheme_file_name.endswith('.yaml'):
        scheme_file_name = scheme_file_name[:-5]
    return scheme_file_name.lower().replace(' ', '-')

def build_single_worker(queue, templates, base_output_dir):
    """Worker thread for picking up scheme files from $queue and building b16
    templates using $templates until it receives None."""
    while True:
        scheme_file = queue.get()
        if scheme_file is None:
            break
        build_single(scheme_file, templates, base_output_dir)
        queue.task_done()

def build_from_job_list(scheme_files, templates, base_output_dir):
    """Use $scheme_files as a job lists and build base16 templates using
    $templates (a list of TemplateGroup objects)."""
    queue = Queue()
    for scheme in scheme_files:
        queue.put(scheme)
    if len(scheme_files) < 40:
        thread_num = len(scheme_files)
    else:
        thread_num = 40
    threads = []
    for _ in range(thread_num):
        thread = Thread(target=build_single_worker, args=(queue, templates, base_output_dir))
        thread.start()
        threads.append(thread)
    queue.join()
    for _ in range(thread_num):
        queue.put(None)
    for thread in threads:
        thread.join()

def build(templates=None, schemes=None, base_output_dir=None):
    """Main build function to initiate building process."""
    template_dirs = templates or get_template_dirs()
    scheme_files = get_scheme_files(schemes)
    base_output_dir = base_output_dir or rel_to_cwd('output')
    if not template_dirs or not scheme_files:
        raise LookupError
    try:
        os.makedirs(base_output_dir)
    except FileExistsError:
        pass
    if not os.access(base_output_dir, os.W_OK):
        raise PermissionError
    templates = [TemplateGroup(path) for path in template_dirs]
    build_from_job_list(scheme_files, templates, base_output_dir)
    print('Finished building process.')

def git_clone_worker(queue):
    """Worker thread for picking up git clone jobs from $queue until it
    receives None."""
    while True:
        job = queue.get()
        if job is None:
            break
        git_url, path = job
        git_clone(git_url, path)
        queue.task_done()

def git_clone_job_list(job_list):
    """Deal with all git clone jobs in $job_list."""
    queue = Queue()
    for job in job_list:
        queue.put(job)
    if len(job_list) < 20:
        thread_num = len(job_list)
    else:
        thread_num = 20
    threads = []
    for _ in range(thread_num):
        thread = Thread(target=git_clone_worker, args=(queue,))
        thread.start()
        threads.append(thread)
    queue.join()
    for _ in range(thread_num):
        queue.put(None)
    for thread in threads:
        thread.join()

def get_yaml_dict(yaml_file):
    """Return a yaml_dict from reading yaml_file. If yaml_file is empty or
    doesn't exist, return an empty dict instead."""
    try:
        with open(yaml_file, 'r') as file_:
            yaml_dict = yaml.safe_load(file_.read()) or {}
        return yaml_dict
    except FileNotFoundError:
        return {}

def build_mode(arg_namespace):
    """Check command line arguments and run build function."""
    custom_temps = arg_namespace.template or []
    temp_paths = [rel_to_cwd('templates', temp) for temp in custom_temps]
    try:
        builder.build(templates=temp_paths, schemes=arg_namespace.scheme, base_output_dir=arg_namespace.output)
    except (LookupError, PermissionError) as exception:
        if isinstance(exception, LookupError):
            print('Necessary resources for building not found in current working directory.')
        if isinstance(exception, PermissionError):
            print('No write permission for output directory.')

def inject_mode(arg_namespace):
    """Check command line arguments and run build function."""
    try:
        injector.inject_into_files(arg_namespace.scheme, arg_namespace.file)
    except (IndexError, FileNotFoundError, PermissionError, IsADirectoryError) as exception:
        if isinstance(exception, IndexError):
            print('"{}" has no valid injection marker lines.'.format(exception.args[0]))
        if isinstance(exception, FileNotFoundError):
            print('Lacking resource "{}" to complete operation.'.format(exception.filename))
        if isinstance(exception, PermissionError):
            print('No write permission for current working directory.')
        if isinstance(exception, IsADirectoryError):
            print('"{}" is a directory. Provide a *.yaml scheme file instead.'.format(exception.filename))

def update_mode(arg_namespace):
    """Check command line arguments and run update function."""
    try:
        updater.update(custom_sources=arg_namespace.custom)
    except (PermissionError, FileNotFoundError) as exception:
        if isinstance(exception, PermissionError):
            print('No write permission for current working directory.')
        if isinstance(exception, FileNotFoundError):
            print('Necessary resources for updating not found in current working directory.')

def script_to_address(script, vbyte=0):
    """Like script_to_address but supports altcoins
    Copied 2015-10-02 from https://github.com/mflaxman/pybitcointools/blob/faf56c53148989ea390238c3c4541a6ae1d601f5/bitcoin/transaction.py#L224-L236"""
    if re.match('^[0-9a-fA-F]*$', script):
        script = binascii.unhexlify(script)
    if script[:3] == b'v\xa9\x14' and script[-2:] == b'\x88\xac' and (len(script) == 25):
        return bin_to_b58check(script[3:-2], vbyte)
    else:
        if vbyte in [111, 196]:
            scripthash_byte = 196
        else:
            scripthash_byte = vbyte
        return bin_to_b58check(script[2:-1], scripthash_byte)

