def art(artname, number=1, text=''):
    """Return 1-line art.

    :param artname: artname
    :type artname : str
    :return: ascii art as str"""
    if isinstance(artname, str) is False:
        raise artError(ART_TYPE_ERROR)
    artname = artname.lower()
    arts = sorted(art_dic.keys())
    if artname == 'random' or artname == 'rand' or artname == 'rnd':
        filtered_arts = list(set(arts) - set(RANDOM_FILTERED_ARTS))
        artname = random.choice(filtered_arts)
    elif artname not in art_dic.keys():
        distance_list = list(map(lambda x: distance_calc(artname, x), arts))
        min_distance = min(distance_list)
        selected_art = arts[distance_list.index(min_distance)]
        threshold = max(len(artname), len(selected_art)) / 2
        if min_distance < threshold:
            artname = selected_art
        else:
            raise artError(ART_NAME_ERROR)
    art_value = art_dic[artname]
    if isinstance(number, int) is False:
        raise artError(NUMBER_TYPE_ERROR)
    if isinstance(art_value, str):
        return (art_value + ' ') * number
    if isinstance(text, str) is False:
        raise artError(TEXT_TYPE_ERROR)
    return (art_value[0] + text + art_value[1] + ' ') * number

def wizard_font(text):
    """Check input text length for wizard mode.

    :param text: input text
    :type text:str
    :return: font as str"""
    text_length = len(text)
    if text_length <= TEXT_XLARGE_THRESHOLD:
        font = random.choice(XLARGE_WIZARD_FONT)
    elif text_length > TEXT_XLARGE_THRESHOLD and text_length <= TEXT_LARGE_THRESHOLD:
        font = random.choice(LARGE_WIZARD_FONT)
    elif text_length > TEXT_LARGE_THRESHOLD and text_length <= TEXT_MEDIUM_THRESHOLD:
        font = random.choice(MEDIUM_WIZARD_FONT)
    else:
        font = random.choice(SMALL_WIZARD_FONT)
    return font

def predicate(fn=None, name=None, **options):
    """Decorator that constructs a ``Predicate`` instance from any function::

        >>> @predicate
        ... def is_book_author(user, book):
        ...     return user == book.author
        ...

        >>> @predicate(bind=True)
        ... def is_book_author(self, user, book):
        ...     if self.context.args:
        ...         return user == book.author"""
    if not name and (not callable(fn)):
        name = fn
        fn = None
    def inner(fn):
        if isinstance(fn, Predicate):
            return fn
        p = Predicate(fn, name, **options)
        update_wrapper(p, fn)
        return p
    if fn:
        return inner(fn)
    else:
        return inner

def objectgetter(model, attr_name='pk', field_name='pk'):
    """Helper that returns a function suitable for use as the ``fn`` argument
    to the ``permission_required`` decorator. Internally uses
    ``get_object_or_404``, so keep in mind that this may raise ``Http404``.

    ``model`` can be a model class, manager or queryset.

    ``attr_name`` is the name of the view attribute.

    ``field_name`` is the model's field name by which the lookup is made, eg.
    "id", "slug", etc."""
    def _getter(request, *view_args, **view_kwargs):
        if attr_name not in view_kwargs:
            raise ImproperlyConfigured('Argument {0} is not available. Given arguments: [{1}]'.format(attr_name, ', '.join(view_kwargs.keys())))
        try:
            return get_object_or_404(model, **{field_name: view_kwargs[attr_name]})
        except FieldError:
            raise ImproperlyConfigured('Model {0} has no field named {1}'.format(model, field_name))
    return _getter

def _parse_date_rfc822(dateString):
    """Parse an RFC822, RFC1123, RFC2822, or asctime-style date"""
    data = dateString.split()
    if data[0][-1] in (',', '.') or data[0].lower() in _daynames:
        del data[0]
    if len(data) == 4:
        s = data[3]
        s = s.split('+', 1)
        if len(s) == 2:
            data[3:] = s
        else:
            data.append('')
        dateString = ' '.join(data)
    if len(data) < 5:
        dateString += ' 00:00:00 GMT'
    return email.utils.parsedate_tz(dateString)

def load_locale(locale, icu=False):
    """Return data of locale
    :param locale:
    :return:"""
    if locale not in locales:
        raise NotImplementedError("The locale '%s' is not supported" % locale)
    if locale not in __locale_caches:
        mod = __import__(__name__, fromlist=[locale], level=0)
        __locale_caches[locale] = getattr(mod, locale)
    return __locale_caches[locale]

def indent(func):
    """Decorator for allowing to use method as normal method or with
    context manager for auto-indenting code blocks."""
    def wrapper(self, *args, **kwds):
        func(self, *args, **kwds)
        return Indent(self)
    return wrapper

def resolve_path(schema, fragment):
    """Return definition from path.

    Path is unescaped according https://tools.ietf.org/html/rfc6901"""
    fragment = fragment.lstrip('/')
    parts = unquote(fragment).split('/') if fragment else []
    for part in parts:
        part = part.replace('~1', '/').replace('~0', '~')
        if isinstance(schema, list):
            schema = schema[int(part)]
        elif part in schema:
            schema = schema[part]
        else:
            raise JsonSchemaException('Unresolvable ref: {}'.format(part))
    return schema

def nn_setsockopt(socket, level, option, value):
    """set a socket option

    socket - socket number
    level - option level
    option - option
    value - a readable byte buffer (not a Unicode string) containing the value
    returns - 0 on success or < 0 on error"""
    try:
        return _nn_setsockopt(socket, level, option, ctypes.addressof(value), len(value))
    except (TypeError, AttributeError):
        buf_value = ctypes.create_string_buffer(value)
        return _nn_setsockopt(socket, level, option, ctypes.addressof(buf_value), len(value))

def nn_send(socket, msg, flags):
    """send a message"""
    try:
        return _nn_send(socket, ctypes.addressof(msg), len(buffer(msg)), flags)
    except (TypeError, AttributeError):
        buf_msg = ctypes.create_string_buffer(msg)
        return _nn_send(socket, ctypes.addressof(buf_msg), len(msg), flags)

def nn_allocmsg(size, type):
    """allocate a message"""
    pointer = _nn_allocmsg(size, type)
    if pointer is None:
        return None
    return _create_message(pointer, size)

def nn_recv(socket, *args):
    """receive a message"""
    if len(args) == 1:
        flags, = args
        pointer = ctypes.c_void_p()
        rtn = _nn_recv(socket, ctypes.byref(pointer), ctypes.c_size_t(-1), flags)
        if rtn < 0:
            return (rtn, None)
        else:
            return (rtn, _create_message(pointer.value, rtn))
    elif len(args) == 2:
        msg_buf, flags = args
        mv_buf = memoryview(msg_buf)
        if mv_buf.readonly:
            raise TypeError('Writable buffer is required')
        rtn = _nn_recv(socket, ctypes.addressof(msg_buf), len(mv_buf), flags)
        return (rtn, msg_buf)

def create_message_buffer(size, type):
    """Create a message buffer"""
    rtn = wrapper.nn_allocmsg(size, type)
    if rtn is None:
        raise NanoMsgAPIError()
    return rtn

def poll(in_sockets, out_sockets, timeout=-1):
    """Poll a list of sockets
    :param in_sockets: sockets for reading
    :param out_sockets: sockets for writing
    :param timeout: poll timeout in seconds, -1 is infinite wait
    :return: tuple (read socket list, write socket list)"""
    sockets = {}
    fd_sockets = {}
    for s in in_sockets:
        sockets[s.fd] = POLLIN
        fd_sockets[s.fd] = s
    for s in out_sockets:
        modes = sockets.get(s.fd, 0)
        sockets[s.fd] = modes | POLLOUT
        fd_sockets[s.fd] = s
    if timeout >= 0:
        timeout_ms = int(timeout * 1000)
    else:
        timeout_ms = -1
    res, sockets = wrapper.nn_poll(sockets, timeout_ms)
    _nn_check_positive_rtn(res)
    read_list, write_list = ([], [])
    for fd, result in sockets.items():
        if result & POLLIN != 0:
            read_list.append(fd_sockets[fd])
        if result & POLLOUT != 0:
            write_list.append(fd_sockets[fd])
    return (read_list, write_list)

def overlap_bbox_and_point(bbox, xp, yp):
    """Given a bbox that contains a given point, return the (x, y) displacement
    necessary to make the bbox not overlap the point."""
    cx, cy = get_midpoint(bbox)
    dir_x = np.sign(cx - xp)
    dir_y = np.sign(cy - yp)
    if dir_x == -1:
        dx = xp - bbox.xmax
    elif dir_x == 1:
        dx = xp - bbox.xmin
    else:
        dx = 0
    if dir_y == -1:
        dy = yp - bbox.ymax
    elif dir_y == 1:
        dy = yp - bbox.ymin
    else:
        dy = 0
    return (dx, dy)

def to_dict(obj, classkey=None):
    """Recursively converts Python object into a dictionary"""
    if isinstance(obj, dict):
        data = {}
        for k, v in obj.items():
            data[k] = to_dict(v, classkey)
        return data
    elif hasattr(obj, '_ast'):
        return to_dict(obj._ast())
    elif hasattr(obj, '__iter__') and (not isinstance(obj, str)):
        return [to_dict(v, classkey) for v in obj]
    elif hasattr(obj, '__dict__'):
        if six.PY2:
            data = dict([(key, to_dict(value, classkey)) for key, value in obj.__dict__.iteritems() if not callable(value) and (not key.startswith('_'))])
        else:
            data = dict([(key, to_dict(value, classkey)) for key, value in obj.__dict__.items() if not callable(value) and (not key.startswith('_'))])
        if classkey is not None and hasattr(obj, '__class__'):
            data[classkey] = obj.__class__.__name__
        return data
    else:
        return obj

