def _extract_reason(kw):
    """Internal helper. Extracts a reason (possibly both reasons!) from
    the kwargs for a circuit failed or closed event."""
    try:
        reason = kw['REASON']
        try:
            reason = '{}, {}'.format(reason, kw['REMOTE_REASON'])
        except KeyError:
            pass
    except KeyError:
        reason = 'unknown'
    return reason

def _load_private_key_file(fname):
    """Loads an onion-service private-key from the given file. This can
    be either a 'key blog' as returned from a previous ADD_ONION call,
    or a v3 or v2 file as created by Tor when using the
    HiddenServiceDir directive.

    In any case, a key-blob suitable for ADD_ONION use is returned."""
    with open(fname, 'rb') as f:
        data = f.read()
    if b'\x00\x00\x00' in data:
        blob = data[data.find(b'\x00\x00\x00') + 3:]
        return u'ED25519-V3:{}'.format(b2a_base64(blob.strip()).decode('ascii').strip())
    if b'-----BEGIN RSA PRIVATE KEY-----' in data:
        blob = ''.join(data.decode('ascii').split('\n')[1:-2])
        return u'RSA1024:{}'.format(blob)
    blob = data.decode('ascii').strip()
    if ':' in blob:
        kind, key = blob.split(':', 1)
        if kind in ['ED25519-V3', 'RSA1024']:
            return blob
    raise ValueError("'{}' does not appear to contain v2 or v3 private key data".format(fname))

def _maybe_unique_host(onion):
    """:param onion: IAuthenticatedOnionClients provider

    :returns: a .onion hostname if all clients have the same name or
        raises ValueError otherwise"""
    hosts = [onion.get_client(nm).hostname for nm in onion.client_names()]
    if not hosts:
        raise ValueError("Can't access .onion_uri because there are no clients")
    host = hosts[0]
    for h in hosts[1:]:
        if h != host:
            raise ValueError('Cannot access .onion_uri for stealth-authenticated services because each client has a unique URI')
    return host

def _wrapture(orig):
    """Returns a new method that wraps orig (the original method) with
    something that first calls on_modify from the
    instance. _ListWrapper uses this to wrap all methods that modify
    the list."""
    def foo(*args):
        obj = args[0]
        obj.on_modify()
        return orig(*args)
    return foo

def _endpoint_from_socksport_line(reactor, socks_config):
    """Internal helper.

    Returns an IStreamClientEndpoint for the given config, which is of
    the same format expected by the SOCKSPort option in Tor."""
    if socks_config.startswith('unix:'):
        return UNIXClientEndpoint(reactor, socks_config[5:])
    if ' ' in socks_config:
        socks_config = socks_config.split()[0]
    if ':' in socks_config:
        host, port = socks_config.split(':', 1)
        port = int(port)
    else:
        host = '127.0.0.1'
        port = int(socks_config)
    return TCP4ClientEndpoint(reactor, host, port)

def create_tbb_web_headers():
