def process_from_address(addr, port, torstate=None):
    """Determines the PID from the address/port provided by using lsof
    and returns it as an int (or None if it couldn't be
    determined). In the special case the addr is '(Tor_internal)' then
    the PID of the Tor process (as gotten from the torstate object) is
    returned (or 0 if unavailable, e.g. a Tor which doesn't implement
    'GETINFO process/pid'). In this case if no TorState instance is
    given, None is returned."""
    if addr is None:
        return None
    if '(tor_internal)' == str(addr).lower():
        if torstate is None:
            return None
        return int(torstate.tor_pid)
    proc = subprocess.Popen(['lsof', '-i', '4tcp@%s:%s' % (addr, port)], stdout=subprocess.PIPE)
    stdout, stderr = proc.communicate()
    lines = stdout.split(b'\n')
    if len(lines) > 1:
        return int(lines[1].split()[1])

def hmac_sha256(key, msg):
    """Adapted from rransom's tor-utils git repository. Returns the
    digest (binary) of an HMAC with SHA256 over msg with key."""
    return hmac.new(key, msg, hashlib.sha256).digest()

def maybe_coroutine(obj):
    """If 'obj' is a coroutine and we're using Python3, wrap it in
    ensureDeferred. Otherwise return the original object.

    (This is to insert in all callback chains from user code, in case
    that user code is Python3 and used 'async def')"""
    if six.PY3 and asyncio.iscoroutine(obj):
        return defer.ensureDeferred(obj)
    return obj

def _is_non_public_numeric_address(host):
    """returns True if 'host' is not public"""
    try:
        a = ipaddress.ip_address(six.text_type(host))
    except ValueError:
        return False
    if a.is_loopback or a.is_multicast or a.is_private or a.is_reserved or a.is_unspecified:
        return True
    return False

def _validate_single_port_string(port):
    '''Validate a single string specifying ports for Onion
    services. These look like: "80 127.0.0.1:4321"'''
    if ' ' not in port or len(port.split(' ')) != 2:
        raise ValueError("Port '{}' should have exactly one space in it".format(port))
    external, internal = port.split(' ')
    try:
        external = int(external)
    except ValueError:
        raise ValueError("Port '{}' external port isn't an int".format(port))
    if ':' not in internal:
        raise ValueError("Port '{}' local address should be 'IP:port'".format(port))
    if not internal.startswith('unix:'):
        ip, localport = internal.split(':')
        if ip != 'localhost' and (not _is_non_public_numeric_address(ip)):
            raise ValueError("Port '{}' internal IP '{}' should be a local address".format(port, ip))

def pldist(point, start, end):
    """Calculates the distance from ``point`` to the line given
    by the points ``start`` and ``end``.

    :param point: a point
    :type point: numpy array
    :param start: a point of the line
    :type start: numpy array
    :param end: another point of the line
    :type end: numpy array"""
    if np.all(np.equal(start, end)):
        return np.linalg.norm(point - start)
    return np.divide(np.abs(np.linalg.norm(np.cross(end - start, start - point))), np.linalg.norm(end - start))

def rdp_rec(M, epsilon, dist=pldist):
    """Simplifies a given array of points.

    Recursive version.

    :param M: an array
    :type M: numpy array
    :param epsilon: epsilon in the rdp algorithm
    :type epsilon: float
    :param dist: distance function
    :type dist: function with signature ``f(point, start, end)`` -- see :func:`rdp.pldist`"""
    dmax = 0.0
    index = -1
    for i in xrange(1, M.shape[0]):
        d = dist(M[i], M[0], M[-1])
        if d > dmax:
            index = i
            dmax = d
    if dmax > epsilon:
        r1 = rdp_rec(M[:index + 1], epsilon, dist)
        r2 = rdp_rec(M[index:], epsilon, dist)
        return np.vstack((r1[:-1], r2))
    else:
        return np.vstack((M[0], M[-1]))

def _append_sorted(root, el, comparator):
    """Add el as a child of root, or as a child of one of root's children.
    Comparator is a function(a, b) returning > 0 if a is a child of b, < 0 if
    b is a child of a, 0 if neither."""
    for child in root:
        rel = comparator(el, child)
        if rel > 0:
            _append_sorted(child, el, comparator)
            return
        if rel < 0:
            _append_sorted(el, child, comparator)
    root.append(el)

def _box_in_box(el, child):
    """Return True if child is contained within el."""
    return all([float(el.get('x0')) <= float(child.get('x0')), float(el.get('x1')) >= float(child.get('x1')), float(el.get('y0')) <= float(child.get('y0')), float(el.get('y1')) >= float(child.get('y1'))])

def _comp_bbox(el, el2):
    """Return 1 if el in el2, -1 if el2 in el, else 0"""
    if _comp_bbox_keys_required <= set(el.keys()) and _comp_bbox_keys_required <= set(el2.keys()):
        if _box_in_box(el2, el):
            return 1
        if _box_in_box(el, el2):
            return -1
    return 0

def prepare_for_json_encoding(obj):
    """Convert an arbitrary object into just JSON data types (list, dict, unicode str, int, bool, null)."""
    obj_type = type(obj)
    if obj_type == list or obj_type == tuple:
        return [prepare_for_json_encoding(item) for item in obj]
    if obj_type == dict:
        return OrderedDict(((prepare_for_json_encoding(k), prepare_for_json_encoding(obj[k])) for k in sorted(obj.keys())))
    if obj_type == six.binary_type:
        return smart_unicode_decode(obj)
    if obj_type == bool or obj is None or obj_type == six.text_type or isinstance(obj, numbers.Number):
        return obj
    if obj_type == PSLiteral:
        return u'/%s' % obj.name
    return six.text_type(obj)

def obj_to_string(obj, top=True):
    """Turn an arbitrary object into a unicode string. If complex (dict/list/tuple), will be json-encoded."""
    obj = prepare_for_json_encoding(obj)
    if type(obj) == six.text_type:
        return obj
    return json.dumps(obj)

def get_stack_info():
    """Capture locals, module name, filename, and line number from the
    stacktrace to provide the source of the assertion error and
    formatted note."""
    stack = traceback.walk_stack(sys._getframe().f_back)
    for frame, _ in stack:
        code = frame.f_code
        if code.co_name.startswith('test_'):
            return (frame.f_locals.copy(), frame.f_globals['__name__'], code.co_filename, frame.f_lineno)

def _class_defining_method(meth):
    """Gets the name of the class that defines meth.

    Adapted from
    http://stackoverflow.com/questions/3589311/get-defining-class-of-unbound-method-object-in-python-3/25959545#25959545."""
    if inspect.ismethod(meth):
        for cls in inspect.getmro(meth.__self__.__class__):
            if cls.__dict__.get(meth.__name__) is meth:
                return '{}.{}'.format(cls.__module__, cls.__name__)
        meth = meth.__func__
    if inspect.isfunction(meth):
        module = meth.__qualname__.split('.<locals>', 1)[0]
        cls = getattr(inspect.getmodule(meth), module.rsplit('.', 1)[0])
        if isinstance(cls, type):
            return '{}.{}'.format(cls.__module__, cls.__name__)

def _extract_msg(args, kwargs, msg_idx, default_msg, non_msg_params):
    """Extracts the ``msg`` argument from the passed ``args``.

    Returns
    -------
    tuple
        The found ``msg``, the args and kwargs with that ``msg``
        removed, and any remaining positional args after ``msg``."""
    rem_args = []
    if 'msg' in kwargs:
        msg = kwargs.pop('msg')
    elif len(args) > non_msg_params and msg_idx < len(args):
        msg = args[msg_idx]
        if 0 <= msg_idx:
            rem_args = args[msg_idx + 1:]
        args = args[:msg_idx]
    else:
        msg = default_msg
    return (msg, args, rem_args, kwargs)

def _tchelper(tc_deps, evals, deps):
    """modifies graph in place"""
    for e in evals:
        if e in tc_deps:
            continue
        elif e in deps:
            tc_deps[e] = deps[e]
            _tchelper(tc_deps, deps[e], deps)
    return tc_deps

def error_rate(predictions, labels):
    """Return the error rate based on dense predictions and 1-hot labels."""
    return 100.0 - 100.0 * np.sum(np.argmax(predictions, 1) == np.argmax(labels, 1)) / predictions.shape[0]

def get_node(name):
    """returns HTOp or tf graph element corresponding to requested node name"""
    if name in _ops:
        return _ops[name]
    else:
        g = tf.get_default_graph()
        return g.as_graph_element(name)

def compute_node_deps():
    """- returns the full dependency graph of ALL ops and ALL tensors
    Map<string,list<string>> where key=node name, values=list of dependency names

    If an Op takes in a placeholder tensor that is the ouput of a PythonOp,
    we need to replace that Placeholder with the PythonOp."""
    deps = {}
    g = tf.get_default_graph()
    for op in g.get_operations():
        d = set([i.name for i in op.control_inputs])
        for t in op.inputs:
            if is_htop_out(t):
                d.add(get_op(t).name)
            else:
                d.add(t.name)
        deps[op.name] = d
        for t in op.outputs:
            deps[t.name] = set([op.name])
    for op in _ops.values():
        d = set()
        for t in op.inputs:
            if is_htop_out(t):
                d.add(get_op(t).name)
            else:
                d.add(t.name)
        deps[op.name] = d
    return deps

