def check_input(Verts=None, E2V=None, Agg=None, A=None, splitting=None, mesh_type=None):
    """Check input for local functions."""
    if Verts is not None:
        if not np.issubdtype(Verts.dtype, np.floating):
            raise ValueError('Verts should be of type float')
    if E2V is not None:
        if not np.issubdtype(E2V.dtype, np.integer):
            raise ValueError('E2V should be of type integer')
        if E2V.min() != 0:
            warnings.warn('element indices begin at %d' % E2V.min())
    if Agg is not None:
        if Agg.shape[1] > Agg.shape[0]:
            raise ValueError('Agg should be of size Npts x Nagg')
    if A is not None:
        if Agg is not None:
            if A.shape[0] != A.shape[1] or A.shape[0] != Agg.shape[0]:
                raise ValueError('expected square matrix A                                  and compatible with Agg')
        else:
            raise ValueError('problem with check_input')
    if splitting is not None:
        splitting = splitting.ravel()
        if Verts is not None:
            if len(splitting) % Verts.shape[0] != 0:
                raise ValueError('splitting must be a multiple of N')
        else:
            raise ValueError('problem with check_input')
    if mesh_type is not None:
        valid_mesh_types = ('vertex', 'tri', 'quad', 'tet', 'hex')
        if mesh_type not in valid_mesh_types:
            raise ValueError('mesh_type should be %s' % ' or '.join(valid_mesh_types))

def has_role(user, roles):
    """Check if a user has any of the given roles."""
    if user and user.is_superuser:
        return True
    if not isinstance(roles, list):
        roles = [roles]
    normalized_roles = []
    for role in roles:
        if not inspect.isclass(role):
            role = RolesManager.retrieve_role(role)
        normalized_roles.append(role)
    user_roles = get_user_roles(user)
    return any([role in user_roles for role in normalized_roles])

def has_permission(user, permission_name):
    """Check if a user has a given permission."""
    if user and user.is_superuser:
        return True
    return permission_name in available_perm_names(user)

def has_object_permission(checker_name, user, obj):
    """Check if a user has permission to perform an action on an object."""
    if user and user.is_superuser:
        return True
    checker = PermissionsManager.retrieve_checker(checker_name)
    user_roles = get_user_roles(user)
    if not user_roles:
        user_roles = [None]
    return any([checker(user_role, user, obj) for user_role in user_roles])

def get_user_roles(user):
    """Get a list of a users's roles."""
    if user:
        groups = user.groups.all()
        roles = (RolesManager.retrieve_role(group.name) for group in groups if group.name in RolesManager.get_roles_names())
        return sorted(roles, key=lambda r: r.get_name())
    else:
        return []

def clear_roles(user):
    """Remove all roles from a user."""
    roles = get_user_roles(user)
    for role in roles:
        role.remove_role_from_user(user)
    return roles

def available_perm_status(user):
    """Get a boolean map of the permissions available to a user
    based on that user's roles."""
    roles = get_user_roles(user)
    permission_hash = {}
    for role in roles:
        permission_names = role.permission_names_list()
        for permission_name in permission_names:
            permission_hash[permission_name] = get_permission(permission_name) in user.user_permissions.all()
    return permission_hash

def determine_endpoint_type(features):
    """Determines the type of an endpoint
    :param features: pandas.DataFrame
        A dataset in a panda's data frame
    :returns string
        string with a name of a dataset"""
    counter = {k.name: v for k, v in features.columns.to_series().groupby(features.dtypes).groups.items()}
    if len(features.groupby('class').apply(list)) == 2:
        return 'binary'
    if 'float64' in counter:
        return 'float'
    return 'integer'

def count_features_type(features):
    """Counts three different types of features (float, integer, binary).
    :param features: pandas.DataFrame
        A dataset in a panda's data frame
    :returns a tuple (binary, integer, float)"""
    counter = {k.name: v for k, v in features.columns.to_series().groupby(features.dtypes)}
    binary = 0
    if 'int64' in counter:
        binary = len(set(features.loc[:, (features <= 1).all(axis=0)].columns.values) & set(features.loc[:, (features >= 0).all(axis=0)].columns.values) & set(counter['int64']))
    return (binary, len(counter['int64']) - binary if 'int64' in counter else 0, len(counter['float64']) if 'float64' in counter else 0)

