def container_instance_from_string(id):
    """Create a ContainerInstance from an id string"""
    try:
        service, instance = id.rsplit('_', 1)
        instance = int(instance)
    except (TypeError, ValueError):
        raise context.ValueError('Invalid container id %r' % id)
    return _proto.ContainerInstance(service_name=service, instance=instance)

def parse_memory(s):
    """Converts bytes expression to number of mebibytes.

    If no unit is specified, ``MiB`` is used."""
    if isinstance(s, integer):
        out = s
    elif isinstance(s, float):
        out = math_ceil(s)
    elif isinstance(s, string):
        s = s.replace(' ', '')
        if not s:
            raise context.ValueError('Could not interpret %r as a byte unit' % s)
        if s[0].isdigit():
            for i, c in enumerate(reversed(s)):
                if not c.isalpha():
                    break
            index = len(s) - i
            prefix = s[:index]
            suffix = s[index:]
            try:
                n = float(prefix)
            except ValueError:
                raise context.ValueError('Could not interpret %r as a number' % prefix)
        else:
            n = 1
            suffix = s
        try:
            multiplier = _byte_sizes[suffix.lower()]
        except KeyError:
            raise context.ValueError('Could not interpret %r as a byte unit' % suffix)
        out = math_ceil(n * multiplier / 2 ** 20)
    else:
        raise context.TypeError('memory must be an integer, got %r' % type(s).__name__)
    if out < 0:
        raise context.ValueError('memory must be positive')
    return out

def humanize_timedelta(td):
    """Pretty-print a timedelta in a human readable format."""
    secs = int(td.total_seconds())
    hours, secs = divmod(secs, 60 * 60)
    mins, secs = divmod(secs, 60)
    if hours:
        return '%dh %dm' % (hours, mins)
    if mins:
        return '%dm' % mins
    return '%ds' % secs

def datetime_to_millis(x):
    """Convert a `datetime.datetime` to milliseconds since the epoch"""
    if x is None:
        return None
    if hasattr(x, 'timestamp'):
        secs = x.timestamp()
    elif x.tzinfo is None:
        secs = time.mktime((x.year, x.month, x.day, x.hour, x.minute, x.second, -1, -1, -1)) + x.microsecond / 1000000.0
    else:
        secs = (x - _EPOCH).total_seconds()
    return int(secs * 1000)

def load_widget(path):
    """Load custom widget for the form field"""
    i = path.rfind('.')
    module, attr = (path[:i], path[i + 1:])
    try:
        mod = import_module(module)
    except (ImportError, ValueError) as e:
        error_message = 'Error importing widget for BleachField %s: "%s"'
        raise ImproperlyConfigured(error_message % (path, e))
    try:
        cls = getattr(mod, attr)
    except AttributeError:
        raise ImproperlyConfigured('Module "%s" does not define a "%s" widget' % (module, attr))
    return cls

def get_default_widget():
    """Get the default widget or the widget defined in settings"""
    default_widget = forms.Textarea
    if hasattr(settings, 'BLEACH_DEFAULT_WIDGET'):
        default_widget = load_widget(settings.BLEACH_DEFAULT_WIDGET)
    return default_widget

def _format_date_param(params, key, format='%Y-%m-%d %H:%M:%S'):
    """Utility function to convert datetime values to strings.

    If the value is already a str, or is not in the dict, no change is made.

    :param params: A `dict` of params that may contain a `datetime` value.
    :param key: The datetime value to be converted to a `str`
    :param format: The `strftime` format to be used to format the date. The default value is '%Y-%m-%d %H:%M:%S'"""
    if key in params:
        param = params[key]
        if hasattr(param, 'strftime'):
            params[key] = param.strftime(format)

