def cupy_wrapper(func):
    """A wrapper function that converts numpy ndarray arguments to cupy
    arrays, and convert any cupy arrays returned by the wrapped
    function into numpy ndarrays."""
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        args = list(args)
        for n, a in enumerate(args):
            if isinstance(a, np.ndarray):
                args[n] = cp.asarray(a)
        for k, v in kwargs.items():
            if isinstance(v, np.ndarray):
                kwargs[k] = cp.asarray(v)
        rtn = func(*args, **kwargs)
        if isinstance(rtn, (list, tuple)):
            for n, a in enumerate(rtn):
                if isinstance(a, cp.core.core.ndarray):
                    rtn[n] = cp.asnumpy(a)
        elif isinstance(rtn, cp.core.core.ndarray):
            rtn = cp.asnumpy(rtn)
        return rtn
    return wrapped

def _list2array(lst):
    """Convert a list to a numpy array."""
    if lst and isinstance(lst[0], cp.ndarray):
        return cp.hstack(lst)
    else:
        return cp.asarray(lst)

def _complex_dtype(dtype):
    """Patched version of :func:`sporco.linalg.complex_dtype`."""
    dt = cp.dtype(dtype)
    if dt == cp.dtype('float128'):
        return cp.dtype('complex256')
    elif dt == cp.dtype('float64'):
        return cp.dtype('complex128')
    else:
        return cp.dtype('complex64')

def _pyfftw_empty_aligned(shape, dtype, order='C', n=None):
    """Patched version of :func:`sporco.linalg.`."""
    return cp.empty(shape, dtype, order)

def _fftconv(a, b, axes=(0, 1)):
    """Patched version of :func:`sporco.linalg.fftconv`."""
    if cp.isrealobj(a) and cp.isrealobj(b):
        fft = cp.fft.rfftn
        ifft = cp.fft.irfftn
    else:
        fft = cp.fft.fftn
        ifft = cp.fft.ifftn
    dims = cp.maximum(cp.asarray([a.shape[i] for i in axes]), cp.asarray([b.shape[i] for i in axes]))
    dims = [int(d) for d in dims]
    af = fft(a, dims, axes)
    bf = fft(b, dims, axes)
    return ifft(af * bf, dims, axes)

def _inner(x, y, axis=-1):
    """Patched version of :func:`sporco.linalg.inner`."""
    return cp.sum(x * y, axis=axis, keepdims=True)

def _cho_factor(A, lower=True, check_finite=True):
    """Implementaton of :func:`scipy.linalg.cho_factor` using
    a function supported in cupy."""
    return (cp.linalg.cholesky(A), True)

def _cho_solve(c_and_lower, b, check_finite=True):
    """Implementaton of :func:`scipy.linalg.cho_solve` using
    a function supported in cupy."""
    L = c_and_lower[0]
    y = cpxl.solve_triangular(L, b, trans=0, lower=True, check_finite=check_finite)
    return cpxl.solve_triangular(L, y, trans=1, lower=True, check_finite=check_finite)

def _linalg_cho_factor(A, rho, lower=False, check_finite=True):
    """Patched version of :func:`sporco.linalg.cho_factor`."""
    N, M = A.shape
    if N >= M:
        c, lwr = _cho_factor(A.T.dot(A) + rho * cp.identity(M, dtype=A.dtype), lower=lower, check_finite=check_finite)
    else:
        c, lwr = _cho_factor(A.dot(A.T) + rho * cp.identity(N, dtype=A.dtype), lower=lower, check_finite=check_finite)
    return (c, lwr)

def _cho_solve_AATI(A, rho, b, c, lwr, check_finite=True):
    """Patched version of :func:`sporco.linalg.cho_solve_AATI`."""
    N, M = A.shape
    if N >= M:
        x = (b - _cho_solve((c, lwr), b.dot(A).T, check_finite=check_finite).T.dot(A.T)) / rho
    else:
        x = _cho_solve((c, lwr), b.T, check_finite=check_finite).T
    return x

def sort_by_list_order(sortlist, reflist, reverse=False, fltr=False, slemap=None):
    """Sort a list according to the order of entries in a reference list.

    Parameters
    ----------
    sortlist : list
      List to be sorted
    reflist : list
      Reference list defining sorting order
    reverse : bool, optional (default False)
      Flag indicating whether to sort in reverse order
    fltr : bool, optional (default False)
      Flag indicating whether to filter `sortlist` to remove any entries
      that are not in `reflist`
    slemap : function or None, optional (default None)
       Function mapping a sortlist entry to the form of an entry in
       `reflist`

    Returns
    -------
    sortedlist : list
      Sorted (and possibly filtered) version of sortlist"""
    def keyfunc(entry):
        if slemap is not None:
            rle = slemap(entry)
        if rle in reflist:
            return reflist.index(rle)
        else:
            return sortlist.index(entry) + len(reflist)
    if fltr:
        if slemap:
            sortlist = filter(lambda x: slemap(x) in reflist, sortlist)
        else:
            sortlist = filter(lambda x: x in reflist, sortlist)
    return sorted(sortlist, key=keyfunc, reverse=reverse)

