def get_requirements(*args):
    """Get requirements from pip requirement files."""
    requirements = set()
    with open(get_absolute_path(*args)) as handle:
        for line in handle:
            line = re.sub('^#.*|\\s#.*', '', line)
            if line and (not line.isspace()):
                requirements.add(re.sub('\\s+', '', line))
    return sorted(requirements)

def have_environment_marker_support():
    """Check whether setuptools has support for PEP-426 environment marker support.

    Based on the ``setup.py`` script of the ``pytest`` package:
    https://bitbucket.org/pytest-dev/pytest/src/default/setup.py"""
    try:
        from pkg_resources import parse_version
        from setuptools import __version__
        return parse_version(__version__) >= parse_version('0.7.2')
    except Exception:
        return False

def flask_ctx_get_request_id():
    """Get request id from flask's G object
    :return: The id or None if not found."""
    from flask import _app_ctx_stack as stack
    if stack.top is None:
        raise ExecutedOutsideContext()
    g_object_attr = stack.top.app.config['LOG_REQUEST_ID_G_OBJECT_ATTRIBUTE']
    return g.get(g_object_attr, None)

def generic_http_header_parser_for(header_name):
    """A parser factory to extract the request id from an HTTP header
    :return: A parser that can be used to extract the request id from the current request context
    :rtype: ()->str|None"""
    def parser():
        request_id = request.headers.get(header_name, '').strip()
        if not request_id:
            return None
        return request_id
    return parser

def auto_parser(parsers=(x_request_id, x_correlation_id, amazon_elb_trace_id)):
    """Meta parser that will try all known parser and it will bring the first found id
    :param list[Callable] parsers: A list of callable parsers to try to extract request_id
    :return: The request id if it is found or None
    :rtype: str|None"""
    for parser in parsers:
        request_id = parser()
        if request_id is not None:
            return request_id
    return None

def build_valid_time(time, step):
    """Return dimensions and data of the valid_time corresponding to the given ``time`` and ``step``.
    The data is seconds from the same epoch as ``time`` and may have one or two dimensions.

    :param time: given in seconds from an epoch, as returned by ``from_grib_date_time``
    :param step: given in hours, as returned by ``from_grib_step``"""
    step_s = step * 3600
    if len(time.shape) == 0 and len(step.shape) == 0:
        data = time + step_s
        dims = ()
    elif len(time.shape) > 0 and len(step.shape) == 0:
        data = time + step_s
        dims = ('time',)
    elif len(time.shape) == 0 and len(step.shape) > 0:
        data = time + step_s
        dims = ('step',)
    else:
        data = time[:, None] + step_s[None, :]
        dims = ('time', 'step')
    return (dims, data)

