def modify_sql(sql, add_comments, add_hints, add_index_hints):
    """Parse the start of the SQL, injecting each string in add_comments in
    individual SQL comments after the first keyword, and adding the named
    SELECT hints from add_hints, taking the latest in the list in cases of
    multiple mutually exclusive hints being given"""
    match = query_start_re.match(sql)
    if not match:
        return sql
    tokens = [match.group('keyword')]
    comments = match.group('comments').strip()
    if comments:
        tokens.append(comments)
    for comment in add_comments:
        tokens.append('/*{}*/'.format(comment))
    if tokens[0] == 'SELECT':
        for group_name, hint_set in SELECT_HINTS.items():
            try:
                to_add = [hint for hint in add_hints if hint in hint_set][-1]
                tokens.append(to_add)
            except IndexError:
                existing = match.group(group_name)
                if existing is not None:
                    tokens.append(existing.rstrip())
    remainder = sql[match.end():]
    if tokens[0] == 'SELECT' and add_index_hints:
        for index_hint in add_index_hints:
            remainder = modify_sql_index_hints(remainder, *index_hint)
    tokens.append(remainder)
    return ' '.join(tokens)

def default_reverse_key_func(full_key):
    """Reverse of Django's default_key_func, i.e. undoing:

        def default_key_func(key, key_prefix, version):
            return '%s:%s:%s' % (key_prefix, version, key)"""
    match = reverse_key_re.match(full_key)
    return (match.group(3), match.group(1), int(match.group(2)))

def parse_create_table(sql):
    """Split output of SHOW CREATE TABLE into {column: column_spec}"""
    column_types = {}
    for line in sql.splitlines()[1:]:
        sline = line.strip()
        if not sline.startswith('`'):
            break
        bits = sline.split('`')
        assert len(bits) == 3
        column_name = bits[1]
        column_spec = bits[2].lstrip().rstrip(',')
        column_types[column_name] = column_spec
    return column_types

def get_choices(module_name):
    """Retrieve members from ``module_name``'s ``__all__`` list.

    :rtype: list"""
    try:
        module = importlib.import_module(module_name)
        if hasattr(module, '__all__'):
            return module.__all__
        else:
            return [name for name, _ in inspect.getmembers(module, inspect.isclass) if name != 'device']
    except ImportError:
        return []

def get_library_version(module_name):
