def prepare_spec(spec, data=None):
    """Prepare a Vega-Lite spec for sending to the frontend.

    This allows data to be passed in either as part of the spec
    or separately. If separately, the data is assumed to be a
    pandas DataFrame or object that can be converted to to a DataFrame.

    Note that if data is not None, this modifies spec in-place"""
    import pandas as pd
    if isinstance(data, pd.DataFrame):
        data = sanitize_dataframe(data)
        spec['data'] = {'values': data.to_dict(orient='records')}
    elif data is None:
        pass
    else:
        data = pd.DataFrame(data)
        data = sanitize_dataframe(data)
        spec['data'] = {'values': data.to_dict(orient='records')}
    return spec

def pass_creds_to_nylas(name, email, password, server_host=None):
    """Passes Exchange credentials to Nylas, to set up native authentication."""
    nylas_authorize_data = {'client_id': app.config['NYLAS_OAUTH_CLIENT_ID'], 'name': name, 'email_address': email, 'provider': 'exchange', 'settings': {'username': email, 'password': password}}
    if server_host:
        nylas_authorize_data['settings']['eas_server_host'] = server_host
    nylas_authorize_resp = requests.post('https://api.nylas.com/connect/authorize', json=nylas_authorize_data)
    if not nylas_authorize_resp.ok:
        message = nylas_authorize_resp.json()['message']
        raise APIError(message)
    nylas_code = nylas_authorize_resp.json()['code']
    nylas_token_data = {'client_id': app.config['NYLAS_OAUTH_CLIENT_ID'], 'client_secret': app.config['NYLAS_OAUTH_CLIENT_SECRET'], 'code': nylas_code}
    nylas_token_resp = requests.post('https://api.nylas.com/connect/token', json=nylas_token_data)
    if not nylas_token_resp.ok:
        message = nylas_token_resp.json()['message']
        raise APIError(message)
    nylas_access_token = nylas_token_resp.json()['access_token']
    session['nylas_access_token'] = nylas_access_token
    return redirect(url_for('success'))

def convert_datetimes_to_timestamps(data, datetime_attrs):
    """Given a dictionary of data, and a dictionary of datetime attributes,
    return a new dictionary that converts any datetime attributes that may
    be present to their timestamped equivalent."""
    if not data:
        return data
    new_data = {}
    for key, value in data.items():
        if key in datetime_attrs and isinstance(value, datetime):
            new_key = datetime_attrs[key]
            new_data[new_key] = timestamp_from_dt(value)
        else:
            new_data[key] = value
    return new_data

def webhook():
    """When the Flask server gets a request at the `/webhook` URL, it will run
    this function. Most of the time, that request will be a genuine webhook
    notification from Nylas. However, it's possible that the request could
    be a fake notification from someone else, trying to fool our app. This
    function needs to verify that the webhook is genuine!"""
    if request.method == 'GET' and 'challenge' in request.args:
        print(' * Nylas connected to the webhook!')
        return request.args['challenge']
    is_genuine = verify_signature(message=request.data, key=app.config['NYLAS_OAUTH_CLIENT_SECRET'].encode('utf8'), signature=request.headers.get('X-Nylas-Signature'))
    if not is_genuine:
        return ('Signature verification failed!', 401)
    data = request.get_json()
    for delta in data['deltas']:
        process_delta.delay(delta)
    return ('Deltas have been queued', 200)

def process_delta(delta):
    """This is the part of the code where you would process the information
    from the webhook notification. Each delta is one change that happened,
    and might require fetching message IDs, updating your database,
    and so on.

    However, because this is just an example project, we'll just print
    out information about the notification, so you can see what
    information is being sent."""
    kwargs = {'type': delta['type'], 'date': datetime.datetime.utcfromtimestamp(delta['date']), 'object_id': delta['object_data']['id']}
    print(' * {type} at {date} with ID {object_id}'.format(**kwargs))

def fill_tree(comments):
    """Insert extra comments in the comments list, so that the root path of the first comment is always visible.
    Use this in comments' pagination to fill in the tree information.

    The inserted comments have an ``added_path`` attribute."""
    if not comments:
        return
    it = iter(comments)
    first = next(it)
    extra_path_items = imap(_mark_as_root_path, first.root_path)
    return chain(extra_path_items, [first], it)

def annotate_tree_properties(comments):
    """iterate through nodes and adds some magic properties to each of them
    representing opening list of children and closing it"""
    if not comments:
        return
    it = iter(comments)
    old = next(it)
    old.open = True
    last = set()
    for c in it:
        if old.last_child_id:
            last.add(old.last_child_id)
        if c.pk in last:
            c.last = True
        if c.depth > old.depth:
            c.open = True
        else:
            old.close = list(range(old.depth - c.depth))
            if old.root_id != c.root_id:
                old.close.append(len(old.close))
                c.open = True
                last = set()
        yield old
        old = c
    old.close = range(old.depth)
    yield old

def to_iter(obj):
    """Convert an object to a list if it is not already an iterable.

    Nones are returned unaltered.

    This is an awful function that proliferates an explosion of types, please do not use anymore."""
    if isinstance(obj, type(None)):
        return None
    elif isinstance(obj, six.string_types):
        return [obj]
    elif isinstance(obj, collections.Iterable):
        return obj
    else:
        return [obj]

def to_list(obj):
    """Converts an object into a list if it not an iterable, forcing tuples into lists.
    Nones are returned unchanged."""
    obj = to_iter(obj)
    if isinstance(obj, type(None)):
        return None
    else:
        return list(obj)

def hlog_inv(y, b=500, r=_display_max, d=_l_mmax):
    """Inverse of base 10 hyperlog transform."""
    aux = 1.0 * d / r * y
    s = sign(y)
    if s.shape:
        s[s == 0] = 1
    elif s == 0:
        s = 1
    return s * 10 ** (s * aux) + b * aux - s

def parse_transform(transform, direction='forward'):
    """direction : 'forward' | 'inverse'"""
    if hasattr(transform, '__call__'):
        tfun = transform
        tname = None
    elif hasattr(transform, 'lower'):
        tname = _get_canonical_name(transform)
        if tname is None:
            raise ValueError('Unknown transform: %s' % transform)
        else:
            tfun = name_transforms[tname][direction]
    else:
        raise TypeError('Unsupported transform type: %s' % type(transform))
    return (tfun, tname)

