def jacobi(a, b):
    """Calculates the value of the Jacobi symbol (a/b) where both a and b are
    positive integers, and b is odd

    :returns: -1, 0 or 1"""
    assert a > 0
    assert b > 0
    if a == 0:
        return 0
    result = 1
    while a > 1:
        if a & 1:
            if (a - 1) * (b - 1) >> 2 & 1:
                result = -result
            a, b = (b % a, a)
        else:
            if b * b - 1 >> 3 & 1:
                result = -result
            a >>= 1
    if a == 0:
        return 0
    return result

def long_to_bytes(lnum, padmultiple=1):
    """Packs the lnum (which must be convertable to a long) into a
    byte string 0 padded to a multiple of padmultiple bytes in size. 0
    means no padding whatsoever, so that packing 0 result in an empty
    string.  The resulting byte string is the big-endian two's
    complement representation of the passed in long."""
    if lnum == 0:
        return b'\x00' * padmultiple
    elif lnum < 0:
        raise ValueError('Can only convert non-negative numbers.')
    s = hex(lnum)[2:]
    s = s.rstrip('L')
    if len(s) & 1:
        s = '0' + s
    s = binascii.unhexlify(s)
    if padmultiple != 1 and padmultiple != 0:
        filled_so_far = len(s) % padmultiple
        if filled_so_far != 0:
            s = b'\x00' * (padmultiple - filled_so_far) + s
    return s

def integer_ceil(a, b):
    """Return the ceil integer of a div b."""
    quanta, mod = divmod(a, b)
    if mod:
        quanta += 1
    return quanta

def integer_byte_size(n):
    """Returns the number of bytes necessary to store the integer n."""
    quanta, mod = divmod(integer_bit_size(n), 8)
    if mod or n == 0:
        quanta += 1
    return quanta

def i2osp(x, x_len):
    """Converts the integer x to its big-endian representation of length
    x_len."""
    if x > 256 ** x_len:
        raise exceptions.IntegerTooLarge
    h = hex(x)[2:]
    if h[-1] == 'L':
        h = h[:-1]
    if len(h) & 1 == 1:
        h = '0%s' % h
    x = binascii.unhexlify(h)
    return b'\x00' * int(x_len - len(x)) + x

def constant_time_cmp(a, b):
    """Compare two strings using constant time."""
    result = True
    for x, y in zip(a, b):
        result &= x == y
    return result

def do_zsh_complete(cli, prog_name):
    """Do the zsh completion

    Parameters
    ----------
    cli : click.Command
        The main click Command of the program
    prog_name : str
        The program name on the command line

    Returns
    -------
    bool
        True if the completion was successful, False otherwise"""
    commandline = os.environ['COMMANDLINE']
    args = split_args(commandline)[1:]
    if args and (not commandline.endswith(' ')):
        incomplete = args[-1]
        args = args[:-1]
    else:
        incomplete = ''
    def escape(s):
        return s.replace('"', '""').replace("'", "''").replace('$', '\\$').replace('`', '\\`')
    res = []
    for item, help in get_choices(cli, prog_name, args, incomplete):
        if help:
            res.append('"%s"\\:"%s"' % (escape(item), escape(help)))
        else:
            res.append('"%s"' % escape(item))
    if res:
        echo("_arguments '*: :((%s))'" % '\n'.join(res))
    else:
        echo('_files')
    return True

