def get_language_tabs(request, current_language, available_languages, css_class=None):
    """Determine the language tabs to show."""
    tabs = TabsList(css_class=css_class)
    get = request.GET.copy()
    tab_languages = []
    site_id = getattr(settings, 'SITE_ID', None)
    for lang_dict in appsettings.PARLER_LANGUAGES.get(site_id, ()):
        code = lang_dict['code']
        title = get_language_title(code)
        get['language'] = code
        url = '?{0}'.format(get.urlencode())
        if code == current_language:
            status = 'current'
        elif code in available_languages:
            status = 'available'
        else:
            status = 'empty'
        tabs.append((url, title, code, status))
        tab_languages.append(code)
    if appsettings.PARLER_SHOW_EXCLUDED_LANGUAGE_TABS:
        for code in available_languages:
            if code not in tab_languages:
                get['language'] = code
                url = '?{0}'.format(get.urlencode())
                if code == current_language:
                    status = 'current'
                else:
                    status = 'available'
                tabs.append((url, get_language_title(code), code, status))
    tabs.current_is_translated = current_language in available_languages
    tabs.allow_deletion = len(available_languages) > 1
    return tabs

def get_object_cache_keys(instance):
    """Return the cache keys associated with an object."""
    if instance.pk is None or instance._state.adding:
        return []
    keys = []
    tr_models = instance._parler_meta.get_all_models()
    for language in instance.get_available_languages():
        for tr_model in tr_models:
            keys.append(get_translation_cache_key(tr_model, instance.pk, language))
    return keys

def get_translation_cache_key(translated_model, master_id, language_code):
    """The low-level function to get the cache key for a translation."""
    return 'parler.{0}.{1}.{2}.{3}'.format(translated_model._meta.app_label, translated_model.__name__, master_id, language_code)

def get_cached_translation(instance, language_code=None, related_name=None, use_fallback=False):
    """Fetch an cached translation.

    .. versionadded 1.2 Added the ``related_name`` parameter."""
    if language_code is None:
        language_code = instance.get_current_language()
    translated_model = instance._parler_meta.get_model_by_related_name(related_name)
    values = _get_cached_values(instance, translated_model, language_code, use_fallback)
    if not values:
        return None
    try:
        translation = translated_model(**values)
    except TypeError:
        return None
    translation._state.adding = False
    return translation

def get_cached_translated_field(instance, field_name, language_code=None, use_fallback=False):
    """Fetch an cached field."""
    if language_code is None:
        language_code = instance.get_current_language()
    if len(field_name) <= 5 and len(language_code) > 5:
        raise RuntimeError('Unexpected language code, did you swap field_name, language_code?')
    translated_model = instance._parler_meta.get_model_by_field(field_name)
    values = _get_cached_values(instance, translated_model, language_code, use_fallback)
    if not values:
        return None
    return values.get(field_name, None)

def _get_cached_values(instance, translated_model, language_code, use_fallback=False):
    """Fetch an cached field."""
    if not appsettings.PARLER_ENABLE_CACHING or not instance.pk or instance._state.adding:
        return None
    key = get_translation_cache_key(translated_model, instance.pk, language_code)
    values = cache.get(key)
    if not values:
        return None
    if values.get('__FALLBACK__', False):
        instance._translations_cache[translated_model][language_code] = MISSING
        if use_fallback:
            lang_dict = get_language_settings(language_code)
            for fallback_lang in lang_dict['fallbacks']:
                if fallback_lang != language_code:
                    return _get_cached_values(instance, translated_model, fallback_lang, use_fallback=False)
        return None
    values['master'] = instance
    values['language_code'] = language_code
    return values

def _cache_translation(translation, timeout=cache.default_timeout):
    """Store a new translation in the cache."""
    if not appsettings.PARLER_ENABLE_CACHING:
        return
    if translation.master_id is None:
        raise ValueError("Can't cache unsaved translation")
    fields = translation.get_translated_fields()
    values = {'id': translation.id}
    for name in fields:
        values[name] = getattr(translation, name)
    key = get_translation_cache_key(translation.__class__, translation.master_id, translation.language_code)
    cache.set(key, values, timeout=timeout)

def select_template_name(template_name_list, using=None):
    """Given a list of template names, find the first one that exists."""
    if not isinstance(template_name_list, tuple):
        template_name_list = tuple(template_name_list)
    try:
        return _cached_name_lookups[template_name_list]
    except KeyError:
        for template_name in template_name_list:
            try:
                get_template(template_name, using=using)
            except TemplateDoesNotExist:
                continue
            else:
                template_name = six.text_type(template_name)
                _cached_name_lookups[template_name_list] = template_name
                return template_name
        return None

def get_parler_languages_from_django_cms(cms_languages=None):
    """Converts django CMS' setting CMS_LANGUAGES into PARLER_LANGUAGES. Since
    CMS_LANGUAGES is a strict superset of PARLER_LANGUAGES, we do a bit of
    cleansing to remove irrelevant items."""
    valid_keys = ['code', 'fallbacks', 'hide_untranslated', 'redirect_on_fallback']
    if cms_languages:
        if sys.version_info < (3, 0, 0):
            int_types = (int, long)
        else:
            int_types = int
        parler_languages = copy.deepcopy(cms_languages)
        for site_id, site_config in cms_languages.items():
            if site_id and (not isinstance(site_id, int_types) and site_id != 'default'):
                del parler_languages[site_id]
                continue
            if site_id == 'default':
                for key, value in site_config.items():
                    if key not in valid_keys:
                        del parler_languages['default'][key]
            else:
                for i, lang_config in enumerate(site_config):
                    for key, value in lang_config.items():
                        if key not in valid_keys:
                            del parler_languages[site_id][i][key]
        return parler_languages
    return None

def _get_model_form_field(model, name, formfield_callback=None, **kwargs):
    """Utility to create the formfield from a model field.
    When a field is not editable, a ``None`` will be returned."""
    field = model._meta.get_field(name)
    if not field.editable:
        return None
    if formfield_callback is None:
        formfield = field.formfield(**kwargs)
    elif not callable(formfield_callback):
        raise TypeError('formfield_callback must be a function or callable')
    else:
        formfield = formfield_callback(field, **kwargs)
    return formfield

def _validate_master(new_class):
    """Check whether the 'master' field on a TranslatedFieldsModel is correctly configured."""
    if not new_class.master or not isinstance(new_class.master, ForwardManyToOneDescriptor):
        raise ImproperlyConfigured('{0}.master should be a ForeignKey to the shared table.'.format(new_class.__name__))
    remote_field = new_class.master.field.remote_field
    shared_model = remote_field.model
    meta = shared_model._parler_meta
    if meta is not None:
        if meta._has_translations_model(new_class):
            raise ImproperlyConfigured("The model '{0}' already has an associated translation table!".format(shared_model.__name__))
        if meta._has_translations_field(remote_field.related_name):
            raise ImproperlyConfigured("The model '{0}' already has an associated translation field named '{1}'!".format(shared_model.__name__, remote_field.related_name))
    return shared_model

def get_language_title(language_code):
    """Return the verbose_name for a language code.

    Fallback to language_code if language is not found in settings."""
    from parler import appsettings
    if not language_code:
        raise ValueError('Missing language_code in get_language_title()')
    if appsettings.PARLER_SHOW_EXCLUDED_LANGUAGE_TABS:
        languages = ALL_LANGUAGES_DICT
    else:
        languages = LANGUAGES_DICT
    try:
        return _(languages[language_code])
    except KeyError:
        language_code = language_code.split('-')[0]
        language_title = languages.get(language_code, None)
        if language_title is not None:
            return _(language_title)
        else:
            return language_code

def get_language_settings(language_code, site_id=None):
    """Return the language settings for the current site"""
    from parler import appsettings
    return appsettings.PARLER_LANGUAGES.get_language(language_code, site_id)

def is_multilingual_project(site_id=None):
    """Whether the current Django project is configured for multilingual support."""
    from parler import appsettings
    if site_id is None:
        site_id = getattr(settings, 'SITE_ID', None)
    return appsettings.PARLER_SHOW_EXCLUDED_LANGUAGE_TABS or site_id in appsettings.PARLER_LANGUAGES

def get_language():
    """Wrapper around Django's `get_language` utility.
    For Django >= 1.8, `get_language` returns None in case no translation is activate.
    Here we patch this behavior e.g. for back-end functionality requiring access to translated fields"""
    from parler import appsettings
    language = dj_get_language()
    if language is None and appsettings.PARLER_DEFAULT_ACTIVATE:
        return appsettings.PARLER_DEFAULT_LANGUAGE_CODE
    else:
        return language

def _get_scripts_resource(pe):
    """Return the PYTHONSCRIPT resource entry."""
    res = None
    for entry in pe.DIRECTORY_ENTRY_RESOURCE.entries:
        if entry.name and entry.name.string == b'PYTHONSCRIPT':
            res = entry.directory.entries[0].directory.entries[0]
            break
    return res

def check_py2exe_file(pe):
    """Check file is a py2exe executable."""
    py2exe_resource = _get_scripts_resource(pe)
    if py2exe_resource is None:
        logging.info('This is not a py2exe executable.')
        if pe.__data__.find(b'pyi-windows-manifest-filename'):
            logging.info('This seems a pyinstaller executable (unsupported).')
    return bool(py2exe_resource)

def extract_code_objects(pe):
    """Extract Python code objects from a py2exe executable."""
    script_res = _get_scripts_resource(pe)
    dump = _resource_dump(pe, script_res)
    return _get_co_from_dump(dump)

def unpy2exe(filename, python_version=None, output_dir=None):
    """Process input params and produce output pyc files."""
    if output_dir is None:
        output_dir = '.'
    elif not os.path.exists(output_dir):
        os.makedirs(output_dir)
    pe = pefile.PE(filename)
    is_py2exe = check_py2exe_file(pe)
    if not is_py2exe:
        raise ValueError('Not a py2exe executable.')
    code_objects = extract_code_objects(pe)
    for co in code_objects:
        dump_to_pyc(co, python_version, output_dir)

def to_yaml(obj):
    """This function returns correct YAML representation of a UAVCAN structure (message, request, or response), or
    a DSDL entity (array or primitive), or a UAVCAN transfer, with comments for human benefit.
    Args:
        obj:            Object to convert.

    Returns: Unicode string containing YAML representation of the object."""
    if not isinstance(obj, CompoundValue) and hasattr(obj, 'transfer'):
        if hasattr(obj, 'message'):
            payload = obj.message
            header = 'Message'
        elif hasattr(obj, 'request'):
            payload = obj.request
            header = 'Request'
        elif hasattr(obj, 'response'):
            payload = obj.response
            header = 'Response'
        else:
            raise ValueError('Cannot generate YAML representation for %r' % type(obj))
        prefix = '### %s from %s to %s  ts_mono=%.6f  ts_real=%.6f\n' % (header, obj.transfer.source_node_id or 'Anon', obj.transfer.dest_node_id or 'All', obj.transfer.ts_monotonic, obj.transfer.ts_real)
        return prefix + _to_yaml_impl(payload)
    else:
        return _to_yaml_impl(obj)

def make_driver(device_name, **kwargs):
    """Creates an instance of CAN driver.
    The right driver class will be selected automatically based on the device_name.
    :param device_name: This parameter is used to select driver class. E.g. "/dev/ttyACM0", "COM9", "can0".
    :param kwargs: Passed directly to the constructor."""
    windows_com_port = device_name.replace('\\', '').replace('.', '').lower().startswith('com')
    unix_tty = device_name.startswith('/dev/')
    if windows_com_port or unix_tty:
        return SLCAN(device_name, **kwargs)
    elif SocketCAN is not None:
        return SocketCAN(device_name, **kwargs)
    else:
        raise DriverError('Unrecognized device name: %r' % device_name)

def make_node(can_device_name, **kwargs):
    """Constructs a node instance with specified CAN device.
    :param can_device_name: CAN device name, e.g. "/dev/ttyACM0", "COM9", "can0".
    :param kwargs: These arguments will be supplied to the CAN driver factory and to the node constructor."""
    can = driver.make_driver(can_device_name, **kwargs)
    return Node(can, **kwargs)

def pretty_filename(filename):
    """Returns a nice human readable path to 'filename'."""
    try:
        a = os.path.abspath(filename)
        r = os.path.relpath(filename)
    except ValueError:
        a = r = filename
    return a if '..' in r else r

def _rectangular(n):
    """Checks to see if a 2D list is a valid 2D matrix"""
    for i in n:
        if len(i) != len(n[0]):
            return False
    return True

def _is_2D_matrix(matrix):
    """Checks to see if a ndarray is 2D or a list of lists is 2D"""
    return isinstance(matrix[0], list) and _rectangular(matrix) and (not isinstance(matrix[0][0], list)) or (not isinstance(matrix, list) and matrix.shape == 2)

def _make_metadata_tsv(metadata, save_path):
    """Given an `NDArray` or a `numpy.ndarray` or a list as metadata e.g. labels, save the
    flattened array into the file metadata.tsv under the path provided by the user. The
    labels can be 1D or 2D with multiple labels per data point.
    Made to satisfy the requirement in the following link:
    https://www.tensorflow.org/programmers_guide/embedding#metadata"""
    if isinstance(metadata, NDArray):
        metadata = metadata.asnumpy()
    elif isinstance(metadata, list):
        metadata = np.array(metadata)
    elif not isinstance(metadata, np.ndarray):
        raise TypeError('expected NDArray or np.ndarray or 1D/2D list, while received type {}'.format(str(type(metadata))))
    if len(metadata.shape) > 2:
        raise TypeError('expected a 1D/2D NDArray, np.ndarray or list, while received shape {}'.format(str(metadata.shape)))
    if len(metadata.shape) == 1:
        metadata = metadata.reshape(-1, 1)
    with open(os.path.join(save_path, 'metadata.tsv'), 'w') as f:
        for row in metadata:
            f.write('\t'.join([str(x) for x in row]) + '\n')

def _save_embedding_tsv(data, file_path):
    """Given a 2D `NDarray` or a `numpy.ndarray` as embeding,
    save it in tensors.tsv under the path provided by the user."""
    if isinstance(data, np.ndarray):
        data_list = data.tolist()
    elif isinstance(data, NDArray):
        data_list = data.asnumpy().tolist()
    else:
        raise TypeError('expected NDArray of np.ndarray, while received type {}'.format(str(type(data))))
    with open(os.path.join(file_path, 'tensors.tsv'), 'w') as f:
        for x in data_list:
            x = [str(i) for i in x]
            f.write('\t'.join(x) + '\n')

def _get(url, headers={}, params=None):
    """Tries to GET data from an endpoint using retries"""
    param_string = _foursquare_urlencode(params)
    for i in xrange(NUM_REQUEST_RETRIES):
        try:
            try:
                response = requests.get(url, headers=headers, params=param_string, verify=VERIFY_SSL)
                return _process_response(response)
            except requests.exceptions.RequestException as e:
                _log_and_raise_exception('Error connecting with foursquare API', e)
        except FoursquareException as e:
            if e.__class__ in [InvalidAuth, ParamError, EndpointError, NotAuthorized, Deprecated]:
                raise
            if i + 1 == NUM_REQUEST_RETRIES:
                raise
        time.sleep(1)

def _post(url, headers={}, data=None, files=None):
    """Tries to POST data to an endpoint"""
    try:
        response = requests.post(url, headers=headers, data=data, files=files, verify=VERIFY_SSL)
        return _process_response(response)
    except requests.exceptions.RequestException as e:
        _log_and_raise_exception('Error connecting with foursquare API', e)

def _process_response(response):
    """Make the request and handle exception processing"""
    try:
        data = response.json()
    except ValueError:
        _log_and_raise_exception('Invalid response', response.text)
    if response.status_code == 200:
        return {'headers': response.headers, 'data': data}
    return _raise_error_from_response(data)

def _raise_error_from_response(data):
    """Processes the response data"""
    meta = data.get('meta')
    if meta:
        if meta.get('code') in (200, 409):
            return data
        exc = error_types.get(meta.get('errorType'))
        if exc:
            raise exc(meta.get('errorDetail'))
        else:
            _log_and_raise_exception('Unknown error. meta', meta)
    else:
        _log_and_raise_exception('Response format invalid, missing meta property. data', data)

def _foursquare_urlencode(query, doseq=0, safe_chars='&/,+'):
    """Gnarly hack because Foursquare doesn't properly handle standard url encoding"""
    if hasattr(query, 'items'):
        query = query.items()
    else:
        try:
            if len(query) and (not isinstance(query[0], tuple)):
                raise TypeError
        except TypeError:
            ty, va, tb = sys.exc_info()
            raise TypeError('not a valid non-string sequence or mapping object').with_traceback(tb)
    l = []
    if not doseq:
        for k, v in query:
            k = parse.quote(_as_utf8(k), safe=safe_chars)
            v = parse.quote(_as_utf8(v), safe=safe_chars)
            l.append(k + '=' + v)
    else:
        for k, v in query:
            k = parse.quote(_as_utf8(k), safe=safe_chars)
            if isinstance(v, six.string_types):
                v = parse.quote(_as_utf8(v), safe=safe_chars)
                l.append(k + '=' + v)
            else:
                try:
                    len(v)
                except TypeError:
                    v = parse.quote(_as_utf8(v), safe=safe_chars)
                    l.append(k + '=' + v)
                else:
                    for elt in v:
                        l.append(k + '=' + parse.quote(_as_utf8(elt)))
    return '&'.join(l)

def normalize(dt, tz=UTC):
    """Convert date or datetime to datetime with timezone.

    :param dt: date to normalize
    :param tz: the normalized date's timezone
    :return: date as datetime with timezone"""
    if type(dt) is date:
        dt = dt + relativedelta(hour=0)
    elif type(dt) is datetime:
        pass
    else:
        raise ValueError('unknown type %s' % type(dt))
    if dt.tzinfo:
        dt = dt.astimezone(tz)
    else:
        dt = dt.replace(tzinfo=tz)
    return dt

def parse_events(content, start=None, end=None, default_span=timedelta(days=7)):
    """Query the events occurring in a given time range.

    :param content: iCal URL/file content as String
    :param start: start date for search, default today
    :param end: end date for search
    :param default_span: default query length (one week)
    :return: events as list"""
    if not start:
        start = now()
    if not end:
        end = start + default_span
    if not content:
        raise ValueError('Content is invalid!')
    calendar = Calendar.from_ical(content)
    for c in calendar.walk():
        if c.name == 'VTIMEZONE':
            cal_tz = gettz(str(c['TZID']))
            break
    else:
        cal_tz = UTC
    start = normalize(start, cal_tz)
    end = normalize(end, cal_tz)
    found = []
    for component in calendar.walk():
        if component.name == 'VEVENT':
            e = create_event(component)
            if e.recurring:
                rule = parse_rrule(component, cal_tz)
                dur = e.end - e.start
                found.extend((e.copy_to(dt) for dt in rule.between(start - dur, end, inc=True)))
            elif e.end >= start and e.start <= end:
                found.append(e)
    return found

def parse_rrule(component, tz=UTC):
    """Extract a dateutil.rrule object from an icalendar component. Also includes
    the component's dtstart and exdate properties. The rdate and exrule
    properties are not yet supported.

    :param component: icalendar component
    :param tz: timezone for DST handling
    :return: extracted rrule or rruleset"""
    if component.get('rrule'):
        rrules = component['rrule']
        if not isinstance(rrules, list):
            rrules = [rrules]
        for rule in rrules:
            until = rule.get('until')
            for idx, dt in enumerate(until or []):
                if not hasattr(dt, 'tzinfo'):
                    until[idx] = normalize(normalize(dt, tz=tz), tz=UTC)
        rule = rrulestr('\n'.join((x.to_ical().decode() for x in rrules)), dtstart=normalize(component['dtstart'].dt, tz=tz))
        if component.get('exdate'):
            if isinstance(rule, rrule):
                rules = rruleset()
                rules.rrule(rule)
                rule = rules
            for exd in extract_exdates(component):
                rule.exdate(exd)
    else:
        rule = rruleset()
        rule.rdate(normalize(component['dtstart'].dt, tz=tz))
    return rule

def extract_exdates(component):
    """Compile a list of all exception dates stored with a component.

    :param component: icalendar iCal component
    :return: list of exception dates"""
    dates = []
    exd_prop = component.get('exdate')
    if exd_prop:
        if isinstance(exd_prop, list):
            for exd_list in exd_prop:
                dates.extend((normalize(exd.dt) for exd in exd_list.dts))
        elif isinstance(exd_prop, vDDDLists):
            dates.extend((normalize(exd.dt) for exd in exd_prop.dts))
    return dates

def can(ability, add_headers=None):
    """Test whether an ability is allowed."""
    client = ClientMixin(api_key=None)
    try:
        client.request('GET', endpoint='abilities/%s' % ability, add_headers=add_headers)
        return True
    except Exception:
        pass
    return False

def create_uniq_field_dis_func(*classes):
    """Given attr classes, generate a disambiguation function.

    The function is based on unique fields."""
    if len(classes) < 2:
        raise ValueError('At least two classes required.')
    cls_and_attrs = [(cl, set((at.name for at in fields(cl)))) for cl in classes]
    if len([attrs for _, attrs in cls_and_attrs if len(attrs) == 0]) > 1:
        raise ValueError('At least two classes have no attributes.')
    uniq_attrs_dict = OrderedDict()
    cls_and_attrs.sort(key=lambda c_a: -len(c_a[1]))
    fallback = None
    for i, (cl, cl_reqs) in enumerate(cls_and_attrs):
        other_classes = cls_and_attrs[i + 1:]
        if other_classes:
            other_reqs = reduce(or_, (c_a[1] for c_a in other_classes))
            uniq = cl_reqs - other_reqs
            if not uniq:
                m = '{} has no usable unique attributes.'.format(cl)
                raise ValueError(m)
            uniq_attrs_dict[next(iter(uniq))] = cl
        else:
            fallback = cl
    def dis_func(data):
        if not isinstance(data, Mapping):
            raise ValueError('Only input mappings are supported.')
        for k, v in uniq_attrs_dict.items():
            if k in data:
                return v
        return fallback
    return dis_func

def _get_acceptable_response_type():
    """Return the mimetype for this request."""
    if 'Accept' not in request.headers or request.headers['Accept'] in ALL_CONTENT_TYPES:
        return JSON
    acceptable_content_types = set(request.headers['ACCEPT'].strip().split(','))
    if acceptable_content_types & HTML_CONTENT_TYPES:
        return HTML
    elif acceptable_content_types & JSON_CONTENT_TYPES:
        return JSON
    else:
        raise InvalidAPIUsage(406)

def handle_exception(error):
    """Return a response with the appropriate status code, message, and content
    type when an ``InvalidAPIUsage`` exception is raised."""
    try:
        if _get_acceptable_response_type() == JSON:
            response = jsonify(error.to_dict())
            response.status_code = error.code
            return response
        else:
            return error.abort()
    except InvalidAPIUsage:
        response = jsonify(error.to_dict())
        response.status_code = 415
        return response

def _collection_json_response(cls, resources, start, stop, depth=0):
    """Return the JSON representation of the collection *resources*.

    :param list resources: list of :class:`sandman.model.Model`s to render
    :rtype: :class:`flask.Response`"""
    top_level_json_name = None
    if cls.__top_level_json_name__ is not None:
        top_level_json_name = cls.__top_level_json_name__
    else:
        top_level_json_name = 'resources'
    result_list = []
    for resource in resources:
        result_list.append(resource.as_dict(depth))
    payload = {}
    if start is not None:
        payload[top_level_json_name] = result_list[start:stop]
    else:
        payload[top_level_json_name] = result_list
    return jsonify(payload)

def _collection_html_response(resources, start=0, stop=20):
    """Return the HTML representation of the collection *resources*.

    :param list resources: list of :class:`sandman.model.Model`s to render
    :rtype: :class:`flask.Response`"""
    return make_response(render_template('collection.html', resources=resources[start:stop]))

def get_resource_data(incoming_request):
    """Return the data from the incoming *request* based on the
    Content-type."""
    content_type = incoming_request.headers['Content-type'].split(';')[0]
    if 'Content-type' not in incoming_request.headers or content_type in JSON_CONTENT_TYPES:
        return incoming_request.json
    elif content_type in HTML_CONTENT_TYPES:
        if not incoming_request.form:
            raise InvalidAPIUsage(400)
        return incoming_request.form
    else:
        raise InvalidAPIUsage(415, UNSUPPORTED_CONTENT_TYPE_MESSAGE.format(types=incoming_request.headers['Content-type']))

def retrieve_collection(collection, query_arguments=None):
    """Return the resources in *collection*, possibly filtered by a series of
    values to use in a 'where' clause search.

    :param string collection: a :class:`sandman.model.Model` endpoint
    :param dict query_arguments: a list of filter query arguments
    :rtype: class:`sandman.model.Model`"""
    session = _get_session()
    cls = endpoint_class(collection)
    if query_arguments:
        filters = []
        order = []
        limit = None
        for key, value in query_arguments.items():
            if key == 'page':
                continue
            if value.startswith('%'):
                filters.append(getattr(cls, key).like(str(value), escape='/'))
            elif key == 'sort':
                order.append(getattr(cls, value))
            elif key == 'limit':
                limit = value
            elif key:
                filters.append(getattr(cls, key) == value)
        resources = session.query(cls).filter(*filters).order_by(*order).limit(limit)
    else:
        resources = session.query(cls).all()
    return resources

def collection_response(cls, resources, start=None, stop=None):
    """Return a response for the *resources* of the appropriate content type.

    :param resources: resources to be returned in request
    :type resource: list of :class:`sandman.model.Model`
    :rtype: :class:`flask.Response`"""
    if _get_acceptable_response_type() == JSON:
        return _collection_json_response(cls, resources, start, stop)
    else:
        return _collection_html_response(resources, start, stop)

def attribute_response(resource, name, value):
    """Return a response for the *resource* of the appropriate content type.

    :param resource: resource to be returned in request
    :type resource: :class:`sandman.model.Model`
    :rtype: :class:`flask.Response`"""
    if _get_acceptable_response_type() == JSON:
        return _single_attribute_json_response(name, value)
    else:
        return _single_attribute_html_response(resource, name, value)

def put_resource(collection, key):
    """Replace the resource identified by the given key and return the
    appropriate response.

    :param string collection: a :class:`sandman.model.Model` endpoint
    :rtype: :class:`flask.Response`"""
    resource = retrieve_resource(collection, key)
    _validate(endpoint_class(collection), request.method, resource)
    resource.replace(get_resource_data(request))
    try:
        _perform_database_action('add', resource)
    except IntegrityError as exception:
        raise InvalidAPIUsage(422, FORWARDED_EXCEPTION_MESSAGE.format(exception))
    return no_content_response()

def get_resource_attribute(collection, key, attribute):
    """Return the appropriate *Response* for retrieving an attribute of
    a single resource.

    :param string collection: a :class:`sandman.model.Model` endpoint
    :param string key: the primary key for the :class:`sandman.model.Model`
    :rtype: :class:`flask.Response`"""
    resource = retrieve_resource(collection, key)
    _validate(endpoint_class(collection), request.method, resource)
    value = getattr(resource, attribute)
    if isinstance(value, Model):
        return resource_response(value)
    else:
        return attribute_response(resource, attribute, value)

def index():
    """Return information about each type of resource and how it can be
    accessed."""
    classes = []
    with app.app_context():
        classes = set(current_app.class_references.values())
    if _get_acceptable_response_type() == JSON:
        meta_data = {}
        for cls in classes:
            meta_data[cls.endpoint()] = {'link': '/' + cls.endpoint(), 'meta': '/' + cls.endpoint() + '/meta'}
        return jsonify(meta_data)
    else:
        return render_template('index.html', classes=classes)

def get_meta(collection):
    """Return the meta-description of a given resource.

    :param collection: The collection to get meta-info for"""
    cls = endpoint_class(collection)
    description = cls.meta()
    return jsonify(description)

def _get_session():
    """Return (and memoize) a database session"""
    session = getattr(g, '_session', None)
    if session is None:
        session = g._session = db.session()
    return session

def generate_endpoint_classes(db, generate_pks=False):
    """Return a list of model classes generated for each reflected database
    table."""
    seen_classes = set()
    for cls in current_app.class_references.values():
        seen_classes.add(cls.__tablename__)
    with app.app_context():
        db.metadata.reflect(bind=db.engine)
        for name, table in db.metadata.tables.items():
            if not name in seen_classes:
                seen_classes.add(name)
                if not table.primary_key and generate_pks:
                    cls = add_pk_if_required(db, table, name)
                else:
                    cls = type(str(name), (sandman_model, db.Model), {'__tablename__': name})
                register(cls)

def add_pk_if_required(db, table, name):
    """Return a class deriving from our Model class as well as the SQLAlchemy
    model.

    :param `sqlalchemy.schema.Table` table: table to create primary key for
    :param  table: table to create primary key for"""
    db.metadata.reflect(bind=db.engine)
    cls_dict = {'__tablename__': name}
    if not table.primary_key:
        for column in table.columns:
            column.primary_key = True
        Table(name, db.metadata, *table.columns, extend_existing=True)
        cls_dict['__table__'] = table
        db.metadata.create_all(bind=db.engine)
    return type(str(name), (sandman_model, db.Model), cls_dict)

def prepare_relationships(db, known_tables):
    """Enrich the registered Models with SQLAlchemy ``relationships``
    so that related tables are correctly processed up by the admin."""
    inspector = reflection.Inspector.from_engine(db.engine)
    for cls in set(known_tables.values()):
        for foreign_key in inspector.get_foreign_keys(cls.__tablename__):
            if foreign_key['referred_table'] in known_tables:
                other = known_tables[foreign_key['referred_table']]
                constrained_column = foreign_key['constrained_columns']
                if other not in cls.__related_tables__ and cls not in other.__related_tables__ and (other != cls):
                    cls.__related_tables__.add(other)
                    setattr(cls, other.__table__.name, relationship(other.__name__, backref=db.backref(cls.__name__.lower()), foreign_keys=str(cls.__name__) + '.' + ''.join(constrained_column)))

def register(cls, use_admin=True):
    """Register with the API a :class:`sandman.model.Model` class and
    associated endpoint.

    :param cls: User-defined class derived from :class:`sandman.model.Model` to
                be registered with the endpoint returned by :func:`endpoint()`
    :type cls: :class:`sandman.model.Model` or tuple"""
    with app.app_context():
        if getattr(current_app, 'class_references', None) is None:
            current_app.class_references = {}
        if isinstance(cls, (list, tuple)):
            for entry in cls:
                register_internal_data(entry)
                entry.use_admin = use_admin
        else:
            register_internal_data(cls)
            cls.use_admin = use_admin

def _ensure_unicode(text):
    """Ensures the text passed in becomes unicode
    Args:
        text (str|unicode)
    Returns:
        unicode"""
    if isinstance(text, six.binary_type):
        return text.decode(sys.getfilesystemencoding(), 'replace')
    else:
        return text

def get_version(module):
    """Return package version as listed in `__version__`."""
    init_py = open('{0}.py'.format(module)).read()
    return re.search('__version__ = [\'"]([^\'"]+)[\'"]', init_py).group(1)

def read_dotenv(dotenv=None, override=False):
    """Read a .env file into os.environ.

    If not given a path to a dotenv path, does filthy magic stack backtracking
    to find manage.py and then find the dotenv.

    If tests rely on .env files, setting the overwrite flag to True is a safe
    way to ensure tests run consistently across all environments.

    :param override: True if values in .env should override system variables."""
    if dotenv is None:
        frame_filename = sys._getframe().f_back.f_code.co_filename
        dotenv = os.path.join(os.path.dirname(frame_filename), '.env')
    if os.path.isdir(dotenv) and os.path.isfile(os.path.join(dotenv, '.env')):
        dotenv = os.path.join(dotenv, '.env')
    if os.path.exists(dotenv):
        with open(dotenv) as f:
            for k, v in parse_dotenv(f.read()).items():
                if override:
                    os.environ[k] = v
                else:
                    os.environ.setdefault(k, v)
    else:
        warnings.warn("Not reading {0} - it doesn't exist.".format(dotenv), stacklevel=2)

def pb2dict(obj):
    """Takes a ProtoBuf Message obj and convertes it to a dict."""
    adict = {}
    if not obj.IsInitialized():
        return None
    for field in obj.DESCRIPTOR.fields:
        if not getattr(obj, field.name):
            continue
        if not field.label == FD.LABEL_REPEATED:
            if not field.type == FD.TYPE_MESSAGE:
                adict[field.name] = getattr(obj, field.name)
            else:
                value = pb2dict(getattr(obj, field.name))
                if value:
                    adict[field.name] = value
        elif field.type == FD.TYPE_MESSAGE:
            adict[field.name] = [pb2dict(v) for v in getattr(obj, field.name)]
        else:
            adict[field.name] = [v for v in getattr(obj, field.name)]
    return adict

def json2pb(cls, json, strict=False):
    """Takes a class representing the Protobuf Message and fills it with data from
    the json string."""
    return dict2pb(cls, simplejson.loads(json), strict)

def check_date_str_format(s, default_time='00:00:00'):
    """Check the format of date string"""
    try:
        str_fmt = s
        if ':' not in s:
            str_fmt = '{} {}'.format(s, default_time)
        dt_obj = datetime.strptime(str_fmt, '%Y-%m-%d %H:%M:%S')
        return (RET_OK, dt_obj)
    except ValueError:
        error_str = ERROR_STR_PREFIX + 'wrong time or time format'
        return (RET_ERROR, error_str)

def normalize_date_format(date_str, default_time='00:00:00'):
    """normalize the format of data"""
    ret_code, ret_data = check_date_str_format(date_str, default_time)
    if ret_code != RET_OK:
        return (ret_code, ret_data)
    return (RET_OK, ret_data.strftime('%Y-%m-%d %H:%M:%S'))

def extract_pls_rsp(rsp_str):
    """Extract the response of PLS"""
    try:
        rsp = json.loads(rsp_str)
    except ValueError:
        traceback.print_exc()
        err = sys.exc_info()[1]
        err_str = ERROR_STR_PREFIX + str(err)
        return (RET_ERROR, err_str, None)
    error_code = int(rsp['retType'])
    if error_code != 1:
        error_str = ERROR_STR_PREFIX + rsp['retMsg']
        return (RET_ERROR, error_str, None)
    return (RET_OK, '', rsp)

def split_stock_str(stock_str_param):
    """split the stock string"""
    stock_str = str(stock_str_param)
    split_loc = stock_str.find('.')
    'do not use the built-in split function in python.\n    The built-in function cannot handle some stock strings correctly.\n    for instance, US..DJI, where the dot . itself is a part of original code'
    if 0 <= split_loc < len(stock_str) - 1 and stock_str[0:split_loc] in MKT_MAP:
        market_str = stock_str[0:split_loc]
        market_code = MKT_MAP[market_str]
        partial_stock_str = stock_str[split_loc + 1:]
        return (RET_OK, (market_code, partial_stock_str))
    else:
        error_str = ERROR_STR_PREFIX + 'format of %s is wrong. (US.AAPL, HK.00700, SZ.000001)' % stock_str
        return (RET_ERROR, error_str)

def merge_trd_mkt_stock_str(trd_mkt, partial_stock_str):
    '''Merge the string of stocks
    :param market: market code
    :param partial_stock_str: original stock code string. i.e. "AAPL","00700", "000001"
    :return: unified representation of a stock code. i.e. "US.AAPL", "HK.00700", "SZ.000001"'''
    mkt_qot = Market.NONE
    mkt = TRADE.REV_TRD_MKT_MAP[trd_mkt] if trd_mkt in TRADE.REV_TRD_MKT_MAP else TrdMarket.NONE
    if mkt == TrdMarket.HK:
        mkt_qot = Market.HK
    elif mkt == TrdMarket.US:
        mkt_qot = Market.US
    elif mkt == TrdMarket.HKCC or mkt == TrdMarket.CN:
        if partial_stock_str.startswith('6') or partial_stock_str.startswith('9'):
            mkt_qot = Market.SH
        else:
            mkt_qot = Market.SZ
    else:
        raise Exception('merge_trd_mkt_stock_str: unknown trd_mkt.')
    return merge_qot_mkt_stock_str(MKT_MAP[mkt_qot], partial_stock_str)

def binary2str(b, proto_id, proto_fmt_type):
    """Transfer binary to string
    :param b: binary content to be transformed to string
    :return: string"""
    if proto_fmt_type == ProtoFMT.Json:
        return b.decode('utf-8')
    elif proto_fmt_type == ProtoFMT.Protobuf:
        rsp = pb_map[proto_id]
        if IS_PY2:
            rsp.ParseFromString(str(b))
        else:
            rsp.ParseFromString(b)
        return MessageToJson(rsp)
    else:
        raise Exception('binary2str: unknown proto format.')

def binary2pb(b, proto_id, proto_fmt_type):
    """Transfer binary to pb message
    :param b: binary content to be transformed to pb message
    :return: pb message"""
    rsp = pb_map[proto_id]
    if rsp is None:
        return None
    if proto_fmt_type == ProtoFMT.Json:
        return json2pb(type(rsp), b.decode('utf-8'))
    elif proto_fmt_type == ProtoFMT.Protobuf:
        rsp = type(rsp)()
        if IS_PY2:
            rsp.ParseFromString(str(b))
        else:
            rsp.ParseFromString(b)
        return rsp
    else:
        raise Exception('binary2str: unknown proto format.')

def get_bond_symmetry(site_symmetry, lattice, positions, atom_center, atom_disp, symprec=1e-05):
    """Bond symmetry is the symmetry operations that keep the symmetry
    of the cell containing two fixed atoms."""
    bond_sym = []
    pos = positions
    for rot in site_symmetry:
        rot_pos = np.dot(pos[atom_disp] - pos[atom_center], rot.T) + pos[atom_center]
        diff = pos[atom_disp] - rot_pos
        diff -= np.rint(diff)
        dist = np.linalg.norm(np.dot(lattice, diff))
        if dist < symprec:
            bond_sym.append(rot)
    return np.array(bond_sym)

def get_least_orbits(atom_index, cell, site_symmetry, symprec=1e-05):
    """Find least orbits for a centering atom"""
    orbits = _get_orbits(atom_index, cell, site_symmetry, symprec)
    mapping = np.arange(cell.get_number_of_atoms())
    for i, orb in enumerate(orbits):
        for num in np.unique(orb):
            if mapping[num] > mapping[i]:
                mapping[num] = mapping[i]
    return np.unique(mapping)

def write_unitary_matrix_to_hdf5(temperature, mesh, unitary_matrix=None, sigma=None, sigma_cutoff=None, solver=None, filename=None, verbose=False):
    """Write eigenvectors of collision matrices at temperatures.

    Depending on the choice of the solver, eigenvectors are sotred in
    either column-wise or row-wise."""
    suffix = _get_filename_suffix(mesh, sigma=sigma, sigma_cutoff=sigma_cutoff, filename=filename)
    hdf5_filename = 'unitary' + suffix + '.hdf5'
    with h5py.File(hdf5_filename, 'w') as w:
        w.create_dataset('temperature', data=temperature)
        if unitary_matrix is not None:
            w.create_dataset('unitary_matrix', data=unitary_matrix)
        if solver is not None:
            w.create_dataset('solver', data=solver)
        if verbose:
            if len(temperature) > 1:
                text = 'Unitary matrices '
            else:
