            if sigma is not None:
                text += '\n'
            text += '"%s".' % hdf5_filename
            print(text)

def detect_scheme_and_format(source):
    """Detect scheme and format based on source and return as a tuple.

    Scheme is a minimum 2 letters before `://` (will be lower cased).
    For example `http` from `http://example.com/table.csv`"""
    if hasattr(source, 'read'):
        return ('stream', None)
    if not isinstance(source, six.string_types):
        return (None, 'inline')
    if 'docs.google.com/spreadsheets' in source:
        if 'export' not in source and 'pub' not in source:
            return (None, 'gsheet')
        elif 'csv' in source:
            return ('https', 'csv')
    for sql_scheme in config.SQL_SCHEMES:
        if source.startswith('%s://' % sql_scheme):
            return (None, 'sql')
    parsed = urlparse(source)
    scheme = parsed.scheme.lower()
    if len(scheme) < 2:
        scheme = config.DEFAULT_SCHEME
    format = os.path.splitext(parsed.path or parsed.netloc)[1][1:].lower() or None
    if format is None:
        query_string = parse_qs(parsed.query)
        query_string_format = query_string.get('format')
        if query_string_format is not None and len(query_string_format) == 1:
            format = query_string_format[0]
    if parsed.path.endswith('datapackage.json'):
        return (None, 'datapackage')
    return (scheme, format)

def detect_encoding(sample, encoding=None):
    """Detect encoding of a byte string sample.
    """
    from cchardet import detect
    if encoding is not None:
        return normalize_encoding(sample, encoding)
    result = detect(sample)
    confidence = result['confidence'] or 0
    encoding = result['encoding'] or 'ascii'
    encoding = normalize_encoding(sample, encoding)
    if confidence < config.ENCODING_CONFIDENCE:
        encoding = config.DEFAULT_ENCODING
    if encoding == 'ascii':
        encoding = config.DEFAULT_ENCODING
    return encoding

def normalize_encoding(sample, encoding):
    """Normalize encoding including 'utf-8-sig', 'utf-16-be', utf-16-le tweaks.
    """
    encoding = codecs.lookup(encoding).name
    if encoding == 'utf-8':
        if sample.startswith(codecs.BOM_UTF8):
            encoding = 'utf-8-sig'
    elif encoding == 'utf-16-be':
        if sample.startswith(codecs.BOM_UTF16_BE):
            encoding = 'utf-16'
    elif encoding == 'utf-16-le':
        if sample.startswith(codecs.BOM_UTF16_LE):
            encoding = 'utf-16'
    return encoding

def detect_html(text):
    """Detect if text is HTML.
    """
    pattern = re.compile('\\s*<(!doctype|html)', re.IGNORECASE)
    return bool(pattern.match(text))

def reset_stream(stream):
    """Reset stream pointer to the first element.

    If stream is not seekable raise Exception."""
    try:
        position = stream.tell()
    except Exception:
        position = True
    if position != 0:
        try:
            stream.seek(0)
        except Exception:
            message = "It's not possible to reset this stream"
            raise exceptions.TabulatorException(message)

def extract_options(options, names):
    """Return options for names and remove it from given options in-place.
    """
    result = {}
    for name, value in copy(options).items():
        if name in names:
            result[name] = value
            del options[name]
    return result

def stringify_value(value):
    """Convert any value to string.
    """
    if value is None:
        return u''
    isoformat = getattr(value, 'isoformat', None)
    if isoformat is not None:
        value = isoformat()
    return type(u'')(value)

def require_axis(f):
    """Check if the object of the function has axis and sel_axis members"""
    @wraps(f)
    def _wrapper(self, *args, **kwargs):
        if None in (self.axis, self.sel_axis):
            raise ValueError('%(func_name) requires the node %(node)s to have an axis and a sel_axis function' % dict(func_name=f.__name__, node=repr(self)))
        return f(self, *args, **kwargs)
    return _wrapper

def level_order(tree, include_all=False):
    """Returns an iterator over the tree in level-order

    If include_all is set to True, empty parts of the tree are filled
    with dummy entries and the iterator becomes infinite."""
    q = deque()
    q.append(tree)
    while q:
        node = q.popleft()
        yield node
        if include_all or node.left:
            q.append(node.left or node.__class__())
        if include_all or node.right:
            q.append(node.right or node.__class__())

def T(t, step=30):
    """The TOTP T value (number of time steps since the epoch)"""
    if hasattr(t, 'timestamp'):
        timestamp = t.timestamp()
    elif t.tzinfo is None:
        timestamp = time.mktime(t.timetuple())
    else:
        utc_naive = t.replace(tzinfo=None) - t.utcoffset()
        timestamp = (utc_naive - datetime.datetime(1970, 1, 1)).total_seconds()
    return int(timestamp) // step

def load_mnist_dataset(mode='supervised', one_hot=True):
    """Load the MNIST handwritten digits dataset.

    :param mode: 'supervised' or 'unsupervised' mode
    :param one_hot: whether to get one hot encoded labels
    :return: train, validation, test data:
            for (X, y) if 'supervised',
            for (X) if 'unsupervised'"""
    mnist = input_data.read_data_sets('MNIST_data/', one_hot=one_hot)
    trX = mnist.train.images
    trY = mnist.train.labels
    vlX = mnist.validation.images
    vlY = mnist.validation.labels
    teX = mnist.test.images
    teY = mnist.test.labels
    if mode == 'supervised':
        return (trX, trY, vlX, vlY, teX, teY)
    elif mode == 'unsupervised':
        return (trX, vlX, teX)

def load_cifar10_dataset(cifar_dir, mode='supervised'):
    """Load the cifar10 dataset.

    :param cifar_dir: path to the dataset directory
        (cPicle format from: https://www.cs.toronto.edu/~kriz/cifar.html)
    :param mode: 'supervised' or 'unsupervised' mode

    :return: train, test data:
            for (X, y) if 'supervised',
            for (X) if 'unsupervised'"""
    trX = None
    trY = np.array([])
    teX = np.array([])
    teY = np.array([])
    for fn in os.listdir(cifar_dir):
        if not fn.startswith('batches') and (not fn.startswith('readme')):
            fo = open(os.path.join(cifar_dir, fn), 'rb')
            data_batch = pickle.load(fo)
            fo.close()
            if fn.startswith('data'):
                if trX is None:
                    trX = data_batch['data']
                    trY = data_batch['labels']
                else:
                    trX = np.concatenate((trX, data_batch['data']), axis=0)
                    trY = np.concatenate((trY, data_batch['labels']), axis=0)
            if fn.startswith('test'):
                teX = data_batch['data']
                teY = data_batch['labels']
    trX = trX.astype(np.float32) / 255.0
    teX = teX.astype(np.float32) / 255.0
    if mode == 'supervised':
        return (trX, trY, teX, teY)
    elif mode == 'unsupervised':
        return (trX, teX)

def sample_prob(probs, rand):
    """Get samples from a tensor of probabilities.

    :param probs: tensor of probabilities
    :param rand: tensor (of the same shape as probs) of random values
    :return: binary sample of probabilities"""
    return tf.nn.relu(tf.sign(probs - rand))

def corrupt_input(data, sess, corrtype, corrfrac):
    """Corrupt a fraction of data according to the chosen noise method.

    :return: corrupted data"""
    corruption_ratio = np.round(corrfrac * data.shape[1]).astype(np.int)
    if corrtype == 'none':
        return np.copy(data)
    if corrfrac > 0.0:
        if corrtype == 'masking':
            return masking_noise(data, sess, corrfrac)
        elif corrtype == 'salt_and_pepper':
            return salt_and_pepper_noise(data, corruption_ratio)
    else:
        return np.copy(data)

def conv2bin(data):
    """Convert a matrix of probabilities into binary values.

    If the matrix has values <= 0 or >= 1, the values are
    normalized to be in [0, 1].

    :type data: numpy array
    :param data: input matrix
    :return: converted binary matrix"""
    if data.min() < 0 or data.max() > 1:
        data = normalize(data)
    out_data = data.copy()
    for i, sample in enumerate(out_data):
        for j, val in enumerate(sample):
            if np.random.random() <= val:
                out_data[i][j] = 1
            else:
                out_data[i][j] = 0
    return out_data

def expand_args(**args_to_expand):
    """Expand the given lists into the length of the layers.

    This is used as a convenience so that the user does not need to specify the
    complete list of parameters for model initialization.
    IE the user can just specify one parameter and this function will expand it"""
    layers = args_to_expand['layers']
    try:
        items = args_to_expand.iteritems()
    except AttributeError:
        items = args_to_expand.items()
    for key, val in items:
        if isinstance(val, list) and len(val) != len(layers):
            args_to_expand[key] = [val[0] for _ in layers]
    return args_to_expand

def flag_to_list(flagval, flagtype):
    """Convert a string of comma-separated tf flags to a list of values."""
    if flagtype == 'int':
        return [int(_) for _ in flagval.split(',') if _]
    elif flagtype == 'float':
        return [float(_) for _ in flagval.split(',') if _]
    elif flagtype == 'str':
        return [_ for _ in flagval.split(',') if _]
    else:
        raise Exception('incorrect type')

def str2actfunc(act_func):
    """Convert activation function name to tf function."""
    if act_func == 'sigmoid':
        return tf.nn.sigmoid
    elif act_func == 'tanh':
        return tf.nn.tanh
    elif act_func == 'relu':
        return tf.nn.relu

def random_seed_np_tf(seed):
    """Seed numpy and tensorflow random number generators.

    :param seed: seed parameter"""
    if seed >= 0:
        np.random.seed(seed)
        tf.set_random_seed(seed)
        return True
    else:
        return False

