def copy_byte_range(infile, outfile, start=None, stop=None, bufsize=16 * 1024):
    """Like shutil.copyfileobj, but only copy a range of the streams.

    Both start and stop are inclusive."""
    if start is not None:
        infile.seek(start)
    while 1:
        to_read = min(bufsize, stop + 1 - infile.tell() if stop else bufsize)
        buf = infile.read(to_read)
        if not buf:
            break
        outfile.write(buf)

def parse_byte_range(byte_range):
    """Returns the two numbers in 'bytes=123-456' or throws ValueError.

    The last number or both numbers may be None."""
    if byte_range.strip() == '':
        return (None, None)
    m = BYTE_RANGE_RE.match(byte_range)
    if not m:
        raise ValueError('Invalid byte range %s' % byte_range)
    first, last = [x and int(x) for x in m.groups()]
    if last and last < first:
        raise ValueError('Invalid byte range %s' % byte_range)
    return (first, last)

def get_author(package):
    """Return package version as listed in `__version__` in `init.py`."""
    init_py = readfile(os.path.join(package, '__init__.py'))
    author = re.search('__author__ = u?[\'"]([^\'"]+)[\'"]', init_py).group(1)
    return UltraMagicString(author)

def get_version(package):
    """Return package version as listed in `__version__` in `init.py`."""
    init_py = readfile(os.path.join(package, '__init__.py'))
    return re.search('__version__ = [\'"]([^\'"]+)[\'"]', init_py).group(1)

def cache_page(*args, **kwargs):
    """Same as django's ``cache_page`` decorator, but wraps the view into
    additional decorators before and after that. Makes it possible to serve multiple
    flavours without getting into trouble with django's caching that doesn't
    know about flavours."""
    decorator = _django_cache_page(*args, **kwargs)
    def flavoured_decorator(func):
        return vary_on_flavour_fetch(decorator(vary_on_flavour_update(func)))
    return flavoured_decorator

def DefaultRC():
    """Check XDG_CONFIG_DIR before ~/.cmakelintrc"""
    xdg = os.path.join(os.path.expanduser('~'), '.config')
    if 'XDG_CONFIG_DIR' in os.environ:
        xdg = os.environ['XDG_CONFIG_DIR']
    xdgfile = os.path.join(xdg, 'cmakelintrc')
    if os.path.exists(xdgfile):
        return xdgfile
    return os.path.join(os.path.expanduser('~'), '.cmakelintrc')

def CleanComments(line, quote=False):
    """quote means 'was in a quote starting this line' so that
    quoted lines can be eaten/removed."""
    if line.find('#') == -1 and line.find('"') == -1:
        if quote:
            return ('', quote)
        else:
            return (line, quote)
    prior = []
    prev = ''
    for char in line:
        try:
            if char == '"':
                if prev != '\\':
                    quote = not quote
                    prior.append(char)
                continue
            elif char == '#' and (not quote):
                break
            if not quote:
                prior.append(char)
        finally:
            prev = char
    return (''.join(prior).rstrip(), quote)

def CheckLineLength(filename, linenumber, clean_lines, errors):
    """Check for lines longer than the recommended length"""
    line = clean_lines.raw_lines[linenumber]
    if len(line) > _lint_state.linelength:
        return errors(filename, linenumber, 'linelength', 'Lines should be <= %d characters long' % _lint_state.linelength)

def CheckUpperLowerCase(filename, linenumber, clean_lines, errors):
    """Check that commands are either lower case or upper case, but not both"""
    line = clean_lines.lines[linenumber]
    if ContainsCommand(line):
        command = GetCommand(line)
        if IsCommandMixedCase(command):
            return errors(filename, linenumber, 'readability/wonkycase', 'Do not use mixed case commands')
        if clean_lines.have_seen_uppercase is None:
            clean_lines.have_seen_uppercase = IsCommandUpperCase(command)
        else:
            is_upper = IsCommandUpperCase(command)
            if is_upper != clean_lines.have_seen_uppercase:
                return errors(filename, linenumber, 'readability/mixedcase', 'Do not mix upper and lower case commands')

def CheckCommandSpaces(filename, linenumber, clean_lines, errors):
    """No extra spaces between command and parenthesis"""
    line = clean_lines.lines[linenumber]
    match = ContainsCommand(line)
    if match and len(match.group(2)):
        errors(filename, linenumber, 'whitespace/extra', "Extra spaces between '%s' and its ()" % match.group(1))
    if match:
        spaces_after_open = len(_RE_COMMAND_START_SPACES.match(line).group(1))
        initial_spaces = GetInitialSpaces(line)
        initial_linenumber = linenumber
        end = None
        while True:
            line = clean_lines.lines[linenumber]
            end = _RE_COMMAND_END_SPACES.search(line)
            if end:
                break
            linenumber += 1
            if linenumber >= len(clean_lines.lines):
                break
        if linenumber == len(clean_lines.lines) and (not end):
            errors(filename, initial_linenumber, 'syntax', 'Unable to find the end of this command')
        if end:
            spaces_before_end = len(end.group(1))
            initial_spaces = GetInitialSpaces(line)
            if initial_linenumber != linenumber and spaces_before_end >= initial_spaces:
                spaces_before_end -= initial_spaces
            if spaces_after_open != spaces_before_end:
                errors(filename, initial_linenumber, 'whitespace/mismatch', 'Mismatching spaces inside () after command')

def CheckRepeatLogic(filename, linenumber, clean_lines, errors):
    """Check for logic inside else, endif etc"""
    line = clean_lines.lines[linenumber]
    for cmd in _logic_commands:
        if re.search('\\b%s\\b' % cmd, line.lower()):
            m = _RE_LOGIC_CHECK.search(line)
            if m:
                errors(filename, linenumber, 'readability/logic', 'Expression repeated inside %s; better to use only %s()' % (cmd, m.group(1)))
            break

def _get_default_retry_params():
    """Get default RetryParams for current request and current thread.

    Returns:
      A new instance of the default RetryParams."""
    default = getattr(_thread_local_settings, 'default_retry_params', None)
    if default is None or not default.belong_to_current_request():
        return RetryParams()
    else:
        return copy.copy(default)

def _should_retry(resp):
    """Given a urlfetch response, decide whether to retry that request."""
    return resp.status_code == httplib.REQUEST_TIMEOUT or (resp.status_code >= 500 and resp.status_code < 600)

def _eager_tasklet(tasklet):
    """Decorator to turn tasklet to run eagerly."""
    @utils.wrapping(tasklet)
    def eager_wrapper(*args, **kwds):
        fut = tasklet(*args, **kwds)
        _run_until_rpc()
        return fut
    return eager_wrapper

def get_metadata(headers):
    """Get user defined options from HTTP response headers."""
    return dict(((k, v) for k, v in headers.iteritems() if any((k.lower().startswith(valid) for valid in _GCS_METADATA))))

def validate_options(options):
    """Validate Google Cloud Storage options.

    Args:
      options: a str->basestring dict of options to pass to Google Cloud Storage.

    Raises:
      ValueError: if option is not supported.
      TypeError: if option is not of type str or value of an option
        is not of type basestring."""
    if not options:
        return
    for k, v in options.iteritems():
        if not isinstance(k, str):
            raise TypeError('option %r should be a str.' % k)
        if not any((k.lower().startswith(valid) for valid in _GCS_OPTIONS)):
            raise ValueError('option %s is not supported.' % k)
        if not isinstance(v, basestring):
            raise TypeError('value %r for option %s should be of type basestring.' % (v, k))

def local_run():
    """Whether we should hit GCS dev appserver stub."""
    server_software = os.environ.get('SERVER_SOFTWARE')
    if server_software is None:
        return True
    if 'remote_api' in server_software:
        return False
    if server_software.startswith(('Development', 'testutil')):
        return True
    return False

def _extractall(self, path='.', members=None):
    """Extract all members from the archive to the current working
    directory and set owner, modification time and permissions on
    directories afterwards. `path' specifies a different directory
    to extract to. `members' is optional and must be a subset of the
    list returned by getmembers()."""
    import copy
    import operator
    from tarfile import ExtractError
    directories = []
    if members is None:
        members = self
    for tarinfo in members:
        if tarinfo.isdir():
            directories.append(tarinfo)
            tarinfo = copy.copy(tarinfo)
            tarinfo.mode = 448
        self.extract(tarinfo, path)
    if sys.version_info < (2, 4):
        def sorter(dir1, dir2):
            return cmp(dir1.name, dir2.name)
        directories.sort(sorter)
        directories.reverse()
    else:
        directories.sort(key=operator.attrgetter('name'), reverse=True)
    for tarinfo in directories:
        dirpath = os.path.join(path, tarinfo.name)
        try:
            self.chown(tarinfo, dirpath)
            self.utime(tarinfo, dirpath)
            self.chmod(tarinfo, dirpath)
        except ExtractError:
            e = sys.exc_info()[1]
            if self.errorlevel > 1:
                raise
            else:
                self._dbg(1, 'tarfile: %s' % e)

def check_palette(palette):
    """Check a palette argument (to the :class:`Writer` class) for validity.
    Returns the palette as a list if okay;
    raises an exception otherwise."""
    if palette is None:
        return None
    p = list(palette)
    if not 0 < len(p) <= 256:
        raise ProtocolError('a palette must have between 1 and 256 entries, see https://www.w3.org/TR/PNG/#11PLTE')
    seen_triple = False
    for i, t in enumerate(p):
        if len(t) not in (3, 4):
            raise ProtocolError('palette entry %d: entries must be 3- or 4-tuples.' % i)
        if len(t) == 3:
            seen_triple = True
        if seen_triple and len(t) == 4:
            raise ProtocolError('palette entry %d: all 4-tuples must precede all 3-tuples' % i)
        for x in t:
            if int(x) != x or not 0 <= x <= 255:
                raise ProtocolError('palette entry %d: values must be integer: 0 <= x <= 255' % i)
    return p

def check_sizes(size, width, height):
    """Check that these arguments, if supplied, are consistent.
    Return a (width, height) pair."""
    if not size:
        return (width, height)
    if len(size) != 2:
        raise ProtocolError('size argument should be a pair (width, height)')
    if width is not None and width != size[0]:
        raise ProtocolError('size[0] (%r) and width (%r) should match when both are used.' % (size[0], width))
    if height is not None and height != size[1]:
        raise ProtocolError('size[1] (%r) and height (%r) should match when both are used.' % (size[1], height))
    return size

def check_color(c, greyscale, which):
    """Checks that a colour argument for transparent or background options
    is the right form.
    Returns the colour
    (which, if it's a bare integer, is "corrected" to a 1-tuple)."""
    if c is None:
        return c
    if greyscale:
        try:
            len(c)
        except TypeError:
            c = (c,)
        if len(c) != 1:
            raise ProtocolError('%s for greyscale must be 1-tuple' % which)
        if not is_natural(c[0]):
            raise ProtocolError('%s colour for greyscale must be integer' % which)
    elif not (len(c) == 3 and is_natural(c[0]) and is_natural(c[1]) and is_natural(c[2])):
        raise ProtocolError('%s colour must be a triple of integers' % which)
    return c

def write_chunks(out, chunks):
    """Create a PNG file by writing out the chunks."""
    out.write(signature)
    for chunk in chunks:
        write_chunk(out, *chunk)

def unpack_rows(rows):
    """Unpack each row from being 16-bits per value,
    to being a sequence of bytes."""
    for row in rows:
        fmt = '!%dH' % len(row)
        yield bytearray(struct.pack(fmt, *row))

def make_palette_chunks(palette):
    """Create the byte sequences for a ``PLTE`` and
    if necessary a ``tRNS`` chunk.
    Returned as a pair (*p*, *t*).
    *t* will be ``None`` if no ``tRNS`` chunk is necessary."""
    p = bytearray()
    t = bytearray()
    for x in palette:
        p.extend(x[0:3])
        if len(x) > 3:
            t.append(x[3])
    if t:
        return (p, t)
    return (p, None)

def check_bitdepth_rescale(palette, bitdepth, transparent, alpha, greyscale):
    """Returns (bitdepth, rescale) pair."""
    if palette:
        if len(bitdepth) != 1:
            raise ProtocolError('with palette, only a single bitdepth may be used')
        bitdepth, = bitdepth
        if bitdepth not in (1, 2, 4, 8):
            raise ProtocolError('with palette, bitdepth must be 1, 2, 4, or 8')
        if transparent is not None:
            raise ProtocolError('transparent and palette not compatible')
        if alpha:
            raise ProtocolError('alpha and palette not compatible')
        if greyscale:
            raise ProtocolError('greyscale and palette not compatible')
        return (bitdepth, None)
    if greyscale and (not alpha):
        bitdepth, = bitdepth
        if bitdepth in (1, 2, 4, 8, 16):
            return (bitdepth, None)
        if bitdepth > 8:
            targetbitdepth = 16
        elif bitdepth == 3:
            targetbitdepth = 4
        else:
            assert bitdepth in (5, 6, 7)
            targetbitdepth = 8
        return (targetbitdepth, [(bitdepth, targetbitdepth)])
    assert alpha or not greyscale
    depth_set = tuple(set(bitdepth))
    if depth_set in [(8,), (16,)]:
        bitdepth, = depth_set
        return (bitdepth, None)
    targetbitdepth = (8, 16)[max(bitdepth) > 8]
    return (targetbitdepth, [(b, targetbitdepth) for b in bitdepth])

def check_bitdepth_colortype(bitdepth, colortype):
    """Check that `bitdepth` and `colortype` are both valid,
    and specified in a valid combination.
    Returns (None) if valid, raise an Exception if not valid."""
    if bitdepth not in (1, 2, 4, 8, 16):
        raise FormatError('invalid bit depth %d' % bitdepth)
    if colortype not in (0, 2, 3, 4, 6):
        raise FormatError('invalid colour type %d' % colortype)
    if colortype & 1 and bitdepth > 8:
        raise FormatError('Indexed images (colour type %d) cannot have bitdepth > 8 (bit depth %d). See http://www.w3.org/TR/2003/REC-PNG-20031110/#table111 .' % (bitdepth, colortype))
    if bitdepth < 8 and colortype not in (0, 3):
        raise FormatError('Illegal combination of bit depth (%d) and colour type (%d). See http://www.w3.org/TR/2003/REC-PNG-20031110/#table111 .' % (bitdepth, colortype))

def is_natural(x):
    """A non-negative integer."""
    try:
        is_integer = int(x) == x
    except (TypeError, ValueError):
        return False
    return is_integer and x >= 0

def undo_filter_up(filter_unit, scanline, previous, result):
    """Undo up filter."""
    for i in range(len(result)):
        x = scanline[i]
        b = previous[i]
        result[i] = x + b & 255

def undo_filter_average(filter_unit, scanline, previous, result):
    """Undo up filter."""
    ai = -filter_unit
    for i in range(len(result)):
        x = scanline[i]
        if ai < 0:
            a = 0
        else:
            a = result[ai]
        b = previous[i]
        result[i] = x + (a + b >> 1) & 255
        ai += 1

def undo_filter_paeth(filter_unit, scanline, previous, result):
    """Undo Paeth filter."""
    ai = -filter_unit
    for i in range(len(result)):
        x = scanline[i]
        if ai < 0:
            a = c = 0
        else:
            a = result[ai]
            c = previous[ai]
        b = previous[i]
        p = a + b - c
        pa = abs(p - a)
        pb = abs(p - b)
        pc = abs(p - c)
        if pa <= pb and pa <= pc:
            pr = a
        elif pb <= pc:
            pr = b
        else:
            pr = c
        result[i] = x + pr & 255
        ai += 1

def binary_stdout():
    """A sys.stdout that accepts bytes."""
    try:
        stdout = sys.stdout.buffer
    except AttributeError:
        stdout = sys.stdout
    if sys.platform == 'win32':
        import msvcrt
        import os
        msvcrt.setmode(sys.stdout.fileno(), os.O_BINARY)
    return stdout

def _dehex(s):
    """Liberally convert from hex string to binary string."""
    import re
    import binascii
    s = re.sub(b'[^a-fA-F\\d]', b'', s)
    return binascii.unhexlify(s)

def black(m):
    """Return a function that maps all values from [0.0,m] to 0, and maps
    the range [m,1.0] into [0.0, 1.0] linearly."""
    m = float(m)
    def f(x):
        if x <= m:
            return 0.0
        return (x - m) / (1.0 - m)
    return f

def linetoraster(m):
    """Convert a single line of text *m* to a raster image,
    by rendering it using the font in *font*.

    A triple of (*width*, *height*, *pixels*) is returned;
    *pixels* is in boxed row packed pixel format."""
    x = 8 * len(m)
    y = 8
    return (x, y, [itertools.chain(*row) for row in zip(*map(char, m))])

def writeICCdatetime(t=None):
    """`t` should be a gmtime tuple (as returned from
    ``time.gmtime()``).  If not supplied, the current time will be used.
    Return an ICC dateTimeNumber in a 12 byte string."""
    import time
    if t is None:
        t = time.gmtime()
    return struct.pack('>6H', *t[:6])

def s15f16l(s):
    """Convert sequence of ICC s15Fixed16 to list of float."""
    n = len(s) // 4
    t = struct.unpack('>%dl' % n, s)
    return map((2 ** (-16)).__mul__, t)

def ICCdecode(s):
    """Take an ICC encoded tag, and dispatch on its type signature
    (first 4 bytes) to decode it into a Python value.  Pair (*sig*,
    *value*) is returned, where *sig* is a 4 byte string, and *value* is
    some Python value determined by the content and type."""
    sig = s[0:4].strip()
    f = dict(text=RDtext, XYZ=RDXYZ, curv=RDcurv, vcgt=RDvcgt, sf32=RDsf32)
    if sig not in f:
        return None
    return (sig, f[sig](s))

def RDcurv(s):
    """Convert ICC curveType."""
    assert s[0:4] == 'curv'
    count, = struct.unpack('>L', s[8:12])
    if count == 0:
        return dict(gamma=1)
    table = struct.unpack('>%dH' % count, s[12:])
    if count == 1:
        return dict(gamma=table[0] * 2 ** (-8))
    return table

def RDvcgt(s):
    """Convert Apple CMVideoCardGammaType."""
    assert s[0:4] == 'vcgt'
    tagtype, = struct.unpack('>L', s[8:12])
    if tagtype != 0:
        return s[8:]
    if tagtype == 0:
        channels, count, size = struct.unpack('>3H', s[12:18])
        if size == 1:
            fmt = 'B'
        elif size == 2:
            fmt = 'H'
        else:
            return s[8:]
        n = len(s[18:]) // size
        t = struct.unpack('>%d%s' % (n, fmt), s[18:])
        t = group(t, count)
        return (size, t)
    return s[8:]

def glue(f, r):
    """Return (metadata, stream) pair where `r` is the initial portion of
    the metadata that has already been read from the stream `f`."""
    r = r + f.read(60 - len(r))
    return (r, f)

def bitdepthof(pixel):
    """Return the bitdepth for a Plan9 pixel format string."""
    maxd = 0
    for c in re.findall('[a-z]\\d*', pixel):
        if c[0] != 'x':
            maxd = max(maxd, int(c[1:]))
    return maxd

def aws_to_unix_id(aws_key_id):
    """Converts a AWS Key ID into a UID"""
    uid_bytes = hashlib.sha256(aws_key_id.encode()).digest()[-2:]
    if USING_PYTHON2:
        return 2000 + int(from_bytes(uid_bytes) // 2)
    else:
        return 2000 + int.from_bytes(uid_bytes, byteorder=sys.byteorder) // 2

def _gorg(cls):
    """This function exists for compatibility with old typing versions."""
    assert isinstance(cls, GenericMeta)
    if hasattr(cls, '_gorg'):
        return cls._gorg
    while cls.__origin__ is not None:
        cls = cls.__origin__
    return cls

def is_optional_type(tp):
    """Returns `True` if the type is `type(None)`, or is a direct `Union` to `type(None)`, such as `Optional[T]`.

    NOTE: this method inspects nested `Union` arguments but not `TypeVar` definitions (`bound`/`constraint`). So it
    will return `False` if
     - `tp` is a `TypeVar` bound, or constrained to, an optional type
     - `tp` is a `Union` to a `TypeVar` bound or constrained to an optional type,
     - `tp` refers to a *nested* `Union` containing an optional type or one of the above.

    Users wishing to check for optionality in types relying on type variables might wish to use this method in
    combination with `get_constraints` and `get_bound`"""
    if tp is type(None):
        return True
    elif is_union_type(tp):
        return any((is_optional_type(tt) for tt in get_args(tp, evaluate=True)))
    else:
        return False

def is_union_type(tp):
    """Test if the type is a union type. Examples::

    is_union_type(int) == False
    is_union_type(Union) == True
    is_union_type(Union[int, int]) == False
    is_union_type(Union[T, int]) == True"""
    if NEW_TYPING:
        return tp is Union or (isinstance(tp, _GenericAlias) and tp.__origin__ is Union)
    return type(tp) is _Union

def get_origin(tp):
    """Get the unsubscripted version of a type. Supports generic types, Union,
    Callable, and Tuple. Returns None for unsupported types. Examples::

        get_origin(int) == None
        get_origin(ClassVar[int]) == None
        get_origin(Generic) == Generic
        get_origin(Generic[T]) == Generic
        get_origin(Union[T, int]) == Union
        get_origin(List[Tuple[T, T]][int]) == list  # List prior to Python 3.7"""
    if NEW_TYPING:
        if isinstance(tp, _GenericAlias):
            return tp.__origin__ if tp.__origin__ is not ClassVar else None
        if tp is Generic:
            return Generic
        return None
    if isinstance(tp, GenericMeta):
        return _gorg(tp)
    if is_union_type(tp):
        return Union
    return None

def get_parameters(tp):
    """Return type parameters of a parameterizable type as a tuple
    in lexicographic order. Parameterizable types are generic types,
    unions, tuple types and callable types. Examples::

        get_parameters(int) == ()
        get_parameters(Generic) == ()
        get_parameters(Union) == ()
        get_parameters(List[int]) == ()

        get_parameters(Generic[T]) == (T,)
        get_parameters(Tuple[List[T], List[S_co]]) == (T, S_co)
        get_parameters(Union[S_co, Tuple[T, T]][int, U]) == (U,)
        get_parameters(Mapping[T, Tuple[S_co, T]]) == (T, S_co)"""
    if NEW_TYPING:
        if isinstance(tp, _GenericAlias) or (isinstance(tp, type) and issubclass(tp, Generic) and (tp is not Generic)):
            return tp.__parameters__
        return ()
    if is_generic_type(tp) or is_union_type(tp) or is_callable_type(tp) or is_tuple_type(tp):
        return tp.__parameters__ if tp.__parameters__ is not None else ()
    return ()

def get_last_args(tp):
    """Get last arguments of (multiply) subscripted type.
    Parameters for Callable are flattened. Examples::

     get_last_args(int) == ()
     get_last_args(Union) == ()
     get_last_args(ClassVar[int]) == (int,)
     get_last_args(Union[T, int]) == (T, int)
     get_last_args(Iterable[Tuple[T, S]][int, T]) == (int, T)
     get_last_args(Callable[[T], int]) == (T, int)
     get_last_args(Callable[[], int]) == (int,)"""
    if NEW_TYPING:
        raise ValueError('This function is only supported in Python 3.6, use get_args instead')
    if is_classvar(tp):
        return (tp.__type__,) if tp.__type__ is not None else ()
    if is_generic_type(tp) or is_union_type(tp) or is_callable_type(tp) or is_tuple_type(tp):
        return tp.__args__ if tp.__args__ is not None else ()
    return ()

def _eval_args(args):
    """Internal helper for get_args."""
    res = []
    for arg in args:
        if not isinstance(arg, tuple):
            res.append(arg)
        elif is_callable_type(arg[0]):
            callable_args = _eval_args(arg[1:])
            if len(arg) == 2:
                res.append(Callable[[], callable_args[0]])
            elif arg[1] is Ellipsis:
                res.append(Callable[..., callable_args[1]])
            else:
                res.append(Callable[list(callable_args[:-1]), callable_args[-1]])
        else:
            res.append(type(arg[0]).__getitem__(arg[0], _eval_args(arg[1:])))
    return tuple(res)

def log_request(request: str, trim_log_values: bool=False, **kwargs: Any) -> None:
    """Log a request"""
    return log_(request, request_logger, logging.INFO, trim=trim_log_values, **kwargs)

def log_response(response: str, trim_log_values: bool=False, **kwargs: Any) -> None:
    """Log a response"""
    return log_(response, response_logger, logging.INFO, trim=trim_log_values, **kwargs)

def call_requests(requests: Union[Request, Iterable[Request]], methods: Methods, debug: bool) -> Response:
    """Takes a request or list of Requests and calls them.

    Args:
        requests: Request object, or a collection of them.
        methods: The list of methods that can be called.
        debug: Include more information in error responses."""
    if isinstance(requests, collections.Iterable):
        return BatchResponse((safe_call(r, methods, debug=debug) for r in requests))
    return safe_call(requests, methods, debug=debug)

def create_requests(requests: Union[Dict, List], *, context: Any=NOCONTEXT, convert_camel_case: bool) -> Union[Request, Set[Request]]:
    """Create a Request object from a dictionary (or list of them).

    Args:
        requests: Request object, or a collection of them.
        methods: The list of methods that can be called.
        context: If specified, will be the first positional argument in all requests.
        convert_camel_case: Will convert the method name/any named params to snake case.

    Returns:
        A Request object, or a collection of them."""
    if isinstance(requests, list):
        return {Request(context=context, convert_camel_case=convert_camel_case, **request) for request in requests}
    return Request(context=context, convert_camel_case=convert_camel_case, **requests)

def dispatch_pure(request: str, methods: Methods, *, context: Any, convert_camel_case: bool, debug: bool) -> Response:
    """Pure version of dispatch - no logging, no optional parameters.

    Does two things:
        1. Deserializes and validates the string.
        2. Calls each request.

    Args:
        request: The incoming request string.
        methods: Collection of methods that can be called.
        context: If specified, will be the first positional argument in all requests.
        convert_camel_case: Will convert the method name/any named params to snake case.
        debug: Include more information in error responses.
    Returns:
        A Response."""
    try:
        deserialized = validate(deserialize(request), schema)
    except JSONDecodeError as exc:
        return InvalidJSONResponse(data=str(exc), debug=debug)
    except ValidationError as exc:
        return InvalidJSONRPCResponse(data=None, debug=debug)
    return call_requests(create_requests(deserialized, context=context, convert_camel_case=convert_camel_case), methods, debug=debug)

def convert_camel_case_keys(original_dict: Dict[str, Any]) -> Dict[str, Any]:
    """Converts all keys of a dict from camel case to snake case, recursively"""
    new_dict = dict()
    for key, val in original_dict.items():
        if isinstance(val, dict):
            new_dict[convert_camel_case_string(key)] = convert_camel_case_keys(val)
        else:
            new_dict[convert_camel_case_string(key)] = val
    return new_dict

def log_(message: str, logger: logging.Logger, level: int=logging.INFO, extra: Optional[Dict]=None, trim: bool=False) -> None:
    """Log a request or response

    Args:
        message: JSON-RPC request or response string.
        logger:
        level: Log level.
        extra: More details to include in the log entry.
        trim: Abbreviate log messages."""
    if extra is None:
        extra = {}
    if message:
        message = message.replace('\n', '').replace('  ', ' ').replace('{ ', '{')
    if trim:
        message = _trim_message(message)
    logger.log(level, message, extra=extra)

