def get_cassandra_connections():
    """:return: List of tuples (db_alias, connection) for all cassandra
    connections in DATABASES dict."""
    from django.db import connections
    for alias in connections:
        engine = connections[alias].settings_dict.get('ENGINE', '')
        if engine == 'django_cassandra_engine':
            yield (alias, connections[alias])

def get_default_cassandra_connection():
    """Return first default cassandra connection
    :return:"""
    for alias, conn in get_cassandra_connections():
        if conn.connection.default:
            return (alias, conn)
    return list(get_cassandra_connections())[0]

def get_cassandra_connection(alias=None, name=None):
    """:return: cassandra connection matching alias or name or just first found."""
    for _alias, connection in get_cassandra_connections():
        if alias is not None:
            if alias == _alias:
                return connection
        elif name is not None:
            if name == connection.settings_dict['NAME']:
                return connection
        else:
            return connection

def convert_pk_field_names_to_real(model, field_names):
    """Convert field names including 'pk' to the real field names:

    >>> convert_pk_field_names_to_real(['pk', 'another_field'])
    ['real_pk_field', 'another_field']"""
    pk_field_names = tuple((f.name for f in model._get_primary_key_columns()))
    def append_field(field_name):
        if field_name not in real_field_names:
            real_field_names.append(field_name)
    real_field_names = []
    for name in field_names:
        if name == 'pk':
            for real_pk_field_name in pk_field_names:
                append_field(real_pk_field_name)
        elif name == '-pk':
            for real_pk_field_name in pk_field_names:
                append_field('-' + real_pk_field_name)
        else:
            append_field(name)
    return real_field_names

def get_cache_key(user_or_username, size, prefix):
    """Returns a cache key consisten of a username and image size."""
    if isinstance(user_or_username, get_user_model()):
        user_or_username = get_username(user_or_username)
    key = six.u('%s_%s_%s') % (prefix, user_or_username, size)
    return six.u('%s_%s') % (slugify(key)[:100], hashlib.md5(force_bytes(key)).hexdigest())

def cache_result(default_size=settings.AVATAR_DEFAULT_SIZE):
    """Decorator to cache the result of functions that take a ``user`` and a
    ``size`` value."""
    if not settings.AVATAR_CACHE_ENABLED:
        def decorator(func):
            return func
        return decorator
    def decorator(func):
        def cached_func(user, size=None, **kwargs):
            prefix = func.__name__
            cached_funcs.add(prefix)
            key = get_cache_key(user, size or default_size, prefix=prefix)
            result = cache.get(key)
            if result is None:
                result = func(user, size or default_size, **kwargs)
                cache_set(key, result)
            return result
        return cached_func
    return decorator

def invalidate_cache(user, size=None):
    """Function to be called when saving or changing an user's avatars."""
    sizes = set(settings.AVATAR_AUTO_GENERATE_SIZES)
    if size is not None:
        sizes.add(size)
    for prefix in cached_funcs:
        for size in sizes:
            cache.delete(get_cache_key(user, size, prefix))

def read_avro(file_path_or_buffer, schema=None, **kwargs):
    """Avro file reader.

    Args:
        file_path_or_buffer: Input file path or file-like object.
        schema: Avro schema.
        **kwargs: Keyword argument to pandas.DataFrame.from_records.

    Returns:
        Class of pd.DataFrame."""
    if isinstance(file_path_or_buffer, six.string_types):
        with open(file_path_or_buffer, 'rb') as f:
            return __file_to_dataframe(f, schema, **kwargs)
    else:
        return __file_to_dataframe(file_path_or_buffer, schema, **kwargs)

def is_undirected(matrix):
    """Determine if the matrix reprensents a directed graph

    :param matrix: The matrix to tested
    :returns: boolean"""
    if isspmatrix(matrix):
        return sparse_allclose(matrix, matrix.transpose())
    return np.allclose(matrix, matrix.T)

def convert_to_adjacency_matrix(matrix):
    """Converts transition matrix into adjacency matrix

    :param matrix: The matrix to be converted
    :returns: adjacency matrix"""
    for i in range(matrix.shape[0]):
        if isspmatrix(matrix):
            col = find(matrix[:, i])[2]
        else:
            col = matrix[:, i].T.tolist()[0]
        coeff = max((Fraction(c).limit_denominator().denominator for c in col))
        matrix[:, i] *= coeff
    return matrix

def delta_matrix(matrix, clusters):
    """Compute delta matrix where delta[i,j]=1 if i and j belong
    to same cluster and i!=j

    :param matrix: The adjacency matrix
    :param clusters: The clusters returned by get_clusters
    :returns: delta matrix"""
    if isspmatrix(matrix):
        delta = dok_matrix(matrix.shape)
    else:
        delta = np.zeros(matrix.shape)
    for i in clusters:
        for j in permutations(i, 2):
            delta[j] = 1
    return delta

def inflate(matrix, power):
    """Apply cluster inflation to the given matrix by raising
    each element to the given power.

    :param matrix: The matrix to be inflated
    :param power: Cluster inflation parameter
    :returns: The inflated matrix"""
    if isspmatrix(matrix):
        return normalize(matrix.power(power))
    return normalize(np.power(matrix, power))

def expand(matrix, power):
    """Apply cluster expansion to the given matrix by raising
    the matrix to the given power.

    :param matrix: The matrix to be expanded
    :param power: Cluster expansion parameter
    :returns: The expanded matrix"""
    if isspmatrix(matrix):
        return matrix ** power
    return np.linalg.matrix_power(matrix, power)

def add_self_loops(matrix, loop_value):
    """Add self-loops to the matrix by setting the diagonal
    to loop_value

    :param matrix: The matrix to add loops to
    :param loop_value: Value to use for self-loops
    :returns: The matrix with self-loops"""
    shape = matrix.shape
    assert shape[0] == shape[1], 'Error, matrix is not square'
    if isspmatrix(matrix):
        new_matrix = matrix.todok()
    else:
        new_matrix = matrix.copy()
    for i in range(shape[0]):
        new_matrix[i, i] = loop_value
    if isspmatrix(matrix):
        return new_matrix.tocsc()
    return new_matrix

def converged(matrix1, matrix2):
    """Check for convergence by determining if
    matrix1 and matrix2 are approximately equal.

    :param matrix1: The matrix to compare with matrix2
    :param matrix2: The matrix to compare with matrix1
    :returns: True if matrix1 and matrix2 approximately equal"""
    if isspmatrix(matrix1) or isspmatrix(matrix2):
        return sparse_allclose(matrix1, matrix2)
    return np.allclose(matrix1, matrix2)

def get_clusters(matrix):
    """Retrieve the clusters from the matrix

    :param matrix: The matrix produced by the MCL algorithm
    :returns: A list of tuples where each tuple represents a cluster and
              contains the indices of the nodes belonging to the cluster"""
    if not isspmatrix(matrix):
        matrix = csc_matrix(matrix)
    attractors = matrix.diagonal().nonzero()[0]
    clusters = set()
    for attractor in attractors:
        cluster = tuple(matrix.getrow(attractor).nonzero()[1].tolist())
        clusters.add(cluster)
    return sorted(list(clusters))

def _guess_concat(data):
    """Guess concat function from given data"""
    return {type(u''): u''.join, type(b''): concat_bytes}.get(type(data), list)

def to_buffer(f):
    """Decorator converting all strings and iterators/iterables into Buffers."""
    @functools.wraps(f)
    def wrap(*args, **kwargs):
        iterator = kwargs.get('iterator', args[0])
        if not isinstance(iterator, Buffer):
            iterator = Buffer(iterator)
        return f(iterator, *args[1:], **kwargs)
    return wrap

def read(tex):
    """Read and parse all LaTeX source

    :param Union[str,iterable] tex: LaTeX source
    :return TexEnv: the global environment"""
    if isinstance(tex, str):
        tex = tex
    else:
        tex = ''.join(itertools.chain(*tex))
    buf, children = (Buffer(tokenize(tex)), [])
    while buf.hasNext():
        content = read_tex(buf)
        if content is not None:
            children.append(content)
    return (TexEnv('[tex]', children), tex)

def resolve(tex):
    """Resolve all imports and update the parse tree.

    Reads from a tex file and once finished, writes to a tex file."""
    soup = TexSoup(tex)
    for subimport in soup.find_all('subimport'):
        path = subimport.args[0] + subimport.args[1]
        subimport.replace_with(*resolve(open(path)).contents)
    for _import in soup.find_all('import'):
        _import.replace_with(*resolve(open(_import.args[0])).contents)
    for include in soup.find_all('include'):
        include.replace_with(*resolve(open(include.args[0])).contents)
    return soup

def tokenize_punctuation_command(text):
    """Process command that augments or modifies punctuation.

    This is important to the tokenization of a string, as opening or closing
    punctuation is not supposed to match.

    :param Buffer text: iterator over text, with current position"""
    if text.peek() == '\\':
        for point in PUNCTUATION_COMMANDS:
            if text.peek((1, len(point) + 1)) == point:
                return text.forward(len(point) + 1)

def tokenize_command(text):
    """Process command, but ignore line breaks. (double backslash)

    :param Buffer text: iterator over line, with current position"""
    if text.peek() == '\\':
        c = text.forward(1)
        tokens = set(string.punctuation + string.whitespace) - {'*'}
        while text.hasNext() and (c == '\\' or text.peek() not in tokens) and (c not in MATH_TOKENS):
            c += text.forward(1)
        return c

def tokenize_argument(text):
    """Process both optional and required arguments.

    :param Buffer text: iterator over line, with current position"""
    for delim in ARG_TOKENS:
        if text.startswith(delim):
            return text.forward(len(delim))

def read_tex(src):
    """Read next expression from buffer

    :param Buffer src: a buffer of tokens"""
    c = next(src)
    if c.startswith('%'):
        return c
    elif c.startswith('$'):
        name = '$$' if c.startswith('$$') else '$'
        expr = TexEnv(name, [], nobegin=True)
        return read_math_env(src, expr)
    elif c.startswith('\\[') or c.startswith('\\('):
        if c.startswith('\\['):
            name = 'displaymath'
            begin = '\\['
            end = '\\]'
        else:
            name = 'math'
            begin = '\\('
            end = '\\)'
        expr = TexEnv(name, [], nobegin=True, begin=begin, end=end)
        return read_math_env(src, expr)
    elif c.startswith('\\'):
        command = TokenWithPosition(c[1:], src.position)
        if command == 'item':
            contents, arg = read_item(src)
            mode, expr = ('command', TexCmd(command, contents, arg))
        elif command == 'begin':
            mode, expr, _ = ('begin', TexEnv(src.peek(1)), src.forward(3))
        else:
            mode, expr = ('command', TexCmd(command))
        expr.args = read_args(src, expr.args)
        if mode == 'begin':
            read_env(src, expr)
        return expr
    if c in ARG_START_TOKENS:
        return read_arg(src, c)
    return c

def read_item(src):
    """Read the item content.

    There can be any number of whitespace characters between \\item and the first
    non-whitespace character. However, after that first non-whitespace
    character, the item can only tolerate one successive line break at a time.

    \\item can also take an argument.

    :param Buffer src: a buffer of tokens
    :return: contents of the item and any item arguments"""
    def stringify(s):
        return TokenWithPosition.join(s.split(' '), glue=' ')
    def forward_until_new(s):
        """Catch the first non-whitespace character"""
        t = TokenWithPosition('', s.peek().position)
        while s.hasNext() and any([s.peek().startswith(substr) for substr in string.whitespace]) and (not t.strip(' ').endswith('\n')):
            t += s.forward(1)
        return t
    arg = []
    extra = []
    if src.peek() in ARG_START_TOKENS:
        c = next(src)
        a = read_arg(src, c)
        arg.append(a)
    if not src.hasNext():
        return (extra, arg)
    last = stringify(forward_until_new(src))
    extra.append(last.lstrip(' '))
    while src.hasNext() and (not str(src).strip(' ').startswith('\n\n')) and (not src.startswith('\\item')) and (not src.startswith('\\end')) and (not (isinstance(last, TokenWithPosition) and last.strip(' ').endswith('\n\n') and (len(extra) > 1))):
        last = read_tex(src)
        extra.append(last)
    return (extra, arg)

def read_env(src, expr):
    """Read the environment from buffer.

    Advances the buffer until right after the end of the environment. Adds
    parsed content to the expression automatically.

    :param Buffer src: a buffer of tokens
    :param TexExpr expr: expression for the environment
    :rtype: TexExpr"""
    contents = []
    if expr.name in SKIP_ENVS:
        contents = [src.forward_until(lambda s: s == '\\end')]
    while src.hasNext() and (not src.startswith('\\end{%s}' % expr.name)):
        contents.append(read_tex(src))
    if not src.startswith('\\end{%s}' % expr.name):
        end = src.peek((0, 5))
        explanation = 'Instead got %s' % end if end else 'Reached end of file.'
        raise EOFError('Expecting \\end{%s}. %s' % (expr.name, explanation))
    else:
        src.forward(4)
    expr.append(*contents)
    return expr

def read_arg(src, c):
    """Read the argument from buffer.

    Advances buffer until right before the end of the argument.

    :param Buffer src: a buffer of tokens
    :param str c: argument token (starting token)
    :return: the parsed argument
    :rtype: Arg"""
    content = [c]
    while src.hasNext():
        if src.peek() in ARG_END_TOKENS:
            content.append(next(src))
            break
        else:
            content.append(read_tex(src))
    return Arg.parse(content)

def ssl_required(allow_non_ssl=False):
    """Views decorated with this will always get redirected to https
    except when allow_non_ssl is set to true."""
    def wrapper(view_func):
        def _checkssl(request, *args, **kwargs):
            if hasattr(settings, 'SSL_ENABLED') and settings.SSL_ENABLED and (not request.is_secure()) and (not allow_non_ssl):
                return HttpResponseRedirect(request.build_absolute_uri().replace('http://', 'https://'))
            return view_func(request, *args, **kwargs)
        return _checkssl
    return wrapper

def anonymous_required(view, redirect_to=None):
    """Only allow if user is NOT authenticated."""
    if redirect_to is None:
        redirect_to = settings.LOGIN_REDIRECT_URL
    @wraps(view)
    def wrapper(request, *a, **k):
        if request.user and request.user.is_authenticated():
            return HttpResponseRedirect(redirect_to)
        return view(request, *a, **k)
    return wrapper

def render_form_field(parser, token):
    """Usage is {% render_form_field form.field_name optional_help_text optional_css_classes %}

    - optional_help_text and optional_css_classes are strings
    - if optional_help_text is not given, then it is taken from form field object"""
    try:
        help_text = None
        css_classes = None
        token_split = token.split_contents()
        if len(token_split) == 4:
            tag_name, form_field, help_text, css_classes = token.split_contents()
        elif len(token_split) == 3:
            tag_name, form_field, help_text = token.split_contents()
        else:
            tag_name, form_field = token.split_contents()
    except ValueError:
        raise template.TemplateSyntaxError('Unable to parse arguments for {0}'.format(repr(token.contents.split()[0])))
    return FormFieldNode(form_field, help_text=help_text, css_classes=css_classes)

def is_among(value, *possibilities):
    """Ensure that the method that has been used for the request is one
    of the expected ones (e.g., GET or POST)."""
    for possibility in possibilities:
        if value == possibility:
            return True
    raise Exception('A different request value was encountered than expected: {0}'.format(value))

def send_mail(subject, message, from_email, recipient_emails, files=None, html=False, reply_to=None, bcc=None, cc=None, files_manually=None):
    """Sends email with advanced optional parameters

    To attach non-file content (e.g. content not saved on disk), use
    files_manually parameter and provide list of 3 element tuples, e.g.
    [('design.png', img_data, 'image/png'),] which will be passed to
    email.attach()."""
    import django.core.mail
    try:
        logging.debug('Sending mail to: {0}'.format(', '.join((r for r in recipient_emails))))
        logging.debug('Message: {0}'.format(message))
        email = django.core.mail.EmailMessage(subject, message, from_email, recipient_emails, bcc, cc=cc)
        if html:
            email.content_subtype = 'html'
        if files:
            for file in files:
                email.attach_file(file)
        if files_manually:
            for filename, content, mimetype in files_manually:
                email.attach(filename, content, mimetype)
        if reply_to:
            email.extra_headers = {'Reply-To': reply_to}
        email.send()
    except Exception as e:
        logging.error('Error sending message [{0}] from {1} to {2} {3}'.format(subject, from_email, recipient_emails, e))

def humanize_time_since(timestamp=None):
    """Returns a fuzzy time since. Will only return the largest time. EX: 20 days, 14 min"""
    timeDiff = datetime.datetime.now() - timestamp
    days = timeDiff.days
    hours = timeDiff.seconds / 3600
    minutes = timeDiff.seconds % 3600 / 60
    seconds = timeDiff.seconds % 3600 % 60
    str = ''
    if days > 0:
        if days == 1:
            t_str = 'day'
        else:
            t_str = 'days'
        str += '{0} {1}'.format(days, t_str)
        return str
    elif hours > 0:
        if hours == 1:
            t_str = 'hour'
        else:
            t_str = 'hours'
        str += '{0} {1}'.format(hours, t_str)
        return str
    elif minutes > 0:
        if minutes == 1:
            t_str = 'min'
        else:
            t_str = 'mins'
        str += '{0} {1}'.format(minutes, t_str)
        return str
    elif seconds > 0:
        if seconds == 1:
            t_str = 'sec'
        else:
            t_str = 'secs'
        str += '{0} {1}'.format(seconds, t_str)
        return str
    else:
        return str

def skip_redundant(iterable, skipset=None):
    """Redundant items are repeated items or items in the original skipset."""
    if skipset is None:
        skipset = set()
    for item in iterable:
        if item not in skipset:
            skipset.add(item)
            yield item

def get_noconflict_metaclass(bases, left_metas, right_metas):
    """Not intended to be used outside of this module, unless you know what you are doing."""
    metas = left_metas + tuple(map(type, bases)) + right_metas
    needed_metas = remove_redundant(metas)
    if needed_metas in memoized_metaclasses_map:
        return memoized_metaclasses_map[needed_metas]
    elif not needed_metas:
        meta = type
    elif len(needed_metas) == 1:
        meta = needed_metas[0]
    elif needed_metas == bases:
        raise TypeError('Incompatible root metatypes', needed_metas)
    else:
        metaname = '_' + ''.join([m.__name__ for m in needed_metas])
        meta = classmaker()(metaname, needed_metas, {})
    memoized_metaclasses_map[needed_metas] = meta
    return meta

def covstr(strings):
    """convert string to int or float."""
    try:
        result = int(strings)
    except ValueError:
        result = float(strings)
    return result

def ensure_unicode_string(obj):
    """Return a unicode string representation of the given obj.

    :param obj:
        The obj we want to represent in unicode
    :type obj:
        varies
    :rtype:
        `unicode`"""
    try:
        return unicode_type(obj)
    except UnicodeDecodeError:
        if hasattr(obj, 'decode'):
            return obj.decode('utf-8', 'replace')
        return str(obj).decode('utf-8', 'replace')

def connection_ok():
    """Check web connection.
    Returns True if web connection is OK, False otherwise."""
    try:
        urlopen(Dataset.base_url, timeout=1)
        return True
    except HTTPError:
        return True
    except URLError:
        return False

def _download_datasets():
    """Utility to download datasets into package source"""
    def filepath(*args):
        return abspath(join(dirname(__file__), '..', 'vega_datasets', *args))
    dataset_listing = {}
    for name in DATASETS_TO_DOWNLOAD:
        data = Dataset(name)
        url = data.url
        filename = filepath('_data', data.filename)
        print('retrieving data {0} -> {1}'.format(url, filename))
        urlretrieve(url, filename)
        dataset_listing[name] = '_data/{0}'.format(data.filename)
    with open(filepath('local_datasets.json'), 'w') as f:
        json.dump(dataset_listing, f, indent=2, sort_keys=True)

def add_chromedriver_to_path():
    """Appends the directory of the chromedriver binary file to PATH."""
    chromedriver_dir = os.path.abspath(os.path.dirname(__file__))
    if 'PATH' not in os.environ:
