    """Function to fetch files using requests

    Works with https authentication"""
    import requests
    print('Retrieving: %s' % url)
    fn = os.path.split(url)[-1]
    if outdir is not None:
        fn = os.path.join(outdir, fn)
    if auth is not None:
        r = requests.get(url, stream=True, auth=auth)
