def parse_sentry_configuration(filename):
    """Parse Sentry DSN out of an application or Sentry configuration file"""
    filetype = os.path.splitext(filename)[-1][1:].lower()
    if filetype == 'ini':
        config = ConfigParser()
        config.read(filename)
        ini_key = 'dsn'
        ini_sections = ['sentry', 'filter:raven']
        for section in ini_sections:
            if section in config:
                print('- Using value from [{section}]:[{key}]'.format(section=section, key=ini_key))
                try:
                    return config[section][ini_key]
                except KeyError:
                    print('- Warning: Key "{key}" not found in section [{section}]'.format(section=section, key=ini_key))
        raise SystemExit('No DSN found in {file}. Tried sections [{sec_list}]'.format(file=filename, sec_list='], ['.join(ini_sections)))
    elif filetype == 'py':
        raise SystemExit('Parsing configuration from pure Python (Django,Flask, Bottle, etc.) not implemented yet.')
    else:
        raise SystemExit('Configuration file type not supported for parsing: %s' % filetype)

def create_daemon():
    """Detach a process from the controlling terminal and run it in the
    background as a daemon."""
    try:
        pid = os.fork()
    except OSError as err:
        raise Exception('%s [%d]' % (err.strerror, err.errno))
    if pid == 0:
        os.setsid()
        try:
            pid = os.fork()
        except OSError as err:
            raise Exception('%s [%d]' % (err.strerror, err.errno))
        if pid == 0:
            os.chdir(WORKDIR)
            os.umask(UMASK)
        else:
            _exit(0)
    else:
        _exit(0)
    import resource
    maxfd = resource.getrlimit(resource.RLIMIT_NOFILE)[1]
    if maxfd == resource.RLIM_INFINITY:
        maxfd = MAXFD
    for file_desc in range(0, maxfd):
        try:
            os.close(file_desc)
        except OSError:
            pass
    os.open(REDIRECT_TO, os.O_RDWR)
    os.dup2(0, 1)
    os.dup2(0, 2)
    return 0

def rmtree_glob(file_glob):
    """Platform independent rmtree, which also allows wildcards (globbing)"""
    for item in glob(file_glob, recursive=True):
        try:
            os.remove(item)
