    with open(configuration['configuration']) as config_file:
        domain_config = config_file.read()
    xml = domain_xml(identifier, domain_config, disk_path)
    return hypervisor.defineXML(xml)

def domain_delete(domain, logger):
    """libvirt domain undefinition.

    @raise: libvirt.libvirtError."""
    if domain is not None:
        try:
            if domain.isActive():
                domain.destroy()
        except libvirt.libvirtError:
            logger.exception('Unable to destroy the domain.')
        try:
            domain.undefine()
        except libvirt.libvirtError:
            try:
                domain.undefineFlags(libvirt.VIR_DOMAIN_UNDEFINE_SNAPSHOTS_METADATA)
            except libvirt.libvirtError:
                logger.exception('Unable to undefine the domain.')

def run_command(args, asynchronous=False):
    """Executes a command returning its exit code and output."""
    logging.info('Executing %s command %s.', asynchronous and 'asynchronous' or 'synchronous', args)
    process = subprocess.Popen(args, shell=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
    try:
        timeout = asynchronous and 1 or None
        output = process.communicate(timeout=timeout)[0].decode('utf8')
    except subprocess.TimeoutExpired:
        pass
    if asynchronous:
        return PopenOutput(None, 'Asynchronous call.')
    else:
        return PopenOutput(process.returncode, output)

def pool_lookup(hypervisor, disk_path):
    """Storage pool lookup.

    Retrieves the the virStoragepool which contains the disk at the given path."""
    try:
        volume = hypervisor.storageVolLookupByPath(disk_path)
        return volume.storagePoolLookupByVolume()
    except libvirt.libvirtError:
        return None

def pool_delete(storage_pool, logger):
    """Storage Pool deletion, removes all the created disk images within the pool and the pool itself."""
    path = etree.fromstring(storage_pool.XMLDesc(0)).find('.//path').text
    volumes_delete(storage_pool, logger)
    try:
        storage_pool.destroy()
    except libvirt.libvirtError:
        logger.exception('Unable to delete storage pool.')
    try:
        if os.path.exists(path):
            shutil.rmtree(path)
    except EnvironmentError:
        logger.exception('Unable to delete storage pool folder.')

def volumes_delete(storage_pool, logger):
    """Deletes all storage volume disks contained in the given storage pool."""
    try:
        for vol_name in storage_pool.listVolumes():
            try:
                vol = storage_pool.storageVolLookupByName(vol_name)
                vol.delete(0)
            except libvirt.libvirtError:
                logger.exception('Unable to delete storage volume %s.', vol_name)
    except libvirt.libvirtError:
        logger.exception('Unable to delete storage volumes.')

def load_configuration(configuration):
    """Returns a dictionary, accepts a dictionary or a path to a JSON file."""
    if isinstance(configuration, dict):
        return configuration
    else:
        with open(configuration) as configfile:
            return json.load(configfile)

def cleanup(logger, *args):
    """Environment's cleanup routine."""
    for obj in args:
        if obj is not None and hasattr(obj, 'cleanup'):
            try:
                obj.cleanup()
            except NotImplementedError:
                pass
            except Exception:
                logger.exception('Unable to cleanup %s object', obj)

def domain_xml(identifier, xml, mounts, network_name=None):
    """Fills the XML file with the required fields.

    @param identifier: (str) UUID of the Environment.
    @param xml: (str) XML configuration of the domain.
    @param filesystem: (tuple) ((source, target), (source, target))

     * name
     * uuid
     * devices
     * network
     * filesystem"""
    domain = etree.fromstring(xml)
    subelement(domain, './/name', 'name', identifier)
    subelement(domain, './/uuid', 'uuid', identifier)
    devices = subelement(domain, './/devices', 'devices', None)
    for mount in mounts:
        filesystem = etree.SubElement(devices, 'filesystem', type='mount')
        etree.SubElement(filesystem, 'source', dir=mount[0])
        etree.SubElement(filesystem, 'target', dir=mount[1])
    if network_name is not None:
        network = subelement(devices, './/interface[@type="network"]', 'interface', None, type='network')
        subelement(network, './/source', 'source', None, network=network_name)
    return etree.tostring(domain).decode('utf-8')

def domain_create(hypervisor, identifier, configuration, network_name=None):
    """libvirt Domain definition.

    @raise: ConfigError, IOError, libvirt.libvirtError."""
    mounts = []
    with open(configuration['configuration']) as config_file:
        domain_config = config_file.read()
    if 'filesystem' in configuration:
        if isinstance(configuration['filesystem'], (list, tuple)):
            for mount in configuration['filesystem']:
                mounts.append(mountpoint(mount, identifier))
        else:
            mounts.append(mountpoint(configuration['filesystem'], identifier))
    xml_config = domain_xml(identifier, domain_config, tuple(mounts), network_name=network_name)
    return hypervisor.defineXML(xml_config)

def domain_delete(domain, logger, filesystem):
    """libvirt domain undefinition.

    @raise: libvirt.libvirtError."""
    if domain is not None:
        try:
            if domain.isActive():
                domain.destroy()
        except libvirt.libvirtError:
            logger.exception('Unable to destroy the domain.')
        try:
            domain.undefine()
        except libvirt.libvirtError:
            logger.exception('Unable to undefine the domain.')
        try:
            if filesystem is not None and os.path.exists(filesystem):
                shutil.rmtree(filesystem)
        except Exception:
            logger.exception('Unable to remove the shared folder.')

def get_tracer(app: Application, tracer_key: str=APP_AIOZIPKIN_KEY) -> Tracer:
