def setval(key, val, dict_=None, delim=defaults.DEFAULT_DELIM):
    """Set a value under the dictionary hierarchy identified
    under the key. The target 'foo/bar/baz' returns the
    dictionary hierarchy {'foo': {'bar': {'baz': {}}}}.

    .. note::

        Currently this doesn't work with integers, i.e.
        cannot build lists dynamically.
        TODO"""
    if not dict_:
        dict_ = {}
    prev_hier = dict_
    dict_hier = key.split(delim)
    for each in dict_hier[:-1]:
        if isinstance(each, six.string_type):
            if each not in prev_hier:
                prev_hier[each] = {}
            prev_hier = prev_hier[each]
        else:
            prev_hier[each] = [{}]
            prev_hier = prev_hier[each]
    prev_hier[dict_hier[-1]] = val
    return dict_

def emit(msg_dict):
    """Extracts the details from the syslog message
    and returns an object having the following structure:

    .. code-block:: python

        {
            u'users': {
                u'user': {
                    u'luke': {
                        u'action': {
                            u'login': True
                        },
                        u'uid': 0
                    }
                }
            }
        }"""
    log.debug('Evaluating the message dict:')
    log.debug(msg_dict)
    ret = {}
    extracted = napalm_logs.utils.extract(_RGX, msg_dict['message'], _RGX_PARTS)
    if not extracted:
        return ret
    uid_key_path = 'users//user//{0[user]}//uid'.format(extracted)
    uid_value = int(extracted['uid'])
    log.debug('Setting %d under key path %s', uid_value, uid_key_path)
    ret.update(napalm_logs.utils.setval(uid_key_path, uid_value, dict_=ret))
    login_key_path = 'users//user//{0[user]}//action//login'.format(extracted)
    ret.update(napalm_logs.utils.setval(login_key_path, True, dict_=ret))
    return ret

def expr_match(line, expr):
    """Evaluate a line of text against an expression. First try a full-string
    match, next try globbing, and then try to match assuming expr is a regular
    expression. Originally designed to match minion IDs for
    whitelists/blacklists."""
    if line == expr:
        return True
    if fnmatch.fnmatch(line, expr):
        return True
    try:
        if re.match('\\A{0}\\Z'.format(expr), line):
            return True
    except re.error:
        pass
    return False

def _get_gdcmconv():
    """Get the full path to gdcmconv.
    If not found raise error"""
    gdcmconv_executable = settings.gdcmconv_path
    if gdcmconv_executable is None:
        gdcmconv_executable = _which('gdcmconv')
    if gdcmconv_executable is None:
        gdcmconv_executable = _which('gdcmconv.exe')
    if gdcmconv_executable is None:
        raise ConversionError('GDCMCONV_NOT_FOUND')
    return gdcmconv_executable

def compress_directory(dicom_directory):
    """This function can be used to convert a folder of jpeg compressed images to an uncompressed ones

    :param dicom_directory: directory of dicom files to compress"""
    if _is_compressed(dicom_directory):
        return
    logger.info('Compressing dicom files in %s' % dicom_directory)
    for root, _, files in os.walk(dicom_directory):
        for dicom_file in files:
            if is_dicom_file(os.path.join(root, dicom_file)):
                _compress_dicom(os.path.join(root, dicom_file))

def dicom_diff(file1, file2):
    """Shows the fields that differ between two DICOM images.

    Inspired by https://code.google.com/p/pydicom/source/browse/source/dicom/examples/DicomDiff.py"""
    datasets = (compressed_dicom.read_file(file1), compressed_dicom.read_file(file2))
    rep = []
    for dataset in datasets:
        lines = (str(dataset.file_meta) + '\n' + str(dataset)).split('\n')
        lines = [line + '\n' for line in lines]
        rep.append(lines)
    diff = difflib.Differ()
    for line in diff.compare(rep[0], rep[1]):
        if line[0] == '+' or line[0] == '-':
            sys.stdout.write(line)

def are_imaging_dicoms(dicom_input):
    """This function will check the dicom headers to see which type of series it is
    Possibilities are fMRI, DTI, Anatomical (if no clear type is found anatomical is used)

    :param dicom_input: directory with dicom files or a list of dicom objects"""
    if common.is_philips(dicom_input):
        if common.is_multiframe_dicom(dicom_input):
            return True
    header = dicom_input[0]
    return Tag(32, 55) in header

def _get_first_header(dicom_directory):
    """Function to get the first dicom file form a directory and return the header
    Useful to determine the type of data to convert

    :param dicom_directory: directory with dicom files"""
    for root, _, file_names in os.walk(dicom_directory):
        for file_name in file_names:
            file_path = os.path.join(root, file_name)
            if not compressed_dicom.is_dicom_file(file_path):
                continue
            return compressed_dicom.read_file(file_path, stop_before_pixels=True, force=dicom2nifti.settings.pydicom_read_force)
    raise ConversionError('NO_DICOM_FILES_FOUND')

def _reorient_3d(image):
    """Reorganize the data for a 3d nifti"""
    new_image = numpy.zeros([image.dimensions[image.sagittal_orientation.normal_component], image.dimensions[image.coronal_orientation.normal_component], image.dimensions[image.axial_orientation.normal_component]], dtype=image.nifti_data.dtype)
    if image.coronal_orientation.y_inverted:
        for i in range(new_image.shape[2]):
            new_image[:, :, i] = numpy.fliplr(numpy.squeeze(image.get_slice(SliceType.AXIAL, new_image.shape[2] - 1 - i).original_data))
    else:
        for i in range(new_image.shape[2]):
            new_image[:, :, i] = numpy.fliplr(numpy.squeeze(image.get_slice(SliceType.AXIAL, i).original_data))
    return new_image

def dicom_to_nifti(dicom_input, output_file=None):
    """This is the main dicom to nifti conversion fuction for philips images.
    As input philips images are required. It will then determine the type of images and do the correct conversion

    Examples: See unit test

    :param output_file: file path to the output nifti
    :param dicom_input: directory with dicom files for 1 scan"""
    assert common.is_philips(dicom_input)
    if common.is_multiframe_dicom(dicom_input):
        _assert_explicit_vr(dicom_input)
        logger.info('Found multiframe dicom')
        if _is_multiframe_4d(dicom_input):
            logger.info('Found sequence type: MULTIFRAME 4D')
            return _multiframe_to_nifti(dicom_input, output_file)
        if _is_multiframe_anatomical(dicom_input):
            logger.info('Found sequence type: MULTIFRAME ANATOMICAL')
            return _multiframe_to_nifti(dicom_input, output_file)
    else:
        logger.info('Found singleframe dicom')
        grouped_dicoms = _get_grouped_dicoms(dicom_input)
        if _is_singleframe_4d(dicom_input):
            logger.info('Found sequence type: SINGLEFRAME 4D')
            return _singleframe_to_nifti(grouped_dicoms, output_file)
    logger.info('Assuming anatomical data')
    return convert_generic.dicom_to_nifti(dicom_input, output_file)

def _assert_explicit_vr(dicom_input):
    """Assert that explicit vr is used"""
    if settings.validate_multiframe_implicit:
        header = dicom_input[0]
        if header.file_meta[2, 16].value == '1.2.840.10008.1.2':
            raise ConversionError('IMPLICIT_VR_ENHANCED_DICOM')

def _is_multiframe_diffusion_imaging(dicom_input):
    """Use this function to detect if a dicom series is a philips multiframe dti dataset
    NOTE: We already assue this is a 4D dataset as input"""
    header = dicom_input[0]
    if 'PerFrameFunctionalGroupsSequence' not in header:
        return False
    found_diffusion = False
    diffusion_tag = Tag(24, 37143)
    for frame in header.PerFrameFunctionalGroupsSequence:
        if diffusion_tag in frame:
            found_diffusion = True
            break
    if not found_diffusion:
        return False
    return True

def _is_multiframe_4d(dicom_input):
    """Use this function to detect if a dicom series is a philips multiframe 4D dataset"""
    if not common.is_multiframe_dicom(dicom_input):
        return False
    header = dicom_input[0]
    number_of_stack_slices = common.get_ss_value(header[Tag(8193, 4191)][0][Tag(8193, 4141)])
    number_of_stacks = int(int(header.NumberOfFrames) / number_of_stack_slices)
    if number_of_stacks <= 1:
        return False
    return True

def _is_singleframe_4d(dicom_input):
    """Use this function to detect if a dicom series is a philips singleframe 4D dataset"""
    header = dicom_input[0]
    slice_number_mr_tag = Tag(8193, 4106)
    if slice_number_mr_tag not in header:
        return False
    grouped_dicoms = _get_grouped_dicoms(dicom_input)
    if len(grouped_dicoms) <= 1:
        return False
    return True

def _is_bval_type_b(grouped_dicoms):
    """Check if the bvals are stored in the second of 2 currently known ways for single frame dti"""
    bval_tag = Tag(24, 36999)
    bvec_tag = Tag(24, 37001)
    for group in grouped_dicoms:
        if bvec_tag in group[0] and bval_tag in group[0]:
            bvec = common.get_fd_array_value(group[0][bvec_tag], 3)
            bval = common.get_fd_value(group[0][bval_tag])
            if _is_float(bvec[0]) and _is_float(bvec[1]) and _is_float(bvec[2]) and _is_float(bval) and (bval != 0):
                return True
    return False

def _get_grouped_dicoms(dicom_input):
    """Search all dicoms in the dicom directory, sort and validate them

    fast_read = True will only read the headers not the data"""
    if [d for d in dicom_input if 'InstanceNumber' in d]:
        dicoms = sorted(dicom_input, key=lambda x: x.InstanceNumber)
    else:
        dicoms = common.sort_dicoms(dicom_input)
    grouped_dicoms = [[]]
    timepoint_index = 0
    previous_stack_position = -1
    stack_position_tag = Tag(8193, 4106)
    for index in range(0, len(dicoms)):
        dicom_ = dicoms[index]
        stack_position = 0
        if stack_position_tag in dicom_:
            stack_position = common.get_is_value(dicom_[stack_position_tag])
        if previous_stack_position == stack_position:
            timepoint_index += 1
            if len(grouped_dicoms) <= timepoint_index:
                grouped_dicoms.append([])
        else:
            timepoint_index = 0
        grouped_dicoms[timepoint_index].append(dicom_)
        previous_stack_position = stack_position
    return grouped_dicoms

def _fix_diffusion_images(bvals, bvecs, nifti, nifti_file):
    """This function will remove the last timepoint from the nifti, bvals and bvecs if the last vector is 0,0,0
    This is sometimes added at the end by philips"""
    if numpy.count_nonzero(bvecs) == 0 or not numpy.count_nonzero(bvals[-1]) == 0:
        return (nifti, bvals, bvecs)
    bvals = bvals[:-1]
    bvecs = bvecs[:-1]
    new_nifti = nibabel.Nifti1Image(nifti.get_data()[:, :, :, :-1], nifti.affine)
    new_nifti.to_filename(nifti_file)
    return (new_nifti, bvals, bvecs)

def _remove_duplicate_slices(dicoms):
    """Search dicoms for localizers and delete them"""
    dicoms_dict = {}
    filtered_dicoms = []
    for dicom_ in dicoms:
        if tuple(dicom_.ImagePositionPatient) not in dicoms_dict:
            dicoms_dict[tuple(dicom_.ImagePositionPatient)] = dicom_
            filtered_dicoms.append(dicom_)
        elif numpy.array_equal(dicom_.pixel_array, dicoms_dict[tuple(dicom_.ImagePositionPatient)].pixel_array):
            logger.warning('Removing duplicate slice from series')
        else:
            filtered_dicoms.append(dicom_)
    return filtered_dicoms

def _remove_localizers_by_imagetype(dicoms):
    """Search dicoms for localizers and delete them"""
    filtered_dicoms = []
    for dicom_ in dicoms:
        if 'ImageType' in dicom_ and 'LOCALIZER' in dicom_.ImageType:
            continue
        if 'CT' in dicom_.Modality and 'ImageType' in dicom_ and ('PROJECTION IMAGE' in dicom_.ImageType):
            continue
        filtered_dicoms.append(dicom_)
    return filtered_dicoms

def read_dicom_directory(dicom_directory, stop_before_pixels=False):
    """Read all dicom files in a given directory (stop before pixels)

    :type stop_before_pixels: bool
    :type dicom_directory: six.string_types
    :param stop_before_pixels: Should we stop reading before the pixeldata (handy if we only want header info)
    :param dicom_directory: Directory with dicom data
    :return: List of dicom objects"""
    dicom_input = []
    for root, _, files in os.walk(dicom_directory):
        for dicom_file in files:
            file_path = os.path.join(root, dicom_file)
            if compressed_dicom.is_dicom_file(file_path):
                dicom_headers = compressed_dicom.read_file(file_path, defer_size='1 KB', stop_before_pixels=stop_before_pixels, force=dicom2nifti.settings.pydicom_read_force)
                if is_valid_imaging_dicom(dicom_headers):
                    dicom_input.append(dicom_headers)
    return dicom_input

def is_hitachi(dicom_input):
    """Use this function to detect if a dicom series is a hitachi dataset

    :param dicom_input: directory with dicom files for 1 scan of a dicom_header"""
    header = dicom_input[0]
    if 'Manufacturer' not in header or 'Modality' not in header:
        return False
    if header.Modality.upper() != 'MR':
        return False
    if 'HITACHI' not in header.Manufacturer.upper():
        return False
    return True

def is_ge(dicom_input):
    """Use this function to detect if a dicom series is a GE dataset

    :param dicom_input: list with dicom objects"""
    header = dicom_input[0]
    if 'Manufacturer' not in header or 'Modality' not in header:
        return False
    if header.Modality.upper() != 'MR':
        return False
    if 'GE MEDICAL SYSTEMS' not in header.Manufacturer.upper():
        return False
    return True

def is_philips(dicom_input):
    """Use this function to detect if a dicom series is a philips dataset

    :param dicom_input: directory with dicom files for 1 scan of a dicom_header"""
    header = dicom_input[0]
    if 'Manufacturer' not in header or 'Modality' not in header:
        return False
    if header.Modality.upper() != 'MR':
        return False
    if 'PHILIPS' not in header.Manufacturer.upper():
        return False
    return True

def is_siemens(dicom_input):
    """Use this function to detect if a dicom series is a siemens dataset

    :param dicom_input: directory with dicom files for 1 scan"""
    header = dicom_input[0]
    if 'Manufacturer' not in header or 'Modality' not in header:
        return False
    if header.Modality.upper() != 'MR':
        return False
    if 'SIEMENS' not in header.Manufacturer.upper():
        return False
    return True

def is_valid_imaging_dicom(dicom_header):
    """Function will do some basic checks to see if this is a valid imaging dicom"""
    try:
        if is_philips([dicom_header]):
            if is_multiframe_dicom([dicom_header]):
                return True
        if 'SeriesInstanceUID' not in dicom_header:
            return False
        if 'InstanceNumber' not in dicom_header:
            return False
        if 'ImageOrientationPatient' not in dicom_header or len(dicom_header.ImageOrientationPatient) < 6:
            return False
        if 'ImagePositionPatient' not in dicom_header or len(dicom_header.ImagePositionPatient) < 3:
            return False
        if Tag(32, 55) not in dicom_header:
            return False
        return True
    except (KeyError, AttributeError):
        return False

def get_numpy_type(dicom_header):
    """Make NumPy format code, e.g. "uint16", "int32" etc
    from two pieces of info:
    mosaic.PixelRepresentation -- 0 for unsigned, 1 for signed;
    mosaic.BitsAllocated -- 8, 16, or 32

    :param dicom_header: the read dicom file/headers
    :returns: numpy format string"""
    format_string = '%sint%d' % (('u', '')[dicom_header.PixelRepresentation], dicom_header.BitsAllocated)
    try:
        numpy.dtype(format_string)
    except TypeError:
        raise TypeError("Data type not understood by NumPy: format='%s', PixelRepresentation=%d, BitsAllocated=%d" % (format_string, dicom_header.PixelRepresentation, dicom_header.BitsAllocated))
    return format_string

def get_fd_array_value(tag, count):
    """Getters for data that also work with implicit transfersyntax

    :param count: number of items in the array
    :param tag: the tag to read"""
    if tag.VR == 'OB' or tag.VR == 'UN':
        values = []
        for i in range(count):
            start = i * 8
            stop = (i + 1) * 8
            values.append(struct.unpack('d', tag.value[start:stop])[0])
        return numpy.array(values)
    return tag.value

def get_is_value(tag):
    """Getters for data that also work with implicit transfersyntax

    :param tag: the tag to read"""
    if tag.VR == 'OB' or tag.VR == 'UN':
        value = int(tag.value.decode('ascii').replace(' ', ''))
        return value
    return int(tag.value)

def apply_scaling(data, dicom_headers):
    """Rescale the data based on the RescaleSlope and RescaleOffset
    Based on the scaling from pydicomseries

    :param dicom_headers: dicom headers to use to retreive the scaling factors
    :param data: the input data"""
    private_scale_slope_tag = Tag(8197, 4110)
    private_scale_intercept_tag = Tag(8197, 4109)
    if 'RescaleSlope' in dicom_headers or 'RescaleIntercept' in dicom_headers or private_scale_slope_tag in dicom_headers or (private_scale_intercept_tag in dicom_headers):
        rescale_slope = 1
        rescale_intercept = 0
        if 'RescaleSlope' in dicom_headers:
            rescale_slope = dicom_headers.RescaleSlope
        if 'RescaleIntercept' in dicom_headers:
            rescale_intercept = dicom_headers.RescaleIntercept
        return do_scaling(data, rescale_slope, rescale_intercept)
    else:
        return data

def _is_diffusion_imaging(grouped_dicoms):
    """Use this function to detect if a dicom series is a ge dti dataset
    NOTE: We already assume this is a 4D dataset"""
    bval_tag = Tag(67, 4153)
    found_bval = False
    for header in list(itertools.chain.from_iterable(grouped_dicoms)):
        if bval_tag in header and int(header[bval_tag].value[0]) != 0:
            found_bval = True
            break
    if not found_bval:
        return False
    return True

def _get_bvals_bvecs(grouped_dicoms):
    """Write the bvals from the sorted dicom files to a bval file"""
    bvals = numpy.zeros([len(grouped_dicoms)], dtype=numpy.int32)
    bvecs = numpy.zeros([len(grouped_dicoms), 3])
    for group_index in range(0, len(grouped_dicoms)):
        dicom_ = grouped_dicoms[group_index][0]
        if isinstance(dicom_[Tag(67, 4153)].value, string_types):
            original_bval = float(dicom_[Tag(67, 4153)].value.split('\\')[0])
        elif isinstance(dicom_[Tag(67, 4153)].value, bytes):
            original_bval = float(dicom_[Tag(67, 4153)].value.decode('utf-8').split('\\')[0])
        else:
            original_bval = dicom_[Tag(67, 4153)][0]
        original_bvec = numpy.array([0, 0, 0], dtype=numpy.float)
        original_bvec[0] = -float(dicom_[Tag(25, 4283)].value)
        original_bvec[1] = float(dicom_[Tag(25, 4284)].value)
        original_bvec[2] = float(dicom_[Tag(25, 4285)].value)
        if original_bval != 0:
            corrected_bval = original_bval * pow(numpy.linalg.norm(original_bvec), 2)
            if numpy.linalg.norm(original_bvec) != 0:
                normalized_bvec = original_bvec / numpy.linalg.norm(original_bvec)
            else:
                normalized_bvec = original_bvec
        else:
            corrected_bval = original_bval
            normalized_bvec = original_bvec
        bvals[group_index] = int(round(corrected_bval))
        bvecs[group_index, :] = normalized_bvec
    return (bvals, bvecs)

def _create_bvals_bvecs(grouped_dicoms, bval_file, bvec_file):
    """Write the bvals from the sorted dicom files to a bval file"""
    bvals, bvecs = _get_bvals_bvecs(grouped_dicoms)
    common.write_bval_file(bvals, bval_file)
    common.write_bvec_file(bvecs, bvec_file)
    return (bvals, bvecs)

def dicom_to_nifti(dicom_input, output_file=None):
    """This is the main dicom to nifti conversion function for ge images.
    As input ge images are required. It will then determine the type of images and do the correct conversion

    :param output_file: filepath to the output nifti
    :param dicom_input: directory with dicom files for 1 scan"""
    assert common.is_siemens(dicom_input)
    if _is_4d(dicom_input):
        logger.info('Found sequence type: MOSAIC 4D')
        return _mosaic_4d_to_nifti(dicom_input, output_file)
    grouped_dicoms = _classic_get_grouped_dicoms(dicom_input)
    if _is_classic_4d(grouped_dicoms):
        logger.info('Found sequence type: CLASSIC 4D')
        return _classic_4d_to_nifti(grouped_dicoms, output_file)
    logger.info('Assuming anatomical data')
    return convert_generic.dicom_to_nifti(dicom_input, output_file)

def _is_mosaic(dicom_input):
    """Use this function to detect if a dicom series is a siemens 4d dataset
    NOTE: Only the first slice will be checked so you can only provide an already sorted dicom directory
    (containing one series)"""
    if type(dicom_input) is list and type(dicom_input[0]) is list:
        header = dicom_input[0][0]
    else:
        header = dicom_input[0]
    if 'ImageType' not in header or 'MOSAIC' not in header.ImageType:
        return False
    if 'AcquisitionMatrix' not in header or header.AcquisitionMatrix is None:
        return False
    return True

def _classic_get_grouped_dicoms(dicom_input):
    """Search all dicoms in the dicom directory, sort and validate them

    fast_read = True will only read the headers not the data"""
    if [d for d in dicom_input if 'InstanceNumber' in d]:
        dicoms = sorted(dicom_input, key=lambda x: x.InstanceNumber)
    else:
        dicoms = common.sort_dicoms(dicom_input)
    grouped_dicoms = []
    stack_position_tag = Tag(32, 18)
    for index in range(0, len(dicoms)):
        dicom_ = dicoms[index]
        if stack_position_tag not in dicom_:
            stack_index = 0
        else:
            stack_index = dicom_[stack_position_tag].value - 1
        while len(grouped_dicoms) <= stack_index:
            grouped_dicoms.append([])
        grouped_dicoms[stack_index].append(dicom_)
    return grouped_dicoms

def _get_sorted_mosaics(dicom_input):
    """Search all mosaics in the dicom directory, sort and validate them"""
    sorted_mosaics = sorted(dicom_input, key=lambda x: x.AcquisitionNumber)
    for index in range(0, len(sorted_mosaics) - 1):
        if sorted_mosaics[index].AcquisitionNumber >= sorted_mosaics[index + 1].AcquisitionNumber:
            raise ConversionValidationError('INCONSISTENT_ACQUISITION_NUMBERS')
    return sorted_mosaics

def _create_bvals(sorted_dicoms, bval_file):
    """Write the bvals from the sorted dicom files to a bval file"""
    bvals = []
    for index in range(0, len(sorted_dicoms)):
        if type(sorted_dicoms[0]) is list:
            dicom_headers = sorted_dicoms[index][0]
        else:
            dicom_headers = sorted_dicoms[index]
        bvals.append(common.get_is_value(dicom_headers[Tag(25, 4108)]))
    common.write_bval_file(bvals, bval_file)
    return numpy.array(bvals)

def _is_valid_imaging_dicom(dicom_header):
    """Function will do some basic checks to see if this is a valid imaging dicom"""
    try:
        if common.is_philips([dicom_header]):
            if common.is_multiframe_dicom([dicom_header]):
                return True
        if 'SeriesInstanceUID' not in dicom_header:
            return False
        if 'InstanceNumber' not in dicom_header:
            return False
        if 'ImageOrientationPatient' not in dicom_header or len(dicom_header.ImageOrientationPatient) < 6:
            return False
        if 'ImagePositionPatient' not in dicom_header or len(dicom_header.ImagePositionPatient) < 3:
            return False
        if Tag(32, 55) not in dicom_header:
            return False
        return True
    except (KeyError, AttributeError):
        return False

def _remove_accents(filename):
    """Function that will try to remove accents from a unicode string to be used in a filename.
    input filename should be either an ascii or unicode string"""
    try:
        filename = filename.replace(' ', '_')
        if isinstance(filename, type(six.u(''))):
            unicode_filename = filename
        else:
            unicode_filename = six.u(filename)
        cleaned_filename = unicodedata.normalize('NFKD', unicode_filename).encode('ASCII', 'ignore').decode('ASCII')
        cleaned_filename = re.sub('[^\\w\\s-]', '', cleaned_filename.strip().lower())
        cleaned_filename = re.sub('[-\\s]+', '-', cleaned_filename)
        return cleaned_filename
    except:
        traceback.print_exc()
        return filename

def _remove_accents_(filename):
    """Function that will try to remove accents from a unicode string to be used in a filename.
    input filename should be either an ascii or unicode string"""
    if isinstance(filename, type(six.u(''))):
        unicode_filename = filename
    else:
        unicode_filename = six.u(filename)
    valid_characters = bytes(b'-_.() 1234567890abcdefghijklmnopqrstuvwxyz')
    cleaned_filename = unicodedata.normalize('NFKD', unicode_filename).encode('ASCII', 'ignore')
    new_filename = six.u('')
    for char_int in bytes(cleaned_filename):
        char_byte = bytes([char_int])
        if char_byte in valid_characters:
            new_filename += char_byte.decode()
    return new_filename

def check_conf_percentage_validity(conf_percentage):
    """Ensures that `conf_percentage` is in (0, 100). Raises a helpful ValueError
    if otherwise."""
    msg = 'conf_percentage MUST be a number between 0.0 and 100.'
    condition_1 = isinstance(conf_percentage, Number)
    if not condition_1:
        raise ValueError(msg)
    else:
        condition_2 = 0 < conf_percentage < 100
        if not condition_2:
            raise ValueError(msg)
    return None

def check_type_and_size_of_param_list(param_list, expected_length):
    """Ensure that param_list is a list with the expected length. Raises a helpful
    ValueError if this is not the case."""
    try:
        assert isinstance(param_list, list)
        assert len(param_list) == expected_length
    except AssertionError:
        msg = 'param_list must be a list containing {} elements.'
        raise ValueError(msg.format(expected_length))
    return None

def substitute_symbol_table(table, version, max_id):
    """Substitutes a given shared symbol table for another version.

    * If the given table has **more** symbols than the requested substitute, then the generated
      symbol table will be a subset of the given table.
    * If the given table has **less** symbols than the requested substitute, then the generated
      symbol table will have symbols with unknown text generated for the difference.

    Args:
        table (SymbolTable): The shared table to derive from.
        version (int): The version to target.
        max_id (int): The maximum ID allocated by the substitute, must be ``>= 0``.

    Returns:
        SymbolTable: The synthesized table."""
    if not table.table_type.is_shared:
        raise ValueError('Symbol table to substitute from must be a shared table')
    if version <= 0:
        raise ValueError('Version must be grater than or equal to 1: %s' % version)
    if max_id < 0:
        raise ValueError('Max ID must be zero or positive: %s' % max_id)
    if max_id <= table.max_id:
        symbols = (token.text for token in islice(table, max_id))
    else:
        symbols = chain((token.text for token in table), repeat(None, max_id - table.max_id))
    return SymbolTable(table_type=SHARED_TABLE_TYPE, symbols=symbols, name=table.name, version=version, is_substitute=True)

def _timestamps_eq(a, b):
    """Compares two timestamp operands for equivalence under the Ion data model."""
    assert isinstance(a, datetime)
    if not isinstance(b, datetime):
        return False
    if (a.tzinfo is None) ^ (b.tzinfo is None):
        return False
    if a.utcoffset() != b.utcoffset():
        return False
    for a, b in ((a, b), (b, a)):
        if isinstance(a, Timestamp):
            if isinstance(b, Timestamp):
                if a.precision is b.precision and a.fractional_precision is b.fractional_precision:
                    break
                return False
            elif a.precision is not TimestampPrecision.SECOND or a.fractional_precision != MICROSECOND_PRECISION:
                return False
    return a == b

def _timestamp_instants_eq(a, b):
    """Compares two timestamp operands for point-in-time equivalence only."""
    assert isinstance(a, datetime)
    if not isinstance(b, datetime):
        return False
    if a.tzinfo is None:
        a = a.replace(tzinfo=OffsetTZInfo())
    if b.tzinfo is None:
        b = b.replace(tzinfo=OffsetTZInfo())
    return a == b

def _parse_var_int_components(buf, signed):
    """Parses a ``VarInt`` or ``VarUInt`` field from a file-like object."""
    value = 0
    sign = 1
    while True:
        ch = buf.read(1)
        if ch == '':
            raise IonException('Variable integer under-run')
        octet = ord(ch)
        if signed:
            if octet & _VAR_INT_SIGN_MASK:
                sign = -1
            value = octet & _VAR_INT_SIGN_VALUE_MASK
            signed = False
        else:
            value <<= _VAR_INT_VALUE_BITS
            value |= octet & _VAR_INT_VALUE_MASK
        if octet & _VAR_INT_SIGNAL_MASK:
            break
    return (sign, value)

def _parse_signed_int_components(buf):
    """Parses the remainder of a file-like object as a signed magnitude value.

    Returns:
        Returns a pair of the sign bit and the unsigned magnitude."""
    sign_bit = 0
    value = 0
    first = True
    while True:
        ch = buf.read(1)
        if ch == b'':
            break
        octet = ord(ch)
        if first:
            if octet & _SIGNED_INT_SIGN_MASK:
                sign_bit = 1
            value = octet & _SIGNED_INT_SIGN_VALUE_MASK
            first = False
        else:
            value <<= 8
            value |= octet
    return (sign_bit, value)

def _parse_decimal(buf):
    """Parses the remainder of a file-like object as a decimal."""
    exponent = _parse_var_int(buf, signed=True)
    sign_bit, coefficient = _parse_signed_int_components(buf)
    if coefficient == 0:
        value = Decimal((sign_bit, (0,), exponent))
    else:
        coefficient *= sign_bit and -1 or 1
        value = Decimal(coefficient).scaleb(exponent)
    return value

def _length_scalar_handler(scalar_factory, ion_type, length, ctx):
    """Handles scalars, ``scalar_factory`` is a function that returns a value or thunk."""
    _, self = (yield)
    if length == 0:
        data = b''
    else:
        yield ctx.read_data_transition(length, self)
        data = ctx.queue.read(length)
    scalar = scalar_factory(data)
    event_cls = IonEvent
    if callable(scalar):
        event_cls = IonThunkEvent
    yield ctx.event_transition(event_cls, IonEventType.SCALAR, ion_type, scalar)

def _bind_length_handlers(tids, user_handler, lns):
    """Binds a set of handlers with the given factory.

    Args:
        tids (Sequence[int]): The Type IDs to bind to.
        user_handler (Callable): A function that takes as its parameters
            :class:`IonType`, ``length``, and the ``ctx`` context
            returning a co-routine.
        lns (Sequence[int]): The low-nibble lengths to bind to."""
    for tid in tids:
        for ln in lns:
            type_octet = _gen_type_octet(tid, ln)
            ion_type = _TID_VALUE_TYPE_TABLE[tid]
            if ln == 1 and ion_type is IonType.STRUCT:
                handler = partial(_ordered_struct_start_handler, partial(user_handler, ion_type))
            elif ln < _LENGTH_FIELD_FOLLOWS:
                handler = partial(user_handler, ion_type, ln)
            else:
                handler = partial(_var_uint_field_handler, partial(user_handler, ion_type))
            _HANDLER_DISPATCH_TABLE[type_octet] = handler

def _narrow_unichr(code_point):
    """Retrieves the unicode character representing any given code point, in a way that won't break on narrow builds.

    This is necessary because the built-in unichr function will fail for ordinals above 0xFFFF on narrow builds (UCS2);
    ordinals above 0xFFFF would require recalculating and combining surrogate pairs. This avoids that by retrieving the
    unicode character that was initially read.

    Args:
        code_point (int|CodePoint): An int or a subclass of int that contains the unicode character representing its
            code point in an attribute named 'char'."""
    try:
        if len(code_point.char) > 1:
            return code_point.char
    except AttributeError:
        pass
    return six.unichr(code_point)

def blocking_reader(reader, input, buffer_size=_DEFAULT_BUFFER_SIZE):
    """Provides an implementation of using the reader co-routine with a file-like object.

    Args:
        reader(Coroutine): A reader co-routine.
        input(BaseIO): The file-like object to read from.
        buffer_size(Optional[int]): The optional buffer size to use."""
    ion_event = None
    while True:
        read_event = (yield ion_event)
        ion_event = reader.send(read_event)
        while ion_event is not None and ion_event.event_type.is_stream_signal:
            data = input.read(buffer_size)
            if len(data) == 0:
                if ion_event.event_type is IonEventType.INCOMPLETE:
                    ion_event = reader.send(NEXT_EVENT)
                    continue
                else:
                    yield ION_STREAM_END_EVENT
                    return
            ion_event = reader.send(read_data_event(data))

def _merge_mappings(*args):
    """Merges a sequence of dictionaries and/or tuples into a single dictionary.

    If a given argument is a tuple, it must have two elements, the first of which is a sequence of keys and the second
    of which is a single value, which will be mapped to from each of the keys in the sequence."""
    dct = {}
    for arg in args:
        if isinstance(arg, dict):
            merge = arg
        else:
            assert isinstance(arg, tuple)
            keys, value = arg
            merge = dict(zip(keys, [value] * len(keys)))
        dct.update(merge)
    return dct

def _as_symbol(value, is_symbol_value=True):
    """Converts the input to a :class:`SymbolToken` suitable for being emitted as part of a :class:`IonEvent`.

    If the input has an `as_symbol` method (e.g. :class:`CodePointArray`), it will be converted using that method.
    Otherwise, it must already be a `SymbolToken`. In this case, there is nothing to do unless the input token is not a
    symbol value and it is an :class:`_IVMToken`. This requires the `_IVMToken` to be converted to a regular
    `SymbolToken`."""
    try:
        return value.as_symbol()
    except AttributeError:
        assert isinstance(value, SymbolToken)
    if not is_symbol_value:
        try:
            return value.regular_token()
        except AttributeError:
            pass
    return value

def _number_or_timestamp_handler(c, ctx):
    """Handles numeric values that start with digits 1-9. May terminate a value, in which case that value is an
    int. If it does not terminate a value, it branches to delegate co-routines according to _NUMBER_OR_TIMESTAMP_TABLE."""
    assert c in _DIGITS
    ctx.set_ion_type(IonType.INT)
    val = ctx.value
    val.append(c)
    c, self = (yield)
    trans = ctx.immediate_transition(self)
    while True:
        if _ends_value(c):
            trans = ctx.event_transition(IonThunkEvent, IonEventType.SCALAR, ctx.ion_type, _parse_decimal_int(ctx.value))
            if c == _SLASH:
                trans = ctx.immediate_transition(_number_slash_end_handler(c, ctx, trans))
        elif c not in _DIGITS:
            trans = ctx.immediate_transition(_NUMBER_OR_TIMESTAMP_TABLE[c](c, ctx))
        else:
            val.append(c)
        c, _ = (yield trans)

def _radix_int_handler_factory(radix_indicators, charset, parse_func):
    """Generates a handler co-routine which tokenizes a integer of a particular radix.

    Args:
        radix_indicators (sequence): The set of ordinals of characters that indicate the radix of this int.
        charset (sequence): Set of ordinals of legal characters for this radix.
        parse_func (callable): Called upon ending the numeric value. Accepts the current token value and returns a
            thunk that lazily parses the token."""
    def assertion(c, ctx):
        return c in radix_indicators and (len(ctx.value) == 1 and ctx.value[0] == _ZERO or (len(ctx.value) == 2 and ctx.value[0] == _MINUS and (ctx.value[1] == _ZERO))) and (ctx.ion_type == IonType.INT)
    return _numeric_handler_factory(charset, lambda prev, c, ctx, trans: _illegal_character(c, ctx), assertion, radix_indicators, parse_func, illegal_at_end=radix_indicators)

def _timestamp_zero_start_handler(c, ctx):
    """Handles numeric values that start with a zero followed by another digit. This is either a timestamp or an
    error."""
    val = ctx.value
    ctx.set_ion_type(IonType.TIMESTAMP)
    if val[0] == _MINUS:
        _illegal_character(c, ctx, 'Negative year not allowed.')
    val.append(c)
    c, self = (yield)
    trans = ctx.immediate_transition(self)
    while True:
        if c in _TIMESTAMP_YEAR_DELIMITERS:
            trans = ctx.immediate_transition(_timestamp_handler(c, ctx))
        elif c in _DIGITS:
            val.append(c)
        else:
            _illegal_character(c, ctx)
        c, _ = (yield trans)

def _comment_handler(c, ctx, whence):
    """Handles comments. Upon completion of the comment, immediately transitions back to `whence`."""
    assert c == _SLASH
    c, self = (yield)
    if c == _SLASH:
        ctx.set_line_comment()
        block_comment = False
    elif c == _ASTERISK:
        if ctx.line_comment:
            ctx.set_line_comment(False)
        block_comment = True
    else:
        _illegal_character(c, ctx, 'Illegal character sequence "/%s".' % (_chr(c),))
    done = False
    prev = None
    trans = ctx.immediate_transition(self)
    while not done:
        c, _ = (yield trans)
        if block_comment:
            if prev == _ASTERISK and c == _SLASH:
                done = True
            prev = c
        elif c in _NEWLINES or BufferQueue.is_eof(c):
            done = True
    yield ctx.set_self_delimiting(True).immediate_transition(whence)

def _sexp_slash_handler(c, ctx, whence=None, pending_event=None):
    """Handles the special case of a forward-slash within an s-expression. This is either an operator or a
    comment."""
    assert c == _SLASH
    if whence is None:
        whence = ctx.whence
    c, self = (yield)
    ctx.queue.unread(c)
    if c == _ASTERISK or c == _SLASH:
        yield ctx.immediate_transition(_comment_handler(_SLASH, ctx, whence))
    else:
        if pending_event is not None:
            assert pending_event.event is not None
            yield _CompositeTransition(pending_event, ctx, partial(_operator_symbol_handler, _SLASH))
        yield ctx.immediate_transition(_operator_symbol_handler(_SLASH, ctx))

def _typed_null_handler(c, ctx):
    """Handles typed null values. Entered once `null.` has been found."""
    assert c == _DOT
    c, self = (yield)
    nxt = _NULL_STARTS
    i = 0
    length = None
    done = False
    trans = ctx.immediate_transition(self)
    while True:
        if done:
            if _ends_value(c) or (ctx.container.ion_type is IonType.SEXP and c in _OPERATORS):
                trans = ctx.event_transition(IonEvent, IonEventType.SCALAR, nxt.ion_type, None)
            else:
                _illegal_character(c, ctx, 'Illegal null type.')
        elif length is None:
            if c not in nxt:
                _illegal_character(c, ctx, 'Illegal null type.')
            nxt = nxt[c]
            if isinstance(nxt, _NullSequence):
                length = len(nxt.sequence)
        else:
            if c != nxt[i]:
                _illegal_character(c, ctx, 'Illegal null type.')
            i += 1
            done = i == length
        c, _ = (yield trans)

def _symbol_token_end(c, ctx, is_field_name, value=None):
    """Returns a transition which ends the current symbol token."""
    if value is None:
        value = ctx.value
    if is_field_name or c in _SYMBOL_TOKEN_TERMINATORS or ctx.quoted_text:
        ctx.set_self_delimiting(ctx.quoted_text).set_pending_symbol(value).set_quoted_text(False)
        trans = ctx.immediate_transition(ctx.whence)
    else:
        trans = ctx.event_transition(IonEvent, IonEventType.SCALAR, IonType.SYMBOL, _as_symbol(value))
    return trans

def _short_string_handler_factory():
    """Generates the short string (double quoted) handler."""
    def before(c, ctx, is_field_name, is_clob):
        assert not (is_clob and is_field_name)
        is_string = not is_clob and (not is_field_name)
        if is_string:
            ctx.set_ion_type(IonType.STRING)
        val = ctx.value
        if is_field_name:
            assert not val
            ctx.set_pending_symbol()
            val = ctx.pending_symbol
        return (val, is_string)
    def on_close(ctx):
        ctx.set_self_delimiting(True)
        return ctx.event_transition(IonEvent, IonEventType.SCALAR, ctx.ion_type, ctx.value.as_text())
    def after(c, ctx, is_field_name):
        ctx.set_quoted_text(False).set_self_delimiting(True)
        return ctx.immediate_transition(ctx.whence if is_field_name else _clob_end_handler(c, ctx))
    return _quoted_text_handler_factory(_DOUBLE_QUOTE, lambda c: c == _DOUBLE_QUOTE, before, after, append_first=False, on_close=on_close)

def _quoted_symbol_handler_factory():
    """Generates the quoted symbol (single quoted) handler."""
    def before(c, ctx, is_field_name, is_clob):
        assert not is_clob
        _validate_short_quoted_text(c, ctx, _MAX_TEXT_CHAR)
        return (ctx.value, False)
    return _quoted_text_handler_factory(_SINGLE_QUOTE, lambda c: c != _SINGLE_QUOTE or _is_escaped(c), before, _symbol_token_end)

def _lob_start_handler(c, ctx):
    """Handles tokens that begin with two open braces."""
    assert c == _OPEN_BRACE
    c, self = (yield)
    trans = ctx.immediate_transition(self)
    quotes = 0
    while True:
        if c in _WHITESPACE:
            if quotes > 0:
                _illegal_character(c, ctx)
        elif c == _DOUBLE_QUOTE:
            if quotes > 0:
                _illegal_character(c, ctx)
            ctx.set_ion_type(IonType.CLOB).set_unicode(quoted_text=True)
            yield ctx.immediate_transition(_short_string_handler(c, ctx))
        elif c == _SINGLE_QUOTE:
            if not quotes:
                ctx.set_ion_type(IonType.CLOB).set_unicode(quoted_text=True)
            quotes += 1
            if quotes == 3:
                yield ctx.immediate_transition(_long_string_handler(c, ctx))
        else:
            yield ctx.immediate_transition(_blob_end_handler(c, ctx))
        c, _ = (yield trans)

def _blob_end_handler_factory():
    """Generates the handler for the end of a blob value. This includes the base-64 data and the two closing braces."""
    def expand_res(res):
        if res is None:
            return (0, 0)
        return res
    def action(c, ctx, prev, res, is_first):
        num_digits, num_pads = expand_res(res)
        if c in _BASE64_DIGITS:
            if prev == _CLOSE_BRACE or prev == _BASE64_PAD:
                _illegal_character(c, ctx.set_ion_type(IonType.BLOB))
            num_digits += 1
        elif c == _BASE64_PAD:
            if prev == _CLOSE_BRACE:
                _illegal_character(c, ctx.set_ion_type(IonType.BLOB))
            num_pads += 1
        else:
            _illegal_character(c, ctx.set_ion_type(IonType.BLOB))
        ctx.value.append(c)
        return (num_digits, num_pads)
    def validate(c, ctx, res):
        num_digits, num_pads = expand_res(res)
        if num_pads > 3 or (num_digits + num_pads) % 4 != 0:
            _illegal_character(c, ctx, 'Incorrect number of pad characters (%d) for a blob of %d base-64 digits.' % (num_pads, num_digits))
    return _lob_end_handler_factory(IonType.BLOB, action, validate)

def _clob_end_handler_factory():
    """Generates the handler for the end of a clob value. This includes anything from the data's closing quote through
    the second closing brace."""
    def action(c, ctx, prev, res, is_first):
        if is_first and ctx.is_self_delimiting and (c == _DOUBLE_QUOTE):
            assert c is prev
            return res
        _illegal_character(c, ctx)
    return _lob_end_handler_factory(IonType.CLOB, action)

def _skip_trampoline(handler):
    """Intercepts events from container handlers, emitting them only if they should not be skipped."""
    data_event, self = (yield None)
    delegate = handler
    event = None
    depth = 0
    while True:
        def pass_through():
            _trans = delegate.send(Transition(data_event, delegate))
            return (_trans, _trans.delegate, _trans.event)
        if data_event is not None and data_event.type is ReadEventType.SKIP:
            while True:
                trans, delegate, event = pass_through()
                if event is not None:
                    if event.event_type is IonEventType.CONTAINER_END and event.depth <= depth:
                        break
                if event is None or event.event_type is IonEventType.INCOMPLETE:
                    data_event, _ = (yield Transition(event, self))
        else:
            trans, delegate, event = pass_through()
            if event is not None and (event.event_type is IonEventType.CONTAINER_START or event.event_type is IonEventType.CONTAINER_END):
                depth = event.depth
        data_event, _ = (yield Transition(event, self))

def timestamp(year, month=1, day=1, hour=0, minute=0, second=0, microsecond=None, off_hours=None, off_minutes=None, precision=None, fractional_precision=None):
    """Shorthand for the :class:`Timestamp` constructor.

    Specifically, converts ``off_hours`` and ``off_minutes`` parameters to a suitable
    :class:`OffsetTZInfo` instance."""
    delta = None
    if off_hours is not None:
        if off_hours < -23 or off_hours > 23:
            raise ValueError('Hour offset %d is out of required range -23..23.' % (off_hours,))
        delta = timedelta(hours=off_hours)
    if off_minutes is not None:
        if off_minutes < -59 or off_minutes > 59:
            raise ValueError('Minute offset %d is out of required range -59..59.' % (off_minutes,))
        minutes_delta = timedelta(minutes=off_minutes)
        if delta is None:
            delta = minutes_delta
        else:
            delta += minutes_delta
    tz = None
    if delta is not None:
        tz = OffsetTZInfo(delta)
    if microsecond is not None:
        if fractional_precision is None:
            fractional_precision = MICROSECOND_PRECISION
    else:
        microsecond = 0
        if fractional_precision is not None:
            raise ValueError('Cannot have fractional precision without a fractional component.')
    return Timestamp(year, month, day, hour, minute, second, microsecond, tz, precision=precision, fractional_precision=fractional_precision)

def consume_item_lazy(rlp, start):
    """Read an item from an RLP string lazily.

    If the length prefix announces a string, the string is read; if it
    announces a list, a :class:`LazyList` is created.

    :param rlp: the rlp string to read from
    :param start: the position at which to start reading
    :returns: a tuple ``(item, end)`` where ``item`` is the read string or a
              :class:`LazyList` and ``end`` is the position of the first
              unprocessed byte."""
    p, t, l, s = consume_length_prefix(rlp, start)
    if t is bytes:
        item, _, end = consume_payload(rlp, p, s, bytes, l)
        return (item, end)
    else:
        assert t is list
        return (LazyList(rlp, s, s + l), s + l)

def _eq(left, right):
    """Equality comparison that allows for equality between tuple and list types
    with equivalent elements."""
    if isinstance(left, (tuple, list)) and isinstance(right, (tuple, list)):
        return len(left) == len(right) and all((_eq(*pair) for pair in zip(left, right)))
    else:
        return left == right

def is_sequence(obj):
    """Check if `obj` is a sequence, but not a string or bytes."""
    return isinstance(obj, Sequence) and (not (isinstance(obj, str) or BinaryClass.is_valid_type(obj)))

def encode_raw(item):
    """RLP encode (a nested sequence of) :class:`Atomic`s."""
    if isinstance(item, Atomic):
        if len(item) == 1 and item[0] < 128:
            return item
        payload = item
        prefix_offset = 128
    elif not isinstance(item, str) and isinstance(item, collections.Sequence):
        payload = b''.join((encode_raw(x) for x in item))
        prefix_offset = 192
    else:
        msg = 'Cannot encode object of type {0}'.format(type(item).__name__)
        raise EncodingError(msg, item)
    try:
        prefix = length_prefix(len(payload), prefix_offset)
    except ValueError:
        raise EncodingError('Item too big to encode', item)
    return prefix + payload

def length_prefix(length, offset):
    """Construct the prefix to lists or strings denoting their length.

    :param length: the length of the item in bytes
    :param offset: ``0x80`` when encoding raw bytes, ``0xc0`` when encoding a
                   list"""
    if length < 56:
        return ALL_BYTES[offset + length]
    elif length < LONG_LENGTH:
        length_string = int_to_big_endian(length)
        return ALL_BYTES[offset + 56 - 1 + len(length_string)] + length_string
    else:
        raise ValueError('Length greater than 256**8')

def infer_sedes(obj):
    """Try to find a sedes objects suitable for a given Python object.

    The sedes objects considered are `obj`'s class, `big_endian_int` and
    `binary`. If `obj` is a sequence, a :class:`rlp.sedes.List` will be
    constructed recursively.

    :param obj: the python object for which to find a sedes object
    :raises: :exc:`TypeError` if no appropriate sedes could be found"""
    if is_sedes(obj.__class__):
        return obj.__class__
    elif not isinstance(obj, bool) and isinstance(obj, int) and (obj >= 0):
        return big_endian_int
    elif BinaryClass.is_valid_type(obj):
        return binary
    elif not isinstance(obj, str) and isinstance(obj, collections.Sequence):
        return List(map(infer_sedes, obj))
    elif isinstance(obj, bool):
        return boolean
    elif isinstance(obj, str):
        return text
    msg = 'Did not find sedes handling type {}'.format(type(obj).__name__)
    raise TypeError(msg)

def data(path, hours, offset=0):
    """Does the metric at ``path`` have any whisper data newer than ``hours``?

    If ``offset`` is not None, view the ``hours`` prior to ``offset`` hours
    ago, instead of from right now."""
    now = time.time()
    end = now - _to_sec(offset)
    start = end - _to_sec(hours)
    _data = whisper.fetch(path, start, end)
    return all((x is None for x in _data[-1]))

def stat(path, hours, offset=None):
    """Has the metric file at ``path`` been modified since ``hours`` ago?

    .. note::
        ``offset`` is only for compatibility with ``data()`` and is ignored."""
    return os.stat(path).st_mtime < time.time() - _to_sec(hours)

def find_path(start, goal, neighbors_fnct, reversePath=False, heuristic_cost_estimate_fnct=lambda a, b: Infinite, distance_between_fnct=lambda a, b: 1.0, is_goal_reached_fnct=lambda a, b: a == b):
    """A non-class version of the path finding algorithm"""
    class FindPath(AStar):
        def heuristic_cost_estimate(self, current, goal):
            return heuristic_cost_estimate_fnct(current, goal)
        def distance_between(self, n1, n2):
            return distance_between_fnct(n1, n2)
        def neighbors(self, node):
            return neighbors_fnct(node)
        def is_goal_reached(self, current, goal):
            return is_goal_reached_fnct(current, goal)
    return FindPath().astar(start, goal, reversePath)

def _clean_empty(d):
    """Remove None values from a dict."""
    if not isinstance(d, (dict, list)):
        return d
    if isinstance(d, list):
        return [v for v in (_clean_empty(v) for v in d) if v is not None]
    return {k: v for k, v in ((k, _clean_empty(v)) for k, v in d.items()) if v is not None}

def load():
    """Loads the libdmtx shared library.
    """
    if 'Windows' == platform.system():
        fname = _windows_fname()
        try:
            libdmtx = cdll.LoadLibrary(fname)
        except OSError:
            libdmtx = cdll.LoadLibrary(str(Path(__file__).parent.joinpath(fname)))
    else:
        path = find_library('dmtx')
        if not path:
            raise ImportError('Unable to find dmtx shared library')
        libdmtx = cdll.LoadLibrary(path)
    return libdmtx

def _pixel_data(image):
    """Returns (pixels, width, height, bpp)

    Returns:
        :obj: `tuple` (pixels, width, height, bpp)"""
    if 'PIL.' in str(type(image)):
        pixels = image.tobytes()
        width, height = image.size
    elif 'numpy.ndarray' in str(type(image)):
        if 'uint8' != str(image.dtype):
            image = image.astype('uint8')
        try:
            pixels = image.tobytes()
        except AttributeError:
            pixels = image.tostring()
        height, width = image.shape[:2]
    else:
        pixels, width, height = image
        if 0 != len(pixels) % (width * height):
            raise PyLibDMTXError('Inconsistent dimensions: image data of {0} bytes is not divisible by (width x height = {1})'.format(len(pixels), width * height))
    bpp = 8 * len(pixels) // (width * height)
    if bpp not in _PACK_ORDER:
        raise PyLibDMTXError('Unsupported bits-per-pixel: [{0}] Should be one of {1}'.format(bpp, sorted(_PACK_ORDER.keys())))
    return (pixels, width, height, bpp)

def _join_names(names):
    """Join the names of a multi-level index with an underscore."""
    levels = (str(name) for name in names if name != '')
    return '_'.join(levels)

def zcr(data):
    """Computes zero crossing rate of segment"""
    data = np.mean(data, axis=1)
    count = len(data)
    countZ = np.sum(np.abs(np.diff(np.sign(data)))) / 2
    return np.float64(countZ) / np.float64(count - 1.0)

def image_transform(X, function, reshape_before=False, reshape_after=False, width=None, height=None, **kwargs):
    """Apply a function image by image.

    Args:
        reshape_before: whether 1d array needs to be reshaped to a 2d image
        reshape_after: whether the returned values need to be reshaped back to a 1d array
        width: image width used to rebuild the 2d images. Required if the image is not square.
        height: image height used to rebuild the 2d images. Required if the image is not square."""
    if not callable(function):
        function = import_object(function)
    elif not callable(function):
        raise ValueError('function must be a str or a callable')
    flat_image = len(X[0].shape) == 1
    if reshape_before and flat_image:
        if not (width and height):
            side_length = math.sqrt(X.shape[1])
            if side_length.is_integer():
                side_length = int(side_length)
                width = side_length
                height = side_length
            else:
                raise ValueError('Image sizes must be given for non-square images')
    else:
        reshape_before = False
    new_X = []
    for image in X:
        if reshape_before:
            image = image.reshape((width, height))
        features = function(image, **kwargs)
        if reshape_after:
            features = np.reshape(features, X.shape[1])
        new_X.append(features)
    return np.array(new_X)

def deltas(errors, epsilon, mean, std):
    """Compute mean and std deltas.

    delta_mean = mean(errors) - mean(all errors below epsilon)
    delta_std = std(errors) - std(all errors below epsilon)"""
    below = errors[errors <= epsilon]
    if not len(below):
        return (0, 0)
    return (mean - below.mean(), std - below.std())

def prune_anomalies(e_seq, smoothed_errors, max_error_below_e, anomaly_indices):
    """Helper method that removes anomalies which don't meet
    a minimum separation from next anomaly."""
    MIN_PERCENT_DECREASE = 0.05
    e_seq_max, smoothed_errors_max = ([], [])
    for error_seq in e_seq:
        if len(smoothed_errors[error_seq[0]:error_seq[1]]) > 0:
            sliced_errors = smoothed_errors[error_seq[0]:error_seq[1]]
            e_seq_max.append(max(sliced_errors))
            smoothed_errors_max.append(max(sliced_errors))
    smoothed_errors_max.sort(reverse=True)
    if max_error_below_e > 0:
        smoothed_errors_max.append(max_error_below_e)
    indices_remove = []
    for i in range(len(smoothed_errors_max)):
        if i < len(smoothed_errors_max) - 1:
            delta = smoothed_errors_max[i] - smoothed_errors_max[i + 1]
            perc_change = delta / smoothed_errors_max[i]
            if perc_change < MIN_PERCENT_DECREASE:
                indices_remove.append(e_seq_max.index(smoothed_errors_max[i]))
    for index in sorted(indices_remove, reverse=True):
        del e_seq[index]
    pruned_indices = []
    for i in anomaly_indices:
        for error_seq in e_seq:
            if i >= error_seq[0] and i <= error_seq[1]:
                pruned_indices.append(i)
    return pruned_indices

def patch_memcache():
    """Monkey patch python-memcached to implement our consistent hashring
    in its node selection and operations."""
    def _init(self, servers, *k, **kw):
        self._old_init(servers, *k, **kw)
        nodes = {}
        for server in self.servers:
            conf = {'hostname': server.ip, 'instance': server, 'port': server.port, 'weight': server.weight}
            nodes[server.ip] = conf
        self.uhashring = HashRing(nodes)
    def _get_server(self, key):
        if isinstance(key, tuple):
            return self._old_get_server(key)
        for i in range(self._SERVER_RETRIES):
            for node in self.uhashring.range(key):
                if node['instance'].connect():
                    return (node['instance'], key)
        return (None, None)
    memcache = __import__('memcache')
    memcache.Client._old_get_server = memcache.Client._get_server
    memcache.Client._old_init = memcache.Client.__init__
    memcache.Client.__init__ = _init
    memcache.Client._get_server = _get_server

def activate(name):
    """Activate plugin.

    Parameters
    ----------
    name : str
        Plugin name."""
    if name in plugins:
        plugins[name].activate()
    else:
        raise Exception('plugin {} not found'.format(name))

def deactivate(name):
    """Deactivate plugin.

    Parameters
    ----------
    name : str
        Plugin name."""
    if name in plugins:
        plugins[name].deactivate()
    else:
        raise Exception('plugin {} not found'.format(name))

def manage_config(cmd, *args):
    """Manage genomepy config file."""
    if cmd == 'file':
        print(config.config_file)
    elif cmd == 'show':
        with open(config.config_file) as f:
            print(f.read())
    elif cmd == 'generate':
        fname = os.path.join(user_config_dir('genomepy'), '{}.yaml'.format('genomepy'))
        if not os.path.exists(user_config_dir('genomepy')):
            os.makedirs(user_config_dir('genomepy'))
        with open(fname, 'w') as fout:
            with open(config.config_file) as fin:
                fout.write(fin.read())
        print('Created config file {}'.format(fname))

def manage_plugins(command, plugin_names=None):
    """Enable or disable plugins.
    """
    if plugin_names is None:
        plugin_names = []
    active_plugins = config.get('plugin', [])
    plugins = init_plugins()
    if command == 'enable':
        for name in plugin_names:
            if name not in plugins:
                raise ValueError('Unknown plugin: {}'.format(name))
            if name not in active_plugins:
                active_plugins.append(name)
    elif command == 'disable':
        for name in plugin_names:
            if name in active_plugins:
                active_plugins.remove(name)
    elif command == 'list':
        print('{:20}{}'.format('plugin', 'enabled'))
        for plugin in sorted(plugins):
            print('{:20}{}'.format(plugin, {False: '', True: '*'}[plugin in active_plugins]))
    else:
        raise ValueError('Invalid plugin command')
    config['plugin'] = active_plugins
    config.save()
    if command in ['enable', 'disable']:
        print('Enabled plugins: {}'.format(', '.join(sorted(active_plugins))))

def install(name, provider, genome_dir, localname, mask, regex, match, annotation):
    """Install genome NAME from provider PROVIDER in directory GENOME_DIR."""
    genomepy.install_genome(name, provider, genome_dir=genome_dir, localname=localname, mask=mask, regex=regex, invert_match=not match, annotation=annotation)

def cmd_ok(cmd):
    """Returns True if cmd can be run.
    """
    try:
        sp.check_call(cmd, stderr=sp.PIPE, stdout=sp.PIPE)
    except sp.CalledProcessError:
        pass
    except:
        sys.stderr.write('{} not found, skipping\n'.format(cmd))
        return False
    return True

def convert_aws_args(aws_args):
    """Convert old style options into arguments to boto3.session.Session."""
    if not isinstance(aws_args, dict):
        raise errors.InvalidConfiguration('Elastic DocManager config option "aws" must be a dict')
    old_session_kwargs = dict(region='region_name', access_id='aws_access_key_id', secret_key='aws_secret_access_key')
    new_kwargs = {}
    for arg in aws_args:
        if arg in old_session_kwargs:
            new_kwargs[old_session_kwargs[arg]] = aws_args[arg]
        else:
            new_kwargs[arg] = aws_args[arg]
    return new_kwargs

def bt_addr_to_string(addr):
    """Convert a binary string to the hex representation."""
    addr_str = array.array('B', addr)
    addr_str.reverse()
    hex_str = hexlify(addr_str.tostring()).decode('ascii')
    return ':'.join((a + b for a, b in zip(hex_str[::2], hex_str[1::2])))

def is_one_of(obj, types):
    """Return true iff obj is an instance of one of the types."""
    for type_ in types:
        if isinstance(obj, type_):
            return True
    return False

def bin_to_int(string):
    """Convert a one element byte string to signed int for python 2 support."""
    if isinstance(string, str):
        return struct.unpack('b', string)[0]
    else:
        return struct.unpack('b', bytes([string]))[0]

def get_mode(device_filter):
    """Determine which beacons the scanner should look for."""
    from .device_filters import IBeaconFilter, EddystoneFilter, BtAddrFilter, EstimoteFilter
    if device_filter is None or len(device_filter) == 0:
        return ScannerMode.MODE_ALL
    mode = ScannerMode.MODE_NONE
    for filtr in device_filter:
        if isinstance(filtr, IBeaconFilter):
            mode |= ScannerMode.MODE_IBEACON
        elif isinstance(filtr, EddystoneFilter):
            mode |= ScannerMode.MODE_EDDYSTONE
        elif isinstance(filtr, EstimoteFilter):
            mode |= ScannerMode.MODE_ESTIMOTE
        elif isinstance(filtr, BtAddrFilter):
            mode |= ScannerMode.MODE_ALL
            break
    return mode

def parse_packet(packet):
    """Parse a beacon advertisement packet."""
    frame = parse_ltv_packet(packet)
    if frame is None:
        frame = parse_ibeacon_packet(packet)
    return frame

def parse_ltv_packet(packet):
    """Parse a tag-length-value style beacon packet."""
    try:
        frame = LTVFrame.parse(packet)
        for ltv in frame:
            if ltv['type'] == SERVICE_DATA_TYPE:
                data = ltv['value']
                if data['service_identifier'] == EDDYSTONE_UUID:
                    return parse_eddystone_service_data(data)
                elif data['service_identifier'] == ESTIMOTE_UUID:
                    return parse_estimote_service_data(data)
    except ConstructError:
        return None
    return None

def parse_eddystone_service_data(data):
    """Parse Eddystone service data."""
    if data['frame_type'] == EDDYSTONE_UID_FRAME:
        return EddystoneUIDFrame(data['frame'])
    elif data['frame_type'] == EDDYSTONE_TLM_FRAME:
        if data['frame']['tlm_version'] == EDDYSTONE_TLM_ENCRYPTED:
            return EddystoneEncryptedTLMFrame(data['frame']['data'])
        elif data['frame']['tlm_version'] == EDDYSTONE_TLM_UNENCRYPTED:
            return EddystoneTLMFrame(data['frame']['data'])
    elif data['frame_type'] == EDDYSTONE_URL_FRAME:
        return EddystoneURLFrame(data['frame'])
    elif data['frame_type'] == EDDYSTONE_EID_FRAME:
        return EddystoneEIDFrame(data['frame'])
    else:
        return None

def parse_estimote_service_data(data):
    """Parse Estimote service data."""
    if data['frame_type'] & 15 == ESTIMOTE_TELEMETRY_FRAME:
        protocol_version = (data['frame_type'] & 240) >> 4
        if data['frame']['subframe_type'] == ESTIMOTE_TELEMETRY_SUBFRAME_A:
            return EstimoteTelemetryFrameA(data['frame'], protocol_version)
        elif data['frame']['subframe_type'] == ESTIMOTE_TELEMETRY_SUBFRAME_B:
            return EstimoteTelemetryFrameB(data['frame'], protocol_version)
    return None

