def stream_download(url, target_path, verbose=False):
    """Download a large file without loading it into memory."""
    response = requests.get(url, stream=True)
    handle = open(target_path, 'wb')
    if verbose:
        print('Beginning streaming download of %s' % url)
        start = datetime.now()
        try:
            content_length = int(response.headers['Content-Length'])
            content_MB = content_length / 1048576.0
            print('Total file size: %.2f MB' % content_MB)
        except KeyError:
            pass
    for chunk in response.iter_content(chunk_size=512):
        if chunk:
            handle.write(chunk)
    if verbose:
        print('Download completed to %s in %s' % (target_path, datetime.now() - start))

def _cached_by_domain(api_name):
    """A caching wrapper for functions that take a list of domains as
    parameters.

    Raises:
        ResponseError - if the response received from the endpoint is
        not valid."""
    def wrapped(func):
        def decorated(self, domains):
            if not self._cache:
                return func(self, domains)
            all_responses = self._cache.bulk_lookup(api_name, domains)
            domains = list(set(domains) - set(all_responses))
            if domains:
                response = func(self, domains)
                if not response:
                    raise ResponseError('No response for uncached domains')
                for domain in response:
                    self._cache.cache_value(api_name, domain, response[domain])
                    all_responses[domain] = response[domain]
            return all_responses
        return decorated
    return wrapped

def remapOpenCv(im, coords):
    """Remap an image using OpenCV. See :func:`remap` for parameters."""
    im = np.require(im, im.dtype, 'C')
    return cv2.remap(im, coords, None, cv2.INTER_LANCZOS4)

def remap(im, coords):
    """Remap an RGB image using the given target coordinate array.

    If available, OpenCV is used (faster), otherwise SciPy.

    :type im: ndarray of shape (h,w,3)
    :param im: RGB image to be remapped
    :type coords: ndarray of shape (h,w,2)
    :param coords: target coordinates in x,y order for each pixel
    :return: remapped RGB image
    :rtype: ndarray of shape (h,w,3)"""
    if cv2:
        return remapOpenCv(im, coords)
    else:
        return remapScipy(im, coords)

def get_valid_commands():
    """Returns valid commands.

    Returns:
        commands (list): List of valid commands"""
    modules = [m.basename().split('.')[0] for m in Path(__file__).dirname().files('*.py')]
    commands = []
    for modname in modules:
        if modname == 'main':
            continue
        mod = importlib.import_module('i18n.%s' % modname)
        if hasattr(mod, 'main'):
            commands.append(modname)
    return commands

def main():
    """Executes the given command. Returns error_message if command is not valid.

    Returns:
        Output of the given command or error message if command is not valid."""
    try:
        command = sys.argv[1]
    except IndexError:
        return error_message()
    try:
        module = importlib.import_module('i18n.%s' % command)
        module.main.args = sys.argv[2:]
    except (ImportError, AttributeError):
        return error_message()
    return module.main()

def validate_po_files(configuration, locale_dir, root_dir=None, report_empty=False, check_all=False):
    """Validate all of the po files found in the root directory that are not product of a merge.

    Returns a boolean indicating whether or not problems were found."""
    found_problems = False
    merged_files = configuration.generate_merge.keys()
    for dirpath, __, filenames in os.walk(root_dir if root_dir else locale_dir):
        for name in filenames:
            __, ext = os.path.splitext(name)
            filename = os.path.join(dirpath, name)
            if ext.lower() == '.po' and (check_all or os.path.basename(filename) not in merged_files):
                if msgfmt_check_po_file(locale_dir, filename):
                    found_problems = True
                if '/locale/en/' not in filename:
                    problems = check_messages(filename, report_empty)
                    if problems:
                        report_problems(filename, problems)
                        found_problems = True
                    dup_filename = filename.replace('.po', '.dup')
                    has_duplicates = os.path.exists(dup_filename)
                    if has_duplicates:
                        log.warning(' Duplicates found in %s, details in .dup file', dup_filename)
                        found_problems = True
                    if not (problems or has_duplicates):
                        log.info(' No problems found in %s', filename)
    return found_problems

def tags_in_string(msg):
    """Return the set of tags in a message string.

    Tags includes HTML tags, data placeholders, etc.

    Skips tags that might change due to translations: HTML entities, <abbr>,
    and so on."""
    def is_linguistic_tag(tag):
        """Is this tag one that can change with the language?"""
        if tag.startswith('&'):
            return True
        if any((x in tag for x in ['<abbr>', '<abbr ', '</abbr>'])):
            return True
        return False
    __, tags = Converter().detag_string(msg)
    return set((t for t in tags if not is_linguistic_tag(t)))

def astral(msg):
    """Does `msg` have characters outside the Basic Multilingual Plane?"""
    utf32 = msg.encode('utf32')[4:]
    code_points = struct.unpack('%dI' % (len(utf32) / 4), utf32)
    return any((cp > 65535 for cp in code_points))

def merge_files(configuration, locale, fail_if_missing=True):
