def validate_files(directory, files_to_merge):
    """Asserts that the given files exist.
    files_to_merge is a list of file names (no directories).
    directory is the directory (a path object from path.py) in which the files should appear.
    raises an Exception if any of the files are not in dir."""
    for file_path in files_to_merge:
        pathname = directory.joinpath(file_path)
        if not pathname.exists():
            raise Exception('I18N: Cannot generate because file not found: {0}'.format(pathname))
        clean_pofile(pathname)

def new_filename(original_filename, new_locale):
    """Returns a filename derived from original_filename, using new_locale as the locale"""
    orig_file = Path(original_filename)
    new_file = orig_file.parent.parent.parent / new_locale / orig_file.parent.name / orig_file.name
    return new_file.abspath()

def remove_file(filename, verbose=True):
    """Attempt to delete filename.
    log is boolean. If true, removal is logged.
    Log a warning if file does not exist.
    Logging filenames are relative to config.BASE_DIR to cut down on noise in output."""
    if verbose:
        LOG.info('Deleting file %s', os.path.relpath(filename, config.BASE_DIR))
    if not os.path.exists(filename):
        LOG.warning('File does not exist: %s', os.path.relpath(filename, config.BASE_DIR))
    else:
        os.remove(filename)

def push(*resources):
    """Push translation source English files to Transifex.

    Arguments name specific resources to push. Otherwise, push all the source
    files."""
    cmd = 'tx push -s'
    if resources:
        for resource in resources:
            execute(cmd + ' -r {resource}'.format(resource=resource))
    else:
        execute(cmd)

def pull(configuration, *resources):
    """Pull translations from all languages listed in conf/locale/config.yaml
    where there is at least 10% reviewed translations.

    If arguments are provided, they are specific resources to pull.  Otherwise,
    all resources are pulled."""
    print('Pulling conf/locale/config.yaml:locales from Transifex...')
    for lang in configuration.translated_locales:
        cmd = 'tx pull -f --mode=reviewed --minimum-perc=3 -l {lang}'.format(lang=lang)
        if resources:
            for resource in resources:
                execute(cmd + ' -r {resource}'.format(resource=resource))
        else:
            execute(cmd)
    clean_translated_locales(configuration)

def clean_translated_locales(configuration, langs=None):
    """Strips out the warning from all translated po files
    about being an English source file."""
    if not langs:
        langs = configuration.translated_locales
    for locale in langs:
        clean_locale(configuration, locale)

def clean_locale(configuration, locale):
    """Strips out the warning from all of a locale's translated po files
    about being an English source file.
    Iterates over machine-generated files."""
    dirname = configuration.get_messages_dir(locale)
    if not dirname.exists():
        return
    for filename in dirname.files('*.po'):
        clean_file(configuration, dirname.joinpath(filename))

