    if len(key_value) != 2:
        raise exceptions.CLIAbort('Invalid ID %s: ID should be of the form xxx:yyy' % input_id)
    return (key_value[0], int(key_value[1]))

def _build_filters(_filters):
    """Builds filters using the filter options passed into the CLI.

    This only supports the equals keyword at the moment."""
    root = utils.NestedDict({})
    for _filter in _filters:
        operation = None
        for operation, token in SPLIT_TOKENS:
            top_parts = _filter.split(token, 1)
            if len(top_parts) == 2:
                break
        else:
            raise exceptions.CLIAbort('Failed to find valid operation for: %s' % _filter)
        key, value = top_parts
        current = root
        parts = [part.strip() for part in key.split('.')]
        for part in parts[:-1]:
            current = current[part]
        if operation == 'eq':
            current[parts[-1]] = utils.query_filter(value.strip())
        elif operation == 'in':
            current[parts[-1]] = {'operation': 'in', 'options': [{'name': 'data', 'value': [p.strip() for p in value.split(',')]}]}
    return root.to_dict()

