def _get_extra_price_id(items, key_name, hourly, location):
    """Returns a price id attached to item with the given key_name."""
    for item in items:
        if utils.lookup(item, 'keyName') != key_name:
            continue
        for price in item['prices']:
            if not _matches_billing(price, hourly):
                continue
            if not _matches_location(price, location):
                continue
            return price['id']
    raise SoftLayer.SoftLayerError("Could not find valid price for extra option, '%s'" % key_name)

def _get_default_price_id(items, option, hourly, location):
    """Returns a 'free' price id given an option."""
    for item in items:
        if utils.lookup(item, 'itemCategory', 'categoryCode') != option:
            continue
        for price in item['prices']:
            if all([float(price.get('hourlyRecurringFee', 0)) == 0.0, float(price.get('recurringFee', 0)) == 0.0, _matches_billing(price, hourly), _matches_location(price, location)]):
                return price['id']
    raise SoftLayer.SoftLayerError("Could not find valid price for '%s' option" % option)

def _get_bandwidth_price_id(items, hourly=True, no_public=False, location=None):
    """Choose a valid price id for bandwidth."""
    for item in items:
        capacity = float(item.get('capacity', 0))
        if any([utils.lookup(item, 'itemCategory', 'categoryCode') != 'bandwidth', (hourly or no_public) and capacity != 0.0, not (hourly or no_public) and capacity == 0.0]):
            continue
        for price in item['prices']:
            if not _matches_billing(price, hourly):
                continue
            if not _matches_location(price, location):
                continue
            return price['id']
    raise SoftLayer.SoftLayerError('Could not find valid price for bandwidth option')

def _get_os_price_id(items, os, location):
    """Returns the price id matching."""
    for item in items:
        if any([utils.lookup(item, 'itemCategory', 'categoryCode') != 'os', utils.lookup(item, 'softwareDescription', 'referenceCode') != os]):
            continue
        for price in item['prices']:
            if not _matches_location(price, location):
                continue
            return price['id']
    raise SoftLayer.SoftLayerError("Could not find valid price for os: '%s'" % os)

def _get_port_speed_price_id(items, port_speed, no_public, location):
    """Choose a valid price id for port speed."""
    for item in items:
        if utils.lookup(item, 'itemCategory', 'categoryCode') != 'port_speed':
            continue
        if any([int(utils.lookup(item, 'capacity')) != port_speed, _is_private_port_speed_item(item) != no_public, not _is_bonded(item)]):
            continue
        for price in item['prices']:
            if not _matches_location(price, location):
                continue
            return price['id']
    raise SoftLayer.SoftLayerError("Could not find valid price for port speed: '%s'" % port_speed)

def _matches_billing(price, hourly):
    """Return True if the price object is hourly and/or monthly."""
    return any([hourly and price.get('hourlyRecurringFee') is not None, not hourly and price.get('recurringFee') is not None])

def _matches_location(price, location):
    """Return True if the price object matches the location."""
    if not price.get('locationGroupId'):
        return True
    for group in location['location']['location']['priceGroups']:
        if group['id'] == price['locationGroupId']:
            return True
    return False

def _get_location(package, location):
    """Get the longer key with a short location name."""
    for region in package['regions']:
        if region['location']['location']['name'] == location:
            return region
    raise SoftLayer.SoftLayerError("Could not find valid location for: '%s'" % location)

def _get_preset_id(package, size):
    """Get the preset id given the keyName of the preset."""
    for preset in package['activePresets'] + package['accountRestrictedActivePresets']:
        if preset['keyName'] == size or preset['id'] == size:
            return preset['id']
    raise SoftLayer.SoftLayerError("Could not find valid size for: '%s'" % size)

