def register_magics(store_name='_ampl_cells', ampl_object=None):
    """Register jupyter notebook magics ``%%ampl`` and ``%%ampl_eval``.

    Args:
        store_name: Name of the store where ``%%ampl cells`` will be stored.
        ampl_object: Object used to evaluate ``%%ampl_eval`` cells."""
    from IPython.core.magic import Magics, magics_class, cell_magic, line_magic
    @magics_class
    class StoreAMPL(Magics):
        def __init__(self, shell=None, **kwargs):
            Magics.__init__(self, shell=shell, **kwargs)
            self._store = []
            shell.user_ns[store_name] = self._store
        @cell_magic
        def ampl(self, line, cell):
            """Store the cell in the store"""
            self._store.append(cell)
        @cell_magic
        def ampl_eval(self, line, cell):
            """Evaluate the cell"""
            ampl_object.eval(cell)
        @line_magic
        def get_ampl(self, line):
            """Retrieve the store"""
            return self._store
    get_ipython().register_magics(StoreAMPL)

def toVName(name, stripNum=0, upper=False):
    """Turn a Python name into an iCalendar style name,
    optionally uppercase and with characters stripped off."""
    if upper:
        name = name.upper()
    if stripNum != 0:
        name = name[:-stripNum]
    return name.replace('_', '-')

def parseParams(string):
    """Parse parameters"""
    all = params_re.findall(string)
    allParameters = []
    for tup in all:
        paramList = [tup[0]]
        for pair in param_values_re.findall(tup[1]):
            if pair[0] != '':
                paramList.append(pair[0])
            else:
                paramList.append(pair[1])
        allParameters.append(paramList)
    return allParameters

def parseLine(line, lineNumber=None):
    """Parse line"""
    match = line_re.match(line)
    if match is None:
        raise ParseError('Failed to parse line: {0!s}'.format(line), lineNumber)
    return (match.group('name').replace('_', '-'), parseParams(match.group('params')), match.group('value'), match.group('group'))

def dquoteEscape(param):
    """Return param, or "param" if ',' or ';' or ':' is in param."""
    if param.find('"') >= 0:
        raise VObjectError("Double quotes aren't allowed in parameter values.")
    for char in ',;:':
        if param.find(char) >= 0:
            return '"' + param + '"'
    return param

def readOne(stream, validate=False, transform=True, ignoreUnreadable=False, allowQP=False):
    """Return the first component from stream."""
    return next(readComponents(stream, validate, transform, ignoreUnreadable, allowQP))

def registerBehavior(behavior, name=None, default=False, id=None):
    """Register the given behavior.

    If default is True (or if this is the first version registered with this
    name), the version will be the default if no id is given."""
    if not name:
        name = behavior.name.upper()
    if id is None:
        id = behavior.versionString
    if name in __behaviorRegistry:
        if default:
            __behaviorRegistry[name].insert(0, (id, behavior))
        else:
            __behaviorRegistry[name].append((id, behavior))
    else:
        __behaviorRegistry[name] = [(id, behavior)]

def getBehavior(name, id=None):
    """Return a matching behavior if it exists, or None.

    If id is None, return the default for name."""
    name = name.upper()
    if name in __behaviorRegistry:
        if id:
            for n, behavior in __behaviorRegistry[name]:
                if n == id:
                    return behavior
        return __behaviorRegistry[name][0][1]
    return None

def change_tz(cal, new_timezone, default, utc_only=False, utc_tz=icalendar.utc):
    """Change the timezone of the specified component.

    Args:
        cal (Component): the component to change
        new_timezone (tzinfo): the timezone to change to
        default (tzinfo): a timezone to assume if the dtstart or dtend in cal
            doesn't have an existing timezone
        utc_only (bool): only convert dates that are in utc
        utc_tz (tzinfo): the tzinfo to compare to for UTC when processing
            utc_only=True"""
    for vevent in getattr(cal, 'vevent_list', []):
        start = getattr(vevent, 'dtstart', None)
        end = getattr(vevent, 'dtend', None)
        for node in (start, end):
            if node:
                dt = node.value
                if isinstance(dt, datetime) and (not utc_only or dt.tzinfo == utc_tz):
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=default)
                    node.value = dt.astimezone(new_timezone)

def foldOneLine(outbuf, input, lineLength=75):
    """Folding line procedure that ensures multi-byte utf-8 sequences are not
    broken across lines

    TO-DO: This all seems odd. Is it still needed, especially in python3?"""
    if len(input) < lineLength:
        try:
            outbuf.write(bytes(input, 'UTF-8'))
        except Exception:
            outbuf.write(str_(input))
    else:
        start = 0
        written = 0
        counter = 0
        decoded = to_unicode(input)
        length = len(to_basestring(input))
        while written < length:
            s = decoded[start]
            size = len(to_basestring(s))
            if counter + size > lineLength:
                try:
                    outbuf.write(bytes('\r\n ', 'UTF-8'))
                except Exception:
                    outbuf.write('\r\n ')
                counter = 1
            if str is unicode_type:
                outbuf.write(to_unicode(s))
            else:
                outbuf.write(s.encode('utf-8'))
            written += size
            counter += size
            start += 1
    try:
        outbuf.write(bytes('\r\n', 'UTF-8'))
    except Exception:
        outbuf.write('\r\n')

def defaultSerialize(obj, buf, lineLength):
    """Encode and fold obj and its children, write to buf or return a string."""
    outbuf = buf or six.StringIO()
    if isinstance(obj, Component):
        if obj.group is None:
            groupString = ''
        else:
            groupString = obj.group + '.'
        if obj.useBegin:
            foldOneLine(outbuf, '{0}BEGIN:{1}'.format(groupString, obj.name), lineLength)
        for child in obj.getSortedChildren():
            child.serialize(outbuf, lineLength, validate=False)
        if obj.useBegin:
            foldOneLine(outbuf, '{0}END:{1}'.format(groupString, obj.name), lineLength)
    elif isinstance(obj, ContentLine):
        startedEncoded = obj.encoded
        if obj.behavior and (not startedEncoded):
            obj.behavior.encode(obj)
        s = six.StringIO()
        if obj.group is not None:
            s.write(obj.group + '.')
        s.write(obj.name.upper())
        keys = sorted(obj.params.keys())
        for key in keys:
            paramstr = ','.join((dquoteEscape(p) for p in obj.params[key]))
            s.write(';{0}={1}'.format(key, paramstr))
        s.write(':{0}'.format(str_(obj.value)))
        if obj.behavior and (not startedEncoded):
            obj.behavior.decode(obj)
        foldOneLine(outbuf, s.getvalue(), lineLength)
    return buf or outbuf.getvalue()

def toUnicode(s):
    """Take a string or unicode, turn it into unicode, decoding as utf-8"""
    if isinstance(s, six.binary_type):
        s = s.decode('utf-8')
    return s

def numToDigits(num, places):
    """Helper, for converting numbers to textual digits."""
    s = str(num)
    if len(s) < places:
        return '0' * (places - len(s)) + s
    elif len(s) > places:
        return s[len(s) - places:]
    else:
        return s

def timedeltaToString(delta):
    """Convert timedelta to an ical DURATION."""
    if delta.days == 0:
        sign = 1
    else:
        sign = delta.days / abs(delta.days)
    delta = abs(delta)
    days = delta.days
    hours = int(delta.seconds / 3600)
    minutes = int(delta.seconds % 3600 / 60)
    seconds = int(delta.seconds % 60)
    output = ''
    if sign == -1:
        output += '-'
    output += 'P'
    if days:
        output += '{}D'.format(days)
    if hours or minutes or seconds:
        output += 'T'
    elif not days:
        output += 'T0S'
    if hours:
        output += '{}H'.format(hours)
    if minutes:
        output += '{}M'.format(minutes)
    if seconds:
        output += '{}S'.format(seconds)
    return output

def parseDtstart(contentline, allowSignatureMismatch=False):
    """Convert a contentline's value into a date or date-time.

    A variety of clients don't serialize dates with the appropriate VALUE
    parameter, so rather than failing on these (technically invalid) lines,
    if allowSignatureMismatch is True, try to parse both varieties."""
    tzinfo = getTzid(getattr(contentline, 'tzid_param', None))
    valueParam = getattr(contentline, 'value_param', 'DATE-TIME').upper()
    if valueParam == 'DATE':
        return stringToDate(contentline.value)
    elif valueParam == 'DATE-TIME':
        try:
            return stringToDateTime(contentline.value, tzinfo)
        except:
            if allowSignatureMismatch:
                return stringToDate(contentline.value)
            else:
                raise

def tzinfo_eq(tzinfo1, tzinfo2, startYear=2000, endYear=2020):
    """Compare offsets and DST transitions from startYear to endYear."""
    if tzinfo1 == tzinfo2:
        return True
    elif tzinfo1 is None or tzinfo2 is None:
        return False
    def dt_test(dt):
        if dt is None:
            return True
        return tzinfo1.utcoffset(dt) == tzinfo2.utcoffset(dt)
    if not dt_test(datetime.datetime(startYear, 1, 1)):
        return False
    for year in range(startYear, endYear):
        for transitionTo in ('daylight', 'standard'):
            t1 = getTransition(transitionTo, year, tzinfo1)
            t2 = getTransition(transitionTo, year, tzinfo2)
            if t1 != t2 or not dt_test(t1):
                return False
    return True

def serializeFields(obj, order=None):
    """Turn an object's fields into a ';' and ',' seperated string.

    If order is None, obj should be a list, backslash escape each field and
    return a ';' separated string."""
    fields = []
    if order is None:
        fields = [backslashEscape(val) for val in obj]
    else:
        for field in order:
            escapedValueList = [backslashEscape(val) for val in toList(getattr(obj, field))]
            fields.append(','.join(escapedValueList))
    return ';'.join(fields)

def list_timezones():
    """Return a list of all time zones known to the system."""
    l = []
    for i in xrange(parentsize):
        l.append(_winreg.EnumKey(tzparent, i))
    return l

def pickNthWeekday(year, month, dayofweek, hour, minute, whichweek):
    """dayofweek == 0 means Sunday, whichweek > 4 means last instance"""
    first = datetime.datetime(year=year, month=month, hour=hour, minute=minute, day=1)
    weekdayone = first.replace(day=(dayofweek - first.isoweekday()) % 7 + 1)
    for n in xrange(whichweek - 1, -1, -1):
        dt = weekdayone + n * WEEKS
        if dt.month == month:
            return dt

def valuesToDict(key):
    """Convert a registry key's values to a dictionary."""
    d = {}
    size = _winreg.QueryInfoKey(key)[1]
    for i in xrange(size):
        d[_winreg.EnumValue(key, i)[0]] = _winreg.EnumValue(key, i)[1]
    return d

def stringToDateTime(s, tzinfo=None):
    """Returns datetime.datetime object."""
    try:
        year = int(s[0:4])
        month = int(s[4:6])
        day = int(s[6:8])
        hour = int(s[9:11])
        minute = int(s[11:13])
        second = int(s[13:15])
        if len(s) > 15:
            if s[15] == 'Z':
                tzinfo = getTzid('UTC')
    except:
        raise ParseError("'{0!s}' is not a valid DATE-TIME".format(s))
    year = year and year or 2000
    if tzinfo is not None and hasattr(tzinfo, 'localize'):
        return tzinfo.localize(datetime.datetime(year, month, day, hour, minute, second))
    return datetime.datetime(year, month, day, hour, minute, second, 0, tzinfo)

def deleteExtraneous(component, ignore_dtstamp=False):
    """Recursively walk the component's children, deleting extraneous details like
    X-VOBJ-ORIGINAL-TZID."""
    for comp in component.components():
        deleteExtraneous(comp, ignore_dtstamp)
    for line in component.lines():
        if 'X-VOBJ-ORIGINAL-TZID' in line.params:
            del line.params['X-VOBJ-ORIGINAL-TZID']
    if ignore_dtstamp and hasattr(component, 'dtstamp_list'):
        del component.dtstamp_list

def get_thermostat_meter_data(zone):
    """This method subscribes to the output of the meter for the given zone.
    It returns a handler to call when you want to stop subscribing data, which
    returns a list of the data readins over that time period"""
    meter_uri = zone2meter.get(zone, 'None')
    data = []
    def cb(msg):
        for po in msg.payload_objects:
            if po.type_dotted == (2, 0, 9, 1):
                m = msgpack.unpackb(po.content)
                data.append(m['current_demand'])
    handle = c.subscribe(meter_uri + '/signal/meter', cb)
    def stop():
        c.unsubscribe(handle)
        return data
    return stop

def make_dataframe(result):
    """Turns the results of one of the data API calls into a pandas dataframe"""
    import pandas as pd
    ret = {}
    if isinstance(result, dict):
        if 'timeseries' in result:
            result = result['timeseries']
    for uuid, data in result.items():
        df = pd.DataFrame(data)
        if len(df.columns) == 5:
            df.columns = ['time', 'min', 'mean', 'max', 'count']
        else:
            df.columns = ['time', 'value']
        df['time'] = pd.to_datetime(df['time'], unit='ns')
        df = df.set_index(df.pop('time'))
        ret[uuid] = df
    return ret

def merge_dfs(dfs, resample=None, do_mean=False, do_sum=False, do_min=False, do_max=False):
    """dfs is a dictionary of key => dataframe
    This method resamples each of the dataframes if a period is provided
    (http://pandas.pydata.org/pandas-docs/stable/timeseries.html#offset-aliases)"""
    if len(dfs) == 0:
        raise Exception('No dataframes provided')
    df = dfs.values()[0]
    name = dfs.keys()[0]
    df.columns = map(lambda x: name + '_' + x if not x.startswith(name) else x, df.columns)
    if resample is not None:
        df = df.resample(resample)
        if do_mean:
            df = df.mean()
        elif do_sum:
            df = df.sum()
        elif do_min:
            df = df.min()
        elif do_max:
            df = df.max()
        else:
            df = df.mean()
    if len(dfs) > 1:
        for name, newdf in dfs.items()[1:]:
            if resample is not None:
                newdf = newdf.resample(resample)
                if do_mean:
                    newdf = newdf.mean()
                elif do_sum:
                    newdf = newdf.sum()
                elif do_min:
                    newdf = newdf.min()
                elif do_max:
                    newdf = newdf.max()
                else:
                    newdf = newdf.mean()
            newdf.columns = map(lambda x: name + '_' + x if not x.startswith(name) else x, newdf.columns)
            df = df.merge(newdf, left_index=True, right_index=True, how='outer')
    return df

def decode(var, encoding):
    """If not already unicode, decode it."""
    if PY2:
        if isinstance(var, unicode):
            ret = var
        elif isinstance(var, str):
            if encoding:
                ret = var.decode(encoding)
            else:
                ret = unicode(var)
        else:
            ret = unicode(var)
    else:
        ret = str(var)
    return ret

def abbr(value: Any, limit: int=20) -> str:
    """Converts a value into its string representation and abbreviates that
    representation based on the given length `limit` if necessary."""
    rep = repr(value)
    if len(rep) > limit:
        if limit < 3:
            raise ValueError('Abbreviation limit may not be less than 3')
        rep = rep[:limit - 3] + '...'
    return rep

def parse_tuple_type_str(old_from_type_str):
    """Used by BaseCoder subclasses as a convenience for implementing the
    ``from_type_str`` method required by ``ABIRegistry``.  Useful if normalizing
    then parsing a tuple type string is required in that method."""
    @functools.wraps(old_from_type_str)
    def new_from_type_str(cls, type_str, registry):
        normalized_type_str = normalize(type_str)
        abi_type = parse(normalized_type_str)
        type_str_repr = repr(type_str)
        if type_str != normalized_type_str:
            type_str_repr = '{} (normalized to {})'.format(type_str_repr, repr(normalized_type_str))
        if not isinstance(abi_type, TupleType):
            raise ValueError('Cannot create {} for non-tuple type {}'.format(cls.__name__, type_str_repr))
        abi_type.validate()
        return old_from_type_str(cls, abi_type, registry)
    return classmethod(new_from_type_str)

def has_arrlist(type_str):
    """A predicate that matches a type string with an array dimension list."""
    try:
        abi_type = grammar.parse(type_str)
    except exceptions.ParseError:
        return False
    return abi_type.arrlist is not None

def is_base_tuple(type_str):
    """A predicate that matches a tuple type with no array dimension list."""
    try:
        abi_type = grammar.parse(type_str)
    except exceptions.ParseError:
        return False
    return isinstance(abi_type, grammar.TupleType) and abi_type.arrlist is None

def quote_address(address: str) -> str:
    """Quote a subset of the email addresses defined by RFC 821.

    Should be able to handle anything email.utils.parseaddr can handle."""
    display_name, parsed_address = email.utils.parseaddr(address)
    if parsed_address:
        quoted_address = '<{}>'.format(parsed_address)
    else:
        quoted_address = '<{}>'.format(address.strip())
    return quoted_address

def _extract_sender(message: Message, resent_dates: List[Union[str, Header]]=None) -> str:
    """Extract the sender from the message object given."""
    if resent_dates:
        sender_header = 'Resent-Sender'
        from_header = 'Resent-From'
    else:
        sender_header = 'Sender'
        from_header = 'From'
    if sender_header in message:
        sender = message[sender_header]
    else:
        sender = message[from_header]
    return str(sender) if sender else ''

def _extract_recipients(message: Message, resent_dates: List[Union[str, Header]]=None) -> List[str]:
    """Extract the recipients from the message object given."""
    recipients = []
    if resent_dates:
        recipient_headers = ('Resent-To', 'Resent-Cc', 'Resent-Bcc')
    else:
        recipient_headers = ('To', 'Cc', 'Bcc')
    for header in recipient_headers:
        recipients.extend(message.get_all(header, []))
    parsed_recipients = [str(email.utils.formataddr(address)) for address in email.utils.getaddresses(recipients)]
    return parsed_recipients

def isValidPublicAddress(address: str) -> bool:
    """Check if address is a valid NEO address"""
    valid = False
    if len(address) == 34 and address[0] == 'A':
        try:
            base58.b58decode_check(address.encode())
            valid = True
        except ValueError:
            valid = False
    return valid

def sso_entry(request):
    """Entrypoint view for SSO. Gathers the parameters from the HTTP request, stores them in the session
    and redirects the requester to the login_process view."""
    if request.method == 'POST':
        passed_data = request.POST
        binding = BINDING_HTTP_POST
    else:
        passed_data = request.GET
        binding = BINDING_HTTP_REDIRECT
    request.session['Binding'] = binding
    try:
        request.session['SAMLRequest'] = passed_data['SAMLRequest']
    except (KeyError, MultiValueDictKeyError) as e:
        return HttpResponseBadRequest(e)
    request.session['RelayState'] = passed_data.get('RelayState', '')
    if 'SigAlg' in passed_data and 'Signature' in passed_data:
        request.session['SigAlg'] = passed_data['SigAlg']
        request.session['Signature'] = passed_data['Signature']
    return HttpResponseRedirect(reverse('djangosaml2idp:saml_login_process'))

def custom_update_user(sender, instance, attributes, user_modified, **kargs):
    """Default behaviour does not play nice with booleans encoded in SAML as u'true'/u'false'.
    This will convert those attributes to real booleans when saving."""
    for k, v in attributes.items():
        u = set.intersection(set(v), set([u'true', u'false']))
        if u:
            setattr(instance, k, u.pop() == u'true')
    return True

def _extract_properties(config):
    """Parse a line within a lease block
    The line should basically match the expression:
    >>> r"\\s+(?P<key>(?:option|set)\\s+\\S+|\\S+) (?P<value>[\\s\\S]+?);"
    For easier seperation of the cases and faster parsing this is done using substrings etc..
    :param config:
    :return: tuple of properties dict, options dict and sets dict"""
    general, options, sets = ({}, {}, {})
    for line in config.splitlines():
        if not line or (not line[-1:] == ';' and '; #' not in line):
            continue
        line = line[:-1].lstrip()
        if line[:6] == 'option':
            key, value = _extract_prop_option(line)
            options[key] = value
        elif line[:3] == 'set':
            key, value = _extract_prop_set(line)
            sets[key] = value
        else:
            key, value = _extract_prop_general(line)
            general[key] = value
    return (general, options, sets)

def order_by_refs(envs):
    """Return topologicaly sorted list of environments.
    I.e. all referenced environments are placed before their references."""
    topology = {env['name']: set(env['refs']) for env in envs}
    by_name = {env['name']: env for env in envs}
    return [by_name[name] for name in toposort_flatten(topology)]

def cli(ctx, compatible, forbid_post, generate_hashes, directory, in_ext, out_ext, header, only_name, upgrade):
    """Recompile"""
    logging.basicConfig(level=logging.DEBUG, format='%(message)s')
    OPTIONS.update({'compatible_patterns': compatible, 'forbid_post': set(forbid_post), 'add_hashes': set(generate_hashes), 'base_dir': directory, 'in_ext': in_ext, 'out_ext': out_ext, 'header_file': header or None, 'include_names': only_name, 'upgrade': upgrade})
    if ctx.invoked_subcommand is None:
        recompile()

def parse_hash_comment(file_path):
    """Read file with given file_path line by line,
    return the first line that starts with "# SHA1:", like this:

        # SHA1:da39a3ee5e6b4b0d3255bfef95601890afd80709"""
    with open(file_path) as fp:
        for line in fp:
            if line.startswith('# SHA1:'):
                return line
    return None

def parse_value(key, value):
    """Parse value as comma-delimited list if default value for it is list"""
    default = OPTIONS.get(key)
    if isinstance(default, collections.Iterable):
        if not isinstance(default, six.string_types):
            return [item.strip() for item in value.split(',')]
    return value

def python_version_matchers():
    """Return set of string representations of current python version"""
    version = sys.version_info
    patterns = ['{0}', '{0}{1}', '{0}.{1}']
    matchers = [pattern.format(*version) for pattern in patterns] + [None]
    return set(matchers)

def skipper(func):
    """Decorator that memorizes base_dir, in_ext and out_ext from OPTIONS
    and skips execution for duplicates."""
    @functools.wraps(func)
    def wrapped():
        """Dummy docstring to make pylint happy."""
        key = (OPTIONS['base_dir'], OPTIONS['in_ext'], OPTIONS['out_ext'])
        if key not in seen:
            seen[key] = func()
        return seen[key]
    seen = {}
    return wrapped

def recompile():
    """Compile requirements files for all environments."""
    pinned_packages = {}
    env_confs = discover(os.path.join(OPTIONS['base_dir'], '*.' + OPTIONS['in_ext']))
    if OPTIONS['header_file']:
        with open(OPTIONS['header_file']) as fp:
            base_header_text = fp.read()
    else:
        base_header_text = DEFAULT_HEADER
    hashed_by_reference = set()
    for name in OPTIONS['add_hashes']:
        hashed_by_reference.update(reference_cluster(env_confs, name))
    included_and_refs = set(OPTIONS['include_names'])
    for name in set(included_and_refs):
        included_and_refs.update(recursive_refs(env_confs, name))
    for conf in env_confs:
        if included_and_refs:
            if conf['name'] not in included_and_refs:
                continue
        rrefs = recursive_refs(env_confs, conf['name'])
        add_hashes = conf['name'] in hashed_by_reference
        env = Environment(name=conf['name'], ignore=merged_packages(pinned_packages, rrefs), forbid_post=conf['name'] in OPTIONS['forbid_post'], add_hashes=add_hashes)
        logger.info('Locking %s to %s. References: %r', env.infile, env.outfile, sorted(rrefs))
        env.create_lockfile()
        header_text = generate_hash_comment(env.infile) + base_header_text
        env.replace_header(header_text)
        env.add_references(conf['refs'])
        pinned_packages[conf['name']] = env.packages

def merged_packages(env_packages, names):
    """Return union set of environment packages with given names

    >>> sorted(merged_packages(
    ...     {
    ...         'a': {'x': 1, 'y': 2},
    ...         'b': {'y': 2, 'z': 3},
    ...         'c': {'z': 3, 'w': 4}
    ...     },
    ...     ['a', 'b']
    ... ).items())
    [('x', 1), ('y', 2), ('z', 3)]"""
    combined_packages = sorted(itertools.chain.from_iterable((env_packages[name].items() for name in names)))
    result = {}
    errors = set()
    for name, version in combined_packages:
        if name in result:
            if result[name] != version:
                errors.add((name, version, result[name]))
        else:
            result[name] = version
    if errors:
        for error in sorted(errors):
            logger.error('Package %s was resolved to different versions in different environments: %s and %s', error[0], error[1], error[2])
        raise RuntimeError('Please add constraints for the package version listed above')
    return result

def recursive_refs(envs, name):
    """Return set of recursive refs for given env name

    >>> local_refs = sorted(recursive_refs([
    ...     {'name': 'base', 'refs': []},
    ...     {'name': 'test', 'refs': ['base']},
    ...     {'name': 'local', 'refs': ['test']},
    ... ], 'local'))
    >>> local_refs == ['base', 'test']
    True"""
    refs_by_name = {env['name']: set(env['refs']) for env in envs}
    refs = refs_by_name[name]
    if refs:
        indirect_refs = set(itertools.chain.from_iterable([recursive_refs(envs, ref) for ref in refs]))
    else:
        indirect_refs = set()
    return set.union(refs, indirect_refs)

def did_parse(did):
    """Parse a DID into it's parts.

    :param did: Asset did, str.
    :return: Python dictionary with the method and the id."""
    if not isinstance(did, str):
        raise TypeError(f'Expecting DID of string type, got {did} of {type(did)} type')
    match = re.match('^did:([a-z0-9]+):([a-zA-Z0-9-.]+)(.*)', did)
    if not match:
        raise ValueError(f'DID {did} does not seem to be valid.')
    result = {'method': match.group(1), 'id': match.group(2)}
    return result

def id_to_did(did_id, method='op'):
    """Return an Ocean DID from given a hex id."""
    if isinstance(did_id, bytes):
        did_id = Web3.toHex(did_id)
    if isinstance(did_id, str):
        did_id = remove_0x_prefix(did_id)
    else:
        raise TypeError('did id must be a hex string or bytes')
    if Web3.toBytes(hexstr=did_id) == b'':
        did_id = '0'
    return f'did:{method}:{did_id}'

def did_to_id_bytes(did):
    """Return an Ocean DID to it's correspondng hex id in bytes.

    So did:op:<hex>, will return <hex> in byte format"""
    if isinstance(did, str):
        if re.match('^[0x]?[0-9A-Za-z]+$', did):
            raise ValueError(f'{did} must be a DID not a hex string')
        else:
            did_result = did_parse(did)
            if not did_result:
                raise ValueError(f'{did} is not a valid did')
            if not did_result['id']:
                raise ValueError(f'{did} is not a valid ocean did')
            id_bytes = Web3.toBytes(hexstr=did_result['id'])
    elif isinstance(did, bytes):
        id_bytes = did
    else:
        raise TypeError(f'Unknown did format, expected str or bytes, got {did} of type {type(did)}')
    return id_bytes

def get_sla_template_path(service_type=ServiceTypes.ASSET_ACCESS):
    """Get the template for a ServiceType.

    :param service_type: ServiceTypes
    :return: Path of the template, str"""
    if service_type == ServiceTypes.ASSET_ACCESS:
        name = 'access_sla_template.json'
    elif service_type == ServiceTypes.CLOUD_COMPUTE:
        name = 'compute_sla_template.json'
    elif service_type == ServiceTypes.FITCHAIN_COMPUTE:
