def has_all_nonzero_segment_lengths(neuron, threshold=0.0):
    """Check presence of neuron segments with length not above threshold

    Arguments:
        neuron(Neuron): The neuron object to test
        threshold(float): value above which a segment length is considered to
        be non-zero

    Returns:
        CheckResult with result including list of (section_id, segment_id)
        of zero length segments"""
    bad_ids = []
    for sec in _nf.iter_sections(neuron):
        p = sec.points
        for i, s in enumerate(zip(p[:-1], p[1:])):
            if segment_length(s) <= threshold:
                bad_ids.append((sec.id, i))
    return CheckResult(len(bad_ids) == 0, bad_ids)

def has_no_dangling_branch(neuron):
    """Check if the neuron has dangling neurites"""
    soma_center = neuron.soma.points[:, COLS.XYZ].mean(axis=0)
    recentered_soma = neuron.soma.points[:, COLS.XYZ] - soma_center
    radius = np.linalg.norm(recentered_soma, axis=1)
    soma_max_radius = radius.max()
    def is_dangling(neurite):
        """Is the neurite dangling ?"""
        starting_point = neurite.points[1][COLS.XYZ]
        if np.linalg.norm(starting_point - soma_center) - soma_max_radius <= 12.0:
            return False
        if neurite.type != NeuriteType.axon:
            return True
        all_points = list(chain.from_iterable((n.points[1:] for n in iter_neurites(neurite) if n.type != NeuriteType.axon)))
        res = [np.linalg.norm(starting_point - p[COLS.XYZ]) >= 2 * p[COLS.R] + 2 for p in all_points]
        return all(res)
    bad_ids = [(n.root_node.id, [n.root_node.points[1]]) for n in iter_neurites(neuron) if is_dangling(n)]
    return CheckResult(len(bad_ids) == 0, bad_ids)

def extract_data(neurons, feature, params=None):
    """Extracts feature from a list of neurons
    and transforms the fitted distribution in the correct format.
    Returns the optimal distribution and corresponding parameters.
    Normal distribution params (mean, std)
    Exponential distribution params (loc, scale)
    Uniform distribution params (min, range)"""
    if params is None:
        params = {}
    feature_data = [get(FEATURE_MAP[feature], n, **params) for n in neurons]
    feature_data = list(chain(*feature_data))
    return stats.optimal_distribution(feature_data)

def parse_args():
    """Parse command line arguments"""
    parser = argparse.ArgumentParser(description='Morphology fit distribution extractor', epilog='Note: Outputs json of the optimal distribution                 and corresponding parameters.')
    parser.add_argument('datapaths', nargs='+', help='Morphology data directory paths')
    parser.add_argument('--mtype', choices=MTYPE_GETTERS.keys(), help='Get mtype from filename or parent directory')
    return parser.parse_args()

def draw(obj, plane='3d', inline=False, **kwargs):
    """Draw the morphology using in the given plane

    plane (str): a string representing the 2D plane (example: 'xy')
                 or '3d', '3D' for a 3D view

    inline (bool): must be set to True for interactive ipython notebook plotting"""
    if plane.lower() == '3d':
        return _plot_neuron3d(obj, inline, **kwargs)
    return _plot_neuron(obj, plane, inline, **kwargs)

def _plot_neuron3d(neuron, inline, **kwargs):
    """Generates a figure of the neuron,
    that contains a soma and a list of trees."""
    return _plotly(neuron, plane='3d', title='neuron-3D', inline=inline, **kwargs)

def _make_trace(neuron, plane):
    """Create the trace to be plotted"""
    for neurite in iter_neurites(neuron):
        segments = list(iter_segments(neurite))
        segs = [(s[0][COLS.XYZ], s[1][COLS.XYZ]) for s in segments]
        coords = dict(x=list(chain.from_iterable(((p1[0], p2[0], None) for p1, p2 in segs))), y=list(chain.from_iterable(((p1[1], p2[1], None) for p1, p2 in segs))), z=list(chain.from_iterable(((p1[2], p2[2], None) for p1, p2 in segs))))
        color = TREE_COLOR.get(neurite.root_node.type, 'black')
        if plane.lower() == '3d':
            plot_fun = go.Scatter3d
        else:
            plot_fun = go.Scatter
            coords = dict(x=coords[plane[0]], y=coords[plane[1]])
        yield plot_fun(line=dict(color=color, width=2), mode='lines', **coords)

def _sin(x):
    """sine with case for pi multiples"""
    return 0.0 if np.isclose(np.mod(x, np.pi), 0.0) else np.sin(x)

