    def _pde(neurite):
        """Get the PDE of a single neurite"""
        points = neurite.points[:, :3]
        return morphmath.principal_direction_extent(points)[direction]
    return map(_pde, iter_neurites(neurites, filt=is_type(neurite_type)))

