def _plane2col(plane):
    """take a string like 'xy', and return the indices from COLS.*"""
    planes = ('xy', 'yx', 'xz', 'zx', 'yz', 'zy')
    assert plane in planes, 'No such plane found! Please select one of: ' + str(planes)
    return (getattr(COLS, plane[0].capitalize()), getattr(COLS, plane[1].capitalize()))

def make_neurites(rdw):
    """Build neurite trees from a raw data wrapper"""
    post_action = _NEURITE_ACTION[rdw.fmt]
    trunks = rdw.neurite_root_section_ids()
    if not trunks:
        return ([], [])
    nodes = tuple((Section(section_id=i, points=rdw.data_block[sec.ids], section_type=_TREE_TYPES[sec.ntype]) for i, sec in enumerate(rdw.sections)))
    for i, node in enumerate(nodes):
        parent_id = rdw.sections[i].pid
        parent_type = nodes[parent_id].type
        if parent_id != ROOT_ID and parent_type != NeuriteType.soma:
            nodes[parent_id].add_child(node)
    neurites = tuple((Neurite(nodes[i]) for i in trunks))
    if post_action is not None:
        for n in neurites:
            post_action(n.root_node)
    return (neurites, nodes)

def _check_soma_topology_swc(points):
    """check if points form valid soma

    Currently checks if there are bifurcations within a soma
    with more than three points."""
    if len(points) == 3:
        return
    parents = tuple((p[COLS.P] for p in points if p[COLS.P] != ROOT_ID))
    if len(parents) > len(set(parents)):
        raise SomaError('Bifurcating soma')

def linear_interpolate(p1, p2, fraction):
    """Returns the point p satisfying: p1 + fraction * (p2 - p1)"""
    return np.array((p1[0] + fraction * (p2[0] - p1[0]), p1[1] + fraction * (p2[1] - p1[1]), p1[2] + fraction * (p2[2] - p1[2])))

def polygon_diameter(points):
    """Compute the maximun euclidian distance between any two points
    in a list of points"""
    return max((point_dist(p0, p1) for p0, p1 in combinations(points, 2)))

def path_distance(points):
    """Compute the path distance from given set of points"""
    vecs = np.diff(points, axis=0)[:, :3]
    d2 = [np.dot(p, p) for p in vecs]
    return np.sum(np.sqrt(d2))

def plot_feature(feature, cell):
    """Plot a feature
    """
    fig = pl.figure()
    ax = fig.add_subplot(111)
    if cell is not None:
        try:
            histogram(cell, feature, ax)
        except ValueError:
            pass
        stylize(ax, cell.name, feature)
    return fig

def path_end_to_end_distance(neurite):
    """Calculate and return end-to-end-distance of a given neurite."""
    trunk = neurite.root_node.points[0]
    return max((morphmath.point_dist(l.points[-1], trunk) for l in neurite.root_node.ileaf()))

def calculate_and_plot_end_to_end_distance(neurite):
    """Calculate and plot the end-to-end distance vs the number of segments for
    an increasingly larger part of a given neurite.

    Note that the plots are not very meaningful for bifurcating trees."""
    def _dist(seg):
        """Distance between segmenr end and trunk"""
        return morphmath.point_dist(seg[1], neurite.root_node.points[0])
    end_to_end_distance = [_dist(s) for s in nm.iter_segments(neurite)]
    make_end_to_end_distance_plot(np.arange(len(end_to_end_distance)) + 1, end_to_end_distance, neurite.type)

def dendrite_filter(n):
    """Select only dendrites"""
    return n.type == NeuriteType.basal_dendrite or n.type == NeuriteType.apical_dendrite

def _max_recursion_depth(obj):
    """Estimate recursion depth, which is defined as the number of nodes in a tree
    """
    neurites = obj.neurites if hasattr(obj, 'neurites') else [obj]
    return max((sum((1 for _ in neu.iter_sections())) for neu in neurites))

def _total_rectangles(tree):
    """Calculate the total number of segments that are required
    for the dendrogram. There is a vertical line for each segment
    and two horizontal line at each branching point"""
    return sum((len(sec.children) + sec.points.shape[0] - 1 for sec in tree.iter_sections()))

def _n_rectangles(obj):
    """Calculate the total number of rectangles with respect to
    the type of the object"""
    return sum((_total_rectangles(neu) for neu in obj.neurites)) if hasattr(obj, 'neurites') else _total_rectangles(obj)

def _square_segment(radius, origin):
    """Vertices for a square
    """
    return np.array(((origin[0] - radius, origin[1] - radius), (origin[0] - radius, origin[1] + radius), (origin[0] + radius, origin[1] + radius), (origin[0] + radius, origin[1] - radius)))

def _vertical_segment(old_offs, new_offs, spacing, radii):
    """Vertices for a vertical rectangle
    """
    return np.array(((new_offs[0] - radii[0], old_offs[1] + spacing[1]), (new_offs[0] - radii[1], new_offs[1]), (new_offs[0] + radii[1], new_offs[1]), (new_offs[0] + radii[0], old_offs[1] + spacing[1])))

def _horizontal_segment(old_offs, new_offs, spacing, diameter):
    """Vertices of a horizontal rectangle
    """
    return np.array(((old_offs[0], old_offs[1] + spacing[1]), (new_offs[0], old_offs[1] + spacing[1]), (new_offs[0], old_offs[1] + spacing[1] - diameter), (old_offs[0], old_offs[1] + spacing[1] - diameter)))

def _update_offsets(start_x, spacing, terminations, offsets, length):
    """Update the offsets
    """
    return (start_x + spacing[0] * terminations / 2.0, offsets[1] + spacing[1] * 2.0 + length)

def _max_diameter(tree):
    """Find max diameter in tree
    """
    return 2.0 * max((max(node.points[:, COLS.R]) for node in tree.ipreorder()))

def register_neurite_feature(name, func):
    """Register a feature to be applied to neurites

    Parameters:
        name: name of the feature, used for access via get() function.
        func: single parameter function of a neurite."""
    if name in NEURITEFEATURES:
        raise NeuroMError('Attempt to hide registered feature %s' % name)
    def _fun(neurites, neurite_type=_ntype.all):
        """Wrap neurite function from outer scope and map into list"""
        return list((func(n) for n in _ineurites(neurites, filt=_is_type(neurite_type))))
    NEURONFEATURES[name] = _fun

def _indent(string, count):
    """indent `string` by `count` * INDENT"""
    indent = _INDENT * count
    ret = indent + string.replace('\n', '\n' + indent)
    return ret.rstrip()

def _get_doc():
    """Get a description of all the known available features"""
    def get_docstring(func):
        """extract doctstring, if possible"""
        docstring = ':\n'
        if func.__doc__:
            docstring += _indent(func.__doc__, 2)
        return docstring
    ret = ['\nNeurite features (neurite, neuron, neuron population):']
    ret.extend((_INDENT + '- ' + feature + get_docstring(func) for feature, func in sorted(NEURITEFEATURES.items())))
    ret.append('\nNeuron features (neuron, neuron population):')
    ret.extend((_INDENT + '- ' + feature + get_docstring(func) for feature, func in sorted(NEURONFEATURES.items())))
    return '\n'.join(ret)

def _unpack_v1(h5file):
    """Unpack groups from HDF5 v1 file"""
    points = np.array(h5file['points'])
    groups = np.array(h5file['structure'])
    return (points, groups)

def graft_neuron(root_section):
    """Returns a neuron starting at root_section"""
    assert isinstance(root_section, Section)
    return Neuron(soma=Soma(root_section.points[:1]), neurites=[Neurite(root_section)])

def eval_stats(values, mode):
    """Extract a summary statistic from an array of list of values

    Parameters:
        values: numpy array of values
        mode: summary stat to extract. One of ['min', 'max', 'median', 'mean', 'std', 'raw']

    Note: fails silently if values is empty, and None is returned"""
    if mode == 'raw':
        return values.tolist()
    if mode == 'total':
        mode = 'sum'
    try:
        return getattr(np, mode)(values, axis=0)
    except ValueError:
        pass
    return None

def _stat_name(feat_name, stat_mode):
    """Set stat name based on feature name and stat mode"""
    if feat_name[-1] == 's':
        feat_name = feat_name[:-1]
    if feat_name == 'soma_radii':
        feat_name = 'soma_radius'
    if stat_mode == 'raw':
        return feat_name
    return '%s_%s' % (stat_mode, feat_name)

def extract_stats(neurons, config):
    """Extract stats from neurons"""
    stats = defaultdict(dict)
    for ns, modes in config['neurite'].items():
        for n in config['neurite_type']:
            n = _NEURITE_MAP[n]
            for mode in modes:
                stat_name = _stat_name(ns, mode)
                stat = eval_stats(nm.get(ns, neurons, neurite_type=n), mode)
                if stat is None or not stat.shape:
                    stats[n.name][stat_name] = stat
                else:
                    assert stat.shape in ((3,),), 'Statistic must create a 1x3 result'
                    for i, suffix in enumerate('XYZ'):
                        compound_stat_name = stat_name + '_' + suffix
                        stats[n.name][compound_stat_name] = stat[i]
    for ns, modes in config['neuron'].items():
        for mode in modes:
            stat_name = _stat_name(ns, mode)
            stats[stat_name] = eval_stats(nm.get(ns, neurons), mode)
    return stats

def get_header(results):
    """Extracts the headers, using the first value in the dict as the template"""
    ret = ['name']
    values = next(iter(results.values()))
    for k, v in values.items():
        if isinstance(v, dict):
            for metric in v.keys():
                ret.append('%s:%s' % (k, metric))
        else:
            ret.append(k)
    return ret

def generate_flattened_dict(headers, results):
    """extract from results the fields in the headers list"""
    for name, values in results.items():
        row = []
        for header in headers:
            if header == 'name':
                row.append(name)
            elif ':' in header:
                neurite_type, metric = header.split(':')
                row.append(values[neurite_type][metric])
            else:
                row.append(values[header])
        yield row

def deprecated(fun_name=None, msg=''):
    """Issue a deprecation warning for a function"""
    def _deprecated(fun):
        """Issue a deprecation warning for a function"""
        @wraps(fun)
        def _wrapper(*args, **kwargs):
            """Issue deprecation warning and forward arguments to fun"""
            name = fun_name if fun_name is not None else fun.__name__
            _warn_deprecated('Call to deprecated function %s. %s' % (name, msg))
            return fun(*args, **kwargs)
        return _wrapper
    return _deprecated

def check_wrapper(fun):
    """Decorate a checking function"""
    @wraps(fun)
    def _wrapper(*args, **kwargs):
        """Sets the title property of the result of running a checker"""
        title = fun.__name__.replace('_', ' ').capitalize()
        result = fun(*args, **kwargs)
        result.title = title
        return result
    return _wrapper

def read(filename, data_wrapper=DataWrapper):
    """Read an SWC file and return a tuple of data, format."""
    data = np.loadtxt(filename)
    if len(np.shape(data)) == 1:
        data = np.reshape(data, (1, -1))
    data = data[:, [X, Y, Z, R, TYPE, ID, P]]
    return data_wrapper(data, 'SWC', None)

def _is_morphology_file(filepath):
    """Check if `filepath` is a file with one of morphology file extensions."""
    return os.path.isfile(filepath) and os.path.splitext(filepath)[1].lower() in ('.swc', '.h5', '.asc')

def get_morph_files(directory):
    """Get a list of all morphology files in a directory

    Returns:
        list with all files with extensions '.swc' , 'h5' or '.asc' (case insensitive)"""
    lsdir = (os.path.join(directory, m) for m in os.listdir(directory))
    return list(filter(_is_morphology_file, lsdir))

def get_files_by_path(path):
    """Get a file or set of files from a file path

    Return list of files with path"""
    if os.path.isfile(path):
        return [path]
    if os.path.isdir(path):
        return get_morph_files(path)
    raise IOError('Invalid data path %s' % path)

def load_neuron(handle, reader=None):
    """Build section trees from an h5 or swc file"""
    rdw = load_data(handle, reader)
    if isinstance(handle, StringType):
        name = os.path.splitext(os.path.basename(handle))[0]
    else:
        name = None
    return FstNeuron(rdw, name)

def load_neurons(neurons, neuron_loader=load_neuron, name=None, population_class=Population, ignored_exceptions=()):
    """Create a population object from all morphologies in a directory        of from morphologies in a list of file names

    Parameters:
        neurons: directory path or list of neuron file paths
        neuron_loader: function taking a filename and returning a neuron
        population_class: class representing populations
        name (str): optional name of population. By default 'Population' or            filepath basename depending on whether neurons is list or            directory path respectively.

    Returns:
        neuron population object"""
    if isinstance(neurons, (list, tuple)):
        files = neurons
        name = name if name is not None else 'Population'
    elif isinstance(neurons, StringType):
        files = get_files_by_path(neurons)
        name = name if name is not None else os.path.basename(neurons)
    ignored_exceptions = tuple(ignored_exceptions)
    pop = []
    for f in files:
        try:
            pop.append(neuron_loader(f))
        except NeuroMError as e:
            if isinstance(e, ignored_exceptions):
                L.info('Ignoring exception "%s" for file %s', e, os.path.basename(f))
                continue
            raise
    return population_class(pop, name=name)

def load_data(handle, reader=None):
    """Unpack data into a raw data wrapper"""
    if not reader:
        reader = os.path.splitext(handle)[1][1:].lower()
    if reader not in _READERS:
        raise NeuroMError('Do not have a loader for "%s" extension' % reader)
    filename = _get_file(handle)
    try:
        return _READERS[reader](filename)
    except Exception as e:
        L.exception('Error reading file %s, using "%s" loader', filename, reader)
        raise RawDataError('Error reading file %s:\n%s' % (filename, str(e)))

def _load_h5(filename):
    """Delay loading of h5py until it is needed"""
    from neurom.io import hdf5
    return hdf5.read(filename, remove_duplicates=False, data_wrapper=DataWrapper)

def population_feature_values(pops, feature):
    """Extracts feature values per population
    """
    pops_feature_values = []
    for pop in pops:
        feature_values = [getattr(neu, 'get_' + feature)() for neu in pop.neurons]
        if any([isinstance(p, (list, np.ndarray)) for p in feature_values]):
            feature_values = list(chain(*feature_values))
        pops_feature_values.append(feature_values)
    return pops_feature_values

def _get_tokens(morph_fd):
    """split a file-like into tokens: split on whitespace

    Note: this also strips newlines and comments"""
    for line in morph_fd:
        line = line.rstrip()
        line = line.split(';', 1)[0]
        squash_token = []
        if '<(' in line:
            assert ')>' in line, 'Missing end of spine'
            continue
        for token in line.replace('(', ' ( ').replace(')', ' ) ').split():
            if squash_token:
                squash_token.append(token)
                if token.endswith('"'):
                    token = ' '.join(squash_token)
                    squash_token = []
                    yield token
            elif token.startswith('"') and (not token.endswith('"')):
                squash_token.append(token)
            else:
                yield token

def _parse_section(token_iter):
    """take a stream of tokens, and create the tree structure that is defined
    by the s-expressions"""
    sexp = []
    for token in token_iter:
        if token == '(':
            new_sexp = _parse_section(token_iter)
            if not _match_section(new_sexp, UNWANTED_SECTIONS):
                sexp.append(new_sexp)
        elif token == ')':
            return sexp
        else:
            sexp.append(token)
    return sexp

def _parse_sections(morph_fd):
    """returns array of all the sections that exist

    The format is nested lists that correspond to the s-expressions"""
    sections = []
    token_iter = _get_tokens(morph_fd)
    for token in token_iter:
        if token == '(':
            section = _parse_section(token_iter)
            if not _match_section(section, UNWANTED_SECTIONS):
                sections.append(section)
    return sections

def stats(data):
    """Dictionary with summary stats for data

    Returns:
        dicitonary with length, mean, sum, standard deviation,            min and max of data"""
    return {'len': len(data), 'mean': np.mean(data), 'sum': np.sum(data), 'std': np.std(data), 'min': np.min(data), 'max': np.max(data)}

