def get_error(response):
    """Gets Error by HTTP Status Code"""
    errors = {400: BadRequestError, 401: UnauthorizedError, 403: AccessDeniedError, 404: NotFoundError, 429: RateLimitExceededError, 500: ServerError, 502: BadGatewayError, 503: ServiceUnavailableError}
    error_class = HTTPError
    if response.status_code in errors:
