    if resources is not None:
        cache_key = '{0}:{1}:{2}'.format(link['sys']['linkType'], link['sys']['id'], locale)
        if cache_key in resources:
            return resources[cache_key]
    for i in includes:
        if i['sys']['id'] == link['sys']['id'] and i['sys']['type'] == link['sys']['linkType']:
            return i
    return None

def all_resource_urls(query):
    """Get all the URLs for every resource"""
    urls = []
    next = True
    while next:
        response = requests.get(query)
        json_data = json.loads(response.content)
        for resource in json_data['results']:
            urls.append(resource['url'])
        if bool(json_data['next']):
            query = json_data['next']
        else:
            next = False
    return urls

