def __remove_alias(type_):
    """Implementation detail.

    Args:
        type_ (type_t): type

    Returns:
        type_t: the type associated to the inputted type"""
    if isinstance(type_, cpptypes.declarated_t) and isinstance(type_.declaration, typedef.typedef_t):
        return __remove_alias(type_.declaration.decl_type)
    if isinstance(type_, cpptypes.compound_t):
        type_.base = __remove_alias(type_.base)
        return type_
    return type_

def decompose_type(tp):
    """Implementation detail"""
    if isinstance(tp, cpptypes.compound_t):
        return [tp] + decompose_type(tp.base)
    elif isinstance(tp, typedef.typedef_t):
        return decompose_type(tp.decl_type)
    elif isinstance(tp, cpptypes.declarated_t) and isinstance(tp.declaration, typedef.typedef_t):
        return decompose_type(tp.declaration.decl_type)
    return [tp]

def _create_cv_types(base):
    """Implementation detail."""
    return [base, cpptypes.const_t(base), cpptypes.volatile_t(base), cpptypes.volatile_t(cpptypes.const_t(base))]

def does_match_definition(given, main, secondary):
    """implementation details"""
    assert isinstance(secondary, tuple)
    assert len(secondary) == 2
    types = decompose_type(given)
    if isinstance(types[0], main):
        return True
    if len(types) >= 2:
        cond1 = isinstance(types[0], main)
        cond2 = isinstance(types[1], secondary)
        cond3 = isinstance(types[1], main)
        cond4 = isinstance(types[0], secondary)
        if cond1 and cond2 or (cond3 and cond4):
            return True
        if len(types) >= 3:
            classes = set([tp.__class__ for tp in types[:3]])
            desired = set([main] + list(secondary))
            diff = classes.symmetric_difference(desired)
            if not diff:
                return True
            if len(diff) == 2:
                items = list(diff)
                return issubclass(items[0], items[1]) or issubclass(items[1], items[0])
            return False
    else:
        return False

def is_pointer(type_):
    """returns True, if type represents C++ pointer type, False otherwise"""
    return does_match_definition(type_, cpptypes.pointer_t, (cpptypes.const_t, cpptypes.volatile_t)) or does_match_definition(type_, cpptypes.pointer_t, (cpptypes.volatile_t, cpptypes.const_t))

def is_calldef_pointer(type_):
    """returns True, if type represents pointer to free/member function,
    False otherwise"""
    if not is_pointer(type_):
        return False
    nake_type = remove_alias(type_)
    nake_type = remove_cv(nake_type)
    return isinstance(nake_type, cpptypes.compound_t) and isinstance(nake_type.base, cpptypes.calldef_type_t)

def remove_pointer(type_):
    """removes pointer from the type definition

    If type is not pointer type, it will be returned as is."""
    nake_type = remove_alias(type_)
    if not is_pointer(nake_type):
        return type_
    elif isinstance(nake_type, cpptypes.volatile_t) and isinstance(nake_type.base, cpptypes.pointer_t):
        return cpptypes.volatile_t(nake_type.base.base)
    elif isinstance(nake_type, cpptypes.const_t) and isinstance(nake_type.base, cpptypes.pointer_t):
        return cpptypes.const_t(nake_type.base.base)
    elif isinstance(nake_type, cpptypes.volatile_t) and isinstance(nake_type.base, cpptypes.const_t) and isinstance(nake_type.base.base, cpptypes.pointer_t):
        return cpptypes.volatile_t(cpptypes.const_t(nake_type.base.base.base))
    return nake_type.base

def is_array(type_):
    """returns True, if type represents C++ array type, False otherwise"""
    nake_type = remove_alias(type_)
    nake_type = remove_reference(nake_type)
    nake_type = remove_cv(nake_type)
    return isinstance(nake_type, cpptypes.array_t)

def array_item_type(type_):
    """returns array item type"""
    if is_array(type_):
        type_ = remove_alias(type_)
        type_ = remove_cv(type_)
        return type_.base
    elif is_pointer(type_):
        return remove_pointer(type_)
    else:
        raise RuntimeError('array_item_type functions takes as argument array or pointer ' + 'types')

def remove_const(type_):
    """removes const from the type definition

    If type is not const type, it will be returned as is"""
    nake_type = remove_alias(type_)
    if not is_const(nake_type):
        return type_
    else:
        if isinstance(nake_type, cpptypes.array_t):
            is_v = is_volatile(nake_type)
            if is_v:
                result_type = nake_type.base.base.base
            else:
                result_type = nake_type.base.base
            if is_v:
                result_type = cpptypes.volatile_t(result_type)
            return cpptypes.array_t(result_type, nake_type.size)
        elif isinstance(nake_type, cpptypes.volatile_t):
            return cpptypes.volatile_t(nake_type.base.base)
        return nake_type.base

def remove_declarated(type_):
    """removes type-declaration class-binder :class:`declarated_t` from
    the `type_`

    If `type_` is not :class:`declarated_t`, it will be returned as is"""
    type_ = remove_alias(type_)
    if isinstance(type_, cpptypes.elaborated_t):
        type_ = type_.base
    if isinstance(type_, cpptypes.declarated_t):
        type_ = type_.declaration
    return type_

def is_elaborated(type_):
    """returns True, if type represents C++ elaborated type, False otherwise"""
    nake_type = remove_alias(type_)
    if isinstance(nake_type, cpptypes.elaborated_t):
        return True
    elif isinstance(nake_type, cpptypes.reference_t):
        return is_elaborated(nake_type.base)
    elif isinstance(nake_type, cpptypes.pointer_t):
        return is_elaborated(nake_type.base)
    elif isinstance(nake_type, cpptypes.volatile_t):
        return is_elaborated(nake_type.base)
    elif isinstance(nake_type, cpptypes.const_t):
        return is_elaborated(nake_type.base)
    return False

def remove_elaborated(type_):
    """removes type-declaration class-binder :class:`elaborated_t` from
    the `type_`

    If `type_` is not :class:`elaborated_t`, it will be returned as is"""
    nake_type = remove_alias(type_)
    if not is_elaborated(nake_type):
        return type_
    elif isinstance(type_, cpptypes.elaborated_t):
        type_ = type_.base
    return type_

def is_volatile(type_):
    """returns True, if type represents C++ volatile type, False otherwise"""
    nake_type = remove_alias(type_)
    if isinstance(nake_type, cpptypes.volatile_t):
        return True
    elif isinstance(nake_type, cpptypes.const_t):
        return is_volatile(nake_type.base)
    elif isinstance(nake_type, cpptypes.array_t):
        return is_volatile(nake_type.base)
    return False

def remove_volatile(type_):
    """removes volatile from the type definition

    If type is not volatile type, it will be returned as is"""
    nake_type = remove_alias(type_)
    if not is_volatile(nake_type):
        return type_
    else:
        if isinstance(nake_type, cpptypes.array_t):
            is_c = is_const(nake_type)
            if is_c:
                base_type_ = nake_type.base.base.base
            else:
                base_type_ = nake_type.base.base
            result_type = base_type_
            if is_c:
                result_type = cpptypes.const_t(result_type)
            return cpptypes.array_t(result_type, nake_type.size)
        return nake_type.base

def remove_cv(type_):
    """removes const and volatile from the type definition"""
    nake_type = remove_alias(type_)
    if not is_const(nake_type) and (not is_volatile(nake_type)):
        return type_
    result = nake_type
    if is_const(result):
        result = remove_const(result)
    if is_volatile(result):
        result = remove_volatile(result)
    if is_const(result):
        result = remove_const(result)
    return result

def is_fundamental(type_):
    """returns True, if type represents C++ fundamental type"""
    return does_match_definition(type_, cpptypes.fundamental_t, (cpptypes.const_t, cpptypes.volatile_t)) or does_match_definition(type_, cpptypes.fundamental_t, (cpptypes.volatile_t, cpptypes.const_t))

def _search_in_bases(type_):
    """Implementation detail."""
    found = False
    for base_type in type_.declaration.bases:
        try:
            found = internal_type_traits.get_by_name(base_type.related_class, 'element_type')
        except runtime_errors.declaration_not_found_t:
            pass
        if found:
            return found
    raise RuntimeError("Unable to find 'element_type' declaration '%s'in type '%s'." % type_.decl_string)

def has_public_assign(class_):
    """returns True, if class has public assign operator, False otherwise"""
    class_ = class_traits.get_declaration(class_)
    decls = class_.member_operators(lambda o: o.symbol == '=' and o.access_type == 'public', recursive=False, allow_empty=True)
    return bool(decls)

def has_vtable(decl_type):
    """True, if class has virtual table, False otherwise"""
    assert isinstance(decl_type, class_declaration.class_t)
    return bool(decl_type.calldefs(lambda f: isinstance(f, calldef_members.member_function_t) and f.virtuality != calldef_types.VIRTUALITY_TYPES.NOT_VIRTUAL, recursive=False, allow_empty=True))

def is_base_and_derived(based, derived):
    """returns True, if there is "base and derived" relationship between
    classes, False otherwise"""
    assert isinstance(based, class_declaration.class_t)
    assert isinstance(derived, (class_declaration.class_t, tuple))
    if isinstance(derived, class_declaration.class_t):
        all_derived = [derived]
    else:
        all_derived = derived
    for derived_cls in all_derived:
        for base_desc in derived_cls.recursive_bases:
            if base_desc.related_class == based:
                return True
    return False

def is_unary_operator(oper):
    """returns True, if operator is unary operator, otherwise False"""
    symbols = ['!', '&', '~', '*', '+', '++', '-', '--']
    if not isinstance(oper, calldef_members.operator_t):
        return False
    if oper.symbol not in symbols:
        return False
    if isinstance(oper, calldef_members.member_operator_t):
        if len(oper.arguments) == 0:
            return True
        elif oper.symbol in ['++', '--'] and isinstance(oper.arguments[0].decl_type, cpptypes.int_t):
            return True
        return False
    if len(oper.arguments) == 1:
        return True
    elif oper.symbol in ['++', '--'] and len(oper.arguments) == 2 and isinstance(oper.arguments[1].decl_type, cpptypes.int_t):
        return True
    return False

def is_binary_operator(oper):
    """returns True, if operator is binary operator, otherwise False"""
    symbols = [',', '()', '[]', '!=', '%', '%=', '&', '&&', '&=', '*', '*=', '+', '+=', '-', '-=', '->', '->*', '/', '/=', '<', '<<', '<<=', '<=', '=', '==', '>', '>=', '>>', '>>=', '^', '^=', '|', '|=', '||']
    if not isinstance(oper, calldef_members.operator_t):
        return False
    if oper.symbol not in symbols:
        return False
    if isinstance(oper, calldef_members.member_operator_t):
        if len(oper.arguments) == 1:
            return True
        return False
    if len(oper.arguments) == 2:
        return True
    return False

def is_copy_constructor(constructor):
    """Check if the declaration is a copy constructor,

    Args:
        constructor (declarations.constructor_t): the constructor
            to be checked.

    Returns:
        bool: True if this is a copy constructor, False instead."""
    assert isinstance(constructor, calldef_members.constructor_t)
    args = constructor.arguments
    parent = constructor.parent
    if len(args) != 1:
        return False
    arg = args[0]
    if not isinstance(arg.decl_type, cpptypes.compound_t):
        return False
    if not type_traits.is_reference(arg.decl_type):
        return False
    if not type_traits.is_const(arg.decl_type.base):
        return False
    un_aliased = type_traits.remove_alias(arg.decl_type.base)
    if not isinstance(un_aliased.base, cpptypes.declarated_t):
        return False
    return id(un_aliased.base.declaration) == id(parent)

def fix_calldef_decls(decls, enums, cxx_std):
    """some times gccxml report typedefs defined in no namespace
    it happens for example in next situation
    template< typename X>
    void ddd(){ typedef typename X::Y YY;}
    if I will fail on this bug next time, the right way to fix it may be
    different"""
    default_arg_patcher = default_argument_patcher_t(enums, cxx_std)
    for decl in decls:
        default_arg_patcher(decl)
        if isinstance(decl, declarations.casting_operator_t):
            _casting_oper_patcher_(decl)

def get_dependencies_from_decl(decl, recursive=True):
    """Returns the list of all types and declarations the declaration depends on."""
    result = []
    if isinstance(decl, typedef.typedef_t) or isinstance(decl, variable.variable_t):
        return [dependency_info_t(decl, decl.decl_type)]
    if isinstance(decl, namespace.namespace_t):
        if recursive:
            for d in decl.declarations:
                result.extend(get_dependencies_from_decl(d))
        return result
    if isinstance(decl, calldef.calldef_t):
        if decl.return_type:
            result.append(dependency_info_t(decl, decl.return_type, hint='return type'))
        for arg in decl.arguments:
            result.append(dependency_info_t(decl, arg.decl_type))
        for exc in decl.exceptions:
            result.append(dependency_info_t(decl, exc, hint='exception'))
        return result
    if isinstance(decl, class_declaration.class_t):
        for base in decl.bases:
            result.append(dependency_info_t(decl, base.related_class, base.access_type, 'base class'))
        if recursive:
            for access_type in class_declaration.ACCESS_TYPES.ALL:
                result.extend(__find_out_member_dependencies(decl.get_members(access_type), access_type))
        return result
    return result

def find_container_traits(cls_or_string):
    """Find the container traits type of a declaration.

    Args:
        cls_or_string (str | declarations.declaration_t): a string

    Returns:
        declarations.container_traits: a container traits"""
    if utils.is_str(cls_or_string):
        if not templates.is_instantiation(cls_or_string):
            return None
        name = templates.name(cls_or_string)
        if name.startswith('std::'):
            name = name[len('std::'):]
        if name.startswith('std::tr1::'):
            name = name[len('std::tr1::'):]
        for cls_traits in all_container_traits:
            if cls_traits.name() == name:
                return cls_traits
    else:
        if isinstance(cls_or_string, class_declaration.class_types):
            if cls_or_string.cache.container_traits is not None:
                return cls_or_string.cache.container_traits
        for cls_traits in all_container_traits:
            if cls_traits.is_my_case(cls_or_string):
                if isinstance(cls_or_string, class_declaration.class_types):
                    cls_or_string.cache.container_traits = cls_traits
                return cls_traits

def is_same_function(f1, f2):
    """returns true if f1 and f2 is same function

    Use case: sometimes when user defines some virtual function in base class,
    it overrides it in a derived one. Sometimes we need to know whether two
    member functions is actually same function."""
    if f1 is f2:
        return True
    if f1.__class__ is not f2.__class__:
        return False
    if isinstance(f1, calldef_members.member_calldef_t) and f1.has_const != f2.has_const:
        return False
    if f1.name != f2.name:
        return False
    if not is_same_return_type(f1, f2):
        return False
    if len(f1.arguments) != len(f2.arguments):
        return False
    for f1_arg, f2_arg in zip(f1.arguments, f2.arguments):
        if not type_traits.is_same(f1_arg.decl_type, f2_arg.decl_type):
            return False
    return True

def make_flatten(decl_or_decls):
    """Converts tree representation of declarations to flatten one.

    :param decl_or_decls: reference to list of declaration's or single
        declaration
    :type decl_or_decls: :class:`declaration_t` or [ :class:`declaration_t` ]
    :rtype: [ all internal declarations ]"""
    def proceed_single(decl):
        answer = [decl]
        if not isinstance(decl, scopedef_t):
            return answer
        for elem in decl.declarations:
            if isinstance(elem, scopedef_t):
                answer.extend(proceed_single(elem))
            else:
                answer.append(elem)
        return answer
    decls = []
    if isinstance(decl_or_decls, list):
        decls.extend(decl_or_decls)
    else:
        decls.append(decl_or_decls)
    answer = []
    for decl in decls:
        answer.extend(proceed_single(decl))
    return answer

def find_all_declarations(declarations, decl_type=None, name=None, parent=None, recursive=True, fullname=None):
    """Returns a list of all declarations that match criteria, defined by
    developer.

    For more information about arguments see :class:`match_declaration_t`
    class.

    :rtype: [ matched declarations ]"""
    if recursive:
        decls = make_flatten(declarations)
    else:
        decls = declarations
    return list(filter(algorithm.match_declaration_t(decl_type=decl_type, name=name, fullname=fullname, parent=parent), decls))

def find_first_declaration(declarations, decl_type=None, name=None, parent=None, recursive=True, fullname=None):
    """Returns first declaration that match criteria, defined by developer.

    For more information about arguments see :class:`match_declaration_t`
    class.

    :rtype: matched declaration :class:`declaration_t` or None"""
    decl_matcher = algorithm.match_declaration_t(decl_type=decl_type, name=name, fullname=fullname, parent=parent)
    if recursive:
        decls = make_flatten(declarations)
    else:
        decls = declarations
    for decl in decls:
        if decl_matcher(decl):
            return decl
    return None

def full_name(decl, with_defaults=True):
    """Returns declaration full qualified name.

    If `decl` belongs to anonymous namespace or class, the function will return
    C++ illegal qualified name.

    Args:
        decl (declaration_t): declaration for which the full qualified name
                              should be calculated.

    Returns:
        list[(str | basestring)]: full name of the declaration."""
    if None is decl:
        raise RuntimeError('Unable to generate full name for None object!')
    if with_defaults:
        if not decl.cache.full_name:
            path = declaration_path(decl)
            if path == ['']:
                decl.cache.full_name = ''
            else:
                decl.cache.full_name = full_name_from_declaration_path(path)
        return decl.cache.full_name
    else:
        if not decl.cache.full_partial_name:
            path = partial_declaration_path(decl)
            if path == ['']:
                decl.cache.full_partial_name = ''
            else:
                decl.cache.full_partial_name = full_name_from_declaration_path(path)
        return decl.cache.full_partial_name

def apply_visitor(visitor, decl_inst):
    """Applies a visitor on declaration instance.

    :param visitor: instance
    :type visitor: :class:`type_visitor_t` or :class:`decl_visitor_t`"""
    fname = 'visit_' + decl_inst.__class__.__name__[:-2]
    if not hasattr(visitor, fname):
        raise runtime_errors.visit_function_has_not_been_found_t(visitor, decl_inst)
    return getattr(visitor, fname)()

def file_signature(filename):
    """Return a signature for a file."""
    if not os.path.isfile(filename):
        return None
    if not os.path.exists(filename):
        return None
    sig = hashlib.sha1()
    with open(filename, 'rb') as f:
        buf = f.read()
        sig.update(buf)
    return sig.hexdigest()

def configuration_signature(config):
    """Return a signature for a configuration (xml_generator_configuration_t)
    object.

    This can then be used as a key in the cache.
    This method must take into account anything about
    a configuration that could cause the declarations generated
    to be different between runs."""
    sig = hashlib.sha1()
    if isinstance(config, cxx_parsers_cfg.xml_generator_configuration_t):
        sig.update(str(config.xml_generator_path).encode())
    sig.update(str(config.working_directory).encode('utf-8'))
    if isinstance(config, cxx_parsers_cfg.xml_generator_configuration_t):
        sig.update(str(config.cflags).encode('utf-8'))
    for p in config.include_paths:
        sig.update(str(p).encode('utf-8'))
    for s in config.define_symbols:
        sig.update(str(s).encode('utf-8'))
    for u in config.undefine_symbols:
        sig.update(str(u).encode('utf-8'))
    return sig.hexdigest()

