def set_blocking(fd, blocking=True):
    """Set the given file-descriptor blocking or non-blocking.

    Returns the original blocking status."""
    old_flag = fcntl.fcntl(fd, fcntl.F_GETFL)
    if blocking:
        new_flag = old_flag & ~os.O_NONBLOCK
    else:
        new_flag = old_flag | os.O_NONBLOCK
    fcntl.fcntl(fd, fcntl.F_SETFL, new_flag)
    return not bool(old_flag & os.O_NONBLOCK)

def select(read_streams, write_streams, timeout=0):
    """Select the streams from `read_streams` that are ready for reading, and
    streams from `write_streams` ready for writing.

    Uses `select.select()` internally but only returns two lists of ready streams."""
    exception_streams = []
    try:
        return builtin_select.select(read_streams, write_streams, exception_streams, timeout)[0:2]
    except builtin_select.error as e:
        no = e.errno if six.PY3 else e[0]
        if no == errno.EINTR:
            return ([], [])
        else:
            raise e

def size(fd):
    """Return a tuple (rows,cols) representing the size of the TTY `fd`.

    The provided file descriptor should be the stdout stream of the TTY.

    If the TTY size cannot be determined, returns None."""
    if not os.isatty(fd.fileno()):
        return None
    try:
        dims = struct.unpack('hh', fcntl.ioctl(fd, termios.TIOCGWINSZ, 'hhhh'))
    except:
        try:
            dims = (os.environ['LINES'], os.environ['COLUMNS'])
        except:
            return None
    return dims

def _determine_datatype(fields):
    """Determine the numpy dtype of the data."""
    np_typestring = _TYPEMAP_NRRD2NUMPY[fields['type']]
    if np.dtype(np_typestring).itemsize > 1 and fields['encoding'] not in ['ASCII', 'ascii', 'text', 'txt']:
        if 'endian' not in fields:
            raise NRRDError('Header is missing required field: "endian".')
        elif fields['endian'] == 'big':
            np_typestring = '>' + np_typestring
        elif fields['endian'] == 'little':
            np_typestring = '<' + np_typestring
        else:
            raise NRRDError('Invalid endian value in header: "%s"' % fields['endian'])
    return np.dtype(np_typestring)

def get_prep_lookup(self):
    """Raise errors for unsupported lookups"""
    raise FieldError("{} '{}' does not support lookups".format(self.lhs.field.__class__.__name__, self.lookup_name))

def derive_fernet_key(input_key):
    """Derive a 32-bit b64-encoded Fernet key from arbitrary input key."""
    hkdf = HKDF(algorithm=hashes.SHA256(), length=32, salt=salt, info=info, backend=backend)
    return base64.urlsafe_b64encode(hkdf.derive(force_bytes(input_key)))

def reduce_cpu(f, x, axes, dtype):
    """NumPy's reduce in terms of fold."""
    axes = _get_axes(axes, x.ndim)
    if not axes:
        return x
    permute = [n for n in range(x.ndim) if n not in axes]
    permute = axes + permute
    T = x.transpose(permute=permute)
    N = len(axes)
    t = T.type.at(N, dtype=dtype)
    acc = x.empty(t, device=x.device)
    if f.identity is not None:
        _copyto(acc, f.identity)
        tl = T
    elif N == 1 and T.type.shape[0] > 0:
        hd, tl = (T[0], T[1:])
        acc[()] = hd
    else:
        raise ValueError('reduction not possible for function without an identity element')
    return fold(f, acc, tl)

def reduce_cuda(g, x, axes, dtype):
    """Reductions in CUDA use the thrust library for speed and have limited
    functionality."""
    if axes != 0:
        raise NotImplementedError("'axes' keyword is not implemented for CUDA")
    return g(x, dtype=dtype)

def maxlevel(lst):
    """Return maximum nesting depth"""
    maxlev = 0
    def f(lst, level):
        nonlocal maxlev
        if isinstance(lst, list):
            level += 1
            maxlev = max(level, maxlev)
            for item in lst:
                f(item, level)
    f(lst, 0)
    return maxlev

def getitem(lst, indices):
    """Definition for multidimensional slicing and indexing on arbitrarily
    shaped nested lists."""
    if not indices:
        return lst
    i, indices = (indices[0], indices[1:])
    item = list.__getitem__(lst, i)
    if isinstance(i, int):
        return getitem(item, indices)
    if not item:
        if lst:
            _ = getitem(lst, (slice(None),) + indices)
        elif any((isinstance(k, int) for k in indices)):
            raise IndexError
        return []
    return [getitem(x, indices) for x in item]

def genslices(n):
    """Generate all possible slices for a single dimension."""
    def range_with_none():
        yield None
        yield from range(-n, n + 1)
    for t in product(range_with_none(), range_with_none(), range_with_none()):
        s = slice(*t)
        if s.step != 0:
            yield s

def best_archiver(random, population, archive, args):
    """Archive only the best individual(s).

    This function archives the best solutions and removes inferior ones.
    If the comparison operators have been overloaded to define Pareto
    preference (as in the ``Pareto`` class), then this archiver will form
    a Pareto archive.

    .. Arguments:
       random -- the random number generator object
       population -- the population of individuals
       archive -- the current archive of individuals
       args -- a dictionary of keyword arguments"""
    new_archive = archive
    for ind in population:
        if len(new_archive) == 0:
            new_archive.append(ind)
        else:
            should_remove = []
            should_add = True
            for a in new_archive:
                if ind.candidate == a.candidate:
                    should_add = False
                    break
                elif ind < a:
                    should_add = False
                elif ind > a:
                    should_remove.append(a)
            for r in should_remove:
                new_archive.remove(r)
            if should_add:
                new_archive.append(ind)
    return new_archive

def acceleration_of_satellite(position, mass):
    """Returns the acceleration based on all forces acting upon the body."""
    F_x, F_y = force_on_satellite(position, mass)
    return (F_x / mass, F_y / mass)

def paes_replacement(random, population, parents, offspring, args):
    """Replaces population using the Pareto Archived Evolution Strategy method.

    .. Arguments:
       random -- the random number generator object
       population -- the population of individuals
       parents -- the list of parent individuals
       offspring -- the list of offspring individuals
       args -- a dictionary of keyword arguments"""
    archive = args['_ec'].archive
    archiver = args['_ec'].archiver
    survivors = []
    for p, o in zip(parents, offspring):
        if o == p:
            survivors.append(p)
        elif o in archive:
            survivors.append(p)
        elif o > p:
            archive = archiver(random, [o], archive, args)
            survivors.append(o)
        elif o >= p:
            for a in archive:
                if o > a or o < a:
                    break
            if o >= a:
                archive = archiver(random, [o], archive, args)
                if o > a or archiver.grid_population[o.grid_location] <= archiver.grid_population[p.grid_location]:
                    survivors.append(o)
                else:
                    survivors.append(p)
            else:
                survivors.append(p)
        else:
            survivors.append(p)
    return survivors

def allow_ajax(request):
    """Default function to determine whether to show the toolbar on a given page."""
    if request.META.get('REMOTE_ADDR', None) not in settings.INTERNAL_IPS:
        return False
    if toolbar_version < LooseVersion('1.8') and request.get_full_path().startswith(DEBUG_TOOLBAR_URL_PREFIX) and (request.GET.get('panel_id', None) != 'RequestHistoryPanel'):
        return False
    return bool(settings.DEBUG)

def check_arguments(args):
    """Validates the arguments passed through the CLI commands.

    :param args: The arguments passed in the CLI, parsed by the docopt module
    :return: None"""
    projectname_re = re.compile('[^a-zA-Z0-9_]')
    if args['genconfig']:
        if args['--type'] not in ['scraper', 'crawler']:
            raise InvalidType("--type has to be 'scraper' or 'crawler'")
        if args['--selector'] not in ['xpath', 'css']:
            raise InvalidSelector("--selector has to be 'xpath' or 'css'")
    if args['generate'] or args['run']:
        if args['--output_type'] not in ['json', 'csv']:
            raise InvalidOutputType("--output_type has to be 'json' or 'csv'")
    if args['genconfig'] or args['generate'] or args['run']:
        if projectname_re.search(args['<projectname>']) is not None:
            message = '<projectname> should consist of letters, digits or _'
            raise InvalidProjectName(message)
    try:
        if int(args['--levels']) < 1:
            message = '--levels should be greater than, or equal to 1'
            raise InvalidLevels(message)
    except (TypeError, ValueError):
        message = ' '.join(['--levels should be an integer and not of type', '{}'.format(type(args['--levels']))])
        raise InvalidLevels(message)

def form_to_json(form):
    """Takes the form from the POST request in the web interface, and generates the JSON config        file

    :param form: The form from the POST request
    :return: None"""
    config = dict()
    if form['project_name'] == '':
        raise Exception('Project name cannot be empty.')
    if form['selector_type'] not in ['css', 'xpath']:
        raise Exception('Selector type has to css or xpath')
    config['project_name'] = form['project_name']
    config['selector_type'] = form['selector_type']
    config['scraping'] = dict()
    if form['url'] == '':
        raise Exception('URL cannot be empty')
    config['scraping']['url'] = form['url']
    config['scraping']['data'] = list()
    for i in itertools.count(start=1):
        try:
            data = {'field': form['field_' + str(i)], 'selector': form['selector_' + str(i)], 'attr': form['attribute_' + str(i)], 'default': form['default_' + str(i)]}
            config['scraping']['data'].append(data)
        except KeyError:
            break
    with open(os.path.join(os.getcwd(), form['project_name'] + '.json'), 'w') as f:
        json.dump(config, f)
    return

def get_fields(config):
    """Recursive generator that yields the field names in the config file

    :param config: The configuration file that contains the specification of the extractor
    :return: The field names in the config file, through a generator"""
    for data in config['scraping']['data']:
        if data['field'] != '':
            yield data['field']
    if 'next' in config['scraping']:
        for n in config['scraping']['next']:
            for f in get_fields(n):
                yield f

def extract_fieldnames(config):
    """Function to return a list of unique field names from the config file

    :param config: The configuration file that contains the specification of the extractor
    :return: A list of field names from the config file"""
    fields = []
    for x in get_fields(config):
        if x in fields:
            fields.append(x + '_' + str(fields.count(x) + 1))
        else:
            fields.append(x)
    return fields

def _sort_row_col(qubits: Iterator[GridQubit]) -> List[GridQubit]:
    """Sort grid qubits first by row then by column"""
    return sorted(qubits, key=lambda x: (x.row, x.col))

def xmon_to_arc(xmon: XmonDevice) -> Architecture:
    """Generates a :math:`\\mathrm{t|ket}\\rangle` :py:class:`Architecture` object for a Cirq :py:class:`XmonDevice` .

    :param xmon: The device to convert

    :return: The corresponding :math:`\\mathrm{t|ket}\\rangle` :py:class:`Architecture`"""
    nodes = len(xmon.qubits)
    indexed_qubits = _sort_row_col(xmon.qubits)
    pairs = []
    for qb in indexed_qubits:
        neighbours = xmon.neighbors_of(qb)
        forward_neighbours = filter(lambda x: indexed_qubits.index(x) > indexed_qubits.index(qb), neighbours)
        for x in forward_neighbours:
            pairs.append((indexed_qubits.index(qb), indexed_qubits.index(x)))
    return Architecture(pairs, nodes)

def tk_to_pyquil(circ: Circuit) -> Program:
    """   Convert a :math:`\\mathrm{t|ket}\\rangle` :py:class:`Circuit` to a :py:class:`pyquil.Program` .

    :param circ: A circuit to be converted

    :return: The converted circuit"""
    p = Program()
    ro = p.declare('ro', 'BIT', circ.n_qubits())
    grid = circ._int_routing_grid()
    qubits = _grid_to_qubits(grid)
    slices = []
    for s in grid:
        news = set()
        for pair in s:
            if pair[0] > -1:
                news.add(pair[0])
        slices.append(news)
    for s in slices:
        for v in s:
            op = circ._unsigned_to_op(v)
            optype = op.get_type()
            if optype == OpType.Input or optype == OpType.Output:
                continue
            elif optype == OpType.Measure:
                p += Measurement(qubits[v, 0], ro[int(op.get_desc())])
                continue
            try:
                gatetype = _known_quil_gate_rev[optype]
            except KeyError as error:
                raise NotImplementedError('Cannot convert tket Op to pyquil gate: ' + op.get_name()) from error
            params = [p * PI for p in op.get_params()]
            g = Gate(gatetype, params, [qubits[v, port] for port in range(op.get_n_inputs())])
            p += g
    return p

def halt_running():
    """Halts all running servers"""
    vultr = Vultr(API_KEY)
    try:
        serverList = vultr.server.list()
    except VultrError as ex:
        logging.error('VultrError: %s', ex)
    for serverID in serverList:
