def is_url_allowed(url):
    """Return ``True`` if ``url`` is not in ``blacklist``.

    :rtype: bool"""
    blacklist = ['\\.ttf', '\\.woff', 'fonts\\.googleapis\\.com', '\\.png', '\\.jpe?g', '\\.gif', '\\.svg']
    for ft in blacklist:
        if re.search(ft, url):
            return False
    return True

def is_valid_mimetype(response):
    """Return ``True`` if the mimetype is not blacklisted.

    :rtype: bool"""
    blacklist = ['image/']
    mimetype = response.get('mimeType')
    if not mimetype:
        return True
    for bw in blacklist:
        if bw in mimetype:
            return False
    return True

def to_javascript_data(plugins):
    """Return a dictionary with all JavaScript matchers. Quotes are escaped.

    :rtype: dict"""
    def escape(v):
        return re.sub('"', '\\\\"', v)
    def dom_matchers(p):
        dom_matchers = p.get_matchers('dom')
        escaped_dom_matchers = []
        for dm in dom_matchers:
            check_statement, version_statement = dm
            escaped_dom_matchers.append({'check_statement': escape(check_statement), 'version_statement': escape(version_statement or '')})
        return escaped_dom_matchers
    return [{'name': p.name, 'matchers': dom_matchers(p)} for p in plugins.with_dom_matchers()]

def load_plugins():
    """Return the list of plugin instances."""
    loader = _PluginLoader()
    for pkg in PLUGIN_PACKAGES:
        loader.load_plugins(pkg)
    return loader.plugins

def extract_named_group(text, named_group, matchers, return_presence=False):
    """Return ``named_group`` match from ``text`` reached
    by using a matcher from ``matchers``.

    It also supports matching without a ``named_group`` in a matcher,
    which sets ``presence=True``.

    ``presence`` is only returned if ``return_presence=True``."""
    presence = False
    for matcher in matchers:
        if isinstance(matcher, str):
            v = re.search(matcher, text, flags=re.DOTALL)
            if v:
                dict_result = v.groupdict()
                try:
                    return dict_result[named_group]
                except KeyError:
                    if dict_result:
                        continue
                    else:
                        presence = True
        elif callable(matcher):
            v = matcher(text)
            if v:
                return v
    if return_presence and presence:
        return 'presence'
    return None

def find_all(soup, name=None, attrs=None, recursive=True, text=None, limit=None, **kwargs):
    """The `find` and `find_all` methods of `BeautifulSoup` don't handle the
    `text` parameter combined with other parameters. This is necessary for
    e.g. finding links containing a string or pattern. This method first
    searches by text content, and then by the standard BeautifulSoup arguments."""
    if text is None:
        return soup.find_all(name, attrs or {}, recursive, text, limit, **kwargs)
    if isinstance(text, string_types):
        text = re.compile(re.escape(text), re.I)
    tags = soup.find_all(name, attrs or {}, recursive, **kwargs)
    rv = []
    for tag in tags:
        if match_text(text, tag):
            rv.append(tag)
        if limit is not None and len(rv) >= limit:
            break
    return rv

def ensure_soup(value, parser=None):
    """Coerce a value (or list of values) to Tag (or list of Tag).

    :param value: String, BeautifulSoup, Tag, or list of the above
    :param str parser: Parser to use; defaults to BeautifulSoup default
    :return: Tag or list of Tags"""
    if isinstance(value, BeautifulSoup):
        return value.find()
    if isinstance(value, Tag):
        return value
    if isinstance(value, list):
        return [ensure_soup(item, parser=parser) for item in value]
    parsed = BeautifulSoup(value, features=parser)
    return parsed.find()

def encode_if_py2(func):
    """If Python 2.x, return decorated function encoding unicode return value
    to UTF-8; else noop."""
    if not PY2:
        return func
    def wrapped(*args, **kwargs):
        ret = func(*args, **kwargs)
        if not isinstance(ret, unicode):
            raise TypeError('Wrapped function must return `unicode`')
        return ret.encode('utf-8', 'ignore')
    return wrapped

def _parse_fields(parsed):
    """Parse form fields from HTML.

    :param BeautifulSoup parsed: Parsed HTML
    :return OrderedDict: Collection of field objects"""
    out = []
    tags = parsed.find_all(_tag_ptn)
    for tag in tags:
        helpers.lowercase_attr_names(tag)
    while tags:
        tag = tags.pop(0)
        try:
            field = _parse_field(tag, tags)
        except exceptions.InvalidNameError:
            continue
        if field is not None:
            out.append(field)
    return out

def _add_handler(logger, handler=None, loglevel=None):
    """Add a handler to an existing logging.Logger object"""
    handler.setLevel(loglevel or DEFAULT_LOGLEVEL)
    if handler.level <= logging.DEBUG:
        _fmt = '%(asctime)s| %(levelname)-4.3s|%(threadName)10.9s/%(lineno)04d@%(module)-10.9s| %(message)s'
        handler.setFormatter(logging.Formatter(_fmt))
    else:
        handler.setFormatter(logging.Formatter('%(asctime)s| %(levelname)-8s| %(message)s'))
    logger.addHandler(handler)

def _check_paramiko_handlers(logger=None):
    """Add a console handler for paramiko.transport's logger if not present"""
    paramiko_logger = logging.getLogger('paramiko.transport')
    if not paramiko_logger.handlers:
        if logger:
            paramiko_logger.handlers = logger.handlers
        else:
            console_handler = logging.StreamHandler()
            console_handler.setFormatter(logging.Formatter('%(asctime)s | %(levelname)-8s| PARAMIKO: %(lineno)03d@%(module)-10s| %(message)s'))
            paramiko_logger.addHandler(console_handler)

def _remove_none_values(dictionary):
    """Remove dictionary keys whose value is None"""
    return list(map(dictionary.pop, [i for i in dictionary if dictionary[i] is None]))

def _bindlist(input_str):
    """Define type of data expected for remote and local bind address lists
    Returns a tuple (ip_address, port) whose elements are (str, int)"""
    try:
        ip_port = input_str.split(':')
        if len(ip_port) == 1:
            _ip = ip_port[0]
            _port = None
        else:
            _ip, _port = ip_port
        if not _ip and (not _port):
            raise AssertionError
        elif not _port:
            _port = '22'
        return (_ip, int(_port))
    except ValueError:
        raise argparse.ArgumentTypeError('Address tuple must be of type IP_ADDRESS:PORT')
    except AssertionError:
        raise argparse.ArgumentTypeError("Both IP:PORT can't be missing!")

def _all_expander(fringe, iteration, viewer):
    """Expander that expands all nodes on the fringe."""
    expanded_neighbors = [node.expand(local_search=True) for node in fringe]
    if viewer:
        viewer.event('expanded', list(fringe), expanded_neighbors)
    list(map(fringe.extend, expanded_neighbors))

def _random_best_expander(fringe, iteration, viewer):
    """Expander that expands one randomly chosen nodes on the fringe that
    is better than the current (first) node."""
    current = fringe[0]
    neighbors = current.expand(local_search=True)
    if viewer:
        viewer.event('expanded', [current], [neighbors])
    betters = [n for n in neighbors if n.value > current.value]
    if betters:
        chosen = random.choice(betters)
        if viewer:
            viewer.event('chosen_node', chosen)
        fringe.append(chosen)

def _exp_schedule(iteration, k=20, lam=0.005, limit=100):
    """Possible scheduler for simulated_annealing, based on the aima example."""
    return k * math.exp(-lam * iteration)

def _create_simulated_annealing_expander(schedule):
    """Creates an expander that has a random chance to choose a node that is worse
    than the current (first) node, but that chance decreases with time."""
    def _expander(fringe, iteration, viewer):
        T = schedule(iteration)
        current = fringe[0]
        neighbors = current.expand(local_search=True)
        if viewer:
            viewer.event('expanded', [current], [neighbors])
        if neighbors:
            succ = random.choice(neighbors)
            delta_e = succ.value - current.value
            if delta_e > 0 or random.random() < math.exp(delta_e / T):
                fringe.pop()
                fringe.append(succ)
                if viewer:
                    viewer.event('chosen_node', succ)
    return _expander

def _local_search(problem, fringe_expander, iterations_limit=0, fringe_size=1, random_initial_states=False, stop_when_no_better=True, viewer=None):
    """Basic algorithm for all local search algorithms."""
    if viewer:
        viewer.event('started')
    fringe = BoundedPriorityQueue(fringe_size)
    if random_initial_states:
        for _ in range(fringe_size):
            s = problem.generate_random_state()
            fringe.append(SearchNodeValueOrdered(state=s, problem=problem))
    else:
        fringe.append(SearchNodeValueOrdered(state=problem.initial_state, problem=problem))
    finish_reason = ''
    iteration = 0
    run = True
    best = None
    while run:
        if viewer:
            viewer.event('new_iteration', list(fringe))
        old_best = fringe[0]
        fringe_expander(fringe, iteration, viewer)
        best = fringe[0]
        iteration += 1
        if iterations_limit and iteration >= iterations_limit:
            run = False
            finish_reason = 'reaching iteration limit'
        elif old_best.value >= best.value and stop_when_no_better:
            run = False
            finish_reason = 'not being able to improve solution'
    if viewer:
        viewer.event('finished', fringe, best, 'returned after %s' % finish_reason)
    return best

def find_location(rows, element_to_find):
    """Find the location of a piece in the puzzle.
    Returns a tuple: row, column"""
    for ir, row in enumerate(rows):
        for ic, element in enumerate(row):
            if element == element_to_find:
                return (ir, ic)

def tree_to_str(root):
    """Returns a string representation of a decision tree with
    root node `root`."""
    xs = []
    for value, node, depth in iter_tree(root):
        template = '{indent}'
        if node is not root:
            template += 'case={value}\t'
        if node.attribute is None:
            template += 'result={result} -- P={prob:.2}'
        else:
            template += 'split by {split}:\t' + '(partial result={result} -- P={prob:.2})'
        line = template.format(indent='    ' * depth, value=value, result=node.result[0], prob=node.result[1], split=str(node.attribute))
        xs.append(line)
    return '\n'.join(xs)

def backtrack(problem, variable_heuristic='', value_heuristic='', inference=True):
    """Backtracking search.

    variable_heuristic is the heuristic for variable choosing, can be
    MOST_CONSTRAINED_VARIABLE, HIGHEST_DEGREE_VARIABLE, or blank for simple
    ordered choosing.
    value_heuristic is the heuristic for value choosing, can be
    LEAST_CONSTRAINING_VALUE or blank for simple ordered choosing."""
    assignment = {}
    domains = deepcopy(problem.domains)
    if variable_heuristic == MOST_CONSTRAINED_VARIABLE:
        variable_chooser = _most_constrained_variable_chooser
    elif variable_heuristic == HIGHEST_DEGREE_VARIABLE:
        variable_chooser = _highest_degree_variable_chooser
    else:
        variable_chooser = _basic_variable_chooser
    if value_heuristic == LEAST_CONSTRAINING_VALUE:
        values_sorter = _least_constraining_values_sorter
    else:
        values_sorter = _basic_values_sorter
    return _backtracking(problem, assignment, domains, variable_chooser, values_sorter, inference=inference)

def _most_constrained_variable_chooser(problem, variables, domains):
    """Choose the variable that has less available values."""
    return sorted(variables, key=lambda v: len(domains[v]))[0]

def _highest_degree_variable_chooser(problem, variables, domains):
    """Choose the variable that is involved on more constraints."""
    return sorted(variables, key=lambda v: problem.var_degrees[v], reverse=True)[0]

def _count_conflicts(problem, assignment, variable=None, value=None):
    """Count the number of violated constraints on a given assignment."""
    return len(_find_conflicts(problem, assignment, variable, value))

def _find_conflicts(problem, assignment, variable=None, value=None):
    """Find violated constraints on a given assignment, with the possibility
    of specifying a new variable and value to add to the assignment before
    checking."""
    if variable is not None and value is not None:
        assignment = deepcopy(assignment)
        assignment[variable] = value
    conflicts = []
    for neighbors, constraint in problem.constraints:
        if all((n in assignment for n in neighbors)):
            if not _call_constraint(assignment, neighbors, constraint):
                conflicts.append((neighbors, constraint))
    return conflicts

def _backtracking(problem, assignment, domains, variable_chooser, values_sorter, inference=True):
    """Internal recursive backtracking algorithm."""
    from simpleai.search.arc import arc_consistency_3
    if len(assignment) == len(problem.variables):
        return assignment
    pending = [v for v in problem.variables if v not in assignment]
    variable = variable_chooser(problem, pending, domains)
    values = values_sorter(problem, assignment, variable, domains)
    for value in values:
        new_assignment = deepcopy(assignment)
        new_assignment[variable] = value
        if not _count_conflicts(problem, new_assignment):
            new_domains = deepcopy(domains)
            new_domains[variable] = [value]
            if not inference or arc_consistency_3(new_domains, problem.constraints):
                result = _backtracking(problem, new_assignment, new_domains, variable_chooser, values_sorter, inference=inference)
                if result:
                    return result
    return None

def _min_conflicts_value(problem, assignment, variable):
    """Return the value generate the less number of conflicts.
    In case of tie, a random value is selected among this values subset."""
    return argmin(problem.domains[variable], lambda x: _count_conflicts(problem, assignment, variable, x))

def min_conflicts(problem, initial_assignment=None, iterations_limit=0):
    """Min conflicts search.

    initial_assignment the initial assignment, or None to generate a random
    one.
    If iterations_limit is specified, the algorithm will end after that
    number of iterations. Else, it will continue until if finds an assignment
    that doesn't generate conflicts (a solution)."""
    assignment = {}
    if initial_assignment:
        assignment.update(initial_assignment)
    else:
        for variable in problem.variables:
            value = _min_conflicts_value(problem, assignment, variable)
            assignment[variable] = value
    iteration = 0
    run = True
    while run:
        conflicts = _find_conflicts(problem, assignment)
        conflict_variables = [v for v in problem.variables if any((v in conflict[0] for conflict in conflicts))]
        if conflict_variables:
            variable = random.choice(conflict_variables)
            value = _min_conflicts_value(problem, assignment, variable)
            assignment[variable] = value
        iteration += 1
        if iterations_limit and iteration >= iterations_limit:
            run = False
        elif not _count_conflicts(problem, assignment):
            run = False
    return assignment

def convert_to_binary(variables, domains, constraints):
    """Returns new constraint list, all binary, using hidden variables.

    You can use it as previous step when creating a problem."""
    def wdiff(vars_):
        def diff(variables, values):
            hidden, other = variables
            if hidden.startswith('hidden'):
                idx = vars_.index(other)
                return values[1] == values[0][idx]
            else:
                idx = vars_.index(hidden)
                return values[0] == values[1][idx]
        diff.no_wrap = True
        return diff
    new_constraints = []
    new_domains = copy(domains)
    new_variables = list(variables)
    last = 0
    for vars_, const in constraints:
        if len(vars_) == 2:
            new_constraints.append((vars_, const))
            continue
        hidden = 'hidden%d' % last
        new_variables.append(hidden)
        last += 1
        new_domains[hidden] = [t for t in product(*map(domains.get, vars_)) if const(vars_, t)]
        for var in vars_:
            new_constraints.append(((hidden, var), wdiff(vars_)))
    return (new_variables, new_domains, new_constraints)

def make_exponential_temperature(initial_temperature, alpha):
    """returns a function like initial / exp(n * alpha)"""
    def _function(n):
        try:
            return initial_temperature / math.exp(n * alpha)
        except OverflowError:
            return 0.01
    return _function

def mkconstraints():
    """Make constraint list for binary constraint problem."""
    constraints = []
    for j in range(1, 10):
        vars = ['%s%d' % (i, j) for i in uppercase[:9]]
        constraints.extend(((c, const_different) for c in combinations(vars, 2)))
    for i in uppercase[:9]:
        vars = ['%s%d' % (i, j) for j in range(1, 10)]
        constraints.extend(((c, const_different) for c in combinations(vars, 2)))
    for b0 in ['ABC', 'DEF', 'GHI']:
        for b1 in [[1, 2, 3], [4, 5, 6], [7, 8, 9]]:
            vars = ['%s%d' % (i, j) for i in b0 for j in b1]
            l = list(((c, const_different) for c in combinations(vars, 2)))
            constraints.extend(l)
    return constraints

def precision(classifier, testset):
    """Runs the classifier for each example in `testset`
    and verifies that the classification is correct
    using the `target`.

    Returns a number between 0.0 and 1.0 with the
    precision of classification for this test set."""
    hit = 0
    total = 0
    for example in testset:
        if classifier.classify(example)[0] == classifier.target(example):
            hit += 1
        total += 1
    if total == 0:
        raise ValueError('Empty testset!')
    return hit / float(total)

def all_arcs(constraints):
    """For each constraint ((X, Y), const) adds:
        ((X, Y), const)
        ((Y, X), const)"""
    arcs = set()
    for neighbors, constraint in constraints:
        if len(neighbors) == 2:
            x, y = neighbors
            list(map(arcs.add, ((x, y), (y, x))))
    return arcs

def arc_consistency_3(domains, constraints):
    """Makes a CSP problem arc consistent.

    Ignores any constraint that is not binary."""
    arcs = list(all_arcs(constraints))
    pending_arcs = set(arcs)
    while pending_arcs:
        x, y = pending_arcs.pop()
        if revise(domains, (x, y), constraints):
            if len(domains[x]) == 0:
                return False
            pending_arcs = pending_arcs.union(((x2, y2) for x2, y2 in arcs if y2 == x))
    return True

