def decimal_default(obj):
    """Properly parse out the Decimal datatypes into proper int/float types."""
    if isinstance(obj, decimal.Decimal):
        if obj % 1:
            return float(obj)
        return int(obj)
    raise TypeError

def fix_decimals(obj):
    """Removes the stupid Decimals

    See: https://github.com/boto/boto3/issues/369#issuecomment-302137290"""
    if isinstance(obj, list):
        for i in range(len(obj)):
            obj[i] = fix_decimals(obj[i])
        return obj
    elif isinstance(obj, dict):
        for key, value in obj.items():
            obj[key] = fix_decimals(value)
        return obj
    elif isinstance(obj, decimal.Decimal):
        if obj % 1 == 0:
            return int(obj)
        else:
            return float(obj)
    else:
        return obj

def deserialize_records(records):
    """This properly deserializes records depending on where they came from:
        - SQS
        - SNS"""
    native_records = []
    for record in records:
        parsed = json.loads(record['body'])
        if isinstance(parsed, str):
            native_records.append(json.loads(parsed))
        elif parsed.get('Type') == 'SubscriptionConfirmation':
            continue
        elif parsed.get('Message'):
            native_records.append(json.loads(parsed['Message']))
        else:
            native_records.append(parsed)
    return native_records

def pull_tag_dict(data):
    """This will pull out a list of Tag Name-Value objects, and return it as a dictionary.

    :param data: The dict collected from the collector.
    :returns dict: A dict of the tag names and their corresponding values."""
    tags = data.pop('Tags', {}) or {}
    if tags:
        proper_tags = {}
        for tag in tags:
            proper_tags[tag['Key']] = tag['Value']
        tags = proper_tags
    return tags

def create_delete_model(record):
    """Create an S3 model from a record."""
    arn = f"arn:aws:s3:::{cloudwatch.filter_request_parameters('bucketName', record)}"
    LOG.debug(f'[-] Deleting Dynamodb Records. Hash Key: {arn}')
    data = {'arn': arn, 'principalId': cloudwatch.get_principal(record), 'userIdentity': cloudwatch.get_user_identity(record), 'accountId': record['account'], 'eventTime': record['detail']['eventTime'], 'BucketName': cloudwatch.filter_request_parameters('bucketName', record), 'Region': cloudwatch.get_region(record), 'Tags': {}, 'configuration': {}, 'eventSource': record['detail']['eventSource'], 'version': VERSION}
    return CurrentS3Model(**data)

def process_delete_records(delete_records):
    """Process the requests for S3 bucket deletions"""
    for rec in delete_records:
        arn = f"arn:aws:s3:::{rec['detail']['requestParameters']['bucketName']}"
        try:
            LOG.debug(f'[-] Deleting bucket: {arn}')
            model = create_delete_model(rec)
            model.save(condition=CurrentS3Model.eventTime <= rec['detail']['eventTime'])
            model.delete()
        except PynamoDBConnectionError as pdce:
            LOG.warning(f"[?] Unable to delete bucket: {arn}. Either it doesn't exist, or this deletion event is stale (arrived before a NEWER creation/update). The specific exception is: {pdce}")

def handler(event, context):
    """Historical {{cookiecutter.technology_name}}  event poller.

    This poller is run at a set interval in order to ensure that changes do not go undetected by historical.

    Historical pollers generate `polling events` which simulate changes. These polling events contain configuration
    data such as the account/region defining where the collector should attempt to gather data from."""
    log.debug('Running poller. Configuration: {}'.format(event))
    for account in get_historical_accounts():
        try:
            events = []
            produce_events(events, os.environ.get('HISTORICAL_STREAM', 'Historical{{cookiecutter.technology_slug | titlecase }}PollerStream'))
