def shrink_blob(record, deletion):
    """Makes a shrunken blob to be sent to SNS/SQS (due to the 256KB size limitations of SNS/SQS messages).
    This will essentially remove the "configuration" field such that the size of the SNS/SQS message remains under
    256KB.
    :param record:
    :return:"""
    item = {'eventName': record['eventName'], EVENT_TOO_BIG_FLAG: not deletion}
    if record.get('userIdentity'):
        item['userIdentity'] = record['userIdentity']
    if not deletion:
        if record['dynamodb'].get('NewImage'):
            record['dynamodb']['NewImage'].pop('configuration', None)
            record['dynamodb']['NewImage'].pop('requestParameters', None)
    if record['dynamodb'].get('OldImage'):
        record['dynamodb']['OldImage'].pop('configuration', None)
        record['dynamodb']['OldImage'].pop('requestParameters', None)
    item['dynamodb'] = record['dynamodb']
    return item

def group_records_by_type(records, update_events):
    """Break records into two lists; create/update events and delete events.

    :param records:
    :param update_events:
    :return update_records, delete_records:"""
    update_records, delete_records = ([], [])
    for record in records:
        if record.get('detail-type', '') == 'Scheduled Event':
            LOG.error('[X] Received a Scheduled Event in the Queue... Please check that your environment is set up correctly.')
            continue
        if not record.get('detail'):
            continue
        if not record['detail'].get('errorCode'):
            if record['detail']['eventName'] in update_events:
                update_records.append(record)
            else:
                delete_records.append(record)
    return (update_records, delete_records)

def group_records_by_type(records):
    """Break records into two lists; create/update events and delete events."""
    update_records, delete_records = ([], [])
    for r in records:
        if isinstance(r, str):
            break
        if r['detail']['eventName'] in UPDATE_EVENTS:
            update_records.append(r)
        else:
            delete_records.append(r)
    return (update_records, delete_records)

