    link = '<a href="%s">%s</a>' % (page.data.get('url'), page.data.get('title'))
    desc = page.data.get('description')
    if desc:
        link += '&mdash;<i>%s</i>' % desc
    else:
        link += '&mdash;<i>description</i>'
    if link:
        return '<p>%s</p>' % link

def _safe_exit(start, output):
    """exit without breaking pipes"""
    try:
        sys.stdout.write(output)
        sys.stdout.flush()
    except TypeError:
        sys.stdout.write(str(output, 'utf-8'))
        sys.stdout.flush()
    except IOError:
        pass
    seconds = time.time() - start
    print('\n\n%5.3f seconds' % seconds, file=sys.stderr)

def get(args):
    """invoke wptools and assemble selected output"""
    html = args.H
    lang = args.l
    nowrap = args.n
    query = args.q
    silent = args.s
    title = args.t
    verbose = args.v
    wiki = args.w
    if query:
        qobj = WPToolsQuery(lang=lang, wiki=wiki)
        if title:
            return qobj.query(title)
        return qobj.random()
    page = wptools.page(title, lang=lang, silent=silent, verbose=verbose, wiki=wiki)
    try:
        page.get_query()
    except (StandardError, ValueError, LookupError):
        return 'NOT_FOUND'
    if not page.data.get('extext'):
        out = page.cache['query']['query']
    out = _page_text(page, nowrap)
    if html:
        out = _page_html(page)
    try:
        return out.encode('utf-8')
    except KeyError:
        return out

def curl_info(crl):
    """returns curl (response) info from Pycurl object"""
    kbps = crl.getinfo(crl.SPEED_DOWNLOAD) / 1000.0
    url = crl.getinfo(crl.EFFECTIVE_URL)
    url = url.replace('&format=json', '').replace('&formatversion=2', '')
    try:
        content_type = crl.getinfo(crl.CONTENT_TYPE)
    except TypeError:
        content_type = None
    return {'url': url, 'user-agent': user_agent(), 'content-type': content_type, 'status': crl.getinfo(crl.RESPONSE_CODE), 'bytes': crl.getinfo(crl.SIZE_DOWNLOAD), 'seconds': '%5.3f' % crl.getinfo(crl.TOTAL_TIME), 'kB/s': '%3.1f' % kbps}

def safequote_restbase(title):
    """Safequote restbase title possibly having slash in title"""
    try:
        return quote(title.encode('utf-8'), safe='')
    except UnicodeDecodeError:
        return quote(title, safe='')

def get_infobox(ptree, boxterm='box'):
    """Returns parse tree template with title containing <boxterm> as dict:

        <box> = {<name>: <value>, ...}

    If simple transform fails, attempts more general assembly:

        <box> = {'boxes': [{<title>: <parts>}, ...],
                 'count': <len(boxes)>}"""
    boxes = []
    for item in lxml.etree.fromstring(ptree).xpath('//template'):
        title = item.find('title').text
        if title and boxterm in title:
            box = template_to_dict(item)
            if box:
                return box
            alt = template_to_dict_alt(item, title)
            if alt:
                boxes.append(alt)
    if boxes:
        return {'boxes': boxes, 'count': len(boxes)}

def get_links(rlinks):
    """returns list of titles/urls from query/parse links response"""
    if rlinks is None:
        return
    links = []
    for item in rlinks:
        if 'url' in item:
            links.append(item['url'])
        if 'title' in item and 'ns' in item:
            if item['ns'] == 0:
                links.append(item['title'])
    return sorted(links) if links else None

def is_text(obj, name=None):
