def get_pdf(article, debug=False):
    """Download an article PDF from arXiv.

    :param article:
        The ADS article to retrieve.

    :type article:
        :class:`ads.search.Article`

    :returns:
        The binary content of the requested PDF."""
    print('Retrieving {0}'.format(article))
    identifier = [_ for _ in article.identifier if 'arXiv' in _]
    if identifier:
        url = 'http://arXiv.org/pdf/{0}.{1}'.format(identifier[0][9:13], ''.join((_ for _ in identifier[0][14:] if _.isdigit())))
    else:
        params = {'bibcode': article.bibcode, 'link_type': 'ARTICLE', 'db_key': 'AST'}
        url = requests.get('http://adsabs.harvard.edu/cgi-bin/nph-data_query', params=params).url
    q = requests.get(url)
    if not q.ok:
        print('Error retrieving {0}: {1} for {2}'.format(article, q.status_code, url))
        if debug:
            q.raise_for_status()
        else:
            return None
    if q.content.endswith('</html>'):
        print('Error retrieving {0}: 200 (access denied?) for {1}'.format(article, url))
        return None
    return q.content

def parse_name(name):
    """Parse a gs:// URL into the bucket and object names.

    Args:
      name: a GCS URL of the form gs://bucket or gs://bucket/object
    Returns:
      The bucket name (with no gs:// prefix), and the object name if present. If the name
      could not be parsed returns None for both."""
    bucket = None
    obj = None
    m = re.match(_STORAGE_NAME, name)
    if m:
        bucket = m.group(1)
        obj = m.group(2)
        if obj is not None:
            obj = obj[1:]
    else:
        m = re.match('(' + _OBJECT_NAME + ')', name)
        if m:
            obj = m.group(1)
    return (bucket, obj)

def _gcs_create(args, _):
    """Create one or more buckets."""
    errs = []
    for name in args['bucket']:
        try:
            bucket, key = google.datalab.storage._bucket.parse_name(name)
            if bucket and (not key):
                google.datalab.storage.Bucket(bucket).create(_make_context(args['project']))
            else:
                raise Exception('Invalid bucket name %s' % name)
        except Exception as e:
            errs.append("Couldn't create %s: %s" % (name, _extract_gcs_api_response_error(str(e))))
    if errs:
        raise Exception('\n'.join(errs))

def _gcs_delete(args, _):
    """Delete one or more buckets or objects."""
    objects = _expand_list(args['bucket'])
    objects.extend(_expand_list(args['object']))
    errs = []
    for obj in objects:
        try:
            bucket, key = google.datalab.storage._bucket.parse_name(obj)
            if bucket and key:
                gcs_object = google.datalab.storage.Object(bucket, key)
                if gcs_object.exists():
                    google.datalab.storage.Object(bucket, key).delete()
                else:
                    errs.append('%s does not exist' % obj)
            elif bucket:
                gcs_bucket = google.datalab.storage.Bucket(bucket)
                if gcs_bucket.exists():
                    gcs_bucket.delete()
                else:
                    errs.append('%s does not exist' % obj)
            else:
                raise Exception("Can't delete object with invalid name %s" % obj)
        except Exception as e:
            errs.append("Couldn't delete %s: %s" % (obj, _extract_gcs_api_response_error(str(e))))
    if errs:
        raise Exception('\n'.join(errs))

def _gcs_list_buckets(project, pattern):
    """List all Google Cloud Storage buckets that match a pattern."""
    data = [{'Bucket': 'gs://' + bucket.name, 'Created': bucket.metadata.created_on} for bucket in google.datalab.storage.Buckets(_make_context(project)) if fnmatch.fnmatch(bucket.name, pattern)]
    return google.datalab.utils.commands.render_dictionary(data, ['Bucket', 'Created'])

def _gcs_get_keys(bucket, pattern):
    """Get names of all Google Cloud Storage keys in a specified bucket that match a pattern."""
    return [obj for obj in list(bucket.objects()) if fnmatch.fnmatch(obj.metadata.name, pattern)]

def _gcs_get_key_names(bucket, pattern):
    """Get names of all Google Cloud Storage keys in a specified bucket that match a pattern."""
    return [obj.metadata.name for obj in _gcs_get_keys(bucket, pattern)]

def _gcs_list_keys(bucket, pattern):
    """List all Google Cloud Storage keys in a specified bucket that match a pattern."""
    data = [{'Name': obj.metadata.name, 'Type': obj.metadata.content_type, 'Size': obj.metadata.size, 'Updated': obj.metadata.updated_on} for obj in _gcs_get_keys(bucket, pattern)]
    return google.datalab.utils.commands.render_dictionary(data, ['Name', 'Type', 'Size', 'Updated'])

def _gcs_list(args, _):
    """List the buckets or the contents of a bucket.

    This command is a bit different in that we allow wildchars in the bucket name and will list
    the buckets that match."""
    target = args['objects']
    project = args['project']
    if target is None:
        return _gcs_list_buckets(project, '*')
    bucket_name, key = google.datalab.storage._bucket.parse_name(target)
    if bucket_name is None:
        raise Exception('Cannot list %s; not a valid bucket name' % target)
    if target:
        if not re.search('\\?|\\*|\\[', target):
            key = key.strip('/') + '/*' if key else '*'
        if project:
            for bucket in google.datalab.storage.Buckets(_make_context(project)):
                if bucket.name == bucket_name:
                    break
            else:
                raise Exception('%s does not exist in project %s' % (target, project))
        else:
            bucket = google.datalab.storage.Bucket(bucket_name)
        if bucket.exists():
            return _gcs_list_keys(bucket, key)
        else:
            raise Exception('Bucket %s does not exist' % target)
    else:
        return _gcs_list_buckets(project, target.strip('/')[5:])

def serialize_example(transformed_json_data, info_dict):
    """Makes a serialized tf.example.

    Args:
      transformed_json_data: dict of transformed data.
      info_dict: output of feature_transforms.get_transfrormed_feature_info()

    Returns:
      The serialized tf.example version of transformed_json_data."""
    import six
    import tensorflow as tf
    def _make_int64_list(x):
        return tf.train.Feature(int64_list=tf.train.Int64List(value=x))
    def _make_bytes_list(x):
        return tf.train.Feature(bytes_list=tf.train.BytesList(value=x))
    def _make_float_list(x):
        return tf.train.Feature(float_list=tf.train.FloatList(value=x))
    if sorted(six.iterkeys(transformed_json_data)) != sorted(six.iterkeys(info_dict)):
        raise ValueError('Keys do not match %s, %s' % (list(six.iterkeys(transformed_json_data)), list(six.iterkeys(info_dict))))
    ex_dict = {}
    for name, info in six.iteritems(info_dict):
        if info['dtype'] == tf.int64:
            ex_dict[name] = _make_int64_list(transformed_json_data[name])
        elif info['dtype'] == tf.float32:
            ex_dict[name] = _make_float_list(transformed_json_data[name])
        elif info['dtype'] == tf.string:
            ex_dict[name] = _make_bytes_list(transformed_json_data[name])
        else:
            raise ValueError('Unsupported data type %s' % info['dtype'])
    ex = tf.train.Example(features=tf.train.Features(feature=ex_dict))
    return ex.SerializeToString()

def _tf_load_model(sess, model_dir):
    """Load a tf model from model_dir, and return input/output alias maps."""
    meta_graph_pb = tf.saved_model.loader.load(sess=sess, tags=[tf.saved_model.tag_constants.SERVING], export_dir=model_dir)
    signature = meta_graph_pb.signature_def[signature_constants.DEFAULT_SERVING_SIGNATURE_DEF_KEY]
    input_alias_map = {friendly_name: tensor_info_proto.name for friendly_name, tensor_info_proto in signature.inputs.items()}
    output_alias_map = {friendly_name: tensor_info_proto.name for friendly_name, tensor_info_proto in signature.outputs.items()}
    return (input_alias_map, output_alias_map)

def _tf_predict(model_dir, input_csvlines):
    """Prediction with a tf savedmodel.

    Args:
      model_dir: directory that contains a saved model
      input_csvlines: list of csv strings

    Returns:
      Dict in the form tensor_name:prediction_list. Note that the value is always
          a list, even if there was only 1 row in input_csvlines."""
    with tf.Graph().as_default(), tf.Session() as sess:
        input_alias_map, output_alias_map = _tf_load_model(sess, model_dir)
        csv_tensor_name = list(input_alias_map.values())[0]
        results = sess.run(fetches=output_alias_map, feed_dict={csv_tensor_name: input_csvlines})
    if len(input_csvlines) == 1:
        for k, v in six.iteritems(results):
            if not isinstance(v, (list, np.ndarray)):
                results[k] = [v]
    for k, v in six.iteritems(results):
        if any((isinstance(x, bytes) for x in v)):
            results[k] = [x.decode('utf-8') for x in v]
    return results

def _download_images(data, img_cols):
    """Download images given image columns."""
    images = collections.defaultdict(list)
    for d in data:
        for img_col in img_cols:
            if d.get(img_col, None):
                if isinstance(d[img_col], Image.Image):
                    images[img_col].append(d[img_col])
                else:
                    with file_io.FileIO(d[img_col], 'rb') as fi:
                        im = Image.open(fi)
                    images[img_col].append(im)
            else:
                images[img_col].append('')
    return images

def _get_display_data_with_images(data, images):
    """Create display data by converting image urls to base64 strings."""
    if not images:
        return data
    display_data = copy.deepcopy(data)
    for img_col in images:
        for d, im in zip(display_data, images[img_col]):
            if im == '':
                d[img_col + '_image'] = ''
            else:
                im = im.copy()
                im.thumbnail((128, 128), Image.ANTIALIAS)
                buf = BytesIO()
                im.save(buf, 'PNG')
                content = base64.b64encode(buf.getvalue()).decode('ascii')
                d[img_col + '_image'] = content
    return display_data

