def save_project_id(project_id):
    """Save project id to config file.

    Args:
      project_id: the project_id to save."""
    try:
        subprocess.call(['gcloud', 'config', 'set', 'project', project_id])
    except:
        config_file = os.path.join(get_config_dir(), 'config.json')
        config = {}
        if os.path.exists(config_file):
            with open(config_file) as f:
                config = json.loads(f.read())
        config['project_id'] = project_id
        with open(config_file, 'w') as f:
            f.write(json.dumps(config))

def get_default_project_id():
    """Get default project id from config or environment var.

    Returns: the project id if available, or None."""
    try:
        proc = subprocess.Popen(['gcloud', 'config', 'list', '--format', 'value(core.project)'], stdout=subprocess.PIPE)
        stdout, _ = proc.communicate()
        value = stdout.strip()
        if proc.poll() == 0 and value:
            if isinstance(value, six.string_types):
                return value
            else:
                return value.decode()
    except:
        pass
    config_file = os.path.join(get_config_dir(), 'config.json')
    if os.path.exists(config_file):
        with open(config_file) as f:
            config = json.loads(f.read())
            if 'project_id' in config and config['project_id']:
                return str(config['project_id'])
    if os.getenv('PROJECT_ID') is not None:
        return os.getenv('PROJECT_ID')
    return None

def _construct_context_for_args(args):
    """Construct a new Context for the parsed arguments.

    Args:
      args: the dictionary of magic arguments.
    Returns:
      A new Context based on the current default context, but with any explicitly
        specified arguments overriding the default's config."""
    global_default_context = google.datalab.Context.default()
    config = {}
    for key in global_default_context.config:
        config[key] = global_default_context.config[key]
    billing_tier_arg = args.get('billing', None)
    if billing_tier_arg:
        config['bigquery_billing_tier'] = billing_tier_arg
    return google.datalab.Context(project_id=global_default_context.project_id, credentials=global_default_context.credentials, config=config)

def python_portable_string(string, encoding='utf-8'):
    """Converts bytes into a string type.

    Valid string types are retuned without modification. So in Python 2, type str
    and unicode are not converted.

    In Python 3, type bytes is converted to type str (unicode)"""
    if isinstance(string, six.string_types):
        return string
    if six.PY3:
        return string.decode(encoding)
    raise ValueError('Unsupported type %s' % str(type(string)))

def _storage_create(args, _):
    """Create one or more buckets."""
    buckets = datalab.storage.Buckets(project_id=args['project'])
    errs = []
    for name in args['bucket']:
        try:
            bucket, key = datalab.storage._bucket.parse_name(name)
            if bucket and (not key):
                buckets.create(bucket)
            else:
                raise Exception('Invalid bucket name %s' % name)
        except Exception as e:
            errs.append("Couldn't create %s: %s" % (name, _extract_storage_api_response_error(str(e))))
    if errs:
        raise Exception('\n'.join(errs))

def _storage_delete(args, _):
    """Delete one or more buckets or objects."""
    items = _expand_list(args['bucket'])
    items.extend(_expand_list(args['object']))
    errs = []
    for item in items:
        try:
            bucket, key = datalab.storage._bucket.parse_name(item)
            if bucket and key:
                gcs_item = datalab.storage.Item(bucket, key)
                if gcs_item.exists():
                    datalab.storage.Item(bucket, key).delete()
                else:
                    errs.append('%s does not exist' % item)
            elif bucket:
                gcs_bucket = datalab.storage.Bucket(bucket)
                if gcs_bucket.exists():
                    gcs_bucket.delete()
                else:
                    errs.append('%s does not exist' % item)
            else:
                raise Exception("Can't delete item with invalid name %s" % item)
        except Exception as e:
            errs.append("Couldn't delete %s: %s" % (item, _extract_storage_api_response_error(str(e))))
    if errs:
        raise Exception('\n'.join(errs))

