def get_field_list(fields, schema):
    """Convert a field list spec into a real list of field names.

    For tables, we return only the top-level non-RECORD fields as Google charts
    can't handle nested data."""
    if schema:
        all_fields = [f['name'] for f in schema._bq_schema if f['type'] != 'RECORD']
    if isinstance(fields, list):
        if schema:
            for f in fields:
                if f not in all_fields:
                    raise Exception('Cannot find field %s in given schema' % f)
        return fields
    if isinstance(fields, basestring) and fields != '*':
        if schema:
            for f in fields.split(','):
                if f not in all_fields:
                    raise Exception('Cannot find field %s in given schema' % f)
            return fields.split(',')
    if not schema:
        return []
    return all_fields

def _get_data_from_list_of_dicts(source, fields='*', first_row=0, count=-1, schema=None):
    """Helper function for _get_data that handles lists of dicts."""
    if schema is None:
        schema = google.datalab.bigquery.Schema.from_data(source)
    fields = get_field_list(fields, schema)
    gen = source[first_row:first_row + count] if count >= 0 else source
    rows = [{'c': [{'v': row[c]} if c in row else {} for c in fields]} for row in gen]
    return ({'cols': _get_cols(fields, schema), 'rows': rows}, len(source))

def _get_data_from_list_of_lists(source, fields='*', first_row=0, count=-1, schema=None):
    """Helper function for _get_data that handles lists of lists."""
    if schema is None:
        schema = google.datalab.bigquery.Schema.from_data(source)
    fields = get_field_list(fields, schema)
    gen = source[first_row:first_row + count] if count >= 0 else source
    cols = [schema.find(name) for name in fields]
    rows = [{'c': [{'v': row[i]} for i in cols]} for row in gen]
    return ({'cols': _get_cols(fields, schema), 'rows': rows}, len(source))

def _get_data_from_dataframe(source, fields='*', first_row=0, count=-1, schema=None):
    """Helper function for _get_data that handles Pandas DataFrames."""
    if schema is None:
        schema = google.datalab.bigquery.Schema.from_data(source)
    fields = get_field_list(fields, schema)
    rows = []
    if count < 0:
        count = len(source.index)
    df_slice = source.reset_index(drop=True)[first_row:first_row + count]
    for index, data_frame_row in df_slice.iterrows():
        row = data_frame_row.to_dict()
        for key in list(row.keys()):
            val = row[key]
            if isinstance(val, pandas.Timestamp):
                row[key] = val.to_pydatetime()
        rows.append({'c': [{'v': row[c]} if c in row else {} for c in fields]})
    cols = _get_cols(fields, schema)
    return ({'cols': cols, 'rows': rows}, len(source))

def handle_magic_line(line, cell, parser, namespace=None):
    """Helper function for handling magic command lines given a parser with handlers set."""
    try:
        args, cell = parser.parse(line, cell, namespace)
        if args:
            return args['func'](args, cell)
    except Exception as e:
        if e.args and e.args[0] == 'exit_0':
            return
        sys.stderr.write('\n' + str(e))
        sys.stderr.flush()

def extract_archive(archive_path, dest):
    """Extract a local or GCS archive file to a folder.

    Args:
      archive_path: local or gcs path to a *.tar.gz or *.tar file
      dest: local folder the archive will be extracted to"""
    if not os.path.isdir(dest):
        os.makedirs(dest)
    try:
        tmpfolder = None
        if not tf.gfile.Exists(archive_path) or tf.gfile.IsDirectory(archive_path):
            raise ValueError('archive path %s is not a file' % archive_path)
        if archive_path.startswith('gs://'):
            tmpfolder = tempfile.mkdtemp()
            cmd_args = ['gsutil', 'cp', archive_path, tmpfolder]
            _shell_process.run_and_monitor(cmd_args, os.getpid())
            archive_path = os.path.join(tmpfolder, os.path.name(archive_path))
        if archive_path.lower().endswith('.tar.gz'):
            flags = '-xzf'
        elif archive_path.lower().endswith('.tar'):
            flags = '-xf'
        else:
            raise ValueError('Only tar.gz or tar.Z files are supported.')
        cmd_args = ['tar', flags, archive_path, '-C', dest]
        _shell_process.run_and_monitor(cmd_args, os.getpid())
    finally:
        if tmpfolder:
            shutil.rmtree(tmpfolder)

def serialize_example(transformed_json_data, features, feature_indices, target_name):
    """Makes an instance of data in libsvm format.

    Args:
      transformed_json_data: dict of transformed data.
      features: features config.
      feature_indices: output of feature_transforms.get_transformed_feature_indices()

    Returns:
      The text line representation of an instance in libsvm format."""
    import six
    import tensorflow as tf
    from trainer import feature_transforms
    line = str(transformed_json_data[target_name][0])
    for name, info in feature_indices:
        if features[name]['transform'] in [feature_transforms.IDENTITY_TRANSFORM, feature_transforms.SCALE_TRANSFORM]:
            line += ' %d:%s' % (info['index_start'], str(transformed_json_data[name][0]))
        elif features[name]['transform'] in [feature_transforms.ONE_HOT_TRANSFORM, feature_transforms.MULTI_HOT_TRANSFORM]:
            for i in range(info['size']):
                if i in transformed_json_data[name]:
                    line += ' %d:1' % (info['index_start'] + i)
        elif features[name]['transform'] in [feature_transforms.IMAGE_TRANSFORM]:
            for i in range(info['size']):
                line += ' %d:%s' % (info['index_start'] + i, str(transformed_json_data[name][i]))
    return line

def get_credentials():
    """Get the credentials to use. We try application credentials first, followed by
    user credentials. The path to the application credentials can be overridden
    by pointing the GOOGLE_APPLICATION_CREDENTIALS environment variable to some file;
    the path to the user credentials can be overridden by pointing the CLOUDSDK_CONFIG
    environment variable to some directory (after which we will look for the file
    $CLOUDSDK_CONFIG/gcloud/credentials). Unless you have specific reasons for
    overriding these the defaults should suffice."""
    try:
        credentials, _ = google.auth.default()
        credentials = google.auth.credentials.with_scopes_if_required(credentials, CREDENTIAL_SCOPES)
        return credentials
    except Exception as e:
        cred_file = get_config_dir() + '/credentials'
        if os.path.exists(cred_file):
            with open(cred_file) as f:
                creds = json.loads(f.read())
            for entry in creds['data']:
                if entry['key']['type'] == 'google-cloud-sdk':
                    creds = oauth2client.client.OAuth2Credentials.from_json(json.dumps(entry['credential']))
                    return _convert_oauth2client_creds(creds)
        if type(e) == google.auth.exceptions.DefaultCredentialsError:
            if _in_datalab_docker():
                raise Exception('No application credentials found. Perhaps you should sign in.')
        raise e

def invert_features(features):
    """Make a dict in the form source column : set of transforms.

    Note that the key transform is removed."""
    inverted_features = collections.defaultdict(list)
    for transform in six.itervalues(features):
        source_column = transform['source_column']
        inverted_features[source_column].append(transform)
    return dict(inverted_features)

def _create_cell(args, cell_body):
    """Implements the BigQuery cell magic used to create datasets and tables.

     The supported syntax is:

       %%bigquery create dataset -n|--name <name> [-f|--friendly <friendlyname>]
       [<description>]

     or:

       %%bigquery create table -n|--name <tablename> [--overwrite]
       [<YAML or JSON cell_body defining schema to use for tables>]

    Args:
      args: the argument following '%bigquery create <command>'."""
    if args['command'] == 'dataset':
        try:
            datalab.bigquery.Dataset(args['name']).create(friendly_name=args['friendly'], description=cell_body)
        except Exception as e:
            print('Failed to create dataset %s: %s' % (args['name'], e))
    elif cell_body is None:
        print('Failed to create %s: no schema specified' % args['name'])
    else:
        try:
            record = datalab.utils.commands.parse_config(cell_body, datalab.utils.commands.notebook_environment(), as_dict=False)
            schema = datalab.bigquery.Schema(record)
            datalab.bigquery.Table(args['name']).create(schema=schema, overwrite=args['overwrite'])
        except Exception as e:
            print('Failed to create table %s: %s' % (args['name'], e))

def _delete_cell(args, _):
    """Implements the BigQuery cell magic used to delete datasets and tables.

     The supported syntax is:

       %%bigquery delete dataset -n|--name <name>

     or:

       %%bigquery delete table -n|--name <name>

    Args:
      args: the argument following '%bigquery delete <command>'."""
    if args['command'] == 'dataset':
        try:
            datalab.bigquery.Dataset(args['name']).delete()
        except Exception as e:
            print('Failed to delete dataset %s: %s' % (args['name'], e))
    else:
        try:
            datalab.bigquery.Table(args['name']).delete()
        except Exception as e:
            print('Failed to delete table %s: %s' % (args['name'], e))

def _pipeline_cell(args, cell_body):
    """Implements the BigQuery cell magic used to validate, execute or deploy BQ pipelines.

     The supported syntax is:
     %%bigquery pipeline [-q|--sql <query identifier>] <other args> <action>
     [<YAML or JSON cell_body or inline SQL>]

    Args:
      args: the arguments following '%bigquery pipeline'.
      cell_body: optional contents of the cell interpreted as YAML or JSON.
    Returns:
      The QueryResultsTable"""
    if args['action'] == 'deploy':
        raise Exception('Deploying a pipeline is not yet supported')
    env = {}
    for key, value in datalab.utils.commands.notebook_environment().items():
        if isinstance(value, datalab.bigquery._udf.UDF):
            env[key] = value
    query = _get_query_argument(args, cell_body, env)
    if args['verbose']:
        print(query.sql)
    if args['action'] == 'dryrun':
        print(query.sql)
        result = query.execute_dry_run()
        return datalab.bigquery._query_stats.QueryStats(total_bytes=result['totalBytesProcessed'], is_cached=result['cacheHit'])
    if args['action'] == 'run':
        return query.execute(args['target'], table_mode=args['mode'], use_cache=not args['nocache'], allow_large_results=args['large'], dialect=args['dialect'], billing_tier=args['billing']).results

def _get_schema(name):
    """Given a variable or table name, get the Schema if it exists."""
    item = datalab.utils.commands.get_notebook_item(name)
