      {list, create, delete}

    Args:
      args: the optional arguments following '%bq datasets command'."""
    if args['command'] == 'list':
        filter_ = args['filter'] if args['filter'] else '*'
        context = google.datalab.Context.default()
        if args['project']:
            context = google.datalab.Context(args['project'], context.credentials)
        return _render_list([str(dataset) for dataset in bigquery.Datasets(context) if fnmatch.fnmatch(str(dataset), filter_)])
    elif args['command'] == 'create':
        try:
            bigquery.Dataset(args['name']).create(friendly_name=args['friendly'])
        except Exception as e:
            print('Failed to create dataset %s: %s' % (args['name'], e))
    elif args['command'] == 'delete':
        try:
            bigquery.Dataset(args['name']).delete()
        except Exception as e:
            print('Failed to delete dataset %s: %s' % (args['name'], e))

def serving_from_csv_input(train_config, args, keep_target):
    """Read the input features from a placeholder csv string tensor."""
    examples = tf.placeholder(dtype=tf.string, shape=(None,), name='csv_input_string')
    features = parse_example_tensor(examples=examples, train_config=train_config, keep_target=keep_target)
    if keep_target:
        target = features.pop(train_config['target_column'])
    else:
        target = None
    features, target = preprocess_input(features=features, target=target, train_config=train_config, preprocess_output_dir=args.preprocess_output_dir, model_type=args.model_type)
    return input_fn_utils.InputFnOps(features, target, {'csv_line': examples})

def read_examples(input_files, batch_size, shuffle, num_epochs=None):
    """Creates readers and queues for reading example protos."""
    files = []
    for e in input_files:
        for path in e.split(','):
            files.extend(file_io.get_matching_files(path))
    thread_count = multiprocessing.cpu_count()
    min_after_dequeue = 1000
    queue_size_multiplier = thread_count + 3
    num_epochs = num_epochs or None
    filename_queue = tf.train.string_input_producer(files, num_epochs, shuffle)
    example_id, encoded_example = tf.TextLineReader().read_up_to(filename_queue, batch_size)
    if shuffle:
        capacity = min_after_dequeue + queue_size_multiplier * batch_size
        return tf.train.shuffle_batch([example_id, encoded_example], batch_size, capacity, min_after_dequeue, enqueue_many=True, num_threads=thread_count)
    else:
        capacity = queue_size_multiplier * batch_size
        return tf.train.batch([example_id, encoded_example], batch_size, capacity=capacity, enqueue_many=True, num_threads=thread_count)

def init_app(state):
    """Prepare the Flask application for Flask-Split.

    :param state: :class:`BlueprintSetupState` instance"""
    app = state.app
    app.config.setdefault('SPLIT_ALLOW_MULTIPLE_EXPERIMENTS', False)
    app.config.setdefault('SPLIT_DB_FAILOVER', False)
    app.config.setdefault('SPLIT_IGNORE_IP_ADDRESSES', [])
    app.config.setdefault('SPLIT_ROBOT_REGEX', '\n        (?i)\\b(\n            Baidu|\n            Gigabot|\n            Googlebot|\n            libwww-perl|\n            lwp-trivial|\n            msnbot|\n            SiteUptime|\n            Slurp|\n            WordPress|\n            ZIBB|\n            ZyBorg\n        )\\b\n    ')
    app.jinja_env.globals.update({'ab_test': ab_test, 'finished': finished})
    @app.template_filter()
    def percentage(number):
        number *= 100
        if abs(number) < 10:
            return '%.1f%%' % round(number, 1)
        else:
            return '%d%%' % round(number)

def finished(experiment_name, reset=True):
    """Track a conversion.

    :param experiment_name: Name of the experiment.
    :param reset: If set to `True` current user's session is reset so that they
        may start the test again in the future.  If set to `False` the user
        will always see the alternative they started with.  Defaults to `True`."""
    if _exclude_visitor():
        return
    redis = _get_redis_connection()
    try:
        experiment = Experiment.find(redis, experiment_name)
        if not experiment:
            return
        alternative_name = _get_session().get(experiment.key)
        if alternative_name:
            split_finished = set(session.get('split_finished', []))
            if experiment.key not in split_finished:
                alternative = Alternative(redis, alternative_name, experiment_name)
                alternative.increment_completion()
            if reset:
                _get_session().pop(experiment.key, None)
                try:
                    split_finished.remove(experiment.key)
                except KeyError:
                    pass
            else:
                split_finished.add(experiment.key)
            session['split_finished'] = list(split_finished)
    except ConnectionError:
        if not current_app.config['SPLIT_DB_FAILOVER']:
            raise

def set_experiment_winner(experiment):
    """Mark an alternative as the winner of the experiment."""
    redis = _get_redis_connection()
    experiment = Experiment.find(redis, experiment)
    if experiment:
        alternative_name = request.form.get('alternative')
        alternative = Alternative(redis, alternative_name, experiment.name)
        if alternative.name in experiment.alternative_names:
            experiment.winner = alternative.name
    return redirect(url_for('.index'))

def reset_experiment(experiment):
    """Delete all data for an experiment."""
    redis = _get_redis_connection()
    experiment = Experiment.find(redis, experiment)
    if experiment:
        experiment.reset()
    return redirect(url_for('.index'))

def delete_experiment(experiment):
    """Delete an experiment and all its data."""
    redis = _get_redis_connection()
    experiment = Experiment.find(redis, experiment)
    if experiment:
        experiment.delete()
    return redirect(url_for('.index'))

def _get_ipaddress(node):
    """Adds the ipaddress attribute to the given node object if not already
    present and it is correctly given by ohai
    Returns True if ipaddress is added, False otherwise"""
    if 'ipaddress' not in node:
        with settings(hide('stdout'), warn_only=True):
            output = sudo('ohai -l warn ipaddress')
        if output.succeeded:
            try:
                node['ipaddress'] = json.loads(output)[0]
            except ValueError:
                abort("Could not parse ohai's output for ipaddress:\n  {0}".format(output))
            return True
    return False

def build_dct(dic, keys, value):
    """Builds a dictionary with arbitrary depth out of a key list"""
    key = keys.pop(0)
    if len(keys):
        dic.setdefault(key, {})
        build_dct(dic[key], keys, value)
    else:
        if value == 'false':
            value = False
        elif value == 'true':
            value = True
        dic[key] = deepcopy(value)

def update_dct(dic1, dic2):
    """Merges two dictionaries recursively
    dic2 will have preference over dic1"""
    for key, val in dic2.items():
        if isinstance(val, dict):
            dic1.setdefault(key, {})
            update_dct(dic1[key], val)
        else:
            dic1[key] = val

