def get_plugins():
    """Gets available plugins by looking into the plugins/ directory"""
    if os.path.exists('plugins'):
        for filename in sorted([f for f in os.listdir('plugins') if not os.path.isdir(f) and f.endswith('.py')]):
            plugin_name = filename[:-3]
            try:
                plugin = import_plugin(plugin_name)
            except SystemExit as e:
                description = 'Plugin has a syntax error'
            else:
                description = plugin.__doc__ or 'No description found'
            yield {plugin_name: description}

def import_plugin(name):
    """Imports plugin python module"""
    path = os.path.join('plugins', name + '.py')
    try:
        with open(path, 'rb') as f:
            try:
                plugin = imp.load_module('p_' + name, f, name + '.py', ('.py', 'rb', imp.PY_SOURCE))
            except SyntaxError as e:
                error = "Found plugin '{0}', but it seems".format(name)
                error += ' to have a syntax error: {0}'.format(str(e))
                abort(error)
    except IOError:
        abort("Sorry, could not find '{0}.py' in the plugin directory".format(name))
    return plugin

def get_cookbook_path(cookbook_name):
    """Returns path to the cookbook for the given cookbook name"""
    for cookbook_path in cookbook_paths:
        path = os.path.join(cookbook_path, cookbook_name)
        if os.path.exists(path):
            return path
    raise IOError('Can\'t find cookbook with name "{0}"'.format(cookbook_name))

def _pprint(dic):
    """Prints a dictionary with one indentation level"""
    for key, value in dic.items():
        print('        {0}: {1}'.format(key, value))

def get_margin(length):
    """Add enough tabs to align in two columns"""
    if length > 23:
        margin_left = '\t'
        chars = 1
    elif length > 15:
        margin_left = '\t\t'
        chars = 2
    elif length > 7:
        margin_left = '\t\t\t'
        chars = 3
    else:
        margin_left = '\t\t\t\t'
        chars = 4
    return margin_left

def nodes_with_role(rolename):
    """Configures a list of nodes that have the given role in their run list"""
    nodes = [n['name'] for n in lib.get_nodes_with_role(rolename, env.chef_environment)]
    if not len(nodes):
        print("No nodes found with role '{0}'".format(rolename))
        sys.exit(0)
    return node(*nodes)

def nodes_with_recipe(recipename):
    """Configures a list of nodes that have the given recipe in their run list
    """
    nodes = [n['name'] for n in lib.get_nodes_with_recipe(recipename, env.chef_environment)]
    if not len(nodes):
        print("No nodes found with recipe '{0}'".format(recipename))
        sys.exit(0)
    return node(*nodes)

def nodes_with_tag(tag):
    """Sets a list of nodes that have the given tag assigned and calls node()"""
    nodes = lib.get_nodes_with_tag(tag, env.chef_environment, littlechef.include_guests)
    nodes = [n['name'] for n in nodes]
    if not len(nodes):
        print("No nodes found with tag '{0}'".format(tag))
        sys.exit(0)
    return node(*nodes)

def node(*nodes):
    """Selects and configures a list of nodes. 'all' configures all nodes"""
    chef.build_node_data_bag()
    if not len(nodes) or nodes[0] == '':
        abort('No node was given')
    elif nodes[0] == 'all':
        for node in lib.get_nodes(env.chef_environment):
            env.hosts.append(node['name'])
        if not len(env.hosts):
            abort('No nodes found in /nodes/')
        message = 'Are you sure you want to configure all nodes ({0})'.format(len(env.hosts))
        if env.chef_environment:
            message += ' in the {0} environment'.format(env.chef_environment)
        message += '?'
        if not __testing__:
            if not lib.global_confirm(message):
                abort('Aborted by user')
    else:
        env.hosts = list(nodes)
    env.all_hosts = list(env.hosts)
    if not (littlechef.__cooking__ and 'node:' not in sys.argv[-1] and ('nodes_with_role:' not in sys.argv[-1]) and ('nodes_with_recipe:' not in sys.argv[-1]) and ('nodes_with_tag:' not in sys.argv[-1])):
        with settings():
            execute(_node_runner)
        chef.remove_local_node_data_bag()

def deploy_chef(ask='yes', version='11'):
    """Install chef-solo on a node"""
    env.host_string = lib.get_env_host_string()
    if ask == 'no' or littlechef.noninteractive:
        print('Deploying Chef using omnibus installer version: ...'.format(version))
    else:
        message = '\nAre you sure you want to install Chef version:{0} on node {1}?'.format(version, env.host_string)
        if not confirm(message):
            abort('Aborted by user')
    lib.print_header('Configuring Chef Solo on {0}'.format(env.host_string))
    if not __testing__:
        solo.install(version)
        solo.configure()
        with settings(hide('stdout'), warn_only=True):
            output = sudo('ohai -l warn')
        if output.succeeded:
            try:
                ohai = json.loads(output)
            except ValueError:
                abort("Could not parse ohai's output:\n  {0}".format(output))
            node = {'run_list': []}
            for attribute in ['ipaddress', 'platform', 'platform_family', 'platform_version']:
                if ohai.get(attribute):
                    node[attribute] = ohai[attribute]
            chef.save_config(node)

