def _check_appliances():
    """Looks around and return True or False based on whether we are in a
    kitchen"""
    filenames = os.listdir(os.getcwd())
    missing = []
    for dirname in ['nodes', 'environments', 'roles', 'cookbooks', 'data_bags']:
        if dirname not in filenames or not os.path.isdir(dirname):
            missing.append(dirname)
    return (not bool(missing), missing)

def _is_allowed(attr, *args):
    """Test if a given attribute is allowed according to the
    current set of configured service backends."""
    for backend in _get_backends():
        try:
            if getattr(backend, attr)(*args):
                return True
        except AttributeError:
            raise NotImplementedError('%s.%s.%s() not implemented' % (backend.__class__.__module__, backend.__class__.__name__, attr))
    return False

def _is_valid_service_url(url):
    """Access services list from ``MAMA_CAS_VALID_SERVICES``."""
    valid_services = getattr(settings, 'MAMA_CAS_VALID_SERVICES', ())
    if not valid_services:
        return True
    warnings.warn('The MAMA_CAS_VALID_SERVICES setting is deprecated. Services should be configured using MAMA_CAS_SERVICES.', DeprecationWarning)
    for service in [re.compile(s) for s in valid_services]:
        if service.match(url):
            return True
    return False

def get_backend_path(service):
    """Return the dotted path of the matching backend."""
    for backend in _get_backends():
        try:
            if backend.service_allowed(service):
                return '%s.%s' % (backend.__class__.__module__, backend.__class__.__name__)
        except AttributeError:
            raise NotImplementedError('%s.%s.service_allowed() not implemented' % (backend.__class__.__module__, backend.__class__.__name__))
    return None

def get_callbacks(service):
    """Get configured callbacks list for a given service identifier."""
    callbacks = list(getattr(settings, 'MAMA_CAS_ATTRIBUTE_CALLBACKS', []))
    if callbacks:
        warnings.warn('The MAMA_CAS_ATTRIBUTE_CALLBACKS setting is deprecated. Service callbacks should be configured using MAMA_CAS_SERVICES.', DeprecationWarning)
    for backend in _get_backends():
        try:
            callbacks.extend(backend.get_callbacks(service))
        except AttributeError:
            raise NotImplementedError('%s.%s.get_callbacks() not implemented' % (backend.__class__.__module__, backend.__class__.__name__))
    return callbacks

def get_logout_url(service):
    """Get the configured logout URL for a given service identifier, if any."""
    for backend in _get_backends():
        try:
            return backend.get_logout_url(service)
        except AttributeError:
            raise NotImplementedError('%s.%s.get_logout_url() not implemented' % (backend.__class__.__module__, backend.__class__.__name__))
    return None

def logout_allowed(service):
    """Check if a given service identifier should be sent a logout request."""
    if hasattr(settings, 'MAMA_CAS_SERVICES'):
        return _is_allowed('logout_allowed', service)
    if hasattr(settings, 'MAMA_CAS_ENABLE_SINGLE_SIGN_OUT'):
        warnings.warn('The MAMA_CAS_ENABLE_SINGLE_SIGN_OUT setting is deprecated. SLO should be configured using MAMA_CAS_SERVICES.', DeprecationWarning)
    return getattr(settings, 'MAMA_CAS_ENABLE_SINGLE_SIGN_OUT', False)

def proxy_callback_allowed(service, pgturl):
    """Check if a given proxy callback is allowed for the given service identifier."""
    if hasattr(settings, 'MAMA_CAS_SERVICES'):
        return _is_allowed('proxy_callback_allowed', service, pgturl)
    return _is_valid_service_url(service)

def validate_service_ticket(service, ticket, pgturl=None, renew=False, require_https=False):
    """Validate a service ticket string. Return a triplet containing a
    ``ServiceTicket`` and an optional ``ProxyGrantingTicket``, or a
    ``ValidationError`` if ticket validation failed."""
    logger.debug('Service validation request received for %s' % ticket)
    if ticket and ticket.startswith(ProxyTicket.TICKET_PREFIX):
        raise InvalidTicketSpec('Proxy tickets cannot be validated with /serviceValidate')
    st = ServiceTicket.objects.validate_ticket(ticket, service, renew=renew, require_https=require_https)
    attributes = get_attributes(st.user, st.service)
    if pgturl is not None:
        logger.debug('Proxy-granting ticket request received for %s' % pgturl)
        pgt = ProxyGrantingTicket.objects.create_ticket(service, pgturl, user=st.user, granted_by_st=st)
    else:
        pgt = None
    return (st, attributes, pgt)

def get_attributes(user, service):
    """Return a dictionary of user attributes from the set of configured
    callback functions."""
    attributes = {}
    for path in get_callbacks(service):
        callback = import_string(path)
        attributes.update(callback(user, service))
    return attributes

def user_model_attributes(user, service):
    """Return all fields on the user object that are not in the list
    of fields to ignore."""
    ignore_fields = ['id', 'password']
    attributes = {}
    for field in user._meta.fields:
        if field.name not in ignore_fields:
            attributes[field.name] = getattr(user, field.name)
    return attributes

def add_query_params(url, params):
    """Inject additional query parameters into an existing URL. If
    parameters already exist with the same name, they will be
    overwritten. Parameters with empty values are ignored. Return
    the modified URL as a string."""
    def encode(s):
        return force_bytes(s, settings.DEFAULT_CHARSET)
    params = dict([(encode(k), encode(v)) for k, v in params.items() if v])
    parts = list(urlparse(url))
    query = dict(parse_qsl(parts[4]))
    query.update(params)
    parts[4] = urlencode(query)
    return urlunparse(parts)

def clean_service_url(url):
    """Return only the scheme, hostname (with optional port) and path
    components of the parameter URL."""
    parts = urlparse(url)
    return urlunparse((parts.scheme, parts.netloc, parts.path, '', '', ''))

def match_service(service1, service2):
    """Compare two service URLs. Return ``True`` if the scheme, hostname,
    optional port and path match."""
    s1, s2 = (urlparse(service1), urlparse(service2))
    try:
        return (s1.scheme, s1.netloc, s1.path) == (s2.scheme, s2.netloc, s2.path)
    except ValueError:
        return False

def redirect(to, *args, **kwargs):
    """Similar to the Django ``redirect`` shortcut but with altered
    functionality. If an optional ``params`` argument is provided, the
    dictionary items will be injected as query parameters on the
    redirection URL."""
    params = kwargs.pop('params', {})
    try:
        to = reverse(to, args=args, kwargs=kwargs)
    except NoReverseMatch:
        if '/' not in to and '.' not in to:
            to = reverse('cas_login')
        elif not service_allowed(to):
            raise PermissionDenied()
    if params:
        to = add_query_params(to, params)
    logger.debug('Redirecting to %s' % to)
    return HttpResponseRedirect(to)

def arg_to_dict(arg):
    """Convert an argument that can be None, list/tuple or dict to dict

    Example::

        >>> arg_to_dict(None)
        []
        >>> arg_to_dict(['a', 'b'])
        {'a':{},'b':{}}
        >>> arg_to_dict({'a':{'only': 'id'}, 'b':{'only': 'id'}})
        {'a':{'only':'id'},'b':{'only':'id'}}

    :return: dict with keys and dict arguments as value"""
    if arg is None:
        arg = []
    try:
        arg = dict(arg)
    except ValueError:
        arg = dict.fromkeys(list(arg), {})
    return arg

