def http_get(blink, url, stream=False, json=True, is_retry=False):
    """Perform an http get request.

    :param url: URL to perform get request.
    :param stream: Stream response? True/FALSE
    :param json: Return json response? TRUE/False
    :param is_retry: Is this part of a re-auth attempt?"""
    if blink.auth_header is None:
        raise BlinkException(ERROR.AUTH_TOKEN)
    _LOGGER.debug('Making GET request to %s', url)
    return http_req(blink, url=url, headers=blink.auth_header, reqtype='get', stream=stream, json_resp=json, is_retry=is_retry)

def http_post(blink, url, is_retry=False):
    """Perform an http post request.

    :param url: URL to perfom post request.
    :param is_retry: Is this part of a re-auth attempt?"""
    if blink.auth_header is None:
        raise BlinkException(ERROR.AUTH_TOKEN)
    _LOGGER.debug('Making POST request to %s', url)
    return http_req(blink, url=url, headers=blink.auth_header, reqtype='post', is_retry=is_retry)

def get_login_password(site_name='github.com', netrc_file='~/.netrc', git_credential_file='~/.git-credentials'):
    """Read a .netrc file and return login/password for LWN."""
    try:
        n = netrc.netrc(os.path.expanduser(netrc_file))
    except OSError:
        pass
    else:
        if site_name in n.hosts:
            return (n.hosts[site_name][0], n.hosts[site_name][2])
    try:
        with open(os.path.expanduser(git_credential_file)) as f:
            for line in f:
                parsed = parse.urlparse(line.strip())
                if parsed.hostname == site_name:
                    return (parse.unquote(parsed.username), parse.unquote(parsed.password))
    except OSError:
        pass
    return (None, None)

def get_github_hostname_user_repo_from_url(url):
    """Return hostname, user and repository to fork from.

    :param url: The URL to parse
    :return: hostname, user, repository"""
    parsed = parse.urlparse(url)
    if parsed.netloc == '':
        host, sep, path = parsed.path.partition(':')
        if '@' in host:
            username, sep, host = host.partition('@')
    else:
        path = parsed.path[1:].rstrip('/')
        host = parsed.netloc
    user, repo = path.split('/', 1)
    return (host, user, repo[:-4] if repo.endswith('.git') else repo)

