def validate_term(func):
    """Compares current term and request term:
    if current term is stale:
        update current term & become follower
    if received term is stale:
        respond with False"""
    @functools.wraps(func)
    def on_receive_function(self, data):
        if self.storage.term < data['term']:
            self.storage.update({'term': data['term']})
            if not isinstance(self, Follower):
                self.state.to_follower()
        if self.storage.term > data['term'] and (not data['type'].endswith('_response')):
            response = {'type': '{}_response'.format(data['type']), 'term': self.storage.term, 'success': False}
            asyncio.ensure_future(self.state.send(response, data['sender']), loop=self.loop)
            return
        return func(self, data)
    return on_receive_function

def validate_commit_index(func):
    """Apply to State Machine everything up to commit index"""
    @functools.wraps(func)
    def wrapped(self, *args, **kwargs):
        for not_applied in range(self.log.last_applied + 1, self.log.commit_index + 1):
            self.state_machine.apply(self.log[not_applied]['command'])
            self.log.last_applied += 1
            try:
                self.apply_future.set_result(not_applied)
            except (asyncio.futures.InvalidStateError, AttributeError):
                pass
        return func(self, *args, **kwargs)
    return wrapped

def _set_parameter(encoder, parameter, parameter_name, val):
    """This helper function sets a specific Brotli encoder parameter, checking
    the return code and raising :class:`Error <brotli.Error>` if it is
    invalid."""
    rc = lib.BrotliEncoderSetParameter(encoder, parameter, val)
    if parameter == lib.BROTLI_PARAM_MODE:
        _validate_mode(val)
    elif parameter == lib.BROTLI_PARAM_QUALITY:
        _validate_quality(val)
    elif parameter == lib.BROTLI_PARAM_LGWIN:
        _validate_lgwin(val)
    elif parameter == lib.BROTLI_PARAM_LGBLOCK:
        _validate_lgblock(val)
    else:
        raise RuntimeError('Unexpected parameter!')
    if rc != lib.BROTLI_TRUE:
        raise Error('Error setting parameter %s: %d' % (parameter_name, val))

def hsv_to_rgb(hsv):
    """Converts a tuple of hue, saturation, value to a tuple of red, green blue.
    Hue should be an angle from 0.0 to 359.0.  Saturation and value should be a
    value from 0.0 to 1.0, where saturation controls the intensity of the hue and
    value controls the brightness."""
    h, s, v = hsv
    if s == 0:
        return (v, v, v)
    h /= 60.0
    i = math.floor(h)
    f = h - i
    p = v * (1.0 - s)
    q = v * (1.0 - s * f)
    t = v * (1.0 - s * (1.0 - f))
    if i == 0:
        return (v, t, p)
    elif i == 1:
        return (q, v, p)
    elif i == 2:
        return (p, v, t)
    elif i == 3:
        return (p, q, v)
    elif i == 4:
        return (t, p, v)
    else:
        return (v, p, q)

def rectify_partial_form_field(base_field, partial_form_fields):
    """In base_field reset the attributes label and help_text, since they are overriden by the
    partial field. Additionally, from the list, or list of lists of partial_form_fields
    append the bound validator methods to the given base field."""
    base_field.label = ''
    base_field.help_text = ''
    for fieldset in partial_form_fields:
        if not isinstance(fieldset, (list, tuple)):
            fieldset = [fieldset]
        for field in fieldset:
            base_field.validators.append(field.run_validators)

