def bigger_version(version_string_a, version_string_b):
    """Returns the bigger version of two version strings."""
    major_a, minor_a, patch_a = parse_version_string(version_string_a)
    major_b, minor_b, patch_b = parse_version_string(version_string_b)
    if major_a > major_b:
        return version_string_a
    elif major_a == major_b and minor_a > minor_b:
        return version_string_a
    elif major_a == major_b and minor_a == minor_b and (patch_a > patch_b):
        return version_string_a
    return version_string_b

def api_version(created_ver, last_changed_ver, return_value_ver):
    """Version check decorator. Currently only checks Bigger Than."""
    def api_min_version_decorator(function):
        def wrapper(function, self, *args, **kwargs):
            if not self.version_check_mode == 'none':
                if self.version_check_mode == 'created':
                    version = created_ver
                else:
                    version = bigger_version(last_changed_ver, return_value_ver)
                major, minor, patch = parse_version_string(version)
                if major > self.mastodon_major:
                    raise MastodonVersionError('Version check failed (Need version ' + version + ')')
                elif major == self.mastodon_major and minor > self.mastodon_minor:
                    print(self.mastodon_minor)
                    raise MastodonVersionError('Version check failed (Need version ' + version + ')')
                elif major == self.mastodon_major and minor == self.mastodon_minor and (patch > self.mastodon_patch):
                    raise MastodonVersionError('Version check failed (Need version ' + version + ', patch is ' + str(self.mastodon_patch) + ')')
            return function(self, *args, **kwargs)
        function.__doc__ = function.__doc__ + '\n\n        *Added: Mastodon v' + created_ver + ', last changed: Mastodon v' + last_changed_ver + '*'
        return decorate(function, wrapper)
    return api_min_version_decorator

def clean(decrypted: bytes) -> str:
    """Strip padding from decrypted value.

    Remove number indicated by padding
    e.g. if last is '\\x0e' then ord('\\x0e') == 14, so take off 14.

    Args:
        decrypted: decrypted value
    Returns:
        Decrypted stripped of junk padding"""
    last = decrypted[-1]
    if isinstance(last, int):
        return decrypted[:-last].decode('utf8')
    return decrypted[:-ord(last)].decode('utf8')

def get_osx_config(browser: str) -> dict:
    """Get settings for getting Chrome/Chromium cookies on OSX.

    Args:
        browser: Either "Chrome" or "Chromium"
    Returns:
        Config dictionary for Chrome/Chromium cookie decryption"""
    if browser.lower() == 'chrome':
        cookie_file = '~/Library/Application Support/Google/Chrome/Default/Cookies'
    elif browser.lower() == 'chromium':
        cookie_file = '~/Library/Application Support/Chromium/Default/Cookies'
    else:
        raise ValueError('Browser must be either Chrome or Chromium.')
    config = {'my_pass': keyring.get_password('{} Safe Storage'.format(browser), browser), 'iterations': 1003, 'cookie_file': cookie_file}
    return config

def get_linux_config(browser: str) -> dict:
    """Get the settings for Chrome/Chromium cookies on Linux.

    Args:
        browser: Either "Chrome" or "Chromium"
    Returns:
        Config dictionary for Chrome/Chromium cookie decryption"""
    if browser.lower() == 'chrome':
        cookie_file = '~/.config/google-chrome/Default/Cookies'
    elif browser.lower() == 'chromium':
        cookie_file = '~/.config/chromium/Default/Cookies'
    else:
        raise ValueError('Browser must be either Chrome or Chromium.')
    config = {'my_pass': 'peanuts', 'iterations': 1, 'cookie_file': cookie_file}
    try:
        import gi
        gi.require_version('Secret', '1')
        from gi.repository import Secret
    except ImportError:
        pass
    else:
        flags = Secret.ServiceFlags.LOAD_COLLECTIONS
        service = Secret.Service.get_sync(flags)
        gnome_keyring = service.get_collections()
        unlocked_keyrings = service.unlock_sync(gnome_keyring).unlocked
        keyring_name = '{} Safe Storage'.format(browser.capitalize())
        for unlocked_keyring in unlocked_keyrings:
            for item in unlocked_keyring.get_items():
                if item.get_label() == keyring_name:
                    item.load_secret_sync()
                    config['my_pass'] = item.get_secret().get_text()
                    break
            else:
                continue
            break
    return config

def _hexdecode(hexstring):
    """Convert a hex encoded string to a byte string.

    For example '4A' will return 'J', and '04' will return ``'\\x04'`` (which has length 1).

    Args:
        hexstring (str): Can be for example 'A3' or 'A3B4'. Must be of even length.
        Allowed characters are '0' to '9', 'a' to 'f' and 'A' to 'F' (not space).

    Returns:
        A string of half the length, with characters corresponding to all 0-255 values for each byte.

    Raises:
        TypeError, ValueError"""
    _checkString(hexstring, description='hexstring')
    if len(hexstring) % 2 != 0:
        raise ValueError('The input hexstring must be of even length. Given: {!r}'.format(hexstring))
    if sys.version_info[0] > 2:
        by = bytes(hexstring, 'latin1')
        try:
            return str(binascii.unhexlify(by), encoding='latin1')
        except binascii.Error as err:
            new_error_message = 'Hexdecode reported an error: {!s}. Input hexstring: {}'.format(err.args[0], hexstring)
            raise TypeError(new_error_message)
    else:
        try:
            return hexstring.decode('hex')
        except TypeError as err:
            raise TypeError('Hexdecode reported an error: {}. Input hexstring: {}'.format(err.message, hexstring))

def _checkMode(mode):
    """Check that the Modbus mode is valie.

    Args:
        mode (string): The Modbus mode (MODE_RTU or MODE_ASCII)

    Raises:
        TypeError, ValueError"""
    if not isinstance(mode, str):
        raise TypeError('The {0} should be a string. Given: {1!r}'.format('mode', mode))
    if mode not in [MODE_RTU, MODE_ASCII]:
        raise ValueError("Unreconized Modbus mode given. Must be 'rtu' or 'ascii' but {0!r} was given.".format(mode))

