def ifndefs():
    """generate `#ifndef ZMQ_CONST` block for zmq_constants.h"""
    lines = ['#define _PYZMQ_UNDEFINED (-9999)']
    for name in all_names:
        if not no_prefix(name):
            name = 'ZMQ_%s' % name
        lines.append(ifndef_t.format(name))
    return dict(ZMQ_IFNDEFS='\n'.join(lines))

def constants_pyx():
    """generate CONST = ZMQ_CONST and __all__ for constants.pxi"""
    all_lines = []
    assign_lines = []
    for name in all_names:
        if name == 'NULL':
            assign_lines.append("globals()['NULL'] = ZMQ_NULL")
        else:
            assign_lines.append('{0} = ZMQ_{0}'.format(name))
        all_lines.append('  "{0}",'.format(name))
    return dict(ASSIGNMENTS='\n'.join(assign_lines), ALL='\n'.join(all_lines))

def import_from_api(request):
    """Import a part of a source site's page tree via a direct API request from
    this Wagtail Admin to the source site

    The source site's base url and the source page id of the point in the
    tree to import defined what to import and the destination parent page
    defines where to import it to."""
    if request.method == 'POST':
        form = ImportFromAPIForm(request.POST)
        if form.is_valid():
            base_url = re.sub('\\/$', '', form.cleaned_data['source_site_base_url'])
            import_url = base_url + reverse('wagtailimportexport:export', args=[form.cleaned_data['source_page_id']])
            r = requests.get(import_url)
            import_data = r.json()
            parent_page = form.cleaned_data['parent_page']
            try:
                page_count = import_pages(import_data, parent_page)
            except LookupError as e:
                messages.error(request, _('Import failed: %(reason)s') % {'reason': e})
            else:
                messages.success(request, ungettext('%(count)s page imported.', '%(count)s pages imported.', page_count) % {'count': page_count})
            return redirect('wagtailadmin_explore', parent_page.pk)
    else:
        form = ImportFromAPIForm()
    return render(request, 'wagtailimportexport/import_from_api.html', {'form': form})

def import_from_file(request):
    """Import a part of a source site's page tree via an import of a JSON file
    exported to a user's filesystem from the source site's Wagtail Admin

    The source site's base url and the source page id of the point in the
    tree to import defined what to import and the destination parent page
    defines where to import it to."""
    if request.method == 'POST':
        form = ImportFromFileForm(request.POST, request.FILES)
        if form.is_valid():
            import_data = json.loads(form.cleaned_data['file'].read().decode('utf-8-sig'))
            parent_page = form.cleaned_data['parent_page']
            try:
                page_count = import_pages(import_data, parent_page)
            except LookupError as e:
                messages.error(request, _('Import failed: %(reason)s') % {'reason': e})
            else:
                messages.success(request, ungettext('%(count)s page imported.', '%(count)s pages imported.', page_count) % {'count': page_count})
            return redirect('wagtailadmin_explore', parent_page.pk)
    else:
        form = ImportFromFileForm()
    return render(request, 'wagtailimportexport/import_from_file.html', {'form': form})

def export_to_file(request):
    """Export a part of this source site's page tree to a JSON file
    on this user's filesystem for subsequent import in a destination
    site's Wagtail Admin"""
    if request.method == 'POST':
        form = ExportForm(request.POST)
        if form.is_valid():
            payload = export_pages(form.cleaned_data['root_page'], export_unpublished=True)
            response = JsonResponse(payload)
            response['Content-Disposition'] = 'attachment; filename="export.json"'
            return response
    else:
        form = ExportForm()
    return render(request, 'wagtailimportexport/export_to_file.html', {'form': form})

def export(request, page_id, export_unpublished=False):
    """API endpoint of this source site to export a part of the page tree
    rooted at page_id

    Requests are made by a destination site's import_from_api view."""
    try:
        if export_unpublished:
            root_page = Page.objects.get(id=page_id)
        else:
            root_page = Page.objects.get(id=page_id, live=True)
    except Page.DoesNotExist:
        return JsonResponse({'error': _('page not found')})
    payload = export_pages(root_page, export_unpublished=export_unpublished)
    return JsonResponse(payload)

def url(context, view, subdomain=UNSET, *args, **kwargs):
    """Resolves a URL in a template, using subdomain-based URL resolution.

    If no subdomain is provided and a ``request`` is in the template context
    when rendering, the URL will be resolved relative to the current request's
    subdomain. If no ``request`` is provided, the URL will be resolved relative
    to current domain with the ``settings.ROOT_URLCONF``.

    Usage::

        {% load subdomainurls %}
        {% url 'view-name' subdomain='subdomain' %}

    .. note:: This tag uses the variable URL syntax introduced in Django
       1.3 as ``{% load url from future %}`` and was made the standard in Django
       1.5. If you are upgrading a legacy application from one of the previous
       template tag formats, make sure to quote your constant string URL names
       to avoid :exc:`~django.core.urlresolver.NoReverseMatch` errors during
       template rendering."""
    if subdomain is UNSET:
        request = context.get('request')
        if request is not None:
            subdomain = getattr(request, 'subdomain', None)
        else:
            subdomain = None
    elif subdomain is '':
        subdomain = None
    return reverse(view, subdomain=subdomain, args=args, kwargs=kwargs)

def urljoin(domain, path=None, scheme=None):
    """Joins a domain, path and scheme part together, returning a full URL.

    :param domain: the domain, e.g. ``example.com``
    :param path: the path part of the URL, e.g. ``/example/``
    :param scheme: the scheme part of the URL, e.g. ``http``, defaulting to the
        value of ``settings.DEFAULT_URL_SCHEME``
    :returns: a full URL"""
    if scheme is None:
        scheme = getattr(settings, 'DEFAULT_URL_SCHEME', 'http')
    return urlunparse((scheme, domain, path or '', None, None, None))

def getArcs(domains, constraints):
    """Return a dictionary mapping pairs (arcs) of constrained variables

    @attention: Currently unused."""
    arcs = {}
    for x in constraints:
        constraint, variables = x
        if len(variables) == 2:
            variable1, variable2 = variables
            arcs.setdefault(variable1, {}).setdefault(variable2, []).append(x)
            arcs.setdefault(variable2, {}).setdefault(variable1, []).append(x)
    return arcs

def doArc8(arcs, domains, assignments):
    """Perform the ARC-8 arc checking algorithm and prune domains

    @attention: Currently unused."""
    check = dict.fromkeys(domains, True)
    while check:
        variable, _ = check.popitem()
        if variable not in arcs or variable in assignments:
            continue
        domain = domains[variable]
        arcsvariable = arcs[variable]
        for othervariable in arcsvariable:
            arcconstraints = arcsvariable[othervariable]
            if othervariable in assignments:
                otherdomain = [assignments[othervariable]]
            else:
                otherdomain = domains[othervariable]
            if domain:
                for value in domain[:]:
                    assignments[variable] = value
                    if otherdomain:
                        for othervalue in otherdomain:
                            assignments[othervariable] = othervalue
                            for constraint, variables in arcconstraints:
                                if not constraint(variables, domains, assignments, True):
                                    break
                            else:
                                break
                        else:
                            domain.hideValue(value)
                        del assignments[othervariable]
                del assignments[variable]
            if not domain:
                return False
    return True

def is_valid_ip(ip_address):
    """Check Validity of an IP address"""
    if not ip_address:
        return False
    ip_address = ip_address.strip()
    try:
        validate_ipv46_address(ip_address)
        return True
    except ValidationError:
        return False

def get_ip_address_from_request(request):
    """Makes the best attempt to get the client's real IP or return
    the loopback"""
    remote_addr = request.META.get('REMOTE_ADDR', '')
    if remote_addr and is_valid_ip(remote_addr):
        return remote_addr.strip()
    return '127.0.0.1'

def get_ip(request):
    """get the ip address from the request"""
    if config.BEHIND_REVERSE_PROXY:
        ip_address = request.META.get(config.REVERSE_PROXY_HEADER, '')
        ip_address = ip_address.split(',', 1)[0].strip()
        if ip_address == '':
            ip_address = get_ip_address_from_request(request)
    else:
        ip_address = get_ip_address_from_request(request)
    return ip_address

def get_blocked_ips():
    """get a list of blocked ips from redis"""
    if config.DISABLE_IP_LOCKOUT:
        return []
    key = get_ip_blocked_cache_key('*')
    key_list = [redis_key.decode('utf-8') for redis_key in REDIS_SERVER.keys(key)]
    return strip_keys(key_list)

def get_blocked_usernames():
