def username_from_request(request):
    """unloads username from default POST request"""
    if config.USERNAME_FORM_FIELD in request.POST:
        return request.POST[config.USERNAME_FORM_FIELD][:255]
    return None

def block_ip(ip_address):
    """given the ip, block it"""
    if not ip_address:
        return
    if config.DISABLE_IP_LOCKOUT:
        return
    key = get_ip_blocked_cache_key(ip_address)
    if config.COOLOFF_TIME:
        REDIS_SERVER.set(key, 'blocked', config.COOLOFF_TIME)
    else:
        REDIS_SERVER.set(key, 'blocked')
    send_ip_block_signal(ip_address)

def block_username(username):
    """given the username block it."""
    if not username:
        return
    if config.DISABLE_USERNAME_LOCKOUT:
        return
    key = get_username_blocked_cache_key(username)
    if config.COOLOFF_TIME:
        REDIS_SERVER.set(key, 'blocked', config.COOLOFF_TIME)
    else:
        REDIS_SERVER.set(key, 'blocked')
    send_username_block_signal(username)

def record_failed_attempt(ip_address, username):
    """record the failed login attempt, if over limit return False,
    if not over limit return True"""
    ip_block = False
    if not config.DISABLE_IP_LOCKOUT:
        ip_count = increment_key(get_ip_attempt_cache_key(ip_address))
        if ip_count > config.IP_FAILURE_LIMIT:
            block_ip(ip_address)
            ip_block = True
    user_block = False
    if username and (not config.DISABLE_USERNAME_LOCKOUT):
        user_count = increment_key(get_username_attempt_cache_key(username))
        if user_count > config.USERNAME_FAILURE_LIMIT:
            block_username(username)
            user_block = True
    if config.DISABLE_IP_LOCKOUT:
        return not user_block
    if config.DISABLE_USERNAME_LOCKOUT:
        return not ip_block
    if config.LOCKOUT_BY_IP_USERNAME:
        return not (ip_block and user_block)
    return not (ip_block or user_block)

def unblock_ip(ip_address, pipe=None):
    """unblock the given IP"""
    do_commit = False
    if not pipe:
        pipe = REDIS_SERVER.pipeline()
        do_commit = True
    if ip_address:
        pipe.delete(get_ip_attempt_cache_key(ip_address))
        pipe.delete(get_ip_blocked_cache_key(ip_address))
        if do_commit:
            pipe.execute()

def unblock_username(username, pipe=None):
    """unblock the given Username"""
    do_commit = False
    if not pipe:
        pipe = REDIS_SERVER.pipeline()
        do_commit = True
    if username:
        pipe.delete(get_username_attempt_cache_key(username))
        pipe.delete(get_username_blocked_cache_key(username))
        if do_commit:
            pipe.execute()

def lockout_response(request):
    """if we are locked out, here is the response"""
    if config.LOCKOUT_TEMPLATE:
        context = {'cooloff_time_seconds': config.COOLOFF_TIME, 'cooloff_time_minutes': config.COOLOFF_TIME / 60, 'failure_limit': config.FAILURE_LIMIT}
        return render(request, config.LOCKOUT_TEMPLATE, context)
    if config.LOCKOUT_URL:
        return HttpResponseRedirect(config.LOCKOUT_URL)
    if config.COOLOFF_TIME:
        return HttpResponse('Account locked: too many login attempts.  Please try again later.')
    else:
        return HttpResponse('Account locked: too many login attempts.  Contact an admin to unlock your account.')

def is_user_already_locked(username):
    """Is this username already locked?"""
    if username is None:
        return False
    if config.DISABLE_USERNAME_LOCKOUT:
        return False
    return REDIS_SERVER.get(get_username_blocked_cache_key(username))

def is_source_ip_already_locked(ip_address):
    """Is this IP already locked?"""
    if ip_address is None:
        return False
    if config.DISABLE_IP_LOCKOUT:
        return False
    return REDIS_SERVER.get(get_ip_blocked_cache_key(ip_address))

def check_request(request, login_unsuccessful, get_username=get_username_from_request, username=None):
    """check the request, and process results"""
    ip_address = get_ip(request)
    username = username or get_username(request)
    if not login_unsuccessful:
        reset_failed_attempts(ip_address=ip_address, username=username)
        return True
    else:
        return record_failed_attempt(ip_address, username)

def add_login_attempt_task(user_agent, ip_address, username, http_accept, path_info, login_valid):
    """Create a record for the login attempt"""
    store_login_attempt(user_agent, ip_address, username, http_accept, path_info, login_valid)

def watch_login(status_code=302, msg='', get_username=utils.get_username_from_request):
    """Used to decorate the django.contrib.admin.site.login method or
    any other function you want to protect by brute forcing.
    To make it work on normal functions just pass the status code that should
    indicate a failure and/or a string that will be checked within the
    response body."""
    def decorated_login(func):
        @functools.wraps(func)
        def wrapper(request, *args, **kwargs):
            if utils.is_already_locked(request):
                return utils.lockout_response(request)
            response = func(request, *args, **kwargs)
            if request.method == 'POST':
                if status_code == 302:
                    login_unsuccessful = response and (not response.has_header('location')) and (response.status_code != status_code)
                else:
                    login_unsuccessful = response and response.status_code == status_code and (msg in response.content.decode('utf-8'))
                utils.add_login_attempt_to_db(request, not login_unsuccessful, get_username)
                if utils.check_request(request, login_unsuccessful, get_username):
                    return response
                return utils.lockout_response(request)
            return response
        return wrapper
    return decorated_login

def store_login_attempt(user_agent, ip_address, username, http_accept, path_info, login_valid):
    """Store the login attempt to the db."""
    AccessAttempt.objects.create(user_agent=user_agent, ip_address=ip_address, username=username, http_accept=http_accept, path_info=path_info, login_valid=login_valid)

def get_redis_connection():
