    if config.MOCK_REDIS:
        import mockredis
        return mockredis.mock_strict_redis_client()
    elif config.DEFENDER_REDIS_NAME:
        try:
            cache = caches[config.DEFENDER_REDIS_NAME]
        except InvalidCacheBackendError:
