def _process_name(name):
    """Fix issues with Jochem names."""
    name = unescape(name)
    name = NG_RE.sub('', name).strip()
    name = END_RE.sub('', name).strip(', ')
    name = RATIO_RE.sub('', name).strip(', ')
    name = START_RE.sub('', name).strip()
    name = BRACKET_RE.sub('\\g<1>', name)
    comps = name.split(', ')
    if len(comps) == 2:
        if comps[1].endswith('-'):
            name = comps[0]
            name = '%s%s' % (comps[1], name)
    elif len(comps) > 2:
        name = comps[0]
        for i in range(1, len(comps)):
            if comps[i].endswith('-'):
                name = '%s%s' % (comps[i], name)
            else:
                name = '%s %s' % (name, comps[i])
    return name

