def tag(ctx, input, output):
    """Output POS-tagged tokens."""
    log.info('chemdataextractor.pos.tag')
    log.info('Reading %s' % input.name)
    doc = Document.from_file(input)
    for element in doc.elements:
        if isinstance(element, Text):
            for sentence in element.sentences:
                output.write(u' '.join((u'/'.join([token, tag]) for token, tag in sentence.pos_tagged_tokens)))
                output.write(u'\n')

def getLocalTime(date, time, *args, **kwargs):
    """Get the time in the local timezone from date and time"""
    if time is not None:
        return getLocalDateAndTime(date, time, *args, **kwargs)[1]

def getLocalDateAndTime(date, time, *args, **kwargs):
    """Get the date and time in the local timezone from date and optionally time"""
    localDt = getLocalDatetime(date, time, *args, **kwargs)
    if time is not None:
        return (localDt.date(), localDt.timetz())
    else:
        return (localDt.date(), None)

def getLocalDatetime(date, time, tz=None, timeDefault=dt.time.max):
    """Get a datetime in the local timezone from date and optionally time"""
    localTZ = timezone.get_current_timezone()
    if tz is None or tz == localTZ:
        localDt = getAwareDatetime(date, time, tz, timeDefault)
    else:
        eventDt = getAwareDatetime(date, time, tz, timeDefault)
        localDt = eventDt.astimezone(localTZ)
        if time is None:
            localDt = getAwareDatetime(localDt.date(), None, localTZ, timeDefault)
    return localDt

def timeFormat(time_from, time_to=None, prefix='', infix=None):
    """Format the times time_from and optionally time_to, e.g. 10am"""
    retval = ''
    if time_from != '' and time_from is not None:
        retval += prefix
        retval += dateformat.time_format(time_from, 'fA').lower()
    if time_to != '' and time_to is not None:
        to = format(dateformat.time_format(time_to, 'fA').lower())
        if infix is not None:
            retval = '{} {} {}'.format(retval, infix, to)
        else:
            retval = _('{fromTime} to {toTime}').format(fromTime=retval, toTime=to)
    return retval.strip()

def dateFormat(when):
    """Format the date when, e.g. Friday 14th of April 2011"""
    retval = ''
    if when is not None:
        dow = dateformat.format(when, 'l')
        dom = dateformat.format(when, 'jS')
        month = dateformat.format(when, 'F')
        if when.year != dt.date.today().year:
            retval = _('{weekday} {day} of {month} {year}').format(weekday=dow, day=dom, month=month, year=when.year)
        else:
            retval = _('{weekday} {day} of {month}').format(weekday=dow, day=dom, month=month)
    return retval

def _iso_to_gregorian(iso_year, iso_week, iso_day):
    """Gregorian calendar date for the given ISO year, week and day"""
    year_start = _iso_year_start(iso_year)
    return year_start + dt.timedelta(days=iso_day - 1, weeks=iso_week - 1)

def _ssweek_to_gregorian(ssweek_year, ssweek_week, ssweek_day):
    """Gregorian calendar date for the given Sundaystarting-week year, week and day"""
    year_start = _ssweek_year_start(ssweek_year)
    return year_start + dt.timedelta(days=ssweek_day - 1, weeks=ssweek_week - 1)

def _gregorian_to_ssweek(date_value):
    """Sundaystarting-week year, week and day for the given  Gregorian calendar date"""
    yearStart = _ssweek_year_start(date_value.year)
    weekNum = (date_value - yearStart).days // 7 + 1
    dayOfWeek = date_value.weekday() + 1
    return (date_value.year, weekNum, dayOfWeek)

def get_group_model():
    """Get the group model from the ``JOYOUS_GROUP_MODEL`` setting.
    Useful for developers that need the group model.
    Defaults to the standard :class:`ls.joyous.models.GroupPage` model
    if no custom model is defined."""
    from django.apps import apps
    model_string = get_group_model_string()
    try:
        return apps.get_model(model_string)
    except ValueError:
        raise ImproperlyConfigured("JOYOUS_GROUP_MODEL must be of the form 'app_label.model_name'")
    except LookupError:
        raise ImproperlyConfigured("JOYOUS_GROUP_MODEL refers to model '%s' that has not been installed" % model_string)

def toOrdinal(n):
    """Returns the ordinal name of a number
    e.g. 'first'"""
    if n == -1:
        retval = _('last')
    elif n == -2:
        retval = _('penultimate')
    elif 1 <= n <= 5:
        retval = _n2w(n, to='ordinal')
    else:
        retval = _n2w(n, to='ordinal_num')
    return retval

def toTheOrdinal(n, inTitleCase=True):
    """Returns the definite article with the ordinal name of a number
    e.g. 'the second'
    Becomes important for languages with multiple definite articles (e.g. French)"""
    if n == -1:
        retval = _('the last')
    elif n == -2:
        retval = _('the penultimate')
    elif n == 1:
        retval = _('the first')
    elif n == 2:
        retval = _('the second')
    elif n == 3:
        retval = _('the third')
    elif n == 4:
        retval = _('the fourth')
    elif n == 5:
        retval = _('the fifth')
    else:
        retval = _('the')
        if inTitleCase:
            retval = retval.title()
        retval += ' ' + _n2w(n, to='ordinal_num')
        return retval
    if inTitleCase:
        retval = retval.title()
    return retval

def hrJoin(items):
    """Joins items together in a human readable string
    e.g. 'wind, ice and fire'"""
    conjuction = ' ' + _('and') + ' '
    if len(items) <= 2:
        return conjuction.join(items)
    else:
        return ', '.join(items[:-1]) + conjuction + items[-1]

