def parseHolidays(holidaysStr, holidayMap=None):
    """Takes a string like NZ[WTL,Nelson],AU[*],Northern Ireland and builds a HolidaySum from it"""
    if holidayMap is None:
        holidayMap = _HOLIDAY_MAP
    retval = holidays.HolidayBase()
    retval.country = None
    holidaysStr = holidaysStr.strip()
    for country, subdivisions in HolsRe.findall(holidaysStr):
        cls = holidayMap.get(country)
        if cls is not None:
            if subdivisions:
                retval += _parseSubdivisions(subdivisions, cls)
            else:
                retval += cls()
    return retval

def _raise_for_status(response):
    """Custom raise_for_status with more appropriate error message."""
    http_error_msg = ''
    if 400 <= response.status_code < 500:
        http_error_msg = '{0} Client Error: {1}'.format(response.status_code, response.reason)
    elif 500 <= response.status_code < 600:
        http_error_msg = '{0} Server Error: {1}'.format(response.status_code, response.reason)
    if http_error_msg:
        try:
            more_info = response.json().get('message')
        except ValueError:
            more_info = None
        if more_info and more_info.lower() != response.reason.lower():
            http_error_msg += '.\n\t{0}'.format(more_info)
        raise requests.exceptions.HTTPError(http_error_msg, response=response)

def _clear_empty_values(args):
    """Scrap junk data from a dict."""
    result = {}
    for param in args:
        if args[param] is not None:
            result[param] = args[param]
    return result

def authentication_validation(username, password, access_token):
    """Only accept one form of authentication."""
    if bool(username) is not bool(password):
        raise Exception('Basic authentication requires a username AND password.')
    if username and access_token or (password and access_token):
        raise Exception('Cannot use both Basic Authentication and OAuth2.0. Please use only one authentication method.')

def _download_file(url, local_filename):
    """Utility function that downloads a chunked response from the specified url to a local path.
    This method is suitable for larger downloads."""
    response = requests.get(url, stream=True)
    with open(local_filename, 'wb') as outfile:
        for chunk in response.iter_content(chunk_size=1024):
            if chunk:
                outfile.write(chunk)

def nowarnings(func):
    """Create a function wrapped in a context that ignores warnings.
    """
    @functools.wraps(func)
    def new_func(*args, **kwargs):
        with warnings.catch_warnings():
            warnings.simplefilter('ignore')
            return func(*args, **kwargs)
    return new_func

def calculate_first_digit(number):
    """This function calculates the first check digit of a
    cpf or cnpj.

    :param number: cpf (length 9) or cnpf (length 12)
        string to check the first digit. Only numbers.
    :type number: string
    :returns: string -- the first digit"""
    sum = 0
    if len(number) == 9:
        weights = CPF_WEIGHTS[0]
    else:
        weights = CNPJ_WEIGHTS[0]
    for i in range(len(number)):
        sum = sum + int(number[i]) * weights[i]
    rest_division = sum % DIVISOR
    if rest_division < 2:
        return '0'
    return str(11 - rest_division)

def xml_open(filename, expected_root=None):
    """Opens the provided 'filename'. Handles detecting if the file is an archive,
    detecting the document version, and validating the root tag."""
    if zipfile.is_zipfile(filename):
        tree = get_xml_from_archive(filename)
    else:
        tree = ET.parse(filename)
    tree_root = tree.getroot()
    file_version = Version(tree_root.attrib.get('version', '0.0'))
    if file_version < MIN_SUPPORTED_VERSION:
        raise TableauVersionNotSupportedException(file_version)
    if expected_root and expected_root != tree_root.tag:
        raise TableauInvalidFileException("'{}'' is not a valid '{}' file".format(filename, expected_root))
    return tree

def find_file_in_zip(zip_file):
    """Returns the twb/tds file from a Tableau packaged file format. Packaged
    files can contain cache entries which are also valid XML, so only look for
    files with a .tds or .twb extension."""
    candidate_files = filter(lambda x: x.split('.')[-1] in ('twb', 'tds'), zip_file.namelist())
    for filename in candidate_files:
        with zip_file.open(filename) as xml_candidate:
            try:
                ET.parse(xml_candidate)
                return filename
            except ET.ParseError:
                pass

def build_archive_file(archive_contents, zip_file):
    """Build a Tableau-compatible archive file."""
    for root_dir, _, files in os.walk(archive_contents):
        relative_dir = os.path.relpath(root_dir, archive_contents)
        for f in files:
            temp_file_full_path = os.path.join(archive_contents, relative_dir, f)
            zipname = os.path.join(relative_dir, f)
            zip_file.write(temp_file_full_path, arcname=zipname)

def hellinger_distance(outputs, targets, derivative=False):
    """The output signals should be in the range [0, 1]"""
    root_difference = np.sqrt(outputs) - np.sqrt(targets)
    if derivative:
        return root_difference / (np.sqrt(2) * np.sqrt(outputs))
    else:
        return np.mean(np.sum(np.power(root_difference, 2), axis=1) / math.sqrt(2))

def binary_cross_entropy_cost(outputs, targets, derivative=False, epsilon=1e-11):
    """The output signals should be in the range [0, 1]"""
    outputs = np.clip(outputs, epsilon, 1 - epsilon)
    divisor = np.maximum(outputs * (1 - outputs), epsilon)
    if derivative:
        return (outputs - targets) / divisor
    else:
        return np.mean(-np.sum(targets * np.log(outputs) + (1 - targets) * np.log(1 - outputs), axis=1))

def softmax_categorical_cross_entropy_cost(outputs, targets, derivative=False, epsilon=1e-11):
    """The output signals should be in the range [0, 1]"""
    outputs = np.clip(outputs, epsilon, 1 - epsilon)
    if derivative:
        return outputs - targets
    else:
        return np.mean(-np.sum(targets * np.log(outputs), axis=1))

def standarize(trainingset):
    """Morph the input signal to a mean of 0 and scale the signal strength by
    dividing with the standard deviation (rather that forcing a [0, 1] range)"""
    def encoder(dataset):
        for instance in dataset:
            if np.any(stds == 0):
                nonzero_indexes = np.where(stds != 0)
                instance.features[nonzero_indexes] = (instance.features[nonzero_indexes] - means[nonzero_indexes]) / stds[nonzero_indexes]
            else:
                instance.features = (instance.features - means) / stds
        return dataset
    training_data = np.array([instance.features for instance in trainingset])
    means = training_data.mean(axis=0)
    stds = training_data.std(axis=0)
    return encoder

def replace_nan(trainingset, replace_with=None):
    """Replace instanced of "not a number" with either the mean of the signal feature
    or a specific value assigned by `replace_nan_with`"""
    training_data = np.array([instance.features for instance in trainingset]).astype(np.float64)
    def encoder(dataset):
        for instance in dataset:
            instance.features = instance.features.astype(np.float64)
            if np.sum(np.isnan(instance.features)):
                if replace_with == None:
                    instance.features[np.isnan(instance.features)] = means[np.isnan(instance.features)]
                else:
                    instance.features[np.isnan(instance.features)] = replace_with
        return dataset
    if replace_nan_with == None:
        means = np.mean(np.nan_to_num(training_data), axis=0)
    return encoder

def normalize(trainingset):
    """Morph the input signal to a mean of 0 and scale the signal strength by
    dividing with the standard deviation (rather that forcing a [0, 1] range)"""
    def encoder(dataset):
        for instance in dataset:
            if np.any(stds == 0):
                nonzero_indexes = np.where(stds != 0)
                instance.features[nonzero_indexes] = instance.features[nonzero_indexes] / stds[nonzero_indexes]
            else:
                instance.features = instance.features / stds
        return dataset
    training_data = np.array([instance.features for instance in trainingset])
    stds = training_data.std(axis=0)
    return encoder

def elliot_function(signal, derivative=False):
    """A fast approximation of sigmoid"""
    s = 1
    abs_signal = 1 + np.abs(signal * s)
    if derivative:
        return 0.5 * s / abs_signal ** 2
    else:
        return 0.5 * (signal * s) / abs_signal + 0.5

def symmetric_elliot_function(signal, derivative=False):
    """A fast approximation of tanh"""
    s = 1.0
    abs_signal = 1 + np.abs(signal * s)
    if derivative:
        return s / abs_signal ** 2
    else:
        return signal * s / abs_signal

def LReLU_function(signal, derivative=False, leakage=0.01):
    """Leaky Rectified Linear Unit"""
    if derivative:
        return np.clip(signal > 0, leakage, 1.0)
    else:
        output = np.copy(signal)
        output[output < 0] *= leakage
        return output

def is_zipfile(filename):
    """Quickly see if a file is a ZIP file by checking the magic number.

    The filename argument may be a file or file-like object too."""
    result = False
    try:
        if hasattr(filename, 'read'):
            result = _check_zipfile(fp=filename)
        else:
            with open(filename, 'rb') as fp:
                result = _check_zipfile(fp)
    except OSError:
        pass
    return result

def _section_from_spec(elf_file, spec):
    """Retrieve a section given a "spec" (either number or name).
    Return None if no such section exists in the file."""
    if isinstance(spec, int):
        num = int(spec)
        if num < elf_file.num_sections():
            return elf_file.get_section(num)
    if isinstance(spec, str):
        try:
            return elf_file.get_section_by_name(spec)
        except AttributeError:
            return None

def import_object_from_string_code(code, object):
    """Used to import an object from arbitrary passed code.

    Passed in code is treated as a module and is imported and added
    to `sys.modules` with its SHA256 hash as key.

    Args:
        code (string): Python code to import as module

        object (string): Name of object to extract from imported module"""
    sha256 = hashlib.sha256(code.encode('UTF-8')).hexdigest()
    module = imp.new_module(sha256)
    try:
        exec_(code, module.__dict__)
    except Exception as e:
        raise exceptions.UserError('User code exception', exception_message=str(e))
    sys.modules[sha256] = module
    try:
        return getattr(module, object)
    except AttributeError:
        raise exceptions.UserError('{} not found in code'.format(object))

def prefer_master(nodes: List[DiscoveredNode]) -> Optional[DiscoveredNode]:
    """Select the master if available, otherwise fall back to a replica."""
    return max(nodes, key=attrgetter('state'))

def prefer_replica(nodes: List[DiscoveredNode]) -> Optional[DiscoveredNode]:
    """Select a random replica if any are available or fall back to the master."""
    masters = [node for node in nodes if node.state == NodeState.Master]
    replicas = [node for node in nodes if node.state != NodeState.Master]
    if replicas:
        return random.choice(replicas)
    else:
        return masters[0]

def create_event_handler(event_type, handler):
    """Register a comm and return a serializable object with target name"""
    target_name = '{hash}_{event_type}'.format(hash=hash(handler), event_type=event_type)
    def handle_comm_opened(comm, msg):
        @comm.on_msg
        def _handle_msg(msg):
            data = msg['content']['data']
            event = json.loads(data)
            return_value = handler(event)
            if return_value:
                comm.send(return_value)
        comm.send('Comm target "{target_name}" registered by vdom'.format(target_name=target_name))
    if get_ipython():
        get_ipython().kernel.comm_manager.register_target(target_name, handle_comm_opened)
    return target_name

def to_json(el, schema=None):
    """Convert an element to VDOM JSON

    If you wish to validate the JSON, pass in a schema via the schema keyword
    argument. If a schema is provided, this raises a ValidationError if JSON
    does not match the schema."""
    if type(el) is str:
        json_el = el
    elif type(el) is list:
        json_el = list(map(to_json, el))
    elif type(el) is dict:
        assert 'tagName' in el
        json_el = el.copy()
        if 'attributes' not in el:
            json_el['attributes'] = {}
        if 'children' not in el:
            json_el['children'] = []
    elif isinstance(el, VDOM):
        json_el = el.to_dict()
    else:
        json_el = el
    if schema:
        try:
            validate(instance=json_el, schema=schema, cls=Draft4Validator)
        except ValidationError as e:
            raise ValidationError(_validate_err_template.format(schema, e))
    return json_el

def create_component(tag_name, allow_children=True):
    """Create a component for an HTML Tag

    Examples:
        >>> marquee = create_component('marquee')
        >>> marquee('woohoo')
        <marquee>woohoo</marquee>"""
    def _component(*children, **kwargs):
        if 'children' in kwargs:
            children = kwargs.pop('children')
        elif len(children) == 1 and isinstance(children[0], list):
            children = tuple(children[0])
        style = None
        event_handlers = None
        attributes = dict(**kwargs)
        if 'style' in kwargs:
            style = kwargs.pop('style')
        if 'attributes' in kwargs:
            attributes = kwargs['attributes']
        for key, value in attributes.items():
            if callable(value):
                attributes = attributes.copy()
                if event_handlers == None:
                    event_handlers = {key: attributes.pop(key)}
                else:
                    event_handlers[key] = attributes.pop(key)
        if not allow_children and children:
            raise ValueError('<{tag_name} /> cannot have children'.format(tag_name=tag_name))
        v = VDOM(tag_name, attributes, style, children, None, event_handlers)
        return v
    return _component

def h(tagName, *children, **kwargs):
    """Takes an HTML Tag, children (string, array, or another element), and
    attributes

    Examples:

      >>> h('div', [h('p', 'hey')])
      <div><p>hey</p></div>"""
    attrs = {}
    if 'attrs' in kwargs:
        attrs = kwargs.pop('attrs')
    attrs = attrs.copy()
    attrs.update(kwargs)
    el = createComponent(tagName)
    return el(children, **attrs)

