def extract_table_names(query):
    """Extract table names from an SQL query."""
    tables_blocks = re.findall('(?:FROM|JOIN)\\s+(\\w+(?:\\s*,\\s*\\w+)*)', query, re.IGNORECASE)
    tables = [tbl for block in tables_blocks for tbl in re.findall('\\w+', block)]
    return set(tables)

def spherical_variogram_model(m, d):
    """Spherical model, m is [psill, range, nugget]"""
    psill = float(m[0])
    range_ = float(m[1])
    nugget = float(m[2])
    return np.piecewise(d, [d <= range_, d > range_], [lambda x: psill * (3.0 * x / (2.0 * range_) - x ** 3.0 / (2.0 * range_ ** 3.0)) + nugget, psill + nugget])

def calc_cR(Q2, sigma):
    """Returns the cR statistic for the variogram fit (see [1])."""
    return Q2 * np.exp(np.sum(np.log(sigma ** 2)) / sigma.shape[0])

def get_sort_field(model=None, sort_field='sort', order_name='asc'):
    """Get sort column info according request, the data format just likes:

        ?sort=fieldA.asc&sort=fieldB.desc

        or:

        ?sort=fieldA&sort=fieldB&order=asc&order=desc

    default order is 'asc'. `field` can be just like `model.field`
    :param model: default model, if no model existed in field
    :param sort_field: sort field name in request
    :param order_name: order field name in request, the order direction can be
        set in field, just like `model.field.asc` or `field.asc`, etc.
    :return:"""
    from uliweb import request
    if request.values.getlist('sort'):
        sort_fields = request.values.getlist('sort')
        order_by = []
        orders = request.values.getlist('order')
        for i, f in enumerate(sort_fields):
            _order = 'asc'
            if not orders:
                if f.endswith('.asc') or f.endswith('.desc'):
                    f, _order = f.rsplit('.', 1)
                else:
                    continue
            field = get_column(f, model)
            if field is not None:
                if orders:
                    _order = orders[i]
                if _order == 'asc':
                    order_by.append(field)
                else:
                    order_by.append(field.desc())
    else:
        order_by = None
    return order_by

def get_fields(model, fields, meta=None):
    """Acording to model and fields to get fields list
    Each field element is a two elements tuple, just like:
        (name, field_obj)"""
    model = get_model(model)
    if fields is not None:
        f = fields
    elif meta and hasattr(model, meta):
        m = getattr(model, meta)
        if hasattr(m, 'fields'):
            f = m.fields
        else:
            f = model._fields_list
    else:
        f = model._fields_list
    fields_list = []
    for x in f:
        field = {}
        if isinstance(x, str):
            field['name'] = x
        elif isinstance(x, tuple):
            field['name'] = x[0]
            field['field'] = x[1]
        elif isinstance(x, dict):
            field = x.copy()
        else:
            raise UliwebError('Field definition {!r} is not right, it should be just like (field_name, form_field_obj)'.format(x))
        if 'prop' not in field:
            if hasattr(model, field['name']):
                field['prop'] = getattr(model, field['name'])
            else:
                field['prop'] = None
        fields_list.append((field['name'], field))
    return fields_list

def get_columns(model=None, fields=None, meta=None):
    """Get model columns list"""
    if model:
        M = get_model(model)
    else:
        M = None
    if fields is not None:
        f = fields
    if M:
        if meta and hasattr(M, meta):
            m = getattr(model, meta)
            if hasattr(m, 'fields'):
                f = m.fields
            else:
                f = M._fields_list
        else:
            f = M._fields_list
    columns = []
    for x in f:
        if isinstance(x, str):
            field_name = x
        elif isinstance(x, dict):
            field_name = x['name']
        else:
            raise UliwebError("Field definition is not right, it should be just like str or {'name':xxx}")
        if '.' in field_name:
            model_name, field_name = field_name.split('.')
            M = get_model(model_name)
        if not M:
            raise UliwebError("Model can't be empty, because field name not has `model.` prefix")
        if field_name in M.c:
            columns.append(M.c[field_name])
    return columns

def get_model_columns(model, fields=None, meta='Table'):
    """Get fields info according model class, the fields just like ListView fields definition
    :param fields: A list
    :param meta: if no fields, it'll use meta"""
    from copy import deepcopy
    fields = fields or []
    model = functions.get_model(model)
    if not fields:
        if hasattr(model, meta):
            fields = getattr(model, meta).fields
        else:
            fields = [x for x, y in model._fields_list]
    fields_list = []
    for x in fields:
        if isinstance(x, (str, unicode)):
            f = get_grid_column(model, x)
        elif isinstance(x, dict):
            name = x['name']
            f = deepcopy(x)
            if 'verbose_name' in x:
                f['title'] = x['verbose_name']
            if 'title' not in f:
                f.update(get_grid_column(model, name))
        else:
            raise ValueError('Field should be string or dict type, but {!r} found'.format(x))
        fields_list.append(f)
    return fields_list

