        return (False, {'_': 'Creating user failed!'})

def get_commands(mod):
    """Find commands from a module"""
    import inspect
    import types
    commands = {}
    def check(c):
        return inspect.isclass(c) and issubclass(c, Command) and (c is not Command) and (not issubclass(c, CommandManager))
    for name in dir(mod):
        c = getattr(mod, name)
        if check(c):
            commands[c.name] = c
    return commands

def get_input(prompt, default=None, choices=None, option_value=None):
    """If option_value is not None, then return it. Otherwise get the result from
    input."""
    if option_value is not None:
        return option_value
    choices = choices or []
    while 1:
        r = raw_input(prompt + ' ').strip()
        if not r and default is not None:
            return default
        if choices:
            if r not in choices:
                r = None
            else:
                break
        else:
            break
    return r

