def find_actions(namespace, action_prefix):
    """Find all the actions in the namespace."""
    actions = {}
    for key, value in iteritems(namespace):
        if key.startswith(action_prefix):
            actions[key[len(action_prefix):]] = analyse_action(value)
    return actions

def print_usage(actions):
    """Print the usage information.  (Help screen)"""
    actions = actions.items()
    actions.sort()
    print('usage: %s <action> [<options>]' % basename(sys.argv[0]))
    print('       %s --help' % basename(sys.argv[0]))
    print()
    print('actions:')
    for name, (func, doc, arguments) in actions:
        print('  %s:' % name)
        for line in doc.splitlines():
            print('    %s' % line)
        if arguments:
            print()
        for arg, shortcut, default, argtype in arguments:
            if isinstance(default, bool):
                print('    %s' % ((shortcut and '-%s, ' % shortcut or '') + '--' + arg))
            else:
                print('    %-30s%-10s%s' % ((shortcut and '-%s, ' % shortcut or '') + '--' + arg, argtype, default))
        print()

def analyse_action(func):
    """Analyse a function."""
    description = inspect.getdoc(func) or 'undocumented action'
    arguments = []
    args, varargs, kwargs, defaults = inspect.getargspec(func)
    if varargs or kwargs:
        raise TypeError('variable length arguments for action not allowed.')
    if len(args) != len(defaults or ()):
        raise TypeError('not all arguments have proper definitions')
    for idx, (arg, definition) in enumerate(zip(args, defaults or ())):
        if arg.startswith('_'):
            raise TypeError('arguments may not start with an underscore')
        if not isinstance(definition, tuple):
            shortcut = None
            default = definition
        else:
            shortcut, default = definition
        argument_type = argument_types[type(default)]
        if isinstance(default, bool) and default is True:
            arg = 'no-' + arg
        arguments.append((arg.replace('_', '-'), shortcut, default, argument_type))
    return (func, description, arguments)

def make_shell(init_func=None, banner=None, use_ipython=True):
    """Returns an action callback that spawns a new interactive
    python shell.

    :param init_func: an optional initialization function that is
                      called before the shell is started.  The return
                      value of this function is the initial namespace.
    :param banner: the banner that is displayed before the shell.  If
                   not specified a generic banner is used instead.
    :param use_ipython: if set to `True` ipython is used if available."""
    if banner is None:
        banner = 'Interactive Werkzeug Shell'
    if init_func is None:
        init_func = dict
    def action(ipython=use_ipython):
        """Start a new interactive python session."""
        namespace = init_func()
        if ipython:
            try:
                try:
                    from IPython.frontend.terminal.embed import InteractiveShellEmbed
                    sh = InteractiveShellEmbed(banner1=banner)
                except ImportError:
                    from IPython.Shell import IPShellEmbed
                    sh = IPShellEmbed(banner=banner)
            except ImportError:
                pass
            else:
                sh(global_ns={}, local_ns=namespace)
                return
        from code import interact
        interact(banner, local=namespace)
    return action

def _line_parse(line):
    """Removes line ending characters and returns a tuple (`stripped_line`,
    `is_terminated`)."""
    if line[-2:] in ['\r\n', b'\r\n']:
        return (line[:-2], True)
    elif line[-1:] in ['\r', '\n', b'\r', b'\n']:
        return (line[:-1], True)
    return (line, False)

def parse_multipart_headers(iterable):
    """Parses multipart headers from an iterable that yields lines (including
    the trailing newline symbol).  The iterable has to be newline terminated.

    The iterable will stop at the line where the headers ended so it can be
    further consumed.

    :param iterable: iterable of strings that are newline terminated"""
    result = []
    for line in iterable:
        line = to_native(line)
        line, line_terminated = _line_parse(line)
        if not line_terminated:
            raise ValueError('unexpected end of line in multipart header')
        if not line:
            break
        elif line[0] in ' \t' and result:
            key, value = result[-1]
            result[-1] = (key, value + '\n ' + line[1:])
        else:
            parts = line.split(':', 1)
            if len(parts) == 2:
                result.append((parts[0].strip(), parts[1].strip()))
    return Headers(result)

def bind(topic, signal=None, kind=MIDDLE, nice=-1):
    """This is a decorator function, so you should use it as:

        @bind('init')
        def process_init(a, b):
            ..."""
    def f(func):
        if not topic in _receivers:
            receivers = _receivers[topic] = []
        else:
            receivers = _receivers[topic]
        if nice == -1:
            if kind == MIDDLE:
                n = 500
            elif kind == HIGH:
                n = 100
            else:
                n = 900
        else:
            n = nice
        if callable(func):
            func_name = func.__module__ + '.' + func.__name__
            func = func
        else:
            func_name = func
            func = None
        _f = (n, {'func': func, 'signal': signal, 'func_name': func_name})
        receivers.append(_f)
        return func
    return f

def unbind(topic, func):
    """Remove receiver function"""
    if topic in _receivers:
        receivers = _receivers[topic]
        for i in range(len(receivers) - 1, -1, -1):
            nice, f = receivers[i]
            if callable(func) and f['func'] == func or f['func_name'] == func:
                del receivers[i]
                return

def get(sender, topic, *args, **kwargs):
    """Invoke receiver functions according topic, it'll invoke receiver functions one by one,
    and if one receiver function return non-None value, it'll return it and break
    the loop."""
    if not topic in _receivers:
        return
    items = _receivers[topic]
    def _cmp(x, y):
        return cmp(x[0], y[0])
    items.sort(_cmp)
    for i in range(len(items)):
        nice, f = items[i]
        _f = f['func']
        if not _f:
            try:
                _f = import_attr(f['func_name'])
            except ImportError:
                logging.error("Can't import function %s" % f['func_name'])
                raise
            f['func'] = _f
        if callable(_f):
            if not _test(kwargs, f):
                continue
            try:
                v = _f(sender, *args, **kwargs)
            except:
                func = _f.__module__ + '.' + _f.__name__
                logging.exception('Calling dispatch point [%s] %s(%r,%r) error!' % (topic, func, args, kwargs))
                raise
            if v is not None:
                return v
        else:
            raise "Dispatch point [%s] %r can't been invoked" % (topic, _f)

def find_model(sender, model_name):
    """Register new model to ORM"""
    MC = get_mc()
    model = MC.get((MC.c.model_name == model_name) & (MC.c.uuid != ''))
    if model:
        model_inst = model.get_instance()
        orm.set_model(model_name, model_inst.table_name, appname=__name__, model_path='')
        return orm.__models__.get(model_name)

def get_model(sender, model_name, model_inst, model_info, model_config):
    """#todo Add objcache support"""
    MC = get_mc()
    if MC:
        model = MC.get((MC.c.model_name == model_name) & (MC.c.uuid != ''))
        if model:
            cached_inst = __cache__.get(model_name)
            if not cached_inst or (cached_inst and cached_inst[1] != model.uuid):
                model_inst = model.get_instance()
                M = orm.create_model(model_name, fields=eval(model_inst.fields or '[]'), indexes=eval(model_inst.indexes or '[]'), basemodel=model_inst.basemodel, __replace__=True)
                __cache__[model_name] = (M, model.uuid)
                if model_inst.has_extension:
                    ext_model_name = model_name + '_extension'
                    fields = eval(model_inst.extension_fields or '[]')
                    fields.insert(0, {'name': '_parent', 'type': 'OneToOne', 'reference_class': model_name, 'collection_name': 'ext'})
                    ME = orm.create_model(ext_model_name, fields=fields, indexes=eval(model_inst.extension_indexes or '[]'), basemodel=model_inst.extension_model, __replace__=True)
            else:
                M = cached_inst[0]
            return M

def get_model_fields(model, add_reserver_flag=True):
    """Creating fields suit for model_config , id will be skipped."""
    import uliweb.orm as orm
    fields = []
    m = {'type': 'type_name', 'hint': 'hint', 'default': 'default', 'required': 'required'}
    m1 = {'index': 'index', 'unique': 'unique'}
    for name, prop in model.properties.items():
        if name == 'id':
            continue
        d = {}
        for k, v in m.items():
            d[k] = getattr(prop, v)
        for k, v in m1.items():
            d[k] = bool(prop.kwargs.get(v))
        d['name'] = prop.fieldname or name
        d['verbose_name'] = unicode(prop.verbose_name)
        d['nullable'] = bool(prop.kwargs.get('nullable', orm.__nullable__))
        if d['type'] in ('VARCHAR', 'CHAR', 'BINARY', 'VARBINARY'):
            d['max_length'] = prop.max_length
        if d['type'] in ('Reference', 'OneToOne', 'ManyToMany'):
            d['reference_class'] = prop.reference_class
            d['collection_name'] = prop._collection_name
        d['server_default'] = prop.kwargs.get('server_default')
        d['_reserved'] = True
        fields.append(d)
    return fields

def host_is_trusted(hostname, trusted_list):
    """Checks if a host is trusted against a list.  This also takes care
    of port normalization.

    .. versionadded:: 0.9

    :param hostname: the hostname to check
    :param trusted_list: a list of hostnames to check against.  If a
                         hostname starts with a dot it will match against
                         all subdomains as well."""
    if not hostname:
        return False
    if isinstance(trusted_list, string_types):
        trusted_list = [trusted_list]
    def _normalize(hostname):
        if ':' in hostname:
            hostname = hostname.rsplit(':', 1)[0]
        return _encode_idna(hostname)
    hostname = _normalize(hostname)
    for ref in trusted_list:
        if ref.startswith('.'):
            ref = ref[1:]
            suffix_match = True
        else:
            suffix_match = False
        ref = _normalize(ref)
        if ref == hostname:
            return True
        if suffix_match and hostname.endswith('.' + ref):
            return True
    return False

def get_content_length(environ):
    """Returns the content length from the WSGI environment as
    integer.  If it's not available `None` is returned.

    .. versionadded:: 0.9

    :param environ: the WSGI environ to fetch the content length from."""
    content_length = environ.get('CONTENT_LENGTH')
    if content_length is not None:
        try:
            return max(0, int(content_length))
        except (ValueError, TypeError):
            pass

def _default_json_default(obj):
    """Coerce everything to strings.
    All objects representing time get output as ISO8601."""
    if isinstance(obj, (datetime.datetime, datetime.date, datetime.time)):
        return obj.isoformat()
    else:
        return str(obj)

def scope_compose(scope, name, sep=private.SCOPE_SEPARATOR):
    """compose a new scope

    :param str scope: current scope
    :param str name: name of next level in scope
    :return the composed scope"""
    if name == None:
        new_scope = scope
    else:
        new_scope = scope if scope else name
    if scope and name:
        new_scope = scope + sep + name
    return new_scope

def import_string(name):
    """import module
    """
    mod = fp = None
    try:
        return sys.modules[name]
    except KeyError:
        pass
    try:
        fp, pathname, desc = imp.find_module(name)
        mod = imp.load_module(name, fp, pathname, desc)
    except ImportError:
        mod = None
    finally:
        if fp:
            fp.close()
    return mod

def jp_compose(s, base=None):
    """append/encode a string to json-pointer
    """
    if s == None:
        return base
    ss = [s] if isinstance(s, six.string_types) else s
    ss = [s.replace('~', '~0').replace('/', '~1') for s in ss]
    if base:
        ss.insert(0, base)
    return '/'.join(ss)

def jp_split(s):
    """split/decode a string from json-pointer
    """
    if s == '' or s == None:
        return []
    def _decode(s):
        s = s.replace('~1', '/')
        return s.replace('~0', '~')
    return [_decode(ss) for ss in s.split('/')]

def jr_split(s):
    """split a json-reference into (url, json-pointer)
    """
    p = six.moves.urllib.parse.urlparse(s)
    return (normalize_url(six.moves.urllib.parse.urlunparse(p[:5] + ('',))), '#' + p.fragment if p.fragment else '#')

def nv_tuple_list_replace(l, v):
    """replace a tuple in a tuple list
    """
    _found = False
    for i, x in enumerate(l):
        if x[0] == v[0]:
            l[i] = v
            _found = True
    if not _found:
        l.append(v)

def path2url(p):
    """Return file:// URL from a filename.
    """
    if sys.version_info.major >= 3 and sys.version_info.minor >= 4:
        import pathlib
        return pathlib.Path(p).as_uri()
    else:
        return six.moves.urllib.parse.urljoin('file:', six.moves.urllib.request.pathname2url(p))

def normalize_url(url):
    """Normalize url
    """
    if not url:
        return url
    matched = _windows_path_prefix.match(url)
    if matched:
        return path2url(url)
    p = six.moves.urllib.parse.urlparse(url)
    if p.scheme == '':
        if p.netloc == '' and p.path != '':
            url = path2url(os.path.abspath(url))
        else:
            raise ValueError('url should be a http-url or file path -- ' + url)
    return url

def url_dirname(url):
    """Return the folder containing the '.json' file
    """
    p = six.moves.urllib.parse.urlparse(url)
    for e in [private.FILE_EXT_JSON, private.FILE_EXT_YAML]:
        if p.path.endswith(e):
            return six.moves.urllib.parse.urlunparse(p[:2] + (os.path.dirname(p.path),) + p[3:])
    return url

def url_join(url, path):
    """url version of os.path.join
    """
    p = six.moves.urllib.parse.urlparse(url)
    t = None
    if p.path and p.path[-1] == '/':
        if path and path[0] == '/':
            path = path[1:]
        t = ''.join([p.path, path])
    else:
        t = ('' if path and path[0] == '/' else '/').join([p.path, path])
    return six.moves.urllib.parse.urlunparse(p[:2] + (t,) + p[3:])

def derelativise_url(url):
    """Normalizes URLs, gets rid of .. and ."""
    parsed = six.moves.urllib.parse.urlparse(url)
    newpath = []
    for chunk in parsed.path[1:].split('/'):
        if chunk == '.':
            continue
        elif chunk == '..':
            newpath = newpath[:-1]
            continue
        elif _fullmatch('\\.{3,}', chunk) is not None:
            newpath = newpath[:-1]
            continue
        newpath += [chunk]
    return six.moves.urllib.parse.urlunparse(parsed[:2] + ('/' + '/'.join(newpath),) + parsed[3:])

def walk(start, ofn, cyc=None):
    """Non recursive DFS to detect cycles

    :param start: start vertex in graph
    :param ofn: function to get the list of outgoing edges of a vertex
    :param cyc: list of existing cycles, cycles are represented in a list started with minimum vertex.
    :return: cycles
    :rtype: list of lists"""
    ctx, stk = ({}, [start])
    cyc = [] if cyc == None else cyc
    while len(stk):
        top = stk[-1]
        if top not in ctx:
            ctx.update({top: list(ofn(top))})
        if len(ctx[top]):
            n = ctx[top][0]
            if n in stk:
                nc = stk[stk.index(n):]
                ni = nc.index(min(nc))
                nc = nc[ni:] + nc[:ni] + [min(nc)]
                if nc not in cyc:
                    cyc.append(nc)
                ctx[top].pop(0)
            else:
                stk.append(n)
        else:
            ctx.pop(top)
            stk.pop()
            if len(stk):
                ctx[stk[-1]].remove(top)
    return cyc

def min_max(obj, val, is_max):
    """min/max validator for float and integer
    """
    n = getattr(obj, 'maximum' if is_max else 'minimum', None)
    if n == None:
        return
    _eq = getattr(obj, 'exclusiveMaximum' if is_max else 'exclusiveMinimum', False)
    if is_max:
        to_raise = val >= n if _eq else val > n
    else:
        to_raise = val <= n if _eq else val < n
    if to_raise:
        raise ValidationError('condition failed: {0}, v:{1} compared to o:{2}'.format('maximum' if is_max else 'minimum', val, n))

def default_tree_traversal(root, leaves):
    """default tree traversal"""
    objs = [('#', root)]
    while len(objs) > 0:
        path, obj = objs.pop()
        if obj.__class__ not in leaves:
            objs.extend(map(lambda i: (path + '/' + i[0],) + (i[1],), six.iteritems(obj._children_)))
        yield (path, obj)

def _method_(name):
    """getter factory"""
    def _getter_(self):
        return getattr(self, self.get_private_name(name))
    return _getter_

def _check_elementary_axis_name(name: str) -> bool:
    """Valid elementary axes contain only lower latin letters and digits and start with a letter."""
    if len(name) == 0:
        return False
    if not 'a' <= name[0] <= 'z':
        return False
    for letter in name:
        if not letter.isdigit() and (not 'a' <= letter <= 'z'):
            return False
    return True

def get_backend(tensor):
    """Takes a correct backend (e.g. numpy backend if tensor is numpy.ndarray) for a tensor.
    If needed, imports package and creates backend"""
    for framework_name, backend in _backends.items():
        if backend.is_appropriate_type(tensor):
            return backend
    for BackendSubclass in AbstractBackend.__subclasses__():
        if _debug_importing:
            print('Testing for subclass of ', BackendSubclass)
        if BackendSubclass.framework_name not in _backends:
            if BackendSubclass.framework_name in sys.modules:
                if _debug_importing:
                    print('Imported backend for ', BackendSubclass.framework_name)
                backend = BackendSubclass()
                _backends[backend.framework_name] = backend
                if backend.is_appropriate_type(tensor):
                    return backend
    raise RuntimeError('Tensor type unknown to einops {}'.format(type(tensor)))

def xml2text(xml):
    """A string representing the textual content of this run, with content
    child elements like ``<w:tab/>`` translated to their Python
    equivalent.
    Adapted from: https://github.com/python-openxml/python-docx/"""
    text = u''
    root = ET.fromstring(xml)
    for child in root.iter():
        if child.tag == qn('w:t'):
            t_text = child.text
            text += t_text if t_text is not None else ''
        elif child.tag == qn('w:tab'):
            text += '\t'
        elif child.tag in (qn('w:br'), qn('w:cr')):
            text += '\n'
        elif child.tag == qn('w:p'):
            text += '\n\n'
    return text

