def verify_otp(request):
    """Verify a OTP request"""
    ctx = {}
    if request.method == 'POST':
        verification_code = request.POST.get('verification_code')
        if verification_code is None:
            ctx['error_message'] = 'Missing verification code.'
        else:
            otp_ = UserOTP.objects.get(user=request.user)
            totp_ = totp.TOTP(otp_.secret_key)
            is_verified = totp_.verify(verification_code)
            if is_verified:
                request.session['verfied_otp'] = True
                response = redirect(request.POST.get('next', settings.LOGIN_REDIRECT_URL))
                return update_rmb_cookie(request, response)
            ctx['error_message'] = 'Your code is expired or invalid.'
    ctx['next'] = request.GET.get('next', settings.LOGIN_REDIRECT_URL)
    return render(request, 'django_mfa/login_verify.html', ctx, status=400)

def build_uri(secret, name, initial_count=None, issuer_name=None):
    """Returns the provisioning URI for the OTP; works for either TOTP or HOTP.

    This can then be encoded in a QR Code and used to provision the Google
    Authenticator app.

    For module-internal use.

    See also:
        http://code.google.com/p/google-authenticator/wiki/KeyUriFormat

    @param [String] the hotp/totp secret used to generate the URI
    @param [String] name of the account
    @param [Integer] initial_count starting counter value, defaults to None.
        If none, the OTP type will be assumed as TOTP.
    @param [String] the name of the OTP issuer; this will be the
        organization title of the OTP entry in Authenticator
    @return [String] provisioning uri"""
    is_initial_count_present = initial_count is not None
    otp_type = 'hotp' if is_initial_count_present else 'totp'
    base = 'otpauth://%s/' % otp_type
    if issuer_name:
        issuer_name = quote(issuer_name)
        base += '%s:' % issuer_name
    uri = '%(base)s%(name)s?secret=%(secret)s' % {'name': quote(name, safe='@'), 'secret': secret, 'base': base}
    if is_initial_count_present:
        uri += '&counter=%s' % initial_count
    if issuer_name:
        uri += '&issuer=%s' % issuer_name
    return uri

def strings_equal(s1, s2):
    """Timing-attack resistant string comparison.

    Normal comparison using == will short-circuit on the first mismatching
    character. This avoids that by scanning the whole string, though we
    still reveal to a timing attack whether the strings are the same
    length."""
    try:
        s1 = unicodedata.normalize('NFKC', str(s1))
        s2 = unicodedata.normalize('NFKC', str(s2))
    except:
        s1 = unicodedata.normalize('NFKC', unicode(s1))
        s2 = unicodedata.normalize('NFKC', unicode(s2))
    return compare_digest(s1, s2)

def babel_compile(source, **kwargs):
    """Compiles the given ``source`` from ES6 to ES5 using Babeljs"""
    presets = kwargs.get('presets')
    if not presets:
        kwargs['presets'] = ['es2015']
