def _render_sources(dataset, tables):
    """Render the source part of a query.

    Parameters
    ----------
    dataset : str
        The data set to fetch log data from.
    tables : Union[dict, list]
        The tables to fetch log data from

    Returns
    -------
    str
        A string that represents the "from" part of a query."""
    if isinstance(tables, dict):
        if tables.get('date_range', False):
            try:
                dataset_table = '.'.join([dataset, tables['table']])
                return "FROM (TABLE_DATE_RANGE([{}], TIMESTAMP('{}'), TIMESTAMP('{}'))) ".format(dataset_table, tables['from_date'], tables['to_date'])
            except KeyError as exp:
                logger.warn('Missing parameter %s in selecting sources' % exp)
    else:
        return 'FROM ' + ', '.join(['[%s.%s]' % (dataset, table) for table in tables])

def formatException(type, value, tb):
    """Format traceback, darkening entries from global site-packages directories
    and user-specific site-packages directory.

    https://stackoverflow.com/a/46071447/5156190"""
    packages = tuple((join(abspath(p), '') for p in sys.path[1:]))
    lines = []
    for line in format_exception(type, value, tb):
        matches = re.search('^  File \\"([^\\"]+)\\", line \\d+, in .+', line)
        if matches and matches.group(1).startswith(packages):
            lines += line
        else:
            matches = re.search('^(\\s*)(.*?)(\\s*)$', line, re.DOTALL)
            lines.append(matches.group(1) + colored(matches.group(2), 'yellow') + matches.group(3))
    return ''.join(lines).rstrip()

def get_char(prompt=None):
    """Read a line of text from standard input and return the equivalent char;
    if text is not a single char, user is prompted to retry. If line can't
    be read, return None."""
    while True:
        s = get_string(prompt)
        if s is None:
            return None
        if len(s) == 1:
            return s[0]
        if prompt is None:
            print('Retry: ', end='')

def get_float(prompt=None):
    """Read a line of text from standard input and return the equivalent float
    as precisely as possible; if text does not represent a double, user is
    prompted to retry. If line can't be read, return None."""
    while True:
        s = get_string(prompt)
        if s is None:
            return None
        if len(s) > 0 and re.search('^[+-]?\\d*(?:\\.\\d*)?$', s):
            try:
                return float(s)
            except ValueError:
                pass
        if prompt is None:
            print('Retry: ', end='')

def get_int(prompt=None):
    """Read a line of text from standard input and return the equivalent int;
    if text does not represent an int, user is prompted to retry. If line
    can't be read, return None."""
    while True:
        s = get_string(prompt)
        if s is None:
            return None
        if re.search('^[+-]?\\d+$', s):
            try:
                i = int(s, 10)
                if type(i) is int:
                    return i
            except ValueError:
                pass
        if prompt is None:
            print('Retry: ', end='')

def get_string(prompt=None):
    """    Read a line of text from standard input and return it as a string,
        sans trailing line ending. Supports CR (\r), LF (
    ), and CRLF (
    )
        as line endings. If user inputs only a line ending, returns "", not None.
        Returns None upon error or no input whatsoever (i.e., just EOF). Exits
        from Python altogether on SIGINT.
    """
    try:
        if prompt is not None:
            print(prompt, end='')
        s = sys.stdin.readline()
        if not s:
            return None
        return re.sub('(?:\\r|\\r\\n|\\n)$', '', s)
    except KeyboardInterrupt:
        sys.exit('')
    except ValueError:
        return None

def _connect(dbapi_connection, connection_record):
