def padRectEqually(rect, padding, bounds, clipExcess=True):
    """Applies equal padding to all sides of a rectangle,
    ensuring the padded rectangle falls within the specified bounds.

    The input rectangle, bounds, and return value are all a tuple of (x,y,w,h)."""
    return padRect(rect, padding, padding, padding, padding, bounds, clipExcess)

def squareAspect(rect):
    """Crops either the width or height, as necessary, to make a rectangle into a square.

    The input rectangle and return value are both a tuple of (x,y,w,h)."""
    x, y, w, h = rect
    if w > h:
        cropX = (w - h) // 2
        return cropRect(rect, 0, 0, cropX, cropX)
    elif w < h:
        cropY = (h - w) // 2
        return cropRect(rect, cropY, cropY, 0, 0)
    return rect

def _requiredSize(shape, dtype):
    """Determines the number of bytes required to store a NumPy array with
    the specified shape and datatype."""
    return math.floor(np.prod(np.asarray(shape, dtype=np.uint64)) * np.dtype(dtype).itemsize)

def arrayFactory(shape, dtype=float):
    """Creates a new ndarray of the specified shape and datatype, storing
    it in memory if there is sufficient available space or else using
    a memory-mapped temporary file to provide the underlying buffer."""
    requiredBytes = _requiredSize(shape, dtype)
    vmem = psutil.virtual_memory()
    if vmem.available > requiredBytes:
        return np.ndarray(shape=shape, dtype=dtype)
    else:
        return TempfileBackedArray(shape=shape, dtype=dtype)

def arrayCast(source, dtype):
    """Casts a NumPy array to the specified datatype, storing the copy
    in memory if there is sufficient available space or else using a
    memory-mapped temporary file to provide the underlying buffer."""
    requiredBytes = _requiredSize(source.shape, dtype)
    vmem = psutil.virtual_memory()
    if vmem.available > requiredBytes:
        return source.astype(dtype, subok=False)
    else:
        dest = arrayFactory(source.shape, dtype)
        np.copyto(dest, source, casting='unsafe')
        return dest

def _fullname(o):
    """Return the fully-qualified name of a function."""
    return o.__module__ + '.' + o.__name__ if o.__module__ else o.__name__

def require_qt(func):
    """Specify that a function requires a Qt application.

    Use this decorator to specify that a function needs a running
    Qt application before it can run. An error is raised if that is not
    the case."""
    @wraps(func)
    def wrapped(*args, **kwargs):
        if not QApplication.instance():
            raise RuntimeError('A Qt application must be created.')
        return func(*args, **kwargs)
    return wrapped

def _parse_list(s):
    """Parse a comma-separated list of values (strings or numbers)."""
    if '-' in s:
        m, M = map(_parse_arg, s.split('-'))
        return list(range(m, M + 1))
    elif ',' in s:
        return list(map(_parse_arg, s.split(',')))
    else:
        return _parse_arg(s)

def _wrap_callback_args(f, docstring=None):
    """Display a Qt dialog when a function has arguments.

    The user can write function arguments as if it was a snippet."""
    def wrapped(checked, *args):
        if args:
            return f(*args)
        if isinstance(f, partial):
            argspec = inspect.getargspec(f.func)
        else:
            argspec = inspect.getargspec(f)
        f_args = argspec.args
        if 'self' in f_args:
            f_args.remove('self')
        if len(argspec.defaults or ()):
            f_args = f_args[:-len(argspec.defaults)]
        if isinstance(f, partial):
            f_args = f_args[len(f.args):]
            f_args = [arg for arg in f_args if arg not in f.keywords]
        if not f_args:
            return f()
        r = re.search('Example: `([^`]+)`', docstring)
        docstring_ = docstring[:r.start()].strip() if r else docstring
        text = r.group(1) if r else None
        s, ok = _input_dialog(getattr(f, '__name__', 'action'), docstring_, text)
        if not ok or not s:
            return
        args = _parse_snippet(s)
        return f(*args)
    return wrapped

def _get_shortcut_string(shortcut):
    """Return a string representation of a shortcut."""
    if shortcut is None:
        return ''
    if isinstance(shortcut, (tuple, list)):
        return ', '.join([_get_shortcut_string(s) for s in shortcut])
    if isinstance(shortcut, string_types):
        if hasattr(QKeySequence, shortcut):
            shortcut = QKeySequence(getattr(QKeySequence, shortcut))
        else:
            return shortcut.lower()
    assert isinstance(shortcut, QKeySequence)
    s = shortcut.toString() or ''
    return str(s).lower()

def _get_qkeysequence(shortcut):
    """Return a QKeySequence or list of QKeySequence from a shortcut string."""
    if shortcut is None:
        return []
    if isinstance(shortcut, (tuple, list)):
        return [_get_qkeysequence(s) for s in shortcut]
    assert isinstance(shortcut, string_types)
    if hasattr(QKeySequence, shortcut):
        return QKeySequence(getattr(QKeySequence, shortcut))
    sequence = QKeySequence.fromString(shortcut)
    assert not sequence.isEmpty()
    return sequence

def _show_shortcuts(shortcuts, name=None):
    """Display shortcuts."""
    name = name or ''
    print('')
    if name:
        name = ' for ' + name
    print('Keyboard shortcuts' + name)
    for name in sorted(shortcuts):
        shortcut = _get_shortcut_string(shortcuts[name])
        if not name.startswith('_'):
            print('- {0:<40}: {1:s}'.format(name, shortcut))

def _before_after(n_samples):
    """Get the number of samples before and after."""
    if not isinstance(n_samples, (tuple, list)):
        before = n_samples // 2
        after = n_samples - before
    else:
        assert len(n_samples) == 2
        before, after = n_samples
        n_samples = before + after
    assert before >= 0
    assert after >= 0
    assert before + after == n_samples
    return (before, after)

def _md5(path, blocksize=2 ** 20):
    """Compute the checksum of a file."""
    m = hashlib.md5()
    with open(path, 'rb') as f:
        while True:
            buf = f.read(blocksize)
            if not buf:
                break
            m.update(buf)
    return m.hexdigest()

def _make_class(cls, **kwargs):
    """Return a custom Visual class with given parameters."""
    kwargs = {k: v if v is not None else getattr(cls, k, None) for k, v in kwargs.items()}
    name = cls.__name__ + '_' + _hash(kwargs)
    if name not in _CLASSES:
        logger.log(5, 'Create class %s %s.', name, kwargs)
        cls = type(name, (cls,), kwargs)
        _CLASSES[name] = cls
    return _CLASSES[name]

def _range_from_slice(myslice, start=None, stop=None, step=None, length=None):
    """Convert a slice to an array of integers."""
    assert isinstance(myslice, slice)
    step = myslice.step if myslice.step is not None else step
    if step is None:
        step = 1
    start = myslice.start if myslice.start is not None else start
    if start is None:
        start = 0
    stop = myslice.stop if myslice.stop is not None else stop
    if length is not None:
        stop_inferred = floor(start + step * length)
        if stop is not None and stop < stop_inferred:
            raise ValueError("'stop' ({stop}) and ".format(stop=stop) + "'length' ({length}) ".format(length=length) + 'are not compatible.')
        stop = stop_inferred
    if stop is None and length is None:
        raise ValueError("'stop' and 'length' cannot be both unspecified.")
    myrange = np.arange(start, stop, step)
    if length is not None:
        assert len(myrange) == length
    return myrange

def _unique(x):
    """Faster version of np.unique().

    This version is restricted to 1D arrays of non-negative integers.

    It is only faster if len(x) >> len(unique(x))."""
    if x is None or len(x) == 0:
        return np.array([], dtype=np.int64)
    x = _as_array(x)
    x = x[x >= 0]
    bc = np.bincount(x)
    return np.nonzero(bc)[0]

def _pad(arr, n, dir='right'):
    """Pad an array with zeros along the first axis.

    Parameters
    ----------

    n : int
        Size of the returned array in the first axis.
    dir : str
        Direction of the padding. Must be one 'left' or 'right'."""
    assert dir in ('left', 'right')
    if n < 0:
        raise ValueError("'n' must be positive: {0}.".format(n))
    elif n == 0:
        return np.zeros((0,) + arr.shape[1:], dtype=arr.dtype)
    n_arr = arr.shape[0]
    shape = (n,) + arr.shape[1:]
    if n_arr == n:
        assert arr.shape == shape
        return arr
    elif n_arr < n:
        out = np.zeros(shape, dtype=arr.dtype)
        if dir == 'left':
            out[-n_arr:, ...] = arr
        elif dir == 'right':
            out[:n_arr, ...] = arr
        assert out.shape == shape
        return out
    else:
        if dir == 'left':
            out = arr[-n:, ...]
        elif dir == 'right':
            out = arr[:n, ...]
        assert out.shape == shape
        return out

def _get_padded(data, start, end):
    """Return `data[start:end]` filling in with zeros outside array bounds

    Assumes that either `start<0` or `end>len(data)` but not both."""
    if start < 0 and end > data.shape[0]:
        raise RuntimeError()
    if start < 0:
        start_zeros = np.zeros((-start, data.shape[1]), dtype=data.dtype)
        return np.vstack((start_zeros, data[:end]))
    elif end > data.shape[0]:
        end_zeros = np.zeros((end - data.shape[0], data.shape[1]), dtype=data.dtype)
        return np.vstack((data[start:], end_zeros))
    else:
        return data[start:end]

def read_array(path, mmap_mode=None):
    """Read a .npy array."""
    file_ext = op.splitext(path)[1]
    if file_ext == '.npy':
        return np.load(path, mmap_mode=mmap_mode)
    raise NotImplementedError('The file extension `{}` '.format(file_ext) + 'is not currently supported.')

def write_array(path, arr):
    """Write an array to a .npy file."""
    file_ext = op.splitext(path)[1]
    if file_ext == '.npy':
        return np.save(path, arr)
    raise NotImplementedError('The file extension `{}` '.format(file_ext) + 'is not currently supported.')

def _start_stop(item):
    """Find the start and stop indices of a __getitem__ item.

    This is used only by ConcatenatedArrays.

    Only two cases are supported currently:

    * Single integer.
    * Contiguous slice in the first dimension only."""
    if isinstance(item, tuple):
        item = item[0]
    if isinstance(item, slice):
        if item.step not in (None, 1):
            raise NotImplementedError()
        return (item.start, item.stop)
    elif isinstance(item, (list, np.ndarray)):
        return (np.min(item), np.max(item))
    else:
        return (item, item + 1)

def _concatenate_virtual_arrays(arrs, cols=None, scaling=None):
    """Return a virtual concatenate of several NumPy arrays."""
    return None if not len(arrs) else ConcatenatedArrays(arrs, cols, scaling=scaling)

def excerpts(n_samples, n_excerpts=None, excerpt_size=None):
    """Yield (start, end) where start is included and end is excluded."""
    assert n_excerpts >= 2
    step = _excerpt_step(n_samples, n_excerpts=n_excerpts, excerpt_size=excerpt_size)
    for i in range(n_excerpts):
        start = i * step
        if start >= n_samples:
            break
        end = min(start + excerpt_size, n_samples)
        yield (start, end)

def data_chunk(data, chunk, with_overlap=False):
    """Get a data chunk."""
    assert isinstance(chunk, tuple)
    if len(chunk) == 2:
        i, j = chunk
    elif len(chunk) == 4:
        if with_overlap:
            i, j = chunk[:2]
        else:
            i, j = chunk[2:]
    else:
        raise ValueError("'chunk' should have 2 or 4 elements, not {0:d}".format(len(chunk)))
    return data[i:j, ...]

def _spikes_in_clusters(spike_clusters, clusters):
    """Return the ids of all spikes belonging to the specified clusters."""
    if len(spike_clusters) == 0 or len(clusters) == 0:
        return np.array([], dtype=np.int)
    return np.nonzero(np.in1d(spike_clusters, clusters))[0]

def _flatten_per_cluster(per_cluster):
    """Convert a dictionary {cluster: spikes} to a spikes array."""
    return np.sort(np.concatenate(list(per_cluster.values()))).astype(np.int64)

def select_spikes(cluster_ids=None, max_n_spikes_per_cluster=None, spikes_per_cluster=None, batch_size=None, subset=None):
    """Return a selection of spikes belonging to the specified clusters."""
    subset = subset or 'regular'
    assert _is_array_like(cluster_ids)
    if not len(cluster_ids):
        return np.array([], dtype=np.int64)
    if max_n_spikes_per_cluster in (None, 0):
        selection = {c: spikes_per_cluster(c) for c in cluster_ids}
    else:
        assert max_n_spikes_per_cluster > 0
        selection = {}
        n_clusters = len(cluster_ids)
        for cluster in cluster_ids:
            n = int(max_n_spikes_per_cluster * exp(-0.1 * (n_clusters - 1)))
            n = max(1, n)
            spike_ids = spikes_per_cluster(cluster)
            if subset == 'regular':
                if batch_size is None or len(spike_ids) <= max(batch_size, n):
                    spike_ids = regular_subset(spike_ids, n_spikes_max=n)
                else:
                    spike_ids = get_excerpts(spike_ids, n // batch_size, batch_size)
            elif subset == 'random' and len(spike_ids) > n:
                spike_ids = np.random.choice(spike_ids, n, replace=False)
                spike_ids = np.unique(spike_ids)
            selection[cluster] = spike_ids
    return _flatten_per_cluster(selection)

def _accumulate(data_list, no_concat=()):
    """Concatenate a list of dicts `(name, array)`.

    You can specify some names which arrays should not be concatenated.
    This is necessary with lists of plots with different sizes."""
    acc = Accumulator()
    for data in data_list:
        for name, val in data.items():
            acc.add(name, val)
    out = {name: acc[name] for name in acc.names if name not in no_concat}
    out.update({name: acc.get(name) for name in no_concat})
    return out

def bandpass_filter(rate=None, low=None, high=None, order=None):
    """Butterworth bandpass filter."""
    assert low < high
    assert order >= 1
    return signal.butter(order, (low / (rate / 2.0), high / (rate / 2.0)), 'pass')

def apply_filter(x, filter=None, axis=0):
    """Apply a filter to an array."""
    x = _as_array(x)
    if x.shape[axis] == 0:
        return x
    b, a = filter
    return signal.filtfilt(b, a, x, axis=axis)

def _run_cmd(cmd, ctx, glob, loc):
    """Run a command with optionally a debugger, IPython, or profiling."""
    if PDB:
        _enable_pdb()
    if IPYTHON:
        from IPython import start_ipython
        args_ipy = ['-i', '--gui=qt']
        ns = glob.copy()
        ns.update(loc)
        return start_ipython(args_ipy, user_ns=ns)
    prof = __builtins__.get('profile', None)
    if prof:
        prof = __builtins__['profile']
        return _profile(prof, cmd, glob, loc)
    return exec_(cmd, glob, loc)

def load_cli_plugins(cli, config_dir=None):
    """Load all plugins and attach them to a CLI object."""
    from .config import load_master_config
    config = load_master_config(config_dir=config_dir)
    plugins = discover_plugins(config.Plugins.dirs)
    for plugin in plugins:
        if not hasattr(plugin, 'attach_to_cli'):
            continue
        logger.debug('Attach plugin `%s` to CLI.', _fullname(plugin))
        try:
            plugin().attach_to_cli(cli)
        except Exception as e:
