def _iter_vars(mod):
    """Iterate through a list of variables define in a module's
    public namespace."""
    vars = sorted((var for var in dir(mod) if _is_public(var)))
    for var in vars:
        yield getattr(mod, var)

def _function_header(subpackage, func):
    """Generate the docstring of a function."""
    args = inspect.formatargspec(*inspect.getfullargspec(func))
    return '{name}{args}'.format(name=_full_name(subpackage, func), args=args)

def _doc_method(klass, func):
    """Generate the docstring of a method."""
    argspec = inspect.getfullargspec(func)
    if argspec.args and argspec.args[0] == 'self':
        del argspec.args[0]
    args = inspect.formatargspec(*argspec)
    header = '{klass}.{name}{args}'.format(klass=klass.__name__, name=_name(func), args=args)
    docstring = _doc(func)
    return _concat(header, docstring)

def _doc_property(klass, prop):
    """Generate the docstring of a property."""
    header = '{klass}.{name}'.format(klass=klass.__name__, name=_name(prop))
    docstring = _doc(prop)
    return _concat(header, docstring)

def _generate_paragraphs(package, subpackages):
    """Generate the paragraphs of the API documentation."""
    for subpackage in _iter_subpackages(package, subpackages):
        subpackage_name = subpackage.__name__
        yield '## {}'.format(subpackage_name)
        yield _doc(_import_module(subpackage_name))
        for func in _iter_functions(subpackage):
            yield ('##### ' + _doc_function(subpackage, func))
        for klass in _iter_classes(subpackage):
            yield '### {}'.format(_full_name(subpackage, klass))
            yield _doc(klass)
            yield '#### Methods'
            for method in _iter_methods(klass, package):
                yield ('##### ' + _doc_method(klass, method))
            yield '#### Properties'
            for prop in _iter_properties(klass, package):
                yield ('##### ' + _doc_property(klass, prop))

def _process_ups(ups):
    """This function processes the UpdateInfo instances of the two
    undo stacks (clustering and cluster metadata) and concatenates them
    into a single UpdateInfo instance."""
    if len(ups) == 0:
        return
    elif len(ups) == 1:
        return ups[0]
    elif len(ups) == 2:
        up = ups[0]
        up.update(ups[1])
        return up
    else:
        raise NotImplementedError()

def create_cluster_meta(cluster_groups):
    """Return a ClusterMeta instance with cluster group support."""
    meta = ClusterMeta()
    meta.add_field('group')
    cluster_groups = cluster_groups or {}
    data = {c: {'group': v} for c, v in cluster_groups.items()}
    meta.from_dict(data)
    return meta

def _binary_search(f, xmin, xmax, eps=1e-09):
    """Return the largest x such f(x) is True."""
    middle = (xmax + xmin) / 2.0
    while xmax - xmin > eps:
        assert xmin < xmax
        middle = (xmax + xmin) / 2.0
        if f(xmax):
            return xmax
        if not f(xmin):
            return xmin
        if f(middle):
            xmin = middle
        else:
            xmax = middle
    return middle

def _get_array(val, shape, default=None, dtype=np.float64):
    """Ensure an object is an array with the specified shape."""
    assert val is not None or default is not None
    if hasattr(val, '__len__') and len(val) == 0:
        val = None
    if isinstance(val, np.ndarray) and val.shape == shape and (val.dtype == dtype):
        return val
    out = np.zeros(shape, dtype=dtype)
    if val is not None and isinstance(val, np.ndarray):
        if val.size == out.size:
            val = val.reshape(out.shape)
    out.flat[:] = val if val is not None else default
    assert out.shape == shape
    return out

def _get_data_bounds(data_bounds, pos=None, length=None):
    """"Prepare data bounds, possibly using min/max of the data."""
    if data_bounds is None or (isinstance(data_bounds, string_types) and data_bounds == 'auto'):
        if pos is not None and len(pos):
            m, M = (pos.min(axis=0), pos.max(axis=0))
            data_bounds = [m[0], m[1], M[0], M[1]]
        else:
            data_bounds = NDC
    data_bounds = np.atleast_2d(data_bounds)
    ind_x = data_bounds[:, 0] == data_bounds[:, 2]
    ind_y = data_bounds[:, 1] == data_bounds[:, 3]
    if np.sum(ind_x):
        data_bounds[ind_x, 0] -= 1
        data_bounds[ind_x, 2] += 1
    if np.sum(ind_y):
        data_bounds[ind_y, 1] -= 1
        data_bounds[ind_y, 3] += 1
    if length is None:
        length = pos.shape[0] if pos is not None else 1
    if data_bounds.shape[0] == 1:
        data_bounds = np.tile(data_bounds, (length, 1))
    assert data_bounds.shape == (length, 4)
    _check_data_bounds(data_bounds)
    return data_bounds

def _random_color(h_range=(0.0, 1.0), s_range=(0.5, 1.0), v_range=(0.5, 1.0)):
    """Generate a random RGB color."""
    h, s, v = (uniform(*h_range), uniform(*s_range), uniform(*v_range))
    r, g, b = hsv_to_rgb(np.array([[[h, s, v]]])).flat
    return (r, g, b)

def _bunchify(b):
    """Ensure all dict elements are Bunch."""
    assert isinstance(b, dict)
    b = Bunch(b)
    for k in b:
        if isinstance(b[k], dict):
            b[k] = Bunch(b[k])
    return b

def _as_list(obj):
    """Ensure an object is a list."""
    if obj is None:
        return None
    elif isinstance(obj, string_types):
        return [obj]
    elif isinstance(obj, tuple):
        return list(obj)
    elif not hasattr(obj, '__len__'):
        return [obj]
    else:
        return obj

def _as_array(arr, dtype=None):
    """Convert an object to a numerical NumPy array.

    Avoid a copy if possible."""
    if arr is None:
        return None
    if isinstance(arr, np.ndarray) and dtype is None:
        return arr
    if isinstance(arr, integer_types + (float,)):
        arr = [arr]
    out = np.asarray(arr)
    if dtype is not None:
        if out.dtype != dtype:
            out = out.astype(dtype)
    if out.dtype not in _ACCEPTED_ARRAY_DTYPES:
        raise ValueError("'arr' seems to have an invalid dtype: {0:s}".format(str(out.dtype)))
    return out

def _glslify(r):
    """Transform a string or a n-tuple to a valid GLSL expression."""
    if isinstance(r, string_types):
        return r
    else:
        assert 2 <= len(r) <= 4
        return 'vec{}({})'.format(len(r), ', '.join(map(str, r)))

def get_plugin(name):
    """Get a plugin class from its name."""
    for plugin in IPluginRegistry.plugins:
        if name in plugin.__name__:
            return plugin
    raise ValueError('The plugin %s cannot be found.' % name)

def _ensure_dir_exists(path):
    """Ensure a directory exists."""
    if not op.exists(path):
        os.makedirs(path)
    assert op.exists(path) and op.isdir(path)

def load_config(path=None):
    """Load a Python or JSON config file."""
    if not path or not op.exists(path):
        return Config()
    path = op.realpath(path)
    dirpath, filename = op.split(path)
    file_ext = op.splitext(path)[1]
    logger.debug('Load config file `%s`.', path)
    if file_ext == '.py':
        config = PyFileConfigLoader(filename, dirpath, log=logger).load_config()
    elif file_ext == '.json':
        config = JSONFileConfigLoader(filename, dirpath, log=logger).load_config()
    return config

def _edges_to_adjacency_list(edges):
    """Convert a list of edges into an adjacency list."""
    adj = {}
    for i, j in edges:
        if i in adj:
            ni = adj[i]
        else:
            ni = adj[i] = set()
        if j in adj:
            nj = adj[j]
        else:
            nj = adj[j] = set()
        ni.add(j)
        nj.add(i)
    return adj

def _probe_positions(probe, group):
    """Return the positions of a probe channel group."""
    positions = probe['channel_groups'][group]['geometry']
    channels = _probe_channels(probe, group)
    return np.array([positions[channel] for channel in channels])

def load_probe(name):
    """Load one of the built-in probes."""
