def stripped_db_url(url):
    """Return a version of the DB url with the password stripped out."""
    parsed = urlparse(url)
    if parsed.password is None:
        return url
    return parsed._replace(netloc='{}:***@{}'.format(parsed.username, parsed.hostname)).geturl()

def is_sf_database(db, model=None):
    """The alias is a Salesforce database."""
    from django.db import connections
    if db is None:
        return getattr(model, '_salesforce_object', False)
    engine = connections[db].settings_dict['ENGINE']
    return engine == 'salesforce.backend' or connections[db].vendor == 'salesforce'

def prep_for_deserialize(model, record, using, init_list=None):
    """Convert a record from SFDC (decoded JSON) to dict(model string, pk, fields)
    If fixes fields of some types. If names of required fields `init_list `are
    specified, then only these fields are processed."""
    attribs = record.pop('attributes')
    mod = model.__module__.split('.')
    if hasattr(model._meta, 'app_label'):
        app_label = getattr(model._meta, 'app_label')
    elif mod[-1] == 'models':
        app_label = mod[-2]
    else:
        raise ImproperlyConfigured("Can't discover the app_label for %s, you must specify it via model meta options.")
    if len(record.keys()) == 1 and model._meta.db_table in record:
        while len(record) == 1:
            record = list(record.values())[0]
            if record is None:
                return None
    fields = prep_for_deserialize_inner(model, record, init_list=init_list)
    if init_list and set(init_list).difference(fields).difference([SF_PK]):
        raise DatabaseError('Not found some expected fields')
    return dict(model='.'.join([app_label, model.__name__]), pk=record.pop('Id'), fields=fields)

def str_dict(some_dict):
    """Convert dict of ascii str/unicode to dict of str, if necessary"""
    return {str(k): str(v) for k, v in some_dict.items()}

def fix_field_params_repr(params):
    """Fixes repr() of "field_params" for Python 2 with future text_type_literals."""
    class ReprUnicode(text_type):
        def __new__(cls, text):
            return text_type.__new__(cls, text)
        def __repr__(self):
            out = repr(text_type(self))
            return out[1:] if out.startswith("u'") or out.startswith('u"') else out
    class ReprChoices(list):
        def __new__(cls, choices):
            return list.__new__(cls, choices)
        def __repr__(self):
            out = []
            for x_0, x_1 in self:
                out.append('(%s, %s)' % (repr(ReprUnicode(x_0) if isinstance(x_0, text_type) else x_0), repr(ReprUnicode(x_1) if isinstance(x_1, text_type) else x_1)))
            return '[%s]' % ', '.join(out)
    if PY3:
        return params
    out = OrderedDict()
    for k, v in params.items():
        if k == 'choices' and v:
            v = ReprChoices(v)
        elif isinstance(v, text_type):
            v = ReprUnicode(v)
        out[k] = v
    return out

def fix_international(text):
    """Fix excaped international characters back to utf-8"""
    class SmartInternational(str):
        def __new__(cls, text):
            return str.__new__(cls, text)
        def endswith(self, string):
            return super(SmartInternational, self).endswith(str(string))
    if PY3:
        return text
    out = []
    last = 0
    for match in re.finditer('(?<=[^\\\\])(?:\\\\x[0-9a-f]{2}|\\\\u[0-9a-f]{4})', text):
        start, end, group = (match.start(), match.end(), match.group())
        out.append(text[last:start])
        c = group.decode('unicode_escape')
        out.append(c if ord(c) > 160 and ord(c) != 173 else group)
        last = end
    out.append(text[last:])
    return SmartInternational(''.join(out).encode('utf-8'))

def relative_path(path):
    """Return the given path relative to this file."""
    return os.path.join(os.path.dirname(__file__), path)

def find_closing_parenthesis(sql, startpos):
    """Find the pair of opening and closing parentheses.

    Starts search at the position startpos.
    Returns tuple of positions (opening, closing) if search succeeds, otherwise None."""
    pattern = re.compile('[()]')
    level = 0
    opening = []
    for match in pattern.finditer(sql, startpos):
        par = match.group()
        if par == '(':
            if level == 0:
                opening = match.start()
            level += 1
        if par == ')':
            assert level > 0, "missing '(' before ')'"
            level -= 1
            if level == 0:
                closing = match.end()
                return (opening, closing)

def simplify_expression(txt):
    """Remove all unecessary whitespace and some very usual space"""
    minimal = re.sub('\\s', ' ', re.sub('\\s(?=\\W)', '', re.sub('(?<=\\W)\\s', '', txt.strip())))
    return re.sub('\\)(?=\\w)', ') ', re.sub('(,|\\b(?:{}))\\('.format('|'.join(RESERVED_WORDS)), '\\1 (', minimal))

def warn_sf(messages, response, verbs=None, klass=SalesforceWarning):
    """Issue a warning SalesforceWarning, with message combined from message and data from SFDC response"""
    warnings.warn(klass(messages, response, verbs), stacklevel=2)

def getaddrinfo_wrapper(host, port, family=socket.AF_INET, socktype=0, proto=0, flags=0):
    """Patched 'getaddrinfo' with default family IPv4 (enabled by settings IPV4_ONLY=True)"""
    return orig_getaddrinfo(host, port, family, socktype, proto, flags)

def quoted_string_literal(txt):
    """SOQL requires single quotes to be escaped.
    http://www.salesforce.com/us/developer/docs/soql_sosl/Content/sforce_api_calls_soql_select_quotedstringescapes.htm"""
    try:
        return "'%s'" % (txt.replace('\\', '\\\\').replace("'", "\\'"),)
    except TypeError:
        raise NotSupportedError('Cannot quote %r objects: %r' % (type(txt), txt))

def arg_to_soql(arg):
    """Perform necessary SOQL quoting on the arg."""
    conversion = sql_conversions.get(type(arg))
    if conversion:
        return conversion(arg)
    for type_ in subclass_conversions:
        if isinstance(arg, type_):
            return sql_conversions[type_](arg)
    return sql_conversions[str](arg)

def arg_to_json(arg):
    """Perform necessary JSON conversion on the arg."""
    conversion = json_conversions.get(type(arg))
    if conversion:
        return conversion(arg)
    for type_ in subclass_conversions:
        if isinstance(arg, type_):
            return json_conversions[type_](arg)
    return json_conversions[str](arg)

def is_readable(fpath):
    """Path references a readable file."""
    return os.path.isfile(fpath) and os.access(fpath, os.R_OK)

def dirname(hdfs_path):
    """Return the directory component of ``hdfs_path``."""
    scheme, netloc, path = parse(hdfs_path)
    return unparse(scheme, netloc, os.path.dirname(path))

def expanduser(path):
    """Replace initial ``~`` or ``~user`` with the user's home directory.

    **NOTE:** if the default file system is HDFS, the ``~user`` form is
    expanded regardless of the user's existence."""
    if hdfs_fs.default_is_local():
        return os.path.expanduser(path)
    m = re.match('^~([^/]*)', path)
    if m is None:
        return path
    user = m.groups()[0] or common.DEFAULT_USER
    return '/user/%s%s' % (user, path[m.end(1):])

def islink(path, user=None):
    """Return :obj:`True` if ``path`` is a symbolic link.

    Currently this function always returns :obj:`False` for non-local paths."""
    host, _, path_ = split(path, user)
    if host:
        return False
    return os.path.islink(path_)

def ismount(path):
    """Return :obj:`True` if ``path`` is a mount point.

    This function always returns :obj:`False` for non-local paths."""
    host, _, path_ = split(path, None)
    if host:
        return False
    return os.path.ismount(path_)

def normpath(path):
    """Normalize ``path``, collapsing redundant separators and up-level refs."""
    scheme, netloc, path_ = parse(path)
    return unparse(scheme, netloc, os.path.normpath(path_))

def realpath(path):
    """Return ``path`` with symlinks resolved.

    Currently this function returns non-local paths unchanged."""
    scheme, netloc, path_ = parse(path)
    if scheme == 'file' or hdfs_fs.default_is_local():
        return unparse(scheme, netloc, os.path.realpath(path_))
    return path

def samefile(path1, path2, user=None):
    """Return :obj:`True` if both path arguments refer to the same path."""
    def tr(p):
        return abspath(normpath(realpath(p)), user=user)
    return tr(path1) == tr(path2)

def access(path, mode, user=None):
    """Perform the equivalent of :func:`os.access` on ``path``."""
    scheme = parse(path)[0]
    if scheme == 'file' or hdfs_fs.default_is_local():
        return os.access(path, mode)
    if user is None:
        user = common.DEFAULT_USER
    st = stat(path)
    if st.st_uid == user:
        mode <<= 6
    else:
        try:
            groups = common.get_groups(user)
        except KeyError:
            groups = []
        if st.st_gid in groups:
            mode <<= 3
    return st.st_mode & mode == mode

def default_is_local(hadoop_conf=None, hadoop_home=None):
    """Is Hadoop configured to use the local file system?

    By default, it is. A DFS must be explicitly configured."""
    params = pydoop.hadoop_params(hadoop_conf, hadoop_home)
    for k in ('fs.defaultFS', 'fs.default.name'):
        if not params.get(k, 'file:').startswith('file:'):
            return False
    return True

def rm_rf(path, dry_run=False):
    """Remove a file or directory tree.

    Won't throw an exception, even if the removal fails."""
    log.info('removing %s' % path)
    if dry_run:
        return
    try:
        if os.path.isdir(path) and (not os.path.islink(path)):
            shutil.rmtree(path)
        else:
            os.remove(path)
    except OSError:
        pass

def get_task_trackers(properties=None, hadoop_conf_dir=None, offline=False):
    """Get the list of task trackers in the Hadoop cluster.

    Each element in the returned list is in the ``(host, port)`` format.
    All arguments are passed to :func:`run_class`.

    If ``offline`` is :obj:`True`, try getting the list of task trackers from
    the ``slaves`` file in Hadoop's configuration directory (no attempt is
    made to contact the Hadoop daemons).  In this case, ports are set to 0."""
    if offline:
        if not hadoop_conf_dir:
            hadoop_conf_dir = pydoop.hadoop_conf()
            slaves = os.path.join(hadoop_conf_dir, 'slaves')
        try:
            with open(slaves) as f:
                task_trackers = [(l.strip(), 0) for l in f]
        except IOError:
            task_trackers = []
    else:
        stdout = run_class('org.apache.hadoop.mapred.JobClient', ['-list-active-trackers'], properties=properties, hadoop_conf_dir=hadoop_conf_dir, keep_streams=True)
        task_trackers = []
        for line in stdout.splitlines():
            if not line:
                continue
            line = line.split(':')
            task_trackers.append((line[0].split('_')[1], int(line[-1])))
    return task_trackers

def get_num_nodes(properties=None, hadoop_conf_dir=None, offline=False):
    """Get the number of task trackers in the Hadoop cluster.

    All arguments are passed to :func:`get_task_trackers`."""
    return len(get_task_trackers(properties, hadoop_conf_dir, offline))

def dfs(args=None, properties=None, hadoop_conf_dir=None):
