def ccor(alt, r, h1, zh):
    """/*        CHEMISTRY/DISSOCIATION CORRECTION FOR MSIS MODELS
     *         ALT - altitude
     *         R - target ratio
     *         H1 - transition scale length
     *         ZH - altitude of 1/2 R
     */
    """
    e = (alt - zh) / h1
    if e > 70.0:
        return 1.0
    elif e < -70.0:
        return exp(r)
    ex = exp(e)
    e = r / (1.0 + ex)
    return exp(e)

def Engauge_2d_parser(lines, flat=False):
    """Not exposed function to read a 2D file generated by engauge-digitizer;
    for curve fitting."""
    z_values = []
    x_lists = []
    y_lists = []
    working_xs = []
    working_ys = []
    new_curve = True
    for line in lines:
        if line.strip() == '':
            new_curve = True
        elif new_curve:
            z = float(line.split(',')[1])
            z_values.append(z)
            if working_xs and working_ys:
                x_lists.append(working_xs)
                y_lists.append(working_ys)
            working_xs = []
            working_ys = []
            new_curve = False
        else:
            x, y = [float(i) for i in line.strip().split(',')]
            working_xs.append(x)
            working_ys.append(y)
    x_lists.append(working_xs)
    y_lists.append(working_ys)
    if flat:
        all_zs = []
        all_xs = []
        all_ys = []
        for z, xs, ys in zip(z_values, x_lists, y_lists):
            for x, y in zip(xs, ys):
                all_zs.append(z)
                all_xs.append(x)
                all_ys.append(y)
        return (all_zs, all_xs, all_ys)
    return (z_values, x_lists, y_lists)

def linspace(start, stop, num=50, endpoint=True, retstep=False, dtype=None):
    """Port of numpy's linspace to pure python. Does not support dtype, and
    returns lists of floats."""
    num = int(num)
    start = start * 1.0
    stop = stop * 1.0
    if num <= 0:
        return []
    if endpoint:
        if num == 1:
            return [start]
        step = (stop - start) / float(num - 1)
        if num == 1:
            step = nan
        y = [start]
        for _ in range(num - 2):
            y.append(y[-1] + step)
        y.append(stop)
    else:
        step = (stop - start) / float(num)
        if num == 1:
            step = nan
        y = [start]
        for _ in range(num - 1):
            y.append(y[-1] + step)
    if retstep:
        return (y, step)
    else:
        return y

def polyder(c, m=1, scl=1, axis=0):
    """not quite a copy of numpy's version because this was faster to implement.
    """
    c = list(c)
    cnt = int(m)
    if cnt == 0:
        return c
    n = len(c)
    if cnt >= n:
        c = c[:1] * 0
    else:
        for i in range(cnt):
            n = n - 1
            c *= scl
            der = [0.0 for _ in range(n)]
            for j in range(n, 0, -1):
                der[j - 1] = j * c[j]
            c = der
    return c

def horner_log(coeffs, log_coeff, x):
    """Technically possible to save one addition of the last term of
    coeffs is removed but benchmarks said nothing was saved"""
    tot = 0.0
    for c in coeffs:
        tot = tot * x + c
    return tot + log_coeff * log(x)

def py_bisect(f, a, b, args=(), xtol=_xtol, rtol=_rtol, maxiter=_iter, ytol=None, full_output=False, disp=True):
    """Port of SciPy's C bisect routine.
    """
    fa = f(a, *args)
    fb = f(b, *args)
    if fa * fb > 0.0:
        raise ValueError('f(a) and f(b) must have different signs')
    elif fa == 0.0:
        return a
    elif fb == 0.0:
        return b
    dm = b - a
    iterations = 0.0
    for i in range(maxiter):
        dm *= 0.5
        xm = a + dm
        fm = f(xm, *args)
        if fm * fa >= 0.0:
            a = xm
        abs_dm = fabs(dm)
        if fm == 0.0:
            return xm
        elif ytol is not None:
            if abs_dm < xtol + rtol * abs_dm and abs(fm) < ytol:
                return xm
        elif abs_dm < xtol + rtol * abs_dm:
            return xm
    raise UnconvergedError('Failed to converge after %d iterations' % maxiter)

def func_args(func):
    """Basic function which returns a tuple of arguments of a function or
    method."""
    try:
        return tuple(inspect.signature(func).parameters)
    except:
        return tuple(inspect.getargspec(func).args)

def isothermal_gas(rho, fd, P1=None, P2=None, L=None, D=None, m=None):
    """>>> isothermal_gas(rho=11.3*u.kg/u.m**3, fd=0.00185*u.dimensionless, P1=1E6*u.Pa, P2=9E5*u.Pa, L=1000*u.m, D=0.5*u.m)
    <Quantity(145.484757264, 'kilogram / second')>"""
    ans = wrapped_isothermal_gas(rho, fd, P1, P2, L, D, m)
    if m is None and None not in [P1, P2, L, D]:
        return ans * u.kg / u.s
    elif L is None and None not in [P1, P2, D, m]:
        return ans * u.m
    elif P1 is None and None not in [L, P2, D, m]:
        return ans * u.Pa
    elif P2 is None and None not in [L, P1, D, m]:
        return ans * u.Pa
    elif D is None and None not in [P2, P1, L, m]:
        return ans * u.m

def cheb_range_simplifier(low, high, text=False):
    """>>> low, high = 0.0023046250851646434, 4.7088985707840125
    >>> cheb_range_simplifier(low, high, text=True)
    'chebval(0.42493574399544564724*(x + -2.3556015979345885647), coeffs)'"""
    constant = 0.5 * (-low - high)
    factor = 2.0 / (high - low)
    if text:
        return 'chebval(%.20g*(x + %.20g), coeffs)' % (factor, constant)
    return (constant, factor)

def cast_scalar(method):
    """Cast scalars to constant interpolating objects"""
    @wraps(method)
    def new_method(self, other):
        if np.isscalar(other):
            other = type(self)([other], self.domain())
        return method(self, other)
    return new_method

def chebfun(f=None, domain=[-1, 1], N=None, chebcoeff=None):
    """Create a Chebyshev polynomial approximation of the function $f$ on the interval :math:`[-1, 1]`.
    :param callable f: Python, Numpy, or Sage function
    :param int N: (default = None)  specify number of interpolating points
    :param np.array chebcoeff: (default = np.array(0)) specify the coefficients"""
    if chebcoeff is not None:
        return Chebfun.from_coeff(chebcoeff, domain)
    if isinstance(f, Polyfun):
        return Chebfun.from_fun(f)
    if hasattr(f, '__call__'):
        return Chebfun.from_function(f, domain, N)
    if np.isscalar(f):
        f = [f]
    try:
        iter(f)
    except TypeError:
        pass
    else:
        return Chebfun(f, domain)
    raise TypeError('Impossible to initialise the object from an object of type {}'.format(type(f)))

def bend_rounded_Ito(Di, angle, Re, rc=None, bend_diameters=None, roughness=0.0):
    """Ito method as shown in Blevins. Curved friction factor as given in
    Blevins, with minor tweaks to be more accurate to the original methods."""
    if not rc:
        if bend_diameters is None:
            bend_diameters = 5.0
        rc = Di * bend_diameters
    radius_ratio = rc / Di
    angle_rad = radians(angle)
    De2 = Re * (Di / rc) ** 2.0
    if rc > 50.0 * Di:
        alpha = 1.0
    else:
        alpha_45 = 1.0 + 5.13 * (Di / rc) ** 1.47
        alpha_90 = 0.95 + 4.42 * (Di / rc) ** 1.96 if rc / Di < 9.85 else 1.0
        alpha_180 = 1.0 + 5.06 * (Di / rc) ** 4.52
        alpha = interp(angle, _Ito_angles, [alpha_45, alpha_90, alpha_180])
    if De2 <= 360.0:
        fc = friction_factor_curved(Re=Re, Di=Di, Dc=2.0 * rc, roughness=roughness, Rec_method='Srinivasan', laminar_method='White', turbulent_method='Srinivasan turbulent')
        K = 0.0175 * alpha * fc * angle * rc / Di
    else:
        K = 0.00431 * alpha * angle * Re ** (-0.17) * (rc / Di) ** 0.84
    return K

def geopy_geolocator():
    """Lazy loader for geocoder from geopy. This currently loads the
    `Nominatim` geocode and returns an instance of it, taking ~2 us."""
