def splitBorder(parts):
    """The order of the elements seems to be of no importance:

    http://www.w3.org/TR/CSS21/box.html#border-shorthand-properties"""
    width = style = color = None
    if len(parts) > 3:
        log.warn('To many elements for border style %r', parts)
    for part in parts:
        if isSize(part):
            width = part
        elif hasattr(part, 'lower') and part.lower() in _borderStyleTable:
            style = part
        else:
            color = part
    return (width, style, color)

def copy_attrs(obj1, obj2, attrs):
    """Allows copy a list of attributes from object2 to object1.
    Useful for copy ccs attributes to fragment"""
    for attr in attrs:
        value = getattr(obj2, attr) if hasattr(obj2, attr) else None
        if value is None and isinstance(obj2, dict) and (attr in obj2):
            value = obj2[attr]
        setattr(obj1, attr, value)

def set_value(obj, attrs, value, _copy=False):
    """Allows set the same value to a list of attributes"""
    for attr in attrs:
        if _copy:
            value = copy(value)
        setattr(obj, attr, value)

def getColor(value, default=None):
    """Convert to color value.
    This returns a Color object instance from a text bit."""
    if isinstance(value, Color):
        return value
    value = str(value).strip().lower()
    if value == 'transparent' or value == 'none':
        return default
    if value in COLOR_BY_NAME:
        return COLOR_BY_NAME[value]
    if value.startswith('#') and len(value) == 4:
        value = '#' + value[1] + value[1] + value[2] + value[2] + value[3] + value[3]
    elif rgb_re.search(value):
        r, g, b = [int(x) for x in rgb_re.search(value).groups()]
        value = '#%02x%02x%02x' % (r, g, b)
    else:
        pass
    return toColor(value, default)

def getCoords(x, y, w, h, pagesize):
    """As a stupid programmer I like to use the upper left
    corner of the document as the 0,0 coords therefore
    we need to do some fancy calculations"""
    ax, ay = pagesize
    if x < 0:
        x = ax + x
    if y < 0:
        y = ay + y
    if w is not None and h is not None:
        if w <= 0:
            w = ax - x + w
        if h <= 0:
            h = ay - y + h
        return (x, ay - y - h, w, h)
    return (x, ay - y)

def getBox(box, pagesize):
    """Parse sizes by corners in the form:
    <X-Left> <Y-Upper> <Width> <Height>
    The last to values with negative values are interpreted as offsets form
    the right and lower border."""
    box = str(box).split()
    if len(box) != 4:
        raise Exception('box not defined right way')
    x, y, w, h = [getSize(pos) for pos in box]
    return getCoords(x, y, w, h, pagesize)

def getPos(position, pagesize):
    """Pair of coordinates"""
    position = str(position).split()
    if len(position) != 2:
        raise Exception('position not defined right way')
    x, y = [getSize(pos) for pos in position]
    return getCoords(x, y, None, None, pagesize)

def cleanBlockQuotedText(text, joiner=b' '):
    """This is an internal utility which takes triple-
    quoted text form within the document and returns
    (hopefully) the paragraph the user intended originally."""
    L = filter(truth, map(_lineClean, split(text, '\n')))
    return joiner.join(L)

def imgVRange(h, va, fontSize):
    """return bottom,top offsets relative to baseline(0)"""
    if va == 'baseline':
        iyo = 0
    elif va in ('text-top', 'top'):
        iyo = fontSize - h
    elif va == 'middle':
        iyo = fontSize - (1.2 * fontSize + h) * 0.5
    elif va in ('text-bottom', 'bottom'):
        iyo = fontSize - 1.2 * fontSize
    elif va == 'super':
        iyo = 0.5 * fontSize
    elif va == 'sub':
        iyo = -0.5 * fontSize
    elif hasattr(va, 'normalizedValue'):
        iyo = va.normalizedValue(fontSize)
    else:
        iyo = va
    return (iyo, iyo + h)

def _sameFrag(f, g):
    """returns 1 if two ParaFrags map out the same"""
    if hasattr(f, 'cbDefn') or hasattr(g, 'cbDefn') or hasattr(f, 'lineBreak') or hasattr(g, 'lineBreak'):
        return 0
    for a in ('fontName', 'fontSize', 'textColor', 'backColor', 'rise', 'underline', 'strike', 'link'):
        if getattr(f, a, None) != getattr(g, a, None):
            return 0
    return 1

def _handleBulletWidth(bulletText, style, maxWidths):
    """work out bullet width and adjust maxWidths[0] if neccessary"""
    if bulletText:
        if isinstance(bulletText, basestring):
            bulletWidth = stringWidth(bulletText, style.bulletFontName, style.bulletFontSize)
        else:
            bulletWidth = 0
            for f in bulletText:
                bulletWidth = bulletWidth + stringWidth(f.text, f.fontName, f.fontSize)
        bulletRight = style.bulletIndent + bulletWidth + 0.6 * style.bulletFontSize
        indent = style.leftIndent + style.firstLineIndent
        if bulletRight > indent:
            maxWidths[0] -= bulletRight - indent

def cjkFragSplit(frags, maxWidths, calcBounds, encoding='utf8'):
    """This attempts to be wordSplit for frags using the dumb algorithm"""
    from reportlab.rl_config import _FUZZ
    U = []
    for f in frags:
        text = f.text
        if not isinstance(text, unicode):
            text = text.decode(encoding)
        if text:
            U.extend([cjkU(t, f, encoding) for t in text])
        else:
            U.append(cjkU(text, f, encoding))
    lines = []
    widthUsed = lineStartPos = 0
    maxWidth = maxWidths[0]
    for i, u in enumerate(U):
        w = u.width
        widthUsed += w
        lineBreak = hasattr(u.frag, 'lineBreak')
        endLine = widthUsed > maxWidth + _FUZZ and widthUsed > 0 or lineBreak
        if endLine:
            if lineBreak:
                continue
            extraSpace = maxWidth - widthUsed + w
            nextChar = U[i]
            if nextChar in ALL_CANNOT_START:
                extraSpace -= w
                i += 1
            lines.append(makeCJKParaLine(U[lineStartPos:i], extraSpace, calcBounds))
            try:
                maxWidth = maxWidths[len(lines)]
            except IndexError:
                maxWidth = maxWidths[-1]
            lineStartPos = i
            widthUsed = w
            i -= 1
    if widthUsed > 0:
        lines.append(makeCJKParaLine(U[lineStartPos:], maxWidth - widthUsed, calcBounds))
    return ParaLines(kind=1, lines=lines)

def link_callback(uri, rel):
    """Convert HTML URIs to absolute system paths so xhtml2pdf can access those
    resources"""
    sUrl = settings.STATIC_URL
    sRoot = settings.STATIC_ROOT
    mUrl = settings.MEDIA_URL
    mRoot = settings.MEDIA_ROOT
    if uri.startswith(mUrl):
        path = os.path.join(mRoot, uri.replace(mUrl, ''))
    elif uri.startswith(sUrl):
        path = os.path.join(sRoot, uri.replace(sUrl, ''))
    else:
        return uri
    if not os.path.isfile(path):
        raise Exception('media URI must start with %s or %s' % (sUrl, mUrl))
    return path

def start():
    """Start the CherryPy application server."""
    setupdir = dirname(dirname(__file__))
    curdir = os.getcwd()
    if len(sys.argv) > 1:
        configfile = sys.argv[1]
    elif exists(join(setupdir, 'setup.py')):
        configfile = join(setupdir, 'dev.cfg')
    elif exists(join(curdir, 'prod.cfg')):
        configfile = join(curdir, 'prod.cfg')
    else:
        try:
            configfile = pkg_resources.resource_filename(pkg_resources.Requirement.parse('tgpisa'), 'config/default.cfg')
        except pkg_resources.DistributionNotFound:
            raise ConfigurationError('Could not find default configuration.')
    turbogears.update_config(configfile=configfile, modulename='tgpisa.config')
    from tgpisa.controllers import Root
    turbogears.start_server(Root())

def parse_shutitfile_args(args_str):
    """Parse shutitfile args (eg in the line 'RUN some args', the passed-in args_str would be 'some args').
    If the string is bounded by square brackets, then it's treated in the form: ['arg1','arg2'], and the returned list looks the same.
    If the string composed entirely of name-value pairs (eg RUN a=b c=d) then it's returned as a dict (eg {'a':'b','c':'d'}).
    If what's passed-in is of the form: "COMMAND ['a=b','c=d']" then a dict is also returned.'
    Also eg: ["asd and space=value","asd 2=asdgasdg"]"""
    ret = []
    if args_str == '':
        return ret
    if args_str[0] == '[' and args_str[-1] == ']':
        ret = eval(args_str)
        assert isinstance(ret, list)
    else:
        ret = args_str.split()
    nv_pairs = True
    for item in ret:
        if item.find('=') < 0:
            nv_pairs = False
    if nv_pairs:
        d = {}
        for item in ret:
            item_nv = item.split('=')
            d.update({item_nv[0]: item_nv[1]})
        ret = d
    return ret

def scan_text(text):
    """Scan text, and replace items that match shutit's pattern format, ie:
    {{ shutit.THING }}"""
    while True:
        match = re.match('(.*){{ shutit.(.*) }}(.*)$', text)
        if match:
            before = match.group(1)
            name = match.group(2)
            after = match.group(3)
            text = before + '\'\'\' + shutit.cfg[self.module_id]["' + name + '"] + \'\'\'' + after
        else:
            break
    return text

def do_finalize():
    """Runs finalize phase; run after all builds are complete and all modules
    have been stopped."""
    def _finalize(shutit):
        shutit.stop_all()
        shutit.log('PHASE: finalizing object ' + str(shutit), level=logging.DEBUG)
        for module_id in shutit.module_ids(rev=True):
            if shutit.is_installed(shutit.shutit_map[module_id]):
                shutit.login(prompt_prefix=module_id, command=shutit_global.shutit_global_object.bash_startup_command, echo=False)
                if not shutit.shutit_map[module_id].finalize(shutit):
                    shutit.fail(module_id + ' failed on finalize', shutit_pexpect_child=shutit.get_shutit_pexpect_session_from_id('target_child').pexpect_child)
                shutit.logout(echo=False)
        for fshutit in shutit_global.shutit_global_object.shutit_objects:
            _finalize(fshutit)

def map_package(shutit_pexpect_session, package, install_type):
    """If package mapping exists, then return it, else return package.
    """
    if package in PACKAGE_MAP.keys():
        for itype in PACKAGE_MAP[package].keys():
            if itype == install_type:
                ret = PACKAGE_MAP[package][install_type]
                if isinstance(ret, str):
                    return ret
                if callable(ret):
                    ret(shutit_pexpect_session)
                    return ''
    return package

def is_file_secure(file_name):
    """Returns false if file is considered insecure, true if secure.
    If file doesn't exist, it's considered secure!"""
    if not os.path.isfile(file_name):
        return True
    file_mode = os.stat(file_name).st_mode
    if file_mode & (stat.S_IRGRP | stat.S_IWGRP | stat.S_IXGRP | stat.S_IROTH | stat.S_IWOTH | stat.S_IXOTH):
        return False
    return True

def random_id(size=8, chars=string.ascii_letters + string.digits):
    """Generates a random string of given size from the given chars.

    @param size:  The size of the random string.
    @param chars: Constituent pool of characters to draw random characters from.
    @type size:   number
    @type chars:  string
    @rtype:       string
    @return:      The string of random characters."""
    return ''.join((random.choice(chars) for _ in range(size)))

def random_word(size=6):
    """Returns a random word in lower case.
    """
    words = shutit_assets.get_words().splitlines()
    word = ''
    while len(word) != size or "'" in word:
        word = words[int(random.random() * (len(words) - 1))]
    return word.lower()

def util_raw_input(prompt='', default=None, ispass=False, use_readline=True):
    """Handles raw_input calls, and switches off interactivity if there is apparently
    no controlling terminal (or there are any other problems)"""
    if use_readline:
        try:
            readline.read_init_file('/etc/inputrc')
        except IOError:
            pass
        readline.parse_and_bind('tab: complete')
    prompt = '\r\n' + prompt
    if ispass:
        prompt += '\r\nInput Secret: '
    sanitize_terminal()
    if shutit_global.shutit_global_object.interactive == 0:
        return default
    if not shutit_global.shutit_global_object.determine_interactive():
        return default
    while True:
        try:
            if ispass:
                return getpass.getpass(prompt=prompt)
            else:
                return input(prompt).strip() or default
        except KeyboardInterrupt:
            continue
        except IOError:
            msg = 'Problems getting raw input, assuming no controlling terminal.'
    if ispass:
        return getpass.getpass(prompt=prompt)
    else:
        return input(prompt).strip() or default
    shutit_global.shutit_global_object.set_noninteractive(msg=msg)
    return default

def get_shutit_pexpect_sessions():
    """Returns all the shutit_pexpect sessions in existence.
    """
    sessions = []
    for shutit_object in shutit_global_object.shutit_objects:
        for key in shutit_object.shutit_pexpect_sessions:
            sessions.append(shutit_object.shutit_pexpect_sessions[key])
    return sessions

def main():
    """Main ShutIt function.

    Handles the configured actions:

            - skeleton     - create skeleton module
            - list_configs - output computed configuration
            - depgraph     - output digraph of module dependencies"""
    shutit = shutit_global.shutit_global_object.shutit_objects[0]
    if sys.version_info[0] == 2:
        if sys.version_info[1] < 7:
            shutit.fail('Python version must be 2.7+')
    try:
        shutit.setup_shutit_obj()
    except KeyboardInterrupt:
        shutit_util.print_debug(sys.exc_info())
        shutit_global.shutit_global_object.shutit_print('Keyboard interrupt caught, exiting with status 1')
        sys.exit(1)

def decode_aes256_plain_auto(data, encryption_key):
    """Guesses AES cipher (EBC or CBD) from the length of the plain data."""
    assert isinstance(data, bytes)
    length = len(data)
    if length == 0:
        return b''
    elif data[0] == b'!'[0] and length % 16 == 1 and (length > 32):
        return decode_aes256_cbc_plain(data, encryption_key)
    else:
        return decode_aes256_ecb_plain(data, encryption_key)

def decode_aes256_base64_auto(data, encryption_key):
    """Guesses AES cipher (EBC or CBD) from the length of the base64 encoded data."""
    assert isinstance(data, bytes)
    length = len(data)
    if length == 0:
        return b''
    elif data[0] == b'!'[0]:
        return decode_aes256_cbc_base64(data, encryption_key)
    else:
        return decode_aes256_ecb_base64(data, encryption_key)

def decode_aes256_cbc_base64(data, encryption_key):
    """Decrypts base64 encoded AES-256 CBC bytes."""
    if not data:
        return b''
    else:
        return decode_aes256('cbc', decode_base64(data[1:25]), decode_base64(data[26:]), encryption_key)

def decode_aes256(cipher, iv, data, encryption_key):
    """Decrypt AES-256 bytes.
    Allowed ciphers are: :ecb, :cbc.
    If for :ecb iv is not used and should be set to ""."""
    if cipher == 'cbc':
        aes = AES.new(encryption_key, AES.MODE_CBC, iv)
    elif cipher == 'ecb':
        aes = AES.new(encryption_key, AES.MODE_ECB)
    else:
        raise ValueError('Unknown AES mode')
    d = aes.decrypt(data)
    unpad = lambda s: s[0:-ord(d[-1:])]
    return unpad(d)

def get_args(cls, dist, header=None):
    """Overrides easy_install.ScriptWriter.get_args

    This method avoids using pkg_resources to map a named entry_point
    to a callable at invocation time."""
    if header is None:
        header = cls.get_header()
    spec = str(dist.as_requirement())
    for type_ in ('console', 'gui'):
        group = type_ + '_scripts'
        for name, ep in dist.get_entry_map(group).items():
            if re.search('[\\\\/]', name):
                raise ValueError('Path separators not allowed in script names')
            script_text = TEMPLATE.format(ep.module_name, ep.attrs[0], '.'.join(ep.attrs), spec, group, name)
            args = cls._get_script_args(type_, name, header, script_text)
            for res in args:
                yield res

def clean_pip_env() -> Generator[None, None, None]:
    """A context manager for temporarily removing 'PIP_REQUIRE_VIRTUALENV' from the environment.

    Since shiv installs via `--target`, we need to ignore venv requirements if they exist."""
    require_venv = os.environ.pop(PIP_REQUIRE_VIRTUALENV, None)
    try:
        yield
    finally:
        if require_venv is not None:
            os.environ[PIP_REQUIRE_VIRTUALENV] = require_venv

def current_zipfile():
    """A function to vend the current zipfile, if any"""
    if zipfile.is_zipfile(sys.argv[0]):
        fd = open(sys.argv[0], 'rb')
        return zipfile.ZipFile(fd)

def extract_site_packages(archive, target_path, compile_pyc, compile_workers=0, force=False):
    """Extract everything in site-packages to a specified path.

    :param ZipFile archive: The zipfile object we are bootstrapping from.
    :param Path target_path: The path to extract our zip to."""
    parent = target_path.parent
    target_path_tmp = Path(parent, target_path.stem + '.tmp')
    lock = Path(parent, target_path.stem + '.lock')
    if not parent.exists():
        parent.mkdir(parents=True, exist_ok=True)
    with FileLock(lock):
        if not target_path.exists() or force:
            for filename in archive.namelist():
                if filename.startswith('site-packages'):
                    archive.extract(filename, target_path_tmp)
            if compile_pyc:
                compileall.compile_dir(target_path_tmp, quiet=2, workers=compile_workers)
            if target_path.exists():
                shutil.rmtree(str(target_path))
            shutil.move(str(target_path_tmp), str(target_path))

def bootstrap():
    """Actually bootstrap our shiv environment."""
    archive = current_zipfile()
    env = Environment.from_json(archive.read('environment.json').decode())
    site_packages = cache_path(archive, env.root, env.build_id) / 'site-packages'
    if not site_packages.exists() or env.force_extract:
        extract_site_packages(archive, site_packages.parent, env.compile_pyc, env.compile_workers, env.force_extract)
    length = len(sys.path)
    index = _first_sitedir_index() or length
    site.addsitedir(site_packages)
    if env.extend_pythonpath:
        _extend_python_path(os.environ, sys.path[index:])
    sys.path = sys.path[:index] + sys.path[length:] + sys.path[index:length]
    if not env.interpreter:
        if env.entry_point is not None:
            mod = import_string(env.entry_point)
            try:
                sys.exit(mod())
            except TypeError:
                sys.exit(getattr(mod, env.entry_point.replace(':', '.').split('.')[1])())
        elif env.script is not None:
            sys.exit(runpy.run_path(site_packages / 'bin' / env.script, run_name='__main__'))
    execute_interpreter()

def acquire_win(lock_file):
    """Acquire a lock file on windows."""
    try:
        fd = os.open(lock_file, OPEN_MODE)
    except OSError:
        pass
    else:
        try:
            msvcrt.locking(fd, msvcrt.LK_NBLCK, 1)
        except (IOError, OSError):
            os.close(fd)
        else:
            return fd

def acquire_nix(lock_file):
    """Acquire a lock file on linux or osx."""
    fd = os.open(lock_file, OPEN_MODE)
    try:
        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except (IOError, OSError):
        os.close(fd)
    else:
        return fd

def copy_bootstrap(bootstrap_target: Path) -> None:
    """Copy bootstrap code from shiv into the pyz.

    This function is excluded from type checking due to the conditional import.

    :param bootstrap_target: The temporary directory where we are staging pyz contents."""
    for bootstrap_file in importlib_resources.contents(bootstrap):
        if importlib_resources.is_resource(bootstrap, bootstrap_file):
            with importlib_resources.path(bootstrap, bootstrap_file) as f:
                shutil.copyfile(f.absolute(), bootstrap_target / f.name)

def _interpreter_path(append_version: bool=False) -> str:
    """A function to return the path to the current Python interpreter.

    Even when inside a venv, this will return the interpreter the venv was created with."""
    base_dir = Path(getattr(sys, 'real_prefix', sys.base_prefix)).resolve()
    sys_exec = Path(sys.executable)
    name = sys_exec.stem
    suffix = sys_exec.suffix
    if append_version:
        name += str(sys.version_info.major)
    name += suffix
    try:
        return str(next(iter(base_dir.rglob(name))))
    except StopIteration:
        if not append_version:
            return _interpreter_path(append_version=True)
        return sys.executable

def get_session(*, env_vars=None, loop=None):
