def find_lexer_class_for_filename(_fn, code=None):
    """Get a lexer for a filename.

    If multiple lexers match the filename pattern, use ``analyse_text()`` to
    figure out which one is more appropriate.

    Returns None if not found."""
    matches = []
    fn = basename(_fn)
    for modname, name, _, filenames, _ in itervalues(LEXERS):
        for filename in filenames:
            if _fn_matches(fn, filename):
                if name not in _lexer_cache:
                    _load_lexers(modname)
                matches.append((_lexer_cache[name], filename))
    for cls in find_plugin_lexers():
        for filename in cls.filenames:
            if _fn_matches(fn, filename):
                matches.append((cls, filename))
    if sys.version_info > (3,) and isinstance(code, bytes):
        code = guess_decode(code)
    def get_rating(info):
        cls, filename = info
        bonus = '*' not in filename and 0.5 or 0
        if code:
            return (cls.analyse_text(code) + bonus, cls.__name__)
        return (cls.priority + bonus, cls.__name__)
    if matches:
        matches.sort(key=get_rating)
        return matches[-1][0]

def get_lexer_for_filename(_fn, code=None, **options):
    """Get a lexer for a filename.

    If multiple lexers match the filename pattern, use ``analyse_text()`` to
    figure out which one is more appropriate.

    Raises ClassNotFound if not found."""
    res = find_lexer_class_for_filename(_fn, code)
    if not res:
        raise ClassNotFound('no lexer for filename %r found' % _fn)
    return res(**options)

def get_lexer_for_mimetype(_mime, **options):
    """Get a lexer for a mimetype.

    Raises ClassNotFound if not found."""
    for modname, name, _, _, mimetypes in itervalues(LEXERS):
        if _mime in mimetypes:
            if name not in _lexer_cache:
                _load_lexers(modname)
            return _lexer_cache[name](**options)
    for cls in find_plugin_lexers():
        if _mime in cls.mimetypes:
            return cls(**options)
    raise ClassNotFound('no lexer for mimetype %r found' % _mime)

def _iter_lexerclasses(plugins=True):
    """Return an iterator over all lexer classes."""
    for key in sorted(LEXERS):
        module_name, name = LEXERS[key][:2]
        if name not in _lexer_cache:
            _load_lexers(module_name)
        yield _lexer_cache[name]
    if plugins:
        for lexer in find_plugin_lexers():
            yield lexer

def guess_lexer(_text, **options):
    """Guess a lexer by strong distinctions in the text (eg, shebang)."""
    ft = get_filetype_from_buffer(_text)
    if ft is not None:
        try:
            return get_lexer_by_name(ft, **options)
        except ClassNotFound:
            pass
    best_lexer = [0.0, None]
    for lexer in _iter_lexerclasses():
        rv = lexer.analyse_text(_text)
        if rv == 1.0:
            return lexer(**options)
        if rv > best_lexer[0]:
            best_lexer[:] = (rv, lexer)
    if not best_lexer[0] or best_lexer[1] is None:
        raise ClassNotFound('no lexer matching the text found')
    return best_lexer[1](**options)

def get_file_stats(file_name, entity_type='file', lineno=None, cursorpos=None, plugin=None, language=None, local_file=None):
    """Returns a hash of information about the entity."""
    language = standardize_language(language, plugin)
    stats = {'language': language, 'dependencies': [], 'lines': None, 'lineno': lineno, 'cursorpos': cursorpos}
    if entity_type == 'file':
        lexer = get_lexer(language)
        if not language:
            language, lexer = guess_language(file_name, local_file)
        parser = DependencyParser(local_file or file_name, lexer)
        stats.update({'language': use_root_language(language, lexer), 'dependencies': parser.parse(), 'lines': number_lines_in_file(local_file or file_name)})
    return stats

def guess_language(file_name, local_file):
    """Guess lexer and language for a file.

    Returns a tuple of (language_str, lexer_obj)."""
    lexer = None
    language = get_language_from_extension(file_name)
    if language:
        lexer = get_lexer(language)
    else:
        lexer = smart_guess_lexer(file_name, local_file)
        if lexer:
            language = u(lexer.name)
    return (language, lexer)

def guess_lexer_using_filename(file_name, text):
    """Guess lexer for given text, limited to lexers for this file's extension.

    Returns a tuple of (lexer, accuracy)."""
    lexer, accuracy = (None, None)
    try:
        lexer = custom_pygments_guess_lexer_for_filename(file_name, text)
    except SkipHeartbeat as ex:
        raise SkipHeartbeat(u(ex))
    except:
        log.traceback(logging.DEBUG)
    if lexer is not None:
        try:
            accuracy = lexer.analyse_text(text)
        except:
            log.traceback(logging.DEBUG)
    return (lexer, accuracy)

def guess_lexer_using_modeline(text):
    """Guess lexer for given text using Vim modeline.

    Returns a tuple of (lexer, accuracy)."""
    lexer, accuracy = (None, None)
    file_type = None
    try:
        file_type = get_filetype_from_buffer(text)
    except:
        log.traceback(logging.DEBUG)
    if file_type is not None:
        try:
            lexer = get_lexer_by_name(file_type)
        except ClassNotFound:
            log.traceback(logging.DEBUG)
    if lexer is not None:
        try:
            accuracy = lexer.analyse_text(text)
        except:
            log.traceback(logging.DEBUG)
    return (lexer, accuracy)

def standardize_language(language, plugin):
    """Maps a string to the equivalent Pygments language.

    Returns the standardized language string."""
    if not language:
        return None
    if plugin:
        plugin = plugin.split(' ')[-1].split('/')[0].split('-')[0]
        standardized = get_language_from_json(language, plugin)
        if standardized is not None:
            return standardized
    return get_language_from_json(language, 'default')

def get_language_from_json(language, key):
    """Finds the given language in a json file."""
    file_name = os.path.join(os.path.dirname(__file__), 'languages', '{0}.json').format(key.lower())
    if os.path.exists(file_name):
        try:
            with open(file_name, 'r', encoding='utf-8') as fh:
                languages = json.loads(fh.read())
                if languages.get(language.lower()):
                    return languages[language.lower()]
        except:
            log.traceback(logging.DEBUG)
    return None

def get_file_head(file_name):
    """Returns the first 512000 bytes of the file's contents."""
    text = None
    try:
        with open(file_name, 'r', encoding='utf-8') as fh:
            text = fh.read(512000)
    except:
        try:
            with open(file_name, 'r', encoding=sys.getfilesystemencoding()) as fh:
                text = fh.read(512000)
        except:
            log.traceback(logging.DEBUG)
    return text

def customize_lexer_priority(file_name, accuracy, lexer):
    """Customize lexer priority"""
    priority = lexer.priority
    lexer_name = lexer.name.lower().replace('sharp', '#')
    if lexer_name in LANGUAGES:
        priority = LANGUAGES[lexer_name]
    elif lexer_name == 'matlab':
        available_extensions = extensions_in_same_folder(file_name)
        if '.mat' in available_extensions:
            accuracy += 0.01
        if '.h' not in available_extensions:
            accuracy += 0.01
    elif lexer_name == 'objective-c':
        available_extensions = extensions_in_same_folder(file_name)
        if '.mat' in available_extensions:
            accuracy -= 0.01
        else:
            accuracy += 0.01
        if '.h' in available_extensions:
            accuracy += 0.01
    return (accuracy, priority, lexer)

def _get_server_cert(response):
    """Get the certificate at the request_url and return it as a SHA256 hash. Will get the raw socket from the
    original response from the server. This socket is then checked if it is an SSL socket and then used to
    get the hash of the certificate. The certificate hash is then used with NTLMv2 authentication for
    Channel Binding Tokens support. If the raw object is not a urllib3 HTTPReponse (default with requests)
    then no certificate will be returned.

    :param response: The original 401 response from the server
    :return: SHA256 hash of the DER encoded certificate at the request_url or None if not a HTTPS endpoint"""
    certificate_hash = None
    raw_response = response.raw
    if isinstance(raw_response, HTTPResponse):
        if sys.version_info > (3, 0):
            socket = raw_response._fp.fp.raw._sock
        else:
            socket = raw_response._fp.fp._sock
        try:
            server_certificate = socket.getpeercert(True)
        except AttributeError:
            pass
        else:
            hash_object = hashlib.sha256(server_certificate)
            certificate_hash = hash_object.hexdigest().upper()
    else:
        warnings.warn('Requests is running with a non urllib3 backend, cannot retrieve server certificate for CBT', NoCertificateRetrievedWarning)
    return certificate_hash

def _dnsname_to_stdlib(name):
    """Converts a dNSName SubjectAlternativeName field to the form used by the
    standard library on the given Python version.

    Cryptography produces a dNSName as a unicode string that was idna-decoded
    from ASCII bytes. We need to idna-encode that string to get it back, and
    then on Python 3 we also need to convert to unicode via UTF-8 (the stdlib
    uses PyUnicode_FromStringAndSize on it, which decodes via UTF-8)."""
    def idna_encode(name):
        """Borrowed wholesale from the Python Cryptography Project. It turns out
        that we can't just safely call `idna.encode`: it can explode for
        wildcard names. This avoids that problem."""
        import idna
        for prefix in [u'*.', u'.']:
            if name.startswith(prefix):
                name = name[len(prefix):]
                return prefix.encode('ascii') + idna.encode(name)
        return idna.encode(name)
    name = idna_encode(name)
    if sys.version_info >= (3, 0):
        name = name.decode('utf-8')
    return name

def _objdump_lexer_tokens(asm_lexer):
    """Common objdump lexer tokens to wrap an ASM lexer."""
    hex_re = '[0-9A-Za-z]'
    return {'root': [('(.*?)(:)( +file format )(.*?)$', bygroups(Name.Label, Punctuation, Text, String)), ('(Disassembly of section )(.*?)(:)$', bygroups(Text, Name.Label, Punctuation)), ('(' + hex_re + '+)( )(<)(.*?)([-+])(0[xX][A-Za-z0-9]+)(>:)$', bygroups(Number.Hex, Text, Punctuation, Name.Function, Punctuation, Number.Hex, Punctuation)), ('(' + hex_re + '+)( )(<)(.*?)(>:)$', bygroups(Number.Hex, Text, Punctuation, Name.Function, Punctuation)), ('( *)(' + hex_re + '+:)(\\t)((?:' + hex_re + hex_re + ' )+)( *\t)([a-zA-Z].*?)$', bygroups(Text, Name.Label, Text, Number.Hex, Text, using(asm_lexer))), ('( *)(' + hex_re + '+:)(\\t)((?:' + hex_re + hex_re + ' )+)( *)(.*?)$', bygroups(Text, Name.Label, Text, Number.Hex, Text, String)), ('( *)(' + hex_re + '+:)(\\t)((?:' + hex_re + hex_re + ' )+)$', bygroups(Text, Name.Label, Text, Number.Hex)), ('\\t\\.\\.\\.$', Text), ('(\\t\\t\\t)(' + hex_re + '+:)( )([^\\t]+)(\\t)(.*?)([-+])(0x' + hex_re + '+)$', bygroups(Text, Name.Label, Text, Name.Property, Text, Name.Constant, Punctuation, Number.Hex)), ('(\\t\\t\\t)(' + hex_re + '+:)( )([^\\t]+)(\\t)(.*?)$', bygroups(Text, Name.Label, Text, Name.Property, Text, Name.Constant)), ('[^\\n]+\\n', Other)]}

def _fileobj_to_fd(fileobj):
    """Return a file descriptor from a file object. If
    given an integer will simply return that integer back."""
    if isinstance(fileobj, int):
        fd = fileobj
    else:
        try:
            fd = int(fileobj.fileno())
        except (AttributeError, TypeError, ValueError):
            raise ValueError('Invalid file object: {0!r}'.format(fileobj))
    if fd < 0:
        raise ValueError('Invalid file descriptor: {0}'.format(fd))
    return fd

def _can_allocate(struct):
    """Checks that select structs can be allocated by the underlying
    operating system, not just advertised by the select module. We don't
    check select() because we'll be hopeful that most platforms that
    don't have it available will not advertise it. (ie: GAE)"""
    try:
        if struct == 'poll':
            p = select.poll()
            p.poll(0)
        else:
            getattr(select, struct)().close()
        return True
    except (OSError, AttributeError) as e:
        return False

def DefaultSelector():
    """This function serves as a first call for DefaultSelector to
    detect if the select module is being monkey-patched incorrectly
    by eventlet, greenlet, and preserve proper behavior."""
    global _DEFAULT_SELECTOR
    if _DEFAULT_SELECTOR is None:
        if _can_allocate('kqueue'):
            _DEFAULT_SELECTOR = KqueueSelector
        elif _can_allocate('epoll'):
            _DEFAULT_SELECTOR = EpollSelector
        elif _can_allocate('poll'):
            _DEFAULT_SELECTOR = PollSelector
        elif hasattr(select, 'select'):
            _DEFAULT_SELECTOR = SelectSelector
        else:
            raise ValueError('Platform does not have a selector')
    return _DEFAULT_SELECTOR()

def get_filetype_from_buffer(buf, max_lines=5):
    """Scan the buffer for modelines and return filetype if one is found."""
    lines = buf.splitlines()
    for l in lines[-1:-max_lines - 1:-1]:
        ret = get_filetype_from_line(l)
        if ret:
            return ret
    for i in range(max_lines, -1, -1):
        if i < len(lines):
            ret = get_filetype_from_line(lines[i])
            if ret:
                return ret
    return None

def lex(code, lexer):
    """Lex ``code`` with ``lexer`` and return an iterable of tokens."""
    try:
        return lexer.get_tokens(code)
    except TypeError as err:
        if isinstance(err.args[0], str) and ('unbound method get_tokens' in err.args[0] or 'missing 1 required positional argument' in err.args[0]):
            raise TypeError('lex() argument must be a lexer instance, not a class')
        raise

def highlight(code, lexer, formatter, outfile=None):
    """Lex ``code`` with ``lexer`` and format it with the formatter ``formatter``.

    If ``outfile`` is given and a valid file object (an object
    with a ``write`` method), the result will be written to it, otherwise
    it is returned as a string."""
    return format(lex(code, lexer), formatter, outfile)

def getConfigFile():
    """Returns the config file location.

    If $WAKATIME_HOME env varialbe is defined, returns
    $WAKATIME_HOME/.wakatime.cfg, otherwise ~/.wakatime.cfg."""
    fileName = '.wakatime.cfg'
    home = os.environ.get('WAKATIME_HOME')
    if home:
        return os.path.join(os.path.expanduser(home), fileName)
    return os.path.join(os.path.expanduser('~'), fileName)

def parseConfigFile(configFile=None):
    """Returns a configparser.SafeConfigParser instance with configs
    read from the config file. Default location of the config file is
    at ~/.wakatime.cfg."""
    if not configFile:
        configFile = getConfigFile()
    configs = configparser.ConfigParser(delimiters='=', strict=False)
    try:
        with open(configFile, 'r', encoding='utf-8') as fh:
            try:
                configs.read_file(fh)
            except configparser.Error:
                print(traceback.format_exc())
                raise SystemExit(CONFIG_FILE_PARSE_ERROR)
    except IOError:
        pass
    return configs

def get_filter_by_name(filtername, **options):
    """Return an instantiated filter.

    Options are passed to the filter initializer if wanted.
    Raise a ClassNotFound if not found."""
    cls = find_filter_class(filtername)
    if cls:
        return cls(**options)
    else:
        raise ClassNotFound('filter %r not found' % filtername)

def format_file_path(filepath):
    """Formats a path as absolute and with the correct platform separator."""
    try:
        is_windows_network_mount = WINDOWS_NETWORK_MOUNT_PATTERN.match(filepath)
        filepath = os.path.realpath(os.path.abspath(filepath))
        filepath = re.sub(BACKSLASH_REPLACE_PATTERN, '/', filepath)
        is_windows_drive = WINDOWS_DRIVE_PATTERN.match(filepath)
        if is_windows_drive:
            filepath = filepath.capitalize()
        if is_windows_network_mount:
            filepath = '/' + filepath
    except:
        pass
    return filepath

def _ipv6_host(host):
    """Process IPv6 address literals"""
    if host.startswith('[') and host.endswith(']'):
        host = host.replace('%25', '%').strip('[]')
    return host

def get_sign_key(exported_session_key, magic_constant):
    """3.4.5.2 SIGNKEY

    @param exported_session_key: A 128-bit session key used to derive signing and sealing keys
    @param magic_constant: A constant value set in the MS-NLMP documentation (constants.SignSealConstants)
    @return sign_key: Key used to sign messages"""
    sign_key = hashlib.md5(exported_session_key + magic_constant).digest()
    return sign_key

def get_seal_key(negotiate_flags, exported_session_key, magic_constant):
    """3.4.5.3. SEALKEY
    Main method to use to calculate the seal_key used to seal (encrypt) messages. This will determine
    the correct method below to use based on the compatibility flags set and should be called instead
    of the others

    @param exported_session_key: A 128-bit session key used to derive signing and sealing keys
    @param negotiate_flags: The negotiate_flags structure sent by the server
    @param magic_constant: A constant value set in the MS-NLMP documentation (constants.SignSealConstants)
    @return seal_key: Key used to seal messages"""
    if negotiate_flags & NegotiateFlags.NTLMSSP_NEGOTIATE_EXTENDED_SESSIONSECURITY:
        seal_key = _get_seal_key_ntlm2(negotiate_flags, exported_session_key, magic_constant)
    elif negotiate_flags & NegotiateFlags.NTLMSSP_NEGOTIATE_LM_KEY:
        seal_key = _get_seal_key_ntlm1(negotiate_flags, exported_session_key)
    else:
        seal_key = exported_session_key
    return seal_key

def _get_seal_key_ntlm1(negotiate_flags, exported_session_key):
    """3.4.5.3 SEALKEY
    Calculates the seal_key used to seal (encrypt) messages. This for authentication where
    NTLMSSP_NEGOTIATE_EXTENDED_SESSIONSECURITY has not been negotiated. Will weaken the keys
    if NTLMSSP_NEGOTIATE_56 is not negotiated it will default to the 40-bit key

    @param negotiate_flags: The negotiate_flags structure sent by the server
    @param exported_session_key: A 128-bit session key used to derive signing and sealing keys
    @return seal_key: Key used to seal messages"""
    if negotiate_flags & NegotiateFlags.NTLMSSP_NEGOTIATE_56:
        seal_key = exported_session_key[:7] + binascii.unhexlify('a0')
    else:
        seal_key = exported_session_key[:5] + binascii.unhexlify('e538b0')
    return seal_key

def _get_seal_key_ntlm2(negotiate_flags, exported_session_key, magic_constant):
    """3.4.5.3 SEALKEY
    Calculates the seal_key used to seal (encrypt) messages. This for authentication where
    NTLMSSP_NEGOTIATE_EXTENDED_SESSIONSECURITY has been negotiated. Will weaken the keys
    if NTLMSSP_NEGOTIATE_128 is not negotiated, will try NEGOTIATE_56 and then will default
    to the 40-bit key

    @param negotiate_flags: The negotiate_flags structure sent by the server
    @param exported_session_key: A 128-bit session key used to derive signing and sealing keys
    @param magic_constant: A constant value set in the MS-NLMP documentation (constants.SignSealConstants)
    @return seal_key: Key used to seal messages"""
    if negotiate_flags & NegotiateFlags.NTLMSSP_NEGOTIATE_128:
        seal_key = exported_session_key
    elif negotiate_flags & NegotiateFlags.NTLMSSP_NEGOTIATE_56:
        seal_key = exported_session_key[:7]
    else:
        seal_key = exported_session_key[:5]
    seal_key = hashlib.md5(seal_key + magic_constant).digest()
    return seal_key

def _wait_for_io_events(socks, events, timeout=None):
    """Waits for IO events to be available from a list of sockets
    or optionally a single socket if passed in. Returns a list of
    sockets that can be interacted with immediately."""
    if not HAS_SELECT:
        raise ValueError('Platform does not have a selector')
    if not isinstance(socks, list):
        if hasattr(socks, 'fileno'):
            socks = [socks]
        else:
            socks = list(socks)
    with DefaultSelector() as selector:
        for sock in socks:
            selector.register(sock, events)
        return [key[0].fileobj for key in selector.select(timeout) if key[1] & events]

def looks_like_xml(text):
    """Check if a doctype exists or if we have some tags."""
    if xml_decl_re.match(text):
        return True
    key = hash(text)
    try:
        return _looks_like_xml_cache[key]
    except KeyError:
        m = doctype_lookup_re.match(text)
        if m is not None:
            return True
        rv = tag_re.search(text[:1000]) is not None
        _looks_like_xml_cache[key] = rv
        return rv

def unirange(a, b):
    """Returns a regular expression string to match the given non-BMP range."""
    if b < a:
        raise ValueError('Bad character range')
    if a < 65536 or b < 65536:
        raise ValueError('unirange is only defined for non-BMP ranges')
    if sys.maxunicode > 65535:
        return u'[%s-%s]' % (unichr(a), unichr(b))
    else:
        ah, al = _surrogatepair(a)
        bh, bl = _surrogatepair(b)
        if ah == bh:
            return u'(?:%s[%s-%s])' % (unichr(ah), unichr(al), unichr(bl))
        else:
            buf = []
            buf.append(u'%s[%s-%s]' % (unichr(ah), unichr(al), ah == bh and unichr(bl) or unichr(57343)))
            if ah - bh > 1:
                buf.append(u'[%s-%s][%s-%s]' % unichr(ah + 1), unichr(bh - 1), unichr(56320), unichr(57343))
            if ah != bh:
                buf.append(u'%s[%s-%s]' % (unichr(bh), unichr(56320), unichr(bl)))
            return u'(?:' + u'|'.join(buf) + u')'

def guess_decode(text):
    """Decode *text* with guessed encoding.

    First try UTF-8; this should fail for non-UTF-8 encodings.
    Then try the preferred locale encoding.
    Fall back to latin-1, which always works."""
    try:
        text = text.decode('utf-8')
        return (text, 'utf-8')
    except UnicodeDecodeError:
        try:
            import locale
            prefencoding = locale.getpreferredencoding()
            text = text.decode()
            return (text, prefencoding)
        except (UnicodeDecodeError, LookupError):
            text = text.decode('latin1')
            return (text, 'latin1')

def apply_filters(stream, filters, lexer=None):
    """Use this method to apply an iterable of filters to
    a stream. If lexer is given it's forwarded to the
    filter, otherwise the filter receives `None`."""
    def _apply(filter_, stream):
        for token in filter_.filter(lexer, stream):
            yield token
    for filter_ in filters:
        stream = _apply(filter_, stream)
    return stream

def simplefilter(f):
    """Decorator that converts a function into a filter::

        @simplefilter
        def lowercase(self, lexer, stream, options):
            for ttype, value in stream:
                yield ttype, value.lower()"""
    return type(f.__name__, (FunctionFilter,), {'__module__': getattr(f, '__module__'), '__doc__': f.__doc__, 'function': f})

def is_connection_dropped(conn):
    """Returns True if the connection is dropped and should be closed.

    :param conn:
        :class:`httplib.HTTPConnection` object.

    Note: For platforms like AppEngine, this will always return ``False`` to
    let the platform handle connection recycling transparently for us."""
    sock = getattr(conn, 'sock', False)
    if sock is False:
        return False
    if sock is None:
        return True
    if not HAS_SELECT:
        return False
    try:
        return bool(wait_for_read(sock, timeout=0.0))
    except SelectorError:
        return True

def using(_other, **kwargs):
    """Callback that processes the match with a different lexer.

    The keyword arguments are forwarded to the lexer, except `state` which
    is handled separately.

    `state` specifies the state that the new lexer will start in, and can
    be an enumerable such as ('root', 'inline', 'string') or a simple
    string which is assumed to be on top of the root state.

    Note: For that to work, `_other` must not be an `ExtendedRegexLexer`."""
    gt_kwargs = {}
    if 'state' in kwargs:
        s = kwargs.pop('state')
        if isinstance(s, (list, tuple)):
            gt_kwargs['stack'] = s
        else:
            gt_kwargs['stack'] = ('root', s)
    if _other is this:
        def callback(lexer, match, ctx=None):
            if kwargs:
                kwargs.update(lexer.options)
                lx = lexer.__class__(**kwargs)
            else:
                lx = lexer
            s = match.start()
            for i, t, v in lx.get_tokens_unprocessed(match.group(), **gt_kwargs):
                yield (i + s, t, v)
            if ctx:
                ctx.pos = match.end()
    else:
        def callback(lexer, match, ctx=None):
            kwargs.update(lexer.options)
            lx = _other(**kwargs)
            s = match.start()
            for i, t, v in lx.get_tokens_unprocessed(match.group(), **gt_kwargs):
                yield (i + s, t, v)
            if ctx:
                ctx.pos = match.end()
    return callback

def memorized_timedelta(seconds):
    """Create only one instance of each distinct timedelta"""
    try:
        return _timedelta_cache[seconds]
    except KeyError:
        delta = timedelta(seconds=seconds)
        _timedelta_cache[seconds] = delta
        return delta

def memorized_datetime(seconds):
    """Create only one instance of each distinct datetime"""
    try:
        return _datetime_cache[seconds]
    except KeyError:
        dt = _epoch + timedelta(seconds=seconds)
        _datetime_cache[seconds] = dt
        return dt

def memorized_ttinfo(*args):
    """Create only one instance of each distinct tuple"""
    try:
        return _ttinfo_cache[args]
    except KeyError:
        ttinfo = (memorized_timedelta(args[0]), memorized_timedelta(args[1]), args[2])
        _ttinfo_cache[args] = ttinfo
        return ttinfo

def check_range(number, min_r, max_r, name=''):
    """Check if a number is within a given range"""
    try:
        number = float(number)
        if number < min_r or number > max_r:
            raise FFmpegNormalizeError('{} must be within [{},{}]'.format(name, min_r, max_r))
        return number
        pass
    except Exception as e:
        raise e

def which(program):
    """Find a program in PATH and return path
    From: http://stackoverflow.com/q/377017/"""
    def is_exe(fpath):
        found = os.path.isfile(fpath) and os.access(fpath, os.X_OK)
        if not found and sys.platform == 'win32':
            fpath = fpath + '.exe'
            found = os.path.isfile(fpath) and os.access(fpath, os.X_OK)
        return found
    fpath, _ = os.path.split(program)
    if fpath:
        if is_exe(program):
            logger.debug('found executable: ' + str(program))
            return program
    else:
        for path in os.environ['PATH'].split(os.pathsep):
            path = os.path.expandvars(os.path.expanduser(path)).strip('"')
            exe_file = os.path.join(path, program)
            if is_exe(exe_file):
                logger.debug('found executable in path: ' + str(exe_file))
                return exe_file
    return None

def get_ffmpeg_exe():
    """Return path to ffmpeg executable"""
    if 'FFMPEG_PATH' in os.environ:
        ffmpeg_exe = os.environ['FFMPEG_PATH']
    else:
        ffmpeg_exe = which('ffmpeg')
    if not ffmpeg_exe:
        if which('avconv'):
            raise FFmpegNormalizeError('avconv is not supported. Please install ffmpeg from http://ffmpeg.org instead.')
        else:
            raise FFmpegNormalizeError('Could not find ffmpeg in your $PATH or $FFMPEG_PATH. Please install ffmpeg from http://ffmpeg.org')
    return ffmpeg_exe

def _extract_accessor_pairs(members):
    """Extract pairs of corresponding property access methods
    (getter and setter) from a Java class's members (attributes).

    If a public method with a property's name exists no pair for
    that property will be extracted.

    Returns a dictionary with the property name as key and a tuple
    of (getter method, setter method) as value. A tuple element
    value might be `None` if only a getter or only a setter
    exists."""
    accessor_pairs = {}
    for name, member in members.items():
        if not (len(name) > _PROPERTY_ACCESSOR_PREFIX_LEN and _is_java_method(member)):
            continue
        access, rest = (name[:_PROPERTY_ACCESSOR_PREFIX_LEN], name[_PROPERTY_ACCESSOR_PREFIX_LEN:])
        property_name = rest[:1].lower() + rest[1:]
        if property_name in members:
            if _is_java_method(members[property_name]):
                continue
        if access == 'get' and member.isBeanAccessor():
            try:
                pair = accessor_pairs[property_name]
                pair[0] = member
            except KeyError:
                accessor_pairs[property_name] = [member, None]
        elif access == 'set' and member.isBeanMutator():
            try:
                pair = accessor_pairs[property_name]
                pair[1] = member
            except KeyError:
                accessor_pairs[property_name] = [None, member]
    return accessor_pairs

def getClassPath():
    """Get the full java class path.

    Includes user added paths and the environment CLASSPATH."""
    global _CLASSPATHS
    global _SEP
    out = []
    for path in _CLASSPATHS:
        if path == '':
            continue
        if path.endswith('*'):
            paths = _glob.glob(path + '.jar')
            if len(path) == 0:
                continue
            out.extend(paths)
        else:
            out.append(path)
    return _SEP.join(out)

def get_default_jvm_path():
    """Retrieves the path to the default or first found JVM library

    :return: The path to the JVM shared library file
    :raise ValueError: No JVM library found"""
    if sys.platform == 'cygwin':
        from ._cygwin import WindowsJVMFinder
        finder = WindowsJVMFinder()
    elif sys.platform == 'win32':
        from ._windows import WindowsJVMFinder
        finder = WindowsJVMFinder()
    elif sys.platform == 'darwin':
        from ._darwin import DarwinJVMFinder
        finder = DarwinJVMFinder()
    else:
        from ._linux import LinuxJVMFinder
        finder = LinuxJVMFinder()
    return finder.get_jvm_path()

def default(thumbnailer, prepared_options, source_filename, thumbnail_extension, **kwargs):
    """Easy-thumbnails' default name processor.

    For example: ``source.jpg.100x100_q80_crop_upscale.jpg``"""
    filename_parts = [source_filename]
    if '%(opts)s' in thumbnailer.thumbnail_basedir or '%(opts)s' in thumbnailer.thumbnail_subdir:
        if thumbnail_extension != os.path.splitext(source_filename)[1][1:]:
            filename_parts.append(thumbnail_extension)
    else:
        filename_parts += ['_'.join(prepared_options), thumbnail_extension]
    return '.'.join(filename_parts)

def alias(thumbnailer, thumbnail_options, source_filename, thumbnail_extension, **kwargs):
    """Generate filename based on thumbnail alias name (option ``THUMBNAIL_ALIASES``).

    For example: ``source.jpg.medium_large.jpg``"""
    return '.'.join([source_filename, thumbnail_options.get('ALIAS', ''), thumbnail_extension])

def process_image(source, processor_options, processors=None):
    """Process a source PIL image through a series of image processors, returning
    the (potentially) altered image."""
    processor_options = ThumbnailOptions(processor_options)
    if processors is None:
        processors = [utils.dynamic_import(name) for name in settings.THUMBNAIL_PROCESSORS]
    image = source
    for processor in processors:
        image = processor(image, **processor_options)
    return image

def save_image(image, destination=None, filename=None, **options):
    """Save a PIL image."""
    if destination is None:
        destination = BytesIO()
    filename = filename or ''
    Image.init()
    format = Image.EXTENSION.get(os.path.splitext(filename)[1].lower(), 'JPEG')
    if format in ('JPEG', 'WEBP'):
        options.setdefault('quality', 85)
    saved = False
    if format == 'JPEG':
        if image.mode.endswith('A'):
            image = image.convert(image.mode[:-1])
        if settings.THUMBNAIL_PROGRESSIVE and max(image.size) >= settings.THUMBNAIL_PROGRESSIVE:
            options['progressive'] = True
        try:
            image.save(destination, format=format, optimize=1, **options)
            saved = True
        except IOError:
            pass
    if not saved:
        image.save(destination, format=format, **options)
    if hasattr(destination, 'seek'):
        destination.seek(0)
    return destination

def optimize_thumbnail(thumbnail):
    """Optimize thumbnail images by removing unnecessary data"""
    try:
        optimize_command = settings.THUMBNAIL_OPTIMIZE_COMMAND[determinetype(thumbnail.path)]
        if not optimize_command:
            return
    except (TypeError, KeyError, NotImplementedError):
        return
    storage = thumbnail.storage
    try:
        with NamedTemporaryFile() as temp_file:
            thumbnail.seek(0)
            temp_file.write(thumbnail.read())
            temp_file.flush()
            optimize_command = optimize_command.format(filename=temp_file.name)
            output = check_output(optimize_command, stderr=subprocess.STDOUT, shell=True)
            if output:
                logger.warning('{0} returned {1}'.format(optimize_command, output))
            else:
                logger.info('{0} returned nothing'.format(optimize_command))
            with open(temp_file.name, 'rb') as f:
                thumbnail.file = ContentFile(f.read())
                storage.delete(thumbnail.path)
                storage.save(thumbnail.path, thumbnail)
    except Exception as e:
        logger.error(e)

def split_args(args):
    """Split a list of argument strings into a dictionary where each key is an
    argument name.

    An argument looks like ``crop``, ``crop="some option"`` or ``crop=my_var``.
    Arguments which provide no value get a value of ``True``."""
    args_dict = {}
    for arg in args:
        split_arg = arg.split('=', 1)
        if len(split_arg) > 1:
            value = split_arg[1]
        else:
            value = True
        args_dict[split_arg[0]] = value
    return args_dict

def read_files(*filenames):
    """Output the contents of one or more files to a single concatenated string."""
    output = []
    for filename in filenames:
        f = codecs.open(filename, encoding='utf-8')
        try:
            output.append(f.read())
        finally:
            f.close()
    return '\n\n'.join(output)

def thumbnails_for_file(relative_source_path, root=None, basedir=None, subdir=None, prefix=None):
    """Return a list of dictionaries, one for each thumbnail belonging to the
    source image.

    The following list explains each key of the dictionary:

      `filename`  -- absolute thumbnail path
      `x` and `y` -- the size of the thumbnail
      `options`   -- list of options for this thumbnail
      `quality`   -- quality setting for this thumbnail"""
    if root is None:
        root = settings.MEDIA_ROOT
    if prefix is None:
        prefix = settings.THUMBNAIL_PREFIX
    if subdir is None:
        subdir = settings.THUMBNAIL_SUBDIR
    if basedir is None:
        basedir = settings.THUMBNAIL_BASEDIR
    source_dir, filename = os.path.split(relative_source_path)
    thumbs_path = os.path.join(root, basedir, source_dir, subdir)
    if not os.path.isdir(thumbs_path):
        return []
    files = all_thumbnails(thumbs_path, recursive=False, prefix=prefix, subdir='')
    return files.get(filename, [])

def delete_thumbnails(relative_source_path, root=None, basedir=None, subdir=None, prefix=None):
    """Delete all thumbnails for a source image."""
    thumbs = thumbnails_for_file(relative_source_path, root, basedir, subdir, prefix)
    return _delete_using_thumbs_list(thumbs)

def find_uncommitted_filefields(sender, instance, **kwargs):
    """A pre_save signal handler which attaches an attribute to the model instance
    containing all uncommitted ``FileField``s, which can then be used by the
    :func:`signal_committed_filefields` post_save handler."""
    uncommitted = instance._uncommitted_filefields = []
    fields = sender._meta.fields
    if kwargs.get('update_fields', None):
        update_fields = set(kwargs['update_fields'])
        fields = update_fields.intersection(fields)
    for field in fields:
        if isinstance(field, FileField):
            fieldfile = getattr(instance, field.name)
            if fieldfile and (not fieldfile._committed):
                uncommitted.append(field.name)

def signal_committed_filefields(sender, instance, **kwargs):
    """A post_save signal handler which sends a signal for each ``FileField`` that
    was committed this save."""
    for field_name in getattr(instance, '_uncommitted_filefields', ()):
        fieldfile = getattr(instance, field_name)
        if fieldfile:
            signals.saved_file.send_robust(sender=sender, fieldfile=fieldfile)

def _compare_entropy(start_slice, end_slice, slice, difference):
    """Calculate the entropy of two slices (from the start and end of an axis),
    returning a tuple containing the amount that should be added to the start
    and removed from the end of the axis."""
    start_entropy = utils.image_entropy(start_slice)
    end_entropy = utils.image_entropy(end_slice)
    if end_entropy and abs(start_entropy / end_entropy - 1) < 0.01:
        if difference >= slice * 2:
            return (slice, slice)
        half_slice = slice // 2
        return (half_slice, slice - half_slice)
    if start_entropy > end_entropy:
        return (0, slice)
    else:
        return (slice, 0)

def database_get_image_dimensions(file, close=False, dimensions=None):
    """Returns the (width, height) of an image, given ThumbnailFile.  Set
    'close' to True to close the file at the end if it is initially in an open
    state.

    Will attempt to get the dimensions from the file itself if they aren't
    in the db."""
    storage_hash = utils.get_storage_hash(file.storage)
    dimensions = None
    dimensions_cache = None
    try:
        thumbnail = models.Thumbnail.objects.select_related('dimensions').get(storage_hash=storage_hash, name=file.name)
    except models.Thumbnail.DoesNotExist:
        thumbnail = None
    else:
        try:
            dimensions_cache = thumbnail.dimensions
        except models.ThumbnailDimensions.DoesNotExist:
            dimensions_cache = None
        if dimensions_cache:
            return (dimensions_cache.width, dimensions_cache.height)
    dimensions = get_image_dimensions(file, close=close)
    if settings.THUMBNAIL_CACHE_DIMENSIONS and thumbnail:
        models.ThumbnailDimensions.objects.get_or_create(thumbnail=thumbnail, defaults={'width': dimensions[0], 'height': dimensions[1]})
    return dimensions

def queryset_iterator(queryset, chunksize=1000):
    """The queryset iterator helps to keep the memory consumption down.
    And also making it easier to process for weaker computers."""
    if queryset.exists():
        primary_key = 0
        last_pk = queryset.order_by('-pk')[0].pk
        queryset = queryset.order_by('pk')
        while primary_key < last_pk:
            for row in queryset.filter(pk__gt=primary_key)[:chunksize]:
                primary_key = row.pk
                yield row
            gc.collect()

def image_entropy(im):
    """Calculate the entropy of an image. Used for "smart cropping"."""
    if not isinstance(im, Image.Image):
        return 0
    hist = im.histogram()
    hist_size = float(sum(hist))
    hist = [h / hist_size for h in hist]
    return -sum([p * math.log(p, 2) for p in hist if p != 0])

def dynamic_import(import_string):
    """Dynamically import a module or object."""
    lastdot = import_string.rfind('.')
    if lastdot == -1:
        return __import__(import_string, {}, {}, [])
    module_name, attr = (import_string[:lastdot], import_string[lastdot + 1:])
    parent_module = __import__(module_name, {}, {}, [attr])
    return getattr(parent_module, attr)

def valid_processor_options(processors=None):
    """Return a list of unique valid options for a list of image processors
    (and/or source generators)"""
    if processors is None:
        processors = [dynamic_import(p) for p in tuple(settings.THUMBNAIL_PROCESSORS) + tuple(settings.THUMBNAIL_SOURCE_GENERATORS)]
    valid_options = set(['size', 'quality', 'subsampling'])
    for processor in processors:
        args = inspect.getfullargspec(processor)[0] if six.PY3 else inspect.getargspec(processor)[0]
        valid_options.update(args[1:])
    return list(valid_options)

def get_storage_hash(storage):
    """Return a hex string hash for a storage object (or string containing
    'full.path.ClassName' referring to a storage object)."""
    if isinstance(storage, LazyObject):
        if storage._wrapped is None:
            storage._setup()
        storage = storage._wrapped
    if not isinstance(storage, six.string_types):
        storage_cls = storage.__class__
        storage = '%s.%s' % (storage_cls.__module__, storage_cls.__name__)
    return hashlib.md5(storage.encode('utf8')).hexdigest()

def is_transparent(image):
    """Check to see if an image is transparent."""
    if not isinstance(image, Image.Image):
        return False
    return image.mode in ('RGBA', 'LA') or (image.mode == 'P' and 'transparency' in image.info)

def is_progressive(image):
    """Check to see if an image is progressive."""
    if not isinstance(image, Image.Image):
        return False
    return 'progressive' in image.info or 'progression' in image.info

def exif_orientation(im):
    """Rotate and/or flip an image to respect the image's EXIF orientation data."""
    try:
        exif = im._getexif()
    except Exception:
        exif = None
    if exif:
        orientation = exif.get(274)
        if orientation == 2:
            im = im.transpose(Image.FLIP_LEFT_RIGHT)
        elif orientation == 3:
            im = im.transpose(Image.ROTATE_180)
        elif orientation == 4:
            im = im.transpose(Image.FLIP_TOP_BOTTOM)
        elif orientation == 5:
            im = im.transpose(Image.ROTATE_270).transpose(Image.FLIP_LEFT_RIGHT)
        elif orientation == 6:
            im = im.transpose(Image.ROTATE_270)
        elif orientation == 7:
            im = im.transpose(Image.ROTATE_90).transpose(Image.FLIP_LEFT_RIGHT)
        elif orientation == 8:
            im = im.transpose(Image.ROTATE_90)
    return im

def get_modified_time(storage, name):
    """Get modified time from storage, ensuring the result is a timezone-aware
    datetime."""
    try:
        try:
            modified_time = storage.get_modified_time(name)
        except AttributeError:
            modified_time = storage.modified_time(name)
    except OSError:
        return 0
    except NotImplementedError:
        return None
    if modified_time and timezone.is_naive(modified_time):
        if getattr(settings, 'USE_TZ', False):
            default_timezone = timezone.get_default_timezone()
            return timezone.make_aware(modified_time, default_timezone)
    return modified_time

def odo_register():
    """Enable conversion of .sdmx files with odo (http://odo.readthedocs.org).
    Adds conversion from sdmx to PD.DataFrame to odo graph.
    Note that native discovery of sdmx files is not yet supported. odo will thus
    convert to PD.DataFrame
    and discover the data shape from there."""
    logger.info('Registering with odo...')
    import odo
    from odo.utils import keywords
    import pandas as PD
    from toolz import keyfilter
    import toolz.curried.operator as op
    class PandaSDMX(object):
        def __init__(self, uri):
            self.uri = uri
    @odo.resource.register('.*\\.sdmx')
    def resource_sdmx(uri, **kwargs):
        return PandaSDMX(uri)
    @odo.discover.register(PandaSDMX)
    def _(sdmx):
        return odo.discover(Request().get(fromfile=sdmx.uri).write())
    @odo.convert.register(PD.DataFrame, PandaSDMX)
    def convert_sdmx(sdmx, **kwargs):
        write = Request().get(fromfile=sdmx.uri).write
        return write(**keyfilter(op.contains(keywords(write)), kwargs))
    logger.info('odo registration complete.')

def concat_namedtuples(*tup, **kwargs):
    """Concatenate 2 or more namedtuples. The new namedtuple type
    is provided by :class:`NamedTupleFactory`
    return new namedtuple instance"""
    name = kwargs['name'] if 'name' in kwargs else None
    filtered = [i for i in filter(None, tup)]
    if filtered:
        if len(filtered) == 1:
            return filtered[0]
        else:
            fields = chain(*(t._fields for t in filtered))
            values = chain(*(t for t in filtered))
            if not name:
                name = 'SDMXNamedTuple'
            ConcatType = namedtuple_factory(name, fields)
            return ConcatType(*values)
    else:
        return ()

def tokenize(s):
    """Translate a type comment into a list of tokens."""
    original = s
    tokens = []
    while True:
        if not s:
            tokens.append(End())
            return tokens
        elif s[0] == ' ':
            s = s[1:]
        elif s[0] in '()[],*':
            tokens.append(Separator(s[0]))
            s = s[1:]
        elif s[:2] == '->':
            tokens.append(Separator('->'))
            s = s[2:]
        else:
            m = re.match('[-\\w]+(\\s*(\\.|:)\\s*[-/\\w]*)*', s)
            if not m:
                raise ParseError(original)
            fullname = m.group(0)
            fullname = fullname.replace(' ', '')
            if fullname in TYPE_FIXUPS:
                fullname = TYPE_FIXUPS[fullname]
            if fullname.startswith('pytz.tzfile.'):
                fullname = 'datetime.tzinfo'
            if '-' in fullname or '/' in fullname:
                fullname = 'Any'
            tokens.append(DottedName(fullname))
            s = s[len(m.group(0)):]

def generate_annotations_json_string(source_path, only_simple=False):
    """Produce annotation data JSON file from a JSON file with runtime-collected types.

    Data formats:

    * The source JSON is a list of pyannotate_tools.annotations.parse.RawEntry items.
    * The output JSON is a list of FunctionData items."""
    items = parse_json(source_path)
    results = []
    for item in items:
        signature = unify_type_comments(item.type_comments)
        if is_signature_simple(signature) or not only_simple:
            data = {'path': item.path, 'line': item.line, 'func_name': item.func_name, 'signature': signature, 'samples': item.samples}
            results.append(data)
    return results

def _my_hash(arg_list):
    """Simple helper hash function"""
    res = 0
    for arg in arg_list:
        res = res * 31 + hash(arg)
    return res

def name_from_type(type_):
    """Helper function to get PEP-484 compatible string representation of our internal types."""
    if isinstance(type_, (DictType, ListType, TupleType, SetType, IteratorType)):
        return repr(type_)
    elif type_.__name__ != 'NoneType':
        module = type_.__module__
        if module in BUILTIN_MODULES or module == '<unknown>':
            return type_.__name__
        else:
            name = getattr(type_, '__qualname__', None) or type_.__name__
            delim = '.' if '.' not in name else ':'
            return '%s%s%s' % (module, delim, name)
    else:
        return 'None'

def prep_args(arg_info):
    """Resolve types from ArgInfo"""
    filtered_args = [a for a in arg_info.args if getattr(arg_info, 'varargs', None) != a]
    if filtered_args and filtered_args[0] in ('self', 'cls'):
        filtered_args = filtered_args[1:]
    pos_args = []
    if filtered_args:
        for arg in filtered_args:
            if isinstance(arg, str) and arg in arg_info.locals:
                resolved_type = resolve_type(arg_info.locals[arg])
                pos_args.append(resolved_type)
            else:
                pos_args.append(type(UnknownType()))
    varargs = None
    if arg_info.varargs:
        varargs_tuple = arg_info.locals[arg_info.varargs]
        if isinstance(varargs_tuple, tuple):
            varargs = [resolve_type(arg) for arg in varargs_tuple[:4]]
    return ResolvedTypes(pos_args=pos_args, varargs=varargs)

def _make_type_comment(args_info, return_type):
    """Generate a type comment of form '(arg, ...) -> ret'."""
    if not args_info.pos_args:
        args_string = ''
    else:
        args_string = ', '.join([repr(t) for t in args_info.pos_args])
    if args_info.varargs:
        varargs = '*%s' % repr(args_info.varargs)
        if args_string:
            args_string += ', %s' % varargs
        else:
            args_string = varargs
    return_name = name_from_type(return_type)
    return '(%s) -> %s' % (args_string, return_name)

def type_consumer():
    """Infinite loop of the type consumer thread.
    It gets types to process from the task query."""
    while True:
        item = _task_queue.get()
        if isinstance(item, KeyAndTypes):
            if item.key in collected_args:
                _flush_signature(item.key, UnknownType)
            collected_args[item.key] = ArgTypes(item.types)
        else:
            assert isinstance(item, KeyAndReturn)
            if item.key in collected_args:
                _flush_signature(item.key, item.return_type)
        _task_queue.task_done()

def default_filter_filename(filename):
    """Default filter for filenames.

    Returns either a normalized filename or None.
    You can pass your own filter to init_types_collection()."""
    if filename is None:
        return None
    elif filename.startswith(TOP_DIR):
        if filename.startswith(TOP_DIR_DOT):
            return None
        else:
            return filename[TOP_DIR_LEN:].lstrip(os.sep)
    elif filename.startswith(os.sep):
        return None
    else:
        return filename

def _filter_types(types_dict):
    """Filter type info before dumping it to the file."""
    def exclude(k):
        """Exclude filter"""
        return k.path.startswith('<') or k.func_name == '<module>'
    return {k: v for k, v in iteritems(types_dict) if not exclude(k)}

def infer_annotation(type_comments):
    """Given some type comments, return a single inferred signature.

    Args:
        type_comments: Strings of form '(arg1, ... argN) -> ret'

    Returns: Tuple of (argument types and kinds, return type)."""
    assert type_comments
    args = {}
    returns = set()
    for comment in type_comments:
        arg_types, return_type = parse_type_comment(comment)
        for i, arg_type in enumerate(arg_types):
            args.setdefault(i, set()).add(arg_type)
        returns.add(return_type)
    combined_args = []
    for i in sorted(args):
        arg_infos = list(args[i])
        kind = argument_kind(arg_infos)
        if kind is None:
            raise InferError('Ambiguous argument kinds:\n' + '\n'.join(type_comments))
        types = [arg.type for arg in arg_infos]
        combined = combine_types(types)
        if str(combined) == 'None':
            combined = UnionType([ClassType('None'), AnyType()])
        if kind != ARG_POS and (len(str(combined)) > 120 or isinstance(combined, UnionType)):
            combined = AnyType()
        combined_args.append(Argument(combined, kind))
    combined_return = combine_types(returns)
    return (combined_args, combined_return)

def argument_kind(args):
    """Return the kind of an argument, based on one or more descriptions of the argument.

    Return None if every item does not have the same kind."""
    kinds = set((arg.kind for arg in args))
    if len(kinds) != 1:
        return None
    return kinds.pop()

def combine_types(types):
    """Given some types, return a combined and simplified type.

    For example, if given 'int' and 'List[int]', return Union[int, List[int]]. If given
    'int' and 'int', return just 'int'."""
    items = simplify_types(types)
    if len(items) == 1:
        return items[0]
    else:
        return UnionType(items)

def simplify_recursive(typ):
    """Simplify all components of a type."""
    if isinstance(typ, UnionType):
        return combine_types(typ.items)
    elif isinstance(typ, ClassType):
        simplified = ClassType(typ.name, [simplify_recursive(arg) for arg in typ.args])
        args = simplified.args
        if simplified.name == 'Dict' and len(args) == 2 and isinstance(args[0], ClassType) and (args[0].name in ('str', 'Text')) and isinstance(args[1], UnionType) and (not is_optional(args[1])):
            return ClassType('Dict', [args[0], AnyType()])
        return simplified
    elif isinstance(typ, TupleType):
        return TupleType([simplify_recursive(item) for item in typ.items])
    return typ

def remove_redundant_items(items):
    """Filter out redundant union items."""
    result = []
    for item in items:
        for other in items:
            if item is not other and is_redundant_union_item(item, other):
                break
        else:
            result.append(item)
    return result

def is_redundant_union_item(first, other):
    """If union has both items, is the first one redundant?

    For example, if first is 'str' and the other is 'Text', return True.

    If items are equal, return False."""
    if isinstance(first, ClassType) and isinstance(other, ClassType):
        if first.name == 'str' and other.name == 'Text':
            return True
        elif first.name == 'bool' and other.name == 'int':
            return True
        elif first.name == 'int' and other.name == 'float':
            return True
        elif first.name in ('List', 'Dict', 'Set') and other.name == first.name:
            if not first.args and other.args:
                return True
            elif len(first.args) == len(other.args) and first.args:
                result = all((first_arg == other_arg or other_arg == AnyType() for first_arg, other_arg in zip(first.args, other.args)))
                return result
    return False

def merge_items(items):
    """Merge union items that can be merged."""
    result = []
    while items:
        item = items.pop()
        merged = None
        for i, other in enumerate(items):
            merged = merged_type(item, other)
            if merged:
                break
        if merged:
            del items[i]
            items.append(merged)
        else:
            result.append(item)
    return list(reversed(result))

def merged_type(t, s):
    """Return merged type if two items can be merged in to a different, more general type.

    Return None if merging is not possible."""
    if isinstance(t, TupleType) and isinstance(s, TupleType):
        if len(t.items) == len(s.items):
            return TupleType([combine_types([ti, si]) for ti, si in zip(t.items, s.items)])
        all_items = t.items + s.items
        if all_items and all((item == all_items[0] for item in all_items[1:])):
            return ClassType('Tuple', [all_items[0]])
    elif isinstance(t, TupleType) and isinstance(s, ClassType) and (s.name == 'Tuple') and (len(s.args) == 1):
        if all((item == s.args[0] for item in t.items)):
            return s
    elif isinstance(s, TupleType) and isinstance(t, ClassType) and (t.name == 'Tuple'):
        return merged_type(s, t)
    elif isinstance(s, NoReturnType):
        return t
    elif isinstance(t, NoReturnType):
        return s
    elif isinstance(s, AnyType):
        return t
    elif isinstance(t, AnyType):
        return s
    return None

def crawl_up(arg):
    """Given a .py[i] filename, return (root directory, module).
    We crawl up the path until we find a directory without
    __init__.py[i], or until we run out of path components."""
    dir, mod = os.path.split(arg)
    mod = strip_py(mod) or mod
    while dir and get_init_file(dir):
        dir, base = os.path.split(dir)
        if not base:
            break
        if mod == '__init__' or not mod:
            mod = base
        else:
            mod = base + '.' + mod
    return (dir, mod)

def strip_py(arg):
    """Strip a trailing .py or .pyi suffix.
    Return None if no such suffix is found."""
    for ext in PY_EXTENSIONS:
        if arg.endswith(ext):
            return arg[:-len(ext)]
    return None

def get_init_file(dir):
    """Check whether a directory contains a file named __init__.py[i].
    If so, return the file's name (with dir prefixed).  If not, return
    None.
    This prefers .pyi over .py (because of the ordering of PY_EXTENSIONS)."""
    for ext in PY_EXTENSIONS:
        f = os.path.join(dir, '__init__' + ext)
        if os.path.isfile(f):
            return f
    return None

def inform_if_paths_invalid(egrc_path, examples_dir, custom_dir, debug=True):
    """If egrc_path, examples_dir, or custom_dir is truthy and debug is True,
    informs the user that a path is not set.

    This should be used to verify input arguments from the command line."""
    if not debug:
        return
    if egrc_path:
        _inform_if_path_does_not_exist(egrc_path)
    if examples_dir:
        _inform_if_path_does_not_exist(examples_dir)
    if custom_dir:
        _inform_if_path_does_not_exist(custom_dir)

def get_expanded_path(path):
    """Expand ~ and variables in a path. If path is not truthy, return None."""
    if path:
        result = path
        result = os.path.expanduser(result)
        result = os.path.expandvars(result)
        return result
    else:
        return None

def _inform_if_path_does_not_exist(path):
    """If the path does not exist, print a message saying so. This is intended to
    be helpful to users if they specify a custom path that eg cannot find."""
    expanded_path = get_expanded_path(path)
    if not os.path.exists(expanded_path):
        print('Could not find custom path at: {}'.format(expanded_path))

def _get_color_from_config(config, option):
    """Helper method to uet an option from the COLOR_SECTION of the config.

    Returns None if the value is not present. If the value is present, it tries
    to parse the value as a raw string literal, allowing escape sequences in
    the egrc."""
    if not config.has_option(COLOR_SECTION, option):
        return None
    else:
        return ast.literal_eval(config.get(COLOR_SECTION, option))

def parse_substitution_from_list(list_rep):
    """Parse a substitution from the list representation in the config file."""
    if type(list_rep) is not list:
        raise SyntaxError('Substitution must be a list')
    if len(list_rep) < 2:
        raise SyntaxError('Substitution must be a list of size 2')
    pattern = list_rep[0]
    replacement = list_rep[1]
    is_multiline = False
    if len(list_rep) > 2:
        is_multiline = list_rep[2]
        if type(is_multiline) is not bool:
            raise SyntaxError('is_multiline must be a boolean')
    result = substitute.Substitution(pattern, replacement, is_multiline)
    return result

def edit_custom_examples(program, config):
    """Edit custom examples for the given program, creating the file if it does
    not exist."""
    if not config.custom_dir or not os.path.exists(config.custom_dir):
        _inform_cannot_edit_no_custom_dir()
        return
    resolved_program = get_resolved_program(program, config)
    custom_file_paths = get_file_paths_for_program(resolved_program, config.custom_dir)
    if len(custom_file_paths) > 0:
        path_to_edit = custom_file_paths[0]
    else:
        path_to_edit = os.path.join(config.custom_dir, resolved_program + '.md')
    subprocess.call([config.editor_cmd, path_to_edit])

def get_file_paths_for_program(program, dir_to_search):
    """Return an array of full paths matching the given program. If no directory is
    present, returns an empty list.

    Path is not guaranteed to exist. Just says where it should be if it
    existed. Paths must be fully expanded before being passed in (i.e. no ~ or
    variables)."""
    if dir_to_search is None:
        return []
    else:
        wanted_file_name = program + EXAMPLE_FILE_SUFFIX
        result = []
        for basedir, dirs, file_names in os.walk(dir_to_search):
            for file_name in file_names:
                if file_name == wanted_file_name:
                    result.append(os.path.join(basedir, file_name))
        return result

def page_string(str_to_page, pager_cmd):
    """Page str_to_page via the pager."""
    use_fallback_page_function = False
    if pager_cmd is None:
        use_fallback_page_function = True
    elif pager_cmd == FLAG_FALLBACK:
        use_fallback_page_function = True
    try:
        if use_fallback_page_function:
            pydoc.pager(str_to_page)
        else:
            pydoc.pipepager(str_to_page, cmd=pager_cmd)
    except KeyboardInterrupt:
        pass

def get_formatted_contents(raw_contents, use_color, color_config, squeeze, subs):
    """Apply formatting to raw_contents and return the result. Formatting is
    applied in the order: color, squeeze, subs."""
    result = raw_contents
    if use_color:
        result = get_colorized_contents(result, color_config)
    if squeeze:
        result = get_squeezed_contents(result)
    if subs:
        result = get_substituted_contents(result, subs)
    return result

def get_alias_dict(config_obj):
    """Return a dictionary consisting of all aliases known to eg.

    The format is {'alias': 'resolved_program'}.

    If the aliases file does not exist, returns an empty dict."""
    if not config_obj.examples_dir:
        return {}
    alias_file_path = _get_alias_file_path(config_obj)
    if not os.path.isfile(alias_file_path):
        return {}
    alias_file_contents = _get_contents_of_file(alias_file_path)
    result = json.loads(alias_file_contents)
    return result

def decorate(func, caller, extras=()):
    """decorate(func, caller) decorates a function using a caller.
    If the caller is a generator function, the resulting function
    will be a generator function."""
    evaldict = dict(_call_=caller, _func_=func)
    es = ''
    for i, extra in enumerate(extras):
        ex = '_e%d_' % i
        evaldict[ex] = extra
        es += ex + ', '
    if '3.5' <= sys.version < '3.6':
        generatorcaller = isgeneratorfunction(caller) and (not iscoroutinefunction(caller))
    else:
        generatorcaller = isgeneratorfunction(caller)
    if generatorcaller:
        fun = FunctionMaker.create(func, 'for res in _call_(_func_, %s%%(shortsignature)s):\n    yield res' % es, evaldict, __wrapped__=func)
    else:
        fun = FunctionMaker.create(func, 'return _call_(_func_, %s%%(shortsignature)s)' % es, evaldict, __wrapped__=func)
    if hasattr(func, '__qualname__'):
        fun.__qualname__ = func.__qualname__
    return fun

def decorator(caller, _func=None):
    """decorator(caller) converts a caller function into a decorator"""
    if _func is not None:
        return decorate(_func, caller)
    defaultargs, defaults = ('', ())
    if inspect.isclass(caller):
        name = caller.__name__.lower()
        doc = 'decorator(%s) converts functions/generators into factories of %s objects' % (caller.__name__, caller.__name__)
    elif inspect.isfunction(caller):
        if caller.__name__ == '<lambda>':
            name = '_lambda_'
        else:
            name = caller.__name__
        doc = caller.__doc__
        nargs = caller.__code__.co_argcount
        ndefs = len(caller.__defaults__ or ())
        defaultargs = ', '.join(caller.__code__.co_varnames[nargs - ndefs:nargs])
        if defaultargs:
            defaultargs += ','
        defaults = caller.__defaults__
    else:
        name = caller.__class__.__name__.lower()
        doc = caller.__call__.__doc__
    evaldict = dict(_call=caller, _decorate_=decorate)
    dec = FunctionMaker.create('%s(func, %s)' % (name, defaultargs), 'if func is None: return lambda func:  _decorate_(func, _call, (%s))\nreturn _decorate_(func, _call, (%s))' % (defaultargs, defaultargs), evaldict, doc=doc, module=caller.__module__, __wrapped__=caller)
    if defaults:
        dec.__defaults__ = (None,) + defaults
    return dec

def _get_signature_object(func, as_instance, eat_self):
    """Given an arbitrary, possibly callable object, try to create a suitable
    signature object.
    Return a (reduced func, signature) tuple, or None."""
    if isinstance(func, ClassTypes) and (not as_instance):
        try:
            func = func.__init__
        except AttributeError:
            return None
        eat_self = True
    elif not isinstance(func, FunctionTypes):
        try:
            func = func.__call__
        except AttributeError:
            return None
    if eat_self:
        sig_func = partial(func, None)
    else:
        sig_func = func
    try:
        return (func, inspectsignature(sig_func))
    except ValueError:
        return None

def _instance_callable(obj):
    """Given an object, return True if the object is callable.
    For classes, return True if instances would be callable."""
    if not isinstance(obj, ClassTypes):
        return getattr(obj, '__call__', None) is not None
    if six.PY3:
        for base in (obj,) + obj.__mro__:
            if base.__dict__.get('__call__') is not None:
                return True
    else:
        klass = obj
        if klass.__dict__.get('__call__') is not None:
            return True
        for base in klass.__bases__:
            if _instance_callable(base):
                return True
    return False

def is_scheme(scheme, slashes=True):
    """Return whether *scheme* is valid for external links."""
    scheme = scheme.lower()
    if slashes:
        return scheme in URI_SCHEMES
    return scheme in URI_SCHEMES and (not URI_SCHEMES[scheme])

def make(name):
    """Create a new Token class using ``type()`` and add it to ``__all__``."""
    __all__.append(name)
    return type(name if py3k else name.encode('utf8'), (Token,), {})

def _find_literal(s, start, level, parts, exprs):
    """Roughly Python/ast.c:fstring_find_literal"""
    i = start
    parse_expr = True
    while i < len(s):
        ch = s[i]
        if ch in ('{', '}'):
            if level == 0:
                if i + 1 < len(s) and s[i + 1] == ch:
                    i += 2
                    parse_expr = False
                    break
                elif ch == '}':
                    raise SyntaxError("f-string: single '}' is not allowed")
            break
        i += 1
    parts.append(s[start:i])
    return (i, parse_expr and i < len(s))

def _fstring_parse(s, i, level, parts, exprs):
    """Roughly Python/ast.c:fstring_find_literal_and_expr"""
    while True:
        i, parse_expr = _find_literal(s, i, level, parts, exprs)
        if i == len(s) or s[i] == '}':
            return i
        if parse_expr:
            i = _find_expr(s, i, level, parts, exprs)

def write_pid_file(fn):
    """Create a file with our PID."""
    if not fn:
        return None
    if fn == '' or fn == "''":
        return None
    f = open(fn, 'w')
    f.write('%s\n' % os.getpid())
    f.close()

def hexdump(src, length=8):
    """Produce a string hexdump of src, for debug output."""
    if not src:
        return str(src)
    src = input_validate_str(src, 'src')
    offset = 0
    result = ''
    for this in group(src, length):
        hex_s = ' '.join(['%02x' % ord(x) for x in this])
        result += '%04X   %s\n' % (offset, hex_s)
        offset += length
    return result

def group(data, num):
    """Split data into chunks of num chars each"""
    return [data[i:i + num] for i in xrange(0, len(data), num)]

def key_handle_to_int(this):
    """Turn "123" into 123 and "KSM1" into 827151179
    (0x314d534b, 'K' = 0x4b, S = '0x53', M = 0x4d).

    YHSM is little endian, so this makes the bytes KSM1 appear
    in the most human readable form in packet traces."""
    try:
        num = int(this)
        return num
    except ValueError:
        if this[:2] == '0x':
            return int(this, 16)
        if len(this) == 4:
            num = struct.unpack('<I', this)[0]
            return num
    raise pyhsm.exception.YHSM_Error("Could not parse key_handle '%s'" % this)

def input_validate_str(string, name, max_len=None, exact_len=None):
    """Input validation for strings."""
    if type(string) is not str:
        raise pyhsm.exception.YHSM_WrongInputType(name, str, type(string))
    if max_len != None and len(string) > max_len:
        raise pyhsm.exception.YHSM_InputTooLong(name, max_len, len(string))
    if exact_len != None and len(string) != exact_len:
        raise pyhsm.exception.YHSM_WrongInputSize(name, exact_len, len(string))
    return string

def input_validate_int(value, name, max_value=None):
    """Input validation for integers."""
    if type(value) is not int:
        raise pyhsm.exception.YHSM_WrongInputType(name, int, type(value))
    if max_value != None and value > max_value:
        raise pyhsm.exception.YHSM_WrongInputSize(name, max_value, value)
    return value

def input_validate_nonce(nonce, name='nonce', pad=False):
    """Input validation for nonces."""
    if type(nonce) is not str:
        raise pyhsm.exception.YHSM_WrongInputType(name, str, type(nonce))
    if len(nonce) > pyhsm.defines.YSM_AEAD_NONCE_SIZE:
        raise pyhsm.exception.YHSM_InputTooLong(name, pyhsm.defines.YSM_AEAD_NONCE_SIZE, len(nonce))
    if pad:
        return nonce.ljust(pyhsm.defines.YSM_AEAD_NONCE_SIZE, chr(0))
    else:
        return nonce

def input_validate_key_handle(key_handle, name='key_handle'):
    """Input validation for key_handles."""
    if type(key_handle) is not int:
        try:
            return key_handle_to_int(key_handle)
        except pyhsm.exception.YHSM_Error:
            raise pyhsm.exception.YHSM_WrongInputType(name, int, type(key_handle))
    return key_handle

def input_validate_yubikey_secret(data, name='data'):
    """Input validation for YHSM_YubiKeySecret or string."""
    if isinstance(data, pyhsm.aead_cmd.YHSM_YubiKeySecret):
        data = data.pack()
    return input_validate_str(data, name)

def input_validate_aead(aead, name='aead', expected_len=None, max_aead_len=pyhsm.defines.YSM_AEAD_MAX_SIZE):
    """Input validation for YHSM_GeneratedAEAD or string."""
    if isinstance(aead, pyhsm.aead_cmd.YHSM_GeneratedAEAD):
        aead = aead.data
    if expected_len != None:
        return input_validate_str(aead, name, exact_len=expected_len)
    else:
        return input_validate_str(aead, name, max_len=max_aead_len)

def validate_cmd_response_int(name, got, expected):
    """Check that some value returned in the response to a command matches what
    we put in the request (the command)."""
    if got != expected:
        raise pyhsm.exception.YHSM_Error('Bad %s in response (got %i, expected %i)' % (name, got, expected))
    return got

def validate_cmd_response_hex(name, got, expected):
    """Check that some value returned in the response to a command matches what
    we put in the request (the command)."""
    if got != expected:
        raise pyhsm.exception.YHSM_Error('Bad %s in response (got 0x%x, expected 0x%x)' % (name, got, expected))
    return got

def validate_cmd_response_str(name, got, expected, hex_encode=True):
    """Check that some value returned in the response to a command matches what
    we put in the request (the command)."""
    if got != expected:
        if hex_encode:
            got_s = got.encode('hex')
            exp_s = expected.encode('hex')
        else:
            got_s = got
            exp_s = expected
        raise pyhsm.exception.YHSM_Error('Bad %s in response (got %s, expected %s)' % (name, got_s, exp_s))
    return got

def validate_cmd_response_nonce(got, used):
    """Check that the returned nonce matches nonce used in request.

    A request nonce of 000000000000 means the HSM should generate a nonce internally though,
    so if 'used' is all zeros we actually check that 'got' does NOT match 'used'."""
    if used == '000000000000'.decode('hex'):
        if got == used:
            raise pyhsm.exception.YHSM_Error('Bad nonce in response (got %s, expected HSM generated nonce)' % got.encode('hex'))
        return got
    return validate_cmd_response_str('nonce', got, used)

def _raw_pack(key_handle, flags, data):
    """Common code for packing payload to YHSM_HMAC_SHA1_GENERATE command."""
    return struct.pack('<IBB', key_handle, flags, len(data)) + data

def make_otp_response(vres, client_key):
    """Create validation response (signed, if a client key is supplied)."""
    if client_key is not None:
        sig = make_signature(vres, client_key)
        vres['h'] = sig
    pairs = [x + '=' + ''.join(vres[x]) for x in sorted(vres.keys())]
    return '\n'.join(pairs)

def check_signature(params):
    """Verify the signature of the parameters in an OTP v2.0 verify request.

    Returns ValResultBool, Key"""
    if 'id' in params:
        try:
            id_int = int(params['id'][0])
        except:
            my_log_message(args, syslog.LOG_INFO, 'Non-numerical client id (%s) in request.' % params['id'][0])
            return (False, None)
        key = client_ids.get(id_int)
        if key:
            if 'h' in params:
                sig = params['h'][0]
                good_sig = make_signature(params, key)
                if sig == good_sig:
                    return (True, key)
                else:
                    my_log_message(args, syslog.LOG_INFO, "Bad signature from client id '%i' (%s, expected %s)." % (id_int, sig, good_sig))
            else:
                my_log_message(args, syslog.LOG_INFO, 'Client id (%i) but no HMAC in request.' % id_int)
                return (False, key)
        else:
            my_log_message(args, syslog.LOG_INFO, "Unknown client id '%i'" % id_int)
            return (False, None)
    return (True, None)

def make_signature(params, hmac_key):
    """Calculate a HMAC-SHA-1 (using hmac_key) of all the params except "h=".

    Returns base64 encoded signature as string."""
    pairs = [x + '=' + ''.join(params[x]) for x in sorted(params.keys()) if x != 'h']
    sha = hmac.new(hmac_key, '&'.join(pairs), hashlib.sha1)
    return base64.b64encode(sha.digest())

def get_pwhash_bits(params):
    """Extract bits for password hash validation from params."""
    if not 'pwhash' in params or not 'nonce' in params or (not 'aead' in params) or (not 'kh' in params):
        raise Exception('Missing required parameter in request (pwhash, nonce, aead or kh)')
    pwhash = params['pwhash'][0]
    nonce = params['nonce'][0]
    aead = params['aead'][0]
    key_handle = pyhsm.util.key_handle_to_int(params['kh'][0])
    return (pwhash, nonce, aead, key_handle)

def get_oath_hotp_bits(params):
    """Extract the OATH-HOTP uid and OTP from params."""
    if 'uid' in params:
        return (params['uid'][0], int(params['hotp'][0]))
    m = re.match('^([cbdefghijklnrtuv]*)([0-9]{6,8})', params['hotp'][0])
    uid, otp = m.groups()
    return (uid, int(otp))

def args_fixup():
    """Various cleanups/initializations based on result of parse_args()."""
    global saved_key_handle
    saved_key_handle = args.hmac_kh
    args.key_handle = pyhsm.util.key_handle_to_int(args.hmac_kh)
    if not (args.mode_otp or args.mode_short_otp or args.mode_totp or args.mode_hotp or args.mode_pwhash):
        my_log_message(args, syslog.LOG_ERR, 'No validation mode enabled')
        sys.exit(1)
    global client_ids
    if args.clients_file != None:
        if not args.mode_otp:
            my_log_message(args, syslog.LOG_ERR, 'Clients file should only be used with --otp.')
            sys.exit(1)
        client_ids = load_clients_file(args.clients_file)
        if not client_ids:
            my_log_message(args, syslog.LOG_ERR, 'Failed loading clients file "%s"' % args.clients_file)
            sys.exit(1)
    else:
        loaded_client_ids = load_clients_file(default_clients_file)
        if loaded_client_ids:
            args.clients_file = default_clients_file
            client_ids = loaded_client_ids

def load_clients_file(filename):
    """Load a list of base64 encoded shared secrets for numerical client ids.

    Returns a dict.

    Format of file is expected to be

        # This is a comment. Blank lines are OK.

        123,c2hhcmVkIHNlY3JldA==
        456,MTIzNDU2Nzg5MDEyMw=="""
    res = {}
    content = []
    try:
        fhandle = file(filename)
        content = fhandle.readlines()
        fhandle.close()
    except IOError:
        return None
    linenum = 0
    for line in content:
        linenum += 1
        while line.endswith('\r') or line.endswith('\n'):
            line = line[:-1]
        if re.match('(^\\s*#|^\\s*$)', line):
            continue
        parts = [x.strip() for x in line.split(',')]
        try:
            if len(parts) != 2:
                raise Exception()
            id_num = int(parts[0])
            key = base64.b64decode(parts[1])
            res[id_num] = key
        except:
            my_log_message(args, syslog.LOG_ERR, 'Bad data on line %i of clients file "%s" : "%s"' % (linenum, filename, line))
            return None
    return res

def aead_filename(aead_dir, key_handle, public_id):
    """Return the filename of the AEAD for this public_id,
    and create any missing directorys."""
    parts = [aead_dir, key_handle] + pyhsm.util.group(public_id, 2)
    path = os.path.join(*parts)
    if not os.path.isdir(path):
        os.makedirs(path)
    return os.path.join(path, public_id)

def walk_dir(path, args, state):
    """Check all files in `path' to see if there is any requests that
    we should send out on the bus."""
    if args.debug:
        sys.stderr.write('Walking %s\n' % path)
    for root, _dirs, files in os.walk(path):
        if not safe_process_files(root, files, args, state):
            return False
        if state.should_quit():
            return False
    return True

def main():
    """Main function when running as a program."""
    global args
    args = parse_args()
    if not args:
        return 1
    state = MyState(args)
    for path in args.paths:
        if os.path.isdir(path):
            walk_dir(path, args, state)
        else:
            safe_process_files(os.path.dirname(path), [os.path.basename(path)], args, state)
        if state.should_quit():
            break
    if state.failed_files:
        sys.stderr.write('error: %i/%i AEADs failed\n' % (len(state.failed_files), state.file_count))
        return 1
    if args.debug:
        sys.stderr.write('Successfully processed %i AEADs\n' % state.file_count)

def keyhandles_fixup(args):
    """Walk through the supplied key handles and normalize them, while keeping
    the input format too (as value in a dictionary). The input format is
    used in AEAD filename paths."""
    new_handles = {}
    for val in args.key_handles:
        n = pyhsm.util.key_handle_to_int(val)
        new_handles[n] = val
    args.key_handles = new_handles

def shorten_aead(aead):
    """Produce pretty-printable version of long AEAD."""
    head = aead.data[:4].encode('hex')
    tail = aead.data[-4:].encode('hex')
    return '%s...%s' % (head, tail)

def aead_filename(aead_dir, key_handle, public_id):
    """Return the filename of the AEAD for this public_id."""
    parts = [aead_dir, key_handle] + pyhsm.util.group(public_id, 2) + [public_id]
    return os.path.join(*parts)

def args_fixup(args):
    """Additional checks/cleanups of parsed arguments."""
    res = []
    for kh in args.key_handles:
        kh_int = pyhsm.util.key_handle_to_int(kh)
        res.append((kh, kh_int))
    args.key_handles = res
    if args.db_url and args.db_url.startswith('env:'):
        env_var = args.db_url[4:]
        if env_var in os.environ:
            args.db_url = os.environ[env_var]

def my_log_message(verbose, prio, msg):
    """Log to syslog, and possibly also to stderr."""
    syslog.syslog(prio, msg)
    if verbose or prio == syslog.LOG_ERR:
        sys.stderr.write('%s\n' % msg)

def get_oath_k(args):
    """Get the OATH K value (secret key), either from args or by prompting."""
    if args.oath_k:
        decoded = args.oath_k.decode('hex')
    else:
        t = raw_input('Enter OATH key (hex encoded) : ')
        decoded = t.decode('hex')
    if len(decoded) > 20:
        decoded = sha1(decoded).digest()
    decoded = decoded.ljust(20, '\x00')
    return decoded

def insert_slash(string, every=2):
    """insert_slash insert / every 2 char"""
    return os.path.join((string[i:i + every] for i in xrange(0, len(string), every)))

def main():
    """What will be executed when running as a stand alone program."""
    args = parse_args()
    try:
        s = pyhsm.base.YHSM(device=args.device, debug=args.debug)
        get_entropy(s, args.iterations, args.ratio)
        return 0
    except pyhsm.exception.YHSM_Error as e:
        sys.stderr.write('ERROR: %s' % e.reason)
        return 1

def timecode(time_now, interval):
    """make integer and divide by time interval of valid OTP"""
    i = time.mktime(time_now.timetuple())
    return int(i / interval)

def _xor_block(a, b):
    """XOR two blocks of equal length."""
    return ''.join([chr(ord(x) ^ ord(y)) for x, y in zip(a, b)])

def aesCCM(key, key_handle, nonce, data, decrypt=False):
    """Function implementing YubiHSM AEAD encrypt/decrypt in software."""
    if decrypt:
        data, saved_mac = _split_data(data, len(data) - pyhsm.defines.YSM_AEAD_MAC_SIZE)
    nonce = pyhsm.util.input_validate_nonce(nonce, pad=True)
    mac = _cbc_mac(key, key_handle, nonce, len(data))
    counter = _ctr_counter(key_handle, nonce, value=0)
    ctr_aes = AES.new(key, AES.MODE_CTR, counter=counter.next)
    out = []
    while data:
        thisblock, data = _split_data(data, pyhsm.defines.YSM_BLOCK_SIZE)
        if decrypt:
            aes_out = ctr_aes.decrypt(thisblock)
            mac.update(aes_out)
        else:
            mac.update(thisblock)
            aes_out = ctr_aes.encrypt(thisblock)
        out.append(aes_out)
    counter.value = 0
    mac.finalize(counter.pack())
    if decrypt:
        if mac.get() != saved_mac:
            raise pyhsm.exception.YHSM_Error('AEAD integrity check failed')
    else:
        out.append(mac.get())
    return ''.join(out)

def crc16(data):
    """Calculate an ISO13239 CRC checksum of the input buffer."""
    m_crc = 65535
    for this in data:
        m_crc ^= ord(this)
        for _ in range(8):
            j = m_crc & 1
            m_crc >>= 1
            if j:
                m_crc ^= 33800
    return m_crc

def validate_yubikey_with_aead(hsm, from_key, aead, key_handle):
    """Try to validate an OTP from a YubiKey using the AEAD that can decrypt this YubiKey's
    internal secret, using the key_handle for the AEAD.

    `from_key' is the modhex encoded string emitted when you press the
    button on your YubiKey.

    Will only return on succesfull validation. All failures will result
    in an L{pyhsm.exception.YHSM_CommandFailed}.

    @param hsm: The YHSM instance
    @param from_key: The OTP from a YubiKey (in modhex)
    @param aead: AEAD containing the cryptographic key and permission flags
    @param key_handle: The key handle that can decrypt the AEAD
    @type hsm: L{pyhsm.YHSM}
    @type from_key: string
    @type aead: L{YHSM_GeneratedAEAD} or string
    @type key_handle: integer or string

    @returns: validation response
    @rtype: L{YHSM_ValidationResult}

    @see: L{pyhsm.validate_cmd.YHSM_Cmd_AEAD_Validate_OTP.parse_result}"""
    from_key = pyhsm.util.input_validate_str(from_key, 'from_key', max_len=48)
    nonce = aead.nonce
    aead = pyhsm.util.input_validate_aead(aead)
    key_handle = pyhsm.util.input_validate_key_handle(key_handle)
    public_id, otp = split_id_otp(from_key)
    public_id = modhex_decode(public_id)
    otp = modhex_decode(otp)
    if not nonce:
        nonce = public_id.decode('hex')
    return hsm.validate_aead_otp(nonce, otp.decode('hex'), key_handle, aead)

def split_id_otp(from_key):
    """Separate public id from OTP given a YubiKey OTP as input.

    @param from_key: The OTP from a YubiKey (in modhex)
    @type from_key: string

    @returns: public_id and OTP
    @rtype: tuple of string"""
    if len(from_key) > 32:
        public_id, otp = (from_key[:-32], from_key[-32:])
    elif len(from_key) == 32:
        public_id = ''
        otp = from_key
    else:
        raise pyhsm.exception.YHSM_Error('Bad from_key length %i < 32 : %s' % (len(from_key), from_key))
    return (public_id, otp)

def get_password(hsm, args):
    """Get password of correct length for this YubiHSM version."""
    expected_len = 32
    name = 'HSM password'
    if hsm.version.have_key_store_decrypt():
        expected_len = 64
        name = 'master key'
    if args.stdin:
        password = sys.stdin.readline()
        while password and password[-1] == '\n':
            password = password[:-1]
    elif args.debug:
        password = raw_input('Enter %s (press enter to skip) (will be echoed) : ' % name)
    else:
        password = getpass.getpass('Enter %s (press enter to skip) : ' % name)
    if len(password) <= expected_len:
        password = password.decode('hex')
        if not password:
            return None
        return password
    else:
        sys.stderr.write('ERROR: Invalid HSM password (expected max %i chars, got %i)\n' % (expected_len, len(password)))
        return 1

def get_otp(hsm, args):
    """Get OTP from YubiKey."""
    if args.no_otp:
        return None
    if hsm.version.have_unlock():
        if args.stdin:
            otp = sys.stdin.readline()
            while otp and otp[-1] == '\n':
                otp = otp[:-1]
        else:
            otp = raw_input('Enter admin YubiKey OTP (press enter to skip) : ')
        if len(otp) == 44:
            return otp
        if otp:
            sys.stderr.write('ERROR: Invalid YubiKey OTP\n')
    return None

def gaussian_points(loc=(0, 0), scale=(10, 10), n=100):
    """Generates and returns `n` normally distributed points centered at `loc` with `scale` x and y directionality."""
    arr = np.random.normal(loc, scale, (n, 2))
    return gpd.GeoSeries([shapely.geometry.Point(x, y) for x, y in arr])

def gaussian_polygons(points, n=10):
    """Returns an array of approximately `n` `shapely.geometry.Polygon` objects for an array of `shapely.geometry.Point`
    objects."""
    gdf = gpd.GeoDataFrame(data={'cluster_number': classify_clusters(points, n=n)}, geometry=points)
    polygons = []
    for i in range(n):
        sel_points = gdf[gdf['cluster_number'] == i].geometry
        polygons.append(shapely.geometry.MultiPoint([(p.x, p.y) for p in sel_points]).convex_hull)
    polygons = [p for p in polygons if not isinstance(p, shapely.geometry.Point) and (not isinstance(p, shapely.geometry.LineString))]
    return gpd.GeoSeries(polygons)

def gaussian_multi_polygons(points, n=10):
    """Returns an array of approximately `n` `shapely.geometry.MultiPolygon` objects for an array of
    `shapely.geometry.Point` objects."""
    polygons = gaussian_polygons(points, n * 2)
    polygon_pairs = [shapely.geometry.MultiPolygon(list(pair)) for pair in np.array_split(polygons.values, n)]
    return gpd.GeoSeries(polygon_pairs)

def uniform_random_global_network(loc=2000, scale=250, n=100):
    """Returns an array of `n` uniformally randomly distributed `shapely.geometry.Point` objects."""
    arr = np.random.normal(loc, scale, n).astype(int)
    return pd.DataFrame(data={'mock_variable': arr, 'from': uniform_random_global_points(n), 'to': uniform_random_global_points(n)})

def flatten(items):
    """Yield items from any nested iterable. Used by ``QuadTree.flatten`` to one-dimensionalize a list of sublists.
    cf. http://stackoverflow.com/questions/952914/making-a-flat-list-out-of-list-of-lists-in-python"""
    for x in items:
        if isinstance(x, Iterable):
            yield from flatten(x)
        else:
            yield x

def get_version():
    """Return tmux version.

    If tmux is built from git master, the version returned will be the latest
    version appended with -master, e.g. ``2.4-master``.

    If using OpenBSD's base system tmux, the version will have ``-openbsd``
    appended to the latest version, e.g. ``2.4-openbsd``.

    Returns
    -------
    :class:`distutils.version.LooseVersion`
        tmux version according to :func:`libtmux.common.which`'s tmux"""
    proc = tmux_cmd('-V')
    if proc.stderr:
        if proc.stderr[0] == 'tmux: unknown option -- V':
            if sys.platform.startswith('openbsd'):
                return LooseVersion('%s-openbsd' % TMUX_MAX_VERSION)
            raise exc.LibTmuxException('libtmux supports tmux %s and greater. This system is running tmux 1.3 or earlier.' % TMUX_MIN_VERSION)
        raise exc.VersionTooLow(proc.stderr)
    version = proc.stdout[0].split('tmux ')[1]
    if version == 'master':
        return LooseVersion('%s-master' % TMUX_MAX_VERSION)
    version = re.sub('[a-z-]', '', version)
    return LooseVersion(version)

def export_certificate(ctx, slot, format, certificate):
    """Export a X.509 certificate.

    Reads a certificate from one of the slots on the YubiKey.

    \x08
    SLOT        PIV slot to read certificate from.
    CERTIFICATE File to write certificate to. Use '-' to use stdout."""
    controller = ctx.obj['controller']
    try:
        cert = controller.read_certificate(slot)
    except APDUError as e:
        if e.sw == SW.NOT_FOUND:
            ctx.fail('No certificate found.')
        else:
            logger.error('Failed to read certificate from slot %s', slot, exc_info=e)
    certificate.write(cert.public_bytes(encoding=format))

def change_pin(ctx, pin, new_pin):
    """Change the PIN code.

    The PIN must be between 6 and 8 characters long, and supports any type of
    alphanumeric characters. For cross-platform compatibility,
    numeric digits are recommended."""
    controller = ctx.obj['controller']
    if not pin:
        pin = _prompt_pin(ctx, prompt='Enter your current PIN')
    if not new_pin:
        new_pin = click.prompt('Enter your new PIN', default='', hide_input=True, show_default=False, confirmation_prompt=True, err=True)
    if not _valid_pin_length(pin):
        ctx.fail('Current PIN must be between 6 and 8 characters long.')
    if not _valid_pin_length(new_pin):
        ctx.fail('New PIN must be between 6 and 8 characters long.')
    try:
        controller.change_pin(pin, new_pin)
        click.echo('New PIN set.')
    except AuthenticationBlocked as e:
        logger.debug('PIN is blocked.', exc_info=e)
        ctx.fail('PIN is blocked.')
    except WrongPin as e:
        logger.debug('Failed to change PIN, %d tries left', e.tries_left, exc_info=e)
        ctx.fail('PIN change failed - %d tries left.' % e.tries_left)

def change_puk(ctx, puk, new_puk):
    """Change the PUK code.

    If the PIN is lost or blocked it can be reset using a PUK.
    The PUK must be between 6 and 8 characters long, and supports any type of
    alphanumeric characters."""
    controller = ctx.obj['controller']
    if not puk:
        puk = _prompt_pin(ctx, prompt='Enter your current PUK')
    if not new_puk:
        new_puk = click.prompt('Enter your new PUK', default='', hide_input=True, show_default=False, confirmation_prompt=True, err=True)
    if not _valid_pin_length(puk):
        ctx.fail('Current PUK must be between 6 and 8 characters long.')
    if not _valid_pin_length(new_puk):
        ctx.fail('New PUK must be between 6 and 8 characters long.')
    try:
        controller.change_puk(puk, new_puk)
        click.echo('New PUK set.')
    except AuthenticationBlocked as e:
        logger.debug('PUK is blocked.', exc_info=e)
        ctx.fail('PUK is blocked.')
    except WrongPuk as e:
        logger.debug('Failed to change PUK, %d tries left', e.tries_left, exc_info=e)
        ctx.fail('PUK change failed - %d tries left.' % e.tries_left)

def unblock_pin(ctx, puk, new_pin):
    """Unblock the PIN.

    Reset the PIN using the PUK code."""
    controller = ctx.obj['controller']
    if not puk:
        puk = click.prompt('Enter PUK', default='', show_default=False, hide_input=True, err=True)
    if not new_pin:
        new_pin = click.prompt('Enter a new PIN', default='', show_default=False, hide_input=True, err=True)
    controller.unblock_pin(puk, new_pin)

def read_object(ctx, pin, object_id):
    """Read arbitrary PIV object.

    Read PIV object by providing the object id.

    \x08
    OBJECT-ID       Id of PIV object in HEX."""
    controller = ctx.obj['controller']
    def do_read_object(retry=True):
        try:
            click.echo(controller.get_data(object_id))
        except APDUError as e:
            if e.sw == SW.NOT_FOUND:
                ctx.fail('No data found.')
            elif e.sw == SW.SECURITY_CONDITION_NOT_SATISFIED:
                _verify_pin(ctx, controller, pin)
                do_read_object(retry=False)
            else:
                raise
    do_read_object()

def fido(ctx):
    """Manage FIDO applications.

    Examples:

    \x08
      Reset the FIDO (FIDO2 and U2F) applications:
      $ ykman fido reset

    \x08
      Change the FIDO2 PIN from 123456 to 654321:
      $ ykman fido set-pin --pin 123456 --new-pin 654321"""
    dev = ctx.obj['dev']
    if dev.is_fips:
        try:
            ctx.obj['controller'] = FipsU2fController(dev.driver)
        except Exception as e:
            logger.debug('Failed to load FipsU2fController', exc_info=e)
            ctx.fail('Failed to load FIDO Application.')
    else:
        try:
            ctx.obj['controller'] = Fido2Controller(dev.driver)
        except Exception as e:
            logger.debug('Failed to load Fido2Controller', exc_info=e)
            ctx.fail('Failed to load FIDO 2 Application.')

def info(ctx):
    """Display status of FIDO2 application."""
    controller = ctx.obj['controller']
    if controller.is_fips:
        click.echo('FIPS Approved Mode: {}'.format('Yes' if controller.is_in_fips_mode else 'No'))
    elif controller.has_pin:
        try:
            click.echo('PIN is set, with {} tries left.'.format(controller.get_pin_retries()))
        except CtapError as e:
            if e.code == CtapError.ERR.PIN_BLOCKED:
                click.echo('PIN is blocked.')
    else:
        click.echo('PIN is not set.')

def unlock(ctx, pin):
    """Verify U2F PIN for YubiKey FIPS.

    Unlock the YubiKey FIPS and allow U2F registration."""
    controller = ctx.obj['controller']
    if not controller.is_fips:
        ctx.fail('This is not a YubiKey FIPS, and therefore does not support a U2F PIN.')
    if pin is None:
        pin = _prompt_current_pin('Enter your PIN')
    _fail_if_not_valid_pin(ctx, pin, True)
    try:
        controller.verify_pin(pin)
    except ApduError as e:
        if e.code == SW.VERIFY_FAIL_NO_RETRY:
            ctx.fail('Wrong PIN.')
        if e.code == SW.AUTH_METHOD_BLOCKED:
            ctx.fail('PIN is blocked.')
        if e.code == SW.COMMAND_NOT_ALLOWED:
            ctx.fail('PIN is not set.')
        logger.error('PIN verification failed', exc_info=e)
        ctx.fail('PIN verification failed.')

def cli(ctx, device, log_level, log_file, reader):
    """Configure your YubiKey via the command line.

    Examples:

    \x08
      List connected YubiKeys, only output serial number:
      $ ykman list --serials

    \x08
      Show information about YubiKey with serial number 0123456:
      $ ykman --device 0123456 info"""
    ctx.obj = YkmanContextObject()
    if log_level:
        ykman.logging_setup.setup(log_level, log_file=log_file)
    if reader and device:
        ctx.fail("--reader and --device options can't be combined.")
    subcmd = next((c for c in COMMANDS if c.name == ctx.invoked_subcommand))
    if subcmd == list_keys:
        if reader:
            ctx.fail("--reader and list command can't be combined.")
        return
    transports = getattr(subcmd, 'transports', TRANSPORT.usb_transports())
    if transports:
        def resolve_device():
            if device is not None:
                dev = _run_cmd_for_serial(ctx, subcmd.name, transports, device)
            else:
                dev = _run_cmd_for_single(ctx, subcmd.name, transports, reader)
            ctx.call_on_close(dev.close)
            return dev
        ctx.obj.add_resolver('dev', resolve_device)

def list_keys(ctx, serials, readers):
    """List connected YubiKeys."""
    if readers:
        for reader in list_readers():
            click.echo(reader.name)
        ctx.exit()
    all_descriptors = get_descriptors()
    descriptors = [d for d in all_descriptors if d.key_type != YUBIKEY.SKY]
    skys = len(all_descriptors) - len(descriptors)
    handled_serials = set()
    for dev in list_devices():
        handled = False
        if skys > 0 and dev.key_type == YUBIKEY.SKY:
            skys -= 1
            serial = None
            handled = True
        else:
            serial = dev.serial
            if serial not in handled_serials:
                handled_serials.add(serial)
                matches = [d for d in descriptors if (d.key_type, d.mode) == (dev.driver.key_type, dev.driver.mode)]
                if len(matches) > 0:
                    d = matches[0]
                    descriptors.remove(d)
                    handled = True
        if handled:
            if serials:
                if serial:
                    click.echo(serial)
            else:
                click.echo('{} [{}]{}'.format(dev.device_name, dev.mode, ' Serial: {}'.format(serial) if serial else ''))
        dev.close()
        if not descriptors and (not skys):
            break

def swap(ctx):
    """Swaps the two slot configurations."""
    controller = ctx.obj['controller']
    click.echo('Swapping slots...')
    try:
        controller.swap_slots()
    except YkpersError as e:
        _failed_to_write_msg(ctx, e)

def ndef(ctx, slot, prefix):
    """Select slot configuration to use for NDEF.

    The default prefix will be used if no prefix is specified."""
    dev = ctx.obj['dev']
    controller = ctx.obj['controller']
    if not dev.config.nfc_supported:
        ctx.fail('NFC interface not available.')
    if not controller.slot_status[slot - 1]:
        ctx.fail('Slot {} is empty.'.format(slot))
    try:
        if prefix:
            controller.configure_ndef_slot(slot, prefix)
        else:
            controller.configure_ndef_slot(slot)
    except YkpersError as e:
        _failed_to_write_msg(ctx, e)

def delete(ctx, slot, force):
    """Deletes the configuration of a slot."""
    controller = ctx.obj['controller']
    if not force and (not controller.slot_status[slot - 1]):
        ctx.fail('Not possible to delete an empty slot.')
    force or click.confirm('Do you really want to delete the configuration of slot {}?'.format(slot), abort=True, err=True)
    click.echo('Deleting the configuration of slot {}...'.format(slot))
    try:
        controller.zap_slot(slot)
    except YkpersError as e:
        _failed_to_write_msg(ctx, e)

def static(ctx, slot, password, generate, length, keyboard_layout, no_enter, force):
    """Configure a static password.

    To avoid problems with different keyboard layouts, the following characters
    are allowed by default: cbdefghijklnrtuv

    Use the --keyboard-layout option to allow more characters based on
    preferred keyboard layout."""
    controller = ctx.obj['controller']
    keyboard_layout = KEYBOARD_LAYOUT[keyboard_layout]
    if password and len(password) > 38:
        ctx.fail('Password too long (maximum length is 38 characters).')
    if generate and (not length):
        ctx.fail('Provide a length for the generated password.')
    if not password and (not generate):
        password = click.prompt('Enter a static password', err=True)
    elif not password and generate:
        password = generate_static_pw(length, keyboard_layout)
    if not force:
        _confirm_slot_overwrite(controller, slot)
    try:
        controller.program_static(slot, password, not no_enter, keyboard_layout=keyboard_layout)
    except YkpersError as e:
        _failed_to_write_msg(ctx, e)

def chalresp(ctx, slot, key, totp, touch, force, generate):
    """Program a challenge-response credential.

    If KEY is not given, an interactive prompt will ask for it."""
    controller = ctx.obj['controller']
    if key:
        if generate:
            ctx.fail('Invalid options: --generate conflicts with KEY argument.')
        elif totp:
            key = parse_b32_key(key)
        else:
            key = parse_key(key)
    elif force and (not generate):
        ctx.fail('No secret key given. Please remove the --force flag, set the KEY argument or set the --generate flag.')
    elif totp:
        while True:
            key = click.prompt('Enter a secret key (base32)', err=True)
            try:
                key = parse_b32_key(key)
                break
            except Exception as e:
                click.echo(e)
    elif generate:
        key = os.urandom(20)
        click.echo('Using a randomly generated key: {}'.format(b2a_hex(key).decode('ascii')))
    else:
        key = click.prompt('Enter a secret key', err=True)
        key = parse_key(key)
    cred_type = 'TOTP' if totp else 'challenge-response'
    force or click.confirm('Program a {} credential in slot {}?'.format(cred_type, slot), abort=True, err=True)
    try:
        controller.program_chalresp(slot, key, touch)
    except YkpersError as e:
        _failed_to_write_msg(ctx, e)

def calculate(ctx, slot, challenge, totp, digits):
    """Perform a challenge-response operation.

    Send a challenge (in hex) to a YubiKey slot with a challenge-response
    credential, and read the response. Supports output as a OATH-TOTP code."""
    controller = ctx.obj['controller']
    if not challenge and (not totp):
        ctx.fail('No challenge provided.')
    slot1, slot2 = controller.slot_status
    if slot == 1 and (not slot1) or (slot == 2 and (not slot2)):
        ctx.fail('Cannot perform challenge-response on an empty slot.')
    if challenge and totp:
        try:
            challenge = int(challenge)
        except Exception as e:
            logger.error('Error', exc_info=e)
            ctx.fail('Timestamp challenge for TOTP must be an integer.')
    try:
        res = controller.calculate(slot, challenge, totp=totp, digits=int(digits), wait_for_touch=False)
    except YkpersError as e:
        if e.errno == 11:
            prompt_for_touch()
            try:
                res = controller.calculate(slot, challenge, totp=totp, digits=int(digits), wait_for_touch=True)
            except YkpersError as e:
                if e.errno == 4:
                    ctx.fail('The YubiKey timed out.')
                else:
                    ctx.fail(e)
        else:
            ctx.fail('Failed to calculate challenge.')
    click.echo(res)

def hotp(ctx, slot, key, digits, counter, no_enter, force):
    """Program an HMAC-SHA1 OATH-HOTP credential."""
    controller = ctx.obj['controller']
    if not key:
        while True:
            key = click.prompt('Enter a secret key (base32)', err=True)
            try:
                key = parse_b32_key(key)
                break
            except Exception as e:
                click.echo(e)
    force or click.confirm('Program a HOTP credential in slot {}?'.format(slot), abort=True, err=True)
    try:
        controller.program_hotp(slot, key, counter, int(digits) == 8, not no_enter)
    except YkpersError as e:
        _failed_to_write_msg(ctx, e)

def parse_private_key(data, password):
    """Identifies, decrypts and returns a cryptography private key object."""
    if is_pem(data):
        if b'ENCRYPTED' in data:
            if password is None:
                raise TypeError('No password provided for encrypted key.')
        try:
            return serialization.load_pem_private_key(data, password, backend=default_backend())
        except ValueError:
            raise
        except Exception:
            pass
    if is_pkcs12(data):
        try:
            p12 = crypto.load_pkcs12(data, password)
            data = crypto.dump_privatekey(crypto.FILETYPE_PEM, p12.get_privatekey())
            return serialization.load_pem_private_key(data, password=None, backend=default_backend())
        except crypto.Error as e:
            raise ValueError(e)
    try:
        return serialization.load_der_private_key(data, password, backend=default_backend())
    except Exception:
        pass
    raise ValueError('Could not parse private key.')

def parse_certificates(data, password):
    """Identifies, decrypts and returns list of cryptography x509 certificates."""
    if is_pem(data):
        certs = []
        for cert in data.split(PEM_IDENTIFIER):
            try:
                certs.append(x509.load_pem_x509_certificate(PEM_IDENTIFIER + cert, default_backend()))
            except Exception:
                pass
        if len(certs) > 0:
            return certs
    if is_pkcs12(data):
        try:
            p12 = crypto.load_pkcs12(data, password)
            data = crypto.dump_certificate(crypto.FILETYPE_PEM, p12.get_certificate())
            return [x509.load_pem_x509_certificate(data, default_backend())]
        except crypto.Error as e:
            raise ValueError(e)
    try:
        return [x509.load_der_x509_certificate(data, default_backend())]
    except Exception:
        pass
    raise ValueError('Could not parse certificate.')

def is_pkcs12(data):
    """Tries to identify a PKCS12 container.
    The PFX PDU version is assumed to be v3.
    See: https://tools.ietf.org/html/rfc7292."""
    if isinstance(data, bytes):
        tlv = Tlv(data)
        if tlv.tag == 48:
            header = Tlv(tlv.value)
            return header.tag == 2 and header.value == b'\x03'
        return False
    else:
        return False

def uri(ctx, uri, touch, force):
    """Add a new credential from URI.

    Use a URI to add a new credential to your YubiKey."""
    if not uri:
        while True:
            uri = click.prompt('Enter an OATH URI', err=True)
            try:
                uri = CredentialData.from_uri(uri)
                break
            except Exception as e:
                click.echo(e)
    ensure_validated(ctx)
    data = uri
    if data.digits == 5 and data.issuer == 'Steam':
        data.digits = 6
    data.touch = touch
    _add_cred(ctx, data, force=force)

def delete(ctx, query, force):
    """Delete a credential.

    Delete a credential from your YubiKey.
    Provide a query string to match the credential to delete."""
    ensure_validated(ctx)
    controller = ctx.obj['controller']
    creds = controller.list()
    hits = _search(creds, query)
    if len(hits) == 0:
        click.echo('No matches, nothing to be done.')
    elif len(hits) == 1:
        cred = hits[0]
        if force or click.confirm(u'Delete credential: {} ?'.format(cred.printable_key), default=False, err=True):
            controller.delete(cred)
            click.echo(u'Deleted {}.'.format(cred.printable_key))
        else:
            click.echo('Deletion aborted by user.')
    else:
        _error_multiple_hits(ctx, hits)

def bysize(words):
    """take a list of words and return a dict of sets sorted by word length
    e.g.
    ret[3]=set(['ant', 'cat', 'dog', 'pig'])
    ret[4]=set(['frog', 'goat'])
    ret[5]=set(['horse'])
    ret[8]=set(['elephant'])"""
    ret = {}
    for w in words:
        if len(w) not in ret:
            ret[len(w)] = set()
        ret[len(w)].add(w)
    return ret

def make_pl_si_lists(lst, plending, siendingsize, dojoinstem=True):
    """given a list of singular words: lst
    an ending to append to make the plural: plending
    the number of characters to remove from the singular
        before appending plending: siendingsize
    a flag whether to create a joinstem: dojoinstem

    return:
    a list of pluralised words: si_list (called si because this is what you need to
                                         look for to make the singular)
    the pluralised words as a dict of sets sorted by word length: si_bysize
    the singular words as a dict of sets sorted by word length: pl_bysize
    if dojoinstem is True: a regular expression that matches any of the stems: stem"""
    if siendingsize is not None:
        siendingsize = -siendingsize
    si_list = [w[:siendingsize] + plending for w in lst]
    pl_bysize = bysize(lst)
    si_bysize = bysize(si_list)
    if dojoinstem:
        stem = joinstem(siendingsize, lst)
        return (si_list, si_bysize, pl_bysize, stem)
    else:
        return (si_list, si_bysize, pl_bysize)

def _int(int_or_str: Any) -> int:
    """return an integer where a single character string may be expected"""
    if isinstance(int_or_str, str):
        return ord(int_or_str)
    if isinstance(int_or_str, bytes):
        return int_or_str[0]
    return int(int_or_str)

def _console(console: Any) -> Any:
    """Return a cffi console."""
    try:
        return console.console_c
    except AttributeError:
        warnings.warn('Falsy console parameters are deprecated, always use the root console instance returned by console_init_root.', DeprecationWarning, stacklevel=3)
        return ffi.NULL

def _pixel_to_tile(x: float, y: float) -> Tuple[float, float]:
    """Convert pixel coordinates to tile coordinates."""
    xy = tcod.ffi.new('double[2]', (x, y))
    tcod.lib.TCOD_sys_pixel_to_tile(xy, xy + 1)
    return (xy[0], xy[1])

def get() -> Iterator[Any]:
    """Return an iterator for all pending events.

    Events are processed as the iterator is consumed.  Breaking out of, or
    discarding the iterator will leave the remaining events on the event queue.

    Example::

        for event in tcod.event.get():
            if event.type == "QUIT":
                print(event)
                raise SystemExit()
            elif event.type == "KEYDOWN":
                print(event)
            elif event.type == "MOUSEBUTTONDOWN":
                print(event)
            elif event.type == "MOUSEMOTION":
                print(event)
            else:
                print(event)"""
    sdl_event = tcod.ffi.new('SDL_Event*')
    while tcod.lib.SDL_PollEvent(sdl_event):
        if sdl_event.type in _SDL_TO_CLASS_TABLE:
            yield _SDL_TO_CLASS_TABLE[sdl_event.type].from_sdl_event(sdl_event)
        else:
            yield Undefined.from_sdl_event(sdl_event)

def wait(timeout: Optional[float]=None) -> Iterator[Any]:
    """Block until events exist, then return an event iterator.

    `timeout` is the maximum number of seconds to wait as a floating point
    number with millisecond precision, or it can be None to wait forever.

    Returns the same iterator as a call to :any:`tcod.event.get`.

    Example::

        for event in tcod.event.wait():
            if event.type == "QUIT":
                print(event)
                raise SystemExit()
            elif event.type == "KEYDOWN":
                print(event)
            elif event.type == "MOUSEBUTTONDOWN":
                print(event)
            elif event.type == "MOUSEMOTION":
                print(event)
            else:
                print(event)"""
    if timeout is not None:
        tcod.lib.SDL_WaitEventTimeout(tcod.ffi.NULL, int(timeout * 1000))
    else:
        tcod.lib.SDL_WaitEvent(tcod.ffi.NULL)
    return get()

def deprecate(message: str, category: Any=DeprecationWarning, stacklevel: int=0) -> Callable[[F], F]:
    """Return a decorator which adds a warning to functions."""
    def decorator(func: F) -> F:
        if not __debug__:
            return func
        @functools.wraps(func)
        def wrapper(*args, **kargs):
            warnings.warn(message, category, stacklevel=stacklevel + 2)
            return func(*args, **kargs)
        return cast(F, wrapper)
    return decorator

def _format_char(char):
    """Prepares a single character for passing to ctypes calls, needs to return
    an integer but can also pass None which will keep the current character
    instead of overwriting it.

    This is called often and needs to be optimized whenever possible."""
    if char is None:
        return -1
    if isinstance(char, _STRTYPES) and len(char) == 1:
        return ord(char)
    try:
        return int(char)
    except:
        raise TypeError('char single character string, integer, or None\nReceived: ' + repr(char))

def _format_str(string):
    """Attempt fast string handing by decoding directly into an array."""
    if isinstance(string, _STRTYPES):
        if _IS_PYTHON3:
            array = _array.array('I')
            array.frombytes(string.encode(_utf32_codec))
        elif isinstance(string, unicode):
            array = _array.array(b'I')
            array.fromstring(string.encode(_utf32_codec))
        else:
            array = _array.array(b'B')
            array.fromstring(string)
        return array
    return string

def _pycall_path_old(x1: int, y1: int, x2: int, y2: int, handle: Any) -> float:
    """libtcodpy style callback, needs to preserve the old userData issue."""
