def backport(func):
    """Backport a function name into an old style for compatibility.

    The docstring is updated to reflect that the new function returned is
    deprecated and that the other function is preferred.
    A DeprecationWarning is also raised for using this function.

    If the script is run with an optimization flag then the real function
    will be returned without being wrapped."""
    if not __debug__:
        return func
    @_functools.wraps(func)
    def deprecated_function(*args, **kargs):
        _warnings.warn('This function name is deprecated', DeprecationWarning, 2)
        return func(*args, **kargs)
    deprecated_function.__doc__ = None
    return deprecated_function

def _get_fov_type(fov):
    """Return a FOV from a string"""
    oldFOV = fov
    fov = str(fov).upper()
    if fov in _FOVTYPES:
        return _FOVTYPES[fov]
    if fov[:10] == 'PERMISSIVE' and fov[10].isdigit() and (fov[10] != '9'):
        return 4 + int(fov[10])
    raise _tdl.TDLError('No such fov option as %s' % oldFOV)

def get_package_data():
    """get data files which will be included in the main tcod/ directory"""
    BITSIZE, LINKAGE = platform.architecture()
    files = ['py.typed', 'lib/LIBTCOD-CREDITS.txt', 'lib/LIBTCOD-LICENSE.txt', 'lib/README-SDL.txt']
    if 'win32' in sys.platform:
        if BITSIZE == '32bit':
            files += ['x86/SDL2.dll']
        else:
            files += ['x64/SDL2.dll']
    if sys.platform == 'darwin':
        files += ['SDL2.framework/Versions/A/SDL2']
    return files

def memory_warning(config, context):
    """Determines when memory usage is nearing it's max."""
    used = psutil.Process(os.getpid()).memory_info().rss / 1048576
    limit = float(context.memory_limit_in_mb)
    p = used / limit
    memory_threshold = config.get('memory_warning_threshold')
    if p >= memory_threshold:
        config['raven_client'].captureMessage('Memory Usage Warning', level='warning', extra={'MemoryLimitInMB': context.memory_limit_in_mb, 'MemoryUsedInMB': math.floor(used)})
    else:
        Timer(0.5, memory_warning, (config, context)).start()

def install_timers(config, context):
    """Create the timers as specified by the plugin configuration."""
    timers = []
    if config.get('capture_timeout_warnings'):
        timeout_threshold = config.get('timeout_warning_threshold')
        time_remaining = context.get_remaining_time_in_millis() / 1000
        timers.append(Timer(time_remaining * timeout_threshold, timeout_warning, (config, context)))
        timers.append(Timer(max(time_remaining - 0.5, 0), timeout_error, [config]))
    if config.get('capture_memory_warnings'):
        timers.append(Timer(0.5, memory_warning, (config, context)))
    for t in timers:
        t.start()
    return timers

def topic_pages_inline_list(topic):
    """This will render an inline pagination for the posts related to the given topic.

    Usage::

        {% topic_pages_inline_list my_topic %}"""
    data_dict = {'topic': topic}
    pages_number = (topic.posts_count - 1) // machina_settings.TOPIC_POSTS_NUMBER_PER_PAGE + 1
    if pages_number > 5:
        data_dict['first_pages'] = range(1, 5)
        data_dict['last_page'] = pages_number
    elif pages_number > 1:
        data_dict['first_pages'] = range(1, pages_number + 1)
    return data_dict

def get_classes(module_label, classnames):
    """Imports a set of classes from a given module.

    Usage::

        get_classes('forum.models', ['Forum', 'ForumReadTrack', ])"""
    app_label = module_label.split('.')[0]
    app_module_path = _get_app_module_path(module_label)
    if not app_module_path:
        raise AppNotFoundError("No app found matching '{}'".format(module_label))
    module_path = app_module_path
    if '.' in app_module_path:
        base_package = app_module_path.rsplit('.' + app_label, 1)[0]
        module_path = '{}.{}'.format(base_package, module_label)
    local_imported_module = _import_module(module_path, classnames)
    machina_imported_module = None
    if not app_module_path.startswith('machina.apps'):
        machina_imported_module = _import_module('{}.{}'.format('machina.apps', module_label), classnames)
    if local_imported_module is None and machina_imported_module is None:
        raise AppNotFoundError("Error importing '{}'".format(module_path))
    imported_modules = [m for m in (local_imported_module, machina_imported_module) if m is not None]
    return _pick_up_classes(imported_modules, classnames)

def _import_module(module_path, classnames):
    """Tries to import the given Python module path."""
    try:
        imported_module = __import__(module_path, fromlist=classnames)
        return imported_module
    except ImportError:
        __, __, exc_traceback = sys.exc_info()
        frames = traceback.extract_tb(exc_traceback)
        if len(frames) > 1:
            raise

def _pick_up_classes(modules, classnames):
    """Given a list of class names to retrieve, try to fetch them from the specified list of
    modules and returns the list of the fetched classes."""
    klasses = []
    for classname in classnames:
        klass = None
        for module in modules:
            if hasattr(module, classname):
                klass = getattr(module, classname)
                break
        if not klass:
            raise ClassNotFoundError("Error fetching '{}' in {}".format(classname, str([module.__name__ for module in modules])))
        klasses.append(klass)
    return klasses

def _get_app_module_path(module_label):
    """Given a module label, loop over the apps specified in the INSTALLED_APPS to find the
    corresponding application module path."""
    app_name = module_label.rsplit('.', 1)[0]
    for app in settings.INSTALLED_APPS:
        if app.endswith('.' + app_name) or app == app_name:
            return app
    return None

def assign_perm(perm, user_or_group, forum=None, has_perm=True):
    """Assigns a permission to a user (anonymous or not) or a group."""
    user, group = get_identity(user_or_group)
    perm = ForumPermission.objects.get(codename=perm)
    if user:
        return UserForumPermission.objects.create(forum=forum, permission=perm, user=user if not user.is_anonymous else None, anonymous_user=user.is_anonymous, has_perm=has_perm)
    if group:
        return GroupForumPermission.objects.create(forum=forum, permission=perm, group=group, has_perm=has_perm)

def remove_perm(perm, user_or_group, forum=None):
    """Remove a permission to a user (anonymous or not) or a group."""
    user, group = get_identity(user_or_group)
    perm = ForumPermission.objects.get(codename=perm)
    if user:
        UserForumPermission.objects.filter(forum=forum, permission=perm, user=user if not user.is_anonymous else None, anonymous_user=user.is_anonymous).delete()
    if group:
        GroupForumPermission.objects.filter(forum=forum, permission=perm, group=group).delete()

def get_identity(identity):
    """Returns a (user_obj, None) tuple or a (None, group_obj) tuple depending on the considered
    instance."""
    if isinstance(identity, AnonymousUser):
        return (identity, None)
    if isinstance(identity, get_user_model()):
        return (identity, None)
    elif isinstance(identity, Group):
        return (None, identity)
    else:
        raise NotUserNorGroup('User/AnonymousUser or Group instance is required (got {})'.format(identity))

