def get_model(app_label, model_name):
    """Given an app label and a model name, returns the corresponding model class."""
    try:
        return apps.get_model(app_label, model_name)
    except AppRegistryNotReady:
        if apps.apps_ready and (not apps.models_ready):
            app_config = apps.get_app_config(app_label)
            import_module('%s.%s' % (app_config.name, MODELS_MODULE_NAME))
            return apps.get_registered_model(app_label, model_name)
        else:
            raise

def is_model_registered(app_label, model_name):
    """Checks whether the given model is registered or not.

    It is usefull to prevent Machina models for being registered if they are overridden by local
    apps."""
    try:
        apps.get_registered_model(app_label, model_name)
    except LookupError:
        return False
    else:
        return True

def model_factory(abstract_class):
    """Given an abstract class, constructs the model that inherits from this class only if a model
    with the same (app label, model name) was not already in the app registry."""
    app_label = abstract_class.Meta.app_label
    model_name = abstract_class.__name__.replace('Abstract', '')
    if not is_model_registered(app_label, model_name):
        return type(str(model_name), (abstract_class,), {'__module__': __name__})

def has_been_completed_by(poll, user):
    """This will return a boolean indicating if the passed user has already voted in the given
        poll.

    Usage::
        {% if poll|has_been_completed_by:user %}...{% endif %}"""
    user_votes = TopicPollVote.objects.filter(poll_option__poll=poll)
    if user.is_anonymous:
        forum_key = get_anonymous_user_forum_key(user)
        user_votes = user_votes.filter(anonymous_key=forum_key) if forum_key else user_votes.none()
    else:
        user_votes = user_votes.filter(voter=user)
    return user_votes.exists()

def increase_posts_count(sender, instance, **kwargs):
    """Increases the member's post count after a post save.

    This receiver handles the update of the profile related to the user who is the poster of the
    forum post being created or updated."""
    if instance.poster is None:
        return
    profile, dummy = ForumProfile.objects.get_or_create(user=instance.poster)
    increase_posts_count = False
    if instance.pk:
        try:
            old_instance = instance.__class__._default_manager.get(pk=instance.pk)
        except ObjectDoesNotExist:
            increase_posts_count = True
            old_instance = None
        if old_instance and old_instance.approved is False and (instance.approved is True):
            increase_posts_count = True
    elif instance.approved:
        increase_posts_count = True
    if increase_posts_count:
        profile.posts_count = F('posts_count') + 1
        profile.save()

def decrease_posts_count_after_post_unaproval(sender, instance, **kwargs):
    """Decreases the member's post count after a post unaproval.

    This receiver handles the unaproval of a forum post: the posts count associated with the post's
    author is decreased."""
    if not instance.pk:
        return
    profile, dummy = ForumProfile.objects.get_or_create(user=instance.poster)
    try:
        old_instance = instance.__class__._default_manager.get(pk=instance.pk)
    except ObjectDoesNotExist:
        return
    if old_instance and old_instance.approved is True and (instance.approved is False):
        profile.posts_count = F('posts_count') - 1
        profile.save()

def decrease_posts_count_after_post_deletion(sender, instance, **kwargs):
    """Decreases the member's post count after a post deletion.

    This receiver handles the deletion of a forum post: the posts count related to the post's
    author is decreased."""
    if not instance.approved:
        return
    try:
        assert instance.poster_id is not None
        poster = User.objects.get(pk=instance.poster_id)
    except AssertionError:
        return
    except ObjectDoesNotExist:
        return
    profile, dummy = ForumProfile.objects.get_or_create(user=poster)
    if profile.posts_count:
        profile.posts_count = F('posts_count') - 1
        profile.save()

def update_topic_counter(sender, topic, user, request, response, **kwargs):
