def as_fstring(text):
    """expansion with python f-string, usually ok, but with the case
    of ' inside expressions, adding repr will add backslash to it
    and cause trouble."""
    for quote in ('"""', "'''"):
        if quote not in text and (not text.endswith(quote[0])):
            return 'fr' + quote + text + quote
    pieces = split_fstring(text)
    if not any(("'" in piece for piece in pieces[1::2])):
        return 'f' + repr(text)
    args = []
    for idx in range(len(pieces))[1::2]:
        pos = valid_expr_till(pieces[idx])
        if pos == 0:
            raise SyntaxError(f'invalid expression in {pieces[idx]}')
        args.append(pieces[idx][:pos])
        pieces[idx] = '{' + str(idx // 2) + pieces[idx][pos:] + '}'
    return repr(''.join(pieces)) + '.format(' + ', '.join(args) + ')'

def dict_merge(dct, merge_dct):
    """Recursive dict merge. Inspired by :meth:``dict.update()``, instead of
    updating only top-level keys, dict_merge recurses down into dicts nested
    to an arbitrary depth, updating keys. The ``merge_dct`` is merged into
    ``dct``.
    :param dct: dict onto which the merge is executed
    :param merge_dct: dct merged into dct
    :return: None"""
    for k, v in merge_dct.items():
        if k in dct and isinstance(dct[k], dict) and isinstance(v, dict):
            dict_merge(dct[k], v)
        else:
            dct[k] = v

def tail_of_file(filename, n, ansi2html=False):
    """Reads a n lines from f with an offset of offset lines."""
    avg_line_length = 74
    to_read = n
    with open(filename) as f:
        while 1:
            try:
                f.seek(-(avg_line_length * to_read), 2)
            except IOError:
                f.seek(0)
            pos = f.tell()
            lines = f.read().splitlines()
            if len(lines) >= to_read or pos == 0:
                if ansi2html:
                    return convertAnsi2html('\n'.join(lines[-to_read:]))
                return '\n'.join(lines[-to_read:]) + '\n'
            avg_line_length *= 1.3

def sample_lines(lines, n):
    """Draw a sample of n lines from filename, largely evenly."""
    if len(lines) <= n:
        return ''.join(lines)
    else:
        m = len(lines)
        return ''.join([lines[x * m // n + m // (2 * n)] for x in range(n)])

def is_type_hint(stmt: str) -> bool:
    """Try to differentiate

    var: type = value

    with

    action: input = whatever"""
    if stmt.count('=') > 1:
        return False
    if ':' not in stmt:
        return False
    if not stmt.split(':')[1].strip():
        return False
    if '=' not in stmt:
        action, par = [x.strip() for x in stmt.split(':', 1)]
    else:
        action, par = [x.strip() for x in stmt.split('=', 1)[0].split(':', 1)]
    if action in SOS_DIRECTIVES:
        return False
    if par in SOS_ACTION_OPTIONS:
        return False
    if not par.isidentifier():
        return True
    if action in dir(builtins):
        return False
    global _action_list
    if _action_list is None:
        import pkg_resources
        _action_list = [x.name for x in pkg_resources.iter_entry_points(group='sos_actions')]
    if action in _action_list:
        return False
    if par in dir(typing) or par in dir(builtins):
        return True
    env.logger.debug(f"Failed to tell if '{stmt}' is an assignment with type hint or function in script format. Assuming type hint.")
    return True

def glob_wildcards(pattern: str, files: Optional[List[str]]=None) -> Dict[str, Union[List[Any], List[str]]]:
    """Glob the values of the wildcards by matching the given pattern to the filesystem.
    Returns a named tuple with a list of values for each wildcard."""
    pattern = os.path.normpath(pattern)
    if sys.platform == 'win32':
        pattern = pattern.replace('\\', '/')
    first_wildcard = re.search('{[^{]', pattern)
    dirname = os.path.dirname(pattern[:first_wildcard.start()]) if first_wildcard else os.path.dirname(pattern)
    if not dirname:
        dirname = '.'
    names = [match.group('name') for match in SOS_WILDCARD.finditer(pattern)]
    res = {x: [] for x in names}
    pattern = re.compile(regex(pattern))
    if files is None:
        files = (os.path.join(dirpath, f) if dirpath != '.' else f for dirpath, dirnames, filenames in os.walk(dirname) for f in chain(filenames, dirnames))
    for f in files:
        match = re.match(pattern, str(f).replace('\\', '/'))
        if match:
            for name, value in match.groupdict().items():
                res[name].append(value)
    return res

def extract_pattern(pattern: str, ifiles: List[str]) -> Dict[str, any]:
    """This function match pattern to a list of input files, extract and return
    pieces of filenames as a list of variables with keys defined by pattern."""
    res = glob_wildcards(pattern, [])
    for ifile in ifiles:
        matched = glob_wildcards(pattern, [ifile])
        for key in matched.keys():
            if not matched[key]:
                res[key].append(None)
            else:
                res[key].extend(matched[key])
    return res

def expand_pattern(pattern: str) -> List[str]:
    """This function expand patterns against the current namespace
    and return a list of filenames"""
    ofiles = []
    sz = None
    res = glob_wildcards(pattern, [])
    sz = None
    wildcard = [{}]
    for key in res.keys():
        if key not in env.sos_dict:
            raise ValueError(f'Undefined variable {key} in pattern {pattern}')
        if not isinstance(env.sos_dict[key], str) and isinstance(env.sos_dict[key], collections.Sequence):
            if sz is None:
                sz = len(env.sos_dict[key])
                wildcard = [copy.deepcopy(wildcard[0]) for x in range(sz)]
            elif sz != len(env.sos_dict[key]):
                raise ValueError(f'Variables in output pattern should have the same length (other={sz}, len({key})={len(env.sos_dict[key])})')
            for idx, value in enumerate(env.sos_dict[key]):
                wildcard[idx][key] = value
        else:
            for v in wildcard:
                v[key] = env.sos_dict[key]
    for card in wildcard:
        ofiles.append(apply_wildcards(pattern, card, fill_missing=False, fail_dynamic=False, dynamic_fill=None, keep_dynamic=False))
    return ofiles

def interpolate(text, global_dict=None, local_dict=None):
    """Evaluate expressions in `text`"""
    try:
        return eval(as_fstring(text), global_dict, local_dict)
    except Exception as e:
        raise ValueError(f'Failed to interpolate {text}: {e}')

def get_accessed(node):
    """Get names, but ignore variables names to the left hand side
    That is to say, in case of
       a = b + 1
    we consider b as "being accessed", while a is not."""
    if isinstance(node, ast.Assign):
        return get_accessed(node.value)
    elif isinstance(node, ast.Name):
        return {node.id}
    names = set()
    if isinstance(node, list):
        for x in node:
            names |= get_accessed(x)
    else:
        for x in ast.iter_child_nodes(node):
            names |= get_accessed(x)
    return names

def accessed_vars(statement: str, mode: str='exec') -> Set[str]:
    """Parse a Python statement and analyze the symbols used. The result
    will be used to determine what variables a step depends upon."""
    try:
        if mode == 'exec':
            return get_accessed(ast.parse(statement, '<string>', 'exec'))
        else:
            res = get_accessed(ast.parse('__NULL__(' + statement + ')', '<string>', 'eval'))
            res.remove('__NULL__')
            return res
    except:
        raise RuntimeError(f'Failed to parse statement: {statement} in {mode} mode')

def get_used_in_func(node):
    """Get names, but ignore variables names to the left hand side
    That is to say, in case of
       a = b + 1
    we consider b as "being accessed", while a is not."""
    if isinstance(node, ast.FunctionDef):
        return {node.name: get_accessed(node.body)}
    names = {}
    for node in ast.iter_child_nodes(node):
        names.update(get_used_in_func(node))
    return names

def used_in_func(statement: str, filename: str='<string>', mode: str='exec'):
    """Parse a Python statement and analyze the symbols used. The result
    will be used to determine what variables a step depends upon."""
    try:
        return get_used_in_func(ast.parse(statement, filename, mode))
    except Exception as e:
        raise RuntimeError(f'Failed to parse statement: {statement} {e}')

def SoS_eval(expr: str, extra_dict: dict={}) -> Any:
    """Evaluate an expression with sos dict."""
    return eval(expr, env.sos_dict.dict(), extra_dict)

def SoS_exec(script: str, _dict: dict=None, return_result: bool=True) -> None:
    """Execute a statement."""
    if _dict is None:
        _dict = env.sos_dict.dict()
    if not return_result:
        exec(compile(script, filename=stmtHash.hash(script), mode='exec'), _dict)
        return None
    try:
        stmts = list(ast.iter_child_nodes(ast.parse(script)))
        if not stmts:
            return
        if isinstance(stmts[-1], ast.Expr):
            if len(stmts) > 1:
                exec(compile(ast.Module(body=stmts[:-1]), filename=stmtHash.hash(script), mode='exec'), _dict)
            res = eval(compile(ast.Expression(body=stmts[-1].value), filename=stmtHash.hash(script), mode='eval'), _dict)
        else:
            exec(compile(script, filename=stmtHash.hash(script), mode='exec'), _dict)
            res = None
    except SyntaxError as e:
        raise SyntaxError(f'Invalid code {script}: {e}')
    return res

def expand_depends_files(*args, **kwargs):
    """handle directive depends"""
    args = [x.resolve() if isinstance(x, dynamic) else x for x in args]
    kwargs = {x: y.resolve() if isinstance(y, dynamic) else y for x, y in kwargs.items()}
    return sos_targets(*args, **kwargs, _verify_existence=True, _undetermined=False, _source=env.sos_dict['step_name'])

def expand_output_files(value, *args, **kwargs):
    """Process output files (perhaps a pattern) to determine input files.
    """
    if any((isinstance(x, dynamic) for x in args)) or any((isinstance(y, dynamic) for y in kwargs.values())):
        return sos_targets(_undetermined=value)
    else:
        return sos_targets(*args, **kwargs, _undetermined=False, _source=env.sos_dict['step_name'])

def script(script, interpreter='', suffix='', args='', **kwargs):
    """Execute specified script using specified interpreter. This action accepts common
    action arguments such as input, active, workdir, docker_image and args. In particular,
    content of one or more files specified by option input would be prepended before
    the specified script."""
    return SoS_ExecuteScript(script, interpreter, suffix, args).run(**kwargs)

def stop_if(expr, msg='', no_output=False):
    """Abort the execution of the current step or loop and yield
    an warning message `msg` if `expr` is False"""
    if expr:
        raise StopInputGroup(msg=msg, keep_output=not no_output)
    return 0

def run(script, args='', **kwargs):
    """Execute specified script using bash. This action accepts common action arguments such as
    input, active, workdir, docker_image and args. In particular, content of one or more files
    specified by option input would be prepended before the specified script."""
    if sys.platform == 'win32':
        interpreter = ''
    elif not script.startswith('#!'):
        interpreter = '/bin/bash'
        if not args:
            args = '-ev {filename:q}'
    else:
        interpreter = ''
    return SoS_ExecuteScript(script, interpreter, '', args).run(**kwargs)

def get_changed_vars(section: SoS_Step):
    """changed vars are variables that are "shared" and therefore "provides"
    to others"""
    if 'shared' not in section.options:
        return set()
    changed_vars = set()
    svars = section.options['shared']
    if isinstance(svars, str):
        changed_vars.add(svars)
        svars = {svars: svars}
    elif isinstance(svars, Sequence):
        for item in svars:
            if isinstance(item, str):
                changed_vars.add(item)
            elif isinstance(item, Mapping):
                changed_vars |= set(item.keys())
            else:
                raise ValueError(f'Option shared should be a string, a mapping of expression, or list of string or mappings. {svars} provided')
    elif isinstance(svars, Mapping):
        changed_vars |= set(svars.keys())
    else:
        raise ValueError(f'Option shared should be a string, a mapping of expression, or list of string or mappings. {svars} provided')
    return changed_vars

def get_signature_vars(section):
    """Get signature variables which are variables that will be
    saved with step signatures"""
    signature_vars = set(section.parameters.keys() & accessed_vars(strip_param_defs(section.global_stmts)))
    input_idx = find_statement(section, 'input')
    after_input_idx = 0 if input_idx is None else input_idx + 1
    for statement in section.statements[after_input_idx:]:
        if statement[0] == '=':
            signature_vars |= accessed_vars('='.join(statement[1:3]))
        elif statement[0] == '!':
            signature_vars |= accessed_vars(statement[1])
    if section.task:
        signature_vars |= accessed_vars(section.task)
    return {x for x in signature_vars if not x.startswith('__')}

def get_sos_step_steps(stmt):
    """Extract sos_step(x) from statement"""
    opt_values = get_param_of_function('sos_step', stmt, extra_dict=env.sos_dict.dict())
    for value in opt_values:
        if len(value) != 1:
            raise ValueError('sos_step only accept one and only one parameter')
    return [x[0] for x in opt_values]

def get_output_from_steps(stmt, last_step):
    """Extract output_from(1), output_from('step_1'), and output_from([1, 2])
    to determine dependent steps"""
    opt_values = get_param_of_function('output_from', stmt, extra_dict=env.sos_dict.dict())
    def step_name(val):
        if isinstance(val, str):
            return val
        elif isinstance(val, int):
            if val == -1:
                if last_step is None:
                    return None
                return last_step
            if '_' in env.sos_dict['step_name']:
                return f"{env.sos_dict['step_name'].rsplit('_', 1)[0]}_{val}"
            else:
                return str(val)
        else:
            raise ValueError(f'Invalid value {val} for output_from() function')
    res = []
    for value in opt_values:
        if len(value) == 1:
            value = value[0]
        elif value[0] == 'steps':
            value = value[1]
        elif value[0] in SOS_TARGETS_OPTIONS:
            continue
        else:
            raise ValueError(f'Unacceptable keyword argument {value[0]} for function output_from')
        if isinstance(value, (int, str)):
            res.append(step_name(value))
        elif isinstance(value, Sequence):
            res.extend([step_name(x) for x in value])
        else:
            raise ValueError(f'Invalid value for input option from {value}')
    return [x for x in res if x is not None]

def extract_workflow(notebook):
    """Extract workflow from a notebook file or notebook JSON instance"""
    if isinstance(notebook, str):
        nb = nbformat.read(notebook, nbformat.NO_CONVERT)
    else:
        nb = notebook
    cells = nb.cells
    content = '#!/usr/bin/env sos-runner\n#fileformat=SOS1.0\n\n'
    for cell in cells:
        if cell.cell_type != 'code':
            continue
        if 'kernel' in cell.metadata and cell.metadata['kernel'] not in ('sos', 'SoS', None):
            continue
        lines = cell.source.split('\n')
        valid_cell = False
        for idx, line in enumerate(lines):
            if valid_cell or (line.startswith('%include') or line.startswith('%from')):
                content += line + '\n'
            elif SOS_SECTION_HEADER.match(line):
                valid_cell = True
                c = idx - 1
                comment = ''
                while c >= 0 and lines[c].startswith('#'):
                    comment = lines[c] + '\n' + comment
                    c -= 1
                content += comment + line + '\n'
        if valid_cell:
            content += '\n'
    return content

def vim_ipython_is_open():
