def rename(**kwargs):
    """Rename one or more columns, leaving other columns unchanged

    Example usage:
      diamonds >> rename(new_name=old_name)"""
    def rename_columns(df):
        column_assignments = {old_name_later._name: new_name for new_name, old_name_later in kwargs.items()}
        return df.rename(columns=column_assignments)
    return rename_columns

def get_join_cols(by_entry):
    """helper function used for joins
    builds left and right join list for join function"""
    left_cols = []
    right_cols = []
    for col in by_entry:
        if isinstance(col, str):
            left_cols.append(col)
            right_cols.append(col)
        else:
            left_cols.append(col[0])
            right_cols.append(col[1])
    return (left_cols, right_cols)

def mutating_join(*args, **kwargs):
    """generic function for mutating dplyr-style joins
    """
    left = args[0]
    right = args[1]
    if 'by' in kwargs:
        left_cols, right_cols = get_join_cols(kwargs['by'])
    else:
        left_cols, right_cols = (None, None)
    if 'suffixes' in kwargs:
        dsuffixes = kwargs['suffixes']
    else:
        dsuffixes = ('_x', '_y')
    if left._grouped_on:
        outDf = DplyFrame((left >> ungroup()).merge(right, how=kwargs['how'], left_on=left_cols, right_on=right_cols, suffixes=dsuffixes)).regroup(left._grouped_on)
    else:
        outDf = DplyFrame(left.merge(right, how=kwargs['how'], left_on=left_cols, right_on=right_cols, suffixes=dsuffixes))
    return outDf

def js():
