def collate_fonts_data(fonts_data):
    """Collate individual fonts data into a single glyph data list."""
    glyphs = {}
    for family in fonts_data:
        for glyph in family:
            if glyph['unicode'] not in glyphs:
                glyphs[glyph['unicode']] = glyph
            else:
                c = glyphs[glyph['unicode']]['contours']
                glyphs[glyph['unicode']]['contours'] = c | glyph['contours']
    return glyphs.values()

def com_adobe_fonts_check_family_consistent_upm(ttFonts):
    """Fonts have consistent Units Per Em?"""
    upm_set = set()
    for ttFont in ttFonts:
        upm_set.add(ttFont['head'].unitsPerEm)
    if len(upm_set) > 1:
        yield (FAIL, 'Fonts have different units per em: {}.'.format(sorted(upm_set)))
    else:
        yield (PASS, 'Fonts have consistent units per em.')

def _quick_and_dirty_glyph_is_empty(font, glyph_name):
    """This is meant to be a quick-and-dirty test to see if a glyph is empty.
    Ideally we'd use the glyph_has_ink() method for this, but for a family of
    large CJK CFF fonts with tens of thousands of glyphs each, it's too slow.

    Caveat Utilitor:
    If this method returns True, the glyph is definitely empty.
    If this method returns False, the glyph *might* still be empty."""
    if 'glyf' in font:
        glyph = font['glyf'][glyph_name]
        if not glyph.isComposite():
            if glyph.numberOfContours == 0:
                return True
        return False
    elif 'CFF2' in font:
        top_dict = font['CFF2'].cff.topDictIndex[0]
    else:
        top_dict = font['CFF '].cff.topDictIndex[0]
    char_strings = top_dict.CharStrings
    char_string = char_strings[glyph_name]
    if len(char_string.bytecode) <= 1:
        return True
    return False

def com_adobe_fonts_check_find_empty_letters(ttFont):
    """Letters in font have glyphs that are not empty?"""
    cmap = ttFont.getBestCmap()
    passed = True
    letter_categories = {'Ll', 'Lm', 'Lo', 'Lt', 'Lu'}
    invisible_letters = {4447, 4448, 12644, 65440}
    for unicode_val, glyph_name in cmap.items():
        category = unicodedata.category(chr(unicode_val))
        if _quick_and_dirty_glyph_is_empty(ttFont, glyph_name) and category in letter_categories and (unicode_val not in invisible_letters):
            yield (FAIL, "U+%04X should be visible, but its glyph ('%s') is empty." % (unicode_val, glyph_name))
            passed = False
    if passed:
        yield (PASS, 'No empty glyphs for letters found.')

def com_adobe_fonts_check_name_empty_records(ttFont):
    """Check name table for empty records."""
    failed = False
    for name_record in ttFont['name'].names:
        name_string = name_record.toUnicode().strip()
        if len(name_string) == 0:
            failed = True
            name_key = tuple([name_record.platformID, name_record.platEncID, name_record.langID, name_record.nameID])
            yield (FAIL, "'name' table record with key={} is empty and should be removed.".format(name_key))
    if not failed:
        yield (PASS, 'No empty name table records found.')

def com_google_fonts_check_name_no_copyright_on_description(ttFont):
    """Description strings in the name table must not contain copyright info."""
    failed = False
    for name in ttFont['name'].names:
        if 'opyright' in name.string.decode(name.getEncoding()) and name.nameID == NameID.DESCRIPTION:
            failed = True
    if failed:
        yield (FAIL, 'Namerecords with ID={} (NameID.DESCRIPTION) should be removed (perhaps these were added by a longstanding FontLab Studio 5.x bug that copied copyright notices to them.)'.format(NameID.DESCRIPTION))
    else:
        yield (PASS, 'Description strings in the name table do not contain any copyright string.')

def com_google_fonts_check_name_line_breaks(ttFont):
    """Name table entries should not contain line-breaks."""
    failed = False
    for name in ttFont['name'].names:
        string = name.string.decode(name.getEncoding())
        if '\n' in string:
            failed = True
            yield (FAIL, 'Name entry {} on platform {} contains a line-break.'.format(NameID(name.nameID).name, PlatformID(name.platformID).name))
    if not failed:
        yield (PASS, 'Name table entries are all single-line (no line-breaks found).')

def com_google_fonts_check_name_match_familyname_fullfont(ttFont):
    """Does full font name begin with the font family name?"""
    from fontbakery.utils import get_name_entry_strings
    familyname = get_name_entry_strings(ttFont, NameID.FONT_FAMILY_NAME)
    fullfontname = get_name_entry_strings(ttFont, NameID.FULL_FONT_NAME)
    if len(familyname) == 0:
        yield (FAIL, Message('no-font-family-name', "Font lacks a NameID.FONT_FAMILY_NAME entry in the 'name' table."))
    elif len(fullfontname) == 0:
        yield (FAIL, Message('no-full-font-name', "Font lacks a NameID.FULL_FONT_NAME entry in the 'name' table."))
    else:
        fullfontname = fullfontname[0]
        familyname = familyname[0]
        if not fullfontname.startswith(familyname):
            yield (FAIL, Message('does-not', " On the 'name' table, the full font name (NameID {} - FULL_FONT_NAME: '{}') does not begin with font family name (NameID {} - FONT_FAMILY_NAME: '{}')".format(NameID.FULL_FONT_NAME, familyname, NameID.FONT_FAMILY_NAME, fullfontname)))
        else:
            yield (PASS, 'Full font name begins with the font family name.')

def com_google_fonts_check_name_rfn(ttFont):
    """Name table strings must not contain the string 'Reserved Font Name'."""
    failed = False
    for entry in ttFont['name'].names:
        string = entry.toUnicode()
        if 'reserved font name' in string.lower():
            yield (WARN, 'Name table entry ("{}") contains "Reserved Font Name". This is an error except in a few specific rare cases.'.format(string))
            failed = True
    if not failed:
        yield (PASS, 'None of the name table strings contain "Reserved Font Name".')

def com_adobe_fonts_check_name_postscript_vs_cff(ttFont):
    """CFF table FontName must match name table ID 6 (PostScript name)."""
    failed = False
    cff_names = ttFont['CFF '].cff.fontNames
    if len(cff_names) != 1:
        yield (ERROR, 'Unexpected number of font names in CFF table.')
        return
    cff_name = cff_names[0]
    for entry in ttFont['name'].names:
        if entry.nameID == NameID.POSTSCRIPT_NAME:
            postscript_name = entry.toUnicode()
            if postscript_name != cff_name:
                yield (FAIL, "Name table PostScript name '{}' does not match CFF table FontName '{}'.".format(postscript_name, cff_name))
                failed = True
    if not failed:
        yield (PASS, 'Name table PostScript name matches CFF table FontName.')

def com_adobe_fonts_check_name_postscript_name_consistency(ttFont):
    """Name table ID 6 (PostScript name) must be consistent across platforms."""
    postscript_names = set()
    for entry in ttFont['name'].names:
        if entry.nameID == NameID.POSTSCRIPT_NAME:
            postscript_name = entry.toUnicode()
            postscript_names.add(postscript_name)
    if len(postscript_names) > 1:
        yield (FAIL, "Entries in the 'name' table for ID 6 (PostScript name) are not consistent. Names found: {}.".format(sorted(postscript_names)))
    else:
        yield (PASS, "Entries in the 'name' table for ID 6 (PostScript name) are consistent.")

def com_google_fonts_check_family_equal_unicode_encodings(ttFonts):
    """Fonts have equal unicode encodings?"""
    encoding = None
    failed = False
    for ttFont in ttFonts:
        cmap = None
        for table in ttFont['cmap'].tables:
            if table.format == 4:
                cmap = table
                break
        if not encoding:
            encoding = cmap.platEncID
        if encoding != cmap.platEncID:
            failed = True
    if failed:
        yield (FAIL, 'Fonts have different unicode encodings.')
    else:
        yield (PASS, 'Fonts have equal unicode encodings.')

def com_google_fonts_check_all_glyphs_have_codepoints(ttFont):
    """Check all glyphs have codepoints assigned."""
    failed = False
    for subtable in ttFont['cmap'].tables:
        if subtable.isUnicode():
            for item in subtable.cmap.items():
                codepoint = item[0]
                if codepoint is None:
                    failed = True
                    yield (FAIL, 'Glyph {} lacks a unicode codepoint assignment'.format(codepoint))
    if not failed:
        yield (PASS, 'All glyphs have a codepoint value assigned.')

def com_google_fonts_check_name_trailing_spaces(ttFont):
    """Name table records must not have trailing spaces."""
    failed = False
    for name_record in ttFont['name'].names:
        name_string = name_record.toUnicode()
        if name_string != name_string.strip():
            failed = True
            name_key = tuple([name_record.platformID, name_record.platEncID, name_record.langID, name_record.nameID])
            shortened_str = name_record.toUnicode()
            if len(shortened_str) > 20:
                shortened_str = shortened_str[:10] + '[...]' + shortened_str[-10:]
            yield (FAIL, f"Name table record with key = {name_key} has trailing spaces that must be removed: '{shortened_str}'")
    if not failed:
        yield (PASS, 'No trailing spaces on name table entries.')

def com_google_fonts_check_family_single_directory(fonts):
    """Checking all files are in the same directory.

    If the set of font files passed in the command line is not all in the
    same directory, then we warn the user since the tool will interpret
    the set of files as belonging to a single family (and it is unlikely
    that the user would store the files from a single family spreaded in
    several separate directories)."""
    directories = []
    for target_file in fonts:
        directory = os.path.dirname(target_file)
        if directory not in directories:
            directories.append(directory)
    if len(directories) == 1:
        yield (PASS, 'All files are in the same directory.')
    else:
        yield (FAIL, 'Not all fonts passed in the command line are in the same directory. This may lead to bad results as the tool will interpret all font files as belonging to a single font family. The detected directories are: {}'.format(directories))

def com_google_fonts_check_ftxvalidator(font):
    """Checking with ftxvalidator."""
    import plistlib
    try:
        import subprocess
        ftx_cmd = ['ftxvalidator', '-t', 'all', font]
        ftx_output = subprocess.check_output(ftx_cmd, stderr=subprocess.STDOUT)
        ftx_data = plistlib.loads(ftx_output)
        if 'kATSFontTestSeverityFatalError' not in ftx_data['kATSFontTestResultKey']:
            yield (PASS, 'ftxvalidator passed this file')
        else:
            ftx_cmd = ['ftxvalidator', '-T', '-r', '-t', 'all', font]
            ftx_output = subprocess.check_output(ftx_cmd, stderr=subprocess.STDOUT)
            yield (FAIL, f'ftxvalidator output follows:\n\n{ftx_output}\n')
    except subprocess.CalledProcessError as e:
        yield (ERROR, 'ftxvalidator returned an error code. Output follows:\n\n{}\n'.format(e.output.decode('utf-8')))
    except OSError:
        yield (ERROR, 'ftxvalidator is not available!')

def com_google_fonts_check_ots(font):
    """Checking with ots-sanitize."""
    import ots
    try:
        process = ots.sanitize(font, check=True, capture_output=True)
    except ots.CalledProcessError as e:
        yield (FAIL, 'ots-sanitize returned an error code ({}). Output follows:\n\n{}{}'.format(e.returncode, e.stderr.decode(), e.stdout.decode()))
    else:
        if process.stderr:
            yield (WARN, 'ots-sanitize passed this file, however warnings were printed:\n\n{}'.format(process.stderr.decode()))
        else:
            yield (PASS, 'ots-sanitize passed this file')

def com_google_fonts_check_fontbakery_version():
    """Do we have the latest version of FontBakery installed?"""
    try:
        import subprocess
        installed_str = None
        latest_str = None
        is_latest = False
        failed = False
        pip_cmd = ['pip', 'search', 'fontbakery']
        pip_output = subprocess.check_output(pip_cmd, stderr=subprocess.STDOUT)
        for line in pip_output.decode().split('\n'):
            if 'INSTALLED' in line:
                installed_str = line.split('INSTALLED')[1].strip()
            if 'LATEST' in line:
                latest_str = line.split('LATEST')[1].strip()
            if '(latest)' in line:
                is_latest = True
        if not (is_latest or is_up_to_date(installed_str, latest_str)):
            failed = True
            yield (FAIL, f"Current Font Bakery version is {installed_str}, while a newer {latest_str} is already available. Please upgrade it with 'pip install -U fontbakery'")
        yield (INFO, pip_output.decode())
    except subprocess.CalledProcessError as e:
        yield (ERROR, "Running 'pip search fontbakery' returned an error code. Output follows :\n\n{}\n".format(e.output.decode()))
    if not failed:
        yield (PASS, 'Font Bakery is up-to-date')

def com_google_fonts_check_fontforge_stderr(font, fontforge_check_results):
    """FontForge validation outputs error messages?"""
    if 'skip' in fontforge_check_results:
        yield (SKIP, fontforge_check_results['skip'])
        return
    filtered_err_msgs = ''
    for line in fontforge_check_results['ff_err_messages'].split('\n'):
        if 'The following table(s) in the font have been ignored by FontForge' in line:
            continue
        if "Ignoring 'DSIG' digital signature table" in line:
            continue
        filtered_err_msgs += line + '\n'
    if len(filtered_err_msgs.strip()) > 0:
        yield (WARN, 'FontForge seems to dislike certain aspects of this font file. The actual meaning of the log messages below is not always clear and may require further investigation.\n\n{}'.format(filtered_err_msgs))
    else:
        yield (PASS, 'FontForge validation did not output any error message.')

def com_google_fonts_check_whitespace_glyphnames(ttFont):
    """Font has **proper** whitespace glyph names?"""
    from fontbakery.utils import get_glyph_name
    def getGlyphEncodings(font, names):
        result = set()
        for subtable in font['cmap'].tables:
            if subtable.isUnicode():
                for codepoint, name in subtable.cmap.items():
                    if name in names:
                        result.add(codepoint)
        return result
    if ttFont['post'].formatType == 3.0:
        yield (SKIP, 'Font has version 3 post table.')
    else:
        failed = False
        space_enc = getGlyphEncodings(ttFont, ['uni0020', 'space'])
        nbsp_enc = getGlyphEncodings(ttFont, ['uni00A0', 'nonbreakingspace', 'nbspace', 'nbsp'])
        space = get_glyph_name(ttFont, 32)
        if 32 not in space_enc:
            failed = True
            yield (FAIL, Message('bad20', 'Glyph 0x0020 is called "{}": Change to "space" or "uni0020"'.format(space)))
        nbsp = get_glyph_name(ttFont, 160)
        if 160 not in nbsp_enc:
            if 160 in space_enc:
                pass
            else:
                failed = True
                yield (FAIL, Message('badA0', 'Glyph 0x00A0 is called "{}": Change to "nbsp" or "uni00A0"'.format(nbsp)))
        if failed is False:
            yield (PASS, 'Font has **proper** whitespace glyph names.')

def com_google_fonts_check_whitespace_ink(ttFont):
    """Whitespace glyphs have ink?"""
    from fontbakery.utils import get_glyph_name, glyph_has_ink
    WHITESPACE_CHARACTERS = [9, 10, 11, 12, 13, 32, 133, 160, 5760, 8192, 8193, 8194, 8195, 8196, 8197, 8198, 8199, 8200, 8201, 8202, 8232, 8233, 8239, 8287, 12288, 6158, 8203, 8288, 65279]
    failed = False
    for codepoint in WHITESPACE_CHARACTERS:
        g = get_glyph_name(ttFont, codepoint)
        if g is not None and glyph_has_ink(ttFont, g):
            failed = True
            yield (FAIL, 'Glyph "{}" has ink. It needs to be replaced by an empty glyph.'.format(g))
    if not failed:
        yield (PASS, 'There is no whitespace glyph with ink.')

def com_google_fonts_check_required_tables(ttFont):
    """Font contains all required tables?"""
    from .shared_conditions import is_variable_font
    REQUIRED_TABLES = {'cmap', 'head', 'hhea', 'hmtx', 'maxp', 'name', 'OS/2', 'post'}
    OPTIONAL_TABLES = {'cvt ', 'fpgm', 'loca', 'prep', 'VORG', 'EBDT', 'EBLC', 'EBSC', 'BASE', 'GPOS', 'GSUB', 'JSTF', 'DSIG', 'gasp', 'hdmx', 'LTSH', 'PCLT', 'VDMX', 'vhea', 'vmtx', 'kern'}
    optional_tables = [opt for opt in OPTIONAL_TABLES if opt in ttFont.keys()]
    if optional_tables:
        yield (INFO, 'This font contains the following optional tables [{}]'.format(', '.join(optional_tables)))
    if is_variable_font(ttFont):
        REQUIRED_TABLES.add('STAT')
    missing_tables = [req for req in REQUIRED_TABLES if req not in ttFont.keys()]
    if 'glyf' not in ttFont.keys() and 'CFF ' not in ttFont.keys():
        missing_tables.append("CFF ' or 'glyf")
    if missing_tables:
        yield (FAIL, "This font is missing the following required tables: ['{}']".format("', '".join(missing_tables)))
    else:
        yield (PASS, 'Font contains all required tables.')

def com_google_fonts_check_unwanted_tables(ttFont):
    """Are there unwanted tables?"""
    UNWANTED_TABLES = {'FFTM': '(from FontForge)', 'TTFA': '(from TTFAutohint)', 'TSI0': '(from VTT)', 'TSI1': '(from VTT)', 'TSI2': '(from VTT)', 'TSI3': '(from VTT)', 'TSI5': '(from VTT)', 'prop': ''}
    unwanted_tables_found = []
    for table in ttFont.keys():
        if table in UNWANTED_TABLES.keys():
            info = UNWANTED_TABLES[table]
            unwanted_tables_found.append(f'{table} {info}')
    if len(unwanted_tables_found) > 0:
        yield (FAIL, 'Unwanted tables were found in the font and should be removed, either by fonttools/ttx or by editing them using the tool they are from: {}'.format(', '.join(unwanted_tables_found)))
    else:
        yield (PASS, 'There are no unwanted tables.')

def com_google_fonts_check_valid_glyphnames(ttFont):
    """Glyph names are all valid?"""
    if ttFont.sfntVersion == b'\x00\x01\x00\x00' and ttFont.get('post') and (ttFont['post'].formatType == 3.0):
        yield (SKIP, 'TrueType fonts with a format 3.0 post table contain no glyph names.')
    else:
        import re
        bad_names = []
        for _, glyphName in enumerate(ttFont.getGlyphOrder()):
            if glyphName in ['.null', '.notdef', '.ttfautohint']:
                continue
            if not re.match('^(?![.0-9])[a-zA-Z._0-9]{1,31}$', glyphName):
                bad_names.append(glyphName)
        if len(bad_names) == 0:
            yield (PASS, 'Glyph names are all valid.')
        else:
            from fontbakery.utils import pretty_print_list
            yield (FAIL, 'The following glyph names do not comply with naming conventions: {}\n\n A glyph name may be up to 31 characters in length, must be entirely comprised of characters from the following set: A-Z a-z 0-9 .(period) _(underscore). and must not start with a digit or period. There are a few exceptions such as the special character ".notdef". The glyph names "twocents", "a1", and "_" are all valid, while "2cents" and ".twocents" are not.'.format(pretty_print_list(bad_names)))

def com_google_fonts_check_unique_glyphnames(ttFont):
    """Font contains unique glyph names?"""
    if ttFont.sfntVersion == b'\x00\x01\x00\x00' and ttFont.get('post') and (ttFont['post'].formatType == 3.0):
        yield (SKIP, 'TrueType fonts with a format 3.0 post table contain no glyph names.')
    else:
        import re
        glyphs = []
        duplicated_glyphIDs = []
        for _, g in enumerate(ttFont.getGlyphOrder()):
            glyphID = re.sub('#\\w+', '', g)
            if glyphID in glyphs:
                duplicated_glyphIDs.append(glyphID)
            else:
                glyphs.append(glyphID)
        if len(duplicated_glyphIDs) == 0:
            yield (PASS, 'Font contains unique glyph names.')
        else:
            yield (FAIL, 'The following glyph names occur twice: {}'.format(duplicated_glyphIDs))

def com_google_fonts_check_glyphnames_max_length(ttFont):
    """Check that glyph names do not exceed max length."""
    if ttFont.sfntVersion == b'\x00\x01\x00\x00' and ttFont.get('post') and (ttFont['post'].formatType == 3.0):
        yield (PASS, 'TrueType fonts with a format 3.0 post table contain no glyph names.')
    else:
        failed = False
        for name in ttFont.getGlyphOrder():
            if len(name) > 109:
                failed = True
                yield (FAIL, "Glyph name is too long: '{}'".format(name))
        if not failed:
            yield (PASS, 'No glyph names exceed max allowed length.')

def com_google_fonts_check_family_vertical_metrics(ttFonts):
    """Each font in a family must have the same vertical metrics values."""
    failed = []
    vmetrics = {'sTypoAscender': {}, 'sTypoDescender': {}, 'sTypoLineGap': {}, 'usWinAscent': {}, 'usWinDescent': {}, 'ascent': {}, 'descent': {}}
    for ttfont in ttFonts:
        full_font_name = ttfont['name'].getName(4, 3, 1, 1033).toUnicode()
        vmetrics['sTypoAscender'][full_font_name] = ttfont['OS/2'].sTypoAscender
        vmetrics['sTypoDescender'][full_font_name] = ttfont['OS/2'].sTypoDescender
        vmetrics['sTypoLineGap'][full_font_name] = ttfont['OS/2'].sTypoLineGap
        vmetrics['usWinAscent'][full_font_name] = ttfont['OS/2'].usWinAscent
        vmetrics['usWinDescent'][full_font_name] = ttfont['OS/2'].usWinDescent
        vmetrics['ascent'][full_font_name] = ttfont['hhea'].ascent
        vmetrics['descent'][full_font_name] = ttfont['hhea'].descent
    for k, v in vmetrics.items():
        metric_vals = set(vmetrics[k].values())
        if len(metric_vals) != 1:
            failed.append(k)
    if failed:
        for k in failed:
            s = ['{}: {}'.format(k, v) for k, v in vmetrics[k].items()]
            yield (FAIL, '{} is not the same across the family:\n:{}'.format(k, '\n'.join(s)))
    else:
        yield (PASS, 'Vertical metrics are the same across the family')

def com_google_fonts_check_linegaps(ttFont):
    """Checking Vertical Metric Linegaps."""
    if ttFont['hhea'].lineGap != 0:
        yield (WARN, Message('hhea', 'hhea lineGap is not equal to 0.'))
    elif ttFont['OS/2'].sTypoLineGap != 0:
        yield (WARN, Message('OS/2', 'OS/2 sTypoLineGap is not equal to 0.'))
    else:
        yield (PASS, 'OS/2 sTypoLineGap and hhea lineGap are both 0.')

def com_google_fonts_check_maxadvancewidth(ttFont):
    """MaxAdvanceWidth is consistent with values in the Hmtx and Hhea tables?"""
    hhea_advance_width_max = ttFont['hhea'].advanceWidthMax
    hmtx_advance_width_max = None
    for g in ttFont['hmtx'].metrics.values():
        if hmtx_advance_width_max is None:
            hmtx_advance_width_max = max(0, g[0])
        else:
            hmtx_advance_width_max = max(g[0], hmtx_advance_width_max)
    if hmtx_advance_width_max != hhea_advance_width_max:
        yield (FAIL, 'AdvanceWidthMax mismatch: expected {} (from hmtx); got {} (from hhea)'.format(hmtx_advance_width_max, hhea_advance_width_max))
    else:
        yield (PASS, 'MaxAdvanceWidth is consistent with values in the Hmtx and Hhea tables.')

def vtt_talk_sources(ttFont) -> List[str]:
    """Return the tags of VTT source tables found in a font."""
    VTT_SOURCE_TABLES = {'TSI0', 'TSI1', 'TSI2', 'TSI3', 'TSI5'}
    tables_found = [tag for tag in ttFont.keys() if tag in VTT_SOURCE_TABLES]
    return tables_found

def com_google_fonts_check_family_equal_font_versions(ttFonts):
    """Make sure all font files have the same version value."""
    all_detected_versions = []
    fontfile_versions = {}
    for ttFont in ttFonts:
        v = ttFont['head'].fontRevision
        fontfile_versions[ttFont] = v
        if v not in all_detected_versions:
            all_detected_versions.append(v)
    if len(all_detected_versions) != 1:
        versions_list = ''
        for v in fontfile_versions.keys():
            versions_list += '* {}: {}\n'.format(v.reader.file.name, fontfile_versions[v])
        yield (WARN, 'version info differs among font files of the same font project.\nThese were the version values found:\n{}'.format(versions_list))
    else:
        yield (PASS, 'All font files have the same version.')

def com_google_fonts_check_unitsperem(ttFont):
    """Checking unitsPerEm value is reasonable."""
    upem = ttFont['head'].unitsPerEm
    target_upem = [2 ** i for i in range(4, 15)]
    target_upem.append(1000)
    target_upem.append(2000)
    if upem < 16 or upem > 16384:
        yield (FAIL, "The value of unitsPerEm at the head table must be a value between 16 and 16384. Got '{}' instead.".format(upem))
    elif upem not in target_upem:
        yield (WARN, 'In order to optimize performance on some legacy renderers, the value of unitsPerEm at the head table should idealy be a power of between 16 to 16384. And values of 1000 and 2000 are also common and may be just fine as well. But we got upm={} instead.'.format(upem))
    else:
        yield (PASS, "unitsPerEm value ({}) on the 'head' table is reasonable.".format(upem))

def com_google_fonts_check_font_version(ttFont):
    """Checking font version fields (head and name table)."""
    from decimal import Decimal
    head_version_str = str(Decimal(ttFont['head'].fontRevision).quantize(Decimal('1.000')))
    head_version = parse_version_string(head_version_str)
    name_id_5_records = [record for record in ttFont['name'].names if record.nameID == NameID.VERSION_STRING]
    failed = False
    if name_id_5_records:
        for record in name_id_5_records:
            try:
                name_version = parse_version_string(record.toUnicode())
                if name_version != head_version:
                    failed = True
                    yield (FAIL, Message('mismatch', "head version is '{}' while name version string (for platform {}, encoding {}) is '{}'.".format(head_version_str, record.platformID, record.platEncID, record.toUnicode())))
            except ValueError:
                failed = True
                yield (FAIL, Message('parse', "name version string for platform {}, encoding {} ('{}'), could not be parsed.".format(record.platformID, record.platEncID, record.toUnicode())))
    else:
        failed = True
        yield (FAIL, Message('missing', 'There is no name ID 5 (version string) in the font.'))
    if not failed:
        yield (PASS, 'All font version fields match.')

def cached_getter(func):
    """Decorate a property by executing it at instatiation time and cache the
    result on the instance object."""
    @wraps(func)
    def wrapper(self):
        attribute = f'_{func.__name__}'
        value = getattr(self, attribute, None)
        if value is None:
            value = func(self)
            setattr(self, attribute, value)
        return value
    return wrapper

def condition(*args, **kwds):
    """Check wrapper, a factory for FontBakeryCondition

    Requires all arguments of FontBakeryCondition but not `func`
    which is passed via the decorator syntax."""
    if len(args) == 1 and len(kwds) == 0 and callable(args[0]):
        func = args[0]
        return wraps(func)(FontBakeryCondition(func))
    else:
        def wrapper(func):
            return wraps(func)(FontBakeryCondition(func, *args, **kwds))
    return wrapper

def com_adobe_fonts_check_cff_call_depth(ttFont):
    """Is the CFF subr/gsubr call depth > 10?"""
    any_failures = False
    cff = ttFont['CFF '].cff
    for top_dict in cff.topDictIndex:
        if hasattr(top_dict, 'FDArray'):
            for fd_index, font_dict in enumerate(top_dict.FDArray):
                if hasattr(font_dict, 'Private'):
                    private_dict = font_dict.Private
                else:
                    private_dict = None
                failed = (yield from _check_call_depth(top_dict, private_dict, fd_index))
                any_failures = any_failures or failed
        else:
            if hasattr(top_dict, 'Private'):
                private_dict = top_dict.Private
            else:
                private_dict = None
            failed = (yield from _check_call_depth(top_dict, private_dict))
            any_failures = any_failures or failed
    if not any_failures:
        yield (PASS, 'Maximum call depth not exceeded.')

def com_adobe_fonts_check_cff2_call_depth(ttFont):
    """Is the CFF2 subr/gsubr call depth > 10?"""
    any_failures = False
    cff = ttFont['CFF2'].cff
    for top_dict in cff.topDictIndex:
        for fd_index, font_dict in enumerate(top_dict.FDArray):
            if hasattr(font_dict, 'Private'):
                private_dict = font_dict.Private
            else:
                private_dict = None
            failed = (yield from _check_call_depth(top_dict, private_dict, fd_index))
            any_failures = any_failures or failed
    if not any_failures:
        yield (PASS, 'Maximum call depth not exceeded.')

def get_bounding_box(font):
    """Returns max and min bbox of given truetype font"""
    ymin = 0
    ymax = 0
    if font.sfntVersion == 'OTTO':
        ymin = font['head'].yMin
        ymax = font['head'].yMax
    else:
        for g in font['glyf'].glyphs:
            char = font['glyf'][g]
            if hasattr(char, 'yMin') and ymin > char.yMin:
                ymin = char.yMin
            if hasattr(char, 'yMax') and ymax < char.yMax:
                ymax = char.yMax
    return (ymin, ymax)

def glyph_contour_count(font, name):
    """Contour count for specified glyph.
    This implementation will also return contour count for
    composite glyphs."""
    contour_count = 0
    items = [font['glyf'][name]]
    while items:
        g = items.pop(0)
        if g.isComposite():
            for comp in g.components:
                if comp.glyphName != '.ttfautohint':
                    items.append(font['glyf'][comp.glyphName])
        if g.numberOfContours != -1:
            contour_count += g.numberOfContours
    return contour_count

def get_font_glyph_data(font):
    """Return information for each glyph in a font"""
    from fontbakery.constants import PlatformID, WindowsEncodingID
    font_data = []
    try:
        subtable = font['cmap'].getcmap(PlatformID.WINDOWS, WindowsEncodingID.UNICODE_BMP)
        if not subtable:
            subtable = font['cmap'].tables[0]
        cmap = subtable.cmap
    except:
        return None
    cmap_reversed = dict(zip(cmap.values(), cmap.keys()))
    for glyph_name in font.getGlyphSet().keys():
        if glyph_name in cmap_reversed:
            uni_glyph = cmap_reversed[glyph_name]
            contours = glyph_contour_count(font, glyph_name)
            font_data.append({'unicode': uni_glyph, 'name': glyph_name, 'contours': {contours}})
    return font_data

def assert_results_contain(check_results, expected_status, expected_msgcode=None):
    """This helper function is useful when we want to make sure that
    a certain log message is emited by a check but it can be in any
    order among other log messages."""
    found = False
    for status, message in check_results:
        if status == expected_status and message.code == expected_msgcode:
            found = True
            break
    assert found

def com_google_fonts_check_family_underline_thickness(ttFonts):
    """Fonts have consistent underline thickness?"""
    underTs = {}
    underlineThickness = None
    failed = False
    for ttfont in ttFonts:
        fontname = ttfont.reader.file.name
        ut = ttfont['post'].underlineThickness
        underTs[fontname] = ut
        if underlineThickness is None:
            underlineThickness = ut
        if ut != underlineThickness:
            failed = True
    if failed:
        msg = "Thickness of the underline is not the same accross this family. In order to fix this, please make sure that the underlineThickness value is the same in the 'post' table of all of this family font files.\nDetected underlineThickness values are:\n"
        for style in underTs.keys():
            msg += '\t{}: {}\n'.format(style, underTs[style])
        yield (FAIL, msg)
    else:
        yield (PASS, 'Fonts have consistent underline thickness.')

def com_google_fonts_check_post_table_version(ttFont, is_ttf):
    """Font has correct post table version (2 for TTF, 3 for OTF)?"""
    formatType = ttFont['post'].formatType
    if is_ttf:
        expected = 2
    else:
        expected = 3
    if formatType != expected:
        yield (FAIL, 'Post table should be version {} instead of {}. More info at https://github.com/google/fonts/issues/215'.format(expected, formatType))
    else:
        yield (PASS, f'Font has post table version {expected}.')

def has_kerning_info(ttFont):
    """A font has kerning info if it has a GPOS table containing at least one
    Pair Adjustment lookup (eigther directly or through an extension
    subtable)."""
    if 'GPOS' not in ttFont:
        return False
    if not ttFont['GPOS'].table.LookupList:
        return False
    for lookup in ttFont['GPOS'].table.LookupList.Lookup:
        if lookup.LookupType == 2:
            return True
        elif lookup.LookupType == 9:
            for ext in lookup.SubTable:
                if ext.ExtensionLookupType == 2:
                    return True

def style(font):
    """Determine font style from canonical filename."""
    from fontbakery.constants import STATIC_STYLE_NAMES
    filename = os.path.basename(font)
    if '-' in filename:
        stylename = os.path.splitext(filename)[0].split('-')[1]
        if stylename in [name.replace(' ', '') for name in STATIC_STYLE_NAMES]:
            return stylename
    return None

def family_directory(fonts):
    """Get the path of font project directory."""
    if fonts:
        dirname = os.path.dirname(fonts[0])
        if dirname == '':
            dirname = '.'
        return dirname

def descfile(family_directory):
    """Get the path of the DESCRIPTION file of a given font project."""
    if family_directory:
        descfilepath = os.path.join(family_directory, 'DESCRIPTION.en_us.html')
        if os.path.exists(descfilepath):
            return descfilepath

def com_google_fonts_check_description_broken_links(description):
    """Does DESCRIPTION file contain broken links?"""
    from lxml.html import HTMLParser
    import defusedxml.lxml
    import requests
    doc = defusedxml.lxml.fromstring(description, parser=HTMLParser())
    broken_links = []
    for link in doc.xpath('//a/@href'):
        if link.startswith('mailto:') and '@' in link and ('.' in link.split('@')[1]):
            yield (INFO, f'Found an email address: {link}')
            continue
        try:
            response = requests.head(link, allow_redirects=True, timeout=10)
            code = response.status_code
            if code != requests.codes.ok:
                broken_links.append("url: '{}' status code: '{}'".format(link, code))
        except requests.exceptions.Timeout:
            yield (WARN, "Timedout while attempting to access: '{}'. Please verify if that's a broken link.".format(link))
        except requests.exceptions.RequestException:
            broken_links.append(link)
    if len(broken_links) > 0:
        yield (FAIL, "The following links are broken in the DESCRIPTION file: '{}'".format("', '".join(broken_links)))
    else:
        yield (PASS, 'All links in the DESCRIPTION file look good!')

def com_google_fonts_check_metadata_parses(family_directory):
    """Check METADATA.pb parse correctly."""
    from google.protobuf import text_format
    from fontbakery.utils import get_FamilyProto_Message
    try:
        pb_file = os.path.join(family_directory, 'METADATA.pb')
        get_FamilyProto_Message(pb_file)
        yield (PASS, 'METADATA.pb parsed successfuly.')
    except text_format.ParseError as e:
        yield (FAIL, f'Family metadata at {family_directory} failed to parse.\nTRACEBACK:\n{e}')
    except FileNotFoundError:
        yield (SKIP, f"Font family at '{family_directory}' lacks a METADATA.pb file.")

def com_google_fonts_check_family_equal_glyph_names(ttFonts):
    """Fonts have equal glyph names?"""
    fonts = list(ttFonts)
    all_glyphnames = set()
    for ttFont in fonts:
        all_glyphnames |= set(ttFont['glyf'].glyphs.keys())
    missing = {}
    available = {}
    for glyphname in all_glyphnames:
        missing[glyphname] = []
        available[glyphname] = []
    failed = False
    for ttFont in fonts:
        fontname = ttFont.reader.file.name
        these_ones = set(ttFont['glyf'].glyphs.keys())
        for glyphname in all_glyphnames:
            if glyphname not in these_ones:
                failed = True
                missing[glyphname].append(fontname)
            else:
                available[glyphname].append(fontname)
    for gn in missing.keys():
        if missing[gn]:
            available_styles = [style(k) for k in available[gn]]
            missing_styles = [style(k) for k in missing[gn]]
            if None not in available_styles + missing_styles:
                avail = ', '.join(available_styles)
                miss = ', '.join(missing_styles)
            else:
                avail = ', '.join(available[gn])
                miss = ', '.join(missing[gn])
            yield (FAIL, f"Glyphname '{gn}' is defined on {avail} but is missing on {miss}.")
    if not failed:
        yield (PASS, 'All font files have identical glyph names.')

def com_google_fonts_check_vendor_id(ttFont, registered_vendor_ids):
    """Checking OS/2 achVendID."""
    SUGGEST_MICROSOFT_VENDORLIST_WEBSITE = ' You should set it to your own 4 character code, and register that code with Microsoft at https://www.microsoft.com/typography/links/vendorlist.aspx'
    vid = ttFont['OS/2'].achVendID
    bad_vids = ['UKWN', 'ukwn', 'PfEd']
    if vid is None:
        yield (WARN, Message('not set', 'OS/2 VendorID is not set.' + SUGGEST_MICROSOFT_VENDORLIST_WEBSITE))
    elif vid in bad_vids:
        yield (WARN, Message('bad', "OS/2 VendorID is '{}', a font editor default.".format(vid) + SUGGEST_MICROSOFT_VENDORLIST_WEBSITE))
    elif vid not in registered_vendor_ids.keys():
        yield (WARN, Message('unknown', "OS/2 VendorID value '{}' is not a known registered id.".format(vid) + SUGGEST_MICROSOFT_VENDORLIST_WEBSITE))
    else:
        yield (PASS, f"OS/2 VendorID '{vid}' looks good!")

def com_google_fonts_check_usweightclass(font, ttFont, style):
    """Checking OS/2 usWeightClass."""
    from fontbakery.profiles.shared_conditions import is_ttf
    weight_name, expected_value = expected_os2_weight(style)
    value = ttFont['OS/2'].usWeightClass
    if value != expected_value:
        if is_ttf(ttFont) and (weight_name == 'Thin' and value == 100) or (weight_name == 'ExtraLight' and value == 200):
            yield (WARN, '{}:{} is OK on TTFs, but OTF files with those values will cause bluring on Windows. GlyphsApp users must set a Instance Custom Parameter for the Thin and ExtraLight styles to 250 and 275, so that if OTFs are exported then it will not blur on Windows.')
        else:
            yield (FAIL, "OS/2 usWeightClass expected value for '{}' is {} but this font has {}.".format(weight_name, expected_value, value))
    else:
        yield (PASS, 'OS/2 usWeightClass value looks good!')

def licenses(family_directory):
    """Get a list of paths for every license
    file found in a font project."""
    found = []
    search_paths = [family_directory]
    gitroot = git_rootdir(family_directory)
    if gitroot and gitroot not in search_paths:
        search_paths.append(gitroot)
    for directory in search_paths:
        if directory:
            for license in ['OFL.txt', 'LICENSE.txt']:
                license_path = os.path.join(directory, license)
                if os.path.exists(license_path):
                    found.append(license_path)
    return found

def com_google_fonts_check_family_has_license(licenses):
    """Check font has a license."""
    if len(licenses) > 1:
        yield (FAIL, Message('multiple', 'More than a single license file found. Please review.'))
    elif not licenses:
        yield (FAIL, Message('no-license', 'No license file was found. Please add an OFL.txt or a LICENSE.txt file. If you are running fontbakery on a Google Fonts upstream repo, which is fine, just make sure there is a temporary license file in the same folder.'))
    else:
        yield (PASS, "Found license at '{}'".format(licenses[0]))

def com_google_fonts_check_name_license(ttFont, license):
    """Check copyright namerecords match license file."""
    from fontbakery.constants import PLACEHOLDER_LICENSING_TEXT
    failed = False
    placeholder = PLACEHOLDER_LICENSING_TEXT[license]
    entry_found = False
    for i, nameRecord in enumerate(ttFont['name'].names):
        if nameRecord.nameID == NameID.LICENSE_DESCRIPTION:
            entry_found = True
            value = nameRecord.toUnicode()
            if value != placeholder:
                failed = True
                yield (FAIL, Message('wrong', 'License file {} exists but NameID {} (LICENSE DESCRIPTION) value on platform {} ({}) is not specified for that. Value was: "{}" Must be changed to "{}"'.format(license, NameID.LICENSE_DESCRIPTION, nameRecord.platformID, PlatformID(nameRecord.platformID).name, value, placeholder)))
    if not entry_found:
        yield (FAIL, Message('missing', 'Font lacks NameID {} (LICENSE DESCRIPTION). A proper licensing entry must be set.'.format(NameID.LICENSE_DESCRIPTION)))
    elif not failed:
        yield (PASS, 'Licensing entry on name table is correctly set.')

def com_google_fonts_check_name_description_max_length(ttFont):
    """Description strings in the name table must not exceed 200 characters."""
    failed = False
    for name in ttFont['name'].names:
        if name.nameID == NameID.DESCRIPTION and len(name.string.decode(name.getEncoding())) > 200:
            failed = True
            break
    if failed:
        yield (WARN, "A few name table entries with ID={} (NameID.DESCRIPTION) are longer than 200 characters. Please check whether those entries are copyright notices mistakenly stored in the description string entries by a bug in an old FontLab version. If that's the case, then such copyright notices must be removed from these entries.".format(NameID.DESCRIPTION))
    else:
        yield (PASS, 'All description name records have reasonably small lengths.')

def com_google_fonts_check_name_version_format(ttFont):
    """Version format is correct in 'name' table?"""
    from fontbakery.utils import get_name_entry_strings
    import re
    def is_valid_version_format(value):
        return re.match('Version\\s0*[1-9]+\\.\\d+', value)
    failed = False
    version_entries = get_name_entry_strings(ttFont, NameID.VERSION_STRING)
    if len(version_entries) == 0:
        failed = True
        yield (FAIL, Message('no-version-string', 'Font lacks a NameID.VERSION_STRING (nameID={}) entry'.format(NameID.VERSION_STRING)))
    for ventry in version_entries:
        if not is_valid_version_format(ventry):
            failed = True
            yield (FAIL, Message('bad-version-strings', 'The NameID.VERSION_STRING (nameID={}) value must follow the pattern "Version X.Y" with X.Y between 1.000 and 9.999. Current version string is: "{}"'.format(NameID.VERSION_STRING, ventry)))
    if not failed:
        yield (PASS, 'Version format in NAME table entries is correct.')

def com_google_fonts_check_has_ttfautohint_params(ttFont):
    """Font has ttfautohint params?"""
    from fontbakery.utils import get_name_entry_strings
    def ttfautohint_version(value):
        import re
        results = re.search('ttfautohint \\(v(.*)\\) ([^;]*)', value)
        if results:
            return (results.group(1), results.group(2))
    version_strings = get_name_entry_strings(ttFont, NameID.VERSION_STRING)
    failed = True
    for vstring in version_strings:
        values = ttfautohint_version(vstring)
        if values:
            ttfa_version, params = values
            if params:
                yield (PASS, f'Font has ttfautohint params ({params})')
                failed = False
        else:
            yield (SKIP, 'Font appears to our heuristic as not hinted using ttfautohint.')
            failed = False
    if failed:
        yield (FAIL, 'Font is lacking ttfautohint params on its version strings on the name table.')

def com_google_fonts_check_name_familyname_first_char(ttFont):
    """Make sure family name does not begin with a digit.

    Font family names which start with a numeral are often not
    discoverable in Windows applications."""
    from fontbakery.utils import get_name_entry_strings
    failed = False
    for familyname in get_name_entry_strings(ttFont, NameID.FONT_FAMILY_NAME):
        digits = map(str, range(0, 10))
        if familyname[0] in digits:
            yield (FAIL, "Font family name '{}' begins with a digit!".format(familyname))
            failed = True
    if failed is False:
        yield (PASS, 'Font family name first character is not a digit.')

def com_google_fonts_check_currency_chars(ttFont):
    """Font has all expected currency sign characters?"""
    def font_has_char(ttFont, codepoint):
        for subtable in ttFont['cmap'].tables:
            if codepoint in subtable.cmap:
                return True
        return False
    failed = False
    OPTIONAL = {}
    MANDATORY = {8364: 'EURO SIGN'}
    for codepoint, charname in OPTIONAL.items():
        if not font_has_char(ttFont, codepoint):
            failed = True
            yield (WARN, f'Font lacks "{charname}" character (unicode: 0x{codepoint:04X})')
    for codepoint, charname in MANDATORY.items():
        if not font_has_char(ttFont, codepoint):
            failed = True
            yield (FAIL, f'Font lacks "{charname}" character (unicode: 0x{codepoint:04X})')
    if not failed:
        yield (PASS, 'Font has all expected currency sign characters.')

def com_google_fonts_check_name_ascii_only_entries(ttFont):
    """Are there non-ASCII characters in ASCII-only NAME table entries?"""
    bad_entries = []
    for name in ttFont['name'].names:
        if name.nameID == NameID.COPYRIGHT_NOTICE or name.nameID == NameID.POSTSCRIPT_NAME:
            string = name.string.decode(name.getEncoding())
            try:
                string.encode('ascii')
            except:
                bad_entries.append(name)
                yield (INFO, "Bad string at [nameID {}, '{}']: '{}'".format(name.nameID, name.getEncoding(), string.encode('ascii', errors='xmlcharrefreplace')))
    if len(bad_entries) > 0:
        yield (FAIL, 'There are {} strings containing non-ASCII characters in the ASCII-only NAME table entries.'.format(len(bad_entries)))
    else:
        yield (PASS, 'None of the ASCII-only NAME table entries contain non-ASCII characteres.')

def com_google_fonts_check_metadata_profiles_csv(family_metadata):
    """METADATA.pb: Designer exists in Google Fonts profiles.csv?"""
    PROFILES_GIT_URL = 'https://github.com/google/fonts/blob/master/designers/profiles.csv'
    PROFILES_RAW_URL = 'https://raw.githubusercontent.com/google/fonts/master/designers/profiles.csv'
    if family_metadata.designer == '':
        yield (FAIL, 'METADATA.pb field "designer" MUST NOT be empty!')
    elif family_metadata.designer == 'Multiple Designers':
        yield (SKIP, 'Found "Multiple Designers" at METADATA.pb, which is OK, so we won\'t look for it at profiles.csv')
    else:
        from urllib import request
        import csv
        try:
            handle = request.urlopen(PROFILES_RAW_URL)
            designers = []
            for row in csv.reader(handle):
                if not row:
                    continue
                designers.append(row[0].decode('utf-8'))
            if family_metadata.designer not in designers:
                yield (WARN, 'METADATA.pb: Designer "{}" is not listed in profiles.csv (at "{}")'.format(family_metadata.designer, PROFILES_GIT_URL))
            else:
                yield (PASS, 'Found designer "{}" at profiles.csv'.format(family_metadata.designer))
        except:
            yield (WARN, f'Failed to fetch "{PROFILES_RAW_URL}"')

def com_google_fonts_check_metadata_unique_full_name_values(family_metadata):
    """METADATA.pb: check if fonts field only has
    unique "full_name" values."""
    fonts = {}
    for f in family_metadata.fonts:
        fonts[f.full_name] = f
    if len(set(fonts.keys())) != len(family_metadata.fonts):
        yield (FAIL, 'Found duplicated "full_name" values in METADATA.pb fonts field.')
    else:
        yield (PASS, 'METADATA.pb "fonts" field only has unique "full_name" values.')

def com_google_fonts_check_metadata_unique_weight_style_pairs(family_metadata):
    """METADATA.pb: check if fonts field
    only contains unique style:weight pairs."""
    pairs = {}
    for f in family_metadata.fonts:
        styleweight = f'{f.style}:{f.weight}'
        pairs[styleweight] = 1
    if len(set(pairs.keys())) != len(family_metadata.fonts):
        yield (FAIL, 'Found duplicated style:weight pair in METADATA.pb fonts field.')
    else:
        yield (PASS, 'METADATA.pb "fonts" field only has unique style:weight pairs.')

def com_google_fonts_check_metadata_license(family_metadata):
    """METADATA.pb license is "APACHE2", "UFL" or "OFL"?"""
    licenses = ['APACHE2', 'OFL', 'UFL']
    if family_metadata.license in licenses:
        yield (PASS, 'Font license is declared in METADATA.pb as "{}"'.format(family_metadata.license))
    else:
        yield (FAIL, 'METADATA.pb license field ("{}") must be one of the following: {}'.format(family_metadata.license, licenses))

def com_google_fonts_check_metadata_menu_and_latin(family_metadata):
    """METADATA.pb should contain at least "menu" and "latin" subsets."""
    missing = []
    for s in ['menu', 'latin']:
        if s not in list(family_metadata.subsets):
            missing.append(s)
    if missing != []:
        yield (FAIL, 'Subsets "menu" and "latin" are mandatory, but METADATA.pb is missing "{}"'.format(' and '.join(missing)))
    else:
        yield (PASS, 'METADATA.pb contains "menu" and "latin" subsets.')

def com_google_fonts_check_metadata_subsets_order(family_metadata):
    """METADATA.pb subsets should be alphabetically ordered."""
    expected = list(sorted(family_metadata.subsets))
    if list(family_metadata.subsets) != expected:
        yield (FAIL, "METADATA.pb subsets are not sorted in alphabetical order: Got ['{}'] and expected ['{}']".format("', '".join(family_metadata.subsets), "', '".join(expected)))
    else:
        yield (PASS, 'METADATA.pb subsets are sorted in alphabetical order.')

def com_google_fonts_check_metadata_copyright(family_metadata):
    """METADATA.pb: Copyright notice is the same in all fonts?"""
    copyright = None
    fail = False
    for f in family_metadata.fonts:
        if copyright and f.copyright != copyright:
            fail = True
        copyright = f.copyright
    if fail:
        yield (FAIL, 'METADATA.pb: Copyright field value is inconsistent across family')
    else:
        yield (PASS, 'Copyright is consistent across family')

def com_google_fonts_check_metadata_familyname(family_metadata):
    """Check that METADATA.pb family values are all the same."""
    name = ''
    fail = False
    for f in family_metadata.fonts:
        if name and f.name != name:
            fail = True
        name = f.name
    if fail:
        yield (FAIL, 'METADATA.pb: Family name is not the same in all metadata "fonts" items.')
    else:
        yield (PASS, 'METADATA.pb: Family name is the same in all metadata "fonts" items.')

def com_google_fonts_check_metadata_regular_is_400(family_metadata):
    """METADATA.pb: Regular should be 400."""
    badfonts = []
    for f in family_metadata.fonts:
        if f.full_name.endswith('Regular') and f.weight != 400:
            badfonts.append(f'{f.filename} (weight: {f.weight})')
    if len(badfonts) > 0:
        yield (FAIL, 'METADATA.pb: Regular font weight must be 400. Please fix these: {}'.format(', '.join(badfonts)))
    else:
        yield (PASS, 'Regular has weight = 400.')

def com_google_fonts_check_metadata_nameid_family_name(ttFont, font_metadata):
    """Checks METADATA.pb font.name field matches
    family name declared on the name table."""
    from fontbakery.utils import get_name_entry_strings
    familynames = get_name_entry_strings(ttFont, NameID.TYPOGRAPHIC_FAMILY_NAME)
    if not familynames:
        familynames = get_name_entry_strings(ttFont, NameID.FONT_FAMILY_NAME)
    if len(familynames) == 0:
        yield (FAIL, Message('missing', 'This font lacks a FONT_FAMILY_NAME entry (nameID={}) in the name table.'.format(NameID.FONT_FAMILY_NAME)))
    elif font_metadata.name not in familynames:
        yield (FAIL, Message('mismatch', 'Unmatched family name in font: TTF has "{}" while METADATA.pb has "{}"'.format(familynames[0], font_metadata.name)))
    else:
        yield (PASS, 'Family name "{}" is identical in METADATA.pb and on the TTF file.'.format(font_metadata.name))

def com_google_fonts_check_metadata_nameid_post_script_name(ttFont, font_metadata):
    """Checks METADATA.pb font.post_script_name matches
    postscript name declared on the name table."""
    failed = False
    from fontbakery.utils import get_name_entry_strings
    postscript_names = get_name_entry_strings(ttFont, NameID.POSTSCRIPT_NAME)
    if len(postscript_names) == 0:
        failed = True
        yield (FAIL, Message('missing', 'This font lacks a POSTSCRIPT_NAME entry (nameID={}) in the name table.'.format(NameID.POSTSCRIPT_NAME)))
    else:
        for psname in postscript_names:
            if psname != font_metadata.post_script_name:
                failed = True
                yield (FAIL, Message('mismatch', 'Unmatched postscript name in font: TTF has "{}" while METADATA.pb has "{}".'.format(psname, font_metadata.post_script_name)))
    if not failed:
        yield (PASS, 'Postscript name "{}" is identical in METADATA.pb and on the TTF file.'.format(font_metadata.post_script_name))

def com_google_fonts_check_metadata_nameid_full_name(ttFont, font_metadata):
