def com_google_fonts_check_metadata_valid_name_values(style, font_metadata, font_familynames, typographic_familynames):
    """METADATA.pb font.name field contains font name in right format?"""
    from fontbakery.constants import RIBBI_STYLE_NAMES
    if style in RIBBI_STYLE_NAMES:
        familynames = font_familynames
    else:
        familynames = typographic_familynames
    failed = False
    for font_familyname in familynames:
        if font_familyname not in font_metadata.name:
            failed = True
            yield (FAIL, 'METADATA.pb font.name field ("{}") does not match correct font name format ("{}").'.format(font_metadata.name, font_familyname))
    if not failed:
        yield (PASS, 'METADATA.pb font.name field contains font name in right format.')

def com_google_fonts_check_metadata_valid_full_name_values(style, font_metadata, font_familynames, typographic_familynames):
    """METADATA.pb font.full_name field contains font name in right format?"""
    from fontbakery.constants import RIBBI_STYLE_NAMES
    if style in RIBBI_STYLE_NAMES:
        familynames = font_familynames
        if familynames == []:
            yield (SKIP, 'No FONT_FAMILYNAME')
    else:
        familynames = typographic_familynames
        if familynames == []:
            yield (SKIP, 'No TYPOGRAPHIC_FAMILYNAME')
    for font_familyname in familynames:
        if font_familyname in font_metadata.full_name:
            yield (PASS, "METADATA.pb font.full_name field contains font name in right format. ('{}' in '{}')".format(font_familyname, font_metadata.full_name))
        else:
            yield (FAIL, 'METADATA.pb font.full_name field ("{}") does not match correct font name format ("{}").'.format(font_metadata.full_name, font_familyname))

def com_google_fonts_check_metadata_valid_filename_values(font, family_metadata):
    """METADATA.pb font.filename field contains font name in right format?"""
    expected = os.path.basename(font)
    failed = True
    for font_metadata in family_metadata.fonts:
        if font_metadata.filename == expected:
            failed = False
            yield (PASS, 'METADATA.pb filename field contains font name in right format.')
            break
    if failed:
        yield (FAIL, f'None of the METADATA.pb filename fields match correct font name format ("{expected}").')

def com_google_fonts_check_metadata_valid_post_script_name_values(font_metadata, font_familynames):
    """METADATA.pb font.post_script_name field
