def com_google_fonts_check_metadata_valid_copyright(font_metadata):
    """Copyright notices match canonical pattern in METADATA.pb"""
    import re
    string = font_metadata.copyright
    does_match = re.search('Copyright [0-9]{4} The .* Project Authors \\([^\\@]*\\)', string)
    if does_match:
        yield (PASS, 'METADATA.pb copyright string is good')
    else:
        yield (FAIL, "METADATA.pb: Copyright notices should match a pattern similar to: 'Copyright 2017 The Familyname Project Authors (git url)'\nBut instead we have got: '{}'".format(string))

def com_google_fonts_check_font_copyright(ttFont):
    """Copyright notices match canonical pattern in fonts"""
    import re
    from fontbakery.utils import get_name_entry_strings
    failed = False
    for string in get_name_entry_strings(ttFont, NameID.COPYRIGHT_NOTICE):
        does_match = re.search('Copyright [0-9]{4} The .* Project Authors \\([^\\@]*\\)', string)
        if does_match:
            yield (PASS, "Name Table entry: Copyright field '{}' matches canonical pattern.".format(string))
        else:
            failed = True
            yield (FAIL, "Name Table entry: Copyright notices should match a pattern similar to: 'Copyright 2017 The Familyname Project Authors (git url)'\nBut instead we have got: '{}'".format(string))
    if not failed:
        yield (PASS, 'Name table copyright entries are good')

def com_google_fonts_check_metadata_canonical_filename(font_metadata, canonical_filename, is_variable_font):
    """METADATA.pb: Filename is set canonically?"""
    if is_variable_font:
        valid_varfont_suffixes = [('Roman-VF', 'Regular'), ('Italic-VF', 'Italic')]
        for valid_suffix, style in valid_varfont_suffixes:
            if style in canonical_filename:
                canonical_filename = valid_suffix.join(canonical_filename.split(style))
    if canonical_filename != font_metadata.filename:
        yield (FAIL, 'METADATA.pb: filename field ("{}") does not match canonical name "{}".'.format(font_metadata.filename, canonical_filename))
    else:
        yield (PASS, 'Filename in METADATA.pb is set canonically.')

def com_google_fonts_check_metadata_italic_style(ttFont, font_metadata):
    """METADATA.pb font.style "italic" matches font internals?"""
    from fontbakery.utils import get_name_entry_strings
    from fontbakery.constants import MacStyle
    if font_metadata.style != 'italic':
        yield (SKIP, 'This check only applies to italic fonts.')
    else:
        font_fullname = get_name_entry_strings(ttFont, NameID.FULL_FONT_NAME)
        if len(font_fullname) == 0:
            yield (SKIP, 'Font lacks fullname entries in name table.')
        else:
            font_fullname = font_fullname[0]
            if not bool(ttFont['head'].macStyle & MacStyle.ITALIC):
                yield (FAIL, Message('bad-macstyle', 'METADATA.pb style has been set to italic but font macStyle is improperly set.'))
            elif not font_fullname.split('-')[-1].endswith('Italic'):
                yield (FAIL, Message('bad-fullfont-name', 'Font macStyle Italic bit is set but nameID {} ("{}") is not ended with "Italic"'.format(NameID.FULL_FONT_NAME, font_fullname)))
            else:
                yield (PASS, 'OK: METADATA.pb font.style "italic" matches font internals.')

def com_google_fonts_check_metadata_nameid_family_and_full_names(ttFont, font_metadata):
    """METADATA.pb font.name and font.full_name fields match
    the values declared on the name table?"""
    from fontbakery.utils import get_name_entry_strings
    font_familynames = get_name_entry_strings(ttFont, NameID.TYPOGRAPHIC_FAMILY_NAME)
    if font_familynames:
        font_familyname = font_familynames[0]
    else:
        font_familyname = get_name_entry_strings(ttFont, NameID.FONT_FAMILY_NAME)[0]
    font_fullname = get_name_entry_strings(ttFont, NameID.FULL_FONT_NAME)[0]
    if font_fullname != font_metadata.full_name:
        yield (FAIL, Message('fullname-mismatch', 'METADATA.pb: Fullname ("{}") does not match name table entry "{}" !'.format(font_metadata.full_name, font_fullname)))
    elif font_familyname != font_metadata.name:
        yield (FAIL, Message('familyname-mismatch', 'METADATA.pb Family name "{}") does not match name table entry "{}" !'.format(font_metadata.name, font_familyname)))
    else:
        yield (PASS, 'METADATA.pb familyname and fullName fields match corresponding name table entries.')

def com_google_fonts_check_metadata_fontname_not_camel_cased(font_metadata):
    """METADATA.pb: Check if fontname is not camel cased."""
    import re
    if bool(re.match('([A-Z][a-z]+){2,}', font_metadata.name)):
        yield (FAIL, "METADATA.pb: '{}' is a CamelCased name. To solve this, simply use spaces instead in the font name.".format(font_metadata.name))
    else:
        yield (PASS, 'Font name is not camel-cased.')

def com_google_fonts_check_metadata_match_name_familyname(family_metadata, font_metadata):
    """METADATA.pb: Check font name is the same as family name."""
    if font_metadata.name != family_metadata.name:
        yield (FAIL, 'METADATA.pb: {}: Family name "{}" does not match font name: "{}"'.format(font_metadata.filename, family_metadata.name, font_metadata.name))
    else:
        yield (PASS, 'Font name is the same as family name.')

def com_google_fonts_check_metadata_canonical_weight_value(font_metadata):
    """METADATA.pb: Check that font weight has a canonical value."""
    first_digit = font_metadata.weight / 100
    if font_metadata.weight % 100 != 0 or (first_digit < 1 or first_digit > 9):
        yield (FAIL, 'METADATA.pb: The weight is declared as {} which is not a multiple of 100 between 100 and 900.'.format(font_metadata.weight))
    else:
        yield (PASS, 'Font weight has a canonical value.')

def com_google_fonts_check_metadata_os2_weightclass(ttFont, font_metadata):
    """Checking OS/2 usWeightClass matches weight specified at METADATA.pb."""
    GF_API_WEIGHT_NAMES = {250: 'Thin', 275: 'ExtraLight', 300: 'Light', 400: 'Regular', 500: 'Medium', 600: 'SemiBold', 700: 'Bold', 800: 'ExtraBold', 900: 'Black'}
    CSS_WEIGHT_NAMES = {100: 'Thin', 200: 'ExtraLight', 300: 'Light', 400: 'Regular', 500: 'Medium', 600: 'SemiBold', 700: 'Bold', 800: 'ExtraBold', 900: 'Black'}
    gf_weight = GF_API_WEIGHT_NAMES.get(ttFont['OS/2'].usWeightClass, 'bad Google Fonts API weight value')
    css_weight = CSS_WEIGHT_NAMES.get(font_metadata.weight, 'bad CSS weight value')
    if gf_weight != css_weight:
        yield (FAIL, 'OS/2 usWeightClass ({}:"{}") does not match weight specified at METADATA.pb ({}:"{}").'.format(ttFont['OS/2'].usWeightClass, gf_weight, font_metadata.weight, css_weight))
    else:
        yield (PASS, 'OS/2 usWeightClass matches weight specified at METADATA.pb')

def com_google_fonts_check_metatada_canonical_style_names(ttFont, font_metadata):
    """METADATA.pb: Font styles are named canonically?"""
    from fontbakery.constants import MacStyle
    def find_italic_in_name_table():
        for entry in ttFont['name'].names:
            if entry.nameID < 256 and 'italic' in entry.string.decode(entry.getEncoding()).lower():
                return True
        return False
    def is_italic():
        return ttFont['head'].macStyle & MacStyle.ITALIC or ttFont['post'].italicAngle or find_italic_in_name_table()
    if font_metadata.style not in ['italic', 'normal']:
        yield (SKIP, 'This check only applies to font styles declared as "italic" or "regular" on METADATA.pb.')
    elif is_italic() and font_metadata.style != 'italic':
        yield (FAIL, 'The font style is {} but it should be italic'.format(font_metadata.style))
    elif not is_italic() and font_metadata.style != 'normal':
        yield (FAIL, 'The font style is {} but it should be normal'.format(font_metadata.style))
    else:
        yield (PASS, 'Font styles are named canonically.')

def com_google_fonts_check_unitsperem_strict(ttFont):
    """Stricter unitsPerEm criteria for Google Fonts."""
    upm_height = ttFont['head'].unitsPerEm
    ACCEPTABLE = [16, 32, 64, 128, 256, 500, 512, 1000, 1024, 2000, 2048]
    if upm_height not in ACCEPTABLE:
        yield (FAIL, f'Font em size (unitsPerEm) is {upm_height}. If possible, please consider using 1000 or even 2000 (which is ideal for Variable Fonts). The acceptable values for unitsPerEm, though, are: {ACCEPTABLE}.')
    elif upm_height != 2000:
        yield (WARN, f'Even though unitsPerEm ({upm_height}) in this font is reasonable. It is strongly advised to consider changing it to 2000, since it will likely improve the quality of Variable Fonts by avoiding excessive rounding of coordinates on interpolations.')
    else:
        yield (PASS, 'Font em size is good (unitsPerEm = 2000).')

def remote_styles(family_metadata):
    """Get a dictionary of TTFont objects of all font files of
    a given family as currently hosted at Google Fonts."""
    def download_family_from_Google_Fonts(family_name):
        """Return a zipfile containing a font family hosted on fonts.google.com"""
        from zipfile import ZipFile
        from fontbakery.utils import download_file
        url_prefix = 'https://fonts.google.com/download?family='
        url = '{}{}'.format(url_prefix, family_name.replace(' ', '+'))
        return ZipFile(download_file(url))
    def fonts_from_zip(zipfile):
        """return a list of fontTools TTFonts"""
        from fontTools.ttLib import TTFont
        from io import BytesIO
        fonts = []
        for file_name in zipfile.namelist():
            if file_name.lower().endswith('.ttf'):
                file_obj = BytesIO(zipfile.open(file_name).read())
                fonts.append([file_name, TTFont(file_obj)])
        return fonts
    if not listed_on_gfonts_api(family_metadata) or not family_metadata:
        return None
    remote_fonts_zip = download_family_from_Google_Fonts(family_metadata.name)
    rstyles = {}
    for remote_filename, remote_font in fonts_from_zip(remote_fonts_zip):
        remote_style = os.path.splitext(remote_filename)[0]
        if '-' in remote_style:
            remote_style = remote_style.split('-')[1]
        rstyles[remote_style] = remote_font
    return rstyles

def com_google_fonts_check_version_bump(ttFont, api_gfonts_ttFont, github_gfonts_ttFont):
    """Version number has increased since previous release on Google Fonts?"""
    v_number = ttFont['head'].fontRevision
    api_gfonts_v_number = api_gfonts_ttFont['head'].fontRevision
    github_gfonts_v_number = github_gfonts_ttFont['head'].fontRevision
    failed = False
    if v_number == api_gfonts_v_number:
        failed = True
        yield (FAIL, 'Version number {} is equal to version on Google Fonts.'.format(v_number))
    if v_number < api_gfonts_v_number:
        failed = True
        yield (FAIL, 'Version number {} is less than version on Google Fonts ({}).'.format(v_number, api_gfonts_v_number))
    if v_number == github_gfonts_v_number:
        failed = True
        yield (FAIL, 'Version number {} is equal to version on Google Fonts GitHub repo.'.format(v_number))
    if v_number < github_gfonts_v_number:
        failed = True
        yield (FAIL, 'Version number {} is less than version on Google Fonts GitHub repo ({}).'.format(v_number, github_gfonts_v_number))
    if not failed:
        yield (PASS, 'Version number {} is greater than version on Google Fonts GitHub ({}) and production servers ({}).'.format(v_number, github_gfonts_v_number, api_gfonts_v_number))

def com_google_fonts_check_metadata_nameid_copyright(ttFont, font_metadata):
    """Copyright field for this font on METADATA.pb matches
    all copyright notice entries on the name table ?"""
    failed = False
    for nameRecord in ttFont['name'].names:
        string = nameRecord.string.decode(nameRecord.getEncoding())
        if nameRecord.nameID == NameID.COPYRIGHT_NOTICE and string != font_metadata.copyright:
            failed = True
            yield (FAIL, "Copyright field for this font on METADATA.pb ('{}') differs from a copyright notice entry on the name table: '{}'".format(font_metadata.copyright, string))
    if not failed:
        yield (PASS, 'Copyright field for this font on METADATA.pb matches copyright notice entries on the name table.')

def com_google_fonts_check_name_mandatory_entries(ttFont, style):
    """Font has all mandatory 'name' table entries ?"""
    from fontbakery.utils import get_name_entry_strings
    from fontbakery.constants import RIBBI_STYLE_NAMES
    required_nameIDs = [NameID.FONT_FAMILY_NAME, NameID.FONT_SUBFAMILY_NAME, NameID.FULL_FONT_NAME, NameID.POSTSCRIPT_NAME]
    if style not in RIBBI_STYLE_NAMES:
        required_nameIDs += [NameID.TYPOGRAPHIC_FAMILY_NAME, NameID.TYPOGRAPHIC_SUBFAMILY_NAME]
    failed = False
    for nameId in required_nameIDs:
        if len(get_name_entry_strings(ttFont, nameId)) == 0:
            failed = True
            yield (FAIL, f'Font lacks entry with nameId={nameId} ({NameID(nameId).name})')
    if not failed:
        yield (PASS, 'Font contains values for all mandatory name table entries.')

def com_google_fonts_check_name_familyname(ttFont, style, familyname_with_spaces):
    """Check name table: FONT_FAMILY_NAME entries."""
    from fontbakery.utils import name_entry_id
    failed = False
    only_weight = get_only_weight(style)
    for name in ttFont['name'].names:
        if name.nameID == NameID.FONT_FAMILY_NAME:
            if name.platformID == PlatformID.MACINTOSH:
                expected_value = familyname_with_spaces
            elif name.platformID == PlatformID.WINDOWS:
                if style in ['Regular', 'Italic', 'Bold', 'Bold Italic']:
                    expected_value = familyname_with_spaces
                else:
                    expected_value = ' '.join([familyname_with_spaces, only_weight]).strip()
            else:
                failed = True
                yield (FAIL, 'Font should not have a {} entry!'.format(name_entry_id(name)))
                continue
            string = name.string.decode(name.getEncoding()).strip()
            if string != expected_value:
                failed = True
                yield (FAIL, "Entry {} on the 'name' table: Expected '{}' but got '{}'.".format(name_entry_id(name), expected_value, string))
    if not failed:
        yield (PASS, 'FONT_FAMILY_NAME entries are all good.')

def com_google_fonts_check_name_subfamilyname(ttFont, style_with_spaces, familyname_with_spaces):
    """Check name table: FONT_SUBFAMILY_NAME entries."""
    from fontbakery.utils import name_entry_id
    failed = False
    for name in ttFont['name'].names:
        if name.nameID == NameID.FONT_SUBFAMILY_NAME:
            if name.platformID == PlatformID.MACINTOSH:
                expected_value = style_with_spaces
            elif name.platformID == PlatformID.WINDOWS:
                if style_with_spaces in ['Bold', 'Bold Italic']:
                    expected_value = style_with_spaces
                elif 'Italic' in style_with_spaces:
                    expected_value = 'Italic'
                else:
                    expected_value = 'Regular'
            else:
                yield (FAIL, Message('invalid-entry', 'Font should not have a {} entry!'.format(name_entry_id(name))))
                failed = True
                continue
            string = name.string.decode(name.getEncoding()).strip()
            if string != expected_value:
                failed = True
                yield (FAIL, Message('bad-familyname', "Entry {} on the 'name' table: Expected '{}' but got '{}'.".format(name_entry_id(name), expected_value, string)))
    if not failed:
        yield (PASS, 'FONT_SUBFAMILY_NAME entries are all good.')

def com_google_fonts_check_name_fullfontname(ttFont, style_with_spaces, familyname_with_spaces):
    """Check name table: FULL_FONT_NAME entries."""
    from fontbakery.utils import name_entry_id
    failed = False
    for name in ttFont['name'].names:
        if name.nameID == NameID.FULL_FONT_NAME:
