def com_google_fonts_check_name_typographicfamilyname(ttFont, style, familyname_with_spaces):
    """Check name table: TYPOGRAPHIC_FAMILY_NAME entries."""
    from fontbakery.utils import name_entry_id
    failed = False
    if style in ['Regular', 'Italic', 'Bold', 'BoldItalic']:
        for name in ttFont['name'].names:
            if name.nameID == NameID.TYPOGRAPHIC_FAMILY_NAME:
                failed = True
                yield (FAIL, Message('ribbi', "Font style is '{}' and, for that reason, it is not expected to have a {} entry!".format(style, name_entry_id(name))))
    else:
        expected_value = familyname_with_spaces
        has_entry = False
        for name in ttFont['name'].names:
            if name.nameID == NameID.TYPOGRAPHIC_FAMILY_NAME:
                string = name.string.decode(name.getEncoding()).strip()
                if string == expected_value:
                    has_entry = True
                else:
                    failed = True
                    yield (FAIL, Message('non-ribbi-bad-value', "Entry {} on the 'name' table: Expected '{}' but got '{}'.".format(name_entry_id(name), expected_value, string)))
        if not failed and (not has_entry):
            failed = True
            yield (FAIL, Message('non-ribbi-lacks-entry', 'non-RIBBI fonts must have a TYPOGRAPHIC_FAMILY_NAME entry on the name table.'))
    if not failed:
        yield (PASS, 'TYPOGRAPHIC_FAMILY_NAME entries are all good.')

def com_google_fonts_check_name_typographicsubfamilyname(ttFont, style_with_spaces):
    """Check name table: TYPOGRAPHIC_SUBFAMILY_NAME entries."""
    from fontbakery.utils import name_entry_id
    failed = False
    if style_with_spaces in ['Regular', 'Italic', 'Bold', 'Bold Italic']:
        for name in ttFont['name'].names:
            if name.nameID == NameID.TYPOGRAPHIC_SUBFAMILY_NAME:
                failed = True
                yield (FAIL, Message('ribbi', "Font style is '{}' and, for that reason, it is not expected to have a {} entry!".format(style_with_spaces, name_entry_id(name))))
    else:
        expected_value = style_with_spaces
        has_entry = False
        for name in ttFont['name'].names:
            if name.nameID == NameID.TYPOGRAPHIC_SUBFAMILY_NAME:
                string = name.string.decode(name.getEncoding()).strip()
                if string == expected_value:
                    has_entry = True
                else:
                    failed = True
                    yield (FAIL, Message('non-ribbi-bad-value', "Entry {} on the 'name' table: Expected '{}' but got '{}'.".format(name_entry_id(name), expected_value, string)))
        if not failed and (not has_entry):
            failed = True
            yield (FAIL, Message('non-ribbi-lacks-entry', 'non-RIBBI fonts must have a TYPOGRAPHIC_SUBFAMILY_NAME entry on the name table.'))
    if not failed:
        yield (PASS, 'TYPOGRAPHIC_SUBFAMILY_NAME entries are all good.')

def com_google_fonts_check_name_copyright_length(ttFont):
    """Length of copyright notice must not exceed 500 characters."""
    from fontbakery.utils import get_name_entries
    failed = False
    for notice in get_name_entries(ttFont, NameID.COPYRIGHT_NOTICE):
        notice_str = notice.string.decode(notice.getEncoding())
        if len(notice_str) > 500:
            failed = True
            yield (FAIL, "The length of the following copyright notice ({}) exceeds 500 chars: '{}'".format(len(notice_str), notice_str))
    if not failed:
        yield (PASS, "All copyright notice name entries on the 'name' table are shorter than 500 characters.")

def com_google_fonts_check_fontdata_namecheck(ttFont, familyname):
    """Familyname must be unique according to namecheck.fontdata.com"""
    FB_ISSUE_TRACKER = 'https://github.com/googlefonts/fontbakery/issues'
    import requests
    url = f'http://namecheck.fontdata.com/?q={familyname}'
    try:
        response = requests.get(url, timeout=10)
        data = response.content.decode('utf-8')
        if 'fonts by that exact name' in data:
            yield (INFO, "The family name '{}' seem to be already in use.\nPlease visit {} for more info.".format(familyname, url))
        else:
            yield (PASS, 'Font familyname seems to be unique.')
    except:
        yield (ERROR, "Failed to access: '{}'.\nPlease report this issue at:\n{}".format(url, FB_ISSUE_TRACKER))

def com_google_fonts_check_fontv(ttFont):
    """Check for font-v versioning"""
    from fontv.libfv import FontVersion
    fv = FontVersion(ttFont)
    if fv.version and (fv.is_development or fv.is_release):
        yield (PASS, 'Font version string looks GREAT!')
    else:
        yield (INFO, 'Version string is: "{}"\nThe version string must ideally include a git commit hash and either a \'dev\' or a \'release\' suffix such as in the example below:\n"Version 1.3; git-0d08353-release"'.format(fv.get_name_id5_version_string()))

def com_google_fonts_check_negative_advance_width(ttFont):
    """Check that advance widths cannot be inferred as negative."""
    failed = False
    for glyphName in ttFont['glyf'].glyphs:
        coords = ttFont['glyf'][glyphName].coordinates
        rightX = coords[-3][0]
        leftX = coords[-4][0]
        advwidth = rightX - leftX
        if advwidth < 0:
            failed = True
            yield (FAIL, "glyph '{}' has bad coordinates on the glyf table, which may lead to the advance width to be interpreted as a negative value ({}).".format(glyphName, advwidth))
    if not failed:
        yield (PASS, 'The x-coordinates of all glyphs look good.')

def com_google_fonts_check_varfont_generate_static(ttFont):
    """Check a static ttf can be generated from a variable font."""
    import tempfile
    from fontTools.varLib import mutator
    try:
        loc = {k.axisTag: float((k.maxValue + k.minValue) / 2) for k in ttFont['fvar'].axes}
        with tempfile.TemporaryFile() as instance:
            font = mutator.instantiateVariableFont(ttFont, loc)
            font.save(instance)
            yield (PASS, 'fontTools.varLib.mutator generated a static font instance')
    except Exception as e:
        yield (FAIL, 'fontTools.varLib.mutator failed to generated a static font instance\n{}'.format(repr(e)))

def com_google_fonts_check_aat(ttFont):
    """Are there unwanted Apple tables?"""
    UNWANTED_TABLES = {'EBSC', 'Zaph', 'acnt', 'ankr', 'bdat', 'bhed', 'bloc', 'bmap', 'bsln', 'fdsc', 'feat', 'fond', 'gcid', 'just', 'kerx', 'lcar', 'ltag', 'mort', 'morx', 'opbd', 'prop', 'trak', 'xref'}
    unwanted_tables_found = []
    for table in ttFont.keys():
        if table in UNWANTED_TABLES:
            unwanted_tables_found.append(table)
    if len(unwanted_tables_found) > 0:
        yield (FAIL, 'Unwanted AAT tables were found in the font and should be removed, either by fonttools/ttx or by editing them using the tool they built with: {}'.format(', '.join(unwanted_tables_found)))
    else:
        yield (PASS, 'There are no unwanted AAT tables.')

def com_google_fonts_check_fvar_name_entries(ttFont):
    """All name entries referenced by fvar instances exist on the name table?"""
    failed = False
    for instance in ttFont['fvar'].instances:
        entries = [entry for entry in ttFont['name'].names if entry.nameID == instance.subfamilyNameID]
        if len(entries) == 0:
            failed = True
            yield (FAIL, f'Named instance with coordinates {instance.coordinates} lacks an entry on the name table (nameID={instance.subfamilyNameID}).')
    if not failed:
        yield (PASS, 'OK')

def com_google_fonts_check_varfont_weight_instances(ttFont):
    """Variable font weight coordinates must be multiples of 100."""
    failed = False
    for instance in ttFont['fvar'].instances:
        if 'wght' in instance.coordinates and instance.coordinates['wght'] % 100 != 0:
            failed = True
            yield (FAIL, f"Found an variable font instance with 'wght'={instance.coordinates['wght']}. This should instead be a multiple of 100.")
    if not failed:
        yield (PASS, 'OK')

def com_google_fonts_check_family_tnum_horizontal_metrics(fonts):
    """All tabular figures must have the same width across the RIBBI-family."""
    from fontbakery.constants import RIBBI_STYLE_NAMES
    from fontTools.ttLib import TTFont
    RIBBI_ttFonts = [TTFont(f) for f in fonts if style(f) in RIBBI_STYLE_NAMES]
    tnum_widths = {}
    for ttFont in RIBBI_ttFonts:
        glyphs = ttFont.getGlyphSet()
        tnum_glyphs = [(glyph_id, glyphs[glyph_id]) for glyph_id in glyphs.keys() if glyph_id.endswith('.tnum')]
        for glyph_id, glyph in tnum_glyphs:
            if glyph.width not in tnum_widths:
                tnum_widths[glyph.width] = [glyph_id]
            else:
                tnum_widths[glyph.width].append(glyph_id)
    if len(tnum_widths.keys()) > 1:
        max_num = 0
        most_common_width = None
        for width, glyphs in tnum_widths.items():
            if len(glyphs) > max_num:
                max_num = len(glyphs)
                most_common_width = width
        del tnum_widths[most_common_width]
        yield (FAIL, f'The most common tabular glyph width is {most_common_width}. But there are other tabular glyphs with different widths such as the following ones:\n\t{tnum_widths}.')
    else:
        yield (PASS, 'OK')

def com_google_fonts_check_ligature_carets(ttFont, ligature_glyphs):
    """Are there caret positions declared for every ligature?"""
    if ligature_glyphs == -1:
        yield (FAIL, Message('malformed', 'Failed to lookup ligatures. This font file seems to be malformed. For more info, read: https://github.com/googlefonts/fontbakery/issues/1596'))
    elif 'GDEF' not in ttFont:
        yield (WARN, Message('GDEF-missing', 'GDEF table is missing, but it is mandatory to declare it on fonts that provide ligature glyphs because the caret (text cursor) positioning for each ligature must be provided in this table.'))
    else:
        lig_caret_list = ttFont['GDEF'].table.LigCaretList
        if lig_caret_list is None:
            missing = set(ligature_glyphs)
        else:
            missing = set(ligature_glyphs) - set(lig_caret_list.Coverage.glyphs)
        if lig_caret_list is None or lig_caret_list.LigGlyphCount == 0:
            yield (WARN, Message('lacks-caret-pos', 'This font lacks caret position values for ligature glyphs on its GDEF table.'))
        elif missing:
            missing = '\n\t- '.join(missing)
            yield (WARN, Message('incomplete-caret-pos-data', f'This font lacks caret positioning values for these ligature glyphs:\n\t- {missing}\n\n  '))
        else:
            yield (PASS, 'Looks good!')

def com_google_fonts_check_name_family_and_style_max_length(ttFont):
    """Combined length of family and style must not exceed 27 characters."""
    from fontbakery.utils import get_name_entries, get_name_entry_strings
    failed = False
    for familyname in get_name_entries(ttFont, NameID.FONT_FAMILY_NAME):
        plat = familyname.platformID
        familyname_str = familyname.string.decode(familyname.getEncoding())
        for stylename_str in get_name_entry_strings(ttFont, NameID.FONT_SUBFAMILY_NAME, platformID=plat):
            if len(familyname_str + stylename_str) > 27:
                failed = True
                yield (WARN, "The combined length of family and style exceeds 27 chars in the following '{}' entries: FONT_FAMILY_NAME = '{}' / SUBFAMILY_NAME = '{}'".format(PlatformID(plat).name, familyname_str, stylename_str))
                yield (WARN, 'Please take a look at the conversation at https://github.com/googlefonts/fontbakery/issues/2179 in order to understand the reasoning behing these name table records max-length criteria.')
    if not failed:
        yield (PASS, 'All name entries are good.')

def com_google_fonts_check_family_control_chars(ttFonts):
    """Does font file include unacceptable control character glyphs?"""
    unacceptable_cc_list = ['uni0001', 'uni0002', 'uni0003', 'uni0004', 'uni0005', 'uni0006', 'uni0007', 'uni0008', 'uni0009', 'uni000A', 'uni000B', 'uni000C', 'uni000E', 'uni000F', 'uni0010', 'uni0011', 'uni0012', 'uni0013', 'uni0014', 'uni0015', 'uni0016', 'uni0017', 'uni0018', 'uni0019', 'uni001A', 'uni001B', 'uni001C', 'uni001D', 'uni001E', 'uni001F']
    failed_font_dict = {}
    for ttFont in ttFonts:
        font_failed = False
        unacceptable_glyphs_in_set = []
        glyph_name_set = set(ttFont['glyf'].glyphs.keys())
        fontname = ttFont.reader.file.name
        for unacceptable_glyph_name in unacceptable_cc_list:
            if unacceptable_glyph_name in glyph_name_set:
                font_failed = True
                unacceptable_glyphs_in_set.append(unacceptable_glyph_name)
        if font_failed:
            failed_font_dict[fontname] = unacceptable_glyphs_in_set
    if len(failed_font_dict) > 0:
        unacceptable_cc_report_string = 'The following unacceptable control characters were identified:\n'
        for fnt in failed_font_dict.keys():
            unacceptable_cc_report_string += ' {}: {}\n'.format(fnt, ', '.join(failed_font_dict[fnt]))
        yield (FAIL, '{}'.format(unacceptable_cc_report_string))
    else:
        yield (PASS, 'Unacceptable control characters were not identified.')

def com_google_fonts_check_family_panose_proportion(ttFonts):
    """Fonts have consistent PANOSE proportion?"""
    failed = False
    proportion = None
    for ttFont in ttFonts:
        if proportion is None:
            proportion = ttFont['OS/2'].panose.bProportion
        if proportion != ttFont['OS/2'].panose.bProportion:
            failed = True
    if failed:
        yield (FAIL, 'PANOSE proportion is not the same accross this family. In order to fix this, please make sure that the panose.bProportion value is the same in the OS/2 table of all of this family font files.')
    else:
        yield (PASS, 'Fonts have consistent PANOSE proportion.')

def com_google_fonts_check_family_panose_familytype(ttFonts):
    """Fonts have consistent PANOSE family type?"""
    failed = False
    familytype = None
    for ttfont in ttFonts:
        if familytype is None:
            familytype = ttfont['OS/2'].panose.bFamilyType
        if familytype != ttfont['OS/2'].panose.bFamilyType:
            failed = True
    if failed:
        yield (FAIL, 'PANOSE family type is not the same accross this family. In order to fix this, please make sure that the panose.bFamilyType value is the same in the OS/2 table of all of this family font files.')
    else:
        yield (PASS, 'Fonts have consistent PANOSE family type.')

def com_google_fonts_check_code_pages(ttFont):
    """Check code page character ranges"""
    if not hasattr(ttFont['OS/2'], 'ulCodePageRange1') or not hasattr(ttFont['OS/2'], 'ulCodePageRange2') or (ttFont['OS/2'].ulCodePageRange1 == 0 and ttFont['OS/2'].ulCodePageRange2 == 0):
        yield (FAIL, 'No code pages defined in the OS/2 table ulCodePageRage1 and CodePageRage2 fields.')
    else:
        yield (PASS, 'At least one code page is defined.')

def com_google_fonts_check_glyf_unused_data(ttFont):
    """Is there any unused data at the end of the glyf table?"""
    try:
        expected_glyphs = len(ttFont.getGlyphOrder())
        actual_glyphs = len(ttFont['glyf'].glyphs)
        diff = actual_glyphs - expected_glyphs
        if diff < 0:
            yield (FAIL, Message('unreachable-data', 'Glyf table has unreachable data at the end of  the table. Expected glyf table length {} (from loca table), got length {} (difference: {})'.format(expected_glyphs, actual_glyphs, diff)))
        elif not diff:
            yield (PASS, 'There is no unused data at the end of the glyf table.')
        else:
            raise Exception('Bug: fontTools did not raise an expected exception.')
    except fontTools.ttLib.TTLibError as error:
        if "not enough 'glyf' table data" in format(error):
            yield (FAIL, Message('missing-data', 'Loca table references data beyond the end of the glyf table. Expected glyf table length {} (from loca table).'.format(expected_glyphs)))
        else:
            raise Exception('Bug: Unexpected fontTools exception.')

def com_google_fonts_check_points_out_of_bounds(ttFont):
    """Check for points out of bounds."""
    failed = False
    out_of_bounds = []
    for glyphName in ttFont['glyf'].keys():
        glyph = ttFont['glyf'][glyphName]
        coords = glyph.getCoordinates(ttFont['glyf'])[0]
        for x, y in coords:
            if x < glyph.xMin or x > glyph.xMax or y < glyph.yMin or (y > glyph.yMax) or (abs(x) > 32766) or (abs(y) > 32766):
                failed = True
                out_of_bounds.append((glyphName, x, y))
    if failed:
        yield (WARN, 'The following glyphs have coordinates which are out of bounds:\n{}\nThis happens a lot when points are not extremes, which is usually bad. However, fixing this alert by adding points on extremes may do more harm than good, especially with italics, calligraphic-script, handwriting, rounded and other fonts. So it is common to ignore this message'.format(out_of_bounds))
    else:
        yield (PASS, 'All glyph paths have coordinates within bounds!')

def com_daltonmaag_check_ufolint(font):
    """Run ufolint on UFO source directory."""
    import subprocess
    ufolint_cmd = ['ufolint', font]
    try:
        subprocess.check_output(ufolint_cmd, stderr=subprocess.STDOUT)
    except subprocess.CalledProcessError as e:
        yield (FAIL, 'ufolint failed the UFO source. Output follows :\n\n{}\n'.format(e.output.decode()))
    except OSError:
        yield (ERROR, 'ufolint is not available!')
    else:
        yield (PASS, 'ufolint passed the UFO source.')

def com_daltonmaag_check_required_fields(ufo_font):
    """Check that required fields are present in the UFO fontinfo.

    ufo2ft requires these info fields to compile a font binary:
    unitsPerEm, ascender, descender, xHeight, capHeight and familyName."""
    recommended_fields = []
    for field in ['unitsPerEm', 'ascender', 'descender', 'xHeight', 'capHeight', 'familyName']:
        if ufo_font.info.__dict__.get('_' + field) is None:
            recommended_fields.append(field)
    if recommended_fields:
        yield (FAIL, f'Required field(s) missing: {recommended_fields}')
    else:
        yield (PASS, 'Required fields present.')

def com_daltonmaag_check_recommended_fields(ufo_font):
    """Check that recommended fields are present in the UFO fontinfo.

    This includes fields that should be in any production font."""
    recommended_fields = []
    for field in ['postscriptUnderlineThickness', 'postscriptUnderlinePosition', 'versionMajor', 'versionMinor', 'styleName', 'copyright', 'openTypeOS2Panose']:
        if ufo_font.info.__dict__.get('_' + field) is None:
            recommended_fields.append(field)
    if recommended_fields:
        yield (WARN, f'Recommended field(s) missing: {recommended_fields}')
    else:
        yield (PASS, 'Recommended fields present.')

def com_daltonmaag_check_unnecessary_fields(ufo_font):
    """Check that no unnecessary fields are present in the UFO fontinfo.

    ufo2ft will generate these.

    openTypeOS2UnicodeRanges and openTypeOS2CodePageRanges are exempted
    because it is useful to toggle a range when not _all_ the glyphs in that
    region are present.

    year is deprecated since UFO v2."""
    unnecessary_fields = []
    for field in ['openTypeNameUniqueID', 'openTypeNameVersion', 'postscriptUniqueID', 'year']:
        if ufo_font.info.__dict__.get('_' + field) is not None:
            unnecessary_fields.append(field)
    if unnecessary_fields:
        yield (WARN, f'Unnecessary field(s) present: {unnecessary_fields}')
    else:
        yield (PASS, 'Unnecessary fields omitted.')

def com_google_fonts_check_varfont_regular_opsz_coord(ttFont, regular_opsz_coord):
    """The variable font 'opsz' (Optical Size) axis coordinate should be between
    9 and 13 on the 'Regular' instance."""
    if regular_opsz_coord >= 9 and regular_opsz_coord <= 13:
        yield (PASS, 'Regular:opsz coordinate ({}) looks good.'.format(regular_opsz_coord))
    else:
        yield (WARN, "The 'opsz' (Optical Size) coordinate on the 'Regular' instance is recommended to be a value in the range 9 to 13. Got a '{}' coordinate instead.".format(regular_opsz_coord))

def com_google_fonts_check_wght_valid_range(ttFont):
    """The variable font 'wght' (Weight) axis coordinate
    must be within spec range of 1 to 1000 on all instances."""
    Failed = False
    for instance in ttFont['fvar'].instances:
        if 'wght' in instance.coordinates:
            value = instance.coordinates['wght']
            if value < 1 or value > 1000:
                Failed = True
                yield (FAIL, f"Found a bad wght coordinate with value '{value}' outside of the valid range from 1 to 1000.")
                break
    if not Failed:
        yield (PASS, 'OK')

def normalize_variable_name(node, reachability_tester):
    """Returns normalized variable name.
    Normalizing means that variable names get explicit visibility by
    visibility prefix such as: "g:", "s:", ...

    Returns None if the specified node is unanalyzable.
    A node is unanalyzable if:

    - the node is not identifier-like
    - the node is named dynamically"""
    node_type = NodeType(node['type'])
    if not is_analyzable_identifier(node):
        return None
    if node_type is NodeType.IDENTIFIER:
        return _normalize_identifier_value(node, reachability_tester)
    if node_type in IdentifierLikeNodeTypes:
        return node['value']

def traverse(node, on_enter=None, on_leave=None):
    """Traverses the specified Vim script AST node (depth first order).
    The on_enter/on_leave handler will be called with the specified node and
    the children. You can skip traversing child nodes by returning
    SKIP_CHILDREN."""
    node_type = NodeType(node['type'])
    if node_type not in ChildNodeAccessorMap:
        raise UnknownNodeTypeException(node_type)
    if on_enter:
        should_traverse_children = on_enter(node) is not SKIP_CHILDREN
    else:
        should_traverse_children = True
    if should_traverse_children:
        for property_accessor in ChildNodeAccessorMap[node_type]:
            accessor_func = property_accessor['accessor']
            prop_name = property_accessor['property_name']
            accessor_func(lambda child_node: traverse(child_node, on_enter, on_leave), node[prop_name])
        for handler in _traverser_extensions:
            handler(node, on_enter=on_enter, on_leave=on_leave)
    if on_leave:
        on_leave(node)

def _build_cmdargs(argv):
    """Build command line arguments dict to use;
    - displaying usages
    - vint.linting.env.build_environment

    This method take an argv parameter to make function pure."""
    parser = _build_arg_parser()
    namespace = parser.parse_args(argv[1:])
    cmdargs = vars(namespace)
    return cmdargs

def is_builtin_variable(id_node):
    """Whether the specified node is a builtin identifier."""
    if NodeType(id_node['type']) is not NodeType.IDENTIFIER:
        return False
    id_value = id_node['value']
    if id_value.startswith('v:'):
        return True
    if is_builtin_function(id_node):
        return True
    if id_value in ['key', 'val']:
        return is_on_lambda_string_context(id_node)
    return id_value in BuiltinVariablesCanHaveImplicitScope

def is_builtin_function(id_node):
    """Whether the specified node is a builtin function name identifier.
    The given identifier should be a child node of NodeType.CALL."""
    if NodeType(id_node['type']) is not NodeType.IDENTIFIER:
        return False
    id_value = id_node['value']
    if not is_function_identifier(id_node):
        return False
    return id_value in BuiltinFunctions

def detect_possible_scope_visibility(node, context_scope):
    """Returns a *possible* variable visibility by the specified node.
    The "possible" means that we can not determine a scope visibility of lambda arguments until reachability check."""
    node_type = NodeType(node['type'])
    if not is_analyzable_identifier(node):
        return ScopeVisibilityHint(ScopeVisibility.UNANALYZABLE, ExplicityOfScopeVisibility.UNANALYZABLE)
    if node_type is NodeType.IDENTIFIER:
        return _detect_possible_identifier_scope_visibility(node, context_scope)
    if node_type in GlobalLikeScopeVisibilityNodeTypes:
        return ScopeVisibilityHint(ScopeVisibility.GLOBAL_LIKE, ExplicityOfScopeVisibility.IMPLICIT_BUT_CONSTRAINED)
    return ScopeVisibilityHint(ScopeVisibility.UNANALYZABLE, ExplicityOfScopeVisibility.UNANALYZABLE)

def clone(name, clone_name, config=None):
    """Clone an entry to the sshconfig."""
    storm_ = get_storm_instance(config)
    try:
        if '@' in name:
            raise ValueError('invalid value: "@" cannot be used in name.')
        storm_.clone_entry(name, clone_name)
        print(get_formatted_message('{0} added to your ssh config. you can connect it by typing "ssh {0}".'.format(clone_name), 'success'))
    except ValueError as error:
        print(get_formatted_message(error, 'error'), file=sys.stderr)
        sys.exit(1)

def move(name, entry_name, config=None):
    """Move an entry to the sshconfig."""
    storm_ = get_storm_instance(config)
    try:
        if '@' in name:
            raise ValueError('invalid value: "@" cannot be used in name.')
        storm_.clone_entry(name, entry_name, keep_original=False)
        print(get_formatted_message('{0} moved in ssh config. you can connect it by typing "ssh {0}".'.format(entry_name), 'success'))
    except ValueError as error:
        print(get_formatted_message(error, 'error'), file=sys.stderr)
        sys.exit(1)

def edit(name, connection_uri, id_file='', o=[], config=None):
    """Edits the related entry in ssh config."""
    storm_ = get_storm_instance(config)
    try:
        if ',' in name:
            name = ' '.join(name.split(','))
        user, host, port = parse(connection_uri, user=get_default('user', storm_.defaults), port=get_default('port', storm_.defaults))
        storm_.edit_entry(name, host, user, port, id_file, o)
        print(get_formatted_message('"{0}" updated successfully.'.format(name), 'success'))
    except ValueError as error:
        print(get_formatted_message(error, 'error'), file=sys.stderr)
        sys.exit(1)

def update(name, connection_uri='', id_file='', o=[], config=None):
    """Enhanced version of the edit command featuring multiple
    edits using regular expressions to match entries"""
    storm_ = get_storm_instance(config)
    settings = {}
    if id_file != '':
        settings['identityfile'] = id_file
    for option in o:
        k, v = option.split('=')
        settings[k] = v
    try:
        storm_.update_entry(name, **settings)
        print(get_formatted_message('"{0}" updated successfully.'.format(name), 'success'))
    except ValueError as error:
        print(get_formatted_message(error, 'error'), file=sys.stderr)
        sys.exit(1)

def delete(name, config=None):
    """Deletes a single host."""
    storm_ = get_storm_instance(config)
    try:
        storm_.delete_entry(name)
        print(get_formatted_message('hostname "{0}" deleted successfully.'.format(name), 'success'))
    except ValueError as error:
        print(get_formatted_message(error, 'error'), file=sys.stderr)
        sys.exit(1)

def delete_all(config=None):
    """Deletes all hosts from ssh config."""
    storm_ = get_storm_instance(config)
    try:
        storm_.delete_all_entries()
        print(get_formatted_message('all entries deleted.', 'success'))
    except Exception as error:
        print(get_formatted_message(str(error), 'error'), file=sys.stderr)
