def wait_for_any_log(nodes, pattern, timeout, filename='system.log', marks=None):
    """Look for a pattern in the system.log of any in a given list
    of nodes.
    @param nodes The list of nodes whose logs to scan
    @param pattern The target pattern
    @param timeout How long to wait for the pattern. Note that
                    strictly speaking, timeout is not really a timeout,
                    but a maximum number of attempts. This implies that
                    the all the grepping takes no time at all, so it is
                    somewhat inaccurate, but probably close enough.
    @param marks A dict of nodes to marks in the file. Keys must match the first param list.
    @return The first node in whose log the pattern was found"""
    if marks is None:
        marks = {}
    for _ in range(timeout):
        for node in nodes:
            found = node.grep_log(pattern, filename=filename, from_mark=marks.get(node, None))
            if found:
                return node
        time.sleep(1)
    raise TimeoutError(time.strftime('%d %b %Y %H:%M:%S', time.gmtime()) + ' Unable to find: ' + repr(pattern) + ' in any node log within ' + str(timeout) + 's')

def get_tagged_version_numbers(series='stable'):
    """Retrieve git tags and find version numbers for a release series

    series - 'stable', 'oldstable', or 'testing'"""
    releases = []
    if series == 'testing':
        tag_regex = re.compile('^refs/tags/cassandra-([0-9]+\\.[0-9]+\\.[0-9]+-.*$)')
    else:
        tag_regex = re.compile('^refs/tags/cassandra-([0-9]+\\.[0-9]+\\.[0-9]+$)')
    tag_url = urllib.request.urlopen(GITHUB_TAGS)
    for ref in (i.get('ref', '') for i in json.loads(tag_url.read())):
        m = tag_regex.match(ref)
        if m:
            releases.append(LooseVersion(m.groups()[0]))
    releases.sort(reverse=True)
    stable_major_version = LooseVersion(str(releases[0].version[0]) + '.' + str(releases[0].version[1]))
    stable_releases = [r for r in releases if r >= stable_major_version]
    oldstable_releases = [r for r in releases if r not in stable_releases]
    oldstable_major_version = LooseVersion(str(oldstable_releases[0].version[0]) + '.' + str(oldstable_releases[0].version[1]))
    oldstable_releases = [r for r in oldstable_releases if r >= oldstable_major_version]
    if series == 'testing':
        return [r.vstring for r in releases]
    elif series == 'stable':
        return [r.vstring for r in stable_releases]
    elif series == 'oldstable':
        return [r.vstring for r in oldstable_releases]
    else:
        raise AssertionError('unknown release series: {series}'.format(series=series))

def _jwt_required(realm):
    """Does the actual work of verifying the JWT data in the current request.
    This is done automatically for you by `jwt_required()` but you could call it manually.
    Doing so would be useful in the context of optional JWT access in your APIs.

    :param realm: an optional realm"""
    token = _jwt.request_callback()
    if token is None:
        raise JWTError('Authorization Required', 'Request does not contain an access token', headers={'WWW-Authenticate': 'JWT realm="%s"' % realm})
    try:
        payload = _jwt.jwt_decode_callback(token)
    except jwt.InvalidTokenError as e:
        raise JWTError('Invalid token', str(e))
    _request_ctx_stack.top.current_identity = identity = _jwt.identity_callback(payload)
    if identity is None:
        raise JWTError('Invalid JWT', 'User does not exist')

def jwt_required(realm=None):
    """View decorator that requires a valid JWT token to be present in the request

    :param realm: an optional realm"""
    def wrapper(fn):
        @wraps(fn)
        def decorator(*args, **kwargs):
            _jwt_required(realm or current_app.config['JWT_DEFAULT_REALM'])
            return fn(*args, **kwargs)
        return decorator
    return wrapper

def create_incident(**kwargs):
    """Creates an incident"""
    incidents = cachet.Incidents(endpoint=ENDPOINT, api_token=API_TOKEN)
    if 'component_id' in kwargs:
        return incidents.post(name=kwargs['name'], message=kwargs['message'], status=kwargs['status'], component_id=kwargs['component_id'], component_status=kwargs['component_status'])
    else:
        return incidents.post(name=kwargs['name'], message=kwargs['message'], status=kwargs['status'])

def incident_exists(name, message, status):
    """Check if an incident with these attributes already exists"""
    incidents = cachet.Incidents(endpoint=ENDPOINT)
    all_incidents = json.loads(incidents.get())
    for incident in all_incidents['data']:
        if name == incident['name'] and status == incident['status'] and (message.strip() == incident['message'].strip()):
            return True
    return False

def api_token_required(f, *args, **kwargs):
    """Decorator helper function to ensure some methods aren't needlessly called
    without an api_token configured."""
    try:
        if args[0].api_token is None:
            raise AttributeError('Parameter api_token is required.')
    except AttributeError:
        raise AttributeError('Parameter api_token is required.')
    return f(*args, **kwargs)

def check_required_args(required_args, args):
    """Checks if all required_args have a value.
    :param required_args: list of required args
    :param args: kwargs
    :return: True (if an exception isn't raised)"""
    for arg in required_args:
        if arg not in args:
            raise KeyError('Required argument: %s' % arg)
    return True

def synchronized(wrapped):
    """The missing @synchronized decorator

    https://git.io/vydTA"""
    _lock = threading.RLock()
    @functools.wraps(wrapped)
    def _wrapper(*args, **kwargs):
        with _lock:
            return wrapped(*args, **kwargs)
    return _wrapper

def get_version():
    """Obtain the packge version from a python file e.g. pkg/__init__.py
    See <https://packaging.python.org/en/latest/single_source_version.html>."""
    file_dir = os.path.realpath(os.path.dirname(__file__))
    with open(os.path.join(file_dir, '..', 'behold', 'version.py')) as f:
        txt = f.read()
    version_match = re.search('^__version__ = [\'"]([^\'"]*)[\'"]', txt, re.M)
    if version_match:
        return version_match.group(1)
    raise RuntimeError('Unable to find version string.')

def staticmap(ctx, mapid, output, features, lat, lon, zoom, size):
    """Generate static map images from existing Mapbox map ids.
    Optionally overlay with geojson features.

      $ mapbox staticmap --features features.geojson mapbox.satellite out.png
      $ mapbox staticmap --lon -61.7 --lat 12.1 --zoom 12 mapbox.satellite out2.png

    An access token is required, see `mapbox --help`."""
    access_token = ctx.obj and ctx.obj.get('access_token') or None
    if features:
        features = list(cligj.normalize_feature_inputs(None, 'features', [features]))
    service = mapbox.Static(access_token=access_token)
    try:
        res = service.image(mapid, lon=lon, lat=lat, z=zoom, width=size[0], height=size[1], features=features, sort_keys=True)
    except mapbox.errors.ValidationError as exc:
        raise click.BadParameter(str(exc))
    if res.status_code == 200:
        output.write(res.content)
    else:
        raise MapboxCLIException(res.text.strip())

def coords_from_query(query):
    """Transform a query line into a (lng, lat) pair of coordinates."""
    try:
        coords = json.loads(query)
    except ValueError:
        vals = re.split('[,\\s]+', query.strip())
        coords = [float(v) for v in vals]
    return tuple(coords[:2])

def echo_headers(headers, file=None):
    """Echo headers, sorted."""
    for k, v in sorted(headers.items()):
        click.echo('{0}: {1}'.format(k.title(), v), file=file)
    click.echo(file=file)

def ftdetect(filename):
    """Determine if filename is markdown or notebook,
    based on the file extension."""
    _, extension = os.path.splitext(filename)
    md_exts = ['.md', '.markdown', '.mkd', '.mdown', '.mkdn', '.Rmd']
    nb_exts = ['.ipynb']
    if extension in md_exts:
        return 'markdown'
    elif extension in nb_exts:
        return 'notebook'
    else:
        return None

def strip(notebook):
    """Remove outputs from a notebook."""
    for cell in notebook.cells:
        if cell.cell_type == 'code':
            cell.outputs = []
            cell.execution_count = None

def get_caption_comments(content):
    """Retrieve an id and a caption from a code cell.

    If the code cell content begins with a commented
    block that looks like

    ## fig:id
    # multi-line or single-line
    # caption

    then the 'fig:id' and the caption will be returned.
    The '#' are stripped."""
    if not content.startswith('## fig:'):
        return (None, None)
    content = content.splitlines()
    id = content[0].strip('## ')
    caption = []
    for line in content[1:]:
        if not line.startswith('# ') or line.startswith('##'):
            break
        else:
            caption.append(line.lstrip('# ').rstrip())
    caption = '"' + ' '.join(caption) + '"'
    return (id, caption)

def is_path_protected(path):
    """returns True if given path is to be protected, otherwise False

    The path is not to be protected when it appears on:
    TERMS_EXCLUDE_URL_PREFIX_LIST, TERMS_EXCLUDE_URL_LIST, TERMS_EXCLUDE_URL_CONTAINS_LIST or as
    ACCEPT_TERMS_PATH"""
    protected = True
    for exclude_path in TERMS_EXCLUDE_URL_PREFIX_LIST:
        if path.startswith(exclude_path):
            protected = False
    for contains_path in TERMS_EXCLUDE_URL_CONTAINS_LIST:
        if contains_path in path:
            protected = False
    if path in TERMS_EXCLUDE_URL_LIST:
        protected = False
    if path.startswith(ACCEPT_TERMS_PATH):
        protected = False
    return protected

def terms_required(view_func):
    """This decorator checks to see if the user is logged in, and if so, if they have accepted the site terms."""
    @wraps(view_func, assigned=available_attrs(view_func))
    def _wrapped_view(request, *args, **kwargs):
        """Method to wrap the view passed in"""
        if DJANGO_VERSION <= (2, 0, 0):
            user_authenticated = request.user.is_authenticated()
        else:
            user_authenticated = request.user.is_authenticated
        if not user_authenticated or not TermsAndConditions.get_active_terms_not_agreed_to(request.user):
            return view_func(request, *args, **kwargs)
        current_path = request.path
        login_url_parts = list(urlparse(ACCEPT_TERMS_PATH))
        querystring = QueryDict(login_url_parts[4], mutable=True)
        querystring['returnTo'] = current_path
        login_url_parts[4] = querystring.urlencode(safe='/')
        return HttpResponseRedirect(urlunparse(login_url_parts))
    return _wrapped_view

def show_terms_if_not_agreed(context, field=TERMS_HTTP_PATH_FIELD):
    """Displays a modal on a current page if a user has not yet agreed to the
    given terms. If terms are not specified, the default slug is used.

    A small snippet is included into your template if a user
    who requested the view has not yet agreed the terms. The snippet takes
    care of displaying a respective modal."""
    request = context['request']
    url = urlparse(request.META[field])
    not_agreed_terms = TermsAndConditions.get_active_terms_not_agreed_to(request.user)
    if not_agreed_terms and is_path_protected(url.path):
        return {'not_agreed_terms': not_agreed_terms, 'returnTo': url.path}
    else:
        return {}

def user_accept_terms(backend, user, uid, social_user=None, *args, **kwargs):
    """Check if the user has accepted the terms and conditions after creation."""
    LOGGER.debug('user_accept_terms')
    if TermsAndConditions.get_active_terms_not_agreed_to(user):
        return redirect_to_terms_accept('/')
    else:
        return {'social_user': social_user, 'user': user}

def redirect_to_terms_accept(current_path='/', slug='default'):
    """Redirect the user to the terms and conditions accept page."""
    redirect_url_parts = list(urlparse(ACCEPT_TERMS_PATH))
    if slug != 'default':
        redirect_url_parts[2] += slug
    querystring = QueryDict(redirect_url_parts[4], mutable=True)
    querystring[TERMS_RETURNTO_PARAM] = current_path
    redirect_url_parts[4] = querystring.urlencode(safe='/')
    return HttpResponseRedirect(urlunparse(redirect_url_parts))

def user_terms_updated(sender, **kwargs):
    """Called when user terms and conditions is changed - to force cache clearing"""
