        cache.delete('tandc.not_agreed_terms_' + utandc.user.get_username())

def show_pages(parser, token):
    """Show page links.

    Usage:

    .. code-block:: html+django

        {% show_pages %}

    It is just a shortcut for:

    .. code-block:: html+django

        {% get_pages %}
        {{ pages.get_rendered }}

    You can set ``ENDLESS_PAGINATION_PAGE_LIST_CALLABLE`` in your *settings.py*
    to a callable, or to a dotted path representing a callable, used to
    customize the pages that are displayed.

    See the *__unicode__* method of ``endless_pagination.models.PageList`` for
    a detailed explanation of how the callable can be used.

    Must be called after ``{% paginate objects %}``."""
    if len(token.contents.split()) != 1:
        msg = '%r tag takes no arguments' % token.contents.split()[0]
        raise template.TemplateSyntaxError(msg)
    return ShowPagesNode()

def page_template(template, key=PAGE_LABEL):
    """Return a view dynamically switching template if the request is Ajax.

    Decorate a view that takes a *template* and *extra_context* keyword
    arguments (like generic views).
    The template is switched to *page_template* if request is ajax and
    if *querystring_key* variable passed by the request equals to *key*.
    This allows multiple Ajax paginations in the same page.
    The name of the page template is given as *page_template* in the
    extra context."""
    def decorator(view):
        @wraps(view)
        def decorated(request, *args, **kwargs):
            extra_context = kwargs.setdefault('extra_context', {})
            extra_context['page_template'] = template
            querystring_key = request.GET.get(QS_KEY, request.POST.get(QS_KEY, PAGE_LABEL))
            if request.is_ajax() and querystring_key == key:
                kwargs[TEMPLATE_VARNAME] = template
            return view(request, *args, **kwargs)
        return decorated
    return decorator

def _get_template(querystring_key, mapping):
    """Return the template corresponding to the given ``querystring_key``."""
    default = None
    try:
        template_and_keys = mapping.items()
    except AttributeError:
        template_and_keys = mapping
    for template, key in template_and_keys:
        if key is None:
            key = PAGE_LABEL
            default = template
        if key == querystring_key:
            return template
    return default

def page_templates(mapping):
    """Like the *page_template* decorator but manage multiple paginations.

    You can map multiple templates to *querystring_keys* using the *mapping*
    dict, e.g.::

        @page_templates({
            'page_contents1.html': None,
            'page_contents2.html': 'go_to_page',
        })
        def myview(request):
            ...

    When the value of the dict is None then the default *querystring_key*
    (defined in settings) is used. You can use this decorator instead of
    chaining multiple *page_template* calls."""
    def decorator(view):
        @wraps(view)
        def decorated(request, *args, **kwargs):
            extra_context = kwargs.setdefault('extra_context', {})
            querystring_key = request.GET.get(QS_KEY, request.POST.get(QS_KEY, PAGE_LABEL))
            template = _get_template(querystring_key, mapping)
            extra_context['page_template'] = template
            if request.is_ajax() and template:
                kwargs[TEMPLATE_VARNAME] = template
            return view(request, *args, **kwargs)
        return decorated
    return decorator

def get_elastic_page_numbers(current_page, num_pages):
    """Alternative callable for page listing.

    Produce an adaptive pagination, useful for big numbers of pages, by
    splitting the num_pages ranges in two parts at current_page. Each part
    will have its own S-curve."""
    if num_pages <= 10:
        return list(range(1, num_pages + 1))
    if current_page == 1:
        pages = [1]
    else:
        pages = ['first', 'previous']
        pages.extend(_make_elastic_range(1, current_page))
    if current_page != num_pages:
        pages.extend(_make_elastic_range(current_page, num_pages)[1:])
        pages.extend(['next', 'last'])
    return pages

def get_querystring_for_page(request, page_number, querystring_key, default_number=1):
    """Return a querystring pointing to *page_number*."""
    querydict = request.GET.copy()
    querydict[querystring_key] = page_number
    if page_number == default_number:
        del querydict[querystring_key]
    if 'querystring_key' in querydict:
        del querydict['querystring_key']
    if querydict:
        return '?' + querydict.urlencode()
    return ''

def load_object(path):
    """Return the Python object represented by dotted *path*."""
    i = path.rfind('.')
    module_name, object_name = (path[:i], path[i + 1:])
    try:
        module = import_module(module_name)
    except ImportError:
        raise ImproperlyConfigured('Module %r not found' % module_name)
    except ValueError:
        raise ImproperlyConfigured('Invalid module %r' % module_name)
    try:
        return getattr(module, object_name)
    except AttributeError:
        msg = 'Module %r does not define an object named %r'
        raise ImproperlyConfigured(msg % (module_name, object_name))

def derivative_colors(colors):
    """Return the names of valid color variants, given the base colors."""
    return set(['on_' + c for c in colors] + ['bright_' + c for c in colors] + ['on_bright_' + c for c in colors])

def load(filename, **kwargs):
    """Loads the given t7 file using default settings; kwargs are forwarded
    to `T7Reader`."""
    with open(filename, 'rb') as f:
        reader = T7Reader(f, **kwargs)
        return reader.read_obj()

def retire(did):
    """Retire metadata of an asset
    ---
    tags:
      - ddo
    parameters:
      - name: did
        in: path
        description: DID of the asset.
        required: true
        type: string
    responses:
      200:
        description: successfully deleted
      404:
        description: This asset DID is not in OceanDB
      500:
        description: Error"""
    try:
        if dao.get(did) is None:
            return ('This asset DID is not in OceanDB', 404)
        else:
            dao.delete(did)
            return ('Succesfully deleted', 200)
    except Exception as err:
        return (f'Some error: {str(err)}', 500)

def retire_all():
    """Retire metadata of all the assets.
    ---
    tags:
      - ddo
    responses:
      200:
        description: successfully deleted
      500:
        description: Error"""
    try:
        all_ids = [a['id'] for a in dao.get_all_assets()]
        for i in all_ids:
            dao.delete(i)
        return ('All ddo successfully deleted', 200)
    except Exception as e:
        logger.error(e)
        return ('An error was found', 500)

def parametric_line(x, y):
    """Parameters
    ----------
    x : 1D numpy array
    y : 1D numpy array"""
    if len(x) != len(y):
        raise ValueError('Arrays must be the same length')
    X = np.ones((len(x), len(x))) * np.nan
    Y = X.copy()
    for i in range(len(x)):
        X[i, :i + 1] = x[:i + 1]
        Y[i, :i + 1] = y[:i + 1]
    return (X, Y)

def by_own_time_per_call(stat):
    """Sorting by exclusive elapsed time per call in descending order."""
    return (-stat.own_time_per_call if stat.own_hits else -stat.own_time, by_deep_time_per_call(stat))

def pack_msg(method, msg, pickle_protocol=PICKLE_PROTOCOL):
    """Packs a method and message."""
    dump = io.BytesIO()
    pickle.dump(msg, dump, pickle_protocol)
    size = dump.tell()
    return struct.pack(METHOD_STRUCT_FORMAT, method) + struct.pack(SIZE_STRUCT_FORMAT, size) + dump.getvalue()

def recv(sock, size):
    """Receives exactly `size` bytes.  This function blocks the thread."""
    data = sock.recv(size, socket.MSG_WAITALL)
    if len(data) < size:
        raise socket.error(ECONNRESET, 'Connection closed')
    return data

def option_getter(type):
    """Gets an unbound method to get a configuration option as the given type.
    """
    option_getters = {None: ConfigParser.get, int: ConfigParser.getint, float: ConfigParser.getfloat, bool: ConfigParser.getboolean}
    return option_getters.get(type, option_getters[None])

def config_default(option, default=None, type=None, section=cli.name):
    """Guesses a default value of a CLI option from the configuration.

    ::

       @click.option('--locale', default=config_default('locale'))"""
    def f(option=option, default=default, type=type, section=section):
        config = read_config()
        if type is None and default is not None:
            type = builtins.type(default)
        get_option = option_getter(type)
        try:
            return get_option(config, section, option)
        except (NoOptionError, NoSectionError):
            return default
    return f

def config_flag(option, value, default=False, section=cli.name):
    """Guesses whether a CLI flag should be turned on or off from the
    configuration.  If the configuration option value is same with the given
    value, it returns ``True``.

    ::

       @click.option('--ko-kr', 'locale', is_flag=True,
                     default=config_flag('locale', 'ko_KR'))"""
    class x(object):
        def __bool__(self, option=option, value=value, default=default, section=section):
            config = read_config()
            type = builtins.type(value)
            get_option = option_getter(type)
            try:
                return get_option(config, section, option) == value
            except (NoOptionError, NoSectionError):
                return default
        __nonzero__ = __bool__
    return x()

