def pluralize(word):
    '''Return the plural form of a word.

    Examples::

        >>> pluralize("post")
        "posts"
        >>> pluralize("octopus")
        "octopi"
        >>> pluralize("sheep")
        "sheep"
        >>> pluralize("CamelOctopus")
        "CamelOctopi"'''
    if not word or word.lower() in UNCOUNTABLES:
        return word
    else:
        for rule, replacement in PLURALS:
            if re.search(rule, word):
                return re.sub(rule, replacement, word)
        return word

def singularize(word):
    '''Return the singular form of a word, the reverse of :func:`pluralize`.

    Examples::

        >>> singularize("posts")
        "post"
        >>> singularize("octopi")
        "octopus"
        >>> singularize("sheep")
        "sheep"
        >>> singularize("word")
        "word"
        >>> singularize("CamelOctopi")
        "CamelOctopus"'''
    for inflection in UNCOUNTABLES:
        if re.search('(?i)\\b(%s)\\Z' % inflection, word):
            return word
    for rule, replacement in SINGULARS:
        if re.search(rule, word):
            return re.sub(rule, replacement, word)
    return word

def _to_string(x):
    """Convert to a unicode string.

    If x is a byte string, assume it is utf-8 and decode to a Python unicode
    string. You must call this on text strings you get back from libvips."""
    if x == ffi.NULL:
        x = 'NULL'
    else:
        x = ffi.string(x)
        if isinstance(x, byte_type):
            x = x.decode('utf-8')
    return x

def _run_cmplx(fn, image):
    """Run a complex function on a non-complex image.

    The image needs to be complex, or have an even number of bands. The input
    can be int, the output is always float or double."""
    original_format = image.format
    if image.format != 'complex' and image.format != 'dpcomplex':
        if image.bands % 2 != 0:
            raise Error('not an even number of bands')
        if image.format != 'float' and image.format != 'double':
            image = image.cast('float')
        if image.format == 'double':
            new_format = 'dpcomplex'
        else:
            new_format = 'complex'
        image = image.copy(format=new_format, bands=image.bands / 2)
    image = fn(image)
    if original_format != 'complex' and original_format != 'dpcomplex':
        if image.format == 'dpcomplex':
            new_format = 'double'
        else:
            new_format = 'float'
        image = image.copy(format=new_format, bands=image.bands * 2)
    return image

def at_least_libvips(x, y):
    """Is this at least libvips x.y?"""
    major = version(0)
    minor = version(1)
    return major > x or (major == x and minor >= y)

