def parse(input):
    """parse input to datetime"""
    if isinstance(input, datetime):
        return input
    if isinstance(input, date):
        return date_to_datetime(input)
    if isinstance(input, time):
        return time_to_datetime(input)
    if isinstance(input, (int, float)):
        return timestamp_to_datetime(input)
    if isinstance(input, str):
        return string_to_data_time(input)
    return None

def string_to_data_time(d):
    """simple parse date string, such as:
    2016-5-27 21:22:20
    2016-05-27 21:22:2
    2016/05/27 21:22:2

    2016-05-27
    2016/5/27

    21:22:2"""
    if d:
        d = d.replace('/', '-')
        if ' ' in d:
            _datetime = d.split(' ')
            if len(_datetime) == 2:
                _d = _string_to_date(_datetime[0])
                _t = _string_to_time(_datetime[1])
                return _combine_date_time(_d, _t)
        elif '-' in d:
            return date_to_datetime(_string_to_date(d))
        elif ':' in d:
            return time_to_datetime(_string_to_time(d))
    return None

def format(date, now=None, locale='en'):
    """the entry method"""
    if not isinstance(date, timedelta):
        if now is None:
            now = datetime.now()
        date = parser.parse(date)
        now = parser.parse(now)
        if date is None:
            raise ParameterUnvalid('the parameter `date` should be datetime / timedelta, or datetime formated string.')
        if now is None:
            raise ParameterUnvalid('the parameter `now` should be datetime, or datetime formated string.')
        date = now - date
    diff_seconds = int(total_seconds(date))
    ago_in = 0
    if diff_seconds < 0:
        ago_in = 1
        diff_seconds *= -1
    tmp = 0
    i = 0
    while i < SEC_ARRAY_LEN:
        tmp = SEC_ARRAY[i]
        if diff_seconds >= tmp:
            i += 1
            diff_seconds /= tmp
        else:
            break
    diff_seconds = int(diff_seconds)
    i *= 2
    if diff_seconds > (i == 0 and 9 or 1):
        i += 1
    if locale is None:
        locale = DEFAULT_LOCALE
    tmp = timeago_template(locale, i, ago_in)
    if hasattr(tmp, '__call__'):
        tmp = tmp(diff_seconds)
    return '%s' in tmp and tmp % diff_seconds or tmp

def _is_parent_of(parent, child):
    """Check whether the first device is the parent of the second device."""
    if child.is_partition:
        return child.partition_slave == parent
    if child.is_toplevel:
        return child.drive == parent and child != parent
    return False

def prune_empty_node(node, seen):
    """Recursively remove empty branches and return whether this makes the node
    itself empty.

    The ``seen`` parameter is used to avoid infinite recursion due to cycles
    (you never know)."""
    if node.methods:
        return False
    if id(node) in seen:
        return True
    seen = seen | {id(node)}
    for branch in list(node.branches):
        if prune_empty_node(branch, seen):
            node.branches.remove(branch)
        else:
            return False
    return True

def samefile(a: str, b: str) -> bool:
    """Check if two pathes represent the same file."""
    try:
        return os.path.samefile(a, b)
    except OSError:
        return os.path.normpath(a) == os.path.normpath(b)

def sameuuid(a: str, b: str) -> bool:
    """Compare two UUIDs."""
    return a and b and (a.lower() == b.lower())

def setdefault(self: dict, other: dict):
    """Like .update() but values in self take priority."""
    for k, v in other.items():
        self.setdefault(k, v)

def cachedproperty(func):
    """A memoize decorator for class properties."""
    key = '_' + func.__name__
    @wraps(func)
    def get(self):
        try:
            return getattr(self, key)
        except AttributeError:
            val = func(self)
            setattr(self, key, val)
            return val
    return property(get)

def decode_ay(ay):
    """Convert binary blob from DBus queries to strings."""
    if ay is None:
        return ''
    elif isinstance(ay, str):
        return ay
    elif isinstance(ay, bytes):
        return ay.decode('utf-8')
    else:
        return bytearray(ay).rstrip(bytearray((0,))).decode('utf-8')

def format_exc(*exc_info):
    """Show exception with traceback."""
    typ, exc, tb = exc_info or sys.exc_info()
    error = traceback.format_exception(typ, exc, tb)
    return ''.join(error)

def require_Gtk(min_version=2):
    """Make sure Gtk is properly initialized.

    :raises RuntimeError: if Gtk can not be properly initialized"""
    if not _in_X:
        raise RuntimeError('Not in X session.')
    if _has_Gtk < min_version:
        raise RuntimeError('Module gi.repository.Gtk not available!')
    if _has_Gtk == 2:
        logging.getLogger(__name__).warn(_('Missing runtime dependency GTK 3. Falling back to GTK 2 for password prompt'))
    from gi.repository import Gtk
    if not Gtk.init_check(None)[0]:
        raise RuntimeError(_('X server not connected!'))
    return Gtk

def _(text, *args, **kwargs):
