def is_user_profile_valid(user_profile):
    """Determine if provided user profile is valid or not.

    Args:
      user_profile: User's profile which needs to be validated.

    Returns:
      Boolean depending upon whether profile is valid or not."""
    if not user_profile:
        return False
    if not type(user_profile) is dict:
        return False
    if UserProfile.USER_ID_KEY not in user_profile:
        return False
    if UserProfile.EXPERIMENT_BUCKET_MAP_KEY not in user_profile:
        return False
    experiment_bucket_map = user_profile.get(UserProfile.EXPERIMENT_BUCKET_MAP_KEY)
    if not type(experiment_bucket_map) is dict:
        return False
    for decision in experiment_bucket_map.values():
        if type(decision) is not dict or UserProfile.VARIATION_ID_KEY not in decision:
            return False
    return True

def is_attribute_valid(attribute_key, attribute_value):
    """Determine if given attribute is valid.

    Args:
      attribute_key: Variable which needs to be validated
      attribute_value: Variable which needs to be validated

    Returns:
      False if attribute_key is not a string
      False if attribute_value is not one of the supported attribute types
      True otherwise"""
    if not isinstance(attribute_key, string_types):
        return False
    if isinstance(attribute_value, (string_types, bool)):
        return True
    if isinstance(attribute_value, (numbers.Integral, float)):
        return is_finite_number(attribute_value)
    return False

def is_finite_number(value):
    """Validates if the given value is a number, enforces
     absolute limit of 2^53 and restricts NAN, INF, -INF.

    Args:
      value: Value to be validated.

    Returns:
      Boolean: True if value is a number and not NAN, INF, -INF or
               greater than absolute limit of 2^53 else False."""
    if not isinstance(value, (numbers.Integral, float)):
        return False
    if isinstance(value, bool):
        return False
    if isinstance(value, float):
        if math.isnan(value) or math.isinf(value):
            return False
    if abs(value) > 2 ** 53:
        return False
    return True

def hash64(key, seed=0, x64arch=True):
    """Implements 64bit murmur3 hash. Returns a tuple."""
    hash_128 = hash128(key, seed, x64arch)
    unsigned_val1 = hash_128 & 18446744073709551615
    if unsigned_val1 & 9223372036854775808 == 0:
        signed_val1 = unsigned_val1
    else:
        signed_val1 = -((unsigned_val1 ^ 18446744073709551615) + 1)
    unsigned_val2 = hash_128 >> 64 & 18446744073709551615
    if unsigned_val2 & 9223372036854775808 == 0:
        signed_val2 = unsigned_val2
    else:
        signed_val2 = -((unsigned_val2 ^ 18446744073709551615) + 1)
    return (int(signed_val1), int(signed_val2))

def evaluate(conditions, leaf_evaluator):
    """Top level method to evaluate conditions.

    Args:
      conditions: Nested array of and/or conditions, or a single leaf condition value of any type.
                  Example: ['and', '0', ['or', '1', '2']]
      leaf_evaluator: Function which will be called to evaluate leaf condition values.

    Returns:
      Boolean: Result of evaluating the conditions using the operator rules and the leaf evaluator.
      None: if conditions couldn't be evaluated."""
    if isinstance(conditions, list):
        if conditions[0] in list(EVALUATORS_BY_OPERATOR_TYPE.keys()):
            return EVALUATORS_BY_OPERATOR_TYPE[conditions[0]](conditions[1:], leaf_evaluator)
        else:
            return EVALUATORS_BY_OPERATOR_TYPE[ConditionOperatorTypes.OR](conditions, leaf_evaluator)
    leaf_condition = conditions
    return leaf_evaluator(leaf_condition)

def check_backends(title):
    """Invoke test() for all backends and fail (raise) if some dep
    is missing."""
    path = os.path.dirname(fulltext.backends.__file__)
    errs = []
    for name in os.listdir(path):
        if not name.endswith('.py'):
            continue
        if name == '__init__.py':
            continue
        mod_name = 'fulltext.backends.%s' % os.path.splitext(os.path.basename(name))[0]
        try:
            mod = __import__(mod_name, fromlist=[' '])
        except ImportError as err:
            errs.append((mod_name, str(err)))
            continue
        kw = dict(encoding='utf8', encoding_errors='strict', kwargs={})
        try:
            inst = getattr(mod, 'Backend')(**kw)
            if hasattr(inst, 'check'):
                inst.check(title=title)
        except Exception as err:
            errs.append((mod.__name__, str(err)))
    if errs:
        for mod, err in errs:
            msg = hilite('%s: %s' % (mod, err), ok=False)
            print(msg, file=sys.stderr)
        sys.exit(1)

def register_backend(mimetype, module, extensions=None):
    """Register a backend.
    `mimetype`: a mimetype string (e.g. 'text/plain')
    `module`: an import string (e.g. path.to.my.module)
    `extensions`: a list of extensions (e.g. ['txt', 'text'])"""
    if mimetype in MIMETYPE_TO_BACKENDS:
        warn('overwriting %r mimetype which was already set' % mimetype)
    MIMETYPE_TO_BACKENDS[mimetype] = module
    if extensions is None:
        try:
            ext = _MIMETYPES_TO_EXT[mimetype]
        except KeyError:
            raise KeyError("mimetypes module has no extension associated with %r mimetype; use 'extensions' arg yourself" % mimetype)
        assert ext, ext
        EXTS_TO_MIMETYPES[ext] = mimetype
    else:
        if not isinstance(extensions, (list, tuple, set, frozenset)):
            raise TypeError('invalid extensions type (got %r)' % extensions)
        for ext in set(extensions):
            ext = ext if ext.startswith('.') else '.' + ext
            assert ext, ext
            EXTS_TO_MIMETYPES[ext] = mimetype

def is_binary(f):
    """Return True if binary mode."""
    if getattr(f, 'encoding', None):
        return False
    if not PY3:
        return True
    try:
        if 'b' in getattr(f, 'mode', ''):
            return True
    except TypeError:
        import gzip
        if isinstance(f, gzip.GzipFile):
            return True
        raise
    try:
        f.seek(0, os.SEEK_CUR)
    except (AttributeError, IOError):
        return False
    byte = f.read(1)
    f.seek(-1, os.SEEK_CUR)
    return hasattr(byte, 'decode')

def handle_path(backend_inst, path, **kwargs):
    """Handle a path.

    Called by `get()` when provided a path. This function will prefer the
    backend's `handle_path()` if one is provided Otherwise, it will open the
    given path then use `handle_fobj()`."""
    if callable(getattr(backend_inst, 'handle_path', None)):
        LOGGER.debug('using handle_path')
        return backend_inst.handle_path(path)
    elif callable(getattr(backend_inst, 'handle_fobj', None)):
        LOGGER.debug('using handle_fobj')
        with open(path, 'rb') as f:
            return backend_inst.handle_fobj(f)
    else:
        raise AssertionError('Backend %s has no _get functions' % backend_inst.__name__)

def handle_fobj(backend, f, **kwargs):
    """Handle a file-like object.

    Called by `get()` when provided a file-like. This function will prefer the
    backend's `handle_fobj()` if one is provided. Otherwise, it will write the
    data to a temporary file and call `handle_path()`."""
    if not is_binary(f):
        raise AssertionError('File must be opened in binary mode.')
    if callable(getattr(backend, 'handle_fobj', None)):
        LOGGER.debug('using handle_fobj')
        return backend.handle_fobj(f)
    elif callable(getattr(backend, 'handle_path', None)):
        LOGGER.debug('using handle_path')
        LOGGER.warning('Using disk, %r backend does not provide `handle_fobj()`', backend)
        ext = ''
        if 'ext' in kwargs:
            ext = '.' + kwargs['ext']
        with fobj_to_tempfile(f, suffix=ext) as fname:
            return backend.handle_path(fname, **kwargs)
    else:
        raise AssertionError('Backend %s has no _get functions' % backend.__name__)

def backend_from_mime(mime):
    """Determine backend module object from a mime string."""
    try:
        mod_name = MIMETYPE_TO_BACKENDS[mime]
    except KeyError:
        msg = 'No handler for %r, defaulting to %r' % (mime, DEFAULT_MIME)
        if 'FULLTEXT_TESTING' in os.environ:
            warn(msg)
        else:
            LOGGER.debug(msg)
        mod_name = MIMETYPE_TO_BACKENDS[DEFAULT_MIME]
    mod = import_mod(mod_name)
    return mod

def backend_from_fname(name):
    """Determine backend module object from a file name."""
    ext = splitext(name)[1]
    try:
        mime = EXTS_TO_MIMETYPES[ext]
    except KeyError:
        try:
            f = open(name, 'rb')
        except IOError as e:
            if e.errno != errno.ENOENT:
                raise
            msg = 'No handler for %r, defaulting to %r' % (ext, DEFAULT_MIME)
            if 'FULLTEXT_TESTING' in os.environ:
                warn(msg)
            else:
                LOGGER.debug(msg)
            mod_name = MIMETYPE_TO_BACKENDS[DEFAULT_MIME]
        else:
            with f:
                return backend_from_fobj(f)
    else:
        mod_name = MIMETYPE_TO_BACKENDS[mime]
    mod = import_mod(mod_name)
    return mod

def backend_from_fobj(f):
    """Determine backend module object from a file object."""
    if magic is None:
        warn('magic lib is not installed; assuming mime type %r' % DEFAULT_MIME)
        return backend_from_mime(DEFAULT_MIME)
    else:
        offset = f.tell()
        try:
            f.seek(0)
            chunk = f.read(MAGIC_BUFFER_SIZE)
            mime = magic.from_buffer(chunk, mime=True)
            return backend_from_mime(mime)
        finally:
            f.seek(offset)

def hilite(s, ok=True, bold=False):
    """Return an highlighted version of 'string'."""
    if not term_supports_colors():
        return s
    attr = []
    if ok is None:
        pass
    elif ok:
        attr.append('32')
    else:
        attr.append('31')
    if bold:
        attr.append('1')
    return '\x1b[%sm%s\x1b[0m' % (';'.join(attr), s)

def safe_print(text, file=sys.stdout, flush=False):
    """Prints a (unicode) string to the console, encoded depending on
    the stdout/file encoding (eg. cp437 on Windows). This is to avoid
    encoding errors in case of funky path names.
    Works with Python 2 and 3."""
    if not isinstance(text, basestring):
        return print(text, file=file)
    try:
        file.write(text)
    except UnicodeEncodeError:
        bytes_string = text.encode(file.encoding, 'backslashreplace')
        if hasattr(file, 'buffer'):
            file.buffer.write(bytes_string)
        else:
            text = bytes_string.decode(file.encoding, 'strict')
            file.write(text)
    file.write('\n')

def rm(pattern):
    """Recursively remove a file or dir by pattern."""
    paths = glob.glob(pattern)
    for path in paths:
        if path.startswith('.git/'):
            continue
        if os.path.isdir(path):
            def onerror(fun, path, excinfo):
                exc = excinfo[1]
                if exc.errno != errno.ENOENT:
                    raise
            safe_print('rmdir -f %s' % path)
            shutil.rmtree(path, onerror=onerror)
        else:
            safe_print('rm %s' % path)
            os.remove(path)

