def fromlist(items, accessor=None, keys=None, dims=None, dtype=None, labels=None, npartitions=None, engine=None):
    """Load images from a list of items using the given accessor.

    Parameters
    ----------
    accessor : function
        Apply to each item from the list to yield an image.

    keys : list, optional, default=None
        An optional list of keys.

    dims : tuple, optional, default=None
        Specify a known image dimension to avoid computation.

    labels : array, optional, default = None
        Labels for records. If provided, should be one-dimensional.

    npartitions : int
        Number of partitions for computational engine."""
    if spark and isinstance(engine, spark):
        nrecords = len(items)
        if keys:
            items = zip(keys, items)
        else:
            keys = [(i,) for i in range(nrecords)]
            items = zip(keys, items)
        if not npartitions:
            npartitions = engine.defaultParallelism
        rdd = engine.parallelize(items, npartitions)
        if accessor:
            rdd = rdd.mapValues(accessor)
        return fromrdd(rdd, nrecords=nrecords, dims=dims, dtype=dtype, labels=labels, ordered=True)
    else:
        if accessor:
            items = asarray([accessor(i) for i in items])
        return fromarray(items, labels=labels)

def _binaryconfig(path, conf, dtype=None, shape=None, credentials=None):
    """Collects parameters to use for binary series loading."""
    import json
    from thunder.readers import get_file_reader, FileNotFoundError
    reader = get_file_reader(path)(credentials=credentials)
    try:
        buf = reader.read(path, filename=conf)
        params = json.loads(str(buf.decode('utf-8')))
    except FileNotFoundError:
        params = {}
    if dtype:
        params['dtype'] = dtype
    if shape:
        params['shape'] = shape
    if 'dtype' not in params.keys():
        raise ValueError('dtype not specified either in conf.json or as argument')
    if 'shape' not in params.keys():
        raise ValueError('shape not specified either in conf.json or as argument')
    return (params['shape'], params['dtype'])

def addextension(path, ext=None):
    """Helper function for handling of paths given separately passed file extensions."""
    if ext:
        if '*' in path:
            return path
        elif os.path.splitext(path)[1]:
            return path
        else:
            if not ext.startswith('.'):
                ext = '.' + ext
            if not path.endswith(ext):
                if not path.endswith(os.path.sep):
                    path += os.path.sep
                return path + '*' + ext
            else:
                return path
    else:
        return path

def select(files, start, stop):
    """Helper function for handling start and stop indices"""
    if start or stop:
        if start is None:
            start = 0
        if stop is None:
            stop = len(files)
        files = files[start:stop]
    return files

def readlocal(path, offset=None, size=-1):
    """Wrapper around open(path, 'rb') that returns the contents of the file as a string.

    Will rethrow FileNotFoundError if it receives an IOError."""
    try:
        with open(path, 'rb') as f:
            if offset:
                f.seek(offset)
            buf = f.read(size)
    except IOError as e:
        if e.errno == errno.ENOENT:
            raise FileNotFoundError(e)
        else:
            raise
    return buf

def listrecursive(path, ext=None):
    """List files recurisvely"""
    filenames = set()
    for root, dirs, files in os.walk(path):
        if ext:
            if ext == 'tif' or ext == 'tiff':
                tmp = fnmatch.filter(files, '*.' + 'tiff')
                files = tmp + fnmatch.filter(files, '*.' + 'tif')
            else:
                files = fnmatch.filter(files, '*.' + ext)
        for filename in files:
            filenames.add(os.path.join(root, filename))
    filenames = list(filenames)
    filenames.sort()
    return sorted(filenames)

def listflat(path, ext=None):
    """List files without recursion"""
    if os.path.isdir(path):
        if ext:
            if ext == 'tif' or ext == 'tiff':
                files = glob.glob(os.path.join(path, '*.tif'))
                files = files + glob.glob(os.path.join(path, '*.tiff'))
            else:
                files = glob.glob(os.path.join(path, '*.' + ext))
        else:
            files = [os.path.join(path, fname) for fname in os.listdir(path)]
    else:
        files = glob.glob(path)
    files = [fpath for fpath in files if not isinstance(fpath, list) and (not os.path.isdir(fpath))]
    return sorted(files)

def normalize_scheme(path, ext):
    """Normalize scheme for paths related to hdfs"""
    path = addextension(path, ext)
    parsed = urlparse(path)
    if parsed.scheme:
        return path
    else:
        import os
        dirname, filename = os.path.split(path)
        if not os.path.isabs(dirname):
            dirname = os.path.abspath(dirname)
            path = os.path.join(dirname, filename)
        return 'file://' + path

def check_path(path, credentials=None):
    """Check that specified output path does not already exist

    The ValueError message will suggest calling with overwrite=True;
    this function is expected to be called from the various output methods
    that accept an 'overwrite' keyword argument."""
    from thunder.readers import get_file_reader
    reader = get_file_reader(path)(credentials=credentials)
    existing = reader.list(path, directories=True)
    if existing:
        raise ValueError('Path %s appears to already exist. Specify a new directory, or call with overwrite=True to overwrite.' % path)

def gabc(elem, doc):
    """Handle gabc file inclusion and gabc code block."""
    if type(elem) == Code and 'gabc' in elem.classes:
        if doc.format == 'latex':
            if elem.identifier == '':
                label = ''
            else:
                label = '\\label{' + elem.identifier + '}'
            return latex('\n\\smallskip\n{%\n' + latexsnippet('\\gregorioscore{' + elem.text + '}', elem.attributes) + '%\n}' + label)
        else:
            infile = elem.text + ('.gabc' if '.gabc' not in elem.text else '')
            with open(infile, 'r') as doc:
                code = doc.read().split('%%\n')[1]
            return Image(png(elem.text, latexsnippet('\\gregorioscore', elem.attributes)))
    elif type(elem) == CodeBlock and 'gabc' in elem.classes:
        if doc.format == 'latex':
            if elem.identifier == '':
                label = ''
            else:
                label = '\\label{' + elem.identifier + '}'
            return latexblock('\n\\smallskip\n{%\n' + latexsnippet('\\gabcsnippet{' + elem.text + '}', elem.attributes) + '%\n}' + label)
        else:
            return Para(Image(url=png(elem.text, latexsnippet('\\gabcsnippet', elem.attributes))))

def gabc(key, value, fmt, meta):
    """Handle gabc file inclusion and gabc code block."""
    if key == 'Code':
        [[ident, classes, kvs], contents] = value
        kvs = {key: value for key, value in kvs}
        if 'gabc' in classes:
            if fmt == 'latex':
                if ident == '':
                    label = ''
                else:
                    label = '\\label{' + ident + '}'
                return latex('\n\\smallskip\n{%\n' + latexsnippet('\\gregorioscore{' + contents + '}', kvs) + '%\n}' + label)
            else:
                infile = contents + ('.gabc' if '.gabc' not in contents else '')
                with open(infile, 'r') as doc:
                    code = doc.read().split('%%\n')[1]
                return [Image(['', [], []], [], [png(contents, latexsnippet('\\gregorioscore', kvs)), ''])]
    elif key == 'CodeBlock':
        [[ident, classes, kvs], contents] = value
        kvs = {key: value for key, value in kvs}
        if 'gabc' in classes:
            if fmt == 'latex':
                if ident == '':
                    label = ''
                else:
                    label = '\\label{' + ident + '}'
                return [latexblock('\n\\smallskip\n{%\n' + latexsnippet('\\gabcsnippet{' + contents + '}', kvs) + '%\n}' + label)]
            else:
                return Para([Image(['', [], []], [], [png(contents, latexsnippet('\\gabcsnippet', kvs)), ''])])

def shell(args, wait=True, msg=None):
    """Execute the external command and get its exitcode, stdout and stderr."""
    if isinstance(args, str):
        args = shlex.split(args, posix=os.name != 'nt')
        if os.name == 'nt':
            args = [arg.replace('/', '\\') for arg in args]
    if wait:
        proc = Popen(args, stdin=PIPE, stdout=PIPE, stderr=PIPE)
        out, err = proc.communicate(input=msg)
        exitcode = proc.returncode
        if exitcode != 0:
            raise IOError(err)
        return out
    else:
        DETACHED_PROCESS = 8
        proc = Popen(args, creationflags=DETACHED_PROCESS)

def run_pandoc(text='', args=None):
    """Low level function that calls Pandoc with (optionally)
    some input text and/or arguments"""
    if args is None:
        args = []
    pandoc_path = which('pandoc')
    if pandoc_path is None or not os.path.exists(pandoc_path):
        raise OSError('Path to pandoc executable does not exists')
    proc = Popen([pandoc_path] + args, stdin=PIPE, stdout=PIPE, stderr=PIPE)
    out, err = proc.communicate(input=text.encode('utf-8'))
    exitcode = proc.returncode
    if exitcode != 0:
        raise IOError(err)
    return out.decode('utf-8')

def format_pattrs(pattrs: List['api.PrettyAttribute']) -> str:
    """Generates repr string given a list of pattrs."""
    output = []
    pattrs.sort(key=lambda x: (_FORMATTER[x.display_group].display_index, x.display_group, x.name))
    for display_group, grouped_pattrs in groupby(pattrs, lambda x: x.display_group):
        output.append(_FORMATTER[display_group].formatter(display_group, grouped_pattrs))
    return '\n'.join(output)

def get_attr_from_dict(inspected_obj: Any, attr_name: str) -> Any:
    """Ensures we get descriptor object instead of its return value.
    """
    if inspect.isclass(inspected_obj):
        obj_list = [inspected_obj] + list(inspected_obj.__mro__)
    else:
        obj_list = [inspected_obj] + list(inspected_obj.__class__.__mro__)
    for obj in obj_list:
        if hasattr(obj, '__dict__') and attr_name in obj.__dict__:
            return obj.__dict__[attr_name]
    return attr_name

def attr_category_postprocess(get_attr_category_func):
    """Unifies attr_category to a tuple, add AttrCategory.SLOT if needed."""
    @functools.wraps(get_attr_category_func)
    def wrapped(name: str, attr: Any, obj: Any) -> Tuple[AttrCategory, ...]:
        category = get_attr_category_func(name, attr, obj)
        category = list(category) if isinstance(category, tuple) else [category]
        if is_slotted_attr(obj, name):
            category.append(AttrCategory.SLOT)
        return tuple(category)
    return wrapped

def dfs_do_func_on_graph(node, func, *args, **kwargs):
    """invoke func on each node of the dr graph"""
    for _node in node.tree_iterator():
        func(_node, *args, **kwargs)

def sparse_is_desireable(lhs, rhs):
    """Examines a pair of matrices and determines if the result of their multiplication should be sparse or not."""
    return False
    if len(lhs.shape) == 1:
        return False
    else:
        lhs_rows, lhs_cols = lhs.shape
    if len(rhs.shape) == 1:
        rhs_rows = 1
        rhs_cols = rhs.size
    else:
        rhs_rows, rhs_cols = rhs.shape
    result_size = lhs_rows * rhs_cols
    if sp.issparse(lhs) and sp.issparse(rhs):
        return True
    elif sp.issparse(lhs):
        lhs_zero_rows = lhs_rows - np.unique(lhs.nonzero()[0]).size
        rhs_zero_cols = np.all(rhs == 0, axis=0).sum()
    elif sp.issparse(rhs):
        lhs_zero_rows = np.all(lhs == 0, axis=1).sum()
        rhs_zero_cols = rhs_cols - np.unique(rhs.nonzero()[1]).size
    else:
        lhs_zero_rows = np.all(lhs == 0, axis=1).sum()
        rhs_zero_cols = np.all(rhs == 0, axis=0).sum()
    num_zeros = lhs_zero_rows * rhs_cols + rhs_zero_cols * lhs_rows - lhs_zero_rows * rhs_zero_cols
    return float(num_zeros) / float(size) >= 0.5

def convert_inputs_to_sparse_if_necessary(lhs, rhs):
    """This function checks to see if a sparse output is desireable given the inputs and if so, casts the inputs to sparse in order to make it so."""
    if not sp.issparse(lhs) or not sp.issparse(rhs):
        if sparse_is_desireable(lhs, rhs):
            if not sp.issparse(lhs):
                lhs = sp.csc_matrix(lhs)
            if not sp.issparse(rhs):
                rhs = sp.csc_matrix(rhs)
    return (lhs, rhs)

def persistent_modprobe(module):
    """Load a kernel module and configure for auto-load on reboot."""
    with open('/etc/modules', 'r+') as modules:
        if module not in modules.read():
            modules.write(module + '\n')

def create_loopback(file_path):
    """Create a loopback device for a given backing file.

    :returns: str: Full path to new loopback device (eg, /dev/loop0)"""
    file_path = os.path.abspath(file_path)
    check_call(['losetup', '--find', file_path])
    for d, f in six.iteritems(loopback_devices()):
        if f == file_path:
            return d

def ensure_loopback_device(path, size):
    """Ensure a loopback device exists for a given backing file path and size.
    If it a loopback device is not mapped to file, a new one will be created.

    TODO: Confirm size of found loopback device.

    :returns: str: Full path to the ensured loopback device (eg, /dev/loop0)"""
    for d, f in six.iteritems(loopback_devices()):
        if f == path:
            return d
    if not os.path.exists(path):
        cmd = ['truncate', '--size', size, path]
        check_call(cmd)
    return create_loopback(path)

def relation_set(relation_id=None, relation_settings=None, **kwargs):
    """Attempt to use leader-set if supported in the current version of Juju,
    otherwise falls back on relation-set.

    Note that we only attempt to use leader-set if the provided relation_id is
    a peer relation id or no relation id is provided (in which case we assume
    we are within the peer relation context)."""
    try:
        if relation_id in relation_ids('cluster'):
            return leader_set(settings=relation_settings, **kwargs)
        else:
            raise NotImplementedError
    except NotImplementedError:
        return _relation_set(relation_id=relation_id, relation_settings=relation_settings, **kwargs)

def relation_get(attribute=None, unit=None, rid=None):
    """Attempt to use leader-get if supported in the current version of Juju,
    otherwise falls back on relation-get.

    Note that we only attempt to use leader-get if the provided rid is a peer
    relation id or no relation id is provided (in which case we assume we are
    within the peer relation context)."""
    try:
        if rid in relation_ids('cluster'):
            return leader_get(attribute, rid)
        else:
            raise NotImplementedError
    except NotImplementedError:
        return _relation_get(attribute=attribute, rid=rid, unit=unit)

def peer_retrieve(key, relation_name='cluster'):
    """Retrieve a named key from peer relation `relation_name`."""
    cluster_rels = relation_ids(relation_name)
    if len(cluster_rels) > 0:
        cluster_rid = cluster_rels[0]
        return relation_get(attribute=key, rid=cluster_rid, unit=local_unit())
    else:
        raise ValueError('Unable to detectpeer relation {}'.format(relation_name))

def peer_retrieve_by_prefix(prefix, relation_name='cluster', delimiter='_', inc_list=None, exc_list=None):
    """Retrieve k/v pairs given a prefix and filter using {inc,exc}_list"""
    inc_list = inc_list if inc_list else []
    exc_list = exc_list if exc_list else []
    peerdb_settings = peer_retrieve('-', relation_name=relation_name)
    matched = {}
    if peerdb_settings is None:
        return matched
    for k, v in peerdb_settings.items():
        full_prefix = prefix + delimiter
        if k.startswith(full_prefix):
            new_key = k.replace(full_prefix, '')
            if new_key in exc_list:
                continue
            if new_key in inc_list or len(inc_list) == 0:
                matched[new_key] = v
    return matched

def peer_store(key, value, relation_name='cluster'):
    """Store the key/value pair on the named peer relation `relation_name`."""
    cluster_rels = relation_ids(relation_name)
    if len(cluster_rels) > 0:
        cluster_rid = cluster_rels[0]
        relation_set(relation_id=cluster_rid, relation_settings={key: value})
    else:
        raise ValueError('Unable to detect peer relation {}'.format(relation_name))

def peer_echo(includes=None, force=False):
    """Echo filtered attributes back onto the same relation for storage.

    This is a requirement to use the peerstorage module - it needs to be called
    from the peer relation's changed hook.

    If Juju leader support exists this will be a noop unless force is True."""
    try:
        is_leader()
    except NotImplementedError:
        pass
    else:
        if not force:
            return
    relation_get = _relation_get
    relation_set = _relation_set
    rdata = relation_get()
    echo_data = {}
    if includes is None:
        echo_data = rdata.copy()
        for ex in ['private-address', 'public-address']:
            if ex in echo_data:
                echo_data.pop(ex)
    else:
        for attribute, value in six.iteritems(rdata):
            for include in includes:
                if include in attribute:
                    echo_data[attribute] = value
    if len(echo_data) > 0:
        relation_set(relation_settings=echo_data)

def peer_store_and_set(relation_id=None, peer_relation_name='cluster', peer_store_fatal=False, relation_settings=None, delimiter='_', **kwargs):
    """Store passed-in arguments both in argument relation and in peer storage.

    It functions like doing relation_set() and peer_store() at the same time,
    with the same data.

    @param relation_id: the id of the relation to store the data on. Defaults
                        to the current relation.
    @param peer_store_fatal: Set to True, the function will raise an exception
                             should the peer sotrage not be avialable."""
    relation_settings = relation_settings if relation_settings else {}
    relation_set(relation_id=relation_id, relation_settings=relation_settings, **kwargs)
    if is_relation_made(peer_relation_name):
        for key, value in six.iteritems(dict(list(kwargs.items()) + list(relation_settings.items()))):
            key_prefix = relation_id or current_relation_id()
            peer_store(key_prefix + delimiter + key, value, relation_name=peer_relation_name)
    elif peer_store_fatal:
        raise ValueError('Unable to detect peer relation {}'.format(peer_relation_name))

def lsb_release():
    """Return /etc/os-release in a dict."""
    d = {}
    with open('/etc/os-release', 'r') as lsb:
        for l in lsb:
            s = l.split('=')
            if len(s) != 2:
                continue
            d[s[0].strip()] = s[1].strip()
    return d

def is_elected_leader(resource):
    """Returns True if the charm executing this is the elected cluster leader.

    It relies on two mechanisms to determine leadership:
        1. If juju is sufficiently new and leadership election is supported,
        the is_leader command will be used.
        2. If the charm is part of a corosync cluster, call corosync to
        determine leadership.
        3. If the charm is not part of a corosync cluster, the leader is
        determined as being "the alive unit with the lowest unit numer". In
        other words, the oldest surviving unit."""
    try:
        return juju_is_leader()
    except NotImplementedError:
        log('Juju leadership election feature not enabled, using fallback support', level=WARNING)
    if is_clustered():
        if not is_crm_leader(resource):
            log('Deferring action to CRM leader.', level=INFO)
            return False
    else:
        peers = peer_units()
        if peers and (not oldest_peer(peers)):
            log('Deferring action to oldest service unit.', level=INFO)
            return False
    return True

def is_crm_dc():
    """Determine leadership by querying the pacemaker Designated Controller"""
    cmd = ['crm', 'status']
    try:
        status = subprocess.check_output(cmd, stderr=subprocess.STDOUT)
        if not isinstance(status, six.text_type):
            status = six.text_type(status, 'utf-8')
    except subprocess.CalledProcessError as ex:
        raise CRMDCNotFound(str(ex))
    current_dc = ''
    for line in status.split('\n'):
        if line.startswith('Current DC'):
            current_dc = line.split(':')[1].split()[0]
    if current_dc == get_unit_hostname():
        return True
    elif current_dc == 'NONE':
        raise CRMDCNotFound('Current DC: NONE')
    return False

def is_crm_leader(resource, retry=False):
    """Returns True if the charm calling this is the elected corosync leader,
    as returned by calling the external "crm" command.

    We allow this operation to be retried to avoid the possibility of getting a
    false negative. See LP #1396246 for more info."""
    if resource == DC_RESOURCE_NAME:
        return is_crm_dc()
    cmd = ['crm', 'resource', 'show', resource]
    try:
        status = subprocess.check_output(cmd, stderr=subprocess.STDOUT)
        if not isinstance(status, six.text_type):
            status = six.text_type(status, 'utf-8')
    except subprocess.CalledProcessError:
        status = None
    if status and get_unit_hostname() in status:
        return True
    if status and 'resource %s is NOT running' % resource in status:
        raise CRMResourceNotFound('CRM resource %s not found' % resource)
    return False

def peer_ips(peer_relation='cluster', addr_key='private-address'):
    """Return a dict of peers and their private-address"""
    peers = {}
    for r_id in relation_ids(peer_relation):
        for unit in relation_list(r_id):
            peers[unit] = relation_get(addr_key, rid=r_id, unit=unit)
    return peers

def oldest_peer(peers):
    """Determines who the oldest peer is by comparing unit numbers."""
    local_unit_no = int(os.getenv('JUJU_UNIT_NAME').split('/')[1])
    for peer in peers:
        remote_unit_no = int(peer.split('/')[1])
        if remote_unit_no < local_unit_no:
            return False
    return True

def https():
    """Determines whether enough data has been provided in configuration
    or relation data to configure HTTPS
    .
    returns: boolean"""
    use_https = config_get('use-https')
    if use_https and bool_from_string(use_https):
        return True
    if config_get('ssl_cert') and config_get('ssl_key'):
        return True
    for r_id in relation_ids('certificates'):
        for unit in relation_list(r_id):
            ca = relation_get('ca', rid=r_id, unit=unit)
            if ca:
                return True
    for r_id in relation_ids('identity-service'):
        for unit in relation_list(r_id):
            rel_state = [relation_get('https_keystone', rid=r_id, unit=unit), relation_get('ca_cert', rid=r_id, unit=unit)]
            if None not in rel_state and '' not in rel_state:
                return True
    return False

def get_hacluster_config(exclude_keys=None):
    """Obtains all relevant configuration from charm configuration required
    for initiating a relation to hacluster:

        ha-bindiface, ha-mcastport, vip, os-internal-hostname,
        os-admin-hostname, os-public-hostname, os-access-hostname

    param: exclude_keys: list of setting key(s) to be excluded.
    returns: dict: A dict containing settings keyed by setting name.
    raises: HAIncompleteConfig if settings are missing or incorrect."""
    settings = ['ha-bindiface', 'ha-mcastport', 'vip', 'os-internal-hostname', 'os-admin-hostname', 'os-public-hostname', 'os-access-hostname']
    conf = {}
    for setting in settings:
        if exclude_keys and setting in exclude_keys:
            continue
        conf[setting] = config_get(setting)
    if not valid_hacluster_config():
        raise HAIncorrectConfig('Insufficient or incorrect config data to configure hacluster.')
    return conf

def canonical_url(configs, vip_setting='vip'):
    """Returns the correct HTTP URL to this host given the state of HTTPS
    configuration and hacluster.

    :configs    : OSTemplateRenderer: A config tempating object to inspect for
                                      a complete https context.

    :vip_setting:                str: Setting in charm config that specifies
                                      VIP address."""
    scheme = 'http'
    if 'https' in configs.complete_contexts():
        scheme = 'https'
    if is_clustered():
        addr = config_get(vip_setting)
    else:
        addr = unit_get('private-address')
    return '%s://%s' % (scheme, addr)

def install(packages, options=None, fatal=False):
    """Install one or more packages."""
    cmd = ['yum', '--assumeyes']
    if options is not None:
        cmd.extend(options)
    cmd.append('install')
    if isinstance(packages, six.string_types):
        cmd.append(packages)
    else:
        cmd.extend(packages)
    log('Installing {} with options: {}'.format(packages, options))
    _run_yum_command(cmd, fatal)

def purge(packages, fatal=False):
    """Purge one or more packages."""
    cmd = ['yum', '--assumeyes', 'remove']
    if isinstance(packages, six.string_types):
        cmd.append(packages)
    else:
        cmd.extend(packages)
    log('Purging {}'.format(packages))
    _run_yum_command(cmd, fatal)

def yum_search(packages):
    """Search for a package."""
    output = {}
    cmd = ['yum', 'search']
    if isinstance(packages, six.string_types):
        cmd.append(packages)
    else:
        cmd.extend(packages)
    log('Searching for {}'.format(packages))
    result = subprocess.check_output(cmd)
    for package in list(packages):
        output[package] = package in result
    return output

def _run_yum_command(cmd, fatal=False):
    """Run an YUM command.

    Checks the output and retry if the fatal flag is set to True.

    :param: cmd: str: The yum command to run.
    :param: fatal: bool: Whether the command's output should be checked and
        retried."""
    env = os.environ.copy()
    if fatal:
        retry_count = 0
        result = None
        while result is None or result == YUM_NO_LOCK:
            try:
                result = subprocess.check_call(cmd, env=env)
            except subprocess.CalledProcessError as e:
                retry_count = retry_count + 1
                if retry_count > YUM_NO_LOCK_RETRY_COUNT:
                    raise
                result = e.returncode
                log("Couldn't acquire YUM lock. Will retry in {} seconds.".format(YUM_NO_LOCK_RETRY_DELAY))
                time.sleep(YUM_NO_LOCK_RETRY_DELAY)
    else:
        subprocess.call(cmd, env=env)

def describe_arguments(func):
    """Analyze a function's signature and return a data structure suitable for
    passing in as arguments to an argparse parser's add_argument() method."""
    argspec = inspect.getargspec(func)
    if argspec.defaults:
        positional_args = argspec.args[:-len(argspec.defaults)]
        keyword_names = argspec.args[-len(argspec.defaults):]
        for arg, default in zip(keyword_names, argspec.defaults):
            yield (('--{}'.format(arg),), {'default': default})
    else:
        positional_args = argspec.args
    for arg in positional_args:
        yield ((arg,), {})
    if argspec.varargs:
        yield ((argspec.varargs,), {'nargs': '*'})

def ssh_authorized_peers(peer_interface, user, group=None, ensure_local_user=False):
    """Main setup function, should be called from both peer -changed and -joined
    hooks with the same parameters."""
    if ensure_local_user:
        ensure_user(user, group)
    priv_key, pub_key = get_keypair(user)
    hook = hook_name()
    if hook == '%s-relation-joined' % peer_interface:
        relation_set(ssh_pub_key=pub_key)
    elif hook == '%s-relation-changed' % peer_interface or hook == '%s-relation-departed' % peer_interface:
        hosts = []
        keys = []
        for r_id in relation_ids(peer_interface):
            for unit in related_units(r_id):
                ssh_pub_key = relation_get('ssh_pub_key', rid=r_id, unit=unit)
                priv_addr = relation_get('private-address', rid=r_id, unit=unit)
                if ssh_pub_key:
                    keys.append(ssh_pub_key)
                    hosts.append(priv_addr)
                else:
                    log('ssh_authorized_peers(): ssh_pub_key missing for unit %s, skipping.' % unit)
        write_authorized_keys(user, keys)
        write_known_hosts(user, hosts)
        authed_hosts = ':'.join(hosts)
        relation_set(ssh_authorized_hosts=authed_hosts)

def collect_authed_hosts(peer_interface):
    """Iterate through the units on peer interface to find all that
    have the calling host in its authorized hosts list"""
    hosts = []
    for r_id in relation_ids(peer_interface) or []:
        for unit in related_units(r_id):
            private_addr = relation_get('private-address', rid=r_id, unit=unit)
            authed_hosts = relation_get('ssh_authorized_hosts', rid=r_id, unit=unit)
            if not authed_hosts:
                log('Peer %s has not authorized *any* hosts yet, skipping.' % unit, level=INFO)
                continue
            if unit_private_ip() in authed_hosts.split(':'):
                hosts.append(private_addr)
            else:
                log('Peer %s has not authorized *this* host yet, skipping.' % unit, level=INFO)
    return hosts

def sync_path_to_host(path, host, user, verbose=False, cmd=None, gid=None, fatal=False):
    """Sync path to an specific peer host

    Propagates exception if operation fails and fatal=True."""
    cmd = cmd or copy(BASE_CMD)
    if not verbose:
        cmd.append('-silent')
    if path.endswith('/'):
        path = path[:len(path) - 1]
    cmd = cmd + [path, 'ssh://%s@%s/%s' % (user, host, path)]
    try:
        log('Syncing local path %s to %s@%s:%s' % (path, user, host, path))
        run_as_user(user, cmd, gid)
    except Exception:
        log('Error syncing remote files')
        if fatal:
            raise

def sync_to_peer(host, user, paths=None, verbose=False, cmd=None, gid=None, fatal=False):
    """Sync paths to an specific peer host

    Propagates exception if any operation fails and fatal=True."""
    if paths:
        for p in paths:
            sync_path_to_host(p, host, user, verbose, cmd, gid, fatal)

def sync_to_peers(peer_interface, user, paths=None, verbose=False, cmd=None, gid=None, fatal=False):
    """Sync all hosts to an specific path

    The type of group is integer, it allows user has permissions to
    operate a directory have a different group id with the user id.

    Propagates exception if any operation fails and fatal=True."""
    if paths:
        for host in collect_authed_hosts(peer_interface):
            sync_to_peer(host, user, paths, verbose, cmd, gid, fatal)

def pip_execute(*args, **kwargs):
    """Overriden pip_execute() to stop sys.path being changed.

    The act of importing main from the pip module seems to cause add wheels
    from the /usr/share/python-wheels which are installed by various tools.
    This function ensures that sys.path remains the same after the call is
    executed."""
    try:
        _path = sys.path
        try:
            from pip import main as _pip_execute
        except ImportError:
            apt_update()
            if six.PY2:
                apt_install('python-pip')
            else:
                apt_install('python3-pip')
            from pip import main as _pip_execute
        _pip_execute(*args, **kwargs)
    finally:
        sys.path = _path

def parse_options(given, available):
    """Given a set of options, check if available"""
    for key, value in sorted(given.items()):
        if not value:
            continue
        if key in available:
            yield '--{0}={1}'.format(key, value)

def pip_install(package, fatal=False, upgrade=False, venv=None, constraints=None, **options):
    """Install a python package"""
    if venv:
        venv_python = os.path.join(venv, 'bin/pip')
        command = [venv_python, 'install']
    else:
        command = ['install']
    available_options = ('proxy', 'src', 'log', 'index-url')
    for option in parse_options(options, available_options):
        command.append(option)
    if upgrade:
        command.append('--upgrade')
    if constraints:
        command.extend(['-c', constraints])
    if isinstance(package, list):
        command.extend(package)
    else:
        command.append(package)
    log('Installing {} package with options: {}'.format(package, command))
    if venv:
        subprocess.check_call(command)
    else:
        pip_execute(command)

def pip_uninstall(package, **options):
    """Uninstall a python package"""
    command = ['uninstall', '-q', '-y']
    available_options = ('proxy', 'log')
    for option in parse_options(options, available_options):
        command.append(option)
    if isinstance(package, list):
        command.extend(package)
    else:
        command.append(package)
    log('Uninstalling {} package with options: {}'.format(package, command))
    pip_execute(command)

def pip_create_virtualenv(path=None):
    """Create an isolated Python environment."""
    if six.PY2:
        apt_install('python-virtualenv')
    else:
        apt_install('python3-virtualenv')
    if path:
        venv_path = path
    else:
        venv_path = os.path.join(charm_dir(), 'venv')
    if not os.path.exists(venv_path):
        subprocess.check_call(['virtualenv', venv_path])

def configure_sources(update=False, sources_var='install_sources', keys_var='install_keys'):
    """Configure multiple sources from charm configuration.

    The lists are encoded as yaml fragments in the configuration.
    The fragment needs to be included as a string. Sources and their
    corresponding keys are of the types supported by add_source().

    Example config:
        install_sources: |
          - "ppa:foo"
          - "http://example.com/repo precise main"
        install_keys: |
          - null
          - "a1b2c3d4"

    Note that 'null' (a.k.a. None) should not be quoted."""
    sources = safe_load((config(sources_var) or '').strip()) or []
    keys = safe_load((config(keys_var) or '').strip()) or None
    if isinstance(sources, six.string_types):
        sources = [sources]
    if keys is None:
        for source in sources:
            add_source(source, None)
    else:
        if isinstance(keys, six.string_types):
            keys = [keys]
        if len(sources) != len(keys):
            raise SourceConfigError('Install sources and keys lists are different lengths')
        for source, key in zip(sources, keys):
            add_source(source, key)
    if update:
        _fetch_update(fatal=True)

def is_block_device(path):
    """Confirm device at path is a valid block device node.

    :returns: boolean: True if path is a block device, False if not."""
    if not os.path.exists(path):
        return False
    return S_ISBLK(os.stat(path).st_mode)

def is_device_mounted(device):
    """Given a device path, return True if that device is mounted, and False
    if it isn't.

    :param device: str: Full path of the device to check.
    :returns: boolean: True if the path represents a mounted device, False if
        it doesn't."""
    try:
        out = check_output(['lsblk', '-P', device]).decode('UTF-8')
    except Exception:
        return False
    return bool(re.search('MOUNTPOINT=".+"', out))

def wait_for_machine(num_machines=1, timeout=300):
    """Wait `timeout` seconds for `num_machines` machines to come up.

    This wait_for... function can be called by other wait_for functions
    whose timeouts might be too short in situations where only a bare
    Juju setup has been bootstrapped.

    :return: A tuple of (num_machines, time_taken). This is used for
             testing."""
    if get_machine_data()[0]['dns-name'] == 'localhost':
        return (1, 0)
    start_time = time.time()
    while True:
        machine_data = get_machine_data()
        non_zookeeper_machines = [machine_data[key] for key in list(machine_data.keys())[1:]]
        if len(non_zookeeper_machines) >= num_machines:
            all_machines_running = True
            for machine in non_zookeeper_machines:
                if machine.get('instance-state') != 'running':
                    all_machines_running = False
                    break
            if all_machines_running:
                break
        if time.time() - start_time >= timeout:
            raise RuntimeError('timeout waiting for service to start')
        time.sleep(SLEEP_AMOUNT)
    return (num_machines, time.time() - start_time)

def wait_for_unit(service_name, timeout=480):
    """Wait `timeout` seconds for a given service name to come up."""
    wait_for_machine(num_machines=1)
    start_time = time.time()
    while True:
        state = unit_info(service_name, 'agent-state')
        if 'error' in state or state == 'started':
            break
        if time.time() - start_time >= timeout:
            raise RuntimeError('timeout waiting for service to start')
        time.sleep(SLEEP_AMOUNT)
    if state != 'started':
        raise RuntimeError('unit did not start, agent-state: ' + state)

def wait_for_relation(service_name, relation_name, timeout=120):
    """Wait `timeout` seconds for a given relation to come up."""
    start_time = time.time()
    while True:
        relation = unit_info(service_name, 'relations').get(relation_name)
        if relation is not None and relation['state'] == 'up':
            break
        if time.time() - start_time >= timeout:
            raise RuntimeError('timeout waiting for relation to be up')
        time.sleep(SLEEP_AMOUNT)

def service_available(service_name):
    """Determine whether a system service is available"""
    try:
        subprocess.check_output(['service', service_name, 'status'], stderr=subprocess.STDOUT).decode('UTF-8')
    except subprocess.CalledProcessError as e:
        return b'unrecognized service' not in e.output
    else:
        return True

def lsb_release():
    """Return /etc/lsb-release in a dict"""
    d = {}
    with open('/etc/lsb-release', 'r') as lsb:
        for l in lsb:
            k, v = l.split('=')
            d[k.strip()] = v.strip()
    return d

def get_mon_map(service):
    """Returns the current monitor map.
    :param service: six.string_types. The Ceph user name to run the command under
    :return: json string. :raise: ValueError if the monmap fails to parse.
      Also raises CalledProcessError if our ceph command fails"""
    try:
        mon_status = check_output(['ceph', '--id', service, 'mon_status', '--format=json'])
        if six.PY3:
            mon_status = mon_status.decode('UTF-8')
        try:
            return json.loads(mon_status)
        except ValueError as v:
            log('Unable to parse mon_status json: {}. Error: {}'.format(mon_status, str(v)))
            raise
    except CalledProcessError as e:
        log('mon_status command failed with message: {}'.format(str(e)))
        raise

def hash_monitor_names(service):
    """Uses the get_mon_map() function to get information about the monitor
    cluster.
    Hash the name of each monitor.  Return a sorted list of monitor hashes
    in an ascending order.
    :param service: six.string_types. The Ceph user name to run the command under
    :rtype : dict.   json dict of monitor name, ip address and rank
    example: {
        'name': 'ip-172-31-13-165',
        'rank': 0,
        'addr': '172.31.13.165:6789/0'}"""
    try:
        hash_list = []
        monitor_list = get_mon_map(service=service)
        if monitor_list['monmap']['mons']:
            for mon in monitor_list['monmap']['mons']:
                hash_list.append(hashlib.sha224(mon['name'].encode('utf-8')).hexdigest())
            return sorted(hash_list)
        else:
            return None
    except (ValueError, CalledProcessError):
        raise

def monitor_key_delete(service, key):
    """Delete a key and value pair from the monitor cluster
    :param service: six.string_types. The Ceph user name to run the command under
    Deletes a key value pair on the monitor cluster.
    :param key: six.string_types.  The key to delete."""
    try:
        check_output(['ceph', '--id', service, 'config-key', 'del', str(key)])
    except CalledProcessError as e:
        log('Monitor config-key put failed with message: {}'.format(e.output))
        raise

def monitor_key_exists(service, key):
    """Searches for the existence of a key in the monitor cluster.
    :param service: six.string_types. The Ceph user name to run the command under
    :param key: six.string_types.  The key to search for
    :return: Returns True if the key exists, False if not and raises an
     exception if an unknown error occurs. :raise: CalledProcessError if
     an unknown error occurs"""
    try:
        check_call(['ceph', '--id', service, 'config-key', 'exists', str(key)])
        return True
    except CalledProcessError as e:
        if e.returncode == errno.ENOENT:
            return False
        else:
            log('Unknown error from ceph config-get exists: {} {}'.format(e.returncode, e.output))
            raise

