def ensure_ceph_keyring(service, user=None, group=None, relation='ceph', key=None):
    """Ensures a ceph keyring is created for a named service and optionally
    ensures user and group ownership.

    @returns boolean: Flag to indicate whether a key was successfully written
                      to disk based on either relation data or a supplied key"""
    if not key:
        for rid in relation_ids(relation):
            for unit in related_units(rid):
                key = relation_get('key', rid=rid, unit=unit)
                if key:
                    break
    if not key:
        return False
    add_key(service=service, key=key)
    keyring = _keyring_path(service)
    if user and group:
        check_call(['chown', '%s.%s' % (user, group), keyring])
    return True

def get_previous_request(rid):
    """Return the last ceph broker request sent on a given relation

    @param rid: Relation id to query for request"""
    request = None
    broker_req = relation_get(attribute='broker_req', rid=rid, unit=local_unit())
    if broker_req:
        request_data = json.loads(broker_req)
        request = CephBrokerRq(api_version=request_data['api-version'], request_id=request_data['request-id'])
        request.set_ops(request_data['ops'])
    return request

def get_request_states(request, relation='ceph'):
    """Return a dict of requests per relation id with their corresponding
       completion state.

    This allows a charm, which has a request for ceph, to see whether there is
    an equivalent request already being processed and if so what state that
    request is in.

    @param request: A CephBrokerRq object"""
    complete = []
    requests = {}
    for rid in relation_ids(relation):
        complete = False
        previous_request = get_previous_request(rid)
        if request == previous_request:
            sent = True
            complete = is_request_complete_for_rid(previous_request, rid)
        else:
            sent = False
            complete = False
        requests[rid] = {'sent': sent, 'complete': complete}
    return requests

def is_request_sent(request, relation='ceph'):
    """Check to see if a functionally equivalent request has already been sent

    Returns True if a similair request has been sent

    @param request: A CephBrokerRq object"""
    states = get_request_states(request, relation=relation)
    for rid in states.keys():
        if not states[rid]['sent']:
            return False
    return True

def is_request_complete_for_rid(request, rid):
    """Check if a given request has been completed on the given relation

    @param request: A CephBrokerRq object
    @param rid: Relation ID"""
    broker_key = get_broker_rsp_key()
    for unit in related_units(rid):
        rdata = relation_get(rid=rid, unit=unit)
        if rdata.get(broker_key):
            rsp = CephBrokerRsp(rdata.get(broker_key))
            if rsp.request_id == request.request_id:
                if not rsp.exit_code:
                    return True
        elif rdata.get('broker_rsp'):
            request_data = json.loads(rdata['broker_rsp'])
            if request_data.get('request-id'):
                log('Ignoring legacy broker_rsp without unit key as remote service supports unit specific replies', level=DEBUG)
            else:
                log('Using legacy broker_rsp as remote service does not supports unit specific replies', level=DEBUG)
                rsp = CephBrokerRsp(rdata['broker_rsp'])
                if not rsp.exit_code:
                    return True
    return False

def send_request_if_needed(request, relation='ceph'):
    """Send broker request if an equivalent request has not already been sent

    @param request: A CephBrokerRq object"""
    if is_request_sent(request, relation=relation):
        log('Request already sent but not complete, not sending new request', level=DEBUG)
    else:
        for rid in relation_ids(relation):
            log('Sending request {}'.format(request.request_id), level=DEBUG)
            relation_set(relation_id=rid, broker_req=request.request)

def is_broker_action_done(action, rid=None, unit=None):
    """Check whether broker action has completed yet.

    @param action: name of action to be performed
    @returns True if action complete otherwise False"""
    rdata = relation_get(rid, unit) or {}
    broker_rsp = rdata.get(get_broker_rsp_key())
    if not broker_rsp:
        return False
    rsp = CephBrokerRsp(broker_rsp)
    unit_name = local_unit().partition('/')[2]
    key = 'unit_{}_ceph_broker_action.{}'.format(unit_name, action)
    kvstore = kv()
    val = kvstore.get(key=key)
    if val and val == rsp.request_id:
        return True
    return False

def mark_broker_action_done(action, rid=None, unit=None):
    """Mark action as having been completed.

    @param action: name of action to be performed
    @returns None"""
    rdata = relation_get(rid, unit) or {}
    broker_rsp = rdata.get(get_broker_rsp_key())
    if not broker_rsp:
        return
    rsp = CephBrokerRsp(broker_rsp)
    unit_name = local_unit().partition('/')[2]
    key = 'unit_{}_ceph_broker_action.{}'.format(unit_name, action)
    kvstore = kv()
    kvstore.set(key=key, value=rsp.request_id)
    kvstore.flush()

def get_nagios_unit_name(relation_name='nrpe-external-master'):
    """Return the nagios unit name prepended with host_context if needed

    :param str relation_name: Name of relation nrpe sub joined to"""
    host_context = get_nagios_hostcontext(relation_name)
    if host_context:
        unit = '%s:%s' % (host_context, local_unit())
    else:
        unit = local_unit()
    return unit

def copy_nrpe_checks(nrpe_files_dir=None):
    """Copy the nrpe checks into place"""
    NAGIOS_PLUGINS = '/usr/local/lib/nagios/plugins'
    if nrpe_files_dir is None:
        for segment in ['.', 'hooks']:
            nrpe_files_dir = os.path.abspath(os.path.join(os.getenv('CHARM_DIR'), segment, 'charmhelpers', 'contrib', 'openstack', 'files'))
            if os.path.isdir(nrpe_files_dir):
                break
        else:
            raise RuntimeError("Couldn't find charmhelpers directory")
    if not os.path.exists(NAGIOS_PLUGINS):
        os.makedirs(NAGIOS_PLUGINS)
    for fname in glob.glob(os.path.join(nrpe_files_dir, 'check_*')):
        if os.path.isfile(fname):
            shutil.copy2(fname, os.path.join(NAGIOS_PLUGINS, os.path.basename(fname)))

def retry_on_exception(num_retries, base_delay=0, exc_type=Exception):
    """If the decorated function raises exception exc_type, allow num_retries
    retry attempts before raise the exception."""
    def _retry_on_exception_inner_1(f):
        def _retry_on_exception_inner_2(*args, **kwargs):
            retries = num_retries
            multiplier = 1
            while True:
                try:
                    return f(*args, **kwargs)
                except exc_type:
                    if not retries:
                        raise
                delay = base_delay * multiplier
                multiplier += 1
                log("Retrying '%s' %d more times (delay=%s)" % (f.__name__, retries, delay), level=INFO)
                retries -= 1
                if delay:
                    time.sleep(delay)
        return _retry_on_exception_inner_2
    return _retry_on_exception_inner_1

def snap_remove(packages, *flags):
    """Remove a snap package.

    :param packages: String or List String package name
    :param flags: List String flags to pass to remove command
    :return: Integer return code from snap"""
    if type(packages) is not list:
        packages = [packages]
    flags = list(flags)
    message = 'Removing snap(s) "%s"' % ', '.join(packages)
    if flags:
        message += ' with options "%s"' % ', '.join(flags)
    log(message, level='INFO')
    return _snap_exec(['remove'] + flags + packages)

def persistent_modprobe(module):
    """Load a kernel module and configure for auto-load on reboot."""
    if not os.path.exists('/etc/rc.modules'):
        open('/etc/rc.modules', 'a')
        os.chmod('/etc/rc.modules', 111)
    with open('/etc/rc.modules', 'r+') as modules:
        if module not in modules.read():
            modules.write('modprobe %s\n' % module)

def splituser(host):
    """urllib.splituser(), but six's support of this seems broken"""
    _userprog = re.compile('^(.*)@(.*)$')
    match = _userprog.match(host)
    if match:
        return match.group(1, 2)
    return (None, host)

def splitpasswd(user):
    """urllib.splitpasswd(), but six's support of this is missing"""
    _passwdprog = re.compile('^([^:]*):(.*)$', re.S)
    match = _passwdprog.match(user)
    if match:
        return match.group(1, 2)
    return (user, None)

def set_trace(addr=DEFAULT_ADDR, port=DEFAULT_PORT):
    """Set a trace point using the remote debugger"""
    atexit.register(close_port, port)
    try:
        log('Starting a remote python debugger session on %s:%s' % (addr, port))
        open_port(port)
        debugger = Rpdb(addr=addr, port=port)
        debugger.set_trace(sys._getframe().f_back)
    except Exception:
        _error('Cannot start a remote debug session on %s:%s' % (addr, port))

def device_info(device):
    """Returns a DeviceInfo object with the current device settings"""
    status = subprocess.check_output(['ibstat', device, '-s']).splitlines()
    regexes = {'CA type: (.*)': 'device_type', 'Number of ports: (.*)': 'num_ports', 'Firmware version: (.*)': 'fw_ver', 'Hardware version: (.*)': 'hw_ver', 'Node GUID: (.*)': 'node_guid', 'System image GUID: (.*)': 'sys_guid'}
    device = DeviceInfo()
    for line in status:
        for expression, key in regexes.items():
            matches = re.search(expression, line)
            if matches:
                setattr(device, key, matches.group(1))
    return device

def ipoib_interfaces():
    """Return a list of IPOIB capable ethernet interfaces"""
    interfaces = []
    for interface in network_interfaces():
        try:
            driver = re.search('^driver: (.+)$', subprocess.check_output(['ethtool', '-i', interface]), re.M).group(1)
            if driver in IPOIB_DRIVERS:
                interfaces.append(interface)
        except Exception:
            log('Skipping interface %s' % interface, level=INFO)
            continue
    return interfaces

def _get_defaults(modules):
    """Load the default config for the provided modules.

    :param modules: stack modules config defaults to lookup.
    :returns: modules default config dictionary."""
    default = os.path.join(os.path.dirname(__file__), 'defaults/%s.yaml' % modules)
    return yaml.safe_load(open(default))

def _get_user_provided_overrides(modules):
    """Load user-provided config overrides.

    :param modules: stack modules to lookup in user overrides yaml file.
    :returns: overrides dictionary."""
    overrides = os.path.join(os.environ['JUJU_CHARM_DIR'], 'hardening.yaml')
    if os.path.exists(overrides):
        log("Found user-provided config overrides file '%s'" % overrides, level=DEBUG)
        settings = yaml.safe_load(open(overrides))
        if settings and settings.get(modules):
            log("Applying '%s' overrides" % modules, level=DEBUG)
            return settings.get(modules)
        log("No overrides found for '%s'" % modules, level=DEBUG)
    else:
        log("No hardening config overrides file '%s' found in charm root dir" % overrides, level=DEBUG)
    return {}

def _apply_overrides(settings, overrides, schema):
    """Get overrides config overlayed onto modules defaults.

    :param modules: require stack modules config.
    :returns: dictionary of modules config with user overrides applied."""
    if overrides:
        for k, v in six.iteritems(overrides):
            if k in schema:
                if schema[k] is None:
                    settings[k] = v
                elif type(schema[k]) is dict:
                    settings[k] = _apply_overrides(settings[k], overrides[k], schema[k])
                else:
                    raise Exception("Unexpected type found in schema '%s'" % type(schema[k]), level=ERROR)
            else:
                log("Unknown override key '%s' - ignoring" % k, level=INFO)
    return settings

def get_audits():
    """Get OS hardening PAM authentication audits.

    :returns:  dictionary of audits"""
    audits = []
    settings = utils.get_settings('os')
    if settings['auth']['pam_passwdqc_enable']:
        audits.append(PasswdqcPAM('/etc/passwdqc.conf'))
    if settings['auth']['retries']:
        audits.append(Tally2PAM('/usr/share/pam-configs/tally2'))
    else:
        audits.append(DeletedFile('/usr/share/pam-configs/tally2'))
    return audits

def get_platform():
    """Return the current OS platform.

    For example: if current os platform is Ubuntu then a string "ubuntu"
    will be returned (which is the name of the module).
    This string is used to decide which platform module should be imported."""
    tuple_platform = platform.linux_distribution()
    current_platform = tuple_platform[0]
    if 'Ubuntu' in current_platform:
        return 'ubuntu'
    elif 'CentOS' in current_platform:
        return 'centos'
    elif 'debian' in current_platform:
        return 'ubuntu'
    else:
        raise RuntimeError('This module is not supported on {}.'.format(current_platform))

def current_version_string():
    """Current system python version as string major.minor.micro"""
    return '{0}.{1}.{2}'.format(sys.version_info.major, sys.version_info.minor, sys.version_info.micro)

def service_running(service_name, **kwargs):
    """Determine whether a system service is running.

    :param service_name: the name of the service
    :param **kwargs: additional args to pass to the service command. This is
                     used to pass additional key=value arguments to the
                     service command line for managing specific instance
                     units (e.g. service ceph-osd status id=2). The kwargs
                     are ignored in systemd services."""
    if init_is_systemd():
        return service('is-active', service_name)
    else:
        if os.path.exists(_UPSTART_CONF.format(service_name)):
            try:
                cmd = ['status', service_name]
                for key, value in six.iteritems(kwargs):
                    parameter = '%s=%s' % (key, value)
                    cmd.append(parameter)
                output = subprocess.check_output(cmd, stderr=subprocess.STDOUT).decode('UTF-8')
            except subprocess.CalledProcessError:
                return False
            else:
                if 'start/running' in output or 'is running' in output or 'up and running' in output:
                    return True
        elif os.path.exists(_INIT_D_CONF.format(service_name)):
            return service('status', service_name)
        return False

def user_exists(username):
    """Check if a user exists"""
    try:
        pwd.getpwnam(username)
        user_exists = True
    except KeyError:
        user_exists = False
    return user_exists

def uid_exists(uid):
    """Check if a uid exists"""
    try:
        pwd.getpwuid(uid)
        uid_exists = True
    except KeyError:
        uid_exists = False
    return uid_exists

def group_exists(groupname):
    """Check if a group exists"""
    try:
        grp.getgrnam(groupname)
        group_exists = True
    except KeyError:
        group_exists = False
    return group_exists

def gid_exists(gid):
    """Check if a gid exists"""
    try:
        grp.getgrgid(gid)
        gid_exists = True
    except KeyError:
        gid_exists = False
    return gid_exists

def fstab_add(dev, mp, fs, options=None):
    """Adds the given device entry to the /etc/fstab file"""
    return Fstab.add(dev, mp, fs, options=options)

def mount(device, mountpoint, options=None, persist=False, filesystem='ext3'):
    """Mount a filesystem at a particular mountpoint"""
    cmd_args = ['mount']
    if options is not None:
        cmd_args.extend(['-o', options])
    cmd_args.extend([device, mountpoint])
    try:
        subprocess.check_output(cmd_args)
    except subprocess.CalledProcessError as e:
        log('Error mounting {} at {}\n{}'.format(device, mountpoint, e.output))
        return False
    if persist:
        return fstab_add(device, mountpoint, filesystem, options=options)
    return True

def umount(mountpoint, persist=False):
    """Unmount a filesystem"""
    cmd_args = ['umount', mountpoint]
    try:
        subprocess.check_output(cmd_args)
    except subprocess.CalledProcessError as e:
        log('Error unmounting {}\n{}'.format(mountpoint, e.output))
        return False
    if persist:
        return fstab_remove(mountpoint)
    return True

def fstab_mount(mountpoint):
    """Mount filesystem using fstab"""
    cmd_args = ['mount', mountpoint]
    try:
        subprocess.check_output(cmd_args)
    except subprocess.CalledProcessError as e:
        log('Error unmounting {}\n{}'.format(mountpoint, e.output))
        return False
    return True

def file_hash(path, hash_type='md5'):
    """Generate a hash checksum of the contents of 'path' or None if not found.

    :param str hash_type: Any hash alrgorithm supported by :mod:`hashlib`,
                          such as md5, sha1, sha256, sha512, etc."""
    if os.path.exists(path):
        h = getattr(hashlib, hash_type)()
        with open(path, 'rb') as source:
            h.update(source.read())
        return h.hexdigest()
    else:
        return None

def restart_on_change(restart_map, stopstart=False, restart_functions=None):
    """Restart services based on configuration files changing

    This function is used a decorator, for example::

        @restart_on_change({
            '/etc/ceph/ceph.conf': [ 'cinder-api', 'cinder-volume' ]
            '/etc/apache/sites-enabled/*': [ 'apache2' ]
            })
        def config_changed():
            pass  # your code here

    In this example, the cinder-api and cinder-volume services
    would be restarted if /etc/ceph/ceph.conf is changed by the
    ceph_client_changed function. The apache2 service would be
    restarted if any file matching the pattern got changed, created
    or removed. Standard wildcards are supported, see documentation
    for the 'glob' module for more information.

    @param restart_map: {path_file_name: [service_name, ...]
    @param stopstart: DEFAULT false; whether to stop, start OR restart
    @param restart_functions: nonstandard functions to use to restart services
                              {svc: func, ...}
    @returns result from decorated function"""
    def wrap(f):
        @functools.wraps(f)
        def wrapped_f(*args, **kwargs):
            return restart_on_change_helper(lambda: f(*args, **kwargs), restart_map, stopstart, restart_functions)
        return wrapped_f
    return wrap

def restart_on_change_helper(lambda_f, restart_map, stopstart=False, restart_functions=None):
    """Helper function to perform the restart_on_change function.

    This is provided for decorators to restart services if files described
    in the restart_map have changed after an invocation of lambda_f().

    @param lambda_f: function to call.
    @param restart_map: {file: [service, ...]}
    @param stopstart: whether to stop, start or restart a service
    @param restart_functions: nonstandard functions to use to restart services
                              {svc: func, ...}
    @returns result of lambda_f()"""
    if restart_functions is None:
        restart_functions = {}
    checksums = {path: path_hash(path) for path in restart_map}
    r = lambda_f()
    restarts = [restart_map[path] for path in restart_map if path_hash(path) != checksums[path]]
    services_list = list(OrderedDict.fromkeys(itertools.chain(*restarts)))
    if services_list:
        actions = ('stop', 'start') if stopstart else ('restart',)
        for service_name in services_list:
            if service_name in restart_functions:
                restart_functions[service_name](service_name)
            else:
                for action in actions:
                    service(action, service_name)
    return r

def pwgen(length=None):
    """Generate a random pasword."""
    if length is None:
        length = random.choice(range(35, 45))
    alphanumeric_chars = [l for l in string.ascii_letters + string.digits if l not in 'l0QD1vAEIOUaeiou']
    random_generator = random.SystemRandom()
    random_chars = [random_generator.choice(alphanumeric_chars) for _ in range(length)]
    return ''.join(random_chars)

def is_phy_iface(interface):
    """Returns True if interface is not virtual, otherwise False."""
    if interface:
        sys_net = '/sys/class/net'
        if os.path.isdir(sys_net):
            for iface in glob.glob(os.path.join(sys_net, '*')):
                if '/virtual/' in os.path.realpath(iface):
                    continue
                if interface == os.path.basename(iface):
                    return True
    return False

def get_bond_master(interface):
    """Returns bond master if interface is bond slave otherwise None.

    NOTE: the provided interface is expected to be physical"""
    if interface:
        iface_path = '/sys/class/net/%s' % interface
        if os.path.exists(iface_path):
            if '/virtual/' in os.path.realpath(iface_path):
                return None
            master = os.path.join(iface_path, 'master')
            if os.path.exists(master):
                master = os.path.realpath(master)
                if os.path.exists(os.path.join(master, 'bonding')):
                    return os.path.basename(master)
    return None

def list_nics(nic_type=None):
    """Return a list of nics of given type(s)"""
    if isinstance(nic_type, six.string_types):
        int_types = [nic_type]
    else:
        int_types = nic_type
    interfaces = []
    if nic_type:
        for int_type in int_types:
            cmd = ['ip', 'addr', 'show', 'label', int_type + '*']
            ip_output = subprocess.check_output(cmd).decode('UTF-8')
            ip_output = ip_output.split('\n')
            ip_output = (line for line in ip_output if line)
            for line in ip_output:
                if line.split()[1].startswith(int_type):
                    matched = re.search('.*: (' + int_type + '[0-9]+\\.[0-9]+)@.*', line)
                    if matched:
                        iface = matched.groups()[0]
                    else:
                        iface = line.split()[1].replace(':', '')
                    if iface not in interfaces:
                        interfaces.append(iface)
    else:
        cmd = ['ip', 'a']
        ip_output = subprocess.check_output(cmd).decode('UTF-8').split('\n')
        ip_output = (line.strip() for line in ip_output if line)
        key = re.compile('^[0-9]+:\\s+(.+):')
        for line in ip_output:
            matched = re.search(key, line)
            if matched:
                iface = matched.group(1)
                iface = iface.partition('@')[0]
                if iface not in interfaces:
                    interfaces.append(iface)
    return interfaces

def get_nic_mtu(nic):
    """Return the Maximum Transmission Unit (MTU) for a network interface."""
    cmd = ['ip', 'addr', 'show', nic]
    ip_output = subprocess.check_output(cmd).decode('UTF-8').split('\n')
    mtu = ''
    for line in ip_output:
        words = line.split()
        if 'mtu' in words:
            mtu = words[words.index('mtu') + 1]
    return mtu

def chownr(path, owner, group, follow_links=True, chowntopdir=False):
    """Recursively change user and group ownership of files and directories
    in given path. Doesn't chown path itself by default, only its children.

    :param str path: The string path to start changing ownership.
    :param str owner: The owner string to use when looking up the uid.
    :param str group: The group string to use when looking up the gid.
    :param bool follow_links: Also follow and chown links if True
    :param bool chowntopdir: Also chown path itself if True"""
    uid = pwd.getpwnam(owner).pw_uid
    gid = grp.getgrnam(group).gr_gid
    if follow_links:
        chown = os.chown
    else:
        chown = os.lchown
    if chowntopdir:
        broken_symlink = os.path.lexists(path) and (not os.path.exists(path))
        if not broken_symlink:
            chown(path, uid, gid)
    for root, dirs, files in os.walk(path, followlinks=follow_links):
        for name in dirs + files:
            full = os.path.join(root, name)
            broken_symlink = os.path.lexists(full) and (not os.path.exists(full))
            if not broken_symlink:
                chown(full, uid, gid)

def get_total_ram():
    """The total amount of system RAM in bytes.

    This is what is reported by the OS, and may be overcommitted when
    there are multiple containers hosted on the same machine."""
    with open('/proc/meminfo', 'r') as f:
        for line in f.readlines():
            if line:
                key, value, unit = line.split()
                if key == 'MemTotal:':
                    assert unit == 'kB', 'Unknown unit'
                    return int(value) * 1024
        raise NotImplementedError()

def dict_keys_without_hyphens(a_dict):
    """Return the a new dict with underscores instead of hyphens in keys."""
    return dict(((key.replace('-', '_'), val) for key, val in a_dict.items()))

def update_relations(context, namespace_separator=':'):
    """Update the context with the relation data."""
    relation_type = charmhelpers.core.hookenv.relation_type()
    relations = []
    context['current_relation'] = {}
    if relation_type is not None:
        relation_data = charmhelpers.core.hookenv.relation_get()
        context['current_relation'] = relation_data
        relation_data = dict((('{relation_type}{namespace_separator}{key}'.format(relation_type=relation_type, key=key, namespace_separator=namespace_separator), val) for key, val in relation_data.items()))
        relation_data = dict_keys_without_hyphens(relation_data)
        context.update(relation_data)
        relations = charmhelpers.core.hookenv.relations_of_type(relation_type)
        relations = [dict_keys_without_hyphens(rel) for rel in relations]
    context['relations_full'] = charmhelpers.core.hookenv.relations()
    local_unit = charmhelpers.core.hookenv.local_unit()
    relations = {}
    for rname, rids in context['relations_full'].items():
        relations[rname] = []
        for rid, rdata in rids.items():
            data = rdata.copy()
            if local_unit in rdata:
                data.pop(local_unit)
            for unit_name, rel_data in data.items():
                new_data = {'__relid__': rid, '__unit__': unit_name}
                new_data.update(rel_data)
                relations[rname].append(new_data)
    context['relations'] = relations

def kernel_version():
    """Retrieve the current major kernel version as a tuple e.g. (3, 13)"""
    kver = check_output(['uname', '-r']).decode('UTF-8').strip()
    kver = kver.split('.')
    return (int(kver[0]), int(kver[1]))

def network_manager():
    """Deals with the renaming of Quantum to Neutron in H and any situations
    that require compatability (eg, deploying H with network-manager=quantum,
    upgrading from G)."""
    release = os_release('nova-common')
    manager = config('network-manager').lower()
    if manager not in ['quantum', 'neutron']:
        return manager
    if release in ['essex']:
        log('Neutron networking not supported in Essex.', level=ERROR)
        raise Exception
    elif release in ['folsom', 'grizzly']:
        return 'quantum'
    else:
        return 'neutron'

def parse_mappings(mappings, key_rvalue=False):
    """By default mappings are lvalue keyed.

    If key_rvalue is True, the mapping will be reversed to allow multiple
    configs for the same lvalue."""
    parsed = {}
    if mappings:
        mappings = mappings.split()
        for m in mappings:
            p = m.partition(':')
            if key_rvalue:
                key_index = 2
                val_index = 0
                if not p[1]:
                    continue
            else:
                key_index = 0
                val_index = 2
            key = p[key_index].strip()
            parsed[key] = p[val_index].strip()
    return parsed

def parse_data_port_mappings(mappings, default_bridge='br-data'):
    """Parse data port mappings.

    Mappings must be a space-delimited list of bridge:port.

    Returns dict of the form {port:bridge} where ports may be mac addresses or
    interface names."""
    _mappings = parse_mappings(mappings, key_rvalue=True)
    if not _mappings or list(_mappings.values()) == ['']:
        if not mappings:
            return {}
        _mappings = {mappings.split()[0]: default_bridge}
    ports = _mappings.keys()
    if len(set(ports)) != len(ports):
        raise Exception('It is not allowed to have the same port configured on more than one bridge')
    return _mappings

def parse_vlan_range_mappings(mappings):
    """Parse vlan range mappings.

    Mappings must be a space-delimited list of provider:start:end mappings.

    The start:end range is optional and may be omitted.

    Returns dict of the form {provider: (start, end)}."""
    _mappings = parse_mappings(mappings)
    if not _mappings:
        return {}
    mappings = {}
    for p, r in six.iteritems(_mappings):
        mappings[p] = tuple(r.split(':'))
    return mappings

def _get_ipv6_network_from_address(address):
    """Get an netaddr.IPNetwork for the given IPv6 address
    :param address: a dict as returned by netifaces.ifaddresses
    :returns netaddr.IPNetwork: None if the address is a link local or loopback
    address"""
    if address['addr'].startswith('fe80') or address['addr'] == '::1':
        return None
    prefix = address['netmask'].split('/')
    if len(prefix) > 1:
        netmask = prefix[1]
    else:
        netmask = address['netmask']
    return netaddr.IPNetwork('%s/%s' % (address['addr'], netmask))

def is_ipv6(address):
    """Determine whether provided address is IPv6 or not."""
    try:
        address = netaddr.IPAddress(address)
    except netaddr.AddrFormatError:
        return False
    return address.version == 6

def is_address_in_network(network, address):
    """Determine whether the provided address is within a network range.

    :param network (str): CIDR presentation format. For example,
        '192.168.1.0/24'.
    :param address: An individual IPv4 or IPv6 address without a net
        mask or subnet prefix. For example, '192.168.1.1'.
    :returns boolean: Flag indicating whether address is in network."""
    try:
        network = netaddr.IPNetwork(network)
    except (netaddr.core.AddrFormatError, ValueError):
        raise ValueError('Network (%s) is not in CIDR presentation format' % network)
    try:
        address = netaddr.IPAddress(address)
    except (netaddr.core.AddrFormatError, ValueError):
        raise ValueError('Address (%s) is not in correct presentation format' % address)
    if address in network:
        return True
    else:
        return False

def resolve_network_cidr(ip_address):
    """Resolves the full address cidr of an ip_address based on
    configured network interfaces"""
    netmask = get_netmask_for_address(ip_address)
    return str(netaddr.IPNetwork('%s/%s' % (ip_address, netmask)).cidr)

def get_iface_from_addr(addr):
    """Work out on which interface the provided address is configured."""
    for iface in netifaces.interfaces():
        addresses = netifaces.ifaddresses(iface)
        for inet_type in addresses:
            for _addr in addresses[inet_type]:
                _addr = _addr['addr']
                ll_key = re.compile('(.+)%.*')
                raw = re.match(ll_key, _addr)
                if raw:
                    _addr = raw.group(1)
                if _addr == addr:
                    log("Address '%s' is configured on iface '%s'" % (addr, iface))
                    return iface
    msg = "Unable to infer net iface on which '%s' is configured" % addr
    raise Exception(msg)

def sniff_iface(f):
    """Ensure decorated function is called with a value for iface.

    If no iface provided, inject net iface inferred from unit private address."""
    def iface_sniffer(*args, **kwargs):
        if not kwargs.get('iface', None):
            kwargs['iface'] = get_iface_from_addr(unit_get('private-address'))
        return f(*args, **kwargs)
    return iface_sniffer

def is_ip(address):
    """Returns True if address is a valid IP address."""
    try:
        address = netaddr.IPAddress(address)
        return True
    except (netaddr.AddrFormatError, ValueError):
        return False

def get_host_ip(hostname, fallback=None):
    """Resolves the IP for a given hostname, or returns
    the input if it is already an IP."""
    if is_ip(hostname):
        return hostname
    ip_addr = ns_query(hostname)
    if not ip_addr:
        try:
            ip_addr = socket.gethostbyname(hostname)
        except Exception:
            log("Failed to resolve hostname '%s'" % hostname, level=WARNING)
            return fallback
    return ip_addr

def get_hostname(address, fqdn=True):
    """Resolves hostname for given IP, or returns the input
    if it is already a hostname."""
    if is_ip(address):
        try:
            import dns.reversename
        except ImportError:
            if six.PY2:
                apt_install('python-dnspython', fatal=True)
            else:
                apt_install('python3-dnspython', fatal=True)
            import dns.reversename
        rev = dns.reversename.from_address(address)
        result = ns_query(rev)
        if not result:
            try:
                result = socket.gethostbyaddr(address)[0]
            except Exception:
                return None
    else:
        result = address
    if fqdn:
        if result.endswith('.'):
            return result[:-1]
        else:
            return result
    else:
        return result.split('.')[0]

def port_has_listener(address, port):
    """Returns True if the address:port is open and being listened to,
    else False.

    @param address: an IP address or hostname
    @param port: integer port

    Note calls 'zc' via a subprocess shell"""
    cmd = ['nc', '-z', address, str(port)]
    result = subprocess.call(cmd)
    return not bool(result)

def get_relation_ip(interface, cidr_network=None):
    """Return this unit's IP for the given interface.

    Allow for an arbitrary interface to use with network-get to select an IP.
    Handle all address selection options including passed cidr network and
    IPv6.

    Usage: get_relation_ip('amqp', cidr_network='10.0.0.0/8')

    @param interface: string name of the relation.
    @param cidr_network: string CIDR Network to select an address from.
    @raises Exception if prefer-ipv6 is configured but IPv6 unsupported.
    @returns IPv6 or IPv4 address"""
    try:
        address = network_get_primary_address(interface)
    except NotImplementedError:
        address = get_host_ip(unit_get('private-address'))
    except NoNetworkBinding:
        log('No network binding for {}'.format(interface), WARNING)
        address = get_host_ip(unit_get('private-address'))
    if config('prefer-ipv6'):
        assert_charm_supports_ipv6()
        return get_ipv6_addr()[0]
    elif cidr_network:
        return get_address_in_network(cidr_network, address)
    return address

def bool_from_string(value):
    """Interpret string value as boolean.

    Returns True if value translates to True otherwise False."""
    if isinstance(value, six.string_types):
        value = six.text_type(value)
    else:
        msg = "Unable to interpret non-string value '%s' as boolean" % value
        raise ValueError(msg)
    value = value.strip().lower()
    if value in ['y', 'yes', 'true', 't', 'on']:
        return True
    elif value in ['n', 'no', 'false', 'f', 'off']:
        return False
    msg = "Unable to interpret string value '%s' as boolean" % value
    raise ValueError(msg)

def bytes_from_string(value):
    """Interpret human readable string value as bytes.

    Returns int"""
    BYTE_POWER = {'K': 1, 'KB': 1, 'M': 2, 'MB': 2, 'G': 3, 'GB': 3, 'T': 4, 'TB': 4, 'P': 5, 'PB': 5}
    if isinstance(value, six.string_types):
        value = six.text_type(value)
    else:
        msg = "Unable to interpret non-string value '%s' as bytes" % value
        raise ValueError(msg)
    matches = re.match('([0-9]+)([a-zA-Z]+)', value)
    if matches:
        size = int(matches.group(1)) * 1024 ** BYTE_POWER[matches.group(2)]
    else:
        try:
            size = int(value)
        except ValueError:
            msg = "Unable to interpret string value '%s' as bytes" % value
            raise ValueError(msg)
    return size

def is_audit_type(*args):
    """This audit is included in the specified kinds of audits.

    :param *args: List of AuditTypes to include this audit in
    :type args: List[AuditType]
    :rtype: Callable[Dict]"""
    def _is_audit_type(audit_options):
        if audit_options.get('audit_type') in args:
            return True
        else:
            return False
    return _is_audit_type

def run(audit_options):
    """Run the configured audits with the specified audit_options.

    :param audit_options: Configuration for the audit
    :type audit_options: Config

    :rtype: Dict[str, str]"""
    errors = {}
    results = {}
    for name, audit in sorted(_audits.items()):
        result_name = name.replace('_', '-')
        if result_name in audit_options.get('excludes', []):
            print('Skipping {} because it isexcluded in audit config'.format(result_name))
            continue
        if all((p(audit_options) for p in audit.filters)):
            try:
                audit.func(audit_options)
                print('{}: PASS'.format(name))
                results[result_name] = {'success': True}
            except AssertionError as e:
                print('{}: FAIL ({})'.format(name, e))
                results[result_name] = {'success': False, 'message': e}
            except Exception as e:
                print('{}: ERROR ({})'.format(name, e))
                errors[name] = e
                results[result_name] = {'success': False, 'message': e}
    for name, error in errors.items():
        print('=' * 20)
        print('Error in {}: '.format(name))
        traceback.print_tb(error.__traceback__)
        print()
    return results

def action_parse_results(result):
    """Parse the result of `run` in the context of an action.

    :param result: The result of running the security-checklist
        action on a unit
    :type result: Dict[str, Dict[str, str]]
    :rtype: int"""
    passed = True
    for test, result in result.items():
        if result['success']:
            hookenv.action_set({test: 'PASS'})
        else:
            hookenv.action_set({test: 'FAIL - {}'.format(result['message'])})
            passed = False
    if not passed:
        hookenv.action_fail('One or more tests failed')
    return 0 if passed else 1

def ssh_directory_for_unit(application_name, user=None):
    """Return the directory used to store ssh assets for the application.

    :param application_name: Name of application eg nova-compute-something
    :type application_name: str
    :param user: The user that the ssh asserts are for.
    :type user: str
    :returns: Fully qualified directory path.
    :rtype: str"""
    if user:
        application_name = '{}_{}'.format(application_name, user)
    _dir = os.path.join(NOVA_SSH_DIR, application_name)
    for d in [NOVA_SSH_DIR, _dir]:
        if not os.path.isdir(d):
            os.mkdir(d)
    for f in ['authorized_keys', 'known_hosts']:
        f = os.path.join(_dir, f)
        if not os.path.isfile(f):
            open(f, 'w').close()
    return _dir

def get_ssh_settings(application_name, user=None):
    """Retrieve the known host entries and public keys for application

    Retrieve the known host entries and public keys for application for all
    units of the given application related to this application for the
    app + user combination.

    :param application_name: Name of application eg nova-compute-something
    :type application_name: str
    :param user: The user that the ssh asserts are for.
    :type user: str
    :returns: Public keys + host keys for all units for app + user combination.
    :rtype: dict"""
    settings = {}
    keys = {}
    prefix = ''
    if user:
        prefix = '{}_'.format(user)
    for i, line in enumerate(ssh_known_hosts_lines(application_name=application_name, user=user)):
        settings['{}known_hosts_{}'.format(prefix, i)] = line
    if settings:
        settings['{}known_hosts_max_index'.format(prefix)] = len(settings.keys())
    for i, line in enumerate(ssh_authorized_keys_lines(application_name=application_name, user=user)):
        keys['{}authorized_keys_{}'.format(prefix, i)] = line
    if keys:
        keys['{}authorized_keys_max_index'.format(prefix)] = len(keys.keys())
    settings.update(keys)
    return settings

def filter_installed_packages(packages):
    """Return a list of packages that require installation."""
    cache = apt_cache()
    _pkgs = []
    for package in packages:
        try:
            p = cache[package]
            p.current_ver or _pkgs.append(package)
        except KeyError:
            log('Package {} has no installation candidate.'.format(package), level='WARNING')
            _pkgs.append(package)
    return _pkgs

def apt_cache(in_memory=True, progress=None):
    """Build and return an apt cache."""
    from apt import apt_pkg
    apt_pkg.init()
    if in_memory:
        apt_pkg.config.set('Dir::Cache::pkgcache', '')
        apt_pkg.config.set('Dir::Cache::srcpkgcache', '')
    return apt_pkg.Cache(progress)

def apt_install(packages, options=None, fatal=False):
    """Install one or more packages."""
    if options is None:
        options = ['--option=Dpkg::Options::=--force-confold']
    cmd = ['apt-get', '--assume-yes']
    cmd.extend(options)
    cmd.append('install')
    if isinstance(packages, six.string_types):
        cmd.append(packages)
    else:
        cmd.extend(packages)
    log('Installing {} with options: {}'.format(packages, options))
    _run_apt_command(cmd, fatal)

def apt_upgrade(options=None, fatal=False, dist=False):
    """Upgrade all packages."""
    if options is None:
        options = ['--option=Dpkg::Options::=--force-confold']
    cmd = ['apt-get', '--assume-yes']
    cmd.extend(options)
    if dist:
        cmd.append('dist-upgrade')
    else:
        cmd.append('upgrade')
    log('Upgrading with options: {}'.format(options))
    _run_apt_command(cmd, fatal)

def apt_purge(packages, fatal=False):
    """Purge one or more packages."""
    cmd = ['apt-get', '--assume-yes', 'purge']
    if isinstance(packages, six.string_types):
        cmd.append(packages)
    else:
        cmd.extend(packages)
    log('Purging {}'.format(packages))
    _run_apt_command(cmd, fatal)

def apt_autoremove(purge=True, fatal=False):
    """Purge one or more packages."""
    cmd = ['apt-get', '--assume-yes', 'autoremove']
    if purge:
        cmd.append('--purge')
    _run_apt_command(cmd, fatal)

def apt_mark(packages, mark, fatal=False):
    """Flag one or more packages using apt-mark."""
    log('Marking {} as {}'.format(packages, mark))
    cmd = ['apt-mark', mark]
    if isinstance(packages, six.string_types):
        cmd.append(packages)
    else:
        cmd.extend(packages)
    if fatal:
        subprocess.check_call(cmd, universal_newlines=True)
    else:
        subprocess.call(cmd, universal_newlines=True)

def _run_apt_command(cmd, fatal=False):
    """Run an apt command with optional retries.

    :param: cmd: str: The apt command to run.
    :param: fatal: bool: Whether the command's output should be checked and
        retried."""
    cmd_env = {'DEBIAN_FRONTEND': os.environ.get('DEBIAN_FRONTEND', 'noninteractive')}
    if fatal:
        _run_with_retries(cmd, cmd_env=cmd_env, retry_exitcodes=(1, APT_NO_LOCK), retry_message="Couldn't acquire DPKG lock")
    else:
        env = os.environ.copy()
        env.update(cmd_env)
        subprocess.call(cmd, env=env)

def get_upstream_version(package):
    """Determine upstream version based on installed package

    @returns None (if not installed) or the upstream version"""
    import apt_pkg
    cache = apt_cache()
    try:
        pkg = cache[package]
    except Exception:
        return None
    if not pkg.current_ver:
        return None
    return apt_pkg.upstream_version(pkg.current_ver.ver_str)

def get_stats_action(cachespec, interval):
    """Action for getting bcache statistics for a given cachespec.
    Cachespec can either be a device name, eg. 'sdb', which will retrieve
    cache stats for the given device, or 'global', which will retrieve stats
    for all cachesets"""
    if cachespec == 'global':
        caches = get_bcache_fs()
    else:
        caches = [Bcache.fromdevice(cachespec)]
    res = dict(((c.cachepath, c.get_stats(interval)) for c in caches))
    return json.dumps(res, indent=4, separators=(',', ': '))

def update_dns_ha_resource_params(resources, resource_params, relation_id=None, crm_ocf='ocf:maas:dns'):
    """Configure DNS-HA resources based on provided configuration and
    update resource dictionaries for the HA relation.

    @param resources: Pointer to dictionary of resources.
                      Usually instantiated in ha_joined().
    @param resource_params: Pointer to dictionary of resource parameters.
                            Usually instantiated in ha_joined()
    @param relation_id: Relation ID of the ha relation
    @param crm_ocf: Corosync Open Cluster Framework resource agent to use for
                    DNS HA"""
    _relation_data = {'resources': {}, 'resource_params': {}}
    update_hacluster_dns_ha(charm_name(), _relation_data, crm_ocf)
    resources.update(_relation_data['resources'])
    resource_params.update(_relation_data['resource_params'])
    relation_set(relation_id=relation_id, groups=_relation_data['groups'])

def expect_ha():
    """Determine if the unit expects to be in HA

    Check juju goal-state if ha relation is expected, check for VIP or dns-ha
    settings which indicate the unit should expect to be related to hacluster.

    @returns boolean"""
    ha_related_units = []
    try:
        ha_related_units = list(expected_related_units(reltype='ha'))
    except (NotImplementedError, KeyError):
        pass
    return len(ha_related_units) > 0 or config('vip') or config('dns-ha')

def get_vip_settings(vip):
    """Calculate which nic is on the correct network for the given vip.

    If nic or netmask discovery fail then fallback to using charm supplied
    config. If fallback is used this is indicated via the fallback variable.

    @param vip: VIP to lookup nic and cidr for.
    @returns (str, str, bool): eg (iface, netmask, fallback)"""
    iface = get_iface_for_address(vip)
    netmask = get_netmask_for_address(vip)
    fallback = False
    if iface is None:
        iface = config('vip_iface')
        fallback = True
    if netmask is None:
        netmask = config('vip_cidr')
        fallback = True
    return (iface, netmask, fallback)

def format_endpoint(schema, addr, port, api_version):
    """Return a formatted keystone endpoint
    @param schema: http or https
    @param addr: ipv4/ipv6 host of the keystone service
    @param port: port of the keystone service
    @param api_version: 2 or 3
    @returns a fully formatted keystone endpoint"""
    return '{}://{}:{}/{}/'.format(schema, addr, port, get_api_suffix(api_version))

def get_keystone_manager(endpoint, api_version, **kwargs):
    """Return a keystonemanager for the correct API version

    @param endpoint: the keystone endpoint to point client at
    @param api_version: version of the keystone api the client should use
    @param kwargs: token or username/tenant/password information
    @returns keystonemanager class used for interrogating keystone"""
    if api_version == 2:
        return KeystoneManager2(endpoint, **kwargs)
    if api_version == 3:
        return KeystoneManager3(endpoint, **kwargs)
    raise ValueError('No manager found for api version {}'.format(api_version))

def get_keystone_manager_from_identity_service_context():
    """Return a keystonmanager generated from a
    instance of charmhelpers.contrib.openstack.context.IdentityServiceContext
    @returns keystonamenager instance"""
    context = IdentityServiceContext()()
    if not context:
        msg = 'Identity service context cannot be generated'
        log(msg, level=ERROR)
        raise ValueError(msg)
    endpoint = format_endpoint(context['service_protocol'], context['service_host'], context['service_port'], context['api_version'])
    if context['api_version'] in (2, '2.0'):
        api_version = 2
    else:
        api_version = 3
    return get_keystone_manager(endpoint, api_version, username=context['admin_user'], password=context['admin_password'], tenant_name=context['admin_tenant_name'])

def list_logical_volumes(select_criteria=None, path_mode=False):
    """List logical volumes

    :param select_criteria: str: Limit list to those volumes matching this
                                 criteria (see 'lvs -S help' for more details)
    :param path_mode: bool: return logical volume name in 'vg/lv' format, this
                            format is required for some commands like lvextend
    :returns: [str]: List of logical volumes"""
    lv_diplay_attr = 'lv_name'
    if path_mode:
        lv_diplay_attr = 'vg_name,' + lv_diplay_attr
    cmd = ['lvs', '--options', lv_diplay_attr, '--noheadings']
    if select_criteria:
        cmd.extend(['--select', select_criteria])
    lvs = []
    for lv in check_output(cmd).decode('UTF-8').splitlines():
        if not lv:
            continue
        if path_mode:
            lvs.append('/'.join(lv.strip().split()))
        else:
            lvs.append(lv.strip())
    return lvs

def create_logical_volume(lv_name, volume_group, size=None):
    """Create a new logical volume in an existing volume group

    :param lv_name: str: name of logical volume to be created.
    :param volume_group: str: Name of volume group to use for the new volume.
    :param size: str: Size of logical volume to create (100% if not supplied)
    :raises subprocess.CalledProcessError: in the event that the lvcreate fails."""
    if size:
        check_call(['lvcreate', '--yes', '-L', '{}'.format(size), '-n', lv_name, volume_group])
    else:
        check_call(['lvcreate', '--yes', '-l', '100%FREE', '-n', lv_name, volume_group])

def cached(func):
    """Cache return values for multiple executions of func + args

    For example::

        @cached
        def unit_get(attribute):
            pass

        unit_get('test')

    will cache the result of unit_get + 'test' for future calls."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        global cache
        key = json.dumps((func, args, kwargs), sort_keys=True, default=str)
        try:
            return cache[key]
        except KeyError:
            pass
        res = func(*args, **kwargs)
        cache[key] = res
        return res
    wrapper._wrapped = func
    return wrapper

def flush(key):
    """Flushes any entries from function cache where the
    key is found in the function+args"""
    flush_list = []
    for item in cache:
        if key in item:
            flush_list.append(item)
    for item in flush_list:
        del cache[item]

def log(message, level=None):
    """Write a message to the juju log"""
    command = ['juju-log']
    if level:
        command += ['-l', level]
    if not isinstance(message, six.string_types):
        message = repr(message)
    command += [message[:SH_MAX_ARG]]
    try:
        subprocess.call(command)
    except OSError as e:
        if e.errno == errno.ENOENT:
            if level:
                message = '{}: {}'.format(level, message)
            message = 'juju-log: {}'.format(message)
            print(message, file=sys.stderr)
        else:
            raise

def relation_id(relation_name=None, service_or_unit=None):
    """The relation ID for the current or a specified relation"""
    if not relation_name and (not service_or_unit):
        return os.environ.get('JUJU_RELATION_ID', None)
    elif relation_name and service_or_unit:
        service_name = service_or_unit.split('/')[0]
        for relid in relation_ids(relation_name):
            remote_service = remote_service_name(relid)
            if remote_service == service_name:
                return relid
    else:
        raise ValueError('Must specify neither or both of relation_name and service_or_unit')

def principal_unit():
    """Returns the principal unit of this unit, otherwise None"""
    principal_unit = os.environ.get('JUJU_PRINCIPAL_UNIT', None)
    if principal_unit == '':
        return os.environ['JUJU_UNIT_NAME']
    elif principal_unit is not None:
        return principal_unit
    for reltype in relation_types():
        for rid in relation_ids(reltype):
            for unit in related_units(rid):
                md = _metadata_unit(unit)
                if not md:
                    continue
                subordinate = md.pop('subordinate', None)
                if not subordinate:
                    return unit
    return None

def remote_service_name(relid=None):
    """The remote service name for a given relation-id (or the current relation)"""
    if relid is None:
        unit = remote_unit()
    else:
        units = related_units(relid)
        unit = units[0] if units else None
    return unit.split('/')[0] if unit else None

def config(scope=None):
    """Get the juju charm configuration (scope==None) or individual key,
    (scope=str).  The returned value is a Python data structure loaded as
    JSON from the Juju config command.

    :param scope: If set, return the value for the specified key.
    :type scope: Optional[str]
    :returns: Either the whole config as a Config, or a key from it.
    :rtype: Any"""
    global _cache_config
    config_cmd_line = ['config-get', '--all', '--format=json']
    try:
        exc_json = json.decoder.JSONDecodeError
    except AttributeError:
        exc_json = ValueError
    try:
        if _cache_config is None:
            config_data = json.loads(subprocess.check_output(config_cmd_line).decode('UTF-8'))
            _cache_config = Config(config_data)
        if scope is not None:
            return _cache_config.get(scope)
        return _cache_config
    except (exc_json, UnicodeDecodeError) as e:
        log('Unable to parse output from config-get: config_cmd_line="{}" message="{}"'.format(config_cmd_line, str(e)), level=ERROR)
        return None

def relation_get(attribute=None, unit=None, rid=None):
    """Get relation information"""
    _args = ['relation-get', '--format=json']
    if rid:
        _args.append('-r')
        _args.append(rid)
    _args.append(attribute or '-')
    if unit:
        _args.append(unit)
    try:
        return json.loads(subprocess.check_output(_args).decode('UTF-8'))
    except ValueError:
        return None
    except CalledProcessError as e:
        if e.returncode == 2:
            return None
        raise

def relation_set(relation_id=None, relation_settings=None, **kwargs):
    """Set relation information for the current unit"""
    relation_settings = relation_settings if relation_settings else {}
    relation_cmd_line = ['relation-set']
    accepts_file = '--file' in subprocess.check_output(relation_cmd_line + ['--help'], universal_newlines=True)
    if relation_id is not None:
        relation_cmd_line.extend(('-r', relation_id))
    settings = relation_settings.copy()
    settings.update(kwargs)
    for key, value in settings.items():
        if value is not None:
            settings[key] = '{}'.format(value)
    if accepts_file:
        with tempfile.NamedTemporaryFile(delete=False) as settings_file:
            settings_file.write(yaml.safe_dump(settings).encode('utf-8'))
        subprocess.check_call(relation_cmd_line + ['--file', settings_file.name])
        os.remove(settings_file.name)
    else:
        for key, value in settings.items():
            if value is None:
                relation_cmd_line.append('{}='.format(key))
            else:
                relation_cmd_line.append('{}={}'.format(key, value))
        subprocess.check_call(relation_cmd_line)
    flush(local_unit())

def relation_clear(r_id=None):
    """Clears any relation data already set on relation r_id"""
    settings = relation_get(rid=r_id, unit=local_unit())
    for setting in settings:
        if setting not in ['public-address', 'private-address']:
            settings[setting] = None
    relation_set(relation_id=r_id, **settings)

def relation_for_unit(unit=None, rid=None):
    """Get the json represenation of a unit's relation"""
    unit = unit or remote_unit()
    relation = relation_get(unit=unit, rid=rid)
    for key in relation:
        if key.endswith('-list'):
            relation[key] = relation[key].split()
    relation['__unit__'] = unit
    return relation

def relations_of_type(reltype=None):
    """Get relations of a specific type"""
    relation_data = []
    reltype = reltype or relation_type()
    for relid in relation_ids(reltype):
        for relation in relations_for_id(relid):
            relation['__relid__'] = relid
            relation_data.append(relation)
    return relation_data

def metadata():
    """Get the current charm metadata.yaml contents as a python object"""
    with open(os.path.join(charm_dir(), 'metadata.yaml')) as md:
        return yaml.safe_load(md)

def relation_types():
    """Get a list of relation types supported by this charm"""
    rel_types = []
    md = metadata()
    for key in ('provides', 'requires', 'peers'):
        section = md.get(key)
        if section:
            rel_types.extend(section.keys())
    return rel_types

def peer_relation_id():
    """Get the peers relation id if a peers relation has been joined, else None."""
    md = metadata()
    section = md.get('peers')
    if section:
        for key in section:
            relids = relation_ids(key)
            if relids:
                return relids[0]
    return None

def relation_to_role_and_interface(relation_name):
    """Given the name of a relation, return the role and the name of the interface
    that relation uses (where role is one of ``provides``, ``requires``, or ``peers``).

    :returns: A tuple containing ``(role, interface)``, or ``(None, None)``."""
    _metadata = metadata()
    for role in ('provides', 'requires', 'peers'):
        interface = _metadata.get(role, {}).get(relation_name, {}).get('interface')
        if interface:
            return (role, interface)
    return (None, None)

def relations():
    """Get a nested dictionary of relation data for all related units"""
    rels = {}
    for reltype in relation_types():
        relids = {}
        for relid in relation_ids(reltype):
            units = {local_unit(): relation_get(unit=local_unit(), rid=relid)}
            for unit in related_units(relid):
                reldata = relation_get(unit=unit, rid=relid)
                units[unit] = reldata
            relids[relid] = units
        rels[reltype] = relids
    return rels

def is_relation_made(relation, keys='private-address'):
    """Determine whether a relation is established by checking for
    presence of key(s).  If a list of keys is provided, they
    must all be present for the relation to be identified as made"""
    if isinstance(keys, str):
        keys = [keys]
    for r_id in relation_ids(relation):
        for unit in related_units(r_id):
            context = {}
            for k in keys:
                context[k] = relation_get(k, rid=r_id, unit=unit)
            if None not in context.values():
                return True
    return False

def _port_op(op_name, port, protocol='TCP'):
    """Open or close a service network port"""
    _args = [op_name]
    icmp = protocol.upper() == 'ICMP'
    if icmp:
        _args.append(protocol)
    else:
        _args.append('{}/{}'.format(port, protocol))
    try:
        subprocess.check_call(_args)
    except subprocess.CalledProcessError:
        if not icmp:
            raise

def unit_get(attribute):
    """Get the unit ID for the remote unit"""
    _args = ['unit-get', '--format=json', attribute]
    try:
        return json.loads(subprocess.check_output(_args).decode('UTF-8'))
    except ValueError:
        return None

def storage_get(attribute=None, storage_id=None):
    """Get storage attributes"""
    _args = ['storage-get', '--format=json']
    if storage_id:
        _args.extend(('-s', storage_id))
    if attribute:
        _args.append(attribute)
    try:
