def get_certificate_request(json_encode=True):
    """Generate a certificatee requests based on the network confioguration

    """
    req = CertRequest(json_encode=json_encode)
    req.add_hostname_cn()
    for net_type in [INTERNAL, ADMIN, PUBLIC]:
        net_config = config(ADDRESS_MAP[net_type]['override'])
        try:
            net_addr = resolve_address(endpoint_type=net_type)
            ip = network_get_primary_address(ADDRESS_MAP[net_type]['binding'])
            addresses = [net_addr, ip]
            vip = get_vip_in_network(resolve_network_cidr(ip))
            if vip:
                addresses.append(vip)
            if net_config:
                req.add_entry(net_type, net_config, addresses)
            else:
                req.add_hostname_cn_ip(addresses)
        except NoNetworkBinding:
            log('Skipping request for certificate for ip in {} space, no local address found'.format(net_type), WARNING)
    return req.get_request()

def create_ip_cert_links(ssl_dir, custom_hostname_link=None):
    """Create symlinks for SAN records

    :param ssl_dir: str Directory to create symlinks in
    :param custom_hostname_link: str Additional link to be created"""
    hostname = get_hostname(unit_get('private-address'))
    hostname_cert = os.path.join(ssl_dir, 'cert_{}'.format(hostname))
    hostname_key = os.path.join(ssl_dir, 'key_{}'.format(hostname))
    for net_type in [INTERNAL, ADMIN, PUBLIC]:
        try:
            addr = resolve_address(endpoint_type=net_type)
            cert = os.path.join(ssl_dir, 'cert_{}'.format(addr))
            key = os.path.join(ssl_dir, 'key_{}'.format(addr))
            if os.path.isfile(hostname_cert) and (not os.path.isfile(cert)):
                os.symlink(hostname_cert, cert)
                os.symlink(hostname_key, key)
        except NoNetworkBinding:
            log('Skipping creating cert symlink for ip in {} space, no local address found'.format(net_type), WARNING)
    if custom_hostname_link:
        custom_cert = os.path.join(ssl_dir, 'cert_{}'.format(custom_hostname_link))
        custom_key = os.path.join(ssl_dir, 'key_{}'.format(custom_hostname_link))
        if os.path.isfile(hostname_cert) and (not os.path.isfile(custom_cert)):
            os.symlink(hostname_cert, custom_cert)
            os.symlink(hostname_key, custom_key)

def get_bundle_for_cn(cn, relation_name=None):
    """Extract certificates for the given cn.

    :param cn: str Canonical Name on certificate.
    :param relation_name: str Relation to check for certificates down.
    :returns: Dictionary of certificate data,
    :rtype: dict."""
    entries = get_requests_for_local_unit(relation_name)
    cert_bundle = {}
    for entry in entries:
        for _cn, bundle in entry['certs'].items():
            if _cn == cn:
                cert_bundle = {'cert': bundle['cert'], 'key': bundle['key'], 'chain': entry['chain'], 'ca': entry['ca']}
                break
        if cert_bundle:
            break
    return cert_bundle

def render(template, extra={}, **kwargs):
    """Return the template rendered using Python's str.format()."""
    context = hookenv.execution_environment()
    context.update(extra)
    context.update(kwargs)
    return template.format(**context)

def _config_section(config, section):
    """Read the configuration file and return a section."""
    path = os.path.join(config.get('config_path'), config.get('config_file'))
    conf = _config_ini(path)
    return conf.get(section)

def validate_file_ownership(config):
    """Verify that configuration files are owned by the correct user/group."""
    files = config.get('files', {})
    for file_name, options in files.items():
        for key in options.keys():
            if key not in ['owner', 'group', 'mode']:
                raise RuntimeError('Invalid ownership configuration: {}'.format(key))
        owner = options.get('owner', config.get('owner', 'root'))
        group = options.get('group', config.get('group', 'root'))
        optional = options.get('optional', config.get('optional', 'False'))
        if '*' in file_name:
            for file in glob.glob(file_name):
                if file not in files.keys():
                    if os.path.isfile(file):
                        _validate_file_ownership(owner, group, file, optional)
        elif os.path.isfile(file_name):
            _validate_file_ownership(owner, group, file_name, optional)

def validate_file_permissions(config):
    """Verify that permissions on configuration files are secure enough."""
    files = config.get('files', {})
    for file_name, options in files.items():
        for key in options.keys():
            if key not in ['owner', 'group', 'mode']:
                raise RuntimeError('Invalid ownership configuration: {}'.format(key))
        mode = options.get('mode', config.get('permissions', '600'))
        optional = options.get('optional', config.get('optional', 'False'))
        if '*' in file_name:
            for file in glob.glob(file_name):
                if file not in files.keys():
                    if os.path.isfile(file):
                        _validate_file_mode(mode, file, optional)
        elif os.path.isfile(file_name):
            _validate_file_mode(mode, file_name, optional)

def service_restart(service_name):
    """Wrapper around host.service_restart to prevent spurious "unknown service"
    messages in the logs."""
    if host.service_available(service_name):
        if host.service_running(service_name):
            host.service_restart(service_name)
        else:
            host.service_start(service_name)

def is_ipv6_ok(soft_fail=False):
    """Check if IPv6 support is present and ip6tables functional

    :param soft_fail: If set to True and IPv6 support is broken, then reports
                      that the host doesn't have IPv6 support, otherwise a
                      UFWIPv6Error exception is raised.
    :returns: True if IPv6 is working, False otherwise"""
    if os.path.isdir('/proc/sys/net/ipv6'):
        if not is_module_loaded('ip6_tables'):
            try:
                modprobe('ip6_tables')
                return True
            except subprocess.CalledProcessError as ex:
                hookenv.log("Couldn't load ip6_tables module: %s" % ex.output, level='WARN')
                if soft_fail:
                    return False
                else:
                    raise UFWIPv6Error('IPv6 firewall support broken')
        else:
            return True
    else:
        return False

def disable_ipv6():
    """Disable ufw IPv6 support in /etc/default/ufw"""
    exit_code = subprocess.call(['sed', '-i', 's/IPV6=.*/IPV6=no/g', '/etc/default/ufw'])
    if exit_code == 0:
        hookenv.log('IPv6 support in ufw disabled', level='INFO')
    else:
        hookenv.log("Couldn't disable IPv6 support in ufw", level='ERROR')
        raise UFWError("Couldn't disable IPv6 support in ufw")

def service(name, action):
    """Open/close access to a service

    :param name: could be a service name defined in `/etc/services` or a port
                 number.
    :param action: `open` or `close`"""
    if action == 'open':
        subprocess.check_output(['ufw', 'allow', str(name)], universal_newlines=True)
    elif action == 'close':
        subprocess.check_output(['ufw', 'delete', 'allow', str(name)], universal_newlines=True)
    else:
        raise UFWError("'{}' not supported, use 'allow' or 'delete'".format(action))

def rmmod(module, force=False):
    """Remove a module from the linux kernel"""
    cmd = ['rmmod']
    if force:
        cmd.append('-f')
    cmd.append(module)
    log('Removing kernel module %s' % module, level=INFO)
    return subprocess.check_call(cmd)

def get_config():
    """Gather and sanity-check volume configuration data"""
    volume_config = {}
    config = hookenv.config()
    errors = False
    if config.get('volume-ephemeral') in (True, 'True', 'true', 'Yes', 'yes'):
        volume_config['ephemeral'] = True
    else:
        volume_config['ephemeral'] = False
    try:
        volume_map = yaml.safe_load(config.get('volume-map', '{}'))
    except yaml.YAMLError as e:
        hookenv.log('Error parsing YAML volume-map: {}'.format(e), hookenv.ERROR)
        errors = True
    if volume_map is None:
        volume_map = {}
    elif not isinstance(volume_map, dict):
        hookenv.log('Volume-map should be a dictionary, not {}'.format(type(volume_map)))
        errors = True
    volume_config['device'] = volume_map.get(os.environ['JUJU_UNIT_NAME'])
    if volume_config['device'] and volume_config['ephemeral']:
        hookenv.log('A volume is defined for this unit, but ephemeral storage was requested', hookenv.ERROR)
        errors = True
    elif not volume_config['device'] and (not volume_config['ephemeral']):
        hookenv.log('Ephemeral storage was requested, but there is no volume defined for this unit.', hookenv.ERROR)
        errors = True
    unit_mount_name = hookenv.local_unit().replace('/', '-')
    volume_config['mountpoint'] = os.path.join(MOUNT_BASE, unit_mount_name)
    if errors:
        return None
    return volume_config

def install_alternative(name, target, source, priority=50):
    """Install alternative configuration"""
    if os.path.exists(target) and (not os.path.islink(target)):
        shutil.move(target, '{}.bak'.format(target))
    cmd = ['update-alternatives', '--force', '--install', target, name, source, str(priority)]
    subprocess.check_call(cmd)

def ensure_packages(packages):
    """Install but do not upgrade required plugin packages."""
    required = filter_installed_packages(packages)
    if required:
        apt_install(required, fatal=True)

def execd_module_paths(execd_dir=None):
    """Generate a list of full paths to modules within execd_dir."""
    if not execd_dir:
        execd_dir = default_execd_dir()
    if not os.path.exists(execd_dir):
        return
    for subpath in os.listdir(execd_dir):
        module = os.path.join(execd_dir, subpath)
        if os.path.isdir(module):
            yield module

def execd_submodule_paths(command, execd_dir=None):
    """Generate a list of full paths to the specified command within exec_dir.
    """
    for module_path in execd_module_paths(execd_dir):
        path = os.path.join(module_path, command)
        if os.access(path, os.X_OK) and os.path.isfile(path):
            yield path

def execd_run(command, execd_dir=None, die_on_error=True, stderr=subprocess.STDOUT):
    """Run command for each module within execd_dir which defines it."""
    for submodule_path in execd_submodule_paths(command, execd_dir):
        try:
            subprocess.check_output(submodule_path, stderr=stderr, universal_newlines=True)
        except subprocess.CalledProcessError as e:
            hookenv.log('Error ({}) running  {}. Output: {}'.format(e.returncode, e.cmd, e.output))
            if die_on_error:
                sys.exit(e.returncode)

def add_bridge_port(name, port, promisc=False):
    """Add a port to the named openvswitch bridge"""
    log('Adding port {} to bridge {}'.format(port, name))
    subprocess.check_call(['ovs-vsctl', '--', '--may-exist', 'add-port', name, port])
    subprocess.check_call(['ip', 'link', 'set', port, 'up'])
    if promisc:
        subprocess.check_call(['ip', 'link', 'set', port, 'promisc', 'on'])
    else:
        subprocess.check_call(['ip', 'link', 'set', port, 'promisc', 'off'])

def is_linuxbridge_interface(port):
    """Check if the interface is a linuxbridge bridge
    :param port: Name of an interface to check whether it is a Linux bridge
    :returns: True if port is a Linux bridge"""
    if os.path.exists('/sys/class/net/' + port + '/bridge'):
        log('Interface {} is a Linux bridge'.format(port), level=DEBUG)
        return True
    else:
        log('Interface {} is not a Linux bridge'.format(port), level=DEBUG)
        return False

def check_for_eni_source():
    """Juju removes the source line when setting up interfaces,
    replace if missing"""
    with open('/etc/network/interfaces', 'r') as eni:
        for line in eni:
            if line == 'source /etc/network/interfaces.d/*':
                return
    with open('/etc/network/interfaces', 'a') as eni:
        eni.write('\nsource /etc/network/interfaces.d/*')

def get_argument_parser(name=None, **kwargs):
    """Returns the global ArgumentParser instance with the given name. The 1st
    time this function is called, a new ArgumentParser instance will be created
    for the given name, and any args other than "name" will be passed on to the
    ArgumentParser constructor."""
    if name is None:
        name = 'default'
    if len(kwargs) > 0 or name not in _parsers:
        init_argument_parser(name, **kwargs)
    return _parsers[name]

def eval(lisp):
    """plash lisp is one dimensional lisp."""
    macro_values = []
    if not isinstance(lisp, list):
        raise EvalError('eval root element must be a list')
    for item in lisp:
        if not isinstance(item, list):
            raise EvalError('must evaluate list of list')
        if not all((isinstance(i, str) for i in item)):
            raise EvalError('must evaluate list of list of strings. not a list of strings: {}'.format(item))
        name = item[0]
        args = item[1:]
        try:
            macro = state['macros'][name]
        except KeyError:
            raise MacroNotFoundError('macro {} not found'.format(repr(name)))
        try:
            res = macro(*args)
        except Exception as exc:
            if os.getenv('PLASH_DEBUG', '').lower() in ('1', 'yes', 'true'):
                raise
            if isinstance(exc, MacroError):
                raise
            raise MacroError(macro, name, sys.exc_info())
        if not isinstance(res, str) and res is not None:
            raise EvalError('eval macro must return string or None ({} returned {})'.format(name, type(res)))
        if res is not None:
            macro_values.append(res)
    return '\n'.join(macro_values)

def plash_map(*args):
    from subprocess import check_output
    'thin wrapper around plash map'
    out = check_output(['plash', 'map'] + list(args))
    if out == '':
        return None
    return out.decode().strip('\n')

def defpm(name, *lines):
    """define a new package manager"""
    @register_macro(name, group='package managers')
    @shell_escape_args
    def package_manager(*packages):
        if not packages:
            return
        sh_packages = ' '.join((pkg for pkg in packages))
        expanded_lines = [line.format(sh_packages) for line in lines]
        return eval([['run'] + expanded_lines])
    package_manager.__doc__ = 'install packages with {}'.format(name)

def layer(command=None, *args):
    """hints the start of a new layer"""
    if not command:
        return eval([['hint', 'layer']])
    else:
        lst = [['layer']]
        for arg in args:
            lst.append([command, arg])
            lst.append(['layer'])
        return eval(lst)

def import_env(*envs):
    """import environment variables from host"""
    for env in envs:
        parts = env.split(':', 1)
        if len(parts) == 1:
            export_as = env
        else:
            env, export_as = parts
        env_val = os.environ.get(env)
        if env_val is not None:
            yield '{}={}'.format(export_as, shlex.quote(env_val))

def write_file(fname, *lines):
    """write lines to a file"""
    yield 'touch {}'.format(fname)
    for line in lines:
        yield 'echo {} >> {}'.format(line, fname)

def eval_string(stri):
    """evaluate expressions passed as string"""
    tokens = shlex.split(stri)
    return run_write_read(['plash', 'eval'], '\n'.join(tokens).encode()).decode()

def entrypoint_script(*lines):
    """write lines to /entrypoint and hint it as default command"""
    lines = list(lines)
    if lines and (not lines[0].startswith('#!')):
        lines.insert(0, '#!/bin/sh')
    return eval([['entrypoint', '/entrypoint'], ['write-script', '/entrypoint'] + lines])

def from_map(map_key):
    """use resolved map as image"""
    image_id = subprocess.check_output(['plash', 'map', map_key]).decode().strip('\n')
    if not image_id:
        raise MapDoesNotExist('map {} not found'.format(repr(map_key)))
    return hint('image', image_id)

def json_datetime_serial(obj):
    """JSON serializer for objects not serializable by default json code"""
    if isinstance(obj, (datetime, date)):
        serial = obj.isoformat()
        return serial
    if ObjectId is not None and isinstance(obj, ObjectId):
        return str(obj)
    raise TypeError('Type not serializable')

def validate_query_structure(query):
    """Validate query arguments in list request.

    :param query: mapping with pagination and filtering information"""
    query_dict = dict(query)
    filters = query_dict.pop('_filters', None)
    if filters:
        try:
            f = json.loads(filters)
        except ValueError:
            msg = '_filters field can not be serialized'
            raise JsonValidaitonError(msg)
        else:
            query_dict['_filters'] = f
    try:
        q = ListQuery(query_dict)
    except t.DataError as exc:
        msg = '_filters query invalid'
        raise JsonValidaitonError(msg, **as_dict(exc))
    return q

def full_dict(ldict, keys):
    """Return Comparison Dictionaries
    from list dict on keys
    keys: a list of keys that when
    combined make the row in the list unique"""
    if type(keys) == str:
        keys = [keys]
    else:
        keys = keys
    cmp_dict = {}
    for line in ldict:
        index = []
        for key in keys:
            index.append(str(line.get(key, '')))
        index = '-'.join(index)
        cmp_dict[index] = line
    return cmp_dict

