def makedirs(*args, **kwargs):
    """Wrapper around os.makedirs that doesn't raise an exception if the
    directory already exists."""
    try:
        os.makedirs(*args, **kwargs)
    except OSError as ex:
        if ex.errno != errno.EEXIST:
            raise

def strip_headers(text):
    """Remove lines that are part of the Project Gutenberg header or footer.
    Note: this function is a port of the C++ utility by Johannes Krugel. The
    original version of the code can be found at:
    http://www14.in.tum.de/spp1307/src/strip_headers.cpp

    Args:
        text (unicode): The body of the text to clean up.

    Returns:
        unicode: The text with any non-text content removed."""
    lines = text.splitlines()
    sep = str(os.linesep)
    out = []
    i = 0
    footer_found = False
    ignore_section = False
    for line in lines:
        reset = False
        if i <= 600:
            if any((line.startswith(token) for token in TEXT_START_MARKERS)):
                reset = True
            if reset:
                out = []
                continue
        if i >= 100:
            if any((line.startswith(token) for token in TEXT_END_MARKERS)):
                footer_found = True
            if footer_found:
                break
        if any((line.startswith(token) for token in LEGALESE_START_MARKERS)):
            ignore_section = True
            continue
        elif any((line.startswith(token) for token in LEGALESE_END_MARKERS)):
            ignore_section = False
            continue
        if not ignore_section:
            out.append(line.rstrip(sep))
            i += 1
    return sep.join(out)

def _create_metadata_cache(cache_location):
    """Creates a new metadata cache instance appropriate for this platform.

    """
    cache_url = os.getenv('GUTENBERG_FUSEKI_URL')
    if cache_url:
        return FusekiMetadataCache(cache_location, cache_url)
    try:
        return SleepycatMetadataCache(cache_location)
    except InvalidCacheException:
        logging.warning('Unable to create cache based on BSD-DB. Falling back to SQLite backend. Performance may be degraded significantly.')
    return SqliteMetadataCache(cache_location)

def all_subclasses(cls):
    """Recursively returns all the subclasses of the provided class.

    """
    subclasses = cls.__subclasses__()
    descendants = (descendant for subclass in subclasses for descendant in all_subclasses(subclass))
    return set(subclasses) | set(descendants)

def wrap(value):
    """Wraps the given value in a Document or DocumentList as applicable."""
    if isinstance(value, Document) or isinstance(value, DocumentList):
        return value
    elif isinstance(value, dict):
        return Document(value)
    elif isinstance(value, list):
        return DocumentList(value)
    else:
        return value

def unwrap(value):
    """Unwraps the given Document or DocumentList as applicable."""
    if isinstance(value, Document):
        return value.to_dict()
    elif isinstance(value, DocumentList):
        return value.to_list()
    else:
        return value

def query_params(*frb_fred_params):
    """Decorator that pops all accepted parameters from method's kwargs and puts
    them in the params argument. Modeled after elasticsearch-py client utils strategy.
    See https://github.com/elastic/elasticsearch-py/blob/3400179153cc13b6ae2c26734337202569bdfd80/elasticsearch/client/utils.py"""
    def _wrapper(func):
        @wraps(func)
        def _wrapped(*args, **kwargs):
            params = kwargs.pop('params', {})
            for p in frb_fred_params:
                if p in kwargs:
                    params[p] = kwargs.pop(p)
            return func(*args, params=params, **kwargs)
        return _wrapped
    return _wrapper

def _convert(frame):
    """Helper funcation to build a parameterized url."""
    frame = frame.convert_objects(convert_numeric=True)
    for column in frame:
        if column in c.dates:
            frame[column] = frame[column].astype('datetime64')
    return frame

def _dict(content):
    """Helper funcation that converts text-based get response
    to a python dictionary for additional manipulation."""
    if _has_pandas:
        data = _data_frame(content).to_dict(orient='records')
    else:
        response = loads(content)
        key = [x for x in response.keys() if x in c.response_data][0]
        data = response[key]
    return data

