def get_reviews(obj):
    """Simply returns the reviews for an object."""
    ctype = ContentType.objects.get_for_model(obj)
    return models.Review.objects.filter(content_type=ctype, object_id=obj.id)

def get_review_average(obj):
    """Returns the review average for an object."""
    total = 0
    reviews = get_reviews(obj)
    if not reviews:
        return False
    for review in reviews:
        average = review.get_average_rating()
        if average:
            total += review.get_average_rating()
    if total > 0:
        return total / reviews.count()
    return False

def render_category_averages(obj, normalize_to=100):
    """Renders all the sub-averages for each category."""
    context = {'reviewed_item': obj}
    ctype = ContentType.objects.get_for_model(obj)
    reviews = models.Review.objects.filter(content_type=ctype, object_id=obj.id)
    category_averages = {}
    for review in reviews:
        review_category_averages = review.get_category_averages(normalize_to)
        if review_category_averages:
            for category, average in review_category_averages.items():
                if category not in category_averages:
                    category_averages[category] = review_category_averages[category]
                else:
                    category_averages[category] += review_category_averages[category]
    if reviews and category_averages:
        for category, average in category_averages.items():
            category_averages[category] = category_averages[category] / models.Rating.objects.filter(category=category, value__isnull=False, review__content_type=ctype, review__object_id=obj.id).exclude(value='').count()
    else:
        category_averages = {}
        for category in models.RatingCategory.objects.filter(counts_for_average=True):
            category_averages[category] = 0.0
    context.update({'category_averages': category_averages})
    return context

def total_review_average(obj, normalize_to=100):
    """Returns the average for all reviews of the given object."""
    ctype = ContentType.objects.get_for_model(obj)
    total_average = 0
    reviews = models.Review.objects.filter(content_type=ctype, object_id=obj.id)
    for review in reviews:
        total_average += review.get_average_rating(normalize_to)
    if reviews:
        total_average /= reviews.count()
    return total_average

def user_has_reviewed(obj, user):
    """Returns True if the user has already reviewed the object."""
    ctype = ContentType.objects.get_for_model(obj)
    try:
        models.Review.objects.get(user=user, content_type=ctype, object_id=obj.id)
    except models.Review.DoesNotExist:
        return False
    return True

def parse(value: ULIDPrimitive) -> ulid.ULID:
    """Create a new :class:`~ulid.ulid.ULID` instance from the given value.

    .. note:: This method should only be used when the caller is trying to parse a ULID from
    a value when they're unsure what format/primitive type it will be given in.

    :param value: ULID value of any supported type
    :type value: :class:`~ulid.api.ULIDPrimitive`
    :return: ULID from value
    :rtype: :class:`~ulid.ulid.ULID`
    :raises ValueError: when unable to parse a ULID from the value"""
    if isinstance(value, ulid.ULID):
        return value
    if isinstance(value, uuid.UUID):
        return from_uuid(value)
    if isinstance(value, str):
        len_value = len(value)
        if len_value == 36:
            return from_uuid(uuid.UUID(value))
        if len_value == 32:
            return from_uuid(uuid.UUID(value))
        if len_value == 26:
            return from_str(value)
        if len_value == 16:
            return from_randomness(value)
        if len_value == 10:
            return from_timestamp(value)
        raise ValueError('Cannot create ULID from string of length {}'.format(len_value))
    if isinstance(value, (int, float)):
        return from_int(int(value))
    if isinstance(value, (bytes, bytearray)):
        return from_bytes(value)
    if isinstance(value, memoryview):
        return from_bytes(value.tobytes())
    raise ValueError('Cannot create ULID from type {}'.format(value.__class__.__name__))

def from_int(value: int) -> ulid.ULID:
    """Create a new :class:`~ulid.ulid.ULID` instance from the given :class:`~int` value.

    :param value: 128 bit integer
    :type value: :class:`~int`
    :return: ULID from integer value
    :rtype: :class:`~ulid.ulid.ULID`
    :raises ValueError: when the value is not a 128 bit integer"""
    if value < 0:
        raise ValueError('Expects positive integer')
    length = (value.bit_length() + 7) // 8
    if length > 16:
        raise ValueError('Expects integer to be 128 bits; got {} bytes'.format(length))
    return ulid.ULID(value.to_bytes(16, byteorder='big'))

def decode(value: str) -> bytes:
    """Decode the given Base32 encoded :class:`~str` instance to :class:`~bytes`.

    .. note:: You should only use this method if you've got a :class:`~str` instance
        and you are unsure of what it represents. If you know the the _meaning_ of the
        :class:`~str` instance, you should call the `decode_*` method explicitly for
        better performance.

    :param value: String to decode
    :type value: :class:`~str`
    :return: Value decoded from Base32 string
    :rtype: :class:`~bytes`
    :raises ValueError: when value is not 10, 16, or 26 characters
    :raises ValueError: when value cannot be encoded in ASCII"""
    length = len(value)
    if length == 26:
        return decode_ulid(value)
    if length == 10:
        return decode_timestamp(value)
    if length == 16:
        return decode_randomness(value)
    raise ValueError('Expects string in lengths of 10, 16, or 26; got {}'.format(length))

def str_to_bytes(value: str, expected_length: int) -> bytes:
    """Convert the given string to bytes and validate it is within the Base32 character set.

    :param value: String to convert to bytes
    :type value: :class:`~str`
    :param expected_length: Expected length of the input string
    :type expected_length: :class:`~int`
    :return: Value converted to bytes.
    :rtype: :class:`~bytes`"""
    length = len(value)
    if length != expected_length:
        raise ValueError('Expects {} characters for decoding; got {}'.format(expected_length, length))
    try:
        encoded = value.encode('ascii')
    except UnicodeEncodeError as ex:
        raise ValueError('Expects value that can be encoded in ASCII charset: {}'.format(ex))
    decoding = DECODING
    for byte in encoded:
        if decoding[byte] > 31:
            raise ValueError('Non-base32 character found: "{}"'.format(chr(byte)))
    return encoded

def _try_methods(methods, to_find=None):
    """Runs the methods specified by _hunt_for_mac().

    We try every method and see if it returned a MAC address. If it returns
    None or raises an exception, we continue and try the next method."""
    found = None
    for m in methods:
        try:
            if isinstance(m, tuple):
                for arg in m[3]:
                    if DEBUG:
                        log.debug("Trying: '%s %s'", m[2], arg)
                    found = _search(m[0], _popen(m[2], arg), m[1])
                    if DEBUG:
                        log.debug('Result: %s\n', found)
                    if found:
                        break
            elif callable(m):
                if DEBUG:
                    log.debug("Trying: '%s' (to_find: '%s')", m.__name__, str(to_find))
                if to_find is not None:
                    found = m(to_find)
                else:
                    found = m()
                if DEBUG:
                    log.debug('Result: %s\n', found)
            else:
                log.critical("Invalid type '%s' for method '%s'", type(m), str(m))
        except Exception as ex:
            if DEBUG:
                log.debug('Exception: %s', str(ex))
            if DEBUG >= 2:
                log.debug(traceback.format_exc())
            continue
        if found:
            break
    return found

def _get_default_iface_linux():
    """Get the default interface by reading /proc/net/route.

    This is the same source as the `route` command, however it's much
    faster to read this file than to call `route`. If it fails for whatever
    reason, we can fall back on the system commands (e.g for a platform
    that has a route command, but maybe doesn't use /proc?)."""
    data = _read_file('/proc/net/route')
    if data is not None and len(data) > 1:
        for line in data.split('\n')[1:-1]:
            iface_name, dest = line.split('\t')[:2]
            if dest == '00000000':
                return iface_name
    return None

def create_cities_csv(filename='places2k.txt', output='cities.csv'):
