    if path:
        pixmap.save(path)
    else:
        image_buffer = QtCore.QBuffer()
        image_buffer.open(QtCore.QIODevice.ReadWrite)
        pixmap.save(image_buffer, 'PNG')
        return image_buffer.data().data()

