def get(obj):
    """Determines file format and picks suitable file types, extensions and MIME types

    Takes:
        obj (bytes) -> byte sequence (128 bytes are enough)

    Returns:
        (<class 'fleep.Info'>) -> Class instance"""
    if not isinstance(obj, bytes):
        raise TypeError('object type must be bytes')
    info = {'type': dict(), 'extension': dict(), 'mime': dict()}
    stream = ' '.join(['{:02X}'.format(byte) for byte in obj])
    for element in data:
        for signature in element['signature']:
            offset = element['offset'] * 2 + element['offset']
            if signature == stream[offset:len(signature) + offset]:
                for key in ['type', 'extension', 'mime']:
                    info[key][element[key]] = len(signature)
    for key in ['type', 'extension', 'mime']:
        info[key] = [element for element in sorted(info[key], key=info[key].get, reverse=True)]
    return Info(info['type'], info['extension'], info['mime'])

def evalHeatKernel(dgm1, dgm2, sigma):
    """Evaluate the continuous heat-based kernel between dgm1 and dgm2 (more correct than L2 on the discretized version above but may be slower because can't exploit fast matrix multiplication when evaluating many, many kernels)"""
    kSigma = 0
    I1 = np.array(dgm1)
    I2 = np.array(dgm2)
    for i in range(I1.shape[0]):
        p = I1[i, 0:2]
        for j in range(I2.shape[0]):
            q = I2[j, 0:2]
            qc = I2[j, 1::-1]
            kSigma += np.exp(-np.sum((p - q) ** 2) / (8 * sigma)) - np.exp(-np.sum((p - qc) ** 2) / (8 * sigma))
    return kSigma / (8 * np.pi * sigma)

def contains_plural_field(model, fields):
    """Returns a boolean indicating if ``fields`` contains a relationship to multiple items."""
    source_model = model
    for orm_path in fields:
        model = source_model
        bits = orm_path.lstrip('+-').split('__')
        for bit in bits[:-1]:
            field = model._meta.get_field(bit)
            if field.many_to_many or field.one_to_many:
                return True
            model = get_model_at_related_field(model, bit)
    return False

def get_column_for_modelfield(model_field):
    """Return the built-in Column class for a model field class."""
    while model_field.related_model:
        model_field = model_field.related_model._meta.pk
    for ColumnClass, modelfield_classes in COLUMN_CLASSES:
        if isinstance(model_field, tuple(modelfield_classes)):
            return ColumnClass

def get_declared_columns(bases, attrs, with_base_columns=True):
    """Create a list of form field instances from the passed in 'attrs', plus any
    similar fields on the base classes (in 'bases'). This is used by both the
    Form and ModelForm metclasses.

    If 'with_base_columns' is True, all fields from the bases are used.
    Otherwise, only fields in the 'declared_fields' attribute on the bases are
    used. The distinction is useful in ModelForm subclassing.
    Also integrates any additional media definitions"""
    local_columns = [(column_name, attrs.pop(column_name)) for column_name, obj in list(six.iteritems(attrs)) if isinstance(obj, Column)]
    local_columns.sort(key=lambda x: x[1].creation_counter)
    if with_base_columns:
        for base in bases[::-1]:
            if hasattr(base, 'base_columns'):
                local_columns = list(six.iteritems(base.base_columns)) + local_columns
    else:
        for base in bases[::-1]:
            if hasattr(base, 'declared_columns'):
                local_columns = list(six.iteritems(base.declared_columns)) + local_columns
    return OrderedDict(local_columns)

def get_field_definition(field_definition):
    """Normalizes a field definition into its component parts, even if some are missing."""
    if not isinstance(field_definition, (tuple, list)):
        field_definition = [field_definition]
    else:
        field_definition = list(field_definition)
    if len(field_definition) == 1:
        field = [None, field_definition, None]
    elif len(field_definition) == 2:
        field = field_definition + [None]
    elif len(field_definition) == 3:
        field = field_definition
    else:
        raise ValueError('Invalid field definition format.')
    if not isinstance(field[1], (tuple, list)):
        field[1] = (field[1],)
    field[1] = tuple((name for name in field[1] if name is not None))
    return FieldDefinitionTuple(*field)

def get_cache_key(datatable_class, view=None, user=None, **kwargs):
    """Returns a cache key unique to the current table, and (if available) the request user.

    The ``view`` argument should be the class reference itself, since it is easily obtainable
    in contexts where the instance is not available."""
    datatable_name = datatable_class.__name__
    if datatable_name.endswith('_Synthesized'):
        datatable_name = datatable_name[:-12]
    datatable_id = '%s.%s' % (datatable_class.__module__, datatable_name)
    if CACHE_KEY_HASH:
        datatable_id = _hash_key_component(datatable_id)
    cache_key = 'datatable_%s' % (datatable_id,)
    if view:
        if not inspect.isclass(view):
            view = view.__class__
        view_id = '%s.%s' % (view.__module__, view.__name__)
        if CACHE_KEY_HASH:
            view_id = _hash_key_component(view_id)
        cache_key += '__view_%s' % (view_id,)
    if user and user.is_authenticated():
        cache_key += '__user_%s' % (user.pk,)
    items = sorted(kwargs.items(), key=lambda item: item[0])
    values = []
    for k, v in items:
        values.append('%r:%r' % (k, v))
    if values:
        kwargs_id = '__'.join(values)
        kwargs_id = _hash_key_component(kwargs_id)
        cache_key += '__kwargs_%s' % (kwargs_id,)
    log.debug('Cache key derived for %r: %r (from kwargs %r)', datatable_class, cache_key, values)
    return cache_key

def format_date(format_string, localize=False, key=None):
    """A pre-called helper to supply a date format string ahead of time, so that it can apply to each
    date or datetime that this column represents.  With Django >= 1.5, the ``localize=True`` keyword
    argument can be given, or else can be supplied in the column's own declaration for the same
    effect.  (The date and datetime columns explicitly forward their ``localize`` setting to all
    helpers.)

    If the ``key`` argument is given, it may be a function which maps the target value to something
    else before the date formatting takes place."""
    if localize is not False and localtime is None:
        raise Exception("Cannot use format_date argument 'localize' with Django < 1.5")
    def helper(value, *args, **kwargs):
        inner_localize = kwargs.get('localize', localize)
        if inner_localize is not False and localtime is None:
            raise Exception("Cannot use format_date argument 'localize' with Django < 1.5")
        if key:
            value = key(value)
        else:
            value = kwargs.get('default_value', value)
        if not value:
            return ''
        if localize:
            value = localtime(value)
        return value.strftime(format_string)
    if key:
        return keyed_helper(helper)(key=key)
    return helper

def _mktime(time_struct):
    """Custom mktime because Windows can't be arsed to properly do pre-Epoch
    dates, probably because it's busy counting all its chromosomes."""
    try:
        return time.mktime(time_struct)
    except OverflowError:
        dt = datetime.datetime(*time_struct[:6])
        ep = datetime.datetime(1970, 1, 1)
        diff = dt - ep
        ts = diff.days * 24 * 3600 + diff.seconds + time.timezone
        if time_struct.tm_isdst == 1:
            ts -= 3600
        if time_struct.tm_isdst == -1 and _isdst(dt):
            ts -= 3600
        return ts

def _strftime(pattern, time_struct=time.localtime()):
    """Custom strftime because Windows is shit again.
    """
    try:
        return time.strftime(pattern, time_struct)
    except OSError:
        dt = datetime.datetime.fromtimestamp(_mktime(time_struct))
        original = dt.year
        current = datetime.datetime.now().year
        dt = dt.replace(year=current)
        ts = dt.timestamp()
        if _isdst(dt):
            ts -= 3600
        string = time.strftime(pattern, time.localtime(ts))
        string = string.replace(str(current), str(original))
        return string

def _gmtime(timestamp):
    """Custom gmtime because yada yada.
    """
    try:
        return time.gmtime(timestamp)
    except OSError:
        dt = datetime.datetime(1970, 1, 1) + datetime.timedelta(seconds=timestamp)
        dst = int(_isdst(dt))
        return time.struct_time(dt.timetuple()[:8] + tuple([dst]))

def _dtfromtimestamp(timestamp):
    """Custom datetime timestamp constructor. because Windows. again.
    """
    try:
        return datetime.datetime.fromtimestamp(timestamp)
    except OSError:
        timestamp -= time.timezone
        dt = datetime.datetime(1970, 1, 1) + datetime.timedelta(seconds=timestamp)
        if _isdst(dt):
            timestamp += 3600
            dt = datetime.datetime(1970, 1, 1) + datetime.timedelta(seconds=timestamp)
        return dt

def _dfromtimestamp(timestamp):
    """Custom date timestamp constructor. ditto
    """
    try:
        return datetime.date.fromtimestamp(timestamp)
    except OSError:
        timestamp -= time.timezone
        d = datetime.date(1970, 1, 1) + datetime.timedelta(seconds=timestamp)
        if _isdst(d):
            timestamp += 3600
            d = datetime.date(1970, 1, 1) + datetime.timedelta(seconds=timestamp)
        return d

def guesstype(timestr):
    """Tries to guess whether a string represents a time or a time delta and
    returns the appropriate object.

    :param timestr (required)
        The string to be analyzed"""
    timestr_full = ' {} '.format(timestr)
    if timestr_full.find(' in ') != -1 or timestr_full.find(' ago ') != -1:
        return Chronyk(timestr)
    comps = ['second', 'minute', 'hour', 'day', 'week', 'month', 'year']
    for comp in comps:
        if timestr_full.find(comp) != -1:
            return ChronykDelta(timestr)
    return Chronyk(timestr)

def _round(num):
    """A custom rounding function that's a bit more 'strict'.
    """
    deci = num - math.floor(num)
    if deci > 0.8:
        return int(math.floor(num) + 1)
    else:
        return int(math.floor(num))

def headTail_breaks(values, cuts):
    """head tail breaks helper function"""
    values = np.array(values)
    mean = np.mean(values)
    cuts.append(mean)
    if len(values) > 1:
        return headTail_breaks(values[values >= mean], cuts)
    return cuts

def get_static_folder(app_or_blueprint):
    """Return the static folder of the given Flask app
    instance, or module/blueprint.

    In newer Flask versions this can be customized, in older
    ones (<=0.6) the folder is fixed."""
    if not hasattr(app_or_blueprint, 'static_folder'):
        return path.join(app_or_blueprint.root_path, 'static')
    if not app_or_blueprint.has_static_folder:
        raise TypeError('The referenced blueprint %s has no static folder.' % app_or_blueprint)
    return app_or_blueprint.static_folder

