def _Moran_BV_Matrix_array(variables, w, permutations=0, varnames=None):
    """Base calculation for MORAN_BV_Matrix"""
    if varnames is None:
        varnames = ['x{}'.format(i) for i in range(k)]
    k = len(variables)
    rk = list(range(0, k - 1))
    results = {}
    for i in rk:
        for j in range(i + 1, k):
            y1 = variables[i]
            y2 = variables[j]
            results[i, j] = Moran_BV(y1, y2, w, permutations=permutations)
            results[j, i] = Moran_BV(y2, y1, w, permutations=permutations)
            results[i, j].varnames = {'x': varnames[i], 'y': varnames[j]}
            results[j, i].varnames = {'x': varnames[j], 'y': varnames[i]}
    return results

def with_metaclass(meta, *bases):
    """Create a base class with a metaclass.

    For example, if you have the metaclass

    >>> class Meta(type):
    ...     pass

    Use this as the metaclass by doing

    >>> from symengine.compatibility import with_metaclass
    >>> class MyClass(with_metaclass(Meta, object)):
    ...     pass

    This is equivalent to the Python 2::

        class MyClass(object):
            __metaclass__ = Meta

    or Python 3::

        class MyClass(object, metaclass=Meta):
            pass

    That is, the first argument is the metaclass, and the remaining arguments
    are the base classes. Note that if the base class is just ``object``, you
    may omit it.

    >>> MyClass.__mro__
    (<class 'MyClass'>, <... 'object'>)
    >>> type(MyClass)
    <class 'Meta'>"""
    class metaclass(meta):
        __call__ = type.__call__
        __init__ = type.__init__
        def __new__(cls, name, this_bases, d):
            if this_bases is None:
                return type.__new__(cls, name, (), d)
            return meta(name, bases, d)
    return metaclass('NewBase', None, {})

def _nodes(e):
    """A helper for ordered() which returns the node count of ``e`` which
    for Basic objects is the number of Basic nodes in the expression tree
    but for other objects is 1 (unless the object is an iterable or dict
    for which the sum of nodes is returned)."""
    from .basic import Basic
    if isinstance(e, Basic):
        return e.count(Basic)
    elif iterable(e):
        return 1 + sum((_nodes(ei) for ei in e))
    elif isinstance(e, dict):
        return 1 + sum((_nodes(k) + _nodes(v) for k, v in e.items()))
    else:
        return 1

def ensure_trafaret(trafaret):
    """Helper for complex trafarets, takes trafaret instance or class
    and returns trafaret instance"""
    if isinstance(trafaret, Trafaret):
        return trafaret
    elif isinstance(trafaret, type):
        if issubclass(trafaret, Trafaret):
            return trafaret()
        return Call(lambda val: trafaret(val))
    elif callable(trafaret):
        return Call(trafaret)
    else:
        raise RuntimeError('%r should be instance or subclass of Trafaret' % trafaret)

def catch(checker, *a, **kw):
    """Helper for tests - catch error and return it as dict"""
    try:
        return checker(*a, **kw)
    except DataError as error:
        return error

def extract_error(checker, *a, **kw):
    """Helper for tests - catch error and return it as dict"""
    res = catch_error(checker, *a, **kw)
    if isinstance(res, DataError):
        return res.as_dict()
    return res

def get_deep_attr(obj, keys):
    """Helper for DeepKey"""
    cur = obj
    for k in keys:
        if isinstance(cur, Mapping) and k in cur:
            cur = cur[k]
            continue
        else:
            try:
                cur = getattr(cur, k)
                continue
            except AttributeError:
                pass
        raise DataError(error='Unexistent key')
    return cur

def construct(arg):
    """Shortcut syntax to define trafarets.

    - int, str, float and bool will return t.Int, t.String, t.Float and t.Bool
    - one element list will return t.List
    - tuple or list with several args will return t.Tuple
    - dict will return t.Dict. If key has '?' at the and it will be optional and '?' will be removed
    - any callable will be t.Call
    - otherwise it will be returned as is

    construct is recursive and will try construct all lists, tuples and dicts args"""
    if isinstance(arg, t.Trafaret):
        return arg
    elif isinstance(arg, tuple) or (isinstance(arg, list) and len(arg) > 1):
        return t.Tuple(*(construct(a) for a in arg))
    elif isinstance(arg, list):
        return t.List(construct(arg[0]))
    elif isinstance(arg, dict):
        return t.Dict({construct_key(key): construct(value) for key, value in arg.items()})
    elif isinstance(arg, str):
        return t.Atom(arg)
    elif isinstance(arg, type):
        if arg is int:
            return t.Int()
        elif arg is float:
            return t.Float()
        elif arg is str:
            return t.String()
        elif arg is bool:
            return t.Bool()
        else:
            return t.Type(arg)
    elif callable(arg):
        return t.Call(arg)
    else:
        return arg

def confirm_key(name, confirm_name, trafaret):
    """confirm_key - takes `name`, `confirm_name` and `trafaret`.

    Checks if data['name'] equals data['confirm_name'] and both
    are valid against `trafaret`."""
    def check_(value):
        first, second = (None, None)
        if name in value:
            first = value[name]
        else:
            yield (name, t.DataError('is required'), (name,))
        if confirm_name in value:
            second = value[confirm_name]
        else:
            yield (confirm_name, t.DataError('is required'), (confirm_name,))
        if not (first and second):
            return
        yield (name, t.catch_error(trafaret, first), (name,))
        yield (confirm_name, t.catch_error(trafaret, second), (confirm_name,))
        if first != second:
            yield (confirm_name, t.DataError('must be equal to {}'.format(name)), (confirm_name,))
    return check_

def modify_mempool(mempool, remove=0, add=0, verbose=False):
    """Given a list of txids (mempool), add and remove some items to simulate
    an out of sync mempool."""
    for i in range(remove):
        popped = mempool.pop()
        if verbose:
            print('removed:', popped)
    for i in range(add):
        new_txid = _make_txid()
        mempool.append(new_txid)
        if verbose:
            print('added:', new_txid)
    return mempool

def gen_primes():
    """Generate an infinite sequence of prime numbers.
    """
    D = {}
    q = 2
    while True:
        if q not in D:
            yield q
            D[q * q] = [q]
        else:
            for p in D[q]:
                D.setdefault(p + q, []).append(p)
            del D[q]
        q += 1

def get_optimal_fee(crypto, tx_bytes, **modes):
    """Get the optimal fee based on how big the transaction is. Currently this
    is only provided for BTC. Other currencies will return $0.02 in satoshi."""
    try:
        services = get_optimal_services(crypto, 'get_optimal_fee')
    except NoServicesDefined:
        convert = get_current_price(crypto, 'usd')
        fee = int(0.02 / convert * 100000000.0)
        if modes.get('report_services'):
            return ([None], fee)
        else:
            return fee
    fee = enforce_service_mode(services, OptimalFee, dict(crypto=crypto, tx_bytes=tx_bytes), modes=modes)
    if modes.get('report_services'):
        return (fee[0], int(fee[1]))
    else:
        return int(fee)

def get_onchain_exchange_rates(deposit_crypto=None, withdraw_crypto=None, **modes):
    """Gets exchange rates for all defined on-chain exchange services."""
    from moneywagon.onchain_exchange import ALL_SERVICES
    rates = []
    for Service in ALL_SERVICES:
        srv = Service(verbose=modes.get('verbose', False))
        rates.extend(srv.onchain_exchange_rates())
    if deposit_crypto:
        rates = [x for x in rates if x['deposit_currency']['code'] == deposit_crypto.upper()]
    if withdraw_crypto:
        rates = [x for x in rates if x['withdraw_currency']['code'] == withdraw_crypto.upper()]
    if modes.get('best', False):
        return max(rates, key=lambda x: float(x['rate']))
    return rates

def guess_currency_from_address(address):
    """Given a crypto address, find which currency it likely belongs to.
    Raises an exception if it can't find a match. Raises exception if address
    is invalid."""
    if is_py2:
        fixer = lambda x: int(x.encode('hex'), 16)
    else:
        fixer = lambda x: x
    first_byte = fixer(b58decode_check(address)[0])
    double_first_byte = fixer(b58decode_check(address)[:2])
    hits = []
    for currency, data in crypto_data.items():
        if hasattr(data, 'get'):
            version = data.get('address_version_byte', None)
            if version is not None and version in [double_first_byte, first_byte]:
                hits.append([currency, data['name']])
    if hits:
        return hits
    raise ValueError('Unknown Currency with first byte: %s' % first_byte)

def change_version_byte(address, new_version=None, new_crypto=None):
    """Convert the passed in address (or any base58 encoded string), and change the
    version byte to `new_version`."""
    if not new_version and new_crypto:
        try:
            new_version = crypto_data[new_crypto]['address_version_byte']
        except KeyError:
            raise CurrencyNotSupported('Unknown currency symbol: ' + new_crypto)
        if not new_version:
            raise CurrencyNotSupported("Can't yet make %s addresses." % new_crypto)
    payload = b58decode_check(address)[1:]
    if is_py2:
        byte = chr(new_version)
    else:
        byte = bytes(chr(new_version), 'ascii')
    return b58encode_check(byte + payload)

def service_table(format='simple', authenticated=False):
    """Returns a string depicting all services currently installed."""
    if authenticated:
        all_services = ExchangeUniverse.get_authenticated_services()
    else:
        all_services = ALL_SERVICES
    if format == 'html':
        linkify = lambda x: "<a href='{0}' target='_blank'>{0}</a>".format(x)
