def import_units(module, namespace):
    """Import Unit objects from a module into a namespace"""
    for key, value in module.__dict__.items():
        if isinstance(value, (unyt_quantity, Unit)):
            namespace[key] = value

def _get_unit_data_from_expr(unit_expr, unit_symbol_lut):
    """Grabs the total base_value and dimensions from a valid unit expression.

    Parameters
    ----------
    unit_expr: Unit object, or sympy Expr object
        The expression containing unit symbols.
    unit_symbol_lut: dict
        Provides the unit data for each valid unit symbol."""
    if isinstance(unit_expr, Number):
        if unit_expr is sympy_one:
            return (1.0, sympy_one)
        return (float(unit_expr), sympy_one)
    if isinstance(unit_expr, Symbol):
        return _lookup_unit_symbol(unit_expr.name, unit_symbol_lut)
    if isinstance(unit_expr, Pow):
        unit_data = _get_unit_data_from_expr(unit_expr.args[0], unit_symbol_lut)
        power = unit_expr.args[1]
        if isinstance(power, Symbol):
            raise UnitParseError("Invalid unit expression '%s'." % unit_expr)
        conv = float(unit_data[0] ** power)
        unit = unit_data[1] ** power
        return (conv, unit)
    if isinstance(unit_expr, Mul):
        base_value = 1.0
        dimensions = 1
        for expr in unit_expr.args:
            unit_data = _get_unit_data_from_expr(expr, unit_symbol_lut)
            base_value *= unit_data[0]
            dimensions *= unit_data[1]
        return (float(base_value), dimensions)
    raise UnitParseError("Cannot parse for unit data from '%s'. Please supply an expression of only Unit, Symbol, Pow, and Mulobjects." % str(unit_expr))

def _auto_positive_symbol(tokens, local_dict, global_dict):
    """Inserts calls to ``Symbol`` for undefined variables.
    Passes in positive=True as a keyword argument.
    Adapted from sympy.sympy.parsing.sympy_parser.auto_symbol"""
    result = []
    tokens.append((None, None))
    for tok, nextTok in zip(tokens, tokens[1:]):
        tokNum, tokVal = tok
        nextTokNum, nextTokVal = nextTok
        if tokNum == token.NAME:
            name = tokVal
            if name in global_dict:
                obj = global_dict[name]
                if isinstance(obj, (Basic, type)) or callable(obj):
                    result.append((token.NAME, name))
                    continue
            try:
                used_name = inv_name_alternatives[str(name)]
            except KeyError:
                used_name = str(name)
            result.extend([(token.NAME, 'Symbol'), (token.OP, '('), (token.NAME, repr(used_name)), (token.OP, ','), (token.NAME, 'positive'), (token.OP, '='), (token.NAME, 'True'), (token.OP, ')')])
        else:
            result.append((tokNum, tokVal))
    return result

def _ensure_tree(path):
    """Create a directory (and any ancestor directories required).

    :param path: Directory to create"""
    try:
        os.makedirs(path)
    except OSError as e:
        if e.errno == errno.EEXIST:
            if not os.path.isdir(path):
                raise
            else:
                return False
        elif e.errno == errno.EISDIR:
            return False
        else:
            raise
    else:
        return True

def interprocess_locked(path):
    """Acquires & releases a interprocess lock around call into
    decorated function."""
    lock = InterProcessLock(path)
    def decorator(f):
        @six.wraps(f)
        def wrapper(*args, **kwargs):
            with lock:
                return f(*args, **kwargs)
        return wrapper
    return decorator

def canonicalize_path(path):
    """Canonicalizes a potential path.

    Returns a binary string encoded into filesystem encoding."""
    if isinstance(path, six.binary_type):
        return path
    if isinstance(path, six.text_type):
        return _fsencode(path)
    else:
        return canonicalize_path(str(path))

def read_locked(*args, **kwargs):
    """Acquires & releases a read lock around call into decorated method.

    NOTE(harlowja): if no attribute name is provided then by default the
    attribute named '_lock' is looked for (this attribute is expected to be
    a :py:class:`.ReaderWriterLock`) in the instance object this decorator
    is attached to."""
    def decorator(f):
        attr_name = kwargs.get('lock', '_lock')
        @six.wraps(f)
        def wrapper(self, *args, **kwargs):
            rw_lock = getattr(self, attr_name)
            with rw_lock.read_lock():
                return f(self, *args, **kwargs)
        return wrapper
    if kwargs or not args:
        return decorator
    elif len(args) == 1:
        return decorator(args[0])
    else:
        return decorator

def write_locked(*args, **kwargs):
    """Acquires & releases a write lock around call into decorated method.

    NOTE(harlowja): if no attribute name is provided then by default the
    attribute named '_lock' is looked for (this attribute is expected to be
    a :py:class:`.ReaderWriterLock` object) in the instance object this
    decorator is attached to."""
    def decorator(f):
        attr_name = kwargs.get('lock', '_lock')
        @six.wraps(f)
        def wrapper(self, *args, **kwargs):
            rw_lock = getattr(self, attr_name)
            with rw_lock.write_lock():
                return f(self, *args, **kwargs)
        return wrapper
    if kwargs or not args:
        return decorator
    elif len(args) == 1:
        return decorator(args[0])
    else:
        return decorator

def try_lock(lock):
    """Attempts to acquire a lock, and auto releases if acquired (on exit)."""
    was_locked = lock.acquire(False)
    try:
        yield was_locked
    finally:
        if was_locked:
            lock.release()

def create_document_batches(jsonlines, id_field, max_batch_size=CLOUDSEARCH_MAX_BATCH_SIZE):
    """Create batches in expected AWS Cloudsearch format, limiting the
    byte size per batch according to given max_batch_size

    See: http://docs.aws.amazon.com/cloudsearch/latest/developerguide/preparing-data.html"""
    batch = []
    fixed_initial_size = 2
    def create_entry(line):
        try:
            record = json.loads(line)
        except:
            raise ValueError('Could not parse JSON from: %s' % line)
        key = record[id_field]
        return '{"type":"add","id":%s,"fields":%s}' % (json.dumps(key), line)
    current_size = fixed_initial_size
    for line in jsonlines:
        entry = create_entry(line)
        entry_size = len(entry) + 1
        if max_batch_size > current_size + entry_size:
            current_size += entry_size
            batch.append(entry)
        else:
            yield ('[' + ','.join(batch) + ']')
            batch = [entry]
            current_size = fixed_initial_size + entry_size
    if batch:
        yield ('[' + ','.join(batch) + ']')

def get_boto_connection(aws_access_key_id, aws_secret_access_key, region=None, bucketname=None, host=None):
    """Conection parameters must be different only if bucket name has a period"""
    m = _AWS_ACCESS_KEY_ID_RE.match(aws_access_key_id)
    if m is None or m.group() != aws_access_key_id:
        logging.error('The provided aws_access_key_id is not in the correct format. It must                       be alphanumeric and contain between 16 and 32 characters.')
    if len(aws_access_key_id) > len(aws_secret_access_key):
        logging.warn("The AWS credential keys aren't in the usual size, are you using the correct ones?")
    import boto
    from boto.s3.connection import OrdinaryCallingFormat
    extra_args = {}
    if host is not None:
        extra_args['host'] = host
    if bucketname is not None and '.' in bucketname:
        extra_args['calling_format'] = OrdinaryCallingFormat()
    if region is None:
        return boto.connect_s3(aws_access_key_id, aws_secret_access_key, **extra_args)
    return boto.s3.connect_to_region(region, aws_access_key_id=aws_access_key_id, aws_secret_access_key=aws_secret_access_key, **extra_args)

def maybe_cast_list(value, types):
    """Try to coerce list values into more specific list subclasses in types."""
    if not isinstance(value, list):
        return value
    if type(types) not in (list, tuple):
        types = (types,)
    for list_type in types:
        if issubclass(list_type, list):
            try:
                return list_type(value)
            except (TypeError, ValueError):
                pass
    return value

def iterate_chunks(file, chunk_size):
    """Iterate chunks of size chunk_size from a file-like object"""
    chunk = file.read(chunk_size)
    while chunk:
        yield chunk
        chunk = file.read(chunk_size)

def get_cache_key(path):
    """Create a cache key by concatenating the prefix with a hash of the path."""
    try:
        path_hash = hashlib.md5(path).hexdigest()
    except TypeError:
        path_hash = hashlib.md5(path.encode('utf-8')).hexdigest()
    return settings.cache_key_prefix + path_hash

def get_remote_etag(storage, prefixed_path):
    """Get etag of path from S3 using boto or boto3."""
    normalized_path = safe_join(storage.location, prefixed_path).replace('\\', '/')
    try:
        return storage.bucket.get_key(normalized_path).etag
    except AttributeError:
        pass
    try:
        return storage.bucket.Object(normalized_path).e_tag
    except:
        pass
    return None

def _merge_common_bands(rasters):
    """Combine the common bands.

    """
    all_bands = IndexedSet([rs.band_names[0] for rs in rasters])
    def key(rs):
        return all_bands.index(rs.band_names[0])
    rasters_final = []
    for band_name, rasters_group in groupby(sorted(rasters, key=key), key=key):
        rasters_final.append(reduce(_fill_pixels, rasters_group))
    return rasters_final

def _prepare_rasters(rasters, merge_strategy, first, resampling=Resampling.nearest):
    """Prepares the rasters according to the baseline (first) raster and the merge strategy.

    The baseline (first) raster is used to crop and reproject the other rasters,
    while the merge strategy is used to compute the bands of the result. These
    are returned for diagnostics."""
    all_band_names = IndexedSet(first.band_names)
    projected_rasters = []
    for raster in rasters:
        projected_raster = _prepare_other_raster(first, raster, resampling=resampling)
        if projected_raster:
            if merge_strategy is MergeStrategy.INTERSECTION:
                all_band_names.intersection_update(projected_raster.band_names)
            elif merge_strategy is MergeStrategy.UNION:
                all_band_names.update(projected_raster.band_names)
        projected_rasters.append(projected_raster)
    return (all_band_names, projected_rasters)

def _explode_raster(raster, band_names=[]):
    """Splits a raster into multiband rasters.

    """
    if not band_names:
        band_names = raster.band_names
    else:
        band_names = list(IndexedSet(raster.band_names).intersection(band_names))
    return [_Raster(image=raster.bands_data([band_name]), band_names=[band_name]) for band_name in band_names]

def _stack_bands(one, other):
    """Merges two rasters with non overlapping bands by stacking the bands.

    """
    assert set(one.band_names).intersection(set(other.band_names)) == set()
    if one.band_names == other.band_names:
        raise ValueError('rasters have the same bands, use another merge strategy')
    new_mask = np.ma.getmaskarray(one.image)[0] | np.ma.getmaskarray(other.image)[0]
    new_image = np.ma.masked_array(np.concatenate([one.image.data, other.image.data]), mask=[new_mask] * (one.image.shape[0] + other.image.shape[0]))
    new_bands = one.band_names + other.band_names
    return _Raster(image=new_image, band_names=new_bands)

def dissolve(collection, aggfunc=None):
    """Dissolves features contained in a FeatureCollection and applies an aggregation
    function to its properties."""
    new_properties = {}
    if aggfunc:
        temp_properties = defaultdict(list)
        for feature in collection:
            for key, value in feature.attributes.items():
                temp_properties[key].append(value)
        for key, values in temp_properties.items():
            try:
                new_properties[key] = aggfunc(values)
            except Exception:
                pass
    return GeoFeature(collection.cascaded_union, new_properties)

