def cVectorToPython(x):
    """Convert the c vector data into the correct python data type
    (numpy arrays or strings)
    :param x:
    :return:"""
    if isinstance(x[0], bool):
        return numpy.frombuffer(x, dtype=numpy.bool).copy()
    elif isinstance(x[0], int):
        return numpy.frombuffer(x, dtype=numpy.int32).copy()
    elif isinstance(x[0], float):
        return numpy.frombuffer(x, dtype=numpy.float64).copy()
    elif isinstance(x[0].value, bytes):
        return [toPythonString(y) for y in x]

def stringToCharP(inobject, inlen=None):
    """:param inobject: input string, int for getting null string of length of int
    :param inlen: optional parameter, length of a given string can be specified
    :return:"""
    if inlen and isinstance(inobject, str):
        return create_string_buffer(inobject.encode(encoding='UTF-8'), inlen)
    if isinstance(inobject, bytes):
        return inobject
    if isinstance(inobject, c_int):
        return stringToCharP(' ' * inobject.value)
    if isinstance(inobject, int):
        return stringToCharP(' ' * inobject)
    return c_char_p(inobject.encode(encoding='UTF-8'))

def _process_registry(registry, call_func):
    """Given a dictionary, and a registration function, process the registry"""
    from django.core.exceptions import ImproperlyConfigured
    from django.apps import apps
    for key, value in list(registry.items()):
        model = apps.get_model(*key.split('.'))
        if model is None:
            raise ImproperlyConfigured(_('%(key)s is not a model') % {'key': key})
        if isinstance(value, (tuple, list)):
            for item in value:
                if isinstance(item, str):
                    call_func(model, item)
                elif isinstance(item, dict):
                    field_name = item.pop('name')
                    call_func(model, field_name, extra_params=item)
                else:
                    raise ImproperlyConfigured(_("%(settings)s doesn't recognize the value of %(key)s") % {'settings': 'CATEGORY_SETTINGS', 'key': key})
        elif isinstance(value, str):
            call_func(model, value)
        elif isinstance(value, dict):
            field_name = value.pop('name')
            call_func(model, field_name, extra_params=value)
        else:
            raise ImproperlyConfigured(_("%(settings)s doesn't recognize the value of %(key)s") % {'settings': 'CATEGORY_SETTINGS', 'key': key})

def migrate_app(sender, *args, **kwargs):
    """Migrate all models of this app registered"""
    from .registration import registry
    if 'app_config' not in kwargs:
        return
    app_config = kwargs['app_config']
    app_name = app_config.label
    fields = [fld for fld in list(registry._field_registry.keys()) if fld.startswith(app_name)]
    sid = transaction.savepoint()
    for fld in fields:
        model_name, field_name = fld.split('.')[1:]
        if field_exists(app_name, model_name, field_name):
            continue
        model = app_config.get_model(model_name)
        try:
            with connection.schema_editor() as schema_editor:
                schema_editor.add_field(model, registry._field_registry[fld])
                if sid:
                    transaction.savepoint_commit(sid)
        except ProgrammingError:
            if sid:
                transaction.savepoint_rollback(sid)
            continue

