def get_top_level_categories(parser, token):
    """Retrieves an alphabetical list of all the categories that have no parents.

    Syntax::

        {% get_top_level_categories [using "app.Model"] as categories %}

    Returns an list of categories [<category>, <category>, <category, ...]"""
    bits = token.split_contents()
    usage = 'Usage: {%% %s [using "app.Model"] as <variable> %%}' % bits[0]
    if len(bits) == 3:
        if bits[1] != 'as':
            raise template.TemplateSyntaxError(usage)
        varname = bits[2]
        model = 'categories.category'
    elif len(bits) == 5:
        if bits[1] not in ('as', 'using') and bits[3] not in ('as', 'using'):
            raise template.TemplateSyntaxError(usage)
        if bits[1] == 'using':
            model = bits[2].strip('\'"')
            varname = bits[4].strip('\'"')
        else:
            model = bits[4].strip('\'"')
            varname = bits[2].strip('\'"')
    return TopLevelCategoriesNode(varname, model)

def tree_queryset(value):
    """Converts a normal queryset from an MPTT model to include all the ancestors
    so a filtered subset of items can be formatted correctly"""
    from django.db.models.query import QuerySet
    from copy import deepcopy
    if not isinstance(value, QuerySet):
        return value
    qs = value
    qs2 = deepcopy(qs)
    is_filtered = bool(qs.query.where.children)
    if is_filtered:
        include_pages = set()
        for p in qs2.order_by('rght').iterator():
            if p.parent_id and p.parent_id not in include_pages and (p.id not in include_pages):
                ancestor_id_list = p.get_ancestors().values_list('id', flat=True)
                include_pages.update(ancestor_id_list)
        if include_pages:
            qs = qs | qs.model._default_manager.filter(id__in=include_pages)
        qs = qs.distinct()
    return qs

def recursetree(parser, token):
    """Iterates over the nodes in the tree, and renders the contained block for each node.
    This tag will recursively render children into the template variable {{ children }}.
    Only one database query is required (children are cached for the whole tree)

    Usage:
            <ul>
                {% recursetree nodes %}
                    <li>
                        {{ node.name }}
                        {% if not node.is_leaf_node %}
                            <ul>
                                {{ children }}
                            </ul>
                        {% endif %}
                    </li>
                {% endrecursetree %}
            </ul>"""
    bits = token.contents.split()
    if len(bits) != 2:
        raise template.TemplateSyntaxError('%s tag requires a queryset' % bits[0])
    queryset_var = FilterExpression(bits[1], parser)
    template_nodes = parser.parse(('endrecursetree',))
    parser.delete_first_token()
    return RecurseTreeNode(template_nodes, queryset_var)

def gaussian_filter(data, sigma=4.0, truncate=4.0, normalize=True, res_g=None):
    """blurs data with a gaussian kernel of given sigmas

    Parameters
    ----------
    data: ndarray
        2 or 3 dimensional array
    sigma: scalar or tuple
        the sigma of the gaussian
    truncate: float
        truncate the kernel after truncate*sigma
    normalize: bool
        uses a normalized kernel is true
    res_g: OCLArray
        used to store result if given

    Returns
    -------
        blurred array"""
    if not len(data.shape) in [1, 2, 3]:
        raise ValueError('dim = %s not supported' % len(data.shape))
    if np.isscalar(sigma):
        sigma = [sigma] * data.ndim
    if any(tuple((s <= 0 for s in sigma))):
        raise ValueError('sigma = %s : all sigmas have to be positive!' % str(sigma))
    if isinstance(data, OCLArray):
        return _gaussian_buf(data, sigma, res_g, normalize=normalize, truncate=truncate)
    elif isinstance(data, np.ndarray):
        return _gaussian_np(data, sigma, normalize=normalize, truncate=truncate)
    else:
        raise TypeError('unknown type (%s)' % type(data))

def convolve(data, h, res_g=None, sub_blocks=None):
    """convolves 1d-3d data with kernel h

    data and h can either be numpy arrays or gpu buffer objects (OCLArray,
    which must be float32 then)

    boundary conditions are clamping to zero at edge."""
    if not len(data.shape) in [1, 2, 3]:
        raise ValueError('dim = %s not supported' % len(data.shape))
    if len(data.shape) != len(h.shape):
        raise ValueError('dimemnsion of data (%s) and h (%s) are different' % (len(data.shape), len(h.shape)))
    if isinstance(data, OCLArray) and isinstance(h, OCLArray):
        return _convolve_buf(data, h, res_g)
    elif isinstance(data, np.ndarray) and isinstance(h, np.ndarray):
        if sub_blocks == (1,) * len(data.shape) or sub_blocks is None:
            return _convolve_np(data, h)
        else:
            N_sub = [int(np.ceil(1.0 * n / s)) for n, s in zip(data.shape, sub_blocks)]
            Npads = [int(s / 2) for s in h.shape]
            res = np.empty(data.shape, np.float32)
            for data_tile, data_s_src, data_s_dest in tile_iterator(data, blocksize=N_sub, padsize=Npads, mode='constant'):
                res_tile = _convolve_np(data_tile.copy(), h)
                res[data_s_src] = res_tile[data_s_dest]
            return res
    else:
        raise TypeError('unknown types (%s, %s)' % (type(data), type(h)))

def _convolve_np(data, h):
    """numpy variant"""
    data_g = OCLArray.from_array(np.require(data, np.float32, 'C'))
    h_g = OCLArray.from_array(np.require(h, np.float32, 'C'))
    return _convolve_buf(data_g, h_g).get()

def _convolve_buf(data_g, h_g, res_g=None):
    """buffer variant"""
    assert_bufs_type(np.float32, data_g, h_g)
    prog = OCLProgram(abspath('kernels/convolve.cl'))
    if res_g is None:
        res_g = OCLArray.empty(data_g.shape, dtype=np.float32)
    Nhs = [np.int32(n) for n in h_g.shape]
    kernel_name = 'convolve%sd_buf' % len(data_g.shape)
    try:
        prog.run_kernel(kernel_name, data_g.shape[::-1], None, data_g.data, h_g.data, res_g.data, *Nhs)
    except cl.cffi_cl.LogicError as e:
        if e.code == -52:
            kernel_name = 'convolve%sd_buf_global' % len(data_g.shape)
            prog.run_kernel(kernel_name, data_g.shape[::-1], None, data_g.data, h_g.data, res_g.data, *Nhs)
        else:
            raise e
    except cl.cffi_cl.RuntimeError as e:
        if e.code == -5:
            kernel_name = 'convolve%sd_buf_global' % len(data_g.shape)
            prog.run_kernel(kernel_name, data_g.shape[::-1], None, data_g.data, h_g.data, res_g.data, *Nhs)
        else:
            raise e
    return res_g

def _convolve3_old(data, h, dev=None):
    """convolves 3d data with kernel h on the GPU Device dev
    boundary conditions are clamping to edge.
    h is converted to float32

    if dev == None the default one is used"""
    if dev is None:
        dev = get_device()
    if dev is None:
        raise ValueError('no OpenCLDevice found...')
    dtype = data.dtype.type
    dtypes_options = {np.float32: '', np.uint16: '-D SHORTTYPE'}
    if not dtype in dtypes_options:
        raise TypeError('data type %s not supported yet, please convert to:' % dtype, list(dtypes_options.keys()))
    prog = OCLProgram(abspath('kernels/convolve3.cl'), build_options=dtypes_options[dtype])
    hbuf = OCLArray.from_array(h.astype(np.float32))
    img = OCLImage.from_array(data)
    res = OCLArray.empty(data.shape, dtype=np.float32)
    Ns = [np.int32(n) for n in data.shape + h.shape]
    prog.run_kernel('convolve3d', img.shape, None, img, hbuf.data, res.data, *Ns)
    return res.get()

def _scale_shape(dshape, scale=(1, 1, 1)):
    """returns the shape after scaling (should be the same as ndimage.zoom"""
    nshape = np.round(np.array(dshape) * np.array(scale))
    return tuple(nshape.astype(np.int))

def abspath(myPath):
    import sys, os
    ' Get absolute path to resource, works for dev and for PyInstaller '
    try:
        base_path = sys._MEIPASS
        return os.path.join(base_path, os.path.basename(myPath))
    except Exception:
        base_path = os.path.abspath(os.path.dirname(__file__))
        return os.path.join(base_path, myPath)

def perlin3(size, units=(1.0,) * 3, repeat=(10.0,) * 3, shift=0, scale=None, n_volumes=1):
    """returns a 3d perlin noise array of given size (Nx,Ny,Nz)
    and units (dx,dy,dz) with given repeats (in units)
    by doing the noise calculations on the gpu

    The volume can be splitted into n_volumes pieces if gou memory is not enough

    either scale or units have to be given

    shift = (.1,.1,.2)  or 1. can be used to slide the pattern in each dim (offset = 0 is the original)"""
    if np.isscalar(shift):
        shift = (shift,) * len(size)
    if scale:
        if np.isscalar(scale):
            scale = (scale,) * 3
        repeat = scale
        units = (1.0,) * 3
    if n_volumes == 1:
        return _perlin3_single(size, units, repeat, shift=shift)
    else:
        Nx, Ny, Nz = size
        Nz2 = Nz // n_volumes + 1
        res = np.empty((Nz, Ny, Nx), np.float32)
        res_part = np.empty((Nz2, Ny, Nx), np.float32)
        for i in range(n_volumes):
            i1, i2 = (i * Nz2, np.clip((i + 1) * Nz2, 0, Nz))
            if i < n_volumes - 1:
                res_part = _perlin3_single((Nx, Ny, i2 - i1 + 1), units, shift=shift, repeat=repeat, offz=Nz2 * i, Nz0=Nz)
                res[i1:i2, ...] = res_part[:-1, ...]
            else:
                res_part = _perlin3_single((Nx, Ny, i2 - i1), units, shift=shift, repeat=repeat, offz=Nz2 * i, Nz0=Nz)
                res[i1:i2, ...] = res_part
        return res

def convolve_sep2(data, hx, hy, res_g=None, sub_blocks=None):
    """convolves 2d data with kernel h = outer(hx,hy)
    boundary conditions are clamping to edge.

    data is either np array or a gpu buffer (OCLArray)"""
    if isinstance(data, np.ndarray):
        data = np.ascontiguousarray(data)
        if sub_blocks == (1, 1) or sub_blocks is None:
            return _convolve_sep2_numpy(data, hx, hy)
        else:
            N_sub = [int(np.ceil(1.0 * n / s)) for n, s in zip(data.shape, sub_blocks)]
            Npads = [int(len(_h) / 2) for _h in [hy, hx]]
            res = np.empty(data.shape, np.float32)
            for data_tile, data_s_src, data_s_dest in tile_iterator(data, blocksize=N_sub, padsize=Npads, mode='constant'):
                res_tile = _convolve_sep2_numpy(data_tile.copy(), hx, hy)
                res[data_s_src] = res_tile[data_s_dest]
            return res
    elif isinstance(data, OCLArray):
        if not sub_blocks is None:
            raise NotImplementedError()
        return _convolve_sep2_gpu(data, hx, hy, res_g=res_g)
    else:
        raise TypeError('array argument (1) has bad type: %s' % type(data))

def convolve_sep3(data, hx, hy, hz, res_g=None, sub_blocks=(1, 1, 1), tmp_g=None):
    """convolves 3d data with kernel h = outer(hx,hy, hz)
    boundary conditions are clamping to edge.

    data, hx, hy.... are either np array or a gpu buffer (OCLArray)"""
    if isinstance(data, np.ndarray):
        data = np.ascontiguousarray(data)
        if sub_blocks == (1, 1, 1) or sub_blocks is None:
            return _convolve_sep3_numpy(data, hx, hy, hz)
        else:
            N_sub = [int(np.ceil(1.0 * n / s)) for n, s in zip(data.shape, sub_blocks)]
            Npads = [int(len(_h) / 2) for _h in [hz, hy, hx]]
            res = np.empty(data.shape, np.float32)
            for i, (data_tile, data_s_src, data_s_dest) in enumerate(tile_iterator(data, blocksize=N_sub, padsize=Npads, mode='constant')):
                res_tile = _convolve_sep3_numpy(data_tile.copy(), hx, hy, hz)
                res[data_s_src] = res_tile[data_s_dest]
            return res
    elif isinstance(data, OCLArray):
        return _convolve_sep3_gpu(data, hx, hy, hz, res_g=res_g, tmp_g=tmp_g)
    else:
        raise TypeError('array argument (1) has bad type: %s' % type(data))

def bilateral2(data, fSize, sigma_p, sigma_x=10.0):
    """bilateral filter"""
    dtype = data.dtype.type
    dtypes_kernels = {np.float32: 'bilat2_float', np.uint16: 'bilat2_short'}
    if not dtype in dtypes_kernels:
        logger.info('data type %s not supported yet (%s), casting to float:' % (dtype, list(dtypes_kernels.keys())))
        data = data.astype(np.float32)
        dtype = data.dtype.type
    img = OCLImage.from_array(data)
    res = OCLArray.empty_like(data)
    prog = OCLProgram(abspath('kernels/bilateral2.cl'))
    prog.run_kernel(dtypes_kernels[dtype], img.shape, None, img, res.data, np.int32(img.shape[0]), np.int32(img.shape[1]), np.int32(fSize), np.float32(sigma_x), np.float32(sigma_p))
    return res.get()

