def fft_convolve(data, h, res_g=None, plan=None, inplace=False, kernel_is_fft=False, kernel_is_fftshifted=False):
    """convolves data with kernel h via FFTs


    data should be either a numpy array or a OCLArray (see doc for fft)
    both data and h should be same shape

    if data/h are OCLArrays, then:
        - type should be complex64
        - shape should be equal and power of two
        - h is assumed to be already fftshifted
         (otherwise set kernel_is_fftshifted  to true)"""
    if isinstance(data, np.ndarray):
        return _fft_convolve_numpy(data, h, plan=plan, kernel_is_fft=kernel_is_fft, kernel_is_fftshifted=kernel_is_fftshifted)
    elif isinstance(data, OCLArray):
        return _fft_convolve_gpu(data, h, res_g=res_g, plan=plan, inplace=inplace, kernel_is_fft=kernel_is_fft)
    else:
        raise TypeError('array argument (1) has bad type: %s' % type(data))

def _fft_convolve_gpu(data_g, h_g, res_g=None, plan=None, inplace=False, kernel_is_fft=False):
    """fft convolve for gpu buffer
    """
    assert_bufs_type(np.complex64, data_g, h_g)
    if data_g.shape != h_g.shape:
        raise ValueError('data and kernel must have same size! %s vs %s ' % (str(data_g.shape), str(h_g.shape)))
    if plan is None:
        plan = fft_plan(data_g.shape)
    if inplace:
        res_g = data_g
    else:
        if res_g is None:
            res_g = OCLArray.empty(data_g.shape, data_g.dtype)
        res_g.copy_buffer(data_g)
    if not kernel_is_fft:
        kern_g = OCLArray.empty(h_g.shape, h_g.dtype)
        kern_g.copy_buffer(h_g)
        fft(kern_g, inplace=True, plan=plan)
    else:
        kern_g = h_g
    fft(res_g, inplace=True, plan=plan)
    _complex_multiply_kernel(res_g, kern_g)
    fft(res_g, inplace=True, inverse=True, plan=plan)
    return res_g

def _convert_axes_to_absolute(dshape, axes):
    """axes = (-2,-1) does not work in reikna, so we have to convetr that"""
    if axes is None:
        return None
    elif isinstance(axes, (tuple, list)):
        return tuple(np.arange(len(dshape))[list(axes)])
    else:
        raise NotImplementedError('axes %s is of unsupported type %s ' % (str(axes), type(axes)))

def fft(arr_obj, res_g=None, inplace=False, inverse=False, axes=None, plan=None, fast_math=True):
    """(inverse) fourier trafo of 1-3D arrays

    creates a new plan or uses the given plan

    the transformed arr_obj should be either a

    - numpy array:

        returns the fft as numpy array (inplace is ignored)

    - OCLArray of type complex64:

        writes transform into res_g if given, to arr_obj if inplace
        or returns a new OCLArray with the transform otherwise"""
    if plan is None:
        plan = fft_plan(arr_obj.shape, arr_obj.dtype, axes=axes, fast_math=fast_math)
    if isinstance(arr_obj, np.ndarray):
        return _ocl_fft_numpy(plan, arr_obj, inverse=inverse)
    elif isinstance(arr_obj, OCLArray):
        if not arr_obj.dtype.type is np.complex64:
            raise TypeError('OCLArray arr_obj has to be of complex64 type')
        if inplace:
            _ocl_fft_gpu_inplace(plan, arr_obj, inverse=inverse)
        else:
            raise NotImplementedError('currently only inplace fft is supported (FIXME)')
            return _ocl_fft_gpu(plan, arr_obj, res_arr=res_g, inverse=inverse)
    else:
        raise TypeError('array argument (1) has bad type: %s' % type(arr_obj))

def pad_to_shape(d, dshape, mode='constant'):
    """pad array d to shape dshape"""
    if d.shape == dshape:
        return d
    diff = np.array(dshape) - np.array(d.shape)
    slices = tuple((slice(-x // 2, x // 2) if x < 0 else slice(None, None) for x in diff))
    res = d[slices]
    return np.pad(res, [(int(np.ceil(d / 2.0)), d - int(np.ceil(d / 2.0))) if d > 0 else (0, 0) for d in diff], mode=mode)

def pad_to_power2(data, axis=None, mode='constant'):
    """pad data to a shape of power 2
    if axis == None all axis are padded"""
    if axis is None:
        axis = list(range(data.ndim))
    if np.all([_is_power2(n) for i, n in enumerate(data.shape) if i in axis]):
        return data
    else:
        return pad_to_shape(data, [_next_power_of_2(n) if i in axis else n for i, n in enumerate(data.shape)], mode)

def deconv_rl(data, h, Niter=10, mode_conv='fft', log_iter=False):
    '''richardson lucy deconvolution of data with psf h
    using spatial convolutions (h should be small then)

    mode_conv = "fft" or "spatial"'''
    if isinstance(data, np.ndarray):
        mode_data = 'np'
    elif isinstance(data, OCLArray):
        mode_data = 'gpu'
    else:
        raise TypeError('array argument (1) has bad type: %s' % type(arr_obj))
    if mode_conv == 'fft':
        res = _deconv_rl_np_fft(data, h, Niter) if mode_data == 'np' else _deconv_rl_gpu_fft(data, h, Niter)
        return res
    elif mode_conv == 'spatial':
        res = _deconv_rl_np_conv(data, h, Niter) if mode_data == 'np' else gpu_conv(data, h, Niter)
        return res
    else:
        raise KeyError("mode_conv = %s not known, either 'fft' or 'spatial'" % mode_conv)

def _separable_series2(h, N=1):
    """finds separable approximations to the 2d function 2d h

    returns res = (hx, hy)[N]
    s.t. h \x07pprox sum_i outer(res[i,0],res[i,1])"""
    if min(h.shape) < N:
        raise ValueError('smallest dimension of h is smaller than approximation order! (%s < %s)' % (min(h.shape), N))
    U, S, V = linalg.svd(h)
    hx = [-U[:, n] * np.sqrt(S[n]) for n in range(N)]
    hy = [-V[n, :] * np.sqrt(S[n]) for n in range(N)]
    return np.array(list(zip(hx, hy)))

def _separable_approx2(h, N=1):
    """returns the N first approximations to the 2d function h
    whose sum should be h"""
    return np.cumsum([np.outer(fy, fx) for fy, fx in _separable_series2(h, N)], 0)

def _separable_approx3(h, N=1):
    """returns the N first approximations to the 3d function h
    """
    return np.cumsum([np.einsum('i,j,k', fz, fy, fx) for fz, fy, fx in _separable_series3(h, N)], 0)

def separable_approx(h, N=1):
    """finds the k-th rank approximation to h, where k = 1..N

    similar to separable_series

    Parameters
    ----------
    h: ndarray
        input array (2 or 2 dimensional)
    N: int
        order of approximation

    Returns
    -------
        all N apprxoimations res[i], the i-th approximation"""
    if h.ndim == 2:
        return _separable_approx2(h, N)
    elif h.ndim == 3:
        return _separable_approx3(h, N)
    else:
        raise ValueError('unsupported array dimension: %s (only 2d or 3d) ' % h.ndim)

def offset_to_timezone(offset, now=None):
    """Convert a minutes offset (JavaScript-style) into a pytz timezone

    The ``now`` parameter is generally used for testing only"""
    now = now or datetime.now()
    user_offset = -offset
    def get_tz_offset(tz):
        try:
            return tz.utcoffset(now).total_seconds() / 60
        except (pytz.NonExistentTimeError, pytz.AmbiguousTimeError):
            return tz.localize(now, is_dst=False).utcoffset().total_seconds() / 60
    return min((pytz.timezone(tz_name) for tz_name in get_prioritized_timezones()), key=lambda tz: abs(get_tz_offset(tz) - user_offset))

def pulse_train(time, start, duration, repeat_time, end):
    """Implements vensim's PULSE TRAIN function

    In range [-inf, start) returns 0
    In range [start + n * repeat_time, start + n * repeat_time + duration) return 1
    In range [start + n * repeat_time + duration, start + (n+1) * repeat_time) return 0"""
    t = time()
    if start <= t < end:
        return 1 if (t - start) % repeat_time < duration else 0
    else:
        return 0

def pulse_magnitude(time, magnitude, start, repeat_time=0):
    """Implements xmile's PULSE function

    PULSE:             Generate a one-DT wide pulse at the given time
       Parameters:     2 or 3:  (magnitude, first time[, interval])
                       Without interval or when interval = 0, the PULSE is generated only once
       Example:        PULSE(20, 12, 5) generates a pulse value of 20/DT at time 12, 17, 22, etc.

    In rage [-inf, start) returns 0
    In range [start + n * repeat_time, start + n * repeat_time + dt) return magnitude/dt
    In rage [start + n * repeat_time + dt, start + (n + 1) * repeat_time) return 0"""
    t = time()
    small = 1e-06
    if repeat_time <= small:
        if abs(t - start) < time.step():
            return magnitude * time.step()
        else:
            return 0
    elif abs((t - start) % repeat_time) < time.step():
        return magnitude * time.step()
    else:
        return 0

def lookup_discrete(x, xs, ys):
    """Intermediate values take on the value associated with the next lower x-coordinate (also called a step-wise function). The last two points of a discrete graphical function must have the same y value.
    Out-of-range values are the same as the closest endpoint (i.e, no extrapolation is performed)."""
    for index in range(0, len(xs)):
        if x < xs[index]:
            return ys[index - 1] if index > 0 else ys[index]
    return ys[len(ys) - 1]

def parse_lookup_expression(element):
    """This syntax parses lookups that are defined with their own element"""
    lookup_grammar = '\n    lookup = _ "(" range? _ ( "(" _ number _ "," _ number _ ")" _ ","? _ )+ ")"\n    number = ("+"/"-")? ~r"\\d+\\.?\\d*(e[+-]\\d+)?"\n    _ = ~r"[\\s\\\\]*"  # whitespace character\n\trange = _ "[" ~r"[^\\]]*" "]" _ ","\n    '
    parser = parsimonious.Grammar(lookup_grammar)
    tree = parser.parse(element['expr'])
    class LookupParser(parsimonious.NodeVisitor):
        def __init__(self, ast):
            self.translation = ''
            self.new_structure = []
            self.visit(ast)
        def visit__(self, n, vc):
            return ''
        def visit_lookup(self, n, vc):
            pairs = max(vc, key=len)
            mixed_list = pairs.replace('(', '').replace(')', '').split(',')
            xs = mixed_list[::2]
            ys = mixed_list[1::2]
            string = 'functions.lookup(x, [%(xs)s], [%(ys)s])' % {'xs': ','.join(xs), 'ys': ','.join(ys)}
            self.translation = string
        def generic_visit(self, n, vc):
            return ''.join(filter(None, vc)) or n.text
    parse_object = LookupParser(tree)
    return {'py_expr': parse_object.translation, 'arguments': 'x'}

def _find_address_range(addresses):
    """Find a sequence of addresses.

    Args:
        addresses: a list of IPv4 or IPv6 addresses.

    Returns:
        A tuple containing the first and last IP addresses in the sequence,
        and the index of the last IP address in the sequence."""
    first = last = addresses[0]
    last_index = 0
    for ip in addresses[1:]:
        if ip._ip == last._ip + 1:
            last = ip
            last_index += 1
        else:
            break
    return (first, last, last_index)

def output_colored(code, text, is_bold=False):
    """Create function to output with color sequence"""
    if is_bold:
        code = '1;%s' % code
    return '\x1b[%sm%s\x1b[0m' % (code, text)

def view_as_consumer(wrapped_view: typing.Callable[[HttpRequest], HttpResponse], mapped_actions: typing.Optional[typing.Dict[str, str]]=None) -> Type[AsyncConsumer]:
    """Wrap a django View so that it will be triggered by actions over this json
     websocket consumer."""
    if mapped_actions is None:
        mapped_actions = {'create': 'PUT', 'update': 'PATCH', 'list': 'GET', 'retrieve': 'GET'}
    class DjangoViewWrapper(DjangoViewAsConsumer):
        view = wrapped_view
        actions = mapped_actions
    return DjangoViewWrapper

def action(atomic=None, **kwargs):
    """Mark a method as an action."""
    def decorator(func):
        if atomic is None:
            _atomic = getattr(settings, 'ATOMIC_REQUESTS', False)
        else:
            _atomic = atomic
        func.action = True
        func.kwargs = kwargs
        if asyncio.iscoroutinefunction(func):
            if _atomic:
                raise ValueError('Only synchronous actions can be atomic')
            return func
        if _atomic:
            func = transaction.atomic(func)
        @wraps(func)
        async def async_f(self: AsyncAPIConsumer, *args, **_kwargs):
            result, status = await database_sync_to_async(func)(self, *args, **_kwargs)
            return (result, status)
        async_f.action = True
        async_f.kwargs = kwargs
        async_f.__name__ = func.__name__
        return async_f
    return decorator

def slack_user(request, api_data):
    """Pipeline for backward compatibility prior to 1.0.0 version.
    In case if you're willing maintain `slack_user` table."""
    if request.user.is_anonymous:
        return (request, api_data)
    data = deepcopy(api_data)
    slacker, _ = SlackUser.objects.get_or_create(slacker=request.user)
    slacker.access_token = data.pop('access_token')
    slacker.extras = data
    slacker.save()
    messages.add_message(request, messages.SUCCESS, 'Your account has been successfully updated with Slack. You can share your messages within your slack domain.')
    return (request, api_data)

def read(varin, fname='MS2_L10.mat.txt'):
    """Read in dataset for variable var

    :param varin: Variable for which to read in data."""
    d = np.loadtxt(fname, comments='*')
