def get_utc_date(entry):
    """Return datestamp converted to UTC"""
    if entry['numeric_date_stamp'] == '0':
        entry['numeric_date_stamp_utc'] = '0'
        return entry
    else:
        if '.' in entry['numeric_date_stamp']:
            t = datetime.strptime(entry['numeric_date_stamp'], '%Y%m%d%H%M%S.%f')
        else:
            t = datetime.strptime(entry['numeric_date_stamp'], '%Y%m%d%H%M%S')
        tdelta = timedelta(hours=int(entry['tzone'][1:3]), minutes=int(entry['tzone'][3:5]))
        if entry['tzone'][0] == '-':
            ut = t + tdelta
        else:
            ut = t - tdelta
        entry['numeric_date_stamp_utc'] = ut.strftime('%Y%m%d%H%M%S.%f')
        return entry

def get_local_tzone():
    """Get the current time zone on the local host"""
    if localtime().tm_isdst:
        if altzone < 0:
            tzone = '+' + str(int(float(altzone) / 60 // 60)).rjust(2, '0') + str(int(float(altzone) / 60 % 60)).ljust(2, '0')
        else:
            tzone = '-' + str(int(float(altzone) / 60 // 60)).rjust(2, '0') + str(int(float(altzone) / 60 % 60)).ljust(2, '0')
    elif altzone < 0:
        tzone = '+' + str(int(float(timezone) / 60 // 60)).rjust(2, '0') + str(int(float(timezone) / 60 % 60)).ljust(2, '0')
    else:
        tzone = '-' + str(int(float(timezone) / 60 // 60)).rjust(2, '0') + str(int(float(timezone) / 60 % 60)).ljust(2, '0')
    return tzone

