def pprint(data, tag_lookup, indent=0):
    """Return a pretty formatted string of parsed DMAP data."""
    output = ''
    if isinstance(data, dict):
        for key, value in data.items():
            tag = tag_lookup(key)
            if isinstance(value, (dict, list)) and tag.type is not read_bplist:
                output += '{0}{1}: {2}\n'.format(indent * ' ', key, tag)
                output += pprint(value, tag_lookup, indent + 2)
            else:
                output += '{0}{1}: {2} {3}\n'.format(indent * ' ', key, str(value), tag)
    elif isinstance(data, list):
        for elem in data:
            output += pprint(elem, tag_lookup, indent)
    else:
        raise exceptions.InvalidDmapDataError('invalid dmap data: ' + str(data))
    return output

def retrieve_commands(obj):
    """Retrieve all commands and help texts from an API object."""
    commands = {}
    for func in obj.__dict__:
        if not inspect.isfunction(obj.__dict__[func]) and (not isinstance(obj.__dict__[func], property)):
            continue
        if func.startswith('_'):
            continue
        commands[func] = _get_first_sentence_in_pydoc(obj.__dict__[func])
    return commands

def hash_sha512(*indata):
    """Create SHA512 hash for input arguments."""
    hasher = hashlib.sha512()
    for data in indata:
        if isinstance(data, str):
            hasher.update(data.encode('utf-8'))
        elif isinstance(data, bytes):
            hasher.update(data)
        else:
            raise Exception('invalid input data: ' + str(data))
    return hasher.digest()

def read_uint(data, start, length):
    """Extract a uint from a position in a sequence."""
    return int.from_bytes(data[start:start + length], byteorder='big')

def read_bplist(data, start, length):
    """Extract a binary plist from a position in a sequence."""
    return plistlib.loads(data[start:start + length], fmt=plistlib.FMT_BINARY)

def raw_tag(name, value):
    """Create a DMAP tag with raw data."""
    return name.encode('utf-8') + len(value).to_bytes(4, byteorder='big') + value

def string_tag(name, value):
    """Create a DMAP tag with string data."""
    return name.encode('utf-8') + len(value).to_bytes(4, byteorder='big') + value.encode('utf-8')

def read_variant(variant):
    """Read and parse a binary protobuf variant value."""
    result = 0
    cnt = 0
    for data in variant:
        result |= (data & 127) << 7 * cnt
        cnt += 1
        if not data & 128:
            return (result, variant[cnt:])
    raise Exception('invalid variant')

def read_tlv(data):
    """Parse TLV8 bytes into a dict.

    If value is larger than 255 bytes, it is split up in multiple chunks. So
    the same tag might occurr several times."""
    def _parse(data, pos, size, result=None):
        if result is None:
            result = {}
        if pos >= size:
            return result
        tag = str(data[pos])
        length = data[pos + 1]
        value = data[pos + 2:pos + 2 + length]
        if tag in result:
            result[tag] += value
        else:
            result[tag] = value
        return _parse(data, pos + 2 + length, size, result)
    return _parse(data, 0, len(data))

def comment(value, comment_text):
    """Annotates a value or a Doc with a comment.

    When printed by prettyprinter, the comment will be
    rendered next to the value or Doc."""
    if isinstance(value, Doc):
        return comment_doc(value, comment_text)
    return comment_value(value, comment_text)

def commentdoc(text):
    """Returns a Doc representing a comment `text`. `text` is
    treated as words, and any whitespace may be used to break
    the comment to multiple lines."""
    if not text:
        raise ValueError('Expected non-empty comment str, got {}'.format(repr(text)))
    commentlines = []
    for line in text.splitlines():
        alternating_words_ws = list(filter(None, WHITESPACE_PATTERN_TEXT.split(line)))
        starts_with_whitespace = bool(WHITESPACE_PATTERN_TEXT.match(alternating_words_ws[0]))
        if starts_with_whitespace:
            prefix = alternating_words_ws[0]
            alternating_words_ws = alternating_words_ws[1:]
        else:
            prefix = NIL
        if len(alternating_words_ws) % 2 == 0:
            alternating_words_ws = alternating_words_ws[:-1]
        for idx, tup in enumerate(zip(alternating_words_ws, cycle([False, True]))):
            part, is_ws = tup
            if is_ws:
                alternating_words_ws[idx] = flat_choice(when_flat=part, when_broken=always_break(concat([HARDLINE, '# '])))
        commentlines.append(concat(['# ', prefix, fill(alternating_words_ws)]))
    outer = identity
    if len(commentlines) > 1:
        outer = always_break
    return annotate(Token.COMMENT_SINGLE, outer(concat(intersperse(HARDLINE, commentlines))))

def align(doc):
    """Aligns each new line in ``doc`` with the first new line.
    """
    validate_doc(doc)
    def evaluator(indent, column, page_width, ribbon_width):
        return Nest(column - indent, doc)
    return contextual(evaluator)

def set_default_style(style):
    """Sets default global style to be used by ``prettyprinter.cpprint``.

    :param style: the style to set, either subclass of
                  ``pygments.styles.Style`` or one of ``'dark'``, ``'light'``"""
    global default_style
    if style == 'dark':
        style = default_dark_style
    elif style == 'light':
        style = default_light_style
    if not issubclass(style, Style):
        raise TypeError("style must be a subclass of pygments.styles.Style or one of 'dark', 'light'. Got {}".format(repr(style)))
    default_style = style

def set_default_config(*, style=_UNSET_SENTINEL, max_seq_len=_UNSET_SENTINEL, width=_UNSET_SENTINEL, ribbon_width=_UNSET_SENTINEL, depth=_UNSET_SENTINEL, sort_dict_keys=_UNSET_SENTINEL):
    """Sets the default configuration values used when calling
    `pprint`, `cpprint`, or `pformat`, if those values weren't
    explicitly provided. Only overrides the values provided in
    the keyword arguments."""
    global _default_config
    if style is not _UNSET_SENTINEL:
        set_default_style(style)
    new_defaults = {**_default_config}
    if max_seq_len is not _UNSET_SENTINEL:
        new_defaults['max_seq_len'] = max_seq_len
    if width is not _UNSET_SENTINEL:
        new_defaults['width'] = width
    if ribbon_width is not _UNSET_SENTINEL:
        new_defaults['ribbon_width'] = ribbon_width
    if depth is not _UNSET_SENTINEL:
        new_defaults['depth'] = depth
    if sort_dict_keys is not _UNSET_SENTINEL:
        new_defaults['sort_dict_keys'] = sort_dict_keys
    _default_config = new_defaults
    return new_defaults

def pretty_repr(instance):
    """A function assignable to the ``__repr__`` dunder method, so that
    the ``prettyprinter`` definition for the type is used to provide
    repr output. Usage:

    .. code:: python

        from prettyprinter import pretty_repr

        class MyClass:
            __repr__ = pretty_repr"""
    instance_type = type(instance)
    if not is_registered(instance_type, check_superclasses=True, check_deferred=True, register_deferred=True):
        warnings.warn("pretty_repr is assigned as the __repr__ method of '{}'. However, no pretty printer is registered for that type, its superclasses or its subclasses. Falling back to the default repr implementation. To fix this warning, register a pretty printer using prettyprinter.register_pretty.".format(instance_type.__qualname__), UserWarning)
        return object.__repr__(instance)
    return pformat(instance)

def _write_jpy_config(target_dir=None, install_dir=None):
    """Write out a well-formed jpyconfig.properties file for easier Java
    integration in a given location."""
    if not target_dir:
        target_dir = _build_dir()
    args = [sys.executable, os.path.join(target_dir, 'jpyutil.py'), '--jvm_dll', jvm_dll_file, '--java_home', jdk_home_dir, '--log_level', 'DEBUG', '--req_java', '--req_py']
    if install_dir:
        args.append('--install_dir')
        args.append(install_dir)
    log.info('Writing jpy configuration to %s using install_dir %s' % (target_dir, install_dir))
    return subprocess.call(args)

def _get_module_path(name, fail=False, install_path=None):
    """Find the path to the jpy jni modules."""
    import imp
    module = imp.find_module(name)
    if not module and fail:
        raise RuntimeError("can't find module '" + name + "'")
    path = module[1]
    if not path and fail:
        raise RuntimeError("module '" + name + "' is missing a file path")
    if install_path:
        return os.path.join(install_path, os.path.split(path)[1])
    return path

def find_jdk_home_dir():
    """Try to detect the JDK home directory from Maven, if available, or use
    dedicated environment variables.
    :return: pathname if found, else None"""
    for name in JDK_HOME_VARS:
        jdk_home_dir = os.environ.get(name, None)
        if jdk_home_dir and os.path.exists(os.path.join(jdk_home_dir, 'include')) and os.path.exists(os.path.join(jdk_home_dir, 'lib')):
            return jdk_home_dir
    logger.debug('Checking Maven for JAVA_HOME...')
    try:
        output = subprocess.check_output(['mvn', '-v'])
        if isinstance(output, bytes) and (not isinstance(output, str)):
            output = output.decode('utf-8')
        for part in output.split('\n'):
            if part.startswith('Java home:'):
                path = part.split(':')[1].strip()
                if path.endswith('jre'):
                    return path[0:-3]
    except Exception:
        logger.debug('Maven not found on PATH. No JAVA_HOME found.')
    return None

def find_jvm_dll_file(java_home_dir=None, fail=False):
    """Try to detect the JVM's shared library file.
    :param java_home_dir: The Java JRE or JDK installation directory to be used for searching.
    :return: pathname if found, else None"""
    logger.debug('Searching for JVM shared library file')
    if java_home_dir:
        jvm_dll_path = _find_jvm_dll_file(java_home_dir)
        if jvm_dll_path:
            return jvm_dll_path
    jvm_dll_path = os.environ.get('JPY_JVM_DLL', None)
    if jvm_dll_path:
        return jvm_dll_path
    for name in JRE_HOME_VARS:
        java_home_dir = os.environ.get(name, None)
        if java_home_dir:
            jvm_dll_path = _find_jvm_dll_file(java_home_dir)
            if jvm_dll_path:
                return jvm_dll_path
    jvm_dll_path = ctypes.util.find_library(JVM_LIB_NAME)
    if jvm_dll_path:
        logger.debug('No JVM shared library file found in all search paths. Using fallback %s' % repr(jvm_dll_path))
    elif fail:
        raise RuntimeError("can't find any JVM shared library")
    return jvm_dll_path

def run_lint_command():
    """Run lint command in the shell and save results to lint-result.xml"""
    lint, app_dir, lint_result, ignore_layouts = parse_args()
    if not lint_result:
        if not distutils.spawn.find_executable(lint):
            raise Exception('`%s` executable could not be found and path to lint result not specified. See --help' % lint)
        lint_result = os.path.join(app_dir, 'lint-result.xml')
        call_result = subprocess.call([lint, app_dir, '--xml', lint_result])
        if call_result > 0:
            print('Running the command failed with result %s. Try running it from the console. Arguments for subprocess.call: %s' % (call_result, [lint, app_dir, '--xml', lint_result]))
    elif not os.path.isabs(lint_result):
        lint_result = os.path.join(app_dir, lint_result)
    lint_result = os.path.abspath(lint_result)
    return (lint_result, app_dir, ignore_layouts)

def remove_resource_file(issue, filepath, ignore_layouts):
    """Delete a file from the filesystem"""
    if os.path.exists(filepath) and (ignore_layouts is False or issue.elements[0][0] != 'layout'):
        print('removing resource: {0}'.format(filepath))
        os.remove(os.path.abspath(filepath))

def remove_resource_value(issue, filepath):
    """Read an xml file and remove an element which is unused, then save the file back to the filesystem"""
    if os.path.exists(filepath):
        for element in issue.elements:
            print('removing {0} from resource {1}'.format(element, filepath))
            parser = etree.XMLParser(remove_blank_text=False, remove_comments=False, remove_pis=False, strip_cdata=False, resolve_entities=False)
            tree = etree.parse(filepath, parser)
            root = tree.getroot()
            for unused_value in root.findall('.//{0}[@name="{1}"]'.format(element[0], element[1])):
                root.remove(unused_value)
            with open(filepath, 'wb') as resource:
                tree.write(resource, encoding='utf-8', xml_declaration=True)

def remove_unused_resources(issues, app_dir, ignore_layouts):
    """Remove the file or the value inside the file depending if the whole file is unused or not."""
    for issue in issues:
        filepath = os.path.join(app_dir, issue.filepath)
        if issue.remove_file:
            remove_resource_file(issue, filepath, ignore_layouts)
        else:
            remove_resource_value(issue, filepath)

def serialize_raw_master_key_prefix(raw_master_key):
    """Produces the prefix that a RawMasterKey will always use for the
    key_info value of keys which require additional information.

    :param raw_master_key: RawMasterKey for which to produce a prefix
    :type raw_master_key: aws_encryption_sdk.key_providers.raw.RawMasterKey
    :returns: Serialized key_info prefix
    :rtype: bytes"""
    if raw_master_key.config.wrapping_key.wrapping_algorithm.encryption_type is EncryptionType.ASYMMETRIC:
        return to_bytes(raw_master_key.key_id)
    return struct.pack('>{}sII'.format(len(raw_master_key.key_id)), to_bytes(raw_master_key.key_id), raw_master_key.config.wrapping_key.wrapping_algorithm.algorithm.tag_len * 8, raw_master_key.config.wrapping_key.wrapping_algorithm.algorithm.iv_len)

def read_short(source, offset):
    """Reads a number from a byte array.

    :param bytes source: Source byte string
    :param int offset: Point in byte string to start reading
    :returns: Read number and offset at point after read data
    :rtype: tuple of ints
    :raises: SerializationError if unable to unpack"""
    try:
        short, = struct.unpack_from('>H', source, offset)
        return (short, offset + struct.calcsize('>H'))
    except struct.error:
        raise SerializationError('Bad format of serialized context.')

def read_string(source, offset, length):
    """Reads a string from a byte string.

    :param bytes source: Source byte string
    :param int offset: Point in byte string to start reading
    :param int length: Length of string to read
    :returns: Read string and offset at point after read data
    :rtype: tuple of str and int
    :raises SerializationError: if unable to unpack"""
    end = offset + length
    try:
        return (codecs.decode(source[offset:end], aws_encryption_sdk.internal.defaults.ENCODING), end)
    except Exception:
        raise SerializationError('Bad format of serialized context.')

def get_version():
    """Reads the version (MAJOR.MINOR) from this module."""
    release = get_release()
    split_version = release.split('.')
    if len(split_version) == 3:
        return '.'.join(split_version[:2])
    return release

def _verified_version_from_id(version_id):
    """Load a message :class:`SerializationVersion` for the specified version ID.

    :param int version_id: Message format version ID
    :return: Message format version
    :rtype: SerializationVersion
    :raises NotSupportedError: if unsupported version ID is received"""
    try:
        return SerializationVersion(version_id)
    except ValueError as error:
        raise NotSupportedError('Unsupported version {}'.format(version_id), error)

def _verified_message_type_from_id(message_type_id):
    """Load a message :class:`ObjectType` for the specified message type ID.

    :param int message_type_id: Message type ID
    :return: Message type
    :rtype: ObjectType
    :raises NotSupportedError: if unsupported message type ID is received"""
    try:
        return ObjectType(message_type_id)
    except ValueError as error:
        raise NotSupportedError('Unsupported type {} discovered in data stream'.format(message_type_id), error)

def _verified_content_type_from_id(content_type_id):
    """Load a message :class:`ContentType` for the specified content type ID.

    :param int content_type_id: Content type ID
    :return: Message content type
    :rtype: ContentType
    :raises UnknownIdentityError: if unknown content type ID is received"""
    try:
        return ContentType(content_type_id)
    except ValueError as error:
        raise UnknownIdentityError('Unknown content type {}'.format(content_type_id), error)

def deserialize_footer(stream, verifier=None):
    """Deserializes a footer.

    :param stream: Source data stream
    :type stream: io.BytesIO
    :param verifier: Signature verifier object (optional)
    :type verifier: aws_encryption_sdk.internal.crypto.Verifier
    :returns: Deserialized footer
    :rtype: aws_encryption_sdk.internal.structures.MessageFooter
    :raises SerializationError: if verifier supplied and no footer found"""
    _LOGGER.debug('Starting footer deserialization')
    signature = b''
    if verifier is None:
        return MessageFooter(signature=signature)
    try:
        sig_len, = unpack_values('>H', stream)
        signature, = unpack_values('>{sig_len}s'.format(sig_len=sig_len), stream)
    except SerializationError:
        raise SerializationError('No signature found in message')
    if verifier:
        verifier.verify(signature)
    return MessageFooter(signature=signature)

def get_aad_content_string(content_type, is_final_frame):
    """Prepares the appropriate Body AAD Value for a message body.

    :param content_type: Defines the type of content for which to prepare AAD String
    :type content_type: aws_encryption_sdk.identifiers.ContentType
    :param bool is_final_frame: Boolean stating whether this is the final frame in a body
    :returns: Appropriate AAD Content String
    :rtype: bytes
    :raises UnknownIdentityError: if unknown content type"""
    if content_type == ContentType.NO_FRAMING:
        aad_content_string = ContentAADString.NON_FRAMED_STRING_ID
    elif content_type == ContentType.FRAMED_DATA:
        if is_final_frame:
            aad_content_string = ContentAADString.FINAL_FRAME_STRING_ID
        else:
            aad_content_string = ContentAADString.FRAME_STRING_ID
    else:
        raise UnknownIdentityError('Unhandled content type')
    return aad_content_string

def prep_stream_data(data):
    """Take an input and prepare it for use as a stream.

    :param data: Input data
    :returns: Prepared stream
    :rtype: InsistentReaderBytesIO"""
    if isinstance(data, (six.string_types, six.binary_type)):
        stream = io.BytesIO(to_bytes(data))
    else:
        stream = data
    return InsistentReaderBytesIO(stream)

def to_str(data):
    """Takes an input str or bytes object and returns an equivalent str object.

    :param data: Input data
    :type data: str or bytes
    :returns: Data normalized to str
    :rtype: str"""
    if isinstance(data, bytes):
        return codecs.decode(data, aws_encryption_sdk.internal.defaults.ENCODING)
    return data

def to_bytes(data):
    """Takes an input str or bytes object and returns an equivalent bytes object.

    :param data: Input data
    :type data: str or bytes
    :returns: Data normalized to bytes
    :rtype: bytes"""
    if isinstance(data, six.string_types) and (not isinstance(data, bytes)):
        return codecs.encode(data, aws_encryption_sdk.internal.defaults.ENCODING)
    return data

def css_class_cycler():
    """Return a dictionary keyed by ``EventType`` abbreviations, whose values are an
    iterable or cycle of CSS class names."""
    FMT = 'evt-{0}-{1}'.format
    return defaultdict(default_css_class_cycler, ((e.abbr, itertools.cycle((FMT(e.abbr, 'even'), FMT(e.abbr, 'odd')))) for e in EventType.objects.all()))

def event_view(request, pk, template='swingtime/event_detail.html', event_form_class=forms.EventForm, recurrence_form_class=forms.MultipleOccurrenceForm):
    """View an ``Event`` instance and optionally update either the event or its
    occurrences.

    Context parameters:

    ``event``
        the event keyed by ``pk``

    ``event_form``
        a form object for updating the event

    ``recurrence_form``
        a form object for adding occurrences"""
    event = get_object_or_404(Event, pk=pk)
    event_form = recurrence_form = None
    if request.method == 'POST':
        if '_update' in request.POST:
            event_form = event_form_class(request.POST, instance=event)
            if event_form.is_valid():
                event_form.save(event)
                return http.HttpResponseRedirect(request.path)
        elif '_add' in request.POST:
            recurrence_form = recurrence_form_class(request.POST)
            if recurrence_form.is_valid():
                recurrence_form.save(event)
                return http.HttpResponseRedirect(request.path)
        else:
            return http.HttpResponseBadRequest('Bad Request')
    data = {'event': event, 'event_form': event_form or event_form_class(instance=event), 'recurrence_form': recurrence_form or recurrence_form_class(initial={'dtstart': datetime.now()})}
    return render(request, template, data)

def occurrence_view(request, event_pk, pk, template='swingtime/occurrence_detail.html', form_class=forms.SingleOccurrenceForm):
    """View a specific occurrence and optionally handle any updates.

    Context parameters:

    ``occurrence``
        the occurrence object keyed by ``pk``

    ``form``
        a form object for updating the occurrence"""
    occurrence = get_object_or_404(Occurrence, pk=pk, event__pk=event_pk)
    if request.method == 'POST':
        form = form_class(request.POST, instance=occurrence)
        if form.is_valid():
            form.save()
            return http.HttpResponseRedirect(request.path)
    else:
        form = form_class(instance=occurrence)
    return render(request, template, {'occurrence': occurrence, 'form': form})

def add_event(request, template='swingtime/add_event.html', event_form_class=forms.EventForm, recurrence_form_class=forms.MultipleOccurrenceForm):
    """Add a new ``Event`` instance and 1 or more associated ``Occurrence``s.

    Context parameters:

    ``dtstart``
        a datetime.datetime object representing the GET request value if present,
        otherwise None

    ``event_form``
        a form object for updating the event

    ``recurrence_form``
        a form object for adding occurrences"""
    dtstart = None
    if request.method == 'POST':
        event_form = event_form_class(request.POST)
        recurrence_form = recurrence_form_class(request.POST)
        if event_form.is_valid() and recurrence_form.is_valid():
            event = event_form.save()
            recurrence_form.save(event)
            return http.HttpResponseRedirect(event.get_absolute_url())
    else:
        if 'dtstart' in request.GET:
            try:
                dtstart = parser.parse(request.GET['dtstart'])
            except (TypeError, ValueError) as exc:
                logging.warning(exc)
        dtstart = dtstart or datetime.now()
        event_form = event_form_class()
        recurrence_form = recurrence_form_class(initial={'dtstart': dtstart})
    return render(request, template, {'dtstart': dtstart, 'event_form': event_form, 'recurrence_form': recurrence_form})

