def get_operation_pattern(server_url, request_url_pattern):
    """Return an updated request URL pattern with the server URL removed."""
    if server_url[-1] == '/':
        server_url = server_url[:-1]
    if is_absolute(server_url):
        return request_url_pattern.replace(server_url, '', 1)
    return path_qs(request_url_pattern).replace(server_url, '', 1)

def url_for(context, __route_name, **parts):
    """Filter for generating urls.

    Usage: {{ url('the-view-name') }} might become "/path/to/view" or
    {{ url('item-details', id=123, query={'active': 'true'}) }}
    might become "/items/1?active=true"."""
    app = context['app']
    query = None
    if 'query_' in parts:
        query = parts.pop('query_')
    for key in parts:
        val = parts[key]
        if isinstance(val, str):
            val = str(val)
        elif type(val) is int:
            val = str(val)
        else:
            raise TypeError('argument value should be str or int, got {} -> [{}] {!r}'.format(key, type(val), val))
        parts[key] = val
    url = app.router[__route_name].url_for(**parts)
    if query:
        url = url.with_query(query)
    return url

def static_url(context, static_file_path):
    '''Filter for generating urls for static files.

    NOTE: you'll need
    to set app['static_root_url'] to be used as the root for the urls returned.

    Usage: {{ static('styles.css') }} might become
    "/static/styles.css" or "http://mycdn.example.com/styles.css"'''
    app = context['app']
    try:
        static_url = app['static_root_url']
    except KeyError:
        raise RuntimeError("app does not define a static root url 'static_root_url', you need to set the url root with app['static_root_url'] = '<static root>'.") from None
    return '{}/{}'.format(static_url.rstrip('/'), static_file_path.lstrip('/'))

def get_extended_access_token(access_token, application_id, application_secret_key, api_version=None):
    """Get an extended OAuth access token.

    :param access_token: A string describing an OAuth access token.
    :param application_id: An integer describing the Facebook application's ID.
    :param application_secret_key: A string describing the Facebook application's secret key.

    Returns a tuple with a string describing the extended access token and a datetime instance
    describing when it expires."""
    graph = GraphAPI(version=api_version)
    response = graph.get(path='oauth/access_token', client_id=application_id, client_secret=application_secret_key, grant_type='fb_exchange_token', fb_exchange_token=access_token)
    try:
        components = parse_qs(response)
    except AttributeError:
        return (response['access_token'], None)
    token = components['access_token'][0]
    try:
        expires_at = datetime.now() + timedelta(seconds=int(components['expires'][0]))
    except KeyError:
        expires_at = None
    return (token, expires_at)

def get_application_access_token(application_id, application_secret_key, api_version=None):
    """Get an OAuth access token for the given application.

    :param application_id: An integer describing a Facebook application's ID.
    :param application_secret_key: A string describing a Facebook application's secret key."""
    graph = GraphAPI(version=api_version)
    response = graph.get(path='oauth/access_token', client_id=application_id, client_secret=application_secret_key, grant_type='client_credentials')
    try:
        data = parse_qs(response)
        try:
            return data['access_token'][0]
        except KeyError:
            raise GraphAPI.FacebookError('No access token given')
    except AttributeError:
        return (response['access_token'], None)

def _eval_script(redis, script_id, *keys, **kwargs):
    """Tries to call ``EVALSHA`` with the `hash` and then, if it fails, calls
    regular ``EVAL`` with the `script`."""
    args = kwargs.pop('args', ())
    if kwargs:
        raise TypeError('Unexpected keyword arguments %s' % kwargs.keys())
    try:
        return redis.evalsha(SCRIPTS[script_id], len(keys), *keys + args)
    except NoScriptError:
        logger.info('%s not cached.', SCRIPTS[script_id + 2])
        return redis.eval(SCRIPTS[script_id + 1], len(keys), *keys + args)

def bunchify(x):
    """Recursively transforms a dictionary into a Bunch via copy.

    >>> b = bunchify({'urmom': {'sez': {'what': 'what'}}})
    >>> b.urmom.sez.what
    'what'

    bunchify can handle intermediary dicts, lists and tuples (as well as
    their subclasses), but ymmv on custom datatypes.

    >>> b = bunchify({ 'lol': ('cats', {'hah':'i win again'}),
    ...         'hello': [{'french':'salut', 'german':'hallo'}] })
    >>> b.hello[0].french
    'salut'
    >>> b.lol[1].hah
    'i win again'

    nb. As dicts are not hashable, they cannot be nested in sets/frozensets."""
    if isinstance(x, dict):
        return Bunch(((k, bunchify(v)) for k, v in iteritems(x)))
    elif isinstance(x, (list, tuple)):
        return type(x)((bunchify(v) for v in x))
    else:
        return x

def unbunchify(x):
    """Recursively converts a Bunch into a dictionary.

    >>> b = Bunch(foo=Bunch(lol=True), hello=42, ponies='are pretty!')
    >>> unbunchify(b)
    {'ponies': 'are pretty!', 'foo': {'lol': True}, 'hello': 42}

    unbunchify will handle intermediary dicts, lists and tuples (as well as
    their subclasses), but ymmv on custom datatypes.

    >>> b = Bunch(foo=['bar', Bunch(lol=True)], hello=42,
    ...         ponies=('are pretty!', Bunch(lies='are trouble!')))
    >>> unbunchify(b) #doctest: +NORMALIZE_WHITESPACE
    {'ponies': ('are pretty!', {'lies': 'are trouble!'}),
     'foo': ['bar', {'lol': True}], 'hello': 42}

    nb. As dicts are not hashable, they cannot be nested in sets/frozensets."""
    if isinstance(x, dict):
        return dict(((k, unbunchify(v)) for k, v in iteritems(x)))
    elif isinstance(x, (list, tuple)):
        return type(x)((unbunchify(v) for v in x))
    else:
        return x

def clamp(color, min_v, max_v):
    """Clamps a color such that the value is between min_v and max_v."""
    h, s, v = rgb_to_hsv(*map(down_scale, color))
    min_v, max_v = map(down_scale, (min_v, max_v))
    v = min(max(min_v, v), max_v)
    return tuple(map(up_scale, hsv_to_rgb(h, s, v)))

def brighten(color, brightness):
    """Adds or subtracts value to a color."""
    h, s, v = rgb_to_hsv(*map(down_scale, color))
    return tuple(map(up_scale, hsv_to_rgb(h, s, v + down_scale(brightness))))

def long_description(*paths):
    """Returns a RST formated string.
    """
    result = ''
    try:
        import pypandoc
    except (ImportError, OSError) as e:
        print('Unable to import pypandoc - %s' % e)
        return result
    try:
        for path in paths:
            result += '\n' + pypandoc.convert(path, 'rst', format='markdown')
    except (OSError, IOError) as e:
        print('Failed to convert with pypandoc - %s' % e)
        return result
    return result

def decode_wireformat_uuid(rawguid):
    """Decode a wire format UUID

    It handles the rather particular scheme where half is little endian
    and half is big endian.  It returns a string like dmidecode would output."""
    if isinstance(rawguid, list):
        rawguid = bytearray(rawguid)
    lebytes = struct.unpack_from('<IHH', buffer(rawguid[:8]))
    bebytes = struct.unpack_from('>HHI', buffer(rawguid[8:]))
    return '{0:08X}-{1:04X}-{2:04X}-{3:04X}-{4:04X}{5:08X}'.format(lebytes[0], lebytes[1], lebytes[2], bebytes[0], bebytes[1], bebytes[2])

def parse_inventory_category_entry(raw, fields):
    """Parses one entry in an inventory category.

    :param raw: the raw data to the entry. May contain more than one entry,
                only one entry will be read in that case.
    :param fields: an iterable of EntryField objects to be used for parsing the
                   entry.

    :returns: dict -- a tuple with the number of bytes read and a dictionary
                      representing the entry."""
    r = raw
    obj = {}
    bytes_read = 0
    discard = False
    for field in fields:
        value = struct.unpack_from(field.fmt, r)[0]
        read = struct.calcsize(field.fmt)
        bytes_read += read
        r = r[read:]
        if field.presence and (not bool(value)):
            discard = True
        if not field.include:
            continue
        if field.fmt[-1] == 's':
            value = value.rstrip('\x00')
        if field.mapper and value in field.mapper:
            value = field.mapper[value]
        if field.valuefunc:
            value = field.valuefunc(value)
        if not field.multivaluefunc:
            obj[field.name] = value
        else:
            for key in value:
                obj[key] = value[key]
    if discard:
        obj = None
    return (bytes_read, obj)

def make_tarball(tarball_fname, directory, cwd=None):
    """create a tarball from a directory"""
    if tarball_fname.endswith('.gz'):
        opts = 'czf'
    else:
        opts = 'cf'
    args = ['/bin/tar', opts, tarball_fname, directory]
    process_command(args, cwd=cwd)

def expand_tarball(tarball_fname, cwd=None):
    """expand a tarball"""
    if tarball_fname.endswith('.gz'):
        opts = 'xzf'
    elif tarball_fname.endswith('.bz2'):
        opts = 'xjf'
    else:
        opts = 'xf'
    args = ['/bin/tar', opts, tarball_fname]
    process_command(args, cwd=cwd)

def parse_vals(cfg, section, option):
    """parse comma separated values in debian control file style from .cfg"""
    try:
        vals = cfg.get(section, option)
    except ConfigParser.NoSectionError as err:
        if section != 'DEFAULT':
            vals = cfg.get('DEFAULT', option)
        else:
            raise err
    vals = vals.split('#')[0]
    vals = vals.strip()
    vals = vals.split(',')
    vals = [v.strip() for v in vals]
    vals = [v for v in vals if len(v)]
    return vals

def parse_val(cfg, section, option):
    """extract a single value from .cfg"""
    vals = parse_vals(cfg, section, option)
    if len(vals) == 0:
        return ''
    else:
        assert len(vals) == 1, (section, option, vals, type(vals))
    return vals[0]

def encode_basestring(s):
    """Return a JSON representation of a Python string

    """
    if isinstance(s, str) and HAS_UTF8.search(s) is not None:
        s = s.decode('utf-8')
    def replace(match):
        return ESCAPE_DCT[match.group(0)]
    return u'"' + ESCAPE.sub(replace, s) + u'"'

def loads(s, **kwargs):
    """Loads JSON object."""
    try:
        return _engine[0](s)
    except _engine[2]:
        why = sys.exc_info()[1]
        raise JSONError(why)

def dumps(o, **kwargs):
    """Dumps JSON object."""
    try:
        return _engine[1](o)
    except:
        ExceptionClass, why = sys.exc_info()[:2]
        if any([issubclass(ExceptionClass, e) for e in _engine[2]]):
            raise JSONError(why)
        else:
            raise why

def from_data(data):
    """Construct a Prettytable from list of rows."""
    if len(data) == 0:
        return None
    else:
        ptable = PrettyTable()
        ptable.field_names = data[0].keys()
        for row in data:
            ptable.add_row(row)
        return ptable

def from_everything(everything, engine, limit=None):
    """Construct a Prettytable from any kinds of sqlalchemy query."""
    if isinstance(everything, Table):
        return from_table(everything, engine, limit=limit)
    if type(everything) is DeclarativeMeta:
        return from_object(everything, engine, limit=limit)
    if isinstance(everything, Query):
        return from_query(everything, engine, limit=limit)
    if isinstance(everything, Select):
        return from_sql(everything, engine, limit=limit)
    if isinstance(everything, ResultProxy):
        return from_resultproxy(everything)
    if isinstance(everything, list):
        return from_data(everything)

def update_all(engine, table, data, upsert=False):
    """Update data by its primary_key column."""
    data = ensure_list(data)
    ins = table.insert()
    upd = table.update()
    pk_cols = OrderedDict()
    for column in table._columns:
        if column.primary_key:
            pk_cols[column.name] = column
    data_to_insert = list()
    if len(pk_cols) >= 2:
        for row in data:
            result = engine.execute(upd.where(and_(*[col == row[name] for name, col in pk_cols.items()])).values(**row))
            if result.rowcount == 0:
                data_to_insert.append(row)
    elif len(pk_cols) == 1:
        for row in data:
            result = engine.execute(upd.where([col == row[name] for name, col in pk_cols.items()][0]).values(**row))
            if result.rowcount == 0:
                data_to_insert.append(row)
    else:
        data_to_insert = data
    if upsert:
        if len(data_to_insert):
            engine.execute(ins, data_to_insert)

def ensure_session(engine_or_session):
    """If it is an engine, then create a session from it. And indicate that
    this session should be closed after the job done."""
    if isinstance(engine_or_session, Engine):
        ses = sessionmaker(bind=engine_or_session)()
        auto_close = True
    elif isinstance(engine_or_session, Session):
        ses = engine_or_session
        auto_close = False
    return (ses, auto_close)

