def titleize(text):
    """Capitalizes all the words and replaces some characters in the string
    to create a nicer looking title."""
    if len(text) == 0:
        return text
    else:
        text = text.lower()
        chunks = [chunk[0].upper() + chunk[1:] for chunk in text.split(' ') if len(chunk) >= 1]
        return ' '.join(chunks)

