def _create_scales(hist: HistogramBase, vega: dict, kwargs: dict):
    """Find proper scales for axes."""
    if hist.ndim == 1:
        bins0 = hist.bins.astype(float)
    else:
        bins0 = hist.bins[0].astype(float)
    xlim = kwargs.pop('xlim', 'auto')
    ylim = kwargs.pop('ylim', 'auto')
    if xlim is 'auto':
        nice_x = True
    else:
        nice_x = False
    if ylim is 'auto':
        nice_y = True
    else:
        nice_y = False
    vega['scales'] = [{'name': 'xscale', 'type': 'linear', 'range': 'width', 'nice': nice_x, 'zero': None, 'domain': [bins0[0, 0], bins0[-1, 1]] if xlim == 'auto' else [float(xlim[0]), float(xlim[1])]}, {'name': 'yscale', 'type': 'linear', 'range': 'height', 'nice': nice_y, 'zero': True if hist.ndim == 1 else None, 'domain': {'data': 'table', 'field': 'y'} if ylim == 'auto' else [float(ylim[0]), float(ylim[1])]}]
    if hist.ndim >= 2:
        bins1 = hist.bins[1].astype(float)
        vega['scales'][1]['domain'] = [bins1[0, 0], bins1[-1, 1]]

def spherical_histogram(data=None, radial_bins='numpy', theta_bins=16, phi_bins=16, transformed=False, *args, **kwargs):
    """Facade construction function for the SphericalHistogram.

    """
    dropna = kwargs.pop('dropna', True)
    data = _prepare_data(data, transformed=transformed, klass=SphericalHistogram, dropna=dropna)
    if isinstance(theta_bins, int):
        theta_range = (0, np.pi)
        if 'theta_range' in 'kwargs':
            theta_range = kwargs['theta_range']
        elif 'range' in 'kwargs':
            theta_range = kwargs['range'][1]
        theta_range = list(theta_range) + [theta_bins + 1]
        theta_bins = np.linspace(*theta_range)
    if isinstance(phi_bins, int):
        phi_range = (0, 2 * np.pi)
        if 'phi_range' in 'kwargs':
            phi_range = kwargs['phi_range']
        elif 'range' in 'kwargs':
            phi_range = kwargs['range'][2]
        phi_range = list(phi_range) + [phi_bins + 1]
        phi_bins = np.linspace(*phi_range)
    bin_schemas = binnings.calculate_bins_nd(data, [radial_bins, theta_bins, phi_bins], *args, check_nan=not dropna, **kwargs)
    weights = kwargs.pop('weights', None)
    frequencies, errors2, missed = histogram_nd.calculate_frequencies(data, ndim=3, binnings=bin_schemas, weights=weights)
    return SphericalHistogram(binnings=bin_schemas, frequencies=frequencies, errors2=errors2, missed=missed)

def enable_collection(f):
    """Call the wrapped function with a HistogramCollection as argument."""
    @wraps(f)
    def new_f(h: AbstractHistogram1D, **kwargs):
        from physt.histogram_collection import HistogramCollection
        if isinstance(h, HistogramCollection):
            return f(h, **kwargs)
        else:
            return f(HistogramCollection(h), **kwargs)
    return new_f

def _add_ticks(xaxis: go.layout.XAxis, histogram: HistogramBase, kwargs: dict):
    """Customize ticks for an axis (1D histogram)."""
    ticks = kwargs.pop('ticks', None)
    tick_handler = kwargs.pop('tick_handler', None)
    if tick_handler:
        if ticks:
            raise ValueError('Cannot specify both tick and tick_handler')
        ticks, labels = tick_handler(histogram, histogram.min_edge, histogram.max_edge)
        xaxis.tickvals = ticks
        xaxis.ticktext = labels
    elif ticks == 'center':
        xaxis.tickvals = histogram.bin_centers
    elif ticks == 'edge':
        xaxis.tickvals = histogram.bin_left_edges
    else:
        xaxis.tickvals = ticks

def load_csv(path):
    """Loads a histogram as output from Geant4 analysis tools in CSV format.

    Parameters
    ----------
    path: str
        Path to the CSV file

    Returns
    -------
    physt.histogram1d.Histogram1D or physt.histogram_nd.Histogram2D"""
    meta = []
    data = []
    with codecs.open(path, encoding='ASCII') as in_file:
        for line in in_file:
            if line.startswith('#'):
                key, value = line[1:].strip().split(' ', 1)
                meta.append((key, value))
            else:
                try:
                    data.append([float(frag) for frag in line.split(',')])
                except:
                    pass
    data = np.asarray(data)
    ndim = int(_get(meta, 'dimension'))
    if ndim == 1:
        return _create_h1(data, meta)
    elif ndim == 2:
        return _create_h2(data, meta)

def _get(pseudodict, key, single=True):
    """Helper method for getting values from "multi-dict"s"""
    matches = [item[1] for item in pseudodict if item[0] == key]
    if single:
        return matches[0]
    else:
        return matches

def generateAcceptHeader(*elements):
    """Generate an accept header value

    [str or (str, float)] -> str"""
    parts = []
    for element in elements:
        if type(element) is str:
            qs = '1.0'
            mtype = element
        else:
            mtype, q = element
            q = float(q)
            if q > 1 or q <= 0:
                raise ValueError('Invalid preference factor: %r' % q)
            qs = '%0.1f' % (q,)
        parts.append((qs, mtype))
    parts.sort()
    chunks = []
    for q, mtype in parts:
        if q == '1.0':
            chunks.append(mtype)
        else:
            chunks.append('%s; q=%s' % (mtype, q))
    return ', '.join(chunks)

def parseAcceptHeader(value):
    """Parse an accept header, ignoring any accept-extensions

    returns a list of tuples containing main MIME type, MIME subtype,
    and quality markdown.

    str -> [(str, str, float)]"""
    chunks = [chunk.strip() for chunk in value.split(',')]
    accept = []
    for chunk in chunks:
        parts = [s.strip() for s in chunk.split(';')]
        mtype = parts.pop(0)
        if '/' not in mtype:
            continue
        main, sub = mtype.split('/', 1)
        for ext in parts:
            if '=' in ext:
                k, v = ext.split('=', 1)
                if k == 'q':
                    try:
                        q = float(v)
                        break
                    except ValueError:
                        pass
        else:
            q = 1.0
        accept.append((q, main, sub))
    accept.sort()
    accept.reverse()
    return [(main, sub, q) for q, main, sub in accept]

def matchTypes(accept_types, have_types):
    """Given the result of parsing an Accept: header, and the
    available MIME types, return the acceptable types with their
    quality markdowns.

    For example:

    >>> acceptable = parseAcceptHeader('text/html, text/plain; q=0.5')
    >>> matchTypes(acceptable, ['text/plain', 'text/html', 'image/jpeg'])
    [('text/html', 1.0), ('text/plain', 0.5)]


    Type signature: ([(str, str, float)], [str]) -> [(str, float)]"""
    if not accept_types:
        default = 1
    else:
        default = 0
    match_main = {}
    match_sub = {}
    for main, sub, q in accept_types:
        if main == '*':
            default = max(default, q)
            continue
        elif sub == '*':
            match_main[main] = max(match_main.get(main, 0), q)
        else:
            match_sub[main, sub] = max(match_sub.get((main, sub), 0), q)
    accepted_list = []
    order_maintainer = 0
    for mtype in have_types:
        main, sub = mtype.split('/')
        if (main, sub) in match_sub:
            q = match_sub[main, sub]
        else:
            q = match_main.get(main, default)
        if q:
            accepted_list.append((1 - q, order_maintainer, q, mtype))
            order_maintainer += 1
    accepted_list.sort()
    return [(mtype, q) for _, _, q, mtype in accepted_list]

def toTypeURIs(namespace_map, alias_list_s):
    """Given a namespace mapping and a string containing a
    comma-separated list of namespace aliases, return a list of type
    URIs that correspond to those aliases.

    @param namespace_map: The mapping from namespace URI to alias
    @type namespace_map: openid.message.NamespaceMap

    @param alias_list_s: The string containing the comma-separated
        list of aliases. May also be None for convenience.
    @type alias_list_s: str or NoneType

    @returns: The list of namespace URIs that corresponds to the
        supplied list of aliases. If the string was zero-length or
        None, an empty list will be returned.

    @raise KeyError: If an alias is present in the list of aliases but
        is not present in the namespace map."""
    uris = []
    if alias_list_s:
        for alias in alias_list_s.split(','):
            type_uri = namespace_map.getNamespaceURI(alias)
            if type_uri is None:
                raise KeyError('No type is defined for attribute name %r' % (alias,))
            else:
                uris.append(type_uri)
    return uris

def returnToMatches(allowed_return_to_urls, return_to):
    """Is the return_to URL under one of the supplied allowed
    return_to URLs?

    @since: 2.1.0"""
    for allowed_return_to in allowed_return_to_urls:
        return_realm = TrustRoot.parse(allowed_return_to)
        if return_realm is not None and (not return_realm.wildcard) and return_realm.validateURL(return_to):
            return True
    return False

def getAllowedReturnURLs(relying_party_url):
    """Given a relying party discovery URL return a list of return_to URLs.

    @since: 2.1.0"""
    rp_url_after_redirects, return_to_urls = services.getServiceEndpoints(relying_party_url, _extractReturnURL)
    if rp_url_after_redirects != relying_party_url:
        raise RealmVerificationRedirected(relying_party_url, rp_url_after_redirects)
    return return_to_urls

