def execute(cmd, cwd=None):
    """Execute a command and return it's output."""
    try:
        lines = subprocess.check_output(cmd, cwd=cwd, stderr=DEVNULL).splitlines()
    except subprocess.CalledProcessError:
        return None
    else:
        if lines:
            return decode(lines[0].strip())
        else:
            return None

def decode(s):
    """Decode a string using the system encoding if needed (ie byte strings)"""
    if isinstance(s, bytes):
        return s.decode(sys.getdefaultencoding())
    else:
        return s

def run(version, quiet, no_fetch, push, **kwargs):
    """A nicer `git pull`."""
    if version:
        if NO_DISTRIBUTE:
            print(colored("Please install 'git-up' via pip in order to get version information.", 'yellow'))
        else:
            GitUp(sparse=True).version_info()
        return
    if quiet:
        sys.stdout = StringIO()
    try:
        gitup = GitUp()
        if push is not None:
            gitup.settings['push.auto'] = push
        if no_fetch:
            gitup.should_fetch = False
    except GitError:
        sys.exit(1)
    else:
        gitup.run()

def makeelement(tagname, tagtext=None, nsprefix='w', attributes=None, attrnsprefix=None):
    """Create an element & return it"""
    namespacemap = None
    if isinstance(nsprefix, list):
        namespacemap = {}
        for prefix in nsprefix:
            namespacemap[prefix] = nsprefixes[prefix]
        nsprefix = nsprefix[0]
    if nsprefix:
        namespace = '{%s}' % nsprefixes[nsprefix]
    else:
        namespace = ''
    newelement = etree.Element(namespace + tagname, nsmap=namespacemap)
    if attributes:
        if not attrnsprefix:
            if nsprefix == 'w':
                attributenamespace = namespace
            else:
                attributenamespace = ''
        else:
            attributenamespace = '{' + nsprefixes[attrnsprefix] + '}'
        for tagattribute in attributes:
            newelement.set(attributenamespace + tagattribute, attributes[tagattribute])
    if tagtext:
        newelement.text = tagtext
    return newelement

def clean(document):
    """Perform misc cleaning operations on documents.
    Returns cleaned document."""
    newdocument = document
    for t in ('t', 'r'):
        rmlist = []
        for element in newdocument.iter():
            if element.tag == '{%s}%s' % (nsprefixes['w'], t):
                if not element.text and (not len(element)):
                    rmlist.append(element)
        for element in rmlist:
            element.getparent().remove(element)
    return newdocument

def findTypeParent(element, tag):
    """Finds fist parent of element of the given type

    @param object element: etree element
    @param string the tag parent to search for

    @return object element: the found parent or None when not found"""
    p = element
    while True:
        p = p.getparent()
        if p.tag == tag:
            return p
    return None

def getdocumenttext(document):
    """Return the raw text of a document, as a list of paragraphs."""
    paratextlist = []
    paralist = []
    for element in document.iter():
        if element.tag == '{' + nsprefixes['w'] + '}p':
            paralist.append(element)
    for para in paralist:
        paratext = u''
        for element in para.iter():
            if element.tag == '{' + nsprefixes['w'] + '}t':
                if element.text:
                    paratext = paratext + element.text
            elif element.tag == '{' + nsprefixes['w'] + '}tab':
                paratext = paratext + '\t'
        if not len(paratext) == 0:
            paratextlist.append(paratext)
    return paratextlist

