def _build_connstr(host, port, bucket):
    """Converts a 1.x host:port specification to a connection string"""
    hostlist = []
    if isinstance(host, (tuple, list)):
        for curhost in host:
            if isinstance(curhost, (list, tuple)):
                hostlist.append(_fmthost(*curhost))
            else:
                hostlist.append(curhost)
    else:
        hostlist.append(_fmthost(host, port))
    return 'http://{0}/{1}'.format(','.join(hostlist), bucket)

def _mk_lcberr(rc, name=None, default=CouchbaseError, docstr='', extrabase=[]):
    """Create a new error class derived from the appropriate exceptions.
    :param int rc: libcouchbase error code to map
    :param str name: The name of the new exception
    :param class default: Default exception to return if no categories are found
    :return: a new exception derived from the appropriate categories, or the
             value supplied for `default`"""
    categories = C._get_errtype(rc)
    if not categories:
        return default
    bases = extrabase[:]
    for cat, base in _LCB_ERRCAT_MAP.items():
        if cat & categories:
            bases.append(base)
    if name is None:
        name = 'LCB_0x{0:0X} (generated, catch: {1})'.format(rc, ', '.join((x.__name__ for x in bases)))
    d = {'__doc__': docstr}
    if not bases:
        bases = [CouchbaseError]
    return type(name, tuple(bases), d)

def deprecate_module_attribute(mod, deprecated):
    """Return a wrapped object that warns about deprecated accesses"""
    deprecated = set(deprecated)
    class Wrapper(object):
        def __getattr__(self, attr):
            if attr in deprecated:
                warnings.warn('Property %s is deprecated' % attr)
            return getattr(mod, attr)
        def __setattr__(self, attr, value):
            if attr in deprecated:
                warnings.warn('Property %s is deprecated' % attr)
            return setattr(mod, attr, value)
    return Wrapper()

def _gen_3spec(op, path, xattr=False):
    """Returns a Spec tuple suitable for passing to the underlying C extension.
    This variant is called for operations that lack an input value.

    :param str path: The path to fetch
    :param bool xattr: Whether this is an extended attribute
    :return: a spec suitable for passing to the underlying C extension"""
    flags = 0
    if xattr:
        flags |= _P.SDSPEC_F_XATTR
    return Spec(op, path, flags)

def _gen_4spec(op, path, value, create_path=False, xattr=False, _expand_macros=False):
    """Like `_gen_3spec`, but also accepts a mandatory value as its third argument
    :param bool _expand_macros: Whether macros in the value should be expanded.
        The macros themselves are defined at the server side"""
    flags = 0
    if create_path:
        flags |= _P.SDSPEC_F_MKDIR_P
    if xattr:
        flags |= _P.SDSPEC_F_XATTR
    if _expand_macros:
        flags |= _P.SDSPEC_F_EXPANDMACROS
    return Spec(op, path, flags, value)

def _assign_kwargs(self, kwargs):
    """Assigns all keyword arguments to a given instance, raising an exception
    if one of the keywords is not already the name of a property."""
    for k in kwargs:
        if not hasattr(self, k):
            raise AttributeError(k, 'Not valid for', self.__class__.__name__)
        setattr(self, k, kwargs[k])

def _with_fields(*fields):
    """Class decorator to include common query fields
    :param fields: List of fields to include. These should be keys of the
        `_COMMON_FIELDS` dict"""
    dd = {}
    for x in fields:
        dd[x] = _COMMON_FIELDS[x]
    def wrap(cls):
        dd.update(cls.__dict__)
        return type(cls.__name__, cls.__bases__, dd)
    return wrap

def _bprop_wrap(name, reqtype, doc):
    """Helper function to generate properties
    :param name: The name of the subfield in the JSON dictionary
    :param reqtype: The compound query type the query
        list should be coerced into
    :param doc: Documentation for the field
    :return: the property."""
    def fget(self):
        return self._subqueries.get(name)
    def fset(self, value):
        if value is None:
            if name in self._subqueries:
                del self._subqueries[name]
        elif isinstance(value, reqtype):
            self._subqueries[name] = value
        elif isinstance(value, Query):
            self._subqueries[name] = reqtype(value)
        else:
            try:
                it = iter(value)
            except ValueError:
                raise TypeError('Value must be instance of Query')
            l = []
            for q in it:
                if not isinstance(q, Query):
                    raise TypeError('Item is not a query!', q)
                l.append(q)
            self._subqueries[name] = reqtype(*l)
    def fdel(self):
        setattr(self, name, None)
    return property(fget, fset, fdel, doc)

def get_version():
    """Returns the version from the generated version file without actually
    loading it (and thus trying to load the extension module)."""
    if not os.path.exists(VERSION_FILE):
        raise VersionNotFound(VERSION_FILE + ' does not exist')
    fp = open(VERSION_FILE, 'r')
    vline = None
    for x in fp.readlines():
        x = x.rstrip()
        if not x:
            continue
        if not x.startswith('__version__'):
            continue
        vline = x.split('=')[1]
        break
    if not vline:
        raise VersionNotFound('version file present but has no contents')
    return vline.strip().rstrip().replace("'", '')

def parseargs(argv):
    """handle --help, --version and our double-equal ==options"""
    args = []
    options = {}
    key = None
    for arg in argv:
        if arg in DEFAULT_OPTION_VALUES:
            key = arg.strip('=').replace('-', '_')
            options[key] = ()
        elif key is None:
            args.append(arg)
        else:
            options[key] += (arg,)
    if set(args) & {'-h', '--help'}:
        print(__doc__, end='')
        exit(0)
    elif set(args) & {'-V', '--version'}:
        print(__version__)
        exit(0)
    elif args:
        exit('invalid option: %s\nTry --help for more information.' % args[0])
    return options

def ensure_virtualenv(args, return_values):
    """Ensure we have a valid virtualenv."""
    def adjust_options(options, args):
        venv_path = return_values.venv_path = args[0]
        if venv_path == DEFAULT_VIRTUALENV_PATH or options.prompt == '<dirname>':
            from os.path import abspath, basename, dirname
            options.prompt = '(%s)' % basename(dirname(abspath(venv_path)))
        if options.python is None:
            source_python = None
        else:
            source_python = virtualenv.resolve_interpreter(options.python)
        destination_python = venv_python(venv_path)
        if exists(destination_python):
            reason = invalid_virtualenv_reason(venv_path, source_python, destination_python, options)
            if reason:
                info('Removing invalidated virtualenv. (%s)' % reason)
                run(('rm', '-rf', venv_path))
            else:
                info('Keeping valid virtualenv from previous run.')
                raise SystemExit(0)
    import virtualenv
    virtualenv.adjust_options = adjust_options
    from sys import argv
    argv[:] = ('virtualenv',) + args
    info(colorize(argv))
    raise_on_failure(virtualenv.main)
    if return_values.venv_path is not None:
        run(('rm', '-rf', join(return_values.venv_path, 'local')))

def touch(filename, timestamp):
