def assign_texts(node, words, next_idx=0):
    """Recursively assign the words to nodes by finding and
    assigning strings to the leaves of a tree in left
    to right order."""
    if len(node.children) == 0:
        node.text = words[next_idx]
        return next_idx + 1
    else:
        for child in node.children:
            next_idx = assign_texts(child, words, next_idx)
        return next_idx

def read_tree(parents, labels, words):
    """Take as input a list of integers for parents
    and labels, along with a list of words, and
    reconstruct a LabeledTree."""
    trees = {}
    root = None
    for i in range(1, len(parents) + 1):
        if not i in trees and parents[i - 1] != -1:
            idx = i
            prev = None
            while True:
                parent = parents[idx - 1]
                if parent == -1:
                    break
                tree = LabeledTree()
                if prev is not None:
                    tree.add_child(prev)
                trees[idx] = tree
                tree.label = labels[idx - 1]
                if trees.get(parent) is not None:
                    trees[parent].add_child(tree)
                    break
                elif parent == 0:
                    root = tree
                    break
                else:
                    prev = tree
                    idx = parent
    assert assign_texts(root, words) == len(words)
    return root

def _getitem(string, depth=0):
    """Get an item from the string (where item is up to the next ',' or '}' or the
    end of the string)"""
    out = ['']
    while string:
        char = string[0]
        if depth and (char == ',' or char == '}'):
            return (out, string)
        if char == '{':
            groups_string = _getgroup(string[1:], depth + 1)
            if groups_string is not None:
                groups, string = groups_string
                out = [a + g for a in out for g in groups]
                continue
        if char == '\\' and len(string) > 1:
            string, char = (string[1:], char + string[1])
        out, string = ([a + char for a in out], string[1:])
    return (out, string)

def _getgroup(string, depth):
    """Get a group from the string, where group is a list of all the comma
    separated substrings up to the next '}' char or the brace enclosed substring
    if there is no comma"""
    out, comma = ([], False)
    while string:
        items, string = _getitem(string, depth)
        if not string:
            break
        out += items
        if string[0] == '}':
            if comma:
                return (out, string[1:])
            return (['{' + a + '}' for a in out], string[1:])
        if string[0] == ',':
            comma, string = (True, string[1:])
    return None

def extract(context, data):
    """Extract a compressed file"""
    with context.http.rehash(data) as result:
        file_path = result.file_path
        content_type = result.content_type
        extract_dir = random_filename(context.work_path)
        if content_type in ZIP_MIME_TYPES:
            extracted_files = extract_zip(file_path, extract_dir)
        elif content_type in TAR_MIME_TYPES:
            extracted_files = extract_tar(file_path, extract_dir, context)
        elif content_type in SEVENZIP_MIME_TYPES:
            extracted_files = extract_7zip(file_path, extract_dir, context)
        else:
            context.log.warning('Unsupported archive content type: %s', content_type)
            return
        extracted_content_hashes = {}
        for path in extracted_files:
            relative_path = os.path.relpath(path, extract_dir)
            content_hash = context.store_file(path)
            extracted_content_hashes[relative_path] = content_hash
            data['content_hash'] = content_hash
            data['file_name'] = relative_path
            context.emit(data=data.copy())

def read_word(image, whitelist=None, chars=None, spaces=False):
    """OCR a single word from an image. Useful for captchas.
    Image should be pre-processed to remove noise etc."""
    from tesserocr import PyTessBaseAPI
    api = PyTessBaseAPI()
    api.SetPageSegMode(8)
    if whitelist is not None:
        api.SetVariable('tessedit_char_whitelist', whitelist)
    api.SetImage(image)
    api.Recognize()
    guess = api.GetUTF8Text()
    if not spaces:
        guess = ''.join([c for c in guess if c != ' '])
        guess = guess.strip()
    if chars is not None and len(guess) != chars:
        return (guess, None)
    return (guess, api.MeanTextConf())

def read_char(image, whitelist=None):
    """OCR a single character from an image. Useful for captchas."""
    from tesserocr import PyTessBaseAPI
    api = PyTessBaseAPI()
    api.SetPageSegMode(10)
    if whitelist is not None:
        api.SetVariable('tessedit_char_whitelist', whitelist)
    api.SetImage(image)
    api.Recognize()
    return api.GetUTF8Text().strip()

def fetch(context, data):
    """Do an HTTP GET on the ``url`` specified in the inbound data."""
    url = data.get('url')
    attempt = data.pop('retry_attempt', 1)
    try:
        result = context.http.get(url, lazy=True)
        rules = context.get('rules', {'match_all': {}})
        if not Rule.get_rule(rules).apply(result):
            context.log.info('Fetch skip: %r', result.url)
            return
        if not result.ok:
            err = (result.url, result.status_code)
            context.emit_warning('Fetch fail [%s]: HTTP %s' % err)
            if not context.params.get('emit_errors', False):
                return
        else:
            context.log.info('Fetched [%s]: %r', result.status_code, result.url)
        data.update(result.serialize())
        if url != result.url:
            tag = make_key(context.run_id, url)
            context.set_tag(tag, None)
        context.emit(data=data)
    except RequestException as ce:
        retries = int(context.get('retry', 3))
        if retries >= attempt:
            context.log.warn('Retry: %s (error: %s)', url, ce)
            data['retry_attempt'] = attempt + 1
            context.recurse(data=data, delay=2 ** attempt)
        else:
            context.emit_warning('Fetch fail [%s]: %s' % (url, ce))

def soviet_checksum(code):
    """Courtesy of Sir Vlad Lavrov."""
    def sum_digits(code, offset=1):
        total = 0
        for digit, index in zip(code[:7], count(offset)):
            total += int(digit) * index
        summed = total / 11 * 11
        return total - summed
    check = sum_digits(code, 1)
    if check == 10:
        check = sum_digits(code, 3)
        if check == 10:
            return code + '0'
    return code + str(check)

def search_results_total(html, xpath, check, delimiter):
    """Get the total number of results from the DOM of a search index."""
    for container in html.findall(xpath):
        if check in container.findtext('.'):
            text = container.findtext('.').split(delimiter)
            total = int(text[-1].strip())
            return total

def search_results_last_url(html, xpath, label):
    """Get the URL of the 'last' button in a search results listing."""
    for container in html.findall(xpath):
        if container.text_content().strip() == label:
            return container.find('.//a').get('href')

def _recursive_upsert(context, params, data):
    """Insert or update nested dicts recursively into db tables"""
    children = params.get('children', {})
    nested_calls = []
    for child_params in children:
        key = child_params.get('key')
        child_data_list = ensure_list(data.pop(key))
        if isinstance(child_data_list, dict):
            child_data_list = [child_data_list]
        if not (isinstance(child_data_list, list) and all((isinstance(i, dict) for i in child_data_list))):
            context.log.warn('Expecting a dict or a lost of dicts as children for key', key)
            continue
        if child_data_list:
            table_suffix = child_params.get('table_suffix', key)
            child_params['table'] = params.get('table') + '_' + table_suffix
            inherit = child_params.get('inherit', {})
            for child_data in child_data_list:
                for dest, src in inherit.items():
                    child_data[dest] = data.get(src)
                nested_calls.append((child_params, child_data))
    _upsert(context, params, data)
    for child_params, child_data in nested_calls:
        _recursive_upsert(context, child_params, child_data)

