def make_key(*criteria):
    """Make a string key out of many criteria."""
    criteria = [stringify(c) for c in criteria]
    criteria = [c for c in criteria if c is not None]
    if len(criteria):
        return ':'.join(criteria)

def _sample_orthonormal_to(mu):
    """Sample point on sphere orthogonal to mu."""
    v = np.random.randn(mu.shape[0])
    proj_mu_v = mu * np.dot(mu, v) / np.linalg.norm(mu)
    orthto = v - proj_mu_v
    return orthto / np.linalg.norm(orthto)

def _inertia_from_labels(X, centers, labels):
    """Compute inertia with cosine distance using known labels.
    """
    n_examples, n_features = X.shape
    inertia = np.zeros((n_examples,))
    for ee in range(n_examples):
        inertia[ee] = 1 - X[ee, :].dot(centers[int(labels[ee]), :].T)
    return np.sum(inertia)

def _vmf_log(X, kappa, mu):
    """Computs log(vMF(X, kappa, mu)) using built-in numpy/scipy Bessel
    approximations.

    Works well on small kappa and mu."""
    n_examples, n_features = X.shape
    return np.log(_vmf_normalize(kappa, n_features) * np.exp(kappa * X.dot(mu).T))

def _vmf_normalize(kappa, dim):
    """Compute normalization constant using built-in numpy/scipy Bessel
    approximations.

    Works well on small kappa and mu."""
    num = np.power(kappa, dim / 2.0 - 1.0)
    if dim / 2.0 - 1.0 < 1e-15:
        denom = np.power(2.0 * np.pi, dim / 2.0) * i0(kappa)
    else:
        denom = np.power(2.0 * np.pi, dim / 2.0) * iv(dim / 2.0 - 1.0, kappa)
    if np.isinf(num):
        raise ValueError('VMF scaling numerator was inf.')
    if np.isinf(denom):
        raise ValueError('VMF scaling denominator was inf.')
    if np.abs(denom) < 1e-15:
        raise ValueError('VMF scaling denominator was 0.')
    return num / denom

def empirical(X):
    """Compute empirical covariance as baseline estimator.
    """
    print('Empirical')
    cov = np.dot(X.T, X) / n_samples
    return (cov, np.linalg.inv(cov))

def support_false_positive_count(m, m_hat):
    """Count the number of false positive support elements in
    m_hat in one triangle, not including the diagonal."""
    m_nnz, m_hat_nnz, intersection_nnz = _nonzero_intersection(m, m_hat)
    return int((m_hat_nnz - intersection_nnz) / 2.0)

def support_false_negative_count(m, m_hat):
    """Count the number of false negative support elements in
    m_hat in one triangle, not including the diagonal."""
    m_nnz, m_hat_nnz, intersection_nnz = _nonzero_intersection(m, m_hat)
    return int((m_nnz - intersection_nnz) / 2.0)

def support_difference_count(m, m_hat):
    """Count the number of different elements in the support in one triangle,
    not including the diagonal."""
    m_nnz, m_hat_nnz, intersection_nnz = _nonzero_intersection(m, m_hat)
    return int((m_nnz + m_hat_nnz - 2 * intersection_nnz) / 2.0)

def has_exact_support(m, m_hat):
    """Returns 1 if support_difference_count is zero, 0 else.
    """
    m_nnz, m_hat_nnz, intersection_nnz = _nonzero_intersection(m, m_hat)
    return int(m_nnz + m_hat_nnz - 2 * intersection_nnz == 0)

def _validate_path(path):
    """Sorts path values from largest to smallest.

    Will warn if path parameter was not already sorted."""
    if path is None:
        return None
    new_path = np.array(sorted(set(path), reverse=True))
    if new_path[0] != path[0]:
        print('Warning: Path must be sorted largest to smallest.')
    return new_path

def _quic_path(X, path, X_test=None, lam=0.5, tol=1e-06, max_iter=1000, Theta0=None, Sigma0=None, method='quic', verbose=0, score_metric='log_likelihood', init_method='corrcoef'):
    """Wrapper to compute path for example X.
    """
    S, lam_scale_ = _init_coefs(X, method=init_method)
    path = path.copy(order='C')
    if method == 'quic':
        precisions_, covariances_, opt_, cputime_, iters_, duality_gap_ = quic(S, lam, mode='path', tol=tol, max_iter=max_iter, Theta0=Theta0, Sigma0=Sigma0, path=path, msg=verbose)
    else:
        raise NotImplementedError("Only method='quic' has been implemented.")
    if X_test is not None:
        S_test, lam_scale_test = _init_coefs(X_test, method=init_method)
        path_errors = []
        for lidx, lam in enumerate(path):
            path_errors.append(_compute_error(S_test, covariances_[lidx], precisions_[lidx], score_metric=score_metric))
        scores_ = [-e for e in path_errors]
        return (covariances_, precisions_, scores_)
    return (covariances_, precisions_)

def asbool(s):
    """Return the boolean value ``True`` if the case-lowered value of string
    input ``s`` is a :term:`truthy string`. If ``s`` is already one of the
    boolean values ``True`` or ``False``, return it."""
    if s is None:
        return False
    if isinstance(s, bool):
        return s
    s = str(s).strip()
    return s.lower() in truthy

def _find_plugin_dir(module_type):
    """Find the directory containing the plugin definition for the given type.
    Do this by searching all the paths where plugins can live for a dir that
    matches the type name."""
    for install_dir in _get_plugin_install_dirs():
        candidate = os.path.join(install_dir, module_type)
        if os.path.isdir(candidate):
            return candidate
    else:
        raise PluginCandidateError('No plugin found for `{}` module in paths:\n{}'.format(module_type, '\n'.join(_get_plugin_install_dirs())))

def _get_plugin_install_dirs():
    """Return all the places on the filesystem where we should look for plugin
    definitions. Order is significant here: user-installed plugins should be
    searched first, followed by system-installed plugins, and last of all peru
    builtins."""
    builtins_dir = os.path.join(compat.MODULE_ROOT, 'resources', 'plugins')
    if os.name == 'nt':
        local_data_dir = os.path.expandvars('%LOCALAPPDATA%')
        program_files_dir = os.path.expandvars('%PROGRAMFILES%')
        return (os.path.join(local_data_dir, 'peru', 'plugins'), os.path.join(program_files_dir, 'peru', 'plugins'), builtins_dir)
    else:
        default_config_dir = os.path.expanduser('~/.config')
        config_dir = os.environ.get('XDG_CONFIG_HOME', default_config_dir)
        return (os.path.join(config_dir, 'peru', 'plugins'), '/usr/local/lib/peru/plugins', '/usr/lib/peru/plugins', builtins_dir)

def unglobbed_prefix(glob):
    """Returns all the path components, starting from the beginning, up to the
    first one with any kind of glob. So for example, if glob is 'a/b/c*/d',
    return 'a/b'."""
    parts = []
    for part in PurePosixPath(glob).parts:
        if contains_unescaped_stars(part):
            break
        else:
            parts.append(part)
    return str(PurePosixPath(*parts)) if parts else ''

def glob_to_path_regex(glob):
    """Supports * and **. Backslashes can escape stars or other backslashes. As
    in pathlib, ** may not adjoin any characters other than slash. Unlike
    pathlib, because we're not talking to the actual filesystem, ** will match
    files as well as directories. Paths get canonicalized before they're
    converted, so duplicate and trailing slashes get dropped. You should make
    sure the other paths you try to match are in canonical (Posix) form as
    well."""
    canonical_glob = str(PurePosixPath(glob))
    regex = '^'
    components = canonical_glob.split('/')
    for i, component in enumerate(components):
        if component == '**':
            if i == len(components) - 1:
                raise GlobError(glob, '** may not be the last component in a path.')
            else:
                regex += '(?:[^/]+/)*'
        elif '**' in component:
            raise GlobError(glob, '** must be an entire path component.')
        else:
            if component == '*':
                regex += '[^/]+'
            else:
                star_parts = split_on_stars_interpreting_backslashes(component)
                escaped_parts = map(re.escape, star_parts)
                regex += '[^/]*'.join(escaped_parts)
            if i < len(components) - 1:
                regex += '/'
    regex += '$'
    return regex

def merged_args_dicts(global_args, subcommand_args):
    """We deal with docopt args from the toplevel peru parse and the subcommand
    parse. We don't want False values for a flag in the subcommand to override
    True values if that flag was given at the top level. This function
    specifically handles that case."""
    merged = global_args.copy()
    for key, val in subcommand_args.items():
        if key not in merged:
            merged[key] = val
        elif type(merged[key]) is type(val) is bool:
            merged[key] = merged[key] or val
        else:
            raise RuntimeError('Unmergable args.')
    return merged

def _maybe_quote(val):
    """All of our values should be strings. Usually those can be passed in as
    bare words, but if they're parseable as an int or float we need to quote
    them."""
    assert isinstance(val, str), 'We should never set non-string values.'
    needs_quoting = False
    try:
        int(val)
        needs_quoting = True
    except Exception:
        pass
    try:
        float(val)
        needs_quoting = True
    except Exception:
        pass
    if needs_quoting:
        return '"{}"'.format(val)
    else:
        return val

def raises_gathered(error_type):
    """For use in tests. Many tests expect a single error to be thrown, and
    want it to be of a specific type. This is a helper method for when that
    type is inside a gathered exception."""
    container = RaisesGatheredContainer()
    try:
        yield container
    except GatheredExceptions as e:
        if len(e.exceptions) != 1:
            raise
        inner = e.exceptions[0]
        if not isinstance(inner, error_type):
            raise
        container.exception = inner

def get_request_filename(request):
    """Figure out the filename for an HTTP download."""
    if 'Content-Disposition' in request.info():
        disposition = request.info()['Content-Disposition']
        pieces = re.split('\\s*;\\s*', disposition)
        for piece in pieces:
            if piece.startswith('filename='):
                filename = piece[len('filename='):]
                if filename.startswith('"'):
                    filename = filename[1:]
                if filename.endswith('"'):
                    filename = filename[:-1]
                filename = filename.replace('\\"', '"')
                return filename
    return os.path.basename(urlsplit(request.url).path) or 'index.html'

def _optional_list(value):
    """Convert a value that may be a scalar (str) or list into a tuple. This
    produces uniform output for fields that may supply a single value or list
    of values, like the `imports` field."""
    if isinstance(value, str):
        return (value,)
    elif isinstance(value, list):
        return tuple(value)
    return None

def find_project_file(start_dir, basename):
    """Walk up the directory tree until we find a file of the given name."""
    prefix = os.path.abspath(start_dir)
    while True:
        candidate = os.path.join(prefix, basename)
        if os.path.isfile(candidate):
            return candidate
        if os.path.exists(candidate):
            raise PrintableError("Found {}, but it's not a file.".format(candidate))
        if os.path.dirname(prefix) == prefix:
            raise PrintableError("Can't find " + basename)
        prefix = os.path.dirname(prefix)

def delete_if_error(path):
    """If any exception is raised inside the context, delete the file at the
    given path, and allow the exception to continue."""
    try:
        yield
    except Exception:
        if os.path.exists(path):
            os.remove(path)
        raise

def _format_file_lines(files):
    """Given a list of filenames that we're about to print, limit it to a
    reasonable number of lines."""
    LINES_TO_SHOW = 10
    if len(files) <= LINES_TO_SHOW:
        lines = '\n'.join(files)
    else:
        lines = '\n'.join(files[:LINES_TO_SHOW - 1]) + '\n...{} total'.format(len(files))
    return lines

def load_states():
    """Load state data from pickle file distributed with this package.

    Creates lists of states, territories, and combined states and
    territories. Also adds state abbreviation attribute access
    to the package: us.states.MD"""
    from pkg_resources import resource_stream
    with resource_stream(__name__, 'states.pkl') as pklfile:
        for s in pickle.load(pklfile):
            state = State(**s)
            if state.is_obsolete:
                OBSOLETE.append(state)
            elif state.is_territory:
                TERRITORIES.append(state)
            else:
                STATES.append(state)
                if state.is_contiguous:
                    STATES_CONTIGUOUS.append(state)
                if state.is_continental:
                    STATES_CONTINENTAL.append(state)
            STATES_AND_TERRITORIES.append(state)
            globals()[state.abbr] = state

