def download_archive(sources):
    """Downloads an archive and saves locally (taken from PySMT)."""
    save_to = sources[-1]
    if os.path.exists(save_to):
        print('not downloading {0} since it exists locally'.format(save_to))
        return
    for url in sources[:-1]:
        for i in range(5):
            response = urlopen(url)
            u = urlopen(response.geturl())
            meta = u.info()
            if meta.get('Content-Length') and len(meta.get('Content-Length')) > 0:
                filesz = int(meta.get('Content-Length'))
                if os.path.exists(save_to) and os.path.getsize(save_to) == filesz:
                    print('not downloading {0} since it exists locally'.format(save_to))
                    return
                print('downloading: {0} ({1} bytes)...'.format(save_to, filesz), end=' ')
                with open(save_to, 'wb') as fp:
                    block_sz = 8192
                    while True:
                        buff = u.read(block_sz)
                        if not buff:
                            break
                        fp.write(buff)
                print('done')
                break
        else:
            continue
        break
    else:
        assert 0, 'something went wrong -- cannot download {0}'.format(save_to)

def extract_archive(archive, solver, put_inside=False):
    """Unzips/untars a previously downloaded archive file."""
    print('extracting {0}'.format(archive))
    root = os.path.join('solvers', solver if put_inside else '')
    if archive.endswith('.tar.gz'):
        if os.path.exists(archive[:-7]):
            shutil.rmtree(archive[:-7])
        tfile = tarfile.open(archive, 'r:gz')
        tfile.extractall(root)
        for name in tfile.getnames():
            if not name.startswith('./.'):
                directory = name
                break
    elif archive.endswith('.zip'):
        if os.path.exists(archive[:-4]):
            shutil.rmtree(archive[:-4])
        myzip = zipfile.ZipFile(archive, 'r')
        myzip.extractall(root)
        directory = myzip.namelist()[0]
        directory = directory.rstrip('/').split('/')[0]
        myzip.close()
    if not put_inside:
        if os.path.exists(os.path.join('solvers', solver)):
            shutil.rmtree(os.path.join('solvers', solver))
        shutil.move(os.path.join('solvers', directory), os.path.join('solvers', solver))

def adapt_files(solver):
    """Rename and remove files whenever necessary."""
    print("adapting {0}'s files".format(solver))
    root = os.path.join('solvers', solver)
    for arch in to_extract[solver]:
        arch = os.path.join(root, arch)
        extract_archive(arch, solver, put_inside=True)
    for fnames in to_move[solver]:
        old = os.path.join(root, fnames[0])
        new = os.path.join(root, fnames[1])
        os.rename(old, new)
    for f in to_remove[solver]:
        f = os.path.join(root, f)
        if os.path.isdir(f):
            shutil.rmtree(f)
        else:
            os.remove(f)

def parse_options():
    """Parses command-line options:"""
    try:
        opts, args = getopt.getopt(sys.argv[1:], 'k:n:ht:v', ['kval=', 'size=', 'help', 'type=', 'verb'])
    except getopt.GetoptError as err:
        sys.stderr.write(str(err).capitalize())
        usage()
        sys.exit(1)
    kval = 1
    size = 8
    ftype = 'php'
    verb = False
    for opt, arg in opts:
        if opt in ('-h', '--help'):
            usage()
            sys.exit(0)
        elif opt in ('-k', '--kval'):
            kval = int(arg)
        elif opt in ('-n', '--size'):
            size = int(arg)
        elif opt in ('-t', '--type'):
            ftype = str(arg)
        elif opt in ('-v', '--verb'):
            verb = True
        else:
            assert False, 'Unhandled option: {0} {1}'.format(opt, arg)
    return (ftype, kval, size, verb)

def parse_options():
    """Parses command-line options."""
    try:
        opts, args = getopt.getopt(sys.argv[1:], 'hms:v', ['help', 'model', 'solver=', 'verbose'])
    except getopt.GetoptError as err:
        sys.stderr.write(str(err).capitalize())
        print_usage()
        sys.exit(1)
    solver = 'g4'
    verbose = 1
    print_model = False
    for opt, arg in opts:
        if opt in ('-h', '--help'):
            print_usage()
            sys.exit(0)
        elif opt in ('-m', '--model'):
            print_model = True
        elif opt in ('-s', '--solver'):
            solver = str(arg)
        elif opt in ('-v', '--verbose'):
            verbose += 1
        else:
            assert False, 'Unhandled option: {0} {1}'.format(opt, arg)
    return (print_model, solver, verbose, args)

def parse_formula(fml_file):
    """Parse and return MaxSAT formula."""
    if re.search('\\.wcnf(\\.(gz|bz2|lzma|xz))?$', fml_file):
        fml = WCNF(from_file=fml_file)
    else:
        fml = CNF(from_file=fml_file).weighted()
    return fml

def __is_valid_pos(pos_tuple, valid_pos):
    """This function checks token's pos is with in POS set that user specified.
    If token meets all conditions, Return True; else return False"""
    def is_valid_pos(valid_pos_tuple):
        length_valid_pos_tuple = len(valid_pos_tuple)
        if valid_pos_tuple == pos_tuple[:length_valid_pos_tuple]:
            return True
        else:
            return False
    seq_bool_flags = [is_valid_pos(valid_pos_tuple) for valid_pos_tuple in valid_pos]
    if True in set(seq_bool_flags):
        return True
    else:
        return False

def denormalize_text(input_text):
    """* What you can do
    - It converts text into standard japanese writing way

    * Note
    - hankaku-katakana is to zenkaku-katakana
    - zenkaku-eisu is to hankaku-eisu"""
    if input_text in STRING_EXCEPTION:
        return input_text
    else:
        return jaconv.z2h(input_text, kana=False, ascii=True, digit=True)

def normalize_text_normal_ipadic(input_text, kana=True, ascii=True, digit=True):
    """* All hankaku Katanaka is converted into Zenkaku Katakana
    * All hankaku English alphabet and numberc string are converted into Zenkaku one"""
    return jaconv.h2z(input_text, kana=kana, ascii=ascii, digit=digit)

def feature_parser(uni_feature, word_surface):
    """Parse the POS feature output by Mecab
    :param uni_feature unicode:
    :return ( (pos1, pos2, pos3), word_stem ):"""
    list_feature_items = uni_feature.split(',')
    if len(list_feature_items) == 1:
        return ('*', '*')
    pos1 = list_feature_items[0]
    pos2 = list_feature_items[1]
    pos3 = list_feature_items[2]
    tuple_pos = (pos1, pos2, pos3)
    if len(list_feature_items) == 9:
        word_stem = list_feature_items[6]
    else:
        word_stem = word_surface
    return (tuple_pos, word_stem)

def notify(notification, value=None, unset_environment=False):
    """Send notification to systemd daemon

    :type notification: Notification
    :type value: int
    :type unset_environment: bool
    :param value: str or int value for non constant notifications
    :returns None"""
    if not isinstance(notification, Notification):
        raise TypeError('state must be an instance of Notification')
    state = notification.value
    if state.constant is not None and value:
        raise ValueError('State %s should contain only constant value %r' % (state.name, state.constant), state.name, state.constant)
    line = '%s=%s' % (state.name, state.constant if state.constant is not None else state.type(value))
    log.debug('Send %r into systemd', line)
    try:
        return sd_notify(line, unset_environment)
    except Exception as e:
        log.error('%s', e)

def expand_source_paths(paths):
    """Convert pyc files into their source equivalents."""
    for src_path in paths:
        if src_path.endswith(('.pyc', '.pyo')):
            py_path = get_py_path(src_path)
            if os.path.exists(py_path):
                src_path = py_path
        yield src_path

def args_from_interpreter_flags():
    """Return a list of command-line arguments reproducing the current
    settings in sys.flags and sys.warnoptions."""
    flag_opt_map = {'debug': 'd', 'dont_write_bytecode': 'B', 'no_user_site': 's', 'no_site': 'S', 'ignore_environment': 'E', 'verbose': 'v', 'bytes_warning': 'b', 'quiet': 'q', 'optimize': 'O'}
    args = []
    for flag, opt in flag_opt_map.items():
        v = getattr(sys.flags, flag, 0)
        if v > 0:
            args.append('-' + opt * v)
    for opt in sys.warnoptions:
        args.append('-W' + opt)
    return args

def world_info(world_name, world_config=None, initial_indent='', next_indent='  '):
    """Gets and prints the information of a world.

    Args:
        world_name (str): the name of the world to retrieve information for
        world_config (dict optional): A dictionary containing the world's configuration. Will find the config if None. Defaults to None.
        initial_indent (str optional): This indent will apply to each output line. Defaults to "".
        next_indent (str optional): This indent will be applied within each nested line. Defaults to "  "."""
    if world_config is None:
        for config, _ in _iter_packages():
            for world in config['maps']:
                if world['name'] == world_name:
                    world_config = world
    if world_config is None:
        raise HolodeckException("Couldn't find world " + world_name)
    second_indent = initial_indent + next_indent
    agent_indent = second_indent + next_indent
    sensor_indent = agent_indent + next_indent
    print(initial_indent, world_config['name'])
    print(second_indent, 'Resolution:', world_config['window_width'], 'x', world_config['window_height'])
    print(second_indent, 'Agents:')
    for agent in world_config['agents']:
        print(agent_indent, 'Name:', agent['agent_name'])
        print(agent_indent, 'Type:', agent['agent_type'])
        print(agent_indent, 'Sensors:')
        for sensor in agent['sensors']:
            print(sensor_indent, sensor)

