def build_D3treeStandard(old, MAX_DEPTH, level=1, toplayer=None):
    """ For d3s examples all we need is a json with name, children and size .. eg

     {
    "name": "flare",
    "children": [
     {
      "name": "analytics",
      "children": [
           {
            "name": "cluster",
            "children": [
             {"name": "AgglomerativeCluster", "size": 3938},
             {"name": "CommunityStructure", "size": 3812},
             {"name": "HierarchicalCluster", "size": 6714},
             {"name": "MergeEdge", "size": 743}
            ]
           },
           etc..."""
    out = []
    if not old:
        old = toplayer
    for x in old:
        d = {}
        d['qname'] = x.qname
        d['name'] = x.bestLabel(quotes=False).replace('_', ' ')
        d['objid'] = x.id
        if x.children() and level < MAX_DEPTH:
            d['size'] = len(x.children()) + 5
            d['realsize'] = len(x.children())
            d['children'] = build_D3treeStandard(x.children(), MAX_DEPTH, level + 1)
        else:
            d['size'] = 1
            d['realsize'] = 0
        out += [d]
    return out

def build_D3treepie(old, MAX_DEPTH, level=1, toplayer=None):
    """Create the JSON needed by the treePie viz
    http://bl.ocks.org/adewes/4710330/94a7c0aeb6f09d681dbfdd0e5150578e4935c6ae

    Eg

    ['origin' , [n1, n2],
                    { 'name1' :
                            ['name1', [n1, n2],
                                    {'name1-1' : ...}
                            ] ,
                    } ,
    ]"""
    d = {}
    if not old:
        old = toplayer
    for x in old:
        label = x.bestLabel(quotes=False).replace('_', ' ')
        if x.children() and level < MAX_DEPTH:
            size = len(x.children())
            d[x.qname] = [label, [size, size], build_D3treepie(x.children(), MAX_DEPTH, level + 1)]
        else:
            size = 1
            d[x.qname] = [label, [size, size], {}]
    return d

def get_home_location():
    '''Gets the path of the local library folder
    :return - a string e.g. "/users/mac/ontospy"'''
    config = SafeConfigParser()
    config_filename = ONTOSPY_LOCAL + '/config.ini'
    if not os.path.exists(config_filename):
        config_filename = 'config.ini'
    config.read(config_filename)
    try:
        _location = config.get('models', 'dir')
        if _location.endswith('/'):
            return _location
        else:
            return _location + '/'
    except:
        config.add_section('models')
        config.set('models', 'dir', ONTOSPY_LIBRARY_DEFAULT)
        with open(config_filename, 'w') as f:
            config.write(f)
        return ONTOSPY_LIBRARY_DEFAULT

def get_localontologies(pattern=''):
    """returns a list of file names in the ontologies folder (not the full path)"""
    res = []
    ONTOSPY_LOCAL_MODELS = get_home_location()
    if not os.path.exists(ONTOSPY_LOCAL_MODELS):
        get_or_create_home_repo()
    for f in os.listdir(ONTOSPY_LOCAL_MODELS):
        if os.path.isfile(os.path.join(ONTOSPY_LOCAL_MODELS, f)):
            if not f.startswith('.') and (not f.endswith('.pickle')):
                if not pattern:
                    res += [f]
                elif pattern in f:
                    res += [f]
    return res

