def _point_in_bbox(point, bounds):
    """valid whether the point is inside the bounding box"""
    return not (point['coordinates'][1] < bounds[0] or point['coordinates'][1] > bounds[2] or point['coordinates'][0] < bounds[1] or (point['coordinates'][0] > bounds[3]))

def geometry_within_radius(geometry, center, radius):
    """To valid whether point or linestring or polygon is inside a radius around a center

    Keyword arguments:
    geometry  -- point/linstring/polygon geojson object
    center    -- point geojson object
    radius    -- radius

    if(geometry inside radius) return true else false"""
    if geometry['type'] == 'Point':
        return point_distance(geometry, center) <= radius
    elif geometry['type'] == 'LineString' or geometry['type'] == 'Polygon':
        point = {}
        coordinates = geometry['coordinates'][0] if geometry['type'] == 'Polygon' else geometry['coordinates']
        for coordinate in coordinates:
            point['coordinates'] = coordinate
            if point_distance(point, center) > radius:
                return False
    return True

def convertor(geometry, method='wgs2gcj'):
    """convert wgs84 to gcj
    referencing by https://github.com/wandergis/coordTransform_py"""
    if geometry['type'] == 'Point':
        coords = geometry['coordinates']
        coords[0], coords[1] = methods[method](coords[0], coords[1])
    elif geometry['type'] == 'LineString' or geometry['type'] == 'MutliPoint':
        coordinates = geometry['coordinates']
        for coords in coordinates:
            coords[0], coords[1] = methods[method](coords[0], coords[1])
    elif geometry['type'] == 'Polygon' or geometry['type'] == 'MultiLineString':
        coordinates = geometry['coordinates']
        for rings in coordinates:
            for coords in rings:
                coords[0], coords[1] = methods[method](coords[0], coords[1])
    elif geometry['type'] == 'MultiPolygon':
        coordinates = geometry['coordinates']
        for rings in coordinates:
            for lines in rings:
                for coords in lines:
                    coords[0], coords[1] = methods[method](coords[0], coords[1])
    return geometry

def merge_featurecollection(*jsons):
    """merge features into one featurecollection

    Keyword arguments:
    jsons   -- jsons object list

    return geojson featurecollection"""
    features = []
    for json in jsons:
        if json['type'] == 'FeatureCollection':
            for feature in json['features']:
                features.append(feature)
    return {'type': 'FeatureCollection', 'features': features}

def accepts_kwarg(func, kwarg):
    """Determine whether the callable `func` has a signature that accepts the
    keyword argument `kwarg`"""
    signature = inspect.signature(func)
    try:
        signature.bind_partial(**{kwarg: None})
        return True
    except TypeError:
        return False

def get_version(version):
    """Returns a PEP 386-compliant version number from VERSION."""
    main = get_main_version(version)
    sub = ''
    if version[3] != 'final':
        mapping = {'alpha': 'a', 'beta': 'b', 'rc': 'c'}
        sub = mapping[version[3]] + str(version[4])
    return main + sub

def get_main_version(version):
    """Returns main version (X.Y[.Z]) from VERSION."""
    parts = 2 if version[2] == 0 else 3
    return '.'.join((str(x) for x in version[:parts]))

def loop(server, test_loop=None):
    """Run the main loop

    server is a limbo Server object
    test_loop, if present, is a number of times to run the loop"""
    try:
        loops_without_activity = 0
        while test_loop is None or test_loop > 0:
            start = time.time()
            loops_without_activity += 1
            events = server.slack.rtm_read()
            for event in events:
                loops_without_activity = 0
                logger.debug('got {0}'.format(event))
                response = handle_event(event, server)
                thread_ts = None
                if 'thread_ts' in event:
                    thread_ts = event['thread_ts']
                while response:
                    server.slack.rtm_send_message(event['channel'], response[:1000], thread_ts)
                    response = response[1000:]
            run_hook(server.hooks, 'loop', server)
            if loops_without_activity > 5:
                server.slack.ping()
                loops_without_activity = 0
            end = time.time()
            runtime = start - end
            time.sleep(max(1 - runtime, 0))
            if test_loop:
                test_loop -= 1
    except KeyboardInterrupt:
        if os.environ.get('LIMBO_DEBUG'):
            import ipdb
            ipdb.set_trace()
        raise

def dig(obj, *keys):
    """Return obj[key_1][key_2][...] for each key in keys, or None if any key
    in the chain is not found

    So, given this `obj`:

    {
        "banana": {
            "cream": "pie"
        }
    }

    dig(obj, "banana") -> {"cream": "pie"}
    dig(obj, "banana", "cream") -> "pie"
    dig(obj, "banana", "rama") -> None
    dig(obj, "Led", "Zeppelin") -> None"""
    for key in keys:
        if not obj or key not in obj:
            return None
        obj = obj[key]
    return obj

