        data.append((c.contracted_hours(), c.hours_worked, pt_label))
        chart_max = max([max(x[0], x[1]) for x in data[1:]])
    return render(request, 'timepiece/reports/estimation_accuracy.html', {'data': json.dumps(data, cls=DecimalEncoder), 'chart_max': chart_max})

def add_parameters(url, parameters):
    """Appends URL-encoded parameters to the base URL. It appends after '&' if
    '?' is found in the URL; otherwise it appends using '?'. Keep in mind that
    this tag does not take into account the value of existing params; it is
    therefore possible to add another value for a pre-existing parameter.

    For example::

        {% url 'this_view' as current_url %}
        {% with complete_url=current_url|add_parameters:request.GET %}
            The <a href="{% url 'other' %}?next={{ complete_url|urlencode }}">
            other page</a> will redirect back to the current page (including
            any GET parameters).
        {% endwith %}"""
    if parameters:
        sep = '&' if '?' in url else '?'
        return '{0}{1}{2}'.format(url, sep, urlencode(parameters))
    return url

def get_max_hours(context):
    """Return the largest number of hours worked or assigned on any project."""
    progress = context['project_progress']
    return max([0] + [max(p['worked'], p['assigned']) for p in progress])

def get_uninvoiced_hours(entries, billable=None):
    """Given an iterable of entries, return the total hours that have
    not been invoiced. If billable is passed as 'billable' or 'nonbillable',
    limit to the corresponding entries."""
    statuses = ('invoiced', 'not-invoiced')
    if billable is not None:
        billable = billable.lower() == u'billable'
        entries = [e for e in entries if e.activity.billable == billable]
    hours = sum([e.hours for e in entries if e.status not in statuses])
    return '{0:.2f}'.format(hours)

def humanize_hours(total_hours, frmt='{hours:02d}:{minutes:02d}:{seconds:02d}', negative_frmt=None):
    """Given time in hours, return a string representing the time."""
    seconds = int(float(total_hours) * 3600)
    return humanize_seconds(seconds, frmt, negative_frmt)

def humanize_seconds(total_seconds, frmt='{hours:02d}:{minutes:02d}:{seconds:02d}', negative_frmt=None):
    """Given time in int(seconds), return a string representing the time.

    If negative_frmt is not given, a negative sign is prepended to frmt
    and the result is wrapped in a <span> with the "negative-time" class."""
    if negative_frmt is None:
        negative_frmt = '<span class="negative-time">-{0}</span>'.format(frmt)
    seconds = abs(int(total_seconds))
    mapping = {'hours': seconds // 3600, 'minutes': seconds % 3600 // 60, 'seconds': seconds % 3600 % 60}
    if total_seconds < 0:
        result = negative_frmt.format(**mapping)
    else:
        result = frmt.format(**mapping)
    return mark_safe(result)

def _timesheet_url(url_name, pk, date=None):
    """Utility to create a time sheet URL with optional date parameters."""
    url = reverse(url_name, args=(pk,))
    if date:
        params = {'month': date.month, 'year': date.year}
        return '?'.join((url, urlencode(params)))
    return url

def reject_user_timesheet(request, user_id):
    """This allows admins to reject all entries, instead of just one"""
    form = YearMonthForm(request.GET or request.POST)
    user = User.objects.get(pk=user_id)
    if form.is_valid():
        from_date, to_date = form.save()
        entries = Entry.no_join.filter(status=Entry.VERIFIED, user=user, start_time__gte=from_date, end_time__lte=to_date)
        if request.POST.get('yes'):
            if entries.exists():
                count = entries.count()
                Entry.no_join.filter(pk__in=entries).update(status=Entry.UNVERIFIED)
                msg = 'You have rejected %d previously verified entries.' % count
            else:
                msg = 'There are no verified entries to reject.'
            messages.info(request, msg)
        else:
            return render(request, 'timepiece/user/timesheet/reject.html', {'date': from_date, 'timesheet_user': user})
    else:
        msg = 'You must provide a month and year for entries to be rejected.'
        messages.error(request, msg)
    url = reverse('view_user_timesheet', args=(user_id,))
    return HttpResponseRedirect(url)

def _is_requirement(line):
    """Returns whether the line is a valid package requirement."""
    line = line.strip()
    return line and (not (line.startswith('-r') or line.startswith('#')))

def clock_in(request):
    """For clocking the user into a project."""
    user = request.user
    active_entry = utils.get_active_entry(user, select_for_update=True)
    initial = dict([(k, v) for k, v in request.GET.items()])
    data = request.POST or None
    form = ClockInForm(data, initial=initial, user=user, active=active_entry)
    if form.is_valid():
        entry = form.save()
        message = 'You have clocked into {0} on {1}.'.format(entry.activity.name, entry.project)
        messages.info(request, message)
        return HttpResponseRedirect(reverse('dashboard'))
    return render(request, 'timepiece/entry/clock_in.html', {'form': form, 'active': active_entry})

def reject_entry(request, entry_id):
    """Admins can reject an entry that has been verified or approved but not
    invoiced to set its status to 'unverified' for the user to fix."""
    return_url = request.GET.get('next', reverse('dashboard'))
    try:
        entry = Entry.no_join.get(pk=entry_id)
    except:
        message = 'No such log entry.'
        messages.error(request, message)
        return redirect(return_url)
    if entry.status == Entry.UNVERIFIED or entry.status == Entry.INVOICED:
        msg_text = 'This entry is unverified or is already invoiced.'
        messages.error(request, msg_text)
        return redirect(return_url)
    if request.POST.get('Yes'):
        entry.status = Entry.UNVERIFIED
        entry.save()
        msg_text = "The entry's status was set to unverified."
        messages.info(request, msg_text)
        return redirect(return_url)
    return render(request, 'timepiece/entry/reject.html', {'entry': entry, 'next': request.GET.get('next')})

def delete_entry(request, entry_id):
    """Give the user the ability to delete a log entry, with a confirmation
    beforehand.  If this method is invoked via a GET request, a form asking
    for a confirmation of intent will be presented to the user. If this method
    is invoked via a POST request, the entry will be deleted."""
    try:
        entry = Entry.no_join.get(pk=entry_id, user=request.user)
    except Entry.DoesNotExist:
        message = 'No such entry found.'
        messages.info(request, message)
        url = request.GET.get('next', reverse('dashboard'))
        return HttpResponseRedirect(url)
    if request.method == 'POST':
        key = request.POST.get('key', None)
        if key and key == entry.delete_key:
            entry.delete()
            message = 'Deleted {0} for {1}.'.format(entry.activity.name, entry.project)
            messages.info(request, message)
            url = request.GET.get('next', reverse('dashboard'))
            return HttpResponseRedirect(url)
        else:
            message = 'You are not authorized to delete this entry!'
            messages.error(request, message)
    return render(request, 'timepiece/entry/delete.html', {'entry': entry})

def date_totals(entries, by):
    """Yield a user's name and a dictionary of their hours"""
    date_dict = {}
    for date, date_entries in groupby(entries, lambda x: x['date']):
        if isinstance(date, datetime.datetime):
            date = date.date()
        d_entries = list(date_entries)
        if by == 'user':
            name = ' '.join((d_entries[0]['user__first_name'], d_entries[0]['user__last_name']))
        elif by == 'project':
            name = d_entries[0]['project__name']
        else:
            name = d_entries[0][by]
        pk = d_entries[0][by]
        hours = get_hours_summary(d_entries)
        date_dict[date] = hours
    return (name, pk, date_dict)

def get_project_totals(entries, date_headers, hour_type=None, overtime=False, total_column=False, by='user'):
    """Yield hour totals grouped by user and date. Optionally including overtime."""
    totals = [0 for date in date_headers]
    rows = []
    for thing, thing_entries in groupby(entries, lambda x: x[by]):
        name, thing_id, date_dict = date_totals(thing_entries, by)
        dates = []
        for index, day in enumerate(date_headers):
            if isinstance(day, datetime.datetime):
                day = day.date()
            if hour_type:
                total = date_dict.get(day, {}).get(hour_type, 0)
                dates.append(total)
            else:
                billable = date_dict.get(day, {}).get('billable', 0)
                nonbillable = date_dict.get(day, {}).get('non_billable', 0)
                total = billable + nonbillable
                dates.append({'day': day, 'billable': billable, 'nonbillable': nonbillable, 'total': total})
            totals[index] += total
        if total_column:
            dates.append(sum(dates))
        if overtime:
            dates.append(find_overtime(dates))
        dates = [date or '' for date in dates]
        rows.append((name, thing_id, dates))
    if total_column:
        totals.append(sum(totals))
    totals = [t or '' for t in totals]
    yield (rows, totals)

def sized_imap(func, iterable, strict=False):
    """Return an iterable whose elements are the result of applying the callable `func`
    to each element of `iterable`. If `iterable` has a `len()`, then the iterable returned
    by this function will have the same `len()`. Otherwise calling `len()` on the
    returned iterable will raise `TypeError`.

    :param func: The function to apply to each element of `iterable`.
    :param iterable: An iterable whose objects will be mapped.
    :param bool strict: If `True` and `iterable` does not support `len()`, raise an exception
        immediately instead of returning an iterable that does not support `len()`."""
    try:
        length = len(iterable)
    except TypeError:
        if strict:
            raise
        else:
            return imap(func, iterable)
    return SizedGenerator(lambda: imap(func, iterable), length=length)

def parse_bytes(field):
    """>>> parse_bytes('24B')
    24.0
    >>> parse_bytes('4MiB')
    4194304.0"""
    if field[-1] in 'bB':
        field = field[:-1]
    try:
        for i, prefix in enumerate('KMGTPEZ'):
            if field.endswith(prefix + 'i'):
                factor = 2 ** (10 * (i + 1))
                return float(field[:-2]) * factor
        return float(field)
    except ValueError:
        return None

def json2pb(pb, js, useFieldNumber=False):
    """convert JSON string to google.protobuf.descriptor instance"""
    for field in pb.DESCRIPTOR.fields:
        if useFieldNumber:
            key = field.number
        else:
            key = field.name
        if key not in js:
            continue
        if field.type == FD.TYPE_MESSAGE:
            pass
        elif field.type in _js2ftype:
            ftype = _js2ftype[field.type]
        else:
            raise ParseError("Field %s.%s of type '%d' is not supported" % (pb.__class__.__name__, field.name, field.type))
        value = js[key]
        if field.label == FD.LABEL_REPEATED:
            pb_value = getattr(pb, field.name, None)
            for v in value:
                if field.type == FD.TYPE_MESSAGE:
                    json2pb(pb_value.add(), v, useFieldNumber=useFieldNumber)
                else:
                    pb_value.append(ftype(v))
        elif field.type == FD.TYPE_MESSAGE:
            json2pb(getattr(pb, field.name, None), value, useFieldNumber=useFieldNumber)
        else:
            setattr(pb, field.name, ftype(value))
    return pb

def pb2json(pb, useFieldNumber=False):
    """convert google.protobuf.descriptor instance to JSON string"""
    js = {}
    fields = pb.ListFields()
    for field, value in fields:
        if useFieldNumber:
            key = field.number
        else:
            key = field.name
        if field.type == FD.TYPE_MESSAGE:
            ftype = partial(pb2json, useFieldNumber=useFieldNumber)
        elif field.type in _ftype2js:
            ftype = _ftype2js[field.type]
        else:
            raise ParseError("Field %s.%s of type '%d' is not supported" % (pb.__class__.__name__, field.name, field.type))
        if field.label == FD.LABEL_REPEATED:
            js_value = []
            for v in value:
                js_value.append(ftype(v))
        else:
            js_value = ftype(value)
        js[key] = js_value
    return js

def modified_ngram_precision(references, pred, n):
    """Borrowed from the ntlk BLEU implementation:
    http://www.nltk.org/_modules/nltk/translate/bleu_score.html

    >>> modified_ngram_precision([['the', 'fat', 'cat', 'the', 'rat']],
    ...                          ['the', 'the', 'the', 'the', 'the'], 1)
    (2, 5)
    >>> modified_ngram_precision([['the', 'fat', 'cat', 'the', 'rat']],
    ...                          ['the', 'fat', 'the', 'rat'], 2)
    (2, 3)"""
    counts = Counter(iter_ngrams(pred, n))
    max_counts = {}
    for reference in references:
        reference_counts = Counter(iter_ngrams(reference, n))
        for ngram in counts:
            max_counts[ngram] = max(max_counts.get(ngram, 0), reference_counts[ngram])
    clipped_counts = {ngram: min(count, max_counts[ngram]) for ngram, count in counts.items()}
    numerator = sum(clipped_counts.values())
    denominator = sum(counts.values())
    return (numerator, denominator)

def unescape_sql(inp):
    """:param inp: an input string to be unescaped
    :return: return the unescaped version of the string."""
    if inp.startswith('"') and inp.endswith('"'):
        inp = inp[1:-1]
    return inp.replace('""', '"').replace('\\\\', '\\')

def parse_psql_array(inp):
    """:param inp: a string encoding an array
    :return: the array of elements as represented by the input"""
    inp = unescape_sql(inp)
    if inp.startswith('{') and inp.endswith('}'):
        inp = inp[1:-1]
    lst = []
    elem = ''
    in_quotes, escaped = (False, False)
    for ch in inp:
        if escaped:
            elem += ch
            escaped = False
        elif ch == '"':
            in_quotes = not in_quotes
            escaped = False
        elif ch == '\\':
            escaped = True
        else:
            if in_quotes:
                elem += ch
            elif ch == ',':
                lst.append(elem)
                elem = ''
            else:
                elem += ch
            escaped = False
    if len(elem) > 0:
        lst.append(elem)
    return lst

def mkdirp(dirname, overwrite=True):
    """Create a directory at the path given by `dirname`, if it doesn't
    already exist. If `overwrite` is False, raise an error when trying
    to create a directory that already has a config.json file in it.
    Otherwise do nothing if the directory already exists. (Note that an
    existing directory without a config.json will not raise an error
    regardless.)

    http://stackoverflow.com/a/14364249/4481448"""
    try:
        os.makedirs(dirname)
    except OSError:
        if not os.path.isdir(dirname):
            raise
        config_path = os.path.join(dirname, 'config.json')
        if not overwrite and os.path.lexists(config_path):
            raise OverwriteError('%s exists and already contains a config.json. To allow overwriting, pass the -O/--overwrite option.' % dirname)

def GitHub_post(data, url, *, auth, headers):
    """POST the data ``data`` to GitHub.

    Returns the json response from the server, or raises on error status."""
    r = requests.post(url, auth=auth, headers=headers, data=json.dumps(data))
    GitHub_raise_for_status(r)
    return r.json()

def generate_GitHub_token(*, note='Doctr token for pushing to gh-pages from Travis', scopes=None, **login_kwargs):
    """Generate a GitHub token for pushing from Travis

    The scope requested is public_repo.

    If no password or OTP are provided, they will be requested from the
    command line.

    The token created here can be revoked at
    https://github.com/settings/tokens."""
    if scopes is None:
        scopes = ['public_repo']
    AUTH_URL = 'https://api.github.com/authorizations'
    data = {'scopes': scopes, 'note': note, 'note_url': 'https://github.com/drdoctr/doctr', 'fingerprint': str(uuid.uuid4())}
    return GitHub_post(data, AUTH_URL, **login_kwargs)

def upload_GitHub_deploy_key(deploy_repo, ssh_key, *, read_only=False, title='Doctr deploy key for pushing to gh-pages from Travis', **login_kwargs):
    """Uploads a GitHub deploy key to ``deploy_repo``.

    If ``read_only=True``, the deploy_key will not be able to write to the
    repo."""
    DEPLOY_KEY_URL = 'https://api.github.com/repos/{deploy_repo}/keys'.format(deploy_repo=deploy_repo)
    data = {'title': title, 'key': ssh_key, 'read_only': read_only}
    return GitHub_post(data, DEPLOY_KEY_URL, **login_kwargs)

def guess_github_repo():
    """Guesses the github repo for the current directory

    Returns False if no guess can be made."""
    p = subprocess.run(['git', 'ls-remote', '--get-url', 'origin'], stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=False)
    if p.stderr or p.returncode:
        return False
    url = p.stdout.decode('utf-8').strip()
    m = GIT_URL.fullmatch(url)
    if not m:
        return False
    return m.group(1)

def get_config():
    """This load some configuration from the ``.travis.yml``, if file is present,
    ``doctr`` key if present."""
    p = Path('.travis.yml')
    if not p.exists():
        return {}
    with p.open() as f:
        travis_config = yaml.safe_load(f.read())
    config = travis_config.get('doctr', {})
    if not isinstance(config, dict):
        raise ValueError('config is not a dict: {}'.format(config))
    return config

def get_travis_branch():
    """Get the name of the branch that the PR is from.

    Note that this is not simply ``$TRAVIS_BRANCH``. the ``push`` build will
    use the correct branch (the branch that the PR is from) but the ``pr``
    build will use the _target_ of the PR (usually master). So instead, we ask
    for ``$TRAVIS_PULL_REQUEST_BRANCH`` if it's a PR build, and
    ``$TRAVIS_BRANCH`` if it's a push build."""
    if os.environ.get('TRAVIS_PULL_REQUEST', '') == 'true':
        return os.environ.get('TRAVIS_PULL_REQUEST_BRANCH', '')
    else:
        return os.environ.get('TRAVIS_BRANCH', '')

def set_git_user_email():
    """Set global user and email for git user if not already present on system"""
    username = subprocess.run(shlex.split('git config user.name'), stdout=subprocess.PIPE).stdout.strip().decode('utf-8')
    if not username or username == 'Travis CI User':
        run(['git', 'config', '--global', 'user.name', 'Doctr (Travis CI)'])
    else:
        print("Not setting git user name, as it's already set to %r" % username)
    email = subprocess.run(shlex.split('git config user.email'), stdout=subprocess.PIPE).stdout.strip().decode('utf-8')
    if not email or email == 'travis@example.org':
        run(['git', 'config', '--global', 'user.email', 'drdoctr@users.noreply.github.com'])
    else:
        print("Not setting git user email, as it's already set to %r" % email)

def determine_push_rights(*, branch_whitelist, TRAVIS_BRANCH, TRAVIS_PULL_REQUEST, TRAVIS_TAG, build_tags, fork):
    """Check if Travis is running on ``master`` (or a whitelisted branch) to
    determine if we can/should push the docs to the deploy repo"""
    canpush = True
    if TRAVIS_TAG:
        if not build_tags:
            print('The docs are not pushed on tag builds. To push on future tag builds, use --build-tags')
        return build_tags
    if not any([re.compile(x).match(TRAVIS_BRANCH) for x in branch_whitelist]):
        print('The docs are only pushed to gh-pages from master. To allow pushing from a non-master branch, use the --no-require-master flag', file=sys.stderr)
        print('This is the {TRAVIS_BRANCH} branch'.format(TRAVIS_BRANCH=TRAVIS_BRANCH), file=sys.stderr)
        canpush = False
    if TRAVIS_PULL_REQUEST != 'false':
        print('The website and docs are not pushed to gh-pages on pull requests', file=sys.stderr)
        canpush = False
    if fork:
        print('The website and docs are not pushed to gh-pages on fork builds.', file=sys.stderr)
        canpush = False
    if last_commit_by_doctr():
        print(red('The last commit on this branch was pushed by doctr. Not pushing to avoid an infinite build-loop.'), file=sys.stderr)
        canpush = False
    return canpush

def guess_organization():
    """Guess the organization from `git config`. If that can't be found,
    fall back to $USER environment variable."""
    try:
        stdout = subprocess.check_output('git config --get user.name'.split())
        org = stdout.strip().decode('UTF-8')
    except:
        org = getpass.getuser()
        if sys.version_info[0] == 2:
            org = org.decode('UTF-8')
    return org

def load_file_template(path):
    """Load template from the specified filesystem path.
    """
    template = StringIO()
    if not os.path.exists(path):
        raise ValueError('path does not exist: %s' % path)
    with open(clean_path(path), 'rb') as infile:
        for line in infile:
            template.write(line.decode('utf-8'))
    return template

def extract_vars(template):
    """Extract variables from template. Variables are enclosed in
    double curly braces."""
    keys = set()
    for match in re.finditer('\\{\\{ (?P<key>\\w+) \\}\\}', template.getvalue()):
        keys.add(match.groups()[0])
    return sorted(list(keys))

def get_suffix(name):
    """Check if file name have valid suffix for formatting.
    if have suffix return it else return False."""
    a = name.count('.')
    if a:
        ext = name.split('.')[-1]
        if ext in LANGS.keys():
            return ext
        return False
    else:
        return False

def get_tgt_for(user):
    """Fetch a ticket granting ticket for a given user.

    :param user: UserObj

    :return: TGT or Exepction"""
    if not settings.CAS_PROXY_CALLBACK:
        raise CasConfigException('No proxy callback set in settings')
    try:
        return Tgt.objects.get(username=user.username)
    except ObjectDoesNotExist:
        logger.warning('No ticket found for user {user}'.format(user=user.username))
        raise CasTicketException('no ticket found for user ' + user.username)

def _verify_cas1(ticket, service):
    """Verifies CAS 1.0 authentication ticket.

    :param: ticket
    :param: service

    Returns username on success and None on failure."""
    params = {'ticket': ticket, 'service': service}
    url = urljoin(settings.CAS_SERVER_URL, 'validate') + '?' + urlencode(params)
    page = urlopen(url)
    try:
        verified = page.readline().strip()
        if verified == 'yes':
            return page.readline().strip()
        else:
            return None
    finally:
        page.close()

def verify_proxy_ticket(ticket, service):
    """Verifies CAS 2.0+ XML-based proxy ticket.

    :param: ticket
    :param: service

    Returns username on success and None on failure."""
    params = {'ticket': ticket, 'service': service}
    url = urljoin(settings.CAS_SERVER_URL, 'proxyValidate') + '?' + urlencode(params)
    page = urlopen(url)
    try:
        response = page.read()
        tree = ElementTree.fromstring(response)
        if tree[0].tag.endswith('authenticationSuccess'):
            username = tree[0][0].text
            proxies = []
            if len(tree[0]) > 1:
                for element in tree[0][1]:
                    proxies.append(element.text)
            return {'username': username, 'proxies': proxies}
        else:
            return None
    finally:
        page.close()

def _get_pgtiou(pgt):
    """Returns a PgtIOU object given a pgt.

    The PgtIOU (tgt) is set by the CAS server in a different request
    that has completed before this call, however, it may not be found in
    the database by this calling thread, hence the attempt to get the
    ticket is retried for up to 5 seconds. This should be handled some
    better way.

    Users can opt out of this waiting period by setting CAS_PGT_FETCH_WAIT = False

    :param: pgt"""
    pgtIou = None
    retries_left = 5
    if not settings.CAS_PGT_FETCH_WAIT:
        retries_left = 1
    while not pgtIou and retries_left:
        try:
            return PgtIOU.objects.get(tgt=pgt)
        except PgtIOU.DoesNotExist:
            if settings.CAS_PGT_FETCH_WAIT:
                time.sleep(1)
            retries_left -= 1
            logger.info('Did not fetch ticket, trying again.  {tries} tries left.'.format(tries=retries_left))
    raise CasTicketException('Could not find pgtIou for pgt %s' % pgt)

def gateway():
    """Authenticates single sign on session if ticket is available,
    but doesn't redirect to sign in url otherwise."""
    if settings.CAS_GATEWAY == False:
        raise ImproperlyConfigured('CAS_GATEWAY must be set to True')
    def wrap(func):
        def wrapped_f(*args):
            from cas.views import login
            request = args[0]
            try:
                is_authenticated = request.user.is_authenticated()
            except TypeError:
                is_authenticated = request.user.is_authenticated
            if is_authenticated:
                pass
            else:
                path_with_params = request.path + '?' + urlencode(request.GET.copy())
                if request.GET.get('ticket'):
                    response = login(request, path_with_params, False, True)
                    if isinstance(response, HttpResponseRedirect):
                        return response
                else:
                    gatewayed = request.GET.get('gatewayed')
                    if gatewayed == 'true':
                        pass
                    else:
                        response = login(request, path_with_params, False, True)
                        if isinstance(response, HttpResponseRedirect):
                            return response
            return func(*args)
        return wrapped_f
    return wrap

def _service_url(request, redirect_to=None, gateway=False):
    """Generates application service URL for CAS

    :param: request Request Object
    :param: redirect_to URL to redriect to
    :param: gateway Should this be a gatewayed pass through"""
    if settings.CAS_FORCE_SSL_SERVICE_URL:
        protocol = 'https://'
    else:
        protocol = ('http://', 'https://')[request.is_secure()]
    host = request.get_host()
    service = protocol + host + request.path
    if redirect_to:
        if '?' in service:
            service += '&'
        else:
            service += '?'
        if gateway:
            ' If gateway, capture params and reencode them before returning a url '
            gateway_params = [(REDIRECT_FIELD_NAME, redirect_to), ('gatewayed', 'true')]
            query_dict = request.GET.copy()
            try:
                del query_dict['ticket']
            except:
                pass
            query_list = query_dict.items()
            for item in query_list:
                for index, item2 in enumerate(gateway_params):
                    if item[0] == item2[0]:
                        gateway_params.pop(index)
            extra_params = gateway_params + query_list
            sorted_params = sorted(extra_params, key=itemgetter(0))
            service += urlencode(sorted_params)
        else:
            service += urlencode({REDIRECT_FIELD_NAME: redirect_to})
    return service

def _redirect_url(request):
    """Redirects to referring page, or CAS_REDIRECT_URL if no referrer is
    set.

    :param: request RequestObj"""
    next = request.GET.get(REDIRECT_FIELD_NAME)
    if not next:
        if settings.CAS_IGNORE_REFERER:
            next = settings.CAS_REDIRECT_URL
        else:
            next = request.META.get('HTTP_REFERER', settings.CAS_REDIRECT_URL)
        host = request.get_host()
        prefix = ('http://', 'https://')[request.is_secure()] + host
        if next.startswith(prefix):
            next = next[len(prefix):]
    return next

def _login_url(service, ticket='ST', gateway=False):
    """Generates CAS login URL

    :param: service Service URL
    :param: ticket Ticket
    :param: gateway Gatewayed"""
    LOGINS = {'ST': 'login', 'PT': 'proxyValidate'}
    if gateway:
        params = {'service': service, 'gateway': 'true'}
    else:
        params = {'service': service}
    if settings.CAS_EXTRA_LOGIN_PARAMS:
        params.update(settings.CAS_EXTRA_LOGIN_PARAMS)
    if not ticket:
        ticket = 'ST'
    login_type = LOGINS.get(ticket[:2], 'login')
    return urlparse.urljoin(settings.CAS_SERVER_URL, login_type) + '?' + urlencode(params)

def logout(request, next_page=None):
    """Redirects to CAS logout page

    :param: request RequestObj
    :param: next_page Page to redirect to"""
    auth.logout(request)
    if not next_page:
        next_page = _redirect_url(request)
    if settings.CAS_LOGOUT_COMPLETELY:
        return HttpResponseRedirect(_logout_url(request, next_page))
    else:
        return HttpResponseRedirect(next_page)

def proxy_callback(request):
    """Handles CAS 2.0+ XML-based proxy callback call.
    Stores the proxy granting ticket in the database for
    future use.

    NB: Use created and set it in python in case database
    has issues with setting up the default timestamp value"""
    pgtIou = request.GET.get('pgtIou')
    tgt = request.GET.get('pgtId')
    if not (pgtIou and tgt):
        logger.info('No pgtIou or tgt found in request.GET')
        return HttpResponse('No pgtIOO', content_type='text/plain')
    try:
        PgtIOU.objects.create(tgt=tgt, pgtIou=pgtIou, created=datetime.datetime.now())
        request.session['pgt-TICKET'] = pgtIou
        return HttpResponse('PGT ticket is: {ticket}'.format(ticket=pgtIou), content_type='text/plain')
    except Exception as e:
        logger.warning('PGT storage failed. {message}'.format(message=e))
        return HttpResponse('PGT storage failed for {request}'.format(request=str(request.GET)), content_type='text/plain')

def objectify(func):
    """Converts the returned value from a models.Payload to
    a models.EventbriteObject. Used by the access methods
    of the client.Eventbrite object"""
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        try:
            payload = func(*args, **kwargs)
        except requests.exceptions.ConnectionError as e:
            raise InternetConnectionError(e)
        return EventbriteObject.create(payload)
    return wrapper

def is_valid_ip(ip_address):
    """Check Validity of an IP address"""
    valid = True
    try:
        socket.inet_aton(ip_address.strip())
    except:
        valid = False
    return valid

def get_ip_address_from_request(request):
    """Makes the best attempt to get the client's real IP or return the loopback"""
    PRIVATE_IPS_PREFIX = ('10.', '172.', '192.', '127.')
    ip_address = ''
    x_forwarded_for = request.META.get('HTTP_X_FORWARDED_FOR', '')
    if x_forwarded_for and ',' not in x_forwarded_for:
        if not x_forwarded_for.startswith(PRIVATE_IPS_PREFIX) and is_valid_ip(x_forwarded_for):
            ip_address = x_forwarded_for.strip()
    else:
        ips = [ip.strip() for ip in x_forwarded_for.split(',')]
        for ip in ips:
            if ip.startswith(PRIVATE_IPS_PREFIX):
                continue
            elif not is_valid_ip(ip):
                continue
            else:
                ip_address = ip
                break
    if not ip_address:
        x_real_ip = request.META.get('HTTP_X_REAL_IP', '')
        if x_real_ip:
            if not x_real_ip.startswith(PRIVATE_IPS_PREFIX) and is_valid_ip(x_real_ip):
                ip_address = x_real_ip.strip()
    if not ip_address:
        remote_addr = request.META.get('REMOTE_ADDR', '')
        if remote_addr:
            if not remote_addr.startswith(PRIVATE_IPS_PREFIX) and is_valid_ip(remote_addr):
                ip_address = remote_addr.strip()
            if remote_addr.startswith(PRIVATE_IPS_PREFIX) and is_valid_ip(remote_addr):
                ip_address = remote_addr.strip()
    if not ip_address:
        ip_address = '127.0.0.1'
    return ip_address

def get_settings(editor_override=None):
    """Utility function to retrieve settings.py values with defaults"""
    flavor = getattr(settings, 'DJANGO_WYSIWYG_FLAVOR', 'yui')
    if editor_override is not None:
        flavor = editor_override
    return {'DJANGO_WYSIWYG_MEDIA_URL': getattr(settings, 'DJANGO_WYSIWYG_MEDIA_URL', urljoin(settings.STATIC_URL, flavor) + '/'), 'DJANGO_WYSIWYG_FLAVOR': flavor}

def wysiwyg_setup(protocol='http', editor_override=None):
    """Create the <style> and <script> tags needed to initialize the rich text editor.

    Create a local django_wysiwyg/includes.html template if you don't want to use Yahoo's CDN"""
    ctx = {'protocol': protocol}
    ctx.update(get_settings(editor_override=editor_override))
    return render_to_string('django_wysiwyg/%s/includes.html' % ctx['DJANGO_WYSIWYG_FLAVOR'], ctx)

def wysiwyg_editor(field_id, editor_name=None, config=None, editor_override=None):
    """Turn the textarea #field_id into a rich editor. If you do not specify the
    JavaScript name of the editor, it will be derived from the field_id.

    If you don't specify the editor_name then you'll have a JavaScript object
    named "<field_id>_editor" in the global namespace. We give you control of
    this in case you have a complex JS ctxironment."""
    if not editor_name:
        editor_name = '%s_editor' % field_id
    ctx = {'field_id': field_id, 'editor_name': editor_name, 'config': config}
    ctx.update(get_settings(editor_override=editor_override))
    if editor_override is not None:
        ctx['DJANGO_WYSIWYG_FLAVOR'] = editor_override
    return render_to_string('django_wysiwyg/%s/editor_instance.html' % ctx['DJANGO_WYSIWYG_FLAVOR'], ctx)

def wysiwyg_static_url(appname, prefix, default_path):
    """Automatically use an prefix if a given application is installed.
    For example, if django-ckeditor is installed, use it's STATIC_URL/ckeditor folder to find the CKEditor distribution.
    When the application does not available, fallback to the default path.

    This is a function for the internal templates of *django-wysiwyg*."""
    if appname in settings.INSTALLED_APPS:
        return urljoin(settings.STATIC_URL, prefix)
    else:
        return default_path

