def get_tables_and_gsis():
    """Get a set of tables and gsis and their configuration keys

    :returns: set -- A set of tuples (table_name, table_conf_key)"""
    table_names = set()
    configured_tables = get_configured_tables()
    not_used_tables = set(configured_tables)
    for table_instance in list_tables():
        for key_name in configured_tables:
            try:
                if re.match(key_name, table_instance.table_name):
                    logger.debug('Table {0} match with config key {1}'.format(table_instance.table_name, key_name))
                    if table_instance.table_name in [x[0] for x in table_names]:
                        logger.warning('Table {0} matches more than one regexp in config, skipping this match: "{1}"'.format(table_instance.table_name, key_name))
                    else:
                        table_names.add((table_instance.table_name, key_name))
                        not_used_tables.discard(key_name)
                else:
                    logger.debug('Table {0} did not match with config key {1}'.format(table_instance.table_name, key_name))
            except re.error:
                logger.error('Invalid regular expression: "{0}"'.format(key_name))
                sys.exit(1)
    if not_used_tables:
        logger.warning('No tables matching the following configured tables found: {0}'.format(', '.join(not_used_tables)))
    return sorted(table_names)

def get_table(table_name):
    """Return the DynamoDB table

    :type table_name: str
    :param table_name: Name of the DynamoDB table
    :returns: boto.dynamodb.table.Table"""
    try:
        table = Table(table_name, connection=DYNAMODB_CONNECTION)
    except DynamoDBResponseError as error:
        dynamodb_error = error.body['__type'].rsplit('#', 1)[1]
        if dynamodb_error == 'ResourceNotFoundException':
            logger.error('{0} - Table {1} not found'.format(table_name, table_name))
        raise
    return table

def get_gsi_status(table_name, gsi_name):
    """Return the DynamoDB table

    :type table_name: str
    :param table_name: Name of the DynamoDB table
    :type gsi_name: str
    :param gsi_name: Name of the GSI
    :returns: str"""
    try:
        desc = DYNAMODB_CONNECTION.describe_table(table_name)
    except JSONResponseError:
        raise
    for gsi in desc[u'Table'][u'GlobalSecondaryIndexes']:
        if gsi[u'IndexName'] == gsi_name:
            return gsi[u'IndexStatus']

def get_table_status(table_name):
    """Return the DynamoDB table

    :type table_name: str
    :param table_name: Name of the DynamoDB table
    :returns: str"""
    try:
        desc = DYNAMODB_CONNECTION.describe_table(table_name)
    except JSONResponseError:
        raise
    return desc[u'Table'][u'TableStatus']

def list_tables():
    """Return list of DynamoDB tables available from AWS

    :returns: list -- List of DynamoDB tables"""
    tables = []
    try:
        table_list = DYNAMODB_CONNECTION.list_tables()
        while True:
            for table_name in table_list[u'TableNames']:
                tables.append(get_table(table_name))
            if u'LastEvaluatedTableName' in table_list:
                table_list = DYNAMODB_CONNECTION.list_tables(table_list[u'LastEvaluatedTableName'])
            else:
                break
    except DynamoDBResponseError as error:
        dynamodb_error = error.body['__type'].rsplit('#', 1)[1]
        if dynamodb_error == 'ResourceNotFoundException':
            logger.error('No tables found')
        elif dynamodb_error == 'AccessDeniedException':
            logger.debug('Your AWS API keys lack access to listing tables. That is an issue if you are trying to use regular expressions in your table configuration.')
        elif dynamodb_error == 'UnrecognizedClientException':
            logger.error('Invalid security token. Are your AWS API keys correct?')
        else:
            logger.error('Unhandled exception: {0}: {1}. Please file a bug report at https://github.com/sebdah/dynamic-dynamodb/issues'.format(dynamodb_error, error.body['message']))
    except JSONResponseError as error:
        logger.error('Communication error: {0}'.format(error))
        sys.exit(1)
    return tables

def table_gsis(table_name):
    """Returns a list of GSIs for the given table

    :type table_name: str
    :param table_name: Name of the DynamoDB table
    :returns: list -- List of GSI names"""
    try:
        desc = DYNAMODB_CONNECTION.describe_table(table_name)[u'Table']
    except JSONResponseError:
        raise
    if u'GlobalSecondaryIndexes' in desc:
        return desc[u'GlobalSecondaryIndexes']
    return []

def __get_connection_dynamodb(retries=3):
    """Ensure connection to DynamoDB

    :type retries: int
    :param retries: Number of times to retry to connect to DynamoDB"""
    connected = False
    region = get_global_option('region')
    while not connected:
        if get_global_option('aws_access_key_id') and get_global_option('aws_secret_access_key'):
            logger.debug('Authenticating to DynamoDB using credentials in configuration file')
            connection = dynamodb2.connect_to_region(region, aws_access_key_id=get_global_option('aws_access_key_id'), aws_secret_access_key=get_global_option('aws_secret_access_key'))
        else:
            logger.debug("Authenticating using boto's authentication handler")
            connection = dynamodb2.connect_to_region(region)
        if not connection:
            if retries == 0:
                logger.error('Failed to connect to DynamoDB. Giving up.')
                raise
            else:
                logger.error('Failed to connect to DynamoDB. Retrying in 5 seconds')
                retries -= 1
                time.sleep(5)
        else:
            connected = True
            logger.debug('Connected to DynamoDB in {0}'.format(region))
    return connection

