def resolve(label):
    """composite mapping
    given f(x) and g(x)    here:  GLOBALTT & LOCALTT respectivly
    in order of preference
    return g(f(x))|f(x)|g(x) | x
    TODO consider returning x on fall through
    : return label's mapping"""
    term_id = label
    if label is not None and label in LOCALTT:
        term_id = LOCALTT[label]
        if term_id in GLOBALTT:
            term_id = GLOBALTT[term_id]
        else:
            LOG.warning('Local translation but do not have a global term_id for %s', label)
    elif label is not None and label in GLOBALTT:
        term_id = GLOBALTT[label]
    else:
        LOG.error('Do not have any mapping for label: ' + label)
    return term_id

def toRoman(num):
    """convert integer to Roman numeral"""
    if not 0 < num < 5000:
        raise ValueError('number %n out of range (must be 1..4999)', num)
    if int(num) != num:
        raise TypeError('decimals %n can not be converted', num)
    result = ''
    for numeral, integer in romanNumeralMap:
        while num >= integer:
            result += numeral
            num -= integer
    return result

def fromRoman(strng):
    """convert Roman numeral to integer"""
    if not strng:
        raise TypeError('Input can not be blank')
    if not romanNumeralPattern.search(strng):
        raise ValueError('Invalid Roman numeral: %s', strng)
    result = 0
    index = 0
    for numeral, integer in romanNumeralMap:
        while strng[index:index + len(numeral)] == numeral:
            result += integer
            index += len(numeral)
    return result

def getChrPartTypeByNotation(notation, graph=None):
    """This method will figure out the kind of feature that a given band
    is based on pattern matching to standard karyotype notation.
    (e.g. 13q22.2 ==> chromosome sub-band)

    This has been validated against human, mouse, fish, and rat nomenclature.
    :param notation: the band (without the chromosome prefix)
    :return:"""
    if re.match('p$', notation):
        rti = graph.globaltt['short_chromosome_arm']
    elif re.match('q$', notation):
        rti = graph.globaltt['long_chromosome_arm']
    elif re.match('[pq][A-H\\d]$', notation):
        rti = graph.globaltt['chromosome_region']
    elif re.match('[pq][A-H\\d]\\d', notation):
        rti = graph.globaltt['chromosome_band']
    elif re.match('[pq][A-H\\d]\\d\\.\\d+', notation):
        rti = graph.globaltt['chromosome_subband']
    else:
        rti = graph.globaltt['chromosome_part']
    return rti

def get_branch(db, root_hash, key):
    """Get a long-format Merkle branch"""
    validate_is_bytes(key)
