def transform_list_to_dict(list):
    """    Transforms a list into a dictionary, putting values as keys
    Args:
        id:
    Returns:
        dict: dictionary built"""
    ret = {}
    for value in list:
        if isinstance(value, dict):
            ret.update(value)
