def substitution_set(string, indexes):
    """for a string, return a set of all possible substitutions"""
    strlen = len(string)
    return {mutate_string(string, x) for x in indexes if valid_substitution(strlen, x)}

def valid_substitution(strlen, index):
    """skip performing substitutions that are outside the bounds of the string"""
    values = index[0]
    return all([strlen > i for i in values])

def acgt_match(string):
    '''returns True if sting consist of only "A "C" "G" "T"'''
    search = re.compile('[^ACGT]').search
    return not bool(search(string))

def stream_fastq(file_handler):
    """Generator which gives all four lines if a fastq read as one string
    """
    next_element = ''
    for i, line in enumerate(file_handler):
        next_element += line
        if i % 4 == 3:
            yield next_element
            next_element = ''

def read_fastq(filename):
    """return a stream of FASTQ entries, handling gzipped and empty files"""
    if not filename:
        return itertools.cycle((None,))
    if filename == '-':
        filename_fh = sys.stdin
    elif filename.endswith('gz'):
        if is_python3:
            filename_fh = gzip.open(filename, mode='rt')
        else:
            filename_fh = BufferedReader(gzip.open(filename, mode='rt'))
    else:
        filename_fh = open(filename)
    return stream_fastq(filename_fh)

def write_fastq(filename):
    """return a handle for FASTQ writing, handling gzipped files"""
    if filename:
        if filename.endswith('gz'):
            filename_fh = gzip.open(filename, mode='wb')
        else:
            filename_fh = open(filename, mode='w')
    else:
        filename_fh = None
    return filename_fh

def detect_alignment_annotations(queryalignment, tags=False):
    """detects the annotations present in a SAM file, inspecting either the
    tags or the query names and returns a set of annotations present"""
    annotations = set()
    for k, v in BARCODEINFO.items():
        if tags:
            if queryalignment.has_tag(v.bamtag):
                annotations.add(k)
        elif v.readprefix in queryalignment.qname:
            annotations.add(k)
    return annotations

def detect_fastq_annotations(fastq_file):
    """detects annotations preesent in a FASTQ file by examining the first read"""
    annotations = set()
    queryread = tz.first(read_fastq(fastq_file))
    for k, v in BARCODEINFO.items():
        if v.readprefix in queryread:
            annotations.add(k)
    return annotations

def construct_transformed_regex(annotations):
    """construct a regex that matches possible fields in a transformed file
    annotations is a set of which keys in BARCODEINFO are present in the file"""
    re_string = '.*'
    if 'cellular' in annotations:
        re_string += ':CELL_(?P<CB>.*)'
    if 'molecular' in annotations:
        re_string += ':UMI_(?P<MB>\\w*)'
    if 'sample' in annotations:
        re_string += ':SAMPLE_(?P<SB>\\w*)'
    if re_string == '.*':
        logger.error('No annotation present on this file, aborting.')
        sys.exit(1)
    return re_string

def cb_filter(fastq, bc1, bc2, bc3, cores, nedit):
    """Filters reads with non-matching barcodes
    Expects formatted fastq files."""
    with open_gzipsafe(bc1) as bc1_fh:
        bc1 = set((cb.strip() for cb in bc1_fh))
    if bc2:
        with open_gzipsafe(bc2) as bc2_fh:
            bc2 = set((cb.strip() for cb in bc2_fh))
    if bc3:
        with open_gzipsafe(bc3) as bc3_fh:
            bc3 = set((cb.strip() for cb in bc3_fh))
    annotations = detect_fastq_annotations(fastq)
    re_string = construct_transformed_regex(annotations)
    if nedit == 0:
        filter_cb = partial(exact_barcode_filter, bc1=bc1, bc2=bc2, bc3=bc3, re_string=re_string)
    else:
        bc1hash = MutationHash(bc1, nedit)
        bc2hash = None
        bc3hash = None
        if bc2:
            bc2hash = MutationHash(bc2, nedit)
        if bc3:
            bc3hash = MutationHash(bc3, nedit)
        filter_cb = partial(correcting_barcode_filter, bc1hash=bc1hash, bc2hash=bc2hash, bc3hash=bc3hash, re_string=re_string)
    p = multiprocessing.Pool(cores)
    chunks = tz.partition_all(10000, read_fastq(fastq))
    bigchunks = tz.partition_all(cores, chunks)
    for bigchunk in bigchunks:
        for chunk in p.map(filter_cb, list(bigchunk)):
            for read in chunk:
                sys.stdout.write(read)

def sb_filter(fastq, bc, cores, nedit):
    """Filters reads with non-matching sample barcodes
    Expects formatted fastq files."""
    barcodes = set((sb.strip() for sb in bc))
    if nedit == 0:
        filter_sb = partial(exact_sample_filter2, barcodes=barcodes)
    else:
        barcodehash = MutationHash(barcodes, nedit)
        filter_sb = partial(correcting_sample_filter2, barcodehash=barcodehash)
    p = multiprocessing.Pool(cores)
    chunks = tz.partition_all(10000, read_fastq(fastq))
    bigchunks = tz.partition_all(cores, chunks)
    for bigchunk in bigchunks:
        for chunk in p.map(filter_sb, list(bigchunk)):
            for read in chunk:
                sys.stdout.write(read)

def mb_filter(fastq, cores):
    """Filters umis with non-ACGT bases
    Expects formatted fastq files."""
    filter_mb = partial(umi_filter)
    p = multiprocessing.Pool(cores)
    chunks = tz.partition_all(10000, read_fastq(fastq))
    bigchunks = tz.partition_all(cores, chunks)
    for bigchunk in bigchunks:
        for chunk in p.map(filter_mb, list(bigchunk)):
            for read in chunk:
                sys.stdout.write(read)

def add_uid(fastq, cores):
    """Adds UID:[samplebc cellbc umi] to readname for umi-tools deduplication
    Expects formatted fastq files with correct sample and cell barcodes."""
    uids = partial(append_uids)
    p = multiprocessing.Pool(cores)
    chunks = tz.partition_all(10000, read_fastq(fastq))
    bigchunks = tz.partition_all(cores, chunks)
    for bigchunk in bigchunks:
        for chunk in p.map(uids, list(bigchunk)):
            for read in chunk:
                sys.stdout.write(read)

def array_type(data_types, field):
    """Allows conversion of Django ArrayField to SQLAlchemy Array.
    Takes care of mapping the type of the array element."""
    from sqlalchemy.dialects import postgresql
    internal_type = field.base_field.get_internal_type()
    if internal_type in data_types and internal_type != 'ArrayField':
        sub_type = data_types[internal_type](field)
        if not isinstance(sub_type, (list, tuple)):
            sub_type = [sub_type]
    else:
        raise RuntimeError('Unsupported array element type')
    return postgresql.ARRAY(sub_type)

def join_thread(thr):
    """Join a thread
    :type threading.Thread thr: thread to join"""
    if on_python2():
        while True:
            thr.join(timeout=1)
            if not thr.isAlive():
                break
    else:
        thr.join()

def datetime_from_timestamp(ts, tz=None, as_utc=False):
    """Convert a timestamp into datetime with offset
    :param float ts: timestamp
    :param dateutil.tz tz: time zone or local tz if not specified
    :param bool as_utc: convert datetime to UTC
    :rtype: datetime.datetime
    :return: converted timestamp to datetime"""
    if tz is None:
        tz = dateutil.tz.tzlocal()
    dt = datetime.datetime.fromtimestamp(ts, tz=tz)
    if as_utc:
        return dt.astimezone(tz=dateutil.tz.tzutc())
    else:
        return dt

def scantree(path):
    """Recursively scan a directory tree
    :param str path: path to scan
    :rtype: DirEntry
    :return: DirEntry via generator"""
    for entry in scandir(path):
        if entry.is_dir(follow_symlinks=True):
            for t in scantree(entry.path):
                yield t
        else:
            yield entry

def base64_encode_as_string(obj):
    """Encode object to base64
    :param any obj: object to encode
    :rtype: str
    :return: base64 encoded string"""
    if on_python2():
        return base64.b64encode(obj)
    else:
        return str(base64.b64encode(obj), 'ascii')

def page_align_content_length(length):
    """Compute page boundary alignment
    :param int length: content length
    :rtype: int
    :return: aligned byte boundary"""
    mod = length % _PAGEBLOB_BOUNDARY
    if mod != 0:
        return length + (_PAGEBLOB_BOUNDARY - mod)
    return length

def normalize_azure_path(path):
    """Normalize remote path (strip slashes and use forward slashes)
    :param str path: path to normalize
    :rtype: str
    :return: normalized path"""
    if is_none_or_empty(path):
        raise ValueError('provided path is invalid')
    _path = path.strip('/').strip('\\')
    return '/'.join(re.split('/|\\\\', _path))

def explode_azure_path(path):
    """Explodes an azure path into a container or fileshare and the
    remaining virtual path
    :param str path: path to explode
    :rtype: tuple
    :return: container, vpath"""
    rpath = normalize_azure_path(path).split('/')
    container = str(rpath[0])
    if len(rpath) > 1:
        rpath = '/'.join(rpath[1:])
    else:
        rpath = ''
    return (container, rpath)

def blob_is_snapshot(url):
    """Checks if the blob is a snapshot blob
    :param url str: blob url
    :rtype: bool
    :return: if blob is a snapshot blob"""
    if '?snapshot=' in url:
        try:
            dateutil.parser.parse(url.split('?snapshot=')[-1])
            return True
        except (ValueError, OverflowError):
            pass
    return False

def parse_blob_snapshot_parameter(url):
    """Retrieves the blob snapshot parameter from a url
    :param url str: blob url
    :rtype: str
    :return: snapshot parameter"""
    if blob_is_snapshot(url):
        tmp = url.split('?snapshot=')
        if len(tmp) == 2:
            return (tmp[0], tmp[1])
    return None

def parse_fileshare_or_file_snapshot_parameter(url):
    """Checks if the fileshare or file is a snapshot
    :param url str: file url
    :rtype: tuple
    :return: (url, snapshot)"""
    if is_not_empty(url):
        if '?sharesnapshot=' in url:
            try:
                tmp = url.split('?sharesnapshot=')
                if len(tmp) == 2:
                    dateutil.parser.parse(tmp[1])
                    return (tmp[0], tmp[1])
            except (ValueError, OverflowError):
                pass
        elif '?snapshot=' in url:
            try:
                tmp = url.split('?snapshot=')
                if len(tmp) == 2:
                    dateutil.parser.parse(tmp[1])
                    return (tmp[0], tmp[1])
            except (ValueError, OverflowError):
                pass
    return (url, None)

def compute_md5_for_file_asbase64(filename, pagealign=False, start=None, end=None, blocksize=65536):
    """Compute MD5 hash for file and encode as Base64
    :param str filename: file to compute MD5 for
    :param bool pagealign: page align data
    :param int start: file start offset
    :param int end: file end offset
    :param int blocksize: block size
    :rtype: str
    :return: MD5 for file encoded as Base64"""
    hasher = blobxfer.util.new_md5_hasher()
    with open(filename, 'rb') as filedesc:
        if start is not None:
            filedesc.seek(start)
            curr = start
        else:
            curr = 0
        while True:
            if end is not None and curr + blocksize > end:
                blocksize = end - curr
            if blocksize == 0:
                break
            buf = filedesc.read(blocksize)
            if not buf:
                break
            buflen = len(buf)
            if pagealign and buflen < blocksize:
                aligned = blobxfer.util.page_align_content_length(buflen)
                if aligned != buflen:
                    buf = buf.ljust(aligned, b'\x00')
            hasher.update(buf)
            curr += blocksize
        return blobxfer.util.base64_encode_as_string(hasher.digest())

def check_data_is_empty(data):
    """Check if data is empty via MD5
    :param bytes data: data to check
    :rtype: bool
    :return: if data is empty"""
    contentmd5 = compute_md5_for_data_asbase64(data)
    datalen = len(data)
    if datalen == _MAX_PAGE_SIZE_BYTES:
        if contentmd5 == _EMPTY_MAX_PAGE_SIZE_MD5:
            return True
    else:
        data_chk = b'\x00' * datalen
        if compute_md5_for_data_asbase64(data_chk) == contentmd5:
            return True
    return False

def parse_file_path(filepath):
    """Parse file path from file path
    :param str filepath: file path
    :rtype: tuple
    :return: (dirname, rest of path, snapshot)"""
    if not isinstance(filepath, pathlib.Path):
        filepath = pathlib.Path(filepath)
    dirname = '/'.join(filepath.parts[:len(filepath.parts) - 1])
    if len(dirname) == 0:
        dirname = None
    if len(filepath.parts) > 0:
        fname = filepath.parts[-1]
    else:
        fname = None
    fname, snapshot = blobxfer.util.parse_fileshare_or_file_snapshot_parameter(fname)
    return (dirname, fname, snapshot)

def get_file_properties(client, fileshare, prefix, timeout=None, snapshot=None):
    """Get file properties
    :param FileService client: blob client
    :param str fileshare: file share name
    :param str prefix: path prefix
    :param int timeout: timeout
    :param str snapshot: snapshot
    :rtype: azure.storage.file.models.File
    :return: file properties"""
    dirname, fname, ss = parse_file_path(prefix)
    if ss is not None:
        if snapshot is not None:
            raise RuntimeError('snapshot specified as {} but parsed {} from prefix {}'.format(snapshot, ss, prefix))
        else:
            snapshot = ss
    try:
        return client.get_file_properties(share_name=fileshare, directory_name=dirname, file_name=fname, timeout=timeout, snapshot=snapshot)
    except azure.common.AzureMissingResourceHttpError:
        return None

def check_if_single_file(client, fileshare, prefix, timeout=None):
    """Check if prefix is a single file or multiple files
    :param FileService client: blob client
    :param str fileshare: file share name
    :param str prefix: path prefix
    :param int timeout: timeout
    :rtype: tuple
    :return: (if prefix in fileshare is a single file, file)"""
    if blobxfer.util.is_none_or_empty(prefix):
        return (False, None)
    file = get_file_properties(client, fileshare, prefix, timeout)
    if file is None:
        return (False, file)
    else:
        return (True, file)

def create_share(ase, containers_created, timeout=None):
    """Create file share
    :param blobxfer.models.azure.StorageEntity ase: Azure StorageEntity
    :param dict containers_created: containers already created map
    :param int timeout: timeout"""
    if not ase.can_create_containers:
        return
    key = ase.client.account_name + ':file=' + ase.container
    if key in containers_created:
        return
    if ase.client.create_share(share_name=ase.container, fail_on_exist=False, timeout=timeout):
        logger.info('created file share {} on storage account {}'.format(ase.container, ase.client.account_name))
    containers_created.add(key)

def get_md5_from_metadata(ase):
    """Get MD5 from properties or metadata
    :param blobxfer.models.azure.StorageEntity ase: Azure Storage Entity
    :rtype: str or None
    :return: md5"""
    md5 = None
    if ase.is_encrypted:
        try:
            md5 = ase.encryption_metadata.blobxfer_extensions.pre_encrypted_content_md5
        except AttributeError:
            md5 = None
    if blobxfer.util.is_none_or_empty(md5):
