def vectored_io_from_metadata(md):
    """Convert vectored io metadata in json metadata
    :param dict md: metadata dictionary
    :rtype: VectoredStripe or None
    :return: vectored io metadata"""
    try:
        mdattr = json.loads(md[JSON_KEY_BLOBXFER_METADATA])[_JSON_KEY_VECTORED_IO]
    except (KeyError, TypeError):
        pass
    else:
        if mdattr[_JSON_KEY_VECTORED_IO_MODE] == _JSON_KEY_VECTORED_IO_STRIPE:
            mdstripe = mdattr[_JSON_KEY_VECTORED_IO_STRIPE]
            try:
                nextptr = explode_vectored_io_next_entry(mdstripe[_JSON_KEY_VECTORED_IO_STRIPE_NEXT])
            except (KeyError, AttributeError):
                nextptr = None
            vio = VectoredStripe(total_size=mdstripe[_JSON_KEY_VECTORED_IO_STRIPE_TOTAL_SIZE], offset_start=mdstripe[_JSON_KEY_VECTORED_IO_STRIPE_OFFSET_START], total_slices=mdstripe[_JSON_KEY_VECTORED_IO_STRIPE_TOTAL_SLICES], slice_id=mdstripe[_JSON_KEY_VECTORED_IO_STRIPE_SLICE_ID], next=nextptr)
            return vio
        else:
            raise RuntimeError('Cannot handle Vectored IO mode: {}'.format(mdattr[_JSON_KEY_VECTORED_IO_MODE]))
    return None

def aes_cbc_encrypt_data(symkey, iv, data, pad):
    """Encrypt data using AES CBC
    :param bytes symkey: symmetric key
    :param bytes iv: initialization vector
    :param bytes data: data to encrypt
    :param bool pad: pad data
    :rtype: bytes
    :return: encrypted data"""
    cipher = cryptography.hazmat.primitives.ciphers.Cipher(cryptography.hazmat.primitives.ciphers.algorithms.AES(symkey), cryptography.hazmat.primitives.ciphers.modes.CBC(iv), backend=cryptography.hazmat.backends.default_backend()).encryptor()
    if pad:
        return cipher.update(pkcs7_pad(data)) + cipher.finalize()
    else:
        return cipher.update(data) + cipher.finalize()

def get_idp_sso_supported_bindings(idp_entity_id=None, config=None):
