def verify_cb(conn, cert, errnum, depth, ok):
    """The default OpenSSL certificate verification callback."""
    if not ok:
        raise SecurityError('Could not verify CA certificate {0}'.format(cert.get_subject()))
    return ok

def is_retryable(err):
    """Determines if the given exception is something that is
    network/socket-related and should thus cause the TCP connection to
    close and the operation retried on another node.

    :rtype: boolean"""
    if isinstance(err, ConnectionClosed):
        if err.mid_stream:
            return False
        else:
            return True
    elif isinstance(err, socket.error):
        code = err.args[0]
        return code in CONN_CLOSED_ERRORS
    else:
        return False

def _validate_timeout(timeout, infinity_ok=False):
    """Raises an exception if the given timeout is an invalid value."""
    if timeout is None:
        return
    if timeout == 'infinity':
        if infinity_ok:
            return
        else:
            raise ValueError('timeout must be a positive integer ("infinity" is not valid)')
    if isinstance(timeout, six.integer_types) and timeout > 0:
        return
    raise ValueError('timeout must be a positive integer')

def content_property(name, doc=None):
    """Delegates a property to the first sibling in a RiakObject, raising
    an error when the object is in conflict."""
    def _setter(self, value):
        if len(self.siblings) == 0:
            self.siblings = [RiakContent(self)]
        if len(self.siblings) != 1:
            raise ConflictError()
        setattr(self.siblings[0], name, value)
    def _getter(self):
        if len(self.siblings) == 0:
            return
        if len(self.siblings) != 1:
            raise ConflictError()
        return getattr(self.siblings[0], name)
    return property(_getter, _setter, doc=doc)

def content_method(name):
    """Delegates a method to the first sibling in a RiakObject, raising
    an error when the object is in conflict."""
    def _delegate(self, *args, **kwargs):
        if len(self.siblings) != 1:
            raise ConflictError()
        return getattr(self.siblings[0], name).__call__(*args, **kwargs)
    _delegate.__doc__ = getattr(RiakContent, name).__doc__
    return _delegate

def retryable(fn, protocol=None):
    """Wraps a client operation that can be retried according to the set
    :attr:`RiakClient.retries`. Used internally."""
    def wrapper(self, *args, **kwargs):
        pool = self._choose_pool(protocol)
        def thunk(transport):
            return fn(self, transport, *args, **kwargs)
        return self._with_retries(pool, thunk)
    wrapper.__doc__ = fn.__doc__
    wrapper.__repr__ = fn.__repr__
    return wrapper

def default_encoder(obj):
    """Default encoder for JSON datatypes, which returns UTF-8 encoded
    json instead of the default bloated backslash u XXXX escaped ASCII strings."""
    if isinstance(obj, bytes):
        return json.dumps(bytes_to_str(obj), ensure_ascii=False).encode('utf-8')
    else:
        return json.dumps(obj, ensure_ascii=False).encode('utf-8')

def user_agent():
    """Return a User-Agent that identifies this client.

    Example:
        python-requests/2.9.1 edx-rest-api-client/1.7.2 ecommerce

    The last item in the list will be the application name, taken from the
    OS environment variable EDX_REST_API_CLIENT_NAME. If that environment
    variable is not set, it will default to the hostname."""
    client_name = 'unknown_client_name'
    try:
        client_name = os.environ.get('EDX_REST_API_CLIENT_NAME') or socket.gethostbyname(socket.gethostname())
    except:
        pass
    return '{} edx-rest-api-client/{} {}'.format(requests.utils.default_user_agent(), __version__, client_name)

def to_bedtool(iterator):
    """Convert any iterator into a pybedtools.BedTool object.

    Note that the supplied iterator is not consumed by this function. To save
    to a temp file or to a known location, use the `.saveas()` method of the
    returned BedTool object."""
    def gen():
        for i in iterator:
            yield helpers.asinterval(i)
    return pybedtools.BedTool(gen())

def clean_gff(gff, cleaned, add_chr=False, chroms_to_ignore=None, featuretypes_to_ignore=None):
    """Cleans a GFF file by removing features on unwanted chromosomes and of
    unwanted featuretypes.  Optionally adds "chr" to chrom names."""
    logger.info('Cleaning GFF')
    chroms_to_ignore = chroms_to_ignore or []
    featuretypes_to_ignore = featuretypes_to_ignore or []
    with open(cleaned, 'w') as fout:
        for i in gffutils.iterators.DataIterator(gff):
            if add_chr:
                i.chrom = 'chr' + i.chrom
            if i.chrom in chroms_to_ignore:
                continue
            if i.featuretype in featuretypes_to_ignore:
                continue
            fout.write(str(i) + '\n')
    return cleaned

