def _jsonify(x):
    """Use most compact form of JSON"""
    if isinstance(x, dict_class):
        return json.dumps(x._d, separators=(',', ':'))
    return json.dumps(x, separators=(',', ':'))

def _unjsonify(x, isattributes=False):
    """Convert JSON string to an ordered defaultdict."""
    if isattributes:
        obj = json.loads(x)
        return dict_class(obj)
    return json.loads(x)

def _feature_to_fields(f, jsonify=True):
    """Convert feature to tuple, for faster sqlite3 import"""
    x = []
    for k in constants._keys:
        v = getattr(f, k)
        if jsonify and k in ('attributes', 'extra'):
            x.append(_jsonify(v))
        else:
            x.append(v)
    return tuple(x)

def _dict_to_fields(d, jsonify=True):
    """Convert dict to tuple, for faster sqlite3 import"""
    x = []
    for k in constants._keys:
        v = d[k]
        if jsonify and k in ('attributes', 'extra'):
            x.append(_jsonify(v))
        else:
            x.append(v)
    return tuple(x)

def merge_attributes(attr1, attr2):
    """Merges two attribute dictionaries into a single dictionary.

    Parameters
    ----------
    `attr1`, `attr2` : dict

    Returns
    -------
    dict"""
    new_d = copy.deepcopy(attr1)
    new_d.update(attr2)
    for k, v in new_d.items():
        if not isinstance(v, list):
            new_d[k] = [v]
    for k, v in six.iteritems(attr1):
        if k in attr2:
            if not isinstance(v, list):
                v = [v]
            new_d[k].extend(v)
    return dict(((k, sorted(set(v))) for k, v in new_d.items()))

def dialect_compare(dialect1, dialect2):
    """Compares two dialects."""
    orig = set(dialect1.items())
    new = set(dialect2.items())
    return dict(added=dict(list(new.difference(orig))), removed=dict(list(orig.difference(new))))

def sanitize_gff_file(gff_fname, in_memory=True, in_place=False):
    """Sanitize a GFF file."""
    db = None
    if is_gff_db(gff_fname):
        db = gffutils.FeatureDB(gff_fname)
    elif in_memory:
        db = gffutils.create_db(gff_fname, ':memory:', verbose=False)
    else:
        db = get_gff_db(gff_fname)
    if in_place:
        gff_out = gffwriter.GFFWriter(gff_fname, in_place=in_place)
    else:
        gff_out = gffwriter.GFFWriter(sys.stdout)
    sanitized_db = sanitize_gff_db(db)
    for gene_rec in sanitized_db.all_features(featuretype='gene'):
        gff_out.write_gene_recs(sanitized_db, gene_rec.id)
    gff_out.close()

def is_gff_db(db_fname):
    """Return True if the given filename is a GFF database.

    For now, rely on .db extension."""
    if not os.path.isfile(db_fname):
        return False
    if db_fname.endswith('.db'):
        return True
    return False

def print_bin_sizes():
    """Useful for debugging: how large is each bin, and what are the bin IDs?"""
    for i, offset in enumerate(OFFSETS):
        binstart = offset
        try:
            binstop = OFFSETS[i + 1]
        except IndexError:
            binstop = binstart
        bin_size = 2 ** (FIRST_SHIFT + i * NEXT_SHIFT)
        actual_size = bin_size
        bin_size, suffix = (bin_size / 1024, 'Kb')
        if bin_size >= 1024:
            bin_size, suffix = (bin_size / 1024, 'Mb')
        if bin_size >= 1024:
            bin_size, suffix = (bin_size / 1024, 'Gb')
        size = '(%s %s)' % (bin_size, suffix)
        actual_size = '%s bp' % actual_size
        print('level: {i:1};  bins {binstart:<4} to {binstop:<4}; size: {actual_size:<12} {size:<6}'.format(**locals()))

def wait_for_js(function):
    """Method decorator that waits for JavaScript dependencies before executing `function`.
    If the function is not a method, the decorator has no effect.

    Args:
        function (callable): Method to decorate.

    Returns:
        Decorated method"""
    @functools.wraps(function)
    def wrapper(*args, **kwargs):
        if len(args) < 1:
            return function(*args, **kwargs)
        else:
            self = args[0]
            if hasattr(self, 'wait_for_js'):
                self.wait_for_js()
            return function(*args, **kwargs)
    return wrapper

def _decorator(store_name, store_values):
    """Return a class decorator that:

    1) Defines a new class method, `wait_for_js`
    2) Defines a new class list variable, `store_name` and adds
        `store_values` to the list."""
    def decorator(clz):
        if not hasattr(clz, 'wait_for_js'):
            setattr(clz, 'wait_for_js', _wait_for_js)
        if not hasattr(clz, store_name):
            setattr(clz, store_name, set())
        getattr(clz, store_name).update(store_values)
        return clz
    return decorator

def _are_js_vars_defined(browser, js_vars):
    """Return a boolean indicating whether all the JavaScript
    variables `js_vars` are defined on the current page.

    `browser` is a Selenium webdriver instance."""
    script = u' && '.join([u"!(typeof {0} === 'undefined')".format(var) for var in js_vars])
    try:
        return browser.execute_script(u'return {}'.format(script))
    except WebDriverException as exc:
        if 'is not defined' in exc.msg or 'is undefined' in exc.msg:
            return False
        else:
            raise

def _are_requirejs_deps_loaded(browser, deps):
    """Return a boolean indicating whether all the RequireJS
    dependencies `deps` have loaded on the current page.

    `browser` is a WebDriver instance."""
    script = dedent(u'
        // Retrieve the callback function used to return control to the test suite
        var callback = arguments[arguments.length - 1];

        // If RequireJS isn't defined, then return immediately
        if (!window.require) {{
            callback("RequireJS not defined");
        }}

        // Otherwise, install a RequireJS module that depends on the modules
        // we're waiting for.
        else {{

            // Catch errors reported by RequireJS
            requirejs.onError = callback;

            // Install our module
            require({deps}, function() {{
                callback('Success');
            }});
        }}
    ').format(deps=json.dumps(list(deps)))
    browser.set_script_timeout(30)
    try:
        result = browser.execute_async_script(script)
        return result == 'Success'
    except TimeoutException:
        return False

def pre_verify(method):
    """Decorator that calls self._verify_page() before executing the decorated method

    Args:
        method (callable): The method to decorate.

    Returns:
        Decorated method"""
    @wraps(method)
    def wrapper(self, *args, **kwargs):
        self._verify_page()
        return method(self, *args, **kwargs)
    return wrapper

def _remote_browser_class(env_vars, tags=None):
    """Returns class, kwargs, and args needed to instantiate the remote browser."""
    if tags is None:
        tags = []
    envs = _required_envs(env_vars)
    envs.update(_optional_envs())
    caps = _capabilities_dict(envs, tags)
    if 'accessKey' in caps:
        LOGGER.info(u'Using SauceLabs: %s %s %s', caps['platform'], caps['browserName'], caps['version'])
    else:
        LOGGER.info(u'Using Remote Browser: %s', caps['browserName'])
    url = u'http://{0}:{1}/wd/hub'.format(envs['SELENIUM_HOST'], envs['SELENIUM_PORT'])
    browser_args = []
    browser_kwargs = {'command_executor': url, 'desired_capabilities': caps}
    if caps['browserName'] == 'firefox':
        browser_kwargs['browser_profile'] = _firefox_profile()
    return (webdriver.Remote, browser_args, browser_kwargs)

def _proxy_kwargs(browser_name, proxy, browser_kwargs={}):
    """Determines the kwargs needed to set up a proxy based on the
    browser type.

    Returns: a dictionary of arguments needed to pass when
        instantiating the WebDriver instance."""
    proxy_dict = {'httpProxy': proxy.proxy, 'proxyType': 'manual'}
    if browser_name == 'firefox' and 'desired_capabilities' not in browser_kwargs:
        wd_proxy = webdriver.common.proxy.Proxy(proxy_dict)
        browser_kwargs['proxy'] = wd_proxy
    else:
        if 'desired_capabilities' not in browser_kwargs:
            browser_kwargs['desired_capabilities'] = {}
        browser_kwargs['desired_capabilities']['proxy'] = proxy_dict
    return browser_kwargs

def _required_envs(env_vars):
    """Parse environment variables for required values,
    raising a `BrowserConfig` error if they are not found.

    Returns a `dict` of environment variables."""
    envs = {key: os.environ.get(key) for key in env_vars}
    missing = [key for key, val in list(envs.items()) if val is None]
    if missing:
        msg = u'These environment variables must be set: ' + u', '.join(missing)
        raise BrowserConfigError(msg)
    if envs['SELENIUM_BROWSER'] not in BROWSERS:
        msg = u'Unsuppported browser: {0}'.format(envs['SELENIUM_BROWSER'])
        raise BrowserConfigError(msg)
    return envs

def _optional_envs():
    """Parse environment variables for optional values,
    raising a `BrowserConfig` error if they are insufficiently specified.

    Returns a `dict` of environment variables."""
    envs = {key: os.environ.get(key) for key in OPTIONAL_ENV_VARS if key in os.environ}
    if 'JOB_NAME' in envs and 'BUILD_NUMBER' not in envs:
        raise BrowserConfigError('Missing BUILD_NUMBER environment var')
    if 'BUILD_NUMBER' in envs and 'JOB_NAME' not in envs:
        raise BrowserConfigError('Missing JOB_NAME environment var')
    return envs

def _capabilities_dict(envs, tags):
    """Convert the dictionary of environment variables to
    a dictionary of desired capabilities to send to the
    Remote WebDriver.

    `tags` is a list of string tags to apply to the SauceLabs job."""
    capabilities = {'browserName': envs['SELENIUM_BROWSER'], 'acceptInsecureCerts': bool(envs.get('SELENIUM_INSECURE_CERTS', False)), 'video-upload-on-pass': False, 'sauce-advisor': False, 'capture-html': True, 'record-screenshots': True, 'max-duration': 600, 'public': 'public restricted', 'tags': tags}
    if _use_remote_browser(SAUCE_ENV_VARS):
        sauce_capabilities = {'platform': envs['SELENIUM_PLATFORM'], 'version': envs['SELENIUM_VERSION'], 'username': envs['SAUCE_USER_NAME'], 'accessKey': envs['SAUCE_API_KEY']}
        capabilities.update(sauce_capabilities)
    if 'JOB_NAME' in envs:
        jenkins_vars = {'build': envs['BUILD_NUMBER'], 'name': envs['JOB_NAME']}
        capabilities.update(jenkins_vars)
    return capabilities

def prepare_headers(table, bound_columns):
    """:type bound_columns: list of BoundColumn"""
    if table.request is None:
        return
    for column in bound_columns:
        if column.sortable:
            params = table.request.GET.copy()
            param_path = _with_path_prefix(table, 'order')
            order = table.request.GET.get(param_path, None)
            start_sort_desc = column.sort_default_desc
            params[param_path] = column.name if not start_sort_desc else '-' + column.name
            column.is_sorting = False
            if order is not None:
                is_desc = order.startswith('-')
                order_field = order if not is_desc else order[1:]
                if order_field == column.name:
                    new_order = order_field if is_desc else '-' + order_field
                    params[param_path] = new_order
                    column.sort_direction = DESCENDING if is_desc else ASCENDING
                    column.is_sorting = True
            column.url = '?' + params.urlencode()
        else:
            column.is_sorting = False

def default_cell_formatter(table, column, row, value, **_):
    """:type column: tri.table.Column"""
    formatter = _cell_formatters.get(type(value))
    if formatter:
        value = formatter(table=table, column=column, row=row, value=value)
    if value is None:
        return ''
    return conditional_escape(value)

