def _validate_image_orientation(image_orientation):
    """Ensure that the image orientation is supported
    - The direction cosines have magnitudes of 1 (just in case)
    - The direction cosines are perpendicular"""
    row_cosine, column_cosine, slice_cosine = _extract_cosines(image_orientation)
    if not _almost_zero(np.dot(row_cosine, column_cosine), 0.0001):
        raise DicomImportException('Non-orthogonal direction cosines: {}, {}'.format(row_cosine, column_cosine))
    elif not _almost_zero(np.dot(row_cosine, column_cosine), 1e-08):
        logger.warning("Direction cosines aren't quite orthogonal: {}, {}".format(row_cosine, column_cosine))
    if not _almost_one(np.linalg.norm(row_cosine), 0.0001):
        raise DicomImportException("The row direction cosine's magnitude is not 1: {}".format(row_cosine))
    elif not _almost_one(np.linalg.norm(row_cosine), 1e-08):
        logger.warning("The row direction cosine's magnitude is not quite 1: {}".format(row_cosine))
    if not _almost_one(np.linalg.norm(column_cosine), 0.0001):
        raise DicomImportException("The column direction cosine's magnitude is not 1: {}".format(column_cosine))
    elif not _almost_one(np.linalg.norm(column_cosine), 1e-08):
        logger.warning("The column direction cosine's magnitude is not quite 1: {}".format(column_cosine))

def handle_cd_command(arg):
    """Handles a `cd` shell command by calling python's os.chdir."""
    CD_CMD = 'cd'
    tokens = arg.split(CD_CMD + ' ')
    directory = tokens[-1] if len(tokens) > 1 else None
    if not directory:
        return (False, 'No folder name was provided.')
    try:
        os.chdir(directory)
        subprocess.call(['pwd'])
        return (True, None)
    except OSError as e:
        return (False, e.strerror)

def open_external_editor(filename=None, sql=None):
    """Open external editor, wait for the user to type in their query, return
    the query.
    :return: list with one tuple, query as first element."""
    message = None
    filename = filename.strip().split(' ', 1)[0] if filename else None
    sql = sql or ''
    MARKER = '# Type your query above this line.\n'
    query = click.edit(u'{sql}\n\n{marker}'.format(sql=sql, marker=MARKER), filename=filename, extension='.sql')
    if filename:
        try:
            with open(filename, encoding='utf-8') as f:
                query = f.read()
        except IOError:
            message = 'Error reading file: %s.' % filename
    if query is not None:
        query = query.split(MARKER, 1)[0].rstrip('\n')
    else:
        query = sql
    return (query, message)

def execute_favorite_query(cur, arg, **_):
    """Returns (title, rows, headers, status)"""
    if arg == '':
        for result in list_favorite_queries():
            yield result
    'Parse out favorite name and optional substitution parameters'
    name, _, arg_str = arg.partition(' ')
    args = shlex.split(arg_str)
    query = favoritequeries.get(name)
    if query is None:
        message = 'No favorite query: %s' % name
        yield (None, None, None, message)
    else:
        query, arg_error = subst_favorite_query_args(query, args)
        if arg_error:
            yield (None, None, None, arg_error)
        else:
            for sql in sqlparse.split(query):
                _logger.debug('query is [%s]', sql)
                sql = sql.rstrip(';')
                title = '> %s' % sql
                cur.execute(sql)
                if cur.description:
                    headers = [x[0] for x in cur.description]
                    yield (title, cur.fetchall(), headers, None)
                else:
                    yield (title, None, None, None)

def list_favorite_queries():
    """List of all favorite queries.
    Returns (title, rows, headers, status)"""
    headers = ['Name', 'Query']
    rows = [(r, favoritequeries.get(r)) for r in favoritequeries.list()]
    if not rows:
        status = '\nNo favorite queries found.' + favoritequeries.usage
    else:
        status = ''
    return [('', rows, headers, status)]

def subst_favorite_query_args(query, args):
    """replace positional parameters ($1...$N) in query."""
    for idx, val in enumerate(args):
        subst_var = '$' + str(idx + 1)
        if subst_var not in query:
            return [None, 'query does not have substitution parameter ' + subst_var + ':\n  ' + query]
        query = query.replace(subst_var, val)
    match = re.search('\\$\\d+', query)
    if match:
        return [None, 'missing substitution for ' + match.group(0) + ' in query:\n  ' + query]
    return [query, None]

def execute_system_command(arg, **_):
    """Execute a system shell command."""
    usage = 'Syntax: system [command].\n'
    if not arg:
        return [(None, None, None, usage)]
    try:
        command = arg.strip()
        if command.startswith('cd'):
            ok, error_message = handle_cd_command(arg)
            if not ok:
                return [(None, None, None, error_message)]
            return [(None, None, None, '')]
        args = arg.split(' ')
        process = subprocess.Popen(args, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        output, error = process.communicate()
        response = output if not error else error
        if isinstance(response, bytes):
            encoding = locale.getpreferredencoding(False)
            response = response.decode(encoding)
        return [(None, None, None, response)]
    except OSError as e:
        return [(None, None, None, 'OSError: %s' % e.strerror)]

def need_completion_refresh(queries):
    """Determines if the completion needs a refresh by checking if the sql
    statement is an alter, create, drop or change db."""
    tokens = {'use', '\\u', 'create', 'drop'}
    for query in sqlparse.split(queries):
        try:
            first_token = query.split()[0]
            if first_token.lower() in tokens:
                return True
        except Exception:
            return False

def is_mutating(status):
    """Determines if the statement is mutating based on the status."""
    if not status:
        return False
    mutating = set(['insert', 'update', 'delete', 'alter', 'create', 'drop', 'replace', 'truncate', 'load'])
    return status.split(None, 1)[0].lower() in mutating

def list_path(root_dir):
    """List directory if exists.
    :param dir: str
    :return: list"""
    res = []
    if os.path.isdir(root_dir):
        for name in os.listdir(root_dir):
            res.append(name)
    return res

def complete_path(curr_dir, last_dir):
    """Return the path to complete that matches the last entered component.
    If the last entered component is ~, expanded path would not
    match, so return all of the available paths.
    :param curr_dir: str
    :param last_dir: str
    :return: str"""
    if not last_dir or curr_dir.startswith(last_dir):
        return curr_dir
    elif last_dir == '~':
        return os.path.join(last_dir, curr_dir)

def parse_path(root_dir):
    """Split path into head and last component for the completer.
    Also return position where last component starts.
    :param root_dir: str path
    :return: tuple of (string, string, int)"""
    base_dir, last_dir, position = ('', '', 0)
    if root_dir:
        base_dir, last_dir = os.path.split(root_dir)
        position = -len(last_dir) if last_dir else 0
    return (base_dir, last_dir, position)

def suggest_path(root_dir):
    """List all files and subdirectories in a directory.
    If the directory is not specified, suggest root directory,
    user directory, current and parent directory.
    :param root_dir: string: directory to list
    :return: list"""
    if not root_dir:
        return [os.path.abspath(os.sep), '~', os.curdir, os.pardir]
    if '~' in root_dir:
        root_dir = os.path.expanduser(root_dir)
    if not os.path.exists(root_dir):
        root_dir, _ = os.path.split(root_dir)
    return list_path(root_dir)

def log(logger, level, message):
    """Logs message to stderr if logging isn't initialized."""
    if logger.parent.name != 'root':
        logger.log(level, message)
    else:
        print(message, file=sys.stderr)

def read_config_file(f):
    """Read a config file."""
    if isinstance(f, basestring):
        f = os.path.expanduser(f)
    try:
        config = ConfigObj(f, interpolation=False, encoding='utf8')
    except ConfigObjError as e:
        log(LOGGER, logging.ERROR, "Unable to parse line {0} of config file '{1}'.".format(e.line_number, f))
        log(LOGGER, logging.ERROR, 'Using successfully parsed config values.')
        return e.config
    except (IOError, OSError) as e:
        log(LOGGER, logging.WARNING, "You don't have permission to read config file '{0}'.".format(e.filename))
        return None
    return config

def read_config_files(files):
    """Read and merge a list of config files."""
    config = ConfigObj()
    for _file in files:
        _config = read_config_file(_file)
        if bool(_config) is True:
            config.merge(_config)
            config.filename = _config.filename
    return config

def confirm_destructive_query(queries):
    """Check if the query is destructive and prompts the user to confirm.
    Returns:
    * None if the query is non-destructive or we can't prompt the user.
    * True if the query is destructive and the user wants to proceed.
    * False if the query is destructive and the user doesn't want to proceed."""
    prompt_text = "You're about to run a destructive command.\nDo you want to proceed? (y/n)"
    if is_destructive(queries) and sys.stdin.isatty():
        return prompt(prompt_text, type=bool)

def confirm(*args, **kwargs):
    """Prompt for confirmation (yes/no) and handle any abort exceptions."""
    try:
        return click.confirm(*args, **kwargs)
    except click.Abort:
        return False

def prompt(*args, **kwargs):
    """Prompt the user for input and handle any abort exceptions."""
    try:
        return click.prompt(*args, **kwargs)
    except click.Abort:
        return False

def style_factory(name, cli_style):
    """Create a Pygments Style class based on the user's preferences.
    :param str name: The name of a built-in Pygments style.
    :param dict cli_style: The user's token-type style preferences."""
    try:
        style = pygments.styles.get_style_by_name(name)
    except ClassNotFound:
        style = pygments.styles.get_style_by_name('native')
    style_tokens = {}
    style_tokens.update(style.styles)
    custom_styles = {string_to_tokentype(x): y for x, y in cli_style.items()}
    style_tokens.update(custom_styles)
    class CliStyle(pygments.style.Style):
        default_styles = ''
        styles = style_tokens
    return CliStyle

def create_toolbar_tokens_func(get_is_refreshing, show_fish_help):
    """Return a function that generates the toolbar tokens."""
    token = Token.Toolbar
    def get_toolbar_tokens(cli):
        result = []
        result.append((token, ' '))
        if cli.buffers[DEFAULT_BUFFER].always_multiline:
            result.append((token.On, '[F3] Multiline: ON  '))
        else:
            result.append((token.Off, '[F3] Multiline: OFF  '))
        if cli.buffers[DEFAULT_BUFFER].always_multiline:
            result.append((token, ' (Semi-colon [;] will end the line)'))
        if cli.editing_mode == EditingMode.VI:
            result.append((token.On, 'Vi-mode ({})'.format(_get_vi_mode(cli))))
        if show_fish_help():
            result.append((token, '  Right-arrow to complete suggestion'))
        if get_is_refreshing():
            result.append((token, '     Refreshing completions...'))
        return result
    return get_toolbar_tokens

def _get_vi_mode(cli):
    """Get the current vi mode for display."""
    return {InputMode.INSERT: 'I', InputMode.NAVIGATION: 'N', InputMode.REPLACE: 'R', InputMode.INSERT_MULTIPLE: 'M'}[cli.vi_state.input_mode]

def run_step(*args, prompt=None):
    """Prints out the command and asks if it should be run.
    If yes (default), runs it.
    :param args: list of strings (command and args)"""
    global DRY_RUN
    cmd = args
    print(' '.join(cmd))
    if skip_step():
        print('--- Skipping...')
    elif DRY_RUN:
        print('--- Pretending to run...')
    else:
        if prompt:
            print(prompt)
        subprocess.check_output(cmd)

def execute(cur, sql):
    """Execute a special command and return the results. If the special command
    is not supported a KeyError will be raised."""
    command, verbose, arg = parse_special_command(sql)
    if command not in COMMANDS and command.lower() not in COMMANDS:
        raise CommandNotFound
    try:
        special_cmd = COMMANDS[command]
    except KeyError:
        special_cmd = COMMANDS[command.lower()]
        if special_cmd.case_sensitive:
            raise CommandNotFound('Command not found: %s' % command)
    if command == 'help' and arg:
        return show_keyword_help(cur=cur, arg=arg)
    if special_cmd.arg_type == NO_QUERY:
        return special_cmd.handler()
    elif special_cmd.arg_type == PARSED_QUERY:
        return special_cmd.handler(cur=cur, arg=arg, verbose=verbose)
    elif special_cmd.arg_type == RAW_QUERY:
        return special_cmd.handler(cur=cur, query=sql)

def extract_table_identifiers(token_stream):
    """yields tuples of (schema_name, table_name, table_alias)"""
    for item in token_stream:
        if isinstance(item, IdentifierList):
            for identifier in item.get_identifiers():
                try:
                    schema_name = identifier.get_parent_name()
                    real_name = identifier.get_real_name()
                except AttributeError:
                    continue
                if real_name:
                    yield (schema_name, real_name, identifier.get_alias())
        elif isinstance(item, Identifier):
            real_name = item.get_real_name()
            schema_name = item.get_parent_name()
            if real_name:
                yield (schema_name, real_name, item.get_alias())
            else:
                name = item.get_name()
                yield (None, name, item.get_alias() or name)
        elif isinstance(item, Function):
            yield (None, item.get_name(), item.get_name())

def extract_tables(sql):
    """Extract the table names from an SQL statment.
    Returns a list of (schema, table, alias) tuples"""
    parsed = sqlparse.parse(sql)
    if not parsed:
        return []
    insert_stmt = parsed[0].token_first().value.lower() == 'insert'
    stream = extract_from_part(parsed[0], stop_at_punctuation=insert_stmt)
    return list(extract_table_identifiers(stream))

def find_prev_keyword(sql):
    """Find the last sql keyword in an SQL statement
    Returns the value of the last keyword, and the text of the query with
    everything after the last keyword stripped"""
    if not sql.strip():
        return (None, '')
    parsed = sqlparse.parse(sql)[0]
    flattened = list(parsed.flatten())
    logical_operators = ('AND', 'OR', 'NOT', 'BETWEEN')
    for t in reversed(flattened):
        if t.value == '(' or (t.is_keyword and t.value.upper() not in logical_operators):
            idx = flattened.index(t)
            text = ''.join((tok.value for tok in flattened[:idx + 1]))
            return (t, text)
    return (None, '')

def queries_start_with(queries, prefixes):
    """Check if any queries start with any item from *prefixes*."""
    for query in sqlparse.split(queries):
        if query and query_starts_with(query, prefixes) is True:
            return True
    return False

def rename_tables(db, table_mapping, reverse=False):
    """renames tables from source to destination name, if the source exists and the destination does
    not exist yet."""
    from django.db import connection
    if reverse:
        table_mapping = [(dst, src) for src, dst in table_mapping]
    table_names = connection.introspection.table_names()
    for source, destination in table_mapping:
        if source in table_names and destination in table_names:
            print(u'    WARNING: not renaming {0} to {1}, because both tables already exist.'.format(source, destination))
        elif source in table_names and destination not in table_names:
            print(u'     - renaming {0} to {1}'.format(source, destination))
            db.rename_table(source, destination)

def _is_autonomous(indep, exprs):
    """Whether the expressions for the dependent variables are autonomous.

    Note that the system may still behave as an autonomous system on the interface
    of :meth:`integrate` due to use of pre-/post-processors."""
    if indep is None:
        return True
    for expr in exprs:
        try:
            in_there = indep in expr.free_symbols
        except:
            in_there = expr.has(indep)
        if in_there:
            return False
    return True

def user_can_edit_news(user):
    """Check if the user has permission to edit any of the registered NewsItem
    types."""
    newsitem_models = [model.get_newsitem_model() for model in NEWSINDEX_MODEL_CLASSES]
    if user.is_active and user.is_superuser:
        return bool(newsitem_models)
    for NewsItem in newsitem_models:
        for perm in format_perms(NewsItem, ['add', 'change', 'delete']):
            if user.has_perm(perm):
                return True
    return False

def user_can_edit_newsitem(user, NewsItem):
    """Check if the user has permission to edit a particular NewsItem type."""
    for perm in format_perms(NewsItem, ['add', 'change', 'delete']):
        if user.has_perm(perm):
            return True
    return False

def get_date_or_404(year, month, day):
    """Try to make a date from the given inputs, raising Http404 on error"""
    try:
        return datetime.date(int(year), int(month), int(day))
    except ValueError:
        raise Http404

def get_newsitem_model(model_string):
    """Get the NewsItem model from a model string. Raises ValueError if the model
    string is invalid, or references a model that is not a NewsItem."""
    try:
        NewsItem = apps.get_model(model_string)
        assert issubclass(NewsItem, AbstractNewsItem)
    except (ValueError, LookupError, AssertionError):
        raise ValueError('Invalid news item model string'.format(model_string))
    return NewsItem

def requires_package(pkg, msg, error_type=ImportError):
    """Decorator when a function requires an optional dependency

    Parameters
    ----------
    pkg : imported package object
    msg : string
        Message to show to user with error_type
    error_type : python error class"""
    def _requires_package(func):
        def wrapper(*args, **kwargs):
            if pkg is None:
                raise error_type(msg)
            return func(*args, **kwargs)
        return wrapper
    return _requires_package

def read_pandas(fname, *args, **kwargs):
    """Read a file and return a pd.DataFrame"""
    if not os.path.exists(fname):
        raise ValueError('no data file `{}` found!'.format(fname))
    if fname.endswith('csv'):
        df = pd.read_csv(fname, *args, **kwargs)
    else:
        xl = pd.ExcelFile(fname)
        if len(xl.sheet_names) > 1 and 'sheet_name' not in kwargs:
            kwargs['sheet_name'] = 'data'
        df = pd.read_excel(fname, *args, **kwargs)
    return df

def read_file(fname, *args, **kwargs):
    """Read data from a file saved in the standard IAMC format
    or a table with year/value columns"""
    if not isstr(fname):
        raise ValueError('reading multiple files not supported, please use `pyam.IamDataFrame.append()`')
    logger().info('Reading `{}`'.format(fname))
    format_kwargs = {}
    for c in [i for i in IAMC_IDX + ['year', 'time', 'value'] if i in kwargs]:
        format_kwargs[c] = kwargs.pop(c)
    return format_data(read_pandas(fname, *args, **kwargs), **format_kwargs)

def sort_data(data, cols):
    """Sort `data` rows and order columns"""
    return data.sort_values(cols)[cols + ['value']].reset_index(drop=True)

def find_depth(data, s='', level=None):
    """return or assert the depth (number of `|`) of variables

    Parameters
    ----------
    data : pd.Series of strings
        IAMC-style variables
    s : str, default ''
        remove leading `s` from any variable in `data`
    level : int or str, default None
        if None, return depth (number of `|`); else, return list of booleans
        whether depth satisfies the condition (equality if `level` is int,
        >= if `.+`,  <= if `.-`)"""
    _s = re.compile('^' + _escape_regexp(s.rstrip('*')))
    _p = re.compile('\\|')
    def _count_pipes(val):
        return len(_p.findall(re.sub(_s, '', val))) if _s.match(val) else None
    n_pipes = map(_count_pipes, data)
    if level is None:
        return list(n_pipes)
    if not isstr(level):
        test = lambda x: level == x if x is not None else False
    elif level[-1] == '-':
        level = int(level[:-1])
        test = lambda x: level >= x if x is not None else False
    elif level[-1] == '+':
        level = int(level[:-1])
        test = lambda x: level <= x if x is not None else False
    else:
        raise ValueError('Unknown level type: `{}`'.format(level))
    return list(map(test, n_pipes))

def pattern_match(data, values, level=None, regexp=False, has_nan=True):
    """matching of model/scenario names, variables, regions, and meta columns to
    pseudo-regex (if `regexp == False`) for filtering (str, int, bool)"""
    matches = np.array([False] * len(data))
    if not isinstance(values, collections.Iterable) or isstr(values):
        values = [values]
    _data = data.copy()
    if has_nan:
        _data.loc[[np.isnan(i) if not isstr(i) else False for i in _data]] = ''
    for s in values:
        if isstr(s):
            pattern = re.compile(_escape_regexp(s) + '$' if not regexp else s)
            subset = filter(pattern.match, _data)
            depth = True if level is None else find_depth(_data, s, level)
            matches |= _data.isin(subset) & depth
        else:
            matches |= data == s
    return matches

def _escape_regexp(s):
    """escape characters with specific regexp use"""
    return str(s).replace('|', '\\|').replace('.', '\\.').replace('*', '.*').replace('+', '\\+').replace('(', '\\(').replace(')', '\\)').replace('$', '\\$')

def years_match(data, years):
    """matching of year columns for data filtering"""
    years = [years] if isinstance(years, int) else years
    dt = datetime.datetime
    if isinstance(years, dt) or isinstance(years[0], dt):
        error_msg = '`year` can only be filtered with ints or lists of ints'
        raise TypeError(error_msg)
    return data.isin(years)

def hour_match(data, hours):
    """matching of days in time columns for data filtering"""
    hours = [hours] if isinstance(hours, int) else hours
    return data.isin(hours)

def datetime_match(data, dts):
    """matching of datetimes in time columns for data filtering"""
    dts = dts if islistable(dts) else [dts]
    if any([not isinstance(i, datetime.datetime) for i in dts]):
        error_msg = '`time` can only be filtered by datetimes'
        raise TypeError(error_msg)
    return data.isin(dts)

def concat_with_pipe(x, cols=None):
    """Concatenate a `pd.Series` separated by `|`, drop `None` or `np.nan`"""
    cols = cols or x.index
    return '|'.join([x[i] for i in cols if x[i] not in [None, np.nan]])

def reduce_hierarchy(x, depth):
    """Reduce the hierarchy (depth by `|`) string to the specified level"""
    _x = x.split('|')
    depth = len(_x) + depth - 1 if depth < 0 else depth
    return '|'.join(_x[0:depth + 1])

def _apply_criteria(df, criteria, **kwargs):
    """Apply criteria individually to every model/scenario instance"""
    idxs = []
    for var, check in criteria.items():
        _df = df[df['variable'] == var]
        for group in _df.groupby(META_IDX):
            grp_idxs = _check_rows(group[-1], check, **kwargs)
            idxs.append(grp_idxs)
    df = df.loc[itertools.chain(*idxs)]
    return df

def _make_index(df, cols=META_IDX):
    """Create an index from the columns of a dataframe"""
    return pd.MultiIndex.from_tuples(pd.unique(list(zip(*[df[col] for col in cols]))), names=tuple(cols))

def concat(dfs):
    """Concatenate a series of `pyam.IamDataFrame`-like objects together"""
    if isstr(dfs) or not hasattr(dfs, '__iter__'):
        msg = 'Argument must be a non-string iterable (e.g., list or tuple)'
        raise TypeError(msg)
    _df = None
    for df in dfs:
        df = df if isinstance(df, IamDataFrame) else IamDataFrame(df)
        if _df is None:
            _df = copy.deepcopy(df)
        else:
            _df.append(df, inplace=True)
    return _df

def reset_default_props(**kwargs):
    """Reset properties to initial cycle point"""
    global _DEFAULT_PROPS
    pcycle = plt.rcParams['axes.prop_cycle']
    _DEFAULT_PROPS = {'color': itertools.cycle(_get_standard_colors(**kwargs)) if len(kwargs) > 0 else itertools.cycle([x['color'] for x in pcycle]), 'marker': itertools.cycle(['o', 'x', '.', '+', '*']), 'linestyle': itertools.cycle(['-', '--', '-.', ':'])}

def load_and_validate_keys(authorized_keys):
    """Loads authorized_keys as taken by :any:`instance_create`,
    :any:`disk_create` or :any:`rebuild`, and loads in any keys from any files
    provided.

    :param authorized_keys: A list of keys or paths to keys, or a single key

    :returns: A list of raw keys
    :raises: ValueError if keys in authorized_keys don't appear to be a raw
             key and can't be opened."""
    if not authorized_keys:
        return None
    if not isinstance(authorized_keys, list):
        authorized_keys = [authorized_keys]
    ret = []
    for k in authorized_keys:
        accepted_types = ('ssh-dss', 'ssh-rsa', 'ecdsa-sha2-nistp', 'ssh-ed25519')
        if any([t for t in accepted_types if k.startswith(t)]):
            ret.append(k)
        else:
            k = os.path.expanduser(k)
            if os.path.isfile(k):
                with open(k) as f:
                    ret.append(f.read().rstrip())
            else:
                raise ValueError('authorized_keys must either be paths to the key files or a list of raw public key of one of these types: {}'.format(accepted_types))
    return ret

def wrapped_target(target, q_stdout, q_stderr, q_error, robust, name, *args, **kwargs):
    """Wraps a target with queues replacing stdout and stderr"""
    import sys
    sys.stdout = IOQueue(q_stdout)
    sys.stderr = IOQueue(q_stderr)
    try:
        target(*args, **kwargs)
    except:
        if not robust:
            s = 'Error in tab\n' + traceback.format_exc()
            logger = daiquiri.getLogger(name)
            logger.error(s)
        else:
            raise
        if not robust:
            q_error.put(name)
        raise

def escape(string, escape_pattern):
    """Assistant function for string escaping"""
    try:
        return string.translate(escape_pattern)
    except AttributeError:
        warnings.warn("Non-string-like data passed. Attempting to convert to 'str'.")
        return str(string).translate(tag_escape)

def serialize(point: Mapping, measurement=None, **extra_tags) -> bytes:
    """Converts dictionary-like data into a single line protocol line (point)"""
    tags = _serialize_tags(point, extra_tags)
    return f"{_serialize_measurement(point, measurement)}{(',' if tags else '')}{tags} {_serialize_fields(point)} {_serialize_timestamp(point)}".encode()

def _serialize_fields(point):
    """Field values can be floats, integers, strings, or Booleans."""
    output = []
    for k, v in point['fields'].items():
        k = escape(k, key_escape)
        if isinstance(v, bool):
            output.append(f'{k}={v}')
        elif isinstance(v, int):
            output.append(f'{k}={v}i')
        elif isinstance(v, str):
            output.append(f'{k}="{v.translate(str_escape)}"')
        elif v is None:
            continue
        else:
            output.append(f'{k}={v}')
    return ','.join(output)

def serialize(data, measurement=None, tag_columns=None, **extra_tags):
    """Converts input data into line protocol format"""
    if isinstance(data, bytes):
        return data
    elif isinstance(data, str):
        return data.encode('utf-8')
    elif hasattr(data, 'to_lineprotocol'):
        return data.to_lineprotocol()
    elif pd is not None and isinstance(data, pd.DataFrame):
        return dataframe.serialize(data, measurement, tag_columns, **extra_tags)
    elif isinstance(data, dict):
        return mapping.serialize(data, measurement, **extra_tags)
    elif hasattr(data, '__iter__'):
        return b'\n'.join([serialize(i, measurement, tag_columns, **extra_tags) for i in data])
    else:
        raise ValueError('Invalid input', data)

def parse(resp) -> DataFrameType:
    """Makes a dictionary of DataFrames from a response object"""
    statements = []
    for statement in resp['results']:
        series = {}
        for s in statement.get('series', []):
            series[_get_name(s)] = _drop_zero_index(_serializer(s))
        statements.append(series)
    if len(statements) == 1:
        series: dict = statements[0]
        if len(series) == 1:
            return list(series.values())[0]
        else:
            return series
    return statements

def _itertuples(df):
    """Custom implementation of ``DataFrame.itertuples`` that
    returns plain tuples instead of namedtuples. About 50% faster."""
    cols = [df.iloc[:, k] for k in range(len(df.columns))]
    return zip(df.index, *cols)

def serialize(df, measurement, tag_columns=None, **extra_tags) -> bytes:
    """Converts a Pandas DataFrame into line protocol format"""
    if measurement is None:
        raise ValueError("Missing 'measurement'")
    if not isinstance(df.index, pd.DatetimeIndex):
        raise ValueError('DataFrame index is not DatetimeIndex')
    tag_columns = set(tag_columns or [])
    isnull = df.isnull().any(axis=1)
    tags = []
    fields = []
    for k, v in extra_tags.items():
        tags.append(f'{k}={escape(v, key_escape)}')
    for i, (k, v) in enumerate(df.dtypes.items()):
        k = k.translate(key_escape)
        if k in tag_columns:
            tags.append(f'{k}={{p[{i + 1}]}}')
        elif issubclass(v.type, np.integer):
            fields.append(f'{k}={{p[{i + 1}]}}i')
        elif issubclass(v.type, (np.float, np.bool_)):
            fields.append(f'{k}={{p[{i + 1}]}}')
        else:
            fields.append(f'{k}="{{p[{i + 1}]}}"')
    fmt = (f'{measurement}', f"{(',' if tags else '')}", ','.join(tags), ' ', ','.join(fields), ' {p[0].value}')
    f = eval("lambda p: f'{}'".format(''.join(fmt)))
    if isnull.any():
        lp = map(f, _itertuples(df[~isnull]))
        rep = _replace(df)
        lp_nan = (reduce(lambda a, b: re.sub(*b, a), rep, f(p)) for p in _itertuples(df[isnull]))
        return '\n'.join(chain(lp, lp_nan)).encode('utf-8')
    else:
        return '\n'.join(map(f, _itertuples(df))).encode('utf-8')

def runner(coro):
    """Function execution decorator."""
    @wraps(coro)
    def inner(self, *args, **kwargs):
        if self.mode == 'async':
            return coro(self, *args, **kwargs)
        return self._loop.run_until_complete(coro(self, *args, **kwargs))
    return inner

def mjml(parser, token):
    """Compile MJML template after render django template.

    Usage:
        {% mjml %}
            .. MJML template code ..
        {% endmjml %}"""
    nodelist = parser.parse(('endmjml',))
    parser.delete_first_token()
    tokens = token.split_contents()
    if len(tokens) != 1:
        raise template.TemplateSyntaxError("'%r' tag doesn't receive any arguments." % tokens[0])
    return MJMLRenderNode(nodelist)

def build_info_string(info):
    """Build a new vcf INFO string based on the information in the info_dict.

    The info is a dictionary with vcf info keys as keys and lists of vcf values
    as values. If there is no value False is value in info

    Args:
        info (dict): A dictionary with information from the vcf file

    Returns:
        String: A string that is on the proper vcf format for the INFO column"""
    info_list = []
    for annotation in info:
        if info[annotation]:
            info_list.append('='.join([annotation, ','.join(info[annotation])]))
        else:
            info_list.append(annotation)
    return ';'.join(info_list)

