def dump_stacktraces():
    """Dumps thread ids and tracebacks to stdout."""
    lines = []
    for thread_id, stack in sys._current_frames().items():
        lines.append('\n######### ProcessID=%s, ThreadID=%s #########' % (os.getpid(), thread_id))
        for filename, lineno, name, line in traceback.extract_stack(stack):
            lines.append('File: "%s", line %d, in %s' % (filename, lineno, name))
            if line:
                lines.append('  %s' % line.strip())
    lines.append('#############################################\n\n')
    print('\n'.join(lines), file=sys.stderr if _MANHOLE.redirect_stderr else sys.stdout)

def addevensubodd(operator, operand):
    """Add even numbers, subtract odd ones. See http://1w6.org/w6"""
    try:
        for i, x in enumerate(operand):
            if x % 2:
                operand[i] = -x
        return operand
    except TypeError:
        if operand % 2:
            return -operand
        return operand

def main(argv=None):
    """Run roll() from a command line interface"""
    args = docopt.docopt(__doc__, argv=argv, version=__version__)
    verbose = bool(args['--verbose'])
    f_roll = dice.roll
    kwargs = {}
    if args['--min']:
        f_roll = dice.roll_min
    elif args['--max']:
        f_roll = dice.roll_max
    if args['--max-dice']:
        try:
            kwargs['max_dice'] = int(args['--max-dice'])
        except ValueError:
            print("Invalid value for --max-dice: '%s'" % args['--max-dice'])
            exit(1)
    expr = ' '.join(args['<expression>'])
    try:
        roll, kwargs = f_roll(expr, raw=True, return_kwargs=True, **kwargs)
        if verbose:
            print('Result: ', end='')
        print(str(roll.evaluate_cached(**kwargs)))
        if verbose:
            print('Breakdown:')
            print(dice.utilities.verbose_print(roll, **kwargs))
    except DiceBaseException as e:
        print('Whoops! Something went wrong:')
        print(e.pretty_print())
        exit(1)

