def full_domain_validator(hostname):
    """Fully validates a domain name as compilant with the standard rules:
        - Composed of series of labels concatenated with dots, as are all domain names.
        - Each label must be between 1 and 63 characters long.
        - The entire hostname (including the delimiting dots) has a maximum of 255 characters.
        - Only characters 'a' through 'z' (in a case-insensitive manner), the digits '0' through '9'.
        - Labels can't start or end with a hyphen."""
    HOSTNAME_LABEL_PATTERN = re.compile('(?!-)[A-Z\\d-]+(?<!-)$', re.IGNORECASE)
    if not hostname:
        return
    if len(hostname) > 255:
        raise ValidationError(_('The domain name cannot be composed of more than 255 characters.'))
    if hostname[-1:] == '.':
        hostname = hostname[:-1]
    for label in hostname.split('.'):
        if len(label) > 63:
            raise ValidationError(_("The label '%(label)s' is too long (maximum is 63 characters).") % {'label': label})
        if not HOSTNAME_LABEL_PATTERN.match(label):
            raise ValidationError(_("Unallowed characters in label '%(label)s'.") % {'label': label})

def serialize_hook(instance):
    """Serialize the object down to Python primitives.

    By default it uses Django's built in serializer."""
    if getattr(instance, 'serialize_hook', None) and callable(instance.serialize_hook):
        return instance.serialize_hook(hook=instance)
    if getattr(settings, 'HOOK_SERIALIZER', None):
        serializer = get_module(settings.HOOK_SERIALIZER)
        return serializer(instance, hook=instance)
    return {'hook': instance.dict(), 'data': serializers.serialize('python', [instance])[0]}

def deliver_hook(instance, target, payload_override=None):
    """Deliver the payload to the target URL.

    By default it serializes to JSON and POSTs."""
    payload = payload_override or serialize_hook(instance)
    if hasattr(settings, 'HOOK_DELIVERER'):
        deliverer = get_module(settings.HOOK_DELIVERER)
        deliverer(target, payload, instance=instance)
    else:
        client.post(url=target, data=json.dumps(payload, cls=serializers.json.DjangoJSONEncoder), headers={'Content-Type': 'application/json'})
    return None

