def load(istream, strict=True):
    """Deserialize a patch object."""
    try:
        diff = json.load(istream)
        if strict:
            jsonschema.validate(diff, SCHEMA)
    except ValueError:
        raise InvalidPatchError('patch is not valid JSON')
    except jsonschema.exceptions.ValidationError as e:
        raise InvalidPatchError(e.message)
    return diff

def save(diff, stream=sys.stdout, compact=False):
    """Serialize a patch object."""
    flags = {'sort_keys': True}
    if not compact:
        flags['indent'] = 2
    json.dump(diff, stream, **flags)

def create(from_records, to_records, index_columns, ignore_columns=None):
    """Diff two sets of records, using the index columns as the primary key for
    both datasets."""
    from_indexed = records.index(from_records, index_columns)
    to_indexed = records.index(to_records, index_columns)
    if ignore_columns is not None:
        from_indexed = records.filter_ignored(from_indexed, ignore_columns)
        to_indexed = records.filter_ignored(to_indexed, ignore_columns)
    return create_indexed(from_indexed, to_indexed, index_columns)

def _compare_rows(from_recs, to_recs, keys):
    """Return the set of keys which have changed."""
    return set((k for k in keys if sorted(from_recs[k].items()) != sorted(to_recs[k].items())))

def record_diff(lhs, rhs):
    """Diff an individual row."""
    delta = {}
    for k in set(lhs).union(rhs):
        from_ = lhs[k]
        to_ = rhs[k]
        if from_ != to_:
            delta[k] = {'from': from_, 'to': to_}
    return delta

def _is_significant(change, significance):
    """Return True if a change is genuinely significant given our tolerance."""
    try:
        a = float(change['from'])
        b = float(change['to'])
    except ValueError:
        return True
    return abs(a - b) > 10 ** (-significance)

def patch_records(diff, from_records, strict=True):
    """Apply the patch to the sequence of records, returning the transformed
    records."""
    return patch.apply(diff, from_records, strict=strict)

def csvdiff_cmd(index_columns, from_csv, to_csv, style=None, output=None, sep=',', quiet=False, ignore_columns=None, significance=None):
    """Compare two csv files to see what rows differ between them. The files
    are each expected to have a header row, and for each row to be uniquely
    identified by one or more indexing columns."""
    if ignore_columns is not None:
        for i in ignore_columns:
            if i in index_columns:
                error.abort("You can't ignore an index column")
    ostream = open(output, 'w') if output else io.StringIO() if quiet else sys.stdout
    try:
        if style == 'summary':
            _diff_and_summarize(from_csv, to_csv, index_columns, ostream, sep=sep, ignored_columns=ignore_columns, significance=significance)
        else:
            compact = style == 'compact'
            _diff_files_to_stream(from_csv, to_csv, index_columns, ostream, compact=compact, sep=sep, ignored_columns=ignore_columns, significance=significance)
    except records.InvalidKeyError as e:
        error.abort(e.args[0])
    finally:
        ostream.close()

def sort(records: Sequence[Record]) -> List[Record]:
    """Sort records into a canonical order, suitable for comparison."""
    return sorted(records, key=_record_key)

def _record_key(record: Record) -> List[Tuple[Column, str]]:
    """An orderable representation of this record."""
    return sorted(record.items())

def getargspecs(func):
    """Bridges inspect.getargspec and inspect.getfullargspec.
    Automatically selects the proper one depending of current Python version.
    Automatically bypasses wrappers from typechecked- and override-decorators."""
    if func is None:
        raise TypeError('None is not a Python function')
    if hasattr(func, 'ch_func'):
        return getargspecs(func.ch_func)
    elif hasattr(func, 'ov_func'):
        return getargspecs(func.ov_func)
    if hasattr(inspect, 'getfullargspec'):
        return inspect.getfullargspec(func)
    else:
        return inspect.getargspec(func)

def get_required_kwonly_args(argspecs):
    """Determines whether given argspecs implies required keywords-only args
    and returns them as a list. Returns empty list if no such args exist."""
    try:
        kwonly = argspecs.kwonlyargs
        if argspecs.kwonlydefaults is None:
            return kwonly
        res = []
        for name in kwonly:
            if not name in argspecs.kwonlydefaults:
                res.append(name)
        return res
    except AttributeError:
        return []

def getargnames(argspecs, with_unbox=False):
    """Resembles list of arg-names as would be seen in a function signature, including
    var-args, var-keywords and keyword-only args."""
    args = argspecs.args
    vargs = argspecs.varargs
    try:
        kw = argspecs.keywords
    except AttributeError:
        kw = argspecs.varkw
    try:
        kwonly = argspecs.kwonlyargs
    except AttributeError:
        kwonly = None
    res = []
    if not args is None:
        res.extend(args)
    if not vargs is None:
        res.append('*' + vargs if with_unbox else vargs)
    if not kwonly is None:
        res.extend(kwonly)
    if not kw is None:
        res.append('**' + kw if with_unbox else kw)
    return res

def fromargskw(argskw, argspecs, slf_or_clsm=False):
    """Turns a linearized list of args into (args, keywords) form
    according to given argspecs (like inspect module provides)."""
    res_args = argskw
    try:
        kwds = argspecs.keywords
    except AttributeError:
        kwds = argspecs.varkw
    if not kwds is None:
        res_kw = argskw[-1]
        res_args = argskw[:-1]
    else:
        res_kw = None
    if not argspecs.varargs is None:
        vargs_pos = len(argspecs.args) - 1 if slf_or_clsm else len(argspecs.args)
        if vargs_pos > 0:
            res_lst = list(argskw[:vargs_pos])
            res_lst.extend(argskw[vargs_pos])
            res_args = tuple(res_lst)
        else:
            res_args = argskw[0]
    try:
        if len(argspecs.kwonlyargs) > 0:
            res_kw = {} if res_kw is None else dict(res_kw)
            ipos = -len(argspecs.kwonlyargs) - (0 if kwds is None else 1)
            for name in argspecs.kwonlyargs:
                res_kw[name] = argskw[ipos]
                ipos += 1
    except AttributeError:
        pass
    if res_kw is None:
        res_kw = {}
    return (res_args, res_kw)

def get_class_qualname(cls):
    """Determines the fully qualified name of a class.
    Yields a result similar to what __qualname__ contains, but also works on
    Python 2.7."""
    if hasattr(cls, '__qualname__'):
        return cls.__qualname__
    module = sys.modules[cls.__module__]
    if cls.__module__ == 'typing' and (not hasattr(cls, '__name__')):
        return cls._name
    if hasattr(module, cls.__name__) and getattr(module, cls.__name__) is cls:
        return cls.__name__
    else:
        nst = _get_class_nesting_list(cls, module)
        nst.append(cls)
        nst = [cl.__name__ for cl in nst]
        return '.'.join(nst)
    return cls.__name__

def search_class_module(cls, deep_search=True):
    """E.g. if cls is a TypeVar, cls.__module__ won't contain the actual module
    that declares cls. This returns the actual module declaring cls.
    Can be used with any class (not only TypeVar), though usually cls.__module__
    is the recommended way.
    If deep_search is True (default) this even finds the correct module if it
    declares cls as an inner class of another class."""
    for md_name in sys.modules:
        module = sys.modules[md_name]
        if hasattr(module, cls.__name__) and getattr(module, cls.__name__) is cls:
            return module
    if deep_search:
        for md_name in sys.modules:
            module = sys.modules[md_name]
            try:
                nst = _get_class_nesting_list(cls, module)
                if cls is nst[-1]:
                    return module
            except:
                pass
    return None

def get_class_that_defined_method(meth):
    """Determines the class owning the given method.
    """
    if is_classmethod(meth):
        return meth.__self__
    if hasattr(meth, 'im_class'):
        return meth.im_class
    elif hasattr(meth, '__qualname__'):
        try:
            cls_names = meth.__qualname__.split('.<locals>', 1)[0].rsplit('.', 1)[0].split('.')
            cls = inspect.getmodule(meth)
            for cls_name in cls_names:
                cls = getattr(cls, cls_name)
            if isinstance(cls, type):
                return cls
        except AttributeError:
            pass
    raise ValueError(str(meth) + ' is not a method.')

def is_method(func):
    """Detects if the given callable is a method. In context of pytypes this
    function is more reliable than plain inspect.ismethod, e.g. it automatically
    bypasses wrappers from typechecked and override decorators."""
    func0 = _actualfunc(func)
    argNames = getargnames(getargspecs(func0))
    if len(argNames) > 0:
        if argNames[0] == 'self':
            if inspect.ismethod(func):
                return True
            elif sys.version_info.major >= 3:
                return True
            else:
                _warn_argname('is_method encountered non-method declaring self', func0, False, False, None)
        else:
            return inspect.ismethod(func)
    return False

def is_classmethod(meth):
    """Detects if the given callable is a classmethod.
    """
    if inspect.ismethoddescriptor(meth):
        return isinstance(meth, classmethod)
    if not inspect.ismethod(meth):
        return False
    if not inspect.isclass(meth.__self__):
        return False
    if not hasattr(meth.__self__, meth.__name__):
        return False
    return meth == getattr(meth.__self__, meth.__name__)

def get_current_args(caller_level=0, func=None, argNames=None):
    """Determines the args of current function call.
    Use caller_level > 0 to get args of even earlier function calls in current stack."""
    if argNames is None:
        argNames = getargnames(getargspecs(func))
    if func is None:
        func = get_current_function(caller_level + 1)
    if isinstance(func, property):
        func = func.fget if func.fset is None else func.fset
    stck = inspect.stack()
    lcs = stck[1 + caller_level][0].f_locals
    return tuple([lcs[t] for t in argNames])

def getmodule(code):
    """More robust variant of inspect.getmodule.
    E.g. has less issues on Jython."""
    try:
        md = inspect.getmodule(code, code.co_filename)
    except AttributeError:
        return inspect.getmodule(code)
    if md is None:
        cfname = code.co_filename.replace('__pyclasspath__', os.path.realpath('') + os.sep + '__pyclasspath__')
        cfname = cfname.replace('$py.class', '.py')
        md = inspect.getmodule(code, cfname)
    if md is None:
        md = inspect.getmodule(code)
    return md

def get_callable_fq_for_code(code, locals_dict=None):
    """Determines the function belonging to a given code object in a fully qualified fashion.
    Returns a tuple consisting of
    - the callable
    - a list of classes and inner classes, locating the callable (like a fully qualified name)
    - a boolean indicating whether the callable is a method"""
    if code in _code_callable_dict:
        res = _code_callable_dict[code]
        if not res[0] is None or locals_dict is None:
            return res
    md = getmodule(code)
    if not md is None:
        nesting = []
        res, slf = _get_callable_fq_for_code(code, md, md, False, nesting, set())
        if res is None and (not locals_dict is None):
            nesting = []
            res, slf = _get_callable_from_locals(code, locals_dict, md, False, nesting)
        else:
            _code_callable_dict[code] = (res, nesting, slf)
        return (res, nesting, slf)
    else:
        return (None, None, None)

def _calc_traceback_limit(tb):
    """Calculates limit-parameter to strip away pytypes' internals when used
    with API from traceback module."""
    limit = 1
    tb2 = tb
    while not tb2.tb_next is None:
        try:
            maybe_pytypes = tb2.tb_next.tb_frame.f_code.co_filename.split(os.sep)[-2]
        except IndexError:
            maybe_pytypes = None
        if maybe_pytypes == 'pytypes' and (not tb2.tb_next.tb_frame.f_code == pytypes.typechecker._pytypes___import__.__code__):
            break
        else:
            limit += 1
            tb2 = tb2.tb_next
    return limit

def _pytypes_excepthook(exctype, value, tb):
    """"An excepthook suitable for use as sys.excepthook, that strips away
    the part of the traceback belonging to pytypes' internals.
    Can be switched on and off via pytypes.clean_traceback
    or pytypes.set_clean_traceback.
    The latter automatically installs this hook in sys.excepthook."""
    if pytypes.clean_traceback and issubclass(exctype, TypeError):
        traceback.print_exception(exctype, value, tb, _calc_traceback_limit(tb))
    elif _sys_excepthook is None:
        sys.__excepthook__(exctype, value, tb)
    else:
        _sys_excepthook(exctype, value, tb)

def get_generator_type(genr):
    """Obtains PEP 484 style type of a generator object, i.e. returns a
    typing.Generator object."""
    if genr in _checked_generator_types:
        return _checked_generator_types[genr]
    if not genr.gi_frame is None and 'gen_type' in genr.gi_frame.f_locals:
        return genr.gi_frame.f_locals['gen_type']
    else:
        cllble, nesting, slf = util.get_callable_fq_for_code(genr.gi_code)
        if cllble is None:
            return Generator
        return _funcsigtypes(cllble, slf, nesting[-1] if slf else None, genr.gi_frame.f_globals if not genr.gi_frame is None else None)[1]

def get_Generic_itemtype(sq, simplify=True):
    """Retrieves the item type from a PEP 484 generic or subclass of such.
    sq must be a typing.Tuple or (subclass of) typing.Iterable or typing.Container.
    Consequently this also works with typing.List, typing.Set and typing.Dict.
    Note that for typing.Dict and mapping types in general, the key type is regarded as item type.
    For typing.Tuple all contained types are returned as a typing.Union.
    If simplify == True some effort is taken to eliminate redundancies in such a union."""
    if is_Tuple(sq):
        if simplify:
            itm_tps = [x for x in get_Tuple_params(sq)]
            simplify_for_Union(itm_tps)
            return Union[tuple(itm_tps)]
        else:
            return Union[get_Tuple_params(sq)]
    else:
        try:
            res = _select_Generic_superclass_parameters(sq, typing.Container)
        except TypeError:
            res = None
        if res is None:
            try:
                res = _select_Generic_superclass_parameters(sq, typing.Iterable)
            except TypeError:
                pass
        if res is None:
            raise TypeError('Has no itemtype: ' + type_str(sq))
        else:
            return res[0]

def get_Mapping_key_value(mp):
    """Retrieves the key and value types from a PEP 484 mapping or subclass of such.
    mp must be a (subclass of) typing.Mapping."""
    try:
        res = _select_Generic_superclass_parameters(mp, typing.Mapping)
    except TypeError:
        res = None
    if res is None:
        raise TypeError('Has no key/value types: ' + type_str(mp))
    else:
        return tuple(res)

def get_Generic_parameters(tp, generic_supertype):
    """tp must be a subclass of generic_supertype.
    Retrieves the type values from tp that correspond to parameters
    defined by generic_supertype.

    E.g. get_Generic_parameters(tp, typing.Mapping) is equivalent
    to get_Mapping_key_value(tp) except for the error message.

    Note that get_Generic_itemtype(tp) is not exactly equal to
    get_Generic_parameters(tp, typing.Container), as that method
    additionally contains treatment for typing.Tuple and typing.Iterable."""
    try:
        res = _select_Generic_superclass_parameters(tp, generic_supertype)
    except TypeError:
        res = None
    if res is None:
        raise TypeError('%s has no proper parameters defined by %s.' % (type_str(tp), type_str(generic_supertype)))
    else:
        return tuple(res)

def get_Tuple_params(tpl):
    """Python version independent function to obtain the parameters
    of a typing.Tuple object.
    Omits the ellipsis argument if present. Use is_Tuple_ellipsis for that.
    Tested with CPython 2.7, 3.5, 3.6 and Jython 2.7.1."""
    try:
        return tpl.__tuple_params__
    except AttributeError:
        try:
            if tpl.__args__ is None:
                return None
            if tpl.__args__[0] == ():
                return ()
            elif tpl.__args__[-1] is Ellipsis:
                return tpl.__args__[:-1] if len(tpl.__args__) > 1 else None
            else:
                return tpl.__args__
        except AttributeError:
            return None

def is_Tuple_ellipsis(tpl):
    """Python version independent function to check if a typing.Tuple object
    contains an ellipsis."""
    try:
        return tpl.__tuple_use_ellipsis__
    except AttributeError:
        try:
            if tpl.__args__ is None:
                return False
            if tpl.__args__[-1] is Ellipsis:
                return True
        except AttributeError:
            pass
        return False

def get_Callable_args_res(clb):
    """Python version independent function to obtain the parameters
    of a typing.Callable object. Returns as tuple: args, result.
    Tested with CPython 2.7, 3.5, 3.6 and Jython 2.7.1."""
    try:
        return (clb.__args__, clb.__result__)
    except AttributeError:
        return (clb.__args__[:-1], clb.__args__[-1])

def is_Type(tp):
    """Python version independent check if an object is a type.
    For Python 3.7 onwards(?) this is not equivalent to
    ``isinstance(tp, type)`` any more, as that call would return
    ``False`` for PEP 484 types.
    Tested with CPython 2.7, 3.5, 3.6, 3.7 and Jython 2.7.1."""
    if isinstance(tp, type):
        return True
    try:
        typing._type_check(tp, '')
        return True
    except TypeError:
        return False

def is_Union(tp):
    """Python version independent check if a type is typing.Union.
    Tested with CPython 2.7, 3.5, 3.6 and Jython 2.7.1."""
    if tp is Union:
        return True
    try:
        return tp.__origin__ is Union
    except AttributeError:
        try:
            return isinstance(tp, typing.UnionMeta)
        except AttributeError:
            return False

def is_builtin_type(tp):
    """Checks if the given type is a builtin one.
    """
    return hasattr(__builtins__, tp.__name__) and tp is getattr(__builtins__, tp.__name__)

def get_types(func):
    """Works like get_type_hints, but returns types as a sequence rather than a
    dictionary. Types are returned in declaration order of the corresponding arguments."""
    return _get_types(func, util.is_classmethod(func), util.is_method(func))

def _get_types(func, clsm, slf, clss=None, prop_getter=False, unspecified_type=Any, infer_defaults=None):
    """Helper for get_types and get_member_types.
    """
    func0 = util._actualfunc(func, prop_getter)
    if not slf:
        argNames = util.getargnames(util.getargspecs(func0))
        if len(argNames) > 0:
            if clsm:
                if argNames[0] != 'cls':
                    util._warn_argname('classmethod using non-idiomatic cls argname', func0, slf, clsm, clss)
    if clss is None and (slf or clsm):
        if slf:
            assert util.is_method(func) or isinstance(func, property)
        if clsm:
            assert util.is_classmethod(func)
        clss = util.get_class_that_defined_method(func)
        assert hasattr(clss, func.__name__)
    args, res = _funcsigtypes(func, slf or clsm, clss, None, prop_getter, unspecified_type=unspecified_type, infer_defaults=infer_defaults)
    return (_match_stub_type(args), _match_stub_type(res))

def _get_type_hints(func, args=None, res=None, infer_defaults=None):
    """Helper for get_type_hints.
    """
    if args is None or res is None:
        args2, res2 = _get_types(func, util.is_classmethod(func), util.is_method(func), unspecified_type=type(NotImplemented), infer_defaults=infer_defaults)
        if args is None:
            args = args2
        if res is None:
            res = res2
    slf = 1 if util.is_method(func) else 0
    argNames = util.getargnames(util.getargspecs(util._actualfunc(func)))
    result = {}
    if not args is Any:
        prms = get_Tuple_params(args)
        for i in range(slf, len(argNames)):
            if not prms[i - slf] is type(NotImplemented):
                result[argNames[i]] = prms[i - slf]
    result['return'] = res
    return result

def _find_Generic_super_origin(subclass, superclass_origin):
    """Helper for _issubclass_Generic.
    """
    stack = [subclass]
    param_map = {}
    while len(stack) > 0:
        bs = stack.pop()
        if is_Generic(bs):
            if not bs.__origin__ is None and len(bs.__origin__.__parameters__) > 0:
                for i in range(len(bs.__args__)):
                    ors = bs.__origin__.__parameters__[i]
                    if bs.__args__[i] != ors and isinstance(bs.__args__[i], TypeVar):
                        param_map[ors] = bs.__args__[i]
            if bs.__origin__ is superclass_origin or (bs.__origin__ is None and bs is superclass_origin):
                prms = []
                try:
                    if len(bs.__origin__.__parameters__) > len(bs.__parameters__):
                        prms.extend(bs.__origin__.__parameters__)
                    else:
                        prms.extend(bs.__parameters__)
                except:
                    prms.extend(bs.__parameters__)
                for i in range(len(prms)):
                    while prms[i] in param_map:
                        prms[i] = param_map[prms[i]]
                return prms
            try:
                stack.extend(bs.__orig_bases__)
            except AttributeError:
                stack.extend(bs.__bases__)
    return None

def _select_Generic_superclass_parameters(subclass, superclass_origin):
    """Helper for _issubclass_Generic.
    """
    subclass = _find_base_with_origin(subclass, superclass_origin)
    if subclass is None:
        return None
    if subclass.__origin__ is superclass_origin:
        return subclass.__args__
    prms = _find_Generic_super_origin(subclass, superclass_origin)
    res = []
    for prm in prms:
        sub_search = subclass
        while not sub_search is None:
            try:
                res.append(sub_search.__args__[sub_search.__origin__.__parameters__.index(prm)])
                break
            except ValueError:
                sub_search = _find_base_with_origin(sub_search.__origin__, superclass_origin)
        else:
            return None
    return res

def _issubclass_Union(subclass, superclass, bound_Generic, bound_typevars, bound_typevars_readonly, follow_fwd_refs, _recursion_check):
    """Helper for _issubclass, a.k.a pytypes.issubtype.
    """
    if not follow_fwd_refs:
        return _issubclass_Union_rec(subclass, superclass, bound_Generic, bound_typevars, bound_typevars_readonly, follow_fwd_refs, _recursion_check)
    try:
        return _issubclass_Union_rec(subclass, superclass, bound_Generic, bound_typevars, bound_typevars_readonly, False, _recursion_check)
    except pytypes.ForwardRefError:
        return _issubclass_Union_rec(subclass, superclass, bound_Generic, bound_typevars, bound_typevars_readonly, follow_fwd_refs, _recursion_check)

def _issubclass_Union_rec(subclass, superclass, bound_Generic, bound_typevars, bound_typevars_readonly, follow_fwd_refs, _recursion_check):
    """Helper for _issubclass_Union.
    """
    super_args = get_Union_params(superclass)
    if super_args is None:
        return is_Union(subclass)
    elif is_Union(subclass):
        sub_args = get_Union_params(subclass)
        if sub_args is None:
            return False
        return all((_issubclass(c, superclass, bound_Generic, bound_typevars, bound_typevars_readonly, follow_fwd_refs, _recursion_check) for c in sub_args))
    elif isinstance(subclass, TypeVar):
        if subclass in super_args:
            return True
        if subclass.__constraints__:
            return _issubclass(Union[subclass.__constraints__], superclass, bound_Generic, bound_typevars, bound_typevars_readonly, follow_fwd_refs, _recursion_check)
        return False
    else:
        return any((_issubclass(subclass, t, bound_Generic, bound_typevars, bound_typevars_readonly, follow_fwd_refs, _recursion_check) for t in super_args))

def _has_base(cls, base):
    """Helper for _issubclass, a.k.a pytypes.issubtype.
    """
    if cls is base:
        return True
    elif cls is None:
        return False
    try:
        for bs in cls.__bases__:
            if _has_base(bs, base):
                return True
    except:
        pass
    return False

def annotations_func(func):
    """Works like annotations, but is only applicable to functions,
    methods and properties."""
    if not has_type_hints(func):
        func.__annotations__ = {}
    func.__annotations__ = _get_type_hints(func, infer_defaults=False)
    return func

def annotations_class(cls):
    """Works like annotations, but is only applicable to classes.
    """
    assert isclass(cls)
    keys = [key for key in cls.__dict__]
    for key in keys:
        memb = cls.__dict__[key]
        if _check_as_func(memb):
            annotations_func(memb)
        elif isclass(memb):
            annotations_class(memb)
    return cls

def annotations_module(md):
    """Works like annotations, but is only applicable to modules (by explicit call).
    md must be a module or a module name contained in sys.modules."""
    if isinstance(md, str):
        if md in sys.modules:
            md = sys.modules[md]
            if md is None:
                return md
        elif md in pytypes.typechecker._pending_modules:
            pytypes.typechecker._pending_modules[md].append(annotations_module)
            return md
    assert ismodule(md)
    if md.__name__ in pytypes.typechecker._pending_modules:
        pytypes.typechecker._pending_modules[md.__name__].append(annotations_module)
    if md.__name__ in _annotated_modules and _annotated_modules[md.__name__] == len(md.__dict__):
        return md
    keys = [key for key in md.__dict__]
    for key in keys:
        memb = md.__dict__[key]
        if _check_as_func(memb) and memb.__module__ == md.__name__:
            annotations_func(memb)
        elif isclass(memb) and memb.__module__ == md.__name__:
            annotations_class(memb)
    if not md.__name__ in pytypes.typechecker._pending_modules:
        _annotated_modules[md.__name__] = len(md.__dict__)
    return md

def annotations(memb):
    """Decorator applicable to functions, methods, properties,
    classes or modules (by explicit call).
    If applied on a module, memb must be a module or a module name contained in sys.modules.
    See pytypes.set_global_annotations_decorator to apply this on all modules.
    Methods with type comment will have type hints parsed from that
    string and get them attached as __annotations__ attribute.
    Methods with either a type comment or ordinary type annotations in
    a stubfile will get that information attached as __annotations__
    attribute (also a relevant use case in Python 3).
    Behavior in case of collision with previously (manually)
    attached __annotations__ can be controlled using the flags
    pytypes.annotations_override_typestring and pytypes.annotations_from_typestring."""
    if _check_as_func(memb):
        return annotations_func(memb)
    if isclass(memb):
        return annotations_class(memb)
    if ismodule(memb):
        return annotations_module(memb)
    if memb in sys.modules or memb in pytypes.typechecker._pending_modules:
        return annotations_module(memb)
    return memb

def simplify_for_Union(type_list):
    """Removes types that are subtypes of other elements in the list.
    Does not return a copy, but instead modifies the given list.
    Intended for preprocessing of types to be combined into a typing.Union.
    Subtypecheck is backed by pytypes.is_subtype, so this differs from
    typing.Union's own simplification efforts.
    E.g. this also considers numeric tower like described in
    https://www.python.org/dev/peps/pep-0484/#the-numeric-tower
    (treats int as subtype of float as subtype of complex)
    Use pytypes.apply_numeric_tower flag to switch off numeric tower support."""
    i = 0
    while i < len(type_list):
        j = 0
        while j < i:
            if _issubclass(type_list[j], type_list[i]):
                del type_list[j]
                i -= 1
            else:
                j += 1
        j = i + 1
        while j < len(type_list):
            if _issubclass(type_list[j], type_list[i]):
                del type_list[j]
            else:
                j += 1
        i += 1

def log_type(args_kw, ret, func, slf=False, prop_getter=False, clss=None, argspecs=None, args_kw_type=None, ret_type=None):
    """Stores information of a function or method call into a cache, so pytypes can
    create a PEP 484 stubfile from this information later on (see dump_cache)."""
    if args_kw_type is None:
        args_kw_type = deep_type(args_kw)
    if ret_type is None:
        ret_type = deep_type(ret)
    if argspecs is None:
        argspecs = getargspecs(func)
    node = _register_logged_func(func, slf, prop_getter, clss, argspecs)
    node.add_observation(args_kw_type, ret_type)
    md = util.getmodule_for_member(func, prop_getter)
    if not md.__name__ in _module_file_map:
        _module_file_map[md.__name__] = md.__file__
    if clss is None:
        try:
            clss = util.get_class_that_defined_method(func)
        except ValueError:
            pass
    if not clss is None and (not clss in _member_line_map):
        _member_line_map[clss] = findsource(clss)[1]

def combine_argtype(observations):
    """Combines a list of Tuple types into one.
    Basically these are combined element wise into a Union with some
    additional unification effort (e.g. can apply PEP 484 style numeric tower)."""
    assert len(observations) > 0
    assert is_Tuple(observations[0])
    if len(observations) > 1:
        prms = [get_Tuple_params(observations[0])]
        ln = len(prms[0])
        for obs in observations[1:]:
            assert is_Tuple(obs)
            prms.append(get_Tuple_params(obs))
            assert len(prms[-1]) == ln
        if simplify:
            prms = map(list, zip(*prms))
            if not isinstance(prms, list):
                prms = list(prms)
            for type_list in prms:
                simplify_for_Union(type_list)
            prms = map(tuple, prms)
        else:
            prms = map(tuple, zip(*prms))
        prms = map(Union.__getitem__, prms)
        return Tuple[tuple(prms)]
    else:
        return observations[0]

def dump_cache(path=None, python2=False, suffix=None):
    """Writes cached observations by @typelogged into stubfiles.
    Files will be created in the directory provided as 'path'; overwrites
    existing files without notice.
    Uses 'pyi2' suffix if 'python2' flag is given else 'pyi'. Resulting
    files will be Python 2.7 compilant accordingly."""
    typelogging_enabled_tmp = pytypes.typelogging_enabled
    pytypes.typelogging_enabled = False
    if suffix is None:
        suffix = 'pyi2' if python2 else 'pyi'
    if path is None:
        path = pytypes.default_typelogger_path
    modules = {}
    for key in _member_cache:
        node = _member_cache[key]
        mname = node.get_modulename()
        if not mname in modules:
            mnode = _module_node(mname)
            modules[mname] = mnode
        else:
            mnode = modules[mname]
        mnode.append(node)
    for module in modules:
        _dump_module(modules[module], path, python2, suffix)
    pytypes.typelogging_enabled = typelogging_enabled_tmp

def get_indentation(func):
    """Extracts a function's indentation as a string,
    In contrast to an inspect.indentsize based implementation,
    this function preserves tabs if present."""
    src_lines = getsourcelines(func)[0]
    for line in src_lines:
        if not (line.startswith('@') or line.startswith('def') or line.lstrip().startswith('#')):
            return line[:len(line) - len(line.lstrip())]
    return pytypes.default_indent

def typelogged_func(func):
    """Works like typelogged, but is only applicable to functions,
    methods and properties."""
    if not pytypes.typelogging_enabled:
        return func
    if hasattr(func, 'do_logging'):
        func.do_logging = True
        return func
    elif hasattr(func, 'do_typecheck'):
        return _typeinspect_func(func, func.do_typecheck, True)
    else:
        return _typeinspect_func(func, False, True)

def typelogged_class(cls):
    """Works like typelogged, but is only applicable to classes.
    """
    if not pytypes.typelogging_enabled:
        return cls
    assert isclass(cls)
    keys = [key for key in cls.__dict__]
    for key in keys:
        memb = cls.__dict__[key]
        if _check_as_func(memb):
            setattr(cls, key, typelogged_func(memb))
        elif isclass(memb):
            typelogged_class(memb)
    return cls

def typelogged_module(md):
    """Works like typelogged, but is only applicable to modules by explicit call).
    md must be a module or a module name contained in sys.modules."""
    if not pytypes.typelogging_enabled:
        return md
    if isinstance(md, str):
        if md in sys.modules:
            md = sys.modules[md]
            if md is None:
                return md
        elif md in pytypes.typechecker._pending_modules:
            pytypes.typechecker._pending_modules[md].append(typelogged_module)
            return md
    assert ismodule(md)
    if md.__name__ in pytypes.typechecker._pending_modules:
        pytypes.typechecker._pending_modules[md.__name__].append(typelogged_module)
    assert ismodule(md)
    if md.__name__ in _fully_typelogged_modules and _fully_typelogged_modules[md.__name__] == len(md.__dict__):
        return md
    keys = [key for key in md.__dict__]
    for key in keys:
        memb = md.__dict__[key]
        if _check_as_func(memb) and memb.__module__ == md.__name__:
            setattr(md, key, typelogged_func(memb))
        elif isclass(memb) and memb.__module__ == md.__name__:
            typelogged_class(memb)
    if not md.__name__ in pytypes.typechecker._pending_modules:
        _fully_typelogged_modules[md.__name__] = len(md.__dict__)
    return md

def typelogged(memb):
    """Decorator applicable to functions, methods, properties,
    classes or modules (by explicit call).
    If applied on a module, memb must be a module or a module name contained in sys.modules.
    See pytypes.set_global_typelogged_decorator to apply this on all modules.
    Observes function and method calls at runtime and allows pytypes to generate stubfiles
    from the acquired type information.
    Use dump_cache to write a stubfile in this manner."""
    if not pytypes.typelogging_enabled:
        return memb
    if _check_as_func(memb):
        return typelogged_func(memb)
    if isclass(memb):
        return typelogged_class(memb)
    if ismodule(memb):
        return typelogged_module(memb)
    if memb in sys.modules or memb in pytypes.typechecker._pending_modules:
        return typelogged_module(memb)
    return memb

def enable_global_typechecked_profiler(flag=True):
    """Enables or disables global typechecking mode via a profiler.
    See flag global_typechecked_profiler.
    Does not work if checking_enabled is false."""
    global global_typechecked_profiler, _global_type_agent, global_typelogged_profiler
    global_typechecked_profiler = flag
    if flag and checking_enabled:
        if _global_type_agent is None:
            _global_type_agent = TypeAgent()
            _global_type_agent.start()
        elif not _global_type_agent.active:
            _global_type_agent.start()
    elif not flag and (not global_typelogged_profiler) and (not _global_type_agent is None) and _global_type_agent.active:
        _global_type_agent.stop()

def enable_global_typelogged_profiler(flag=True):
    """Enables or disables global typelogging mode via a profiler.
    See flag global_typelogged_profiler.
    Does not work if typelogging_enabled is false."""
    global global_typelogged_profiler, _global_type_agent, global_typechecked_profiler
    global_typelogged_profiler = flag
    if flag and typelogging_enabled:
        if _global_type_agent is None:
            _global_type_agent = TypeAgent()
            _global_type_agent.start()
        elif not _global_type_agent.active:
            _global_type_agent.start()
    elif not flag and (not global_typechecked_profiler) and (not _global_type_agent is None) and _global_type_agent.active:
        _global_type_agent.stop()

def typechecked_func(func, force=False, argType=None, resType=None, prop_getter=False):
    """Works like typechecked, but is only applicable to functions, methods and properties.
    """
    if not pytypes.checking_enabled and (not pytypes.do_logging_in_typechecked):
        return func
    assert _check_as_func(func)
    if not force and is_no_type_check(func):
        return func
    if hasattr(func, 'do_typecheck'):
        func.do_typecheck = True
        return func
    elif hasattr(func, 'do_logging'):
        return _typeinspect_func(func, True, func.do_logging, argType, resType, prop_getter)
    else:
        return _typeinspect_func(func, True, False, argType, resType, prop_getter)

def typechecked_class(cls, force=False, force_recursive=False):
    """Works like typechecked, but is only applicable to classes.
    """
    return _typechecked_class(cls, set(), force, force_recursive)

def typechecked_module(md, force_recursive=False):
    """Works like typechecked, but is only applicable to modules (by explicit call).
    md must be a module or a module name contained in sys.modules."""
    if not pytypes.checking_enabled:
        return md
    if isinstance(md, str):
        if md in sys.modules:
            md = sys.modules[md]
            if md is None:
                return md
        elif md in _pending_modules:
            _pending_modules[md].append(lambda t: typechecked_module(t, True))
            return md
    assert ismodule(md)
    if md.__name__ in _pending_modules:
        _pending_modules[md.__name__].append(lambda t: typechecked_module(t, True))
    if md.__name__ in _fully_typechecked_modules and _fully_typechecked_modules[md.__name__] == len(md.__dict__):
        return md
    keys = [key for key in md.__dict__]
    for key in keys:
        memb = md.__dict__[key]
        if force_recursive or (not is_no_type_check(memb) and hasattr(memb, '__module__')):
            if _check_as_func(memb) and memb.__module__ == md.__name__ and has_type_hints(memb):
                setattr(md, key, typechecked_func(memb, force_recursive))
            elif isclass(memb) and memb.__module__ == md.__name__:
                typechecked_class(memb, force_recursive, force_recursive)
    if not md.__name__ in _pending_modules:
        _fully_typechecked_modules[md.__name__] = len(md.__dict__)
    return md

def typechecked(memb):
    """Decorator applicable to functions, methods, properties,
    classes or modules (by explicit call).
    If applied on a module, memb must be a module or a module name contained in sys.modules.
    See pytypes.set_global_typechecked_decorator to apply this on all modules.
    Asserts compatibility of runtime argument and return values of all targeted functions
    and methods w.r.t. PEP 484-style type annotations of these functions and methods."""
    if not pytypes.checking_enabled:
        return memb
    if is_no_type_check(memb):
        return memb
    if type_util._check_as_func(memb):
        return typechecked_func(memb)
    if isclass(memb):
        return typechecked_class(memb)
    if ismodule(memb):
        return typechecked_module(memb, True)
    if memb in sys.modules or memb in _pending_modules:
        return typechecked_module(memb, True)
    return memb

def auto_override_class(cls, force=False, force_recursive=False):
    """Works like auto_override, but is only applicable to classes.
    """
    if not pytypes.checking_enabled:
        return cls
    assert isclass(cls)
    if not force and is_no_type_check(cls):
        return cls
    keys = [key for key in cls.__dict__]
    for key in keys:
        memb = cls.__dict__[key]
        if force_recursive or not is_no_type_check(memb):
            if isfunction(memb) or ismethod(memb) or ismethoddescriptor(memb):
                if util._has_base_method(memb, cls):
                    setattr(cls, key, override(memb))
            elif isclass(memb):
                auto_override_class(memb, force_recursive, force_recursive)
    return cls

def auto_override_module(md, force_recursive=False):
    """Works like auto_override, but is only applicable to modules (by explicit call).
    md must be a module or a module name contained in sys.modules."""
    if not pytypes.checking_enabled:
        return md
    if isinstance(md, str):
        if md in sys.modules:
            md = sys.modules[md]
            if md is None:
                return md
        elif md in _pending_modules:
            _pending_modules[md].append(lambda t: auto_override_module(t, True))
            return md
    assert ismodule(md)
    if md.__name__ in _pending_modules:
        _pending_modules[md.__name__].append(lambda t: auto_override_module(t, True))
    if md.__name__ in _auto_override_modules and _auto_override_modules[md.__name__] == len(md.__dict__):
        return md
    keys = [key for key in md.__dict__]
    for key in keys:
        memb = md.__dict__[key]
        if force_recursive or not is_no_type_check(memb):
            if isclass(memb) and memb.__module__ == md.__name__:
                auto_override_class(memb, force_recursive, force_recursive)
    if not md.__name__ in _pending_modules:
        _auto_override_modules[md.__name__] = len(md.__dict__)
    return md

def auto_override(memb):
    """Decorator applicable to methods, classes or modules (by explicit call).
    If applied on a module, memb must be a module or a module name contained in sys.modules.
    See pytypes.set_global_auto_override_decorator to apply this on all modules.
    Works like override decorator on type annotated methods that actually have a type
    annotated parent method. Has no effect on methods that do not override anything.
    In contrast to plain override decorator, auto_override can be applied easily on
    every method in a class or module.
    In contrast to explicit override decorator, auto_override is not suitable to detect
    typos in spelling of a child method's name. It is only useful to assert compatibility
    of type information (note that return type is contravariant).
    Use pytypes.check_override_at_runtime and pytypes.check_override_at_class_definition_time
    to control whether checks happen at class definition time or at "actual runtime"."""
    if type_util._check_as_func(memb):
        return override(memb, True)
    if isclass(memb):
        return auto_override_class(memb)
    if ismodule(memb):
        return auto_override_module(memb, True)
    if memb in sys.modules or memb in _pending_modules:
        return auto_override_module(memb, True)
    return memb

def no_type_check(memb):
    """Works like typing.no_type_check, but also supports cases where
    typing.no_type_check fails due to AttributeError. This can happen,
    because typing.no_type_check wants to access __no_type_check__, which
    might fail if e.g. a class is using slots or an object doesn't support
    custom attributes."""
    try:
        return typing.no_type_check(memb)
    except AttributeError:
        _not_type_checked.add(memb)
        return memb

def is_no_type_check(memb):
    """Checks if an object was annotated with @no_type_check
    (from typing or pytypes.typechecker)."""
    try:
        return hasattr(memb, '__no_type_check__') and memb.__no_type_check__ or memb in _not_type_checked
    except TypeError:
        return False

def check_argument_types(cllable=None, call_args=None, clss=None, caller_level=0):
    """Can be called from within a function or method to apply typechecking to
    the arguments that were passed in by the caller. Checking is applied w.r.t.
    type hints of the function or method hosting the call to check_argument_types."""
    return _check_caller_type(False, cllable, call_args, clss, caller_level + 1)

def check_return_type(value, cllable=None, clss=None, caller_level=0):
    """Can be called from within a function or method to apply typechecking to
    the value that is going to be returned. Checking is applied w.r.t.
    type hints of the function or method hosting the call to check_return_type."""
    return _check_caller_type(True, cllable, value, clss, caller_level + 1)

def os_walk_pre_35(top, topdown=True, onerror=None, followlinks=False):
    """Pre Python 3.5 implementation of os.walk() that doesn't use scandir."""
    islink, join, isdir = (os.path.islink, os.path.join, os.path.isdir)
    try:
        names = os.listdir(top)
    except OSError as err:
        if onerror is not None:
            onerror(err)
        return
    dirs, nondirs = ([], [])
    for name in names:
        if isdir(join(top, name)):
            dirs.append(name)
        else:
            nondirs.append(name)
    if topdown:
        yield (top, dirs, nondirs)
    for name in dirs:
        new_path = join(top, name)
        if followlinks or not islink(new_path):
            for x in os_walk_pre_35(new_path, topdown, onerror, followlinks):
                yield x
    if not topdown:
        yield (top, dirs, nondirs)

def create_tree(path, depth=DEPTH):
    """Create a directory tree at path with given depth, and NUM_DIRS and
    NUM_FILES at each level."""
    os.mkdir(path)
    for i in range(NUM_FILES):
        filename = os.path.join(path, 'file{0:03}.txt'.format(i))
        with open(filename, 'wb') as f:
            f.write(b'foo')
    if depth <= 1:
        return
    for i in range(NUM_DIRS):
        dirname = os.path.join(path, 'dir{0:03}'.format(i))
        create_tree(dirname, depth - 1)

def get_tree_size(path):
    """Return total size of all files in directory tree at path."""
    size = 0
    try:
        for entry in scandir.scandir(path):
            if entry.is_symlink():
                pass
            elif entry.is_dir():
                size += get_tree_size(os.path.join(path, entry.name))
            else:
                size += entry.stat().st_size
    except OSError:
        pass
    return size

def _broadcast_arg(U, arg, argtype, name):
    """Broadcasts plotting option `arg` to all factors.

    Args:
        U : KTensor
        arg : argument provided by the user
        argtype : expected type for arg
        name : name of the variable, used for error handling

    Returns:
        iterable version of arg of length U.ndim"""
    if arg is None or isinstance(arg, argtype):
        return [arg for _ in range(U.ndim)]
    elif np.iterable(arg):
        if len(arg) != U.ndim:
            raise ValueError('Parameter {} was specified as a sequence of incorrect length. The length must match the number of tensor dimensions (U.ndim={})'.format(name, U.ndim))
        elif not all([isinstance(a, argtype) for a in arg]):
            raise TypeError('Parameter {} specified as a sequence of incorrect type. Expected {}.'.format(name, argtype))
        else:
            return arg
    else:
        raise TypeError('Parameter {} specified as a {}. Expected {}.'.format(name, type(arg), argtype))

def to_wei(number: int, unit: str) -> int:
    """Takes a number of a unit and converts it to wei."""
    if unit.lower() not in units:
        raise ValueError('Unknown unit.  Must be one of {0}'.format('/'.join(units.keys())))
    if is_integer(number) or is_string(number):
        d_number = decimal.Decimal(value=number)
    elif isinstance(number, float):
        d_number = decimal.Decimal(value=str(number))
    elif isinstance(number, decimal.Decimal):
        d_number = number
    else:
        raise TypeError('Unsupported type.  Must be one of integer, float, or string')
    s_number = str(number)
    unit_value = units[unit.lower()]
    if d_number == 0:
        return 0
    if d_number < 1 and '.' in s_number:
        with localcontext() as ctx:
            multiplier = len(s_number) - s_number.index('.') - 1
            ctx.prec = multiplier
            d_number = decimal.Decimal(value=number, context=ctx) * 10 ** multiplier
        unit_value /= 10 ** multiplier
    with localcontext() as ctx:
        ctx.prec = 999
        result_value = decimal.Decimal(value=d_number, context=ctx) * unit_value
    if result_value < MIN_WEI or result_value > MAX_WEI:
        raise ValueError('Resulting wei value must be between 1 and 2**256 - 1')
    return int(result_value)

def to_hex(primitive: Primitives=None, hexstr: HexStr=None, text: str=None) -> HexStr:
    """Auto converts any supported value into its hex representation.
    Trims leading zeros, as defined in:
    https://github.com/ethereum/wiki/wiki/JSON-RPC#hex-value-encoding"""
    if hexstr is not None:
        return HexStr(add_0x_prefix(hexstr.lower()))
    if text is not None:
        return HexStr(encode_hex(text.encode('utf-8')))
    if is_boolean(primitive):
        return HexStr('0x1') if primitive else HexStr('0x0')
    if isinstance(primitive, (bytes, bytearray)):
        return HexStr(encode_hex(primitive))
    elif is_string(primitive):
        raise TypeError('Unsupported type: The primitive argument must be one of: bytes,bytearray, int or bool and not str')
    if is_integer(primitive):
        return HexStr(hex(cast(int, primitive)))
    raise TypeError("Unsupported type: '{0}'.  Must be one of: bool, str, bytes, bytearrayor int.".format(repr(type(primitive))))

def to_int(primitive: Primitives=None, hexstr: HexStr=None, text: str=None) -> int:
    """Converts value to its integer representation.
    Values are converted this way:

     * primitive:

       * bytes, bytearrays: big-endian integer
       * bool: True => 1, False => 0
     * hexstr: interpret hex as integer
     * text: interpret as string of digits, like '12' => 12"""
    if hexstr is not None:
        return int(hexstr, 16)
    elif text is not None:
        return int(text)
    elif isinstance(primitive, (bytes, bytearray)):
        return big_endian_to_int(primitive)
    elif isinstance(primitive, str):
        raise TypeError('Pass in strings with keyword hexstr or text')
    elif isinstance(primitive, (int, bool)):
        return int(primitive)
    else:
        raise TypeError('Invalid type.  Expected one of int/bool/str/bytes/bytearray.  Got {0}'.format(type(primitive)))

def text_if_str(to_type: Callable[..., T], text_or_primitive: Union[bytes, int, str]) -> T:
    """Convert to a type, assuming that strings can be only unicode text (not a hexstr)

    :param to_type function: takes the arguments (primitive, hexstr=hexstr, text=text),
        eg~ to_bytes, to_text, to_hex, to_int, etc
    :param text_or_primitive bytes, str, int: value to convert"""
    if isinstance(text_or_primitive, str):
        return to_type(text=text_or_primitive)
    else:
        return to_type(text_or_primitive)

def hexstr_if_str(to_type: Callable[..., T], hexstr_or_primitive: Union[bytes, int, str]) -> T:
    """Convert to a type, assuming that strings can be only hexstr (not unicode text)

    :param to_type function: takes the arguments (primitive, hexstr=hexstr, text=text),
        eg~ to_bytes, to_text, to_hex, to_int, etc
    :param hexstr_or_primitive bytes, str, int: value to convert"""
    if isinstance(hexstr_or_primitive, str):
        if remove_0x_prefix(hexstr_or_primitive) and (not is_hex(hexstr_or_primitive)):
            raise ValueError('when sending a str, it must be a hex string. Got: {0!r}'.format(hexstr_or_primitive))
        return to_type(hexstr=hexstr_or_primitive)
    else:
        return to_type(hexstr_or_primitive)

def validate_conversion_arguments(to_wrap):
    """Validates arguments for conversion functions.
    - Only a single argument is present
    - Kwarg must be 'primitive' 'hexstr' or 'text'
    - If it is 'hexstr' or 'text' that it is a text type"""
    @functools.wraps(to_wrap)
    def wrapper(*args, **kwargs):
        _assert_one_val(*args, **kwargs)
        if kwargs:
            _validate_supported_kwarg(kwargs)
        if len(args) == 0 and 'primitive' not in kwargs:
            _assert_hexstr_or_text_kwarg_is_text_type(**kwargs)
        return to_wrap(*args, **kwargs)
    return wrapper

def return_arg_type(at_position):
    """Wrap the return value with the result of `type(args[at_position])`"""
    def decorator(to_wrap):
        @functools.wraps(to_wrap)
        def wrapper(*args, **kwargs):
            result = to_wrap(*args, **kwargs)
            ReturnType = type(args[at_position])
            return ReturnType(result)
        return wrapper
    return decorator

def replace_exceptions(old_to_new_exceptions: Dict[Type[BaseException], Type[BaseException]]) -> Callable[..., Any]:
    """Replaces old exceptions with new exceptions to be raised in their place."""
    old_exceptions = tuple(old_to_new_exceptions.keys())
    def decorator(to_wrap: Callable[..., Any]) -> Callable[..., Any]:
        @functools.wraps(to_wrap)
        def wrapper(*args: Iterable[Any], **kwargs: Dict[str, Any]) -> Callable[..., Any]:
            try:
                return to_wrap(*args, **kwargs)
            except old_exceptions as err:
                try:
                    raise old_to_new_exceptions[type(err)] from err
                except KeyError:
                    raise TypeError('could not look up new exception to use for %r' % err) from err
        return wrapper
    return decorator

def is_hex_address(value: Any) -> bool:
    """Checks if the given string of text type is an address in hexadecimal encoded form."""
    if not is_text(value):
        return False
    elif not is_hex(value):
        return False
    else:
        unprefixed = remove_0x_prefix(value)
        return len(unprefixed) == 40

def is_binary_address(value: Any) -> bool:
    """Checks if the given string is an address in raw bytes form."""
    if not is_bytes(value):
        return False
    elif len(value) != 20:
        return False
    else:
        return True

def is_address(value: Any) -> bool:
    """Checks if the given string in a supported value
    is an address in any of the known formats."""
    if is_checksum_formatted_address(value):
        return is_checksum_address(value)
    elif is_hex_address(value):
        return True
    elif is_binary_address(value):
        return True
    else:
        return False

def to_normalized_address(value: AnyStr) -> HexAddress:
    """Converts an address to its normalized hexadecimal representation."""
    try:
        hex_address = hexstr_if_str(to_hex, value).lower()
    except AttributeError:
        raise TypeError('Value must be any string, instead got type {}'.format(type(value)))
    if is_address(hex_address):
        return HexAddress(hex_address)
    else:
        raise ValueError('Unknown format {}, attempted to normalize to {}'.format(value, hex_address))

def is_normalized_address(value: Any) -> bool:
    """Returns whether the provided value is an address in its normalized form."""
    if not is_address(value):
        return False
    else:
        return value == to_normalized_address(value)

def is_canonical_address(address: Any) -> bool:
    """Returns `True` if the `value` is an address in its canonical form."""
    if not is_bytes(address) or len(address) != 20:
        return False
    return address == to_canonical_address(address)

def is_same_address(left: AnyAddress, right: AnyAddress) -> bool:
    """Checks if both addresses are same or not."""
    if not is_address(left) or not is_address(right):
        raise ValueError('Both values must be valid addresses')
    else:
        return to_normalized_address(left) == to_normalized_address(right)

def to_checksum_address(value: AnyStr) -> ChecksumAddress:
    """Makes a checksum address given a supported format."""
    norm_address = to_normalized_address(value)
    address_hash = encode_hex(keccak(text=remove_0x_prefix(norm_address)))
    checksum_address = add_0x_prefix(''.join((norm_address[i].upper() if int(address_hash[i], 16) > 7 else norm_address[i] for i in range(2, 42))))
    return ChecksumAddress(HexAddress(checksum_address))

def get_msi_token(resource, port=50342, msi_conf=None):
    """Get MSI token if MSI_ENDPOINT is set.

    IF MSI_ENDPOINT is not set, will try legacy access through 'http://localhost:{}/oauth2/token'.format(port).

    If msi_conf is used, must be a dict of one key in ["client_id", "object_id", "msi_res_id"]

    :param str resource: The resource where the token would be use.
    :param int port: The port if not the default 50342 is used. Ignored if MSI_ENDPOINT is set.
    :param dict[str,str] msi_conf: msi_conf if to request a token through a User Assigned Identity (if not specified, assume System Assigned)"""
    request_uri = os.environ.get('MSI_ENDPOINT', 'http://localhost:{}/oauth2/token'.format(port))
    payload = {'resource': resource}
    if msi_conf:
        if len(msi_conf) > 1:
            raise ValueError('{} are mutually exclusive'.format(list(msi_conf.keys())))
        payload.update(msi_conf)
    try:
        result = requests.post(request_uri, data=payload, headers={'Metadata': 'true'})
        _LOGGER.debug('MSI: Retrieving a token from %s, with payload %s', request_uri, payload)
        result.raise_for_status()
    except Exception as ex:
        _LOGGER.warning("MSI: Failed to retrieve a token from '%s' with an error of '%s'. This could be caused by the MSI extension not yet fully provisioned.", request_uri, ex)
        raise
    token_entry = result.json()
    return (token_entry['token_type'], token_entry['access_token'], token_entry)

def get_msi_token_webapp(resource):
    """Get a MSI token from inside a webapp or functions.

    Env variable will look like:

    - MSI_ENDPOINT = http://127.0.0.1:41741/MSI/token/
    - MSI_SECRET = 69418689F1E342DD946CB82994CDA3CB"""
    try:
        msi_endpoint = os.environ['MSI_ENDPOINT']
        msi_secret = os.environ['MSI_SECRET']
    except KeyError as err:
        err_msg = '{} required env variable was not found. You might need to restart your app/function.'.format(err)
        _LOGGER.critical(err_msg)
        raise RuntimeError(err_msg)
    request_uri = '{}/?resource={}&api-version=2017-09-01'.format(msi_endpoint, resource)
    headers = {'secret': msi_secret}
    err = None
    try:
        result = requests.get(request_uri, headers=headers)
        _LOGGER.debug('MSI: Retrieving a token from %s', request_uri)
        if result.status_code != 200:
            err = result.text
        if 'ExceptionMessage' in result.text:
            err = result.text
    except Exception as ex:
        err = str(ex)
    if err:
        err_msg = "MSI: Failed to retrieve a token from '{}' with an error of '{}'.".format(request_uri, err)
        _LOGGER.critical(err_msg)
        raise RuntimeError(err_msg)
    _LOGGER.debug('MSI: token retrieved')
    token_entry = result.json()
    return (token_entry['token_type'], token_entry['access_token'], token_entry)

def _validate(url):
    """Validate a url.

    :param str url: Polling URL extracted from response header.
    :raises: ValueError if URL has no scheme or host."""
    if url is None:
        return
    parsed = urlparse(url)
    if not parsed.scheme or not parsed.netloc:
        raise ValueError('Invalid URL header')

def _get_header_url(response, header_name):
    """Get a URL from a header requests.

    :param requests.Response response: REST call response.
    :param str header_name: Header name.
    :returns: URL if not None AND valid, None otherwise"""
    url = response.headers.get(header_name)
    try:
        _validate(url)
    except ValueError:
        return None
    else:
        return url

def register_rp_hook(r, *args, **kwargs):
    """This is a requests hook to register RP automatically.

    You should not use this command manually, this is added automatically
    by the SDK.

    See requests documentation for details of the signature of this function.
    http://docs.python-requests.org/en/master/user/advanced/#event-hooks"""
    if r.status_code == 409 and 'msrest' in kwargs:
        rp_name = _check_rp_not_registered_err(r)
        if rp_name:
            session = kwargs['msrest']['session']
            url_prefix = _extract_subscription_url(r.request.url)
            if not _register_rp(session, url_prefix, rp_name):
                return
            req = r.request
            if 'x-ms-client-request-id' in req.headers:
                req.headers['x-ms-client-request-id'] = str(uuid.uuid1())
            return session.send(req)

def _extract_subscription_url(url):
    """Extract the first part of the URL, just after subscription:
    https://management.azure.com/subscriptions/00000000-0000-0000-0000-000000000000/"""
    match = re.match('.*/subscriptions/[a-f0-9-]+/', url, re.IGNORECASE)
    if not match:
        raise ValueError('Unable to extract subscription ID from URL')
    return match.group(0)

def set_backend(backend_name: str):
    """Sets backend (local or aws)"""
    global _backend, _backend_name
    _backend_name = backend_name
    assert not ncluster_globals.task_launched, 'Not allowed to change backend after launching a task (this pattern is error-prone)'
    if backend_name == 'aws':
        _backend = aws_backend
    elif backend_name == 'local':
        _backend = local_backend
    else:
        assert False, f'Unknown backend {backend_name}'
    ncluster_globals.LOGDIR_ROOT = _backend.LOGDIR_ROOT

def get_vpc_dict():
    """Returns dictionary of named VPCs {name: vpc}

    Assert fails if there's more than one VPC with same name."""
    client = get_ec2_client()
    response = client.describe_vpcs()
    assert is_good_response(response)
    result = OrderedDict()
    ec2 = get_ec2_resource()
    for vpc_response in response['Vpcs']:
        key = get_name(vpc_response.get('Tags', []))
        if not key or key == EMPTY_NAME:
            continue
        if key in result:
            util.log(f'Warning: Duplicate VPC group {key} in {response}')
            if DUPLICATE_CHECKING:
                assert False
        result[key] = ec2.Vpc(vpc_response['VpcId'])
    return result

def get_default_vpc():
    """Return default VPC or none if not present"""
    ec2 = get_ec2_resource()
    for vpc in ec2.vpcs.all():
        if vpc.is_default:
            return vpc

def get_subnet_dict():
    """Returns dictionary of "availability zone" -> subnet for current VPC."""
    subnet_dict = {}
    vpc = get_vpc()
    for subnet in vpc.subnets.all():
        zone = subnet.availability_zone
        assert zone not in subnet_dict, 'More than one subnet in %s, why?' % (zone,)
        subnet_dict[zone] = subnet
    return subnet_dict

def get_keypair_dict():
    """Returns dictionary of {keypairname: keypair}"""
    client = get_ec2_client()
    response = client.describe_key_pairs()
    assert is_good_response(response)
    result = {}
    ec2 = get_ec2_resource()
    for keypair in response['KeyPairs']:
        keypair_name = keypair.get('KeyName', '')
        if keypair_name in result:
            util.log(f'Warning: Duplicate key {keypair_name}')
        if DUPLICATE_CHECKING:
            assert keypair_name not in result, 'Duplicate key ' + keypair_name
        result[keypair_name] = ec2.KeyPair(keypair_name)
