def _escapeCharacters(tag):
    """non-recursively escape underlines and asterisks
    in the tag"""
    for i, c in enumerate(tag.contents):
        if type(c) != bs4.element.NavigableString:
            continue
        c.replace_with(_escapeCharSub('\\\\\\1', c))

def _breakRemNewlines(tag):
    """non-recursively break spaces and remove newlines in the tag"""
    for i, c in enumerate(tag.contents):
        if type(c) != bs4.element.NavigableString:
            continue
        c.replace_with(re.sub(' {2,}', ' ', c).replace('\n', ''))

def int32(x):
    """Return a signed or unsigned int"""
    if x > 4294967295:
        raise OverflowError
    if x > 2147483647:
        x = int(4294967296 - x)
        if x < 2147483648:
            return -x
        else:
            return -2147483648
    return x

def _get_args_and_errors(self, minuit=None, args=None, errors=None):
    """consistent algorithm to get argument and errors
    1) get it from minuit if minuit is available
    2) if not get it from args and errors
    2.1) if args is dict parse it.
    3) if all else fail get it from self.last_arg"""
    ret_arg = None
    ret_error = None
    if minuit is not None:
        ret_arg = minuit.args
        ret_error = minuit.errors
        return (ret_arg, ret_error)
    if args is not None:
        if isinstance(args, dict):
            ret_arg = parse_arg(self, args)
        else:
            ret_arg = args
    else:
        ret_arg = self.last_arg
    if errors is not None:
        ret_error = errors
    return (ret_arg, ret_error)

def draw_compare(f, arg, edges, data, errors=None, ax=None, grid=True, normed=False, parts=False):
    """TODO: this needs to be rewritten"""
    from matplotlib import pyplot as plt
    ax = plt.gca() if ax is None else ax
    arg = parse_arg(f, arg, 1) if isinstance(arg, dict) else arg
    x = (edges[:-1] + edges[1:]) / 2.0
    bw = np.diff(edges)
    yf = vector_apply(f, x, *arg)
    total = np.sum(data)
    if normed:
        ax.errorbar(x, data / bw / total, errors / bw / total, fmt='.b', zorder=0)
        ax.plot(x, yf, 'r', lw=2, zorder=2)
    else:
        ax.errorbar(x, data, errors, fmt='.b', zorder=0)
        ax.plot(x, yf * bw, 'r', lw=2, zorder=2)
    if parts:
        if not hasattr(f, 'eval_parts'):
            warn(RuntimeWarning('parts is set to True but function does not have eval_parts method'))
        else:
            scale = bw if not normed else 1.0
            parts_val = list()
            for tx in x:
                val = f.eval_parts(tx, *arg)
                parts_val.append(val)
            py = zip(*parts_val)
            for y in py:
                tmpy = np.array(y)
                ax.plot(x, tmpy * scale, lw=2, alpha=0.5)
    plt.grid(grid)
    return (x, yf, data)

def gauss_pdf(x, mu, sigma):
    """Normalized Gaussian"""
    return 1 / np.sqrt(2 * np.pi) / sigma * np.exp(-(x - mu) ** 2 / 2.0 / sigma ** 2)

def get_kwargs(kwargs):
