def feincms_render_region(context, feincms_object, region, request=None, classes='', wrapper=True):
    """{% feincms_render_region feincms_page "main" request %}

    Support for rendering Page without some regions especialy for modals
    this feature is driven by context variable"""
    if not feincms_object:
        return ''
    if not context.get('standalone', False) or region in STANDALONE_REGIONS:
        region_content = ''.join((_render_content(content, request=request, context=context) for content in getattr(feincms_object.content, region)))
    else:
        region_content = ''
    if not wrapper:
        return region_content
    _classes = 'leonardo-region leonardo-region-%(region)s %(classes)s' % {'region': region, 'classes': classes}
    _id = '%(region)s-%(id)s' % {'id': feincms_object.id, 'region': region}
    return '<div class="%(classes)s" id=%(id)s>%(content)s</div>' % {'id': _id, 'classes': _classes, 'content': region_content}

