def get_grouped_widgets(feincms_object, request=None):
    """returns tuple(choices, grouped, ungrouped)

    requires feincms_object for getting content types

    request optionaly for checking permissions, but not required

    grouped = {'web': (id, label, icon)}"""
    grouped = {}
    ungrouped = []
    choices = []
    for ct in feincms_object._feincms_content_types:
        opts = ct._meta
        if request and request.user:
            from django.contrib.auth import get_permission_codename
            perm = opts.app_label + '.' + get_permission_codename('add', opts)
            if not request.user.has_perm(perm):
                continue
        ct_info = ('.'.join([ct._meta.app_label, ct.__name__.lower()]), ct._meta.verbose_name, ct.get_widget_icon)
        if hasattr(ct, 'optgroup'):
            if ct.optgroup in grouped:
                grouped[ct.optgroup].append(ct_info)
            else:
                grouped[ct.optgroup] = [ct_info]
        else:
            ungrouped.append(ct_info)
        choices.append(ct_info)
    return (choices, grouped, ungrouped)

def render_region(widget=None, request=None, view=None, page=None, region=None):
    """returns rendered content
    this is not too clear and little tricky,
    because external apps needs calling process method"""
    if not isinstance(request, dict):
        request.query_string = None
        request.method = 'GET'
    if not hasattr(request, '_feincms_extra_context'):
        request._feincms_extra_context = {}
    leonardo_page = widget.parent if widget else page
    render_region = widget.region if widget else region
    for fn in reversed(list(leonardo_page.request_processors.values())):
        try:
            r = fn(leonardo_page, request)
        except:
            pass
    contents = {}
    for content in leonardo_page.content.all_of_type(tuple(leonardo_page._feincms_content_types_with_process)):
        try:
            r = content.process(request, view=view)
        except:
            pass
        else:
            if not isinstance(r, six.string_types):
                r.render()
                contents[content.fe_identifier] = getattr(r, 'content', r)
            else:
                contents[content.fe_identifier] = r
    from leonardo.templatetags.leonardo_tags import _render_content
    region_content = ''.join((contents[content.fe_identifier] if content.fe_identifier in contents else _render_content(content, request=request, context={}) for content in getattr(leonardo_page.content, render_region)))
    return region_content

def install_package(package, upgrade=True, target=None):
    """Install a package on PyPi. Accepts pip compatible package strings.

    Return boolean if install successful."""
    with INSTALL_LOCK:
        if check_package_exists(package, target):
            return True
        _LOGGER.info('Attempting install of %s', package)
        args = [sys.executable, '-m', 'pip', 'install', '--quiet', package]
        if upgrade:
            args.append('--upgrade')
        if target:
            args += ['--target', os.path.abspath(target)]
        try:
            return subprocess.call(args) == 0
        except subprocess.SubprocessError:
            _LOGGER.exception('Unable to install pacakge %s', package)
            return False

def check_package_exists(package, lib_dir):
    """Check if a package is installed globally or in lib_dir.

    Returns True when the requirement is met.
    Returns False when the package is not installed or doesn't meet req."""
    try:
        req = pkg_resources.Requirement.parse(package)
    except ValueError:
        req = pkg_resources.Requirement.parse(urlparse(package).fragment)
    if lib_dir is not None:
        if any((dist in req for dist in pkg_resources.find_distributions(lib_dir))):
            return True
    return any((dist in req for dist in pkg_resources.working_set))

def post_process_fieldsets(context, fieldset):
    """Removes a few fields from FeinCMS admin inlines, those being
    ``id``, ``DELETE`` and ``ORDER`` currently.
    Additionally, it ensures that dynamically added fields (i.e.
    ``ApplicationContent``'s ``admin_fields`` option) are shown."""
    if fieldset.model_admin.fieldsets:
        return fieldset
    fields_to_include = set(fieldset.form.fields.keys())
    for f in ('id', 'DELETE', 'ORDER'):
        fields_to_include.discard(f)
    def _filter_recursive(fields):
        ret = []
        for f in fields:
            if isinstance(f, (list, tuple)):
                sub = _filter_recursive(f)
                if sub:
                    ret.append(sub)
            elif f in fields_to_include:
                ret.append(f)
                fields_to_include.discard(f)
        return ret
    new_fields = _filter_recursive(fieldset.fields)
    for f in fields_to_include:
        new_fields.append(f)
    if context.get('request'):
        new_fields.extend(list(fieldset.model_admin.get_readonly_fields(context.get('request'), context.get('original'))))
    fieldset.fields = new_fields
    return ''

def staff_member(view_func):
    """Performs user authentication check.

    Similar to Django's `login_required` decorator, except that this throws
    :exc:`~leonardo.exceptions.NotAuthenticated` exception if the user is not
    signed-in."""
    @functools.wraps(view_func, assigned=available_attrs(view_func))
    def dec(request, *args, **kwargs):
        if request.user.is_staff:
            return view_func(request, *args, **kwargs)
        raise PermissionDenied(_("You haven't permissions to do this action."))
    return dec

def _decorate_urlconf(urlpatterns, decorator=require_auth, *args, **kwargs):
    """Decorate all urlpatterns by specified decorator"""
    if isinstance(urlpatterns, (list, tuple)):
        for pattern in urlpatterns:
            if getattr(pattern, 'callback', None):
                pattern._callback = decorator(pattern.callback, *args, **kwargs)
            if getattr(pattern, 'url_patterns', []):
                _decorate_urlconf(pattern.url_patterns, decorator, *args, **kwargs)
    elif getattr(urlpatterns, 'callback', None):
        urlpatterns._callback = decorator(urlpatterns.callback, *args, **kwargs)

def input(self, **kwargs):
    """main override which append variables import to all scss content
    """
    with_variables = None
    context = kwargs.get('context', {})
    if context.get('leonardo_page', None):
        try:
            context['leonardo_page']['theme']
            context['leonardo_page']['color_scheme']
        except Exception as e:
            LOG.exception(str(e))
        else:
            with_variables = '\n            @import "/themes/{}/{}/_variables";\n            {}\n            '.format(context['leonardo_page']['theme']['name'], context['leonardo_page']['color_scheme']['name'], self.content)
    return self.compiler.compile_string(with_variables or self.content, filename=self.filename)

def hunks(self, forced=False, context=None):
    """The heart of content parsing, iterates over the
    list of split contents and looks at its kind
    to decide what to do with it. Should yield a
    bunch of precompiled and/or rendered hunks."""
    enabled = settings.COMPRESS_ENABLED or forced
    for kind, value, basename, elem in self.split_contents():
        precompiled = False
        attribs = self.parser.elem_attribs(elem)
        charset = attribs.get('charset', self.charset)
        options = {'method': METHOD_INPUT, 'elem': elem, 'kind': kind, 'basename': basename, 'charset': charset, 'context': context}
        if kind == SOURCE_FILE:
            options = dict(options, filename=value)
            value = self.get_filecontent(value, charset)
        if self.precompiler_mimetypes:
            precompiled, value = self.precompile(value, **options)
        if enabled:
            yield self.filter(value, self.cached_filters, **options)
        elif precompiled:
            if CssAbsoluteFilter in self.cached_filters:
                value = self.filter(value, [CssAbsoluteFilter], **options)
            yield self.handle_output(kind, value, forced=True, basename=basename)
        else:
            yield self.parser.elem_str(elem)

def output(self, mode='file', forced=False, context=None):
    """The general output method, override in subclass if you need to do
    any custom modification. Calls other mode specific methods or simply
    returns the content directly."""
    output = '\n'.join(self.filter_input(forced, context=context))
    if not output:
        return ''
    if settings.COMPRESS_ENABLED or forced:
        filtered_output = self.filter_output(output)
        return self.handle_output(mode, filtered_output, forced)
    return output

def precompile(self, content, kind=None, elem=None, filename=None, charset=None, **kwargs):
    """Processes file using a pre compiler.
    This is the place where files like coffee script are processed."""
    if not kind:
        return (False, content)
    attrs = self.parser.elem_attribs(elem)
    mimetype = attrs.get('type', None)
    if mimetype is None:
        return (False, content)
    filter_or_command = self.precompiler_mimetypes.get(mimetype)
    if filter_or_command is None:
        if mimetype in ('text/css', 'text/javascript'):
            return (False, content)
        raise CompressorError("Couldn't find any precompiler in COMPRESS_PRECOMPILERS setting for mimetype '%s'." % mimetype)
    mod_name, cls_name = get_mod_func(filter_or_command)
    try:
        mod = import_module(mod_name)
    except (ImportError, TypeError):
        filter = CachedCompilerFilter(content=content, filter_type=self.type, filename=filename, charset=charset, command=filter_or_command, mimetype=mimetype)
        return (True, filter.input(**kwargs))
    try:
        precompiler_class = getattr(mod, cls_name)
    except AttributeError:
        raise FilterDoesNotExist('Could not find "%s".' % filter_or_command)
    filter = precompiler_class(content, attrs=attrs, filter_type=self.type, charset=charset, filename=filename, **kwargs)
    return (True, filter.input(**kwargs))

def thumbnail(parser, token):
