def register_widgets():
    """Register all collected widgets from settings
    WIDGETS = [('mymodule.models.MyWidget', {'mykwargs': 'mykwarg'})]
    WIDGETS = ['mymodule.models.MyWidget', MyClass]"""
    Page.create_content_type(ApplicationWidget, APPLICATIONS=settings.APPLICATION_CHOICES)
    for _optgroup, _widgets in six.iteritems(settings.WIDGETS):
        optgroup = _optgroup if _optgroup != 'ungrouped' else None
        for widget in _widgets:
            kwargs = {'optgroup': optgroup}
            if isinstance(widget, six.string_types):
                try:
                    WidgetCls = get_class_from_string(widget)
                except:
                    exc_info = sys.exc_info()
                    raise six.reraise(*exc_info)
            elif isinstance(widget, tuple):
                try:
                    WidgetCls = get_class_from_string(widget[0])
                    if len(widget) > 1:
                        kwargs.update(widget[1])
                except Exception as e:
                    raise Exception('%s: %s' % (mod, e))
            else:
                WidgetCls = widget
            Page.create_content_type(WidgetCls, **kwargs)

def handle_uploaded_file(file, folder=None, is_public=True):
    """handle uploaded file to folder
    match first media type and create media object and returns it

    file: File object
    folder: str or Folder isinstance
    is_public: boolean"""
    _folder = None
    if folder and isinstance(folder, Folder):
        _folder = folder
    elif folder:
        _folder, folder_created = Folder.objects.get_or_create(name=folder)
    for cls in MEDIA_MODELS:
        if cls.matches_file_type(file.name):
            obj, created = cls.objects.get_or_create(original_filename=file.name, file=file, folder=_folder, is_public=is_public)
            if created:
                return obj
    return None

def serve_protected_file(request, path):
    """Serve protected files to authenticated users with read permissions."""
    path = path.rstrip('/')
    try:
        file_obj = File.objects.get(file=path)
    except File.DoesNotExist:
        raise Http404('File not found %s' % path)
    if not file_obj.has_read_permission(request):
        if settings.DEBUG:
            raise PermissionDenied
        else:
            raise Http404('File not found %s' % path)
    return server.serve(request, file_obj=file_obj.file, save_as=False)

def serve_protected_thumbnail(request, path):
    """Serve protected thumbnails to authenticated users.
    If the user doesn't have read permissions, redirect to a static image."""
    source_path = thumbnail_to_original_filename(path)
    if not source_path:
        raise Http404('File not found')
    try:
        file_obj = File.objects.get(file=source_path)
    except File.DoesNotExist:
        raise Http404('File not found %s' % path)
    if not file_obj.has_read_permission(request):
        if settings.DEBUG:
            raise PermissionDenied
        else:
            raise Http404('File not found %s' % path)
    try:
        thumbnail = ThumbnailFile(name=path, storage=file_obj.file.thumbnail_storage)
        return thumbnail_server.serve(request, thumbnail, save_as=False)
    except Exception:
        raise Http404('File not found %s' % path)

def permalink(func):
    """Decorator that calls app_reverse()
    Use this instead of standard django.db.models.permalink if you want to
    integrate the model through ApplicationContent. The wrapped function
    must return 4 instead of 3 arguments::
        class MyModel(models.Model):
            @appmodels.permalink
            def get_absolute_url(self):
                return ('myapp.urls', 'model_detail', (), {'slug': self.slug})"""
    def inner(*args, **kwargs):
        return app_reverse(*func(*args, **kwargs))
    return wraps(func)(inner)

def add_page_if_missing(request):
    """Returns ``feincms_page`` for request."""
    try:
        page = Page.objects.for_request(request, best_match=True)
        return {'leonardo_page': page, 'feincms_page': page}
    except Page.DoesNotExist:
        return {}

def render_in_page(request, template):
    """return rendered template in standalone mode or ``False``
    """
    from leonardo.module.web.models import Page
    page = request.leonardo_page if hasattr(request, 'leonardo_page') else Page.objects.filter(parent=None).first()
    if page:
        try:
            slug = request.path_info.split('/')[-2:-1][0]
        except KeyError:
            slug = None
        try:
            body = render_to_string(template, RequestContext(request, {'request_path': request.path, 'feincms_page': page, 'slug': slug, 'standalone': True}))
            response = http.HttpResponseNotFound(body, content_type=CONTENT_TYPE)
        except TemplateDoesNotExist:
            response = False
        return response
    return False

def server_error(request, template_name='500.html'):
    """500 error handler.

    Templates: :template:`500.html`
    Context: None"""
    response = render_in_page(request, template_name)
    if response:
        return response
    try:
        template = loader.get_template(template_name)
    except TemplateDoesNotExist:
        return http.HttpResponseServerError('<h1>Server Error (500)</h1>', content_type='text/html')
    return http.HttpResponseServerError(template.render(Context({})))

def bad_request(request, template_name='400.html'):
    """400 error handler.

    Templates: :template:`400.html`
    Context: None"""
    response = render_in_page(request, template_name)
    if response:
        return response
    try:
        template = loader.get_template(template_name)
    except TemplateDoesNotExist:
        return http.HttpResponseBadRequest('<h1>Bad Request (400)</h1>', content_type='text/html')
    return http.HttpResponseBadRequest(template.render(Context({})))

def permission_denied(request, template_name='403.html'):
    """Permission denied (403) handler.

    Templates: :template:`403.html`
    Context: None

    If the template does not exist, an Http403 response containing the text
    "403 Forbidden" (as per RFC 2616) will be returned."""
    response = render_in_page(request, template_name)
    if response:
        return response
    try:
        template = loader.get_template(template_name)
    except TemplateDoesNotExist:
        return http.HttpResponseForbidden('<h1>403 Forbidden</h1>', content_type='text/html')
    return http.HttpResponseForbidden(template.render(RequestContext(request)))

