def frontendediting_request_processor(page, request):
    """Sets the frontend editing state in the cookie depending on the
    ``frontend_editing`` GET parameter and the user's permissions."""
    if 'frontend_editing' not in request.GET:
        return
    response = HttpResponseRedirect(request.path)
    if request.user.has_module_perms('page'):
        if 'frontend_editing' in request.GET:
            try:
                enable_fe = int(request.GET['frontend_editing']) > 0
            except ValueError:
                enable_fe = False
            if enable_fe:
                response.set_cookie(str('frontend_editing'), enable_fe)
                clear_cache()
            else:
                response.delete_cookie(str('frontend_editing'))
                clear_cache()
    else:
        response.delete_cookie(str('frontend_editing'))
    return response

def flatten_template_loaders(templates):
    """Given a collection of template loaders, unwrap them into one flat iterable.

    :param templates: template loaders to unwrap
    :return: template loaders as an iterable of strings.
    :rtype: generator expression"""
    for loader in templates:
        if not isinstance(loader, string_types):
            for subloader in flatten_template_loaders(loader):
                yield subloader
        else:
            yield loader

def get_current_context_id():
    """Identifis which context it is (greenlet, stackless, or thread).

    :returns: the identifier of the current context."""
    global get_current_context_id
    if greenlet is not None:
        if stackless is None:
            get_current_context_id = greenlet.getcurrent
            return greenlet.getcurrent()
        return (greenlet.getcurrent(), stackless.getcurrent())
    elif stackless is not None:
        get_current_context_id = stackless.getcurrent
        return stackless.getcurrent()
    get_current_context_id = _thread.get_ident
    return _thread.get_ident()

def append_docstring(docstring, *lines):
    """Appends the ``docstring`` with given ``lines``::

        function.__doc__ = append_docstring(
            function.__doc__,
            '.. note::'
            '',
            '   Appended docstring!'
        )

    :param docstring: a docstring to be appended
    :param \\*lines: lines of trailing docstring
    :returns: new docstring which is appended
    :rtype: :class:`str`"""
    shallowest = get_minimum_indent(docstring)
    appender = []
    for line in lines:
        appender.append('\n')
        if line.strip():
            appender.append(shallowest)
            appender.append(line)
    return docstring + ''.join(appender)

def write_header(term='bash', tree_dir=None, name=None):
    """Write proper file header in a given shell format

    Parameters:
        term (str):
            The type of shell header to write, can be "bash", "tsch", or "modules"
        tree_dir (str):
            The path to this repository
        name (str):
            The name of the configuration

    Returns:
        A string header to insert"""
    assert term in ['bash', 'tsch', 'modules'], 'term must be either bash, tsch, or module'
    product_dir = tree_dir.rstrip('/')
    base = 'export' if term == 'bash' else 'setenv'
    if term != 'modules':
        hdr = '# Set up tree/{0} for {1}
{2} TREE_DIR {3}
{2} TREE_VER {1}
{2} PATH $TREE_DIR/bin:$PATH
{2} PYTHONPATH $TREE_DIR/python:$PYTHONPATH
                '.format(name, term, base, product_dir)
    else:
        hdr = '#%Module1.0
proc ModulesHelp {{ }} {{
    global product version
    puts stderr "This module adds $product/$version to various paths"
}}
set name tree
set product tree
set version {1}
conflict $product
module-whatis "Sets up $product/$version in your environment"

set PRODUCT_DIR {0}
setenv [string toupper $product]_DIR $PRODUCT_DIR
setenv [string toupper $product]_VER $version
prepend-path PATH $PRODUCT_DIR/bin
prepend-path PYTHONPATH $PRODUCT_DIR/python

                '.format(product_dir, name)
    return hdr.strip()

def copy_modules(filespath=None, modules_path=None, verbose=None):
    """Copy over the tree module files into your path"""
    if not modules_path:
        modulepath = os.getenv('MODULEPATH')
        if not modulepath:
            modules_path = input('Enter the root path for your module files:')
        else:
            split_mods = modulepath.split(':')
            if len(split_mods) > 1:
                if verbose:
                    print('Multiple module paths found.  Finding all that contain a tree directory.')
                for mfile in split_mods:
                    if os.path.exists(os.path.join(mfile, 'tree')):
                        copy_modules(filespath=filespath, modules_path=mfile, verbose=verbose)
                    else:
                        return
            else:
                modules_path = split_mods[0]
    tree_mod = os.path.join(modules_path, 'tree')
    if not os.path.isdir(tree_mod):
        os.makedirs(tree_mod)
    if verbose:
        print('Copying modules from etc/ into {0}'.format(tree_mod))
    module_files = glob.glob(os.path.join(filespath, '*.module'))
    for mfile in module_files:
        base = os.path.splitext(os.path.basename(mfile))[0]
        tree_out = os.path.join(tree_mod, base)
        shutil.copy2(mfile, tree_out)
    version = os.path.join(filespath, '.version')
    if os.path.isfile(version):
        shutil.copy2(version, tree_mod)

def _indent(text, level=1):
    """Does a proper indenting for Sphinx rst"""
    prefix = ' ' * (4 * level)
    def prefixed_lines():
        for line in text.splitlines(True):
            yield (prefix + line if line.strip() else line)
    return ''.join(prefixed_lines())

