    :param file_name: path/to/file.pickle"""
    from pickle import UnpicklingError
    _python3 = True
    try:
        import cPickle as pickle
        _python3 = False
    except ImportError:
        import pickle
    try:
        if _python3:
            strcl = str
            p3kw = dict(encoding='latin1')
