def parse(date, dayfirst=True):
    """Parse a `date` into a `FlexiDate`.

    @param date: the date to parse - may be a string, datetime.date,
    datetime.datetime or FlexiDate.

    TODO: support for quarters e.g. Q4 1980 or 1954 Q3
    TODO: support latin stuff like M.DCC.LIII
    TODO: convert '-' to '?' when used that way
        e.g. had this date [181-]"""
    if not date:
        return None
    if isinstance(date, FlexiDate):
        return date
    if isinstance(date, int):
        return FlexiDate(year=date)
    elif isinstance(date, datetime.datetime):
        parser = PythonDateTimeParser()
        return parser.parse(date)
    elif isinstance(date, datetime.date):
        parser = PythonDateParser()
        return parser.parse(date)
    else:
        parser = DateutilDateParser()
        out = parser.parse(date, **{'dayfirst': dayfirst})
        if out is not None:
            return out
        val = 'UNPARSED: %s' % date
        val = val.encode('ascii', 'ignore')
        return FlexiDate(qualifier=val)

def potcar_spec(filename):
    """Returns a dictionary specifying the pseudopotentials contained in a POTCAR file.

    Args:
        filename (Str): The name of the POTCAR file to process.

    Returns:
        (Dict): A dictionary of pseudopotential filename: dataset pairs, e.g.
                { 'Fe_pv': 'PBE_54', 'O', 'PBE_54' }"""
    p_spec = {}
    with open(filename, 'r') as f:
        potcars = re.split('(End of Dataset\n)', f.read())
    potcar_md5sums = [md5sum(''.join(pair)) for pair in zip(potcars[::2], potcars[1:-1:2])]
    for this_md5sum in potcar_md5sums:
        for ps in potcar_sets:
            for p, p_md5sum in potcar_md5sum_data[ps].items():
                if this_md5sum == p_md5sum:
                    p_spec[p] = ps
    if len(p_spec) != len(potcar_md5sums):
        raise ValueError('One or more POTCARs did not have matching md5 hashes')
    return p_spec

def delta_E(reactants, products, check_balance=True):
    """Calculate the change in energy for reactants --> products.

    Args:
        reactants (list(vasppy.Calculation): A list of vasppy.Calculation objects. The initial state.
        products  (list(vasppy.Calculation): A list of vasppy.Calculation objects. The final state.
        check_balance (bool:optional): Check that the reaction stoichiometry is balanced. Default: True.

    Returns:
        (float) The change in energy."""
    if check_balance:
        if delta_stoichiometry(reactants, products) != {}:
            raise ValueError('reaction is not balanced: {}'.format(delta_stoichiometry(reactants, products)))
    return sum([r.energy for r in products]) - sum([r.energy for r in reactants])

def delta_stoichiometry(reactants, products):
    """Calculate the change in stoichiometry for reactants --> products.

    Args:
        reactants (list(vasppy.Calculation): A list of vasppy.Calculation objects. The initial state.
        products  (list(vasppy.Calculation): A list of vasppy.Calculation objects. The final state.

    Returns:
        (Counter): The change in stoichiometry."""
    totals = Counter()
    for r in reactants:
        totals.update((r * -1.0).stoichiometry)
    for p in products:
        totals.update(p.stoichiometry)
    to_return = {}
    for c in totals:
        if totals[c] != 0:
            to_return[c] = totals[c]
    return to_return

def describe_filter(f):
    """Return text describing the logging filter `f`."""
    if f.__class__ is logging.Filter:
        return 'name=%r' % f.name
    return repr(f)

def describe_handler(h):
    """Yield one or more lines describing the logging handler `h`."""
    t = h.__class__
    format = handler_formats.get(t)
    if format is not None:
        yield (format % h.__dict__)
    else:
        yield repr(h)
    level = getattr(h, 'level', logging.NOTSET)
    if level != logging.NOTSET:
        yield ('  Level ' + logging.getLevelName(level))
    for f in getattr(h, 'filters', ()):
        yield ('  Filter %s' % describe_filter(f))
    formatter = getattr(h, 'formatter', None)
    if formatter is not None:
        if type(formatter) is logging.Formatter:
            yield ('  Formatter fmt=%r datefmt=%r' % (getattr(formatter, '_fmt', None), getattr(formatter, 'datefmt', None)))
        else:
            yield ('  Formatter %r' % (formatter,))
    if t is logging.handlers.MemoryHandler and h.target is not None:
        yield '  Flushes output to:'
        g = describe_handler(h.target)
        yield ('    Handler ' + next(g))
        for line in g:
            yield ('    ' + line)

def patched_str(self):
    """Try to pretty-print the exception, if this is going on screen."""
    def red(words):
        return u('\x1b[31m\x1b[49m%s\x1b[0m') % words
    def white(words):
        return u('\x1b[37m\x1b[49m%s\x1b[0m') % words
    def blue(words):
        return u('\x1b[34m\x1b[49m%s\x1b[0m') % words
    def teal(words):
        return u('\x1b[36m\x1b[49m%s\x1b[0m') % words
    def get_uri(code):
        return 'https://www.signalwire.com/docs/errors/{0}'.format(code)
    if hasattr(sys.stderr, 'isatty') and sys.stderr.isatty():
        msg = '\n{red_error} {request_was}\n\n{http_line}\n\n{sw_returned}\n\n{message}\n'.format(red_error=red('HTTP Error'), request_was=white('Your request was:'), http_line=teal('%s %s' % (self.method, self.uri)), sw_returned=white('Signalwire returned the following information:'), message=blue(str(self.msg)))
        if self.code:
            msg = ''.join([msg, '\n{more_info}\n\n{uri}\n\n'.format(more_info=white('More information may be available here:'), uri=blue(get_uri(self.code)))])
        return msg
    else:
        return 'HTTP {0} error: {1}'.format(self.status, self.msg)

def find_this(search, filename=MODULE_PATH):
    """Take a string and a filename path string and return the found value."""
    if not search:
        return
    for line in open(str(filename)).readlines():
        if search.lower() in line.lower():
            line = line.split('=')[1].strip()
            if "'" in line or '"' in line or '"""' in line:
                line = line.replace("'", '').replace('"', '').replace('"""', '')
            return line

def outer_product(vec):
    """Returns the outer product of a vector :math:`v`
    with itself, :math:`v v^\\T`."""
    return np.dot(vec[:, np.newaxis], vec[np.newaxis, :]) if len(vec.shape) == 1 else np.dot(vec, vec.T)

def ellipsoid_volume(A=None, invA=None):
    """Returns the volume of an ellipsoid given either its
    matrix or the inverse of its matrix."""
    if invA is None and A is None:
        raise ValueError('Must pass either inverse(A) or A.')
    if invA is None and A is not None:
        invA = la.inv(A)
    n = invA.shape[0]
    Vn = np.pi ** (n / 2) / gamma(1 + n / 2)
    return Vn * la.det(sqrtm(invA))

def format_uncertainty(value, uncertianty, scinotn_break=4):
    """Given a value and its uncertianty, format as a LaTeX string
    for pretty-printing.

    :param int scinotn_break: How many decimal points to print
        before breaking into scientific notation."""
    if uncertianty == 0:
        return '{0:f}'.format(value)
    else:
        mag_unc = int(np.log10(np.abs(uncertianty)))
        mag_val = int(np.log10(np.abs(value))) if value != 0 else 0
        n_digits = max(mag_val - mag_unc, 0)
        if abs(mag_val) < abs(mag_unc) and abs(mag_unc) > scinotn_break:
            scale = 10 ** mag_unc
            return '({{0:0.{0}f}} \\pm {{1:0.{0}f}}) \\times 10^{{2}}'.format(n_digits).format(value / scale, uncertianty / scale, mag_unc)
        if abs(mag_val) <= scinotn_break:
            return '{{0:0.{n_digits}f}} \\pm {{1:0.{n_digits}f}}'.format(n_digits=n_digits).format(value, uncertianty)
        else:
            scale = 10 ** mag_val
            return '({{0:0.{0}f}} \\pm {{1:0.{0}f}}) \\times 10^{{2}}'.format(n_digits).format(value / scale, uncertianty / scale, mag_val)

def sqrtm_psd(A, est_error=True, check_finite=True):
    """Returns the matrix square root of a positive semidefinite matrix,
    truncating negative eigenvalues."""
    w, v = eigh(A, check_finite=check_finite)
    mask = w <= 0
    w[mask] = 0
    np.sqrt(w, out=w)
    A_sqrt = (v * w).dot(v.conj().T)
    if est_error:
        return (A_sqrt, np.linalg.norm(np.dot(A_sqrt, A_sqrt) - A, 'fro'))
    else:
        return A_sqrt

def binom_est_error(p, N, hedge=float(0)):
    """"""
    return np.sqrt(p * (1 - p) / (N + 2 * hedge + 1))

def tensor_product_basis(*bases):
    """Returns a TomographyBasis formed by the tensor
    product of two or more factor bases. Each basis element
    is the tensor product of basis elements from the underlying
    factors."""
    dim = np.prod([basis.data.shape[1] for basis in bases])
    tp_basis = np.zeros((dim ** 2, dim, dim), dtype=complex)
    for idx_factors, factors in enumerate(it.product(*[basis.data for basis in bases])):
        tp_basis[idx_factors, :, :] = reduce(np.kron, factors)
    return TomographyBasis(tp_basis, sum((factor.dims for factor in bases), []), list(map('\\otimes'.join, it.product(*[basis.labels for basis in bases]))))

def get_ascii(pid=None, name=None, pokemons=None, return_pokemons=False, message=None):
    """get_ascii will return ascii art for a pokemon based on a name or pid.
    :param pid: the pokemon ID to return
    :param name: the pokemon name to return
    :param return_pokemons: return catches (default False)
    :param message: add a message to the ascii"""
    pokemon = get_pokemon(name=name, pid=pid, pokemons=pokemons)
    printme = message
    if len(pokemon) > 0:
        for pid, data in pokemon.items():
            if message == None:
                printme = data['name'].capitalize()
            print('%s\n\n%s' % (data['ascii'], printme))
    if return_pokemons == True:
        return pokemon

def get_pokemon(pid=None, name=None, pokemons=None):
    """get_pokemon will return a pokemon with a specific ID, or if none is given,
    will select randomly. First the pid will be used, then the name, then any filters.
    :param pid: the pokemon ID to return
    :param pokemons: the pokemons data structure"""
    if pokemons == None:
        pokemons = catch_em_all()
    if name is not None:
        catches = lookup_pokemon(field='name', value=name, pokemons=pokemons)
        if catches is not None:
            return catches
        print("We don't have a pokemon called %s" % name)
        sys.exit(1)
    if pid is None:
        choices = list(pokemons.keys())
        pid = int(choice(choices))
    if pid is not None and str(pid) in pokemons.keys():
        return {pid: pokemons[str(pid)]}
    else:
        print('Cannot find pokemon with this criteria!')

def catch_em_all(data_file=None, return_names=False):
    """catch_em_all returns the entire database of pokemon, a base function for starting
    :param data_file: location of pokemons.json data file (not required)"""
    if data_file == None:
        data_file = '%s/database/pokemons.json' % base
    pokemons = load_json(data_file)
    if return_names is True:
        names = []
        for key, meta in pokemons.items():
            names.append(meta['name'])
        return names
    return pokemons

def lookup_pokemon(field, value, pokemons=None):
    """lookup_pokemon will search a particular field (name) for a value. If no pokemons
    data structure is provided, all will be used.
    :param field: the field to look up.
    :param pokemons: the pokemons data structure"""
    if pokemons == None:
        pokemons = catch_em_all()
    catches = {}
    for pid, data in pokemons.items():
        if isinstance(data[field], list):
            for entry in data[field]:
                found = search_entry(entry, value)
                if found == True:
                    catches[pid] = data
        else:
            found = search_entry(data[field], value)
            if found == True:
                catches[pid] = data
    if len(catches) > 0:
        return catches
    return None

def load_yaml(filename):
    """Return object in yaml file."""
    with open(filename) as myfile:
        content = myfile.read()
        if 'win' in sys.platform:
            content = content.replace('\\', '/')
        return yaml.safe_load(content)

def sort_loading_order(step_files):
    """Sort step files into correct loading order.

    The correct loading order is first tools, then workflows without
    subworkflows, and then workflows with subworkflows. This order is
    required to avoid error messages when a working directory is used."""
    tools = []
    workflows = []
    workflows_with_subworkflows = []
    for f in step_files:
        if f.startswith('http://') or f.startswith('https://'):
            tools.append(f)
        else:
            obj = load_yaml(f)
            if obj.get('class', '') == 'Workflow':
                if 'requirements' in obj.keys():
                    subw = {'class': 'SubworkflowFeatureRequirement'}
                    if subw in obj['requirements']:
                        workflows_with_subworkflows.append(f)
                    else:
                        workflows.append(f)
                else:
                    workflows.append(f)
            else:
                tools.append(f)
    return tools + workflows + workflows_with_subworkflows

def str_presenter(dmpr, data):
    """Return correct str_presenter to write multiple lines to a yaml field.


    Source: http://stackoverflow.com/a/33300001"""
    if is_multiline(data):
        return dmpr.represent_scalar('tag:yaml.org,2002:str', data, style='|')
    return dmpr.represent_scalar('tag:yaml.org,2002:str', data)

def delta(a, b):
    """Computes the distances between two colors or color sets. The shape of
    `a` and `b` must be equal."""
    diff = a - b
    return numpy.einsum('i...,i...->...', diff, diff)

def e():
    """This is a hypothetical reference radiator. All wavelengths in CIE
    illuminant E are weighted equally with a relative spectral power of 100.0."""
    lmbda = 1e-09 * numpy.arange(300, 831)
    data = numpy.full(lmbda.shape, 100.0)
    return (lmbda, data)

def dot(a, b):
    """Take arrays `a` and `b` and form the dot product between the last axis
    of `a` and the first of `b`."""
    b = numpy.asarray(b)
    return numpy.dot(a, b.reshape(b.shape[0], -1)).reshape(a.shape[:-1] + b.shape[1:])

