def get_nlcd_mask(nlcd_ds, filter='not_forest', out_fn=None):
    """Generate raster mask for specified NLCD LULC filter
    """
    print('Loading NLCD LULC')
    b = nlcd_ds.GetRasterBand(1)
    l = b.ReadAsArray()
    print('Filtering NLCD LULC with: %s' % filter)
    if filter == 'rock':
        mask = l == 31
    elif filter == 'rock+ice':
        mask = np.logical_or(l == 31, l == 12)
    elif filter == 'rock+ice+water':
        mask = np.logical_or(np.logical_or(l == 31, l == 12), l == 11)
    elif filter == 'not_forest':
        mask = ~np.logical_or(np.logical_or(l == 41, l == 42), l == 43)
    elif filter == 'not_forest+not_water':
        mask = ~np.logical_or(np.logical_or(np.logical_or(l == 41, l == 42), l == 43), l == 11)
    else:
        print('Invalid mask type')
        mask = None
    if out_fn is not None:
        print('Writing out %s' % out_fn)
        iolib.writeGTiff(l, out_fn, nlcd_ds)
    l = None
    return mask

def modutf7_decode(data: bytes) -> str:
    """Decode the bytestring using modified UTF-7.

    Args:
        data: The encoded bytestring to decode."""
    parts = []
    is_usascii = True
    buf = memoryview(data)
    while buf:
        byte = buf[0]
        if is_usascii:
            if buf[0:2] == b'&-':
                parts.append('&')
                buf = buf[2:]
            elif byte == 38:
                is_usascii = False
                buf = buf[1:]
            else:
                parts.append(chr(byte))
                buf = buf[1:]
        else:
            for i, byte in enumerate(buf):
                if byte == 45:
                    to_decode = buf[:i].tobytes()
                    decoded = _modified_b64decode(to_decode)
                    parts.append(decoded)
                    buf = buf[i + 1:]
                    is_usascii = True
                    break
    if not is_usascii:
        to_decode = buf.tobytes()
        decoded = _modified_b64decode(to_decode)
        parts.append(decoded)
    return ''.join(parts)

def get_system_flags() -> FrozenSet[Flag]:
    """Return the set of implemented system flags."""
    return frozenset({Seen, Recent, Deleted, Flagged, Answered, Draft})

def spell(word):
    """most likely correction for everything up to a double typo"""
    w = Word(word)
    candidates = common([word]) or exact([word]) or known([word]) or known(w.typos()) or common(w.double_typos()) or [word]
    correction = max(candidates, key=NLP_COUNTS.get)
    return get_case(word, correction)

def words_from_archive(filename, include_dups=False, map_case=False):
    """extract words from a text file in the archive"""
    bz2 = os.path.join(PATH, BZ2)
    tar_path = '{}/{}'.format('words', filename)
    with closing(tarfile.open(bz2, 'r:bz2')) as t:
        with closing(t.extractfile(tar_path)) as f:
            words = re.findall(RE, f.read().decode(encoding='utf-8'))
    if include_dups:
        return words
    elif map_case:
        return {w.lower(): w for w in words}
    else:
        return set(words)

def parse(lang_sample):
    """tally word popularity using novel extracts, etc"""
    words = words_from_archive(lang_sample, include_dups=True)
    counts = zero_default_dict()
    for word in words:
        counts[word] += 1
    return (set(words), counts)

def get_case(word, correction):
    """Best guess of intended case.

    manchester => manchester
    chilton => Chilton
    AAvTech => AAvTech
    THe => The
    imho => IMHO"""
    if word.istitle():
        return correction.title()
    if word.isupper():
        return correction.upper()
    if correction == word and (not word.islower()):
        return word
    if len(word) > 2 and word[:2].isupper():
        return correction.title()
    if not known_as_lower([correction]):
        try:
            return CASE_MAPPED[correction]
        except KeyError:
            pass
    return correction

def register(lib_name: str, cbl: Callable[[_AsyncLib], None]):
    """Registers a new library function with the current manager."""
