def load_deploy_config(deploy_filename, config=None):
    """Loads any local config overrides in the deploy file."""
    if not config:
        config = Config()
    if not deploy_filename:
        return
    if path.exists(deploy_filename):
        extract_file_config(deploy_filename, config)
    return config

def _parse_mode(mode):
    """Converts ls mode output (rwxrwxrwx) -> integer (755)."""
    result = ''
    for group in [mode[0:3], mode[3:6], mode[6:9]]:
        if group in SYMBOL_TO_OCTAL_PERMISSIONS:
            result = '{0}{1}'.format(result, SYMBOL_TO_OCTAL_PERMISSIONS[group])
        else:
            result = '{0}0'.format(result)
    return int(result)

def parse_iptables_rule(line):
    """Parse one iptables rule. Returns a dict where each iptables code argument
    is mapped to a name using IPTABLES_ARGS."""
    bits = line.split()
    definition = {}
    key = None
    args = []
    not_arg = False
    def add_args():
        arg_string = ' '.join(args)
        if key in IPTABLES_ARGS:
            definition_key = 'not_{0}'.format(IPTABLES_ARGS[key]) if not_arg else IPTABLES_ARGS[key]
            definition[definition_key] = arg_string
        else:
            definition.setdefault('extras', []).extend((key, arg_string))
    for bit in bits:
        if bit == '!':
            if key:
                add_args()
                args = []
                key = None
            not_arg = True
        elif bit.startswith('-'):
            if key:
                add_args()
                args = []
                not_arg = False
            key = bit
        else:
            args.append(bit)
    if key:
        add_args()
    if 'extras' in definition:
        definition['extras'] = set(definition['extras'])
    return definition

def config(state, host, key, value, repo=None):
    """Manage git config for a repository or globally.

    + key: the key of the config to ensure
    + value: the value this key should have
    + repo: specify the git repo path to edit local config (defaults to global)"""
    existing_config = host.fact.git_config(repo)
    if key not in existing_config or existing_config[key] != value:
        if repo is None:
            yield 'git config --global {0} "{1}"'.format(key, value)
        else:
            yield 'cd {0} && git config --local {1} "{2}"'.format(repo, key, value)

def virtualenv(state, host, path, python=None, site_packages=False, always_copy=False, present=True):
    """Add/remove Python virtualenvs.

    + python: python interpreter to use
    + site_packages: give access to the global site-packages
    + always_copy: always copy files rather than symlinking
    + present: whether the virtualenv should exist"""
    if present is False and host.fact.directory(path):
        yield files.directory(state, host, path, present=False)
    elif present and (not host.fact.directory(path)):
        command = ['virtualenv']
        if python:
            command.append('-p {0}'.format(python))
        if site_packages:
            command.append('--system-site-packages')
        if always_copy:
            command.append('--always-copy')
        command.append(path)
        yield ' '.join(command)

def include(filename, hosts=False, when=True):
    """Executes a local python file within the ``pyinfra.pseudo_state.deploy_dir``
    directory.

    Args:
        hosts (string, list): group name or list of hosts to limit this include to
        when (bool): indicate whether to trigger operations in this include"""
    if not pyinfra.is_cli:
        raise PyinfraError('local.include is only available in CLI mode.')
    if not when:
        return
    if hosts is not False:
        hosts = ensure_host_list(hosts, inventory=pseudo_state.inventory)
        if pseudo_host not in hosts:
            return
    if pseudo_state.deploy_dir:
        filename = path.join(pseudo_state.deploy_dir, filename)
    frameinfo = get_caller_frameinfo()
    logger.debug('Including local file: {0}'.format(filename))
    try:
        from pyinfra_cli.config import extract_file_config
        from pyinfra_cli.util import exec_file
        config_data = extract_file_config(filename)
        kwargs = {key.lower(): value for key, value in six.iteritems(config_data) if key in ['SUDO', 'SUDO_USER', 'SU_USER', 'PRESERVE_SUDO_ENV', 'IGNORE_ERRORS']}
        with pseudo_state.deploy(filename, kwargs, None, frameinfo.lineno, in_deploy=False):
            exec_file(filename)
    except IOError as e:
        raise PyinfraError('Could not include local file: {0}\n{1}'.format(filename, e))

def rpm(state, host, source, present=True):
    """Add/remove ``.rpm`` file packages.

    + source: filename or URL of the ``.rpm`` package
    + present: whether ore not the package should exist on the system

    URL sources with ``present=False``:
        If the ``.rpm`` file isn't downloaded, pyinfra can't remove any existing
        package as the file won't exist until mid-deploy."""
    if urlparse(source).scheme:
        temp_filename = '{0}.rpm'.format(state.get_temp_filename(source))
        yield files.download(state, host, source, temp_filename)
        source = temp_filename
    info = host.fact.rpm_package(source)
    exists = False
    if info:
        current_packages = host.fact.rpm_packages
        if info['name'] in current_packages and info['version'] in current_packages[info['name']]:
            exists = True
    if present and (not exists):
        if info:
            yield 'rpm -U {0}'.format(source)
        else:
            yield 'rpm -qa | grep `rpm -qp {0}` || rpm -U {0}'.format(source)
    if exists and (not present):
        yield 'yum remove -y {0}'.format(info['name'])

def pop_op_kwargs(state, kwargs):
    """Pop and return operation global keyword arguments."""
    meta_kwargs = state.deploy_kwargs or {}
    def get_kwarg(key, default=None):
        return kwargs.pop(key, meta_kwargs.get(key, default))
    env = state.config.ENV.copy()
    env.update(get_kwarg('env', {}))
    hosts = get_kwarg('hosts')
    hosts = ensure_host_list(hosts, inventory=state.inventory)
    if meta_kwargs.get('hosts') is not None:
        hosts = [host for host in hosts if host in meta_kwargs['hosts']]
    return {'env': env, 'hosts': hosts, 'when': get_kwarg('when', True), 'sudo': get_kwarg('sudo', state.config.SUDO), 'sudo_user': get_kwarg('sudo_user', state.config.SUDO_USER), 'su_user': get_kwarg('su_user', state.config.SU_USER), 'preserve_sudo_env': get_kwarg('preserve_sudo_env', state.config.PRESERVE_SUDO_ENV), 'ignore_errors': get_kwarg('ignore_errors', state.config.IGNORE_ERRORS), 'timeout': get_kwarg('timeout'), 'get_pty': get_kwarg('get_pty', False), 'serial': get_kwarg('serial', False), 'run_once': get_kwarg('run_once', False), 'parallel': get_kwarg('parallel'), 'on_success': get_kwarg('on_success'), 'on_error': get_kwarg('on_error'), 'op': get_kwarg('op')}

def unroll_generators(generator):
    """Take a generator and unroll any sub-generators recursively. This is
    essentially a Python 2 way of doing `yield from` in Python 3 (given
    iterating the entire thing)."""
    if not isinstance(generator, GeneratorType):
        raise TypeError('{0} is not a generator'.format(generator))
    items = []
    for item in generator:
        if isinstance(item, GeneratorType):
            items.extend(unroll_generators(item))
        else:
            items.append(item)
    return items

def get_template(filename_or_string, is_string=False):
    """Gets a jinja2 ``Template`` object for the input filename or string, with caching
    based on the filename of the template, or the SHA1 of the input string."""
    cache_key = sha1_hash(filename_or_string) if is_string else filename_or_string
    if cache_key in TEMPLATES:
        return TEMPLATES[cache_key]
    if is_string:
        template_string = filename_or_string
    else:
        with open(filename_or_string, 'r') as file_io:
            template_string = file_io.read()
    TEMPLATES[cache_key] = Template(template_string, keep_trailing_newline=True)
    return TEMPLATES[cache_key]

def sha1_hash(string):
    """Return the SHA1 of the input string."""
    hasher = sha1()
    hasher.update(string.encode())
    return hasher.hexdigest()

def get_arg_value(state, host, arg):
    """Runs string arguments through the jinja2 templating system with a state and
    host. Used to avoid string formatting in deploy operations which result in
    one operation per host/variable. By parsing the commands after we generate
    the ``op_hash``, multiple command variations can fall under one op."""
    if isinstance(arg, six.string_types):
        data = {'host': host, 'inventory': state.inventory}
        try:
            return get_template(arg, is_string=True).render(data)
        except (TemplateSyntaxError, UndefinedError) as e:
            raise PyinfraError('Error in template string: {0}'.format(e))
    elif isinstance(arg, list):
        return [get_arg_value(state, host, value) for value in arg]
    elif isinstance(arg, tuple):
        return tuple((get_arg_value(state, host, value) for value in arg))
    elif isinstance(arg, dict):
        return {key: get_arg_value(state, host, value) for key, value in six.iteritems(arg)}
    return arg

def make_hash(obj):
    """Make a hash from an arbitrary nested dictionary, list, tuple or set, used to generate
    ID's for operations based on their name & arguments."""
    if isinstance(obj, (set, tuple, list)):
        hash_string = ''.join([make_hash(e) for e in obj])
    elif isinstance(obj, dict):
        hash_string = ''.join((''.join((key, make_hash(value))) for key, value in six.iteritems(obj)))
    else:
        hash_string = '_PYINFRA_CONSTANT' if obj in (True, False, None) else obj if isinstance(obj, six.string_types) else obj.__name__ if hasattr(obj, '__name__') else obj.name if hasattr(obj, 'name') else repr(obj)
    return sha1_hash(hash_string)

def read_buffer(io, print_output=False, print_func=None):
    """Reads a file-like buffer object into lines and optionally prints the output."""
    def _print(line):
        if print_output:
            if print_func:
                formatted_line = print_func(line)
            else:
                formatted_line = line
            encoded_line = unicode(formatted_line).encode('utf-8')
            print(encoded_line)
    out = []
    for line in io:
        if not isinstance(line, six.text_type):
            line = line.decode('utf-8')
        line = line.strip()
        out.append(line)
        _print(line)
    return out

def create(state, host, ctid, template=None):
    """Create OpenVZ containers.

    + ctid: CTID of the container to create"""
    current_containers = host.fact.openvz_containers
    if ctid in current_containers:
        raise OperationError('An OpenVZ container with CTID {0} already exists'.format(ctid))
    args = ['{0}'.format(ctid)]
    if template:
        args.append('--ostemplate {0}'.format(template))
    yield 'vzctl create {0}'.format(' '.join(args))

def exec_file(filename, return_locals=False, is_deploy_code=False):
    """Execute a Python file and optionally return it's attributes as a dict."""
    if filename not in PYTHON_CODES:
        with open(filename, 'r') as f:
            code = f.read()
        code = compile(code, filename, 'exec')
        PYTHON_CODES[filename] = code
    data = {'__file__': filename, 'state': pseudo_state}
    exec(PYTHON_CODES[filename], data)
    return data

def shell(state, host, commands, chdir=None):
    """Run raw shell code.

    + commands: command or list of commands to execute on the remote server
    + chdir: directory to cd into before executing commands"""
    if isinstance(commands, six.string_types):
        commands = [commands]
    for command in commands:
        if chdir:
            yield 'cd {0} && ({1})'.format(chdir, command)
        else:
            yield command

def hostname(state, host, hostname, hostname_file=None):
    """Set the system hostname.

    + hostname: the hostname that should be set
    + hostname_file: the file that permanently sets the hostname

    Hostname file:
        By default pyinfra will auto detect this by targetting ``/etc/hostname``
        on Linux and ``/etc/myname`` on OpenBSD."""
    if hostname_file is None:
        os = host.fact.os
        if os == 'Linux':
            hostname_file = '/etc/hostname'
        elif os == 'OpenBSD':
            hostname_file = '/etc/myname'
    current_hostname = host.fact.hostname
    if current_hostname != hostname:
        yield 'hostname {0}'.format(hostname)
    if hostname_file:
        file = six.StringIO('{0}\n'.format(hostname))
        yield files.put(state, host, file, hostname_file)

def download(state, host, source_url, destination, user=None, group=None, mode=None, cache_time=None, force=False):
    """Download files from remote locations.

    + source_url: source URl of the file
    + destination: where to save the file
    + user: user to own the files
    + group: group to own the files
    + mode: permissions of the files
    + cache_time: if the file exists already, re-download after this time (in s)
    + force: always download the file, even if it already exists"""
    info = host.fact.file(destination)
    if info is False:
        raise OperationError('Destination {0} already exists and is not a file'.format(destination))
    download = force
    if info is None:
        download = True
    elif cache_time:
        cache_time = host.fact.date.replace(tzinfo=None) - timedelta(seconds=cache_time)
        if info['mtime'] and info['mtime'] > cache_time:
            download = True
    if download:
        yield 'wget -q {0} -O {1}'.format(source_url, destination)
        if user or group:
            yield chown(destination, user, group)
        if mode:
            yield chmod(destination, mode)

def file(state, host, name, present=True, user=None, group=None, mode=None, touch=False):
    """Add/remove/update files.

    + name: name/path of the remote file
    + present: whether the file should exist
    + user: user to own the files
    + group: group to own the files
    + mode: permissions of the files as an integer, eg: 755
    + touch: whether to touch the file"""
    mode = ensure_mode_int(mode)
    info = host.fact.file(name)
    if info is False:
        raise OperationError('{0} exists and is not a file'.format(name))
    if info is None and present:
        yield 'touch {0}'.format(name)
        if mode:
            yield chmod(name, mode)
        if user or group:
            yield chown(name, user, group)
    elif info and (not present):
        yield 'rm -f {0}'.format(name)
    elif info and present:
        if touch:
            yield 'touch {0}'.format(name)
        if mode and info['mode'] != mode:
            yield chmod(name, mode)
        if user and info['user'] != user or (group and info['group'] != group):
            yield chown(name, user, group)

def _is_inventory_group(key, value):
    """Verify that a module-level variable (key = value) is a valid inventory group."""
    if key.startswith('_') or not isinstance(value, (list, tuple, GeneratorType)):
        return False
    if isinstance(value, tuple):
        value = value[0]
    if isinstance(value, GeneratorType):
        value = list(value)
    return all((isinstance(item, ALLOWED_HOST_TYPES) for item in value))

def get_fact(state, host, name):
    """Wrapper around ``get_facts`` returning facts for one host or a function
    that does."""
    if callable(getattr(FACTS[name], 'command', None)):
        def wrapper(*args):
            fact_data = get_facts(state, name, args=args, ensure_hosts=(host,))
            return fact_data.get(host)
        return wrapper
    else:
        fact_data = get_facts(state, name, ensure_hosts=(host,))
        return fact_data.get(host)

def connect_all(state):
    """Connect to all the configured servers in parallel. Reads/writes state.inventory.

    Args:
        state (``pyinfra.api.State`` obj): the state containing an inventory to connect to"""
    hosts = [host for host in state.inventory if state.is_host_in_limit(host)]
    greenlet_to_host = {state.pool.spawn(host.connect, state): host for host in hosts}
    with progress_spinner(greenlet_to_host.values()) as progress:
        for greenlet in gevent.iwait(greenlet_to_host.keys()):
            host = greenlet_to_host[greenlet]
            progress(host)
    failed_hosts = set()
    for greenlet, host in six.iteritems(greenlet_to_host):
        greenlet.get()
        if host.connection:
            state.activate_host(host)
        else:
            failed_hosts.add(host)
    state.fail_hosts(failed_hosts, activated_count=len(hosts))

def key(state, host, key=None, keyserver=None, keyid=None):
    """Add apt gpg keys with ``apt-key``.

    + key: filename or URL
    + keyserver: URL of keyserver to fetch key from
    + keyid: key identifier when using keyserver

    Note:
        Always returns an add command, not state checking.

    keyserver/id:
        These must be provided together."""
    if key:
        if urlparse(key).scheme:
            yield 'wget -O- {0} | apt-key add -'.format(key)
        else:
            yield 'apt-key add {0}'.format(key)
    if keyserver and keyid:
        yield 'apt-key adv --keyserver {0} --recv-keys {1}'.format(keyserver, keyid)

def repo(state, host, name, present=True, filename=None):
    """Add/remove apt repositories.

    + name: apt source string eg ``deb http://X hardy main``
    + present: whether the repo should exist on the system
    + filename: optional filename to use ``/etc/apt/sources.list.d/<filename>.list``. By
      default uses ``/etc/apt/sources.list``."""
    if filename:
        filename = '/etc/apt/sources.list.d/{0}.list'.format(filename)
    else:
        filename = '/etc/apt/sources.list'
    apt_sources = host.fact.apt_sources
    is_present = False
    repo = parse_apt_repo(name)
    if repo and repo in apt_sources:
        is_present = True
    if not is_present and present:
        yield files.line(state, host, filename, name)
    if is_present and (not present):
        yield files.line(state, host, filename, name, present=False)

def ppa(state, host, name, present=True):
    """Add/remove Ubuntu ppa repositories.

    + name: the PPA name (full ppa:user/repo format)
    + present: whether it should exist

    Note:
        requires ``apt-add-repository`` on the remote host"""
    if present:
        yield 'apt-add-repository -y "{0}"'.format(name)
    if not present:
        yield 'apt-add-repository -y --remove "{0}"'.format(name)

def update(state, host, cache_time=None, touch_periodic=False):
    """Updates apt repos.

    + cache_time: cache updates for this many seconds
    + touch_periodic: touch ``/var/lib/apt/periodic/update-success-stamp`` after update"""
    if cache_time:
        cache_info = host.fact.file(APT_UPDATE_FILENAME)
        host_cache_time = host.fact.date.replace(tzinfo=None) - timedelta(seconds=cache_time)
        if cache_info and cache_info['mtime'] and (cache_info['mtime'] > host_cache_time):
            return
    yield 'apt-get update'
    if cache_time:
        yield 'touch {0}'.format(APT_UPDATE_FILENAME)

def put_file(state, host, filename_or_io, remote_filename, sudo=False, sudo_user=None, su_user=None, print_output=False):
    """Upload file-ios to the specified host using SFTP. Supports uploading files
    with sudo by uploading to a temporary directory then moving & chowning."""
    if sudo or su_user:
        temp_file = state.get_temp_filename(remote_filename)
        _put_file(host, filename_or_io, temp_file)
        if print_output:
            print('{0}file uploaded: {1}'.format(host.print_prefix, remote_filename))
        command = 'mv {0} {1}'.format(temp_file, remote_filename)
        if su_user:
            command = '{0} && chown {1} {2}'.format(command, su_user, remote_filename)
        elif sudo_user:
            command = '{0} && chown {1} {2}'.format(command, sudo_user, remote_filename)
        status, _, stderr = run_shell_command(state, host, command, sudo=sudo, sudo_user=sudo_user, su_user=su_user, print_output=print_output)
        if status is False:
            logger.error('File error: {0}'.format('\n'.join(stderr)))
            return False
    else:
        _put_file(host, filename_or_io, remote_filename)
        if print_output:
            print('{0}file uploaded: {1}'.format(host.print_prefix, remote_filename))
    return True

def _run_server_ops(state, host, progress=None):
    """Run all ops for a single server."""
    logger.debug('Running all ops on {0}'.format(host))
    for op_hash in state.get_op_order():
        op_meta = state.op_meta[op_hash]
        logger.info('--> {0} {1} on {2}'.format(click.style('--> Starting operation:', 'blue'), click.style(', '.join(op_meta['names']), bold=True), click.style(host.name, bold=True)))
        result = _run_server_op(state, host, op_hash)
        if progress:
            progress((host, op_hash))
        if result is False:
            raise PyinfraError('Error in operation {0} on {1}'.format(', '.join(op_meta['names']), host))
        if pyinfra.is_cli:
            print()

def _run_serial_ops(state):
    """Run all ops for all servers, one server at a time."""
    for host in list(state.inventory):
        host_operations = product([host], state.get_op_order())
        with progress_spinner(host_operations) as progress:
            try:
                _run_server_ops(state, host, progress=progress)
            except PyinfraError:
                state.fail_hosts({host})

def run_ops(state, serial=False, no_wait=False):
    """Runs all operations across all servers in a configurable manner.

    Args:
        state (``pyinfra.api.State`` obj): the deploy state to execute
        serial (boolean): whether to run operations host by host
        no_wait (boolean): whether to wait for all hosts between operations"""
    state.deploying = True
    if serial:
        _run_serial_ops(state)
    elif no_wait:
        _run_no_wait_ops(state)
    for op_hash in state.get_op_order():
        _run_single_op(state, op_hash)

def check_originating_identity():
    """Check and decode the "X-Broker-API-Originating-Identity" header
    https://github.com/openservicebrokerapi/servicebroker/blob/v2.13/spec.md#originating-identity"""
    from flask import request, json
    if 'X-Broker-API-Originating-Identity' in request.headers:
        try:
            platform, value = request.headers['X-Broker-API-Originating-Identity'].split(None, 1)
            request.originating_identity = {'platform': platform, 'value': json.loads(base64.standard_b64decode(value))}
        except ValueError as e:
            return (to_json_response(ErrorResponse(description='Improper "X-Broker-API-Originating-Identity" header. ' + str(e))), HTTPStatus.BAD_REQUEST)
    else:
        request.originating_identity = None

def requires_application_json(f):
    """Decorator for enforcing application/json Content-Type"""
    @functools.wraps(f)
    def wrapped(*args, **kwargs):
        from flask import request
        if request.get_json(silent=True) is None:
            er = ErrorResponse(description='Improper Content-Type header. Expecting "application/json"')
            return (to_json_response(er), HTTPStatus.BAD_REQUEST)
        else:
            return f(*args, **kwargs)
    return wrapped

def get_last_activity(session):
    """Get the last activity datetime string from the session and return the
    python datetime object."""
    try:
        return datetime.strptime(session['_session_security'], '%Y-%m-%dT%H:%M:%S.%f')
    except AttributeError:
        return datetime.now()
    except TypeError:
        return datetime.now()

def inquire_property(name, doc=None):
    """Creates a property based on an inquire result

    This method creates a property that calls the
    :python:`_inquire` method, and return the value of the
    requested information.

    Args:
        name (str): the name of the 'inquire' result information

    Returns:
        property: the created property"""
    def inquire_property(self):
        if not self._started:
            msg = 'Cannot read {0} from a security context whose establishment has not yet been started.'
            raise AttributeError(msg)
        return getattr(self._inquire(**{name: True}), name)
    return property(inquire_property, doc=doc)

def _encode_dict(d):
    """Encodes any relevant strings in a dict"""
    def enc(x):
        if isinstance(x, six.text_type):
            return x.encode(_ENCODING)
        else:
            return x
    return dict(((enc(k), enc(v)) for k, v in six.iteritems(d)))

def catch_and_return_token(func, self, *args, **kwargs):
    """Optionally defer exceptions and return a token instead

    When `__DEFER_STEP_ERRORS__` is set on the implementing class
    or instance, methods wrapped with this wrapper will
    catch and save their :python:`GSSError` exceptions and
    instead return the result token attached to the exception.

    The exception can be later retrived through :python:`_last_err`
    (and :python:`_last_tb` when Python 2 is in use)."""
    try:
        return func(self, *args, **kwargs)
    except GSSError as e:
        if e.token is not None and self.__DEFER_STEP_ERRORS__:
            self._last_err = e
            if six.PY2:
                self._last_tb = sys.exc_info()[2].tb_next.tb_next
            else:
                self._last_err.__traceback__ = e.__traceback__.tb_next
            return e.token
        else:
            raise

def check_last_err(func, self, *args, **kwargs):
    """Check and raise deferred errors before running the function

    This method checks :python:`_last_err` before running the wrapped
    function.  If present and not None, the exception will be raised
    with its original traceback."""
    if self._last_err is not None:
        try:
            if six.PY2:
                six.reraise(type(self._last_err), self._last_err, self._last_tb)
            else:
                raise self._last_err
        finally:
            if six.PY2:
                del self._last_tb
            self._last_err = None
    else:
        return func(self, *args, **kwargs)
    @deco.decorator
    def check_last_err(func, self, *args, **kwargs):
        if self._last_err is not None:
            try:
                raise self._last_err
            finally:
                self._last_err = None
        else:
            return func(self, *args, **kwargs)

def strings_to_categoricals(adata):
    """Transform string annotations to categoricals.
    """
    from pandas.api.types import is_string_dtype
    from pandas import Categorical
    for df in [adata.obs, adata.var]:
        string_cols = [key for key in df.columns if is_string_dtype(df[key])]
        for key in string_cols:
            c = df[key]
            c = Categorical(c)
            if len(c.categories) < len(c):
                df[key] = c

def select_groups(adata, groups='all', key='louvain'):
    """Get subset of groups in adata.obs[key].
    """
    strings_to_categoricals(adata)
    if isinstance(groups, list) and isinstance(groups[0], int):
        groups = [str(n) for n in groups]
    categories = adata.obs[key].cat.categories
    groups_masks = np.array([categories[i] == adata.obs[key].values for i, name in enumerate(categories)])
    if groups == 'all':
        groups = categories.values
    else:
        groups_ids = [np.where(categories.values == name)[0][0] for name in groups]
        groups_masks = groups_masks[groups_ids]
        groups = categories[groups_ids].values
    return (groups, groups_masks)

def sum_obs(A):
    """summation over axis 0 (obs) equivalent to np.sum(A, 0)
    """
    return A.sum(0).A1 if issparse(A) else np.einsum('ij -> j', A)

def prod_sum_var(A, B):
    """dot product and sum over axis 1 (var) equivalent to np.sum(A * B, 1)
    """
    return A.multiply(B).sum(1).A1 if issparse(A) else np.einsum('ij, ij -> i', A, B)

def norm(A):
    """computes the L2-norm along axis 1 (e.g. genes or embedding dimensions) equivalent to np.linalg.norm(A, axis=1)
    """
    return np.sqrt(A.multiply(A).sum(1).A1) if issparse(A) else np.sqrt(np.einsum('ij, ij -> i', A, A))

def strings_to_categoricals(adata):
    """Transform string annotations to categoricals.
    """
    from pandas import Categorical
    def is_valid_dtype(values):
        from pandas.api.types import is_string_dtype, is_integer_dtype, is_bool_dtype
        return is_string_dtype(values) or is_integer_dtype(values) or is_bool_dtype(values)
    for df in [adata.obs, adata.var]:
        string_cols = [key for key in df.columns if is_valid_dtype(df[key])]
        for key in string_cols:
            c = df[key]
            c = Categorical(c)
            if len(c.categories) < min(len(c), 100):
                df[key] = c

def get_obj_module(qualname):
    """Get a module/class/attribute and its original module by qualname"""
    modname = qualname
    classname = None
    attrname = None
    while modname not in sys.modules:
        attrname = classname
        modname, classname = modname.rsplit('.', 1)
    if classname:
        cls = getattr(sys.modules[modname], classname)
        modname = cls.__module__
        obj = getattr(cls, attrname) if attrname else cls
    else:
        obj = None
    return (obj, sys.modules[modname])

def get_version_from_dirname(name, parent):
    """Extracted sdist"""
    parent = parent.resolve()
    re_dirname = re.compile(f'{name}-{RE_VERSION}$')
    if not re_dirname.match(parent.name):
        return None
    return Version.parse(parent.name[len(name) + 1:])

def optimize_NxN(x, y, fit_offset=False, perc=None):
    """Just to compare with closed-form solution
    """
    if perc is not None:
        if not fit_offset and isinstance(perc, (list, tuple)):
            perc = perc[1]
        weights = get_weight(x, y, perc).astype(bool)
        if issparse(weights):
            weights = weights.A
    else:
        weights = None
    x, y = (x.astype(np.float64), y.astype(np.float64))
    n_vars = x.shape[1]
    offset, gamma = (np.zeros(n_vars), np.zeros(n_vars))
    for i in range(n_vars):
        xi = x[:, i] if weights is None else x[:, i][weights[:, i]]
        yi = y[:, i] if weights is None else y[:, i][weights[:, i]]
        if fit_offset:
            offset[i], gamma[i] = minimize(lambda m: np.sum((-yi + xi * m[1] + m[0]) ** 2), method='L-BFGS-B', x0=(0, 0.1), bounds=[(0, None), (None, None)]).x
        else:
            gamma[i] = minimize(lambda m: np.sum((-yi + xi * m) ** 2), x0=0.1, method='L-BFGS-B').x
    offset[np.isnan(offset)], gamma[np.isnan(gamma)] = (0, 0)
    return (offset, gamma)

def average_price(quantity_1, price_1, quantity_2, price_2):
    """Calculates the average price between two asset states."""
    return (quantity_1 * price_1 + quantity_2 * price_2) / (quantity_1 + quantity_2)

def invert(color):
    """Returns the inverse (negative) of a color.  The red, green, and blue
    values are inverted, while the opacity is left alone."""
    if isinstance(color, Number):
        return String.unquoted('invert(%s)' % (color.render(),))
    expect_type(color, Color)
    r, g, b, a = color.rgba
    return Color.from_rgb(1 - r, 1 - g, 1 - b, alpha=a)

def nth(lst, n):
    """Return the nth item in the list."""
    expect_type(n, (String, Number), unit=None)
    if isinstance(n, String):
        if n.value.lower() == 'first':
            i = 0
        elif n.value.lower() == 'last':
            i = -1
        else:
            raise ValueError('Invalid index %r' % (n,))
    else:
        i = n.to_python_index(len(lst), circular=True)
    return lst[i]

def make_filename_hash(key):
    """Convert the given key (a simple Python object) to a unique-ish hash
    suitable for a filename."""
    key_repr = repr(key).replace(BASE_DIR, '').encode('utf8')
    if sys.platform == 'win32':
        key_repr = key_repr.replace(b'\\\\', b'/')
    key_repr = re.sub(b"\\bu'", b"'", key_repr)
    key_hash = hashlib.md5(key_repr).digest()
    return base64.b64encode(key_hash, b'__').decode('ascii').rstrip('=')

def extend_unique(seq, more):
    """Return a new sequence containing the items in `seq` plus any items in
    `more` that aren't already in `seq`, preserving the order of both."""
    seen = set(seq)
    new = []
    for item in more:
        if item not in seen:
            seen.add(item)
            new.append(item)
    return seq + type(seq)(new)

def blank(*objs):
    """Returns true when the object is false, an empty string, or an empty list"""
    for o in objs:
        if isinstance(o, Boolean):
            is_blank = not o
        elif isinstance(o, String):
            is_blank = not len(o.value.strip())
        elif isinstance(o, List):
            is_blank = all((blank(el) for el in o))
        else:
            is_blank = False
        if not is_blank:
            return Boolean(False)
    return Boolean(True)

def compact(*args):
    """Returns a new list after removing any non-true values"""
    use_comma = True
    if len(args) == 1 and isinstance(args[0], List):
        use_comma = args[0].use_comma
        args = args[0]
    return List([arg for arg in args if arg], use_comma=use_comma)

def reject(lst, *values):
    """Removes the given values from the list"""
    lst = List.from_maybe(lst)
    values = frozenset(List.from_maybe_starargs(values))
    ret = []
    for item in lst:
        if item not in values:
            ret.append(item)
    return List(ret, use_comma=lst.use_comma)

def font_url(path, only_path=False, cache_buster=True):
    """Generates a path to an asset found relative to the project's font directory.
    Passing a true value as the second argument will cause the only the path to
    be returned instead of a `url()` function"""
    return _font_url(path, only_path, cache_buster, False)

def stylesheet_url(path, only_path=False, cache_buster=True):
    """Generates a path to an asset found relative to the project's css directory.
    Passing a true value as the second argument will cause the only the path to
    be returned instead of a `url()` function"""
    filepath = String.unquoted(path).value
    if callable(config.STATIC_ROOT):
        try:
            _file, _storage = list(config.STATIC_ROOT(filepath))[0]
        except IndexError:
            filetime = None
        else:
            filetime = getmtime(_file, _storage)
        if filetime is None:
            filetime = 'NA'
    else:
        _path = os.path.join(config.STATIC_ROOT, filepath.strip('/'))
        filetime = getmtime(_path)
        if filetime is None:
            filetime = 'NA'
    BASE_URL = config.STATIC_URL
    url = '%s%s' % (BASE_URL, filepath)
    if cache_buster:
        url = add_cache_buster(url, filetime)
    if only_path:
        return String.unquoted(url)
    else:
        return Url.unquoted(url)

def compile_string(string, compiler_class=Compiler, **kwargs):
    """Compile a single string, and return a string of CSS.

    Keyword arguments are passed along to the underlying `Compiler`."""
    compiler = compiler_class(**kwargs)
    return compiler.compile_string(string)

def _constrain(value, lb=0, ub=1):
    """Helper for Color constructors.  Constrains a value to a range."""
    if value < lb:
        return lb
    elif value > ub:
        return ub
    else:
        return value

def _is_combinator_subset_of(specific, general, is_first=True):
    """Return whether `specific` matches a non-strict subset of what `general`
    matches."""
    if is_first and general == ' ':
        return True
    if specific == general:
        return True
    if specific == '>' and general == ' ':
        return True
    if specific == '+' and general == '~':
        return True
    return False

def _weave_conflicting_selectors(prefixes, a, b, suffix=()):
    """Part of the selector merge algorithm above.  Not useful on its own.  Pay
    no attention to the man behind the curtain."""
    both = a and b
    for prefix in prefixes:
        yield (prefix + a + b + suffix)
        if both:
            yield (prefix + b + a + suffix)

def _merge_simple_selectors(a, b):
    """Merge two simple selectors, for the purposes of the LCS algorithm below.

    In practice this returns the more specific selector if one is a subset of
    the other, else it returns None."""
    if a.is_superset_of(b):
        return b
    elif b.is_superset_of(a):
        return a
    else:
        return None

def convert_units_to_base_units(units):
    """Convert a set of units into a set of "base" units.

    Returns a 2-tuple of `factor, new_units`."""
    total_factor = 1
    new_units = []
    for unit in units:
        if unit not in BASE_UNIT_CONVERSIONS:
            continue
        factor, new_unit = BASE_UNIT_CONVERSIONS[unit]
        total_factor *= factor
        new_units.append(new_unit)
    new_units.sort()
    return (total_factor, tuple(new_units))

def count_base_units(units):
    """Returns a dict mapping names of base units to how many times they
    appear in the given iterable of units.  Effectively this counts how
    many length units you have, how many time units, and so forth."""
    ret = {}
    for unit in units:
        factor, base_unit = get_conversion_factor(unit)
        ret.setdefault(base_unit, 0)
        ret[base_unit] += 1
    return ret

def is_builtin_css_function(name):
    """Returns whether the given `name` looks like the name of a builtin CSS
    function.

    Unrecognized functions not in this list produce warnings."""
    name = name.replace('_', '-')
    if name in BUILTIN_FUNCTIONS:
        return True
    if name[0] == '-' and '-' in name[1:]:
        return True
    return False

def sprite_map_name(map):
    """Returns the name of a sprite map The name is derived from the folder than
    contains the sprites."""
    map = map.render()
    sprite_maps = _get_cache('sprite_maps')
    sprite_map = sprite_maps.get(map)
    if not sprite_map:
        log.error('No sprite map found: %s', map, extra={'stack': True})
    if sprite_map:
        return String.unquoted(sprite_map['*n*'])
    return String.unquoted('')

def sprite_file(map, sprite):
    """Returns the relative path (from the images directory) to the original file
    used when construction the sprite. This is suitable for passing to the
    image_width and image_height helpers."""
    map = map.render()
    sprite_maps = _get_cache('sprite_maps')
    sprite_map = sprite_maps.get(map)
    sprite_name = String.unquoted(sprite).value
    sprite = sprite_map and sprite_map.get(sprite_name)
    if not sprite_map:
        log.error('No sprite map found: %s', map, extra={'stack': True})
    elif not sprite:
        log.error('No sprite found: %s in %s', sprite_name, sprite_map['*n*'], extra={'stack': True})
    if sprite:
        return String(sprite[1][0])
    return String.unquoted('')

def sprite(map, sprite, offset_x=None, offset_y=None, cache_buster=True):
    """Returns the image and background position for use in a single shorthand
    property"""
    map = map.render()
    sprite_maps = _get_cache('sprite_maps')
    sprite_map = sprite_maps.get(map)
    sprite_name = String.unquoted(sprite).value
    sprite = sprite_map and sprite_map.get(sprite_name)
    if not sprite_map:
        log.error('No sprite map found: %s', map, extra={'stack': True})
    elif not sprite:
        log.error('No sprite found: %s in %s', sprite_name, sprite_map['*n*'], extra={'stack': True})
    if sprite:
        url = '%s%s' % (config.ASSETS_URL, sprite_map['*f*'])
        if cache_buster:
            url += '?_=%s' % sprite_map['*t*']
        x = Number(offset_x or 0, 'px')
        y = Number(offset_y or 0, 'px')
        if not x.value or ((x.value <= -1 or x.value >= 1) and (not x.is_simple_unit('%'))):
            x -= Number(sprite[2], 'px')
        if not y.value or ((y.value <= -1 or y.value >= 1) and (not y.is_simple_unit('%'))):
            y -= Number(sprite[3], 'px')
        url = 'url(%s)' % escape(url)
        return List([String.unquoted(url), x, y])
    return List([Number(0), Number(0)])

def sprite_url(map, cache_buster=True):
    """Returns a url to the sprite image."""
    map = map.render()
    sprite_maps = _get_cache('sprite_maps')
    sprite_map = sprite_maps.get(map)
    if not sprite_map:
        log.error('No sprite map found: %s', map, extra={'stack': True})
    if sprite_map:
        url = '%s%s' % (config.ASSETS_URL, sprite_map['*f*'])
        if cache_buster:
            url += '?_=%s' % sprite_map['*t*']
        url = 'url(%s)' % escape(url)
        return String.unquoted(url)
    return String.unquoted('')

def inline_image(image, mime_type=None, dst_color=None, src_color=None, spacing=None, collapse_x=None, collapse_y=None):
    """Embeds the contents of a file directly inside your stylesheet, eliminating
    the need for another HTTP request. For small files such images or fonts,
    this can be a performance benefit at the cost of a larger generated CSS
    file."""
    return _image_url(image, False, False, dst_color, src_color, True, mime_type, spacing, collapse_x, collapse_y)

def image_url(path, only_path=False, cache_buster=True, dst_color=None, src_color=None, spacing=None, collapse_x=None, collapse_y=None):
    """Generates a path to an asset found relative to the project's images
    directory.
    Passing a true value as the second argument will cause the only the path to
