def image_height(image):
    """Returns the height of the image found at the path supplied by `image`
    relative to your project's images directory."""
    image_size_cache = _get_cache('image_size_cache')
    if not Image:
        raise SassMissingDependency('PIL', 'image manipulation')
    filepath = String.unquoted(image).value
    path = None
    try:
        height = image_size_cache[filepath][1]
    except KeyError:
        height = 0
        IMAGES_ROOT = _images_root()
        if callable(IMAGES_ROOT):
            try:
                _file, _storage = list(IMAGES_ROOT(filepath))[0]
            except IndexError:
                pass
            else:
                path = _storage.open(_file)
        else:
            _path = os.path.join(IMAGES_ROOT, filepath.strip(os.sep))
            if os.path.exists(_path):
                path = open(_path, 'rb')
        if path:
            image = Image.open(path)
            size = image.size
            height = size[1]
            image_size_cache[filepath] = size
    return Number(height, 'px')

def server_extensions_handshake(requested, supported):
    """Agree on the extensions to use returning an appropriate header value.

    This returns None if there are no agreed extensions"""
    accepts = {}
    for offer in requested:
        name = offer.split(';', 1)[0].strip()
        for extension in supported:
            if extension.name == name:
                accept = extension.accept(offer)
                if accept is True:
                    accepts[extension.name] = True
                elif accept is not False and accept is not None:
                    accepts[extension.name] = accept.encode('ascii')
    if accepts:
        extensions = []
        for name, params in accepts.items():
            if params is True:
                extensions.append(name.encode('ascii'))
            else:
                params = params.decode('ascii')
                if params == '':
                    extensions.append(('%s' % name).encode('ascii'))
                else:
                    extensions.append(('%s; %s' % (name, params)).encode('ascii'))
        return b', '.join(extensions)
    return None

