def check_cli_version():
    """Check if the current cli version satisfies the server requirements"""
    should_exit = False
    server_version = VersionClient().get_cli_version()
    current_version = get_cli_version()
    if LooseVersion(current_version) < LooseVersion(server_version.min_version):
        print('\nYour version of CLI (%s) is no longer compatible with server.' % current_version)
        should_exit = True
    elif LooseVersion(current_version) < LooseVersion(server_version.latest_version):
        print('\nNew version of CLI (%s) is now available.' % server_version.latest_version)
    else:
        return
    if should_exit and click.confirm('\nDo you want to upgrade to version %s now?' % server_version.latest_version):
        auto_upgrade()
        sys.exit(0)
    else:
        msg_parts = []
        msg_parts.append('\nTo manually upgrade run:')
        msg_parts.append('    pip install -U floyd-cli')
        if is_conda_env():
            msg_parts.append('Or if you prefer to use conda:')
            msg_parts.append('    conda install -y -c conda-forge -c floydhub floyd-cli')
        print('\n'.join(msg_parts))
        print('')
    if should_exit:
        sys.exit(0)

def get_unignored_file_paths(ignore_list=None, whitelist=None):
    """Given an ignore_list and a whitelist of glob patterns, returns the list of
    unignored file paths in the current directory and its subdirectories"""
    unignored_files = []
    if ignore_list is None:
        ignore_list = []
    if whitelist is None:
        whitelist = []
    for root, dirs, files in os.walk('.'):
        floyd_logger.debug('Root:%s, Dirs:%s', root, dirs)
        if ignore_path(unix_style_path(root), ignore_list, whitelist):
            dirs[:] = []
            floyd_logger.debug('Ignoring directory : %s', root)
            continue
        for file_name in files:
            file_path = unix_style_path(os.path.join(root, file_name))
            if ignore_path(file_path, ignore_list, whitelist):
                floyd_logger.debug('Ignoring file : %s', file_name)
                continue
            unignored_files.append(os.path.join(root, file_name))
    return unignored_files

def ignore_path(path, ignore_list=None, whitelist=None):
    """Returns a boolean indicating if a path should be ignored given an
    ignore_list and a whitelist of glob patterns."""
    if ignore_list is None:
        return True
    should_ignore = matches_glob_list(path, ignore_list)
    if whitelist is None:
        return should_ignore
    return should_ignore and (not matches_glob_list(path, whitelist))

def matches_glob_list(path, glob_list):
    """Given a list of glob patterns, returns a boolean
    indicating if a path matches any glob in the list"""
    for glob in glob_list:
        try:
            if PurePath(path).match(glob):
                return True
        except TypeError:
            pass
    return False

def pretty_date(time=False):
    """Get a datetime object or a int() Epoch timestamp and return a
    pretty string like 'an hour ago', 'Yesterday', '3 months ago',
    'just now', etc"""
    now = datetime.now(PST_TIMEZONE)
    if type(time) is int:
        diff = now - datetime.fromtimestamp(time)
    elif isinstance(time, datetime):
        diff = now - time
    elif not time:
        diff = now - now
    second_diff = diff.seconds
    day_diff = diff.days
    if day_diff < 0:
        return ''
    if day_diff == 0:
        if second_diff < 10:
            return 'just now'
        if second_diff < 60:
            return str(second_diff) + ' seconds ago'
        if second_diff < 120:
            return 'a minute ago'
        if second_diff < 3600:
            return str(int(second_diff / 60)) + ' minutes ago'
        if second_diff < 7200:
            return 'an hour ago'
        if second_diff < 86400:
            return str(int(second_diff / 3600)) + ' hours ago'
    if day_diff == 1:
        return 'Yesterday'
    if day_diff < 7:
        return str(day_diff) + ' days ago'
    if day_diff < 31:
        return str(int(day_diff / 7)) + ' weeks ago'
    if day_diff < 365:
        return str(int(day_diff / 30)) + ' months ago'
    return str(int(day_diff / 365)) + ' years ago'

def get_command_line(instance_type, env, message, data, mode, open_notebook, command_str):
    """Return a string representing the full floyd command entered in the command line"""
    floyd_command = ['floyd', 'run']
    if instance_type:
        floyd_command.append('--' + INSTANCE_NAME_MAP[instance_type])
    if env and (not env == DEFAULT_ENV):
        floyd_command += ['--env', env]
    if message:
        floyd_command += ['--message', shell_quote(message)]
    if data:
        for data_item in data:
            parts = data_item.split(':')
            if len(parts) > 1:
                data_item = normalize_data_name(parts[0], use_data_config=False) + ':' + parts[1]
            floyd_command += ['--data', data_item]
    if mode and mode != 'job':
        floyd_command += ['--mode', mode]
        if mode == 'jupyter':
            if not open_notebook:
                floyd_command.append('--no-open')
    elif command_str:
        floyd_command.append(shell_quote(command_str))
    return ' '.join(floyd_command)

def positions_binning(records):
    """Bin records by chunks of 30 minutes, returning the most prevalent position.

    If multiple positions have the same number of occurrences
    (during 30 minutes), we select the last one."""
    def get_key(d):
        return (d.year, d.day, d.hour, d.minute // 30)
    chunks = itertools.groupby(records, key=lambda r: get_key(r.datetime))
    for _, items in chunks:
        positions = [i.position for i in items]
        yield max(positions, key=positions.count)

def _group_range(records, method):
    """Yield the range of all dates between the extrema of
    a list of records, separated by a given time delta."""
    start_date = records[0].datetime
    end_date = records[-1].datetime
    _fun = DATE_GROUPERS[method]
    d = start_date
    if method not in ['month', 'year']:
        def increment(i):
            return i + timedelta(**{method + 's': 1})
    elif method == 'month':
        def increment(i):
            year, month = divmod(i.month + 1, 12)
            if month == 0:
                month = 12
                year = year - 1
            return d.replace(year=d.year + year, month=month)
    elif method == 'year':
        def increment(i):
            return d.replace(year=d.year + 1)
    while _fun(d) <= _fun(end_date):
        yield d
        d = increment(d)

def infer_type(data):
    """Infer the type of objects returned by indicators.

    infer_type returns:
     - 'scalar' for a number or None,
     - 'summarystats' for a SummaryStats object,
     - 'distribution_scalar' for a list of scalars,
     - 'distribution_summarystats' for a list of SummaryStats objects"""
    if isinstance(data, (type(None), numbers.Number)):
        return 'scalar'
    if isinstance(data, SummaryStats):
        return 'summarystats'
    if hasattr(data, '__len__'):
        data = [x for x in data if x is not None]
        if len(data) == 0 or isinstance(data[0], numbers.Number):
            return 'distribution_scalar'
        if isinstance(data[0], SummaryStats):
            return 'distribution_summarystats'
        raise TypeError('{} is not a valid input. It should be a number, a SummaryStats object, or None'.format(data[0]))
    raise TypeError('{} is not a valid input. It should be a number, a SummaryStats object, or a list'.format(data))

def entropy(data):
    """Compute the Shannon entropy, a measure of uncertainty."""
    if len(data) == 0:
        return None
    n = sum(data)
    _op = lambda f: f * math.log(f)
    return -sum((_op(float(i) / n) for i in data))

def percent_records_missing_location(user, method=None):
    """Return the percentage of records missing a location parameter."""
    if len(user.records) == 0:
        return 0.0
    missing_locations = sum([1 for record in user.records if record.position._get_location(user) is None])
    return float(missing_locations) / len(user.records)

def percent_overlapping_calls(records, min_gab=300):
    """Return the percentage of calls that overlap with the next call.

    Parameters
    ----------
    records : list
        The records for a single user.
    min_gab : int
        Number of seconds that the calls must overlap to be considered an issue.
        Defaults to 5 minutes."""
    calls = [r for r in records if r.interaction == 'call']
    if len(calls) == 0:
        return 0.0
    overlapping_calls = 0
    for i, r in enumerate(calls):
        if i <= len(calls) - 2:
            if r.datetime + timedelta(seconds=r.call_duration - min_gab) >= calls[i + 1].datetime:
                overlapping_calls += 1
    return float(overlapping_calls) / len(calls)

def antennas_missing_locations(user, Method=None):
    """Return the number of antennas missing locations in the records of a given user."""
    unique_antennas = set([record.position.antenna for record in user.records if record.position.antenna is not None])
    return sum([1 for antenna in unique_antennas if user.antennas.get(antenna) is None])

def bandicoot_code_signature():
    """Returns a unique hash of the Python source code in the current bandicoot
    module, using the cryptographic hash function SHA-1."""
    checksum = hashlib.sha1()
    for root, dirs, files in os.walk(MAIN_DIRECTORY):
        for filename in sorted(files):
            if not filename.endswith('.py'):
                continue
            f_path = os.path.join(root, filename)
            f_size = os.path.getsize(f_path)
            with open(f_path, 'rb') as f:
                while f.tell() != f_size:
                    checksum.update(f.read(262144))
    return checksum.hexdigest()

def entropy_of_antennas(positions, normalize=False):
    """The entropy of visited antennas.

    Parameters
    ----------
    normalize: boolean, default is False
        Returns a normalized entropy between 0 and 1."""
    counter = Counter((p for p in positions))
    raw_entropy = entropy(list(counter.values()))
    n = len(counter)
    if normalize and n > 1:
        return raw_entropy / math.log(n)
    else:
        return raw_entropy

def frequent_antennas(positions, percentage=0.8):
    """The number of location that account for 80% of the locations where the user was.
    Percentage can be supplied as a decimal (e.g., .8 for default 80%)."""
    location_count = Counter(list(map(str, positions)))
    target = math.ceil(sum(location_count.values()) * percentage)
    location_sort = sorted(list(location_count.keys()), key=lambda x: location_count[x])
    while target > 0 and len(location_sort) > 0:
        location_id = location_sort.pop()
        target -= location_count[location_id]
    return len(location_count) - len(location_sort)

def churn_rate(user, summary='default', **kwargs):
    """Computes the frequency spent at every towers each week, and returns the
    distribution of the cosine similarity between two consecutives week.

    .. note:: The churn rate is always computed between pairs of weeks."""
    if len(user.records) == 0:
        return statistics([], summary=summary)
    query = {'groupby': 'week', 'divide_by': OrderedDict([('part_of_week', ['allweek']), ('part_of_day', ['allday'])]), 'using': 'records', 'filter_empty': True, 'binning': True}
    rv = grouping_query(user, query)
    weekly_positions = rv[0][1]
    all_positions = list(set((p for l in weekly_positions for p in l)))
    frequencies = {}
    cos_dist = []
    for week, week_positions in enumerate(weekly_positions):
        count = Counter(week_positions)
        total = sum(count.values())
        frequencies[week] = [count.get(p, 0) / total for p in all_positions]
    all_indexes = range(len(all_positions))
    for f_1, f_2 in pairwise(list(frequencies.values())):
        num = sum((f_1[a] * f_2[a] for a in all_indexes))
        denom_1 = sum((f ** 2 for f in f_1))
        denom_2 = sum((f ** 2 for f in f_2))
        cos_dist.append(1 - num / (denom_1 ** 0.5 * denom_2 ** 0.5))
    return statistics(cos_dist, summary=summary)

def flatten(d, parent_key='', separator='__'):
    """Flatten a nested dictionary.

    Parameters
    ----------
    d: dict_like
        Dictionary to flatten.
    parent_key: string, optional
        Concatenated names of the parent keys.
    separator: string, optional
        Separator between the names of the each key.
        The default separator is '_'.

    Examples
    --------

    >>> d = {'alpha': 1, 'beta': {'a': 10, 'b': 42}}
    >>> flatten(d) == {'alpha': 1, 'beta_a': 10, 'beta_b': 42}
    True
    >>> flatten(d, separator='.') == {'alpha': 1, 'beta.a': 10, 'beta.b': 42}
    True"""
    items = []
    for k, v in d.items():
        new_key = parent_key + separator + k if parent_key else k
        if isinstance(v, (dict, OrderedDict)):
            items.extend(flatten(v, new_key, separator).items())
        else:
            items.append((new_key, v))
    return OrderedDict(items)

def interevent_time_recharges(recharges):
    """Return the distribution of time between consecutive recharges
    of the user."""
    time_pairs = pairwise((r.datetime for r in recharges))
    times = [(new - old).total_seconds() for old, new in time_pairs]
    return summary_stats(times)

def percent_pareto_recharges(recharges, percentage=0.8):
    """Percentage of recharges that account for 80% of total recharged amount."""
    amounts = sorted([r.amount for r in recharges], reverse=True)
    total_sum = sum(amounts)
    partial_sum = 0
    for count, a in enumerate(amounts):
        partial_sum += a
        if partial_sum >= percentage * total_sum:
            break
    return (count + 1) / len(recharges)

def _round_half_hour(record):
    """Round a time DOWN to half nearest half-hour."""
    k = record.datetime + timedelta(minutes=-(record.datetime.minute % 30))
    return datetime(k.year, k.month, k.day, k.hour, k.minute, 0)

def matrix_directed_unweighted(user):
    """Returns a directed, unweighted matrix where an edge exists if there is at
    least one call or text."""
    matrix = _interaction_matrix(user, interaction=None)
    for a in range(len(matrix)):
        for b in range(len(matrix)):
            if matrix[a][b] is not None and matrix[a][b] > 0:
                matrix[a][b] = 1
    return matrix

def matrix_undirected_weighted(user, interaction=None):
    """Returns an undirected, weighted matrix for call, text and call duration
    where an edge exists if the relationship is reciprocated."""
    matrix = _interaction_matrix(user, interaction=interaction)
    result = [[0 for _ in range(len(matrix))] for _ in range(len(matrix))]
    for a in range(len(matrix)):
        for b in range(len(matrix)):
            if a != b and matrix[a][b] and matrix[b][a]:
                result[a][b] = matrix[a][b] + matrix[b][a]
            elif matrix[a][b] is None or matrix[b][a] is None:
                result[a][b] = None
            else:
                result[a][b] = 0
    return result

def matrix_undirected_unweighted(user):
    """Returns an undirected, unweighted matrix where an edge exists if the
    relationship is reciprocated."""
    matrix = matrix_undirected_weighted(user, interaction=None)
    for a, b in combinations(range(len(matrix)), 2):
        if matrix[a][b] is None or matrix[b][a] is None:
            continue
        if matrix[a][b] > 0 and matrix[b][a] > 0:
            matrix[a][b], matrix[b][a] = (1, 1)
    return matrix

def assortativity_attributes(user):
    """Computes the assortativity of the nominal attributes.

    This indicator measures the homophily of the current user with his
    correspondants, for each attributes. It returns a value between 0
    (no assortativity) and 1 (all the contacts share the same value):
    the percentage of contacts sharing the same value."""
    matrix = matrix_undirected_unweighted(user)
    neighbors = [k for k in user.network.keys() if k != user.name]
    neighbors_attrbs = {}
    for i, u_name in enumerate(matrix_index(user)):
        correspondent = user.network.get(u_name, None)
        if correspondent is None or u_name == user.name or matrix[0][i] == 0:
            continue
        if correspondent.has_attributes:
            neighbors_attrbs[correspondent.name] = correspondent.attributes
    assortativity = {}
    for a in user.attributes:
        total = sum((1 for n in neighbors if n in neighbors_attrbs and user.attributes[a] == neighbors_attrbs[n][a]))
        den = sum((1 for n in neighbors if n in neighbors_attrbs))
        assortativity[a] = total / den if den != 0 else None
    return assortativity

def _parse_record(data, duration_format='seconds'):
    """Parse a raw data dictionary and return a Record object."""
    def _map_duration(s):
        if s == '':
            return None
        elif duration_format.lower() == 'seconds':
            return int(s)
        else:
            t = time.strptime(s, duration_format)
            return 3600 * t.tm_hour + 60 * t.tm_min + t.tm_sec
    def _map_position(data):
        antenna = Position()
        if 'antenna_id' in data and data['antenna_id']:
            antenna.antenna = data['antenna_id']
        if 'place_id' in data:
            raise NameError("Use field name 'antenna_id' in input files. 'place_id' is deprecated.")
        if 'latitude' in data and 'longitude' in data:
            latitude = data['latitude']
            longitude = data['longitude']
            if latitude and longitude:
                antenna.location = (float(latitude), float(longitude))
        return antenna
    return Record(interaction=data['interaction'] if data['interaction'] else None, direction=data['direction'], correspondent_id=data['correspondent_id'], datetime=_tryto(lambda x: datetime.strptime(x, '%Y-%m-%d %H:%M:%S'), data['datetime']), call_duration=_tryto(_map_duration, data['call_duration']), position=_tryto(_map_position, data))

def entropy_of_contacts(records, normalize=False):
    """The entropy of the user's contacts.

    Parameters
    ----------
    normalize: boolean, default is False
        Returns a normalized entropy between 0 and 1."""
    counter = Counter((r.correspondent_id for r in records))
    raw_entropy = entropy(counter.values())
    n = len(counter)
    if normalize and n > 1:
        return raw_entropy / math.log(n)
    else:
        return raw_entropy

def interactions_per_contact(records, direction=None):
    """The number of interactions a user had with each of its contacts.

    Parameters
    ----------
    direction : str, optional
        Filters the records by their direction: ``None`` for all records,
        ``'in'`` for incoming, and ``'out'`` for outgoing."""
    if direction is None:
        counter = Counter((r.correspondent_id for r in records))
    else:
        counter = Counter((r.correspondent_id for r in records if r.direction == direction))
    return summary_stats(counter.values())

def percent_initiated_interactions(records, user):
    """The percentage of calls initiated by the user."""
    if len(records) == 0:
        return 0
    initiated = sum((1 for r in records if r.direction == 'out'))
    return initiated / len(records)

def percent_nocturnal(records, user):
    """The percentage of interactions the user had at night.

    By default, nights are 7pm-7am. Nightimes can be set in
    ``User.night_start`` and ``User.night_end``."""
    if len(records) == 0:
        return 0
    if user.night_start < user.night_end:
        night_filter = lambda d: user.night_end > d.time() > user.night_start
    else:
        night_filter = lambda d: not user.night_end < d.time() < user.night_start
    return sum((1 for r in records if night_filter(r.datetime))) / len(records)

def call_duration(records, direction=None):
    """The duration of the user's calls.

    Parameters
    ----------
    direction : str, optional
        Filters the records by their direction: ``None`` for all records,
        ``'in'`` for incoming, and ``'out'`` for outgoing."""
    if direction is None:
        call_durations = [r.call_duration for r in records]
    else:
        call_durations = [r.call_duration for r in records if r.direction == direction]
    return summary_stats(call_durations)

def _conversations(group, delta=datetime.timedelta(hours=1)):
    """Group texts into conversations. The function returns an iterator over
    records grouped by conversations.

    See :ref:`Using bandicoot <conversations-label>` for a definition of
    conversations.

    A conversation begins when one person sends a text-message to the other and
    ends when one of them makes a phone call or there is no activity between
    them for an hour."""
    last_time = None
    results = []
    for g in group:
        if last_time is None or g.datetime - last_time < delta:
            if g.interaction == 'text':
                results.append(g)
            elif len(results) != 0:
                yield results
                results = []
        else:
            if len(results) != 0:
                yield results
            if g.interaction == 'call':
                results = []
            else:
                results = [g]
        last_time = g.datetime
    if len(results) != 0:
        yield results

def active_days(records):
    """The number of days during which the user was active. A user is considered
    active if he sends a text, receives a text, initiates a call, receives a
    call, or has a mobility point."""
    days = set((r.datetime.date() for r in records))
    return len(days)

def percent_pareto_interactions(records, percentage=0.8):
    """The percentage of user's contacts that account for 80% of its interactions."""
    if len(records) == 0:
        return None
    user_count = Counter((r.correspondent_id for r in records))
    target = int(math.ceil(sum(user_count.values()) * percentage))
    user_sort = sorted(user_count.keys(), key=lambda x: user_count[x])
    while target > 0 and len(user_sort) > 0:
        user_id = user_sort.pop()
        target -= user_count[user_id]
    return (len(user_count) - len(user_sort)) / len(records)

def percent_pareto_durations(records, percentage=0.8):
    """The percentage of user's contacts that account for 80% of its total time
    spend on the phone. Optionally takes a percentage argument as a decimal
    (e.g., .8 for 80%)."""
    if len(records) == 0:
        return None
    user_count = defaultdict(int)
    for r in records:
        if r.interaction == 'call':
            user_count[r.correspondent_id] += r.call_duration
    target = int(math.ceil(sum(user_count.values()) * percentage))
    user_sort = sorted(user_count.keys(), key=lambda x: user_count[x])
    while target > 0 and len(user_sort) > 0:
        user_id = user_sort.pop()
        target -= user_count[user_id]
    return (len(user_count) - len(user_sort)) / len(records)

def balance_of_contacts(records, weighted=True):
    """The balance of interactions per contact. For every contact,
    the balance is the number of outgoing interactions divided by the total
    number of interactions (in+out).

    .. math::

       \\forall \\,\\text{contact}\\,c,\\;\\text{balance}\\,(c) = \\frac{\\bigl|\\text{outgoing}\\,(c)\\bigr|}{\\bigl|\\text{outgoing}\\,(c)\\bigr|+\\bigl|\\text{incoming}\\,(c)\\bigr|}

    Parameters
    ----------
    weighted : str, optional
        If ``True``, the balance for each contact is weighted by
        the number of interactions the user had with this contact."""
    counter_out = defaultdict(int)
    counter = defaultdict(int)
    for r in records:
        if r.direction == 'out':
            counter_out[r.correspondent_id] += 1
        counter[r.correspondent_id] += 1
    if not weighted:
        balance = [counter_out[c] / counter[c] for c in counter]
    else:
        balance = [counter_out[c] / sum(counter.values()) for c in counter]
    return summary_stats(balance)

def number_of_interactions(records, direction=None):
    """The number of interactions.

    Parameters
    ----------
    direction : str, optional
        Filters the records by their direction: ``None`` for all records,
        ``'in'`` for incoming, and ``'out'`` for outgoing."""
    if direction is None:
        return len(records)
    else:
        return len([r for r in records if r.direction == direction])

def to_csv(weekmatrices, filename, digits=5):
    """Exports a list of week-matrices to a specified filename in the CSV format.

    Parameters
    ----------
    weekmatrices : list
        The week-matrices to export.
    filename : string
        Path for the exported CSV file."""
    with open(filename, 'w') as f:
        w = csv.writer(f, lineterminator='\n')
        w.writerow(['year_week', 'channel', 'weekday', 'section', 'value'])
        def make_repr(item):
            if item is None:
                return None
            elif isinstance(item, float):
                return repr(round(item, digits))
            else:
                return str(item)
        for row in weekmatrices:
            w.writerow([make_repr(item) for item in row])

def _seconds_to_section_split(record, sections):
    """Finds the seconds to the next section from the datetime of a record."""
    next_section = sections[bisect_right(sections, _find_weektime(record.datetime))] * 60
    return next_section - _find_weektime(record.datetime, time_type='sec')

def fix_location(records, max_elapsed_seconds=300):
    """Update position of all records based on the position of
    the closest GPS record.

    .. note:: Use this function when call and text records are missing a
              location, but you have access to accurate GPS traces."""
    groups = itertools.groupby(records, lambda r: r.direction)
    groups = [(interaction, list(g)) for interaction, g in groups]
    def tdist(t1, t2):
        return abs((t1 - t2).total_seconds())
    for i, (interaction, g) in enumerate(groups):
        if interaction == 'in':
            continue
        prev_gps = groups[i - 1][1][-1]
        next_gps = groups[i + 1][1][0]
        for r in g:
            if tdist(r.datetime, prev_gps.datetime) <= max_elapsed_seconds:
                r.position = prev_gps.position
            elif tdist(r.datetime, next_gps.datetime) <= max_elapsed_seconds:
                r.position = next_gps.position

def _self_signed(cert):
    """Determines if a certificate is self-signed

    :param cert:
        An asn1crypto.x509.Certificate object to check

    :return:
        A boolean - True if the certificate is self-signed, False otherwise"""
    self_signed = cert.self_signed
    if self_signed == 'yes':
        return True
    if self_signed == 'no':
        return False
    signature_algo = cert['signature_algorithm'].signature_algo
    hash_algo = cert['signature_algorithm'].hash_algo
    if signature_algo == 'rsassa_pkcs1v15':
        verify_func = asymmetric.rsa_pkcs1v15_verify
    elif signature_algo == 'dsa':
        verify_func = asymmetric.dsa_verify
    elif signature_algo == 'ecdsa':
        verify_func = asymmetric.ecdsa_verify
    else:
        raise PathValidationError(pretty_message('\n            Unable to verify the signature of the certificate since it uses\n            the unsupported algorithm %s\n            ', signature_algo))
    try:
        key_object = asymmetric.load_certificate(cert)
        verify_func(key_object, cert['signature_value'].native, cert['tbs_certificate'].dump(), hash_algo)
        return True
    except oscrypto.errors.SignatureError:
        return False

def _verify_signature(certificate_list, crl_issuer):
    """Verifies the digital signature on an asn1crypto.crl.CertificateList object

    :param certificate_list:
        An asn1crypto.crl.CertificateList object

    :param crl_issuer:
        An asn1crypto.x509.Certificate object of the CRL issuer

    :raises:
        certvalidator.errors.CRLValidationError - when the signature is invalid or uses an unsupported algorithm"""
    signature_algo = certificate_list['signature_algorithm'].signature_algo
    hash_algo = certificate_list['signature_algorithm'].hash_algo
    if signature_algo == 'rsassa_pkcs1v15':
        verify_func = asymmetric.rsa_pkcs1v15_verify
    elif signature_algo == 'dsa':
        verify_func = asymmetric.dsa_verify
    elif signature_algo == 'ecdsa':
        verify_func = asymmetric.ecdsa_verify
    else:
        raise CRLValidationError(pretty_message('\n            Unable to verify the CertificateList since the signature uses the\n            unsupported algorithm %s\n            ', signature_algo))
    try:
        key_object = asymmetric.load_certificate(crl_issuer)
        verify_func(key_object, certificate_list['signature'].native, certificate_list['tbs_cert_list'].dump(), hash_algo)
    except oscrypto.errors.SignatureError:
        raise CRLValidationError('Unable to verify the signature of the CertificateList')

def is_castable(src, dst):
    """Check if src type can be cast to dst type"""
    if (src in [int, bool] or rdltypes.is_user_enum(src)) and dst in [int, bool]:
        return True
    elif src == rdltypes.ArrayPlaceholder and dst == rdltypes.ArrayPlaceholder:
        if src.element_type is None:
            return True
        elif src.element_type == dst.element_type:
            return True
        else:
            return False
    elif rdltypes.is_user_struct(dst):
        return issubclass(src, dst)
    elif dst == rdltypes.PropertyReference:
        return issubclass(src, rdltypes.PropertyReference)
    elif src == dst:
        return True
    else:
        return False

def get_group_node_size(node):
    """Shared getter for AddrmapNode and RegfileNode's "size" property"""
    if not node.inst.children or not isinstance(node.inst.children[-1], comp.AddressableComponent):
        return 0
    last_child_node = Node._factory(node.inst.children[-1], node.env, node)
    return last_child_node.inst.addr_offset + last_child_node.total_size

def get_rdltype(value):
    """Given a value, return the type identifier object used within the RDL compiler
    If not a supported type, return None"""
    if isinstance(value, (int, bool, str)):
        return type(value)
    elif is_user_enum(type(value)):
        return type(value)
    elif is_user_struct(type(value)):
        return type(value)
    elif isinstance(value, enum.Enum):
        return type(value)
    elif isinstance(value, list):
        array_el_type = None
        for el in value:
            el_type = get_rdltype(el)
            if el_type is None:
                return None
            if array_el_type is not None and el_type != array_el_type:
                return None
            array_el_type = el_type
        return ArrayPlaceholder(array_el_type)
    else:
        return None

def get_ID_text(token):
    """Get the text from the ID token.
    Strips off leading slash escape if present"""
    if isinstance(token, CommonToken):
        text = token.text
    else:
        text = token.getText()
    text = text.lstrip('\\')
    return text

def get_function(fn_name):
    """Retrieve the function defined by the function_name.

    Arguments:
      fn_name: specification of the type module:function_name."""
    module_name, callable_name = fn_name.split(':')
    current = globals()
    if not callable_name:
        callable_name = module_name
    else:
        import importlib
        try:
            module = importlib.import_module(module_name)
        except ImportError:
            log.error('failed to import %s', module_name)
            raise
        current = module
    for level in callable_name.split('.'):
        current = getattr(current, level)
    code = current.__code__
    if code.co_argcount != 2:
        raise ValueError('function should take 2 arguments: lines, file_name')
    return current

def get_paths(patterns, start_dirs=None, max_depth=1):
    """Retrieve files that match any of the patterns."""
    if len(patterns) == 1 and (not start_dirs):
        pattern = patterns[0]
        directory = os.path.dirname(pattern)
        if directory:
            patterns = [os.path.basename(pattern)]
            start_dirs = directory
            max_depth = 1
    if not start_dirs or start_dirs == '.':
        start_dirs = os.getcwd()
    for start_dir in start_dirs.split(','):
        for root, dirs, files in os.walk(start_dir):
            if max_depth is not None:
                relpath = os.path.relpath(root, start=start_dir)
                depth = len(relpath.split(os.sep))
                if depth > max_depth:
                    continue
            names = []
            for pattern in patterns:
                names += fnmatch.filter(files, pattern)
            for name in names:
                path = os.path.join(root, name)
                yield path

def format_msg(external_id, external_id_prop, wdid, msg, msg_type=None, delimiter=';'):
    """Format message for logging
    :return: str"""
    fmt = ('{}' + delimiter) * 4 + '{}'
    d = {'external_id': external_id, 'external_id_prop': external_id_prop, 'wdid': wdid, 'msg': msg, 'msg_type': msg_type}
    for k, v in d.items():
        if isinstance(v, str) and delimiter in v and ('"' in v):
            v = v.replace('"', "'")
        if isinstance(v, str) and delimiter in v:
            d[k] = '"' + v + '"'
    s = fmt.format(d['external_id'], d['external_id_prop'], d['wdid'], d['msg'], d['msg_type'])
    return s

def joint(*parsers):
    """Joint two or more parsers, implements the operator of `(+)`."""
    @Parser
    def joint_parser(text, index):
        values = []
        prev_v = None
        for p in parsers:
            if prev_v:
                index = prev_v.index
            prev_v = v = p(text, index)
            if not v.status:
                return v
            values.append(v)
        return Value.combinate(values)
    return joint_parser

def times(p, mint, maxt=None):
    """Repeat a parser between `mint` and `maxt` times. DO AS MUCH MATCH AS IT CAN.
    Return a list of values."""
    maxt = maxt if maxt else mint
    @Parser
    def times_parser(text, index):
        cnt, values, res = (0, Value.success(index, []), None)
        while cnt < maxt:
            res = p(text, index)
            if res.status:
                values = values.aggregate(Value.success(res.index, [res.value]))
                index, cnt = (res.index, cnt + 1)
            elif cnt >= mint:
                break
            else:
                return res
            if cnt >= maxt:
                break
            if index >= len(text):
                if cnt >= mint:
                    break
                else:
                    r = p(text, index)
                    if index != r.index:
                        return Value.failure(index, 'already meets the end, no enough text')
        return values
    return times_parser

def optional(p, default_value=None):
    """`Make a parser as optional. If success, return the result, otherwise return
    default_value silently, without raising any exception. If default_value is not
    provided None is returned instead."""
    @Parser
    def optional_parser(text, index):
        res = p(text, index)
        if res.status:
            return Value.success(res.index, res.value)
        else:
            return Value.success(res.index, default_value)
    return optional_parser

def sepBy(p, sep):
    """`sepBy(p, sep)` parses zero or more occurrences of p, separated by `sep`.
    Returns a list of values returned by `p`."""
    return separated(p, sep, 0, maxt=float('inf'), end=False)

def sepBy1(p, sep):
    """`sepBy1(p, sep)` parses one or more occurrences of `p`, separated by
    `sep`. Returns a list of values returned by `p`."""
    return separated(p, sep, 1, maxt=float('inf'), end=False)

def endBy(p, sep):
    """`endBy(p, sep)` parses zero or more occurrences of `p`, separated and
    ended by `sep`. Returns a list of values returned by `p`."""
    return separated(p, sep, 0, maxt=float('inf'), end=True)

def endBy1(p, sep):
    """`endBy1(p, sep) parses one or more occurrences of `p`, separated and
    ended by `sep`. Returns a list of values returned by `p`."""
    return separated(p, sep, 1, maxt=float('inf'), end=True)

def one_of(s):
    """Parser a char from specified string."""
    @Parser
    def one_of_parser(text, index=0):
        if index < len(text) and text[index] in s:
            return Value.success(index + 1, text[index])
        else:
            return Value.failure(index, 'one of {}'.format(s))
    return one_of_parser

def none_of(s):
    """Parser a char NOT from specified string."""
    @Parser
    def none_of_parser(text, index=0):
        if index < len(text) and text[index] not in s:
            return Value.success(index + 1, text[index])
        else:
            return Value.failure(index, 'none of {}'.format(s))
    return none_of_parser

def space():
    """Parser a whitespace character."""
    @Parser
    def space_parser(text, index=0):
        if index < len(text) and text[index].isspace():
            return Value.success(index + 1, text[index])
        else:
            return Value.failure(index, 'one space')
    return space_parser

def letter():
    """Parse a letter in alphabet."""
    @Parser
    def letter_parser(text, index=0):
        if index < len(text) and text[index].isalpha():
            return Value.success(index + 1, text[index])
        else:
            return Value.failure(index, 'a letter')
    return letter_parser

def digit():
    """Parse a digit character."""
    @Parser
    def digit_parser(text, index=0):
        if index < len(text) and text[index].isdigit():
            return Value.success(index + 1, text[index])
        else:
            return Value.failure(index, 'a digit')
    return digit_parser

def eof():
    """Parser EOF flag of a string."""
    @Parser
    def eof_parser(text, index=0):
        if index >= len(text):
            return Value.success(index, None)
        else:
            return Value.failure(index, 'EOF')
    return eof_parser

def string(s):
    """Parser a string."""
    @Parser
    def string_parser(text, index=0):
        slen, tlen = (len(s), len(text))
        if text[index:index + slen] == s:
            return Value.success(index + slen, s)
        else:
            matched = 0
            while matched < slen and index + matched < tlen and (text[index + matched] == s[matched]):
                matched = matched + 1
            return Value.failure(index + matched, s)
    return string_parser

def charseq():
    """Parse string. (normal string and escaped string)"""
    def string_part():
        """Parse normal string."""
        return regex('[^"\\\\]+')
    def string_esc():
        """Parse escaped string."""
        return string('\\') >> (string('\\') | string('/') | string('"') | string('b').result('\x08') | string('f').result('\x0c') | string('n').result('\n') | string('r').result('\r') | string('t').result('\t') | regex('u[0-9a-fA-F]{4}').parsecmap(lambda s: chr(int(s[1:], 16))))
    return string_part() | string_esc()

def lookup_controller(obj, remainder, request=None):
    """Traverses the requested url path and returns the appropriate controller
    object, including default routes.

    Handles common errors gracefully."""
    if request is None:
        warnings.warn('The function signature for %s.lookup_controller is changing in the next version of pecan.\nPlease update to: `lookup_controller(self, obj, remainder, request)`.' % (__name__,), DeprecationWarning)
    notfound_handlers = []
    while True:
        try:
            obj, remainder = find_object(obj, remainder, notfound_handlers, request)
            handle_security(obj)
            return (obj, remainder)
        except (exc.HTTPNotFound, exc.HTTPMethodNotAllowed, PecanNotFound) as e:
            if isinstance(e, PecanNotFound):
                e = exc.HTTPNotFound()
            while notfound_handlers:
                name, obj, remainder = notfound_handlers.pop()
                if name == '_default':
                    return (obj, remainder)
                else:
                    result = handle_lookup_traversal(obj, remainder)
                    if result:
                        if remainder == [''] and len(obj._pecan['argspec'].args) > 1:
                            raise e
                        obj_, remainder_ = result
                        return lookup_controller(obj_, remainder_, request)
            else:
                raise e

def unlocked(func_or_obj):
    """This method unlocks method or class attribute on a SecureController.  Can
    be used to decorate or wrap an attribute"""
    if ismethod(func_or_obj) or isfunction(func_or_obj):
        return _unlocked_method(func_or_obj)
    else:
        return _UnlockedAttribute(func_or_obj)

def secure(func_or_obj, check_permissions_for_obj=None):
    """This method secures a method or class depending on invocation.

    To decorate a method use one argument:
        @secure(<check_permissions_method>)

    To secure a class, invoke with two arguments:
        secure(<obj instance>, <check_permissions_method>)"""
    if _allowed_check_permissions_types(func_or_obj):
        return _secure_method(func_or_obj)
    else:
        if not _allowed_check_permissions_types(check_permissions_for_obj):
            msg = 'When securing an object, secure() requires the ' + 'second argument to be method'
            raise TypeError(msg)
        return _SecuredAttribute(func_or_obj, check_permissions_for_obj)

def _make_wrapper(f):
    """return a wrapped function with a copy of the _pecan context"""
    @wraps(f)
    def wrapper(*args, **kwargs):
        return f(*args, **kwargs)
    wrapper._pecan = f._pecan.copy()
    return wrapper

def handle_security(controller, im_self=None):
    """Checks the security of a controller."""
    if controller._pecan.get('secured', False):
        check_permissions = controller._pecan['check_permissions']
        if isinstance(check_permissions, six.string_types):
            check_permissions = getattr(im_self or six.get_method_self(controller), check_permissions)
        if not check_permissions():
            raise exc.HTTPUnauthorized

def cross_boundary(prev_obj, obj):
    """Check permissions as we move between object instances."""
    if prev_obj is None:
        return
    if isinstance(obj, _SecuredAttribute):
        obj.parent = prev_obj
    if hasattr(prev_obj, '_pecan'):
        if obj not in prev_obj._pecan.get('unlocked', []):
            handle_security(prev_obj)

def makedirs(directory):
    """Resursively create a named directory."""
    parent = os.path.dirname(os.path.abspath(directory))
    if not os.path.exists(parent):
        makedirs(parent)
    os.mkdir(directory)

def substitute_filename(fn, variables):
    """Substitute +variables+ in file directory names."""
    for var, value in variables.items():
        fn = fn.replace('+%s+' % var, str(value))
    return fn

def render_template(content, variables):
    """Return a bytestring representing a templated file based on the
    input (content) and the variable names defined (vars)."""
    fsenc = sys.getfilesystemencoding()
    def to_native(s, encoding='latin-1', errors='strict'):
        if six.PY3:
            if isinstance(s, six.text_type):
                return s
            return str(s, encoding, errors)
        else:
            if isinstance(s, six.text_type):
                return s.encode(encoding, errors)
            return str(s)
    output = Template(to_native(content, fsenc)).substitute(variables)
    if isinstance(output, six.text_type):
        output = output.encode(fsenc, 'strict')
    return output

def conf_from_file(filepath):
    """Creates a configuration dictionary from a file.

    :param filepath: The path to the file."""
    abspath = os.path.abspath(os.path.expanduser(filepath))
    conf_dict = {}
    if not os.path.isfile(abspath):
        raise RuntimeError('`%s` is not a file.' % abspath)
    with open(abspath, 'rb') as f:
        compiled = compile(f.read(), abspath, 'exec')
    absname, _ = os.path.splitext(abspath)
    basepath, module_name = absname.rsplit(os.sep, 1)
    if six.PY3:
        SourceFileLoader(module_name, abspath).load_module(module_name)
    else:
        imp.load_module(module_name, *imp.find_module(module_name, [basepath]))
    exec(compiled, globals(), conf_dict)
    conf_dict['__file__'] = abspath
    return conf_from_dict(conf_dict)

def get_conf_path_from_env():
    """If the ``PECAN_CONFIG`` environment variable exists and it points to
    a valid path it will return that, otherwise it will raise
    a ``RuntimeError``."""
    config_path = os.environ.get('PECAN_CONFIG')
    if not config_path:
        error = 'PECAN_CONFIG is not set and no config file was passed as an argument.'
    elif not os.path.isfile(config_path):
        error = 'PECAN_CONFIG was set to an invalid path: %s' % config_path
    else:
        return config_path
    raise RuntimeError(error)

def conf_from_dict(conf_dict):
    """Creates a configuration dictionary from a dictionary.

    :param conf_dict: The configuration dictionary."""
    conf = Config(filename=conf_dict.get('__file__', ''))
    for k, v in six.iteritems(conf_dict):
        if k.startswith('__'):
            continue
        elif inspect.ismodule(v):
            continue
        conf[k] = v
    return conf

def set_config(config, overwrite=False):
    """Updates the global configuration.

    :param config: Can be a dictionary containing configuration, or a string
                   which represents a (relative) configuration filename."""
    if config is None:
        config = get_conf_path_from_env()
    if overwrite is True:
        _runtime_conf.empty()
    if isinstance(config, six.string_types):
        config = conf_from_file(config)
        _runtime_conf.update(config)
        if config.__file__:
            _runtime_conf.__file__ = config.__file__
    elif isinstance(config, dict):
        _runtime_conf.update(conf_from_dict(config))
    else:
        raise TypeError('%s is neither a dictionary or a string.' % config)

def gunicorn_run():
    """The ``gunicorn_pecan`` command for launching ``pecan`` applications"""
    try:
        from gunicorn.app.wsgiapp import WSGIApplication
    except ImportError as exc:
        args = exc.args
        arg0 = args[0] if args else ''
        arg0 += ' (are you sure `gunicorn` is installed?)'
        exc.args = (arg0,) + args[1:]
        raise
    class PecanApplication(WSGIApplication):
        def init(self, parser, opts, args):
            if len(args) != 1:
                parser.error('No configuration file was specified.')
            self.cfgfname = os.path.normpath(os.path.join(os.getcwd(), args[0]))
            self.cfgfname = os.path.abspath(self.cfgfname)
            if not os.path.exists(self.cfgfname):
                parser.error('Config file not found: %s' % self.cfgfname)
            from pecan.configuration import _runtime_conf, set_config
            set_config(self.cfgfname, overwrite=True)
            cfg = {}
            if _runtime_conf.get('server'):
                server = _runtime_conf['server']
                if hasattr(server, 'host') and hasattr(server, 'port'):
                    cfg['bind'] = '%s:%s' % (server.host, server.port)
            return cfg
        def load(self):
            from pecan.deploy import deploy
            return deploy(self.cfgfname)
    PecanApplication('%(prog)s [OPTIONS] config.py').run()

def transactional(ignore_redirects=True):
    """If utilizing the :mod:`pecan.hooks` ``TransactionHook``, allows you
    to flag a controller method or class as being wrapped in a transaction,
    regardless of HTTP method.

    :param ignore_redirects: Indicates if the hook should ignore redirects
                             for this controller or not."""
    def deco(f):
        if isclass(f):
            for meth in [m[1] for m in getmembers(f) if (isfunction if six.PY3 else ismethod)(m[1])]:
                if getattr(meth, 'exposed', False):
                    _cfg(meth)['transactional'] = True
                    _cfg(meth)['transactional_ignore_redirects'] = _cfg(meth).get('transactional_ignore_redirects', ignore_redirects)
        else:
            _cfg(f)['transactional'] = True
            _cfg(f)['transactional_ignore_redirects'] = ignore_redirects
        return f
    return deco

def parse_ctcp(query):
    """Strip and de-quote CTCP messages."""
    query = query.strip(CTCP_DELIMITER)
    query = query.replace(CTCP_ESCAPE_CHAR + '0', '\x00')
    query = query.replace(CTCP_ESCAPE_CHAR + 'n', '\n')
    query = query.replace(CTCP_ESCAPE_CHAR + 'r', '\r')
    query = query.replace(CTCP_ESCAPE_CHAR + CTCP_ESCAPE_CHAR, CTCP_ESCAPE_CHAR)
    if ' ' in query:
        return query.split(' ', 1)
    return (query, None)

def normalize(input, case_mapping=protocol.DEFAULT_CASE_MAPPING):
    """Normalize input according to case mapping."""
    if case_mapping not in protocol.CASE_MAPPINGS:
        raise pydle.protocol.ProtocolViolation('Unknown case mapping ({})'.format(case_mapping))
    input = input.lower()
    if case_mapping in ('rfc1459', 'rfc1459-strict'):
        input = input.replace('{', '[').replace('}', ']').replace('|', '\\')
    if case_mapping == 'rfc1459':
        input = input.replace('~', '^')
    return input

def parse_user(raw):
    """Parse nick(!user(@host)?)? structure."""
    nick = raw
    user = None
    host = None
    if protocol.HOST_SEPARATOR in raw:
        raw, host = raw.split(protocol.HOST_SEPARATOR)
    if protocol.USER_SEPARATOR in raw:
        nick, user = raw.split(protocol.USER_SEPARATOR)
    return (nick, user, host)

def featurize(*features):
    """Put features into proper MRO order."""
    from functools import cmp_to_key
    def compare_subclass(left, right):
        if issubclass(left, right):
            return -1
        elif issubclass(right, left):
            return 1
        return 0
    sorted_features = sorted(features, key=cmp_to_key(compare_subclass))
    name = 'FeaturizedClient[{features}]'.format(features=', '.join((feature.__name__ for feature in sorted_features)))
    return type(name, tuple(sorted_features), {})

def normalize(url):
    """Normalize a URL.

    >>> normalize('hTtp://ExAMPLe.COM:80')
    'http://example.com/'"""
    url = url.strip()
    if url == '':
        return ''
    parts = split(url)
    if parts.scheme:
        netloc = parts.netloc
        if parts.scheme in SCHEMES:
            path = normalize_path(parts.path)
        else:
            path = parts.path
    else:
        netloc = parts.path
        path = ''
        if '/' in netloc:
            netloc, path_raw = netloc.split('/', 1)
            path = normalize_path('/' + path_raw)
    username, password, host, port = split_netloc(netloc)
    host = normalize_host(host)
    port = _normalize_port(parts.scheme, port)
    query = normalize_query(parts.query)
    fragment = normalize_fragment(parts.fragment)
    return construct(URL(parts.scheme, username, password, None, host, None, port, path, query, fragment, None))

def _encode_query(query):
    """Quote all values of a query string."""
    if query == '':
        return query
    query_args = []
    for query_kv in query.split('&'):
        k, v = query_kv.split('=')
        query_args.append(k + '=' + quote(v.encode('utf-8')))
    return '&'.join(query_args)

def construct(parts):
    """Construct a new URL from parts."""
    url = ''
    if parts.scheme:
        if parts.scheme in SCHEMES:
            url += parts.scheme + '://'
        else:
            url += parts.scheme + ':'
    if parts.username and parts.password:
        url += parts.username + ':' + parts.password + '@'
    elif parts.username:
        url += parts.username + '@'
    if parts.subdomain:
        url += parts.subdomain + '.'
    url += parts.domain
    if parts.tld:
        url += '.' + parts.tld
    if parts.port:
        url += ':' + parts.port
    if parts.path:
        url += parts.path
    if parts.query:
        url += '?' + parts.query
    if parts.fragment:
        url += '#' + parts.fragment
    return url

def normalize_host(host):
    """Normalize host (decode IDNA)."""
    if 'xn--' not in host:
        return host
    return '.'.join([_idna_decode(p) for p in host.split('.')])

def _normalize_port(scheme, port):
    """Return port if it is not default port, else None.

    >>> _normalize_port('http', '80')

    >>> _normalize_port('http', '8080')
    '8080'"""
    if not scheme:
        return port
    if port and port != DEFAULT_PORT[scheme]:
        return port

def normalize_path(path):
    """Normalize path: collapse etc.

    >>> normalize_path('/a/b///c')
    '/a/b/c'"""
    if path in ['//', '/', '']:
        return '/'
    npath = normpath(unquote(path, exceptions=QUOTE_EXCEPTIONS['path']))
    if path[-1] == '/' and npath != '/':
        npath += '/'
    return npath

def normalize_query(query):
    """Normalize query: sort params by name, remove params without value.

    >>> normalize_query('z=3&y=&x=1')
    'x=1&z=3'"""
    if query == '' or len(query) <= 2:
        return ''
    nquery = unquote(query, exceptions=QUOTE_EXCEPTIONS['query'])
    params = nquery.split('&')
    nparams = []
    for param in params:
        if '=' in param:
            k, v = param.split('=', 1)
            if k and v:
                nparams.append('%s=%s' % (k, v))
    nparams.sort()
    return '&'.join(nparams)

def unquote(text, exceptions=[]):
    """Unquote a text but ignore the exceptions.

    >>> unquote('foo%23bar')
    'foo#bar'
    >>> unquote('foo%23bar', ['#'])
    'foo%23bar'"""
    if not text:
        if text is None:
            raise TypeError('None object cannot be unquoted')
        else:
            return text
    if '%' not in text:
        return text
    s = text.split('%')
    res = [s[0]]
    for h in s[1:]:
        c = _hextochr.get(h[:2])
        if c and c not in exceptions:
            if len(h) > 2:
                res.append(c + h[2:])
            else:
                res.append(c)
        else:
            res.append('%' + h)
    return ''.join(res)

def parse(url):
    """Parse a URL.

    >>> parse('http://example.com/foo/')
    URL(scheme='http', ..., domain='example', tld='com', ..., path='/foo/', ...)"""
    parts = split(url)
    if parts.scheme:
        username, password, host, port = split_netloc(parts.netloc)
        subdomain, domain, tld = split_host(host)
    else:
        username = password = subdomain = domain = tld = port = ''
    return URL(parts.scheme, username, password, subdomain, domain, tld, port, parts.path, parts.query, parts.fragment, url)

def _clean_netloc(netloc):
    """Remove trailing '.' and ':' and tolower.

    >>> _clean_netloc('eXample.coM:')
    'example.com'"""
    try:
        return netloc.rstrip('.:').lower()
    except:
        return netloc.rstrip('.:').decode('utf-8').lower().encode('utf-8')

def split_netloc(netloc):
    """Split netloc into username, password, host and port.

    >>> split_netloc('foo:bar@www.example.com:8080')
    ('foo', 'bar', 'www.example.com', '8080')"""
    username = password = host = port = ''
    if '@' in netloc:
        user_pw, netloc = netloc.split('@', 1)
        if ':' in user_pw:
            username, password = user_pw.split(':', 1)
        else:
            username = user_pw
    netloc = _clean_netloc(netloc)
    if ':' in netloc and netloc[-1] != ']':
        host, port = netloc.rsplit(':', 1)
    else:
        host = netloc
    return (username, password, host, port)

def split_host(host):
    """Use the Public Suffix List to split host into subdomain, domain and tld.

    >>> split_host('foo.bar.co.uk')
    ('foo', 'bar', 'co.uk')"""
    if '[' in host:
        return ('', host, '')
    for c in host:
        if c not in IP_CHARS:
            break
    else:
        return ('', host, '')
    domain = subdomain = tld = ''
    parts = host.split('.')
    for i in range(len(parts)):
        tld = '.'.join(parts[i:])
        wildcard_tld = '*.' + tld
        exception_tld = '!' + tld
        if exception_tld in PSL:
            domain = '.'.join(parts[:i + 1])
            tld = '.'.join(parts[i + 1:])
            break
        if tld in PSL:
            domain = '.'.join(parts[:i])
            break
        if wildcard_tld in PSL:
            domain = '.'.join(parts[:i - 1])
            tld = '.'.join(parts[i - 1:])
            break
    if '.' in domain:
        subdomain, domain = domain.rsplit('.', 1)
    return (subdomain, domain, tld)

def human_readable_size(num, suffix='B'):
    """FROM http://stackoverflow.com/a/1094933/1958900
    """
    for unit in ['', 'Ki', 'Mi', 'Gi', 'Ti', 'Pi', 'Ei', 'Zi']:
        if abs(num) < 1024.0:
            return '%3.1f%s%s' % (num, unit, suffix)
        num /= 1024.0
    return '%.1f%s%s' % (num, 'Yi', suffix)

def lookup(source, keys, fallback=None):
    """Traverses the source, looking up each key.  Returns None if can't find anything instead of raising an exception."""
    try:
        for key in keys:
            source = source[key]
        return source
    except (KeyError, AttributeError, TypeError):
        return fallback

def statsId(obj):
    """Gets a unique ID for each object."""
    if hasattr(obj, ID_KEY):
        return getattr(obj, ID_KEY)
    newId = next(NEXT_ID)
    setattr(obj, ID_KEY, newId)
    return newId

def filterCollapsedItems(data):
    """Return a filtered iteration over a list of items."""
    return ((key, value) for key, value in six.iteritems(data) if not (isinstance(value, StatContainer) and value.isCollapsed()))

def collection(path, *stats):
    """Creates a named stats collection object."""
    def initMethod(self):
        """Init method for the underlying stat object's class."""
        init(self, path)
    attributes = {'__init__': initMethod}
    for stat in stats:
        attributes[stat.getName()] = stat
    newClass = type('Stats:%s' % path, (object,), attributes)
    instance = newClass()
    for stat in stats:
        default = stat._getInit()
        if default:
            setattr(instance, stat.getName(), default)
    return instance

def statsHandler(serverName, path=''):
    """Renders a GET request, by showing this nodes stats and children."""
    path = path.lstrip('/')
    parts = path.split('/')
    if not parts[0]:
        parts = parts[1:]
    statDict = util.lookup(scales.getStats(), parts)
    if statDict is None:
        abort(404, 'No stats found with path /%s' % '/'.join(parts))
    output = StringIO()
    outputFormat = request.args.get('format', 'html')
    query = request.args.get('query', None)
    if outputFormat == 'json':
        formats.jsonFormat(output, statDict, query)
    elif outputFormat == 'prettyjson':
        formats.jsonFormat(output, statDict, query, pretty=True)
    else:
        formats.htmlHeader(output, '/' + path, serverName, query)
        formats.htmlFormat(output, tuple(parts), statDict, query)
    return output.getvalue()

def _humanSortKey(s):
    """Sort strings with numbers in a way that makes sense to humans (e.g., 5 < 20)"""
    if isinstance(s, str):
        return [w.isdigit() and int(w) or w for w in re.split('(\\d+)', s)]
    else:
        return s

def compose(*decorators):
    """Helper to compose decorators::

        @a
        @b
        def f():
            pass

    Is equivalent to::

        @compose(a, b)
        def f():
            ..."""
    def composed(f):
        for decor in reversed(decorators):
            f = decor(f)
        return f
    return composed

def installStatsLoop(statsFile, statsDelay):
    """Installs an interval loop that dumps stats to a file."""
    def dumpStats():
        """Actual stats dump function."""
        scales.dumpStatsTo(statsFile)
        reactor.callLater(statsDelay, dumpStats)
    def startStats():
        """Starts the stats dump in "statsDelay" seconds."""
        reactor.callLater(statsDelay, dumpStats)
    reactor.callWhenRunning(startStats)

def runQuery(statDict, query):
    """Filters for the given query."""
    parts = [x.strip() for x in OPERATOR.split(query)]
    assert len(parts) in (1, 3)
    queryKey = parts[0]
    result = {}
    for key, value in six.iteritems(statDict):
        if key == queryKey:
            if len(parts) == 3:
                op = OPERATORS[parts[1]]
                try:
                    queryValue = type(value)(parts[2]) if value else parts[2]
                except (TypeError, ValueError):
                    continue
                if not op(value, queryValue):
                    continue
            result[key] = value
        elif isinstance(value, scales.StatContainer) or isinstance(value, dict):
            child = runQuery(value, query)
            if child:
                result[key] = child
    return result

def htmlHeader(output, path, serverName, query=None):
    """Writes an HTML header."""
    if path and path != '/':
        output.write('<title>%s - Status: %s</title>' % (serverName, path))
    else:
        output.write('<title>%s - Status</title>' % serverName)
    output.write('
<style>
body,td { font-family: monospace }
.level div {
  padding-bottom: 4px;
}
.level .level {
  margin-left: 2em;
  padding: 1px 0;
}
span { color: #090; vertical-align: top }
.key { color: black; font-weight: bold }
.int, .float { color: #00c }
</style>
  ')
    output.write('<h1 style="margin: 0">Stats</h1>')
    output.write('<h3 style="margin: 3px 0 18px">%s</h3>' % serverName)
    output.write('<p><form action="#" method="GET">Filter: <input type="text" name="query" size="20" value="%s"></form></p>' % (query or ''))

def htmlFormat(output, pathParts=(), statDict=None, query=None):
    """Formats as HTML, writing to the given object."""
    statDict = statDict or scales.getStats()
    if query:
        statDict = runQuery(statDict, query)
    _htmlRenderDict(pathParts, statDict, output)

def _htmlRenderDict(pathParts, statDict, output):
    """Render a dictionary as a table - recursing as necessary."""
    keys = list(statDict.keys())
    keys.sort()
    links = []
    output.write('<div class="level">')
    for key in keys:
        keyStr = cgi.escape(_utf8str(key))
        value = statDict[key]
        if hasattr(value, '__call__'):
            value = value()
        if hasattr(value, 'keys'):
            valuePath = pathParts + (keyStr,)
            if isinstance(value, scales.StatContainer) and value.isCollapsed():
                link = '/status/' + '/'.join(valuePath)
                links.append('<div class="key"><a href="%s">%s</a></div>' % (link, keyStr))
            else:
                output.write('<div class="key">%s</div>' % keyStr)
                _htmlRenderDict(valuePath, value, output)
        else:
            output.write('<div><span class="key">%s</span> <span class="%s">%s</span></div>' % (keyStr, type(value).__name__, cgi.escape(_utf8str(value)).replace('\n', '<br/>')))
    if links:
        for link in links:
            output.write(link)
    output.write('</div>')

def _utf8str(x):
    """Like str(x), but returns UTF8."""
    if six.PY3:
        return str(x)
    if isinstance(x, six.binary_type):
        return x
    elif isinstance(x, six.text_type):
        return x.encode('utf-8')
    else:
        return six.binary_type(x)

def jsonFormat(output, statDict=None, query=None, pretty=False):
    """Formats as JSON, writing to the given object."""
    statDict = statDict or scales.getStats()
    if query:
        statDict = runQuery(statDict, query)
    indent = 2 if pretty else None
    try:
        serialized = json.dumps(statDict, cls=scales.StatContainerEncoder, indent=indent)
    except UnicodeDecodeError:
        serialized = json.dumps(statDict, cls=scales.StatContainerEncoder, indent=indent, encoding='iso-8859-1')
    output.write(serialized)
    output.write('\n')

def RepeatTimer(interval, function, iterations=0, *args, **kwargs):
    """Repeating timer. Returns a thread id."""
    def __repeat_timer(interval, function, iterations, args, kwargs):
        """Inner function, run in background thread."""
        count = 0
        while iterations <= 0 or count < iterations:
            sleep(interval)
            function(*args, **kwargs)
            count += 1
    return start_new_thread(__repeat_timer, (interval, function, iterations, args, kwargs))

