def min_or_none(val1, val2):
    """Returns min(val1, val2) returning None only if both values are None"""
    return min(val1, val2, key=lambda x: sys.maxint if x is None else x)

def max_or_none(val1, val2):
    """Returns max(val1, val2) returning None only if both values are None"""
    return max(val1, val2, key=lambda x: -sys.maxint if x is None else x)

def merge_schema(first, second):
    """Returns the result of merging the two given schemas.
    """
    if not type(first) == type(second) == dict:
        raise ValueError('Argument is not a schema')
    if not first.get('type') == second.get('type') == 'object':
        raise NotImplementedError('Unsupported root type')
    return merge_objects(first, second)

def event_emitter(cls_=None, *, events=('*',)):
    """A class-decorator which will add the specified events and the methods 'on'
    and 'emit' to the class."""
    event_dict = dict.fromkeys(events, [])
    allow_any_eventname = event_dict.pop('*', False) == []
    def _event_emitter(cls):
        def on(self, name, callback):
            """Add a callback to the event named 'name'. Returns the object for
            chained 'on' calls."""
            if not (callable(callback) or isawaitable(callback)):
                raise ValueError('Callback not callable: %r' % callback)
            try:
                event_dict[name].append(callback)
            except KeyError:
                if allow_any_eventname:
                    event_dict[name] = [callback]
                else:
                    msg = 'Event Emitter has no event {!r}'.format(name)
                    raise KeyError(msg)
            return self
        async def emit(self, name):
            """Coroutine which executes each of the callbacks added to the event
            identified by 'name'"""
            for cb in event_dict[name]:
                if isawaitable(cb):
                    await cb
                else:
                    cb()
        cls.on = on
        cls.emit = emit
        return cls
    if cls_ is None:
        return _event_emitter
    else:
        return _event_emitter(cls_)

def _find_routeable_attributes(obj, keys):
    """From the set of provided `keys`, this function yields the attributes
    of `obj` that fulfill the requirements of 'routeable':
    * callable
    * matched by ROUTABLE_NAME_REGEX
    * has docstring"""
    for attr in keys:
        matches = ROUTABLE_NAME_REGEX.match(attr)
        if matches is None:
            continue
        try:
            val = getattr(obj, attr)
        except AttributeError:
            continue
        if not callable(val) or val.__doc__ is None:
            continue
        method_name = matches.group(1).upper()
        yield (val, method_name)

def add_relationship_url(user, status):
    '''Generate a url for adding a relationship on a given user.  ``user`` is a
    User object, and ``status`` is either a relationship_status object or a
    string denoting a RelationshipStatus

    Usage::

        href="{{ user|add_relationship_url:"following" }}"'''
    if isinstance(status, RelationshipStatus):
        status = status.from_slug
    return reverse('relationship_add', args=[user.username, status])

def getScriptLanguageSystems(feaFile):
    """Return dictionary keyed by Unicode script code containing lists of
    (OT_SCRIPT_TAG, [OT_LANGUAGE_TAG, ...]) tuples (excluding "DFLT")."""
    languagesByScript = collections.OrderedDict()
    for ls in [st for st in feaFile.statements if isinstance(st, ast.LanguageSystemStatement)]:
        if ls.script == 'DFLT':
            continue
        languagesByScript.setdefault(ls.script, []).append(ls.language)
    langSysMap = collections.OrderedDict()
    for script, languages in languagesByScript.items():
        sc = unicodedata.ot_tag_to_script(script)
        langSysMap.setdefault(sc, []).append((script, languages))
    return langSysMap

def makeGlyphClassDefinitions(groups, feaFile=None, stripPrefix=''):
    """Given a groups dictionary ({str: list[str]}), create feaLib
    GlyphClassDefinition objects for each group.
    Return a dict keyed by the original group name.

    If `stripPrefix` (str) is provided and a group name starts with it,
    the string will be stripped from the beginning of the class name."""
    classDefs = {}
    if feaFile is not None:
        classNames = {cdef.name for cdef in iterClassDefinitions(feaFile)}
    else:
        classNames = set()
    lengthPrefix = len(stripPrefix)
    for groupName, members in sorted(groups.items()):
        originalGroupName = groupName
        if stripPrefix and groupName.startswith(stripPrefix):
            groupName = groupName[lengthPrefix:]
        className = makeFeaClassName(groupName, classNames)
        classNames.add(className)
        classDef = makeGlyphClassDefinition(className, members)
        classDefs[originalGroupName] = classDef
    return classDefs

def addLookupReferences(feature, lookups, script=None, languages=None, exclude_dflt=False):
    """Add references to named lookups to the feature's statements.
    If `script` (str) and `languages` (sequence of str) are provided,
    only register the lookup for the given script and languages,
    optionally with `exclude_dflt` directive.
    Otherwise add a global reference which will be registered for all
    the scripts and languages in the feature file's `languagesystems`
    statements."""
    assert lookups
    if not script:
        for lookup in lookups:
            feature.statements.append(ast.LookupReferenceStatement(lookup))
        return
    feature.statements.append(ast.ScriptStatement(script))
    if exclude_dflt:
        for language in languages or ('dflt',):
            feature.statements.append(ast.LanguageStatement(language, include_default=False))
            for lookup in lookups:
                feature.statements.append(ast.LookupReferenceStatement(lookup))
    else:
        feature.statements.append(ast.LanguageStatement('dflt', include_default=True))
        for lookup in lookups:
            feature.statements.append(ast.LookupReferenceStatement(lookup))
        for language in languages or ():
            if language == 'dflt':
                continue
            feature.statements.append(ast.LanguageStatement(language, include_default=True))

def addLookupReference(feature, lookup, script=None, languages=None, exclude_dflt=False):
    """Shortcut for addLookupReferences, but for a single lookup.
    """
    return addLookupReferences(feature, (lookup,), script=script, languages=languages, exclude_dflt=exclude_dflt)

def getGDEFGlyphClasses(feaLib):
    """Return GDEF GlyphClassDef base/mark/ligature/component glyphs, or
    None if no GDEF table is defined in the feature file."""
    for st in feaLib.statements:
        if isinstance(st, ast.TableBlock) and st.name == 'GDEF':
            for st in st.statements:
                if isinstance(st, ast.GlyphClassDefStatement):
                    return _GDEFGlyphClasses(frozenset(st.baseGlyphs.glyphSet()) if st.baseGlyphs is not None else frozenset(), frozenset(st.ligatureGlyphs.glyphSet()) if st.ligatureGlyphs is not None else frozenset(), frozenset(st.markGlyphs.glyphSet()) if st.markGlyphs is not None else frozenset(), frozenset(st.componentGlyphs.glyphSet()) if st.componentGlyphs is not None else frozenset())
    return _GDEFGlyphClasses(None, None, None, None)

def styleMapFamilyNameFallback(info):
    """Fallback to *openTypeNamePreferredFamilyName* if
    *styleMapStyleName* or, if *styleMapStyleName* isn't defined,
    *openTypeNamePreferredSubfamilyName* is
    *regular*, *bold*, *italic* or *bold italic*, otherwise
    fallback to *openTypeNamePreferredFamilyName openTypeNamePreferredFamilyName*."""
    familyName = getAttrWithFallback(info, 'openTypeNamePreferredFamilyName')
    styleName = info.styleMapStyleName
    if not styleName:
        styleName = getAttrWithFallback(info, 'openTypeNamePreferredSubfamilyName')
    if styleName is None:
        styleName = ''
    elif styleName.lower() in _styleMapStyleNames:
        styleName = ''
    return (familyName + ' ' + styleName).strip()

def styleMapStyleNameFallback(info):
    """Fallback to *openTypeNamePreferredSubfamilyName* if
    it is one of *regular*, *bold*, *italic*, *bold italic*, otherwise
    fallback to *regular*."""
    styleName = getAttrWithFallback(info, 'openTypeNamePreferredSubfamilyName')
    if styleName is None:
        styleName = 'regular'
    elif styleName.strip().lower() not in _styleMapStyleNames:
        styleName = 'regular'
    else:
        styleName = styleName.strip().lower()
    return styleName

def openTypeHeadCreatedFallback(info):
    """Fallback to the environment variable SOURCE_DATE_EPOCH if set, otherwise
    now."""
    if 'SOURCE_DATE_EPOCH' in os.environ:
        t = datetime.utcfromtimestamp(int(os.environ['SOURCE_DATE_EPOCH']))
        return t.strftime(_date_format)
    else:
        return dateStringForNow()

def openTypeHheaCaretSlopeRiseFallback(info):
    """Fallback to *openTypeHheaCaretSlopeRise*. If the italicAngle is zero,
    return 1. If italicAngle is non-zero, compute the slope rise from the
    complementary openTypeHheaCaretSlopeRun, if the latter is defined.
    Else, default to an arbitrary fixed reference point (1000)."""
    italicAngle = getAttrWithFallback(info, 'italicAngle')
    if italicAngle != 0:
        if hasattr(info, 'openTypeHheaCaretSlopeRun') and info.openTypeHheaCaretSlopeRun is not None:
            slopeRun = info.openTypeHheaCaretSlopeRun
            return otRound(slopeRun / math.tan(math.radians(-italicAngle)))
        else:
            return 1000
    return 1

def openTypeHheaCaretSlopeRunFallback(info):
    """Fallback to *openTypeHheaCaretSlopeRun*. If the italicAngle is zero,
    return 0. If italicAngle is non-zero, compute the slope run from the
    complementary openTypeHheaCaretSlopeRise."""
    italicAngle = getAttrWithFallback(info, 'italicAngle')
    if italicAngle != 0:
        slopeRise = getAttrWithFallback(info, 'openTypeHheaCaretSlopeRise')
        return otRound(math.tan(math.radians(-italicAngle)) * slopeRise)
    return 0

def openTypeNameVersionFallback(info):
    """Fallback to *versionMajor.versionMinor* in the form 0.000."""
    versionMajor = getAttrWithFallback(info, 'versionMajor')
    versionMinor = getAttrWithFallback(info, 'versionMinor')
    return 'Version %d.%s' % (versionMajor, str(versionMinor).zfill(3))

def openTypeNameUniqueIDFallback(info):
    """Fallback to *openTypeNameVersion;openTypeOS2VendorID;postscriptFontName*."""
    version = getAttrWithFallback(info, 'openTypeNameVersion').replace('Version ', '')
    vendor = getAttrWithFallback(info, 'openTypeOS2VendorID')
    fontName = getAttrWithFallback(info, 'postscriptFontName')
    return '%s;%s;%s' % (version, vendor, fontName)

def openTypeOS2TypoLineGapFallback(info):
    """Fallback to *UPM * 1.2 - ascender + descender*, or zero if that's negative."""
    return max(int(info.unitsPerEm * 1.2) - info.ascender + info.descender, 0)

def postscriptBlueScaleFallback(info):
    """Fallback to a calculated value: 3/(4 * *maxZoneHeight*)
    where *maxZoneHeight* is the tallest zone from *postscriptBlueValues*
    and *postscriptOtherBlues*. If zones are not set, return 0.039625."""
    blues = getAttrWithFallback(info, 'postscriptBlueValues')
    otherBlues = getAttrWithFallback(info, 'postscriptOtherBlues')
    maxZoneHeight = 0
    blueScale = 0.039625
    if blues:
        assert len(blues) % 2 == 0
        for x, y in zip(blues[:-1:2], blues[1::2]):
            maxZoneHeight = max(maxZoneHeight, abs(y - x))
    if otherBlues:
        assert len(otherBlues) % 2 == 0
        for x, y in zip(otherBlues[:-1:2], otherBlues[1::2]):
            maxZoneHeight = max(maxZoneHeight, abs(y - x))
    if maxZoneHeight != 0:
        blueScale = 3 / (4 * maxZoneHeight)
    return blueScale

def getAttrWithFallback(info, attr):
    """Get the value for *attr* from the *info* object.
    If the object does not have the attribute or the value
    for the atribute is None, this will either get a
    value from a predefined set of attributes or it
    will synthesize a value from the available data."""
    if hasattr(info, attr) and getattr(info, attr) is not None:
        value = getattr(info, attr)
    elif attr in specialFallbacks:
        value = specialFallbacks[attr](info)
    else:
        value = staticFallbackData[attr]
    return value

def preflightInfo(info):
    """Returns a dict containing two items. The value for each
    item will be a list of info attribute names.

    ==================  ===
    missingRequired     Required data that is missing.
    missingRecommended  Recommended data that is missing.
    ==================  ==="""
    missingRequired = set()
    missingRecommended = set()
    for attr in requiredAttributes:
        if not hasattr(info, attr) or getattr(info, attr) is None:
            missingRequired.add(attr)
    for attr in recommendedAttributes:
        if not hasattr(info, attr) or getattr(info, attr) is None:
            missingRecommended.add(attr)
    return dict(missingRequired=missingRequired, missingRecommended=missingRecommended)

def makeUnicodeToGlyphNameMapping(font, glyphOrder=None):
    """Make a unicode: glyph name mapping for this glyph set (dict or Font).

    Raises InvalidFontData exception if multiple glyphs are mapped to the
    same unicode codepoint."""
    if glyphOrder is None:
        glyphOrder = makeOfficialGlyphOrder(font)
    mapping = {}
    for glyphName in glyphOrder:
        glyph = font[glyphName]
        unicodes = glyph.unicodes
        for uni in unicodes:
            if uni not in mapping:
                mapping[uni] = glyphName
            else:
                from ufo2ft.errors import InvalidFontData
                InvalidFontData("cannot map '%s' to U+%04X; already mapped to '%s'" % (glyphName, uni, mapping[uni]))
    return mapping

def classifyGlyphs(unicodeFunc, cmap, gsub=None):
    """'unicodeFunc' is a callable that takes a Unicode codepoint and
    returns a string denoting some Unicode property associated with the
    given character (or None if a character is considered 'neutral').
    'cmap' is a dictionary mapping Unicode codepoints to glyph names.
    'gsub' is an (optional) fonttools GSUB table object, used to find all
    the glyphs that are "reachable" via substitutions from the initial
    sets of glyphs defined in the cmap.

    Returns a dictionary of glyph sets associated with the given Unicode
    properties."""
    glyphSets = {}
    neutralGlyphs = set()
    for uv, glyphName in cmap.items():
        key = unicodeFunc(uv)
        if key is None:
            neutralGlyphs.add(glyphName)
        else:
            glyphSets.setdefault(key, set()).add(glyphName)
    if gsub is not None:
        if neutralGlyphs:
            closeGlyphsOverGSUB(gsub, neutralGlyphs)
        for glyphs in glyphSets.values():
            s = glyphs | neutralGlyphs
            closeGlyphsOverGSUB(gsub, s)
            glyphs.update(s - neutralGlyphs)
    return glyphSets

def unicodeInScripts(uv, scripts):
    """Check UnicodeData's ScriptExtension property for unicode codepoint
    'uv' and return True if it intersects with the set of 'scripts' provided,
    False if it does not intersect.
    Return None for 'Common' script ('Zyyy')."""
    sx = unicodedata.script_extension(unichr(uv))
    if 'Zyyy' in sx:
        return None
    return not sx.isdisjoint(scripts)

def parseLayoutFeatures(font):
    """Parse OpenType layout features in the UFO and return a
    feaLib.ast.FeatureFile instance."""
    featxt = tounicode(font.features.text or '', 'utf-8')
    if not featxt:
        return ast.FeatureFile()
    buf = UnicodeIO(featxt)
    ufoPath = font.path
    if ufoPath is not None:
        buf.name = ufoPath
    glyphNames = set(font.keys())
    try:
        parser = Parser(buf, glyphNames)
        doc = parser.parse()
    except IncludedFeaNotFound as e:
        if ufoPath and os.path.exists(os.path.join(ufoPath, e.args[0])):
            logger.warning("Please change the file name in the include(...); statement to be relative to the UFO itself, instead of relative to the 'features.fea' file contained in it.")
        raise
    return doc

def maxCtxFont(font):
    """Calculate the usMaxContext value for an entire font."""
    maxCtx = 0
    for tag in ('GSUB', 'GPOS'):
        if tag not in font:
            continue
        table = font[tag].table
        if table.LookupList is None:
            continue
        for lookup in table.LookupList.Lookup:
            for st in lookup.SubTable:
                maxCtx = maxCtxSubtable(maxCtx, tag, lookup.LookupType, st)
    return maxCtx

def maxCtxSubtable(maxCtx, tag, lookupType, st):
    """Calculate usMaxContext based on a single lookup table (and an existing
    max value)."""
    if tag == 'GPOS' and lookupType == 1 or (tag == 'GSUB' and lookupType in (1, 2, 3)):
        maxCtx = max(maxCtx, 1)
    elif tag == 'GPOS' and lookupType == 2:
        maxCtx = max(maxCtx, 2)
    elif tag == 'GSUB' and lookupType == 4:
        for ligatures in st.ligatures.values():
            for ligature in ligatures:
                maxCtx = max(maxCtx, ligature.CompCount)
    elif tag == 'GPOS' and lookupType == 7 or (tag == 'GSUB' and lookupType == 5):
        maxCtx = maxCtxContextualSubtable(maxCtx, st, 'Pos' if tag == 'GPOS' else 'Sub')
    elif tag == 'GPOS' and lookupType == 8 or (tag == 'GSUB' and lookupType == 6):
        maxCtx = maxCtxContextualSubtable(maxCtx, st, 'Pos' if tag == 'GPOS' else 'Sub', 'Chain')
    elif tag == 'GPOS' and lookupType == 9 or (tag == 'GSUB' and lookupType == 7):
        maxCtx = maxCtxSubtable(maxCtx, tag, st.ExtensionLookupType, st.ExtSubTable)
    elif tag == 'GSUB' and lookupType == 8:
        maxCtx = maxCtxContextualRule(maxCtx, st, 'Reverse')
    return maxCtx

def maxCtxContextualSubtable(maxCtx, st, ruleType, chain=''):
    """Calculate usMaxContext based on a contextual feature subtable."""
    if st.Format == 1:
        for ruleset in getattr(st, '%s%sRuleSet' % (chain, ruleType)):
            if ruleset is None:
                continue
            for rule in getattr(ruleset, '%s%sRule' % (chain, ruleType)):
                if rule is None:
                    continue
                maxCtx = maxCtxContextualRule(maxCtx, rule, chain)
    elif st.Format == 2:
        for ruleset in getattr(st, '%s%sClassSet' % (chain, ruleType)):
            if ruleset is None:
                continue
            for rule in getattr(ruleset, '%s%sClassRule' % (chain, ruleType)):
                if rule is None:
                    continue
                maxCtx = maxCtxContextualRule(maxCtx, rule, chain)
    elif st.Format == 3:
        maxCtx = maxCtxContextualRule(maxCtx, st, chain)
    return maxCtx

def maxCtxContextualRule(maxCtx, st, chain):
    """Calculate usMaxContext based on a contextual feature rule."""
    if not chain:
        return max(maxCtx, st.GlyphCount)
    elif chain == 'Reverse':
        return max(maxCtx, st.GlyphCount + st.LookAheadGlyphCount)
    return max(maxCtx, st.InputGlyphCount + st.LookAheadGlyphCount)

def _get_anchor_data(anchor_data, glyphSet, components, anchor_name):
    """Get data for an anchor from a list of components."""
    anchors = []
    for component in components:
        for anchor in glyphSet[component.baseGlyph].anchors:
            if anchor.name == anchor_name:
                anchors.append((anchor, component))
                break
    if len(anchors) > 1:
        for i, (anchor, component) in enumerate(anchors):
            t = Transform(*component.transformation)
            name = '%s_%d' % (anchor.name, i + 1)
            anchor_data[name] = t.transformPoint((anchor.x, anchor.y))
    elif anchors:
        anchor, component = anchors[0]
        t = Transform(*component.transformation)
        anchor_data[anchor.name] = t.transformPoint((anchor.x, anchor.y))

def _component_closest_to_origin(components, glyph_set):
    """Return the component whose (xmin, ymin) bounds are closest to origin.

    This ensures that a component that is moved below another is
    actually recognized as such. Looking only at the transformation
    offset can be misleading."""
    return min(components, key=lambda comp: _distance((0, 0), _bounds(comp, glyph_set)))

def _bounds(component, glyph_set):
    """Return the (xmin, ymin) of the bounds of `component`."""
    if hasattr(component, 'bounds'):
        return component.bounds[:2]
    elif hasattr(component, 'draw'):
        pen = fontTools.pens.boundsPen.BoundsPen(glyphSet=glyph_set)
        component.draw(pen)
        return pen.bounds[:2]
    else:
        raise ValueError("Don't know to to compute the bounds of component '{}' ".format(component))

def _join_host_port(host, port):
    """Adapted golang's net.JoinHostPort"""
    template = '%s:%s'
    host_requires_bracketing = ':' in host or '%' in host
    if host_requires_bracketing:
        template = '[%s]:%s'
    return template % (host, port)

def min_validator(min_value):
    """Return validator function that ensures lower bound of a number.

    Result validation function will validate the internal value of resource
    instance field with the ``value >= min_value`` check

    Args:
        min_value: minimal value for new validator"""
    def validator(value):
        if value < min_value:
            raise ValidationError('{} is not >= {}'.format(value, min_value))
    return validator

def max_validator(max_value):
    """Return validator function that ensures upper bound of a number.

    Result validation function will validate the internal value of resource
    instance field with the ``value >= min_value`` check.

    Args:
        max_value: maximum value for new validator"""
    def validator(value):
        if value > max_value:
            raise ValidationError('{} is not <= {}'.format(value, max_value))
    return validator

def choices_validator(choices):
    """Return validator function that will check if ``value in choices``.

    Args:
        max_value (list, set, tuple): allowed choices for new validator"""
    def validator(value):
        if value not in choices:
            raise ValidationError('{} is not in {}'.format(value, list(choices)))
    return validator

def match_validator(expression):
    """Return validator function that will check if matches given expression.

    Args:
        match: if string then this will be converted to regular expression
           using ``re.compile``. Can be also any object that has ``match()``
           method like already compiled regular regular expression or custom
           matching object/class."""
    if isinstance(expression, str):
        compiled = re.compile(expression)
    elif hasattr(expression, 'match'):
        compiled = expression
    else:
        raise TypeError('Provided match is nor a string nor has a match method (like re expressions)')
    def validator(value):
        if not compiled.match(value):
            raise ValidationError('{} does not match pattern: {}'.format(value, compiled.pattern if hasattr(compiled, 'pattern') else compiled))
    return validator

def project(dataIn, projectionScript):
    """Programs may make use of data in the `dataIn` variable and should
    produce data on the `dataOut` variable."""
    dataOut = {}
    try:
        projectionScript = str(projectionScript)
        program = makeProgramFromString(projectionScript)
        if PY3:
            loc = {'dataIn': dataIn, 'dataOut': dataOut}
            exec(program, {}, loc)
            dataOut = loc['dataOut']
        else:
            exec(program)
    except Exception as e:
        glogger.error('Error while executing SPARQL projection')
        glogger.error(projectionScript)
        glogger.error('Encountered exception: ')
        glogger.error(e)
        dataOut = {'status': 'error', 'message': e.message}
    return dataOut

def init_cache():
    """Initializes the grlc cache (json file)"""
