def macro(name):
    """Replaces :func:`~flask_admin.model.template.macro`, adding support for using
    macros imported from another file. For example:

    .. code:: html+jinja

        {# templates/admin/column_formatters.html #}

        {% macro email(model, column) %}
          {% set address = model[column] %}
          <a href="mailto:{{ address }}">{{ address }}</a>
        {% endmacro %}

    .. code:: python

        class FooAdmin(ModelAdmin):
            column_formatters = {
                'col_name': macro('column_formatters.email')
            }

    Also required for this to work, is to add the following to the top of your
    master admin template:

    .. code:: html+jinja

        {# templates/admin/master.html #}

        {% import 'admin/column_formatters.html' as column_formatters with context %}"""
    def wrapper(view, context, model, column):
        if '.' in name:
            macro_import_name, macro_name = name.split('.')
            m = getattr(context.get(macro_import_name), macro_name, None)
        else:
            m = context.resolve(name)
        if not m:
            return m
        return m(model=model, column=column)
    return wrapper

def patch_loader(*decorator_args, serializer):
    """Decorator to automatically load and (partially) update a model from json
    request data

    :param serializer: The ModelSerializer to use to load data from the request"""
    def wrapped(fn):
        @wraps(fn)
        def decorated(*args, **kwargs):
            result = serializer.load(request.get_json(), instance=kwargs.pop('instance'), partial=True)
            if not result.errors and (not result.data.id):
                abort(HTTPStatus.NOT_FOUND)
            return fn(*result)
        return decorated
    if decorator_args and callable(decorator_args[0]):
        return wrapped(decorator_args[0])
    return wrapped

def post_loader(*decorator_args, serializer):
    """Decorator to automatically instantiate a model from json request data

    :param serializer: The ModelSerializer to use to load data from the request"""
    def wrapped(fn):
        @wraps(fn)
        def decorated(*args, **kwargs):
            return fn(*serializer.load(request.get_json()))
        return decorated
    if decorator_args and callable(decorator_args[0]):
        return wrapped(decorator_args[0])
    return wrapped

def no_route(arg=None):
    """Decorator to mark a
    :class:`~flask_unchained.bundles.controller.controller.Controller` or
    :class:`~flask_unchained.bundles.resource.resource.Resource` method as *not*
    a route. For example::

        class SiteController(Controller):
            @route('/')
            def index():
                return self.render('index')

            def about():
                return self.render('about', stuff=self.utility_method())

            @no_route
            def utility_method():
                return 'stuff'

        # registered like so in ``your_app_bundle/routes.py``
        routes = lambda: [
            controller(SiteController),
        ]

        # results in the following routes
        SiteController.index            => GET /
        SiteController.about            => GET /about

        # but without the @no_route decorator, it would have also added this route:
        SiteController.utility_method   => GET /utility-method

    NOTE: The perhaps more Pythonic way to accomplish is simply to make all non-route
    methods protected by prefixing them with an underscore, eg ``_utility_method``."""
    def wrapper(fn):
        setattr(fn, NO_ROUTES_ATTR, True)
        return fn
    if callable(arg):
        return wrapper(arg)
    return wrapper

def force_text(s, encoding='utf-8', errors='strict'):
    """Similar to smart_text, except that lazy instances are resolved to
    strings, rather than kept as lazy objects.

    If strings_only is True, don't convert (some) non-string-like objects."""
    if isinstance(s, text_type):
        return s
    try:
        if not isinstance(s, string_types):
            if PY3:
                if isinstance(s, bytes):
                    s = text_type(s, encoding, errors)
                else:
                    s = text_type(s)
            elif hasattr(s, '__unicode__'):
                s = s.__unicode__()
            else:
                s = text_type(bytes(s), encoding, errors)
        else:
            s = s.decode(encoding, errors)
    except UnicodeDecodeError as e:
        if not isinstance(s, Exception):
            raise FlaskMailUnicodeDecodeError(s, *e.args)
        else:
            s = ' '.join([force_text(arg, encoding, errors) for arg in s])
    return s

def model_fields(model, db_session=None, only=None, exclude=None, field_args=None, converter=None, exclude_pk=False, exclude_fk=False):
    """Generate a dictionary of fields for a given SQLAlchemy model.

    See `model_form` docstring for description of parameters."""
    mapper = model._sa_class_manager.mapper
    converter = converter or _ModelConverter()
    field_args = field_args or {}
    properties = []
    for prop in mapper.iterate_properties:
        if getattr(prop, 'columns', None):
            if exclude_fk and prop.columns[0].foreign_keys:
                continue
            elif exclude_pk and prop.columns[0].primary_key:
                continue
        properties.append((prop.key, prop))
    if only is not None:
        properties = (x for x in properties if x[0] in only)
    elif exclude:
        properties = (x for x in properties if x[0] not in exclude)
    field_dict = {}
    for name, prop in properties:
        field = converter.convert(model, mapper, prop, field_args.get(name), db_session)
        if field is not None:
            field_dict[name] = field
    return field_dict

def url(url: str, method: str):
    """Show details for a specific URL."""
    try:
        url_rule, params = current_app.url_map.bind('localhost').match(url, method=method, return_rule=True)
    except (NotFound, MethodNotAllowed) as e:
        click.secho(str(e), fg='white', bg='red')
    else:
        headings = ('Method(s)', 'Rule', 'Params', 'Endpoint', 'View', 'Options')
        print_table(headings, [(_get_http_methods(url_rule), url_rule.rule if url_rule.strict_slashes else url_rule.rule + '[/]', _format_dict(params), url_rule.endpoint, _get_rule_view(url_rule), _format_rule_options(url_rule))], ['<' if i > 0 else '>' for i, col in enumerate(headings)], primary_column_idx=1)

def urls(order_by: Optional[str]=None):
    """List all URLs registered with the app."""
    url_rules: List[Rule] = current_app.url_map._rules
    if order_by == 'view':
        url_rules = sorted(url_rules, key=lambda rule: _get_rule_view(rule))
    elif order_by != 'priority':
        url_rules = sorted(url_rules, key=lambda rule: getattr(rule, order_by))
    headings = ('Method(s)', 'Rule', 'Endpoint', 'View', 'Options')
    print_table(headings, [(_get_http_methods(url_rule), url_rule.rule if url_rule.strict_slashes else url_rule.rule.rstrip('/') + '[/]', url_rule.endpoint, _get_rule_view(url_rule), _format_rule_options(url_rule)) for url_rule in url_rules], ['<' if i > 0 else '>' for i, col in enumerate(headings)], primary_column_idx=1)

def singularize(word, pos=NOUN, custom=None):
    """Returns the singular of a given word.
    """
    if custom and word in custom:
        return custom[word]
    if '-' in word:
        w = word.split('-')
        if len(w) > 1 and w[1] in plural_prepositions:
            return singularize(w[0], pos, custom) + '-' + '-'.join(w[1:])
    if word.endswith("'"):
        return singularize(word[:-1]) + "'s"
    w = word.lower()
    for x in singular_uninflected:
        if x.endswith(w):
            return word
    for x in singular_uncountable:
        if x.endswith(w):
            return word
    for x in singular_ie:
        if w.endswith(x + 's'):
            return w[:-1]
    for x in singular_irregular:
        if w.endswith(x):
            return re.sub('(?i)' + x + '$', singular_irregular[x], word)
    for suffix, inflection in singular_rules:
        m = suffix.search(word)
        g = m and m.groups() or []
        if m:
            for k in range(len(g)):
                if g[k] is None:
                    inflection = inflection.replace('\\' + str(k + 1), '')
            return suffix.sub(inflection, word)
    return word

def gettext(*args, **kwargs):
    """Return the localized translation of message, based on the language, and
    locale directory of the domain specified in the translation key (or the
    current global domain). This function is usually aliased as ``_``."""
    key = args[0]
    key_match = TRANSLATION_KEY_RE.match(key)
    translation = _gettext(*args, **kwargs)
    if not key_match or translation != key:
        return translation
    return _get_domain(key_match).gettext(*args, **kwargs)

def ngettext(*args, **kwargs):
    """Like :func:`gettext`, except it supports pluralization."""
    is_plural = args[2] > 1
    if not is_plural:
        key = args[0]
        key_match = TRANSLATION_KEY_RE.match(key)
    else:
        key = args[1]
        key_match = PLURAL_TRANSLATION_KEY_RE.match(key)
    translation = _ngettext(*args, **kwargs)
    if not key_match or translation != key:
        return translation
    return _get_domain(key_match).ngettext(*args, **kwargs)

