def controller_name(cls, _remove_suffixes=None) -> str:
    """Returns the snake-cased name for a controller/resource class. Automatically
    strips ``Controller``, ``View``, and ``MethodView`` suffixes, eg::

        SiteController -> site
        FooBarBazView -> foo_bar_baz
        UsersMethodView -> users"""
    name = cls if isinstance(cls, str) else cls.__name__
    remove_suffixes = _remove_suffixes or getattr(cls, REMOVE_SUFFIXES_ATTR)
    for suffix in remove_suffixes:
        if name.endswith(suffix):
            name = right_replace(name, suffix, '')
            break
    return snake_case(name)

def roles_required(*roles):
    """Decorator which specifies that a user must have all the specified roles.

    Aborts with HTTP 403: Forbidden if the user doesn't have the required roles.

    Example::

        @app.route('/dashboard')
        @roles_required('ROLE_ADMIN', 'ROLE_EDITOR')
        def dashboard():
            return 'Dashboard'

    The current user must have both the `ROLE_ADMIN` and `ROLE_EDITOR` roles
    in order to view the page.

    :param roles: The required roles."""
    def wrapper(fn):
        @wraps(fn)
        def decorated_view(*args, **kwargs):
            perms = [Permission(RoleNeed(role)) for role in roles]
            for perm in perms:
                if not perm.can():
                    abort(HTTPStatus.FORBIDDEN)
            return fn(*args, **kwargs)
        return decorated_view
    return wrapper

def get_boolean_env(name, default):
    """Converts environment variables to boolean values, where truthy is defined as:
    ``value.lower() in {'true', 'yes', 'y', '1'}`` (everything else is falsy)."""
    default = 'true' if default else 'false'
    return os.getenv(name, default).lower() in {'true', 'yes', 'y', '1'}

def safe_import_module(module_name):
    """Like :func:`importlib.import_module`, except it does not raise ``ImportError``
    if the requested ``module_name`` was not found."""
    try:
        return import_module(module_name)
    except ImportError as e:
        m = re.match("No module named '([\\w\\.]+)'", str(e))
        if not m or not module_name.startswith(m.group(1)):
            raise e

def camel_case(string):
    """Converts a string to camel case. For example::

        camel_case('one_two_three') -> 'oneTwoThree'"""
    if not string:
        return string
    parts = snake_case(string).split('_')
    rv = ''
    while parts:
        part = parts.pop(0)
        rv += part or '_'
        if part:
            break
    return rv + ''.join((x.title() for x in parts))

def class_case(string):
    """Converts a string to class case. For example::

        class_case('one_two_three') -> 'OneTwoThree'"""
    if not string:
        return string
    string = string.replace(' ', '_').replace('-', '_')
    parts = de_camel(string, '_', _lowercase=False).split('_')
    rv = ''
    while parts:
        part = parts.pop(0)
        rv += part.title() or '_'
        if part:
            break
    return rv + ''.join([part if part.isupper() else part.title() for part in parts])

def kebab_case(string):
    """Converts a string to kebab case. For example::

        kebab_case('one_two_three') -> 'one-two-three'

    NOTE: To generate valid slugs, use :meth:`slugify`"""
    if not string:
        return string
    string = string.replace('_', '-').replace(' ', '-')
    return de_camel(string, '-')

def right_replace(string, old, new, count=1):
    """Right replaces ``count`` occurrences of ``old`` with ``new`` in ``string``.
    For example::

        right_replace('one_two_two', 'two', 'three') -> 'one_two_three'"""
    if not string:
        return string
    return new.join(string.rsplit(old, count))

def slugify(string):
    """Converts a string to a valid slug. For example::

        slugify('Hello World') -> 'hello-world'"""
    if not string:
        return string
    string = re.sub('[^\\w\\s-]', '', unicodedata.normalize('NFKD', de_camel(string, '-')).encode('ascii', 'ignore').decode('ascii')).strip()
    return re.sub('[-_\\s]+', '-', string).strip('-').lower()

def snake_case(string):
    """Converts a string to snake case. For example::

        snake_case('OneTwoThree') -> 'one_two_three'"""
    if not string:
        return string
    string = string.replace('-', '_').replace(' ', '_')
    return de_camel(string)

def title_case(string):
    """Converts a string to title case. For example::

        title_case('one_two_three') -> 'One Two Three'"""
    if not string:
        return string
    string = string.replace('_', ' ').replace('-', ' ')
    parts = de_camel(string, ' ', _lowercase=False).strip().split(' ')
    return ' '.join([part if part.isupper() else part.title() for part in parts])

def parse_template(template):
    """returns a 2-tuple of (template_name, number_of_priors)"""
    m = TEMPLATE_OVERRIDE_RE.match(template)
    if not m:
        return (template, 0)
    return (m.group('template'), int(m.group('depth')))

def clean():
