def _auth_required():
    """Decorator that protects endpoints through token and session auth mechanisms"""
    login_mechanisms = (('token', lambda: _check_token()), ('session', lambda: current_user.is_authenticated))
    def wrapper(fn):
        @wraps(fn)
        def decorated_view(*args, **kwargs):
            for method, mechanism in login_mechanisms:
                if mechanism and mechanism():
                    return fn(*args, **kwargs)
            return security._unauthorized_callback()
        return decorated_view
    return wrapper

def copy_file_tree(src: str, dest: str, ctx: Optional[Dict[str, Any]]=None, option_locations: Optional[List[Tuple[str, List[str]]]]=None):
    """Copy the file tree under the :param:`src` directory to the :param:`dest`
    directory. Pass :param:`ctx` to support rendering the files, and pass
    :param:`option_locations` to support deleting optional files/folders."""
    if os.path.exists(dest):
        shutil.rmtree(dest, ignore_errors=True)
    shutil.copytree(src, dest)
    if option_locations:
        for option, paths in option_locations:
            for path in paths:
                path = os.path.join(dest, path)
                if os.path.isfile(path):
                    os.remove(path)
                else:
                    shutil.rmtree(path, ignore_errors=True)
    if 'app_bundle_module_name' in ctx:
        shutil.move(os.path.join(dest, 'app'), os.path.join(dest, ctx['app_bundle_module_name']))
        shutil.move(os.path.join(dest, 'tests', 'app'), os.path.join(dest, 'tests', ctx['app_bundle_module_name']))
    _render_file_tree(dest, ctx)

def unified_load(namespace, subclasses=None, recurse=False):
    """Provides a unified interface to both the module and class loaders,
    finding modules by default or classes if given a ``subclasses`` parameter."""
    if subclasses is not None:
        return ClassLoader(recurse=recurse).load(namespace, subclasses=subclasses)
    else:
        return ModuleLoader(recurse=recurse).load(namespace)

def _preserve_settings(method: T.Callable) -> T.Callable:
    """Decorator that ensures ObservableProperty-specific attributes
    are kept when using methods to change deleter, getter or setter."""
    @functools.wraps(method)
    def _wrapper(old: 'ObservableProperty', handler: T.Callable) -> 'ObservableProperty':
        new = method(old, handler)
        new.event = old.event
        new.observable = old.observable
        return new
    return _wrapper

def select(*cases):
    """Select the first case that becomes ready.
    If a default case (:class:`goless.dcase`) is present,
    return that if no other cases are ready.
    If there is no default case and no case is ready,
    block until one becomes ready.

    See Go's ``reflect.Select`` method for an analog
    (http://golang.org/pkg/reflect/#Select).

    :param cases: List of case instances, such as
      :class:`goless.rcase`, :class:`goless.scase`, or :class:`goless.dcase`.
    :return: ``(chosen case, received value)``.
      If the chosen case is not an :class:`goless.rcase`, it will be None."""
    if len(cases) == 0:
        return
    if isinstance(cases[0], list):
        if len(cases) != 1:
            raise TypeError('Select can be called either with a list of cases or multiple case arguments, but not both.')
        cases = cases[0]
        if not cases:
            return
    default = None
    for c in cases:
        if c.ready():
            return (c, c.exec_())
        if isinstance(c, dcase):
            assert default is None, 'Only one default case is allowd.'
            default = c
    if default is not None:
        return (default, None)
    if _be.would_deadlock():
        raise _Deadlock('No other tasklets running, cannot select.')
    while True:
        for c in cases:
            if c.ready():
                return (c, c.exec_())
        _be.yield_()

def calculate_backend(name_from_env, backends=None):
    """Calculates which backend to use with the following algorithm:

    - Try to read the GOLESS_BACKEND environment variable.
      Usually 'gevent' or 'stackless'.
      If a value is set but no backend is available or it fails to be created,
      this function will error.
    - Determine the default backend (gevent for PyPy, stackless for Python).
      If no default can be determined or created, continue.
    - Try to create all the runtimes and choose the first one to create
      successfully.
    - If no runtime can be created, return a NullBackend,
      which will error when accessed.

    The "default" backend is the less-easy backend for a runtime.
    Since PyPy has stackless by default, gevent is intentional.
    Since Stackless is a separate interpreter for CPython,
    that is more intentional than gevent.
    We feel this is a good default behavior."""
    if backends is None:
        backends = _default_backends
    if name_from_env:
        if name_from_env not in backends:
            raise RuntimeError('Invalid backend %r specified. Valid backends are: %s' % (name_from_env, _default_backends.keys()))
        return backends[name_from_env]()
    try:
        return _calc_default(backends)
    except SystemError:
        pass
    for maker in backends.values():
        try:
            return maker()
        except Exception:
            pass
    return NullBackend()

def go(func, *args, **kwargs):
    """Run a function in a new tasklet, like a goroutine.
    If the goroutine raises an unhandled exception (*panics*),
    the :func:`goless.on_panic` will be called,
    which by default logs the error and exits the process.

    :param args: Positional arguments to ``func``.
    :param kwargs: Keyword arguments to ``func``."""
    def safe_wrapped(f):
        try:
            f(*args, **kwargs)
        except:
            on_panic(*_sys.exc_info())
    _be.start(safe_wrapped, func)

