def get_pypi_url(requirement, version=None, base_url=PYPI_BASE_URL):
    """Get the PyPI url for a given requirement and optional version number and
    PyPI base URL. The default base url is 'https://pypi.python.org/pypi'"""
    if version:
        return '{base}/{req}/{version}/json'.format(base=base_url, req=requirement, version=version)
    else:
        return '{base}/{req}/json'.format(base=base_url, req=requirement)

def parse_req_file(req_file, verbatim=False):
    """Take a file and return a dict of (requirement, versions, ignore) based
    on the files requirements specs."""
    req_list = []
    requirements = req_file.readlines()
    for requirement in requirements:
        requirement_no_comments = requirement.split('#')[0].strip()
        req_match = re.match('\\s*(?P<package>[^\\s\\[\\]]+)(?P<extras>\\[\\S+\\])?==(?P<version>\\S+)', requirement_no_comments)
        req_ignore = requirement.strip().endswith('  # norot')
        if req_match:
            req_list.append((req_match.group('package'), req_match.group('version'), req_ignore))
        elif requirement_no_comments.startswith('-r'):
            try:
                base_dir = os.path.dirname(os.path.abspath(req_file.name))
            except AttributeError:
                print('Recursive requirements are not supported in URL based lookups')
                continue
            file_name = requirement_no_comments.replace('-r', '').strip()
            new_path = os.path.join(base_dir, file_name)
            try:
                if verbatim:
                    req_list.append((None, requirement, req_ignore))
                req_list.extend(parse_req_file(open(new_path), verbatim=verbatim))
            except IOError:
                print('Failed to import {}'.format(file_name))
        elif verbatim:
            req_list.append((None, requirement, req_ignore))
    return req_list

def ensure_directory_exists(directory):
    """Ensures `directory` exists. May make `directory` and intermediate dirs.
    Raises RuntimeError if `directory` is a file."""
    if not os.path.exists(directory):
        os.makedirs(directory)
    elif os.path.isfile(directory):
        raise RuntimeError('Path %s is a file, not a directory.' % directory)

def _object_getattr(obj, field):
    """Attribute getter for the objects to operate on.

    This function can be overridden in classes or instances of Query, Filter, and
    Order. Thus, a custom function to extract values to attributes can be
    specified, and the system can remain agnostic to the client's data model,
    without loosing query power.

    For example, the default implementation works with attributes and items::

      def _object_getattr(obj, field):
        # check whether this key is an attribute
        if hasattr(obj, field):
          value = getattr(obj, field)

        # if not, perhaps it is an item (raw dicts, etc)
        elif field in obj:
          value = obj[field]

        # return whatever we've got.
        return value

    Or consider a more complex, application-specific structure::

      def _object_getattr(version, field):

        if field in ['key', 'committed', 'created', 'hash']:
          return getattr(version, field)

        else:
          return version.attributes[field]['value']"""
    value = None
    if hasattr(obj, field):
        value = getattr(obj, field)
    elif field in obj:
        value = obj[field]
    return value

def limit_gen(limit, iterable):
    """A generator that applies a count `limit`."""
    limit = int(limit)
    assert limit >= 0, 'negative limit'
    for item in iterable:
        if limit <= 0:
            break
        yield item
        limit -= 1

def offset_gen(offset, iterable, skip_signal=None):
    """A generator that applies an `offset`, skipping `offset` elements from
    `iterable`. If skip_signal is a callable, it will be called with every
    skipped element."""
    offset = int(offset)
    assert offset >= 0, 'negative offset'
    for item in iterable:
        if offset > 0:
            offset -= 1
            if callable(skip_signal):
                skip_signal(item)
        else:
            yield item

def run_transaction(transactor, callback):
    """Run a transaction with retries.

    ``callback()`` will be called with one argument to execute the
    transaction. ``callback`` may be called more than once; it should have
    no side effects other than writes to the database on the given
    connection. ``callback`` should not call ``commit()` or ``rollback()``;
    these will be called automatically.

    The ``transactor`` argument may be one of the following types:
    * `sqlalchemy.engine.Connection`: the same connection is passed to the callback.
    * `sqlalchemy.engine.Engine`: a connection is created and passed to the callback.
    * `sqlalchemy.orm.sessionmaker`: a session is created and passed to the callback."""
    if isinstance(transactor, sqlalchemy.engine.Connection):
        return _txn_retry_loop(transactor, callback)
    elif isinstance(transactor, sqlalchemy.engine.Engine):
        with transactor.connect() as connection:
            return _txn_retry_loop(connection, callback)
    elif isinstance(transactor, sqlalchemy.orm.sessionmaker):
        session = transactor(autocommit=True)
        return _txn_retry_loop(session, callback)
    else:
        raise TypeError("don't know how to run a transaction on %s", type(transactor))

def _txn_retry_loop(conn, callback):
    """Inner transaction retry loop.

    ``conn`` may be either a Connection or a Session, but they both
    have compatible ``begin()`` and ``begin_nested()`` methods."""
    with conn.begin():
        while True:
            try:
                with _NestedTransaction(conn):
                    ret = callback(conn)
                    return ret
            except sqlalchemy.exc.DatabaseError as e:
                if isinstance(e.orig, psycopg2.OperationalError):
                    if e.orig.pgcode == psycopg2.errorcodes.SERIALIZATION_FAILURE:
                        continue
                raise

def do_rating_by_request(parser, token):
    """Retrieves the ``Vote`` cast by a user on a particular object and
    stores it in a context variable. If the user has not voted, the
    context variable will be 0.

    Example usage::

        {% rating_by_request request on instance as vote %}"""
    bits = token.contents.split()
    if len(bits) != 6:
        raise template.TemplateSyntaxError("'%s' tag takes exactly five arguments" % bits[0])
    if bits[2] != 'on':
        raise template.TemplateSyntaxError("second argument to '%s' tag must be 'on'" % bits[0])
    if bits[4] != 'as':
        raise template.TemplateSyntaxError("fourth argument to '%s' tag must be 'as'" % bits[0])
    return RatingByRequestNode(bits[1], bits[3], bits[5])

def do_rating_by_user(parser, token):
    """Retrieves the ``Vote`` cast by a user on a particular object and
    stores it in a context variable. If the user has not voted, the
    context variable will be 0.

    Example usage::

        {% rating_by_user user on instance as vote %}"""
    bits = token.contents.split()
    if len(bits) != 6:
        raise template.TemplateSyntaxError("'%s' tag takes exactly five arguments" % bits[0])
    if bits[2] != 'on':
        raise template.TemplateSyntaxError("second argument to '%s' tag must be 'on'" % bits[0])
    if bits[4] != 'as':
        raise template.TemplateSyntaxError("fourth argument to '%s' tag must be 'as'" % bits[0])
    return RatingByUserNode(bits[1], bits[3], bits[5])

def get_revision():
