def greenfct(zsrc, zrec, lsrc, lrec, depth, etaH, etaV, zetaH, zetaV, lambd):
    """Calculate Green's function for TM and TE.

    This is a modified version of empymod.kernel.greenfct(). See the original
    version for more information."""
    for TM in [True, False]:
        if TM:
            e_zH, e_zV, z_eH = (etaH, etaV, zetaH)
        else:
            e_zH, e_zV, z_eH = (zetaH, zetaV, etaH)
        Gam = np.sqrt((e_zH / e_zV)[:, None, :, None] * (lambd * lambd)[None, :, None, :] + (z_eH * e_zH)[:, None, :, None])
        lrecGam = Gam[:, :, lrec, :]
        Rp, Rm = reflections(depth, e_zH, Gam, lrec, lsrc, False)
        if lrec != depth.size - 1:
            ddepth = depth[lrec + 1] - zrec
            Wu = np.exp(-lrecGam * ddepth)
        else:
            Wu = np.full_like(lrecGam, 0 + 0j)
        if lrec != 0:
            ddepth = zrec - depth[lrec]
            Wd = np.exp(-lrecGam * ddepth)
        else:
            Wd = np.full_like(lrecGam, 0 + 0j)
        Puu, Pud, Pdu, Pdd = fields(depth, Rp, Rm, Gam, lrec, lsrc, zsrc, TM)
        df = np.exp(-lrecGam * abs(zsrc - zrec))
        fTM = Gam[:, :, lrec, :] / etaH[:, None, lrec, None]
        fTE = zetaH[:, None, lsrc, None] / Gam[:, :, lsrc, :]
        if TM:
            PTM = [Puu * Wu * fTM, Pud * Wu * fTM, Pdu * Wd * fTM, Pdd * Wd * fTM, -df * fTM]
        else:
            PTE = [Puu * Wu * fTE, Pud * Wu * fTE, Pdu * Wd * fTE, Pdd * Wd * fTE, df * fTE]
    return (PTM, PTE)

def load_filter(name, full=False, path='filters'):
    """Load saved DLF-filter and inversion output from text files."""
    filt = DigitalFilter(name.split('.')[0])
    filt.fromfile(path)
    if full:
        try:
            path = os.path.abspath(path)
            if len(name.split('.')) == 2:
                suffix = '.gz'
            else:
                suffix = ''
            fullfile = os.path.join(path, name.split('.')[0] + '_full.txt' + suffix)
            out = np.loadtxt(fullfile)
        except IOError:
            return filt
        nspace = int(out[0][0])
        nshift = int(out[1][0])
        space_shift_matrix = np.zeros((2, nspace, nshift))
        space_shift_matrix[0, :, :] = out[5:nspace + 5, :]
        space_shift_matrix[1, :, :] = out[nspace + 5:2 * nspace + 5, :]
        out = (np.array([out[2][0], out[3][0]]), out[4][0], space_shift_matrix, out[2 * nspace + 5:3 * nspace + 5, :], int(out[3 * nspace + 5, 0]))
        return (filt, out)
    else:
        return filt

def _plot_transform_pairs(fCI, r, k, axes, tit):
    """Plot the input transform pairs."""
    plt.sca(axes[0])
    plt.title('|' + tit + ' lhs|')
    for f in fCI:
        if f.name == 'j2':
            lhs = f.lhs(k)
            plt.loglog(k, np.abs(lhs[0]), lw=2, label='j0')
            plt.loglog(k, np.abs(lhs[1]), lw=2, label='j1')
        else:
            plt.loglog(k, np.abs(f.lhs(k)), lw=2, label=f.name)
    if tit != 'fC':
        plt.xlabel('l')
    plt.legend(loc='best')
    plt.sca(axes[1])
    plt.title('|' + tit + ' rhs|')
    for f in fCI:
        if tit == 'fC':
            plt.loglog(r, np.abs(f.rhs), lw=2, label=f.name)
        else:
            plt.loglog(r, np.abs(f.rhs(r)), lw=2, label=f.name)
    for f in fCI:
        if f.name[1] in ['0', '1', '2']:
            filt = j0j1filt()
        else:
            filt = sincosfilt()
        kk = filt.base / r[:, None]
        if f.name == 'j2':
            lhs = f.lhs(kk)
            kr0 = np.dot(lhs[0], getattr(filt, 'j0')) / r
            kr1 = np.dot(lhs[1], getattr(filt, 'j1')) / r ** 2
            kr = kr0 + kr1
        else:
            kr = np.dot(f.lhs(kk), getattr(filt, f.name)) / r
        plt.loglog(r, np.abs(kr), '-.', lw=2, label=filt.name)
    if tit != 'fC':
        plt.xlabel('r')
    plt.legend(loc='best')

def j0_1(a=1):
    """Hankel transform pair J0_1 ([Ande75]_)."""
    def lhs(x):
        return x * np.exp(-a * x ** 2)
    def rhs(b):
        return np.exp(-b ** 2 / (4 * a)) / (2 * a)
    return Ghosh('j0', lhs, rhs)

def j0_2(a=1):
    """Hankel transform pair J0_2 ([Ande75]_)."""
    def lhs(x):
        return np.exp(-a * x)
    def rhs(b):
        return 1 / np.sqrt(b ** 2 + a ** 2)
    return Ghosh('j0', lhs, rhs)

def j1_2(a=1):
    """Hankel transform pair J1_2 ([Ande75]_)."""
    def lhs(x):
        return np.exp(-a * x)
    def rhs(b):
        return (np.sqrt(b ** 2 + a ** 2) - a) / (b * np.sqrt(b ** 2 + a ** 2))
    return Ghosh('j1', lhs, rhs)

def sin_3(a=1):
    """Fourier sine transform pair sin_3 ([Ande75]_)."""
    def lhs(x):
        return x / (a ** 2 + x ** 2)
    def rhs(b):
        return np.pi * np.exp(-a * b) / 2
    return Ghosh('sin', lhs, rhs)

def cos_1(a=1):
    """Fourier cosine transform pair cos_1 ([Ande75]_)."""
    def lhs(x):
        return np.exp(-a ** 2 * x ** 2)
    def rhs(b):
        return np.sqrt(np.pi) * np.exp(-b ** 2 / (4 * a ** 2)) / (2 * a)
    return Ghosh('cos', lhs, rhs)

def _ls2ar(inp, strinp):
    """Convert float or linspace-input to arange/slice-input for brute."""
    if np.size(inp) == 1:
        start = np.squeeze(inp)
        stop = start + 1
        num = 1
    elif np.size(inp) == 3:
        start = inp[0]
        stop = inp[1]
        num = inp[2]
    else:
        print('* ERROR   :: <' + strinp + '> must be a float or a tuple of 3 ' + 'elements (start, stop, num); <' + strinp + ' provided: ' + str(inp))
        raise ValueError(strinp)
    if num < 2 or start == stop:
        stop = start
        step = 1
    else:
        step = (stop - start) / (num - 1)
    return (start, stop + step / 2, step)

def _print_count(log):
    """Print run-count information."""
    log['cnt2'] += 1
    cp = log['cnt2'] / log['totnr'] * 100
    if log['cnt2'] == 0:
        pass
    elif log['cnt2'] > log['totnr']:
        print('   fmin  fct calls : %d' % (log['cnt2'] - log['totnr']), end='\r')
    elif int(cp) > log['cnt1'] or cp < 1 or log['cnt2'] == log['totnr']:
        sec = int(default_timer() - log['time'])
        tleft = str(timedelta(seconds=int(100 * sec / cp - sec)))
        pstr = '   brute fct calls : %d/%d' % (log['cnt2'], log['totnr'])
        if log['totnr'] > 100:
            pstr += ' (%d %%); est: %s        ' % (cp, tleft)
        print(pstr, end='\r')
        if log['cnt2'] == log['totnr']:
            print(' ' * len(pstr), end='\r')
            print('   brute fct calls : %d' % log['totnr'])
        log['cnt1'] = cp
    return log

