def get_spline_values(filt, inp, nr_per_dec=None):
    """Return required calculation points."""
    if nr_per_dec == 0:
        return (filt.base / inp[:, None], inp)
    outmax = filt.base[-1] / inp.min()
    outmin = filt.base[0] / inp.max()
    if nr_per_dec < 0:
        pts_per_dec = 1 / np.log(filt.factor)
        nout = int(np.ceil(np.log(outmax / outmin) * pts_per_dec) + 1)
    else:
        pts_per_dec = nr_per_dec
        nout = int(np.ceil(np.log10(outmax / outmin) * pts_per_dec) + 1)
    if nr_per_dec < 0:
        if nout - filt.base.size < 3:
            nout = filt.base.size + 3
    elif nout < 4:
        nout = 4
    if nr_per_dec < 0:
        out = np.exp(np.arange(np.log(outmin), np.log(outmin) + nout / pts_per_dec, 1 / pts_per_dec))
        new_inp = inp.max() * np.exp(-np.arange(nout - filt.base.size + 1) / pts_per_dec)
    else:
        out = 10 ** np.arange(np.log10(outmin), np.log10(outmin) + nout / pts_per_dec, 1 / pts_per_dec)
        new_inp = filt.base / inp[:, None]
    return (np.atleast_2d(out), new_inp)

def _get_cpu_info_from_cpuid():
    """Returns the CPU info gathered by querying the X86 cpuid register in a new process.
    Returns {} on non X86 cpus.
    Returns {} if SELinux is in enforcing mode."""
    from multiprocessing import Process, Queue
    if not DataSource.can_cpuid:
        return {}
    arch, bits = _parse_arch(DataSource.arch_string_raw)
    if not arch in ['X86_32', 'X86_64']:
        return {}
    try:
        queue = Queue()
        p = Process(target=_actual_get_cpu_info_from_cpuid, args=(queue,))
        p.start()
        while p.is_alive():
            p.join(0)
        if p.exitcode != 0:
            return {}
        if not queue.empty():
            output = queue.get()
            return _b64_to_obj(output)
    except:
        pass
    return {}

def _get_cpu_info_from_cpufreq_info():
    """Returns the CPU info gathered from cpufreq-info.
    Returns {} if cpufreq-info is not found."""
    try:
        hz_brand, scale = ('0.0', 0)
        if not DataSource.has_cpufreq_info():
            return {}
        returncode, output = DataSource.cpufreq_info()
        if returncode != 0:
            return {}
        hz_brand = output.split('current CPU frequency is')[1].split('\n')[0]
        i = hz_brand.find('Hz')
        assert i != -1
        hz_brand = hz_brand[0:i + 2].strip().lower()
        if hz_brand.endswith('mhz'):
            scale = 6
        elif hz_brand.endswith('ghz'):
            scale = 9
        hz_brand = hz_brand.rstrip('mhz').rstrip('ghz').strip()
        hz_brand = _to_decimal_string(hz_brand)
        info = {'hz_advertised_friendly': _hz_short_to_friendly(hz_brand, scale), 'hz_actual_friendly': _hz_short_to_friendly(hz_brand, scale), 'hz_advertised': _hz_short_to_full(hz_brand, scale), 'hz_actual': _hz_short_to_full(hz_brand, scale)}
        info = {k: v for k, v in info.items() if v}
        return info
    except:
        return {}

