def is_leap(year):
    """Leap year or not in the Gregorian calendar."""
    x = math.fmod(year, 4)
    y = math.fmod(year, 100)
    z = math.fmod(year, 400)
    return not x and (y or not z)

def add_args_kwargs(func):
    """Add Args and Kwargs

    This wrapper adds support for additional arguments and keyword arguments to
    any callable function

    Parameters
    ----------
    func : function
        Callable function

    Returns
    -------
    function wrapper"""
    @wraps(func)
    def wrapper(*args, **kwargs):
        props = argspec(func)
        if isinstance(props[1], type(None)):
            args = args[:len(props[0])]
        if not isinstance(props[2], type(None)) or not isinstance(props[3], type(None)):
            return func(*args, **kwargs)
        else:
            return func(*args)
    return wrapper

def check_npndarray(val, dtype=None, writeable=True, verbose=True):
    """Check if input object is a numpy array.

    Parameters
    ----------
    val : np.ndarray
        Input object"""
    if not isinstance(val, np.ndarray):
        raise TypeError('Input is not a numpy array.')
    if not isinstance(dtype, type(None)) and (not np.issubdtype(val.dtype, dtype)):
        raise TypeError('The numpy array elements are not of type: {}'.format(dtype))
    if not writeable and verbose and val.flags.writeable:
        warn('Making input data immutable.')
    val.flags.writeable = writeable

def rec_apply(func, n):
    """Used to determine parent directory n levels up
    by repeatedly applying os.path.dirname"""
    if n > 1:
        rec_func = rec_apply(func, n - 1)
        return lambda x: func(rec_func(x))
    return func

def assert_dimensionless(value):
    """Tests for dimensionlessness of input.
    If input is dimensionless but expressed as a Quantity, it returns the
    bare value.  If it not, it raised an error."""
    if isinstance(value, Quantity):
        value = value.simplified
        if value.dimensionality == Dimensionality({}):
            value = value.base.item()
        else:
            raise TypeError('Score value %s must be dimensionless' % value)
    return value

def import_all_modules(package, skip=None, verbose=False, prefix='', depth=0):
    """Recursively imports all subpackages, modules, and submodules of a
    given package.
    'package' should be an imported package, not a string.
    'skip' is a list of modules or subpackages not to import."""
    skip = [] if skip is None else skip
    for ff, modname, ispkg in pkgutil.walk_packages(path=package.__path__, prefix=prefix, onerror=lambda x: None):
        if ff.path not in package.__path__[0]:
            continue
        if verbose:
            print('\t' * depth, modname)
        if modname in skip:
            if verbose:
                print('\t' * depth, '*Skipping*')
            continue
        module = '%s.%s' % (package.__name__, modname)
        subpackage = importlib.import_module(module)
        if ispkg:
            import_all_modules(subpackage, skip=skip, verbose=verbose, depth=depth + 1)

def main(*args):
    """Launch the main routine."""
    parser = argparse.ArgumentParser()
    parser.add_argument('action', help='create, check, run, make-nb, or run-nb')
    parser.add_argument('--directory', '-dir', default=os.getcwd(), help='path to directory with a .sciunit file')
    parser.add_argument('--stop', '-s', default=True, help='stop and raise errors, halting the program')
    parser.add_argument('--tests', '-t', default=False, help='runs tests instead of suites')
    if args:
        args = parser.parse_args(args)
    else:
        args = parser.parse_args()
    file_path = os.path.join(args.directory, '.sciunit')
    config = None
    if args.action == 'create':
        create(file_path)
    elif args.action == 'check':
        config = parse(file_path, show=True)
        print('\nNo configuration errors reported.')
    elif args.action == 'run':
        config = parse(file_path)
        run(config, path=args.directory, stop_on_error=args.stop, just_tests=args.tests)
    elif args.action == 'make-nb':
        config = parse(file_path)
        make_nb(config, path=args.directory, stop_on_error=args.stop, just_tests=args.tests)
    elif args.action == 'run-nb':
        config = parse(file_path)
        run_nb(config, path=args.directory)
    else:
        raise NameError('No such action %s' % args.action)
    if config:
        cleanup(config, path=args.directory)

def parse(file_path=None, show=False):
    """Parse a .sciunit config file."""
    if file_path is None:
        file_path = os.path.join(os.getcwd(), '.sciunit')
    if not os.path.exists(file_path):
        raise IOError('No .sciunit file was found at %s' % file_path)
    config = configparser.RawConfigParser(allow_no_value=True)
    config.read(file_path)
    for section in config.sections():
        if show:
            print(section)
        for options in config.options(section):
            if show:
                print('\t%s: %s' % (options, config.get(section, options)))
    return config

def prep(config=None, path=None):
    """Prepare to read the configuration information."""
    if config is None:
        config = parse()
    if path is None:
        path = os.getcwd()
    root = config.get('root', 'path')
    root = os.path.join(path, root)
    root = os.path.realpath(root)
    os.environ['SCIDASH_HOME'] = root
    if sys.path[0] != root:
        sys.path.insert(0, root)

def run(config, path=None, stop_on_error=True, just_tests=False):
    """Run sciunit tests for the given configuration."""
    if path is None:
        path = os.getcwd()
    prep(config, path=path)
    models = __import__('models')
    tests = __import__('tests')
    suites = __import__('suites')
    print('\n')
    for x in ['models', 'tests', 'suites']:
        module = __import__(x)
        assert hasattr(module, x), "'%s' module requires attribute '%s'" % (x, x)
    if just_tests:
        for test in tests.tests:
            _run(test, models, stop_on_error)
    else:
        for suite in suites.suites:
            _run(suite, models, stop_on_error)

def nb_name_from_path(config, path):
    """Get a notebook name from a path to a notebook"""
    if path is None:
        path = os.getcwd()
    root = config.get('root', 'path')
    root = os.path.join(path, root)
    root = os.path.realpath(root)
    default_nb_name = os.path.split(os.path.realpath(root))[1]
    nb_name = config.get('misc', 'nb-name', fallback=default_nb_name)
    return (root, nb_name)

def cleanup(config=None, path=None):
    """Cleanup by removing paths added during earlier in configuration."""
    if config is None:
        config = parse()
    if path is None:
        path = os.getcwd()
    root = config.get('root', 'path')
    root = os.path.join(path, root)
    if sys.path[0] == root:
        sys.path.remove(root)

