def get_xy(artist):
    """Attempts to get the x,y data for individual items subitems of the artist.
    Returns None if this is not possible.

    At present, this only supports Line2D's and basic collections."""
    xy = None
    if hasattr(artist, 'get_offsets'):
        xy = artist.get_offsets().T
    elif hasattr(artist, 'get_xydata'):
        xy = artist.get_xydata().T
    return xy

def wrap_exception(func: Callable) -> Callable:
    """Decorator to wrap pygatt exceptions into BluetoothBackendException."""
    try:
        from pygatt.backends.bgapi.exceptions import BGAPIError
        from pygatt.exceptions import NotConnectedError
    except ImportError:
        return func
    def _func_wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except BGAPIError as exception:
            raise BluetoothBackendException() from exception
        except NotConnectedError as exception:
            raise BluetoothBackendException() from exception
    return _func_wrapper

def wrap_exception(func: Callable) -> Callable:
    """Decorator to wrap BTLEExceptions into BluetoothBackendException."""
    try:
        from bluepy.btle import BTLEException
    except ImportError:
        return func
    def _func_wrapper(*args, **kwargs):
        error_count = 0
        last_error = None
        while error_count < RETRY_LIMIT:
            try:
                return func(*args, **kwargs)
            except BTLEException as exception:
                error_count += 1
                last_error = exception
                time.sleep(RETRY_DELAY)
                _LOGGER.debug('Call to %s failed, try %d of %d', func, error_count, RETRY_LIMIT)
        raise BluetoothBackendException() from last_error
    return _func_wrapper

def wrap_exception(func: Callable) -> Callable:
    """Wrap all IOErrors to BluetoothBackendException"""
    def _func_wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except IOError as exception:
            raise BluetoothBackendException() from exception
    return _func_wrapper

def rpc_request(method_name: str, *args, **kwargs) -> rpcq.messages.RPCRequest:
    """Create RPC request

    :param method_name: Method name
    :param args: Positional arguments
    :param kwargs: Keyword arguments
    :return: JSON RPC formatted dict"""
    if args:
        kwargs['*args'] = args
    return rpcq.messages.RPCRequest(jsonrpc='2.0', id=str(uuid.uuid4()), method=method_name, params=kwargs)

def get_input(params: Union[dict, list]) -> Tuple[list, dict]:
    """Get positional or keyword arguments from JSON RPC params

    :param params: Parameters passed through JSON RPC
    :return: args, kwargs"""
    if isinstance(params, list):
        args = params
        kwargs = {}
    elif isinstance(params, dict):
        args = params.pop('*args', [])
        kwargs = params
    else:
        raise TypeError('Unknown type {} of params, must be list or dict'.format(type(params)))
    return (args, kwargs)

def repr_value(value):
    """Represent a value in human readable form. For long list's this truncates the printed
    representation.

    :param value: The value to represent.
    :return: A string representation.
    :rtype: basestring"""
    if isinstance(value, list) and len(value) > REPR_LIST_TRUNCATION:
        return '[{},...]'.format(', '.join(map(repr, value[:REPR_LIST_TRUNCATION])))
    else:
        return repr(value)

def from_msgpack(b, *, max_bin_len=MAX_BIN_LEN, max_str_len=MAX_STR_LEN):
