def _get_loader(config):
    """Determine which config file type and loader to use based on a filename.

    :param config str: filename to config file
    :return: a tuple of the loader type and callable to load
    :rtype: (str, Callable)"""
    if config.endswith('.yml') or config.endswith('.yaml'):
        if not yaml:
            LOGGER.error('pyyaml must be installed to use the YAML loader')
            return (None, None)
        return ('yaml', yaml.load)
    else:
        return ('json', json.loads)

def get_chatlist(chatfile):
    """Try reading ids of saved chats from file.
    If we fail, return empty set"""
    if not chatfile:
        return set()
    try:
        with open(chatfile) as file_contents:
            return set((int(chat) for chat in file_contents))
    except (OSError, IOError) as exc:
        LOGGER.error('could not load saved chats:\n%s', exc)
        return set()

def get_data(upd, bot_ident):
    """Parse telegram update."""
    update_content = json.loads(upd.decode())
    result = update_content['result']
    data = (get_fields(update, bot_ident) for update in result)
    return (dt for dt in data if dt is not None)

def substitute_variables(command, level, name, value, target=None, **kwargs):
    """Substitute variables in command fragments by values e.g. ${level} => 'warning'."""
    rule = kwargs.get('rule', {})
    rule_value = rule.get('value', '') if rule else ''
    substitutes = {'${level}': str(level), '${target}': str(target), '${name}': '"' + str(name) + '"', '${value}': str(value), '${limit_value}': str(rule_value)}
    result = command
    for pattern, value in substitutes.items():
        result = result.replace(pattern, value)
    return result

def iterator_mix(*iterators):
    """Iterating over list of iterators.
    Bit like zip, but zip stops after the
    shortest iterator is empty, abd here
    we go one until all iterators are empty."""
    while True:
        one_left = False
        for it in iterators:
            try:
                yield it.next()
            except StopIteration:
                pass
            else:
                one_left = True
        if not one_left:
            break

