        raise TestStepFail(format_message(message) if message is not None else 'Json string is empty')

def get_git_info(git_folder, verbose=False):
    """Detect GIT information by folder.

    :param git_folder: Folder
    :param verbose: Verbosity, boolean, default is False
    :return: dict"""
    if verbose:
        print("detect GIT info by folder: '%s'" % git_folder)
    try:
        git_info = {'commitid': get_commit_id(git_folder), 'branch': get_current_branch(git_folder), 'git_path': get_git_file_path(git_folder), 'url': get_remote_url(git_folder), 'scm': 'unknown', 'scm_group': 'unknown', 'scm_path': 'unknown', 'scm_link': ''}
        if is_git_root_dirty(git_folder):
            git_info['dirty'] = True
    except Exception as err:
        print('GitTool exception:')
        print(err)
        return {}
    if isinstance(git_info['url'], str):
        match = re.search('github\\.com:(.*)\\/(.*)', git_info['url'])
        if match:
            git_info['scm'] = 'github.com'
            git_info['scm_path'] = match.group(2)
            git_info['scm_group'] = match.group(1)
            scm_link_end = ' %s/%s' % (git_info['scm_group'], git_info['scm_path'].replace('.git', ''))
            git_info['scm_link'] = 'https://github.com/' + scm_link_end
            git_info['scm_link'] += '/tree/%s/%s' % (git_info['commitid'], git_info['git_path'])
    if verbose:
        print('all git_info:')
        print(git_info)
    return git_info

def __get_git_bin():
    """Get git binary location.

    :return: Check git location"""
    git = 'git'
    alternatives = ['/usr/bin/git']
    for alt in alternatives:
        if os.path.exists(alt):
            git = alt
            break
    return git

def __run_git(cmd, path=None):
    """internal run git command
    :param cmd: git parameters as array
    :param path: path where command will be executed
    :return: tuple (<line>, <returncode>)"""
    exe = [__get_git_bin()] + cmd
    try:
        proc = subprocess.Popen(exe, cwd=path, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except subprocess.CalledProcessError:
        return (None, None)
    except ValueError:
        return (None, None)
    except OSError:
        return (None, None)
    out, err = proc.communicate()
    if IS_PYTHON3:
        out = out.decode('utf-8')
    if err:
        print("Cmd ('%s') fails: %s" % (' '.join(exe), err))
        return (None, proc.returncode)
    return (out.strip(), proc.returncode)

def str_arg_to_bool(value):
    """Convert string argument into a boolean values.
    :param value: str value to convert. Allowed values are y, yes, true, 1, t, n, no, false, 0, f.
    The implementation is case insensitive.
    :raises: argparse.ArgumentTypeError if value is not recognized as a boolean.
    :return: boolean"""
    if value.lower() in ['y', 'yes', 'true', '1', 't']:
        return True
    elif value.lower() in ['n', 'no', 'false', '0', 'f']:
        return False
    else:
        raise argparse.ArgumentTypeError('Boolean value expected.')

def find_next(lines, find_str, start_index):
    """Find the next instance of find_str from lines starting from start_index.

    :param lines: Lines to look through
    :param find_str: String or Invert to look for
    :param start_index: Index to start from
    :return: (boolean, index, line)"""
    mode = None
    if isinstance(find_str, basestring):
        mode = 'normal'
        message = find_str
    elif isinstance(find_str, Invert):
        mode = 'invert'
        message = str(find_str)
    else:
        raise TypeError('Unsupported message type')
    for i in range(start_index, len(lines)):
        if re.search(message, lines[i]):
            return (mode == 'normal', i, lines[i])
        elif message in lines[i]:
            return (mode == 'normal', i, lines[i])
    if mode == 'invert':
        return (True, len(lines), None)
    raise LookupError('Not found')

def verify_message(lines, expected_response):
    """Looks for expectedResponse in lines.

    :param lines: a list of strings to look through
    :param expected_response: list or str to look for in lines.
    :return: True or False.
    :raises: TypeError if expectedResponse was not list or str.
    LookUpError through FindNext function."""
    position = 0
    if isinstance(expected_response, basestring):
        expected_response = [expected_response]
    if isinstance(expected_response, set):
        expected_response = list(expected_response)
    if not isinstance(expected_response, list):
        raise TypeError('verify_message: expectedResponse must be list, set or string')
    for message in expected_response:
        try:
            found, position, _ = find_next(lines, message, position)
            if not found:
                return False
            position = position + 1
        except TypeError:
            return False
        except LookupError:
            return False
    return True

