def ripple_carry_add(A, B, cin=0):
    """Return symbolic logic for an N-bit ripple carry adder."""
    if len(A) != len(B):
        raise ValueError('expected A and B to be equal length')
    ss, cs = (list(), list())
    for i, a in enumerate(A):
        c = cin if i == 0 else cs[i - 1]
        ss.append(a ^ B[i] ^ c)
        cs.append(a & B[i] | a & c | B[i] & c)
    return (farray(ss), farray(cs))

def kogge_stone_add(A, B, cin=0):
    """Return symbolic logic for an N-bit Kogge-Stone adder."""
    if len(A) != len(B):
        raise ValueError('expected A and B to be equal length')
    N = len(A)
    gs = [A[i] & B[i] for i in range(N)]
    ps = [A[i] ^ B[i] for i in range(N)]
    for i in range(clog2(N)):
        start = 1 << i
        for j in range(start, N):
            gs[j] = gs[j] | ps[j] & gs[j - start]
            ps[j] = ps[j] & ps[j - start]
    ss = [A[0] ^ B[0] ^ cin]
    ss += [A[i] ^ B[i] ^ gs[i - 1] for i in range(1, N)]
    return (farray(ss), farray(gs))

def brent_kung_add(A, B, cin=0):
    """Return symbolic logic for an N-bit Brent-Kung adder."""
    if len(A) != len(B):
        raise ValueError('expected A and B to be equal length')
    N = len(A)
    gs = [A[i] & B[i] for i in range(N)]
    ps = [A[i] ^ B[i] for i in range(N)]
    for i in range(floor(log(N, 2))):
        step = 2 ** i
        for start in range(2 ** (i + 1) - 1, N, 2 ** (i + 1)):
            gs[start] = gs[start] | ps[start] & gs[start - step]
            ps[start] = ps[start] & ps[start - step]
    for i in range(floor(log(N, 2)) - 2, -1, -1):
        start = 2 ** (i + 1) - 1
        step = 2 ** i
        while start + step < N:
            gs[start + step] = gs[start + step] | ps[start + step] & gs[start]
            ps[start + step] = ps[start + step] & ps[start]
            start += step
    ss = [A[0] ^ B[0] ^ cin]
    ss += [A[i] ^ B[i] ^ gs[i - 1] for i in range(1, N)]
    return (farray(ss), farray(gs))

def _expect_token(lexer, types):
    """Return the next token, or raise an exception."""
    tok = next(lexer)
    if any((isinstance(tok, t) for t in types)):
        return tok
    else:
        raise Error('unexpected token: ' + str(tok))

def _cnf_formula(lexer, varname, nvars, nclauses):
    """Return a DIMACS CNF formula."""
    clauses = _clauses(lexer, varname, nvars)
    if len(clauses) < nclauses:
        fstr = 'formula has fewer than {} clauses'
        raise Error(fstr.format(nclauses))
    if len(clauses) > nclauses:
        fstr = 'formula has more than {} clauses'
        raise Error(fstr.format(nclauses))
    return ('and',) + clauses

def _clauses(lexer, varname, nvars):
    """Return a tuple of DIMACS CNF clauses."""
    tok = next(lexer)
    toktype = type(tok)
    if toktype is OP_not or toktype is IntegerToken:
        lexer.unpop_token(tok)
        first = _clause(lexer, varname, nvars)
        rest = _clauses(lexer, varname, nvars)
        return (first,) + rest
    else:
        lexer.unpop_token(tok)
        return tuple()

def _lits(lexer, varname, nvars):
    """Return a tuple of DIMACS CNF clause literals."""
    tok = _expect_token(lexer, {OP_not, IntegerToken})
    if isinstance(tok, IntegerToken) and tok.value == 0:
        return tuple()
    else:
        if isinstance(tok, OP_not):
            neg = True
            tok = _expect_token(lexer, {IntegerToken})
        else:
            neg = False
        index = tok.value
        if index > nvars:
            fstr = 'formula literal {} is greater than {}'
            raise Error(fstr.format(index, nvars))
        lit = ('var', (varname,), (index,))
        if neg:
            lit = ('not', lit)
        return (lit,) + _lits(lexer, varname, nvars)

def _sat_formula(lexer, varname, fmt, nvars):
    """Return a DIMACS SAT formula."""
    types = {IntegerToken, LPAREN} | _SAT_TOKS[fmt]
    tok = _expect_token(lexer, types)
    if isinstance(tok, IntegerToken):
        index = tok.value
        if not 0 < index <= nvars:
            fstr = 'formula literal {} outside valid range: (0, {}]'
            raise Error(fstr.format(index, nvars))
        return ('var', (varname,), (index,))
    elif isinstance(tok, OP_not):
        tok = _expect_token(lexer, {IntegerToken, LPAREN})
        if isinstance(tok, IntegerToken):
            index = tok.value
            if not 0 < index <= nvars:
                fstr = 'formula literal {} outside valid range: (0, {}]'
                raise Error(fstr.format(index, nvars))
            return ('not', ('var', (varname,), (index,)))
        else:
            formula = _sat_formula(lexer, varname, fmt, nvars)
            _expect_token(lexer, {RPAREN})
            return ('not', formula)
    elif isinstance(tok, LPAREN):
        formula = _sat_formula(lexer, varname, fmt, nvars)
        _expect_token(lexer, {RPAREN})
        return formula
    else:
        _expect_token(lexer, {LPAREN})
        formulas = _formulas(lexer, varname, fmt, nvars)
        _expect_token(lexer, {RPAREN})
        return (tok.ASTOP,) + formulas

def action(toktype):
    """Return a parser action property."""
    def outer(func):
        """Return a function that pushes a token onto the token queue."""
        def inner(lexer, text):
            """Push a token onto the token queue."""
            value = func(lexer, text)
            lexer.tokens.append(toktype(value, lexer.lineno, lexer.offset))
        return inner
    return outer

def cached_property(func):
    """Return a cached property calculated by the input function.

    Unlike the ``property`` decorator builtin, this decorator will cache the
    return value in order to avoid repeated calculations.
    This is particularly useful when the property involves some non-trivial
    computation.

    For example, consider a class that models a right triangle.
    The hypotenuse ``c`` will only be calculated once.

    .. code-block:: python

       import math

       class RightTriangle:
           def __init__(self, a, b):
               self.a = a
               self.b = b

           @cached_property
           def c(self):
               return math.sqrt(self.a**2 + self.b**2)"""
    def get(self):
        """this docstring will be over-written by func.__doc__"""
        try:
            return self._property_cache[func]
        except AttributeError:
            self._property_cache = dict()
            prop = self._property_cache[func] = func(self)
            return prop
        except KeyError:
            prop = self._property_cache[func] = func(self)
            return prop
    get.__doc__ = func.__doc__
    return property(get)

def point2upoint(point):
    """Convert *point* into an untyped point."""
    upoint = [set(), set()]
    for v, val in point.items():
        upoint[val].add(v.uniqid)
    upoint[0] = frozenset(upoint[0])
    upoint[1] = frozenset(upoint[1])
    return tuple(upoint)

def point2term(point, conj=False):
    """Convert *point* into a min/max term.

    If *conj* is ``False``, return a minterm.
    Otherwise, return a maxterm."""
    if conj:
        return tuple((~v if val else v for v, val in point.items()))
    else:
        return tuple((v if val else ~v for v, val in point.items()))

def _flatten(v, val):
    """Recursively flatten vectorized var => {0, 1} mappings."""
    if isinstance(v, Variable):
        yield (v, int(val))
    else:
        if len(v) != len(val):
            raise ValueError('expected 1:1 mapping from Variable => {0, 1}')
        for _var, _val in zip(v, val):
            yield from _flatten(_var, _val)

def truthtable(inputs, outputs):
    """Return a truth table."""
    def items():
        """Convert all outputs to PC notation."""
        for output in outputs:
            if isinstance(output, boolfunc.Function):
                output = output.unbox()
            if output in (0, '0'):
                yield PC_ZERO
            elif output in (1, '1'):
                yield PC_ONE
            elif output in '-xX':
                yield PC_DC
            else:
                fstr = 'expected output in [01-xX], got {}'
                raise ValueError(fstr.format(output))
    inputs = [ttvar(v.names, v.indices) for v in inputs]
    pcdata = PCData(items())
    if len(pcdata) != 1 << len(inputs):
        fstr = 'expected {} outputs, got {}'
        raise ValueError(fstr.format(1 << len(inputs), len(pcdata)))
    return _truthtable(inputs, pcdata)

def _truthtable(inputs, pcdata):
    """Return a truth table."""
    if len(inputs) == 0 and pcdata[0] in {PC_ZERO, PC_ONE}:
        return {PC_ZERO: TTZERO, PC_ONE: TTONE}[pcdata[0]]
    elif len(inputs) == 1 and pcdata[0] == PC_ZERO and (pcdata[1] == PC_ONE):
        return inputs[0]
    else:
        return TruthTable(inputs, pcdata)

def expr2truthtable(expr):
    """Convert an expression into a truth table."""
    inputs = [ttvar(v.names, v.indices) for v in expr.inputs]
    return truthtable(inputs, expr.iter_image())

def truthtable2expr(tt, conj=False):
    """Convert a truth table into an expression."""
    if conj:
        outer, inner = (And, Or)
        nums = tt.pcdata.iter_zeros()
    else:
        outer, inner = (Or, And)
        nums = tt.pcdata.iter_ones()
    inputs = [exprvar(v.names, v.indices) for v in tt.inputs]
    terms = [boolfunc.num2term(num, inputs, conj) for num in nums]
    return outer(*[inner(*term) for term in terms])

def _expr2bddnode(expr):
    """Convert an expression into a BDD node."""
    if expr.is_zero():
        return BDDNODEZERO
    elif expr.is_one():
        return BDDNODEONE
    else:
        top = expr.top
        _ = bddvar(top.names, top.indices)
        root = top.uniqid
        lo = _expr2bddnode(expr.restrict({top: 0}))
        hi = _expr2bddnode(expr.restrict({top: 1}))
        return _bddnode(root, lo, hi)

def bdd2expr(bdd, conj=False):
    """Convert a binary decision diagram into an expression.

    This function will always return an expression in two-level form.
    If *conj* is ``False``, return a sum of products (SOP).
    Otherwise, return a product of sums (POS).

    For example::

       >>> a, b = map(bddvar, 'ab')
       >>> bdd2expr(~a | b)
       Or(~a, And(a, b))"""
    if conj:
        outer, inner = (And, Or)
        paths = _iter_all_paths(bdd.node, BDDNODEZERO)
    else:
        outer, inner = (Or, And)
        paths = _iter_all_paths(bdd.node, BDDNODEONE)
    terms = list()
    for path in paths:
        expr_point = {exprvar(v.names, v.indices): val for v, val in _path2point(path).items()}
        terms.append(boolfunc.point2term(expr_point, conj))
    return outer(*[inner(*term) for term in terms])

def _bddnode(root, lo, hi):
    """Return a unique BDD node."""
    if lo is hi:
        node = lo
    else:
        key = (root, lo, hi)
        try:
            node = _NODES[key]
        except KeyError:
            node = _NODES[key] = BDDNode(*key)
    return node

def _bdd(node):
    """Return a unique BDD."""
    try:
        bdd = _BDDS[node]
    except KeyError:
        bdd = _BDDS[node] = BinaryDecisionDiagram(node)
    return bdd

def _path2point(path):
    """Convert a BDD path to a BDD point."""
    return {_VARS[node.root]: int(node.hi is path[i + 1]) for i, node in enumerate(path[:-1])}

def _neg(node):
    """Return the inverse of *node*."""
    if node is BDDNODEZERO:
        return BDDNODEONE
    elif node is BDDNODEONE:
        return BDDNODEZERO
    else:
        return _bddnode(node.root, _neg(node.lo), _neg(node.hi))

def _ite(f, g, h):
    """Return node that results from recursively applying ITE(f, g, h)."""
    if g is BDDNODEONE and h is BDDNODEZERO:
        return f
    elif g is BDDNODEZERO and h is BDDNODEONE:
        return _neg(f)
    elif f is BDDNODEONE:
        return g
    elif f is BDDNODEZERO:
        return h
    elif g is h:
        return g
    else:
        root = min((node.root for node in (f, g, h) if node.root > 0))
        npoint0 = {root: BDDNODEZERO}
        npoint1 = {root: BDDNODEONE}
        fv0, gv0, hv0 = [_restrict(node, npoint0) for node in (f, g, h)]
        fv1, gv1, hv1 = [_restrict(node, npoint1) for node in (f, g, h)]
        return _bddnode(root, _ite(fv0, gv0, hv0), _ite(fv1, gv1, hv1))

def _restrict(node, npoint, cache=None):
    """Restrict a subset of support variables to {0, 1}."""
    if node is BDDNODEZERO or node is BDDNODEONE:
        return node
    if cache is None:
        cache = dict()
    try:
        ret = cache[node]
    except KeyError:
        try:
            val = npoint[node.root]
        except KeyError:
            lo = _restrict(node.lo, npoint, cache)
            hi = _restrict(node.hi, npoint, cache)
            ret = _bddnode(node.root, lo, hi)
        else:
            child = {BDDNODEZERO: node.lo, BDDNODEONE: node.hi}[val]
            ret = _restrict(child, npoint, cache)
        cache[node] = ret
    return ret

def _find_path(start, end, path=tuple()):
    """Return the path from start to end.

    If no path exists, return None."""
    path = path + (start,)
    if start is end:
        return path
    else:
        ret = None
        if start.lo is not None:
            ret = _find_path(start.lo, end, path)
        if ret is None and start.hi is not None:
            ret = _find_path(start.hi, end, path)
        return ret

def _iter_all_paths(start, end, rand=False, path=tuple()):
    """Iterate through all paths from start to end."""
    path = path + (start,)
    if start is end:
        yield path
    else:
        nodes = [start.lo, start.hi]
        if rand:
            random.shuffle(nodes)
        for node in nodes:
            if node is not None:
                yield from _iter_all_paths(node, end, rand, path)

def _dfs_preorder(node, visited):
    """Iterate through nodes in DFS pre-order."""
    if node not in visited:
        visited.add(node)
        yield node
    if node.lo is not None:
        yield from _dfs_preorder(node.lo, visited)
    if node.hi is not None:
        yield from _dfs_preorder(node.hi, visited)

def _dfs_postorder(node, visited):
    """Iterate through nodes in DFS post-order."""
    if node.lo is not None:
        yield from _dfs_postorder(node.lo, visited)
    if node.hi is not None:
        yield from _dfs_postorder(node.hi, visited)
    if node not in visited:
        visited.add(node)
        yield node

def _bfs(node, visited):
    """Iterate through nodes in BFS order."""
    queue = collections.deque()
    queue.appendleft(node)
    while queue:
        node = queue.pop()
        if node not in visited:
            if node.lo is not None:
                queue.appendleft(node.lo)
            if node.hi is not None:
                queue.appendleft(node.hi)
            visited.add(node)
            yield node

def _ite(lexer):
    """Return an ITE expression."""
    s = _impl(lexer)
    tok = next(lexer)
    if isinstance(tok, OP_question):
        d1 = _ite(lexer)
        _expect_token(lexer, {OP_colon})
        d0 = _ite(lexer)
        return ('ite', s, d1, d0)
    else:
        lexer.unpop_token(tok)
        return s

def _impl(lexer):
    """Return an Implies expression."""
    p = _sumterm(lexer)
    tok = next(lexer)
    if isinstance(tok, OP_rarrow):
        q = _impl(lexer)
        return ('implies', p, q)
    elif isinstance(tok, OP_lrarrow):
        q = _impl(lexer)
        return ('equal', p, q)
    else:
        lexer.unpop_token(tok)
        return p

def _sumterm(lexer):
    """Return a sum term expresssion."""
    xorterm = _xorterm(lexer)
    sumterm_prime = _sumterm_prime(lexer)
    if sumterm_prime is None:
        return xorterm
    else:
        return ('or', xorterm, sumterm_prime)

def _sumterm_prime(lexer):
    """Return a sum term' expression, eliminates left recursion."""
    tok = next(lexer)
    if isinstance(tok, OP_or):
        xorterm = _xorterm(lexer)
        sumterm_prime = _sumterm_prime(lexer)
        if sumterm_prime is None:
            return xorterm
        else:
            return ('or', xorterm, sumterm_prime)
    else:
        lexer.unpop_token(tok)
        return None

def _xorterm(lexer):
    """Return an xor term expresssion."""
    prodterm = _prodterm(lexer)
    xorterm_prime = _xorterm_prime(lexer)
    if xorterm_prime is None:
        return prodterm
    else:
        return ('xor', prodterm, xorterm_prime)

def _xorterm_prime(lexer):
    """Return an xor term' expression, eliminates left recursion."""
    tok = next(lexer)
    if isinstance(tok, OP_xor):
        prodterm = _prodterm(lexer)
        xorterm_prime = _xorterm_prime(lexer)
        if xorterm_prime is None:
            return prodterm
        else:
            return ('xor', prodterm, xorterm_prime)
    else:
        lexer.unpop_token(tok)
        return None

def _prodterm(lexer):
    """Return a product term expression."""
    factor = _factor(lexer)
    prodterm_prime = _prodterm_prime(lexer)
    if prodterm_prime is None:
        return factor
    else:
        return ('and', factor, prodterm_prime)

def _prodterm_prime(lexer):
    """Return a product term' expression, eliminates left recursion."""
    tok = next(lexer)
    if isinstance(tok, OP_and):
        factor = _factor(lexer)
        prodterm_prime = _prodterm_prime(lexer)
        if prodterm_prime is None:
            return factor
        else:
            return ('and', factor, prodterm_prime)
    else:
        lexer.unpop_token(tok)
        return None

def _zom_arg(lexer):
    """Return zero or more arguments."""
    tok = next(lexer)
    if isinstance(tok, COMMA):
        return (_expr(lexer),) + _zom_arg(lexer)
    else:
        lexer.unpop_token(tok)
        return tuple()

def _variable(lexer):
    """Return a variable expression."""
    names = _names(lexer)
    tok = next(lexer)
    if isinstance(tok, LBRACK):
        indices = _indices(lexer)
        _expect_token(lexer, {RBRACK})
    else:
        lexer.unpop_token(tok)
        indices = tuple()
    return ('var', names, indices)

def _zom_name(lexer):
    """Return zero or more names."""
    tok = next(lexer)
    if isinstance(tok, DOT):
        first = _expect_token(lexer, {NameToken}).value
        rest = _zom_name(lexer)
        return (first,) + rest
    else:
        lexer.unpop_token(tok)
        return tuple()

def _zom_index(lexer):
    """Return zero or more indices."""
    tok = next(lexer)
    if isinstance(tok, COMMA):
        first = _expect_token(lexer, {IntegerToken}).value
        rest = _zom_index(lexer)
        return (first,) + rest
    else:
        lexer.unpop_token(tok)
        return tuple()

def rowxcol(row, col):
    """Multiply one row and one column."""
    row = row.reshape(4, 4)
    col = col.reshape(4, 8)
    ret = uint2exprs(0, 8)
    for i in range(4):
        for j in range(4):
            if row[i, j]:
                ret ^= xtime(col[i], j)
    return ret

def xtime(b, n):
    """Repeated polynomial multiplication in GF(2^8)."""
    b = b.reshape(8)
    for _ in range(n):
        b = exprzeros(1) + b[:7] ^ uint2exprs(27, 8) & b[7] * 8
    return b

def sub_bytes(state):
    """Transformation in the Cipher that processes the State using a non\xadlinear
    byte substitution table (S-box) that operates on each of the State bytes
    independently."""
    state = state.reshape(4, 32)
    return fcat(subword(state[0]), subword(state[1]), subword(state[2]), subword(state[3]))

def inv_sub_bytes(state):
    """Transformation in the Inverse Cipher that is the inverse of SubBytes()."""
    state = state.reshape(4, 32)
    return fcat(invsubword(state[0]), invsubword(state[1]), invsubword(state[2]), invsubword(state[3]))

def shift_rows(state):
    """Transformation in the Cipher that processes the State by cyclically shifting
    the last three rows of the State by different offsets."""
    state = state.reshape(4, 4, 8)
    return fcat(state[0][0], state[1][1], state[2][2], state[3][3], state[1][0], state[2][1], state[3][2], state[0][3], state[2][0], state[3][1], state[0][2], state[1][3], state[3][0], state[0][1], state[1][2], state[2][3])

def inv_shift_rows(state):
    """Transformation in the Inverse Cipher that is the inverse of ShiftRows()."""
    state = state.reshape(4, 4, 8)
    return fcat(state[0][0], state[3][1], state[2][2], state[1][3], state[1][0], state[0][1], state[3][2], state[2][3], state[2][0], state[1][1], state[0][2], state[3][3], state[3][0], state[2][1], state[1][2], state[0][3])

def mix_columns(state):
    """Transformation in the Cipher that takes all of the columns of the State and
    mixes their data (independently of one another) to produce new columns."""
    state = state.reshape(4, 4, 8)
    return fcat(multiply(MA, state[0]), multiply(MA, state[1]), multiply(MA, state[2]), multiply(MA, state[3]))

def inv_mix_columns(state):
    """Transformation in the Inverse Cipher that is the inverse of MixColumns()."""
    state = state.reshape(4, 4, 8)
    return fcat(multiply(IMA, state[0]), multiply(IMA, state[1]), multiply(IMA, state[2]), multiply(IMA, state[3]))

def key_expand(key, Nk=4):
    """Expand the key into the round key."""
    assert Nk in {4, 6, 8}
    Nr = Nk + 6
    key = key.reshape(Nk, 32)
    rkey = exprzeros(4 * (Nr + 1), 32)
    for i in range(Nk):
        rkey[i] = key[i]
    for i in range(Nk, 4 * (Nr + 1)):
        if i % Nk == 0:
            rkey[i] = rkey[i - Nk] ^ subword(rotword(rkey[i - 1])) ^ RCON[i // Nk].zext(32 - 8)
        elif Nk > 6 and i % Nk == 4:
            rkey[i] = rkey[i - Nk] ^ subword(rkey[i - 1])
        else:
            rkey[i] = rkey[i - Nk] ^ rkey[i - 1]
    return rkey

def decrypt(key, ct, Nk=4):
    """Decrypt a plain text block."""
    assert Nk in {4, 6, 8}
    rkey = key_expand(key, Nk)
    pt = inv_cipher(rkey, ct, Nk)
    return pt

def gray2bin(G):
    """Convert a gray-coded vector into a binary-coded vector."""
    return farray([G[i:].uxor() for i, _ in enumerate(G)])

def _assume2point():
    """Convert global assumptions to a point."""
    point = dict()
    for lit in _ASSUMPTIONS:
        if isinstance(lit, Complement):
            point[~lit] = 0
        elif isinstance(lit, Variable):
            point[lit] = 1
    return point

def _exprcomp(node):
    """Return a unique Expression complement."""
    try:
        comp = _LITS[node.data()]
    except KeyError:
        comp = _LITS[node.data()] = Complement(node)
    return comp

def expr(obj, simplify=True):
    """Convert an arbitrary object into an Expression."""
    if isinstance(obj, Expression):
        return obj
    elif isinstance(obj, int) and obj in {0, 1}:
        return _CONSTS[obj]
    elif isinstance(obj, str):
        ast = pyeda.parsing.boolexpr.parse(obj)
        ex = ast2expr(ast)
        if simplify:
            ex = ex.simplify()
        return ex
    else:
        return One if bool(obj) else Zero

def ast2expr(ast):
    """Convert an abstract syntax tree to an Expression."""
    if ast[0] == 'const':
        return _CONSTS[ast[1]]
    elif ast[0] == 'var':
        return exprvar(ast[1], ast[2])
    else:
        xs = [ast2expr(x) for x in ast[1:]]
        return ASTOPS[ast[0]](*xs, simplify=False)

def expr2dimacscnf(ex):
    """Convert an expression into an equivalent DIMACS CNF."""
    litmap, nvars, clauses = ex.encode_cnf()
    return (litmap, DimacsCNF(nvars, clauses))

def expr2dimacssat(ex):
    """Convert an expression into an equivalent DIMACS SAT string."""
    if not ex.simple:
        raise ValueError('expected ex to be simplified')
    litmap, nvars = ex.encode_inputs()
    formula = _expr2sat(ex, litmap)
    if 'xor' in formula:
        if '=' in formula:
            fmt = 'satex'
        else:
            fmt = 'satx'
    elif '=' in formula:
        fmt = 'sate'
    else:
        fmt = 'sat'
    return 'p {} {}\n{}'.format(fmt, nvars, formula)

def _expr2sat(ex, litmap):
    """Convert an expression to a DIMACS SAT string."""
    if isinstance(ex, Literal):
        return str(litmap[ex])
    elif isinstance(ex, NotOp):
        return '-(' + _expr2sat(ex.x, litmap) + ')'
    elif isinstance(ex, OrOp):
        return '+(' + ' '.join((_expr2sat(x, litmap) for x in ex.xs)) + ')'
    elif isinstance(ex, AndOp):
        return '*(' + ' '.join((_expr2sat(x, litmap) for x in ex.xs)) + ')'
    elif isinstance(ex, XorOp):
        return 'xor(' + ' '.join((_expr2sat(x, litmap) for x in ex.xs)) + ')'
    elif isinstance(ex, EqualOp):
        return '=(' + ' '.join((_expr2sat(x, litmap) for x in ex.xs)) + ')'
    else:
        fstr = 'expected ex to be a Literal or Not/Or/And/Xor/Equal op, got {0.__name__}'
        raise ValueError(fstr.format(type(ex)))

def Not(x, simplify=True):
    """Expression negation operator

    If *simplify* is ``True``, return a simplified expression."""
    x = Expression.box(x).node
    y = exprnode.not_(x)
    if simplify:
        y = y.simplify()
    return _expr(y)

def Or(*xs, simplify=True):
    """Expression disjunction (sum, OR) operator

    If *simplify* is ``True``, return a simplified expression."""
    xs = [Expression.box(x).node for x in xs]
    y = exprnode.or_(*xs)
    if simplify:
        y = y.simplify()
    return _expr(y)

def And(*xs, simplify=True):
    """Expression conjunction (product, AND) operator

    If *simplify* is ``True``, return a simplified expression."""
    xs = [Expression.box(x).node for x in xs]
    y = exprnode.and_(*xs)
    if simplify:
        y = y.simplify()
    return _expr(y)

def Xor(*xs, simplify=True):
    """Expression exclusive or (XOR) operator

    If *simplify* is ``True``, return a simplified expression."""
    xs = [Expression.box(x).node for x in xs]
    y = exprnode.xor(*xs)
    if simplify:
        y = y.simplify()
    return _expr(y)

def Equal(*xs, simplify=True):
    """Expression equality operator

    If *simplify* is ``True``, return a simplified expression."""
    xs = [Expression.box(x).node for x in xs]
    y = exprnode.eq(*xs)
    if simplify:
        y = y.simplify()
    return _expr(y)

def Implies(p, q, simplify=True):
    """Expression implication operator

    If *simplify* is ``True``, return a simplified expression."""
    p = Expression.box(p).node
    q = Expression.box(q).node
    y = exprnode.impl(p, q)
    if simplify:
        y = y.simplify()
    return _expr(y)

def ITE(s, d1, d0, simplify=True):
    """Expression If-Then-Else (ITE) operator

    If *simplify* is ``True``, return a simplified expression."""
    s = Expression.box(s).node
    d1 = Expression.box(d1).node
    d0 = Expression.box(d0).node
    y = exprnode.ite(s, d1, d0)
    if simplify:
        y = y.simplify()
    return _expr(y)

def Nor(*xs, simplify=True):
    """Expression NOR (not OR) operator

    If *simplify* is ``True``, return a simplified expression."""
    xs = [Expression.box(x).node for x in xs]
    y = exprnode.not_(exprnode.or_(*xs))
    if simplify:
        y = y.simplify()
    return _expr(y)

def Nand(*xs, simplify=True):
    """Expression NAND (not AND) operator

    If *simplify* is ``True``, return a simplified expression."""
    xs = [Expression.box(x).node for x in xs]
    y = exprnode.not_(exprnode.and_(*xs))
    if simplify:
        y = y.simplify()
    return _expr(y)

def Xnor(*xs, simplify=True):
    """Expression exclusive nor (XNOR) operator

    If *simplify* is ``True``, return a simplified expression."""
    xs = [Expression.box(x).node for x in xs]
    y = exprnode.not_(exprnode.xor(*xs))
    if simplify:
        y = y.simplify()
    return _expr(y)

def Unequal(*xs, simplify=True):
    """Expression inequality operator

    If *simplify* is ``True``, return a simplified expression."""
    xs = [Expression.box(x).node for x in xs]
    y = exprnode.not_(exprnode.eq(*xs))
    if simplify:
        y = y.simplify()
    return _expr(y)

def OneHot0(*xs, simplify=True, conj=True):
    """Return an expression that means
    "at most one input function is true".

    If *simplify* is ``True``, return a simplified expression.

    If *conj* is ``True``, return a CNF.
    Otherwise, return a DNF."""
    xs = [Expression.box(x).node for x in xs]
    terms = list()
    if conj:
        for x0, x1 in itertools.combinations(xs, 2):
            terms.append(exprnode.or_(exprnode.not_(x0), exprnode.not_(x1)))
        y = exprnode.and_(*terms)
    else:
        for _xs in itertools.combinations(xs, len(xs) - 1):
            terms.append(exprnode.and_(*[exprnode.not_(x) for x in _xs]))
        y = exprnode.or_(*terms)
    if simplify:
        y = y.simplify()
    return _expr(y)

def OneHot(*xs, simplify=True, conj=True):
    """Return an expression that means
    "exactly one input function is true".

    If *simplify* is ``True``, return a simplified expression.

    If *conj* is ``True``, return a CNF.
    Otherwise, return a DNF."""
    xs = [Expression.box(x).node for x in xs]
    terms = list()
    if conj:
        for x0, x1 in itertools.combinations(xs, 2):
            terms.append(exprnode.or_(exprnode.not_(x0), exprnode.not_(x1)))
        terms.append(exprnode.or_(*xs))
        y = exprnode.and_(*terms)
    else:
        for i, xi in enumerate(xs):
            zeros = [exprnode.not_(x) for x in xs[:i] + xs[i + 1:]]
            terms.append(exprnode.and_(xi, *zeros))
        y = exprnode.or_(*terms)
    if simplify:
        y = y.simplify()
    return _expr(y)

def NHot(n, *xs, simplify=True):
    """Return an expression that means
    "exactly N input functions are true".

    If *simplify* is ``True``, return a simplified expression."""
    if not isinstance(n, int):
        raise TypeError('expected n to be an int')
    if not 0 <= n <= len(xs):
        fstr = 'expected 0 <= n <= {}, got {}'
        raise ValueError(fstr.format(len(xs), n))
    xs = [Expression.box(x).node for x in xs]
    num = len(xs)
    terms = list()
    for hot_idxs in itertools.combinations(range(num), n):
        hot_idxs = set(hot_idxs)
        _xs = [xs[i] if i in hot_idxs else exprnode.not_(xs[i]) for i in range(num)]
        terms.append(exprnode.and_(*_xs))
    y = exprnode.or_(*terms)
    if simplify:
        y = y.simplify()
    return _expr(y)

def AchillesHeel(*xs, simplify=True):
    """Return the Achille's Heel function, defined as:
    :math:`\\prod_{i=0}^{n/2-1}{X_{2i} + X_{2i+1}}`.

    If *simplify* is ``True``, return a simplified expression."""
    nargs = len(xs)
    if nargs & 1:
        fstr = 'expected an even number of arguments, got {}'
        raise ValueError(fstr.format(nargs))
    xs = [Expression.box(x).node for x in xs]
    y = exprnode.and_(*[exprnode.or_(xs[2 * i], xs[2 * i + 1]) for i in range(nargs // 2)])
    if simplify:
        y = y.simplify()
    return _expr(y)

def Mux(fs, sel, simplify=True):
    """Return an expression that multiplexes a sequence of input functions over a
    sequence of select functions."""
    if isinstance(sel, Expression):
        sel = [sel]
    if len(sel) < clog2(len(fs)):
        fstr = 'expected at least {} select bits, got {}'
        raise ValueError(fstr.format(clog2(len(fs)), len(sel)))
    it = boolfunc.iter_terms(sel)
    y = exprnode.or_(*[exprnode.and_(f.node, *[lit.node for lit in next(it)]) for f in fs])
    if simplify:
        y = y.simplify()
    return _expr(y)

def _backtrack(ex):
    """If this function is satisfiable, return a satisfying input upoint.
    Otherwise, return None."""
    if ex is Zero:
        return None
    elif ex is One:
        return dict()
    else:
        v = ex.top
        points = ({v: 0}, {v: 1})
        for point in points:
            soln = _backtrack(ex.restrict(point))
            if soln is not None:
                soln.update(point)
                return soln
        return None

def _iter_backtrack(ex, rand=False):
    """Iterate through all satisfying points using backtrack algorithm."""
    if ex is One:
        yield dict()
    elif ex is not Zero:
        if rand:
            v = random.choice(ex.inputs) if rand else ex.top
        else:
            v = ex.top
        points = [{v: 0}, {v: 1}]
        if rand:
            random.shuffle(points)
        for point in points:
            for soln in _iter_backtrack(ex.restrict(point), rand):
                soln.update(point)
                yield soln

def _tseitin(ex, auxvarname, auxvars=None):
    """Convert a factored expression to a literal, and a list of constraints."""
    if isinstance(ex, Literal):
        return (ex, list())
    else:
        if auxvars is None:
            auxvars = list()
        lits = list()
        constraints = list()
        for x in ex.xs:
            lit, subcons = _tseitin(x, auxvarname, auxvars)
            lits.append(lit)
            constraints.extend(subcons)
        auxvarindex = len(auxvars)
        auxvar = exprvar(auxvarname, auxvarindex)
        auxvars.append(auxvar)
        f = ASTOPS[ex.ASTOP](*lits)
        constraints.append((auxvar, f))
        return (auxvar, constraints)

def _cover2exprs(inputs, noutputs, cover):
    """Convert a cover to a tuple of Expression instances."""
    fs = list()
    for i in range(noutputs):
        terms = list()
        for invec, outvec in cover:
            if outvec[i]:
                term = list()
                for j, v in enumerate(inputs):
                    if invec[j] == 1:
                        term.append(~v)
                    elif invec[j] == 2:
                        term.append(v)
                terms.append(term)
        fs.append(Or(*[And(*term) for term in terms]))
    return tuple(fs)

def fcat(*fs):
    """Concatenate a sequence of farrays.

    The variadic *fs* input is a homogeneous sequence of functions or arrays."""
    items = list()
    for f in fs:
        if isinstance(f, boolfunc.Function):
            items.append(f)
        elif isinstance(f, farray):
            items.extend(f.flat)
        else:
            raise TypeError('expected Function or farray')
    return farray(items)

def _dims2shape(*dims):
    """Convert input dimensions to a shape."""
    if not dims:
        raise ValueError('expected at least one dimension spec')
    shape = list()
    for dim in dims:
        if isinstance(dim, int):
            dim = (0, dim)
        if isinstance(dim, tuple) and len(dim) == 2:
            if dim[0] < 0:
                raise ValueError('expected low dimension to be >= 0')
            if dim[1] < 0:
                raise ValueError('expected high dimension to be >= 0')
            if dim[0] > dim[1]:
                raise ValueError('expected low <= high dimensions')
            start, stop = dim
        else:
            raise TypeError('expected dimension to be int or (int, int)')
        shape.append((start, stop))
    return tuple(shape)

def _volume(shape):
    """Return the volume of a shape."""
    prod = 1
    for start, stop in shape:
        prod *= stop - start
    return prod

def _zeros(ftype, *dims):
    """Return a new farray filled with zeros."""
    shape = _dims2shape(*dims)
    objs = [ftype.box(0) for _ in range(_volume(shape))]
    return farray(objs, shape, ftype)

def _vars(ftype, name, *dims):
    """Return a new farray filled with Boolean variables."""
    shape = _dims2shape(*dims)
    objs = list()
    for indices in itertools.product(*[range(i, j) for i, j in shape]):
        objs.append(_VAR[ftype](name, indices))
    return farray(objs, shape, ftype)

def _uint2objs(ftype, num, length=None):
    """Convert an unsigned integer to a list of constant expressions."""
    if num == 0:
        objs = [ftype.box(0)]
    else:
        _num = num
        objs = list()
        while _num != 0:
            objs.append(ftype.box(_num & 1))
            _num >>= 1
    if length:
        if length < len(objs):
            fstr = 'overflow: num = {} requires length >= {}, got length = {}'
            raise ValueError(fstr.format(num, len(objs), length))
        else:
            while len(objs) < length:
                objs.append(ftype.box(0))
    return objs

def _uint2farray(ftype, num, length=None):
    """Convert an unsigned integer to an farray."""
    if num < 0:
        raise ValueError('expected num >= 0')
    else:
        objs = _uint2objs(ftype, num, length)
        return farray(objs)

def _int2farray(ftype, num, length=None):
    """Convert a signed integer to an farray."""
    if num < 0:
        req_length = clog2(abs(num)) + 1
        objs = _uint2objs(ftype, 2 ** req_length + num)
    else:
        req_length = clog2(num + 1) + 1
        objs = _uint2objs(ftype, num, req_length)
    if length:
        if length < req_length:
            fstr = 'overflow: num = {} requires length >= {}, got length = {}'
            raise ValueError(fstr.format(num, req_length, length))
        else:
            sign = objs[-1]
            objs += [sign] * (length - req_length)
    return farray(objs)

def _check_shape(shape):
    """Verify that a shape has the right format."""
    if isinstance(shape, tuple):
        for dim in shape:
            if isinstance(dim, tuple) and len(dim) == 2 and isinstance(dim[0], int) and isinstance(dim[1], int):
                if dim[0] < 0:
                    raise ValueError('expected low dimension to be >= 0')
                if dim[1] < 0:
                    raise ValueError('expected high dimension to be >= 0')
                if dim[0] > dim[1]:
                    raise ValueError('expected low <= high dimensions')
            else:
                raise TypeError('expected shape dimension to be (int, int)')
    else:
        raise TypeError('expected shape to be tuple of (int, int)')

def _get_key2sl(key):
    """Convert a key part to a slice part."""
    if isinstance(key, (int, farray)) or key is Ellipsis:
        return key
    elif isinstance(key, slice):
        if key.step is not None:
            raise ValueError('farray slice step is not supported')
        return key
    elif isinstance(key, boolfunc.Function):
        return farray([key])
    else:
        raise TypeError('expected int, slice, Function, farray, or ...')

def _set_key2sl(key):
    """Convert a key part to a slice part."""
    if isinstance(key, int) or key is Ellipsis:
        return key
    elif isinstance(key, slice):
        if key.step is not None:
            raise ValueError('farray slice step is not supported')
        return key
    else:
        raise TypeError('expected int, slice, or ...')

def _norm_index(dim, index, start, stop):
    """Return an index normalized to an farray start index."""
    length = stop - start
    if -length <= index < 0:
        normindex = index + length
    elif start <= index < stop:
        normindex = index - start
    else:
        fstr = 'expected dim {} index in range [{}, {})'
        raise IndexError(fstr.format(dim, start, stop))
    return normindex

def _norm_slice(sl, start, stop):
    """Return a slice normalized to an farray start index."""
    length = stop - start
    if sl.start is None:
        normstart = 0
    elif sl.start < 0:
        if sl.start < -length:
            normstart = 0
        else:
            normstart = sl.start + length
    elif sl.start > stop:
        normstart = length
    else:
        normstart = sl.start - start
    if sl.stop is None:
        normstop = length
    elif sl.stop < 0:
        if sl.stop < -length:
            normstop = 0
        else:
            normstop = sl.stop + length
    elif sl.stop > stop:
        normstop = length
    else:
        normstop = sl.stop - start
    if normstop < normstart:
        normstop = normstart
    return slice(normstart, normstop)

def _filtdim(items, shape, dim, nsl):
    """Return items, shape filtered by a dimension slice."""
    normshape = tuple((stop - start for start, stop in shape))
    nsl_type = type(nsl)
    newitems = list()
    num = reduce(operator.mul, normshape[:dim + 1])
    size = len(items) // num
    n = normshape[dim]
    if nsl_type is int:
        for i in range(num):
            if i % n == nsl:
                newitems += items[size * i:size * (i + 1)]
        newshape = shape[:dim] + shape[dim + 1:]
    elif nsl_type is slice:
        for i in range(num):
            if nsl.start <= i % n < nsl.stop:
                newitems += items[size * i:size * (i + 1)]
        offset = shape[dim][0]
        redim = (offset + nsl.start, offset + nsl.stop)
        newshape = shape[:dim] + (redim,) + shape[dim + 1:]
    else:
        if nsl.size < clog2(n):
            fstr = 'expected dim {} select to have >= {} bits, got {}'
            raise ValueError(fstr.format(dim, clog2(n), nsl.size))
        groups = [list() for _ in range(n)]
        for i in range(num):
            groups[i % n] += items[size * i:size * (i + 1)]
        for muxins in zip(*groups):
            it = boolfunc.iter_terms(nsl._items)
            xs = [reduce(operator.and_, (muxin,) + next(it)) for muxin in muxins]
            newitems.append(reduce(operator.or_, xs))
        newshape = shape[:dim] + shape[dim + 1:]
    return (newitems, newshape)

def _iter_coords(nsls):
    """Iterate through all matching coordinates in a sequence of slices."""
    ranges = list()
    for nsl in nsls:
        if isinstance(nsl, int):
            ranges.append(range(nsl, nsl + 1))
        else:
            ranges.append(range(nsl.start, nsl.stop))
    yield from itertools.product(*ranges)

def parse(text: str, style: Style=Style.auto) -> Docstring:
    """Parse the docstring into its components.

    :param text: docstring text to parse
    :param style: docstring style
    :returns: parsed docstring representation"""
    if style != Style.auto:
        return _styles[style](text)
    rets = []
    for parse_ in _styles.values():
        try:
            rets.append(parse_(text))
        except ParseError as e:
            exc = e
    if not rets:
        raise exc
    return sorted(rets, key=lambda d: len(d.meta), reverse=True)[0]

def _build_meta(text: str, title: str) -> DocstringMeta:
    """Build docstring element.

    :param text: docstring element text
    :param title: title of section containing element
    :return:"""
    meta = _sections[title]
    if meta == 'returns' and ':' not in text.split()[0]:
        return DocstringMeta([meta], description=text)
    before, desc = text.split(':', 1)
    if desc:
        desc = desc[1:] if desc[0] == ' ' else desc
        if '\n' in desc:
            first_line, rest = desc.split('\n', 1)
            desc = first_line + '\n' + inspect.cleandoc(rest)
        desc = desc.strip('\n')
    m = re.match('(\\S+) \\((\\S+)\\)$', before)
    if meta == 'param' and m:
        arg_name, type_name = m.group(1, 2)
        args = [meta, type_name, arg_name]
    else:
        args = [meta, before]
    return DocstringMeta(args, description=desc)

def _determine_tool(files):
    """Yields tuples in the form of (linker file, tool the file links for"""
    for file in files:
        linker_ext = file.split('.')[-1]
        if 'sct' in linker_ext or 'lin' in linker_ext:
            yield (str(file), 'uvision')
        elif 'ld' in linker_ext:
            yield (str(file), 'make_gcc_arm')
        elif 'icf' in linker_ext:
            yield (str(file), 'iar_arm')

def fix_paths(project_data, rel_path, extensions):
    """Fix paths for extension list"""
    norm_func = lambda path: os.path.normpath(os.path.join(rel_path, path))
    for key in extensions:
        if type(project_data[key]) is dict:
            for k, v in project_data[key].items():
                project_data[key][k] = [norm_func(i) for i in v]
        elif type(project_data[key]) is list:
            project_data[key] = [norm_func(i) for i in project_data[key]]
        else:
            project_data[key] = norm_func(project_data[key])

def make_timedelta(value):
    """Tries to convert the given value to a :class:`datetime.timedelta`.

    Strings will be parsed as ISO 8601 durations.

    If a number is provided, it will be interpreted as the number of
    seconds.

    If a `dict` is provided, does `datetime.timedelta(**value)`.

    :param value: something to convert
    :type value: str | unicode | float | int | datetime.timedelta | dict
    :return: the value after conversion
    :rtype: datetime.timedelta"""
    if isinstance(value, basestring):
        try:
            return aniso8601.parse_duration(value)
        except Exception as e:
            msg = 'Conversion to datetime.timedelta failed. Could not parse the given string as an ISO 8601 duration: %s\n\n%s' % (repr(value), e.message)
            raise ValueError(msg)
    try:
        if isinstance(value, datetime.timedelta):
            return value
        elif isinstance(value, dict):
            return datetime.timedelta(**value)
        elif isinstance(value, (float, int)):
            return datetime.timedelta(seconds=value)
        else:
            return datetime.timedelta(value)
    except Exception as e:
        msg = "Could not convert the given value of type '%s' to a datetime.timedelta: %s\n\n%s" % (value.__class__.__name__, repr(value), e.message)
        raise TypeError(msg) if isinstance(e, TypeError) else ValueError(msg)

def zip_dicts(left, right, prefix=()):
    """Modified zip through two dictionaries.

    Iterate through all keys of left dictionary, returning:

      -  A nested path
      -  A value and parent for both dictionaries"""
    for key, left_value in left.items():
        path = prefix + (key,)
        right_value = right.get(key)
        if isinstance(left_value, dict):
            yield from zip_dicts(left_value, right_value or {}, path)
        else:
            yield (path, left, left_value, right, right_value)

def boolean(value):
    """Configuration-friendly boolean type converter.

    Supports both boolean-valued and string-valued inputs (e.g. from env vars)."""
    if isinstance(value, bool):
        return value
    if value == '':
        return False
    return strtobool(value)

def load_from_dict(dct=None, **kwargs):
    """Load configuration from a dictionary."""
    dct = dct or dict()
    dct.update(kwargs)
    def _load_from_dict(metadata):
        return dict(dct)
    return _load_from_dict

def binding(key, registry=None):
    """Creates a decorator that binds a factory function to a key.

    :param key: the binding key
    :param: registry: the registry to bind to; defaults to the global registry"""
    if registry is None:
        registry = _registry
    def decorator(func):
        registry.bind(key, func)
        return func
    return decorator

def defaults(**kwargs):
    """Creates a decorator that saves the provided kwargs as defaults for a factory function."""
    def decorator(func):
        setattr(func, DEFAULTS, kwargs)
        return func
    return decorator

def _invoke_hook(hook_name, target):
    """Generic hook invocation."""
    try:
        for value in getattr(target, hook_name):
            func, args, kwargs = value
            func(target, *args, **kwargs)
    except AttributeError:
        pass
    except (TypeError, ValueError):
        pass

def on_resolve(target, func, *args, **kwargs):
    """Register a resolution hook."""
    return _register_hook(ON_RESOLVE, target, func, *args, **kwargs)

def create_cache(name):
    """Create a cache by name.

    Defaults to `NaiveCache`"""
    caches = {subclass.name(): subclass for subclass in Cache.__subclasses__()}
    return caches.get(name, NaiveCache)()

def get_config_filename(metadata):
    """Derive a configuration file name from the FOO_SETTINGS
    environment variable."""
    envvar = '{}__SETTINGS'.format(underscore(metadata.name).upper())
    try:
        return environ[envvar]
    except KeyError:
        return None

def _load_from_file(metadata, load_func):
    """Load configuration from a file.

    The file path is derived from an environment variable
    named after the service of the form FOO_SETTINGS."""
    config_filename = get_config_filename(metadata)
    if config_filename is None:
        return dict()
    with open(config_filename, 'r') as file_:
        data = load_func(file_.read())
        return dict(data)

def load_each(*loaders):
    """Loader factory that combines a series of loaders."""
    def _load_each(metadata):
        return merge((loader(metadata) for loader in loaders))
    return _load_each

def get_root_uri(uri):
    """Return root URI - strip query and fragment."""
    chunks = urlsplit(uri)
    return urlunsplit((chunks.scheme, chunks.netloc, chunks.path, '', ''))

def _parse_date_input(date_input, default_offset=0):
    """Parses a date input."""
    if date_input:
        try:
            return parse_date_input(date_input)
        except ValueError as err:
            raise CommandError(force_text(err))
    else:
        return get_midnight() - timedelta(days=default_offset)

def process_report(request):
    """Given the HTTP request of a CSP violation report, log it in the required ways."""
    if config.EMAIL_ADMINS:
        email_admins(request)
    if config.LOG:
        log_report(request)
    if config.SAVE:
        save_report(request)
    if config.ADDITIONAL_HANDLERS:
        run_additional_handlers(request)

def format_report(jsn):
    """Given a JSON report, return a nicely formatted (i.e. with indentation) string.
    This should handle invalid JSON (as the JSON comes from the browser/user).
    We trust that Python's json library is secure, but if the JSON is invalid then we still
    want to be able to display it, rather than tripping up on a ValueError."""
    if isinstance(jsn, bytes):
        jsn = jsn.decode('utf-8')
    try:
        return json.dumps(json.loads(jsn), indent=4, sort_keys=True, separators=(',', ': '))
    except ValueError:
        return 'Invalid JSON. Raw dump is below.\n\n' + jsn

def get_additional_handlers():
    """Returns the actual functions from the dotted paths specified in ADDITIONAL_HANDLERS."""
    global _additional_handlers
    if not isinstance(_additional_handlers, list):
        handlers = []
        for name in config.ADDITIONAL_HANDLERS:
            module_name, function_name = name.rsplit('.', 1)
            function = getattr(import_module(module_name), function_name)
            handlers.append(function)
        _additional_handlers = handlers
    return _additional_handlers

def parse_date_input(value):
    """Return datetime based on the user's input.

    @param value: User's input
    @type value: str
    @raise ValueError: If the input is not valid.
    @return: Datetime of the beginning of the user's date."""
    try:
        limit = parse_date(value)
    except ValueError:
        limit = None
    if limit is None:
        raise ValueError("'{}' is not a valid date.".format(value))
    limit = datetime(limit.year, limit.month, limit.day)
    if settings.USE_TZ:
        limit = make_aware(limit)
    return limit

def get_midnight():
    """Return last midnight in localtime as datetime.

    @return: Midnight datetime"""
    limit = now()
    if settings.USE_TZ:
        limit = localtime(limit)
    return limit.replace(hour=0, minute=0, second=0, microsecond=0)

def as_chord(chord):
    """convert from str to Chord instance if input is str

    :type chord: str|pychord.Chord
    :param chord: Chord name or Chord instance
    :rtype: pychord.Chord
    :return: Chord instance"""
    if isinstance(chord, Chord):
        return chord
    elif isinstance(chord, str):
        return Chord(chord)
    else:
        raise TypeError('input type should be str or Chord instance.')

def parse(chord):
    """Parse a string to get chord component

    :param str chord: str expression of a chord
    :rtype: (str, pychord.Quality, str, str)
    :return: (root, quality, appended, on)"""
    if len(chord) > 1 and chord[1] in ('b', '#'):
        root = chord[:2]
        rest = chord[2:]
    else:
        root = chord[:1]
        rest = chord[1:]
    check_note(root, chord)
    on_chord_idx = rest.find('/')
    if on_chord_idx >= 0:
        on = rest[on_chord_idx + 1:]
        rest = rest[:on_chord_idx]
        check_note(on, chord)
    else:
        on = None
    if rest in QUALITY_DICT:
        quality = Quality(rest)
    else:
        raise ValueError('Invalid chord {}: Unknown quality {}'.format(chord, rest))
    appended = []
    return (root, quality, appended, on)

def note_to_chord(notes):
    """Convert note list to chord list

    :param list[str] notes: list of note arranged from lower note. ex) ["C", "Eb", "G"]
    :rtype: list[pychord.Chord]
    :return: list of chord"""
    if not notes:
        raise ValueError('Please specify notes which consist a chord.')
    root = notes[0]
    root_and_positions = []
    for rotated_notes in get_all_rotated_notes(notes):
        rotated_root = rotated_notes[0]
        root_and_positions.append([rotated_root, notes_to_positions(rotated_notes, rotated_notes[0])])
    chords = []
    for temp_root, positions in root_and_positions:
        quality = find_quality(positions)
        if quality is None:
            continue
        if temp_root == root:
            chord = '{}{}'.format(root, quality)
        else:
            chord = '{}{}/{}'.format(temp_root, quality, root)
        chords.append(Chord(chord))
    return chords

def find_quality(positions):
    """Find a quality consists of positions

    :param list[int] positions: note positions
    :rtype: str|None"""
    for q, p in QUALITY_DICT.items():
        if positions == list(p):
            return q
    return None

def iter_links(operations, page):
    """Generate links for an iterable of operations on a starting page."""
    for operation, ns, rule, func in operations:
        yield Link.for_(operation=operation, ns=ns, type=ns.subject_name, qs=page.to_items())

def build_logger_tree():
    """Build a DFS tree representing the logger layout.

    Adapted with much appreciation from: https://github.com/brandon-rhodes/logging_tree"""
    cache = {}
    tree = make_logger_node('', root)
    for name, logger in sorted(root.manager.loggerDict.items()):
        if '.' in name:
            parent_name = '.'.join(name.split('.')[:-1])
            parent = cache[parent_name]
        else:
            parent = tree
        cache[name] = make_logger_node(name, logger, parent)
    return tree

def swagger_field(swagger_type='string', swagger_format=None):
    """Decorator for an existing field type to coerce a specific swagger type/format.

    Usage:

        class MySchema(Schema):
             myfield = swagger_field(swagger_type="string")(fields.Foo())"""
    def decorator(field):
        setattr(field, SWAGGER_TYPE, swagger_type)
        setattr(field, SWAGGER_FORMAT, swagger_format)
        return field
    return decorator

def use_forwarded_port(graph):
    """Inject the `X-Forwarded-Port` (if any) into the current URL adapter.

    The URL adapter is used by `url_for` to build a URLs."""
    context = _request_ctx_stack.top
    if _request_ctx_stack is None:
        return None
    forwarded_host = graph.config.port_forwarding.get('host')
    forwarded_port = request.headers.get('X-Forwarded-Port')
    if not forwarded_port and (not forwarded_host):
        return None
    if ':' in context.url_adapter.server_name:
        server_host, server_port = context.url_adapter.server_name.split(':', 1)
    else:
        server_host = context.url_adapter.server_name
        server_port = 443 if context.url_adapter.url_scheme == 'https' else 80
    if forwarded_host:
        server_name = forwarded_host
    elif server_port:
        server_name = '{}:{}'.format(server_host, forwarded_port)
    else:
        server_name = '{}:{}'.format(server_host, server_port)
    context.url_adapter.server_name = server_name
    return server_name

def build_schema(schema: Schema) -> Mapping[str, Any]:
    """Build JSON schema from a marshmallow schema."""
    builder = Schemas(build_parameter=build_parameter)
    return builder.build(schema)

def iter_schemas(schema: Schema) -> Iterable[Tuple[str, Any]]:
    """Build zero or more JSON schemas for a marshmallow schema.

    Generates: name, schema pairs."""
    builder = Schemas(build_parameter=build_parameter)
    return builder.iter_schemas(schema)

def build_parameter(field: Field) -> Mapping[str, Any]:
    """Build JSON parameter from a marshmallow field."""
    builder = Parameters()
    return builder.build(field)

def hide(*keys):
    """Hide a set of request and/or response fields from logs.

    Example:

        @hide("id")
        def create_foo():
            return Foo(id=uuid4())"""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            g.hide_request_fields = keys
            g.hide_response_fields = keys
            return func(*args, **kwargs)
        return wrapper
    return decorator

def show_as(**mappings):
    """Show a set of request and/or response fields in logs using a different key.

    Example:

        @show_as(id="foo_id")
        def create_foo():
            return Foo(id=uuid4())"""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            g.show_request_fields = mappings
            g.show_response_fields = mappings
            return func(*args, **kwargs)
        return wrapper
    return decorator

def encode_basic_auth(username, password):
    """Encode basic auth credentials."""
    return 'Basic {}'.format(b64encode('{}:{}'.format(username, password).encode('utf-8')).decode('utf-8'))

def configure_basic_auth_decorator(graph):
    """Configure a basic auth decorator."""
    graph.config.setdefault('BASIC_AUTH_REALM', graph.metadata.name)
    return ConfigBasicAuth(app=graph.flask, credentials=dict(graph.config.basic_auth.credentials))

def operation_name(operation, ns):
    """Convert an operation, obj(s) pair into a swagger operation id.

    For compatability with Bravado, we want to use underscores instead of dots and
    verb-friendly names. Example:

        foo.retrieve       => client.foo.retrieve()
        foo.search_for.bar => client.foo.search_for_bars()"""
    verb = operation.value.name
    if ns.object_:
        return '{}_{}'.format(verb, pluralize(ns.object_name))
    else:
        return verb

def normalize_uri_result(uri):
    """Normalize a URI (And return a URIResult)"""
    ref = uri_reference(uri).normalize()
    return ref._replace(authority=normalize_uri_authority(ref), query=normalize_uri_query(ref), path=normalize_uri_path(ref))

def name_for(obj):
    """Get a name for something.

    Allows overriding of default names using the `__alias__` attribute."""
    if isinstance(obj, str):
        return obj
    cls = obj if isclass(obj) else obj.__class__
    if hasattr(cls, '__alias__'):
        return underscore(cls.__alias__)
    else:
        return underscore(cls.__name__)

def instance_path_for(name, identifier_type, identifier_key=None):
    """Get a path for thing."""
    return '/{}/<{}:{}>'.format(name_for(name), identifier_type, identifier_key or '{}_id'.format(name_for(name)))

def relation_path_for(from_name, to_name, identifier_type, identifier_key=None):
    """Get a path relating a thing to another."""
    return '/{}/<{}:{}>/{}'.format(name_for(from_name), identifier_type, identifier_key or '{}_id'.format(name_for(from_name)), name_for(to_name))

def encode_id_header(resource):
    """Generate a header for a newly created resource.

    Assume `id` attribute convention."""
    if not hasattr(resource, 'id'):
        return {}
    return {'X-{}-Id'.format(camelize(name_for(resource))): str(resource.id)}

def load_request_data(request_schema, partial=False):
    """Load request data as JSON using the given schema.

    Forces JSON decoding even if the client not specify the `Content-Type` header properly.

    This is friendlier to client and test software, even at the cost of not distinguishing
    HTTP 400 and 415 errors."""
    try:
        json_data = request.get_json(force=True) or {}
    except Exception:
        json_data = {}
    request_data = request_schema.load(json_data, partial=partial)
    if request_data.errors:
        raise with_context(UnprocessableEntity('Validation error'), [{'message': 'Could not validate field: {}'.format(field), 'field': field, 'reasons': reasons} for field, reasons in request_data.errors.items()])
    return request_data.data

def load_query_string_data(request_schema, query_string_data=None):
    """Load query string data using the given schema.

    Schemas are assumed to be compatible with the `PageSchema`."""
    if query_string_data is None:
        query_string_data = request.args
    request_data = request_schema.load(query_string_data)
    if request_data.errors:
        raise with_context(UnprocessableEntity('Validation error'), dict(errors=request_data.errors))
    return request_data.data

def dump_response_data(response_schema, response_data, status_code=200, headers=None, response_format=None):
    """Dumps response data as JSON using the given schema.

    Forces JSON encoding even if the client did not specify the `Accept` header properly.

    This is friendlier to client and test software, even at the cost of not distinguishing
    HTTP 400 and 406 errors."""
    if response_schema:
        response_data = response_schema.dump(response_data).data
    return make_response(response_data, response_schema, response_format, status_code, headers)

def merge_data(path_data, request_data):
    """Merge data from the URI path and the request.

    Path data wins."""
    merged = request_data.copy() if request_data else {}
    merged.update(path_data or {})
    return merged

def find_response_format(allowed_response_formats):
    """Basic content negotiation logic.

    If the 'Accept' header doesn't exactly match a format we can handle, we return JSON"""
    if not allowed_response_formats:
        allowed_response_formats = [ResponseFormats.JSON]
    content_type = request.headers.get('Accept')
    if content_type is None:
        if allowed_response_formats:
            return allowed_response_formats[0]
        return ResponseFormats.JSON
    for response_format in ResponseFormats.prioritized():
        if response_format not in allowed_response_formats:
            continue
        if response_format.matches(content_type):
            return response_format
    return ResponseFormats.JSON

def add_paths(paths, base_path, operations):
    """Add paths to swagger."""
    for operation, ns, rule, func in operations:
        path = build_path(operation, ns)
        if not path.startswith(base_path):
            continue
        method = operation.value.method.lower()
        suffix_start = 0 if len(base_path) == 1 else len(base_path)
        paths.setdefault(path[suffix_start:], swagger.PathItem())[method] = build_operation(operation, ns, rule, func)

def add_definitions(definitions, operations):
    """Add definitions to swagger."""
    for definition_schema in iter_definitions(definitions, operations):
        if definition_schema is None:
            continue
        if isinstance(definition_schema, str):
            continue
        for name, schema in iter_schemas(definition_schema):
            definitions.setdefault(name, swagger.Schema(schema))

def iter_definitions(definitions, operations):
    """Generate definitions to be converted to swagger schema."""
    for error_schema_class in [ErrorSchema, ErrorContextSchema, SubErrorSchema]:
        yield error_schema_class()
    for operation, obj, rule, func in operations:
        yield get_request_schema(func)
        yield get_response_schema(func)

def build_path(operation, ns):
    """Build a path URI for an operation."""
    try:
        return ns.url_for(operation, _external=False)
    except BuildError as error:
        uri_templates = {argument: '{{{}}}'.format(argument) for argument in error.suggested.arguments}
        return unquote(ns.url_for(operation, _external=False, **uri_templates))

def header_param(name, required=False, param_type='string'):
    """Build a header parameter definition."""
    return swagger.HeaderParameterSubSchema(**{'name': name, 'in': 'header', 'required': required, 'type': param_type})

def path_param(name, ns):
    """Build a path parameter definition."""
    if ns.identifier_type == 'uuid':
        param_type = 'string'
        param_format = 'uuid'
    else:
        param_type = 'string'
        param_format = None
    kwargs = {'name': name, 'in': 'path', 'required': True, 'type': param_type}
    if param_format:
        kwargs['format'] = param_format
    return swagger.PathParameterSubSchema(**kwargs)

def add_responses(swagger_operation, operation, ns, func):
    """Add responses to an operation."""
    swagger_operation.responses['default'] = build_response(description='An error occurred', resource=type_name(name_for(ErrorSchema())))
    if getattr(func, '__doc__', None):
        description = func.__doc__.strip().splitlines()[0]
    else:
        description = '{} {}'.format(operation.value.name, ns.subject_name)
    if operation in (Operation.Upload, Operation.UploadFor):
        swagger_operation.consumes = ['multipart/form-data']
    request_resource = get_request_schema(func)
    if isinstance(request_resource, str):
        if not hasattr(swagger_operation, 'consumes'):
            swagger_operation.consumes = []
        swagger_operation.consumes.append(request_resource)
    response_resource = get_response_schema(func)
    if isinstance(response_resource, str):
        if not hasattr(swagger_operation, 'produces'):
            swagger_operation.produces = []
        swagger_operation.produces.append(response_resource)
    elif not response_resource:
        response_code = 204 if operation.value.default_code == 200 else operation.value.default_code
        swagger_operation.responses[str(response_code)] = build_response(description=description)
    else:
        swagger_operation.responses[str(operation.value.default_code)] = build_response(description=description, resource=response_resource)

def build_response(description, resource=None):
    """Build a response definition."""
    response = swagger.Response(description=description)
    if resource is not None:
        response.schema = swagger.JsonReference({'$ref': '#/definitions/{}'.format(type_name(name_for(resource)))})
    return response

def iter_endpoints(graph, match_func):
    """Iterate through matching endpoints.

    The `match_func` is expected to have a signature of:

        def matches(operation, ns, rule):
            return True

    :returns: a generator over (`Operation`, `Namespace`, rule, func) tuples."""
    for rule in graph.flask.url_map.iter_rules():
        try:
            operation, ns = Namespace.parse_endpoint(rule.endpoint, get_converter(rule))
        except (IndexError, ValueError, InternalServerError):
            continue
        else:
            if match_func(operation, ns, rule):
                func = graph.flask.view_functions[rule.endpoint]
                yield (operation, ns, rule, func)

def get_converter(rule):
    """Parse rule will extract the converter from the rule as a generator

    We iterate through the parse_rule results to find the converter
    parse_url returns the static rule part in the first iteration
    parse_url returns the dynamic rule part in the second iteration if its dynamic"""
    for converter, _, _ in parse_rule(str(rule)):
        if converter is not None:
            return converter
    return None

def request(schema):
    """Decorate a function with a request schema."""
    def wrapper(func):
        setattr(func, REQUEST, schema)
        return func
    return wrapper

def response(schema):
    """Decorate a function with a response schema."""
    def wrapper(func):
        setattr(func, RESPONSE, schema)
        return func
    return wrapper

def qs(schema):
    """Decorate a function with a query string schema."""
    def wrapper(func):
        setattr(func, QS, schema)
        return func
    return wrapper

def register_session_factory(graph, key, session_factory):
    """Register a session creation function so that a new session (of user-defined type)
    will be saved to `flask.g` on every request (and closed on teardown).

    In other words: this os a mechanism to register a SQLAlchemy session instance
    or similar without coupling the web and database tiers directly.

    The session function should have the signature:

        def session_factory(graph):
            return Session()

    If the session instance is closeable, it will be closed on teardown."""
    @graph.flask.before_request
    def begin_session():
        setattr(g, key, session_factory(graph))
    @graph.flask.teardown_request
    def end_session(*args, **kwargs):
        session = getattr(g, key, None)
        if session is not None and hasattr(session, 'close'):
            session.close()

def should_skip_logging(func):
    """Should we skip logging for this handler?"""
    disabled = strtobool(request.headers.get('x-request-nolog', 'false'))
    return disabled or getattr(func, SKIP_LOGGING, False)

def logging_levels():
    """Context manager to conditionally set logging levels.

    Supports setting per-request debug logging using the `X-Request-Debug` header."""
    enabled = strtobool(request.headers.get('x-request-debug', 'false'))
    level = None
    try:
        if enabled:
            level = getLogger().getEffectiveLevel()
            getLogger().setLevel(DEBUG)
        yield
    finally:
        if enabled:
            getLogger().setLevel(level)

def audit(func):
    """Record a Flask route function in the audit log.

    Generates a JSON record in the Flask log for every request."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        options = AuditOptions(include_request_body=DEFAULT_INCLUDE_REQUEST_BODY, include_response_body=DEFAULT_INCLUDE_RESPONSE_BODY, include_path=True, include_query_string=True)
        with logging_levels():
            return _audit_request(options, func, None, *args, **kwargs)
    return wrapper

def parse_response(response):
    """Parse a Flask response into a body, a status code, and headers

    The returned value from a Flask view could be:
        * a tuple of (response, status) or (response, status, headers)
        * a Response object
        * a string"""
    if isinstance(response, tuple):
        if len(response) > 2:
            return (response[0], response[1], response[2])
        elif len(response) > 1:
            return (response[0], response[1], {})
    try:
        return (response.data, response.status_code, response.headers)
    except AttributeError:
        return (response, 200, {})

def configure_audit_decorator(graph):
    """Configure the audit decorator.

    Example Usage:

        @graph.audit
        def login(username, password):
            ..."""
    include_request_body = int(graph.config.audit.include_request_body)
    include_response_body = int(graph.config.audit.include_response_body)
    include_path = strtobool(graph.config.audit.include_path)
    include_query_string = strtobool(graph.config.audit.include_query_string)
    def _audit(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            options = AuditOptions(include_request_body=include_request_body, include_response_body=include_response_body, include_path=include_path, include_query_string=include_query_string)
            return _audit_request(options, func, graph.request_context, *args, **kwargs)
        return wrapper
    return _audit

def extract_status_code(error):
    """Extract an error code from a message."""
    try:
        return int(error.code)
    except (AttributeError, TypeError, ValueError):
        try:
            return int(error.status_code)
        except (AttributeError, TypeError, ValueError):
            try:
                return int(error.errno)
            except (AttributeError, TypeError, ValueError):
                return 500

def extract_error_message(error):
    """Extract a useful message from an error.

    Prefer the description attribute, then the message attribute, then
    the errors string conversion. In each case, fall back to the error class's
    name in the event that the attribute value was set to a uselessly empty string."""
    try:
        return error.description or error.__class__.__name__
    except AttributeError:
        try:
            return str(error.message) or error.__class__.__name__
        except AttributeError:
            return str(error) or error.__class__.__name__

def make_json_error(error):
    """Handle errors by logging and"""
    message = extract_error_message(error)
    status_code = extract_status_code(error)
    context = extract_context(error)
    retryable = extract_retryable(error)
    headers = extract_headers(error)
    error_logger.debug('Handling {} error: {}'.format(status_code, message))
    response_data = {'code': status_code, 'context': context, 'message': message, 'retryable': retryable}
    return dump_response_data(None, response_data, status_code, headers)

def configure_error_handlers(graph):
    """Register error handlers."""
    for code in default_exceptions.keys():
        graph.flask.register_error_handler(code, make_json_error)
    graph.flask.register_error_handler(Exception, make_json_error)

def ElemMatch(q, *conditions):
    """The ElemMatch operator matches documents that contain an array field with at
    least one element that matches all the specified query criteria."""
    new_condition = {}
    for condition in conditions:
        deep_merge(condition.to_dict(), new_condition)
    return Condition(q._path, new_condition, '$elemMatch')

def SortBy(*qs):
    """Convert a list of Q objects into list of sort instructions"""
    sort = []
    for q in qs:
        if q._path.endswith('.desc'):
            sort.append((q._path[:-5], DESCENDING))
        else:
            sort.append((q._path, ASCENDING))
    return sort

def deep_merge(source, dest):
    """Deep merges source dict into dest dict.

    This code was taken directly from the mongothon project:
    https://github.com/gamechanger/mongothon/tree/master/mongothon"""
    for key, value in source.items():
        if key in dest:
            if isinstance(value, dict) and isinstance(dest[key], dict):
                deep_merge(value, dest[key])
                continue
            elif isinstance(value, list) and isinstance(dest[key], list):
                for item in value:
                    if item not in dest[key]:
                        dest[key].append(item)
                continue
        dest[key] = value

def to_refs(value):
    """Convert all Frame instances within the given value to Ids"""
    from mongoframes.frames import Frame, SubFrame
    if isinstance(value, Frame):
        return value._id
    elif isinstance(value, SubFrame):
        return to_refs(value._document)
    elif isinstance(value, (list, tuple)):
        return [to_refs(v) for v in value]
    elif isinstance(value, dict):
        return {k: to_refs(v) for k, v in value.items()}
    return value

def list_models(args: argparse.Namespace):
    """Output the list of known models in the registry.

    :param args: :class:`argparse.Namespace` with "username", "password", "remote_repo" and                         "log_level"
    :return: None"""
    try:
        git_index = GitIndex(remote=args.index_repo, username=args.username, password=args.password, cache=args.cache, log_level=args.log_level)
    except ValueError:
        return 1
    for model_type, models in git_index.models.items():
        print(model_type)
        default = git_index.meta[model_type]['default']
        for uuid, model in sorted(models.items(), key=lambda m: parse_datetime(m[1]['created_at']), reverse=True):
            print('  %s %s' % ('*' if default == uuid else ' ', uuid), model['created_at'])

def register_backend(cls: Type[StorageBackend]):
    """Decorator to register another StorageBackend using it's `NAME`."""
    if not issubclass(cls, StorageBackend):
        raise TypeError('cls must be a subclass of StorageBackend')
    __registry__[cls.NAME] = cls
    return cls

def create_backend(name: str=None, git_index: GitIndex=None, args: str=None) -> StorageBackend:
    """Initialize a new StorageBackend by it's name and the specified model registry."""
    if name is None:
        name = config.BACKEND
    if not args:
        args = config.BACKEND_ARGS
    if args:
        try:
            kwargs = dict((p.split('=') for p in args.split(',')))
        except:
            raise ValueError('Invalid args') from None
    else:
        kwargs = {}
    if git_index is None:
        git_index = GitIndex()
    kwargs['index'] = git_index
    return __registry__[name](**kwargs)

def create_backend_noexc(log: logging.Logger, name: str=None, git_index: GitIndex=None, args: str=None) -> Optional[StorageBackend]:
    """Initialize a new Backend, return None if there was a known problem."""
    try:
        return create_backend(name, git_index, args)
    except KeyError:
        log.critical('No such backend: %s (looked in %s)', name, list(__registry__.keys()))
        return None
    except ValueError:
        log.critical('Invalid backend arguments: %s', args)
        return None

def disassemble_sparse_matrix(matrix: scipy.sparse.spmatrix) -> dict:
    """Transform a scipy.sparse matrix into the serializable collection of     :class:`numpy.ndarray`-s. :func:`assemble_sparse_matrix()` does the inverse.

    :param matrix: :mod:`scipy.sparse` matrix; csr, csc and coo formats are                    supported.
    :return: :class:`dict` with "shape", "format" and "data" - :class:`tuple`              of :class:`numpy.ndarray`."""
    fmt = matrix.getformat()
    if fmt not in ('csr', 'csc', 'coo'):
        raise ValueError('Unsupported scipy.sparse matrix format: %s.' % fmt)
    result = {'shape': matrix.shape, 'format': fmt}
    if isinstance(matrix, (scipy.sparse.csr_matrix, scipy.sparse.csc_matrix)):
        lengths = numpy.concatenate(([0], numpy.diff(matrix.indptr)))
        result['data'] = (matrix.data, squeeze_bits(matrix.indices), squeeze_bits(lengths))
    elif isinstance(matrix, scipy.sparse.coo_matrix):
        result['data'] = (matrix.data, (squeeze_bits(matrix.row), squeeze_bits(matrix.col)))
    return result

def squeeze_bits(arr: numpy.ndarray) -> numpy.ndarray:
    """Return a copy of an integer numpy array with the minimum bitness."""
    assert arr.dtype.kind in ('i', 'u')
    if arr.dtype.kind == 'i':
        assert arr.min() >= 0
    mlbl = int(arr.max()).bit_length()
    if mlbl <= 8:
        dtype = numpy.uint8
    elif mlbl <= 16:
        dtype = numpy.uint16
    elif mlbl <= 32:
        dtype = numpy.uint32
    else:
        dtype = numpy.uint64
    return arr.astype(dtype)

def refresh():
    """Scan over all the involved directories and load configs from them."""
    override_files = []
    for stack in traceback.extract_stack():
        f = os.path.join(os.path.dirname(stack[0]), OVERRIDE_FILE)
        if f not in override_files:
            override_files.insert(0, f)
    if OVERRIDE_FILE in override_files:
        del override_files[override_files.index(OVERRIDE_FILE)]
    override_files.append(OVERRIDE_FILE)
    def import_path(path):
        if sys.version_info < (3, 5, 0):
            from importlib.machinery import SourceFileLoader
            return SourceFileLoader(__name__, path).load_module()
        import importlib.util
        spec = importlib.util.spec_from_file_location(__name__, path)
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        return module
    for override_file in override_files:
        if not os.path.isfile(override_file):
            continue
        mod = import_path(override_file)
        globals().update({n: getattr(mod, n) for n in dir(mod) if not n.startswith('__')})

def download_http(source: str, file: Union[str, BinaryIO], log: logging.Logger, chunk_size: int=DEFAULT_DOWNLOAD_CHUNK_SIZE) -> None:
    """Download a file from an HTTP source.

    :param source: URL to fetch.
    :param file: Where to store the downloaded data.
    :param log: Logger.
    :param chunk_size: Size of download buffer."""
    log.info('Fetching %s...', source)
    r = requests.get(source, stream=True)
    if r.status_code != 200:
        log.error('An error occurred while fetching the model, with code %s' % r.status_code)
        raise ValueError
    if isinstance(file, str):
        os.makedirs(os.path.dirname(file), exist_ok=True)
        f = open(file, 'wb')
    else:
        f = file
    try:
        total_length = int(r.headers.get('content-length'))
        num_chunks = math.ceil(total_length / chunk_size)
        if num_chunks == 1:
            f.write(r.content)
        else:
            for chunk in progress_bar(r.iter_content(chunk_size=chunk_size), log, expected_size=num_chunks):
                if chunk:
                    f.write(chunk)
    finally:
        if isinstance(file, str):
            f.close()

def get_timezone() -> Tuple[datetime.tzinfo, str]:
    """Discover the current time zone and it's standard string representation (for source{d})."""
    dt = get_datetime_now().astimezone()
    tzstr = dt.strftime('%z')
    tzstr = tzstr[:-2] + ':' + tzstr[-2:]
    return (dt.tzinfo, tzstr)

def set_context(context):
    """Assign the logging context - an abstract object - to the current thread."""
    try:
        handler = logging.getLogger().handlers[0]
    except IndexError:
        return
    if not isinstance(handler, StructuredHandler):
        return
    handler.acquire()
    try:
        handler.local.context = context
    finally:
        handler.release()

def register_model(cls: Type[Model]):
    """Include the given model class into the registry.

    :param cls: The class of the registered model.
    :return: None"""
    if not issubclass(cls, Model):
        raise TypeError('model bust be a subclass of Model')
    if issubclass(cls, GenericModel):
        raise TypeError('model must not be a subclass of GenericModel')
    __models__.add(cls)
    return cls

def progress_bar(enumerable, logger, **kwargs):
    """Show the progress bar in the terminal, if the logging level matches and we are interactive.

    :param enumerable: The iterator of which we indicate the progress.
    :param logger: The bound logging.Logger.
    :param kwargs: Keyword arguments to pass to clint.textui.progress.bar.
    :return: The wrapped iterator."""
    if not logger.isEnabledFor(logging.INFO) or sys.stdin.closed or (not sys.stdin.isatty()):
        return enumerable
    return progress.bar(enumerable, **kwargs)

def collect_loaded_packages() -> List[Tuple[str, str]]:
    """Return the currently loaded package names and their versions."""
    dists = get_installed_distributions()
    get_dist_files = DistFilesFinder()
    file_table = {}
    for dist in dists:
        for file in get_dist_files(dist):
            file_table[file] = dist
    used_dists = set()
    for module in list(sys.modules.values()):
        try:
            dist = file_table[module.__file__]
        except (AttributeError, KeyError):
            continue
        used_dists.add(dist)
    return sorted(((dist.project_name, dist.version) for dist in used_dists))

def find_pattern_on_line(lines, n, max_wrap_lines):
    """Finds a forward/reply pattern within the given lines on text on the given
    line number and returns a tuple with the type ('reply' or 'forward') and
    line number of where the pattern ends. The returned line number may be
    different from the given line number in case the pattern wraps over
    multiple lines.

    Returns (None, None) if no pattern was found."""
    for typ, regexes in COMPILED_PATTERN_MAP.items():
        for regex in regexes:
            for m in range(max_wrap_lines):
                match_line = join_wrapped_lines(lines[n:n + 1 + m])
                if match_line.startswith('>'):
                    match_line = match_line[1:].strip()
                if regex.match(match_line.strip()):
                    return (n + m, typ)
    return (None, None)

def find_quote_position(lines, max_wrap_lines, limit=None):
    """Returns the (ending) line number of a quoting pattern. If a limit is given
    and the limit is reached, the limit is returned."""
    for n in range(len(lines)):
        end, typ = find_pattern_on_line(lines, n, max_wrap_lines)
        if typ:
            return end
        if limit != None and n >= limit - 1:
            return n
    return None

def join_wrapped_lines(lines):
    """Join one or multiple lines that wrapped. Returns the reconstructed line.
    Takes into account proper spacing between the lines (see
    STRIP_SPACE_CHARS)."""
    if len(lines) == 1:
        return lines[0]
    joined = lines[0]
    for line in lines[1:]:
        if joined and joined[-1] in STRIP_SPACE_CHARS:
            joined += line
        else:
            joined += ' '
            joined += line
    return joined

def extract_headers(lines, max_wrap_lines):
    """Extracts email headers from the given lines. Returns a dict with the
    detected headers and the amount of lines that were processed."""
    hdrs = {}
    header_name = None
    extend_lines = 0
    lines_processed = 0
    for n, line in enumerate(lines):
        if not line.strip():
            header_name = None
            continue
        match = HEADER_RE.match(line)
        if match:
            header_name, header_value = match.groups()
            header_name = header_name.strip().lower()
            extend_lines = 0
            if header_name in HEADER_MAP:
                hdrs[HEADER_MAP[header_name]] = header_value.strip()
            lines_processed = n + 1
        else:
            extend_lines += 1
            if extend_lines < max_wrap_lines and header_name in HEADER_MAP:
                hdrs[HEADER_MAP[header_name]] = join_wrapped_lines([hdrs[HEADER_MAP[header_name]], line.strip()])
                lines_processed = n + 1
            else:
                break
    return (hdrs, lines_processed)

def parse_reply(line):
    """Parses the given reply line ("On DATE, USER wrote:") and returns a
    dictionary with the "Date" and "From" keys, or None, if couldn't parse."""
    if line.startswith('>'):
        line = line[1:].strip()
    date = user = None
    for pattern in COMPILED_PATTERN_MAP['reply']:
        match = pattern.match(line)
        if match:
            groups = match.groups()
            if len(groups) == 2:
                date, user = groups
            else:
                split_match = REPLY_DATE_SPLIT_REGEX.match(groups[0])
                if split_match:
                    split_groups = split_match.groups()
                    date = split_groups[0]
                    user = split_groups[-1]
                else:
                    split = groups[0].rsplit(',', 1)
                    if len(split) == 2:
                        date, user = split
    if date:
        date = date.strip()
    if user:
        user = user.strip()
    if date and user:
        return {'date': date.strip(), 'from': user.strip()}

def trim_tree_after(element, include_element=True):
    """Removes the document tree following the given element. If include_element
    is True, the given element is kept in the tree, otherwise it is removed."""
    el = element
    for parent_el in element.iterancestors():
        el.tail = None
        if el != element or include_element:
            el = el.getnext()
        while el is not None:
            remove_el = el
            el = el.getnext()
            parent_el.remove(remove_el)
        el = parent_el

def trim_tree_before(element, include_element=True, keep_head=True):
    """Removes the document tree preceding the given element. If include_element
    is True, the given element is kept in the tree, otherwise it is removed."""
    el = element
    for parent_el in element.iterancestors():
        parent_el.text = None
        if el != element or include_element:
            el = el.getprevious()
        else:
            parent_el.text = el.tail
        while el is not None:
            remove_el = el
            el = el.getprevious()
            tag = remove_el.tag
            is_head = isinstance(tag, string_class) and tag.lower() == 'head'
            if not keep_head or not is_head:
                parent_el.remove(remove_el)
        el = parent_el

def trim_slice(lines, slice_tuple):
    """Trim a slice tuple (begin, end) so it starts at the first non-empty line
    (obtained via indented_tree_line_generator / get_line_info) and ends at the
    last non-empty line within the slice. Returns the new slice."""
    def _empty(line):
        return not line or line.strip() == '>'
    if not slice_tuple:
        return None
    slice_start, slice_end = slice_tuple
    if slice_start is None:
        slice_start = 0
    if slice_end is None:
        slice_end = len(lines)
    while slice_start < slice_end and _empty(lines[slice_start]):
        slice_start += 1
    while slice_end > slice_start and _empty(lines[slice_end - 1]):
        slice_end -= 1
    return (slice_start, slice_end)

def unindent_tree(element):
    '''Removes the outermost indent. For example, the tree
    "<div>A<blockqote>B<div>C<blockquote>D</blockquote>E</div>F</blockquote>G</div>"
    is transformed to
    "<div>A<div>B<div>C<blockquote>D</blockquote>E</div>F</div>G</div>"'''
    for el in element.iter():
        if is_indentation_element(el):
            el.attrib.clear()
            el.tag = 'div'
            return

def get_html_tree(html):
    """Given the HTML string, returns a LXML tree object. The tree is wrapped in
    <div> elements if it doesn't have a top level tag or parsing would
    otherwise result in an error. The wrapping can be later removed with
    strip_wrapping()."""
    parser = lxml.html.HTMLParser(encoding='utf-8')
    html = html.encode('utf8')
    try:
        tree = lxml.html.fromstring(html, parser=parser)
    except lxml.etree.Error:
        tree = lxml.html.fromstring('<div></div>')
    if tree.tag not in lxml.html.defs.top_level_tags:
        html = b'<div>%s</div>' % html
        tree = lxml.html.fromstring(html, parser=parser)
    for el in tree.iter():
        if el.nsmap or (isinstance(el.tag, string_class) and ':' in el.tag):
            if el.nsmap:
                actual_tag_name = '{}:{}'.format(list(el.nsmap.keys())[0], el.tag)
            else:
                actual_tag_name = el.tag
            el.tag = 'span'
            el.attrib['__tag_name'] = actual_tag_name
    return tree

def strip_wrapping(html):
    """Removes the wrapping that might have resulted when using get_html_tree()."""
    if html.startswith('<div>') and html.endswith('</div>'):
        html = html[5:-6]
    return html.strip()

def render_html_tree(tree):
    """Renders the given HTML tree, and strips any wrapping that was applied in
    get_html_tree().

    You should avoid further processing of the given tree after calling this
    method because we modify namespaced tags here."""
    for el in tree.iter():
        if '__tag_name' in el.attrib:
            actual_tag_name = el.attrib.pop('__tag_name')
            el.tag = actual_tag_name
    html = lxml.html.tostring(tree, encoding='utf8').decode('utf8')
    return strip_wrapping(html)

def get_line_info(tree, max_lines=None):
    """Shortcut for indented_tree_line_generator() that returns an array of
    start references, an array of corresponding end references (see
    tree_line_generator() docs), and an array of corresponding lines."""
    line_gen = indented_tree_line_generator(tree, max_lines=max_lines)
    line_gen_result = list(zip(*line_gen))
    if line_gen_result:
        return line_gen_result
    else:
        return ([], [], [])

