def transaction(commit=True):
    """Wrap a context with a commit/rollback."""
    try:
        yield SessionContext.session
        if commit:
            SessionContext.session.commit()
    except Exception:
        if SessionContext.session:
            SessionContext.session.rollback()
        raise

def transactional(func):
    """Decorate a function call with a commit/rollback and pass the session as the first arg."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        with transaction():
            return func(*args, **kwargs)
    return wrapper

def maybe_transactional(func):
    """Variant of `transactional` that will not commit if there's an argument `commit` with a falsey value.

    Useful for dry-run style operations."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        commit = kwargs.get('commit', True)
        with transaction(commit=commit):
            return func(*args, **kwargs)
    return wrapper

def get_migrations_dir(graph):
    """Resolve the migrations directory path.

    Either take the directory from a component of the object graph or by
    using the metaata's path resolution facilities."""
    try:
        migrations_dir = graph.migrations_dir
    except (LockedGraphError, NotBoundError):
        migrations_dir = graph.metadata.get_path('migrations')
    if not isdir(migrations_dir):
        raise Exception('Migrations dir must exist: {}'.format(migrations_dir))
    return migrations_dir

def configure_sessionmaker(graph):
    """Create the SQLAlchemy session class."""
    engine_routing_strategy = getattr(graph, graph.config.sessionmaker.engine_routing_strategy)
    if engine_routing_strategy.supports_multiple_binds:
        ScopedFactory.infect(graph, 'postgres')
    class RoutingSession(Session):
        """Route session bind to an appropriate engine.

        See: http://docs.sqlalchemy.org/en/latest/orm/persistence_techniques.html#partitioning-strategies"""
        def get_bind(self, mapper=None, clause=None):
            return engine_routing_strategy.get_bind(mapper, clause)
    return sessionmaker(class_=RoutingSession)

def clone(instance, substitutions, ignore=()):
    """Clone an instance of `Model` that uses `IdentityMixin`.

    :param instance: the instance to clonse
    :param substitutions: a dictionary of substitutions
    :param ignore: a tuple of column names to ignore"""
    substitutions[instance.id] = new_object_id()
    def substitute(value):
        try:
            hash(value)
        except Exception:
            return value
        else:
            return substitutions.get(value, value)
    return instance.__class__(**{key: substitute(value) for key, value in iter_items(instance, ignore)}).create()

def configure_encryptor(graph):
    """Create a MultiTenantEncryptor from configured keys."""
    encryptor = graph.multi_tenant_key_registry.make_encryptor(graph)
    for encryptable in EncryptableMixin.__subclasses__():
        encryptable.register(encryptor)
    return encryptor

def should_copy(column):
    """Determine if a column should be copied."""
    if not isinstance(column.type, Serial):
        return True
    if column.nullable:
        return True
    if not column.server_default:
        return True
    return False

def copy_table(from_table, name):
    """Copy a table.

    Based on `Table.tometadata`, but simplified to remove constraints and indexes."""
    metadata = from_table.metadata
    if name in metadata.tables:
        return metadata.tables[name]
    schema = metadata.schema
    columns = [copy_column(column, schema) for column in from_table.columns if should_copy(column)]
    return Table(name, metadata, *columns, schema=schema, comment=from_table.comment, **from_table.kwargs)

def on_load(target: 'EncryptableMixin', context):
    """Intercept SQLAlchemy's instance load event."""
    decrypt, plaintext = decrypt_instance(target)
    if decrypt:
        target.plaintext = plaintext

def choose_database_name(metadata, config):
    """Choose the database name to use.

    As a default, databases should be named after the service that uses them. In addition,
    database names should be different between unit testing and runtime so that there is
    no chance of a unit test dropping a real database by accident."""
    if config.database_name is not None:
        return config.database_name
    if metadata.testing:
        return f'{metadata.name}_test_db'
    return f'{metadata.name}_db'

def choose_username(metadata, config):
    """Choose the database username to use.

    Because databases should not be shared between services, database usernames should be
    the same as the service that uses them."""
    if config.username is not None:
        return config.username
    if config.read_only:
        return f'{metadata.name}_ro'
    return metadata.name

def choose_connect_args(metadata, config):
    """Choose the SSL mode and optional root cert for the connection."""
    if not config.require_ssl and (not config.verify_ssl):
        return dict(sslmode='prefer')
    if config.require_ssl and (not config.verify_ssl):
        return dict(sslmode='require')
    if not config.ssl_cert_path:
        raise Exception('SSL certificate path (`ssl_cert_path`) must be configured for verification')
    return dict(sslmode='verify-full', sslrootcert=config.ssl_cert_path)

def choose_args(metadata, config):
    """Choose database connection arguments."""
    return dict(connect_args=choose_connect_args(metadata, config), echo=config.echo, max_overflow=config.max_overflow, pool_size=config.pool_size, pool_timeout=config.pool_timeout)

def insert_many(self, items):
    """Insert many items at once into a temporary table."""
    return SessionContext.session.execute(self.insert(values=[to_dict(item, self.c) for item in items])).rowcount

def upsert_into(self, table):
    """Upsert from a temporarty table into another table."""
    return SessionContext.session.execute(insert(table).from_select(self.c, self).on_conflict_do_nothing()).rowcount

