def get_boto_ses_connection():
    """Shortcut for instantiating and returning a boto SESConnection object.

    :rtype: boto.ses.SESConnection
    :returns: A boto SESConnection object, from which email sending is done."""
    access_key_id = getattr(settings, 'CUCUMBER_SES_ACCESS_KEY_ID', getattr(settings, 'AWS_ACCESS_KEY_ID', None))
    access_key = getattr(settings, 'CUCUMBER_SES_SECRET_ACCESS_KEY', getattr(settings, 'AWS_SECRET_ACCESS_KEY', None))
    region_name = getattr(settings, 'CUCUMBER_SES_REGION_NAME', getattr(settings, 'AWS_SES_REGION_NAME', None))
    if region_name != None:
        return boto.ses.connect_to_region(region_name, aws_access_key_id=access_key_id, aws_secret_access_key=access_key)
    else:
        return boto.connect_ses(aws_access_key_id=access_key_id, aws_secret_access_key=access_key)

def dkim_sign(message):
    """:returns: A signed email message if dkim package and settings are available."""
    if not HAS_DKIM:
        return message
    if not (DKIM_DOMAIN and DKIM_PRIVATE_KEY):
        return message
    sig = dkim.sign(message, DKIM_SELECTOR, DKIM_DOMAIN, DKIM_PRIVATE_KEY, include_headers=DKIM_HEADERS)
    return sig + message

def class_factory(name, base_class, class_dict):
    """Internal method for dynamically building Custom Indicator classes."""
    def __init__(self, tcex):
        base_class.__init__(self, tcex)
        for k, v in class_dict.items():
            setattr(self, k, v)
    newclass = type(str(name), (base_class,), {'__init__': __init__})
    return newclass

def print_header(vcf_obj, include, exclude, samples=None):
    """Print the header of a vcf obj

    Parameters
    ----------
    vcf_obj: cyvcf2.VCF
    include: tuple
        set of strings with info fields that should be included
    exclude: tuple
        set of strings with info fields that should be excluded
    samples: list
            list of samples to extract."""
    if not samples is None:
        vcf_obj.set_samples(samples)
    for header_line in vcf_obj.raw_header.split('\n'):
        if len(header_line) == 0:
            continue
        print_line = True
        if 'INFO' not in header_line:
            pass
        elif include:
            print_line = any(('ID=' + inc + ',' for inc in include))
        elif exclude:
            print_line = not any(('ID=' + exc + ',' for exc in exclude))
        if print_line:
            click.echo(header_line)

def print_variant(variant, include, exclude):
    """Print a vcf variant

    Parameters
    ----------
    variant: cyvcf2.Variant
    include: tuple
        set of strings with info fields that should be included
    include: tuple
        set of strings with info fields that should be included"""
    if include:
        for info in variant.INFO:
            key = info[0]
            if not key in include:
                del variant.INFO[key]
    if exclude:
        for exc in exclude:
            if variant.INFO.get(exc):
                del variant.INFO[exc]
    print_string = str(variant).rstrip()
    click.echo(print_string)

def get_version():
    """Get the version info from the mpld3 package without importing it"""
    import ast
    with open(os.path.join('cyvcf2', '__init__.py'), 'r') as init_file:
        module = ast.parse(init_file.read())
    version = (ast.literal_eval(node.value) for node in ast.walk(module) if isinstance(node, ast.Assign) and node.targets[0].id == '__version__')
    try:
        return next(version)
    except StopIteration:
        raise ValueError('version could not be located')

def dense_output(t_current, t_old, h_current, rcont):
    """Dense output function, basically extrapolatin"""
    s = (t_current - t_old) / h_current
    s1 = 1.0 - s
    return rcont[0] + s * (rcont[1] + s1 * (rcont[2] + s * (rcont[3] + s1 * (rcont[4] + s * (rcont[5] + s1 * (rcont[6] + s * rcont[7]))))))

def _parse_integrator(int_method):
    """parse the integrator method to pass to C"""
    if int_method.lower() == 'rk4_c':
        int_method_c = 1
    elif int_method.lower() == 'rk6_c':
        int_method_c = 2
    elif int_method.lower() == 'symplec4_c':
        int_method_c = 3
    elif int_method.lower() == 'symplec6_c':
        int_method_c = 4
    elif int_method.lower() == 'dopr54_c':
        int_method_c = 5
    elif int_method.lower() == 'dop853_c':
        int_method_c = 6
    else:
        int_method_c = 0
    return int_method_c

def _parse_tol(rtol, atol):
    """Parse the tolerance keywords"""
    if rtol is None:
        rtol = -12.0 * nu.log(10.0)
    else:
        rtol = nu.log(rtol)
    if atol is None:
        atol = -12.0 * nu.log(10.0)
    else:
        atol = nu.log(atol)
    return (rtol, atol)

def _check_integrate_dt(t, dt):
    """Check that the stepszie in t is an integer x dt"""
    if dt is None:
        return True
    mult = round((t[1] - t[0]) / dt)
    if nu.fabs(mult * dt - t[1] + t[0]) < 10.0 ** (-10.0):
        return True
    else:
        return False

def _potInt(x, y, z, psi, b2, c2, glx=None, glw=None):
    """int_0^\\infty [psi(m)-psi(\\infy)]/sqrt([1+tau]x[b^2+tau]x[c^2+tau])dtau"""
    def integrand(s):
        t = 1 / s ** 2.0 - 1.0
        return psi(numpy.sqrt(x ** 2.0 / (1.0 + t) + y ** 2.0 / (b2 + t) + z ** 2.0 / (c2 + t))) / numpy.sqrt((1.0 + (b2 - 1.0) * s ** 2.0) * (1.0 + (c2 - 1.0) * s ** 2.0))
    if glx is None:
        return integrate.quad(integrand, 0.0, 1.0)[0]
    else:
        return numpy.sum(glw * integrand(glx))

def _forceInt(x, y, z, dens, b2, c2, i, glx=None, glw=None):
    """Integral that gives the force in x,y,z"""
    def integrand(s):
        t = 1 / s ** 2.0 - 1.0
        return dens(numpy.sqrt(x ** 2.0 / (1.0 + t) + y ** 2.0 / (b2 + t) + z ** 2.0 / (c2 + t))) * (x / (1.0 + t) * (i == 0) + y / (b2 + t) * (i == 1) + z / (c2 + t) * (i == 2)) / numpy.sqrt((1.0 + (b2 - 1.0) * s ** 2.0) * (1.0 + (c2 - 1.0) * s ** 2.0))
    if glx is None:
        return integrate.quad(integrand, 0.0, 1.0)[0]
    else:
        return numpy.sum(glw * integrand(glx))

def _2ndDerivInt(x, y, z, dens, densDeriv, b2, c2, i, j, glx=None, glw=None):
    """Integral that gives the 2nd derivative of the potential in x,y,z"""
    def integrand(s):
        t = 1 / s ** 2.0 - 1.0
        m = numpy.sqrt(x ** 2.0 / (1.0 + t) + y ** 2.0 / (b2 + t) + z ** 2.0 / (c2 + t))
        return (densDeriv(m) * (x / (1.0 + t) * (i == 0) + y / (b2 + t) * (i == 1) + z / (c2 + t) * (i == 2)) * (x / (1.0 + t) * (j == 0) + y / (b2 + t) * (j == 1) + z / (c2 + t) * (j == 2)) / m + dens(m) * (i == j) * (1.0 / (1.0 + t) * (i == 0) + 1.0 / (b2 + t) * (i == 1) + 1.0 / (c2 + t) * (i == 2))) / numpy.sqrt((1.0 + (b2 - 1.0) * s ** 2.0) * (1.0 + (c2 - 1.0) * s ** 2.0))
    if glx is None:
        return integrate.quad(integrand, 0.0, 1.0)[0]
    else:
        return numpy.sum(glw * integrand(glx))

def logsumexp(arr, axis=0):
    """Faster logsumexp?"""
    minarr = numpy.amax(arr, axis=axis)
    if axis == 1:
        minarr = numpy.reshape(minarr, (arr.shape[0], 1))
    if axis == 0:
        minminarr = numpy.tile(minarr, (arr.shape[0], 1))
    elif axis == 1:
        minminarr = numpy.tile(minarr, (1, arr.shape[1]))
    elif axis == None:
        minminarr = numpy.tile(minarr, arr.shape)
    else:
        raise NotImplementedError("'galpy.util.logsumexp' not implemented for axis > 2")
    if axis == 1:
        minarr = numpy.reshape(minarr, arr.shape[0])
    return minarr + numpy.log(numpy.sum(numpy.exp(arr - minminarr), axis=axis))

def fast_cholesky_invert(A, logdet=False, tiny=_TINY):
    """NAME:
       fast_cholesky_invert
    PURPOSE:
       invert a positive definite matrix by using its Cholesky decomposition
    INPUT:
       A - matrix to be inverted
       logdet - (Bool) if True, return the logarithm of the determinant as well
       tiny - (double) tiny number to add to the covariance matrix to make the decomposition stable (has a default)
    OUTPUT:
       A^{-1}
    REVISION HISTORY:
       2009-10-07 - Written - Bovy (NYU)"""
    L = stable_cho_factor(A, tiny=tiny)
    if logdet:
        return (linalg.cho_solve(L, numpy.eye(A.shape[0])), 2.0 * numpy.sum(numpy.log(numpy.diag(L[0]))))
    else:
        return linalg.cho_solve(L, numpy.eye(A.shape[0]))

def _direct_nbody_force(q, m, t, pot, softening, softening_args):
    """Calculate the force"""
    nq = len(q)
    dim = len(q[0])
    dist_vec = nu.zeros((nq, nq, dim))
    dist = nu.zeros((nq, nq))
    for ii in range(nq):
        for jj in range(ii + 1, nq):
            dist_vec[ii, jj, :] = q[jj] - q[ii]
            dist_vec[jj, ii, :] = -dist_vec[ii, jj, :]
            dist[ii, jj] = linalg.norm(dist_vec[ii, jj, :])
            dist[jj, ii] = dist[ii, jj]
    force = []
    for ii in range(nq):
        thisforce = nu.zeros(dim)
        for jj in range(nq):
            if ii == jj:
                continue
            thisforce += m[jj] * softening(dist[ii, jj], *softening_args) / dist[ii, jj] * dist_vec[ii, jj, :]
        force.append(thisforce)
    if pot is None:
        return force
    for ii in range(nq):
        force[ii] += _external_force(q[ii], t, pot)
    return force

def _h_ars(x, params):
    """ln p(Omega) for ARS"""
    mO, sO2 = params
    return -0.5 * (x - mO) ** 2.0 / sO2 + numpy.log(x)

def check_inputs_not_arrays(func):
    """Decorator to check inputs and throw TypeError if any of the inputs are arrays.
    Methods potentially return with silent errors if inputs are not checked."""
    @wraps(func)
    def func_wrapper(self, R, z, phi, t):
        if hasattr(R, '__len__') and len(R) > 1 or (hasattr(z, '__len__') and len(z) > 1) or (hasattr(phi, '__len__') and len(phi) > 1) or (hasattr(t, '__len__') and len(t) > 1):
            raise TypeError('Methods in SpiralArmsPotential do not accept array inputs. Please input scalars.')
        return func(self, R, z, phi, t)
    return func_wrapper

def _uminUmaxFindStart(u, E, Lz, I3U, delta, u0, sinh2u0, v0, sin2v0, potu0v0, pot, umax=False):
    """NAME:
       _uminUmaxFindStart
    PURPOSE:
       Find adequate start or end points to solve for umin and umax
    INPUT:
       same as JRStaeckelIntegrandSquared
    OUTPUT:
       rstart or rend
    HISTORY:
       2012-11-30 - Written - Bovy (IAS)"""
    if umax:
        utry = u * 1.1
    else:
        utry = u * 0.9
    prevu = u
    while _JRStaeckelIntegrandSquared(utry, E, Lz, I3U, delta, u0, sinh2u0, v0, sin2v0, potu0v0, pot) >= 0.0 and utry > 1e-09:
        prevu = utry
        if umax:
            if utry > 100.0:
                raise UnboundError('Orbit seems to be unbound')
            utry *= 1.1
        else:
            utry *= 0.9
    if utry < 1e-09:
        return (0.0, prevu)
    return (utry, prevu)

