def _JRAxiIntegrand(r, E, L, pot):
    """The J_R integrand"""
    return nu.sqrt(2.0 * (E - potentialAxi(r, pot)) - L ** 2.0 / r ** 2.0)

def _rapRperiAxiEq(R, E, L, pot):
    """The vr=0 equation that needs to be solved to find apo- and pericenter"""
    return E - potentialAxi(R, pot) - L ** 2.0 / 2.0 / R ** 2.0

def RZToplanarPotential(RZPot):
    """NAME:

       RZToplanarPotential

    PURPOSE:

       convert an RZPotential to a planarPotential in the mid-plane (z=0)

    INPUT:

       RZPot - RZPotential instance or list of such instances (existing planarPotential instances are just copied to the output)

    OUTPUT:

       planarPotential instance(s)

    HISTORY:

       2010-07-13 - Written - Bovy (NYU)"""
    RZPot = flatten(RZPot)
    if isinstance(RZPot, list):
        out = []
        for pot in RZPot:
            if isinstance(pot, planarPotential) and (not pot.isNonAxi):
                out.append(pot)
            elif isinstance(pot, Potential) and (not pot.isNonAxi):
                out.append(planarPotentialFromRZPotential(pot))
            else:
                raise PotentialError("Input to 'RZToplanarPotential' is neither an RZPotential-instance or a list of such instances")
        return out
    elif isinstance(RZPot, Potential) and (not RZPot.isNonAxi):
        return planarPotentialFromRZPotential(RZPot)
    elif isinstance(RZPot, planarPotential) and (not RZPot.isNonAxi):
        return RZPot
    else:
        raise PotentialError("Input to 'RZToplanarPotential' is neither an RZPotential-instance or a list of such instances")

def _evaluateplanarRforces(Pot, R, phi=None, t=0.0):
    """Raw, undecorated function for internal use"""
    from .Potential import _isNonAxi
    isList = isinstance(Pot, list)
    nonAxi = _isNonAxi(Pot)
    if nonAxi and phi is None:
        raise PotentialError('The (list of) planarPotential instances is non-axisymmetric, but you did not provide phi')
    if isinstance(Pot, list) and nu.all([isinstance(p, planarPotential) for p in Pot]):
        sum = 0.0
        for pot in Pot:
            if nonAxi:
                sum += pot._Rforce_nodecorator(R, phi=phi, t=t)
            else:
                sum += pot._Rforce_nodecorator(R, t=t)
        return sum
    elif isinstance(Pot, planarPotential):
        if nonAxi:
            return Pot._Rforce_nodecorator(R, phi=phi, t=t)
        else:
            return Pot._Rforce_nodecorator(R, t=t)
    else:
        raise PotentialError("Input to 'evaluatePotentials' is neither a Potential-instance or a list of such instances")

def _evaluatePotentials(Pot, R, z, phi=None, t=0.0, dR=0, dphi=0):
    """Raw, undecorated function for internal use"""
    nonAxi = _isNonAxi(Pot)
    if nonAxi and phi is None:
        raise PotentialError('The (list of) Potential instances is non-axisymmetric, but you did not provide phi')
    isList = isinstance(Pot, list)
    if isList:
        sum = 0.0
        for pot in Pot:
            if not isinstance(pot, DissipativeForce):
                sum += pot._call_nodecorator(R, z, phi=phi, t=t, dR=dR, dphi=dphi)
        return sum
    elif isinstance(Pot, Potential):
        return Pot._call_nodecorator(R, z, phi=phi, t=t, dR=dR, dphi=dphi)
    else:
        raise PotentialError("Input to 'evaluatePotentials' is neither a Potential-instance or a list of such instances")

def _evaluatephiforces(Pot, R, z, phi=None, t=0.0, v=None):
    """Raw, undecorated function for internal use"""
    isList = isinstance(Pot, list)
    nonAxi = _isNonAxi(Pot)
    if nonAxi and phi is None:
        raise PotentialError('The (list of) Potential instances is non-axisymmetric, but you did not provide phi')
    dissipative = _isDissipative(Pot)
    if dissipative and v is None:
        raise PotentialError('The (list of) Potential instances includes dissipative, but you did not provide the 3D velocity (required for dissipative forces')
    if isList:
        sum = 0.0
        for pot in Pot:
            if isinstance(pot, DissipativeForce):
                sum += pot._phiforce_nodecorator(R, z, phi=phi, t=t, v=v)
            else:
                sum += pot._phiforce_nodecorator(R, z, phi=phi, t=t)
        return sum
    elif isinstance(Pot, Potential):
        return Pot._phiforce_nodecorator(R, z, phi=phi, t=t)
    elif isinstance(Pot, DissipativeForce):
        return Pot._phiforce_nodecorator(R, z, phi=phi, t=t, v=v)
    else:
        raise PotentialError("Input to 'evaluatephiforces' is neither a Potential-instance, DissipativeForce-instance or a list of such instances")

def epifreq(Pot, R):
    """NAME:

        epifreq

    PURPOSE:

        calculate the epicycle frequency at R in the potential Pot

    INPUT:

        Pot - Potential instance or list thereof

        R - Galactocentric radius (can be Quantity)

    OUTPUT:

        epicycle frequency

    HISTORY:

        2012-07-25 - Written - Bovy (IAS)"""
    from .planarPotential import planarPotential
    if isinstance(Pot, (Potential, planarPotential)):
        return Pot.epifreq(R, use_physical=False)
    from galpy.potential import evaluateplanarRforces, evaluateplanarR2derivs
    from galpy.potential import PotentialError
    try:
        return nu.sqrt(evaluateplanarR2derivs(Pot, R, use_physical=False) - 3.0 / R * evaluateplanarRforces(Pot, R, use_physical=False))
    except PotentialError:
        from galpy.potential import RZToplanarPotential
        Pot = RZToplanarPotential(Pot)
        return nu.sqrt(evaluateplanarR2derivs(Pot, R, use_physical=False) - 3.0 / R * evaluateplanarRforces(Pot, R, use_physical=False))

def rl(Pot, lz):
    """NAME:

       rl

    PURPOSE:

       calculate the radius of a circular orbit of Lz

    INPUT:

       Pot - Potential instance or list thereof

       lz - Angular momentum (can be Quantity)

    OUTPUT:

       radius

    HISTORY:

       2012-07-30 - Written - Bovy (IAS@MPIA)

    NOTE:

       seems to take about ~0.5 ms for a Miyamoto-Nagai potential;
       ~0.75 ms for a MWPotential"""
    Pot = flatten(Pot)
    if _APY_LOADED and isinstance(lz, units.Quantity):
        if hasattr(Pot, '_ro'):
            lz = lz.to(units.km / units.s * units.kpc).value / Pot._vo / Pot._ro
        elif hasattr(Pot[0], '_ro'):
            lz = lz.to(units.km / units.s * units.kpc).value / Pot[0]._vo / Pot[0]._ro
    rstart = _rlFindStart(math.fabs(lz), math.fabs(lz), Pot)
    try:
        return optimize.brentq(_rlfunc, 10.0 ** (-5.0), rstart, args=(math.fabs(lz), Pot), maxiter=200, disp=False)
    except ValueError:
        rlower = _rlFindStart(10.0 ** (-5.0), math.fabs(lz), Pot, lower=True)
        return optimize.brentq(_rlfunc, rlower, rstart, args=(math.fabs(lz), Pot))

def _rlFindStart(rl, lz, pot, lower=False):
    """find a starting interval for rl"""
    rtry = 2.0 * rl
    while (2.0 * lower - 1.0) * _rlfunc(rtry, lz, pot) > 0.0:
        if lower:
            rtry /= 2.0
        else:
            rtry *= 2.0
    return rtry

def nemo_accname(Pot):
    """NAME:

       nemo_accname

    PURPOSE:

