def _vmomentsurfaceIntegrand(vz, vR, vT, R, z, df, sigmaR1, gamma, sigmaz1, n, m, o):
    """Internal function that is the integrand for the vmomentsurface mass integration"""
    return vR ** n * vT ** m * vz ** o * df(R, vR * sigmaR1, vT * sigmaR1 * gamma, z, vz * sigmaz1, use_physical=False)

def _vmomentsurfaceMCIntegrand(vz, vR, vT, R, z, df, sigmaR1, gamma, sigmaz1, mvT, n, m, o):
    """Internal function that is the integrand for the vmomentsurface mass integration"""
    return vR ** n * vT ** m * vz ** o * df(R, vR * sigmaR1, vT * sigmaR1 * gamma, z, vz * sigmaz1, use_physical=False) * numpy.exp(vR ** 2.0 / 2.0 + (vT - mvT) ** 2.0 / 2.0 + vz ** 2.0 / 2.0)

def _jmomentsurfaceIntegrand(vz, vR, vT, R, z, df, sigmaR1, gamma, sigmaz1, n, m, o):
    """Internal function that is the integrand for the vmomentsurface mass integration"""
    return df(R, vR * sigmaR1, vT * sigmaR1 * gamma, z, vz * sigmaz1, use_physical=False, func=lambda x, y, z: x ** n * y ** m * z ** o)

def _jmomentsurfaceMCIntegrand(vz, vR, vT, R, z, df, sigmaR1, gamma, sigmaz1, mvT, n, m, o):
    """Internal function that is the integrand for the vmomentsurface mass integration"""
    return df(R, vR * sigmaR1, vT * sigmaR1 * gamma, z, vz * sigmaz1, use_physical=False, func=lambda x, y, z: x ** n * y ** m * z ** o) * numpy.exp(vR ** 2.0 / 2.0 + (vT - mvT) ** 2.0 / 2.0 + vz ** 2.0 / 2.0)

def impact_check_range(func):
    """Decorator to check the range of interpolated kicks"""
    @wraps(func)
    def impact_wrapper(*args, **kwargs):
        if isinstance(args[1], numpy.ndarray):
            out = numpy.zeros(len(args[1]))
            goodIndx = (args[1] < args[0]._deltaAngleTrackImpact) * (args[1] > 0.0)
            out[goodIndx] = func(args[0], args[1][goodIndx])
            return out
        elif args[1] >= args[0]._deltaAngleTrackImpact or args[1] <= 0.0:
            return 0.0
        else:
            return func(*args, **kwargs)
    return impact_wrapper

def HernquistX(s):
    """Computes X function from equations (33) & (34) of Hernquist (1990)"""
    if s < 0.0:
        raise ValueError('s must be positive in Hernquist X function')
    elif s < 1.0:
        return numpy.log((1 + numpy.sqrt(1 - s * s)) / s) / numpy.sqrt(1 - s * s)
    elif s == 1.0:
        return 1.0
    else:
        return numpy.arccos(1.0 / s) / numpy.sqrt(s * s - 1)

def run_tasks(procs, err_q, out_q, num):
    """A function that executes populated processes and processes
    the resultant array. Checks error queue for any exceptions.

    :param procs: list of Process objects
    :param out_q: thread-safe output queue
    :param err_q: thread-safe queue to populate on exception
    :param num : length of resultant array"""
    die = lambda vals: [val.terminate() for val in vals if val.exitcode is None]
    try:
        for proc in procs:
            proc.start()
        for proc in procs:
            proc.join()
    except Exception as e:
        try:
            die(procs)
        finally:
            raise e
    if not err_q.empty():
        try:
            die(procs)
        finally:
            raise err_q.get()
    results = [None] * num
    while not out_q.empty():
        idx, result = out_q.get()
        results[idx] = result
    return list(numpy.concatenate(results))

def parallel_map(function, sequence, numcores=None):
    """A parallelized version of the native Python map function that
    utilizes the Python multiprocessing module to divide and
    conquer sequence.

    parallel_map does not yet support multiple argument sequences.

    :param function: callable function that accepts argument from iterable
    :param sequence: iterable sequence
    :param numcores: number of cores to use"""
    if not callable(function):
        raise TypeError("input function '%s' is not callable" % repr(function))
    if not numpy.iterable(sequence):
        raise TypeError("input '%s' is not iterable" % repr(sequence))
    size = len(sequence)
    if not _multi or size == 1:
        return map(function, sequence)
    if numcores is None:
        numcores = _ncpus
    if platform.system() == 'Windows':
        return list(map(function, sequence))
    manager = multiprocessing.Manager()
    out_q = manager.Queue()
    err_q = manager.Queue()
    lock = manager.Lock()
    if size < numcores:
        numcores = size
    sequence = numpy.array_split(sequence, numcores)
    procs = [multiprocessing.Process(target=worker, args=(function, ii, chunk, out_q, err_q, lock)) for ii, chunk in enumerate(sequence)]
    return run_tasks(procs, err_q, out_q, numcores)

def evaluate_hull(x, hull):
    """evaluate_hull: evaluate h_u(x) and (optional) h_l(x)

    Input:
       x     - abcissa
       hull  - the hull (see setup_hull for a definition)

    Output:
      hu(x) (optional), hl(x)

    History:
       2009-05-21 - Written - Bovy (NYU)"""
    if x < hull[4][0]:
        hux = hull[3][0] * (x - hull[1][0]) + hull[2][0]
        indx = 0
    else:
        if len(hull[5]) == 1:
            indx = 1
        else:
            indx = 1
            while indx < len(hull[4]) and hull[4][indx] < x:
                indx = indx + 1
            indx = indx - 1
        hux = hull[3][indx] * (x - hull[1][indx]) + hull[2][indx]
    neginf = sc.finfo(sc.dtype(sc.float64)).min
    if x < hull[1][0] or x > hull[1][-1]:
        hlx = neginf
    elif indx == 0:
        hlx = ((hull[1][1] - x) * hull[2][0] + (x - hull[1][0]) * hull[2][1]) / (hull[1][1] - hull[1][0])
    elif indx == len(hull[4]):
        hlx = ((hull[1][-1] - x) * hull[2][-2] + (x - hull[1][-2]) * hull[2][-1]) / (hull[1][-1] - hull[1][-2])
    elif x < hull[1][indx + 1]:
        hlx = ((hull[1][indx + 1] - x) * hull[2][indx] + (x - hull[1][indx]) * hull[2][indx + 1]) / (hull[1][indx + 1] - hull[1][indx])
    else:
        hlx = ((hull[1][indx + 2] - x) * hull[2][indx + 1] + (x - hull[1][indx + 1]) * hull[2][indx + 2]) / (hull[1][indx + 2] - hull[1][indx + 1])
    return (hux, hlx)

def _potInt(x, y, z, a2, b2, c2, n):
    """Integral involed in the potential at (x,y,z)
    integrates 1/A B^(n+1) where
    A = sqrt((tau+a)(tau+b)(tau+c)) and B = (1-x^2/(tau+a)-y^2/(tau+b)-z^2/(tau+c))
    from lambda to infty with respect to tau.
    The lower limit lambda is given by lowerlim function."""
    def integrand(tau):
        return _FracInt(x, y, z, a2, b2, c2, tau, n + 1)
    return integrate.quad(integrand, lowerlim(x ** 2, y ** 2, z ** 2, a2, b2, c2), np.inf)[0]

def _forceInt(x, y, z, a2, b2, c2, n, i):
    """Integral involved in the force at (x,y,z)
    integrates 1/A B^n (x_i/(tau+a_i)) where
    A = sqrt((tau+a)(tau+b)(tau+c)) and B = (1-x^2/(tau+a)-y^2/(tau+b)-z^2/(tau+c))
    from lambda to infty with respect to tau.
    The lower limit lambda is given by lowerlim function."""
    def integrand(tau):
        return (x * (i == 0) + y * (i == 1) + z * (i == 2)) / (a2 * (i == 0) + b2 * (i == 1) + c2 * (i == 2) + tau) * _FracInt(x, y, z, a2, b2, c2, tau, n)
    return integrate.quad(integrand, lowerlim(x ** 2, y ** 2, z ** 2, a2, b2, c2), np.inf, epsabs=1e-12)[0]

def _2ndDerivInt(x, y, z, a2, b2, c2, n, i, j):
    """Integral involved in second derivatives d^\\Phi/(dx_i dx_j)
    integrate
        1/A B^(n-1) (-2 x_i/(tau+a_i)) (-2 x_j/(tau+a_j))
    when i /= j or
        1/A [ B^(n-1) 4n x_i^2 / (a_i+t)^2 + B^n -(-2/(a_i+t)) ]
    when i == j where
    A = sqrt((tau+a)(tau+b)(tau+c)) and B = (1-x^2/(tau+a)-y^2/(tau+b)-z^2/(tau+c))
    from lambda to infty with respect to tau
    The lower limit lambda is given by lowerlim function.
    This is a second derivative of _potInt."""
    def integrand(tau):
        if i != j:
            return _FracInt(x, y, z, a2, b2, c2, tau, n - 1) * n * (1.0 + (-1.0 - 2.0 * x / (tau + a2)) * (i == 0 or j == 0)) * (1.0 + (-1.0 - 2.0 * y / (tau + b2)) * (i == 1 or j == 1)) * (1.0 + (-1.0 - 2.0 * z / (tau + c2)) * (i == 2 or j == 2))
        else:
            var2 = x ** 2 * (i == 0) + y ** 2 * (i == 1) + z ** 2 * (i == 2)
            coef2 = a2 * (i == 0) + b2 * (i == 1) + c2 * (i == 2)
            return _FracInt(x, y, z, a2, b2, c2, tau, n - 1) * n * (4.0 * var2) / (tau + coef2) ** 2 + _FracInt(x, y, z, a2, b2, c2, tau, n) * (-2.0 / (tau + coef2))
    return integrate.quad(integrand, lowerlim(x ** 2, y ** 2, z ** 2, a2, b2, c2), np.inf)[0]

def _JzIntegrand(z, Ez, pot):
    """The J_z integrand"""
    return nu.sqrt(2.0 * (Ez - potentialVertical(z, pot)))

def quoted(s):
    """quotes a string if necessary."""
    s = s.strip(u'"')
    if s[0] in (u'-', u' '):
        return s
    if u' ' in s or u'/' in s:
        return u'"%s"' % s
    else:
        return s

def install(path, remove=False, prefix=sys.prefix, recursing=False):
    """install Menu and shortcuts"""
    if sys.platform == 'win32' and (not exists(join(sys.prefix, '.nonadmin'))):
        if isUserAdmin():
            _install(path, remove, prefix, mode='system')
        else:
            from pywintypes import error
            try:
                if not recursing:
                    retcode = runAsAdmin([join(sys.prefix, 'python'), '-c', 'import menuinst; menuinst.install(%r, %r, %r, %r)' % (path, bool(remove), prefix, True)])
                else:
                    retcode = 1
            except error:
                retcode = 1
            if retcode != 0:
                logging.warn('Insufficient permissions to write menu folder.  Falling back to user location')
                _install(path, remove, prefix, mode='user')
    else:
        _install(path, remove, prefix, mode='user')

