def _radix_sort(L, i=0):
    """Most significant char radix sort"""
    if len(L) <= 1:
        return L
    done_bucket = []
    buckets = [[] for x in range(255)]
    for s in L:
        if i >= len(s):
            done_bucket.append(s)
        else:
            buckets[ord(s[i])].append(s)
    buckets = [_radix_sort(b, i + 1) for b in buckets]
    return done_bucket + [b for blist in buckets for b in blist]

def pad_block(block, block_size):
    """Pad a block to block_size with its most frequent value"""
    unique_vals, unique_counts = np.unique(block, return_counts=True)
    most_frequent_value = unique_vals[np.argmax(unique_counts)]
    return np.pad(block, tuple(((0, desired_size - actual_size) for desired_size, actual_size in zip(block_size, block.shape))), mode='constant', constant_values=most_frequent_value)

def divisors(n):
    """Generate the divisors of n"""
    for i in range(1, int(math.sqrt(n) + 1)):
        if n % i == 0:
            yield i
            if i * i != n:
                yield (n / i)

def wait_for_any_cluster(contexts):
    """Wait until any of the clusters are out of retry-wait

    :param contexts: List[ClusterRetryContext]
    :raises: AllClustersFailedException if no more retry attempts allowed"""
    try:
        earliest_retry_at = min((ctx.retry_at for ctx in contexts.values() if not ctx.failed))
    except ValueError:
        raise AllClustersFailedException('Could not find appropriate cluster for worker build.')
    time_until_next = earliest_retry_at - dt.datetime.now()
    time.sleep(max(timedelta(seconds=0), time_until_next).seconds)

def get_checksums(path, algorithms):
    """Compute a checksum(s) of given file using specified algorithms.

    :param path: path to file
    :param algorithms: list of cryptographic hash functions, currently supported: md5, sha256
    :return: dictionary"""
    if not algorithms:
        return {}
    compute_md5 = 'md5' in algorithms
    compute_sha256 = 'sha256' in algorithms
    if compute_md5:
        md5 = hashlib.md5()
    if compute_sha256:
        sha256 = hashlib.sha256()
    blocksize = 65536
    with open(path, mode='rb') as f:
        buf = f.read(blocksize)
        while len(buf) > 0:
            if compute_md5:
                md5.update(buf)
            if compute_sha256:
                sha256.update(buf)
            buf = f.read(blocksize)
    checksums = {}
    if compute_md5:
        checksums['md5sum'] = md5.hexdigest()
        logger.debug('md5sum: %s', checksums['md5sum'])
    if compute_sha256:
        checksums['sha256sum'] = sha256.hexdigest()
        logger.debug('sha256sum: %s', checksums['sha256sum'])
    return checksums

def get_version_of_tools():
    """get versions of tools reactor is using (specified in constants.TOOLS_USED)

    :returns list of dicts, [{"name": "docker-py", "version": "1.2.3"}, ...]"""
    response = []
    for tool in TOOLS_USED:
        pkg_name = tool['pkg_name']
        try:
            tool_module = import_module(pkg_name)
        except ImportError as ex:
            logger.warning("can't import module %s: %r", pkg_name, ex)
        else:
            version = getattr(tool_module, '__version__', None)
            if version is None:
                logger.warning("tool %s doesn't have __version__", pkg_name)
            else:
                response.append({'name': tool.get('display_name', pkg_name), 'version': version, 'path': tool_module.__file__})
    return response

def print_version_of_tools():
    """print versions of used tools to logger"""
    logger.info('Using these tools:')
    for tool in get_version_of_tools():
        logger.info('%s-%s at %s', tool['name'], tool['version'], tool['path'])

def registry_hostname(registry):
    """Strip a reference to a registry to just the hostname:port"""
    if registry.startswith('http:') or registry.startswith('https:'):
        return urlparse(registry).netloc
    else:
        return registry

def guess_manifest_media_type(content):
    """Guess the media type for the given manifest content

    :param content: JSON content of manifest (bytes)
    :return: media type (str), or None if unable to guess"""
    encoding = guess_json_utf(content)
    try:
        manifest = json.loads(content.decode(encoding))
    except (ValueError, TypeError, UnicodeDecodeError):
        logger.exception('Unable to decode JSON')
        logger.debug('response content (%s): %r', encoding, content)
        return None
    try:
        return manifest['mediaType']
    except KeyError:
        if manifest.get('schemaVersion') == 1:
            return get_manifest_media_type('v1')
        logger.warning('no mediaType or schemaVersion=1 in manifest, keys: %s', manifest.keys())

def are_plugins_in_order(plugins_conf, *plugins_names):
    """Check if plugins are configured in given order."""
    all_plugins_names = [plugin['name'] for plugin in plugins_conf or []]
    start_index = 0
    for plugin_name in plugins_names:
        try:
            start_index = all_plugins_names.index(plugin_name, start_index)
        except ValueError:
            return False
    return True

def read_yaml(yaml_data, schema):
    """:param yaml_data: string, yaml content"""
    try:
        resource = resource_stream('atomic_reactor', schema)
        schema = codecs.getreader('utf-8')(resource)
    except (IOError, TypeError):
        logger.error('unable to extract JSON schema, cannot validate')
        raise
    try:
        schema = json.load(schema)
    except ValueError:
        logger.error('unable to decode JSON schema, cannot validate')
        raise
    data = yaml.safe_load(yaml_data)
    validator = jsonschema.Draft4Validator(schema=schema)
    try:
        jsonschema.Draft4Validator.check_schema(schema)
        validator.validate(data)
    except jsonschema.SchemaError:
        logger.error('invalid schema, cannot validate')
        raise
    except jsonschema.ValidationError:
        for error in validator.iter_errors(data):
            path = ''.join((('[{}]' if isinstance(element, int) else '.{}').format(element) for element in error.path))
            if path.startswith('.'):
                path = path[1:]
            logger.error('validation error (%s): %s', path or 'at top level', error.message)
        raise
    return data

def get_parent_image_koji_data(workflow):
    """Transform koji_parent plugin results into metadata dict."""
    koji_parent = workflow.prebuild_results.get(PLUGIN_KOJI_PARENT_KEY) or {}
    image_metadata = {}
    parents = {}
    for img, build in (koji_parent.get(PARENT_IMAGES_KOJI_BUILDS) or {}).items():
        if not build:
            parents[str(img)] = None
        else:
            parents[str(img)] = {key: val for key, val in build.items() if key in ('id', 'nvr')}
    image_metadata[PARENT_IMAGE_BUILDS_KEY] = parents
    image_metadata[PARENT_IMAGES_KEY] = workflow.builder.parents_ordered
    if workflow.builder.base_from_scratch:
        return image_metadata
    base_info = koji_parent.get(BASE_IMAGE_KOJI_BUILD) or {}
    parent_id = base_info.get('id')
    if parent_id is not None:
        try:
            parent_id = int(parent_id)
        except ValueError:
            logger.exception('invalid koji parent id %r', parent_id)
        else:
            image_metadata[BASE_IMAGE_BUILD_ID_KEY] = parent_id
    return image_metadata

def rpm_qf_args(tags=None, separator=';'):
    """Return the arguments to pass to rpm to list RPMs in the format expected
    by parse_rpm_output."""
    if tags is None:
        tags = image_component_rpm_tags
    fmt = separator.join(['%%{%s}' % tag for tag in tags])
    return "-qa --qf '{0}\\n'".format(fmt)

def parse_rpm_output(output, tags=None, separator=';'):
    """Parse output of the rpm query.

    :param output: list, decoded output (str) from the rpm subprocess
    :param tags: list, str fields used for query output
    :return: list, dicts describing each rpm package"""
    if tags is None:
        tags = image_component_rpm_tags
    def field(tag):
        """Get a field value by name"""
        try:
            value = fields[tags.index(tag)]
        except ValueError:
            return None
        if value == '(none)':
            return None
        return value
    components = []
    sigmarker = 'Key ID '
    for rpm in output:
        fields = rpm.rstrip('\n').split(separator)
        if len(fields) < len(tags):
            continue
        signature = field('SIGPGP:pgpsig') or field('SIGGPG:pgpsig')
        if signature:
            parts = signature.split(sigmarker, 1)
            if len(parts) > 1:
                signature = parts[1]
        component_rpm = {'type': 'rpm', 'name': field('NAME'), 'version': field('VERSION'), 'release': field('RELEASE'), 'arch': field('ARCH'), 'sigmd5': field('SIGMD5'), 'signature': signature}
        epoch = field('EPOCH')
        if epoch is not None:
            epoch = int(epoch)
        component_rpm['epoch'] = epoch
        if component_rpm['name'] != 'gpg-pubkey':
            components.append(component_rpm)
    return components

def filter_components_by_name(name, components_list, type_=T_RPM):
    """Generator filters components from components_list by name"""
    for components in components_list:
        for component in components:
            if component['type'] == type_ and component['name'] == name:
                yield component

def deserialize_instance(model, data={}):
    """Translate raw data into a model instance."""
    ret = model()
    for k, v in data.items():
        if v is not None:
            try:
                f = model._meta.get_field(k)
                if isinstance(f, DateTimeField):
                    v = dateparse.parse_datetime(v)
                elif isinstance(f, TimeField):
                    v = dateparse.parse_time(v)
                elif isinstance(f, DateField):
                    v = dateparse.parse_date(v)
            except FieldDoesNotExist:
                pass
        setattr(ret, k, v)
    return ret

