def lazy_property(fn):
    """Decorator that makes a property lazy-evaluated whilst preserving
    docstrings.

    Args:
        fn (function): the property in question

    Returns:
        evaluated version of the property."""
    attr_name = '_lazy_' + fn.__name__
    @property
    @wraps(fn)
    def _lazy_property(self):
        if not hasattr(self, attr_name):
            setattr(self, attr_name, fn(self))
        return getattr(self, attr_name)
    return _lazy_property

def deprecated(reason):
    """This is a decorator which can be used to mark functions
    as deprecated. It will result in a warning being emitted
    when the function is used."""
    if isinstance(reason, string_types):
        def decorator(func1):
            if inspect.isclass(func1):
                fmt1 = 'Call to deprecated class {name} ({reason}).'
            else:
                fmt1 = 'Call to deprecated function {name} ({reason}).'
            @functools.wraps(func1)
            def new_func1(*args, **kwargs):
                warnings.warn(fmt1.format(name=func1.__name__, reason=reason), category=FieldDeprecationWarning, stacklevel=2)
                return func1(*args, **kwargs)
            return new_func1
        return decorator
    elif inspect.isclass(reason) or inspect.isfunction(reason):
        func2 = reason
        if inspect.isclass(func2):
            fmt2 = 'Call to deprecated class {name}.'
        else:
            fmt2 = 'Call to deprecated function {name}.'
        @functools.wraps(func2)
        def new_func2(*args, **kwargs):
            warnings.warn(fmt2.format(name=func2.__name__), category=FieldDeprecationWarning, stacklevel=2)
            return func2(*args, **kwargs)
        return new_func2
    else:
        raise TypeError(repr(type(reason)))

def xpath_selector(selector, html, select_all):
    """Returns Xpath match for `selector` within `html`.

    :param selector: XPath string
    :param html: Unicode content
    :param select_all: True to get all matches"""
    from defusedxml import lxml as dlxml
    from lxml import etree
    import re
    encoded = html.encode('utf-8')
    root = dlxml.fromstring(encoded, parser=etree.HTMLParser())
    xpath_results = root.xpath(selector)
    if not xpath_results:
        logger.warning('XPath selector not found: %r', selector)
        return (False, html)
    if isinstance(xpath_results, list):
        if select_all is False:
            xpath_results = xpath_results[0:1]
    else:
        xpath_results = [xpath_results]
    results = []
    for r in xpath_results:
        if isinstance(r, tuple):
            results.append('%s="%s"' % (r[0], r[1]))
        elif hasattr(r, 'tag'):
            results.append(re.sub('\\s+', ' ', dlxml.tostring(r, method='html', encoding='unicode')))
        else:
            results.append(r)
    return (True, u'\n'.join((six.text_type(x).strip() for x in results)))

