def get_abspath(path, content_dir=CONTENT_DIR):
    """Replaces `content://` with absolute path of `content_dir`.
    By default looks for content in subdirectory `content` in current directory."""
    if path:
        file = re.search('content://(.+)', path)
        if file:
            return os.path.join(content_dir, file.group(1))
    return path

def guess_file_type(kind, filepath=None, youtube_id=None, web_url=None, encoding=None):
    """guess_file_class: determines what file the content is
    Args:
        filepath (str): filepath of file to check
    Returns: string indicating file's class"""
    if youtube_id:
        return FileTypes.YOUTUBE_VIDEO_FILE
    elif web_url:
        return FileTypes.WEB_VIDEO_FILE
    elif encoding:
        return FileTypes.BASE64_FILE
    else:
        ext = os.path.splitext(filepath)[1][1:].lower()
        if kind in FILE_TYPE_MAPPING and ext in FILE_TYPE_MAPPING[kind]:
            return FILE_TYPE_MAPPING[kind][ext]
    return None

def guess_content_kind(path=None, web_video_data=None, questions=None):
    """guess_content_kind: determines what kind the content is
    Args:
        files (str or list): files associated with content
    Returns: string indicating node's kind"""
    if questions and len(questions) > 0:
        return content_kinds.EXERCISE
    if path:
        ext = os.path.splitext(path)[1][1:].lower()
        if ext in content_kinds.MAPPING:
            return content_kinds.MAPPING[ext]
        raise InvalidFormatException('Invalid file type: Allowed formats are {0}'.format([key for key, value in content_kinds.MAPPING.items()]))
    elif web_video_data:
        return content_kinds.VIDEO
    else:
        return content_kinds.TOPIC

def get_content_curation_token(args_token):
    """Get the token through one of four possible ways. Input `args_token` can be
    1. path to a token-containing file (path)
    2. actual token (str) in which case there's nothing to get just pass along
    3. `#` (default value when no --token is given on command line)
    3a. if environment variable CONTENT_CURATION_TOKEN exists, we'll use that
    3b. else we prompt the user interactively"""
    if args_token != '#':
        if os.path.isfile(args_token):
            with open(args_token, 'r') as fobj:
                return fobj.read().strip()
        else:
            return args_token
    else:
        token = get_env('STUDIO_TOKEN') or get_env('CONTENT_CURATION_TOKEN')
        if token is not None:
            return token
        else:
            return prompt_token(config.DOMAIN)

def prompt_token(domain):
    """Prompt user to enter content curation server authentication token.
    Args: domain (str): domain to authenticate user
    Returns: token"""
    token = input("\nEnter content curation server token ('q' to quit): ").lower()
    if token == 'q':
        sys.exit()
    else:
        return token.strip()

def calculate_relative_url(url, filename=None, baseurl=None, subpath=None):
    """Calculate the relative path for a URL relative to a base URL, possibly also injecting in a subpath prefix."""
    if isinstance(subpath, str):
        subpath = subpath.strip('/').split('/')
    elif subpath is None:
        subpath = []
    if baseurl:
        baseurl = urllib.parse.urljoin(baseurl, '.')
        assert url.startswith(baseurl), 'URL must start with baseurl'
        subpath = subpath + url[len(baseurl):].strip('/').split('/')[:-1]
    if not filename:
        filename = unquote(urlparse(url).path.split('/')[-1])
    relative_file_url = '/'.join(['.'] + subpath + [filename])
    return (relative_file_url, subpath, filename)

def extract_path_ext(path, default_ext=None):
    """Extract file extension (without dot) from `path` or return `default_ext` if
    path does not contain a valid extension."""
    ext = None
    _, dotext = os.path.splitext(path)
    if dotext:
        ext = dotext[1:]
    if not ext and default_ext:
        ext = default_ext
    if not ext:
        raise ValueError('No extension in path {} and default_ext is None'.format(path))
    return ext

def path_to_tuple(path, windows=False):
    """Split `chan_path` into individual parts and form a tuple (used as key)."""
    if windows:
        path_tup = tuple(path.split('\\'))
    else:
        path_tup = tuple(path.split('/'))
    path_tup = tuple((normalize('NFD', part) for part in path_tup))
    return path_tup

def get_metadata_file_path(channeldir, filename):
    """Return the path to the metadata file named `filename` that is a sibling of `channeldir`."""
    channelparentdir, channeldirname = os.path.split(channeldir)
    return os.path.join(channelparentdir, filename)

def _clean_dict(row):
    """Transform empty strings values of dict `row` to None."""
    row_cleaned = {}
    for key, val in row.items():
        if val is None or val == '':
            row_cleaned[key] = None
        else:
            row_cleaned[key] = val
    return row_cleaned

def authenticate_user(token):
    """Add the content curation Authorizatino `token` header to `config.SESSION`."""
    config.SESSION.headers.update({'Authorization': 'Token {0}'.format(token)})
    try:
        response = config.SESSION.post(config.authentication_url())
        response.raise_for_status()
        user = json.loads(response._content.decode('utf-8'))
        config.LOGGER.info('Logged in with username {0}'.format(user['username']))
        return (user['username'], token)
    except HTTPError:
        config.LOGGER.error('Invalid token: Credentials not found')
        sys.exit()

def prompt_yes_or_no(message):
    """prompt_yes_or_no: Prompt user to reply with a y/n response
    Args: None
    Returns: None"""
    user_input = input('{} [y/n]:'.format(message)).lower()
    if user_input.startswith('y'):
        return True
    elif user_input.startswith('n'):
        return False
    else:
        return prompt_yes_or_no(message)

def transform_array(rot_mtx, vec_array):
    """transform_array( matrix, vector_array ) -> vector_array

    """
    return map(lambda x, m=rot_mtx: transform(m, x), vec_array)

def translate_array(trans_vec, vec_array):
    """translate_array(trans_vec,vec_array) -> vec_array

    Adds 'mult'*'trans_vec' to each element in vec_array, and returns
    the translated vector."""
    return map(lambda x, m=trans_vec: add(m, x), vec_array)

def fit_apply(fit_result, vec_array):
    """fit_apply(fir_result,vec_array) -> vec_array

    Applies a fit result to an array of vectors"""
    return map(lambda x, t1=fit_result[0], mt2=negate(fit_result[1]), m=fit_result[2]: add(t1, transform(m, add(mt2, x))), vec_array)

def clean_single_dict(indict, prepend_to_keys=None, remove_keys_containing=None):
    """Clean a dict with values that contain single item iterators to single items

    Args:
        indict (dict): Dictionary to be cleaned
        prepend_to_keys (str): String to prepend to all keys
        remove_keys_containing (str): Text to check for in keys to ignore

    Returns:
         dict: Cleaned dictionary

    Examples:
        >>> clean_single_dict(indict={'test1': [1], 'test2': ['H']})
        {'test1': 1, 'test2': 'H'}

        >>> clean_single_dict(indict={'test1': [1], 'test2': ['H']}, prepend_to_keys='struct_')
        {'struct_test1': 1, 'struct_test2': 'H'}

        >>> clean_single_dict(indict={'test1': [1], 'ignore': ['H']}, prepend_to_keys='struct_', remove_keys_containing='ignore')
        {'struct_test1': 1}"""
    if not prepend_to_keys:
        prepend_to_keys = ''
    outdict = {}
    for k, v in indict.items():
        if remove_keys_containing:
            if remove_keys_containing in k:
                continue
        outdict[prepend_to_keys + k] = v[0]
    return outdict

def force_string(val=None):
    """Force a string representation of an object

    Args:
        val: object to parse into a string

    Returns:
        str: String representation"""
    if val is None:
        return ''
    if isinstance(val, list):
        newval = [str(x) for x in val]
        return ';'.join(newval)
    if isinstance(val, str):
        return val
    else:
        return str(val)

def force_list(val=None):
    """Force a list representation of an object

    Args:
        val: object to parse into a list

    Returns:"""
    if val is None:
        return []
    if isinstance(val, pd.Series):
        return val.tolist()
    return val if isinstance(val, list) else [val]

def conv_to_float(indata, inf_str=''):
    """Try to convert an arbitrary string to a float. Specify what will be replaced with "Inf".

    Args:
        indata (str): String which contains a float
        inf_str (str): If string contains something other than a float, and you want to replace it with float("Inf"),
            specify that string here.

    Returns:
        float: Converted string representation"""
    if indata.strip() == inf_str:
        outdata = float('Inf')
    else:
        try:
            outdata = float(indata)
        except:
            raise ValueError('Unable to convert {} to float'.format(indata))
    return outdata

def model_loader(gem_file_path, gem_file_type):
    """Consolidated function to load a GEM using COBRApy. Specify the file type being loaded.

    Args:
        gem_file_path (str): Path to model file
        gem_file_type (str): GEM model type - ``sbml`` (or ``xml``), ``mat``, or ``json`` format

    Returns:
        COBRApy Model object."""
    if gem_file_type.lower() == 'xml' or gem_file_type.lower() == 'sbml':
        model = read_sbml_model(gem_file_path)
    elif gem_file_type.lower() == 'mat':
        model = load_matlab_model(gem_file_path)
    elif gem_file_type.lower() == 'json':
        model = load_json_model(gem_file_path)
    else:
        raise ValueError('File type must be "sbml", "xml", "mat", or "json".')
    return model

def true_num_reactions(model, custom_spont_id=None):
    """Return the number of reactions associated with a gene.

    Args:
        model (Model):
        custom_spont_id (str): Optional custom spontaneous ID if it does not match the regular expression ``[Ss](_|)0001``

    Returns:
        int: Number of reactions associated with a gene"""
    true_num = 0
    for rxn in model.reactions:
        if len(rxn.genes) == 0:
            continue
        if len(rxn.genes) == 1 and is_spontaneous(list(rxn.genes)[0], custom_id=custom_spont_id):
            continue
        else:
            true_num += 1
    return true_num

def parse_results_mol2(mol2_outpath):
    """Parse a DOCK6 mol2 output file, return a Pandas DataFrame of the results.

    Args:
        mol2_outpath (str): Path to mol2 output file

    Returns:
        DataFrame: Pandas DataFrame of the results"""
    docked_ligands = pd.DataFrame()
    lines = [line.strip() for line in open(mol2_outpath, 'r')]
    props = {}
    for i, line in enumerate(lines):
        if line.startswith('########## Name:'):
            ligand = line.strip().strip('##########').replace(' ', '').replace('\t', '').split(':')[1]
            line = lines[i + 1]
            props = {}
            props['Ligand'] = ligand
        if line.startswith('##########'):
            splitter = line.strip().strip('##########').replace(' ', '').replace('\t', '').split(':')
            props[splitter[0]] = float(splitter[1])
        if line.startswith('@<TRIPOS>MOLECULE'):
            if props:
                docked_ligands = docked_ligands.append(props, ignore_index=True)
    return docked_ligands

def get_metalpdb_info(metalpdb_lig_file):
    """Parse a MetalPDB .lig file and return a tuple of the chain ID it represents, along with metal binding information.

    Args:
        metalpdb_lig_file (str): Path to .lig file

    Returns:
        tuple: (str, dict) of the chain ID and the parsed metal binding site information"""
    pdb_metals = ['CU', 'ZN', 'MN', 'FE', 'MG', 'CO', 'SE', 'YB', 'SF4', 'FES', 'F3S', 'NI', 'FE2']
    coordination_number = 0
    endogenous_ligands = []
    exogenous_ligands = []
    ss = StructProp(ident='metalpdb', structure_path=metalpdb_lig_file, file_type='pdb')
    chain_id = op.basename(metalpdb_lig_file)[5]
    metal_id = (op.basename(metalpdb_lig_file).split('_')[2], op.basename(metalpdb_lig_file).split('_')[3])
    for r in ss.parse_structure().first_model.get_residues():
        return_id = (r.get_id(), r.get_resname())
        if r.get_id()[0] != ' ':
            if not r.resname.strip() in pdb_metals and r.resname != 'HOH':
                exogenous_ligands.append(return_id)
        else:
            endogenous_ligands.append(return_id)
        for a in r.get_atom():
            if not a.element in pdb_metals:
                coordination_number += 1
    infodict = {metal_id: {'endogenous_ligands': endogenous_ligands, 'exogenous_ligands': exogenous_ligands, 'coordination_number': coordination_number}}
    return (chain_id, infodict)

def get_percent_identity(a_aln_seq, b_aln_seq):
    """Get the percent identity between two alignment strings"""
    if len(a_aln_seq) != len(b_aln_seq):
        raise ValueError('Sequence lengths not equal - was an alignment run?')
    count = 0
    gaps = 0
    for n in range(0, len(a_aln_seq)):
        if a_aln_seq[n] == b_aln_seq[n]:
            if a_aln_seq[n] != '-':
                count += 1
            else:
                gaps += 1
    return count / float(len(a_aln_seq) - gaps)

def get_oligomeric_state(swiss_model_path):
    """Parse the oligomeric prediction in a SWISS-MODEL repository file

    As of 2018-02-26, works on all E. coli models. Untested on other pre-made organism models.

    Args:
        swiss_model_path (str): Path to SWISS-MODEL PDB file

    Returns:
        dict: Information parsed about the oligomeric state"""
    oligo_info = {}
    with open(swiss_model_path, 'r') as f:
        for line in f:
            if line.startswith('REMARK   3 MODEL INFORMATION'):
                break
        for i in range(10):
            line = f.readline()
            if 'ENGIN' in line:
                oligo_info['ENGIN'] = line.rstrip().split(' ')[-1]
            elif 'OSTAT' in line:
                oligo_info['OSTAT'] = line.rstrip().split(' ')[-1]
            elif 'OSRSN' in line:
                oligo_info['OSRSN'] = line.rstrip().split(' ')[-1]
            elif 'QSPRD' in line:
                oligo_info['QSPRD'] = line.rstrip().split(' ')[-1]
            elif 'GMQE' in line:
                oligo_info['GMQE'] = line.rstrip().split(' ')[-1]
            elif 'QMN4' in line:
                oligo_info['QMN4'] = line.rstrip().split(' ')[-1]
            elif 'MODT' in line:
                oligo_info['MODT'] = line.rstrip().split(' ')[-1]
    return oligo_info

def translate_ostat(ostat):
    """Translate the OSTAT field to an integer.

    As of 2018-02-26, works on all E. coli models. Untested on other pre-made organism models.

    Args:
        ostat (str): Predicted oligomeric state of the PDB file

    Returns:
        int: Translated string to integer"""
    ostat_lower = ostat.strip().lower()
    if ostat_lower == 'monomer':
        return 1
    elif ostat_lower == 'homo-dimer':
        return 2
    elif ostat_lower == 'homo-trimer':
        return 3
    elif ostat_lower == 'homo-tetramer':
        return 4
    elif ostat_lower == 'homo-pentamer':
        return 5
    elif ostat_lower == 'homo-hexamer':
        return 6
    elif ostat_lower == 'homo-heptamer':
        return 7
    elif ostat_lower == 'homo-octamer':
        return 8
    else:
        num = int(ostat_lower.split('-')[1])
        return num

def parse_cctop_regions(infile):
    """Parse a CCTOP XML results file and return a dictionary of labeled TM domains in the format::

            {'I1': [31, 32, 33, 34, 35, 36],
             'I2': [73, 74, 75, 76, 77, 78],
             'I3': [133, ...],
             ...}

    Where the regions are labeled as they are sequentially found along with a list of the residue numbers that make up
    the region.

    Args:
        infile (str): Path to CCTOP XML file

    Returns:
        dict: Dictionary of lists in the format described above"""
    parsed = parse_cctop_full(infile)
    if not parsed:
        return {}
    return ssbio.utils.label_sequential_regions(parsed)

def get_protein_feather_paths(protgroup, memornot, protgroup_dict, protein_feathers_dir, core_only_genes=None):
    """protgroup example: ('subsystem', 'cog_primary', 'H')
    memornot example: ('vizrecon', 'membrane')
    protgroup_dict example: {'databases': {'redoxdb': {'experimental_sensitive_cys': ['b2518','b3352','b2195','b4016'], ...}}}"""
    prots_memornot = protgroup_dict['localization'][memornot[0]][memornot[1]]
    if protgroup[0] == 'localization':
        if protgroup[2] != 'all':
            if memornot[1] in ['membrane', 'inner_membrane', 'outer_membrane'] and protgroup[2] not in ['membrane', 'inner_membrane', 'outer_membrane']:
                return []
            if memornot[1] not in ['membrane', 'inner_membrane', 'outer_membrane'] and protgroup[2] in ['membrane', 'inner_membrane', 'outer_membrane']:
                return []
    prots_group = protgroup_dict[protgroup[0]][protgroup[1]][protgroup[2]]
    prots_filtered = list(set(prots_group).intersection(prots_memornot))
    if core_only_genes:
        prots_filtered = list(set(prots_filtered).intersection(core_only_genes))
    return [op.join(protein_feathers_dir, '{}_protein_strain_properties.fthr'.format(x)) for x in prots_filtered if op.exists(op.join(protein_feathers_dir, '{}_protein_strain_properties.fthr'.format(x)))]

def get_observed_strains_and_df(observation, observation_dict):
    """observation example: 'ros_simulated'
    observation_dict example: {'ros_simulated': [['NT12204_755', 'wt'], ['NT12120_270', 'wt'], ...] ...}"""
    observed_df = pd.DataFrame.from_records(observation_dict[observation], columns=['strain', 'phenotype']).set_index('strain')
    observed_strains = observed_df.index.tolist()
    return (observed_strains, observed_df)

def get_interested_subsequences(subsequences):
    """subsequences example: ['disorder_2D', 'ss_disorder_2D', ...]
    filter_subseq_suffixes example: {'disorder_2D': ['aa_count_ord', 'aa_count_dis'], ... } -- defined above"""
    keep_indices = []
    for subseq in subsequences:
        if subseq == 'all':
            keep_indices.extend([x for x in filter_subseq_suffixes[subseq]])
        else:
            keep_indices.extend([subseq + '_' + x for x in filter_subseq_suffixes[subseq]])
    return keep_indices

def compute_skew_stats(intra, inter):
    """Returns two dictionaries reporting (skew, skew_pval) for all groups"""
    intra_skew = {}
    for k, v in intra.items():
        skew = st.skew(v)
        try:
            skew_zstat, skew_pval = st.skewtest(v)
        except ValueError:
            skew_zstat, skew_pval = (0, 1)
        intra_skew[k] = (skew, skew_zstat, skew_pval)
    inter_skew = {}
    for k, v in inter.items():
        skew_sep = st.skew(v.flatten())
        try:
            skew_sep_zstat, skew_sep_pval = st.skewtest(v.flatten())
        except ValueError:
            skew_sep_zstat, skew_sep_pval = (0, 1)
        inter_skew['-'.join(k)] = (skew_sep, skew_sep_zstat, skew_sep_pval)
        for intra_key in k:
            try:
                separation_zstat, separation_pval = mannwhitneyu(intra[intra_key], v.flatten(), alternative='less')
            except ValueError:
                separation_zstat, separation_pval = (0, 1)
            inter_skew['{}<{}'.format(intra_key, '-'.join(k))] = (separation_zstat, separation_pval)
    return (intra_skew, inter_skew)

def save_json(obj, outfile, allow_nan=True, compression=False):
    """Save an ssbio object as a JSON file using json_tricks"""
    if compression:
        with open(outfile, 'wb') as f:
            dump(obj, f, allow_nan=allow_nan, compression=compression)
    else:
        with open(outfile, 'w') as f:
            dump(obj, f, allow_nan=allow_nan, compression=compression)
    log.info('Saved {} (id: {}) to {}'.format(type(obj), obj.id, outfile))

def load_json(file, new_root_dir=None, decompression=False):
    """Load a JSON file using json_tricks"""
    if decompression:
        with open(file, 'rb') as f:
            my_object = load(f, decompression=decompression)
    else:
        with open(file, 'r') as f:
            my_object = load(f, decompression=decompression)
    if new_root_dir:
        my_object.root_dir = new_root_dir
    return my_object

def write(structure, name=None):
    """Writes a Structure in PDB format through PDBIO.
    Simplifies life.."""
    from Bio.PDB import PDBIO
    io = PDBIO()
    io.set_structure(structure)
    if not name:
        s_name = structure.id
    else:
        s_name = name
    name = '%s.pdb' % s_name
    seed = 0
    while 1:
        if os.path.exists(name):
            name = '%s_%s.pdb' % (s_name, seed)
            seed += 1
        else:
            break
    io.save(name)
    return name

def biopython_protein_scale(inseq, scale, custom_scale_dict=None, window=7):
    """Use Biopython to calculate properties using a sliding window over a sequence given a specific scale to use."""
    if scale == 'kd_hydrophobicity':
        scale_dict = kd_hydrophobicity_one
    elif scale == 'bulkiness':
        scale_dict = bulkiness_one
    elif scale == 'custom':
        scale_dict = custom_scale_dict
    else:
        raise ValueError('Scale not available')
    inseq = ssbio.protein.sequence.utils.cast_to_str(inseq)
    analysed_seq = ProteinAnalysis(inseq)
    result = analysed_seq.protein_scale(param_dict=scale_dict, window=window)
    for i in range(window // 2):
        result.insert(0, float('Inf'))
        result.append(float('Inf'))
    return result

def parse_kegg_gene_metadata(infile):
    """Parse the KEGG flatfile and return a dictionary of metadata.

    Dictionary keys are:
        refseq
        uniprot
        pdbs
        taxonomy

    Args:
        infile: Path to KEGG flatfile

    Returns:
        dict: Dictionary of metadata"""
    metadata = defaultdict(str)
    with open(infile) as mf:
        kegg_parsed = bs_kegg.parse(mf.read())
    if 'DBLINKS' in kegg_parsed.keys():
        if 'UniProt' in kegg_parsed['DBLINKS']:
            unis = str(kegg_parsed['DBLINKS']['UniProt']).split(' ')
            if isinstance(unis, list):
                metadata['uniprot'] = unis[0]
            else:
                metadata['uniprot'] = unis
        if 'NCBI-ProteinID' in kegg_parsed['DBLINKS']:
            metadata['refseq'] = str(kegg_parsed['DBLINKS']['NCBI-ProteinID'])
    if 'STRUCTURE' in kegg_parsed.keys():
        metadata['pdbs'] = str(kegg_parsed['STRUCTURE']['PDB']).split(' ')
    else:
        metadata['pdbs'] = None
    if 'ORGANISM' in kegg_parsed.keys():
        metadata['taxonomy'] = str(kegg_parsed['ORGANISM'])
    return metadata

def run_makeblastdb(infile, dbtype, outdir=''):
    """Make the BLAST database for a genome file.

    Args:
        infile (str): path to genome FASTA file
        dbtype (str): "nucl" or "prot" - what format your genome files are in
        outdir (str): path to directory to output database files (default is original folder)

    Returns:
        Paths to BLAST databases."""
    og_dir, name, ext = utils.split_folder_and_path(infile)
    if not outdir:
        outdir = og_dir
    outfile_basename = op.join(outdir, name)
    if dbtype == 'nucl':
        outext = ['.nhr', '.nin', '.nsq']
    elif dbtype == 'prot':
        outext = ['.phr', '.pin', '.psq']
    else:
        raise ValueError('dbtype must be "nucl" or "prot"')
    outfile_all = [outfile_basename + x for x in outext]
    db_made = True
    for f in outfile_all:
        if not op.exists(f):
            db_made = False
    if db_made:
        log.debug('BLAST database already exists at {}'.format(outfile_basename))
        return outfile_all
    else:
        retval = subprocess.call('makeblastdb -in {} -dbtype {} -out {}'.format(infile, dbtype, outfile_basename), shell=True)
        if retval == 0:
            log.debug('Made BLAST database at {}'.format(outfile_basename))
            return outfile_all
        else:
            log.error('Error running makeblastdb, exit code {}'.format(retval))

def cast_to_str(obj):
    """Return a string representation of a Seq or SeqRecord.

    Args:
        obj (str, Seq, SeqRecord): Biopython Seq or SeqRecord

    Returns:
        str: String representation of the sequence"""
    if isinstance(obj, str):
        return obj
    if isinstance(obj, Seq):
        return str(obj)
    if isinstance(obj, SeqRecord):
        return str(obj.seq)
    else:
        raise ValueError('Must provide a string, Seq, or SeqRecord object.')

def cast_to_seq(obj, alphabet=IUPAC.extended_protein):
    """Return a Seq representation of a string or SeqRecord object.

    Args:
        obj (str, Seq, SeqRecord): Sequence string or Biopython SeqRecord object
        alphabet: See Biopython SeqRecord docs

    Returns:
        Seq: Seq representation of the sequence"""
    if isinstance(obj, Seq):
        return obj
    if isinstance(obj, SeqRecord):
        return obj.seq
    if isinstance(obj, str):
        obj = obj.upper()
        return Seq(obj, alphabet)
    else:
        raise ValueError('Must provide a string, Seq, or SeqRecord object.')

def cast_to_seq_record(obj, alphabet=IUPAC.extended_protein, id='<unknown id>', name='<unknown name>', description='<unknown description>', dbxrefs=None, features=None, annotations=None, letter_annotations=None):
    """Return a SeqRecord representation of a string or Seq object.

    Args:
        obj (str, Seq, SeqRecord): Sequence string or Biopython Seq object
        alphabet: See Biopython SeqRecord docs
        id: See Biopython SeqRecord docs
        name: See Biopython SeqRecord docs
        description: See Biopython SeqRecord docs
        dbxrefs: See Biopython SeqRecord docs
        features: See Biopython SeqRecord docs
        annotations: See Biopython SeqRecord docs
        letter_annotations: See Biopython SeqRecord docs

    Returns:
        SeqRecord: SeqRecord representation of the sequence"""
    if isinstance(obj, SeqRecord):
        return obj
    if isinstance(obj, Seq):
        return SeqRecord(obj, id, name, description, dbxrefs, features, annotations, letter_annotations)
    if isinstance(obj, str):
        obj = obj.upper()
        return SeqRecord(Seq(obj, alphabet), id, name, description, dbxrefs, features, annotations, letter_annotations)
    else:
        raise ValueError('Must provide a string, Seq, or SeqRecord object.')

