    :rtype: dict"""
    shared_mapping = {'description': (definition_header, 'DescriptionString'), 'version': (definition_header, 'VersionString'), 'author': ('Author', 'NameString'), 'license': ('Author', 'CopyrightString'), 'contact': ('Author', 'ContactInfoString'), 'citation': ('Citation', 'NameString'), 'citation_description': ('Citation', 'DescriptionString'), 'citation_version': ('Citation', 'PublishedVersionString'), 'citation_url': ('Citation', 'ReferenceURL')}
    result = {}
    update_insert_values(bel_resource, shared_mapping, result)
