def int_or_str(v: Optional[str]) -> Union[None, int, str]:
    """Safe converts an string represent an integer to an integer or passes through ``None``."""
    if v is None:
        return
    try:
        return int(v)
    except ValueError:
        return v

def get_fusion_language(identifier: ParserElement, permissive: bool=True) -> ParserElement:
    """Build a fusion parser."""
    range_coordinate = Suppress('"') + range_coordinate_unquoted + Suppress('"')
    if permissive:
        range_coordinate = range_coordinate | range_coordinate_unquoted
    return fusion_tags + nest(Group(identifier)(PARTNER_5P), Group(range_coordinate)(RANGE_5P), Group(identifier)(PARTNER_3P), Group(range_coordinate)(RANGE_3P))

def _fusion_legacy_handler(_, __, tokens):
    """Handle a legacy fusion."""
    if RANGE_5P not in tokens:
        tokens[RANGE_5P] = {FUSION_MISSING: '?'}
    if RANGE_3P not in tokens:
        tokens[RANGE_3P] = {FUSION_MISSING: '?'}
    return tokens

def to_graphml(graph: BELGraph, path: Union[str, BinaryIO]) -> None:
    """Write this graph to GraphML XML file using :func:`networkx.write_graphml`.

    The .graphml file extension is suggested so Cytoscape can recognize it."""
    rv = nx.MultiDiGraph()
    for node in graph:
        rv.add_node(node.as_bel(), function=node.function)
    for u, v, key, edge_data in graph.edges(data=True, keys=True):
        rv.add_edge(u.as_bel(), v.as_bel(), interaction=edge_data[RELATION], bel=graph.edge_to_bel(u, v, edge_data), key=key)
    nx.write_graphml(rv, path)

def to_gsea(graph: BELGraph, file: Optional[TextIO]=None) -> None:
    """Write the genes/gene products to a GRP file for use with GSEA gene set enrichment analysis.

    .. seealso::

        - GRP `format specification <http://software.broadinstitute.org/cancer/software/gsea/wiki/index.php/Data_formats#GRP:_Gene_set_file_format_.28.2A.grp.29>`_
        - GSEA `publication <https://doi.org/10.1073/pnas.0506580102>`_"""
    print('# {}'.format(graph.name), file=file)
    nodes = {data[NAME] for data in graph if NAMESPACE in data and data[NAMESPACE].upper() == 'HGNC' and (NAME in data)}
    for node in sorted(nodes):
        print(node, file=file)

def _handle_nodes(nodes: MaybeNodeList) -> List[BaseEntity]:
    """Handle node(s) that might be dictionaries."""
    if isinstance(nodes, BaseEntity):
