def function_inclusion_filter_builder(func: Strings) -> NodePredicate:
    """Build a filter that only passes on nodes of the given function(s).

    :param func: A BEL Function or list/set/tuple of BEL functions"""
    if isinstance(func, str):
        return _single_function_inclusion_filter_builder(func)
    elif isinstance(func, Iterable):
        return _collection_function_inclusion_builder(func)
    raise TypeError('Invalid type for argument: {}'.format(func))

def _single_function_inclusion_filter_builder(func: str) -> NodePredicate:
    """Build a function inclusion filter for a single function."""
    def function_inclusion_filter(_: BELGraph, node: BaseEntity) -> bool:
        """Pass only for a node that has the enclosed function."""
        return node.function == func
    return function_inclusion_filter

def _collection_function_inclusion_builder(funcs: Iterable[str]) -> NodePredicate:
    """Build a function inclusion filter for a collection of functions."""
    funcs = set(funcs)
    if not funcs:
        raise ValueError('can not build function inclusion filter with empty list of functions')
    def functions_inclusion_filter(_: BELGraph, node: BaseEntity) -> bool:
        """Pass only for a node that is one of the enclosed functions."""
        return node.function in funcs
    return functions_inclusion_filter

def build_node_data_search(key: str, data_predicate: Callable[[Any], bool]) -> NodePredicate:
    """Build a filter for nodes whose associated data with the given key passes the given predicate.

    :param key: The node data dictionary key to check
    :param data_predicate: The filter to apply to the node data dictionary"""
    def node_data_filter(_: BELGraph, node: BaseEntity) -> bool:
        """Pass if the given node has a given data annotated and passes the contained filter."""
        value = node.get(key)
        return value is not None and data_predicate(value)
    return node_data_filter

def build_node_graph_data_search(key: str, data_predicate: Callable[[Any], bool]):
    """Build a function for testing data associated with the node in the graph.

    :param key: The node data dictionary key to check
    :param data_predicate: The filter to apply to the node data dictionary"""
    def node_data_filter(graph: BELGraph, node: BaseEntity) -> bool:
        """Pass if the given node has a given data annotated and passes the contained filter."""
        value = graph.nodes[node].get(key)
        return value is not None and data_predicate(value)
    return node_data_filter

def build_node_key_search(query, key) -> NodePredicate:
    """Build a node filter for nodes whose values for the given key are superstrings of the query string(s).

    :param query: The query string or strings to check if they're in the node name
    :type query: str or iter[str]
    :param str key: The key for the node data dictionary. Should refer only to entries that have str values"""
    if isinstance(query, str):
        return build_node_data_search(key, lambda s: query.lower() in s.lower())
    if isinstance(query, Iterable):
        return build_node_data_search(key, lambda s: any((q.lower() in s.lower() for q in query)))
    raise TypeError('query is wrong type: %s', query)

def namespace_inclusion_builder(namespace: Strings) -> NodePredicate:
    """Build a predicate for namespace inclusion."""
    if isinstance(namespace, str):
        def namespace_filter(_: BELGraph, node: BaseEntity) -> bool:
            """Pass only for a node that has the enclosed namespace."""
            return NAMESPACE in node and node[NAMESPACE] == namespace
    elif isinstance(namespace, Iterable):
        namespaces = set(namespace)
        def namespace_filter(_: BELGraph, node: BaseEntity) -> bool:
            """Pass only for a node that has a namespace in the enclosed set."""
            return NAMESPACE in node and node[NAMESPACE] in namespaces
    else:
        raise TypeError('Invalid type for argument: {}'.format(namespace))
    return namespace_filter

def hbp_namespace(name: str, sha: Optional[str]=None) -> str:
    """Format a namespace URL."""
    return HBP_NAMESPACE_URL.format(sha=sha or LAST_HASH, keyword=name)

def has_pubmed(edge_data: EdgeData) -> bool:
    """Check if the edge has a PubMed citation."""
    return CITATION in edge_data and CITATION_TYPE_PUBMED == edge_data[CITATION][CITATION_TYPE]

def has_authors(edge_data: EdgeData) -> bool:
    """Check if the edge contains author information for its citation."""
    return CITATION in edge_data and CITATION_AUTHORS in edge_data[CITATION] and edge_data[CITATION][CITATION_AUTHORS]

def has_pathology_causal(graph: BELGraph, u: BaseEntity, v: BaseEntity, k: str) -> bool:
    """Check if the subject is a pathology and has a causal relationship with a non bioprocess/pathology.

    :return: If the subject of this edge is a pathology and it participates in a causal reaction."""
    return isinstance(u, Pathology) and is_causal_relation(graph, u, v, k) and (not isinstance(v, (Pathology, BiologicalProcess)))

def modifier_po_to_dict(tokens):
    """Get the location, activity, and/or transformation information as a dictionary.

    :return: a dictionary describing the modifier
    :rtype: dict"""
    attrs = {}
    if LOCATION in tokens:
        attrs[LOCATION] = dict(tokens[LOCATION])
    if MODIFIER not in tokens:
        return attrs
    if LOCATION in tokens[TARGET]:
        attrs[LOCATION] = tokens[TARGET][LOCATION].asDict()
    if tokens[MODIFIER] == DEGRADATION:
        attrs[MODIFIER] = tokens[MODIFIER]
    elif tokens[MODIFIER] == ACTIVITY:
        attrs[MODIFIER] = tokens[MODIFIER]
        if EFFECT in tokens:
            attrs[EFFECT] = dict(tokens[EFFECT])
    elif tokens[MODIFIER] == TRANSLOCATION:
        attrs[MODIFIER] = tokens[MODIFIER]
        if EFFECT in tokens:
            attrs[EFFECT] = tokens[EFFECT].asDict()
    elif tokens[MODIFIER] == CELL_SECRETION:
        attrs.update(secretion())
    elif tokens[MODIFIER] == CELL_SURFACE_EXPRESSION:
        attrs.update(cell_surface_expression())
    else:
        raise ValueError('Invalid value for tokens[MODIFIER]: {}'.format(tokens[MODIFIER]))
    return attrs

def invert_node_predicate(node_predicate: NodePredicate) -> NodePredicate:
    """Build a node predicate that is the inverse of the given node predicate."""
    def inverse_predicate(graph: BELGraph, node: BaseEntity) -> bool:
        """Return the inverse of the enclosed node predicate applied to the graph and node."""
        return not node_predicate(graph, node)
    return inverse_predicate

def filter_nodes(graph: BELGraph, node_predicates: NodePredicates) -> Iterable[BaseEntity]:
    """Apply a set of predicates to the nodes iterator of a BEL graph."""
    concatenated_predicate = concatenate_node_predicates(node_predicates=node_predicates)
    for node in graph:
        if concatenated_predicate(graph, node):
            yield node

def get_nodes(graph: BELGraph, node_predicates: NodePredicates) -> Set[BaseEntity]:
    """Get the set of all nodes that pass the predicates."""
    return set(filter_nodes(graph, node_predicates=node_predicates))

def count_passed_node_filter(graph: BELGraph, node_predicates: NodePredicates) -> int:
    """Count how many nodes pass a given set of node predicates."""
    return sum((1 for _ in filter_nodes(graph, node_predicates=node_predicates)))

def get_rna_leaves(graph) -> Iterable[BaseEntity]:
    """Iterate over all RNAs who have only one connection, that's a translation to its protein.

    :param pybel.BELGraph graph: A BEL graph"""
    for node in get_nodes_by_function(graph, RNA):
        if graph.in_degree(node) != 0:
            continue
        if graph.out_degree(node) != 1:
            continue
        _, _, d = list(graph.out_edges(node, data=True))[0]
        if d[RELATION] == TRANSLATED_TO:
            yield node

def _entity_list_as_bel(entities: Iterable[BaseEntity]) -> str:
    """Stringify a list of BEL entities."""
    return ', '.join((e.as_bel() for e in entities))

def iter_annotation_value_pairs(graph) -> Iterable[Tuple[str, str]]:
    """Iterate over the key/value pairs, with duplicates, for each annotation used in a BEL graph.

    :param pybel.BELGraph graph: A BEL graph"""
    return ((key, value) for _, _, data in graph.edges(data=True) if ANNOTATIONS in data for key, values in data[ANNOTATIONS].items() for value in values)

def iter_annotation_values(graph, annotation: str) -> Iterable[str]:
    """Iterate over all of the values for an annotation used in the graph.

    :param pybel.BELGraph graph: A BEL graph
    :param str annotation: The annotation to grab"""
    return (value for _, _, data in graph.edges(data=True) if edge_has_annotation(data, annotation) for value in data[ANNOTATIONS][annotation])

def _group_dict_set(iterator):
    """Make a dict that accumulates the values for each key in an iterator of doubles.

    :param iter[tuple[A,B]] iterator: An iterator
    :rtype: dict[A,set[B]]"""
    d = defaultdict(set)
    for key, value in iterator:
        d[key].add(value)
    return dict(d)

def get_annotation_values(graph, annotation: str) -> Set[str]:
    """Get all values for the given annotation.

    :param pybel.BELGraph graph: A BEL graph
    :param annotation: The annotation to summarize
    :return: A set of all annotation values"""
    return set(iter_annotation_values(graph, annotation))

def count_relations(graph) -> Counter:
    """Return a histogram over all relationships in a graph.

    :param pybel.BELGraph graph: A BEL graph
    :return: A Counter from {relation type: frequency}"""
    return Counter((data[RELATION] for _, _, data in graph.edges(data=True)))

def _annotation_iter_helper(graph) -> Iterable[str]:
    """Iterate over the annotation keys.

    :param pybel.BELGraph graph: A BEL graph"""
    return (key for _, _, data in graph.edges(data=True) if ANNOTATIONS in data for key in data[ANNOTATIONS])

def get_unused_list_annotation_values(graph) -> Mapping[str, Set[str]]:
    """Get all of the unused values for list annotations.

    :param pybel.BELGraph graph: A BEL graph
    :return: A dictionary of {str annotation: set of str values that aren't used}"""
    result = {}
    for annotation, values in graph.annotation_list.items():
        used_values = get_annotation_values(graph, annotation)
        if len(used_values) == len(values):
            continue
        result[annotation] = set(values) - used_values
    return result

def expand_all_node_neighborhoods(universe, graph, filter_pathologies: bool=False) -> None:
    """Expand the neighborhoods of all nodes in the given graph.

    :param pybel.BELGraph universe: The graph containing the stuff to add
    :param pybel.BELGraph  graph: The graph to add stuff to
    :param filter_pathologies: Should expansion take place around pathologies?"""
    for node in list(graph):
        if filter_pathologies and is_pathology(node):
            continue
        expand_node_neighborhood(universe, graph, node)

def parse_document(graph: BELGraph, enumerated_lines: Iterable[Tuple[int, str]], metadata_parser: MetadataParser) -> None:
    """Parse the lines in the document section of a BEL script."""
    parse_document_start_time = time.time()
    for line_number, line in enumerated_lines:
        try:
            metadata_parser.parseString(line, line_number=line_number)
        except VersionFormatWarning as exc:
            _log_parse_exception(graph, exc)
            graph.add_warning(exc)
        except Exception as e:
            exc = MalformedMetadataException(line_number, line, 0)
            _log_parse_exception(graph, exc)
            raise exc from e
    for required in REQUIRED_METADATA:
        required_metadatum = metadata_parser.document_metadata.get(required)
        if required_metadatum is not None:
            continue
        required_metadatum_key = INVERSE_DOCUMENT_KEYS[required]
        exc = MissingMetadataException.make(required_metadatum_key)
        graph.warnings.insert(0, (None, exc, {}))
        _log_parse_exception(graph, exc)
    graph.document.update(metadata_parser.document_metadata)
    log.info('Finished parsing document section in %.02f seconds', time.time() - parse_document_start_time)

def to_database(graph, manager: Optional[Manager]=None, store_parts: bool=True, use_tqdm: bool=False):
    """Store a graph in a database.

    :param BELGraph graph: A BEL graph
    :param store_parts: Should the graph be stored in the edge store?
    :return: If successful, returns the network object from the database.
    :rtype: Optional[Network]"""
    if manager is None:
        manager = Manager()
    try:
        return manager.insert_graph(graph, store_parts=store_parts, use_tqdm=use_tqdm)
    except (IntegrityError, OperationalError):
        manager.session.rollback()
        log.exception('Error storing graph')
    except Exception as e:
        manager.session.rollback()
        raise e

def node_predicate(f: Callable[[BaseEntity], bool]) -> NodePredicate:
    """Tag a node predicate that takes a dictionary to also accept a pair of (BELGraph, node).

    Apply this as a decorator to a function that takes a single argument, a PyBEL node, to make
    sure that it can also accept a pair of arguments, a BELGraph and a PyBEL node as well."""
    @wraps(f)
    def wrapped(*args):
        x = args[0]
        if isinstance(x, BELGraph):
            return f(args[1], *args[2:])
        return f(*args)
    return wrapped

def _node_has_variant(node: BaseEntity, variant: str) -> bool:
    """Return true if the node has at least one of the given variant.

    :param variant: :data:`PMOD`, :data:`HGVS`, :data:`GMOD`, or :data:`FRAGMENT`"""
    return VARIANTS in node and any((variant_dict[KIND] == variant for variant_dict in node[VARIANTS]))

def has_activity(graph: BELGraph, node: BaseEntity) -> bool:
    """Return true if over any of the node's edges, it has a molecular activity."""
    return _node_has_modifier(graph, node, ACTIVITY)

def is_degraded(graph: BELGraph, node: BaseEntity) -> bool:
    """Return true if over any of the node's edges, it is degraded."""
    return _node_has_modifier(graph, node, DEGRADATION)

def is_translocated(graph: BELGraph, node: BaseEntity) -> bool:
    """Return true if over any of the node's edges, it is translocated."""
    return _node_has_modifier(graph, node, TRANSLOCATION)

def has_causal_in_edges(graph: BELGraph, node: BaseEntity) -> bool:
    """Return true if the node contains any in_edges that are causal."""
    return any((data[RELATION] in CAUSAL_RELATIONS for _, _, data in graph.in_edges(node, data=True)))

def has_causal_out_edges(graph: BELGraph, node: BaseEntity) -> bool:
    """Return true if the node contains any out_edges that are causal."""
    return any((data[RELATION] in CAUSAL_RELATIONS for _, _, data in graph.out_edges(node, data=True)))

def node_exclusion_predicate_builder(nodes: Iterable[BaseEntity]) -> NodePredicate:
    """Build a node predicate that returns false for the given nodes."""
    nodes = set(nodes)
    @node_predicate
    def node_exclusion_predicate(node: BaseEntity) -> bool:
        """Return true if the node is not in the given set of nodes."""
        return node not in nodes
    return node_exclusion_predicate

def node_inclusion_predicate_builder(nodes: Iterable[BaseEntity]) -> NodePredicate:
    """Build a function that returns true for the given nodes."""
    nodes = set(nodes)
    @node_predicate
    def node_inclusion_predicate(node: BaseEntity) -> bool:
        """Return true if the node is in the given set of nodes."""
        return node in nodes
    return node_inclusion_predicate

def is_causal_source(graph: BELGraph, node: BaseEntity) -> bool:
    """Return true of the node is a causal source.

    - Doesn't have any causal in edge(s)
    - Does have causal out edge(s)"""
    return not has_causal_in_edges(graph, node) and has_causal_out_edges(graph, node)

def is_causal_sink(graph: BELGraph, node: BaseEntity) -> bool:
    """Return true if the node is a causal sink.

    - Does have causal in edge(s)
    - Doesn't have any causal out edge(s)"""
    return has_causal_in_edges(graph, node) and (not has_causal_out_edges(graph, node))

def is_causal_central(graph: BELGraph, node: BaseEntity) -> bool:
    """Return true if the node is neither a causal sink nor a causal source.

    - Does have causal in edges(s)
    - Does have causal out edge(s)"""
    return has_causal_in_edges(graph, node) and has_causal_out_edges(graph, node)

def is_isolated_list_abundance(graph: BELGraph, node: BaseEntity, cls: Type[ListAbundance]=ListAbundance) -> bool:
    """Return if the node is a list abundance but has no qualified edges."""
    return isinstance(node, cls) and 0 == graph.in_degree(node) and all((data[RELATION] == HAS_COMPONENT for _, __, data in graph.out_edges(node, data=True)))

def collapse_nodes(graph, survivor_mapping: Mapping[BaseEntity, Set[BaseEntity]]) -> None:
    """Collapse all nodes in values to the key nodes, in place.

    :param pybel.BELGraph graph: A BEL graph
    :param survivor_mapping: A dictionary with survivors as their keys, and iterables of the corresponding victims as
     values."""
    inconsistencies = surviors_are_inconsistent(survivor_mapping)
    if inconsistencies:
        raise ValueError('survivor mapping is inconsistent: {}'.format(inconsistencies))
    for survivor, victims in survivor_mapping.items():
        for victim in victims:
            collapse_pair(graph, survivor=survivor, victim=victim)
    _remove_self_edges(graph)

def surviors_are_inconsistent(survivor_mapping: Mapping[BaseEntity, Set[BaseEntity]]) -> Set[BaseEntity]:
    """Check that there's no transitive shit going on."""
    victim_mapping = set()
    for victim in itt.chain.from_iterable(survivor_mapping.values()):
        if victim in survivor_mapping:
            victim_mapping.add(victim)
    return victim_mapping

def update_metadata(source, target) -> None:
    """Update the namespace and annotation metadata in the target graph.

    :param pybel.BELGraph source:
    :param pybel.BELGraph target:"""
    target.namespace_url.update(source.namespace_url)
    target.namespace_pattern.update(source.namespace_pattern)
    target.annotation_url.update(source.annotation_url)
    target.annotation_pattern.update(source.annotation_pattern)
    for keyword, values in source.annotation_list.items():
        if keyword not in target.annotation_list:
            target.annotation_list[keyword] = values
        else:
            target.annotation_list[keyword].update(values)

def update_node_helper(source: nx.Graph, target: nx.Graph) -> None:
    """Update the nodes' data dictionaries in the target graph from the source graph.

    :param source: The universe of all knowledge
    :param target: The target BEL graph"""
    for node in target:
        if node in source:
            target.nodes[node].update(source.nodes[node])

def get_syntax_errors(graph: BELGraph) -> List[WarningTuple]:
    """List the syntax errors encountered during compilation of a BEL script."""
    return [(path, exc, an) for path, exc, an in graph.warnings if isinstance(exc, BELSyntaxError)]

def count_error_types(graph: BELGraph) -> Counter:
    """Count the occurrence of each type of error in a graph.

    :return: A Counter of {error type: frequency}"""
    return Counter((exc.__class__.__name__ for _, exc, _ in graph.warnings))

def _naked_names_iter(graph: BELGraph) -> Iterable[str]:
    """Iterate over naked name warnings from a graph."""
    for _, exc, _ in graph.warnings:
        if isinstance(exc, NakedNameWarning):
            yield exc.name

def calculate_incorrect_name_dict(graph: BELGraph) -> Mapping[str, List[str]]:
    """Get missing names grouped by namespace."""
    missing = defaultdict(list)
    for namespace, name in _iterate_namespace_name(graph):
        missing[namespace].append(name)
    return dict(missing)

def calculate_error_by_annotation(graph: BELGraph, annotation: str) -> Mapping[str, List[str]]:
    """Group error names by a given annotation."""
    results = defaultdict(list)
    for _, exc, ctx in graph.warnings:
        if not ctx or not edge_has_annotation(ctx, annotation):
            continue
        values = ctx[ANNOTATIONS][annotation]
        if isinstance(values, str):
            results[values].append(exc.__class__.__name__)
        elif isinstance(values, Iterable):
            for value in values:
                results[value].append(exc.__class__.__name__)
    return dict(results)

def get_subgraph_by_induction(graph, nodes: Iterable[BaseEntity]):
    """Induce a sub-graph over the given nodes or return None if none of the nodes are in the given graph.

    :param pybel.BELGraph graph: A BEL graph
    :param nodes: A list of BEL nodes in the graph
    :rtype: Optional[pybel.BELGraph]"""
    nodes = tuple(nodes)
    if all((node not in graph for node in nodes)):
        return
    return subgraph(graph, nodes)

def _normalize_url(graph: BELGraph, keyword: str) -> Optional[str]:
    """Normalize a URL for the BEL graph."""
    if keyword == BEL_DEFAULT_NAMESPACE and BEL_DEFAULT_NAMESPACE not in graph.namespace_url:
        return BEL_DEFAULT_NAMESPACE_URL
    return graph.namespace_url.get(keyword)

def _clean_annotations(annotations_dict: AnnotationsHint) -> AnnotationsDict:
    """Fix the formatting of annotation dict."""
    return {key: values if isinstance(values, dict) else {v: True for v in values} if isinstance(values, set) else {values: True} for key, values in annotations_dict.items()}

def chebi(name=None, identifier=None) -> Abundance:
    """Build a ChEBI abundance node."""
    return Abundance(namespace='CHEBI', name=name, identifier=identifier)

def hgnc(name=None, identifier=None) -> Protein:
