    return Protein(namespace='HGNC', name=name, identifier=identifier)

def sanitize_date(publication_date: str) -> str:
    """Sanitize lots of different date strings into ISO-8601."""
    if re1.search(publication_date):
        return datetime.strptime(publication_date, '%Y %b %d').strftime('%Y-%m-%d')
    if re2.search(publication_date):
        return datetime.strptime(publication_date, '%Y %b').strftime('%Y-%m-01')
    if re3.search(publication_date):
        return publication_date + '-01-01'
    if re4.search(publication_date):
        return datetime.strptime(publication_date[:-4], '%Y %b').strftime('%Y-%m-01')
    s = re5.search(publication_date)
    if s:
        year, season = s.groups()
        return '{}-{}-01'.format(year, season_map[season])
    s = re6.search(publication_date)
    if s:
        return datetime.strptime(publication_date, '%Y %b %d-{}'.format(s.groups()[0])).strftime('%Y-%m-%d')
    s = re7.search(publication_date)
    if s:
        return datetime.strptime(publication_date, '%Y %b %d-{}'.format(s.groups()[0])).strftime('%Y-%m-%d')

def clean_pubmed_identifiers(pmids: Iterable[str]) -> List[str]:
    """Clean a list of PubMed identifiers with string strips, deduplicates, and sorting."""
    return sorted({str(pmid).strip() for pmid in pmids})

def _build_collapse_to_gene_dict(graph) -> Dict[BaseEntity, Set[BaseEntity]]:
    """Build a collapse dictionary.

    :param pybel.BELGraph graph: A BEL graph
    :return: A dictionary of {node: set of PyBEL node tuples}"""
    collapse_dict = defaultdict(set)
    r2g = {}
    for gene_node, rna_node, d in graph.edges(data=True):
        if d[RELATION] != TRANSCRIBED_TO:
            continue
        collapse_dict[gene_node].add(rna_node)
        r2g[rna_node] = gene_node
    for rna_node, protein_node, d in graph.edges(data=True):
        if d[RELATION] != TRANSLATED_TO:
            continue
        if rna_node not in r2g:
            raise ValueError('Should complete origin before running this function')
        collapse_dict[r2g[rna_node]].add(protein_node)
    return collapse_dict

def insert(manager, graph: BELGraph):
    """Insert a graph to the database."""
    to_database(graph, manager=manager, use_tqdm=True)

def serialize(graph: BELGraph, csv, sif, gsea, graphml, json, bel):
    """Serialize a graph to various formats."""
    if csv:
        log.info('Outputting CSV to %s', csv)
        to_csv(graph, csv)
    if sif:
        log.info('Outputting SIF to %s', sif)
        to_sif(graph, sif)
    if graphml:
        log.info('Outputting GraphML to %s', graphml)
        to_graphml(graph, graphml)
    if gsea:
        log.info('Outputting GRP to %s', gsea)
        to_gsea(graph, gsea)
    if json:
        log.info('Outputting JSON to %s', json)
        to_json_file(graph, json)
    if bel:
        log.info('Outputting BEL to %s', bel)
        to_bel(graph, bel)

