def parse_result_to_dsl(tokens):
    """Convert a ParseResult to a PyBEL DSL object.

    :type tokens: dict or pyparsing.ParseResults
    :rtype: BaseEntity"""
    if MODIFIER in tokens:
        return parse_result_to_dsl(tokens[TARGET])
    elif REACTION == tokens[FUNCTION]:
        return _reaction_po_to_dict(tokens)
    elif VARIANTS in tokens:
        return _variant_po_to_dict(tokens)
    elif MEMBERS in tokens:
        return _list_po_to_dict(tokens)
    elif FUSION in tokens:
        return _fusion_to_dsl(tokens)
    return _simple_po_to_dict(tokens)

def _fusion_range_to_dsl(tokens) -> FusionRangeBase:
    """Convert a PyParsing data dictionary into a PyBEL.

    :type tokens: ParseResult"""
    if FUSION_MISSING in tokens:
        return missing_fusion_range()
    return fusion_range(reference=tokens[FUSION_REFERENCE], start=tokens[FUSION_START], stop=tokens[FUSION_STOP])

def _simple_po_to_dict(tokens) -> BaseAbundance:
    """Convert a simple named entity to a DSL object.

    :type tokens: ParseResult"""
    dsl = FUNC_TO_DSL.get(tokens[FUNCTION])
    if dsl is None:
        raise ValueError('invalid tokens: {}'.format(tokens))
    return dsl(namespace=tokens[NAMESPACE], name=tokens.get(NAME), identifier=tokens.get(IDENTIFIER))

def _variant_po_to_dict(tokens) -> CentralDogma:
    """Convert a PyParsing data dictionary to a central dogma abundance (i.e., Protein, RNA, miRNA, Gene).

    :type tokens: ParseResult"""
    dsl = FUNC_TO_DSL.get(tokens[FUNCTION])
    if dsl is None:
        raise ValueError('invalid tokens: {}'.format(tokens))
    return dsl(namespace=tokens[NAMESPACE], name=tokens[NAME], variants=[_variant_to_dsl_helper(variant_tokens) for variant_tokens in tokens[VARIANTS]])

def _variant_to_dsl_helper(tokens) -> Variant:
    """Convert variant tokens to DSL objects.

    :type tokens: ParseResult"""
    kind = tokens[KIND]
    if kind == HGVS:
        return hgvs(tokens[IDENTIFIER])
    if kind == GMOD:
        return gmod(name=tokens[IDENTIFIER][NAME], namespace=tokens[IDENTIFIER][NAMESPACE])
    if kind == PMOD:
        return pmod(name=tokens[IDENTIFIER][NAME], namespace=tokens[IDENTIFIER][NAMESPACE], code=tokens.get(PMOD_CODE), position=tokens.get(PMOD_POSITION))
    if kind == FRAGMENT:
        start, stop = (tokens.get(FRAGMENT_START), tokens.get(FRAGMENT_STOP))
        return fragment(start=start, stop=stop, description=tokens.get(FRAGMENT_DESCRIPTION))
    raise ValueError('invalid fragment kind: {}'.format(kind))

def _reaction_po_to_dict(tokens) -> Reaction:
    """Convert a reaction parse object to a DSL.

    :type tokens: ParseResult"""
    return Reaction(reactants=_reaction_part_po_to_dict(tokens[REACTANTS]), products=_reaction_part_po_to_dict(tokens[PRODUCTS]))

def get_subgraph_by_annotation_value(graph, annotation, values):
    """Induce a sub-graph over all edges whose annotations match the given key and value.

    :param pybel.BELGraph graph: A BEL graph
    :param str annotation: The annotation to group by
    :param values: The value(s) for the annotation
    :type values: str or iter[str]
    :return: A subgraph of the original BEL graph
    :rtype: pybel.BELGraph"""
    if isinstance(values, str):
        values = {values}
    return get_subgraph_by_annotations(graph, {annotation: values})

def invert_edge_predicate(edge_predicate: EdgePredicate) -> EdgePredicate:
    """Build an edge predicate that is the inverse of the given edge predicate."""
    def _inverse_filter(graph, u, v, k):
        return not edge_predicate(graph, u, v, k)
    return _inverse_filter

def and_edge_predicates(edge_predicates: EdgePredicates) -> EdgePredicate:
    """Concatenate multiple edge predicates to a new predicate that requires all predicates to be met."""
    if not isinstance(edge_predicates, Iterable):
        return edge_predicates
    edge_predicates = tuple(edge_predicates)
    if 1 == len(edge_predicates):
        return edge_predicates[0]
    def concatenated_edge_predicate(graph: BELGraph, u: BaseEntity, v: BaseEntity, k: str) -> bool:
        """Pass only for an edge that pass all enclosed predicates.

        :return: If the edge passes all enclosed predicates"""
        return all((edge_predicate(graph, u, v, k) for edge_predicate in edge_predicates))
    return concatenated_edge_predicate

def filter_edges(graph: BELGraph, edge_predicates: EdgePredicates) -> EdgeIterator:
    """Apply a set of filters to the edges iterator of a BEL graph.

    :return: An iterable of edges that pass all predicates"""
    compound_edge_predicate = and_edge_predicates(edge_predicates=edge_predicates)
    for u, v, k in graph.edges(keys=True):
        if compound_edge_predicate(graph, u, v, k):
            yield (u, v, k)

def count_passed_edge_filter(graph: BELGraph, edge_predicates: EdgePredicates) -> int:
    """Return the number of edges passing a given set of predicates."""
    return sum((1 for _ in filter_edges(graph, edge_predicates=edge_predicates)))

def strip_annotations(graph):
    """Strip all the annotations from a BEL graph.

    :param pybel.BELGraph graph: A BEL graph"""
    for u, v, k in graph.edges(keys=True):
        if ANNOTATIONS in graph[u][v][k]:
            del graph[u][v][k][ANNOTATIONS]

def add_annotation_value(graph, annotation, value):
    """Add the given annotation/value pair to all qualified edges.

    :param pybel.BELGraph graph:
    :param str annotation:
    :param str value:"""
    if annotation not in graph.defined_annotation_keywords:
        raise ValueError('annotation not defined: {}'.format(annotation))
    for u, v, k in graph.edges(keys=True):
        if ANNOTATIONS not in graph[u][v][k]:
            continue
        if annotation not in graph[u][v][k][ANNOTATIONS]:
            graph[u][v][k][ANNOTATIONS][annotation] = {}
        graph[u][v][k][ANNOTATIONS][annotation][value] = True

def remove_annotation_value(graph, annotation, value):
    """Remove the given annotation/value pair to all qualified edges.

    :param pybel.BELGraph graph:
    :param str annotation:
    :param str value:"""
    if annotation not in graph.defined_annotation_keywords:
        log.warning('annotation was not defined: %s', annotation)
        return
    for u, v, k in graph.edges(keys=True):
        if ANNOTATIONS not in graph[u][v][k]:
            continue
        if annotation not in graph[u][v][k][ANNOTATIONS]:
            continue
        if value not in graph[u][v][k][ANNOTATIONS][annotation]:
            continue
        del graph[u][v][k][ANNOTATIONS][annotation][value]

def remove_citation_metadata(graph):
    """Remove the metadata associated with a citation.

    Best practice is to add this information programmatically."""
    for u, v, k in graph.edges(keys=True):
        if CITATION not in graph[u][v][k]:
            continue
        for key in list(graph[u][v][k][CITATION]):
            if key not in _CITATION_KEEP_KEYS:
                del graph[u][v][k][CITATION][key]

def to_json(graph: BELGraph) -> Mapping[str, Any]:
    """Convert this graph to a Node-Link JSON object."""
    graph_json_dict = node_link_data(graph)
    graph_json_dict['graph'][GRAPH_ANNOTATION_LIST] = {keyword: list(sorted(values)) for keyword, values in graph_json_dict['graph'].get(GRAPH_ANNOTATION_LIST, {}).items()}
    graph_json_dict['graph'][GRAPH_UNCACHED_NAMESPACES] = list(graph_json_dict['graph'].get(GRAPH_UNCACHED_NAMESPACES, []))
    return graph_json_dict

def to_jsons(graph: BELGraph, **kwargs) -> str:
    """Dump this graph as a Node-Link JSON object to a string."""
    graph_json_str = to_json(graph)
    return json.dumps(graph_json_str, ensure_ascii=False, **kwargs)

def from_json(graph_json_dict: Mapping[str, Any], check_version=True) -> BELGraph:
    """Build a graph from Node-Link JSON Object."""
    graph = node_link_graph(graph_json_dict)
    return ensure_version(graph, check_version=check_version)

def from_json_path(path: str, check_version: bool=True) -> BELGraph:
    """Build a graph from a file containing Node-Link JSON."""
    with open(os.path.expanduser(path)) as f:
        return from_json_file(f, check_version=check_version)

def from_json_file(file: TextIO, check_version=True) -> BELGraph:
    """Build a graph from the Node-Link JSON contained in the given file."""
    graph_json_dict = json.load(file)
    return from_json(graph_json_dict, check_version=check_version)

def from_jsons(graph_json_str: str, check_version: bool=True) -> BELGraph:
    """Read a BEL graph from a Node-Link JSON string."""
    graph_json_dict = json.loads(graph_json_str)
    return from_json(graph_json_dict, check_version=check_version)

def node_link_data(graph: BELGraph) -> Mapping[str, Any]:
    """Convert a BEL graph to a node-link format.

    Adapted from :func:`networkx.readwrite.json_graph.node_link_data`"""
    nodes = sorted(graph, key=methodcaller('as_bel'))
    mapping = dict(zip(nodes, count()))
    return {'directed': True, 'multigraph': True, 'graph': graph.graph.copy(), 'nodes': [_augment_node(node) for node in nodes], 'links': [dict(chain(data.copy().items(), [('source', mapping[u]), ('target', mapping[v]), ('key', key)])) for u, v, key, data in graph.edges(keys=True, data=True)]}

def iter_children(graph, node: BaseEntity) -> Iterable[BaseEntity]:
    """Iterate over children of the node."""
    return (node for node, _, d in graph.in_edges(node, data=True) if d[RELATION] == IS_A)

def transfer_causal_edges(graph, source: BaseEntity, target: BaseEntity) -> Iterable[str]:
    """Transfer causal edges that the source has to the target and yield the resulting hashes."""
    for _, v, data in graph.out_edges(source, data=True):
        if data[RELATION] not in CAUSAL_RELATIONS:
            continue
        yield graph.add_qualified_edge(target, v, relation=data[RELATION], evidence=data[EVIDENCE], citation=data[CITATION], annotations=data.get(ANNOTATIONS), subject_modifier=data.get(SUBJECT), object_modifier=data.get(OBJECT))
    for u, _, data in graph.in_edges(source, data=True):
        if data[RELATION] not in CAUSAL_RELATIONS:
            continue
        yield graph.add_qualified_edge(u, target, relation=data[RELATION], evidence=data[EVIDENCE], citation=data[CITATION], annotations=data.get(ANNOTATIONS), subject_modifier=data.get(SUBJECT), object_modifier=data.get(OBJECT))

def infer_child_relations(graph, node: BaseEntity) -> List[str]:
    """Propagate causal relations to children."""
    return list(_infer_child_relations_iter(graph, node))

def _infer_child_relations_iter(graph, node: BaseEntity) -> Iterable[str]:
    """Propagate causal relations to children."""
    for child in iter_children(graph, node):
        yield from transfer_causal_edges(graph, node, child)
        yield from infer_child_relations(graph, child)

def _get_protocol_tuple(data: Dict[str, Any]) -> Tuple[str, List, Dict]:
    """Convert a dictionary to a tuple."""
    return (data['function'], data.get('args', []), data.get('kwargs', {}))

def get_names(graph):
    """Get all names for each namespace.

    :type graph: pybel.BELGraph
    :rtype: dict[str,set[str]]"""
    rv = defaultdict(set)
    for namespace, name in _identifier_filtered_iterator(graph):
        rv[namespace].add(name)
    return dict(rv)

def _identifier_filtered_iterator(graph):
    """Iterate over names in the given namespace."""
    for data in graph:
        for pair in _get_node_names(data):
            yield pair
        for member in data.get(MEMBERS, []):
            for pair in _get_node_names(member):
                yield pair
    for (_, _, data), side in itt.product(graph.edges(data=True), (SUBJECT, OBJECT)):
        side_data = data.get(side)
        if side_data is None:
            continue
        modifier = side_data.get(MODIFIER)
        effect = side_data.get(EFFECT)
        if modifier == ACTIVITY and effect is not None and (NAMESPACE in effect) and (NAME in effect):
            yield (effect[NAMESPACE], effect[NAME])
        elif modifier == TRANSLOCATION and effect is not None:
            from_loc = effect.get(FROM_LOC)
            if NAMESPACE in from_loc and NAME in from_loc:
                yield (from_loc[NAMESPACE], from_loc[NAME])
            to_loc = effect.get(TO_LOC)
            if NAMESPACE in to_loc and NAME in to_loc:
                yield (to_loc[NAMESPACE], to_loc[NAME])
        location = side_data.get(LOCATION)
        if location is not None and NAMESPACE in location and (NAME in location):
            yield (location[NAMESPACE], location[NAME])

def _namespace_filtered_iterator(graph, namespace):
    """Iterate over names in the given namespace."""
    for it_namespace, name in _identifier_filtered_iterator(graph):
        if namespace == it_namespace:
            yield name

def count_names_by_namespace(graph, namespace):
    """Get the set of all of the names in a given namespace that are in the graph.

    :param pybel.BELGraph graph: A BEL graph
    :param str namespace: A namespace keyword
    :return: A counter from {name: frequency}
    :rtype: collections.Counter

    :raises IndexError: if the namespace is not defined in the graph."""
    if namespace not in graph.defined_namespace_keywords:
        raise IndexError('{} is not defined in {}'.format(namespace, graph))
    return Counter(_namespace_filtered_iterator(graph, namespace))

def get_names_by_namespace(graph, namespace):
    """Get the set of all of the names in a given namespace that are in the graph.

    :param pybel.BELGraph graph: A BEL graph
    :param str namespace: A namespace keyword
    :return: A set of names belonging to the given namespace that are in the given graph
    :rtype: set[str]

    :raises IndexError: if the namespace is not defined in the graph."""
    if namespace not in graph.defined_namespace_keywords:
        raise IndexError('{} is not defined in {}'.format(namespace, graph))
    return set(_namespace_filtered_iterator(graph, namespace))

def count_variants(graph):
    """Count how many of each type of variant a graph has.

    :param pybel.BELGraph graph: A BEL graph
    :rtype: Counter"""
    return Counter((variant_data[KIND] for data in graph if has_variant(graph, data) for variant_data in data[VARIANTS]))

def get_top_hubs(graph, *, n: Optional[int]=15) -> List[Tuple[BaseEntity, int]]:
    """Get the top hubs in the graph by BEL.

    :param pybel.BELGraph graph: A BEL graph
    :param n: The number of top hubs to return. If None, returns all nodes"""
    return Counter(dict(graph.degree())).most_common(n=n)

def _pathology_iterator(graph):
    """Iterate over edges in which either the source or target is a pathology node.

    :param pybel.BELGraph graph: A BEL graph
    :rtype: iter"""
    for node in itt.chain.from_iterable(graph.edges()):
        if isinstance(node, Pathology):
            yield node

def get_top_pathologies(graph, n: Optional[int]=15) -> List[Tuple[BaseEntity, int]]:
    """Get the top highest relationship-having edges in the graph by BEL.

    :param pybel.BELGraph graph: A BEL graph
    :param n: The number of top connected pathologies to return. If None, returns all nodes"""
    return count_pathologies(graph).most_common(n)

def enrich_proteins_with_rnas(graph):
    """Add the corresponding RNA node for each protein node and connect them with a translation edge.

    :param pybel.BELGraph graph: A BEL graph"""
    for protein_node in list(graph):
        if not isinstance(protein_node, Protein):
            continue
        if protein_node.variants:
            continue
        rna_node = protein_node.get_rna()
        graph.add_translation(rna_node, protein_node)

def enrich_rnas_with_genes(graph):
    """Add the corresponding gene node for each RNA/miRNA node and connect them with a transcription edge.

    :param pybel.BELGraph graph: A BEL graph"""
    for rna_node in list(graph):
        if rna_node[FUNCTION] not in {MIRNA, RNA} or FUSION in rna_node or VARIANTS in rna_node:
            continue
        gene_node = rna_node.get_gene()
        graph.add_transcription(gene_node, rna_node)

def get_upstream_causal_subgraph(graph, nbunch: Union[BaseEntity, Iterable[BaseEntity]]):
    """Induce a sub-graph from all of the upstream causal entities of the nodes in the nbunch.

    :type graph: pybel.BELGraph
    :rtype: pybel.BELGraph"""
    return get_subgraph_by_edge_filter(graph, build_upstream_edge_predicate(nbunch))

def get_downstream_causal_subgraph(graph, nbunch: Union[BaseEntity, Iterable[BaseEntity]]):
    """Induce a sub-graph from all of the downstream causal entities of the nodes in the nbunch.

    :type graph: pybel.BELGraph
    :rtype: pybel.BELGraph"""
    return get_subgraph_by_edge_filter(graph, build_downstream_edge_predicate(nbunch))

def get_nodes_by_function(graph: BELGraph, func: Strings) -> Set[BaseEntity]:
    """Get all nodes with the given function(s)."""
    return get_nodes(graph, function_inclusion_filter_builder(func))

def get_nodes_by_namespace(graph: BELGraph, namespaces: Strings) -> Set[BaseEntity]:
    """Get all nodes identified by the given namespace(s)."""
    return get_nodes(graph, namespace_inclusion_builder(namespaces))

def get_protein_modification_language(identifier_qualified: ParserElement) -> ParserElement:
    """Build a protein modification parser."""
    pmod_identifier = MatchFirst([identifier_qualified, pmod_default_ns, pmod_legacy_ns])
    return pmod_tag + nest(Group(pmod_identifier)(IDENTIFIER) + Optional(WCW + amino_acid(PMOD_CODE) + Optional(WCW + ppc.integer(PMOD_POSITION))))

def _activity_helper(modifier: str, location=None):
    """Make an activity dictionary.

    :param str modifier:
    :param Optional[dict] location: An entity from :func:`pybel.dsl.entity`
    :rtype: dict"""
    rv = {MODIFIER: modifier}
    if location:
        rv[LOCATION] = location
    return rv

def iterate_pubmed_identifiers(graph) -> Iterable[str]:
    """Iterate over all PubMed identifiers in a graph.

    :param pybel.BELGraph graph: A BEL graph
    :return: An iterator over the PubMed identifiers in the graph"""
    return (data[CITATION][CITATION_REFERENCE].strip() for _, _, data in graph.edges(data=True) if has_pubmed(data))

def get_gene_modification_language(identifier_qualified: ParserElement) -> ParserElement:
    """Build a gene modification parser."""
    gmod_identifier = MatchFirst([identifier_qualified, gmod_default_ns])
    return gmod_tag + nest(Group(gmod_identifier)(IDENTIFIER))

def expand_dict(flat_dict, sep='_'):
    """Expand a flattened dictionary.

    :param dict flat_dict: a nested dictionary that has been flattened so the keys are composite
    :param str sep: the separator between concatenated keys
    :rtype: dict"""
    res = {}
    rdict = defaultdict(list)
    for flat_key, value in flat_dict.items():
        key = flat_key.split(sep, 1)
        if 1 == len(key):
            res[key[0]] = value
        else:
            rdict[key[0]].append((key[1:], value))
    for k, v in rdict.items():
        res[k] = expand_dict({ik: iv for (ik,), iv in v})
    return res

def flatten_dict(data, parent_key='', sep='_'):
    """Flatten a nested dictionary.

    :param data: A nested dictionary
    :type data: dict or MutableMapping
    :param str parent_key: The parent's key. This is a value for tail recursion, so don't set it yourself.
    :param str sep: The separator used between dictionary levels
    :rtype: dict

    .. seealso:: http://stackoverflow.com/a/6027615"""
    items = {}
    for key, value in data.items():
        key = parent_key + sep + key if parent_key else key
        if isinstance(value, (dict, MutableMapping)):
            items.update(flatten_dict(value, key, sep=sep))
        elif isinstance(value, (set, list)):
            items[key] = ','.join(value)
        else:
            items[key] = value
    return items

def hash_dump(data) -> str:
    """Hash an arbitrary JSON dictionary by dumping it in sorted order, encoding it in UTF-8, then hashing the bytes.

    :param data: An arbitrary JSON-serializable object
    :type data: dict or list or tuple"""
    return hashlib.sha512(json.dumps(data, sort_keys=True).encode('utf-8')).hexdigest()

def hash_citation(type: str, reference: str) -> str:
    """Create a hash for a type/reference pair of a citation.

    :param type: The corresponding citation type
    :param reference: The citation reference"""
    s = u'{type}:{reference}'.format(type=type, reference=reference)
    return hashlib.sha512(s.encode('utf8')).hexdigest()

def canonicalize_edge(edge_data: EdgeData) -> Tuple[str, Optional[Tuple], Optional[Tuple]]:
    """Canonicalize the edge to a tuple based on the relation, subject modifications, and object modifications."""
    return (edge_data[RELATION], _canonicalize_edge_modifications(edge_data.get(SUBJECT)), _canonicalize_edge_modifications(edge_data.get(OBJECT)))

def get_subgraphs_by_citation(graph):
    """Stratify the graph based on citations.

    :type graph: pybel.BELGraph
    :rtype: dict[tuple[str,str],pybel.BELGraph]"""
    rv = defaultdict(graph.fresh_copy)
    for u, v, key, data in graph.edges(keys=True, data=True):
        if CITATION not in data:
            continue
        dk = (data[CITATION][CITATION_TYPE], data[CITATION][CITATION_REFERENCE])
        rv[dk].add_edge(u, v, key=key, **data)
    cleanup(graph, rv)
    return dict(rv)

def get_random_path(graph) -> List[BaseEntity]:
    """Get a random path from the graph as a list of nodes.

    :param pybel.BELGraph graph: A BEL graph"""
    wg = graph.to_undirected()
    nodes = wg.nodes()
    def pick_random_pair() -> Tuple[BaseEntity, BaseEntity]:
        """Get a pair of random nodes."""
        return random.sample(nodes, k=2)
    source, target = pick_random_pair()
    tries = 0
    sentinel_tries = 5
    while not nx.has_path(wg, source, target) and tries < sentinel_tries:
        tries += 1
        source, target = pick_random_pair()
    if tries == sentinel_tries:
        return [source]
    return nx.shortest_path(wg, source=source, target=target)

def _annotation_dict_all_filter(edge_data: EdgeData, query: Mapping[str, Iterable[str]]) -> bool:
    """Match edges with the given dictionary as a sub-dictionary.

    :param query: The annotation query dict to match"""
    annotations = edge_data.get(ANNOTATIONS)
    if annotations is None:
        return False
    for key, values in query.items():
        ak = annotations.get(key)
        if ak is None:
            return False
        for value in values:
            if value not in ak:
                return False
    return True

def build_annotation_dict_all_filter(annotations: Mapping[str, Iterable[str]]) -> EdgePredicate:
    """Build an edge predicate for edges whose annotations are super-dictionaries of the given dictionary.

    If no annotations are given, will always evaluate to true.

    :param annotations: The annotation query dict to match"""
    if not annotations:
        return keep_edge_permissive
    @edge_predicate
    def annotation_dict_all_filter(edge_data: EdgeData) -> bool:
        """Check if the all of the annotations in the enclosed query match."""
        return _annotation_dict_all_filter(edge_data, query=annotations)
    return annotation_dict_all_filter

def _annotation_dict_any_filter(edge_data: EdgeData, query: Mapping[str, Iterable[str]]) -> bool:
    """Match edges with the given dictionary as a sub-dictionary.

    :param query: The annotation query dict to match"""
    annotations = edge_data.get(ANNOTATIONS)
    if annotations is None:
        return False
    return any((key in annotations and value in annotations[key] for key, values in query.items() for value in values))

def build_annotation_dict_any_filter(annotations: Mapping[str, Iterable[str]]) -> EdgePredicate:
    """Build an edge predicate that passes for edges whose data dictionaries match the given dictionary.

    If the given dictionary is empty, will always evaluate to true.

    :param annotations: The annotation query dict to match"""
    if not annotations:
        return keep_edge_permissive
    @edge_predicate
    def annotation_dict_any_filter(edge_data: EdgeData) -> bool:
        """Check if the any of the annotations in the enclosed query match."""
        return _annotation_dict_any_filter(edge_data, query=annotations)
    return annotation_dict_any_filter

def build_relation_predicate(relations: Strings) -> EdgePredicate:
    """Build an edge predicate that passes for edges with the given relation."""
    if isinstance(relations, str):
        @edge_predicate
        def relation_predicate(edge_data: EdgeData) -> bool:
            """Pass for relations matching the enclosed value."""
            return edge_data[RELATION] == relations
    elif isinstance(relations, Iterable):
        relation_set = set(relations)
        @edge_predicate
        def relation_predicate(edge_data: EdgeData) -> bool:
            """Pass for relations matching the enclosed values."""
            return edge_data[RELATION] in relation_set
    else:
        raise TypeError
    return relation_predicate

def build_pmid_inclusion_filter(pmids: Strings) -> EdgePredicate:
    """Build an edge predicate that passes for edges with citations from the given PubMed identifier(s).

    :param pmids: A PubMed identifier or list of PubMed identifiers to filter for"""
    if isinstance(pmids, str):
        @edge_predicate
        def pmid_inclusion_filter(edge_data: EdgeData) -> bool:
            """Pass for edges with PubMed citations matching the contained PubMed identifier."""
            return has_pubmed(edge_data) and edge_data[CITATION][CITATION_REFERENCE] == pmids
    elif isinstance(pmids, Iterable):
        pmids = set(pmids)
        @edge_predicate
        def pmid_inclusion_filter(edge_data: EdgeData) -> bool:
            """Pass for edges with PubMed citations matching one of the contained PubMed identifiers."""
            return has_pubmed(edge_data) and edge_data[CITATION][CITATION_REFERENCE] in pmids
    else:
        raise TypeError
    return pmid_inclusion_filter

def build_author_inclusion_filter(authors: Strings) -> EdgePredicate:
    """Build an edge predicate that passes for edges with citations written by the given author(s)."""
    if isinstance(authors, str):
        @edge_predicate
        def author_filter(edge_data: EdgeData) -> bool:
            """Pass for edges with citations with an author that matches the contained author."""
            return has_authors(edge_data) and authors in edge_data[CITATION][CITATION_AUTHORS]
    elif isinstance(authors, Iterable):
        authors = set(authors)
        @edge_predicate
        def author_filter(edge_data: EdgeData) -> bool:
            """Pass for edges with citations with an author that matches one or more of the contained authors."""
            return has_authors(edge_data) and any((author in edge_data[CITATION][CITATION_AUTHORS] for author in authors))
    else:
        raise TypeError
    return author_filter

def _register_function(name: str, func, universe: bool, in_place: bool):
    """Register a transformation function under the given name.

    :param name: Name to register the function under
    :param func: A function
    :param universe:
    :param in_place:
    :return: The same function, with additional properties added"""
    if name in mapped:
        mapped_func = mapped[name]
        raise PipelineNameError('{name} is already registered with {func_mod}.{func_name}'.format(name=name, func_mod=mapped_func.__module__, func_name=mapped_func.__name__))
    mapped[name] = func
    if universe:
        universe_map[name] = func
    if in_place:
        in_place_map[name] = func
    if _has_arguments(func, universe):
        has_arguments_map[name] = func
    else:
        no_arguments_map[name] = func
    return func

def _build_register_function(universe: bool, in_place: bool):
    """Build a decorator function to tag transformation functions.

    :param universe: Does the first positional argument of this function correspond to a universe graph?
    :param in_place: Does this function return a new graph, or just modify it in-place?"""
    def register(func):
        """Tag a transformation function.

        :param func: A function
        :return: The same function, with additional properties added"""
        return _register_function(func.__name__, func, universe, in_place)
    return register

def get_transformation(name: str):
    """Get a transformation function and error if its name is not registered.

    :param name: The name of a function to look up
    :return: A transformation function
    :raises MissingPipelineFunctionError: If the given function name is not registered"""
    func = mapped.get(name)
    if func is None:
        raise MissingPipelineFunctionError('{} is not registered as a pipeline function'.format(name))
    return func

def get_random_node(graph, node_blacklist: Set[BaseEntity], invert_degrees: Optional[bool]=None) -> Optional[BaseEntity]:
    """Choose a node from the graph with probabilities based on their degrees.

    :type graph: networkx.Graph
    :param node_blacklist: Nodes to filter out
    :param invert_degrees: Should the degrees be inverted? Defaults to true."""
    try:
        nodes, degrees = zip(*((node, degree) for node, degree in sorted(graph.degree(), key=itemgetter(1)) if node not in node_blacklist))
    except ValueError:
        return
    if invert_degrees is None or invert_degrees:
        degrees = [1 / degree for degree in degrees]
    wrg = WeightedRandomGenerator(nodes, degrees)
    return wrg.next()

def raise_for_old_graph(graph):
    """Raise an ImportVersionWarning if the BEL graph was produced by a legacy version of PyBEL.

    :raises ImportVersionWarning: If the BEL graph was produced by a legacy version of PyBEL"""
    graph_version = tokenize_version(graph.pybel_version)
    if graph_version < PYBEL_MINIMUM_IMPORT_VERSION:
        raise ImportVersionWarning(graph_version, PYBEL_MINIMUM_IMPORT_VERSION)

def nest(*content):
    """Define a delimited list by enumerating each element of the list."""
    if len(content) == 0:
        raise ValueError('no arguments supplied')
    return And([LPF, content[0]] + list(itt.chain.from_iterable(zip(itt.repeat(C), content[1:]))) + [RPF])

def triple(subject, relation, obj):
    """Build a simple triple in PyParsing that has a ``subject relation object`` format."""
    return And([Group(subject)(SUBJECT), relation(RELATION), Group(obj)(OBJECT)])

def docstring_to_markdown(docstring):
    """Convert a Python object's docstring to markdown

    Parameters
    ----------
    docstring : str
        The docstring body.

    Returns
    ----------
    clean_lst : list
        The markdown formatted docstring as lines (str) in a Python list."""
    new_docstring_lst = []
    for idx, line in enumerate(docstring.split('\n')):
        line = line.strip()
        if set(line) in ({'-'}, {'='}):
            new_docstring_lst[idx - 1] = '**%s**' % new_docstring_lst[idx - 1]
        elif line.startswith('>>>'):
            line = '    %s' % line
        new_docstring_lst.append(line)
    for idx, line in enumerate(new_docstring_lst[1:]):
        if line:
            if line.startswith('Description : '):
                new_docstring_lst[idx + 1] = new_docstring_lst[idx + 1].replace('Description : ', '')
            elif ' : ' in line:
                line = line.replace(' : ', '` : ')
                new_docstring_lst[idx + 1] = '\n- `%s\n' % line
            elif '**' in new_docstring_lst[idx - 1] and '**' not in line:
                new_docstring_lst[idx + 1] = '\n%s' % line.lstrip()
            elif '**' not in line:
                new_docstring_lst[idx + 1] = '    %s' % line.lstrip()
    clean_lst = []
    for line in new_docstring_lst:
        if set(line.strip()) not in ({'-'}, {'='}):
            clean_lst.append(line)
    return clean_lst

def get_functions_and_classes(package):
    """Retun lists of functions and classes from a package.

    Parameters
    ----------
    package : python package object

    Returns
    --------
    list, list : list of classes and functions
        Each sublist consists of [name, member] sublists."""
    classes, functions = ([], [])
    for name, member in inspect.getmembers(package):
        if not name.startswith('_'):
            if inspect.isclass(member):
                classes.append([name, member])
            elif inspect.isfunction(member):
                functions.append([name, member])
    return (classes, functions)

def field_or_value(clause):
    """For a clause that could be a field or value,
    create the right one and return it"""
    if hasattr(clause, 'getName') and clause.getName() != 'field':
        return Value(resolve(clause))
    else:
        return Field(clause)

def default(value):
    """Default encoder for JSON"""
    if isinstance(value, Decimal):
        primative = float(value)
        if int(primative) == primative:
            return int(primative)
        else:
            return primative
    elif isinstance(value, set):
        return list(value)
    elif isinstance(value, Binary):
        return b64encode(value.value)
    raise TypeError('Cannot encode %s value %r' % (type(value), value))

def add_query_kwargs(kwargs, visitor, constraints, index):
    """Construct KeyConditionExpression and FilterExpression"""
    query_const, filter_const = constraints.remove_index(index)
    kwargs['key_condition_expr'] = query_const.build(visitor)
    if filter_const:
        kwargs['filter'] = filter_const.build(visitor)
    if index.name != 'TABLE':
        kwargs['index'] = index.name

def iter_insert_items(tree):
    """Iterate over the items to insert from an INSERT statement"""
    if tree.list_values:
        keys = tree.attrs
        for values in tree.list_values:
            if len(keys) != len(values):
                raise SyntaxError("Values '%s' do not match attributes '%s'" % (values, keys))
            yield dict(zip(keys, map(resolve, values)))
    elif tree.map_values:
        for item in tree.map_values:
            data = {}
            for key, val in item:
                data[key] = resolve(val)
            yield data
    else:
        raise SyntaxError('No insert data found')

def format_throughput(available, used=None):
    """Format the read/write throughput for display"""
    if used is None:
        return str(available)
    percent = float(used) / available
    return '{0:.0f}/{1:.0f} ({2:.0%})'.format(used, available, percent)

def resolve(val):
    """Convert a pyparsing value to the python type"""
    name = val.getName()
    if name == 'number':
        try:
            return int(val.number)
        except ValueError:
            return Decimal(val.number)
    elif name == 'str':
        return unwrap(val.str)
    elif name == 'null':
        return None
    elif name == 'binary':
        return Binary(val.binary[2:-1])
    elif name == 'set':
        if val.set == '()':
            return set()
        return set([resolve(v) for v in val.set])
    elif name == 'bool':
        return val.bool == 'TRUE'
    elif name == 'list':
        return [resolve(v) for v in val.list]
    elif name == 'dict':
        dict_val = {}
        for k, v in val.dict:
            dict_val[resolve(k)] = resolve(v)
        return dict_val
    elif name == 'ts_function':
        return dt_to_ts(eval_function(val.ts_function))
    elif name == 'ts_expression':
        return dt_to_ts(eval_expression(val))
    else:
        raise SyntaxError("Unable to resolve value '%s'" % val)

def dt_to_ts(value):
    """If value is a datetime, convert to timestamp"""
    if not isinstance(value, datetime):
        return value
    return calendar.timegm(value.utctimetuple()) + value.microsecond / 1000000.0

def eval_function(value):
    """Evaluate a timestamp function"""
    name, args = (value[0], value[1:])
    if name == 'NOW':
        return datetime.utcnow().replace(tzinfo=tzutc())
    elif name in ['TIMESTAMP', 'TS']:
        return parse(unwrap(args[0])).replace(tzinfo=tzlocal())
    elif name in ['UTCTIMESTAMP', 'UTCTS']:
        return parse(unwrap(args[0])).replace(tzinfo=tzutc())
    elif name == 'MS':
        return 1000 * resolve(args[0])
    else:
        raise SyntaxError('Unrecognized function %r' % name)

def eval_interval(interval):
    """Evaluate an interval expression"""
    kwargs = {'years': 0, 'months': 0, 'weeks': 0, 'days': 0, 'hours': 0, 'minutes': 0, 'seconds': 0, 'microseconds': 0}
    for section in interval[1:]:
        name = section.getName()
        if name == 'year':
            kwargs['years'] += int(section[0])
        elif name == 'month':
            kwargs['months'] += int(section[0])
        elif name == 'week':
            kwargs['weeks'] += int(section[0])
        elif name == 'day':
            kwargs['days'] += int(section[0])
        elif name == 'hour':
            kwargs['hours'] += int(section[0])
        elif name == 'minute':
            kwargs['minutes'] += int(section[0])
        elif name == 'second':
            kwargs['seconds'] += int(section[0])
        elif name == 'millisecond':
            kwargs['microseconds'] += 1000 * int(section[0])
        elif name == 'microsecond':
            kwargs['microseconds'] += int(section[0])
        else:
            raise SyntaxError('Unrecognized interval type %r: %s' % (name, section))
    return relativedelta(**kwargs)

def eval_expression(value):
    """Evaluate a full time expression"""
    start = eval_function(value.ts_expression[0])
    interval = eval_interval(value.ts_expression[2])
    op = value.ts_expression[1]
    if op == '+':
        return start + interval
    elif op == '-':
        return start - interval
    else:
        raise SyntaxError('Unrecognized operator %r' % op)

def linkcode_resolve(domain, info):
    """Link source code to github"""
    if domain != 'py' or not info['module']:
        return None
    filename = info['module'].replace('.', '/')
    mod = importlib.import_module(info['module'])
    basename = os.path.splitext(mod.__file__)[0]
    if basename.endswith('__init__'):
        filename += '/__init__'
    item = mod
    lineno = ''
    for piece in info['fullname'].split('.'):
        item = getattr(item, piece)
        try:
            lineno = '#L%d' % inspect.getsourcelines(item)[1]
        except (TypeError, IOError):
            pass
    return 'https://github.com/%s/%s/blob/%s/%s.py%s' % (github_user, project, release, filename, lineno)

def sub(a, b):
    """Subtract two values, ignoring None"""
    if a is None:
        if b is None:
            return None
        else:
            return -1 * b
    elif b is None:
        return a
    return a - b

def mul(a, b):
    """Multiply two values, ignoring None"""
    if a is None:
        if b is None:
            return None
        else:
            return b
    elif b is None:
        return a
    return a * b

def div(a, b):
    """Divide two values, ignoring None"""
    if a is None:
        if b is None:
            return None
        else:
            return 1 / b
    elif b is None:
        return a
    return a / b

def parse_expression(clause):
    """For a clause that could be a field, value, or expression"""
    if isinstance(clause, Expression):
        return clause
    elif hasattr(clause, 'getName') and clause.getName() != 'field':
        if clause.getName() == 'nested':
            return AttributeSelection.from_statement(clause)
        elif clause.getName() == 'function':
            return SelectFunction.from_statement(clause)
        else:
            return Value(resolve(clause[0]))
    else:
        return Field(clause[0])

def select_functions(expr):
    """Create the function expressions for selection"""
    body = Group(expr)
    return Group(function('timestamp', body, caseless=True) | function('ts', body, caseless=True) | function('utctimestamp', body, caseless=True) | function('utcts', body, caseless=True) | function('now', caseless=True) | function('utcnow', caseless=True)).setResultsName('function')

def create_keys_in():
    """Create a grammer for the 'KEYS IN' clause used for queries"""
    keys = Group(Optional(Suppress('(')) + value + Optional(Suppress(',') + value) + Optional(Suppress(')')))
    return (Suppress(upkey('keys') + upkey('in')) + delimitedList(keys)).setResultsName('keys_in')

def wrap(string, length, indent):
    """Wrap a string at a line length"""
    newline = '\n' + ' ' * indent
    return newline.join((string[i:i + length] for i in range(0, len(string), length)))

def format_json(json_object, indent):
    """Pretty-format json data"""
    indent_str = '\n' + ' ' * indent
    json_str = json.dumps(json_object, indent=2, default=serialize_json_var)
    return indent_str.join(json_str.split('\n'))

def delta_to_str(rd):
    """Convert a relativedelta to a human-readable string"""
    parts = []
    if rd.days > 0:
        parts.append('%d day%s' % (rd.days, plural(rd.days)))
    clock_parts = []
    if rd.hours > 0:
        clock_parts.append('%02d' % rd.hours)
    if rd.minutes > 0 or rd.hours > 0:
        clock_parts.append('%02d' % rd.minutes)
    if rd.seconds > 0 or rd.minutes > 0 or rd.hours > 0:
        clock_parts.append('%02d' % rd.seconds)
    if clock_parts:
        parts.append(':'.join(clock_parts))
    return ' '.join(parts)

def stdout_display():
    """Print results straight to stdout"""
    if sys.version_info[0] == 2:
        yield SmartBuffer(sys.stdout)
    else:
        yield SmartBuffer(sys.stdout.buffer)

def prompt(msg, default=NO_DEFAULT, validate=None):
    """Prompt user for input"""
    while True:
        response = input(msg + ' ').strip()
        if not response:
            if default is NO_DEFAULT:
                continue
            return default
        if validate is None or validate(response):
            return response

def promptyn(msg, default=None):
    """Display a blocking prompt until the user confirms"""
    while True:
        yes = 'Y' if default else 'y'
        if default or default is None:
            no = 'n'
        else:
            no = 'N'
        confirm = prompt('%s [%s/%s]' % (msg, yes, no), '').lower()
        if confirm in ('y', 'yes'):
            return True
        elif confirm in ('n', 'no'):
            return False
        elif not confirm and default is not None:
            return default

def repl_command(fxn):
    """Decorator for cmd methods

    Parses arguments from the arg string and passes them to the method as *args
    and **kwargs."""
    @functools.wraps(fxn)
    def wrapper(self, arglist):
        """Wraps the command method"""
        args = []
        kwargs = {}
        if arglist:
            for arg in shlex.split(arglist):
                if '=' in arg:
                    split = arg.split('=', 1)
                    kwargs[split[0]] = split[1]
                else:
                    args.append(arg)
        return fxn(self, *args, **kwargs)
    return wrapper

def get_enum_key(key, choices):
    """Get an enum by prefix or equality"""
    if key in choices:
        return key
    keys = [k for k in choices if k.startswith(key)]
    if len(keys) == 1:
        return keys[0]

def function(name, *args, **kwargs):
    """Construct a parser for a standard function format"""
    if kwargs.get('caseless'):
        name = upkey(name)
    else:
        name = Word(name)
    fxn_args = None
    for i, arg in enumerate(args):
        if i == 0:
            fxn_args = arg
        else:
            fxn_args += Suppress(',') + arg
    if fxn_args is None:
        return name + Suppress('(') + Suppress(')')
    if kwargs.get('optparen'):
        return name + (Suppress('(') + fxn_args + Suppress(')') | fxn_args)
    else:
        return name + Suppress('(') + fxn_args + Suppress(')')

def make_interval(long_name, short_name):
    """Create an interval segment"""
    return Group(Regex('(-+)?[0-9]+') + (upkey(long_name + 's') | Regex(long_name + 's').setParseAction(upcaseTokens) | upkey(long_name) | Regex(long_name).setParseAction(upcaseTokens) | upkey(short_name) | Regex(short_name).setParseAction(upcaseTokens))).setResultsName(long_name)

def create_throughput(variable=primitive):
    """Create a throughput specification"""
    return (Suppress(upkey('throughput') | upkey('tp')) + Suppress('(') + variable + Suppress(',') + variable + Suppress(')')).setResultsName('throughput')

def create_throttle():
    """Create a THROTTLE statement"""
    throttle_amount = '*' | Combine(number + '%') | number
    return Group(function('throttle', throttle_amount, throttle_amount, caseless=True)).setResultsName('throttle')

def create_delete():
    """Create the grammar for the 'delete' statement"""
    delete = upkey('delete').setResultsName('action')
    return delete + from_ + table + Optional(keys_in) + Optional(where) + Optional(using) + Optional(throttle)

def create_update():
    """Create the grammar for the 'update' statement"""
    update = upkey('update').setResultsName('action')
    returns, none, all_, updated, old, new = map(upkey, ['returns', 'none', 'all', 'updated', 'old', 'new'])
    return_ = returns + Group(none | all_ + old | all_ + new | updated + old | updated + new).setResultsName('returns')
    return update + table + update_expr + Optional(keys_in) + Optional(where) + Optional(using) + Optional(return_) + Optional(throttle)

def create_dump():
    """Create the grammar for the 'dump' statement"""
    dump = upkey('dump').setResultsName('action')
    return dump + upkey('schema') + Optional(Group(delimitedList(table)).setResultsName('tables'))

def create_load():
    """Create the grammar for the 'load' statement"""
    load = upkey('load').setResultsName('action')
    return load + Group(filename).setResultsName('load_file') + upkey('into') + table + Optional(throttle)

def normalize_hex(hex_value):
    """Normalize a hexadecimal color value to 6 digits, lowercase."""
    match = HEX_COLOR_RE.match(hex_value)
    if match is None:
        raise ValueError(u"'{}' is not a valid hexadecimal color value.".format(hex_value))
    hex_digits = match.group(1)
    if len(hex_digits) == 3:
        hex_digits = u''.join((2 * s for s in hex_digits))
    return u'#{}'.format(hex_digits.lower())

def _normalize_percent_rgb(value):
    """Internal normalization function for clipping percent values into
    the permitted range (0%-100%, inclusive)."""
    percent = value.split(u'%')[0]
    percent = float(percent) if u'.' in percent else int(percent)
    return u'0%' if percent < 0 else u'100%' if percent > 100 else u'{}%'.format(percent)

def hex_to_rgb(hex_value):
    """Convert a hexadecimal color value to a 3-tuple of integers
    suitable for use in an ``rgb()`` triplet specifying that color."""
    hex_value = normalize_hex(hex_value)
    hex_value = int(hex_value[1:], 16)
    return IntegerRGB(hex_value >> 16, hex_value >> 8 & 255, hex_value & 255)

def html5_parse_simple_color(input):
    """Apply the simple color parsing algorithm from section 2.4.6 of
    HTML5."""
    if not isinstance(input, unicode) or len(input) != 7:
        raise ValueError(u'An HTML5 simple color must be a Unicode string exactly seven characters long.')
    if not input.startswith('#'):
        raise ValueError(u"An HTML5 simple color must begin with the character '#' (U+0023).")
    if not all((c in string.hexdigits for c in input[1:])):
        raise ValueError(u'An HTML5 simple color must contain exactly six ASCII hex digits.')
    return HTML5SimpleColor(int(input[1:3], 16), int(input[3:5], 16), int(input[5:7], 16))

def today(year=None):
    """this day, last year"""
    return datetime.date(int(year), _date.month, _date.day) if year else _date

def tomorrow(date=None):
    """tomorrow is another day"""
    if not date:
        return _date + datetime.timedelta(days=1)
    else:
        current_date = parse(date)
        return current_date + datetime.timedelta(days=1)

def yesterday(date=None):
    """yesterday once more"""
    if not date:
        return _date - datetime.timedelta(days=1)
    else:
        current_date = parse(date)
        return current_date - datetime.timedelta(days=1)

def midnight(arg=None):
    """convert date to datetime as midnight or get current day's midnight
    :param arg: string or date/datetime
    :return: datetime at 00:00:00"""
    if arg:
        _arg = parse(arg)
        if isinstance(_arg, datetime.date):
            return datetime.datetime.combine(_arg, datetime.datetime.min.time())
        elif isinstance(_arg, datetime.datetime):
            return datetime.datetime.combine(_arg.date(), datetime.datetime.min.time())
    else:
        return datetime.datetime.combine(_date, datetime.datetime.min.time())

def before(base=_datetime, diff=None):
    """count datetime before `base` time
    :param base:  minuend -> str/datetime/date
    :param diff:  str
    :return: datetime"""
    _base = parse(base)
    if isinstance(_base, datetime.date):
        _base = midnight(_base)
    if not diff:
        return _base
    result_dict = dp(diff)
    for unit in result_dict:
        _val = result_dict[unit]
        if not _val:
            continue
        if unit == 'years':
            _base = _base.replace(year=_base.year - _val)
        elif unit == 'months':
            if _base.month <= _val:
                _month_diff = 12 - (_val - _base.month)
                _base = _base.replace(year=_base.year - 1).replace(month=_month_diff)
            else:
                _base = _base.replace(month=_base.month - _val)
        elif unit in ['days', 'hours', 'minutes', 'seconds']:
            _base = _base - datetime.timedelta(**{unit: _val})
    return _base

def easter(year=None):
    """1900 - 2099 limit
    :param year: int
    :return: Easter day"""
    y = int(year) if year else _year
    n = y - 1900
    a = n % 19
    q = n // 4
    b = (7 * a + 1) // 19
    m = (11 * a + 4 - b) % 29
    w = (n + q + 31 - m) % 7
    d = 25 - m - w
    if d > 0:
        return datetime.date(y, 4, d)
    else:
        return datetime.date(y, 3, 31 + d)

def thanks(year=None):
    """4rd Thursday in Nov
    :param year: int
    :return: Thanksgiving Day"""
    nov_first = datetime.date(_year, 11, 1) if not year else datetime.date(int(year), 11, 1)
    weekday_seq = nov_first.weekday()
    if weekday_seq > 3:
        current_day = 32 - weekday_seq
    else:
        current_day = 25 - weekday_seq
    return datetime.date(nov_first.year, 11, current_day)

def throws_errors(func):
    """Wraps a function responsible for implementing an API endpoint such that
    any server errors that are thrown are automatically transformed into
    appropriate HTTP responses."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        response = func(*args, **kwargs)
        if isinstance(response, BugZooException):
            err_jsn = flask.jsonify(response.to_dict())
            return (err_jsn, 400)
        if isinstance(response, tuple) and isinstance(response[0], BugZooException):
            err = response[0]
            err_jsn = flask.jsonify(err.to_dict())
            return (err_jsn, *response[1:])
        return response
    return wrapper

def register(name: str):
    """Registers a coverage extractor class under a given name.

    .. code: python

        from bugzoo.mgr.coverage import CoverageExtractor, register

        @register('mycov')
        class MyCoverageExtractor(CoverageExtractor):
            ..."""
    def decorator(cls: Type['CoverageExtractor']):
        cls.register(name)
        return cls
    return decorator

def register_as_default(language: Language):
    """Registers a coverage extractor class as the default coverage extractor
    for a given language. Requires that the coverage extractor class has
    already been registered with a given name.

    .. code: python

        from bugzoo.core import Language
        from bugzoo.mgr.coverage import CoverageExtractor, register,             register_as_default

        @register_as_default(Language.CPP)
        @register('mycov')
        class MyCoverageExtractor(CoverageExtractor):
            ..."""
    def decorator(cls: Type['CoverageExtractor']):
        cls.register_as_default(language)
        return cls
    return decorator

def get_tags(doc):
    """Get tags from a DOM tree

    :param doc: lxml parsed object
    :return:"""
    tags = list()
    for el in doc.getroot().iter():
        if isinstance(el, lxml.html.HtmlElement):
            tags.append(el.tag)
        elif isinstance(el, lxml.html.HtmlComment):
            tags.append('comment')
        else:
            raise ValueError("Don't know what to do with element: {}".format(el))
    return tags

def object_deserializer(obj):
    """Helper to deserialize a raw result dict into a proper dict.

    :param obj: The dict."""
    for key, val in obj.items():
        if isinstance(val, six.string_types) and DATETIME_REGEX.search(val):
            try:
                obj[key] = dates.localize_datetime(parser.parse(val))
            except ValueError:
                obj[key] = val
    return obj

def login(session, user, password, database=None, server=None):
    """Logs into a MyGeotab server and stores the returned credentials.

    :param session: The current Session object.
    :param user: The username used for MyGeotab servers. Usually an email address.
    :param password: The password associated with the username. Optional if `session_id` is provided.
    :param database: The database or company name. Optional as this usually gets resolved upon authentication.
    :param server: The server ie. my23.geotab.com. Optional as this usually gets resolved upon authentication."""
    if not user:
        user = click.prompt('Username', type=str)
    if not password:
        password = click.prompt('Password', hide_input=True, type=str)
    try:
        with click.progressbar(length=1, label='Logging in...') as progressbar:
            session.login(user, password, database, server)
            progressbar.update(1)
        if session.credentials:
            click.echo('Logged in as: %s' % session.credentials)
            session.load(database)
        return session.get_api()
    except mygeotab.AuthenticationException:
        click.echo('Incorrect credentials. Please try again.')
        sys.exit(0)

def sessions(session):
    """Shows the current logged in sessions.

    :param session: The current Session object."""
    active_sessions = session.get_sessions()
    if not active_sessions:
        click.echo('(No active sessions)')
        return
    for active_session in active_sessions:
        click.echo(active_session)

def run(*tasks: Awaitable, loop: asyncio.AbstractEventLoop=asyncio.get_event_loop()):
    """Helper to run tasks in the event loop

    :param tasks: Tasks to run in the event loop.
    :param loop: The event loop."""
    futures = [asyncio.ensure_future(task, loop=loop) for task in tasks]
    return loop.run_until_complete(asyncio.gather(*futures))

def localize_datetime(datetime_obj, tz=pytz.utc):
    """Converts a naive or UTC-localized date into the provided timezone.

    :param datetime_obj: The datetime object.
    :type datetime_obj: datetime
    :param tz: The timezone. If blank or None, UTC is used.
    :type tz: datetime.tzinfo
    :return: The localized datetime object.
    :rtype: datetime"""
    if not datetime_obj.tzinfo:
        return tz.localize(datetime_obj)
    else:
        try:
            return datetime_obj.astimezone(tz)
        except OverflowError:
            if datetime_obj < datetime(2, 1, 1, tzinfo=pytz.utc):
                return MIN_DATE.astimezone(tz)
            return MAX_DATE.astimezone(tz)

def process_parameters(parameters):
    """Allows the use of Pythonic-style parameters with underscores instead of camel-case.

    :param parameters: The parameters object.
    :type parameters: dict
    :return: The processed parameters.
    :rtype: dict"""
    if not parameters:
        return {}
    params = copy.copy(parameters)
    for param_name in parameters:
        value = parameters[param_name]
        server_param_name = re.sub('_(\\w)', lambda m: m.group(1).upper(), param_name)
        if isinstance(value, dict):
            value = process_parameters(value)
        params[server_param_name] = value
        if server_param_name != param_name:
            del params[param_name]
    return params

def _should_allocate_port(pid):
    """Determine if we should allocate a port for use by the given process id."""
    if pid <= 0:
        log.info('Not allocating a port to invalid pid')
        return False
    if pid == 1:
        log.info('Not allocating a port to init.')
        return False
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        log.info('Not allocating a port to a non-existent process')
        return False
    return True

def return_port(port):
    """Return a port that is no longer being used so it can be reused."""
    if port in _random_ports:
        _random_ports.remove(port)
    elif port in _owned_ports:
        _owned_ports.remove(port)
        _free_ports.add(port)
    elif port in _free_ports:
        logging.info('Returning a port that was already returned: %s', port)
    else:
        logging.info("Returning a port that wasn't given by portpicker: %s", port)

def main(argv):
    """If passed an arg, treat it as a PID, otherwise portpicker uses getpid."""
    port = pick_unused_port(pid=int(argv[1]) if len(argv) > 1 else None)
    if not port:
        sys.exit(1)
    print(port)

def is_text(bytesio):
    """Return whether the first KB of contents seems to be binary.

    This is roughly based on libmagic's binary/text detection:
    https://github.com/file/file/blob/df74b09b9027676088c797528edcaae5a9ce9ad0/src/encoding.c#L203-L228"""
    text_chars = bytearray([7, 8, 9, 10, 11, 12, 13, 27]) + bytearray(range(32, 127)) + bytearray(range(128, 256))
    return not bool(bytesio.read(1024).translate(None, text_chars))

def parse_shebang(bytesio):
    """Parse the shebang from a file opened for reading binary."""
    if bytesio.read(2) != b'#!':
        return ()
    first_line = bytesio.readline()
    try:
        first_line = first_line.decode('UTF-8')
    except UnicodeDecodeError:
        return ()
    for c in first_line:
        if c not in printable:
            return ()
    cmd = tuple(_shebang_split(first_line.strip()))
    if cmd[0] == '/usr/bin/env':
        cmd = cmd[1:]
    return cmd

def parse_shebang_from_file(path):
    """Parse the shebang given a file path."""
    if not os.path.lexists(path):
        raise ValueError('{} does not exist.'.format(path))
    if not os.access(path, os.X_OK):
        return ()
    with open(path, 'rb') as f:
        return parse_shebang(f)

def ReliefF_compute_scores(inst, attr, nan_entries, num_attributes, mcmap, NN, headers, class_type, X, y, labels_std, data_type):
    """Unique scoring procedure for ReliefF algorithm. Scoring based on k nearest hits and misses of current target instance."""
    scores = np.zeros(num_attributes)
    for feature_num in range(num_attributes):
        scores[feature_num] += compute_score(attr, mcmap, NN, feature_num, inst, nan_entries, headers, class_type, X, y, labels_std, data_type)
    return scores

def SURFstar_compute_scores(inst, attr, nan_entries, num_attributes, mcmap, NN_near, NN_far, headers, class_type, X, y, labels_std, data_type):
    """Unique scoring procedure for SURFstar algorithm. Scoring based on nearest neighbors within defined radius, as well as
    'anti-scoring' of far instances outside of radius of current target instance"""
    scores = np.zeros(num_attributes)
    for feature_num in range(num_attributes):
        if len(NN_near) > 0:
            scores[feature_num] += compute_score(attr, mcmap, NN_near, feature_num, inst, nan_entries, headers, class_type, X, y, labels_std, data_type)
        if len(NN_far) > 0:
            scores[feature_num] -= compute_score(attr, mcmap, NN_far, feature_num, inst, nan_entries, headers, class_type, X, y, labels_std, data_type)
    return scores

def get_live_data_dir():
    """pygeth needs a base directory to store it's chain data.  By default this is
    the directory that `geth` uses as it's `datadir`."""
    if sys.platform == 'darwin':
        data_dir = os.path.expanduser(os.path.join('~', 'Library', 'Ethereum'))
    elif sys.platform in {'linux', 'linux2', 'linux3'}:
        data_dir = os.path.expanduser(os.path.join('~', '.ethereum'))
    elif sys.platform == 'win32':
        data_dir = os.path.expanduser(os.path.join('\\', '~', 'AppData', 'Roaming', 'Ethereum'))
    else:
        raise ValueError("Unsupported platform: '{0}'.  Only darwin/linux2/win32 are supported.  You must specify the geth datadir manually".format(sys.platform))
    return data_dir

def get_accounts(data_dir, **geth_kwargs):
    """Returns all geth accounts as tuple of hex encoded strings

    >>> geth_accounts()
    ... ('0x...', '0x...')"""
    command, proc = spawn_geth(dict(data_dir=data_dir, suffix_args=['account', 'list'], **geth_kwargs))
    stdoutdata, stderrdata = proc.communicate()
    if proc.returncode:
        if 'no keys in store' in stderrdata.decode('utf-8'):
            return tuple()
        else:
            raise ValueError(format_error_message('Error trying to list accounts', command, proc.returncode, stdoutdata, stderrdata))
    accounts = parse_geth_accounts(stdoutdata)
    return accounts

def ensure_path_exists(dir_path):
    """Make sure that a path exists"""
    if not os.path.exists(dir_path):
        mkdir(dir_path)
        return True
    return False

def clean_exit(signum, frame=None):
    """Exit all processes attempting to finish uncommitted active work before exit.
    Can be called on an os signal or no zookeeper losing connection."""
    global exiting
    if exiting:
        LOG.debug('Exit in progress clean_exit received additional signal %s' % signum)
        return
    LOG.info('Received signal %s, beginning graceful shutdown.' % signum)
    exiting = True
    wait_for_exit = False
    for process in processors:
        try:
            if process.is_alive():
                process.terminate()
                wait_for_exit = True
        except Exception:
            pass
    if wait_for_exit:
        time.sleep(2)
    for child in multiprocessing.active_children():
        LOG.debug('Killing pid %s' % child.pid)
        try:
            os.kill(child.pid, signal.SIGKILL)
        except Exception:
            pass
    if signum == signal.SIGTERM:
        sys.exit(0)
    sys.exit(signum)

def _get_config_files():
    """Get the possible configuration files accepted by oslo.config

    This also includes the deprecated ones"""
    conf_files = cfg.find_config_files(project='monasca', prog='monasca-persister')
    if len(conf_files) == 0:
        old_conf_files = cfg.find_config_files(project='monasca', prog='persister')
        if len(old_conf_files) > 0:
            LOG.warning('Found deprecated old location "{}" of main configuration file'.format(old_conf_files))
            conf_files += old_conf_files
    return conf_files

def load_conf_modules():
    """Load all modules that contain configuration.

    Method iterates over modules of :py:module:`monasca_persister.conf`
    and imports only those that contain following methods:

    - list_opts (required by oslo_config.genconfig)
    - register_opts (required by :py:currentmodule:)"""
    for modname in _list_module_names():
        mod = importutils.import_module('monasca_persister.conf.' + modname)
        required_funcs = ['register_opts', 'list_opts']
        for func in required_funcs:
            if hasattr(mod, func):
                yield mod

def list_opts():
    """List all conf modules opts.

    Goes through all conf modules and yields their opts."""
    for mod in load_conf_modules():
        mod_opts = mod.list_opts()
        if type(mod_opts) is list:
            for single_mod_opts in mod_opts:
                yield (single_mod_opts[0], single_mod_opts[1])
        else:
            yield (mod_opts[0], mod_opts[1])

def find_microbit():
    """Returns a tuple representation of the port and serial number for a
    connected micro:bit device. If no device is connected the tuple will be
    (None, None)."""
    ports = list_serial_ports()
    for port in ports:
        if 'VID:PID=0D28:0204' in port[2].upper():
            return (port[0], port.serial_number)
    return (None, None)

def get_serial():
    """Detect if a micro:bit is connected and return a serial object to talk to
    it."""
    port, serial_number = find_microbit()
    if port is None:
        raise IOError('Could not find micro:bit.')
    return Serial(port, SERIAL_BAUD_RATE, timeout=1, parity='N')

def clean_error(err):
    """Take stderr bytes returned from MicroPython and attempt to create a
    non-verbose error message."""
    if err:
        decoded = err.decode('utf-8')
        try:
            return decoded.split('\r\n')[-2]
        except Exception:
            return decoded
    return 'There was an error.'

def ls(serial=None):
    """List the files on the micro:bit.

    If no serial object is supplied, microfs will attempt to detect the
    connection itself.

    Returns a list of the files on the connected device or raises an IOError if
    there's a problem."""
    out, err = execute(['import os', 'print(os.listdir())'], serial)
    if err:
        raise IOError(clean_error(err))
    return ast.literal_eval(out.decode('utf-8'))

def version(serial=None):
    """Returns version information for MicroPython running on the connected
    device.

    If such information is not available or the device is not running
    MicroPython, raise a ValueError.

    If any other exception is thrown, the device was running MicroPython but
    there was a problem parsing the output."""
    try:
        out, err = execute(['import os', 'print(os.uname())'], serial)
        if err:
            raise ValueError(clean_error(err))
    except ValueError:
        raise
    except Exception:
        raise ValueError()
    raw = out.decode('utf-8').strip()
    raw = raw[1:-1]
    items = raw.split(', ')
    result = {}
    for item in items:
        key, value = item.split('=')
        result[key] = value[1:-1]
    return result

def wait_for_path_blocking(path: pathlib.Path, timeout: int=30) -> None:
    """Waits up to ``timeout`` seconds for the path to appear at path
    ``path`` otherwise raises :exc:`TimeoutError`."""
    start_at = time.monotonic()
    while time.monotonic() - start_at < timeout:
        if path.exists():
            return
        else:
            time.sleep(0.05)
    raise TimeoutError(f'IPC socket file {path} has not appeared in {timeout} seconds')

def get_start_and_end_times(feed: 'Feed', date: Optional[str]=None) -> List[str]:
    """Return the first departure time and last arrival time
    (HH:MM:SS time strings) listed in ``feed.stop_times``, respectively.
    Restrict to the given date (YYYYMMDD string) if specified."""
    st = feed.get_stop_times(date)
    return (st['departure_time'].dropna().min(), st['arrival_time'].dropna().max())

def valid_str(x: str) -> bool:
    """Return ``True`` if ``x`` is a non-blank string;
    otherwise return ``False``."""
    if isinstance(x, str) and x.strip():
        return True
    else:
        return False

def valid_time(x: str) -> bool:
    """Return ``True`` if ``x`` is a valid H:MM:SS or HH:MM:SS time;
    otherwise return ``False``."""
    if isinstance(x, str) and (re.match(TIME_PATTERN1, x) or re.match(TIME_PATTERN2, x)):
        return True
    else:
        return False

def valid_url(x: str) -> bool:
    """Return ``True`` if ``x`` is a valid URL; otherwise return ``False``."""
    if isinstance(x, str) and re.match(URL_PATTERN, x):
        return True
    else:
        return False

def valid_email(x: str) -> bool:
    """Return ``True`` if ``x`` is a valid email address; otherwise return
    ``False``."""
    if isinstance(x, str) and re.match(EMAIL_PATTERN, x):
        return True
    else:
        return False

def valid_color(x: str) -> bool:
    """Return ``True`` if ``x`` a valid hexadecimal color string without
    the leading hash; otherwise return ``False``."""
    if isinstance(x, str) and re.match(COLOR_PATTERN, x):
        return True
    else:
        return False

def check_agency(feed: 'Feed', *, as_df: bool=False, include_warnings: bool=False) -> List:
    """Check that ``feed.agency`` follows the GTFS.
    Return a list of problems of the form described in
    :func:`check_table`;
    the list will be empty if no problems are found."""
    table = 'agency'
    problems = []
    if feed.agency is None:
        problems.append(['error', 'Missing table', table, []])
    else:
        f = feed.agency.copy()
        problems = check_for_required_columns(problems, table, f)
    if problems:
        return format_problems(problems, as_df=as_df)
    if include_warnings:
        problems = check_for_invalid_columns(problems, table, f)
    problems = check_column_id(problems, table, f, 'agency_id', column_required=False)
    problems = check_column(problems, table, f, 'agency_name', valid_str)
    problems = check_column(problems, table, f, 'agency_url', valid_url)
    problems = check_column(problems, table, f, 'agency_timezone', valid_timezone)
    problems = check_column(problems, table, f, 'agency_fare_url', valid_url, column_required=False)
    problems = check_column(problems, table, f, 'agency_lang', valid_lang, column_required=False)
    problems = check_column(problems, table, f, 'agency_phone', valid_str, column_required=False)
    problems = check_column(problems, table, f, 'agency_email', valid_email, column_required=False)
    return format_problems(problems, as_df=as_df)

