    """Analog of :func:`check_agency` for ``feed.calendar``."""
    table = 'calendar'
    problems = []
    if feed.calendar is None:
        return problems
    f = feed.calendar.copy()
    problems = check_for_required_columns(problems, table, f)
    if problems:
