def compute_bounds(feed: 'Feed') -> Tuple:
    """Return the tuple (min longitude, min latitude, max longitude,
    max latitude) where the longitudes and latitude vary across all
    the Feed's stop coordinates."""
    lons, lats = (feed.stops['stop_lon'], feed.stops['stop_lat'])
    return (lons.min(), lats.min(), lons.max(), lats.max())

def clean_ids(feed: 'Feed') -> 'Feed':
    """In the given "Feed", strip whitespace from all string IDs and
    then replace every remaining whitespace chunk with an underscore.
    Return the resulting "Feed"."""
    feed = feed.copy()
    for table in cs.GTFS_REF['table'].unique():
        f = getattr(feed, table)
        if f is None:
            continue
        for column in cs.GTFS_REF.loc[cs.GTFS_REF['table'] == table, 'column']:
            if column in f.columns and column.endswith('_id'):
                try:
                    f[column] = f[column].str.strip().str.replace('\\s+', '_')
                    setattr(feed, table, f)
                except AttributeError:
                    continue
    return feed

def clean_times(feed: 'Feed') -> 'Feed':
    """In the given "Feed", convert H:MM:SS time strings to HH:MM:SS time
    strings to make sorting by time work as expected.
    Return the resulting "Feed"."""
    def reformat(t):
        if pd.isnull(t):
            return t
        t = t.strip()
        if len(t) == 7:
            t = '0' + t
        return t
    feed = feed.copy()
    tables_and_columns = [('stop_times', ['arrival_time', 'departure_time']), ('frequencies', ['start_time', 'end_time'])]
    for table, columns in tables_and_columns:
        f = getattr(feed, table)
        if f is not None:
            f[columns] = f[columns].applymap(reformat)
        setattr(feed, table, f)
    return feed

def drop_invalid_columns(feed: 'Feed') -> 'Feed':
    """Drop all DataFrame columns of the given "Feed" that are not
    listed in the GTFS.
    Return the resulting new "Feed"."""
    feed = feed.copy()
    for table, group in cs.GTFS_REF.groupby('table'):
        f = getattr(feed, table)
        if f is None:
            continue
        valid_columns = group['column'].values
        for col in f.columns:
            if col not in valid_columns:
                print(f'{table}: dropping invalid column {col}')
                del f[col]
        setattr(feed, table, f)
    return feed

def shapes_to_geojson(feed: 'Feed', shape_ids: Optional[List[str]]=None) -> Dict:
    """Return a (decoded) GeoJSON FeatureCollection of LineString features
    representing ``feed.shapes``.
    Each feature will have a ``shape_id`` property.
    The coordinates reference system is the default one for GeoJSON,
    namely WGS84.

    If a list of shape IDs is given, then return only the LineString
    features corresponding to those shape IDS.
    Return the empty dictionary if ``feed.shapes is None``"""
    geometry_by_shape = feed.build_geometry_by_shape(shape_ids=shape_ids)
    if geometry_by_shape:
        fc = {'type': 'FeatureCollection', 'features': [{'properties': {'shape_id': shape}, 'type': 'Feature', 'geometry': sg.mapping(linestring)} for shape, linestring in geometry_by_shape.items()]}
    else:
        fc = {}
    return fc

def timestr_to_seconds(x: Union[dt.date, str], *, inverse: bool=False, mod24: bool=False) -> int:
    """Given an HH:MM:SS time string ``x``, return the number of seconds
    past midnight that it represents.
    In keeping with GTFS standards, the hours entry may be greater than
    23.
    If ``mod24``, then return the number of seconds modulo ``24*3600``.
    If ``inverse``, then do the inverse operation.
    In this case, if ``mod24`` also, then first take the number of
    seconds modulo ``24*3600``."""
    if not inverse:
        try:
            hours, mins, seconds = x.split(':')
            result = int(hours) * 3600 + int(mins) * 60 + int(seconds)
            if mod24:
                result %= 24 * 3600
        except:
            result = np.nan
    else:
        try:
            seconds = int(x)
            if mod24:
                seconds %= 24 * 3600
            hours, remainder = divmod(seconds, 3600)
            mins, secs = divmod(remainder, 60)
            result = f'{hours:02d}:{mins:02d}:{secs:02d}'
        except:
            result = np.nan
    return result

def timestr_mod24(timestr: str) -> int:
    """Given a GTFS HH:MM:SS time string, return a timestring in the same
    format but with the hours taken modulo 24."""
    try:
        hours, mins, secs = [int(x) for x in timestr.split(':')]
        hours %= 24
        result = f'{hours:02d}:{mins:02d}:{secs:02d}'
    except:
        result = None
    return result

def is_not_null(df: DataFrame, col_name: str) -> bool:
    """Return ``True`` if the given DataFrame has a column of the given
    name (string), and there exists at least one non-NaN value in that
    column; return ``False`` otherwise."""
    if isinstance(df, pd.DataFrame) and col_name in df.columns and df[col_name].notnull().any():
        return True
    else:
        return False

def linestring_to_utm(linestring: LineString) -> LineString:
    """Given a Shapely LineString in WGS84 coordinates,
    convert it to the appropriate UTM coordinates.
    If ``inverse``, then do the inverse."""
    proj = lambda x, y: utm.from_latlon(y, x)[:2]
    return transform(proj, linestring)

def get_dates(feed: 'Feed', *, as_date_obj: bool=False) -> List[str]:
    """Return a list of dates for which the given "Feed" is valid, which
    could be the empty list if the "Feed" has no calendar information.

    Parameters
    ----------
    feed : "Feed"
    as_date_obj : boolean
        If ``True``, then return the dates as ``datetime.date`` objects;
        otherwise return them as strings

    Returns
    -------
    list
        Dates"""
    dates = []
    if feed.calendar is not None and (not feed.calendar.empty):
        if 'start_date' in feed.calendar.columns:
            dates.append(feed.calendar['start_date'].min())
        if 'end_date' in feed.calendar.columns:
            dates.append(feed.calendar['end_date'].max())
    if feed.calendar_dates is not None and (not feed.calendar_dates.empty):
        if 'date' in feed.calendar_dates.columns:
            start = feed.calendar_dates['date'].min()
            end = feed.calendar_dates['date'].max()
            dates.extend([start, end])
    if not dates:
        return []
    start_date, end_date = (min(dates), max(dates))
    start_date, end_date = map(hp.datestr_to_date, [start_date, end_date])
    num_days = (end_date - start_date).days
    result = [start_date + rd.relativedelta(days=+d) for d in range(num_days + 1)]
    if not as_date_obj:
        result = [hp.datestr_to_date(x, inverse=True) for x in result]
    return result

def list_gtfs(path: Path) -> DataFrame:
    """Given a path (string or Path object) to a GTFS zip file or
    directory, record the file names and file sizes of the contents,
    and return the result in a DataFrame with the columns:

    - ``'file_name'``
    - ``'file_size'``"""
    path = Path(path)
    if not path.exists():
        raise ValueError(f'Path {path} does not exist')
    rows = []
    if path.is_file():
        with zipfile.ZipFile(str(path)) as src:
            for x in src.infolist():
                if x.filename == './':
                    continue
                d = {}
                d['file_name'] = x.filename
                d['file_size'] = x.file_size
                rows.append(d)
    else:
        for x in path.iterdir():
            d = {}
            d['file_name'] = x.name
            d['file_size'] = x.stat().st_size
            rows.append(d)
    return pd.DataFrame(rows)

def read_gtfs(path: Path, dist_units: str) -> 'Feed':
    """Create a Feed instance from the given path and given distance units.
    The path should be a directory containing GTFS text files or a
    zip file that unzips as a collection of GTFS text files
    (and not as a directory containing GTFS text files).
    The distance units given must lie in :const:`constants.dist_units`

    Notes
    -----
    - Ignore non-GTFS files
    - Automatically strip whitespace from the column names in GTFS files"""
    path = Path(path)
    if not path.exists():
        raise ValueError(f'Path {path} does not exist')
    if path.is_file():
        zipped = True
        tmp_dir = tempfile.TemporaryDirectory()
        src_path = Path(tmp_dir.name)
        shutil.unpack_archive(str(path), tmp_dir.name, 'zip')
    else:
        zipped = False
        src_path = path
    feed_dict = {table: None for table in cs.GTFS_REF['table']}
    for p in src_path.iterdir():
        table = p.stem
        if p.is_file() and p.stat().st_size and (table in feed_dict):
            df = pd.read_csv(p, dtype=cs.DTYPE, encoding='utf-8-sig')
            if not df.empty:
                feed_dict[table] = cn.clean_column_names(df)
    feed_dict['dist_units'] = dist_units
    if zipped:
        tmp_dir.cleanup()
    return Feed(**feed_dict)

