def timestamp2date(tstamp):
    """Converts a unix timestamp to a Python datetime object"""
    dt = datetime.fromtimestamp(tstamp)
    if not dt.hour + dt.minute + dt.second + dt.microsecond:
        return dt.date()
    else:
        return dt

def date2juldate(val):
    """Convert from a python date/datetime to a Julian date & time"""
    f = 12 * val.year + val.month - 22803
    fq = f // 12
    fr = f % 12
    dt = (fr * 153 + 302) // 5 + val.day + fq * 1461 // 4
    if isinstance(val, datetime):
        return dt + (val.hour + (val.minute + (val.second + 1e-06 * val.microsecond) / 60.0) / 60.0) / 24.0
    else:
        return dt

def currency_pair(code):
    """Construct a :class:`ccy_pair` from a six letter string."""
    c = str(code)
    c1 = currency(c[:3])
    c2 = currency(c[3:])
    return ccy_pair(c1, c2)

def get_package_version(module_obj, value):
    """Get the version of a package or a module's package.

    :param object module_obj: The module that was imported for the consumer
    :param str value: The namespaced module path or package name
    :rtype: str or None"""
    for key in ['version', '__version__']:
        if hasattr(module_obj, key):
            return getattr(module_obj, key)
    parts = value.split('.')
    for index, part in enumerate(parts):
        try:
            return pkg_resources.get_distribution('.'.join(parts[0:index + 1])).version
        except (pkg_resources.DistributionNotFound, pkg_resources.RequirementParseError):
            continue

def message_info(exchange, routing_key, properties):
    """Return info about a message using the same conditional constructs

    :param str exchange: The exchange the message was published to
    :param str routing_key: The routing key used
    :param properties: The AMQP message properties
    :type properties: pika.spec.Basic.Properties
    :rtype: str"""
    output = []
    if properties.message_id:
        output.append(properties.message_id)
    if properties.correlation_id:
        output.append('[correlation_id="{}"]'.format(properties.correlation_id))
    if exchange:
        output.append('published to "{}"'.format(exchange))
    if routing_key:
        output.append('using "{}"'.format(routing_key))
    return ' '.join(output)

def notify_observers(table, kind, primary_key=None):
    """Transmit ORM table change notification.

    :param table: Name of the table that has changed
    :param kind: Change type
    :param primary_key: Primary key of the affected instance"""
    if IN_MIGRATIONS:
        return
    if not Observer.objects.filter(dependencies__table=table).exists():
        return
    def handler():
        """Send a notification to the given channel."""
        try:
            async_to_sync(get_channel_layer().send)(CHANNEL_MAIN, {'type': TYPE_ORM_NOTIFY, 'table': table, 'kind': kind, 'primary_key': str(primary_key)})
        except ChannelFull:
            logger.exception('Unable to notify workers.')
    batcher = PrioritizedBatcher.global_instance()
    if batcher.is_started:
        batcher.add('rest_framework_reactive', handler, group_by=(table, kind, primary_key))
    else:
        handler()

def model_post_save(sender, instance, created=False, **kwargs):
    """Signal emitted after any model is saved via Django ORM.

    :param sender: Model class that was saved
    :param instance: The actual instance that was saved
    :param created: True if a new row was created"""
    if sender._meta.app_label == 'rest_framework_reactive':
        return
    def notify():
        table = sender._meta.db_table
        if created:
            notify_observers(table, ORM_NOTIFY_KIND_CREATE, instance.pk)
        else:
            notify_observers(table, ORM_NOTIFY_KIND_UPDATE, instance.pk)
    transaction.on_commit(notify)

def model_post_delete(sender, instance, **kwargs):
    """Signal emitted after any model is deleted via Django ORM.

    :param sender: Model class that was deleted
    :param instance: The actual instance that was removed"""
    if sender._meta.app_label == 'rest_framework_reactive':
        return
    def notify():
        table = sender._meta.db_table
        notify_observers(table, ORM_NOTIFY_KIND_DELETE, instance.pk)
    transaction.on_commit(notify)

def model_m2m_changed(sender, instance, action, **kwargs):
    """Signal emitted after any M2M relation changes via Django ORM.

    :param sender: M2M intermediate model
    :param instance: The actual instance that was saved
    :param action: M2M action"""
    if sender._meta.app_label == 'rest_framework_reactive':
        return
    def notify():
        table = sender._meta.db_table
        if action == 'post_add':
            notify_observers(table, ORM_NOTIFY_KIND_CREATE)
        elif action in ('post_remove', 'post_clear'):
            notify_observers(table, ORM_NOTIFY_KIND_DELETE)
    transaction.on_commit(notify)

def _format_param_value(key, value):
    """Wraps string values in quotes, and returns as 'key=value'.
    """
    if isinstance(value, str):
        value = "'{}'".format(value)
    return '{}={}'.format(key, value)

def randmatrix(m, n, random_seed=None):
    """Creates an m x n matrix of random values drawn using
    the Xavier Glorot method."""
    val = np.sqrt(6.0 / (m + n))
    np.random.seed(random_seed)
    return np.random.uniform(-val, val, size=(m, n))

def _pprint(params):
    """prints object state in stable manner"""
    params_list = list()
    line_sep = ','
    for i, (k, v) in enumerate(sorted(params.iteritems())):
        if type(v) is float:
            this_repr = '%s=%.10f' % (k, v)
        else:
            this_repr = '%s=%r' % (k, v)
        params_list.append(this_repr)
    lines = ','.join(params_list)
    return lines

def cross_validate(data=None, folds=5, repeat=1, metrics=None, reporters=None, model_def=None, **kwargs):
    """Shortcut to cross-validate a single configuration.

    ModelDefinition variables are passed in as keyword args, along
    with the cross-validation parameters."""
    md_kwargs = {}
    if model_def is None:
        for arg in ModelDefinition.params:
            if arg in kwargs:
                md_kwargs[arg] = kwargs.pop(arg)
        model_def = ModelDefinition(**md_kwargs)
    if metrics is None:
        metrics = []
    if reporters is None:
        reporters = []
    metrics = [MetricReporter(metric) for metric in metrics]
    results = modeling.cross_validate(model_def, data, folds, repeat=repeat, **kwargs)
    for r in reporters + metrics:
        r.process_results(results)
    return CVResult(results, reporters, metrics)

def build_flags(library, type_, path):
    """Return separated build flags from pkg-config output"""
    pkg_config_path = [path]
    if 'PKG_CONFIG_PATH' in os.environ:
        pkg_config_path.append(os.environ['PKG_CONFIG_PATH'])
    if 'LIB_DIR' in os.environ:
        pkg_config_path.append(os.environ['LIB_DIR'])
        pkg_config_path.append(os.path.join(os.environ['LIB_DIR'], 'pkgconfig'))
    options = ['--static', {'I': '--cflags-only-I', 'L': '--libs-only-L', 'l': '--libs-only-l'}[type_]]
    return [flag.strip('-{}'.format(type_)) for flag in subprocess.check_output(['pkg-config'] + options + [library], env=dict(os.environ, PKG_CONFIG_PATH=':'.join(pkg_config_path))).decode('UTF-8').split()]

def get_doc(func):
    """Extract and dedent the __doc__ of a function.

    Unlike `textwrap.dedent()` it also works when the first line
    is not indented."""
    doc = func.__doc__
    if not doc:
        return ''
    if '\n' not in doc:
        return doc
    if doc.startswith(('\n', '\\\n')):
        return textwrap.dedent(doc)
    first, rest = doc.split('\n', 1)
    return first + '\n' + textwrap.dedent(rest)

def is_key(sarg):
    """Check if `sarg` is a key (eg. -foo, --foo) or a negative number (eg. -33).
    """
    if not sarg.startswith('-'):
        return False
    if sarg.startswith('--'):
        return True
    return not sarg.lstrip('-').isnumeric()

def album_to_ref(album):
    """Convert a mopidy album to a mopidy ref."""
    name = ''
    for artist in album.artists:
        if len(name) > 0:
            name += ', '
        name += artist.name
    if len(name) > 0:
        name += ' - '
    if album.name:
        name += album.name
    else:
        name += 'Unknown Album'
    return Ref.directory(uri=album.uri, name=name)

def artist_to_ref(artist):
    """Convert a mopidy artist to a mopidy ref."""
    if artist.name:
        name = artist.name
    else:
        name = 'Unknown artist'
    return Ref.directory(uri=artist.uri, name=name)

def track_to_ref(track, with_track_no=False):
    """Convert a mopidy track to a mopidy ref."""
    if with_track_no and track.track_no > 0:
        name = '%d - ' % track.track_no
    else:
        name = ''
    for artist in track.artists:
        if len(name) > 0:
            name += ', '
        name += artist.name
    if len(name) > 0:
        name += ' - '
    name += track.name
    return Ref.track(uri=track.uri, name=name)

def pretty_str(something, indent=0):
    """Return a human-readable string representation of an object.

        Uses `pretty_str` if the given value is an instance of
        `CodeEntity` and `repr` otherwise.

    Args:
        something: Some value to convert.

    Kwargs:
        indent (int): The amount of spaces to use as indentation."""
    if isinstance(something, CodeEntity):
        return something.pretty_str(indent=indent)
    else:
        return ' ' * indent + repr(something)

def parse_time(val):
    """Parse a time to a `datetime.time` value.
    Can't just use `dateutil.parse.parser(val).time()` because that doesn't preserve tzinfo."""
    dt = parse_date(val)
    if dt.tzinfo is None:
        return dt.time()
    return datetime.time(dt.hour, dt.minute, dt.second, dt.microsecond, dt.tzinfo)

def marshal_value(datatype, value):
    """Marshal a given string into a relevant Python type given the uPnP datatype.
    Assumes that the value has been pre-validated, so performs no checks.
    Returns a tuple pair of a boolean to say whether the value was marshalled and the (un)marshalled
    value."""
    for types, func in MARSHAL_FUNCTIONS:
        if datatype in types:
            return (True, func(value))
    return (False, value)

def discover(timeout=5):
    """Convenience method to discover UPnP devices on the network. Returns a
    list of `upnp.Device` instances. Any invalid servers are silently
    ignored."""
    devices = {}
    for entry in scan(timeout):
        if entry.location in devices:
            continue
        try:
            devices[entry.location] = Device(entry.location)
        except Exception as exc:
            log = _getLogger('ssdp')
            log.error("Error '%s' for %s", exc, entry.location)
    return list(devices.values())

def coroutine(f):
    """A sink should be send `None` first, so that the coroutine arrives
    at the `yield` position. This wrapper takes care that this is done
    automatically when the coroutine is started."""
    @wraps(f)
    def g(*args, **kwargs):
        sink = f(*args, **kwargs)
        sink.send(None)
        return sink
    return g

def maybe(func):
    """Calls `f` in a try/except block, returning a `Fail` object if
    the call fails in any way. If any of the arguments to the call are Fail
    objects, the call is not attempted."""
    name = object_name(func)
    @wraps(func)
    def maybe_wrapped(*args, **kwargs):
        """@maybe wrapped version of ``func``."""
        fails = [(name, k, v) for k, v in chain(enumerate(args), kwargs.items()) if isinstance(v, Fail)]
        if fails:
            return Fail(func, fails=fails)
        try:
            result = func(*args, **kwargs)
        except Exception as exc:
            return Fail(func, exception=exc)
        else:
            if isinstance(result, Fail):
                result.add_call(func)
            return result
    return maybe_wrapped

def is_node_ready(node):
    """Returns True if none of the argument holders contain any `Empty` object.
    """
    return all((ref_argument(node.bound_args, a) is not Empty for a in serialize_arguments(node.bound_args)))

def static_sum(values, limit_n=1000):
    """Example of static sum routine."""
    if len(values) < limit_n:
        return sum(values)
    else:
        half = len(values) // 2
        return add(static_sum(values[:half], limit_n), static_sum(values[half:], limit_n))

def dynamic_sum(values, limit_n=1000, acc=0, depth=4):
    """Example of dynamic sum."""
    if len(values) < limit_n:
        return acc + sum(values)
    if depth > 0:
        half = len(values) // 2
        return add(dynamic_sum(values[:half], limit_n, acc, depth=depth - 1), dynamic_sum(values[half:], limit_n, 0, depth=depth - 1))
    return dynamic_sum(values[limit_n:], limit_n, acc + sum(values[:limit_n]), depth)

def _all_valid(links):
    """Iterates over all links, forgetting emtpy registers."""
    for k, v in links.items():
        for i in v:
            yield (k, i)

def s_find_first(pred, first, lst):
    """Evaluate `first`; if predicate `pred` succeeds on the result of `first`,
    return the result; otherwise recur on the first element of `lst`.

    :param pred: a predicate.
    :param first: a promise.
    :param lst: a list of quoted promises.
    :return: the first element for which predicate is true."""
    if pred(first):
        return first
    elif lst:
        return s_find_first(pred, unquote(lst[0]), lst[1:])
    else:
        return None

def get_workflow_graph(promise):
    """Get a graph of a promise."""
    workflow = get_workflow(promise)
    dot = Digraph()
    for i, n in workflow.nodes.items():
        dot.node(str(i), label='{0} \n {1}'.format(n.foo.__name__, _format_arg_list(n.bound_args.args)))
    for i in workflow.links:
        for j in workflow.links[i]:
            dot.edge(str(i), str(j[0]), label=str(j[1].name))
    return dot

def decorator(f):
    """Creates a paramatric decorator from a function. The resulting decorator
    will optionally take keyword arguments."""
    @functools.wraps(f)
    def decoratored_function(*args, **kwargs):
        if args and len(args) == 1:
            return f(*args, **kwargs)
        if args:
            raise TypeError('This decorator only accepts extra keyword arguments.')
        return lambda g: f(g, **kwargs)
    return decoratored_function

def ref_argument(bound_args, address):
    """Taking a bound_args object, and an ArgumentAddress, retrieves the data
    currently stored in bound_args for this particular address."""
    if address.kind == ArgumentKind.regular:
        return bound_args.arguments[address.name]
    return bound_args.arguments[address.name][address.key]

def set_argument(bound_args, address, value):
    """Taking a bound_args object, and an |ArgumentAddress| and a value, sets
    the value pointed to by the address to `value`."""
    if address.kind == ArgumentKind.regular:
        bound_args.arguments[address.name] = value
        return
    if address.kind == ArgumentKind.variadic:
        if address.name not in bound_args.arguments:
            bound_args.arguments[address.name] = []
        n_args = len(bound_args.arguments[address.name])
        if address.key >= n_args:
            bound_args.arguments[address.name].extend(repeat(Empty, address.key - n_args + 1))
    if address.kind == ArgumentKind.keyword:
        if address.name not in bound_args.arguments:
            bound_args.arguments[address.name] = {}
    bound_args.arguments[address.name][address.key] = value

def format_address(address):
    """Formats an ArgumentAddress for human reading."""
    if address.kind == ArgumentKind.regular:
        return address.name
    return '{0}[{1}]'.format(address.name, address.key)

def run(wf, *, display, n_threads=1):
    """Run the workflow using the dynamic-exclusion worker."""
    worker = dynamic_exclusion_worker(display, n_threads)
    return noodles.Scheduler(error_handler=display.error_handler).run(worker, get_workflow(wf))

def branch(*sinks_):
    """The |branch| decorator creates a |pull| object that pulls from a single
    source and then sends to all the sinks given. After all the sinks received
    the message, it is yielded.

    .. |branch| replace:: :py:func:`branch`"""
    @pull
    def junction(source):
        sinks = [s() for s in sinks_]
        for msg in source():
            for s in sinks:
                s.send(msg)
            yield msg
    return junction

def broadcast(*sinks_):
    """The |broadcast| decorator creates a |push| object that receives a
    message by ``yield`` and then sends this message on to all the given sinks.

    .. |broadcast| replace:: :py:func:`broadcast`"""
    @push
    def bc():
        sinks = [s() for s in sinks_]
        while True:
            msg = (yield)
            for s in sinks:
                s.send(msg)
    return bc

def push_from(iterable):
    """Creates a |push| object from an iterable. The resulting function
    is not a coroutine, but can be chained to another |push|.

    :param iterable: an iterable object.
    :type iterable: :py:class:`~collections.abc.Iterable`
    :rtype: |push|"""
    def p(sink):
        sink = sink()
        for x in iterable:
            sink.send(x)
    return push(p, dont_wrap=True)

def patch(source, sink):
    """Create a direct link between a source and a sink.

    Implementation::

        sink = sink()
        for value in source():
            sink.send(value)

    .. |patch| replace:: :py:func:`patch`"""
    sink = sink()
    for v in source():
        try:
            sink.send(v)
        except StopIteration:
            return

def schedule_branches(b: bool, quoted_true, quoted_false):
    """Helper function to choose which workflow to execute
    based on the boolean `b`.

    :param b:
       promised boolean value

    :param quoted_true:
       quoted workflow to eval if the boolean is true.
    :param quoted_true:
       quoted workflow to eval if the boolean is false."""
    if b:
        return unquote(quoted_true)
    else:
        return unquote(quoted_false)

