def pass_job(db: JobDB, result_queue: Queue, always_cache=False):
    """Create a pull stream that receives jobs and passes them on to the
    database. If the job already has a result, that result is pushed onto
    the `result_queue`."""
    @pull
    def pass_job_stream(job_source):
        """Pull stream instance created by `pass_job`."""
        result_sink = result_queue.sink()
        for message in job_source():
            if message is EndOfQueue:
                return
            key, job = message
            if always_cache or 'store' in job.hints:
                status, retrieved_result = db.add_job_to_db(key, job)
                if status == 'retrieved':
                    result_sink.send(retrieved_result)
                    continue
                elif status == 'attached':
                    continue
            yield message
    return pass_job_stream

def pass_result(db: JobDB, always_cache=False):
    """Creates a pull stream receiving results, storing them in the database,
    then sending them on. At this stage, the database may return a list of
    attached jobs which also need to be sent on to the scheduler."""
    @pull
    def pass_result_stream(worker_source):
        """Pull stream instance created by `pass_result`."""
        for result in worker_source():
            if result is EndOfQueue:
                return
            attached = db.store_result_in_db(result, always_cache=always_cache)
            yield result
            yield from (ResultMessage(key, 'attached', result.value, None) for key in attached)
    return pass_result_stream

def importable(obj):
    """Check if an object can be serialised as a qualified name. This is done
    by checking that a ``look_up(object_name(obj))`` gives back the same
    object.

    .. |importable| replace:: :py:func:`importable`"""
    try:
        return look_up(object_name(obj)) is obj
    except (AttributeError, TypeError, ImportError):
        return False

def is_unwrapped(f):
    """If `f` was imported and then unwrapped, this function might return True.

    .. |is_unwrapped| replace:: :py:func:`is_unwrapped`"""
    try:
        g = look_up(object_name(f))
        return g != f and unwrap(g) == f
    except (AttributeError, TypeError, ImportError):
        return False

def inverse_deep_map(f, root):
    """Sibling to |deep_map|. Recursively maps objects in a nested structure of
    ``list`` and ``dict`` objects. Where |deep_map| starts at the top,
    |inverse_deep_map| starts at the bottom. First, if `root` is a ``list`` or
    ``dict``, its contents are |inverse_deep_map|ed. Then at the end, the
    entire object is passed through `f`.

    This function was created with decoding from JSON compatible data in mind.

    .. |inverse_deep_map| replace:: :py:func:`inverse_deep_map`"""
    if isinstance(root, dict):
        r = {k: inverse_deep_map(f, v) for k, v in root.items()}
    elif isinstance(root, list):
        r = [inverse_deep_map(f, v) for v in root]
    else:
        r = root
    return f(r)

def registry():
    """Returns the Noodles base serialisation registry."""
    return Registry(types={dict: SerDict(), tuple: SerSequence(tuple), set: SerSequence(set), bytes: SerBytes(), slice: SerSlice(), complex: SerByMembers(complex, ['real', 'imag']), Reasonable: SerReasonableObject(Reasonable), ArgumentKind: SerEnum(ArgumentKind), FunctionNode: SerNode(), ArgumentAddress: SerNamedTuple(ArgumentAddress), Workflow: SerWorkflow(), PromisedObject: SerPromisedObject(), Quote: SerReasonableObject(Quote), Path: SerPath(), Fail: SerReasonableObject(Fail)}, hooks={'<method>': SerMethod(), '<boundmethod>': SerBoundMethod(), '<importable>': SerImportable(), '<automagic>': SerAuto(), '<unwrapped>': SerUnwrapped()}, hook_fn=_noodles_hook, default=SerUnknown())

def scheduled_function(f, hints=None):
    """The Noodles schedule function decorator.

    The decorated function will return a workflow in stead of
    being applied immediately. This workflow can then be passed to a job
    scheduler in order to be run on any architecture supporting the current
    python environment."""
    if hints is None:
        hints = {}
    if 'version' not in hints:
        try:
            source_bytes = inspect.getsource(f).encode()
        except Exception:
            pass
        else:
            m = hashlib.md5()
            m.update(source_bytes)
            hints['version'] = m.hexdigest()
    @wraps(f)
    def wrapped(*args, **kwargs):
        return PromisedObject(from_call(f, args, kwargs, deepcopy(hints), call_by_value=config['call_by_value']))
    if hasattr(wrapped, '__doc__') and wrapped.__doc__ is not None:
        wrapped.__doc__ = '*(scheduled)* ' + wrapped.__doc__
    return wrapped

def has_scheduled_methods(cls):
    """Decorator; use this on a class for which some methods have been
    decorated with :func:`schedule` or :func:`schedule_hint`. Those methods
    are then tagged with the attribute `__member_of__`, so that we may
    serialise and retrieve the correct method. This should be considered
    a patch to a flaw in the Python object model."""
    for member in cls.__dict__.values():
        if hasattr(member, '__wrapped__'):
            member.__wrapped__.__member_of__ = cls
    return cls

def worker(job):
    """Primary |worker| coroutine. This is a |pull| object that pulls jobs from
    a source and yield evaluated results.

    Input should be of type |JobMessage|, output of type |ResultMessage|.

    .. |worker| replace:: :py:func::`worker`"""
    if job is EndOfQueue:
        return
    if not isinstance(job, JobMessage):
        print('Warning: Job should be communicated using `JobMessage`.', file=sys.stderr)
    key, node = job
    return run_job(key, node)

def run_job(key, node):
    """Run a job. This applies the function node, and returns a |ResultMessage|
    when complete. If an exception is raised in the job, the |ResultMessage|
    will have ``'error'`` status.

    .. |run_job| replace:: :py:func:`run_job`"""
    try:
        result = node.apply()
        return ResultMessage(key, 'done', result, None)
    except Exception as exc:
        return ResultMessage(key, 'error', None, exc)

def hybrid_coroutine_worker(selector, workers):
    """Runs a set of workers, all of them in the main thread.
    This runner is here for testing purposes.

    :param selector:
        A function returning a worker key, given a job.
    :type selector: function

    :param workers:
        A dict of workers.
    :type workers: dict"""
    jobs = Queue()
    worker_source = {}
    worker_sink = {}
    for k, w in workers.items():
        worker_source[k], worker_sink[k] = w.setup()
    def get_result():
        source = jobs.source()
        for msg in source:
            key, job = msg
            worker = selector(job)
            if worker is None:
                yield run_job(key, job)
            else:
                worker_sink[worker].send(msg)
                result = next(worker_source[worker])
                yield result
    return Connection(get_result, jobs.sink)

def fill_graph(graph, array):
    """Fill a ROOT graph with a NumPy array.

    Parameters
    ----------
    graph : a ROOT TGraph or TGraph2D
        The ROOT graph to fill.
    array : numpy array of shape [n_samples, n_dimensions]
        The values to fill the graph with. The number of columns must match the
        dimensionality of the graph."""
    import ROOT
    array = np.asarray(array, dtype=np.double)
    if isinstance(graph, ROOT.TGraph):
        if array.ndim != 2:
            raise ValueError('array must be 2-dimensional')
        if array.shape[1] != 2:
            raise ValueError('length of the second dimension must equal the dimension of the graph')
        return _librootnumpy.fill_g1(ROOT.AsCObject(graph), array)
    elif isinstance(graph, ROOT.TGraph2D):
        if array.ndim != 2:
            raise ValueError('array must be 2-dimensional')
        if array.shape[1] != 3:
            raise ValueError('length of the second dimension must equal the dimension of the graph')
        return _librootnumpy.fill_g2(ROOT.AsCObject(graph), array)
    else:
        raise TypeError('hist must be an instance of ROOT.TGraph or ROOT.TGraph2D')

def _glob(filenames):
    """Glob a filename or list of filenames but always return the original
    string if the glob didn't match anything so URLs for remote file access
    are not clobbered."""
    if isinstance(filenames, string_types):
        filenames = [filenames]
    matches = []
    for name in filenames:
        matched_names = glob(name)
        if not matched_names:
            matches.append(name)
        else:
            matches.extend(matched_names)
    return matches

def extract_docstring(filename):
    """Extract a module-level docstring, if any
    """
    lines = file(filename).readlines()
    start_row = 0
    if lines[0].startswith('#!'):
        lines.pop(0)
        start_row = 1
    docstring = ''
    first_par = ''
    tokens = tokenize.generate_tokens(iter(lines).next)
    for tok_type, tok_content, _, (erow, _), _ in tokens:
        tok_type = token.tok_name[tok_type]
        if tok_type in ('NEWLINE', 'COMMENT', 'NL', 'INDENT', 'DEDENT'):
            continue
        elif tok_type == 'STRING':
            docstring = eval(tok_content)
            paragraphs = '\n'.join((line.rstrip() for line in docstring.split('\n'))).split('\n\n')
            if len(paragraphs) > 0:
                first_par = paragraphs[0]
        break
    end_row = erow + 1 + start_row
    if lines and lines[end_row - 2] == 'print(__doc__)\n':
        end_row += 1
    return (docstring, first_par, end_row)

def generate_example_rst(app):
    """Generate the list of examples, as well as the contents of
    examples."""
    root_dir = os.path.join(app.builder.srcdir, 'auto_examples')
    example_dir = os.path.abspath(app.builder.srcdir + '/../' + 'examples')
    try:
        plot_gallery = eval(app.builder.config.plot_gallery)
    except TypeError:
        plot_gallery = bool(app.builder.config.plot_gallery)
    if not os.path.exists(example_dir):
        os.makedirs(example_dir)
    if not os.path.exists(root_dir):
        os.makedirs(root_dir)
    fhindex = file(os.path.join(root_dir, 'index.rst'), 'w')
    fhindex.write('
.. raw:: html


    <style type="text/css">

    div#sidebarbutton {
        display: none;
    }

    .figure {
        float: left;
        margin: 10px;
        width: auto;
        height: 200px;
        width: 180px;
    }

    .figure img {
        display: inline;
        }

    .figure .caption {
        width: 170px;
        text-align: center !important;
    }
    </style>

.. _examples-index:

Examples
========

')
    generate_dir_rst('.', fhindex, example_dir, root_dir, plot_gallery)
    for dir in sorted(os.listdir(example_dir)):
        if os.path.isdir(os.path.join(example_dir, dir)):
            generate_dir_rst(dir, fhindex, example_dir, root_dir, plot_gallery)
    fhindex.flush()

def generate_dir_rst(dir, fhindex, example_dir, root_dir, plot_gallery):
    """Generate the rst file for an example directory.
    """
    if not dir == '.':
        target_dir = os.path.join(root_dir, dir)
        src_dir = os.path.join(example_dir, dir)
    else:
        target_dir = root_dir
        src_dir = example_dir
    if not os.path.exists(os.path.join(src_dir, 'README.txt')):
        print('Example directory %s does not have a README.txt file' % src_dir)
        print('Skipping this directory')
        print(80 * '_')
        return
