def Binary(x):
    """Return x as a binary type."""
    if isinstance(x, text_type) and (not (JYTHON or IRONPYTHON)):
        return x.encode()
    return bytes(x)

def convert_datetime(obj):
    """Returns a DATETIME or TIMESTAMP column value as a datetime object:

      >>> datetime_or_None('2007-02-25 23:06:20')
      datetime.datetime(2007, 2, 25, 23, 6, 20)
      >>> datetime_or_None('2007-02-25T23:06:20')
      datetime.datetime(2007, 2, 25, 23, 6, 20)

    Illegal values are returned as None:

      >>> datetime_or_None('2007-02-31T23:06:20') is None
      True
      >>> datetime_or_None('0000-00-00 00:00:00') is None
      True"""
    if ' ' in obj:
        sep = ' '
    elif 'T' in obj:
        sep = 'T'
    else:
        return convert_date(obj)
    try:
        ymd, hms = obj.split(sep, 1)
        usecs = '0'
        if '.' in hms:
            hms, usecs = hms.split('.')
        usecs = float('0.' + usecs) * 1000000.0
        return datetime.datetime(*[int(x) for x in ymd.split('-') + hms.split(':') + [usecs]])
    except ValueError:
        return convert_date(obj)

def convert_date(obj):
    """Returns a DATE column as a date object:

      >>> date_or_None('2007-02-26')
      datetime.date(2007, 2, 26)

    Illegal values are returned as None:

      >>> date_or_None('2007-02-31') is None
      True
      >>> date_or_None('0000-00-00') is None
      True"""
    try:
        return datetime.date(*[int(x) for x in obj.split('-', 2)])
    except ValueError:
        return None

def partition(list_, columns=2):
    """Break a list into ``columns`` number of columns."""
    iter_ = iter(list_)
    columns = int(columns)
    rows = []
    while True:
        row = []
        for column_number in range(1, columns + 1):
            try:
                value = six.next(iter_)
            except StopIteration:
                pass
            else:
                row.append(value)
        if not row:
            return rows
        rows.append(row)

def _build_sentence(word):
    """Builds a Pinyin sentence re pattern from a Pinyin word re pattern.

    A sentence is defined as a series of valid Pinyin words, punctuation
    (non-stops), and spaces followed by a single stop and zero or more
    container-closing punctuation marks (e.g. apostrophe and brackets)."""
    return '(?:{word}|[{non_stops}]|(?<![{stops} ]) )+[{stops}][\'"\\]\\}}\\)]*'.format(word=word, non_stops=non_stops.replace('-', '\\-'), stops=stops)

def OrderReplicates(replicates, K):
    """Inputs: An array of replicates, and the size of the data.

    Outputs: a Nxdims arrary of the data in the replicates, normalized by the standard deviation"""
    dims = np.shape(replicates[0]['destimated'])
    sigma = replicates[0]['destimated']
    zerosigma = sigma == 0
    sigmacorr = zerosigma
    sigma += sigmacorr
    yi = []
    for replicate_index, replicate in enumerate(replicates):
        yi.append(replicate['error'] / sigma)
    yiarray = np.asarray(yi)
    sortedyi = np.zeros(np.shape(yiarray))
    if len(dims) == 0:
        sortedyi[:] = np.sort(yiarray)
    elif len(dims) == 1:
        for i in range(K):
            sortedyi[:, i] = np.sort(yiarray[:, i])
    elif len(dims) == 2:
        for i in range(K):
            for j in range(K):
                sortedyi[:, i, j] = np.sort(yiarray[:, i, j])
    sigma -= sigmacorr
    return sortedyi

def to_str(data):
    """Takes an input str or bytes object and returns an equivalent str object.

    :param data: Input data
    :type data: str or bytes
    :returns: Data normalized to str
    :rtype: str"""
    if isinstance(data, bytes):
        return codecs.decode(data, TEXT_ENCODING)
    return data

def to_bytes(data):
    """Takes an input str or bytes object and returns an equivalent bytes object.

    :param data: Input data
    :type data: str or bytes
    :returns: Data normalized to bytes
    :rtype: bytes"""
    if isinstance(data, six.string_types) and (not isinstance(data, bytes)):
        return codecs.encode(data, TEXT_ENCODING)
    return data

