def _string_to_sign(item, table_name, attribute_actions):
    """Generate the string to sign from an encrypted item and configuration.

    :param dict item: Encrypted DynamoDB item
    :param str table_name: Table name to use when generating the string to sign
    :param AttributeActions attribute_actions: Actions to take for item"""
    hasher = hashes.Hash(hashes.SHA256(), backend=default_backend())
    data_to_sign = bytearray()
    data_to_sign.extend(_hash_data(hasher=hasher, data='TABLE>{}<TABLE'.format(table_name).encode(TEXT_ENCODING)))
    for key in sorted(item.keys()):
        action = attribute_actions.action(key)
        if action is CryptoAction.DO_NOTHING:
            continue
        data_to_sign.extend(_hash_data(hasher=hasher, data=key.encode(TEXT_ENCODING)))
        if action is CryptoAction.SIGN_ONLY:
            data_to_sign.extend(SignatureValues.PLAINTEXT.sha256)
        else:
            data_to_sign.extend(SignatureValues.ENCRYPTED.sha256)
        data_to_sign.extend(_hash_data(hasher=hasher, data=serialize_attribute(item[key])))
    return bytes(data_to_sign)

def serialize(material_description):
    """Serialize a material description dictionary into a DynamodDB attribute.

    :param dict material_description: Material description dictionary
    :returns: Serialized material description as a DynamoDB binary attribute value
    :rtype: dict
    :raises InvalidMaterialDescriptionError: if invalid name or value found in material description"""
    material_description_bytes = bytearray(_MATERIAL_DESCRIPTION_VERSION)
    for name, value in sorted(material_description.items(), key=lambda x: x[0]):
        try:
            material_description_bytes.extend(encode_value(to_bytes(name)))
            material_description_bytes.extend(encode_value(to_bytes(value)))
        except (TypeError, struct.error):
            raise InvalidMaterialDescriptionError('Invalid name or value in material description: "{name}"="{value}"'.format(name=name, value=value))
    return {Tag.BINARY.dynamodb_tag: bytes(material_description_bytes)}

def dictionary_validator(key_type, value_type):
    """Validator for ``attrs`` that performs deep type checking of dictionaries."""
    def _validate_dictionary(instance, attribute, value):
        """Validate that a dictionary is structured as expected.

        :raises TypeError: if ``value`` is not a dictionary
        :raises TypeError: if ``value`` keys are not all of ``key_type`` type
        :raises TypeError: if ``value`` values are not all of ``value_type`` type"""
        if not isinstance(value, dict):
            raise TypeError('"{}" must be a dictionary'.format(attribute.name))
        for key, data in value.items():
            if not isinstance(key, key_type):
                raise TypeError('"{name}" dictionary keys must be of type "{type}"'.format(name=attribute.name, type=key_type))
            if not isinstance(data, value_type):
                raise TypeError('"{name}" dictionary values must be of type "{type}"'.format(name=attribute.name, type=value_type))
    return _validate_dictionary

def iterable_validator(iterable_type, member_type):
    """Validator for ``attrs`` that performs deep type checking of iterables."""
    def _validate_tuple(instance, attribute, value):
        """Validate that a dictionary is structured as expected.

        :raises TypeError: if ``value`` is not of ``iterable_type`` type
        :raises TypeError: if ``value`` members are not all of ``member_type`` type"""
        if not isinstance(value, iterable_type):
            raise TypeError('"{name}" must be a {type}'.format(name=attribute.name, type=iterable_type))
        for member in value:
            if not isinstance(member, member_type):
                raise TypeError('"{name}" members must all be of type "{type}"'.format(name=attribute.name, type=member_type))
    return _validate_tuple

def callable_validator(instance, attribute, value):
    """Validate that an attribute value is callable.

    :raises TypeError: if ``value`` is not callable"""
    if not callable(value):
        raise TypeError('"{name}" value "{value}" must be callable'.format(name=attribute.name, value=value))

def _validate_attribute_values_are_ddb_items(instance, attribute, value):
    """Validate that dictionary values in ``value`` match the structure of DynamoDB JSON
    items.

    .. note::

        We are not trying to validate the full structure of the item with this validator.
        This is just meant to verify that the values roughly match the correct format."""
    for data in value.values():
        if len(list(data.values())) != 1:
            raise TypeError('"{}" values do not look like DynamoDB items'.format(attribute.name))

def crypto_config_from_kwargs(fallback, **kwargs):
    """Pull all encryption-specific parameters from the request and use them to build a crypto config.

    :returns: crypto config and updated kwargs
    :rtype: dynamodb_encryption_sdk.encrypted.CryptoConfig and dict"""
    try:
        crypto_config = kwargs.pop('crypto_config')
    except KeyError:
        try:
            fallback_kwargs = {'table_name': kwargs['TableName']}
        except KeyError:
            fallback_kwargs = {}
        crypto_config = fallback(**fallback_kwargs)
    return (crypto_config, kwargs)

def crypto_config_from_table_info(materials_provider, attribute_actions, table_info):
    """Build a crypto config from the provided values and table info.

    :returns: crypto config and updated kwargs
    :rtype: tuple(CryptoConfig, dict)"""
    ec_kwargs = table_info.encryption_context_values
    if table_info.primary_index is not None:
        ec_kwargs.update({'partition_key_name': table_info.primary_index.partition, 'sort_key_name': table_info.primary_index.sort})
    return CryptoConfig(materials_provider=materials_provider, encryption_context=EncryptionContext(**ec_kwargs), attribute_actions=attribute_actions)

def decrypt_batch_get_item(decrypt_method, crypto_config_method, read_method, **kwargs):
    """Transparently decrypt multiple items after getting them in a batch request.

    :param callable decrypt_method: Method to use to decrypt items
    :param callable crypto_config_method: Method that accepts ``kwargs`` and provides a :class:`CryptoConfig`
    :param callable read_method: Method that reads from the table
    :param **kwargs: Keyword arguments to pass to ``read_method``
    :return: DynamoDB response
    :rtype: dict"""
    request_crypto_config = kwargs.pop('crypto_config', None)
    for _table_name, table_kwargs in kwargs['RequestItems'].items():
        validate_get_arguments(table_kwargs)
    response = read_method(**kwargs)
    for table_name, items in response['Responses'].items():
        if request_crypto_config is not None:
            crypto_config = request_crypto_config
        else:
            crypto_config = crypto_config_method(table_name=table_name)
        for pos, value in enumerate(items):
            items[pos] = decrypt_method(item=value, crypto_config=crypto_config.with_item(_item_transformer(decrypt_method)(items[pos])))
    return response

def encrypt_batch_write_item(encrypt_method, crypto_config_method, write_method, **kwargs):
    """Transparently encrypt multiple items before putting them in a batch request.

    :param callable encrypt_method: Method to use to encrypt items
    :param callable crypto_config_method: Method that accepts a table name string and provides a :class:`CryptoConfig`
    :param callable write_method: Method that writes to the table
    :param **kwargs: Keyword arguments to pass to ``write_method``
    :return: DynamoDB response
    :rtype: dict"""
    request_crypto_config = kwargs.pop('crypto_config', None)
    table_crypto_configs = {}
    plaintext_items = copy.deepcopy(kwargs['RequestItems'])
    for table_name, items in kwargs['RequestItems'].items():
        if request_crypto_config is not None:
            crypto_config = request_crypto_config
        else:
            crypto_config = crypto_config_method(table_name=table_name)
        table_crypto_configs[table_name] = crypto_config
        for pos, value in enumerate(items):
            for request_type, item in value.items():
                if request_type == 'PutRequest':
                    items[pos][request_type]['Item'] = encrypt_method(item=item['Item'], crypto_config=crypto_config.with_item(_item_transformer(encrypt_method)(item['Item'])))
    response = write_method(**kwargs)
    return _process_batch_write_response(plaintext_items, response, table_crypto_configs)

def _load_library(library_names, library_file_extensions, library_search_paths, version_check_callback):
    """Finds, loads and returns the most recent version of the library."""
    candidates = _find_library_candidates(library_names, library_file_extensions, library_search_paths)
    library_versions = []
    for filename in candidates:
        version = version_check_callback(filename)
        if version is not None and version >= (3, 0, 0):
            library_versions.append((version, filename))
    if not library_versions:
        return None
    library_versions.sort()
    return ctypes.CDLL(library_versions[-1][1])

def _get_library_search_paths():
    """Returns a list of library search paths, considering of the current working
    directory, default paths and paths from environment variables."""
    search_paths = ['', '/usr/lib64', '/usr/local/lib64', '/usr/lib', '/usr/local/lib', '/run/current-system/sw/lib', '/usr/lib/x86_64-linux-gnu/', os.path.abspath(os.path.dirname(__file__))]
    if sys.platform == 'darwin':
        path_environment_variable = 'DYLD_LIBRARY_PATH'
    else:
        path_environment_variable = 'LD_LIBRARY_PATH'
    if path_environment_variable in os.environ:
        search_paths.extend(os.environ[path_environment_variable].split(':'))
    return search_paths

def _prepare_errcheck():
    """This function sets the errcheck attribute of all ctypes wrapped functions
    to evaluate the _exc_info_from_callback global variable and re-raise any
    exceptions that might have been raised in callbacks.
    It also modifies all callback types to automatically wrap the function
    using the _callback_exception_decorator."""
    def errcheck(result, *args):
        global _exc_info_from_callback
        if _exc_info_from_callback is not None:
            exc = _exc_info_from_callback
            _exc_info_from_callback = None
            _reraise(exc[1], exc[2])
        return result
    for symbol in dir(_glfw):
        if symbol.startswith('glfw'):
            getattr(_glfw, symbol).errcheck = errcheck
    _globals = globals()
    for symbol in _globals:
        if symbol.startswith('_GLFW') and symbol.endswith('fun'):
            def wrapper_cfunctype(func, cfunctype=_globals[symbol]):
                return cfunctype(_callback_exception_decorator(func))
            _globals[symbol] = wrapper_cfunctype

