def do_page_has_content(parser, token):
    """Conditional tag that only renders its nodes if the page
    has content for a particular content type. By default the
    current page is used.

    Syntax::

        {% page_has_content <content_type> [<page var name>] %}
            ...
        {%_end page_has_content %}

    Example use::

        {% page_has_content 'header-image' %}
            <img src="{{ MEDIA_URL }}{% imageplaceholder 'header-image' %}">
        {% end_page_has_content %}"""
    nodelist = parser.parse(('end_page_has_content',))
    parser.delete_first_token()
    args = token.split_contents()
    try:
        content_type = unescape_string_literal(args[1])
    except IndexError:
        raise template.TemplateSyntaxError('%r tag requires the argument content_type' % args[0])
    if len(args) > 2:
        page = args[2]
    else:
        page = None
    return PageHasContentNode(page, content_type, nodelist)

def remove_slug(path):
    """Return the remainin part of the path

        >>> remove_slug('/test/some/function/')
        test/some"""
    if path.endswith('/'):
        path = path[:-1]
    if path.startswith('/'):
        path = path[1:]
    if '/' not in path or not path:
        return None
    parts = path.split('/')[:-1]
    return '/'.join(parts)

def get_template_from_request(request, page=None):
    """Gets a valid template from different sources or falls back to the
    default template."""
    page_templates = settings.get_page_templates()
    if len(page_templates) == 0:
        return settings.PAGE_DEFAULT_TEMPLATE
    template = request.POST.get('template', request.GET.get('template', None))
    if template is not None and (template in list(dict(page_templates).keys()) or template == settings.PAGE_DEFAULT_TEMPLATE):
        return template
    if page is not None:
        return page.get_template()
    return settings.PAGE_DEFAULT_TEMPLATE

def get_language_from_request(request):
    """Return the most obvious language according the request."""
    language = request.GET.get('language', None)
    if language:
        return language
    if hasattr(request, 'LANGUAGE_CODE'):
        lang = settings.PAGE_LANGUAGE_MAPPING(str(request.LANGUAGE_CODE))
        if lang not in LANGUAGE_KEYS:
            return settings.PAGE_DEFAULT_LANGUAGE
        else:
            return lang
    else:
        return settings.PAGE_DEFAULT_LANGUAGE

def automatic_slug_renaming(slug, is_slug_safe):
    """Helper to add numbers to slugs"""
    if not isinstance(is_slug_safe, collections.Callable):
        raise TypeError('is_slug_safe must be callable')
    if is_slug_safe(slug):
        return slug
    count = 2
    new_slug = slug + '-' + str(count)
    while not is_slug_safe(new_slug):
        count = count + 1
        new_slug = slug + '-' + str(count)
    return new_slug

