def _unescape(v):
    """Unescape characters in a TOML string."""
    i = 0
    backslash = False
    while i < len(v):
        if backslash:
            backslash = False
            if v[i] in _escapes:
                v = v[:i - 1] + _escape_to_escapedchars[v[i]] + v[i + 1:]
            elif v[i] == '\\':
                v = v[:i - 1] + v[i:]
            elif v[i] == 'u' or v[i] == 'U':
                i += 1
            else:
                raise TomlDecodeError('Reserved escape sequence used')
            continue
        elif v[i] == '\\':
            backslash = True
        i += 1
    return v

def dumps(o, preserve=False):
    """Stringifies input dict as toml

    Args:
        o: Object to dump into toml

        preserve: Boolean parameter. If true, preserve inline tables.

    Returns:
        String containing the toml corresponding to dict"""
    retval = ''
    addtoretval, sections = _dump_sections(o, '')
    retval += addtoretval
    while sections != {}:
        newsections = {}
        for section in sections:
            addtoretval, addtosections = _dump_sections(sections[section], section, preserve)
            if addtoretval or (not addtoretval and (not addtosections)):
                if retval and retval[-2:] != '\n\n':
                    retval += '\n'
                retval += '[' + section + ']\n'
                if addtoretval:
                    retval += addtoretval
            for s in addtosections:
                newsections[section + '.' + s] = addtosections[s]
        sections = newsections
    return retval

def _dump_inline_table(section):
    """Preserve inline table in its compact syntax instead of expanding
    into subsection.

    https://github.com/toml-lang/toml#user-content-inline-table"""
    retval = ''
    if isinstance(section, dict):
        val_list = []
        for k, v in section.items():
            val = _dump_inline_table(v)
            val_list.append(k + ' = ' + val)
        retval += '{ ' + ', '.join(val_list) + ' }\n'
        return retval
    else:
        return str(_dump_value(section))

def setuptools_parse_requirements_backport(strs):
    """Yield ``Requirement`` objects for each specification in `strs`

    `strs` must be a string, or a (possibly-nested) iterable thereof."""
    def yield_lines(strs):
        """Yield non-empty/non-comment lines of a string or sequence"""
        if isinstance(strs, six.string_types):
            for s in strs.splitlines():
                s = s.strip()
                if s and (not s.startswith('#')):
                    yield s
        else:
            for ss in strs:
                for s in yield_lines(ss):
                    yield s
    lines = iter(yield_lines(strs))
    for line in lines:
        if ' #' in line:
            line = line[:line.find(' #')]
        if line.endswith('\\'):
            line = line[:-2].strip()
            line += next(lines)
        yield PackagingRequirement(line)

def _load_ini(path):
