        downloader = AVAILABLE_ICON_FONTS[icon_font]['downloader'](directory)
        downloader.download_files()
        return downloader
    except KeyError:
        raise Exception("We don't support downloading font '{name}'".format(name=icon_font))

def autoconfig_url_from_preferences():
    """Get the PAC ``AutoConfigURL`` value from the macOS System Preferences.
    This setting is visible as the "URL" field in
    System Preferences > Network > Advanced... > Proxies > Automatic Proxy Configuration.

    :return: The value from the registry, or None if the value isn't configured or available.
        Note that it may be local filesystem path instead of a URL.
    :rtype: str|None
    :raises NotDarwinError: If called on a non-macOS/OSX platform."""
    if not ON_DARWIN:
        raise NotDarwinError()
    try:
        config = SystemConfiguration.SCDynamicStoreCopyProxies(None)
    except AttributeError:
        return
    if all(('ProxyAutoConfigEnable' in config, 'ProxyAutoConfigURLString' in config, not config.get('ProxyAutoDiscoveryEnable', 0))):
        return str(config['ProxyAutoConfigURLString'])

def file_url_to_local_path(file_url):
    """Parse a ``AutoConfigURL`` value with ``file://`` scheme into a usable local filesystem path.

    :param file_url: Must start with ``file://``.
    :return: A local filesystem path. It might not exist."""
    parts = urlparse(file_url)
    path = unquote(parts.path)
    if path.startswith('/') and (not path.startswith('//')):
        if ON_DARWIN:
            return path
        if len(parts.netloc) == 2 and parts.netloc[1] == ':':
            return parts.netloc + path
        return 'C:' + path
    if len(path) > 2 and path[1] == ':':
        return path

def add_proxy_auth(possible_proxy_url, proxy_auth):
    """Add a username and password to a proxy URL, if the input value is a proxy URL.

    :param str possible_proxy_url: Proxy URL or ``DIRECT``.
    :param requests.auth.HTTPProxyAuth proxy_auth: Proxy authentication info.
    :returns: Proxy URL with auth info added, or ``DIRECT``.
    :rtype: str"""
    if possible_proxy_url == 'DIRECT':
        return possible_proxy_url
    parsed = urlparse(possible_proxy_url)
    return '{0}://{1}:{2}@{3}'.format(parsed.scheme, proxy_auth.username, proxy_auth.password, parsed.netloc)

def collect_pac_urls(from_os_settings=True, from_dns=True, **kwargs):
    """Get all the URLs that potentially yield a PAC file.

    :param bool from_os_settings: Look for a PAC URL from the OS settings.
        If a value is found and is a URL, it comes first in the returned list.
        Doesn't do anything on non-Windows or non-macOS/OSX platforms.
    :param bool from_dns: Assemble a list of PAC URL candidates using the WPAD protocol.
    :return: A list of URLs that should be tried in order.
    :rtype: list[str]"""
    from_registry = kwargs.get('from_registry')
    if from_registry is not None:
        import warnings
        warnings.warn('from_registry is deprecated, use from_os_settings instead.')
        from_os_settings = from_registry
    pac_urls = []
    if from_os_settings:
        if ON_WINDOWS:
            url_or_path = autoconfig_url_from_registry()
        elif ON_DARWIN:
            url_or_path = autoconfig_url_from_preferences()
        else:
            url_or_path = None
        if url_or_path and (url_or_path.lower().startswith('http://') or url_or_path.lower().startswith('https://')):
            pac_urls.append(url_or_path)
    if from_dns:
        pac_urls.extend(proxy_urls_from_dns())
    return pac_urls

def proxy_url(value, socks_scheme=None):
    """Parse a single proxy config value from FindProxyForURL() into a more usable element.

    :param str value: Value to parse, e.g.: ``DIRECT``, ``PROXY example.local:8080``, or ``SOCKS example.local:8080``.
    :param str socks_scheme: Scheme to assume for SOCKS proxies. ``socks5`` by default.
    :returns: Parsed value, e.g.: ``DIRECT``, ``http://example.local:8080``, or ``socks5://example.local:8080``.
    :rtype: str
    :raises ValueError: If input value is invalid."""
    if value.upper() == 'DIRECT':
        return 'DIRECT'
    parts = value.split()
    if len(parts) == 2:
        keyword, proxy = (parts[0].upper(), parts[1])
        if keyword == 'PROXY':
            return 'http://' + proxy
        if keyword == 'SOCKS':
            if not socks_scheme:
                socks_scheme = 'socks5'
            return '{0}://{1}'.format(socks_scheme, proxy)
    raise ValueError("Unrecognized proxy config value '{}'".format(value))

def dnsDomainIs(host, domain):
    """:param str host: is the hostname from the URL.
    :param str domain: is the domain name to test the hostname against.
    :return: true iff the domain of hostname matches.
    :rtype: bool"""
    if domain.startswith('.'):
        domain = '*' + domain
    return shExpMatch(host, domain)

def set_monitor(module):
    """Defines the monitor method on the module."""
    def monitor(name, tensor, track_data=True, track_grad=True):
        """Register the tensor under the name given (now a string)
        and track it based on the track_data and track_grad arguments."""
        module.monitored_vars[name] = {'tensor': tensor, 'track_data': track_data, 'track_grad': track_grad}
    module.monitor = monitor

def grad_hook(module, name, writer, bins):
    """Factory for grad_hook closures"""
    def hook(grad):
        writer.add_histogram('{}/grad'.format(name.replace('.', '/')), grad.detach().cpu().numpy(), module.global_step - 1, bins=bins)
    return hook

def remove_grad_hooks(module, input):
    """Remove gradient hooks to all of the parameters and monitored vars"""
    for hook in list(module.param_hooks.keys()):
        module.param_hooks[hook].remove()
        module.param_hooks.pop(hook)
    for hook in list(module.var_hooks.keys()):
        module.var_hooks[hook].remove()
        module.var_hooks.pop(hook)

def commit(experiment_name, time):
    """Try to commit repo exactly as it is when starting the experiment for reproducibility."""
    try:
        sh.git.commit('-a', m='"auto commit tracked files for new experiment: {} on {}"'.format(experiment_name, time), allow_empty=True)
        commit_hash = sh.git('rev-parse', 'HEAD').strip()
        return commit_hash
    except:
        return '<Unable to commit>'

def parse_ports(ports_text):
    '''Parse ports text

    e.g. ports_text = "12345,13000-15000,20000-30000"'''
    ports_set = set()
    for bit in ports_text.split(','):
        if '-' in bit:
            low, high = bit.split('-', 1)
            ports_set = ports_set.union(range(int(low), int(high) + 1))
        else:
            ports_set.add(int(bit))
    return sorted(list(ports_set))

def become_daemon(*args, **kwargs):
    """become_daemon function wrapper

    In Django 1.9, 'become_daemon' is removed.
    It means compatibility."""
    if django.VERSION >= (1, 9):
        from .daemonize import become_daemon
    else:
        from django.utils.daemonize import become_daemon
    return become_daemon(*args, **kwargs)

def showref():
    """Like :func:`getref` but print results to screen instead of returning
    a dictionary."""
    refdata = getref()
    for k, v in refdata.items():
        print('%10s: %s' % (k, v))

def read_kwfile(fname):
    """Syntax used as of r452 in commissioning tests"""
    d = {}
    f = open(fname)
    for line in f:
        try:
            kvpair = re.findall('(.*):: (.*)=(.*)$', line)[0]
            d['name'] = os.path.basename(kvpair[0])
            key, val = kvpair[1:]
            d[key.lower()] = val
        except (ValueError, IndexError):
            break
    f.close()
    return d

def classify_file(f):
    '''Examine the column names to determine which type of file
    this is. Return a tuple:
    retvalue[0] = "file is non-parameterized"
    retvalue[1] = "file contains error column"'''
    cols = f[1].columns
    if len(cols) == 2:
        return (True, False)
    elif len(cols) == 3 and 'ERROR' in cols.names:
        return (True, True)
    elif len(cols) > 2 and 'ERROR' not in cols.names:
        return (True, False)
    else:
        return (False, True)

def get_data_filename(filename):
    """Map filename to its actual path.

    Parameters
    ----------
    filename : str
        Filename to search.

    Returns
    -------
    path : str
        Full path to the file in data directory."""
    global _data_map
    if _data_map is None:
        _data_map = {}
        for root, dirs, files in os.walk(specdir):
            for fname in files:
                _data_map[fname] = os.path.join(root, fname)
    if filename not in _data_map:
        raise KeyError(filename + ' not found in ' + specdir)
    return _data_map[filename]

def setdirs(outfiles):
    """Create the directories if need be"""
    for k in outfiles:
        fname = outfiles[k]
        dname = os.path.dirname(fname)
        if not os.path.isdir(dname):
            os.mkdir(dname)

def Units(uname):
    """Generate a unit object.

    Parameters
    ----------
    uname : str
        Wavelength or flux unit name.

    Returns
    -------
    unit : `BaseUnit` or `None`
        Unit object. `None` means unitless.

    Raises
    ------
    ValueError
        Unknown unit name."""
    if isinstance(uname, BaseUnit):
        return uname
    else:
        try:
            if issubclass(uname, BaseUnit):
                return uname()
        except TypeError:
            try:
                return factory(uname)
            except KeyError:
                if uname == str(None):
                    return None
                else:
                    raise ValueError('Unknown units %s' % uname)

def ismatch(a, b):
    """Method to allow smart comparisons between classes, instances,
    and string representations of units and give the right answer.
    For internal use only."""
    if a == b:
        return True
    else:
        try:
            if isinstance(a, b):
                return True
        except TypeError:
            try:
                if isinstance(b, a):
                    return True
            except TypeError:
                try:
                    if isinstance(a, type(b)):
                        return True
                except TypeError:
                    try:
                        if isinstance(b, type(a)):
                            return True
                    except TypeError:
                        if str(a).lower() == str(b).lower():
                            return True
                        else:
                            return False

def _fields_list_to_dict(fields):
    """Takes a list of field names and returns a matching dictionary.

    ["a", "b"] becomes {"a": 1, "b": 1}

    and

    ["a.b.c", "d", "a.c"] becomes {"a.b.c": 1, "d": 1, "a.c": 1}"""
    for key in fields:
        assert isinstance(key, (str, unicode))
    return dict([[key, 1] for key in fields])

def _index_document(index_list):
    """Helper to generate an index specifying document.

    Takes a list of (key, direction) pairs."""
    if isinstance(index_list, dict):
        raise TypeError('passing a dict to sort/create_index/hint is not allowed - use a list of tuples instead. did you mean %r?' % list(index_list.iteritems()))
    elif not isinstance(index_list, list):
        raise TypeError('must use a list of (key, direction) pairs, not: ' + repr(index_list))
    if not len(index_list):
        raise ValueError('key_or_list must not be the empty list')
    index = SON()
    for key, value in index_list:
        if not isinstance(key, basestring):
            raise TypeError('first item in each key pair must be a string')
        if value not in [ASCENDING, DESCENDING, GEO2D]:
            raise TypeError('second item in each key pair must be ASCENDING, DESCENDING, or GEO2D')
        index[key] = value
    return index

def _password_digest(username, password):
    """Get a password digest to use for authentication.
    """
    if not isinstance(password, basestring):
        raise TypeError('password must be an instance of basestring')
    if not isinstance(username, basestring):
        raise TypeError('username must be an instance of basestring')
    md5hash = hashlib.md5()
    md5hash.update('%s:mongo:%s' % (username.encode('utf-8'), password.encode('utf-8')))
    return unicode(md5hash.hexdigest())

def update_context(app, pagename, templatename, context, doctree):
    """Remove sphinx-tabs CSS and JS asset files if not used in a page"""
    if doctree is None:
        return
    visitor = _FindTabsDirectiveVisitor(doctree)
    doctree.walk(visitor)
    if not visitor.found_tabs_directive:
        paths = [posixpath.join('_static', 'sphinx_tabs/' + f) for f in FILES]
        if 'css_files' in context:
            context['css_files'] = context['css_files'][:]
            for path in paths:
                if path.endswith('.css'):
                    context['css_files'].remove(path)
        if 'script_files' in context:
            context['script_files'] = context['script_files'][:]
            for path in paths:
                if path.endswith('.js'):
                    context['script_files'].remove(path)

def copy_assets(app, exception):
    """Copy asset files to the output"""
    if 'getLogger' in dir(logging):
        log = logging.getLogger(__name__).info
    else:
        log = app.info
    builders = get_compatible_builders(app)
    if exception:
        return
    if app.builder.name not in builders:
        if not app.config['sphinx_tabs_nowarn']:
            app.warn('Not copying tabs assets! Not compatible with %s builder' % app.builder.name)
        return
    log('Copying tabs assets')
    installdir = os.path.join(app.builder.outdir, '_static', 'sphinx_tabs')
    for path in FILES:
        source = resource_filename('sphinx_tabs', path)
        dest = os.path.join(installdir, path)
        destdir = os.path.dirname(dest)
        if not os.path.exists(destdir):
            os.makedirs(destdir)
        copyfile(source, dest)

def setup(app):
    """Set up the plugin"""
    app.add_config_value('sphinx_tabs_nowarn', False, '')
    app.add_config_value('sphinx_tabs_valid_builders', [], '')
    app.add_directive('tabs', TabsDirective)
    app.add_directive('tab', TabDirective)
    app.add_directive('group-tab', GroupTabDirective)
    app.add_directive('code-tab', CodeTabDirective)
    for path in ['sphinx_tabs/' + f for f in FILES]:
        if path.endswith('.css'):
            if 'add_css_file' in dir(app):
                app.add_css_file(path)
            else:
                app.add_stylesheet(path)
        if path.endswith('.js'):
            if 'add_script_file' in dir(app):
                app.add_script_file(path)
            else:
                app.add_javascript(path)
    app.connect('html-page-context', update_context)
    app.connect('build-finished', copy_assets)

def insert(collection_name, docs, check_keys, safe, last_error_args):
    """Get an **insert** message.
    """
    data = __ZERO
    data += bson._make_c_string(collection_name)
    bson_data = ''.join([bson.BSON.encode(doc, check_keys) for doc in docs])
    if not bson_data:
        raise InvalidOperation('cannot do an empty bulk insert')
    data += bson_data
    if safe:
        _, insert_message = __pack_message(2002, data)
        request_id, error_message = __last_error(last_error_args)
        return (request_id, insert_message + error_message)
    else:
        return __pack_message(2002, data)

def update(collection_name, upsert, multi, spec, doc, safe, last_error_args):
    """Get an **update** message.
    """
    options = 0
    if upsert:
        options += 1
    if multi:
        options += 2
    data = __ZERO
    data += bson._make_c_string(collection_name)
    data += struct.pack('<i', options)
    data += bson.BSON.encode(spec)
    data += bson.BSON.encode(doc)
    if safe:
        _, update_message = __pack_message(2001, data)
        request_id, error_message = __last_error(last_error_args)
        return (request_id, update_message + error_message)
    else:
        return __pack_message(2001, data)

def delete(collection_name, spec, safe, last_error_args):
    """Get a **delete** message.
    """
    data = __ZERO
    data += bson._make_c_string(collection_name)
    data += __ZERO
    data += bson.BSON.encode(spec)
    if safe:
        _, remove_message = __pack_message(2006, data)
        request_id, error_message = __last_error(last_error_args)
        return (request_id, remove_message + error_message)
    else:
        return __pack_message(2006, data)

def b2u(string):
    """bytes to unicode"""
    if isinstance(string, bytes) or (PY2 and isinstance(string, str)):
        return string.decode('utf-8')
    return string

def u2b(string):
    """unicode to bytes"""
    if PY2 and isinstance(string, unicode) or (not PY2 and isinstance(string, str)):
        return string.encode('utf-8')
    return string

def number_of_partitions(max_range, max_sum):
    """Returns an array arr of the same shape as max_range, where
    arr[j] = number of admissible partitions for
             j summands bounded by max_range[j:] and with sum <= max_sum"""
    M = max_sum + 1
    N = len(max_range)
    arr = np.zeros(shape=(M, N), dtype=int)
    arr[:, -1] = np.where(np.arange(M) <= min(max_range[-1], max_sum), 1, 0)
    for i in range(N - 2, -1, -1):
        for j in range(max_range[i] + 1):
            arr[j:, i] += arr[:M - j, i + 1]
    return arr.sum(axis=0)

def make_qr(content, error=None, version=None, mode=None, mask=None, encoding=None, eci=False, boost_error=True):
    """Creates a QR Code (never a Micro QR Code).

    See :py:func:`make` for a description of the parameters.

    :rtype: QRCode"""
