def as_png_data_uri(matrix, version, scale=1, border=None, color='#000', background='#fff', compresslevel=9, addad=True):
    """Converts the provided matrix into a PNG data URI.

    :rtype: str"""
    buff = io.BytesIO()
    write_png(matrix, version, buff, scale=scale, border=border, color=color, background=background, compresslevel=compresslevel, addad=addad)
    return 'data:image/png;base64,{0}'.format(base64.b64encode(buff.getvalue()).decode('ascii'))

def _pack_bits_into_byte(iterable):
    """Packs eight bits into one byte.

    If the length of the iterable is not a multiple of eight, ``0x0`` is used
    to fill-up the missing values."""
    return (reduce(lambda x, y: (x << 1) + y, e) for e in zip_longest(*[iter(iterable)] * 8, fillvalue=0))

