def user_error(status_code, title, detail, pointer):
    """Create and return a general user error response that is jsonapi compliant.

    Required args:
        status_code: The HTTP status code associated with the problem.
        title: A short summary of the problem.
        detail: An explanation specific to the occurence of the problem.
        pointer: The request path associated with the source of the problem."""
    response = {'errors': [{'status': status_code, 'source': {'pointer': '{0}'.format(pointer)}, 'title': title, 'detail': detail}], 'jsonapi': {'version': '1.0'}, 'meta': {'sqlalchemy_jsonapi_version': __version__}}
    return (json.dumps(response), status_code)

def attr_descriptor(action, *names):
    """Wrap a function that allows for getting or setting of an attribute.  This
    allows for specific handling of an attribute when it comes to serializing
    and deserializing.

    :param action: The AttributeActions that this descriptor performs
    :param names: A list of names of the attributes this references"""
    if isinstance(action, AttributeActions):
        action = [action]
    def wrapped(fn):
        if not hasattr(fn, '__jsonapi_action__'):
            fn.__jsonapi_action__ = set()
            fn.__jsonapi_desc_for_attrs__ = set()
        fn.__jsonapi_desc_for_attrs__ |= set(names)
        fn.__jsonapi_action__ |= set(action)
        return fn
    return wrapped

def relationship_descriptor(action, *names):
    """Wrap a function for modification of a relationship.  This allows for
    specific handling for serialization and deserialization.

    :param action: The RelationshipActions that this descriptor performs
    :param names: A list of names of the relationships this references"""
    if isinstance(action, RelationshipActions):
        action = [action]
    def wrapped(fn):
        if not hasattr(fn, '__jsonapi_action__'):
            fn.__jsonapi_action__ = set()
            fn.__jsonapi_desc_for_rels__ = set()
        fn.__jsonapi_desc_for_rels__ |= set(names)
        fn.__jsonapi_action__ |= set(action)
        return fn
    return wrapped

def get_attr_desc(instance, attribute, action):
    """Fetch the appropriate descriptor for the attribute.

    :param instance: Model instance
    :param attribute: Name of the attribute
    :param action: AttributeAction"""
    descs = instance.__jsonapi_attribute_descriptors__.get(attribute, {})
    if action == AttributeActions.GET:
        check_permission(instance, attribute, Permissions.VIEW)
        return descs.get(action, lambda x: getattr(x, attribute))
    check_permission(instance, attribute, Permissions.EDIT)
    return descs.get(action, lambda x, v: setattr(x, attribute, v))

def get_rel_desc(instance, key, action):
    """Fetch the appropriate descriptor for the relationship.

    :param instance: Model instance
    :param key: Name of the relationship
    :param action: RelationshipAction"""
    descs = instance.__jsonapi_rel_desc__.get(key, {})
    if action == RelationshipActions.GET:
        check_permission(instance, key, Permissions.VIEW)
        return descs.get(action, lambda x: getattr(x, key))
    elif action == RelationshipActions.APPEND:
        check_permission(instance, key, Permissions.CREATE)
        return descs.get(action, lambda x, v: getattr(x, key).append(v))
    elif action == RelationshipActions.SET:
        check_permission(instance, key, Permissions.EDIT)
        return descs.get(action, lambda x, v: setattr(x, key, v))
    else:
        check_permission(instance, key, Permissions.DELETE)
        return descs.get(action, lambda x, v: getattr(x, key).remove(v))

def map_event_code(event_code):
    """Map a specific event_code to an event group."""
    event_code = int(event_code)
    if 1100 <= event_code <= 1199:
        return ALARM_GROUP
    elif 3100 <= event_code <= 3199:
        return ALARM_END_GROUP
    elif 1300 <= event_code <= 1399:
        return PANEL_FAULT_GROUP
    elif 3300 <= event_code <= 3399:
        return PANEL_RESTORE_GROUP
    elif 1400 <= event_code <= 1499:
        return DISARM_GROUP
    elif 3400 <= event_code <= 3799:
        return ARM_GROUP
    elif 1600 <= event_code <= 1699:
        return TEST_GROUP
    elif 5000 <= event_code <= 5099:
        return CAPTURE_GROUP
    elif 5100 <= event_code <= 5199:
        return DEVICE_GROUP
    elif 5200 <= event_code <= 5299:
        return AUTOMATION_GROUP
    return None

def new_device(device_json, abode):
    """Create new device object for the given type."""
    type_tag = device_json.get('type_tag')
    if not type_tag:
        raise AbodeException(ERROR.UNABLE_TO_MAP_DEVICE)
    generic_type = CONST.get_generic_type(type_tag.lower())
    device_json['generic_type'] = generic_type
    if generic_type == CONST.TYPE_CONNECTIVITY or generic_type == CONST.TYPE_MOISTURE or generic_type == CONST.TYPE_OPENING:
        return AbodeBinarySensor(device_json, abode)
    elif generic_type == CONST.TYPE_CAMERA:
        return AbodeCamera(device_json, abode)
    elif generic_type == CONST.TYPE_COVER:
        return AbodeCover(device_json, abode)
    elif generic_type == CONST.TYPE_LIGHT:
        return AbodeLight(device_json, abode)
    elif generic_type == CONST.TYPE_LOCK:
        return AbodeLock(device_json, abode)
    elif generic_type == CONST.TYPE_SWITCH:
        return AbodeSwitch(device_json, abode)
    elif generic_type == CONST.TYPE_VALVE:
        return AbodeValve(device_json, abode)
    elif generic_type == CONST.TYPE_UNKNOWN_SENSOR:
        return _new_sensor(device_json, abode)
    return None

def get_generic_type(type_tag):
    """Map type tag to generic type."""
    return {DEVICE_ALARM: TYPE_ALARM, DEVICE_GLASS_BREAK: TYPE_CONNECTIVITY, DEVICE_KEYPAD: TYPE_CONNECTIVITY, DEVICE_REMOTE_CONTROLLER: TYPE_CONNECTIVITY, DEVICE_SIREN: TYPE_CONNECTIVITY, DEVICE_STATUS_DISPLAY: TYPE_CONNECTIVITY, DEVICE_DOOR_CONTACT: TYPE_OPENING, DEVICE_MOTION_CAMERA: TYPE_CAMERA, DEVICE_MOTION_VIDEO_CAMERA: TYPE_CAMERA, DEVICE_IP_CAM: TYPE_CAMERA, DEVICE_OUTDOOR_MOTION_CAMERA: TYPE_CAMERA, DEVICE_SECURE_BARRIER: TYPE_COVER, DEVICE_DIMMER: TYPE_LIGHT, DEVICE_DIMMER_METER: TYPE_LIGHT, DEVICE_HUE: TYPE_LIGHT, DEVICE_DOOR_LOCK: TYPE_LOCK, DEVICE_WATER_SENSOR: TYPE_CONNECTIVITY, DEVICE_SWITCH: TYPE_SWITCH, DEVICE_NIGHT_SWITCH: TYPE_SWITCH, DEVICE_POWER_SWITCH_SENSOR: TYPE_SWITCH, DEVICE_POWER_SWITCH_METER: TYPE_SWITCH, DEVICE_VALVE: TYPE_VALVE, DEVICE_ROOM_SENSOR: TYPE_UNKNOWN_SENSOR, DEVICE_TEMPERATURE_SENSOR: TYPE_UNKNOWN_SENSOR, DEVICE_MULTI_SENSOR: TYPE_UNKNOWN_SENSOR, DEVICE_PIR: TYPE_UNKNOWN_SENSOR, DEVICE_POVS: TYPE_UNKNOWN_SENSOR}.get(type_tag.lower(), None)

def update(dct, dct_merge):
    """Recursively merge dicts."""
    for key, value in dct_merge.items():
        if key in dct and isinstance(dct[key], dict):
            dct[key] = update(dct[key], value)
        else:
            dct[key] = value
    return dct

def load(json_src, save=False):
    """Load any json serialized cinderlib object."""
    if isinstance(json_src, six.string_types):
        json_src = json_lib.loads(json_src)
    if isinstance(json_src, list):
        return [getattr(objects, obj['class']).load(obj, save) for obj in json_src]
    return getattr(objects, json_src['class']).load(json_src, save)

