def normal_prior(value, mean, sigma):
    """Normal prior distribution.
    """
    return -0.5 * (2 * np.pi * sigma) - (value - mean) ** 2 / (2.0 * sigma)

def log_uniform_prior(value, umin=0, umax=None):
    """Log-uniform prior distribution.
    """
    if value > 0 and value >= umin:
        if umax is not None:
            if value <= umax:
                return 1 / value
            else:
                return -np.inf
        else:
            return 1 / value
    else:
        return -np.inf

def save_batches(server_context, assay_id, batches):
    """Saves a modified batches.
    :param server_context: A LabKey server context. See utils.create_server_context.
    :param assay_id: The assay protocol id.
    :param batches: The Batch(es) to save.
    :return:"""
    save_batch_url = server_context.build_url('assay', 'saveAssayBatch.api')
    json_batches = []
    if batches is None:
        return None
    for batch in batches:
        if isinstance(batch, Batch):
            json_batches.append(batch.to_json())
        else:
            raise Exception('save_batch() "batches" expected to be a set Batch instances')
    payload = {'assayId': assay_id, 'batches': json_batches}
    headers = {'Content-type': 'application/json', 'Accept': 'text/plain'}
    json_body = server_context.make_request(save_batch_url, json_dumps(payload, sort_keys=True), headers=headers)
    if json_body is not None:
        resp_batches = json_body['batches']
        return [Batch.from_data(resp_batch) for resp_batch in resp_batches]
    return None

def sed_conversion(energy, model_unit, sed):
    """Manage conversion between differential spectrum and SED"""
    model_pt = model_unit.physical_type
    ones = np.ones(energy.shape)
    if sed:
        f_unit = u.Unit('erg/s')
        if model_pt == 'power' or model_pt == 'flux' or model_pt == 'energy':
            sedf = ones
        elif 'differential' in model_pt:
            sedf = energy ** 2
        else:
            raise u.UnitsError('Model physical type ({0}) is not supported'.format(model_pt), 'Supported physical types are: power, flux, differential power, differential flux')
        if 'flux' in model_pt:
            f_unit /= u.cm ** 2
        elif 'energy' in model_pt:
            f_unit = u.erg
    else:
        f_unit = u.Unit('1/(s TeV)')
        if 'differential' in model_pt:
            sedf = ones
        elif model_pt == 'power' or model_pt == 'flux' or model_pt == 'energy':
            sedf = 1 / energy ** 2
        else:
            raise u.UnitsError('Model physical type ({0}) is not supported'.format(model_pt), 'Supported physical types are: power, flux, differential power, differential flux')
        if 'flux' in model_pt:
            f_unit /= u.cm ** 2
        elif 'energy' in model_pt:
            f_unit = u.Unit('1/TeV')
    log.debug('Converted from {0} ({1}) into {2} ({3}) for sed={4}'.format(model_unit, model_pt, f_unit, f_unit.physical_type, sed))
    return (f_unit, sedf)

def ElectronIC(pars, data):
    """Define particle distribution model, radiative model, and return model flux
    at data energy values"""
    ECPL = ExponentialCutoffPowerLaw(pars[0] / u.eV, 10.0 * u.TeV, pars[1], 10 ** pars[2] * u.TeV)
    IC = InverseCompton(ECPL, seed_photon_fields=['CMB'])
    return IC.flux(data, distance=1.0 * u.kpc)

def _latex_float(f, format='.3g'):
    """http://stackoverflow.com/a/13490601
    """
    float_str = '{{0:{0}}}'.format(format).format(f)
    if 'e' in float_str:
        base, exponent = float_str.split('e')
        return '{0}\\times 10^{{{1}}}'.format(base, int(exponent))
    else:
        return float_str

def _read_or_calc_samples(sampler, modelidx=0, n_samples=100, last_step=False, e_range=None, e_npoints=100, threads=None):
    """Get samples from blob or compute them from chain and sampler.modelfn
    """
    if not e_range:
        modelx, model = _process_blob(sampler, modelidx, last_step=last_step)
    else:
        e_range = validate_array('e_range', u.Quantity(e_range), physical_type='energy')
        e_unit = e_range.unit
        energy = np.logspace(np.log10(e_range[0].value), np.log10(e_range[1].value), e_npoints) * e_unit
        data = {'energy': energy, 'flux': np.zeros(energy.shape) * sampler.data['flux'].unit}
        chain = sampler.chain[-1] if last_step else sampler.flatchain
        pars = chain[np.random.randint(len(chain), size=n_samples)]
        blobs = []
        p = Pool(threads)
        modelouts = p.map(partial(sampler.modelfn, data=data), pars)
        p.close()
        p.terminate()
        for modelout in modelouts:
            if isinstance(modelout, np.ndarray):
                blobs.append([modelout])
            else:
                blobs.append(modelout)
        modelx, model = _process_blob(blobs, modelidx=modelidx, energy=data['energy'])
    return (modelx, model)

def _calc_ML(sampler, modelidx=0, e_range=None, e_npoints=100):
    """Get ML model from blob or compute them from chain and sampler.modelfn
    """
    ML, MLp, MLerr, ML_model = find_ML(sampler, modelidx)
    if e_range is not None:
        e_range = validate_array('e_range', u.Quantity(e_range), physical_type='energy')
        e_unit = e_range.unit
        energy = np.logspace(np.log10(e_range[0].value), np.log10(e_range[1].value), e_npoints) * e_unit
        data = {'energy': energy, 'flux': np.zeros(energy.shape) * sampler.data['flux'].unit}
        modelout = sampler.modelfn(MLp, data)
        if isinstance(modelout, np.ndarray):
            blob = modelout
        else:
            blob = modelout[modelidx]
        if isinstance(blob, u.Quantity):
            modelx = data['energy'].copy()
            model_ML = blob.copy()
        elif len(blob) == 2:
            modelx = blob[0].copy()
            model_ML = blob[1].copy()
        else:
            raise TypeError('Model {0} has wrong blob format'.format(modelidx))
        ML_model = (modelx, model_ML)
    return (ML, MLp, MLerr, ML_model)

def _calc_CI(sampler, modelidx=0, confs=[3, 1], last_step=False, e_range=None, e_npoints=100, threads=None):
    """Calculate confidence interval.
    """
    from scipy import stats
    if e_range:
        maxconf = np.max(confs)
        minsamples = min(100, int(1 / stats.norm.cdf(-maxconf) + 1))
        if minsamples > 1000:
            log.warning('In order to sample the confidence band for {0} sigma, {1} new samples need to be computed, but we are limiting it to 1000 samples, so the confidence band might not be well constrained. Consider reducing the maximum confidence significance or using the samples stored in the sampler by setting e_range to None'.format(maxconf, minsamples))
            minsamples = 1000
    else:
        minsamples = None
    modelx, model = _read_or_calc_samples(sampler, modelidx, last_step=last_step, e_range=e_range, e_npoints=e_npoints, n_samples=minsamples, threads=threads)
    nwalkers = len(model) - 1
    CI = []
    for conf in confs:
        fmin = stats.norm.cdf(-conf)
        fmax = stats.norm.cdf(conf)
        ymin, ymax = ([], [])
        for fr, y in ((fmin, ymin), (fmax, ymax)):
            nf = int(fr * nwalkers)
            for i in six.moves.range(len(modelx)):
                ysort = np.sort(model[:, i])
                y.append(ysort[nf])
        CI.append((u.Quantity(ymin), u.Quantity(ymax)))
    return (modelx, CI)

def deref(data, spec: dict):
    """Return dereference data
    :param data:
    :param spec:
    :return:"""
    if isinstance(data, Sequence):
        is_dict = False
        gen = enumerate(data)
    elif not isinstance(data, Mapping):
        return data
    elif '$ref' in data:
        return deref(get_ref(spec, data['$ref']), spec)
    else:
        is_dict = True
        gen = data.items()
    result = None
    for k, v in gen:
        new_v = deref(v, spec)
        if new_v is not v:
            if result is not None:
                pass
            elif is_dict:
                result = data.copy()
            else:
                result = data[:]
            result[k] = new_v
    return result or data

def template(template_name, *, app_key=APP_KEY, encoding='utf-8', status=200):
    """Decorator compatible with aiohttp_apiset router"""
    def wrapper(func):
        @functools.wraps(func)
        async def wrapped(*args, **kwargs):
            if asyncio.iscoroutinefunction(func):
                coro = func
            else:
                coro = asyncio.coroutine(func)
            context = await coro(*args, **kwargs)
            if isinstance(context, web.StreamResponse):
                return context
            if 'request' in kwargs:
                request = kwargs['request']
            elif not args:
                request = None
                warnings.warn('Request not detected')
            elif isinstance(args[0], AbstractView):
                request = args[0].request
            else:
                request = args[-1]
            response = render_template(template_name, request, context, app_key=app_key, encoding=encoding)
            response.set_status(status)
            return response
        return wrapped
    return wrapper

def get_collection(source, name, collection_format, default):
    """get collection named `name` from the given `source` that
    formatted accordingly to `collection_format`."""
    if collection_format in COLLECTION_SEP:
        separator = COLLECTION_SEP[collection_format]
        value = source.get(name, None)
        if value is None:
            return default
        return value.split(separator)
    if collection_format == 'brackets':
        return source.getall(name + '[]', default)
    else:
        return source.getall(name, default)

def _col_name(index):
    """Converts a column index to a column name.

    >>> _col_name(0)
    'A'
    >>> _col_name(26)
    'AA'"""
    for exp in itertools.count(1):
        limit = 26 ** exp
        if index < limit:
            return ''.join((chr(ord('A') + index // 26 ** i % 26) for i in range(exp - 1, -1, -1)))
        index -= limit

def main():
    """program entry point"""
    parser = create_parser()
    options = vars(parser.parse_args())
    HASH_STORE.IGNORE_CACHE_FILE = options[constants.LABEL_FORCE]
    moban_file = options[constants.LABEL_MOBANFILE]
    load_engine_factory_and_engines()
    if moban_file is None:
        moban_file = mobanfile.find_default_moban_file()
    if moban_file:
        try:
            count = handle_moban_file(moban_file, options)
            moban_exit(options[constants.LABEL_EXIT_CODE], count)
        except (exceptions.DirectoryNotFound, exceptions.NoThirdPartyEngine, exceptions.MobanfileGrammarException) as e:
            reporter.report_error_message(str(e))
            moban_exit(options[constants.LABEL_EXIT_CODE], constants.ERROR)
    else:
        try:
            count = handle_command_line(options)
            moban_exit(options[constants.LABEL_EXIT_CODE], count)
        except exceptions.NoTemplate as e:
            reporter.report_error_message(str(e))
            moban_exit(options[constants.LABEL_EXIT_CODE], constants.ERROR)

def handle_moban_file(moban_file, options):
    """act upon default moban file"""
    moban_file_configurations = load_data(None, moban_file)
    if moban_file_configurations is None:
        raise exceptions.MobanfileGrammarException(constants.ERROR_INVALID_MOBAN_FILE % moban_file)
    if constants.LABEL_TARGETS not in moban_file_configurations and constants.LABEL_COPY not in moban_file_configurations:
        raise exceptions.MobanfileGrammarException(constants.ERROR_NO_TARGETS % moban_file)
    check_none(moban_file_configurations, moban_file)
    version = moban_file_configurations.get(constants.MOBAN_VERSION, constants.DEFAULT_MOBAN_VERSION)
    if version == constants.DEFAULT_MOBAN_VERSION:
        mobanfile.handle_moban_file_v1(moban_file_configurations, options)
    else:
        raise exceptions.MobanfileGrammarException(constants.MESSAGE_FILE_VERSION_NOT_SUPPORTED % version)
    HASH_STORE.save_hashes()

def handle_command_line(options):
    """act upon command options"""
    options = merge(options, constants.DEFAULT_OPTIONS)
    engine = plugins.ENGINES.get_engine(options[constants.LABEL_TEMPLATE_TYPE], options[constants.LABEL_TMPL_DIRS], options[constants.LABEL_CONFIG_DIR])
    if options[constants.LABEL_TEMPLATE] is None:
        if options[constants.POSITIONAL_LABEL_TEMPLATE] is None:
            raise exceptions.NoTemplate(constants.ERROR_NO_TEMPLATE)
        else:
            engine.render_string_to_file(options[constants.POSITIONAL_LABEL_TEMPLATE], options[constants.LABEL_CONFIG], options[constants.LABEL_OUTPUT])
    else:
        engine.render_to_file(options[constants.LABEL_TEMPLATE], options[constants.LABEL_CONFIG], options[constants.LABEL_OUTPUT])
    engine.report()
    HASH_STORE.save_hashes()
    exit_code = reporter.convert_to_shell_exit_code(engine.number_of_templated_files())
    return exit_code

def _data():
    """(Lazy)load index data structure for currences

    Load the `data.json` file (created with `gen_data.py`) and index by alpha3,
    code_num, symbol and country.

    Returns:
        Dict[str, Dict[str, Any]]: Currency data indexed by different angles"""
    global _DATA
    if _DATA is None:
        _DATA = {}
        with open(resource_filename(__name__, 'data.json'), 'r', encoding='utf-8') as f:
            _DATA['alpha3'] = {k: Currency(**v) for k, v in json.load(f).items()}
        _DATA['code_num'] = {d.code_num: d for d in _DATA['alpha3'].values() if d.code_num is not None}
        _DATA['symbol'] = defaultdict(list)
        for d in _DATA['alpha3'].values():
            for s in d.symbols:
                _DATA['symbol'][s] += [d]
        for s, d in _DATA['symbol'].items():
            _DATA['symbol'][s] = sorted(d, key=lambda d: 10000 if d.code_num is None else d.code_num)
        _DATA['name'] = {}
        for d in _DATA['alpha3'].values():
            if d.name in _DATA['name']:
                assert 'Duplicate name "{}"!'.format(d.name)
            _DATA['name'][d.name] = d
        _DATA['country'] = defaultdict(list)
        for d in _DATA['alpha3'].values():
            for cc in d.countries:
                _DATA['country'][cc] += [d]
        for s, d in _DATA['country'].items():
            _DATA['country'][s] = sorted(d, key=lambda d: (int(d.symbols == []), 10000 if d.code_num is None else d.code_num, len(d.countries)))
    return _DATA

def by_symbol(symbol, country_code=None):
    """Get list of possible currencies for symbol; filter by country_code

    Look for all currencies that use the `symbol`. If there are currencies used
    in the country of `country_code`, return only those; otherwise return all
    found currencies.

    Parameters:
        symbol: unicode                  Currency symbol.
        country_code: Optional[unicode]  Iso3166 alpha2 country code.

    Returns:
        List[Currency]: Currency objects for `symbol`; filter by country_code."""
    res = _data()['symbol'].get(symbol)
    if res:
        tmp_res = []
        for d in res:
            if country_code in d.countries:
                tmp_res += [d]
        if tmp_res:
            return tmp_res
        if country_code is None:
            return res

def by_symbol_match(value, country_code=None):
    """Get list of possible currencies where the symbol is in value; filter by country_code (iso3166 alpha2 code)

    Look for first matching currency symbol in `value`. Filter similar to `by_symbol`.
    Symbols are sorted by length and relevance of first character (see `_symbols()`).

    Symbols are considered to be currency symbols, alpha3 codes or currency names.

    Note: This is a [heuristic](https://en.wikipedia.org/wiki/Heuristic) !

    Parameters:
        value: unicode                   Some input string.
        country_code: Optional[unicode]  Iso3166 alpha2 country code.

    Returns:
        List[Currency]: Currency objects found in `value`; filter by country_code."""
    res = None
    for s, group in _symbols():
        if s.lower() in value.lower():
            if group == 'symbol':
                res = by_symbol(s, country_code)
            if group == 'alpha3':
                res = [by_alpha3(s)]
            if group == 'name':
                res = [_data()['name'][s]]
            if res and country_code is not None:
                res = [currency for currency in res if country_code in currency.countries]
            if res:
                return res

