    for k, v in list(data['data_details'].items()):
        v['urls'] = sorted(list(v['urls'].items()), key=lambda k_v: k_v[1].total, reverse=True)[:limit_per_url_group]
    data_details = sorted(iter(data['data_details'].items()), key=lambda k_v1: k_v1[1]['duration_agr_data'].total, reverse=True)[:limit_url_groups]
