def xprint(m, *args):
    """Print string to stdout.

    Format unicode safely."""
    if sys.hexversion < 50331648:
        m = m.decode('utf8')
    if args:
        m = m % args
    if sys.hexversion < 50331648:
        m = m.encode('utf8')
    sys.stdout.write(m)
    sys.stdout.write('\n')

def render_flags(flags, bit_list):
    """Show bit names.
    """
    res = []
    known = 0
    for bit in bit_list:
        known = known | bit[0]
        if flags & bit[0]:
            res.append(bit[1])
    unknown = flags & ~known
    n = 0
    while unknown:
        if unknown & 1:
            res.append('UNK_%04x' % (1 << n))
        unknown = unknown >> 1
        n += 1
    if not res:
        return '-'
    return ','.join(res)

