def case_insensitive_file_search(directory, pattern):
    """Looks for file with pattern with case insensitive search"""
    try:
        return os.path.join(directory, [filename for filename in os.listdir(directory) if re.search(pattern, filename, re.IGNORECASE)][0])
    except IndexError:
        print('{0} not found'.format(pattern))
        raise

def partition(lst, n):
    """Divide list into n equal parts"""
    q, r = divmod(len(lst), n)
    indices = [q * i + min(i, r) for i in xrange(n + 1)]
    return ([lst[indices[i]:indices[i + 1]] for i in xrange(n)], [list(xrange(indices[i], indices[i + 1])) for i in xrange(n)])

