def ensure_unique(qs, field_name, value, exclude_id=None):
    """Makes sure that `value` is unique on model.fieldname. And nonempty."""
    orig = value
    if not value:
        value = 'None'
    for x in itertools.count(1):
        if not qs.exclude(id=exclude_id).filter(**{field_name: value}).exists():
            break
        if orig:
            value = '%s-%d' % (orig, x)
        else:
            value = '%d' % x
    return value

def update_json_analysis(analysis, j):
    """Step through the items in a piece of json, and update an analysis dict
    with the values found."""
    def _analyze_list(l, parent=''):
        for v in l:
            if isinstance(v, (dict, CaseInsensitiveDict)):
                _analyze_json(v, parent=parent)
            elif isinstance(v, list):
                _analyze_list(v, parent=parent + '[]')
            else:
                analysis[parent].add(v)
    def _analyze_json(d, parent=''):
        for k, v in d.iteritems():
            if parent:
                path = '.'.join([parent, k])
            else:
                path = k
            if isinstance(v, (dict, CaseInsensitiveDict)):
                _analyze_json(v, parent=path)
            elif isinstance(v, list):
                _analyze_list(v, parent=path + '[]')
            else:
                analysis[path].add(v)
    if isinstance(j, list):
        _analyze_list(j)
    if isinstance(j, (dict, CaseInsensitiveDict)):
        _analyze_json(j)

def zero_datetime(dt, tz=None):
    """Return the given datetime with hour/minutes/seconds/ms zeroed and the
    timezone coerced to the given ``tz`` (or UTC if none is given)."""
    if tz is None:
        tz = get_current_timezone()
    return coerce_naive(dt).replace(hour=0, minute=0, second=0, microsecond=0)

def coerce_dt_awareness(date_or_datetime, tz=None, t=None):
    """Coerce the given `datetime` or `date` object into a timezone-aware or
    timezone-naive `datetime` result, depending on which is appropriate for
    the project's settings."""
    if isinstance(date_or_datetime, datetime):
        dt = date_or_datetime
    else:
        dt = datetime.combine(date_or_datetime, t or time.min)
    is_project_tz_aware = settings.USE_TZ
    if is_project_tz_aware:
        return coerce_aware(dt, tz)
    elif not is_project_tz_aware:
        return coerce_naive(dt, tz)
    return dt

def format_naive_ical_dt(date_or_datetime):
    """Return datetime formatted for use in iCal as a *naive* datetime value to
    work more like people expect, e.g. creating a series of events starting
    at 9am should not create some occurrences that start at 8am or 10am after
    a daylight savings change."""
    dt = coerce_dt_awareness(date_or_datetime)
    if is_naive(dt):
        return dt.strftime('%Y%m%dT%H%M%S')
    else:
        return dt.astimezone(get_current_timezone()).strftime('%Y%m%dT%H%M%S')

def verify_draft_url(url):
    """Return ``True`` if the given URL has a valid draft mode HMAC in its
    querystring."""
    url = urlparse.urlparse(url)
    query = QueryDict(force_bytes(url.query))
    preview_hmac = query.get('preview') or query.get('edit')
    if preview_hmac:
        salt, hmac = preview_hmac.split(':')
        return hmac == get_draft_hmac(salt, url.path)
    return False

