def expand_python_version(version):
    """Expand Python versions to all identifiers used on PyPI.

    >>> expand_python_version('3.5')
    ['3.5', 'py3', 'py2.py3', 'cp35']"""
    if not re.match('^\\d\\.\\d$', version):
        return [version]
    major, minor = version.split('.')
    patterns = ['{major}.{minor}', 'cp{major}{minor}', 'py{major}', 'py{major}.{minor}', 'py{major}{minor}', 'source', 'py2.py3']
    return set((pattern.format(major=major, minor=minor) for pattern in patterns))

def one_instance(function=None, key='', timeout=DEFAULT_ONE_INSTANCE_TIMEOUT):
    """Decorator to enforce only one Celery task execution at a time when multiple
    workers are available.

    See http://loose-bits.com/2010/10/distributed-task-locking-in-celery.html"""
    def _dec(run_func):
        def _caller(*args, **kwargs):
            ret_value = None
            have_lock = False
            if REDIS_CLIENT.config_get('appendonly').values()[0] == 'no':
                REDIS_CLIENT.config_set('appendonly', 'yes')
            lock = REDIS_CLIENT.lock(key, timeout=timeout)
            try:
                logger.debug('%s: trying to acquire lock (PID %d).' % (key, os.getpid()))
                have_lock = lock.acquire(blocking=False)
                if have_lock:
                    logger.debug('%s: acquired lock (PID %d).' % (key, os.getpid()))
                    ret_value = run_func(*args, **kwargs)
                else:
                    logger.error('%s: did not acquire lock (PID %d).' % (key, os.getpid()))
            finally:
                if have_lock:
                    lock.release()
                    logger.debug('%s: released lock (PID %d).' % (key, os.getpid()))
            return ret_value
        return _caller
    return _dec(function) if function is not None else _dec

def resolve(obj, attr, fallback=None):
    """Resolves obj.attr to a value, calling it as a function if necessary.
    :param obj:
    :param attr: a string name of a property or function
    :param fallback: the value to return if none can be resolved
    :return: the result of the attribute, or fallback if object/attr not found"""
    if obj is None:
        return fallback
    value = getattr(obj, attr, fallback)
    if callable(value):
        return value()
    return value

def first_of(obj, *attrs):
    """:param obj:
    :param attrs: a list of strings
    :return: the first truthy attribute of obj, calling it as a function if necessary."""
    for attr in attrs:
        r = resolve(obj, attr)
        if r:
            return r

