def handle_publishable_m2m_changed(sender, instance, action, reverse, model, pk_set, **kwargs):
    """Cache related published objects in `pre_clear` so they can be restored in
    `post_clear`."""
    if not issubclass(model, PublishingModel):
        return
    if reverse:
        for rel_obj in instance._meta.get_all_related_many_to_many_objects():
            if rel_obj.field.rel.through == sender:
                m2m = getattr(instance, rel_obj.get_accessor_name())
                break
    else:
        for field in instance._meta.many_to_many:
            if field.rel.through == sender:
                m2m = getattr(instance, field.attname)
                break
    if action == 'pre_clear':
        instance._published_m2m_cache = set(m2m.filter(publishing_is_draft=False).values_list('pk', flat=True))
    if action == 'post_clear':
        m2m.add(*instance._published_m2m_cache)
        del instance._published_m2m_cache

def update_fluent_cached_urls(item, dry_run=False):
    """Regenerate the cached URLs for an item's translations. This is a fiddly
    business: we use "hidden" methods instead of the public ones to avoid
    unnecessary and unwanted slug changes to ensure uniqueness, the logic for
    which doesn't work with our publishing."""
    change_report = []
    if hasattr(item, 'translations'):
        for translation in item.translations.all():
            old_url = translation._cached_url
            item._update_cached_url(translation)
            change_report.append((translation, '_cached_url', old_url, translation._cached_url))
            if not dry_run:
                translation.save()
        if not dry_run:
            item._expire_url_caches()
        if item.is_draft:
            children = [child for child in item.children.all() if child.is_draft]
        else:
            children = [child for child in item.get_draft().children.all() if child.is_published]
        for child in children:
            update_fluent_cached_urls(child, dry_run=dry_run)
    return change_report

def create_can_publish_and_can_republish_permissions(sender, **kwargs):
    """Add `can_publish` and `ca_nrepublish` permissions for each publishable
    model in the system."""
    for model in sender.get_models():
        if not issubclass(model, PublishingModel):
            continue
        content_type = ContentType.objects.get_for_model(model)
        permission, created = Permission.objects.get_or_create(content_type=content_type, codename='can_publish', defaults=dict(name='Can Publish %s' % model.__name__))
        permission, created = Permission.objects.get_or_create(content_type=content_type, codename='can_republish', defaults=dict(name='Can Republish %s' % model.__name__))

def maybe_automatically_publish_drafts_on_save(sender, instance, **kwargs):
    """If automatic publishing is enabled, immediately publish a draft copy after
    it has been saved."""
    if not is_automatic_publishing_enabled(sender):
        return
    if not instance or not hasattr(instance, 'publishing_linked'):
        return
    if instance.is_published:
        return
    if not instance.is_dirty:
        return
    instance.publish()

def _grammatical_join_filter(l, arg=None):
    """:param l: List of strings to join
    :param arg: A pipe-separated list of final_join (" and ") and
    initial_join (", ") strings. For example
    :return: A string that grammatically concatenates the items in the list."""
    if not arg:
        arg = ' and |, '
    try:
        final_join, initial_joins = arg.split('|')
    except ValueError:
        final_join = arg
        initial_joins = ', '
    return grammatical_join(l, initial_joins, final_join)

