def _format_with_same_year(format_specifier):
    """Return a version of `format_specifier` that renders a date
    assuming it has the same year as another date. Usually this means ommitting
    the year.

    This can be overridden by specifying a format that has `_SAME_YEAR` appended
    to the name in the project's `formats` spec."""
    test_format_specifier = format_specifier + '_SAME_YEAR'
    test_format = get_format(test_format_specifier, use_l10n=True)
    if test_format == test_format_specifier:
        return re.sub(YEAR_RE, '', get_format(format_specifier))
    else:
        return test_format

def render_queries(queries, sort):
    """Returns a StringIO containing the formatted SQL queries.

    _sort_ is a field to sort by."""
    output = StringIO()
    if sort == 'order':
        (print >> output, '     time query')
        for query in queries:
            (print >> output, ' %8s %s' % (query['time'], query['sql']))
        return output
    if sort == 'time':
        def sorter(x, y):
            return cmp(x[1][1], y[1][1])
    elif sort == 'queries':
        def sorter(x, y):
            return cmp(x[1][0], y[1][0])
    else:
        raise RuntimeError('Unknown sort: %s' % sort)
    (print >> output, '  queries     time query')
    results = {}
    for query in queries:
        try:
            result = results[query['sql']]
            result[0] += 1
            result[1] += Decimal(query['time'])
        except KeyError:
            results[query['sql']] = [1, Decimal(query['time'])]
    results = sorted(results.iteritems(), cmp=sorter, reverse=True)
    for result in results:
        (print >> output, ' %8d %8.3f %s' % (result[1][0], result[1][1], result[0]))
    return output

def quote(key, value):
    """Certain options support string values. We want clients to be able to pass Python strings in
    but we need them to be quoted in the output. Unfortunately some of those options also allow
    numbers so we type check the value before wrapping it in quotes."""
    if key in quoted_options and isinstance(value, string_types):
        return "'%s'" % value
    if key in quoted_bool_options and isinstance(value, bool):
        return {True: 'true', False: 'false'}[value]
    return value

