def _queryset_iterator(qs):
    """Override default iterator to wrap returned items in a publishing
    sanity-checker "booby trap" to lazily raise an exception if DRAFT
    items are mistakenly returned and mis-used in a public context
    where only PUBLISHED items should be used.

    This booby trap is added when all of:

    - the publishing middleware is active, and therefore able to report
    accurately whether the request is in a drafts-permitted context
    - the publishing middleware tells us we are not in
    a drafts-permitted context, which means only published items
    should be used."""
    if issubclass(type(qs), UrlNodeQuerySet):
        super_without_boobytrap_iterator = super(UrlNodeQuerySet, qs)
    else:
        super_without_boobytrap_iterator = super(PublishingQuerySet, qs)
    if is_publishing_middleware_active() and (not is_draft_request_context()):
        for item in super_without_boobytrap_iterator.iterator():
            if getattr(item, 'publishing_is_draft', False):
                yield DraftItemBoobyTrap(item)
            else:
                yield item
    else:
        for item in super_without_boobytrap_iterator.iterator():
            yield item

def redis_from_url(url):
    """Converts a redis URL used by celery into a `redis.Redis` object."""
    import redis
    url = url or ''
    parsed_url = urlparse(url)
    if parsed_url.scheme != 'redis':
        return None
    kwargs = {}
    match = PASS_HOST_PORT.match(parsed_url.netloc)
    if match.group('password') is not None:
        kwargs['password'] = match.group('password')
    if match.group('host') is not None:
        kwargs['host'] = match.group('host')
    if match.group('port') is not None:
        kwargs['port'] = int(match.group('port'))
    if len(parsed_url.path) > 1:
        kwargs['db'] = int(parsed_url.path[1:])
    return redis.StrictRedis(**kwargs)

def parse_injection(request, rev_id):
    """Parse values for features / datasources of interest."""
    cache = {}
    if 'inject' in request.values:
        try:
            cache = json.loads(request.values['inject'])
        except json.JSONDecodeError as e:
            raise CacheParsingError(e)
    if rev_id is not None:
        rev_cache = cache
        try:
            for k, v in request.values.items():
                if k.startswith(('feature.', 'datasource.')):
                    rev_cache[k] = json.loads(v)
        except json.JSONDecodeError as e:
            raise CacheParsingError(e)
        if len(rev_cache) > 0:
            cache = {rev_id: rev_cache}
    else:
        cache = {int(rev_id): c for rev_id, c in cache.items()}
    return cache or None

def build_event_set(event):
    """Turn an EventStream event into a set of event types that ORES
    uses internally."""
    event_set = set()
    if re.match('([^\\.]+.)?mediawiki\\.revision-create$', event['meta']['topic']):
        event_set.add('edit')
        user_groups = event.get('performer', {}).get('user_groups', [])
        if 'bot' in user_groups:
            event_set.add('bot_edit')
        else:
            event_set.add('nonbot_edit')
        if not event.get('rev_parent_id'):
            event_set.add('page_creation')
            if 'bot' in user_groups:
                event_set.add('bot_page_creation')
            else:
                event_set.add('nonbot_page_creation')
    return event_set

def build_precache_map(config):
    """Build a mapping of contexts and models from the configuration"""
    precache_map = {}
    ss_name = config['ores']['scoring_system']
    for context in config['scoring_systems'][ss_name]['scoring_contexts']:
        precache_map[context] = {}
        for model in config['scoring_contexts'][context].get('precache', []):
            precached_config = config['scoring_contexts'][context]['precache'][model]
            events = precached_config['on']
            if len(set(events) - AVAILABLE_EVENTS) > 0:
                logger.warning('{0} events are not available'.format(set(events) - AVAILABLE_EVENTS))
            for event in precached_config['on']:
                if event in precache_map[context]:
                    precache_map[context][event].add(model)
                else:
                    precache_map[context][event] = {model}
                logger.debug('Setting up precaching for {0} in {1} on {2}'.format(model, context, event))
    return precache_map

def format_v1_score_response(response, limit_to_model=None):
    """The response format looks like this::

        {
            "<rev_id>": {
                "<model_name>": <score>
                "<model_name>": <score>
            },
            "<rev_id>": {
                "<model_name>": <score>
                "<model_name>": <score>
            }
        }"""
    response_doc = defaultdict(dict)
    for rev_id, rev_scores in response.scores.items():
        for model_name, score in rev_scores.items():
            response_doc[rev_id][model_name] = score
    for rev_id, rev_errors in response.errors.items():
        for model_name, error in rev_errors.items():
            response_doc[rev_id][model_name] = util.format_error(error)
    if limit_to_model is not None:
        return util.jsonify({rev_id: model_scores[limit_to_model] for rev_id, model_scores in response_doc.items()})
    else:
        return util.jsonify(response_doc)

def requirements(fname):
    """Generator to parse requirements.txt file

    Supports bits of extended pip format (git urls)"""
    with open(fname) as f:
        for line in f:
            match = re.search('#egg=(.*)$', line)
            if match:
                yield match.groups()[0]
            else:
                yield line.strip()

