def expandpath(path):
    """Expand a filesystem path that may or may not contain user/env vars.

    :param str path: path to expand
    :return str: expanded version of input path"""
    return os.path.expandvars(os.path.expanduser(path)).replace('//', '/')

def get_file_size(filename):
    """Get size of all files in gigabytes (Gb).

    :param str | collections.Iterable[str] filename: A space-separated
        string or list of space-separated strings of absolute file paths.
    :return float: size of file(s), in gigabytes."""
    if filename is None:
        return float(0)
    if type(filename) is list:
        return float(sum([get_file_size(x) for x in filename]))
    try:
        total_bytes = sum([float(os.stat(f).st_size) for f in filename.split(' ') if f is not ''])
    except OSError:
        return 0.0
    else:
        return float(total_bytes) / 1024 ** 3

def grab_project_data(prj):
    """From the given Project, grab Sample-independent data.

    There are some aspects of a Project of which it's beneficial for a Sample
    to be aware, particularly for post-hoc analysis. Since Sample objects
    within a Project are mutually independent, though, each doesn't need to
    know about any of the others. A Project manages its, Sample instances,
    so for each Sample knowledge of Project data is limited. This method
    facilitates adoption of that conceptual model.

    :param Project prj: Project from which to grab data
    :return Mapping: Sample-independent data sections from given Project"""
    if not prj:
        return {}
    data = {}
    for section in SAMPLE_INDEPENDENT_PROJECT_SECTIONS:
        try:
            data[section] = getattr(prj, section)
        except AttributeError:
            _LOGGER.debug("Project lacks section '%s', skipping", section)
    return data

def infer_delimiter(filepath):
    """From extension infer delimiter used in a separated values file.

    :param str filepath: path to file about which to make inference
    :return str | NoneType: extension if inference succeeded; else null"""
    ext = os.path.splitext(filepath)[1][1:].lower()
    return {'txt': '\t', 'tsv': '\t', 'csv': ','}.get(ext)

def is_null_like(x):
    '''Determine whether an object is effectively null.

    :param object x: Object for which null likeness is to be determined.
    :return bool: Whether given object is effectively "null."'''
    return x in [None, ''] or (coll_like(x) and isinstance(x, Sized) and (0 == len(x)))

def parse_ftype(input_file):
    """Checks determine filetype from extension.

    :param str input_file: String to check.
    :return str: filetype (extension without dot prefix)
    :raises TypeError: if file does not appear of a supported type"""
    if input_file.endswith('.bam'):
        return 'bam'
    elif input_file.endswith('.fastq') or input_file.endswith('.fq') or input_file.endswith('.fq.gz') or input_file.endswith('.fastq.gz'):
        return 'fastq'
    else:
        raise TypeError("Type of input file ends in neither '.bam' nor '.fastq' [file: '" + input_file + "']")

def parse_text_data(lines_or_path, delimiter=os.linesep):
    """Interpret input argument as lines of data. This is intended to support
    multiple input argument types to core model constructors.

    :param str | collections.Iterable lines_or_path:
    :param str delimiter: line separator used when parsing a raw string that's
        not a file
    :return collections.Iterable: lines of text data
    :raises ValueError: if primary data argument is neither a string nor
        another iterable"""
    if os.path.isfile(lines_or_path):
        with open(lines_or_path, 'r') as f:
            return f.readlines()
    else:
        _LOGGER.debug("Not a file: '{}'".format(lines_or_path))
    if isinstance(lines_or_path, str):
        return lines_or_path.split(delimiter)
    elif isinstance(lines_or_path, Iterable):
        return lines_or_path
    else:
        raise ValueError('Unable to parse as data lines {} ({})'.format(lines_or_path, type(lines_or_path)))

def is_command_callable(command, name=''):
    """Check if command can be called.

    :param str command: actual command to call
    :param str name: nickname/alias by which to reference the command, optional
    :return bool: whether given command's call succeeded"""
    code = os.system('command -v {0} >/dev/null 2>&1 || {{ exit 1; }}'.format(command))
    if code != 0:
        alias_value = " ('{}') ".format(name) if name else ' '
        _LOGGER.debug("Command '{0}' is not callable: {1}".format(alias_value, command))
    return not bool(code)

def call(cmd, input=None, assert_zero_exit_status=True, warn_on_non_zero_exist_status=False, **kwargs):
    """:rtype: SubprocessResult

    Raises OSError if command was not found

    Returns non-zero result in result.ret if subprocess terminated with non-zero exist status."""
    if not kwargs.get('shell') and isinstance(cmd, basestring):
        raise ValueError('cmd should be list or tuple, not a string: %r' % cmd)
    result = SubprocessResult.call(cmd, input=input, **kwargs)
    if assert_zero_exit_status and result.ret != 0:
        raise SubprocessError(result)
    if warn_on_non_zero_exist_status and result.ret != 0:
        logger.warn('subprocess failed %r' % result)
    return result

def format_event_time(date_time):
    """Accepts either an ISO 8601 string, a dict with a time and tzid OR a datetime object.
    Must be in UTC format:

    2016-01-31T12:33:00Z
    2016-01-31T12:33:00UTC
    2016-01-31T12:33:00+00:00

    https://en.wikipedia.org/wiki/ISO_8601

    :param datetime.datetime date_time: ``datetime.datetime``, ``dict`` or ``string``.
    :return: ISO 8601 formatted datetime string.
    :rtype: ``string`` or ``dict``"""
    if not date_time:
        return date_time
    date_time_type = type(date_time)
    if date_time_type in (type(''), type(u'')):
        return date_time
    elif date_time_type == datetime.date:
        return date_time.strftime(ISO_8601_DATE_FORMAT)
    elif date_time_type is dict:
        if date_time.get('time'):
            date_time['time'] = format_event_time(date_time['time'])
        return date_time
    elif date_time_type != datetime.datetime:
        error_message = 'Unsupported type: ``%s``.\nSupported types: ``<datetime.datetime>``, ``<datetime.date>``, ``<dict>``, or ``<str>``.'
        raise PyCronofyDateTimeError(error_message % repr(type(date_time)), date_time)
    if date_time.tzinfo and date_time.tzinfo != pytz.utc:
        date_time = date_time.astimezone(pytz.utc)
    return date_time.strftime(ISO_8601_DATETIME_FORMAT)

def check_exists_in_object(method, obj, required_fields):
    """Checks if required fields have a value in the object instance.
    Throws an exception with the missing fields.

    :param object obj: Object to check.
    :param typle required_fields: Required fields that must have a value."""
    missing = []
    for field in required_fields:
        if getattr(obj, field) is None:
            missing.append(field)
    if missing:
        raise PyCronofyValidationError('Method: %s. Missing auth field(s): %s' % (method, missing), method, missing)

def check_datetime(method, dictionary, fields, label=None):
    """Checks if the specified fields are formatted correctly if they have a value.
    Throws an exception on incorrectly formatted fields.

    :param dict dictionary: Dictionary to check.
    :param typle fields: Fields to check.
    :param string label: Dictionary name."""
    improperly_formatted = []
    values = []
    for field in fields:
        if field in dictionary and dictionary[field] is not None:
            if type(dictionary[field]) not in (datetime.datetime, datetime.date) and (not ISO_8601_REGEX.match(dictionary[field])):
                improperly_formatted.append(field)
                values.append(dictionary[field])
    if improperly_formatted:
        error_label = ' for "%s"' % label if label else ''
        raise PyCronofyValidationError('Method: %s. Improperly formatted datetime/date field(s)%s: %s\n%s' % (method, error_label, improperly_formatted, values), method, improperly_formatted, values)

def check_exists_in_dictionary(method, dictionary, required_fields, label=None):
    """Checks if required fields have a value in the object instance.
    Throws an exception with the missing fields.

    :param dict dictionary: Dictionary to check.
    :param typle required_fields: Required fields that must have a value.
    :param string label: Dictionary name."""
    missing = []
    for field in required_fields:
        if field not in dictionary or dictionary[field] is None:
            missing.append(field)
    if missing:
        error_label = ' for "%s"' % label if label else ''
        raise PyCronofyValidationError('Method: %s. Missing required field(s)%s: %s' % (method, error_label, missing), method, missing)

