def isValidSemver(version):
    """Semantic version number - determines whether the version is qualified. The format is MAJOR.Minor.PATCH, more with https://semver.org/"""
    if version and isinstance(version, string_types):
        try:
            semver.parse(version)
        except (TypeError, ValueError):
            return False
        else:
            return True
    return False

def sortedSemver(versions, sort='asc'):
    """Semantically sort the list of version Numbers"""
    if versions and isinstance(versions, (list, tuple)):
        if PY2:
            return sorted(versions, cmp=semver.compare, reverse=True if sort.upper() == 'DESC' else False)
        else:
            from functools import cmp_to_key
            return sorted(versions, key=cmp_to_key(semver.compare), reverse=True if sort.upper() == 'DESC' else False)
    else:
        raise TypeError('Invaild Versions, a list or tuple is right.')

def get_index(lis, argument):
    """Find the index of an item, given either the item or index as an argument.

    Particularly useful as a wrapper for arguments like channel or axis.

    Parameters
    ----------
    lis : list
        List to parse.
    argument : int or object
        Argument.

    Returns
    -------
    int
        Index of chosen object."""
    if isinstance(argument, int):
        if -len(lis) <= argument < len(lis):
            return argument
        else:
            raise IndexError('index {0} incompatible with length {1}'.format(argument, len(lis)))
    else:
        return lis.index(argument)

def orthogonal(*args) -> bool:
    """Determine if a set of arrays are orthogonal.

    Parameters
    ----------
    args : array-likes or array shapes

    Returns
    -------
    bool
        Array orthogonality condition."""
    for i, arg in enumerate(args):
        if hasattr(arg, 'shape'):
            args[i] = arg.shape
    for s in zip(*args):
        if np.product(s) != max(s):
            return False
    return True

def valid_index(index, shape) -> tuple:
    """Get a valid index for a broadcastable shape.

    Parameters
    ----------
    index : tuple
        Given index.
    shape : tuple of int
        Shape.

    Returns
    -------
    tuple
        Valid index."""
    index = list(index)
    while len(index) < len(shape):
        index.append(slice(None))
    out = []
    for i, s in zip(index[::-1], shape[::-1]):
        if s == 1:
            if isinstance(i, slice):
                out.append(slice(None))
            else:
                out.append(0)
        else:
            out.append(i)
    return tuple(out[::-1])

def get_symbol(units) -> str:
    """Get default symbol type.

    Parameters
    ----------
    units_str : string
        Units.

    Returns
    -------
    string
        LaTeX formatted symbol."""
    if kind(units) == 'energy':
        d = {}
        d['nm'] = '\\lambda'
        d['wn'] = '\\bar\\nu'
        d['eV'] = '\\hslash\\omega'
        d['Hz'] = 'f'
        d['THz'] = 'f'
        d['GHz'] = 'f'
        return d.get(units, 'E')
    elif kind(units) == 'delay':
        return '\\tau'
    elif kind(units) == 'fluence':
        return '\\mathcal{F}'
    elif kind(units) == 'pulse_width':
        return '\\sigma'
    elif kind(units) == 'temperature':
        return 'T'
    else:
        return kind(units)

