def get_orbit(name, date):
    """Retrieve the orbit of a solar system object

    Args:
        name (str): The name of the body desired. For exact nomenclature, see
            :py:func:`available_planets`
        date (Date): Date at which the state vector will be extracted
    Return:
        Orbit: Orbit of the desired object, in the reference frame in which it is declared in
            the .bsp file"""
    if name not in [x.name for x in Bsp().top.list]:
        raise UnknownBodyError(name)
    for a, b in Bsp().top.steps(name):
        if b.name not in _propagator_cache:
            propagator = type('%sBspPropagator' % b.name, (GenericBspPropagator,), {'src': a, 'dst': b})
            center = Pck()[b.full_name.title()]
            propagator.propagate(date).as_frame(b.name, center=center)
            _propagator_cache[b.name] = propagator
    if Bsp().top not in _propagator_cache:
        _propagator_cache[Bsp().top.name] = EarthPropagator()
    return _propagator_cache[name].propagate(date)

def loads(text):
    """Read CCSDS from a string, and provide the beyond class corresponding;
    Orbit or list of Orbit if it's an OPM, Ephem if it's an OEM.

    Args:
        text (str):
    Return:
        Orbit or Ephem
    Raise:
        ValueError: when the text is not a recognizable CCSDS format"""
    if text.startswith('CCSDS_OEM_VERS'):
        func = _read_oem
    elif text.startswith('CCSDS_OPM_VERS'):
        func = _read_opm
    else:
        raise ValueError('Unknown CCSDS type')
    return func(text)

def dumps(data, **kwargs):
    """Create a string CCSDS representation of the object

    Same arguments and behaviour as :py:func:`dump`"""
    if isinstance(data, Ephem) or (isinstance(data, Iterable) and all((isinstance(x, Ephem) for x in data))):
        content = _dump_oem(data, **kwargs)
    elif isinstance(data, Orbit):
        content = _dump_opm(data, **kwargs)
    else:
        raise TypeError('Unknown object type')
    return content

def _float(value):
    """Conversion of state vector field, with automatic unit handling
    """
    if '[' in value:
        value, sep, unit = value.partition('[')
        unit = sep + unit
        if unit in ('[km]', '[km/s]'):
            multiplier = 1000
        elif unit == '[s]':
            multiplier = 1
        else:
            raise ValueError('Unknown unit for this field', unit)
    else:
        multiplier = 1000
    return float(value) * multiplier

def _earth_orientation(date):
    """Earth orientation parameters in degrees
    """
    ttt = date.change_scale('TT').julian_century
    s_prime = -4.7e-05 * ttt
    return (date.eop.x / 3600.0, date.eop.y / 3600.0, s_prime / 3600)

def earth_orientation(date):
    """Earth orientation as a rotating matrix
    """
    x_p, y_p, s_prime = np.deg2rad(_earth_orientation(date))
    return rot3(-s_prime) @ rot2(x_p) @ rot1(y_p)

def rot1(theta):
    """Args:
        theta (float): Angle in radians
    Return:
        Rotation matrix of angle theta around the X-axis"""
    return np.array([[1, 0, 0], [0, np.cos(theta), np.sin(theta)], [0, -np.sin(theta), np.cos(theta)]])

def rot2(theta):
    """Args:
        theta (float): Angle in radians
    Return:
        Rotation matrix of angle theta around the Y-axis"""
    return np.array([[np.cos(theta), 0, -np.sin(theta)], [0, 1, 0], [np.sin(theta), 0, np.cos(theta)]])

def rot3(theta):
    """Args:
        theta (float): Angle in radians
    Return:
        Rotation matrix of angle theta around the Z-axis"""
    return np.array([[np.cos(theta), np.sin(theta), 0], [-np.sin(theta), np.cos(theta), 0], [0, 0, 1]])

def register(name=EopDb.DEFAULT_DBNAME):
    """Decorator for registering an Eop Database

    Example:

    .. code-block:: python

        @register
        class SqliteEnvDatabase:
            # sqlite implementation
            # this database will be known as 'default'

        @register('json')
        class JsonEnvDatabase:
            # JSON implementation

        EopDb.get(58090.2)                    # get Eop from SqliteEnvDatabase
        EopDb.get(58090.2, dbname='default')  # same as above
        EopDb.get(58090.2, dbname='json')     # get Eop from JsonEnvDatabase"""
    if isinstance(name, str):
        def wrapper(klass):
            EopDb.register(klass, name)
            return klass
        return wrapper
    else:
        klass = name
        EopDb.register(klass)
        return klass

def precesion(date):
    """Precession as a rotation matrix
    """
    zeta, theta, z = np.deg2rad(_precesion(date))
    return rot3(zeta) @ rot2(-theta) @ rot3(z)

def nutation(date, eop_correction=True, terms=106):
    """Nutation as a rotation matrix
    """
    epsilon_bar, delta_psi, delta_eps = np.deg2rad(_nutation(date, eop_correction, terms))
    epsilon = epsilon_bar + delta_eps
    return rot1(-epsilon_bar) @ rot3(delta_psi) @ rot1(epsilon)

def sideral(date, longitude=0.0, model='mean', eop_correction=True, terms=106):
    """Sideral time as a rotation matrix
    """
    theta = _sideral(date, longitude, model, eop_correction, terms)
    return rot3(np.deg2rad(-theta))

