def deunicode(item):
    """Convert unicode objects to str"""
    if item is None:
        return None
    if isinstance(item, str):
        return item
    if isinstance(item, six.text_type):
        return item.encode('utf-8')
    if isinstance(item, dict):
        return {deunicode(key): deunicode(value) for key, value in item.items()}
    if isinstance(item, list):
        return [deunicode(x) for x in item]
    raise TypeError('Unhandled item type: {!r}'.format(item))

def to_bytes(obj):
    """Ensures that the obj is of byte-type.
    """
    if PY3:
        if isinstance(obj, str):
            return obj.encode(settings.DEFAULT_ENCODING)
        else:
            return obj if isinstance(obj, bytes) else b''
    elif isinstance(obj, str):
        return obj
    else:
        return obj.encode(settings.DEFAULT_ENCODING) if isinstance(obj, unicode) else ''

def padding(s, bs=AES.block_size):
    """Fills a bytes-like object with arbitrary symbols to make its length divisible by `bs`.
    """
    s = to_bytes(s)
    if len(s) % bs == 0:
        res = s + b''.join(map(to_bytes, [random.SystemRandom().choice(string.ascii_lowercase + string.digits) for _ in range(bs - 1)])) + to_bytes(chr(96 - bs))
    elif len(s) % bs > 0 and len(s) > bs:
        res = s + b''.join(map(to_bytes, [random.SystemRandom().choice(string.ascii_lowercase + string.digits) for _ in range(bs - len(s) % bs - 1)])) + to_bytes(chr(96 + len(s) % bs - bs))
    else:
        res = s + b''.join(map(to_bytes, [random.SystemRandom().choice(string.ascii_lowercase + string.digits) for _ in range(bs - len(s) - 1)])) + to_bytes(chr(96 + len(s) - bs))
    return res

def unpadding(s, bs=AES.block_size):
    """Reverse operation to padding (see above).

    Parameters
    ==========

        :param s: bytes-like object;
        :param bs: encryption block size."""
    if PY3:
        return s[:s[-1] - 96] if len(s) % bs == 0 else ''
    else:
        return s[:ord(s[-1]) - 96] if len(s) % bs == 0 else ''

def display(views, location_sync=[], zoom_sync=[], host='localhost', server_port=None):
    """Instantiate a HiGlass display with the given views"""
    from .server import Server
    from .client import ViewConf
    tilesets = []
    for view in views:
        for track in view.tracks:
            if track.tracks:
                for track1 in track.tracks:
                    if track1.tileset:
                        tilesets += [track1.tileset]
            if track.tileset:
                tilesets += [track.tileset]
    print('tilesets:', tilesets)
    server = Server(tilesets, host=host, port=server_port)
    server.start()
    for view in views:
        for track in view.tracks:
            if track.tracks:
                for track1 in track.tracks:
                    if 'server' not in track1.viewconf or track1.viewconf['server'] is None:
                        track1.viewconf['server'] = server.api_address
            elif 'server' not in track.viewconf or track.viewconf['server'] is None:
                track.viewconf['server'] = server.api_address
    conf = ViewConf(views, location_syncs=location_syncs, zoom_syncs=zoom_syncs)
    return (HiGlassDisplay(viewconf=conf.to_dict()), server, conf)

def slugify_argument(func):
    """Wraps a function that returns a string, adding the 'slugify' argument.

    >>> slugified_fn = slugify_argument(lambda *args, **kwargs: "YOU ARE A NICE LADY")
    >>> slugified_fn()
    'YOU ARE A NICE LADY'
    >>> slugified_fn(slugify=True)
    'you-are-a-nice-lady'"""
    @six.wraps(func)
    def wrapped(*args, **kwargs):
        if 'slugify' in kwargs and kwargs['slugify']:
            return _slugify(func(*args, **kwargs))
        else:
            return func(*args, **kwargs)
    return wrapped

def capitalize_argument(func):
    """Wraps a function that returns a string, adding the 'capitalize' argument.

    >>> capsified_fn = capitalize_argument(lambda *args, **kwargs: "what in the beeswax is this?")
    >>> capsified_fn()
    'what in the beeswax is this?'
    >>> capsified_fn(capitalize=True)
    'What In The Beeswax Is This?'"""
    @six.wraps(func)
    def wrapped(*args, **kwargs):
        if 'capitalize' in kwargs and kwargs['capitalize']:
            return func(*args, **kwargs).title()
        else:
            return func(*args, **kwargs)
    return wrapped

def datetime(past=True, random=random):
    """Returns a random datetime from the past... or the future!

    >>> mock_random.seed(0)
    >>> datetime(random=mock_random).isoformat()
    '1950-02-03T03:04:05'"""
    def year():
        if past:
            return random.choice(range(1950, 2005))
        else:
            return _datetime.datetime.now().year + random.choice(range(1, 50))
    def month():
        return random.choice(range(1, 12))
    def day():
        return random.choice(range(1, 31))
    def hour():
        return random.choice(range(0, 23))
    def minute():
        return random.choice(range(0, 59))
    def second():
        return random.choice(range(0, 59))
    try:
        return _datetime.datetime(year=year(), month=month(), day=day(), hour=hour(), minute=minute(), second=second())
    except ValueError:
        return datetime(past=past)

def thing(random=random, *args, **kwargs):
    """Return a ... thing.

    >>> mock_random.seed(0)
    >>> thing(random=mock_random)
    'two secrets'
    >>> mock_random.seed(1)
    >>> thing(random=mock_random, capitalize=True)
    'Mighty Poop'
    >>> mock_random.seed(2)
    >>> thing(random=mock_random, slugify=True)
    'poop'
    >>> mock_random.seed(4)
    >>> thing(random=mock_random, slugify=True)
    'two-chimps'"""
    def noun_or_adjective_noun():
        if random.choice([True, False]):
            return noun(random=random)
        else:
            return adjective(random=random) + ' ' + noun(random=random)
    def plural_or_adjective_plural():
        if random.choice([True, False]):
            return plural(random=random)
        else:
            return adjective(random=random) + ' ' + plural(random=random)
    def container_of_nouns():
        return container(random=random) + ' of ' + plural_or_adjective_plural()
    def number_of_plurals():
        return numberwang(random=random) + ' ' + plural_or_adjective_plural()
    if 'an' in kwargs and kwargs['an']:
        return random.choice([inflectify.a(noun_or_adjective_noun()), inflectify.a(container_of_nouns()), number_of_plurals()])
    else:
        return random.choice([noun_or_adjective_noun(), container_of_nouns(), number_of_plurals()])

def name(random=random, *args, **kwargs):
    """Return someone's name

    >>> mock_random.seed(0)
    >>> name(random=mock_random)
    'carl poopbritches'
    >>> mock_random.seed(7)
    >>> name(random=mock_random, capitalize=True)
    'Duke Testy Wonderful'"""
    if random.choice([True, True, True, False]):
        return firstname(random=random) + ' ' + lastname(random=random)
    elif random.choice([True, False]):
        return title(random=random) + ' ' + firstname(random=random) + ' ' + lastname(random=random)
    else:
        return title(random=random) + ' ' + lastname(random=random)

def markdown(random=random, length=10, *args, **kwargs):
    """Produces a bunch of markdown text.

    >>> mock_random.seed(0)
    >>> markdown(random=mock_random, length=2)
    'Nobody will **head** _to_ Mystery Studies Department **to** _buy_ a mighty poop.\\nNobody will **head** _to_ Mystery Studies Department **to** _buy_ a mighty poop.'"""
    def title_sentence():
        return '\n' + '#' * random.randint(1, 5) + ' ' + sentence(capitalize=True, random=random)
    def embellish(word):
        return random.choice([word, word, word, '**' + word + '**', '_' + word + '_'])
    def randomly_markdownify(string):
        return ' '.join([embellish(word) for word in string.split(' ')])
    sentences = []
    for i in range(0, length):
        sentences.append(random.choice([title_sentence(), sentence(random=random), sentence(random=random), randomly_markdownify(sentence(random=random))]))
    return '\n'.join(sentences)

def image(random=random, width=800, height=600, https=False, *args, **kwargs):
    """Generate the address of a placeholder image.

    >>> mock_random.seed(0)
    >>> image(random=mock_random)
    'http://dummyimage.com/800x600/292929/e3e3e3&text=mighty poop'
    >>> image(random=mock_random, width=60, height=60)
    'http://placekitten.com/60/60'
    >>> image(random=mock_random, width=1920, height=1080)
    'http://dummyimage.com/1920x1080/292929/e3e3e3&text=To get to Westeros, you need to go to Britchestown, then drive west.'
    >>> image(random=mock_random, https=True, width=1920, height=1080)
    'https://dummyimage.com/1920x1080/292929/e3e3e3&text=East Mysteryhall is in Westeros.'"""
    target_fn = noun
    if width + height > 300:
        target_fn = thing
    if width + height > 2000:
        target_fn = sentence
    s = ''
    if https:
        s = 's'
    if random.choice([True, False]):
        return 'http{s}://dummyimage.com/{width}x{height}/292929/e3e3e3&text={text}'.format(s=s, width=width, height=height, text=target_fn(random=random))
    else:
        return 'http{s}://placekitten.com/{width}/{height}'.format(s=s, width=width, height=height)

def decode_copy_value(value):
    """Decodes value received as part of Postgres `COPY` command.

    :param value: Value to decode.
    :type value: str

    :return: Either None if the value is NULL string, or the given value where
             escape sequences have been decoded from.
    :rtype: str|None"""
    if value == POSTGRES_COPY_NULL_VALUE:
        return None
    if '\\' not in value:
        return value
    return DECODE_REGEX.sub(unescape_single_character, value)

def unescape_single_character(match):
    """Unescape a single escape sequence found by regular expression.

    :param match: Regular expression match object
    :rtype: str
    :raises: ValueError if the escape sequence is invalid"""
    try:
        return DECODE_MAP[match.group(0)]
    except KeyError:
        value = match.group(0)
        if value == '\\':
            raise ValueError('Unterminated escape sequence encountered')
        raise ValueError('Unrecognized escape sequence encountered: {}'.format(value))

def get_mysqldump_args_and_env_from_url(url):
    """Constructs list of command line arguments and dictionary of environment
    variables that can be given to `mysqldump` executable to obtain database
    dump of the database described in given URL.

    :param url: Parsed database URL.
    :type url: urllib.urlparse.ParseResult

    :return: List of command line arguments as well as dictionary of
             environment variables that can be used to launch the MySQL dump
             process to obtain dump of the database.
    :rtype: tuple[list[str],dict[str,str]]"""
    args = ['--complete-insert', '--extended-insert', '--net_buffer_length=10240', '-h', url.hostname]
    env = {}
    if url.port is not None:
        args.extend(('-P', six.text_type(url.port)))
    if url.username:
        args.extend(('-u', url.username))
    if url.password:
        env['MYSQL_PWD'] = url.password
    if len(url.path) < 2 or not url.path.startswith('/'):
        raise ValueError('Name of the database is missing from the URL')
    args.append(url.path[1:])
    return (args, env)

def decode_mysql_literal(text):
    """Attempts to decode given MySQL literal into Python value.

    :param text: Value to be decoded, as MySQL literal.
    :type text: str

    :return: Python version of the given MySQL literal.
    :rtype: any"""
    if MYSQL_NULL_PATTERN.match(text):
        return None
    if MYSQL_BOOLEAN_PATTERN.match(text):
        return text.lower() == 'true'
    if MYSQL_FLOAT_PATTERN.match(text):
        return float(text)
    if MYSQL_INT_PATTERN.match(text):
        return int(text)
    if MYSQL_STRING_PATTERN.match(text):
        return decode_mysql_string_literal(text)
    raise ValueError('Unable to decode given value: %r' % (text,))

def sanitize_random(value):
    """Random string of same length as the given value."""
    if not value:
        return value
    return ''.join((random.choice(CHARACTERS) for _ in range(len(value))))

def get_cli_parser(func, skip_first=0, parser=None):
    """makes a parser for parsing cli arguments for `func`.

    :param callable func: the function the parser will parse
    :param int skip_first: skip this many first arguments of the func
    :param ArgumentParser parser: bind func to this parser."""
    help_msg, func_args = _get_func_args(func)
    if not parser:
        parser = ArgumentParser(description=help_msg)
    for i, arg in enumerate(func_args):
        arg_name, arg_type, arg_default, arg_required, arg_help = arg
        if i < skip_first:
            continue
        if arg_default is not _empty:
            parser.add_argument(arg_name, type=arg_type, default=arg_default, required=arg_required, help=arg_help)
        else:
            parser.add_argument(arg_name, type=arg_type, required=arg_required, help=arg_help)
    return parser

def _parse_docstring(docstring):
    """parses docstring into its help message and params"""
    params = {}
    if not docstring:
        return (None, params)
    try:
        help_msg = _DOCSTRING_REGEX.search(docstring).group()
        help_msg = _strip_lines(help_msg)
    except AttributeError:
        help_msg = None
    for param in _DOCSTRING_PARAM_REGEX.finditer(docstring):
        param_definition = param.group(1).rsplit(' ', 1)
        if len(param_definition) == 2:
            param_type, param_name = param_definition
        else:
            param_type = None
            param_name = param_definition[0]
        param_help = param.group(2).strip()
        params[param_name] = (param_type, _strip_lines(param_help))
    return (help_msg, params)

def main(argv=None, input_stream=stdin, output_stream=stdout, error_stream=stderr):
    """runs inline function - more info run `cbox --help`"""
    args = _parse_args(argv)
    args_dict = args.__dict__.copy()
    inline_str = args_dict.pop('inline')
    modules = args_dict.pop('modules')
    func = get_inline_func(inline_str, modules, **args_dict)
    return cbox.main(func=func, argv=[], input_stream=input_stream, output_stream=output_stream, error_stream=error_stream, exit=False)

def parse_markdown_readme():
    """Convert README.md to RST via pandoc, and load into memory
    (fallback to LONG_DESCRIPTION on failure)"""
    import subprocess
    try:
        subprocess.call(['pandoc', '-t', 'rst', '-o', 'README.rst', 'README.md'])
    except OSError:
        return LONG_DESCRIPTION
    try:
        readme = open(os.path.join(os.path.dirname(__file__), 'README.rst'))
    except IOError:
        return LONG_DESCRIPTION
    return readme.read()

def is_swapped(app_label, model):
    """Returns the value of the swapped setting, or False if the model hasn't
    been swapped."""
    default_model = join(app_label, model)
    setting = swappable_setting(app_label, model)
    value = getattr(settings, setting, default_model)
    if value != default_model:
        return value
    else:
        return False

def dependency(app_label, model):
    """Returns a Django 1.7+ style dependency tuple for inclusion in
    migration.dependencies[]"""
    from django.db.migrations import swappable_dependency
    return swappable_dependency(get_model_name(app_label, model))

def get_model_names(app_label, models):
    """Map model names to their swapped equivalents for the given app"""
    return dict(((model, get_model_name(app_label, model)) for model in models))

def load_model(app_label, model, orm=None, required=True):
    """Load the specified model class, or the class it was swapped out for.
    If a South orm object is provided, it will be used (but only if the
    model hasn't been swapped.)"""
    swapped = is_swapped(app_label, model)
    if swapped:
        app_label, model = split(swapped)
    elif orm is not None:
        return orm[join(app_label, model)]
    try:
        try:
            from django.apps import apps
            cls = apps.get_model(app_label, model)
        except ImportError:
            from django.db.models import get_model
            cls = get_model(app_label, model)
    except LookupError:
        cls = None
    if cls is None and required:
        raise ImproperlyConfigured('Could not find {name}!'.format(name=join(app_label, model)))
    return cls

def get_elastix_exes():
    """Get the executables for elastix and transformix. Raises an error
    if they cannot be found."""
    if EXES:
        if EXES[0]:
            return EXES
        else:
            raise RuntimeError('No Elastix executable.')
    elastix, ver = _find_executables('elastix')
    if elastix:
        base, ext = os.path.splitext(elastix)
        base = os.path.dirname(base)
        transformix = os.path.join(base, 'transformix' + ext)
        EXES.extend([elastix, transformix])
        print('Found %s in %r' % (ver, elastix))
        return EXES
    else:
        raise RuntimeError('Could not find Elastix executable. Download Elastix from http://elastix.isi.uu.nl/. Pyelastix looks for the exe in a series of common locations. Set ELASTIX_PATH if necessary.')

def _clear_dir(dirName):
    """Remove a directory and it contents. Ignore any failures.
    """
    for fname in os.listdir(dirName):
        try:
            os.remove(os.path.join(dirName, fname))
        except Exception:
            pass
    try:
        os.rmdir(dirName)
    except Exception:
        pass

def get_tempdir():
    """Get the temporary directory where pyelastix stores its temporary
    files. The directory is specific to the current process and the
    calling thread. Generally, the user does not need this; directories
    are automatically cleaned up. Though Elastix log files are also
    written here."""
    tempdir = os.path.join(tempfile.gettempdir(), 'pyelastix')
    if not os.path.isdir(tempdir):
        os.makedirs(tempdir)
    for fname in os.listdir(tempdir):
        dirName = os.path.join(tempdir, fname)
        if not (os.path.isdir(dirName) and fname.startswith('id_')):
            continue
        try:
            pid = int(fname.split('_')[1])
        except Exception:
            continue
        if not _is_pid_running(pid):
            _clear_dir(dirName)
    tid = id(threading.current_thread() if hasattr(threading, 'current_thread') else threading.currentThread())
    dir = os.path.join(tempdir, 'id_%i_%i' % (os.getpid(), tid))
    if not os.path.isdir(dir):
        os.mkdir(dir)
    return dir

def _clear_temp_dir():
    """Clear the temporary directory.
    """
    tempdir = get_tempdir()
    for fname in os.listdir(tempdir):
        try:
            os.remove(os.path.join(tempdir, fname))
        except Exception:
            pass

def _get_image_paths(im1, im2):
    """If the images are paths to a file, checks whether the file exist
    and return the paths. If the images are numpy arrays, writes them
    to disk and returns the paths of the new files."""
    paths = []
    for im in [im1, im2]:
        if im is None:
            paths.append(paths[0])
            continue
        if isinstance(im, str):
            if os.path.isfile(im1):
                paths.append(im)
            else:
                raise ValueError('Image location does not exist.')
        elif isinstance(im, np.ndarray):
            id = len(paths) + 1
            p = _write_image_data(im, id)
            paths.append(p)
        else:
            raise ValueError('Invalid input image.')
    return tuple(paths)

def _get_dtype_maps():
    """Get dictionaries to map numpy data types to ITK types and the
    other way around."""
    tmp = [(np.float32, 'MET_FLOAT'), (np.float64, 'MET_DOUBLE'), (np.uint8, 'MET_UCHAR'), (np.int8, 'MET_CHAR'), (np.uint16, 'MET_USHORT'), (np.int16, 'MET_SHORT'), (np.uint32, 'MET_UINT'), (np.int32, 'MET_INT'), (np.uint64, 'MET_ULONG'), (np.int64, 'MET_LONG')]
    map1, map2 = ({}, {})
    for np_type, itk_type in tmp:
        map1[np_type.__name__] = itk_type
        map2[itk_type] = np_type.__name__
    return (map1, map2)

def _compile_params(params, im1):
    """Compile the params dictionary:
    * Combine parameters from different sources
    * Perform checks to prevent non-compatible parameters
    * Extend parameters that need a list with one element per dimension"""
    p = _get_fixed_params(im1) + get_advanced_params()
    p = p + params
    params = p.as_dict()
    if isinstance(im1, np.ndarray):
        lt = (list, tuple)
        for key in ['FinalGridSpacingInPhysicalUnits', 'FinalGridSpacingInVoxels']:
            if key in params.keys() and (not isinstance(params[key], lt)):
                params[key] = [params[key]] * im1.ndim
    if 'FinalGridSpacingInVoxels' in params:
        if 'FinalGridSpacingInPhysicalUnits' in params:
            params.pop('FinalGridSpacingInPhysicalUnits')
    return params

def _write_parameter_file(params):
    """Write the parameter file in the format that elaxtix likes.
    """
    path = os.path.join(get_tempdir(), 'params.txt')
    def valToStr(val):
        if val in [True, False]:
            return '"%s"' % str(val).lower()
        elif isinstance(val, int):
            return str(val)
        elif isinstance(val, float):
            tmp = str(val)
            if not '.' in tmp:
                tmp += '.0'
            return tmp
        elif isinstance(val, str):
            return '"%s"' % val
    text = ''
    for key in params:
        val = params[key]
        if isinstance(val, (list, tuple)):
            vals = [valToStr(v) for v in val]
            val_ = ' '.join(vals)
        else:
            val_ = valToStr(val)
        line = '(%s %s)' % (key, val_)
        text += line + '\n'
    f = open(path, 'wb')
    try:
        f.write(text.encode('utf-8'))
    finally:
        f.close()
    return path

def render_code(code, filetype, pygments_style):
    """Renders a piece of code into HTML. Highlights syntax if filetype is specfied"""
    if filetype:
        lexer = pygments.lexers.get_lexer_by_name(filetype)
        formatter = pygments.formatters.HtmlFormatter(style=pygments_style)
        return pygments.highlight(code, lexer, formatter)
    else:
        return '<pre><code>{}</code></pre>'.format(code)

def _constraint_lb_and_ub_to_gurobi_sense_rhs_and_range_value(lb, ub):
    """Helper function used by Constraint and Model"""
    if lb is None and ub is None:
        raise Exception('Free constraint ...')
    elif lb is None:
        sense = '<'
        rhs = float(ub)
        range_value = 0.0
    elif ub is None:
        sense = '>'
        rhs = float(lb)
        range_value = 0.0
    elif lb == ub:
        sense = '='
        rhs = float(lb)
        range_value = 0.0
    elif lb > ub:
        raise ValueError('Lower bound is larger than upper bound.')
    else:
        sense = '='
        rhs = float(lb)
        range_value = float(ub - lb)
    return (sense, rhs, range_value)

def _parse_linear_expression(expression, expanded=False, **kwargs):
    """Parse the coefficients of a linear expression (linearity is assumed).

    Returns a dictionary of variable: coefficient pairs."""
    offset = 0
    constant = None
    if expression.is_Add:
        coefficients = expression.as_coefficients_dict()
    elif expression.is_Mul:
        coefficients = {expression.args[1]: expression.args[0]}
    elif expression.is_Symbol:
        coefficients = {expression: 1}
    elif expression.is_Number:
        coefficients = {}
    else:
        raise ValueError('Expression {} seems to be invalid'.format(expression))
    for var in coefficients:
        if not var.is_Symbol:
            if var == one:
                constant = var
                offset = float(coefficients[var])
            elif expanded:
                raise ValueError('Expression {} seems to be invalid'.format(expression))
            else:
                coefficients = _parse_linear_expression(expression, expanded=True, **kwargs)
    if constant is not None:
        del coefficients[constant]
    return (offset, coefficients)

def inheritdocstring(name, bases, attrs):
    """Use as metaclass to inherit class and method docstrings from parent.
    Adapted from http://stackoverflow.com/questions/13937500/inherit-a-parent-class-docstring-as-doc-attribute
    Use this on classes defined in solver-specific interfaces to inherit docstrings from the high-level interface."""
    if '__doc__' not in attrs or not attrs['__doc__']:
        temp = type('temporaryclass', bases, {})
        for cls in inspect.getmro(temp):
            if cls.__doc__ is not None:
                attrs['__doc__'] = cls.__doc__
                break
    for attr_name, attr in attrs.items():
        if not attr.__doc__:
            for cls in inspect.getmro(temp):
                try:
                    if getattr(cls, attr_name).__doc__ is not None:
                        attr.__doc__ = getattr(cls, attr_name).__doc__
                        break
                except (AttributeError, TypeError):
                    continue
    return type(name, bases, attrs)

def expr_to_json(expr):
    """Converts a Sympy expression to a json-compatible tree-structure."""
    if isinstance(expr, symbolics.Mul):
        return {'type': 'Mul', 'args': [expr_to_json(arg) for arg in expr.args]}
    elif isinstance(expr, symbolics.Add):
        return {'type': 'Add', 'args': [expr_to_json(arg) for arg in expr.args]}
    elif isinstance(expr, symbolics.Symbol):
        return {'type': 'Symbol', 'name': expr.name}
    elif isinstance(expr, symbolics.Pow):
        return {'type': 'Pow', 'args': [expr_to_json(arg) for arg in expr.args]}
    elif isinstance(expr, (float, int)):
        return {'type': 'Number', 'value': expr}
    elif isinstance(expr, symbolics.Real):
        return {'type': 'Number', 'value': float(expr)}
    elif isinstance(expr, symbolics.Integer):
        return {'type': 'Number', 'value': int(expr)}
    else:
        raise NotImplementedError('Type not implemented: ' + str(type(expr)))

def parse_expr(expr, local_dict=None):
    """Parses a json-object created with 'expr_to_json' into a Sympy expression.

    If a local_dict argument is passed, symbols with be looked up by name, and a new symbol will
    be created only if the name is not in local_dict."""
    if local_dict is None:
        local_dict = {}
    if expr['type'] == 'Add':
        return add([parse_expr(arg, local_dict) for arg in expr['args']])
    elif expr['type'] == 'Mul':
        return mul([parse_expr(arg, local_dict) for arg in expr['args']])
    elif expr['type'] == 'Pow':
        return Pow((parse_expr(arg, local_dict) for arg in expr['args']))
    elif expr['type'] == 'Symbol':
        try:
            return local_dict[expr['name']]
        except KeyError:
            return symbolics.Symbol(expr['name'])
    elif expr['type'] == 'Number':
        return symbolics.sympify(expr['value'])
    else:
        raise NotImplementedError(expr['type'] + ' is not implemented')

def object_to_json(obj):
    """Convert object that cannot be natively serialized by python to JSON representation."""
    if isinstance(obj, (datetime.datetime, datetime.date, datetime.time)):
        return obj.isoformat()
    return str(obj)

def grad_f(xy):
    """Gradient of f"""
    return np.array([grad_fx(xy[0], xy[1]), grad_fy(xy[0], xy[1])])

def prox_circle(xy, step):
    """Projection onto circle"""
    center = np.array([0, 0])
    dxy = xy - center
    radius = 0.5
    if 1:
        phi = np.arctan2(dxy[1], dxy[0])
        return center + radius * np.array([np.cos(phi), np.sin(phi)])
    else:
        return xy

def prox_yline(y, step):
    """Projection onto line in y"""
    if not np.isscalar(y):
        y = y[0]
    if y > -0.75:
        return np.array([-0.75])
    else:
        return np.array([y])

def prox_line(xy, step):
    """2D projection onto 2 lines"""
    return np.concatenate((prox_xline(xy[0], step), prox_yline(xy[1], step)))

def prox_lim(xy, step, boundary=None):
    """Proximal projection operator"""
    if boundary == 'circle':
        return prox_circle(xy, step)
    if boundary == 'line':
        return prox_line(xy, step)
    return xy

def prox_gradf_lim(xy, step, boundary=None):
    """Forward-backward step: gradient, followed by projection"""
    return prox_lim(prox_gradf(xy, step), step, boundary=boundary)

def prox_gradf12(x, step, j=None, Xs=None):
    """1D gradient operator for x or y"""
    if j == 0:
        return x - step * grad_fx(Xs[0][0], Xs[1][0])
    if j == 1:
        y = x
        return y - step * grad_fy(Xs[0][0], Xs[1][0])
    raise NotImplementedError

def prox_lim12(x, step, j=None, Xs=None, boundary=None):
    if boundary == 'line':
        if j == 0:
            return prox_xline(x, step)
        if j == 1:
            return prox_yline(x, step)
    raise NotImplementedError
    '\n    if boundary == "circle":\n        if j == 0:\n            xy = np.array([x[0], Xs[1][0]])\n        if j == 1:\n            xy = np.array([Xs[0][0], x[0]])\n        return [prox_circle(xy, step)[j]]\n    '

def prox_gradf_lim12(x, step, j=None, Xs=None, boundary=None):
    """1D projection operator"""
    if j == 0:
        x -= step * grad_fx(Xs[0][0], Xs[1][0])
    if j == 1:
        y = x
        y -= step * grad_fy(Xs[0][0], Xs[1][0])
    return prox_lim12(x, step, j=j, Xs=Xs, boundary=boundary)

def get_step_f(step_f, lR2, lS2):
    """Update the stepsize of given the primal and dual errors.

    See Boyd (2011), section 3.4.1"""
    mu, tau = (10, 2)
    if lR2 > mu * lS2:
        return step_f * tau
    elif lS2 > mu * lR2:
        return step_f / tau
    return step_f

def get_variable_errors(X, L, LX, Z, U, step_g, e_rel, e_abs=0):
    """Get the errors in a single multiplier method step

    For a given linear operator A, (and its dot product with X to save time),
    calculate the errors in the prime and dual variables, used by the
    Boyd 2011 Section 3 stopping criteria."""
    n = X.size
    p = Z.size
    e_pri2 = np.sqrt(p) * e_abs / L.spectral_norm + e_rel * np.max([l2(LX), l2(Z)])
    if step_g is not None:
        e_dual2 = np.sqrt(n) * e_abs / L.spectral_norm + e_rel * l2(L.T.dot(U) / step_g)
    else:
        e_dual2 = np.sqrt(n) * e_abs / L.spectral_norm + e_rel * l2(L.T.dot(U))
    return (e_pri2, e_dual2)

def check_constraint_convergence(X, L, LX, Z, U, R, S, step_f, step_g, e_rel, e_abs):
    """Calculate if all constraints have converged.

    Using the stopping criteria from Boyd 2011, Sec 3.3.1, calculate whether the
    variables for each constraint have converged."""
    if isinstance(L, list):
        M = len(L)
        convergence = True
        errors = []
        for i in range(M):
            c, e = check_constraint_convergence(X, L[i], LX[i], Z[i], U[i], R[i], S[i], step_f, step_g[i], e_rel, e_abs)
            convergence &= c
            errors.append(e)
        return (convergence, errors)
    else:
        e_pri, e_dual = get_variable_errors(X, L, LX, Z, U, step_g, e_rel, e_abs)
        lR = l2(R)
        lS = l2(S)
        convergence = lR <= e_pri and lS <= e_dual
        return (convergence, (e_pri, e_dual, lR, lS))

def generateAmplitudes(k):
    """Makes mixing coefficients"""
    res = np.array([np.random.random() for i in range(k)])
    return res / res.sum()

def add_noise(Y, sigma):
    """Adds noise to Y"""
    return Y + np.random.normal(0, sigma, Y.shape)

def prox_zero(X, step):
    """Proximal operator to project onto zero
    """
    return np.zeros(X.shape, dtype=X.dtype)

def prox_unity(X, step, axis=0):
    """Projection onto sum=1 along an axis
    """
    return X / np.sum(X, axis=axis, keepdims=True)

def prox_unity_plus(X, step, axis=0):
    """Non-negative projection onto sum=1 along an axis
    """
    return prox_unity(prox_plus(X, step), step, axis=axis)

def prox_components(X, step, prox=None, axis=0):
    """Split X along axis and apply prox to each chunk.

    prox can be a list."""
    K = X.shape[axis]
    if not hasattr(prox_list, '__iter__'):
        prox = [prox] * K
    assert len(prox_list) == K
    if axis == 0:
        Pk = [prox_list[k](X[k], step) for k in range(K)]
    if axis == 1:
        Pk = [prox_list[k](X[:, k], step) for k in range(K)]
    return np.stack(Pk, axis=axis)

def prox_hard_plus(X, step, thresh=0):
    """Hard thresholding with projection onto non-negative numbers
    """
    return prox_plus(prox_hard(X, step, thresh=thresh), step)

def prox_soft(X, step, thresh=0):
    """Soft thresholding proximal operator
    """
    thresh_ = _step_gamma(step, thresh)
    return np.sign(X) * prox_plus(np.abs(X) - thresh_, step)

def prox_soft_plus(X, step, thresh=0):
    """Soft thresholding with projection onto non-negative numbers
    """
    return prox_plus(prox_soft(X, step, thresh=thresh), step)

def profile(ctx, filepath, calltree=False):
    """Run and profile a given Python script.

    :param str filepath: The filepath of the script to profile"""
    filepath = pathlib.Path(filepath)
    if not filepath.is_file():
        report.error(ctx, 'profile', f'no such script {filepath!s}')
    elif calltree:
        report.info(ctx, 'profile', f'profiling script {filepath!s} calltree')
        ctx.run(f'python -m cProfile -o .profile.cprof {filepath!s} && pyprof2calltree -k -i .profile.cprof && rm -rf .profile.cprof')
    else:
        report.info(ctx, 'profile', f'profiling script {filepath!s}')
        ctx.run(f'vprof -c cmhp {filepath!s}')

def _handle_dumps(self, handler, **kwargs):
    """Dumps caller, used by partial method for dynamic handler assignments.

    :param object handler: The dump handler
    :return: The dumped string
    :rtype: str"""
    return handler.dumps(self.__class__, to_dict(self), **kwargs)

def _build_string_type(var, property_path=None):
    """Builds schema definitions for string type values.

    :param var: The string type value
    :param List[str] property_path: The property path of the current type,
        defaults to None, optional
    :param property_path: [type], optional
    :return: The built schema definition
    :rtype: Dict[str, Any]"""
    if not property_path:
        property_path = []
    schema = {'type': 'string'}
    if is_builtin_type(var):
        return schema
    if is_regex_type(var):
        schema['pattern'] = var.__supertype__.pattern
        return schema
    if is_config_var(var):
        schema.update(_build_attribute_modifiers(var, {'min': 'minLength', 'max': 'maxLength'}))
        if is_regex_type(var.type):
            schema['pattern'] = var.type.__supertype__.pattern
    return schema

def _build_integer_type(var, property_path=None):
    """Builds schema definitions for integer type values.

    :param var: The integer type value
    :param List[str] property_path: The property path of the current type,
        defaults to None, optional
    :param property_path: [type], optional
    :return: The built schema definition
    :rtype: Dict[str, Any]"""
    if not property_path:
        property_path = []
    schema = {'type': 'integer'}
    if is_builtin_type(var):
        return schema
    if is_config_var(var):
        schema.update(_build_attribute_modifiers(var, {'min': 'minimum', 'max': 'maximum'}))
    return schema

def _build_number_type(var, property_path=None):
    """Builds schema definitions for number type values.

    :param var: The number type value
    :param List[str] property_path: The property path of the current type,
        defaults to None, optional
    :param property_path: [type], optional
    :return: The built schema definition
    :rtype: Dict[str, Any]"""
    if not property_path:
        property_path = []
    schema = {'type': 'number'}
    if is_builtin_type(var):
        return schema
    if is_config_var(var):
        schema.update(_build_attribute_modifiers(var, {'min': 'minimum', 'max': 'maximum'}))
    return schema

def _build_array_type(var, property_path=None):
    """Builds schema definitions for array type values.

    :param var: The array type value
    :param List[str] property_path: The property path of the current type,
        defaults to None, optional
    :param property_path: [type], optional
    :return: The built schema definition
    :rtype: Dict[str, Any]"""
    if not property_path:
        property_path = []
    schema = {'type': 'array', 'items': {'$id': f"#/{'/'.join(property_path)}/items"}}
    if is_builtin_type(var):
        return schema
    if is_config_var(var):
        schema.update(_build_attribute_modifiers(var, {'min': 'minItems', 'max': 'maxItems', 'unique': 'uniqueItems', 'contains': 'contains'}))
        if is_typing_type(var.type) and len(var.type.__args__) > 0:
            nested_type = var.type.__args__[0]
            schema['items'].update(_build(nested_type, property_path=property_path + ['items']))
    elif is_typing_type(var):
        nested_type = var.__args__[0]
        schema['items'].update(_build(nested_type, property_path=property_path + ['items']))
    return schema

def _build_object_type(var, property_path=None):
    """Builds schema definitions for object type values.

    :param var: The object type value
    :param List[str] property_path: The property path of the current type,
        defaults to None, optional
    :param property_path: [type], optional
    :return: The built schema definition
    :rtype: Dict[str, Any]"""
    if not property_path:
        property_path = []
    schema = {'type': 'object'}
    if is_builtin_type(var):
        return schema
    entry = var.metadata[CONFIG_KEY]
    if isinstance(entry.min, int):
        schema['minProperties'] = entry.min
    if isinstance(entry.max, int):
        schema['maxProperties'] = entry.max
    if is_typing_type(var.type) and len(var.type.__args__) == 2:
        key_type, value_type = var.type.__args__
        key_pattern = '^(.*)$'
        if is_regex_type(key_type):
            key_pattern = key_type.__supertype__.pattern
        elif not is_string_type(key_type):
            raise ValueError(f'cannot serialize object with key of type {key_type!r}, located in var {var.name!r}')
        schema['patternProperties'] = {key_pattern: _build(value_type, property_path=property_path)}
    return schema

def _build_type(type_, value, property_path=None):
    """Builds the schema definition based on the given type for the given value.

    :param type_: The type of the value
    :param value: The value to build the schema definition for
    :param List[str] property_path: The property path of the current type,
        defaults to None, optional
    :return: The built schema definition
    :rtype: Dict[str, Any]"""
    if not property_path:
        property_path = []
    for type_check, builder in ((is_enum_type, _build_enum_type), (is_null_type, _build_null_type), (is_bool_type, _build_bool_type), (is_string_type, _build_string_type), (is_integer_type, _build_integer_type), (is_number_type, _build_number_type), (is_array_type, _build_array_type), (is_object_type, _build_object_type)):
        if type_check(type_):
            return builder(value, property_path=property_path)
    if type_:
        warnings.warn(f'unhandled translation for type {type_!r} with value {value!r}')
    return {}

def _build(value, property_path=None):
    """The generic schema definition build method.

    :param value: The value to build a schema definition for
    :param List[str] property_path: The property path of the current type,
        defaults to None, optional
    :return: The built schema definition
    :rtype: Dict[str, Any]"""
    if not property_path:
        property_path = []
    if is_config_type(value):
        return _build_config(value, property_path=property_path)
    elif is_config_var(value):
        return _build_var(value, property_path=property_path)
    elif is_builtin_type(value):
        return _build_type(value, value, property_path=property_path)
    elif is_regex_type(value):
        return _build_type(str, value, property_path=property_path)
    elif is_typing_type(value):
        return _build_type(value, value, property_path=property_path)
    return _build_type(type(value), value, property_path=property_path)

def _get_types(type_):
    """Gathers all types within the ``TYPE_MAPPINGS`` for a specific ``Types`` value.

    :param Types type_: The type to retrieve
    :return: All types within the ``TYPE_MAPPINGS``
    :rtype: list"""
    return list(itertools.chain.from_iterable(map(lambda x: TYPE_MAPPINGS[x].get(type_, []), TYPE_MAPPINGS)))

def decode_bytes(string):
    """Decodes a given base64 string into bytes.

    :param str string: The string to decode
    :return: The decoded bytes
    :rtype: bytes"""
    if is_string_type(type(string)):
        string = bytes(string, 'utf-8')
    return base64.decodebytes(string)

def is_config_var(var):
    """Checks if the given value is a valid ``file_config.var``.

    :param var: The value to check
    :return: True if the given value is a var, otherwise False
    :rtype: bool"""
    return isinstance(var, (attr._make.Attribute, attr._make._CountingAttr)) and hasattr(var, 'metadata') and (CONFIG_KEY in var.metadata)

def is_config_type(type_):
    """Checks if the given type is ``file_config.config`` decorated.

    :param type_: The type to check
    :return: True if the type is config decorated, otherwise False
    :rtype: bool"""
    return isinstance(type_, type) and hasattr(type_, '__attrs_attrs__') and hasattr(type_, CONFIG_KEY)

def is_enum_type(type_):
    """Checks if the given type is an enum type.

    :param type_: The type to check
    :return: True if the type is a enum type, otherwise False
    :rtype: bool"""
    return isinstance(type_, type) and issubclass(type_, tuple(_get_types(Types.ENUM)))

def is_regex_type(type_):
    """Checks if the given type is a regex type.

    :param type_: The type to check
    :return: True if the type is a regex type, otherwise False
    :rtype: bool"""
    return callable(type_) and getattr(type_, '__name__', None) == REGEX_TYPE_NAME and hasattr(type_, '__supertype__') and is_compiled_pattern(type_.__supertype__)

def is_union_type(type_):
    """Checks if the given type is a union type.

    :param type_: The type to check
    :return: True if the type is a union type, otherwise False
    :rtype: bool"""
    if is_typing_type(type_) and hasattr(type_, '__origin__'):
        return type_.__origin__ in _get_types(Types.UNION)
    return False

def is_string_type(type_):
    """Checks if the given type is a string type.

    :param type_: The type to check
    :return: True if the type is a string type, otherwise False
    :rtype: bool"""
    string_types = _get_types(Types.STRING)
    if is_typing_type(type_):
        return type_ in string_types or is_regex_type(type_)
    return type_ in string_types

def is_array_type(type_):
    """Checks if the given type is a array type.

    :param type_: The type to check
    :return: True if the type is a array type, otherwise False
    :rtype: bool"""
    array_types = _get_types(Types.ARRAY)
    if is_typing_type(type_):
        return type_ in array_types or (hasattr(type_, '__origin__') and type_.__origin__ in array_types)
    return type_ in array_types

def is_object_type(type_):
    """Checks if the given type is a object type.

    :param type_: The type to check
    :return: True if the type is a object type, otherwise False
    :rtype: bool"""
    object_types = _get_types(Types.OBJECT)
    if is_typing_type(type_):
        return type_ in object_types or (hasattr(type_, '__origin__') and type_.__origin__ in object_types)
    return type_ in object_types

def typecast(type_, value):
    """Tries to smartly typecast the given value with the given type.

    :param type_: The type to try to use for the given value
    :param value: The value to try and typecast to the given type
    :return: The typecasted value if possible, otherwise just the original value"""
    if is_builtin_type(type_) or is_collections_type(type_) or is_enum_type(type_):
        if is_bytes_type(type_):
            return decode_bytes(value)
        return type_(value)
    elif is_regex_type(type_):
        return typecast(str, value)
    elif is_typing_type(type_):
        try:
            base_type = type_.__extra__
        except AttributeError:
            base_type = type_.__origin__
        arg_types = type_.__args__
        if is_array_type(type_):
            if len(arg_types) == 1:
                item_type = arg_types[0]
                return base_type([typecast(item_type, item) for item in value])
            else:
                return base_type(value)
        elif is_object_type(type_):
            if len(arg_types) == 2:
                key_type, item_type = arg_types
                return base_type({typecast(key_type, key): typecast(item_type, item) for key, item in value.items()})
            else:
                return base_type(value)
        else:
            return base_type(value)
    else:
        return value

def version(ctx, version=None, force=False):
    """Specify a new version for the package.

    .. important:: If no version is specified, will take the most recent parsable git
        tag and bump the patch number.

    :param str version: The new version of the package.
    :param bool force: If True, skips version check"""
    updates = {ctx.directory.joinpath('setup.cfg'): [('^(version\\s?=\\s?)(.*)', '\\g<1>{version}')], ctx.package.directory.joinpath('__version__.py'): [('(__version__\\s?=\\s?)(.*)', '\\g<1>"{version}"')]}
    previous_version = get_previous_version(ctx)
    if isinstance(version, str):
        version = parver.Version.parse(version)
        if not force and version <= previous_version:
            error_message = f'version {version!s} is <= to previous version {previous_version!s}'
            report.error(ctx, 'package.version', error_message)
            raise ValueError(error_message)
    else:
        version = previous_version.bump_release(index=len(previous_version.release) - 1)
    report.info(ctx, 'package.version', f'updating version to {version!s}')
    for path, replacements in updates.items():
        if path.is_file():
            content = path.read_text()
            for pattern, sub in replacements:
                report.debug(ctx, 'package.version', f'applying replacement ({pattern!r}, {sub!r}) to {path!s}')
                content = re.sub(pattern, sub.format(version=version), content, re.M)
            path.write_text(content)

def s(obj):
    """Helper to normalize linefeeds in strings."""
    if isinstance(obj, bytes):
        return obj.replace(b'\n', os.linesep.encode())
    else:
        return obj.replace('\n', os.linesep)

def parse_config(file_path):
    """Loads the configuration file given as parameter"""
    config_parser = configparser.ConfigParser()
    config_parser.read(file_path)
    plugin_config = {}
    options = config_parser.options(CONFIG_OPTION)
    for option in options:
        try:
            plugin_config[option] = config_parser.get(CONFIG_OPTION, option)
            if plugin_config[option] == -1:
                print('skip: %s' % option)
        except Exception as e:
            print('exception on %s!' % option)
            print(e.message)
            plugin_config[option] = None
    return plugin_config

def start_plugin(file_path=None):
    """This function initialize the Ocean plugin"""
    if os.getenv('CONFIG_PATH'):
        file_path = os.getenv('CONFIG_PATH')
    else:
        file_path = file_path
    if file_path is not None:
        config = parse_config(file_path)
        plugin_instance = load_plugin(config)
    else:
        plugin_instance = load_plugin
    return plugin_instance

def findMachinesViaWrapper(within):
    """Recursively yield L{MethodicalMachine}s and their FQPNs within a
    L{PythonModule} or a L{twisted.python.modules.PythonAttribute}
    wrapper object.

    Note that L{PythonModule}s may refer to packages, as well.

    The discovery heuristic considers L{MethodicalMachine} instances
    that are module-level attributes or class-level attributes
    accessible from module scope.  Machines inside nested classes will
    be discovered, but those returned from functions or methods will not be.

    @type within: L{PythonModule} or L{twisted.python.modules.PythonAttribute}
    @param within: Where to start the search.

    @return: a generator which yields FQPN, L{MethodicalMachine} pairs."""
    queue = collections.deque([within])
    visited = set()
    while queue:
        attr = queue.pop()
        value = attr.load()
        if isinstance(value, MethodicalMachine) and value not in visited:
            visited.add(value)
            yield (attr.name, value)
        elif inspect.isclass(value) and isOriginalLocation(attr) and (value not in visited):
            visited.add(value)
            queue.extendleft(attr.iterAttributes())
        elif isinstance(attr, PythonModule) and value not in visited:
            visited.add(value)
            queue.extendleft(attr.iterAttributes())
            queue.extendleft(attr.iterModules())

def wrapFQPN(fqpn):
    """Given an FQPN, retrieve the object via the global Python module
    namespace and wrap it with a L{PythonModule} or a
    L{twisted.python.modules.PythonAttribute}."""
    if not fqpn:
        raise InvalidFQPN('FQPN was empty')
    components = collections.deque(fqpn.split('.'))
    if '' in components:
        raise InvalidFQPN("name must be a string giving a '.'-separated list of Python identifiers, not %r" % (fqpn,))
    component = components.popleft()
    try:
        module = getModule(component)
    except KeyError:
        raise NoModule(component)
    while components:
        component = components.popleft()
        try:
            module = module[component]
        except KeyError:
            components.appendleft(component)
            break
        else:
            module.load()
    else:
        return module
    attribute = module
    for component in components:
        try:
            attribute = next((child for child in attribute.iterAttributes() if child.name.rsplit('.', 1)[-1] == component))
        except StopIteration:
            raise NoObject('{}.{}'.format(attribute.name, component))
    return attribute

def _keywords_only(f):
    """Decorate a function so all its arguments must be passed by keyword.

    A useful utility for decorators that take arguments so that they don't
    accidentally get passed the thing they're decorating as their first
    argument.

    Only works for methods right now."""
    @wraps(f)
    def g(self, **kw):
        return f(self, **kw)
    return g

def _filterArgs(args, kwargs, inputSpec, outputSpec):
    """Filter out arguments that were passed to input that output won't accept.

    :param tuple args: The *args that input received.
    :param dict kwargs: The **kwargs that input received.
    :param ArgSpec inputSpec: The input's arg spec.
    :param ArgSpec outputSpec: The output's arg spec.
    :return: The args and kwargs that output will accept.
    :rtype: Tuple[tuple, dict]"""
    named_args = tuple(zip(inputSpec.args[1:], args))
    if outputSpec.varargs:
        return_args = args
    else:
        return_args = [v for n, v in named_args if n in outputSpec.args]
    passed_arg_names = tuple(kwargs)
    for name, value in named_args:
        passed_arg_names += (name, value)
    defaults = zip(inputSpec.args[::-1], inputSpec.defaults[::-1])
    full_kwargs = {n: v for n, v in defaults if n not in passed_arg_names}
    full_kwargs.update(kwargs)
    if outputSpec.varkw:
        return_kwargs = full_kwargs
    else:
        all_accepted_names = outputSpec.args[1:] + outputSpec.kwonlyargs
        return_kwargs = {n: v for n, v in full_kwargs.items() if n in all_accepted_names}
    return (return_args, return_kwargs)

def elementMaker(name, *children, **attrs):
    """Construct a string from the HTML element description."""
    formattedAttrs = ' '.join(('{}={}'.format(key, _gvquote(str(value))) for key, value in sorted(attrs.items())))
    formattedChildren = ''.join(children)
    return u'<{name} {attrs}>{children}</{name}>'.format(name=name, attrs=formattedAttrs, children=formattedChildren)

def tableMaker(inputLabel, outputLabels, port, _E=elementMaker):
    """Construct an HTML table to label a state transition."""
    colspan = {}
    if outputLabels:
        colspan['colspan'] = str(len(outputLabels))
    inputLabelCell = _E('td', _E('font', inputLabel, face='menlo-italic'), color='purple', port=port, **colspan)
    pointSize = {'point-size': '9'}
    outputLabelCells = [_E('td', _E('font', outputLabel, **pointSize), color='pink') for outputLabel in outputLabels]
    rows = [_E('tr', inputLabelCell)]
    if outputLabels:
        rows.append(_E('tr', *outputLabelCells))
    return _E('table', *rows)

def preserveName(f):
    """Preserve the name of the given function on the decorated function."""
    def decorator(decorated):
        return copyfunction(decorated, dict(name=f.__name__), dict(name=f.__name__))
    return decorator

def get_kafka_brokers():
    """Parses the KAKFA_URL and returns a list of hostname:port pairs in the format
    that kafka-python expects."""
    if not os.environ.get('KAFKA_URL'):
        raise RuntimeError('The KAFKA_URL config variable is not set.')
    return ['{}:{}'.format(parsedUrl.hostname, parsedUrl.port) for parsedUrl in [urlparse(url) for url in os.environ.get('KAFKA_URL').split(',')]]

def mkdir(name, mode=488):
    """Implementation of ``mkdir -p``: Creates folder with the given `name` and
    the given permissions (`mode`)

    * Create missing parents folder
    * Do nothing if the folder with the given `name` already exists
    * Raise `OSError` if there is already a file with the given `name`"""
    if os.path.isdir(name):
        pass
    elif os.path.isfile(name):
        raise OSError("A file with the same name as the desired dir, '%s', already exists." % name)
    else:
        os.makedirs(name, mode)

def bind(value, name):
    """A filter that prints %s, and stores the value
    in an array, so that it can be bound using a prepared statement

    This filter is automatically applied to every {{variable}}
    during the lexing stage, so developers can't forget to bind"""
    if isinstance(value, Markup):
        return value
    elif requires_in_clause(value):
        raise MissingInClauseException("Got a list or tuple. \n            Did you forget to apply '|inclause' to your query?")
    else:
        return _bind_param(_thread_local.bind_params, name, value)

