def _flatten_schema(schema):
    """:type schema: dict"""
    def _flatten(schema, parent_path, result):
        """:type schema: dict"""
        for path, value in schema.items():
            if isinstance(path, InstrumentedAttribute):
                path = path.key
            if isinstance(value, tuple):
                join_method, inner_schema = (value[0], value[1])
            elif isinstance(value, dict):
                join_method, inner_schema = (JOINED, value)
            else:
                join_method, inner_schema = (value, None)
            full_path = parent_path + '.' + path if parent_path else path
            result[full_path] = join_method
            if inner_schema:
                _flatten(inner_schema, full_path, result)
    result = {}
    _flatten(schema, '', result)
    return result

def _eager_expr_from_flat_schema(flat_schema):
    """:type flat_schema: dict"""
    result = []
    for path, join_method in flat_schema.items():
        if join_method == JOINED:
            result.append(joinedload(path))
        elif join_method == SUBQUERY:
            result.append(subqueryload(path))
        else:
            raise ValueError('Bad join method `{}` in `{}`'.format(join_method, path))
    return result

def _parse_path_and_make_aliases(entity, entity_path, attrs, aliases):
    """:type entity: InspectionMixin
    :type entity_path: str
    :type attrs: list
    :type aliases: OrderedDict

    Sample values:

    attrs: ['product__subject_ids', 'user_id', '-group_id',
            'user__name', 'product__name', 'product__grade_from__order']
    relations: {'product': ['subject_ids', 'name'], 'user': ['name']}"""
    relations = {}
    for attr in attrs:
        if RELATION_SPLITTER in attr:
            relation_name, nested_attr = attr.split(RELATION_SPLITTER, 1)
            if relation_name in relations:
                relations[relation_name].append(nested_attr)
            else:
                relations[relation_name] = [nested_attr]
    for relation_name, nested_attrs in relations.items():
        path = entity_path + RELATION_SPLITTER + relation_name if entity_path else relation_name
        if relation_name not in entity.relations:
            raise KeyError('Incorrect path `{}`: {} doesnt have `{}` relationship '.format(path, entity, relation_name))
        relationship = getattr(entity, relation_name)
        alias = aliased(relationship.property.argument())
        aliases[path] = (alias, relationship)
        _parse_path_and_make_aliases(alias, path, nested_attrs, aliases)

def _find_unused_static_warnings(filename, lines, ast_list):
    """Warn about unused static variables."""
    static_declarations = dict(_get_static_declarations(ast_list))
    def find_variables_use(body):
        for child in body:
            if child.name in static_declarations:
                static_use_counts[child.name] += 1
    static_use_counts = collections.Counter()
    for node in ast_list:
        if isinstance(node, ast.Function) and node.body:
            find_variables_use(node.body)
        elif isinstance(node, ast.Class) and node.body:
            for child in node.body:
                if isinstance(child, ast.Function) and child.body:
                    find_variables_use(child.body)
    count = 0
    for name, _ in sorted(static_declarations.items(), key=lambda x: x[1].start):
        if not static_use_counts[name]:
            print("{}:{}: unused variable '{}'".format(filename, lines.get_line_number(static_declarations[name].start), name))
            count += 1
    return count

def read_file(filename, print_error=True):
    """Returns the contents of a file."""
    try:
        for encoding in ['utf-8', 'latin1']:
            try:
                with io.open(filename, encoding=encoding) as fp:
                    return fp.read()
            except UnicodeDecodeError:
                pass
    except IOError as exception:
        if print_error:
            print(exception, file=sys.stderr)
        return None

def compose(f: Callable[[Any], Monad], g: Callable[[Any], Monad]) -> Callable[[Any], Monad]:
    """Monadic compose function.

    Right-to-left Kleisli composition of two monadic functions.

    (<=<) :: Monad m => (b -> m c) -> (a -> m b) -> a -> m c
    f <=< g = \\x -> g x >>= f"""
    return lambda x: g(x).bind(f)

def compress(func):
    """Compress route return data with gzip compression"""
    @wraps(func)
    def wrapper(*args, **kwargs):
        result = func(*args, **kwargs)
        if 'gzip' in bottle.request.headers.get('Accept-Encoding', '') and isinstance(result, string_type) and (len(result) > 1024):
            if isinstance(result, unicode):
                result = result.encode('utf-8')
            tmp_fo = BytesIO()
            with gzip.GzipFile(mode='wb', fileobj=tmp_fo) as gzip_fo:
                gzip_fo.write(result)
            result = tmp_fo.getvalue()
            bottle.response.add_header('Content-Encoding', 'gzip')
        return result
    return wrapper

def solve_sdr(prob, *args, **kwargs):
    """Solve the SDP relaxation.
    """
    X = cvx.Semidef(prob.n + 1)
    W = prob.f0.homogeneous_form()
    rel_obj = cvx.Minimize(cvx.sum_entries(cvx.mul_elemwise(W, X)))
    rel_constr = [X[-1, -1] == 1]
    for f in prob.fs:
        W = f.homogeneous_form()
        lhs = cvx.sum_entries(cvx.mul_elemwise(W, X))
        if f.relop == '==':
            rel_constr.append(lhs == 0)
        else:
            rel_constr.append(lhs <= 0)
    rel_prob = cvx.Problem(rel_obj, rel_constr)
    rel_prob.solve(*args, **kwargs)
    if rel_prob.status not in [cvx.OPTIMAL, cvx.OPTIMAL_INACCURATE]:
        raise Exception('Relaxation problem status: %s' % rel_prob.status)
    return (X.value, rel_prob.value)

def get_qcqp_form(prob):
    """Returns the problem metadata in QCQP class
    """
    if not prob.objective.args[0].is_quadratic():
        raise Exception('Objective is not quadratic.')
    if not all([constr._expr.is_quadratic() for constr in prob.constraints]):
        raise Exception('Not all constraints are quadratic.')
    if prob.is_dcp():
        logging.warning('Problem is already convex; specifying solve method is unnecessary.')
    extractor = QuadCoeffExtractor(*get_id_map(prob.variables()))
    P0, q0, r0 = extractor.get_coeffs(prob.objective.args[0])
    P0, q0, r0 = ((P0[0] + P0[0].T) / 2.0, q0.T.tocsc(), r0[0])
    if prob.objective.NAME == 'maximize':
        P0, q0, r0 = (-P0, -q0, -r0)
    f0 = QuadraticFunction(P0, q0, r0)
    fs = []
    for constr in prob.constraints:
        sz = constr._expr.size[0] * constr._expr.size[1]
        Pc, qc, rc = extractor.get_coeffs(constr._expr)
        for i in range(sz):
            fs.append(QuadraticFunction((Pc[i] + Pc[i].T) / 2.0, qc[i, :].T.tocsc(), rc[i], constr.OP_NAME))
    return QCQPForm(f0, fs)

