def get_list_qtype(array):
    """Finds out a corresponding qtype for a specified `QList`/`numpy.ndarray`
    instance.

    :Parameters:
     - `array` (`QList` or `numpy.ndarray`) - array to be checked

    :returns: `integer` - qtype matching the specified array object"""
    if not isinstance(array, numpy.ndarray):
        raise ValueError('array parameter is expected to be of type: numpy.ndarray, got: %s' % type(array))
    if isinstance(array, QList):
        return -abs(array.meta.qtype)
    qtype = None
    if str(array.dtype) in ('|S1', '<U1', '>U1', '|U1'):
        qtype = QCHAR
    if qtype is None:
        qtype = Q_TYPE.get(array.dtype.type, None)
    if qtype is None and array.dtype.type in (numpy.datetime64, numpy.timedelta64):
        qtype = TEMPORAL_PY_TYPE.get(str(array.dtype), None)
    if qtype is None:
        qtype = Q_TYPE.get(type(array[0]), QGENERAL_LIST)
    return qtype

def parse_url(url, warning=True):
    """Parse URLs especially for Google Drive links.

    file_id: ID of file on Google Drive.
    is_download_link: Flag if it is download link of Google Drive."""
    parsed = urllib_parse.urlparse(url)
    query = urllib_parse.parse_qs(parsed.query)
    is_gdrive = parsed.hostname == 'drive.google.com'
    is_download_link = parsed.path.endswith('/uc')
    file_id = None
    if is_gdrive and 'id' in query:
        file_ids = query['id']
        if len(file_ids) == 1:
            file_id = file_ids[0]
    match = re.match('^/file/d/(.*?)/view$', parsed.path)
    if match:
        file_id = match.groups()[0]
    if is_gdrive and (not is_download_link):
        warnings.warn('You specified Google Drive Link but it is not the correct link to download the file. Maybe you should try: {url}'.format(url='https://drive.google.com/uc?id={}'.format(file_id)))
    return (file_id, is_download_link)

def extractall(path, to=None):
    """Extract archive file.

    Parameters
    ----------
    path: str
        Path of archive file to be extracted.
    to: str, optional
        Directory to which the archive file will be extracted.
        If None, it will be set to the parent directory of the archive file."""
    if to is None:
        to = osp.dirname(path)
    if path.endswith('.zip'):
        opener, mode = (zipfile.ZipFile, 'r')
    elif path.endswith('.tar'):
        opener, mode = (tarfile.open, 'r')
    elif path.endswith('.tar.gz') or path.endswith('.tgz'):
        opener, mode = (tarfile.open, 'r:gz')
    elif path.endswith('.tar.bz2') or path.endswith('.tbz'):
        opener, mode = (tarfile.open, 'r:bz2')
    else:
        raise ValueError("Could not extract '%s' as no appropriate extractor is found" % path)
    def namelist(f):
        if isinstance(f, zipfile.ZipFile):
            return f.namelist()
        return [m.path for m in f.members]
    def filelist(f):
        files = []
        for fname in namelist(f):
            fname = osp.join(to, fname)
            files.append(fname)
        return files
    with opener(path, mode) as f:
        f.extractall(path=to)
    return filelist(f)

def find_template_companion(template, extension='', check=True):
    """Returns the first found template companion file"""
    if check and (not os.path.isfile(template)):
        yield ''
        return
    template = os.path.abspath(template)
    template_dirname = os.path.dirname(template)
    template_basename = os.path.basename(template).split('.')
    current_path = template_dirname
    stop_path = os.path.commonprefix((os.getcwd(), current_path))
    stop_path = os.path.dirname(stop_path)
    token = template_basename[0] + '.'
    while True:
        for file in sorted(os.listdir(current_path)):
            if not file.startswith(token):
                continue
            if not file.endswith(extension):
                continue
            file_parts = file.split('.')
            for i in range(1, len(template_basename)):
                if template_basename[:-i] != file_parts[:-1]:
                    continue
                if current_path == template_dirname:
                    if file_parts == template_basename:
                        continue
                yield os.path.join(current_path, file)
        if current_path == stop_path:
            break
        current_path = os.path.split(current_path)[0]

def sanitize_network(network, ip_version):
    """:return: Network string
    :rtype: str
    :raises ValueError: if the network string is invalid."""
    import ipaddress
    if typepy.is_null_string(network) or network.lower() == 'anywhere':
        return get_anywhere_network(ip_version)
    try:
        if ip_version == 4:
            ipaddress.IPv4Address(network)
            return network + '/32'
        if ip_version == 6:
            return ipaddress.IPv6Address(network).compressed
    except ipaddress.AddressValueError:
        pass
    if ip_version == 4:
        return ipaddress.IPv4Network(six.text_type(network)).compressed
    if ip_version == 6:
        return ipaddress.IPv6Network(six.text_type(network)).compressed
    raise ValueError('unexpected ip version: {}'.format(ip_version))

def request(identifier, namespace='cid', domain='compound', operation=None, output='JSON', searchtype=None, **kwargs):
    """Construct API request from parameters and return the response.

    Full specification at http://pubchem.ncbi.nlm.nih.gov/pug_rest/PUG_REST.html"""
    if not identifier:
        raise ValueError('identifier/cid cannot be None')
    if isinstance(identifier, int):
        identifier = str(identifier)
    if not isinstance(identifier, text_types):
        identifier = ','.join((str(x) for x in identifier))
    kwargs = dict(((k, v) for k, v in kwargs.items() if v is not None))
    urlid, postdata = (None, None)
    if namespace == 'sourceid':
        identifier = identifier.replace('/', '.')
    if namespace in ['listkey', 'formula', 'sourceid'] or searchtype == 'xref' or (searchtype and namespace == 'cid') or (domain == 'sources'):
        urlid = quote(identifier.encode('utf8'))
    else:
        postdata = urlencode([(namespace, identifier)]).encode('utf8')
    comps = filter(None, [API_BASE, domain, searchtype, namespace, urlid, operation, output])
    apiurl = '/'.join(comps)
    if kwargs:
        apiurl += '?%s' % urlencode(kwargs)
    try:
        log.debug('Request URL: %s', apiurl)
        log.debug('Request data: %s', postdata)
        response = urlopen(apiurl, postdata)
        return response
    except HTTPError as e:
        raise PubChemHTTPError(e)

def get(identifier, namespace='cid', domain='compound', operation=None, output='JSON', searchtype=None, **kwargs):
    """Request wrapper that automatically handles async requests."""
    if searchtype and searchtype != 'xref' or namespace in ['formula']:
        response = request(identifier, namespace, domain, None, 'JSON', searchtype, **kwargs).read()
        status = json.loads(response.decode())
        if 'Waiting' in status and 'ListKey' in status['Waiting']:
            identifier = status['Waiting']['ListKey']
            namespace = 'listkey'
            while 'Waiting' in status and 'ListKey' in status['Waiting']:
                time.sleep(2)
                response = request(identifier, namespace, domain, operation, 'JSON', **kwargs).read()
                status = json.loads(response.decode())
            if not output == 'JSON':
                response = request(identifier, namespace, domain, operation, output, searchtype, **kwargs).read()
    else:
        response = request(identifier, namespace, domain, operation, output, searchtype, **kwargs).read()
    return response

def get_json(identifier, namespace='cid', domain='compound', operation=None, searchtype=None, **kwargs):
    """Request wrapper that automatically parses JSON response and supresses NotFoundError."""
    try:
        return json.loads(get(identifier, namespace, domain, operation, 'JSON', searchtype, **kwargs).decode())
    except NotFoundError as e:
        log.info(e)
        return None

def get_sdf(identifier, namespace='cid', domain='compound', operation=None, searchtype=None, **kwargs):
    """Request wrapper that automatically parses SDF response and supresses NotFoundError."""
    try:
        return get(identifier, namespace, domain, operation, 'SDF', searchtype, **kwargs).decode()
    except NotFoundError as e:
        log.info(e)
        return None

def deprecated(message=None):
    """Decorator to mark functions as deprecated. A warning will be emitted when the function is used."""
    def deco(func):
        @functools.wraps(func)
        def wrapped(*args, **kwargs):
            warnings.warn(message or 'Call to deprecated function {}'.format(func.__name__), category=PubChemPyDeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapped
    return deco

def _parse_prop(search, proplist):
