def load_targets(explanatory_rasters):
    """Parameters
    ----------
    explanatory_rasters : List of Paths to GDAL rasters containing explanatory variables

    Returns
    -------
    expl : Array of explanatory variables
    raster_info : dict of raster info"""
    explanatory_raster_arrays = []
    aff = None
    shape = None
    crs = None
    for raster in explanatory_rasters:
        logger.debug(raster)
        with rasterio.open(raster) as src:
            ar = src.read(1)
            if not aff:
                aff = src.affine
            else:
                assert aff == src.affine
            if not shape:
                shape = ar.shape
            else:
                assert shape == ar.shape
            if not crs:
                crs = src.crs
            else:
                assert crs == src.crs
        arf = ar.flatten()
        explanatory_raster_arrays.append(arf)
    expl = np.array(explanatory_raster_arrays).T
    raster_info = {'affine': aff, 'shape': shape, 'crs': crs}
    return (expl, raster_info)

def get_func(func_name, module_pathname):
    """Get function from module
    :param func_name: function name
    :param module_pathname:  pathname to module
    :return:"""
    if sys.version_info[0] >= 3:
        if sys.version_info[1] >= 6:
            import importlib.util
            spec = importlib.util.spec_from_file_location('module_name', module_pathname)
            cells_module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(cells_module)
            return getattr(cells_module, func_name)
        elif sys.version_info[1] >= 4:
            import importlib.machinery
            module = importlib.machinery.SourceFileLoader('module_name', module_pathname).load_module()
            return getattr(module, func_name)
    fatal('Python version {} not supported'.format(sys.version))

def git_check():
    """Check that all changes , besides versioning files, are committed
    :return:"""
    output = local('git diff --name-only | egrep -v "^(pynb/version.py)|(version.py)$" | tr "\\n" " "', capture=True).strip()
    if output:
        fatal('Stage for commit and commit all changes first: {}'.format(output))
    output = local('git diff --cached --name-only | egrep -v "^(pynb/version.py)|(version.py)$" | tr "\\n" " "', capture=True).strip()
    if output:
        fatal('Commit all changes first: {}'.format(output))

