def to_dict(obj, **kwargs):
    """Convert an object into dictionary. Uses singledispatch to allow for
    clean extensions for custom class types.

    Reference: https://pypi.python.org/pypi/singledispatch

    :param obj: object instance
    :param kwargs: keyword arguments such as suppress_private_attr,
                   suppress_empty_values, dict_factory
    :return: converted dictionary."""
    if is_model(obj.__class__):
        return related_obj_to_dict(obj, **kwargs)
    else:
        return obj

def to_model(cls, value):
    """Coerce a value into a model object based on a class-type (cls).
    :param cls: class type to coerce into
    :param value: value to be coerced
    :return: original value or coerced value (value')"""
    if isinstance(value, cls) or value is None:
        pass
    elif issubclass(cls, Enum):
        value = cls(value)
    elif is_model(cls) and isinstance(value, dict):
        value = convert_key_to_attr_names(cls, value)
        value = cls(**value)
    else:
        value = cls(value)
    return value

def convert_key_to_attr_names(cls, original):
    """convert key names to their corresponding attribute names"""
    attrs = fields(cls)
    updated = {}
    keys_pulled = set()
    for a in attrs:
        key_name = a.metadata.get('key') or a.name
        if key_name in original:
            updated[a.name] = original.get(key_name)
            keys_pulled.add(key_name)
    if getattr(cls, '__related_strict__', False):
        extra = set(original.keys()) - keys_pulled
        if len(extra):
            raise ValueError('Extra keys (strict mode): {}'.format(extra))
    return updated

def from_yaml(stream, cls=None, loader_cls=yaml.Loader, object_pairs_hook=OrderedDict, **extras):
    """Convert a YAML stream into a class via the OrderedLoader class."""
    class OrderedLoader(loader_cls):
        pass
    def construct_mapping(loader, node):
        loader.flatten_mapping(node)
        return object_pairs_hook(loader.construct_pairs(node))
    OrderedLoader.add_constructor(yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG, construct_mapping)
    yaml_dict = yaml.load(stream, OrderedLoader) or {}
    yaml_dict.update(extras)
    return cls(**yaml_dict) if cls else yaml_dict

def run_clingo(draco_query: List[str], constants: Dict[str, str]=None, files: List[str]=None, relax_hard=False, silence_warnings=False, debug=False) -> Tuple[str, str]:
    """Run draco and return stderr and stdout"""
    files = files or DRACO_LP
    if relax_hard and 'hard-integrity.lp' in files:
        files.remove('hard-integrity.lp')
    constants = constants or {}
    options = ['--outf=2', '--quiet=1,2,2']
    if silence_warnings:
        options.append('--warn=no-atom-undefined')
    for name, value in constants.items():
        options.append(f'-c {name}={value}')
    cmd = ['clingo'] + options
    logger.debug('Command: %s', ' '.join(cmd))
    proc = subprocess.Popen(args=cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    program = '\n'.join(draco_query)
    file_names = [os.path.join(DRACO_LP_DIR, f) for f in files]
    asp_program = b'\n'.join(map(load_file, file_names)) + program.encode('utf8')
    if debug:
        with tempfile.NamedTemporaryFile(mode='w', delete=False) as fd:
            fd.write(program)
            logger.info('Debug ASP with "clingo %s %s"', ' '.join(file_names), fd.name)
    stdout, stderr = proc.communicate(asp_program)
    return (stderr, stdout)

def run(draco_query: List[str], constants: Dict[str, str]=None, files: List[str]=None, relax_hard=False, silence_warnings=False, debug=False, clear_cache=False) -> Optional[Result]:
    """Run clingo to compute a completion of a partial spec or violations."""
    if clear_cache and file_cache:
        logger.warning('Cleared file cache')
        file_cache.clear()
    stderr, stdout = run_clingo(draco_query, constants, files, relax_hard, silence_warnings, debug)
    try:
        json_result = json.loads(stdout)
    except json.JSONDecodeError:
        logger.error('stdout: %s', stdout)
        logger.error('stderr: %s', stderr)
        raise
    if stderr:
        logger.error(stderr)
    result = json_result['Result']
    if result == 'UNSATISFIABLE':
        logger.info('Constraints are unsatisfiable.')
        return None
    elif result == 'OPTIMUM FOUND':
        answers = json_result['Call'][0]['Witnesses'][-1]
        logger.debug(answers['Value'])
        return Result(clyngor.Answers(answers['Value']).sorted, cost=json_result['Models']['Costs'][0])
    elif result == 'SATISFIABLE':
        answers = json_result['Call'][0]['Witnesses'][-1]
        assert json_result['Models']['Number'] == 1, "Should not have more than one model if we don't optimize"
        logger.debug(answers['Value'])
        return Result(clyngor.Answers(answers['Value']).sorted)
    else:
        logger.error('Unsupported result: %s', result)
        return None

def _drop_degenerate_inners(shape):
    """Drop degenerate (zero-size) inners from the polygon.

    This is implemented as dropping anything with a size less than 0.5, as the
    polygon is in integer coordinates and the smallest valid inner would be a
    triangle with height and width 1."""
    assert shape.geom_type == 'Polygon'
    new_inners = []
    for inner in shape.interiors:
        if abs(Polygon(inner).area) >= 0.5:
            new_inners.append(inner)
    return Polygon(shape.exterior, new_inners)

def make_it_valid(shape):
    """Attempt to make any polygon or multipolygon valid."""
    if shape.is_empty:
        return shape
    elif shape.type == 'MultiPolygon':
        shape = make_valid_multipolygon(shape)
    elif shape.type == 'Polygon':
        shape = make_valid_polygon(shape)
    return shape

def optimise_tile(tile_bytes):
    """Decode a sequence of bytes as an MVT tile and reorder the string table of
    its layers and the order of its multilinestrings to save a few bytes."""
    t = tile()
    t.ParseFromString(tile_bytes)
    for layer in t.layers:
        sto = StringTableOptimiser()
        for feature in layer.features:
            if feature.type == 2:
                optimise_multilinestring(feature.geometry)
            sto.add_tags(feature.tags)
        sto.update_string_table(layer)
    return t.SerializeToString()

