                try:
                    nav = navigator.Navigator(anchore_config=config, imagelist=imagelist, allimages=contexts['anchore_allimages'])
                except Exception as err:
                    nav = None
                    raise err
    except Exception as err:
        anchore_print_err('operation failed')
        ecode = 1
    if ecode:
        sys.exit(ecode)

