def get_version_relationship(ver_str1, ver_str2):
    """Comparison of alpine package version numbers. Roughly based on the C code from github.com/apk-tools/version.c but in pure python.

    :param ver_str1:
    :param ver_str2:
    :return:"""
    v1_type = TokenType.DIGIT
    v2_type = TokenType.DIGIT
    v1_tok = 0
    v2_tok = 0
    if ver_str1 is None and ver_str2 is None:
        return ComparisonResult.equal_to
    if ver_str1 is None and ver_str2 is not None:
        return ComparisonResult.less_than
    if ver_str1 is not None and ver_str2 is None:
        return ComparisonResult.greater_than
    while v1_type == v2_type and v1_type != TokenType.END and (v1_type != TokenType.INVALID) and (v1_tok == v2_tok):
        v1_tok, v1_type, ver_str1 = get_token(v1_type, ver_str1)
        v2_tok, v2_type, ver_str2 = get_token(v2_type, ver_str2)
    if v1_tok < v2_tok:
        return ComparisonResult.less_than
    if v1_tok > v2_tok:
        return ComparisonResult.greater_than
    if v1_type == v2_type:
        return ComparisonResult.equal_to
    if v1_type == TokenType.SUFFIX and get_token(v1_type, ver_str1)[0] < 0:
        return ComparisonResult.less_than
    if v2_type == TokenType.SUFFIX and get_token(v2_type, ver_str2)[0] < 0:
        return ComparisonResult.greater_than
    if v1_type > v2_type:
        return ComparisonResult.less_than
    if v2_type > v1_type:
        return ComparisonResult.greater_than
    return ComparisonResult.equal_to

def load_and_merge(file_path=None, defaults=None):
    """Load a given file and apply defaults as specified to any values not present in the file.
    Does a merge of the file and defaults and returns a dict with the results
    :param file_path: file to load. Supports .yaml and .json files
    :param defaults: dict with defaults in correct structure to compare and overlay with the values from the file
    :return: a new dict with the merged results"""
    ret = None
    if defaults is not None:
        ret = defaults.copy()
    file_data = None
    if file_path is not None:
        with open(file_path) as f:
            if file_path.endswith('.yaml') or file_path.endswith('.yml'):
                file_data = yaml.safe_load(f)
            elif file_path.endswith('.json'):
                file_data = json.load(f.read())
    else:
        file_data = {}
    if file_data is not None:
        if ret is not None:
            ret.update(file_data)
            return ret
        else:
            return file_data
    else:
        return ret

def show(feed):
    """Show detailed feed information"""
    ecode = 0
    try:
        feedmeta = anchore_feeds.load_anchore_feedmeta()
        if feed in feedmeta:
            result = {}
            groups = feedmeta[feed].get('groups', {}).values()
            result['name'] = feed
            result['access_tier'] = int(feedmeta[feed].get('access_tier'))
            result['description'] = feedmeta[feed].get('description')
            result['groups'] = {}
            if 'subscribed' not in feedmeta[feed]:
                result['subscribed'] = False
            else:
                result['subscribed'] = feedmeta[feed]['subscribed']
            for g in groups:
                result['groups'][g['name']] = {'access_tier': int(g.get('access_tier')), 'description': g.get('description'), 'last_sync': datetime.datetime.fromtimestamp(g.get('last_update')).isoformat() if 'last_update' in g else 'None'}
            anchore_print(result, do_formatting=True)
        else:
            anchore_print_err('Unknown feed name. Valid feeds can be seen withe the "list" command')
            ecode = 1
    except Exception as err:
        anchore_print_err('operation failed')
        ecode = 1
    sys.exit(ecode)

def sub(feednames):
    """Subscribe to the specified feed(s)."""
    ecode = 0
    current_user_data = contexts.get('anchore_auth', {}).get('user_info', None)
    if not current_user_data:
        current_user_tier = 0
    else:
        current_user_tier = int(current_user_data['tier'])
    try:
        for feed in feednames:
            rc, msg = anchore_feeds.subscribe_anchore_feed(feed, current_user_tier)
            if not rc:
                ecode = 1
                anchore_print_err(msg)
            else:
                anchore_print(msg)
    except Exception as err:
        anchore_print_err('operation failed')
        ecode = 1
    sys.exit(ecode)

def unsub(feednames, delete, dontask):
    """Unsubscribe from the specified feed(s)."""
    ecode = 0
    try:
        for feed in feednames:
            rc, msg = anchore_feeds.unsubscribe_anchore_feed(feed)
            if not rc:
                ecode = 1
                anchore_print_err(msg)
            else:
                anchore_print(msg)
                if delete:
                    dodelete = False
                    if dontask:
                        dodelete = True
                    else:
                        try:
                            answer = raw_input('Really delete feed data (' + str(feed) + "'? (y/N)")
                        except:
                            answer = 'n'
                        if 'y' == answer.lower():
                            dodelete = True
                        else:
                            anchore_print(str(feed) + ': skipping delete.')
                    if dodelete:
                        anchore_print(str(feed) + ': deleting feed.')
                        rc = anchore_feeds.delete_anchore_feed(feed)
    except Exception as err:
        anchore_print_err('operation failed')
        ecode = 1
    sys.exit(ecode)

