def _surpress_formatting_errors(fn):
    """I know this is dangerous and the wrong way to solve the problem, but when
    using both row and columns summaries it's easier to just swallow errors
    so users can format their tables how they need."""
    @wraps(fn)
    def inner(*args, **kwargs):
        try:
            return fn(*args, **kwargs)
        except ValueError:
            return ''
    return inner

def _format_numer(number_format, prefix='', suffix=''):
    """Format a number to a string."""
    @_surpress_formatting_errors
    def inner(v):
        if isinstance(v, Number):
            return '{{}}{{:{}}}{{}}'.format(number_format).format(prefix, v, suffix)
        else:
            raise TypeError('Numberic type required.')
    return inner

def as_percent(precision=2, **kwargs):
    """Convert number to percentage string.

    Parameters:
    -----------
    :param v: numerical value to be converted
    :param precision: int
        decimal places to round to"""
    if not isinstance(precision, Integral):
        raise TypeError('Precision must be an integer.')
    return _surpress_formatting_errors(_format_numer('.{}%'.format(precision)))

def as_unit(unit, precision=2, location='suffix'):
    """Convert value to unit.

    Parameters:
    -----------
    :param v: numerical value
    :param unit: string of unit
    :param precision: int
        decimal places to round to
    :param location:
        'prefix' or 'suffix' representing where the currency symbol falls
        relative to the value"""
    if not isinstance(precision, Integral):
        raise TypeError('Precision must be an integer.')
    if location == 'prefix':
        formatter = partial(_format_numer, prefix=unit)
    elif location == 'suffix':
        formatter = partial(_format_numer, suffix=unit)
    else:
        raise ValueError("location must be either 'prefix' or 'suffix'.")
    return _surpress_formatting_errors(formatter('0.{}f'.format(precision)))

def unique_files(event_list):
    """Find the unique files

    Parameters
    ----------
    event_list : list or dcase_util.containers.MetaDataContainer
        A list containing event dicts

    Returns
    -------
    list
        Unique filenames in alphabetical order"""
    if isinstance(event_list, dcase_util.containers.MetaDataContainer):
        return event_list.unique_files
    else:
        files = {}
        for event in event_list:
            if 'file' in event:
                files[event['file']] = event['file']
            elif 'filename' in event:
                files[event['filename']] = event['filename']
        files = list(files.keys())
        files.sort()
        return files

def max_event_offset(event_list):
    """Find the offset (end-time) of last event

    Parameters
    ----------
    event_list : list or dcase_util.containers.MetaDataContainer
        A list containing event dicts

    Returns
    -------
    float > 0
        maximum offset"""
    if isinstance(event_list, dcase_util.containers.MetaDataContainer):
        return event_list.max_offset
    else:
        max_offset = 0
        for event in event_list:
            if 'event_offset' in event:
                if event['event_offset'] > max_offset:
                    max_offset = event['event_offset']
            elif 'offset' in event:
                if event['offset'] > max_offset:
                    max_offset = event['offset']
        return max_offset

def make_varname(tree):
    """<left> tree </left>"""
    if tree.tag == 'identifier':
        return tree.attrib['name']
    if tree.tag in ('string', 'boolean'):
        return tree.text
    if tree.tag == 'number':
        return tree.attrib['value']
    if tree.tag in ('property', 'object'):
        return make_varname(_xpath_one(tree, '*'))
    if tree.tag.endswith('accessor'):
        kind = tree.tag[:-len('accessor')]
        obj = make_varname(_xpath_one(tree, 'object'))
        prop = make_varname(_xpath_one(tree, 'property'))
        if kind == 'dot':
            fmt = '%s.%s'
        elif kind == 'bracket':
            fmt = '%s[%s]'
        else:
            raise ValueError('Unknown accessor: %s' % tree.tag)
        return fmt % (obj, prop)
    raise ValueError('Unknown tag: %s' % tree.tag)

def _users_from_environ(env_prefix=''):
    """Environment value via `user:password|user2:password2`"""
    auth_string = os.environ.get(env_prefix + 'WSGI_AUTH_CREDENTIALS')
    if not auth_string:
        return {}
    result = {}
    for credentials in auth_string.split('|'):
        username, password = credentials.split(':', 1)
        result[username] = password
    return result

def _exclude_paths_from_environ(env_prefix=''):
    """Environment value via `/login;/register`"""
    paths = os.environ.get(env_prefix + 'WSGI_AUTH_EXCLUDE_PATHS')
    if not paths:
        return []
    return paths.split(';')

def _include_paths_from_environ(env_prefix=''):
    """Environment value via `/login;/register`"""
    paths = os.environ.get(env_prefix + 'WSGI_AUTH_PATHS')
    if not paths:
        return []
    return paths.split(';')

