def delta_e_cie1976(lab_color_vector, lab_color_matrix):
    """Calculates the Delta E (CIE1976) between `lab_color_vector` and all
    colors in `lab_color_matrix`."""
    return numpy.sqrt(numpy.sum(numpy.power(lab_color_vector - lab_color_matrix, 2), axis=1))

def _get_lab_color1_vector(color):
    """Converts an LabColor into a NumPy vector.

    :param LabColor color:
    :rtype: numpy.ndarray"""
    if not color.__class__.__name__ == 'LabColor':
        raise ValueError('Delta E functions can only be used with two LabColor objects.')
    return numpy.array([color.lab_l, color.lab_a, color.lab_b])

def delta_e_cie1976(color1, color2):
    """Calculates the Delta E (CIE1976) of two colors."""
    color1_vector = _get_lab_color1_vector(color1)
    color2_matrix = _get_lab_color2_matrix(color2)
    delta_e = color_diff_matrix.delta_e_cie1976(color1_vector, color2_matrix)[0]
    return numpy.asscalar(delta_e)

def delta_e_cie2000(color1, color2, Kl=1, Kc=1, Kh=1):
    """Calculates the Delta E (CIE2000) of two colors."""
    color1_vector = _get_lab_color1_vector(color1)
    color2_matrix = _get_lab_color2_matrix(color2)
    delta_e = color_diff_matrix.delta_e_cie2000(color1_vector, color2_matrix, Kl=Kl, Kc=Kc, Kh=Kh)[0]
    return numpy.asscalar(delta_e)

def Lab_to_LCHab(cobj, *args, **kwargs):
    """Convert from CIE Lab to LCH(ab)."""
    lch_l = cobj.lab_l
    lch_c = math.sqrt(math.pow(float(cobj.lab_a), 2) + math.pow(float(cobj.lab_b), 2))
    lch_h = math.atan2(float(cobj.lab_b), float(cobj.lab_a))
    if lch_h > 0:
        lch_h = lch_h / math.pi * 180
    else:
        lch_h = 360 - math.fabs(lch_h) / math.pi * 180
    return LCHabColor(lch_l, lch_c, lch_h, observer=cobj.observer, illuminant=cobj.illuminant)

def Lab_to_XYZ(cobj, *args, **kwargs):
    """Convert from Lab to XYZ"""
    illum = cobj.get_illuminant_xyz()
    xyz_y = (cobj.lab_l + 16.0) / 116.0
    xyz_x = cobj.lab_a / 500.0 + xyz_y
    xyz_z = xyz_y - cobj.lab_b / 200.0
    if math.pow(xyz_y, 3) > color_constants.CIE_E:
        xyz_y = math.pow(xyz_y, 3)
    else:
        xyz_y = (xyz_y - 16.0 / 116.0) / 7.787
    if math.pow(xyz_x, 3) > color_constants.CIE_E:
        xyz_x = math.pow(xyz_x, 3)
    else:
        xyz_x = (xyz_x - 16.0 / 116.0) / 7.787
    if math.pow(xyz_z, 3) > color_constants.CIE_E:
        xyz_z = math.pow(xyz_z, 3)
    else:
        xyz_z = (xyz_z - 16.0 / 116.0) / 7.787
    xyz_x = illum['X'] * xyz_x
    xyz_y = illum['Y'] * xyz_y
    xyz_z = illum['Z'] * xyz_z
    return XYZColor(xyz_x, xyz_y, xyz_z, observer=cobj.observer, illuminant=cobj.illuminant)

def Luv_to_LCHuv(cobj, *args, **kwargs):
    """Convert from CIE Luv to LCH(uv)."""
    lch_l = cobj.luv_l
    lch_c = math.sqrt(math.pow(cobj.luv_u, 2.0) + math.pow(cobj.luv_v, 2.0))
    lch_h = math.atan2(float(cobj.luv_v), float(cobj.luv_u))
    if lch_h > 0:
        lch_h = lch_h / math.pi * 180
    else:
        lch_h = 360 - math.fabs(lch_h) / math.pi * 180
    return LCHuvColor(lch_l, lch_c, lch_h, observer=cobj.observer, illuminant=cobj.illuminant)

def Luv_to_XYZ(cobj, *args, **kwargs):
    """Convert from Luv to XYZ."""
    illum = cobj.get_illuminant_xyz()
    if cobj.luv_l <= 0.0:
        xyz_x = 0.0
        xyz_y = 0.0
        xyz_z = 0.0
        return XYZColor(xyz_x, xyz_y, xyz_z, observer=cobj.observer, illuminant=cobj.illuminant)
    cie_k_times_e = color_constants.CIE_K * color_constants.CIE_E
    u_sub_0 = 4.0 * illum['X'] / (illum['X'] + 15.0 * illum['Y'] + 3.0 * illum['Z'])
    v_sub_0 = 9.0 * illum['Y'] / (illum['X'] + 15.0 * illum['Y'] + 3.0 * illum['Z'])
    var_u = cobj.luv_u / (13.0 * cobj.luv_l) + u_sub_0
    var_v = cobj.luv_v / (13.0 * cobj.luv_l) + v_sub_0
    if cobj.luv_l > cie_k_times_e:
        xyz_y = math.pow((cobj.luv_l + 16.0) / 116.0, 3.0)
    else:
        xyz_y = cobj.luv_l / color_constants.CIE_K
    xyz_x = xyz_y * 9.0 * var_u / (4.0 * var_v)
    xyz_z = xyz_y * (12.0 - 3.0 * var_u - 20.0 * var_v) / (4.0 * var_v)
    return XYZColor(xyz_x, xyz_y, xyz_z, illuminant=cobj.illuminant, observer=cobj.observer)

def LCHab_to_Lab(cobj, *args, **kwargs):
    """Convert from LCH(ab) to Lab."""
    lab_l = cobj.lch_l
    lab_a = math.cos(math.radians(cobj.lch_h)) * cobj.lch_c
    lab_b = math.sin(math.radians(cobj.lch_h)) * cobj.lch_c
    return LabColor(lab_l, lab_a, lab_b, illuminant=cobj.illuminant, observer=cobj.observer)

def LCHuv_to_Luv(cobj, *args, **kwargs):
    """Convert from LCH(uv) to Luv."""
    luv_l = cobj.lch_l
    luv_u = math.cos(math.radians(cobj.lch_h)) * cobj.lch_c
    luv_v = math.sin(math.radians(cobj.lch_h)) * cobj.lch_c
    return LuvColor(luv_l, luv_u, luv_v, illuminant=cobj.illuminant, observer=cobj.observer)

def XYZ_to_xyY(cobj, *args, **kwargs):
    """Convert from XYZ to xyY."""
    xyz_sum = cobj.xyz_x + cobj.xyz_y + cobj.xyz_z
    if xyz_sum == 0.0:
        xyy_x = 0.0
        xyy_y = 0.0
    else:
        xyy_x = cobj.xyz_x / xyz_sum
        xyy_y = cobj.xyz_y / xyz_sum
    xyy_Y = cobj.xyz_y
    return xyYColor(xyy_x, xyy_y, xyy_Y, observer=cobj.observer, illuminant=cobj.illuminant)

def XYZ_to_Lab(cobj, *args, **kwargs):
    """Converts XYZ to Lab."""
    illum = cobj.get_illuminant_xyz()
    temp_x = cobj.xyz_x / illum['X']
    temp_y = cobj.xyz_y / illum['Y']
    temp_z = cobj.xyz_z / illum['Z']
    if temp_x > color_constants.CIE_E:
        temp_x = math.pow(temp_x, 1.0 / 3.0)
    else:
        temp_x = 7.787 * temp_x + 16.0 / 116.0
    if temp_y > color_constants.CIE_E:
        temp_y = math.pow(temp_y, 1.0 / 3.0)
    else:
        temp_y = 7.787 * temp_y + 16.0 / 116.0
    if temp_z > color_constants.CIE_E:
        temp_z = math.pow(temp_z, 1.0 / 3.0)
    else:
        temp_z = 7.787 * temp_z + 16.0 / 116.0
    lab_l = 116.0 * temp_y - 16.0
    lab_a = 500.0 * (temp_x - temp_y)
    lab_b = 200.0 * (temp_y - temp_z)
    return LabColor(lab_l, lab_a, lab_b, observer=cobj.observer, illuminant=cobj.illuminant)

def __RGB_to_Hue(var_R, var_G, var_B, var_min, var_max):
    """For RGB_to_HSL and RGB_to_HSV, the Hue (H) component is calculated in
    the same way."""
    if var_max == var_min:
        return 0.0
    elif var_max == var_R:
        return (60.0 * ((var_G - var_B) / (var_max - var_min)) + 360) % 360.0
    elif var_max == var_G:
        return 60.0 * ((var_B - var_R) / (var_max - var_min)) + 120
    elif var_max == var_B:
        return 60.0 * ((var_R - var_G) / (var_max - var_min)) + 240.0

def __Calc_HSL_to_RGB_Components(var_q, var_p, C):
    """This is used in HSL_to_RGB conversions on R, G, and B."""
    if C < 0:
        C += 1.0
    if C > 1:
        C -= 1.0
    if C < 1.0 / 6.0:
        return var_p + (var_q - var_p) * 6.0 * C
    elif 1.0 / 6.0 <= C < 0.5:
        return var_q
    elif 0.5 <= C < 2.0 / 3.0:
        return var_p + (var_q - var_p) * 6.0 * (2.0 / 3.0 - C)
    else:
        return var_p

def CMY_to_CMYK(cobj, *args, **kwargs):
    """Converts from CMY to CMYK.

    NOTE: CMYK and CMY values range from 0.0 to 1.0"""
    var_k = 1.0
    if cobj.cmy_c < var_k:
        var_k = cobj.cmy_c
    if cobj.cmy_m < var_k:
        var_k = cobj.cmy_m
    if cobj.cmy_y < var_k:
        var_k = cobj.cmy_y
    if var_k == 1:
        cmyk_c = 0.0
        cmyk_m = 0.0
        cmyk_y = 0.0
    else:
        cmyk_c = (cobj.cmy_c - var_k) / (1.0 - var_k)
        cmyk_m = (cobj.cmy_m - var_k) / (1.0 - var_k)
        cmyk_y = (cobj.cmy_y - var_k) / (1.0 - var_k)
    cmyk_k = var_k
    return CMYKColor(cmyk_c, cmyk_m, cmyk_y, cmyk_k)

def compile(script, vars={}, library_paths=[]):
    """Compile a jq script, retuning a script object.

    library_paths is a list of strings that defines the module search path."""
    return _pyjq.Script(script.encode('utf-8'), vars=vars, library_paths=library_paths)

def apply(script, value=None, vars={}, url=None, opener=default_opener, library_paths=[]):
    """Transform value by script, returning all results as list."""
    return all(script, value, vars, url, opener, library_paths)

def one(script, value=None, vars={}, url=None, opener=default_opener, library_paths=[]):
    """Transform object by jq script, returning the first result.
    Raise ValueError unless results does not include exactly one element."""
    return compile(script, vars, library_paths).one(_get_value(value, url, opener))

def unpublish_object(content_type_pk, obj_pk):
    """Unbuild all views related to a object and then sync to S3.

    Accepts primary keys to retrieve a model object that
    inherits bakery's BuildableModel class."""
    ct = ContentType.objects.get_for_id(content_type_pk)
    obj = ct.get_object_for_this_type(pk=obj_pk)
    try:
        logger.info('unpublish_object task has received %s' % obj)
        obj.unbuild()
        if not getattr(settings, 'ALLOW_BAKERY_AUTO_PUBLISHING', True):
            logger.info('Not running publish command because ALLOW_BAKERY_AUTO_PUBLISHING is False')
        else:
            management.call_command('publish')
    except Exception:
        logger.error('Task Error: unpublish_object', exc_info=True)

def get_s3_client():
    """A DRY place to make sure AWS credentials in settings override
    environment based credentials.  Boto3 will fall back to:
    http://boto3.readthedocs.io/en/latest/guide/configuration.html"""
    session_kwargs = {}
    if hasattr(settings, 'AWS_ACCESS_KEY_ID'):
        session_kwargs['aws_access_key_id'] = settings.AWS_ACCESS_KEY_ID
    if hasattr(settings, 'AWS_SECRET_ACCESS_KEY'):
        session_kwargs['aws_secret_access_key'] = settings.AWS_SECRET_ACCESS_KEY
    boto3.setup_default_session(**session_kwargs)
    s3_kwargs = {}
    if hasattr(settings, 'AWS_S3_ENDPOINT'):
        s3_kwargs['endpoint_url'] = settings.AWS_S3_ENDPOINT
    elif hasattr(settings, 'AWS_S3_HOST'):
        if hasattr(settings, 'AWS_S3_USE_SSL') and settings.AWS_S3_USE_SSL is False:
            protocol = 'http://'
        else:
            protocol = 'https://'
        s3_kwargs['endpoint_url'] = '{}{}'.format(protocol, settings.AWS_S3_HOST)
    if hasattr(settings, 'AWS_REGION'):
        s3_kwargs['region_name'] = settings.AWS_REGION
    s3_client = boto3.client('s3', **s3_kwargs)
    s3_resource = boto3.resource('s3', **s3_kwargs)
    return (s3_client, s3_resource)

def get_bucket_page(page):
    """Returns all the keys in a s3 bucket paginator page."""
    key_list = page.get('Contents', [])
    logger.debug('Retrieving page with {} keys'.format(len(key_list)))
    return dict(((k.get('Key'), k) for k in key_list))

def get_all_objects_in_bucket(aws_bucket_name, s3_client=None, max_keys=1000):
    """Little utility method that handles pagination and returns
    all objects in given bucket."""
    logger.debug('Retrieving bucket object list')
    if not s3_client:
        s3_client, s3_resource = get_s3_client()
    obj_dict = {}
    paginator = s3_client.get_paginator('list_objects')
    page_iterator = paginator.paginate(Bucket=aws_bucket_name)
    for page in page_iterator:
        key_list = page.get('Contents', [])
        logger.debug('Loading page with {} keys'.format(len(key_list)))
        for obj in key_list:
            obj_dict[obj.get('Key')] = obj
    return obj_dict

def batch_delete_s3_objects(keys, aws_bucket_name, chunk_size=100, s3_client=None):
    """Utility method that batch deletes objects in given bucket."""
    if s3_client is None:
        s3_client, s3_resource = get_s3_client()
    key_chunks = []
    for i in range(0, len(keys), chunk_size):
        chunk = []
        for key in list(keys)[i:i + 100]:
            chunk.append({'Key': key})
        key_chunks.append(chunk)
    for chunk in key_chunks:
        s3_client.delete_objects(Bucket=aws_bucket_name, Delete={'Objects': chunk})

def lexeme(p):
    """From a parser (or string), make a parser that consumes
    whitespace on either side."""
    if isinstance(p, str):
        p = string(p)
    return regex('\\s*') >> p << regex('\\s*')

def is_present(p):
    """Given a parser or string, make a parser that returns
    True if the parser matches, False otherwise"""
    return lexeme(p).optional().map(lambda v: False if v is None else True)

def extract_key_values(array_value, separators=(';', ',', ':'), **kwargs):
    """Serialize array of objects with simple key-values
    """
    items_sep, fields_sep, keys_sep = separators
    return items_sep.join((fields_sep.join((keys_sep.join(x) for x in sorted(it.items()))) for it in array_value))

def get_current_user():
    """Return the current username for the logged in user

    :rtype: str"""
    if pwd is None:
        return getpass.getuser()
    else:
        try:
            return pwd.getpwuid(os.getuid())[0]
        except KeyError as error:
            LOGGER.error('Could not get logged-in user: %s', error)

def uri(host='localhost', port=5432, dbname='postgres', user='postgres', password=None):
    """Return a PostgreSQL connection URI for the specified values.

    :param str host: Host to connect to
    :param int port: Port to connect on
    :param str dbname: The database name
    :param str user: User to connect as
    :param str password: The password to use, None for no password
    :return str: The PostgreSQL connection URI

    """
    if port:
        host = '%s:%s' % (host, port)
    if password:
        return 'postgresql://%s:%s@%s/%s' % (user, password, host, dbname)
    return 'postgresql://%s@%s/%s' % (user, host, dbname)

def uri_to_kwargs(uri):
    """Return a URI as kwargs for connecting to PostgreSQL with psycopg2,
    applying default values for non-specified areas of the URI.

    :param str uri: The connection URI
    :rtype: dict"""
    parsed = urlparse(uri)
    default_user = get_current_user()
    password = unquote(parsed.password) if parsed.password else None
    kwargs = {'host': parsed.hostname, 'port': parsed.port, 'dbname': parsed.path[1:] or default_user, 'user': parsed.username or default_user, 'password': password}
    values = parse_qs(parsed.query)
    if 'host' in values:
        kwargs['host'] = values['host'][0]
    for k in [k for k in values if k in KEYWORDS]:
        kwargs[k] = values[k][0] if len(values[k]) == 1 else values[k]
        try:
            if kwargs[k].isdigit():
                kwargs[k] = int(kwargs[k])
        except AttributeError:
            pass
    return kwargs

def validate_args(opts):
    """Validate and return options provided by docopt parsing."""
    if opts['--wide'] is None:
        opts['--wide'] = 2
    else:
        assert opts['--wide'] in ('1', '2'), opts['--wide']
    if opts['--alignment'] is None:
        opts['--alignment'] = 'left'
    else:
        assert opts['--alignment'] in ('left', 'right'), opts['--alignment']
    opts['--wide'] = int(opts['--wide'])
    opts['character_factory'] = WcWideCharacterGenerator
    if opts['--combining']:
        opts['character_factory'] = WcCombinedCharacterGenerator
    return opts

def ensure_permissions(mode_flags=stat.S_IWUSR):
    """decorator to ensure a filename has given permissions.

    If changed, original permissions are restored after the decorated
    modification."""
    def decorator(f):
        def modify(filename, *args, **kwargs):
            m = chmod_perms(filename) if exists(filename) else mode_flags
            if not m & mode_flags:
                os.chmod(filename, m | mode_flags)
            try:
                return f(filename, *args, **kwargs)
            finally:
                if not m & mode_flags:
                    os.chmod(filename, m)
        return modify
    return decorator

def get_rpaths(filename):
    """Return a tuple of rpaths from the library `filename`

    If `filename` is not a library then the returned tuple will be empty.

    Parameters
    ----------
    filaname : str
        filename of library

    Returns
    -------
    rpath : tuple
        rpath paths in `filename`"""
    try:
        lines = _cmd_out_err(['otool', '-l', filename])
    except RuntimeError:
        return ()
    if not _line0_says_object(lines[0], filename):
        return ()
    lines = [line.strip() for line in lines]
    paths = []
    line_no = 1
    while line_no < len(lines):
        line = lines[line_no]
        line_no += 1
        if line != 'cmd LC_RPATH':
            continue
        cmdsize, path = lines[line_no:line_no + 2]
        assert cmdsize.startswith('cmdsize ')
        paths.append(RPATH_RE.match(path).groups()[0])
        line_no += 2
    return tuple(paths)

def get_archs(libname):
    """Return architecture types from library `libname`

    Parameters
    ----------
    libname : str
        filename of binary for which to return arch codes

    Returns
    -------
    arch_names : frozenset
        Empty (frozen)set if no arch codes.  If not empty, contains one or more
        of 'ppc', 'ppc64', 'i386', 'x86_64'"""
    if not exists(libname):
        raise RuntimeError(libname + ' is not a file')
    try:
        stdout = back_tick(['lipo', '-info', libname])
    except RuntimeError:
        return frozenset()
    lines = [line.strip() for line in stdout.split('\n') if line.strip()]
    if lines[0] == 'input file {0} is not a fat file'.format(libname):
        line = lines[1]
    else:
        assert len(lines) == 1
        line = lines[0]
    for reggie in ('Non-fat file: {0} is architecture: (.*)'.format(libname), 'Architectures in the fat file: {0} are: (.*)'.format(libname)):
        reggie = re.compile(reggie)
        match = reggie.match(line)
        if not match is None:
            return frozenset(match.groups()[0].split(' '))
    raise ValueError("Unexpected output: '{0}' for {1}".format(stdout, libname))

def os_path_relpath(path, start=os.path.curdir):
    """Return a relative version of a path"""
    if not path:
        raise ValueError('no path specified')
    start_list = [x for x in os.path.abspath(start).split(os.path.sep) if x]
    path_list = [x for x in os.path.abspath(path).split(os.path.sep) if x]
    i = len(os.path.commonprefix([start_list, path_list]))
    rel_list = [os.path.pardir] * (len(start_list) - i) + path_list[i:]
    if not rel_list:
        return os.path.curdir
    return os.path.join(*rel_list)

def _merge_lib_dict(d1, d2):
    """Merges lib_dict `d2` into lib_dict `d1`
    """
    for required, requirings in d2.items():
        if required in d1:
            d1[required].update(requirings)
        else:
            d1[required] = requirings
    return None

def _open_for_csv(name, mode):
    """Deal with Python 2/3 open API differences"""
    if sys.version_info[0] < 3:
        return open_rw(name, mode + 'b')
    return open_rw(name, mode, newline='', encoding='utf-8')

def check_pianoroll(arr):
    """Return True if the array is a standard piano-roll matrix. Otherwise,
    return False. Raise TypeError if the input object is not a numpy array."""
    if not isinstance(arr, np.ndarray):
        raise TypeError('`arr` must be of np.ndarray type')
    if not (np.issubdtype(arr.dtype, np.bool_) or np.issubdtype(arr.dtype, np.number)):
        return False
    if arr.ndim != 2:
        return False
    if arr.shape[1] != 128:
        return False
    return True

def parse(filepath, beat_resolution=24, name='unknown'):
    """Return a :class:`pypianoroll.Multitrack` object loaded from a MIDI
    (.mid, .midi, .MID, .MIDI) file.

    Parameters
    ----------
    filepath : str
        The file path to the MIDI file."""
    if not filepath.endswith(('.mid', '.midi', '.MID', '.MIDI')):
        raise ValueError('Only MIDI files are supported')
    return Multitrack(filepath, beat_resolution=beat_resolution, name=name)

def _validate_pianoroll(pianoroll):
    """Raise an error if the input array is not a standard pianoroll."""
    if not isinstance(pianoroll, np.ndarray):
        raise TypeError('`pianoroll` must be of np.ndarray type.')
    if not (np.issubdtype(pianoroll.dtype, np.bool_) or np.issubdtype(pianoroll.dtype, np.number)):
        raise TypeError('The data type of `pianoroll` must be np.bool_ or a subdtype of  np.number.')
    if pianoroll.ndim != 2:
        raise ValueError('`pianoroll` must have exactly two dimensions.')
    if pianoroll.shape[1] != 128:
        raise ValueError('The length of the second axis of `pianoroll` must be 128.')

def _to_chroma(pianoroll):
    """Return the unnormalized chroma features of a pianoroll."""
    _validate_pianoroll(pianoroll)
    reshaped = pianoroll[:, :120].reshape(-1, 12, 10)
    reshaped[..., :8] += pianoroll[:, 120:].reshape(-1, 1, 8)
    return np.sum(reshaped, 1)

def n_pitche_classes_used(pianoroll):
    """Return the number of unique pitch classes used in a pianoroll."""
    _validate_pianoroll(pianoroll)
    chroma = _to_chroma(pianoroll)
    return np.count_nonzero(np.any(chroma, 0))

def drum_in_pattern_rate(pianoroll, beat_resolution, tolerance=0.1):
    """Return the ratio of the number of drum notes that lie on the drum
    pattern (i.e., at certain time steps) to the total number of drum notes."""
    if beat_resolution not in (4, 6, 8, 9, 12, 16, 18, 24):
        raise ValueError('Unsupported beat resolution. Only 4, 6, 8 ,9, 12, 16, 18, 42 are supported.')
    _validate_pianoroll(pianoroll)
    def _drum_pattern_mask(res, tol):
        """Return a drum pattern mask with the given tolerance."""
        if res == 24:
            drum_pattern_mask = np.tile([1.0, tol, 0.0, 0.0, 0.0, tol], 4)
        elif res == 12:
            drum_pattern_mask = np.tile([1.0, tol, tol], 4)
        elif res == 6:
            drum_pattern_mask = np.tile([1.0, tol, tol], 2)
        elif res == 18:
            drum_pattern_mask = np.tile([1.0, tol, 0.0, 0.0, 0.0, tol], 3)
        elif res == 9:
            drum_pattern_mask = np.tile([1.0, tol, tol], 3)
        elif res == 16:
            drum_pattern_mask = np.tile([1.0, tol, 0.0, tol], 4)
        elif res == 8:
            drum_pattern_mask = np.tile([1.0, tol], 4)
        elif res == 4:
            drum_pattern_mask = np.tile([1.0, tol], 2)
        return drum_pattern_mask
    drum_pattern_mask = _drum_pattern_mask(beat_resolution, tolerance)
    n_in_pattern = np.sum(drum_pattern_mask * np.count_nonzero(pianoroll, 1))
    return n_in_pattern / np.count_nonzero(pianoroll)

def in_scale_rate(pianoroll, key=3, kind='major'):
    """Return the ratio of the number of nonzero entries that lie in a specific
    scale to the total number of nonzero entries in a pianoroll. Default to C
    major scale."""
    if not isinstance(key, int):
        raise TypeError('`key` must an integer.')
    if key > 11 or key < 0:
        raise ValueError('`key` must be in an integer in between 0 and 11.')
    if kind not in ('major', 'minor'):
        raise ValueError("`kind` must be one of 'major' or 'minor'.")
    _validate_pianoroll(pianoroll)
    def _scale_mask(key, kind):
        """Return a scale mask for the given key. Default to C major scale."""
        if kind == 'major':
            a_scale_mask = np.array([0, 1, 1, 0, 1, 0, 1, 0, 1, 1, 0, 1], bool)
        else:
            a_scale_mask = np.array([1, 0, 1, 0, 1, 1, 0, 1, 0, 1, 0, 1], bool)
        return np.roll(a_scale_mask, key)
    chroma = _to_chroma(pianoroll)
    scale_mask = _scale_mask(key, kind)
    n_in_scale = np.sum(scale_mask.reshape(-1, 12) * chroma)
    return n_in_scale / np.count_nonzero(pianoroll)

def rpc_call(payload):
    """Simple Flask implementation for making asynchronous Rpc calls."""
    corr_id = RPC_CLIENT.send_request(payload)
    while RPC_CLIENT.queue[corr_id] is None:
        sleep(0.1)
    return RPC_CLIENT.queue[corr_id]

def get_default_ssl_version():
    """Get the highest support TLS version, if none is available, return None.

    :rtype: bool|None"""
    if hasattr(ssl, 'PROTOCOL_TLSv1_2'):
        return ssl.PROTOCOL_TLSv1_2
    elif hasattr(ssl, 'PROTOCOL_TLSv1_1'):
        return ssl.PROTOCOL_TLSv1_1
    elif hasattr(ssl, 'PROTOCOL_TLSv1'):
        return ssl.PROTOCOL_TLSv1
    return None

def is_string(obj):
    """Is this a string.

    :param object obj:
    :rtype: bool"""
    if PYTHON3:
        str_type = (bytes, str)
    else:
        str_type = (bytes, str, unicode)
    return isinstance(obj, str_type)

def is_integer(obj):
    """Is this an integer.

    :param object obj:
    :return:"""
    if PYTHON3:
        return isinstance(obj, int)
    return isinstance(obj, (int, long))

def try_utf8_decode(value):
    """Try to decode an object.

    :param value:
    :return:"""
    if not value or not is_string(value):
        return value
    elif PYTHON3 and (not isinstance(value, bytes)):
        return value
    elif not PYTHON3 and (not isinstance(value, unicode)):
        return value
    try:
        return value.decode('utf-8')
    except UnicodeDecodeError:
        pass
    return value

def _prep_fields_param(fields):
    """Prepare the `fields` parameter, and determine whether or not to store samples."""
    store_samples = False
    if fields is None:
        return (True, None)
    if isinstance(fields, str):
        fields = [fields]
    else:
        fields = list(fields)
    if 'samples' in fields:
        fields.remove('samples')
        store_samples = True
    elif '*' in fields:
        store_samples = True
    return (store_samples, fields)

def store(data, arr, start=0, stop=None, offset=0, blen=None):
    """Copy `data` block-wise into `arr`."""
    blen = _util.get_blen_array(data, blen)
    if stop is None:
        stop = len(data)
    else:
        stop = min(stop, len(data))
    length = stop - start
    if length < 0:
        raise ValueError('invalid stop/start')
    for bi in range(start, stop, blen):
        bj = min(bi + blen, stop)
        bl = bj - bi
        arr[offset:offset + bl] = data[bi:bj]
        offset += bl

def copy(data, start=0, stop=None, blen=None, storage=None, create='array', **kwargs):
    """Copy `data` block-wise into a new array."""
    storage = _util.get_storage(storage)
    blen = _util.get_blen_array(data, blen)
    if stop is None:
        stop = len(data)
    else:
        stop = min(stop, len(data))
    length = stop - start
    if length < 0:
        raise ValueError('invalid stop/start')
    out = None
    for i in range(start, stop, blen):
        j = min(i + blen, stop)
        block = data[i:j]
        if out is None:
            out = getattr(storage, create)(block, expectedlen=length, **kwargs)
        else:
            out.append(block)
    return out

def copy_table(tbl, start=0, stop=None, blen=None, storage=None, create='table', **kwargs):
    """Copy `tbl` block-wise into a new table."""
    names, columns = _util.check_table_like(tbl)
    storage = _util.get_storage(storage)
    blen = _util.get_blen_table(tbl, blen)
    if stop is None:
        stop = len(columns[0])
    else:
        stop = min(stop, len(columns[0]))
    length = stop - start
    if length < 0:
        raise ValueError('invalid stop/start')
    out = None
    for i in range(start, stop, blen):
        j = min(i + blen, stop)
        res = [c[i:j] for c in columns]
        if out is None:
            out = getattr(storage, create)(res, names=names, expectedlen=length, **kwargs)
        else:
            out.append(res)
    return out

def map_blocks(data, f, blen=None, storage=None, create='array', **kwargs):
    """Apply function `f` block-wise over `data`."""
    storage = _util.get_storage(storage)
    if isinstance(data, tuple):
        blen = max((_util.get_blen_array(d, blen) for d in data))
    else:
        blen = _util.get_blen_array(data, blen)
    if isinstance(data, tuple):
        _util.check_equal_length(*data)
        length = len(data[0])
    else:
        length = len(data)
    out = None
    for i in range(0, length, blen):
        j = min(i + blen, length)
        if isinstance(data, tuple):
            blocks = [d[i:j] for d in data]
        else:
            blocks = [data[i:j]]
        res = f(*blocks)
        if out is None:
            out = getattr(storage, create)(res, expectedlen=length, **kwargs)
        else:
            out.append(res)
    return out

def amax(data, axis=None, mapper=None, blen=None, storage=None, create='array', **kwargs):
    """Compute the maximum value."""
    return reduce_axis(data, axis=axis, reducer=np.amax, block_reducer=np.maximum, mapper=mapper, blen=blen, storage=storage, create=create, **kwargs)

def amin(data, axis=None, mapper=None, blen=None, storage=None, create='array', **kwargs):
    """Compute the minimum value."""
    return reduce_axis(data, axis=axis, reducer=np.amin, block_reducer=np.minimum, mapper=mapper, blen=blen, storage=storage, create=create, **kwargs)

def asum(data, axis=None, mapper=None, blen=None, storage=None, create='array', **kwargs):
    """Compute the sum."""
    return reduce_axis(data, axis=axis, reducer=np.sum, block_reducer=np.add, mapper=mapper, blen=blen, storage=storage, create=create, **kwargs)

def count_nonzero(data, mapper=None, blen=None, storage=None, create='array', **kwargs):
    """Count the number of non-zero elements."""
    return reduce_axis(data, reducer=np.count_nonzero, block_reducer=np.add, mapper=mapper, blen=blen, storage=storage, create=create, **kwargs)

def compress(condition, data, axis=0, out=None, blen=None, storage=None, create='array', **kwargs):
    """Return selected slices of an array along given axis."""
    if out is not None:
        raise NotImplementedError('out argument is not supported')
    storage = _util.get_storage(storage)
    blen = _util.get_blen_array(data, blen)
    length = len(data)
    nnz = count_nonzero(condition)
    if axis == 0:
        _util.check_equal_length(data, condition)
        out = None
        for i in range(0, length, blen):
            j = min(i + blen, length)
            bcond = np.asarray(condition[i:j])
            if np.any(bcond):
                block = np.asarray(data[i:j])
                res = np.compress(bcond, block, axis=0)
                if out is None:
                    out = getattr(storage, create)(res, expectedlen=nnz, **kwargs)
                else:
                    out.append(res)
        return out
    elif axis == 1:
        out = None
        condition = np.asanyarray(condition)
        for i in range(0, length, blen):
            j = min(i + blen, length)
            block = np.asarray(data[i:j])
            res = np.compress(condition, block, axis=1)
            if out is None:
                out = getattr(storage, create)(res, expectedlen=length, **kwargs)
            else:
                out.append(res)
        return out
    else:
        raise NotImplementedError('axis not supported: %s' % axis)

def take(data, indices, axis=0, out=None, mode='raise', blen=None, storage=None, create='array', **kwargs):
    """Take elements from an array along an axis."""
    if out is not None:
        raise NotImplementedError('out argument is not supported')
    length = len(data)
    if axis == 0:
        indices = np.asanyarray(indices)
        if np.any(indices[1:] <= indices[:-1]):
            raise NotImplementedError('indices must be strictly increasing')
        condition = np.zeros((length,), dtype=bool)
        condition[indices] = True
        return compress(condition, data, axis=0, blen=blen, storage=storage, create=create, **kwargs)
    elif axis == 1:
        storage = _util.get_storage(storage)
        blen = _util.get_blen_array(data, blen)
        out = None
        for i in range(0, length, blen):
            j = min(i + blen, length)
            block = data[i:j]
            res = np.take(block, indices, axis=1, mode=mode)
            if out is None:
                out = getattr(storage, create)(res, expectedlen=length, **kwargs)
            else:
                out.append(res)
        return out
    else:
        raise NotImplementedError('axis not supported: %s' % axis)

def take_table(tbl, indices, axis=None, out=None, mode='raise', blen=None, storage=None, create='table', **kwargs):
    """Return selected rows of a table."""
    if axis is not None and axis != 0:
        raise NotImplementedError('only axis 0 is supported')
    if out is not None:
        raise NotImplementedError('out argument is not supported')
    if mode is not None and mode != 'raise':
        raise NotImplementedError('only mode=raise is supported')
    names, columns = _util.check_table_like(tbl)
    length = len(columns[0])
    indices = np.asanyarray(indices)
    if np.any(indices[1:] <= indices[:-1]):
        raise NotImplementedError('indices must be strictly increasing')
    condition = np.zeros((length,), dtype=bool)
    condition[indices] = True
    return compress_table(condition, tbl, blen=blen, storage=storage, create=create, **kwargs)

def concatenate_table(tup, blen=None, storage=None, create='table', **kwargs):
    """Stack tables in sequence vertically (row-wise)."""
    storage = _util.get_storage(storage)
    if not isinstance(tup, (tuple, list)):
        raise ValueError('expected tuple or list, found %r' % tup)
    if len(tup) < 2:
        raise ValueError('expected two or more tables to stack')
    expectedlen = sum((len(t) for t in tup))
    out = None
    tnames = None
    for tdata in tup:
        tblen = _util.get_blen_table(tdata, blen)
        tnames, tcolumns = _util.check_table_like(tdata, names=tnames)
        tlen = len(tcolumns[0])
        for i in range(0, tlen, tblen):
            j = min(i + tblen, tlen)
            bcolumns = [c[i:j] for c in tcolumns]
            if out is None:
                out = getattr(storage, create)(bcolumns, names=tnames, expectedlen=expectedlen, **kwargs)
            else:
                out.append(bcolumns)
    return out

def binary_op(data, op, other, blen=None, storage=None, create='array', **kwargs):
    """Compute a binary operation block-wise over `data`."""
    if hasattr(other, 'shape') and len(other.shape) == 0:
        other = other[()]
    if np.isscalar(other):
        def f(block):
            return op(block, other)
        return map_blocks(data, f, blen=blen, storage=storage, create=create, **kwargs)
    elif len(data) == len(other):
        def f(a, b):
            return op(a, b)
        return map_blocks((data, other), f, blen=blen, storage=storage, create=create, **kwargs)
    else:
        raise NotImplementedError('argument type not supported')

def eval_table(tbl, expression, vm='python', blen=None, storage=None, create='array', vm_kwargs=None, **kwargs):
    """Evaluate `expression` against columns of a table."""
    storage = _util.get_storage(storage)
    names, columns = _util.check_table_like(tbl)
    length = len(columns[0])
    if vm_kwargs is None:
        vm_kwargs = dict()
    if vm == 'numexpr':
        import numexpr
        evaluate = numexpr.evaluate
    elif vm == 'python':
        def evaluate(expr, local_dict=None, **kw):
            return eval(expr, dict(), local_dict)
    else:
        raise ValueError('expected vm either "numexpr" or "python"')
    variables = _get_expression_variables(expression, vm)
    required_columns = {v: columns[names.index(v)] for v in variables}
    blen = _util.get_blen_table(required_columns, blen=blen)
    out = None
    for i in range(0, length, blen):
        j = min(i + blen, length)
        blocals = {v: c[i:j] for v, c in required_columns.items()}
        res = evaluate(expression, local_dict=blocals, **vm_kwargs)
        if out is None:
            out = getattr(storage, create)(res, expectedlen=length, **kwargs)
        else:
            out.append(res)
    return out

def get_chunks(data, chunks=None):
    """Try to guess a reasonable chunk shape to use for block-wise
    algorithms operating over `data`."""
    if chunks is None:
        if hasattr(data, 'chunklen') and hasattr(data, 'shape'):
            return (data.chunklen,) + data.shape[1:]
        elif hasattr(data, 'chunks') and hasattr(data, 'shape') and (len(data.chunks) == len(data.shape)):
            return data.chunks
        else:
            row = np.asarray(data[0])
            chunklen = max(1, 2 ** 22 // row.nbytes)
            if row.shape:
                chunks = (chunklen,) + row.shape
            else:
                chunks = (chunklen,)
            return chunks
    else:
        return chunks

def index_windows(values, size, start, stop, step):
    """Convenience function to construct windows for the
    :func:`moving_statistic` function."""
    if stop is None:
        stop = len(values)
    if step is None:
        step = size
    for window_start in range(start, stop, step):
        window_stop = window_start + size
        if window_stop > stop:
            return
        yield (window_start, window_stop)

def position_windows(pos, size, start, stop, step):
    """Convenience function to construct windows for the
    :func:`windowed_statistic` and :func:`windowed_count` functions."""
    last = False
    if start is None:
        start = pos[0]
    if stop is None:
        stop = pos[-1]
    if step is None:
        step = size
    windows = []
    for window_start in range(start, stop, step):
        window_stop = window_start + size
        if window_stop >= stop:
            window_stop = stop
            last = True
        else:
            window_stop -= 1
        windows.append([window_start, window_stop])
        if last:
            break
    return np.asarray(windows)

def attachment_form(context, obj):
    """Renders a "upload attachment" form.

    The user must own ``attachments.add_attachment permission`` to add
    attachments."""
    if context['user'].has_perm('attachments.add_attachment'):
        return {'form': AttachmentForm(), 'form_url': add_url_for_obj(obj), 'next': context.request.build_absolute_uri()}
    else:
        return {'form': None}

def attachment_delete_link(context, attachment):
    """Renders a html link to the delete view of the given attachment. Returns
    no content if the request-user has no permission to delete attachments.

    The user must own either the ``attachments.delete_attachment`` permission
    and is the creator of the attachment, that he can delete it or he has
    ``attachments.delete_foreign_attachments`` which allows him to delete all
    attachments."""
    if context['user'].has_perm('attachments.delete_foreign_attachments') or (context['user'] == attachment.creator and context['user'].has_perm('attachments.delete_attachment')):
        return {'next': context.request.build_absolute_uri(), 'delete_url': reverse('attachments:delete', kwargs={'attachment_pk': attachment.pk})}
    return {'delete_url': None}

def attachment_upload(instance, filename):
    """Stores the attachment in a "per module/appname/primary key" folder"""
    return 'attachments/{app}_{model}/{pk}/{filename}'.format(app=instance.content_object._meta.app_label, model=instance.content_object._meta.object_name.lower(), pk=instance.content_object.pk, filename=filename)

def routes_register(app, handler, *paths, methods=None, router=None, name=None):
    """Register routes."""
    if router is None:
        router = app.router
    handler = to_coroutine(handler)
    resources = []
    for path in paths:
        if isinstance(path, type) and issubclass(path, BaseException):
            app._error_handlers[path] = handler
            continue
        name = str(name or '')
        rname, rnum = (name, 2)
        while rname in router:
            rname = '%s%d' % (name, rnum)
            rnum += 1
        path = parse(path)
        if isinstance(path, RETYPE):
            resource = RawReResource(path, name=rname)
            router.register_resource(resource)
        else:
            resource = router.add_resource(path, name=rname)
        for method in methods or [METH_ANY]:
            method = method.upper()
            resource.add_route(method, handler)
        resources.append(resource)
    return resources

def parse(path):
    """Parse URL path and convert it to regexp if needed."""
    parsed = re.sre_parse.parse(path)
    for case, _ in parsed:
        if case not in (re.sre_parse.LITERAL, re.sre_parse.ANY):
            break
    else:
        return path
    path = path.strip('^$')
    def parse_(match):
        [part] = match.groups()
        match = DYNR_RE.match(part)
        params = match.groupdict()
        return '(?P<%s>%s)' % (params['var'], params['re'] or '[^{}/]+')
    return re.compile('^%s$' % DYNS_RE.sub(parse_, path))

def create_signature(secret, value, digestmod='sha256', encoding='utf-8'):
    """Create HMAC Signature from secret for value."""
    if isinstance(secret, str):
        secret = secret.encode(encoding)
    if isinstance(value, str):
        value = value.encode(encoding)
    if isinstance(digestmod, str):
        digestmod = getattr(hashlib, digestmod, hashlib.sha1)
    hm = hmac.new(secret, digestmod=digestmod)
    hm.update(value)
    return hm.hexdigest()

def check_signature(signature, *args, **kwargs):
    """Check for the signature is correct."""
    return hmac.compare_digest(signature, create_signature(*args, **kwargs))

def generate_password_hash(password, digestmod='sha256', salt_length=8):
    """Hash a password with given method and salt length."""
    salt = ''.join(random.sample(SALT_CHARS, salt_length))
    signature = create_signature(salt, password, digestmod=digestmod)
    return '$'.join((digestmod, salt, signature))

def import_submodules(package_name, *submodules):
    """Import all submodules by package name."""
    package = sys.modules[package_name]
    return {name: importlib.import_module(package_name + '.' + name) for _, name, _ in pkgutil.walk_packages(package.__path__) if not submodules or name in submodules}

def register(*paths, methods=None, name=None, handler=None):
    '''Mark Handler.method to aiohttp handler.

    It uses when registration of the handler with application is postponed.

    ::
        class AwesomeHandler(Handler):

            def get(self, request):
                return "I'm awesome!"

            @register('/awesome/best')
            def best(self, request):
                return "I'm best!"'''
    def wrapper(method):
        """Store route params into method."""
        method = to_coroutine(method)
        setattr(method, ROUTE_PARAMS_ATTR, (paths, methods, name))
        if handler and (not hasattr(handler, method.__name__)):
            setattr(handler, method.__name__, method)
        return method
    return wrapper

def _exc_middleware_factory(app):
    """Handle exceptions.

    Route exceptions to handlers if they are registered in application."""
    @web.middleware
    async def middleware(request, handler):
        try:
            return await handler(request)
        except Exception as exc:
            for cls in type(exc).mro():
                if cls in app._error_handlers:
                    request.exception = exc
                    response = await app._error_handlers[cls](request)
                    return response
            raise
    return middleware

def verify_honeypot_value(request, field_name):
    """Verify that request.POST[field_name] is a valid honeypot.

    Ensures that the field exists and passes verification according to
    HONEYPOT_VERIFIER."""
    verifier = getattr(settings, 'HONEYPOT_VERIFIER', honeypot_equals)
    if request.method == 'POST':
        field = field_name or settings.HONEYPOT_FIELD_NAME
        if field not in request.POST or not verifier(request.POST[field]):
            resp = render_to_string('honeypot/honeypot_error.html', {'fieldname': field})
            return HttpResponseBadRequest(resp)

def check_honeypot(func=None, field_name=None):
    """Check request.POST for valid honeypot field.

    Takes an optional field_name that defaults to HONEYPOT_FIELD_NAME if
    not specified."""
    if isinstance(func, six.string_types):
        func, field_name = (field_name, func)
    def decorated(func):
        def inner(request, *args, **kwargs):
            response = verify_honeypot_value(request, field_name)
            if response:
                return response
            else:
                return func(request, *args, **kwargs)
        return wraps(func, assigned=available_attrs(func))(inner)
    if func is None:
        def decorator(func):
            return decorated(func)
        return decorator
    return decorated(func)

def honeypot_exempt(view_func):
    """Mark view as exempt from honeypot validation"""
    def wrapped(*args, **kwargs):
        return view_func(*args, **kwargs)
    wrapped.honeypot_exempt = True
    return wraps(view_func, assigned=available_attrs(view_func))(wrapped)

def render_honeypot_field(field_name=None):
    """Renders honeypot field named field_name (defaults to HONEYPOT_FIELD_NAME)."""
    if not field_name:
        field_name = settings.HONEYPOT_FIELD_NAME
    value = getattr(settings, 'HONEYPOT_VALUE', '')
    if callable(value):
        value = value()
    return {'fieldname': field_name, 'value': value}

