def autodiscover(module_name=None):
    """Autodiscover INSTALLED_APPS perms.py modules and fail silently when not
    present. This forces an import on them to register any permissions bits
    they may want."""
    from django.utils.module_loading import module_has_submodule
    from permission.compat import import_module
    from permission.conf import settings
    module_name = module_name or settings.PERMISSION_AUTODISCOVER_MODULE_NAME
    app_names = (app.name for app in apps.app_configs.values())
    for app in app_names:
        mod = import_module(app)
        try:
            discover(app, module_name=module_name)
        except:
            if module_has_submodule(mod, module_name):
                raise

def redirect_to_login(request, login_url=None, redirect_field_name=REDIRECT_FIELD_NAME):
    """redirect to login"""
    path = request.build_absolute_uri()
    login_scheme, login_netloc = urlparse(login_url or settings.LOGIN_URL)[:2]
    current_scheme, current_netloc = urlparse(path)[:2]
    if (not login_scheme or login_scheme == current_scheme) and (not login_netloc or login_netloc == current_netloc):
        path = request.get_full_path()
    from django.contrib.auth.views import redirect_to_login as auth_redirect_to_login
    return auth_redirect_to_login(path, login_url, redirect_field_name)

def of_operator(context, x, y):
    """'of' operator of permission if

    This operator is used to specify the target object of permission"""
    return (x.eval(context), y.eval(context))

def has_operator(context, x, y):
    """'has' operator of permission if

    This operator is used to specify the user object of permission"""
    user = x.eval(context)
    perm = y.eval(context)
    if isinstance(perm, (list, tuple)):
        perm, obj = perm
    else:
        obj = None
    return user.has_perm(perm, obj)

def get_body_from_message(message, maintype, subtype):
    """Fetchs the body message matching main/sub content type."""
    body = six.text_type('')
    for part in message.walk():
        if part.get('content-disposition', '').startswith('attachment;'):
            continue
        if part.get_content_maintype() == maintype and part.get_content_subtype() == subtype:
            charset = part.get_content_charset()
            this_part = part.get_payload(decode=True)
            if charset:
                try:
                    this_part = this_part.decode(charset, 'replace')
                except LookupError:
                    this_part = this_part.decode('ascii', 'replace')
                    logger.warning('Unknown encoding %s encountered while decoding text payload.  Interpreting as ASCII with replacement, but some data may not be represented as the sender intended.', charset)
                except ValueError:
                    this_part = this_part.decode('ascii', 'replace')
                    logger.warning('Error encountered while decoding text payload from an incorrectly-constructed e-mail; payload was converted to ASCII with replacement, but some data may not be represented as the sender intended.')
            else:
                this_part = this_part.decode('ascii', 'replace')
            body += this_part
    return body

def diam_circle(AreaCircle):
    """Return the diameter of a circle."""
    ut.check_range([AreaCircle, '>0', 'AreaCircle'])
    return np.sqrt(4 * AreaCircle / np.pi)

def re_pipe(FlowRate, Diam, Nu):
    """Return the Reynolds Number for a pipe."""
    ut.check_range([FlowRate, '>0', 'Flow rate'], [Diam, '>0', 'Diameter'], [Nu, '>0', 'Nu'])
    return 4 * FlowRate / (np.pi * Diam * Nu)

def radius_hydraulic(Width, DistCenter, openchannel):
    """Return the hydraulic radius.

    Width and DistCenter are length values and openchannel is a boolean."""
    ut.check_range([Width, '>0', 'Width'], [DistCenter, '>0', 'DistCenter'], [openchannel, 'boolean', 'openchannel'])
    if openchannel:
        return Width * DistCenter / (Width + 2 * DistCenter)
    else:
        return Width * DistCenter / (2 * (Width + DistCenter))

def re_rect(FlowRate, Width, DistCenter, Nu, openchannel):
    """Return the Reynolds Number for a rectangular channel."""
    ut.check_range([FlowRate, '>0', 'Flow rate'], [Nu, '>0', 'Nu'])
    return 4 * FlowRate * radius_hydraulic(Width, DistCenter, openchannel).magnitude / (Width * DistCenter * Nu)

def fric(FlowRate, Diam, Nu, PipeRough):
    """Return the friction factor for pipe flow.

    This equation applies to both laminar and turbulent flows."""
    ut.check_range([PipeRough, '0-1', 'Pipe roughness'])
    if re_pipe(FlowRate, Diam, Nu) >= RE_TRANSITION_PIPE:
        f = 0.25 / np.log10(PipeRough / (3.7 * Diam) + 5.74 / re_pipe(FlowRate, Diam, Nu) ** 0.9) ** 2
    else:
        f = 64 / re_pipe(FlowRate, Diam, Nu)
    return f

def fric_rect(FlowRate, Width, DistCenter, Nu, PipeRough, openchannel):
    """Return the friction factor for a rectangular channel."""
    ut.check_range([PipeRough, '0-1', 'Pipe roughness'])
    if re_rect(FlowRate, Width, DistCenter, Nu, openchannel) >= RE_TRANSITION_PIPE:
        return 0.25 / np.log10(PipeRough / (3.7 * 4 * radius_hydraulic(Width, DistCenter, openchannel).magnitude) + 5.74 / re_rect(FlowRate, Width, DistCenter, Nu, openchannel) ** 0.9) ** 2
    else:
        return 64 / re_rect(FlowRate, Width, DistCenter, Nu, openchannel)

def fric_general(Area, PerimWetted, Vel, Nu, PipeRough):
    """Return the friction factor for a general channel."""
    ut.check_range([PipeRough, '0-1', 'Pipe roughness'])
    if re_general(Vel, Area, PerimWetted, Nu) >= RE_TRANSITION_PIPE:
        f = 0.25 / np.log10(PipeRough / (3.7 * 4 * radius_hydraulic_general(Area, PerimWetted).magnitude) + 5.74 / re_general(Vel, Area, PerimWetted, Nu) ** 0.9) ** 2
    else:
        f = 64 / re_general(Vel, Area, PerimWetted, Nu)
    return f

def headloss_fric_rect(FlowRate, Width, DistCenter, Length, Nu, PipeRough, openchannel):
    """Return the major head loss due to wall shear in a rectangular channel.

    This equation applies to both laminar and turbulent flows."""
    ut.check_range([Length, '>0', 'Length'])
    return fric_rect(FlowRate, Width, DistCenter, Nu, PipeRough, openchannel) * Length / (4 * radius_hydraulic(Width, DistCenter, openchannel).magnitude) * FlowRate ** 2 / (2 * gravity.magnitude * (Width * DistCenter) ** 2)

def headloss_exp_rect(FlowRate, Width, DistCenter, KMinor):
    """Return the minor head loss due to expansion in a rectangular channel.

    This equation applies to both laminar and turbulent flows."""
    ut.check_range([FlowRate, '>0', 'Flow rate'], [Width, '>0', 'Width'], [DistCenter, '>0', 'DistCenter'], [KMinor, '>=0', 'K minor'])
    return KMinor * FlowRate ** 2 / (2 * gravity.magnitude * (Width * DistCenter) ** 2)

def headloss_fric_general(Area, PerimWetted, Vel, Length, Nu, PipeRough):
    """Return the major head loss due to wall shear in the general case.

    This equation applies to both laminar and turbulent flows."""
    ut.check_range([Length, '>0', 'Length'])
    return fric_general(Area, PerimWetted, Vel, Nu, PipeRough) * Length / (4 * radius_hydraulic_general(Area, PerimWetted).magnitude) * Vel ** 2 / (2 * gravity.magnitude)

def headloss_exp_general(Vel, KMinor):
    """Return the minor head loss due to expansion in the general case.

    This equation applies to both laminar and turbulent flows."""
    ut.check_range([Vel, '>0', 'Velocity'], [KMinor, '>=0', 'K minor'])
    return KMinor * Vel ** 2 / (2 * gravity.magnitude)

def headloss_manifold(FlowRate, Diam, Length, KMinor, Nu, PipeRough, NumOutlets):
    """Return the total head loss through the manifold."""
    ut.check_range([NumOutlets, '>0, int', 'Number of outlets'])
    return headloss(FlowRate, Diam, Length, Nu, PipeRough, KMinor).magnitude * (1 / 3 + 1 / (2 * NumOutlets) + 1 / (6 * NumOutlets ** 2))

def flow_orifice(Diam, Height, RatioVCOrifice):
    """Return the flow rate of the orifice."""
    ut.check_range([Diam, '>0', 'Diameter'], [RatioVCOrifice, '0-1', 'VC orifice ratio'])
    if Height > 0:
        return RatioVCOrifice * area_circle(Diam).magnitude * np.sqrt(2 * gravity.magnitude * Height)
    else:
        return 0

def flow_orifice_vert(Diam, Height, RatioVCOrifice):
    """Return the vertical flow rate of the orifice."""
    ut.check_range([RatioVCOrifice, '0-1', 'VC orifice ratio'])
    if Height > -Diam / 2:
        flow_vert = integrate.quad(lambda z: Diam * np.sin(np.arccos(z / (Diam / 2))) * np.sqrt(Height - z), -Diam / 2, min(Diam / 2, Height))
        return flow_vert[0] * RatioVCOrifice * np.sqrt(2 * gravity.magnitude)
    else:
        return 0

def head_orifice(Diam, RatioVCOrifice, FlowRate):
    """Return the head of the orifice."""
    ut.check_range([Diam, '>0', 'Diameter'], [FlowRate, '>0', 'Flow rate'], [RatioVCOrifice, '0-1', 'VC orifice ratio'])
    return (FlowRate / (RatioVCOrifice * area_circle(Diam).magnitude)) ** 2 / (2 * gravity.magnitude)

def area_orifice(Height, RatioVCOrifice, FlowRate):
    """Return the area of the orifice."""
    ut.check_range([Height, '>0', 'Height'], [FlowRate, '>0', 'Flow rate'], [RatioVCOrifice, '0-1, >0', 'VC orifice ratio'])
    return FlowRate / (RatioVCOrifice * np.sqrt(2 * gravity.magnitude * Height))

def num_orifices(FlowPlant, RatioVCOrifice, HeadLossOrifice, DiamOrifice):
    """Return the number of orifices."""
    return np.ceil(area_orifice(HeadLossOrifice, RatioVCOrifice, FlowPlant).magnitude / area_circle(DiamOrifice).magnitude)

def flow_swamee(Diam, HeadLossFric, Length, Nu, PipeRough):
    """Return the flow rate for turbulent flow with only major losses."""
    ut.check_range([Diam, '>0', 'Diameter'], [Length, '>0', 'Length'], [HeadLossFric, '>0', 'Headloss due to friction'], [Nu, '>0', 'Nu'], [PipeRough, '0-1', 'Pipe roughness'])
    logterm = np.log10(PipeRough / (3.7 * Diam) + 2.51 * Nu * np.sqrt(Length / (2 * gravity.magnitude * HeadLossFric * Diam ** 3)))
    return -np.pi / np.sqrt(2) * Diam ** (5 / 2) * logterm * np.sqrt(gravity.magnitude * HeadLossFric / Length)

def flow_pipemajor(Diam, HeadLossFric, Length, Nu, PipeRough):
    """Return the flow rate with only major losses.

    This function applies to both laminar and turbulent flows."""
    FlowHagen = flow_hagen(Diam, HeadLossFric, Length, Nu).magnitude
    if FlowHagen < flow_transition(Diam, Nu).magnitude:
        return FlowHagen
    else:
        return flow_swamee(Diam, HeadLossFric, Length, Nu, PipeRough).magnitude

def flow_pipeminor(Diam, HeadLossExpans, KMinor):
    """Return the flow rate with only minor losses.

    This function applies to both laminar and turbulent flows."""
    ut.check_range([HeadLossExpans, '>=0', 'Headloss due to expansion'], [KMinor, '>0', 'K minor'])
    return area_circle(Diam).magnitude * np.sqrt(2 * gravity.magnitude * HeadLossExpans / KMinor)

def flow_pipe(Diam, HeadLoss, Length, Nu, PipeRough, KMinor):
    """Return the the flow in a straight pipe.

    This function works for both major and minor losses and
    works whether the flow is laminar or turbulent."""
    if KMinor == 0:
        FlowRate = flow_pipemajor(Diam, HeadLoss, Length, Nu, PipeRough).magnitude
    else:
        FlowRatePrev = 0
        err = 1.0
        FlowRate = min(flow_pipemajor(Diam, HeadLoss, Length, Nu, PipeRough).magnitude, flow_pipeminor(Diam, HeadLoss, KMinor).magnitude)
        while err > 0.01:
            FlowRatePrev = FlowRate
            HLFricNew = HeadLoss * headloss_fric(FlowRate, Diam, Length, Nu, PipeRough).magnitude / (headloss_fric(FlowRate, Diam, Length, Nu, PipeRough).magnitude + headloss_exp(FlowRate, Diam, KMinor).magnitude)
            FlowRate = flow_pipemajor(Diam, HLFricNew, Length, Nu, PipeRough).magnitude
            if FlowRate == 0:
                err = 0.0
            else:
                err = abs(FlowRate - FlowRatePrev) / ((FlowRate + FlowRatePrev) / 2)
    return FlowRate

def diam_pipemajor(FlowRate, HeadLossFric, Length, Nu, PipeRough):
    """Return the pipe IDiam that would result in given major losses.
    This function applies to both laminar and turbulent flow."""
    DiamLaminar = diam_hagen(FlowRate, HeadLossFric, Length, Nu).magnitude
    if re_pipe(FlowRate, DiamLaminar, Nu) <= RE_TRANSITION_PIPE:
        return DiamLaminar
    else:
        return diam_swamee(FlowRate, HeadLossFric, Length, Nu, PipeRough).magnitude

def diam_pipeminor(FlowRate, HeadLossExpans, KMinor):
    """Return the pipe ID that would result in the given minor losses.

    This function applies to both laminar and turbulent flow."""
    ut.check_range([FlowRate, '>0', 'Flow rate'], [KMinor, '>=0', 'K minor'], [HeadLossExpans, '>0', 'Headloss due to expansion'])
    return np.sqrt(4 * FlowRate / np.pi) * (KMinor / (2 * gravity.magnitude * HeadLossExpans)) ** (1 / 4)

def width_rect_weir(FlowRate, Height):
    """Return the width of a rectangular weir."""
    ut.check_range([FlowRate, '>0', 'Flow rate'], [Height, '>0', 'Height'])
    return 3 / 2 * FlowRate / (con.VC_ORIFICE_RATIO * np.sqrt(2 * gravity.magnitude) * Height ** (3 / 2))

def headloss_weir(FlowRate, Width):
    """Return the headloss of a weir."""
    ut.check_range([FlowRate, '>0', 'Flow rate'], [Width, '>0', 'Width'])
    return (3 / 2 * FlowRate / (con.VC_ORIFICE_RATIO * np.sqrt(2 * gravity.magnitude) * Width)) ** (2 / 3)

def height_water_critical(FlowRate, Width):
    """Return the critical local water depth."""
    ut.check_range([FlowRate, '>0', 'Flow rate'], [Width, '>0', 'Width'])
    return (FlowRate / (Width * np.sqrt(gravity.magnitude))) ** (2 / 3)

def vel_horizontal(HeightWaterCritical):
    """Return the horizontal velocity."""
    ut.check_range([HeightWaterCritical, '>0', 'Critical height of water'])
    return np.sqrt(gravity.magnitude * HeightWaterCritical)

def k_value_orifice(pipe_id, orifice_id, orifice_l, q, nu=con.WATER_NU):
    """Calculates the minor loss coefficient of an orifice plate in a
    pipe.

    Parameters:
        pipe_id: Entrance pipe's inner diameter from which fluid flows.
        orifice_id: Orifice's inner diameter.
        orifice_l: Orifice's length from start to end.
        q: Fluid's q rate.

        nu: Fluid's dynamic viscosity of the fluid. Default: room
            temperature water (1 * 10**-6 * m**2/s)

    Returns:
        k-value at the orifice."""
    if orifice_id > pipe_id:
        raise ValueError("The orifice's inner diameter cannot be larger thanthat of the entrance pipe.")
    re = pc.re_pipe(q, pipe_id, nu)
    orifice_type = _get_orifice_type(orifice_l, orifice_id)
    if orifice_type == 'thin':
        return _k_value_thin_sharp_orifice(pipe_id, orifice_id, re)
    elif orifice_type == 'thick':
        return _k_value_thick_orifice(pipe_id, orifice_id, orifice_l, re)
    elif orifice_type == 'oversize':
        return k_value_reduction(pipe_id, orifice_id, q) + k_value_expansion(orifice_id, pipe_id, q)

def _k_value_square_reduction(ent_pipe_id, exit_pipe_id, re, f):
    """Returns the minor loss coefficient for a square reducer.

    Parameters:
        ent_pipe_id: Entrance pipe's inner diameter.
        exit_pipe_id: Exit pipe's inner diameter.
        re: Reynold's number.
        f: Darcy friction factor."""
    if re < 2500:
        return (1.2 + 160 / re) * (ent_pipe_id / exit_pipe_id) ** 4
    else:
        return (0.6 + 0.48 * f) * (ent_pipe_id / exit_pipe_id) ** 2 * ((ent_pipe_id / exit_pipe_id) ** 2 - 1)

def _k_value_tapered_reduction(ent_pipe_id, exit_pipe_id, fitting_angle, re, f):
    """Returns the minor loss coefficient for a tapered reducer.

    Parameters:
        ent_pipe_id: Entrance pipe's inner diameter.
        exit_pipe_id: Exit pipe's inner diameter.
        fitting_angle: Fitting angle between entrance and exit pipes.
        re: Reynold's number.
        f: Darcy friction factor."""
    k_value_square_reduction = _k_value_square_reduction(ent_pipe_id, exit_pipe_id, re, f)
    if 45 < fitting_angle <= 180:
        return k_value_square_reduction * np.sqrt(np.sin(fitting_angle / 2))
    elif 0 < fitting_angle <= 45:
        return k_value_square_reduction * 1.6 * np.sin(fitting_angle / 2)
    else:
        raise ValueError('k_value_tapered_reduction: The reducer angle (' + fitting_angle + ') cannot be outside of [0,180].')

def ND_all_available():
    """Return an array of available nominal diameters.

    NDs available are those commonly used as based on the 'Used' column
    in the pipedb."""
    ND_all_available = []
    for i in range(len(pipedb['NDinch'])):
        if pipedb.iloc[i, 4] == 1:
            ND_all_available.append(pipedb['NDinch'][i])
    return ND_all_available * u.inch

def ND_SDR_available(ID, SDR):
    """Return an available ND given an ID and a schedule.

    Takes the values of the array, compares to the ID, and finds the index
    of the first value greater or equal."""
    for i in range(len(np.array(ID_SDR_all_available(SDR)))):
        if np.array(ID_SDR_all_available(SDR))[i] >= ID.to(u.inch).magnitude:
            return ND_all_available()[i]

def get_drill_bits_d_metric():
    """Return array of possible drill diameters in metric."""
    return np.concatenate((np.arange(1.0, 10.0, 0.1), np.arange(10.0, 18.0, 0.5), np.arange(18.0, 36.0, 1.0), np.arange(40.0, 55.0, 5.0))) * u.mm

def viscosity_kinematic_chem(conc_chem, temp, en_chem):
    """Return the dynamic viscosity of water at a given temperature.

    If given units, the function will automatically convert to Kelvin.
    If not given units, the function will assume Kelvin."""
    if en_chem == 0:
        nu = viscosity_kinematic_alum(conc_chem, temp).magnitude
    if en_chem == 1:
        nu = viscosity_kinematic_pacl(conc_chem, temp).magnitude
    if en_chem not in [0, 1]:
        nu = pc.viscosity_kinematic(temp).magnitude
    return nu

def sep_dist_clay(ConcClay, material):
    """Return the separation distance between clay particles."""
    return (material.Density / ConcClay * (np.pi * material.Diameter ** 3 / 6)) ** (1 / 3)

def num_nanoclusters(ConcAluminum, coag):
    """Return the number of Aluminum nanoclusters."""
    return ConcAluminum / (dens_alum_nanocluster(coag).magnitude * np.pi * coag.Diameter ** 3)

def num_coll_reqd(DIM_FRACTAL, material, DiamTarget):
    """Return the number of doubling collisions required.

    Calculates the number of doubling collisions required to produce
    a floc of diameter DiamTarget."""
    return DIM_FRACTAL * np.log2(DiamTarget / material.Diameter)

def sep_dist_floc(ConcAluminum, ConcClay, coag, material, DIM_FRACTAL, DiamTarget):
    """Return separation distance as a function of floc size."""
    return material.Diameter * (np.pi / (6 * frac_vol_floc_initial(ConcAluminum, ConcClay, coag, material))) ** (1 / 3) * (DiamTarget / material.Diameter) ** (DIM_FRACTAL / 3)

def frac_vol_floc(ConcAluminum, ConcClay, coag, DIM_FRACTAL, material, DiamTarget):
    """Return the floc volume fraction."""
    return frac_vol_floc_initial(ConcAluminum, ConcClay, coag, material) * (DiamTarget / material.Diameter) ** (3 - DIM_FRACTAL)

def dens_floc_init(ConcAluminum, ConcClay, coag, material):
    """Return the density of the initial floc.

    Initial floc is made primarily of the primary colloid and nanoglobs."""
    return conc_floc(ConcAluminum, ConcClay, coag).magnitude / frac_vol_floc_initial(ConcAluminum, ConcClay, coag, material)

def vel_term_floc(ConcAl, ConcClay, coag, material, DIM_FRACTAL, DiamTarget, Temp):
    """Calculate floc terminal velocity."""
    WaterDensity = pc.density_water(Temp).magnitude
    return pc.gravity.magnitude * material.Diameter ** 2 / (18 * PHI_FLOC * pc.viscosity_kinematic(Temp).magnitude) * ((dens_floc_init(ConcAl, ConcClay, coag, material).magnitude - WaterDensity) / WaterDensity) * (DiamTarget / material.Diameter) ** (DIM_FRACTAL - 1)

def diam_floc_vel_term(ConcAl, ConcClay, coag, material, DIM_FRACTAL, VelTerm, Temp):
    """Calculate floc diamter as a function of terminal velocity."""
    WaterDensity = pc.density_water(Temp).magnitude
    return material.Diameter * (18 * VelTerm * PHI_FLOC * pc.viscosity_kinematic(Temp).magnitude / (pc.gravity.magnitude * material.Diameter ** 2) * (WaterDensity / (dens_floc_init(ConcAl, ConcClay, coag, material).magnitude - WaterDensity))) ** (1 / (DIM_FRACTAL - 1))

def time_col_turbulent(EnergyDis, ConcAl, ConcClay, coag, material, DiamTarget, DIM_FRACTAL):
    """Calculate single collision time for turbulent flow mediated collisions.

    Calculated as a function of floc size."""
    return 1 / 6 * (6 / np.pi) ** (1 / 9) * EnergyDis ** (-1 / 3) * DiamTarget ** (2 / 3) * frac_vol_floc_initial(ConcAl, ConcClay, coag, material) ** (-8 / 9) * (DiamTarget / material.Diameter) ** (8 * (DIM_FRACTAL - 3) / 9)

def diam_kolmogorov(EnergyDis, Temp, ConcAl, ConcClay, coag, material, DIM_FRACTAL):
    """Return the size of the floc with separation distances equal to
    the Kolmogorov length and the inner viscous length scale."""
    return material.Diameter * (eta_kolmogorov(EnergyDis, Temp).magnitude / material.Diameter * (6 * frac_vol_floc_initial(ConcAl, ConcClay, coag, material) / np.pi) ** (1 / 3)) ** (3 / DIM_FRACTAL)

def g_coil(FlowPlant, IDTube, RadiusCoil, Temp):
    """We need a reference for this.

    Karen's thesis likely has this equation and the reference."""
    return g_straight(FlowPlant, IDTube).magnitude * (1 + 0.033 * np.log10(dean_number(FlowPlant, IDTube, RadiusCoil, Temp)) ** 4) ** (1 / 2)

def g_time_res(FlowPlant, IDTube, RadiusCoil, LengthTube, Temp):
    """G Residence Time calculated for a coiled tube flocculator."""
    return g_coil(FlowPlant, IDTube, RadiusCoil, Temp).magnitude * time_res_tube(IDTube, LengthTube, FlowPlant).magnitude

def n_lfom_orifices_per_row_max(FLOW, HL_LFOM, drill_bits):
    """A bound on the number of orifices allowed in each row.
    The distance between consecutive orifices must be enough to retain
    structural integrity of the pipe."""
    return math.floor(math.pi * pipe.ID_SDR(nom_diam_lfom_pipe(FLOW, HL_LFOM), design.lfom.SDR_LFOM).magnitude / (orifice_diameter(FLOW, HL_LFOM, drill_bits).magnitude + aguaclara.design.lfom.ORIFICE_S.magnitude))

def height_lfom_orifices(FLOW, HL_LFOM, drill_bits):
    """Calculates the height of the center of each row of orifices.
    The bottom of the bottom row orifices is at the zero elevation
    point of the LFOM so that the flow goes to zero when the water height
    is at zero."""
    return np.arange(orifice_diameter(FLOW, HL_LFOM, drill_bits) * 0.5, HL_LFOM, dist_center_lfom_rows(FLOW, HL_LFOM))

def round_sf(number, digits):
    """Returns inputted value rounded to number of significant figures desired.

    :param number: Value to be rounded
    :type number: float
    :param digits: number of significant digits to be rounded to.
    :type digits: int"""
    units = None
    try:
        num = number.magnitude
        units = number.units
    except AttributeError:
        num = number
    try:
        if units != None:
            rounded_num = round(num, digits - int(floor(log10(abs(num)))) - 1) * units
        else:
            rounded_num = round(num, digits - int(floor(log10(abs(num)))) - 1)
        return rounded_num
    except ValueError:
        if units != None:
            return 0 * units
        else:
            return 0

def ngram_count(text, N=1, keep_punct=False):
    """if N=1, return a dict containing each letter along with how many times the letter occurred.
    if N=2, returns a dict containing counts of each bigram (pair of letters)
    etc.
    There is an option to remove all spaces and punctuation prior to processing"""
    if not keep_punct:
        text = re.sub('[^A-Z]', '', text.upper())
    count = {}
    for i in range(len(text) - N + 1):
        c = text[i:i + N]
        if c in count:
            count[c] += 1
        else:
            count[c] = 1.0
    return count

def ngram_freq(text, N=1, log=False, floor=0.01):
    """returns the n-gram frequencies of all n-grams encountered in text.
    Option to return log probabilities or standard probabilities.
    Note that only n-grams occurring in 'text' will have probabilities.
    For the probability of not-occurring n-grams, use freq['floor'].
    This is set to floor/len(text)"""
    freq = ngram_count(text, N)
    L = 1.0 * (len(text) - N + 1)
    for c in freq.keys():
        if log:
            freq[c] = math.log10(freq[c] / L)
        else:
            freq[c] = freq[c] / L
    if log:
        freq['floor'] = math.log10(floor / L)
    else:
        freq['floor'] = floor / L
    return freq

def restore_punctuation(original, modified):
    """If punctuation was accidently removed, use this function to restore it.
    requires the orignial string with punctuation."""
    ret = ''
    count = 0
    try:
        for c in original:
            if c.isalpha():
                ret += modified[count]
                count += 1
            else:
                ret += c
    except IndexError:
        print('restore_punctuation: strings must have same number of alphabetic chars')
        raise
    return ret

def keyword_to_key(word, alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ'):
    """convert a key word to a key by appending on the other letters of the alphabet.
    e.g. MONARCHY -> MONARCHYBDEFGIJKLPQSTUVWXZ"""
    ret = ''
    word = (word + alphabet).upper()
    for i in word:
        if i in ret:
            continue
        ret += i
    return ret

def kron(a, b):
    """Kronecker product of two TT-matrices or two TT-vectors"""
    if hasattr(a, '__kron__'):
        return a.__kron__(b)
    if a is None:
        return b
    else:
        raise ValueError('Kron is waiting for two TT-vectors or two TT-matrices')

def dot(a, b):
    """Dot product of two TT-matrices or two TT-vectors"""
    if hasattr(a, '__dot__'):
        return a.__dot__(b)
    if a is None:
        return b
    else:
        raise ValueError('Dot is waiting for two TT-vectors or two TT-    matrices')

def zkron(ttA, ttB):
    """Do kronecker product between cores of two matrices ttA and ttB.
    Look about kronecker at: https://en.wikipedia.org/wiki/Kronecker_product
    For details about operation refer: https://arxiv.org/abs/1802.02839
    :param ttA: first TT-matrix;
    :param ttB: second TT-matrix;
    :return: TT-matrix in z-order"""
    Al = _matrix.matrix.to_list(ttA)
    Bl = _matrix.matrix.to_list(ttB)
    Hl = [_np.kron(B, A) for A, B in zip(Al, Bl)]
    return _matrix.matrix.from_list(Hl)

def zkronv(ttA, ttB):
    """Do kronecker product between vectors ttA and ttB.
    Look about kronecker at: https://en.wikipedia.org/wiki/Kronecker_product
    For details about operation refer: https://arxiv.org/abs/1802.02839
    :param ttA: first TT-vector;
    :param ttB: second TT-vector;
    :return: operation result in z-order"""
    Al = _vector.vector.to_list(ttA)
    Bl = _vector.vector.to_list(ttB)
    Hl = [_np.kron(B, A) for A, B in zip(Al, Bl)]
    return _vector.vector.from_list(Hl)

def linspace(n, d=None, a=0.0, b=1.0, right=True, left=True):
    """Create a QTT-representation of a uniform grid on an interval [a, b]"""
    if isinstance(n, six.integer_types):
        n = [n]
    if d is None:
        n0 = _np.asanyarray(n, dtype=_np.int32)
    else:
        n0 = _np.array(n * d, dtype=_np.int32)
    d = n0.size
    t = xfun(n0)
    e = ones(n0)
    N = _np.prod(n0)
    if left and right:
        h = (b - a) * 1.0 / (N - 1)
        res = a * e + t * h
    elif left and (not right):
        h = (b - a) * 1.0 / N
        res = a * e + t * h
    elif right and (not left):
        h = (b - a) * 1.0 / N
        res = a * e + (t + e) * h
    else:
        h = (b - a) * 1.0 / (N - 1)
        res = a * e + (t + e) * h
    return res.round(1e-13)

def cos(d, alpha=1.0, phase=0.0):
    """Create TT-vector for :math:`\\cos(\\alpha n + \\varphi)`."""
    return sin(d, alpha, phase + _math.pi * 0.5)

def delta(n, d=None, center=0):
    """Create TT-vector for delta-function :math:`\\delta(x - x_0)`."""
    if isinstance(n, six.integer_types):
        n = [n]
    if d is None:
        n0 = _np.asanyarray(n, dtype=_np.int32)
    else:
        n0 = _np.array(n * d, dtype=_np.int32)
    d = n0.size
    if center < 0:
        cind = [0] * d
    else:
        cind = []
        for i in xrange(d):
            cind.append(center % n0[i])
            center //= n0[i]
        if center > 0:
            cind = [0] * d
    cr = []
    for i in xrange(d):
        cur_core = _np.zeros((1, n0[i], 1))
        cur_core[0, cind[i], 0] = 1
        cr.append(cur_core)
    return _vector.vector.from_list(cr)

def unit(n, d=None, j=None, tt_instance=True):
    """Generates e_j _vector in tt.vector format
    ---------
    Parameters:
        n - modes (either integer or array)
        d - dimensionality (integer)
        j - position of 1 in full-format e_j (integer)
        tt_instance - if True, returns tt.vector;
                      if False, returns tt cores as a list"""
    if isinstance(n, int):
        if d is None:
            d = 1
        n = n * _np.ones(d, dtype=_np.int32)
    else:
        d = len(n)
    if j is None:
        j = 0
    rv = []
    j = _ind2sub(n, j)
    for k in xrange(d):
        rv.append(_np.zeros((1, n[k], 1)))
        rv[-1][0, j[k], 0] = 1
    if tt_instance:
        rv = _vector.vector.from_list(rv)
    return rv

def left(X, i):
    """Compute the orthogonal matrix Q_{\\leq i} as defined in [1]."""
    if i < 0:
        return np.ones([1, 1])
    answ = np.ones([1, 1])
    cores = tt.tensor.to_list(X)
    for dim in xrange(i + 1):
        answ = np.tensordot(answ, cores[dim], 1)
    answ = reshape(answ, (-1, X.r[i + 1]))
    return answ

def right(X, i):
    """Compute the orthogonal matrix Q_{\\geq i} as defined in [1]."""
    if i > X.d - 1:
        return np.ones([1, 1])
    answ = np.ones([1, 1])
    cores = tt.tensor.to_list(X)
    for dim in xrange(X.d - 1, i - 1, -1):
        answ = np.tensordot(cores[dim], answ, 1)
    answ = reshape(answ, (X.r[i], -1))
    return answ.T

def unfolding(tens, i):
    """Compute the i-th unfolding of a tensor."""
    return reshape(tens.full(), (np.prod(tens.n[0:i + 1]), -1))

def _update_lhs(lhs, xCore, zCore, new_lhs):
    """Function to be called from the project()"""
    r_old_x, n, r_x = xCore.shape
    num_obj, r_old_z, n, r_z = zCore.shape
    for idx in range(num_obj):
        for val in range(n):
            for alpha_old_z in range(r_old_z):
                for alpha_z in range(r_z):
                    for alpha_old_x in range(r_old_x):
                        for alpha_x in range(r_x):
                            curr_value = lhs[idx, alpha_old_x, alpha_old_z]
                            curr_value *= xCore[alpha_old_x, val, alpha_x]
                            curr_value *= zCore[idx, alpha_old_z, val, alpha_z]
                            new_lhs[idx, alpha_x, alpha_z] += curr_value

def _update_rhs(curr_rhs, xCore, zCore, new_rhs):
    """Function to be called from the project()"""
    r_x, n, r_old_x = xCore.shape
    num_obj, r_z, n, r_old_z = zCore.shape
    for idx in range(num_obj):
        for val in range(n):
            for alpha_old_z in range(r_old_z):
                for alpha_z in range(r_z):
                    for alpha_old_x in range(r_old_x):
                        for alpha_x in range(r_x):
                            curr_value = curr_rhs[idx, alpha_old_z, alpha_old_x]
                            curr_value *= xCore[alpha_x, val, alpha_old_x]
                            curr_value *= zCore[idx, alpha_z, val, alpha_old_z]
                            new_rhs[idx, alpha_z, alpha_x] += curr_value

def encode_for_locale(s):
    """Encode text items for system locale. If encoding fails, fall back to ASCII."""
    try:
        return s.encode(LOCALE_ENCODING, 'ignore')
    except (AttributeError, UnicodeDecodeError):
        return s.decode('ascii', 'ignore').encode(LOCALE_ENCODING)

def run_fib_with_clear(r):
    """Run Fibonacci generator r times."""
    for i in range(r):
        if randint(RAND_MIN, RAND_MAX) == RAND_MIN:
            fib.cache_clear()
            fib2.cache_clear()
        res = fib(PythonInt(FIB))
        if RESULT != res:
            raise ValueError('Expected %d, Got %d' % (RESULT, res))

def run_fib_with_stats(r):
    """Run Fibonacci generator r times."""
    for i in range(r):
        res = fib(PythonInt(FIB))
        if RESULT != res:
            raise ValueError('Expected %d, Got %d' % (RESULT, res))

def get_topic_tree(rs, topic, depth=0):
    """Given one topic, get the list of all included/inherited topics.

    :param str topic: The topic to start the search at.
    :param int depth: The recursion depth counter.

    :return []str: Array of topics."""
    if depth > rs._depth:
        rs._warn('Deep recursion while scanning topic trees!')
        return []
    topics = [topic]
    if topic in rs._includes:
        for includes in sorted(rs._includes[topic]):
            topics.extend(get_topic_tree(rs, includes, depth + 1))
    if topic in rs._lineage:
        for inherits in sorted(rs._lineage[topic]):
            topics.extend(get_topic_tree(rs, inherits, depth + 1))
    return topics

def word_count(trigger, all=False):
    """Count the words that aren't wildcards or options in a trigger.

    :param str trigger: The trigger to count words for.
    :param bool all: Count purely based on whitespace separators, or
        consider wildcards not to be their own words.

    :return int: The word count."""
    words = []
    if all:
        words = re.split(RE.ws, trigger)
    else:
        words = re.split(RE.wilds_and_optionals, trigger)
    wc = 0
    for word in words:
        if len(word) > 0:
            wc += 1
    return wc

def string_format(msg, method):
    """Format a string (upper, lower, formal, sentence).

    :param str msg: The user's message.
    :param str method: One of ``uppercase``, ``lowercase``,
        ``sentence`` or ``formal``.

    :return str: The reformatted string."""
    if method == 'uppercase':
        return msg.upper()
    elif method == 'lowercase':
        return msg.lower()
    elif method == 'sentence':
        return msg.capitalize()
    elif method == 'formal':
        return string.capwords(msg)

def hello_rivescript():
    """Receive an inbound SMS and send a reply from RiveScript."""
    from_number = request.values.get('From', 'unknown')
    message = request.values.get('Body')
    reply = '(Internal error)'
    if message:
        reply = bot.reply(from_number, message)
    resp = twilio.twiml.Response()
    resp.message(reply)
    return str(resp)

def reply():
    """Fetch a reply from RiveScript.

    Parameters (JSON):
    * username
    * message
    * vars"""
    params = request.json
    if not params:
        return jsonify({'status': 'error', 'error': 'Request must be of the application/json type!'})
    username = params.get('username')
    message = params.get('message')
    uservars = params.get('vars', dict())
    if username is None or message is None:
        return jsonify({'status': 'error', 'error': 'username and message are required keys'})
    if type(uservars) is dict:
        for key, value in uservars.items():
            bot.set_uservar(username, key, value)
    reply = bot.reply(username, message)
    uservars = bot.get_uservars(username)
    return jsonify({'status': 'ok', 'reply': reply, 'vars': uservars})

