    if not points:
        return
    points = [(int(t), float(v)) for t, v in points]
    points.sort(key=lambda p: p[0], reverse=True)
    fh = None
    try:
        fh = open(path, 'r+b')
        return file_update_many(fh, points)
    finally:
        if fh:
            fh.close()

