        if fh:
            fh.close()
    return None

def extract_variants(pattern):
    """Extract the pattern variants (ie. {foo,bar}baz = foobaz or barbaz)."""
    v1, v2 = (pattern.find('{'), pattern.find('}'))
    if v1 > -1 and v2 > v1:
        variations = pattern[v1 + 1:v2].split(',')
        variants = [pattern[:v1] + v + pattern[v2 + 1:] for v in variations]
    else:
        variants = [pattern]
    return list(_deduplicate(variants))

def match_entries(entries, pattern):
    """A drop-in replacement for fnmatch.filter that supports pattern
    variants (ie. {foo,bar}baz = foobaz or barbaz)."""
    matching = []
    for variant in expand_braces(pattern):
        matching.extend(fnmatch.filter(entries, variant))
    return list(_deduplicate(matching))

def expand_braces(pattern):
    """Find the rightmost, innermost set of braces and, if it contains a
    comma-separated list, expand its contents recursively (any of its items
    may itself be a list enclosed in braces).

    Return the full list of expanded strings."""
    res = set()
    def remove_outer_braces(s):
        if s[0] == '{' and s[-1] == '}':
            return s[1:-1]
        return s
    match = EXPAND_BRACES_RE.search(pattern)
    if match is not None:
        sub = match.group(1)
        v1, v2 = match.span(1)
        if ',' in sub:
            for pat in sub.strip('{}').split(','):
                subpattern = pattern[:v1] + pat + pattern[v2:]
                res.update(expand_braces(subpattern))
        else:
            subpattern = pattern[:v1] + remove_outer_braces(sub) + pattern[v2:]
            res.update(expand_braces(subpattern))
    else:
        res.add(pattern.replace('\\}', '}'))
    return list(res)

def safeArgs(args):
    """Iterate over valid, finite values in an iterable.

    Skip any items that are None, NaN, or infinite."""
    return (arg for arg in args if arg is not None and (not math.isnan(arg)) and (not math.isinf(arg)))

def dataLimits(data, drawNullAsZero=False, stacked=False):
    """Return the range of values in data as (yMinValue, yMaxValue).

    data is an array of TimeSeries objects."""
    missingValues = any((None in series for series in data))
    finiteData = [series for series in data if not series.options.get('drawAsInfinite')]
    yMinValue = safeMin((safeMin(series) for series in finiteData))
    if yMinValue is None:
        return (0.0, 1.0)
    if yMinValue > 0.0 and drawNullAsZero and missingValues:
        yMinValue = 0.0
    if stacked:
        length = safeMin((len(series) for series in finiteData))
        sumSeries = []
        for i in range(0, length):
            sumSeries.append(safeSum((series[i] for series in finiteData)))
        yMaxValue = safeMax(sumSeries)
    else:
        yMaxValue = safeMax((safeMax(series) for series in finiteData))
    if yMaxValue < 0.0 and drawNullAsZero and missingValues:
        yMaxValue = 0.0
    return (yMinValue, yMaxValue)

def format_units(v, step=None, system='si', units=None):
    """Format the given value in standardized units.

    ``system`` is either 'binary' or 'si'

    For more info, see:
        http://en.wikipedia.org/wiki/SI_prefix
        http://en.wikipedia.org/wiki/Binary_prefix"""
    if v is None:
        return (0, '')
    for prefix, size in UnitSystems[system]:
        if condition(v, size, step):
            v2 = v / size
            if v2 - math.floor(v2) < 1e-11 and v > 1:
                v2 = float(math.floor(v2))
            if units:
                prefix = '%s%s' % (prefix, units)
            return (v2, prefix)
    if v - math.floor(v) < 1e-11 and v > 1:
        v = float(math.floor(v))
    if units:
        prefix = units
    else:
        prefix = ''
    return (v, prefix)

def formatPathExpressions(seriesList):
    """Returns a comma-separated list of unique path expressions."""
    pathExpressions = sorted(set([s.pathExpression for s in seriesList]))
    return ','.join(pathExpressions)

def keepLastValue(requestContext, seriesList, limit=INF):
    """Takes one metric or a wildcard seriesList, and optionally a limit to the
    number of 'None' values to skip over. Continues the line with the last
    received value when gaps ('None' values) appear in your data, rather than
    breaking your line.

    Example::

        &target=keepLastValue(Server01.connections.handled)
        &target=keepLastValue(Server01.connections.handled, 10)"""
    for series in seriesList:
        series.name = 'keepLastValue(%s)' % series.name
        series.pathExpression = series.name
        consecutiveNones = 0
        for i, value in enumerate(series):
            series[i] = value
            if i == 0:
                continue
            if value is None:
                consecutiveNones += 1
            else:
                if 0 < consecutiveNones <= limit:
                    for index in range(i - consecutiveNones, i):
                        series[index] = series[i - consecutiveNones - 1]
                consecutiveNones = 0
        if 0 < consecutiveNones <= limit:
            for index in range(len(series) - consecutiveNones, len(series)):
                series[index] = series[len(series) - consecutiveNones - 1]
    return seriesList

def changed(requestContext, seriesList):
    """Takes one metric or a wildcard seriesList.
    Output 1 when the value changed, 0 when null or the same
    Example::

        &target=changed(Server01.connections.handled)"""
    for series in seriesList:
        series.name = series.pathExpression = 'changed(%s)' % series.name
        previous = None
        for index, value in enumerate(series):
            if previous is None:
                series[index] = 0
            elif value is not None and previous != value:
                series[index] = 1
            else:
                series[index] = 0
            previous = value
    return seriesList

def squareRoot(requestContext, seriesList):
    """Takes one metric or a wildcard seriesList, and computes the square root
    of each datapoint.

    Example::

        &target=squareRoot(Server.instance01.threads.busy)"""
    for series in seriesList:
        series.name = 'squareRoot(%s)' % series.name
        for i, value in enumerate(series):
            series[i] = safePow(value, 0.5)
    return seriesList

def offset(requestContext, seriesList, factor):
    """Takes one metric or a wildcard seriesList followed by a constant, and adds
    the constant to each datapoint.

    Example::

        &target=offset(Server.instance01.threads.busy,10)"""
    for series in seriesList:
        series.name = 'offset(%s,%g)' % (series.name, float(factor))
        series.pathExpression = series.name
        for i, value in enumerate(series):
            if value is not None:
                series[i] = value + factor
    return seriesList

def aliasSub(requestContext, seriesList, search, replace):
    """ Runs series names through a regex search/replace.

    Example::

         &target=aliasSub(ip.*TCP*,"^.*TCP(\\d+)","\\1")
    """
    try:
        seriesList.name = re.sub(search, replace, seriesList.name)
    except AttributeError:
        for series in seriesList:
            series.name = re.sub(search, replace, series.name)
    return seriesList

def alias(requestContext, seriesList, newName):
    """Takes one metric or a wildcard seriesList and a string in quotes.
    Prints the string instead of the metric name in the legend.

    Example::

        &target=alias(Sales.widgets.largeBlue,"Large Blue Widgets")"""
    try:
        seriesList.name = newName
    except AttributeError:
        for series in seriesList:
            series.name = newName
    return seriesList

def _getFirstPathExpression(name):
    """Returns the first metric path in an expression."""
    tokens = grammar.parseString(name)
    pathExpression = None
    while pathExpression is None:
        if tokens.pathExpression:
            pathExpression = tokens.pathExpression
        elif tokens.expression:
            tokens = tokens.expression
        elif tokens.call:
            tokens = tokens.call.args[0]
        else:
            break
    return pathExpression

def legendValue(requestContext, seriesList, *valueTypes):
    """Takes one metric or a wildcard seriesList and a string in quotes.
    Appends a value to the metric name in the legend. Currently one or several
    of: `last`, `avg`, `total`, `min`, `max`. The last argument can be `si`
    (default) or `binary`, in that case values will be formatted in the
    corresponding system.

    Example::

        &target=legendValue(Sales.widgets.largeBlue, 'avg', 'max', 'si')"""
    valueFuncs = {'avg': lambda s: safeDiv(safeSum(s), safeLen(s)), 'total': safeSum, 'min': safeMin, 'max': safeMax, 'last': safeLast}
    system = None
    if valueTypes[-1] in ('si', 'binary'):
        system = valueTypes[-1]
        valueTypes = valueTypes[:-1]
    for valueType in valueTypes:
        valueFunc = valueFuncs.get(valueType, lambda s: '(?)')
        if system is None:
            for series in seriesList:
                series.name += ' (%s: %s)' % (valueType, valueFunc(series))
        else:
            for series in seriesList:
                value = valueFunc(series)
                formatted = None
                if value is not None:
                    formatted = '%.2f%s' % format_units(value, system=system)
                series.name = '%-20s%-5s%-10s' % (series.name, valueType, formatted)
    return seriesList

def alpha(requestContext, seriesList, alpha):
    """Assigns the given alpha transparency setting to the series. Takes a float
    value between 0 and 1."""
    for series in seriesList:
        series.options['alpha'] = alpha
    return seriesList

def logarithm(requestContext, seriesList, base=10):
    """Takes one metric or a wildcard seriesList, a base, and draws the y-axis in
    logarithmic format. If base is omitted, the function defaults to base 10.

    Example::

        &target=log(carbon.agents.hostname.avgUpdateTime,2)"""
    results = []
    for series in seriesList:
        newValues = []
        for val in series:
            if val is None:
                newValues.append(None)
            elif val <= 0:
                newValues.append(None)
            else:
                newValues.append(math.log(val, base))
        newName = 'log(%s, %s)' % (series.name, base)
        newSeries = TimeSeries(newName, series.start, series.end, series.step, newValues)
        newSeries.pathExpression = newName
        results.append(newSeries)
    return results

def _getPercentile(points, n, interpolate=False):
    """Percentile is calculated using the method outlined in the NIST Engineering
    Statistics Handbook:
    http://www.itl.nist.gov/div898/handbook/prc/section2/prc252.htm"""
    sortedPoints = sorted(not_none(points))
    if len(sortedPoints) == 0:
        return None
    fractionalRank = n / 100.0 * (len(sortedPoints) + 1)
    rank = int(fractionalRank)
    rankFraction = fractionalRank - rank
    if not interpolate:
        rank += int(math.ceil(rankFraction))
    if rank == 0:
        percentile = sortedPoints[0]
    elif rank - 1 == len(sortedPoints):
        percentile = sortedPoints[-1]
    else:
        percentile = sortedPoints[rank - 1]
    if interpolate:
        if rank != len(sortedPoints):
            nextValue = sortedPoints[rank]
            percentile = percentile + rankFraction * (nextValue - percentile)
    return percentile

def removeAboveValue(requestContext, seriesList, n):
    """Removes data above the given threshold from the series or list of series
    provided. Values above this threshold are assigned a value of None."""
    for s in seriesList:
        s.name = 'removeAboveValue(%s, %g)' % (s.name, n)
        s.pathExpression = s.name
        for index, val in enumerate(s):
            if val is None:
                continue
            if val > n:
                s[index] = None
    return seriesList

def removeBelowPercentile(requestContext, seriesList, n):
    """Removes data below the nth percentile from the series or list of series
    provided. Values below this percentile are assigned a value of None."""
    for s in seriesList:
        s.name = 'removeBelowPercentile(%s, %g)' % (s.name, n)
        s.pathExpression = s.name
        try:
            percentile = nPercentile(requestContext, [s], n)[0][0]
        except IndexError:
            continue
        for index, val in enumerate(s):
            if val is None:
                continue
            if val < percentile:
                s[index] = None
    return seriesList

def sortByTotal(requestContext, seriesList):
    """Takes one metric or a wildcard seriesList.

    Sorts the list of metrics by the sum of values across the time period
    specified."""
    return list(sorted(seriesList, key=safeSum, reverse=True))

def secondYAxis(requestContext, seriesList):
    """Graph the series on the secondary Y axis."""
    for series in seriesList:
        series.options['secondYAxis'] = True
        series.name = 'secondYAxis(%s)' % series.name
    return seriesList

def holtWintersAberration(requestContext, seriesList, delta=3):
    """Performs a Holt-Winters forecast using the series as input data and plots
    the positive or negative deviation of the series data from the forecast."""
    results = []
    for series in seriesList:
        confidenceBands = holtWintersConfidenceBands(requestContext, [series], delta)
        lowerBand = confidenceBands[0]
        upperBand = confidenceBands[1]
        aberration = list()
        for i, actual in enumerate(series):
            if actual is None:
                aberration.append(0)
            elif upperBand[i] is not None and actual > upperBand[i]:
                aberration.append(actual - upperBand[i])
            elif lowerBand[i] is not None and actual < lowerBand[i]:
                aberration.append(actual - lowerBand[i])
            else:
                aberration.append(0)
        newName = 'holtWintersAberration(%s)' % series.name
        results.append(TimeSeries(newName, series.start, series.end, series.step, aberration))
    return results

def find_transported_elements(rxn):
    """Return a dictionary showing the amount of transported elements of a rxn.

    Collects the elements for each metabolite participating in a reaction,
    multiplies the amount by the metabolite's stoichiometry in the reaction and
    bins the result according to the compartment that metabolite is in. This
    produces a dictionary of dictionaries such as this
    ``{'p': {'C': -1, 'H': -4}, c: {'C': 1, 'H': 4}}`` which shows the
    transported entities. This dictionary is then simplified to only include
    the non-zero elements of one single compartment i.e. showing the precise
    elements that are transported.

    Parameters
    ----------
    rxn : cobra.Reaction
        Any cobra.Reaction containing metabolites."""
    element_dist = defaultdict()
    for met in rxn.metabolites:
        if met.compartment not in element_dist:
            element_dist[met.compartment] = {k: v * rxn.metabolites[met] for k, v in iteritems(met.elements)}
        else:
            x = {k: v * rxn.metabolites[met] for k, v in iteritems(met.elements)}
            y = element_dist[met.compartment]
            element_dist[met.compartment] = {k: x.get(k, 0) + y.get(k, 0) for k in set(x) | set(y)}
    delta_dict = defaultdict()
    for elements in itervalues(element_dist):
        delta_dict.update(elements)
    delta_dict = {k: abs(v) for k, v in iteritems(delta_dict) if v != 0}
    return delta_dict

def find_compartment_id_in_model(model, compartment_id):
    """Identify a model compartment by looking up names in COMPARTMENT_SHORTLIST.

    Parameters
    ----------
    model : cobra.Model
        The metabolic model under investigation.
    compartment_id : string
        Memote internal compartment identifier used to access compartment name
        shortlist to look up potential compartment names.

    Returns
    -------
    string
        Compartment identifier in the model corresponding to compartment_id."""
    if compartment_id not in COMPARTMENT_SHORTLIST.keys():
        raise KeyError('{} is not in the COMPARTMENT_SHORTLIST! Make sure you typed the ID correctly, if yes, update the shortlist manually.'.format(compartment_id))
    if len(model.compartments) == 0:
        raise KeyError('It was not possible to identify the compartment {}, since the model has no compartments at all.'.format(COMPARTMENT_SHORTLIST[compartment_id][0]))
    if compartment_id in model.compartments.keys():
        return compartment_id
    for name in COMPARTMENT_SHORTLIST[compartment_id]:
        for c_id, c_name in model.compartments.items():
            if c_name.lower() == name:
                return c_id
    if compartment_id == 'c':
        return largest_compartment_id_met(model)

def snapshot_report(result, config=None, html=True):
    """Generate a snapshot report from a result set and configuration.

    Parameters
    ----------
    result : memote.MemoteResult
        Nested dictionary structure as returned from the test suite.
    config : dict, optional
        The final test report configuration (default None).
    html : bool, optional
        Whether to render the report as full HTML or JSON (default True)."""
    if config is None:
        config = ReportConfiguration.load()
    report = SnapshotReport(result=result, configuration=config)
    if html:
        return report.render_html()
    else:
        return report.render_json()

def diff_report(diff_results, config=None, html=True):
    """Generate a diff report from a result set and configuration.

    Parameters
    ----------
    diff_results : iterable of memote.MemoteResult
        Nested dictionary structure as returned from the test suite.
    config : dict, optional
        The final test report configuration (default None).
    html : bool, optional
        Whether to render the report as full HTML or JSON (default True)."""
    if config is None:
        config = ReportConfiguration.load()
    report = DiffReport(diff_results=diff_results, configuration=config)
    if html:
        return report.render_html()
    else:
        return report.render_json()

def find_zero_constrained_reactions(model):
    """Return list of reactions that are constrained to zero flux."""
    return [rxn for rxn in model.reactions if rxn.lower_bound == 0 and rxn.upper_bound == 0]

def is_constrained_reaction(model, rxn):
    """Return whether a reaction has fixed constraints."""
    lower_bound, upper_bound = helpers.find_bounds(model)
    if rxn.reversibility:
        return rxn.lower_bound > lower_bound or rxn.upper_bound < upper_bound
    else:
        return rxn.lower_bound > 0 or rxn.upper_bound < upper_bound

def find_oxygen_reactions(model):
    """Return list of oxygen-producing/-consuming reactions."""
    o2_in_model = helpers.find_met_in_model(model, 'MNXM4')
    return set([rxn for met in model.metabolites for rxn in met.reactions if met.formula == 'O2' or met in o2_in_model])

def find_unique_metabolites(model):
    """Return set of metabolite IDs without duplicates from compartments."""
    unique = set()
    for met in model.metabolites:
        is_missing = True
        for comp in model.compartments:
            if met.id.endswith('_{}'.format(comp)):
                unique.add(met.id[:-(len(comp) + 1)])
                is_missing = False
                break
        if is_missing:
            unique.add(met.id)
    return unique

def find_medium_metabolites(model):
    """Return the list of metabolites ingested/excreted by the model."""
    return [met.id for rxn in model.medium for met in model.reactions.get_by_id(rxn).metabolites]

def load_cobra_model(path, notifications):
    """Load a COBRA model with meta information from an SBML document."""
    doc = libsbml.readSBML(path)
    fbc = doc.getPlugin('fbc')
    sbml_ver = (doc.getLevel(), doc.getVersion(), fbc if fbc is None else fbc.getVersion())
    with catch_warnings(record=True) as warnings:
        simplefilter('always')
        try:
            model = read_sbml_model(path)
        except Exception as err:
            notifications['errors'].append(str(err))
            model = None
            validate = True
        else:
            validate = False
        notifications['warnings'].extend([str(w.message) for w in warnings])
    if validate:
        run_sbml_validation(doc, notifications)
    return (model, sbml_ver)

def format_failure(failure):
    """Format how an error or warning should be displayed."""
    return 'Line {}, Column {} - #{}: {} - Category: {}, Severity: {}'.format(failure.getLine(), failure.getColumn(), failure.getErrorId(), failure.getMessage(), failure.getCategoryAsString(), failure.getSeverity())

def run_sbml_validation(document, notifications):
    """Report errors and warnings found in an SBML document."""
    validator = libsbml.SBMLValidator()
    validator.validate(document)
    for i in range(document.getNumErrors()):
        notifications['errors'].append(format_failure(document.getError(i)))
    for i in range(validator.getNumFailures()):
        failure = validator.getFailure(i)
        if failure.isWarning():
            notifications['warnings'].append(format_failure(failure))
        else:
            notifications['errors'].append(format_failure(failure))

def truncate(sequence):
    """Create a potentially shortened text display of a list.

    Parameters
    ----------
    sequence : list
        An indexable sequence of elements.

    Returns
    -------
    str
        The list as a formatted string."""
    if len(sequence) > LIST_SLICE:
        return ', '.join(sequence[:LIST_SLICE] + ['...'])
    else:
        return ', '.join(sequence)

def jsonify(obj, pretty=False):
    """Turn a nested object into a (compressed) JSON string.

    Parameters
    ----------
    obj : dict
        Any kind of dictionary structure.
    pretty : bool, optional
        Whether to format the resulting JSON in a more legible way (
        default False)."""
    if pretty:
        params = dict(sort_keys=True, indent=2, allow_nan=False, separators=(',', ': '), ensure_ascii=False)
    else:
        params = dict(sort_keys=False, indent=None, allow_nan=False, separators=(',', ':'), ensure_ascii=False)
    try:
        return json.dumps(obj, **params)
    except (TypeError, ValueError) as error:
        LOGGER.critical('The memote result structure is incompatible with the JSON standard.')
        log_json_incompatible_types(obj)
        raise_with_traceback(error)

def flatten(list_of_lists):
    """Flatten a list of lists but maintain strings and ints as entries."""
    flat_list = []
    for sublist in list_of_lists:
        if isinstance(sublist, string_types) or isinstance(sublist, int):
            flat_list.append(sublist)
        elif sublist is None:
            continue
        elif not isinstance(sublist, string_types) and len(sublist) == 1:
            flat_list.append(sublist[0])
        else:
            flat_list.append(tuple(sublist))
    return flat_list

def stdout_notifications(notifications):
    """Print each entry of errors and warnings to stdout.

    Parameters
    ----------
    notifications: dict
        A simple dictionary structure containing a list of errors and warnings."""
    for error in notifications['errors']:
        LOGGER.error(error)
    for warn in notifications['warnings']:
        LOGGER.warning(warn)

def is_mass_balanced(reaction):
    """Confirm that a reaction is mass balanced."""
    balance = defaultdict(int)
    for metabolite, coefficient in iteritems(reaction.metabolites):
        if metabolite.elements is None or len(metabolite.elements) == 0:
            return False
        for element, amount in iteritems(metabolite.elements):
            balance[element] += coefficient * amount
    return all((amount == 0 for amount in itervalues(balance)))

def is_charge_balanced(reaction):
    """Confirm that a reaction is charge balanced."""
    charge = 0
    for metabolite, coefficient in iteritems(reaction.metabolites):
        if metabolite.charge is None:
            return False
        charge += coefficient * metabolite.charge
    return charge == 0

def online(note, github_repository, github_username):
    """Upload the repository to GitHub and enable testing on Travis CI."""
    callbacks.git_installed()
    try:
        repo = git.Repo()
    except git.InvalidGitRepositoryError:
        LOGGER.critical("'memote online' requires a git repository in order to follow the current branch's commit history.")
        sys.exit(1)
    if note == 'memote-ci access':
        note = '{} to {}'.format(note, github_repository)
    gh_repo_name, auth_token, repo_access_token = _setup_gh_repo(github_repository, github_username, note)
    secret = _setup_travis_ci(gh_repo_name, auth_token, repo_access_token)
    LOGGER.info("Storing GitHub token in '.travis.yml'.")
    config = te.load_travis_configuration('.travis.yml')
    global_env = config.setdefault('env', {}).get('global')
    if global_env is None:
        config['env']['global'] = global_env = {}
    try:
        global_env['secure'] = secret
    except TypeError:
        global_env.append({'secure': secret})
    te.dump_travis_configuration(config, '.travis.yml')
    LOGGER.info("Add, commit and push changes to '.travis.yml' to GitHub.")
    repo.index.add(['.travis.yml'])
    check_call(['git', 'commit', '-m', 'chore: add encrypted GitHub access token'])
    check_call(['git', 'push', '--set-upstream', 'origin', repo.active_branch.name])

def gam_in_biomass(model, reaction):
    """Return boolean if biomass reaction includes growth-associated maintenance.

    Parameters
    ----------
    model : cobra.Model
        The metabolic model under investigation.
    reaction : cobra.core.reaction.Reaction
        The biomass reaction of the model under investigation.

    Returns
    -------
    boolean
        True if the biomass reaction includes ATP and H2O as reactants and ADP,
        Pi and H as products, False otherwise."""
    id_of_main_compartment = helpers.find_compartment_id_in_model(model, 'c')
    try:
        left = {helpers.find_met_in_model(model, 'MNXM3', id_of_main_compartment)[0], helpers.find_met_in_model(model, 'MNXM2', id_of_main_compartment)[0]}
        right = {helpers.find_met_in_model(model, 'MNXM7', id_of_main_compartment)[0], helpers.find_met_in_model(model, 'MNXM1', id_of_main_compartment)[0], helpers.find_met_in_model(model, 'MNXM9', id_of_main_compartment)[0]}
    except RuntimeError:
        return False
    return left.issubset(set(reaction.reactants)) and right.issubset(set(reaction.products))

def probe_git():
    """Return a git repository instance if it exists."""
    try:
        repo = git.Repo()
    except git.InvalidGitRepositoryError:
        LOGGER.warning('We highly recommend keeping your model in a git repository. It allows you to track changes and to easily collaborate with others via online platforms such as https://github.com.\n')
        return
    if repo.is_dirty():
        LOGGER.critical('Please git commit or git stash all changes before running the memote suite.')
        sys.exit(1)
    return repo

def git_installed():
    """Interrupt execution of memote if `git` has not been installed."""
    LOGGER.info('Checking `git` installation.')
    try:
        check_output(['git', '--version'])
    except CalledProcessError as e:
        LOGGER.critical('The execution of memote was interrupted since no installation of `git` could be detected. Please install git to use this functionality: https://git-scm.com/book/en/v2/Getting-Started-Installing-Git')
        LOGGER.debug('Underlying error:', exc_info=e)
        sys.exit(1)

def _get_html_contents(html):
    """Process a HTML block and detects whether it is a code block,
    a math block, or a regular HTML block."""
    parser = MyHTMLParser()
    parser.feed(html)
    if parser.is_code:
        return ('code', parser.data.strip())
    elif parser.is_math:
        return ('math', parser.data.strip())
    else:
        return ('', '')

def _is_path(s):
    """Return whether an object is a path."""
    if isinstance(s, string_types):
        try:
            return op.exists(s)
        except (OSError, ValueError):
            return False
    else:
        return False

def _starts_with_regex(line, regex):
    """Return whether a line starts with a regex or not."""
    if not regex.startswith('^'):
        regex = '^' + regex
    reg = re.compile(regex)
    return reg.match(line)

def create_prompt(prompt):
    """Create a prompt manager.

    Parameters
    ----------

    prompt : str or class driving from BasePromptManager
        The prompt name ('python' or 'ipython') or a custom PromptManager
        class."""
    if prompt is None:
        prompt = 'python'
    if prompt == 'python':
        prompt = PythonPromptManager
    elif prompt == 'ipython':
        prompt = IPythonPromptManager
    if isinstance(prompt, BasePromptManager):
        return prompt
    else:
        return prompt()

def _is_chunk_markdown(source):
    """Return whether a chunk contains Markdown contents."""
    lines = source.splitlines()
    if all((line.startswith('# ') for line in lines)):
        source = '\n'.join((line[2:] for line in lines if not line[2:].startswith('#')))
        if not source:
            return True
        return not _is_python(source)
    return False

def _filter_markdown(source, filters):
    """Only keep some Markdown headers from a Markdown string."""
    lines = source.splitlines()
    headers = [_replace_header_filter(filter) for filter in filters]
    lines = [line for line in lines if line.startswith(tuple(headers))]
    return '\n'.join(lines)

def _diff(text_0, text_1):
    """Return a diff between two strings."""
    diff = difflib.ndiff(text_0.splitlines(), text_1.splitlines())
    return _diff_removed_lines(diff)

def _write_json(file, contents):
