def _iterparse(xmlfile):
    """Avoid bug in python 3.{2,3}. See http://bugs.python.org/issue9257.

    :param xmlfile: XML file or file-like object"""
    try:
        return ET.iterparse(xmlfile, events=('start-ns',))
    except TypeError:
        return ET.iterparse(xmlfile, events=(b'start-ns',))

def _tweak_ns(tag, **options):
    """:param tag: XML tag element
    :param nspaces: A namespaces dict, {uri: prefix}
    :param options: Extra keyword options may contain 'nspaces' keyword option
        provide a namespace dict, {uri: prefix}

    >>> _tweak_ns("a", nspaces={})
    'a'
    >>> _tweak_ns("a", nspaces={"http://example.com/ns/val/": "val"})
    'a'
    >>> _tweak_ns("{http://example.com/ns/val/}a",
    ...           nspaces={"http://example.com/ns/val/": "val"})
    'val:a'"""
    nspaces = options.get('nspaces', None)
    if nspaces is not None:
        matched = _ET_NS_RE.match(tag)
        if matched:
            uri, tag = matched.groups()
            prefix = nspaces.get(uri, False)
            if prefix:
                return '%s:%s' % (prefix, tag)
    return tag

def _merge_dicts(dics, container=dict):
    """:param dics: [<dict/-like object must not have same keys each other>]
    :param container: callble to make a container object
    :return: <container> object

    >>> _merge_dicts(({}, ))
    {}
    >>> _merge_dicts(({'a': 1}, ))
    {'a': 1}
    >>> sorted(kv for kv in _merge_dicts(({'a': 1}, {'b': 2})).items())
    [('a', 1), ('b', 2)]"""
    dic_itr = anyconfig.compat.from_iterable((d.items() for d in dics))
    return container(anyconfig.compat.OrderedDict(dic_itr))

def _parse_text(val, **options):
    """:return: Parsed value or value itself depends on 'ac_parse_value'"""
    if val and options.get('ac_parse_value', False):
        return anyconfig.parser.parse_single(val)
    return val

def _parse_attrs(elem, container=dict, **options):
    """:param elem: ET Element object has attributes (elem.attrib)
    :param container: callble to make a container object
    :return: Parsed value or value itself depends on 'ac_parse_value'"""
    adic = dict(((_tweak_ns(a, **options), v) for a, v in elem.attrib.items()))
    if options.get('ac_parse_value', False):
        return container(dict(((k, anyconfig.parser.parse_single(v)) for k, v in adic.items())))
    return container(adic)

def root_to_container(root, container=dict, nspaces=None, **options):
    """Convert XML ElementTree Root Element to a collection of container objects.

    :param root: etree root object or None
    :param container: callble to make a container object
    :param nspaces: A namespaces dict, {uri: prefix} or None
    :param options: Keyword options,

        - tags: Dict of tags for special nodes to keep XML info, attributes,
          text and children nodes, e.g. {"attrs": "@attrs", "text": "#text"}"""
    tree = container()
    if root is None:
        return tree
    if nspaces is not None:
        for uri, prefix in nspaces.items():
            root.attrib['xmlns:' + prefix if prefix else 'xmlns'] = uri
    return elem_to_container(root, container=container, nspaces=nspaces, **_complement_tag_options(options))

def _elem_from_descendants(children_nodes, **options):
    """:param children_nodes: A list of child dict objects
    :param options: Keyword options, see :func:`container_to_etree`"""
    for child in children_nodes:
        for ckey, cval in anyconfig.compat.iteritems(child):
            celem = ET.Element(ckey)
            container_to_etree(cval, parent=celem, **options)
            yield celem

def container_to_etree(obj, parent=None, to_str=None, **options):
    """Convert a dict-like object to XML ElementTree.

    :param obj: Container instance to convert to
    :param parent: XML ElementTree parent node object or None
    :param to_str: Callable to convert value to string or None
    :param options: Keyword options,

        - tags: Dict of tags for special nodes to keep XML info, attributes,
          text and children nodes, e.g. {"attrs": "@attrs", "text": "#text"}"""
    if to_str is None:
        to_str = _to_str_fn(**options)
    if not anyconfig.utils.is_dict_like(obj):
        if parent is not None and obj:
            parent.text = to_str(obj)
        return parent
    options = _complement_tag_options(options)
    attrs, text, children = operator.itemgetter(*_ATC)(options)
    for key, val in anyconfig.compat.iteritems(obj):
        if key == attrs:
            _elem_set_attrs(val, parent, to_str)
        elif key == text:
            parent.text = to_str(val)
        elif key == children:
            for celem in _elem_from_descendants(val, **options):
                parent.append(celem)
        else:
            parent = _get_or_update_parent(key, val, to_str, parent=parent, **options)
    return ET.ElementTree(parent)

def etree_write(tree, stream):
    """Write XML ElementTree 'root' content into 'stream'.

    :param tree: XML ElementTree object
    :param stream: File or file-like object can write to"""
    try:
        tree.write(stream, encoding='utf-8', xml_declaration=True)
    except TypeError:
        tree.write(stream, encoding='unicode', xml_declaration=True)

def _customized_dumper(container, dumper=Dumper):
    """Coutnerpart of :func:`_customized_loader` for dumpers."""
    def container_representer(dumper, data, mapping_tag=_MAPPING_TAG):
        """Container representer.
        """
        return dumper.represent_mapping(mapping_tag, data.items())
    def ustr_representer(dumper, data):
        """Unicode string representer"""
        tag = 'tag:yaml.org,2002:python/unicode'
        return dumper.represent_scalar(tag, data)
    try:
        dumper.add_representer(unicode, ustr_representer)
    except NameError:
        pass
    if type(container) != dict:
        dumper.add_representer(container, container_representer)
    return dumper

def yml_load(stream, container, yml_fnc=yml_fnc, **options):
    """An wrapper of yaml.safe_load and yaml.load.

    :param stream: a file or file-like object to load YAML content
    :param container: callble to make a container object

    :return: Mapping object"""
    if options.get('ac_safe', False):
        options = {}
    elif not options.get('Loader'):
        maybe_container = options.get('ac_dict', False)
        if maybe_container and callable(maybe_container):
            container = maybe_container
        options['Loader'] = _customized_loader(container)
    ret = yml_fnc('load', stream, **common.filter_from_options('ac_dict', options))
    if ret is None:
        return container()
    return ret

def yml_dump(data, stream, yml_fnc=yml_fnc, **options):
    """An wrapper of yaml.safe_dump and yaml.dump.

    :param data: Some data to dump
    :param stream: a file or file-like object to dump YAML data"""
    _is_dict = anyconfig.utils.is_dict_like(data)
    if options.get('ac_safe', False):
        options = {}
    elif not options.get('Dumper', False) and _is_dict:
        maybe_container = options.get('ac_dict', type(data))
        options['Dumper'] = _customized_dumper(maybe_container)
    if _is_dict:
        data = anyconfig.dicts.convert_to(data, ac_dict=dict)
        options = common.filter_from_options('ac_dict', options)
    return yml_fnc('dump', data, stream, **options)

def mk_nested_dic(path, val, seps=PATH_SEPS):
    """Make a nested dict iteratively.

    :param path: Path expression to make a nested dict
    :param val: Value to set
    :param seps: Separator char candidates

    >>> mk_nested_dic("a.b.c", 1)
    {'a': {'b': {'c': 1}}}
    >>> mk_nested_dic("/a/b/c", 1)
    {'a': {'b': {'c': 1}}}"""
    ret = None
    for key in reversed(_split_path(path, seps)):
        ret = {key: val if ret is None else ret.copy()}
    return ret

def get(dic, path, seps=PATH_SEPS, idx_reg=_JSNP_GET_ARRAY_IDX_REG):
    """getter for nested dicts.

    :param dic: a dict[-like] object
    :param path: Path expression to point object wanted
    :param seps: Separator char candidates
    :return: A tuple of (result_object, error_message)

    >>> d = {'a': {'b': {'c': 0, 'd': [1, 2]}}, '': 3}
    >>> assert get(d, '/') == (3, '')  # key becomes '' (empty string).
    >>> assert get(d, "/a/b/c") == (0, '')
    >>> sorted(get(d, "a.b")[0].items())
    [('c', 0), ('d', [1, 2])]
    >>> (get(d, "a.b.d"), get(d, "/a/b/d/1"))
    (([1, 2], ''), (2, ''))
    >>> get(d, "a.b.key_not_exist")  # doctest: +ELLIPSIS
    (None, "'...'")
    >>> get(d, "/a/b/d/2")
    (None, 'list index out of range')
    >>> get(d, "/a/b/d/-")  # doctest: +ELLIPSIS
    (None, 'list indices must be integers...')"""
    items = [_jsnp_unescape(p) for p in _split_path(path, seps)]
    if not items:
        return (dic, '')
    try:
        if len(items) == 1:
            return (dic[items[0]], '')
        prnt = functools.reduce(operator.getitem, items[:-1], dic)
        arr = anyconfig.utils.is_list_like(prnt) and idx_reg.match(items[-1])
        return (prnt[int(items[-1])], '') if arr else (prnt[items[-1]], '')
    except (TypeError, KeyError, IndexError) as exc:
        return (None, str(exc))

def _get_update_fn(strategy):
    """Select dict-like class based on merge strategy and orderness of keys.

    :param merge: Specify strategy from MERGE_STRATEGIES of how to merge dicts.
    :return: Callable to update objects"""
    if strategy is None:
        strategy = MS_DICTS
    try:
        return _MERGE_FNS[strategy]
    except KeyError:
        if callable(strategy):
            return strategy
        raise ValueError('Wrong merge strategy: %r' % strategy)

def _make_recur(obj, make_fn, ac_ordered=False, ac_dict=None, **options):
    """:param obj: A mapping objects or other primitive object
    :param make_fn: Function to make/convert to
    :param ac_ordered: Use OrderedDict instead of dict to keep order of items
    :param ac_dict: Callable to convert 'obj' to mapping object
    :param options: Optional keyword arguments.

    :return: Mapping object"""
    if ac_dict is None:
        ac_dict = anyconfig.compat.OrderedDict if ac_ordered else dict
    return ac_dict(((k, None if v is None else make_fn(v, **options)) for k, v in obj.items()))

def _make_iter(obj, make_fn, **options):
    """:param obj: A mapping objects or other primitive object
    :param make_fn: Function to make/convert to
    :param options: Optional keyword arguments.

    :return: Mapping object"""
    return type(obj)((make_fn(v, **options) for v in obj))

def convert_to(obj, ac_ordered=False, ac_dict=None, **options):
    """Convert a mapping objects to a dict or object of 'to_type' recursively.
    Borrowed basic idea and implementation from bunch.unbunchify. (bunch is
    distributed under MIT license same as this.)

    :param obj: A mapping objects or other primitive object
    :param ac_ordered: Use OrderedDict instead of dict to keep order of items
    :param ac_dict: Callable to convert 'obj' to mapping object
    :param options: Optional keyword arguments.

    :return: A dict or OrderedDict or object of 'cls'

    >>> OD = anyconfig.compat.OrderedDict
    >>> convert_to(OD((('a', 1) ,)), cls=dict)
    {'a': 1}
    >>> convert_to(OD((('a', OD((('b', OD((('c', 1), ))), ))), )), cls=dict)
    {'a': {'b': {'c': 1}}}"""
    options.update(ac_ordered=ac_ordered, ac_dict=ac_dict)
    if anyconfig.utils.is_dict_like(obj):
        return _make_recur(obj, convert_to, **options)
    if anyconfig.utils.is_list_like(obj):
        return _make_iter(obj, convert_to, **options)
    return obj

def copen(filepath, flag='r', encoding=None):
    """FIXME: How to test this ?

    >>> c = copen(__file__)
    >>> c is not None
    True"""
    if encoding is None:
        encoding = locale.getdefaultlocale()[1]
    return codecs.open(filepath, flag, encoding)

def render_s(tmpl_s, ctx=None, paths=None, filters=None):
    """Compile and render given template string 'tmpl_s' with context 'context'.

    :param tmpl_s: Template string
    :param ctx: Context dict needed to instantiate templates
    :param paths: Template search paths
    :param filters: Custom filters to add into template engine
    :return: Compiled result (str)

    >>> render_s("aaa") == "aaa"
    True
    >>> s = render_s('a = {{ a }}, b = "{{ b }}"', {'a': 1, 'b': 'bbb'})
    >>> if SUPPORTED:
    ...     assert s == 'a = 1, b = "bbb"'"""
    if paths is None:
        paths = [os.curdir]
    env = tmpl_env(paths)
    if env is None:
        return tmpl_s
    if filters is not None:
        env.filters.update(filters)
    if ctx is None:
        ctx = {}
    return tmpl_env(paths).from_string(tmpl_s).render(**ctx)

def render_impl(template_file, ctx=None, paths=None, filters=None):
    """:param template_file: Absolute or relative path to the template file
    :param ctx: Context dict needed to instantiate templates
    :param filters: Custom filters to add into template engine
    :return: Compiled result (str)"""
    env = tmpl_env(make_template_paths(template_file, paths))
    if env is None:
        return copen(template_file).read()
    if filters is not None:
        env.filters.update(filters)
    if ctx is None:
        ctx = {}
    return env.get_template(os.path.basename(template_file)).render(**ctx)

def render(filepath, ctx=None, paths=None, ask=False, filters=None):
    """Compile and render template and return the result as a string.

    :param template_file: Absolute or relative path to the template file
    :param ctx: Context dict needed to instantiate templates
    :param paths: Template search paths
    :param ask: Ask user for missing template location if True
    :param filters: Custom filters to add into template engine
    :return: Compiled result (str)"""
    try:
        return render_impl(filepath, ctx, paths, filters)
    except TemplateNotFound as mtmpl:
        if not ask:
            raise
        usr_tmpl = anyconfig.compat.raw_input(os.linesep + "*** Missing template '%s'. Please enter absolute or relative path starting from '.' to the template file: " % mtmpl)
        usr_tmpl = os.path.normpath(usr_tmpl.strip())
        paths = make_template_paths(usr_tmpl, paths)
        return render_impl(usr_tmpl, ctx, paths, filters)

def try_render(filepath=None, content=None, **options):
    """Compile and render template and return the result as a string.

    :param filepath: Absolute or relative path to the template file
    :param content: Template content (str)
    :param options: Keyword options passed to :func:`render` defined above.
    :return: Compiled result (str) or None"""
    if filepath is None and content is None:
        raise ValueError("Either 'path' or 'content' must be some value!")
    tmpl_s = filepath or content[:10] + ' ...'
    LOGGER.debug('Compiling: %s', tmpl_s)
    try:
        if content is None:
            render_opts = anyconfig.utils.filter_options(RENDER_OPTS, options)
            return render(filepath, **render_opts)
        render_s_opts = anyconfig.utils.filter_options(RENDER_S_OPTS, options)
        return render_s(content, **render_s_opts)
    except Exception as exc:
        LOGGER.warning("Failed to compile '%s'. It may not be a template.%sexc=%r", tmpl_s, os.linesep, exc)
        return None

def _to_s(val, sep=', '):
    """Convert any to string.

    :param val: An object
    :param sep: separator between values

    >>> _to_s([1, 2, 3])
    '1, 2, 3'
    >>> _to_s("aaa")
    'aaa'"""
    if anyconfig.utils.is_iterable(val):
        return sep.join((str(x) for x in val))
    return str(val)

def _make_parser(**kwargs):
    """:return: (keyword args to be used, parser object)"""
    kwargs_0 = filter_options(('defaults', 'dict_type', 'allow_no_value'), kwargs)
    kwargs_1 = filter_options(('filename',), kwargs)
    try:
        parser = configparser.SafeConfigParser(**kwargs_0)
    except TypeError:
        kwargs_0 = filter_options(('defaults', 'dict_type'), kwargs)
        parser = configparser.SafeConfigParser(**kwargs_0)
    return (kwargs_1, parser)

def _dumps_itr(cnf, dkey=DEFAULTSECT):
    """:param cnf: Configuration data to dump"""
    for sect, params in iteritems(cnf):
        yield ('[%s]' % sect)
        for key, val in iteritems(params):
            if sect != dkey and dkey in cnf and (cnf[dkey].get(key) == val):
                continue
            yield ('%s = %s' % (key, _to_s(val)))
        yield ''

def _dumps(cnf, **kwargs):
    """:param cnf: Configuration data to dump
    :param kwargs: optional keyword parameters to be sanitized :: dict

    :return: String representation of 'cnf' object in INI format"""
    return os.linesep.join((l for l in _dumps_itr(cnf)))

def query(data, **options):
    """Filter data with given JMESPath expression.

    See also: https://github.com/jmespath/jmespath.py and http://jmespath.org.

    :param data: Target object (a dict or a dict-like object) to query
    :param options:
        Keyword option may include 'ac_query' which is a string represents
        JMESPath expression.

    :return: Maybe queried result data, primitive (int, str, ...) or dict"""
    expression = options.get('ac_query', None)
    if expression is None or not expression:
        return data
    try:
        pexp = jmespath.compile(expression)
        return pexp.search(data)
    except ValueError as exc:
        LOGGER.warning('Failed to compile or search: exp=%s, exc=%r', expression, exc)
    except (NameError, AttributeError):
        LOGGER.warning('Filter module (jmespath) is not available. Do nothing.')
    return data

def is_paths(maybe_paths, marker='*'):
    """Does given object 'maybe_paths' consist of path or path pattern strings?"""
    return is_path(maybe_paths) and marker in maybe_paths or (is_path_obj(maybe_paths) and marker in maybe_paths.as_posix()) or (is_iterable(maybe_paths) and all((is_path(p) or is_ioinfo(p) for p in maybe_paths)))

def get_path_from_stream(strm):
    """Try to get file path from given file or file-like object 'strm'.

    :param strm: A file or file-like object
    :return: Path of given file or file-like object or None
    :raises: ValueError

    >>> assert __file__ == get_path_from_stream(open(__file__, 'r'))
    >>> assert get_path_from_stream(anyconfig.compat.StringIO()) is None
    >>> get_path_from_stream(__file__)  # doctest: +ELLIPSIS
    Traceback (most recent call last):
        ...
    ValueError: ..."""
    if not is_file_stream(strm):
        raise ValueError('Given object does not look a file/file-like object: %r' % strm)
    path = getattr(strm, 'name', None)
    if path is not None:
        try:
            return normpath(path)
        except (TypeError, ValueError):
            pass
    return None

def _try_to_get_extension(obj):
    """Try to get file extension from given path or file object.

    :param obj: a file, file-like object or something
    :return: File extension or None

    >>> _try_to_get_extension("a.py")
    'py'"""
    if is_path(obj):
        path = obj
    elif is_path_obj(obj):
        return obj.suffix[1:]
    elif is_file_stream(obj):
        try:
            path = get_path_from_stream(obj)
        except ValueError:
            return None
    elif is_ioinfo(obj):
        path = obj.path
    else:
        return None
    if path:
        return get_file_extension(path)
    return None

def _expand_paths_itr(paths, marker='*'):
    """Iterator version of :func:`expand_paths`.
    """
    for path in paths:
        if is_path(path):
            if marker in path:
                for ppath in sglob(path):
                    yield ppath
            else:
                yield path
        elif is_path_obj(path):
            if marker in path.as_posix():
                for ppath in sglob(path.as_posix()):
                    yield normpath(ppath)
            else:
                yield normpath(path.as_posix())
        elif is_ioinfo(path):
            yield path.path
        else:
            yield path

def filter_options(keys, options):
    """Filter 'options' with given 'keys'.

    :param keys: key names of optional keyword arguments
    :param options: optional keyword arguments to filter with 'keys'

    >>> filter_options(("aaa", ), dict(aaa=1, bbb=2))
    {'aaa': 1}
    >>> filter_options(("aaa", ), dict(bbb=2))
    {}"""
    return dict(((k, options[k]) for k in keys if k in options))

def _try_validate(cnf, schema, **options):
    """:param cnf: Mapping object represents configuration data
    :param schema: JSON schema object
    :param options: Keyword options passed to :func:`jsonschema.validate`

    :return: Given 'cnf' as it is if validation succeeds else None"""
    valid = True
    if schema:
        valid, msg = validate(cnf, schema, **options)
        if msg:
            LOGGER.warning(msg)
    if valid:
        return cnf
    return None

def attr_val_itr(str_, avs_sep=':', vs_sep=',', as_sep=';'):
    """Atrribute and value pair parser.

    :param str_: String represents a list of pairs of attribute and value
    :param avs_sep: char to separate attribute and values
    :param vs_sep: char to separate values
    :param as_sep: char to separate attributes"""
    for rel in parse_list(str_, as_sep):
        if avs_sep not in rel or rel.endswith(avs_sep):
            continue
        _attr, _values = parse_list(rel, avs_sep)
        if vs_sep in str(_values):
            _values = parse_list(_values, vs_sep)
        if _values:
            yield (_attr, _values)

def parse(str_, lsep=',', avsep=':', vssep=',', avssep=';'):
    """Generic parser"""
    if avsep in str_:
        return parse_attrlist(str_, avsep, vssep, avssep)
    if lsep in str_:
        return parse_list(str_, lsep)
    return parse_single(str_)

def _parse_args(argv):
    """Show supported config format types or usage.

    :param argv: Argument list to parse or None (sys.argv will be set).
    :return: argparse.Namespace object or None (exit before return)"""
    parser = make_parser()
    args = parser.parse_args(argv)
    LOGGER.setLevel(to_log_level(args.loglevel))
    if args.inputs:
        if '-' in args.inputs:
            args.inputs = sys.stdin
    elif args.list:
        _show_psrs()
    elif args.env:
        cnf = os.environ.copy()
        _output_result(cnf, args.output, args.otype or 'json', None, None)
        sys.exit(0)
    else:
        parser.print_usage()
        sys.exit(1)
    if args.validate and args.schema is None:
        _exit_with_output('--validate option requires --scheme option', 1)
    return args

def _output_type_by_input_path(inpaths, itype, fmsg):
    """:param inpaths: List of input file paths
    :param itype: Input type or None
    :param fmsg: message if it cannot detect otype by 'inpath'
    :return: Output type :: str"""
    msg = 'Specify inpath and/or outpath type[s] with -I/--itype or -O/--otype option explicitly'
    if itype is None:
        try:
            otype = API.find(inpaths[0]).type()
        except API.UnknownFileTypeError:
            _exit_with_output(fmsg % inpaths[0] + msg, 1)
        except (ValueError, IndexError):
            _exit_with_output(msg, 1)
    else:
        otype = itype
    return otype

def _try_dump(cnf, outpath, otype, fmsg, extra_opts=None):
    """:param cnf: Configuration object to print out
    :param outpath: Output file path or None
    :param otype: Output type or None
    :param fmsg: message if it cannot detect otype by 'inpath'
    :param extra_opts: Map object will be given to API.dump as extra options"""
    if extra_opts is None:
        extra_opts = {}
    try:
        API.dump(cnf, outpath, otype, **extra_opts)
    except API.UnknownFileTypeError:
        _exit_with_output(fmsg % outpath, 1)
    except API.UnknownProcessorTypeError:
        _exit_with_output("Invalid output type '%s'" % otype, 1)

def _load_diff(args, extra_opts):
    """:param args: :class:`argparse.Namespace` object
    :param extra_opts: Map object given to API.load as extra options"""
    try:
        diff = API.load(args.inputs, args.itype, ac_ignore_missing=args.ignore_missing, ac_merge=args.merge, ac_template=args.template, ac_schema=args.schema, **extra_opts)
    except API.UnknownProcessorTypeError:
        _exit_with_output("Wrong input type '%s'" % args.itype, 1)
    except API.UnknownFileTypeError:
        _exit_with_output("No appropriate backend was found for given file '%s'" % args.itype, 1)
    _exit_if_load_failure(diff, 'Failed to load: args=%s' % ', '.join(args.inputs))
    return diff

def _do_filter(cnf, args):
    """:param cnf: Mapping object represents configuration data
    :param args: :class:`argparse.Namespace` object
    :return: 'cnf' may be updated"""
    if args.query:
        cnf = API.query(cnf, args.query)
    elif args.get:
        cnf = _do_get(cnf, args.get)
    elif args.set:
        key, val = args.set.split('=')
        API.set_(cnf, key, anyconfig.parser.parse(val))
    return cnf

def main(argv=None):
    """:param argv: Argument list to parse or None (sys.argv will be set)."""
    args = _parse_args((argv if argv else sys.argv)[1:])
    cnf = os.environ.copy() if args.env else {}
    extra_opts = dict()
    if args.extra_opts:
        extra_opts = anyconfig.parser.parse(args.extra_opts)
    diff = _load_diff(args, extra_opts)
    if cnf:
        API.merge(cnf, diff)
    else:
        cnf = diff
    if args.args:
        diff = anyconfig.parser.parse(args.args)
        API.merge(cnf, diff)
    if args.validate:
        _exit_with_output('Validation succeds')
    cnf = API.gen_schema(cnf) if args.gen_schema else _do_filter(cnf, args)
    _output_result(cnf, args.output, args.otype, args.inputs, args.itype, extra_opts=extra_opts)

def _validate(data, schema, ac_schema_safe=True, **options):
    """See the descritpion of :func:`validate` for more details of parameters and
    return value.

    Validate target object 'data' with given schema object."""
    try:
        jsonschema.validate(data, schema, **options)
    except (jsonschema.ValidationError, jsonschema.SchemaError, Exception) as exc:
        if ac_schema_safe:
            return (False, str(exc))
        raise
    return (True, '')

def gen_schema(data, **options):
    """Generate a node represents JSON schema object with type annotation added
    for given object node.

    :param data: Configuration data object (dict[-like] or namedtuple)
    :param options: Other keyword options such as:

        - ac_schema_strict: True if more strict (precise) schema is needed
        - ac_schema_typemap: Type to JSON schema type mappings

    :return: A dict represents JSON schema of this node"""
    if data is None:
        return dict(type='null')
    _type = type(data)
    if _type in _SIMPLE_TYPES:
        typemap = options.get('ac_schema_typemap', _SIMPLETYPE_MAP)
        scm = dict(type=typemap[_type])
    elif anyconfig.utils.is_dict_like(data):
        scm = object_to_schema(data, **options)
    elif anyconfig.utils.is_list_like(data):
        scm = array_to_schema(data, **options)
    return scm

def to_method(func):
    """Lift :func:`func` to a method; it will be called with the first argument
    'self' ignored.

    :param func: Any callable object"""
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        """Wrapper function.
        """
        return func(*args[1:], **kwargs)
    return wrapper

def dump_with_fn(dump_fn, data, stream, **options):
    """Dump 'data' to a string if 'stream' is None, or dump 'data' to a file or
    file-like object 'stream'.

    :param dump_fn: Callable to dump data
    :param data: Data to dump
    :param stream:  File or file like object or None
    :param options: optional keyword parameters

    :return: String represents data if stream is None or None"""
    if stream is None:
        return dump_fn(data, **options)
    return dump_fn(data, stream, **options)

def inspect_io_obj(obj):
    """:param obj: a path string, a pathlib.Path or a file / file-like object

    :return: A tuple of (objtype, objpath, objopener)
    :raises: UnknownFileTypeError"""
    itype = guess_io_type(obj)
    if itype == IOI_PATH_STR:
        ipath = anyconfig.utils.normpath(obj)
        ext = anyconfig.utils.get_file_extension(ipath)
        opener = open
    elif itype == IOI_PATH_OBJ:
        ipath = anyconfig.utils.normpath(obj.as_posix())
        ext = anyconfig.utils.get_file_extension(ipath)
        opener = obj.open
    elif itype == IOI_STREAM:
        ipath = anyconfig.utils.get_path_from_stream(obj)
        ext = anyconfig.utils.get_file_extension(ipath) if ipath else None
        opener = anyconfig.utils.noop
    elif itype == IOI_NONE:
        ipath = ext = None
        opener = anyconfig.utils.noop
    else:
        raise UnknownFileTypeError('%r' % obj)
    return (itype, ipath, opener, ext)

def make(obj):
    """:param obj: a path string, a pathlib.Path or a file / file-like object
    :return:
        Namedtuple object represents a kind of input object such as a file /
        file-like object, path string or pathlib.Path object

    :raises: ValueError, UnknownProcessorTypeError, UnknownFileTypeError"""
    if anyconfig.utils.is_ioinfo(obj):
        return obj
    itype, ipath, opener, ext = inspect_io_obj(obj)
    return IOInfo(src=obj, type=itype, path=ipath, opener=opener, extension=ext)

def total_results(data: Union[List[JSONRPCResponse], JSONRPCResponse, None], *, ok: bool=True) -> int:
    """Returns the total parsed responses, given the return value from parse()."""
    if isinstance(data, list):
        return sum([1 for d in data if d.ok == ok])
    elif isinstance(data, JSONRPCResponse):
        return int(data.ok == ok)
    return 0

def get_response(response: Dict[str, Any]) -> JSONRPCResponse:
    """Converts a deserialized response into a JSONRPCResponse object.

    The dictionary be either an error or success response, never a notification.

    Args:
        response: Deserialized response dictionary. We can assume the response is valid
            JSON-RPC here, since it passed the jsonschema validation."""
    if 'error' in response:
        return ErrorResponse(**response)
    return SuccessResponse(**response)

def parse(response_text: str, *, batch: bool, validate_against_schema: bool=True) -> Union[JSONRPCResponse, List[JSONRPCResponse]]:
    """Parses response text, returning JSONRPCResponse objects.

    Args:
        response_text: JSON-RPC response string.
        batch: If the response_text is an empty string, this determines how to parse.
        validate_against_schema: Validate against the json-rpc schema.

    Returns:
        Either a JSONRPCResponse, or a list of them.

    Raises:
        json.JSONDecodeError: The response was not valid JSON.
        jsonschema.ValidationError: The response was not a valid JSON-RPC response
            object."""
    if not response_text:
        if batch:
            return []
        else:
            return NotificationResponse()
    deserialized = deserialize(response_text)
    if validate_against_schema:
        jsonschema.validate(deserialized, schema)
    if isinstance(deserialized, list):
        return [get_response(r) for r in deserialized if 'id' in r]
    return get_response(deserialized)

def main(context: click.core.Context, method: str, request_type: str, id: Any, send: str) -> None:
    """Create a JSON-RPC request."""
    exit_status = 0
    positional = [a for a in context.args if '=' not in a]
    named = {a.split('=')[0]: a.split('=')[1] for a in context.args if '=' in a}
    if request_type == 'notify':
        req = Notification(method, *positional, **named)
    else:
        req = Request(method, *positional, request_id=id, **named)
    if send:
        client = HTTPClient(send)
        try:
            response = client.send(req)
        except JsonRpcClientError as e:
            click.echo(str(e), err=True)
            exit_status = 1
        else:
            click.echo(response.text)
    else:
        click.echo(str(req))
    sys.exit(exit_status)

def log_(message: str, logger: logging.Logger, level: str='info', extra: Optional[Dict]=None, trim: bool=False) -> None:
    """Log a request or response

    Args:
        message: JSON-RPC request or response string.
        level: Log level.
        extra: More details to include in the log entry.
        trim: Abbreviate log messages."""
    if extra is None:
        extra = {}
    if message:
        message = message.replace('\n', '').replace('  ', ' ').replace('{ ', '{')
    if trim:
        message = _trim_message(message)
    getattr(logger, level)(message, extra=extra)

def load(fp, base_uri='', loader=None, jsonschema=False, load_on_repr=True, **kwargs):
    """Drop in replacement for :func:`json.load`, where JSON references are
    proxied to their referent data.

    :param fp: File-like object containing JSON document
    :param kwargs: This function takes any of the keyword arguments from
        :meth:`JsonRef.replace_refs`. Any other keyword arguments will be passed to
        :func:`json.load`"""
    if loader is None:
        loader = functools.partial(jsonloader, **kwargs)
    return JsonRef.replace_refs(json.load(fp, **kwargs), base_uri=base_uri, loader=loader, jsonschema=jsonschema, load_on_repr=load_on_repr)

def loads(s, base_uri='', loader=None, jsonschema=False, load_on_repr=True, **kwargs):
    """Drop in replacement for :func:`json.loads`, where JSON references are
    proxied to their referent data.

    :param s: String containing JSON document
    :param kwargs: This function takes any of the keyword arguments from
        :meth:`JsonRef.replace_refs`. Any other keyword arguments will be passed to
        :func:`json.loads`"""
    if loader is None:
        loader = functools.partial(jsonloader, **kwargs)
    return JsonRef.replace_refs(json.loads(s, **kwargs), base_uri=base_uri, loader=loader, jsonschema=jsonschema, load_on_repr=load_on_repr)

def load_uri(uri, base_uri=None, loader=None, jsonschema=False, load_on_repr=True):
    """Load JSON data from ``uri`` with JSON references proxied to their referent
    data.

    :param uri: URI to fetch the JSON from
    :param kwargs: This function takes any of the keyword arguments from
        :meth:`JsonRef.replace_refs`"""
    if loader is None:
        loader = jsonloader
    if base_uri is None:
        base_uri = uri
    return JsonRef.replace_refs(loader(uri), base_uri=base_uri, loader=loader, jsonschema=jsonschema, load_on_repr=load_on_repr)

def dumpb(obj, container_count=False, sort_keys=False, no_float32=True, default=None):
    """Returns the given object as UBJSON in a bytes instance. See dump() for
    available arguments."""
    with BytesIO() as fp:
        dump(obj, fp, container_count=container_count, sort_keys=sort_keys, no_float32=no_float32, default=default)
        return fp.getvalue()

def _resolve_version(version):
    """Resolve LATEST version"""
    if version is not LATEST:
        return version
    resp = urlopen('https://pypi.python.org/pypi/setuptools/json')
    with contextlib.closing(resp):
        try:
            charset = resp.info().get_content_charset()
        except Exception:
            charset = 'UTF-8'
        reader = codecs.getreader(charset)
        doc = json.load(reader(resp))
    return str(doc['info']['version'])

def loadb(chars, no_bytes=False, object_hook=None, object_pairs_hook=None, intern_object_keys=False):
    """Decodes and returns UBJSON from the given bytes or bytesarray object. See
    load() for available arguments."""
    with BytesIO(chars) as fp:
        return load(fp, no_bytes=no_bytes, object_hook=object_hook, object_pairs_hook=object_pairs_hook, intern_object_keys=intern_object_keys)

def load_config(path):
    """Loads configuration from a path.

    Path can be a json file, or a directory containing config.json
    and zero or more *.txt files with word lists or phrase lists.

    Returns config dict.

    Raises InitializationError when something is wrong."""
    path = os.path.abspath(path)
    if os.path.isdir(path):
        config, wordlists = _load_data(path)
    elif os.path.isfile(path):
        config = _load_config(path)
        wordlists = {}
    else:
        raise InitializationError('File or directory not found: {0}'.format(path))
    for name, wordlist in wordlists.items():
        if name in config:
            raise InitializationError("Conflict: list {!r} is defined both in config and in *.txt file. If it's a {!r} list, you should remove it from config.".format(name, _CONF.TYPE.WORDS))
        config[name] = wordlist
    return config

def _load_data(path):
    """Loads data from a directory.
    Returns tuple (config_dict, wordlists).
    Raises Exception on failure (e.g. if data is corrupted)."""
    path = os.path.abspath(path)
    if not os.path.isdir(path):
        raise InitializationError('Directory not found: {0}'.format(path))
    wordlists = {}
    for file_name in os.listdir(path):
        if os.path.splitext(file_name)[1] != '.txt':
            continue
        file_path = os.path.join(path, file_name)
        name = os.path.splitext(os.path.split(file_path)[1])[0]
        try:
            with codecs.open(file_path, encoding='utf-8') as file:
                wordlists[name] = _load_wordlist(name, file)
        except OSError as ex:
            raise InitializationError('Failed to read {}: {}'.format(file_path, ex))
    config = _load_config(os.path.join(path, 'config.json'))
    return (config, wordlists)

def _parse_option(line):
    """Parses option line.
    Returns (name, value).
    Raises ValueError on invalid syntax or unknown option."""
    match = _OPTION_REGEX.match(line)
    if not match:
        raise ValueError('Invalid syntax')
    for name, type_ in _OPTIONS:
        if name == match.group(1):
            return (name, type_(match.group(2)))
    raise ValueError('Unknown option')

def prioritized_mux(selects, vals):
    """Returns the value in the first wire for which its select bit is 1

    :param [WireVector] selects: a list of WireVectors signaling whether
        a wire should be chosen
    :param [WireVector] vals: values to return when the corresponding select
        value is 1
    :return: WireVector

    If none of the items are high, the last val is returned"""
    if len(selects) != len(vals):
        raise pyrtl.PyrtlError('Number of select and val signals must match')
    if len(vals) == 0:
        raise pyrtl.PyrtlError('Must have a signal to mux')
    if len(vals) == 1:
        return vals[0]
    else:
        half = len(vals) // 2
        return pyrtl.select(pyrtl.rtl_any(*selects[:half]), truecase=prioritized_mux(selects[:half], vals[:half]), falsecase=prioritized_mux(selects[half:], vals[half:]))

def sparse_mux(sel, vals):
    """Mux that avoids instantiating unnecessary mux_2s when possible.

    :param WireVector sel: Select wire, determines what is selected on a given cycle
    :param dictionary vals: dictionary of values at mux inputs (of type `{int:WireVector}`)
    :return: WireVector that signifies the change

    This mux supports not having a full specification. Indices that are not
    specified are treated as don't-cares

    It also supports a specified default value, SparseDefault"""
    import numbers
    max_val = 2 ** len(sel) - 1
    if SparseDefault in vals:
        default_val = vals[SparseDefault]
        del vals[SparseDefault]
        for i in range(max_val + 1):
            if i not in vals:
                vals[i] = default_val
    for key in vals.keys():
        if not isinstance(key, numbers.Integral):
            raise pyrtl.PyrtlError("value %s nust be either an integer or 'default'" % str(key))
        if key < 0 or key > max_val:
            raise pyrtl.PyrtlError('value %s is out of range of the sel wire' % str(key))
    return _sparse_mux(sel, vals)

def log_middleware(store):
    """log all actions to console as they are dispatched"""
    def wrapper(next_):
        def log_dispatch(action):
            print('Dispatch Action:', action)
            return next_(action)
        return log_dispatch
    return wrapper

def _trivial_mult(A, B):
    """turns a multiplication into an And gate if one of the
    wires is a bitwidth of 1

    :param A:
    :param B:
    :return:"""
    if len(B) == 1:
        A, B = (B, A)
    if len(A) == 1:
        a_vals = A.sign_extended(len(B))
        return pyrtl.concat_list([a_vals & B, pyrtl.Const(0)])

def _one_cycle_mult(areg, breg, rem_bits, sum_sf=0, curr_bit=0):
    """returns a WireVector sum of rem_bits multiplies (in one clock cycle)
    note: this method requires a lot of area because of the indexing in the else statement"""
    if rem_bits == 0:
        return sum_sf
    else:
        a_curr_val = areg[curr_bit].sign_extended(len(breg))
        if curr_bit == 0:
            return _one_cycle_mult(areg, breg, rem_bits - 1, sum_sf + (a_curr_val & breg), curr_bit + 1)
        else:
            return _one_cycle_mult(areg, breg, rem_bits - 1, sum_sf + (a_curr_val & pyrtl.concat(breg, pyrtl.Const(0, curr_bit))), curr_bit + 1)

def signed_tree_multiplier(A, B, reducer=adders.wallace_reducer, adder_func=adders.kogge_stone):
    """Same as tree_multiplier, but uses two's-complement signed integers"""
    if len(A) == 1 or len(B) == 1:
        raise pyrtl.PyrtlError('sign bit required, one or both wires too small')
    aneg, bneg = (A[-1], B[-1])
    a = _twos_comp_conditional(A, aneg)
    b = _twos_comp_conditional(B, bneg)
    res = tree_multiplier(a[:-1], b[:-1]).zero_extended(len(A) + len(B))
    return _twos_comp_conditional(res, aneg ^ bneg)

def all_nets(transform_func):
    """Decorator that wraps a net transform function"""
    @functools.wraps(transform_func)
    def t_res(**kwargs):
        net_transform(transform_func, **kwargs)
    return t_res

def all_wires(transform_func):
    """Decorator that wraps a wire transform function"""
    @functools.wraps(transform_func)
    def t_res(**kwargs):
        wire_transform(transform_func, **kwargs)
    return t_res

def clone_wire(old_wire, name=None):
    """Makes a copy of any existing wire

    :param old_wire: The wire to clone
    :param name: a name fo rhte new wire

    Note that this function is mainly intended to be used when the
    two wires are from different blocks. Making two wires with the
    same name in the same block is not allowed"""
    if isinstance(old_wire, Const):
        return Const(old_wire.val, old_wire.bitwidth)
    else:
        if name is None:
            return old_wire.__class__(old_wire.bitwidth, name=old_wire.name)
        return old_wire.__class__(old_wire.bitwidth, name=name)

def copy_block(block=None, update_working_block=True):
    """Makes a copy of an existing block

    :param block: The block to clone. (defaults to the working block)
    :return: The resulting block"""
    block_in = working_block(block)
    block_out, temp_wv_map = _clone_block_and_wires(block_in)
    mems = {}
    for net in block_in.logic:
        _copy_net(block_out, net, temp_wv_map, mems)
    block_out.mem_map = mems
    if update_working_block:
        set_working_block(block_out)
    return block_out

def _get_new_block_mem_instance(op_param, mem_map, block_out):
    """gets the instance of the memory in the new block that is
    associated with a memory in a old block"""
    memid, old_mem = op_param
    if old_mem not in mem_map:
        new_mem = old_mem._make_copy(block_out)
        new_mem.id = old_mem.id
        mem_map[old_mem] = new_mem
    return (memid, mem_map[old_mem])

def check_rtl_assertions(sim):
    """Checks the values in sim to see if any registers assertions fail.

    :param sim: Simulation in which to check the assertions
    :return: None"""
    for w, exp in sim.block.rtl_assert_dict.items():
        try:
            value = sim.inspect(w)
            if not value:
                raise exp
        except KeyError:
            pass

def cla_adder(a, b, cin=0, la_unit_len=4):
    """Carry Lookahead Adder
    :param int la_unit_len: the length of input that every unit processes

    A Carry LookAhead Adder is an adder that is faster than
    a ripple carry adder, as it calculates the carry bits faster.
    It is not as fast as a Kogge-Stone adder, but uses less area."""
    a, b = pyrtl.match_bitwidth(a, b)
    if len(a) <= la_unit_len:
        sum, cout = _cla_adder_unit(a, b, cin)
        return pyrtl.concat(cout, sum)
    else:
        sum, cout = _cla_adder_unit(a[0:la_unit_len], b[0:la_unit_len], cin)
        msbits = cla_adder(a[la_unit_len:], b[la_unit_len:], cout, la_unit_len)
        return pyrtl.concat(msbits, sum)

def _trivialgraph_default_namer(thing, is_edge=True):
    """Returns a "good" string for thing in printed graphs."""
    if is_edge:
        if thing.name is None or thing.name.startswith('tmp'):
            return ''
        else:
            return '/'.join([thing.name, str(len(thing))])
    elif isinstance(thing, Const):
        return str(thing.val)
    elif isinstance(thing, WireVector):
        return thing.name or '??'
    else:
        try:
            return thing.op + str(thing.op_param or '')
        except AttributeError:
            raise PyrtlError('no naming rule for "%s"' % str(thing))

def output_to_trivialgraph(file, namer=_trivialgraph_default_namer, block=None):
    """Walk the block and output it in trivial graph format to the open file."""
    graph = net_graph(block)
    node_index_map = {}
    for index, node in enumerate(graph):
        print('%d %s' % (index, namer(node, is_edge=False)), file=file)
        node_index_map[node] = index
    print('#', file=file)
    for _from in graph:
        for _to in graph[_from]:
            from_index = node_index_map[_from]
            to_index = node_index_map[_to]
            edge = graph[_from][_to]
            print('%d %d %s' % (from_index, to_index, namer(edge)), file=file)

def output_to_graphviz(file, namer=_graphviz_default_namer, block=None):
    """Walk the block and output it in graphviz format to the open file."""
    print(block_to_graphviz_string(block, namer), file=file)

def block_to_svg(block=None):
    """Return an SVG for the block."""
    block = working_block(block)
    try:
        from graphviz import Source
        return Source(block_to_graphviz_string())._repr_svg_()
    except ImportError:
        raise PyrtlError('need graphviz installed (try "pip install graphviz")')

def twos_comp_repr(val, bitwidth):
    """Converts a value to it's two's-complement (positive) integer representation using a
    given bitwidth (only converts the value if it is negative).
    For use with Simulation.step() etc. in passing negative numbers, which it does not accept"""
    correctbw = abs(val).bit_length() + 1
    if bitwidth < correctbw:
        raise pyrtl.PyrtlError('please choose a larger target bitwidth')
    if val >= 0:
        return val
    else:
        return (~abs(val) & 2 ** bitwidth - 1) + 1

def rev_twos_comp_repr(val, bitwidth):
    """Takes a two's-complement represented value and
    converts it to a signed integer based on the provided bitwidth.
    For use with Simulation.inspect() etc. when expecting negative numbers,
    which it does not recognize"""
    valbl = val.bit_length()
    if bitwidth < val.bit_length() or val == 2 ** (bitwidth - 1):
        raise pyrtl.PyrtlError('please choose a larger target bitwidth')
    if bitwidth == valbl:
        return -((~val & 2 ** bitwidth - 1) + 1)
    else:
        return val

def _shifted_reg_next(reg, direct, num=1):
    """Creates a shifted 'next' property for shifted (left or right) register.

    Use: `myReg.next = shifted_reg_next(myReg, 'l', 4)`

    :param string direct: direction of shift, either 'l' or 'r'
    :param int num: number of shifts
    :return: Register containing reg's (shifted) next state"""
    if direct == 'l':
        if num >= len(reg):
            return 0
        else:
            return pyrtl.concat(reg, pyrtl.Const(0, num))
    elif direct == 'r':
        if num >= len(reg):
            return 0
        else:
            return reg[num:]
    else:
        raise pyrtl.PyrtlError("direction must be specified with 'direct'parameter as either 'l' or 'r'")

def _remove_wire_nets(block):
    """Remove all wire nodes from the block."""
    wire_src_dict = _ProducerList()
    wire_removal_set = set()
    for net in block.logic:
        if net.op == 'w':
            wire_src_dict[net.dests[0]] = net.args[0]
            if not isinstance(net.dests[0], Output):
                wire_removal_set.add(net.dests[0])
    new_logic = set()
    for net in block.logic:
        if net.op != 'w' or isinstance(net.dests[0], Output):
            new_args = tuple((wire_src_dict.find_producer(x) for x in net.args))
            new_net = LogicNet(net.op, net.op_param, new_args, net.dests)
            new_logic.add(new_net)
    block.logic = new_logic
    for dead_wirevector in wire_removal_set:
        del block.wirevector_by_name[dead_wirevector.name]
        block.wirevector_set.remove(dead_wirevector)
    block.sanity_check()

def _remove_unlistened_nets(block):
    """Removes all nets that are not connected to an output wirevector
    """
    listened_nets = set()
    listened_wires = set()
    prev_listened_net_count = 0
    def add_to_listened(net):
        listened_nets.add(net)
        listened_wires.update(net.args)
    for a_net in block.logic:
        if a_net.op == '@':
            add_to_listened(a_net)
        elif any((isinstance(destW, Output) for destW in a_net.dests)):
            add_to_listened(a_net)
    while len(listened_nets) > prev_listened_net_count:
        prev_listened_net_count = len(listened_nets)
        for net in block.logic - listened_nets:
            if any((destWire in listened_wires for destWire in net.dests)):
                add_to_listened(net)
    block.logic = listened_nets
    _remove_unused_wires(block)

def _remove_unused_wires(block, keep_inputs=True):
    """Removes all unconnected wires from a block"""
    valid_wires = set()
    for logic_net in block.logic:
        valid_wires.update(logic_net.args, logic_net.dests)
    wire_removal_set = block.wirevector_set.difference(valid_wires)
    for removed_wire in wire_removal_set:
        if isinstance(removed_wire, Input):
            term = ' optimized away'
            if keep_inputs:
                valid_wires.add(removed_wire)
                term = ' deemed useless by optimization'
            print('Input Wire, ' + removed_wire.name + ' has been' + term)
        if isinstance(removed_wire, Output):
            PyrtlInternalError('Output wire, ' + removed_wire.name + ' not driven')
    block.wirevector_set = valid_wires

def nand_synth(net):
    """Synthesizes an Post-Synthesis block into one consisting of nands and inverters in place
    :param block: The block to synthesize."""
    if net.op in '~nrwcsm@':
        return True
    def arg(num):
        return net.args[num]
    dest = net.dests[0]
    if net.op == '&':
        dest <<= ~arg(0).nand(arg(1))
    elif net.op == '|':
        dest <<= (~arg(0)).nand(~arg(1))
    elif net.op == '^':
        temp_0 = arg(0).nand(arg(1))
        dest <<= temp_0.nand(arg(0)).nand(temp_0.nand(arg(1)))
    else:
        raise PyrtlError("Op, '{}' is not supported in nand_synth".format(net.op))

def and_inverter_synth(net):
    """Transforms a decomposed block into one consisting of ands and inverters in place
    :param block: The block to synthesize"""
    if net.op in '~&rwcsm@':
        return True
    def arg(num):
        return net.args[num]
    dest = net.dests[0]
    if net.op == '|':
        dest <<= ~(~arg(0) & ~arg(1))
    elif net.op == '^':
        all_1 = arg(0) & arg(1)
        all_0 = ~arg(0) & ~arg(1)
        dest <<= all_0 & ~all_1
    elif net.op == 'n':
        dest <<= ~(arg(0) & arg(1))
    else:
        raise PyrtlError("Op, '{}' is not supported in and_inv_synth".format(net.op))

def combine_reducers(reducers):
    """composition tool for creating reducer trees.

    Args:
        reducers: dict with state keys and reducer functions
                  that are responsible for each key

    Returns:
        a new, combined reducer function"""
    final_reducers = {key: reducer for key, reducer in reducers.items() if hasattr(reducer, '__call__')}
    sanity_error = None
    try:
        assert_reducer_sanity(final_reducers)
    except Exception as e:
        sanity_error = e
    def combination(state=None, action=None):
        if state is None:
            state = {}
        if sanity_error:
            raise sanity_error
        has_changed = False
        next_state = {}
        for key, reducer in final_reducers.items():
            previous_state_for_key = state.get(key)
            next_state_for_key = reducer(previous_state_for_key, action)
            if next_state_for_key is None:
                msg = get_undefined_state_error_message(key, action)
                raise Exception(msg)
            next_state[key] = next_state_for_key
            has_changed = has_changed or next_state_for_key != previous_state_for_key
        return next_state if has_changed else state
    return combination

def apply_middleware(*middlewares):
    """creates an enhancer function composed of middleware

    Args:
        *middlewares: list of middleware functions to apply

    Returns:
        an enhancer for subsequent calls to create_store()"""
    def inner(create_store_):
        def create_wrapper(reducer, enhancer=None):
            store = create_store_(reducer, enhancer)
            dispatch = store['dispatch']
            middleware_api = {'get_state': store['get_state'], 'dispatch': lambda action: dispatch(action)}
            chain = [mw(middleware_api) for mw in middlewares]
            dispatch = compose(*chain)(store['dispatch'])
            return extend(store, {'dispatch': dispatch})
        return create_wrapper
    return inner

def signed_le(a, b):
    """Return a single bit result of signed less than or equal comparison."""
    a, b = match_bitwidth(as_wires(a), as_wires(b), signed=True)
    r = a - b
    return r[-1] ^ ~a[-1] ^ ~b[-1] | (a == b)

def signed_ge(a, b):
    """Return a single bit result of signed greater than or equal comparison."""
    a, b = match_bitwidth(as_wires(a), as_wires(b), signed=True)
    r = b - a
    return r[-1] ^ ~a[-1] ^ ~b[-1] | (a == b)

def match_bitwidth(*args, **opt):
    """Matches the bitwidth of all of the input arguments with zero or sign extend

    :param args: WireVectors of which to match bitwidths
    :param opt: Optional keyword argument 'signed=True' (defaults to False)
    :return: tuple of args in order with extended bits

    Example of matching the bitwidths of two WireVectors `a` and `b` with
    with zero extention: ::

        a,b = match_bitwidth(a, b)

    Example of matching the bitwidths of three WireVectors `a`,`b`, and `c` with
    with sign extention: ::

        a,b = match_bitwidth(a, b, c, signed=True)"""
    if len(opt) == 0:
        signed = False
    else:
        if len(opt) > 1 or 'signed' not in opt:
            raise PyrtlError('error, only supported kwarg to match_bitwidth is "signed"')
        signed = bool(opt['signed'])
    max_len = max((len(wv) for wv in args))
    if signed:
        return (wv.sign_extended(max_len) for wv in args)
    else:
        return (wv.zero_extended(max_len) for wv in args)

def rtl_any(*vectorlist):
    """Hardware equivalent of python native "any".

    :param WireVector vectorlist: all arguments are WireVectors of length 1
    :return: WireVector of length 1

    Returns a 1-bit WireVector which will hold a '1' if any of the inputs
    are '1' (i.e. it is a big ol' OR gate)"""
    if len(vectorlist) <= 0:
        raise PyrtlError('rtl_any requires at least 1 argument')
    converted_vectorlist = [as_wires(v) for v in vectorlist]
    if any((len(v) != 1 for v in converted_vectorlist)):
        raise PyrtlError('only length 1 WireVectors can be inputs to rtl_any')
    return or_all_bits(concat_list(converted_vectorlist))

def rtl_all(*vectorlist):
    """Hardware equivalent of python native "all".

    :param WireVector vectorlist: all arguments are WireVectors of length 1
    :return: WireVector of length 1

    Returns a 1-bit WireVector which will hold a '1' only if all of the
    inputs are '1' (i.e. it is a big ol' AND gate)"""
    if len(vectorlist) <= 0:
        raise PyrtlError('rtl_all requires at least 1 argument')
    converted_vectorlist = [as_wires(v) for v in vectorlist]
    if any((len(v) != 1 for v in converted_vectorlist)):
        raise PyrtlError('only length 1 WireVectors can be inputs to rtl_all')
    return and_all_bits(concat_list(converted_vectorlist))

def _basic_mult(A, B):
    """A stripped-down copy of the Wallace multiplier in rtllib"""
    if len(B) == 1:
        A, B = (B, A)
    if len(A) == 1:
        return concat_list(list((A & b for b in B)) + [Const(0)])
    result_bitwidth = len(A) + len(B)
    bits = [[] for weight in range(result_bitwidth)]
    for i, a in enumerate(A):
        for j, b in enumerate(B):
            bits[i + j].append(a & b)
    while not all((len(i) <= 2 for i in bits)):
        deferred = [[] for weight in range(result_bitwidth + 1)]
        for i, w_array in enumerate(bits):
            while len(w_array) >= 3:
                a, b, cin = (w_array.pop(0) for j in range(3))
                deferred[i].append(a ^ b ^ cin)
                deferred[i + 1].append(a & b | a & cin | b & cin)
            if len(w_array) == 2:
                a, b = w_array
                deferred[i].append(a ^ b)
                deferred[i + 1].append(a & b)
            else:
                deferred[i].extend(w_array)
        bits = deferred[:result_bitwidth]
    import six
    add_wires = tuple(six.moves.zip_longest(*bits, fillvalue=Const(0)))
    adder_result = concat_list(add_wires[0]) + concat_list(add_wires[1])
    return adder_result[:result_bitwidth]

def _pred_sets_are_in_conflict(pred_set_a, pred_set_b):
    """Find conflict in sets, return conflict if found, else None."""
    for pred_a, bool_a in pred_set_a:
        for pred_b, bool_b in pred_set_b:
            if pred_a is pred_b and bool_a != bool_b:
                return False
    return True

def _finalize():
    """Build the required muxes and call back to WireVector to finalize the wirevector build."""
    from .memory import MemBlock
    from pyrtl.corecircuits import select
    for lhs in _predicate_map:
        if isinstance(lhs, MemBlock):
            p, (addr, data, enable) = _predicate_map[lhs][0]
            combined_enable = select(p, truecase=enable, falsecase=Const(0))
            combined_addr = addr
            combined_data = data
            for p, (addr, data, enable) in _predicate_map[lhs][1:]:
                combined_enable = select(p, truecase=enable, falsecase=combined_enable)
                combined_addr = select(p, truecase=addr, falsecase=combined_addr)
                combined_data = select(p, truecase=data, falsecase=combined_data)
            lhs._build(combined_addr, combined_data, combined_enable)
        else:
            if isinstance(lhs, Register):
                result = lhs
            elif isinstance(lhs, WireVector):
                result = 0
            else:
                raise PyrtlInternalError('unknown assignment in finalize')
            predlist = _predicate_map[lhs]
            for p, rhs in predlist:
                result = select(p, truecase=rhs, falsecase=result)
            lhs._build(result)

def _current_select():
    """Function to calculate the current "predicate" in the current context.

    Returns a tuple of information: (predicate, pred_set).
    The value pred_set is a set([ (predicate, bool), ... ]) as described in
    the _reset_conditional_state"""
    def and_with_possible_none(a, b):
        assert a is not None or b is not None
        if a is None:
            return b
        if b is None:
            return a
        return a & b
    def between_otherwise_and_current(predlist):
        lastother = None
        for i, p in enumerate(predlist[:-1]):
            if p is otherwise:
                lastother = i
        if lastother is None:
            return predlist[:-1]
        else:
            return predlist[lastother + 1:-1]
    select = None
    pred_set = set()
    for predlist in _conditions_list_stack[:-1]:
        for predicate in between_otherwise_and_current(predlist):
            select = and_with_possible_none(select, ~predicate)
            pred_set.add((predicate, True))
        if predlist[-1] is not otherwise:
            predicate = predlist[-1]
            select = and_with_possible_none(select, predicate)
            pred_set.add((predicate, False))
    if select is None:
        raise PyrtlError('problem with conditional assignment')
    if len(select) != 1:
        raise PyrtlInternalError('conditional predicate with length greater than 1')
    return (select, pred_set)

def _bits_ports_and_isrom_from_memory(mem):
    """Helper to extract mem bits and ports for estimation."""
    is_rom = False
    bits = 2 ** mem.addrwidth * mem.bitwidth
    read_ports = len(mem.readport_nets)
    try:
        write_ports = len(mem.writeport_nets)
    except AttributeError:
        if not isinstance(mem, RomBlock):
            raise PyrtlInternalError('Mem with no writeport_nets attribute but not a ROM? Thats an error')
        write_ports = 0
        is_rom = True
    ports = max(read_ports, write_ports)
    return (bits, ports, is_rom)

def ansi_len(string):
