def clean_response(response):
    '''Recurse through dictionary and replace any keys "self" with
    "self_"'''
    if type(response) is list:
        for elem in response:
            clean_response(elem)
    elif type(response) is dict:
        for key, val in response.items():
            if key == 'self':
                val = response.pop('self')
                response['self_'] = val
                clean_response(val)
            else:
                clean_response(response[key])
    return response

def _lower(string):
    """Custom lower string function.
    Examples:
        FooBar -> foo_bar"""
    if not string:
        return ''
    new_string = [string[0].lower()]
    for char in string[1:]:
        if char.isupper():
            new_string.append('_')
        new_string.append(char.lower())
    return ''.join(new_string)

def check_dataset(dataset):
    """Confirm shape (3 colors x rows x cols) and values [0 to 255] are OK."""
    if isinstance(dataset, numpy.ndarray) and (not len(dataset.shape) == 4):
        check_dataset_shape(dataset)
        check_dataset_range(dataset)
    else:
        for i, d in enumerate(dataset):
            if not isinstance(d, numpy.ndarray):
                raise ValueError('Requires a NumPy array (rgb x rows x cols) with integer values in the range [0, 255].')
            try:
                check_dataset_shape(d)
                check_dataset_range(d)
            except ValueError as err:
                raise ValueError('{}\nAt position {} in the list of arrays.'.format(err, i))

def try_fix_dataset(dataset):
    """Transpose the image data if it's in PIL format."""
    if isinstance(dataset, numpy.ndarray):
        if len(dataset.shape) == 3:
            if dataset.shape[-1] == 3:
                return dataset.transpose((2, 0, 1))
        elif len(dataset.shape) == 4:
            if dataset.shape[-1] == 3:
                return dataset.transpose((0, 3, 1, 2))
        return dataset
    for i, d in enumerate(dataset):
        if not isinstance(d, numpy.ndarray):
            return dataset
        if not (len(d.shape) == 3 and d.shape[-1] == 3):
            return dataset
        dataset[i] = d.transpose()
    return dataset

def add_pref_suff(pref_suff_map):
    """Decorator adds visit, depart methods for prefix/suffix pairs
    """
    def dec(cls):
        for key, (prefix, suffix) in pref_suff_map.items():
            setattr(cls, 'visit_' + key, _make_method(prefix))
            setattr(cls, 'depart_' + key, _make_method(suffix))
        return cls
    return dec

def add_pass_thru(pass_thrus):
    """Decorator adds explicit pass-through visit and depart methods
    """
    def meth(self, node):
        pass
    def dec(cls):
        for element_name in pass_thrus:
            for meth_prefix in ('visit_', 'depart_'):
                meth_name = meth_prefix + element_name
                if hasattr(cls, meth_name):
                    raise ValueError('method name {} already defined'.format(meth_name))
                setattr(cls, meth_name, meth)
        return cls
    return dec

def _load(content_or_fp):
    """YAML Parse a file or str and check version.
    """
    try:
        data = yaml.load(content_or_fp, Loader=yaml.loader.BaseLoader)
    except Exception as e:
        raise type(e)('Malformed yaml file:\n%r' % format_exc())
    try:
        ver = data['spec']
    except:
        raise ValueError('The file does not specify a spec version')
    try:
        ver = tuple(map(int, ver.split('.')))
    except:
        raise ValueError("Invalid spec version format. Expect 'X.Y' (X and Y integers), found %s" % ver)
    if ver > SPEC_VERSION_TUPLE:
        raise ValueError('The spec version of the file is %s but the parser is %s. Please update pyvisa-sim.' % (ver, SPEC_VERSION))
    return data

def parse_resource(name):
    """Parse a resource file
    """
    with closing(pkg_resources.resource_stream(__name__, name)) as fp:
        rbytes = fp.read()
    return _load(StringIO(rbytes.decode('utf-8')))

def update_component(name, comp, component_dict):
    """Get a component from a component dict.

    """
    for dia in component_dict.get('dialogues', ()):
        try:
            comp.add_dialogue(*_get_pair(dia))
        except Exception as e:
            msg = 'In device %s, malformed dialogue %s\n%r'
            raise Exception(msg % (name, dia, e))
    for prop_name, prop_dict in component_dict.get('properties', {}).items():
        try:
            getter = _get_pair(prop_dict['getter']) if 'getter' in prop_dict else None
            setter = _get_triplet(prop_dict['setter']) if 'setter' in prop_dict else None
            comp.add_property(prop_name, prop_dict.get('default', ''), getter, setter, prop_dict.get('specs', {}))
        except Exception as e:
            msg = 'In device %s, malformed property %s\n%r'
            raise type(e)(msg % (name, prop_name, format_exc()))

def get_bases(definition_dict, loader):
