def to_bytes(val):
    """Takes a text message and return a tuple
    """
    if val is NoResponse:
        return val
    val = val.replace('\\r', '\r').replace('\\n', '\n')
    return val.encode()

def multiply_iterables(it1, it2):
    """Element-wise iterables multiplications."""
    assert len(it1) == len(it2), 'Can not element-wise multiply iterables of different length.'
    return list(map(mul, it1, it2))

def read_chunk(stream):
    """Ignore whitespace outside of strings. If we hit a string, read it in
    its entirety."""
    chunk = stream.read(1)
    while chunk in SKIP:
        chunk = stream.read(1)
    if chunk == '"':
        chunk += stream.read(1)
        while not chunk.endswith('"'):
            if chunk[-1] == ESCAPE:
                chunk += stream.read(2)
            else:
                chunk += stream.read(1)
    return chunk

def items(stream, **kwargs):
    """External facing items. Will return item from stream as available.
    Currently waits in loop waiting for next item. Can pass keywords that
    json.loads accepts (such as object_pairs_hook)"""
    for s in yield_json(stream):
        yield json.loads(s, **kwargs)

def yield_json(stream):
    """Uses array and object delimiter counts for balancing.
    """
    buff = u''
    arr_count = 0
    obj_count = 0
    while True:
        buff += read_chunk(stream)
        if buff.endswith('{'):
            obj_count += 1
        if buff.endswith('['):
            arr_count += 1
        if buff.endswith(']'):
            arr_count -= 1
            if obj_count == arr_count == 0:
                json_item = copy(buff)
                buff = u''
                yield json_item
        if buff.endswith('}'):
            obj_count -= 1
            if obj_count == arr_count == 0:
                json_item = copy(buff)
                buff = u''
                yield json_item

def check_property(prop, name, **kwargs):
    """Check and parse a property with either a specific checking function
    or a generic parser"""
    checkers = {'color': check_color, 'alpha': check_alpha, 'size': check_size, 'thickness': check_thickness, 'index': check_index, 'coordinates': check_coordinates, 'colormap': check_colormap, 'bins': check_bins, 'spec': check_spec}
    if name in checkers:
        return checkers[name](prop, **kwargs)
    elif isinstance(prop, list) or isinstance(prop, ndarray) or isscalar(prop):
        return check_1d(prop, name)
    else:
        return prop

def check_coordinates(co, xy=None):
    """Check and parse coordinates as either a single coordinate list [[r,c],[r,c]] or a
    list of coordinates for multiple regions [[[r0,c0],[r0,c0]], [[r1,c1],[r1,c1]]]"""
    if isinstance(co, ndarray):
        co = co.tolist()
    if not (isinstance(co[0][0], list) or isinstance(co[0][0], tuple)):
        co = [co]
    if xy is not True:
        co = map(lambda p: asarray(p)[:, ::-1].tolist(), co)
    return co

def check_color(c):
    """Check and parse color specs as either a single [r,g,b] or a list of
    [[r,g,b],[r,g,b]...]"""
    c = asarray(c)
    if c.ndim == 1:
        c = c.flatten()
        c = c[newaxis, :]
        if c.shape[1] != 3:
            raise Exception('Color must have three values per point')
    elif c.ndim == 2:
        if c.shape[1] != 3:
            raise Exception('Color array must have three values per point')
    return c

def check_colormap(cmap):
    """Check if cmap is one of the colorbrewer maps"""
    names = set(['BrBG', 'PiYG', 'PRGn', 'PuOr', 'RdBu', 'RdGy', 'RdYlBu', 'RdYlGn', 'Spectral', 'Blues', 'BuGn', 'BuPu', 'GnBu', 'Greens', 'Greys', 'Oranges', 'OrRd', 'PuBu', 'PuBuGn', 'PuRd', 'Purples', 'RdPu', 'Reds', 'YlGn', 'YlGnBu', 'YlOrBr', 'YlOrRd', 'Accent', 'Dark2', 'Paired', 'Pastel1', 'Pastel2', 'Set1', 'Set2', 'Set3', 'Lightning'])
    if cmap not in names:
        raise Exception("Invalid cmap '%s',  must be one of %s" % (cmap, names))
    else:
        return cmap

def check_size(s):
    """Check and parse size specs as either a single [s] or a list of [s,s,s,...]"""
    s = check_1d(s, 'size')
    if any(map(lambda d: d <= 0, s)):
        raise Exception('Size cannot be 0 or negative')
    return s

def check_thickness(s):
    """Check and parse thickness specs as either a single [s] or a list of [s,s,s,...]"""
    s = check_1d(s, 'thickness')
    if any(map(lambda d: d <= 0, s)):
        raise Exception('Thickness cannot be 0 or negative')
    return s

def check_index(i):
    """Checks and parses an index spec, must be a one-dimensional array [i0, i1, ...]"""
    i = asarray(i)
    if i.ndim > 1 or size(i) < 1:
        raise Exception('Index must be one-dimensional and non-singleton')
    return i

def check_alpha(a):
    """Check and parse alpha specs as either a single [a] or a list of [a,a,a,...]"""
    a = check_1d(a, 'alpha')
    if any(map(lambda d: d <= 0, a)):
        raise Exception('Alpha cannot be 0 or negative')
    return a

def check_1d(x, name):
    """Check and parse a one-dimensional spec as either a single [x] or a list of [x,x,x...]"""
    x = asarray(x)
    if size(x) == 1:
        x = asarray([x])
    if x.ndim == 2:
        raise Exception('Property: %s must be one-dimensional' % name)
    x = x.flatten()
    return x

def temporary_unavailable(request, template_name='503.html'):
