def _glob_pjoin(*parts):
    """Join paths for glob processing"""
    if parts[0] in ('.', ''):
        parts = parts[1:]
    return pjoin(*parts).replace(os.sep, '/')

def _get_files(file_patterns, top=HERE):
    """Expand file patterns to a list of paths.

    Parameters
    -----------
    file_patterns: list or str
        A list of glob patterns for the data file locations.
        The globs can be recursive if they include a `**`.
        They should be relative paths from the top directory or
        absolute paths.
    top: str
        the directory to consider for data files

    Note:
    Files in `node_modules` are ignored."""
    if not isinstance(file_patterns, (list, tuple)):
        file_patterns = [file_patterns]
    for i, p in enumerate(file_patterns):
        if os.path.isabs(p):
            file_patterns[i] = os.path.relpath(p, top)
    matchers = [_compile_pattern(p) for p in file_patterns]
    files = set()
    for root, dirnames, filenames in os.walk(top):
        if 'node_modules' in dirnames:
            dirnames.remove('node_modules')
        for m in matchers:
            for filename in filenames:
                fn = os.path.relpath(_glob_pjoin(root, filename), top)
                fn = fn.replace(os.sep, '/')
                if m(fn):
                    files.add(fn.replace(os.sep, '/'))
    return list(files)

def optimize(order):
    """optimize(impl)
    Tries to set the implementation type of all registered :py:class:`Operation` classes to *impl*.
    This has no effect when an op does not implement that type.

    The behavior is equivalent to:

    .. code-block:: python

       for op in Operation.__subclasses__():
           if impl in op.impls:
               op.use_impl(impl)

    *impl* can also be a list or tuple of valid implementation types representing a preferred order."""
    if not isinstance(order, (list, tuple)):
        order = [order]
    for op in Operation.__subclasses__():
        for impl in order:
            if impl in op.impls:
                op.use_impl(impl)
                break

def LinSpace(start, stop, num):
    """Linspace op."""
    return (np.linspace(start, stop, num=num, dtype=np.float32),)

def Range(start, limit, delta):
    """Range op."""
    return (np.arange(start, limit, delta, dtype=np.int32),)

def RandomStandardNormal(shape, dtype, seed):
    """Standard (mu=0, sigma=1) gaussian op."""
    if seed:
        np.random.seed(seed)
    return (np.random.normal(size=reduce(mul, shape)).reshape(shape).astype(dtype_map[dtype]),)

def TruncatedNormal(shape, dtype, seed):
    """Standard (mu=0, sigma=1) gaussian op with truncation above 2 sigma."""
    if seed:
        np.random.seed(seed)
    n = reduce(mul, shape)
    r = np.empty(n, dtype=dtype_map[dtype])
    idxs = np.ones(n, dtype=np.bool)
    while n:
        r[idxs] = np.random.normal(size=n)
        idxs = np.abs(r) > 2
        n = np.sum(idxs)
    return (r.reshape(shape),)

def RandomUniform(shape, dtype, seed):
    """Random uniform op."""
    if seed:
        np.random.seed(seed)
    return (np.random.uniform(size=shape).astype(dtype_map[dtype]),)

def RandomUniformInt(shape, minval, maxval, seed):
    """Random uniform int op."""
    if seed:
        np.random.seed(seed)
    return (np.random.randint(minval, maxval, size=shape),)

def RandomShuffle(a, seed):
    """Random uniform op."""
    if seed:
        np.random.seed(seed)
    r = a.copy()
    np.random.shuffle(r)
    return (r,)

def Rank(a):
    """Rank op."""
    return (np.array([len(a.shape)], dtype=np.int32),)

def Squeeze(a, squeeze_dims):
    """Squeeze op, i.e. removes singular axes."""
    if not squeeze_dims:
        squeeze_dims = list(range(len(a.shape)))
    slices = [0 if dim == 1 and i in squeeze_dims else slice(None) for i, dim in enumerate(a.shape)]
    return (np.copy(a)[slices],)

def ExpandDims(a, dim):
    """Expand dim op, i.e. add singular axis at dim."""
    shape = list(a.shape)
    if dim >= 0:
        shape.insert(dim, 1)
    else:
        shape.insert(len(shape) + dim + 1, 1)
    return (np.copy(a).reshape(*shape),)

def Slice(a, begin, size):
    """Slicing op."""
    return (np.copy(a)[[slice(*tpl) for tpl in zip(begin, begin + size)]],)

def SplitV(a, splits, axis):
    """Split op with multiple split sizes."""
    return tuple(np.split(np.copy(a), np.cumsum(splits), axis=axis))

def ConcatV2(inputs):
    """Concat op."""
    axis = inputs.pop()
    return (np.concatenate(inputs, axis=axis),)

def Unpack(a, num, axis):
    """Unpack op."""
    return tuple((np.squeeze(b, axis=axis) for b in np.split(a, num, axis=axis)))

def ReverseSequence(a, seq_lengths, seq_dim, batch_dim):
    """Sequential reverse op."""
    r = np.copy(a)
    invidxs = (len(r.shape) - 1) * [slice(None)]
    if seq_dim < batch_dim:
        invidxs[seq_dim] = slice(None, None, -1)
    else:
        invidxs[seq_dim - 1] = slice(None, None, -1)
    _invidxs = tuple(invidxs)
    selidxs = len(r.shape) * [slice(None)]
    for i, l in enumerate(seq_lengths):
        if not l:
            continue
        selidxs[batch_dim] = i
        selidxs[seq_dim] = slice(0, l)
        _selidxs = tuple(selidxs)
        r[_selidxs] = a[_selidxs][_invidxs]
    return (r,)

def ReverseV2(a, axes):
    """Reverse op."""
    idxs = tuple((slice(None, None, 2 * int(i not in axes) - 1) for i in range(len(a.shape))))
    return (np.copy(a[idxs]),)

def Betainc(a, b, x):
    """Complemented, incomplete gamma op."""
    return (sp.special.betainc(a, b, x),)

def Diag(a):
    """Diag op."""
    r = np.zeros(2 * a.shape, dtype=a.dtype)
    for idx, v in np.ndenumerate(a):
        r[2 * idx] = v
    return (r,)

def MatrixDiagPart(a):
    """Batched diag op that returns only the diagonal elements."""
    r = np.zeros(a.shape[:-2] + (min(a.shape[-2:]),))
    for coord in np.ndindex(a.shape[:-2]):
        pos = coord + (Ellipsis,)
        r[pos] = np.diagonal(a[pos])
    return (r,)

def MatMul(a, b, transpose_a, transpose_b):
    """Matrix multiplication op."""
    return (np.dot(a if not transpose_a else np.transpose(a), b if not transpose_b else np.transpose(b)),)

def MatrixInverse(a, adj):
    """Matrix inversion op."""
    return (np.linalg.inv(a if not adj else _adjoint(a)),)

def MatrixSolve(a, rhs, adj):
    """Matrix solve op."""
    return (np.linalg.solve(a if not adj else _adjoint(a), rhs),)

def MatrixTriangularSolve(a, rhs, lower, adj):
    """Matrix triangular solve op."""
    trans = 0 if not adj else 2
    r = np.empty(rhs.shape).astype(a.dtype)
    for coord in np.ndindex(a.shape[:-2]):
        pos = coord + (Ellipsis,)
        r[pos] = sp.linalg.solve_triangular(a[pos] if not adj else np.conj(a[pos]), rhs[pos], trans=trans, lower=lower)
    return (r,)

def MatrixSolveLs(a, rhs, l2_reg):
    """Matrix least-squares solve op."""
    r = np.empty(rhs.shape).astype(a.dtype)
    for coord in np.ndindex(a.shape[:-2]):
        pos = coord + (Ellipsis,)
        r[pos] = np.linalg.lstsq(a[pos], rhs[pos])[0]
    return (r,)

def SelfAdjointEig(a):
    """Eigen decomp op."""
    shape = list(a.shape)
    shape[-2] += 1
    return (np.append(*np.linalg.eig(a)).reshape(*shape),)

def Svd(a, uv, full):
    """Single value decomp op."""
    u, s, v = np.linalg.svd(a, full_matrices=full, compute_uv=uv)
    return (s, u, v)

def Prod(a, axis, keep_dims):
    """Prod reduction op."""
    return (np.prod(a, axis=axis if not isinstance(axis, np.ndarray) else tuple(axis), keepdims=keep_dims),)

def Min(a, axis, keep_dims):
    """Min reduction op."""
    return (np.amin(a, axis=axis if not isinstance(axis, np.ndarray) else tuple(axis), keepdims=keep_dims),)

def Max(a, axis, keep_dims):
    """Max reduction op."""
    return (np.amax(a, axis=axis if not isinstance(axis, np.ndarray) else tuple(axis), keepdims=keep_dims),)

def Mean(a, axis, keep_dims):
    """Mean reduction op."""
    return (np.mean(a, axis=axis if not isinstance(axis, np.ndarray) else tuple(axis), keepdims=keep_dims),)

def All(a, axis, keep_dims):
    """All reduction op."""
    return (np.all(a, axis=axis if not isinstance(axis, np.ndarray) else tuple(axis), keepdims=keep_dims),)

def Any(a, axis, keep_dims):
    """Any reduction op."""
    return (np.any(a, axis=axis if not isinstance(axis, np.ndarray) else tuple(axis), keepdims=keep_dims),)

def SegmentSum(a, ids, *args):
    """Segmented sum op."""
    func = lambda idxs: reduce(np.add, a[idxs])
    return (seg_map(func, a, ids),)

def SegmentProd(a, ids):
    """Segmented prod op."""
    func = lambda idxs: reduce(np.multiply, a[idxs])
    return (seg_map(func, a, ids),)

def SegmentMin(a, ids):
    """Segmented min op."""
    func = lambda idxs: np.amin(a[idxs], axis=0)
    return (seg_map(func, a, ids),)

def SegmentMax(a, ids):
    """Segmented max op."""
    func = lambda idxs: np.amax(a[idxs], axis=0)
    return (seg_map(func, a, ids),)

def SegmentMean(a, ids):
    """Segmented mean op."""
    func = lambda idxs: np.mean(a[idxs], axis=0)
    return (seg_map(func, a, ids),)

def SparseSegmentSqrtN(a, idxs, ids):
    """Sparse segmented sum / sqrt(n=len(idxs)) op."""
    func = lambda _idxs: np.divide(reduce(np.add, a[idxs][_idxs]), np.math.sqrt(len(_idxs)))
    return (seg_map(func, a, ids),)

def ListDiff(a, b):
    """List diff op."""
    d = np.setdiff1d(a, b)
    return (d, np.searchsorted(a, d).astype(np.int32))

def Unique(a, t):
    """Unique op."""
    _, idxs, inv = np.unique(a, return_index=True, return_inverse=True)
    return (np.copy(a)[np.sort(idxs)], idxs[inv].astype(dtype_map[t]))

def Elu(a):
    """Elu op."""
    return (np.where(a < 0, np.subtract(np.exp(a), 1), a),)

def Softsign(a):
    """Softsign op."""
    return (np.divide(a, np.add(np.abs(a), 1)),)

def Softmax(a):
    """Softmax op."""
    e = np.exp(a)
    return (np.divide(e, np.sum(e, axis=-1, keepdims=True)),)

def Conv1D(a, f, strides, padding, data_format):
    """1D conv op."""
    if data_format.decode('ascii') == 'NCHW':
        a = (np.rollaxis(a, 1, -1),)
    patches = _conv_patches(a, f, 3 * [strides], padding.decode('ascii'))
    conv = np.sum(patches, axis=tuple(range(-f.ndim, -1)))
    if data_format.decode('ascii') == 'NCHW':
        conv = np.rollaxis(conv, -1, 1)
    return (conv,)

def Conv3D(a, f, strides, padding):
    """3D conv op."""
    patches = _conv_patches(a, f, strides, padding.decode('ascii'))
    return (np.sum(patches, axis=tuple(range(-f.ndim, -1))),)

def AvgPool(a, k, strides, padding, data_format):
    """Average pooling op."""
    if data_format.decode('ascii') == 'NCHW':
        a = (np.rollaxis(a, 1, -1),)
    patches = _pool_patches(a, k, strides, padding.decode('ascii'))
    pool = np.average(patches, axis=tuple(range(-len(k), 0)))
    if data_format.decode('ascii') == 'NCHW':
        pool = np.rollaxis(pool, -1, 1)
    return (pool,)

def MaxPool(a, k, strides, padding, data_format):
    """Maximum pooling op."""
    if data_format.decode('ascii') == 'NCHW':
        a = (np.rollaxis(a, 1, -1),)
    patches = _pool_patches(a, k, strides, padding.decode('ascii'))
    pool = np.amax(patches, axis=tuple(range(-len(k), 0)))
    if data_format.decode('ascii') == 'NCHW':
        pool = np.rollaxis(pool, -1, 1)
    return (pool,)

def AvgPool3D(a, k, strides, padding):
    """Average 3D pooling op."""
    patches = _pool_patches(a, k, strides, padding.decode('ascii'))
    return (np.average(patches, axis=tuple(range(-len(k), 0))),)

def MaxPool3D(a, k, strides, padding):
    """Maximum 3D pooling op."""
    patches = _pool_patches(a, k, strides, padding.decode('ascii'))
    return (np.amax(patches, axis=tuple(range(-len(k), 0))),)

def root_task_parser():
    """Returns a new *ArgumentParser* instance that only contains paremeter actions of the root task.
    The returned instance is cached."""
    global _root_task_parser
    if _root_task_parser:
        return _root_task_parser
    luigi_parser = luigi.cmdline_parser.CmdlineParser.get_instance()
    if not luigi_parser:
        return None
    root_task = luigi_parser.known_args.root_task
    root_dests = []
    for task_name, _, param_name, _ in luigi.task_register.Register.get_all_params():
        if task_name == root_task:
            root_dests.append(param_name)
    _root_task_parser = ArgumentParser(add_help=False)
    for action in list(full_parser()._actions):
        if not action.option_strings or action.dest in root_dests:
            _root_task_parser._add_action(action)
    logger.debug('build luigi argument parser for root task {}'.format(root_task))
    return _root_task_parser

def global_cmdline_values():
    """Returns a dictionary of global command line arguments (computed with
    :py:func:`global_cmdline_args`) to their current values. The returnd dictionary is cached.
    Example:

    .. code-block:: python

        global_cmdline_values()
        # -> {"core_local_scheduler": True}"""
    global _global_cmdline_values
    if _global_cmdline_values:
        return _global_cmdline_values
    luigi_parser = luigi.cmdline_parser.CmdlineParser.get_instance()
    if not luigi_parser:
        return None
    parser = full_parser()
    global_args = global_cmdline_args()
    _global_cmdline_values = {}
    for action in parser._actions:
        if any((arg in action.option_strings for arg in global_args)):
            _global_cmdline_values[action.dest] = getattr(luigi_parser.known_args, action.dest)
    return _global_cmdline_values

def split_transfer_kwargs(kwargs, skip=None):
    """Takes keyword arguments *kwargs*, splits them into two separate dictionaries depending on their
    content, and returns them in a tuple. The first one will contain arguments related to potential
    file transfer operations (e.g. ``"cache"`` or ``"retries"``), while the second one will contain
    all remaining arguments. This function is used internally to decide which arguments to pass to
    target formatters. *skip* can be a list of argument keys that are ignored."""
    skip = make_list(skip) if skip else []
    transfer_kwargs = {name: kwargs.pop(name) for name in ['cache', 'prefer_cache', 'retries', 'retry_delay'] if name in kwargs and name not in skip}
    return (transfer_kwargs, kwargs)

def get_global_parameters(config_names=('core', 'scheduler', 'worker', 'retcode')):
    """Returns a list of global, luigi-internal configuration parameters. Each list item is a 4-tuple
    containing the configuration class, the parameter instance, the parameter name, and the full
    parameter name in the cli. When *config_names* is set, it should be a list of configuration
    class names that are exclusively taken into account."""
    params = []
    for cls in luigi.task.Config.__subclasses__():
        if config_names and cls.__name__ not in config_names:
            continue
        for attr in dir(cls):
            param = getattr(cls, attr)
            if not isinstance(param, luigi.Parameter):
                continue
            full_name = attr.replace('_', '-')
            if getattr(cls, 'use_cmdline_section', True):
                full_name = '{}-{}'.format(cls.__name__.replace('_', '-'), full_name)
            params.append((cls, param, attr, full_name))
    return params

def rel_path(anchor, *paths):
    """Returns a path made of framgment *paths* relativ to an *anchor* path. When *anchor* is a file,
    its absolute directory is used instead."""
    anchor = os.path.abspath(os.path.expandvars(os.path.expanduser(anchor)))
    if os.path.exists(anchor) and os.path.isfile(anchor):
        anchor = os.path.dirname(anchor)
    return os.path.normpath(os.path.join(anchor, *paths))

def law_home_path(*paths):
    """Returns the law home directory (``$LAW_HOME``) that defaults to ``"$HOME/.law"``, optionally
    joined with *paths*."""
    home = os.getenv('LAW_HOME', '$HOME/.law')
    home = os.path.expandvars(os.path.expanduser(home))
    return os.path.normpath(os.path.join(home, *paths))

def print_err(*args, **kwargs):
    """print_err(*args, flush=False)
    Same as *print*, but outputs to stderr. If *flush* is *True*, stderr is flushed after printing."""
    sys.stderr.write(' '.join((str(arg) for arg in args)) + '\n')
    if kwargs.get('flush', False):
        sys.stderr.flush()

def abort(msg=None, exitcode=1):
    """Aborts the process (*sys.exit*) with an *exitcode*. If *msg* is not *None*, it is printed first
    to stdout if *exitcode* is 0 or *None*, and to stderr otherwise."""
    if msg is not None:
        if exitcode in (None, 0):
            print(msg)
        else:
            print_err(msg)
    sys.exit(exitcode)

def colored(msg, color=None, background=None, style=None, force=False):
    """Return the colored version of a string *msg*. For *color*, *background* and *style* options, see
    https://misc.flogisoft.com/bash/tip_colors_and_formatting. Unless *force* is *True*, the *msg*
    string is returned unchanged in case the output is not a tty."""
    try:
        if not force and (not os.isatty(sys.stdout.fileno())):
            return msg
    except:
        return msg
    color = colors.get(color, colors['default'])
    background = backgrounds.get(background, backgrounds['default'])
    if not isinstance(style, (tuple, list, set)):
        style = (style,)
    style = ';'.join((str(styles.get(s, styles['default'])) for s in style))
    return '\x1b[{};{};{}m{}\x1b[0m'.format(style, background, color, msg)

def query_choice(msg, choices, default=None, descriptions=None, lower=True):
    """Interactively query a choice from the prompt until the input matches one of the *choices*. The
    prompt can be configured using *msg* and *descriptions*, which, if set, must have the same
    length as *choices*. When *default* is not *None* it must be one of the choices and is used when
    the input is empty. When *lower* is *True*, the input is compared to the choices in lower case."""
    choices = _choices = [str(c) for c in choices]
    if lower:
        _choices = [c.lower() for c in choices]
    if default is not None:
        if default not in choices:
            raise Exception('default must be one of the choices')
    hints = [choice if choice != default else choice + '*' for choice in choices]
    if descriptions is not None:
        if len(descriptions) != len(choices):
            raise ValueError('length of descriptions must match length of choices')
        hints = ['{}({})'.format(*tpl) for tpl in zip(hints, descriptions)]
    msg += ' [{}] '.format(', '.join(hints))
    choice = None
    while choice not in _choices:
        if choice is not None:
            print("invalid choice: '{}'\n".format(choice))
        choice = six.moves.input(msg)
        if default is not None and choice == '':
            choice = default
        if lower:
            choice = choice.lower()
    return choice

def multi_match(name, patterns, mode=any, regex=False):
    """Compares *name* to multiple *patterns* and returns *True* in case of at least one match (*mode*
    = *any*, the default), or in case all patterns matched (*mode* = *all*). Otherwise, *False* is
    returned. When *regex* is *True*, *re.match* is used instead of *fnmatch.fnmatch*."""
    if not regex:
        return mode((fnmatch.fnmatch(name, pattern) for pattern in patterns))
    else:
        return mode((re.match(pattern, name) for pattern in patterns))

def is_lazy_iterable(obj):
    """Returns whether *obj* is iterable lazily, such as generators, range objects, etc."""
    return isinstance(obj, (types.GeneratorType, collections.MappingView, six.moves.range, enumerate))

def make_list(obj, cast=True):
    """Converts an object *obj* to a list and returns it. Objects of types *tuple* and *set* are
    converted if *cast* is *True*. Otherwise, and for all other types, *obj* is put in a new list."""
    if isinstance(obj, list):
        return list(obj)
    elif is_lazy_iterable(obj):
        return list(obj)
    elif isinstance(obj, (tuple, set)) and cast:
        return list(obj)
    else:
        return [obj]

def make_tuple(obj, cast=True):
    """Converts an object *obj* to a tuple and returns it. Objects of types *list* and *set* are
    converted if *cast* is *True*. Otherwise, and for all other types, *obj* is put in a new tuple."""
    if isinstance(obj, tuple):
        return tuple(obj)
    elif is_lazy_iterable(obj):
        return tuple(obj)
    elif isinstance(obj, (list, set)) and cast:
        return tuple(obj)
    else:
        return (obj,)

def flatten(struct):
    """Flattens and returns a complex structured object *struct*."""
    if isinstance(struct, dict):
        return flatten(struct.values())
    elif isinstance(struct, (list, tuple, set)) or is_lazy_iterable(struct):
        objs = []
        for obj in struct:
            objs.extend(flatten(obj))
        return objs
    else:
        return [struct]

def merge_dicts(*dicts, **kwargs):
    """merge_dicts(*dicts, cls=None)
    Takes multiple *dicts* and returns a single merged dict. The merging takes place in order of the
    passed dicts and therefore, values of rear objects have precedence in case of field collisions.
    The class of the returned merged dict is configurable via *cls*. If it is *None*, the class is
    inferred from the first dict object in *dicts*."""
    cls = kwargs.get('cls', None)
    if cls is None:
        for d in dicts:
            if isinstance(d, dict):
                cls = d.__class__
                break
        else:
            raise TypeError('cannot infer cls as none of the passed objects is of type dict')
    merged_dict = cls()
    for d in dicts:
        if isinstance(d, dict):
            merged_dict.update(d)
    return merged_dict

def which(prog):
    """Pythonic ``which`` implementation. Returns the path to an executable *prog* by searching in
    *PATH*, or *None* when it could not be found."""
    executable = lambda path: os.path.isfile(path) and os.access(path, os.X_OK)
    dirname, _ = os.path.split(prog)
    if dirname:
        if executable(prog):
            return prog
    elif 'PATH' in os.environ:
        for search_path in os.environ['PATH'].split(os.pathsep):
            path = os.path.join(search_path.strip('"'), prog)
            if executable(path):
                return path
    return None

def interruptable_popen(*args, **kwargs):
    """Shorthand to :py:class:`Popen` followed by :py:meth:`Popen.communicate`. All *args* and *kwargs*
    are forwatded to the :py:class:`Popen` constructor. The return code, standard output and
    standard error are returned in a tuple. The call :py:meth:`Popen.communicate` is interruptable
    by the user."""
    kwargs['preexec_fn'] = os.setsid
    p = subprocess.Popen(*args, **kwargs)
    try:
        out, err = p.communicate()
    except KeyboardInterrupt:
        os.killpg(os.getpgid(p.pid), signal.SIGTERM)
        raise
    if six.PY3:
        if out is not None:
            out = out.decode('utf-8')
        if err is not None:
            err = err.decode('utf-8')
    return (p.returncode, out, err)

def readable_popen(*args, **kwargs):
    """Shorthand to :py:class:`Popen` which yields the output live line-by-line. All *args* and
    *kwargs* are forwatded to the :py:class:`Popen` constructor. When EOF is reached,
    ``communicate()`` is called on the subprocess and it is yielded. Example:

    .. code-block:: python

        for line in readable_popen(["some_executable", "--args"]):
            if isinstance(line, str):
                print(line)
            else:
                process = line
                if process.returncode != 0:
                    raise Exception("complain ...")"""
    kwargs['stdout'] = subprocess.PIPE
    kwargs['stderr'] = subprocess.STDOUT
    p = subprocess.Popen(*args, **kwargs)
    for line in iter(lambda: p.stdout.readline(), ''):
        if six.PY3:
            line = line.decode('utf-8')
        yield line.rstrip()
    p.communicate()
    yield p

def makedirs_perm(path, perm=None):
    """Recursively creates directory up to *path*. If *perm* is set, the permissions of all newly
    created directories are set to its value."""
    if not os.path.exists(path):
        if perm is None:
            os.makedirs(path)
        else:
            umask = os.umask(0)
            try:
                os.makedirs(path, perm)
            finally:
                os.umask(umask)

def iter_chunks(l, size):
    """Returns a generator containing chunks of *size* of a list, integer or generator *l*. A *size*
    smaller than 1 results in no chunking at all."""
    if isinstance(l, six.integer_types):
        l = six.moves.range(l)
    if is_lazy_iterable(l):
        if size < 1:
            yield list(l)
        else:
            chunk = []
            for elem in l:
                if len(chunk) < size:
                    chunk.append(elem)
                else:
                    yield chunk
                    chunk = [elem]
            else:
                if chunk:
                    yield chunk
    elif size < 1:
        yield l
    else:
        for i in six.moves.range(0, len(l), size):
            yield l[i:i + size]

def human_bytes(n, unit=None):
    """Takes a number of bytes *n*, assigns the best matching unit and returns the respective number
    and unit string in a tuple. When *unit* is set, that unit is used. Example:

    .. code-block:: python

        human_bytes(3407872)
        # -> (3.25, "MB")

        human_bytes(3407872, "kB")
        # -> (3328.0, "kB")"""
    if n == 0:
        idx = 0
    elif unit:
        idx = byte_units.index(unit)
    else:
        idx = int(math.floor(math.log(abs(n), 1024)))
        idx = min(idx, len(byte_units))
    return (n / 1024.0 ** idx, byte_units[idx])

def human_time_diff(*args, **kwargs):
    '''Returns a human readable time difference. The largest unit is days. All *args* and *kwargs* are
    passed to ``datetime.timedelta``. Example:

    .. code-block:: python

        human_time_diff(seconds=1233)
        # -> "20 minutes, 33 seconds"

        human_time_diff(seconds=90001)
        # -> "1 day, 1 hour, 1 second"'''
    secs = float(datetime.timedelta(*args, **kwargs).total_seconds())
    parts = []
    for unit, mul in time_units:
        if secs / mul >= 1 or mul == 1:
            if mul > 1:
                n = int(math.floor(secs / mul))
                secs -= n * mul
            else:
                n = round(secs, 1)
            parts.append('{} {}{}'.format(n, unit, '' if n == 1 else 's'))
    return ', '.join(parts)

def is_file_exists_error(e):
    """Returns whether the exception *e* was raised due to an already existing file or directory."""
    if six.PY3:
        return isinstance(e, FileExistsError)
    else:
        return isinstance(e, OSError) and e.errno == 17

def open_compat(*args, **kwargs):
    """Polyfill for python's ``open`` factory, returning the plain ``open`` in python 3, and
    ``io.open`` in python 2 with a patched ``write`` method that internally handles unicode
    conversion of its first argument. All *args* and *kwargs* are forwarded."""
    if six.PY3:
        return open(*args, **kwargs)
    else:
        f = io.open(*args, **kwargs)
        if f.encoding and f.encoding.lower().replace('-', '') == 'utf8':
            write_orig = f.write
            def write(data, *args, **kwargs):
                u = unicode
                if not isinstance(data, u):
                    data = u(data)
                return write_orig(data, *args, **kwargs)
            f.write = write
        return f

def patch_object(obj, attr, value):
    """Context manager that temporarily patches an object *obj* by replacing its attribute *attr* with
    *value*. The original value is set again when the context is closed."""
    orig = getattr(obj, attr, no_value)
    try:
        setattr(obj, attr, value)
        yield obj
    finally:
        try:
            if orig is no_value:
                delattr(obj, attr)
            else:
                setattr(obj, attr, orig)
        except:
            pass

def notify_telegram(title, content, token=None, chat=None, mention_user=None, **kwargs):
    """Sends a telegram notification and returns *True* on success. The communication with the telegram
    API might have some delays and is therefore handled by a thread."""
    import telegram
    cfg = Config.instance()
    if not token:
        token = cfg.get_expanded('notifications', 'telegram_token')
    if not chat:
        chat = cfg.get_expanded('notifications', 'telegram_chat')
    if not token or not chat:
        logger.warning('cannot send Telegram notification, token ({}) or chat ({}) empty'.format(token, chat))
        return False
    mention_text = ''
    if mention_user is None:
        mention_user = cfg.get_expanded('notifications', 'telegram_mention_user')
    if mention_user:
        mention_text = ' (@{})'.format(mention_user)
    request = {'parse_mode': 'Markdown'}
    if isinstance(content, six.string_types):
        request['text'] = '{}{}\n\n{}'.format(title, mention_text, content)
    else:
        request['text'] = '{}{}\n\n'.format(title, mention_text)
        for key, value in content.items():
            request['text'] += '_{}_: {}\n'.format(key, value)
    request.update(kwargs)
    thread = threading.Thread(target=_notify_telegram, args=(token, chat, request))
    thread.start()
    return True

def safe_output(fn, opts, task, *args, **kwargs):
    """safe_output(skip=None)
    Wraps a bound method of a task and guards its execution. If an exception occurs, and it is not
    an instance of *skip*, the task's output is removed prior to the actual raising."""
    try:
        return fn(task, *args, **kwargs)
    except Exception as e:
        if opts['skip'] is None or not isinstance(e, opts['skip']):
            for outp in luigi.task.flatten(task.output()):
                outp.remove()
        raise

def delay(fn, opts, task, *args, **kwargs):
    """delay(t=5, stddev=0., pdf="gauss")
    Wraps a bound method of a task and delays its execution by *t* seconds."""
    if opts['stddev'] <= 0:
        t = opts['t']
    elif opts['pdf'] == 'gauss':
        t = random.gauss(opts['t'], opts['stddev'])
    elif opts['pdf'] == 'uniform':
        t = random.uniform(opts['t'], opts['stddev'])
    else:
        raise ValueError("unknown delay decorator pdf '{}'".format(opts['pdf']))
    time.sleep(t)
    return fn(task, *args, **kwargs)

def timeit(fn, opts, task, *args, **kwargs):
    """Wraps a bound method of a task and logs its execution time in a human readable format. Logs in
    info mode. When *publish_message* is *True*, the duration is also published as a task message to
    the scheduler."""
    start_time = time.time()
    try:
        return fn(task, *args, **kwargs)
    finally:
        duration = human_time_diff(seconds=round(time.time() - start_time, 1))
        timeit_logger = logger.getChild('timeit')
        timeit_logger.info('runtime of {}: {}'.format(task.task_id, duration))
        if opts['publish_message'] and callable(getattr(task, 'publish_message', None)):
            task.publish_message('runtime: {}'.format(duration))

def get_voms_proxy_user():
    """Returns the owner of the voms proxy."""
    out = _voms_proxy_info(['--identity'])[1].strip()
    try:
        return re.match('.*\\/CN\\=([^\\/]+).*', out.strip()).group(1)
    except:
        raise Exception('no valid identity found in voms proxy: {}'.format(out))

def get_formatter(name, silent=False):
    """Returns the formatter class whose name attribute is *name*. When no class could be found and
    *silent* is *True*, *None* is returned. Otherwise, an exception is raised."""
    formatter = FormatterRegister.formatters.get(name)
    if formatter or silent:
        return formatter
    else:
        raise Exception("cannot find formatter '{}'".format(name))

def find_formatters(path, silent=True):
    """Returns a list of formatter classes which would accept the file given by *path*. When no classes
    could be found and *silent* is *True*, an empty list is returned. Otherwise, an exception is
    raised."""
    formatters = [f for f in six.itervalues(FormatterRegister.formatters) if f.accepts(path)]
    if formatters or silent:
        return formatters
    else:
        raise Exception("cannot find formatter for path '{}'".format(path))

def find_formatter(name, path):
    """Returns the formatter class whose name attribute is *name* when *name* is not *AUTO_FORMATTER*.
    Otherwise, the first formatter that accepts *path* is returned. Internally, this method simply
    uses :py:func:`get_formatter` or :py:func:`find_formatters` depending on the value of *name*."""
    if name == AUTO_FORMATTER:
        return find_formatters(path, silent=False)[0]
    else:
        return get_formatter(name, silent=False)

