        if user[0] == '@':
            user = user[1:]
        exclude[i] = user
    users = [user['username'] for user in status_dict['mentions'] if user['username'].casefold() not in exclude]
    return users

def spec_dice(spec):
    """Return the dice specification as a string in a common format"""
    if spec[0] == 'c':
        return str(spec[1])
    elif spec[0] == 'r':
        r = spec[1:]
        s = '{}d{}'.format(r[0], r[1])
        if len(r) == 4 and (r[2] == 'd' and r[3] < r[0] or (r[2] == 'k' and r[3] > 0)):
            s += '{}{}'.format(r[2], r[3])
        return s
    elif spec[0] in ops:
        return '{} {} {}'.format(spec_dice(spec[1]), spec[0], spec_dice(spec[2]))
    else:
        raise ValueError('Invalid dice specification')

def roll_dice(spec):
    """Perform the dice rolls and replace all roll expressions with lists of
    the dice faces that landed up."""
    if spec[0] == 'c':
        return spec
    if spec[0] == 'r':
        r = spec[1:]
        if len(r) == 2:
            return ('r', perform_roll(r[0], r[1]))
        k = r[3] if r[2] == 'k' else -1
        d = r[3] if r[2] == 'd' else -1
        return ('r', perform_roll(r[0], r[1], k, d))
    if spec[0] == 'x':
        c = None
        roll = None
        if spec[1][0] == 'c':
            c = spec[1]
        elif spec[1][0] == 'r':
            roll = spec[1]
        if spec[2][0] == 'c':
            c = spec[2]
        elif spec[2][0] == 'r':
            roll = spec[2]
        if c == None or roll == None:
            return ('*', roll_dice(spec[1]), roll_dice(spec[2]))
        else:
            if c[1] > 50:
                raise SillyDiceError("I don't have that many dice!")
            return ('x', [roll_dice(roll) for i in range(c[1])])
    if spec[0] in ops:
        return (spec[0], roll_dice(spec[1]), roll_dice(spec[2]))
    else:
        raise ValueError('Invalid dice specification')

def sum_dice(spec):
    """Replace the dice roll arrays from roll_dice in place with summations of
    the rolls."""
    if spec[0] == 'c':
        return spec[1]
    elif spec[0] == 'r':
        return sum(spec[1])
    elif spec[0] == 'x':
        return [sum_dice(r) for r in spec[1]]
    elif spec[0] in ops:
        return (spec[0], sum_dice(spec[1]), sum_dice(spec[2]))
    else:
        raise ValueError('Invalid dice specification')

def short_sequence_repeat_extractor(string, min_length=1):
    """Extract the short tandem repeat structure from a string.

    :arg string string: The string.
    :arg integer min_length: Minimum length of the repeat structure."""
    length = len(string)
    k_max = length // 2 + 1
    if k_max > THRESHOLD:
        k_max = THRESHOLD // 2
    repeats = []
    i = 0
    last_repeat = i
    while i < length:
        max_count = 0
        max_k = 1
        for k in range(min_length, k_max):
            count = 0
            for j in range(i + k, length - k + 1, k):
                if string[i:i + k] != string[j:j + k]:
                    break
                count += 1
            if count > 0 and count >= max_count:
                max_count = count
                max_k = k
        if max_count > 0:
            if last_repeat < i:
                repeats.append(Repeat(last_repeat, i))
            repeats.append(Repeat(i, i + max_k, max_count))
            last_repeat = i + max_k * (max_count + 1)
        i += max_k * (max_count + 1)
    if last_repeat < i:
        repeats.append(Repeat(last_repeat, i))
    return repeats

def unregister(model_or_iterable, fail_silently=False):
    """Remove one or more models from the autofixture registry."""
    from django.db import models
    from .compat import get_model
    if issubclass(model_or_iterable, models.Model):
        model_or_iterable = [model_or_iterable]
    for model in model_or_iterable:
        if isinstance(model, string_types):
            model = get_model(*model.split('.', 1))
        try:
            del REGISTRY[model]
        except KeyError:
            if fail_silently:
                continue
            raise ValueError(u'The model %s.%s is not registered.' % (model._meta.app_label, model._meta.object_name))

def get(model, *args, **kwargs):
    """Get an autofixture instance for the passed in *model* sing the either an
    appropiate autofixture that was :ref:`registry <registry>` or fall back
    to the default:class:`AutoFixture` class.  *model* can be a model class or
    its string representation (e.g.  ``"app.ModelClass"``).

    All positional and keyword arguments are passed to the autofixture
    constructor."""
    from .compat import get_model
    if isinstance(model, string_types):
        model = get_model(*model.split('.', 1))
    if model in REGISTRY:
        return REGISTRY[model](model, *args, **kwargs)
    else:
        return AutoFixture(model, *args, **kwargs)

