def gen_category(yaml_file, sig):
    """Genereting catetory from YAML file."""
    out_dic = yaml.load(open(yaml_file))
    for key in out_dic:
        if key.endswith('00'):
            uid = key[1:]
            cur_dic = out_dic[key]
            porder = cur_dic['order']
            cat_dic = {'uid': uid, 'slug': cur_dic['slug'], 'name': cur_dic['name'], 'count': 0, 'tmpl': 1, 'pid': '0000', 'order': porder * 100, 'kind': '{0}'.format(sig)}
            MCategory.add_or_update(uid, cat_dic)
        else:
            sub_arr = out_dic[key]
            pid = key[1:3]
            for sub_dic in sub_arr:
                porder = out_dic['z' + pid + '00']['order']
                for key2 in sub_dic:
                    uid = key2[1:]
                    cur_dic = sub_dic[key2]
                    sorder = cur_dic['order']
                    cat_dic = {'uid': uid, 'slug': cur_dic['slug'], 'name': cur_dic['name'], 'count': 0, 'tmpl': 1, 'pid': pid + '00', 'order': porder * 100 + sorder, 'kind': '{0}'.format(sig)}
                    MCategory.add_or_update(pid + uid, cat_dic)

