    SITE_CFG['LANG'] = SITE_CFG.get('LANG', 'zh')
    if SITE_CFG['LANG'] == 'zh' and ChineseAnalyzer:
        schema = Schema(title=TEXT(stored=True, analyzer=ChineseAnalyzer()), catid=TEXT(stored=True), type=TEXT(stored=True), link=ID(unique=True, stored=True), content=TEXT(stored=True, analyzer=ChineseAnalyzer()))
