def _load_feed(path: str, view: View, config: nx.DiGraph) -> Feed:
    """Multi-file feed filtering"""
    config_ = remove_node_attributes(config, ['converters', 'transformations'])
    feed_ = Feed(path, view={}, config=config_)
    for filename, column_filters in view.items():
        config_ = reroot_graph(config_, filename)
        view_ = {filename: column_filters}
        feed_ = Feed(feed_, view=view_, config=config_)
    return Feed(feed_, config=config)

def reroot_graph(G: nx.DiGraph, node: str) -> nx.DiGraph:
    """Return a copy of the graph rooted at the given node"""
    G = G.copy()
    for n, successors in list(nx.bfs_successors(G, source=node)):
        for s in successors:
            G.add_edge(s, n, **G.edges[n, s])
            G.remove_edge(n, s)
    return G

def setwrap(value: Any) -> Set[str]:
    """Returns a flattened and stringified set from the given object or iterable.

    For use in public functions which accept argmuents or kwargs that can be
    one object or a list of objects."""
    return set(map(str, set(flatten([value]))))

def remove_node_attributes(G: nx.DiGraph, attributes: Union[str, Iterable[str]]):
    """Return a copy of the graph with the given attributes
    deleted from all nodes."""
    G = G.copy()
    for _, data in G.nodes(data=True):
        for attribute in setwrap(attributes):
            if attribute in data:
                del data[attribute]
    return G

def _coerce_topic(topic):
    """Ensure that the topic name is text string of a valid length.

    :param topic: Kafka topic name. Valid characters are in the set ``[a-zA-Z0-9._-]``.
    :raises ValueError: when the topic name exceeds 249 bytes
    :raises TypeError: when the topic is not :class:`unicode` or :class:`str`"""
    if not isinstance(topic, string_types):
        raise TypeError('topic={!r} must be text'.format(topic))
    if not isinstance(topic, text_type):
        topic = topic.decode('ascii')
    if len(topic) < 1:
        raise ValueError('invalid empty topic name')
    if len(topic) > 249:
        raise ValueError('topic={!r} name is too long: {} > 249'.format(topic, len(topic)))
    return topic

def _coerce_consumer_group(consumer_group):
    """Ensure that the consumer group is a text string.

    :param consumer_group: :class:`bytes` or :class:`str` instance
    :raises TypeError: when `consumer_group` is not :class:`bytes`
        or :class:`str`"""
    if not isinstance(consumer_group, string_types):
        raise TypeError('consumer_group={!r} must be text'.format(consumer_group))
    if not isinstance(consumer_group, text_type):
        consumer_group = consumer_group.decode('utf-8')
    return consumer_group

def _coerce_client_id(client_id):
    """Ensure the provided client ID is a byte string. If a text string is
    provided, it is encoded as UTF-8 bytes.

    :param client_id: :class:`bytes` or :class:`str` instance"""
    if isinstance(client_id, type(u'')):
        client_id = client_id.encode('utf-8')
    if not isinstance(client_id, bytes):
        raise TypeError('{!r} is not a valid consumer group (must be str or bytes)'.format(client_id))
    return client_id

def write_short_ascii(s):
    """Encode a Kafka short string which represents text.

    :param str s:
        Text string (`str` on Python 3, `str` or `unicode` on Python 2) or
        ``None``. The string will be ASCII-encoded.

    :returns: length-prefixed `bytes`
    :raises:
        `struct.error` for strings longer than 32767 characters"""
    if s is None:
        return _NULL_SHORT_STRING
    if not isinstance(s, string_types):
        raise TypeError('{!r} is not text'.format(s))
    return write_short_bytes(s.encode('ascii'))

def group_envs(envlist):
    """Group Tox environments for Travis CI builds

    Separate by Python version so that they can go in different Travis jobs:

    >>> group_envs('py37-int-snappy', 'py36-int')
    [('py36', 'int', ['py36-int']), ('py37', 'int', ['py37-int-snappy'])]

    Group unit tests and linting together:

    >>> group_envs(['py27-unit', 'py27-lint'])
    [('py27', 'unit', ['py27-unit', 'py27-lint'])]"""
    groups = {}
    for env in envlist:
        envpy, category = env.split('-')[0:2]
        if category == 'lint':
            category = 'unit'
        try:
            groups[envpy, category].append(env)
        except KeyError:
            groups[envpy, category] = [env]
    return sorted(((envpy, category, envs) for (envpy, category), envs in groups.items()))

def convert_all_videos(app_label, model_name, object_pk):
    """Automatically converts all videos of a given instance."""
    Model = apps.get_model(app_label=app_label, model_name=model_name)
    instance = Model.objects.get(pk=object_pk)
    fields = instance._meta.fields
    for field in fields:
        if isinstance(field, VideoField):
            if not getattr(instance, field.name):
                continue
            fieldfile = getattr(instance, field.name)
            convert_video(fieldfile)

def convert_video(fieldfile, force=False):
    """Converts a given video file into all defined formats."""
    instance = fieldfile.instance
    field = fieldfile.field
    filename = os.path.basename(fieldfile.path)
    source_path = fieldfile.path
    encoding_backend = get_backend()
    for options in settings.VIDEO_ENCODING_FORMATS[encoding_backend.name]:
        video_format, created = Format.objects.get_or_create(object_id=instance.pk, content_type=ContentType.objects.get_for_model(instance), field_name=field.name, format=options['name'])
        if video_format.file and (not force):
            continue
        else:
            video_format.reset_progress()
        _, target_path = tempfile.mkstemp(suffix='_{name}.{extension}'.format(**options))
        try:
            encoding = encoding_backend.encode(source_path, target_path, options['params'])
            while encoding:
                try:
                    progress = next(encoding)
                except StopIteration:
                    break
                video_format.update_progress(progress)
        except VideoEncodingError:
            video_format.delete()
            os.remove(target_path)
            continue
        video_format.file.save('{filename}_{name}.{extension}'.format(filename=filename, **options), File(open(target_path, mode='rb')))
        video_format.update_progress(100)
        os.remove(target_path)

def check_argument_type(dtype, kernel_argument, i):
    """check if the numpy.dtype matches the type used in the code"""
    types_map = {'uint8': ['uchar', 'unsigned char', 'uint8_t'], 'int8': ['char', 'int8_t'], 'uint16': ['ushort', 'unsigned short', 'uint16_t'], 'int16': ['short', 'int16_t'], 'uint32': ['uint', 'unsigned int', 'uint32_t'], 'int32': ['int', 'int32_t'], 'uint64': ['ulong', 'unsigned long', 'uint64_t'], 'int64': ['long', 'int64_t'], 'float16': ['half'], 'float32': ['float'], 'float64': ['double']}
    if dtype in types_map:
        return any([substr in kernel_argument for substr in types_map[dtype]])
    else:
        return False

def check_tune_params_list(tune_params):
    """raise an exception if a tune parameter has a forbidden name"""
    forbidden_names = ('grid_size_x', 'grid_size_y', 'grid_size_z')
    forbidden_name_substr = ('time', 'times')
    for name, param in tune_params.items():
        if name in forbidden_names:
            raise ValueError('Tune parameter ' + name + ' with value ' + str(param) + ' has a forbidden name!')
        for forbidden_substr in forbidden_name_substr:
            if forbidden_substr in name:
                raise ValueError('Tune parameter ' + name + ' with value ' + str(param) + ' has a forbidden name: not allowed to use ' + forbidden_substr + ' in tune parameter names!')

def check_restrictions(restrictions, element, keys, verbose):
    """check whether a specific instance meets the search space restrictions"""
    params = OrderedDict(zip(keys, element))
    for restrict in restrictions:
        if not eval(replace_param_occurrences(restrict, params)):
            if verbose:
                print('skipping config', get_instance_string(params), 'reason: config fails restriction')
            return False
    return True

def detect_language(lang, kernel_source):
    """attempt to detect language from the kernel_string if not specified"""
    if lang is None:
        if callable(kernel_source):
            raise TypeError('Please specify language when using a code generator function')
        kernel_string = get_kernel_string(kernel_source)
        if '__global__' in kernel_string:
            lang = 'CUDA'
        elif '__kernel' in kernel_string:
            lang = 'OpenCL'
        else:
            lang = 'C'
    return lang

def get_config_string(params, units=None):
    """return a compact string representation of a dictionary"""
    compact_str_items = []
    for k, v in params.items():
        unit = ''
        if isinstance(units, dict):
            unit = units.get(k, '')
        compact_str_items.append(k + '=' + str(v) + unit)
    compact_str = ', '.join(compact_str_items)
    return compact_str

def get_grid_dimensions(current_problem_size, params, grid_div, block_size_names):
    """compute grid dims based on problem sizes and listed grid divisors"""
    def get_dimension_divisor(divisor_list, default, params):
        if divisor_list is None:
            if default in params:
                divisor_list = [default]
            else:
                return 1
        return numpy.prod([int(eval(replace_param_occurrences(s, params))) for s in divisor_list])
    divisors = [get_dimension_divisor(d, block_size_names[i], params) for i, d in enumerate(grid_div)]
    return tuple((int(numpy.ceil(float(current_problem_size[i]) / float(d))) for i, d in enumerate(divisors)))

def get_problem_size(problem_size, params):
    """compute current problem size"""
    if isinstance(problem_size, (str, int, numpy.integer)):
        problem_size = (problem_size,)
    current_problem_size = [1, 1, 1]
    for i, s in enumerate(problem_size):
        if isinstance(s, str):
            current_problem_size[i] = int(eval(replace_param_occurrences(s, params)))
        elif isinstance(s, (int, numpy.integer)):
            current_problem_size[i] = s
        else:
            raise TypeError('Error: problem_size should only contain strings or integers')
    return current_problem_size

def get_thread_block_dimensions(params, block_size_names=None):
    """thread block size from tuning params, currently using convention"""
    if not block_size_names:
        block_size_names = default_block_size_names
    block_size_x = params.get(block_size_names[0], 256)
    block_size_y = params.get(block_size_names[1], 1)
    block_size_z = params.get(block_size_names[2], 1)
    return (int(block_size_x), int(block_size_y), int(block_size_z))

def looks_like_a_filename(kernel_source):
    """attempt to detect whether source code or a filename was passed"""
    logging.debug('looks_like_a_filename called')
    result = False
    if isinstance(kernel_source, str):
        result = True
        if len(kernel_source) > 250:
            result = False
        for c in '();{}\\':
            if c in kernel_source:
                result = False
        for s in ['__global__ ', '__kernel ', 'void ', 'float ']:
            if s in kernel_source:
                result = False
        result = result and any([s in kernel_source for s in ('.c', '.opencl', '.F')])
    logging.debug('kernel_source is a filename: %s' % str(result))
    return result

def read_file(filename):
    """return the contents of the file named filename or None if file not found"""
    if os.path.isfile(filename):
        with open(filename, 'r') as f:
            return f.read()

def replace_param_occurrences(string, params):
    """replace occurrences of the tuning params with their current value"""
    for k, v in params.items():
        string = string.replace(k, str(v))
    return string

def setup_block_and_grid(problem_size, grid_div, params, block_size_names=None):
    """compute problem size, thread block and grid dimensions for this kernel"""
    threads = get_thread_block_dimensions(params, block_size_names)
    current_problem_size = get_problem_size(problem_size, params)
    grid = get_grid_dimensions(current_problem_size, params, grid_div, block_size_names)
    return (threads, grid)

def write_file(filename, string):
    """dump the contents of string to a file called filename"""
    import sys
    if sys.version_info[0] >= 3:
        with open(filename, 'w', encoding='utf-8') as f:
            f.write(string)
    else:
        with open(filename, 'w') as f:
            f.write(string.encode('utf-8'))

def random_population(dna_size, pop_size, tune_params):
    """create a random population"""
    population = []
    for _ in range(pop_size):
        dna = []
        for i in range(dna_size):
            dna.append(random_val(i, tune_params))
        population.append(dna)
    return population

def random_val(index, tune_params):
    """return a random value for a parameter"""
    key = list(tune_params.keys())[index]
    return random.choice(tune_params[key])

def mutate(dna, dna_size, tune_params):
    """Mutate DNA with 1/mutation_chance chance"""
    dna_out = []
    mutation_chance = 10
    for i in range(dna_size):
        if int(random.random() * mutation_chance) == 1:
            dna_out.append(random_val(i, tune_params))
        else:
            dna_out.append(dna[i])
    return dna_out

def setup_method_options(method, tuning_options):
    """prepare method specific options"""
    kwargs = {}
    maxiter = numpy.prod([len(v) for v in tuning_options.tune_params.values()])
    kwargs['maxiter'] = maxiter
    if method in ['Nelder-Mead', 'Powell']:
        kwargs['maxfev'] = maxiter
    elif method == 'L-BFGS-B':
        kwargs['maxfun'] = maxiter
    if method in ['CG', 'BFGS', 'L-BFGS-B', 'TNC', 'SLSQP']:
        kwargs['eps'] = tuning_options.eps
    elif method == 'COBYLA':
        kwargs['rhobeg'] = tuning_options.eps
    return kwargs

def allocate(n, dtype=numpy.float32):
    """allocate context-portable pinned host memory"""
    return drv.pagelocked_empty(int(n), dtype, order='C', mem_flags=drv.host_alloc_flags.PORTABLE)

def acceptance_prob(old_cost, new_cost, T):
    """annealing equation, with modifications to work towards a lower value"""
    if old_cost == 1e+20:
        return 1.0
    if new_cost == 1e+20:
        return 0.0
    if new_cost < old_cost:
        return 1.0
    return np.exp((old_cost - new_cost) / old_cost / T)

def neighbor(pos, tune_params):
    """return a random neighbor of pos"""
    size = len(pos)
    pos_out = []
    for i in range(size):
        key = list(tune_params.keys())[i]
        values = tune_params[key]
        if random.random() < 0.2:
            new_value = random_val(i, tune_params)
        else:
            ind = values.index(pos[i])
            if random.random() > 0.5:
                ind += 1
            else:
                ind -= 1
            ind = min(max(ind, 0), len(values) - 1)
            new_value = values[ind]
        pos_out.append(new_value)
    return pos_out

def clock(rpc):
    """This task runs forever and notifies all clients subscribed to
    'clock' once a second."""
    while True:
        yield from rpc.notify('clock', str(datetime.datetime.now()))
        yield from asyncio.sleep(1)

def restore_schema(task, **kwargs):
    """Switches the schema back to the one from before running the task."""
    from .compat import get_public_schema_name
    schema_name = get_public_schema_name()
    include_public = True
    if hasattr(task, '_old_schema'):
        schema_name, include_public = task._old_schema
    if connection.schema_name == schema_name:
        return
    connection.set_schema(schema_name, include_public=include_public)

def set_node_attributes(G, values, name=None):
    """Set node attributes from dictionary of nodes and values

    Parameters
    ----------
    G : DyNetx Graph

    name : string
       Attribute name

    values: dict
       Dictionary of attribute values keyed by node. If `values` is not a
       dictionary, then it is treated as a single attribute value that is then
       applied to every node in `G`."""
    if name is not None:
        try:
            for n, v in values.items():
                try:
                    G.node[n][name] = values[n]
                except KeyError:
                    pass
        except AttributeError:
            for n in G:
                G.node[n][name] = values
    else:
        for n, d in values.items():
            try:
                G.node[n].update(d)
            except KeyError:
                pass

