def arctic_paginate(parser, token):
    '''Renders a Page object with pagination bar.
    Example::
        {% arctic_paginate page_obj paginator=page_obj.paginator range=10 %}
    Named Parameters::
        range - The size of the pagination bar (ie, if set to 10 then, at most,
                10 page numbers will display at any given time) Defaults to
                None, which shows all pages.
        show_first_last - Accepts "true" or "false". Determines whether or not
                          to show the first and last page links. Defaults to
                          "false"'''
    bits = token.split_contents()
    if len(bits) < 2:
        raise TemplateSyntaxError("'%s' takes at least one argument (Page object reference)" % bits[0])
    page = parser.compile_filter(bits[1])
    kwargs = {}
    bits = bits[2:]
    kwarg_re = re.compile('(\\w+)=(.+)')
    if len(bits):
        for bit in bits:
            match = kwarg_re.match(bit)
            if not match:
                raise TemplateSyntaxError('Malformed arguments to bootstrap_pagination paginate tag')
            name, value = match.groups()
            kwargs[name] = parser.compile_filter(value)
    return PaginationNode(page, kwargs)

def menu(menu_config=None, **kwargs):
    """Tranforms a menu definition into a dictionary which is a frendlier format
    to parse in a template."""
    request = kwargs.pop('request', None)
    user = kwargs.pop('user', None)
    url_full_name = ':'.join([request.resolver_match.namespace, request.resolver_match.url_name])
    if not menu_config:
        menu_config = settings.ARCTIC_MENU
    menu_dict = OrderedDict()
    for menu_entry in menu_config:
        if type(menu_entry) in (list, tuple):
            path = None
            if menu_entry[1]:
                if not view_from_url(menu_entry[1]).has_permission(user):
                    continue
                path = reverse(menu_entry[1])
            icon = None
            if len(menu_entry) >= 3 and (not type(menu_entry[2]) in (list, tuple)):
                icon = menu_entry[2]
            active_weight = len(path) if path else 0
            menu_dict[menu_entry[0]] = {'url': menu_entry[1], 'icon': icon, 'submenu': None, 'active': is_active(menu_entry, url_full_name), 'active_weight': active_weight}
            submenu = _get_submenu(menu_entry)
            if submenu:
                menu_dict[menu_entry[0]]['submenu'] = menu(submenu, user=user, request=request)
    return menu_clean(menu_dict)

def menu_clean(menu_config):
    """Make sure that only the menu item with the largest weight is active.
    If a child of a menu item is active, the parent should be active too.
    :param menu:
    :return:"""
    max_weight = -1
    for _, value in list(menu_config.items()):
        if value['submenu']:
            for _, v in list(value['submenu'].items()):
                if v['active']:
                    value['active'] = True
                    value['active_weight'] = v['active_weight']
        if value['active']:
            max_weight = max(value['active_weight'], max_weight)
    if max_weight > 0:
        for _, value in list(menu_config.items()):
            if value['active'] and value['active_weight'] < max_weight:
                value['active'] = False
    return menu_config

def find_attribute(obj, value):
    """Finds the attribute connected to the last object when a chain of
    connected objects is given in a string separated with double underscores.
    For example when a model x has a foreign key to model y and model y has
    attribute a, findattr(x, 'y__a') will return the a attribute from the y
    model that exists in x."""
    if '__' in value:
        value_list = value.split('__')
        attr = get_attribute(obj, value_list[0])
        return find_attribute(attr, '__'.join(value_list[1:]))
    return get_attribute(obj, value)

def get_attribute(obj, value):
    """Normally the result of list_items for listviews are a set of model objects.
    But when you want a GROUP_BY query (with 'values' method), than
    the result will be a dict. This method will help you find an item for
    either objects or dictionaries."""
    if type(obj) == dict:
        return dict.get(obj, value)
    else:
        return getattr(obj, value)

def find_field_meta(obj, value):
    """In a model, finds the attribute meta connected to the last object when
    a chain of  connected objects is given in a string separated with double
    underscores."""
    if '__' in value:
        value_list = value.split('__')
        child_obj = obj._meta.get_field(value_list[0]).rel.to
        return find_field_meta(child_obj, '__'.join(value_list[1:]))
    return obj._meta.get_field(value)

def get_field_class(qs, field_name):
    """Given a queryset and a field name, it will return the field's class"""
    try:
        return qs.model._meta.get_field(field_name).__class__.__name__
    except FieldDoesNotExist:
        return None

def reverse_url(url, obj, fallback_field=None):
    """Reverses a named url, in addition to the standard django reverse, it also
    accepts a list of ('named url', 'field1', 'field2', ...) and will use the
    value of the supplied fields as arguments.
    When a fallback field is given it will use it as an argument if none other
    are given."""
    args = []
    if type(url) in (list, tuple):
        named_url = url[0]
        for arg in url[1:]:
            if type(obj) is dict:
                args.append(obj[arg])
            else:
                args.append(find_attribute(obj, arg))
    else:
        if url.startswith('#'):
            return url
        named_url = url
        if obj and fallback_field:
            if type(obj) is dict:
                args = [obj[fallback_field]]
            else:
                args = [get_attribute(obj, fallback_field)]
    if fallback_field and (not args):
        return ''
    return reverse(named_url, args=args)

def arctic_setting(setting_name, valid_options=None):
    """Tries to get a setting from the django settings, if not available defaults
    to the one defined in defaults.py"""
    try:
        value = getattr(settings, setting_name)
        if valid_options and value not in valid_options:
            error_message = 'Invalid value for {}, must be one of: {}'.format(setting_name, str(valid_options))
            raise ImproperlyConfigured(error_message)
    except AttributeError:
        pass
    return getattr(settings, setting_name, getattr(defaults, setting_name))

def offset_limit(func):
    """Decorator that converts python slicing to offset and limit"""
    def func_wrapper(self, start, stop):
        offset = start
        limit = stop - start
        return func(self, offset, limit)
    return func_wrapper

def is_list_of_list(item):
    """check whether the item is list (tuple)
    and consist of list (tuple) elements"""
    if type(item) in (list, tuple) and len(item) and isinstance(item[0], (list, tuple)):
        return True
    return False

def append_query_parameter(url, parameters, ignore_if_exists=True):
    """quick and dirty appending of query parameters to a url"""
    if ignore_if_exists:
        for key in parameters.keys():
            if key + '=' in url:
                del parameters[key]
    parameters_str = '&'.join((k + '=' + v for k, v in parameters.items()))
    append_token = '&' if '?' in url else '?'
    return url + append_token + parameters_str

def run(port, like, use_json, server):
    """Search port names and numbers."""
    if not port and (not server[0]):
        raise click.UsageError('Please specify a port')
    if server[0]:
        app.run(host=server[0], port=server[1])
        return
    ports = get_ports(port, like)
    if not ports:
        sys.stderr.write("No ports found for '{0}'\n".format(port))
        return
    if use_json:
        print(json.dumps(ports, indent=4))
    else:
        table = get_table(ports)
        print(table)

def update_git_devstr(version, path=None):
    """Updates the git revision string if and only if the path is being imported
    directly from a git working copy.  This ensures that the revision number in
    the version string is accurate."""
    try:
        devstr = get_git_devstr(sha=True, show_warning=False, path=path)
    except OSError:
        return version
    if not devstr:
        return version
    if 'dev' in version:
        version_base = version.split('.dev', 1)[0]
        devstr = get_git_devstr(sha=False, show_warning=False, path=path)
        return version_base + '.dev' + devstr
    else:
        return version

def _get_repo_path(pathname, levels=None):
    """Given a file or directory name, determine the root of the git repository
    this path is under.  If given, this won't look any higher than ``levels``
    (that is, if ``levels=0`` then the given path must be the root of the git
    repository and is returned if so.

    Returns `None` if the given path could not be determined to belong to a git
    repo."""
    if os.path.isfile(pathname):
        current_dir = os.path.abspath(os.path.dirname(pathname))
    elif os.path.isdir(pathname):
        current_dir = os.path.abspath(pathname)
    else:
        return None
    current_level = 0
    while levels is None or current_level <= levels:
        if os.path.exists(os.path.join(current_dir, '.git')):
            return current_dir
        current_level += 1
        if current_dir == os.path.dirname(current_dir):
            break
        current_dir = os.path.dirname(current_dir)
    return None

def find_first_stop_codon(nucleotide_sequence):
    """Given a sequence of codons (expected to have length multiple of three),
    return index of first stop codon, or -1 if none is in the sequence."""
    n_mutant_codons = len(nucleotide_sequence) // 3
    for i in range(n_mutant_codons):
        codon = nucleotide_sequence[3 * i:3 * i + 3]
        if codon in STOP_CODONS:
            return i
    return -1

def load_maf_dataframe(path, nrows=None, raise_on_error=True, encoding=None):
    """Load the guaranteed columns of a TCGA MAF file into a DataFrame

    Parameters
    ----------
    path : str
        Path to MAF file

    nrows : int
        Optional limit to number of rows loaded

    raise_on_error : bool
        Raise an exception upon encountering an error or log an error

    encoding : str, optional
        Encoding to use for UTF when reading MAF file."""
    require_string(path, 'Path to MAF')
    n_basic_columns = len(MAF_COLUMN_NAMES)
    df = pandas.read_csv(path, comment='#', sep='\t', low_memory=False, skip_blank_lines=True, header=0, encoding=encoding)
    if len(df.columns) < n_basic_columns:
        error_message = 'Too few columns in MAF file %s, expected %d but got  %d : %s' % (path, n_basic_columns, len(df.columns), df.columns)
        if raise_on_error:
            raise ValueError(error_message)
        else:
            logging.warn(error_message)
    for expected, actual in zip(MAF_COLUMN_NAMES, df.columns):
        if expected != actual:
            if expected.lower() == actual.lower():
                df[expected] = df[actual]
                del df[actual]
            else:
                error_message = 'Expected column %s but got %s' % (expected, actual)
                if raise_on_error:
                    raise ValueError(error_message)
                else:
                    logging.warn(error_message)
    return df

def apply_to_field_if_exists(effect, field_name, fn, default):
    """Apply function to specified field of effect if it is not None,
    otherwise return default."""
    value = getattr(effect, field_name, None)
    if value is None:
        return default
    else:
        return fn(value)

def apply_to_transcript_if_exists(effect, fn, default):
    """Apply function to transcript associated with effect,
    if it exists, otherwise return default."""
    return apply_to_field_if_exists(effect=effect, field_name='transcript', fn=fn, default=default)

def number_exons_in_associated_transcript(effect):
    """Number of exons on transcript associated with effect,
    if there is one (otherwise return 0)."""
    return apply_to_transcript_if_exists(effect=effect, fn=lambda t: len(t.exons), default=0)

def cds_length_of_associated_transcript(effect):
    """Length of coding sequence of transcript associated with effect,
    if there is one (otherwise return 0)."""
    return apply_to_transcript_if_exists(effect=effect, fn=lambda t: len(t.coding_sequence) if t.complete and t.coding_sequence else 0, default=0)

def length_of_associated_transcript(effect):
    """Length of spliced mRNA sequence of transcript associated with effect,
    if there is one (otherwise return 0)."""
    return apply_to_transcript_if_exists(effect=effect, fn=lambda t: len(t.sequence), default=0)

def name_of_associated_transcript(effect):
    """Name of transcript associated with effect,
    if there is one (otherwise return "")."""
    return apply_to_transcript_if_exists(effect=effect, fn=lambda t: t.name, default='')

def gene_id_of_associated_transcript(effect):
    """Ensembl gene ID of transcript associated with effect, returns
    None if effect does not have transcript."""
    return apply_to_transcript_if_exists(effect=effect, fn=lambda t: t.gene_id, default=None)

def effect_has_complete_transcript(effect):
    """Parameters
    ----------
    effect : subclass of MutationEffect

    Returns True if effect has transcript and that transcript has complete CDS"""
    return apply_to_transcript_if_exists(effect=effect, fn=lambda t: t.complete, default=False)

def select_between_exonic_splice_site_and_alternate_effect(effect):
    """If the given effect is an ExonicSpliceSite then it might contain
    an alternate effect of higher priority. In that case, return the
    alternate effect. Otherwise, this acts as an identity function."""
    if effect.__class__ is not ExonicSpliceSite:
        return effect
    if effect.alternate_effect is None:
        return effect
    splice_priority = effect_priority(effect)
    alternate_priority = effect_priority(effect.alternate_effect)
    if splice_priority > alternate_priority:
        return effect
    else:
        return effect.alternate_effect

def top_priority_effect(effects):
    """Given a collection of variant transcript effects,
    return the top priority object. ExonicSpliceSite variants require special
    treatment since they actually represent two effects -- the splicing modification
    and whatever else would happen to the exonic sequence if nothing else gets
    changed. In cases where multiple transcripts give rise to multiple
    effects, use a variety of filtering and sorting heuristics to pick
    the canonical transcript."""
    if len(effects) == 0:
        raise ValueError('List of effects cannot be empty')
    effects = map(select_between_exonic_splice_site_and_alternate_effect, effects)
    effects_grouped_by_gene = apply_groupby(effects, fn=gene_id_of_associated_transcript, skip_none=False)
    if None in effects_grouped_by_gene:
        effects_without_genes = effects_grouped_by_gene.pop(None)
    else:
        effects_without_genes = []
    if len(effects_grouped_by_gene) > 0:
        effects_with_genes = [top_priority_effect_for_single_gene(gene_effects) for gene_effects in effects_grouped_by_gene.values()]
        return max(effects_with_genes, key=multi_gene_effect_sort_key)
    else:
        assert len(effects_without_genes) > 0
        return max(effects_without_genes, key=multi_gene_effect_sort_key)

def infer_genome(genome_object_string_or_int):
    """If given an integer, return associated human EnsemblRelease for that
    Ensembl version.

    If given a string, return latest EnsemblRelease which has a reference
    of the same name.

    If given a PyEnsembl Genome, simply return it."""
    if isinstance(genome_object_string_or_int, Genome):
        return genome_object_string_or_int
    if is_integer(genome_object_string_or_int):
        return cached_release(genome_object_string_or_int)
    elif is_string(genome_object_string_or_int):
        reference_name = infer_reference_name(genome_object_string_or_int)
        return genome_for_reference_name(reference_name)
    else:
        raise TypeError('Expected genome to be an int, string, or pyensembl.Genome instance, got %s : %s' % (str(genome_object_string_or_int), type(genome_object_string_or_int)))

def is_purine(nucleotide, allow_extended_nucleotides=False):
    """Is the nucleotide a purine"""
    if not allow_extended_nucleotides and nucleotide not in STANDARD_NUCLEOTIDES:
        raise ValueError('{} is a non-standard nucleotide, neither purine or pyrimidine'.format(nucleotide))
    return nucleotide in PURINE_NUCLEOTIDES

def pyvcf_calls_to_sample_info_list(calls):
    """Given pyvcf.model._Call instances, return a dict mapping each sample
    name to its per-sample info:
        sample name -> field -> value"""
    return OrderedDict(((call.sample, call.data._asdict()) for call in calls))

def cdna_codon_sequence_after_insertion_frameshift(sequence_from_start_codon, cds_offset_before_insertion, inserted_nucleotides):
    """Returns index of mutated codon and nucleotide sequence starting at the first
    mutated codon."""
    coding_sequence_after_insertion = sequence_from_start_codon[cds_offset_before_insertion + 1:]
    if cds_offset_before_insertion % 3 == 2:
        mutated_codon_index = cds_offset_before_insertion // 3 + 1
        nucleotides_before = ''
    elif cds_offset_before_insertion % 3 == 1:
        mutated_codon_index = cds_offset_before_insertion // 3
        nucleotides_before = sequence_from_start_codon[cds_offset_before_insertion - 1:cds_offset_before_insertion + 1]
    elif cds_offset_before_insertion % 3 == 0:
        mutated_codon_index = cds_offset_before_insertion // 3
        nucleotides_before = sequence_from_start_codon[cds_offset_before_insertion]
    sequence_from_mutated_codon = nucleotides_before + inserted_nucleotides + coding_sequence_after_insertion
    return (mutated_codon_index, sequence_from_mutated_codon)

def predict_variant_effects(variant, raise_on_error=False):
    """Determine the effects of a variant on any transcripts it overlaps.
    Returns an EffectCollection object.

    Parameters
    ----------
    variant : Variant

    raise_on_error : bool
        Raise an exception if we encounter an error while trying to
        determine the effect of this variant on a transcript, or simply
        log the error and continue."""
    if len(variant.gene_ids) == 0:
        effects = [Intergenic(variant)]
    else:
        effects = []
        transcripts_grouped_by_gene = groupby_field(variant.transcripts, 'gene_id')
        for gene_id in sorted(variant.gene_ids):
            if gene_id not in transcripts_grouped_by_gene:
                gene = variant.ensembl.gene_by_id(gene_id)
                effects.append(Intragenic(variant, gene))
            else:
                for transcript in transcripts_grouped_by_gene[gene_id]:
                    if raise_on_error:
                        effect = predict_variant_effect_on_transcript(variant=variant, transcript=transcript)
                    else:
                        effect = predict_variant_effect_on_transcript_or_failure(variant=variant, transcript=transcript)
                    effects.append(effect)
    return EffectCollection(effects)

def predict_variant_effect_on_transcript_or_failure(variant, transcript):
    """Try predicting the effect of a variant on a particular transcript but
    suppress raised exceptions by converting them into `Failure` effect
    values."""
    try:
        return predict_variant_effect_on_transcript(variant=variant, transcript=transcript)
    except (AssertionError, ValueError) as error:
        logger.warn('Encountered error annotating %s for %s: %s', variant, transcript, error)
        return Failure(variant, transcript)

def choose_intronic_effect_class(variant, nearest_exon, distance_to_exon):
    """Infer effect of variant which does not overlap any exon of
    the given transcript."""
    assert distance_to_exon > 0, 'Expected intronic effect to have distance_to_exon > 0, got %d' % (distance_to_exon,)
    if nearest_exon.strand == '+':
        start_before = variant.trimmed_base1_start < nearest_exon.start
        start_same = variant.trimmed_base1_start == nearest_exon.start
        before_exon = start_before or (variant.is_insertion and start_same)
    else:
        end_after = variant.trimmed_base1_end > nearest_exon.end
        end_same = variant.trimmed_base1_end == nearest_exon.end
        before_exon = end_after or (variant.is_insertion and end_same)
    if distance_to_exon <= 2:
        if before_exon:
            return SpliceAcceptor
        else:
            return SpliceDonor
    elif not before_exon and distance_to_exon <= 6:
        return IntronicSpliceSite
    elif before_exon and distance_to_exon <= 3:
        return IntronicSpliceSite
    else:
        return Intronic

def groupby_field(records, field_name, skip_none=True):
    """Given a list of objects, group them into a dictionary by
    the unique values of a given field name."""
    return apply_groupby(records, lambda obj: getattr(obj, field_name), skip_none=skip_none)

def memoize(fn):
    """Simple memoization decorator for functions and methods,
    assumes that all arguments to the function can be hashed and
    compared."""
    memoized_values = {}
    @wraps(fn)
    def wrapped_fn(*args, **kwargs):
        key = (args, tuple(sorted(kwargs.items())))
        try:
            return memoized_values[key]
        except KeyError:
            memoized_values[key] = fn(*args, **kwargs)
            return memoized_values[key]
    return wrapped_fn

def interval_offset_on_transcript(start, end, transcript):
    """Given an interval [start:end] and a particular transcript,
    return the start offset of the interval relative to the
    chromosomal positions of the transcript."""
    if start > end:
        raise ValueError("start_pos %d shouldn't be greater than end_pos %d" % (start, end))
    if start > transcript.end:
        raise ValueError('Range %d:%d starts after transcript %s (%d:%d)' % (start, end, transcript, transcript.start, transcript.end))
    if end < transcript.start:
        raise ValueError('Range %d:%d ends before transcript %s (%d:%d)' % (start, end, transcript, transcript.start, transcript.end))
    if start < transcript.start:
        start = transcript.start
    if end > transcript.end:
        end = transcript.end
    return min(transcript.spliced_offset(start), transcript.spliced_offset(end))

def vn(x):
    """value or none, returns none if x is an empty list"""
    if x == []:
        return None
    if isinstance(x, list):
        return '|'.join(x)
    if isinstance(x, datetime):
        return x.isoformat()
    return x

def json_serialize(obj):
    """Simple generic JSON serializer for common objects."""
    if isinstance(obj, datetime):
        return obj.isoformat()
    if hasattr(obj, 'id'):
        return jsonify(obj.id)
    if hasattr(obj, 'name'):
        return jsonify(obj.name)
    raise TypeError('{0} is not JSON serializable'.format(obj))

def json_get(serialized_object, field):
    """This emulates the HSTORE `->` get value operation.
    It get value from JSON serialized column by given key and return `null` if not present.
    Key can be either an integer for array index access or a string for object field access.

    :return: JSON serialized value of key in object"""
    if serialized_object is None:
        return None
    obj = json.loads(serialized_object)
    if obj is None:
        return None
    if isinstance(field, int):
        res = obj[field] if 0 <= field < len(obj) else None
    else:
        res = obj.get(field)
    if not isinstance(res, (int, float, string_types)):
        res = json.dumps(res)
    return res

def qualified_name(obj) -> str:
    """Return the qualified name (e.g. package.module.Type) for the given object.

    If ``obj`` is not a class, the returned name will match its type instead."""
    if not isclass(obj):
        obj = type(obj)
    if obj.__module__ == 'builtins':
        return obj.__name__
    else:
        return '{}.{}'.format(obj.__module__, obj.__qualname__)

def callable_name(func: Callable) -> str:
    """Return the qualified name (e.g. package.module.func) for the given callable."""
    if func.__module__ == 'builtins':
        return func.__name__
    else:
        return '{}.{}'.format(func.__module__, func.__qualname__)

def merge_config(original: Optional[Dict[str, Any]], overrides: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    """Return a copy of the ``original`` configuration dictionary, with overrides from ``overrides``
    applied.

    This similar to what :meth:`dict.update` does, but when a dictionary is about to be
    replaced with another dictionary, it instead merges the contents.

    If a key in ``overrides`` is a dotted path (ie. ``foo.bar.baz: value``), it is assumed to be a
    shorthand for ``foo: {bar: {baz: value}}``.

    :param original: a configuration dictionary (or ``None``)
    :param overrides: a dictionary containing overriding values to the configuration (or ``None``)
    :return: the merge result"""
    assert check_argument_types()
    copied = original.copy() if original else {}
    if overrides:
        for key, value in overrides.items():
            if '.' in key:
                key, rest = key.split('.', 1)
                value = {rest: value}
            orig_value = copied.get(key)
            if isinstance(orig_value, dict) and isinstance(value, dict):
                copied[key] = merge_config(orig_value, value)
            else:
                copied[key] = value
    return copied

def executor(arg: Union[Executor, str, Callable]=None):
    """Decorate a function so that it runs in an :class:`~concurrent.futures.Executor`.

    If a resource name is given, the first argument must be a :class:`~.Context`.

    Usage::

        @executor
        def should_run_in_executor():
            ...

    With a resource name::

        @executor('resourcename')
        def should_run_in_executor(ctx):
            ...

    :param arg: a callable to decorate, an :class:`~concurrent.futures.Executor` instance, the
        resource name of one or ``None`` to use the event loop's default executor
    :return: the wrapped function"""
    def outer_wrapper(func: Callable):
        @wraps(func)
        def inner_wrapper(*args, **kwargs):
            try:
                ctx = next((arg for arg in args[:2] if isinstance(arg, Context)))
            except StopIteration:
                raise RuntimeError('the first positional argument to {}() has to be a Context instance'.format(callable_name(func))) from None
            executor = ctx.require_resource(Executor, resource_name)
            return asyncio_extras.call_in_executor(func, *args, executor=executor, **kwargs)
        return inner_wrapper
    if isinstance(arg, str):
        resource_name = arg
        return outer_wrapper
    return asyncio_extras.threadpool(arg)

def stream_events(signals: Sequence[Signal], filter: Callable[[T_Event], bool]=None, *, max_queue_size: int=0) -> AsyncIterator[T_Event]:
    """Return an async generator that yields events from the given signals.

    Only events that pass the filter callable (if one has been given) are returned.
    If no filter function was given, all events are yielded from the generator.

    :param signals: the signals to get events from
    :param filter: a callable that takes an event object as an argument and returns ``True`` if
        the event should pass, ``False`` if not
    :param max_queue_size: maximum size of the queue, after which it will start to drop events"""
    @async_generator
    async def streamer():
        try:
            while True:
                event = await queue.get()
                if filter is None or filter(event):
                    await yield_(event)
        finally:
            cleanup()
    def cleanup():
        nonlocal queue
        if queue is not None:
            for signal in signals:
                signal.disconnect(queue.put_nowait)
            queue = None
    assert check_argument_types()
    queue = Queue(max_queue_size)
    for signal in signals:
        signal.connect(queue.put_nowait)
    gen = [streamer()]
    weakref.finalize(gen[0], cleanup)
    return gen.pop()

def deprecated(fn):
    """Mark a function as deprecated and warn the user on use."""
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        warnings.warn(fn.__doc__.split('\n')[0], category=DeprecationWarning, stacklevel=2)
        return fn(*args, **kwargs)
    return wrapper

def ArgSpec(*args, **kwargs):
    """Validate a function based on the given argspec.

    # Example:
        validations = {
            "foo": [ArgSpec("a", "b", c", bar="baz")]
        }
        def pass_func(a, b, c, bar="baz"):
            pass
        def fail_func(b, c, a, baz="bar"):
            pass
        passes = {"foo": pass_func}
        fails = {"foo": fail_func}"""
    def argspec_lambda(value):
        argspec = getargspec(value)
        argspec_kw_vals = ()
        if argspec.defaults is not None:
            argspec_kw_vals = argspec.defaults
        kw_vals = {}
        arg_offset = 0
        arg_len = len(argspec.args) - 1
        for val in argspec_kw_vals[::-1]:
            kw_vals[argspec.args[arg_len - arg_offset]] = val
            arg_offset += 1
        if kwargs == kw_vals:
            if len(args) != arg_len - arg_offset + 1:
                return False
            index = 0
            for arg in args:
                if argspec.args[index] != arg:
                    return False
                index += 1
            return True
        return False
    argspec_lambda.err_message = 'must match argspec ({0}) {{{1}}}'.format(args, kwargs)
    argspec_lambda.not_message = 'must not match argspec ({0}) {{{1}}}'.format(args, kwargs)
    return argspec_lambda

def get_first_date_for_group(start_date, group_type, n):
    """:param start:   start date
    :n          :   how many groups we want to get
    :group_type :   daily, weekly, monthly"""
    current_date = start_date
    if group_type == 'monthly':
        current_year = start_date.year
        current_month = start_date.month
        for i in range(n - 1):
            current_month -= 1
            if current_month == 0:
                current_month = 12
                current_year -= 1
        first_date = datetime.datetime(current_year, current_month, 1)
    elif group_type == 'weekly':
        first_date = start_date - datetime.timedelta(days=start_date.weekday() + (n - 1) * 7)
    elif group_type == 'daily':
        first_date = start_date - datetime.timedelta(days=n - 1)
    first_date = datetime.datetime(first_date.year, first_date.month, first_date.day, 0, 0, 0)
    return first_date

def update(d, ud):
    """Recursively merge the values of ud into d."""
    if ud is None:
        return
    for key, value in ud.items():
        if not key in d:
            d[key] = value
        elif isinstance(value, dict):
            update(d[key], value)
        else:
            d[key] = value

def get_hash(node, fields=None, exclude=['pk', '_id'], target='pk'):
    """Here we generate a unique hash for a given node in the syntax tree."""
    hasher = Hasher()
    def add_to_hash(value):
        if isinstance(value, dict):
            if target in value:
                add_to_hash(value[target])
            else:
                attribute_list = []
                for key, v in sorted(value.items(), key=lambda x: x[0]):
                    if fields is not None and key not in fields or (exclude is not None and key in exclude):
                        continue
                    add_to_hash(key)
                    add_to_hash(v)
        elif isinstance(value, (tuple, list)) and value and isinstance(value[0], (dict, node_class)):
            for i, v in enumerate(value):
                hasher.add(i)
                add_to_hash(v)
        else:
            hasher.add(value)
    add_to_hash(node)
    return hasher.digest.hexdigest()

def replace_symbol(text, replacement_text='', is_replace_consecutive_chars=False, is_strip=False):
    """Replace all of the symbols in the ``text``.

    :param str text: Input text.
    :param str replacement_text: Replacement text.
    :return: A replacement string.
    :rtype: str

    :Examples:

        :ref:`example-sanitize-symbol`"""
    try:
        new_text = __RE_SYMBOL.sub(replacement_text, preprocess(text))
    except (TypeError, AttributeError):
        raise TypeError('text must be a string')
    if not replacement_text:
        return new_text
    if is_replace_consecutive_chars:
        new_text = re.sub('{}+'.format(re.escape(replacement_text)), replacement_text, new_text)
    if is_strip:
        new_text = new_text.strip(replacement_text)
    return new_text

def convert_to_record(func):
    """Wrap mongodb record to a dict record with default value None
    """
    @functools.wraps(func)
    def wrapper(self, *args, **kwargs):
        result = func(self, *args, **kwargs)
        if result is not None:
            if isinstance(result, dict):
                return _record(result)
            return (_record(i) for i in result)
        return result
    return wrapper

def to_list_str(value, encode=None):
    """recursively convert list content into string

    :arg list value: The list that need to be converted.
    :arg function encode: Function used to encode object."""
    result = []
    for index, v in enumerate(value):
        if isinstance(v, dict):
            result.append(to_dict_str(v, encode))
            continue
        if isinstance(v, list):
            result.append(to_list_str(v, encode))
            continue
        if encode:
            result.append(encode(v))
        else:
            result.append(default_encode(v))
    return result

def to_dict_str(origin_value, encode=None):
    """recursively convert dict content into string
    """
    value = copy.deepcopy(origin_value)
    for k, v in value.items():
        if isinstance(v, dict):
            value[k] = to_dict_str(v, encode)
            continue
        if isinstance(v, list):
            value[k] = to_list_str(v, encode)
            continue
        if encode:
            value[k] = encode(v)
        else:
            value[k] = default_encode(v)
    return value

def default_encode(v):
    """convert ObjectId, datetime, date into string
    """
    if isinstance(v, ObjectId):
        return unicode_type(v)
    if isinstance(v, datetime):
        return format_time(v)
    if isinstance(v, date):
        return format_time(v)
    return v

def to_str(v, encode=None):
    """convert any list, dict, iterable and primitives object to string
    """
    if isinstance(v, basestring_type):
        return v
    if isinstance(v, dict):
        return to_dict_str(v, encode)
    if isinstance(v, Iterable):
        return to_list_str(v, encode)
    if encode:
        return encode(v)
    else:
        return default_encode(v)

def join_sys_path(currfile, dir_level_num=3):
    """find certain path then load into sys path"""
    if os.path.isdir(currfile):
        root_path = currfile
    else:
        root_path = get_base_dir(currfile, dir_level_num)
    sys.path.append(root_path)

def to_basestring(value):
    """Converts a string argument to a subclass of basestring.

    In python2, byte and unicode strings are mostly interchangeable,
    so functions that deal with a user-supplied argument in combination
    with ascii string constants can use either and should return the type
    the user supplied.  In python3, the two types are not interchangeable,
    so this method is needed to convert byte strings to unicode."""
    if isinstance(value, _BASESTRING_TYPES):
        return value
    if not isinstance(value, bytes):
        raise TypeError('Expected bytes, unicode, or None; got %r' % type(value))
    return value.decode('utf-8')

def encode_http_params(**kw):
    """url paremeter encode"""
    try:
        _fo = lambda k, v: '{name}={value}'.format(name=k, value=to_basestring(quote(v)))
    except:
        _fo = lambda k, v: '%s=%s' % (k, to_basestring(quote(v)))
    _en = utf8
    return '&'.join([_fo(k, _en(v)) for k, v in kw.items() if not is_empty(v)])

def _init_file_logger(logger, level, log_path, log_size, log_count):
    """one logger only have one level RotatingFileHandler"""
    if level not in [logging.NOTSET, logging.DEBUG, logging.INFO, logging.WARNING, logging.ERROR, logging.CRITICAL]:
        level = logging.DEBUG
    for h in logger.handlers:
        if isinstance(h, logging.handlers.RotatingFileHandler):
            if h.level == level:
                return
    fh = logging.handlers.RotatingFileHandler(log_path, maxBytes=log_size, backupCount=log_count)
    fh.setLevel(level)
    fh.setFormatter(_formatter)
    logger.addHandler(fh)

def is_local(filename, pathlist):
    """Returns True if *filename* is a subpath of any of the paths in *pathlist*."""
    filename = os.path.abspath(filename)
    for path_name in pathlist:
        path_name = os.path.abspath(path_name)
        if is_subpath(filename, path_name):
            return True
    return False

def is_subpath(path, parent):
    """Returns True if *path* points to the same or a subpath of *parent*."""
    try:
        relpath = os.path.relpath(path, parent)
    except ValueError:
        return False
    return relpath == os.curdir or not relpath.startswith(os.pardir)

def eval_pth(filename, sitedir, dest=None, imports=None):
    """Evaluates a `.pth` file (including support for `import` statements), and
    appends the result to the list *dest*. If *dest* is #None, it will fall
    back to `sys.path`.

    If *imports* is specified, it must be a list. `import` statements will not
    executed but instead appended to that list in tuples of
    (*filename*, *line*, *stmt*).

    Returns a tuple of (*dest*, *imports*)."""
    if dest is None:
        dest = sys.path
    if not os.path.isfile(filename):
        return
    with open(filename, 'r') as fp:
        for index, line in enumerate(fp):
            if line.startswith('import'):
                if imports is None:
                    exec_pth_import(filename, index + 1, line)
                else:
                    imports.append((filename, index + 1, line))
            else:
                index = line.find('#')
                if index > 0:
                    line = line[:index]
                line = line.strip()
                if not os.path.isabs(line):
                    line = os.path.join(os.path.dirname(filename), line)
                line = os.path.normpath(line)
                if line and line not in dest:
                    dest.insert(0, line)
    return dest

def _tostream(parser, obj, stream, skipprepack=False):
    """Compatible to old parsers"""
    if hasattr(parser, 'tostream'):
        return parser.tostream(obj, stream, skipprepack)
    else:
        data = parser.tobytes(obj, skipprepack)
        cls = type(parser)
        if cls not in _deprecated_parsers:
            _deprecated_parsers.add(cls)
            warnings.warn("Parser %r does not have 'tostream' interfaces" % (cls,), UserWarning)
        return stream.write(data)

def _to_str(dumped_val, encoding='utf-8', ordered=True):
    """Convert bytes in a dump value to str, allowing json encode"""
    _dict = OrderedDict if ordered else dict
    if isinstance(dumped_val, dict):
        return OrderedDict(((k, _to_str(v, encoding)) for k, v in dumped_val.items()))
    elif isinstance(dumped_val, (list, tuple)):
        return [_to_str(v, encoding) for v in dumped_val]
    elif isinstance(dumped_val, bytes):
        try:
            d = dumped_val.decode('utf-8')
        except Exception:
            d = repr(dumped_val)
        return d
    else:
        return dumped_val

def rgb2short(rgb):
    """Find the closest xterm-256 approximation to the given RGB value.
    @param rgb: Hex code representing an RGB value, eg, 'abcdef'
    @returns: String between 0 and 255, compatible with xterm.
    >>> rgb2short('123456')
    ('23', '005f5f')
    >>> rgb2short('ffffff')
    ('231', 'ffffff')
    >>> rgb2short('0DADD6') # vimeo logo
    ('38', '00afd7')"""
    incs = (0, 95, 135, 175, 215, 255)
    parts = [int(h, 16) for h in re.split('(..)(..)(..)', rgb)[1:4]]
    res = []
    for part in parts:
        i = 0
        while i < len(incs) - 1:
            s, b = (incs[i], incs[i + 1])
            if s <= part <= b:
                s1 = abs(s - part)
                b1 = abs(b - part)
                if s1 < b1:
                    closest = s
                else:
                    closest = b
                res.append(closest)
                break
            i += 1
    res = ''.join(['%02.x' % i for i in res])
    equiv = RGB2SHORT_DICT[res]
    return (equiv, res)

