def fetch_host_ip(host: str) -> str:
    """Fetch ip by host"""
    try:
        ip = socket.gethostbyname(host)
    except socket.gaierror:
        return ''
    return ip

def fetch_host_ip_and_country(host: str) -> Tuple:
    """Fetch ip and country by host"""
    ip = fetch_host_ip(host)
