def send_document(url, data, timeout=10, *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :returns: Tuple of status code (int or None) and error (exception class instance or None)"""
    logger.debug('send_document: url=%s, data=%s, timeout=%s', url, data, timeout)
    headers = CaseInsensitiveDict({'User-Agent': USER_AGENT})
    if 'headers' in kwargs:
        headers.update(kwargs.get('headers'))
    kwargs.update({'data': data, 'timeout': timeout, 'headers': headers})
    try:
        response = requests.post(url, *args, **kwargs)
        logger.debug('send_document: response status code %s', response.status_code)
        return (response.status_code, None)
    except RequestException as ex:
        logger.debug('send_document: exception %s', ex)
        return (None, ex)

def get_http_authentication(private_key: RsaKey, private_key_id: str) -> HTTPSignatureHeaderAuth:
    """Get HTTP signature authentication for a request."""
    key = private_key.exportKey()
    return HTTPSignatureHeaderAuth(headers=['(request-target)', 'user-agent', 'host', 'date'], algorithm='rsa-sha256', key=key, key_id=private_key_id)

def get_base_attributes(entity):
    """Build a dict of attributes of an entity.

    Returns attributes and their values, ignoring any properties, functions and anything that starts
    with an underscore."""
    attributes = {}
    cls = entity.__class__
    for attr, _ in inspect.getmembers(cls, lambda o: not isinstance(o, property) and (not inspect.isroutine(o))):
        if not attr.startswith('_'):
            attributes[attr] = getattr(entity, attr)
    return attributes

def pkcs7_unpad(data):
    """Remove the padding bytes that were added at point of encryption.

    Implementation copied from pyaspora:
    https://github.com/mjnovice/pyaspora/blob/master/pyaspora/diaspora/protocol.py#L209"""
    if isinstance(data, str):
        return data[0:-ord(data[-1])]
    else:
        return data[0:-data[-1]]

def validate_host(cert, name):
    """Validates host name against certificate

    @param cert: Certificate returned by host
    @param name: Actual host name used for connection
    @return: Returns true if host name matches certificate"""
    cn = None
    for t, v in cert.get_subject().get_components():
        if t == b'CN':
            cn = v
            break
    if cn == name:
        return True
    s_name = name.decode('ascii')
    for i in range(cert.get_extension_count()):
        ext = cert.get_extension(i)
        if ext.get_short_name() == b'subjectAltName':
            s = str(ext)
            if s.startswith('DNS:') and s[4:] == s_name:
                return True
    return False

def readall_fast(stm, size):
    """Slightly faster version of readall, it reads no more than two chunks.
    Meaning that it can only be used to read small data that doesn't span
    more that two packets.

    :param stm: Stream to read from, should have read method.
    :param size: Number of bytes to read.
    :return:"""
    buf, offset = stm.read_fast(size)
    if len(buf) - offset < size:
        buf = buf[offset:]
        buf += stm.recv(size - len(buf))
        return (buf, 0)
    return (buf, offset)

def _decode_num(buf):
    """Decodes little-endian integer from buffer

    Buffer can be of any size"""
    return functools.reduce(lambda acc, val: acc * 256 + tds_base.my_ord(val), reversed(buf), 0)

def dict_row_strategy(column_names):
    """Dict row strategy, rows returned as dictionaries
    """
    column_names = [name or idx for idx, name in enumerate(column_names)]
    def row_factory(row):
        return dict(zip(column_names, row))
    return row_factory

def namedtuple_row_strategy(column_names):
    """Namedtuple row strategy, rows returned as named tuples

    Column names that are not valid Python identifiers will be replaced
    with col<number>_"""
    import collections
    column_names = [name if is_valid_identifier(name) else 'col%s_' % idx for idx, name in enumerate(column_names)]
    row_class = collections.namedtuple('Row', column_names)
    def row_factory(row):
        return row_class(*row)
    return row_factory

def recordtype_row_strategy(column_names):
    """Recordtype row strategy, rows returned as recordtypes

    Column names that are not valid Python identifiers will be replaced
    with col<number>_"""
    try:
        from namedlist import namedlist as recordtype
    except ImportError:
        from recordtype import recordtype
    column_names = [name if is_valid_identifier(name) else 'col%s_' % idx for idx, name in enumerate(column_names)]
    recordtype_row_class = recordtype('Row', column_names)
    class Row(recordtype_row_class):
        def __getitem__(self, index):
            if isinstance(index, slice):
                return tuple((getattr(self, x) for x in self.__slots__[index]))
            return getattr(self, self.__slots__[index])
        def __setitem__(self, index, value):
            setattr(self, self.__slots__[index], value)
    def row_factory(row):
        return Row(*row)
    return row_factory

def _parse_connection_string(connstr):
    """MSSQL style connection string parser

    Returns normalized dictionary of connection string parameters"""
    res = {}
    for item in connstr.split(';'):
        item = item.strip()
        if not item:
            continue
        key, value = item.split('=', 1)
        key = key.strip().lower().replace(' ', '_')
        value = value.strip()
        res[key] = value
    return res

def _psutil_kill_pid(pid):
    """http://stackoverflow.com/questions/1230669/subprocess-deleting-child-processes-in-windows"""
    try:
        parent = Process(pid)
        for child in parent.children(recursive=True):
            child.kill()
        parent.kill()
    except NoSuchProcess:
        return

