def FastaIter(handle):
    """generator that returns (header, sequence) tuples from an open FASTA file handle

    Lines before the start of the first record are ignored."""
    header = None
    for line in handle:
        if line.startswith('>'):
            if header is not None:
                yield (header, ''.join(seq_lines))
            seq_lines = list()
            header = line[1:].rstrip()
        elif header is not None:
            seq_lines.append(line.strip())
    if header is not None:
        yield (header, ''.join(seq_lines))
    else:
        return

def which(file):
    """>>> which("sh") is not None
    True

    >>> which("bogus-executable-that-doesn't-exist") is None
    True"""
    for path in os.environ['PATH'].split(os.pathsep):
        if os.path.exists(os.path.join(path, file)):
            return os.path.join(path, file)
    return None

def _find_bgzip():
    """return path to bgzip if found and meets version requirements, else exception"""
    missing_file_exception = OSError if six.PY2 else FileNotFoundError
    min_bgzip_version = '.'.join(map(str, min_bgzip_version_info))
    exe = os.environ.get('SEQREPO_BGZIP_PATH', which('bgzip') or '/usr/bin/bgzip')
    try:
        bgzip_version = _get_bgzip_version(exe)
    except AttributeError:
        raise RuntimeError("Didn't find version string in bgzip executable ({exe})".format(exe=exe))
    except missing_file_exception:
        raise RuntimeError("{exe} doesn't exist; you need to install htslib (See https://github.com/biocommons/biocommons.seqrepo#requirements)".format(exe=exe))
    except Exception:
        raise RuntimeError('Unknown error while executing {exe}'.format(exe=exe))
    bgzip_version_info = tuple(map(int, bgzip_version.split('.')))
    if bgzip_version_info < min_bgzip_version_info:
        raise RuntimeError('bgzip ({exe}) {ev} is too old; >= {rv} is required; please upgrade'.format(exe=exe, ev=bgzip_version, rv=min_bgzip_version))
    logger.info('Using bgzip {ev} ({exe})'.format(ev=bgzip_version, exe=exe))
    return exe

def _reraise_with_traceback(f):
    """Call the function normally. But if the function raises an error, attach the str(traceback)
    into the function.traceback attribute, then reraise the error.
    Args:
        f: The function to run.

    Returns: A function that wraps f, attaching the traceback if an error occurred."""
    def wrap(*args, **kwargs):
        try:
            return f(*args, **kwargs)
        except Exception as e:
            traceback_str = traceback.format_exc()
            e.traceback = traceback_str
            raise e
    return wrap

def invalidate_cache_after_error(f):
    """catch any exception and invalidate internal cache with list of nodes"""
    @wraps(f)
    def wrapper(self, *args, **kwds):
        try:
            return f(self, *args, **kwds)
        except Exception:
            self.clear_cluster_nodes_cache()
            raise
    return wrapper

def humanize_placeholders(msgid):
    """Convert placeholders to the (google translate) service friendly form.

    %(name)s -> __name__
    %s       -> __item__
    %d       -> __number__"""
    return re.sub('%(?:\\((\\w+)\\))?([sd])', lambda match: '__{0}__'.format(match.group(1).lower() if match.group(1) else 'number' if match.group(2) == 'd' else 'item'), msgid)

def restore_placeholders(msgid, translation):
    """Restore placeholders in the translated message."""
    placehoders = re.findall('(\\s*)(%(?:\\(\\w+\\))?[sd])(\\s*)', msgid)
    return re.sub('(\\s*)(__[\\w]+?__)(\\s*)', lambda matches: '{0}{1}{2}'.format(placehoders[0][0], placehoders[0][1], placehoders.pop(0)[2]), translation)

def read_ssh_config(path):
