    return SshConfig(lines)

def _remap_key(key):
    """Change key into correct casing if we know the parameter"""
    if key in KNOWN_PARAMS:
        return key
    if key.lower() in known_params:
        return KNOWN_PARAMS[known_params.index(key.lower())]
    return key

def orthogonal_vector(v):
    """Return an arbitrary vector that is orthogonal to v"""
    if v[1] != 0 or v[2] != 0:
        c = (1, 0, 0)
    else:
        c = (0, 1, 0)
    return np.cross(v, c)

def get_next_triangle(mesh, T, plane, intersection, dist_tol):
    """Returns the next triangle to visit given the intersection and
    the list of unvisited triangles (T)

    We look for a triangle that is cut by the plane (2 intersections) as
    opposed to one that only touch the plane (1 vertex intersection)"""
    if intersection[0] == INTERSECT_EDGE:
        tris = mesh.triangles_for_edge(intersection[2])
    elif intersection[0] == INTERSECT_VERTEX:
        tris = mesh.triangles_for_vert(intersection[2])
    else:
        assert False, 'Invalid intersection[0] value : %d' % intersection[0]
    T = set(T)
    for tid in tris:
        if tid in T:
            intersections = compute_triangle_plane_intersections(mesh, tid, plane, dist_tol)
            if len(intersections) == 2:
                T = T.difference(tris)
                return (tid, intersections, T)
    return (None, [], T)

def _walk_polyline(tid, intersect, T, mesh, plane, dist_tol):
    """Given an intersection, walk through the mesh triangles, computing
    intersection with the cut plane for each visited triangle and adding
    those intersection to a polyline."""
    T = set(T)
    p = []
    while True:
        p.append(intersect[1])
        tid, intersections, T = get_next_triangle(mesh, T, plane, intersect, dist_tol)
        if tid is None:
            break
        assert len(intersections) == 2
        if la.norm(intersections[0][1] - p[-1]) < dist_tol:
            intersect = intersections[1]
        else:
            assert la.norm(intersections[1][1] - p[-1]) < dist_tol, '%s not close to %s' % (str(p[-1]), str(intersections))
            intersect = intersections[0]
    return (p, T)

def signed_to_float(hex: str) -> float:
    """Convert signed hexadecimal to floating value."""
    if int(hex, 16) & 32768:
        return -(int(hex, 16) & 32767) / 10
    else:
        return int(hex, 16) / 10

def encode_packet(packet: dict) -> str:
    """Construct packet string from packet dictionary.

    >>> encode_packet({
    ...     'protocol': 'newkaku',
    ...     'id': '000001',
    ...     'switch': '01',
    ...     'command': 'on',
    ... })
    '10;newkaku;000001;01;on;'"""
    if packet['protocol'] == 'rfdebug':
        return '10;RFDEBUG=' + packet['command'] + ';'
    elif packet['protocol'] == 'rfudebug':
        return '10;RFDEBUG=' + packet['command'] + ';'
    else:
        return SWITCH_COMMAND_TEMPLATE.format(node=PacketHeader.master.value, **packet)

def deserialize_packet_id(packet_id: str) -> dict:
    """Turn a packet id into individual packet components.

    >>> deserialize_packet_id('newkaku_000001_01') == {
    ...     'protocol': 'newkaku',
    ...     'id': '000001',
    ...     'switch': '01',
    ... }
    True
    >>> deserialize_packet_id('ikeakoppla_000080_0') == {
    ...     'protocol': 'ikea koppla',
    ...     'id': '000080',
    ...     'switch': '0',
    ... }
    True"""
    if packet_id == 'rflink':
        return {'protocol': UNKNOWN}
    protocol, *id_switch = packet_id.split(PACKET_ID_SEP)
    assert len(id_switch) < 3
    packet_identifiers = {'protocol': protocol_translations.get(protocol, protocol)}
    if id_switch:
        packet_identifiers['id'] = id_switch[0]
    if len(id_switch) > 1:
        packet_identifiers['switch'] = id_switch[1]
    return packet_identifiers

def decode_tx_packet(packet: str) -> dict:
    """Break packet down into primitives, and do basic interpretation.

    >>> decode_packet('10;Kaku;ID=41;SWITCH=1;CMD=ON;') == {
    ...     'node': 'gateway',
    ...     'protocol': 'kaku',
    ...     'id': '000041',
    ...     'switch': '1',
    ...     'command': 'on',
    ... }
    True"""
    node_id, protocol, attrs = packet.split(DELIM, 2)
    data = cast(Dict[str, Any], {'node': PacketHeader(node_id).name})
    data['protocol'] = protocol.lower()
    for i, attr in enumerate(filter(None, attrs.strip(DELIM).split(DELIM))):
        if i == 0:
            data['id'] = attr
        if i == 1:
            data['switch'] = attr
        if i == 2:
            data['command'] = attr
    if data.get('protocol', '') == 'kaku' and len(data['id']) != 6:
        data['id'] = '0000' + data['id']
    return data

def create_rflink_connection(port=None, host=None, baud=57600, protocol=RflinkProtocol, packet_callback=None, event_callback=None, disconnect_callback=None, ignore=None, loop=None):
    """Create Rflink manager class, returns transport coroutine."""
    protocol = partial(protocol, loop=loop if loop else asyncio.get_event_loop(), packet_callback=packet_callback, event_callback=event_callback, disconnect_callback=disconnect_callback, ignore=ignore if ignore else [])
    if host:
        conn = loop.create_connection(protocol, host, port)
    else:
        baud = baud
        conn = create_serial_connection(loop, protocol, port, baud)
    return conn

def main(argv=sys.argv[1:], loop=None):
    """Parse argument and setup main program loop."""
    args = docopt(__doc__, argv=argv, version=pkg_resources.require('rflink')[0].version)
    level = logging.ERROR
    if args['-v']:
        level = logging.INFO
    if args['-v'] == 2:
        level = logging.DEBUG
    logging.basicConfig(level=level)
    if not loop:
        loop = asyncio.get_event_loop()
    if args['--ignore']:
        ignore = args['--ignore'].split(',')
    else:
        ignore = []
    command = next((c for c in ALL_COMMANDS if args[c] is True), None)
    if command:
        protocol = PROTOCOLS['command']
    else:
        protocol = PROTOCOLS[args['-m']]
    conn = create_rflink_connection(protocol=protocol, host=args['--host'], port=args['--port'], baud=args['--baud'], loop=loop, ignore=ignore)
    transport, protocol = loop.run_until_complete(conn)
    try:
        if command:
            for _ in range(int(args['--repeat'])):
                loop.run_until_complete(protocol.send_command_ack(args['<id>'], command))
        else:
            loop.run_forever()
    except KeyboardInterrupt:
        transport.close()
        loop.run_forever()
    finally:
        loop.close()

def _next_grav_gsa(grav_initial, grav_reduction_rate, iteration, max_iterations):
    """Calculate G as given by GSA algorithm.

    In GSA paper, grav is G"""
    return grav_initial * math.exp(-grav_reduction_rate * iteration / float(max_iterations))

def _gsa_total_force(force_vectors, vector_length):
    """Return a randomly weighted sum of the force vectors.

    args:
        force_vectors: A list of force vectors on solution i.

    returns:
        numpy.array; The total force on solution i."""
    if len(force_vectors) == 0:
        return [0.0] * vector_length
    total_force = [0.0] * vector_length
    for force_vec in force_vectors:
        for i in range(vector_length):
            total_force[i] += random.uniform(0.0, 1.0) * force_vec[i]
    return total_force

def _crossover(population, crossover_chance, crossover_operator):
    """Perform crossover on a population, return the new crossed-over population."""
    new_population = []
    for i in range(0, len(population), 2):
        try:
            parents = (population[i], population[i + 1])
        except IndexError:
            parents = (population[i], population[0])
        if random.uniform(0.0, 1.0) <= crossover_chance:
            new_population.extend(crossover_operator(parents))
        else:
            new_population.extend(parents)
    return new_population

def random_real_solution(solution_size, lower_bounds, upper_bounds):
    """Make a list of random real numbers between lower and upper bounds."""
    return [random.uniform(lower_bounds[i], upper_bounds[i]) for i in range(solution_size)]

def make_population(population_size, solution_generator, *args, **kwargs):
    """Make a population with the supplied generator."""
    return [solution_generator(*args, **kwargs) for _ in range(population_size)]

def roulette_selection(population, fitnesses):
    """Create a list of parents with roulette selection."""
    probabilities = _fitnesses_to_probabilities(fitnesses)
    intermediate_population = []
    for _ in range(len(population)):
        selection = random.uniform(0.0, 1.0)
        for i, probability in enumerate(probabilities):
            if probability >= selection:
                intermediate_population.append(population[i])
                break
    return intermediate_population

def _rescale(vector):
    """Scale values in vector to the range [0, 1].

    Args:
        vector: A list of real values."""
    min_val = min(vector)
    vector = [v - min_val for v in vector]
    max_val = float(max(vector))
    try:
        return [v / max_val for v in vector]
    except ZeroDivisionError:
        return [1.0] * len(vector)

def _diversity_metric(solution, population):
    """Return diversity value for solution compared to given population.

    Metric is sum of distance between solution and each solution in population,
    normalized to [0.0, 1.0]."""
    if population == []:
        return 1.0
    return sum([_manhattan_distance(solution, other) for other in population]) / (len(population) * len(solution))

def _manhattan_distance(vec_a, vec_b):
    """Return manhattan distance between two lists of numbers."""
    if len(vec_a) != len(vec_b):
        raise ValueError('len(vec_a) must equal len(vec_b)')
    return sum(map(lambda a, b: abs(a - b), vec_a, vec_b))

def random_flip_mutate(population, mutation_chance):
    """Mutate every chromosome in a population, list is modified in place.

    Mutation occurs by randomly flipping bits (genes)."""
    for chromosome in population:
        for i in range(len(chromosome)):
            if random.uniform(0.0, 1.0) <= mutation_chance:
                chromosome[i] = 1 - chromosome[i]

def _duplicates(list_):
    """Return dict mapping item -> indices."""
    item_indices = {}
    for i, item in enumerate(list_):
        try:
            item_indices[item].append(i)
        except KeyError:
            item_indices[item] = [i]
    return item_indices

def _parse_parameter_locks(optimizer, meta_parameters, parameter_locks):
    """Synchronize meta_parameters and locked_values.

    The union of these two sets will have all necessary parameters.
    locked_values will have the parameters specified in parameter_locks."""
    locked_values = {}
    if parameter_locks:
        for name in parameter_locks:
            locked_values[name] = getattr(optimizer, name)
            meta_parameters.pop(name)
    return locked_values

def _get_hyperparameter_solution_size(meta_parameters):
    """Determine size of binary encoding of parameters.

    Also adds binary size information for each parameter."""
    solution_size = 0
    for _, parameters in meta_parameters.iteritems():
        if parameters['type'] == 'discrete':
            num_values = len(parameters['values'])
            binary_size = helpers.binary_size(num_values)
        elif parameters['type'] == 'int':
            int_range = parameters['max'] - parameters['min'] + 1
            binary_size = helpers.binary_size(int_range)
        elif parameters['type'] == 'float':
            float_range = parameters['max'] - parameters['min']
            binary_size = helpers.binary_size(float_range * 1000)
        else:
            raise ValueError('Parameter type "{}" does not match known values'.format(parameters['type']))
        parameters['binary_size'] = binary_size
        solution_size += binary_size
    return solution_size

def _make_hyperparameter_decode_func(locked_values, meta_parameters):
    """Create a function that converts the binary solution to parameters."""
    def decode(solution):
        """Convert solution into dict of hyperparameters."""
        hyperparameters = copy.deepcopy(locked_values)
        index = 0
        for name, parameters in meta_parameters.iteritems():
            binary_size = parameters['binary_size']
            binary = solution[index:index + binary_size]
            index += binary_size
            if parameters['type'] == 'discrete':
                i = helpers.binary_to_int(binary, upper_bound=len(parameters['values']) - 1)
                value = parameters['values'][i]
            elif parameters['type'] == 'int':
                value = helpers.binary_to_int(binary, lower_bound=parameters['min'], upper_bound=parameters['max'])
            elif parameters['type'] == 'float':
                value = helpers.binary_to_float(binary, lower_bound=parameters['min'], upper_bound=parameters['max'])
            else:
                raise ValueError('Parameter type "{}" does not match known values'.format(parameters['type']))
            hyperparameters[name] = value
        return hyperparameters
    return decode

def _mean_of_runs(stats, key='runs'):
    """Obtain the mean of stats.

    Args:
        stats: dict; A set of stats, structured as above.
        key: str; Optional key to determine where list of runs is found in stats"""
    num_runs = len(stats[key])
    first = stats[key][0]
    mean = {}
    for stat_key in first:
        if isinstance(first[stat_key], numbers.Number):
            mean[stat_key] = sum((run[stat_key] for run in stats[key])) / float(num_runs)
    return mean

def _sd_of_runs(stats, mean, key='runs'):
    """Obtain the standard deviation of stats.

    Args:
        stats: dict; A set of stats, structured as above.
        mean: dict; Mean for each key in stats.
        key: str; Optional key to determine where list of runs is found in stats"""
    num_runs = len(stats[key])
    first = stats[key][0]
    standard_deviation = {}
    for stat_key in first:
        if isinstance(first[stat_key], numbers.Number):
            standard_deviation[stat_key] = math.sqrt(sum(((run[stat_key] - mean[stat_key]) ** 2 for run in stats[key])) / float(num_runs))
    return standard_deviation

def _sample(probability_vec):
    """Return random binary string, with given probabilities."""
    return map(int, numpy.random.random(probability_vec.size) <= probability_vec)

def _adjust_probability_vec_best(population, fitnesses, probability_vec, adjust_rate):
    """Shift probabilities towards the best solution."""
    best_solution = max(zip(fitnesses, population))[1]
    return _adjust(probability_vec, best_solution, adjust_rate)

def benchmark_multi(optimizer):
    """Benchmark an optimizer configuration on multiple functions."""
    all_stats = benchmark.compare(optimizer, PROBLEMS, runs=100)
    return benchmark.aggregate(all_stats)

def _sample(probabilities, population_size):
    """Return a random population, drawn with regard to a set of probabilities"""
    population = []
    for _ in range(population_size):
        solution = []
        for probability in probabilities:
            if random.uniform(0.0, 1.0) < probability:
                solution.append(1)
            else:
                solution.append(0)
        population.append(solution)
    return population

def _chance(solution, pdf):
    """Return the chance of obtaining a solution from a pdf.

    The probability of many independant weighted "coin flips" (one for each bit)"""
    return _prod([1.0 - abs(bit - p) for bit, p in zip(solution, pdf)])

def _pdf_value(pdf, population, fitnesses, fitness_threshold):
    """Give the value of a pdf.

    This represents the likelihood of a pdf generating solutions
    that exceed the threshold."""
    value = 0.0
    for solution, fitness in zip(population, fitnesses):
        if fitness >= fitness_threshold:
            value += math.log(1.0 + _chance(solution, pdf))
    return value

def _update_pdf(population, fitnesses, pdfs, quantile):
    """Find a better pdf, based on fitnesses."""
    fitness_threshold = _get_quantile_cutoff(fitnesses, quantile)
    return _best_pdf(pdfs, population, fitnesses, fitness_threshold)

def _int_to_binary(integer, size=None):
    """Return bit list representation of integer.

    If size is given, binary string is padded with 0s, or clipped to the size."""
    binary_list = map(int, format(integer, 'b'))
    if size is None:
        return binary_list
    elif len(binary_list) > size:
        return binary_list[len(binary_list) - size:]
    elif size > len(binary_list):
        return [0] * (size - len(binary_list)) + binary_list
    else:
        return binary_list

def walk_tree(root):
    """Pre-order depth-first"""
    yield root
    for child in root.children:
        for el in walk_tree(child):
            yield el

def walk_up_tree(root):
    """Post-order depth-first"""
    for child in root.children:
        for el in walk_up_tree(child):
            yield el
    yield root

def make(class_name, base, schema):
    """Create a new schema aware type."""
    return type(class_name, (base,), dict(SCHEMA=schema))

def lookup(schema):
    """Lookup a class by property schema."""
    if not isinstance(schema, dict) or '$ref' not in schema:
        return None
    ref = schema['$ref']
    return REGISTRY.get(ref)

def main():
    """Continues to validate patterns until it encounters EOF within a pattern
    file or Ctrl-C is pressed by the user."""
    parser = argparse.ArgumentParser(description='Validate STIX Patterns.')
    parser.add_argument('-f', '--file', help='Specify this arg to read patterns from a file.', type=argparse.FileType('r'))
    args = parser.parse_args()
    pass_count = fail_count = 0
    import functools
    if args.file:
        nextpattern = args.file.readline
    else:
        nextpattern = functools.partial(six.moves.input, 'Enter a pattern to validate: ')
    try:
        while True:
            pattern = nextpattern()
            if not pattern:
                break
            tests_passed, err_strings = validate(pattern, True)
            if tests_passed:
                print('\nPASS: %s' % pattern)
                pass_count += 1
            else:
                for err in err_strings:
                    print(err, '\n')
                fail_count += 1
    except (EOFError, KeyboardInterrupt):
        pass
    finally:
        if args.file:
            args.file.close()
    print('\nPASSED:', pass_count, ' patterns')
    print('FAILED:', fail_count, ' patterns')

def calczeta(phi1, phi2, theta1, theta2):
    """Calculate the angular separation between position (phi1, theta1) and
    (phi2, theta2)"""
    zeta = 0.0
    if phi1 == phi2 and theta1 == theta2:
        zeta = 0.0
    else:
        argument = sin(theta1) * sin(theta2) * cos(phi1 - phi2) + cos(theta1) * cos(theta2)
        if argument < -1:
            zeta = np.pi
        elif argument > 1:
            zeta = 0.0
        else:
            zeta = acos(argument)
    return zeta

def dlmk(l, m, k, theta1):
    """returns value of d^l_mk as defined in allen, ottewill 97.
    Called by Dlmk"""
    if m >= k:
        factor = sqrt(factorial(l - k) * factorial(l + m) / factorial(l + k) / factorial(l - m))
        part2 = cos(theta1 / 2) ** (2 * l + k - m) * (-sin(theta1 / 2)) ** (m - k) / factorial(m - k)
        part3 = sp.hyp2f1(m - l, -k - l, m - k + 1, -tan(theta1 / 2) ** 2)
        return factor * part2 * part3
    else:
        return (-1) ** (m - k) * dlmk(l, k, m, theta1)

def Dlmk(l, m, k, phi1, phi2, theta1, theta2):
    """returns value of D^l_mk as defined in allen, ottewill 97."""
    return exp(complex(0.0, -m * phi1)) * dlmk(l, m, k, theta1) * exp(complex(0.0, -k * gamma(phi1, phi2, theta1, theta2)))

def gamma(phi1, phi2, theta1, theta2):
    """calculate third rotation angle
    inputs are angles from 2 pulsars
    returns the angle."""
    if phi1 == phi2 and theta1 == theta2:
        gamma = 0
    else:
        gamma = atan(sin(theta2) * sin(phi2 - phi1) / (cos(theta1) * sin(theta2) * cos(phi1 - phi2) - sin(theta1) * cos(theta2)))
    dummy_arg = cos(gamma) * cos(theta1) * sin(theta2) * cos(phi1 - phi2) + sin(gamma) * sin(theta2) * sin(phi2 - phi1) - cos(gamma) * sin(theta1) * cos(theta2)
    if dummy_arg >= 0:
        return gamma
    else:
        return pi + gamma

def real_rotated_Gammas(m, l, phi1, phi2, theta1, theta2, gamma_ml):
    """This function returns the real-valued form of the Overlap Reduction Functions,
    see Eqs 47 in Mingarelli et al, 2013."""
    if m > 0:
        ans = 1.0 / sqrt(2) * (rotated_Gamma_ml(m, l, phi1, phi2, theta1, theta2, gamma_ml) + (-1) ** m * rotated_Gamma_ml(-m, l, phi1, phi2, theta1, theta2, gamma_ml))
        return ans.real
    if m == 0:
        return rotated_Gamma_ml(0, l, phi1, phi2, theta1, theta2, gamma_ml).real
    if m < 0:
        ans = 1.0 / sqrt(2) / complex(0.0, 1) * (rotated_Gamma_ml(-m, l, phi1, phi2, theta1, theta2, gamma_ml) - (-1) ** m * rotated_Gamma_ml(m, l, phi1, phi2, theta1, theta2, gamma_ml))
        return ans.real

def chisq(psr, formbats=False):
    """Return the total chisq for the current timing solution,
    removing noise-averaged mean residual, and ignoring deleted points."""
    if formbats:
        psr.formbats()
    res, err = (psr.residuals(removemean=False)[psr.deleted == 0], psr.toaerrs[psr.deleted == 0])
    res -= numpy.sum(res / err ** 2) / numpy.sum(1 / err ** 2)
    return numpy.sum(res * res / (1e-12 * err * err))

def add_efac(psr, efac=1.0, flagid=None, flags=None, seed=None):
    """Add nominal TOA errors, multiplied by `efac` factor.
    Optionally take a pseudorandom-number-generator seed."""
    if seed is not None:
        N.random.seed(seed)
    efacvec = N.ones(psr.nobs)
    if flags is None:
        if not N.isscalar(efac):
            raise ValueError('ERROR: If flags is None, efac must be a scalar')
        else:
            efacvec = N.ones(psr.nobs) * efac
    if flags is not None and flagid is not None and (not N.isscalar(efac)):
        if len(efac) == len(flags):
            for ct, flag in enumerate(flags):
                ind = flag == N.array(psr.flagvals(flagid))
                efacvec[ind] = efac[ct]
    psr.stoas[:] += efacvec * psr.toaerrs * (1e-06 / day) * N.random.randn(psr.nobs)

def add_equad(psr, equad, flagid=None, flags=None, seed=None):
    """Add quadrature noise of rms `equad` [s].
    Optionally take a pseudorandom-number-generator seed."""
    if seed is not None:
        N.random.seed(seed)
    equadvec = N.zeros(psr.nobs)
    if flags is None:
        if not N.isscalar(equad):
            raise ValueError('ERROR: If flags is None, equad must be a scalar')
        else:
            equadvec = N.ones(psr.nobs) * equad
    if flags is not None and flagid is not None and (not N.isscalar(equad)):
        if len(equad) == len(flags):
            for ct, flag in enumerate(flags):
                ind = flag == N.array(psr.flagvals(flagid))
                equadvec[ind] = equad[ct]
    psr.stoas[:] += equadvec / day * N.random.randn(psr.nobs)

def add_jitter(psr, ecorr, flagid=None, flags=None, coarsegrain=0.1, seed=None):
    """Add correlated quadrature noise of rms `ecorr` [s],
    with coarse-graining time `coarsegrain` [days].
    Optionally take a pseudorandom-number-generator seed."""
    if seed is not None:
        N.random.seed(seed)
    if flags is None:
        t, U = quantize_fast(N.array(psr.toas(), 'd'), dt=coarsegrain)
    elif flags is not None and flagid is not None:
        t, f, U = quantize_fast(N.array(psr.toas(), 'd'), N.array(psr.flagvals(flagid)), dt=coarsegrain)
    ecorrvec = N.zeros(len(t))
    if flags is None:
        if not N.isscalar(ecorr):
            raise ValueError('ERROR: If flags is None, jitter must be a scalar')
        else:
            ecorrvec = N.ones(len(t)) * ecorr
    if flags is not None and flagid is not None and (not N.isscalar(ecorr)):
        if len(ecorr) == len(flags):
            for ct, flag in enumerate(flags):
                ind = flag == N.array(f)
                ecorrvec[ind] = ecorr[ct]
    psr.stoas[:] += 1 / day * N.dot(U * ecorrvec, N.random.randn(U.shape[1]))

def extrap1d(interpolator):
    """Function to extend an interpolation function to an
    extrapolation function.

    :param interpolator: scipy interp1d object

    :returns ufunclike: extension of function to extrapolation"""
    xs = interpolator.x
    ys = interpolator.y
    def pointwise(x):
        if x < xs[0]:
            return ys[0]
        elif x > xs[-1]:
            return ys[-1]
        else:
            return interpolator(x)
    def ufunclike(xs):
        return N.array(map(pointwise, N.array(xs)))
    return ufunclike

def expandranges(parlist):
    """Rewrite a list of parameters by expanding ranges (e.g., log10_efac{1-10}) into
    individual parameters."""
    ret = []
    for par in parlist:
        m = re.match('(.*)\\{([0-9]+)\\-([0-9]+)\\}', par)
        if m is None:
            ret.append(par)
        else:
            root, number1, number2 = (m.group(1), m.group(2), m.group(3))
            fmt = '{{0}}{{1:0{0}d}}'.format(len(number1)) if number1[0] == '0' else '{0}{1:d}'
            ret = ret + [fmt.format(root, i) for i in range(int(m.group(2)), int(m.group(3)) + 1)]
    return ret

def _findrange(parlist, roots=['JUMP', 'DMXR1_', 'DMXR2_', 'DMX_', 'efac', 'log10_efac']):
    """Rewrite a list of parameters name by detecting ranges (e.g., JUMP1, JUMP2, ...)
    and compressing them."""
    rootdict = {root: [] for root in roots}
    res = []
    for par in parlist:
        found = False
        for root in roots:
            if len(par) > len(root) and par[:len(root)] == root:
                rootdict[root].append(int(par[len(root):]))
                found = True
        if not found:
            res.append(par)
    for root in roots:
        if rootdict[root]:
            if len(rootdict[root]) > 1:
                rmin, rmax = (min(rootdict[root]), max(rootdict[root]))
                res.append('{0}{{{1}-{2}}}{3}'.format(root, rmin, rmax, '(incomplete)' if rmax - rmin != len(rootdict[root]) - 1 else ''))
            else:
                res.append('{0}{1}'.format(root, rootdict[root][0]))
    return res

def cull(data, index, min=None, max=None):
    """Sieve an emcee clouds by excluding walkers with search variable 'index'
    smaller than 'min' or larger than 'max'."""
    ret = data
    if min is not None:
        ret = ret[ret[:, index] > min, :]
    if max is not None:
        ret = ret[ret[:, index] < max, :]
    return ret

def dict_to_numpy_dict(obj_dict):
    """Convert a dictionary of lists into a dictionary of numpy arrays"""
    return {key: np.asarray(value) if value is not None else None for key, value in obj_dict.items()}

def rec_dict_to_numpy_dict(obj_dict):
    """Same as dict_to_numpy_dict, but recursive"""
    if type(obj_dict) == dict:
        return {key: rec_dict_to_numpy_dict(value) if value is not None else None for key, value in obj_dict.items()}
    elif obj_dict is None:
        return None
    else:
        return np.asarray(obj_dict)

def compare_numpy_dict(a, b, exact=True):
    """Compare two recursive numpy dictionaries"""
    if type(a) != type(b) and type(a) != np.ndarray and (type(b) != np.ndarray):
        return False
    if type(a) == dict and type(b) == dict:
        if not a.keys() == b.keys():
            return False
        for key in a.keys():
            res = compare_numpy_dict(a[key], b[key], exact)
            if res == False:
                print('false for key = ', key)
                return False
        return True
    if type(a) == np.ndarray or type(b) == np.ndarray:
        if exact:
            return (a == b).all()
        else:
            return np.testing.assert_almost_equal(a, b)
    if a is None and b is None:
        return True
    raise NotImplementedError

def auc(y_true, y_pred, round=True):
    """Area under the ROC curve
    """
    y_true, y_pred = _mask_value_nan(y_true, y_pred)
    if round:
        y_true = y_true.round()
    if len(y_true) == 0 or len(np.unique(y_true)) < 2:
        return np.nan
    return skm.roc_auc_score(y_true, y_pred)

def auprc(y_true, y_pred):
    """Area under the precision-recall curve
    """
    y_true, y_pred = _mask_value_nan(y_true, y_pred)
    precision, recall, _ = skm.precision_recall_curve(y_true, y_pred)
    return skm.auc(recall, precision)

def accuracy(y_true, y_pred, round=True):
    """Classification accuracy
    """
    y_true, y_pred = _mask_value_nan(y_true, y_pred)
    if round:
        y_true = np.round(y_true)
        y_pred = np.round(y_pred)
    return skm.accuracy_score(y_true, y_pred)

def tpr(y_true, y_pred, round=True):
    """True positive rate `tp / (tp + fn)`
    """
    y_true, y_pred = _mask_value_nan(y_true, y_pred)
    if round:
        y_true = np.round(y_true)
        y_pred = np.round(y_pred)
    return skm.recall_score(y_true, y_pred)

def tnr(y_true, y_pred, round=True):
    """True negative rate `tn / (tn + fp)`
    """
    y_true, y_pred = _mask_value_nan(y_true, y_pred)
    if round:
        y_true = np.round(y_true)
        y_pred = np.round(y_pred)
    c = skm.confusion_matrix(y_true, y_pred)
    return c[0, 0] / c[0].sum()

def mcc(y_true, y_pred, round=True):
    """Matthews correlation coefficient
    """
    y_true, y_pred = _mask_value_nan(y_true, y_pred)
    if round:
        y_true = np.round(y_true)
        y_pred = np.round(y_pred)
    return skm.matthews_corrcoef(y_true, y_pred)

def cat_acc(y_true, y_pred):
    """Categorical accuracy
    """
    return np.mean(y_true.argmax(axis=1) == y_pred.argmax(axis=1))

def mad(y_true, y_pred):
    """Median absolute deviation
    """
    y_true, y_pred = _mask_nan(y_true, y_pred)
    return np.mean(np.abs(y_true - y_pred))

def mse(y_true, y_pred):
    """Mean squared error
    """
    y_true, y_pred = _mask_nan(y_true, y_pred)
    return ((y_true - y_pred) ** 2).mean(axis=None)

def tpr(y, z):
    """True positive rate `tp / (tp + fn)`
    """
    tp, tn, fp, fn = contingency_table(y, z)
    return tp / (tp + fn)

def tnr(y, z):
    """True negative rate `tn / (tn + fp)`
    """
    tp, tn, fp, fn = contingency_table(y, z)
    return tn / (tn + fp)

def fpr(y, z):
    """False positive rate `fp / (fp + tn)`
    """
    tp, tn, fp, fn = contingency_table(y, z)
    return fp / (fp + tn)

def fnr(y, z):
    """False negative rate `fn / (fn + tp)`
    """
    tp, tn, fp, fn = contingency_table(y, z)
    return fn / (fn + tp)

def precision(y, z):
    """Precision `tp / (tp + fp)`
    """
    tp, tn, fp, fn = contingency_table(y, z)
    return tp / (tp + fp)

def fdr(y, z):
    """False discovery rate `fp / (tp + fp)`
    """
    tp, tn, fp, fn = contingency_table(y, z)
    return fp / (tp + fp)

def accuracy(y, z):
    """Classification accuracy `(tp + tn) / (tp + tn + fp + fn)`
    """
    tp, tn, fp, fn = contingency_table(y, z)
    return (tp + tn) / (tp + tn + fp + fn)

def f1(y, z):
    """F1 score: `2 * (p * r) / (p + r)`, where p=precision and r=recall.
    """
    _recall = recall(y, z)
    _prec = precision(y, z)
    return 2 * (_prec * _recall) / (_prec + _recall)

def mcc(y, z):
    """Matthews correlation coefficient
    """
    tp, tn, fp, fn = contingency_table(y, z)
    return (tp * tn - fp * fn) / K.sqrt((tp + fp) * (tp + fn) * (tn + fp) * (tn + fn))

def split_KFold_idx(train, cv_n_folds=5, stratified=False, random_state=None):
    """Get k-fold indices generator
    """
    test_len(train)
    y = train[1]
    n_rows = y.shape[0]
    if stratified:
        if len(y.shape) > 1:
            if y.shape[1] > 1:
                raise ValueError("Can't use stratified K-fold with multi-column response variable")
            else:
                y = y[:, 0]
        return model_selection.StratifiedKFold(n_splits=cv_n_folds, shuffle=True, random_state=random_state).split(X=np.zeros((n_rows, 1)), y=y)
    else:
        return model_selection.KFold(n_splits=cv_n_folds, shuffle=True, random_state=random_state).split(X=np.zeros((n_rows, 1)))

