    return True

def _truncated_normal(mean, stddev, seed=None, normalize=True, alpha=0.01):
    """Add noise with truncnorm from numpy.
    Bounded (0.001,0.999)"""
    if seed is not None:
        np.random.seed(seed)
    if stddev == 0:
        X = mean
    else:
        gen_X = truncnorm((alpha - mean) / stddev, (1 - alpha - mean) / stddev, loc=mean, scale=stddev)
        X = gen_X.rvs() + mean
        if normalize:
            col_sums = X.sum(1)
            X = X / col_sums[:, np.newaxis]
    return X

def add_letter_to_axis(ax, let, col, x, y, height):
    """Add 'let' with position x,y and height height to matplotlib axis 'ax'.
    """
    if len(let) == 2:
        colors = [col, 'white']
    elif len(let) == 1:
        colors = [col]
    else:
        raise ValueError('3 or more Polygons are not supported')
    for polygon, color in zip(let, colors):
        new_polygon = affinity.scale(polygon, yfact=height, origin=(0, 0, 0))
        new_polygon = affinity.translate(new_polygon, xoff=x, yoff=y)
        patch = PolygonPatch(new_polygon, edgecolor=color, facecolor=color)
        ax.add_patch(patch)
    return

