def parse_version(ver, pre=False):
    """Parse version into a comparable Version tuple."""
    m = RE_VER.match(ver)
    major = int(m.group('major'))
    minor = int(m.group('minor')) if m.group('minor') else 0
    micro = int(m.group('micro')) if m.group('micro') else 0
    if m.group('type'):
        release = PRE_REL_MAP[m.group('type')]
        pre = int(m.group('pre'))
    else:
        release = 'final'
        pre = 0
    dev = m.group('dev') if m.group('dev') else 0
    if m.group('dev'):
        dev = int(m.group('dev'))
        release = '.dev-' + release if pre else '.dev'
    else:
        dev = 0
    post = int(m.group('post')) if m.group('post') else 0
    return Version(major, minor, micro, release, pre, post, dev)

def lower(string):
    """Lower."""
    new_string = []
    for c in string:
        o = ord(c)
        new_string.append(chr(o + 32) if UC_A <= o <= UC_Z else c)
    return ''.join(new_string)

def upper(string):
    """Lower."""
    new_string = []
    for c in string:
        o = ord(c)
        new_string.append(chr(o - 32) if LC_A <= o <= LC_Z else c)
    return ''.join(new_string)

def uord(c):
    """Get Unicode ordinal."""
    if len(c) == 2:
        high, low = [ord(p) for p in c]
        ordinal = (high - 55296) * 1024 + low - 56320 + 65536
    else:
        ordinal = ord(c)
    return ordinal

def deprecated(message, stacklevel=2):
    """Raise a `DeprecationWarning` when wrapped function/method is called.

    Borrowed from https://stackoverflow.com/a/48632082/866026"""
    def _decorator(func):
        @wraps(func)
        def _func(*args, **kwargs):
            warnings.warn("'{}' is deprecated. {}".format(func.__name__, message), category=DeprecationWarning, stacklevel=stacklevel)
            return func(*args, **kwargs)
        return _func
    return _decorator

def warn_deprecated(message, stacklevel=2):
    """Warn deprecated."""
    warnings.warn(message, category=DeprecationWarning, stacklevel=stacklevel)

def compile(pattern, namespaces=None, flags=0, **kwargs):
    """Compile CSS pattern."""
    if namespaces is not None:
        namespaces = ct.Namespaces(**namespaces)
    custom = kwargs.get('custom')
    if custom is not None:
        custom = ct.CustomSelectors(**custom)
    if isinstance(pattern, SoupSieve):
        if flags:
            raise ValueError("Cannot process 'flags' argument on a compiled selector list")
        elif namespaces is not None:
            raise ValueError("Cannot process 'namespaces' argument on a compiled selector list")
        elif custom is not None:
            raise ValueError("Cannot process 'custom' argument on a compiled selector list")
        return pattern
    return cp._cached_css_compile(pattern, namespaces, custom, flags)

