def _raise_exception(cls, reason, data=None):
    """Raise aiohttp exception and pass payload/reason into it."""
    text_dict = {'error': reason}
    if data is not None:
        text_dict['errors'] = data
    raise cls(text=json.dumps(text_dict), content_type='application/json')

def _validate_data(data, schema, validator_cls):
    """Validate the dict against given schema (using given validator class)."""
    validator = validator_cls(schema)
    _errors = defaultdict(list)
    for err in validator.iter_errors(data):
        path = err.schema_path
        if 'properties' in path:
            path.remove('properties')
        key = path.popleft()
        if key == 'required':
            key = err.message.split("'")[1]
        _errors[key].append(str(err))
    if _errors:
        _raise_exception(web.HTTPBadRequest, 'Request is invalid; There are validation errors.', _errors)

def parse(text):
    """Parse the given text into metadata and strip it for a Markdown parser.

    :param text: text to be parsed"""
    rv = {}
    m = META.match(text)
    while m:
        key = m.group(1)
        value = m.group(2)
        value = INDENTATION.sub('\n', value.strip())
        rv[key] = value
        text = text[len(m.group(0)):]
        m = META.match(text)
    return (rv, text)

