def normalizeURL(url):
    """Normalize a URL, converting normalization failures to
    DiscoveryFailure"""
    try:
        normalized = urinorm.urinorm(url)
    except ValueError as why:
        raise DiscoveryFailure('Normalizing identifier: %s' % (why,), None)
    else:
        return urllib.parse.urldefrag(normalized)[0]

def parseXRDS(text):
    """Parse the given text as an XRDS document.

    @return: ElementTree containing an XRDS document

    @raises XRDSError: When there is a parse error or the document does
        not contain an XRDS."""
    try:
        bytestring = text.encode('utf8') if isinstance(text, str) else text
        element = SafeElementTree.XML(bytestring)
    except (SystemExit, MemoryError, AssertionError, ImportError):
        raise
    except Exception as why:
        exc = XRDSError('Error parsing document as XML')
        exc.reason = why
        raise exc
    else:
        tree = ElementTree.ElementTree(element)
        if not isXRDS(tree):
            raise XRDSError('Not an XRDS document')
        return tree

def importSafeElementTree(module_names=None):
    """Find a working ElementTree implementation that is not vulnerable
    to XXE, using `defusedxml`.

    >>> XXESafeElementTree = importSafeElementTree()

    @param module_names: The names of modules to try to use as
        a safe ElementTree. Defaults to C{L{xxe_safe_elementtree_modules}}

    @returns: An ElementTree module that is not vulnerable to XXE."""
    if module_names is None:
        module_names = xxe_safe_elementtree_modules
    try:
        return importElementTree(module_names)
    except ImportError:
        raise ImportError('Unable to find a ElementTree module that is not vulnerable to XXE. Tried importing %r' % (module_names,))

def appendArgs(url, args):
    """Append query arguments to a HTTP(s) URL. If the URL already has
    query arguemtns, these arguments will be added, and the existing
    arguments will be preserved. Duplicate arguments will not be
    detected or collapsed (both will appear in the output).

    @param url: The url to which the arguments will be appended
    @type url: str

    @param args: The query arguments to add to the URL. If a
        dictionary is passed, the items will be sorted before
        appending them to the URL. If a sequence of pairs is passed,
        the order of the sequence will be preserved.
    @type args: A dictionary from string to string, or a sequence of
        pairs of strings.

    @returns: The URL with the parameters added
    @rtype: str"""
    if hasattr(args, 'items'):
        args = sorted(args.items())
    else:
        args = list(args)
    if not isinstance(url, str):
        url = str(url, encoding='utf-8')
    if not args:
        return url
    if '?' in url:
        sep = '&'
    else:
        sep = '?'
    i = 0
    for k, v in args:
        if not isinstance(k, bytes):
            k = k.encode('utf-8')
        if not isinstance(v, bytes):
            v = v.encode('utf-8')
        args[i] = (k, v)
        i += 1
    return '%s%s%s' % (url, sep, urlencode(args))

def toBase64(s):
    """Represent string / bytes s as base64, omitting newlines"""
    if isinstance(s, str):
        s = s.encode('utf-8')
    return binascii.b2a_base64(s)[:-1]

def findLinksRel(link_attrs_list, target_rel):
    """Filter the list of link attributes on whether it has target_rel
    as a relationship."""
    matchesTarget = lambda attrs: linkHasRel(attrs, target_rel)
    return list(filter(matchesTarget, link_attrs_list))

def _appendArgs(url, args):
    """Append some arguments to an HTTP query.
    """
    if hasattr(args, 'items'):
        args = list(args.items())
        args.sort()
    if len(args) == 0:
        return url
    if '?' in url.rstrip('?'):
        sep = '&'
    else:
        sep = '?'
    return '%s%s%s' % (url, sep, urlencode(args))

def iriToURI(iri):
    """Transform an IRI to a URI by escaping unicode."""
    if isinstance(iri, bytes):
        iri = str(iri, encoding='utf-8')
    return iri.encode('ascii', errors='oid_percent_escape').decode()

def server(request):
    """Respond to requests for the server's primary web page."""
    return render_to_response('server/index.html', {'user_url': getViewURL(request, idPage), 'server_xrds_url': getViewURL(request, idpXrds)}, context_instance=RequestContext(request))

def displayResponse(request, openid_response):
    """Display an OpenID response.  Errors will be displayed directly to
    the user; successful responses and other protocol-level messages
    will be sent using the proper mechanism (i.e., direct response,
    redirection, etc.)."""
    s = getServer(request)
    try:
        webresponse = s.encodeResponse(openid_response)
    except EncodingError as why:
        text = why.response.encodeToKVForm()
        return render_to_response('server/endpoint.html', {'error': cgi.escape(text)}, context_instance=RequestContext(request))
    r = http.HttpResponse(webresponse.body)
    r.status_code = webresponse.code
    for header, value in webresponse.headers.items():
        r[header] = value
    return r

def _removeIfPresent(filename):
    """Attempt to remove a file, returning whether the file existed at
    the time of the call.

    str -> bool"""
    try:
        os.unlink(filename)
    except OSError as why:
        if why.errno == ENOENT:
            return 0
        else:
            raise
    else:
        return 1

def mkCompoundFilter(parts):
    """Create a filter out of a list of filter-like things

    Used by mkFilter

    @param parts: list of filter, endpoint, callable or list of any of these"""
    transformers = []
    filters = []
    for subfilter in parts:
        try:
            subfilter = list(subfilter)
        except TypeError:
            if hasattr(subfilter, 'getServiceEndpoints'):
                filters.append(subfilter)
            elif hasattr(subfilter, 'fromBasicServiceEndpoint'):
                transformers.append(subfilter.fromBasicServiceEndpoint)
            elif isinstance(subfilter, collections.Callable):
                transformers.append(subfilter)
            else:
                raise filter_type_error
        else:
            filters.append(mkCompoundFilter(subfilter))
    if transformers:
        filters.append(TransformFilterMaker(transformers))
    if len(filters) == 1:
        return filters[0]
    else:
        return CompoundFilter(filters)

def cron(cronline, venusian_category='irc3.plugins.cron'):
    """main decorator"""
    def wrapper(func):
        def callback(context, name, ob):
            obj = context.context
            crons = obj.get_plugin(Crons)
            if info.scope == 'class':
                callback = getattr(obj.get_plugin(ob), func.__name__)
            else:
                callback = irc3.utils.wraps_with_context(func, obj)
            crons.add_cron(cronline, callback)
        info = venusian.attach(func, callback, category=venusian_category)
        return func
    return wrapper

def dcc_event(regexp, callback=None, iotype='in', venusian_category='irc3.dcc'):
    """Work like :class:`~irc3.dec.event` but occurs during DCC CHATs"""
    return event(regexp, callback=callback, iotype='dcc_' + iotype, venusian_category=venusian_category)

def split_message(message, max_length):
    """Split long messages"""
    if len(message) > max_length:
        for message in textwrap.wrap(message, max_length):
            yield message
    else:
        yield message.rstrip(STRIPPED_CHARS)

def parse_config(main_section, *filenames):
    """parse config files"""
    filename = filenames[-1]
    filename = os.path.abspath(filename)
    here = os.path.dirname(filename)
    defaults = dict(here=here, hash='#')
    defaults['#'] = '#'
    config = configparser.ConfigParser(defaults, allow_no_value=False, interpolation=configparser.ExtendedInterpolation())
    config.optionxform = str
    config.read([os.path.expanduser('~/.irc3/passwd.ini')] + list(filenames))
    value = {}
    for s in config.sections():
        items = {}
        for k, v in config.items(s):
            if '\n' in v:
                v = as_list(v)
            elif v.isdigit():
                v = int(v)
            elif v.replace('.', '').isdigit() and v.count('.') == 1:
                v = float(v)
            elif v in ('true', 'false'):
                v = v == 'true' and True or False
            items[k] = v
        if s == main_section:
            value.update(items)
        else:
            for k in ('here', 'config'):
                items.pop(k, '')
            value[s] = items
    value.update(defaults)
    value['configfiles'] = filenames
    return value

def extract_config(config, prefix):
    """return all keys with the same prefix without the prefix"""
    prefix = prefix.strip('.') + '.'
    plen = len(prefix)
    value = {}
    for k, v in config.items():
        if k.startswith(prefix):
            value[k[plen:]] = v
    return value

def maybedotted(name):
    """Resolve dotted names:

    .. code-block:: python

        >>> maybedotted('irc3.config')
        <module 'irc3.config' from '...'>
        >>> maybedotted('irc3.utils.IrcString')
        <class 'irc3.utils.IrcString'>

    .."""
    if not name:
        raise LookupError('Not able to resolve %s' % name)
    if not hasattr(name, '__name__'):
        try:
            mod = importlib.import_module(name)
        except ImportError:
            attr = None
            if '.' in name:
                names = name.split('.')
                attr = names.pop(-1)
                try:
                    mod = maybedotted('.'.join(names))
                except LookupError:
                    attr = None
                else:
                    attr = getattr(mod, attr, None)
            if attr is not None:
                return attr
            raise LookupError('Not able to resolve %s' % name)
        else:
            return mod
    return name

def decode(tagstring):
    """Decodes a tag-string from an IRC-message into a python dictionary.
    See IRC Message Tags: http://ircv3.net/specs/core/message-tags-3.2.html

    >>> from pprint import pprint
    >>> pprint(decode('key=value'))
    {'key': 'value'}

    >>> pprint(decode('aaa=bbb;ccc;example.com/ddd=eee'))
    {'aaa': 'bbb', 'ccc': None, 'example.com/ddd': 'eee'}

    >>> s = r'key=value\\:with\\sspecial\\\\characters;key2=with=equals'
    >>> pprint(decode(s))
    {'key': 'value;with special\\\\characters', 'key2': 'with=equals'}
    >>> print(decode(s)['key'])
    value;with special\\characters

    >>> print(decode(r'key=\\\\something')['key'])
    \\something"""
    if not tagstring:
        return {}
    tags = {}
    for tag in tagstring.split(';'):
        key, value = (tag.split('=', 1) + [None])[:2]
        if not _valid_key.match(key):
            raise ValueError('invalid tag key: ' + key)
        if value:
            if not _valid_escaped_value.match(value):
                raise ValueError('invalid escaped tag value: ' + value)
            value = _unescape(value)
        tags[key] = value
    return tags

def auto_retweet(bot):
    """retweet author tweets about irc3 and pypi releases"""
    conn = bot.get_social_connection(id='twitter')
    dirname = os.path.expanduser('~/.irc3/twitter/{nick}'.format(**bot.config))
    if not os.path.isdir(dirname):
        os.makedirs(dirname)
    filename = os.path.join(dirname, 'retweeted')
    if os.path.isfile(filename):
        with open(filename) as fd:
            retweeted = [i.strip() for i in fd.readlines()]
    else:
        retweeted = []
    for user in ('pypi', 'gawel_'):
        results = conn.search.tweets(q=user + ' AND irc3', result_type='recent')
        for item in results.get('statuses', []):
            if item['user']['screen_name'] == user:
                if item['id_str'] not in retweeted:
                    res = conn(getattr(conn.statuses.retweet, item['id_str']))
                    if 'id' in res:
                        with open(filename, 'a+') as fd:
                            fd.write(item['id_str'] + '\n')

def fetch(args):
    """fetch a feed"""
    session = args['session']
    for feed, filename in zip(args['feeds'], args['filenames']):
        try:
            resp = session.get(feed, timeout=5)
            content = resp.content
        except Exception:
            pass
        else:
            with open(filename, 'wb') as fd:
                fd.write(content)
    return args['name']

def parse(feedparser, args):
    """parse a feed using feedparser"""
    entries = []
    args = irc3.utils.Config(args)
    max_date = datetime.datetime.now() - datetime.timedelta(days=2)
    for filename in args['filenames']:
        try:
            with open(filename + '.updated') as fd:
                updated = fd.read().strip()
        except (OSError, IOError):
            updated = '0'
        feed = feedparser.parse(filename)
        for e in feed.entries:
            if e.updated <= updated:
                continue
            try:
                updated_parsed = e.updated_parsed
            except AttributeError:
                continue
            if datetime.datetime(*updated_parsed[:7]) < max_date:
                continue
            e['filename'] = filename
            e['feed'] = args
            entries.append((e.updated, e))
        if entries:
            entries = sorted(entries, key=itemgetter(0))
            with open(filename + '.updated', 'w') as fd:
                fd.write(str(entries[-1][0]))
    return entries

def extend(func):
    """same as :func:`~irc3.dec.extend` but for servers"""
    def callback(context, name, ob):
        obj = context.context
        if info.scope == 'class':
            @functools.wraps(func)
            def f(self, *args, **kwargs):
                plugin = obj.get_plugin(ob)
                return getattr(plugin, func.__name__)(*args, **kwargs)
            setattr(obj, func.__name__, f.__get__(obj, obj.__class__))
        else:
            setattr(obj, func.__name__, func.__get__(obj, obj.__class__))
    info = venusian.attach(func, callback, category='irc3d.extend')
    return func

def null(alphabet):
    """An FSM accepting nothing (not even the empty string). This is
    demonstrates that this is possible, and is also extremely useful
    in some situations"""
    return fsm(alphabet=alphabet, states={0}, initial=0, finals=set(), map={0: dict([(symbol, 0) for symbol in alphabet])})

def parallel(fsms, test):
    """Crawl several FSMs in parallel, mapping the states of a larger meta-FSM.
    To determine whether a state in the larger FSM is final, pass all of the
    finality statuses (e.g. [True, False, False] to `test`."""
    alphabet = set().union(*[fsm.alphabet for fsm in fsms])
    initial = dict([(i, fsm.initial) for i, fsm in enumerate(fsms)])
    def follow(current, symbol):
        next = {}
        for i in range(len(fsms)):
            if symbol not in fsms[i].alphabet and anything_else in fsms[i].alphabet:
                actual_symbol = anything_else
            else:
                actual_symbol = symbol
            if i in current and current[i] in fsms[i].map and (actual_symbol in fsms[i].map[current[i]]):
                next[i] = fsms[i].map[current[i]][actual_symbol]
        if len(next.keys()) == 0:
            raise OblivionError
        return next
    def final(state):
        accepts = [i in state and state[i] in fsm.finals for i, fsm in enumerate(fsms)]
        return test(accepts)
    return crawl(alphabet, initial, final, follow).reduce()

def crawl(alphabet, initial, final, follow):
    """Given the above conditions and instructions, crawl a new unknown FSM,
    mapping its states, final states and transitions. Return the new FSM.
    This is a pretty powerful procedure which could potentially go on
    forever if you supply an evil version of follow()."""
    states = [initial]
    finals = set()
    map = {}
    i = 0
    while i < len(states):
        state = states[i]
        if final(state):
            finals.add(i)
        map[i] = {}
        for symbol in sorted(alphabet, key=key):
            try:
                next = follow(state, symbol)
                try:
                    j = states.index(next)
                except ValueError:
                    j = len(states)
                    states.append(next)
            except OblivionError:
                continue
            map[i][symbol] = j
        i += 1
    return fsm(alphabet=alphabet, states=range(len(states)), initial=0, finals=finals, map=map)

def reduce_after(method):
    """reduce() the result of this method call (unless you already reduced it)."""
    def new_method(self, *args, **kwargs):
        result = method(self, *args, **kwargs)
        if result == self:
            return result
        return result.reduce()
    return new_method

def call_fsm(method):
    """Take a method which acts on 0 or more regular expression objects... return a
    new method which simply converts them all to FSMs, calls the FSM method
    on them instead, then converts the result back to a regular expression.
    We do this for several of the more annoying operations."""
    fsm_method = getattr(fsm.fsm, method.__name__)
    def new_method(*legos):
        alphabet = set().union(*[lego.alphabet() for lego in legos])
        return from_fsm(fsm_method(*[lego.to_fsm(alphabet) for lego in legos]))
    return new_method

def mkdir_p(path):
    """mkdir -p path"""
    if PY3:
        return os.makedirs(path, exist_ok=True)
    try:
        os.makedirs(path)
    except OSError as exc:
        if exc.errno == errno.EEXIST and os.path.isdir(path):
            pass
        else:
            raise

def _events_available_in_scheduled_slot(events, slots, X, **kwargs):
    """Constraint that ensures that an event is scheduled in slots for which it is
    available"""
    slot_availability_array = lpu.slot_availability_array(slots=slots, events=events)
    label = 'Event scheduled when not available'
    for row, event in enumerate(slot_availability_array):
        for col, availability in enumerate(event):
            if availability == 0:
                yield Constraint(f'{label} - event: {row}, slot: {col}', X[row, col] <= availability)

def _events_available_during_other_events(events, slots, X, summation_type=None, **kwargs):
    """Constraint that ensures that an event is not scheduled at the same time as
    another event for which it is unavailable. Unavailability of events is
    either because it is explicitly defined or because they share a tag."""
    summation = lpu.summation_functions[summation_type]
    event_availability_array = lpu.event_availability_array(events)
    label = 'Event clashes with another event'
    for slot1, slot2 in lpu.concurrent_slots(slots):
        for row, event in enumerate(event_availability_array):
            if events[row].unavailability:
                for col, availability in enumerate(event):
                    if availability == 0:
                        yield Constraint(f'{label} - event: {row} and event: {col}', summation((X[row, slot1], X[col, slot2])) <= 1 + availability)

def _upper_bound_on_event_overflow(events, slots, X, beta, summation_type=None, **kwargs):
    """This is an artificial constraint that is used by the objective function
    aiming to minimise the maximum overflow in a slot."""
    label = 'Artificial upper bound constraint'
    for row, event in enumerate(events):
        for col, slot in enumerate(slots):
            yield Constraint(f'{label} - slot: {col} and event: {row}', event.demand * X[row, col] - slot.capacity <= beta)

def tag_array(events):
    """Return a numpy array mapping events to tags

    - Rows corresponds to events
    - Columns correspond to tags"""
    all_tags = sorted(set((tag for event in events for tag in event.tags)))
    array = np.zeros((len(events), len(all_tags)))
    for row, event in enumerate(events):
        for tag in event.tags:
            array[row, all_tags.index(tag)] = 1
    return array

def slot_availability_array(events, slots):
    """Return a numpy array mapping events to slots

    - Rows corresponds to events
    - Columns correspond to stags

    Array has value 0 if event cannot be scheduled in a given slot
    (1 otherwise)"""
    array = np.ones((len(events), len(slots)))
    for row, event in enumerate(events):
        for col, slot in enumerate(slots):
            if slot in event.unavailability or event.duration > slot.duration:
                array[row, col] = 0
    return array

def event_availability_array(events):
    """Return a numpy array mapping events to events

    - Rows corresponds to events
    - Columns correspond to events

    Array has value 0 if event cannot be scheduled at same time as other event
    (1 otherwise)"""
    array = np.ones((len(events), len(events)))
    for row, event in enumerate(events):
        for col, other_event in enumerate(events):
            if row != col:
                tags = set(event.tags)
                events_share_tag = len(tags.intersection(other_event.tags)) > 0
                if other_event in event.unavailability or events_share_tag:
                    array[row, col] = 0
                    array[col, row] = 0
    return array

def slots_overlap(slot, other_slot):
    """Return boolean: whether or not two events overlap"""
    slot_ends_at = ends_at(slot)
    other_ends_at = ends_at(other_slot)
    if slot.starts_at >= other_slot.starts_at and slot_ends_at <= other_ends_at:
        return True
    if other_slot.starts_at >= slot.starts_at and other_ends_at <= slot_ends_at:
        return True
    return False

def concurrent_slots(slots):
    """Yields all concurrent slot indices."""
    for i, slot in enumerate(slots):
        for j, other_slot in enumerate(slots[i + 1:]):
            if slots_overlap(slot, other_slot):
                yield (i, j + i + 1)

def add_line(self, line, source, *lineno):
    """Append one line of generated reST to the output."""
    if 'conference_scheduler.scheduler' in source:
        module = 'scheduler'
    else:
        module = 'resources'
    rst[module].append(line)
    self.directive.result.append(self.indent + line, source, *lineno)

def efficiency_capacity_demand_difference(slots, events, X, **kwargs):
    """A function that calculates the total difference between demand for an event
    and the slot capacity it is scheduled in."""
    overflow = 0
    for row, event in enumerate(events):
        for col, slot in enumerate(slots):
            overflow += (event.demand - slot.capacity) * X[row, col]
    return overflow

def number_of_changes(slots, events, original_schedule, X, **kwargs):
    """A function that counts the number of changes between a given schedule
    and an array (either numpy array of lp array)."""
    changes = 0
    original_array = schedule_to_array(original_schedule, events=events, slots=slots)
    for row, event in enumerate(original_array):
        for col, slot in enumerate(event):
            if slot == 0:
                changes += X[row, col]
            else:
                changes += 1 - X[row, col]
    return changes

def fcs(bits):
    """Append running bitwise FCS CRC checksum to end of generator"""
    fcs = FCS()
    for bit in bits:
        yield bit
        fcs.update_bit(bit)
    digest = bitarray(endian='little')
    digest.frombytes(fcs.digest())
    for bit in digest:
        yield bit

def nrzi(data):
    """Packet uses NRZI (non-return to zero inverted) encoding, which means
    that a 0 is encoded as a change in tone, and a 1 is encoded as
    no change in tone."""
    current = True
    for bit in data:
        if not bit:
            current = not current
        yield current

def _buckets_nearly_equal(a_dist, b_dist):
    """Determines whether two `Distributions` are nearly equal.

    Args:
      a_dist (:class:`Distribution`): an instance
      b_dist (:class:`Distribution`): another instance

    Return:
      boolean: `True` if the two instances are approximately equal, otherwise
        False"""
    a_type, a_buckets = _detect_bucket_option(a_dist)
    b_type, b_buckets = _detect_bucket_option(b_dist)
    if a_type != b_type:
        return False
    elif a_type == u'linearBuckets':
        return _linear_buckets_nearly_equal(a_buckets, b_buckets)
    elif a_type == u'exponentialBuckets':
        return _exponential_buckets_nearly_equal(a_buckets, b_buckets)
    elif a_type == u'explicitBuckets':
        return _explicit_buckets_nearly_equal(a_buckets, b_buckets)
    else:
        return False

def _sign_of(money):
    """Determines the amount sign of a money instance

    Args:
      money (:class:`endpoints_management.gen.servicecontrol_v1_messages.Money`): the
        instance to test

    Return:
      int: 1, 0 or -1"""
    units = money.units
    nanos = money.nanos
    if units:
        if units > 0:
            return 1
        elif units < 0:
            return -1
    if nanos:
        if nanos > 0:
            return 1
        elif nanos < 0:
            return -1
    return 0

def _verify_required_claims_exist(jwt_claims):
    """Verifies that the required claims exist.

    Args:
      jwt_claims: the JWT claims to be verified.

    Raises:
      UnauthenticatedException: if some claim doesn't exist."""
    for claim_name in [u'aud', u'exp', u'iss', u'sub']:
        if claim_name not in jwt_claims:
            raise suppliers.UnauthenticatedException(u'Missing "%s" claim' % claim_name)

