def add_dict_to_hash(a_hash, a_dict):
    """Adds `a_dict` to `a_hash`

    Args:
       a_hash (`Hash`): the secure hash, e.g created by hashlib.md5
       a_dict (dict[string, [string]]): the dictionary to add to the hash"""
    if a_dict is None:
        return
    for k, v in a_dict.items():
        a_hash.update(b'\x00' + k.encode('utf-8') + b'\x00' + v.encode('utf-8'))

def _available_cpu_count():
    """Number of available virtual or physical CPUs on this system
    Adapted from http://stackoverflow.com/a/1006301/715090"""
    try:
        return len(os.sched_getaffinity(0))
    except AttributeError:
        pass
    import re
    try:
        with open('/proc/self/status') as f:
            status = f.read()
        m = re.search('(?m)^Cpus_allowed:\\s*(.*)$', status)
        if m:
            res = bin(int(m.group(1).replace(',', ''), 16)).count('1')
            if res > 0:
                return res
    except IOError:
        pass
    try:
        import multiprocessing
        return multiprocessing.cpu_count()
    except (ImportError, NotImplementedError):
        return 1

def valuemap(f):
    """Decorator to help PEG functions handle value conversions."""
    @wraps(f)
    def wrapper(*args, **kwargs):
        if 'value' in kwargs:
            val = kwargs['value']
            del kwargs['value']
            _f = f(*args, **kwargs)
            def valued_f(*args, **kwargs):
                result = _f(*args, **kwargs)
                s, obj, span = result
                if callable(val):
                    return PegreResult(s, val(obj), span)
                else:
                    return PegreResult(s, val, span)
            return valued_f
        else:
            return f(*args, **kwargs)
    return wrapper

def literal(x):
    """Create a PEG function to consume a literal."""
    xlen = len(x)
    msg = 'Expected: "{}"'.format(x)
    def match_literal(s, grm=None, pos=0):
        if s[:xlen] == x:
            return PegreResult(s[xlen:], x, (pos, pos + xlen))
        raise PegreError(msg, pos)
    return match_literal

def regex(r):
    """Create a PEG function to match a regular expression."""
    if isinstance(r, stringtypes):
        p = re.compile(r)
    else:
        p = r
    msg = 'Expected to match: {}'.format(p.pattern)
    def match_regex(s, grm=None, pos=0):
        m = p.match(s)
        if m is not None:
            start, end = m.span()
            data = m.groupdict() if p.groupindex else m.group()
            return PegreResult(s[m.end():], data, (pos + start, pos + end))
        raise PegreError(msg, pos)
    return match_regex

def nonterminal(n):
    """Create a PEG function to match a nonterminal."""
    def match_nonterminal(s, grm=None, pos=0):
        if grm is None:
            grm = {}
        expr = grm[n]
        return expr(s, grm, pos)
    return match_nonterminal

def and_next(e):
    """Create a PEG function for positive lookahead."""
    def match_and_next(s, grm=None, pos=0):
        try:
            e(s, grm, pos)
        except PegreError as ex:
            raise PegreError('Positive lookahead failed', pos)
        else:
            return PegreResult(s, Ignore, (pos, pos))
    return match_and_next

def not_next(e):
    """Create a PEG function for negative lookahead."""
    def match_not_next(s, grm=None, pos=0):
        try:
            e(s, grm, pos)
        except PegreError as ex:
            return PegreResult(s, Ignore, (pos, pos))
        else:
            raise PegreError('Negative lookahead failed', pos)
    return match_not_next

def choice(*es):
    """Create a PEG function to match an ordered choice."""
    msg = 'Expected one of: {}'.format(', '.join(map(repr, es)))
    def match_choice(s, grm=None, pos=0):
        errs = []
        for e in es:
            try:
                return e(s, grm, pos)
            except PegreError as ex:
                errs.append((ex.message, ex.position))
        if errs:
            raise PegreChoiceError(errs, pos)
    return match_choice

def optional(e, default=Ignore):
    """Create a PEG function to optionally match an expression."""
    def match_optional(s, grm=None, pos=0):
        try:
            return e(s, grm, pos)
        except PegreError:
            return PegreResult(s, default, (pos, pos))
    return match_optional

def zero_or_more(e, delimiter=None):
    """Create a PEG function to match zero or more expressions.

    Args:
        e: the expression to match
        delimiter: an optional expression to match between the
            primary *e* matches."""
    if delimiter is None:
        delimiter = lambda s, grm, pos: (s, Ignore, (pos, pos))
    def match_zero_or_more(s, grm=None, pos=0):
        start = pos
        try:
            s, obj, span = e(s, grm, pos)
            pos = span[1]
            data = [] if obj is Ignore else [obj]
        except PegreError:
            return PegreResult(s, [], (pos, pos))
        try:
            while True:
                s, obj, span = delimiter(s, grm, pos)
                pos = span[1]
                if obj is not Ignore:
                    data.append(obj)
                s, obj, span = e(s, grm, pos)
                pos = span[1]
                if obj is not Ignore:
                    data.append(obj)
        except PegreError:
            pass
        return PegreResult(s, data, (start, pos))
    return match_zero_or_more

def one_or_more(e, delimiter=None):
    """Create a PEG function to match one or more expressions.

    Args:
        e: the expression to match
        delimiter: an optional expression to match between the
            primary *e* matches."""
    if delimiter is None:
        delimiter = lambda s, grm, pos: (s, Ignore, (pos, pos))
    msg = 'Expected one or more of: {}'.format(repr(e))
    def match_one_or_more(s, grm=None, pos=0):
        start = pos
        s, obj, span = e(s, grm, pos)
        pos = span[1]
        data = [] if obj is Ignore else [obj]
        try:
            while True:
                s, obj, span = delimiter(s, grm, pos)
                pos = span[1]
                if obj is not Ignore:
                    data.append(obj)
                s, obj, span = e(s, grm, pos)
                pos = span[1]
                if obj is not Ignore:
                    data.append(obj)
        except PegreError:
            pass
        return PegreResult(s, data, (start, pos))
    return match_one_or_more

def _prepare_axes(node, sort_key):
    """Sort axes and combine those that point to the same target and go
    in the same direction."""
    links = node.links
    o_links = node._overlapping_links
    overlap = {ax2 for ax in links for ax2 in o_links.get(ax, [])}
    axes = []
    for axis in sorted(links.keys(), key=sort_key):
        if axis in overlap:
            continue
        tgt = links[axis]
        if axis in o_links:
            s, e = (axis[0], axis[-1])
            axis = '%s%s%s' % (s, '&'.join((a[1:-1] for a in [axis] + o_links[axis])), e)
        axes.append((axis, tgt))
    return axes

def _turbo_isomorphic(q, g, check_varprops=True):
    """Query Xmrs q is isomorphic to given Xmrs g if there exists an
    isomorphism (bijection of eps and vars) from q to g."""
    if len(q.eps()) != len(g.eps()):
        return False
    if len(q.variables()) != len(g.variables()):
        return False
    try:
        next(_isomorphisms(q, g, check_varprops=check_varprops))
        return True
    except StopIteration:
        return False

def _isomorphism_rewrite_to_NECtree(q_s, qgraph):
    """Neighborhood Equivalence Class tree (see Turbo_ISO paper)"""
    qadj = qgraph.adj
    adjsets = lambda x: set(chain.from_iterable(qadj[x].values()))
    t = ([q_s], [])
    visited = {q_s}
    vcur, vnext = ([t], [])
    while vcur:
        for nec, children in vcur:
            c = defaultdict(list)
            for u in nec:
                for sig, adjlist in qadj[u].items():
                    c[sig].extend((x for x, _, _ in adjlist if x not in visited))
            for sig, c_adjlist in c.items():
                visited.update(c_adjlist)
                for key, grp in groupby(c_adjlist, key=adjsets):
                    grp = list(grp)
                    if len(grp) > 1:
                        children.append((list(grp), []))
                    else:
                        children.append((list(grp), []))
            vnext.extend(children)
        vcur, vnext = (vnext, [])
    return t

def _node_isomorphic(a, b, check_varprops=True):
    """Two Xmrs objects are isomorphic if they have the same structure as
    determined by variable linkages between preds."""
    a_var_refs = sorted((len(vd['refs']) for vd in a._vars.values()))
    b_var_refs = sorted((len(vd['refs']) for vd in b._vars.values()))
    if a_var_refs != b_var_refs:
        return False
    print()
    a_nd = _node_isomorphic_build_nodedict(a, check_varprops)
    b_nd = _node_isomorphic_build_nodedict(b, check_varprops)
    a_sigs = {}
    agenda = []
    isomap = {}
    for sig, a_pairs in sorted(a_nd.items(), key=lambda x: len(x[1])):
        b_pairs = b_nd.get(sig, [])
        if len(a_pairs) != len(b_pairs):
            return False
        if len(a_pairs) == 1:
            a_, a_edges = a_pairs[0]
            b_, b_edges = b_pairs[0]
            if len(a_edges) != len(b_edges):
                return False
            a_sigs[a_] = sig
            isomap[a_] = b_
            for edge, a_tgt in a_edges.items():
                if edge not in b_edges:
                    return False
                isomap[a_tgt] = b_edges[edge]
        else:
            for a_, ed in a_pairs:
                a_sigs[a_] = sig
                agenda.append((a_, sig, ed))
    isomaps = _node_isomorphic(agenda, a_sigs, b_nd, isomap, {})
    try:
        next(isomaps)
        return True
    except StopIteration:
        return False

def compare_bags(testbag, goldbag, count_only=True):
    """Compare two bags of Xmrs objects, returning a triple of
    (unique in test, shared, unique in gold).

    Args:
        testbag: An iterable of Xmrs objects to test.
        goldbag: An iterable of Xmrs objects to compare against.
        count_only: If True, the returned triple will only have the
            counts of each; if False, a list of Xmrs objects will be
            returned for each (using the ones from testbag for the
            shared set)
    Returns:
        A triple of (unique in test, shared, unique in gold), where
        each of the three items is an integer count if the count_only
        parameter is True, or a list of Xmrs objects otherwise."""
    gold_remaining = list(goldbag)
    test_unique = []
    shared = []
    for test in testbag:
        gold_match = None
        for gold in gold_remaining:
            if isomorphic(test, gold):
                gold_match = gold
                break
        if gold_match is not None:
            gold_remaining.remove(gold_match)
            shared.append(test)
        else:
            test_unique.append(test)
    if count_only:
        return (len(test_unique), len(shared), len(gold_remaining))
    else:
        return (test_unique, shared, gold_remaining)

def query(query, ts, **kwargs):
    """Perform *query* on the testsuite *ts*.

    Note: currently only 'select' queries are supported.

    Args:
        query (str): TSQL query string
        ts (:class:`delphin.itsdb.TestSuite`): testsuite to query over
        kwargs: keyword arguments passed to the more specific query
            function (e.g., :func:`select`)
    Example:
        >>> list(tsql.query('select i-id where i-length < 4', ts))
        [[142], [1061]]"""
    queryobj = _parse_query(query)
    if queryobj['querytype'] in ('select', 'retrieve'):
        return _select(queryobj['projection'], queryobj['tables'], queryobj['where'], ts, mode=kwargs.get('mode', 'list'), cast=kwargs.get('cast', True))
    else:
        raise TSQLSyntaxError(queryobj['querytype'] + ' queries are not supported')

def _lex(s):
    """Lex the input string according to _tsql_lex_re.

    Yields
        (gid, token, line_number)"""
    s += '.'
    lines = enumerate(s.splitlines(), 1)
    lineno = pos = 0
    try:
        for lineno, line in lines:
            matches = _tsql_lex_re.finditer(line)
            for m in matches:
                gid = m.lastindex
                if gid == 11:
                    raise TSQLSyntaxError('unexpected input', lineno=lineno, offset=m.start(), text=line)
                else:
                    token = m.group(gid)
                    yield (gid, token, lineno)
    except StopIteration:
        pass

def intrinsic_variables(xmrs):
    """Return the list of all intrinsic variables in *xmrs*"""
    ivs = set((ep.intrinsic_variable for ep in xmrs.eps() if not ep.is_quantifier() and ep.intrinsic_variable is not None))
    return sorted(ivs, key=var_id)

def bound_variables(xmrs):
    """Return the list of all bound variables in *xmrs*"""
    bvs = set((ep.intrinsic_variable for ep in xmrs.eps() if ep.is_quantifier() and ep.intrinsic_variable is not None))
    return sorted(bvs, key=var_id)

def _prepare_target(ts, tables, buffer_size):
    """Clear tables affected by the processing."""
    for tablename in tables:
        table = ts[tablename]
        table[:] = []
        if buffer_size is not None and table.is_attached():
            table.write(append=False)

def _prepare_source(selector, source):
    """Normalize source rows and selectors."""
    tablename, fields = get_data_specifier(selector)
    if len(fields) != 1:
        raise ItsdbError('Selector must specify exactly one data column: {}'.format(selector))
    if isinstance(source, TestSuite):
        if not tablename:
            tablename = source.relations.find(fields[0])[0]
        source = source[tablename]
    cols = list(source.fields.keys()) + fields
    return (source, cols)

def _add_record(table, data, buffer_size):
    """Prepare and append a Record into its Table; flush to disk if necessary."""
    fields = table.fields
    for invalid_key in set(data).difference([f.name for f in fields]):
        del data[invalid_key]
    table.append(Record.from_dict(fields, data))
    if buffer_size is not None and table.is_attached():
        if len(table) - 1 - table._last_synced_index > buffer_size:
            table.commit()

def get_data_specifier(string):
    """Return a tuple (table, col) for some [incr tsdb()] data specifier.
    For example::

        item              -> ('item', None)
        item:i-input      -> ('item', ['i-input'])
        item:i-input@i-wf -> ('item', ['i-input', 'i-wf'])
        :i-input          -> (None, ['i-input'])
        (otherwise)       -> (None, None)"""
    match = data_specifier_re.match(string)
    if match is None:
        return (None, None)
    table = match.group('table')
    if table is not None:
        table = table.strip()
    cols = _split_cols(match.group('cols'))
    return (table, cols)

def _table_filename(tbl_filename):
    """Determine if the table path should end in .gz or not and return it.

    A .gz path is preferred only if it exists and is newer than any
    regular text file path.

    Raises:
        :class:`delphin.exceptions.ItsdbError`: when neither the .gz
            nor text file exist."""
    tbl_filename = str(tbl_filename)
    txfn = _normalize_table_path(tbl_filename)
    gzfn = txfn + '.gz'
    if os.path.exists(txfn):
        if os.path.exists(gzfn) and os.stat(gzfn).st_mtime > os.stat(txfn).st_mtime:
            tbl_filename = gzfn
        else:
            tbl_filename = txfn
    elif os.path.exists(gzfn):
        tbl_filename = gzfn
    else:
        raise ItsdbError('Table does not exist at {}(.gz)'.format(tbl_filename))
    return tbl_filename

def make_row(row, fields):
    """Encode a mapping of column name to values into a [incr tsdb()]
    profile line. The *fields* parameter determines what columns are
    used, and default values are provided if a column is missing from
    the mapping.

    Args:
        row: a mapping of column names to values
        fields: an iterable of :class:`Field` objects
    Returns:
        A [incr tsdb()]-encoded string"""
    if not hasattr(row, 'get'):
        row = {f.name: col for f, col in zip(fields, row)}
    row_fields = []
    for f in fields:
        val = row.get(f.name, None)
        if val is None:
            val = str(f.default_value())
        row_fields.append(val)
    return encode_row(row_fields)

def default_value(fieldname, datatype):
    """Return the default value for a column.

    If the column name (e.g. *i-wf*) is defined to have an idiosyncratic
    value, that value is returned. Otherwise the default value for the
    column's datatype is returned.

    Args:
        fieldname: the column name (e.g. `i-wf`)
        datatype: the datatype of the column (e.g. `:integer`)
    Returns:
        The default value for the column.

    .. deprecated:: v0.7.0"""
    if fieldname in tsdb_coded_attributes:
        return str(tsdb_coded_attributes[fieldname])
    else:
        return _default_datatype_values.get(datatype, '')

def load(source, semi=None):
    """Read a variable-property mapping from *source* and return the VPM.

    Args:
        source: a filename or file-like object containing the VPM
            definitions
        semi (:class:`~delphin.mrs.semi.SemI`, optional): if provided,
            it is passed to the VPM constructor
    Returns:
        a :class:`VPM` instance"""
    if hasattr(source, 'read'):
        return _load(source, semi)
    else:
        with open(source, 'r') as fh:
            return _load(fh, semi)

def _valmatch(vs, ss, op, varsort, semi, section):
    """Return `True` if for every paired *v* and *s* from *vs* and *ss*:
        v <> s (subsumption or equality if *semi* is `None`)
        v == s (equality)
        s == '*'
        s == '!' and v == `None`
        s == '[xyz]' and varsort == 'xyz'"""
    if op in _EQUAL_OPS or semi is None:
        return all((s == v or (s == '*' and v is not None) or (v is None and (s == '!' or (s[0], s[-1], s[1:-1]) == ('[', ']', varsort))) for v, s in zip(vs, ss)))
    else:
        pass

def load(fh, single=False):
    """Deserialize :class:`Eds` from a file (handle or filename)

    Args:
        fh (str, file): input filename or file object
        single (bool): if `True`, only return the first Xmrs object
    Returns:
        a generator of :class:`Eds` objects (unless the *single* option
        is `True`)"""
    if isinstance(fh, stringtypes):
        s = open(fh, 'r').read()
    else:
        s = fh.read()
    return loads(s, single=single)

def loads(s, single=False, version=_default_version, strict=False, errors='warn'):
    """Deserialize SimpleMRS string representations

    Args:
        s (str): a SimpleMRS string
        single (bool): if `True`, only return the first Xmrs object
    Returns:
        a generator of Xmrs objects (unless *single* is `True`)"""
    ms = deserialize(s, version=version, strict=strict, errors=errors)
    if single:
        return next(ms)
    else:
        return ms

def _read_lnk(tokens):
    """Read and return a tuple of the pred's lnk type and lnk value,
    if a pred lnk is specified."""
    lnk = None
    if tokens[0] == '<':
        tokens.popleft()
        if tokens[0] == '>':
            pass
        elif tokens[0] == '@':
            tokens.popleft()
            lnk = Lnk.edge(tokens.popleft())
        elif tokens[1] == ':':
            lnk = Lnk.charspan(tokens.popleft(), tokens[1])
            tokens.popleft()
            tokens.popleft()
        elif tokens[1] == '#':
            lnk = Lnk.chartspan(tokens.popleft(), tokens[1])
            tokens.popleft()
            tokens.popleft()
        else:
            lnkdata = []
            while tokens[0] != '>':
                lnkdata.append(int(tokens.popleft()))
            lnk = Lnk.tokens(lnkdata)
        _read_literals(tokens, '>')
    return lnk

def _serialize_argument(rargname, value, varprops):
    """Serialize an MRS argument into the SimpleMRS format."""
    _argument = '{rargname}: {value}{props}'
    if rargname == CONSTARG_ROLE:
        value = '"{}"'.format(value)
    props = ''
    if value in varprops:
        props = ' [ {} ]'.format(' '.join([var_sort(value)] + list(map('{0[0]}: {0[1]}'.format, [(k.upper(), v) for k, v in varprops[value]]))))
        del varprops[value]
    return _argument.format(rargname=rargname, value=str(value), props=props)

def _serialize_ep(ep, varprops, version=_default_version):
    """Serialize an Elementary Predication into the SimpleMRS encoding."""
    args = ep[3]
    arglist = ' '.join([_serialize_argument(rarg, args[rarg], varprops) for rarg in sorted(args, key=rargname_sortkey)])
    if version < 1.1 or len(ep) < 6 or ep[5] is None:
        surface = ''
    else:
        surface = ' "%s"' % ep[5]
    lnk = None if len(ep) < 5 else ep[4]
    pred = ep[1]
    predstr = pred.string
    return '[ {pred}{lnk}{surface} LBL: {label}{s}{args} ]'.format(pred=predstr, lnk=_serialize_lnk(lnk), surface=surface, label=str(ep[2]), s=' ' if arglist else '', args=arglist)

def _serialize_hcons(hcons):
    """Serialize [HandleConstraints] into the SimpleMRS encoding."""
    toks = ['HCONS:', '<']
    for hc in hcons:
        toks.extend(hc)
    toks += ['>']
    return ' '.join(toks)

def _serialize_icons(icons):
    """Serialize [IndividualConstraints] into the SimpleMRS encoding."""
    toks = ['ICONS:', '<']
    for ic in icons:
        toks.extend(ic)
    toks += ['>']
    return ' '.join(toks)

def _peek(tokens, n=0):
    """peek and drop comments"""
    return tokens.peek(n=n, skip=_is_comment, drop=True)

def _shift(tokens):
    """pop the next token, then peek the gid of the following"""
    after = tokens.peek(n=1, skip=_is_comment, drop=True)
    tok = tokens._buffer.popleft()
    return (tok[0], tok[1], tok[2], after[0])

def _lex(stream):
    """Lex the input stream according to _tdl_lex_re.

    Yields
        (gid, token, line_number)"""
    lines = enumerate(stream, 1)
    line_no = pos = 0
    try:
        while True:
            if pos == 0:
                line_no, line = next(lines)
            matches = _tdl_lex_re.finditer(line, pos)
            pos = 0
            for m in matches:
                gid = m.lastindex
                if gid <= 2:
                    if gid == 1:
                        s, start_line_no, line_no, line, pos = _bounded('"""', '"""', line, m.end(), line_no, lines)
                    elif gid == 2:
                        s, start_line_no, line_no, line, pos = _bounded('#|', '|#', line, m.end(), line_no, lines)
                    yield (gid, s, line_no)
                    break
                elif gid == 30:
                    raise TdlParsingError('Syntax error:\n  {}\n {}^'.format(line, ' ' * m.start()), line_number=line_no)
                else:
                    token = m.group(gid)
                    yield (gid, token, line_no)
    except StopIteration:
        pass

def _bounded(p1, p2, line, pos, line_no, lines):
    """Collect the contents of a bounded multiline string"""
    substrings = []
    start_line_no = line_no
    end = pos
    while not line.startswith(p2, end):
        if line[end] == '\\':
            end += 2
        else:
            end += 1
        if end >= len(line):
            substrings.append(line[pos:])
            try:
                line_no, line = next(lines)
            except StopIteration:
                pattern = 'docstring' if p1 == '"""' else 'block comment'
                raise TdlParsingError('Unterminated {}'.format(pattern), line_number=start_line_no)
            pos = end = 0
    substrings.append(line[pos:end])
    end += len(p2)
    return (''.join(substrings), start_line_no, line_no, line, end)

def tokenize(s):
    """Tokenize a string *s* of TDL code."""
    return [m.group(m.lastindex) for m in _tdl_re.finditer(s)]

def parse(f, encoding='utf-8'):
    """Parse the TDL file *f* and yield the interpreted contents.

    If *f* is a filename, the file is opened and closed when the
    generator has finished, otherwise *f* is an open file object and
    will not be closed when the generator has finished.

    Args:
        f (str, file): a filename or open file object
        encoding (str): the encoding of the file (default: `"utf-8"`;
            ignored if *f* is an open file)"""
    if hasattr(f, 'read'):
        for event in _parse(f):
            yield event
    else:
        with io.open(f, encoding=encoding) as fh:
            for event in _parse(fh):
                yield event

def format(obj, indent=0):
    """Serialize TDL objects to strings.

    Args:
        obj: instance of :class:`Term`, :class:`Conjunction`, or
            :class:`TypeDefinition` classes or subclasses
        indent (int): number of spaces to indent the formatted object
    Returns:
        str: serialized form of *obj*
    Example:
        >>> conj = tdl.Conjunction([
        ...     tdl.TypeIdentifier('lex-item'),
        ...     tdl.AVM([('SYNSEM.LOCAL.CAT.HEAD.MOD',
        ...               tdl.ConsList(end=tdl.EMPTY_LIST_TYPE))])
        ... ])
        >>> t = tdl.TypeDefinition('non-mod-lex-item', conj)
        >>> print(format(t))
        non-mod-lex-item := lex-item &
          [ SYNSEM.LOCAL.CAT.HEAD.MOD < > ]."""
    if isinstance(obj, TypeDefinition):
        return _format_typedef(obj, indent)
    elif isinstance(obj, Conjunction):
        return _format_conjunction(obj, indent)
    elif isinstance(obj, Term):
        return _format_term(obj, indent)
    elif isinstance(obj, _MorphSet):
        return _format_morphset(obj, indent)
    elif isinstance(obj, _Environment):
        return _format_environment(obj, indent)
    elif isinstance(obj, FileInclude):
        return _format_include(obj, indent)
    else:
        raise ValueError('cannot format object as TDL: {!r}'.format(obj))

def sort_vid_split(vs):
    """Split a valid variable string into its variable sort and id.

    Examples:
        >>> sort_vid_split('h3')
        ('h', '3')
        >>> sort_vid_split('ref-ind12')
        ('ref-ind', '12')"""
    match = var_re.match(vs)
    if match is None:
        raise ValueError('Invalid variable string: {}'.format(str(vs)))
    else:
        return match.groups()

def hcons(xmrs):
    """Return the list of all HandleConstraints in *xmrs*."""
    return [HandleConstraint(hi, reln, lo) for hi, reln, lo in sorted(xmrs.hcons(), key=lambda hc: var_id(hc[0]))]

def icons(xmrs):
    """Return the list of all IndividualConstraints in *xmrs*."""
    return [IndividualConstraint(left, reln, right) for left, reln, right in sorted(xmrs.icons(), key=lambda ic: var_id(ic[0]))]

def get_version(release_level=True):
    """Return the formatted version information"""
    vers = ['%(major)i.%(minor)i.%(micro)i' % __version_info__]
    if release_level and __version_info__['releaselevel'] != 'final':
        vers.append('%(releaselevel)s%(serial)i' % __version_info__)
    return ''.join(vers)

def _python_psk_client_callback(ssl_id, hint):
    """Called by _sslpsk.c to return the (psk, identity) tuple for the socket with
    the specified ssl socket."""
    if ssl_id not in _callbacks:
        return ('', '')
    else:
        res = _callbacks[ssl_id](hint)
        return res if isinstance(res, tuple) else (res, '')

def _sslobj(sock):
    """Returns the underlying PySLLSocket object with which the C extension
    functions interface."""
    pass
    if isinstance(sock._sslobj, _ssl._SSLSocket):
        return sock._sslobj
    else:
        return sock._sslobj._sslobj

def _colorize(val, color):
    """Colorize a string using termcolor or colorama.

    If any of them are available."""
    if termcolor is not None:
        val = termcolor.colored(val, color)
    elif colorama is not None:
        val = TERMCOLOR2COLORAMA[color] + val + colorama.Style.RESET_ALL
    return val

def get_rand_string(length=12, allowed_chars='0123456789abcdef'):
    """Returns a securely generated random string. Taken from the Django project

    The default length of 12 with the a-z, A-Z, 0-9 character set returns
    a 71-bit value. log_2((26+26+10)^12) =~ 71 bits"""
    if not using_sysrandom:
        random.seed(hashlib.sha256(('%s%s' % (random.getstate(), time.time())).encode('utf-8')).digest())
    return ''.join([random.choice(allowed_chars) for i in range(length)])

def make_id(name):
    """Create a random id combined with the creditor name.
    @return string consisting of name (truncated at 22 chars), -,
    12 char rand hex string."""
    name = re.sub('[^a-zA-Z0-9]', '', name)
    r = get_rand_string(12)
    if len(name) > 22:
        name = name[:22]
    return name + '-' + r

def int_to_decimal_str(integer):
    """Helper to convert integers (representing cents) into decimal currency
    string. WARNING: DO NOT TRY TO DO THIS BY DIVISION, FLOATING POINT
    ERRORS ARE NO FUN IN FINANCIAL SYSTEMS.
    @param integer The amount in cents
    @return string The amount in currency with full stop decimal separator"""
    int_string = str(integer)
    if len(int_string) < 2:
        return '0.' + int_string.zfill(2)
    else:
        return int_string[:-2] + '.' + int_string[-2:]

def decimal_str_to_int(decimal_string):
    """Helper to decimal currency string into integers (cents).
    WARNING: DO NOT TRY TO DO THIS BY CONVERSION AND MULTIPLICATION,
    FLOATING POINT ERRORS ARE NO FUN IN FINANCIAL SYSTEMS.
    @param string The amount in currency with full stop decimal separator
    @return integer The amount in cents"""
    int_string = decimal_string.replace('.', '')
    int_string = int_string.lstrip('0')
    return int(int_string)

def read_rdf(sources, infmt):
    """Read a list of RDF files and/or RDF graphs. May raise an Exception."""
    rdf = Graph()
    for source in sources:
        if isinstance(source, Graph):
            for triple in source:
                rdf.add(triple)
            continue
        if source == '-':
            f = sys.stdin
        else:
            f = open(source, 'r')
        if infmt:
            fmt = infmt
        else:
            fmt = 'xml'
            if source.endswith('n3'):
                fmt = 'n3'
            if source.endswith('ttl'):
                fmt = 'n3'
            if source.endswith('nt'):
                fmt = 'nt'
        logging.debug('Parsing input file %s (format: %s)', source, fmt)
        rdf.parse(f, format=fmt)
    return rdf

def mapping_get(uri, mapping):
    """Look up the URI in the given mapping and return the result.

    Throws KeyError if no matching mapping was found."""
    ln = localname(uri)
    for k, v in mapping.items():
        if k == uri:
            return v
    for k, v in mapping.items():
        if k == ln:
            return v
    l = list(mapping.items())
    l.sort(key=lambda i: len(i[0]), reverse=True)
    for k, v in l:
        if k[0] == '*' and ln.endswith(k[1:]):
            return v
    raise KeyError(uri)

def mapping_match(uri, mapping):
    """Determine whether the given URI matches one of the given mappings.

    Returns True if a match was found, False otherwise."""
    try:
        val = mapping_get(uri, mapping)
        return True
    except KeyError:
        return False

def in_general_ns(uri):
    """Return True iff the URI is in a well-known general RDF namespace.

    URI namespaces considered well-known are RDF, RDFS, OWL, SKOS and DC."""
    RDFuri = RDF.uri
    RDFSuri = RDFS.uri
    for ns in (RDFuri, RDFSuri, OWL, SKOS, DC):
        if uri.startswith(ns):
            return True
    return False

def get_concept_scheme(rdf):
    """Return a skos:ConceptScheme contained in the model.

    Returns None if no skos:ConceptScheme is present."""
    for s, o in rdf.subject_objects(SKOS.inScheme):
        if not isinstance(o, Literal):
            rdf.add((o, RDF.type, SKOS.ConceptScheme))
        else:
            logging.warning('Literal value %s for skos:inScheme detected, ignoring.', o)
    css = list(rdf.subjects(RDF.type, SKOS.ConceptScheme))
    if len(css) > 1:
        css.sort()
        cs = css[0]
        logging.warning('Multiple concept schemes found. Selecting %s as default concept scheme.', cs)
    elif len(css) == 1:
        cs = css[0]
    else:
        cs = None
    return cs

def create_concept_scheme(rdf, ns, lname=''):
    """Create a skos:ConceptScheme in the model and return it."""
    ont = None
    if not ns:
        onts = list(rdf.subjects(RDF.type, OWL.Ontology))
        if len(onts) > 1:
            onts.sort()
            ont = onts[0]
            logging.warning('Multiple owl:Ontology instances found. Creating concept scheme from %s.', ont)
        elif len(onts) == 1:
            ont = onts[0]
        else:
            ont = None
        if not ont:
            logging.info('No skos:ConceptScheme or owl:Ontology found. Using namespace auto-detection for creating concept scheme.')
            ns = detect_namespace(rdf)
        elif ont.endswith('/') or ont.endswith('#') or ont.endswith(':'):
            ns = ont
        else:
            ns = ont + '/'
    NS = Namespace(ns)
    cs = NS[lname]
    rdf.add((cs, RDF.type, SKOS.ConceptScheme))
    if ont is not None:
        rdf.remove((ont, RDF.type, OWL.Ontology))
        for o in rdf.objects(ont, OWL.imports):
            rdf.remove((ont, OWL.imports, o))
        for p, o in rdf.predicate_objects(ont):
            prot = URIRef('http://protege.stanford.edu/plugins/owl/protege#')
            if p.startswith(prot):
                rdf.remove((ont, p, o))
        replace_uri(rdf, ont, cs)
    return cs

def initialize_concept_scheme(rdf, cs, label, language, set_modified):
    """Initialize a concept scheme: Optionally add a label if the concept
    scheme doesn't have a label, and optionally add a dct:modified
    timestamp."""
    labels = list(rdf.objects(cs, RDFS.label)) + list(rdf.objects(cs, SKOS.prefLabel))
    if len(labels) == 0:
        if not label:
            logging.warning('Concept scheme has no label(s). Use --label option to set the concept scheme label.')
        else:
            logging.info("Unlabeled concept scheme detected. Setting label to '%s'" % label)
            rdf.add((cs, RDFS.label, Literal(label, language)))
    if set_modified:
        curdate = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + 'Z'
        rdf.remove((cs, DCTERMS.modified, None))
        rdf.add((cs, DCTERMS.modified, Literal(curdate, datatype=XSD.dateTime)))

def transform_sparql_construct(rdf, construct_query):
    """Perform a SPARQL CONSTRUCT query on the RDF data and return a new graph."""
    logging.debug('performing SPARQL CONSTRUCT transformation')
    if construct_query[0] == '@':
        construct_query = file(construct_query[1:]).read()
    logging.debug('CONSTRUCT query: %s', construct_query)
    newgraph = Graph()
    for triple in rdf.query(construct_query):
        newgraph.add(triple)
    return newgraph

def transform_concepts(rdf, typemap):
    """Transform Concepts into new types, as defined by the config file."""
    types = set()
    for s, o in rdf.subject_objects(RDF.type):
        if o not in typemap and in_general_ns(o):
            continue
        types.add(o)
    for t in types:
        if mapping_match(t, typemap):
            newval = mapping_get(t, typemap)
            newuris = [v[0] for v in newval]
            logging.debug('transform class %s -> %s', t, str(newuris))
            if newuris[0] is None:
                for inst in rdf.subjects(RDF.type, t):
                    delete_uri(rdf, inst)
                delete_uri(rdf, t)
            else:
                replace_object(rdf, t, newuris, predicate=RDF.type)
        else:
            logging.info("Don't know what to do with type %s", t)

def transform_literals(rdf, literalmap):
    """Transform literal properties of Concepts, as defined by config file."""
    affected_types = (SKOS.Concept, SKOS.Collection, SKOSEXT.DeprecatedConcept)
    props = set()
    for t in affected_types:
        for conc in rdf.subjects(RDF.type, t):
            for p, o in rdf.predicate_objects(conc):
                if isinstance(o, Literal) and (p in literalmap or not in_general_ns(p)):
                    props.add(p)
    for p in props:
        if mapping_match(p, literalmap):
            newval = mapping_get(p, literalmap)
            newuris = [v[0] for v in newval]
            logging.debug('transform literal %s -> %s', p, str(newuris))
            replace_predicate(rdf, p, newuris, subjecttypes=affected_types)
        else:
            logging.info("Don't know what to do with literal %s", p)

def transform_relations(rdf, relationmap):
    """Transform YSO-style concept relations into SKOS equivalents."""
    affected_types = (SKOS.Concept, SKOS.Collection, SKOSEXT.DeprecatedConcept)
    props = set()
    for t in affected_types:
        for conc in rdf.subjects(RDF.type, t):
            for p, o in rdf.predicate_objects(conc):
                if isinstance(o, (URIRef, BNode)) and (p in relationmap or not in_general_ns(p)):
                    props.add(p)
    for p in props:
        if mapping_match(p, relationmap):
            newval = mapping_get(p, relationmap)
            logging.debug('transform relation %s -> %s', p, str(newval))
            replace_predicate(rdf, p, newval, subjecttypes=affected_types)
        else:
            logging.info("Don't know what to do with relation %s", p)

def transform_aggregate_concepts(rdf, cs, relationmap, aggregates):
    """Transform YSO-style AggregateConcepts into skos:Concepts within their
    own skos:ConceptScheme, linked to the regular concepts with
    SKOS.narrowMatch relationships. If aggregates is False, remove
    all aggregate concepts instead."""
    if not aggregates:
        logging.debug('removing aggregate concepts')
    aggregate_concepts = []
    relation = relationmap.get(OWL.equivalentClass, [(OWL.equivalentClass, False)])[0][0]
    for conc, eq in rdf.subject_objects(relation):
        eql = rdf.value(eq, OWL.unionOf, None)
        if eql is None:
            continue
        if aggregates:
            aggregate_concepts.append(conc)
            for item in rdf.items(eql):
                rdf.add((conc, SKOS.narrowMatch, item))
        rdf.remove((conc, relation, eq))
        rdf.remove((eq, RDF.type, OWL.Class))
        rdf.remove((eq, OWL.unionOf, eql))
        delete_uri(rdf, eql)
        if not aggregates:
            delete_uri(rdf, conc)
    if len(aggregate_concepts) > 0:
        ns = cs.replace(localname(cs), '')
        acs = create_concept_scheme(rdf, ns, 'aggregateconceptscheme')
        logging.debug('creating aggregate concept scheme %s', acs)
        for conc in aggregate_concepts:
            rdf.add((conc, SKOS.inScheme, acs))

def enrich_relations(rdf, enrich_mappings, use_narrower, use_transitive):
    """Enrich the SKOS relations according to SKOS semantics, including
    subproperties of broader and symmetric related properties. If use_narrower
    is True, include inverse narrower relations for all broader relations. If
    use_narrower is False, instead remove all narrower relations, replacing
    them with inverse broader relations. If use_transitive is True, calculate
    transitive hierarchical relationships.

    (broaderTransitive, and also narrowerTransitive if use_narrower is
    True) and include them in the model."""
    if enrich_mappings:
        infer.skos_symmetric_mappings(rdf)
        infer.skos_hierarchical_mappings(rdf, use_narrower)
    infer.skos_related(rdf)
    for s, o in rdf.subject_objects(SKOSEXT.broaderGeneric):
        rdf.add((s, SKOS.broader, o))
    for s, o in rdf.subject_objects(SKOSEXT.broaderPartitive):
        rdf.add((s, SKOS.broader, o))
    infer.skos_hierarchical(rdf, use_narrower)
    if use_transitive:
        infer.skos_transitive(rdf, use_narrower)
    else:
        for s, o in rdf.subject_objects(SKOS.broaderTransitive):
            rdf.remove((s, SKOS.broaderTransitive, o))
        for s, o in rdf.subject_objects(SKOS.narrowerTransitive):
            rdf.remove((s, SKOS.narrowerTransitive, o))
    infer.skos_topConcept(rdf)

def cleanup_classes(rdf):
    """Remove unnecessary class definitions: definitions of SKOS classes or
    unused classes. If a class is also a skos:Concept or skos:Collection,
    remove the 'classness' of it but leave the Concept/Collection."""
    for t in (OWL.Class, RDFS.Class):
        for cl in rdf.subjects(RDF.type, t):
            if cl.startswith(SKOS):
                logging.debug('removing SKOS class definition: %s', cl)
                replace_subject(rdf, cl, None)
                continue
            if rdf.value(None, RDF.type, cl, any=True) is not None:
                continue
            if rdf.value(None, RDFS.domain, cl, any=True) is not None:
                continue
            if rdf.value(None, RDFS.range, cl, any=True) is not None:
                continue
            if rdf.value(None, OWL.equivalentClass, cl, any=True) is not None:
                continue
            if (cl, RDF.type, SKOS.Concept) in rdf or (cl, RDF.type, SKOS.Collection) in rdf:
                logging.debug('removing classiness of %s', cl)
                rdf.remove((cl, RDF.type, t))
            else:
                logging.debug('removing unused class definition: %s', cl)
                replace_subject(rdf, cl, None)

def cleanup_properties(rdf):
    """Remove unnecessary property definitions.

    Reemoves SKOS and DC property definitions and definitions of unused
    properties."""
    for t in (RDF.Property, OWL.DatatypeProperty, OWL.ObjectProperty, OWL.SymmetricProperty, OWL.TransitiveProperty, OWL.InverseFunctionalProperty, OWL.FunctionalProperty):
        for prop in rdf.subjects(RDF.type, t):
            if prop.startswith(SKOS):
                logging.debug('removing SKOS property definition: %s', prop)
                replace_subject(rdf, prop, None)
                continue
            if prop.startswith(DC):
                logging.debug('removing DC property definition: %s', prop)
                replace_subject(rdf, prop, None)
                continue
            if len(list(rdf.subject_objects(prop))) > 0:
                continue
            logging.debug('removing unused property definition: %s', prop)
            replace_subject(rdf, prop, None)

def find_reachable(rdf, res):
    """Return the set of reachable resources starting from the given resource,
    excluding the seen set of resources.

    Note that the seen set is modified
    in-place to reflect the ongoing traversal."""
    starttime = time.time()
    seen = set()
    to_search = set([res])
    while len(to_search) > 0:
        res = to_search.pop()
        if res in seen:
            continue
        seen.add(res)
        for p, o in rdf.predicate_objects(res):
            if isinstance(p, URIRef) and p not in seen:
                to_search.add(p)
            if isinstance(o, URIRef) and o not in seen:
                to_search.add(o)
        for s, o in rdf.subject_objects(res):
            if isinstance(s, URIRef) and s not in seen:
                to_search.add(s)
            if isinstance(o, URIRef) and o not in seen:
                to_search.add(o)
        for s, p in rdf.subject_predicates(res):
            if isinstance(s, URIRef) and s not in seen:
                to_search.add(s)
            if isinstance(p, URIRef) and p not in seen:
                to_search.add(p)
    endtime = time.time()
    logging.debug('find_reachable took %f seconds', endtime - starttime)
    return seen

def expand_curielike(namespaces, curie):
    """Expand a CURIE (or a CURIE-like string with a period instead of colon
    as separator) into URIRef. If the provided curie is not a CURIE, return it
    unchanged."""
    if curie == '':
        return None
    if sys.version < '3' and (not isinstance(curie, type(u''))):
        curie = curie.decode('UTF-8')
    if curie.startswith('[') and curie.endswith(']'):
        curie = curie[1:-1]
    if ':' in curie:
        ns, localpart = curie.split(':', 1)
    elif '.' in curie:
        ns, localpart = curie.split('.', 1)
    else:
        return curie
    if ns in namespaces:
        return URIRef(namespaces[ns].term(localpart))
    else:
        logging.warning('Unknown namespace prefix %s', ns)
        return URIRef(curie)

def replace_subject(rdf, fromuri, touri):
    """Replace occurrences of fromuri as subject with touri in given model.

    If touri=None, will delete all occurrences of fromuri instead.
    If touri is a list or tuple of URIRefs, all values will be inserted."""
    if fromuri == touri:
        return
    for p, o in rdf.predicate_objects(fromuri):
        rdf.remove((fromuri, p, o))
        if touri is not None:
            if not isinstance(touri, (list, tuple)):
                touri = [touri]
            for uri in touri:
                rdf.add((uri, p, o))

def replace_predicate(rdf, fromuri, touri, subjecttypes=None, inverse=False):
    """Replace occurrences of fromuri as predicate with touri in given model.

    If touri=None, will delete all occurrences of fromuri instead.
    If touri is a list or tuple of URIRef, all values will be inserted. If
    touri is a list of (URIRef, boolean) tuples, the boolean value will be
    used to determine whether an inverse property is created (if True) or
    not (if False). If a subjecttypes sequence is given, modify only those
    triples where the subject is one of the provided types."""
    if fromuri == touri:
        return
    for s, o in rdf.subject_objects(fromuri):
        if subjecttypes is not None:
            typeok = False
            for t in subjecttypes:
                if (s, RDF.type, t) in rdf:
                    typeok = True
            if not typeok:
                continue
        rdf.remove((s, fromuri, o))
        if touri is not None:
            if not isinstance(touri, (list, tuple)):
                touri = [touri]
            for val in touri:
                if not isinstance(val, tuple):
                    val = (val, False)
                uri, inverse = val
                if uri is None:
                    continue
                if inverse:
                    rdf.add((o, uri, s))
                else:
                    rdf.add((s, uri, o))

def replace_object(rdf, fromuri, touri, predicate=None):
    """Replace all occurrences of fromuri as object with touri in the given
    model.

    If touri=None, will delete all occurrences of fromuri instead.
    If touri is a list or tuple of URIRef, all values will be inserted.
    If predicate is given, modify only triples with the given predicate."""
    if fromuri == touri:
        return
    for s, p in rdf.subject_predicates(fromuri):
        if predicate is not None and p != predicate:
            continue
        rdf.remove((s, p, fromuri))
        if touri is not None:
            if not isinstance(touri, (list, tuple)):
                touri = [touri]
            for uri in touri:
                rdf.add((s, p, uri))

def hierarchy_cycles(rdf, fix=False):
    """Check if the graph contains skos:broader cycles and optionally break these.

    :param Graph rdf: An rdflib.graph.Graph object.
    :param bool fix: Fix the problem by removing any skos:broader that overlaps
        with skos:broaderTransitive."""
    top_concepts = sorted(rdf.subject_objects(SKOS.hasTopConcept))
    status = {}
    for cs, root in top_concepts:
        _hierarchy_cycles_visit(rdf, root, None, fix, status=status)
    recheck_top_concepts = False
    for conc in sorted(rdf.subjects(RDF.type, SKOS.Concept)):
        if conc not in status:
            recheck_top_concepts = True
            _hierarchy_cycles_visit(rdf, conc, None, fix, status=status)
    return recheck_top_concepts

def disjoint_relations(rdf, fix=False):
    """Check if the graph contains concepts connected by both of the semantically
    disjoint semantic skos:related and skos:broaderTransitive (S27),
    and optionally remove the involved skos:related relations.

    :param Graph rdf: An rdflib.graph.Graph object.
    :param bool fix: Fix the problem by removing skos:related relations that
        overlap with skos:broaderTransitive."""
    for conc1, conc2 in sorted(rdf.subject_objects(SKOS.related)):
        if conc2 in sorted(rdf.transitive_objects(conc1, SKOS.broader)):
            if fix:
                logging.warning('Concepts %s and %s connected by both skos:broaderTransitive and skos:related, removing skos:related', conc1, conc2)
                rdf.remove((conc1, SKOS.related, conc2))
                rdf.remove((conc2, SKOS.related, conc1))
            else:
                logging.warning('Concepts %s and %s connected by both skos:broaderTransitive and skos:related, but keeping it because keep_related is enabled', conc1, conc2)

def hierarchical_redundancy(rdf, fix=False):
    """Check for and optionally remove extraneous skos:broader relations.

    :param Graph rdf: An rdflib.graph.Graph object.
    :param bool fix: Fix the problem by removing skos:broader relations between
        concepts that are otherwise connected by skos:broaderTransitive."""
    for conc, parent1 in rdf.subject_objects(SKOS.broader):
        for parent2 in rdf.objects(conc, SKOS.broader):
            if parent1 == parent2:
                continue
            if parent2 in rdf.transitive_objects(parent1, SKOS.broader):
                if fix:
                    logging.warning('Eliminating redundant hierarchical relationship: %s skos:broader %s', conc, parent2)
                    rdf.remove((conc, SKOS.broader, parent2))
                    rdf.remove((conc, SKOS.broaderTransitive, parent2))
                    rdf.remove((parent2, SKOS.narrower, conc))
                    rdf.remove((parent2, SKOS.narrowerTransitive, conc))
                else:
                    logging.warning('Redundant hierarchical relationship %s skos:broader %s found, but not eliminated because eliminate_redundancy is not set', conc, parent2)

def find_prop_overlap(rdf, prop1, prop2):
    """Generate (subject,object) pairs connected by two properties."""
    for s, o in sorted(rdf.subject_objects(prop1)):
        if (s, prop2, o) in rdf:
            yield (s, o)

def skos_related(rdf):
    """Make sure that skos:related is stated in both directions (S23)."""
    for s, o in rdf.subject_objects(SKOS.related):
        rdf.add((o, SKOS.related, s))

def skos_topConcept(rdf):
    """Infer skos:topConceptOf/skos:hasTopConcept (S8) and skos:inScheme (S7)."""
    for s, o in rdf.subject_objects(SKOS.hasTopConcept):
        rdf.add((o, SKOS.topConceptOf, s))
    for s, o in rdf.subject_objects(SKOS.topConceptOf):
        rdf.add((o, SKOS.hasTopConcept, s))
    for s, o in rdf.subject_objects(SKOS.topConceptOf):
        rdf.add((s, SKOS.inScheme, o))

def skos_hierarchical(rdf, narrower=True):
    """Infer skos:broader/skos:narrower (S25) but only keep skos:narrower on request.

    :param bool narrower: If set to False, skos:narrower will not be added,
        but rather removed."""
    if narrower:
        for s, o in rdf.subject_objects(SKOS.broader):
            rdf.add((o, SKOS.narrower, s))
    for s, o in rdf.subject_objects(SKOS.narrower):
        rdf.add((o, SKOS.broader, s))
        if not narrower:
            rdf.remove((s, SKOS.narrower, o))

def skos_transitive(rdf, narrower=True):
    """Perform transitive closure inference (S22, S24)."""
    for conc in rdf.subjects(RDF.type, SKOS.Concept):
        for bt in rdf.transitive_objects(conc, SKOS.broader):
            if bt == conc:
                continue
            rdf.add((conc, SKOS.broaderTransitive, bt))
            if narrower:
                rdf.add((bt, SKOS.narrowerTransitive, conc))

def skos_symmetric_mappings(rdf, related=True):
    """Ensure that the symmetric mapping properties (skos:relatedMatch,
    skos:closeMatch and skos:exactMatch) are stated in both directions (S44).

    :param bool related: Add the skos:related super-property for all
        skos:relatedMatch relations (S41)."""
    for s, o in rdf.subject_objects(SKOS.relatedMatch):
        rdf.add((o, SKOS.relatedMatch, s))
        if related:
            rdf.add((s, SKOS.related, o))
            rdf.add((o, SKOS.related, s))
    for s, o in rdf.subject_objects(SKOS.closeMatch):
        rdf.add((o, SKOS.closeMatch, s))
    for s, o in rdf.subject_objects(SKOS.exactMatch):
        rdf.add((o, SKOS.exactMatch, s))

def skos_hierarchical_mappings(rdf, narrower=True):
    """Infer skos:broadMatch/skos:narrowMatch (S43) and add the super-properties
    skos:broader/skos:narrower (S41).

    :param bool narrower: If set to False, skos:narrowMatch will not be added,
        but rather removed."""
    for s, o in rdf.subject_objects(SKOS.broadMatch):
        rdf.add((s, SKOS.broader, o))
        if narrower:
            rdf.add((o, SKOS.narrowMatch, s))
            rdf.add((o, SKOS.narrower, s))
    for s, o in rdf.subject_objects(SKOS.narrowMatch):
        rdf.add((o, SKOS.broadMatch, s))
        rdf.add((o, SKOS.broader, s))
        if narrower:
            rdf.add((s, SKOS.narrower, o))
        else:
            rdf.remove((s, SKOS.narrowMatch, o))

def rdfs_classes(rdf):
    """Perform RDFS subclass inference.

    Mark all resources with a subclass type with the upper class."""
    upperclasses = {}
    for s, o in rdf.subject_objects(RDFS.subClassOf):
        upperclasses.setdefault(s, set())
        for uc in rdf.transitive_objects(s, RDFS.subClassOf):
            if uc != s:
                upperclasses[s].add(uc)
    for s, ucs in upperclasses.items():
        logging.debug('setting superclass types: %s -> %s', s, str(ucs))
        for res in rdf.subjects(RDF.type, s):
            for uc in ucs:
                rdf.add((res, RDF.type, uc))

def rdfs_properties(rdf):
    """Perform RDFS subproperty inference.

    Add superproperties where subproperties have been used."""
    superprops = {}
    for s, o in rdf.subject_objects(RDFS.subPropertyOf):
        superprops.setdefault(s, set())
        for sp in rdf.transitive_objects(s, RDFS.subPropertyOf):
            if sp != s:
                superprops[s].add(sp)
    for p, sps in superprops.items():
        logging.debug('setting superproperties: %s -> %s', p, str(sps))
        for s, o in rdf.subject_objects(p):
            for sp in sps:
                rdf.add((s, sp, o))

def overextends(parser, token):
    """Extended version of Django's ``extends`` tag that allows circular
    inheritance to occur, eg a template can both be overridden and
    extended at once."""
    bits = token.split_contents()
    if len(bits) != 2:
        raise TemplateSyntaxError("'%s' takes one argument" % bits[0])
    parent_name = parser.compile_filter(bits[1])
    nodelist = parser.parse()
    if nodelist.get_nodes_by_type(ExtendsNode):
        raise TemplateSyntaxError("'%s' cannot appear more than once in the same template" % bits[0])
    return OverExtendsNode(nodelist, parent_name, None)

def main():
    """Read command line parameters and make a transform based on them."""
    config = Config()
    defaults = vars(config)
    defaults['to_format'] = None
    defaults['output'] = '-'
    defaults['log'] = None
    defaults['debug'] = False
    options, remainingArgs = get_option_parser(defaults).parse_args()
    for key in vars(options):
        if hasattr(config, key):
            setattr(config, key, getattr(options, key))
    logformat = '%(levelname)s: %(message)s'
    loglevel = logging.INFO
    if options.debug:
        loglevel = logging.DEBUG
    if options.log:
        logging.basicConfig(filename=options.log, format=logformat, level=loglevel)
    else:
        logging.basicConfig(format=logformat, level=loglevel)
    output = options.output
    to_format = options.to_format
    if options.config is not None:
        config.read_and_parse_config_file(options.config)
        options, remainingArgs = get_option_parser(vars(config)).parse_args()
        for key in vars(options):
            if hasattr(config, key):
                setattr(config, key, getattr(options, key))
    if remainingArgs:
        inputfiles = remainingArgs
    else:
        inputfiles = ['-']
    voc = skosify(*inputfiles, **vars(config))
    write_rdf(voc, output, to_format)

