def _encode_uvarint(data, n):
    """Encodes integer into variable-length format into data."""
    if n < 0:
        raise ValueError('only support positive integer')
    while True:
        this_byte = n & 127
        n >>= 7
        if n == 0:
            data.append(this_byte)
            break
        data.append(this_byte | 128)

def _caveat_v1_to_dict(c):
    """Return a caveat as a dictionary for export as the JSON
    macaroon v1 format."""
    serialized = {}
    if len(c.caveat_id) > 0:
        serialized['cid'] = c.caveat_id
    if c.verification_key_id:
        serialized['vid'] = utils.raw_urlsafe_b64encode(c.verification_key_id).decode('utf-8')
    if c.location:
        serialized['cl'] = c.location
    return serialized

def _caveat_v2_to_dict(c):
    """Return a caveat as a dictionary for export as the JSON
    macaroon v2 format."""
    serialized = {}
    if len(c.caveat_id_bytes) > 0:
        _add_json_binary_field(c.caveat_id_bytes, serialized, 'i')
    if c.verification_key_id:
        _add_json_binary_field(c.verification_key_id, serialized, 'v')
    if c.location:
        serialized['l'] = c.location
    return serialized

def _read_json_binary_field(deserialized, field):
    """Read the value of a JSON field that may be string or base64-encoded.
    """
    val = deserialized.get(field)
    if val is not None:
        return utils.convert_to_bytes(val)
    val = deserialized.get(field + '64')
    if val is None:
        return None
    return utils.raw_urlsafe_b64decode(val)

def is_nullable_list(val, vtype):
    """Return True if list contains either values of type `vtype` or None."""
    return isinstance(val, list) and any((isinstance(v, vtype) for v in val)) and all((isinstance(v, vtype) or v is None for v in val))

def pad(s, n, p=' ', sep='|', align='left'):
    '''Returns a padded string.
    s = string to pad
    n = width of string to return
    sep = separator (on end of string)
    align = text alignment, "left", "center", or "right"'''
    if align == 'left':
        return (s + p * n)[:n] + sep
    elif align == 'center':
        pos = n + len(s) / 2 - n / 2
        return (p * n + s + p * n)[pos:pos + n] + sep
    elif align == 'right':
        return (p * n + s)[-n:] + sep

def sumMerge(dict1, dict2):
    """Adds two dictionaries together, and merges into the first, dict1.
    Returns first dict."""
    for key in dict2:
        dict1[key] = list(map(lambda a, b: a + b, dict1.get(key, [0, 0, 0, 0]), dict2[key]))
    return dict1

def ndim(n, *args, **kwargs):
    """Makes a multi-dimensional array of random floats. (Replaces RandomArray)."""
    thunk = kwargs.get('thunk', lambda: random.random())
    if not args:
        return [thunk() for i in range(n)]
    A = []
    for i in range(n):
        A.append(ndim(*args, thunk=thunk))
    return A

def randomArray(size, bound):
    """Returns an array initialized to random values between -max and max."""
    if type(size) == type(1):
        size = (size,)
    temp = Numeric.array(ndim(*size)) * (2.0 * bound)
    return temp - bound

def displayArray(name, a, width=0):
    """Prints an array (any sequence of floats, really) to the screen."""
    print(name + ': ', end=' ')
    cnt = 0
    for i in a:
        print('%4.2f' % i, end=' ')
        if width > 0 and (cnt + 1) % width == 0:
            print('')
        cnt += 1

def toStringArray(name, a, width=0):
    """Returns an array (any sequence of floats, really) as a string."""
    string = name + ': '
    cnt = 0
    for i in a:
        string += '%4.2f  ' % i
        if width > 0 and (cnt + 1) % width == 0:
            string += '\n'
        cnt += 1
    return string

def writeArray(fp, a, delim=' ', nl=1):
    """Writes a sequence a of floats to file pointed to by file pointer."""
    for i in a:
        fp.write('%f%s' % (i, delim))
    if nl:
        fp.write('\n')

def pycomplex(v_str):
    """Convert string repr of Fortran complex to Python complex."""
    assert isinstance(v_str, str)
    if v_str[0] == '(' and v_str[-1] == ')' and (len(v_str.split(',')) == 2):
        v_re, v_im = v_str[1:-1].split(',', 1)
        return complex(pyfloat(v_re), pyfloat(v_im))
    else:
        raise ValueError('{0} must be in complex number form (x, y).'.format(v_str))

def pybool(v_str, strict_logical=True):
    """Convert string repr of Fortran logical to Python logical."""
    assert isinstance(v_str, str)
    assert isinstance(strict_logical, bool)
    if strict_logical:
        v_bool = v_str.lower()
    else:
        try:
            if v_str.startswith('.'):
                v_bool = v_str[1].lower()
            else:
                v_bool = v_str[0].lower()
        except IndexError:
            raise ValueError('{0} is not a valid logical constant.'.format(v_str))
    if v_bool in ('.true.', '.t.', 'true', 't'):
        return True
    elif v_bool in ('.false.', '.f.', 'false', 'f'):
        return False
    else:
        raise ValueError('{0} is not a valid logical constant.'.format(v_str))

def pystr(v_str):
    """Convert string repr of Fortran string to Python string."""
    assert isinstance(v_str, str)
    if v_str[0] in ("'", '"') and v_str[0] == v_str[-1]:
        quote = v_str[0]
        out = v_str[1:-1]
    else:
        quote = None
        out = v_str
    if quote:
        out = out.replace(2 * quote, quote)
    return out

def pad_array(v, idx):
    """Expand lists in multidimensional arrays to pad unset values."""
    i_v, i_s = idx[0]
    if len(idx) > 1:
        v.extend([[] for _ in range(len(v), i_v - i_s + 1)])
        for e in v:
            pad_array(e, idx[1:])
    else:
        v.extend([None for _ in range(len(v), i_v - i_s + 1)])

def merge_values(src, new):
    """Merge two lists or dicts into a single element."""
    if isinstance(src, dict) and isinstance(new, dict):
        return merge_dicts(src, new)
    else:
        if not isinstance(src, list):
            src = [src]
        if not isinstance(new, list):
            new = [new]
        return merge_lists(src, new)

def merge_lists(src, new):
    """Update a value list with a list of new or updated values."""
    l_min, l_max = (src, new) if len(src) < len(new) else (new, src)
    l_min.extend((None for i in range(len(l_min), len(l_max))))
    for i, val in enumerate(new):
        if isinstance(val, dict) and isinstance(src[i], dict):
            new[i] = merge_dicts(src[i], val)
        elif isinstance(val, list) and isinstance(src[i], list):
            new[i] = merge_lists(src[i], val)
        elif val is not None:
            new[i] = val
        else:
            new[i] = src[i]
    return new

def merge_dicts(src, patch):
    """Merge contents of dict `patch` into `src`."""
    for key in patch:
        if key in src:
            if isinstance(src[key], dict) and isinstance(patch[key], dict):
                merge_dicts(src[key], patch[key])
            else:
                src[key] = merge_values(src[key], patch[key])
        else:
            src[key] = patch[key]
    return src

def delist(values):
    """Reduce lists of zero or one elements to individual values."""
    assert isinstance(values, list)
    if not values:
        return None
    elif len(values) == 1:
        return values[0]
    return values

def count_values(tokens):
    """Identify the number of values ahead of the current token."""
    ntoks = 0
    for tok in tokens:
        if tok in ('=', '/', '$', '&'):
            if ntoks > 0 and tok == '=':
                ntoks -= 1
            break
        elif tok in whitespace + ',':
            continue
        else:
            ntoks += 1
    return ntoks

