def pday(dayfmt):
    """P the day

    >>> print(pday('2012-08-24'))
    Friday the 24th"""
    year, month, day = map(int, dayfmt.split('-'))
    return '{day} the {number}'.format(day=calendar.day_name[calendar.weekday(year, month, day)], number=inflect.engine().ordinal(day))

