def completion_hints(config, prompt, session, context, current, arguments):
    """Returns the possible completions of the current argument

    :param config: Configuration of the current completion
    :param prompt: The shell prompt string
    :param session: Current shell session
    :param context: Context of the shell UI bundle
    :param current: Current argument (to be completed)
    :param arguments: List of all arguments in their current state
    :return: A list of possible completions"""
    if not current:
        arg_idx = len(arguments)
    else:
        arg_idx = arguments.index(current)
    completers = config.completers
    if arg_idx > len(completers) - 1:
        if config.multiple:
            completer_id = completers[-1]
        else:
            return []
    else:
        completer_id = completers[arg_idx]
    if completer_id == DUMMY:
        return []
    svc_ref = context.get_service_reference(SVC_COMPLETER, '({}={})'.format(PROP_COMPLETER_ID, completer_id))
    if svc_ref is None:
        _logger.debug('Unknown shell completer ID: %s', completer_id)
        return []
    try:
        with use_service(context, svc_ref) as completer:
            matches = completer.complete(config, prompt, session, context, arguments, current)
            if not matches:
                return []
            return matches
    except Exception as ex:
        _logger.exception('Error calling completer %s: %s', completer_id, ex)
        return []

def handle_common_arguments(parsed_args):
    """Handles the arguments defined by :meth:`~make_common_parser`

    :param parsed_args: Argument parsed with ``argparse`` (``Namespace``)
    :return: An :class:`~InitFileHandler` object
    :raise IOError: Initial or run script not found"""
    logging.basicConfig(level=logging.DEBUG if parsed_args.verbose else logging.WARNING)
    props = {}
    init = InitFileHandler()
    if not parsed_args.init_empty:
        if not parsed_args.init_conf_exclusive:
            init.load()
        conf_file = parsed_args.init_conf_exclusive or parsed_args.init_conf
        if conf_file:
            init.load(conf_file)
        init.normalize()
        props.update(init.properties)
    for prop_def in parsed_args.properties or []:
        key, value = prop_def.split('=', 1)
        props[key] = value
    if parsed_args.init_script:
        path = props[PROP_INIT_FILE] = _resolve_file(parsed_args.init_script)
        if not path:
            raise IOError('Initial script file not found: {0}'.format(parsed_args.init_script))
    if parsed_args.run_script:
        path = props[PROP_RUN_FILE] = _resolve_file(parsed_args.run_script)
        if not path:
            raise IOError('Script file not found: {0}'.format(parsed_args.run_script))
    init.properties.update(props)
    return init

def is_lock(lock):
    """Tests if the given lock is an instance of a lock class"""
    if lock is None:
        return False
    for attr in ('acquire', 'release', '__enter__', '__exit__'):
        if not hasattr(lock, attr):
            return False
    return True

def _make_args(args_list, session, fw_props):
    """Converts the given list of arguments into a list (args) and a
    dictionary (kwargs).
    All arguments with an assignment are put into kwargs, others in args.

    :param args_list: The list of arguments to be treated
    :param session: The current shell session
    :return: The (arg_token, kwargs) tuple."""
    args = []
    kwargs = {}
    for arg_token in args_list:
        idx = _find_assignment(arg_token)
        if idx != -1:
            key = arg_token[:idx]
            value = arg_token[idx + 1:]
            kwargs[key] = value
        else:
            args.append(arg_token)
    variables = collections.defaultdict(str)
    variables.update(fw_props)
    variables.update(session.variables)
    args = [_ArgTemplate(arg).safe_substitute(variables) for arg in args]
    kwargs = {key: _ArgTemplate(value).safe_substitute(variables) for key, value in kwargs.items()}
    return (args, kwargs)

def _split_ns_command(cmd_token):
    """Extracts the name space and the command name of the given command token.

    :param cmd_token: The command token
    :return: The extracted (name space, command) tuple"""
    namespace = None
    cmd_split = cmd_token.split('.', 1)
    if len(cmd_split) == 1:
        command = cmd_split[0]
    else:
        namespace = cmd_split[0]
        command = cmd_split[1]
    if not namespace:
        namespace = ''
    return (namespace.lower(), command.lower())

def unescape(b, encoding):
    """Unescape all string and unicode literals in bytes."""
    return string_literal_re.sub(lambda m: unescape_string_literal(m.group(), encoding), b)

def make_unistream(stream):
    """Make a stream which unescapes string literals before writes out."""
    unistream = lambda: 'I am an unistream!'
    for attr_name in dir(stream):
        if not attr_name.startswith('_'):
            setattr(unistream, attr_name, getattr(stream, attr_name))
    unistream.write = lambda b: stream.write(unescape(to_bytes(b, unistream.encoding), unistream.encoding))
    return unistream

def format_frame_info(frame):
    """Formats the given stack frame to show its position in the code and
    part of its context

    :param frame: A stack frame"""
    line_no = frame.f_lineno
    code = frame.f_code
    filename = code.co_filename
    method_name = code.co_name
    linecache.checkcache(filename)
    try:
        instance = frame.f_locals['self']
        method_name = '{0}::{1}'.format(type(instance).__name__, method_name)
    except KeyError:
        pass
    output_lines = ['  File "{0}", line {1}, in {2}'.format(filename, line_no, method_name)]
    if frame.f_locals:
        arg_info = inspect.getargvalues(frame)
        for name in arg_info.args:
            try:
                output_lines.append('    - {0:s} = {1}'.format(name, repr(frame.f_locals[name])))
            except TypeError:
                name = name[0]
                output_lines.append('    - {0:s} = {1}'.format(name, repr(frame.f_locals[name])))
        if arg_info.varargs:
            output_lines.append('    - *{0:s} = {1}'.format(arg_info.varargs, frame.f_locals[arg_info.varargs]))
        if arg_info.keywords:
            output_lines.append('    - **{0:s} = {1}'.format(arg_info.keywords, frame.f_locals[arg_info.keywords]))
    lines = _extract_lines(filename, frame.f_globals, line_no, 3)
    if lines:
        output_lines.append('')
        prefix = '      '
        output_lines.append('{0}{1}'.format(prefix, '\n{0}'.format(prefix).join(lines)))
    return '\n'.join(output_lines)

def make_mreq(family, address):
    """Makes a mreq structure object for the given address and socket family.

    :param family: A socket family (AF_INET or AF_INET6)
    :param address: A multicast address (group)
    :raise ValueError: Invalid family or address"""
    if not address:
        raise ValueError('Empty address')
    group_bin = pton(family, address)
    if family == socket.AF_INET:
        return group_bin + struct.pack('=I', socket.INADDR_ANY)
    elif family == socket.AF_INET6:
        return group_bin + struct.pack('@I', 0)
    raise ValueError('Unknown family {0}'.format(family))

def close_multicast_socket(sock, address):
    """Cleans up the given multicast socket.
    Unregisters it of the multicast group.

    Parameters should be the result of create_multicast_socket

    :param sock: A multicast socket
    :param address: The multicast address used by the socket"""
    if sock is None:
        return
    if address:
        mreq = make_mreq(sock.family, address)
        if sock.family == socket.AF_INET:
            sock.setsockopt(socket.IPPROTO_IP, socket.IP_DROP_MEMBERSHIP, mreq)
        elif sock.family == socket.AF_INET6:
            sock.setsockopt(ipproto_ipv6(), socket.IPV6_LEAVE_GROUP, mreq)
    sock.close()

def _set_factory_context(factory_class, bundle_context):
    """Transforms the context data dictionary into its FactoryContext object form.

    :param factory_class: A manipulated class
    :param bundle_context: The class bundle context
    :return: The factory context, None on error"""
    try:
        context = getattr(factory_class, constants.IPOPO_FACTORY_CONTEXT)
    except AttributeError:
        return None
    if not context.completed:
        return None
    context.set_bundle_context(bundle_context)
    return context

def _load_bundle_factories(bundle):
    """Retrieves a list of pairs (FactoryContext, factory class) with all
    readable manipulated classes found in the bundle.

    :param bundle: A Bundle object
    :return: The list of factories loaded from the bundle"""
    result = []
    module_ = bundle.get_module()
    bundle_context = bundle.get_bundle_context()
    for name in dir(module_):
        try:
            factory_class = getattr(module_, name)
            if not inspect.isclass(factory_class):
                continue
            if sys.modules[factory_class.__module__] is not module_:
                continue
        except (AttributeError, KeyError):
            continue
        context = _set_factory_context(factory_class, bundle_context)
        if context is None:
            continue
        result.append((context, factory_class))
    return result

def set_double_stack(socket_obj, double_stack=True):
    """Sets up the IPv6 double stack according to the operating system

    :param socket_obj: A socket object
    :param double_stack: If True, use the double stack, else only support IPv6
    :raise AttributeError: Python or system doesn't support V6
    :raise socket.error: Error setting up the double stack value"""
    try:
        opt_ipv6_only = socket.IPV6_V6ONLY
    except AttributeError:
        if os.name == 'nt':
            opt_ipv6_only = 27
        elif platform.system() == 'Linux':
            opt_ipv6_only = 26
        else:
            raise
    socket_obj.setsockopt(ipproto_ipv6(), opt_ipv6_only, int(not double_stack))

def escape_LDAP(ldap_string):
    """Escape a string to let it go in an LDAP filter

    :param ldap_string: The string to escape
    :return: The protected string"""
    if not ldap_string:
        return ldap_string
    assert is_string(ldap_string)
    ldap_string = ldap_string.replace(ESCAPE_CHARACTER, ESCAPE_CHARACTER + ESCAPE_CHARACTER)
    if ldap_string.startswith(' '):
        ldap_string = '\\ {0}'.format(ldap_string[1:])
    if ldap_string.endswith(' '):
        ldap_string = '{0}\\ '.format(ldap_string[:-1])
    for escaped in ESCAPED_CHARACTERS:
        ldap_string = ldap_string.replace(escaped, ESCAPE_CHARACTER + escaped)
    return ldap_string

def unescape_LDAP(ldap_string):
    """Unespaces an LDAP string

    :param ldap_string: The string to unescape
    :return: The unprotected string"""
    if ldap_string is None:
        return None
    if ESCAPE_CHARACTER not in ldap_string:
        return ldap_string
    escaped = False
    result = ''
    for character in ldap_string:
        if not escaped and character == ESCAPE_CHARACTER:
            escaped = True
        else:
            escaped = False
            result += character
    return result

def _comparator_presence(_, tested_value):
    """Tests a filter which simply a joker, i.e. a value presence test"""
    if tested_value is None:
        return False
    elif hasattr(tested_value, '__len__'):
        return len(tested_value) != 0
    return True

def _comparator_star(filter_value, tested_value):
    """Tests a filter containing a joker"""
    if isinstance(tested_value, ITERABLES):
        for value in tested_value:
            if _star_comparison(filter_value, value):
                return True
        return False
    return _star_comparison(filter_value, tested_value)

def _star_comparison(filter_value, tested_value):
    """Tests a filter containing a joker"""
    if not is_string(tested_value):
        return False
    parts = filter_value.split('*')
    i = 0
    last_part = len(parts) - 1
    idx = 0
    for part in parts:
        idx = tested_value.find(part, idx)
        if idx == -1:
            return False
        len_part = len(part)
        if i == 0 and len_part != 0 and (idx != 0):
            return False
        if i == last_part and len_part != 0 and (idx != len(tested_value) - len_part):
            return False
        idx += len_part
        i += 1
    return True

def _comparator_eq(filter_value, tested_value):
    """Tests if the filter value is equal to the tested value"""
    if isinstance(tested_value, ITERABLES):
        for value in tested_value:
            if not is_string(value):
                value = repr(value)
            if filter_value == value:
                return True
    elif not is_string(tested_value):
        return filter_value == repr(tested_value)
    else:
        return filter_value == tested_value
    return False

def _comparator_approximate(filter_value, tested_value):
    """Tests if the filter value is nearly equal to the tested value.

    If the tested value is a string or an array of string, it compares their
    lower case forms"""
    lower_filter_value = filter_value.lower()
    if is_string(tested_value):
        return _comparator_eq(lower_filter_value, tested_value.lower())
    elif hasattr(tested_value, '__iter__'):
        new_tested = [value.lower() for value in tested_value if is_string(value)]
        if _comparator_eq(lower_filter_value, new_tested):
            return True
    return _comparator_eq(filter_value, tested_value) or _comparator_eq(lower_filter_value, tested_value)

def _comparator_approximate_star(filter_value, tested_value):
    """Tests if the filter value, which contains a joker, is nearly equal to the
    tested value.

    If the tested value is a string or an array of string, it compares their
    lower case forms"""
    lower_filter_value = filter_value.lower()
    if is_string(tested_value):
        return _comparator_star(lower_filter_value, tested_value.lower())
    elif hasattr(tested_value, '__iter__'):
        new_tested = [value.lower() for value in tested_value if is_string(value)]
        if _comparator_star(lower_filter_value, new_tested):
            return True
    return _comparator_star(filter_value, tested_value) or _comparator_star(lower_filter_value, tested_value)

def _comparator_lt(filter_value, tested_value):
    """Tests if the filter value is strictly greater than the tested value

    tested_value < filter_value"""
    if is_string(filter_value):
        value_type = type(tested_value)
        try:
            filter_value = value_type(filter_value)
        except (TypeError, ValueError):
            if value_type is int:
                try:
                    filter_value = float(filter_value)
                except (TypeError, ValueError):
                    return False
            else:
                return False
    try:
        return tested_value < filter_value
    except TypeError:
        return False

def _compute_comparator(string, idx):
    """Tries to compute the LDAP comparator at the given index

    Valid operators are :

    * = : equality
    * <= : less than
    * >= : greater than
    * ~= : approximate

    :param string: A LDAP filter string
    :param idx: An index in the given string
    :return: The corresponding operator, None if unknown"""
    part1 = string[idx]
    try:
        part2 = string[idx + 1]
    except IndexError:
        return None
    if part1 == '=':
        return _comparator_eq
    elif part2 != '=':
        if part1 == '<':
            return _comparator_lt
        elif part1 == '>':
            return _comparator_gt
    elif part1 == '<':
        return _comparator_le
    elif part1 == '>':
        return _comparator_ge
    elif part1 == '~':
        return _comparator_approximate
    return None

def get_ldap_filter(ldap_filter):
    """Retrieves the LDAP filter object corresponding to the given filter.
    Parses it the argument if it is an LDAPFilter instance

    :param ldap_filter: An LDAP filter (LDAPFilter or string)
    :return: The corresponding filter, can be None
    :raise ValueError: Invalid filter string found
    :raise TypeError: Unknown filter type"""
    if ldap_filter is None:
        return None
    if isinstance(ldap_filter, (LDAPFilter, LDAPCriteria)):
        return ldap_filter
    elif is_string(ldap_filter):
        return _parse_ldap(ldap_filter)
    raise TypeError('Unhandled filter type {0}'.format(type(ldap_filter).__name__))

def combine_filters(filters, operator=AND):
    """Combines two LDAP filters, which can be strings or LDAPFilter objects

    :param filters: Filters to combine
    :param operator: The operator for combination
    :return: The combined filter, can be None if all filters are None
    :raise ValueError: Invalid filter string found
    :raise TypeError: Unknown filter type"""
    if not filters:
        return None
    if not hasattr(filters, '__iter__') or is_string(filters):
        raise TypeError('Filters argument must be iterable')
    ldap_filters = []
    for sub_filter in filters:
        if sub_filter is None:
            continue
        ldap_filter = get_ldap_filter(sub_filter)
        if ldap_filter is not None:
            ldap_filters.append(ldap_filter)
    if not ldap_filters:
        return None
    elif len(ldap_filters) == 1:
        return ldap_filters[0]
    new_filter = LDAPFilter(operator)
    for sub_filter in ldap_filters:
        new_filter.append(sub_filter)
    return new_filter.normalize()

def walk_modules(path):
    """Code from ``pkgutil.ImpImporter.iter_modules()``: walks through a folder
    and yields all loadable packages and modules.

    :param path: Path where to look for modules
    :return: Generator to walk through found packages and modules"""
    if path is None or not os.path.isdir(path):
        return
    yielded = set()
    try:
        file_names = os.listdir(path)
    except OSError:
        file_names = []
    file_names.sort()
    for filename in file_names:
        modname = inspect.getmodulename(filename)
        if modname == '__init__' or modname in yielded:
            continue
        file_path = os.path.join(path, filename)
        is_package = False
        if not modname and os.path.isdir(file_path) and ('.' not in filename):
            modname = filename
            try:
                dir_contents = os.listdir(file_path)
            except OSError:
                dir_contents = []
            for sub_filename in dir_contents:
                sub_name = inspect.getmodulename(sub_filename)
                if sub_name == '__init__':
                    is_package = True
                    break
            else:
                continue
        if modname and '.' not in modname:
            yielded.add(modname)
            yield (modname, is_package)

def _package_exists(path):
    """Checks if the given Python path matches a valid file or a valid container
    file

    :param path: A Python path
    :return: True if the module or its container exists"""
    while path:
        if os.path.exists(path):
            return True
        else:
            path = os.path.dirname(path)
    return False

def normalize_path():
    """Normalizes sys.path to avoid the use of relative folders"""
    whole_path = [os.path.abspath(path) for path in sys.path if os.path.exists(path)]
    whole_set = collections.OrderedDict((('', 1), (os.getcwd(), 1)))
    for path in whole_path:
        if path not in whole_set:
            whole_set[path] = 1
    sys.path = list(whole_set)
    for module_ in sys.modules.values():
        try:
            module_.__path__ = [os.path.abspath(path) for path in module_.__path__ if _package_exists(path)]
        except AttributeError:
            pass
        except ImportError:
            pass

def get_matching_interfaces(object_class, exported_intfs):
    """Returns the list of interfaces matching the export property

    :param object_class: The specifications of the service
    :param exported_intfs: The declared exported interfaces
    :return: The list of declared exported interfaces"""
    if object_class is None or exported_intfs is None:
        return None
    if isinstance(exported_intfs, str) and exported_intfs == '*':
        return object_class
    exported_intfs = get_string_plus_property_value(exported_intfs)
    if len(exported_intfs) == 1 and exported_intfs[0] == '*':
        return object_class
    return exported_intfs

def get_prop_value(name, props, default=None):
    """Returns the value of a property or the default one

    :param name: Name of a property
    :param props: Dictionary of properties
    :param default: Default value
    :return: The value of the property or the default one"""
    if not props:
        return default
    try:
        return props[name]
    except KeyError:
        return default

def get_string_plus_property_value(value):
    """Converts a string or list of string into a list of strings

    :param value: A string or a list of strings
    :return: A list of strings or None"""
    if value:
        if isinstance(value, str):
            return [value]
        if isinstance(value, list):
            return value
        if isinstance(value, tuple):
            return list(value)
    return None

def get_exported_interfaces(svc_ref, overriding_props=None):
    """Looks for the interfaces exported by a service

    :param svc_ref: Service reference
    :param overriding_props: Properties overriding service ones
    :return: The list of exported interfaces"""
    exported_intfs = get_prop_value(SERVICE_EXPORTED_INTERFACES, overriding_props)
    if not exported_intfs:
        exported_intfs = svc_ref.get_property(SERVICE_EXPORTED_INTERFACES)
    if not exported_intfs:
        return None
    return get_matching_interfaces(svc_ref.get_property(constants.OBJECTCLASS), exported_intfs)

def validate_exported_interfaces(object_class, exported_intfs):
    """Validates that the exported interfaces are all provided by the service

    :param object_class: The specifications of a service
    :param exported_intfs: The exported specifications
    :return: True if the exported specifications are all provided by the service"""
    if not exported_intfs or not isinstance(exported_intfs, list) or (not exported_intfs):
        return False
    else:
        for exintf in exported_intfs:
            if exintf not in object_class:
                return False
    return True

def get_edef_props(object_class, exported_cfgs, ep_namespace, ep_id, ecf_ep_id, ep_rsvc_id, ep_ts, remote_intents=None, fw_id=None, pkg_ver=None, service_intents=None):
    """Prepares the EDEF properties of an endpoint, merge of RSA and ECF
    properties"""
    osgi_props = get_rsa_props(object_class, exported_cfgs, remote_intents, ep_rsvc_id, fw_id, pkg_ver, service_intents)
    ecf_props = get_ecf_props(ecf_ep_id, ep_namespace, ep_rsvc_id, ep_ts)
    return merge_dicts(osgi_props, ecf_props)

def get_dot_properties(prefix, props, remove_prefix):
    """Gets the properties starting with the given prefix"""
    result_props = {}
    if props:
        dot_keys = [x for x in props.keys() if x.startswith(prefix + '.')]
        for dot_key in dot_keys:
            if remove_prefix:
                new_key = dot_key[len(prefix) + 1:]
            else:
                new_key = dot_key
            result_props[new_key] = props.get(dot_key)
    return result_props

def set_append(input_set, item):
    """Appends in-place the given item to the set.
    If the item is a list, all elements are added to the set.

    :param input_set: An existing set
    :param item: The item or list of items to add
    :return: The given set"""
    if item:
        if isinstance(item, (list, tuple)):
            input_set.update(item)
        else:
            input_set.add(item)
    return input_set

def package_name(package):
    """Returns the package name of the given module name"""
    if not package:
        return ''
    lastdot = package.rfind('.')
    if lastdot == -1:
        return package
    return package[:lastdot]

def encode_osgi_props(ed):
    """Prepares a dictionary of OSGi properties for the given EndpointDescription"""
    result_props = {}
    intfs = ed.get_interfaces()
    result_props[OBJECTCLASS] = ' '.join(intfs)
    for intf in intfs:
        pkg_name = package_name(intf)
        ver = ed.get_package_version(pkg_name)
        if ver and (not ver == (0, 0, 0)):
            result_props[ENDPOINT_PACKAGE_VERSION_] = '.'.join((str(v) for v in ver))
    result_props[ENDPOINT_ID] = ed.get_id()
    result_props[ENDPOINT_SERVICE_ID] = '{0}'.format(ed.get_service_id())
    result_props[ENDPOINT_FRAMEWORK_UUID] = ed.get_framework_uuid()
    imp_configs = ed.get_imported_configs()
    if imp_configs:
        result_props[SERVICE_IMPORTED_CONFIGS] = ' '.join(ed.get_imported_configs())
    intents = ed.get_intents()
    if intents:
        result_props[SERVICE_INTENTS] = ' '.join(intents)
    remote_configs = ed.get_remote_configs_supported()
    if remote_configs:
        result_props[REMOTE_CONFIGS_SUPPORTED] = ' '.join(remote_configs)
    remote_intents = ed.get_remote_intents_supported()
    if remote_intents:
        result_props[REMOTE_INTENTS_SUPPORTED] = ' '.join(remote_intents)
    return result_props

def decode_osgi_props(input_props):
    """Decodes the OSGi properties of the given endpoint properties"""
    result_props = {}
    intfs = decode_list(input_props, OBJECTCLASS)
    result_props[OBJECTCLASS] = intfs
    for intf in intfs:
        package_key = ENDPOINT_PACKAGE_VERSION_ + package_name(intf)
        intfversionstr = input_props.get(package_key, None)
        if intfversionstr:
            result_props[package_key] = intfversionstr
    result_props[ENDPOINT_ID] = input_props[ENDPOINT_ID]
    result_props[ENDPOINT_SERVICE_ID] = input_props[ENDPOINT_SERVICE_ID]
    result_props[ENDPOINT_FRAMEWORK_UUID] = input_props[ENDPOINT_FRAMEWORK_UUID]
    imp_configs = decode_list(input_props, SERVICE_IMPORTED_CONFIGS)
    if imp_configs:
        result_props[SERVICE_IMPORTED_CONFIGS] = imp_configs
    intents = decode_list(input_props, SERVICE_INTENTS)
    if intents:
        result_props[SERVICE_INTENTS] = intents
    remote_configs = decode_list(input_props, REMOTE_CONFIGS_SUPPORTED)
    if remote_configs:
        result_props[REMOTE_CONFIGS_SUPPORTED] = remote_configs
    remote_intents = decode_list(input_props, REMOTE_INTENTS_SUPPORTED)
    if remote_intents:
        result_props[REMOTE_INTENTS_SUPPORTED] = remote_intents
    return result_props

def encode_endpoint_props(ed):
    """Encodes the properties of the given EndpointDescription"""
    props = encode_osgi_props(ed)
    props[ECF_RSVC_ID] = '{0}'.format(ed.get_remoteservice_id()[1])
    props[ECF_ENDPOINT_ID] = '{0}'.format(ed.get_container_id()[1])
    props[ECF_ENDPOINT_CONTAINERID_NAMESPACE] = '{0}'.format(ed.get_container_id()[0])
    props[ECF_ENDPOINT_TIMESTAMP] = '{0}'.format(ed.get_timestamp())
    ctid = ed.get_connect_target_id()
    if ctid:
        props[ECF_ENDPOINT_CONNECTTARGET_ID] = '{0}'.format(ctid)
    id_filters = ed.get_id_filters()
    if id_filters:
        props[ECF_ENDPOINT_IDFILTER_IDS] = ' '.join([x[1] for x in id_filters])
    rs_filter = ed.get_remoteservice_filter()
    if rs_filter:
        props[ECF_ENDPOINT_REMOTESERVICE_FILTER] = ed.get_remoteservice_filter()
    async_intfs = ed.get_async_interfaces()
    if async_intfs:
        props[ECF_SERVICE_EXPORTED_ASYNC_INTERFACES] = ' '.join(async_intfs)
    all_props = ed.get_properties()
    other_props = {key: all_props[key] for key in all_props.keys() if not is_reserved_property(key)}
    return merge_dicts(props, other_props)

def to_import_properties(properties):
    """Returns a dictionary where export properties have been replaced by import
    ones

    :param properties: A dictionary of service properties (with export keys)
    :return: A dictionary with import properties"""
    props = properties.copy()
    props[pelix.remote.PROP_IMPORTED] = True
    try:
        props[pelix.remote.PROP_ENDPOINT_SERVICE_ID] = props.pop(pelix.constants.SERVICE_ID)
    except KeyError:
        pass
    configs = props.pop(pelix.remote.PROP_EXPORTED_CONFIGS, None)
    if configs:
        props[pelix.remote.PROP_IMPORTED_CONFIGS] = configs
    for key in (pelix.remote.PROP_EXPORTED_INTENTS, pelix.remote.PROP_EXPORTED_INTENTS_EXTRA, pelix.remote.PROP_EXPORTED_INTERFACES):
        try:
            del props[key]
        except KeyError:
            pass
    return props

def extract_specifications(specifications, properties):
    """Converts "python:/name" specifications to "name". Keeps the other
    specifications as is.

    :param specifications: The specifications found in a remote registration
    :param properties: Service properties
    :return: The filtered specifications (as a list)"""
    all_specs = set(pelix.utilities.to_iterable(specifications))
    try:
        synonyms = pelix.utilities.to_iterable(properties[pelix.remote.PROP_SYNONYMS], False)
        all_specs.update(synonyms)
    except KeyError:
        pass
    filtered_specs = set()
    for original in all_specs:
        try:
            lang, spec = _extract_specification_parts(original)
            if lang == PYTHON_LANGUAGE:
                filtered_specs.add(spec)
            else:
                filtered_specs.add(original)
        except ValueError:
            pass
    return list(filtered_specs)

def format_specifications(specifications):
    """Transforms the interfaces names into URI strings, with the interface
    implementation language as a scheme.

    :param specifications: Specifications to transform
    :return: The transformed names"""
    transformed = set()
    for original in specifications:
        try:
            lang, spec = _extract_specification_parts(original)
            transformed.add(_format_specification(lang, spec))
        except ValueError:
            pass
    return list(transformed)

def _extract_specification_parts(specification):
    """Extract the language and the interface from a "language:/interface"
    interface name

    :param specification: The formatted interface name
    :return: A (language, interface name) tuple
    :raise ValueError: Invalid specification content"""
    try:
        parsed = urlparse(specification)
    except:
        raise ValueError('Invalid specification URL: {0}'.format(specification))
    interface = parsed.path
    language = parsed.scheme
    if not language:
        language = PYTHON_LANGUAGE
    else:
        interface = _unescape_specification(interface[1:])
    return (language, interface)

def is_from_parent(cls, attribute_name, value=None):
    """Tests if the current attribute value is shared by a parent of the given
    class.

    Returns None if the attribute value is None.

    :param cls: Child class with the requested attribute
    :param attribute_name: Name of the attribute to be tested
    :param value: The exact value in the child class (optional)
    :return: True if the attribute value is shared with a parent class"""
    if value is None:
        try:
            value = getattr(cls, attribute_name)
        except AttributeError:
            return False
    for base in cls.__bases__:
        try:
            return getattr(base, attribute_name) is value
        except AttributeError:
            pass
    return False

def get_method_description(method):
    """Retrieves a description of the given method. If possible, the description
    contains the source file name and line.

    :param method: A method
    :return: A description of the method (at least its name)
    :raise AttributeError: Given object has no __name__ attribute"""
    try:
        try:
            line_no = inspect.getsourcelines(method)[1]
        except IOError:
            line_no = -1
        return "'{method}' ({file}:{line})".format(method=method.__name__, file=inspect.getfile(method), line=line_no)
    except TypeError:
        return "'{0}'".format(method.__name__)

def validate_method_arity(method, *needed_args):
    """Tests if the decorated method has a sufficient number of parameters.

    :param method: The method to be tested
    :param needed_args: The name (for description only) of the needed
                        arguments, without "self".
    :return: Nothing
    :raise TypeError: Invalid number of parameter"""
    nb_needed_args = len(needed_args)
    arg_spec = get_method_arguments(method)
    method_args = arg_spec.args
    try:
        if method_args[0] == 'self':
            del method_args[0]
    except IndexError:
        pass
    nb_args = len(method_args)
    if arg_spec.varargs is not None:
        if nb_args != 0:
            raise TypeError("When using '*args', the decorated {0} method must only accept the 'self' argument".format(get_method_description(method)))
    elif arg_spec.keywords is not None:
        raise TypeError("Methods using '**kwargs' are not handled")
    elif nb_args != nb_needed_args:
        raise TypeError('The decorated method {0} must accept exactly {1} parameters: (self, {2})'.format(get_method_description(method), nb_needed_args + 1, ', '.join(needed_args)))

def _ipopo_setup_callback(cls, context):
    """Sets up the class _callback dictionary

    :param cls: The class to handle
    :param context: The factory class context"""
    assert inspect.isclass(cls)
    assert isinstance(context, FactoryContext)
    if context.callbacks is not None:
        callbacks = context.callbacks.copy()
    else:
        callbacks = {}
    functions = inspect.getmembers(cls, inspect.isroutine)
    for _, func in functions:
        if not hasattr(func, constants.IPOPO_METHOD_CALLBACKS):
            continue
        method_callbacks = getattr(func, constants.IPOPO_METHOD_CALLBACKS)
        if not isinstance(method_callbacks, list):
            _logger.warning('Invalid callback information %s in %s', constants.IPOPO_METHOD_CALLBACKS, get_method_description(func))
            continue
        for _callback in method_callbacks:
            if _callback in callbacks and (not is_from_parent(cls, callbacks[_callback].__name__, callbacks[_callback])):
                _logger.warning("Redefining the callback %s in class '%s'.\n\tPrevious callback : %s\n\tNew callback : %s", _callback, cls.__name__, get_method_description(callbacks[_callback]), get_method_description(func))
            callbacks[_callback] = func
    context.callbacks.clear()
    context.callbacks.update(callbacks)

def _ipopo_setup_field_callback(cls, context):
    """Sets up the class _field_callback dictionary

    :param cls: The class to handle
    :param context: The factory class context"""
    assert inspect.isclass(cls)
    assert isinstance(context, FactoryContext)
    if context.field_callbacks is not None:
        callbacks = context.field_callbacks.copy()
    else:
        callbacks = {}
    functions = inspect.getmembers(cls, inspect.isroutine)
    for name, func in functions:
        if not hasattr(func, constants.IPOPO_METHOD_FIELD_CALLBACKS):
            continue
        method_callbacks = getattr(func, constants.IPOPO_METHOD_FIELD_CALLBACKS)
        if not isinstance(method_callbacks, list):
            _logger.warning('Invalid attribute %s in %s', constants.IPOPO_METHOD_FIELD_CALLBACKS, name)
            continue
        for kind, field, if_valid in method_callbacks:
            fields_cbs = callbacks.setdefault(field, {})
            if kind in fields_cbs and (not is_from_parent(cls, fields_cbs[kind][0].__name__)):
                _logger.warning("Redefining the callback %s in '%s'. Previous callback : '%s' (%s). New callback : %s", kind, name, fields_cbs[kind][0].__name__, fields_cbs[kind][0], func)
            fields_cbs[kind] = (func, if_valid)
    context.field_callbacks.clear()
    context.field_callbacks.update(callbacks)

def _ipopo_class_field_property(name, value, methods_prefix):
    """Sets up an iPOPO field property, using Python property() capabilities

    :param name: The property name
    :param value: The property default value
    :param methods_prefix: The common prefix of the getter and setter injected
                           methods
    :return: A generated Python property()"""
    lock = threading.RLock()
    getter_name = '{0}{1}'.format(methods_prefix, constants.IPOPO_GETTER_SUFFIX)
    setter_name = '{0}{1}'.format(methods_prefix, constants.IPOPO_SETTER_SUFFIX)
    local_holder = Holder(value)
    def get_value(self):
        """Retrieves the property value, from the iPOPO dictionaries"""
        getter = getattr(self, getter_name, None)
        if getter is not None:
            with lock:
                return getter(self, name)
        else:
            return local_holder.value
    def set_value(self, new_value):
        """Sets the property value and trigger an update event

        :param new_value: The new property value"""
        setter = getattr(self, setter_name, None)
        if setter is not None:
            with lock:
                setter(self, name, new_value)
        else:
            local_holder.value = new_value
    return property(get_value, set_value)

def _get_specifications(specifications):
    """Computes the list of strings corresponding to the given specifications

    :param specifications: A string, a class or a list of specifications
    :return: A list of strings
    :raise ValueError: Invalid specification found"""
    if not specifications or specifications is object:
        raise ValueError('No specifications given')
    elif inspect.isclass(specifications):
        if Provides.USE_MODULE_QUALNAME:
            if sys.version_info < (3, 3, 0):
                raise ValueError('Qualified name capability requires Python 3.3+')
            if not specifications.__module__:
                return [specifications.__qualname__]
            return ['{0}.{1}'.format(specifications.__module__, specifications.__qualname__)]
        else:
            return [specifications.__name__]
    elif is_string(specifications):
        specifications = specifications.strip()
        if not specifications:
            raise ValueError('Empty specification given')
        return [specifications]
    elif isinstance(specifications, (list, tuple)):
        results = []
        for specification in specifications:
            results.extend(_get_specifications(specification))
        return results
    else:
        raise ValueError('Unhandled specifications type : {0}'.format(type(specifications).__name__))

def _parse_boolean(value):
    """Returns a boolean value corresponding to the given value.

    :param value: Any value
    :return: Its boolean value"""
    if not value:
        return False
    try:
        value = value.lower()
        return value not in ('none', '0', 'false', 'no')
    except AttributeError:
        return True

def sanitize_html(value, valid_tags=VALID_TAGS, strip=True):
    """Strips unwanted markup out of HTML."""
    return bleach.clean(value, tags=list(VALID_TAGS.keys()), attributes=VALID_TAGS, strip=strip)

def word_count(text, html=True):
    """Return the count of words in the given text. If the text is HTML (default True),
    tags are stripped before counting. Handles punctuation and bad formatting like.this
    when counting words, but assumes conventions for Latin script languages. May not
    be reliable for other languages."""
    if html:
        text = _tag_re.sub(' ', text)
    text = _strip_re.sub('', text)
    text = _punctuation_re.sub(' ', text)
    return len(text.split())

def simplify_text(text):
    """Simplify text to allow comparison.

    >>> simplify_text("Awesome Coder wanted at Awesome Company")
    'awesome coder wanted at awesome company'
    >>> simplify_text("Awesome Coder, wanted  at Awesome Company! ")
    'awesome coder wanted at awesome company'
    >>> simplify_text(u"Awesome Coder, wanted  at Awesome Company! ") == 'awesome coder wanted at awesome company'
    True"""
    if isinstance(text, six.text_type):
        if six.PY3:
            text = text.translate(text.maketrans('', '', string.punctuation)).lower()
        else:
            text = six.text_type(text.encode('utf-8').translate(string.maketrans('', ''), string.punctuation).lower(), 'utf-8')
    else:
        text = text.translate(string.maketrans('', ''), string.punctuation).lower()
    return ' '.join(text.split())

def extract_named_entities(text_blocks):
    """Return a list of named entities extracted from provided text blocks (list of text strings)."""
    sentences = []
    for text in text_blocks:
        sentences.extend(nltk.sent_tokenize(text))
    tokenized_sentences = [nltk.word_tokenize(sentence) for sentence in sentences]
    tagged_sentences = [nltk.pos_tag(sentence) for sentence in tokenized_sentences]
    chunked_sentences = nltk.ne_chunk_sents(tagged_sentences, binary=True)
    def extract_entity_names(t):
        entity_names = []
        if hasattr(t, 'label'):
            if t.label() == 'NE':
                entity_names.append(' '.join([child[0] for child in t]))
            else:
                for child in t:
                    entity_names.extend(extract_entity_names(child))
        return entity_names
    entity_names = []
    for tree in chunked_sentences:
        entity_names.extend(extract_entity_names(tree))
    return set(entity_names)

def sync_resources():
    """Sync the client's resources with the Lastuser server"""
    print('Syncing resources with Lastuser...')
    resources = manager.app.lastuser.sync_resources()['results']
    for rname, resource in six.iteritems(resources):
        if resource['status'] == 'error':
            print('Error for %s: %s' % (rname, resource['error']))
        else:
            print('Resource %s %s...' % (rname, resource['status']))
            for aname, action in six.iteritems(resource['actions']):
                if action['status'] == 'error':
                    print('\tError for %s/%s: %s' % (rname, aname, action['error']))
                else:
                    print('\tAction %s/%s %s...' % (rname, aname, resource['status']))
    print('Resources synced...')

def load_config_from_file(app, filepath):
    """Helper function to load config from a specified file"""
    try:
        app.config.from_pyfile(filepath)
        return True
    except IOError:
        print('Did not find settings file %s for additional settings, skipping it' % filepath, file=sys.stderr)
