    """Create a getter function for retrieving values from the config cache.
    Getters will default to the DEFAULT namespace."""
    def proxy_register(key_name, default=UndefToken, help=None, namespace=None):
        name = namespace or getter_namespace or config.DEFAULT
        namespace = config.get_namespace(name)
        return proxy_factory.build(validator, namespace, key_name, default, help)
    return proxy_register

def alphanum_order(triples):
    """Sort a list of triples by relation name.

    Embedded integers are sorted numerically, but otherwise the sorting
    is alphabetic."""
    return sorted(triples, key=lambda t: [int(t) if t.isdigit() else t for t in re.split('([0-9]+)', t.relation or '')])

def load(source, triples=False, cls=PENMANCodec, **kwargs):
    """Deserialize a list of PENMAN-encoded graphs from *source*.

    Args:
        source: a filename or file-like object to read from
        triples: if True, read graphs as triples instead of as PENMAN
        cls: serialization codec class
        kwargs: keyword arguments passed to the constructor of *cls*
    Returns:
        a list of Graph objects"""
    decode = cls(**kwargs).iterdecode
    if hasattr(source, 'read'):
        return list(decode(source.read()))
    else:
        with open(source) as fh:
            return list(decode(fh.read()))

def query_cast(value, answers, ignorecase=False):
    """A cast function for query

    Answers should look something like it does in query"""
    if ignorecase:
        value = value.lower()
    for item in answers:
        for a in item['values']:
            if ignorecase and value == str(a).lower():
                return item['values'][0]
            elif value == a:
                return item['values'][0]
    raise ValueError("Response '%s' not understood, please try again." % value)

def file_chooser(prompt_text='Enter File: ', default=None, filearg=[], filekwarg={}):
    """A simple tool to get a file from the user. Takes keyworded arguemnts
    and passes them to open().

    If the user enters nothing the function will return the ``default`` value.
    Otherwise it continues to prompt the user until it get's a decent response.

    filekwarg may contain arguements passed on to ``open()``."""
    try:
        import readline, rlcomplete
        completer = rlcomplete.PathCompleter()
        readline.set_completer_delims(completer.delims)
        readline.parse_and_bind('tab: complete')
        readline.set_completer(completer.complete)
    except ImportError:
        pass
    while True:
        f = raw_input(prompt_text)
        if f == '':
            return default
        f = os.path.expanduser(f)
        if len(f) != 0 and f[0] == os.path.sep:
            f = os.path.abspath(f)
        try:
            return open(f, *filearg, **filekwarg)
        except IOError as e:
            stderr.write(ERROR_MESSAGE % ('unable to open %s : %s' % (f, e)))

def file(value, **kwarg):
    """value should be a path to file in the filesystem.

    returns a file object"""
    try:
        f = open(value, **kwarg)
    except IOError as e:
        raise ValueError('unable to open %s : %s' % (path.abspath(value), e))
    return f

def xterm_to_rgb(xcolor):
    """Convert xterm Color ID to an RGB value

    All 256 values are precalculated and stored in :data:`COLOR_TABLE`"""
    assert 0 <= xcolor <= 255
    if xcolor < 16:
        return BASIC16[xcolor]
    elif 16 <= xcolor <= 231:
        xcolor -= 16
        return (CUBE_STEPS[xcolor // 36 % 6], CUBE_STEPS[xcolor // 6 % 6], CUBE_STEPS[xcolor % 6])
    elif 232 <= xcolor <= 255:
        c = 8 + (xcolor - 232) * 10
        return (c, c, c)

