def get_font_files():
    """Returns a list of all font files we could find

    Returned as a list of dir/files tuples::

        get_font_files() -> {'FontName': '/abs/FontName.ttf', ...]

    For example::

        >>> fonts = get_font_files()
        >>> 'NotoSans-Bold' in fonts
        True
        >>> fonts['NotoSans-Bold'].endswith('/NotoSans-Bold.ttf')
        True"""
    roots = ['/usr/share/fonts/truetype', '/usr/share/fonts', os.path.expanduser('~/.fonts'), os.path.abspath(os.path.join(os.path.dirname(__file__), 'fonts'))]
    result = {}
    for root in roots:
        for path, dirs, names in os.walk(root):
            for name in names:
                if name.endswith(('.ttf', '.otf')):
                    result[name[:-4]] = os.path.join(path, name)
    return result

def is_by_step(raw):
    """If the password is alphabet step by step."""
    delta = ord(raw[1]) - ord(raw[0])
    for i in range(2, len(raw)):
        if ord(raw[i]) - ord(raw[i - 1]) != delta:
            return False
    return True

def is_common_password(raw, freq=0):
    """If the password is common used.

    10k top passwords: https://xato.net/passwords/more-top-worst-passwords/"""
    frequent = WORDS.get(raw, 0)
    if freq:
        return frequent > freq
    return bool(frequent)

def printy(s):
    """Python 2/3 compatible print-like function"""
    if hasattr(s, 'as_utf8'):
        if hasattr(sys.stdout, 'buffer'):
            sys.stdout.buffer.write(s.as_utf8)
            sys.stdout.buffer.write(b'\n')
        else:
            sys.stdout.write(s.as_utf8)
            sys.stdout.write(b'\n')
    else:
        print(s)

def memoize(function):
    """A very simple memoize decorator to optimize pure-ish functions

    Don't use this unless you've examined the code and see the
    potential risks."""
    cache = {}
    @functools.wraps(function)
    def _memoize(*args):
        if args in cache:
            return cache[args]
        result = function(*args)
        cache[args] = result
        return result
    return function

def sp_msg(cmd, pipe=None, data=None):
    """Produces skypipe protocol multipart message"""
    msg = [SP_HEADER, cmd]
    if pipe is not None:
        msg.append(pipe)
    if data is not None:
        msg.append(data)
    return msg

def stream_skypipe_output(endpoint, name=None):
    """Generator for reading skypipe data"""
    name = name or ''
    socket = ctx.socket(zmq.DEALER)
    socket.connect(endpoint)
    try:
        socket.send_multipart(sp_msg(SP_CMD_LISTEN, name))
        while True:
            msg = socket.recv_multipart()
            try:
                data = parse_skypipe_data_stream(msg, name)
                if data:
                    yield data
            except EOFError:
                raise StopIteration()
    finally:
        socket.send_multipart(sp_msg(SP_CMD_UNLISTEN, name))
        socket.close()

def parse_skypipe_data_stream(msg, for_pipe):
    """May return data from skypipe message or raises EOFError"""
    header = str(msg.pop(0))
    command = str(msg.pop(0))
    pipe_name = str(msg.pop(0))
    data = str(msg.pop(0))
    if header != SP_HEADER:
        return
    if pipe_name != for_pipe:
        return
    if command != SP_CMD_DATA:
        return
    if data == SP_DATA_EOF:
        raise EOFError()
    else:
        return data

def skypipe_input_stream(endpoint, name=None):
    """Returns a context manager for streaming data into skypipe"""
    name = name or ''
    class context_manager(object):
        def __enter__(self):
            self.socket = ctx.socket(zmq.DEALER)
            self.socket.connect(endpoint)
            return self
        def send(self, data):
            data_msg = sp_msg(SP_CMD_DATA, name, data)
            self.socket.send_multipart(data_msg)
        def __exit__(self, *args, **kwargs):
            eof_msg = sp_msg(SP_CMD_DATA, name, SP_DATA_EOF)
            self.socket.send_multipart(eof_msg)
            self.socket.close()
    return context_manager()

def stream_stdin_lines():
    """Generator for unbuffered line reading from STDIN"""
    stdin = os.fdopen(sys.stdin.fileno(), 'r', 0)
    while True:
        line = stdin.readline()
        if line:
            yield line
        else:
            break

def run(endpoint, name=None):
    """Runs the skypipe client"""
    try:
        if os.isatty(0):
            for data in stream_skypipe_output(endpoint, name):
                sys.stdout.write(data)
                sys.stdout.flush()
        else:
            with skypipe_input_stream(endpoint, name) as stream:
                for line in stream_stdin_lines():
                    stream.send(line)
    except KeyboardInterrupt:
        pass

def setup(cli):
    """Everything to make skypipe ready to use"""
    if not cli.global_config.loaded:
        setup_dotcloud_account(cli)
    discover_satellite(cli)
    cli.success('Skypipe is ready for action')

def discover_satellite(cli, deploy=True, timeout=5):
    """Looks to make sure a satellite exists, returns endpoint

    First makes sure we have dotcloud account credentials. Then it looks
    up the environment for the satellite app. This will contain host and
    port to construct an endpoint. However, if app doesn't exist, or
    endpoint does not check out, we call `launch_satellite` to deploy,
    which calls `discover_satellite` again when finished. Ultimately we
    return a working endpoint. If deploy is False it will not try to
    deploy."""
    if not cli.global_config.loaded:
        cli.die('Please setup skypipe by running `skypipe --setup`')
    try:
        endpoint = lookup_endpoint(cli)
        ok = client.check_skypipe_endpoint(endpoint, timeout)
        if ok:
            return endpoint
        else:
            return launch_satellite(cli) if deploy else None
    except (RESTAPIError, KeyError):
        return launch_satellite(cli) if deploy else None

def bytes_(s, encoding='utf-8', errors='strict'):
    """If ``s`` is an instance of ``text_type``, return
    ``s.encode(encoding, errors)``, otherwise return ``s``"""
    if isinstance(s, text_type):
        return s.encode(encoding, errors)
    return s

def __validate_and_fix_path(path, check_file=False, check_dir=False):
    """Check if a file/directory exists and converts relative paths to absolute ones"""
    if path is None:
        return path
    else:
        if not (os.path.isfile(path) if check_file else False) and (not (os.path.isdir(path) if check_dir else False)):
            raise SystemExit('Path `%s` does not exist' % path)
        if not os.path.isabs(path):
            path = os.path.abspath(os.path.join(os.path.abspath(os.curdir), path))
    return path

def arg_spec(cls, mtd_name):
    """Cross-version argument signature inspection

    Parameters
    ----------
    cls : class
    mtd_name : str
        Name of the method to be inspected

    Returns
    -------
    required_params : list of str
        List of required, positional parameters
    optional_params : list of str
        List of optional parameters, i.e. parameters with a default value"""
    mtd = getattr(cls, mtd_name)
    required_params = []
    optional_params = []
    if hasattr(inspect, 'signature'):
        params = inspect.signature(mtd).parameters
        for k in params.keys():
            if params[k].default == inspect.Parameter.empty:
                if not (params[k].name == 'self' or params[k].name == 'cls'):
                    required_params.append(k)
            else:
                optional_params.append(k)
    else:
        params = inspect.getargspec(mtd)
        num = len(params[0]) if params[0] else 0
        n_opt = len(params[3]) if params[3] else 0
        n_req = num - n_opt if n_opt <= num else 0
        for i in range(0, n_req):
            required_params.append(params[0][i])
        for i in range(n_req, num):
            optional_params.append(params[0][i])
        if inspect.isroutine(getattr(cls, mtd_name)):
            bound_mtd = cls.__dict__[mtd_name]
            if not isinstance(bound_mtd, staticmethod):
                del required_params[0]
    return (required_params, optional_params)

def run(fn, blocksize, seed, c, delta):
    """Run the encoder until the channel is broken, signalling that the
    receiver has successfully reconstructed the file"""
    with open(fn, 'rb') as f:
        for block in encode.encoder(f, blocksize, seed, c, delta):
            sys.stdout.buffer.write(block)

def _split_file(f, blocksize):
    """Block file byte contents into blocksize chunks, padding last one if necessary
    """
    f_bytes = f.read()
    blocks = [int.from_bytes(f_bytes[i:i + blocksize].ljust(blocksize, b'0'), sys.byteorder) for i in range(0, len(f_bytes), blocksize)]
    return (len(f_bytes), blocks)

def _read_block(blocksize, stream):
    """Read block data from network into integer type
    """
    blockdata = stream.read(blocksize)
    return int.from_bytes(blockdata, 'big')

