    def func(self, filename, seq_label='sequence', alphabet=None, combine_on='uid', use_uids=True, **kwargs):
        df0 = self._data
        df1 = _read(filename=filename, schema=schema, seq_label=seq_label, alphabet=alphabet, use_uids=use_uids, **kwargs)
