def parse_delay(data):
    """Prase the delay"""
    rsp = requests.get(data['details'])
    soup = BeautifulSoup(rsp.text, 'html.parser')
    delay_departure_raw = soup.find('div', class_='routeStart').find('span', class_=['delay', 'delayOnTime'])
    if delay_departure_raw:
        delay_departure = calculate_delay(data['departure'], delay_departure_raw.text)
    else:
        delay_departure = 0
    delay_arrival_raw = soup.find('div', class_=['routeEnd', 'routeEndAdditional']).find('span', class_=['delay', 'delayOnTime'])
    if delay_arrival_raw:
        delay_arrival = calculate_delay(data['arrival'], delay_arrival_raw.text)
    else:
        delay_arrival = 0
    if delay_departure + delay_arrival == 0:
        data['ontime'] = True
    else:
        data['ontime'] = False
    data['delay'] = {'delay_departure': int(delay_departure), 'delay_arrival': int(delay_arrival)}
    data['canceled'] = False
    return data

def _handle_zeros_in_scale(scale, copy=True):
    """Makes sure that whenever scale is zero, we handle it correctly.
    This happens in most scalers when we have constant features."""
    if numpy.isscalar(scale):
        if scale == 0.0:
            scale = 1.0
        return scale
    elif isinstance(scale, numpy.ndarray):
        if copy:
            scale = scale.copy()
        scale[scale == 0.0] = 1.0
        return scale

def _recurse_replace(obj, key, new_key, sub, remove):
    """Recursive helper for `replace_by_key`"""
    if isinstance(obj, list):
        return [_recurse_replace(x, key, new_key, sub, remove) for x in obj]
    if isinstance(obj, dict):
        for k, v in list(obj.items()):
            if k == key and v in sub:
                obj[new_key] = sub[v]
                if remove:
                    del obj[key]
            else:
                obj[k] = _recurse_replace(v, key, new_key, sub, remove)
    return obj

