def ok_did(token: str) -> bool:
    """Whether input token looks like a valid distributed identifier.

    :param token: candidate string
    :return: whether input token looks like a valid schema identifier"""
    return bool(re.match('[{}]{{21,22}}$'.format(B58), token or ''))

def ok_schema_id(token: str) -> bool:
    """Whether input token looks like a valid schema identifier;
    i.e., <issuer-did>:2:<name>:<version>.

    :param token: candidate string
    :return: whether input token looks like a valid schema identifier"""
    return bool(re.match('[{}]{{21,22}}:2:.+:[0-9.]+$'.format(B58), token or ''))

def cred_def_id2seq_no(cd_id: str) -> int:
    """Given a credential definition identifier, return its schema sequence number.
    Raise BadIdentifier on input that is not a credential definition identifier.

    :param cd_id: credential definition identifier
    :return: sequence number"""
    if ok_cred_def_id(cd_id):
        return int(cd_id.split(':')[3])
    raise BadIdentifier('Bad credential definition identifier {}'.format(cd_id))

def rev_reg_id2cred_def_id(rr_id: str) -> str:
    """Given a revocation registry identifier, return its corresponding credential definition identifier.
    Raise BadIdentifier if input is not a revocation registry identifier.

    :param rr_id: revocation registry identifier
    :return: credential definition identifier"""
    if ok_rev_reg_id(rr_id):
        return ':'.join(rr_id.split(':')[2:-2])
    raise BadIdentifier('Bad revocation registry identifier {}'.format(rr_id))

def iter_briefs(briefs: Union[dict, Sequence[dict]]) -> tuple:
    """Given a cred-brief/cred-info, an sequence thereof, or cred-brief-dict
    (as HolderProver.get_cred_briefs_by_proof_req_q() returns), return tuple with
    all contained cred-briefs.

    :param briefs: cred-brief/cred-info, sequence thereof, or cred-brief-dict
    :return: tuple of cred-briefs"""
    if isinstance(briefs, dict):
        if all((ok_wallet_reft(k) for k in briefs)):
            return tuple(briefs.values())
        return (briefs,)
    return tuple(briefs)

def prune_creds_json(creds: dict, cred_ids: set) -> str:
    """Strip all creds out of the input json structure that do not match any of the input credential identifiers.

    :param creds: indy-sdk creds structure
    :param cred_ids: the set of credential identifiers of interest
    :return: the reduced creds json"""
    rv = deepcopy(creds)
    for key in ('attrs', 'predicates'):
        for attr_uuid, creds_by_uuid in rv[key].items():
            rv[key][attr_uuid] = [cred for cred in creds_by_uuid if cred['cred_info']['referent'] in cred_ids]
        empties = [attr_uuid for attr_uuid in rv[key] if not rv[key][attr_uuid]]
        for attr_uuid in empties:
            del rv[key][attr_uuid]
    return json.dumps(rv)

def proof_req2wql_all(proof_req: dict, x_cd_ids: Union[str, Sequence[str]]=None) -> dict:
    """Given a proof request and a list of cred def ids to omit, return an extra WQL query dict
    that will find all corresponding credentials in search.

    The proof request must have cred def id restrictions on all requested attribute specifications.
    At present, the utility does not support predicates.

    :param proof_req: proof request
    :param x_cd_ids: cred def identifier or sequence thereof to omit
    :return: extra WQL dict to fetch all corresponding credentials in search."""
    rv = {}
    attr_refts = proof_req_attr_referents(proof_req)
    for cd_id in [k for k in attr_refts if k not in ([x_cd_ids] if isinstance(x_cd_ids, str) else x_cd_ids or [])]:
        rv[set(attr_refts[cd_id].values()).pop()] = {'cred_def_id': cd_id}
    return rv

def revealed_attrs(proof: dict) -> dict:
    """Fetch revealed attributes from input proof and return dict mapping credential definition identifiers
    to dicts, each dict mapping attribute names to (raw) values, for processing in further creds downstream.

    :param proof: indy-sdk proof as dict
    :return: dict mapping cred-ids to dicts, each mapping revealed attribute names to (raw) values"""
    rv = {}
    for sub_index in range(len(proof['identifiers'])):
        cd_id = proof['identifiers'][sub_index]['cred_def_id']
        rv[cd_id] = {'_'.join(uuid.split('_')[1:-1]): proof['requested_proof']['revealed_attrs'][uuid]['raw'] for uuid in proof['requested_proof']['revealed_attrs'] if proof['requested_proof']['revealed_attrs'][uuid]['sub_proof_index'] == sub_index}
    return rv

def do_ultracache(parser, token):
    """Based on Django's default cache template tag"""
    nodelist = parser.parse(('endultracache',))
    parser.delete_first_token()
    tokens = token.split_contents()
    if len(tokens) < 3:
        raise TemplateSyntaxError('' % ' tag requires at least 2 arguments.' % tokens[0])
    return UltraCacheNode(nodelist, parser.compile_filter(tokens[1]), tokens[2], [parser.compile_filter(token) for token in tokens[3:]])

def ppjson(dumpit: Any, elide_to: int=None) -> str:
    """JSON pretty printer, whether already json-encoded or not

    :param dumpit: object to pretty-print
    :param elide_to: optional maximum length including ellipses ('...')
    :return: json pretty-print"""
    if elide_to is not None:
        elide_to = max(elide_to, 3)
    try:
        rv = json.dumps(json.loads(dumpit) if isinstance(dumpit, str) else dumpit, indent=4)
    except TypeError:
        rv = '{}'.format(pformat(dumpit, indent=4, width=120))
    return rv if elide_to is None or len(rv) <= elide_to else '{}...'.format(rv[0:elide_to - 3])

def do_wait(coro: Callable) -> Any:
    """Perform aynchronous operation; await then return the result.

    :param coro: coroutine to await
    :return: coroutine result"""
    event_loop = None
    try:
        event_loop = asyncio.get_event_loop()
    except RuntimeError:
        event_loop = asyncio.new_event_loop()
        asyncio.set_event_loop(event_loop)
    return event_loop.run_until_complete(coro)

def inis2dict(ini_paths: Union[str, Sequence[str]]) -> dict:
    """Take one or more ini files and return a dict with configuration from all,
    interpolating bash-style variables ${VAR} or ${VAR:-DEFAULT}.

    :param ini_paths: path or paths to .ini files"""
    var_dflt = '\\${(.*?):-(.*?)}'
    def _interpolate(content):
        rv = expandvars(content)
        while True:
            match = re.search(var_dflt, rv)
            if match is None:
                break
            bash_var = '${{{}}}'.format(match.group(1))
            value = expandvars(bash_var)
            rv = re.sub(var_dflt, match.group(2) if value == bash_var else value, rv, count=1)
        return rv
    parser = ConfigParser()
    for ini in [ini_paths] if isinstance(ini_paths, str) else ini_paths:
        if not isfile(ini):
            raise FileNotFoundError('No such file: {}'.format(ini))
        with open(ini, 'r') as ini_fh:
            ini_text = _interpolate(ini_fh.read())
            parser.read_string(ini_text)
    return {s: dict(parser[s].items()) for s in parser.sections()}

def storage_record2pairwise_info(storec: StorageRecord) -> PairwiseInfo:
    """Given indy-sdk non_secrets implementation of pairwise storage record dict, return corresponding PairwiseInfo.

    :param storec: (non-secret) storage record to convert to PairwiseInfo
    :return: PairwiseInfo on record DIDs, verkeys, metadata"""
    return PairwiseInfo(storec.id, storec.value, storec.tags['~my_did'], storec.tags['~my_verkey'], {tag[tag.startswith('~'):]: storec.tags[tag] for tag in storec.tags or {}})

def on_post_delete(sender, **kwargs):
    """Expire ultracache cache keys affected by this object
    """
    if not invalidate:
        return
    if kwargs.get('raw', False):
        return
    if sender is MigrationRecorder.Migration:
        return
    if issubclass(sender, Model):
        obj = kwargs['instance']
        if isinstance(obj, Model):
            try:
                ct = ContentType.objects.get_for_model(sender)
            except RuntimeError:
                return
            key = 'ucache-%s-%s' % (ct.id, obj.pk)
            to_delete = cache.get(key, [])
            if to_delete:
                try:
                    cache.delete_many(to_delete)
                except NotImplementedError:
                    for k in to_delete:
                        cache.delete(k)
            cache.delete(key)
            key = 'ucache-pth-%s-%s' % (ct.id, obj.pk)
            if purger is not None:
                for li in cache.get(key, []):
                    purger(li[0], li[1])
            cache.delete(key)

def canon_cred_wql(query: dict) -> dict:
    """Canonicalize WQL attribute marker and value keys for input to indy-sdk wallet credential filtration.
    Canonicalize comparison values to proper indy-sdk raw values as per raw().

    Raise BadWalletQuery for WQL mapping '$or' to non-list.

    :param query: WQL query
    :return: canonicalized WQL query dict"""
    for k in [qk for qk in query]:
        attr_match = re.match('attr::([^:]+)::(marker|value)$', k)
        if isinstance(query[k], dict):
            query[k] = canon_cred_wql(query[k])
        if k == '$or':
            if not isinstance(query[k], list):
                raise BadWalletQuery('Bad WQL; $or value must be a list in {}'.format(json.dumps(query)))
            query[k] = [canon_cred_wql(subq) for subq in query[k]]
        if attr_match:
            qkey = 'attr::{}::{}'.format(canon(attr_match.group(1)), canon(attr_match.group(2)))
            query[qkey] = query.pop(k)
            tag_value = query[qkey]
            if isinstance(tag_value, dict) and len(tag_value) == 1:
                if '$in' in tag_value:
                    tag_value['$in'] = [raw(val) for val in tag_value.pop('$in')]
                else:
                    wql_op = set(tag_value.keys()).pop()
                    tag_value[wql_op] = raw(tag_value[wql_op])
            else:
                query[qkey] = raw(query[qkey])
    return query

def parse_requirements(filename):
    """Load requirements from a pip requirements file.

    :param filename: file name with requirements to parse"""
    try:
        with open(filename) as fh_req:
            return [line.strip() for line in fh_req if line.strip() and (not line.startswith('#'))]
    except FileNotFoundError:
        print('File not found: {}'.format(realpath(filename)), file=stderr)
        raise

def ultracache(timeout, *params):
    """Decorator applied to a view class. The get method is decorated
    implicitly."""
    def decorator(cls):
        class WrappedClass(cls):
            def __init__(self, *args, **kwargs):
                super(WrappedClass, self).__init__(*args, **kwargs)
            @cached_get(timeout, *params)
            def get(self, *args, **kwargs):
                return super(WrappedClass, self).get(*args, **kwargs)
        return WrappedClass
    return decorator

def canon_did(uri: str) -> str:
    """Convert a URI into a DID if need be, left-stripping 'did:sov:' if present.
    Return input if already a DID. Raise BadIdentifier for invalid input.

    :param uri: input URI or DID
    :return: corresponding DID"""
    if ok_did(uri):
        return uri
    if uri.startswith('did:sov:'):
        rv = uri[8:]
        if ok_did(rv):
            return rv
    raise BadIdentifier('Bad specification {} does not correspond to a sovrin DID'.format(uri))

def canon_ref(did: str, ref: str, delimiter: str=None):
    """Given a reference in a DID document, return it in its canonical form of a URI.

    :param did: DID acting as the identifier of the DID document
    :param ref: reference to canonicalize, either a DID or a fragment pointing to a location in the DID doc
    :param delimiter: delimiter character marking fragment (default '#') or
        introducing identifier (';') against DID resource"""
    if not ok_did(did):
        raise BadIdentifier('Bad DID {} cannot act as DID document identifier'.format(did))
    if ok_did(ref):
        return 'did:sov:{}'.format(did)
    if ok_did(resource(ref, delimiter)):
        return 'did:sov:{}'.format(ref)
    if ref.startswith('did:sov:'):
        rv = ref[8:]
        if ok_did(resource(rv, delimiter)):
            return ref
        raise BadIdentifier('Bad URI {} does not correspond to a sovrin DID'.format(ref))
    if urlparse(ref).scheme:
        return ref
    return 'did:sov:{}{}{}'.format(did, delimiter if delimiter else '#', ref)

def _get_pwned(prefix):
    """Fetches a dict of all hash suffixes from Pwned Passwords for a
    given SHA-1 prefix."""
    try:
        response = requests.get(url=API_ENDPOINT.format(prefix), headers={'User-Agent': USER_AGENT}, timeout=getattr(settings, 'PWNED_PASSWORDS_API_TIMEOUT', REQUEST_TIMEOUT))
        response.raise_for_status()
    except requests.RequestException as e:
        log.warning('Skipped Pwned Passwords check due to error: %r', e)
        return None
    results = {}
    for line in response.text.splitlines():
        line_suffix, _, times = line.partition(':')
        results[line_suffix] = int(times)
    return results

def pwned_password(password):
    """Checks a password against the Pwned Passwords database."""
    if not isinstance(password, text_type):
        raise TypeError('Password values to check must be Unicode strings.')
    password_hash = hashlib.sha1(password.encode('utf-8')).hexdigest().upper()
    prefix, suffix = (password_hash[:5], password_hash[5:])
    results = _get_pwned(prefix)
    if results is None:
        return None
    return results.get(suffix, 0)

def _split_into_mimetype_and_priority(x):
    """Split an accept header item into mimetype and priority.

    >>> _split_into_mimetype_and_priority('text/*')
    ('text/*', 1.0)

    >>> _split_into_mimetype_and_priority('application/json;q=0.5')
    ('application/json', 0.5)"""
    if ';' in x:
        content_type, priority = x.split(';')
        casted_priority = float(priority.split('=')[1])
    else:
        content_type, casted_priority = (x, 1.0)
    content_type = content_type.lstrip().rstrip()
    return (content_type, casted_priority)

def _parse_and_sort_accept_header(accept_header):
    """Parse and sort the accept header items.

    >>> _parse_and_sort_accept_header('application/json;q=0.5, text/*')
    [('text/*', 1.0), ('application/json', 0.5)]"""
    return sorted([_split_into_mimetype_and_priority(x) for x in accept_header.split(',')], key=lambda x: x[1], reverse=True)

def match_url_vars_type(url_vars, type_hints):
    """Match types of url vars.

    >>> match_url_vars_type({'user_id': '1'}, {'user_id': int})
    (True, {'user_id': 1})
    >>> match_url_vars_type({'user_id': 'foo'}, {'user_id': int})
    (False, {})"""
    typed_url_vars = {}
    try:
        for k, v in url_vars.items():
            arg_type = type_hints.get(k)
            if arg_type and arg_type != str:
                typed_url_vars[k] = arg_type(v)
            else:
                typed_url_vars[k] = v
    except ValueError:
        return (False, {})
    return (True, typed_url_vars)

def match_path(rule, path):
    """Match path.

    >>> match_path('/foo', '/foo')
    (True, {})
    >>> match_path('/foo', '/bar')
    (False, {})
    >>> match_path('/users/{user_id}', '/users/1')
    (True, {'user_id': '1'})
    >>> match_path('/users/{user_id}', '/users/not-integer')
    (True, {'user_id': 'not-integer'})"""
    split_rule = split_by_slash(rule)
    split_path = split_by_slash(path)
    url_vars = {}
    if len(split_rule) != len(split_path):
        return (False, {})
    for r, p in zip(split_rule, split_path):
        if r.startswith('{') and r.endswith('}'):
            url_vars[r[1:-1]] = p
            continue
        if r != p:
            return (False, {})
    return (True, url_vars)

def synchronized(fn):
    """A decorator which acquires a lock before attempting to execute its wrapped
    function. Releases the lock in a finally clause.

    :param fn: The function to wrap."""
    lock = threading.Lock()
    @functools.wraps(fn)
    def decorated(*args, **kwargs):
        lock.acquire()
        try:
            return fn(*args, **kwargs)
        finally:
            lock.release()
    return decorated

def generate(number=4, choice=SystemRandom().choice, words=words, joiner=' '):
    """Generate a random passphrase from the GSL."""
    return joiner.join((choice(words) for each in range(number)))

def how_long(length=4, choices=len(words), speed=1000 * 1000 * 1000 * 1000, optimism=2):
    """How long might it take to guess a password?

    @param length: the number of words that we're going to choose.
    @type length: L{int}

    @param choice: the number of words we might choose between.
    @type choice: L{int}

    @param speed: the speed of our hypothetical password guesser, in guesses
        per second.
    @type speed: L{int}

    @param optimism: When we start guessing all the options, we probably won't
        have to guess I{all} of them to get a hit.  This assumes that the
        guesser will have to guess only C{1/optimism} of the total number of
        possible options before it finds a hit."""
    return choices ** length / (speed * optimism)

def redivmod(initial_value, factors):
    """Chop up C{initial_value} according to the list of C{factors} and return a
    formatted string."""
    result = []
    value = initial_value
    for divisor, label in factors:
        if not divisor:
            remainder = value
            if not remainder:
                break
        else:
            value, remainder = divmod(value, divisor)
            if not value and (not remainder):
                break
        if remainder == 1:
            label = label[:-1]
        if six.PY2:
            addition = unicode(remainder) + ' ' + unicode(label)
        else:
            addition = str(remainder) + ' ' + str(label)
        result.insert(0, addition)
    if len(result) > 1:
        result[-1] = 'and ' + result[-1]
    if result:
        return ', '.join(result)
    else:
        return 'instantly'

def debug(sequence):
    """adds information to the sequence for better debugging, currently only
    an index property on each point in the sequence."""
    points = []
    for i, p in enumerate(sequence):
        copy = Point(p)
        copy['index'] = i
        points.append(copy)
    return sequence.__class__(points)

def transform_sequence(f):
    """A decorator to take a function operating on a point and
    turn it into a function returning a callable operating on a sequence.
    The functions passed to this decorator must define a kwarg called "point",
    or have point be the last positional argument"""
    @wraps(f)
    def wrapper(*args, **kwargs):
        return lambda seq: seq.map_points(partial(f, *args, **kwargs))
    return wrapper

def subseq(start_offset=0, end_offset=None):
    """Return a portion of the input sequence"""
    def _(sequence):
        return sequence.subseq(start_offset, end_offset)
    return _

def query_revisions_by_revids(session, revids, **params):
    """Gets a set of revisions by their IDs by repeatedly querying in batches.
    If an ID cannot be found, it is ignored."""
    doc = session.get(action='query', prop='revisions', revids=revids, **params)
    for page_doc in doc['query'].get('pages', {}).values():
        revisions = page_doc.get('revisions', [])
        if 'revisions' in page_doc:
            del page_doc['revisions']
        for revision_doc in revisions:
            revision_doc['page'] = page_doc
            yield revision_doc

def load_metafile(filepath):
    """Load a metadata file from the filesystem"""
    try:
        with open(filepath, 'r', encoding='utf-8') as file:
            return email.message_from_file(file)
    except FileNotFoundError:
        logger.warning('Category file %s not found', filepath)
        orm.delete((c for c in model.Category if c.file_path == filepath))
        orm.commit()
    return None

def scan_file(fullpath, relpath):
    """scan a file and put it into the index"""
    load_metafile.cache_clear()
    meta = load_metafile(fullpath)
    if not meta:
        return True
    category = meta.get('Category', utils.get_category(relpath))
    values = {'category': category, 'file_path': fullpath, 'sort_name': meta.get('Sort-Name', '')}
    logger.debug('setting category %s to metafile %s', category, fullpath)
    record = model.Category.get(category=category)
    if record:
        record.set(**values)
    else:
        record = model.Category(**values)
    path_alias.remove_aliases(record)
    for alias in meta.get_all('Path-Alias', []):
        path_alias.set_alias(alias, category=record)
    orm.commit()
    return record

def parse_date(datestr):
    """Parse a date expression into a tuple of:

        (start_date, span_type, span_format)

    Arguments:
        datestr -- A date specification, in the format of YYYY-MM-DD (dashes optional)"""
    match = re.match('([0-9]{4})(-?([0-9]{1,2}))?(-?([0-9]{1,2}))?(_w)?$', datestr)
    if not match:
        return (arrow.get(datestr, tzinfo=config.timezone).replace(tzinfo=config.timezone), 'day', 'YYYY-MM-DD')
    year, month, day, week = match.group(1, 3, 5, 6)
    start = arrow.Arrow(year=int(year), month=int(month or 1), day=int(day or 1), tzinfo=config.timezone)
    if week:
        return (start.span('week')[0], 'week', WEEK_FORMAT)
    if day:
        return (start, 'day', DAY_FORMAT)
    if month:
        return (start, 'month', MONTH_FORMAT)
    if year:
        return (start, 'year', YEAR_FORMAT)
    raise ValueError('Could not parse date: {}'.format(datestr))

def find_file(path, search_path):
    """Find a file by relative path. Arguments:

    path -- the image's filename
    search_path -- a list of directories to check in

    Returns: the resolved file path"""
    if isinstance(search_path, str):
        search_path = [search_path]
    for relative in search_path:
        candidate = os.path.normpath(os.path.join(relative, path))
        if os.path.isfile(candidate):
            return candidate
    return None

def find_entry(rel_path, search_path):
    """Find an entry by relative path. Arguments:

    path -- the entry's filename (or entry ID)
    search_path -- a list of directories to check in

    Returns: the resolved Entry object"""
    from . import entry
    try:
        entry_id = int(rel_path)
        record = model.Entry.get(id=entry_id)
        if record:
            return entry.Entry(record)
    except ValueError:
        pass
    if rel_path.startswith('/'):
        search_path = [config.content_folder]
        rel_path = '.' + rel_path
    for where in search_path:
        abspath = os.path.normpath(os.path.join(where, rel_path))
        record = model.Entry.get(file_path=abspath)
        if record:
            return entry.Entry(record)
    return None

def static_url(path, absolute=False):
    """Shorthand for returning a URL for the requested static file.

    Arguments:

    path -- the path to the file (relative to the static files directory)
    absolute -- whether the link should be absolute or relative"""
    if os.sep != '/':
        path = '/'.join(path.split(os.sep))
    return flask.url_for('static', filename=path, _external=absolute)

def make_tag(name, attrs, start_end=False):
    """Build an HTML tag from the given name and attributes.

    Arguments:

    name -- the name of the tag (p, div, etc.)
    attrs -- a dict of attributes to apply to the tag
    start_end -- whether this tag should be self-closing"""
    text = '<' + name
    if isinstance(attrs, dict):
        attr_list = attrs.items()
    elif isinstance(attrs, list):
        attr_list = attrs
    elif attrs is not None:
        raise TypeError('Unhandled attrs type ' + str(type(attrs)))
    for key, val in attr_list:
        if val is not None:
            escaped = html.escape(str(val), False).replace('"', '&#34;')
            text += ' {}="{}"'.format(key, escaped)
    if start_end:
        text += ' /'
    text += '>'
    return flask.Markup(text)

def file_fingerprint(fullpath):
    """Get a metadata fingerprint for a file"""
    stat = os.stat(fullpath)
    return ','.join([str(value) for value in [stat.st_ino, stat.st_mtime, stat.st_size] if value])

def remap_args(input_args, remap):
    """Generate a new argument list by remapping keys. The 'remap'
    dict maps from destination key -> priority list of source keys"""
    out_args = input_args
    for dest_key, src_keys in remap.items():
        remap_value = None
        if isinstance(src_keys, str):
            src_keys = [src_keys]
        for key in src_keys:
            if key in input_args:
                remap_value = input_args[key]
                break
        if remap_value is not None:
            if out_args is input_args:
                out_args = {**input_args}
            out_args[dest_key] = remap_value
    return out_args

def remap_link_target(path, absolute=False):
    """remap a link target to a static URL if it's prefixed with @"""
    if path.startswith('@'):
        return static_url(path[1:], absolute=absolute)
    if absolute:
        return urllib.parse.urljoin(flask.request.url, path)
    return path

def get_category(filename):
    """Get a default category name from a filename in a cross-platform manner"""
    return '/'.join(os.path.dirname(filename).split(os.sep))

def setup():
    """Set up the database"""
    try:
        db.bind(**config.database_config)
    except OSError:
        db.bind(**config.database_config, create_db=True)
    rebuild = True
    try:
        db.generate_mapping(create_tables=True)
        with orm.db_session:
            version = GlobalConfig.get(key='schema_version')
            if version and version.int_value != SCHEMA_VERSION:
                logger.info('Existing database has schema version %d', version.int_value)
            else:
                rebuild = False
    except:
        logger.exception('Error mapping schema')
    if rebuild:
        logger.info('Rebuilding schema')
        try:
            db.drop_all_tables(with_all_data=True)
            db.create_tables()
        except:
            raise RuntimeError('Unable to upgrade schema automatically; please ' + 'delete the existing database and try again.')
    with orm.db_session:
        if not GlobalConfig.get(key='schema_version'):
            logger.info('setting schema version to %d', SCHEMA_VERSION)
            GlobalConfig(key='schema_version', int_value=SCHEMA_VERSION)
            orm.commit()

def set_cache_expiry(response):
    """Set the cache control headers"""
    if response.cache_control.max_age is None and 'CACHE_DEFAULT_TIMEOUT' in config.cache:
        response.cache_control.max_age = config.cache['CACHE_DEFAULT_TIMEOUT']
    return response

def guess_title(basename):
    """Attempt to guess the title from the filename"""
    base, _ = os.path.splitext(basename)
    return re.sub('[ _-]+', ' ', base).title()

def get_entry_id(entry, fullpath, assign_id):
    """Get or generate an entry ID for an entry"""
    warn_duplicate = False
    if 'Entry-ID' in entry:
        entry_id = int(entry['Entry-ID'])
    else:
        entry_id = None
    if entry_id:
        try:
            other_entry = model.Entry.get(id=entry_id)
            if other_entry and os.path.isfile(other_entry.file_path) and (not os.path.samefile(other_entry.file_path, fullpath)):
                warn_duplicate = entry_id
                entry_id = None
        except FileNotFoundError:
            pass
    if not entry_id and (not assign_id):
        return None
    if not entry_id:
        by_filepath = model.Entry.get(file_path=fullpath)
        if by_filepath:
            entry_id = by_filepath.id
    if not entry_id:
        limit = max(10, orm.get((orm.count(e) for e in model.Entry)) * 5)
        attempt = 0
        while not entry_id or model.Entry.get(id=entry_id):
            md5 = hashlib.md5()
            md5.update('{} {}'.format(fullpath, attempt).encode('utf-8'))
            entry_id = int.from_bytes(md5.digest(), byteorder='big') % limit
            attempt = attempt + 1
    if warn_duplicate is not False:
        logger.warning("Entry '%s' had ID %d, which belongs to '%s'. Reassigned to %d", fullpath, warn_duplicate, other_entry.file_path, entry_id)
    return entry_id

def setup(cfg):
    """set up the global configuration from an object"""
    this_module = sys.modules[__name__]
    for name, value in cfg.items():
        if hasattr(this_module, name):
            setattr(this_module, name, value)

def mime_type(template):
    """infer the content-type from the extension"""
    _, ext = os.path.splitext(template.filename)
    return EXTENSION_MAP.get(ext, 'text/html; charset=utf-8')

def map_template(category, template_list):
    """Given a file path and an acceptable list of templates, return the
    best-matching template's path relative to the configured template
    directory.

    Arguments:

    category -- The path to map
    template_list -- A template to look up (as a string), or a list of templates."""
    if isinstance(template_list, str):
        template_list = [template_list]
    for template in template_list:
        path = os.path.normpath(category)
        while path is not None:
            for extension in ['', '.html', '.htm', '.xml', '.json']:
                candidate = os.path.join(path, template + extension)
                file_path = os.path.join(config.template_folder, candidate)
                if os.path.isfile(file_path):
                    return Template(template, candidate, file_path)
            parent = os.path.dirname(path)
            if parent != path:
                path = parent
            else:
                path = None

def get_template(template, relation):
    """Given an entry or a category, return the path to a related template"""
    if isinstance(relation, Entry):
        path = relation.category.path
    elif isinstance(relation, Category):
        path = relation.path
    else:
        path = relation
    tmpl = map_template(path, template)
    return tmpl.filename if tmpl else None

def image_function(template=None, entry=None, category=None):
    """Get a function that gets an image"""
    path = []
    if entry is not None:
        path += entry.search_path
    if category is not None:
        path += category.search_path
    if template is not None:
        path.append(os.path.join(config.content_folder, os.path.dirname(template.filename)))
    return lambda filename: image.get_image(filename, path)

def render_exception(error):
    """Catch-all renderer for the top-level exception handler"""
    _, _, category = str.partition(request.path, '/')
    qsize = index.queue_length()
    if isinstance(error, http_error.NotFound) and qsize:
        response = flask.make_response(render_error(category, 'Site reindex in progress (qs={})'.format(qsize), 503))
        response.headers['Retry-After'] = qsize
        response.headers['Refresh'] = max(5, qsize / 5)
        return (response, 503)
    if isinstance(error, http_error.HTTPException):
        return render_error(category, error.name, error.code, exception={'type': type(error).__name__, 'str': error.description, 'args': error.args})
    return render_error(category, 'Exception occurred', 500, exception={'type': type(error).__name__, 'str': str(error), 'args': error.args})

def render_path_alias(path):
    """Render a known path-alias (used primarily for forced .php redirects)"""
    redir = path_alias.get_redirect('/' + path)
    if not redir:
        raise http_error.NotFound('Path redirection not found')
    return redir

def render_transparent_chit():
    """Render a transparent chit for external, sized images"""
    if request.if_none_match.contains('chit') or request.if_modified_since:
        return ('Not modified', 304)
    out_bytes = base64.b64decode('R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7')
    return (out_bytes, {'Content-Type': 'image/gif', 'ETag': 'chit', 'Last-Modified': 'Tue, 31 Jul 1990 08:00:00 -0000'})

def retrieve_asset(filename):
    """Retrieves a non-image asset associated with an entry"""
    record = model.Image.get(asset_name=filename)
    if not record:
        raise http_error.NotFound('File not found')
    if not record.is_asset:
        raise http_error.Forbidden()
    return flask.send_file(record.file_path, conditional=True)

def _get_asset(file_path):
    """Get the database record for an asset file"""
    record = model.Image.get(file_path=file_path)
    fingerprint = ','.join((utils.file_fingerprint(file_path), str(RENDITION_VERSION)))
    if not record or record.fingerprint != fingerprint:
        logger.info('Updating image %s -> %s', file_path, fingerprint)
        md5 = hashlib.md5()
        md5.update(bytes(RENDITION_VERSION))
        with open(file_path, 'rb') as file:
            for chunk in iter(lambda: file.read(16384), b''):
                md5.update(chunk)
        values = {'file_path': file_path, 'checksum': md5.hexdigest(), 'fingerprint': fingerprint}
        try:
            image = PIL.Image.open(file_path)
            image = fix_orientation(image)
        except IOError:
            image = None
        if image:
            values['width'] = image.width
            values['height'] = image.height
            values['transparent'] = image.mode in ('RGBA', 'P')
            values['is_asset'] = False
        else:
            values['is_asset'] = True
            values['asset_name'] = os.path.join(values['checksum'][:5], os.path.basename(file_path))
        record = model.Image.get(file_path=file_path)
        if record:
            record.set(**values)
        else:
            record = model.Image(**values)
        orm.commit()
    return record

def get_image(path, search_path):
    """Get an Image object. If the path is given as absolute, it will be
    relative to the content directory; otherwise it will be relative to the
    search path.

    path -- the image's filename
    search_path -- a search path for the image (string or list of strings)"""
    if path.startswith('@'):
        return StaticImage(path[1:], search_path)
    if path.startswith('//') or '://' in path:
        return RemoteImage(path, search_path)
    if os.path.isabs(path):
        file_path = utils.find_file(os.path.relpath(path, '/'), config.content_folder)
    else:
        file_path = utils.find_file(path, search_path)
    if not file_path:
        return ImageNotFound(path, search_path)
    record = _get_asset(file_path)
    if record.is_asset:
        return FileAsset(record, search_path)
    return LocalImage(record, search_path)

def parse_arglist(args):
    """Parses an arglist into arguments for Image, as a kwargs dict"""
    args = 'f({})'.format(args)
    tree = ast.parse(args)
    funccall = tree.body[0].value
    args = [ast.literal_eval(arg) for arg in funccall.args]
    kwargs = {arg.arg: ast.literal_eval(arg.value) for arg in funccall.keywords}
    if len(args) > 2:
        raise TypeError('Expected at most 2 positional args but {} were given'.format(len(args)))
    if len(args) >= 1:
        kwargs['width'] = int(args[0])
    if len(args) >= 2:
        kwargs['height'] = int(args[1])
    return kwargs

def parse_image_spec(spec):
    """Parses out a Publ-Markdown image spec into a tuple of path, args, title"""
    match = re.match('(.+)\\s+\\"(.*)\\"\\s*$', spec)
    if match:
        spec, title = match.group(1, 2)
    else:
        title = None
    match = re.match('([^\\{]*)(\\{(.*)\\})\\s*$', spec)
    if match:
        spec = match.group(1)
        args = parse_arglist(match.group(3))
    else:
        args = {}
    return (spec, args, title and html.unescape(title))

def get_spec_list(image_specs, container_args):
    """Given a list of specs and a set of container args, return a tuple of
    the final container argument list and the original list size"""
    spec_list = [spec.strip() for spec in image_specs.split('|')]
    original_count = len(spec_list)
    if 'count' in container_args:
        if 'count_offset' in container_args:
            spec_list = spec_list[container_args['count_offset']:]
        spec_list = spec_list[:container_args['count']]
    return (spec_list, original_count)

def remove_aliases(target):
    """Remove all aliases to a destination"""
    if isinstance(target, model.Entry):
        orm.delete((p for p in model.PathAlias if p.entry == target))
    elif isinstance(target, model.Category):
        orm.delete((p for p in model.PathAlias if p.category == target))
    else:
        raise TypeError('Unknown type {}'.format(type(target)))
    orm.commit()

def get_alias(path):
    """Get a path alias for a single path

    Returns a tuple of (url,is_permanent)"""
    record = model.PathAlias.get(path=path)
    if not record:
        return (None, None)
    template = record.template if record.template != 'index' else None
    if record.entry and record.entry.visible:
        if record.template:
            category = record.category.category if record.category else record.entry.category
            return (url_for('category', start=record.entry.id, template=template, category=category), True)
        from . import entry
        outbound = entry.Entry(record.entry).get('Redirect-To')
        if outbound:
            return (outbound, False)
        return (url_for('entry', entry_id=record.entry.id, category=record.entry.category, slug_text=record.entry.slug_text), True)
    if record.category:
        return (url_for('category', category=record.category.category, template=template), True)
    if record.url:
        return (record.url, False)
    return (None, None)

def get_redirect(paths):
    """Get a redirect from a path or list of paths

    Arguments:

    paths -- either a single path string, or a list of paths to check

    Returns: a flask.redirect() result"""
    if isinstance(paths, str):
        paths = [paths]
    for path in paths:
        url, permanent = get_alias(path)
        if url:
            return redirect(url, 301 if permanent else 302)
        url, permanent = current_app.get_path_regex(path)
        if url:
            return redirect(url, 301 if permanent else 302)
    return None

def process(text, config, search_path):
    """Process an HTML entry's HTML"""
    processor = HTMLEntry(config, search_path)
    processor.feed(text)
    text = processor.get_data()
    if not config.get('no_smartquotes'):
        text = misaka.smartypants(text)
    return flask.Markup(text)

def last_modified():
    """information about the most recently modified file"""
    files = model.FileFingerprint.select().order_by(orm.desc(model.FileFingerprint.file_mtime))
    for file in files:
        return (file.file_mtime, file.file_path)
    return (None, None)

def get_last_fingerprint(fullpath):
    """Get the last known modification time for a file"""
    record = model.FileFingerprint.get(file_path=fullpath)
    if record:
        return record.fingerprint
    return None

def set_fingerprint(fullpath, fingerprint=None):
    """Set the last known modification time for a file"""
    try:
        fingerprint = fingerprint or utils.file_fingerprint(fullpath)
        record = model.FileFingerprint.get(file_path=fullpath)
        if record:
            record.set(fingerprint=fingerprint, file_mtime=os.stat(fullpath).st_mtime)
        else:
            record = model.FileFingerprint(file_path=fullpath, fingerprint=fingerprint, file_mtime=os.stat(fullpath).st_mtime)
        orm.commit()
    except FileNotFoundError:
        orm.delete((fp for fp in model.FileFingerprint if fp.file_path == fullpath))

def prune_missing(table):
    """Prune any files which are missing from the specified table"""
    try:
        for item in table.select():
            if not os.path.isfile(item.file_path):
                logger.info('File disappeared: %s', item.file_path)
                item.delete()
    except:
        logger.exception('Error pruning %s', table)

def scan_index(content_dir):
    """Scan all files in a content directory"""
    def scan_directory(root, files):
        """Helper function to scan a single directory"""
        try:
            for file in files:
                fullpath = os.path.join(root, file)
                relpath = os.path.relpath(fullpath, content_dir)
                fingerprint = utils.file_fingerprint(fullpath)
                last_fingerprint = get_last_fingerprint(fullpath)
                if fingerprint != last_fingerprint and SCHEDULED_FILES.add(fullpath):
                    scan_file(fullpath, relpath, False)
        except:
            logger.exception('Got error parsing directory %s', root)
    for root, _, files in os.walk(content_dir, followlinks=True):
        THREAD_POOL.submit(scan_directory, root, files)
    for table in (model.Entry, model.Category, model.Image, model.FileFingerprint):
        THREAD_POOL.submit(prune_missing, table)

def parse_view_spec(args):
    """Parse a view specification from a request arg list"""
    view_spec = {}
    if 'date' in args:
        view_spec['date'] = args['date']
    elif 'id' in args:
        view_spec['start'] = args['id']
    if 'tag' in args:
        view_spec['tag'] = args.getlist('tag')
        if len(view_spec['tag']) == 1:
            view_spec['tag'] = args['tag']
    return view_spec

def render_title(text, markup=True, no_smartquotes=False):
    """Convert a Markdown title to HTML"""
    pfx, text = re.match('([0-9. ]*)(.*)', text).group(1, 2)
    text = pfx + misaka.Markdown(TitleRenderer(), extensions=TITLE_EXTENSIONS)(text)
    if not markup:
        strip = HTMLStripper()
        strip.feed(text)
        text = strip.get_data()
    if not no_smartquotes:
        text = misaka.smartypants(text)
    return flask.Markup(text)

def resolve(path, search_path, absolute=False):
    """Remap a link or source target to an appropriate entry or image rendition"""
    if re.match('([a-z][a-z0-9+.\\-]*:)?//', path, re.I):
        return path
    if path.startswith('@'):
        return utils.static_url(path[1:], absolute)
    path, sep, anchor = path.partition('#')
    entry = utils.find_entry(path, search_path)
    if entry:
        return entry.permalink(absolute=absolute) + sep + anchor
    img_path, img_args, _ = image.parse_image_spec(path)
    img = image.get_image(img_path, search_path)
    if not isinstance(img, image.ImageNotFound):
        path, _ = img.get_rendition(**img_args)
    return path + sep + anchor

def do_not_cache():
    """Return whether we should cache a page render"""
    from . import index
    if index.in_progress():
        return True
    if request.if_none_match or request.if_modified_since:
        return True
    return False

def where_entry_visible(query, date=None):
    """Generate a where clause for currently-visible entries

    Arguments:

    date -- The date to generate it relative to (defaults to right now)"""
    return orm.select((e for e in query if e.status == model.PublishStatus.PUBLISHED.value or (e.status == model.PublishStatus.SCHEDULED.value and e.utc_date <= (date or arrow.utcnow().datetime))))

def where_entry_visible_future(query):
    """Generate a where clause for entries that are visible now or in the future"""
    return orm.select((e for e in query if e.status in (model.PublishStatus.PUBLISHED.value, model.PublishStatus.SCHEDULED.value)))

def where_entry_deleted(query):
    """Generate a where clause for entries that have been deleted"""
    return orm.select((e for e in query if e.status == model.PublishStatus.GONE.value))

def where_entry_category(query, category, recurse=False):
    """Generate a where clause for a particular category"""
    category = str(category)
    if category and recurse:
        return orm.select((e for e in query if e.category == category or e.category.startswith(category + '/')))
    if not recurse:
        return orm.select((e for e in query if e.category == category))
    return query

def where_before_entry(query, ref):
    """Generate a where clause for prior entries

    ref -- The entry of reference"""
    return orm.select((e for e in query if e.local_date < ref.local_date or (e.local_date == ref.local_date and e.id < ref.id)))

def where_after_entry(query, ref):
    """Generate a where clause for later entries

    ref -- the entry of reference"""
    return orm.select((e for e in query if e.local_date > ref.local_date or (e.local_date == ref.local_date and e.id > ref.id)))

def where_entry_last(query, ref):
    """Generate a where clause where this is the last entry

    ref -- the entry of reference"""
    return orm.select((e for e in query if e.local_date < ref.local_date or (e.local_date == ref.local_date and e.id <= ref.id)))

def where_entry_first(query, ref):
    """Generate a where clause where this is the first entry

    ref -- the entry of reference"""
    return orm.select((e for e in query if e.local_date > ref.local_date or (e.local_date == ref.local_date and e.id >= ref.id)))

def where_entry_type(query, entry_type):
    """Generate a where clause for entries of certain types

    entry_type -- one or more entries to check against"""
    if isinstance(entry_type, (list, set, tuple)):
        return orm.select((e for e in query if e.entry_type in entry_type))
    return orm.select((e for e in query if e.entry_type == entry_type))

def where_entry_tag(query, tag):
    """Generate a where clause for entries with the given tag"""
    if isinstance(tag, (list, set, tuple)):
        tags = [t.lower() for t in tag]
        return orm.select((e for e in query for t in e.tags if t.key in tags))
    return orm.select((e for e in query for t in e.tags if t.key == tag.lower()))

def where_entry_date(query, datespec):
    """Where clause for entries which match a textual date spec

    datespec -- The date spec to check for, in YYYY[[-]MM[[-]DD]] format"""
    date, interval, _ = utils.parse_date(datespec)
    start_date, end_date = date.span(interval)
    return orm.select((e for e in query if e.local_date >= start_date.naive and e.local_date <= end_date.naive))

def get_entry(entry):
    """Helper function to get an entry by ID or by object"""
    if hasattr(entry, 'id'):
        return entry
    if isinstance(entry, (int, str)):
        return model.Entry.get(id=int(entry))
    raise ValueError('entry is of unknown type {}'.format(type(entry)))

def start_init_info(path):
