        exit(1)
    else:
        logger.info('\x1b[33m{Info}\x1b[0m\n    ==> start init your flask project [on]\n    ==> \x1b[32m%s\x1b[0m\n' % path)

def _mkdir_p(abspath):
    """Usage:
        create the abspath
        except the abspath exist

    Param:
        abspath: the absolutly path you want to be created"""
    try:
        os.makedirs(abspath)
    except OSError as e:
        if e.errno == errno.EEXIST and os.path.isdir(abspath):
            pass
        else:
            raise

def raise_error(error_type: str) -> None:
    """Raise the appropriate error based on error message."""
    try:
        error = next((v for k, v in ERROR_CODES.items() if k in error_type))
    except StopIteration:
        error = AirVisualError
    raise error(error_type)

def column_width(tokens):
    """Return a suitable column width to display one or more strings."""
    get_len = tools.display_len if PY3 else len
    lens = sorted(map(get_len, tokens or [])) or [0]
    width = lens[-1]
    if width >= 18:
        most = lens[int(len(lens) * 0.9)]
        if most < width + 6:
            return most
    return width

def justify_token(tok, col_width):
    """Justify a string to fill one or more columns."""
    get_len = tools.display_len if PY3 else len
    tok_len = get_len(tok)
    diff_len = tok_len - len(tok) if PY3 else 0
    cols = int(math.ceil(float(tok_len) / col_width)) if col_width < tok_len + 4 else 1
    if cols > 1:
        return tok.ljust(col_width * cols + 4 * cols - diff_len)
    else:
        return tok.ljust(col_width + 4 - diff_len)

def display_name(name, obj, local):
    """Get the display name of an object.

    Keyword arguments (all required):

    * ``name`` -- the name of the object as a string.
    * ``obj`` -- the object itself.
    * ``local`` -- a boolean value indicating whether the object is in local
      scope or owned by an object."""
    prefix = '' if local else '.'
    if isinstance(obj, SeeError):
        suffix = '?'
    elif hasattr(obj, '__call__'):
        suffix = '()'
    else:
        suffix = ''
    return ''.join((prefix, name, suffix))

def term_width():
    """Return the column width of the terminal, or ``None`` if it can't be
    determined."""
    if fcntl and termios:
        try:
            winsize = fcntl.ioctl(0, termios.TIOCGWINSZ, '    ')
            _, width = struct.unpack('hh', winsize)
            return width
        except IOError:
            pass
    elif windll and create_string_buffer:
        stderr_handle, struct_size = (-12, 22)
        handle = windll.kernel32.GetStdHandle(stderr_handle)
        csbi = create_string_buffer(struct_size)
        res = windll.kernel32.GetConsoleScreenBufferInfo(handle, csbi)
        if res:
            _, _, _, _, _, left, _, right, _, _, _ = struct.unpack('hhhhHhhhhhh', csbi.raw)
            return right - left + 1
        else:
            return 0

def line_width(default_width=DEFAULT_LINE_WIDTH, max_width=MAX_LINE_WIDTH):
    """Return the ideal column width for the output from :func:`see.see`, taking
    the terminal width into account to avoid wrapping."""
    width = term_width()
    if width:
        return min(width, max_width)
    else:
        return default_width

def get_global_vars(func):
    """Store any methods or variables bound from the function's closure

    Args:
        func (function): function to inspect

    Returns:
        dict: mapping of variable names to globally bound VARIABLES"""
    closure = getclosurevars(func)
    if closure['nonlocal']:
        raise TypeError("Can't launch a job with closure variables: %s" % closure['nonlocals'].keys())
    globalvars = dict(modules={}, functions={}, vars={})
    for name, value in closure['global'].items():
        if inspect.ismodule(value):
            globalvars['modules'][name] = value.__name__
        elif inspect.isfunction(value) or inspect.ismethod(value):
            globalvars['functions'][name] = value
        else:
            globalvars['vars'][name] = value
    return globalvars

def getsourcefallback(cls):
    """Fallback for getting the source of interactively defined classes (typically in ipython)

    This is basically just a patched version of the inspect module, in which
    we get the code by calling inspect.findsource on an *instancemethod* of
    a class for which inspect.findsource fails."""
    for attr in cls.__dict__:
        if inspect.ismethod(getattr(cls, attr)):
            imethod = getattr(cls, attr)
            break
    else:
        raise AttributeError("Cannot get this class' source; it does not appear to have any methods")
    module = inspect.getmodule(cls)
    file = inspect.getfile(imethod)
    lines = linecache.getlines(file, module.__dict__)
    name = cls.__name__
    pat = re.compile('^(\\s*)class\\s*' + name + '\\b')
    candidates = []
    toplevel = False
    for i in range(len(lines)):
        match = pat.match(lines[i])
        if match:
            if lines[i][0] == 'c':
                flines, flnum = (lines, i)
                toplevel = True
                break
            candidates.append((match.group(1), i))
    if candidates and (not toplevel):
        candidates.sort()
        flines, flnum = (lines, candidates[0][1])
    elif not candidates and (not toplevel):
        raise IOError('could not find class definition')
    glines = inspect.getblock(flines[flnum:])
    if False:
        return ''.join(glines).decode(encoding)
    else:
        return ''.join(glines)

def create_build_context(image, inputs, wdir):
    """Creates a tar archive with a dockerfile and a directory called "inputs"
    The Dockerfile will copy the "inputs" directory to the chosen working directory"""
    assert os.path.isabs(wdir)
    dockerlines = ['FROM %s' % image, 'RUN mkdir -p %s' % wdir]
    build_context = {}
    if inputs:
        dockerlines.append('COPY root /')
        for ifile, (path, obj) in enumerate(inputs.items()):
            if not os.path.isabs(path):
                path = os.path.join(wdir, path)
            assert path[0] == '/'
            build_context['root' + path] = obj
    dockerstring = '\n'.join(dockerlines)
    build_context['Dockerfile'] = pyccc.BytesContainer(dockerstring.encode('utf-8'))
    return build_context

def make_tar_stream(build_context, buffer):
    """Write a tar stream of the build context to the provided buffer

    Args:
        build_context (Mapping[str, pyccc.FileReferenceBase]): dict mapping filenames to file references
        buffer (io.BytesIO): writable binary mode buffer"""
    tf = tarfile.TarFile(fileobj=buffer, mode='w')
    for context_path, fileobj in build_context.items():
        if getattr(fileobj, 'localpath', None) is not None:
            tf.add(fileobj.localpath, arcname=context_path)
        else:
            tar_add_bytes(tf, context_path, fileobj.read('rb'))
    tf.close()

def kwargs_from_client(client, assert_hostname=False):
    """More or less stolen from docker-py's kwargs_from_env
    https://github.com/docker/docker-py/blob/c0ec5512ae7ab90f7fac690064e37181186b1928/docker/utils/utils.py
    :type client : docker.Client"""
    from docker import tls
    if client.base_url in ('http+docker://localunixsocket', 'http+docker://localhost'):
        return {'base_url': 'unix://var/run/docker.sock'}
    params = {'base_url': client.base_url}
    if client.cert:
        params['tls'] = tls.TLSConfig(client_cert=client.cert, ca_cert=client.verify, verify=bool(client.verify), assert_hostname=assert_hostname)
    return params

def autodecode(b):
    """Try to decode ``bytes`` to text - try default encoding first, otherwise try to autodetect

    Args:
        b (bytes): byte string

    Returns:
        str: decoded text string"""
    import warnings
    import chardet
    try:
        return b.decode()
    except UnicodeError:
        result = chardet.detect(b)
        if result['confidence'] < 0.95:
            warnings.warn('autodecode failed with utf-8; guessing %s' % result['encoding'])
        return result.decode(result['encoding'])

def can_use_widgets():
    """Expanded from from http://stackoverflow.com/a/34092072/1958900
    """
    if 'IPython' not in sys.modules:
        return False
    from IPython import get_ipython
    if getattr(get_ipython(), 'kernel', None) is None:
        return False
    try:
        import ipywidgets as ipy
        import traitlets
    except ImportError:
        return False
    return True

def remove_directories(list_of_paths):
    """Removes non-leafs from a list of directory paths"""
    found_dirs = set('/')
    for path in list_of_paths:
        dirs = path.strip().split('/')
        for i in range(2, len(dirs)):
            found_dirs.add('/'.join(dirs[:i]))
    paths = [path for path in list_of_paths if path.strip() not in found_dirs and path.strip()[-1] != '/']
    return paths

def get_target_path(destination, origname):
    """Implements the directory/path semantics of linux mv/cp etc.

    Examples:
        >>> import os
        >>> os.makedirs('./a')
        >>> get_target_path('./a', '/tmp/myfile')
        './myfile'
        >>> get_target_path('./a/b', '/tmp/myfile')
        './a/b'

    Raises:
        OSError: if neither destination NOR destination's parent exists OR it already exists"""
    if os.path.exists(destination):
        if not os.path.isdir(destination):
            raise OSError('Cannot write to requested destination %s - file exists' % destination)
        return os.path.join(destination, os.path.basename(origname))
    else:
        destdir = os.path.abspath(os.path.join(destination, os.path.pardir))
        if not os.path.isdir(destdir):
            raise OSError('Cannot write to requested destination %s - parent directory does not exist' % destination)
        return os.path.join(destination)

def char_width(char):
    """Get the display length of a unicode character."""
    if ord(char) < 128:
        return 1
    elif unicodedata.east_asian_width(char) in ('F', 'W'):
        return 2
    elif unicodedata.category(char) in ('Mn',):
        return 0
    else:
        return 1

def display_len(text):
    """Get the display length of a string. This can differ from the character
    length if the string contains wide characters."""
    text = unicodedata.normalize('NFD', text)
    return sum((char_width(char) for char in text))

def filter_regex(names, regex):
    """Return a tuple of strings that match the regular expression pattern."""
    return tuple((name for name in names if regex.search(name) is not None))

def filter_wildcard(names, pattern):
    """Return a tuple of strings that match a shell-style wildcard pattern."""
    return tuple((name for name in names if fnmatch.fnmatch(name, pattern)))

def decimal_format(value, TWOPLACES=Decimal(100) ** (-2)):
    """Format a decimal.Decimal like to 2 decimal places."""
    if not isinstance(value, Decimal):
        value = Decimal(str(value))
    return value.quantize(TWOPLACES)

def notification_preference(obj_type, profile):
    """Display two radio buttons for turning notifications on or off.
    The default value is is have alerts_on = True."""
    default_alert_value = True
    if not profile:
        alerts_on = True
    else:
        notifications = profile.get('notifications', {})
        alerts_on = notifications.get(obj_type, default_alert_value)
    return dict(alerts_on=alerts_on, obj_type=obj_type)

def get_scraper(mod_path, scraper_type):
    """import a scraper from the scraper registry"""
    try:
        module = importlib.import_module(mod_path)
    except ImportError as e:
        raise ScrapeError('could not import %s' % mod_path, e)
    ScraperClass = None
    for k, v in module.__dict__.items():
        if k.startswith('_'):
            continue
        if getattr(v, 'scraper_type', None) == scraper_type:
            if ScraperClass:
                raise ScrapeError('two %s scrapers found in module %s: %s %s' % (scraper_type, mod_path, ScraperClass, k))
            ScraperClass = v
    if not ScraperClass:
        raise ScrapeError('no %s scraper found in module %s' % (scraper_type, mod_path))
    return ScraperClass

def populate_current_fields(abbr):
    """Set/update _current_term and _current_session fields on all bills
    for a given location."""
    meta = db.metadata.find_one({'_id': abbr})
    current_term = meta['terms'][-1]
    current_session = current_term['sessions'][-1]
    for bill in db.bills.find({settings.LEVEL_FIELD: abbr}):
        if bill['session'] == current_session:
            bill['_current_session'] = True
        else:
            bill['_current_session'] = False
        if bill['session'] in current_term['sessions']:
            bill['_current_term'] = True
        else:
            bill['_current_term'] = False
        db.bills.save(bill, safe=True)

def cd(path):
    """Creates the path if it doesn't exist"""
    old_dir = os.getcwd()
    try:
        os.makedirs(path)
    except OSError:
        pass
    os.chdir(path)
    try:
        yield
    finally:
        os.chdir(old_dir)

def _get_property_dict(schema):
    """given a schema object produce a nested dictionary of fields"""
    pdict = {}
    for k, v in schema['properties'].items():
        pdict[k] = {}
        if 'items' in v and 'properties' in v['items']:
            pdict[k] = _get_property_dict(v['items'])
    pdict[settings.LEVEL_FIELD] = {}
    return pdict

def insert_with_id(obj):
    """Generates a unique ID for the supplied legislator/committee/bill
    and inserts it into the appropriate collection."""
    if '_id' in obj:
        raise ValueError("object already has '_id' field")
    obj['created_at'] = datetime.datetime.utcnow()
    obj['updated_at'] = obj['created_at']
    if obj['_type'] == 'person' or obj['_type'] == 'legislator':
        collection = db.legislators
        id_type = 'L'
    elif obj['_type'] == 'committee':
        collection = db.committees
        id_type = 'C'
    elif obj['_type'] == 'bill':
        collection = db.bills
        id_type = 'B'
    else:
        raise ValueError('unknown _type for object')
    abbr = obj[settings.LEVEL_FIELD].upper()
    id_reg = re.compile('^%s%s' % (abbr, id_type))
    id_prefix = '%s%s' % (abbr, id_type)
    cursor = collection.find({'_id': id_reg}).sort('_id', -1).limit(1)
    try:
        new_id = int(next(cursor)['_id'][len(abbr) + 1:]) + 1
    except StopIteration:
        new_id = 1
    while True:
        if obj['_type'] == 'bill':
            obj['_id'] = '%s%08d' % (id_prefix, new_id)
        else:
            obj['_id'] = '%s%06d' % (id_prefix, new_id)
        obj['_all_ids'] = [obj['_id']]
        if obj['_type'] in ['person', 'legislator']:
            obj['leg_id'] = obj['_id']
        try:
            return collection.insert(obj, safe=True)
        except pymongo.errors.DuplicateKeyError:
            new_id += 1

def convert_timestamps(obj):
    """Convert unix timestamps in the scraper output to python datetimes
    so that they will be saved properly as Mongo datetimes."""
    for key in ('date', 'when', 'end', 'start_date', 'end_date'):
        value = obj.get(key)
        if value:
            try:
                obj[key] = _timestamp_to_dt(value)
            except TypeError:
                raise TypeError('expected float for %s, got %s' % (key, value))
    for key in ('sources', 'actions', 'votes', 'roles'):
        for child in obj.get(key, []):
            convert_timestamps(child)
    return obj

def split_name(obj):
    """If the supplied legislator/person object is missing 'first_name'
    or 'last_name' then use name_tools to split."""
    if obj['_type'] in ('person', 'legislator'):
        for key in ('first_name', 'last_name'):
            if key not in obj or not obj[key]:
                obj['first_name'], obj['last_name'], obj['suffixes'] = name_tools.split(obj['full_name'])[1:]
                break
    return obj

def _make_plus_helper(obj, fields):
    """add a + prefix to any fields in obj that aren't in fields"""
    new_obj = {}
    for key, value in obj.items():
        if key in fields or key.startswith('_'):
            if fields.get(key):
                if isinstance(value, list):
                    value = [_make_plus_helper(item, fields[key]) for item in value]
            new_obj[key] = value
        else:
            new_obj['+%s' % key] = value
    return new_obj

def make_plus_fields(obj):
    """Add a '+' to the key of non-standard fields.

    dispatch to recursive _make_plus_helper based on _type field"""
    fields = standard_fields.get(obj['_type'], dict())
    return _make_plus_helper(obj, fields)

def extract_fields(d, fields, delimiter='|'):
    """get values out of an object ``d`` for saving to a csv"""
    rd = {}
    for f in fields:
        v = d.get(f, None)
        if isinstance(v, (str, unicode)):
            v = v.encode('utf8')
        elif isinstance(v, list):
            v = delimiter.join(v)
        rd[f] = v
    return rd

def document(request, abbr, session, bill_id, doc_id):
    """Context:
        - abbr
        - session
        - bill
        - version
        - metadata
        - nav_active

    Templates:
        - billy/web/public/document.html"""
    fixed_bill_id = fix_bill_id(bill_id)
    if fixed_bill_id.replace(' ', '') != bill_id:
        return redirect('document', abbr=abbr, session=session, bill_id=fixed_bill_id.replace(' ', ''), doc_id=doc_id)
    bill = db.bills.find_one({settings.LEVEL_FIELD: abbr, 'session': session, 'bill_id': fixed_bill_id})
    if not bill:
        raise Http404('No such bill.')
    for version in bill['versions']:
        if version['doc_id'] == doc_id:
            break
    else:
        raise Http404('No such document.')
    if not settings.ENABLE_DOCUMENT_VIEW.get(abbr, False):
        return redirect(version['url'])
    return render(request, templatename('document'), dict(abbr=abbr, session=session, bill=bill, version=version, metadata=bill.metadata, nav_active='bills'))

