def TRM(f, a, b):
    """Calculate TRM using tanh relationship
     TRM(f)=a*math.tanh(b*f)"""
    m = float(a) * math.tanh(float(b) * float(f))
    return float(m)

def TRMinv(m, a, b):
    WARN = True
    '\n     Calculate applied field from TRM using tanh relationship\n     TRMinv(m)=(1/b)*atanh(m/a)\n    '
    if float(a) == 0:
        print('ERROR: TRMinv: a==0.')
        if not WARN:
            sys.exit()
    if float(b) == 0:
        print('ERROR: TRMinv: b==0.')
        if not WARN:
            sys.exit()
    x = old_div(float(m), float(a))
    if 1 - x <= 0:
        print('ERROR:  TRMinv: (1-x)==0.')
        return -1
    if not WARN:
        sys.exit()
    f = old_div(1.0, float(b)) * 0.5 * math.log(old_div(1 + x, 1 - x))
    return float(f)

def NRM(f, a, b, best):
    WARN = True
    ' \n    Calculate NRM expected lab field and estimated ancient field\n    NRM(blab,best)= (best/blab)*TRM(blab)\n    '
    if float(f) == 0:
        print('ERROR: NRM: f==0.')
    if not WARN:
        sys.exit()
    m = old_div(float(best), float(f)) * TRM(f, a, b)
    return float(m)

def get_numpy_dtype(obj):
    """Return NumPy data type associated to obj
    Return None if NumPy is not available
    or if obj is not a NumPy array or scalar"""
    if ndarray is not FakeObject:
        import numpy as np
        if isinstance(obj, np.generic) or isinstance(obj, np.ndarray):
            try:
                return obj.dtype.type
            except (AttributeError, RuntimeError):
                return

def address(obj):
    """Return object address as a string: '<classname @ address>'"""
    return '<%s @ %s>' % (obj.__class__.__name__, hex(id(obj)).upper().replace('X', 'x'))

def get_size(item):
    """Return size of an item of arbitrary type"""
    if isinstance(item, (list, set, tuple, dict)):
        return len(item)
    elif isinstance(item, (ndarray, MaskedArray)):
        return item.shape
    elif isinstance(item, Image):
        return item.size
    if isinstance(item, (DataFrame, Index, Series)):
        return item.shape
    else:
        return 1

def get_color_name(value):
    """Return color name depending on value type"""
    if not is_known_type(value):
        return CUSTOM_TYPE_COLOR
    for typ, name in list(COLORS.items()):
        if isinstance(value, typ):
            return name
    else:
        np_dtype = get_numpy_dtype(value)
        if np_dtype is None or not hasattr(value, 'size'):
            return UNSUPPORTED_COLOR
        elif value.size == 1:
            return SCALAR_COLOR
        else:
            return ARRAY_COLOR

def sort_against(list1, list2, reverse=False):
    """Arrange items of list1 in the same order as sorted(list2).

    In other words, apply to list1 the permutation which takes list2
    to sorted(list2, reverse)."""
    try:
        return [item for _, item in sorted(zip(list2, list1), key=lambda x: x[0], reverse=reverse)]
    except:
        return list1

def default_display(value, with_module=True):
    """Default display for unknown objects."""
    object_type = type(value)
    try:
        name = object_type.__name__
        module = object_type.__module__
        if with_module:
            return name + ' object of ' + module + ' module'
        else:
            return name
    except:
        type_str = to_text_string(object_type)
        return type_str[1:-1]

def collections_display(value, level):
    """Display for collections (i.e. list, set, tuple and dict)."""
    is_dict = isinstance(value, dict)
    is_set = isinstance(value, set)
    if is_dict:
        elements = iteritems(value)
    else:
        elements = value
    truncate = False
    if level == 1 and len(value) > 10:
        elements = islice(elements, 10) if is_dict or is_set else value[:10]
        truncate = True
    elif level == 2 and len(value) > 5:
        elements = islice(elements, 5) if is_dict or is_set else value[:5]
        truncate = True
    if level <= 2:
        if is_dict:
            displays = [value_to_display(k, level=level) + ':' + value_to_display(v, level=level) for k, v in list(elements)]
        else:
            displays = [value_to_display(e, level=level) for e in elements]
        if truncate:
            displays.append('...')
        display = ', '.join(displays)
    else:
        display = '...'
    if is_dict:
        display = '{' + display + '}'
    elif isinstance(value, list):
        display = '[' + display + ']'
    elif isinstance(value, set):
        display = '{' + display + '}'
    else:
        display = '(' + display + ')'
    return display

def get_type_string(item):
    """Return type string of an object."""
    if isinstance(item, DataFrame):
        return 'DataFrame'
    if isinstance(item, Index):
        return type(item).__name__
    if isinstance(item, Series):
        return 'Series'
    found = re.findall("<(?:type|class) '(\\S*)'>", to_text_string(type(item)))
    if found:
        return found[0]

def get_human_readable_type(item):
    """Return human-readable type string of an item"""
    if isinstance(item, (ndarray, MaskedArray)):
        return item.dtype.name
    elif isinstance(item, Image):
        return 'Image'
    else:
        text = get_type_string(item)
        if text is None:
            text = to_text_string('unknown')
        else:
            return text[text.find('.') + 1:]

def is_supported(value, check_all=False, filters=None, iterate=False):
    """Return True if the value is supported, False otherwise"""
    assert filters is not None
    if value is None:
        return True
    if not is_editable_type(value):
        return False
    elif not isinstance(value, filters):
        return False
    elif iterate:
        if isinstance(value, (list, tuple, set)):
            valid_count = 0
            for val in value:
                if is_supported(val, filters=filters, iterate=check_all):
                    valid_count += 1
                if not check_all:
                    break
            return valid_count > 0
        elif isinstance(value, dict):
            for key, val in list(value.items()):
                if not is_supported(key, filters=filters, iterate=check_all) or not is_supported(val, filters=filters, iterate=check_all):
                    return False
                if not check_all:
                    break
    return True

def globalsfilter(input_dict, check_all=False, filters=None, exclude_private=None, exclude_capitalized=None, exclude_uppercase=None, exclude_unsupported=None, excluded_names=None):
    """Keep only objects that can be pickled"""
    output_dict = {}
    for key, value in list(input_dict.items()):
        excluded = exclude_private and key.startswith('_') or (exclude_capitalized and key[0].isupper()) or (exclude_uppercase and key.isupper() and (len(key) > 1) and (not key[1:].isdigit())) or (key in excluded_names) or (exclude_unsupported and (not is_supported(value, check_all=check_all, filters=filters)))
        if not excluded:
            output_dict[key] = value
    return output_dict

def get_supported_types():
    """Return a dictionnary containing types lists supported by the
    namespace browser.

    Note:
    If you update this list, don't forget to update variablexplorer.rst
    in spyder-docs"""
    from datetime import date, timedelta
    editable_types = [int, float, complex, list, set, dict, tuple, date, timedelta] + list(TEXT_TYPES) + list(INT_TYPES)
    try:
        from numpy import ndarray, matrix, generic
        editable_types += [ndarray, matrix, generic]
    except:
        pass
    try:
        from pandas import DataFrame, Series, DatetimeIndex
        editable_types += [DataFrame, Series, Index]
    except:
        pass
    picklable_types = editable_types[:]
    try:
        from spyder.pil_patch import Image
        editable_types.append(Image.Image)
    except:
        pass
    return dict(picklable=picklable_types, editable=editable_types)

