def load_dictionary(filename):
    """Load dictionary from .spydata file"""
    filename = osp.abspath(filename)
    old_cwd = getcwd()
    tmp_folder = tempfile.mkdtemp()
    os.chdir(tmp_folder)
    data = None
    error_message = None
    try:
        with tarfile.open(filename, 'r') as tar:
            tar.extractall()
        pickle_filename = glob.glob('*.pickle')[0]
        with open(pickle_filename, 'rb') as fdesc:
            data = pickle.loads(fdesc.read())
        saved_arrays = {}
        if load_array is not None:
            try:
                saved_arrays = data.pop('__saved_arrays__')
                for (name, index), fname in list(saved_arrays.items()):
                    arr = np.load(osp.join(tmp_folder, fname))
                    if index is None:
                        data[name] = arr
                    elif isinstance(data[name], dict):
                        data[name][index] = arr
                    else:
                        data[name].insert(index, arr)
            except KeyError:
                pass
    except (AttributeError, EOFError, ValueError) as error:
        error_message = to_text_string(error)
    finally:
        os.chdir(old_cwd)
        try:
            shutil.rmtree(tmp_folder)
        except OSError as error:
            error_message = to_text_string(error)
    return (data, error_message)

def getobj(txt, last=False):
    """Return the last valid object name in string"""
    txt_end = ''
    for startchar, endchar in ['[]', '()']:
        if txt.endswith(endchar):
            pos = txt.rfind(startchar)
            if pos:
                txt_end = txt[pos:]
                txt = txt[:pos]
    tokens = re.split(SYMBOLS, txt)
    token = None
    try:
        while token is None or re.match(SYMBOLS, token):
            token = tokens.pop()
        if token.endswith('.'):
            token = token[:-1]
        if token.startswith('.'):
            return None
        if last:
            token += txt[txt.rfind(token) + len(token)]
        token += txt_end
        if token:
            return token
    except IndexError:
        return None

def getsource(obj):
    """Wrapper around inspect.getsource"""
    try:
        try:
            src = to_text_string(inspect.getsource(obj))
        except TypeError:
            if hasattr(obj, '__class__'):
                src = to_text_string(inspect.getsource(obj.__class__))
            else:
                src = getdoc(obj)
        return src
    except (TypeError, IOError):
        return

def getargsfromtext(text, objname):
    """Get arguments from text (object documentation)"""
    signature = getsignaturefromtext(text, objname)
    if signature:
        argtxt = signature[signature.find('(') + 1:-1]
        return argtxt.split(',')

def getargs(obj):
    """Get the names and default values of a function's arguments"""
    if inspect.isfunction(obj) or inspect.isbuiltin(obj):
        func_obj = obj
    elif inspect.ismethod(obj):
        func_obj = get_meth_func(obj)
    elif inspect.isclass(obj) and hasattr(obj, '__init__'):
        func_obj = getattr(obj, '__init__')
    else:
        return []
    if not hasattr(func_obj, 'func_code'):
        args = getargsfromdoc(func_obj)
        if args is not None:
            return args
        else:
            return getargsfromdoc(obj)
    args, _, _ = inspect.getargs(func_obj.func_code)
    if not args:
        return getargsfromdoc(obj)
    for i_arg, arg in enumerate(args):
        if isinstance(arg, list):
            args[i_arg] = '(%s)' % ', '.join(arg)
    defaults = get_func_defaults(func_obj)
    if defaults is not None:
        for index, default in enumerate(defaults):
            args[index + len(args) - len(defaults)] += '=' + repr(default)
    if inspect.isclass(obj) or inspect.ismethod(obj):
        if len(args) == 1:
            return None
        if 'self' in args:
            args.remove('self')
    return args

def getargtxt(obj, one_arg_per_line=True):
    """Get the names and default values of a function's arguments
    Return list with separators (', ') formatted for calltips"""
    args = getargs(obj)
    if args:
        sep = ', '
        textlist = None
        for i_arg, arg in enumerate(args):
            if textlist is None:
                textlist = ['']
            textlist[-1] += arg
            if i_arg < len(args) - 1:
                textlist[-1] += sep
                if len(textlist[-1]) >= 32 or one_arg_per_line:
                    textlist.append('')
        if inspect.isclass(obj) or inspect.ismethod(obj):
            if len(textlist) == 1:
                return None
            if 'self' + sep in textlist:
                textlist.remove('self' + sep)
        return textlist

def isdefined(obj, force_import=False, namespace=None):
    """Return True if object is defined in namespace
    If namespace is None --> namespace = locals()"""
    if namespace is None:
        namespace = locals()
    attr_list = obj.split('.')
    base = attr_list.pop(0)
    if len(base) == 0:
        return False
    if base not in builtins.__dict__ and base not in namespace:
        if force_import:
            try:
                module = __import__(base, globals(), namespace)
                if base not in globals():
                    globals()[base] = module
                namespace[base] = module
            except Exception:
                return False
        else:
            return False
    for attr in attr_list:
        try:
            attr_not_found = not hasattr(eval(base, namespace), attr)
        except (SyntaxError, AttributeError):
            return False
        if attr_not_found:
            if force_import:
                try:
                    __import__(base + '.' + attr, globals(), namespace)
                except (ImportError, SyntaxError):
                    return False
            else:
                return False
        base += '.' + attr
    return True

def _normalize_entity(value):
    """Return an entity from an entity or model instance."""
    if ndb is not None and isinstance(value, ndb.Model):
        return None
    if getattr(value, '_populate_internal_entity', None):
        return value._populate_internal_entity()
    return value

def _normalize_key(value):
    """Return a key from an entity, model instance, key, or key string."""
    if ndb is not None and isinstance(value, (ndb.Model, ndb.Key)):
        return None
    if getattr(value, 'key', None):
        return value.key()
    elif isinstance(value, basestring):
        return datastore.Key(value)
    else:
        return value

def handler_for_name(fq_name):
    """Resolves and instantiates handler by fully qualified name.

    First resolves the name using for_name call. Then if it resolves to a class,
    instantiates a class, if it resolves to a method - instantiates the class and
    binds method to the instance.

    Args:
      fq_name: fully qualified name of something to find.

    Returns:
      handler instance which is ready to be called."""
    resolved_name = for_name(fq_name)
    if isinstance(resolved_name, (type, types.ClassType)):
        return resolved_name()
    elif isinstance(resolved_name, types.MethodType):
        return getattr(resolved_name.im_class(), resolved_name.__name__)
    else:
        return resolved_name

def create_datastore_write_config(mapreduce_spec):
