def convert_to_wav(files):
    """Converts files to a format that pocketsphinx can deal wtih (16khz mono 16bit wav)"""
    converted = []
    for f in files:
        new_name = f + '.temp.wav'
        print(new_name)
        if os.path.exists(f + '.transcription.txt') is False and os.path.exists(new_name) is False:
            subprocess.call(['ffmpeg', '-y', '-i', f, '-acodec', 'pcm_s16le', '-ac', '1', '-ar', '16000', new_name])
        converted.append(new_name)
    return converted

def convert_timestamps(files):
    """Converts pocketsphinx transcriptions to usable timestamps"""
    sentences = []
    for f in files:
        if not f.endswith('.transcription.txt'):
            f = f + '.transcription.txt'
        if os.path.exists(f) is False:
            continue
        with open(f, 'r') as infile:
            lines = infile.readlines()
        lines = [re.sub('\\(.*?\\)', '', l).strip().split(' ') for l in lines]
        lines = [l for l in lines if len(l) == 4]
        seg_start = -1
        seg_end = -1
        for index, line in enumerate(lines):
            word, start, end, conf = line
            if word == '<s>' or word == '<sil>' or word == '</s>':
                if seg_start == -1:
                    seg_start = index
                    seg_end = -1
                else:
                    seg_end = index
                if seg_start > -1 and seg_end > -1:
                    words = lines[seg_start + 1:seg_end]
                    start = float(lines[seg_start][1])
                    end = float(lines[seg_end][1])
                    if words:
                        sentences.append({'start': start, 'end': end, 'words': words, 'file': f})
                    if word == '</s>':
                        seg_start = -1
                    else:
                        seg_start = seg_end
                    seg_end = -1
    return sentences

def text(files):
    """Returns the whole transcribed text"""
    sentences = convert_timestamps(files)
    out = []
    for s in sentences:
        out.append(' '.join([w[0] for w in s['words']]))
    return '\n'.join(out)

def compose(segments, out='out.mp3', padding=0, crossfade=0, layer=False):
    """Stiches together a new audiotrack"""
    files = {}
    working_segments = []
    audio = AudioSegment.empty()
    if layer:
        total_time = max([s['end'] - s['start'] for s in segments]) * 1000
        audio = AudioSegment.silent(duration=total_time)
    for i, s in enumerate(segments):
        try:
            start = s['start'] * 1000
            end = s['end'] * 1000
            f = s['file'].replace('.transcription.txt', '')
            if f not in files:
                if f.endswith('.wav'):
                    files[f] = AudioSegment.from_wav(f)
                elif f.endswith('.mp3'):
                    files[f] = AudioSegment.from_mp3(f)
            segment = files[f][start:end]
            print(start, end, f)
            if layer:
                audio = audio.overlay(segment, times=1)
            elif i > 0:
                audio = audio.append(segment, crossfade=crossfade)
            else:
                audio = audio + segment
            if padding > 0:
                audio = audio + AudioSegment.silent(duration=padding)
            s['duration'] = len(segment)
            working_segments.append(s)
        except:
            continue
    audio.export(out, format=os.path.splitext(out)[1].replace('.', ''))
    return working_segments

def check_key(key, allowed):
    """Validate that the specified key is allowed according the provided
    list of patterns."""
    if key in allowed:
        return True
    for pattern in allowed:
        if fnmatch(key, pattern):
            return True
    return False

def cs_encode(s):
    """Encode URI component like CloudStack would do before signing.

    java.net.URLEncoder.encode(s).replace('+', '%20')"""
    if PY2 and isinstance(s, text_type):
        s = s.encode('utf-8')
    return quote(s, safe='*')

def transform(params):
    """Transforms an heterogeneous map of params into a CloudStack
    ready mapping of parameter to values.

    It handles lists and dicts.

    >>> p = {"a": 1, "b": "foo", "c": ["eggs", "spam"], "d": {"key": "value"}}
    >>> transform(p)
    >>> print(p)
    {'a': '1', 'b': 'foo', 'c': 'eggs,spam', 'd[0].key': 'value'}"""
    for key, value in list(params.items()):
        if value is None:
            params.pop(key)
            continue
        if isinstance(value, (string_type, binary_type)):
            continue
        if isinstance(value, integer_types):
            params[key] = text_type(value)
        elif isinstance(value, (list, tuple, set, dict)):
            if not value:
                params.pop(key)
            else:
                if isinstance(value, dict):
                    value = [value]
                if isinstance(value, set):
                    value = list(value)
                if not isinstance(value[0], dict):
                    params[key] = ','.join(value)
                else:
                    params.pop(key)
                    for index, val in enumerate(value):
                        for name, v in val.items():
                            k = '%s[%d].%s' % (key, index, name)
                            params[k] = text_type(v)
        else:
            raise ValueError(type(value))

def read_config(ini_group=None):
    """Read the configuration from the environment, or config.

    First it try to go for the environment, then it overrides
    those with the cloudstack.ini file."""
    env_conf = dict(DEFAULT_CONFIG)
    for key in REQUIRED_CONFIG_KEYS.union(ALLOWED_CONFIG_KEYS):
        env_key = 'CLOUDSTACK_{0}'.format(key.upper())
        value = os.getenv(env_key)
        if value:
            env_conf[key] = value
    overrides = os.getenv('CLOUDSTACK_OVERRIDES', '').strip()
    if not overrides and set(env_conf).issuperset(REQUIRED_CONFIG_KEYS):
        return env_conf
    ini_conf = read_config_from_ini(ini_group)
    overrides = {s.lower() for s in re.split('\\W+', overrides)}
    config = dict(dict(env_conf, **ini_conf), **{k: v for k, v in env_conf.items() if k in overrides})
    missings = REQUIRED_CONFIG_KEYS.difference(config)
    if missings:
        raise ValueError('the configuration is missing the following keys: ' + ', '.join(missings))
    bool_keys = ('dangerous_no_tls_verify',)
    for bool_key in bool_keys:
        if isinstance(config[bool_key], string_type):
            try:
                config[bool_key] = strtobool(config[bool_key])
            except ValueError:
                pass
    return config

def _format_json(data, theme):
    """Pretty print a dict as a JSON, with colors if pygments is present."""
    output = json.dumps(data, indent=2, sort_keys=True)
    if pygments and sys.stdout.isatty():
        style = get_style_by_name(theme)
        formatter = Terminal256Formatter(style=style)
        return pygments.highlight(output, JsonLexer(), formatter)
    return output

def data_merge(a, b):
    """merges b into a and return merged result
    based on http://stackoverflow.com/questions/7204805/python-dictionaries-of-dictionaries-merge
    and extended to also merge arrays and to replace the content of keys with the same name

    NOTE: tuples and arbitrary objects are not handled as it is totally ambiguous what should happen"""
    key = None
    try:
        if a is None or isinstance(a, (six.string_types, float, six.integer_types)):
            a = b
        elif isinstance(a, list):
            if isinstance(b, list):
                a.extend(b)
            else:
                a.append(b)
        elif isinstance(a, dict):
            if isinstance(b, dict):
                for key in b:
                    if key in a:
                        a[key] = data_merge(a[key], b[key])
                    else:
                        a[key] = b[key]
            else:
                raise YamlReaderError('Cannot merge non-dict "%s" into dict "%s"' % (b, a))
        else:
            raise YamlReaderError('NOT IMPLEMENTED "%s" into "%s"' % (b, a))
    except TypeError as e:
        raise YamlReaderError('TypeError "%s" in key "%s" when merging "%s" into "%s"' % (e, key, b, a))
    return a

def hacking_todo_format(physical_line, tokens):
    """Check for 'TODO()'.

    OpenStack HACKING guide recommendation for TODO:
    Include your name with TODOs as in "# TODO(termie)"

    Okay: # TODO(sdague)
    H101: # TODO fail
    H101: # TODO
    H101: # TODO (jogo) fail
    Okay: TODO = 5"""
    for token_type, text, start_index, _, _ in tokens:
        if token_type == tokenize.COMMENT:
            pos = text.find('TODO')
            pos1 = text.find('TODO(')
            if pos != pos1:
                return (pos + start_index[1], 'H101: Use TODO(NAME)')

def hacking_has_license(physical_line, filename, lines, line_number):
    """Check for Apache 2.0 license.

    H102 license header not found"""
    license_found = False
    if line_number is 1 and len(lines) > 10 and _project_is_apache():
        for idx, line in enumerate(lines):
            if 0 <= line.find('Licensed under the Apache License') < 10:
                license_found = True
            if 0 <= line.find('SPDX-License-Identifier:') < 10:
                license_found = True
        if not license_found:
            return (0, 'H102: Apache 2.0 license header not found')

def hacking_has_correct_license(physical_line, filename, lines, line_number):
    """Check for Apache 2.0 license.

    H103 header does not match Apache 2.0 License notice"""
    if line_number is 1 and len(lines) > 10 and _project_is_apache():
        for idx, line in enumerate(lines):
            column = line.find('Licensed under the Apache License')
            if 0 < column < 10 and (not _check_for_exact_apache(idx, lines)):
                if line.find('SPDX-License-Identifier: Apache-2.0') <= 0:
                    return (column, 'H103: Header does not match Apache 2.0 License notice')

def hacking_has_only_comments(physical_line, filename, lines, line_number):
    """Check for empty files with only comments

    H104 empty file with only comments"""
    if line_number == 1 and all(map(EMPTY_LINE_RE.match, lines)):
        return (0, 'H104: File contains nothing but comments')

def hacking_no_author_tags(physical_line):
    """Check that no author tags are used.

    H105 don't use author tags"""
    for regex in AUTHOR_TAG_RE:
        if regex.match(physical_line):
            physical_line = physical_line.lower()
            pos = physical_line.find('moduleauthor')
            if pos < 0:
                pos = physical_line.find('author')
            return (pos, "H105: Don't use author tags")

def hacking_no_assert_equals(logical_line, tokens, noqa):
    """assert(Not)Equals() is deprecated, use assert(Not)Equal instead.

    Okay: self.assertEqual(0, 0)
    Okay: self.assertNotEqual(0, 1)
    H234: self.assertEquals(0, 0)
    H234: self.assertNotEquals(0, 1)
    Okay: self.assertEquals(0, 0)  # noqa
    Okay: self.assertNotEquals(0, 1)  # noqa"""
    if noqa:
        return
    for token_type, text, start_index, _, _ in tokens:
        if token_type == tokenize.NAME:
            if text == 'assertEquals' or text == 'assertNotEquals':
                yield (start_index[1], 'H234: %s is deprecated, use %s' % (text, text[:-1]))

def is_import_exception(mod):
    """Check module name to see if import has been whitelisted.

    Import based rules should not run on any whitelisted module"""
    return mod in IMPORT_EXCEPTIONS or any((mod.startswith(m + '.') for m in IMPORT_EXCEPTIONS))

def hacking_no_locals(logical_line, tokens, noqa):
    """Do not use locals() or self.__dict__ for string formatting.

    Okay: 'locals()'
    Okay: 'locals'
    Okay: locals()
    Okay: print(locals())
    H501: print("%(something)" % locals())
    H501: LOG.info(_("%(something)") % self.__dict__)
    Okay: print("%(something)" % locals())  # noqa"""
    if noqa:
        return
    for_formatting = False
    for token_type, text, start, _, _ in tokens:
        if text == '%' and token_type == tokenize.OP:
            for_formatting = True
        if for_formatting and token_type == tokenize.NAME:
            for k, v in LOCALS_TEXT_MAP.items():
                if text == k and v in logical_line:
                    yield (start[1], 'H501: Do not use %s for string formatting' % v)

def hacking_docstring_multiline_start(physical_line, previous_logical, tokens):
    """Check multi line docstring starts immediately with summary.

    OpenStack HACKING guide recommendation for docstring:
    Docstring should start with a one-line summary, less than 80 characters.

    Okay: '''foobar\\n\\nfoo\\nbar\\n'''
    Okay: def foo():\\n    a = '''\\nnot\\na docstring\\n'''
    H404: def foo():\\n    '''\\nfoo\\nbar\\n'''\\n\\n
    H404: def foo():\\n    r'''\\nfoo\\nbar\\n'''\\n\\n"""
    docstring = is_docstring(tokens, previous_logical)
    if docstring:
        if '\n' not in docstring:
            return
        start, start_triple = _find_first_of(docstring, START_DOCSTRING_TRIPLE)
        lines = docstring.split('\n')
        if lines[0].strip() == start_triple:
            return (0, 'H404: multi line docstring should start without a leading new line')

def hacking_docstring_summary(physical_line, previous_logical, tokens):
    """Check multi line docstring summary is separated with empty line.

    OpenStack HACKING guide recommendation for docstring:
    Docstring should start with a one-line summary, less than 80 characters.

    Okay: def foo():\\n    a = '''\\nnot\\na docstring\\n'''
    Okay: '''foobar\\n\\nfoo\\nbar\\n'''
    H405: def foo():\\n    '''foobar\\nfoo\\nbar\\n'''
    H405: def foo():\\n    r'''foobar\\nfoo\\nbar\\n'''
    H405: def foo():\\n    '''foobar\\n'''"""
    docstring = is_docstring(tokens, previous_logical)
    if docstring:
        if '\n' not in docstring:
            return
        lines = docstring.split('\n')
        if len(lines) > 1 and len(lines[1].strip()) is not 0:
            return (0, 'H405: multi line docstring summary not separated with an empty line')

def is_docstring(tokens, previous_logical):
    """Return found docstring

    'A docstring is a string literal that occurs as the first statement in a
    module, function, class,'
    http://www.python.org/dev/peps/pep-0257/#what-is-a-docstring"""
    for token_type, text, start, _, _ in tokens:
        if token_type == tokenize.STRING:
            break
        elif token_type != tokenize.INDENT:
            return False
    else:
        return False
    line = text.lstrip()
    start, start_triple = _find_first_of(line, START_DOCSTRING_TRIPLE)
    if previous_logical.startswith('def ') or previous_logical.startswith('class '):
        if start == 0:
            return text

def _find_first_of(line, substrings):
    """Find earliest occurrence of one of substrings in line.

    Returns pair of index and found substring, or (-1, None)
    if no occurrences of any of substrings were found in line."""
    starts = ((line.find(i), i) for i in substrings)
    found = [(i, sub) for i, sub in starts if i != -1]
    if found:
        return min(found)
    else:
        return (-1, None)

def hacking_no_cr(physical_line):
    """Check that we only use newlines not carriage returns.

    Okay: import os\\nimport sys
    # pep8 doesn't yet replace \\r in strings, will work on an
    # upstream fix
    H903 import os\\r\\nimport sys"""
    pos = physical_line.find('\r')
    if pos != -1 and pos == len(physical_line) - 2:
        return (pos, 'H903: Windows style line endings not allowed in code')

def fields_to_dtypes(schema):
