def move_to_backup(path, backup_suffix=BACKUP_SUFFIX):
    """Move the given file or directory to the same name, with a backup suffix.
    If backup_suffix not supplied, move it to the extension ".bak".
    NB: If backup_suffix is supplied and is None, don't do anything."""
    if backup_suffix and os.path.exists(path):
        backup_path = path + backup_suffix
        if os.path.islink(backup_path):
            os.unlink(backup_path)
        elif os.path.isdir(backup_path):
            shutil.rmtree(backup_path)
        shutil.move(path, backup_path)

def make_all_dirs(path, mode=511):
    """Ensure local dir, with all its parent dirs, are created.
    Unlike os.makedirs(), will not fail if the path already exists."""
    try:
        os.makedirs(path, mode=mode)
    except OSError as e:
        if e.errno == errno.EEXIST and os.path.isdir(path):
            pass
        else:
            raise
    return path

def make_parent_dirs(path, mode=511):
    """Ensure parent directories of a file are created as needed."""
    parent = os.path.dirname(path)
    if parent:
        make_all_dirs(parent, mode)
    return path

def atomic_output_file(dest_path, make_parents=False, backup_suffix=None, suffix='.partial.%s'):
    """A context manager for convenience in writing a file or directory in an atomic way. Set up
    a temporary name, then rename it after the operation is done, optionally making a backup of
    the previous file or directory, if present."""
    if dest_path == os.devnull:
        yield dest_path
    else:
        tmp_path = ('%s' + suffix) % (dest_path, new_uid())
        if make_parents:
            make_parent_dirs(tmp_path)
        yield tmp_path
        if not os.path.exists(tmp_path):
            raise IOError("failure in writing file '%s': target file '%s' missing" % (dest_path, tmp_path))
        if backup_suffix:
            move_to_backup(dest_path, backup_suffix=backup_suffix)
        if os.path.isdir(dest_path):
            shutil.rmtree(dest_path)
        shutil.move(tmp_path, dest_path)

def set_file_mtime(path, mtime, atime=None):
    """Set access and modification times on a file."""
    if not atime:
        atime = mtime
    f = open(path, 'a')
    try:
        os.utime(path, (atime, mtime))
    finally:
        f.close()

def copytree_atomic(source_path, dest_path, make_parents=False, backup_suffix=None, symlinks=False):
    """Copy a file or directory recursively, and atomically, reanaming file or top-level dir when done.
    Unlike shutil.copytree, this will not fail on a file."""
    if os.path.isdir(source_path):
        with atomic_output_file(dest_path, make_parents=make_parents, backup_suffix=backup_suffix) as tmp_path:
            shutil.copytree(source_path, tmp_path, symlinks=symlinks)
    else:
        copyfile_atomic(source_path, dest_path, make_parents=make_parents, backup_suffix=backup_suffix)

def movefile(source_path, dest_path, make_parents=False, backup_suffix=None):
    """Move file. With a few extra options."""
    if make_parents:
        make_parent_dirs(dest_path)
    move_to_backup(dest_path, backup_suffix=backup_suffix)
    shutil.move(source_path, dest_path)

def rmtree_or_file(path, ignore_errors=False, onerror=None):
    """rmtree fails on files or symlinks. This removes the target, whatever it is."""
    if ignore_errors and (not os.path.exists(path)):
        return
    if os.path.isdir(path) and (not os.path.islink(path)):
        shutil.rmtree(path, ignore_errors=ignore_errors, onerror=onerror)
    else:
        os.unlink(path)

def file_sha1(path):
    """Compute SHA1 hash of a file."""
    sha1 = hashlib.sha1()
    with open(path, 'rb') as f:
        while True:
            block = f.read(2 ** 10)
            if not block:
                break
            sha1.update(block)
        return sha1.hexdigest()

def _normalise_key_values(filter_obj, attr_map=None):
    """Converts nested dictionary filters into django-style key value pairs

    Map filter operators and aliases to operator-land
    Additionally, perform replacements according to attribute map
    Automatically assumes __eq if not explicitly defined"""
    new_filter = {}
    for key, constraints in filter_obj.items():
        aliased_key = key
        if attr_map is not None:
            aliased_key = attr_map.get(key)
            if aliased_key is None:
                raise CloudValueError('Invalid key %r for filter attribute; must be one of:\n%s' % (key, attr_map.keys()))
        if not isinstance(constraints, dict):
            constraints = {'eq': constraints}
        for operator, value in constraints.items():
            canonical_operator = FILTER_OPERATOR_ALIASES.get(operator.lstrip('$'))
            if canonical_operator is None:
                raise CloudValueError('Invalid operator %r for filter key %s; must be one of:\n%s' % (operator, key, FILTER_OPERATOR_ALIASES.keys()))
            canonical_key = str('%s__%s' % (aliased_key, canonical_operator))
            new_filter[canonical_key] = _normalise_value(value)
    return new_filter

def _get_filter(sdk_filter, attr_map):
    """Common functionality for filter structures

    :param sdk_filter: {field:constraint, field:{operator:constraint}, ...}
    :return: {field__operator: constraint, ...}"""
    if not isinstance(sdk_filter, dict):
        raise CloudValueError('filter value must be a dictionary, was %r' % (sdk_filter,))
    custom = sdk_filter.pop('custom_attributes', {})
    new_filter = _normalise_key_values(filter_obj=sdk_filter, attr_map=attr_map)
    new_filter.update({'custom_attributes__%s' % k: v for k, v in _normalise_key_values(filter_obj=custom).items()})
    return new_filter

def legacy_filter_formatter(kwargs, attr_map):
    """Builds a filter for update and device apis

    :param kwargs: expected to contain {'filter/filters': {filter dict}}
    :returns: {'filter': 'url-encoded-validated-filter-string'}"""
    params = _depluralise_filters_key(copy.copy(kwargs))
    new_filter = _get_filter(sdk_filter=params.pop('filter', {}), attr_map=attr_map)
    if new_filter:
        new_filter = sorted([(k.rsplit('__eq')[0], v) for k, v in new_filter.items()])
        params['filter'] = urllib.parse.urlencode(new_filter)
    return params

def expand_dict_as_keys(d):
    """Expands a dictionary into a list of immutables with cartesian product

    :param d: dictionary (of strings or lists)
    :returns: cartesian product of list parts"""
    to_product = []
    for key, values in sorted(d.items()):
        key_values = sorted([(key, v) for v in utils.ensure_listable(values) if v is not None])
        if key_values:
            to_product.append(key_values)
    return list(itertools.product(*to_product))

