    else:
        return (endpoint, client.endpoint_server_list(endpoint_id))

def cancel_task(all, task_id):
    """Executor for `globus task cancel`"""
    if bool(all) + bool(task_id) != 1:
        raise click.UsageError('You must pass EITHER the special --all flag to cancel all in-progress tasks OR a single task ID to cancel.')
    client = get_client()
    if all:
        from sys import maxsize
        task_ids = [task_row['task_id'] for task_row in client.task_list(filter='type:TRANSFER,DELETE/status:ACTIVE,INACTIVE', fields='task_id', num_results=maxsize)]
        task_count = len(task_ids)
        if not task_ids:
            raise click.ClickException('You have no in-progress tasks.')
        def cancellation_iterator():
            for i in task_ids:
                yield (i, client.cancel_task(i).data)
        def json_converter(res):
            return {'results': [x for i, x in cancellation_iterator()], 'task_ids': task_ids}
        def _custom_text(res):
            for i, (task_id, data) in enumerate(cancellation_iterator(), start=1):
                safeprint(u'{} ({} of {}): {}'.format(task_id, i, task_count, data['message']))
        formatted_print(None, text_format=_custom_text, json_converter=json_converter)
    else:
        res = client.cancel_task(task_id)
        formatted_print(res, text_format=FORMAT_TEXT_RAW, response_key='message')

