def one_use_option(*args, **kwargs):
    """Wrapper of the click.option decorator that replaces any instances of
    the Option class with the custom OneUseOption class"""
    if 'multiple' in kwargs or 'count' in kwargs:
        raise ValueError('Internal error, one_use_option cannot be  used with multiple or count.')
    if kwargs.get('cls'):
        raise TypeError('Internal error, one_use_option cannot overwrite cls {}.'.format(kwargs.get('cls')))
    kwargs['cls'] = OneUseOption
    if kwargs.get('is_flag'):
        kwargs['is_flag'] = False
        kwargs['count'] = True
    else:
        kwargs['multiple'] = True
    def decorator(f):
        return click.option(*args, **kwargs)(f)
    return decorator

def _spec_to_matches(server_list, server_spec, mode):
    """mode is in {uri, hostname, hostname_port}

    A list of matching server docs.
    Should usually be 0 or 1 matches. Multiple matches are possible though."""
    assert mode in ('uri', 'hostname', 'hostname_port')
    def match(server_doc):
        if mode == 'hostname':
            return server_spec == server_doc['hostname']
        elif mode == 'hostname_port':
            return server_spec == '{}:{}'.format(server_doc['hostname'], server_doc['port'])
        elif mode == 'uri':
            return server_spec == '{}://{}:{}'.format(server_doc['scheme'], server_doc['hostname'], server_doc['port'])
        else:
            raise NotImplementedError('Unreachable error! Something is very wrong.')
    return [server_doc for server_doc in server_list if match(server_doc)]

