        raise click.UsageError('You cannot delete servers from S3 endpoints.')
    if endpoint['is_globus_connect']:
        raise click.UsageError('You cannot delete servers from Globus Connect Personal endpoints')
    if mode != 'id':
        matches = _spec_to_matches(server_list, server, mode)
        if not matches:
            raise click.UsageError('No server was found matching "{}"'.format(server))
        elif len(matches) > 1:
            raise click.UsageError(dedent('                Multiple servers matched "{}":\n                    {}\n            ').format(server, [x['id'] for x in matches]))
