def safeprint(message, write_to_stderr=False, newline=True):
    """Wrapper around click.echo used to encapsulate its functionality.
    Also protects against EPIPE during click.echo calls, as this can happen
    normally in piped commands when the consumer closes before the producer."""
    try:
        click.echo(message, nl=newline, err=write_to_stderr)
    except IOError as err:
        if err.errno is errno.EPIPE:
            pass
        else:
            raise

def delete_and_rm_options(*args, **kwargs):
    """Options which apply both to `globus delete` and `globus rm`"""
    def inner_decorator(f, supports_batch=True, default_enable_globs=False):
        f = click.option('--recursive', '-r', is_flag=True, help='Recursively delete dirs')(f)
        f = click.option('--ignore-missing', '-f', is_flag=True, help="Don't throw errors if the file or dir is absent")(f)
        f = click.option('--star-silent', '--unsafe', 'star_silent', is_flag=True, help='Don\'t prompt when the trailing character is a "*".' + (' Implicit in --batch' if supports_batch else ''))(f)
        f = click.option('--enable-globs/--no-enable-globs', is_flag=True, default=default_enable_globs, show_default=True, help='Enable expansion of *, ?, and [ ] characters in the last component of file paths, unless they are escaped with a preceeding backslash, \\')(f)
        if supports_batch:
            f = click.option('--batch', is_flag=True, help='Accept a batch of paths on stdin (i.e. run in batchmode). Uses ENDPOINT_ID as passed on the commandline. Any commandline PATH given will be used as a prefix to all paths given')(f)
        return f
    return detect_and_decorate(inner_decorator, args, kwargs)

def version_option(f):
    """Largely a custom clone of click.version_option -- almost identical, but
    prints our special output."""
    def callback(ctx, param, value):
        if not value or ctx.resilient_parsing:
            return
        print_version()
        ctx.exit(0)
    return click.option('--version', is_flag=True, expose_value=False, is_eager=True, callback=callback, cls=HiddenOption)(f)

def get_versions():
    """Wrap in a function to ensure that we don't run this every time a CLI
    command runs (yuck!)

    Also protects import of `requests` from issues when grabbed by setuptools.
    More on that inline"""
    import requests
    try:
        version_data = requests.get('https://pypi.python.org/pypi/globus-cli/json').json()
        latest = max((LooseVersion(v) for v in version_data['releases']))
        return (latest, LooseVersion(__version__))
    except requests.RequestException:
        return (None, LooseVersion(__version__))

def write_option(option, value, section='cli', system=False):
    """Write an option to disk -- doesn't handle config reloading"""
    os.umask(63)
    conf = get_config_obj(system=system)
    if section not in conf:
        conf[section] = {}
    conf[section][option] = value
    conf.write()

def exit_with_mapped_status(http_status):
    """Given an HTTP Status, exit with either an error status of 1 or the
    status mapped by what we were given."""
    mapping = click.get_current_context().ensure_object(CommandState).http_status_map
    if http_status in mapping:
        sys.exit(mapping[http_status])
    else:
        sys.exit(1)

