def _safe_db(num, den):
    """Properly handle the potential +Inf db SIR instead of raising a
    RuntimeWarning."""
    if den == 0:
        return np.inf
    return 10 * np.log10(num / den)

def parse_link_value(instr):
    """Given a link-value (i.e., after separating the header-value on commas),
    return a dictionary whose keys are link URLs and values are dictionaries
    of the parameters for their associated links.

    Note that internationalised parameters (e.g., title*) are
    NOT percent-decoded.

    Also, only the last instance of a given parameter will be included.

    For example,

    >>> parse_link_value('</foo>; rel="self"; title*=utf-8'de'letztes%20Kapitel')
    {'/foo': {'title*': "utf-8'de'letztes%20Kapitel", 'rel': 'self'}}"""
    out = {}
    if not instr:
        return out
    for link in [h.strip() for h in link_splitter.findall(instr)]:
        url, params = link.split('>', 1)
        url = url[1:]
        param_dict = {}
        for param in _splitstring(params, PARAMETER, '\\s*;\\s*'):
            try:
                a, v = param.split('=', 1)
                param_dict[a.lower()] = _unquotestring(v)
            except ValueError:
                param_dict[param.lower()] = None
        out[url] = param_dict
    return out

def pdf_merge(inputs: [str], output: str, delete: bool=False):
    """Merge multiple Pdf input files in one output file.
    :param inputs: input files
    :param output: output file
    :param delete: delete input files after completion if true"""
    writer = PdfFileWriter()
    if os.path.isfile(output):
        ans = input("The file '%s' already exists. Overwrite? Yes/Abort [Y/a]: " % output).lower()
        if ans == 'a':
            return
    outputfile = open(output, 'wb')
    try:
        infiles = []
        for filename in inputs:
            f = open(filename, 'rb')
            reader = PdfFileReader(f)
            for page in reader.pages:
                writer.addPage(page)
            infiles.append(f)
        writer.write(outputfile)
    except FileNotFoundError as e:
        print(e.strerror + ': ' + e.filename)
    finally:
        outputfile.close()
        for f in infiles:
            f.close()
    if delete:
        for filename in inputs:
            os.remove(filename)

def pdf_rotate(input: str, counter_clockwise: bool=False, pages: [str]=None, output: str=None):
    """Rotate the given Pdf files clockwise or counter clockwise.
    :param inputs: pdf files
    :param counter_clockwise: rotate counter clockwise if true else clockwise
    :param pages: list of page numbers to rotate, if None all pages will be
        rotated"""
    infile = open(input, 'rb')
    reader = PdfFileReader(infile)
    writer = PdfFileWriter()
    if pages is None:
        source_pages = reader.pages
    else:
        pages = parse_rangearg(pages, len(reader.pages))
        source_pages = [reader.getPage(i) for i in pages]
    for i, page in enumerate(source_pages):
        if pages is None or i in pages:
            if counter_clockwise:
                writer.addPage(page.rotateCounterClockwise(90))
            else:
                writer.addPage(page.rotateClockwise(90))
        else:
            writer.addPage(page)
    if output is None:
        outfile = NamedTemporaryFile(delete=False)
    elif not os.path.isfile(output) or overwrite_dlg(output):
        outfile = open(output, 'wb')
    else:
        return
    writer.write(outfile)
    infile.close()
    outfile.close()
    if output is None:
        if overwrite_dlg(input):
            os.remove(input)
            move(outfile.name, input)
        else:
            os.remove(outfile.name)

def pdf_remove(source: str, pages: [str], output: str=None):
    """Remove pages from a PDF source file.
    :param source: pdf source file
    :param pages: list of page numbers or range expressions
    :param output: pdf output file"""
    if output is not None and os.path.isfile(output):
        if overwrite_dlg(output) is False:
            return
    writer = PdfFileWriter()
    srcfile = open(source, 'rb')
    srcreader = PdfFileReader(srcfile)
    pages = parse_rangearg(pages, len(srcreader.pages))
    for pagenr, page in enumerate(srcreader.pages):
        if pagenr not in pages:
            writer.addPage(page)
    if output is None:
        outfile = NamedTemporaryFile(delete=False)
    else:
        outfile = open(output, 'wb')
    writer.write(outfile)
    srcfile.close()
    outfile.close()
    if output is None:
        if overwrite_dlg(source):
            os.remove(source)
            move(outfile.name, source)
        else:
            os.remove(outfile)

def build_command(chunks):
    """Create a command from various parts.

    The parts provided may include a base, flags, option-bound arguments, and
    positional arguments. Each element must be either a string or a two-tuple.
    Raw strings are interpreted as either the command base, a pre-joined
    pair (or multiple pairs) of option and argument, a series of positional
    arguments, or a combination of those elements. The only modification they
    undergo is trimming of any space characters from each end.

    :param Iterable[str | (str, str | NoneType)] chunks: the collection of the
        command components to interpret, modify, and join to create a
        single meaningful command
    :return str: the single meaningful command built from the given components
    :raise ValueError: if no command parts are provided"""
    if not chunks:
        raise ValueError('No command parts: {} ({})'.format(chunks, type(chunks)))
    if isinstance(chunks, str):
        return chunks
    parsed_pieces = []
    for cmd_part in chunks:
        if cmd_part is None:
            continue
        try:
            parsed_pieces.append(cmd_part.strip(' '))
        except AttributeError:
            option, argument = cmd_part
            if argument is None or argument == '':
                continue
            option, argument = (option.strip(' '), str(argument).strip(' '))
            parsed_pieces.append('{} {}'.format(option, argument))
    return ' '.join(parsed_pieces)

def build_sample_paths(sample):
    """Ensure existence of folders for a Sample.

    :param looper.models.Sample sample: Sample (or instance supporting get()
        that stores folders paths in a 'paths' key, in which the value is a
        mapping from path name to actual folder path)"""
    for path_name, path in sample.paths.items():
        print("{}: '{}'".format(path_name, path))
        base, ext = os.path.splitext(path)
        if ext:
            print("Skipping file-like: '[}'".format(path))
        elif not os.path.isdir(base):
            os.makedirs(base)

def checkpoint_filepath(checkpoint, pm):
    """Create filepath for indicated checkpoint.

    :param str | pypiper.Stage checkpoint: Pipeline phase/stage or one's name
    :param pypiper.PipelineManager | pypiper.Pipeline pm: manager of a pipeline
        instance, relevant for output folder path.
    :return str: standardized checkpoint name for file, plus extension
    :raise ValueError: if the checkpoint is given as absolute path that does
        not point within pipeline output folder"""
    if isinstance(checkpoint, str):
        if os.path.isabs(checkpoint):
            if is_in_file_tree(checkpoint, pm.outfolder):
                return checkpoint
            else:
                raise ValueError("Absolute checkpoint path '{}' is not in pipeline output folder '{}'".format(checkpoint, pm.outfolder))
        _, ext = os.path.splitext(checkpoint)
        if ext == CHECKPOINT_EXTENSION:
            return pipeline_filepath(pm, filename=checkpoint)
    try:
        pm = pm.manager
    except AttributeError:
        pass
    chkpt_name = checkpoint_filename(checkpoint, pipeline_name=pm.name)
    return pipeline_filepath(pm, filename=chkpt_name)

def check_shell_redirection(cmd):
    """Determine whether a command appears to contain shell redirection symbol outside of curly brackets

    :param str cmd: Command to investigate.
    :return bool: Whether the command appears to contain shell redirection."""
    curly_brackets = True
    while curly_brackets:
        SRE_match_obj = re.search('\\{(.*?)}', cmd)
        if SRE_match_obj is not None:
            cmd = cmd[:SRE_match_obj.start()] + cmd[SRE_match_obj.end() + 1:]
            if re.search('\\{(.*?)}', cmd) is None:
                curly_brackets = False
        else:
            curly_brackets = False
    return '>' in cmd

def get_proc_name(cmd):
    """Get the representative process name from complex command

    :param str | list[str] cmd: a command to be processed
    :return str: the basename representative command"""
    if isinstance(cmd, Iterable) and (not isinstance(cmd, str)):
        cmd = ' '.join(cmd)
    return cmd.split()[0].replace('(', '').replace(')', '')

def is_gzipped_fastq(file_name):
    """Determine whether indicated file appears to be a gzipped FASTQ.

    :param str file_name: Name/path of file to check as gzipped FASTQ.
    :return bool: Whether indicated file appears to be in gzipped FASTQ format."""
    _, ext = os.path.splitext(file_name)
    return file_name.endswith('.fastq.gz') or file_name.endswith('.fq.gz')

def make_lock_name(original_path, path_base_folder):
    """Create name for lock file from an absolute path.

    The original path must be absolute, and it should point to a location
    within the location indicated by the base folder path provided. This is
    particularly useful for deleting a sample's output folder path from
    within the path of a target file to generate a lock file corresponding
    to the original target.

    :param str original_path: Full original filepath.
    :param str path_base_folder: Portion of original path to delete
    :return str: Name or perhaps relative (to the base folder path indicated)
        path to lock file"""
    def make_name(p):
        return p.replace(path_base_folder, '').replace(os.sep, '__')
    if isinstance(original_path, str):
        return make_name(original_path)
    elif isinstance(original_path, Sequence):
        return [make_name(p) for p in original_path]
    raise TypeError('Neither string nor other sequence type: {} ({})'.format(original_path, type(original_path)))

def is_multi_target(target):
    """Determine if pipeline manager's run target is multiple.

    :param None or str or Sequence of str target: 0, 1, or multiple targets
    :return bool: Whether there are multiple targets
    :raise TypeError: if the argument is neither None nor string nor Sequence"""
    if target is None or isinstance(target, str):
        return False
    elif isinstance(target, Sequence):
        return len(target) > 1
    else:
        raise TypeError('Could not interpret argument as a target: {} ({})'.format(target, type(target)))

def parse_stage_name(stage):
    """Determine the name of a stage.

    The stage may be provided already as a name, as a Stage object, or as a
    callable with __name__ (e.g., function).

    :param str | pypiper.Stage | function stage: Object representing a stage,
        from which to obtain name.
    :return str: Name of putative pipeline Stage."""
    if isinstance(stage, str):
        return stage
    try:
        return stage.name
    except AttributeError:
        try:
            return stage.__name__
        except AttributeError:
            raise TypeError('Unsupported stage type: {}'.format(type(stage)))

def _parse_stage_spec(stage_spec):
    """Handle alternate Stage specifications, returning name and Stage.

    Isolate this parsing logic from any iteration. TypeError as single
    exception type funnel also provides a more uniform way for callers to
    handle specification errors (e.g., skip a stage, warn, re-raise, etc.)

    :param (str, pypiper.Stage) | callable stage_spec: name and Stage
    :return (name, pypiper.Stage): Pair of name and Stage instance from parsing
        input specification
    :raise TypeError: if the specification of the stage is not a supported type"""
    req_msg = 'Stage specification must be either a {0} itself, a (<name>, {0}) pair, or a callable with a __name__ attribute (e.g., a non-anonymous function)'.format(Stage.__name__)
    if isinstance(stage_spec, Stage):
        return (stage_spec.name, stage_spec)
    try:
        name, stage = stage_spec
    except (TypeError, ValueError):
        try:
            name = stage_spec.__name__
        except AttributeError:
            raise TypeError(req_msg)
        else:
            if name == (lambda: None).__name__:
                raise TypeError(req_msg)
        stage = stage_spec
    if not hasattr(stage, '__call__'):
        raise TypeError(req_msg)
    return (name, Stage(stage, name=name))

def to_designspace_instances(self):
    """Write instance data from self.font to self.designspace."""
    for instance in self.font.instances:
        if self.minimize_glyphs_diffs or (is_instance_active(instance) and _is_instance_included_in_family(self, instance)):
            _to_designspace_instance(self, instance)

def to_ufo_components(self, ufo_glyph, layer):
    """Draw .glyphs components onto a pen, adding them to the parent glyph."""
    pen = ufo_glyph.getPointPen()
    for index, component in enumerate(layer.components):
        pen.addComponent(component.name, component.transform)
        if component.anchor:
            if COMPONENT_INFO_KEY not in ufo_glyph.lib:
                ufo_glyph.lib[COMPONENT_INFO_KEY] = []
            ufo_glyph.lib[COMPONENT_INFO_KEY].append({'name': component.name, 'index': index, 'anchor': component.anchor})
    for key in ['alignment', 'locked', 'smartComponentValues']:
        values = [getattr(c, key) for c in layer.components]
        if any(values):
            ufo_glyph.lib[_lib_key(key)] = values

def to_ufo_paths(self, ufo_glyph, layer):
    """Draw .glyphs paths onto a pen."""
    pen = ufo_glyph.getPointPen()
    for path in layer.paths:
        nodes = list(path.nodes)
        for node in nodes:
            self.to_ufo_node_user_data(ufo_glyph, node)
        pen.beginPath()
        if not nodes:
            pen.endPath()
            continue
        if not path.closed:
            node = nodes.pop(0)
            assert node.type == 'line', 'Open path starts with off-curve points'
            pen.addPoint(tuple(node.position), segmentType='move')
        else:
            nodes.insert(0, nodes.pop())
        for node in nodes:
            node_type = _to_ufo_node_type(node.type)
            pen.addPoint(tuple(node.position), segmentType=node_type, smooth=node.smooth)
        pen.endPath()

def request_cached_property(func):
    """Make the given method a per-request cached property.

    This caches the value on the request context rather than on the object
    itself, preventing problems if the object gets reused across multiple
    requests."""
    @property
    @functools.wraps(func)
    def wrapped(self):
        cached_value = context.get_for_view(self, func.__name__, UNDEFINED)
        if cached_value is not UNDEFINED:
            return cached_value
        value = func(self)
        context.set_for_view(self, func.__name__, value)
        return value
    return wrapped

def _ufo_logging_ref(ufo):
    """Return a string that can identify this UFO in logs."""
    if ufo.path:
        return os.path.basename(ufo.path)
    return ufo.info.styleName

def parse_color(src=None):
    """Parse a string representing a color value.

    Color is either a fixed color (when coloring something from the UI, see
    the GLYPHS_COLORS constant) or a list of the format [u8, u8, u8, u8],

    Glyphs does not support an alpha channel as of 2.5.1 (confirmed by Georg
    Seifert), and always writes a 1 to it. This was brought up and is probably
    corrected in the next versions.
    https://github.com/googlei18n/glyphsLib/pull/363#issuecomment-390418497"""
    if src is None:
        return None
    if src[0] == '(':
        rgba = tuple((int(v) for v in src[1:-1].split(',') if v))
        if not (len(rgba) == 4 and all((0 <= v < 256 for v in rgba))):
            raise ValueError('Broken color tuple: {}. Must have four values from 0 to 255.'.format(src))
        return rgba
    return int(src)

def main(args=None):
    """Roundtrip the .glyphs file given as an argument."""
    for arg in args:
        glyphsLib.dump(load(open(arg, 'r', encoding='utf-8')), sys.stdout)

def build_ufo_path(out_dir, family_name, style_name):
    """Build string to use as a UFO path."""
    return os.path.join(out_dir, '%s-%s.ufo' % ((family_name or '').replace(' ', ''), (style_name or '').replace(' ', '')))

def clean_ufo(path):
    """Make sure old UFO data is removed, as it may contain deleted glyphs."""
    if path.endswith('.ufo') and os.path.exists(path):
        shutil.rmtree(path)

def ufo_create_background_layer_for_all_glyphs(ufo_font):
    """Create a background layer for all glyphs in ufo_font if not present to
    reduce roundtrip differences."""
    if 'public.background' in ufo_font.layers:
        background = ufo_font.layers['public.background']
    else:
        background = ufo_font.newLayer('public.background')
    for glyph in ufo_font:
        if glyph.name not in background:
            background.newGlyph(glyph.name)

def cast_to_number_or_bool(inputstr):
    """Cast a string to int, float or bool. Return original string if it can't be
    converted.

    Scientific expression is converted into float."""
    if inputstr.strip().lower() == 'true':
        return True
    elif inputstr.strip().lower() == 'false':
        return False
    try:
        return int(inputstr)
    except ValueError:
        try:
            return float(inputstr)
        except ValueError:
            return inputstr

def to_glyphs_background_image(self, ufo_glyph, layer):
    """Copy the background image from the UFO Glyph to the GSLayer."""
    ufo_image = ufo_glyph.image
    if ufo_image.fileName is None:
        return
    image = self.glyphs_module.GSBackgroundImage()
    image.path = ufo_image.fileName
    image.transform = Transform(*ufo_image.transformation)
    if CROP_KEY in ufo_glyph.lib:
        x, y, w, h = ufo_glyph.lib[CROP_KEY]
        image.crop = Rect(Point(x, y), Size(w, h))
    if LOCKED_KEY in ufo_glyph.lib:
        image.locked = ufo_glyph.lib[LOCKED_KEY]
    if ALPHA_KEY in ufo_glyph.lib:
        image.alpha = ufo_glyph.lib[ALPHA_KEY]
    layer.backgroundImage = image

def to_ufo_guidelines(self, ufo_obj, glyphs_obj):
    """Set guidelines."""
    guidelines = glyphs_obj.guides
    if not guidelines:
        return
    new_guidelines = []
    for guideline in guidelines:
        new_guideline = {}
        x, y = guideline.position
        angle = guideline.angle % 360
        if _is_vertical(x, y, angle):
            new_guideline['x'] = x
        elif _is_horizontal(x, y, angle):
            new_guideline['y'] = y
        else:
            new_guideline['x'] = x
            new_guideline['y'] = y
            new_guideline['angle'] = angle
        name = guideline.name
        if name is not None:
            m = IDENTIFIER_NAME_RE.match(name)
            if m:
                new_guideline['identifier'] = m.group(2)
                name = name[:-len(m.group(1))]
            m = COLOR_NAME_RE.match(name)
            if m:
                new_guideline['color'] = m.group(2)
                name = name[:-len(m.group(1))]
        if guideline.locked:
            name = (name or '') + LOCKED_NAME_SUFFIX
        if name:
            new_guideline['name'] = name
        new_guidelines.append(new_guideline)
    ufo_obj.guidelines = new_guidelines

def to_glyphs_guidelines(self, ufo_obj, glyphs_obj):
    """Set guidelines."""
    if not ufo_obj.guidelines:
        return
    for guideline in ufo_obj.guidelines:
        new_guideline = self.glyphs_module.GSGuideLine()
        name = guideline.name
        if name is not None and name.endswith(LOCKED_NAME_SUFFIX):
            name = name[:-len(LOCKED_NAME_SUFFIX)]
            new_guideline.locked = True
        if guideline.color:
            name = (name or '') + COLOR_NAME_SUFFIX % str(guideline.color)
        if guideline.identifier:
            name = (name or '') + IDENTIFIER_NAME_SUFFIX % guideline.identifier
        new_guideline.name = name
        new_guideline.position = Point(guideline.x or 0, guideline.y or 0)
        if guideline.angle is not None:
            new_guideline.angle = guideline.angle % 360
        elif _is_vertical(guideline.x, guideline.y, None):
            new_guideline.angle = 90
        glyphs_obj.guides.append(new_guideline)

def _to_ufo_kerning(self, ufo, kerning_data):
    """Add .glyphs kerning to an UFO."""
    warning_msg = 'Non-existent glyph class %s found in kerning rules.'
    for left, pairs in kerning_data.items():
        match = re.match('@MMK_L_(.+)', left)
        left_is_class = bool(match)
        if left_is_class:
            left = 'public.kern1.%s' % match.group(1)
            if left not in ufo.groups:
                self.logger.warning(warning_msg % left)
        for right, kerning_val in pairs.items():
            match = re.match('@MMK_R_(.+)', right)
            right_is_class = bool(match)
            if right_is_class:
                right = 'public.kern2.%s' % match.group(1)
                if right not in ufo.groups:
                    self.logger.warning(warning_msg % right)
            ufo.kerning[left, right] = kerning_val

def to_glyphs_kerning(self):
    """Add UFO kerning to GSFont."""
    for master_id, source in self._sources.items():
        for (left, right), value in source.font.kerning.items():
            left_match = UFO_KERN_GROUP_PATTERN.match(left)
            right_match = UFO_KERN_GROUP_PATTERN.match(right)
            if left_match:
                left = '@MMK_L_{}'.format(left_match.group(2))
            if right_match:
                right = '@MMK_R_{}'.format(right_match.group(2))
            self.font.setKerningForPair(master_id, left, right, value)

def _set_default_params(ufo):
    """Set Glyphs.app's default parameters when different from ufo2ft ones.
    """
    for _, ufo_name, default_value in DEFAULT_PARAMETERS:
        if getattr(ufo.info, ufo_name) is None:
            if isinstance(default_value, list):
                default_value = default_value[:]
            setattr(ufo.info, ufo_name, default_value)

def _unset_default_params(glyphs):
    """Unset Glyphs.app's parameters that have default values.
    FIXME: (jany) maybe this should be taken care of in the writer? and/or
        classes should have better default values?"""
    for glyphs_name, _, default_value in DEFAULT_PARAMETERS:
        if glyphs_name in glyphs.customParameters and glyphs.customParameters[glyphs_name] == default_value:
            del glyphs.customParameters[glyphs_name]
        if glyphs_name in glyphs.customParameters and glyphs.customParameters[glyphs_name] == default_value:
            del glyphs.customParameters[glyphs_name]

def to_ufo_propagate_font_anchors(self, ufo):
    """Copy anchors from parent glyphs' components to the parent."""
    processed = set()
    for glyph in ufo:
        _propagate_glyph_anchors(self, ufo, glyph, processed)

def _propagate_glyph_anchors(self, ufo, parent, processed):
    """Propagate anchors for a single parent glyph."""
    if parent.name in processed:
        return
    processed.add(parent.name)
    base_components = []
    mark_components = []
    anchor_names = set()
    to_add = {}
    for component in parent.components:
        try:
            glyph = ufo[component.baseGlyph]
        except KeyError:
            self.logger.warning('Anchors not propagated for inexistent component {} in glyph {}'.format(component.baseGlyph, parent.name))
        else:
            _propagate_glyph_anchors(self, ufo, glyph, processed)
            if any((a.name.startswith('_') for a in glyph.anchors)):
                mark_components.append(component)
            else:
                base_components.append(component)
                anchor_names |= {a.name for a in glyph.anchors}
    for anchor_name in anchor_names:
        if not any((a.name.startswith(anchor_name) for a in parent.anchors)):
            _get_anchor_data(to_add, ufo, base_components, anchor_name)
    for component in mark_components:
        _adjust_anchors(to_add, ufo, component)
    for name, (x, y) in sorted(to_add.items()):
        anchor_dict = {'name': name, 'x': x, 'y': y}
        parent.appendAnchor(glyph.anchorClass(anchorDict=anchor_dict))

def _adjust_anchors(anchor_data, ufo, component):
    """Adjust anchors to which a mark component may have been attached."""
    glyph = ufo[component.baseGlyph]
    t = Transform(*component.transformation)
    for anchor in glyph.anchors:
        if anchor.name in anchor_data and any((a.name == '_' + anchor.name for a in glyph.anchors)):
            anchor_data[anchor.name] = t.transformPoint((anchor.x, anchor.y))

def to_ufo_glyph_anchors(self, glyph, anchors):
    """Add .glyphs anchors to a glyph."""
    for anchor in anchors:
        x, y = anchor.position
        anchor_dict = {'name': anchor.name, 'x': x, 'y': y}
        glyph.appendAnchor(anchor_dict)

def cached_property(func):
    """Special property decorator that caches the computed
    property value in the object's instance dict the first
    time it is accessed."""
    name = func.__name__
    doc = func.__doc__
    def getter(self, name=name):
        try:
            return self.__dict__[name]
        except KeyError:
            self.__dict__[name] = value = func(self)
            return value
    getter.func_name = name
    return property(getter, doc=doc)

def cos_sin_deg(deg):
    """Return the cosine and sin for the given angle
    in degrees, with special-case handling of multiples
    of 90 for perfect right angles"""
    deg = deg % 360.0
    if deg == 90.0:
        return (0.0, 1.0)
    elif deg == 180.0:
        return (-1.0, 0)
    elif deg == 270.0:
        return (0, -1.0)
    rad = math.radians(deg)
    return (math.cos(rad), math.sin(rad))

def _translate_category(glyph_name, unicode_category):
    """Return a translation from Unicode category letters to Glyphs
    categories."""
    DEFAULT_CATEGORIES = {None: ('Letter', None), 'Cc': ('Separator', None), 'Cf': ('Separator', 'Format'), 'Cn': ('Symbol', None), 'Co': ('Letter', 'Compatibility'), 'Ll': ('Letter', 'Lowercase'), 'Lm': ('Letter', 'Modifier'), 'Lo': ('Letter', None), 'Lt': ('Letter', 'Uppercase'), 'Lu': ('Letter', 'Uppercase'), 'Mc': ('Mark', 'Spacing Combining'), 'Me': ('Mark', 'Enclosing'), 'Mn': ('Mark', 'Nonspacing'), 'Nd': ('Number', 'Decimal Digit'), 'Nl': ('Number', None), 'No': ('Number', 'Decimal Digit'), 'Pc': ('Punctuation', None), 'Pd': ('Punctuation', 'Dash'), 'Pe': ('Punctuation', 'Parenthesis'), 'Pf': ('Punctuation', 'Quote'), 'Pi': ('Punctuation', 'Quote'), 'Po': ('Punctuation', None), 'Ps': ('Punctuation', 'Parenthesis'), 'Sc': ('Symbol', 'Currency'), 'Sk': ('Mark', 'Spacing'), 'Sm': ('Symbol', 'Math'), 'So': ('Symbol', None), 'Zl': ('Separator', None), 'Zp': ('Separator', None), 'Zs': ('Separator', 'Space')}
    glyphs_category = DEFAULT_CATEGORIES.get(unicode_category, ('Letter', None))
    if '_' in glyph_name and glyphs_category[0] != 'Mark':
        return (glyphs_category[0], 'Ligature')
    return glyphs_category

def load_to_ufos(file_or_path, include_instances=False, family_name=None, propagate_anchors=True):
    """Load an unpacked .glyphs object to UFO objects."""
    if hasattr(file_or_path, 'read'):
        font = load(file_or_path)
    else:
        with open(file_or_path, 'r', encoding='utf-8') as ifile:
            font = load(ifile)
    logger.info('Loading to UFOs')
    return to_ufos(font, include_instances=include_instances, family_name=family_name, propagate_anchors=propagate_anchors)

def glyphs2ufo(options):
    """Converts a Glyphs.app source file into UFO masters and a designspace file."""
    if options.output_dir is None:
        options.output_dir = os.path.dirname(options.glyphs_file) or '.'
    if options.designspace_path is None:
        options.designspace_path = os.path.join(options.output_dir, os.path.basename(os.path.splitext(options.glyphs_file)[0]) + '.designspace')
    glyphsLib.build_masters(options.glyphs_file, options.output_dir, options.instance_dir, designspace_path=options.designspace_path, minimize_glyphs_diffs=options.no_preserve_glyphsapp_metadata, propagate_anchors=options.propagate_anchors, normalize_ufos=options.normalize_ufos, create_background_layers=options.create_background_layers, generate_GDEF=options.generate_GDEF, store_editor_state=not options.no_store_editor_state)

def _has_manual_kern_feature(font):
    """Return true if the GSFont contains a manually written 'kern' feature."""
    return any((f for f in font.features if f.name == 'kern' and (not f.automatic)))

def to_ufo_family_user_data(self, ufo):
    """Set family-wide user data as Glyphs does."""
    if not self.use_designspace:
        ufo.lib[FONT_USER_DATA_KEY] = dict(self.font.userData)

def to_ufo_master_user_data(self, ufo, master):
    """Set master-specific user data as Glyphs does."""
    for key in master.userData.keys():
        if _user_data_has_no_special_meaning(key):
            ufo.lib[key] = master.userData[key]
    if UFO_DATA_KEY in master.userData:
        for filename, data in master.userData[UFO_DATA_KEY].items():
            ufo.data[filename] = bytes(data)

def to_glyphs_family_user_data_from_designspace(self):
    """Set the GSFont userData from the designspace family-wide lib data."""
    target_user_data = self.font.userData
    for key, value in self.designspace.lib.items():
        if key == UFO2FT_FEATURE_WRITERS_KEY and value == DEFAULT_FEATURE_WRITERS:
            continue
        if _user_data_has_no_special_meaning(key):
            target_user_data[key] = value

def to_glyphs_family_user_data_from_ufo(self, ufo):
    """Set the GSFont userData from the UFO family-wide lib data."""
    target_user_data = self.font.userData
    try:
        for key, value in ufo.lib[FONT_USER_DATA_KEY].items():
            if key not in target_user_data.keys():
                target_user_data[key] = value
    except KeyError:
        pass

def to_glyphs_master_user_data(self, ufo, master):
    """Set the GSFontMaster userData from the UFO master-specific lib data."""
    target_user_data = master.userData
    for key, value in ufo.lib.items():
        if _user_data_has_no_special_meaning(key):
            target_user_data[key] = value
    if ufo.data.fileNames:
        from glyphsLib.types import BinaryData
        ufo_data = {}
        for os_filename in ufo.data.fileNames:
            filename = posixpath.join(*os_filename.split(os.path.sep))
            ufo_data[filename] = BinaryData(ufo.data[os_filename])
        master.userData[UFO_DATA_KEY] = ufo_data

def class_to_value(axis, ufo_class):
    """>>> class_to_value('wdth', 7)
    125"""
    if axis == 'wght':
        return int(ufo_class)
    elif axis == 'wdth':
        return WIDTH_CLASS_TO_VALUE[int(ufo_class)]
    raise NotImplementedError

def user_loc_string_to_value(axis_tag, user_loc):
    """Go from Glyphs UI strings to user space location.
    Returns None if the string is invalid.

    >>> user_loc_string_to_value('wght', 'ExtraLight')
    200
    >>> user_loc_string_to_value('wdth', 'SemiCondensed')
    87.5
    >>> user_loc_string_to_value('wdth', 'Clearly Not From Glyphs UI')"""
    if axis_tag == 'wght':
        try:
            value = _nospace_lookup(WEIGHT_CODES, user_loc)
        except KeyError:
            return None
        return class_to_value('wght', value)
    elif axis_tag == 'wdth':
        try:
            value = _nospace_lookup(WIDTH_CODES, user_loc)
        except KeyError:
            return None
        return class_to_value('wdth', value)
    raise NotImplementedError

def user_loc_value_to_class(axis_tag, user_loc):
    """Return the OS/2 weight or width class that is closest to the provided
    user location. For weight the user location is between 0 and 1000 and for
    width it is a percentage.

    >>> user_loc_value_to_class('wght', 310)
    310
    >>> user_loc_value_to_class('wdth', 62)
    2"""
    if axis_tag == 'wght':
        return int(user_loc)
    elif axis_tag == 'wdth':
        return min(sorted(WIDTH_CLASS_TO_VALUE.items()), key=lambda item: abs(item[1] - user_loc))[0]
    raise NotImplementedError

def user_loc_value_to_instance_string(axis_tag, user_loc):
    """Return the Glyphs UI string (from the instance dropdown) that is
    closest to the provided user location.

    >>> user_loc_value_to_instance_string('wght', 430)
    'Normal'
    >>> user_loc_value_to_instance_string('wdth', 150)
    'Extra Expanded'"""
    codes = {}
    if axis_tag == 'wght':
        codes = WEIGHT_CODES
    elif axis_tag == 'wdth':
        codes = WIDTH_CODES
    else:
        raise NotImplementedError
    class_ = user_loc_value_to_class(axis_tag, user_loc)
    return min(sorted(((code, class_) for code, class_ in codes.items() if code is not None)), key=lambda item: abs(item[1] - class_))[0]

def get_regular_master(font):
    """Find the "regular" master among the GSFontMasters.

    Tries to find the master with the passed 'regularName'.
    If there is no such master or if regularName is None,
    tries to find a base style shared between all masters
    (defaulting to "Regular"), and then tries to find a master
    with that style name. If there is no master with that name,
    returns the first master in the list."""
    if not font.masters:
        return None
    regular_name = font.customParameters['Variation Font Origin']
    if regular_name is not None:
        for master in font.masters:
            if master.name == regular_name:
                return master
    base_style = find_base_style(font.masters)
    if not base_style:
        base_style = 'Regular'
    for master in font.masters:
        if master.name == base_style:
            return master
    for master in font.masters:
        name_without_regular = ' '.join((n for n in master.name.split(' ') if n != 'Regular'))
        if name_without_regular == base_style:
            return master
    return font.masters[0]

def interp(mapping, x):
    """Compute the piecewise linear interpolation given by mapping for input x.

    >>> interp(((1, 1), (2, 4)), 1.5)
    2.5"""
    mapping = sorted(mapping)
    if len(mapping) == 1:
        xa, ya = mapping[0]
        if xa == x:
            return ya
        return x
    for (xa, ya), (xb, yb) in zip(mapping[:-1], mapping[1:]):
        if xa <= x <= xb:
            return ya + float(x - xa) / (xb - xa) * (yb - ya)
    return x

