def MakeCdfFromPmf(pmf, name=None):
    """Makes a CDF from a Pmf object.

    Args:
       pmf: Pmf.Pmf object
       name: string name for the data.

    Returns:
        Cdf object"""
    if name == None:
        name = pmf.name
    return MakeCdfFromItems(pmf.Items(), name)

def Percentile(pmf, percentage):
    """Computes a percentile of a given Pmf.

    percentage: float 0-100"""
    p = percentage / 100.0
    total = 0
    for val, prob in pmf.Items():
        total += prob
        if total >= p:
            return val

def PmfProbLess(pmf1, pmf2):
    """Probability that a value from pmf1 is less than a value from pmf2.

    Args:
        pmf1: Pmf object
        pmf2: Pmf object

    Returns:
        float probability"""
    total = 0.0
    for v1, p1 in pmf1.Items():
        for v2, p2 in pmf2.Items():
            if v1 < v2:
                total += p1 * p2
    return total

def EvalBinomialPmf(k, n, p):
    """Evaluates the binomial pmf.

    Returns the probabily of k successes in n trials with probability p."""
    return scipy.stats.binom.pmf(k, n, p)

def EvalPoissonPmf(k, lam):
    """Computes the Poisson PMF.

    k: number of events
    lam: parameter lambda in events per unit time

    returns: float probability"""
    return lam ** k * math.exp(-lam) / math.factorial(k)

def _get_ann(dbs, features):
    """Gives format to annotation for html table output"""
    value = ''
    for db, feature in zip(dbs, features):
        value += db + ':' + feature
    return value

def _expand(dat, counts, start, end):
    """expand the same counts from start to end"""
    for pos in range(start, end):
        for s in counts:
            dat[s][pos] += counts[s]
    return dat

def _convert_to_df(in_file, freq, raw_file):
    """convert data frame into table with pandas"""
    dat = defaultdict(Counter)
    if isinstance(in_file, (str, unicode)):
        with open(in_file) as in_handle:
            for line in in_handle:
                cols = line.strip().split('\t')
                counts = freq[cols[3]]
                dat = _expand(dat, counts, int(cols[1]), int(cols[2]))
    else:
        if raw_file:
            out_handle = open(raw_file, 'w')
        for name in in_file:
            counts = freq[name]
            if raw_file:
                print('%s\t%s\t%s\t%s\t%s\t%s' % ('chr', in_file[name][0], in_file[name][1], name, sum(counts.values()), '+'), file=out_handle, end='')
            dat = _expand(dat, counts, in_file[name][0], in_file[name][1])
    for s in dat:
        for p in dat[s]:
            dat[s][p] = mlog2(dat[s][p] + 1)
    return dat

def _make(c):
    """create html from template, adding figure,
    annotation and sequences counts"""
    ann = defaultdict(list)
    for pos in c['ann']:
        for db in pos:
            ann[db] += list(pos[db])
    logger.debug(ann)
    valid = [l for l in c['valid']]
    ann_list = [', '.join(list(set(ann[feature]))) for feature in ann if feature in valid]
    return (valid, ann_list)

def _single_cluster(c, data, out_file, args):
    """Map sequences on precursors and create
    expression profile"""
    valid, ann = (0, 0)
    raw_file = None
    freq = defaultdict()
    [freq.update({s.keys()[0]: s.values()[0]}) for s in data[0][c]['freq']]
    names = [s.keys()[0] for s in data[0][c]['seqs']]
    seqs = [s.values()[0] for s in data[0][c]['seqs']]
    loci = data[0][c]['loci']
    if loci[0][3] - loci[0][2] > 500:
        logger.info('locus bigger > 500 nt, skipping: %s' % loci)
        return (valid, ann, {})
    if not file_exists(out_file):
        if args.razer:
            logger.debug('map with razer all sequences to all loci %s ' % loci)
            map_to_precursors(seqs, names, {loci[0][0]: [loci[0][0:5]]}, out_file, args)
        else:
            logger.debug('map with biopython fn all sequences to all loci %s ' % loci)
            if args.debug:
                raw_file = out_file
            out_file = map_to_precursor_biopython(seqs, names, loci[0][0:5], args)
    logger.debug('plot sequences on loci')
    df = _convert_to_df(out_file, freq, raw_file)
    if df:
        valid, ann = _make(data[0][c])
    return (valid, ann, df)

def get_sequences_from_cluster(c1, c2, data):
    """get all sequences from on cluster"""
    seqs1 = data[c1]['seqs']
    seqs2 = data[c2]['seqs']
    seqs = list(set(seqs1 + seqs2))
    names = []
    for s in seqs:
        if s in seqs1 and s in seqs2:
            names.append('both')
        elif s in seqs1:
            names.append(c1)
        else:
            names.append(c2)
    return (seqs, names)

def map_to_precursors_on_fly(seqs, names, loci, args):
    """map sequences to precursors with franpr algorithm to avoid writting on disk"""
    precursor = precursor_sequence(loci, args.ref).upper()
    dat = dict()
    for s, n in itertools.izip(seqs, names):
        res = pyMatch.Match(precursor, str(s), 1, 3)
        if res > -1:
            dat[n] = [res, res + len(s)]
    logger.debug('mapped in %s: %s out of %s' % (loci, len(dat), len(seqs)))
    return dat

def _align(x, y, local=False):
    """https://medium.com/towards-data-science/pairwise-sequence-alignment-using-biopython-d1a9d0ba861f"""
    if local:
        aligned_x = pairwise2.align.localxx(x, y)
    else:
        aligned_x = pairwise2.align.globalms(x, y, 1, -1, -1, -0.5)
    if aligned_x:
        sorted_alignments = sorted(aligned_x, key=operator.itemgetter(2))
        e = enumerate(sorted_alignments[0][0])
        nts = [i for i, c in e if c != '-']
        return [min(nts), max(nts)]

def map_to_precursor_biopython(seqs, names, loci, args):
    """map the sequences using biopython package"""
    precursor = precursor_sequence(loci, args.ref).upper()
    dat = dict()
    for s, n in itertools.izip(seqs, names):
        res = _align(str(s), precursor)
        if res:
            dat[n] = res
    logger.debug('mapped in %s: %s out of %s' % (loci, len(dat), len(seqs)))
    return dat

def get_seqs_fasta(seqs, names, out_fa):
    """get fasta from sequences"""
    with open(out_fa, 'w') as fa_handle:
        for s, n in itertools.izip(seqs, names):
            print('>cx{1}-{0}\n{0}'.format(s, n), file=fa_handle)
    return out_fa

def read_alignment(out_sam, loci, seqs, out_file):
    """read which seqs map to which loci and
    return a tab separated file"""
    hits = defaultdict(list)
    with open(out_file, 'w') as out_handle:
        samfile = pysam.Samfile(out_sam, 'r')
        for a in samfile.fetch():
            if not a.is_unmapped:
                nm = int([t[1] for t in a.tags if t[0] == 'NM'][0])
                a = makeBED(a)
                if not a:
                    continue
                ref, locus = get_loci(samfile.getrname(int(a.chr)), loci)
                hits[a.name].append((nm, '%s %s %s %s %s %s' % (a.name, a.name.split('-')[0], locus, ref, a.start, a.end)))
        for hit in hits.values():
            nm = hit[0][0]
            for l in hit:
                if nm == l[0]:
                    print(l[1], file=out_handle)
    return out_file

