def print_err(*args, **kwargs):
    """A wrapper for print() that uses stderr by default."""
    if kwargs.get('file', None) is None:
        kwargs['file'] = sys.stderr
    print(*args, **kwargs)

def _coloredhelp(s):
    """Colorize the usage string for docopt
    (ColorDocoptExit, docoptextras)"""
    newlines = []
    bigindent = ' ' * 16
    in_opts = False
    for line in s.split('\n'):
        linestripped = line.strip('\n').strip().strip(':')
        if linestripped == 'Usage':
            line = line.replace('Usage', str(C('Usage', **ARGS_LABEL)))
        elif linestripped == 'Options':
            line = line.replace('Options', str(C('Options', **ARGS_LABEL)))
            in_opts = True
        elif ':' in line and (not line.startswith(bigindent)):
            lineparts = line.split(':')
            opt = lineparts[0]
            vals = [lineparts[1]] if len(lineparts) == 2 else lineparts[1:]
            if ',' in opt:
                opts = opt.split(',')
            else:
                opts = [opt]
            optstr = ','.join((str(C(o, **ARGS_OPTIONS)) for o in opts))
            valstr = ':'.join((str(C(val, **ARGS_DESC)) for val in vals))
            line = ':'.join((optstr, valstr))
        elif in_opts and line.startswith(bigindent):
            line = ':'.join((str(C(s, **ARGS_DESC)) for s in line.split(':')))
        elif not line.startswith('    '):
            line = str(C(line, **ARGS_HEADER))
        elif SCRIPT:
            line = line.replace(SCRIPT, str(C(SCRIPT, **ARGS_SCRIPT)))
        newlines.append('{}{}'.format(line, C('', style='reset_all')))
    return '\n'.join(newlines)

def cls_get_by_name(cls, name):
    """Return a class attribute by searching the attributes `name` attribute.
    """
    try:
        val = getattr(cls, name)
    except AttributeError:
        for attr in (a for a in dir(cls) if not a.startswith('_')):
            try:
                val = getattr(cls, attr)
            except AttributeError:
                continue
            valname = getattr(val, 'name', None)
            if valname == name:
                return val
        else:
            raise ValueError('No {} with that name: {}'.format(cls.__name__, name))
    else:
        return val

def cls_sets(cls, wanted_cls, registered=True):
    """Return a list of all `wanted_cls` attributes in this
    class, where `wanted_cls` is the desired attribute type."""
    sets = []
    for attr in dir(cls):
        if attr.startswith('_'):
            continue
        val = getattr(cls, attr, None)
        if not isinstance(val, wanted_cls):
            continue
        if not registered and getattr(val, '_registered', False):
            continue
        sets.append(val)
    return sets

def _build_color_variants(cls):
    """Build colorized variants of all frames and return a list of
    all frame object names."""
    frametypes = cls.sets(registered=False)
    _colornames = ['red', 'green', 'yellow', 'blue', 'magenta', 'cyan', 'white']
    _colornames.extend(('light{}'.format(s) for s in _colornames[:]))
    for colorname in _colornames:
        for framesobj in frametypes:
            framename = '{}_{}'.format(framesobj.name, colorname)
            cls.register(framesobj.as_colr(fore=colorname), name=framename)

def parse_dbus_address(address):
    """Parse a D-BUS address string into a list of addresses."""
    if address == 'session':
        address = os.environ.get('DBUS_SESSION_BUS_ADDRESS')
        if not address:
            raise ValueError('$DBUS_SESSION_BUS_ADDRESS not set')
    elif address == 'system':
        address = os.environ.get('DBUS_SYSTEM_BUS_ADDRESS', 'unix:path=/var/run/dbus/system_bus_socket')
    addresses = []
    for addr in address.split(';'):
        p1 = addr.find(':')
        if p1 == -1:
            raise ValueError('illegal address string: {}'.format(addr))
        kind = addr[:p1]
        args = dict((kv.split('=') for kv in addr[p1 + 1:].split(',')))
        if kind == 'unix':
            if 'path' in args:
                addr = args['path']
            elif 'abstract' in args:
                addr = '\x00' + args['abstract']
            else:
                raise ValueError('require "path" or "abstract" for unix')
        elif kind == 'tcp':
            if 'host' not in args or 'port' not in args:
                raise ValueError('require "host" and "port" for tcp')
            addr = (args['host'], int(args['port']))
        else:
            raise ValueError('unknown transport: {}'.format(kind))
        addresses.append(addr)
    return addresses

def parse_dbus_header(header):
    """Parse a D-BUS header. Return the message size."""
    if six.indexbytes(header, 0) == ord('l'):
        endian = '<'
    elif six.indexbytes(header, 0) == ord('B'):
        endian = '>'
    else:
        raise ValueError('illegal endianness')
    if not 1 <= six.indexbytes(header, 1) <= 4:
        raise ValueError('illegel message type')
    if struct.unpack(endian + 'I', header[8:12])[0] == 0:
        raise ValueError('illegal serial number')
    harrlen = struct.unpack(endian + 'I', header[12:16])[0]
    padlen = (8 - harrlen) % 8
    bodylen = struct.unpack(endian + 'I', header[4:8])[0]
    return 16 + harrlen + padlen + bodylen

def docfrom(base):
    """Decorator to set a function's docstring from another function."""
    def setdoc(func):
        func.__doc__ = (getattr(base, '__doc__') or '') + (func.__doc__ or '')
        return func
    return setdoc

def accept_ws(buf, pos):
    """Skip whitespace at the current buffer position."""
    match = re_ws.match(buf, pos)
    if not match:
        return (None, pos)
    return (buf[match.start(0):match.end(0)], match.end(0))

def accept_lit(char, buf, pos):
    """Accept a literal character at the current buffer position."""
    if pos >= len(buf) or buf[pos] != char:
        return (None, pos)
    return (char, pos + 1)

def expect_lit(char, buf, pos):
    """Expect a literal character at the current buffer position."""
    if pos >= len(buf) or buf[pos] != char:
        return (None, len(buf))
    return (char, pos + 1)

def accept_re(regexp, buf, pos):
    """Accept a regular expression at the current buffer position."""
    match = regexp.match(buf, pos)
    if not match:
        return (None, pos)
    return (buf[match.start(1):match.end(1)], match.end(0))

def expect_re(regexp, buf, pos):
    """Require a regular expression at the current buffer position."""
    match = regexp.match(buf, pos)
    if not match:
        return (None, len(buf))
    return (buf[match.start(1):match.end(1)], match.end(0))

def parse_content_type(header):
    """Parse the "Content-Type" header."""
    typ = subtyp = None
    options = {}
    typ, pos = expect_re(re_token, header, 0)
    _, pos = expect_lit('/', header, pos)
    subtyp, pos = expect_re(re_token, header, pos)
    ctype = header[:pos] if subtyp else ''
    while pos < len(header):
        _, pos = accept_ws(header, pos)
        _, pos = expect_lit(';', header, pos)
        _, pos = accept_ws(header, pos)
        name, pos = expect_re(re_token, header, pos)
        _, pos = expect_lit('=', header, pos)
        char = lookahead(header, pos)
        if char == '"':
            value, pos = expect_re(re_qstring, header, pos)
            value = re_qpair.sub('\\1', value)
        elif char:
            value, pos = expect_re(re_token, header, pos)
        if name and value is not None:
            options[name] = value
    return (ctype, options)

def get_header(headers, name, default=None):
    """Return the value of header *name*.

    The *headers* argument must be a list of ``(name, value)`` tuples. If the
    header is found its associated value is returned, otherwise *default* is
    returned. Header names are matched case insensitively."""
    name = name.lower()
    for header in headers:
        if header[0].lower() == name:
            return header[1]
    return default

def remove_headers(headers, name):
    """Remove all headers with name *name*.

    The list is modified in-place and the updated list is returned."""
    i = 0
    name = name.lower()
    for j in range(len(headers)):
        if headers[j][0].lower() != name:
            if i != j:
                headers[i] = headers[j]
            i += 1
    del headers[i:]
    return headers

def create_chunked_body_end(trailers=None):
    """Create the ending that terminates a chunked body."""
    chunk = []
    chunk.append('0\r\n')
    if trailers:
        for name, value in trailers:
            chunk.append(name)
            chunk.append(': ')
            chunk.append(value)
            chunk.append('\r\n')
    chunk.append('\r\n')
    return s2b(''.join(chunk))

def read(filename: str, limit: Optional[int]=None) -> Tuple[list, int]:
    """Reads any file supported by pydub (ffmpeg) and returns the data contained
    within.
    returns: (channels, samplerate)"""
    audiofile = AudioSegment.from_file(filename)
    if limit:
        audiofile = audiofile[:limit * 1000]
    data = np.fromstring(audiofile._data, np.int16)
    channels = []
    for chn in range(audiofile.channels):
        channels.append(data[chn::audiofile.channels])
    fs = audiofile.frame_rate
    return (channels, fs)

def main(argd=None):
    """Main entry point, expects doctopt arg dict as argd."""
    global DEBUG, debug
    argd = argd or docopt(USAGESTR, version=VERSIONSTR, script=SCRIPT, colors={'header': {'fore': 'yellow'}, 'script': {'fore': 'lightblue', 'style': 'bright'}, 'version': {'fore': 'lightblue'}})
    DEBUG = argd['--debug']
    if DEBUG:
        load_debug_deps()
    else:
        debug = noop
    if argd['--auto-disable']:
        auto_disable()
    if argd['--names']:
        return list_names()
    elif argd['--translate']:
        try:
            print('\n'.join(translate(argd['CODE'] or read_stdin().split(), rgb_mode=argd['--truecolor'])))
        except ValueError as ex:
            print_err('Translation error: {}'.format(ex))
            return 1
        return 0
    elif argd['--listcodes']:
        return list_known_codes(argd['TEXT'] or read_stdin(), unique=argd['--unique'], rgb_mode=argd['--truecolor'])
    txt = argd['TEXT'] or read_stdin()
    fd = sys.stderr if argd['--err'] else sys.stdout
    end = '' if argd['--newline'] else '\n'
    if argd['--stripcodes']:
        txt = justify(strip_codes(txt), argd)
        print(txt, file=fd, end=end)
        return 0
    clr = get_colr(txt, argd)
    clr = justify(clr, argd)
    if clr:
        print(str(clr), file=fd, end=end)
        return 0
    return 1

def get_colr(txt, argd):
    """Return a Colr instance based on user args."""
    fore = parse_colr_arg(get_name_arg(argd, '--fore', 'FORE', default=None), rgb_mode=argd['--truecolor'])
    back = parse_colr_arg(get_name_arg(argd, '--back', 'BACK', default=None), rgb_mode=argd['--truecolor'])
    style = get_name_arg(argd, '--style', 'STYLE', default=None)
    if argd['--gradient']:
        return C(txt).gradient(name=argd['--gradient'], spread=try_int(argd['--spread'], 1, minimum=0), fore=fore, back=back, style=style, rgb_mode=argd['--truecolor'])
    if argd['--gradientrgb']:
        rgb_start, rgb_stop = parse_gradient_rgb_args(argd['--gradientrgb'])
        return C(txt).gradient_rgb(fore=fore, back=back, style=style, start=rgb_start, stop=rgb_stop)
    if argd['--rainbow']:
        return C(txt).rainbow(fore=fore, back=back, style=style, freq=try_float(argd['--frequency'], 0.1, minimum=0), offset=try_int(argd['--offset'], randint(0, 255), minimum=0), spread=try_float(argd['--spread'], 3.0, minimum=0), rgb_mode=argd['--truecolor'])
    return C(txt, fore=fore, back=back, style=style)

def get_name_arg(argd, *argnames, default=None):
    """Return the first argument value given in a docopt arg dict.
    When not given, return default."""
    val = None
    for argname in argnames:
        if argd[argname]:
            val = argd[argname].lower().strip()
            break
    return val if val else default

def handle_err(*args):
    """Handle fatal errors, caught in __main__ scope.
    If DEBUG is set, print a real traceback.
    Otherwise, `print_err` any arguments passed."""
    if DEBUG:
        print_err(traceback.format_exc(), color=False)
    else:
        print_err(*args, newline=True)

def justify(clr, argd):
    """Justify str/Colr based on user args."""
    methodmap = {'--ljust': clr.ljust, '--rjust': clr.rjust, '--center': clr.center}
    for flag in methodmap:
        if argd[flag]:
            if argd[flag] in ('0', '-'):
                val = get_terminal_size(default=(80, 35))[0]
            else:
                val = try_int(argd[flag], minimum=None)
                if val < 0:
                    val = get_terminal_size(default=(80, 35))[0] + val
            return methodmap[flag](val)
    return clr

def print_err(*args, **kwargs):
    """A wrapper for print() that uses stderr by default."""
    if kwargs.get('file', None) is None:
        kwargs['file'] = sys.stderr
    color = dict_pop_or(kwargs, 'color', True)
    if color and kwargs['file'].isatty():
        msg = kwargs.get('sep', ' ').join((str(a) if isinstance(a, C) else str(C(a, 'red')) for a in args))
    else:
        msg = kwargs.get('sep', ' ').join((str(a.stripped() if isinstance(a, C) else a) for a in args))
    newline = dict_pop_or(kwargs, 'newline', False)
    if newline:
        msg = '\n{}'.format(msg)
    print(msg, **kwargs)

def read_stdin():
    """Read text from stdin, and print a helpful message for ttys."""
    if sys.stdin.isatty() and sys.stdout.isatty():
        print('\nReading from stdin until end of file (Ctrl + D)...')
    return sys.stdin.read()

def translate(usercodes, rgb_mode=False):
    """Translate one or more hex, term, or rgb value into the others.
    Yields strings with the results for each code translated."""
    for code in usercodes:
        code = code.strip().lower()
        if code.isalpha() and code in codes['fore']:
            yield translate_basic(code)
        else:
            if ',' in code:
                try:
                    r, g, b = (int(c.strip()) for c in code.split(','))
                except (TypeError, ValueError):
                    raise InvalidColr(code)
                code = (r, g, b)
            colorcode = ColorCode(code, rgb_mode=rgb_mode)
            if disabled():
                yield str(colorcode)
            yield colorcode.example()

def translate_basic(usercode):
    """Translate a basic color name to color with explanation."""
    codenum = get_code_num(codes['fore'][usercode])
    colorcode = codeformat(codenum)
    msg = 'Name: {:>10}, Number: {:>3}, EscapeCode: {!r}'.format(usercode, codenum, colorcode)
    if disabled():
        return msg
    return str(C(msg, fore=usercode))

def try_int(s, default=None, minimum=None):
    """Try parsing a string into an integer.
    If None is passed, default is returned.
    On failure, InvalidNumber is raised."""
    if not s:
        return default
    try:
        val = int(s)
    except (TypeError, ValueError):
        raise InvalidNumber(s)
    if minimum is not None and val < minimum:
        val = minimum
    return val

def try_rgb(s, default=None):
    """Try parsing a string into an rgb value (int, int, int),
    where the ints are 0-255 inclusive.
    If None is passed, default is returned.
    On failure, InvalidArg is raised."""
    if not s:
        return default
    try:
        r, g, b = (int(x.strip()) for x in s.split(','))
    except ValueError:
        raise InvalidRgb(s)
    if not all((in_range(x, 0, 255) for x in (r, g, b))):
        raise InvalidRgb(s)
    return (r, g, b)

def entry_point():
    """An entry point for setuptools. This is required because
    `if __name__ == '__main__'` is not fired when the entry point
    is 'main()'. This just wraps the old behavior in a function so
    it can be called from setuptools."""
    try:
        mainret = main()
    except (EOFError, KeyboardInterrupt):
        print_err('\nUser cancelled.\n')
        mainret = 2
    except BrokenPipeError:
        print_err('\nBroken pipe, input/output was interrupted.\n')
        mainret = 3
    except InvalidArg as exarg:
        handle_err(exarg.as_colr())
        mainret = 4
    except ValueError as exnum:
        handle_err(exnum)
        mainret = 4
    sys.exit(mainret)

def create_default_context(purpose=None, **kwargs):
    """Create a new SSL context in the most secure way available on the current
    Python version. See :func:`ssl.create_default_context`."""
    if hasattr(ssl, 'create_default_context'):
        if purpose is None or purpose is False:
            purpose = ssl.Purpose.SERVER_AUTH
        elif purpose is True:
            purpose = ssl.Purpose.CLIENT_AUTH
        return ssl.create_default_context(purpose, **kwargs)
    context = SSLContext(ssl.PROTOCOL_SSLv23)
    if kwargs.get('cafile'):
        context.load_verify_locations(kwargs['cafile'])
    return context

def get_logger(context=None, name=None):
    """Return a logger for *context*.

    Return a :class:`ContextLogger` instance. The instance implements the
    standard library's :class:`logging.Logger` interface."""
    if name is None:
        name = _logger_name
    if context is None and name in _logger_dict:
        return _logger_dict[name]
    if context is not None and (not isinstance(context, six.string_types)):
        context = util.objref(context)
    logger = logging.getLogger(name)
    logger = ContextLogger(logger, context)
    if context is None:
        _logger_dict[name] = logger
    return logger

def blocking(func, *args, **kwargs):
    """Run a function that uses blocking IO.

    The function is run in the IO thread pool."""
    pool = get_io_pool()
    fut = pool.submit(func, *args, **kwargs)
    return fut.result()

def as_completed(objects, count=None, timeout=None):
    """Wait for one or more waitable objects, yielding them as they become
    ready.

    This is the iterator/generator version of :func:`wait`."""
    for obj in objects:
        if not hasattr(obj, 'add_done_callback'):
            raise TypeError('Expecting sequence of waitable objects')
    if count is None:
        count = len(objects)
    if count < 0 or count > len(objects):
        raise ValueError('count must be between 0 and len(objects)')
    if count == 0:
        return
    pending = list(objects)
    for obj in _wait(pending, timeout):
        yield obj
        count -= 1
        if count == 0:
            break

def wait(objects, count=None, timeout=None):
    """Wait for one or more waitable objects.

    This method waits until *count* elements from the sequence of waitable
    objects *objects* have become ready. If *count* is ``None`` (the default),
    then wait for all objects to become ready.

    What "ready" is means depends on the object type. A waitable object is a
    objects that implements the ``add_done_callback()`` and
    ``remove_done_callback`` methods. This currently includes:

      * :class:`~gruvi.Event` - an event is ready when its internal flag is set.
      * :class:`~gruvi.Future` - a future is ready when its result is set.
      * :class:`~gruvi.Fiber` - a fiber is ready when has terminated.
      * :class:`~gruvi.Process` - a process is ready when the child has exited."""
    for obj in objects:
        if not hasattr(obj, 'add_done_callback'):
            raise TypeError('Expecting sequence of waitable objects')
    if count is None:
        count = len(objects)
    if count < 0 or count > len(objects):
        raise ValueError('count must be between 0 and len(objects)')
    if count == 0:
        return ([], objects)
    pending = list(objects)
    done = []
    try:
        for obj in _wait(pending, timeout):
            done.append(obj)
            if len(done) == count:
                break
    except Timeout:
        pass
    return (done, list(filter(bool, pending)))

def generate_hashes(peaks, fan_value: int=DEFAULT_FAN_VALUE):
    """Hash list structure:
       sha1_hash[0:20]    time_offset
    [(e05b341a9b77a51fd26, 32), ... ]"""
    if PEAK_SORT:
        peaks = sorted(peaks, key=lambda x: x[1])
    for i in range(len(peaks)):
        for j in range(1, fan_value):
            if i + j < len(peaks):
                freq1 = peaks[i][IDX_FREQ_I]
                freq2 = peaks[i + j][IDX_FREQ_I]
                t1 = peaks[i][IDX_TIME_J]
                t2 = peaks[i + j][IDX_TIME_J]
                t_delta = t2 - t1
                if MIN_HASH_TIME_DELTA <= t_delta <= MAX_HASH_TIME_DELTA:
                    key = '{}|{}|{}'.format(freq1, freq2, t_delta)
                    h = hashlib.sha1(key.encode('utf-8'))
                    yield (h.hexdigest()[0:FINGERPRINT_REDUCTION], t1)

def acquire_restore(lock, state):
    """Acquire a lock and restore its state."""
    if hasattr(lock, '_acquire_restore'):
        lock._acquire_restore(state)
    elif hasattr(lock, 'acquire'):
        lock.acquire()
    else:
        raise TypeError('expecting Lock/RLock')

def release_save(lock):
    """Release a lock and return its state."""
    if hasattr(lock, '_release_save'):
        return lock._release_save()
    elif hasattr(lock, 'release'):
        lock.release()
    else:
        raise TypeError('expecting Lock/RLock')

def thread_lock(lock):
    """Return the thread lock for *lock*."""
    if hasattr(lock, '_lock'):
        return lock._lock
    elif hasattr(lock, 'acquire'):
        return lock
    else:
        raise TypeError('expecting Lock/RLock')

def _build_codes() -> Dict[str, Dict[str, str]]:
    """Build code map, encapsulated to reduce module-level globals."""
    built = {'fore': {}, 'back': {}, 'style': {}}
    for name, number in _namemap:
        built['fore'][name] = codeformat(30 + number)
        built['back'][name] = codeformat(40 + number)
        litename = 'light{}'.format(name)
        built['fore'][litename] = codeformat(90 + number)
        built['back'][litename] = codeformat(100 + number)
    built['fore']['reset'] = codeformat(39)
    built['back']['reset'] = codeformat(49)
    for code, names in _stylemap:
        for alias in names:
            built['style'][alias] = codeformat(code)
    for i in range(256):
        built['fore'][str(i)] = extforeformat(i)
        built['back'][str(i)] = extbackformat(i)
    return built

def _build_codes_reverse(codes: Dict[str, Dict[str, str]]) -> Dict[str, Dict[str, str]]:
    """Build a reverse escape-code to name map, based on an existing
    name to escape-code map."""
    built = {}
    for codetype, codemap in codes.items():
        for name, escapecode in codemap.items():
            if len(name) < 2:
                continue
            if built.get(codetype, None) is None:
                built[codetype] = {}
            built[codetype][escapecode] = name
    return built

def format_back(number: FormatArg, light: Optional[bool]=False, extended: Optional[bool]=False) -> str:
    """Return an escape code for a back color, by number.
    This is a convenience method for handling the different code types
    all in one shot.
    It also handles some validation."""
    return _format_code(number, backcolor=True, light=light, extended=extended)

def format_style(number: int) -> str:
    """Return an escape code for a style, by number.
    This handles invalid style numbers."""
    if str(number) not in _stylenums:
        raise InvalidStyle(number)
    return codeformat(number)

def get_all_names() -> Tuple[str]:
    """Retrieve a tuple of all known color names, basic and 'known names'.
    """
    names = list(basic_names)
    names.extend(name_data)
    return tuple(sorted(set(names)))

def get_code_num(s: str) -> Optional[int]:
    """Get code number from an escape code.
    Raises InvalidEscapeCode if an invalid number is found."""
    if ';' in s:
        numberstr = s.rpartition(';')[-1][:-1]
    else:
        numberstr = s.rpartition('[')[-1][:-1]
    num = try_parse_int(numberstr, default=None, minimum=0, maximum=255)
    if num is None:
        raise InvalidEscapeCode(numberstr)
    return num

def get_code_num_rgb(s: str) -> Optional[Tuple[int, int, int]]:
    """Get rgb code numbers from an RGB escape code.
    Raises InvalidRgbEscapeCode if an invalid number is found."""
    parts = s.split(';')
    if len(parts) != 5:
        raise InvalidRgbEscapeCode(s, reason='Count is off.')
    rgbparts = parts[-3:]
    if not rgbparts[2].endswith('m'):
        raise InvalidRgbEscapeCode(s, reason="Missing 'm' on the end.")
    rgbparts[2] = rgbparts[2].rstrip('m')
    try:
        r, g, b = [int(x) for x in rgbparts]
    except ValueError as ex:
        raise InvalidRgbEscapeCode(s) from ex
    if not all((in_range(x, 0, 255) for x in (r, g, b))):
        raise InvalidRgbEscapeCode(s, reason='Not in range 0-255.')
    return (r, g, b)

def get_known_codes(s: Union[str, 'Colr'], unique: Optional[bool]=True, rgb_mode: Optional[bool]=False):
    """Get all known escape codes from a string, and yield the explanations.
    """
    isdisabled = disabled()
    orderedcodes = tuple(((c, get_known_name(c)) for c in get_codes(s)))
    codesdone = set()
    for code, codeinfo in orderedcodes:
        if unique:
            if code in codesdone:
                continue
            codesdone.add(code)
        if codeinfo is None:
            continue
        codetype, name = codeinfo
        typedesc = '{:>13}: {!r:<23}'.format(codetype.title(), code)
        if codetype.startswith(('extended', 'rgb')):
            if isdisabled:
                codedesc = str(ColorCode(name, rgb_mode=rgb_mode))
            else:
                codedesc = ColorCode(name, rgb_mode=rgb_mode).example()
        else:
            codedesc = ''.join((code, str(name).lstrip('(').rstrip(')'), codes['style']['reset_all']))
        yield ' '.join((typedesc, codedesc))

def in_range(x: int, minimum: int, maximum: int) -> bool:
    """Return True if x is >= minimum and <= maximum."""
    return x >= minimum and x <= maximum

def try_parse_int(s: str, default: Optional[Any]=None, minimum: Optional[int]=None, maximum: Optional[int]=None) -> Optional[Any]:
    """Try parsing a string into an integer.
    On failure, return `default`.
    If the number is less then `minimum` or greater than `maximum`,
    return `default`.
    Returns an integer on success."""
    try:
        n = int(s)
    except ValueError:
        return default
    if minimum is not None and n < minimum:
        return default
    elif maximum is not None and n > maximum:
        return default
    return n

def ensure_tty(file=sys.stdout):
    """Ensure a file object is a tty. It must have an `isatty` method that
    returns True.
    TypeError is raised if the method doesn't exist, or returns False."""
    isatty = getattr(file, 'isatty', None)
    if isatty is None:
        raise TypeError('Cannot detect tty, file has no `isatty` method: {}'.format(getattr(file, 'name', type(file).__name__)))
    if not isatty():
        raise TypeError('This will not work, file object is not a tty: {}'.format(getattr(file, 'name', type(file).__name__)))
    return True

def hex2rgb(hexval: str, allow_short: bool=False) -> RGB:
    """Return a tuple of (R, G, B) from a hex color."""
    if not hexval:
        raise ValueError('Expecting hex string (#RGB, #RRGGBB), got nothing: {!r}'.format(hexval))
    try:
        hexval = hexval.strip().lstrip('#')
    except AttributeError:
        raise ValueError('Expecting hex string (#RGB, #RRGGBB), got: ({}) {!r}'.format(type(hexval).__name__, hexval))
    if allow_short:
        hexval = fix_hex(hexval)
    if not len(hexval) == 6:
        raise ValueError('Not a length 3 or 6 hex string (#RGB, #RRGGBB), got: {}'.format(hexval))
    try:
        val = tuple((int(''.join(hexval[i:i + 2]), 16) for i in range(0, len(hexval), 2)))
    except ValueError:
        raise ValueError('Invalid hex value: {}'.format(hexval))
    r, g, b = val
    return (r, g, b)

def hex2term(hexval: str, allow_short: bool=False) -> str:
    """Convert a hex value into the nearest terminal code number."""
    return rgb2term(*hex2rgb(hexval, allow_short=allow_short))

def hex2termhex(hexval: str, allow_short: bool=False) -> str:
    """Convert a hex value into the nearest terminal color matched hex."""
    return rgb2termhex(*hex2rgb(hexval, allow_short=allow_short))

def print_all() -> None:
    """Print all 256 xterm color codes."""
    for code in sorted(term2hex_map):
        print(' '.join(('\x1b[48;5;{code}m{code:<3}:{hexval:<6}\x1b[0m', '\x1b[38;5;{code}m{code:<3}:{hexval:<6}\x1b[0m')).format(code=code, hexval=term2hex_map[code]))

def rgb2hex(r: int, g: int, b: int) -> str:
    """Convert rgb values to a hex code."""
    return '{:02x}{:02x}{:02x}'.format(r, g, b)

def rgb2term(r: int, g: int, b: int) -> str:
    """Convert an rgb value to a terminal code."""
    return hex2term_map[rgb2termhex(r, g, b)]

def rgb2termhex(r: int, g: int, b: int) -> str:
    """Convert an rgb value to the nearest hex value that matches a term code.
    The hex value will be one in `hex2term_map`."""
    incs = [0, 95, 135, 175, 215, 255]
    res = []
    parts = (r, g, b)
    for part in parts:
        if part < 0 or part > 255:
            raise ValueError('Expecting 0-255 for RGB code, got: {!r}'.format(parts))
        i = 0
        while i < len(incs) - 1:
            s, b = (incs[i], incs[i + 1])
            if s <= part <= b:
                s1 = abs(s - part)
                b1 = abs(b - part)
                if s1 < b1:
                    closest = s
                else:
                    closest = b
                res.append(closest)
                break
            i += 1
    return rgb2hex(*res)

def term2hex(code: Numeric, default: Optional[str]=None) -> str:
