def ellipticity2phi_q(e1, e2):
    """:param e1:
    :param e2:
    :return:"""
    phi = np.arctan2(e2, e1) / 2
    c = np.sqrt(e1 ** 2 + e2 ** 2)
    if c > 0.999:
        c = 0.999
    q = (1 - c) / (1 + c)
    return (phi, q)

def compute_lower_upper_errors(sample, num_sigma=1):
    """computes the upper and lower sigma from the median value.
    This functions gives good error estimates for skewed pdf's
    :param sample: 1-D sample
    :return: median, lower_sigma, upper_sigma"""
    if num_sigma > 3:
        raise ValueError('Number of sigma-constraints restircted to three. %s not valid' % num_sigma)
    num = len(sample)
    num_threshold1 = int(round((num - 1) * 0.833))
    num_threshold2 = int(round((num - 1) * 0.977249868))
    num_threshold3 = int(round((num - 1) * 0.998650102))
    median = np.median(sample)
    sorted_sample = np.sort(sample)
    if num_sigma > 0:
        upper_sigma1 = sorted_sample[num_threshold1 - 1]
        lower_sigma1 = sorted_sample[num - num_threshold1 - 1]
    else:
        return (median, [[]])
    if num_sigma > 1:
        upper_sigma2 = sorted_sample[num_threshold2 - 1]
        lower_sigma2 = sorted_sample[num - num_threshold2 - 1]
    else:
        return (median, [[median - lower_sigma1, upper_sigma1 - median]])
    if num_sigma > 2:
        upper_sigma3 = sorted_sample[num_threshold3 - 1]
        lower_sigma3 = sorted_sample[num - num_threshold3 - 1]
        return (median, [[median - lower_sigma1, upper_sigma1 - median], [median - lower_sigma2, upper_sigma2 - median], [median - lower_sigma3, upper_sigma3 - median]])
    else:
        return (median, [[median - lower_sigma1, upper_sigma1 - median], [median - lower_sigma2, upper_sigma2 - median]])

def sqrt(inputArray, scale_min=None, scale_max=None):
    """Performs sqrt scaling of the input numpy array.

    @type inputArray: numpy array
    @param inputArray: image data array
    @type scale_min: float
    @param scale_min: minimum data value
    @type scale_max: float
    @param scale_max: maximum data value
    @rtype: numpy array
    @return: image data array"""
    imageData = np.array(inputArray, copy=True)
    if scale_min is None:
        scale_min = imageData.min()
    if scale_max is None:
        scale_max = imageData.max()
    imageData = imageData.clip(min=scale_min, max=scale_max)
    imageData = imageData - scale_min
    indices = np.where(imageData < 0)
    imageData[indices] = 0.0
    imageData = np.sqrt(imageData)
    imageData = imageData / math.sqrt(scale_max - scale_min)
    return imageData

def findOverlap(x_mins, y_mins, min_distance):
    """finds overlapping solutions, deletes multiples and deletes non-solutions and if it is not a solution, deleted as well"""
    n = len(x_mins)
    idex = []
    for i in range(n):
        if i == 0:
            pass
        else:
            for j in range(0, i):
                if abs(x_mins[i] - x_mins[j]) < min_distance and abs(y_mins[i] - y_mins[j]) < min_distance:
                    idex.append(i)
                    break
    x_mins = np.delete(x_mins, idex, axis=0)
    y_mins = np.delete(y_mins, idex, axis=0)
    return (x_mins, y_mins)

def get_param_WLS(A, C_D_inv, d, inv_bool=True):
    """returns the parameter values given
    :param A: response matrix Nd x Ns (Nd = # data points, Ns = # parameters)
    :param C_D_inv: inverse covariance matrix of the data, Nd x Nd, diagonal form
    :param d: data array, 1-d Nd
    :param inv_bool: boolean, wheter returning also the inverse matrix or just solve the linear system
    :return: 1-d array of parameter values"""
    M = A.T.dot(np.multiply(C_D_inv, A.T).T)
    if inv_bool:
        if np.linalg.cond(M) < 5 / sys.float_info.epsilon:
            try:
                M_inv = np.linalg.inv(M)
            except:
                M_inv = np.zeros_like(M)
        else:
            M_inv = np.zeros_like(M)
        R = A.T.dot(np.multiply(C_D_inv, d))
        B = M_inv.dot(R)
    else:
        if np.linalg.cond(M) < 5 / sys.float_info.epsilon:
            R = A.T.dot(np.multiply(C_D_inv, d))
            try:
                B = np.linalg.solve(M, R).T
            except:
                B = np.zeros(len(A.T))
        else:
            B = np.zeros(len(A.T))
        M_inv = None
    image = A.dot(B)
    return (B, M_inv, image)

