    return json.dumps(symbol, indent='  ')

def hash(symbol, hash_type='sha1'):
    """create a hash code from symbol"""
    code = hashlib.new(hash_type)
    code.update(str(symbol).encode('utf-8'))
    return code.hexdigest()

def sh(args, **kwargs):
    """runs the given cmd as shell command"""
    if isinstance(args, str):
        args = args.split()
    if not args:
        return
    click.echo('$ {0}'.format(' '.join(args)))
    try:
        return subprocess.check_call(args, **kwargs)
    except subprocess.CalledProcessError as exc:
        click.secho('run error {}'.format(exc))
    except OSError as exc:
        click.secho('not found error {}'.format(exc))

def parse_doc(s):
    """parse a comment in the format of JavaDoc and returns an object, where each JavaDoc tag
    is a property of the object."""
    if not s:
        return
    doc = DocObject()
    tag = None
    s = s[3:-2]
    for line in s.splitlines():
        line = line.lstrip(' *')
        if not line:
            tag = None
        elif line[0] == '@':
            line = line[1:]
            res = line.split(maxsplit=1)
            if len(res) == 0:
                continue
            tag = res[0]
            if len(res) == 1:
                doc.add_tag(tag, True)
            elif len(res) == 2:
                value = res[1]
                doc.add_tag(tag, value)
        elif tag:
            doc.add_tag(tag, line)
        else:
            doc.add_tag('description', line)
    return doc

def throw_if_bad_response(response):
    """Throw an exception if the Cerberus response is not successful."""
    try:
        response.raise_for_status()
    except RequestException:
        try:
            msg = 'Response code: {}; response body:\n{}'.format(response.status_code, json.dumps(response.json(), indent=2))
            raise CerberusClientException(msg)
        except ValueError:
            msg = 'Response code: {}; response body:\n{}'.format(response.status_code, response.text)
            raise CerberusClientException(msg)

