def action_log_create(sender, instance, created, **kwargs):
    """Signal receiver that creates a log entry when a model instance is first saved to the database.

    Direct use is discouraged, connect your model through :py:func:`actionslog.registry.register` instead."""
    if created:
        changes = model_instance_diff(None, instance)
        log_entry = LogAction.objects.create_log_action(instance=instance, action=LogAction.CREATE, changes=json.dumps(changes))

def action_log_update(sender, instance, **kwargs):
    """Signal receiver that creates a log entry when a model instance is changed and saved to the database.

    Direct use is discouraged, connect your model through :py:func:`actionslog.registry.register` instead."""
    if instance.pk is not None:
        try:
            old = sender.objects.get(pk=instance.pk)
        except sender.DoesNotExist:
            pass
        else:
            new = instance
            changes = model_instance_diff(old, new)
            if changes:
                log_entry = LogAction.objects.create_log_action(instance=instance, action=LogAction.UPDATE, changes=json.dumps(changes))

def action_log_delete(sender, instance, **kwargs):
    """Signal receiver that creates a log entry when a model instance is deleted from the database.

    Direct use is discouraged, connect your model through :py:func:`actionslog.registry.register` instead."""
    if instance.pk is not None:
        changes = model_instance_diff(instance, None)
        log_entry = LogAction.objects.create_log_action(instance=instance, action=LogAction.DELETE, changes=json.dumps(changes))

def total_size(o, handlers={}, verbose=False, count=False):
    """Returns the approximate memory footprint an object and all of its contents.

    Automatically finds the contents of the following builtin containers and
    their subclasses:  tuple, list, deque, dict, set and frozenset.
    To search other containers, add handlers to iterate over their contents:

        handlers = {SomeContainerClass: iter,
                    OtherContainerClass: OtherContainerClass.get_elements}

    Source: http://code.activestate.com/recipes/577504/ (r3)"""
    dict_handler = lambda d: chain.from_iterable(d.items())
    all_handlers = {tuple: iter, list: iter, deque: iter, dict: dict_handler, set: iter, frozenset: iter}
    all_handlers.update(handlers)
    seen = set()
    default_size = getsizeof(0)
    def sizeof(o):
        """Calculate size of `o` and all its children"""
        if id(o) in seen:
            return 0
        seen.add(id(o))
        if count:
            s = 1
        else:
            s = getsizeof(o, default_size)
        for typ, handler in all_handlers.items():
            if isinstance(o, typ):
                s += sum(map(sizeof, handler(o)))
                break
        return s
    return sizeof(o)

def args_kvp_nodup(s):
    """Parse argument string as key=value pairs separated by commas.

    :param s: Argument string
    :return: Parsed value
    :rtype: dict
    :raises: ValueError for format violations or a duplicated key."""
    if s is None:
        return {}
    d = {}
    for item in [e.strip() for e in s.split(',')]:
        try:
            key, value = item.split('=', 1)
        except ValueError:
            msg = "argument item '{}' not in form key=value".format(item)
            if _argparse_is_dumb:
                _alog.warn(msg)
            raise ValueError(msg)
        if key in d:
            msg = "Duplicate key for '{}' not allowed".format(key)
            if _argparse_is_dumb:
                _alog.warn(msg)
            raise ValueError(msg)
        d[key] = value
    return d

def get_settings(infile):
    """Read settings from input file.

    :param infile: Input file for JSON settings.
    :type infile: file or str path
    :return: Settings parsed from file
    :rtype: dict"""
    settings = yaml.load(_as_file(infile))
    if not hasattr(settings, 'keys'):
        raise ValueError('Settings not found in {}'.format(infile))
    processed_settings = {}
    for k, v in settings.items():
        if k.startswith('PMG_DB_'):
            processed_settings[k[7:].lower()] = v
        else:
            processed_settings[k] = v
    auth_aliases(processed_settings)
    return processed_settings

def auth_aliases(d):
    """Interpret user/password aliases.
    """
    for alias, real in ((USER_KEY, 'readonly_user'), (PASS_KEY, 'readonly_password')):
        if alias in d:
            d[real] = d[alias]
            del d[alias]

def alphadump(d, indent=2, depth=0):
    """Dump a dict to a str,
    with keys in alphabetical order."""
    sep = '\n' + ' ' * depth * indent
    return ''.join(('{}: {}{}'.format(k, alphadump(d[k], depth=depth + 1) if isinstance(d[k], dict) else str(d[k]), sep) for k in sorted(d.keys())))

def collection_keys(coll, sep='.'):
    """Get a list of all (including nested) keys in a collection.
    Examines the first document in the collection.

    :param sep: Separator for nested keys
    :return: List of str"""
    def _keys(x, pre=''):
        for k in x:
            yield (pre + k)
            if isinstance(x[k], dict):
                for nested in _keys(x[k], pre + k + sep):
                    yield nested
    return list(_keys(coll.find_one()))

def csv_dict(d):
    """Format dict to a string with comma-separated values.
    """
    if len(d) == 0:
        return '{}'
    return '{' + ', '.join(["'{}': {}".format(k, quotable(v)) for k, v in d.items()]) + '}'

def kvp_dict(d):
    """Format dict to key=value pairs.
    """
    return ', '.join(['{}={}'.format(k, quotable(v)) for k, v in d.items()])

def mongo_get(rec, key, default=None):
    """Get value from dict using MongoDB dot-separated path semantics.
    For example:

    >>> assert mongo_get({'a': {'b': 1}, 'x': 2}, 'a.b') == 1
    >>> assert mongo_get({'a': {'b': 1}, 'x': 2}, 'x') == 2
    >>> assert mongo_get({'a': {'b': 1}, 'x': 2}, 'a.b.c') is None

    :param rec: mongodb document
    :param key: path to mongo value
    :param default: default to return if not found
    :return: value, potentially nested, or default if not found
    :raise: ValueError, if record is not a dict."""
    if not rec:
        return default
    if not isinstance(rec, collections.Mapping):
        raise ValueError('input record must act like a dict')
    if not '.' in key:
        return rec.get(key, default)
    for key_part in key.split('.'):
        if not isinstance(rec, collections.Mapping):
            return default
        if not key_part in rec:
            return default
        rec = rec[key_part]
    return rec

def obj_ref(obj):
    """Returns a tuple identifying a category/event/contrib/subcontrib"""
    from indico_livesync.models.queue import EntryType
    if isinstance(obj, Category):
        ref = {'type': EntryType.category, 'category_id': obj.id}
    elif isinstance(obj, Event):
        ref = {'type': EntryType.event, 'event_id': obj.id}
    elif isinstance(obj, Session):
        ref = {'type': EntryType.session, 'session_id': obj.id}
    elif isinstance(obj, Contribution):
        ref = {'type': EntryType.contribution, 'contrib_id': obj.id}
    elif isinstance(obj, SubContribution):
        ref = {'type': EntryType.subcontribution, 'subcontrib_id': obj.id}
    else:
        raise ValueError('Unexpected object: {}'.format(obj.__class__.__name__))
    return ImmutableDict(ref)

def obj_deref(ref):
    """Returns the object identified by `ref`"""
    from indico_livesync.models.queue import EntryType
    if ref['type'] == EntryType.category:
        return Category.get_one(ref['category_id'])
    elif ref['type'] == EntryType.event:
        return Event.get_one(ref['event_id'])
    elif ref['type'] == EntryType.session:
        return Session.get_one(ref['session_id'])
    elif ref['type'] == EntryType.contribution:
        return Contribution.get_one(ref['contrib_id'])
    elif ref['type'] == EntryType.subcontribution:
        return SubContribution.get_one(ref['subcontrib_id'])
    else:
        raise ValueError('Unexpected object type: {}'.format(ref['type']))

def get_excluded_categories():
