def iter_user_identities(user):
    """Iterates over all existing user identities that can be used with Vidyo"""
    from indico_vc_vidyo.plugin import VidyoPlugin
    providers = authenticators_re.split(VidyoPlugin.settings.get('authenticators'))
    done = set()
    for provider in providers:
        for _, identifier in user.iter_identifiers(check_providers=True, providers={provider}):
            if identifier in done:
                continue
            done.add(identifier)
            yield identifier

def get_user_from_identifier(settings, identifier):
    """Get an actual User object from an identifier"""
    providers = list((auth.strip() for auth in settings.get('authenticators').split(',')))
    identities = Identity.find_all(Identity.provider.in_(providers), Identity.identifier == identifier)
    if identities:
        return sorted(identities, key=lambda x: providers.index(x.provider))[0].user
    for provider in providers:
        try:
            identity_info = multipass.get_identity(provider, identifier)
        except IdentityRetrievalFailed:
            continue
        if identity_info is None:
            continue
        if not identity_info.provider.settings.get('trusted_email'):
            continue
        emails = {email.lower() for email in identity_info.data.getlist('email') if email}
        if not emails:
            continue
        user = User.find_first(~User.is_deleted, User.all_emails.in_(list(emails)))
        if user:
            return user

def parse_chain(*args):
    """Creates a new parser that executes the passed parsers (args) with the
    previous results and yields a tuple of the results.

    >>> list(parse_chain(lambda: (None, 1), lambda one: (None, 2)))
    [None, None, (1, 2)]

    @param args: parsers
    @returns: parser"""
    items = []
    for parser in args:
        for element in parser(*items):
            if element is None:
                yield None
            else:
                items.append(element)
                break
    yield tuple(items)

def pack_ip(ipstr):
    """Converts an ip address given in dotted notation to a four byte
    string in network byte order.

    >>> len(pack_ip("127.0.0.1"))
    4
    >>> pack_ip("foo")
    Traceback (most recent call last):
    ...
    ValueError: given ip address has an invalid number of dots

    @type ipstr: str
    @rtype: bytes
    @raises ValueError: for badly formatted ip addresses"""
    if not isinstance(ipstr, basestring):
        raise ValueError('given ip address is not a string')
    parts = ipstr.split('.')
    if len(parts) != 4:
        raise ValueError('given ip address has an invalid number of dots')
    parts = [int(x) for x in parts]
    return int_seq_to_bytes(parts)

def unpack_ip(fourbytes):
    """Converts an ip address given in a four byte string in network
    byte order to a string in dotted notation.

    >>> unpack_ip(b"dead")
    '100.101.97.100'
    >>> unpack_ip(b"alive")
    Traceback (most recent call last):
    ...
    ValueError: given buffer is not exactly four bytes long

    @type fourbytes: bytes
    @rtype: str
    @raises ValueError: for bad input"""
    if not isinstance(fourbytes, bytes):
        raise ValueError('given buffer is not a string')
    if len(fourbytes) != 4:
        raise ValueError('given buffer is not exactly four bytes long')
    return '.'.join([str(x) for x in bytes_to_int_seq(fourbytes)])

def pack_mac(macstr):
    """Converts a mac address given in colon delimited notation to a
    six byte string in network byte order.

    >>> pack_mac("30:31:32:33:34:35") == b'012345'
    True
    >>> pack_mac("bad")
    Traceback (most recent call last):
    ...
    ValueError: given mac addresses has an invalid number of colons


    @type macstr: str
    @rtype: bytes
    @raises ValueError: for badly formatted mac addresses"""
    if not isinstance(macstr, basestring):
        raise ValueError('given mac addresses is not a string')
    parts = macstr.split(':')
    if len(parts) != 6:
        raise ValueError('given mac addresses has an invalid number of colons')
    parts = [int(part, 16) for part in parts]
    return int_seq_to_bytes(parts)

def unpack_mac(sixbytes):
    """Converts a mac address given in a six byte string in network
    byte order to a string in colon delimited notation.

    >>> unpack_mac(b"012345")
    '30:31:32:33:34:35'
    >>> unpack_mac(b"bad")
    Traceback (most recent call last):
    ...
    ValueError: given buffer is not exactly six bytes long

    @type sixbytes: bytes
    @rtype: str
    @raises ValueError: for bad input"""
    if not isinstance(sixbytes, bytes):
        raise ValueError('given buffer is not a string')
    if len(sixbytes) != 6:
        raise ValueError('given buffer is not exactly six bytes long')
    return ':'.join(['%2.2x'.__mod__(x) for x in bytes_to_int_seq(sixbytes)])

def maintenance_sleeper(api, response, sleep=300):
    """Pauses the execution if sevenbridges api is under maintenance.
    :param api: Api instance.
    :param response: requests.Response object.
    :param sleep: Time to sleep in between the requests."""
    while response.status_code == 503:
        logger.info('Service unavailable: Response=[%s]', six.text_type(response.__dict__))
        response_body = response.json()
        if 'code' in response_body:
            if response_body['code'] == 0:
                logger.warning('API Maintenance in progress! Waiting for [%s]s', sleep)
                time.sleep(sleep)
                response = api.session.send(response.request)
            else:
                return response
        else:
            return response
    return response

def create_room(room):
    """Creates a MUC room on the XMPP server."""
    if room.custom_server:
        return
    def _create_room(xmpp):
        muc = xmpp.plugin['xep_0045']
        muc.joinMUC(room.jid, xmpp.requested_jid.user)
        muc.configureRoom(room.jid, _set_form_values(xmpp, room))
    current_plugin.logger.info('Creating room %s', room.jid)
    _execute_xmpp(_create_room)

def update_room(room):
    """Updates a MUC room on the XMPP server."""
    if room.custom_server:
        return
    def _update_room(xmpp):
        muc = xmpp.plugin['xep_0045']
        muc.joinMUC(room.jid, xmpp.requested_jid.user)
        muc.configureRoom(room.jid, _set_form_values(xmpp, room, muc.getRoomConfig(room.jid)))
    current_plugin.logger.info('Updating room %s', room.jid)
    _execute_xmpp(_update_room)

def delete_room(room, reason=''):
    """Deletes a MUC room from the XMPP server."""
    if room.custom_server:
        return
    def _delete_room(xmpp):
        muc = xmpp.plugin['xep_0045']
        muc.destroy(room.jid, reason=reason)
    current_plugin.logger.info('Deleting room %s', room.jid)
    _execute_xmpp(_delete_room)
    delete_logs(room)

def get_room_config(jid):
    """Retrieves basic data of a MUC room from the XMPP server.

    :return: dict containing name, description and password of the room"""
    mapping = {'name': 'muc#roomconfig_roomname', 'description': 'muc#roomconfig_roomdesc', 'password': 'muc#roomconfig_roomsecret'}
    def _get_room_config(xmpp):
        muc = xmpp.plugin['xep_0045']
        try:
            form = muc.getRoomConfig(jid)
        except ValueError:
            return None
        fields = form.values['fields']
        return {key: fields[muc_key].values['value'] for key, muc_key in mapping.iteritems()}
    return _execute_xmpp(_get_room_config)

def room_exists(jid):
    """Checks if a MUC room exists on the server."""
    def _room_exists(xmpp):
        disco = xmpp.plugin['xep_0030']
        try:
            disco.get_info(jid)
        except IqError as e:
            if e.condition == 'item-not-found':
                return False
            raise
        else:
            return True
    return _execute_xmpp(_room_exists)

def generate_jid(name, append_date=None):
    """Generates a v alid JID based on the room name.

    :param append_date: appends the given date to the JID"""
    if not append_date:
        return sanitize_jid(name)
    return '{}-{}'.format(sanitize_jid(name), append_date.strftime('%Y-%m-%d'))

def retrieve_logs(room, start_date=None, end_date=None):
    """Retrieves chat logs

    :param room: the `Chatroom`
    :param start_date: the earliest date to get logs for
    :param end_date: the latest date to get logs for
    :return: logs in html format"""
    from indico_chat.plugin import ChatPlugin
    base_url = ChatPlugin.settings.get('log_url')
    if not base_url or room.custom_server:
        return None
    params = {'cr': room.jid}
    if start_date:
        params['sdate'] = start_date.strftime('%Y-%m-%d')
    if end_date:
        params['edate'] = end_date.strftime('%Y-%m-%d')
    try:
        response = requests.get(base_url, params=params)
    except RequestException:
        current_plugin.logger.exception('Could not retrieve logs for %s', room.jid)
        return None
    if response.headers.get('content-type') == 'application/json':
        current_plugin.logger.warning('Could not retrieve logs for %s: %s', room.jid, response.json().get('error'))
        return None
    return response.text

def delete_logs(room):
    """Deletes chat logs"""
    from indico_chat.plugin import ChatPlugin
    base_url = ChatPlugin.settings.get('log_url')
    if not base_url or room.custom_server:
        return
    try:
        response = requests.get(posixpath.join(base_url, 'delete'), params={'cr': room.jid}).json()
    except (RequestException, ValueError):
        current_plugin.logger.exception('Could not delete logs for %s', room.jid)
        return
    if not response.get('success'):
        current_plugin.logger.warning('Could not delete logs for %s: %s', room.jid, response.get('error'))

