def is_chat_admin(user):
    """Checks if a user is a chat admin"""
    from indico_chat.plugin import ChatPlugin
    return ChatPlugin.settings.acls.contains_user('admins', user)

def map_input_output(item, api):
    """Maps item to appropriate sevebridges object.
    :param item: Input/Output value.
    :param api: Api instance.
    :return: Mapped object."""
    if isinstance(item, list):
        return [map_input_output(it, api) for it in item]
    elif isinstance(item, dict) and 'class' in item:
        if item['class'].lower() == 'file':
            return File(id=item['path'], api=api)
    else:
        return item

def inplace_reload(method):
    """Executes the wrapped function and reloads the object
    with data returned from the server."""
    def wrapped(obj, *args, **kwargs):
        in_place = True if kwargs.get('inplace') in (True, None) else False
        api_object = method(obj, *args, **kwargs)
        if in_place and api_object:
            obj._data = api_object._data
            obj._dirty = api_object._dirty
            obj._data.fetched = False
            return obj
        elif api_object:
            return api_object
        else:
            return obj
    return wrapped

def retry_on_excs(excs, retry_count=3, delay=5):
    """Retry decorator used to retry callables on for specific exceptions.

    :param excs: Exceptions tuple.
    :param retry_count: Retry count.
    :param delay: Delay in seconds between retries.
    :return: Wrapped function object."""
    def wrapper(f):
        @functools.wraps(f)
        def deco(*args, **kwargs):
            for i in range(0, retry_count):
                try:
                    return f(*args, **kwargs)
                except excs:
                    if logger:
                        logger.warning('HTTPError caught.Retrying ...'.format(f.__name__), exc_info=True)
                    time.sleep(delay)
            else:
                logger.error('{} failed after {} retries'.format(f.__name__, retry_count))
            return f(*args, **kwargs)
        return deco
    return wrapper

def retry(retry_count):
    """Retry decorator used during file upload and download."""
    def func(f):
        @functools.wraps(f)
        def wrapper(*args, **kwargs):
            for backoff in range(retry_count):
                try:
                    return f(*args, **kwargs)
                except Exception:
                    time.sleep(2 ** backoff)
            else:
                raise SbgError('{}: failed to complete: {}'.format(threading.current_thread().getName(), f.__name__))
        return wrapper
    return func

def check_for_error(func):
    """Executes the wrapped function and inspects the response object
    for specific errors."""
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        try:
            response = func(*args, **kwargs)
            status_code = response.status_code
            if status_code in range(200, 204):
                return response
            if status_code == 204:
                return
            data = response.json()
            e = {400: BadRequest, 401: Unauthorized, 403: Forbidden, 404: NotFound, 405: MethodNotAllowed, 408: RequestTimeout, 409: Conflict, 429: TooManyRequests, 500: ServerError, 503: ServiceUnavailable}.get(status_code, SbgError)()
            if 'message' in data:
                e.message = data['message']
            if 'code' in data:
                e.code = data['code']
            if 'status' in data:
                e.status = data['status']
            if 'more_info' in data:
                e.more_info = data['more_info']
            raise e
        except requests.RequestException as e:
            raise SbgError(message=six.text_type(e))
        except JSONDecodeError:
            message = 'Service might be unavailable. Can also occur by providing too many query parameters.'
            raise_from(ServiceUnavailable(message=six.text_type(message)), None)
        except ValueError as e:
            raise SbgError(message=six.text_type(e))
    return wrapper

def get_json_from_remote_server(func, **kwargs):
    """Safely manage calls to the remote server by encapsulating JSON creation
    from Piwik data."""
    rawjson = func(**kwargs)
    if rawjson is None:
        return {}
    try:
        data = json.loads(rawjson)
        if isinstance(data, dict) and data.get('result') == 'error':
            current_plugin.logger.error('The Piwik server responded with an error: %s', data['message'])
            return {}
        return data
    except Exception:
        current_plugin.logger.exception('Unable to load JSON from source %s', rawjson)
        return {}

def reduce_json(data):
    """Reduce a JSON object"""
    return reduce(lambda x, y: int(x) + int(y), data.values())

def stringify_seconds(seconds=0):
    """Takes time as a value of seconds and deduces the delta in human-readable
    HHh MMm SSs format."""
    seconds = int(seconds)
    minutes = seconds / 60
    ti = {'h': 0, 'm': 0, 's': 0}
    if seconds > 0:
        ti['s'] = seconds % 60
        ti['m'] = minutes % 60
        ti['h'] = minutes / 60
    return '%dh %dm %ds' % (ti['h'], ti['m'], ti['s'])

def supported_sensor(sensor):
    """Check if sensor is supported by pydeconz."""
    if sensor['type'] in DECONZ_BINARY_SENSOR + DECONZ_SENSOR + OTHER_SENSOR:
        return True
    _LOGGER.info('Unsupported sensor type %s (%s)', sensor['type'], sensor['name'])
    return False

def _metric_value(value_str, metric_type):
    """Return a Python-typed metric value from a metric value string."""
    if metric_type in (int, float):
        try:
            return metric_type(value_str)
        except ValueError:
            raise ValueError('Invalid {} metric value: {!r}'.format(metric_type.__class__.__name__, value_str))
    elif metric_type is six.text_type:
        return value_str.strip('"').encode('utf-8').decode('unicode_escape')
    else:
        assert metric_type is bool
        lower_str = value_str.lower()
        if lower_str == 'true':
            return True
        elif lower_str == 'false':
            return False
        else:
            raise ValueError('Invalid boolean metric value: {!r}'.format(value_str))

def _metric_unit_from_name(metric_name):
    """Return a metric unit string for human consumption, that is inferred from
    the metric name.

    If a unit cannot be inferred, `None` is returned."""
    for item in _PATTERN_UNIT_LIST:
        pattern, unit = item
        if pattern.match(metric_name):
            return unit
    return None

def parse_query_parms(method, uri, query_str):
    """Parse the specified query parms string and return a dictionary of query
    parameters. The key of each dict item is the query parameter name, and the
    value of each dict item is the query parameter value. If a query parameter
    shows up more than once, the resulting dict item value is a list of all
    those values.

    query_str is the query string from the URL, everything after the '?'. If
    it is empty or None, None is returned.

    If a query parameter is not of the format "name=value", an HTTPError 400,1
    is raised."""
    if not query_str:
        return None
    query_parms = {}
    for query_item in query_str.split('&'):
        if query_item == '':
            continue
        items = query_item.split('=')
        if len(items) != 2:
            raise BadRequestError(method, uri, reason=1, message="Invalid format for URI query parameter: {!r} (valid format is: 'name=value').".format(query_item))
        name = unquote(items[0])
        value = unquote(items[1])
        if name in query_parms:
            existing_value = query_parms[name]
            if not isinstance(existing_value, list):
                query_parms[name] = list()
                query_parms[name].append(existing_value)
            query_parms[name].append(value)
        else:
            query_parms[name] = value
    return query_parms

def check_required_fields(method, uri, body, field_names):
    """Check required fields in the request body.

    Raises:
      BadRequestError with reason 3: Missing request body
      BadRequestError with reason 5: Missing required field in request body"""
    if body is None:
        raise BadRequestError(method, uri, reason=3, message='Missing request body')
    for field_name in field_names:
        if field_name not in body:
            raise BadRequestError(method, uri, reason=5, message='Missing required field in request body: {}'.format(field_name))

def check_partition_status(method, uri, partition, valid_statuses=None, invalid_statuses=None):
    """Check that the partition is in one of the valid statuses (if specified)
    and not in one of the invalid statuses (if specified), as indicated by its
    'status' property.

    If the Partition object does not have a 'status' property set, this
    function does nothing (in order to make the mock support easy to use).

    Raises:
      ConflictError with reason 1 (reason 6 is not used for partitions)."""
    status = partition.properties.get('status', None)
    if status is None:
        return
    if valid_statuses and status not in valid_statuses or (invalid_statuses and status in invalid_statuses):
        if uri.startswith(partition.uri):
            raise ConflictError(method, uri, reason=1, message='The operation cannot be performed because the targeted partition {} has a status that is not valid for the operation: {}'.format(partition.name, status))
        else:
            raise ConflictError(method, uri, reason=1, message='The operation cannot be performed because partition {} hosting the targeted resource has a status that is not valid for the operation: {}'.format(partition.name, status))

def ensure_crypto_config(partition):
    """Ensure that the 'crypto-configuration' property on the faked partition
    is initialized."""
    if 'crypto-configuration' not in partition.properties or partition.properties['crypto-configuration'] is None:
        partition.properties['crypto-configuration'] = {}
    crypto_config = partition.properties['crypto-configuration']
    if 'crypto-adapter-uris' not in crypto_config or crypto_config['crypto-adapter-uris'] is None:
        crypto_config['crypto-adapter-uris'] = []
    adapter_uris = crypto_config['crypto-adapter-uris']
    if 'crypto-domain-configurations' not in crypto_config or crypto_config['crypto-domain-configurations'] is None:
        crypto_config['crypto-domain-configurations'] = []
    domain_configs = crypto_config['crypto-domain-configurations']
    return (adapter_uris, domain_configs)

def repr_text(text, indent):
    """Return a debug representation of a multi-line text (e.g. the result
    of another repr...() function)."""
    if text is None:
        return 'None'
    ret = _indent(text, amount=indent)
    return ret.lstrip(' ')

def repr_list(_list, indent):
    """Return a debug representation of a list or tuple."""
    if _list is None:
        return 'None'
    if isinstance(_list, MutableSequence):
        bm = '['
        em = ']'
    elif isinstance(_list, Iterable):
        bm = '('
        em = ')'
    else:
        raise TypeError('Object must be an iterable, but is a %s' % type(_list))
    ret = bm + '\n'
    for value in _list:
        ret += _indent('%r,\n' % value, 2)
    ret += em
    ret = repr_text(ret, indent=indent)
    return ret.lstrip(' ')

def repr_dict(_dict, indent):
    """Return a debug representation of a dict or OrderedDict."""
    if _dict is None:
        return 'None'
    if not isinstance(_dict, Mapping):
        raise TypeError('Object must be a mapping, but is a %s' % type(_dict))
    if isinstance(_dict, OrderedDict):
        kind = 'ordered'
        ret = '%s {\n' % kind
        for key in six.iterkeys(_dict):
            value = _dict[key]
            ret += _indent('%r: %r,\n' % (key, value), 2)
    else:
        kind = 'sorted'
        ret = '%s {\n' % kind
        for key in sorted(six.iterkeys(_dict)):
            value = _dict[key]
            ret += _indent('%r: %r,\n' % (key, value), 2)
    ret += '}'
    ret = repr_text(ret, indent=indent)
    return ret.lstrip(' ')

def _handle_request_exc(exc, retry_timeout_config):
    """Handle a :exc:`request.exceptions.RequestException` exception that was
    raised."""
    if isinstance(exc, requests.exceptions.ConnectTimeout):
        raise ConnectTimeout(_request_exc_message(exc), exc, retry_timeout_config.connect_timeout, retry_timeout_config.connect_retries)
    elif isinstance(exc, requests.exceptions.ReadTimeout):
        raise ReadTimeout(_request_exc_message(exc), exc, retry_timeout_config.read_timeout, retry_timeout_config.read_retries)
    elif isinstance(exc, requests.exceptions.RetryError):
        raise RetriesExceeded(_request_exc_message(exc), exc, retry_timeout_config.connect_retries)
    else:
        raise ConnectionError(_request_exc_message(exc), exc)

def _text_repr(text, max_len=1000):
    """Return the input text as a Python string representation (i.e. using repr())
    that is limited to a maximum length."""
    if text is None:
        text_repr = 'None'
    elif len(text) > max_len:
        text_repr = repr(text[0:max_len]) + '...'
    else:
        text_repr = repr(text)
    return text_repr

def makefile(graph):
    """Format graph as Makefile."""
    from renku.models.provenance.activities import ProcessRun, WorkflowRun
    for activity in graph.activities.values():
        if not isinstance(activity, ProcessRun):
            continue
        elif isinstance(activity, WorkflowRun):
            steps = activity.subprocesses.values()
        else:
            steps = [activity]
        for step in steps:
            click.echo(' '.join(step.outputs) + ': ' + ' '.join(step.inputs))
            tool = step.process
            click.echo('\t@' + ' '.join(tool.to_argv()) + ' ' + ' '.join((tool.STD_STREAMS_REPR[key] + ' ' + str(path) for key, path in tool._std_streams().items())))

def install(client, force):
    """Install Git hooks."""
    import pkg_resources
    from git.index.fun import hook_path as get_hook_path
    for hook in HOOKS:
        hook_path = Path(get_hook_path(hook, client.repo.git_dir))
        if hook_path.exists():
            if not force:
                click.echo('Hook already exists. Skipping {0}'.format(str(hook_path)), err=True)
                continue
            else:
                hook_path.unlink()
        hook_path.parent.mkdir(parents=True, exist_ok=True)
        Path(hook_path).write_bytes(pkg_resources.resource_string('renku.data', '{hook}.sh'.format(hook=hook)))
        hook_path.chmod(hook_path.stat().st_mode | stat.S_IEXEC)

def uninstall(client):
    """Uninstall Git hooks."""
    from git.index.fun import hook_path as get_hook_path
    for hook in HOOKS:
        hook_path = Path(get_hook_path(hook, client.repo.git_dir))
        if hook_path.exists():
            hook_path.unlink()

def format_cell(cell, datetime_fmt=None):
    """Format a cell."""
    if datetime_fmt and isinstance(cell, datetime):
        return cell.strftime(datetime_fmt)
    return cell

def tabulate(collection, headers, datetime_fmt='%Y-%m-%d %H:%M:%S', **kwargs):
    """Pretty-print a collection."""
    if isinstance(headers, dict):
        attrs = headers.keys()
        names = [key if value is None else value for key, value in headers.items()]
    else:
        attrs = names = headers
    table = [(format_cell(cell, datetime_fmt=datetime_fmt) for cell in attrgetter(*attrs)(c)) for c in collection]
    return tblte(table, headers=[h.upper() for h in names], **kwargs)

def _convert_dataset_files(value):
    """Convert dataset files."""
    output = {}
    for k, v in value.items():
        inst = DatasetFile.from_jsonld(v)
        output[inst.path] = inst
    return output

def find_release(package, releases, dependencies=None):
    """Return the best release."""
    dependencies = dependencies if dependencies is not None else {}
    for release in releases:
        url = release['url']
        old_priority = dependencies.get(package, {}).get('priority', 0)
        for suffix, priority in SUFFIXES.items():
            if url.endswith(suffix):
                if old_priority < priority:
                    sha256 = release['digests']['sha256']
                    dependencies[package] = {'package': package, 'url': url, 'sha256': sha256, 'priority': priority}
    return dependencies[package]

def _safe_path(filepath, can_be_cwl=False):
    """Check if the path should be used in output."""
    if filepath in {'.gitignore', '.gitattributes'}:
        return False
    if filepath.startswith('.renku'):
        if can_be_cwl and filepath.endswith('.cwl'):
            return True
        return False
    return True

def _format_sha1(graph, node):
    """Return formatted text with the submodule information."""
    try:
        submodules = node.submodules
        if submodules:
            submodule = ':'.join(submodules)
            return click.style(submodule, fg='green') + '@' + click.style(node.commit.hexsha[:8], fg='yellow')
    except KeyError:
        pass
    return click.style(node.commit.hexsha[:8], fg='yellow')

def convert_arguments(value):
    """Convert arguments from various input formats."""
    if isinstance(value, (list, tuple)):
        return [CommandLineBinding(**item) if isinstance(item, dict) else item for item in value]
    return shlex.split(value)

def cli(ctx, path, renku_home, use_external_storage):
    """Check common Renku commands used in various situations."""
    ctx.obj = LocalClient(path=path, renku_home=renku_home, use_external_storage=use_external_storage)

def config_path(path=None, final=False):
    """Return config path."""
    if final and path:
        return path
    if path is None:
        path = default_config_dir()
    try:
        os.makedirs(path)
    except OSError as e:
        if e.errno != errno.EEXIST:
            raise
    return os.path.join(path, 'config.yml')

def read_config(path=None, final=False):
    """Read Renku configuration."""
    try:
        with open(config_path(path, final=final), 'r') as configfile:
            return yaml.safe_load(configfile) or {}
    except FileNotFoundError:
        return {}

def config_load(ctx, param, value):
    """Print application config path."""
    if ctx.obj is None:
        ctx.obj = {}
    ctx.obj['config_path'] = value
    ctx.obj['config'] = read_config(value)
    return value

def with_config(f):
    """Add config to function."""
    @click.pass_context
    def new_func(ctx, *args, **kwargs):
        if 'config' in kwargs:
            return ctx.invoke(f, *args, **kwargs)
        if ctx.obj is None:
            ctx.obj = {}
        config = ctx.obj['config']
        project_enabled = not ctx.obj.get('no_project', False)
        project_config_path = get_project_config_path()
        if project_enabled and project_config_path:
            project_config = read_config(project_config_path)
            config['project'] = project_config
        result = ctx.invoke(f, config, *args, **kwargs)
        project_config = config.pop('project', None)
        if project_config:
            if not project_config_path:
                raise RuntimeError('Invalid config update')
            write_config(project_config, path=project_config_path)
        write_config(config, path=ctx.obj['config_path'])
        if project_config is not None:
            config['project'] = project_config
        return result
    return update_wrapper(new_func, f)

def print_app_config_path(ctx, param, value):
    """Print application config path."""
    if not value or ctx.resilient_parsing:
        return
    click.echo(config_path(os.environ.get('RENKU_CONFIG')))
    ctx.exit()

def create_project_config_path(path, mode=511, parents=False, exist_ok=False):
    """Create new project configuration folder."""
    project_path = Path(path).absolute().joinpath(RENKU_HOME)
    project_path.mkdir(mode=mode, parents=parents, exist_ok=exist_ok)
    return str(project_path)

def get_project_config_path(path=None):
    """Return project configuration folder if exist."""
    project_path = Path(path or '.').absolute().joinpath(RENKU_HOME)
    if project_path.exists() and project_path.is_dir():
        return str(project_path)

def find_project_config_path(path=None):
    """Find project config path."""
    path = Path(path) if path else Path.cwd()
    abspath = path.absolute()
    project_path = get_project_config_path(abspath)
    if project_path:
        return project_path
    for parent in abspath.parents:
        project_path = get_project_config_path(parent)
        if project_path:
            return project_path

def _nodes(output, parent=None):
    """Yield nodes from entities."""
    entity = getattr(output, 'entity', output)
    if isinstance(entity, Collection):
        for member in entity.members:
            if parent is not None:
                member = attr.evolve(member, parent=parent)
            yield from _nodes(member)
        yield output
    else:
        yield output

def mapped(cls, key='id', **kwargs):
    """Create list of instances from a mapping."""
    kwargs.setdefault('metadata', {})
    kwargs['metadata']['jsonldPredicate'] = {'mapSubject': key}
    kwargs.setdefault('default', attr.Factory(list))
    def converter(value):
        """Convert mapping to a list of instances."""
        if isinstance(value, dict):
            result = []
            for k, v in iteritems(value):
                if not hasattr(cls, 'from_cwl'):
                    vv = dict(v)
                    vv[key] = k
                else:
                    vv = attr.evolve(cls.from_cwl(v), **{key: k})
                result.append(vv)
        else:
            result = value
        def fix_keys(data):
            """Fix names of keys."""
            for a in fields(cls):
                a_name = a.name.rstrip('_')
                if a_name in data:
                    yield (a.name, data[a_name])
        return [cls(**{kk: vv for kk, vv in fix_keys(v)}) if not isinstance(v, cls) else v for v in result]
    kwargs['converter'] = converter
    return attr.ib(**kwargs)

def rerun(client, run, job):
    """Re-run existing workflow or tool using CWL runner."""
    from renku.models.provenance import ProcessRun
    activity = client.process_commmit()
    if not isinstance(activity, ProcessRun):
        click.secho('No tool was found.', fg='red', file=sys.stderr)
        return
    try:
        args = ['cwl-runner', activity.path]
        if job:
            job_file = tempfile.NamedTemporaryFile(suffix='.yml', dir=os.getcwd(), delete=False)
            args.append(job_file.name)
            with job_file as fp:
                yaml.dump(yaml.safe_load(job), stream=fp, encoding='utf-8')
        if run:
            return call(args, cwd=os.getcwd())
    finally:
        if job:
            os.unlink(job_file.name)

