    if not yes and records:
        prompt_text = 'You are about to remove following from "{0}" dataset.\n'.format(dataset.name) + '\n'.join([str(record.full_path) for record in records]) + '\nDo you wish to continue?'
        click.confirm(WARNING + prompt_text, abort=True)
