def accepts(*argtypes, **kwargtypes):
    """A function decorator to specify argument types of the function.

    Types may be specified either in the order that they appear in the
    function or via keyword arguments (just as if you were calling the
    function).

    Example usage:

      | @accepts(Positive0)
      | def square_root(x):
      |     ..."""
    theseargtypes = [T.TypeFactory(a) for a in argtypes]
    thesekwargtypes = {k: T.TypeFactory(a) for k, a in kwargtypes.items()}
    def _decorator(func):
        f = func.__wrapped__ if hasattr(func, '__wrapped__') else func
        try:
            argtypes = inspect.getcallargs(f, *theseargtypes, **thesekwargtypes)
            argtypes = {k: v if issubclass(type(v), T.Type) else T.Constant(v) for k, v in argtypes.items()}
        except TypeError:
            raise E.ArgumentTypeError('Invalid argument specification to @accepts in %s' % func.__qualname__)
        kwargname = U.get_func_kwargs_name(func)
        if kwargname in argtypes.keys():
            argtypes[kwargname] = T.KeywordArguments()
        posargname = U.get_func_posargs_name(func)
        if posargname in argtypes.keys():
            argtypes[posargname] = T.PositionalArguments()
        if U.has_fun_prop(func, 'argtypes'):
            raise ValueError('Cannot set argument types twice')
        U.set_fun_prop(func, 'argtypes', argtypes)
        return _wrap(func)
    return _decorator

def TypeFactory(v):
    """Ensure `v` is a valid Type.

    This function is used to convert user-specified types into
    internal types for the verification engine.  It allows Type
    subclasses, Type subclass instances, Python type, and user-defined
    classes to be passed.  Returns an instance of the type of `v`.

    Users should never access this function directly."""
    if v is None:
        return Nothing()
    elif issubclass(type(v), Type):
        return v
    elif issubclass(v, Type):
        return v()
    elif issubclass(type(v), type):
        return Generic(v)
    else:
        raise InvalidTypeError('Invalid type %s' % v)

def profile_v3_to_proofs(profile, fqdn, refresh=False, address=None):
    """Convert profile format v3 to proofs"""
    proofs = []
    try:
        test = profile.items()
    except:
        return proofs
    if 'account' in profile:
        accounts = profile['account']
    else:
        return proofs
    for account in accounts:
        if 'service' in account and account['service'].lower() not in SITES:
            continue
        if 'proofType' in account and account['proofType'] == 'http':
            try:
                proof = {'service': account['service'], 'proof_url': account['proofUrl'], 'identifier': account['identifier'], 'valid': False}
                if is_valid_proof(account['service'], account['identifier'], fqdn, account['proofUrl'], address=address):
                    proof['valid'] = True
                proofs.append(proof)
            except Exception as e:
                pass
    return proofs

def get_func_posargs_name(f):
    """Returns the name of the function f's keyword argument parameter if it exists, otherwise None"""
    sigparams = inspect.signature(f).parameters
    for p in sigparams:
        if sigparams[p].kind == inspect.Parameter.VAR_POSITIONAL:
            return sigparams[p].name
    return None

def get_func_kwargs_name(f):
    """Returns the name of the function f's keyword argument parameter if it exists, otherwise None"""
    sigparams = inspect.signature(f).parameters
    for p in sigparams:
        if sigparams[p].kind == inspect.Parameter.VAR_KEYWORD:
            return sigparams[p].name
    return None

def get_declared_enums(metadata, schema, default):
    """Return a dict mapping SQLAlchemy enumeration types to the set of their
    declared values.

    :param metadata:
        ...

    :param str schema:
        Schema name (e.g. "public").

    :returns dict:
        {
            "my_enum": frozenset(["a", "b", "c"]),
        }"""
    types = set((column.type for table in metadata.tables.values() for column in table.columns if isinstance(column.type, sqlalchemy.Enum) and schema == (column.type.schema or default)))
    return {t.name: frozenset(t.enums) for t in types}

def wcag_refs(code):
    """Given a `code` from pa11y, return a list of the WCAG references.
    These references are always of the form: one or more capital letters,
    followed by one or more digits. One `code` may contain multiple
    references, separated by commas."""
    bits = code.split('.')
    for bit in reversed(bits):
        if WCAG_REFS_RE.match(bit):
            return bit.split(',')
    return []

def ignore_rule_matches_result(ignore_rule, pa11y_result):
    """Returns a boolean result of whether the given ignore rule matches
    the given pa11y result. The rule only matches the result if *all*
    attributes of the rule match."""
    return all((fnmatch.fnmatch(pa11y_result.get(attr), ignore_rule.get(attr)) for attr in ignore_rule.keys()))

def load_pa11y_results(stdout, spider, url):
    """Load output from pa11y, filtering out the ignored messages.
    The `stdout` parameter is a bytestring, not a unicode string."""
    if not stdout:
        return []
    results = json.loads(stdout.decode('utf8'))
    ignore_rules = ignore_rules_for_url(spider, url)
    for rule in ignore_rules:
        results = [result for result in results if not ignore_rule_matches_result(rule, result)]
    return results

def check_title_match(expected_title, pa11y_results, logger):
    """Check if Scrapy reports any issue with the HTML <title> element.
    If so, compare that <title> element to the title that we got in the
    A11yItem. If they don't match, something is screwy, and pa11y isn't
    parsing the page that we expect."""
    if not pa11y_results:
        return
    title_errs = [err for err in pa11y_results if err['context'].startswith('<title')]
    for err in title_errs:
        title_elmt = html.fragment_fromstring(err['context'])
        elided_title = title_elmt.text.strip()
        if elided_title.endswith('...'):
            pa11y_title = elided_title[0:-4].strip()
        else:
            pa11y_title = elided_title
        if pa11y_title not in expected_title:
            msg = u'Parser mismatch! Scrapy saw full title "{scrapy_title}", Pa11y saw elided title "{elided_title}".'.format(scrapy_title=expected_title, elided_title=elided_title)
            logger.error(msg)

def watched_extension(extension):
    """Return True if the given extension is one of the watched extensions"""
    for ext in hamlpy.VALID_EXTENSIONS:
        if extension.endswith('.' + ext):
            return True
    return False

def _watch_folder(folder, destination, compiler_args):
    """Compares "modified" timestamps against the "compiled" dict, calls compiler
    if necessary."""
    for dirpath, dirnames, filenames in os.walk(folder):
        for filename in filenames:
            if watched_extension(filename) and (not filename.startswith('.#')):
                fullpath = os.path.join(dirpath, filename)
                subfolder = os.path.relpath(dirpath, folder)
                mtime = os.stat(fullpath).st_mtime
                compiled_folder = os.path.join(destination, subfolder)
                if not os.path.exists(compiled_folder):
                    os.makedirs(compiled_folder)
                compiled_path = _compiled_path(compiled_folder, filename)
                if not fullpath in compiled or compiled[fullpath] < mtime or (not os.path.isfile(compiled_path)):
                    compile_file(fullpath, compiled_path, compiler_args)
                    compiled[fullpath] = mtime

def pa11y_counts(results):
    """Given a list of pa11y results, return three integers:
    number of errors, number of warnings, and number of notices."""
    num_error = 0
    num_warning = 0
    num_notice = 0
    for result in results:
        if result['type'] == 'error':
            num_error += 1
        elif result['type'] == 'warning':
            num_warning += 1
        elif result['type'] == 'notice':
            num_notice += 1
    return (num_error, num_warning, num_notice)

def get_csrf_token(response):
    """Extract the CSRF token out of the "Set-Cookie" header of a response."""
    cookie_headers = [h.decode('ascii') for h in response.headers.getlist('Set-Cookie')]
    if not cookie_headers:
        return None
    csrf_headers = [h for h in cookie_headers if h.startswith('csrftoken=')]
    if not csrf_headers:
        return None
    match = re.match('csrftoken=([^ ;]+);', csrf_headers[-1])
    return match.group(1)

def load_pa11y_ignore_rules(file=None, url=None):
    """Load the pa11y ignore rules from the given file or URL."""
    if not file and (not url):
        return None
    if file:
        file = Path(file)
        if not file.isfile():
            msg = u'pa11y_ignore_rules_file specified, but file does not exist! {file}'.format(file=file)
            raise ValueError(msg)
        return yaml.safe_load(file.text())
    resp = requests.get(url)
    if not resp.ok:
        msg = u'pa11y_ignore_rules_url specified, but failed to fetch URL. status={status}'.format(status=resp.status_code)
        err = RuntimeError(msg)
        err.response = resp
        raise err
    return yaml.safe_load(resp.text)

def paginate_search_results(object_class, search_results, page_size, page):
    """Takes edx-search results and returns a Page object populated
    with db objects for that page.

    :param object_class: Model class to use when querying the db for objects.
    :param search_results: edX-search results.
    :param page_size: Number of results per page.
    :param page: Page number.
    :return: Paginator object with model objects"""
    paginator = Paginator(search_results['results'], page_size)
    try:
        page_number = paginator.validate_number(page)
    except InvalidPage:
        if page == 'last':
            page_number = paginator.num_pages
        else:
            raise Http404("Page is not 'last', nor can it be converted to an int.")
    try:
        paged_results = paginator.page(page_number)
    except InvalidPage as exception:
        raise Http404('Invalid page {page_number}: {message}'.format(page_number=page_number, message=str(exception)))
    search_queryset_pks = [item['data']['pk'] for item in paged_results.object_list]
    queryset = object_class.objects.filter(pk__in=search_queryset_pks)
    def ordered_objects(primary_key):
        """Returns database object matching the search result object"""
        for obj in queryset:
            if obj.pk == primary_key:
                return obj
    object_results = list(map(ordered_objects, search_queryset_pks))
    paged_results.object_list = object_results
    return paged_results

