def line_starts_subpgm(line: str) -> Tuple[bool, Optional[str]]:
    """Indicates whether a line in the program is the first line of a subprogram
    definition.

    Args:
        line
    Returns:
       (True, f_name) if line begins a definition for subprogram f_name;
       (False, None) if line does not begin a subprogram definition."""
    match = RE_SUB_START.match(line)
    if match != None:
        f_name = match.group(1)
        return (True, f_name)
    match = RE_FN_START.match(line)
    if match != None:
        f_name = match.group(1)
        return (True, f_name)
    return (False, None)

def line_is_executable(line: str) -> bool:
    """line_is_executable() returns True iff the line can start an
    executable statement in a program."""
    if line_is_comment(line):
        return False
    if re.match(RE_TYPE_NAMES, line):
        return False
    for exp in EXECUTABLE_CODE_START:
        if re.match(exp, line) != None:
            return True
    return False

def flatten(xs: Union[List, Tuple]) -> List:
    """Flatten a nested list or tuple."""
    return sum(map(flatten, xs), []) if isinstance(xs, list) or isinstance(xs, tuple) else [xs]

def ptake(n: int, xs: Iterable[T]) -> Iterable[T]:
    """take with a tqdm progress bar."""
    return tqdm(take(n, xs), total=n)

def ltake(n: int, xs: Iterable[T]) -> List[T]:
    """A non-lazy version of take."""
    return list(take(n, xs))

def compose(*fs: Any) -> Callable:
    """Compose functions from left to right.

    e.g. compose(f, g)(x) = f(g(x))"""
    return foldl1(lambda f, g: lambda *x: f(g(*x)), fs)

def rcompose(*fs: Any) -> Callable:
    """Compose functions from right to left.

    e.g. rcompose(f, g)(x) = g(f(x))"""
    return foldl1(lambda f, g: lambda *x: g(f(*x)), fs)

def flatMap(f: Callable, xs: Iterable) -> List:
    """Map a function onto an iterable and flatten the result."""
    return flatten(lmap(f, xs))

def type_of_line(line):
    """Given a line of code, type_of_line() returns a string indicating
    what kind of code it is."""
    if line_is_comment(line):
        return 'comment'
    elif line_is_executable(line):
        return 'exec_stmt'
    elif line_is_pgm_unit_end(line):
        return 'pgm_unit_end'
    elif line_is_pgm_unit_start(line):
        return 'pgm_unit_start'
    else:
        return 'other'

def split_trailing_comment(line: str) -> str:
    """Takes a line and splits it into two parts (code_part, comment_part)
    where code_part is the line up to but not including any trailing
    comment (the '!' comment character and subsequent characters
    to the end of the line), while comment_part is the trailing comment.

    Args:
        line: A line of Fortran source code.

    Returns:
        A pair (code_part, comment_part) where comment_part is the trailing
        comment.  If the line does not contain any trailing comment, then
        comment_part is None."""
    if line.find('!') == -1:
        return (line, None)
    i = 0
    while i < len(line):
        if line[i] == "'":
            j = line.find("'", i + 1)
            if j == -1:
                sys.stderr.write("WEIRD: unbalanced quote ': line = " + line)
                return line
            else:
                i = j + 1
        elif line[i] == '"':
            j = line.find('"', i + 1)
            if j == -1:
                sys.stderr.write('WEIRD: unbalanced quote ": line = ' + line)
                return line
            else:
                i = j + 1
        elif line[i] == '!':
            comment_part = line[i:]
            code_part = line[:i].rstrip() + '\n'
            return (code_part, comment_part)
        else:
            i += 1
    return (line, None)

def dump(node, annotate_fields=True, include_attributes=False, indent='  '):
    """Return a formatted dump of the tree in *node*.  This is mainly useful for
    debugging purposes.  The returned string will show the names and the values
    for fields.  This makes the code impossible to evaluate, so if evaluation
    is wanted *annotate_fields* must be set to False.  Attributes such as line
    numbers and column offsets are not dumped by default. If this is wanted,
    *include_attributes* can be set to True."""
    def _format(node, level=0):
        if isinstance(node, ast.AST):
            fields = [(a, _format(b, level)) for a, b in ast.iter_fields(node)]
            if include_attributes and node._attributes:
                fields.extend([(a, _format(getattr(node, a), level)) for a in node._attributes])
            return ''.join([node.__class__.__name__, '(', ', '.join(('%s=%s' % field for field in fields) if annotate_fields else (b for a, b in fields)), ')'])
        elif isinstance(node, list):
            lines = ['[']
            lines.extend((indent * (level + 2) + _format(x, level + 2) + ',' for x in node))
            if len(lines) > 1:
                lines.append(indent * (level + 1) + ']')
            else:
                lines[-1] += ']'
            return '\n'.join(lines)
        return repr(node)
    if not isinstance(node, ast.AST):
        raise TypeError('expected AST, got %r' % node.__class__.__name__)
    return _format(node)

def filter_and_process_statements(sts, grounding_score_cutoff: float=0.8, belief_score_cutoff: float=0.85, concepts_of_interest: List[str]=[]):
    """Filter preassembled statements according to certain rules."""
    filtered_sts = []
    counters = {}
    def update_counter(counter_name):
        if counter_name in counters:
            counters[counter_name] += 1
        else:
            counters[counter_name] = 1
    for s in tqdm(sts):
        update_counter('Original number of statements')
        if not s.belief > belief_score_cutoff:
            continue
        update_counter(f'Statements with belief score > {belief_score_cutoff}')
        if s.subj.db_refs.get('UN') is None or s.obj.db_refs.get('UN') is None:
            continue
        update_counter('Statements with UN groundings')
        if not all((x[1] > grounding_score_cutoff for x in (y.db_refs['UN'][0] for y in (s.subj, s.obj)))):
            continue
        update_counter(f'Statements with subj and obj grounding scores > {grounding_score_cutoff}')
        if s.subj_delta['polarity'] is None:
            s.subj_delta['polarity'] = 1
        if s.obj_delta['polarity'] is None:
            s.obj_delta['polarity'] = 1
        filtered_sts.append(s)
    for k, v in counters.items():
        print(f'{k}: {v}')
    return filtered_sts

def list_data_type(type_list):
    """This function takes a list of format specifiers and returns a list of data
    types represented by the format specifiers."""
    data_type = []
    for item in type_list:
        match = re.match('(\\d+)(.+)', item)
        if not match:
            reps = 1
            if item[0] in 'FfEegG':
                data_type.append('REAL')
            elif item[0] in 'Ii':
                data_type.append('INTEGER')
        else:
            reps = match.group(1)
            fmt = match.group(2)
            if '(' in fmt and ',' in fmt:
                fmt = fmt[1:-1].split(',')
            elif '(' in fmt:
                fmt = [fmt[1:-1]]
            else:
                fmt = [fmt]
            for i in range(int(reps)):
                for ft in fmt:
                    if ft[0] in 'FfEegG':
                        data_type.append('REAL')
                    elif ft[0] in 'Ii':
                        data_type.append('INTEGER')
    return data_type

