    data = {'observation_photo[observation_id]': observation_id}
    file_data = {'file': file_object}
    response = requests.post(url='{base_url}/observation_photos'.format(base_url=INAT_BASE_URL), headers=_build_auth_header(access_token), data=data, files=file_data)
    return response.json()

def add_properties_callbacks(cls):
    """Class decorator to add change notifications to builtin containers"""
    for name in cls._mutators:
        if not hasattr(cls, name):
            continue
        setattr(cls, name, properties_mutator(cls, name))
    for name in cls._operators:
        if not hasattr(cls, name):
            continue
        setattr(cls, name, properties_operator(cls, name))
    for name in cls._ioperators:
        if not hasattr(cls, name):
            continue
        setattr(cls, name, properties_mutator(cls, name, True))
    return cls

def properties_operator(cls, name):
    """Wraps a container operator to ensure container class is maintained"""
    def wrapper(self, *args, **kwargs):
        """Perform operation and cast to container class"""
        output = getattr(super(cls, self), name)(*args, **kwargs)
        return cls(output)
    wrapped = getattr(cls, name)
    wrapper.__name__ = wrapped.__name__
    wrapper.__doc__ = wrapped.__doc__
    return wrapper

def validate_prop(value):
    """Validate Property instance for container items"""
    if isinstance(value, CLASS_TYPES) and issubclass(value, HasProperties):
        value = Instance('', value)
    if not isinstance(value, basic.Property):
        raise TypeError('Contained prop must be a Property instance or HasProperties class')
    if value.default is not utils.undefined:
        warn('Contained prop default ignored: {}'.format(value.default), RuntimeWarning)
    return value

def accept_kwargs(func):
    """Wrap a function that may not accept kwargs so they are accepted

    The output function will always have call signature of
    :code:`func(val, **kwargs)`, whereas the original function may have
    call signatures of :code:`func(val)` or :code:`func(val, **kwargs)`.
    In the case of the former, rather than erroring, kwargs are just
    ignored.

    This method is called on serializer/deserializer function; these
    functions always receive kwargs from serialize, but by using this,
    the original functions may simply take a single value."""
    def wrapped(val, **kwargs):
        """Perform a function on a value, ignoring kwargs if necessary"""
        try:
            return func(val, **kwargs)
        except TypeError:
            return func(val)
    return wrapped

def _in_bounds(prop, instance, value):
    """Checks if the value is in the range (min, max)"""
    if prop.min is not None and value < prop.min or (prop.max is not None and value > prop.max):
        prop.error(instance, value, extra='Not within allowed range.')

def _set_listener(instance, obs):
    """Add listeners to a HasProperties instance"""
    if obs.names is everything:
        names = list(instance._props)
    else:
        names = obs.names
    for name in names:
        if name not in instance._listeners:
            instance._listeners[name] = {typ: [] for typ in LISTENER_TYPES}
        instance._listeners[name][obs.mode] += [obs]

def _get_listeners(instance, change):
    """Gets listeners of changed Property on a HasProperties instance"""
    if change['mode'] not in listeners_disabled._quarantine and change['name'] in instance._listeners:
        return instance._listeners[change['name']][change['mode']]
    return []

def build_from_bases(bases, classdict, attr, attr_dict):
    """Helper function to build private HasProperties attributes"""
    output = OrderedDict()
    output_keys = set()
    all_bases = []
    for base in reversed(bases):
        if base is not object and isinstance(base, PropertyMetaclass):
            output_keys = output_keys.union(getattr(base, attr))
        for item in reversed(base.__mro__):
            if item is object or not isinstance(item, PropertyMetaclass):
                continue
            if item not in all_bases:
                all_bases.append(item)
    for base in all_bases:
        for key, val in iteritems(getattr(base, attr)):
            if key in base.__dict__ and key in output_keys:
                output.update({key: val})
    for key in classdict:
        if key in output:
            output.pop(key)
    output.update(attr_dict)
    return output

def validate_call(kwargs, returns, is_method=False):
    """Decorator which runs validation on a callable's arguments and its return
    value. Pass a schema for the kwargs and for the return value. Positional
    arguments are not supported."""
    def decorator(func):
        @wraps(func)
        def inner(*passed_args, **passed_kwargs):
            max_allowed_passed_args_len = 0
            if is_method and type(func) in (types.FunctionType, classmethod):
                max_allowed_passed_args_len = 1
            if len(passed_args) > max_allowed_passed_args_len:
                raise PositionalError('You cannot call this with positional arguments.')
            validate(kwargs, passed_kwargs, 'keyword arguments')
            return_value = func(*passed_args, **passed_kwargs)
            validate(returns, return_value, 'return value')
            return return_value
        inner.__wrapped__ = func
        inner.__validated__ = True
        return inner
    return decorator

def _update_error_pointer(error, pointer_or_prefix):
    """Helper function to update an Error's pointer attribute with a (potentially
    prefixed) dictionary key or list index."""
    if error.pointer:
        error.pointer = '{}.{}'.format(pointer_or_prefix, error.pointer)
    else:
        error.pointer = '{}'.format(pointer_or_prefix)
