def target_from_compact(bits):
    """Extract a full target from its compact representation, undoing the
    transformation x=compact_from_target(t). See compact_from_target() for
    more information on this 32-bit floating point format."""
    size = bits >> 24
    word = bits & 8388607
    if size < 3:
        word >>= 8 * (3 - size)
    else:
        word <<= 8 * (size - 3)
    if bits & 8388608:
        word = -word
    return word

def icmp(a, b):
    """Like cmp(), but for any iterator."""
    for xa in a:
        try:
            xb = next(b)
            d = cmp(xa, xb)
            if d:
                return d
        except StopIteration:
            return 1
    try:
        next(b)
        return -1
    except StopIteration:
        return 0

def _merkle_hash256(*args):
    """The default transform provided to merkle(), which calculates the hash
    of its parameters, serializes and joins them together, then performs a
    has256 of the resulting string. There are two special cases: no arguments,
    which results in 0, and a single argument, whose hash value is returned
    unmodified."""
    if not args:
        return 0
    def _to_hash(h):
        if isinstance(h, numbers.Integral):
            return h
        if hasattr(h, 'hash'):
            return h.hash
        return merkle(h)
    if len(args) == 1:
        return _to_hash(args[0])
    return hash256(b''.join(map(lambda h: hash256.serialize(h), map(_to_hash, args)))).intdigest()

def merkle(hashes, func=_merkle_hash256):
    """Convert an iterable of hashes or hashable objects into a binary tree,
    construct the interior values using a passed-in constructor or compression
    function, and return the root value of the tree. The default compressor is
    the hash256 function, resulting in root-hash for the entire tree."""
    hashes = list(iter(hashes))
    if not hashes:
        return func()
    if len(hashes) == 1:
        return func(*hashes)
    while len(hashes) > 1:
        hashes.append(hashes[-1])
        hashes = list((func(l, r) for l, r in zip(*(iter(hashes),) * 2)))
    return hashes[0]

def b58encode(b, errors='strict'):
    """Encode bytes to a base58-encoded string."""
    len_ = len(b)
    n = BigInteger.deserialize(BytesIO(b), len_)
    res = []
    while n > 0:
        n, r = divmod(n, 58)
        res.append(b58digits[r])
    res = ''.join(res[::-1])
    pad = 0
    for c in b:
        if c == six.int2byte(0):
            pad += 1
        else:
            break
    return (b58digits[0] * pad + res, len_)

def b58decode(s, errors='strict'):
    """Decode a base58-encoding string, returning bytes."""
    if not s:
        return (b'', 0)
    n = 0
    for c in s:
        n *= 58
        if c not in b58digits:
            raise InvalidBase58Error(u'character %r is not a valid base58 character' % c)
        digit = b58digits.index(c)
        n += digit
    res = BigInteger(n).serialize((n.bit_length() + 7) // 8 or 1)
    pad = 0
    for c in s[:-1]:
        if c == b58digits[0]:
            pad += 1
        else:
            break
    return (b'\x00' * pad + res, len(s))

def create(source, dest, tracker, open_trackers, comment, cache):
    """Create torrent file from a single file or a directory."""
    source_title = path.basename(source).replace('.', '_').replace(' ', '_')
    dest = '%s.torrent' % path.join(dest, source_title)
    click.secho('Creating torrent from %s ...' % source)
    my_torrent = Torrent.create_from(source)
    if comment:
        my_torrent.comment = comment
    urls = []
    if tracker:
        urls = tracker.split(',')
    if open_trackers:
        click.secho('Fetching an up-to-date open tracker list ...')
        try:
            urls.extend(get_open_trackers_from_remote())
        except RemoteDownloadError:
            click.secho('Failed. Using built-in open tracker list.', fg='red', err=True)
            urls.extend(get_open_trackers_from_local())
    if urls:
        my_torrent.announce_urls = urls
    my_torrent.to_file(dest)
    click.secho('Torrent file created: %s' % dest, fg='green')
    click.secho('Torrent info hash: %s' % my_torrent.info_hash, fg='blue')
    if cache:
        click.secho('Uploading to %s torrent cache service ...')
        try:
            result = upload_to_cache_server(dest)
            click.secho('Cached torrent URL: %s' % result, fg='yellow')
        except RemoteUploadError as e:
            click.secho('Failed: %s' % e, fg='red', err=True)

def humanize_filesize(bytes_size):
    """Returns human readable filesize.

    :param int bytes_size:
    :rtype: str"""
    if not bytes_size:
        return '0 B'
    names = ('B', 'KB', 'MB', 'GB', 'TB', 'PB', 'EB', 'ZB', 'YB')
    name_idx = int(math.floor(math.log(bytes_size, 1024)))
    size = round(bytes_size / math.pow(1024, name_idx), 2)
    return '%s %s' % (size, names[name_idx])

def get_open_trackers_from_local():
    """Returns open trackers announce URLs list from local backup."""
    with open(path.join(path.dirname(__file__), 'repo', OPEN_TRACKERS_FILENAME)) as f:
        open_trackers = map(str.strip, f.readlines())
    return list(open_trackers)

def create_csp_header(cspDict):
    """create csp header string"""
    policy = ['%s %s' % (k, v) for k, v in cspDict.items() if v != '']
    return '; '.join(policy)

def csp_header(csp={}):
    """Decorator to include csp header on app.route wrapper"""
    _csp = csp_default().read()
    _csp.update(csp)
    _header = ''
    if 'report-only' in _csp and _csp['report-only'] is True:
        _header = 'Content-Security-Policy-Report-Only'
    else:
        _header = 'Content-Security-Policy'
    if 'report-only' in _csp:
        del _csp['report-only']
    _headers = {_header: create_csp_header(_csp)}
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            resp = make_response(f(*args, **kwargs))
            h = resp.headers
            for header, value in _headers.items():
                h[header] = value
            return resp
        return decorated_function
    return decorator

def execute(func, handler, args, kwargs):
    """Wrap the handler ``_execute`` method to trace incoming requests,
    extracting the context from the headers, if available."""
    tracing = handler.settings.get('opentracing_tracing')
    with tracer_stack_context():
        if tracing._trace_all:
            attrs = handler.settings.get('opentracing_traced_attributes', [])
            tracing._apply_tracing(handler, attrs)
        return func(*args, **kwargs)

def on_finish(func, handler, args, kwargs):
    """Wrap the handler ``on_finish`` method to finish the Span for the
    given request, if available."""
    tracing = handler.settings.get('opentracing_tracing')
    tracing._finish_tracing(handler)
    return func(*args, **kwargs)

def log_exception(func, handler, args, kwargs):
    """Wrap the handler ``log_exception`` method to finish the Span for the
    given request, if available. This method is called when an Exception
    is not handled in the user code."""
    value = args[1] if len(args) == 3 else None
    if value is None:
        return func(*args, **kwargs)
    tracing = handler.settings.get('opentracing_tracing')
    if not isinstance(value, HTTPError) or 500 <= value.status_code <= 599:
        tracing._finish_tracing(handler, error=value)
    return func(*args, **kwargs)

def import_from_setting(setting_name, fallback):
    """Return the resolution of an import path stored in a Django setting.

    :arg setting_name: The name of the setting holding the import path
    :arg fallback: An alternate object to use if the setting is empty or
      doesn't exist

    Raise ImproperlyConfigured if a path is given that can't be resolved."""
    path = getattr(settings, setting_name, None)
    if path:
        try:
            return import_string(path)
        except ImportError:
            raise ImproperlyConfigured('%s: No such path.' % path)
    else:
        return fallback

def unsubscribe(request, watch_id):
    """Unsubscribe from (i.e. delete) the watch of ID ``watch_id``.

    Expects an ``s`` querystring parameter matching the watch's secret.

    GET will result in a confirmation page (or a failure page if the secret is
    wrong). POST will actually delete the watch (again, if the secret is
    correct).

    Uses these templates:

    * tidings/unsubscribe.html - Asks user to confirm deleting a watch
    * tidings/unsubscribe_error.html - Shown when a watch is not found
    * tidings/unsubscribe_success.html - Shown when a watch is deleted

    The shipped templates assume a ``head_title`` and a ``content`` block
    in a ``base.html`` template.

    The template extension can be changed from the default ``html`` using
    the setting :data:`~django.conf.settings.TIDINGS_TEMPLATE_EXTENSION`."""
    ext = getattr(settings, 'TIDINGS_TEMPLATE_EXTENSION', 'html')
    try:
        watch = Watch.objects.get(pk=watch_id)
        secret = request.GET.get('s')
        if secret != watch.secret:
            raise Watch.DoesNotExist
    except Watch.DoesNotExist:
        return render(request, 'tidings/unsubscribe_error.' + ext)
    if request.method == 'POST':
        watch.delete()
        return render(request, 'tidings/unsubscribe_success.' + ext)
    return render(request, 'tidings/unsubscribe.' + ext)

def rsa_init(spec):
    """Initiates a :py:class:`oidcmsg.keybundle.KeyBundle` instance
    containing newly minted RSA keys according to a spec.

    Example of specification::
        {'size':2048, 'use': ['enc', 'sig'] }

    Using the spec above 2 RSA keys would be minted, one for
    encryption and one for signing.

    :param spec:
    :return: KeyBundle"""
    try:
        size = spec['size']
    except KeyError:
        size = 2048
    kb = KeyBundle(keytype='RSA')
    if 'use' in spec:
        for use in harmonize_usage(spec['use']):
            _key = new_rsa_key(use=use, key_size=size)
            kb.append(_key)
    else:
        _key = new_rsa_key(key_size=size)
        kb.append(_key)
    return kb

def ec_init(spec):
    """Initiate a key bundle with an elliptic curve key.

    :param spec: Key specifics of the form::
        {"type": "EC", "crv": "P-256", "use": ["sig"]}

    :return: A KeyBundle instance"""
    kb = KeyBundle(keytype='EC')
    if 'use' in spec:
        for use in spec['use']:
            eck = new_ec_key(crv=spec['crv'], use=use)
            kb.append(eck)
    else:
        eck = new_ec_key(crv=spec['crv'])
        kb.append(eck)
    return kb

def sort_func(kd1, kd2):
    """Compares 2 key descriptions
    :param kd1: First key description
    :param kd2: Second key description
    :return: -1,0,1 depending on whether kd1 le,eq or gt then kd2"""
    _l = _cmp(kd1['type'], kd2['type'])
    if _l:
        return _l
    if kd1['type'] == 'EC':
        _l = _cmp(kd1['crv'], kd2['crv'])
        if _l:
            return _l
    _l = _cmp(kd1['type'], kd2['type'])
    if _l:
        return _l
    _l = _cmp(kd1['use'][0], kd2['use'][0])
    if _l:
        return _l
    try:
        _kid1 = kd1['kid']
    except KeyError:
        _kid1 = None
    try:
        _kid2 = kd2['kid']
    except KeyError:
        _kid2 = None
    if _kid1 and _kid2:
        return _cmp(_kid1, _kid2)
    elif _kid1:
        return -1
    elif _kid2:
        return 1
    return 0

def update_key_bundle(key_bundle, diff):
    """Apply a diff specification to a KeyBundle.
    The keys that are to be added are added.
    The keys that should be deleted are marked as inactive.

    :param key_bundle: The original KeyBundle
    :param diff: The difference specification
    :return: An updated key_bundle"""
    try:
        _add = diff['add']
    except KeyError:
        pass
    else:
        key_bundle.extend(_add)
    try:
        _del = diff['del']
    except KeyError:
        pass
    else:
        _now = time.time()
        for k in _del:
            k.inactive_since = _now

def ensure_ec_params(jwk_dict, private):
    """Ensure all required EC parameters are present in dictionary"""
    provided = frozenset(jwk_dict.keys())
    if private is not None and private:
        required = EC_PUBLIC_REQUIRED | EC_PRIVATE_REQUIRED
    else:
        required = EC_PUBLIC_REQUIRED
    return ensure_params('EC', provided, required)

def ensure_rsa_params(jwk_dict, private):
    """Ensure all required RSA parameters are present in dictionary"""
    provided = frozenset(jwk_dict.keys())
    if private is not None and private:
        required = RSA_PUBLIC_REQUIRED | RSA_PRIVATE_REQUIRED
    else:
        required = RSA_PUBLIC_REQUIRED
    return ensure_params('RSA', provided, required)

def ensure_params(kty, provided, required):
    """Ensure all required parameters are present in dictionary"""
    if not required <= provided:
        missing = required - provided
        raise MissingValue('Missing properties for kty={}, {}'.format(kty, str(list(missing))))

def jwk_wrap(key, use='', kid=''):
    """Instantiate a Key instance with the given key

    :param key: The keys to wrap
    :param use: What the key are expected to be use for
    :param kid: A key id
    :return: The Key instance"""
    if isinstance(key, rsa.RSAPublicKey) or isinstance(key, rsa.RSAPrivateKey):
        kspec = RSAKey(use=use, kid=kid).load_key(key)
    elif isinstance(key, str):
        kspec = SYMKey(key=key, use=use, kid=kid)
    elif isinstance(key, ec.EllipticCurvePublicKey):
        kspec = ECKey(use=use, kid=kid).load_key(key)
    else:
        raise Exception('Unknown key type:key=' + str(type(key)))
    kspec.serialize()
    return kspec

def update_keyjar(keyjar):
    """Go through the whole key jar, key bundle by key bundle and update them one
    by one.

    :param keyjar: The key jar to update"""
    for iss, kbl in keyjar.items():
        for kb in kbl:
            kb.update()

def key_summary(keyjar, issuer):
    """Return a text representation of the keyjar.

    :param keyjar: A :py:class:`oidcmsg.key_jar.KeyJar` instance
    :param issuer: Which key owner that we are looking at
    :return: A text representation of the keys"""
    try:
        kbl = keyjar[issuer]
    except KeyError:
        return ''
    else:
        key_list = []
        for kb in kbl:
            for key in kb.keys():
                if key.inactive_since:
                    key_list.append('*{}:{}:{}'.format(key.kty, key.use, key.kid))
                else:
                    key_list.append('{}:{}:{}'.format(key.kty, key.use, key.kid))
        return ', '.join(key_list)

def pick_key(keys, use, alg='', key_type='', kid=''):
    """Based on given criteria pick out the keys that fulfill them from a
    given set of keys.

    :param keys: List of keys. These are :py:class:`cryptojwt.jwk.JWK`
        instances.
    :param use: What the key is going to be used for 'sig'/'enc'
    :param alg: crypto algorithm
    :param key_type: Type of key 'rsa'/'ec'/'oct'
    :param kid: Key ID
    :return: A list of keys that match the pattern"""
    res = []
    if not key_type:
        if use == 'sig':
            key_type = jws_alg2keytype(alg)
        else:
            key_type = jwe_alg2keytype(alg)
    for key in keys:
        if key.use and key.use != use:
            continue
        if key.kty == key_type:
            if key.kid and kid:
                if key.kid == kid:
                    res.append(key)
                else:
                    continue
            if key.alg == '':
                if alg:
                    if key_type == 'EC':
                        if key.crv == 'P-{}'.format(alg[2:]):
                            res.append(key)
                        continue
                res.append(key)
            elif alg and key.alg == alg:
                res.append(key)
            else:
                res.append(key)
    return res

def factory(token, alg=''):
    """Instantiate an JWS instance if the token is a signed JWT.

    :param token: The token that might be a signed JWT
    :param alg: The expected signature algorithm
    :return: A JWS instance if the token was a signed JWT, otherwise None"""
    _jw = JWS(alg=alg)
    if _jw.is_jws(token):
        return _jw
    else:
        return None

def import_rsa_key(pem_data):
    """Extract an RSA key from a PEM-encoded X.509 certificate

    :param pem_data: RSA key encoded in standard form
    :return: rsa.RSAPublicKey instance"""
    if not pem_data.startswith(PREFIX):
        pem_data = bytes('{}\n{}\n{}'.format(PREFIX, pem_data, POSTFIX), 'utf-8')
    else:
        pem_data = bytes(pem_data, 'utf-8')
    cert = x509.load_pem_x509_certificate(pem_data, default_backend())
    return cert.public_key()

def der_cert(der_data):
    """Load a DER encoded certificate

    :param der_data: DER-encoded certificate
    :return: A cryptography.x509.certificate instance"""
    if isinstance(der_data, str):
        der_data = bytes(der_data, 'utf-8')
    return x509.load_der_x509_certificate(der_data, default_backend())

def load_x509_cert(url, httpc, spec2key, **get_args):
    """Get and transform a X509 cert into a key.

    :param url: Where the X509 cert can be found
    :param httpc: HTTP client to use for fetching
    :param spec2key: A dictionary over keys already seen
    :param get_args: Extra key word arguments to the HTTP GET request
    :return: List of 2-tuples (keytype, key)"""
    try:
        r = httpc('GET', url, allow_redirects=True, **get_args)
        if r.status_code == 200:
            cert = str(r.text)
            try:
                public_key = spec2key[cert]
            except KeyError:
                public_key = import_rsa_key(cert)
                spec2key[cert] = public_key
            if isinstance(public_key, rsa.RSAPublicKey):
                return {'rsa': public_key}
        else:
            raise Exception('HTTP Get error: %s' % r.status_code)
    except Exception as err:
        logger.warning("Can't load key: %s" % err)
        return []

def cmp_public_numbers(pn1, pn2):
    """Compare 2 sets of public numbers. These is a way to compare
    2 public RSA keys. If the sets are the same then the keys are the same.

    :param pn1: The set of values belonging to the 1st key
    :param pn2: The set of values belonging to the 2nd key
    :return: True is the sets are the same otherwise False."""
    if pn1.n == pn2.n:
        if pn1.e == pn2.e:
            return True
    return False

def cmp_private_numbers(pn1, pn2):
    """Compare 2 sets of private numbers. This is for comparing 2
    private RSA keys.

    :param pn1: The set of values belonging to the 1st key
    :param pn2: The set of values belonging to the 2nd key
    :return: True is the sets are the same otherwise False."""
    if not cmp_public_numbers(pn1.public_numbers, pn2.public_numbers):
        return False
    for param in ['d', 'p', 'q']:
        if getattr(pn1, param) != getattr(pn2, param):
            return False
    return True

def x5t_calculation(cert):
    """base64url-encoded SHA-1 thumbprint (a.k.a. digest) of the DER
    encoding of an X.509 certificate.

    :param cert: DER encoded X.509 certificate
    :return: x5t value"""
    if isinstance(cert, str):
        der_cert = base64.b64decode(cert.encode('ascii'))
    else:
        der_cert = base64.b64decode(cert)
    return b64e(hashlib.sha1(der_cert).digest())

def left_hash(msg, func='HS256'):
    """Calculate left hash as described in
    https://openid.net/specs/openid-connect-core-1_0.html#CodeIDToken
    for at_hash and in
    for c_hash

    :param msg: The message over which the hash should be calculated
    :param func: Which hash function that was used for the ID token"""
    if func == 'HS256':
        return as_unicode(b64e(sha256_digest(msg)[:16]))
    elif func == 'HS384':
        return as_unicode(b64e(sha384_digest(msg)[:24]))
    elif func == 'HS512':
        return as_unicode(b64e(sha512_digest(msg)[:32]))

def alg2keytype(alg):
    """Go from algorithm name to key type.

    :param alg: The algorithm name
    :return: The key type"""
    if not alg or alg.lower() == 'none':
        return 'none'
    elif alg.startswith('RS') or alg.startswith('PS'):
        return 'RSA'
    elif alg.startswith('HS') or alg.startswith('A'):
        return 'oct'
    elif alg.startswith('ES') or alg.startswith('ECDH-ES'):
        return 'EC'
    else:
        return None

def parse_rsa_algorithm(algorithm):
    """Parses a RSA algorithm and returns tuple (hash, padding).

    :param algorithm: string, RSA algorithm as defined at
        https://tools.ietf.org/html/rfc7518#section-3.1.
    :raises: UnsupportedAlgorithm: if the algorithm is not supported.
    :returns: (hash, padding) tuple."""
    if algorithm == 'RS256':
        return (hashes.SHA256(), padding.PKCS1v15())
    elif algorithm == 'RS384':
        return (hashes.SHA384(), padding.PKCS1v15())
    elif algorithm == 'RS512':
        return (hashes.SHA512(), padding.PKCS1v15())
    elif algorithm == 'PS256':
        return (hashes.SHA256(), padding.PSS(mgf=padding.MGF1(hashes.SHA256()), salt_length=padding.PSS.MAX_LENGTH))
    elif algorithm == 'PS384':
        return (hashes.SHA384(), padding.PSS(mgf=padding.MGF1(hashes.SHA384()), salt_length=padding.PSS.MAX_LENGTH))
    elif algorithm == 'PS512':
        return (hashes.SHA512(), padding.PSS(mgf=padding.MGF1(hashes.SHA512()), salt_length=padding.PSS.MAX_LENGTH))
    else:
        raise UnsupportedAlgorithm('Unknown algorithm: {}'.format(algorithm))

def base64url_to_long(data):
    """Stricter then base64_to_long since it really checks that it's
    base64url encoded

    :param data: The base64 string
    :return:"""
    _data = as_bytes(data)
    _d = base64.urlsafe_b64decode(_data + b'==')
    if [e for e in [b'+', b'/', b'='] if e in _data]:
        raise ValueError('Not base64url encoded')
    return intarr2long(struct.unpack('%sB' % len(_d), _d))

def b64d(b):
    """Decode some base64-encoded bytes.

    Raises BadSyntax if the string contains invalid characters or padding.

    :param b: bytes"""
    cb = b.rstrip(b'=')
    if not _b64_re.match(cb):
        raise BadSyntax(cb, 'base64-encoded data contains illegal characters')
    if cb == b:
        b = add_padding(b)
    return base64.urlsafe_b64decode(b)

def deser(val):
    """Deserialize from a string representation of an long integer
    to the python representation of a long integer.

    :param val: The string representation of the long integer.
    :return: The long integer."""
    if isinstance(val, str):
        _val = val.encode('utf-8')
    else:
        _val = val
    return base64_to_long(_val)

def transform_future(transformation, future):
    """Returns a new future that will resolve with a transformed value

    Takes the resolution value of `future` and applies transformation(*future.result())
    to it before setting the result of the new future with the transformed value. If
    future() resolves with an exception, it is passed through to the new future.

    Assumes `future` is a tornado Future."""
    new_future = tornado_Future()
    def _transform(f):
        assert f is future
        if f.exc_info() is not None:
            new_future.set_exc_info(f.exc_info())
        else:
            try:
                new_future.set_result(transformation(f.result()))
            except Exception:
                new_future.set_exc_info(sys.exc_info())
    future.add_done_callback(_transform)
    return new_future

def monitor_resource_sync_state(resource, callback, exit_event=None):
    """Coroutine that monitors a KATCPResource's sync state.

    Calls callback(True/False) whenever the resource becomes synced or unsynced. Will
    always do an initial callback(False) call. Exits without calling callback() if
    exit_event is set"""
    exit_event = exit_event or AsyncEvent()
    callback(False)
    while not exit_event.is_set():
        yield until_any(resource.until_synced(), exit_event.until_set())
        if exit_event.is_set():
            break
        else:
            callback(True)
        yield until_any(resource.until_not_synced(), exit_event.until_set())
        if exit_event.is_set():
            break
        else:
            callback(False)

def open_file(file, mode):
    """Open a file.

    :arg file: file-like or path-like object.
    :arg str mode: ``mode`` argument for :func:`open`."""
    if hasattr(file, 'read'):
        return file
    if hasattr(file, 'open'):
        return file.open(mode)
    return open(file, mode)

def normalize_strategy_parameters(params):
    """Normalize strategy parameters to be a list of strings.

    Parameters
    ----------
    params : (space-delimited) string or sequence of strings/numbers Parameters
        expected by :class:`SampleStrategy` object, in various forms, where the first
        parameter is the name of the strategy.

    Returns
    -------
    params : tuple of strings
        Strategy parameters as a list of strings"""
    def fixup_numbers(val):
        try:
            return str(float(val))
        except ValueError:
            return str(val)
    if isinstance(params, basestring):
        params = params.split(' ')
    return tuple((fixup_numbers(p) for p in params))

def update_in_ioloop(update):
    """Decorator that ensures an update() method is run in the tornado ioloop.

    Does this by checking the thread identity. Requires that the object to
    which the method is bound has the attributes :attr:`_ioloop_thread_id`
    (the result of thread.get_ident() in the ioloop thread) and :attr:`ioloop`
    (the ioloop instance in use). Also assumes the signature
    `update(self, sensor, reading)` for the method."""
    @wraps(update)
    def wrapped_update(self, sensor, reading):
        if get_thread_ident() == self._ioloop_thread_id:
            update(self, sensor, reading)
        else:
            self.ioloop.add_callback(update, self, sensor, reading)
    return wrapped_update

def unpack_types(types, args, argnames, major):
    """Parse arguments according to types list.

    Parameters
    ----------
    types : list of kattypes
        The types of the arguments (in order).
    args : list of strings
        The arguments to parse.
    argnames : list of strings
        The names of the arguments.
    major : integer
        Major version of KATCP to use when packing types"""
    if len(types) > 0:
        multiple = types[-1]._multiple
    else:
        multiple = False
    if len(types) < len(args) and (not multiple):
        raise FailReply('Too many parameters given.')
    params = []
    for i, kattype in enumerate(types):
        name = ''
        if i < len(argnames):
            name = argnames[i]
        params.append(Parameter(i + 1, name, kattype, major))
    if len(args) > len(types) and multiple:
        for i in range(len(types), len(args)):
            params.append(Parameter(i + 1, name, kattype, major))
    return map(lambda param, arg: param.unpack(arg), params, args)

def pack_types(types, args, major):
    """Pack arguments according the the types list.

    Parameters
    ----------
    types : list of kattypes
        The types of the arguments (in order).
    args : list of objects
        The arguments to format.
    major : integer
        Major version of KATCP to use when packing types"""
    if len(types) > 0:
        multiple = types[-1]._multiple
    else:
        multiple = False
    if len(types) < len(args) and (not multiple):
        raise ValueError('Too many arguments to pack.')
    if len(args) < len(types):
        retvals = map(lambda ktype, arg: ktype.pack(arg, major=major), types, args)
    else:
        retvals = [ktype.pack(arg, major=major) for ktype, arg in zip(types, args)]
    if len(args) > len(types) and multiple:
        last_ktype = types[-1]
        for arg in args[len(types):]:
            retvals.append(last_ktype.pack(arg, major=major))
    return retvals

def return_future(fn):
    """Decorator that turns a synchronous function into one returning a future.

    This should only be applied to non-blocking functions. Will do set_result()
    with the return value, or set_exc_info() if an exception is raised."""
    @wraps(fn)
    def decorated(*args, **kwargs):
        return gen.maybe_future(fn(*args, **kwargs))
    return decorated

def log_coroutine_exceptions(coro):
    """Coroutine (or any method that returns a future) decorator to log exceptions

    Example
    -------

    ::

    import logging

    class A(object):
        _logger = logging.getLogger(__name__)

        @log_coroutine_exceptions
        @tornado.gen.coroutine
        def raiser(self, arg):
            yield tornado.gen.moment
            raise Exception(arg)

    Assuming that your object (self) has a `_logger` attribute containing a
    logger instance"""
    def log_cb(self, f):
        try:
            f.result()
        except Exception:
            self._logger.exception('Unhandled exception calling coroutine {0!r}'.format(coro))
    @wraps(coro)
    def wrapped_coro(self, *args, **kwargs):
        try:
            f = coro(self, *args, **kwargs)
        except Exception:
            f = tornado_Future()
            f.set_exc_info(sys.exc_info())
        f.add_done_callback(partial(log_cb, self))
        return f
    return wrapped_coro

def steal_docstring_from(obj):
    """Decorator that lets you steal a docstring from another object

    Example
    -------

    ::

    @steal_docstring_from(superclass.meth)
    def meth(self, arg):
        "Extra subclass documentation"
        pass

    In this case the docstring of the new 'meth' will be copied from superclass.meth, and
    if an additional dosctring was defined for meth it will be appended to the superclass
    docstring with a two newlines inbetween."""
    def deco(fn):
        docs = [obj.__doc__]
        if fn.__doc__:
            docs.append(fn.__doc__)
        fn.__doc__ = '\n\n'.join(docs)
        return fn
    return deco

def hashable_identity(obj):
    """Generate a hashable ID that is stable for methods etc

    Approach borrowed from blinker. Why it matters: see e.g.
    http://stackoverflow.com/questions/13348031/python-bound-and-unbound-method-object"""
    if hasattr(obj, '__func__'):
        return (id(obj.__func__), id(obj.__self__))
    elif hasattr(obj, 'im_func'):
        return (id(obj.im_func), id(obj.im_self))
    elif isinstance(obj, (basestring, unicode)):
        return obj
    else:
        return id(obj)

def until_any(*futures, **kwargs):
    """Return a future that resolves when any of the passed futures resolves.

    Resolves with the value yielded by the first future to resolve.

    Note, this will only work with tornado futures."""
    timeout = kwargs.get('timeout', None)
    ioloop = kwargs.get('ioloop', None) or tornado.ioloop.IOLoop.current()
    any_future = tornado_Future()
    def handle_done(done_future):
        if not any_future.done():
            try:
                any_future.set_result(done_future.result())
            except Exception:
                any_future.set_exc_info(done_future.exc_info())
            for f in futures:
                if f._callbacks:
                    try:
                        f._callbacks.remove(handle_done)
                    except ValueError:
                        pass
    for f in futures:
        f.add_done_callback(handle_done)
        if any_future.done():
            break
    if timeout:
        return with_timeout(ioloop.time() + timeout, any_future, ioloop)
    else:
        return any_future

def alias(*aliases):
    """Decorator to add aliases for Cmdln.do_* command handlers.

    Example:
        class MyShell(cmdln.Cmdln):
            @cmdln.alias("!", "sh")
            def do_shell(self, argv):
                #...implement 'shell' command"""
    def decorate(f):
        if not hasattr(f, 'aliases'):
            f.aliases = []
        f.aliases += aliases
        return f
    return decorate

def option(*args, **kwargs):
    """Decorator to add an option to the optparser argument of a Cmdln
    subcommand.

    Example:
        class MyShell(cmdln.Cmdln):
            @cmdln.option("-f", "--force", help="force removal")
            def do_remove(self, subcmd, opts, *args):
                #..."""
    def decorate(f):
        if not hasattr(f, 'optparser'):
            f.optparser = SubCmdOptionParser()
        f.optparser.add_option(*args, **kwargs)
        return f
    return decorate

def _get_indent(marker, s, tab_width=8):
    """_get_indent(marker, s, tab_width=8) ->
    (<indentation-of-'marker'>, <indentation-width>)"""
    INDENT_CHARS = tuple(' \t')
    start = s.index(marker)
    i = start
    while i > 0:
        if s[i - 1] not in INDENT_CHARS:
            break
        i -= 1
    indent = s[i:start]
    indent_width = 0
    for ch in indent:
        if ch == ' ':
            indent_width += 1
        elif ch == '\t':
            indent_width += tab_width - indent_width % tab_width
    return (indent, indent_width)

def _get_trailing_whitespace(marker, s):
    """Return the whitespace content trailing the given 'marker' in string 's',
    up to and including a newline."""
    suffix = ''
    start = s.index(marker) + len(marker)
    i = start
    while i < len(s):
        if s[i] in ' \t':
            suffix += s[i]
        elif s[i] in '\r\n':
            suffix += s[i]
            if s[i] == '\r' and i + 1 < len(s) and (s[i + 1] == '\n'):
                suffix += s[i + 1]
            break
        else:
            break
        i += 1
    return suffix

def _getRegisteredExecutable(exeName):
    """Windows allow application paths to be registered in the registry."""
    registered = None
    if sys.platform.startswith('win'):
        if os.path.splitext(exeName)[1].lower() != '.exe':
            exeName += '.exe'
        import _winreg
        try:
            key = 'SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\App Paths\\' + exeName
            value = _winreg.QueryValue(_winreg.HKEY_LOCAL_MACHINE, key)
            registered = (value, 'from HKLM\\' + key)
        except _winreg.error:
            pass
        if registered and (not os.path.exists(registered[0])):
            registered = None
    return registered

def get_version():
    """Get the python-manta version without having to import the manta package,
    which requires deps to already be installed."""
    _globals = {}
    _locals = {}
    exec(compile(open(TOP + '/manta/version.py').read(), TOP + '/manta/version.py', 'exec'), _globals, _locals)
    return _locals['__version__']

def fingerprint_from_raw_ssh_pub_key(key):
    """Encode a raw SSH key (string of bytes, as from
    `str(paramiko.AgentKey)`) to a fingerprint in the typical
    '54:c7:4c:93:cf:ff:e3:32:68:bc:89:6e:5e:22:b5:9c' form."""
    fp_plain = hashlib.md5(key).hexdigest()
    return ':'.join((a + b for a, b in zip(fp_plain[::2], fp_plain[1::2])))

def agent_key_info_from_key_id(key_id):
    """Find a matching key in the ssh-agent.

    @param key_id {str} Either a private ssh key fingerprint, e.g.
        'b3:f0:a1:6c:18:3b:42:63:fd:6e:57:42:74:17:d4:bc', or the path to
        an ssh private key file (like ssh's IdentityFile config option).
    @return {dict} with these keys:
        - type: "agent"
        - agent_key: paramiko AgentKey
        - fingerprint: key fingerprint
        - algorithm: "rsa-sha1"  Currently don't support DSA agent signing."""
    if not FINGERPRINT_RE.match(key_id):
        ssh_key = load_ssh_key(key_id, True)
        fingerprint = ssh_key['fingerprint']
    else:
        fingerprint = key_id
    keys = Agent().get_keys()
    for key in keys:
        raw_key = key.blob
        md5_fp = fingerprint_from_raw_ssh_pub_key(raw_key)
        sha_fp = sha256_fingerprint_from_raw_ssh_pub_key(raw_key)
        if sha_fp == fingerprint or md5_fp == fingerprint or 'MD5:' + md5_fp == fingerprint:
            md5_fingerprint = md5_fp
            break
    else:
        raise MantaError('no ssh-agent key with fingerprint "%s"' % fingerprint)
    return {'type': 'agent', 'agent_key': key, 'fingerprint': md5_fingerprint, 'algorithm': ALGO_FROM_SSH_KEY_TYPE[key.name]}

def to_grpc_address(target: str) -> str:
    """Converts a standard gRPC target to one that is supported by grpcio

    :param target: the server address.
    :returns: the converted address."""
    u = urlparse(target)
    if u.scheme == 'dns':
        raise ValueError('dns:// not supported')
    if u.scheme == 'unix':
        return 'unix:' + u.path
    return u.netloc

def wrap_context(func):
    """Wraps the provided servicer method by passing a wrapped context

    The context is wrapped using `lookout.sdk.grpc.log_fields.LogFieldsContext`.

    :param func: the servicer method to wrap_context
    :returns: the wrapped servicer method"""
    @functools.wraps(func)
    def wrapper(self, request, context):
        return func(self, request, LogFieldsContext(context))
    return wrapper

def get_username(details, backend, response, *args, **kwargs):
    """Sets the `username` argument.

    If the user exists already, use the existing username. Otherwise
    generate username from the `new_uuid` using the
    `helusers.utils.uuid_to_username` function."""
    user = details.get('user')
    if not user:
        user_uuid = kwargs.get('uid')
        if not user_uuid:
            return
        username = uuid_to_username(user_uuid)
    else:
        username = user.username
    return {'username': username}

def patch_jwt_settings():
    """Patch rest_framework_jwt authentication settings from allauth"""
    defaults = api_settings.defaults
    defaults['JWT_PAYLOAD_GET_USER_ID_HANDLER'] = __name__ + '.get_user_id_from_payload_handler'
    if 'allauth.socialaccount' not in settings.INSTALLED_APPS:
        return
    from allauth.socialaccount.models import SocialApp
    try:
        app = SocialApp.objects.get(provider='helsinki')
    except SocialApp.DoesNotExist:
        return
    defaults['JWT_SECRET_KEY'] = app.secret
    defaults['JWT_AUDIENCE'] = app.client_id

def username_to_uuid(username):
    """Convert username to UUID.

    >>> username_to_uuid('u-ad52zgilvnpgnduefzlh5jgr6y')
    UUID('00fbac99-0bab-5e66-8e84-2e567ea4d1f6')"""
    if not username.startswith('u-') or len(username) != 28:
        raise ValueError('Not an UUID based username: %r' % (username,))
    decoded = base64.b32decode(username[2:].upper() + '======')
    return UUID(bytes=decoded)

def oidc_to_user_data(payload):
    """Map OIDC claims to Django user fields."""
    payload = payload.copy()
    field_map = {'given_name': 'first_name', 'family_name': 'last_name', 'email': 'email'}
    ret = {}
    for token_attr, user_attr in field_map.items():
        if token_attr not in payload:
            continue
        ret[user_attr] = payload.pop(token_attr)
    ret.update(payload)
    return ret

def get_function_by_path(dotted_function_module_path):
    """Returns the function for a given path (e.g. 'my_app.my_module.my_function')."""
    module_path, function_name = tuple(dotted_function_module_path.rsplit('.', 1))
    module = import_module(module_path)
    return getattr(module, function_name)

def get_mass(chebi_id):
    """Returns mass"""
    if len(__MASSES) == 0:
        __parse_chemical_data()
    return __MASSES[chebi_id] if chebi_id in __MASSES else float('NaN')

def get_charge(chebi_id):
    """Returns charge"""
    if len(__CHARGES) == 0:
        __parse_chemical_data()
    return __CHARGES[chebi_id] if chebi_id in __CHARGES else float('NaN')

def __parse_chemical_data():
    """Gets and parses file"""
    filename = get_file('chemical_data.tsv')
    with io.open(filename, 'r', encoding='cp1252') as textfile:
        next(textfile)
        for line in textfile:
            tokens = line.strip().split('\t')
            if tokens[3] == 'FORMULA':
                chebi_id = int(tokens[1])
                if chebi_id not in __FORMULAE:
                    __FORMULAE[chebi_id] = []
                form = Formula(tokens[4], tokens[2])
                __FORMULAE[chebi_id].append(form)
            elif tokens[3] == 'MASS':
                __MASSES[int(tokens[1])] = float(tokens[4])
            elif tokens[3] == 'CHARGE':
                __CHARGES[int(tokens[1])] = int(tokens[4] if tokens[4][-1] != '-' else '-' + tokens[4][:-1])

def __parse_compound_origins():
    """Gets and parses file"""
    filename = get_file('compound_origins.tsv')
    with io.open(filename, 'r', encoding='cp1252') as textfile:
        next(textfile)
        for line in textfile:
            tokens = line.strip().split('\t')
            if len(tokens) > 10:
                chebi_id = int(tokens[1])
                if chebi_id not in __COMPOUND_ORIGINS:
                    __COMPOUND_ORIGINS[chebi_id] = []
                comp_orig = CompoundOrigin(tokens[2], tokens[3], tokens[4], tokens[5], tokens[6], tokens[7], tokens[8], tokens[9], tokens[10])
                __COMPOUND_ORIGINS[chebi_id].append(comp_orig)

def get_parent_id(chebi_id):
