def get_mol(chebi_id):
    """Returns mol"""
    chebi_id_regexp = '^\\d+\\,' + str(chebi_id) + '\\,.*'
    mol_file_end_regexp = '",mol,\\dD'
    this_structure = []
    filename = get_file('structures.csv.gz')
    with io.open(filename, 'r', encoding='cp1252') as textfile:
        in_chebi_id = False
        next(textfile)
        for line in textfile:
            if in_chebi_id or line[0].isdigit():
                if re.match(chebi_id_regexp, line) and int(line.split(',')[0]) in __get_default_structure_ids():
                    tokens = line.strip().split(',')
                    in_chebi_id = True
                    this_structure = []
                    this_structure.append(','.join(tokens[2:]).replace('"', ''))
                    this_structure.append('\n')
                elif in_chebi_id:
                    if re.match(mol_file_end_regexp, line):
                        tokens = line.strip().split(',')
                        this_structure.append(tokens[0].replace('"', ''))
                        return Structure(''.join(this_structure), Structure.mol, int(tokens[2][0]))
                    else:
                        this_structure.append(line)
    return None

def __parse_structures():
    """COMMENT"""
    filename = get_file('structures.csv.gz')
    with io.open(filename, 'r', encoding='cp1252') as textfile:
        next(textfile)
        for line in textfile:
            tokens = line.strip().split(',')
            if len(tokens) == 5:
                if tokens[3] == 'InChIKey':
                    __INCHI_KEYS[int(tokens[1])] = Structure(tokens[2], Structure.InChIKey, int(tokens[4][0]))
                elif tokens[3] == 'SMILES':
                    __SMILES[int(tokens[1])] = Structure(tokens[2], Structure.SMILES, int(tokens[4][0]))

def __get_default_structure_ids():
    """COMMENT"""
    if len(__DEFAULT_STRUCTURE_IDS) == 0:
        filename = get_file('default_structures.tsv')
        with io.open(filename, 'r', encoding='cp1252') as textfile:
            next(textfile)
            for line in textfile:
                tokens = line.strip().split('\t')
                __DEFAULT_STRUCTURE_IDS.append(int(tokens[1]))
    return __DEFAULT_STRUCTURE_IDS

def __is_current(filepath):
    """Checks whether file is current"""
    if not __DOWNLOAD_PARAMS['auto_update']:
        return True
    if not os.path.isfile(filepath):
        return False
    return datetime.datetime.utcfromtimestamp(os.path.getmtime(filepath)) > __get_last_update_time()

def __get_last_update_time():
    """Returns last FTP site update time"""
    now = datetime.datetime.utcnow()
    first_tuesday = __get_first_tuesday(now)
    if first_tuesday < now:
        return first_tuesday
    else:
        first_of_month = datetime.datetime(now.year, now.month, 1)
        last_month = first_of_month + datetime.timedelta(days=-1)
        return __get_first_tuesday(last_month)

def get_frontend_data_dict_for_cms_page(cms_page, cms_page_title, request, editable=False):
    """Returns the data dictionary of a CMS page that is used by the frontend."""
    placeholders = list(cms_page.placeholders.all())
    placeholder_frontend_data_dict = get_frontend_data_dict_for_placeholders(placeholders=placeholders, request=request, editable=editable)
    global_placeholder_data_dict = get_global_placeholder_data(placeholder_frontend_data_dict)
    data = {'containers': placeholder_frontend_data_dict, 'meta': {'title': cms_page_title.page_title if cms_page_title.page_title else cms_page_title.title, 'description': cms_page_title.meta_description or ''}}
    language_links = get_language_links(cms_page=cms_page, request=request)
    if language_links:
        data['meta']['languages'] = language_links
    if placeholder_frontend_data_dict:
        data['containers'] = placeholder_frontend_data_dict
    if global_placeholder_data_dict:
        data['global_placeholder_data'] = global_placeholder_data_dict
    post_processer = settings.DJANGOCMS_SPA_CMS_PAGE_DATA_POST_PROCESSOR
    if post_processer:
        func = get_function_by_path(post_processer)
        data = func(cms_page=cms_page, data=data, request=request)
    return data

def get_frontend_data_dict_for_plugin(request, plugin, editable):
    """Returns a serializable data dict of a CMS plugin and all its children. It expects a `render_json_plugin()` method
    from each plugin. Make sure you implement it for your custom plugins and monkey patch all third-party plugins."""
    json_data = {}
    instance, plugin = plugin.get_plugin_instance()
    if not instance:
        return json_data
    renderer = renderer_pool.renderer_for_plugin(plugin)
    if renderer:
        json_data = renderer.render(request=request, plugin=plugin, instance=instance, editable=editable)
    if hasattr(plugin, 'parse_child_plugins') and plugin.parse_child_plugins:
        children = []
        for child_plugin in instance.get_children().order_by(settings.DJANGOCMS_SPA_PLUGIN_ORDER_FIELD):
            children.append(get_frontend_data_dict_for_plugin(request=request, plugin=child_plugin, editable=editable))
        if children:
            json_data['plugins'] = children
    return json_data

def get_global_placeholder_data(placeholder_frontend_data_dict):
    """In some rare cases you need to post process the placeholder data and add additional, global data to the route
    object. Define your post-processor in the DJANGOCMS_SPA_VUE_JS_PLACEHOLDER_DATA_POST_PROCESSOR setting variable
    (e.g. `my_app.my_module.my_function` and return the data you need."""
    post_processer = settings.DJANGOCMS_SPA_PLACEHOLDER_DATA_POST_PROCESSOR
    if not post_processer:
        return {}
    func = get_function_by_path(post_processer)
    return func(placeholder_frontend_data_dict=placeholder_frontend_data_dict)

