def run(cmds, **kwargs):
    """Wrapper around subprocess.run, with unicode decoding of output.

    Additional kwargs are passed to subprocess.run."""
    proc = sp.Popen(cmds, bufsize=-1, stdout=sp.PIPE, stderr=sp.STDOUT, close_fds=sys.platform != 'win32')
    for line in proc.stdout:
        print(line[:-1].decode())
    retcode = proc.wait()
    if retcode:
        raise sp.CalledProcessError(retcode, cmds)

def stage(x, staging):
    """Stage an object to the `staging` directory.

    If the object is a Track and is one of the types that needs an index file
    (bam, vcfTabix), then the index file will be staged as well.

    Returns a list of the linknames created."""
    linknames = []
    non_file_objects = (track.ViewTrack, track.CompositeTrack, track.AggregateTrack, track.SuperTrack, genome.Genome)
    if isinstance(x, non_file_objects):
        return linknames
    linknames.append(x.render(staging))
    if hasattr(x, 'source') and hasattr(x, 'filename'):
        def _stg(x, ext=''):
            if x.source is None and x.filename is None and (getattr(x, 'url', None) is not None):
                return
            linknames.append(local_link(x.source + ext, x.filename + ext, staging))
        _stg(x)
        if isinstance(x, track.Track):
            if x.tracktype == 'bam':
                _stg(x, ext='.bai')
            if x.tracktype == 'vcfTabix':
                _stg(x, ext='.tbi')
        if isinstance(x, track.CompositeTrack):
            if x._html:
                _stg(x._html)
    return linknames

def stage_hub(hub, staging=None):
    """Stage a hub by symlinking all its connected files to a local directory."""
    linknames = []
    if staging is None:
        staging = tempfile.mkdtemp()
    for obj, level in hub.leaves(base.HubComponent, intermediate=True):
        linknames.extend(stage(obj, staging))
    return (staging, linknames)

def _get_ldflags():
    """Determine the correct link flags.  This attempts dummy compiles similar
    to how autotools does feature detection."""
    if sys.platform == 'win32':
        prefix = getattr(sys, 'real_prefix', sys.prefix)
        libs = os.path.join(prefix, str('libs'))
        return str('-L{} -lpython{}{}').format(libs, *sys.version_info[:2])
    cc = subprocess.check_output(('go', 'env', 'CC')).decode('UTF-8').strip()
    with _tmpdir() as tmpdir:
        testf = os.path.join(tmpdir, 'test.c')
        with io.open(testf, 'w') as f:
            f.write('int f(int); int main(void) { return f(0); }\n')
        for lflag in LFLAGS:
            try:
                subprocess.check_call((cc, testf, lflag), cwd=tmpdir)
                return lflag
            except subprocess.CalledProcessError:
                pass
        else:
            return LFLAG_GCC

def cmd_string(name, cmd):
    """Define a string parameter coming from a shell command to be used within
    this YAML file. Trailing newlines will be stripped."""
    value = subprocess.check_output(cmd, shell=True).rstrip('\n')
    return Define(name, value)

def make_view(controller, context, data):
    """Make a View subclass containing properties specific for given data

    Args:
        controller (Controller): The child controller that hosts the data
        context (Context): The context the parent has made that the View should
            use for manipulating the data
        data (Model): The actual data that context will be manipulating

    Returns:
        View: A View subclass instance that provides a user-focused API to
            the given data"""
    if isinstance(data, BlockModel):
        view = _make_view_subclass(Block, controller, context, data)
    elif isinstance(data, AttributeModel):
        view = Attribute(controller, context, data)
    elif isinstance(data, MethodModel):
        view = Method(controller, context, data)
    elif isinstance(data, Model):
        view = _make_view_subclass(View, controller, context, data)
    elif isinstance(data, dict):
        d = OrderedDict()
        for k, v in data.items():
            d[k] = make_view(controller, context, v)
        view = d
    elif isinstance(data, list):
        view = [make_view(controller, context, x) for x in data]
    else:
        view = data
    return view

