def dictstr(arg):
    """Parse a key=value string as a tuple (key, value) that can be provided as an argument to dict()"""
    key, value = arg.split('=')
    if value.lower() == 'true' or value.lower() == 'false':
        value = bool(value)
    elif INT_RE.match(value):
        value = int(value)
    elif FLOAT_RE.match(value):
        value = float(value)
    return (key, value)

def translate(patterns, *, flags=0):
    """Translate `fnmatch` pattern."""
    flags = _flag_transform(flags)
    return _wcparse.translate(_wcparse.split(patterns, flags), flags)

def is_negative(pattern, flags):
    """Check if negative pattern."""
    if flags & MINUSNEGATE:
        return flags & NEGATE and pattern[0:1] in MINUS_NEGATIVE_SYM
    else:
        return flags & NEGATE and pattern[0:1] in NEGATIVE_SYM

def expand_braces(patterns, flags):
    """Expand braces."""
    if flags & BRACE:
        for p in [patterns] if isinstance(patterns, (str, bytes)) else patterns:
            try:
                yield from bracex.iexpand(p, keep_escapes=True)
            except Exception:
                yield p
    else:
        for p in [patterns] if isinstance(patterns, (str, bytes)) else patterns:
            yield p

def get_case(flags):
    """Parse flags for case sensitivity settings."""
    if not bool(flags & CASE_FLAGS):
        case_sensitive = util.is_case_sensitive()
    elif flags & FORCECASE:
        case_sensitive = True
    else:
        case_sensitive = False
    return case_sensitive

def is_unix_style(flags):
    """Check if we should use Unix style."""
    return (util.platform() != 'windows' or (not bool(flags & REALPATH) and get_case(flags))) and (not flags & _FORCEWIN)

def translate(patterns, flags):
    """Translate patterns."""
    positive = []
    negative = []
    if isinstance(patterns, (str, bytes)):
        patterns = [patterns]
    flags |= _TRANSLATE
    for pattern in patterns:
        for expanded in expand_braces(pattern, flags):
            (negative if is_negative(expanded, flags) else positive).append(WcParse(expanded, flags & FLAG_MASK).parse())
    if patterns and flags & REALPATH and negative and (not positive):
        positive.append(_compile(b'**' if isinstance(patterns[0], bytes) else '**', flags))
    return (positive, negative)

def compile(patterns, flags):
    """Compile patterns."""
    positive = []
    negative = []
    if isinstance(patterns, (str, bytes)):
        patterns = [patterns]
    for pattern in patterns:
        for expanded in expand_braces(pattern, flags):
            (negative if is_negative(expanded, flags) else positive).append(_compile(expanded, flags))
    if patterns and flags & REALPATH and negative and (not positive):
        positive.append(_compile(b'**' if isinstance(patterns[0], bytes) else '**', flags))
    return WcRegexp(tuple(positive), tuple(negative), flags & REALPATH, flags & PATHNAME, flags & FOLLOW)

def _compile(pattern, flags):
    """Compile the pattern to regex."""
    return re.compile(WcParse(pattern, flags & FLAG_MASK).parse())

def _fs_match(pattern, filename, sep, follow, symlinks):
    """Match path against the pattern.

    Since `globstar` doesn't match symlinks (unless `FOLLOW` is enabled), we must look for symlinks.
    If we identify a symlink in a `globstar` match, we know this result should not actually match."""
    matched = False
    base = None
    m = pattern.fullmatch(filename)
    if m:
        matched = True
        if not follow:
            groups = m.groups()
            last = len(groups)
            for i, star in enumerate(m.groups(), 1):
                if star:
                    parts = star.strip(sep).split(sep)
                    if base is None:
                        base = filename[:m.start(i)]
                    for part in parts:
                        base = os.path.join(base, part)
                        is_link = symlinks.get(base, None)
                        if is_link is not None:
                            matched = not is_link
                        elif i != last or os.path.isdir(base):
                            is_link = os.path.islink(base)
                            symlinks[base] = is_link
                            matched = not is_link
                        if not matched:
                            break
                if matched:
                    break
    return matched

def _match_real(filename, include, exclude, follow, symlinks):
    """Match real filename includes and excludes."""
    sep = '\\' if util.platform() == 'windows' else '/'
    if isinstance(filename, bytes):
        sep = os.fsencode(sep)
    if not filename.endswith(sep) and os.path.isdir(filename):
        filename += sep
    matched = False
    for pattern in include:
        if _fs_match(pattern, filename, sep, follow, symlinks):
            matched = True
            break
    if matched:
        matched = True
        if exclude:
            for pattern in exclude:
                if _fs_match(pattern, filename, sep, follow, symlinks):
                    matched = False
                    break
    return matched

def _match_pattern(filename, include, exclude, real, path, follow):
    """Match includes and excludes."""
    if real:
        symlinks = {}
        if isinstance(filename, bytes):
            curdir = os.fsencode(os.curdir)
            mount = RE_BWIN_MOUNT if util.platform() == 'windows' else RE_BMOUNT
        else:
            curdir = os.curdir
            mount = RE_WIN_MOUNT if util.platform() == 'windows' else RE_MOUNT
        if not mount.match(filename):
            exists = os.path.lexists(os.path.join(curdir, filename))
        else:
            exists = os.path.lexists(filename)
        if not exists:
            return False
        if path:
            return _match_real(filename, include, exclude, follow, symlinks)
    matched = False
    for pattern in include:
        if pattern.fullmatch(filename):
            matched = True
            break
    if not include and exclude:
        matched = True
    if matched:
        matched = True
        if exclude:
            for pattern in exclude:
                if not pattern.fullmatch(filename):
                    matched = False
                    break
    return matched

def _flag_transform(flags):
    """Transform flags to glob defaults."""
    flags = flags & FLAG_MASK | _wcparse.PATHNAME
    if flags & _wcparse.REALPATH and util.platform() == 'windows':
        flags |= _wcparse._FORCEWIN
        if flags & _wcparse.FORCECASE:
            flags ^= _wcparse.FORCECASE
    return flags

def glob(patterns, *, flags=0):
    """Glob."""
    return list(iglob(util.to_tuple(patterns), flags=flags))

def globmatch(filename, patterns, *, flags=0):
    """Check if filename matches pattern.

    By default case sensitivity is determined by the file system,
    but if `case_sensitive` is set, respect that instead."""
    flags = _flag_transform(flags)
    if not _wcparse.is_unix_style(flags):
        filename = util.norm_slash(filename)
    return _wcparse.compile(_wcparse.split(patterns, flags), flags).match(filename)

def globfilter(filenames, patterns, *, flags=0):
    """Filter names using pattern."""
    matches = []
    flags = _flag_transform(flags)
    unix = _wcparse.is_unix_style(flags)
    obj = _wcparse.compile(_wcparse.split(patterns, flags), flags)
    for filename in filenames:
        if not unix:
            filename = util.norm_slash(filename)
        if obj.match(filename):
            matches.append(filename)
    return matches

def raw_escape(pattern, unix=False):
    """Apply raw character transform before applying escape."""
    pattern = util.norm_pattern(pattern, False, True)
    return escape(pattern, unix)

def escape(pattern, unix=False):
    """Escape."""
    is_bytes = isinstance(pattern, bytes)
    replace = b'\\\\\\1' if is_bytes else '\\\\\\1'
    win = util.platform() == 'windows'
    if win and (not unix):
        magic = _wcparse.RE_BWIN_MAGIC if is_bytes else _wcparse.RE_WIN_MAGIC
    else:
        magic = _wcparse.RE_BMAGIC if is_bytes else _wcparse.RE_MAGIC
    drive = b'' if is_bytes else ''
    if win and (not unix):
        m = (_wcparse.RE_BWIN_PATH if is_bytes else _wcparse.RE_WIN_PATH).match(pattern)
        if m:
            drive = m.group(0)
    pattern = pattern[len(drive):]
    return drive + magic.sub(replace, pattern)

def norm_slash(name):
    """Normalize path slashes."""
    if isinstance(name, str):
        return name.replace('/', '\\') if not is_case_sensitive() else name
    else:
        return name.replace(b'/', b'\\') if not is_case_sensitive() else name

def is_hidden(path):
    """Check if file is hidden."""
    hidden = False
    f = os.path.basename(path)
    if f[:1] in ('.', b'.'):
        hidden = True
    elif _PLATFORM == 'windows':
        FILE_ATTRIBUTE_HIDDEN = 2
        if PY35:
            results = os.lstat(path)
            hidden = bool(results.st_file_attributes & FILE_ATTRIBUTE_HIDDEN)
        else:
            if isinstance(path, bytes):
                attrs = ctypes.windll.kernel32.GetFileAttributesA(path)
            else:
                attrs = ctypes.windll.kernel32.GetFileAttributesW(path)
            hidden = attrs != -1 and attrs & FILE_ATTRIBUTE_HIDDEN
    elif _PLATFORM == 'osx':
        results = os.lstat(path)
        hidden = bool(results.st_flags & stat.UF_HIDDEN)
    return hidden

