def allowed_transitions():
    """Get target states allowed for the current state."""
    try:
        sdp_state = SDPState()
        return sdp_state.allowed_target_states[sdp_state.current_state]
    except KeyError:
        LOG.error('Key Error')
        return dict(state='KeyError', reason='KeyError')

def get_state():
    """SDP State.

    Return current state; target state and allowed
    target states."""
    sdp_state = SDPState()
    errval, errdict = _check_status(sdp_state)
    if errval == 'error':
        LOG.debug(errdict['reason'])
        return dict(current_state='unknown', target_state='unknown', last_updated='unknown', reason=errdict['reason'])
    _last_updated = sdp_state.current_timestamp
    if sdp_state.target_timestamp > _last_updated:
        _last_updated = sdp_state.target_timestamp
    return (dict(current_state=sdp_state.current_state, target_state=sdp_state.target_state, allowed_target_states=sdp_state.allowed_target_states[sdp_state.current_state], last_updated=_last_updated.isoformat()), HTTPStatus.OK)

def get_target_state():
    """SDP target State.

    Returns the target state; allowed target states and time updated"""
    sdp_state = SDPState()
    errval, errdict = _check_status(sdp_state)
    if errval == 'error':
        LOG.debug(errdict['reason'])
        return dict(current_target_state='unknown', last_updated='unknown', reason=errdict['reason'])
    LOG.debug('Getting target state')
    target_state = sdp_state.target_state
    LOG.debug('Target state = %s', target_state)
    return dict(current_target_state=target_state, allowed_target_states=sdp_state.allowed_target_states[sdp_state.current_state], last_updated=sdp_state.target_timestamp.isoformat())

def get_current_state():
    """Return the SDP State and the timestamp for when it was updated."""
    sdp_state = SDPState()
    errval, errdict = _check_status(sdp_state)
    if errval == 'error':
        LOG.debug(errdict['reason'])
        return dict(current_state='unknown', last_updated='unknown', reason=errdict['reason'])
    LOG.debug('Current State: %s', sdp_state.current_state)
    LOG.debug('Current State last updated: %s', sdp_state.current_timestamp.isoformat())
