def de_blank(val):
    """Remove blank elements in `val` and return `ret`"""
    ret = list(val)
    if type(val) == list:
        for idx, item in enumerate(val):
            if item.strip() == '':
                ret.remove(item)
            else:
                ret[idx] = item.strip()
    return ret

def parse_string(data, unquote=default_unquote):
    """Decode URL-encoded strings to UTF-8 containing the escaped chars.
    """
    if data is None:
        return None
    if isinstance(data, bytes):
        if sys.version_info > (3, 0, 0):
            data = data.decode('ascii')
    unquoted = unquote(data)
    if isinstance(unquoted, bytes):
        unquoted = unquoted.decode('utf-8')
    return unquoted

def parse_date(value):
    """Parse an RFC 1123 or asctime-like format date string to produce
    a Python datetime object (without a timezone)."""
    match = Definitions.DATE_RE.match(value) if value else None
    if not match:
        return None
    data = {}
    captured = match.groupdict()
    fields = ['year', 'month', 'day', 'hour', 'minute', 'second']
    if captured['year']:
        for field in fields:
            data[field] = captured[field]
    else:
        for field in fields:
            data[field] = captured[field + '2']
    year = data['year']
    if len(year) == 2:
        if int(year) < 70:
            year = '20' + year
        else:
            year = '19' + year
    year = int(year)
    data['year'] = max(1900, min(year, 9999))
    for field in ['day', 'hour', 'minute', 'second']:
        if data[field] is None:
            data[field] = 0
        data[field] = int(data[field])
    data['month'] = Definitions.month_numbers[data['month'].lower()]
    return datetime.datetime(**data)

def parse_value(value, allow_spaces=True, unquote=default_unquote):
    """Process a cookie value"""
    if value is None:
        return None
    value = strip_spaces_and_quotes(value)
    value = parse_string(value, unquote=unquote)
    if not allow_spaces:
        assert ' ' not in value
    return value

def valid_name(name):
    """Validate a cookie name string"""
    if isinstance(name, bytes):
        name = name.decode('ascii')
    if not Definitions.COOKIE_NAME_RE.match(name):
        return False
    if name[0] == '$':
        return False
    return True

def valid_domain(domain):
    """Validate a cookie domain ASCII string"""
    domain.encode('ascii')
    if Definitions.DOMAIN_RE.match(domain):
        return True
    return False

def valid_path(value):
    """Validate a cookie path ASCII string"""
    value.encode('ascii')
    if not (value and value[0] == '/'):
        return False
    if not Definitions.PATH_RE.match(value):
        return False
    return True

def valid_max_age(number):
    """Validate a cookie Max-Age"""
    if isinstance(number, basestring):
        try:
            number = long(number)
        except (ValueError, TypeError):
            return False
    if number >= 0 and number % 1 == 0:
        return True
    return False

def _parse_request(header_data, ignore_bad_cookies=False):
    """Turn one or more lines of 'Cookie:' header data into a dict mapping
    cookie names to cookie values (raw strings)."""
    cookies_dict = {}
    for line in Definitions.EOL.split(header_data.strip()):
        matches = Definitions.COOKIE_RE.finditer(line)
        matches = [item for item in matches]
        for match in matches:
            invalid = match.group('invalid')
            if invalid:
                if not ignore_bad_cookies:
                    raise InvalidCookieError(data=invalid)
                _report_invalid_cookie(invalid)
                continue
            name = match.group('name')
            values = cookies_dict.get(name)
            value = match.group('value').strip('"')
            if values:
                values.append(value)
            else:
                cookies_dict[name] = [value]
        if not matches:
            if not ignore_bad_cookies:
                raise InvalidCookieError(data=line)
            _report_invalid_cookie(line)
    return cookies_dict

def parse_one_response(line, ignore_bad_cookies=False, ignore_bad_attributes=True):
    """Turn one 'Set-Cookie:' line into a dict mapping attribute names to
    attribute values (raw strings)."""
    cookie_dict = {}
    match = Definitions.SET_COOKIE_HEADER_RE.match(line)
    if not match:
        if not ignore_bad_cookies:
            raise InvalidCookieError(data=line)
        _report_invalid_cookie(line)
        return None
    cookie_dict.update({'name': match.group('name'), 'value': match.group('value')})
    for match in Definitions.ATTR_RE.finditer(match.group('attrs')):
        captured = dict(((k, v) for k, v in match.groupdict().items() if v))
        unrecognized = captured.get('unrecognized', None)
        if unrecognized:
            if not ignore_bad_attributes:
                raise InvalidCookieAttributeError(None, unrecognized, 'unrecognized')
            _report_unknown_attribute(unrecognized)
            continue
        for key in ('secure', 'httponly'):
            if captured.get(key):
                captured[key] = True
        timekeys = ('weekday', 'month', 'day', 'hour', 'minute', 'second', 'year')
        if 'year' in captured:
            for key in timekeys:
                del captured[key]
        elif 'year2' in captured:
            for key in timekeys:
                del captured[key + '2']
        cookie_dict.update(captured)
    return cookie_dict

def _parse_response(header_data, ignore_bad_cookies=False, ignore_bad_attributes=True):
    """Turn one or more lines of 'Set-Cookie:' header data into a list of dicts
    mapping attribute names to attribute values (as plain strings)."""
    cookie_dicts = []
    for line in Definitions.EOL.split(header_data.strip()):
        if not line:
            break
        cookie_dict = parse_one_response(line, ignore_bad_cookies=ignore_bad_cookies, ignore_bad_attributes=ignore_bad_attributes)
        if not cookie_dict:
            continue
        cookie_dicts.append(cookie_dict)
    if not cookie_dicts:
        if not ignore_bad_cookies:
            raise InvalidCookieError(data=header_data)
        _report_invalid_cookie(header_data)
    return cookie_dicts

def aorb(a, b):
    """Return a matrix of logic comparison of A or B"""
    return matrix(np.logical_or(a, b).astype('float'), a.size)

def aandb(a, b):
    """Return a matrix of logic comparison of A or B"""
    return matrix(np.logical_and(a, b).astype('float'), a.size)

def not0(a):
    """Return u if u!= 0, return 1 if u == 0"""
    return matrix(list(map(lambda x: 1 if x == 0 else x, a)), a.size)

def sort(m, reverse=False):
    """Return sorted m (default: ascending order)"""
    ty = type(m)
    if ty == matrix:
        m = list(m)
    m = sorted(m, reverse=reverse)
    if ty == matrix:
        m = matrix(m)
    return m

def sort_idx(m, reverse=False):
    """Return the indices of m in sorted order (default: ascending order)"""
    return sorted(range(len(m)), key=lambda k: m[k], reverse=reverse)

def to_number(s):
    """Convert a string to a number.
    If not successful, return the string without blanks"""
    ret = s
    try:
        ret = float(s)
    except ValueError:
        ret = ret.strip("'").strip()
    try:
        ret = int(s)
    except ValueError:
        pass
    if ret == 'True':
        ret = True
    elif ret == 'False':
        ret = False
    elif ret == 'None':
        ret = None
    return ret

def sdiv(a, b):
    """Safe division: if a == b == 0, sdiv(a, b) == 1"""
    if len(a) != len(b):
        raise ValueError('Argument a and b does not have the same length')
    idx = 0
    ret = matrix(0, (len(a), 1), 'd')
    for m, n in zip(a, b):
        try:
            ret[idx] = m / n
        except ZeroDivisionError:
            ret[idx] = 1
        finally:
            idx += 1
    return ret

def generate_unique_host_id():
    """Generate a unique ID, that is somewhat guaranteed to be unique among all
    instances running at the same time."""
    host = '.'.join(reversed(socket.gethostname().split('.')))
    pid = os.getpid()
    return '%s.%d' % (host, pid)

