def anchor(parser, token):
    """Parses a tag that's supposed to be in this format '{% anchor field title %}'
    Title may be a "string", _("trans string"), or variable"""
    bits = [b for b in token.split_contents()]
    if len(bits) < 2:
        raise template.TemplateSyntaxError('anchor tag takes at least 1 argument.')
    title_is_var = False
    try:
        title = bits[2]
        if title[0] in ('"', "'"):
            if title[0] == title[-1]:
                title = title[1:-1]
            else:
                raise template.TemplateSyntaxError('anchor tag title must be a "string", _("trans string"), or variable')
        elif title.startswith('_("') or title.startswith("_('"):
            title = _(title[3:-2])
        else:
            title_is_var = True
    except IndexError:
        title = bits[1].capitalize()
    return SortAnchorNode(bits[1].strip(), title.strip(), title_is_var)

def build(documentPath, outputUFOFormatVersion=3, roundGeometry=True, verbose=True, logPath=None, progressFunc=None, processRules=True, logger=None, useVarlib=False):
    """Simple builder for UFO designspaces."""
    import os, glob
    if os.path.isdir(documentPath):
        todo = glob.glob(os.path.join(documentPath, '*.designspace'))
    else:
        todo = [documentPath]
    results = []
    for path in todo:
        document = DesignSpaceProcessor(ufoVersion=outputUFOFormatVersion)
        document.useVarlib = useVarlib
        document.roundGeometry = roundGeometry
        document.read(path)
