def skeleton_length(labels, indices=None):
    """Compute the length of all skeleton branches for labeled skeletons

    labels - a labels matrix
    indices - the indexes of the labels to be measured. Default is all

    returns an array of one skeleton length per label."""
    global __skel_length_table
    if __skel_length_table is None:
        tbl = np.zeros(512, np.float32)
        for ii in range(-1, 2):
            for jj in range(-1, 2):
                if ii == 0 and jj == 0:
                    continue
                idx = 2 ** (ii + 1 + (jj + 1) * 3) | 16
                mask = np.arange(512) & idx == idx
                if ii != 0 and jj != 0:
                    for adjacent_i, adjacent_j in ((ii - 1, jj), (ii, jj - 1), (ii + 1, jj), (ii, jj + 1)):
                        if any([_ < -1 or _ > 1 for _ in (adjacent_i, adjacent_j)]):
                            continue
                        aidx = 2 ** (adjacent_i + 1 + (adjacent_j + 1) * 3)
                        mask = mask & (np.arange(512) & aidx != aidx)
                tbl[mask] += np.sqrt(ii * ii + jj * jj) / 2
        __skel_length_table = tbl
    if indices is None:
        indices = np.arange(1, np.max(labels) + 1)
    else:
        indices = np.asanyarray(indices)
    if len(indices) == 0:
        return np.zeros(0)
    score = __skel_length_table[table_idx_from_labels(labels)]
    result = np.bincount(labels.ravel(), weights=score.ravel(), minlength=np.max(indices) + 1)
    return result[indices]

def stretch(image, mask=None):
    """Normalize an image to make the minimum zero and maximum one

    image - pixel data to be normalized
    mask  - optional mask of relevant pixels. None = don't mask

    returns the stretched image"""
    image = np.array(image, float)
    if np.product(image.shape) == 0:
        return image
    if mask is None:
        minval = np.min(image)
        maxval = np.max(image)
        if minval == maxval:
            if minval < 0:
                return np.zeros_like(image)
            elif minval > 1:
                return np.ones_like(image)
            return image
        else:
            return (image - minval) / (maxval - minval)
    else:
        significant_pixels = image[mask]
        if significant_pixels.size == 0:
            return image
        minval = np.min(significant_pixels)
        maxval = np.max(significant_pixels)
        if minval == maxval:
            transformed_image = minval
        else:
            transformed_image = (significant_pixels - minval) / (maxval - minval)
        result = image.copy()
        image[mask] = transformed_image
        return image

def reverse_velocity_kalman_model():
    """Return a KalmanState set up to model going backwards in time"""
    om = np.array([[1, 0, 0, 0], [0, 1, 0, 0]])
    tm = np.array([[1, 0, -1, 0], [0, 1, 0, -1], [0, 0, 1, 0], [0, 0, 0, 1]])
    return KalmanState(om, tm)

def prcntiles(x, percents):
    """Equivalent to matlab prctile(x,p), uses linear interpolation."""
    x = np.array(x).flatten()
    listx = np.sort(x)
    xpcts = []
    lenlistx = len(listx)
    refs = []
    for i in range(0, lenlistx):
        r = 100 * ((0.5 + i) / lenlistx)
        refs.append(r)
    rpcts = []
    for p in percents:
        if p < refs[0]:
            rpcts.append(listx[0])
        elif p > refs[-1]:
            rpcts.append(listx[-1])
        else:
            for j in range(0, lenlistx):
                if refs[j] <= p and refs[j + 1] >= p:
                    my = listx[j + 1] - listx[j]
                    mx = refs[j + 1] - refs[j]
                    m = my / mx
                    rpcts.append(m * (p - refs[j]) + listx[j])
                    break
    xpcts.append(rpcts)
    return np.array(xpcts).transpose()

def automode(data):
    """Tries to guess if the image contains dark objects on a bright background (1)
    or if the image contains bright objects on a dark background (-1),
    or if it contains both dark and bright objects on a gray background (0)."""
    pct = prcntiles(np.array(data), [1, 20, 80, 99])
    upper = pct[3] - pct[2]
    mid = pct[2] - pct[1]
    lower = pct[1] - pct[0]
    if upper > mid:
        uo = 1
    else:
        uo = 0
    if lower > mid:
        lo = 1
    else:
        lo = 0
    if uo == 1:
        if lo == 1:
            mode = 0
        else:
            mode = -1
    elif lo == 1:
        mode = 1
    else:
        mode = 0
    return mode

def gauss(x, m_y, sigma):
    """returns the gaussian with mean m_y and std. dev. sigma,
    calculated at the points of x."""
    e_y = [np.exp(1.0 / (2 * float(sigma) ** 2) * -(n - m_y) ** 2) for n in np.array(x)]
    y = [1.0 / (float(sigma) * np.sqrt(2 * np.pi)) * e for e in e_y]
    return np.array(y)

def splinefit2d(x, y, z, px, py, mask=None):
    """Make a least squares fit of the spline (px,py,pz) to the surface (x,y,z).
    If mask is given, only masked points are used for the regression."""
    if mask is None:
        V = np.array(spline_matrix2d(x, y, px, py))
        a = np.array(z.T.flatten())
        pz = np.linalg.lstsq(V.T, a.T)[0].T
    else:
        V = np.array(spline_matrix2d(x, y, px, py, mask))
        indices = np.nonzero(np.array(mask).T.flatten())
        if len(indices[0]) == 0:
            pz = np.zeros((len(py), len(px)))
        else:
            a = np.array(z.T.flatten()[indices[0]])
            pz = np.linalg.lstsq(V.T, a.T)[0].T
    pz = pz.reshape((len(py), len(px)))
    return pz.transpose()

def get_global_threshold(threshold_method, image, mask=None, **kwargs):
    """Compute a single threshold over the whole image"""
    if mask is not None and (not np.any(mask)):
        return 1
    if threshold_method == TM_OTSU:
        fn = get_otsu_threshold
    elif threshold_method == TM_MOG:
        fn = get_mog_threshold
    elif threshold_method == TM_BACKGROUND:
        fn = get_background_threshold
    elif threshold_method == TM_ROBUST_BACKGROUND:
        fn = get_robust_background_threshold
    elif threshold_method == TM_RIDLER_CALVARD:
        fn = get_ridler_calvard_threshold
    elif threshold_method == TM_KAPUR:
        fn = get_kapur_threshold
    elif threshold_method == TM_MCT:
        fn = get_maximum_correlation_threshold
    else:
        raise NotImplementedError('%s algorithm not implemented' % threshold_method)
    kwargs = dict([(k, v) for k, v in kwargs.items() if k in fn.args])
    return fn(image, mask, **kwargs)

def mad(a):
    """Calculate the median absolute deviation of a sample

    a - a numpy array-like collection of values

    returns the median of the deviation of a from its median."""
    a = np.asfarray(a).flatten()
    return np.median(np.abs(a - np.median(a)))

def weighted_variance(image, mask, binary_image):
    """Compute the log-transformed variance of foreground and background

    image - intensity image used for thresholding

    mask - mask of ignored pixels

    binary_image - binary image marking foreground and background"""
    if not np.any(mask):
        return 0
    minval = np.max(image[mask]) / 256
    if minval == 0:
        return 0
    fg = np.log2(np.maximum(image[binary_image & mask], minval))
    bg = np.log2(np.maximum(image[~binary_image & mask], minval))
    nfg = np.product(fg.shape)
    nbg = np.product(bg.shape)
    if nfg == 0:
        return np.var(bg)
    elif nbg == 0:
        return np.var(fg)
    else:
        return (np.var(fg) * nfg + np.var(bg) * nbg) / (nfg + nbg)

def numpy_histogram(a, bins=10, range=None, normed=False, weights=None):
    """A version of numpy.histogram that accounts for numpy's version"""
    args = inspect.getargs(np.histogram.__code__)[0]
    if args[-1] == 'new':
        return np.histogram(a, bins, range, normed, weights, new=True)
    return np.histogram(a, bins, range, normed, weights)

def quantize(image, nlevels):
    """Quantize an image into integers 0, 1, ..., nlevels - 1.

    image   -- a numpy array of type float, range [0, 1]
    nlevels -- an integer"""
    tmp = np.array(image // (1.0 / nlevels), dtype='i1')
    return tmp.clip(0, nlevels - 1)

def _join_chars(chars, length):
    """Used by the random character functions."""
    mult = int(length / len(chars)) + 1
    mult_chars = chars * mult
    return ''.join(random.sample(mult_chars, length))

def random_unicode(length=20):
    """Generates a random name; useful for testing.

    Returns an encoded string of the specified length containing unicode values
    up to code point 1000."""
    def get_char():
        return six.unichr(random.randint(32, 1000))
    chars = u''.join([get_char() for ii in six.moves.range(length)])
    return _join_chars(chars, length)

def coerce_to_list(val):
    """For parameters that can take either a single string or a list of strings,
    this function will ensure that the result is a list containing the passed
    values."""
    if val:
        if not isinstance(val, (list, tuple)):
            val = [val]
    else:
        val = []
    return val

def folder_size(pth, ignore=None):
    """Returns the total bytes for the specified path, optionally ignoring
    any files which match the 'ignore' parameter. 'ignore' can either be
    a single string pattern, or a list of such patterns."""
    if not os.path.isdir(pth):
        raise exc.FolderNotFound
    ignore = coerce_to_list(ignore)
    total = 0
    for root, _, names in os.walk(pth):
        paths = [os.path.realpath(os.path.join(root, nm)) for nm in names]
        for pth in paths[::-1]:
            if not os.path.exists(pth):
                paths.remove(pth)
            elif match_pattern(pth, ignore):
                paths.remove(pth)
        total += sum((os.stat(pth).st_size for pth in paths))
    return total

def _wait_until(obj, att, desired, callback, interval, attempts, verbose, verbose_atts):
    """Loops until either the desired value of the attribute is reached, or the
    number of attempts is exceeded."""
    if not isinstance(desired, (list, tuple)):
        desired = [desired]
    if verbose_atts is None:
        verbose_atts = []
    if not isinstance(verbose_atts, (list, tuple)):
        verbose_atts = [verbose_atts]
    infinite = attempts == 0
    attempt = 0
    start = time.time()
    while infinite or attempt < attempts:
        try:
            obj.get()
        except AttributeError:
            try:
                obj = obj.manager.get(obj.id)
            except AttributeError:
                raise exc.NoReloadError("The 'wait_until' method is not supported for '%s' objects." % obj.__class__)
        attval = getattr(obj, att)
        if verbose:
            elapsed = time.time() - start
            msgs = ['Current value of %s: %s (elapsed: %4.1f seconds)' % (att, attval, elapsed)]
            for vatt in verbose_atts:
                vattval = getattr(obj, vatt, None)
                msgs.append('%s=%s' % (vatt, vattval))
            print(' '.join(msgs))
        if attval in desired:
            return obj
        time.sleep(interval)
        attempt += 1
    return obj

def _parse_datetime_string(val):
    """Attempts to parse a string representation of a date or datetime value, and
    returns a datetime if successful. If not, a InvalidDateTimeString exception
    will be raised."""
    dt = None
    lenval = len(val)
    fmt = {19: '%Y-%m-%d %H:%M:%S', 10: '%Y-%m-%d'}.get(lenval)
    if fmt is None:
        raise exc.InvalidDateTimeString("The supplied value '%s' does not match either of the formats 'YYYY-MM-DD HH:MM:SS' or 'YYYY-MM-DD'." % val)
    return datetime.datetime.strptime(val, fmt)

def iso_time_string(val, show_tzinfo=False):
    """Takes either a date, datetime or a string, and returns the standard ISO
    formatted string for that date/time, with any fractional second portion
    removed."""
    if not val:
        return ''
    if isinstance(val, six.string_types):
        dt = _parse_datetime_string(val)
    else:
        dt = val
    if not isinstance(dt, datetime.datetime):
        dt = datetime.datetime.fromordinal(dt.toordinal())
    has_tz = dt.tzinfo is not None
    if show_tzinfo and has_tz:
        ret = ''.join(dt.isoformat().rsplit(':', 1))
    elif show_tzinfo and (not has_tz):
        ret = '%s+0000' % dt.isoformat().split('.')[0]
    elif not show_tzinfo and has_tz:
        ret = dt.isoformat()[:-6]
    elif not show_tzinfo and (not has_tz):
        ret = dt.isoformat().split('.')[0]
    return ret

def rfc2822_format(val):
    """Takes either a date, a datetime, or a string, and returns a string that
    represents the value in RFC 2822 format. If a string is passed it is
    returned unchanged."""
    if isinstance(val, six.string_types):
        return val
    elif isinstance(val, (datetime.datetime, datetime.date)):
        val = time.mktime(val.timetuple())
    if isinstance(val, numbers.Number):
        return email.utils.formatdate(val)
    else:
        return val

def to_timestamp(val):
    """Takes a value that is either a Python date, datetime, or a string
    representation of a date/datetime value. Returns a standard Unix timestamp
    corresponding to that value."""
    if isinstance(val, numbers.Number):
        return val
    elif isinstance(val, six.string_types):
        dt = _parse_datetime_string(val)
    else:
        dt = val
    return time.mktime(dt.timetuple())

def get_id(id_or_obj):
