def matrixToMathTransform(matrix):
    """Take a 6-tuple and return a ShallowTransform object."""
    if isinstance(matrix, ShallowTransform):
        return matrix
    off, scl, rot = MathTransform(matrix).decompose()
    return ShallowTransform(off, scl, rot)

def mathTransformToMatrix(mathTransform):
    """Take a ShallowTransform object and return a 6-tuple."""
    m = MathTransform().compose(mathTransform.offset, mathTransform.scale, mathTransform.rotation)
    return tuple(m)

def _linearInterpolationTransformMatrix(matrix1, matrix2, value):
    """Linear, 'oldstyle' interpolation of the transform matrix."""
    return tuple((_interpolateValue(matrix1[i], matrix2[i], value) for i in range(len(matrix1))))

def _polarDecomposeInterpolationTransformation(matrix1, matrix2, value):
    """Interpolate using the MathTransform method."""
    m1 = MathTransform(matrix1)
    m2 = MathTransform(matrix2)
    return tuple(m1.interpolate(m2, value))

def find_version(file_path):
    """Scrape version information from specified file path."""
    with open(file_path, 'r') as f:
        file_contents = f.read()
    version_match = re.search('^__version__\\s*=\\s*[\'\\"]([^\'\\"]*)[\'\\"]', file_contents, re.M)
    if version_match:
        return version_match.group(1)
    else:
        raise RuntimeError('unable to find version string')

def smtp_connection(c):
    """Create an SMTP connection from a Config object"""
    if c.smtp_ssl:
        klass = smtplib.SMTP_SSL
    else:
        klass = smtplib.SMTP
    conn = klass(c.smtp_host, c.smtp_port, timeout=c.smtp_timeout)
    if not c.smtp_ssl:
        conn.ehlo()
        conn.starttls()
        conn.ehlo()
    if c.smtp_username:
        conn.login(c.smtp_username, c.smtp_password)
    return conn

def get_version():
    """Read the version from a file (mollie/api/version.py) in the repository.

    We can't import here since we might import from an installed version."""
    try:
        version_file = open(os.path.join(ROOT_DIR, 'mollie', 'api', 'version.py'), encoding='utf=8')
    except TypeError:
        version_file = open(os.path.join(ROOT_DIR, 'mollie', 'api', 'version.py'))
    contents = version_file.read()
    match = re.search('VERSION = [\\\'"]([^\\\'"]+)', contents)
    if match:
        return match.group(1)
    else:
        raise RuntimeError("Can't determine package version")

def generate_querystring(params):
    """Generate a querystring suitable for use in the v2 api.

    The Requests library doesn't know how to generate querystrings that encode dictionaries using square brackets:
    https://api.mollie.com/v2/methods?amount[value]=100.00&amount[currency]=USD

    Note: we use `sorted()` to work around a difference in iteration behaviour between Python 2 and 3.
    This makes the output predictable, and ordering of querystring parameters shouldn't matter."""
    if not params:
        return None
    parts = []
    for param, value in sorted(params.items()):
        if not isinstance(value, dict):
            parts.append(urlencode({param: value}))
        else:
            for key, sub_value in sorted(value.items()):
                composed = '{param}[{key}]'.format(param=param, key=key)
                parts.append(urlencode({composed: sub_value}))
    if parts:
        return '&'.join(parts)

def check_channel(fcn):
    """Decorator that ensures a valid channel passed in.

    Args:
        fcn (function): Function that has a ChannelResource as its second argument.

    Returns:
        (function): Wraps given function with one that checks for a valid channel."""
    def wrapper(*args, **kwargs):
        if not isinstance(args[1], ChannelResource):
            raise RuntimeError('resource must be an instance of intern.resource.boss.ChannelResource.')
        if not args[1].cutout_ready:
            raise PartialChannelResourceError('ChannelResource not fully initialized.  Use intern.remote.BossRemote.get_channel({}, {}, {})'.format(args[1].name, args[1].coll_name, args[1].exp_name))
        return fcn(*args, **kwargs)
    return wrapper

def _parse_arg_list(arglist):
    """Parses a list of arguments.

    Arguments are expected to be split by a comma, surrounded by any amount
    of whitespace. Arguments are then run through Python's eval() method."""
    args = []
    for arg in arglist.split(','):
        arg = arg.strip()
        if arg:
            args.append(eval(arg))
    return args

def _parse_action(action):
    """Parses a single action item, for instance one of the following:

        m; m(); m(True); m(*)

    The brackets must match."""
    i_open = action.find('(')
    if i_open is -1:
        return {'name': action, 'args': [], 'event_args': False}
    i_close = action.rfind(')')
    if i_close is -1:
        raise Exception('Bracket in argument opened but not closed.')
    action_name = action[:i_open]
    arglist = action[i_open + 1:i_close].strip()
    if not arglist:
        return {'name': action_name, 'args': [], 'event_args': False}
    if '*' in arglist:
        return {'name': action_name, 'args': [], 'event_args': True}
    return {'name': action_name, 'args': _parse_arg_list(arglist), 'event_args': False}

def views(model: 'Model') -> list:
