    return model._model_views[:]

def view(model: 'Model', *functions: Callable) -> Optional[Callable]:
    """A decorator for registering a callback to a model

    Parameters:
        model: the model object whose changes the callback should respond to.

    Examples:
        .. code-block:: python

            from spectate import mvc

            items = mvc.List()

            @mvc.view(items)
            def printer(items, events):
                for e in events:
                    print(e)

            items.append(1)"""
    if not isinstance(model, Model):
        raise TypeError('Expected a Model, not %r.' % model)
    def setup(function: Callable):
        model._model_views.append(function)
        return function
    if functions:
        for f in functions:
            setup(f)
    else:
        return setup

def serve_static(app, base_url, base_path, index=False):
    """Serve a directory statically

    Parameters:

        * app: Grole application object
        * base_url: Base URL to serve from, e.g. /static
        * base_path: Base path to look for files in
        * index: Provide simple directory indexes if True"""
    @app.route(base_url + '/(.*)')
    def serve(env, req):
        """Static files"""
        try:
            base = pathlib.Path(base_path).resolve()
            path = (base / req.match.group(1)).resolve()
        except FileNotFoundError:
            return Response(None, 404, 'Not Found')
        if base == path or base in path.parents:
            if path.is_file():
                return ResponseFile(str(path))
            if index and path.is_dir():
                if base == path:
                    ret = ''
                else:
                    ret = '<a href="../">../</a><br/>\r\n'
                for item in path.iterdir():
                    name = item.parts[-1]
                    if item.is_dir():
                        name += '/'
                    ret += '<a href="{}">{}</a><br/>\r\n'.format(urllib.parse.quote(name), html.escape(name))
                ret = ResponseString(ret, 'text/html')
                return ret
        return Response(None, 404, 'Not Found')

def serve_doc(app, url):
    """Serve API documentation extracted from request handler docstrings

    Parameters:
        * app: Grole application object
        * url: URL to serve at"""
    @app.route(url, doc=False)
    def index(env, req):
        ret = ''
        for d in env['doc']:
            ret += 'URL: {url}, supported methods: {methods}{doc}\n'.format(**d)
        return ret

def main(args=sys.argv[1:]):
    """Run Grole static file server"""
    args = parse_args(args)
    if args.verbose:
        logging.basicConfig(level=logging.DEBUG)
    elif args.quiet:
        logging.basicConfig(level=logging.ERROR)
    else:
        logging.basicConfig(level=logging.INFO)
    app = Grole()
    serve_static(app, '', args.directory, not args.noindex)
    app.run(args.address, args.port)

def watchable(value):
    """Returns True if the given value is a :class:`Watchable` subclass or instance."""
    check = issubclass if inspect.isclass(value) else isinstance
    return check(value, Watchable)

def unwatch(value):
    """Return the :class:`Specatator` of a :class:`Watchable` instance."""
    if not isinstance(value, Watchable):
        raise TypeError('Expected a Watchable, not %r.' % value)
    spectator = watcher(value)
    try:
        del value._instance_spectator
    except Exception:
        pass
    return spectator

def is_valid_github_uri(uri: URI, expected_path_terms: Tuple[str, ...]) -> bool:
    '''Return a bool indicating whether or not the URI fulfills the following specs
    Valid Github URIs *must*:
    - Have 'https' scheme
    - Have 'api.github.com' authority
    - Have a path that contains all "expected_path_terms"'''
    if not is_text(uri):
        return False
    parsed = parse.urlparse(uri)
    path, scheme, authority = (parsed.path, parsed.scheme, parsed.netloc)
    if not all((path, scheme, authority)):
        return False
    if any((term for term in expected_path_terms if term not in path)):
        return False
    if scheme != 'https':
        return False
    if authority != GITHUB_API_AUTHORITY:
        return False
    return True

def is_supported_content_addressed_uri(uri: URI) -> bool:
    """Returns a bool indicating whether provided uri is currently supported.
    Currently Py-EthPM only supports IPFS and Github blob content-addressed uris."""
    if not is_ipfs_uri(uri) and (not is_valid_content_addressed_github_uri(uri)):
        return False
    return True

def create_BIP122_uri(chain_id: str, resource_type: str, resource_identifier: str) -> URI:
    """See: https://github.com/bitcoin/bips/blob/master/bip-0122.mediawiki"""
    if resource_type != BLOCK:
        raise ValueError("Invalid resource_type.  Must be one of 'block'")
    elif not is_block_or_transaction_hash(resource_identifier):
        raise ValueError('Invalid resource_identifier.  Must be a hex encoded 32 byte value')
    elif not is_block_or_transaction_hash(chain_id):
        raise ValueError('Invalid chain_id.  Must be a hex encoded 32 byte value')
    return URI(parse.urlunsplit(['blockchain', remove_0x_prefix(chain_id), f'{resource_type}/{remove_0x_prefix(resource_identifier)}', '', '']))

def dummy_ipfs_pin(path: Path) -> Dict[str, str]:
    """Return IPFS data as if file was pinned to an actual node."""
    ipfs_return = {'Hash': generate_file_hash(path.read_bytes()), 'Name': path.name, 'Size': str(path.stat().st_size)}
    return ipfs_return

def extract_ipfs_path_from_uri(value: str) -> str:
    """Return the path from an IPFS URI.
    Path = IPFS hash & following path."""
    parse_result = parse.urlparse(value)
    if parse_result.netloc:
        if parse_result.path:
            return ''.join((parse_result.netloc, parse_result.path.rstrip('/')))
        else:
            return parse_result.netloc
    else:
        return parse_result.path.strip('/')

def is_ipfs_uri(value: str) -> bool:
    """Return a bool indicating whether or not the value is a valid IPFS URI."""
    parse_result = parse.urlparse(value)
    if parse_result.scheme != 'ipfs':
        return False
    if not parse_result.netloc and (not parse_result.path):
        return False
    return True

def validate_address(address: Any) -> None:
    """Raise a ValidationError if an address is not canonicalized."""
    if not is_address(address):
        raise ValidationError(f'Expected an address, got: {address}')
    if not is_canonical_address(address):
        raise ValidationError(f'Py-EthPM library only accepts canonicalized addresses. {address} is not in the accepted format.')

def validate_package_name(pkg_name: str) -> None:
    """Raise an exception if the value is not a valid package name
    as defined in the EthPM-Spec."""
    if not bool(re.match(PACKAGE_NAME_REGEX, pkg_name)):
        raise ValidationError(f'{pkg_name} is not a valid package name.')

def validate_registry_uri_authority(auth: str) -> None:
    """Raise an exception if the authority is not a valid ENS domain
    or a valid checksummed contract address."""
    if is_ens_domain(auth) is False and (not is_checksum_address(auth)):
        raise ValidationError(f'{auth} is not a valid registry URI authority.')

def validate_registry_uri_version(query: str) -> None:
    """Raise an exception if the version param is malformed."""
    query_dict = parse.parse_qs(query, keep_blank_values=True)
    if 'version' not in query_dict:
        raise ValidationError(f'{query} is not a correctly formatted version param.')

def validate_single_matching_uri(all_blockchain_uris: List[str], w3: Web3) -> str:
    """Return a single block URI after validating that it is the *only* URI in
    all_blockchain_uris that matches the w3 instance."""
    matching_uris = [uri for uri in all_blockchain_uris if check_if_chain_matches_chain_uri(w3, uri)]
    if not matching_uris:
        raise ValidationError('Package has no matching URIs on chain.')
    elif len(matching_uris) != 1:
        raise ValidationError(f'Package has too many ({len(matching_uris)}) matching URIs: {matching_uris}.')
    return matching_uris[0]

def validate_meta_object(meta: Dict[str, Any], allow_extra_meta_fields: bool) -> None:
    """Validates that every key is one of `META_FIELDS` and has a value of the expected type."""
    for key, value in meta.items():
        if key in META_FIELDS:
            if type(value) is not META_FIELDS[key]:
                raise ValidationError(f'Values for {key} are expected to have the type {META_FIELDS[key]}, instead got {type(value)}.')
        elif allow_extra_meta_fields:
            if key[:2] != 'x-':
                raise ValidationError(f"Undefined meta fields need to begin with 'x-', {key} is not a valid undefined meta field.")
        else:
            raise ValidationError(f'{key} is not a permitted meta field. To allow undefined fields, set `allow_extra_meta_fields` to True.')

def validate_manifest_against_schema(manifest: Dict[str, Any]) -> None:
    """Load and validate manifest against schema
    located at MANIFEST_SCHEMA_PATH."""
    schema_data = _load_schema_data()
    try:
        validate(manifest, schema_data)
    except jsonValidationError as e:
        raise ValidationError(f"Manifest invalid for schema version {schema_data['version']}. Reason: {e.message}")

def validate_manifest_deployments(manifest: Dict[str, Any]) -> None:
    """Validate that a manifest's deployments contracts reference existing contract_types."""
    if set(('contract_types', 'deployments')).issubset(manifest):
        all_contract_types = list(manifest['contract_types'].keys())
        all_deployments = list(manifest['deployments'].values())
        all_deployment_names = extract_contract_types_from_deployments(all_deployments)
        missing_contract_types = set(all_deployment_names).difference(all_contract_types)
        if missing_contract_types:
            raise ValidationError(f'Manifest missing references to contracts: {missing_contract_types}.')

def build(obj: Dict[str, Any], *fns: Callable[..., Any]) -> Dict[str, Any]:
    """Wrapper function to pipe manifest through build functions.
    Does not validate the manifest by default."""
    return pipe(obj, *fns)

def get_names_and_paths(compiler_output: Dict[str, Any]) -> Dict[str, str]:
    """Return a mapping of contract name to relative path as defined in compiler output."""
    return {contract_name: make_path_relative(path) for path in compiler_output for contract_name in compiler_output[path].keys()}

def make_path_relative(path: str) -> str:
    """Returns the given path prefixed with "./" if the path
    is not already relative in the compiler output."""
    if '../' in path:
        raise ManifestBuildingError(f'Path: {path} appears to be outside of the virtual source tree. Please make sure all sources are within the virtual source tree root directory.')
    if path[:2] != './':
        return f'./{path}'
    return path

def filter_all_data_by_selected_fields(all_type_data: Dict[str, Any], selected_fields: List[str]) -> Iterable[Tuple[str, Any]]:
    """Raises exception if selected field data is not available in the contract type data
    automatically gathered by normalize_compiler_output. Otherwise, returns the data."""
    for field in selected_fields:
        if field in all_type_data:
            yield (field, all_type_data[field])
        else:
            raise ManifestBuildingError(f'Selected field: {field} not available in data collected from solc output: {list(sorted(all_type_data.keys()))}. Please make sure the relevant data is present in your solc output.')

def normalize_compiler_output(compiler_output: Dict[str, Any]) -> Dict[str, Any]:
    """Return compiler output with normalized fields for each contract type,
    as specified in `normalize_contract_type`."""
    paths_and_names = [(path, contract_name) for path in compiler_output for contract_name in compiler_output[path].keys()]
    paths, names = zip(*paths_and_names)
    if len(names) != len(set(names)):
        raise ManifestBuildingError('Duplicate contract names were found in the compiler output.')
    return {name: normalize_contract_type(compiler_output[path][name]) for path, name in paths_and_names}

def normalize_contract_type(contract_type_data: Dict[str, Any]) -> Iterable[Tuple[str, Any]]:
    """Serialize contract_data found in compiler output to the defined fields."""
    yield ('abi', contract_type_data['abi'])
    if 'evm' in contract_type_data:
        if 'bytecode' in contract_type_data['evm']:
            yield ('deployment_bytecode', normalize_bytecode_object(contract_type_data['evm']['bytecode']))
        if 'deployedBytecode' in contract_type_data['evm']:
            yield ('runtime_bytecode', normalize_bytecode_object(contract_type_data['evm']['deployedBytecode']))
    if any((key in contract_type_data for key in NATSPEC_FIELDS)):
        natspec = deep_merge_dicts(contract_type_data.get('userdoc', {}), contract_type_data.get('devdoc', {}))
        yield ('natspec', natspec)
    if 'metadata' in contract_type_data and contract_type_data['metadata']:
        yield ('compiler', normalize_compiler_object(json.loads(contract_type_data['metadata'])))

def deployment_type(*, contract_instance: str, contract_type: str, deployment_bytecode: Dict[str, Any]=None, runtime_bytecode: Dict[str, Any]=None, compiler: Dict[str, Any]=None) -> Manifest:
    """Returns a callable that allows the user to add deployments of the same type
    across multiple chains."""
    return _deployment_type(contract_instance, contract_type, deployment_bytecode, runtime_bytecode, compiler)

def deployment(*, block_uri: URI, contract_instance: str, contract_type: str, address: HexStr, transaction: HexStr=None, block: HexStr=None, deployment_bytecode: Dict[str, Any]=None, runtime_bytecode: Dict[str, Any]=None, compiler: Dict[str, Any]=None) -> Manifest:
    """Returns a manifest, with the newly included deployment. Requires a valid blockchain URI,
    however no validation is provided that this URI is unique amongst the other deployment
    URIs, so the user must take care that each blockchain URI represents a unique blockchain."""
    return _deployment(contract_instance, contract_type, deployment_bytecode, runtime_bytecode, compiler, block_uri, address, transaction, block)

def _build_deployments_object(contract_type: str, deployment_bytecode: Dict[str, Any], runtime_bytecode: Dict[str, Any], compiler: Dict[str, Any], address: HexStr, tx: HexStr, block: HexStr, manifest: Dict[str, Any]) -> Iterable[Tuple[str, Any]]:
    """Returns a dict with properly formatted deployment data."""
    yield ('contract_type', contract_type)
    yield ('address', to_hex(address))
    if deployment_bytecode:
        yield ('deployment_bytecode', deployment_bytecode)
    if compiler:
        yield ('compiler', compiler)
    if tx:
        yield ('transaction', tx)
    if block:
        yield ('block', block)
    if runtime_bytecode:
        yield ('runtime_bytecode', runtime_bytecode)

def init_manifest(package_name: str, version: str, manifest_version: Optional[str]='2') -> Dict[str, Any]:
    """Returns an initial dict with the minimal requried fields for a valid manifest.
    Should only be used as the first fn to be piped into a `build()` pipeline."""
    return {'package_name': package_name, 'version': version, 'manifest_version': manifest_version}

def get_linked_deployments(deployments: Dict[str, Any]) -> Dict[str, Any]:
    """Returns all deployments found in a chain URI's deployment data that contain link dependencies."""
    linked_deployments = {dep: data for dep, data in deployments.items() if get_in(('runtime_bytecode', 'link_dependencies'), data)}
    for deployment, data in linked_deployments.items():
        if any((link_dep['value'] == deployment for link_dep in data['runtime_bytecode']['link_dependencies'])):
            raise BytecodeLinkingError(f'Link dependency found in {deployment} deployment that references its own contract instance, which is disallowed')
    return linked_deployments

def normalize_linked_references(data: List[Dict[str, Any]]) -> Generator[Tuple[int, str, str], None, None]:
    """Return a tuple of information representing all insertions of a linked reference.
    (offset, type, value)"""
    for deployment in data:
        for offset in deployment['offsets']:
            yield (offset, deployment['type'], deployment['value'])

def is_prelinked_bytecode(bytecode: bytes, link_refs: List[Dict[str, Any]]) -> bool:
    """Returns False if all expected link_refs are unlinked, otherwise returns True.
    todo support partially pre-linked bytecode (currently all or nothing)"""
    for link_ref in link_refs:
        for offset in link_ref['offsets']:
            try:
                validate_empty_bytes(offset, link_ref['length'], bytecode)
            except ValidationError:
                return True
    return False

def apply_link_ref(offset: int, length: int, value: bytes, bytecode: bytes) -> bytes:
    """Returns the new bytecode with `value` put into the location indicated by `offset` and `length`."""
    try:
        validate_empty_bytes(offset, length, bytecode)
    except ValidationError:
        raise BytecodeLinkingError('Link references cannot be applied to bytecode')
    new_bytes = bytecode[:offset] + value + bytecode[offset + length:]
    return new_bytes

def validate_minimal_contract_factory_data(contract_data: Dict[str, str]) -> None:
    """Validate that contract data in a package contains at least an "abi" and
    "deployment_bytecode" necessary to generate a deployable contract factory."""
    if not all((key in contract_data.keys() for key in ('abi', 'deployment_bytecode'))):
        raise InsufficientAssetsError('Minimum required contract data to generate a deployable contract factory (abi & deployment_bytecode) not found.')

def generate_contract_factory_kwargs(contract_data: Dict[str, Any]) -> Generator[Tuple[str, Any], None, None]:
    """Build a dictionary of kwargs to be passed into contract factory."""
    if 'abi' in contract_data:
        yield ('abi', contract_data['abi'])
    if 'deployment_bytecode' in contract_data:
        yield ('bytecode', contract_data['deployment_bytecode']['bytecode'])
        if 'link_references' in contract_data['deployment_bytecode']:
            yield ('unlinked_references', tuple(contract_data['deployment_bytecode']['link_references']))
    if 'runtime_bytecode' in contract_data:
        yield ('bytecode_runtime', contract_data['runtime_bytecode']['bytecode'])
        if 'link_references' in contract_data['runtime_bytecode']:
            yield ('linked_references', tuple(contract_data['runtime_bytecode']['link_references']))

def is_ens_domain(authority: str) -> bool:
    """Return false if authority is not a valid ENS domain."""
    if authority[-4:] != '.eth' or len(authority.split('.')) not in [2, 3]:
        return False
    return True

def _get_line_no_from_comments(py_line):
    """Return the line number parsed from the comment or 0."""
    matched = LINECOL_COMMENT_RE.match(py_line)
    if matched:
        return int(matched.group(1))
    else:
        return 0

def _find_bounds(py_line_no, py_by_line_no, cheetah_by_line_no):
    """Searches before and after in the python source to find comments which
    denote cheetah line numbers.  If a lower bound is not found, 0 is
    substituted.  If an upper bound is not found, len(cheetah lines) is
    returned.  The result is a lower-inclusive upper-exclusive range:
    [..., ...)"""
    for line_no in range(py_line_no, 0, -1):
        lower_bound = _get_line_no_from_comments(py_by_line_no[line_no])
        if lower_bound != 0:
            break
    else:
        lower_bound = 0
    for line_no in range(py_line_no, len(py_by_line_no)):
        upper_bound = _get_line_no_from_comments(py_by_line_no[line_no])
        if upper_bound != 0:
            upper_bound += 1
            break
    else:
        upper_bound = len(cheetah_by_line_no)
    return (lower_bound, upper_bound)

def _find_fuzzy_line(py_line_no, py_by_line_no, cheetah_by_line_no, prefer_first):
    """Attempt to fuzzily find matching lines."""
    stripped_line = _fuzz_py_line(py_by_line_no[py_line_no])
    cheetah_lower_bound, cheetah_upper_bound = _find_bounds(py_line_no, py_by_line_no, cheetah_by_line_no)
    sliced = list(enumerate(cheetah_by_line_no))[cheetah_lower_bound:cheetah_upper_bound]
    if not prefer_first:
        sliced = reversed(sliced)
    for line_no, line in sliced:
        if stripped_line in _fuzz_cheetah_line(line):
            return line_no
    else:
        return 0

def _get_parameters(link, encoding):
    """Generates Swagger Parameter Item object."""
    parameters = []
    properties = {}
    required = []
    for field in link.fields:
        parser = OpenApiFieldParser(link, field)
        if parser.location == 'form':
            if encoding in ('multipart/form-data', 'application/x-www-form-urlencoded'):
                parameters.append(parser.as_parameter())
            else:
                properties[field.name] = parser.as_schema_property()
                if field.required:
                    required.append(field.name)
        elif parser.location == 'body':
            parameters.append(parser.as_body_parameter(encoding))
        else:
            parameters.append(parser.as_parameter())
    if properties:
        parameter = {'name': 'data', 'in': 'body', 'schema': {'type': 'object', 'properties': properties}}
        if required:
            parameter['schema']['required'] = required
        parameters.append(parameter)
    return parameters

def get_native_default_args():
    """Get the correct set of batch jobs arguments.
    """
    native_default_args = dict(max_jobs=500, time_per_cycle=15, jobs_per_cycle=20, max_job_age=90, no_batch=False)
    return native_default_args.copy()

def log_level(level):
    """This is a function that returns a python like
    level from a HEASOFT like level."""
    levels_dict = {0: 50, 1: 40, 2: 30, 3: 20, 4: 10}
    if not isinstance(level, int):
        level = int(level)
    if level > 4:
        level = 4
    return levels_dict[level]

def convert_dict_to_option_dict(input_dict):
    """Convert a simple key-value dictionary to a dictionary of options tuples"""
    ret_dict = {}
    for key, value in input_dict.items():
        ret_dict[key] = convert_value_to_option_tuple(value)
    return ret_dict

def convert_option_dict_to_dict(option_dict):
    """Convert a dictionary of options tuples to a simple key-value dictionary"""
    ret_dict = {}
    for key, value in option_dict.items():
        if is_null(value):
            ret_dict[key] = None
        elif isinstance(value, tuple):
            ret_dict[key] = value[0]
        else:
            ret_dict[key] = value
    return ret_dict

def reduce_by_keys(orig_dict, keys, default=None):
    """Reduce a dictionary by selecting a set of keys"""
    ret = {}
    for key in keys:
        ret[key] = orig_dict.get(key, default)
    return ret

def sky_to_offset(skydir, lon, lat, coordsys='CEL', projection='AIT'):
    """Convert sky coordinates to a projected offset.  This function
    is the inverse of offset_to_sky."""
    w = create_wcs(skydir, coordsys, projection)
    skycrd = np.vstack((lon, lat)).T
    if len(skycrd) == 0:
        return skycrd
    return w.wcs_world2pix(skycrd, 0)

def wcs_to_axes(w, npix):
    """Generate a sequence of bin edge vectors corresponding to the
    axes of a WCS object."""
    npix = npix[::-1]
    x = np.linspace(-npix[0] / 2.0, npix[0] / 2.0, npix[0] + 1) * np.abs(w.wcs.cdelt[0])
    y = np.linspace(-npix[1] / 2.0, npix[1] / 2.0, npix[1] + 1) * np.abs(w.wcs.cdelt[1])
    if w.wcs.naxis == 2:
        return (x, y)
    cdelt2 = np.log10((w.wcs.cdelt[2] + w.wcs.crval[2]) / w.wcs.crval[2])
    z = np.linspace(0, npix[2], npix[2] + 1) * cdelt2
    z += np.log10(w.wcs.crval[2])
    return (x, y, z)

def wcs_to_coords(w, shape):
    """Generate an N x D list of pixel center coordinates where N is
    the number of pixels and D is the dimensionality of the map."""
    if w.naxis == 2:
        y, x = wcs_to_axes(w, shape)
    elif w.naxis == 3:
        z, y, x = wcs_to_axes(w, shape)
    else:
        raise Exception('Wrong number of WCS axes %i' % w.naxis)
    x = 0.5 * (x[1:] + x[:-1])
    y = 0.5 * (y[1:] + y[:-1])
    if w.naxis == 2:
        x = np.ravel(np.ones(shape) * x[:, np.newaxis])
        y = np.ravel(np.ones(shape) * y[np.newaxis, :])
        return np.vstack((x, y))
    z = 0.5 * (z[1:] + z[:-1])
    x = np.ravel(np.ones(shape) * x[:, np.newaxis, np.newaxis])
    y = np.ravel(np.ones(shape) * y[np.newaxis, :, np.newaxis])
    z = np.ravel(np.ones(shape) * z[np.newaxis, np.newaxis, :])
    return np.vstack((x, y, z))

def create_inputlist(arglist):
    """Read lines from a file and makes a list of file names.

    Removes whitespace and lines that start with '#'
    Recursively read all files with the extension '.lst'"""
    lines = []
    if isinstance(arglist, list):
        for arg in arglist:
            if os.path.splitext(arg)[1] == '.lst':
                lines += readlines(arg)
            else:
                lines.append(arg)
    elif is_null(arglist):
        pass
    elif os.path.splitext(arglist)[1] == '.lst':
        lines += readlines(arglist)
    else:
        lines.append(arglist)
    return lines

def create_default_config(schema):
    """Create a configuration dictionary from a schema dictionary.
    The schema defines the valid configuration keys and their default
    values.  Each element of ``schema`` should be a tuple/list
    containing (default value,docstring,type) or a dict containing a
    nested schema."""
    o = {}
    for key, item in schema.items():
        if isinstance(item, dict):
            o[key] = create_default_config(item)
        elif isinstance(item, tuple):
            value, comment, item_type = item
            if isinstance(item_type, tuple):
                item_type = item_type[0]
            if value is None and (item_type == list or item_type == dict):
                value = item_type()
            if key in o:
                raise KeyError('Duplicate key in schema.')
            o[key] = value
        else:
            raise TypeError('Unrecognized type for schema dict element: %s %s' % (key, type(item)))
    return o

def update_null_primary(hdu_in, hdu=None):
    """'Update' a null primary HDU

    This actually just checks hdu exists and creates it from hdu_in if it does not."""
    if hdu is None:
        hdu = fits.PrimaryHDU(header=hdu_in.header)
    else:
        hdu = hdu_in
        hdu.header.remove('FILENAME')
    return hdu

def update_image(hdu_in, hdu=None):
    """'Update' an image HDU

    This checks hdu exists and creates it from hdu_in if it does not.
    If hdu does exist, this adds the data in hdu_in to hdu"""
    if hdu is None:
        hdu = fits.ImageHDU(data=hdu_in.data, header=hdu_in.header, name=hdu_in.name)
    else:
        hdu.data += hdu_in.data
    return hdu

def update_ebounds(hdu_in, hdu=None):
    """'Update' the EBOUNDS HDU

    This checks hdu exists and creates it from hdu_in if it does not.
    If hdu does exist, this raises an exception if it doesn not match hdu_in"""
    if hdu is None:
        hdu = fits.BinTableHDU(data=hdu_in.data, header=hdu_in.header, name=hdu_in.name)
    else:
        for col in ['CHANNEL', 'E_MIN', 'E_MAX']:
            if (hdu.data[col] != hdu_in.data[col]).any():
                raise ValueError('Energy bounds do not match : %s %s' % (hdu.data[col], hdu_in.data[col]))
    return hdu

def select_extended(cat_table):
    """Select only rows representing extended sources from a catalog table
    """
    try:
        l = [len(row.strip()) > 0 for row in cat_table['Extended_Source_Name'].data]
        return np.array(l, bool)
    except KeyError:
        return cat_table['Extended']

def select_sources(cat_table, cuts):
    """Select only rows passing a set of cuts from catalog table
    """
    nsrc = len(cat_table)
    full_mask = np.ones(nsrc, bool)
    for cut in cuts:
        if cut == 'mask_extended':
            full_mask *= mask_extended(cat_table)
        elif cut == 'select_extended':
            full_mask *= select_extended(cat_table)
        else:
            full_mask *= make_mask(cat_table, cut)
    lout = [src_name.strip() for src_name in cat_table['Source_Name'][full_mask]]
    return lout

def make_catalog_comp_dict(**kwargs):
