def collect_jobs(dirs, runscript, overwrite=False, max_job_age=90):
    """Construct a list of job dictionaries."""
    jobs = []
    for dirname in sorted(dirs):
        o = dict(cfgfile=os.path.join(dirname, 'config.yaml'), logfile=os.path.join(dirname, os.path.splitext(runscript)[0] + '.log'), runscript=os.path.join(dirname, runscript))
        if not os.path.isfile(o['cfgfile']):
            continue
        if not os.path.isfile(o['runscript']):
            continue
        if not os.path.isfile(o['logfile']):
            jobs.append(o)
            continue
        age = file_age_in_seconds(o['logfile']) / 60.0
        job_status = check_log(o['logfile'])
        print(dirname, job_status, age)
        if job_status is False or overwrite:
            jobs.append(o)
        elif job_status == 'Exited':
            print('Job Exited. Resending command.')
            jobs.append(o)
        elif job_status == 'None' and age > max_job_age:
            print('Job did not exit, but no activity on log file for > %.2f min. Resending command.' % max_job_age)
            jobs.append(o)
    return jobs

def render_pep440(vcs):
    """Convert git release tag into a form that is PEP440 compliant."""
    if vcs is None:
        return None
    tags = vcs.split('-')
    if len(tags) == 1:
        return tags[0]
    else:
        return tags[0] + '+' + '.'.join(tags[1:])

def read_release_version():
    """Read the release version from ``_version.py``."""
    import re
    dirname = os.path.abspath(os.path.dirname(__file__))
    try:
        f = open(os.path.join(dirname, '_version.py'), 'rt')
        for line in f.readlines():
            m = re.match("__version__ = '([^']+)'", line)
            if m:
                ver = m.group(1)
                return ver
    except:
        return None
    return None

def init_matplotlib_backend(backend=None):
    """This function initializes the matplotlib backend.  When no
    DISPLAY is available the backend is automatically set to 'Agg'.

    Parameters
    ----------
    backend : str
       matplotlib backend name."""
    import matplotlib
    try:
        os.environ['DISPLAY']
    except KeyError:
        matplotlib.use('Agg')
    else:
        if backend is not None:
            matplotlib.use(backend)

def load_data(infile, workdir=None):
    """Load python data structure from either a YAML or numpy file."""
    infile = resolve_path(infile, workdir=workdir)
    infile, ext = os.path.splitext(infile)
    if os.path.isfile(infile + '.npy'):
        infile += '.npy'
    elif os.path.isfile(infile + '.yaml'):
        infile += '.yaml'
    else:
        raise Exception('Input file does not exist.')
    ext = os.path.splitext(infile)[1]
    if ext == '.npy':
        return (infile, load_npy(infile))
    elif ext == '.yaml':
        return (infile, load_yaml(infile))
    else:
        raise Exception('Unrecognized extension.')

def collect_dirs(path, max_depth=1, followlinks=True):
    """Recursively find directories under the given path."""
    if not os.path.isdir(path):
        return []
    o = [path]
    if max_depth == 0:
        return o
    for subdir in os.listdir(path):
        subdir = os.path.join(path, subdir)
        if not os.path.isdir(subdir):
            continue
        o += [subdir]
        if os.path.islink(subdir) and (not followlinks):
            continue
        if max_depth > 0:
            o += collect_dirs(subdir, max_depth=max_depth - 1)
    return list(set(o))

def match_regex_list(patterns, string):
    """Perform a regex match of a string against a list of patterns.
    Returns true if the string matches at least one pattern in the
    list."""
    for p in patterns:
        if re.findall(p, string):
            return True
    return False

def separation_cos_angle(lon0, lat0, lon1, lat1):
    """Evaluate the cosine of the angular separation between two
    direction vectors."""
    return np.sin(lat1) * np.sin(lat0) + np.cos(lat1) * np.cos(lat0) * np.cos(lon1 - lon0)

def find_function_root(fn, x0, xb, delta=0.0, bounds=None):
    """Find the root of a function: f(x)+delta in the interval encompassed
    by x0 and xb.

    Parameters
    ----------

    fn : function
       Python function.

    x0 : float
       Fixed bound for the root search.  This will either be used as
       the lower or upper bound depending on the relative value of xb.

    xb : float
       Upper or lower bound for the root search.  If a root is not
       found in the interval [x0,xb]/[xb,x0] this value will be
       increased/decreased until a change in sign is found."""
    if x0 == xb:
        return np.nan
    for i in range(10):
        if np.sign(fn(xb) + delta) != np.sign(fn(x0) + delta):
            break
        if bounds is not None and (xb < bounds[0] or xb > bounds[1]):
            break
        if xb < x0:
            xb *= 0.5
        else:
            xb *= 2.0
    if np.sign(fn(xb) + delta) == np.sign(fn(x0) + delta):
        return np.nan
    if x0 == 0:
        xtol = 1e-10 * np.abs(xb)
    else:
        xtol = 1e-10 * np.abs(xb + x0)
    return brentq(lambda t: fn(t) + delta, x0, xb, xtol=xtol)

def get_region_mask(z, delta, xy=None):
    """Get mask of connected region within delta of max(z)."""
    if xy is None:
        ix, iy = np.unravel_index(np.argmax(z), z.shape)
    else:
        ix, iy = xy
    mz = z > z[ix, iy] - delta
    labels = label(mz)[0]
    mz &= labels == labels[ix, iy]
    return mz

def fits_recarray_to_dict(table):
    """Convert a FITS recarray to a python dictionary."""
    cols = {}
    for icol, col in enumerate(table.columns.names):
        col_data = table.data[col]
        if type(col_data[0]) == np.float32:
            cols[col] = np.array(col_data, dtype=float)
        elif type(col_data[0]) == np.float64:
            cols[col] = np.array(col_data, dtype=float)
        elif type(col_data[0]) == str:
            cols[col] = np.array(col_data, dtype=str)
        elif type(col_data[0]) == np.string_:
            cols[col] = np.array(col_data, dtype=str)
        elif type(col_data[0]) == np.int16:
            cols[col] = np.array(col_data, dtype=int)
        elif type(col_data[0]) == np.ndarray:
            cols[col] = np.array(col_data)
        else:
            raise Exception('Unrecognized column type: %s %s' % (col, str(type(col_data))))
    return cols

def replace_aliases(cut_dict, aliases):
    """Substitute aliases in a cut dictionary."""
    for k, v in cut_dict.items():
        for k0, v0 in aliases.items():
            cut_dict[k] = cut_dict[k].replace(k0, '(%s)' % v0)

def get_files(files, extnames=['.root']):
    """Extract a list of file paths from a list containing both paths
    and file lists with one path per line."""
    files_out = []
    for f in files:
        mime = mimetypes.guess_type(f)
        if os.path.splitext(f)[1] in extnames:
            files_out += [f]
        elif mime[0] == 'text/plain':
            files_out += list(np.loadtxt(f, unpack=True, dtype='str'))
        else:
            raise Exception('Unrecognized input type.')
    return files_out

def get_cuts_from_xml(xmlfile):
    """Extract event selection strings from the XML file."""
    root = ElementTree.ElementTree(file=xmlfile).getroot()
    event_maps = root.findall('EventMap')
    alias_maps = root.findall('AliasDict')[0]
    event_classes = {}
    event_types = {}
    event_aliases = {}
    for m in event_maps:
        if m.attrib['altName'] == 'EVENT_CLASS':
            for c in m.findall('EventCategory'):
                event_classes[c.attrib['name']] = strip(c.find('ShortCut').text)
        elif m.attrib['altName'] == 'EVENT_TYPE':
            for c in m.findall('EventCategory'):
                event_types[c.attrib['name']] = strip(c.find('ShortCut').text)
    for m in alias_maps.findall('Alias'):
        event_aliases[m.attrib['name']] = strip(m.text)
    replace_aliases(event_aliases, event_aliases.copy())
    replace_aliases(event_aliases, event_aliases.copy())
    replace_aliases(event_classes, event_aliases)
    replace_aliases(event_types, event_aliases)
    event_selections = {}
    event_selections.update(event_classes)
    event_selections.update(event_types)
    event_selections.update(event_aliases)
    return event_selections

def make_nfs_path(path):
    """Make a nfs version of a file path.
    This just puts /nfs at the beginning instead of /gpfs"""
    if os.path.isabs(path):
        fullpath = path
    else:
        fullpath = os.path.abspath(path)
    if len(fullpath) < 6:
        return fullpath
    if fullpath[0:6] == '/gpfs/':
        fullpath = fullpath.replace('/gpfs/', '/nfs/')
    return fullpath

def make_gpfs_path(path):
    """Make a gpfs version of a file path.
    This just puts /gpfs at the beginning instead of /nfs"""
    if os.path.isabs(path):
        fullpath = os.path.abspath(path)
    else:
        fullpath = os.path.abspath(path)
    if len(fullpath) < 5:
        return fullpath
    if fullpath[0:5] == '/nfs/':
        fullpath = fullpath.replace('/nfs/', '/gpfs/')
    return fullpath

def get_lsf_status():
    """Count and print the number of jobs in various LSF states
    """
    status_count = {'RUN': 0, 'PEND': 0, 'SUSP': 0, 'USUSP': 0, 'NJOB': 0, 'UNKNWN': 0}
    try:
        subproc = subprocess.Popen(['bjobs'], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        subproc.stderr.close()
        output = subproc.stdout.readlines()
    except OSError:
        return status_count
    for line in output[1:]:
        line = line.strip().split()
        if len(line) < 5:
            continue
        status_count['NJOB'] += 1
        for k in status_count:
            if line[2] == k:
                status_count[k] += 1
    return status_count

def build_bsub_command(command_template, lsf_args):
    """Build and return a lsf batch command template

    The structure will be 'bsub -s <key> <value> <command_template>'
        where <key> and <value> refer to items in lsf_args"""
    if command_template is None:
        return ''
    full_command = 'bsub -o {logfile}'
    for key, value in lsf_args.items():
        full_command += ' -%s' % key
        if value is not None:
            full_command += ' %s' % value
    full_command += ' %s' % command_template
    return full_command

def create_sc_table(scfile, colnames=None):
    """Load an FT2 file from a file or list of files."""
    if utils.is_fits_file(scfile) and colnames is None:
        return create_table_from_fits(scfile, 'SC_DATA')
    if utils.is_fits_file(scfile):
        files = [scfile]
    else:
        files = [line.strip() for line in open(scfile, 'r')]
    tables = [create_table_from_fits(f, 'SC_DATA', colnames) for f in files]
    return vstack(tables)

def create_table_from_fits(fitsfile, hduname, colnames=None):
    """Memory efficient function for loading a table from a FITS
    file."""
    if colnames is None:
        return Table.read(fitsfile, hduname)
    cols = []
    with fits.open(fitsfile, memmap=True) as h:
        for k in colnames:
            data = h[hduname].data.field(k)
            cols += [Column(name=k, data=data)]
    return Table(cols)

def get_spectral_index(src, egy):
    """Compute the local spectral index of a source."""
    delta = 1e-05
    f0 = src.spectrum()(pyLike.dArg(egy * (1 - delta)))
    f1 = src.spectrum()(pyLike.dArg(egy * (1 + delta)))
    if f0 > 0 and f1 > 0:
        gamma = np.log10(f0 / f1) / np.log10((1 - delta) / (1 + delta))
    else:
        gamma = np.nan
    return gamma

def purge_dict(idict):
    """Remove null items from a dictionary"""
    odict = {}
    for key, val in idict.items():
        if is_null(val):
            continue
        odict[key] = val
    return odict

def add_columns(t0, t1):
    """Add columns of table t1 to table t0."""
    for colname in t1.colnames:
        col = t1.columns[colname]
        if colname in t0.columns:
            continue
        new_col = Column(name=col.name, length=len(t0), dtype=col.dtype)
        t0.add_column(new_col)

def join_tables(left, right, key_left, key_right, cols_right=None):
    """Perform a join of two tables.

    Parameters
    ----------
    left : `~astropy.Table`
        Left table for join.

    right : `~astropy.Table`
        Right table for join.

    key_left : str
        Key used to match elements from ``left`` table.

    key_right : str
        Key used to match elements from ``right`` table.

    cols_right : list
        Subset of columns from ``right`` table that will be appended
        to joined table."""
    right = right.copy()
    if cols_right is None:
        cols_right = right.colnames
    else:
        cols_right = [c for c in cols_right if c in right.colnames]
    if key_left != key_right:
        right[key_right].name = key_left
    if key_left not in cols_right:
        cols_right += [key_left]
    out = join(left, right[cols_right], keys=key_left, join_type='left')
    for col in out.colnames:
        if out[col].dtype.kind in ['S', 'U']:
            out[col].fill_value = ''
        elif out[col].dtype.kind in ['i']:
            out[col].fill_value = 0
        else:
            out[col].fill_value = np.nan
    return out.filled()

def strip_columns(tab):
    """Strip whitespace from string columns."""
    for colname in tab.colnames:
        if tab[colname].dtype.kind in ['S', 'U']:
            tab[colname] = np.core.defchararray.strip(tab[colname])

def row_to_dict(row):
    """Convert a table row to a dictionary."""
    o = {}
    for colname in row.colnames:
        if isinstance(row[colname], np.string_) and row[colname].dtype.kind in ['S', 'U']:
            o[colname] = str(row[colname])
        else:
            o[colname] = row[colname]
    return o

def make_ring_dicts(**kwargs):
    """Build and return the information about the Galprop rings
    """
    library_yamlfile = kwargs.get('library', 'models/library.yaml')
    gmm = kwargs.get('GalpropMapManager', GalpropMapManager(**kwargs))
    if library_yamlfile is None or library_yamlfile == 'None':
        return gmm
    diffuse_comps = DiffuseModelManager.read_diffuse_component_yaml(library_yamlfile)
    for diffuse_value in diffuse_comps.values():
        if diffuse_value is None:
            continue
        if diffuse_value['model_type'] != 'galprop_rings':
            continue
        versions = diffuse_value['versions']
        for version in versions:
            gmm.make_ring_dict(version)
    return gmm

def make_diffuse_comp_info_dict(**kwargs):
    """Build and return the information about the diffuse components
    """
    library_yamlfile = kwargs.pop('library', 'models/library.yaml')
    components = kwargs.pop('components', None)
    if components is None:
        comp_yamlfile = kwargs.pop('comp', 'config/binning.yaml')
        components = Component.build_from_yamlfile(comp_yamlfile)
    gmm = kwargs.get('GalpropMapManager', GalpropMapManager(**kwargs))
    dmm = kwargs.get('DiffuseModelManager', DiffuseModelManager(**kwargs))
    if library_yamlfile is None or library_yamlfile == 'None':
        diffuse_comps = {}
    else:
        diffuse_comps = DiffuseModelManager.read_diffuse_component_yaml(library_yamlfile)
    diffuse_comp_info_dict = dmm.make_diffuse_comp_info_dict(diffuse_comps, components)
    for diffuse_value in diffuse_comps.values():
        if diffuse_value is None:
            continue
        if diffuse_value['model_type'] != 'galprop_rings':
            continue
        versions = diffuse_value['versions']
        for version in versions:
            galprop_dict = gmm.make_diffuse_comp_info_dict(version)
            diffuse_comp_info_dict.update(galprop_dict)
    return dict(comp_info_dict=diffuse_comp_info_dict, GalpropMapManager=gmm, DiffuseModelManager=dmm)

def get_unique_match(table, colname, value):
    """Get the row matching value for a particular column.
    If exactly one row matchs, return index of that row,
    Otherwise raise KeyError."""
    if table[colname].dtype.kind in ['S', 'U']:
        mask = table[colname].astype(str) == value
    else:
        mask = table[colname] == value
    if mask.sum() != 1:
        raise KeyError('%i rows in column %s match value %s' % (mask.sum(), colname, value))
    return np.argmax(mask)

def norm(x, mu, sigma=1.0):
    """Scipy norm function"""
    return stats.norm(loc=mu, scale=sigma).pdf(x)

def ln_norm(x, mu, sigma=1.0):
    """Natural log of scipy norm function truncated at zero"""
    return np.log(stats.norm(loc=mu, scale=sigma).pdf(x))

def lognorm(x, mu, sigma=1.0):
    """Log-normal function from scipy"""
    return stats.lognorm(sigma, scale=mu).pdf(x)

def log10norm(x, mu, sigma=1.0):
    """Scale scipy lognorm from natural log to base 10
    x     : input parameter
    mu    : mean of the underlying log10 gaussian
    sigma : variance of underlying log10 gaussian"""
    return stats.lognorm(sigma * np.log(10), scale=mu).pdf(x)

def coadd_maps(geom, maps, preserve_counts=True):
    """Coadd a sequence of `~gammapy.maps.Map` objects."""
    map_out = gammapy.maps.Map.from_geom(geom)
    for m in maps:
        m_tmp = m
        if isinstance(m, gammapy.maps.HpxNDMap):
            if m.geom.order < map_out.geom.order:
                factor = map_out.geom.nside // m.geom.nside
                m_tmp = m.upsample(factor, preserve_counts=preserve_counts)
        map_out.coadd(m_tmp)
    return map_out

def hpx_to_axes(h, npix):
    """Generate a sequence of bin edge vectors corresponding to the
    axes of a HPX object."""
    x = h.ebins
    z = np.arange(npix[-1] + 1)
    return (x, z)

def parse_hpxregion(region):
    """Parse the HPX_REG header keyword into a list of tokens."""
    m = re.match('([A-Za-z\\_]*?)\\((.*?)\\)', region)
    if m is None:
        raise Exception('Failed to parse hpx region string.')
    if not m.group(1):
        return re.split(',', m.group(2))
    else:
        return [m.group(1)] + re.split(',', m.group(2))

def upix_to_pix(upix):
    """Get the nside from a unique pixel number."""
    nside = np.power(2, np.floor(np.log2(upix / 4)) / 2).astype(int)
    pix = upix - 4 * np.power(nside, 2)
    return (pix, nside)

def convert_sed_cols(tab):
    """Cast SED column names to lowercase."""
    for colname in list(tab.columns.keys()):
        newname = colname.lower()
        newname = newname.replace('dfde', 'dnde')
        if tab.columns[colname].name == newname:
            continue
        tab.columns[colname].name = newname
    return tab

def make_rev_dict_unique(cdict):
    """Make a reverse dictionary

    Parameters
    ----------
    in_dict : dict(int:dict(int:True))
       A dictionary of clusters.  Each cluster is a source index and
       the dictionary of other sources in the cluster.

    Returns
    -------
    rev_dict : dict(int:dict(int:True))
       A dictionary pointing from source index to the clusters it is
       included in."""
    rev_dict = {}
    for k, v in cdict.items():
        if k in rev_dict:
            rev_dict[k][k] = True
        else:
            rev_dict[k] = {k: True}
        for vv in v.keys():
            if vv in rev_dict:
                rev_dict[vv][k] = True
            else:
                rev_dict[vv] = {k: True}
    return rev_dict

def make_dict_from_vector(in_array):
    """Converts the cluster membership array stored in a fits file back to a dictionary

    Parameters
    ----------
    in_array : `np.ndarray'
       An array filled with the index of the seed of a cluster if a source belongs to a cluster,
       and with -1 if it does not.

    Returns
    -------
    returns dict(int:[int,...])
       Dictionary of clusters keyed by the best source in each cluster"""
    out_dict = {}
    for i, k in enumerate(in_array):
        if k < 0:
            continue
        try:
            out_dict[k].append(i)
        except KeyError:
            out_dict[k] = [i]
    return out_dict

def get_branches(aliases):
    """Get unique branch names from an alias dictionary."""
    ignore = ['pow', 'log10', 'sqrt', 'max']
    branches = []
    for k, v in aliases.items():
        tokens = re.sub('[\\(\\)\\+\\*\\/\\,\\=\\<\\>\\&\\!\\-\\|]', ' ', v).split()
        for t in tokens:
            if bool(re.search('^\\d', t)) or len(t) <= 3:
                continue
            if bool(re.search('[a-zA-Z]', t)) and t not in ignore:
                branches += [t]
    return list(set(branches))

def read_spectral_data(hdu):
    """Reads and returns the energy bin edges, fluxes and npreds from
    a FITs HDU"""
    ebins = read_energy_bounds(hdu)
    fluxes = np.ndarray(len(ebins))
    try:
        fluxes[0:-1] = hdu.data.field('E_MIN_FL')
        fluxes[-1] = hdu.data.field('E_MAX_FL')[-1]
        npreds = hdu.data.field('NPRED')
    except:
        fluxes = np.ones(len(ebins))
        npreds = np.ones(len(ebins))
    return (ebins, fluxes, npreds)

def write_tables_to_fits(filepath, tablelist, clobber=False, namelist=None, cardslist=None, hdu_list=None):
    """Write some astropy.table.Table objects to a single fits file"""
    outhdulist = [fits.PrimaryHDU()]
    rmlist = []
    for i, table in enumerate(tablelist):
        ft_name = '%s._%i' % (filepath, i)
        rmlist.append(ft_name)
        try:
            os.unlink(ft_name)
        except:
            pass
        table.write(ft_name, format='fits')
        ft_in = fits.open(ft_name)
        if namelist:
            ft_in[1].name = namelist[i]
        if cardslist:
            for k, v in cardslist[i].items():
                ft_in[1].header[k] = v
        ft_in[1].update()
        outhdulist += [ft_in[1]]
    if hdu_list is not None:
        for h in hdu_list:
            outhdulist.append(h)
    fits.HDUList(outhdulist).writeto(filepath, overwrite=clobber)
    for rm in rmlist:
        os.unlink(rm)

def get_source_kernel(gta, name, kernel=None):
    """Get the PDF for the given source."""
    sm = []
    zs = 0
    for c in gta.components:
        z = c.model_counts_map(name).data.astype('float')
        if kernel is not None:
            shape = (z.shape[0],) + kernel.shape
            z = np.apply_over_axes(np.sum, z, axes=[1, 2]) * np.ones(shape) * kernel[np.newaxis, :, :]
            zs += np.sum(z)
        else:
            zs += np.sum(z)
        sm.append(z)
    sm2 = 0
    for i, m in enumerate(sm):
        sm[i] /= zs
        sm2 += np.sum(sm[i] ** 2)
    for i, m in enumerate(sm):
        sm[i] /= sm2
    return sm

def get_priors(like):
    """Extract priors from a likelihood object."""
    npar = len(like.params())
    vals = np.ones(npar)
    errs = np.ones(npar)
    has_prior = np.array([False] * npar)
    for i, p in enumerate(like.params()):
        prior = like[i].log_prior()
        if prior is None:
            continue
        par_names = pyLike.StringVector()
        prior.getParamNames(par_names)
        if not 'Mean' in par_names:
            raise Exception('Failed to find Mean in prior parameters.')
        if not 'Sigma' in par_names:
            raise Exception('Failed to find Sigma in prior parameters.')
        for t in par_names:
            if t == 'Mean':
                vals[i] = prior.parameter(t).getValue()
            if t == 'Sigma':
                errs[i] = prior.parameter(t).getValue()
        has_prior[i] = True
    return (vals, errs, has_prior)

def get_source_pars(src):
    """Extract the parameters associated with a pyLikelihood Source object.

    """
    fnmap = src.getSrcFuncs()
    keys = fnmap.keys()
    if 'Position' in keys:
        ppars = get_function_pars(src.getSrcFuncs()[str('Position')])
    elif 'SpatialDist' in keys:
        ppars = get_function_pars(src.getSrcFuncs()[str('SpatialDist')])
    else:
        raise Exception('Failed to extract spatial parameters.')
    fn = src.getSrcFuncs()[str('Spectrum')]
    spars = get_function_pars(fn)
    for i, p in enumerate(ppars):
        ppars[i]['is_norm'] = False
    for i, p in enumerate(spars):
        if fn.normPar().getName() == p['name']:
            spars[i]['is_norm'] = True
        else:
            spars[i]['is_norm'] = False
    return (spars, ppars)

def update_gtapp(gtapp, **kwargs):
    """Update the parameters of the object that can run ScienceTools applications

    Parameters
    ----------

    gtapp :  `GtApp.GtApp`
        Object that will run the application in question

    kwargs : arguments used to invoke the application"""
    for key, val in kwargs.items():
        if key in ['pfiles', 'scratch']:
            continue
        if val is None:
            continue
        try:
            gtapp[key] = val
        except ValueError:
            raise ValueError('gtapp failed to set parameter %s %s' % (key, val))
        except KeyError:
            raise KeyError('gtapp failed to set parameter %s %s' % (key, val))

def _writer(func):
    """Decorator for a custom writer, but a default reader"""
    name = func.__name__
    return property(fget=lambda self: getattr(self, '_%s' % name), fset=func)

def pem_armor_csr(certification_request):
    """Encodes a CSR into PEM format

    :param certification_request:
        An asn1crypto.csr.CertificationRequest object of the CSR to armor.
        Typically this is obtained from CSRBuilder.build().

    :return:
        A byte string of the PEM-encoded CSR"""
    if not isinstance(certification_request, csr.CertificationRequest):
        raise TypeError(_pretty_message('\n            certification_request must be an instance of\n            asn1crypto.csr.CertificationRequest, not %s\n            ', _type_name(certification_request)))
    return pem.armor('CERTIFICATE REQUEST', certification_request.dump())

def write_tabular(obj, filepath):
    """Write tabular object in HDF5 or pickle format

    Args:
        obj (array or DataFrame): tabular object to write
        filepath (path-like): path to write to; must end in '.h5' or '.pkl'"""
    _, fn, ext = splitext2(filepath)
    if ext == '.h5':
        _write_tabular_h5(obj, filepath)
    elif ext == '.pkl':
        _write_tabular_pickle(obj, filepath)
    else:
        raise NotImplementedError

def read_tabular(filepath):
    """Read tabular object in HDF5 or pickle format

    Args:
        filepath (path-like): path to read to; must end in '.h5' or '.pkl'"""
    _, fn, ext = splitext2(filepath)
    if ext == '.h5':
        return _read_tabular_h5(filepath)
    elif ext == '.pkl':
        return _read_tabular_pickle(filepath)
    else:
        raise NotImplementedError

