def verify_checksum(message, previous_csum=0):
    """Verify checksum for incoming message.

    :param message: incoming message
    :param previous_csum: accumulated checksum value

    :return return True if message checksum type is None
    or checksum is correct"""
    if message.message_type in CHECKSUM_MSG_TYPES:
        csum = compute_checksum(message.checksum[0], message.args, previous_csum)
        if csum == message.checksum[1]:
            return True
        else:
            return False
    else:
        return True

def decorator(caller, _func=None):
    """decorator(caller) converts a caller function into a decorator"""
    if _func is not None:
        return decorate(_func, caller)
    if inspect.isclass(caller):
        name = caller.__name__.lower()
        callerfunc = get_init(caller)
        doc = 'decorator(%s) converts functions/generators into factories of %s objects' % (caller.__name__, caller.__name__)
        fun = getfullargspec(callerfunc).args[1]
    elif inspect.isfunction(caller):
        if caller.__name__ == '<lambda>':
            name = '_lambda_'
        else:
            name = caller.__name__
        callerfunc = caller
        doc = caller.__doc__
        fun = getfullargspec(callerfunc).args[0]
    else:
        name = caller.__class__.__name__.lower()
        callerfunc = caller.__call__.__func__
        doc = caller.__call__.__doc__
        fun = getfullargspec(callerfunc).args[1]
    evaldict = callerfunc.__globals__.copy()
    evaldict['_call_'] = caller
    evaldict['_decorate_'] = decorate
    return FunctionMaker.create('%s(%s)' % (name, fun), 'return _decorate_(%s, _call_)' % fun, evaldict, call=caller, doc=doc, module=caller.__module__, __wrapped__=caller)

def to_twos_comp(val, bits):
    """compute the 2's compliment of int value val"""
    if not val.startswith('-'):
        return to_int(val)
    value = _invert(to_bin_str_from_int_string(bits, bin(to_int(val[1:]))))
    return int(value, 2) + 1

def iso8601time(time_tuple):
    """Format time_tuple as a ISO8601 time string.

    :param time_tuple: Either None, to use the current time, or a tuple tuple."""
    if time_tuple:
        return time.strftime('%Y-%m-%dT%H:%M:%SZ', time_tuple)
    else:
        return time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())

def parse(url, defaultPort=True):
    """Split the given URL into the scheme, host, port, and path.

    @type url: C{str}
    @param url: An URL to parse.

    @type defaultPort: C{bool}
    @param defaultPort: Whether to return the default port associated with the
        scheme in the given url, when the url doesn't specify one.

    @return: A four-tuple of the scheme, host, port, and path of the URL.  All
    of these are C{str} instances except for port, which is an C{int}."""
    url = url.strip()
    parsed = urlparse(url)
    scheme = parsed[0]
    path = urlunparse(('', '') + parsed[2:])
    host = parsed[1]
    if ':' in host:
        host, port = host.split(':')
        try:
            port = int(port)
        except ValueError:
            port = None
    else:
        port = None
    if port is None and defaultPort:
        if scheme == 'https':
            port = 443
        else:
            port = 80
    if path == '':
        path = '/'
    return (str(scheme), str(host), port, str(path))

def retry_when_service_down(func):
    """Decorator that will retry a function while it fails with status code 503
    Assumes the first argument to the fuction will be an object with a set_status_message method.
    :param func: function: will be called until it doesn't fail with DataServiceError status 503
    :return: value returned by func"""
    def retry_function(*args, **kwds):
        showed_status_msg = False
        status_watcher = args[0]
        while True:
            try:
                result = func(*args, **kwds)
                if showed_status_msg:
                    status_watcher.set_status_message('')
                return result
            except DataServiceError as dse:
                if dse.status_code == 503:
                    if not showed_status_msg:
                        message = SERVICE_DOWN_MESSAGE.format(datetime.datetime.utcnow())
                        status_watcher.set_status_message(message)
                        showed_status_msg = True
                    time.sleep(SERVICE_DOWN_RETRY_SECONDS)
                else:
                    raise
    return retry_function

def retry_until_resource_is_consistent(func, monitor):
    """Runs func, if func raises DSResourceNotConsistentError will retry func indefinitely.
    Notifies monitor if we have to wait(only happens if DukeDS API raises DSResourceNotConsistentError.
    :param func: func(): function to run
    :param monitor: object: has start_waiting() and done_waiting() methods when waiting for non-consistent resource
    :return: whatever func returns"""
    waiting = False
    while True:
        try:
            resp = func()
            if waiting and monitor:
                monitor.done_waiting()
            return resp
        except DSResourceNotConsistentError:
            if not waiting and monitor:
                monitor.start_waiting()
                waiting = True
            time.sleep(RESOURCE_NOT_CONSISTENT_RETRY_SECONDS)

def getSignatureKey(key, dateStamp, regionName, serviceName):
    """Generate the signing key for AWS V4 requests.

    @param key: The secret key to use.
    @type key: L{bytes}

    @param dateStamp: The UTC date and time, serialized as an AWS date
        stamp.
    @type dateStamp: L{bytes}

    @param regionName: The name of the region.
    @type regionName: L{bytes}

    @param serviceName: The name of the service to which the request
        will be sent.
    @type serviceName: L{bytes}

    @return: The signature.
    @rtype: L{bytes}"""
    kDate = sign(b'AWS4' + key, dateStamp)
    kRegion = sign(kDate, regionName)
    kService = sign(kRegion, serviceName)
    kSigning = sign(kService, b'aws4_request')
    return kSigning

def _make_canonical_uri(parsed):
    """Return the canonical URI for a parsed URL.

    @param parsed: The parsed URL from which to extract the canonical
        URI
    @type parsed: L{urlparse.ParseResult}

    @return: The canonical URI.
    @rtype: L{str}"""
    path = urllib.quote(parsed.path)
    canonical_parsed = parsed._replace(path=path, params='', query='', fragment='')
    return urlparse.urlunparse(canonical_parsed)

def _make_canonical_query_string(parsed):
    """Return the canonical query string for a parsed URL.

    @param parsed: The parsed URL from which to extract the canonical
        query string.
    @type parsed: L{urlparse.ParseResult}

    @return: The canonical query string.
    @rtype: L{str}"""
    query_params = urlparse.parse_qs(parsed.query, keep_blank_values=True)
    sorted_query_params = sorted(((k, v) for k, vs in query_params.items() for v in vs))
    return urllib.urlencode(sorted_query_params)

def _make_canonical_headers(headers, headers_to_sign):
    """Return canonicalized headers.

    @param headers: The request headers.
    @type headers: L{dict}

    @param headers_to_sign: A sequence of header names that should be
        signed.
    @type headers_to_sign: A sequence of L{bytes}

    @return: The canonicalized headers.
    @rtype: L{bytes}"""
    pairs = []
    for name in headers_to_sign:
        if name not in headers:
            continue
        values = headers[name]
        if not isinstance(values, (list, tuple)):
            values = [values]
        comma_values = b','.join((' '.join(line.strip().split()) for value in values for line in value.splitlines()))
        pairs.append((name.lower(), comma_values))
    sorted_pairs = sorted((b'%s:%s' % (name, value) for name, value in sorted(pairs)))
    return b'\n'.join(sorted_pairs) + b'\n'

def _make_signed_headers(headers, headers_to_sign):
    """Return a semicolon-delimited list of headers to sign.

    @param headers: The request headers.
    @type headers: L{dict}

    @param headers_to_sign: A sequence of header names that should be
        signed.
    @type headers_to_sign: L{bytes}

    @return: The semicolon-delimited list of headers.
    @rtype: L{bytes}"""
    return b';'.join((header.lower() for header in sorted(headers_to_sign) if header in headers))

