def get_command(arguments, output=None):
    """Parse C{arguments} and configure a L{Command} instance.

    An access key, secret key, endpoint and action are required.  Additional
    parameters included with the request are passed as parameters to the
    method call.  For example, the following command will create a L{Command}
    object that can invoke the C{DescribeRegions} method with the optional
    C{RegionName.0} parameter included in the request::

      txaws-discover --key KEY --secret SECRET --endpoint URL                      --action DescribeRegions --RegionName.0 us-west-1

    @param arguments: The command-line arguments to parse.
    @raises OptionError: Raised if C{arguments} can't be used to create a
        L{Command} object.
    @return: A L{Command} instance configured to make an EC2 API method call."""
    options = parse_options(arguments)
    key = options.pop('key')
    secret = options.pop('secret')
    endpoint = options.pop('endpoint')
    action = options.pop('action')
    return Command(key, secret, endpoint, action, options, output)

def _split_quoted(text):
    """Split a unicode string on *SPACE* characters.

    Splitting is not done at *SPACE* characters occurring within matched
    *QUOTATION MARK*s.  *REVERSE SOLIDUS* can be used to remove all
    interpretation from the following character.

    :param unicode text: The string to split.

    :return: A two-tuple of unicode giving the two split pieces."""
    quoted = False
    escaped = False
    result = []
    for i, ch in enumerate(text):
        if escaped:
            escaped = False
            result.append(ch)
        elif ch == u'\\':
            escaped = True
        elif ch == u'"':
            quoted = not quoted
        elif not quoted and ch == u' ':
            return (u''.join(result), text[i:].lstrip())
        else:
            result.append(ch)
    return (u''.join(result), u'')

def error_wrapper(error, errorClass):
    """We want to see all error messages from cloud services. Amazon's EC2 says
    that their errors are accompanied either by a 400-series or 500-series HTTP
    response code. As such, the first thing we want to do is check to see if
    the error is in that range. If it is, we then need to see if the error
    message is an EC2 one.

    In the event that an error is not a Twisted web error nor an EC2 one, the
    original exception is raised."""
    http_status = 0
    if error.check(TwistedWebError):
        xml_payload = error.value.response
        if error.value.status:
            http_status = int(error.value.status)
    else:
        error.raiseException()
    if http_status >= 400:
        if not xml_payload:
            error.raiseException()
        try:
            fallback_error = errorClass(xml_payload, error.value.status, str(error.value), error.value.response)
        except (ParseError, AWSResponseParseError):
            error_message = http.RESPONSES.get(http_status)
            fallback_error = TwistedWebError(http_status, error_message, error.value.response)
        raise fallback_error
    elif 200 <= http_status < 300:
        return str(error.value)
    else:
        error.raiseException()

def _get_joined_path(ctx):
    """@type ctx: L{_URLContext}
    @param ctx: A URL context.

    @return: The path component, un-urlencoded, but joined by slashes.
    @rtype: L{bytes}"""
    return b'/' + b'/'.join((seg.encode('utf-8') for seg in ctx.path))

def create_jwt_token(secret, client_id):
    """Create JWT token for GOV.UK Notify

    Tokens have standard header:
    {
        "typ": "JWT",
        "alg": "HS256"
    }

    Claims consist of:
    iss: identifier for the client
    iat: issued at in epoch seconds (UTC)

    :param secret: Application signing secret
    :param client_id: Identifier for the client
    :return: JWT token for this request"""
    assert secret, 'Missing secret key'
    assert client_id, 'Missing client id'
    headers = {'typ': __type__, 'alg': __algorithm__}
    claims = {'iss': client_id, 'iat': epoch_seconds()}
    return jwt.encode(payload=claims, key=secret, headers=headers).decode()

def get_token_issuer(token):
    """Issuer of a token is the identifier used to recover the secret
    Need to extract this from token to ensure we can proceed to the signature validation stage
    Does not check validity of the token
    :param token: signed JWT token
    :return issuer: iss field of the JWT token
    :raises TokenIssuerError: if iss field not present
    :raises TokenDecodeError: if token does not conform to JWT spec"""
    try:
        unverified = decode_token(token)
        if 'iss' not in unverified:
            raise TokenIssuerError
        return unverified.get('iss')
    except jwt.DecodeError:
        raise TokenDecodeError

def pythag(a, b):
    """Computer c = (a^2 + b^2)^0.5 without destructive underflow or overflow

    It solves the Pythagorean theorem a^2 + b^2 = c^2"""
    absA = abs(a)
    absB = abs(b)
    if absA > absB:
        return absA * sqrt(1.0 + (absB / float(absA)) ** 2)
    elif absB == 0.0:
        return 0.0
    else:
        return absB * sqrt(1.0 + (absA / float(absB)) ** 2)

def _merge_associative_list(alist, path, value):
    """Merge a value into an associative list at the given path, maintaining
    insertion order. Examples will explain it::

        >>> alist = []
        >>> _merge_associative_list(alist, ["foo", "bar"], "barvalue")
        >>> _merge_associative_list(alist, ["foo", "baz"], "bazvalue")
        >>> alist == [("foo", [("bar", "barvalue"), ("baz", "bazvalue")])]

    @param alist: An associative list of names to values.
    @param path: A path through sub-alists which we ultimately want to point to
    C{value}.
    @param value: The value to set.
    @return: None. This operation mutates the associative list in place."""
    for key in path[:-1]:
        for item in alist:
            if item[0] == key:
                alist = item[1]
                break
        else:
            subalist = []
            alist.append((key, subalist))
            alist = subalist
    alist.append((path[-1], value))

def wait_for_processes(processes, size, progress_queue, watcher, item):
    """Watch progress queue for errors or progress.
    Cleanup processes on error or success.
    :param processes: [Process]: processes we are waiting to finish downloading a file
    :param size: int: how many values we expect to be processed by processes
    :param progress_queue: ProgressQueue: queue which will receive tuples of progress or error
    :param watcher: ProgressPrinter: we notify of our progress:
    :param item: object: RemoteFile/LocalFile we are transferring."""
    while size > 0:
        progress_type, value = progress_queue.get()
        if progress_type == ProgressQueue.PROCESSED:
            chunk_size = value
            watcher.transferring_item(item, increment_amt=chunk_size)
            size -= chunk_size
        elif progress_type == ProgressQueue.START_WAITING:
            watcher.start_waiting()
        elif progress_type == ProgressQueue.DONE_WAITING:
            watcher.done_waiting()
        else:
            error_message = value
            for process in processes:
                process.terminate()
            raise ValueError(error_message)
    for process in processes:
        process.join()

def verify_file_private(filename):
