def get_keyword(text):
    """Accept a string such as BACKGROUNDCOLOR [r] [g] [b]
    and return backgroundcolor"""
    first_word = text.split(' ')[0]
    if len(first_word) > 1 and first_word.isupper():
        kwd = str(first_word.lower())
    else:
        kwd = None
    return kwd

def get_values(text):
    """Accept a string such as BACKGROUNDCOLOR [r] [g] [b]
    and return ['r', 'g', 'b']"""
    res = re.findall('\\[(.*?)\\]', text)
    values = []
    for r in res:
        if '|' in r:
            params = r.split('|')
            for p in params:
                values.append(p)
        else:
            values.append(r)
    values = [str(v.lower()) for v in values]
    return values

def process_doc(text):
    """The :ref: role is supported by Sphinx but not by plain docutils"""
    document = docutils.core.publish_doctree(text)
    visitor = RefVisitor(document)
    document.walk(visitor)
    return (visitor.kwd, visitor.values)

def _decode_response(response):
    """Strip off Gerrit's magic prefix and decode a response.

    :returns:
        Decoded JSON content as a dict, or raw text if content could not be
        decoded as JSON.

    :raises:
        requests.HTTPError if the response contains an HTTP error status code."""
    content_type = response.headers.get('content-type', '')
    logger.debug('status[%s] content_type[%s] encoding[%s]' % (response.status_code, content_type, response.encoding))
    response.raise_for_status()
    content = response.content.strip()
    if response.encoding:
        content = content.decode(response.encoding)
    if not content:
        logger.debug('no content in response')
        return content
    if content_type.split(';')[0] != 'application/json':
        return content
    if content.startswith(GERRIT_MAGIC_JSON_PREFIX):
        content = content[len(GERRIT_MAGIC_JSON_PREFIX):]
    try:
        return json.loads(content)
    except ValueError:
        logger.error('Invalid json content: %s', content)
        raise

def zimbra_to_python(zimbra_dict, key_attribute='n', content_attribute='_content'):
    """Converts single level Zimbra dicts to a standard python dict

    :param zimbra_dict: The dictionary in Zimbra-Format
    :return: A native python dict"""
    local_dict = {}
    for item in zimbra_dict:
        local_dict[item[key_attribute]] = item[content_attribute]
    return local_dict

def convert_to_str(input_string):
    """Returns a string of the input compatible between py2 and py3
    :param input_string:
    :return:"""
    if sys.version < '3':
        if isinstance(input_string, str) or isinstance(input_string, unicode):
            return input_string
    elif isinstance(input_string, str):
        return input_string
    return str(input_string)

def dict_to_dom(root_node, xml_dict):
    """Create a DOM node and optionally several subnodes from a dictionary.

    :param root_node: DOM-Node set the dictionary is applied upon
    :type root_node: xml.dom.Element
    :param xml_dict: The dictionary containing the nodes to process
    :type xml_dict: dict"""
    if '_content' in list(xml_dict.keys()):
        root_node.appendChild(root_node.ownerDocument.createTextNode(convert_to_str(xml_dict['_content'])))
    for key, value in xml_dict.items():
        if key == '_content':
            continue
        if type(value) == dict:
            tmp_node = root_node.ownerDocument.createElement(key)
            dict_to_dom(tmp_node, value)
            root_node.appendChild(tmp_node)
        elif type(value) == list:
            for multinode in value:
                tmp_node = root_node.ownerDocument.createElement(key)
                dict_to_dom(tmp_node, multinode)
                root_node.appendChild(tmp_node)
        else:
            root_node.setAttribute(key, convert_to_str(value))

def dom_to_dict(root_node):
    """Serializes the given node to the dictionary

    Serializes the given node to the documented dictionary format.

    :param root_node: Node to serialize
    :returns: The dictionary
    :rtype: dict"""
    tag = root_node.tagName
    if ':' in tag:
        tag = tag.split(':')[1]
    root_dict = {tag: {}}
    node_dict = root_dict[tag]
    if root_node.hasAttributes():
        for key in list(root_node.attributes.keys()):
            node_dict[key] = root_node.getAttribute(key)
    for child in root_node.childNodes:
        if child.nodeType == root_node.TEXT_NODE:
            node_dict['_content'] = child.data
        else:
            subnode_dict = dom_to_dict(child)
            child_tag = child.tagName
            if ':' in child_tag:
                child_tag = child_tag.split(':')[1]
            new_val = subnode_dict[child_tag]
            if child_tag in node_dict:
                prev_val = node_dict[child_tag]
                if type(prev_val) != list:
                    node_dict[child_tag] = [prev_val]
                node_dict[child_tag].append(new_val)
            else:
                node_dict[child_tag] = new_val
    return root_dict

def compress_pruned(table):
    """Compress table based on pruning mask.

    Only the rows/cols in which all of the elements are masked need to be
    pruned."""
    if not isinstance(table, np.ma.core.MaskedArray):
        return table
    if table.ndim == 0:
        return table.data
    if table.ndim == 1:
        return np.ma.compressed(table)
    row_inds = ~table.mask.all(axis=1)
    col_inds = ~table.mask.all(axis=0)
    table = table[row_inds, :][:, col_inds]
    if table.dtype == float and table.mask.any():
        table[table.mask] = np.nan
    return table

def intersperse_hs_in_std_res(slice_, hs_dims, res):
    """Perform the insertions of place-holding rows and cols for insertions."""
    for dim, inds in enumerate(slice_.inserted_hs_indices()):
        if dim not in hs_dims:
            continue
        for i in inds:
            res = np.insert(res, i, np.nan, axis=dim - slice_.ndim)
    return res

