def waliki_box(context, slug, show_edit=True, *args, **kwargs):
    """A templatetag to render a wiki page content as a box in any webpage,
    and allow rapid edition if you have permission.

    It's inspired in `django-boxes`_

    .. _django-boxes: https://github.com/eldarion/django-boxes"""
    request = context['request']
    try:
        page = Page.objects.get(slug=slug)
    except Page.DoesNotExist:
        page = None
    if page and check_perms_helper('change_page', request.user, slug) or (not page and check_perms_helper('add_page', request.user, slug)):
        form = PageForm(instance=page, initial={'slug': slug})
        form_action = reverse('waliki_edit', args=[slug])
    else:
        form = None
        form_action = None
    return {'request': request, 'slug': slug, 'label': slug.replace('/', '_'), 'page': page, 'form': form, 'form_action': form_action}

def check_perms(perms, user, slug, raise_exception=False):
    """a helper user to check if a user has the permissions
    for a given slug"""
    if isinstance(perms, string_types):
        perms = {perms}
    else:
        perms = set(perms)
    allowed_users = ACLRule.get_users_for(perms, slug)
    if allowed_users:
        return user in allowed_users
    if perms.issubset(set(WALIKI_ANONYMOUS_USER_PERMISSIONS)):
        return True
    if is_authenticated(user) and perms.issubset(set(WALIKI_LOGGED_USER_PERMISSIONS)):
        return True
    if user.has_perms(['waliki.%s' % p for p in perms]):
        return True
    if raise_exception:
        raise PermissionDenied
    return False

def get_module(app, modname, verbose=False, failfast=False):
    """Internal function to load a module from a single app.

    taken from https://github.com/ojii/django-load."""
    module_name = '%s.%s' % (app, modname)
    try:
        module = import_module(module_name)
    except ImportError as e:
        if failfast:
            raise e
        elif verbose:
            print('Could not load %r from %r: %s' % (modname, app, e))
        return None
    if verbose:
        print('Loaded %r from %r' % (modname, app))
    return module

def load(modname, verbose=False, failfast=False):
    """Loads all modules with name 'modname' from all installed apps.
    If verbose is True, debug information will be printed to stdout.
    If failfast is True, import errors will not be surpressed."""
    for app in settings.INSTALLED_APPS:
        get_module(app, modname, verbose, failfast)

