def byteToInt(byte):
    """byte -> int

    Determines whether to use ord() or not to get a byte's value."""
    if hasattr(byte, 'bit_length'):
        return byte
    return ord(byte) if hasattr(byte, 'encode') else byte[0]

def autodiscover():
    """Auto-discover INSTALLED_APPS backbone_api.py modules."""
