def retry(ExceptionToCheck, tries=4, delay=3, backoff=2):
    """Retry calling the decorated function using an exponential backoff.

    Reference: http://www.saltycrane.com/blog/2009/11/trying-out-retry
    -decorator-python/

    :param ExceptionToCheck: the exception to check. may be a tuple of
        exceptions to check
    :param tries: number of times to try (not retry) before giving up
    :param delay: initial delay between retries in seconds
    :param backoff: backoff multiplier e.g. value of 2 will double the delay
        each retry"""
    def deco_retry(f):
        @wraps(f)
        def f_retry(*args, **kwargs):
            mtries, mdelay = (tries, delay)
            while mtries > 1:
                try:
                    return f(*args, **kwargs)
                except ExceptionToCheck as e:
                    LOG.debug("%(err_mess)s. Retry calling function '%(f_name)s' in %(delta)d seconds.", {'err_mess': str(e), 'f_name': f.__name__, 'delta': mdelay})
                    time.sleep(mdelay)
                    mtries -= 1
                    mdelay *= backoff
            LOG.debug("Last retry calling function '%s'.", f.__name__)
            return f(*args, **kwargs)
        return f_retry
    return deco_retry

def is_valid_mac(addr):
    """Check the syntax of a given mac address.

    The acceptable format is xx:xx:xx:xx:xx:xx"""
    addrs = addr.split(':')
    if len(addrs) != 6:
        return False
    for m in addrs:
        try:
            if int(m, 16) > 255:
                return False
        except ValueError:
            return False
    return True

def make_cidr(gw, mask):
    """Create network address in CIDR format.

    Return network address for a given gateway address and netmask."""
    try:
        int_mask = 4294967295 << 32 - int(mask) & 4294967295
        gw_addr_int = struct.unpack('>L', socket.inet_aton(gw))[0] & int_mask
        return socket.inet_ntoa(struct.pack('!I', gw_addr_int)) + '/' + str(mask)
    except (socket.error, struct.error, ValueError, TypeError):
        return

