def valid_mimetype(type_, allow_none=True):
    """Checks for validity of given type, optionally allowing for a None value. Note: Unknown idx/NUMBER notation, where
    NUMBER is not a known shorthand mapping, will be rejected, i.e. type_ is valid if it
    1)  is an ASCII-only string between 1 & 64 characters long
    2a) does not begin with "idx/" OR
    2b) begins with "idx/" and is followed by a known shorthand index (integer)"""
    if isinstance(type_, unicode_type):
        match = __IDX_PATTERN.match(type_)
        if match:
            return match.group(1) in __IDX_MAPPING
        else:
            return __is_ascii(type_, 1, __MAX_LEN)
    else:
        return type_ is None and allow_none

def expand_idx_mimetype(type_):
    """Returns long equivalent of type_, if available, otherwise type_ itself. Does not raise exceptions"""
    if isinstance(type_, unicode_type):
        match = __IDX_PATTERN.match(type_)
        return __IDX_MAPPING.get(match.group(1), type_) if match else type_
    else:
        return type_

def decode_rcvd_msg(pref, message, seqnum, pretty=False):
    """decode_rcvd_msg: Return string of received message expanding short codes, optionally with newlines and indent
    """
    newline = '\n' if pretty else ' '
    indent = '    ' if pretty else ''
    start = newline + indent
    out = []
    out.append('%s%s{%sSEQNUM: %d,' % (pref, newline, start, seqnum))
    out.append('%sCLIENTREF: %s,' % (start, message[Const.M_CLIENTREF]))
    out.append('%sTYPE: %s,' % (start, M_TYPES[message[Const.M_TYPE]]))
    if message[Const.M_TYPE] in M_SUB_TYPES:
        out.append('%sPAYLOAD: {CODE: %s, MESSAGE: %s}' % (start, M_SUB_TYPES[message[Const.M_TYPE]][message[Const.M_PAYLOAD][Const.P_CODE]], message[Const.M_PAYLOAD][Const.P_MESSAGE]))
    else:
        payload = None
        if message[Const.M_PAYLOAD] is not None:
            payload = {}
            for item in message[Const.M_PAYLOAD]:
                if item == Const.P_RESOURCE:
                    payload['RESOURCE'] = R_TYPES[message[Const.M_PAYLOAD][Const.P_RESOURCE]]
                else:
                    payload[item] = message[Const.M_PAYLOAD][item]
        out.append('%sPAYLOAD: %s' % (start, payload))
    out.append('%s}' % newline)
    return ''.join(out)

def bool_from(obj, default=False):
    """Returns True if obj is not None and its string representation is not 0 or False (case-insensitive). If obj is
    None, 'default' is used."""
    return str(obj).lower() not in ('0', 'false') if obj is not None else bool(default)

def private_name_for(var_name, cls):
    """Returns mangled variable name (if applicable) for the given variable and class instance.
    See https://docs.python.org/3/tutorial/classes.html#private-variables"""
    if not (isinstance(var_name, string_types) and var_name):
        raise TypeError('var_name must be non-empty string')
    if not (isinstance(cls, type) or isinstance(cls, string_types)):
        raise TypeError('cls not a class or string')
    if __PRIVATE_NAME_PATTERN.match(var_name):
        class_name = cls.__name__ if isinstance(cls, type) else cls
        return '_%s%s' % (class_name.lstrip('_'), var_name)
    else:
        return var_name

def profiled_thread(func):
    """decorator to profile a thread or function. Profiling output will be written to
    'agent_profile_<process_id>.<thread_id_>.<thread_name>.log'"""
    def wrapper(*args, **kwargs):
        profile = Profile()
        profile.enable()
        try:
            func(*args, **kwargs)
        finally:
            profile.disable()
        try:
            thread = current_thread()
            profile.dump_stats('profile_%s.%s.%s.log' % (getpid(), thread.name, thread.ident))
        except:
            logger.exception('Failed to dump stats')
    return wrapper

def get_s3_multipart_chunk_size(filesize):
    """Returns the chunk size of the S3 multipart object, given a file's size."""
    if filesize <= AWS_MAX_MULTIPART_COUNT * AWS_MIN_CHUNK_SIZE:
        return AWS_MIN_CHUNK_SIZE
    else:
        div = filesize // AWS_MAX_MULTIPART_COUNT
        if div * AWS_MAX_MULTIPART_COUNT < filesize:
            div += 1
        return (div + MiB - 1) // MiB * MiB

def _contains_yieldpoint(children):
    """Returns True if ``children`` contains any YieldPoints.

    ``children`` may be a dict or a list, as used by `MultiYieldPoint`
    and `multi_future`."""
    if isinstance(children, dict):
        return any((isinstance(i, YieldPoint) for i in children.values()))
    if isinstance(children, list):
        return any((isinstance(i, YieldPoint) for i in children))
    return False

def _argument_adapter(callback):
    """Returns a function that when invoked runs ``callback`` with one arg.

    If the function returned by this function is called with exactly
    one argument, that argument is passed to ``callback``.  Otherwise
    the args tuple and kwargs dict are wrapped in an `Arguments` object."""
    def wrapper(*args, **kwargs):
        if kwargs or len(args) > 1:
            callback(Arguments(args, kwargs))
        elif args:
            callback(args[0])
        else:
            callback(None)
    return wrapper

def convert_yielded(yielded):
    """Convert a yielded object into a `.Future`.

    The default implementation accepts lists, dictionaries, and Futures.

    If the `~functools.singledispatch` library is available, this function
    may be extended to support additional types. For example::

        @convert_yielded.register(asyncio.Future)
        def _(asyncio_future):
            return tornado.platform.asyncio.to_tornado_future(asyncio_future)

    .. versionadded:: 4.1"""
    if yielded is None:
        return moment
    elif isinstance(yielded, (list, dict)):
        return multi(yielded)
    elif is_future(yielded):
        return yielded
    elif isawaitable(yielded):
        return _wrap_awaitable(yielded)
    else:
        raise BadYieldError('yielded unknown object %r' % (yielded,))

def update_atom_members(old, new):
    """Update an atom member"""
    old_keys = old.members().keys()
    new_keys = new.members().keys()
    for key in old_keys:
        old_obj = getattr(old, key)
        try:
            new_obj = getattr(new, key)
            if old_obj == new_obj:
                continue
        except AttributeError:
            try:
                delattr(old, key)
            except (AttributeError, TypeError):
                pass
            continue
        try:
            setattr(old, key, getattr(new, key))
        except (AttributeError, TypeError):
            pass
    for key in set(new_keys) - set(old_keys):
        try:
            setattr(old, key, getattr(new, key))
        except (AttributeError, TypeError):
            pass

def update_class_by_type(old, new):
    """Update declarative classes or fallback on default"""
    autoreload.update_class(old, new)
    if isinstance2(old, new, AtomMeta):
        update_atom_members(old, new)

def run_on_executor(*args, **kwargs):
    """Decorator to run a synchronous method asynchronously on an executor.

    The decorated method may be called with a ``callback`` keyword
    argument and returns a future.

    The executor to be used is determined by the ``executor``
    attributes of ``self``. To use a different attribute name, pass a
    keyword argument to the decorator::

        @run_on_executor(executor='_thread_pool')
        def foo(self):
            pass

    .. versionchanged:: 4.2
       Added keyword arguments to use alternative attributes.

    .. versionchanged:: 5.0
       Always uses the current IOLoop instead of ``self.io_loop``."""
    def run_on_executor_decorator(fn):
        executor = kwargs.get('executor', 'executor')
        @functools.wraps(fn)
        def wrapper(self, *args, **kwargs):
            callback = kwargs.pop('callback', None)
            future = getattr(self, executor).submit(fn, self, *args, **kwargs)
            if callback:
                from .ioloop import IOLoop
                IOLoop.current().add_future(future, lambda future: callback(future.result()))
            return future
        return wrapper
    if args and kwargs:
        raise ValueError('cannot combine positional and keyword args')
    if len(args) == 1:
        return run_on_executor_decorator(args[0])
    elif len(args) != 0:
        raise ValueError('expected 1 argument, got %d', len(args))
    return run_on_executor_decorator

def chain_future(a, b):
    """Chain two futures together so that when one completes, so does the other.

    The result (success or failure) of ``a`` will be copied to ``b``, unless
    ``b`` has already been completed or cancelled by the time ``a`` finishes."""
    def copy(future):
        assert future is a
        if b.done():
            return
        if isinstance(a, TracebackFuture) and isinstance(b, TracebackFuture) and (a.exc_info() is not None):
            b.set_exc_info(a.exc_info())
        elif a.exception() is not None:
            b.set_exception(a.exception())
        else:
            b.set_result(a.result())
    a.add_done_callback(copy)

def _remove_deactivated(contexts):
    """Remove deactivated handlers from the chain"""
    stack_contexts = tuple([h for h in contexts[0] if h.active])
    head = contexts[1]
    while head is not None and (not head.active):
        head = head.old_contexts[1]
    ctx = head
    while ctx is not None:
        parent = ctx.old_contexts[1]
        while parent is not None:
            if parent.active:
                break
            ctx.old_contexts = parent.old_contexts
            parent = parent.old_contexts[1]
        ctx = parent
    return (stack_contexts, head)

def errno_from_exception(e):
    """Provides the errno from an Exception object.

    There are cases that the errno attribute was not set so we pull
    the errno out of the args but if someone instantiates an Exception
    without any args you will get a tuple error. So this function
    abstracts all that behavior to give you a safe way to get the
    errno."""
    if hasattr(e, 'errno'):
        return e.errno
    elif e.args:
        return e.args[0]
    else:
        return None

def _websocket_mask_python(mask, data):
    """Websocket masking function.

    `mask` is a `bytes` object of length 4; `data` is a `bytes` object of any length.
    Returns a `bytes` object of the same length as `data` with the mask applied
    as specified in section 5.3 of RFC 6455.

    This pure-python implementation may be replaced by an optimized version when available."""
    mask_arr = array.array('B', mask)
    unmasked_arr = array.array('B', data)
    for i in xrange(len(data)):
        unmasked_arr[i] = unmasked_arr[i] ^ mask_arr[i % 4]
    if PY3:
        return unmasked_arr.tobytes()
    else:
        return unmasked_arr.tostring()

def source_from_cache(path):
    """Given the path to a .pyc. file, return the path to its .py file.
    The .pyc file does not need to exist; this simply returns the path to
    the .py file calculated to correspond to the .pyc file.  If path does
    not conform to PEP 3147/488 format, ValueError will be raised. If
    sys.implementation.cache_tag is None then NotImplementedError is raised."""
    head, pycache_filename = os.path.split(path)
    head, pycache = os.path.split(head)
    if pycache != _PYCACHE:
        raise ValueError('{} not bottom-level directory in {!r}'.format(_PYCACHE, path))
    dot_count = pycache_filename.count('.')
    if dot_count not in {2, 3}:
        raise ValueError('expected only 2 or 3 dots in {!r}'.format(pycache_filename))
    elif dot_count == 3:
        optimization = pycache_filename.rsplit('.', 2)[-2]
        if not optimization.startswith(_OPT):
            raise ValueError('optimization portion of filename does not start with {!r}'.format(_OPT))
        opt_level = optimization[len(_OPT):]
        if not opt_level.isalnum():
            raise ValueError('optimization level {!r} is not an alphanumeric value'.format(optimization))
    base_filename = pycache_filename.partition('.')[0]
    return os.path.join(head, base_filename + SOURCE_SUFFIXES[0])

def compare_versions(x, y):
    """Expects 2 strings in the format of 'X.Y.Z' where X, Y and Z are
    integers. It will compare the items which will organize things
    properly by their major, minor and bugfix version.
    ::

        >>> my_list = ['v1.13', 'v1.14.2', 'v1.14.1', 'v1.9', 'v1.1']
        >>> sorted(my_list, cmp=compare_versions)
        ['v1.1', 'v1.9', 'v1.13', 'v1.14.1', 'v1.14.2']"""
    def version_to_tuple(version):
        version_list = version[1:].split('.', 2)
        if len(version_list) <= 3:
            [version_list.append(0) for _ in range(3 - len(version_list))]
        try:
            return tuple((int(version) for version in version_list))
        except ValueError:
            return (0, 0, 0)
    x_major, x_minor, x_bugfix = version_to_tuple(x)
    y_major, y_minor, y_bugfix = version_to_tuple(y)
    return cmp(x_major, y_major) or cmp(x_minor, y_minor) or cmp(x_bugfix, y_bugfix)

def transformTimeDependentVector(quat, vec, inverse=0):
    """Given (for example) a minimal rotation frame quat, transforms
    vec from the minimal rotation frame to the inertial frame.
    With inverse=1, transforms from the inertial frame to the minimal
    rotation frame."""
    qInv = quatInv(quat)
    if inverse:
        return transformTimeDependentVector(qInv, vec, inverse=0)
    return multiplyQuats(quat, multiplyQuats(np.append(np.array([np.zeros(len(vec[0]))]), vec, 0), qInv))[1:]

def LoadFits(name):
    """Loads data for a fit.
    If data is not available, downloads it before loading."""
    if name not in fits_collection.keys():
        raise Exception('Invalid fit name : %s' % name)
    else:
        testPath = DataPath() + '/' + fits_collection[name].data_url.split('/')[-1]
        if not os.path.isfile(testPath):
            DownloadData(name)
        fit = fits_collection[name].fit_class(name.split('surfinBH')[-1])
        print('Loaded %s fit.' % name)
