def DownloadData(name='all', data_dir=DataPath()):
    """Downloads fit data to DataPath() diretory.
    If name='all', gets all fit data."""
    if name == 'all':
        for tmp_name in fits_collection.keys():
            DownloadData(name=tmp_name, data_dir=data_dir)
        return
    if name not in fits_collection.keys():
        raise Exception('Invalid fit name : %s' % name)
    print('Downloading %s data' % name)
    data_url = fits_collection[name].data_url
    filename = data_url.split('/')[-1]
    try:
        os.makedirs(data_dir)
    except OSError as exc:
        if exc.errno == errno.EEXIST and os.path.isdir(data_dir):
            pass
        else:
            raise
    urlretrieve(data_url, data_dir + '/' + filename)

def is_null(value):
    """Check if the scalar value or tuple/list value is NULL.

    :param value: Value to check.
    :type value: a scalar or tuple or list

    :return: Returns ``True`` if and only if the value is NULL (scalar value is None
        or _any_ tuple/list elements are None).
    :rtype: bool"""
    if type(value) in (tuple, list):
        for v in value:
            if v is None:
                return True
        return False
    else:
        return value is None

def qual(obj):
    """Return fully qualified name of a class."""
    return u'{}.{}'.format(obj.__class__.__module__, obj.__class__.__name__)

def _random_string():
    """Generate a globally unique serial / product code of the form ``u'YRAC-EL4X-FQQE-AW4T-WNUV-VN6T'``.
    The generated value is cryptographically strong and has (at least) 114 bits of entropy.

    :return: new random string key"""
    rng = random.SystemRandom()
    token_value = u''.join((rng.choice(CHARSET) for _ in range(CHAR_GROUPS * CHARS_PER_GROUP)))
    if CHARS_PER_GROUP > 1:
        return GROUP_SEP.join(map(u''.join, zip(*[iter(token_value)] * CHARS_PER_GROUP)))
    else:
        return token_value

def DataPath():
