def request_object_encryption(msg, service_context, **kwargs):
    """Created an encrypted JSON Web token with *msg* as body.

    :param msg: The mesaqg
    :param service_context:
    :param kwargs:
    :return:"""
    try:
        encalg = kwargs['request_object_encryption_alg']
    except KeyError:
        try:
            encalg = service_context.behaviour['request_object_encryption_alg']
        except KeyError:
            return msg
    if not encalg:
        return msg
    try:
        encenc = kwargs['request_object_encryption_enc']
    except KeyError:
        try:
            encenc = service_context.behaviour['request_object_encryption_enc']
        except KeyError:
            raise MissingRequiredAttribute('No request_object_encryption_enc specified')
    if not encenc:
        raise MissingRequiredAttribute('No request_object_encryption_enc specified')
    _jwe = JWE(msg, alg=encalg, enc=encenc)
    _kty = alg2keytype(encalg)
    try:
        _kid = kwargs['enc_kid']
    except KeyError:
        _kid = ''
    if 'target' not in kwargs:
        raise MissingRequiredAttribute('No target specified')
    if _kid:
        _keys = service_context.keyjar.get_encrypt_key(_kty, owner=kwargs['target'], kid=_kid)
        _jwe['kid'] = _kid
    else:
        _keys = service_context.keyjar.get_encrypt_key(_kty, owner=kwargs['target'])
    return _jwe.encrypt(_keys)

def init_services(service_definitions, service_context, state_db, client_authn_factory=None):
    """Initiates a set of services

    :param service_definitions: A dictionary cotaining service definitions
    :param service_context: A reference to the service context, this is the same
        for all service instances.
    :param state_db: A reference to the state database. Shared by all the
        services.
    :param client_authn_factory: A list of methods the services can use to
        authenticate the client to a service.
    :return: A dictionary, with service name as key and the service instance as
        value."""
    service = {}
    for service_name, service_configuration in service_definitions.items():
        try:
            kwargs = service_configuration['kwargs']
        except KeyError:
            kwargs = {}
        kwargs.update({'service_context': service_context, 'state_db': state_db, 'client_authn_factory': client_authn_factory})
        if isinstance(service_configuration['class'], str):
            _srv = util.importer(service_configuration['class'])(**kwargs)
        else:
            _srv = service_configuration['class'](**kwargs)
        try:
            service[_srv.service_name] = _srv
        except AttributeError:
            raise ValueError("Could not load '{}'".format(service_name))
    return service

def get_http_url(url, req, method='GET'):
    """Add a query part representing the request to a url that may already contain
    a query part. Only done if the HTTP method used is 'GET' or 'DELETE'.

    :param url: The URL
    :param req: The request as a :py:class:`oidcmsg.message.Message` instance
    :param method: The HTTP method
    :return: A possibly modified URL"""
    if method in ['GET', 'DELETE']:
        if req.keys():
            _req = req.copy()
            comp = urlsplit(str(url))
            if comp.query:
                _req.update(parse_qs(comp.query))
            _query = str(_req.to_urlencoded())
            return urlunsplit((comp.scheme, comp.netloc, comp.path, _query, comp.fragment))
        else:
            return url
    else:
        return url

def get_http_body(req, content_type=URL_ENCODED):
    """Get the message into the format that should be places in the body part
    of a HTTP request.

    :param req: The service request as a  :py:class:`oidcmsg.message.Message`
        instance
    :param content_type: The format of the body part.
    :return: The correctly formatet service request."""
    if URL_ENCODED in content_type:
        return req.to_urlencoded()
    elif JSON_ENCODED in content_type:
        return req.to_json()
    elif JOSE_ENCODED in content_type:
        return req
    else:
        raise UnSupported("Unsupported content type: '%s'" % content_type)

def modsplit(s):
    """Split importable"""
    if ':' in s:
        c = s.split(':')
        if len(c) != 2:
            raise ValueError('Syntax error: {s}')
        return (c[0], c[1])
    else:
        c = s.split('.')
        if len(c) < 2:
            raise ValueError('Syntax error: {s}')
        return ('.'.join(c[:-1]), c[-1])

def importer(name):
    """Import by name"""
    c1, c2 = modsplit(name)
    module = importlib.import_module(c1)
    return getattr(module, c2)

def rndstr(size=16):
    """Returns a string of random ascii characters or digits

    :param size: The length of the string
    :return: string"""
    _basech = string.ascii_letters + string.digits
    return ''.join([rnd.choice(_basech) for _ in range(size)])

def add_redirect_uris(request_args, service=None, **kwargs):
    """Add redirect_uris to the request arguments.

    :param request_args: Incomming request arguments
    :param service: A link to the service
    :param kwargs: Possible extra keyword arguments
    :return: A possibly augmented set of request arguments."""
    _context = service.service_context
    if 'redirect_uris' not in request_args:
        try:
            _cbs = _context.callbacks
        except AttributeError:
            request_args['redirect_uris'] = _context.redirect_uris
        else:
            _uris = [v for k, v in _cbs.items() if not k.startswith('__')]
            request_args['redirect_uris'] = _uris
    return (request_args, {})

def _api_wrapper(fn):
    """API function decorator that performs rate limiting and error checking."""
    def _convert(value):
        if isinstance(value, _datetime.date):
            return value.strftime('%s')
        return value
    @_six.wraps(fn)
    def _fn(self, command, **params):
        with self.startup_lock:
            if self.timer.ident is None:
                self.timer.setDaemon(True)
                self.timer.start()
        params = dict(((key, _convert(value)) for key, value in _six.iteritems(params) if value is not None))
        self.semaphore.acquire()
        resp = fn(self, command, **params)
        try:
            respdata = resp.json(object_hook=_AutoCastDict)
        except:
            resp.raise_for_status()
            raise Exception('No JSON object could be decoded')
        if 'error' in respdata:
            raise PoloniexCommandException(respdata['error'])
        resp.raise_for_status()
        return respdata
    return _fn

def generate_new_cid(upstream_cid=None):
    """Generate a new correlation id, possibly based on the given one."""
    if upstream_cid is None:
        return str(uuid.uuid4()) if getattr(settings, 'CID_GENERATE', False) else None
    if getattr(settings, 'CID_CONCATENATE_IDS', False) and getattr(settings, 'CID_GENERATE', False):
        return '%s, %s' % (upstream_cid, str(uuid.uuid4()))
    return upstream_cid

def import_from_string(val, setting_name):
    """Attempt to import a class from a string representation."""
    try:
        parts = val.split('.')
        module_path, class_name = ('.'.join(parts[:-1]), parts[-1])
        module = importlib.import_module(module_path)
        return getattr(module, class_name)
    except (ImportError, AttributeError) as e:
        msg = "Could not import '%s' for Graph Auth setting '%s'. %s: %s." % (val, setting_name, e.__class__.__name__, e)
        raise ImportError(msg)

def getitem_by_path(d, path):
    """Access item in d using path.

    a = { 0: { 1: 'item' } }
    getitem_by_path(a, [0, 1]) == 'item'"""
    return reduce(lambda d, k: d[k], path, d)

def _format_usage_without_prefix(parser):
    """Use private argparse APIs to get the usage string without
    the 'usage: ' prefix."""
    fmt = parser._get_formatter()
    fmt.add_usage(parser.usage, parser._actions, parser._mutually_exclusive_groups, prefix='')
    return fmt.format_help().strip()

def _get_command(classes):
    """Associates each command class with command depending on setup.cfg
    """
    commands = {}
    setup_file = os.path.join(os.path.abspath(os.path.join(os.path.dirname(__file__), '../..')), 'setup.cfg')
    for line in open(setup_file, 'r'):
        for cl in classes:
            if cl in line:
                commands[cl] = line.split(' = ')[0].strip().replace('_', ' ')
    return commands

def get_json(response):
    """Provide backward compatibility with old versions of requests library."""
    json_field_or_function = getattr(response, 'json', None)
