    return '{0:f},{1:f}'.format(Decimal(str(lat)), Decimal(str(lng)))

def floatify_latlng(input_value):
    """Work around a JSON dict with string, not float, lat/lngs.

    Given anything (list/dict/etc) it will return that thing again, *but* any
    dict (at any level) that has only 2 elements lat & lng, will be replaced
    with the lat & lng turned into floats.

    If the API returns the lat/lng as strings, and not numbers, then this
    function will 'clean them up' to be floats."""
    if isinstance(input_value, collections.Mapping):
        if len(input_value) == 2 and sorted(input_value.keys()) == ['lat', 'lng']:
            return {'lat': float_if_float(input_value['lat']), 'lng': float_if_float(input_value['lng'])}
        else:
            return dict(((key, floatify_latlng(value)) for key, value in input_value.items()))
    elif isinstance(input_value, collections.MutableSequence):
        return [floatify_latlng(x) for x in input_value]
    else:
        return input_value

def _parse_schema(schema, method):
    """Convert a Schema Object to a Python object.

    Args:
        schema: An ``OrderedDict`` representing the schema object."""
    if method and schema.get('readOnly', False):
        return _READONLY_PROPERTY
    if 'allOf' in schema:
        schema_ = copy.deepcopy(schema['allOf'][0])
        for x in schema['allOf'][1:]:
            _dict_merge(schema_, x)
        return _parse_schema(schema_, method)
    if 'oneOf' in schema:
        return _parse_schema(schema['oneOf'][0], method)
    if 'enum' in schema:
        return schema['enum'][0]
    schema_type = schema.get('type', 'object')
    if schema_type == 'array':
        if 'oneOf' in schema['items']:
            return [_parse_schema(x, method) for x in schema['items']['oneOf']]
        return [_parse_schema(schema['items'], method)]
    if schema_type == 'object':
        if method and all((v.get('readOnly', False) for v in schema['properties'].values())):
            return _READONLY_PROPERTY
        results = []
        for name, prop in schema.get('properties', {}).items():
            result = _parse_schema(prop, method)
            if result != _READONLY_PROPERTY:
                results.append((name, result))
        return collections.OrderedDict(results)
    if (schema_type, schema.get('format')) in _TYPE_MAPPING:
        return _TYPE_MAPPING[schema_type, schema.get('format')]
    return _TYPE_MAPPING[schema_type, None]

def _resolve_refs(uri, spec):
    """Resolve JSON references in a given dictionary.

    OpenAPI spec may contain JSON references to its nodes or external
    sources, so any attempt to rely that there's some expected attribute
    in the spec may fail. So we need to resolve JSON references before
    we use it (i.e. replace with referenced object). For details see:

        https://tools.ietf.org/html/draft-pbryan-zyp-json-ref-02

    The input spec is modified in-place despite being returned from
    the function."""
    resolver = jsonschema.RefResolver(uri, spec)
    def _do_resolve(node):
        if isinstance(node, collections.Mapping) and '$ref' in node:
            with resolver.resolving(node['$ref']) as resolved:
                return resolved
        elif isinstance(node, collections.Mapping):
            for k, v in node.items():
                node[k] = _do_resolve(v)
        elif isinstance(node, (list, tuple)):
            for i in range(len(node)):
                node[i] = _do_resolve(node[i])
        return node
    return _do_resolve(spec)

def _rotatedRectWithMaxArea(w, h, angle):
    """Given a rectangle of size wxh that has been rotated by 'angle' (in
    radians), computes the width and height of the largest possible
    axis-aligned rectangle (maximal area) within the rotated rectangle.

    Answer from: https://stackoverflow.com/questions/16702966/rotate-image-and-crop-out-black-borders"""
    if w <= 0 or h <= 0:
        return (0, 0)
    width_is_longer = w >= h
    side_long, side_short = (w, h) if width_is_longer else (h, w)
    sin_a, cos_a = (abs(math.sin(angle)), abs(math.cos(angle)))
    if side_short <= 2.0 * sin_a * cos_a * side_long or abs(sin_a - cos_a) < 1e-10:
        x = 0.5 * side_short
        wr, hr = (x / sin_a, x / cos_a) if width_is_longer else (x / cos_a, x / sin_a)
    else:
        cos_2a = cos_a * cos_a - sin_a * sin_a
        wr, hr = ((w * cos_a - h * sin_a) / cos_2a, (h * cos_a - w * sin_a) / cos_2a)
    return (wr, hr)

def get_cloudformation_client(service_name, environment_name):
    """Given a service name and an environment name, return a boto CloudFormation
    client object."""
    region = service_registry.service_region(service_name)
    if whereami() == 'ec2':
        profile = None
    else:
        profile = get_account_alias(environment_name)
    clients = create_aws_clients(region, profile, 'cloudformation')
    return clients['cloudformation']

def evaluate_service_changes(services, envs, repo_root, func):
    """Given a dict of services, and a list of environments, apply the diff
    function to evaluate the differences between the target environments
    and the rendered templates.

    Sub-services (names with '.' in them) are skipped."""
    for service_name, service in services.iteritems():
        for env_category in service['environments']:
            if env_category not in get_env_categories(envs):
                logger.debug('Skipping not-included environment `%s` for service `%s`', env_category, service_name)
                continue
            environment = generate_test_environment_name(env_category)
            cf_client = get_cloudformation_client(service_name, environment)
            func(service_name, service, environment, cf_client, repo_root)

def get_dict_registry_services(registry, template_files, warn_missing_files=True):
    """Return a dict mapping service name to a dict containing the service's
    type ('fixtures', 'platform_services', 'application_services', 'internal_services'),
    the template file's absolute path, and a list of environments to which the
    service is intended to deploy.

    Service names that appear twice in the output list will emit a warning and
    ignore the latter records.

    Services which have no template file will not appear in the returned dict.
    If the `warn_missing_files` boolean is True these files will emit a warning."""
    with open(registry) as fr:
        parsed_registry = json.load(fr)
    services = {}
    for type, type_services in parsed_registry.iteritems():
        for name, service in type_services.iteritems():
            if name in services:
                logger.warning('Template name appears twice, ignoring later items: `%s`', name)
                continue
            template_file = get_matching_service_template_file(name, template_files)
            if not template_file:
                if warn_missing_files:
                    logger.warning('No template file for `%s` (%s) `%s`', type, service['type'], name)
                continue
            services[name] = {'type': type, 'template_file': template_file, 'environments': service['environments']}
    return services

def scan_dir_for_template_files(search_dir):
    """Return a map of "likely service/template name" to "template file".
    This includes all the template files in fixtures and in services."""
    template_files = {}
    cf_dir = os.path.join(search_dir, 'cloudformation')
    for type in os.listdir(cf_dir):
        template_dir = os.path.join(cf_dir, type, 'templates')
        for x in os.listdir(template_dir):
            name = os.path.splitext(x)[0]
            template_files[name] = os.path.join(template_dir, x)
    return template_files

def layer(op):
    """Decorator for composable network layers."""
    def layer_decorated(self, *args, **kwargs):
        name = kwargs.setdefault('name', self.get_unique_name(op.__name__))
        if len(self.terminals) == 0:
            raise RuntimeError('No input variables found for layer %s.' % name)
        elif len(self.terminals) == 1:
            layer_input = self.terminals[0]
        else:
            layer_input = list(self.terminals)
        layer_output = op(self, layer_input, *args, **kwargs)
        self.layers[name] = layer_output
        self.feed(layer_output)
        return self
    return layer_decorated

def multi_output_layer(op):
    """Decorator for composable network layers."""
    def layer_decorated(self, *args, **kwargs):
        name = kwargs.setdefault('name', self.get_unique_name(op.__name__))
        output_names = kwargs.setdefault('output_names', self.get_unique_name(op.__name__))
        if len(self.terminals) == 0:
            raise RuntimeError('No input variables found for layer %s.' % name)
        elif len(self.terminals) == 1:
            layer_input = self.terminals[0]
        else:
            layer_input = list(self.terminals)
        layer_output = op(self, layer_input, *args, **kwargs)
        for i in range(len(output_names)):
            self.layers[output_names[i]] = layer_output[i]
        self.feed(layer_output)
        return self
    return layer_decorated

def mode_to_str(mode):
    """Converts a tf.estimator.ModeKeys in a nice readable string.
    :param mode: The mdoe as a tf.estimator.ModeKeys
    :return: A human readable string representing the mode."""
    if mode == tf.estimator.ModeKeys.TRAIN:
        return 'train'
    if mode == tf.estimator.ModeKeys.EVAL:
        return 'eval'
    if mode == tf.estimator.ModeKeys.PREDICT:
        return 'predict'
    return 'unknown'

def create_input_fn(prefix, batch_size, augmentation=None):
    """Loads a dataset.

    :param prefix: The path prefix as defined in the write data method.
    :param batch_size: The batch size you want for the tensors.
    :param augmentation: An augmentation function.
    :return: An input function for a tf estimator."""
    if tf.__version__.startswith('1.6') or tf.__version__.startswith('1.5') or tf.__version__.startswith('1.4') or tf.__version__.startswith('1.3') or tf.__version__.startswith('1.2') or tf.__version__.startswith('1.1') or tf.__version__.startswith('1.0'):
        def input_fn():
            with tf.variable_scope('input_pipeline'):
                return _read_data_legacy(prefix, batch_size)
        return input_fn
    else:
        def input_fn():
            with tf.variable_scope('input_pipeline'):
                return _read_data(prefix, batch_size, augmentation)
        return input_fn

def validate_context(context):
    """Set the key for the current context.
    Args:
      context: a populated EFVersionContext object"""
    if not context.service_registry.service_record(context.service_name):
        fail('service: {} not found in service registry: {}'.format(context.service_name, context.service_registry.filespec))
    service_type = context.service_registry.service_record(context.service_name)['type']
    if context.key not in EFConfig.VERSION_KEYS:
        fail('invalid key: {}; see VERSION_KEYS in ef_config for supported keys'.format(context.key))
    if 'allowed_types' in EFConfig.VERSION_KEYS[context.key] and service_type not in EFConfig.VERSION_KEYS[context.key]['allowed_types']:
        fail("service_type: {} is not allowed for key {}; see VERSION_KEYS[KEY]['allowed_types']in ef_config and validate service registry entry".format(service_type, context.key))
    return True

def get_versions(context, return_stable=False):
    """Get all versions of a key
    Args:
      context: a populated EFVersionContext object
      return_stable: (default:False) If True, stop fetching if 'stable' version is found; return only that version
    Returns:
      json list of object data sorted in reverse by last_modified (newest version is first). Each item is a dict:
      {
        'value': <value>,
        'last_modified": <YYYY-MM-DDThh:mm:ssZ>, (ISO8601 date time string)
        'modified_by': '<arn:aws:...>',
        'version_id': '<version_id>',
        'status': See EF_Config.S3_VERSION_STATUS_* for possible values
      }"""
    s3_key = '{}/{}/{}'.format(context.service_name, context.env, context.key)
    object_version_list = context.aws_client('s3').list_object_versions(Bucket=EFConfig.S3_VERSION_BUCKET, Delimiter='/', MaxKeys=context.limit, Prefix=s3_key)
    if 'Versions' not in object_version_list:
        return []
    object_versions = []
    for version in object_version_list['Versions']:
        object_version = Version(context.aws_client('s3').get_object(Bucket=EFConfig.S3_VERSION_BUCKET, Key=s3_key, VersionId=version['VersionId']))
        if return_stable and object_version.status == EFConfig.S3_VERSION_STATUS_STABLE:
            return [object_version]
        object_versions.append(object_version)
    if return_stable:
        return []
    else:
        return sorted(object_versions, key=lambda v: v.last_modified, reverse=True)

def get_version_by_value(context, value):
    """Get the latest version that matches the provided ami-id
    Args:
      context: a populated EFVersionContext object
      value: the value of the version to look for"""
    versions = get_versions(context)
    for version in versions:
        if version.value == value:
            return version
    fail("Didn't find a matching version for: {}:{} in env/service: {}/{}".format(context.key, value, context.env, context.service_name))

def fail(message, exception_data=None):
    """Print a failure message and exit nonzero"""
    print(message, file=sys.stderr)
    if exception_data:
        print(repr(exception_data))
    sys.exit(1)

def http_get_metadata(metadata_path, timeout=__HTTP_DEFAULT_TIMEOUT_SEC):
    """Fetch AWS metadata from http://169.254.169.254/latest/meta-data/<metadata_path>
    ARGS:
      metadata_path - the optional path and required key to the EC2 metadata (e.g. "instance-id")
    RETURN:
      response content on success
    RAISE:
      URLError if there was a problem reading metadata"""
    metadata_path = __METADATA_PREFIX + metadata_path
    try:
        response = urllib2.urlopen(metadata_path, None, timeout)
        if response.getcode() != 200:
            raise IOError('Non-200 response ' + str(response.getcode()) + ' reading ' + metadata_path)
        return response.read()
    except urllib2.URLError as error:
        raise IOError('URLError in http_get_metadata: ' + repr(error))

def is_in_virtualbox():
    """Is the current environment a virtualbox instance?
    Returns a boolean
    Raises IOError if the necessary tooling isn't available"""
    if not isfile(__VIRT_WHAT) or not access(__VIRT_WHAT, X_OK):
        raise IOError('virt-what not available')
    try:
        return subprocess.check_output(['sudo', '-n', __VIRT_WHAT]).split('\n')[0:2] == __VIRT_WHAT_VIRTUALBOX_WITH_KVM
    except subprocess.CalledProcessError as e:
        raise IOError('virt-what failed execution with {}'.format(e))

def whereami():
    """Determine if this is an ec2 instance or "running locally"
    Returns:
      "ec2" - this is an ec2 instance
      "virtualbox-kvm" - kernel VM (virtualbox with vagrant)
      "local" - running locally and not in a known VM
      "unknown" - I have no idea where I am"""
    try:
        response = http_get_metadata('instance-id', 1)
        if response[:2] == 'i-':
            return 'ec2'
    except:
        pass
    try:
        if is_in_virtualbox():
            return 'virtualbox-kvm'
    except:
        pass
    hostname = gethostname()
    if re.findall('\\.local$', hostname):
        return 'local'
    return 'unknown'

def http_get_instance_env():
    '''Returns: just the env this ec2 instance is in. Doesn't require API access like get_instance_aws_context does
    Example return value: "staging"'''
    try:
        info = json.loads(http_get_metadata('iam/info'))
    except Exception as error:
        raise IOError('Error looking up metadata:iam/info: ' + repr(error))
    return info['InstanceProfileArn'].split(':')[5].split('/')[1].split('-', 1)[0]

def pull_repo():
    """Pulls latest version of EF_REPO_BRANCH from EF_REPO (as set in ef_config.py) if client is in EF_REPO
    and on the branch EF_REPO_BRANCH
    Raises:
      RuntimeError with message if not in the correct repo on the correct branch"""
    try:
        current_repo = subprocess.check_output(['git', 'remote', '-v', 'show'])
    except subprocess.CalledProcessError as error:
        raise RuntimeError('Exception checking current repo', error)
    current_repo = re.findall('(https://|@)(.*?)(.git|[ ])', current_repo)[0][1].replace(':', '/')
    if current_repo != EFConfig.EF_REPO:
        raise RuntimeError('Must be in ' + EFConfig.EF_REPO + ' repo. Current repo is: ' + current_repo)
    try:
        current_branch = subprocess.check_output(['git', 'rev-parse', '--abbrev-ref', 'HEAD']).rstrip()
    except subprocess.CalledProcessError as error:
        raise RuntimeError('Exception checking current branch: ' + repr(error))
    if current_branch != EFConfig.EF_REPO_BRANCH:
        raise RuntimeError('Must be on branch: ' + EFConfig.EF_REPO_BRANCH + '. Current branch is: ' + current_branch)
    try:
        subprocess.check_call(['git', 'pull', '-q', 'origin', EFConfig.EF_REPO_BRANCH])
    except subprocess.CalledProcessError as error:
        raise RuntimeError("Exception running 'git pull': " + repr(error))

def kms_decrypt(kms_client, secret):
    """Decrypt kms-encrypted string
    Args:
      kms_client (boto3 kms client object): Instantiated kms client object. Usually created through create_aws_clients.
      secret (string): base64 encoded value to be decrypted
    Returns:
      a populated EFPWContext object
    Raises:
      SystemExit(1): If there is an error with the boto3 decryption call (ex. malformed secret)"""
    try:
        decrypted_secret = kms_client.decrypt(CiphertextBlob=base64.b64decode(secret))['Plaintext']
    except TypeError:
        fail('Malformed base64 string data')
    except ClientError as error:
        if error.response['Error']['Code'] == 'InvalidCiphertextException':
            fail('The decrypt request was rejected because the specified ciphertext       has been corrupted or is otherwise invalid.', error)
        elif error.response['Error']['Code'] == 'NotFoundException':
            fail('The decrypt request was rejected because the specified entity or resource could not be found.', error)
        else:
            fail('boto3 exception occurred while performing kms decrypt operation.', error)
    return decrypted_secret

def get_template_parameters_file(template_full_path):
    """Checks for existance of parameters file against supported suffixes and returns parameters file path if found
    Args:
      template_full_path: full filepath for template file
    Returns:
      filename of parameters file if it exists"""
    for suffix in EFConfig.PARAMETER_FILE_SUFFIXES:
        parameters_file = template_full_path.replace('/templates', '/parameters') + suffix
        if exists(parameters_file):
            return parameters_file
        else:
            continue
    return None

def conditionally_attach_managed_policies(role_name, sr_entry):
    """If 'aws_managed_policies' key lists the names of AWS managed policies to bind to the role,
    attach them to the role
    Args:
      role_name: name of the role to attach the policies to
      sr_entry: service registry entry"""
    service_type = sr_entry['type']
    if not (service_type in SERVICE_TYPE_ROLE and 'aws_managed_policies' in sr_entry):
        print_if_verbose("not eligible for policies; service_type: {} is not valid for policies or no 'aws_managed_policies' key in service registry for this role".format(service_type))
        return
    for policy_name in sr_entry['aws_managed_policies']:
        print_if_verbose('loading policy: {} for role: {}'.format(policy_name, role_name))
        if CONTEXT.commit:
            try:
                CLIENTS['iam'].attach_role_policy(RoleName=role_name, PolicyArn='arn:aws:iam::aws:policy/' + policy_name)
            except:
                fail('Exception putting policy: {} onto role: {}'.format(policy_name, role_name), sys.exc_info())

def conditionally_inline_policies(role_name, sr_entry):
    """If 'policies' key lists the filename prefixes of policies to bind to the role,
    load them from the expected path and inline them onto the role
    Args:
      role_name: name of the role to attach the policies to
      sr_entry: service registry entry"""
    service_type = sr_entry['type']
    if not (service_type in SERVICE_TYPE_ROLE and 'policies' in sr_entry):
        print_if_verbose("not eligible for policies; service_type: {} is not valid for policies or no 'policies' key in service registry for this role".format(service_type))
        return
    for policy_name in sr_entry['policies']:
        print_if_verbose('loading policy: {} for role: {}'.format(policy_name, role_name))
        try:
            policy_document = resolve_policy_document(policy_name)
        except:
            fail('Exception loading policy: {} for role: {}'.format(policy_name, role_name), sys.exc_info())
        if CONTEXT.commit:
            try:
                CLIENTS['iam'].put_role_policy(RoleName=role_name, PolicyName=policy_name, PolicyDocument=policy_document)
            except:
                fail('Exception putting policy: {} onto role: {}'.format(policy_name, role_name), sys.exc_info())

