def _pairs(keys, *, start=1, sep=' AND '):
    """>>> _pairs(['foo', 'bar', 'baz'], sep=', ')
    'foo=$1, bar=$2, baz=$3'
    >>> _pairs(['foo', 'bar', 'baz'], start=2)
    'foo=$2 AND bar=$3 AND baz=$4'"""
    return sep.join(('{}=${}'.format(k, i) for i, k in enumerate(keys, start)))

def _split_dict(dic):
    """Split dict into sorted keys and values

    >>> _split_dict({'b': 2, 'a': 1})
    (['a', 'b'], [1, 2])"""
    keys = sorted(dic.keys())
    return (keys, [dic[k] for k in keys])

def parse(data, datafile):
    """Read the Adventure data file and return a ``Data`` object."""
    data._last_travel = [0, [0]]
    while True:
        section_number = int(datafile.readline())
        if not section_number:
            break
        store = globals().get('section%d' % section_number)
        while True:
            fields = [int(field) if field.lstrip('-').isdigit() else field for field in datafile.readline().strip().split('\t')]
            if fields[0] == -1:
                break
            store(data, *fields)
    del data._last_travel
    del data._object
    data.object_list = sorted(set(data.objects.values()), key=attrgetter('n'))
    for obj in data.object_list:
        name = obj.names[0]
        if hasattr(data, name):
            name = name + '2'
        setattr(data, name, obj)
    return data

def _set_session():
    """Sets global __SESSION and __USER_ID if they haven't been set"""
    global __SESSION
    global __USER_ID
    if __SESSION is None:
        try:
            __SESSION = AuthorizedSession(google.auth.default(['https://www.googleapis.com/auth/userinfo.profile', 'https://www.googleapis.com/auth/userinfo.email'])[0])
            health()
            __USER_ID = id_token.verify_oauth2_token(__SESSION.credentials.id_token, Request(session=__SESSION))['email']
        except (DefaultCredentialsError, RefreshError) as gae:
            if os.getenv('SERVER_SOFTWARE', '').startswith('Google App Engine/'):
                raise
            logging.warning('Unable to determine/refresh application credentials')
            try:
                subprocess.check_call(['gcloud', 'auth', 'application-default', 'login', '--no-launch-browser'])
                __SESSION = AuthorizedSession(google.auth.default(['https://www.googleapis.com/auth/userinfo.profile', 'https://www.googleapis.com/auth/userinfo.email'])[0])
            except subprocess.CalledProcessError as cpe:
                if cpe.returncode < 0:
                    logging.exception('%s was terminated by signal %d', cpe.cmd, -cpe.returncode)
                else:
                    logging.exception('%s returned %d', cpe.cmd, cpe.returncode)
                raise gae

