def clone_workspace(from_namespace, from_workspace, to_namespace, to_workspace, authorizationDomain=''):
    """Clone a FireCloud workspace.

    A clone is a shallow copy of a FireCloud workspace, enabling
    easy sharing of data, such as TCGA data, without duplication.

    Args:
        from_namespace (str):  project (namespace) to which source workspace belongs
        from_workspace (str): Source workspace's name
        to_namespace (str):  project to which target workspace belongs
        to_workspace (str): Target workspace's name
        authorizationDomain: (str) required authorization domains

    Swagger:
        https://api.firecloud.org/#!/Workspaces/cloneWorkspace"""
    if authorizationDomain:
        if isinstance(authorizationDomain, string_types):
            authDomain = [{'membersGroupName': authorizationDomain}]
        else:
            authDomain = [{'membersGroupName': authDomain} for authDomain in authorizationDomain]
    else:
        authDomain = []
    body = {'namespace': to_namespace, 'name': to_workspace, 'attributes': dict(), 'authorizationDomain': authDomain}
    uri = 'workspaces/{0}/{1}/clone'.format(from_namespace, from_workspace)
    return __post(uri, json=body)

def __ensure_gcloud():
    """The *NIX installer is not guaranteed to add the google cloud sdk to the
    user's PATH (the Windows installer does). This ensures that if the default
    directory for the executables exists, it is added to the PATH for the
    duration of this package's use."""
    if which('gcloud') is None:
        gcloud_path = os.path.join(os.path.expanduser('~'), 'google-cloud-sdk', 'bin')
        env_path = os.getenv('PATH')
        if os.path.isdir(gcloud_path):
            if env_path is not None:
                os.environ['PATH'] = gcloud_path + os.pathsep + env_path
            else:
                os.environ['PATH'] = gcloud_path

def supervise(project, workspace, namespace, workflow, sample_sets, recovery_file):
    """Supervise submission of jobs from a Firehose-style workflow of workflows"""
    logging.info('Initializing FireCloud Supervisor...')
    logging.info('Saving recovery checkpoints to ' + recovery_file)
    args = {'project': project, 'workspace': workspace, 'namespace': namespace, 'workflow': workflow, 'sample_sets': sample_sets}
    monitor_data, dependencies = init_supervisor_data(workflow, sample_sets)
    recovery_data = {'args': args, 'monitor_data': monitor_data, 'dependencies': dependencies}
    supervise_until_complete(monitor_data, dependencies, args, recovery_file)

def init_supervisor_data(dotfile, sample_sets):
    """Parse a workflow description written in DOT (like Firehose)"""
    with open(dotfile) as wf:
        graph_data = wf.read()
    graph = pydot.graph_from_dot_data(graph_data)[0]
    nodes = [n.get_name().strip('"') for n in graph.get_nodes()]
    monitor_data = dict()
    dependencies = {n: [] for n in nodes}
    for n in nodes:
        monitor_data[n] = dict()
        for sset in sample_sets:
            monitor_data[n][sset] = {'state': 'Not Started', 'evaluated': False, 'succeeded': False}
    edges = graph.get_edges()
    for e in edges:
        source = e.get_source().strip('"')
        dest = e.get_destination().strip('"')
        dep = e.get_attributes()
        dep['upstream_task'] = source
        dependencies[dest].append(dep)
    return (monitor_data, dependencies)

def space_list(args):
    """List accessible workspaces, in TSV form: <namespace><TAB>workspace"""
    r = fapi.list_workspaces()
    fapi._check_response_code(r, 200)
    spaces = []
    project = args.project
    if project:
        project = re.compile('^' + project)
    for space in r.json():
        ns = space['workspace']['namespace']
        if project and (not project.match(ns)):
            continue
        ws = space['workspace']['name']
        spaces.append(ns + '\t' + ws)
    return sorted(spaces, key=lambda s: s.lower())

