def attr_copy(args):
    """Copy workspace attributes between workspaces."""
    if not args.to_workspace:
        args.to_workspace = args.workspace
    if not args.to_project:
        args.to_project = args.project
    if args.project == args.to_project and args.workspace == args.to_workspace:
        eprint('destination project and namespace must differ from source workspace')
        return 1
    r = fapi.get_workspace(args.project, args.workspace)
    fapi._check_response_code(r, 200)
    workspace_attrs = r.json()['workspace']['attributes']
    if args.attributes:
        workspace_attrs = {k: v for k, v in iteritems(workspace_attrs) if k in args.attributes}
    if len(workspace_attrs) == 0:
        print('No workspace attributes defined in {0}/{1}'.format(args.project, args.workspace))
        return 1
