def _format_mongodb_uri(parsed_uri):
    """Painstakingly reconstruct a MongoDB URI parsed using pymongo.uri_parser.parse_uri.

    :param parsed_uri: Result of pymongo.uri_parser.parse_uri
    :type parsed_uri: dict

    :return: New URI
    :rtype: str | unicode"""
    user_pass = ''
    if parsed_uri.get('username') and parsed_uri.get('password'):
        user_pass = '{username!s}:{password!s}@'.format(**parsed_uri)
    _nodes = []
    for host, port in parsed_uri.get('nodelist'):
        if ':' in host and (not host.endswith(']')):
            host = '[{!s}]'.format(host)
        if port == 27017:
            _nodes.append(host)
        else:
            _nodes.append('{!s}:{!s}'.format(host, port))
    nodelist = ','.join(_nodes)
    options = ''
    if parsed_uri.get('options'):
        _opt_list = []
        for key, value in parsed_uri.get('options').items():
            if isinstance(value, bool):
                value = str(value).lower()
            _opt_list.append('{!s}={!s}'.format(key, value))
        options = '?' + '&'.join(_opt_list)
    db_name = parsed_uri.get('database') or ''
    res = 'mongodb://{user_pass!s}{nodelist!s}/{db_name!s}{options!s}'.format(user_pass=user_pass, nodelist=nodelist, db_name=db_name, options=options)
    return res

def authorization_request_verify(authentication_request):
    """Verifies that all required parameters and correct values are included in the authentication request.
    :param authentication_request: the authentication request to verify
    :raise InvalidAuthenticationRequest: if the authentication is incorrect"""
    try:
        authentication_request.verify()
    except MessageException as e:
        raise InvalidAuthenticationRequest(str(e), authentication_request, oauth_error='invalid_request') from e

def registration_request_verify(registration_request):
    """Verifies that all required parameters and correct values are included in the client registration request.
    :param registration_request: the authentication request to verify
    :raise InvalidClientRegistrationRequest: if the registration is incorrect"""
    try:
        registration_request.verify()
    except MessageException as e:
        raise InvalidClientRegistrationRequest(str(e), registration_request, oauth_error='invalid_request') from e

def client_preferences_match_provider_capabilities(provider, registration_request):
    """Verifies that all requested preferences in the client metadata can be fulfilled by this provider.
    :param registration_request: the authentication request to verify
    :raise InvalidClientRegistrationRequest: if the registration is incorrect"""
    def match(client_preference, provider_capability):
        if isinstance(client_preference, list):
            return len(find_common_values(client_preference, provider_capability)) > 0
        return client_preference in provider_capability
    for client_preference in registration_request.keys():
        if client_preference not in PREFERENCE2PROVIDER:
            continue
        provider_capability = PREFERENCE2PROVIDER[client_preference]
        if not match(registration_request[client_preference], provider.configuration_information[provider_capability]):
            raise InvalidClientRegistrationRequest('Could not match client preference {}={} with provider capability {}={}'.format(client_preference, registration_request[client_preference], provider_capability, provider.configuration_information[provider_capability]), registration_request, oauth_error='invalid_request')

def bottoms(panels):
    """Finds bottom lines of all panels
    :param panels:
    :return: sorted by row list of tuples representing lines (col, row , col + len, row)"""
    bottom_lines = [(p['col'], p['row'] + p['size_y'], p['col'] + p['size_x'], p['row'] + p['size_y']) for p in panels]
    return sorted(bottom_lines, key=lambda l: l[1], reverse=True)

def find_shape(bottom_lines, max_len):
    """Finds a shape of lowest horizontal lines with step=1
    :param bottom_lines:
    :param max_len:
    :return: list of levels (row values), list indexes are columns"""
    shape = [1] * max_len
    for i in range(max_len):
        for line in bottom_lines:
            if line[0] <= i + 1 < line[2]:
                shape[i] = line[1]
                break
    return shape

def longest_lines(shape):
    """Creates lines from shape
    :param shape:
    :return: list of dictionaries with col,row,len fields"""
    lines = []
    for level in set(shape):
        count = 0
        for i in range(len(shape)):
            if shape[i] <= level:
                count += 1
            elif count:
                lines.append({'row': level, 'col': i - count + 1, 'len': count})
                count = 0
        if count:
            lines.append({'row': level, 'col': i - count + 2, 'len': count})
    return sorted(lines, key=lambda l: l['row'])

def namespace_url(context, view_name, *args, **kwargs):
    """Returns an absolute URL matching named view with its parameters and the
    provided application instance namespace.

    If no namespace is passed as a kwarg (or it is "" or None), this templatetag
    will look into the request object for the app_config's namespace. If there
    is still no namespace found, this tag will act like the normal {% url ... %}
    template tag.

    Normally, this tag will return whatever is returned by the ultimate call to
    reverse, which also means it will raise NoReverseMatch if reverse() cannot
    find a match. This behaviour can be override by suppling a 'default' kwarg
    with the value of what should be returned when no match is found."""
    namespace = kwargs.pop('namespace', None)
    if not namespace:
        namespace, __ = get_app_instance(context['request'])
    if namespace:
        namespace += ':'
    reverse = partial(urls.reverse, '{0:s}{1:s}'.format(namespace, view_name))
    if 'default' not in kwargs:
        if kwargs:
            return reverse(kwargs=kwargs)
        elif args:
            return reverse(args=args)
        else:
            return reverse()
    default = kwargs.pop('default', None)
    try:
        if kwargs:
            return reverse(kwargs=kwargs)
        elif args:
            return reverse(args=args)
        else:
            return reverse()
    except urls.NoReverseMatch:
        return default

def get_app_instance(request):
    """Returns a tuple containing the current namespace and the AppHookConfig instance

    :param request: request object
    :return: namespace, config"""
    app = None
    if getattr(request, 'current_page', None) and request.current_page.application_urls:
        app = apphook_pool.get_apphook(request.current_page.application_urls)
    if app and app.app_config:
        try:
            config = None
            with override(get_language_from_request(request, check_path=True)):
                namespace = resolve(request.path_info).namespace
                config = app.get_config(namespace)
            return (namespace, config)
        except Resolver404:
            pass
    return ('', None)

