def set_bit(bitmask, bit, is_on):
    """Set the value of a bit in a bitmask on or off.

    Uses the low bit is 1 and the high bit is 8."""
    bitshift = bit - 1
    if is_on:
        return bitmask | 1 << bitshift
    return bitmask & (255 & ~(1 << bitshift))

def create(rawmessage):
    """Return an INSTEON message class based on a raw byte stream."""
    rawmessage = _trim_buffer_garbage(rawmessage)
    if len(rawmessage) < 2:
        return (None, rawmessage)
    code = rawmessage[1]
    msgclass = _get_msg_class(code)
    msg = None
    remaining_data = rawmessage
    if msgclass is None:
        _LOGGER.debug('Did not find message class 0x%02x', rawmessage[1])
        rawmessage = rawmessage[1:]
        rawmessage = _trim_buffer_garbage(rawmessage, False)
        if rawmessage:
            _LOGGER.debug('Create: %s', create)
            _LOGGER.debug('rawmessage: %s', binascii.hexlify(rawmessage))
            msg, remaining_data = create(rawmessage)
        else:
            remaining_data = rawmessage
    elif iscomplete(rawmessage):
        msg = msgclass.from_raw_message(rawmessage)
        if msg:
            remaining_data = rawmessage[len(msg.bytes):]
    return (msg, remaining_data)

def iscomplete(rawmessage):
    """Test if the raw message is a complete message."""
    if len(rawmessage) < 2:
        return False
    if rawmessage[0] != 2:
        raise ValueError('message does not start with 0x02')
    messageBuffer = bytearray()
    filler = bytearray(30)
    messageBuffer.extend(rawmessage)
    messageBuffer.extend(filler)
    msg = _get_msg_class(rawmessage[1])
    if hasattr(msg, 'receivedSize') and msg.receivedSize:
        expectedSize = msg.receivedSize
    else:
        _LOGGER.error('Unable to find a receivedSize for code 0x%x', rawmessage[1])
        return ValueError
    is_expected_size = False
    if len(rawmessage) >= expectedSize:
        is_expected_size = True
    return is_expected_size

def _trim_buffer_garbage(rawmessage, debug=True):
    """Remove leading bytes from a byte stream.

    A proper message byte stream begins with 0x02."""
    while rawmessage and rawmessage[0] != MESSAGE_START_CODE_0X02:
        if debug:
            _LOGGER.debug('Buffer content: %s', binascii.hexlify(rawmessage))
            _LOGGER.debug('Trimming leading buffer garbage')
        rawmessage = rawmessage[1:]
    return rawmessage

def interactive():
    """Create an interactive command line tool.

    Wrapper for an interactive session for manual commands to be entered."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--device', default='/dev/ttyUSB0', help='Path to PLM device')
    parser.add_argument('-v', '--verbose', action='count', help='Set logging level to verbose')
    parser.add_argument('-l', '--logfile', default='', help='Log file name')
    parser.add_argument('--workdir', default='', help='Working directory for reading and saving device information.')
    args = parser.parse_args()
    loop = asyncio.get_event_loop()
    cmd = Commander(loop, args)
    cmd.start()
    try:
        loop.run_forever()
    except KeyboardInterrupt:
        if cmd.tools.plm:
            if cmd.tools.plm.transport:
                cmd.tools.plm.transport.close()
        loop.stop()
        pending = asyncio.Task.all_tasks(loop=loop)
        for task in pending:
            task.cancel()
            try:
                loop.run_until_complete(task)
            except asyncio.CancelledError:
                pass
            except KeyboardInterrupt:
                pass
        loop.close()

def get(company='', company_uri=''):
    """Performs a HTTP GET for a glassdoor page and returns json"""
    if not company and (not company_uri):
        raise Exception("glassdoor.gd.get(company='', company_uri=''):  company or company_uri required")
    payload = {}
    if not company_uri:
        payload.update({'clickSource': 'searchBtn', 'sc.keyword': company})
        uri = '%s/%s' % (GLASSDOOR_API, REVIEWS_URL)
    else:
        uri = '%s%s' % (GLASSDOOR_API, company_uri)
    r = requests.get(uri, params=payload)
    soup = BeautifulSoup(r.content)
    results = parse(soup)
    return results

def parse_suggestions(soup):
    """Suggests similar/related companies to query"""
    selector_comps = {'class': 'companyData'}
    companies = soup.findAll('div', selector_comps)
    def is_exact_match(c):
        """Determines if this company suggestion has an [exact match]
        html label or whether its name matches the company name the
        user searched for"""
        selector_exact = {'class': 'chickletExactMatch chicklet'}
        searched_name = soup.findAll('input', {'name': 'sc.keyword'})[0]['value']
        actual_name = c.findAll('h3')[0].text
        names_match = searched_name.lower() == actual_name.lower()
        exact_tag = bool(c.findAll('i', selector_exact))
        return exact_tag or names_match
    def parse_suggestion(c):
        return {'name': c.findAll('h3')[0].text, 'uri': c.findAll('a')[1]['href'], 'exact': is_exact_match(c)}
    suggestions = []
    for c in companies:
        try:
            suggestions.append(parse_suggestion(c))
        except IndexError as e:
            pass
    return suggestions

def parse(soup):
    """Parses the results for a company search and return the results
    if is_direct_match. If no company is found, a list of suggestions
    are returned as dict. If one such recommendation is found to be an
    exact match, re-perform request for this exact match"""
    if is_direct_match(soup):
        return {'satisfaction': parse_satisfaction(soup), 'ceo': parse_ceo(soup), 'meta': parse_meta(soup), 'salary': parse_salary(soup)}
    suggestions = parse_suggestions(soup)
    exact_match = next((s for s in suggestions if s['exact']), None)
    if exact_match:
        return get(company_uri=exact_match['uri'])
    return suggestions

def decode_jwt(encoded_token, secret, algorithm, identity_claim_key, user_claims_key):
    """Decodes an encoded JWT

    :param encoded_token: The encoded JWT string to decode
    :param secret: Secret key used to encode the JWT
    :param algorithm: Algorithm used to encode the JWT
    :param identity_claim_key: expected key that contains the identity
    :param user_claims_key: expected key that contains the user claims
    :return: Dictionary containing contents of the JWT"""
    data = jwt.decode(encoded_token, secret, algorithms=[algorithm])
    if 'jti' not in data:
        raise JWTDecodeError('Missing claim: jti')
    if identity_claim_key not in data:
        raise JWTDecodeError('Missing claim: {}'.format(identity_claim_key))
    if 'type' not in data or data['type'] not in ('refresh', 'access'):
        raise JWTDecodeError('Missing or invalid claim: type')
    if user_claims_key not in data:
        data[user_claims_key] = {}
    return data

def query_jwt_required(fn):
    """A decorator to protect a query resolver.

    If you decorate an resolver with this, it will ensure that the requester
    has a valid access token before allowing the resolver to be called. This
    does not check the freshness of the access token."""
    @wraps(fn)
    def wrapper(*args, **kwargs):
        print(args[0])
        token = kwargs.pop(current_app.config['JWT_TOKEN_ARGUMENT_NAME'])
        try:
            verify_jwt_in_argument(token)
        except Exception as e:
            return AuthInfoField(message=str(e))
        return fn(*args, **kwargs)
    return wrapper

