def retrieve_scores(gname, sdir, codon_pos, germ_aa, somatic_aa, default_mga=5.0, default_vest=0, no_file_flag=-1):
    """Retrieves scores from pickle files.

    Used by summary script."""
    mga_path = os.path.join(sdir, gname + '.mgaentropy.pickle')
    if os.path.exists(mga_path):
        if sys.version_info < (3,):
            with open(mga_path) as handle:
                mga_ent = pickle.load(handle)
        else:
            with open(mga_path, 'rb') as handle:
                mga_ent = pickle.load(handle, encoding='latin-1')
    else:
        mga_ent = None
    missense_pos = [p for i, p in enumerate(codon_pos) if germ_aa[i] != somatic_aa[i] and germ_aa[i] not in ['-', '*', 'Splice_Site'] and (somatic_aa[i] not in ['-', '*', 'Splice_Site'])]
    total_mga_ent = compute_mga_entropy_stat(mga_ent, missense_pos, sum, default_mga)
    vest_path = os.path.join(sdir, gname + '.vest.pickle')
    if os.path.exists(vest_path):
        if sys.version_info < (3,):
            with open(vest_path) as handle:
                vest_score = pickle.load(handle)
        else:
            with open(vest_path, 'rb') as handle:
                vest_score = pickle.load(handle, encoding='latin-1')
    else:
        vest_score = None
    total_vest = compute_vest_stat(vest_score, germ_aa, somatic_aa, codon_pos, stat_func=sum, default_val=default_vest)
    return (total_mga_ent, total_vest)

def cummin(x):
    """A python implementation of the cummin function in R"""
    for i in range(1, len(x)):
        if x[i - 1] < x[i]:
            x[i] = x[i - 1]
    return x

def log_error_decorator(f):
    """Writes exception to log file if occured in decorated function.

    This decorator wrapper is needed for multiprocess logging since otherwise
    the python multiprocessing module will obscure the actual line of the error."""
    @wraps(f)
    def wrapper(*args, **kwds):
        try:
            result = f(*args, **kwds)
            return result
        except KeyboardInterrupt:
            logger.info('Ctrl-C stopped a process.')
        except Exception as e:
            logger.exception(e)
            raise
    return wrapper

def team_required(func=None):
    """Decorator for views that require a team be supplied wither via a slug in the
    url pattern or already set on the request object from the TeamMiddleware"""
    def decorator(view_func):
        @functools.wraps(view_func, assigned=available_attrs(view_func))
        def _wrapped_view(request, *args, **kwargs):
            slug = kwargs.pop('slug', None)
            if not getattr(request, 'team', None):
                request.team = get_object_or_404(Team, slug=slug)
            return view_func(request, *args, **kwargs)
        return _wrapped_view
    if func:
        return decorator(func)
    return decorator

def manager_required(func=None):
    """Decorator for views that require not only a team but also that a user be
    logged in and be the manager or owner of that team."""
    def decorator(view_func):
        @team_required
        @login_required
        @functools.wraps(view_func, assigned=available_attrs(view_func))
        def _wrapped_view(request, *args, **kwargs):
            role = request.team.role_for(request.user)
            if role not in [Membership.ROLE_MANAGER, Membership.ROLE_OWNER]:
                raise Http404()
            return view_func(request, *args, **kwargs)
        return _wrapped_view
    if func:
        return decorator(func)
    return decorator

def split_by_commas(maybe_s: str) -> Tuple[str, ...]:
    """Split a string by commas, but allow escaped commas.
    - If maybe_s is falsey, returns an empty tuple
    - Ignore backslashed commas"""
    if not maybe_s:
        return ()
    parts: List[str] = []
    split_by_backslash = maybe_s.split('\\,')
    for split_by_backslash_part in split_by_backslash:
        splitby_comma = split_by_backslash_part.split(',')
        if parts:
            parts[-1] += ',' + splitby_comma[0]
        else:
            parts.append(splitby_comma[0])
        parts.extend(splitby_comma[1:])
    return tuple(parts)

def new_linsolver(name, prop):
    """Creates a linear solver.

    Parameters
    ----------
    name : string
    prop : string

    Returns
    -------
    solver : :class:`LinSolver <optalg.lin_solver.LinSolver>`"""
    if name == 'mumps':
        return LinSolverMUMPS(prop)
    elif name == 'superlu':
        return LinSolverSUPERLU(prop)
    elif name == 'umfpack':
        return LinSolverUMFPACK(prop)
    elif name == 'default':
        try:
            return new_linsolver('mumps', prop)
        except ImportError:
            return new_linsolver('superlu', prop)
    else:
        raise ValueError('invalid linear solver name')

def cast_problem(problem):
