def hex_to_bytes(s):
    """convert hex string to bytes"""
    if len(s) % 2:
        s = b'0' + s
    ia = [int(s[i:i + 2], 16) for i in range(0, len(s), 2)]
    return bs(ia) if PYTHON_MAJOR_VER == 3 else b''.join([chr(c) for c in ia])

def client_seed(a=random.randrange(0, 1 << SRP_KEY_SIZE)):
    """A: Client public key
    a: Client private key"""
    if DEBUG:
        a = DEBUG_PRIVATE_KEY
    N, g, k = get_prime()
    A = pow(g, a, N)
    if DEBUG_PRINT:
        print('a=', binascii.b2a_hex(long2bytes(a)), end='\n')
