    return (A, a)

def decimal128_to_decimal(b):
    """decimal128 bytes to Decimal"""
    v = decimal128_to_sign_digits_exponent(b)
    if isinstance(v, Decimal):
        return v
    sign, digits, exponent = v
    return Decimal((sign, Decimal(digits).as_tuple()[1], exponent))

