def check64bit(current_system='python'):
    """checks if you are on a 64 bit platform"""
    if current_system == 'python':
        return sys.maxsize > 2147483647
    elif current_system == 'os':
        import platform
        pm = platform.machine()
        if pm != '..' and pm.endswith('64'):
            return True
        else:
            if 'PROCESSOR_ARCHITEW6432' in os.environ:
                return True
            try:
                return os.environ['PROCESSOR_ARCHITECTURE'].endswith('64')
            except IndexError:
                pass
            try:
                return '64' in platform.architecture()[0]
            except Exception:
                return False

def add_md(text, s, level=0):
    """Adds text to the readme at the given level"""
    if level > 0:
        if text != '':
            text += '\n'
        text += '#' * level
        text += ' '
    text += s + '\n'
    if level > 0:
        text += '\n'
    return text

