def _convert_json_response_to_entities(response, property_resolver, require_encryption, key_encryption_key, key_resolver):
    """Converts the response to tables class.
    """
    if response is None or response.body is None:
        return None
    entities = _list()
    entities.next_marker = _get_continuation_from_response_headers(response)
    root = loads(response.body.decode('utf-8'))
    if 'value' in root:
        for entity in root['value']:
            entity = _decrypt_and_deserialize_entity(entity, property_resolver, require_encryption, key_encryption_key, key_resolver)
            entities.append(entity)
    else:
        entities.append(_convert_json_to_entity(entity, property_resolver))
    return entities

def _exec_ipmitool(driver_info, command):
    """Execute the ipmitool command.

    This uses the lanplus interface to communicate with the BMC device driver.

    :param driver_info: the ipmitool parameters for accessing a node.
    :param command: the ipmitool command to be executed."""
    ipmi_cmd = 'ipmitool -H %(address)s -I lanplus -U %(user)s -P %(passwd)s %(cmd)s' % {'address': driver_info['address'], 'user': driver_info['username'], 'passwd': driver_info['password'], 'cmd': command}
    out = None
    try:
        out = subprocess.check_output(ipmi_cmd, shell=True)
    except Exception:
        pass
    return out

def get_nic_capacity(driver_info, ilo_fw):
    """Gets the FRU data to see if it is NIC data

    Gets the FRU data in loop from 0-255 FRU Ids
    and check if the returned data is NIC data. Couldn't
    find any easy way to detect if it is NIC data. We should't be
    hardcoding the FRU Id.

    :param driver_info: Contains the access credentials to access
                        the BMC.
    :param ilo_fw: a tuple containing major and minor versions of firmware
    :returns: the max capacity supported by the NIC adapter."""
    i = 0
    value = None
    ilo_fw_rev = get_ilo_version(ilo_fw) or DEFAULT_FW_REV
    if ilo_fw_rev < MIN_SUGGESTED_FW_REV:
        for i in range(255):
            if i < 110 or i > 238:
                cmd = 'fru print %s' % hex(i)
                out = _exec_ipmitool(driver_info, cmd)
                if out and 'port' in out and ('Adapter' in out):
                    value = _parse_ipmi_nic_capacity(out)
                    if value is not None:
                        break
            else:
                continue
    else:
        cmd = 'fru print'
        out = _exec_ipmitool(driver_info, cmd)
        if out:
            for line in out.split('\n'):
                if line and 'port' in line and ('Adapter' in line):
                    value = _parse_ipmi_nic_capacity(line)
                    if value is not None:
                        break
    return value

def _parse_ipmi_nic_capacity(nic_out):
    """Parse the FRU output for NIC capacity

    Parses the FRU output. Seraches for the key "Product Name"
    in FRU output and greps for maximum speed supported by the
    NIC adapter.

    :param nic_out: the FRU output for NIC adapter.
    :returns: the max capacity supported by the NIC adapter."""
    if 'Device not present' in nic_out or 'Unknown FRU header' in nic_out or (not nic_out):
        return None
    capacity = None
    product_name = None
    data = nic_out.split('\n')
    for item in data:
        fields = item.split(':')
        if len(fields) > 1:
            first_field = fields[0].strip()
            if first_field == 'Product Name':
                product_name = ':'.join(fields[1:])
                break
    if product_name:
        product_name_array = product_name.split(' ')
        for item in product_name_array:
            if 'Gb' in item:
                capacity_int = item.strip('Gb')
                if capacity_int.isdigit():
                    capacity = item
    return capacity

def get_supported_boot_mode(supported_boot_mode):
    """Return bios and uefi support.

    :param supported_boot_mode: Supported boot modes
    :return: A tuple of 'true'/'false' based on bios and uefi
        support respectively."""
    boot_mode_bios = 'false'
    boot_mode_uefi = 'false'
    if supported_boot_mode == sys_cons.SUPPORTED_LEGACY_BIOS_ONLY:
        boot_mode_bios = 'true'
    elif supported_boot_mode == sys_cons.SUPPORTED_UEFI_ONLY:
        boot_mode_uefi = 'true'
    elif supported_boot_mode == sys_cons.SUPPORTED_LEGACY_BIOS_AND_UEFI:
        boot_mode_bios = 'true'
        boot_mode_uefi = 'true'
    return SupportedBootModes(boot_mode_bios=boot_mode_bios, boot_mode_uefi=boot_mode_uefi)

def _convert_json_response_to_entities(response, property_resolver):
    """Converts the response to tables class.
    """
    if response is None:
        return response
    entities = _list()
    entities.next_marker = _get_continuation_from_response_headers(response)
    root = loads(response.body.decode('utf-8'))
    if 'value' in root:
        for entity in root['value']:
            entities.append(_convert_json_to_entity(entity, property_resolver))
    else:
        entities.append(_convert_json_to_entity(entity, property_resolver))
    return entities

def _extract_etag(response):
    """Extracts the etag from the response headers."""
    if response and response.headers:
        for name, value in response.headers:
            if name.lower() == 'etag':
                return value
    return None

def _get_request_body_bytes_only(param_name, param_value):
