    if our policy allows it."""
    if param_value is None:
        return b''
    if isinstance(param_value, bytes):
        return param_value
    raise TypeError(_ERROR_VALUE_SHOULD_BE_BYTES.format(param_name))

def _get_attribute_value_of(resource, attribute_name, default=None):
    """Gets the value of attribute_name from the resource

    It catches the exception, if any, while retrieving the
    value of attribute_name from resource and returns default.

    :param resource: The resource object
    :attribute_name: Property of the resource
    :returns the property value if no error encountered
        else return 0."""
    try:
        return getattr(resource, attribute_name)
    except (sushy.exceptions.SushyError, exception.MissingAttributeError) as e:
        msg = 'The Redfish controller failed to get the attribute %(attribute)s from resource %(resource)s. Error %(error)s' % {'error': str(e), 'attribute': attribute_name, 'resource': resource.__class__.__name__}
        LOG.debug(msg)
        return default

def _get_log_file_data_as_encoded_content():
    """Gzip and base64 encode files and BytesIO buffers.

    This method gets the log files created by SUM based
    firmware update and tar zip the files.
    :returns: A gzipped and base64 encoded string as text."""
    with io.BytesIO() as fp:
        with tarfile.open(fileobj=fp, mode='w:gz') as tar:
            for f in OUTPUT_FILES:
                if os.path.isfile(f):
                    tar.add(f)
        fp.seek(0)
        return base64.encode_as_bytes(fp.getvalue())

def _get_hash_object(hash_algo_name):
    """Create a hash object based on given algorithm.

    :param hash_algo_name: name of the hashing algorithm.
    :raises: InvalidInputError, on unsupported or invalid input.
    :returns: a hash object based on the given named algorithm."""
    algorithms = hashlib.algorithms_guaranteed if six.PY3 else hashlib.algorithms
    if hash_algo_name not in algorithms:
        msg = "Unsupported/Invalid hash name '%s' provided." % hash_algo_name
        raise exception.InvalidInputError(msg)
    return getattr(hashlib, hash_algo_name)()

def verify_image_checksum(image_location, expected_checksum):
    """Verifies checksum (md5) of image file against the expected one.

    This method generates the checksum of the image file on the fly and
    verifies it against the expected checksum provided as argument.

    :param image_location: location of image file whose checksum is verified.
    :param expected_checksum: checksum to be checked against
    :raises: ImageRefValidationFailed, if invalid file path or
             verification fails."""
    try:
        with open(image_location, 'rb') as fd:
            actual_checksum = hash_file(fd)
    except IOError as e:
        raise exception.ImageRefValidationFailed(image_href=image_location, reason=e)
    if actual_checksum != expected_checksum:
        msg = 'Error verifying image checksum. Image %(image)s failed to verify against checksum %(checksum)s. Actual checksum is: %(actual_checksum)s' % {'image': image_location, 'checksum': expected_checksum, 'actual_checksum': actual_checksum}
        raise exception.ImageRefValidationFailed(image_href=image_location, reason=msg)

def validate_href(image_href):
    """Validate HTTP image reference.

    :param image_href: Image reference.
    :raises: exception.ImageRefValidationFailed if HEAD request failed or
        returned response code not equal to 200.
    :returns: Response to HEAD request."""
    try:
        response = requests.head(image_href)
        if response.status_code != http_client.OK:
            raise exception.ImageRefValidationFailed(image_href=image_href, reason='Got HTTP code %s instead of 200 in response to HEAD request.' % response.status_code)
    except requests.RequestException as e:
        raise exception.ImageRefValidationFailed(image_href=image_href, reason=e)
    return response

def apply_bios_properties_filter(settings, filter_to_be_applied):
