def erase_devices():
    """Erase all the drives on this server.

    This method performs sanitize erase on all the supported physical drives
    in this server. This erase cannot be performed on logical drives.

    :returns: a dictionary of controllers with drives and the erase status.
    :raises exception.HPSSAException, if none of the drives support
        sanitize erase."""
    server = objects.Server()
    for controller in server.controllers:
        drives = [x for x in controller.unassigned_physical_drives if x.get_physical_drive_dict().get('erase_status', '') == 'OK']
        if drives:
            controller.erase_devices(drives)
    while not has_erase_completed():
        time.sleep(300)
    server.refresh()
    status = {}
    for controller in server.controllers:
        drive_status = {x.id: x.erase_status for x in controller.unassigned_physical_drives}
        sanitize_supported = controller.properties.get('Sanitize Erase Supported', 'False')
        if sanitize_supported == 'False':
            msg = 'Drives overwritten with zeros because sanitize erase is not supported on the controller.'
        else:
            msg = 'Sanitize Erase performed on the disks attached to the controller.'
        drive_status.update({'Summary': msg})
        status[controller.id] = drive_status
    return status

def _parse_properties(response, result_class):
    """Extracts out resource properties and metadata information.
    Ignores the standard http headers."""
    if response is None or response.headers is None:
        return None
    props = result_class()
    for key, value in response.headers:
        info = GET_PROPERTIES_ATTRIBUTE_MAP.get(key)
        if info:
            if info[0] is None:
                setattr(props, info[1], info[2](value))
            else:
                attr = getattr(props, info[0])
                setattr(attr, info[1], info[2](value))
    return props

def _parse_response_for_dict(response):
    """Extracts name-values from response header. Filter out the standard
    http headers."""
    if response is None:
        return None
    http_headers = ['server', 'date', 'location', 'host', 'via', 'proxy-connection', 'connection']
    return_dict = _HeaderDict()
    if response.headers:
        for name, value in response.headers:
            if not name.lower() in http_headers:
                return_dict[name] = value
    return return_dict

