def _get_key_value(string):
    """Return the (key, value) as a tuple from a string."""
    key = ''
    value = ''
    try:
        key, value = string.split(': ')
    except ValueError:
        string = string.lstrip(' ')
        if string.startswith('physicaldrive'):
            fields = string.split(' ')
            key = fields[0] + ' ' + fields[1]
            value = fields[1]
        else:
            return (string.strip(' '), None)
    return (key.strip(' '), value.strip(' '))

def _get_dict(lines, start_index, indentation, deep):
    """Recursive function for parsing hpssacli/ssacli output."""
    info = {}
    current_item = None
    i = start_index
    while i < len(lines):
        current_line = lines[i]
        current_line_indentation = _get_indentation(current_line)
        if current_line_indentation < indentation:
            return (info, i - 1)
        if current_line_indentation == indentation:
            current_item = current_line.lstrip(' ')
            info[current_item] = {}
            i = i + 1
            continue
        if i < len(lines) - 1:
            next_line_indentation = _get_indentation(lines[i + 1])
        else:
            next_line_indentation = current_line_indentation
        if next_line_indentation > current_line_indentation:
            ret_dict, i = _get_dict(lines, i, current_line_indentation, deep + 1)
            for key in ret_dict.keys():
                if key in info[current_item]:
                    info[current_item][key].update(ret_dict[key])
                else:
                    info[current_item][key] = ret_dict[key]
        else:
            key, value = _get_key_value(current_line)
            if key:
                info[current_item][key] = value
        if next_line_indentation < current_line_indentation and deep > 0:
            return (info, i)
        i = i + 1
    return (info, i)

def get_content_type(name, content):
    """Checks if the content_type is already set.
    Otherwise uses the mimetypes library to guess."""
    if hasattr(content, 'content_type'):
        content_type = content.content_type
    else:
        mime_type, encoding = mimetypes.guess_type(name)
        content_type = mime_type
    return content_type

def sync_headers(cloud_obj, headers=None, header_patterns=HEADER_PATTERNS):
    """Overwrites the given cloud_obj's headers with the ones given as ``headers`
    and adds additional headers as defined in the HEADERS setting depending on
    the cloud_obj's file name."""
    if headers is None:
        headers = {}
    content_type = getattr(cloud_obj, 'content_type', None)
    if content_type == 'application/directory':
        return
    matched_headers = {}
    for pattern, pattern_headers in header_patterns:
        if pattern.match(cloud_obj.name):
            matched_headers.update(pattern_headers.copy())
    matched_headers.update(cloud_obj.headers)
    matched_headers.update(headers)
    if matched_headers != cloud_obj.headers:
        cloud_obj.headers = matched_headers
        cloud_obj.sync_metadata()

