def _unpack_list(example):
    """Input data format standardization"""
    try:
        x = example[0]
        y = example[1]
        meta = None
        return (x, y, meta)
    except IndexError:
        raise IndicoError('Invalid input data.  Please ensure input data is formatted as a list of `[data, target]` pairs.')

def _unpack_dict(example):
    """Input data format standardization"""
    try:
        x = example['data']
        y = example['target']
        meta = example.get('metadata', {})
        return (x, y, meta)
    except KeyError:
        raise IndicoError('Invalid input data.  Please ensure input data is formatted as a list of dicts with `data` and `target` keys. A `metadata` key may optionally be included.')

def _unpack_data(data):
    """Break Xs, Ys, and metadata out into separate lists for data preprocessing.
    Run basic data validation."""
    xs = [None] * len(data)
    ys = [None] * len(data)
    metadata = [None] * len(data)
    for idx, example in enumerate(data):
        if isinstance(example, (list, tuple)):
            xs[idx], ys[idx], metadata[idx] = _unpack_list(example)
        if isinstance(example, dict):
            xs[idx], ys[idx], metadata[idx] = _unpack_dict(example)
    return (xs, ys, metadata)

def _pack_data(X, Y, metadata):
    """After modifying / preprocessing inputs,
    reformat the data in preparation for JSON serialization"""
    if not any(metadata):
        return list(zip(X, Y))
    else:
        return [{'data': x, 'target': y, 'metadata': meta} for x, y, meta in zip(X, Y, metadata)]

def visualize_explanation(explanation, label=None):
    """Given the output of the explain() endpoint, produces a terminal visual that plots response strength over a sequence"""
    if not sys.version_info[:2] >= (3, 5):
        raise IndicoError('Python >= 3.5+ is required for explanation visualization')
    try:
        from colr import Colr as C
    except ImportError:
        raise IndicoError('Package colr >= 0.8.1 is required for explanation visualization.')
    cursor = 0
    text = explanation['text']
    for token in explanation.get('token_predictions'):
        try:
            class_confidence = token.get('prediction')[label]
        except KeyError:
            raise IndicoError('Invalid label: {}'.format(label))
        if class_confidence > 0.5:
            fg_color = (255, 255, 255)
        else:
            fg_color = (0, 0, 0)
        rg_value = 255 - int(class_confidence * 255)
        token_end = token.get('token').get('end')
        token_text = text[cursor:token_end]
        cursor = token_end
        sys.stdout.write(str(C().b_rgb(rg_value, rg_value, 255).rgb(fg_color[0], fg_color[1], fg_color[2], token_text)))
    sys.stdout.write('\n')
    sys.stdout.flush()

