def build_values(name, values_mods):
    """Update name/values.yaml with modifications"""
    values_file = os.path.join(name, 'values.yaml')
    with open(values_file) as f:
        values = yaml.load(f)
    for key, value in values_mods.items():
        parts = key.split('.')
        mod_obj = values
        for p in parts:
            mod_obj = mod_obj[p]
        print(f'Updating {values_file}: {key}: {value}')
        if isinstance(mod_obj, MutableMapping):
            keys = IMAGE_REPOSITORY_KEYS & mod_obj.keys()
            if keys:
                for key in keys:
                    mod_obj[key] = value['repository']
            else:
                possible_keys = ' or '.join(IMAGE_REPOSITORY_KEYS)
                raise KeyError(f'Could not find {possible_keys} in {values_file}:{key}')
            mod_obj['tag'] = value['tag']
        else:
            raise TypeError(f'The key {key} in {values_file} must be a mapping.')
    with open(values_file, 'w') as f:
        yaml.dump(values, f)

def add_values_to_bundle_safe(connection, bundle, values):
    """Adds values to specified bundle. Checks, whether each value already contains in bundle. If yes, it is not added.

    Args:
        connection: An opened Connection instance.
        bundle: Bundle instance to add values in.
        values: Values, that should be added in bundle.

    Raises:
        YouTrackException: if something is wrong with queries."""
    for value in values:
        try:
            connection.addValueToBundle(bundle, value)
        except YouTrackException as e:
            if e.response.status == 409:
                print('Value with name [ %s ] already exists in bundle [ %s ]' % (utf8encode(value.name), utf8encode(bundle.name)))
            else:
                raise e

def create_closure_model(cls):
    """Creates a <Model>Closure model in the same module as the model."""
    meta_vals = {'unique_together': (('parent', 'child'),)}
    if getattr(cls._meta, 'db_table', None):
        meta_vals['db_table'] = '%sclosure' % getattr(cls._meta, 'db_table')
    model = type('%sClosure' % cls.__name__, (models.Model,), {'parent': models.ForeignKey(cls.__name__, related_name=cls.closure_parentref()), 'child': models.ForeignKey(cls.__name__, related_name=cls.closure_childref()), 'depth': models.IntegerField(), '__module__': cls.__module__, '__unicode__': _closure_model_unicode, 'Meta': type('Meta', (object,), meta_vals)})
    setattr(cls, '_closure_model', model)
    return model

def vectorize(fn):
    """Allows a method to accept a list argument, but internally deal only
    with a single item of that list."""
    @functools.wraps(fn)
    def vectorized_function(values, *vargs, **kwargs):
        return [fn(value, *vargs, **kwargs) for value in values]
    return vectorized_function

def engineering(value, precision=3, prefix=False, prefixes=SI):
    """Convert a number to engineering notation."""
    display = decimal.Context(prec=precision)
    value = decimal.Decimal(value).normalize(context=display)
    string = value.to_eng_string()
    if prefix:
        prefixes = {e(exponent): prefix for exponent, prefix in prefixes.items()}
        return replace(string, prefixes)
    else:
        return string

def chunked(iterator, chunksize):
    """Yields items from 'iterator' in chunks of size 'chunksize'.

    >>> list(chunked([1, 2, 3, 4, 5], chunksize=2))
    [(1, 2), (3, 4), (5,)]"""
    chunk = []
    for idx, item in enumerate(iterator, 1):
        chunk.append(item)
        if idx % chunksize == 0:
            yield chunk
            chunk = []
    if chunk:
        yield chunk

def find_first_fit(unoccupied_columns, row, row_length):
    """Finds the first index that the row's items can fit."""
    for free_col in unoccupied_columns:
        first_item_x = row[0][0]
        offset = free_col - first_item_x
        if check_columns_fit(unoccupied_columns, row, offset, row_length):
            return offset
    raise ValueError('Row cannot bossily fit in %r: %r' % (list(unoccupied_columns.keys()), row))

def print_square(row_queue, t):
    """Prints a row queue as its conceptual square array."""
    occupied_rows = {y: row for _, y, row in row_queue}
    empty_row = ', '.join(('...' for _ in range(t)))
    for y in range(t):
        print('|', end=' ')
        if y not in occupied_rows:
            print(empty_row, end=' ')
        else:
            row = dict(occupied_rows[y])
            all_cols = ('%3d' % row[x] if x in row else '...' for x in range(t))
            print(', '.join(all_cols), end=' ')
        print('|')

def trim_nones_from_right(xs):
    """Returns the list without all the Nones at the right end.

    >>> trim_nones_from_right([1, 2, None, 4, None, 5, None, None])
    [1, 2, None, 4, None, 5]"""
    for i, item in enumerate(reversed(xs)):
        if item is not None:
            break
    return xs[:-i]

def _nested_transactional(fn):
    """In a transactional method create a nested transaction."""
    @wraps(fn)
    def wrapped(self, *args, **kwargs):
        try:
            rv = fn(self, *args, **kwargs)
        except _TransactionalPolicyViolationError as e:
            getattr(self, _TX_HOLDER_ATTRIBUTE).rollback()
            rv = e.result
        return rv
    return wrapped

def exec_task(task_path, data):
    """Execute task.

    :param task_path: task path
    :type task_path: str|Callable
    :param data: task's data
    :type data: Any
    :return:"""
    if not data:
        data = {'data': None, 'path': task_path}
    elif not isinstance(data, (str, bytes)):
        data = {'data': json.dumps(data, cls=RequestJSONEncoder), 'path': task_path}
    else:
        if data is not None and data.startswith('file://'):
            with open(data[len('file://'):]) as f:
                data = f.read()
        data = {'data': data, 'path': task_path}
    job = Job(data)
    task, task_callable = create_task(task_path)
    with delegating_job_context(job, task, task_callable) as jc:
        return jc.task_callable(jc.task_data)

def log_output(f):
