def check_syntax(string):
    """Check syntax of a string of PostgreSQL-dialect SQL"""
    args = ['ecpg', '-o', '-', '-']
    with open(os.devnull, 'w') as devnull:
        try:
            proc = subprocess.Popen(args, shell=False, stdout=devnull, stdin=subprocess.PIPE, stderr=subprocess.PIPE, universal_newlines=True)
            _, err = proc.communicate(string)
        except OSError:
            msg = "Unable to execute 'ecpg', you likely need to install it.'"
            raise OSError(msg)
        if proc.returncode == 0:
            return (True, '')
        else:
            return (False, parse_error(err))

def back_slash_to_front_converter(string):
    """Replacing all \\ in the str to /
    :param string: single string to modify
    :type string: str"""
    try:
        if not string or not isinstance(string, str):
            return string
        return string.replace('\\', '/')
    except Exception:
        return string

def get_object_as_string(obj):
    """Converts any object to JSON-like readable format, ready to be printed for debugging purposes
    :param obj: Any object
    :return: string"""
    if isinstance(obj, str):
        return obj
    if isinstance(obj, list):
        return '\r\n\\;'.join([get_object_as_string(item) for item in obj])
    attrs = vars(obj)
    as_string = ', '.join(('%s: %s' % item for item in attrs.items()))
    return as_string

