def generate_unique_name(name_prefix, reservation_id=None):
    """Generate a unique name.
    Method generate a guid and adds the first 8 characteres of the new guid to 'name_prefix'.
    If reservation id is provided than the first 4 chars of the generated guid are taken and the last 4
    of the reservation id"""
    if reservation_id and isinstance(reservation_id, str) and (len(reservation_id) >= 4):
        unique_id = str(uuid.uuid4())[:4] + '-' + reservation_id[-4:]
    else:
        unique_id = str(uuid.uuid4())[:8]
    return name_prefix + '_' + unique_id

def endianSwapU16(bytes):
    """Swaps pairs of bytes (16-bit words) in the given bytearray."""
    for b in range(0, len(bytes), 2):
        bytes[b], bytes[b + 1] = (bytes[b + 1], bytes[b])
    return bytes

def toRepr(obj):
    """toRepr(obj) -> string

    Converts the Python object to a string representation of the kind
    often returned by a class __repr__() method."""
    args = []
    names = []
    if hasattr(obj, '__dict__'):
        names += getattr(obj, '__dict__').keys()
    if hasattr(obj, '__slots__'):
        names += getattr(obj, '__slots__')
    for name in names:
        value = getattr(obj, name)
        if value is not None:
            if type(value) is str:
                if len(value) > 32:
                    value = value[0:32] + '...'
                value = "'" + value + "'"
        args.append('%s=%s' % (name, str(value)))
    return '%s(%s)' % (obj.__class__.__name__, ', '.join(args))

def expandPath(pathname, prefix=None):
    """Return pathname as an absolute path, either expanded by the users
    home directory ("~") or with prefix prepended."""
    if prefix is None:
        prefix = ''
    expanded = pathname
    if pathname[0] == '~':
        expanded = os.path.expanduser(pathname)
    elif pathname[0] != '/':
        expanded = os.path.join(prefix, pathname)
    return os.path.abspath(expanded)

def listAllFiles(directory, suffix=None, abspath=False):
    """Returns the list of all files within the input directory and
    all subdirectories."""
    files = []
    directory = expandPath(directory)
    for dirpath, dirnames, filenames in os.walk(directory, followlinks=True):
        if suffix:
            filenames = [f for f in filenames if f.endswith(suffix)]
        for filename in filenames:
            filepath = os.path.join(dirpath, filename)
            if not abspath:
                filepath = os.path.relpath(filepath, start=directory)
            files.append(filepath)
    return files

def getUTCDatetimeDOY(days=0, hours=0, minutes=0, seconds=0):
    """getUTCDatetimeDOY -> datetime

    Returns the UTC current datetime with the input timedelta arguments (days, hours, minutes, seconds)
    added to current date. Returns ISO-8601 datetime format for day of year:

        YYYY-DDDTHH:mm:ssZ"""
    return (datetime.datetime.utcnow() + datetime.timedelta(days=days, hours=hours, minutes=minutes, seconds=seconds)).strftime(DOY_Format)

def handle_includes(defns):
    """Recursive handling of includes for any input list of defns.
    The assumption here is that when an include is handled by the
    pyyaml reader, it adds them as a list, which is stands apart from the rest
    of the expected YAML definitions."""
    newdefns = []
    for d in defns:
        if isinstance(d, list):
            newdefns.extend(handle_includes(d))
        else:
            newdefns.append(d)
    return newdefns

def cbrt(x):
    """Returns the cube root of x."""
    if x >= 0:
        return math.pow(x, 1.0 / 3.0)
    else:
        return -math.pow(abs(x), 1.0 / 3.0)

def hexdumpLine(bytes, length=None):
    """hexdumpLine(bytes[, length])

    Returns a single hexdump formatted line for bytes.  If length is
    greater than len(bytes), the line will be padded with ASCII space
    characters to indicate no byte data is present.

    Used by hexdump()."""
    line = ''
    if length is None:
        length = len(bytes)
    for n in xrange(0, length, 2):
        if n < len(bytes) - 1:
            line += '%02x%02x  ' % (bytes[n], bytes[n + 1])
        elif n < len(bytes):
            line += '%02x    ' % bytes[n]
        else:
            line += '      '
    line += '*'
    for n in xrange(length):
        if n < len(bytes):
            if bytes[n] in xrange(32, 127):
                line += '%c' % bytes[n]
            else:
                line += '.'
        else:
            line += ' '
    line += '*'
    return line

def extant_file(file):
