def parse_passage(obj: dict) -> BioCPassage:
    """Deserialize a dict obj to a BioCPassage object"""
    passage = BioCPassage()
    passage.offset = obj['offset']
    passage.infons = obj['infons']
    if 'text' in obj:
        passage.text = obj['text']
    for sentence in obj['sentences']:
        passage.add_sentence(parse_sentence(sentence))
    for annotation in obj['annotations']:
        passage.add_annotation(parse_annotation(annotation))
    for relation in obj['relations']:
        passage.add_relation(parse_relation(relation))
    return passage

def parse_doc(obj: dict) -> BioCDocument:
    """Deserialize a dict obj to a BioCDocument object"""
    doc = BioCDocument()
    doc.id = obj['id']
    doc.infons = obj['infons']
    for passage in obj['passages']:
        doc.add_passage(parse_passage(passage))
    for annotation in obj['annotations']:
        doc.add_annotation(parse_annotation(annotation))
    for relation in obj['relations']:
        doc.add_relation(parse_relation(relation))
    return doc

def _remove_unexpected_query_parameters(schema, req):
    """Remove unexpected properties from the req.GET."""
    additional_properties = schema.get('addtionalProperties', True)
    if additional_properties:
        pattern_regexes = []
        patterns = schema.get('patternProperties', None)
        if patterns:
            for regex in patterns:
                pattern_regexes.append(re.compile(regex))
        for param in set(req.GET.keys()):
            if param not in schema['properties'].keys():
                if not list((regex for regex in pattern_regexes if regex.match(param))):
                    del req.GET[param]

def query_schema(query_params_schema, min_version=None, max_version=None):
    """Register a schema to validate request query parameters."""
    def add_validator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            if 'req' in kwargs:
                req = kwargs['req']
            else:
                req = args[1]
            if req.environ['wsgiorg.routing_args'][1]:
                if _schema_validation_helper(query_params_schema, req.environ['wsgiorg.routing_args'][1], args, kwargs, is_body=False):
                    _remove_unexpected_query_parameters(query_params_schema, req)
            elif _schema_validation_helper(query_params_schema, req.GET.dict_of_lists(), args, kwargs, is_body=False):
                _remove_unexpected_query_parameters(query_params_schema, req)
            return func(*args, **kwargs)
        return wrapper
    return add_validator

def execute(cmd):
    """execute command, return rc and output string.
    The cmd argument can be a string or a list composed of
    the command name and each of its argument.
    eg, ['/usr/bin/cp', '-r', 'src', 'dst']"""
    if not isinstance(cmd, list):
        cmd = shlex.split(cmd)
    rc = 0
    output = ''
    try:
        output = subprocess.check_output(cmd, close_fds=True, stderr=subprocess.STDOUT)
    except subprocess.CalledProcessError as err:
        rc = err.returncode
        output = err.output
    except Exception as err:
        err_msg = 'Command "%s" Error: %s' % (' '.join(cmd), str(err))
        raise exception.SDKInternalError(msg=err_msg)
    output = bytes.decode(output)
    return (rc, output)

def convert_to_mb(s):
    """Convert memory size from GB to MB."""
    s = s.upper()
    try:
        if s.endswith('G'):
            return float(s[:-1].strip()) * 1024
        elif s.endswith('T'):
            return float(s[:-1].strip()) * 1024 * 1024
        else:
            return float(s[:-1].strip())
    except (IndexError, ValueError, KeyError, TypeError):
        errmsg = 'Invalid memory format: %s' % s
        raise exception.SDKInternalError(msg=errmsg)

def valid_mac_addr(addr):
    """Validates a mac address"""
    if not isinstance(addr, six.string_types):
        return False
    valid = re.compile('\n                      (^([0-9A-F]{2}[:]){5}([0-9A-F]{2})$)\n                      ', re.VERBOSE | re.IGNORECASE)
    return valid.match(addr) is not None

def expect_invalid_resp_data(data=''):
    """Catch exceptions when using zvm client response data."""
    try:
        yield
    except (ValueError, TypeError, IndexError, AttributeError, KeyError) as err:
        msg = 'Invalid smt response data: %s. Error: %s' % (data, six.text_type(err))
        LOG.error(msg)
        raise exception.SDKInternalError(msg=msg)

def wrap_invalid_resp_data_error(function):
    """Catch exceptions when using zvm client response data."""
    @functools.wraps(function)
    def decorated_function(*arg, **kwargs):
        try:
            return function(*arg, **kwargs)
        except (ValueError, TypeError, IndexError, AttributeError, KeyError) as err:
            msg = 'Invalid smt response data. Error: %s' % six.text_type(err)
            LOG.error(msg)
            raise exception.SDKInternalError(msg=msg)
    return decorated_function

def expect_and_reraise_internal_error(modID='SDK'):
    """Catch all kinds of zvm client request failure and reraise.

    modID: the moduleID that the internal error happens in."""
    try:
        yield
    except exception.SDKInternalError as err:
        msg = err.format_message()
        raise exception.SDKInternalError(msg, modID=modID)

def log_and_reraise_smt_request_failed(action=None):
    """Catch SDK base exception and print error log before reraise exception.

    msg: the error message to be logged."""
    try:
        yield
    except exception.SDKSMTRequestFailed as err:
        msg = ''
        if action is not None:
            msg = 'Failed to %s. ' % action
        msg += 'SMT error: %s' % err.format_message()
        LOG.error(msg)
        raise exception.SDKSMTRequestFailed(err.results, msg)

def get_namelist():
    """Generate namelist.

    Either through set CONF.zvm.namelist, or by generate based on smt userid."""
    if CONF.zvm.namelist is not None:
        if len(CONF.zvm.namelist) <= 8:
            return CONF.zvm.namelist
    userid = get_smt_userid()
    return 'NL' + userid.rjust(6, '0')[-6:]

def translate_response_to_dict(rawdata, dirt):
    """Translate SMT response to a python dictionary.

    SMT response example:
    keyword1: value1

    keyword2: value2

    ...
    keywordn: valuen


    Will return a python dictionary:
    {keyword1: value1,
     keyword2: value2,
     ...
     keywordn: valuen,}"""
    data_list = rawdata.split('\n')
    data = {}
    for ls in data_list:
        for k in list(dirt.keys()):
            if ls.__contains__(dirt[k]):
                data[k] = ls[ls.find(dirt[k]) + len(dirt[k]):].strip()
                break
    if data == {}:
        msg = 'Invalid smt response data. Error: No value matched with keywords. Raw Data: %(raw)s; Keywords: %(kws)s' % {'raw': rawdata, 'kws': str(dirt)}
        raise exception.SDKInternalError(msg=msg)
    return data

def delete_guest(userid):
