def _define_fixed(wrapped, callable_):
    """For the callable see how many positional parameters are required"""
    is_class = inspect.isclass(wrapped)
    style = callable_._splpy_style if hasattr(callable_, '_splpy_style') else wrapped._splpy_style
    if style == 'dictionary':
        return -1
    fixed_count = 0
    if style == 'tuple':
        sig = _inspect.signature(callable_)
        pmds = sig.parameters
        itpmds = iter(pmds)
        if is_class:
            next(itpmds)
        for pn in itpmds:
            param = pmds[pn]
            if param.kind == _inspect.Parameter.POSITIONAL_OR_KEYWORD:
                fixed_count += 1
            if param.kind == _inspect.Parameter.VAR_POSITIONAL:
                fixed_count = -1
                break
            if param.kind == _inspect.Parameter.VAR_KEYWORD:
                break
    return fixed_count

def ignore(wrapped):
    """Decorator to ignore a Python function.

    If a Python callable is decorated with ``@spl.ignore``
    then function is ignored by ``spl-python-extract.py``.

    Args:
        wrapped: Function that will be ignored."""
    @functools.wraps(wrapped)
    def _ignore(*args, **kwargs):
        return wrapped(*args, **kwargs)
    _ignore._splpy_optype = _OperatorType.Ignore
    _ignore._splpy_file = inspect.getsourcefile(wrapped)
    return _ignore

def sink(wrapped):
    """Creates an SPL operator with a single input port.

    A SPL operator with a single input port and no output ports.
    For each tuple on the input port the decorated function
    is called passing the contents of the tuple.

    .. deprecated:: 1.8
        Recommended to use :py:class:`@spl.for_each <for_each>` instead."""
    if not inspect.isfunction(wrapped):
        raise TypeError('A function is required')
    return _wrapforsplop(_OperatorType.Sink, wrapped, 'position', False)

def _splpy_convert_tuple(attributes):
    """Create a function that converts tuples to
    be submitted as dict objects into Python tuples
    with the value by position.
    Return function handles tuple,dict,list[tuple|dict|None],None"""
    def _to_tuples(tuple_):
        if isinstance(tuple_, tuple):
            return tuple_
        if isinstance(tuple_, dict):
            return tuple((tuple_.get(name, None) for name in attributes))
        if isinstance(tuple_, list):
            lt = list()
            for ev in tuple_:
                if isinstance(ev, dict):
                    ev = tuple((ev.get(name, None) for name in attributes))
                lt.append(ev)
            return lt
        return tuple_
    return _to_tuples

def _splpy_all_ports_ready(callable_):
    """Call all_ports_ready for a primitive operator."""
    if hasattr(type(callable_), 'all_ports_ready'):
        try:
            return callable_.all_ports_ready()
        except:
            ei = sys.exc_info()
            if streamsx._streams._runtime._call_exit(callable_, ei):
                return None
            raise e1[1]
    return None

def _normalize(schema, allow_none=True):
    """Normalize a schema."""
    if allow_none and schema is None:
        return schema
    if isinstance(schema, CommonSchema):
        return schema
    if isinstance(schema, StreamSchema):
        return schema
    if isinstance(schema, basestring):
        return StreamSchema(schema)
    py_types = {_spl_object: CommonSchema.Python, _spl_str: CommonSchema.String, json: CommonSchema.Json}
    if schema in py_types:
        return py_types[schema]
    if sys.version_info.major == 3:
        import typing
        if isinstance(schema, type) and issubclass(schema, tuple):
            if hasattr(schema, '_fields') and hasattr(schema, '_field_types'):
                return _from_named_tuple(schema)
    raise ValueError('Unknown stream schema type:' + str(schema))

def is_common(schema):
    """Is `schema` an common schema.

    Args:
        schema: Scheme to test.

    Returns:
        bool: ``True`` if schema is a common schema, otherwise ``False``."""
    if isinstance(schema, StreamSchema):
        return schema.schema() in _SCHEMA_COMMON
    if isinstance(schema, CommonSchema):
        return True
    if isinstance(schema, basestring):
        return is_common(StreamSchema(schema))
    return False

def _stop(sas, cmd_args):
    """Stop the service if no jobs are running unless force is set"""
    if not cmd_args.force:
        status = sas.get_instance_status()
        jobs = int(status['job_count'])
        if jobs:
            return status
    return sas.stop_instance()

def main(args=None):
    """Performs an action against a Streaming Analytics service.
    """
    streamsx._streams._version._mismatch_check('streamsx.topology.context')
    try:
        sr = run_cmd(args)
        sr['return_code'] = 0
    except:
