def _source_info():
    """Get information from the user's code (two frames up)
    to leave breadcrumbs for file, line, class and function."""
    ofi = inspect.getouterframes(inspect.currentframe())[2]
    try:
        calling_class = ofi[0].f_locals['self'].__class__
    except KeyError:
        calling_class = None
    return (ofi[1], ofi[2], calling_class, ofi[3])

def _get_package_name(module):
    """Gets the package name given a module object

    Returns:
        str: If the module belongs to a package, the package name.
             if the module does not belong to a package, None or ''."""
    try:
        package_name = module.__package__
    except AttributeError:
        package_name = None
    if package_name is None:
        package_name = module.__name__
        if not hasattr(module, '__path__'):
            package_name = package_name.rpartition('.')[0]
    return package_name

def _is_builtin_module(module):
    """Is builtin or part of standard library
    """
    if not hasattr(module, '__file__') or module.__name__ in sys.builtin_module_names:
        return True
    if module.__name__ in _stdlib._STD_LIB_MODULES:
        return True
    amp = os.path.abspath(module.__file__)
    if 'site-packages' in amp:
        return False
    if amp.startswith(_STD_MODULE_DIR):
        return True
    if not '.' in module.__name__:
        return False
    mn_top = module.__name__.split('.')[0]
    return mn_top in _stdlib._STD_LIB_MODULES

def _is_args_eightbit(*args) -> bool:
    """Check if input matches type: renderer.eightbit."""
    if not args:
        return False
    elif args[0] is 0:
        return True
    elif isinstance(args[0], int):
        return True
    else:
        return False

def request(method, path, params=None, data=None, auto_retry=True):
    """method - HTTP method. e.g. get, put, post, etc.
    path - Path to resource. e.g. /loss_sets/1234
    params - Parameter to pass in the query string
    data - Dictionary of parameters to pass in the request body"""
    body = None
    if data is not None:
        body = json.dumps(data, cls=utils.DateTimeEncoder)
    headers = {'accept': 'application/json', 'content-type': 'application/json', 'user-agent': analyzere.user_agent}
    resp = request_raw(method, path, params=params, body=body, headers=headers, auto_retry=auto_retry)
    content = resp.text
    if content:
        try:
            content = json.loads(content, cls=utils.DateTimeDecoder)
        except ValueError:
            raise errors.ServerError('Unable to parse JSON response returned from server.', resp, resp.status_code)
    return content

def read_in_chunks(file_obj, chunk_size):
    """Generator to read a file piece by piece."""
    offset = 0
    while True:
        data = file_obj.read(chunk_size)
        if not data:
            break
        yield (data, offset)
        offset += len(data)

def vectorize(values):
    """Takes a value or list of values and returns a single result, joined by ","
    if necessary."""
    if isinstance(values, list):
        return ','.join((str(v) for v in values))
    return values

def vectorize_range(values):
    """This function is for url encoding.
    Takes a value or a tuple or list of tuples and returns a single result,
    tuples are joined by "," if necessary, elements in tuple are joined by '_'"""
    if isinstance(values, tuple):
        return '_'.join((str(i) for i in values))
    if isinstance(values, list):
        if not all([isinstance(item, tuple) for item in values]):
            raise TypeError('Items in the list must be tuples')
        return ','.join(('_'.join((str(i) for i in v)) for v in values))
    return str(values)

def hashify_targets(targets: list, build_context) -> list:
    """Return sorted hashes of `targets`."""
    return sorted((build_context.targets[target_name].hash(build_context) for target_name in listify(targets)))

def hashify_files(files: list) -> dict:
    """Return mapping from file path to file hash."""
    return {filepath.replace('\\', '/'): hash_tree(filepath) for filepath in listify(files)}

def process_prop(prop_type: PT, value, build_context):
    """Return a cachable representation of the prop `value` given its type."""
    if prop_type in (PT.Target, PT.TargetList):
        return hashify_targets(value, build_context)
    elif prop_type in (PT.File, PT.FileList):
        return hashify_files(value)
    return value

def handle_build_cache(conf: Config, name: str, tag: str, icb: ImageCachingBehavior):
    """Handle Docker image build cache.

    Return image ID if image is cached, and there's no need to redo the build.
    Return None if need to build the image (whether cached locally or not).
    Raise RuntimeError if not allowed to build the image because of state of
    local cache.

    TODO(itamar): figure out a better name for this function, that reflects
    what it returns (e.g. `get_cached_image_id`),
    without "surprising" the caller with the potential of long
    and non-trivial operations that are not usually expected from functions
    with such names."""
    if icb.pull_if_cached or (icb.pull_if_not_cached and get_cached_image_id(icb.remote_image) is None):
        try:
            pull_docker_image(icb.remote_image, conf.docker_pull_cmd)
        except CalledProcessError:
            pass
    local_image = '{}:{}'.format(name, tag)
    if icb.skip_build_if_cached and get_cached_image_id(icb.remote_image) is not None:
        tag_docker_image(icb.remote_image, local_image)
        return get_cached_image_id(local_image)
    if not icb.allow_build_if_not_cached and get_cached_image_id(icb.remote_image) is None:
        raise RuntimeError('No cached image for {}'.format(local_image))
    return None

