def tidy_ssh_user(url=None, user=None):
    """make sure a git repo ssh:// url has a user set"""
    if url and url.startswith('ssh://'):
        match = re.compile('ssh://([^@]+)@.+').match(url)
        if match:
            ssh_user = match.group(1)
            if user and ssh_user != user:
                url = url.replace(re.escape(ssh_user) + '@', user + '@')
        elif user:
            url = 'ssh://' + user + '@' + url[len('ssh://'):]
    return url

def tag_patches_branch(package, local_patches_branch, patches_branch, force=False, push=False):
    """Tag the local_patches_branch with this package's NVR."""
    vr = specfile.Spec().get_vr(epoch=False)
    nvr_tag = package + '-' + vr
    tag_cmd = ['tag', nvr_tag, local_patches_branch]
    if force:
        tag_cmd.append('-f')
    git(*tag_cmd)
    if push:
        patches_remote = patches_branch.partition('/')[0]
        git('push', patches_remote, nvr_tag)
    else:
        print('Not pushing tag. Run "git push patches %s" by hand.' % nvr_tag)

def decamel(string):
    """"Split CamelCased words.

    CamelCase -> Camel Case, dromedaryCase -> dromedary Case."""
    regex = re.compile('(\\B[A-Z][a-z]*)')
    return regex.sub(' \\1', string)

def decamel_to_snake(string):
    """Convert to lower case, join camel case with underscore.
    CamelCase -> camel_case. Camel Case -> camel_case."""
    strings = [decamel(word) if not word.isupper() else word.lower() for word in string.split()]
    return '_'.join([snake(dstring) for dstring in strings])

def info_file(distro=None):
    """Return default distroinfo info file"""
    if not distro:
        distro = cfg['DISTRO']
    info_file_conf = distro.upper() + 'INFO_FILE'
    try:
        return cfg[info_file_conf]
    except KeyError:
        raise exception.InvalidUsage(why="Couldn't find config option %s for distro: %s" % (info_file_conf, distro))

def get_distroinfo(distro=None):
    """Get DistroInfo initialized from configuration"""
    if not distro:
        distro = cfg['DISTRO']
    _info_file = info_file(distro)
    git_info_url_conf = distro.upper() + 'INFO_REPO'
    try:
        remote_git_info = cfg[git_info_url_conf]
