def string_to_version(verstring):
    """Return a tuple of (epoch, version, release) from a version string

    This function replaces rpmUtils.miscutils.stringToVersion, see
    https://bugzilla.redhat.com/1364504"""
    components = verstring.split(':')
    if len(components) > 1:
        epoch = components[0]
    else:
        epoch = 0
    remaining = components[:2][0].split('-')
    version = remaining[0]
    release = remaining[1]
    return (epoch, version, release)

def spec_fn(spec_dir='.'):
    """Return the filename for a .spec file in this directory."""
    specs = [f for f in os.listdir(spec_dir) if os.path.isfile(f) and f.endswith('.spec')]
    if not specs:
        raise exception.SpecFileNotFound()
    if len(specs) != 1:
        raise exception.MultipleSpecFilesFound()
    return specs[0]

def version_parts(version):
    """Split a version string into numeric X.Y.Z part and the rest (milestone)."""
    m = re.match('(\\d+(?:\\.\\d+)*)([.%]|$)(.*)', version)
    if m:
        numver = m.group(1)
        rest = m.group(2) + m.group(3)
        return (numver, rest)
    else:
        return (version, '')

def patches_base_ref(default=exception.CantGuess):
    """Return a git reference to patches branch base.

    Returns first part of .spec's patches_base is found,
    otherwise return Version(+%{milestone})."""
    ref = None
    try:
        spec = specfile.Spec()
        ref, _ = spec.get_patches_base(expand_macros=True)
        if ref:
            ref, _ = tag2version(ref)
        else:
            ref = spec.get_tag('Version', expand_macros=True)
            milestone = spec.get_milestone()
            if milestone:
                ref += milestone
        if not ref:
            raise exception.CantGuess(msg='got empty .spec Version')
    except Exception as ex:
        if default is exception.CantGuess:
            raise exception.CantGuess(what='current package version', why=str(ex))
        else:
            return default
    tag_style = version_tag_style(ref)
    return version2tag(ref, tag_style=tag_style)

def decode(data):
    """Decode data employing some charset detection and including unicode BOM
    stripping."""
    if isinstance(data, unicode):
        return data
    for bom, encoding in UNICODE_BOMS:
        if data.startswith(bom):
            return data[len(bom):].decode(encoding, errors='ignore')
    try:
        return data.decode('utf-8')
    except UnicodeDecodeError:
        pass
    for encoding in COMMON_ENCODINGS:
        try:
            return data.decode(encoding)
        except UnicodeDecodeError:
            pass
    return NON_ASCII_FILTER.sub('', data).decode('ascii', errors='replace')

def live_pidfile(pidfile):
    """(pidfile:str) -> int | None
    Returns an int found in the named file, if there is one,
    and if there is a running process with that process id.
    Return None if no such process exists."""
    pid = read_pidfile(pidfile)
    if pid:
        try:
            kill(int(pid), 0)
            return pid
        except OSError as e:
            if e.errno == errno.EPERM:
                return pid
    return None

def _turn_sigterm_into_systemexit():
    """Attempts to turn a SIGTERM exception into a SystemExit exception."""
    try:
        import signal
    except ImportError:
        return
    def handle_term(signo, frame):
        raise SystemExit
    signal.signal(signal.SIGTERM, handle_term)

def should_skip_file(name):
    """Checks if a file should be skipped based on its name.

    If it should be skipped, returns the reason, otherwise returns
    None."""
    if name.startswith('.'):
        return 'Skipping hidden file %(filename)s'
    if name.endswith('~') or name.endswith('.bak'):
        return 'Skipping backup file %(filename)s'
    if name.endswith('.pyc') or name.endswith('.pyo'):
        return 'Skipping %s file ' % os.path.splitext(name)[1] + '%(filename)s'
    if name.endswith('$py.class'):
        return 'Skipping $py.class file %(filename)s'
    if name in ('CVS', '_darcs'):
        return 'Skipping version control directory %(filename)s'
    return None

def migrator(state):
    """Tweaks will be lost for Cleverbot and its conversations."""
    for tweak in ('tweak1', 'tweak2', 'tweak3'):
        del state[0][tweak]
        for convo in state[1]:
            if tweak in convo:
                del convo[tweak]
    return state

def version_range(guid, version, before=None, app_versions=None):
    """Returns all values after (and including) `version` for the app `guid`"""
    if app_versions is None:
        app_versions = validator.constants.APPROVED_APPLICATIONS
    app_key = None
    for app_guid, app_name in APPLICATIONS.items():
        if app_name == guid:
            guid = app_guid
            break
    for key in app_versions.keys():
        if app_versions[key]['guid'] == guid:
            app_key = key
            break
    if not app_key or version not in app_versions[app_key]['versions']:
        raise Exception('Bad GUID or version provided for version range: %s' % version)
    all_versions = app_versions[app_key]['versions']
    version_pos = all_versions.index(version)
    before_pos = None
    if before is not None and before in all_versions:
        before_pos = all_versions.index(before)
    return all_versions[version_pos:before_pos]

def validate_name(err, value, source):
    """Tests a manifest name value for trademarks."""
    ff_pattern = re.compile('(mozilla|firefox)', re.I)
    err.metadata['name'] = value
    if ff_pattern.search(value):
        err.warning(('metadata_helpers', '_test_name', 'trademark'), 'Add-on has potentially illegal name.', 'Add-on names cannot contain the Mozilla or Firefox trademarks. These names should not be contained in add-on names if at all possible.', source)

def validate_version(err, value, source):
    """Tests a manifest version number"""
    field_name = '<em:version>' if source == 'install.rdf' else 'version'
    err.metadata['version'] = value
    if len(value) > 32:
        err.error(('metadata_helpers', '_test_version', 'too_long'), 'The value of {name} is too long'.format(name=field_name), 'Values supplied for {name} in the {source} file must be 32 characters or less.'.format(name=field_name, source=source), source)
    if not VERSION_PATTERN.match(value):
        err.error(('metadata_helpers', '_test_version', 'invalid_format'), 'The value of {name} is invalid'.format(name=field_name), 'The values supplied for version in the {source} file is not a valid version string. It can only contain letters, numbers, and the symbols +*.-_.'.format(name=field_name, source=source), source)

def replace_keys(d, keymap, force_snake_case):
    """:param dict d:
    :param Dict[unicode, unicode] keymap:
