def grok_ttl(secret):
    """Parses the TTL information"""
    ttl_obj = {}
    lease_msg = ''
    if 'lease' in secret:
        ttl_obj['lease'] = secret['lease']
        lease_msg = 'lease:%s' % ttl_obj['lease']
    if 'lease_max' in secret:
        ttl_obj['lease_max'] = secret['lease_max']
    elif 'lease' in ttl_obj:
        ttl_obj['lease_max'] = ttl_obj['lease']
    if 'lease_max' in ttl_obj:
        lease_msg = '%s lease_max:%s' % (lease_msg, ttl_obj['lease_max'])
    return (ttl_obj, lease_msg)

def my_version():
    """Return the version, checking both packaged and development locations"""
    if os.path.exists(resource_filename(__name__, 'version')):
        return resource_string(__name__, 'version')
    return open(os.path.join(os.path.dirname(__file__), '..', 'version')).read()

def abspath(raw):
    """Return what is hopefully a OS independent path."""
    path_bits = []
    if raw.find('/') != -1:
        path_bits = raw.split('/')
    elif raw.find('\\') != -1:
        path_bits = raw.split('\\')
    else:
        path_bits = [raw]
    return os.path.abspath(os.sep.join(path_bits))

def is_tagged(required_tags, has_tags):
    """Checks if tags match"""
    if not required_tags and (not has_tags):
        return True
    elif not required_tags:
        return False
    found_tags = []
    for tag in required_tags:
        if tag in has_tags:
            found_tags.append(tag)
    return len(found_tags) == len(required_tags)

def cli_hash(list_of_kv):
    """Parse out a hash from a list of key=value strings"""
    ev_obj = {}
    for extra_var in list_of_kv:
        ev_list = extra_var.split('=')
        key = ev_list[0]
        val = '='.join(ev_list[1:])
        ev_obj[key] = val
    return ev_obj

def merge_dicts(dict_a, dict_b):
    """Deep merge of two dicts"""
    obj = {}
    for key, value in iteritems(dict_a):
        if key in dict_b:
            if isinstance(dict_b[key], dict):
                obj[key] = merge_dicts(value, dict_b.pop(key))
        else:
            obj[key] = value
    for key, value in iteritems(dict_b):
        obj[key] = value
    return obj

def get_tty_password(confirm):
    """When returning a password from a TTY we assume a user
    is entering it on a keyboard so we ask for confirmation."""
    LOG.debug('Reading password from TTY')
    new_password = getpass('Enter Password: ', stream=sys.stderr)
    if not new_password:
        raise aomi.exceptions.AomiCommand('Must specify a password')
    if not confirm:
        return new_password
    confirm_password = getpass('Again, Please: ', stream=sys.stderr)
    if confirm_password != new_password:
        raise aomi.exceptions.AomiCommand('Passwords do not match')
    return new_password

def mount_for_path(path, client):
    """Returns the mountpoint for this path"""
    backend_data = client.list_secret_backends()['data']
    backends = [mnt for mnt in backend_data.keys()]
    path_bits = path.split('/')
    if len(path_bits) == 1:
        vault_path = '%s/' % path
        if vault_path in backends:
            return vault_path[0:len(vault_path) - 1]
    else:
        for i in range(1, len(path_bits) + 1):
            vault_path = '%s/' % '/'.join(path_bits[0:i])
            if vault_path in backends:
                return vault_path[0:len(vault_path) - 1]
    return None

def choose_one(things):
    """Returns a random entry from a list of things"""
    choice = SystemRandom().randint(0, len(things) - 1)
    return things[choice].strip()

def subdir_path(directory, relative):
    """Returns a file path relative to another path."""
    item_bits = directory.split(os.sep)
    relative_bits = relative.split(os.sep)
    for i, _item in enumerate(item_bits):
        if i == len(relative_bits) - 1:
            return os.sep.join(item_bits[i:])
        elif item_bits[i] != relative_bits[i]:
            return None
    return None

def open_maybe_binary(filename):
    """Opens something that might be binary but also
    might be "plain text"."""
    if sys.version_info >= (3, 0):
        data = open(filename, 'rb').read()
        try:
            return data.decode('utf-8')
        except UnicodeDecodeError:
            return data
    return open(filename, 'r').read()

def ensure_dir(path):
    """Ensures a directory exists"""
    if not (os.path.exists(path) and os.path.isdir(path)):
        os.mkdir(path)

def clean_tmpdir(path):
    """Invoked atexit, this removes our tmpdir"""
    if os.path.exists(path) and os.path.isdir(path):
        rmtree(path)

def diff_dict(dict1, dict2, ignore_missing=False):
    """Performs a base type comparison between two dicts"""
    unidict1 = dict_unicodeize(dict1)
    unidict2 = dict_unicodeize(dict2)
    if not ignore_missing and len(unidict1) != len(unidict2) or (ignore_missing and len(unidict1) >= len(unidict2)):
        return True
    for comp_k, comp_v in iteritems(unidict1):
        if comp_k not in unidict2:
            return True
        elif comp_v != unidict2[comp_k]:
            return True
    return False

def map_val(dest, src, key, default=None, src_key=None):
    """Will ensure a dict has values sourced from either
    another dict or based on the provided default"""
    if not src_key:
        src_key = key
    if src_key in src:
        dest[key] = src[src_key]
    elif default is not None:
        dest[key] = default

def filtered_context(context):
    """Filters a context
    This will return a new context with only the resources that
    are actually available for use. Uses tags and command line
    options to make determination."""
    ctx = Context(context.opt)
    for resource in context.resources():
        if resource.child:
            continue
        if resource.filtered():
            ctx.add(resource)
    return ctx

def find_model(config, obj, mods):
    """Given a list of mods (as returned by py_resources) attempts to
    determine if a given Python obj fits one of the models"""
    for mod in mods:
        if mod[0] != config:
            continue
        if len(mod) == 2:
            return mod[1]
        if len(mod) == 3 and mod[1] in obj:
            return mod[2]
    return None

def py_resources():
    """Discovers all aomi Vault resource models. This includes
    anything extending aomi.model.Mount or aomi.model.Resource."""
    aomi_mods = [m for m, _v in iteritems(sys.modules) if m.startswith('aomi.model')]
    mod_list = []
    mod_map = []
    for amod in [sys.modules[m] for m in aomi_mods]:
        for _mod_bit, model in inspect.getmembers(amod):
            if str(model) in mod_list:
                continue
            if model == Mount:
                mod_list.append(str(model))
                mod_map.append((model.config_key, model))
            elif inspect.isclass(model) and issubclass(model, Resource) and model.config_key:
                mod_list.append(str(model))
                if model.resource_key:
                    mod_map.append((model.config_key, model.resource_key, model))
                elif model.config_key != 'secrets':
                    mod_map.append((model.config_key, model))
    return mod_map

def secret_key_name(path, key, opt):
    """Renders a Secret key name appropriately"""
    value = key
    if opt.merge_path:
        norm_path = [x for x in path.split('/') if x]
        value = '%s_%s' % ('_'.join(norm_path), key)
    if opt.add_prefix:
        value = '%s%s' % (opt.add_prefix, value)
    if opt.add_suffix:
        value = '%s%s' % (value, opt.add_suffix)
    return value

def grok_template_file(src):
    """Determine the real deal template file"""
    if not src.startswith('builtin:'):
        return abspath(src)
    builtin = src.split(':')[1]
    builtin = 'templates/%s.j2' % builtin
    return resource_filename(__name__, builtin)

def template(client, src, dest, paths, opt):
    """Writes a template using variables from a vault path"""
    key_map = cli_hash(opt.key_map)
    obj = {}
    for path in paths:
        response = client.read(path)
        if not response:
            raise aomi.exceptions.VaultData('Unable to retrieve %s' % path)
        if is_aws(response['data']) and 'sts' not in path:
            renew_secret(client, response, opt)
        for s_k, s_v in response['data'].items():
            o_key = s_k
            if s_k in key_map:
                o_key = key_map[s_k]
            k_name = secret_key_name(path, o_key, opt).lower().replace('-', '_')
            obj[k_name] = s_v
    template_obj = blend_vars(obj, opt)
    output = render(grok_template_file(src), template_obj)
    write_raw_file(output, abspath(dest))

def write_raw_file(secret, dest):
    """Writes an actual secret out to a file"""
    secret_file = None
    secret_filename = abspath(dest)
    if sys.version_info >= (3, 0):
        if not isinstance(secret, str):
            secret_file = open(secret_filename, 'wb')
    if not secret_file:
        secret_file = open(secret_filename, 'w')
    secret_file.write(secret)
    secret_file.close()
    os.chmod(secret_filename, 384)

def env(client, paths, opt):
    """Renders a shell snippet based on paths in a Secretfile"""
    old_prefix = False
    old_prefix = opt.prefix and (not (opt.add_prefix or opt.add_suffix or (not opt.merge_path)))
    if old_prefix:
        LOG.warning('the prefix option is deprecated please use--no-merge-path --add-prefix $OLDPREFIX_ instead')
    elif opt.prefix:
        LOG.warning('the prefix option is deprecatedplease use--no-merge-path --add-prefix $OLDPREFIX_ instead')
    key_map = cli_hash(opt.key_map)
    for path in paths:
        secrets = client.read(path)
        if secrets and 'data' in secrets:
            if is_aws(secrets['data']) and 'sts' not in path:
                renew_secret(client, secrets, opt)
            for s_key, s_val in secrets['data'].items():
                o_key = s_key
                if s_key in key_map:
                    o_key = key_map[s_key]
                env_name = None
                if old_prefix:
                    env_name = ('%s_%s' % (opt.prefix, o_key)).upper()
                else:
                    env_name = secret_key_name(path, o_key, opt).upper()
                print('%s="%s"' % (env_name, s_val))
                if opt.export:
                    print('export %s' % env_name)

def aws(client, path, opt):
    """Renders a shell environment snippet with AWS information"""
    try:
        creds = client.read(path)
    except hvac.exceptions.InternalServerError as vault_exception:
        if vault_exception.errors[0].find('unsupported path') > 0:
            emsg = 'Invalid AWS path. Did you forget the credential type and role?'
            raise aomi.exceptions.AomiFile(emsg)
        else:
            raise
    if not creds:
        emsg = 'Invalid AWS path. Did you forget the credential type and role?'
        raise aomi.exceptions.AomiFile(emsg)
    renew_secret(client, creds, opt)
    if creds and 'data' in creds:
        print('AWS_ACCESS_KEY_ID="%s"' % creds['data']['access_key'])
        print('AWS_SECRET_ACCESS_KEY="%s"' % creds['data']['secret_key'])
        if 'security_token' in creds['data'] and creds['data']['security_token']:
            token = creds['data']['security_token']
            print('AWS_SECURITY_TOKEN="%s"' % token)
    else:
        client.revoke_self_token()
        e_msg = 'Unable to generate AWS credentials from %s' % path
        raise aomi.exceptions.VaultData(e_msg)
    if opt.export:
        print('export AWS_ACCESS_KEY_ID')
        print('export AWS_SECRET_ACCESS_KEY')
        if 'security_token' in creds['data'] and creds['data']['security_token']:
            print('export AWS_SECURITY_TOKEN')

def generated_key(key):
    """Create the proper generated key value"""
    key_name = key['name']
    if key['method'] == 'uuid':
        LOG.debug('Setting %s to a uuid', key_name)
        return str(uuid4())
    elif key['method'] == 'words':
        LOG.debug('Setting %s to random words', key_name)
        return random_word()
    elif key['method'] == 'static':
        if 'value' not in key.keys():
            raise aomi.exceptions.AomiData('Missing static value')
        LOG.debug('Setting %s to a static value', key_name)
        return key['value']
    else:
        raise aomi.exceptions.AomiData('Unexpected generated secret method %s' % key['method'])

def unhandled(exception, opt):
    """Handle uncaught/unexpected errors and be polite about it"""
    exmod = type(exception).__module__
    name = '%s.%s' % (exmod, type(exception).__name__)
    if exmod == 'aomi.exceptions' or exmod == 'cryptorito':
        if hasattr(exception, 'source'):
            output(exception.message, opt, extra=exception.source)
        else:
            output(exception.message, opt)
    else:
        output('Unexpected error: %s' % name, opt)
    sys.exit(1)

def output(message, opt, extra=None):
    """Politely display an unexpected error"""
    print(message, file=sys.stderr)
    if opt.verbose:
        if extra:
            print(extra)
        traceback.print_exc(sys.stderr)

def grok_seconds(lease):
    """Ensures that we are returning just seconds"""
    if lease.endswith('s'):
        return int(lease[0:-1])
    elif lease.endswith('m'):
        return int(lease[0:-1]) * 60
    elif lease.endswith('h'):
        return int(lease[0:-1]) * 3600
    return None

def renew_secret(client, creds, opt):
    """Renews a secret. This will occur unless the user has
    specified on the command line that it is not neccesary"""
    if opt.reuse_token:
        return
    seconds = grok_seconds(opt.lease)
    if not seconds:
        raise aomi.exceptions.AomiCommand('invalid lease %s' % opt.lease)
    renew = None
    if client.version:
        v_bits = client.version.split('.')
        if int(v_bits[0]) == 0 and int(v_bits[1]) <= 8 and (int(v_bits[2]) <= 0):
            r_obj = {'increment': seconds}
            r_path = 'v1/sys/renew/{0}'.format(creds['lease_id'])
            renew = client._post(r_path, json=r_obj).json()
    if not renew:
        renew = client.renew_secret(creds['lease_id'], seconds)
    if not renew or seconds - renew['lease_duration'] >= 5:
        client.revoke_self_token()
        e_msg = 'Unable to renew with desired lease'
        raise aomi.exceptions.VaultConstraint(e_msg)

def app_token(vault_client, app_id, user_id):
    """Returns a vault token based on the app and user id."""
    resp = vault_client.auth_app_id(app_id, user_id)
    if 'auth' in resp and 'client_token' in resp['auth']:
        return resp['auth']['client_token']
    else:
        raise aomi.exceptions.AomiCredentials('invalid apptoken')

def token_meta(opt):
    """Generates metadata for a token"""
    meta = {'via': 'aomi', 'operation': opt.operation, 'hostname': socket.gethostname()}
    if 'USER' in os.environ:
        meta['unix_user'] = os.environ['USER']
    if opt.metadata:
        meta_bits = opt.metadata.split(',')
        for meta_bit in meta_bits:
            key, value = meta_bit.split('=')
        if key not in meta:
            meta[key] = value
    for key, value in meta.items():
        LOG.debug('Token metadata %s %s', key, value)
    return meta

def get_backend(backend, path, backends):
    """Returns mountpoint details for a backend"""
    m_norm = normalize_vault_path(path)
    for mount_name, values in backends.items():
        b_norm = normalize_vault_path(mount_name)
        if m_norm == b_norm and values['type'] == backend:
            return values
    return None

def wrap_hvac(msg):
    """Error catching Vault API wrapper
    This decorator wraps API interactions with Vault. It will
    catch and return appropriate error output on common
    problems. Do we even need this now that we extend the
    hvac class?"""
    def wrap_call(func):
        def func_wrapper(self, vault_client):
            try:
                return func(self, vault_client)
            except (hvac.exceptions.InvalidRequest, hvac.exceptions.Forbidden) as vault_exception:
                if vault_exception.errors[0] == 'permission denied':
                    emsg = 'Permission denied %s from %s' % (msg, self.path)
                    raise aomi.exceptions.AomiCredentials(emsg)
                else:
                    raise
        return func_wrapper
    return wrap_call

def grok_keys(config):
    """Will retrieve a GPG key from either Keybase or GPG directly"""
    key_ids = []
    for key in config['pgp_keys']:
        if key.startswith('keybase:'):
            key_id = from_keybase(key[8:])
            LOG.debug('Encrypting for keybase user %s', key[8:])
        else:
            if not has_gpg_key(key):
                raise aomi.exceptions.GPG('Do not actually have key %s' % key)
            LOG.debug('Encrypting for gpg id %s', key)
            key_id = key
        validate_gpg_fingerprint(key_id)
        key_ids.append(key_id)
    return key_ids

def thaw_decrypt(vault_client, src_file, tmp_dir, opt):
    """Decrypts the encrypted ice file"""
    if not os.path.isdir(opt.secrets):
        LOG.info('Creating secret directory %s', opt.secrets)
        os.mkdir(opt.secrets)
    zip_file = '%s/aomi.zip' % tmp_dir
    if opt.gpg_pass_path:
        gpg_path_bits = opt.gpg_pass_path.split('/')
        gpg_path = '/'.join(gpg_path_bits[0:len(gpg_path_bits) - 1])
        gpg_field = gpg_path_bits[len(gpg_path_bits) - 1]
        resp = vault_client.read(gpg_path)
        gpg_pass = None
        if resp and 'data' in resp and (gpg_field in resp['data']):
            gpg_pass = resp['data'][gpg_field]
            if not gpg_pass:
                raise aomi.exceptions.GPG('Unable to retrieve GPG password')
            LOG.debug('Retrieved GPG password from Vault')
            if not decrypt(src_file, zip_file, passphrase=gpg_pass):
                raise aomi.exceptions.GPG('Unable to gpg')
        else:
            raise aomi.exceptions.VaultData('Unable to retrieve GPG password')
    elif not decrypt(src_file, zip_file):
        raise aomi.exceptions.GPG('Unable to gpg')
    return zip_file

def find_file(name, directory):
    """Searches up from a directory looking for a file"""
    path_bits = directory.split(os.sep)
    for i in range(0, len(path_bits) - 1):
        check_path = path_bits[0:len(path_bits) - i]
        check_file = '%s%s%s' % (os.sep.join(check_path), os.sep, name)
        if os.path.exists(check_file):
            return abspath(check_file)
    return None

def in_file(string, search_file):
    """Looks in a file for a string."""
    handle = open(search_file, 'r')
    for line in handle.readlines():
        if string in line:
            return True
    return False

def gitignore(opt):
    """Will check directories upwards from the Secretfile in order
    to ensure the gitignore file is set properly"""
    directory = os.path.dirname(abspath(opt.secretfile))
    gitignore_file = find_file('.gitignore', directory)
    if gitignore_file:
        secrets_path = subdir_path(abspath(opt.secrets), gitignore_file)
        if secrets_path:
            if not in_file(secrets_path, gitignore_file):
                e_msg = 'The path %s was not found in %s' % (secrets_path, gitignore_file)
                raise aomi.exceptions.AomiFile(e_msg)
        else:
            LOG.debug('Using a non-relative secret directory')
    else:
        raise aomi.exceptions.AomiFile('You should really have a .gitignore')

def secret_file(filename):
    """Will check the permissions of things which really
    should be secret files"""
    filestat = os.stat(abspath(filename))
    if stat.S_ISREG(filestat.st_mode) == 0 and stat.S_ISLNK(filestat.st_mode) == 0:
        e_msg = 'Secret file %s must be a real file or symlink' % filename
        raise aomi.exceptions.AomiFile(e_msg)
    if platform.system() != 'Windows':
        if filestat.st_mode & stat.S_IROTH or filestat.st_mode & stat.S_IWOTH or filestat.st_mode & stat.S_IWGRP:
            e_msg = 'Secret file %s has too loose permissions' % filename
            raise aomi.exceptions.AomiFile(e_msg)

def validate_obj(keys, obj):
    """Super simple "object" validation."""
    msg = ''
    for k in keys:
        if isinstance(k, str):
            if k not in obj or (not isinstance(obj[k], list) and (not obj[k])):
                if msg:
                    msg = '%s,' % msg
                msg = '%s%s' % (msg, k)
        elif isinstance(k, list):
            found = False
            for k_a in k:
                if k_a in obj:
                    found = True
            if not found:
                if msg:
                    msg = '%s,' % msg
                msg = '%s(%s' % (msg, ','.join(k))
    if msg:
        msg = '%s missing' % msg
    return msg

def specific_path_check(path, opt):
    """Will make checks against include/exclude to determine if we
    actually care about the path in question."""
    if opt.exclude:
        if path in opt.exclude:
            return False
    if opt.include:
        if path not in opt.include:
            return False
    return True

def check_obj(keys, name, obj):
    """Do basic validation on an object"""
    msg = validate_obj(keys, obj)
    if msg:
        raise aomi.exceptions.AomiData('object check : %s in %s' % (msg, name))

def sanitize_mount(mount):
    """Returns a quote-unquote sanitized mount path"""
    sanitized_mount = mount
    if sanitized_mount.startswith('/'):
        sanitized_mount = sanitized_mount[1:]
    if sanitized_mount.endswith('/'):
        sanitized_mount = sanitized_mount[:-1]
    sanitized_mount = sanitized_mount.replace('//', '/')
    return sanitized_mount

def gpg_fingerprint(key):
    """Validates a GPG key fingerprint

    This handles both pre and post GPG 2.1"""
    if len(key) == 8 and re.match('^[0-9A-F]{8}$', key) or (len(key) == 40 and re.match('^[0-9A-F]{40}$', key)):
        return
    raise aomi.exceptions.Validation('Invalid GPG Fingerprint')

def is_unicode_string(string):
    """Validates that we are some kinda unicode string"""
    try:
        if sys.version_info >= (3, 0):
            if not isinstance(string, str):
                string.decode('utf-8')
        else:
            string.decode('utf-8')
    except UnicodeError:
        raise aomi.exceptions.Validation('Not a unicode string')

def is_unicode(string):
    """Validates that the object itself is some kinda string"""
    str_type = str(type(string))
    if str_type.find('str') > 0 or str_type.find('unicode') > 0:
        return True
    return False

def grok_filter_name(element):
    """Extracts the name, which may be embedded, for a Jinja2
    filter node"""
    e_name = None
    if element.name == 'default':
        if isinstance(element.node, jinja2.nodes.Getattr):
            e_name = element.node.node.name
        else:
            e_name = element.node.name
    return e_name

def grok_for_node(element, default_vars):
    """Properly parses a For loop element"""
    if isinstance(element.iter, jinja2.nodes.Filter):
        if element.iter.name == 'default' and element.iter.node.name not in default_vars:
            default_vars.append(element.iter.node.name)
        default_vars = default_vars + grok_vars(element)
    return default_vars

def grok_if_node(element, default_vars):
    """Properly parses a If element"""
    if isinstance(element.test, jinja2.nodes.Filter) and element.test.name == 'default':
        default_vars.append(element.test.node.name)
    return default_vars + grok_vars(element)

def grok_vars(elements):
    """Returns a list of vars for which the value is being appropriately set
    This currently includes the default filter, for-based iterators,
    and the explicit use of set"""
    default_vars = []
    iterbody = None
    if hasattr(elements, 'body'):
        iterbody = elements.body
    elif hasattr(elements, 'nodes'):
        iterbody = elements.nodes
    for element in iterbody:
        if isinstance(element, jinja2.nodes.Output):
            default_vars = default_vars + grok_vars(element)
        elif isinstance(element, jinja2.nodes.Filter):
            e_name = grok_filter_name(element)
            if e_name not in default_vars:
                default_vars.append(e_name)
        elif isinstance(element, jinja2.nodes.For):
            default_vars = grok_for_node(element, default_vars)
        elif isinstance(element, jinja2.nodes.If):
            default_vars = grok_if_node(element, default_vars)
        elif isinstance(element, jinja2.nodes.Assign):
            default_vars.append(element.target.name)
        elif isinstance(element, jinja2.nodes.FromImport):
            for from_var in element.names:
                default_vars.append(from_var)
    return default_vars

def missing_vars(template_vars, parsed_content, obj):
    """If we find missing variables when rendering a template
    we want to give the user a friendly error"""
    missing = []
    default_vars = grok_vars(parsed_content)
    for var in template_vars:
        if var not in default_vars and var not in obj:
            missing.append(var)
    if missing:
        e_msg = 'Missing required variables %s' % ','.join(missing)
        raise aomi_excep.AomiData(e_msg)

def render(filename, obj):
    """Render a template, maybe mixing in extra variables"""
    template_path = abspath(filename)
    env = jinja_env(template_path)
    template_base = os.path.basename(template_path)
    try:
        parsed_content = env.parse(env.loader.get_source(env, template_base))
        template_vars = meta.find_undeclared_variables(parsed_content)
        if template_vars:
            missing_vars(template_vars, parsed_content, obj)
        LOG.debug('rendering %s with %s vars', template_path, len(template_vars))
        return env.get_template(template_base).render(**obj)
    except jinja2.exceptions.TemplateSyntaxError as exception:
        template_trace = traceback.format_tb(sys.exc_info()[2])
        if exception.filename:
            template_line = template_trace[len(template_trace) - 1]
            raise aomi_excep.Validation('Bad template %s %s' % (template_line, str(exception)))
        template_str = ''
        if isinstance(exception.source, tuple):
            template_str = 'Embedded Template\n%s' % exception.source[0]
        raise aomi_excep.Validation('Bad template %s' % str(exception), source=template_str)
    except jinja2.exceptions.UndefinedError as exception:
        template_traces = [x.strip() for x in traceback.format_tb(sys.exc_info()[2]) if 'template code' in x]
        raise aomi_excep.Validation('Missing template variable %s' % ' '.join(template_traces))

def load_vars(opt):
    """Loads variable from cli and var files, passing in cli options
    as a seed (although they can be overwritten!).
    Note, turn this into an object so it's a nicer "cache"."""
    if not hasattr(opt, '_vars_cache'):
        cli_opts = cli_hash(opt.extra_vars)
        setattr(opt, '_vars_cache', merge_dicts(load_var_files(opt, cli_opts), cli_opts))
    return getattr(opt, '_vars_cache')

def load_var_files(opt, p_obj=None):
    """Load variable files, merge, return contents"""
    obj = {}
    if p_obj:
        obj = p_obj
    for var_file in opt.extra_vars_file:
        LOG.debug('loading vars from %s', var_file)
        obj = merge_dicts(obj.copy(), load_var_file(var_file, obj))
    return obj

def load_var_file(filename, obj):
    """Loads a varible file, processing it as a template"""
    rendered = render(filename, obj)
    ext = os.path.splitext(filename)[1][1:]
    v_obj = dict()
    if ext == 'json':
        v_obj = json.loads(rendered)
    elif ext == 'yaml' or ext == 'yml':
        v_obj = yaml.safe_load(rendered)
    else:
        LOG.warning('assuming yaml for unrecognized extension %s', ext)
        v_obj = yaml.safe_load(rendered)
    return v_obj

def load_template_help(builtin):
    """Loads the help for a given template"""
    help_file = 'templates/%s-help.yml' % builtin
    help_file = resource_filename(__name__, help_file)
    help_obj = {}
    if os.path.exists(help_file):
        help_data = yaml.safe_load(open(help_file))
        if 'name' in help_data:
            help_obj['name'] = help_data['name']
        if 'help' in help_data:
            help_obj['help'] = help_data['help']
        if 'args' in help_data:
            help_obj['args'] = help_data['args']
    return help_obj

def builtin_list():
    """Show a listing of all our builtin templates"""
    for template in resource_listdir(__name__, 'templates'):
        builtin, ext = os.path.splitext(os.path.basename(abspath(template)))
        if ext == '.yml':
            continue
        help_obj = load_template_help(builtin)
        if 'name' in help_obj:
            print('%-*s %s' % (20, builtin, help_obj['name']))
        else:
            print('%s' % builtin)

def builtin_info(builtin):
    """Show information on a particular builtin template"""
    help_obj = load_template_help(builtin)
    if help_obj.get('name') and help_obj.get('help'):
        print('The %s template' % help_obj['name'])
        print(help_obj['help'])
    else:
        print('No help for %s' % builtin)
    if help_obj.get('args'):
        for arg, arg_help in iteritems(help_obj['args']):
            print('  %-*s %s' % (20, arg, arg_help))

def render_secretfile(opt):
    """Renders and returns the Secretfile construct"""
    LOG.debug('Using Secretfile %s', opt.secretfile)
    secretfile_path = abspath(opt.secretfile)
    obj = load_vars(opt)
    return render(secretfile_path, obj)

def password(client, path):
    """Will attempt to contextually update a password in Vault"""
    if path.startswith('user:'):
        update_user_password(client, path[5:])
    else:
        update_generic_password(client, path)

def vault_time_to_s(time_string):
    """Will convert a time string, as recognized by other Vault
    tooling, into an integer representation of seconds"""
    if not time_string or len(time_string) < 2:
        raise aomi.exceptions.AomiData('Invalid timestring %s' % time_string)
    last_char = time_string[len(time_string) - 1]
    if last_char == 's':
        return int(time_string[0:len(time_string) - 1])
    elif last_char == 'm':
        cur = int(time_string[0:len(time_string) - 1])
        return cur * 60
    elif last_char == 'h':
        cur = int(time_string[0:len(time_string) - 1])
        return cur * 3600
    elif last_char == 'd':
        cur = int(time_string[0:len(time_string) - 1])
        return cur * 86400
    else:
        raise aomi.exceptions.AomiData('Invalid time scale %s' % last_char)

def run(*args, **kwargs):
    """Execute a command.

    Command can be passed as several arguments, each being a string
    or a list of strings; lists are flattened.
    If opts.verbose is True, output of the command is shown.
    If the command exits with non-zero, print an error message and exit.
    If keyward argument get_output is True, output is returned.
    Additionally, non-zero exit code with empty output is ignored."""
    capture = kwargs.get('get_output', False)
    args = [arg for arglist in args for arg in (arglist if isinstance(arglist, list) else [arglist])]
    if opts.verbose:
        print('Running {}'.format(' '.join(args)))
    live_output = opts.verbose and (not capture)
    runner = subprocess.check_call if live_output else subprocess.check_output
    try:
        output = runner(args, stderr=subprocess.STDOUT)
    except subprocess.CalledProcessError as exception:
        if capture and (not exception.output.strip()):
            return ''
        if not live_output:
            sys.stdout.write(exception.output.decode(default_encoding, 'ignore'))
        sys.exit('Error: got exitcode {} from command {}'.format(exception.returncode, ' '.join(args)))
    except OSError:
        sys.exit("Error: couldn't run {}: is {} in PATH?".format(' '.join(args), args[0]))
    if opts.verbose and capture:
        sys.stdout.write(output.decode(default_encoding, 'ignore'))
    return capture and output.decode(default_encoding, 'ignore').strip()

def get_file_contents(source_path: str) -> str:
    """Loads the contents of the source into a string for execution using multiple
    loading methods to handle cross-platform encoding edge cases. If none of
    the load methods work, a string is returned that contains an error function
    response that will be displayed when the step is run alert the user to the
    error.

    :param source_path:
        Path of the step file to load."""
    open_funcs = [functools.partial(codecs.open, source_path, encoding='utf-8'), functools.partial(open, source_path, 'r')]
    for open_func in open_funcs:
        try:
            with open_func() as f:
                return f.read()
        except Exception:
            pass
    return 'raise IOError("Unable to load step file at: {}")'.format(source_path)

def abort():
    """..."""
    uid_list = list(server_runner.active_execution_responses.keys())
    while len(uid_list) > 0:
        uid = uid_list.pop()
        response = server_runner.active_execution_responses.get(uid)
        if not response:
            continue
        try:
            del server_runner.active_execution_responses[uid]
        except Exception:
            pass
        if not response.thread or not response.thread.is_alive():
            continue
        response.thread.abort = True
        response.thread.join(2)
        try:
            if response.thread.is_alive():
                response.thread.abort_running()
        except Exception:
            pass
    project = cd.project.internal_project
    if project and project.current_step:
        step = project.current_step
        if step.is_running:
            step.is_running = False
            step.progress = 0
            step.progress_message = None
            step.dumps()
        redirection.disable(step)
    redirection.restore_default_configuration()
    project_data = project.kernel_serialize() if project else None
    return flask.jsonify(Response().update(project=project_data).serialize())

def entry_from_dict(data: dict) -> typing.Union[FILE_WRITE_ENTRY, FILE_COPY_ENTRY]:
    """Converts the given data dictionary into either a file write or file copy
    entry depending on the keys in the dictionary. The dictionary should
    contain either ('path', 'contents') keys for file write entries or
    ('source', 'destination') keys for file copy entries."""
    if 'contents' in data:
        return FILE_WRITE_ENTRY(**data)
    return FILE_COPY_ENTRY(**data)

def deploy(files_list: typing.List[tuple]):
    """Iterates through the specified files_list and copies or writes each entry
    depending on whether its a file copy entry or a file write entry.

    :param files_list:
        A list of file write entries and file copy entries"""
    def deploy_entry(entry):
        if not entry:
            return
        if hasattr(entry, 'source') and hasattr(entry, 'destination'):
            return copy(entry)
        if hasattr(entry, 'path') and hasattr(entry, 'contents'):
            return write(entry)
        raise ValueError('Unrecognized deployment entry {}'.format(entry))
    return [deploy_entry(f) for f in files_list]

def restore_default_configuration():
    """Restores the sys.stdout and the sys.stderr buffer streams to their default
    values without regard to what step has currently overridden their values.
    This is useful during cleanup outside of the running execution block"""
    def restore(target, default_value):
        if target == default_value:
            return default_value
        if not isinstance(target, RedirectBuffer):
            return target
        try:
            target.active = False
            target.close()
        except Exception:
            pass
        return default_value
    sys.stdout = restore(sys.stdout, sys.__stdout__)
    sys.stderr = restore(sys.stderr, sys.__stderr__)

