def post_has_mime_parts(request, parts):
    """Validate that a MMP POST contains all required sections.

    :param request: Django Request
    :param parts: [(part_type, part_name), ...]
    :return: None or raises exception.

    Where information is stored in the request:
    part_type header: request.META['HTTP_<UPPER CASE NAME>']
    part_type file: request.FILES['<name>']
    part_type field: request.POST['<name>']"""
    missing = []
    for part_type, part_name in parts:
        if part_type == 'header':
            if 'HTTP_' + part_name.upper() not in request.META:
                missing.append('{}: {}'.format(part_type, part_name))
        elif part_type == 'file':
            if part_name not in list(request.FILES.keys()):
                missing.append('{}: {}'.format(part_type, part_name))
        elif part_type == 'field':
            if part_name not in list(request.POST.keys()):
                missing.append('{}: {}'.format(part_type, part_name))
        else:
            raise d1_common.types.exceptions.ServiceFailure(0, 'Invalid part_type. part_type="{}"'.format(part_type))
    if len(missing) > 0:
        raise d1_common.types.exceptions.InvalidRequest(0, 'Missing part(s) in MIME Multipart document. missing="{}"'.format(', '.join(missing)))

def _smeft_evolve(C_in, scale_in, scale_out, newphys=True, **kwargs):
    """Axuliary function used in `smeft_evolve` and `smeft_evolve_continuous`"""
    def fun(t0, y):
        return beta.beta_array(C=C_array2dict(y.view(complex)), newphys=newphys).view(float) / (16 * pi ** 2)
    y0 = C_dict2array(C_in).view(float)
    sol = solve_ivp(fun=fun, t_span=(log(scale_in), log(scale_out)), y0=y0, **kwargs)
    return sol

def smeft_evolve(C_in, scale_in, scale_out, newphys=True, **kwargs):
    """Solve the SMEFT RGEs by numeric integration.

    Input C_in and output C_out are dictionaries of arrays."""
    sol = _smeft_evolve(C_in, scale_in, scale_out, newphys=newphys, **kwargs)
    return C_array2dict(sol.y[:, -1].view(complex))

def _get_and_assert_slice_param(url_dict, param_name, default_int):
    """Return ``param_str`` converted to an int.

    If str cannot be converted to int or int is not zero or positive, raise
    InvalidRequest."""
    param_str = url_dict['query'].get(param_name, default_int)
    try:
        n = int(param_str)
    except ValueError:
        raise d1_common.types.exceptions.InvalidRequest(0, 'Slice parameter is not a valid integer. {}="{}"'.format(param_name, param_str))
    if n < 0:
        raise d1_common.types.exceptions.InvalidRequest(0, 'Slice parameter cannot be a negative number. {}="{}"'.format(param_name, param_str))
    return n

def _assert_valid_start(start_int, count_int, total_int):
    """Assert that the number of objects visible to the active subject is higher than
    the requested start position for the slice.

    This ensures that it's possible to create a valid slice."""
    if total_int and start_int >= total_int:
        raise d1_common.types.exceptions.InvalidRequest(0, 'Requested a non-existing slice. start={} count={} total={}'.format(start_int, count_int, total_int))

def _add_fallback_slice_filter(query, start_int, count_int, total_int):
    """Create a slice of a query based on request start and count parameters.

    This adds `OFFSET <start> LIMIT <count>` to the SQL query, which causes slicing to
    run very slowly on large result sets."""
    logging.debug('Adding fallback slice filter. start={} count={} total={} '.format(start_int, count_int, total_int))
    if not count_int:
        return query.none()
    else:
        return query[start_int:start_int + count_int]

def _cache_get_last_in_slice(url_dict, start_int, total_int, authn_subj_list):
    """Return None if cache entry does not exist."""
    key_str = _gen_cache_key_for_slice(url_dict, start_int, total_int, authn_subj_list)
    try:
        last_ts_tup = django.core.cache.cache.get(key_str)
    except KeyError:
        last_ts_tup = None
    logging.debug('Cache get. key="{}" -> last_ts_tup={}'.format(key_str, last_ts_tup))
    return last_ts_tup

