def _is_ignored_read_event(request):
    """Return True if this read event was generated by an automated process, as
    indicated by the user configurable LOG_IGNORE* settings.

    See settings_site.py for description and rationale for the settings."""
    if django.conf.settings.LOG_IGNORE_TRUSTED_SUBJECT and d1_gmn.app.auth.is_trusted_subject(request):
        return True
    if django.conf.settings.LOG_IGNORE_NODE_SUBJECT and d1_gmn.app.auth.is_client_side_cert_subject(request):
        return True
    if _has_regex_match(request.META['REMOTE_ADDR'], django.conf.settings.LOG_IGNORE_IP_ADDRESS):
        return True
    if _has_regex_match(request.META.get('HTTP_USER_AGENT', '<not provided>'), django.conf.settings.LOG_IGNORE_USER_AGENT):
        return True
    if _has_regex_match(request.primary_subject_str, django.conf.settings.LOG_IGNORE_SUBJECT):
        return True
    return False

