def pyxb_to_dict(node_list_pyxb):
    """Returns:
       dict : Representation of ``node_list_pyxb``, keyed on the Node identifier
       (``urn:node:*``).

    Example::

      {
        u'urn:node:ARCTIC': {
          'base_url': u'https://arcticdata.io/metacat/d1/mn',
          'description': u'The US National Science Foundation...',
          'name': u'Arctic Data Center',
          'ping': None,
          'replicate': 0,
          'state': u'up',
          'synchronize': 1,
          'type': u'mn'
        },
        u'urn:node:BCODMO': {
          'base_url': u'https://www.bco-dmo.org/d1/mn',
          'description': u'Biological and Chemical Oceanography Data...',
          'name': u'Biological and Chemical Oceanography Data...',
          'ping': None,
          'replicate': 0,
          'state': u'up',
          'synchronize': 1,
          'type': u'mn'
        },
      }"""
    f_dict = {}
    for f_pyxb in sorted(node_list_pyxb.node, key=lambda x: x.identifier.value()):
        f_dict[f_pyxb.identifier.value()] = {'name': f_pyxb.name, 'description': f_pyxb.description, 'base_url': f_pyxb.baseURL, 'ping': f_pyxb.ping, 'replicate': f_pyxb.replicate, 'synchronize': f_pyxb.synchronize, 'type': f_pyxb.type, 'state': f_pyxb.state}
    return f_dict

def _process_permission(perm):
    """Rebuild indexes affected by the given permission."""
    codename = perm.permission.codename
    if not codename.startswith('view') and (not codename.startswith('owner')):
        return
    index_builder.build(perm.content_object)

def normalize(body_part_tup):
    """Normalize a tuple of BodyPart objects to a string.

    Normalization is done by sorting the body_parts by the Content- Disposition headers,
    which is typically on the form, ``form-data; name="name_of_part``."""
    return '\n\n'.join(['{}\n\n{}'.format(str(p.headers[b'Content-Disposition'], p.encoding), p.text) for p in sorted(body_part_tup, key=lambda p: p.headers[b'Content-Disposition'])])

