def _trim_tree(state):
    """Trim empty leaf nodes from the tree.

    - To simplify the tree conversion, empty nodes are added before it is known if they
      will contain items that connect back to the authenticated subject. If there are
      no connections, the nodes remain empty, which causes them to be removed here.

    - Removing a leaf node may cause the parent to become a new empty leaf node, so the
      function is repeated until there are no more empty leaf nodes."""
    for n in list(state.tree.leaf_node_gen):
        if n.type_str == TYPE_NODE_TAG:
            n.parent.child_list.remove(n)
            return _trim_tree(state)

def get_permissible_wcs(classname, f):
    """For some classes (in particular $\\Delta F=1$), only a subset of Wilson
    coefficients exist in WET-3 and WET-4. Therefore, depending on the number
    of flavours `f`, the dimensionality of the ADM has to be reduced."""
    classes = ['cu', 'db', 'sb', 'sd', 'mue', 'mutau', 'taue', 'dF0']
    if classname not in classes or f == 5:
        return 'all'
    if f not in [3, 4]:
        raise ValueError('f must be 3, 4, or 5.')
    if classname == 'dF0':
        sector = 'dF=0'
    else:
        sector = classname
    perm_keys = wcxf.Basis['WET-{}'.format(f), 'JMS'].sectors[sector].keys()
    all_keys = coeffs[sector]
    return [i for i, c in enumerate(all_keys) if c in perm_keys]

def getUs(classname, eta_s, f, alpha_s, alpha_e, m_u, m_d, m_s, m_c, m_b, m_e, m_mu, m_tau):
    """Get the QCD evolution matrix."""
    w, v = admeig(classname, f, m_u, m_d, m_s, m_c, m_b, m_e, m_mu, m_tau)
    b0s = 11 - 2 * f / 3
    a = w / (2 * b0s)
    return v @ np.diag(eta_s ** a) @ np.linalg.inv(v)

def getUe(classname, eta_s, f, alpha_s, alpha_e, m_u, m_d, m_s, m_c, m_b, m_e, m_mu, m_tau):
    """Get the QCD evolution matrix."""
    args = (f, m_u, m_d, m_s, m_c, m_b, m_e, m_mu, m_tau)
    A = getattr(adm, 'adm_e_' + classname)(*args)
    perm_keys = get_permissible_wcs(classname, f)
    if perm_keys != 'all':
        A = A[perm_keys][:, perm_keys]
    w, v = admeig(classname, *args)
    b0s = 11 - 2 * f / 3
    a = w / (2 * b0s)
    K = np.linalg.inv(v) @ A.T @ v
    for i in range(K.shape[0]):
        for j in range(K.shape[1]):
            if a[i] - a[j] != 1:
                K[i, j] *= (eta_s ** (a[j] + 1) - eta_s ** a[i]) / (a[i] - a[j] - 1)
            else:
                K[i, j] *= eta_s ** a[i] * log(1 / eta_s)
    return -alpha_e / (2 * b0s * alpha_s) * v @ K @ np.linalg.inv(v)

def deserialize_pem(cert_pem):
    """Deserialize PEM (Base64) encoded X.509 v3 certificate.

    Args:
      cert_pem: str or bytes
        PEM (Base64) encoded X.509 v3 certificate

    Returns:
      cert_obj: cryptography.Certificate"""
    if isinstance(cert_pem, str):
        cert_pem = cert_pem.encode('utf-8')
    return cryptography.x509.load_pem_x509_certificate(data=cert_pem, backend=cryptography.hazmat.backends.default_backend())

def generate_private_key(key_size=2048):
    """Generate a private key"""
    return cryptography.hazmat.primitives.asymmetric.rsa.generate_private_key(public_exponent=65537, key_size=key_size, backend=cryptography.hazmat.backends.default_backend())

def load_csr(pem_path):
    """Load CSR from PEM encoded file"""
    with open(pem_path, 'rb') as f:
        return cryptography.x509.load_pem_x509_csr(data=f.read(), backend=cryptography.hazmat.backends.default_backend())

def load_private_key(pem_path, passphrase_bytes=None):
    """Load private key from PEM encoded file"""
    with open(pem_path, 'rb') as f:
        return cryptography.hazmat.primitives.serialization.load_pem_private_key(data=f.read(), password=passphrase_bytes, backend=cryptography.hazmat.backends.default_backend())

def get_extension_by_name(cert_obj, extension_name):
    """Get a standard certificate extension by attribute name.

    Args:
      cert_obj: cryptography.Certificate
        Certificate containing a standard extension.

      extension_name : str
        Extension name. E.g., 'SUBJECT_DIRECTORY_ATTRIBUTES'.

    Returns:
      Cryptography.Extension"""
    try:
        return cert_obj.extensions.get_extension_for_oid(getattr(cryptography.x509.oid.ExtensionOID, extension_name))
    except cryptography.x509.ExtensionNotFound:
        pass

def _JMS_to_Bern_I(C, qq):
    """From JMS to BernI basis (= traditional SUSY basis in this case)
    for $\\Delta F=2$ operators.
    `qq` should be 'sb', 'db', 'ds' or 'cu'"""
    if qq in ['sb', 'db', 'ds']:
        dd = 'dd'
        ij = tuple((dflav[q] for q in qq))
    elif qq == 'cu':
        dd = 'uu'
        ij = tuple((uflav[q] for q in qq))
    else:
        raise ValueError('not in Bern_I: '.format(qq))
    ji = (ij[1], ij[0])
    d = {'1' + 2 * qq: C['V{}LL'.format(dd)][ij + ij], '2' + 2 * qq: C['S1{}RR'.format(dd)][ji + ji].conj() - C['S8{}RR'.format(dd)][ji + ji].conj() / (2 * Nc), '3' + 2 * qq: C['S8{}RR'.format(dd)][ji + ji].conj() / 2, '4' + 2 * qq: -C['V8{}LR'.format(dd)][ij + ij], '5' + 2 * qq: -2 * C['V1{}LR'.format(dd)][ij + ij] + C['V8{}LR'.format(dd)][ij + ij] / Nc, '1p' + 2 * qq: C['V{}RR'.format(dd)][ij + ij], '2p' + 2 * qq: C['S1{}RR'.format(dd)][ij + ij] - C['S8{}RR'.format(dd)][ij + ij] / (2 * Nc), '3p' + 2 * qq: C['S8{}RR'.format(dd)][ij + ij] / 2}
    return d

def _Bern_to_JMS_I(C, qq):
    """From Bern to JMS basis for $\\Delta F=2$ operators.
    `qq` should be 'sb', 'db', 'ds' or 'cu'"""
    if qq in ['sb', 'db', 'ds']:
        dd = 'dd'
        ij = '{}{}'.format(dflav[qq[0]] + 1, dflav[qq[1]] + 1)
    elif qq == 'cu':
        dd = 'uu'
        ij = '{}{}'.format(uflav[qq[0]] + 1, uflav[qq[1]] + 1)
    else:
        raise ValueError('not in Bern_I: '.format(qq))
    ji = ij[1] + ij[0]
    d = {'V{}LL_{}{}'.format(dd, ij, ij): C['1' + 2 * qq], 'S1{}RR_{}{}'.format(dd, ji, ji): C['2' + 2 * qq].conjugate() + C['3' + 2 * qq].conjugate() / 3, 'S8{}RR_{}{}'.format(dd, ji, ji): 2 * C['3' + 2 * qq].conjugate(), 'V1{}LR_{}{}'.format(dd, ij, ij): -C['4' + 2 * qq] / 6 - C['5' + 2 * qq] / 2, 'V8{}LR_{}{}'.format(dd, ij, ij): -C['4' + 2 * qq], 'V{}RR_{}{}'.format(dd, ij, ij): C['1p' + 2 * qq], 'S1{}RR_{}{}'.format(dd, ij, ij): C['2p' + 2 * qq] + C['3p' + 2 * qq] / 3, 'S8{}RR_{}{}'.format(dd, ij, ij): 2 * C['3p' + 2 * qq]}
    if qq == 'cu':
        for VXY in ['VuuRR', 'V1uuLR', 'V8uuLR', 'VuuLL']:
            d[VXY + '_1212'] = d.pop(VXY + '_2121').conjugate()
    return d

def _BernI_to_Flavio_I(C, qq):
    """From BernI to FlavioI basis for $\\Delta F=2$ operators.
    `qq` should be 'sb', 'db', 'ds' or 'uc'"""
    qqf = qq[::-1]
    if qq in ['sb', 'db', 'ds', 'cu']:
        return {'CVLL_' + 2 * qqf: C['1' + 2 * qq], 'CSLL_' + 2 * qqf: C['2' + 2 * qq] - 1 / 2 * C['3' + 2 * qq], 'CTLL_' + 2 * qqf: -1 / 8 * C['3' + 2 * qq], 'CVLR_' + 2 * qqf: -1 / 2 * C['5' + 2 * qq], 'CVRR_' + 2 * qqf: C['1p' + 2 * qq], 'CSRR_' + 2 * qqf: C['2p' + 2 * qq] - 1 / 2 * C['3p' + 2 * qq], 'CTRR_' + 2 * qqf: -1 / 8 * C['3p' + 2 * qq], 'CSLR_' + 2 * qqf: C['4' + 2 * qq]}
    else:
        raise ValueError('not in Flavio_I: '.format(qq))

def _FlavioI_to_Bern_I(C, qq):
    """From FlavioI to BernI basis for $\\Delta F=2$ operators.
    `qq` should be 'sb', 'db', 'ds' or 'uc'"""
    qqb = qq[::-1]
    if qq in ['bs', 'bd', 'sd', 'uc']:
        return {'1' + 2 * qqb: C['CVLL_' + 2 * qq], '2' + 2 * qqb: C['CSLL_' + 2 * qq] - 4 * C['CTLL_' + 2 * qq], '3' + 2 * qqb: -8 * C['CTLL_' + 2 * qq], '4' + 2 * qqb: C['CSLR_' + 2 * qq], '5' + 2 * qqb: -2 * C['CVLR_' + 2 * qq], '1p' + 2 * qqb: C['CVRR_' + 2 * qq], '2p' + 2 * qqb: C['CSRR_' + 2 * qq] - 4 * C['CTRR_' + 2 * qq], '3p' + 2 * qqb: -8 * C['CTRR_' + 2 * qq]}
    else:
        raise ValueError('not in Bern_I: '.format(qq))

def _BernI_to_FormFlavor_I(C, qq):
    """From BernI to FormFlavorI basis for $\\Delta F=2$ operators.
    `qq` should be 'sb', 'db', 'ds' or 'uc'"""
    qqf = qq[::-1]
    if qq in ['sb', 'db', 'ds']:
        return {'CVLL_' + 2 * qqf: C['1' + 2 * qq], 'CSLL_' + 2 * qqf: C['2' + 2 * qq] + 1 / 2 * C['3' + 2 * qq], 'CTLL_' + 2 * qqf: -1 / 8 * C['3' + 2 * qq], 'CVLR_' + 2 * qqf: -1 / 2 * C['5' + 2 * qq], 'CVRR_' + 2 * qqf: C['1p' + 2 * qq], 'CSRR_' + 2 * qqf: C['2p' + 2 * qq] + 1 / 2 * C['3p' + 2 * qq], 'CTRR_' + 2 * qqf: -1 / 8 * C['3p' + 2 * qq], 'CSLR_' + 2 * qqf: C['4' + 2 * qq]}
    elif qq == 'cu':
        return {'CVLL_' + 2 * qq: C['1' + 2 * qq].conjugate(), 'CSLL_' + 2 * qq: C['2' + 2 * qq] + 1 / 2 * C['3' + 2 * qq].conjugate(), 'CTLL_' + 2 * qq: -1 / 8 * C['3' + 2 * qq].conjugate(), 'CVLR_' + 2 * qq: -1 / 2 * C['5' + 2 * qq].conjugate(), 'CVRR_' + 2 * qq: C['1p' + 2 * qq].conjugate(), 'CSRR_' + 2 * qq: C['2p' + 2 * qq].conjugate() + 1 / 2 * C['3p' + 2 * qq].conjugate(), 'CTRR_' + 2 * qq: -1 / 8 * C['3p' + 2 * qq], 'CSLR_' + 2 * qq: C['4' + 2 * qq].conjugate()}
    else:
        raise ValueError('{} not in FormFlavor_I'.format(qq))

def Fierz_to_JMS_lep(C, ddll):
    """From Fierz to semileptonic JMS basis for Class V.
    `ddll` should be of the form 'sbl_enu_tau', 'dbl_munu_e' etc."""
    if ddll[:2] == 'uc':
        s = str(uflav[ddll[0]] + 1)
        b = str(uflav[ddll[1]] + 1)
        q = 'u'
    else:
        s = str(dflav[ddll[0]] + 1)
        b = str(dflav[ddll[1]] + 1)
        q = 'd'
    l = str(lflav[ddll[4:ddll.find('n')]] + 1)
    lp = str(lflav[ddll[ddll.find('_', 5) + 1:len(ddll)]] + 1)
    ind = ddll.replace('l_', '').replace('nu_', '')
    d = {'Ve' + q + 'LL' + '_' + l + lp + s + b: -C['F' + ind + '10'] + C['F' + ind + '9'], 'V' + q + 'eLR' + '_' + s + b + l + lp: C['F' + ind + '10'] + C['F' + ind + '9'], 'Se' + q + 'RR' + '_' + l + lp + s + b: C['F' + ind + 'P'] + C['F' + ind + 'S'], 'Se' + q + 'RL' + '_' + lp + l + b + s: -C['F' + ind + 'P'].conjugate() + C['F' + ind + 'S'].conjugate(), 'Te' + q + 'RR' + '_' + lp + l + b + s: C['F' + ind + 'T'].conjugate() - C['F' + ind + 'T5'].conjugate(), 'Te' + q + 'RR' + '_' + l + lp + s + b: C['F' + ind + 'T'] + C['F' + ind + 'T5'], 'Ve' + q + 'LR' + '_' + l + lp + s + b: -C['F' + ind + '10p'] + C['F' + ind + '9p'], 'Ve' + q + 'RR' + '_' + l + lp + s + b: C['F' + ind + '10p'] + C['F' + ind + '9p'], 'Se' + q + 'RL' + '_' + l + lp + s + b: C['F' + ind + 'Pp'] + C['F' + ind + 'Sp'], 'Se' + q + 'RR' + '_' + lp + l + b + s: -C['F' + ind + 'Pp'].conjugate() + C['F' + ind + 'Sp'].conjugate()}
    return symmetrize_JMS_dict(d)

def Fierz_to_JMS_nunu(C, ddll):
    """From Fierz to semileptonic JMS basis for Class V.
    `ddll` should be of the form 'sbl_enu_tau', 'dbl_munu_e' etc."""
    s = str(dflav[ddll[0]] + 1)
    b = str(dflav[ddll[1]] + 1)
    l = str(lflav[ddll[4:ddll.find('n')]] + 1)
    lp = str(lflav[ddll[ddll.find('_', 5) + 1:len(ddll)]] + 1)
    ind = ddll.replace('l_', '').replace('nu_', '')
    d = {'VnudLL' + '_' + l + lp + s + b: C['F' + ind + 'nu'], 'VnudLR' + '_' + l + lp + s + b: C['F' + ind + 'nup']}
    return symmetrize_JMS_dict(d)

def Bern_to_Fierz_lep(C, ddll):
    """From semileptonic Bern basis to Fierz semileptonic basis for Class V.
    C should be the corresponding leptonic Fierz basis and
    `ddll` should be of the form 'sbl_enu_tau', 'dbl_munu_e' etc."""
    ind = ddll.replace('l_', '').replace('nu_', '')
    return {'F' + ind + '9': C['1' + ind] + 10 * C['3' + ind], 'F' + ind + '10': -6 * C['3' + ind], 'F' + ind + 'S': C['5' + ind] + 40 * C['9' + ind], 'F' + ind + 'P': 24 * C['9' + ind], 'F' + ind + 'T': C['7' + ind] / 2 + C['7p' + ind] / 2 - 8 * C['9' + ind] - 8 * C['9p' + ind], 'F' + ind + 'T5': C['7' + ind] / 2 - C['7p' + ind] / 2 - 8 * C['9' + ind] + 8 * C['9p' + ind], 'F' + ind + '9p': C['1p' + ind] + 10 * C['3p' + ind], 'F' + ind + '10p': 6 * C['3p' + ind], 'F' + ind + 'Sp': C['5p' + ind] + 40 * C['9p' + ind], 'F' + ind + 'Pp': -24 * C['9p' + ind]}

def Bern_to_Fierz_nunu(C, ddll):
    """From semileptonic Bern basis to Fierz semileptonic basis for Class V.
    C should be the corresponding leptonic Fierz basis and
    `ddll` should be of the form 'sbl_enu_tau', 'dbl_munu_e' etc."""
    ind = ddll.replace('l_', '').replace('nu_', '')
    return {'F' + ind + 'nu': C['nu1' + ind], 'F' + ind + 'nup': C['nu1p' + ind]}

def Flavio_to_Fierz_nunu(C, ddll, parameters, norm_gf=True):
    """From  Flavio semileptonic basis to semileptonic Fierz basis for Class V.
    C should be the corresponding leptonic Fierz basis and
    `ddll` should be of the form 'sbl_enu_tau', 'dbl_munu_e' etc."""
    p = parameters
    V = ckmutil.ckm.ckm_tree(p['Vus'], p['Vub'], p['Vcb'], p['delta'])
    if ddll[:2] == 'sb':
        xi = V[2, 2] * V[2, 1].conj()
    elif ddll[:2] == 'db':
        xi = V[2, 2] * V[2, 0].conj()
    elif ddll[:2] == 'ds':
        xi = V[2, 1] * V[2, 0].conj()
    else:
        raise ValueError('Unexpected flavours: {}'.format(ddll[:2]))
    q1, q2 = ddll[:2]
    l1 = ddll[4:ddll.find('n')]
    l2 = ddll[ddll.find('_', 5) + 1:]
    ind = q1 + q2 + l1 + l2
    indnu = q2 + q1 + 'nu' + l2 + 'nu' + l1
    e = sqrt(4 * pi * parameters['alpha_e'])
    dic = {'F' + ind + 'nu': C['CL_' + indnu] / (8 * pi ** 2 / e ** 2), 'F' + ind + 'nup': C['CR_' + indnu] / (8 * pi ** 2 / e ** 2)}
    if norm_gf:
        prefactor = sqrt(2) / p['GF'] / xi / 4
    else:
        prefactor = 1 / xi
    return {k: v / prefactor for k, v in dic.items()}

def JMS_to_Fierz_chrom(C, qq):
    """From JMS to chromomagnetic Fierz basis for Class V.
    qq should be of the form 'sb', 'ds' etc."""
    if qq[0] in dflav:
        s = dflav[qq[0]]
        b = dflav[qq[1]]
        return {'F7gamma' + qq: C['dgamma'][s, b], 'F8g' + qq: C['dG'][s, b], 'F7pgamma' + qq: C['dgamma'][b, s].conj(), 'F8pg' + qq: C['dG'][b, s].conj()}
    else:
        u = uflav[qq[0]]
        c = uflav[qq[1]]
        return {'F7gamma' + qq: C['ugamma'][u, c], 'F8g' + qq: C['uG'][u, c], 'F7pgamma' + qq: C['ugamma'][c, u].conj(), 'F8pg' + qq: C['uG'][c, u].conj()}

def Fierz_to_JMS_chrom(C, qq):
    """From chromomagnetic Fierz to JMS basis for Class V.
    qq should be of the form 'sb', 'ds' etc."""
    if qq[0] in dflav:
        s = dflav[qq[0]] + 1
        b = dflav[qq[1]] + 1
        return {'dgamma_{}{}'.format(s, b): C['F7gamma' + qq], 'dG_{}{}'.format(s, b): C['F8g' + qq], 'dgamma_{}{}'.format(b, s): C['F7pgamma' + qq].conjugate(), 'dG_{}{}'.format(b, s): C['F8pg' + qq].conjugate()}
    else:
        u = uflav[qq[0]] + 1
        c = uflav[qq[1]] + 1
        return {'ugamma_{}{}'.format(u, c): C['F7gamma' + qq], 'uG_{}{}'.format(u, c): C['F8g' + qq], 'ugamma_{}{}'.format(c, u): C['F7pgamma' + qq].conjugate(), 'uG_{}{}'.format(c, u): C['F8pg' + qq].conjugate()}

def Fierz_to_Bern_chrom(C, dd, parameters):
    """From Fierz to chromomagnetic Bern basis for Class V.
    dd should be of the form 'sb', 'ds' etc."""
    e = sqrt(4 * pi * parameters['alpha_e'])
    gs = sqrt(4 * pi * parameters['alpha_s'])
    if dd == 'sb' or dd == 'db':
        mq = parameters['m_b']
    elif dd == 'ds':
        mq = parameters['m_s']
    else:
        KeyError('Not sure what to do with quark mass for flavour {}'.format(dd))
    return {'7gamma' + dd: gs ** 2 / e / mq * C['F7gamma' + dd], '8g' + dd: gs / mq * C['F8g' + dd], '7pgamma' + dd: gs ** 2 / e / mq * C['F7pgamma' + dd], '8pg' + dd: gs / mq * C['F8pg' + dd]}

def Flavio_to_Fierz_chrom(C, qq, parameters):
    """From Flavio to chromomagnetic Fierz basis for Class V.
    qq should be of the form 'sb', 'db' etc."""
    p = parameters
    V = ckmutil.ckm.ckm_tree(p['Vus'], p['Vub'], p['Vcb'], p['delta'])
    if qq == 'sb':
        xi = V[2, 2] * V[2, 1].conj()
    elif qq == 'db':
        xi = V[2, 2] * V[2, 0].conj()
    elif qq == 'ds':
        xi = V[2, 1] * V[2, 0].conj()
    elif qq == 'uc':
        xi = V[1, 2].conj() * V[0, 2]
    else:
        raise ValueError('Unexpected flavours: {}'.format(qq))
    qqfl = qq[::-1]
    e = sqrt(4 * pi * parameters['alpha_e'])
    gs = sqrt(4 * pi * parameters['alpha_s'])
    if qq == 'sb' or qq == 'db':
        mq = parameters['m_b']
    elif qq == 'ds':
        mq = parameters['m_s']
    elif qq == 'uc':
        mq = parameters['m_c']
    else:
        KeyError('Not sure what to do with quark mass for flavour {}'.format(qq))
    dic = {'F7gamma' + qq: C['C7_' + qqfl] / (16 * pi ** 2 / e / mq), 'F8g' + qq: C['C8_' + qqfl] / (16 * pi ** 2 / gs / mq), 'F7pgamma' + qq: C['C7p_' + qqfl] / (16 * pi ** 2 / e / mq), 'F8pg' + qq: C['C8p_' + qqfl] / (16 * pi ** 2 / gs / mq)}
    prefactor = sqrt(2) / p['GF'] / xi / 4
    return {k: v / prefactor for k, v in dic.items()}

def JMS_to_FormFlavor_chrom(C, qq, parameters):
    """From JMS to chromomagnetic FormFlavor basis for Class V.
    qq should be of the form 'sb', 'ds', 'uu', mt (mu tau), em (e mu) etc."""
    e = sqrt(4 * pi * parameters['alpha_e'])
    gs = sqrt(4 * pi * parameters['alpha_s'])
    if qq[0] in dflav.keys():
        s = dflav[qq[0]]
        b = dflav[qq[1]]
        return {'CAR_' + qq: C['dgamma'][s, b] / e, 'CGR_' + qq: C['dG'][s, b] / gs, 'CAL_' + qq: C['dgamma'][b, s].conj() / e, 'CGL_' + qq: C['dG'][b, s].conj() / gs}
    if qq[0] in llflav.keys():
        l1 = llflav[qq[0]]
        l2 = llflav[qq[1]]
        return {'CAR_' + qq: C['egamma'][l1, l2] / e, 'CAL_' + qq: C['egamma'][l2, l1].conj() / gs}
    if qq[0] in uflav.keys():
        u = uflav[qq[0]]
        c = uflav[qq[1]]
        return {'CAR_' + qq: C['ugamma'][u, c] / e, 'CGR_' + qq: C['uG'][u, c] / gs, 'CAL_' + qq: C['ugamma'][c, u].conj() / e, 'CGL_' + qq: C['uG'][c, u].conj() / gs}
    else:
        return 'not in FormFlav_chrom'

def is_obsoletes_pid(pid):
    """Return True if ``pid`` is referenced in the obsoletes field of any object.

    This will return True even if the PID is in the obsoletes field of an object that
    does not exist on the local MN, such as replica that is in an incomplete chain."""
    return d1_gmn.app.models.ScienceObject.objects.filter(obsoletes__did=pid).exists()

def is_obsoleted_by_pid(pid):
    """Return True if ``pid`` is referenced in the obsoletedBy field of any object.

    This will return True even if the PID is in the obsoletes field of an object that
    does not exist on the local MN, such as replica that is in an incomplete chain."""
    return d1_gmn.app.models.ScienceObject.objects.filter(obsoleted_by__did=pid).exists()

def _set_chain_sid(chain_model, sid):
    """Set or update SID for chain.

    If the chain already has a SID, ``sid`` must either be None or match the existing
    SID."""
    if not sid:
        return
    if chain_model.sid and chain_model.sid.did != sid:
        raise d1_common.types.exceptions.ServiceFailure(0, 'Attempted to modify existing SID. existing_sid="{}", new_sid="{}"'.format(chain_model.sid.did, sid))
    chain_model.sid = d1_gmn.app.did.get_or_create_did(sid)
    chain_model.save()

def _get_chain_by_pid(pid):
    """Find chain by pid.

    Return None if not found."""
    try:
        return d1_gmn.app.models.ChainMember.objects.get(pid__did=pid).chain
    except d1_gmn.app.models.ChainMember.DoesNotExist:
        pass

def _get_chain_by_sid(sid):
    """Return None if not found."""
    try:
        return d1_gmn.app.models.Chain.objects.get(sid__did=sid)
    except d1_gmn.app.models.Chain.DoesNotExist:
        pass

def populate_entity_type(apps, schema_editor):
    """Populate entity type from attached descriptor schema."""
    Entity = apps.get_model('flow', 'Entity')
    for entity in Entity.objects.all():
        if entity.descriptor_schema is not None:
            entity.type = entity.descriptor_schema.slug
            entity.save()

def are_equal_elements(a_el, b_el):
    """Normalize and compare ElementTrees for equality.

    Args:
      a_el: ElementTree
      b_el: ElementTree
        ElementTrees to compare for equality.

    Returns:
      bool: ``True`` if the ElementTrees are semantically equivalent."""
    if a_el.tagName != b_el.tagName:
        return False
    if sorted(a_el.attributes.items()) != sorted(b_el.attributes.items()):
        return False
    if len(a_el.childNodes) != len(b_el.childNodes):
        return False
    for a_child_el, b_child_el in zip(a_el.childNodes, b_el.childNodes):
        if a_child_el.nodeType != b_child_el.nodeType:
            return False
        if a_child_el.nodeType == a_child_el.TEXT_NODE and a_child_el.data != b_child_el.data:
            return False
        if a_child_el.nodeType == a_child_el.ELEMENT_NODE and (not are_equal_elements(a_child_el, b_child_el)):
            return False
    return True

def resolwe_exception_handler(exc, context):
    """Handle exceptions raised in API and make them nicer.

    To enable this, you have to add it to the settings:

        .. code:: python

            REST_FRAMEWORK = {
                'EXCEPTION_HANDLER': 'resolwe.flow.utils.exceptions.resolwe_exception_handler',
            }"""
    response = exception_handler(exc, context)
    if isinstance(exc, ValidationError):
        if response is None:
            response = Response({})
        response.status_code = 400
        response.data['error'] = exc.message
    return response

def validate_and_decode(jwt_bu64, cert_obj):
    """Example for validating the signature of a JWT using only the cryptography
    library.

    Note that this does NOT validate the claims in the claim set."""
    public_key = cert_obj.public_key()
    message = '.'.join(d1_common.cert.jwt.get_bu64_tup(jwt_bu64)[:2])
    signature = d1_common.cert.jwt.get_jwt_tup(jwt_bu64)[2]
    try:
        public_key.verify(signature, message, cryptography.hazmat.primitives.asymmetric.padding.PKCS1v15(), cryptography.hazmat.primitives.hashes.SHA256())
    except cryptography.exceptions.InvalidSignature as e:
        raise Exception('Signature is invalid. error="{}"'.format(str(e)))
    return d1_common.cert.jwt.get_jwt_dict(jwt_bu64)

def find_valid_combinations(cert_file_name_list, jwt_file_name_list):
    """Given a list of cert and JWT file names, print a list showing each combination
    along with indicators for combinations where the JWT signature was successfully
    validated with the cert."""
    for cert_file_name in cert_file_name_list:
        cert_pem = ''
        cert_obj = d1_common.cert.x509.deserialize_pem(cert_pem)
        for jwt_file_name in jwt_file_name_list:
            jwt_bu64 = ''
            is_ok = False
            try:
                d1_common.cert.jwt.validate_and_decode(jwt_bu64, cert_obj)
            except d1_common.cert.jwt.JwtException as e:
                logging.info('Invalid. msg="{}"'.format(str(e)))
            else:
                is_ok = True
            logging.info('{} {} {}'.format('***' if is_ok else '   ', cert_file_name, jwt_file_name))

def parseUrl(url):
    """Return a dict containing scheme, netloc, url, params, query, fragment keys.

    query is a dict where the values are always lists. If the query key appears only
    once in the URL, the list will have a single value."""
    scheme, netloc, url, params, query, fragment = urllib.parse.urlparse(url)
    query_dict = {k: sorted(v) if len(v) > 1 else v[0] for k, v in list(urllib.parse.parse_qs(query).items())}
    return {'scheme': scheme, 'netloc': netloc, 'url': url, 'params': params, 'query': query_dict, 'fragment': fragment}

def encodePathElement(element):
    """Encode a URL path element according to RFC3986."""
    return urllib.parse.quote(element.encode('utf-8') if isinstance(element, str) else str(element) if isinstance(element, int) else element, safe=d1_common.const.URL_PATHELEMENT_SAFE_CHARS)

def encodeQueryElement(element):
    """Encode a URL query element according to RFC3986."""
    return urllib.parse.quote(element.encode('utf-8') if isinstance(element, str) else str(element) if isinstance(element, int) else element, safe=d1_common.const.URL_QUERYELEMENT_SAFE_CHARS)

def makeCNBaseURL(url):
    """Attempt to create a valid CN BaseURL when one or more sections of the URL are
    missing."""
    o = urllib.parse.urlparse(url, scheme=d1_common.const.DEFAULT_CN_PROTOCOL)
    if o.netloc and o.path:
        netloc = o.netloc
        path = o.path
    elif o.netloc:
        netloc = o.netloc
        path = d1_common.const.DEFAULT_CN_PATH
    elif o.path:
        s = o.path.split('/', 1)
        netloc = s[0]
        if len(s) == 1:
            path = d1_common.const.DEFAULT_CN_PATH
        else:
            path = s[1]
    else:
        netloc = d1_common.const.DEFAULT_CN_HOST
        path = d1_common.const.DEFAULT_CN_PATH
    return urllib.parse.urlunparse((o.scheme, netloc, path, o.params, o.query, o.fragment))

def makeMNBaseURL(url):
    """Attempt to create a valid MN BaseURL when one or more sections of the URL are
    missing."""
    o = urllib.parse.urlparse(url, scheme=d1_common.const.DEFAULT_MN_PROTOCOL)
    if o.netloc and o.path:
        netloc = o.netloc
        path = o.path
    elif o.netloc:
        netloc = o.netloc
        path = d1_common.const.DEFAULT_MN_PATH
    elif o.path:
        s = o.path.split('/', 1)
        netloc = s[0]
        if len(s) == 1:
            path = d1_common.const.DEFAULT_MN_PATH
        else:
            path = s[1]
    else:
        netloc = d1_common.const.DEFAULT_MN_HOST
        path = d1_common.const.DEFAULT_MN_PATH
    return urllib.parse.urlunparse((o.scheme, netloc, path, o.params, o.query, o.fragment))

def main():
    """Run the program."""
    args = parse_arguments()
    ext = os.path.splitext(args.input_file)[-1].lower()
    with gzip.open(args.output_file, mode='wt') as outfile:
        csvwriter = csv.writer(outfile, delimiter=str('\t'), lineterminator='\n')
        try:
            if ext in ('.tab', '.txt', '.tsv'):
                with open(args.input_file) as infile:
                    for line in infile:
                        outline = line.strip().split('\t')
                        csvwriter.writerow(outline)
            elif ext == '.csv':
                with open(args.input_file) as infile:
                    for line in infile:
                        outline = line.strip().split(',')
                        csvwriter.writerow(outline)
            elif ext in ('.xls', '.xlsx'):
                workbook = xlrd.open_workbook(args.input_file)
                worksheet = workbook.sheets()[0]
                for rownum in range(worksheet.nrows):
                    csvwriter.writerow(worksheet.row_values(rownum))
            else:
                print('{"proc.error":"File extension not recognized."}')
        except Exception:
            print('{"proc.error":"Corrupt or unrecognized file."}')
            raise

def apply_filter_list(func, obj):
    """Apply `func` to list or tuple `obj` element-wise and directly otherwise."""
    if isinstance(obj, (list, tuple)):
        return [func(item) for item in obj]
    return func(obj)

def _get_data_attr(data, attr):
    """Get data object field."""
    if isinstance(data, dict):
        data = data['__id']
    data_obj = Data.objects.get(id=data)
    return getattr(data_obj, attr)

def _get_hydrated_path(field):
    """Return HydratedPath object for file-type field."""
    if isinstance(field, str) and hasattr(field, 'file_name'):
        return field
    if isinstance(field, dict) and 'file' in field:
        hydrated_path = field['file']
    if not hasattr(hydrated_path, 'file_name'):
        raise TypeError('Filter argument must be a valid file-type field.')
    return hydrated_path

def get_url(field):
    """Return file's url based on base url set in settings."""
    hydrated_path = _get_hydrated_path(field)
    base_url = getattr(settings, 'RESOLWE_HOST_URL', 'localhost')
    return '{}/data/{}/{}'.format(base_url, hydrated_path.data_id, hydrated_path.file_name)

def descriptor(obj, path=''):
    """Return descriptor of given object.

    If ``path`` is specified, only the content on that path is
    returned."""
    if isinstance(obj, dict):
        desc = obj['__descriptor']
    else:
        desc = obj.descriptor
    resp = dict_dot(desc, path)
    if isinstance(resp, list) or isinstance(resp, dict):
        return json.dumps(resp)
    return resp

def post_error(request):
    """MNRead.synchronizationFailed(session, message)"""
    d1_gmn.app.views.assert_db.post_has_mime_parts(request, (('file', 'message'),))
    try:
        synchronization_failed = d1_gmn.app.views.util.deserialize(request.FILES['message'])
    except d1_common.types.exceptions.DataONEException as e:
        logging.error('Received notification of synchronization error from CN but was unable to deserialize the DataONE Exception passed by the CN. message="{}" error="{}"'.format(d1_gmn.app.views.util.read_utf8_xml(request.FILES['message']), str(e)))
    else:
        logging.error('Received notification of synchronization error from CN:\n{}'.format(str(synchronization_failed)))
    return d1_gmn.app.views.util.http_response_with_boolean_true_type()

def get_is_authorized(request, pid):
    """MNAuthorization.isAuthorized(did, action) -> Boolean."""
    if 'action' not in request.GET:
        raise d1_common.types.exceptions.InvalidRequest(0, 'Missing required parameter. required="action"')
    level = d1_gmn.app.auth.action_to_level(request.GET['action'])
    d1_gmn.app.auth.assert_allowed(request, level, pid)
    return d1_gmn.app.views.util.http_response_with_boolean_true_type()

