def format_currency(number, currency, format, locale=babel.numbers.LC_NUMERIC, force_frac=None, format_type='standard'):
    """Same as ``babel.numbers.format_currency``, but has ``force_frac``
    argument instead of ``currency_digits``.

    If the ``force_frac`` argument is given, the argument is passed down to
    ``pattern.apply``."""
    locale = babel.core.Locale.parse(locale)
    if format:
        pattern = babel.numbers.parse_pattern(format)
    else:
        try:
            pattern = locale.currency_formats[format_type]
        except KeyError:
            raise babel.numbers.UnknownCurrencyFormatError('%r is not a known currency format type' % format_type)
    if force_frac is None:
        fractions = babel.core.get_global('currency_fractions')
        try:
            digits = fractions[currency][0]
        except KeyError:
            digits = fractions['DEFAULT'][0]
        frac = (digits, digits)
    else:
        frac = force_frac
    return pattern.apply(number, locale, currency=currency, force_frac=frac)

def remove_symbol_from_dist(dist, index):
    """prob is a ndarray representing a probability distribution.
    index is a number between 0 and and the number of symbols ( len(prob)-1 )
    return the probability distribution if the element at 'index' was no longer available"""
    if type(dist) is not Distribution:
        raise TypeError('remove_symbol_from_dist got an object ot type {0}'.format(type(dist)))
    new_prob = dist.prob.copy()
    new_prob[index] = 0
    new_prob /= sum(new_prob)
    return Distribution(new_prob)

