def get_address(pk, main_net=True, prefix=None):
    """compute the nem-py address from the public one"""
    if isinstance(pk, str):
        pk = unhexlify(pk.encode())
    assert len(pk) == 32, 'PK is 32bytes {}'.format(len(pk))
    k = keccak_256(pk).digest()
    ripe = RIPEMD160.new(k).digest()
    if prefix is None:
        body = (b'h' if main_net else b'\x98') + ripe
    else:
        assert isinstance(prefix, bytes), 'Set prefix 1 bytes'
        body = prefix + ripe
    checksum = keccak_256(body).digest()[0:4]
    return b32encode(body + checksum).decode()

def entropy(data=None, prob=None, tol=1e-05):
    """given a probability distribution (prob) or an interable of symbols (data) compute and
    return its entropy

    inputs:
    ------
        data:       iterable of symbols

        prob:       iterable with probabilities

        tol:        if prob is given, 'entropy' checks that the sum is about 1.
                    It raises an error if abs(sum(prob)-1) >= tol"""
    if prob is None and data is None:
        raise ValueError("%s.entropy requires either 'prob' or 'data' to be defined" % __name__)
    if prob is not None and data is not None:
        raise ValueError("%s.entropy requires only 'prob' or 'data to be given but not both" % __name__)
    if prob is not None and (not isinstance(prob, np.ndarray)):
        raise TypeError("'entropy' in '%s' needs 'prob' to be an ndarray" % __name__)
    if prob is not None and abs(prob.sum() - 1) > tol:
        raise ValueError("parameter 'prob' in '%s.entropy' should sum to 1" % __name__)
    if data is not None:
        prob = symbols_to_prob(data).prob()
    logProb = np.log2(prob)
    logProb[logProb == -np.inf] = 0
    return -float(np.dot(prob, logProb))

def scalarmult_B(e):
    """Implements scalarmult(B, e) more efficiently."""
    e %= L
    P = IDENT
    for i in range(253):
        if e & 1:
            P = edwards_add(P=P, Q=Bpow[i])
        e //= 2
    assert e == 0, e
    return P

def recover(y):
    """given a value y, recover the preimage x"""
    p = (y * y - 1) * inverse(D * y * y + 1)
    x = powmod(p, (PRIME + 3) // 8, PRIME)
    if (x * x - p) % PRIME != 0:
        i = powmod(2, (PRIME - 1) // 4, PRIME)
        x = x * i % PRIME
    if x % 2 != 0:
        x = PRIME - x
    return x

def euc_to_python(hexstr):
    """Convert a EUC-CN (GB2312) hex to a Python unicode string."""
    hi = hexstr[0:2]
    lo = hexstr[2:4]
    gb_enc = b'\\x' + hi + b'\\x' + lo
    return gb_enc.decode('gb2312')

def ucn_to_unicode(ucn):
    """Convert a Unicode Universal Character Number (e.g. "U+4E00" or "4E00") to
    Python unicode (u'\\u4e00')"""
    if isinstance(ucn, string_types):
        ucn = ucn.strip('U+')
        if len(ucn) > int(4):
            char = b'\\U' + format(int(ucn, 16), '08x').encode('latin1')
            char = char.decode('unicode_escape')
        else:
            char = unichr(int(ucn, 16))
    else:
        char = unichr(ucn)
    assert isinstance(char, text_type)
    return char

def parse_var(var):
    """Returns a tuple consisting of a string and a tag, or None, if none is
    specified."""
    bits = var.split('<', 1)
    if len(bits) < 2:
        tag = None
    else:
        tag = bits[1]
    return (ucn_to_unicode(bits[0]), tag)

def session_request(session, url, **kwargs):
    """Do HTTP/S request and return response as a string."""
    try:
        response = session(url, **kwargs)
        response.raise_for_status()
        return response.text
    except requests.exceptions.HTTPError as errh:
        _LOGGER.debug('%s, %s', response, errh)
        raise_error(response.status_code)
    except requests.exceptions.ConnectionError as errc:
        _LOGGER.debug('%s', errc)
        raise RequestError('Connection error: {}'.format(errc))
    except requests.exceptions.Timeout as errt:
        _LOGGER.debug('%s', errt)
        raise RequestError('Timeout: {}'.format(errt))
    except requests.exceptions.RequestException as err:
        _LOGGER.debug('%s', err)
        raise RequestError('Unknown error: {}'.format(err))

def get_event_list(config):
    """Get a dict of supported events from device."""
    eventinstances = session_request(config.session.post, device_event_url.format(proto=config.web_proto, host=config.host, port=config.port), auth=config.session.auth, headers=headers, data=request_xml)
    raw_event_list = _prepare_event(eventinstances)
    event_list = {}
    for entry in MAP + METAMAP:
        instance = raw_event_list
        try:
            for item in sum(entry[MAP_BASE].values(), []):
                instance = instance[item]
        except KeyError:
            continue
        event_list[entry[MAP_TYPE]] = instance
    return event_list

def _prepare_event(eventinstances):
    """Converts event instances to a relevant dictionary."""
    import xml.etree.ElementTree as ET
    def parse_event(events):
        """Find all events inside of an topicset list.

        MessageInstance signals that subsequent children will
        contain source and data descriptions."""
        def clean_attrib(attrib={}):
            """Clean up child attributes by removing XML namespace."""
            attributes = {}
            for key, value in attrib.items():
                attributes[key.split('}')[-1]] = value
            return attributes
        description = {}
        for child in events:
            child_tag = child.tag.split('}')[-1]
            child_attrib = clean_attrib(child.attrib)
            if child_tag != 'MessageInstance':
                description[child_tag] = {**child_attrib, **parse_event(child)}
            elif child_tag == 'MessageInstance':
                description = {}
                for item in child:
                    tag = item.tag.split('}')[-1]
                    description[tag] = clean_attrib(item[0].attrib)
        return description
    root = ET.fromstring(eventinstances)
    return parse_event(root[0][0][0])

def get_codec(data):
    """Returns the codec used to encode the given data

    :param data: multibase encoded data
    :type data: str or bytes
    :return: the :py:obj:`multibase.Encoding` object for the data's codec
    :raises ValueError: if the codec is not supported"""
    try:
        key = ensure_bytes(data[:CODE_LENGTH], 'utf8')
        codec = ENCODINGS_LOOKUP[key]
    except KeyError:
        raise ValueError('Can not determine encoding for {}'.format(data))
    else:
