def _unwrap_result(action, result):
    """Unwrap a request response and return only the response data.

    :param str action: The action name
    :param result: The result of the action
    :type: result: list or dict
    :rtype: dict | None"""
    if not result:
        return
    elif action in {'DeleteItem', 'PutItem', 'UpdateItem'}:
        return _unwrap_delete_put_update_item(result)
    elif action == 'GetItem':
        return _unwrap_get_item(result)
    elif action == 'Query' or action == 'Scan':
        return _unwrap_query_scan(result)
    elif action == 'CreateTable':
        return _unwrap_create_table(result)
    elif action == 'DescribeTable':
        return _unwrap_describe_table(result)
    return result

def color(x, y):
    """triangles.

    Colors:
    - http://paletton.com/#uid=70l150klllletuehUpNoMgTsdcs shade 2"""
    if x - 4 > y - 4 and -(y - 4) <= x - 4:
        return '#CDB95B'
    elif x - 4 > y - 4 and -(y - 4) > x - 4:
        return '#CD845B'
    elif x - 4 <= y - 4 and -(y - 4) <= x - 4:
        return '#57488E'
    elif x - 4 <= y - 4 and -(y - 4) > x - 4:
        return '#3B8772'
    return 'black'

def on(f):
    """Decorator for action handlers.

    The action name is inferred from the function name.

    This also decorates the method with `tornado.gen.coroutine` so that
    `~tornado.concurrent.Future` can be yielded."""
    action = f.__name__
    f.action = action
    @wrapt.decorator
    @tornado.gen.coroutine
    def _execute(wrapped, instance, args, kwargs):
        return wrapped(*args, **kwargs)
    return _execute(f)

def on_action(action):
    """Decorator for action handlers.

    :param str action: explicit action name

    This also decorates the method with `tornado.gen.coroutine` so that
    `~tornado.concurrent.Future` can be yielded."""
    @wrapt.decorator
    @tornado.gen.coroutine
    def _execute(wrapped, instance, args, kwargs):
        return wrapped(*args, **kwargs)
    _execute.action = action
    return _execute

def norm_vec(vector):
    """Normalize the length of a vector to one"""
    assert len(vector) == 3
    v = np.array(vector)
    return v / np.sqrt(np.sum(v ** 2))

def check_git_unchanged(filename, yes=False):
    """Check git to avoid overwriting user changes."""
    if check_staged(filename):
        s = 'There are staged changes in {}, overwrite? [y/n] '.format(filename)
        if yes or input(s) in ('y', 'yes'):
            return
        else:
            raise RuntimeError('There are staged changes in {}, aborting.'.format(filename))
    if check_unstaged(filename):
        s = 'There are unstaged changes in {}, overwrite? [y/n] '.format(filename)
        if yes or input(s) in ('y', 'yes'):
            return
        else:
            raise RuntimeError('There are unstaged changes in {}, aborting.'.format(filename))

def check_staged(filename=None):
    """Check if there are 'changes to be committed' in the index."""
    retcode, _, stdout = git['diff-index', '--quiet', '--cached', 'HEAD', filename].run(retcode=None)
    if retcode == 1:
        return True
    elif retcode == 0:
        return False
    else:
        raise RuntimeError(stdout)

