def field_to_dict(fields):
    """Build dictionnary which dependancy for each field related to "root"

        fields = ["toto", "toto__tata", "titi__tutu"]
        dico = {
            "toto": {
                EMPTY_DICT,
                "tata": EMPTY_DICT
                },
            "titi" : {
                "tutu": EMPTY_DICT
            }
        }

    EMPTY_DICT is useful because we don't lose field
    without it dico["toto"] would only contains "tata"

    inspired from django.db.models.sql.add_select_related"""
    field_dict = {}
    for field in fields:
        d_tmp = field_dict
        for part in field.split(LOOKUP_SEP)[:-1]:
            d_tmp = d_tmp.setdefault(part, {})
        d_tmp = d_tmp.setdefault(field.split(LOOKUP_SEP)[-1], deepcopy(EMPTY_DICT)).update(deepcopy(EMPTY_DICT))
    return field_dict

def alias_field(model, field):
    """Return the prefix name of a field"""
    for part in field.split(LOOKUP_SEP)[:-1]:
        model = associate_model(model, part)
    return model.__name__ + '-' + field.split(LOOKUP_SEP)[-1]

def associate_model(model, field):
    """Return the model associate to the ForeignKey or ManyToMany
    relation"""
    class_field = model._meta.get_field(field)
    if hasattr(class_field, 'field'):
        return class_field.field.related.related_model
    else:
        return class_field.related_model

def get_formfield(model, field):
    """Return the formfied associate to the field of the model"""
    class_field = model._meta.get_field(field)
    if hasattr(class_field, 'field'):
        formfield = class_field.field.formfield()
    else:
        formfield = class_field.formfield()
    if isinstance(formfield, ChoiceField):
        formfield.choices = class_field.get_choices()
    return formfield

def setup_errors(app, error_template='error.html'):
    """Add a handler for each of the available HTTP error responses."""
    def error_handler(error):
        if isinstance(error, HTTPException):
            description = error.get_description(request.environ)
            code = error.code
            name = error.name
        else:
            description = error
            code = 500
            name = 'Internal Server Error'
        return (render_template(error_template, error=error, code=code, name=Markup(name), description=Markup(description)), code)
    for exception in default_exceptions:
        app.register_error_handler(exception, error_handler)

def to_int(s):
    """converts a string to an integer

    >>> to_int('1_000_000')
    1000000

    >>> to_int('1e6')
    1000000

    >>> to_int('1000')
    1000"""
    try:
        return int(s.replace('_', ''))
    except ValueError:
        return int(ast.literal_eval(s))

def dicts_from_lines(lines):
    """returns a generator producing dicts from json lines

    1 JSON object per line is supported:

        {"name": "n1"}
        {"name": "n2"}

    Or 1 JSON object:

        {
            "name": "n1"
        }

    Or a list of JSON objects:

        [
            {"name": "n1"},
            {"name": "n2"},
        ]"""
    lines = iter(lines)
    for line in lines:
        line = line.strip()
        if not line:
            continue
        try:
            yield json.loads(line, object_pairs_hook=OrderedDict)
        except json.decoder.JSONDecodeError:
            content = line + ''.join(lines)
            dicts = json.loads(content, object_pairs_hook=OrderedDict)
            if isinstance(dicts, list):
                yield from dicts
            else:
                yield dicts

def first_invoke(func1, func2):
    """Return a function that when invoked will invoke func1 without
    any parameters (for its side-effect) and then invoke func2
    with whatever parameters were passed, returning its result."""
    def wrapper(*args, **kwargs):
        func1()
        return func2(*args, **kwargs)
    return wrapper

def retry_call(func, cleanup=lambda: None, retries=0, trap=()):
    """Given a callable func, trap the indicated exceptions
    for up to 'retries' times, invoking cleanup on the
    exception. On the final attempt, allow any exceptions
    to propagate."""
    attempts = count() if retries == float('inf') else range(retries)
    for attempt in attempts:
        try:
            return func()
        except trap:
            cleanup()
    return func()

def wait_until(predicate, timeout=30):
    """Wait until predicate returns a truthy value or the timeout is reached.

    >>> wait_until(lambda: True, timeout=10)"""
    not_expired = Timeout(timeout)
    while not_expired():
        r = predicate()
        if r:
            break

