def _parse_options(options: List[str]) -> Dict[str, str]:
    """Parse repeatable CLI options

    >>> opts = _parse_options(['cluster.name=foo', 'CRATE_JAVA_OPTS="-Dxy=foo"'])
    >>> print(json.dumps(opts, sort_keys=True))
    {"CRATE_JAVA_OPTS": "\\"-Dxy=foo\\"", "cluster.name": "foo"}"""
    try:
        return dict((i.split('=', maxsplit=1) for i in options))
    except ValueError:
        raise ArgumentError(f'Option must be in format <key>=<value>, got: {options}')

def insert_json(table=None, bulk_size=1000, concurrency=25, hosts=None, output_fmt=None):
    """Insert JSON lines fed into stdin into a Crate cluster.

    If no hosts are specified the statements will be printed.

    Args:
        table: Target table name.
        bulk_size: Bulk size of the insert statements.
        concurrency: Number of operations to run concurrently.
        hosts: hostname:port pairs of the Crate nodes"""
    if not hosts:
        return print_only(table)
    queries = (to_insert(table, d) for d in dicts_from_stdin())
    bulk_queries = as_bulk_queries(queries, bulk_size)
    print('Executing inserts: bulk_size={} concurrency={}'.format(bulk_size, concurrency), file=sys.stderr)
    stats = Stats()
    with clients.client(hosts, concurrency=concurrency) as client:
        f = partial(aio.measure, stats, client.execute_many)
        try:
            aio.run_many(f, bulk_queries, concurrency)
        except clients.SqlException as e:
            raise SystemExit(str(e))
    try:
        print(format_stats(stats.get(), output_fmt))
    except KeyError:
        if not stats.sampler.values:
            raise SystemExit('No data received via stdin')
        raise

def _get_dominant_angle(lines, domination_type=MEDIAN):
    """Picks dominant angle of a set of lines.

    Args:
        lines: iterable of (x1, y1, x2, y2) tuples that define lines.
        domination_type: either MEDIAN or MEAN.

    Returns:
        Dominant angle value in radians.

    Raises:
        ValueError: on unknown domination_type."""
    if domination_type == MEDIAN:
        return _get_median_angle(lines)
    elif domination_type == MEAN:
        return _get_mean_angle(lines)
    else:
        raise ValueError('Unknown domination type provided: %s' % domination_type)

def _parse_java_version(line: str) -> tuple:
    """Return the version number found in the first line of `java -version`

    >>> _parse_java_version('openjdk version "11.0.2" 2018-10-16')
    (11, 0, 2)"""
    m = VERSION_RE.search(line)
    version_str = m and m.group(0).replace('"', '') or '0.0.0'
    if '_' in version_str:
        fst, snd = version_str.split('_', maxsplit=2)
        version = parse_version(fst)
        return (version[1], version[2], int(snd))
    else:
        return parse_version(version_str)

def find_java_home(cratedb_version: tuple) -> str:
    """Return a path to a JAVA_HOME suites for the given CrateDB version"""
    if MIN_VERSION_FOR_JVM11 <= cratedb_version < (4, 0):
        return os.environ.get('JAVA_HOME', '')
    if cratedb_version < MIN_VERSION_FOR_JVM11:
        return _find_matching_java_home(lambda ver: ver[0] == 8)
    else:
        return _find_matching_java_home(lambda ver: ver[0] >= 11)

def get_sampler(sample_mode: str):
    """Return a sampler constructor

    >>> get_sampler('all')
    <class 'cr8.metrics.All'>

    >>> get_sampler('reservoir')
    <class 'cr8.metrics.UniformReservoir'>

    >>> get_sampler('reservoir:100')
    functools.partial(<class 'cr8.metrics.UniformReservoir'>, size=100)"""
    if sample_mode == 'all':
        return All
    mode = sample_mode.split(':')
    if mode[0] == 'reservoir':
        if len(mode) == 2:
            return partial(UniformReservoir, size=int(mode[1]))
        else:
            return UniformReservoir
    raise TypeError(f'Invalid sample_mode: {sample_mode}')

