def undo(ui, repo, clname, **opts):
    """undo the effect of a CL

    Creates a new CL that undoes an earlier CL.
    After creating the CL, opens the CL text for editing so that
    you can add the reason for the undo to the description."""
    if repo[None].branch() != 'default':
        raise hg_util.Abort('cannot run hg undo outside default branch')
    err = clpatch_or_undo(ui, repo, clname, opts, mode='undo')
    if err:
        raise hg_util.Abort(err)

def mail(ui, repo, *pats, **opts):
    """mail a change for review

    Uploads a patch to the code review server and then sends mail
    to the reviewer and CC list asking for a review."""
    if codereview_disabled:
        raise hg_util.Abort(codereview_disabled)
    cl, err = CommandLineCL(ui, repo, pats, opts, op='mail', defaultcc=defaultcc)
    if err != '':
        raise hg_util.Abort(err)
    cl.Upload(ui, repo, gofmt_just_warn=True)
    if not cl.reviewer:
        if not defaultcc:
            raise hg_util.Abort('no reviewers listed in CL')
        cl.cc = Sub(cl.cc, defaultcc)
        cl.reviewer = defaultcc
        cl.Flush(ui, repo)
    if cl.files == []:
        raise hg_util.Abort('no changed files, not sending mail')
    cl.Mail(ui, repo)

def ps(ui, repo, *pats, **opts):
    """alias for hg p --short
    """
    opts['short'] = True
    return pending(ui, repo, *pats, **opts)

def pq(ui, repo, *pats, **opts):
    """alias for hg p --quick
    """
    opts['quick'] = True
    return pending(ui, repo, *pats, **opts)

def pending(ui, repo, *pats, **opts):
    """show pending changes

    Lists pending changes followed by a list of unassigned but modified files."""
    if codereview_disabled:
        raise hg_util.Abort(codereview_disabled)
    quick = opts.get('quick', False)
    short = opts.get('short', False)
    m = LoadAllCL(ui, repo, web=not quick and (not short))
    names = m.keys()
    names.sort()
    for name in names:
        cl = m[name]
        if short:
            ui.write(name + '\t' + line1(cl.desc) + '\n')
        else:
            ui.write(cl.PendingText(quick=quick) + '\n')
    if short:
        return 0
    files = DefaultFiles(ui, repo, [])
    if len(files) > 0:
        s = 'Changed files not in any CL:\n'
        for f in files:
            s += '\t' + f + '\n'
        ui.write(s)

def sync(ui, repo, **opts):
    """synchronize with remote repository

    Incorporates recent changes from the remote repository
    into the local repository."""
    if codereview_disabled:
        raise hg_util.Abort(codereview_disabled)
    if not opts['local']:
        if hg_incoming(ui, repo):
            err = hg_pull(ui, repo, update=True)
        else:
            err = hg_update(ui, repo)
        if err:
            return err
    sync_changes(ui, repo)

def _Delta(a, b):
    """Compute the delta for b - a.  Even/odd and odd/even
    are handled specially, as described above."""
    if a + 1 == b:
        if a % 2 == 0:
            return 'EvenOdd'
        else:
            return 'OddEven'
    if a == b + 1:
        if a % 2 == 0:
            return 'OddEven'
        else:
            return 'EvenOdd'
    return b - a

def _AddDelta(a, delta):
    """Return a + delta, handling EvenOdd and OddEven specially."""
    if type(delta) == int:
        return a + delta
    if delta == 'EvenOdd':
        if a % 2 == 0:
            return a + 1
        else:
            return a - 1
    if delta == 'OddEven':
        if a % 2 == 1:
            return a + 1
        else:
            return a - 1
    (print >> sys.stderr, 'Bad Delta: ', delta)
    raise 'Bad Delta'

def _MakeRanges(pairs):
    """Turn a list like [(65,97), (66, 98), ..., (90,122)]
    into [(65, 90, +32)]."""
    ranges = []
    last = -100
    def evenodd(last, a, b, r):
        if a != last + 1 or b != _AddDelta(a, r[2]):
            return False
        r[1] = a
        return True
    def evenoddpair(last, a, b, r):
        if a != last + 2:
            return False
        delta = r[2]
        d = delta
        if type(delta) is not str:
            return False
        if delta.endswith('Skip'):
            d = delta[:-4]
        else:
            delta = d + 'Skip'
        if b != _AddDelta(a, d):
            return False
        r[1] = a
        r[2] = delta
        return True
    for a, b in pairs:
        if ranges and evenodd(last, a, b, ranges[-1]):
            pass
        elif ranges and evenoddpair(last, a, b, ranges[-1]):
            pass
        else:
            ranges.append([a, a, _Delta(a, b)])
        last = a
    return ranges

def discover(url, timeout=None):
    """Discover the hub url and topic url of a given url. Firstly, by inspecting
    the page's headers, secondarily by inspecting the content for link tags.

    timeout determines how long to wait for the url to load. It defaults to 3."""
    resp = get_content({'REQUEST_TIMEOUT': timeout}, url)
    parser = LinkParser()
    parser.hub_url = (resp.links.get('hub') or {}).get('url')
    parser.topic_url = (resp.links.get('self') or {}).get('url')
    try:
        parser.updated()
        for chunk in resp.iter_content(chunk_size=None, decode_unicode=True):
            parser.feed(chunk)
        parser.close()
    except Finished:
        return {'hub_url': parser.hub_url, 'topic_url': parser.topic_url}
    raise DiscoveryError('Could not find hub url in topic page')

