def subscribe(hub, callback_url, topic_url, lease_seconds, secret, endpoint_hook_data):
    """5.2 Subscription Validation"""
    for validate in hub.validators:
        error = validate(callback_url, topic_url, lease_seconds, secret, endpoint_hook_data)
        if error:
            send_denied(hub, callback_url, topic_url, error)
            return
    if intent_verified(hub, callback_url, 'subscribe', topic_url, lease_seconds):
        hub.storage[topic_url, callback_url] = {'lease_seconds': lease_seconds, 'secret': secret}

def intent_verified(hub, callback_url, mode, topic_url, lease_seconds):
    """5.3 Hub Verifies Intent of the Subscriber"""
    challenge = uuid4()
    params = {'hub.mode': mode, 'hub.topic': topic_url, 'hub.challenge': challenge, 'hub.lease_seconds': lease_seconds}
    try:
        response = request_url(hub.config, 'GET', callback_url, params=params)
        assert response.status_code == 200 and response.text == challenge
    except requests.exceptions.RequestException as e:
        warn('Cannot verify subscriber intent', e)
    except AssertionError as e:
        warn(INTENT_UNVERIFIED % (response.status_code, response.content), e)
    else:
        return True
    return False

