    if data.get('statusCode') and data['statusCode'] != 200:
        raise RequestError('Error requesting data from {0}: {1} {2}'.format(url, data['statusCode'], data['message']))

def raise_remote_error(error_code: int) -> None:
    """Raise the appropriate error with a remote error code."""
    try:
        error = next((v for k, v in ERROR_CODES.items() if k == error_code))
        raise RequestError(error)
    except StopIteration:
        raise RequestError('Unknown remote error code returned: {0}'.format(error_code))

def build_command_tree(pattern, cmd_params):
    """Recursively fill in a command tree in cmd_params according to a docopt-parsed "pattern" object."""
    from docopt import Either, Optional, OneOrMore, Required, Option, Command, Argument
    if type(pattern) in [Either, Optional, OneOrMore]:
        for child in pattern.children:
            build_command_tree(child, cmd_params)
    elif type(pattern) in [Required]:
        for child in pattern.children:
            cmd_params = build_command_tree(child, cmd_params)
    elif type(pattern) in [Option]:
        suffix = '=' if pattern.argcount else ''
        if pattern.short:
            cmd_params.options.append(pattern.short + suffix)
        if pattern.long:
            cmd_params.options.append(pattern.long + suffix)
    elif type(pattern) in [Command]:
        cmd_params = cmd_params.get_subcommand(pattern.name)
    elif type(pattern) in [Argument]:
        cmd_params.arguments.append(pattern.name)
    return cmd_params

def cache_json(filename):
    """Caches the JSON-serializable output of the function to a given file

    Args:
        filename (str) The filename (sans directory) to store the output

    Returns: decorator, applicable to a function that produces JSON-serializable output"""
    def cache_decorator(cacheable_function):
        @wraps(cacheable_function)
        def cache_wrapper(*args, **kwargs):
            path = CACHE_DIRECTORY + filename
            check_create_folder(path)
            if os.path.exists(path):
                with open(path) as infile:
                    return json.load(infile)
            else:
                function_output = cacheable_function(*args, **kwargs)
                with open(path, 'w') as outfile:
                    json.dump(function_output, outfile)
                return function_output
        return cache_wrapper
    return cache_decorator

