def perform_import(val):
    """If the given setting is a string import notation,
    then perform the necessary import or imports."""
    if val is None:
        return None
    elif isinstance(val, str):
        return import_from_string(val)
    elif isinstance(val, (list, tuple)):
        return [import_from_string(item) for item in val]
    return val

def import_from_string(val):
    """Attempt to import a class from a string representation."""
    try:
        module_path, class_name = val.rsplit('.', 1)
        module = import_module(module_path)
        return getattr(module, class_name)
    except (ImportError, AttributeError) as e:
        msg = f'Could not import {val}. {e.__class__.__name__}: {e}'
        raise ImportError(msg)

def sequencer(params, source_specs):
    """Add a sequence of sounds to a buffer
    :param params: buffer parameters, controls length of signal created
    :param source_spec: list of tuples containing (source, sample). The source is added into the output buffer
    at the sample position given by the second element in the tuple
    :return:"""
    output = np.zeros(params.length, dtype=np.float)
    for source, pos in source_specs:
        if pos >= 0:
            length = min(source.size, params.length - pos)
            if length > 0:
                output[pos:pos + length] += source[:length]
    return output

def get_timestamp(dt=None):
    """Return current timestamp if @dt is None
    else return timestamp of @dt.

    >>> t = datetime.datetime(2015, 0o5, 21)
    >>> get_timestamp(t)
    1432166400"""
    if dt is None:
        dt = datetime.datetime.utcnow()
    t = dt.utctimetuple()
    return calendar.timegm(t)

def flatten_dict(d, parent_key='', sep='.', ignore_under_prefixed=True, mark_value=True):
    """Flattens a nested dictionary

    >>> from pprint import pprint
    >>> d = {"a": {"b": {"c": 1, "b": 2, "__d": 'ignore', "_e": "mark"} } }
    >>> fd = flatten_dict(d)
    >>> pprint(fd)
    {'a.b._e': "'mark'", 'a.b.b': 2, 'a.b.c': 1}"""
    items = {}
    for k in d:
        if ignore_under_prefixed and k.startswith('__'):
            continue
        v = d[k]
        if mark_value and k.startswith('_') and (not k.startswith('__')):
            v = MarkValue(repr(v))
        new_key = sep.join((parent_key, k)) if parent_key else k
        if isinstance(v, collections.MutableMapping):
            items.update(flatten_dict(v, new_key, sep=sep, ignore_under_prefixed=True, mark_value=True))
        else:
            items[new_key] = v
    return items

