        click.echo(str(variant).rstrip())

def cli(ctx, database, username, password, authdb, port, host, uri, verbose, config, test):
    """loqusdb: manage a local variant count database."""
    loglevel = 'INFO'
    if verbose:
        loglevel = 'DEBUG'
    coloredlogs.install(level=loglevel)
    LOG.info('Running loqusdb version %s', __version__)
    configs = {}
    if config:
        try:
            configs = yaml.safe_load(config)
        except yaml.YAMLError as err:
            LOG.warning(err)
            ctx.abort()
    uri = configs.get('uri') or uri
    if test:
        uri = 'mongomock://'
    try:
        client = get_client(host=configs.get('host') or host, port=configs.get('port') or port, username=configs.get('username') or username, password=configs.get('password') or password, authdb=authdb or database or 'loqusdb', uri=uri)
    except DB_Error as err:
        LOG.warning(err)
        ctx.abort()
    database = configs.get('db_name') or database
    if not database:
        database = 'loqusdb'
        if uri:
            uri_info = uri_parser.parse_uri(uri)
            database = uri_info.get('database')
    adapter = MongoAdapter(client, db_name=database)
    ctx.obj = {}
    ctx.obj['db'] = database
    ctx.obj['user'] = username
    ctx.obj['password'] = password
    ctx.obj['port'] = port
    ctx.obj['host'] = host
    ctx.obj['adapter'] = adapter
    ctx.obj['version'] = __version__

def binarize(qualitative):
    """binarizes an expression dataset."""
    thresholds = qualitative.min(1) + (qualitative.max(1) - qualitative.min(1)) / 2.0
    binarized = qualitative > thresholds.reshape((len(thresholds), 1)).repeat(8, 1)
    return binarized.astype(int)

def script_dir(pyobject, follow_symlinks=True):
    """Get current script's directory

    Args:
        pyobject (Any): Any Python object in the script
        follow_symlinks (Optional[bool]): Follow symlinks or not. Defaults to True.

    Returns:
        str: Current script's directory"""
    if getattr(sys, 'frozen', False):
        path = abspath(sys.executable)
    else:
        path = inspect.getabsfile(pyobject)
    if follow_symlinks:
        path = realpath(path)
    return dirname(path)

def annotate_snvs(adapter, vcf_obj):
    """Annotate all variants in a VCF

    Args:
        adapter(loqusdb.plugin.adapter)
        vcf_obj(cyvcf2.VCF)

    Yields:
        variant(cyvcf2.Variant): Annotated variant"""
    variants = {}
    for nr_variants, variant in enumerate(vcf_obj, 1):
        variants[get_variant_id(variant)] = variant
        if nr_variants % 1000 == 0:
            for var_obj in adapter.search_variants(list(variants.keys())):
                var_id = var_obj['_id']
                if var_id in variants:
                    annotate_variant(variants[var_id], var_obj)
            for variant_id in variants:
                yield variants[variant_id]
            variants = {}
    for var_obj in adapter.search_variants(list(variants.keys())):
        var_id = var_obj['_id']
        if var_id in variants:
            annotate_variant(variants[var_id], var_obj)
    for variant_id in variants:
        yield variants[variant_id]

def poisson_ll_2(p1, p2):
    """Calculates Poisson LL(p1|p2)."""
    p1_1 = p1 + eps
    p2_1 = p2 + eps
    return np.sum(-p2_1 + p1_1 * np.log(p2_1))

def poisson_dist(p1, p2):
    """Calculates the Poisson distance between two vectors.

    p1 can be a sparse matrix, while p2 has to be a dense matrix."""
    p1_ = p1 + eps
    p2_ = p2 + eps
    return np.dot(p1_ - p2_, np.log(p1_ / p2_))

