    for variant in result:
        i += 1
        pp(variant)
    LOG.info('Number of variants found in database: %s', i)

def dotd(A, B, out=None):
    """Diagonal of :math:`\\mathrm A\\mathrm B^\\intercal`.

    If ``A`` is :math:`n\\times p` and ``B`` is :math:`p\\times n`, it is done in
    :math:`O(pn)`.

    Args:
        A (array_like): Left matrix.
        B (array_like): Right matrix.
        out (:class:`numpy.ndarray`, optional): copy result to.

    Returns:
        :class:`numpy.ndarray`: Resulting diagonal."""
    A = asarray(A, float)
    B = asarray(B, float)
    if A.ndim == 1 and B.ndim == 1:
        if out is None:
            return dot(A, B)
        return dot(A, B, out)
    if out is None:
        out = empty((A.shape[0],), float)
    return einsum('ij,ji->i', A, B, out=out)

def ddot(L, R, left=None, out=None):
    """Dot product of a matrix and a diagonal one.

    Args:
        L (array_like): Left matrix.
        R (array_like): Right matrix.
        out (:class:`numpy.ndarray`, optional): copy result to.

    Returns:
        :class:`numpy.ndarray`: Resulting matrix."""
    L = asarray(L, float)
    R = asarray(R, float)
    if left is None:
        ok = min(L.ndim, R.ndim) == 1 and max(L.ndim, R.ndim) == 2
        if not ok:
            msg = 'Wrong array layout. One array should have'
            msg += ' ndim=1 and the other one ndim=2.'
            raise ValueError(msg)
        left = L.ndim == 1
    if left:
        if out is None:
            out = copy(R)
        L = L.reshape(list(L.shape) + [1] * (R.ndim - 1))
        return multiply(L, R, out=out)
    else:
        if out is None:
            out = copy(L)
        return multiply(L, R, out=out)

def cdot(L, out=None):
    """Product of a Cholesky matrix with itself transposed.

    Args:
        L (array_like): Cholesky matrix.
        out (:class:`numpy.ndarray`, optional): copy result to.

    Returns:
        :class:`numpy.ndarray`: :math:`\\mathrm L\\mathrm L^\\intercal`."""
    L = asarray(L, float)
    layout_error = 'Wrong matrix layout.'
    if L.ndim != 2:
        raise ValueError(layout_error)
    if L.shape[0] != L.shape[1]:
        raise ValueError(layout_error)
    if out is None:
        out = empty((L.shape[0], L.shape[1]), float)
    return einsum('ij,kj->ik', L, L, out=out)

def rsolve(A, b, epsilon=_epsilon):
    """Robust solve for the linear equations.

    Args:
        A (array_like): Coefficient matrix.
        b (array_like): Ordinate values.

    Returns:
        :class:`numpy.ndarray`: Solution ``x``."""
    A = asarray(A, float)
    b = asarray(b, float)
    if A.shape[0] == 0:
        return zeros((A.shape[1],))
    if A.shape[1] == 0:
        return zeros((0,))
    try:
        x = lstsq(A, b, rcond=epsilon)
        r = sum(x[3] > epsilon)
        if r == 0:
            return zeros(A.shape[1])
        return x[0]
    except (ValueError, LinAlgError) as e:
        warnings.warn(str(e), RuntimeWarning)
    return solve(A, b)

def check_symmetry(A):
    """Check if ``A`` is a symmetric matrix.

    Args:
        A (array_like): Matrix.

    Returns:
        bool: ``True`` if ``A`` is symmetric; ``False`` otherwise."""
    A = asanyarray(A)
    if A.ndim != 2:
        raise ValueError('Checks symmetry only for bi-dimensional arrays.')
    if A.shape[0] != A.shape[1]:
        return False
    return abs(A - A.T).max() < sqrt(finfo(float).eps)

