def catch_errors(f):
    """Catches specific errors in admin actions and shows a friendly error."""
    @functools.wraps(f)
    def wrapper(self, request, *args, **kwargs):
        try:
            return f(self, request, *args, **kwargs)
        except exceptions.CertificateExpired:
            self.message_user(request, _('The AFIP Taxpayer certificate has expired.'), messages.ERROR)
        except exceptions.UntrustedCertificate:
            self.message_user(request, _('The AFIP Taxpayer certificate is untrusted.'), messages.ERROR)
        except exceptions.CorruptCertificate:
            self.message_user(request, _('The AFIP Taxpayer certificate is corrupt.'), messages.ERROR)
        except exceptions.AuthenticationError as e:
            logger.exception('AFIP auth failed')
            self.message_user(request, _('An unknown authentication error has ocurred: %s') % e, messages.ERROR)
    return wrapper

def ignore(code):
    """Should this code be ignored.

    :param str code: Error code (e.g. D201).

    :return: True if code should be ignored, False otherwise.
    :rtype: bool"""
    if code in Main.options['ignore']:
        return True
    if any((c in code for c in Main.options['ignore'])):
        return True
    return False

def weigh_users(X_test, model, classifier_type='LinearSVC'):
    """Uses a trained model and the unlabelled features to produce a user-to-label distance matrix.

    Inputs:  - feature_matrix: The graph based-features in either NumPy or SciPy sparse array format.
             - model: A trained scikit-learn One-vs-All multi-label scheme of linear SVC models.
             - classifier_type: A string to be chosen among: * LinearSVC (LibLinear)
                                                             * LogisticRegression (LibLinear)
                                                             * RandomForest

    Output:  - decision_weights: A NumPy array containing the distance of each user from each label discriminator."""
    if classifier_type == 'LinearSVC':
        decision_weights = model.decision_function(X_test)
    elif classifier_type == 'LogisticRegression':
        decision_weights = model.predict_proba(X_test)
    elif classifier_type == 'RandomForest':
        if issparse(X_test):
            decision_weights = model.predict_proba(X_test.tocsr())
        else:
            decision_weights = model.predict_proba(X_test)
    else:
        print('Invalid classifier type.')
        raise RuntimeError
    return decision_weights

def _extract_seq(extractor, seq):
    """Convert a sequence to primitive equivalents."""
    subtype = Any
    if seq.__args__ and seq.__args__[0] is not Any:
        subtype = seq.__args__[0]
    return _array_type(extractor.extract(subtype))

def is_middleware(func) -> bool:
    """test whether it is a middleware
    :return: Boolean"""
    if inspect.isfunction(func):
        _check = func
        _name = func.__name__
    else:
        _check = func.__call__
        _name = func.__class__.__name__
    if not inspect.iscoroutinefunction(_check):
        raise UnknownMiddlewareException('Middleware {} should be async function'.format(_name))
    args = list(inspect.signature(_check).parameters.keys())
    if set(args) - MIDDLEWARE_PARAMETER_BOUNDARY:
        raise UnknownMiddlewareException("Parameters of middleware {} must be in list ['app', 'request', 'response', 'next']".format(_name))
    return True

