def pretty_format_args(*args, **kwargs):
    """Take the args, and kwargs that are passed them and format in a
    prototype style."""
    args = list([repr(a) for a in args])
    for key, value in kwargs.items():
        args.append('%s=%s' % (key, repr(value)))
    return '(%s)' % ', '.join([a for a in args])

def _get_context(argspec, kwargs):
    """Prepare a context for the serialization.

    :param argspec: The argspec of the serialization function.
    :param kwargs: Dict with context
    :return: Keywords arguments that function can accept."""
    if argspec.keywords is not None:
        return kwargs
    return dict(((arg, kwargs[arg]) for arg in argspec.args if arg in kwargs))

def _enforce_instance(model_or_class):
    """It's a common mistake to not initialize a
    schematics class. We should handle that by just
    calling the default constructor."""
    if isinstance(model_or_class, type) and issubclass(model_or_class, BaseType):
        return model_or_class()
    return model_or_class

def create_routes_and_handler(transmute_func, context):
    """return back a handler that is the api generated
    from the transmute_func, and a list of routes
    it should be mounted to."""
    @wraps(transmute_func.raw_func)
    def handler():
        exc, result = (None, None)
        try:
            args, kwargs = ParamExtractorFlask().extract_params(context, transmute_func, request.content_type)
            result = transmute_func(*args, **kwargs)
        except Exception as e:
            exc = e
            '\n            attaching the traceack is done for you in Python 3, but\n            in Python 2 the __traceback__ must be\n            attached to the object manually.\n            '
            exc.__traceback__ = sys.exc_info()[2]
        '\n        transmute_func.process_result handles converting\n        the response from the function into the response body,\n        the status code that should be returned, and the\n        response content-type.\n        '
        response = transmute_func.process_result(context, result, exc, request.content_type)
        return Response(response['body'], status=response['code'], mimetype=response['content-type'], headers=response['headers'])
    return (_convert_paths_to_flask(transmute_func.paths), handler)

def add_swagger(app, json_route, html_route, **kwargs):
    """add a swagger html page, and a swagger.json generated
    from the routes added to the app."""
    spec = getattr(app, SWAGGER_ATTR_NAME)
    if spec:
        spec = spec.swagger_definition(**kwargs)
    else:
        spec = {}
    encoded_spec = json.dumps(spec).encode('UTF-8')
    @app.route(json_route)
    def swagger():
        return Response(encoded_spec, headers={'Access-Control-Allow-Origin': '*'}, content_type='application/json')
    static_root = get_swagger_static_root()
    swagger_body = generate_swagger_html(STATIC_PATH, json_route).encode('utf-8')
    @app.route(html_route)
    def swagger_ui():
        return Response(swagger_body, content_type='text/html')
    blueprint = Blueprint('swagger', __name__, static_url_path=STATIC_PATH, static_folder=static_root)
    app.register_blueprint(blueprint)

def rgb_distance(rgb1, rgb2):
    """Calculate the distance between two RGB sequences."""
    return sum(map(lambda c: (c[0] - c[1]) ** 2, zip(rgb1, rgb2)))

def rgb_reduce(r, g, b, mode=8):
    """Convert an RGB colour to 8 or 16 colour ANSI graphics."""
    colours = ANSI_COLOURS[:mode]
    matches = [(rgb_distance(c, map(int, [r, g, b])), i) for i, c in enumerate(colours)]
    matches.sort()
    return sequence('m')(str(30 + matches[0][1]))

def rgb256(r, g, b):
    """Convert an RGB colour to 256 colour ANSI graphics."""
    grey = False
    poss = True
    step = 2.5
    while poss:
        if r < step or g < step or b < step:
            grey = r < step and g < step and (b < step)
            poss = False
        step += 42.5
    if grey:
        colour = 232 + int(float(sum([r, g, b]) / 33.0))
    else:
        colour = sum([16] + [int(6 * float(val) / 256) * mod for val, mod in ((r, 36), (g, 6), (b, 1))])
    return sequence('m', fields=3)(38, 5, colour)

def url_spec(transmute_path, handler, *args, **kwargs):
    """convert the transmute_path
    to a tornado compatible regex,
    and return a tornado url object."""
    p = _to_tornado_pattern(transmute_path)
    for m in METHODS:
        method = getattr(handler, m)
        if hasattr(method, 'transmute_func'):
            method.transmute_func.paths.add(transmute_path)
    return tornado.web.URLSpec(p, handler, *args, **kwargs)

def change_angles(method, theta, tol=1e-10):
    """Function used by all angle conversion functions (from_x_to_x_pi(...))"""
    try:
        theta_new = np.zeros(theta.shape)
        for i, thet in enumerate(theta):
            try:
                theta_new[i] = method(thet, tol)
            except:
                for j, th in enumerate(thet):
                    try:
                        theta_new[i, j] = method(th, tol)
                    except:
                        for k, t in enumerate(th):
                            theta_new[i, j, k] = method(t, tol)
        return theta_new
    except:
        return method(theta, tol)

def rmse_2pi(x, xhat):
    """Calcualte rmse between vector or matrix x and xhat, ignoring mod of 2pi."""
    real_diff = from_0_to_pi(x - xhat)
    np.square(real_diff, out=real_diff)
    sum_ = np.sum(real_diff)
    return sqrt(sum_ / len(x))

def _extract_path_parameters_from_paths(paths):
    """from a list of paths, return back a list of the
    arguments present in those paths.

    the arguments available in all of the paths must match: if not,
    an exception will be raised."""
    params = set()
    for path in paths:
        parts = PART_REGEX.split(path)
        for p in parts:
            match = PARAM_REGEX.match(p)
            if match:
                params.add(match.group('name'))
    return params

def _build_body_schema(serializer, body_parameters):
    """body is built differently, since it's a single argument no matter what."""
    description = ''
    if isinstance(body_parameters, Param):
        schema = serializer.to_json_schema(body_parameters.arginfo.type)
        description = body_parameters.description
        required = True
    else:
        if len(body_parameters) == 0:
            return None
        required = set()
        body_properties = {}
        for name, param in body_parameters.items():
            arginfo = param.arginfo
            body_properties[name] = serializer.to_json_schema(arginfo.type)
            body_properties[name]['description'] = param.description
            if arginfo.default is NoDefault:
                required.add(name)
        schema = {'type': 'object', 'required': list(required), 'properties': body_properties}
        required = len(required) > 0
    return BodyParameter({'name': 'body', 'description': description, 'required': required, 'schema': schema})

