def MDS(D, dim, method='simple', theta=False):
    """recover points from euclidean distance matrix using classic MDS algorithm.
    """
    N = D.shape[0]
    if method == 'simple':
        d1 = D[0, :]
        buf_ = np.broadcast_to(d1, D.shape) + np.broadcast_to(d1[:, np.newaxis], D.shape)
        np.subtract(D, buf_, out=buf_)
        G = buf_
    elif method == 'advanced':
        s1T = np.zeros_like(D)
        s1T[0, :] = 1
        np.subtract(np.identity(N), s1T, out=s1T)
        G = np.dot(np.dot(s1T.T, D), s1T)
    elif method == 'geometric':
        J = np.identity(N) + np.full((N, N), -1.0 / float(N))
        G = np.dot(np.dot(J, D), J)
    else:
        print('Unknown method {} in MDS'.format(method))
    G *= -0.5
    factor, u = eigendecomp(G, dim)
    if theta:
        return theta_from_eigendecomp(factor, u)
    else:
        return x_from_eigendecomp(factor, u, dim)

def iterativeEMDS(X0, N, d, C, b, max_it=10, print_out=False, **kwargs):
    """Find the set of points from an edge kernel with geometric constraints, using iterative projection
    """
    from pylocus.basics import mse, projection
    KE = kwargs.get('KE', None)
    KE_projected = KE.copy()
    d = len(X0)
    for i in range(max_it):
        KE_projected, cost, __ = projection(KE_projected, C, b)
        rank = np.linalg.matrix_rank(KE_projected)
        Xhat_KE, Vhat_KE = superMDS(X0, N, d, KE=KE_projected)
        KE_projected = Vhat_KE.dot(Vhat_KE.T)
        error = mse(C.dot(KE_projected), b)
        if print_out:
            print('cost={:2.2e},error={:2.2e}, rank={}'.format(cost, error, rank))
        if cost < 1e-20 and error < 1e-20 and (rank == d):
            if print_out:
                print('converged after {} iterations'.format(i))
            return (Xhat_KE, Vhat_KE)
    print('iterativeMDS did not converge!')
    return (None, None)

def relaxedEMDS(X0, N, d, C, b, KE, print_out=False, lamda=10):
    """Find the set of points from an edge kernel with geometric constraints, using convex rank relaxation.
    """
    E = C.shape[1]
    X = Variable((E, E), PSD=True)
    constraints = [C[i, :] * X == b[i] for i in range(C.shape[0])]
    obj = Minimize(trace(X) + lamda * norm(KE - X))
    prob = Problem(obj, constraints)
    try:
        total_cost = prob.solve(solver='CVXOPT', verbose=print_out)
    except:
        try:
            print('CVXOPT with default cholesky failed. Trying kktsolver...')
            total_cost = prob.solve(solver='CVXOPT', verbose=print_out, kktsolver='robust')
        except:
            try:
                print('CVXOPT with robust kktsovler failed. Trying SCS...')
                total_cost = prob.solve(solver='SCS', verbose=print_out)
            except:
                print('SCS and CVXOPT solver with default and kktsolver failed .')
    if print_out:
        print('status:', prob.status)
    Xhat_KE, Vhat_KE = superMDS(X0, N, d, KE=X.value)
    return (Xhat_KE, Vhat_KE)

def route(app_or_blueprint, context=default_context, **kwargs):
    """attach a transmute route."""
    def decorator(fn):
        fn = describe(**kwargs)(fn)
        transmute_func = TransmuteFunction(fn)
        routes, handler = create_routes_and_handler(transmute_func, context)
        for r in routes:
            if not hasattr(app_or_blueprint, SWAGGER_ATTR_NAME):
                setattr(app_or_blueprint, SWAGGER_ATTR_NAME, SwaggerSpec())
            swagger_obj = getattr(app_or_blueprint, SWAGGER_ATTR_NAME)
            swagger_obj.add_func(transmute_func, context)
            app_or_blueprint.route(r, methods=transmute_func.methods)(handler)
        return handler
    return decorator

def add_route(app, fn, context=default_context):
    """a decorator that adds a transmute route to the application."""
    transmute_func = TransmuteFunction(fn, args_not_from_request=['request'])
    handler = create_handler(transmute_func, context=context)
    get_swagger_spec(app).add_func(transmute_func, context)
    for p in transmute_func.paths:
        aiohttp_path = _convert_to_aiohttp_path(p)
        resource = app.router.add_resource(aiohttp_path)
        for method in transmute_func.methods:
            resource.add_route(method, handler)

def build_comparators(*values_or_types):
    """All of the comparators that can be used for arguments."""
    comparators = []
    for item in values_or_types:
        if isinstance(item, Comparator):
            comparators.append(item)
        elif isinstance(item, type):
            comparators.append(Any(IsA(item), Is(item)))
        else:
            comparators.append(Equals(item))
    return comparators

def add_codes(err_cls):
    """Add error codes to string messages via class attribute names."""
    class ErrorsWithCodes(object):
        def __getattribute__(self, code):
            msg = getattr(err_cls, code)
            return '[{code}] {msg}'.format(code=code, msg=msg)
    return ErrorsWithCodes()

def link(origin, link_name, force=False, model_path=None):
    """Create a symlink for models within the spacy/data directory. Accepts
    either the name of a pip package, or the local path to the model data
    directory. Linking models allows loading them via spacy.load(link_name)."""
    if util.is_package(origin):
        model_path = util.get_package_path(origin)
    else:
        model_path = Path(origin) if model_path is None else Path(model_path)
    if not model_path.exists():
        prints(Messages.M009.format(path=path2str(model_path)), title=Messages.M008, exits=1)
    data_path = util.get_data_path()
    if not data_path or not data_path.exists():
        spacy_loc = Path(__file__).parent.parent
        prints(Messages.M011, spacy_loc, title=Messages.M010, exits=1)
    link_path = util.get_data_path() / link_name
    if link_path.is_symlink() and (not force):
        prints(Messages.M013, title=Messages.M012.format(name=link_name), exits=1)
    elif link_path.is_symlink():
        link_path.unlink()
    elif link_path.exists():
        prints(Messages.M015, link_path, title=Messages.M014.format(name=link_name), exits=1)
    msg = '%s --> %s' % (path2str(model_path), path2str(link_path))
    try:
        symlink_to(link_path, model_path)
    except:
        prints(Messages.M017, msg, title=Messages.M016.format(name=link_name))
        raise
    prints(msg, Messages.M019.format(name=link_name), title=Messages.M018)

def load_model_from_path(model_path, meta=False, **overrides):
    """Load a model from a data directory path. Creates Language class with
    pipeline from meta.json and then calls from_disk() with path."""
    from .tokenizer_loader import TokenizerLoader
    if not meta:
        meta = get_model_meta(model_path)
    tokenizer_loader = TokenizerLoader(meta=meta, **overrides)
    tokenizers = meta.get('tokenizers', [])
    disable = overrides.get('disable', [])
    if tokenizers is True:
        tokenizers = TokenizerLoader.Defaults.tokenizers
    elif tokenizers in (False, None):
        tokenizers = []
    for tokenizer_name in tokenizers:
        if tokenizer_name not in disable:
            config = meta.get('tokenizer_args', {}).get(tokenizer_name, {})
            component = tokenizer_loader.create_tokenizer(tokenizer_name, config=config)
            tokenizer_loader.add_tokenizer(component, name=tokenizer_name)
    return tokenizer_loader.from_disk(model_path)

def is_package(name):
    """Check if string maps to a package installed via pip.

    name (unicode): Name of package.
    RETURNS (bool): True if installed package, False if not."""
    name = name.lower()
    packages = pkg_resources.working_set.by_key.keys()
    for package in packages:
        if package.lower().replace('-', '_') == name:
            return True
    return False

def decaying(start, stop, decay):
    """Yield an infinite series of linearly decaying values."""
    def clip(value):
        return max(value, stop) if start > stop else min(value, stop)
    nr_upd = 1.0
    while True:
        yield clip(start * 1.0 / (1.0 + decay * nr_upd))
        nr_upd += 1

def print_markdown(data, title=None):
    """Print data in GitHub-flavoured Markdown format for issues etc.

    data (dict or list of tuples): Label/value pairs.
    title (unicode or None): Title, will be rendered as headline 2."""
    def excl_value(value):
        return isinstance(value, basestring_) and Path(value).exists()
    if isinstance(data, dict):
        data = list(data.items())
    markdown = ['* **{}:** {}'.format(l, unicode_(v)) for l, v in data if not excl_value(v)]
    if title:
        print('\n## {}'.format(title))
    print('\n{}\n'.format('\n'.join(markdown)))

def normalize_string_keys(old):
    """Given a dictionary, make sure keys are unicode strings, not bytes."""
    new = {}
    for key, value in old.items():
        if isinstance(key, bytes_):
            new[key.decode('utf8')] = value
        else:
            new[key] = value
    return new

def timedelta_average(*values: datetime.timedelta) -> datetime.timedelta:
    """Compute the arithmetic mean for timedeltas list.

    :param \\*values: Timedelta instances to process."""
    if isinstance(values[0], (list, tuple)):
        values = values[0]
    return sum(values, datetime.timedelta()) // len(values)

def to_int(value: str, default: T=None) -> Union[int, Optional[T]]:
    """Convert given value to int.

    If conversion failed, return default value without raising Exception.

    :param value: Value to convert to int.
    :param default: Default value to use in case of failed conversion."""
    try:
        return int(value)
    except (TypeError, ValueError):
        return default

def safe_unit_norm(a):
    """Ensure that the vector or vectors have unit norm"""
    if 1 == len(a.shape):
        n = np.linalg.norm(a)
        if n:
            return a / n
        return a
    norm = np.sum(np.abs(a) ** 2, axis=-1) ** (1.0 / 2)
    norm[norm == 0] = -1000000000000.0
    return a / norm[:, np.newaxis]

def _wcut(l, windowsize, stepsize):
    """Parameters
        l - The length of the input array
        windowsize - the size of each window of samples
        stepsize - the number of samples to move the window each step

    Returns
        The length the input array should be so that leftover samples are ignored"""
    end = l - windowsize
    if l <= windowsize:
        return (0, 0)
    elif end % stepsize:
        l = windowsize + end // stepsize * stepsize
    return (l, l - (windowsize - stepsize))

def inject_settings(mixed: Union[str, Settings], context: MutableMapping[str, Any], fail_silently: bool=False) -> None:
    """Inject settings values to given context.

    :param mixed:
        Settings can be a string (that it will be read from Python path),
        Python module or dict-like instance.
    :param context:
        Context to assign settings key values. It should support dict-like item
        assingment.
    :param fail_silently:
        When enabled and reading settings from Python path ignore errors if
        given Python path couldn't be loaded."""
    if isinstance(mixed, str):
        try:
            mixed = import_module(mixed)
        except Exception:
            if fail_silently:
                return
            raise
    for key, value in iter_settings(mixed):
        context[key] = value

def iter_settings(mixed: Settings) -> Iterator[Tuple[str, Any]]:
    """Iterate over settings values from settings module or dict-like instance.

    :param mixed: Settings instance to iterate."""
    if isinstance(mixed, types.ModuleType):
        for attr in dir(mixed):
            if not is_setting_key(attr):
                continue
            yield (attr, getattr(mixed, attr))
    else:
        yield from filter(lambda item: is_setting_key(item[0]), mixed.items())

def setup_timezone(timezone: str) -> None:
    """Shortcut helper to configure timezone for backend application.

    :param timezone: Timezone to use, e.g. "UTC", "Europe/Kiev"."""
    if timezone and hasattr(time, 'tzset'):
        tz_root = '/usr/share/zoneinfo'
        tz_filename = os.path.join(tz_root, *timezone.split('/'))
        if os.path.exists(tz_root) and (not os.path.exists(tz_filename)):
            raise ValueError('Incorrect timezone value: {0}'.format(timezone))
        os.environ['TZ'] = timezone
        time.tzset()

def extend_with_default(validator_class: Any) -> Any:
    """Append defaults from schema to instance need to be validated.

    :param validator_class: Apply the change for given validator class."""
    validate_properties = validator_class.VALIDATORS['properties']
    def set_defaults(validator: Any, properties: dict, instance: dict, schema: dict) -> Iterator[ValidationError]:
        for prop, subschema in properties.items():
            if 'default' in subschema:
                instance.setdefault(prop, subschema['default'])
        for error in validate_properties(validator, properties, instance, schema):
            yield error
    return extend(validator_class, {'properties': set_defaults})

def process_session_status(irmc_info, session_timeout, upgrade_type):
    """process session for Bios config backup/restore or RAID config operation

    :param irmc_info: node info
    :param session_timeout: session timeout
    :param upgrade_type: flag to check upgrade with bios or irmc
    :return: a dict with following values:
        {
            'upgrade_message': <Message of firmware upgrade mechanism>,
            'upgrade_status'
        }"""
    session_expiration = time.time() + session_timeout
    while time.time() < session_expiration:
        try:
            session = get_firmware_upgrade_status(irmc_info, upgrade_type)
        except SCCIClientError:
            time.sleep(10)
            continue
        status = session.find('./Value').text
        severity = session.find('./Severity').text
        message = session.find('./Message').text
        result = {}
        if severity == 'Information' and status != '0':
            if 'FLASH successful' in message:
                result['upgrade_status'] = 'Complete'
                return result
            time.sleep(5)
        elif severity == 'Error':
            result['upgrade_status'] = 'Error'
            return result
        else:
            session_log = message
            raise SCCIClientError('Failed to set firmware upgrade. Session log is %s.' % session_log)
    else:
        raise SCCISessionTimeout('Failed to time out mechanism with %s.' % session_expiration)

def _convert_netmask(mask):
    """Convert netmask from CIDR format(integer) to doted decimal string."""
    if mask not in range(0, 33):
        raise scci.SCCIInvalidInputError('Netmask value is invalid.')
    return socket.inet_ntoa(struct.pack('!L', int('1' * mask + '0' * (32 - mask), 2)))

def apply_network(network, x, chunksize=None):
    """Apply a pytorch network, potentially in chunks"""
    network_is_cuda = next(network.parameters()).is_cuda
    x = torch.from_numpy(x)
    with torch.no_grad():
        if network_is_cuda:
            x = x.cuda()
        if chunksize is None:
            return from_var(network(x))
        return np.concatenate([from_var(network(x[i:i + chunksize])) for i in range(0, len(x), chunksize)])

