    session = elcm_profile_create(irmc_info, PARAM_PATH_RAID_CONFIG)
    session_timeout = irmc_info.get('irmc_raid_session_timeout', RAID_CONFIG_SESSION_TIMEOUT)
    return _process_session_data(irmc_info, 'CONFIG_RAID', session['Session']['Id'], session_timeout)

def parse_aioredis_url(url: str) -> DictStrAny:
    """Convert Redis URL string to dict suitable to pass to
    ``aioredis.create_redis(...)`` call.

    **Usage**::

        async def connect_redis(url=None):
            url = url or 'redis://localhost:6379/0'
            return await create_redis(**get_aioredis_parts(url))

    :param url: URL to access Redis instance, started with ``redis://``."""
    parts = urlparse(url)
    db = parts.path[1:] or None
    if db:
        db = int(db)
    return {'address': (parts.hostname, parts.port or 6379), 'db': db, 'password': parts.password}

def oggvorbis(s):
    """This is taken from the ogg vorbis spec
    (http://xiph.org/vorbis/doc/Vorbis_I_spec.html)

    :param s: the total length of the window, in samples"""
    try:
        s = np.arange(s)
    except TypeError:
        s = np.arange(s[0])
    i = np.sin((s + 0.5) / len(s) * np.pi) ** 2
    f = np.sin(0.5 * np.pi * i)
    return f * (1.0 / f.max())

