def random_model(ctx, model_class_name):
    """Get a random model identifier by class name. For example::

        # db/fixtures/Category.yml
        {% for i in range(0, 10) %}
        category{{ i }}:
            name: {{ faker.name() }}
        {% endfor %}

        # db/fixtures/Post.yml
        a_blog_post:
            category: {{ random_model('Category') }}

    Will render to something like the following::

        # db/fixtures/Post.yml (rendered)
        a blog_post:
            category: "Category(category7)"

    :param ctx: The context variables of the current template (passed automatically)
    :param model_class_name: The class name of the model to get."""
    model_identifiers = ctx['model_identifiers'][model_class_name]
    if not model_identifiers:
        return 'None'
    idx = random.randrange(0, len(model_identifiers))
    return '"%s(%s)"' % (model_class_name, model_identifiers[idx])

def manual_argument_parsing(argv):
    """sadness because argparse doesn't quite do what we want."""
    if not argv or argv == ['-h'] or argv == ['--help']:
        print_help_and_exit()
    try:
        dashdash_index = argv.index('--')
    except ValueError:
        print_std_err('Must separate command by `--`')
        print_help_and_exit()
    patches, cmd = (argv[:dashdash_index], argv[dashdash_index + 1:])
    if '--help' in patches or '-h' in patches:
        print_help_and_exit()
    if '--all' in patches:
        all_patches = True
        patches.remove('--all')
    else:
        all_patches = False
    unknown_options = [patch for patch in patches if patch.startswith('-')]
    if unknown_options:
        print_std_err('Unknown options: {!r}'.format(unknown_options))
        print_help_and_exit()
    if patches and all_patches:
        print_std_err('--all and patches specified: {!r}'.format(patches))
        print_help_and_exit()
    return Arguments(all=all_patches, patches=tuple(patches), cmd=tuple(cmd))

def make_entry_point(patches, original_entry_point):
    """Use this to make a console_script entry point for your application
    which applies patches.
    :param patches: iterable of pymonkey patches to apply.  Ex: ('my-patch,)
    :param original_entry_point: Such as 'pip'"""
    def entry(argv=None):
        argv = argv if argv is not None else sys.argv[1:]
        return main(tuple(patches) + ('--', original_entry_point) + tuple(argv))
    return entry

def handle_os_exceptions():
    """Handles pycosio exceptions and raise standard OS exceptions."""
    try:
        yield
    except ObjectException:
        exc_type, exc_value, _ = exc_info()
        raise _OS_EXCEPTIONS.get(exc_type, OSError)(exc_value)
    except (OSError, same_file_error, UnsupportedOperation):
        raise
    except Exception:
        exc_type, exc_value, _ = exc_info()
        raise OSError('%s%s' % (exc_type, ', %s' % exc_value if exc_value else ''))

def _text(code, quiet_zone=4):
    """This method returns a text based representation of the QR code.
    This is useful for debugging purposes."""
    buf = io.StringIO()
    border_row = '0' * (len(code[0]) + quiet_zone * 2)
    for b in range(quiet_zone):
        buf.write(border_row)
        buf.write('\n')
    for row in code:
        for b in range(quiet_zone):
            buf.write('0')
        for bit in row:
            if bit == 1:
                buf.write('1')
            elif bit == 0:
                buf.write('0')
            else:
                buf.write(' ')
        for b in range(quiet_zone):
            buf.write('0')
        buf.write('\n')
    for b in range(quiet_zone):
        buf.write(border_row)
        buf.write('\n')
    return buf.getvalue()

def _hex_to_rgb(color):
    """Helper function to convert a color provided in hexadecimal format
    as RGB triple."""
    if color[0] == '#':
        color = color[1:]
    if len(color) == 3:
        color = color[0] * 2 + color[1] * 2 + color[2] * 2
    if len(color) != 6:
        raise ValueError('Input #{0} is not in #RRGGBB format'.format(color))
    return [int(n, 16) for n in (color[:2], color[2:4], color[4:])]

