def which(filename):
    """This takes a given filename; tries to find it in the environment path;
    then checks if it is executable. This returns the full path to the filename
    if found and executable. Otherwise this returns None.

    Note
    ----
    This function is taken from the pexpect module, see module doc-string for
    license."""
    if os.path.dirname(filename) != '' and is_executable_file(filename):
        return filename
    if 'PATH' not in os.environ or os.environ['PATH'] == '':
        p = os.defpath
    else:
        p = os.environ['PATH']
    pathlist = p.split(os.pathsep)
    for path in pathlist:
        ff = os.path.join(path, filename)
        if pty:
            if is_executable_file(ff):
                return ff
        else:
            pathext = os.environ.get('Pathext', '.exe;.com;.bat;.cmd')
            pathext = pathext.split(os.pathsep) + ['']
            for ext in pathext:
                if os.access(ff + ext, os.X_OK):
                    return ff + ext
    return None

def geometric_partitions(iterable, floor=1, ceiling=32768):
    """Partition an iterable into chunks.  Returns an iterator over partitions."""
    partition_size = floor
    run_length = multiprocessing.cpu_count()
    run_count = 0
    try:
        while True:
            partition, iterable = itertools.tee(iterable)
            yield Queryable(partition).take(partition_size)
            for i in range(partition_size):
                next(iterable)
            run_count += 1
            if run_count >= run_length:
                partition_size *= 2
                run_count = 0
            if partition_size > ceiling:
                partition_size = ceiling
    except StopIteration:
        pass

def _dual_decorator(func):
    """This is a decorator that converts a paramaterized decorator for
    no-param use.

    source: http://stackoverflow.com/questions/3888158"""
    @functools.wraps(func)
    def inner(*args, **kwargs):
        if len(args) == 1 and (not kwargs) and callable(args[0]) and (not (type(args[0]) == type and issubclass(args[0], BaseException))):
            return func()(args[0])
        elif len(args) == 2 and inspect.isclass(args[0]) and callable(args[1]):
            return func(args[0], **kwargs)(args[1])
        else:
            return func(*args, **kwargs)
    return inner

