def upload_files_and_create_package(ctx, opts, package_type, owner_repo, dry_run, no_wait_for_sync, wait_interval, skip_errors, sync_attempts, **kwargs):
    """Upload package files and create a new package."""
    owner, repo = owner_repo
    validate_create_package(ctx=ctx, opts=opts, owner=owner, repo=repo, package_type=package_type, skip_errors=skip_errors, **kwargs)
    md5_checksums = {}
    for k, v in kwargs.items():
        if not v or not k.endswith('_file'):
            continue
        md5_checksums[k] = validate_upload_file(ctx=ctx, opts=opts, owner=owner, repo=repo, filepath=v, skip_errors=skip_errors)
    if dry_run:
        click.echo()
        click.secho('You requested a dry run so skipping upload.', fg='yellow')
        return
    for k, v in kwargs.items():
        if not v or not k.endswith('_file'):
            continue
        kwargs[k] = upload_file(ctx=ctx, opts=opts, owner=owner, repo=repo, filepath=v, skip_errors=skip_errors, md5_checksum=md5_checksums[k])
    _, slug = create_package(ctx=ctx, opts=opts, owner=owner, repo=repo, package_type=package_type, skip_errors=skip_errors, **kwargs)
    if no_wait_for_sync:
        return
    wait_for_package_sync(ctx=ctx, opts=opts, owner=owner, repo=repo, slug=slug, wait_interval=wait_interval, skip_errors=skip_errors, attempts=sync_attempts)

def get_package_formats():
    """Get the list of available package formats and parameters."""
    def get_parameters(cls):
        """Build parameters for a package format."""
        params = {}
        dummy_kwargs = {k: 'dummy' for k in cls.swagger_types}
        instance = cls(**dummy_kwargs)
        for k, v in six.iteritems(cls.swagger_types):
            attr = getattr(cls, k)
            docs = attr.__doc__.strip().split('\n')
            doc = (docs[1] if docs[1] else docs[0]).strip()
            try:
                setattr(instance, k, None)
                required = False
            except ValueError:
                required = True
            params[cls.attribute_map.get(k)] = {'type': v, 'help': doc, 'required': required}
        return params
    return {key.replace('PackagesUpload', '').lower(): get_parameters(cls) for key, cls in inspect.getmembers(cloudsmith_api.models) if key.startswith('PackagesUpload')}

def get_package_format_names(predicate=None):
    """Get names for available package formats."""
    return [k for k, v in six.iteritems(get_package_formats()) if not predicate or predicate(k, v)]

def catch_raise_api_exception():
    """Context manager that translates upstream API exceptions."""
    try:
        yield
    except _ApiException as exc:
        detail = None
        fields = None
        if exc.body:
            try:
                data = json.loads(exc.body)
                detail = data.get('detail', None)
                fields = data.get('fields', None)
            except ValueError:
                pass
        detail = detail or exc.reason
        raise ApiException(exc.status, detail=detail, headers=exc.headers, body=exc.body, fields=fields)

def _get_package_status(package):
    """Get the status for a package."""
    status = package['status_str'] or 'Unknown'
    stage = package['stage_str'] or 'Unknown'
    if stage == 'Fully Synchronised':
        return status
    return '%(status)s / %(stage)s' % {'status': status, 'stage': stage}

def listify(val, return_type=tuple):
    """Examples:
        >>> listify('abc', return_type=list)
        ['abc']
        >>> listify(None)
        ()
        >>> listify(False)
        (False,)
        >>> listify(('a', 'b', 'c'), return_type=list)
        ['a', 'b', 'c']"""
    if val is None:
        return return_type()
    elif isiterable(val):
        return return_type(val)
    else:
        return return_type((val,))

