def load_backend(**orm_config):
    """Load the client adaptor module of django_peeringdb
    Assumes config is valid."""
    settings = {}
    settings['SECRET_KEY'] = orm_config.get('secret_key', '')
    db_config = orm_config['database']
    if db_config:
        settings['DATABASES'] = {'default': database_settings(db_config)}
    from django_peeringdb.client_adaptor.setup import configure
    configure(**settings)
    from django_peeringdb.client_adaptor import backend
    migrate = orm_config.get('migrate')
    if migrate and (not backend.Backend().is_database_migrated()):
        backend.Backend().migrate_database()
    return backend

def make_dict(obj):
    """This method creates a dictionary out of a non-builtin object"""
    if is_builtin(obj) or isinstance(obj, OrderedDict):
        return obj
    output_dict = {}
    for key in dir(obj):
        if not key.startswith('__') and (not callable(getattr(obj, key))):
            attr = getattr(obj, key)
            if isinstance(attr, list):
                output_dict[key] = []
                for item in attr:
                    output_dict[key].append(make_dict(item))
            else:
                output_dict[key] = make_dict(attr)
    return output_dict

def get_value(data, key):
    """Follow the dot notation to get the proper field, then perform the action

    Args:
        data: the data as a dictionary (required to be a dictionary)
        key: the key (as dot notation) into the data that gives the field (IP.src)

     Returns:
        the value of the field(subfield) if it exist, otherwise None"""
    ref = data
    try:
        for subkey in key.split('.'):
            if isinstance(ref, dict):
                ref = ref[subkey]
            else:
                print('CRITICAL: Cannot use subkey %s on non-dictionary element' % subkey)
                return None
        return ref
    except KeyError:
        return None

def match_token(token, tok_type, tok_str=None):
    """Returns true if token is of the given type and, if a string is given, has that string."""
    return token.type == tok_type and (tok_str is None or token.string == tok_str)

def expect_token(token, tok_type, tok_str=None):
    """Verifies that the given token is of the expected type. If tok_str is given, the token string
    is verified too. If the token doesn't match, raises an informative ValueError."""
    if not match_token(token, tok_type, tok_str):
        raise ValueError('Expected token %s, got %s on line %s col %s' % (token_repr(tok_type, tok_str), str(token), token.start[0], token.start[1] + 1))

def _cellrepr(value, allow_formulas):
    """Get a string representation of dataframe value.

    :param :value: the value to represent
    :param :allow_formulas: if True, allow values starting with '='
            to be interpreted as formulas; otherwise, escape
            them with an apostrophe to avoid formula interpretation."""
    if pd.isnull(value) is True:
        return ''
    if isinstance(value, float):
        value = repr(value)
    else:
        value = str(value)
    if not allow_formulas and value.startswith('='):
        value = "'%s" % value
    return value

def _resize_to_minimum(worksheet, rows=None, cols=None):
    """Resize the worksheet to guarantee a minimum size, either in rows,
    or columns, or both.

    Both rows and cols are optional."""
    current_cols, current_rows = (worksheet.col_count, worksheet.row_count)
    if rows is not None and rows <= current_rows:
        rows = None
    if cols is not None and cols <= current_cols:
        cols = None
    if cols is not None or rows is not None:
        worksheet.resize(rows, cols)

def reader(stream, fieldnames=None):
    """Read Items from a stream containing TSV."""
    if not fieldnames:
        fieldnames = load_line(stream.readline())
    for line in stream:
        values = load_line(line)
        item = Item()
        item.__dict__ = dict(zip(fieldnames, values))
        yield item

def dump(self):
    """TSV representation."""
    dict = self.primitive
    if not dict:
        return ''
    return dump_line(self.keys) + dump_line(self.values)

def load(self, text, lineterminator='\r\n', quotechar='"', delimiter=',', escapechar=escapechar, quoting=csv.QUOTE_MINIMAL):
    """Item from CSV representation."""
    f = io.StringIO(text)
    if not quotechar:
        quoting = csv.QUOTE_NONE
    reader = csv.DictReader(f, delimiter=delimiter, quotechar=quotechar, quoting=quoting, lineterminator=lineterminator)
    if reader.fieldnames:
        reader.fieldnames = [field.strip() for field in reader.fieldnames]
    try:
        self.primitive = next(reader)
    except StopIteration:
        self.primitive = {}

def git_hash(blob):
    """Return git-hash compatible SHA-1 hexdigits for a blob of data."""
    head = str('blob ' + str(len(blob)) + '\x00').encode('utf-8')
    return sha1(head + blob).hexdigest()

def dump(self):
    """Item as a JSON representation."""
    return json.dumps(self.primitive, sort_keys=True, ensure_ascii=False, separators=(',', ':'))

def reader(stream):
    """Read Items from a stream containing lines of JSON."""
    for line in stream:
        item = Item()
        item.json = line
        yield item

