def yes_or_no(question, default='yes'):
    """Ask a yes/no question via input() and return their answer.

    "question" is a string that is presented to the user.
    "default" is the presumed answer if the user just hits <Enter>.
        It must be "yes" (the default), "no" or None (meaning
        an answer is required of the user).

    The "answer" return value is True for "yes" or False for "no"."""
    valid = {'yes': True, 'y': True, 'ye': True, 'no': False, 'n': False}
    if default is None:
        prompt = ' [y/n] '
    elif default == 'yes':
        prompt = ' [Y/n] '
    elif default == 'no':
        prompt = ' [y/N] '
    else:
        raise ValueError("invalid default answer: '%s'" % default)
    while True:
        sys.stdout.write('{}[nbinteract]{} {}{}'.format(BLUE, NOCOLOR, question, prompt))
        choice = input().lower()
        if default is not None and choice == '':
            return valid[default]
        elif choice in valid:
            return valid[choice]
        else:
            sys.stdout.write("Please respond with 'yes' or 'no' (or 'y' or 'n').\n")

def expand_folder(notebook_or_folder, recursive=False):
    """If notebook_or_folder is a folder, returns a list containing all notebooks
    in the folder. Otherwise, returns a list containing the notebook name.

    If recursive is True, recurses into subdirectories."""
    is_file = os.path.isfile(notebook_or_folder)
    is_dir = os.path.isdir(notebook_or_folder)
    if not (is_file or is_dir):
        raise ValueError('{} is neither an existing file nor a folder.'.format(notebook_or_folder))
    if is_file:
        return [notebook_or_folder]
    if not recursive:
        return glob('{}/*.ipynb'.format(notebook_or_folder))
    return [os.path.join(folder, filename) for folder, _, filenames in os.walk(notebook_or_folder) if not os.path.basename(folder).startswith('.') for filename in fnmatch.filter(filenames, '*.ipynb')]

