def ad_unif_inf(statistic):
    """Approximates the limiting distribution to about 5 decimal digits."""
    z = statistic
    if z < 2:
        return exp(-1.2337141 / z) / sqrt(z) * (2.00012 + (0.247105 - (0.0649821 - (0.0347962 - (0.011672 - 0.00168691 * z) * z) * z) * z) * z)
    else:
        return exp(-exp(1.0776 - (2.30695 - (0.43424 - (0.082433 - (0.008056 - 0.0003146 * z) * z) * z) * z) * z))

def ad_unif_fix(samples, pinf):
    """Corrects the limiting distribution for a finite sample size."""
    n = samples
    c = 0.01265 + 0.1757 / n
    if pinf < c:
        return ((0.0037 / n + 0.00078) / n + 6e-05) / n * g1(pinf / c)
    elif pinf < 0.8:
        return (0.01365 / n + 0.04213) / n * g2((pinf - c) / (0.8 - c))
    else:
        return g3(pinf) / n

def vectorize(*args, **kwargs):
    """Allows using `@vectorize` as well as `@vectorize()`."""
    if args and callable(args[0]):
        return _vectorize(args[0])
    else:
        return lambda m: _vectorize(m, *args, **kwargs)

def varange(starts, count):
    """Vectorized `arange()` taking a sequence of starts and a count of elements.

    For example::

        >>> varange(1, 5)
        array([1, 2, 3, 4, 5])

        >>> varange((1, 3), 5)
        array([[1, 2, 3, 4, 5],
               [3, 4, 5, 6, 7]])"""
    try:
        return stack((arange(s, s + count) for s in starts))
    except TypeError:
        return arange(starts, starts + count)

def conditional_http_tween_factory(handler, registry):
    """Tween that adds ETag headers and tells Pyramid to enable
    conditional responses where appropriate."""
    settings = registry.settings if hasattr(registry, 'settings') else {}
    not_cacheble_list = []
    if 'not.cachable.list' in settings:
        not_cacheble_list = settings.get('not.cachable.list').split()
    def conditional_http_tween(request):
        response = handler(request)
        if request.path not in not_cacheble_list:
            if response.last_modified is not None:
                response.conditional_response = True
            if response.etag is not None:
                response.conditional_response = True
            elif (isinstance(response.app_iter, Sequence) and len(response.app_iter) == 1) and response.body is not None:
                response.conditional_response = True
                response.md5_etag()
        return response
    return conditional_http_tween

