def cvm_stat(data):
    """Calculates the Cramer-von Mises statistic for sorted values from U(0, 1)."""
    samples2 = 2 * len(data)
    minuends = arange(1, samples2, 2) / samples2
    return 1 / (6 * samples2) + ((minuends - data) ** 2).sum()

def audit_with_request(**kwargs):
    """use this decorator to audit an operation with a request as input variable"""
    def wrap(fn):
        @audit(**kwargs)
        def operation(parent_object, *args, **kw):
            return fn(parent_object.request, *args, **kw)
        @functools.wraps(fn)
        def advice_with_request(the_request, *args, **kw):
            class ParentObject:
                request = the_request
            return operation(ParentObject(), *args, **kw)
        return advice_with_request
    return wrap

def cast_datetime_filter(value):
    """Cast a datetime filter value.

    :param value: string representation of a value that needs to be casted to
        a `datetime` object."""
    if isinstance(value, str):
        dtime = parse_datetime(value)
    elif isinstance(value, datetime):
        dtime = value
    else:
        raise ValueError('Received value of type {0}'.format(type(value)))
    return dtime.isoformat()

def filter_args_to_dict(filter_dict, accepted_filter_keys=[]):
    """Cast and validate filter args.

    :param filter_dict: Filter kwargs
    :param accepted_filter_keys: List of keys that are acceptable to use."""
    out_dict = {}
    for k, v in filter_dict.items():
        if k not in accepted_filter_keys or v is None:
            logger.debug('Filter was not in accepted_filter_keys or value is None.')
            continue
        filter_type = filter_type_map.get(k, None)
        if filter_type is None:
            logger.debug('Filter key not foud in map.')
            continue
        filter_cast_map = {'int': cast_integer_filter, 'datetime': cast_datetime_filter}
        cast_function = filter_cast_map.get(filter_type, None)
        if cast_function:
            out_value = cast_function(v)
        else:
            out_value = v
        out_dict[k] = out_value
    return out_dict

def change_password():
    """Changes the standard password from neo4j to testing to be able to run the test suite."""
    basic_auth = '%s:%s' % (DEFAULT_USERNAME, DEFAULT_PASSWORD)
    try:
        auth = base64.encodestring(basic_auth)
    except TypeError:
        auth = base64.encodestring(bytes(basic_auth, 'utf-8')).decode()
    headers = {'Content-Type': 'application/json', 'Accept': 'application/json', 'Authorization': 'Basic %s' % auth.strip()}
    response = None
    retry = 0
    while not response:
        sleep(1)
        con = http.HTTPConnection('localhost:7474', timeout=10)
        try:
            con.request('GET', 'http://localhost:7474/user/neo4j', headers=headers)
            response = json.loads(con.getresponse().read().decode('utf-8'))
        except ValueError:
            con.close()
        retry += 1
        if retry > 10:
            print('Could not change password for user neo4j')
            break
    if response and response.get('password_change_required', None):
        payload = json.dumps({'password': 'testing'})
        con.request('POST', 'http://localhost:7474/user/neo4j/password', payload, headers)
        print('Password changed for user neo4j')
    con.close()

