def get_mutation_rates(transcripts, mut_dict, ensembl):
    """determines mutation rates per functional category for transcripts

    Args:
        transcripts: list of transcript IDs for a gene
        mut_dict: dictionary of local sequence context mutation rates
        ensembl: EnsemblRequest object, to retrieve information from Ensembl.

    Returns:
        tuple of (rates, merged transcript, and transcript CDS length)"""
    rates = {'missense': 0, 'nonsense': 0, 'splice_lof': 0, 'splice_region': 0, 'synonymous': 0}
    combined = None
    for tx_id in transcripts:
        try:
            tx = construct_gene_object(ensembl, tx_id)
        except ValueError:
            continue
        if len(tx.get_cds_sequence()) % 3 != 0:
            raise ValueError('anomalous_coding_sequence')
        if tx.get_chrom() == 'MT':
            continue
        sites = SiteRates(tx, mut_dict, masked_sites=combined)
        combined = tx + combined
        for cq in ['missense', 'nonsense', 'splice_lof', 'splice_region', 'synonymous']:
            rates[cq] += sites[cq].get_summed_rate()
    if combined is None:
        raise ValueError('no tx found')
    length = combined.get_coding_distance(combined.get_cds_end())['pos']
    return (rates, combined, length)

def log_transform(rates):
    """log transform a numeric value, unless it is zero, or negative
    """
    transformed = []
    for key in ['missense', 'nonsense', 'splice_lof', 'splice_region', 'synonymous']:
        try:
            value = math.log10(rates[key])
        except ValueError:
            value = 'NA'
        except KeyError:
            continue
        transformed.append(value)
    return '\t'.join(map(str, transformed))

def get_usersettings_model():
    """Returns the ``UserSettings`` model that is active in this project."""
    try:
        from django.apps import apps
        get_model = apps.get_model
    except ImportError:
        from django.db.models.loading import get_model
    try:
        app_label, model_name = settings.USERSETTINGS_MODEL.split('.')
    except ValueError:
        raise ImproperlyConfigured('USERSETTINGS_MODEL must be of the form "app_label.model_name"')
    usersettings_model = get_model(app_label, model_name)
    if usersettings_model is None:
        raise ImproperlyConfigured('USERSETTINGS_MODEL refers to model "%s" that has not been installed' % settings.USERSETTINGS_MODEL)
    return usersettings_model

