def count_missense_per_gene(lines):
    """count the number of missense variants in each gene.
    """
    counts = {}
    for x in lines:
        x = x.split('\t')
        gene = x[0]
        consequence = x[3]
        if gene not in counts:
            counts[gene] = 0
        if consequence != 'missense_variant':
            continue
        counts[gene] += 1
    return counts

def Printer(open_file=sys.stdout, closing=False):
    """Prints items with a timestamp."""
    try:
        while True:
            logstr = (yield)
            open_file.write(logstr)
            open_file.write('\n')
    except GeneratorExit:
        if closing:
            try:
                open_file.close()
            except:
                pass

