def is_first_instance_k8s(current_pod_name=None):
    """Returns True if the current pod is the first replica in Kubernetes cluster."""
    current_pod_name = current_pod_name or os.environ.get('POD_NAME')
    if not current_pod_name:
        raise StackInterrogationException('Pod name not known')
    namespace = 'money-to-prisoners-%s' % settings.ENVIRONMENT
    try:
        load_incluster_config()
    except ConfigException as e:
        raise StackInterrogationException(e)
    try:
        response = k8s_client.CoreV1Api().list_namespaced_pod(namespace=namespace, label_selector='app=%s' % settings.APP, watch=False)
    except ApiException as e:
        raise StackInterrogationException(e)
    pod_names = sorted((pod.metadata.name for pod in filter(lambda pod: pod.status.phase == 'Running', response.items)))
    return bool(pod_names and pod_names[0] == current_pod_name)

def splitarg(args):
    """This function will split arguments separated by spaces or commas
    to be backwards compatible with the original ArcGet command line tool"""
    if not args:
        return args
    split = list()
    for arg in args:
        if ',' in arg:
            split.extend([x for x in arg.split(',') if x])
        elif arg:
            split.append(arg)
    return split

def login(request, template_name=None, redirect_field_name=REDIRECT_FIELD_NAME, authentication_form=AuthenticationForm, current_app=None, extra_context=None):
    """Displays the login form and handles the login action."""
    redirect_to = request.POST.get(redirect_field_name, request.GET.get(redirect_field_name, ''))
    def get_redirect_to():
        if not is_safe_url(url=redirect_to, host=request.get_host()):
            return resolve_url(settings.LOGIN_REDIRECT_URL)
        return redirect_to
    if request.user.is_authenticated:
        return HttpResponseRedirect(get_redirect_to())
    if request.method == 'POST':
        form = authentication_form(request=request, data=request.POST)
        if form.is_valid():
            auth_login(request, form.get_user())
            return HttpResponseRedirect(get_redirect_to())
    else:
        form = authentication_form(request=request)
    current_site = get_current_site(request)
    context = {'form': form, redirect_field_name: redirect_to, 'site': current_site, 'site_name': current_site.name}
    if extra_context is not None:
        context.update(extra_context)
    if current_app is not None:
        request.current_app = current_app
    return TemplateResponse(request, template_name, context)

def logout(request, template_name=None, next_page=None, redirect_field_name=REDIRECT_FIELD_NAME, current_app=None, extra_context=None):
    """Logs out the user."""
    auth_logout(request)
    if next_page is not None:
        next_page = resolve_url(next_page)
    if redirect_field_name in request.POST or redirect_field_name in request.GET:
        next_page = request.POST.get(redirect_field_name, request.GET.get(redirect_field_name))
        if not is_safe_url(url=next_page, host=request.get_host()):
            next_page = request.path
    if next_page:
        return HttpResponseRedirect(next_page)
    current_site = get_current_site(request)
    context = {'site': current_site, 'site_name': current_site.name, 'title': _('Logged out')}
    if extra_context is not None:
        context.update(extra_context)
    if current_app is not None:
        request.current_app = current_app
    return TemplateResponse(request, template_name, context)

