def get_table_info(*table_names):
    """Returns a dict with table_name keys mapped to the Interface that table exists in

    :param *table_names: the tables you are searching for"""
    ret = {}
    if table_names:
        for table_name in table_names:
            for name, inter in get_interfaces().items():
                if inter.has_table(table_name):
                    yield (table_name, inter, inter.get_fields(table_name))
    else:
        for name, inter in get_interfaces().items():
            table_names = inter.get_tables()
            for table_name in table_names:
                yield (table_name, inter, inter.get_fields(table_name))

def match_sp_sep(first, second):
    """Verify that all the values in 'first' appear in 'second'.
    The values can either be in the form of lists or as space separated
    items.

    :param first:
    :param second:
    :return: True/False"""
    if isinstance(first, list):
        one = [set(v.split(' ')) for v in first]
    else:
        one = [{v} for v in first.split(' ')]
    if isinstance(second, list):
        other = [set(v.split(' ')) for v in second]
    else:
        other = [{v} for v in second.split(' ')]
    if any((rt not in other for rt in one)):
        return False
    return True

def ver_dec_content(parts, sign_key=None, enc_key=None, sign_alg='SHA256'):
    """Verifies the value of a cookie

    :param parts: The parts of the payload
    :param sign_key: A :py:class:`cryptojwt.jwk.hmac.SYMKey` instance
    :param enc_key: A :py:class:`cryptojwt.jwk.hmac.SYMKey` instance
    :param sign_alg: Which signing algorithm to was used
    :return: A tuple with basic information and a timestamp"""
    if parts is None:
        return None
    elif len(parts) == 3:
        timestamp, load, b64_mac = parts
        mac = base64.b64decode(b64_mac)
        verifier = HMACSigner(algorithm=sign_alg)
        if verifier.verify(load.encode('utf-8') + timestamp.encode('utf-8'), mac, sign_key.key):
            return (load, timestamp)
        else:
            raise VerificationError()
    elif len(parts) == 4:
        b_timestamp = parts[0]
        iv = base64.b64decode(parts[1])
        ciphertext = base64.b64decode(parts[2])
        tag = base64.b64decode(parts[3])
        decrypter = AES_GCMEncrypter(key=enc_key.key)
        msg = decrypter.decrypt(ciphertext, iv, tag=tag)
        p = lv_unpack(msg.decode('utf-8'))
        load = p[0]
        timestamp = p[1]
        if len(p) == 3:
            verifier = HMACSigner(algorithm=sign_alg)
            if verifier.verify(load.encode('utf-8') + timestamp.encode('utf-8'), base64.b64decode(p[2]), sign_key.key):
                return (load, timestamp)
        else:
            return (load, timestamp)
    return None

def cookie_parts(name, kaka):
