def escape_header(val):
    """Escapes a value so that it can be used in a mime header"""
    if val is None:
        return None
    try:
        return quote(val, encoding='ascii', safe='/ ')
    except ValueError:
        return "utf-8''" + quote(val, encoding='utf-8', safe='/ ')

def make_streams(name, value, boundary, encoding):
    """Generates one or more streams for each name, value pair"""
    filename = None
    mime = None
    if isinstance(value, collections.Mapping) and 'name' in value and ('value' in value):
        filename = value['name']
        try:
            mime = value['mime']
        except KeyError:
            pass
        value = value['value']
    if not filename:
        filename = getattr(value, 'name', None)
        if filename:
            filename = os.path.split(filename)[1]
    mime = mime or 'application/octet-stream'
    name, filename, mime = [escape_header(v) for v in (name, filename, mime)]
    stream = BytesIO()
    stream.write('--{}\r\n'.format(boundary).encode(encoding))
    if not filename:
        stream.write('Content-Disposition: form-data; name="{}"\r\n'.format(name).encode(encoding))
    else:
        stream.write('Content-Disposition: form-data; name="{}"; filename="{}"\r\n'.format(name, filename).encode(encoding))
        if mime:
            stream.write('Content-Type: {}\r\n'.format(mime).encode(encoding))
    stream.write(b'\r\n')
    if hasattr(value, 'read'):
        stream.seek(0)
        return (stream, value, BytesIO('\r\n'.encode(encoding)))
    value = value if isinstance(value, (str, bytes)) else json.dumps(value)
    if isinstance(value, bytes):
        stream.write(value)
    else:
        stream.write(value.encode(encoding))
    stream.write(b'\r\n')
    stream.seek(0)
    return (stream,)

def listen(room):
    """Open a volafile room and start listening to it"""
    def onmessage(m):
        """Print the new message and respond to it."""
        print(m)
        if m.admin or m.nick == r.user.name:
            return
        if 'parrot' in m.msg.lower():
            r.post_chat('ayy lmao')
        elif m.msg.lower() in ('lol', 'lel', 'kek'):
            r.post_chat('*kok')
        else:
            r.post_chat(re.sub('\\blain\\b', 'purpleadmin', m.msg, re.I))
    with Room(room) as r:
        r.user.change_nick('DumbParrot')
        r.add_listener('chat', onmessage)
        r.listen()

def build_endpoints(conf, endpoint_context, client_authn_method, issuer):
    """conf typically contains::

        'provider_config': {
            'path': '.well-known/openid-configuration',
            'class': ProviderConfiguration,
            'kwargs': {}
        },

    :param conf:
    :param endpoint_context:
    :param client_authn_method:
    :param issuer:
    :return:"""
    if issuer.endswith('/'):
        _url = issuer[:-1]
    else:
        _url = issuer
    endpoint = {}
    for name, spec in conf.items():
        try:
            kwargs = spec['kwargs']
        except KeyError:
            kwargs = {}
        if isinstance(spec['class'], str):
            _instance = importer(spec['class'])(endpoint_context=endpoint_context, **kwargs)
        else:
            _instance = spec['class'](endpoint_context=endpoint_context, **kwargs)
        _instance.endpoint_path = spec['path']
        _instance.full_path = '{}/{}'.format(_url, spec['path'])
        if 'provider_info' in spec:
            _instance.provider_info = spec['provider_info']
        try:
            _client_authn_method = kwargs['client_authn_method']
        except KeyError:
            _instance.client_auth_method = client_authn_method
        else:
            _instance.client_auth_method = _client_authn_method
        endpoint[name] = _instance
    return endpoint

def lv_pack(*args):
    """Serializes using length:value format

    :param args: values
    :return: string"""
    s = []
    for a in args:
        s.append('{}:{}'.format(len(a), a))
    return ''.join(s)

def with_meta(class_to_decorate=None, add_init_kwargs=True):
    """Class decorator to enable a class (and it's sub-classes) to have a 'Meta' class attribute.

    :type class_to_decorate: class
    :param bool add_init_kwargs: Pass Meta class members to constructor

    :rtype: class"""
    if class_to_decorate is None:
        return functools.partial(with_meta, add_init_kwargs=add_init_kwargs)
    if add_init_kwargs:
        def get_extra_args_function(self):
            return {k: v for k, v in self.get_meta().items() if not k.startswith('_')}
        add_args_to_init_call(class_to_decorate, get_extra_args_function)
    setattr(class_to_decorate, 'get_meta', classmethod(get_meta))
    return class_to_decorate

def get_meta(cls):
    """Collect all members of any contained :code:`Meta` class declarations from the given class or any of its base classes.
    (Sub class values take precedence.)

    :type cls: class
    :rtype: Struct"""
    merged_attributes = Struct()
    for class_ in reversed(cls.mro()):
        if hasattr(class_, 'Meta'):
            for key, value in class_.Meta.__dict__.items():
                merged_attributes[key] = value
    return merged_attributes

def get_signature(func):
    """:type func: Callable
    :rtype: str"""
    try:
        return object.__getattribute__(func, '__tri_declarative_signature')
    except AttributeError:
        pass
    try:
        if sys.version_info[0] < 3:
            names, _, varkw, defaults = inspect.getargspec(func)
        else:
            names, _, varkw, defaults, _, _, _ = inspect.getfullargspec(func)
    except TypeError:
        return None
    first_arg_index = 1 if inspect.ismethod(func) else 0
    number_of_defaults = len(defaults) if defaults else 0
    if number_of_defaults > 0:
        required = ','.join(sorted(names[first_arg_index:-number_of_defaults]))
        optional = ','.join(sorted(names[-number_of_defaults:]))
    else:
        required = ','.join(sorted(names[first_arg_index:]))
        optional = ''
    wildcard = '*' if varkw is not None else ''
    signature = '|'.join((required, optional, wildcard))
    try:
        object.__setattr__(func, '__tri_declarative_signature', signature)
    except TypeError:
        type.__setattr__(func, '__tri_declarative_signature', signature)
    except AttributeError:
        pass
    return signature

def extract_subkeys(kwargs, prefix, defaults=None):
    """Extract mappings of the shape '<base_key>__<sub_key>' to new mappings under '<sub_key>'.

    >>> foo = {
    ...     'foo__foo': 1,
    ...     'foo__bar': 2,
    ...     'baz': 3,
    ... }
    >>> assert extract_subkeys(foo, 'foo', defaults={'quux': 4}) == {
    ...     'foo': 1,
    ...     'bar': 2,
    ...     'quux': 4,
    ... }

    :type kwargs: dict
    :rtype: dict"""
    prefix += '__'
    result = {k[len(prefix):]: v for k, v in kwargs.items() if k.startswith(prefix)}
    if defaults is not None:
        return setdefaults(result, defaults)
    else:
        return result

def getattr_path(obj, path):
    """Get an attribute path, as defined by a string separated by '__'.
    getattr_path(foo, 'a__b__c') is roughly equivalent to foo.a.b.c but
    will short circuit to return None if something on the path is None."""
    path = path.split('__')
    for name in path:
        obj = getattr(obj, name)
        if obj is None:
            return None
    return obj

def reg_copy(reg, keys=None):
    """Make a copy of a subset of a registry.

    :param reg: source registry
    :param keys: keys of registry items to copy
    :return: copied registry subset"""
    if keys is None:
        keys = reg.keys()
    reg_cls = type(reg)
    new_reg = reg_cls()
    mk = {}
    for m in reg_cls.meta_names:
        mstar = getattr(reg, m, None)
        if not mstar:
            mk[m] = None
            continue
        mk[m] = {}
        for k in keys:
            kstar = mstar.get(k)
            if kstar is not None:
                mk[m][k] = kstar
    new_reg.register({k: reg[k] for k in keys}, **mk)
    return new_reg

def listen_many(*rooms):
    """Listen for changes in all registered listeners in all specified rooms"""
    rooms = set((r.conn for r in rooms))
    for room in rooms:
        room.validate_listeners()
    with ARBITRATOR.condition:
        while any((r.connected for r in rooms)):
            ARBITRATOR.condition.wait()
            rooms = [r for r in rooms if r.run_queues()]
            if not rooms:
                return

def _apply_units_to_numpy_data_readers(parameters, data):
    """Apply units to data originally loaded by :class:`NumPyLoadTxtReader` or
    :class:`NumPyGenFromTxtReader`.

    :param parameters: Dictionary of data source parameters read from JSON
        file.
    :type parameters: dict
    :param data: Dictionary of data read"""
    header_param = parameters.get('header')
    if header_param:
        fields = header_param['fields']
        header_fields = {field[0]: field[1:] for field in fields}
        for k, val in header_fields.iteritems():
            if len(val) > 1:
                data[k] *= UREG(str(val[1]))
    data_units = parameters['data'].get('units')
    if data_units:
        for k, val in data_units.iteritems():
            data[k] *= UREG(str(val))
    return data

def make_dict(fields, fields_kwargs):
    """lot's of methods take a dict or kwargs, this combines those

    Basically, we do a lot of def method(fields, **kwargs) and we want to merge
    those into one super dict with kwargs taking precedence, this does that

    fields -- dict -- a passed in dict
    fields_kwargs -- dict -- usually a **kwargs dict from another function

    return -- dict -- a merged fields and fields_kwargs"""
    ret = {}
    if fields:
        ret.update(fields)
    if fields_kwargs:
        ret.update(fields_kwargs)
    return ret

