def process_wildcard(fractions):
    """Processes element with a wildcard ``?`` weight fraction and returns
    composition balanced to 1.0."""
    wildcard_zs = set()
    total_fraction = 0.0
    for z, fraction in fractions.items():
        if fraction == '?':
            wildcard_zs.add(z)
        else:
            total_fraction += fraction
    if not wildcard_zs:
        return fractions
    balance_fraction = (1.0 - total_fraction) / len(wildcard_zs)
    for z in wildcard_zs:
        fractions[z] = balance_fraction
    return fractions

def convert_mass_to_atomic_fractions(mass_fractions):
    """Converts a mass fraction :class:`dict` to an atomic fraction :class:`dict`.

    Args:
        mass_fractions (dict): mass fraction :class:`dict`.
            The composition is specified by a dictionary.
            The keys are atomic numbers and the values weight fractions.
            No wildcard are accepted."""
    atomic_fractions = {}
    for z, mass_fraction in mass_fractions.items():
        atomic_fractions[z] = mass_fraction / pyxray.element_atomic_weight(z)
    total_fraction = sum(atomic_fractions.values())
    for z, fraction in atomic_fractions.items():
        try:
            atomic_fractions[z] = fraction / total_fraction
        except ZeroDivisionError:
            atomic_fractions[z] = 0.0
    return atomic_fractions

def convert_formula_to_atomic_fractions(formula):
    """Converts a chemical formula to an atomic fraction :class:`dict`.

    Args:
        formula (str): chemical formula, like Al2O3. No wildcard are accepted."""
    mole_fractions = {}
    total_mole_fraction = 0.0
    for match in CHEMICAL_FORMULA_PATTERN.finditer(formula):
        symbol, mole_fraction = match.groups()
        z = pyxray.element_atomic_number(symbol.strip())
        if mole_fraction == '':
            mole_fraction = 1.0
        mole_fraction = float(mole_fraction)
        mole_fraction = float(mole_fraction)
        mole_fractions[z] = mole_fraction
        total_mole_fraction += mole_fraction
    atomic_fractions = {}
    for z, mole_fraction in mole_fractions.items():
        atomic_fractions[z] = mole_fraction / total_mole_fraction
    return atomic_fractions

def generate_name(atomic_fractions):
    """Generates a name from the composition.
    The name is generated on the basis of a classical chemical formula."""
    if not atomic_fractions:
        return ''
    if len(atomic_fractions) == 1:
        z = list(atomic_fractions.keys())[0]
        return pyxray.element_symbol(z)
    symbols = []
    fractions = []
    for z in sorted(atomic_fractions.keys(), reverse=True):
        symbols.append(pyxray.element_symbol(z))
        fractions.append(Fraction(atomic_fractions[z]).limit_denominator())
    gcds = []
    for a, b in itertools.combinations(fractions, 2):
        gcds.append(math.gcd(a.denominator, b.denominator))
    smallest_gcd = min(gcds)
    name = ''
    for symbol, fraction in zip(symbols, fractions):
        mole_fraction = int(fraction * smallest_gcd)
        if mole_fraction == 0:
            continue
        elif mole_fraction == 1:
            name += '%s' % symbol
        else:
            name += '%s%i' % (symbol, mole_fraction)
    return name

def claims_match(value, claimspec):
    """Implements matching according to section 5.5.1 of
    http://openid.net/specs/openid-connect-core-1_0.html
    The lack of value is not checked here.
    Also the text doesn't prohibit having both 'value' and 'values'.

    :param value: single value
    :param claimspec: None or dictionary with 'essential', 'value' or 'values'
        as key
    :return: Boolean"""
    if claimspec is None:
        return True
    matched = False
    for key, val in claimspec.items():
        if key == 'value':
            if value == val:
                matched = True
        elif key == 'values':
            if value in val:
                matched = True
        elif key == 'essential':
            continue
        if matched:
            break
    if matched is False:
        if list(claimspec.keys()) == ['essential']:
            return True
    return matched

def userinfo_in_id_token_claims(endpoint_context, session, def_itc=None):
    """Collect user info claims that are to be placed in the id token.

    :param endpoint_context: Endpoint context
    :param session: Session information
    :param def_itc: Default ID Token claims
    :return: User information or None"""
    if def_itc:
        itc = def_itc
    else:
        itc = {}
    itc.update(id_token_claims(session))
    if not itc:
        return None
    _claims = by_schema(endpoint_context.id_token_schema, **itc)
    if _claims:
        return collect_user_info(endpoint_context, session, _claims)
    else:
        return None

def call_async(func):
    """Decorates a function to be called async on the loop thread"""
    @wraps(func)
    def wrapper(self, *args, **kw):
        """Wraps instance method to be called on loop thread"""
        def call():
            """Calls function on loop thread"""
            try:
                func(self, *args, **kw)
            except Exception:
                logger.exception('failed to call async [%r] with [%r] [%r]', func, args, kw)
        self.loop.call_soon_threadsafe(call)
    return wrapper

def call_sync(func):
    """Decorates a function to be called sync on the loop thread"""
    @wraps(func)
    def wrapper(self, *args, **kw):
        """Wraps instance method to be called on loop thread"""
        if self.thread.ident == get_ident():
            return func(self, *args, **kw)
        barrier = Barrier(2)
        result = None
        ex = None
        def call():
            """Calls function on loop thread"""
            nonlocal result, ex
            try:
                result = func(self, *args, **kw)
            except Exception as exc:
                ex = exc
            finally:
                barrier.wait()
        self.loop.call_soon_threadsafe(call)
        barrier.wait()
        if ex:
            raise ex or Exception('Unknown error')
        return result
    return wrapper

def groupby_freq(items, times, freq, wkst='SU'):
    """Group timeseries by frequency. The frequency must be a string in the
    following list: YEARLY, MONTHLY, WEEKLY, DAILY, HOURLY, MINUTELY or
    SECONDLY. The optional weekstart must be a string in the following list:
    MO, TU, WE, TH, FR, SA and SU.

    :param items: items in timeseries
    :param times: times corresponding to items
    :param freq: One of the ``dateutil.rrule`` frequency constants
    :type freq: str
    :param wkst: One of the ``dateutil.rrule`` weekday constants
    :type wkst: str
    :return: generator"""
    timeseries = zip(times, items)
    if freq.upper() == 'DAILY':
        def key(ts_):
            return ts_[0].day
    elif freq.upper() == 'WEEKLY':
        weekday = getattr(rrule, wkst.upper())
        days = (day for day in times if day.weekday() == weekday.weekday)
        day0 = days.next()
        def key(ts_):
            return (ts_[0] - day0).days // 7
    else:
        def key(ts_):
            return getattr(ts_[0], freq.lower()[:-2])
    for k, ts in itertools.groupby(timeseries, key):
        yield (k, ts)

def fetch_resources(uri, rel):
    """Retrieves embeddable resource from given ``uri``.

    For now only local resources (images, fonts) are supported.

    :param str uri: path or url to image or font resource
    :returns: path to local resource file.
    :rtype: str
    :raises: :exc:`~easy_pdf.exceptions.UnsupportedMediaPathException`"""
    if settings.STATIC_URL and uri.startswith(settings.STATIC_URL):
        path = os.path.join(settings.STATIC_ROOT, uri.replace(settings.STATIC_URL, ''))
    elif settings.MEDIA_URL and uri.startswith(settings.MEDIA_URL):
        path = os.path.join(settings.MEDIA_ROOT, uri.replace(settings.MEDIA_URL, ''))
    else:
        path = os.path.join(settings.STATIC_ROOT, uri)
    if not os.path.isfile(path):
        raise UnsupportedMediaPathException('media urls must start with {} or {}'.format(settings.MEDIA_ROOT, settings.STATIC_ROOT))
    return path.replace('\\', '/')

def html_to_pdf(content, encoding='utf-8', link_callback=fetch_resources, **kwargs):
    """Converts html ``content`` into PDF document.

    :param unicode content: html content
    :returns: PDF content
    :rtype: :class:`bytes`
    :raises: :exc:`~easy_pdf.exceptions.PDFRenderingError`"""
    src = BytesIO(content.encode(encoding))
    dest = BytesIO()
    pdf = pisa.pisaDocument(src, dest, encoding=encoding, link_callback=link_callback, **kwargs)
    if pdf.err:
        logger.error('Error rendering PDF document')
        for entry in pdf.log:
            if entry[0] == xhtml2pdf.default.PML_ERROR:
                logger_x2p.error('line %s, msg: %s, fragment: %s', entry[1], entry[2], entry[3])
        raise PDFRenderingError('Errors rendering PDF', content=content, log=pdf.log)
    if pdf.warn:
        for entry in pdf.log:
            if entry[0] == xhtml2pdf.default.PML_WARNING:
                logger_x2p.warning('line %s, msg: %s, fragment: %s', entry[1], entry[2], entry[3])
    return dest.getvalue()

def compile_patterns_in_dictionary(dictionary):
    """Replace all strings in dictionary with compiled
    version of themselves and return dictionary."""
    for key, value in dictionary.items():
        if isinstance(value, str):
            dictionary[key] = re.compile(value)
        elif isinstance(value, dict):
            compile_patterns_in_dictionary(value)
    return dictionary

def explode(prefix: str):
    """given an array of objects de-normalized into fields"""
    def _app(i, e=None):
        if i is not None:
            return ({k: v for k, v in iter_fields(i)}, None)
        return (i, e)
    def iter_fields(event_field: Union[dict, list]):
        if type(event_field) is dict:
            for key, val in event_field.items():
                yield (key, val)
        elif type(event_field) is list:
            for i, value in enumerate(event_field):
                for key, val in value.items():
                    if not i == 0:
                        yield ('{}_{}'.format(key, i), val)
                    else:
                        yield (key, val)
    return compose(_app, add_column_prefix(prefix))

def lazy_import(func):
    """Decorator for declaring a lazy import.

    This decorator turns a function into an object that will act as a lazy
    importer.  Whenever the object's attributes are accessed, the function
    is called and its return value used in place of the object.  So you
    can declare lazy imports like this:

        @lazy_import
        def socket():
            import socket
            return socket

    The name "socket" will then be bound to a transparent object proxy which
    will import the socket module upon first use.

    The syntax here is slightly more verbose than other lazy import recipes,
    but it's designed not to hide the actual "import" statements from tools
    like pyinstaller or grep."""
    try:
        f = sys._getframe(1)
    except Exception:
        namespace = None
    else:
        namespace = f.f_locals
    return _LazyImport(func.__name__, func, namespace)

def csv_to_map(fields, delimiter=','):
    """Convert csv to dict

    :param delimiter:
    :param fields:
    :return:"""
    def _csv_to_list(csv_input):
        """Util function to overcome the use of files by in-memory io buffer

        :param csv_input:
        :return:"""
        io_file = io.StringIO(csv_input)
        return next(csv.reader(io_file, delimiter=delimiter))
    def _app(current_tuple, e=None):
        if current_tuple is None or len(current_tuple) == 0:
            return (None, 'no input')
        csv_list = _csv_to_list(current_tuple)
        if len(csv_list) != len(fields):
            e = {'input': 'unexpected number of fields {} obtained {} expected'.format(len(csv_list), len(fields))}
            return (None, e)
        return ({k: v for k, v in zip(fields, csv_list)}, e)
    if fields is None or len(fields) == 0:
        return fixed_input(None, 'no fields provided, cannot proceed without order')
    return _app

def map_to_csv(fields, delimiter=','):
    """Convert dict to csv

    :param fields:
    :return:"""
    def _list_to_csv(l):
        """Util function to overcome the use of files by in-memory io buffer

        :param l:
        :return:"""
        io_file = io.StringIO()
        writer = csv.writer(io_file, quoting=csv.QUOTE_NONNUMERIC, lineterminator='', delimiter=delimiter)
        writer.writerow(l)
        return io_file.getvalue()
    def _app(current_tuple, e=None):
        if e is not None:
            return (None, e)
        csv_list = []
        for f in fields:
            if f in current_tuple:
                csv_list.append(current_tuple[f])
            else:
                e.update({'output': 'expected field {} not found'.format(f)})
                return (None, e)
        return (_list_to_csv(csv_list), e)
    if fields is None or len(fields) == 0:
        return fixed_input(None, 'no fields provided, cannot proceed without order')
    return _app

def xarrayfunc(func):
    """Make a function compatible with xarray.DataArray.

    This function is intended to be used as a decorator like::

        >>> @dc.xarrayfunc
        >>> def func(array):
        ...     # do something
        ...     return newarray
        >>>
        >>> result = func(array)

    Args:
        func (function): Function to be wrapped. The first argument
            of the function must be an array to be processed.

    Returns:
        wrapper (function): Wrapped function."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        if any((isinstance(arg, xr.DataArray) for arg in args)):
            newargs = []
            for arg in args:
                if isinstance(arg, xr.DataArray):
                    newargs.append(arg.values)
                else:
                    newargs.append(arg)
            return dc.full_like(args[0], func(*newargs, **kwargs))
        else:
            return func(*args, **kwargs)
    return wrapper

def makecontinuum(cube, **kwargs):
    """Make a continuum array.

    Args:
        cube (decode.cube): Decode cube which will be averaged over channels.
        kwargs (optional): Other arguments.
            inchs (list): Included channel kidids.
            exchs (list): Excluded channel kidids.

    Returns:
        decode cube (decode.cube): Decode cube (2d)."""
    inchs = kwargs.pop('inchs', None)
    exchs = kwargs.pop('exchs', None)
    if inchs is not None or exchs is not None:
        raise KeyError('Inchs and exchs are no longer supported. Use weight instead.')
    if weight is None:
        weight = 1.0
    cont = (cube * (1 / weight ** 2)).sum(dim='ch') / (1 / weight ** 2).sum(dim='ch')
    xcoords = {'x': cube.x.values}
    ycoords = {'y': cube.y.values}
    chcoords = {'masterid': np.array([0]), 'kidid': np.array([0]), 'kidfq': np.array([0]), 'kidtp': np.array([1])}
    scalarcoords = {'coordsys': cube.coordsys.values, 'datatype': cube.datatype.values, 'xref': cube.xref.values, 'yref': cube.yref.values}
    return dc.cube(cont.values, xcoords=xcoords, ycoords=ycoords, chcoords=chcoords, scalarcoords=scalarcoords)

def get_correct_answer(question, default=None, required=False, answer=None, is_answer_correct=None):
    u"""Ask user a question and confirm answer

    Args:

        question (str): Question to ask user

        default (str): Default answer if no input from user

        required (str): Require user to input answer

        answer (str): Used for testing

        is_answer_correct (str): Used for testing"""
    while 1:
        if default is None:
            msg = u' - No Default Available'
        else:
            msg = u'\n[DEFAULT] -> {}\nPress Enter To Use Default'.format(default)
        prompt = question + msg + u'\n--> '
        if answer is None:
            answer = six.moves.input(prompt)
        if answer == '' and required and (default is not None):
            print(u'You have to enter a value\n\n')
            six.moves.input(u'Press enter to continue')
            print(u'\n\n')
            answer = None
            continue
        if answer == u'' and default is not None:
            answer = default
        _ans = ask_yes_no(u'You entered {}, is this correct?'.format(answer), answer=is_answer_correct)
        if _ans:
            return answer
        else:
            answer = None

def deprecated(message):
    """Raise a `DeprecationWarning` when wrapped function/method is called.

    Borrowed from https://stackoverflow.com/a/48632082/866026"""
    def deprecated_decorator(func):
        """Deprecation decorator."""
        @wraps(func)
        def deprecated_func(*args, **kwargs):
            """Display deprecation warning."""
            warnings.warn("'{}' is deprecated. {}".format(func.__name__, message), category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return deprecated_func
    return deprecated_decorator

def get_process(cmd):
    """Get a command process."""
    if sys.platform.startswith('win'):
        startupinfo = subprocess.STARTUPINFO()
        startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
        process = subprocess.Popen(cmd, startupinfo=startupinfo, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, stdin=subprocess.PIPE, shell=False)
    else:
        process = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, stdin=subprocess.PIPE, shell=False)
    return process

def get_process_output(process, encoding=None):
    """Get the output from the process."""
    output = process.communicate()
    returncode = process.returncode
    if not encoding:
        try:
            encoding = sys.stdout.encoding
        except Exception:
            encoding = locale.getpreferredencoding()
    if returncode != 0:
        raise RuntimeError('Runtime Error: %s' % output[0].rstrip().decode(encoding, errors='replace'))
    return output[0].decode(encoding, errors='replace')

def call(cmd, input_file=None, input_text=None, encoding=None):
    """Call with arguments."""
    process = get_process(cmd)
    if input_file is not None:
        with open(input_file, 'rb') as f:
            process.stdin.write(f.read())
    if input_text is not None:
        process.stdin.write(input_text)
    return get_process_output(process, encoding)

def call_spellchecker(cmd, input_text=None, encoding=None):
    """Call spell checker with arguments."""
    process = get_process(cmd)
    if input_text is not None:
        for line in input_text.splitlines():
            offset = 0
            end = len(line)
            while True:
                chunk_end = offset + 8191
                m = None if chunk_end >= end else RE_LAST_SPACE_IN_CHUNK.search(line, offset, chunk_end)
                if m:
                    chunk_end = m.start(1)
                    chunk = line[offset:m.start(1)]
                    offset = m.end(1)
                else:
                    chunk = line[offset:chunk_end]
                    offset = chunk_end
                if chunk and (not chunk.isspace()):
                    process.stdin.write(chunk + b'\n')
                if offset >= end:
                    break
    return get_process_output(process, encoding)

def random_name_gen(size=6):
