def owner_required(Model=None):
    """Usage:

    @owner_required(Entry)
    def manage_entry(request, pk=None, object=None):

    @owner_required()
    def entry_delete(*args, **kwargs):
        kwargs["post_delete_redirect"] = reverse('manage_blogs')
        return delete_object(*args, **kwargs)"""
    def decorator(view_func):
        def _wrapped_view(request, *args, **kwargs):
            user = request.user
            grant = False
            model = Model
            mod_edit = False
            if 'pk' in kwargs:
                pk = int(kwargs['pk'])
                if model:
                    mod_edit = True
                elif 'model' in kwargs:
                    model = kwargs['model']
                object = get_object_or_404(model, pk=pk)
                if user.is_superuser:
                    grant = True
                elif user.__class__ == model:
                    grant = pk == user.id
                else:
                    names = [rel.get_accessor_name() for rel in user._meta.get_all_related_objects() if rel.model == model]
                    if names:
                        grant = pk in [o.id for o in getattr(user, names[0]).all()]
                if not grant:
                    return HttpResponseForbidden('Forbidden')
                if mod_edit:
                    kwargs['object'] = object
            return view_func(request, *args, **kwargs)
        return wraps(view_func)(_wrapped_view)
    return decorator

def convert_job(row: list) -> dict:
    """Convert sacct row to dict."""
    state = row[-2]
    start_time_raw = row[-4]
    end_time_raw = row[-3]
    if state not in ('PENDING', 'CANCELLED'):
        start_time = datetime.strptime(start_time_raw, '%Y-%m-%dT%H:%M:%S')
        if state != 'RUNNING':
            end_time = datetime.strptime(end_time_raw, '%Y-%m-%dT%H:%M:%S')
        else:
            end_time = None
    else:
        start_time = end_time = None
    job_name = row[1]
    step_name, step_context = job_name.rstrip('_BOTH').rstrip('_SV').rsplit('_', 1)
    return {'id': int(row[0]), 'name': job_name, 'step': step_name, 'context': step_context, 'state': state, 'start': start_time, 'end': end_time, 'elapsed': time_to_sec(row[-5]), 'cpu': time_to_sec(row[-6]), 'is_completed': state == 'COMPLETED'}

def with_fakes(method):
    """Decorator that calls :func:`fudge.clear_calls` before method() and :func:`fudge.verify` afterwards.
    """
    @wraps(method)
    def apply_clear_and_verify(*args, **kw):
        clear_calls()
        method(*args, **kw)
        verify()
    return apply_clear_and_verify

def secure_required(view_func):
    """Decorator to switch an url from http to https.

    If a view is accessed through http and this decorator is applied
    to that view, than it will return a permanent redirect to the
    secure (https) version of the same view.

    The decorator also must check that ``ACCOUNTS_USE_HTTPS`` is enabled.
    If disabled, it should not redirect to https because the project
    doesn't support it."""
    def _wrapped_view(request, *args, **kwargs):
        if not request.is_secure():
            if defaults.ACCOUNTS_USE_HTTPS:
                request_url = request.build_absolute_uri(request.get_full_path())
                secure_url = request_url.replace('http://', 'https://')
                return HttpResponsePermanentRedirect(secure_url)
        return view_func(request, *args, **kwargs)
    return wraps(view_func, assigned=available_attrs(view_func))(_wrapped_view)

def regexer_for_targets(targets):
    """Pairs up target files with their correct regex"""
    for target in targets:
        path, file_ext = os.path.splitext(target)
        regexer = config.regexers[file_ext]
        yield (target, regexer)

def extract_keypairs(lines, regexer):
    """Given some lines of text, extract key-value pairs from them"""
    updates = {}
    for line in lines:
        match = regexer.match(line.strip())
        if not match:
            continue
        k_v = match.groupdict()
        updates[k_v[Constants.KEY_GROUP]] = k_v[Constants.VALUE_GROUP]
    return updates

def read_targets(targets):
    """Reads generic key-value pairs from input files"""
    results = {}
    for target, regexer in regexer_for_targets(targets):
        with open(target) as fh:
            results.update(extract_keypairs(fh.readlines(), regexer))
    return results

def detect_file_triggers(trigger_patterns):
    """The existence of files matching configured globs will trigger a version bump"""
    triggers = set()
    for trigger, pattern in trigger_patterns.items():
        matches = glob.glob(pattern)
        if matches:
            _LOG.debug('trigger: %s bump from %r\n\t%s', trigger, pattern, matches)
            triggers.add(trigger)
        else:
            _LOG.debug('trigger: no match on %r', pattern)
    return triggers

def get_all_triggers(bump, file_triggers):
    """Aggregated set of significant figures to bump"""
    triggers = set()
    if file_triggers:
        triggers = triggers.union(detect_file_triggers(config.trigger_patterns))
    if bump:
        _LOG.debug('trigger: %s bump requested', bump)
        triggers.add(bump)
    return triggers

def get_lock_behaviour(triggers, all_data, lock):
    """Binary state lock protects from version increments if set"""
    updates = {}
    lock_key = config._forward_aliases.get(Constants.VERSION_LOCK_FIELD)
    if lock:
        updates[Constants.VERSION_LOCK_FIELD] = config.VERSION_LOCK_VALUE
    elif triggers and lock_key and (str(all_data.get(lock_key)) == str(config.VERSION_LOCK_VALUE)):
        triggers.clear()
        updates[Constants.VERSION_LOCK_FIELD] = config.VERSION_UNLOCK_VALUE
    return updates

def get_final_version_string(release_mode, semver, commit_count=0):
    """Generates update dictionary entries for the version string"""
    version_string = '.'.join(semver)
    maybe_dev_version_string = version_string
    updates = {}
    if release_mode:
        updates[Constants.RELEASE_FIELD] = config.RELEASED_VALUE
    else:
        maybe_dev_version_string = config.DEVMODE_TEMPLATE.format(version=version_string, count=commit_count)
    updates[Constants.VERSION_FIELD] = maybe_dev_version_string
    updates[Constants.VERSION_STRICT_FIELD] = version_string
    return updates

def log_cmd(context, sampleinfo, sacct, quiet, config):
    """Log an analysis.

    CONFIG: MIP config file for an analysis"""
    log_analysis = LogAnalysis(context.obj['store'])
    try:
        new_run = log_analysis(config, sampleinfo=sampleinfo, sacct=sacct)
    except MissingFileError as error:
        click.echo(click.style(f'Skipping, missing Sacct file: {error.message}', fg='yellow'))
        return
    except KeyError as error:
        print(click.style(f'unexpected output, missing key: {error.args[0]}', fg='yellow'))
        return
    if new_run is None:
        if not quiet:
            click.echo(click.style('Analysis already logged', fg='yellow'))
    else:
        message = f'New log added: {new_run.family} ({new_run.id}) - {new_run.status}'
        click.echo(click.style(message, fg='green'))

def start(context, mip_config, email, priority, dryrun, command, start_with, family):
    """Start a new analysis."""
    mip_cli = MipCli(context.obj['script'])
    mip_config = mip_config or context.obj['mip_config']
    email = email or environ_email()
    kwargs = dict(config=mip_config, family=family, priority=priority, email=email, dryrun=dryrun, start_with=start_with)
    if command:
        mip_command = mip_cli.build_command(**kwargs)
        click.echo(' '.join(mip_command))
    else:
        try:
            mip_cli(**kwargs)
            if not dryrun:
                context.obj['store'].add_pending(family, email=email)
        except MipStartError as error:
            click.echo(click.style(error.message, fg='red'))

def user(context, name, email):
    """Add a new or display information about an existing user."""
    existing_user = context.obj['store'].user(email)
    if existing_user:
        click.echo(existing_user.to_dict())
    elif name:
        new_user = context.obj['store'].add_user(name, email)
        click.echo(click.style(f'New user added: {email} ({new_user.id})', fg='green'))
    else:
        click.echo(click.style('User not found', fg='yellow'))

def takes_instance_or_queryset(func):
    """Decorator that makes standard Django admin actions compatible."""
    @wraps(func)
    def decorated_function(self, request, queryset):
        if not isinstance(queryset, QuerySet):
            try:
                queryset = self.get_queryset(request).filter(pk=queryset.pk)
            except AttributeError:
                try:
                    model = queryset._meta.model
                except AttributeError:
                    model = queryset._meta.concrete_model
                queryset = model.objects.filter(pk=queryset.pk)
        return func(self, request, queryset)
    return decorated_function

def build_html_element(tag, text=None, icon_class=None, cls=None, **kwargs):
    """Builds an html element.

    :param tag: the html tag to build ('a', 'div', 'img', etc)
    :param icon_class: the class to apply to an icon element.  This only
        applies to elements that allow a closing tag.
    :param cls: the css class to apply to the tag.  This can also be passed
        in as a kwarg as "class".

    >>> build_html_element(tag='a', href='someurl.com', text='hello')
    '<a href='someurl.com'>hello</a>'"""
    if cls is not None:
        kwargs['class'] = cls
    tag_attrs = ' '.join(['{0}="{1}"'.format(k, v) for k, v in kwargs.items()])
    tag_content = '{tag} {tag_attrs}'.format(tag=tag, tag_attrs=tag_attrs)
    if tag in ('img', 'input', 'hr', 'br'):
        return mark_safe('<{tag_content} />'.format(tag_content=tag_content))
    icon = '<i class="{0}"></i> '.format(icon_class) if icon_class else ''
    if not text:
        text = ''
    elif not isinstance(text, SafeText):
        text = escape(text)
    return mark_safe('<{tag_content}>{icon}{text}</{tag}>'.format(tag_content=tag_content, icon=icon, tag=tag, text=text))

def attr(obj, attr):
    """Does the same thing as getattr.

    getattr(obj, attr, '')"""
    if not obj or not hasattr(obj, attr):
        return ''
    return getattr(obj, attr, '')

def make_iterable(obj):
    """Make an object iterable.

    >>> make_iterable(obj='hello')
    ('hello',)
    >>> make_iterable(obj=None)
    ()"""
    if not obj:
        return tuple()
    if isinstance(obj, (list, tuple, set)):
        return obj
    return (obj,)

def is_valid_hex(value):
    """Boolean indicating of the value is a valid hex value."""
    if not value:
        return False
    regex = re.compile(HEX_COLOR_REGEX)
    return bool(regex.match(value))

def is_valid_rgb_color(value):
    """Checks whether the value is a valid rgb or rgba color string.

    Valid colors consist of:

    - rgb(255, 255, 255)
    - rgba(23, 34, 45, .5)"""
    if not value:
        return False
    regex = re.compile(RGB_COLOR_REGEX)
    return bool(regex.match(value))

def validate_password_strength(value):
    """Validates that a password is as least 7 characters long and has at least
    1 digit and 1 letter."""
    min_length = 7
    if len(value) < min_length:
        raise ValidationError(_('Password must be at least {0} characters long.').format(min_length))
    if not any((char.isdigit() for char in value)):
        raise ValidationError(_('Password must contain at least 1 digit.'))
    if not any((char.isalpha() for char in value)):
        raise ValidationError(_('Password must contain at least 1 letter.'))

def add_metaclass(metaclass):
    """Class decorator for creating a class with a metaclass."""
    def wrapper(cls):
        orig_vars = cls.__dict__.copy()
        orig_vars.pop('__dict__', None)
        orig_vars.pop('__weakref__', None)
        return metaclass(cls.__name__, cls.__bases__, orig_vars)
    return wrapper

