def run_code(node: Code, parent_node: Node=None, node_globals: InheritedDict=None, **args):
    """Executes node content as python module and adds its definitions to globals"""
    if not node.xml_node.text:
        return
    code = node.xml_node.text
    try:
        globs = node_globals.to_dictionary()
        exec(dedent(code), globs)
        definitions = [(key, value) for key, value in globs.items() if key != '__builtins__' and (not node_globals.has_key(key))]
        for key, value in definitions:
            parent_node.node_globals[key] = value
    except SyntaxError as err:
        error = _get_compilation_error(code, 'Invalid syntax', err, err.lineno)
        raise error from err
    except:
        info = exc_info()
        cause = info[1]
        line_number = extract_tb(info[2])[-1][1]
        error = _get_compilation_error(code, 'Code execution is failed', cause, line_number)
        raise error from cause

def format_date_argument(date_element):
    """Take a date as either a datetime.date/datetime or a string and return it as a iso8601 formatted value
    :param Union[datetime.date, datetime.datetime] date_element: passed argument
    :rtype str
    :return:"""
    if not isinstance(date_element, (datetime.datetime, datetime.date)):
        if 'T' in date_element:
            _date = datetime.datetime.strptime(date_element, '%Y-%m-%dT%H:%M:%S')
        else:
            _date = datetime.datetime.strptime(date_element, '%Y-%m-%d').date()
    else:
        _date = date_element
    return _date.isoformat()

def make_url(*args, **kwargs):
    """Makes a URL from component parts"""
    base = '/'.join(args)
    if kwargs:
        return '%s?%s' % (base, urlencode(kwargs))
    else:
        return base

