def parseXMLString(xml):
    """Parse XML string, return root
    :param str: Passed in XML"""
    unichr_captured = ''
    if not xml.strip():
        return u''
    while xml[0] != u'<':
        unichr_captured += xml[0]
        xml = xml[1:]
    parser = etree.XMLParser(ns_clean=True, collect_ids=False, huge_tree=True)
    try:
        return etree.fromstring(xml.encode('utf-8'), parser=parser)
    except etree.XMLSyntaxError:
        raise Exception(xml)

def typeof_rave_data(value):
    """Function to duck-type values, not relying on standard Python functions because, for example,
    a string of '1' should be typed as an integer and not as a string or float
    since we're trying to replace like with like when scrambling."""
    for format in ['%d %b %Y', '%b %Y', '%Y', '%d %m %Y', '%m %Y', '%d/%b/%Y', '%b/%Y', '%d/%m/%Y', '%m/%Y']:
        try:
            datetime.datetime.strptime(value, format)
            if len(value) == 4 and (int(value) < 1900 or int(value) > 2030):
                break
            return ('date', format)
        except ValueError:
            pass
        except TypeError:
            pass
    for format in ['%H:%M:%S', '%H:%M', '%I:%M:%S', '%I:%M', '%I:%M:%S %p', '%I:%M %p']:
        try:
            datetime.datetime.strptime(value, format)
            return ('time', format)
        except ValueError:
            pass
        except TypeError:
            pass
    try:
        if isinstance(value, str) and isinstance(int(value), int) or isinstance(value, int):
            return ('int', None)
    except ValueError:
        pass
    except TypeError:
        pass
    try:
        float(value)
        return ('float', None)
    except ValueError:
        pass
    except TypeError:
        pass
    return ('string', None)

def make_int(value, missing=-1):
    """Convert string value to long, '' to missing"""
    if isinstance(value, six.string_types):
        if not value.strip():
            return missing
    elif value is None:
        return missing
    return int(value)

def parse(data, eventer):
    """Parse the XML data, firing events from the eventer"""
