def validate_not_empty():
    """Validate that a field is not empty (blank string).

    :raises: ``ValidationError('empty')``"""
    def empty_validator(field, data):
        if isinstance(field.value, str) and (not field.value.strip()):
            raise ValidationError('empty')
    return empty_validator

def validate_one_of(values):
    """Validate that a field is in one of the given values.

    :param values: Iterable of valid values.
    :raises: ``ValidationError('one_of')``"""
    def one_of_validator(field, data):
        if field.value is None:
            return
        options = values
        if callable(options):
            options = options()
        if field.value not in options:
            raise ValidationError('one_of', choices=', '.join(map(str, options)))
    return one_of_validator

def validate_none_of(values):
    """Validate that a field is not in one of the given values.

    :param values: Iterable of invalid values.
    :raises: ``ValidationError('none_of')``"""
    def none_of_validator(field, data):
        options = values
        if callable(options):
            options = options()
        if field.value in options:
            raise ValidationError('none_of', choices=str.join(', ', options))
    return none_of_validator

def validate_equal(value):
    """Validate the field value is equal to the given value.
    Should work with anything that supports '==' operator.

    :param value: Value to compare.
    :raises: ``ValidationError('equal')``"""
    def equal_validator(field, data):
        if field.value is None:
            return
        if not field.value == value:
            raise ValidationError('equal', other=value)
    return equal_validator

def validate_matches(other):
    """Validate the field value is equal to another field in the data.
    Should work with anything that supports '==' operator.

    :param value: Field key to compare.
    :raises: ``ValidationError('matches')``"""
    def matches_validator(field, data):
        if field.value is None:
            return
        if not field.value == data.get(other):
            raise ValidationError('matches', other=other)
    return matches_validator

def validate_regexp(pattern, flags=0):
    """Validate the field matches the given regular expression.
    Should work with anything that supports '==' operator.

    :param pattern: Regular expresion to match. String or regular expression instance.
    :param pattern: Flags for the regular expression.
    :raises: ``ValidationError('equal')``"""
    regex = re.compile(pattern, flags) if isinstance(pattern, str) else pattern
    def regexp_validator(field, data):
        if field.value is None:
            return
        if regex.match(str(field.value)) is None:
            raise ValidationError('regexp', pattern=pattern)
    return regexp_validator

def validate_function(method, **kwargs):
    """Validate the field matches the result of calling the given method. Example::

        def myfunc(value, name):
            return value == name

        validator = validate_function(myfunc, name='tim')

    Essentially creates a validator that only accepts the name 'tim'.

    :param method: Method to call.
    :param kwargs: Additional keyword arguments passed to the method.
    :raises: ``ValidationError('function')``"""
    def function_validator(field, data):
        if field.value is None:
            return
        if not method(field.value, **kwargs):
            raise ValidationError('function', function=method.__name__)
    return function_validator

def validate_email():
    """Validate the field is a valid email address.

    :raises: ``ValidationError('email')``"""
    user_regex = re.compile('(^[-!#$%&\'*+/=?^`{}|~\\w]+(\\.[-!#$%&\'*+/=?^`{}|~\\w]+)*$|^"([\\001-\\010\\013\\014\\016-\\037!#-\\[\\]-\\177]|\\\\[\\001-\\011\\013\\014\\016-\\177])*"$)', re.IGNORECASE | re.UNICODE)
    domain_regex = re.compile('(?:[A-Z0-9](?:[A-Z0-9-]{0,61}[A-Z0-9])?\\.)+(?:[A-Z]{2,6}|[A-Z0-9-]{2,})$|^\\[(25[0-5]|2[0-4]\\d|[0-1]?\\d?\\d)(\\.(25[0-5]|2[0-4]\\d|[0-1]?\\d?\\d)){3}\\]$', re.IGNORECASE | re.UNICODE)
    domain_whitelist = ('localhost',)
    def email_validator(field, data):
        if field.value is None:
            return
        value = str(field.value)
        if '@' not in value:
            raise ValidationError('email')
        user_part, domain_part = value.rsplit('@', 1)
        if not user_regex.match(user_part):
            raise ValidationError('email')
        if domain_part in domain_whitelist:
            return
        if not domain_regex.match(domain_part):
            raise ValidationError('email')
    return email_validator

def coerce_single_instance(lookup_field, value):
    """Convert from whatever value is given to a scalar value for lookup_field.
    If value is a dict, then lookup_field.name is used to get the value from the dict. Example:
        lookup_field.name = 'id'
        value = {'id': 123, 'name': 'tim'}
        returns = 123
    If value is a model, then lookup_field.name is extracted from the model. Example:
        lookup_field.name = 'id'
        value = <User id=123 name='tim'>
        returns = 123
    Otherwise the value is returned as-is.

    :param lookup_field: Peewee model field used for getting name from value.
    :param value: Some kind of value (usually a dict, Model instance, or scalar)."""
    if isinstance(value, dict):
        return value.get(lookup_field.name)
    if isinstance(value, peewee.Model):
        return getattr(value, lookup_field.name)
    return value

def isiterable_notstring(value):
    """Returns True if the value is iterable but not a string. Otherwise returns False.

    :param value: Value to check."""
    if isinstance(value, str):
        return False
    return isinstance(value, Iterable) or isgeneratorfunction(value) or isgenerator(value)

def _make_digest(k, **kwargs):
    """Creates a digest suitable for use within an :class:`phyles.FSCache`
    object from the key object `k`.

    >>> adict = {'a' : {'b':1}, 'f': []}
    >>> make_digest(adict)
    'a2VKynHgDrUIm17r6BQ5QcA5XVmqpNBmiKbZ9kTu0A'"""
    result = list()
    result_dict = _make_digest_dict(k, **kwargs)
    if result_dict is None:
        return 'default'
    else:
        for key, h in sorted(result_dict.items()):
            result.append('{}_{}'.format(key, h))
        return '.'.join(result)

def cached_model_file(model_name='anon_model', file=None, model_code=None, cache_dir=None, fit_cachefile=None, include_prefix=False):
    """Given model name & stan model code/file, compute path to cached stan fit

    if include_prefix, returns (model_prefix, model_cachefile)"""
    cache_dir = _get_cache_dir(cache_dir)
    model_name = _sanitize_model_name(model_name)
    if file:
        model_code = _read_file(file)
    if model_code:
        model_prefix = '.'.join([model_name, _make_digest(dict(model_code=model_code, pystan=pystan.__version__, cython=Cython.__version__))])
    elif file is not None:
        logger.info('Note - no model code detected from given file: {}'.format(file))
    else:
        logger.info('Note - no model code detected (neither file nor model_code given)')
    if fit_cachefile:
        if fit_cachefile != os.path.basename(fit_cachefile):
            cache_dir, fit_cachefile = os.path.split(os.path.abspath(fit_cachefile))
        fit_model_prefix = re.sub(string=os.path.basename(fit_cachefile), pattern='(.*).stanfit.*', repl='\\1')
        if model_code:
            if fit_model_prefix != model_prefix:
                logger.warning('Computed model prefix does not match that used to estimate model. Using prefix matching fit_cachefile')
        model_prefix = fit_model_prefix
    model_cachefile = '.'.join([model_prefix, 'stanmodel', 'pkl'])
    if include_prefix:
        return (model_prefix, model_cachefile)
    return model_cachefile

def cached_stan_file(model_name='anon_model', file=None, model_code=None, cache_dir=None, fit_cachefile=None, cache_only=None, force=False, include_modelfile=False, prefix_only=False, **kwargs):
    """Given inputs to cached_stan_fit, compute pickle file containing cached fit
    """
    model_prefix, model_cachefile = cached_model_file(model_name=model_name, file=file, model_code=model_code, cache_dir=cache_dir, fit_cachefile=fit_cachefile, include_prefix=True)
    if not fit_cachefile:
        fit_cachefile = '.'.join([model_prefix, 'stanfit', _make_digest(dict(**kwargs)), 'pkl'])
    if include_modelfile:
        return (model_cachefile, fit_cachefile)
    if prefix_only:
        fit_cachefile = re.sub(string=fit_cachefile, pattern='.pkl$', repl='')
    return fit_cachefile

def wrap_cell(entity, json_obj, mapping, table_view=False):
    """Cell wrappers
    for customizing the GUI data table

    TODO : must coincide with hierarchy!
    TODO : simplify this!"""
    html_class = ''
    out = ''
    if entity['multiple']:
        out = ', '.join(map(lambda x: num2name(x, entity, mapping), json_obj.get(entity['source'], [])))
    elif entity['is_chem_formula']:
        out = html_formula(json_obj[entity['source']]) if entity['source'] in json_obj else '&mdash;'
    elif entity['source'] == 'bandgap':
        html_class = ' class=_g'
        out = json_obj.get('bandgap')
        if out is None:
            out = '&mdash;'
    elif entity['source'] == 'energy':
        html_class = ' class=_e'
        out = '%6.5f' % json_obj['energy'] if json_obj['energy'] else '&mdash;'
    elif entity['source'] == 'dims':
        out = '%4.2f' % json_obj['dims'] if json_obj['periodicity'] in [2, 3] else '&mdash;'
    else:
        out = num2name(json_obj.get(entity['source']), entity, mapping) or '&mdash;'
