def is_field_unique_by_group(df, field_col, group_col):
    """Determine if field is constant by group in df
    """
    def num_unique(x):
        return len(pd.unique(x))
    num_distinct = df.groupby(group_col)[field_col].agg(num_unique)
    return all(num_distinct == 1)

def _list_files_in_path(path, pattern='*.stan'):
    """indexes a directory of stan files
    returns as dictionary containing contents of files"""
    results = []
    for dirname, subdirs, files in os.walk(path):
        for name in files:
            if fnmatch(name, pattern):
                results.append(os.path.join(dirname, name))
    return results

def check_positive_integer(name, value):
    """Check a value is a positive integer.

    Returns the value if so, raises ValueError otherwise."""
    try:
        value = int(value)
        is_positive = value > 0
    except ValueError:
        raise ValueError('%s should be an integer; got %r' % (name, value))
    if is_positive:
        return value
    else:
        raise ValueError('%s should be positive; got %r' % (name, value))

def check_color_input(value):
    """Check a value is a valid colour input.

    Returns a parsed `RGBColor` instance if so, raises ValueError
    otherwise."""
    value = value.lower()
    if value.startswith('#'):
        value = value[1:]
    if len(value) != 6:
        raise ValueError('Color should be six hexadecimal digits, got %r (%s)' % (value, len(value)))
    if re.sub('[a-f0-9]', '', value):
        raise ValueError('Color should only contain hex characters, got %r' % value)
    red = int(value[0:2], base=16)
    green = int(value[2:4], base=16)
    blue = int(value[4:6], base=16)
    return RGBColor(red, green, blue)

def eplotter(task, data):
    """eplotter is like bdplotter but less complicated"""
    results, color, fdata = ([], None, [])
    if task == 'optstory':
        color = '#CC0000'
        clickable = True
        for n, i in enumerate(data):
            fdata.append([n, i[4]])
        fdata = array(fdata)
        fdata[:, 1] -= min(fdata[:, 1])
        fdata = fdata.tolist()
    elif task == 'convergence':
        color = '#0066CC'
        clickable = False
        for n, i in enumerate(data):
            fdata.append([n, i])
    for n in range(len(fdata)):
        fdata[n][1] = round(fdata[n][1], 5)
    results.append({'color': color, 'clickable:': clickable, 'data': fdata})
    return results

def isCLIExecutable(filePath):
    """Test whether given `filePath` is an executable.  Does not really
    check whether the executable is a CLI (e.g. whether it supports
    --xml), but can be used to filter out non-executables within a
    directory with CLI modules."""
    if not os.path.isfile(filePath):
        return False
    if sys.platform.startswith('win'):
        filePath = filePath.lower()
        return filePath.endswith('.exe') or filePath.endswith('.bat')
    else:
        if not os.access(filePath, os.X_OK):
            return False
        return not '.' in os.path.basename(filePath)

def listify(arg):
    """Simple utility method to ensure an argument provided is a list. If the
    provider argument is not an instance of `list`, then we return [arg], else
    arg is returned.

    :type arg: list
    :rtype: list"""
    if isinstance(arg, (set, tuple)):
        return list(arg)
    if not isinstance(arg, list):
        return [arg]
    return arg

def mass_mailing_recipients():
    """Returns iterable of all mass email recipients.
    Default behavior will be to return list of all active users' emails.
    This can be changed by providing callback in settings return some other list of users,
    when user emails are stored in many, non default models.
    To accomplish that add constant MASS_EMAIL_RECIPIENTS to settings. It should contain path to function, e.g.
    >>> MASS_EMAIL_RECIPIENTS = 'emailtemplates.helpers.mass_mailing_recipients'

    :rtype iterable"""
    if hasattr(settings, 'MASS_EMAIL_RECIPIENTS'):
        callback_name = settings.MASS_EMAIL_RECIPIENTS.split('.')
        module_name = '.'.join(callback_name[:-1])
        func_name = callback_name[-1]
        module = import_module(module_name)
        func = getattr(module, func_name, lambda: [])
        return func()
    User = get_user_model()
    if hasattr(User, 'is_active') and hasattr(User, 'email'):
        filtered_users = User.objects.filter(is_active=True).exclude(email__isnull=True).exclude(email__exact='')
        return filtered_users.values_list('email', flat=True).distinct()
    return []

def dup2(a, b, timeout=3):
    """Like os.dup2, but retry on EBUSY"""
    dup_err = None
    for i in range(int(10 * timeout)):
        try:
            return os.dup2(a, b)
        except OSError as e:
            dup_err = e
            if e.errno == errno.EBUSY:
                time.sleep(0.1)
            else:
                raise
    if dup_err:
        raise dup_err

def sys_pipes(encoding=_default_encoding):
    """Redirect C-level stdout/stderr to sys.stdout/stderr

    This is useful of sys.sdout/stderr are already being forwarded somewhere.

    DO NOT USE THIS if sys.stdout and sys.stderr are not already being forwarded."""
    return pipes(sys.stdout, sys.stderr, encoding=encoding)

def get_service_from_port(port, all_services=None):
    """Gets the name of the service from the port
    all_services allows you to feed in the services to look through, pass
    in a dict of service names to service information eg.
    {
        'service_name': {
            'port': port_number
        }
    }

    Returns the name of the service"""
    if port is None or not isinstance(port, int):
        return None
    if all_services is None:
        all_services = read_services_configuration()
    for name, info in all_services.items():
        srv_port = info.get('port')
        if srv_port is not None and port == int(srv_port):
            return name
        for elem in info.get('smartstack', {}).values():
            elem_port = elem.get('proxy_port')
            if elem_port is not None and port == int(elem_port):
                return name

def all_nodes_that_receive(service, service_configuration=None, run_only=False, deploy_to_only=False):
    """If run_only, returns only the services that are in the runs_on list.
    If deploy_to_only, returns only the services in the deployed_to list.
    If neither, both are returned, duplicates stripped.
    Results are always sorted."""
    assert not (run_only and deploy_to_only)
    if service_configuration is None:
        service_configuration = read_services_configuration()
    runs_on = service_configuration[service]['runs_on']
    deployed_to = service_configuration[service].get('deployed_to')
    if deployed_to is None:
        deployed_to = []
    if run_only:
        result = runs_on
    elif deploy_to_only:
        result = deployed_to
    else:
        result = set(runs_on) | set(deployed_to)
    return list(sorted(result))

def _places_b4_and_after_decimal(d):
    """>>> _places_b4_and_after_decimal(Decimal('54.212'))
    (2, 3)"""
    tup = d.as_tuple()
    return (len(tup.digits) + tup.exponent, max(-1 * tup.exponent, 0))

def set_worst(old_worst, new_worst):
    """Pad new_worst with zeroes to prevent it being shorter than old_worst.

    >>> set_worst(311920, '48-49')
    '48-490'
    >>> set_worst(98, -2)
    -20"""
    if isinstance(new_worst, bool):
        return new_worst
    negative = hasattr(old_worst, '__neg__') and old_worst < 0 or (hasattr(new_worst, '__neg__') and new_worst < 0)
    try:
        old_worst = abs(old_worst)
        new_worst = abs(new_worst)
    except TypeError:
        pass
    new_len = len(str(new_worst))
    old_len = len(str(old_worst))
    if new_len < old_len:
        new_type = type(new_worst)
        new_worst = str(new_worst).ljust(old_len, '0')
        new_worst = new_type(new_worst)
    if negative:
        try:
            new_worst = -1 * abs(new_worst)
        except:
            pass
    return new_worst

def sqla_datatype_for(datum):
    """Given a scalar Python value, picks an appropriate SQLAlchemy data type.

    >>> sqla_datatype_for(7.2)
    DECIMAL(precision=2, scale=1)
    >>> sqla_datatype_for("Jan 17 2012")
    <class 'sqlalchemy.sql.sqltypes.DATETIME'>
    >>> sqla_datatype_for("something else")
    Unicode(length=14)"""
    try:
        if len(_complex_enough_to_be_date.findall(datum)) > 1:
            dateutil.parser.parse(datum)
            return sa.DATETIME
    except (TypeError, ValueError):
        pass
    try:
        prec, scale = precision_and_scale(datum)
        return sa.DECIMAL(prec, scale)
    except TypeError:
        return sa.Unicode(len(datum))

