def fallback(func):
    """Decorator function for functions that handle spark context.
    If a function changes sc we might lose it if an error occurs in the function.
    In the event of an error this decorator will log the error but return sc.

    :param func: function to decorate
    :return: decorated function"""
    @wraps(func)
    def dec(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception as e:
            logging.getLogger('pySparkUtils').error('Decorator handled exception %s' % e, exc_info=True)
            _, _, tb = sys.exc_info()
            while tb.tb_next:
                tb = tb.tb_next
                frame = tb.tb_frame
                for key, value in iteritems(frame.f_locals):
                    if isinstance(value, SparkContext) and value._jsc is not None:
                        return frame.f_locals[key]
            logging.getLogger('pySparkUtils').error('Could not find SparkContext', exc_info=True)
            return None
    return dec

def balanced_repartition(data, partitions):
    """balanced_repartition(data, partitions)
    Reparations an RDD making sure data is evenly distributed across partitions
    for Spark version < 2.1 (see: https://issues.apache.org/jira/browse/SPARK-17817)
    or < 2.3 when #partitions is power of 2 (see: https://issues.apache.org/jira/browse/SPARK-21782)

    :param data: RDD
    :param partitions: number of partition to use
    :return: repartitioned data"""
    def repartition(data_inner, partitions_inner):
        data_inner = data_inner.zipWithIndex().map(lambda x: (x[1], x[0]))
        data_inner = data_inner.partitionBy(partitions_inner, lambda x: x % partitions_inner)
        return data_inner.map(lambda x: x[1])
    if isinstance(data, RDD):
        return repartition(data, partitions)
    else:
        raise ValueError('Wrong data type, expected [RDD, Images, Series] got: %s' % type(data))

def clip_geometry_to_srs_bounds(geometry, pyramid, multipart=False):
    """Clip input geometry to SRS bounds of given TilePyramid.

    If geometry passes the antimeridian, it will be split up in a multipart
    geometry and shifted to within the SRS boundaries.
    Note: geometry SRS must be the TilePyramid SRS!

    - geometry: any shapely geometry
    - pyramid: a TilePyramid object
    - multipart: return list of geometries instead of a GeometryCollection"""
    if not geometry.is_valid:
        raise ValueError('invalid geometry given')
    pyramid_bbox = box(*pyramid.bounds)
    if pyramid.is_global and (not geometry.within(pyramid_bbox)):
        inside_geom = geometry.intersection(pyramid_bbox)
        outside_geom = geometry.difference(pyramid_bbox)
        if isinstance(outside_geom, Polygon):
            outside_geom = [outside_geom]
        all_geoms = [inside_geom]
        for geom in outside_geom:
            geom_bounds = Bounds(*geom.bounds)
            if geom_bounds.left < pyramid.left:
                geom = translate(geom, xoff=2 * pyramid.right)
            elif geom_bounds.right > pyramid.right:
                geom = translate(geom, xoff=-2 * pyramid.right)
            all_geoms.append(geom)
        if multipart:
            return all_geoms
        else:
            return GeometryCollection(all_geoms)
    elif multipart:
        return [geometry]
    else:
        return geometry

def _tile_intersecting_tilepyramid(tile, tp):
    """Return all tiles from tilepyramid intersecting with tile."""
    if tile.tp.grid != tp.grid:
        raise ValueError('Tile and TilePyramid source grids must be the same.')
    tile_metatiling = tile.tile_pyramid.metatiling
    pyramid_metatiling = tp.metatiling
    multiplier = tile_metatiling / pyramid_metatiling
    if tile_metatiling > pyramid_metatiling:
        return [tp.tile(tile.zoom, int(multiplier) * tile.row + row_offset, int(multiplier) * tile.col + col_offset) for row_offset, col_offset in product(range(int(multiplier)), range(int(multiplier)))]
    elif tile_metatiling < pyramid_metatiling:
        return [tp.tile(tile.zoom, int(multiplier * tile.row), int(multiplier * tile.col))]
    else:
        return [tp.tile(*tile.id)]

def _global_tiles_from_bounds(tp, bounds, zoom):
    """Return also Tiles if bounds cross the antimeridian."""
    seen = set()
    left, right = (bounds.left, bounds.right)
    top = tp.top if bounds.top > tp.top else bounds.top
    bottom = tp.bottom if bounds.bottom < tp.bottom else bounds.bottom
    if left >= tp.left and right <= tp.right:
        for tile in _tiles_from_cleaned_bounds(tp, bounds, zoom):
            yield tile
    if left < tp.left:
        for tile in chain(_tiles_from_cleaned_bounds(tp, Bounds(left + (tp.right - tp.left), bottom, tp.right, top), zoom), _tiles_from_cleaned_bounds(tp, Bounds(tp.left, bottom, right, top), zoom)):
            if tile.id not in seen:
                seen.add(tile.id)
                yield tile
    if right > tp.right:
        for tile in chain(_tiles_from_cleaned_bounds(tp, Bounds(left, bottom, tp.right, top), zoom), _tiles_from_cleaned_bounds(tp, Bounds(tp.left, bottom, right - (tp.right - tp.left), top), zoom)):
            if tile.id not in seen:
                seen.add(tile.id)
                yield tile

def _tiles_from_cleaned_bounds(tp, bounds, zoom):
    """Return all tiles intersecting with bounds."""
    lb = _tile_from_xy(tp, bounds.left, bounds.bottom, zoom, on_edge_use='rt')
    rt = _tile_from_xy(tp, bounds.right, bounds.top, zoom, on_edge_use='lb')
    for tile_id in product([zoom], range(rt.row, lb.row + 1), range(lb.col, rt.col + 1)):
        yield tp.tile(*tile_id)

def human_duration(duration_seconds: float) -> str:
    """Convert a duration in seconds into a human friendly string."""
    if duration_seconds < 0.001:
        return '0 ms'
    if duration_seconds < 1:
        return '{} ms'.format(int(duration_seconds * 1000))
    return '{} s'.format(int(duration_seconds))

def call_with_retry(func: Callable, exceptions, max_retries: int, logger: Logger, *args, **kwargs):
    """Call a function and retry it on failure."""
    attempt = 0
    while True:
        try:
            return func(*args, **kwargs)
        except exceptions as e:
            attempt += 1
            if attempt >= max_retries:
                raise
            delay = exponential_backoff(attempt, cap=60)
            logger.warning('%s: retrying in %s', e, delay)
            time.sleep(delay.total_seconds())

def get_metadata_path(name):
    """Get reference metadata file path."""
    return pkg_resources.resource_filename('voobly', os.path.join(METADATA_PATH, '{}.json'.format(name)))

def _make_request(session, url, argument=None, params=None, raw=False):
    """Make a request to API endpoint."""
    if not params:
        params = {}
    params['key'] = session.auth.key
    try:
        if argument:
            request_url = '{}{}{}{}'.format(session.auth.base_url, VOOBLY_API_URL, url, argument)
        else:
            request_url = '{}{}'.format(VOOBLY_API_URL, url)
        resp = session.get(request_url, params=params)
    except RequestException:
        raise VooblyError('failed to connect')
    if resp.text == 'bad-key':
        raise VooblyError('bad api key')
    elif resp.text == 'too-busy':
        raise VooblyError('service too busy')
    elif not resp.text:
        raise VooblyError('no data returned')
    if raw:
        return resp.text
    try:
        return tablib.Dataset().load(resp.text).dict
    except UnsupportedFormat:
        raise VooblyError('unexpected error {}'.format(resp.text))

def get_ladder(session, ladder_id, user_id=None, user_ids=None, start=0, limit=LADDER_RESULT_LIMIT):
    """Get ladder."""
    params = {'start': start, 'limit': limit}
    if isinstance(ladder_id, str):
        ladder_id = lookup_ladder_id(ladder_id)
    if limit > LADDER_RESULT_LIMIT:
        raise VooblyError('limited to 40 rows')
    if user_ids:
        params['uidlist'] = ','.join([str(uid) for uid in user_ids])
    elif user_id:
        params['uid'] = user_id
    resp = _make_request(session, LADDER_URL, ladder_id, params)
    if user_id:
        if not resp:
            raise VooblyError('user not ranked')
        return resp[0]
    return resp

def get_lobbies(session, game_id):
    """Get lobbies for a game."""
    if isinstance(game_id, str):
        game_id = lookup_game_id(game_id)
    lobbies = _make_request(session, LOBBY_URL, game_id)
    for lobby in lobbies:
        if len(lobby['ladders']) > 0:
            lobby['ladders'] = lobby['ladders'][:-1].split('|')
    return lobbies

def get_user(session, user_id):
    """Get user."""
    try:
        user_id = int(user_id)
    except ValueError:
        user_id = find_user(session, user_id)
    resp = _make_request(session, USER_URL, user_id)
    if not resp:
        raise VooblyError('user id not found')
    return resp[0]

def find_user(session, username):
    """Find user by name - returns user ID."""
    resp = _make_request(session, FIND_USER_URL, username)
    if not resp:
        raise VooblyError('user not found')
    try:
        return int(resp[0]['uid'])
    except ValueError:
        raise VooblyError('user not found')

def find_users(session, *usernames):
    """Find multiple users by name."""
    user_string = ','.join(usernames)
    return _make_request(session, FIND_USERS_URL, user_string)

def user(session, uid, ladder_ids=None):
    """Get all possible user info by name."""
    data = get_user(session, uid)
    resp = dict(data)
    if not ladder_ids:
        return resp
    resp['ladders'] = {}
    for ladder_id in ladder_ids:
        if isinstance(ladder_id, str):
            ladder_id = lookup_ladder_id(ladder_id)
        try:
            ladder_data = dict(get_ladder(session, ladder_id, user_id=uid))
            resp['ladders'][ladder_id] = ladder_data
        except VooblyError:
            pass
    return resp

def ladders(session, game_id):
    """Get a list of ladder IDs."""
    if isinstance(game_id, str):
        game_id = lookup_game_id(game_id)
    lobbies = get_lobbies(session, game_id)
    ladder_ids = set()
    for lobby in lobbies:
        ladder_ids |= set(lobby['ladders'])
    return list(ladder_ids)

def authenticated(function):
    """Re-authenticate if session expired."""
    def wrapped(session, *args, **kwargs):
        """Wrap function."""
        try:
            return function(session, *args, **kwargs)
        except VooblyError:
            with session.cache_disabled():
                _LOGGER.info('attempted to access page before login')
                login(session)
                return function(session, *args, **kwargs)
    return wrapped

def get_clan_matches(session, subdomain, clan_id, from_timestamp=None, limit=None):
    """Get recent matches by clan."""
    return get_recent_matches(session, 'https://{}.voobly.com/{}/{}/0'.format(subdomain, TEAM_MATCHES_URL, clan_id), from_timestamp, limit)

def get_user_matches(session, user_id, from_timestamp=None, limit=None):
    """Get recent matches by user."""
    return get_recent_matches(session, '{}{}/{}/Matches/games/matches/user/{}/0'.format(session.auth.base_url, PROFILE_URL, user_id, user_id), from_timestamp, limit)

def download_rec(session, rec_url, target_path):
    """Download and extract a recorded game."""
    try:
        resp = session.get(session.auth.base_url + rec_url)
    except RequestException:
        raise VooblyError('failed to connect for download')
    try:
        downloaded = zipfile.ZipFile(io.BytesIO(resp.content))
        downloaded.extractall(target_path)
    except zipfile.BadZipFile:
        raise VooblyError('invalid zip file')
    return downloaded.namelist()[0]

def login(session):
    """Login to Voobly."""
    if not session.auth.username or not session.auth.password:
        raise VooblyError('must supply username and password')
    _LOGGER.info('logging in (no valid cookie found)')
    session.cookies.clear()
    try:
        session.get(session.auth.base_url + LOGIN_PAGE)
        resp = session.post(session.auth.base_url + LOGIN_URL, data={'username': session.auth.username, 'password': session.auth.password})
    except RequestException:
        raise VooblyError('failed to connect for login')
    if resp.status_code != 200:
        raise VooblyError('failed to login')
    _save_cookies(session.cookies, session.auth.cookie_path)

def register_datadog(tracer=None, namespace: Optional[str]=None, service: str='spinach'):
    """Register the Datadog integration.

    Exceptions making jobs fail are sent to Sentry.

    :param tracer: optionally use a custom ddtrace Tracer instead of the global
           one.
    :param namespace: optionally only register the Datadog integration for a
           particular Spinach :class:`Engine`
    :param service: Datadog service associated with the trace, defaults to
           `spinach`"""
    if tracer is None:
        from ddtrace import tracer
    @signals.job_started.connect_via(namespace)
    def job_started(namespace, job, **kwargs):
        tracer.trace('spinach.task', service=service, span_type='worker', resource=job.task_name)
    @signals.job_finished.connect_via(namespace)
    def job_finished(namespace, job, **kwargs):
        root_span = tracer.current_root_span()
        for attr in job.__slots__:
            root_span.set_tag(attr, getattr(job, attr))
        root_span.finish()
    @signals.job_failed.connect_via(namespace)
    def job_failed(namespace, job, **kwargs):
        root_span = tracer.current_root_span()
        root_span.set_traceback()
    @signals.job_schedule_retry.connect_via(namespace)
    def job_schedule_retry(namespace, job, **kwargs):
        root_span = tracer.current_root_span()
        root_span.set_traceback()

def serialize(obj):
    """JSON serializer for objects not serializable by default json code"""
    if isinstance(obj, datetime.datetime):
        serial = obj.isoformat(sep='T')
        return serial
    if isinstance(obj, uuid.UUID):
        serial = str(obj)
        return serial
    try:
        return obj.__dict__
    except AttributeError:
        return str(obj)
    except Exception as e:
        strval = 'unknown obj'
        exceptval = 'unknown err'
        try:
            strval = str(obj)
            exceptval = repr(e)
        except Exception:
            pass
        return 'json fail {} {}'.format(exceptval, strval)

def add_namespaces(spec_dict):
    """Add namespace convenience keys, list, list_{short|long}, to_{short|long}"""
    for ns in spec_dict['namespaces']:
        spec_dict['namespaces'][ns]['list'] = []
        spec_dict['namespaces'][ns]['list_long'] = []
        spec_dict['namespaces'][ns]['list_short'] = []
        spec_dict['namespaces'][ns]['to_short'] = {}
        spec_dict['namespaces'][ns]['to_long'] = {}
        for obj in spec_dict['namespaces'][ns]['info']:
            spec_dict['namespaces'][ns]['list'].extend([obj['name'], obj['abbreviation']])
            spec_dict['namespaces'][ns]['list_short'].append(obj['abbreviation'])
            spec_dict['namespaces'][ns]['list_long'].append(obj['name'])
            spec_dict['namespaces'][ns]['to_short'][obj['abbreviation']] = obj['abbreviation']
            spec_dict['namespaces'][ns]['to_short'][obj['name']] = obj['abbreviation']
            spec_dict['namespaces'][ns]['to_long'][obj['abbreviation']] = obj['name']
            spec_dict['namespaces'][ns]['to_long'][obj['name']] = obj['name']
            if 'abbrev1' in obj:
                spec_dict['namespaces'][ns]['to_short'][obj['abbrev1']] = obj['abbreviation']
                spec_dict['namespaces'][ns]['to_long'][obj['abbrev1']] = obj['name']

def get_ebnf_template():
    """Get EBNF template from Github belbio/bel_specifications repo"""
    spec_dir = config['bel']['lang']['specifications']
    local_fp = f'{spec_dir}/bel.ebnf.j2'
    repo_url = 'https://api.github.com/repos/belbio/bel_specifications/contents/resources/bel.ebnf.j2'
    params = {}
    github_access_token = os.getenv('GITHUB_ACCESS_TOKEN', '')
    if github_access_token:
        params = {'access_token': github_access_token}
    try:
        r = requests.get(repo_url, params=params)
        if r.status_code == 200:
            template_url = r.json()['download_url']
        else:
            log.warning('Could not get EBNF file download url from Github')
        try:
            r = requests.get(template_url, params=params, allow_redirects=True)
            if r.status_code == 200:
                open(local_fp, 'wt').write(r.text)
            else:
                log.warning(f'Could not download EBNF file from Github -- Status: {r.status_code}  Msg: {r.text}')
        except Exception as e:
            log.warning(f'Could not download EBNF file from Github -- Status: {r.status_code}  Msg: {e}')
    except Exception as e:
        log.warning('Could not download BEL EBNF template file')
        if not os.path.exists(f'{spec_dir}/local_fp'):
            log.error('No BEL EBNF template file available')
    return local_fp

def get_function_help(function: str, bel_spec: BELSpec):
    """Get function_help given function name

    This will get the function summary template (argument summary in signature)
    and the argument help listing."""
    function_long = bel_spec['functions']['to_long'].get(function)
    function_help = []
    if function_long:
        for signature in bel_spec['functions']['signatures'][function_long]['signatures']:
            function_help.append({'function_summary': signature['argument_summary'], 'argument_help': signature['argument_help_listing'], 'description': bel_spec['functions']['info'][function_long]['description']})
    return function_help

def in_span(loc: int, span: Span) -> bool:
    """Checks if loc is inside span"""
    if loc >= span[0] and loc <= span[1]:
        return True
    else:
        return False

def function_completions(completion_text: str, bel_spec: BELSpec, function_list: list, bel_fmt: str, size: int) -> list:
    """Filter BEL functions by prefix

    Args:
        prefix: completion string
        bel_fmt: short, medium, long BEL formats
        spec: BEL specification

    Returns:
        list: list of BEL functions that match prefix"""
    if isinstance(function_list, list):
        if bel_fmt in ['short', 'medium']:
            function_list = [bel_spec['functions']['to_short'][fn] for fn in function_list]
        else:
            function_list = [bel_spec['functions']['to_long'][fn] for fn in function_list]
    elif bel_fmt in ['short', 'medium']:
        function_list = bel_spec['functions']['primary']['list_short']
    else:
        function_list = bel_spec['functions']['primary']['list_long']
    matches = []
    for f in function_list:
        escaped_completion_text = completion_text.replace('(', '\\(').replace(')', '\\)')
        log.debug(f'Completion match: {escaped_completion_text}  F: {f}')
        if re.match(escaped_completion_text, f):
            matches.append(f)
    replace_list = []
    for match in matches:
        if completion_text:
            highlight = match.replace(completion_text, f'<em>{completion_text}</em>')
        else:
            highlight = completion_text
        replace_list.append({'replacement': match, 'label': f'{match}()', 'highlight': highlight, 'type': 'Function'})
    return replace_list[:size]

def parse_relations(belstr: str, char_locs: CharLocs, parsed: Parsed, errors: Errors) -> Tuple[Parsed, Errors]:
    """Parse relations from BEL string

    Args:
        belstr: BEL string as one single string (not list of chars)
        char_locs: paren, comma and quote char locations
        parsed: data structure for parsed functions, relations, nested
        errors: error messages

    Returns:
        (parsed, errors):"""
    quotes = char_locs['quotes']
    quoted_range = set([i for start, end in quotes.items() for i in range(start, end)])
    for match in relations_pattern_middle.finditer(belstr):
        start, end = match.span(1)
        end = end - 1
        if start != end:
            test_range = set(range(start, end))
        else:
            test_range = set(start)
        if test_range.intersection(quoted_range):
            continue
        span_key = (start, end)
        parsed[span_key] = {'type': 'Relation', 'name': match.group(1), 'span': (start, end)}
    for match in relations_pattern_end.finditer(belstr):
        start, end = match.span(1)
        log.debug(f'Relation-end {match}')
        end = end - 1
        if start != end:
            test_range = set(range(start, end))
        else:
            test_range = set(start)
        if test_range.intersection(quoted_range):
            continue
        span_key = (start, end)
        parsed[span_key] = {'type': 'Relation', 'name': match.group(1), 'span': (start, end)}
    return (parsed, errors)

def parse_nested(bels: list, char_locs: CharLocs, parsed: Parsed, errors: Errors) -> Tuple[Parsed, Errors]:
    """Parse nested BEL object"""
    for sp in char_locs['nested_parens']:
        ep, level = char_locs['nested_parens'][sp]
        if ep == -1:
            ep = len(bels) + 1
        parsed[sp, ep] = {'type': 'Nested', 'span': (sp, ep)}
    return (parsed, errors)

def print_spans(spans, max_idx: int) -> None:
    """Quick test to show how character spans match original BEL String

    Mostly for debugging purposes"""
    bel_spans = [' '] * (max_idx + 3)
    for val, span in spans:
        if val in ['Nested', 'NSArg']:
            continue
        for i in range(span[0], span[1] + 1):
            bel_spans[i] = val[0]
    bel_spans = [' '] * (max_idx + 3)
    for val, span in spans:
        if val not in ['Nested']:
            continue
        for i in range(span[0], span[1] + 1):
            bel_spans[i] = val[0]

def parsed_function_to_ast(parsed: Parsed, parsed_key):
    """Create AST for top-level functions"""
    sub = parsed[parsed_key]
    subtree = {'type': 'Function', 'span': sub['span'], 'function': {'name': sub['name'], 'name_span': sub['name_span'], 'parens_span': sub.get('parens_span', [])}}
    args = []
    for arg in parsed[parsed_key].get('args', []):
        if arg['type'] == 'Function':
            args.append(parsed_function_to_ast(parsed, arg['span']))
        elif arg['type'] == 'NSArg':
            args.append({'arg': arg['arg'], 'type': arg['type'], 'span': arg['span'], 'nsarg': {'ns': arg['ns'], 'ns_val': arg['ns_val'], 'ns_span': arg['ns_span'], 'ns_val_span': arg['ns_val_span']}})
        elif arg['type'] == 'StrArg':
            args.append({'arg': arg['arg'], 'type': arg['type'], 'span': arg['span']})
    subtree['args'] = copy.deepcopy(args)
    return subtree

def get_ast_obj(belstr, bel_version, component_type: str=''):
    """Convert AST partialparse dict to BELAst"""
    ast_dict, errors = get_ast_dict(belstr, component_type)
    spec = bel_specification.get_specification(bel_version)
    subj = ast_dict['subject']
    subj_ast = add_ast_fn(subj, spec)
    relation = None
    obj = None
    if 'relation' in ast_dict:
        relation = ast_dict['relation']['name']
    if 'object' in ast_dict:
        obj = ast_dict['object']
        obj_ast = add_ast_fn(obj, spec)
        return BELAst(subj_ast, relation, obj_ast, spec)
    elif 'nested' in ast_dict:
        nested_subj = ast_dict['nested']['subject']
        nested_subj_ast = add_ast_fn(nested_subj, spec)
        nested_relation = ast_dict['nested']['relation']['name']
        nested_obj = ast_dict['nested']['object']
        nested_obj_ast = add_ast_fn(nested_obj, spec)
        return BELAst(subj_ast, relation, BELAst(nested_subj_ast, nested_relation, nested_obj_ast, spec), spec)
    return BELAst(subj_ast, None, None, spec)

def add_ast_fn(d, spec, parent_function=None):
    """Convert dict AST to object AST Function

    Args:
        ast_fn: AST object Function
        d: AST as dictionary
        spec: BEL Specification

    Return:
        ast_fn"""
    if d['type'] == 'Function':
        ast_fn = Function(d['function']['name'], spec, parent_function=parent_function)
        for arg in d['args']:
            if arg['type'] == 'Function':
                ast_fn.add_argument(add_ast_fn(arg, spec, parent_function=ast_fn))
            elif arg['type'] == 'NSArg':
                ast_fn.add_argument(NSArg(arg['nsarg']['ns'], arg['nsarg']['ns_val'], ast_fn))
            elif arg['type'] == 'StrArg':
                ast_fn.add_argument(StrArg(arg['arg'], ast_fn))
    return ast_fn

def populate_ast_nsarg_orthologs(ast, species):
    """Recursively collect NSArg orthologs for BEL AST

    This requires bo.collect_nsarg_norms() to be run first so NSArg.canonical is available

    Args:
        ast: AST at recursive point in belobj
        species: dictionary of species ids vs labels for or"""
    ortholog_namespace = 'EG'
    if isinstance(ast, NSArg):
        if re.match(ortholog_namespace, ast.canonical):
            orthologs = bel.terms.orthologs.get_orthologs(ast.canonical, list(species.keys()))
            for species_id in species:
                if species_id in orthologs:
                    orthologs[species_id]['species_label'] = species[species_id]
            ast.orthologs = copy.deepcopy(orthologs)
    if hasattr(ast, 'args'):
        for arg in ast.args:
            populate_ast_nsarg_orthologs(arg, species)
    return ast

def extract_ast_species(ast):
    """Extract species from ast.species set of tuples (id, label)"""
    species_id = 'None'
    species_label = 'None'
    species = [(species_id, species_label) for species_id, species_label in ast.species if species_id]
    if len(species) == 1:
        species_id, species_label = species[0]
    if not species_id:
        species_id = 'None'
        species_label = 'None'
    log.debug(f'AST Species: {ast.species}  Species: {species}  SpeciesID: {species_id}')
    return (species_id, species_label)

def orthologize_context(orthologize_target: str, annotations: Mapping[str, Any]) -> Mapping[str, Any]:
    """Orthologize context

    Replace Species context with new orthologize target and add a annotation type of OrthologizedFrom"""
    url = f"{config['bel_api']['servers']['api_url']}/terms/{orthologize_target}"
    r = utils.get_url(url)
    species_label = r.json().get('label', 'unlabeled')
    orthologized_from = {}
    for idx, annotation in enumerate(annotations):
        if annotation['type'] == 'Species':
            orthologized_from = {'id': annotation['id'], 'label': annotation['label']}
            annotations[idx] = {'type': 'Species', 'id': orthologize_target, 'label': species_label}
    if 'id' in orthologized_from:
        annotations.append({'type': 'OrigSpecies', 'id': f"Orig-{orthologized_from['id']}", 'label': f"Orig-{orthologized_from['label']}"})
    return annotations

def migrate_into_triple(belstr: str) -> str:
    """Migrate BEL1 assertion into BEL 2.0.0 SRO triple"""
    bo.ast = bel.lang.partialparse.get_ast_obj(belstr, '2.0.0')
    return migrate_ast(bo.ast).to_triple()

def convert_pmod(pmod):
    """Update BEL1 pmod() protein modification term"""
    if pmod.args[0].value in spec['bel1_migration']['protein_modifications']:
        pmod.args[0].value = spec['bel1_migration']['protein_modifications'][pmod.args[0].value]
    return pmod

def get_user_creds(username, password):
    """Get username/password

    Use provided username and password OR in config OR blank in that order"""
    username = utils.first_true([username, config['bel_api']['servers']['arangodb_username']], default='')
    password = utils.first_true([password, config['secrets']['bel_api']['servers'].get('arangodb_password')], default='')
    return (username, password)

def get_belapi_handle(client, username=None, password=None):
    """Get BEL API arango db handle"""
    username, password = get_user_creds(username, password)
    sys_db = client.db('_system', username=username, password=password)
    try:
        if username and password:
            belapi_db = sys_db.create_database(name=belapi_db_name, users=[{'username': username, 'password': password, 'active': True}])
        else:
            belapi_db = sys_db.create_database(name=belapi_db_name)
    except arango.exceptions.DatabaseCreateError:
        if username and password:
            belapi_db = client.db(belapi_db_name, username=username, password=password)
        else:
            belapi_db = client.db(belapi_db_name)
    try:
        belapi_db.create_collection(belapi_settings_name)
    except Exception:
