def nanopub_stats(ctx, input_fn):
    """Collect statistics on nanopub file

    input_fn can be json, jsonl or yaml and additionally gzipped"""
    counts = {'nanopubs': 0, 'assertions': {'total': 0, 'subject_only': 0, 'nested': 0, 'relations': {}}}
    for np in bnf.read_nanopubs(input_fn):
        if 'nanopub' in np:
            counts['nanopubs'] += 1
            counts['assertions']['total'] += len(np['nanopub']['assertions'])
            for assertion in np['nanopub']['assertions']:
                if assertion['relation'] is None:
                    counts['assertions']['subject_only'] += 1
                else:
                    if re.match('\\s*\\(', assertion['object']):
                        counts['assertions']['nested'] += 1
                    if not assertion.get('relation') in counts['assertions']['relations']:
                        counts['assertions']['relations'][assertion.get('relation')] = 1
                    else:
                        counts['assertions']['relations'][assertion.get('relation')] += 1
    counts['assertions']['relations'] = sorted(counts['assertions']['relations'])
    print('DumpVar:\n', json.dumps(counts, indent=4))

def elasticsearch(delete, index_name):
    """Setup Elasticsearch namespace indexes

    This will by default only create the indexes and run the namespace index mapping
    if the indexes don't exist.  The --delete option will force removal of the
    index if it exists.

    The index_name should be aliased to the index 'terms' when it's ready"""
    if delete:
        bel.db.elasticsearch.get_client(delete=True)
    else:
        bel.db.elasticsearch.get_client()

def arangodb(delete, db_name):
    """Setup ArangoDB database

    db_name: Either 'belns' or 'edgestore' - must be one or the other

    This will create the database, collections and indexes on the collection if it doesn't exist.

    The --delete option will force removal of the database if it exists."""
    if delete:
        client = bel.db.arangodb.get_client()
        bel.db.arangodb.delete_database(client, db_name)
    if db_name == 'belns':
        bel.db.arangodb.get_belns_handle(client)
    elif db_name == 'edgestore':
        bel.db.arangodb.get_edgestore_handle(client)

def find_pyd_file():
    """Return path to .pyd after successful build command.
    :return: Path to .pyd file or None."""
    if not os.path.isdir('./build'):
        raise NotADirectoryError
    for path, dirs, files in os.walk('./build'):
        for file_name in files:
            file_name_parts = os.path.splitext(file_name)
            if file_name_parts[1] == '.pyd':
                return path
    return None

def _void_array_to_nested_list(res, _func, _args):
    """Dereference the FFI result to a list of coordinates"""
    try:
        shape = (res.coords.len, 2)
        ptr = cast(res.coords.data, POINTER(c_double))
        array = np.ctypeslib.as_array(ptr, shape)
        return array.tolist()
    finally:
        drop_array(res.coords)

def is_json_file(abspath):
    """Parse file extension.

    - *.json: uncompressed, utf-8 encode json file
    - *.gz: compressed, utf-8 encode json file"""
    abspath = abspath.lower()
    fname, ext = os.path.splitext(abspath)
    if ext in ['.json', '.js']:
        is_json = True
    elif ext == '.gz':
        is_json = False
    elif ext == '.tmp':
        return is_json_file(fname)
    else:
        raise JsonExtError("'%s' is not a valid json file. extension has to be '.json' for uncompressed, '.gz' for compressed." % abspath)
    return is_json

def lower_ext(abspath):
    """Convert file extension to lowercase.
    """
    fname, ext = os.path.splitext(abspath)
    return fname + ext.lower()

def _read_requirements(filename, extra_packages):
    """Returns a list of package requirements read from the file."""
    requirements_file = open(filename).read()
    hard_requirements = []
    for line in requirements_file.splitlines():
        if _is_requirement(line):
            if line.find(';') > -1:
                dep, condition = tuple(line.split(';'))
                extra_packages[condition.strip()].append(dep.strip())
            else:
                hard_requirements.append(line.strip())
    return (hard_requirements, extra_packages)

def field(ctx, text, index, delimiter=' '):
    """Reference a field in string separated by a delimiter"""
    splits = text.split(delimiter)
    splits = [f for f in splits if f != delimiter and len(f.strip()) > 0]
    index = conversions.to_integer(index, ctx)
    if index < 1:
        raise ValueError('Field index cannot be less than 1')
    if index <= len(splits):
        return splits[index - 1]
    else:
        return ''

def epoch(ctx, datetime):
    """Converts the given date to the number of seconds since January 1st, 1970 UTC"""
    return conversions.to_decimal(str(conversions.to_datetime(datetime, ctx).timestamp()), ctx)

def read_digits(ctx, text):
    """Formats digits in text for reading in TTS"""
    def chunk(value, chunk_size):
        return [value[i:i + chunk_size] for i in range(0, len(value), chunk_size)]
    text = conversions.to_string(text, ctx).strip()
    if not text:
        return ''
    if text[0] == '+':
        text = text[1:]
    length = len(text)
    if length == 9:
        result = ' '.join(text[:3])
        result += ' , ' + ' '.join(text[3:5])
        result += ' , ' + ' '.join(text[5:])
        return result
    if length % 3 == 0 and length > 3:
        chunks = chunk(text, 3)
        return ' '.join(','.join(chunks))
    if length % 4 == 0:
        chunks = chunk(text, 4)
        return ' '.join(','.join(chunks))
    return ','.join(text)

def word_count(ctx, text, by_spaces=False):
    """Returns the number of words in the given text string"""
    text = conversions.to_string(text, ctx)
    by_spaces = conversions.to_boolean(by_spaces, ctx)
    return len(__get_words(text, by_spaces))

def word_slice(ctx, text, start, stop=0, by_spaces=False):
    """Extracts a substring spanning from start up to but not-including stop"""
    text = conversions.to_string(text, ctx)
    start = conversions.to_integer(start, ctx)
    stop = conversions.to_integer(stop, ctx)
    by_spaces = conversions.to_boolean(by_spaces, ctx)
    if start == 0:
        raise ValueError('Start word cannot be zero')
    elif start > 0:
        start -= 1
    if stop == 0:
        stop = None
    elif stop > 0:
        stop -= 1
    words = __get_words(text, by_spaces)
    selection = operator.getitem(words, slice(start, stop))
    return ' '.join(selection)

def format_date(ctx, text):
    """Takes a single parameter (date as string) and returns it in the format defined by the org"""
    dt = conversions.to_datetime(text, ctx)
    return dt.astimezone(ctx.timezone).strftime(ctx.get_date_format(True))

def format_location(ctx, text):
    """Takes a single parameter (administrative boundary as a string) and returns the name of the leaf boundary"""
    text = conversions.to_string(text, ctx)
    return text.split('>')[-1].strip()

def regex_group(ctx, text, pattern, group_num):
    """Tries to match the text with the given pattern and returns the value of matching group"""
    text = conversions.to_string(text, ctx)
    pattern = conversions.to_string(pattern, ctx)
    group_num = conversions.to_integer(group_num, ctx)
    expression = regex.compile(pattern, regex.UNICODE | regex.IGNORECASE | regex.MULTILINE | regex.V0)
    match = expression.search(text)
    if not match:
        return ''
    if group_num < 0 or group_num > len(match.groups()):
        raise ValueError('No such matching group %d' % group_num)
    return match.group(group_num)

def __get_words(text, by_spaces):
    """Helper function which splits the given text string into words. If by_spaces is false, then text like
    '01-02-2014' will be split into 3 separate words. For backwards compatibility, this is the default for all
    expression functions.
    :param text: the text to split
    :param by_spaces: whether words should be split only by spaces or by punctuation like '-', '.' etc"""
    if by_spaces:
        splits = regex.split('\\s+', text, flags=regex.MULTILINE | regex.UNICODE | regex.V0)
        return [split for split in splits if split]
    else:
        return tokenize(text)

def decimal_round(number, num_digits, rounding=ROUND_HALF_UP):
    """Rounding for decimals with support for negative digits"""
    exp = Decimal(10) ** (-num_digits)
    if num_digits >= 0:
        return number.quantize(exp, rounding)
    else:
        return exp * (number / exp).to_integral_value(rounding)

def parse_json_date(value):
    """Parses an ISO8601 formatted datetime from a string value"""
    if not value:
        return None
    return datetime.datetime.strptime(value, JSON_DATETIME_FORMAT).replace(tzinfo=pytz.UTC)

def format_json_date(value):
    '''Formats a datetime as ISO8601 in UTC with millisecond precision, e.g. "2014-10-03T09:41:12.790Z"'''
    if not value:
        return None
    micro_precision = value.astimezone(pytz.UTC).strftime(JSON_DATETIME_FORMAT)
    return micro_precision[:-4] + 'Z'

def clean(ctx, text):
    """Removes all non-printable characters from a text string"""
    text = conversions.to_string(text, ctx)
    return ''.join([c for c in text if ord(c) >= 32])

def fixed(ctx, number, decimals=2, no_commas=False):
    """Formats the given number in decimal format using a period and commas"""
    value = _round(ctx, number, decimals)
    format_str = '{:f}' if no_commas else '{:,f}'
    return format_str.format(value)

def left(ctx, text, num_chars):
    """Returns the first characters in a text string"""
    num_chars = conversions.to_integer(num_chars, ctx)
    if num_chars < 0:
        raise ValueError("Number of chars can't be negative")
    return conversions.to_string(text, ctx)[0:num_chars]

def rept(ctx, text, number_times):
    """Repeats text a given number of times"""
    if number_times < 0:
        raise ValueError("Number of times can't be negative")
    return conversions.to_string(text, ctx) * conversions.to_integer(number_times, ctx)

def right(ctx, text, num_chars):
    """Returns the last characters in a text string"""
    num_chars = conversions.to_integer(num_chars, ctx)
    if num_chars < 0:
        raise ValueError("Number of chars can't be negative")
    elif num_chars == 0:
        return ''
    else:
        return conversions.to_string(text, ctx)[-num_chars:]

def substitute(ctx, text, old_text, new_text, instance_num=-1):
    """Substitutes new_text for old_text in a text string"""
    text = conversions.to_string(text, ctx)
    old_text = conversions.to_string(old_text, ctx)
    new_text = conversions.to_string(new_text, ctx)
    if instance_num < 0:
        return text.replace(old_text, new_text)
    else:
        splits = text.split(old_text)
        output = splits[0]
        instance = 1
        for split in splits[1:]:
            sep = new_text if instance == instance_num else old_text
            output += sep + split
            instance += 1
        return output

def _unicode(ctx, text):
    """Returns a numeric code for the first character in a text string"""
    text = conversions.to_string(text, ctx)
    if len(text) == 0:
        raise ValueError("Text can't be empty")
    return ord(text[0])

def date(ctx, year, month, day):
    """Defines a date value"""
    return _date(conversions.to_integer(year, ctx), conversions.to_integer(month, ctx), conversions.to_integer(day, ctx))

def datedif(ctx, start_date, end_date, unit):
    """Calculates the number of days, months, or years between two dates."""
    start_date = conversions.to_date(start_date, ctx)
    end_date = conversions.to_date(end_date, ctx)
    unit = conversions.to_string(unit, ctx).lower()
    if start_date > end_date:
        raise ValueError('Start date cannot be after end date')
    if unit == 'y':
        return relativedelta(end_date, start_date).years
    elif unit == 'm':
        delta = relativedelta(end_date, start_date)
        return 12 * delta.years + delta.months
    elif unit == 'd':
        return (end_date - start_date).days
    elif unit == 'md':
        return relativedelta(end_date, start_date).days
    elif unit == 'ym':
        return relativedelta(end_date, start_date).months
    elif unit == 'yd':
        return (end_date - start_date.replace(year=end_date.year)).days
    raise ValueError('Invalid unit value: %s' % unit)

def time(ctx, hours, minutes, seconds):
    """Defines a time value"""
    return _time(conversions.to_integer(hours, ctx), conversions.to_integer(minutes, ctx), conversions.to_integer(seconds, ctx))

def _abs(ctx, number):
    """Returns the absolute value of a number"""
    return conversions.to_decimal(abs(conversions.to_decimal(number, ctx)), ctx)

def _int(ctx, number):
    """Rounds a number down to the nearest integer"""
    return conversions.to_integer(conversions.to_decimal(number, ctx).to_integral_value(ROUND_FLOOR), ctx)

def _max(ctx, *number):
    """Returns the maximum value of all arguments"""
    if len(number) == 0:
        raise ValueError('Wrong number of arguments')
    result = conversions.to_decimal(number[0], ctx)
    for arg in number[1:]:
        arg = conversions.to_decimal(arg, ctx)
        if arg > result:
            result = arg
    return result

def mod(ctx, number, divisor):
    """Returns the remainder after number is divided by divisor"""
    number = conversions.to_decimal(number, ctx)
    divisor = conversions.to_decimal(divisor, ctx)
    return number - divisor * _int(ctx, number / divisor)

def _power(ctx, number, power):
    """Returns the result of a number raised to a power"""
    return decimal_pow(conversions.to_decimal(number, ctx), conversions.to_decimal(power, ctx))

def randbetween(ctx, bottom, top):
    """Returns a random integer number between the numbers you specify"""
    bottom = conversions.to_integer(bottom, ctx)
    top = conversions.to_integer(top, ctx)
    return random.randint(bottom, top)

def _round(ctx, number, num_digits):
    """Rounds a number to a specified number of digits"""
    number = conversions.to_decimal(number, ctx)
    num_digits = conversions.to_integer(num_digits, ctx)
    return decimal_round(number, num_digits, ROUND_HALF_UP)

def rounddown(ctx, number, num_digits):
    """Rounds a number down, toward zero"""
    number = conversions.to_decimal(number, ctx)
    num_digits = conversions.to_integer(num_digits, ctx)
    return decimal_round(number, num_digits, ROUND_DOWN)

def roundup(ctx, number, num_digits):
    """Rounds a number up, away from zero"""
    number = conversions.to_decimal(number, ctx)
    num_digits = conversions.to_integer(num_digits, ctx)
    return decimal_round(number, num_digits, ROUND_UP)

def trunc(ctx, number):
    """Truncates a number to an integer by removing the fractional part of the number"""
    return conversions.to_integer(conversions.to_decimal(number, ctx).to_integral_value(ROUND_DOWN), ctx)

def _and(ctx, *logical):
    """Returns TRUE if and only if all its arguments evaluate to TRUE"""
    for arg in logical:
        if not conversions.to_boolean(arg, ctx):
            return False
    return True

def _if(ctx, logical_test, value_if_true=0, value_if_false=False):
    """Returns one value if the condition evaluates to TRUE, and another value if it evaluates to FALSE"""
    return value_if_true if conversions.to_boolean(logical_test, ctx) else value_if_false

def _or(ctx, *logical):
    """Returns TRUE if any argument is TRUE"""
    for arg in logical:
        if conversions.to_boolean(arg, ctx):
            return True
    return False

def can_be_(self, state):
    """Check if machine can transit to given state."""
    translator = self._meta['translator']
    state = translator.translate(state)
    if self._meta['complete']:
        return True
    if self.actual_state is None:
        return True
    transitions = self._meta['transitions'][self.actual_state]
    return state in transitions

def set_(self, state):
    """Set new state for machine."""
    if not self.can_be_(state):
        state = self._meta['translator'].translate(state)
        raise TransitionError("Cannot transit from '{actual_value}' to '{value}'.".format(actual_value=self.actual_state.value, value=state.value))
    self.force_set(state)

def generate_getter(value):
    """Generate getter for given value."""
    @property
    @wraps(is_)
    def getter(self):
        return self.is_(value)
    return getter

def generate_checker(value):
    """Generate state checker for given value."""
    @property
    @wraps(can_be_)
    def checker(self):
        return self.can_be_(value)
    return checker

def generate_setter(value):
    """Generate setter for given value."""
    @wraps(set_)
    def setter(self):
        self.set_(value)
    return setter

def is_venv():
    """Check whether if this workspace is a virtualenv.
    """
    dir_path = os.path.dirname(SRC)
    is_venv_flag = True
    if SYS_NAME == 'Windows':
        executable_list = ['activate', 'pip.exe', 'python.exe']
    elif SYS_NAME in ['Darwin', 'Linux']:
        executable_list = ['activate', 'pip', 'python']
    for executable in executable_list:
        path = os.path.join(dir_path, BIN_SCRIPTS, executable)
        if not os.path.exists(path):
            is_venv_flag = False
    return is_venv_flag

def find_linux_venv_py_version():
    """Find python version name used in this virtualenv.

    For example: ``python2.7``, ``python3.4``"""
    available_python_version = ['python2.6', 'python2.7', 'python3.3', 'python3.4', 'python3.5', 'python3.6']
    dir_path = os.path.dirname(SRC)
    for basename in os.listdir(os.path.join(dir_path, BIN_SCRIPTS)):
        for python_version in available_python_version:
            if python_version in basename:
                return python_version
    raise Exception("Can't find virtualenv python version!")

def find_venv_DST():
    """Find where this package should be installed to in this virtualenv.

    For example: ``/path-to-venv/lib/python2.7/site-packages/package-name``"""
    dir_path = os.path.dirname(SRC)
    if SYS_NAME == 'Windows':
        DST = os.path.join(dir_path, 'Lib', 'site-packages', PKG_NAME)
    elif SYS_NAME in ['Darwin', 'Linux']:
        python_version = find_linux_venv_py_version()
        DST = os.path.join(dir_path, 'lib', python_version, 'site-packages', PKG_NAME)
    return DST

def find_DST():
    """Find where this package should be installed to.
    """
    if SYS_NAME == 'Windows':
        return os.path.join(site.getsitepackages()[1], PKG_NAME)
    elif SYS_NAME in ['Darwin', 'Linux']:
        return os.path.join(site.getsitepackages()[0], PKG_NAME)

def md5_of_file(abspath):
    """Md5 value of a file.
    """
    chunk_size = 1024 * 1024
    m = hashlib.md5()
    with open(abspath, 'rb') as f:
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            m.update(data)
    return m.hexdigest()

def check_need_install():
    """Check if installed package are exactly the same to this one.
    By checking md5 value of all files."""
    need_install_flag = False
    for root, _, basename_list in os.walk(SRC):
        if os.path.basename(root) != '__pycache__':
            for basename in basename_list:
                src = os.path.join(root, basename)
                dst = os.path.join(root.replace(SRC, DST), basename)
                if os.path.exists(dst):
                    if md5_of_file(src) != md5_of_file(dst):
                        return True
                else:
                    return True
    return need_install_flag

def is_git(path):
    """Return True if this is a git repo."""
    try:
        repo_dir = run_cmd(path, 'git', 'rev-parse', '--git-dir')
        return True if repo_dir else False
    except (OSError, RuntimeError):
        return False

def date_version(scm=None):
    """Generate a version string based on the SCM type and the date."""
    dt = str(time.strftime('%Y%m%d%H%M'))
    if scm:
        version = '0.0+unknown.{0}.{1}'.format(scm, dt)
    else:
        version = '0.0+unknown.' + dt
    return version

def get_version_from_scm(path=None):
    """Get the current version string of this package using SCM tool.

    Parameters
    ----------
    path : None or string, optional
        The SCM checkout path (default is current directory)

    Returns
    -------
    version : string
        The version string for this package"""
    if is_git(path):
        return ('git', get_git_version(path))
    elif is_svn(path):
        return ('svn', get_svn_version(path))
    return (None, None)

def get_version_from_module(module):
    """Use pkg_resources to get version of installed module by name."""
    if module is not None:
        module = str(module).split('.', 1)[0]
        try:
            package = pkg_resources.get_distribution(module)
            return package.version
        except pkg_resources.DistributionNotFound:
            pass

def _must_decode(value):
    """Copied from pkginfo 1.4.1, _compat module."""
    if type(value) is bytes:
        try:
            return value.decode('utf-8')
        except UnicodeDecodeError:
            return value.decode('latin1')
    return value

def get_version_from_unpacked_sdist(path):
    """Assume path points to unpacked source distribution and get version."""
    try:
        with open(os.path.join(path, 'PKG-INFO')) as f:
            data = f.read()
    except IOError:
        return
    fp = StringIO(_must_decode(data))
    msg = Parser().parse(fp)
    value = msg.get('Version')
    if value != 'UNKNOWN':
        return value

def get_version_from_file(path):
    """Find the VERSION_FILE and return its contents.

    Returns
    -------
    version : string or None"""
    filename = os.path.join(path, VERSION_FILE)
    if not os.path.isfile(filename):
        filename = os.path.join(os.path.dirname(path), VERSION_FILE)
        if not os.path.isfile(filename):
            filename = ''
    if filename:
        with open(filename) as fh:
            version = fh.readline().strip()
            if version:
                return version

def normalised(version):
    """Normalise a version string according to PEP 440, if possible."""
    norm_version = pkg_resources.parse_version(version)
    if not isinstance(norm_version, tuple):
        return str(norm_version)
    else:
        public, sep, local = version.lower().partition('+')
        if len(public) >= 2:
            if public[0] == 'v' and public[1] in '0123456789':
                public = public[1:]
        local = NON_ALPHANUMERIC.sub('.', local)
        return public + sep + local

def _sane_version_list(version):
    """Ensure the major and minor are int.

    Parameters
    ----------
    version: list
        Version components

    Returns
    -------
    version: list
        List of components where first two components has been sanitised"""
    v0 = str(version[0])
    if v0:
        try:
            v0 = v0.lstrip('v').lstrip('V')
            v0 = int(v0)
        except ValueError:
            v0 = None
    if v0 is None:
        version = [0, 0] + version
    else:
        version[0] = v0
    try:
        version[1] = int(version[1])
    except ValueError:
        version = [version[0], 0] + version[1:]
    return version

