def get_results_generator(future_list, timeout=None, sort_by_completed=False):
    """Return as a generator of tasks order by completed sequence."""
    try:
        if sort_by_completed:
            for future in as_completed(future_list, timeout=timeout):
                yield future.x
        else:
            for future in future_list:
                yield future.x
    except TimeoutError:
        return

def update_redis(project: str, environment: str, feature: str, state: str) -> None:
    """Update redis state for a feature flag.

    :param project: LaunchDarkly project key.
    :param environment: LaunchDarkly environment key.
    :param feature: LaunchDarkly feature key.
    :param state: State for a feature flag."""
    try:
        hosts = RedisWrapper.connection_string_parser(os.environ.get('REDIS_HOSTS'))
    except RuntimeError as ex:
        LOG.error(ex)
        sys.exit(1)
    for host in hosts:
        LOG.info('connecting to %s:%s', host.host, host.port)
        try:
            if valid_state(state):
                new_state = state.lower()
                redis = RedisWrapper(host.host, host.port, project, environment)
                redis.update_flag_record(new_state, feature)
                create_file(project, environment, feature, new_state)
                LOG.info('%s was successfully updated.', feature)
            else:
                raise Exception('Invalid state: {0}, -s needs                     to be either on or off.'.format(state))
        except KeyError as ex:
            LOG.error('unable to update %s. Exception: %s', host.host, ex)
            sys.exit(1)

def is_dicom_dir(datapath):
    """Check if in dir is one or more dicom file. We use two methods.
    First is based on dcm extension detection."""
    retval = False
    datapath = op.expanduser(datapath)
    for f in os.listdir(datapath):
        if f.endswith(('.dcm', '.DCM')):
            retval = True
            return True
        try:
            pydicom.read_file(os.path.join(datapath, f))
            retval = True
        except Exception as e:
            logger.warning('Unable to read dicom file ' + str(f))
            logger.warning(e)
        if retval:
            return True
    return False

def get_slice_location(dcmdata, teil=None):
    """get location of the slice

    :param dcmdata: dicom data structure
    :param teil: filename. Used when slice location doesnt exist
    :return:"""
    slice_location = None
    if hasattr(dcmdata, 'SliceLocation'):
        try:
            slice_location = float(dcmdata.SliceLocation)
        except Exception as exc:
            logger.info('It is not possible to use SliceLocation')
            logger.debug(traceback.format_exc())
    if slice_location is None and hasattr(dcmdata, 'SliceThickness') and (teil is not None):
        logger.debug('Estimating SliceLocation wiht image number and SliceThickness')
        i = list(map(int, re.findall('\\d+', teil)))
        i = i[-1]
        try:
            slice_location = float(i * float(dcmdata.SliceThickness))
        except ValueError as e:
            print(type(dcmdata.SliceThickness))
            print(dcmdata.SliceThickness)
            logger.debug(traceback.format_exc())
            logger.debug('SliceThickness problem')
    if slice_location is None and hasattr(dcmdata, 'ImagePositionPatient') and hasattr(dcmdata, 'ImageOrientationPatient'):
        if dcmdata.ImageOrientationPatient == [1, 0, 0, 0, 1, 0]:
            slice_location = dcmdata.ImagePositionPatient[2]
        else:
            logger.warning('Unknown ImageOrientationPatient')
    if slice_location is None:
        logger.warning('Problem with slice location')
    return slice_location

