def list_filter(lst, startswith=None, notstartswith=None, contain=None, notcontain=None):
    """Keep in list items according to filter parameters.

    :param lst: item list
    :param startswith: keep items starting with
    :param notstartswith: remove items starting with
    :return:"""
    keeped = []
    for item in lst:
        keep = False
        if startswith is not None:
            if item.startswith(startswith):
                keep = True
        if notstartswith is not None:
            if not item.startswith(notstartswith):
                keep = True
        if contain is not None:
            if contain in item:
                keep = True
        if notcontain is not None:
            if not notcontain in item:
                keep = True
        if keep:
            keeped.append(item)
    return keeped

def split_dict(dct, keys):
    """Split dict into two subdicts based on keys.

    :param dct:
    :param keys:
    :return: dict_in, dict_out"""
    if type(dct) == collections.OrderedDict:
        dict_in = collections.OrderedDict()
        dict_out = collections.OrderedDict()
    else:
        dict_in = {}
        dict_out = {}
    for key, value in dct.items:
        if key in keys:
            dict_in[key] = value
        else:
            dict_out[key] = value
    return (dict_in, dict_out)

def flatten_dict_join_keys(dct, join_symbol=' '):
    """Flatten dict with defined key join symbol.

    :param dct: dict to flatten
    :param join_symbol: default value is " "
    :return:"""
    return dict(flatten_dict(dct, join=lambda a, b: a + join_symbol + b))

def ndarray_to_list_in_structure(item, squeeze=True):
    """Change ndarray in structure of lists and dicts into lists.
    """
    tp = type(item)
    if tp == np.ndarray:
        if squeeze:
            item = item.squeeze()
        item = item.tolist()
    elif tp == list:
        for i in range(len(item)):
            item[i] = ndarray_to_list_in_structure(item[i])
    elif tp == dict:
        for lab in item:
            item[lab] = ndarray_to_list_in_structure(item[lab])
    return item

def ordered_dict_to_dict(config):
    """Use dict instead of ordered dict in structure."""
    if type(config) == collections.OrderedDict:
        config = dict(config)
    if type(config) == list:
        for i in range(0, len(config)):
            config[i] = ordered_dict_to_dict(config[i])
    elif type(config) == dict:
        for key in config:
            config[key] = ordered_dict_to_dict(config[key])
    return config

def get_query_columns(query):
    """:type query str
    :rtype: list[str]"""
    columns = []
    last_keyword = None
    last_token = None
    keywords_ignored = ['AS', 'AND', 'OR', 'IN', 'IS', 'NOT', 'NOT NULL', 'LIKE', 'CASE', 'WHEN']
    functions_ignored = ['COUNT', 'MIN', 'MAX', 'FROM_UNIXTIME', 'DATE_FORMAT', 'CAST', 'CONVERT']
    for token in get_query_tokens(query):
        if token.is_keyword and token.value.upper() not in keywords_ignored:
            last_keyword = token.value.upper()
        elif token.ttype is Name:
            if last_keyword in ['SELECT', 'WHERE', 'BY', 'ON'] and last_token.value.upper() not in ['AS']:
                if token.value.upper() not in functions_ignored:
                    if str(last_token) == '.':
                        table_name = columns[-1]
                        columns[-1] = '{}.{}'.format(table_name, token)
                    else:
                        columns.append(str(token.value))
            elif last_keyword in ['INTO'] and last_token.ttype is Punctuation:
                columns.append(str(token.value).strip('`'))
        elif token.ttype is Wildcard:
            if last_keyword == 'SELECT' and last_token.value != '(':
                if str(last_token) == '.':
                    table_name = columns[-1]
                    columns[-1] = '{}.{}'.format(table_name, str(token))
                else:
                    columns.append(str(token.value))
        last_token = token
    return unique(columns)

def get_query_tables(query):
    """:type query str
    :rtype: list[str]"""
    tables = []
    last_keyword = None
    last_token = None
    table_syntax_keywords = ['FROM', 'WHERE', 'JOIN', 'INNER JOIN', 'LEFT JOIN', 'RIGHT JOIN', 'ON', 'INTO', 'VALUES', 'UPDATE', 'SET', 'TABLE']
    for token in get_query_tokens(query):
        if token.is_keyword and token.value.upper() in table_syntax_keywords:
            last_keyword = token.value.upper()
        elif str(token) == '(':
            last_keyword = None
        elif token.is_keyword and str(token) in ['FORCE', 'ORDER']:
            last_keyword = None
        elif token.is_keyword and str(token) == 'SELECT' and (last_keyword in ['INTO', 'TABLE']):
            last_keyword = None
        elif token.ttype is Name or token.is_keyword:
            if last_keyword in ['FROM', 'JOIN', 'INNER JOIN', 'LEFT JOIN', 'RIGHT JOIN', 'INTO', 'UPDATE', 'TABLE'] and last_token not in ['AS'] and (token.value not in ['AS', 'SELECT']):
                if last_token == '.':
                    database_name = tables[-1]
                    tables[-1] = '{}.{}'.format(database_name, token)
                    last_keyword = None
                elif last_token not in [',', last_keyword]:
                    pass
                else:
                    table_name = str(token.value.strip('`'))
                    tables.append(table_name)
        last_token = token.value.upper()
    return unique(tables)

def get_query_limit_and_offset(query):
    """:type query str
    :rtype: (int, int)"""
    limit = None
    offset = None
    last_keyword = None
    last_token = None
    for token in get_query_tokens(query):
        if token.is_keyword and token.value.upper() in ['LIMIT', 'OFFSET']:
            last_keyword = token.value.upper()
        elif token.ttype is Number.Integer:
            if last_keyword == 'LIMIT':
                limit = int(token.value)
                last_keyword = None
            elif last_keyword == 'OFFSET':
                offset = int(token.value)
                last_keyword = None
            elif last_token and last_token.ttype is Punctuation:
                offset = limit
                limit = int(token.value)
        last_token = token
    if limit is None:
        return None
    return (limit, offset or 0)

def run_functor(functor, *args, **kwargs):
    """Given a functor, run it and return its result. We can use this with
    multiprocessing.map and map it over a list of job functors to do them.

    Handles getting more than multiprocessing's pitiful exception output

    This function was derived from:
    http://stackoverflow.com/a/16618842/19741

    This code was adopted from the American Gut project:
    https://github.com/biocore/American-Gut/blob/master/americangut/parallel.py"""
    try:
        return functor(*args, **kwargs)
    except Exception:
        raise Exception(''.join(traceback.format_exception(*sys.exc_info())))

def select2_modelform_meta(model, meta_fields=None, widgets=None, attrs=None, **kwargs):
    """Return `Meta` class with Select2-enabled widgets for fields
    with choices (e.g.  ForeignKey, CharField, etc) for use with
    ModelForm.

    Arguments:
        model - a model class to create `Meta` class for.
        meta_fields - dictionary with `Meta` class fields, for
            example, {'fields': ['id', 'name']}
        attrs - select2 widget attributes (width, for example),
            must be of type `dict`.
        **kwargs - will be merged with meta_fields."""
    widgets = widgets or {}
    meta_fields = meta_fields or {}
    for field in model._meta.fields:
        if isinstance(field, ForeignKey) or field.choices:
            widgets.update({field.name: Select2(select2attrs=attrs)})
    for field in model._meta.many_to_many:
        widgets.update({field.name: Select2Multiple(select2attrs=attrs)})
    meta_fields.update({'model': model, 'widgets': widgets})
    if 'exclude' not in kwargs and 'fields' not in kwargs:
        meta_fields.update({'exclude': []})
    meta_fields.update(**kwargs)
    meta = type('Meta', (object,), meta_fields)
    return meta

def findElementsWithId(node, elems=None):
    """Returns all elements with id attributes"""
    if elems is None:
        elems = {}
    id = node.getAttribute('id')
    if id != '':
        elems[id] = node
    if node.hasChildNodes():
        for child in node.childNodes:
            if child.nodeType == Node.ELEMENT_NODE:
                findElementsWithId(child, elems)
    return elems

def unprotected_ids(doc, options):
    u"""Returns a list of unprotected IDs within the document doc."""
    identifiedElements = findElementsWithId(doc.documentElement)
    if not (options.protect_ids_noninkscape or options.protect_ids_list or options.protect_ids_prefix):
        return identifiedElements
    if options.protect_ids_list:
        protect_ids_list = options.protect_ids_list.split(',')
    if options.protect_ids_prefix:
        protect_ids_prefixes = options.protect_ids_prefix.split(',')
    for id in list(identifiedElements):
        protected = False
        if options.protect_ids_noninkscape and (not id[-1].isdigit()):
            protected = True
        if options.protect_ids_list and id in protect_ids_list:
            protected = True
        if options.protect_ids_prefix:
            for prefix in protect_ids_prefixes:
                if id.startswith(prefix):
                    protected = True
        if protected:
            del identifiedElements[id]
    return identifiedElements

def removeNestedGroups(node):
    """This walks further and further down the tree, removing groups
    which do not have any attributes or a title/desc child and
    promoting their children up one level"""
    global _num_elements_removed
    num = 0
    groupsToRemove = []
    if not (node.nodeType == Node.ELEMENT_NODE and node.nodeName == 'switch'):
        for child in node.childNodes:
            if child.nodeName == 'g' and child.namespaceURI == NS['SVG'] and (len(child.attributes) == 0):
                for grandchild in child.childNodes:
                    if grandchild.nodeType == Node.ELEMENT_NODE and grandchild.namespaceURI == NS['SVG'] and (grandchild.nodeName in ['title', 'desc']):
                        break
                else:
                    groupsToRemove.append(child)
    for g in groupsToRemove:
        while g.childNodes.length > 0:
            g.parentNode.insertBefore(g.firstChild, g)
        g.parentNode.removeChild(g)
        _num_elements_removed += 1
        num += 1
    for child in node.childNodes:
        if child.nodeType == Node.ELEMENT_NODE:
            num += removeNestedGroups(child)
    return num

def _getStyle(node):
    u"""Returns the style attribute of a node as a dictionary."""
    if node.nodeType == Node.ELEMENT_NODE and len(node.getAttribute('style')) > 0:
        styleMap = {}
        rawStyles = node.getAttribute('style').split(';')
        for style in rawStyles:
            propval = style.split(':')
            if len(propval) == 2:
                styleMap[propval[0].strip()] = propval[1].strip()
        return styleMap
    else:
        return {}

def _setStyle(node, styleMap):
    u"""Sets the style attribute of a node to the dictionary ``styleMap``."""
    fixedStyle = ';'.join([prop + ':' + styleMap[prop] for prop in styleMap])
    if fixedStyle != '':
        node.setAttribute('style', fixedStyle)
    elif node.getAttribute('style'):
        node.removeAttribute('style')
    return node

def styleInheritedFromParent(node, style):
    """Returns the value of 'style' that is inherited from the parents of the passed-in node

    Warning: This method only considers presentation attributes and inline styles,
             any style sheets are ignored!"""
    parentNode = node.parentNode
    if parentNode.nodeType == Node.DOCUMENT_NODE:
        return None
    styles = _getStyle(parentNode)
    if style in styles:
        value = styles[style]
        if not value == 'inherit':
            return value
    value = parentNode.getAttribute(style)
    if value not in ['', 'inherit']:
        return parentNode.getAttribute(style)
    return styleInheritedFromParent(parentNode, style)

def styleInheritedByChild(node, style, nodeIsChild=False):
    """Returns whether 'style' is inherited by any children of the passed-in node

    If False is returned, it is guaranteed that 'style' can safely be removed
    from the passed-in node without influencing visual output of it's children

    If True is returned, the passed-in node should not have its text-based
    attributes removed.

    Warning: This method only considers presentation attributes and inline styles,
             any style sheets are ignored!"""
    if node.nodeType != Node.ELEMENT_NODE:
        return False
    if nodeIsChild:
        if node.getAttribute(style) not in ['', 'inherit']:
            return False
        styles = _getStyle(node)
        if style in styles and (not styles[style] == 'inherit'):
            return False
    elif not node.childNodes:
        return False
    if node.childNodes:
        for child in node.childNodes:
            if styleInheritedByChild(child, style, True):
                return True
    if node.nodeName in ['a', 'defs', 'glyph', 'g', 'marker', 'mask', 'missing-glyph', 'pattern', 'svg', 'switch', 'symbol']:
        return False
    return True

def mayContainTextNodes(node):
    """Returns True if the passed-in node is probably a text element, or at least
    one of its descendants is probably a text element.

    If False is returned, it is guaranteed that the passed-in node has no
    business having text-based attributes.

    If True is returned, the passed-in node should not have its text-based
    attributes removed."""
    try:
        return node.mayContainTextNodes
    except AttributeError:
        pass
    result = True
    if node.nodeType != Node.ELEMENT_NODE:
        result = False
    elif node.namespaceURI != NS['SVG']:
        result = True
    elif node.nodeName in ['rect', 'circle', 'ellipse', 'line', 'polygon', 'polyline', 'path', 'image', 'stop']:
        result = False
    elif node.nodeName in ['g', 'clipPath', 'marker', 'mask', 'pattern', 'linearGradient', 'radialGradient', 'symbol']:
        result = False
        for child in node.childNodes:
            if mayContainTextNodes(child):
                result = True
    node.mayContainTextNodes = result
    return result

def taint(taintedSet, taintedAttribute):
    u"""Adds an attribute to a set of attributes.

    Related attributes are also included."""
    taintedSet.add(taintedAttribute)
    if taintedAttribute == 'marker':
        taintedSet |= set(['marker-start', 'marker-mid', 'marker-end'])
    if taintedAttribute in ['marker-start', 'marker-mid', 'marker-end']:
        taintedSet.add('marker')
    return taintedSet

def removeDefaultAttributeValue(node, attribute):
    """Removes the DefaultAttribute 'attribute' from 'node' if specified conditions are fulfilled

    Warning: Does NOT check if the attribute is actually valid for the passed element type for increased preformance!"""
    if not node.hasAttribute(attribute.name):
        return 0
    if isinstance(attribute.value, str):
        if node.getAttribute(attribute.name) == attribute.value:
            if attribute.conditions is None or attribute.conditions(node):
                node.removeAttribute(attribute.name)
                return 1
    else:
        nodeValue = SVGLength(node.getAttribute(attribute.name))
        if attribute.value is None or (nodeValue.value == attribute.value and (not nodeValue.units == Unit.INVALID)):
            if attribute.units is None or nodeValue.units == attribute.units or (isinstance(attribute.units, list) and nodeValue.units in attribute.units):
                if attribute.conditions is None or attribute.conditions(node):
                    node.removeAttribute(attribute.name)
                    return 1
    return 0

def convertColor(value):
    """Converts the input color string and returns a #RRGGBB (or #RGB if possible) string"""
    s = value
    if s in colors:
        s = colors[s]
    rgbpMatch = rgbp.match(s)
    if rgbpMatch is not None:
        r = int(float(rgbpMatch.group(1)) * 255.0 / 100.0)
        g = int(float(rgbpMatch.group(2)) * 255.0 / 100.0)
        b = int(float(rgbpMatch.group(3)) * 255.0 / 100.0)
        s = '#%02x%02x%02x' % (r, g, b)
    else:
        rgbMatch = rgb.match(s)
        if rgbMatch is not None:
            r = int(rgbMatch.group(1))
            g = int(rgbMatch.group(2))
            b = int(rgbMatch.group(3))
            s = '#%02x%02x%02x' % (r, g, b)
    if s[0] == '#':
        s = s.lower()
        if len(s) == 7 and s[1] == s[2] and (s[3] == s[4]) and (s[5] == s[6]):
            s = '#' + s[1] + s[3] + s[5]
    return s

def convertColors(element):
    """Recursively converts all color properties into #RRGGBB format if shorter"""
    numBytes = 0
    if element.nodeType != Node.ELEMENT_NODE:
        return 0
    attrsToConvert = []
    if element.nodeName in ['rect', 'circle', 'ellipse', 'polygon', 'line', 'polyline', 'path', 'g', 'a']:
        attrsToConvert = ['fill', 'stroke']
    elif element.nodeName in ['stop']:
        attrsToConvert = ['stop-color']
    elif element.nodeName in ['solidColor']:
        attrsToConvert = ['solid-color']
    styles = _getStyle(element)
    for attr in attrsToConvert:
        oldColorValue = element.getAttribute(attr)
        if oldColorValue != '':
            newColorValue = convertColor(oldColorValue)
            oldBytes = len(oldColorValue)
            newBytes = len(newColorValue)
            if oldBytes > newBytes:
                element.setAttribute(attr, newColorValue)
                numBytes += oldBytes - len(element.getAttribute(attr))
        if attr in styles:
            oldColorValue = styles[attr]
            newColorValue = convertColor(oldColorValue)
            oldBytes = len(oldColorValue)
            newBytes = len(newColorValue)
            if oldBytes > newBytes:
                styles[attr] = newColorValue
                numBytes += oldBytes - len(element.getAttribute(attr))
    _setStyle(element, styles)
    for child in element.childNodes:
        numBytes += convertColors(child)
    return numBytes

def parseListOfPoints(s):
    """Parse string into a list of points.

    Returns a list containing an even number of coordinate strings"""
    i = 0
    ws_nums = re.split('\\s*[\\s,]\\s*', s.strip())
    nums = []
    for i in range(len(ws_nums)):
        negcoords = ws_nums[i].split('-')
        if len(negcoords) == 1:
            nums.append(negcoords[0])
        else:
            for j in range(len(negcoords)):
                if j == 0:
                    if negcoords[0] != '':
                        nums.append(negcoords[0])
                else:
                    prev = ''
                    if len(nums):
                        prev = nums[len(nums) - 1]
                    if prev and prev[len(prev) - 1] in ['e', 'E']:
                        nums[len(nums) - 1] = prev + '-' + negcoords[j]
                    else:
                        nums.append('-' + negcoords[j])
    if len(nums) % 2 != 0:
        return []
    i = 0
    while i < len(nums):
        try:
            nums[i] = getcontext().create_decimal(nums[i])
            nums[i + 1] = getcontext().create_decimal(nums[i + 1])
        except InvalidOperation:
            return []
        i += 2
    return nums

def controlPoints(cmd, data):
    """Checks if there are control points in the path data

    Returns the indices of all values in the path data which are control points"""
    cmd = cmd.lower()
    if cmd in ['c', 's', 'q']:
        indices = range(len(data))
        if cmd == 'c':
            return [index for index in indices if index % 6 < 4]
        elif cmd in ['s', 'q']:
            return [index for index in indices if index % 4 < 2]
    return []

def serializePath(pathObj, options):
    """Reserializes the path data with some cleanups."""
    return ''.join([cmd + scourCoordinates(data, options, control_points=controlPoints(cmd, data), flags=flags(cmd, data)) for cmd, data in pathObj])

def serializeTransform(transformObj):
    """Reserializes the transform data with some cleanups."""
    return ' '.join([command + '(' + ' '.join([scourUnitlessLength(number) for number in numbers]) + ')' for command, numbers in transformObj])

def scourCoordinates(data, options, force_whitespace=False, control_points=[], flags=[]):
    """Serializes coordinate data with some cleanups:
       - removes all trailing zeros after the decimal
       - integerize coordinates if possible
       - removes extraneous whitespace
       - adds spaces between values in a subcommand if required (or if force_whitespace is True)"""
    if data is not None:
        newData = []
        c = 0
        previousCoord = ''
        for coord in data:
            is_control_point = c in control_points
            scouredCoord = scourUnitlessLength(coord, renderer_workaround=options.renderer_workaround, is_control_point=is_control_point)
            if c > 0 and (force_whitespace or scouredCoord[0].isdigit() or (scouredCoord[0] == '.' and (not ('.' in previousCoord or 'e' in previousCoord)))) and (c - 1 not in flags or options.renderer_workaround):
                newData.append(' ')
            newData.append(scouredCoord)
            previousCoord = scouredCoord
            c += 1
        if options.renderer_workaround:
            if len(newData) > 0:
                for i in range(1, len(newData)):
                    if newData[i][0] == '-' and 'e' in newData[i - 1]:
                        newData[i - 1] += ' '
                return ''.join(newData)
        else:
            return ''.join(newData)
    return ''

def scourLength(length):
    """Scours a length. Accepts units."""
    length = SVGLength(length)
    return scourUnitlessLength(length.value) + Unit.str(length.units)

def scourUnitlessLength(length, renderer_workaround=False, is_control_point=False):
    """Scours the numeric part of a length only. Does not accept units.

    This is faster than scourLength on elements guaranteed not to
    contain units."""
    if not isinstance(length, Decimal):
        length = getcontext().create_decimal(str(length))
    initial_length = length
    if is_control_point:
        length = scouringContextC.plus(length)
    else:
        length = scouringContext.plus(length)
    intLength = length.to_integral_value()
    if length == intLength:
        length = Decimal(intLength)
    else:
        length = length.normalize()
    nonsci = '{0:f}'.format(length)
    nonsci = '{0:f}'.format(initial_length.quantize(Decimal(nonsci)))
    if not renderer_workaround:
        if len(nonsci) > 2 and nonsci[:2] == '0.':
            nonsci = nonsci[1:]
        elif len(nonsci) > 3 and nonsci[:3] == '-0.':
            nonsci = '-' + nonsci[2:]
    return_value = nonsci
    if len(nonsci) > 3:
        exponent = length.adjusted()
        length = length.scaleb(-exponent).normalize()
        sci = six.text_type(length) + 'e' + six.text_type(exponent)
        if len(sci) < len(nonsci):
            return_value = sci
    return return_value

def optimizeAngle(angle):
    """Because any rotation can be expressed within 360 degrees
    of any given number, and since negative angles sometimes
    are one character longer than corresponding positive angle,
    we shorten the number to one in the range to [-90, 270[."""
    if angle < 0:
        angle %= -360
    else:
        angle %= 360
    if angle >= 270:
        angle -= 360
    elif angle < -90:
        angle += 360
    return angle

def optimizeTransforms(element, options):
    """Attempts to optimise transform specifications on the given node and its children.

    Returns the number of bytes saved after performing these reductions."""
    num = 0
    for transformAttr in ['transform', 'patternTransform', 'gradientTransform']:
        val = element.getAttribute(transformAttr)
        if val != '':
            transform = svg_transform_parser.parse(val)
            optimizeTransform(transform)
            newVal = serializeTransform(transform)
            if len(newVal) < len(val):
                if len(newVal):
                    element.setAttribute(transformAttr, newVal)
                else:
                    element.removeAttribute(transformAttr)
                num += len(val) - len(newVal)
    for child in element.childNodes:
        if child.nodeType == Node.ELEMENT_NODE:
            num += optimizeTransforms(child, options)
    return num

def removeComments(element):
    """Removes comments from the element and its children."""
    global _num_bytes_saved_in_comments
    num = 0
    if isinstance(element, xml.dom.minidom.Comment):
        _num_bytes_saved_in_comments += len(element.data)
        element.parentNode.removeChild(element)
        num += 1
    else:
        for subelement in element.childNodes[:]:
            num += removeComments(subelement)
    return num

def get_format(format_):
    """Find format schema in $FORMAT_PATH or nerium/schema
    """
    format_path = os.getenv('FORMAT_PATH', 'format_files')
    try:
        spec = importlib.util.spec_from_file_location('format_mod', f'{format_path}/{format_}.py')
        format_mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(format_mod)
    except FileNotFoundError:
        try:
            format_mod = import_module(f'nerium.schema.{format_}')
        except ModuleNotFoundError:
            format_mod = import_module('nerium.schema.default')
    schema = format_mod.ResultSchema()
    return schema

def housecode_to_index(housecode):
    """Convert a X10 housecode to a zero-based index"""
    match = re.search('^([A-P])(\\d{1,2})$', housecode.upper())
    if match:
        house_index = int(match.group(2))
        if 1 <= house_index <= 16:
            return (ord(match.group(1)) - ord('A')) * 16 + house_index - 1
    raise ValueError('Invalid X10 housecode: %s' % housecode)

def index_to_housecode(index):
    """Convert a zero-based index to a X10 housecode."""
    if index < 0 or index > 255:
        raise ValueError
    quotient, remainder = divmod(index, 16)
    return chr(quotient + ord('A')) + '{:02d}'.format(remainder + 1)

def _check_checksum(msg):
    """Ensure checksum in message is good."""
    checksum = int(msg[-2:], 16)
    for char in msg[:-2]:
        checksum += ord(char)
    if checksum % 256 != 0:
        raise ValueError('Elk message checksum invalid')

def _check_message_valid(msg):
    """Check packet length valid and that checksum is good."""
    try:
        if int(msg[:2], 16) != len(msg) - 2:
            raise ValueError('Elk message length incorrect')
        _check_checksum(msg)
    except IndexError:
        raise ValueError('Elk message length incorrect')

def cw_encode(index, value, value_format):
    """cw: Write a custom value."""
    if value_format == 2:
        value = value[0] << 8 + value[1]
    return MessageEncode('0Dcw{:02d}{:05d}00'.format(index + 1, value), None)

def dm_encode(keypad_area, clear, beep, timeout, line1, line2):
    """dm: Display message on keypad."""
    return MessageEncode('2Edm{:1d}{:1d}{:1d}{:05d}{:^<16.16}{:^<16.16}00'.format(keypad_area + 1, clear, beep, timeout, line1, line2), None)

def pc_encode(index, function_code, extended_code, time):
    """pc: Control any PLC device."""
    return MessageEncode('11pc{hc}{fc:02d}{ec:02d}{time:04d}00'.format(hc=index_to_housecode(index), fc=function_code, ec=extended_code, time=time), None)

def zb_encode(zone, area, user_code):
    """zb: Zone bypass. Zone < 0 unbypass all; Zone > Max bypass all."""
    if zone < 0:
        zone = 0
    elif zone > Max.ZONES.value:
        zone = 999
    else:
        zone += 1
    return MessageEncode('10zb{zone:03d}{area:1d}{code:06d}00'.format(zone=zone, area=area + 1, code=user_code), 'ZB')

def get_result_set(query_name, **kwargs):
    """Call get_query, then submit query from file to resultset module
    """
    query = get_query(query_name)
    if not query:
        query = SimpleNamespace()
        query.error = f"No query found matching '{query_name}'"
        return query
    try:
        result_mod = import_module(f'nerium.contrib.resultset.{query.result_mod}')
    except ModuleNotFoundError:
        result_mod = import_module('nerium.resultset.sql')
    query.params = {**kwargs}
    query.body = process_template(sql=query.body, **query.params)
    result = result_mod.result(query, **query.params)
    query.result = json.loads(json.dumps(result, default=serialize_objects_handler))
    try:
        if 'error' in query.result[0].keys():
            query.error = query.result[0]['error']
    except IndexError:
        pass
    return query

def get_data_source(query):
    """Get data source connection metadata based on config. Prefer, in order:
        - Query file frontmatter
        - `db.yaml` file in query subdirectory
        - DATABASE_URL in environment

    To allow for possible non-SQL sources to be contributed, we only
    return a config value here, and leave connecting to concrete
    resultset module, as required values and connection method might change.
    (This is also why we return a dict, despite having a single value in the
    SQL case.)"""
    try:
        return query.metadata['data_source']
    except KeyError:
        try:
            return dict(url=query.metadata['database_url'])
        except KeyError:
            pass
    db_file = query.path.parent / 'db.yaml'
    if db_file.is_file():
        with open(db_file, 'r') as dbf:
            db_meta = yaml.safe_load(dbf.read())
            try:
                return db_meta['data_source']
            except KeyError:
                try:
                    return dict(url=db_meta['database_url'])
                except KeyError:
                    pass
    return dict(url=os.getenv('DATABASE_URL', 'sqlite:///'))

def unwrap_querystring_lists(obj):
    """Convert responder querystring params, pulling values out of list
    if there's only one."""
    new_dict = {key: obj[key][0] if len(obj[key]) == 1 else obj[key] for key in obj.keys()}
    return new_dict

def parse_url(url):
    """Parse a Elk connection string"""
    scheme, dest = url.split('://')
    host = None
    ssl_context = None
    if scheme == 'elk':
        host, port = dest.split(':') if ':' in dest else (dest, 2101)
    elif scheme == 'elks':
        host, port = dest.split(':') if ':' in dest else (dest, 2601)
        ssl_context = ssl.SSLContext(ssl.PROTOCOL_TLSv1)
        ssl_context.verify_mode = ssl.CERT_NONE
    elif scheme == 'serial':
        host, port = dest.split(':') if ':' in dest else (dest, 115200)
    else:
        raise ValueError("Invalid scheme '%s'" % scheme)
    return (scheme, host, int(port), ssl_context)

def username(elk, user_number):
    """Return name of user."""
    if user_number >= 0 and user_number < elk.users.max_elements:
        return elk.users[user_number].name
    if user_number == 201:
        return '*Program*'
    if user_number == 202:
        return '*Elk RP*'
    if user_number == 203:
        return '*Quick arm*'
    return ''

def groups_of(n, iterable):
    """>>> groups_of(2, range(5))"""
    args = [iter(iterable)] * n
    for x in izip_longest(*args):
        yield [v for v in x if v is not None]

def dir_modtime(dpath):
    """Returns the latest modification time of all files/subdirectories in a
    directory"""
    return max((os.path.getmtime(d) for d, _, _ in os.walk(dpath)))

def parse_single_value(value):
    """Tries to convert to int, float and then gives up and assumes the value
    is of type string. Useful when excepting values that may be string
    representations of numerical values"""
    if isinstance(value, basestring):
        try:
            if value.startswith('"') and value.endswith('"'):
                value = str(value[1:-1])
            elif '.' in value:
                value = float(value)
            else:
                value = int(value)
        except ValueError:
            value = str(value)
    elif not isinstance(value, (int, float)):
        raise ArcanaUsageError('Unrecognised type for single value {}'.format(value))
    return value

def iscontainer(*items):
    """Checks whether all the provided items are containers (i.e of class list,
    dict, tuple, etc...)"""
    return all((isinstance(i, Iterable) and (not isinstance(i, basestring)) for i in items))

def process_iter(proc, cmd=''):
    """helper function to iterate over a process stdout
    and report error messages when done"""
    try:
        for l in proc.stdout:
            yield l
    finally:
        if proc.poll() is None:
            return
        else:
            proc.wait()
            if proc.returncode not in (0, None, signal.SIGPIPE, signal.SIGPIPE + 128):
                sys.stderr.write('cmd was:%s\n' % cmd)
                sys.stderr.write('return code was:%s\n' % proc.returncode)
                raise ProcessException(cmd)

def is_newer_b(a, bfiles):
    """check that all b files have been modified more recently than a"""
    if isinstance(bfiles, basestring):
        bfiles = [bfiles]
    if not op.exists(a):
        return False
    if not all((op.exists(b) for b in bfiles)):
        return False
    atime = os.stat(a).st_mtime
    for b in bfiles:
        if atime > os.stat(b).st_mtime:
            return False
    return True

def pool(n=None, dummy=False):
    """create a multiprocessing pool that responds to interrupts."""
    if dummy:
        from multiprocessing.dummy import Pool
    else:
        from multiprocessing import Pool
    if n is None:
        import multiprocessing
        n = multiprocessing.cpu_count() - 1
    return Pool(n)

def pmap(f, iterable, n=None, dummy=False, p=None):
    """parallel map of a function to an iterable
    if each item in iterable is itself an iterable, then
    automatically call f(*item) instead of f(item)

    Arguments:
      f: function
      iterable: any iterable where each item is sent to f
      n: number of cpus (default is number on machine)
      dummy: use dummy pool.
      p: existing pool to re-use"""
    if n == 1:
        for r in it.starmap(f, iterable):
            yield r
        raise StopIteration
    if p is None:
        po = pool(n, dummy)
    else:
        po = p
    assert hasattr(po, 'imap')
    f = _func_star(f)
    try:
        for r in po.imap(f, iterable):
            yield r
    finally:
        if p is None:
            try:
                po.close()
                po.join()
            except:
                pass

def make_user_role_table(table_name='user', id_column_name='id'):
    """Create the user-role association table so that
    it correctly references your own UserMixin subclass."""
    return db.Table('fp_user_role', db.Column('user_id', db.Integer, db.ForeignKey('{}.{}'.format(table_name, id_column_name))), db.Column('role_id', db.Integer, db.ForeignKey('fp_role.id')), extend_existing=True)

def user_has(ability, get_user=import_user):
    """Takes an ability (a string name of either a role or an ability) and returns the function if the user has that ability"""
    def wrapper(func):
        @wraps(func)
        def inner(*args, **kwargs):
            from .models import Ability
            desired_ability = Ability.query.filter_by(name=ability).first()
            user_abilities = []
            current_user = get_user()
            for role in current_user._roles:
                user_abilities += role.abilities
            if desired_ability in user_abilities:
                return func(*args, **kwargs)
            else:
                raise Forbidden('You do not have access')
        return inner
    return wrapper

def user_is(role, get_user=import_user):
    """Takes an role (a string name of either a role or an ability) and returns the function if the user has that role"""
    def wrapper(func):
        @wraps(func)
        def inner(*args, **kwargs):
            from .models import Role
            current_user = get_user()
            if role in current_user.roles:
                return func(*args, **kwargs)
            raise Forbidden('You do not have access')
        return inner
    return wrapper

def _form_key_str(path):
    """Given a URL path, massage it into a key we can perform a lookup on the
    MEDIASYNC['JOINED'] dict with.

    This mostly involves figuring into account the CSS_PATH and JS_PATH
    settings, if they have been set."""
    if path.endswith('.css'):
        media_path_prefix = msettings['CSS_PATH']
    elif path.endswith('.js'):
        media_path_prefix = msettings['JS_PATH']
    else:
        return None
    if media_path_prefix:
        if not media_path_prefix.endswith('/'):
            media_path_prefix += '/'
        if path.startswith(media_path_prefix):
            return path[len(media_path_prefix):]
        else:
            return path
    return path

def _find_combo_match(path):
    """Calculate the key to check the MEDIASYNC['JOINED'] dict for, perform the
    lookup, and return the matching key string if a match is found. If no
    match is found, return None instead."""
    key_str = _form_key_str(path)
    if not key_str:
        return None
    if not msettings['JOINED'].has_key(key_str):
        return None
    else:
        return key_str

def static_serve(request, path, client):
    """Given a request for a media asset, this view does the necessary wrangling
    to get the correct thing delivered to the user. This can also emulate the
    combo behavior seen when SERVE_REMOTE == False and EMULATE_COMBO == True."""
    if msettings['SERVE_REMOTE']:
        url = client.remote_media_url().strip('/') + '/%(path)s'
        return redirect(url, permanent=True)
    if not msettings['SERVE_REMOTE'] and msettings['EMULATE_COMBO']:
        combo_match = _find_combo_match(path)
        if combo_match:
            return combo_serve(request, combo_match, client)
    resp = serve(request, path, document_root=client.media_root, show_indexes=True)
    try:
        resp.content = client.process(resp.content, resp['Content-Type'], path)
    except KeyError:
        pass
    return resp

def short_description(description):
    """Sets 'short_description' attribute (this attribute is in exports to generate header name)."""
    def decorator(func):
        if isinstance(func, property):
            func = func.fget
        func.short_description = description
        return func
    return decorator

def count_processors():
    """How many cores does the current computer have ?"""
    if 'SLURM_NTASKS' in os.environ:
        return int(os.environ['SLURM_NTASKS'])
    elif 'SLURM_JOB_CPUS_PER_NODE' in os.environ:
        text = os.environ['SLURM_JOB_CPUS_PER_NODE']
        if is_integer(text):
            return int(text)
        else:
            n, N = re.findall('([1-9]+)\\(x([1-9]+)\\)', text)[0]
            return int(n) * int(N)
    else:
        return multiprocessing.cpu_count()

def guess_server_name():
    """We often use the same servers, which one are we running on now ?"""
    if os.environ.get('CSCSERVICE') == 'sisu':
        return 'sisu'
    elif os.environ.get('SLURM_JOB_PARTITION') == 'halvan':
        return 'halvan'
    elif os.environ.get('SNIC_RESOURCE') == 'milou':
        return 'milou'
    elif os.environ.get('LAPTOP') == 'macbook_air':
        return 'macbook_air'
    else:
        return 'unknown'

def _save_translations(sender, instance, *args, **kwargs):
    """This signal saves model translations."""
    if site_is_monolingual():
        return False
    cls = sender
    if not hasattr(cls._meta, 'translatable_fields'):
        return False
    for field in cls._meta.translatable_fields:
        value = getattr(instance, field)
        if not value is None:
            md5_value = checksum(value)
            setattr(instance, u'md5' + field, md5_value)
            for lang in settings.LANGUAGES:
                lang = lang[0]
                if lang != settings.LANGUAGE_CODE:
                    context = u'Updating from object'
                    if hasattr(instance, 'trans_context'):
                        context = getattr(instance, 'trans_context')
                    trans = FieldTranslation.update(instance, field, lang, context)

def _get_fieldtranslations(instance, field=None, lang=None):
    """Get all the translations for this object."""
    _filter = {'module': instance.__module__, 'model': instance.__class__.__name__, 'object_id': instance.id}
    if lang:
        _filter['lang'] = lang
    if field:
        _filter['field'] = field
        try:
            return FieldTranslation.objects.get(**_filter)
        except FieldTranslation.DoesNotExist:
            return False
    return FieldTranslation.objects.filter(**_filter)

def _set_dict_translations(instance, dict_translations):
    """Establece los atributos de traducciones a partir de una dict que
    contiene todas las traducciones."""
    if not hasattr(instance._meta, 'translatable_fields'):
        return False
    if site_is_monolingual():
        return False
    translatable_fields = instance._meta.translatable_fields
    for field in translatable_fields:
        for lang in settings.LANGUAGES:
            lang = lang[0]
            if lang != settings.LANGUAGE_CODE:
                trans_field = trans_attr(field, lang)
                if dict_translations.has_key(trans_field):
                    setattr(instance, trans_field, dict_translations[trans_field])
                trans_isfuzzy = trans_is_fuzzy_attr(field, lang)
                if dict_translations.has_key(trans_isfuzzy):
                    is_fuzzy_value = dict_translations[trans_isfuzzy] == '1' or dict_translations[trans_isfuzzy] == 1
                    setattr(instance, trans_isfuzzy, is_fuzzy_value)

def _setup_schema(Base, session):
    """Create a function which adds `__marshmallow__` attribute to all signal models."""
    def create_schema_class(m):
        if hasattr(m, 'send_signalbus_message'):
            class Meta(object):
                model = m
        else:
            class Meta(object):
                model = m
                sqla_session = session
        schema_class_name = '%sSchema' % m.__name__
        return type(schema_class_name, (ModelSchema,), {'Meta': Meta})
    def setup_schema_fn():
        for model in Base._decl_class_registry.values():
            if hasattr(model, '__tablename__'):
                if model.__name__.endswith('Schema'):
                    raise ModelConversionError('Unexpected model name: "{}". For safety, _setup_schema() can not be used when a model class ends with "Schema".'.format(model.__name__))
                schema_class = getattr(model, '__marshmallow__', None)
                if schema_class is None:
                    schema_class = model.__marshmallow__ = create_schema_class(model)
                if hasattr(model, 'send_signalbus_message'):
                    setattr(model, '__marshmallow_schema__', schema_class())
    return setup_schema_fn

def retry_on_deadlock(session, retries=6, min_wait=0.1, max_wait=10.0):
    """Return function decorator that executes the function again in case of a deadlock."""
    def decorator(action):
        """Function decorator that retries `action` in case of a deadlock."""
        @wraps(action)
        def f(*args, **kwargs):
            num_failures = 0
            while True:
                try:
                    return action(*args, **kwargs)
                except (DBAPIError, DBSerializationError) as e:
                    num_failures += 1
                    is_serialization_error = isinstance(e, DBSerializationError) or get_db_error_code(e.orig) in DEADLOCK_ERROR_CODES
                    if num_failures > retries or not is_serialization_error:
                        raise
                session.rollback()
                wait_seconds = min(max_wait, min_wait * 2 ** (num_failures - 1))
                time.sleep(wait_seconds)
        return f
    return decorator

def cached(f):
    """Decorator for functions evaluated only once."""
    def memoized(*args, **kwargs):
        if hasattr(memoized, '__cache__'):
            return memoized.__cache__
        result = f(*args, **kwargs)
        memoized.__cache__ = result
        return result
    return memoized

def smartformset_factory(form, formset=BaseFormSet, extra=1, can_order=False, can_delete=False, min_num=None, max_num=None, validate_min=False, validate_max=False):
    """Return a FormSet for the given form class."""
    if max_num is None:
        max_num = DEFAULT_MAX_NUM
    absolute_max = max_num + DEFAULT_MAX_NUM
    if min_num is None:
        min_num = 0
    attrs = {'form': form, 'extra': extra, 'can_order': can_order, 'can_delete': can_delete, 'min_num': min_num, 'max_num': max_num, 'absolute_max': absolute_max, 'validate_min': validate_min, 'validate_max': validate_max}
    return type(form.__name__ + str('FormSet'), (formset,), attrs)

def edit(request, translation):
    """Edit a translation.
    @param request: Django HttpRequest object.
    @param translation: Translation id
    @return Django HttpResponse object with the view or a redirection."""
    translation = get_object_or_404(FieldTranslation, id=translation)
    if request.method == 'POST':
        if 'cancel' in request.POST:
            return HttpResponseRedirect(reverse('modeltranslation:view_all_url', args=(translation.lang, 'all')))
        elif 'save' in request.POST:
            form = FieldTranslationForm(request.POST, instance=translation)
            valid_form = form.is_valid()
            if valid_form:
                translation = form.save(commit=False)
                translation.context = u'Admin. Traducciones'
                translation.save()
                return HttpResponseRedirect(reverse('modeltranslation:view_all_url', args=(translation.lang, 'all')))
        else:
            form = FieldTranslationForm(instance=translation)
    else:
        form = FieldTranslationForm(instance=translation)
    LANGUAGES = dict((lang for lang in settings.LANGUAGES))
    language = LANGUAGES[translation.lang]
    return render_to_response('modeltranslation/admin/edit_translation.html', {'translation': translation, 'form': form, 'lang': translation.lang, 'language': language}, RequestContext(request))

def export_translations(request, language):
    """Export translations view."""
    FieldTranslation.delete_orphan_translations()
    translations = FieldTranslation.objects.filter(lang=language)
    for trans in translations:
        trans.source_text = trans.source_text.replace("'", "'").replace('"', '\\"')
        trans.translation = trans.translation.replace("'", "'").replace('"', '\\"')
    replacements = {'translations': translations, 'lang': language}
    if len(settings.ADMINS) > 0:
        replacements['last_translator'] = settings.ADMINS[0][0]
        replacements['last_translator_email'] = settings.ADMINS[0][1]
    if settings.WEBSITE_NAME:
        replacements['website_name'] = settings.WEBSITE_NAME
    response = render(request=request, template_name='modeltranslation/admin/export_translations.po', dictionary=replacements, context_instance=RequestContext(request), content_type='text/x-gettext-translation')
    response['Content-Disposition'] = 'attachment; filename="{0}.po"'.format(language)
    return response

def update_translations(request):
