def find_child(sexpr: Sexpr, *tags: str) -> Optional[Sexpr]:
    """Search for a tag among direct children of the s-expression."""
    _assert_valid_sexpr(sexpr)
    for child in sexpr[1:]:
        if _is_sexpr(child) and child[0] in tags:
            return child
    return None

