def humanized_model_to_dict(instance, readonly_fields, fields=None, exclude=None):
    """Returns a dict containing the humanized data in ``instance`` suitable for passing as
    a Form's ``initial`` keyword argument.

    ``fields`` is an optional list of field names. If provided, only the named
    fields will be included in the returned dict.

    ``exclude`` is an optional list of field names. If provided, the named
    fields will be excluded from the returned dict, even if they are listed in
    the ``fields`` argument."""
    opts = instance._meta
    data = {}
    for f in itertools.chain(opts.concrete_fields, opts.private_fields, opts.many_to_many):
        if not getattr(f, 'editable', False):
            continue
        if fields and f.name not in fields:
            continue
        if f.name not in readonly_fields:
            continue
        if exclude and f.name in exclude:
            continue
        if f.humanized:
            data[f.name] = f.humanized(getattr(instance, f.name), instance)
    return data

def find_info(name=None):
    """Find the needed city server information."""
    if not name:
        return list(servers.keys())
    name = name.lower()
    if name in servers:
        info = servers[name]
    else:
        raise CityNotFound('Could not find the specified city: %s' % name)
    return info

def which(exe=None, default_paths=['/bin', '/sbin', '/usr/bin', '/usr/sbin', '/usr/local/bin']):
    """Return path of bin. Python clone of /usr/bin/which.

    from salt.util - https://www.github.com/saltstack/salt - license apache

    :param exe: Application to search PATHs for.
    :type exe: str
    :param default_path: Application to search PATHs for.
    :type default_path: list
    :rtype: str"""
    def _is_executable_file_or_link(exe):
        return os.access(exe, os.X_OK) and (os.path.isfile(exe) or os.path.islink(exe))
    if _is_executable_file_or_link(exe):
        return exe
    search_path = os.environ.get('PATH') and os.environ['PATH'].split(os.pathsep) or list()
    for default_path in default_paths:
        if default_path not in search_path:
            search_path.append(default_path)
    os.environ['PATH'] = os.pathsep.join(search_path)
    for path in search_path:
        full_path = os.path.join(path, exe)
        if _is_executable_file_or_link(full_path):
            return full_path
    logger.info("'{0}' could not be found in the following search path: '{1}'".format(exe, search_path))
    return None

def strip_project_url(url):
    """strip proto:// | openstack/ prefixes and .git | -distgit suffixes"""
    m = re.match('(?:[^:]+://)?(.*)', url)
    if m:
        url = m.group(1)
    if url.endswith('.git'):
        url, _, _ = url.rpartition('.')
    if url.endswith('-distgit'):
        url, _, _ = url.rpartition('-')
    if url.startswith('openstack/'):
        _, _, url = url.partition('/')
    return url

def get_rev_options(url, rev):
    """Return revision options.

    from pip pip.vcs.subversion."""
    if rev:
        rev_options = ['-r', rev]
    else:
        rev_options = []
    r = urlparse.urlsplit(url)
    if hasattr(r, 'username'):
        username, password = (r.username, r.password)
    else:
        netloc = r[1]
        if '@' in netloc:
            auth = netloc.split('@')[0]
            if ':' in auth:
                username, password = auth.split(':', 1)
            else:
                username, password = (auth, None)
        else:
            username, password = (None, None)
    if username:
        rev_options += ['--username', username]
    if password:
        rev_options += ['--password', password]
    return rev_options

def info2dicts(info, in_place=False):
    """Return info with:

    1) `packages` list replaced by a 'packages' dict indexed by 'project'
    2) `releases` list replaced by a 'releases' dict indexed by 'name'"""
    if 'packages' not in info and 'releases' not in info:
        return info
    if in_place:
        info_dicts = info
    else:
        info_dicts = info.copy()
    packages = info.get('packages')
    if packages:
        info_dicts['packages'] = list2dict(packages, 'project')
    releases = info.get('releases')
    if releases:
        info_dicts['releases'] = list2dict(releases, 'name')
    return info_dicts

def info2lists(info, in_place=False):
    """Return info with:

    1) `packages` dict replaced by a 'packages' list with indexes removed
    2) `releases` dict replaced by a 'releases' list with indexes removed

    info2list(info2dicts(info)) == info"""
    if 'packages' not in info and 'releases' not in info:
        return info
    if in_place:
        info_lists = info
    else:
        info_lists = info.copy()
    packages = info.get('packages')
    if packages:
        info_lists['packages'] = list(packages.values())
    releases = info.get('releases')
    if releases:
        info_lists['releases'] = list(releases.values())
    return info_lists

def alphanumeric(text):
    """Make an ultra-safe, ASCII version a string.
    For instance for use as a filename.
    \\w matches any alphanumeric character and the underscore."""
    return ''.join([c for c in text if re.match('\\w', c)])

def sanitize_text(text):
    """Make a safe representation of a string.
     Note: the `\\s` special character matches any whitespace character.
     This is equivalent to the set [
    ] as well as ` ` (whitespace)."""
    text = re.sub('(\\s)', lambda m: repr(m.group(0)).strip("'"), text)
    try:
        text = text.decode('utf-8')
    except AttributeError:
        pass
    text = unicodedata.normalize('NFC', text)
    return text

def access_dict_like_obj(obj, prop, new_value=None):
    """Access a dictionary like if it was an object with properties.
    If no "new_value", then it's a getter, otherwise it's a setter.
    >>> {'characters': {'cast': 'Jean-Luc Picard', 'featuring': 'Deanna Troi'}}
    >>> access_dict_like_obj(startrek, 'characters.cast', 'Pierce Brosnan')"""
    props = prop.split('.')
    if new_value:
        if props[0] not in obj:
            obj[props[0]] = {}
        if len(props) == 1:
            obj[prop] = new_value
        else:
            return access_dict_like_obj(obj[props[0]], '.'.join(props[1:]), new_value)
    elif len(props) == 1:
        return obj[prop]
    else:
        return access_dict_like_obj(obj[props[0]], '.'.join(props[1:]))

def all_combinations(items):
    """Generate all combinations of a given list of items."""
    return (set(compress(items, mask)) for mask in product(*[[0, 1]] * len(items)))

def pad_equal_whitespace(string, pad=None):
    """Given a multiline string, add whitespaces to every line
    so that every line has the same length."""
    if pad is None:
        pad = max(map(len, string.split('\n'))) + 1
    return '\n'.join((('{0: <%i}' % pad).format(line) for line in string.split('\n')))

def count_string_diff(a, b):
    """Return the number of characters in two strings that don't exactly match"""
    shortest = min(len(a), len(b))
    return sum((a[i] != b[i] for i in range(shortest)))

def iflatten(L):
    """Iterative flatten."""
    for sublist in L:
        if hasattr(sublist, '__iter__'):
            for item in iflatten(sublist):
                yield item
        else:
            yield sublist

def uniquify_list(L):
    """Same order unique list using only a list compression."""
    return [e for i, e in enumerate(L) if L.index(e) == i]

def get_next_item(iterable):
    """Gets the next item of an iterable.
    If the iterable is exhausted, returns None."""
    try:
        x = iterable.next()
    except StopIteration:
        x = None
    except AttributeError:
        x = None
    return x

def pretty_now():
    """Returns some thing like '2019-02-15 15:58:22 CET+0100'"""
    import datetime, tzlocal
    time_zone = tzlocal.get_localzone()
    now = datetime.datetime.now(time_zone)
    return now.strftime('%Y-%m-%d %H:%M:%S %Z%z')

def num_to_ith(num):
    """1 becomes 1st, 2 becomes 2nd, etc."""
    value = str(num)
    before_last_digit = value[-2]
    last_digit = value[-1]
    if len(value) > 1 and before_last_digit == '1':
        return value + 'th'
    if last_digit == '1':
        return value + 'st'
    if last_digit == '2':
        return value + 'nd'
    if last_digit == '3':
        return value + 'rd'
    return value + 'th'

def isubsample(full_sample, k, full_sample_len=None):
    """Down-sample an enumerable list of things"""
    if not full_sample_len:
        full_sample_len = len(full_sample)
    if not 0 <= k <= full_sample_len:
        raise ValueError('Required that 0 <= k <= full_sample_length')
    picked = 0
    for i, element in enumerate(full_sample):
        prob = (k - picked) / (full_sample_len - i)
        if random.random() < prob:
            yield element
            picked += 1
    assert picked == k

def split_thousands(s):
    '''Splits a number on thousands.

    >>> split_thousands(1000012)
    "1'000'012"'''
    if s is None:
        return '0'
    if isinstance(s, basestring):
        s = float(s)
    if isinstance(s, float) and s.is_integer():
        s = int(s)
    result = '{:,}'.format(s)
    result = result.replace(',', "'")
    return result

def load_json_path(path):
    """Load a file with the json module, but report errors better if it
    fails. And have it ordered too !"""
    with open(path) as handle:
        try:
            return json.load(handle, object_pairs_hook=collections.OrderedDict)
        except ValueError as error:
            message = "Could not decode JSON file '%s'." % path
            message = '-' * 20 + '\n' + message + '\n' + str(error) + '\n' + '-' * 20 + '\n'
            sys.stderr.write(message)
            raise error

def md5sum(file_path, blocksize=65536):
    """Compute the md5 of a file. Pretty fast."""
    md5 = hashlib.md5()
    with open(file_path, 'rb') as f:
        for block in iter(lambda: f.read(blocksize), ''):
            md5.update(block)
    return md5.hexdigest()

def reversed_lines(path):
    """Generate the lines of file in reverse order."""
    with open(path, 'r') as handle:
        part = ''
        for block in reversed_blocks(handle):
            for c in reversed(block):
                if c == '\n' and part:
                    yield part[::-1]
                    part = ''
                part += c
        if part:
            yield part[::-1]

def which(cmd, safe=False):
    """https://github.com/jc0n/python-which"""
    from autopaths.file_path import FilePath
    def is_executable(path):
        return os.path.exists(path) and os.access(path, os.X_OK) and (not os.path.isdir(path))
    path, name = os.path.split(cmd)
    if path:
        if is_executable(cmd):
            return FilePath(cmd)
    else:
        for path in os.environ['PATH'].split(os.pathsep):
            candidate = os.path.join(path, cmd)
            if is_executable(candidate):
                return FilePath(candidate)
    if not safe:
        raise Exception('which failed to locate a proper command path "%s"' % cmd)

def css_tag(parser, token):
    """Renders a tag to include the stylesheet. It takes an optional second
    parameter for the media attribute; the default media is "screen, projector".

    Usage::

        {% css "<somefile>.css" ["<projection type(s)>"] %}

    Examples::

        {% css "myfile.css" %}
        {% css "myfile.css" "screen, projection"%}"""
    path = get_path_from_tokens(token)
    tokens = token.split_contents()
    if len(tokens) > 2:
        media_type = tokens[2][1:-1]
    else:
        media_type = 'screen, projection'
    return CssTagNode(path, media_type=media_type)

def css_print_tag(parser, token):
    """Shortcut to render CSS as a print stylesheet.

    Usage::

        {% css_print "myfile.css" %}

    Which is equivalent to

        {% css "myfile.css" "print" %}"""
    path = get_path_from_tokens(token)
    media_type = 'print'
    return CssTagNode(path, media_type=media_type)

def parse_docopt_string(docopt_string):
    """returns a 2-tuple (usage, options)"""
    from re import match, DOTALL
    only_usage_pattern = '\\s+Usage:\\s+(?P<usage>.*)\\s+'
    usage_and_options_pattern = '\\s+Usage:\\s+(?P<usage>.*)\\s+Options:\\s+(?P<options>.*)\\s+'
    usage, options = ('', '')
    if match(usage_and_options_pattern, docopt_string, DOTALL):
        usage = match(usage_and_options_pattern, docopt_string, DOTALL).groupdict()['usage']
        options = match(usage_and_options_pattern, docopt_string, DOTALL).groupdict()['options']
    elif match(only_usage_pattern, docopt_string, DOTALL):
        usage = match(only_usage_pattern, docopt_string, DOTALL).groupdict()['usage']
    return (usage, options)

def distroinfo(cargs, version=__version__):
    """distroinfo Command-Line Interface"""
    code = 1
    args = docopt(__doc__, argv=cargs)
    try:
        if args['--version']:
            if not version:
                version = 'N/A'
            print(version)
            code = 0
        elif args['fetch']:
            code = fetch(info_url=args['<info-url>'], info_files=args['<info-file>'], cache_dir=args['--cache-dir'], fetcher=args['--fetcher'])
        elif args['dump']:
            code = dump(info_url=args['<info-url>'], info_files=args['<info-file>'], yaml_out=args['--yaml-out'], json_out=args['--json-out'], cache_dir=args['--cache-dir'], fetcher=args['--fetcher'])
    except (exception.InvalidInfoFormat, KeyboardInterrupt) as ex:
        code = getattr(ex, 'exit_code', code)
        print('')
        print(str(ex) or type(ex).__name__)
    return code

