def parse_log_line(line):
    """Parses a log line and returns it with more information

    :param line: str - A line from a bcbio-nextgen log
    :returns dict: A dictionary containing the line, if its a new step if its a Traceback or if the
                   analysis is finished"""
    matches = re.search('^\\[([^\\]]+)\\] ([^:]+: .*)', line)
    error = re.search('Traceback', line)
    if error:
        return {'line': line, 'step': 'error'}
    if not matches:
        return {'line': line, 'step': None}
    tstamp = matches.group(1)
    msg = matches.group(2)
    if not msg.find('Timing: ') >= 0:
        return {'line': line, 'step': None}
    when = datetime.strptime(tstamp, '%Y-%m-%dT%H:%MZ').replace(tzinfo=pytz.timezone('UTC'))
    step = msg.split(':')[-1].strip()
    return {'line': line, 'step': step, 'when': when}

def _ensure_ifaces_tuple(ifaces):
    """Convert to a tuple of interfaces and raise if not interfaces."""
    try:
        ifaces = tuple(ifaces)
    except TypeError:
        ifaces = (ifaces,)
    for iface in ifaces:
        if not _issubclass(iface, ibc.Iface):
            raise TypeError('Can only compare against interfaces.')
    return ifaces

def issubclass(cls, ifaces):
    """Check if the given class is an implementation of the given iface."""
    ifaces = _ensure_ifaces_tuple(ifaces)
    for iface in ifaces:
        return all((_check_for_definition(iface, cls, '__iclassattribute__', _is_attribute), _check_for_definition(iface, cls, '__iproperty__', _is_property), _check_for_definition(iface, cls, '__imethod__', _is_method), _check_for_definition(iface, cls, '__iclassmethod__', _is_classmethod)))

def isinstance(instance, ifaces):
    """Check if a given instance is an implementation of the interface."""
    ifaces = _ensure_ifaces_tuple(ifaces)
    for iface in ifaces:
        attributes = (attr for attr in iface.__abstractmethods__ if hasattr(getattr(iface, attr), '__iattribute__'))
        for attribute in attributes:
            if not hasattr(instance, attribute):
                return False
        if not issubclass(type(instance), ifaces):
            return False
    return True

def _get_call_class(method):
    """Find the call class for method if it exists else create one."""
    call_base, call_name = method.split('.', 1)
    mod = __import__('ubersmith.calls.{0}'.format(call_base), fromlist=[''])
    gen = (getattr(mod, x) for x in dir(mod) if not x.startswith('_'))
    gen = (x for x in gen if type(x) is type and issubclass(x, BaseCall))
    for call_class in gen:
        if call_class.method == method:
            return call_class
    else:
        class GenericCall(BaseCall):
            method = '.'.join((call_base, call_name))
        return GenericCall

def total_ordering(cls):
    """Class decorator that fills in missing ordering methods"""
    convert = {'__lt__': [('__gt__', lambda self, other: not (self < other or self == other)), ('__le__', lambda self, other: self < other or self == other), ('__ge__', lambda self, other: not self < other)], '__le__': [('__ge__', lambda self, other: not self <= other or self == other), ('__lt__', lambda self, other: self <= other and (not self == other)), ('__gt__', lambda self, other: not self <= other)], '__gt__': [('__lt__', lambda self, other: not (self > other or self == other)), ('__ge__', lambda self, other: self > other or self == other), ('__le__', lambda self, other: not self > other)], '__ge__': [('__le__', lambda self, other: not self >= other or self == other), ('__gt__', lambda self, other: self >= other and (not self == other)), ('__lt__', lambda self, other: not self >= other)]}
    roots = set(dir(cls)) & set(convert)
    if not roots:
        raise ValueError('must define at least one ordering operation: < > <= >=')
    root = max(roots)
    for opname, opfunc in convert[root]:
        if opname not in roots:
            opfunc.__name__ = opname
            opfunc.__doc__ = getattr(int, opname).__doc__
            setattr(cls, opname, opfunc)
    return cls

def load_signing_key(signing_key, crypto_backend=default_backend()):
    """Optional: crypto backend object from the "cryptography" python library
    """
    if not isinstance(crypto_backend, (Backend, MultiBackend)):
        raise ValueError('backend must be a valid Backend object')
    if isinstance(signing_key, EllipticCurvePrivateKey):
        return signing_key
    elif isinstance(signing_key, (str, unicode)):
        invalid_strings = [b'-----BEGIN PUBLIC KEY-----']
        invalid_string_matches = [string_value in signing_key for string_value in invalid_strings]
        if any(invalid_string_matches):
            raise ValueError('Signing key must be a private key, not a public key.')
        try:
            return load_der_private_key(signing_key, password=None, backend=crypto_backend)
        except:
            try:
                return load_pem_private_key(signing_key, password=None, backend=crypto_backend)
            except Exception:
                raise ValueError('Signing key must be a valid private key PEM or DER.')
    else:
        raise ValueError('Signing key must be in string or unicode format.')

def load_verifying_key(verifying_key, crypto_backend=default_backend()):
    """Optional: crypto backend object from the "cryptography" python library
    """
    if not isinstance(crypto_backend, (Backend, MultiBackend)):
        raise ValueError('backend must be a valid Backend object')
    if isinstance(verifying_key, EllipticCurvePublicKey):
        return verifying_key
    elif isinstance(verifying_key, (str, unicode)):
        try:
            return load_der_public_key(verifying_key, backend=crypto_backend)
        except:
            try:
                return load_pem_public_key(verifying_key, backend=crypto_backend)
            except Exception:
                raise ValueError('Invalid verifying key format')
    else:
        raise ValueError('Invalid verification key type')

def values():
    """Get the full current set of B3 values.
    :return: A dict containing the keys "X-B3-TraceId", "X-B3-ParentSpanId", "X-B3-SpanId", "X-B3-Sampled" and
    "X-B3-Flags" for the current span or subspan. NB some of the values are likely be None, but
    all keys will be present."""
    result = {}
    try:
        span = g.get('subspan') if 'subspan' in g else g
        for header in b3_headers:
            result[header] = span.get(header)
    except RuntimeError:
        for header in b3_headers:
            result[header] = None
    return result

def span(route):
    """Optional decorator for Flask routes.

    If you don't want to trace all routes using `Flask.before_request()' and 'Flask.after_request()'
    you can use this decorator as an alternative way to handle incoming B3 headers:

        @app.route('/instrumented')
        @span
        def instrumented():
            ...
            ...
            ...

    NB @span needs to come after (not before) @app.route."""
    @wraps(route)
    def route_decorator(*args, **kwargs):
        start_span()
        try:
            return route(*args, **kwargs)
        finally:
            end_span()
    return route_decorator

def model_factory(schema, resolver=None, base_class=model.Model, name=None):
    """Generate a model class based on the provided JSON Schema

    :param schema: dict representing valid JSON schema
    :param name: A name to give the class, if `name` is not in `schema`"""
    schema = copy.deepcopy(schema)
    resolver = resolver
    class Model(base_class):
        def __init__(self, *args, **kwargs):
            self.__dict__['schema'] = schema
            self.__dict__['resolver'] = resolver
            base_class.__init__(self, *args, **kwargs)
    if resolver is not None:
        Model.resolver = resolver
    if name is not None:
        Model.__name__ = name
    elif 'name' in schema:
        Model.__name__ = str(schema['name'])
    return Model

def to_raw_address(addr, section):
    """Converts the addr from a rva to a pointer to raw data in the file"""
    return addr - section.header.VirtualAddress + section.header.PointerToRawData

def get_ptr(data, offset=None, ptr_type=ctypes.c_void_p):
    """Returns a void pointer to the data"""
    ptr = ctypes.cast(ctypes.pointer(data), ctypes.c_void_p)
    if offset:
        ptr = ctypes.c_void_p(ptr.value + offset)
    if ptr_type != ctypes.c_void_p:
        ptr = ctypes.cast(ptr, ptr_type)
    return ptr

def modal_projection(self, p, forward=True):
    """Performs a field p into modal amplitudes pn
    using the basis [pmodes]. The inverse
    transform calculates p from pn"""
    if forward:
        pt = np.linalg.solve(self.pmodes[np.newaxis, np.newaxis], p.T).T
    else:
        pt = np.einsum('ik,k...->i...', self.pmodes, p)
    return pt

def reduce(args):
    """>>> reduce([(2, 4), (4, 9)])
    [(2, 4), (4, 9)]

    >>> reduce([(2, 6), (4, 10)])
    [(2, 10)]"""
    if len(args) < 2:
        return args
    args.sort()
    ret = [args[0]]
    for next_i, (s, e) in enumerate(args, start=1):
        if next_i == len(args):
            ret[-1] = (ret[-1][0], max(ret[-1][1], e))
            break
        ns, ne = args[next_i]
        if e > ns or ret[-1][1] > ns:
            ret[-1] = (ret[-1][0], max(e, ne, ret[-1][1]))
        else:
            ret.append((ns, ne))
    return ret

def loaddict(filename=DICTIONARY):
    """Load the dictionary from a specific JSON file."""
    global zhcdicts
    if zhcdicts:
        return
    if filename == _DEFAULT_DICT:
        zhcdicts = json.loads(get_module_res(filename).read().decode('utf-8'))
    else:
        with open(filename, 'rb') as f:
            zhcdicts = json.loads(f.read().decode('utf-8'))
    zhcdicts['SIMPONLY'] = frozenset(zhcdicts['SIMPONLY'])
    zhcdicts['TRADONLY'] = frozenset(zhcdicts['TRADONLY'])

def issimp(s, full=False):
    """Detect text is whether Simplified Chinese or Traditional Chinese.
    Returns True for Simplified; False for Traditional; None for unknown.
    If full=False, it returns once first simplified- or traditional-only
    character is encountered, so it's for quick and rough identification;
    else, it compares the count and returns the most likely one.
    Use `is` (True/False/None) to check the result.

    `s` must be unicode (Python 2) or str (Python 3), or you'll get None."""
    if zhcdicts is None:
        loaddict(DICTIONARY)
    simp, trad = (0, 0)
    if full:
        for ch in s:
            if ch in zhcdicts['SIMPONLY']:
                simp += 1
            elif ch in zhcdicts['TRADONLY']:
                trad += 1
        if simp > trad:
            return True
        elif simp < trad:
            return False
        else:
            return None
    else:
        for ch in s:
            if ch in zhcdicts['SIMPONLY']:
                return True
            elif ch in zhcdicts['TRADONLY']:
                return False
        return None

def main():
    """Simple stdin/stdout interface."""
    if len(sys.argv) == 2 and sys.argv[1] in Locales:
        locale = sys.argv[1]
        convertfunc = convert
    elif len(sys.argv) == 3 and sys.argv[1] == '-w' and (sys.argv[2] in Locales):
        locale = sys.argv[2]
        convertfunc = convert_for_mw
    else:
        thisfile = __file__ if __name__ == '__main__' else 'python -mzhconv'
        print('usage: %s [-w] {zh-cn|zh-tw|zh-hk|zh-sg|zh-hans|zh-hant|zh} < input > output' % thisfile)
        sys.exit(1)
    loaddict()
    ln = sys.stdin.readline()
    while ln:
        l = ln.rstrip('\r\n')
        if sys.version_info[0] < 3:
            l = unicode(l, 'utf-8')
        res = convertfunc(l, locale)
        if sys.version_info[0] < 3:
            print(res.encode('utf-8'))
        else:
            print(res)
        ln = sys.stdin.readline()

def bucket_lister(manager, bucket_name, prefix=None, marker=None, limit=None):
    """A generator function for listing keys in a bucket."""
    eof = False
    while not eof:
        ret, eof, info = manager.list(bucket_name, prefix=prefix, limit=limit, marker=marker)
        if ret is None:
            raise QiniuError(info)
        if not eof:
            marker = ret['marker']
        for item in ret['items']:
            yield item

def get_qiniu_config(name, default=None):
    """Get configuration variable from environment variable
    or django setting.py"""
    config = os.environ.get(name, getattr(settings, name, default))
    if config is not None:
        if isinstance(config, six.string_types):
            return config.strip()
        else:
            return config
    else:
        raise ImproperlyConfigured("Can't find config for '%s' either in environmentvariable or in setting.py" % name)

def _merge(left, right, path=None, conflict=_Conflict.error):
    """Merges values in place from *right* into *left*.

    :param left: mapping to merge into
    :param right: mapping to merge from
    :param path: `list` of keys processed before (used for error reporting
        only, should only need to be provided by recursive calls)
    :param conflict: action to be taken on merge conflict, raising an error
        or overwriting an existing value
    :return: *left*, for convenience"""
    path = path or []
    conflict = _Conflict(conflict)
    for key in right:
        if key in left:
            if isinstance(left[key], Mapping) and isinstance(right[key], Mapping):
                _merge(left[key], right[key], path + [key], conflict=conflict)
            elif left[key] != right[key]:
                if conflict is _Conflict.error:
                    conflict_path = '.'.join(path + [key])
                    raise MergeConflictError('merge conflict at {}'.format(conflict_path), key=conflict_path)
                else:
                    left[key] = right[key]
        else:
            left[key] = right[key]
    return left

def _split_keys(mapping, separator='.', colliding=None):
    """Recursively walks *mapping* to split keys that contain the separator into
    nested mappings.

    .. note::

        Keys not of type `str` are not supported and will raise errors.

    :param mapping: the mapping to process
    :param separator: the character (sequence) to use as the separator between
        keys
    :return: a mapping where keys containing *separator* are split into nested
        mappings"""
    result = {}
    for key, value in mapping.items():
        if isinstance(value, Mapping):
            value = _split_keys(value, separator)
        if not isinstance(key, str):
            raise ValueError('non-str type keys ({0}, {0.__class__.__module__}.{0.__class__.__name__}) not supported'.format(key))
        if separator in key:
            key, rest = key.split(separator, 1)
            value = _split_keys({rest: value}, separator)
        if colliding and key in colliding:
            warnings.warn('key {key} collides with a named member, use get() method to retrieve the value for {key}'.format(key=key), UserWarning)
        _merge(result, {key: value})
    return result

def request(request_callback=None, **kwargs):
    """Chisel request decorator"""
    if request_callback is None:
        return lambda fn: request(fn, **kwargs)
    else:
        return Request(request_callback, **kwargs).decorate_module(request_callback)

def string(_object):
    """Validates a given input is of type string.

    Example usage::

        data = {'a' : 21}
        schema = (string, 21)

    You can also use this as a decorator, as a way to check for the
    input before it even hits a validator you may be writing.

    .. note::
        If the argument is a callable, the decorating behavior will be
        triggered, otherwise it will act as a normal function."""
    if is_callable(_object):
        _validator = _object
        @wraps(_validator)
        def decorated(value):
            ensure(isinstance(value, basestring), 'not of type string')
            return _validator(value)
        return decorated
    ensure(isinstance(_object, basestring), 'not of type string')

