def parse_setup(options: Union[List, str]) -> str:
    """Convert potentially a list of commands into a single string.

    This creates a single string with newlines between each element of the list
    so that they will all run after each other in a bash script."""
    if isinstance(options, str):
        return options
    return '\n'.join(options)

def create_scheduler_file(scheduler: str, job: Job) -> str:
    """Substitute values into a template scheduler file."""
    logger.debug('Create Scheduler File Function')
    if job.scheduler_options is None:
        scheduler_options: Dict[str, Any] = {}
    else:
        scheduler_options = deepcopy(job.scheduler_options)
    try:
        setup_string = parse_setup(scheduler_options['setup'])
        del scheduler_options['setup']
    except KeyError:
        setup_string = ''
    header_string = create_header_string(scheduler, **scheduler_options)
    header_string += get_array_string(scheduler, len(job))
    if scheduler.upper() == 'SLURM':
        workdir = '$SLURM_SUBMIT_DIR'
        array_index = '$SLURM_ARRAY_TASK_ID'
    elif scheduler.upper() == 'PBS':
        workdir = '$PBS_O_WORKDIR'
        array_index = '$PBS_ARRAY_INDEX'
    return header_string + SCHEDULER_TEMPLATE.format(workdir=workdir, command_list=job.as_bash_array(), setup=setup_string, array_index=array_index)

def parse_doc(doc):
    """Parse docstrings to dict, it should look like:
      key: value"""
    if not doc:
        return {}
    out = {}
    for s in doc.split('\n'):
        s = s.strip().split(':', maxsplit=1)
        if len(s) == 2:
            out[s[0]] = s[1]
    return out

def combine_dictionaries(dicts: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Merge a list of dictionaries into a single dictionary.

    Where there are collisions the first value in the list will be set
    as this function is using ChainMap to combine the dicts."""
    return dict(ChainMap(*dicts))

def iterator_zip(variables: VarType, parent: str=None) -> Iterable[VarMatrix]:
    """Apply the zip operator to a set of variables.

    This uses the python zip iterator to combine multiple lists of variables such that
    the nth variable in each list is aligned.

    Args:
        variables: The variables object
        parent: Unused"""
    logger.debug('Yielding from zip iterator')
    if isinstance(variables, list):
        for item in variables:
            yield list(variable_matrix(item, parent, 'zip'))
    else:
        yield list(variable_matrix(variables, parent, 'zip'))

def iterator_arange(variables: VarType, parent: str) -> Iterable[VarMatrix]:
    """Create a list of values using the :func:`numpy.arange` function.

    Args:
        variables: The input variables for the creation of the range
        parent: The variable for which the values are being generated.

    Returns: A list of dictionaries mapping the parent to each value."""
    assert parent is not None
    if isinstance(variables, (int, float)):
        yield [{parent: i} for i in np.arange(variables)]
    elif isinstance(variables, dict):
        if variables.get('stop'):
            yield [{parent: i} for i in arange(**variables)]
        else:
            raise ValueError(f'Stop is a required keyword for the arange iterator.')
    else:
        raise ValueError(f'The arange keyword only takes a dict as arguments, got {variables} of type {type(variables)}')

def iterator_cycle(variables: VarType, parent: str) -> Iterable[VarMatrix]:
    """Cycle through a list of values a specified number of times

    Args:
        variables: The input variables for the creation of the range
        parent: The variable for which the values are being generated.

    Returns: A list of dictionaries mapping the parent to each value."""
    if isinstance(variables, dict):
        if variables.get('times'):
            times = int(variables['times'])
            del variables['times']
            yield (list(variable_matrix(variables, parent, 'product')) * times)
        else:
            raise ValueError(f'times is a required keyword for the repeat iterator.')
    else:
        raise ValueError(f'The repeat operator only takes a dict as arguments, got {variables} of type {type(variables)}')

def uniqueify(my_list: Any) -> List[Any]:
    """Remove duplicate entries in a list retaining order."""
    if sys.version_info >= (3, 6):
        return list(dict.fromkeys(my_list))
    seen = set()
    return [x for x in my_list if x not in seen and (not seen.add(x))]

def process_command(command: CommandInput, matrix: VarMatrix) -> List[Command]:
    """Generate all combinations of commands given a variable matrix.

    Processes the commands to be sequences of strings."""
    assert command is not None
    if isinstance(command, str):
        command_list = [Command(command, variables=variables) for variables in matrix]
    elif isinstance(command, list):
        command_list = [Command(command, variables=variables) for variables in matrix]
    else:
        if command.get('command') is not None:
            cmd = command.get('command')
        else:
            cmd = command.get('cmd')
        creates = str(command.get('creates', ''))
        requires = str(command.get('requires', ''))
        assert isinstance(cmd, (list, str))
        command_list = [Command(cmd, variables, creates, requires) for variables in matrix]
    return uniqueify(command_list)

def run_bash_jobs(jobs: Iterator[Job], directory: PathLike=Path.cwd(), dry_run: bool=False) -> None:
    """Submit commands to the bash shell.

    This function runs the commands iteratively but handles errors in the
    same way as with the pbs_commands function. A command will run for all
    combinations of variables in the variable matrix, however if any one of
    those commands fails then the next command will not run."""
    logger.debug('Running commands in bash shell')
    for job in jobs:
        if shutil.which(job.shell) is None:
            raise ProcessLookupError(f"The shell '{job.shell}' was not found.")
        failed = False
        for command in job:
            for cmd in command:
                logger.info(cmd)
                if dry_run:
                    print(f"{job.shell} -c '{cmd}'")
                else:
                    result = subprocess.run([job.shell, '-c', f'{cmd}'], cwd=str(directory))
                    if result.returncode != 0:
                        failed = True
                        logger.error('Command failed: %s', command)
                        break
        if failed:
            logger.error('A command failed, not continuing further.')
            return

def determine_scheduler(scheduler: Optional[str], experiment_definition: Dict[str, YamlValue]) -> str:
    """Determine the scheduler to use to run the jobs."""
    if scheduler is not None:
        if scheduler in ['shell', 'pbs', 'slurm']:
            return scheduler
        raise ValueError("Argument scheduler only supports input values of ['shell', 'pbs', 'slurm']")
    if experiment_definition.get('pbs'):
        return 'pbs'
    if experiment_definition.get('slurm'):
        return 'slurm'
    if experiment_definition.get('shell'):
        return 'shell'
    if shutil.which('pbs') is not None:
        return 'pbs'
    if shutil.which('slurm') is not None:
        return 'slurm'
    return 'shell'

def request_uniq(func):
    """return unique dict for each uwsgi request.
    note: won't work on non-uwsgi cases"""
    def _wrapped(*args, **kwargs):
        data = _get_request_unique_cache()
        return func(data, *args, **kwargs)
    return _wrapped

def safe_repr(obj):
    """Try to get ``__name__`` first, ``__class__.__name__`` second
    and finally, if we can't get anything acceptable, fallback
    to user a ``repr()`` call."""
    name = getattr(obj, '__name__', getattr(obj.__class__, '__name__'))
    if name == 'ndict':
        name = 'dict'
    return name or repr(obj)

def re_sort(data):
    """A data with keys that are not enumerated sequentially will be
    re sorted and sequentially ordered.

    For example::

        >>> data = {16: ('1', 'b'), 3: ('1', 'a')}
        >>> re_sort(data)
        >>> {0: ('1', 'a'), 1: ('1', 'b')}"""
    keys = sorted(data.keys())
    new_data = {}
    for number, key in enumerate(keys):
        new_data[number] = data[key]
    return new_data

def sift(data, required_items=None):
    """Receive a ``data`` object that will be in the form
    of a normalized structure (e.g. ``{0: {'a': 0}}``) and
    filter out keys that match the ``required_items``."""
    required_items = required_items or []
    new_data = {}
    for k, v in data.items():
        if v[0] in required_items:
            new_data[k] = v
            continue
        for required_item in required_items:
            key = getattr(required_item, '_object', False)
            if key:
                if v[0] == key:
                    new_data[k] = v
    return re_sort(new_data)

def data_item(data):
    """When trying to return a meaningful error about an unexpected data item
    we cannot just `repr(data)` as that could show a gigantic data struture.

    This utility should try to get the key of the first item or the single item
    in the data structure."""
    if isinstance(data, ndict):
        for item in data:
            return repr(data[item][0])
    elif isinstance(data, dict):
        for item in data:
            return repr(data[item])
    elif isinstance(data, list):
        return repr(data[0])
    return repr(data)

def execfile(fname, _globals, _locals):
    """Usage: execfile('path/to/file.py', globals(), locals())"""
    if os.path.exists(fname):
        with open(fname) as f:
            code = compile(f.read(), os.path.basename(fname), 'exec')
            exec(code, _globals, _locals)
            return True
    else:
        return False

def parse_iso8601_date(string):
    """Parse an ISO 8601 date string"""
    match = _RE_ISO8601_DATE.search(string)
    if not match:
        raise ValueError('Expected ISO 8601 date')
    year = int(match.group('year'))
    month = int(match.group('month'))
    day = int(match.group('day'))
    return date(year, month, day)

def import_submodules(package, parent_package=None, exclude_submodules=None):
    """Generator which imports all submodules of a module, recursively, including subpackages

    :param package: package name (e.g 'chisel.util'); may be relative if parent_package is provided
    :type package: str
    :param parent_package: parent package name (e.g 'chisel')
    :type package: str
    :rtype: iterator of modules"""
    exclude_submodules_dot = [x + '.' for x in exclude_submodules] if exclude_submodules else exclude_submodules
    package = importlib.import_module(package, parent_package)
    for _, name, _ in pkgutil.walk_packages(package.__path__, package.__name__ + '.'):
        if exclude_submodules and (name in exclude_submodules or any((name.startswith(x) for x in exclude_submodules_dot))):
            continue
        yield importlib.import_module(name)

def not_empty(_object):
    """Validates the given input (has to be a valid data structure) is empty.
    Input *has* to be one of: `list`, `dict`, or `string`.

    It is specially useful when most of the validators being created are
    dealing with data structures that should not be empty."""
    if is_callable(_object):
        _validator = _object
        @wraps(_validator)
        @instance_of()
        def decorated(value):
            ensure(value, '%s is empty' % safe_repr(value))
            return _validator(value)
        return decorated
    try:
        ensure(len(_object), '%s is empty' % safe_repr(_object))
    except TypeError:
        raise AssertionError('not of any valid types: [list, dict, str]')

def create_analytic_backend(settings):
    """Creates a new Analytics backend from the settings

    :param settings: Dictionary of settings for the analytics backend
    :returns: A backend object implementing the analytics api

    >>>
    >>> analytics = create_analytic({
    >>>     'backend': 'analytics.backends.redis.Redis',
    >>>     'settings': {
    >>>         'defaults': {
    >>>             'host': 'localhost',
    >>>             'port': 6379,
    >>>             'db': 0,
    >>>         },
    >>>         'hosts': [{'db': 0}, {'db': 1}, {'host': 'redis.example.org'}]
    >>>     },
    >>> })"""
    backend = settings.get('backend')
    if isinstance(backend, basestring):
        backend = import_string(backend)
    elif backend:
        backend = backend
    else:
        raise KeyError('backend')
    return backend(settings.get('settings', {}))

def round_controlled(cycled_iterable, rounds=1):
    """Return after <rounds> passes through a cycled iterable."""
    round_start = None
    rounds_completed = 0
    for item in cycled_iterable:
        if round_start is None:
            round_start = item
        elif item == round_start:
            rounds_completed += 1
        if rounds_completed == rounds:
            return
        yield item

def select_only_revertant_mutations(bpdf, snv=None, ins=None, dlt=None):
    """Selects only mutations that revert the given mutations in a single event."""
    if sum([bool(snv), bool(ins), bool(dlt)]) != 1:
        raise Exception('Should be either snv, ins or del'.format(snv))
    if snv:
        if snv not in ['A', 'C', 'G', 'T']:
            raise Exception('snv {} should be A, C, G or T'.format(snv))
        return bpdf[(bpdf.most_common_al == snv) & (bpdf.most_common_al_count == bpdf.most_common_count)]
    elif bool(ins):
        return bpdf[(bpdf.most_common_indel.apply(lambda x: len(x) + len(ins) % 3 if x else None) == 0) & (bpdf.most_common_indel_type == '+') & (bpdf.most_common_count == bpdf.most_common_indel_count) | (bpdf.most_common_indel.apply(lambda x: len(ins) - len(x) % 3 if x else None) == 0) & (bpdf.most_common_indel_type == '-') & (bpdf.most_common_count == bpdf.most_common_indel_count)]
    elif bool(dlt):
        return bpdf[(bpdf.most_common_indel.apply(lambda x: len(x) - len(dlt) % 3 if x else None) == 0) & (bpdf.most_common_indel_type == '+') & (bpdf.most_common_count == bpdf.most_common_indel_count) | (bpdf.most_common_indel.apply(lambda x: -len(dlt) - len(x) % 3 if x else None) == 0) & (bpdf.most_common_indel_type == '-') & (bpdf.most_common_count == bpdf.most_common_indel_count)]
    else:
        raise Exception('No mutation given?')

def generate_s3_url(files):
    """Takes files from React side, creates
    SolveBio Object containing signed S3 URL."""
    if files:
        vault = g.client.Vault.get_personal_vault()
        files = json.loads(files)
        objects = []
        for i in xrange(len(files)):
            obj = g.client.Object.create(vault_id=vault.id, object_type='file', filename=files[i].get('filename'), mimetype=files[i].get('mimetype'), size=files[i].get('size'))
            objects.append({'id': obj.id, 'filename': obj.filename, 'upload_url': obj.upload_url})
        return json.dumps(objects)

def action(action_callback=None, **kwargs):
    """Chisel action decorator"""
    if action_callback is None:
        return lambda fn: action(fn, **kwargs)
    else:
        return Action(action_callback, **kwargs).decorate_module(action_callback)

def get_plain_logname(base_name, root_dir, enable_json):
    """we nest all plain logs to prevent double log shipping"""
    if enable_json:
        nested_dir = os.path.join(root_dir, 'plain')
        if os.path.exists(root_dir) and (not os.path.exists(nested_dir)):
            os.mkdir(nested_dir)
        root_dir = nested_dir
    return os.path.join(root_dir, '{}.log'.format(base_name))

def setup_logger(base_name, root_dir=None, enable_json=True, json_formatter='tipsi_tools.tipsi_logging.JSFormatter', loggers={}):
    """json_formatter:
    'fan.contrib.django.span_formatter.SpanFormatter' - add INSTALLATION_ID, SPAN and etc"""
    if not root_dir:
        root_dir = os.environ.get('LOG_DIR')
    assert root_dir, 'You should pass root_dir parameter or set env LOG_DIR'
    JSON_FORMATTER = {'()': json_formatter, 'env_vars': ['HOST_TYPE', 'TIPSI_CONFIG', 'TIPSI_BRANCH', 'CONTAINER_TYPE']}
    default_loggers = {'': {'handlers': ['default'], 'level': 'DEBUG', 'propagate': True}, 'googleapicliet.discovery_cache': {'level': 'ERROR'}, 'boto3': {'level': 'INFO'}, 'botocore': {'level': 'INFO'}, 'kazoo': {'level': 'INFO'}, 'urllib3': {'level': 'INFO'}}
    LOGGING = {'version': 1, 'disable_existing_loggers': False, 'formatters': {'json': JSON_FORMATTER, 'standard': {'format': '%(asctime)s [%(levelname)s] %(name)s: %(message)s'}}, 'handlers': {'default': base_handler(get_plain_logname(base_name, root_dir, enable_json))}, 'loggers': {**default_loggers, **loggers}}
    if enable_json:
        LOGGING['handlers']['json'] = base_handler(os.path.join(root_dir, '{}.json_log'.format(base_name)), formatter='json')
        LOGGING['loggers']['']['handlers'].append('json')
    logging.config.dictConfig(LOGGING)

def run(command):
    """Run command in shell, accepts command construction from list
    Return (return_code, stdout, stderr)
    stdout and stderr - as list of strings"""
    if isinstance(command, list):
        command = ' '.join(command)
    out = subprocess.run(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    return (out.returncode, _prepare(out.stdout), _prepare(out.stderr))

def succ(cmd, check_stderr=True, stdout=None, stderr=None):
    """Alias to run with check return code and stderr"""
    code, out, err = run(cmd)
    if stdout is not None:
        stdout[:] = out
    if stderr is not None:
        stderr[:] = err
    if code != 0:
        for l in out:
            print(l)
    assert code == 0, 'Return: {} {}\nStderr: {}'.format(code, cmd, err)
    if check_stderr:
        assert err == [], 'Error: {} {}'.format(err, code)
    return (code, out, err)

def wait_socket(host, port, timeout=120):
    """Wait for socket opened on remote side. Return False after timeout"""
    return wait_result(lambda: check_socket(host, port), True, timeout)

def interpolate_sysenv(line, defaults={}):
    """Format line system environment variables + defaults"""
    map = ChainMap(os.environ, defaults)
    return line.format(**map)

def source(fname):
    """Acts similar to bash 'source' or '.' commands."""
    rex = re.compile('(?:export |declare -x )?(.*?)="(.*?)"')
    out = call_out('source {} && export'.format(fname))
    out = [x for x in out if 'export' in x or 'declare' in x]
    out = {k: v for k, v in [rex.match(x).groups() for x in out if rex.match(x)]}
    for k, v in out.items():
        os.environ[k] = v

def cd(dir_name):
    """do something in other directory and return back after block ended"""
    old_path = os.path.abspath('.')
    os.chdir(dir_name)
    try:
        yield
        os.chdir(old_path)
    except Exception:
        os.chdir(old_path)
        raise

def read_envvar_file(name, extension):
    """Read values from a file provided as a environment variable
    ``NAME_CONFIG_FILE``.

    :param name: environment variable prefix to look for (without the
        ``_CONFIG_FILE``)
    :param extension: *(unused)*
    :return: a `.Configuration`, possibly `.NotConfigured`"""
    envvar_file = environ.get('{}_config_file'.format(name).upper())
    if envvar_file:
        return loadf(envvar_file)
    else:
        return NotConfigured

def loadf(*fnames, default=_NoDefault, missing=Missing.silent):
    """Read a `.Configuration` instance from named files.

    :param fnames: name of the files to ``open()``
    :param default: `dict` or `.Configuration` to use when a file does not
        exist (default is to raise a `FileNotFoundError`)
    :param missing: policy to be used when a configured key is missing, either
        as a `.Missing` instance or a default value
    :return: a `.Configuration` instance providing values from *fnames*
    :rtype: `.Configuration`"""
    def readf(fname):
        if default is _NoDefault or path.exists(fname):
            with open(fname, 'r') as fp:
                return yaml.safe_load(fp.read()) or {}
        else:
            return default
    return Configuration(*(readf(path.expanduser(fname)) for fname in fnames), missing=missing)

def fastalite(handle):
    """Return a sequence of namedtuple objects from a fasta file with
    attributes (id, description, seq) given open file-like object
    ``handle``"""
    Seq = namedtuple('Seq', ['id', 'description', 'seq'])
    header, seq = ('', [])
    for line in handle:
        if line.startswith('>'):
            if header:
                yield Seq(header.split()[0], header, ''.join(seq))
            header, seq = (line[1:].strip(), [])
        else:
            seq.append(line.strip())
    if header and seq:
        yield Seq(header.split()[0], header, ''.join(seq))

def _find_in_columncollection(columns, name):
    """Find a column in a column collection by name or _label"""
    for col in columns:
        if col.name == name or getattr(col, '_label', None) == name:
            return col
    return None

def find_column(selectable, name):
    """Find a column named `name` in selectable

    :param selectable:
    :param name:
    :return: A column object"""
    from recipe import Recipe
    if isinstance(selectable, Recipe):
        selectable = selectable.subquery()
    if isinstance(selectable, DeclarativeMeta):
        col = getattr(selectable, name, None)
        if col is not None:
            return col
        col = _find_in_columncollection(selectable.__table__.columns, name)
        if col is not None:
            return col
    elif hasattr(selectable, 'c') and isinstance(selectable.c, ImmutableColumnCollection):
        col = getattr(selectable.c, name, None)
        if col is not None:
            return col
        col = _find_in_columncollection(selectable.c, name)
        if col is not None:
            return col
    raise BadIngredient('Can not find {} in {}'.format(name, selectable))

def ingredient_from_validated_dict(ingr_dict, selectable):
    """Create an ingredient from an dictionary.

    This object will be deserialized from yaml"""
    validator = IngredientValidator(schema=ingr_dict['kind'])
    if not validator.validate(ingr_dict):
        raise Exception(validator.errors)
    ingr_dict = validator.document
    kind = ingr_dict.pop('kind', 'Metric')
    IngredientClass = ingredient_class_for_name(kind)
    if IngredientClass is None:
        raise BadIngredient('Unknown ingredient kind')
    args = []
    for fld in ingr_dict.pop('_fields', []):
        args.append(parse_validated_field(ingr_dict.pop(fld), selectable))
    return IngredientClass(*args, **ingr_dict)

def AutomaticShelf(table):
    """Given a SQLAlchemy Table, automatically generate a Shelf with metrics
    and dimensions based on its schema."""
    if hasattr(table, '__table__'):
        table = table.__table__
    config = introspect_table(table)
    return Shelf.from_config(config, table)

def introspect_table(table):
    """Given a SQLAlchemy Table object, return a Shelf description suitable
    for passing to Shelf.from_config."""
    d = {}
    for c in table.columns:
        if isinstance(c.type, String):
            d[c.name] = {'kind': 'Dimension', 'field': c.name}
        if isinstance(c.type, (Integer, Float)):
            d[c.name] = {'kind': 'Metric', 'field': c.name}
    return d

def prettyprintable_sql(statement, dialect=None, reindent=True):
    """Generate an SQL expression string with bound parameters rendered inline
    for the given SQLAlchemy statement. The function can also receive a
    `sqlalchemy.orm.Query` object instead of statement.

    WARNING: Should only be used for debugging. Inlining parameters is not
             safe when handling user created data."""
    if isinstance(statement, sqlalchemy.orm.Query):
        if dialect is None:
            dialect = statement.session.get_bind().dialect
        statement = statement.statement
    if dialect:
        DialectKlass = dialect.__class__
    else:
        DialectKlass = DefaultDialect
    class LiteralDialect(DialectKlass):
        colspecs = {String: StringLiteral, DateTime: StringLiteral, Date: StringLiteral, NullType: StringLiteral}
    compiled = statement.compile(dialect=LiteralDialect(), compile_kwargs={'literal_binds': True})
    return sqlparse.format(str(compiled), reindent=reindent)

def get_structdmtypes_for_python_typeorobject(typeorobj):
    """Return structchar, dmtype for the python (or numpy)
    type or object typeorobj.
    For more complex types we only return the dm type"""
    if isinstance(typeorobj, type):
        comparer = lambda test: test is typeorobj
    else:
        comparer = lambda test: isinstance(typeorobj, test)
    if comparer(int) and (not -2 ** 31 < typeorobj < 2 ** 31 - 1):
        return ('q', 11)
    for key, name, sc, types in dm_simple_names:
        for t in types:
            if comparer(t):
                return (sc, key)
    if comparer(str):
        return (None, get_dmtype_for_name('array'))
    elif comparer(unicode_type):
        return (None, get_dmtype_for_name('array'))
    elif comparer(array.array):
        return (None, get_dmtype_for_name('array'))
    elif comparer(tuple):
        return (None, get_dmtype_for_name('struct'))
    elif comparer(structarray):
        return (None, get_dmtype_for_name('array'))
    logging.warn('No appropriate DMType found for %s, %s', typeorobj, type(typeorobj))
    return None

def standard_dm_read(datatype_num, desc):
    """datatype_num is the number of the data type, see dm_simple_names
    above. desc is a (nicename, struct_char) tuple. We return a function
    that parses the data for us."""
    nicename, structchar, types = desc
    def dm_read_x(f, outdata=None):
        """Reads (or write if outdata is given) a simple data type.
        returns the data if reading and the number of bytes of header"""
        if outdata is not None:
            if verbose:
                print('dm_write start', structchar, outdata, 'at', f.tell())
            put_into_file(f, '<' + structchar, outdata)
            if verbose:
                print('dm_write end', f.tell())
            return 0
        else:
            if verbose:
                print('dm_read start', structchar, 'at', f.tell())
            result = get_from_file(f, '<' + structchar)
            if verbose:
                print('dm_read end', f.tell())
            return (result, 0)
    return dm_read_x

def read_exif_ifd(fh, byteorder, dtype, count, offsetsize):
    """Read EXIF tags from file and return as dict."""
    exif = read_tags(fh, byteorder, offsetsize, TIFF.EXIF_TAGS, maxifds=1)
    for name in ('ExifVersion', 'FlashpixVersion'):
        try:
            exif[name] = bytes2str(exif[name])
        except Exception:
            pass
    if 'UserComment' in exif:
        idcode = exif['UserComment'][:8]
        try:
            if idcode == b'ASCII\x00\x00\x00':
                exif['UserComment'] = bytes2str(exif['UserComment'][8:])
            elif idcode == b'UNICODE\x00':
                exif['UserComment'] = exif['UserComment'][8:].decode('utf-16')
        except Exception:
            pass
    return exif

def read_gps_ifd(fh, byteorder, dtype, count, offsetsize):
    """Read GPS tags from file and return as dict."""
    return read_tags(fh, byteorder, offsetsize, TIFF.GPS_TAGS, maxifds=1)

def read_interoperability_ifd(fh, byteorder, dtype, count, offsetsize):
    """Read Interoperability tags from file and return as dict."""
    tag_names = {1: 'InteroperabilityIndex'}
    return read_tags(fh, byteorder, offsetsize, tag_names, maxifds=1)

def read_utf8(fh, byteorder, dtype, count, offsetsize):
    """Read tag data from file and return as unicode string."""
    return fh.read(count).decode('utf-8')

def read_numpy(fh, byteorder, dtype, count, offsetsize):
    """Read tag data from file and return as numpy array."""
    dtype = 'b' if dtype[-1] == 's' else byteorder + dtype[-1]
    return fh.read_array(dtype, count)

def read_json(fh, byteorder, dtype, count, offsetsize):
    """Read JSON tag data from file and return as object."""
    data = fh.read(count)
    try:
        return json.loads(unicode(stripnull(data), 'utf-8'))
    except ValueError:
        log.warning('read_json: invalid JSON')

def read_uic1tag(fh, byteorder, dtype, count, offsetsize, planecount=None):
    """Read MetaMorph STK UIC1Tag from file and return as dict.

    Return empty dictionary if planecount is unknown."""
    assert dtype in ('2I', '1I') and byteorder == '<'
    result = {}
    if dtype == '2I':
        values = fh.read_array('<u4', 2 * count).reshape(count, 2)
        result = {'ZDistance': values[:, 0] / values[:, 1]}
    elif planecount:
        for _ in range(count):
            tagid = struct.unpack('<I', fh.read(4))[0]
            if tagid in (28, 29, 37, 40, 41):
                fh.read(4)
                continue
            name, value = read_uic_tag(fh, tagid, planecount, offset=True)
            result[name] = value
    return result

def read_uic2tag(fh, byteorder, dtype, planecount, offsetsize):
    """Read MetaMorph STK UIC2Tag from file and return as dict."""
    assert dtype == '2I' and byteorder == '<'
    values = fh.read_array('<u4', 6 * planecount).reshape(planecount, 6)
    return {'ZDistance': values[:, 0] / values[:, 1], 'DateCreated': values[:, 2], 'TimeCreated': values[:, 3], 'DateModified': values[:, 4], 'TimeModified': values[:, 5]}

def read_uic4tag(fh, byteorder, dtype, planecount, offsetsize):
    """Read MetaMorph STK UIC4Tag from file and return as dict."""
    assert dtype == '1I' and byteorder == '<'
    result = {}
    while True:
        tagid = struct.unpack('<H', fh.read(2))[0]
        if tagid == 0:
            break
        name, value = read_uic_tag(fh, tagid, planecount, offset=False)
        result[name] = value
    return result

def read_uic_image_property(fh):
    """Read UIC ImagePropertyEx tag from file and return as dict."""
    size = struct.unpack('B', fh.read(1))[0]
    name = struct.unpack('%is' % size, fh.read(size))[0][:-1]
    flags, prop = struct.unpack('<IB', fh.read(5))
    if prop == 1:
        value = struct.unpack('II', fh.read(8))
        value = value[0] / value[1]
    else:
        size = struct.unpack('B', fh.read(1))[0]
        value = struct.unpack('%is' % size, fh.read(size))[0]
    return dict(name=name, flags=flags, value=value)

def read_cz_lsminfo(fh, byteorder, dtype, count, offsetsize):
    """Read CZ_LSMINFO tag from file and return as dict."""
    assert byteorder == '<'
    magic_number, structure_size = struct.unpack('<II', fh.read(8))
    if magic_number not in (50350412, 67127628):
        raise ValueError('invalid CZ_LSMINFO structure')
    fh.seek(-8, 1)
    if structure_size < numpy.dtype(TIFF.CZ_LSMINFO).itemsize:
        lsminfo = []
        size = 0
        for name, dtype in TIFF.CZ_LSMINFO:
            size += numpy.dtype(dtype).itemsize
            if size > structure_size:
                break
            lsminfo.append((name, dtype))
    else:
        lsminfo = TIFF.CZ_LSMINFO
    lsminfo = fh.read_record(lsminfo, byteorder=byteorder)
    lsminfo = recarray2dict(lsminfo)
    for name, reader in TIFF.CZ_LSMINFO_READERS.items():
        if reader is None:
            continue
        offset = lsminfo.get('Offset' + name, 0)
        if offset < 8:
            continue
        fh.seek(offset)
        try:
            lsminfo[name] = reader(fh)
        except ValueError:
            pass
    return lsminfo

def read_lsm_floatpairs(fh):
    """Read LSM sequence of float pairs from file and return as list."""
    size = struct.unpack('<i', fh.read(4))[0]
    return fh.read_array('<2f8', count=size)

def read_lsm_positions(fh):
    """Read LSM positions from file and return as list."""
    size = struct.unpack('<I', fh.read(4))[0]
    return fh.read_array('<2f8', count=size)

def read_lsm_timestamps(fh):
    """Read LSM time stamps from file and return as list."""
    size, count = struct.unpack('<ii', fh.read(8))
    if size != 8 + 8 * count:
        log.warning('read_lsm_timestamps: invalid LSM TimeStamps block')
        return []
    return fh.read_array('<f8', count=count)

def read_lsm_scaninfo(fh):
    """Read LSM ScanInfo structure from file and return as dict."""
    block = {}
    blocks = [block]
    unpack = struct.unpack
    if struct.unpack('<I', fh.read(4))[0] != 268435456:
        log.warning('read_lsm_scaninfo: invalid LSM ScanInfo structure')
        return block
    fh.read(8)
    while True:
        entry, dtype, size = unpack('<III', fh.read(12))
        if dtype == 2:
            value = bytes2str(stripnull(fh.read(size)))
        elif dtype == 4:
            value = unpack('<i', fh.read(4))[0]
        elif dtype == 5:
            value = unpack('<d', fh.read(8))[0]
        else:
            value = 0
        if entry in TIFF.CZ_LSMINFO_SCANINFO_ARRAYS:
            blocks.append(block)
            name = TIFF.CZ_LSMINFO_SCANINFO_ARRAYS[entry]
            newobj = []
            block[name] = newobj
            block = newobj
        elif entry in TIFF.CZ_LSMINFO_SCANINFO_STRUCTS:
            blocks.append(block)
            newobj = {}
            block.append(newobj)
            block = newobj
        elif entry in TIFF.CZ_LSMINFO_SCANINFO_ATTRIBUTES:
            name = TIFF.CZ_LSMINFO_SCANINFO_ATTRIBUTES[entry]
            block[name] = value
        elif entry == 4294967295:
            block = blocks.pop()
        else:
            block['Entry0x%x' % entry] = value
        if not blocks:
            break
    return block

def read_sis_ini(fh, byteorder, dtype, count, offsetsize):
    """Read OlympusSIS INI string and return as dict."""
    inistr = fh.read(count)
    inistr = bytes2str(stripnull(inistr))
    try:
        return olympusini_metadata(inistr)
    except Exception as exc:
        log.warning('olympusini_metadata: %s: %s', exc.__class__.__name__, exc)
        return {}

def read_tvips_header(fh, byteorder, dtype, count, offsetsize):
    """Read TVIPS EM-MENU headers and return as dict."""
    result = {}
    header = fh.read_record(TIFF.TVIPS_HEADER_V1, byteorder=byteorder)
    for name, typestr in TIFF.TVIPS_HEADER_V1:
        result[name] = header[name].tolist()
    if header['Version'] == 2:
        header = fh.read_record(TIFF.TVIPS_HEADER_V2, byteorder=byteorder)
        if header['Magic'] != int(2863311530):
            log.warning('read_tvips_header: invalid TVIPS v2 magic number')
            return {}
        for name, typestr in TIFF.TVIPS_HEADER_V2:
            if typestr.startswith('V'):
                s = header[name].tostring().decode('utf16', errors='ignore')
                result[name] = stripnull(s, null='\x00')
            else:
                result[name] = header[name].tolist()
        for axis in 'XY':
            header['PhysicalPixelSize' + axis] /= 1000000000.0
            header['PixelSize' + axis] /= 1000000000.0
    elif header.version != 1:
        log.warning('read_tvips_header: unknown TVIPS header version')
        return {}
    return result

def read_fei_metadata(fh, byteorder, dtype, count, offsetsize):
    """Read FEI SFEG/HELIOS headers and return as dict."""
    result = {}
    section = {}
    data = bytes2str(stripnull(fh.read(count)))
    for line in data.splitlines():
        line = line.strip()
        if line.startswith('['):
            section = {}
            result[line[1:-1]] = section
            continue
        try:
            key, value = line.split('=')
        except ValueError:
            continue
        section[key] = astype(value)
    return result

def read_scanimage_metadata(fh):
    """Read ScanImage BigTIFF v3 static and ROI metadata from open file.

    Return non-varying frame data as dict and ROI group data as JSON.

    The settings can be used to read image data and metadata without parsing
    the TIFF file.

    Raise ValueError if file does not contain valid ScanImage v3 metadata."""
    fh.seek(0)
    try:
        byteorder, version = struct.unpack('<2sH', fh.read(4))
        if byteorder != b'II' or version != 43:
            raise Exception
        fh.seek(16)
        magic, version, size0, size1 = struct.unpack('<IIII', fh.read(16))
        if magic != 117637889 or version != 3:
            raise Exception
    except Exception:
        raise ValueError('not a ScanImage BigTIFF v3 file')
    frame_data = matlabstr2py(bytes2str(fh.read(size0)[:-1]))
    roi_data = read_json(fh, '<', None, size1, None) if size1 > 1 else {}
    return (frame_data, roi_data)

def imagej_description_metadata(description):
    """Return metatata from ImageJ image description as dict.

    Raise ValueError if not a valid ImageJ description.

    >>> description = 'ImageJ=1.11a\\nimages=510\\nhyperstack=true\\n'
    >>> imagej_description_metadata(description)  # doctest: +SKIP
    {'ImageJ': '1.11a', 'images': 510, 'hyperstack': True}"""
    def _bool(val):
        return {'true': True, 'false': False}[val.lower()]
    result = {}
    for line in description.splitlines():
        try:
            key, val = line.split('=')
        except Exception:
            continue
        key = key.strip()
        val = val.strip()
        for dtype in (int, float, _bool):
            try:
                val = dtype(val)
                break
            except Exception:
                pass
        result[key] = val
    if 'ImageJ' not in result:
        raise ValueError('not a ImageJ image description')
    return result

def imagej_shape(shape, rgb=None):
    """Return shape normalized to 6D ImageJ hyperstack TZCYXS.

    Raise ValueError if not a valid ImageJ hyperstack shape.

    >>> imagej_shape((2, 3, 4, 5, 3), False)
    (2, 3, 4, 5, 3, 1)"""
    shape = tuple((int(i) for i in shape))
    ndim = len(shape)
    if 1 > ndim > 6:
        raise ValueError('invalid ImageJ hyperstack: not 2 to 6 dimensional')
    if rgb is None:
        rgb = shape[-1] in (3, 4) and ndim > 2
    if rgb and shape[-1] not in (3, 4):
        raise ValueError('invalid ImageJ hyperstack: not a RGB image')
    if not rgb and ndim == 6 and (shape[-1] != 1):
        raise ValueError('invalid ImageJ hyperstack: not a non-RGB image')
    if rgb or shape[-1] == 1:
        return (1,) * (6 - ndim) + shape
    return (1,) * (5 - ndim) + shape + (1,)

def json_description_metadata(description):
    """Return metatata from JSON formated image description as dict.

    Raise ValuError if description is of unknown format.

    >>> description = '{"shape": [256, 256, 3], "axes": "YXS"}'
    >>> json_description_metadata(description)  # doctest: +SKIP
    {'shape': [256, 256, 3], 'axes': 'YXS'}
    >>> json_description_metadata('shape=(256, 256, 3)')
    {'shape': (256, 256, 3)}"""
    if description[:6] == 'shape=':
        shape = tuple((int(i) for i in description[7:-1].split(',')))
        return dict(shape=shape)
    if description[:1] == '{' and description[-1:] == '}':
        return json.loads(description)
    raise ValueError('invalid JSON image description', description)

def pilatus_description_metadata(description):
    """Return metatata from Pilatus image description as dict.

    Return metadata from Pilatus pixel array detectors by Dectris, created
    by camserver or TVX software.

    >>> pilatus_description_metadata('# Pixel_size 172e-6 m x 172e-6 m')
    {'Pixel_size': (0.000172, 0.000172)}"""
    result = {}
    if not description.startswith('# '):
        return result
    for c in '#:=,()':
        description = description.replace(c, ' ')
    for line in description.split('\n'):
        if line[:2] != '  ':
            continue
        line = line.split()
        name = line[0]
        if line[0] not in TIFF.PILATUS_HEADER:
            try:
                result['DateTime'] = datetime.datetime.strptime(' '.join(line), '%Y-%m-%dT%H %M %S.%f')
            except Exception:
                result[name] = ' '.join(line[1:])
            continue
        indices, dtype = TIFF.PILATUS_HEADER[line[0]]
        if isinstance(indices[0], slice):
            values = line[indices[0]]
        else:
            values = [line[i] for i in indices]
        if dtype is float and values[0] == 'not':
            values = ['NaN']
        values = tuple((dtype(v) for v in values))
        if dtype == str:
            values = ' '.join(values)
        elif len(values) == 1:
            values = values[0]
        result[name] = values
    return result

def stk_description_metadata(description):
    """Return metadata from MetaMorph image description as list of dict.

    The MetaMorph image description format is unspecified. Expect failures."""
    description = description.strip()
    if not description:
        return []
    try:
        description = bytes2str(description)
    except UnicodeDecodeError as exc:
        log.warning('stk_description_metadata: %s: %s', exc.__class__.__name__, exc)
        return []
    result = []
    for plane in description.split('\x00'):
        d = {}
        for line in plane.split('\r\n'):
            line = line.split(':', 1)
            if len(line) > 1:
                name, value = line
                d[name.strip()] = astype(value.strip())
            else:
                value = line[0].strip()
                if value:
                    if '' in d:
                        d[''].append(value)
                    else:
                        d[''] = [value]
        result.append(d)
    return result

def metaseries_description_metadata(description):
    """Return metatata from MetaSeries image description as dict."""
    if not description.startswith('<MetaData>'):
        raise ValueError('invalid MetaSeries image description')
    from xml.etree import cElementTree as etree
    root = etree.fromstring(description)
    types = {'float': float, 'int': int, 'bool': lambda x: asbool(x, 'on', 'off')}
    def parse(root, result):
        for child in root:
            attrib = child.attrib
            if not attrib:
                result[child.tag] = parse(child, {})
                continue
            if 'id' in attrib:
                i = attrib['id']
                t = attrib['type']
                v = attrib['value']
                if t in types:
                    result[i] = types[t](v)
                else:
                    result[i] = v
        return result
    adict = parse(root, {})
    if 'Description' in adict:
        adict['Description'] = adict['Description'].replace('&#13;&#10;', '\n')
    return adict

def scanimage_artist_metadata(artist):
    """Return metatata from ScanImage artist tag as dict."""
    try:
        return json.loads(artist)
    except ValueError as exc:
        log.warning('scanimage_artist_metadata: %s: %s', exc.__class__.__name__, exc)

def delta_encode(data, axis=-1, out=None):
    """Encode Delta."""
    if isinstance(data, (bytes, bytearray)):
        data = numpy.frombuffer(data, dtype='u1')
        diff = numpy.diff(data, axis=0)
        return numpy.insert(diff, 0, data[0]).tobytes()
    dtype = data.dtype
    if dtype.kind == 'f':
        data = data.view('u%i' % dtype.itemsize)
    diff = numpy.diff(data, axis=axis)
    key = [slice(None)] * data.ndim
    key[axis] = 0
    diff = numpy.insert(diff, 0, data[tuple(key)], axis=axis)
    if dtype.kind == 'f':
        return diff.view(dtype)
    return diff

def delta_decode(data, axis=-1, out=None):
    """Decode Delta."""
    if out is not None and (not out.flags.writeable):
        out = None
    if isinstance(data, (bytes, bytearray)):
        data = numpy.frombuffer(data, dtype='u1')
        return numpy.cumsum(data, axis=0, dtype='u1', out=out).tobytes()
    if data.dtype.kind == 'f':
        view = data.view('u%i' % data.dtype.itemsize)
        view = numpy.cumsum(view, axis=axis, dtype=view.dtype)
        return view.view(data.dtype)
    return numpy.cumsum(data, axis=axis, dtype=data.dtype, out=out)

def reorient(image, orientation):
    """Return reoriented view of image array.

    Parameters
    ----------
    image : numpy.ndarray
        Non-squeezed output of asarray() functions.
        Axes -3 and -2 must be image length and width respectively.
    orientation : int or str
        One of TIFF.ORIENTATION names or values."""
    orient = TIFF.ORIENTATION
    orientation = enumarg(orient, orientation)
    if orientation == orient.TOPLEFT:
        return image
    if orientation == orient.TOPRIGHT:
        return image[..., ::-1, :]
    if orientation == orient.BOTLEFT:
        return image[..., ::-1, :, :]
    if orientation == orient.BOTRIGHT:
        return image[..., ::-1, ::-1, :]
    if orientation == orient.LEFTTOP:
        return numpy.swapaxes(image, -3, -2)
    if orientation == orient.RIGHTTOP:
        return numpy.swapaxes(image, -3, -2)[..., ::-1, :]
    if orientation == orient.RIGHTBOT:
        return numpy.swapaxes(image, -3, -2)[..., ::-1, :, :]
    if orientation == orient.LEFTBOT:
        return numpy.swapaxes(image, -3, -2)[..., ::-1, ::-1, :]
    return image

def squeeze_axes(shape, axes, skip=None):
    """Return shape and axes with single-dimensional entries removed.

    Remove unused dimensions unless their axes are listed in 'skip'.

    >>> squeeze_axes((5, 1, 2, 1, 1), 'TZYXC')
    ((5, 2, 1), 'TYX')"""
    if len(shape) != len(axes):
        raise ValueError('dimensions of axes and shape do not match')
    if skip is None:
        skip = 'XY'
    shape, axes = zip(*(i for i in zip(shape, axes) if i[0] > 1 or i[1] in skip))
    return (tuple(shape), ''.join(axes))

def transpose_axes(image, axes, asaxes=None):
    """Return image with its axes permuted to match specified axes.

    A view is returned if possible.

    >>> transpose_axes(numpy.zeros((2, 3, 4, 5)), 'TYXC', asaxes='CTZYX').shape
    (5, 2, 1, 3, 4)"""
    for ax in axes:
        if ax not in asaxes:
            raise ValueError('unknown axis %s' % ax)
    if asaxes is None:
        asaxes = 'CTZYX'
    shape = image.shape
    for ax in reversed(asaxes):
        if ax not in axes:
            axes = ax + axes
            shape = (1,) + shape
    image = image.reshape(shape)
    image = image.transpose([axes.index(ax) for ax in asaxes])
    return image

def clean_offsetscounts(offsets, counts):
    """Return cleaned offsets and byte counts.

    Remove zero offsets and counts.
    Use to sanitize StripOffsets and StripByteCounts tag values."""
    offsets = list(offsets)
    counts = list(counts)
    size = len(offsets)
    if size != len(counts):
        raise ValueError('StripOffsets and StripByteCounts mismatch')
    j = 0
    for i, (o, b) in enumerate(zip(offsets, counts)):
        if b > 0:
            if o > 0:
                if i > j:
                    offsets[j] = o
                    counts[j] = b
                j += 1
                continue
            raise ValueError('invalid offset')
        log.warning('clean_offsetscounts: empty bytecount')
    if size == len(offsets):
        return (offsets, counts)
    if j == 0:
        return ([offsets[0]], [counts[0]])
    return (offsets[:j], counts[:j])

def asbool(value, true=(b'true', u'true'), false=(b'false', u'false')):
    """Return string as bool if possible, else raise TypeError.

    >>> asbool(b' False ')
    False"""
    value = value.strip().lower()
    if value in true:
        return True
    if value in false:
        return False
    raise TypeError()

def astype(value, types=None):
    """Return argument as one of types if possible.

    >>> astype('42')
    42
    >>> astype('3.14')
    3.14
    >>> astype('True')
    True
    >>> astype(b'Neee-Wom')
    'Neee-Wom'"""
    if types is None:
        types = (int, float, asbool, bytes2str)
    for typ in types:
        try:
            return typ(value)
        except (ValueError, AttributeError, TypeError, UnicodeEncodeError):
            pass
    return value

def format_size(size, threshold=1536):
    """Return file size as string from byte size.

    >>> format_size(1234)
    '1234 B'
    >>> format_size(12345678901)
    '11.50 GiB'"""
    if size < threshold:
        return '%i B' % size
    for unit in ('KiB', 'MiB', 'GiB', 'TiB', 'PiB'):
        size /= 1024.0
        if size < threshold:
            return '%.2f %s' % (size, unit)
    return 'ginormous'

def natural_sorted(iterable):
    """Return human sorted list of strings.

    E.g. for sorting file names.

    >>> natural_sorted(['f1', 'f2', 'f10'])
    ['f1', 'f2', 'f10']"""
    def sortkey(x):
        return [int(c) if c.isdigit() else c for c in re.split(numbers, x)]
    numbers = re.compile('(\\d+)')
    return sorted(iterable, key=sortkey)

def excel_datetime(timestamp, epoch=None):
    """Return datetime object from timestamp in Excel serial format.

    Convert LSM time stamps.

    >>> excel_datetime(40237.029999999795)
    datetime.datetime(2010, 2, 28, 0, 43, 11, 999982)"""
    if epoch is None:
        epoch = datetime.datetime.fromordinal(693594)
    return epoch + datetime.timedelta(timestamp)

def byteorder_isnative(byteorder):
    """Return if byteorder matches the system's byteorder.

    >>> byteorder_isnative('=')
    True"""
    if byteorder in ('=', sys.byteorder):
        return True
    keys = {'big': '>', 'little': '<'}
    return keys.get(byteorder, byteorder) == keys[sys.byteorder]

def recarray2dict(recarray):
    """Return numpy.recarray as dict."""
    result = {}
    for descr, value in zip(recarray.dtype.descr, recarray):
        name, dtype = descr[:2]
        if dtype[1] == 'S':
            value = bytes2str(stripnull(value))
        elif value.ndim < 2:
            value = value.tolist()
        result[name] = value
    return result

def xml2dict(xml, sanitize=True, prefix=None):
    """Return XML as dict.

    >>> xml2dict('<?xml version="1.0" ?><root attr="name"><key>1</key></root>')
    {'root': {'key': 1, 'attr': 'name'}}"""
    from xml.etree import cElementTree as etree
    at = tx = ''
    if prefix:
        at, tx = prefix
    def astype(value):
        for t in (int, float, asbool):
            try:
                return t(value)
            except Exception:
                pass
        return value
    def etree2dict(t):
        key = t.tag
        if sanitize:
            key = key.rsplit('}', 1)[-1]
        d = {key: {} if t.attrib else None}
        children = list(t)
        if children:
            dd = collections.defaultdict(list)
            for dc in map(etree2dict, children):
                for k, v in dc.items():
                    dd[k].append(astype(v))
            d = {key: {k: astype(v[0]) if len(v) == 1 else astype(v) for k, v in dd.items()}}
        if t.attrib:
            d[key].update(((at + k, astype(v)) for k, v in t.attrib.items()))
        if t.text:
            text = t.text.strip()
            if children or t.attrib:
                if text:
                    d[key][tx + 'value'] = astype(text)
            else:
                d[key] = astype(text)
        return d
    return etree2dict(etree.fromstring(xml))

def isprintable(string):
    """Return if all characters in string are printable.

    >>> isprintable('abc')
    True
    >>> isprintable(b'\x01')
    False"""
    string = string.strip()
    if not string:
        return True
    if sys.version_info[0] == 3:
        try:
            return string.isprintable()
        except Exception:
            pass
        try:
            return string.decode('utf-8').isprintable()
        except Exception:
            pass
    else:
        if string.isalnum():
            return True
        printable = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ!"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~ \t\n\r\x0b\x0c'
        return all((c in printable for c in string))

def clean_whitespace(string, compact=False):
    """Return string with compressed whitespace."""
    for a, b in (('\r\n', '\n'), ('\r', '\n'), ('\n\n', '\n'), ('\t', ' '), ('  ', ' ')):
        string = string.replace(a, b)
    if compact:
        for a, b in (('\n', ' '), ('[ ', '['), ('  ', ' '), ('  ', ' '), ('  ', ' ')):
            string = string.replace(a, b)
    return string.strip()

def pformat_xml(xml):
    """Return pretty formatted XML."""
    try:
        from lxml import etree
        if not isinstance(xml, bytes):
            xml = xml.encode('utf-8')
        xml = etree.parse(io.BytesIO(xml))
        xml = etree.tostring(xml, pretty_print=True, xml_declaration=True, encoding=xml.docinfo.encoding)
        xml = bytes2str(xml)
    except Exception:
        if isinstance(xml, bytes):
            xml = bytes2str(xml)
        xml = xml.replace('><', '>\n<')
    return xml.replace('  ', ' ').replace('\t', ' ')

def pformat(arg, width=79, height=24, compact=True):
    """Return pretty formatted representation of object as string.

    Whitespace might be altered."""
    if height is None or height < 1:
        height = 1024
    if width is None or width < 1:
        width = 256
    npopt = numpy.get_printoptions()
    numpy.set_printoptions(threshold=100, linewidth=width)
    if isinstance(arg, basestring):
        if arg[:5].lower() in ('<?xml', b'<?xml'):
            if isinstance(arg, bytes):
                arg = bytes2str(arg)
            if height == 1:
                arg = arg[:4 * width]
            else:
                arg = pformat_xml(arg)
        elif isinstance(arg, bytes):
            if isprintable(arg):
                arg = bytes2str(arg)
                arg = clean_whitespace(arg)
            else:
                numpy.set_printoptions(**npopt)
                return hexdump(arg, width=width, height=height, modulo=1)
        arg = arg.rstrip()
    elif isinstance(arg, numpy.record):
        arg = arg.pprint()
    else:
        import pprint
        compact = {} if sys.version_info[0] == 2 else dict(compact=compact)
        arg = pprint.pformat(arg, width=width, **compact)
    numpy.set_printoptions(**npopt)
    if height == 1:
        arg = clean_whitespace(arg, compact=True)
        return arg[:width]
    argl = list(arg.splitlines())
    if len(argl) > height:
        arg = '\n'.join(argl[:height // 2] + ['...'] + argl[-height // 2:])
    return arg

def enumarg(enum, arg):
    """Return enum member from its name or value.

    >>> enumarg(TIFF.PHOTOMETRIC, 2)
    <PHOTOMETRIC.RGB: 2>
    >>> enumarg(TIFF.PHOTOMETRIC, 'RGB')
    <PHOTOMETRIC.RGB: 2>"""
    try:
        return enum(arg)
    except Exception:
        try:
            return enum[arg.upper()]
        except Exception:
            raise ValueError('invalid argument %s' % arg)

def parse_kwargs(kwargs, *keys, **keyvalues):
    """Return dict with keys from keys|keyvals and values from kwargs|keyvals.

    Existing keys are deleted from kwargs.

    >>> kwargs = {'one': 1, 'two': 2, 'four': 4}
    >>> kwargs2 = parse_kwargs(kwargs, 'two', 'three', four=None, five=5)
    >>> kwargs == {'one': 1}
    True
    >>> kwargs2 == {'two': 2, 'four': 4, 'five': 5}
    True"""
    result = {}
    for key in keys:
        if key in kwargs:
            result[key] = kwargs[key]
            del kwargs[key]
    for key, value in keyvalues.items():
        if key in kwargs:
            result[key] = kwargs[key]
            del kwargs[key]
        else:
            result[key] = value
    return result

def update_kwargs(kwargs, **keyvalues):
    """Update dict with keys and values if keys do not already exist.

    >>> kwargs = {'one': 1, }
    >>> update_kwargs(kwargs, one=None, two=2)
    >>> kwargs == {'one': 1, 'two': 2}
    True"""
    for key, value in keyvalues.items():
        if key not in kwargs:
            kwargs[key] = value

def validate_jhove(filename, jhove=None, ignore=None):
    """Validate TIFF file using jhove -m TIFF-hul.

    Raise ValueError if jhove outputs an error message unless the message
    contains one of the strings in 'ignore'.

    JHOVE does not support bigtiff or more than 50 IFDs.

    See `JHOVE TIFF-hul Module <http://jhove.sourceforge.net/tiff-hul.html>`_"""
    import subprocess
    if ignore is None:
        ignore = ['More than 50 IFDs']
    if jhove is None:
        jhove = 'jhove'
    out = subprocess.check_output([jhove, filename, '-m', 'TIFF-hul'])
    if b'ErrorMessage: ' in out:
        for line in out.splitlines():
            line = line.strip()
            if line.startswith(b'ErrorMessage: '):
                error = line[14:].decode('utf8')
                for i in ignore:
                    if i in error:
                        break
                else:
                    raise ValueError(error)
                break

def l_sa_check(template, literal, is_standalone):
    """Do a preliminary check to see if a tag could be a standalone"""
    if literal.find('\n') != -1 or is_standalone:
        padding = literal.split('\n')[-1]
        if padding.isspace() or padding == '':
            return True
        else:
            return False

def r_sa_check(template, tag_type, is_standalone):
    """Do a final checkto see if a tag could be a standalone"""
    if is_standalone and tag_type not in ['variable', 'no escape']:
        on_newline = template.split('\n', 1)
        if on_newline[0].isspace() or not on_newline[0]:
            return True
        else:
            return False
    else:
        return False

def parse_tag(template, l_del, r_del):
    """Parse a tag from a template"""
    global _CURRENT_LINE
    global _LAST_TAG_LINE
    tag_types = {'!': 'comment', '#': 'section', '^': 'inverted section', '/': 'end', '>': 'partial', '=': 'set delimiter?', '{': 'no escape?', '&': 'no escape'}
    try:
        tag, template = template.split(r_del, 1)
    except ValueError:
        raise ChevronError('unclosed tag at line {0}'.format(_CURRENT_LINE))
    tag_type = tag_types.get(tag[0], 'variable')
    if tag_type != 'variable':
        tag = tag[1:]
    if tag_type == 'set delimiter?':
        if tag.endswith('='):
            tag_type = 'set delimiter'
            tag = tag[:-1]
        else:
            raise ChevronError('unclosed set delimiter tag\nat line {0}'.format(_CURRENT_LINE))
    elif tag_type == 'no escape?':
        if l_del == '{{' and r_del == '}}' and template.startswith('}'):
            template = template[1:]
            tag_type = 'no escape'
    return ((tag_type, tag.strip()), template)

def _html_escape(string):
    """HTML escape all of these " & < >"""
    html_codes = {'"': '&quot;', '<': '&lt;', '>': '&gt;'}
    string = string.replace('&', '&amp;')
    for char in html_codes:
        string = string.replace(char, html_codes[char])
    return string

def _get_key(key, scopes):
    """Get a key from the current scope"""
    if key == '.':
        return scopes[0]
    for scope in scopes:
        try:
            for child in key.split('.'):
                try:
                    scope = scope[child]
                except (TypeError, AttributeError):
                    try:
                        scope = scope.__dict__[child]
                    except (TypeError, AttributeError):
                        scope = scope[int(child)]
            if scope is 0:
                return 0
            if scope is False:
                return False
            try:
                if scope._CHEVRON_return_scope_when_falsy:
                    return scope
            except AttributeError:
                return scope or ''
        except (AttributeError, KeyError, IndexError, ValueError):
            pass
    return ''

def _get_partial(name, partials_dict, partials_path, partials_ext):
    """Load a partial"""
    try:
        return partials_dict[name]
    except KeyError:
        try:
            path_ext = '.' + partials_ext if partials_ext else ''
            path = partials_path + '/' + name + path_ext
            with io.open(path, 'r', encoding='utf-8') as partial:
                return partial.read()
        except IOError:
            return ''

def boolean_operator_query(boolean_operator):
    """Generate boolean operator checking function."""
    def _boolean_operator_query(expressions):
        """Apply boolean operator to expressions."""
        def _apply_boolean_operator(query_function, expressions=expressions):
            """Return if expressions with boolean operator are satisfied."""
            compiled_expressions = [compile_query(e) for e in expressions]
            return reduce(boolean_operator, [e(query_function) for e in compiled_expressions])
        return _apply_boolean_operator
    return _boolean_operator_query

def filter_query(key, expression):
    """Filter documents with a key that satisfies an expression."""
    if isinstance(expression, dict) and len(expression) == 1 and list(expression.keys())[0].startswith('$'):
        compiled_expression = compile_query(expression)
    elif callable(expression):
        def _filter(index, expression=expression):
            result = [store_key for value, store_keys in index.get_index().items() if expression(value) for store_key in store_keys]
            return result
        compiled_expression = _filter
    else:
        compiled_expression = expression
    def _get(query_function, key=key, expression=compiled_expression):
        """Get document key and check against expression."""
        return query_function(key, expression)
    return _get

def comparison_operator_query(comparison_operator):
    """Generate comparison operator checking function."""
    def _comparison_operator_query(expression):
        """Apply binary operator to expression."""
        def _apply_comparison_operator(index, expression=expression):
            """Return store key for documents that satisfy expression."""
            ev = expression() if callable(expression) else expression
            return [store_key for value, store_keys in index.get_index().items() if comparison_operator(value, ev) for store_key in store_keys]
        return _apply_comparison_operator
    return _comparison_operator_query

def exists_query(expression):
    """Check that documents have a key that satisfies expression."""
    def _exists(index, expression=expression):
        """Return store key for documents that satisfy expression."""
        ev = expression() if callable(expression) else expression
        if ev:
            return [store_key for store_keys in index.get_index().values() for store_key in store_keys]
        else:
            return index.get_undefined_keys()
    return _exists

def all_query(expression):
    """Match arrays that contain all elements in the query."""
    def _all(index, expression=expression):
        """Return store key for documents that satisfy expression."""
        ev = expression() if callable(expression) else expression
        try:
            iter(ev)
        except TypeError:
            raise AttributeError('$all argument must be an iterable!')
        hashed_ev = [index.get_hash_for(v) for v in ev]
        store_keys = set()
        if len(hashed_ev) == 0:
            return []
        store_keys = set(index.get_keys_for(hashed_ev[0]))
        for value in hashed_ev[1:]:
            store_keys &= set(index.get_keys_for(value))
        return list(store_keys)
    return _all

def in_query(expression):
    """Match any of the values that exist in an array specified in query."""
    def _in(index, expression=expression):
        """Return store key for documents that satisfy expression."""
        ev = expression() if callable(expression) else expression
        try:
            iter(ev)
        except TypeError:
            raise AttributeError('$in argument must be an iterable!')
        hashed_ev = [index.get_hash_for(v) for v in ev]
        store_keys = set()
        for value in hashed_ev:
            store_keys |= set(index.get_keys_for(value))
        return list(store_keys)
    return _in

def compile_query(query):
    """Compile each expression in query recursively."""
    if isinstance(query, dict):
        expressions = []
        for key, value in query.items():
            if key.startswith('$'):
                if key not in query_funcs:
                    raise AttributeError('Invalid operator: {}'.format(key))
                expressions.append(query_funcs[key](value))
            else:
                expressions.append(filter_query(key, value))
        if len(expressions) > 1:
            return boolean_operator_query(operator.and_)(expressions)
        else:
            return expressions[0] if len(expressions) else lambda query_function: query_function(None, None)
    else:
        return query

def construct_url(ip_address: str) -> str:
    """Construct the URL with a given IP address."""
    if 'http://' not in ip_address and 'https://' not in ip_address:
        ip_address = '{}{}'.format('http://', ip_address)
    if ip_address[-1] == '/':
        ip_address = ip_address[:-1]
    return ip_address

def pdb_run(func: Callable, *args: Any, **kwargs: Any) -> None:
    """Calls ``func(*args, **kwargs)``; if it raises an exception, break into
    the ``pdb`` debugger."""
    try:
        func(*args, **kwargs)
    except:
        type_, value, tb = sys.exc_info()
        traceback.print_exc()
        pdb.post_mortem(tb)

def cxxRecordDecl(*args):
    """Matches C++ class declarations.

    >>> from glud import *
    >>> config = '''
    ...  class W;
    ...  template<typename T> class X {};
    ...  struct Y {};
    ...  union Z {};
    ... '''
    >>> m = cxxRecordDecl()
    >>> for c in walk(m, parse_string(config).cursor):
    ...     print(c.spelling)
    W
    X"""
    kinds = [CursorKind.CLASS_DECL, CursorKind.CLASS_TEMPLATE]
    inner = [PredMatcher(is_kind(k)) for k in kinds]
    return allOf(anyOf(*inner), *args)

def recordDecl(*args):
    """Matches class, struct, and union declarations.

    >>> from glud import *
    >>> config = '''
    ...  class W;
    ...  template<typename T> class X {};
    ...  struct Y {};
    ...  union Z {};
    ... '''
    >>> m = recordDecl()
    >>> for c in walk(m, parse_string(config).cursor):
    ...     print(c.spelling)
    W
    X
    Y
    Z"""
    kinds = [CursorKind.STRUCT_DECL, CursorKind.UNION_DECL, CursorKind.CLASS_DECL, CursorKind.CLASS_TEMPLATE]
    inner = [PredMatcher(is_kind(k)) for k in kinds]
    return allOf(anyOf(*inner), *args)

def convert_to_bool(x: Any, default: bool=None) -> bool:
    """Transforms its input to a ``bool`` (or returns ``default`` if ``x`` is
    falsy but not itself a boolean). Accepts various common string versions."""
    if isinstance(x, bool):
        return x
    if not x:
        return default
    try:
        return int(x) != 0
    except (TypeError, ValueError):
        pass
    try:
        return float(x) != 0
    except (TypeError, ValueError):
        pass
    if not isinstance(x, str):
        raise Exception('Unknown thing being converted to bool: {!r}'.format(x))
    x = x.upper()
    if x in ['Y', 'YES', 'T', 'TRUE']:
        return True
    if x in ['N', 'NO', 'F', 'FALSE']:
        return False
    raise Exception('Unknown thing being converted to bool: {!r}'.format(x))

def convert_attrs_to_bool(obj: Any, attrs: Iterable[str], default: bool=None) -> None:
    """Applies :func:`convert_to_bool` to the specified attributes of an object,
    modifying it in place."""
    for a in attrs:
        setattr(obj, a, convert_to_bool(getattr(obj, a), default=default))

def convert_attrs_to_uppercase(obj: Any, attrs: Iterable[str]) -> None:
    """Converts the specified attributes of an object to upper case, modifying
    the object in place."""
    for a in attrs:
        value = getattr(obj, a)
        if value is None:
            continue
        setattr(obj, a, value.upper())

def convert_attrs_to_lowercase(obj: Any, attrs: Iterable[str]) -> None:
    """Converts the specified attributes of an object to lower case, modifying
    the object in place."""
    for a in attrs:
        value = getattr(obj, a)
        if value is None:
            continue
        setattr(obj, a, value.lower())

def convert_attrs_to_int(obj: Any, attrs: Iterable[str], default: int=None) -> None:
    """Applies :func:`convert_to_int` to the specified attributes of an object,
    modifying it in place."""
    for a in attrs:
        value = convert_to_int(getattr(obj, a), default=default)
        setattr(obj, a, value)

def environ_setting(name, default=None, required=True):
    """Fetch setting from the environment. The bahavior of the setting if it
    is not in environment is as follows:

        1. If it is required and the default is None, raise Exception
        2. If it is requried and a default exists, return default
        3. If it is not required and default is None, return  None
        4. If it is not required and default exists, return default"""
    if name not in os.environ and default is None:
        message = 'The {0} ENVVAR is not set.'.format(name)
        if required:
            raise ImproperlyConfigured(message)
        else:
            warnings.warn(ConfigurationMissing(message))
    return os.environ.get(name, default)

def formatdt(date: datetime.date, include_time: bool=True) -> str:
    """Formats a ``datetime.date`` to ISO-8601 basic format, to minute accuracy
    with no timezone (or, if ``include_time`` is ``False``, omit the time)."""
    if include_time:
        return date.strftime('%Y-%m-%dT%H:%M')
    else:
        return date.strftime('%Y-%m-%d')

def convert_duration(duration: datetime.timedelta, units: str) -> Optional[float]:
    """Convert a ``datetime.timedelta`` object -- a duration -- into other
    units. Possible units:

        ``s``, ``sec``, ``seconds``
        ``m``, ``min``, ``minutes``
        ``h``, ``hr``, ``hours``
        ``d``, ``days``
        ``w``, ``weeks``
        ``y``, ``years``"""
    if duration is None:
        return None
    s = duration.total_seconds()
    if units in ['s', 'sec', 'seconds']:
        return s
    if units in ['m', 'min', 'minutes']:
        return s / SECONDS_PER_MINUTE
    if units in ['h', 'hr', 'hours']:
        return s / SECONDS_PER_HOUR
    if units in ['d', 'days']:
        return s / SECONDS_PER_DAY
    if units in ['w', 'weeks']:
        return s / SECONDS_PER_WEEK
    if units in ['y', 'years']:
        return s / SECONDS_PER_YEAR
    raise ValueError('Unknown units: {}'.format(units))

def repr_parameter(param: inspect.Parameter) -> str:
    """Provides a ``repr``-style representation of a function parameter."""
    return 'Parameter(name={name}, annotation={annotation}, kind={kind}, default={default}'.format(name=param.name, annotation=param.annotation, kind=param.kind, default=param.default)

def gpg_version():
    """Returns the GPG version"""
    cmd = flatten([gnupg_bin(), '--version'])
    output = stderr_output(cmd)
    output = output.split('\n')[0].split(' ')[2].split('.')
    return tuple([int(x) for x in output])

def polite_string(a_string):
    """Returns a "proper" string that should work in both Py3/Py2"""
    if is_py3() and hasattr(a_string, 'decode'):
        try:
            return a_string.decode('utf-8')
        except UnicodeDecodeError:
            return a_string
    return a_string

def actually_flatten(iterable):
    """Flatten iterables
    This is super ugly. There must be a cleaner py2/3 way
    of handling this."""
    remainder = iter(iterable)
    while True:
        first = next(remainder)
        is_iter = isinstance(first, collections.Iterable)
        try:
            basestring
        except NameError:
            basestring = str
        if is_py3() and is_iter and not_a_string(first):
            remainder = IT.chain(first, remainder)
        elif not is_py3() and is_iter and (not isinstance(first, basestring)):
            remainder = IT.chain(first, remainder)
        else:
            yield polite_string(first)

def gnupg_home():
    """Returns appropriate arguments if GNUPGHOME is set"""
    if 'GNUPGHOME' in os.environ:
        gnupghome = os.environ['GNUPGHOME']
        if not os.path.isdir(gnupghome):
            raise CryptoritoError('Invalid GNUPGHOME directory')
        return ['--homedir', gnupghome]
    else:
        return []

def fingerprint_from_keybase(fingerprint, kb_obj):
    """Extracts a key matching a specific fingerprint from a
    Keybase API response"""
    if 'public_keys' in kb_obj and 'pgp_public_keys' in kb_obj['public_keys']:
        for key in kb_obj['public_keys']['pgp_public_keys']:
            keyprint = fingerprint_from_var(key).lower()
            fingerprint = fingerprint.lower()
            if fingerprint == keyprint or keyprint.startswith(fingerprint) or keyprint.endswith(fingerprint):
                return {'fingerprint': keyprint, 'bundle': key}
    return None

def key_from_keybase(username, fingerprint=None):
    """Look up a public key from a username"""
    url = keybase_lookup_url(username)
    resp = requests.get(url)
    if resp.status_code == 200:
        j_resp = json.loads(polite_string(resp.content))
        if 'them' in j_resp and len(j_resp['them']) == 1:
            kb_obj = j_resp['them'][0]
            if fingerprint:
                return fingerprint_from_keybase(fingerprint, kb_obj)
            elif 'public_keys' in kb_obj and 'pgp_public_keys' in kb_obj['public_keys']:
                key = kb_obj['public_keys']['primary']
                return massage_key(key)
    return None

def fingerprint_from_var(var):
    """Extract a fingerprint from a GPG public key"""
    vsn = gpg_version()
    cmd = flatten([gnupg_bin(), gnupg_home()])
    if vsn[0] >= 2 and vsn[1] < 1:
        cmd.append('--with-fingerprint')
    output = polite_string(stderr_with_input(cmd, var)).split('\n')
    if not output[0].startswith('pub'):
        raise CryptoritoError('probably an invalid gpg key')
    if vsn[0] >= 2 and vsn[1] < 1:
        return output[1].split('=')[1].replace(' ', '')
    return output[1].strip()

def fingerprint_from_file(filename):
    """Extract a fingerprint from a GPG public key file"""
    cmd = flatten([gnupg_bin(), gnupg_home(), filename])
    outp = stderr_output(cmd).split('\n')
    if not outp[0].startswith('pub'):
        raise CryptoritoError('probably an invalid gpg key')
    return outp[1].strip()

def stderr_handle():
    """Generate debug-level appropriate stderr context for
    executing things through subprocess. Normally stderr gets
    sent to dev/null but when debugging it is sent to stdout."""
    gpg_stderr = None
    handle = None
    if LOGGER.getEffectiveLevel() > logging.DEBUG:
        handle = open(os.devnull, 'wb')
        gpg_stderr = handle
    return (handle, gpg_stderr)

def stderr_output(cmd):
    """Wraps the execution of check_output in a way that
    ignores stderr when not in debug mode"""
    handle, gpg_stderr = stderr_handle()
    try:
        output = subprocess.check_output(cmd, stderr=gpg_stderr)
        if handle:
            handle.close()
        return str(polite_string(output))
    except subprocess.CalledProcessError as exception:
        LOGGER.debug('GPG Command %s', ' '.join(exception.cmd))
        LOGGER.debug('GPG Output %s', exception.output)
        raise CryptoritoError('GPG Execution')

def stderr_with_input(cmd, stdin):
    """Runs a command, passing something in stdin, and returning
    whatever came out from stdout"""
    handle, gpg_stderr = stderr_handle()
    LOGGER.debug('GPG command %s', ' '.join(cmd))
    try:
        gpg_proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stdin=subprocess.PIPE, stderr=gpg_stderr)
        output, _err = gpg_proc.communicate(polite_bytes(stdin))
        if handle:
            handle.close()
        return output
    except subprocess.CalledProcessError as exception:
        return gpg_error(exception, 'GPG variable encryption error')
    except OSError as exception:
        raise CryptoritoError('File %s not found' % exception.filename)

def export_gpg_key(key):
    """Exports a GPG key and returns it"""
    cmd = flatten([gnupg_bin(), gnupg_verbose(), gnupg_home(), '--export', key])
    handle, gpg_stderr = stderr_handle()
    try:
        gpg_proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=gpg_stderr)
        output, _err = gpg_proc.communicate()
        if handle:
            handle.close()
        return portable_b64encode(output)
    except subprocess.CalledProcessError as exception:
        LOGGER.debug('GPG Command %s', ' '.join(exception.cmd))
        LOGGER.debug('GPG Output %s', exception.output)
        raise CryptoritoError('GPG encryption error')

def decrypt_var(source, passphrase=None):
    """Attempts to decrypt a variable"""
    cmd = [gnupg_bin(), '--decrypt', gnupg_home(), gnupg_verbose(), passphrase_file(passphrase)]
    return stderr_with_input(flatten(cmd), source)

def decrypt(source, dest=None, passphrase=None):
    """Attempts to decrypt a file"""
    if not os.path.exists(source):
        raise CryptoritoError('Encrypted file %s not found' % source)
    cmd = [gnupg_bin(), gnupg_verbose(), '--decrypt', gnupg_home(), passphrase_file(passphrase)]
    if dest:
        cmd.append(['--output', dest])
    cmd.append([source])
    stderr_output(flatten(cmd))
    return True

def is_base64(string):
    """Determines whether or not a string is likely to
    be base64 encoded binary nonsense"""
    return not re.match('^[0-9]+$', string) and len(string) % 4 == 0 and re.match('^[A-Za-z0-9+/]+[=]{0,2}$', string)

def portable_b64encode(thing):
    """Wrap b64encode for Python 2 & 3"""
    if is_py3():
        try:
            some_bits = bytes(thing, 'utf-8')
        except TypeError:
            some_bits = thing
        return polite_string(b64encode(some_bits).decode('utf-8'))
    return polite_string(b64encode(thing))

def download_if_not_exists(url: str, filename: str, skip_cert_verify: bool=True, mkdir: bool=True) -> None:
    """Downloads a URL to a file, unless the file already exists."""
    if os.path.isfile(filename):
        log.info('No need to download, already have: {}', filename)
        return
    if mkdir:
        directory, basename = os.path.split(os.path.abspath(filename))
        mkdir_p(directory)
    download(url=url, filename=filename, skip_cert_verify=skip_cert_verify)

def make_copy_paste_env(env: Dict[str, str]) -> str:
    """Convert an environment into a set of commands that can be copied/pasted, on
    the build platform, to recreate that environment."""
    windows = platform.system() == 'Windows'
    cmd = 'set' if windows else 'export'
    return '\n'.join(('{cmd} {k}={v}'.format(cmd=cmd, k=k, v=env[k] if windows else subprocess.list2cmdline([env[k]])) for k in sorted(env.keys())))

def reformat_python_docstrings(top_dirs: List[str], correct_copyright_lines: List[str], show_only: bool=True, rewrite: bool=False, process_only_filenum: int=None) -> None:
    """Walk a directory, finding Python files and rewriting them.

    Args:
        top_dirs: list of directories to descend into
        correct_copyright_lines:
            list of lines (without newlines) representing the copyright
            docstring block, including the transition lines of equals
            symbols
        show_only: show results (to stdout) only; don't rewrite
        rewrite: write the changes
        process_only_filenum: only process this file number (1-based index);
            for debugging only"""
    filenum = 0
    for top_dir in top_dirs:
        for dirpath, dirnames, filenames in walk(top_dir):
            for filename in filenames:
                fullname = join(dirpath, filename)
                extension = splitext(filename)[1]
                if extension != PYTHON_EXTENSION:
                    continue
                filenum += 1
                if process_only_filenum and filenum != process_only_filenum:
                    continue
                log.info('Processing file {}: {}', filenum, fullname)
                proc = PythonProcessor(full_path=fullname, top_dir=top_dir, correct_copyright_lines=correct_copyright_lines)
                if show_only:
                    proc.show()
                elif rewrite:
                    proc.rewrite_file()

def contains_duplicates(values: Iterable[Any]) -> bool:
    """Does the iterable contain any duplicate values?"""
    for v in Counter(values).values():
        if v > 1:
            return True
    return False

def unescape_newlines(s: str) -> str:
    """Reverses :func:`escape_newlines`."""
    if not s:
        return s
    d = ''
    in_escape = False
    for i in range(len(s)):
        c = s[i]
        if in_escape:
            if c == 'r':
                d += '\r'
            elif c == 'n':
                d += '\n'
            else:
                d += c
            in_escape = False
        elif c == '\\':
            in_escape = True
        else:
            d += c
    return d

def _unicode_def_src_to_str(srclist: List[Union[str, int]]) -> str:
    """Used to create :data:`UNICODE_CATEGORY_STRINGS`.

    Args:
        srclist: list of integers or hex range strings like ``"0061-007A"``

    Returns:
        a string with all characters described by ``srclist``: either the
        character corresponding to the integer Unicode character number, or
        all characters corresponding to the inclusive range described"""
    charlist = []
    for src in srclist:
        if isinstance(src, int):
            charlist.append(chr(src))
        else:
            first, last = [int(x, 16) for x in src.split('-')]
            charlist += [chr(x) for x in range(first, last + 1)]
    return ''.join(charlist)

def guess_file_name_stream_type_header(args):
    """Guess filename, file stream, file type, file header from args.

    :param args: may be string (filepath), 2-tuples (filename, fileobj), 3-tuples (filename, fileobj,
    contentype) or 4-tuples (filename, fileobj, contentype, custom_headers).
    :return: filename, file stream, file type, file header"""
    ftype = None
    fheader = None
    if isinstance(args, (tuple, list)):
        if len(args) == 2:
            fname, fstream = args
        elif len(args) == 3:
            fname, fstream, ftype = args
        else:
            fname, fstream, ftype, fheader = args
    else:
        fname, fstream = guess_filename_stream(args)
        ftype = guess_content_type(fname)
    if isinstance(fstream, (str, bytes, bytearray)):
        fdata = fstream
    else:
        fdata = fstream.read()
    return (fname, fdata, ftype, fheader)

def ci(a, which=95, axis=None):
    """Return a percentile range from an array of values."""
    p = (50 - which / 2, 50 + which / 2)
    return percentiles(a, p, axis)

def read_config_multiline_options(obj: Any, parser: ConfigParser, section: str, options: Iterable[str]) -> None:
    """This is to :func:`read_config_string_options` as
    :func:`get_config_multiline_option` is to :func:`get_config_string_option`."""
    for o in options:
        setattr(obj, o, get_config_multiline_option(parser, section, o))

def get_config_parameter(config: ConfigParser, section: str, param: str, fn: Callable[[Any], Any], default: Any) -> Any:
    """Fetch parameter from ``configparser`` ``.INI`` file.

    Args:
        config: :class:`ConfigParser` object
        section: section name within config file
        param: name of parameter within section
        fn: function to apply to string parameter (e.g. ``int``)
        default: default value

    Returns:
        parameter value, or ``None`` if ``default is None``, or ``fn(default)``"""
    try:
        value = fn(config.get(section, param))
    except (TypeError, ValueError, NoOptionError):
        log.warning('Configuration variable {} not found or improper in section [{}]; using default of {!r}', param, section, default)
        if default is None:
            value = default
        else:
            value = fn(default)
    return value

def get_config_parameter_loglevel(config: ConfigParser, section: str, param: str, default: int) -> int:
    """Get ``loglevel`` parameter from ``configparser`` ``.INI`` file, e.g.
    mapping ``'debug'`` to ``logging.DEBUG``.

    Args:
        config: :class:`ConfigParser` object
        section: section name within config file
        param: name of parameter within section
        default: default value
    Returns:
        parameter value, or default"""
    try:
        value = config.get(section, param).lower()
        if value == 'debug':
            return logging.DEBUG
        elif value == 'info':
            return logging.INFO
        elif value in ['warn', 'warning']:
            return logging.WARN
        elif value == 'error':
            return logging.ERROR
        elif value in ['critical', 'fatal']:
            return logging.CRITICAL
        else:
            raise ValueError
    except (TypeError, ValueError, NoOptionError, AttributeError):
        log.warning('Configuration variable {} not found or improper in section [{}]; using default of {!r}', param, section, default)
        return default

def recover_info_from_exception(err: Exception) -> Dict:
    """Retrives the information added to an exception by
    :func:`add_info_to_exception`."""
    if len(err.args) < 1:
        return {}
    info = err.args[-1]
    if not isinstance(info, dict):
        return {}
    return info

def _serialize_function(obj):
    """Still needing this much try-except stuff. We should find a way to get rid of this.
    :param obj:
    :return:"""
    try:
        obj = inspect.getsource(obj)
    except (TypeError, IOError):
        try:
            obj = marshal.dumps(obj)
        except ValueError:
            if hasattr(obj, '__dict__'):
                obj = _serialize_dict(obj.__dict__)
    return obj

def _serialize_module(obj):
    """Tries to serialize a module by its __dict__ attr.
    Remove the builtins attr as this one is not relevant and extremely large.
    If its value is a callable, serialize it using serialize_obj, else, use its repr,
    because in this case we most likely run into max recursion depth errors.
    :param obj:
    :return:"""
    obj = dict(obj.__dict__)
    if '__builtins__' in obj.keys():
        obj.pop('__builtins__')
    for k, v in obj.items():
        if callable(v):
            obj[k] = serialize_obj(v)
        else:
            obj[k] = repr(v)
    return obj

def admin_view_fk_link(modeladmin: ModelAdmin, obj, fkfield: str, missing: str='(None)', use_str: bool=True, view_type: str='change', current_app: str=None) -> str:
    """Get a Django admin site URL for an object that's found from a foreign
    key in our object of interest."""
    if not hasattr(obj, fkfield):
        return missing
    linked_obj = getattr(obj, fkfield)
    app_name = linked_obj._meta.app_label.lower()
    model_name = linked_obj._meta.object_name.lower()
    viewname = 'admin:{}_{}_{}'.format(app_name, model_name, view_type)
    if current_app is None:
        current_app = modeladmin.admin_site.name
    url = reverse(viewname, args=[linked_obj.pk], current_app=current_app)
    if use_str:
        label = escape(str(linked_obj))
    else:
        label = '{} {}'.format(escape(linked_obj._meta.object_name), linked_obj.pk)
    return '<a href="{}">{}</a>'.format(url, label)

def admin_view_reverse_fk_links(modeladmin: ModelAdmin, obj, reverse_fk_set_field: str, missing: str='(None)', use_str: bool=True, separator: str='<br>', view_type: str='change', current_app: str=None) -> str:
    """Get multiple Django admin site URL for multiple objects linked to our
    object of interest (where the other objects have foreign keys to our
    object)."""
    if not hasattr(obj, reverse_fk_set_field):
        return missing
    linked_objs = getattr(obj, reverse_fk_set_field).all()
    if not linked_objs:
        return missing
    first = linked_objs[0]
    app_name = first._meta.app_label.lower()
    model_name = first._meta.object_name.lower()
    viewname = 'admin:{}_{}_{}'.format(app_name, model_name, view_type)
    if current_app is None:
        current_app = modeladmin.admin_site.name
    links = []
    for linked_obj in linked_objs:
        url = reverse(viewname, args=[linked_obj.pk], current_app=current_app)
        if use_str:
            label = escape(str(linked_obj))
        else:
            label = '{} {}'.format(escape(linked_obj._meta.object_name), linked_obj.pk)
        links.append('<a href="{}">{}</a>'.format(url, label))
    return separator.join(links)

def rotation(angle):
    """Rotation about the Z axis (in the XY plane)"""
    return N.array([[N.cos(angle), -N.sin(angle), 0], [N.sin(angle), N.cos(angle), 0], [0, 0, 1]])

def kill_child_processes() -> None:
    """Kills children of this process that were registered in the
    :data:`processes` variable.

    Use with ``@atexit.register``."""
    timeout_sec = 5
    for p in processes:
        try:
            p.wait(timeout_sec)
        except TimeoutExpired:
            p.kill()

def print_lines(process: Popen) -> None:
    """Let a subprocess :func:`communicate`, then write both its ``stdout`` and
    its ``stderr`` to our ``stdout``."""
    out, err = process.communicate()
    if out:
        for line in out.decode('utf-8').splitlines():
            print(line)
    if err:
        for line in err.decode('utf-8').splitlines():
            print(line)

def serialize(pca, **kwargs):
    """Serialize an orientation object to a dict suitable
    for JSON"""
    strike, dip, rake = pca.strike_dip_rake()
    hyp_axes = sampling_axes(pca)
    return dict(**kwargs, principal_axes=pca.axes.tolist(), hyperbolic_axes=hyp_axes.tolist(), n_samples=pca.n, strike=strike, dip=dip, rake=rake, angular_errors=[2 * N.degrees(i) for i in angular_errors(hyp_axes)])

def create_groups(orientations, *groups, **kwargs):
    """Create groups of an orientation measurement dataset"""
    grouped = []
    if kwargs.pop('copy', True):
        orientations = [copy(o) for o in orientations]
    for o in orientations:
        o.member_of = None
        try:
            grouped += o.members
            for a in o.members:
                a.member_of = o
        except AttributeError:
            pass
    def find(uid):
        try:
            val = next((x for x in orientations if x.hash == uid))
            if val in grouped:
                raise GroupedPlaneError('{} is already in a group.'.format(val.hash))
            return val
        except StopIteration:
            raise KeyError('No measurement of with hash {} found'.format(uid))
    for uid_list in groups:
        vals = [find(uid) for uid in uid_list]
        o = GroupedOrientation(*vals, **kwargs)
        orientations.append(o)
    return orientations

def logistic(x: Union[float, np.ndarray], k: float, theta: float) -> Optional[float]:
    """Standard logistic function.

    .. math::

        y = \\frac {1} {1 + e^{-k (x - \\theta)}}

    Args:
        x: :math:`x`
        k: :math:`k`
        theta: :math:`\\theta`

    Returns:
        :math:`y`"""
    if x is None or k is None or theta is None:
        return None
    return 1 / (1 + np.exp(-k * (x - theta)))

def __reverse_ellipse(axes, scalar=1):
    """This method doesn't work as well"""
    ax1 = axes.copy()[::-1] * scalar
    center = ax1[1] * N.sqrt(2) * scalar
    return (ax1, center)

def submit(recaptcha_response_field, secret_key, remoteip, verify_server=VERIFY_SERVER):
    """Submits a reCAPTCHA request for verification. Returns RecaptchaResponse
    for the request

    recaptcha_response_field -- The value from the form
    secret_key -- your reCAPTCHA secret key
    remoteip -- the user's ip address"""
    if not (recaptcha_response_field and len(recaptcha_response_field)):
        return RecaptchaResponse(is_valid=False, error_code='incorrect-captcha-sol')
    def encode_if_necessary(s):
        if isinstance(s, unicode):
            return s.encode('utf-8')
        return s
    params = urllib.urlencode({'secret': encode_if_necessary(secret_key), 'remoteip': encode_if_necessary(remoteip), 'response': encode_if_necessary(recaptcha_response_field)})
    request = Request(url='https://%s/recaptcha/api/siteverify' % verify_server, data=params, headers={'Content-type': 'application/x-www-form-urlencoded', 'User-agent': 'noReCAPTCHA Python'})
    httpresp = urlopen(request)
    return_values = json.loads(httpresp.read())
    httpresp.close()
    return_code = return_values['success']
    error_codes = return_values.get('error-codes', [])
    if return_code:
        return RecaptchaResponse(is_valid=True)
    else:
        return RecaptchaResponse(is_valid=False, error_code=error_codes)

def get_current_revision(database_url: str, version_table: str=DEFAULT_ALEMBIC_VERSION_TABLE) -> str:
    """Ask the database what its current revision is.

    Arguments:
        database_url: SQLAlchemy URL for the database
        version_table: table name for Alembic versions"""
    engine = create_engine(database_url)
    conn = engine.connect()
    opts = {'version_table': version_table}
    mig_context = MigrationContext.configure(conn, opts=opts)
    return mig_context.get_current_revision()

def stamp_allowing_unusual_version_table(config: Config, revision: str, sql: bool=False, tag: str=None, version_table: str=DEFAULT_ALEMBIC_VERSION_TABLE) -> None:
    """Stamps the Alembic version table with the given revision; don't run any
    migrations.

    This function is a clone of ``alembic.command.stamp()``, but allowing
    ``version_table`` to change. See
    http://alembic.zzzcomputing.com/en/latest/api/commands.html#alembic.command.stamp"""
    script = ScriptDirectory.from_config(config)
    starting_rev = None
    if ':' in revision:
        if not sql:
            raise CommandError('Range revision not allowed')
        starting_rev, revision = revision.split(':', 2)
    def do_stamp(rev: str, context):
        return script._stamp_revs(revision, rev)
    with EnvironmentContext(config, script, fn=do_stamp, as_sql=sql, destination_rev=revision, starting_rev=starting_rev, tag=tag, version_table=version_table):
        script.run_env()

def send_http_request_with_json(context, method):
    """Parameters:

        .. code-block:: json

            {
                "param1": "value1",
                "param2": "value2",
                "param3": {
                    "param31": "value31"
                }
            }"""
    safe_add_http_request_context_to_behave_context(context)
    context.http_request_context.body_params = json.loads(context.text)
    context.http_request_context.renderer = JSONRenderer()
    send_http_request(context, method)

def launch_external_file(filename: str, raise_if_fails: bool=False) -> None:
    """Launches a file using the operating system's standard launcher.

    Args:
        filename: file to launch
        raise_if_fails: raise any exceptions from
            ``subprocess.call(["xdg-open", filename])`` (Linux)
            or ``os.startfile(filename)`` (otherwise)? If not, exceptions
            are suppressed."""
    log.info('Launching external file: {!r}', filename)
    try:
        if sys.platform.startswith('linux'):
            cmdargs = ['xdg-open', filename]
            subprocess.call(cmdargs)
        else:
            os.startfile(filename)
    except Exception as e:
        log.critical('Error launching {!r}: error was {}.\n\n{}', filename, str(e), traceback.format_exc())
        if raise_if_fails:
            raise

def make_mysql_url(username: str, password: str, dbname: str, driver: str='mysqldb', host: str='localhost', port: int=3306, charset: str='utf8') -> str:
