def atoi(text: str) -> Union[int, str]:
    """Converts strings to integers if they're composed of digits; otherwise
    returns the strings unchanged. One way of sorting strings with numbers;
    it will mean that ``"11"`` is more than ``"2"``."""
    return int(text) if text.isdigit() else text

def _get_pretty_body(headers, body):
    """Return a pretty printed body using the Content-Type header information.

    :param headers: Headers for the request/response (dict)
    :param body: Body to pretty print (string)
    :return: Body pretty printed (string)"""
    try:
        if CONTENT_TYPE_HEADER_NAME in headers:
            if XMLRenderer.DEFAULT_CONTENT_TYPE == headers[CONTENT_TYPE_HEADER_NAME]:
                xml_parsed = parseString(body)
                pretty_xml_as_string = xml_parsed.toprettyxml()
                return pretty_xml_as_string
            elif JSONRenderer.DEFAULT_CONTENT_TYPE == headers[CONTENT_TYPE_HEADER_NAME]:
                decoded_body = body.decode('utf-8')
                parsed = json.loads(decoded_body)
                return json.dumps(parsed, sort_keys=True, indent=4)
    except:
        pass
    finally:
        return body

def args_kwargs_to_initdict(args: ArgsList, kwargs: KwargsDict) -> InitDict:
    """Converts a set of ``args`` and ``kwargs`` to an ``InitDict``."""
    return {ARGS_LABEL: args, KWARGS_LABEL: kwargs}

def strip_leading_underscores_from_keys(d: Dict) -> Dict:
    """Clones a dictionary, removing leading underscores from key names.
    Raises ``ValueError`` if this causes an attribute conflict."""
    newdict = {}
    for k, v in d.items():
        if k.startswith('_'):
            k = k[1:]
            if k in newdict:
                raise ValueError('Attribute conflict: _{k}, {k}'.format(k=k))
        newdict[k] = v
    return newdict

def verify_initdict(initdict: InitDict) -> None:
    """Ensures that its parameter is a proper ``InitDict``, or raises
    ``ValueError``."""
    if not isinstance(initdict, dict) or ARGS_LABEL not in initdict or KWARGS_LABEL not in initdict:
        raise ValueError('Not an InitDict dictionary')

def wrap_kwargs_to_initdict(init_kwargs_fn: InitKwargsFnType, typename: str, check_result: bool=True) -> InstanceToInitDictFnType:
    """Wraps a function producing a ``KwargsDict``, making it into a function
    producing an ``InitDict``."""
    def wrapper(obj: Instance) -> InitDict:
        result = init_kwargs_fn(obj)
        if check_result:
            if not isinstance(result, dict):
                raise ValueError('Class {} failed to provide a kwargs dict and provided instead: {}'.format(typename, repr(result)))
        return kwargs_to_initdict(init_kwargs_fn(obj))
    return wrapper

def wrap_args_kwargs_to_initdict(init_args_kwargs_fn: InitArgsKwargsFnType, typename: str, check_result: bool=True) -> InstanceToInitDictFnType:
    """Wraps a function producing a ``KwargsDict``, making it into a function
    producing an ``InitDict``."""
    def wrapper(obj: Instance) -> InitDict:
        result = init_args_kwargs_fn(obj)
        if check_result:
            if not isinstance(result, tuple) or not len(result) == 2 or (not isinstance(result[0], list)) or (not isinstance(result[1], dict)):
                raise ValueError('Class {} failed to provide an (args, kwargs) tuple and provided instead: {}'.format(typename, repr(result)))
        return args_kwargs_to_initdict(*result)
    return wrapper

def make_instance_to_initdict(attributes: List[str]) -> InstanceToDictFnType:
    """Returns a function that takes an object (instance) and produces an
    ``InitDict`` enabling its re-creation."""
    def custom_instance_to_initdict(x: Instance) -> InitDict:
        kwargs = {}
        for a in attributes:
            kwargs[a] = getattr(x, a)
        return kwargs_to_initdict(kwargs)
    return custom_instance_to_initdict

def json_class_decoder_hook(d: Dict) -> Any:
    """Provides a JSON decoder that converts dictionaries to Python objects if
    suitable methods are found in our ``TYPE_MAP``."""
    if TYPE_LABEL in d:
        typename = d.get(TYPE_LABEL)
        if typename in TYPE_MAP:
            if DEBUG:
                log.debug('Deserializing: {!r}', d)
            d.pop(TYPE_LABEL)
            descriptor = TYPE_MAP[typename]
            obj = descriptor.to_obj(d)
            if DEBUG:
                log.debug('... to: {!r}', obj)
            return obj
    return d

def json_encode(obj: Instance, **kwargs) -> str:
    """Encodes an object to JSON using our custom encoder.

    The ``**kwargs`` can be used to pass things like ``'indent'``, for
    formatting."""
    return json.dumps(obj, cls=JsonClassEncoder, **kwargs)

def json_decode(s: str) -> Any:
    """Decodes an object from JSON using our custom decoder."""
    try:
        return json.JSONDecoder(object_hook=json_class_decoder_hook).decode(s)
    except json.JSONDecodeError:
        log.warning('Failed to decode JSON (returning None): {!r}', s)
        return None

def dict_to_enum_fn(d: Dict[str, Any], enum_class: Type[Enum]) -> Enum:
    """Converts an ``dict`` to a ``Enum``."""
    return enum_class[d['name']]

def register_enum_for_json(*args, **kwargs) -> Any:
    """Class decorator to register ``Enum``-derived classes with our JSON system.
    See comments/help for ``@register_for_json``, above."""
    if len(args) == 1 and len(kwargs) == 0 and callable(args[0]):
        cls = args[0]
        register_class_for_json(cls, obj_to_dict_fn=enum_to_dict_fn, dict_to_obj_fn=dict_to_enum_fn)
        return cls
    else:
        raise AssertionError('Use as plain @register_enum_for_json, without arguments')

def dict_to_pendulum(d: Dict[str, Any], pendulum_class: ClassType) -> DateTime:
