def simple_eq(one: Instance, two: Instance, attrs: List[str]) -> bool:
    """Test if two objects are equal, based on a comparison of the specified
    attributes ``attrs``."""
    return all((getattr(one, a) == getattr(two, a) for a in attrs))

def smart_open(filename: str, mode: str='Ur', buffering: int=-1, encoding: str=None, errors: str=None, newline: str=None, closefd: bool=True) -> IO:
    """Context manager (for use with ``with``) that opens a filename and provides
    a :class:`IO` object. If the filename is ``'-'``, however, then
    ``sys.stdin`` is used for reading and ``sys.stdout`` is used for writing."""
    if filename == '-':
        if mode is None or mode == '' or 'r' in mode:
            fh = sys.stdin
        else:
            fh = sys.stdout
    else:
        fh = open(filename, mode=mode, buffering=buffering, encoding=encoding, errors=errors, newline=newline, closefd=closefd)
    try:
        yield fh
    finally:
        if filename is not '-':
            fh.close()

def gen_lines_from_textfiles(files: Iterable[TextIO]) -> Generator[str, None, None]:
    """Generates lines from file-like objects.

    Args:
        files: iterable of :class:`TextIO` objects

    Yields:
        each line of all the files"""
    for file in files:
        for line in file:
            yield line

def to_key_val_list(value, sort=False, insensitive=False):
    """Take an object and test to see if it can be represented as a
    dictionary. If it can be, return a list of tuples, e.g.,
    ::
        >>> to_key_val_list([('key', 'val')])
        [('key', 'val')]
        >>> to_key_val_list({'key': 'val'})
        [('key', 'val')]
        >>> to_key_val_list({'key': 'val'}, sort=True)
        [('key', 'val')]
        >>> to_key_val_list('string')
        ValueError: cannot encode objects that are not 2-tuples."""
    if value is None:
        return None
    if isinstance(value, (str, bytes, bool, int)):
        raise ValueError('cannot encode objects that are not 2-tuples')
    if isinstance(value, collections.Mapping):
        value = value.items()
    if sort and (not insensitive):
        values = sorted(value)
    elif sort:
        values = sorted(value, key=lambda t: t[0].lower())
    else:
        values = value
    return list(values)

def to_key_val_dict(values):
    """Take an object and test to see if it can be represented as a
    dictionary. If it can be, return a list of tuples, e.g.,
    ::
        >>> to_key_val_dict([('key', 'val')])
        {'key': 'val'}
        >>> to_key_val_dict({'key': 'val'})
        {'key': 'val'}
        >>> to_key_val_dict('string')
        ValueError: dictionary update sequence element."""
    if values is None:
        return {}
    if isinstance(values, (str, bytes, bool, int)):
        raise ValueError('cannot encode objects that are not 2-tuples')
    if isinstance(values, collections.Mapping):
        values = values.items()
    dict_to_return = dict()
    for k, v in values:
        if k in dict_to_return and isinstance(dict_to_return[k], list) and isinstance(v, list):
            dict_to_return[k].extend(v)
        elif k in dict_to_return and isinstance(dict_to_return[k], list):
            dict_to_return[k].append(v)
        elif k in dict_to_return:
            dict_to_return[k] = [dict_to_return[k], v]
        else:
            dict_to_return[k] = v
    return dict_to_return

def choice_explanation(value: str, choices: Iterable[Tuple[str, str]]) -> str:
    """Returns the explanation associated with a Django choice tuple-list."""
    for k, v in choices:
        if k == value:
            return v
    return ''

def sql_comment(comment: str) -> str:
    """Transforms a single- or multi-line string into an ANSI SQL comment,
    prefixed by ``--``."""
    'Using -- as a comment marker is ANSI SQL.'
    if not comment:
        return ''
    return '\n'.join(('-- {}'.format(x) for x in comment.splitlines()))

def sql_dequote_string(s: str) -> str:
    """Reverses :func:`sql_quote_string`."""
    if len(s) < 2 or s[0] != SQUOTE or s[-1] != SQUOTE:
        raise ValueError('Not an SQL string literal')
    s = s[1:-1]
    return s.replace(DOUBLE_SQUOTE, SQUOTE)

def get_case_insensitive_dict_key(d: Dict, k: str) -> Optional[str]:
    """Within the dictionary ``d``, find a key that matches (in case-insensitive
    fashion) the key ``k``, and return it (or ``None`` if there isn't one)."""
    for key in d.keys():
        if k.lower() == key.lower():
            return key
    return None

def rename_key(d: Dict[str, Any], old: str, new: str) -> None:
    """Rename a key in dictionary ``d`` from ``old`` to ``new``, in place."""
    d[new] = d.pop(old)

def rename_keys_in_dict(d: Dict[str, Any], renames: Dict[str, str]) -> None:
    """Renames, IN PLACE, the keys in ``d`` according to the mapping in
    ``renames``.

    Args:
        d: a dictionary to modify
        renames: a dictionary of the format ``{old_key_name: new_key_name}``

    See
    https://stackoverflow.com/questions/4406501/change-the-name-of-a-key-in-dictionary."""
    for old_key, new_key in renames.items():
        if new_key == old_key:
            continue
        if old_key in d:
            if new_key in d:
                raise ValueError('rename_keys_in_dict: renaming {} -> {} but new key already exists'.format(repr(old_key), repr(new_key)))
            d[new_key] = d.pop(old_key)

def prefix_dict_keys(d: Dict[str, Any], prefix: str) -> Dict[str, Any]:
    """Returns a dictionary that's a copy of as ``d`` but with ``prefix``
    prepended to its keys."""
    result = {}
    for k, v in d.items():
        result[prefix + k] = v
    return result

def set_null_values_in_dict(d: Dict[str, Any], null_literals: List[Any]) -> None:
    """Within ``d`` (in place), replace any values found in ``null_literals`` with
    ``None``."""
    if not null_literals:
        return
    for k, v in d.items():
        if v in null_literals:
            d[k] = None

def mangle_unicode_to_ascii(s: Any) -> str:
    """Mangle unicode to ASCII, losing accents etc. in the process."""
    if s is None:
        return ''
    if not isinstance(s, str):
        s = str(s)
    return unicodedata.normalize('NFKD', s).encode('ascii', 'ignore').decode('ascii')

def strnum(prefix: str, num: int, suffix: str='') -> str:
    """Makes a string of the format ``<prefix><number><suffix>``."""
    return '{}{}{}'.format(prefix, num, suffix)

def launch_cambridge_hphi(jobname: str, cmd: str, memory_mb: int, qos: str, email: str, duration: timedelta, cpus_per_task: int, project: str='hphi', tasks_per_node: int=1, partition: str='wbic-cs', modules: List[str]=None, directory: str=os.getcwd(), encoding: str='ascii') -> None:
