def get_drug(drug_name: str, name_is_generic: bool=False, include_categories: bool=False) -> Optional[Drug]:
    """Converts a drug name to a :class:`.Drug` class.

    If you already have the generic name, you can get the Drug more
    efficiently by setting ``name_is_generic=True``.

    Set ``include_categories=True`` to include drug categories (such as
    tricyclics) as well as individual drugs."""
    drug_name = drug_name.strip().lower()
    if name_is_generic:
        drug = DRUGS_BY_GENERIC_NAME.get(drug_name)
        if drug is not None and drug.category_not_drug and (not include_categories):
            return None
        return drug
    else:
        for d in DRUGS:
            if d.name_matches(drug_name):
                return d
        return None

def drug_name_to_generic(drug_name: str, unknown_to_default: bool=False, default: str=None, include_categories: bool=False) -> str:
    """Converts a drug name to the name of its generic equivalent."""
    drug = get_drug(drug_name, include_categories=include_categories)
    if drug is not None:
        return drug.generic_name
    return default if unknown_to_default else drug_name

def drug_name_matches_criteria(drug_name: str, name_is_generic: bool=False, include_categories: bool=False, **criteria: Dict[str, bool]) -> bool:
    """Establish whether a single drug, passed by name, matches the specified
    criteria. See :func:`drug_matches_criteria`."""
    drug = get_drug(drug_name, name_is_generic)
    if drug is None:
        return False
    if drug.category_not_drug and (not include_categories):
        return False
    return drug_matches_criteria(drug, **criteria)

def quaternion(vector, angle):
    """Unit quaternion for a vector and an angle"""
    return N.cos(angle / 2) + vector * N.sin(angle / 2)

def scale_errors(cov_axes, confidence_level=0.95):
    """Returns major axes of error ellipse or
    hyperbola, rescaled using chi2 test statistic"""
    dof = len(cov_axes)
    x2t = chi2.ppf(confidence_level, dof)
    return N.sqrt(x2t * cov_axes)

def generate_url(scheme=None, host=None, port=None, path=None, query=None):
    """Generate URI from parameters.

    :param str scheme:
    :param str host:
    :param int port:
    :param str path:
    :param dict query:
    :return:"""
    url = ''
    if scheme is not None:
        url += '%s://' % scheme
    if host is not None:
        url += host
    if port is not None:
        url += ':%s' % str(port)
    if path is not None:
        url += ensure_url_path_starts_with_slash(path)
    if query is not None:
        url += '?%s' % urlencode(query)
    return url

def ask_user(prompt: str, default: str=None) -> Optional[str]:
    """Prompts the user, with a default. Returns user input from ``stdin``."""
    if default is None:
        prompt += ': '
    else:
        prompt += ' [' + default + ']: '
    result = input(prompt)
    return result if len(result) > 0 else default

def positive_int(value: str) -> int:
    """``argparse`` argument type that checks that its value is a positive
    integer."""
    try:
        ivalue = int(value)
        assert ivalue > 0
    except (AssertionError, TypeError, ValueError):
        raise ArgumentTypeError('{!r} is an invalid positive int'.format(value))
    return ivalue

def percentage(value: str) -> float:
    """``argparse`` argument type that checks that its value is a percentage (in
    the sense of a float in the range [0, 100])."""
    try:
        fvalue = float(value)
        assert 0 <= fvalue <= 100
    except (AssertionError, TypeError, ValueError):
        raise ArgumentTypeError('{!r} is an invalid percentage value'.format(value))
    return fvalue

def aligned_covariance(fit, type='noise'):
    """Covariance rescaled so that eigenvectors sum to 1
    and rotated into data coordinates from PCA space"""
    cov = fit._covariance_matrix(type)
    cov /= N.linalg.norm(cov)
    return dot(fit.axes, cov)

def fit_angle(fit1, fit2, degrees=True):
    """Finds the angle between the nominal vectors"""
    return N.degrees(angle(fit1.normal, fit2.normal))

def svg_html_from_pyplot_figure(fig: 'Figure') -> str:
    """Converts a ``pyplot`` figure to an SVG tag."""
    if fig is None:
        return ''
    memfile = io.BytesIO()
    fig.savefig(memfile, format='svg')
    return memfile.getvalue().decode('utf-8')

def set_matplotlib_fontsize(matplotlib: ModuleType, fontsize: Union[int, float]=12) -> None:
    """Sets the current font size within the ``matplotlib`` library.

    **WARNING:** not an appropriate method for multithreaded environments, as
    it writes (indirectly) to ``matplotlib`` global objects. See CamCOPS for
    alternative methods."""
    font = {'family': 'sans-serif', 'style': 'normal', 'variant': 'normal', 'weight': 'normal', 'size': fontsize}
    matplotlib.rc('font', **font)
    legend = {'fontsize': fontsize}
    matplotlib.rc('legend', **legend)

def massage_keys(keys):
    """Goes through list of GPG/Keybase keys. For the keybase keys
    it will attempt to look up the GPG key"""
    m_keys = []
    for key in keys:
        if key.startswith('keybase:'):
            m_keys.append(cryptorito.key_from_keybase(key[8:])['fingerprint'])
        else:
            m_keys.append(key)
    return m_keys

def do_thing():
    """Execute command line cryptorito actions"""
    if len(sys.argv) == 5 and sys.argv[1] == 'encrypt_file':
        encrypt_file(sys.argv[2], sys.argv[3], sys.argv[4])
    elif len(sys.argv) == 4 and sys.argv[1] == 'decrypt_file':
        decrypt_file(sys.argv[2], sys.argv[3])
    elif len(sys.argv) == 3 and sys.argv[1] == 'encrypt':
        encrypt_var(sys.argv[2])
    elif len(sys.argv) == 2 and sys.argv[1] == 'decrypt':
        decrypt_var()
    elif len(sys.argv) == 3 and sys.argv[1] == 'decrypt':
        decrypt_var(passphrase=sys.argv[2])
    elif len(sys.argv) == 3 and sys.argv[1] == 'has_key':
        has_key(sys.argv[2])
    elif len(sys.argv) == 3 and sys.argv[1] == 'import_keybase':
        import_keybase(sys.argv[2])
    elif len(sys.argv) == 3 and sys.argv[1] == 'export':
        export_key(sys.argv[2])
    else:
        print('Cryptorito testing wrapper. Not suitable for routine use.', file=sys.stderr)
        sys.exit(1)

def apply_handler_to_all_logs(handler: logging.Handler, remove_existing: bool=False) -> None:
    """Applies a handler to all logs, optionally removing existing handlers.

    Should ONLY be called from the ``if __name__ == 'main'`` script;
    see https://docs.python.org/3.4/howto/logging.html#library-config.

    Generally MORE SENSIBLE just to apply a handler to the root logger.

    Args:
        handler: the handler to apply
        remove_existing: remove existing handlers from logger first?"""
    for name, obj in logging.Logger.manager.loggerDict.items():
        if remove_existing:
            obj.handlers = []
        obj.addHandler(handler)

def get_formatter_report(f: logging.Formatter) -> Optional[Dict[str, str]]:
    """Returns information on a log formatter, as a dictionary.
    For debugging."""
    if f is None:
        return None
    return {'_fmt': f._fmt, 'datefmt': f.datefmt, '_style': str(f._style)}

def get_handler_report(h: logging.Handler) -> Dict[str, Any]:
    """Returns information on a log handler, as a dictionary.
    For debugging."""
    return {'get_name()': h.get_name(), 'level': h.level, 'formatter': get_formatter_report(h.formatter), 'filters': h.filters}

def get_log_report(log: Union[logging.Logger, logging.PlaceHolder]) -> Dict[str, Any]:
    """Returns information on a log, as a dictionary. For debugging."""
    if isinstance(log, logging.Logger):
        return {'(object)': str(log), 'level': log.level, 'disabled': log.disabled, 'propagate': log.propagate, 'parent': str(log.parent), 'manager': str(log.manager), 'handlers': [get_handler_report(h) for h in log.handlers]}
    elif isinstance(log, logging.PlaceHolder):
        return {'(object)': str(log)}
    else:
        raise ValueError('Unknown object type: {!r}'.format(log))

def print_report_on_all_logs() -> None:
    """Use :func:`print` to report information on all logs."""
    d = {}
    for name, obj in logging.Logger.manager.loggerDict.items():
        d[name] = get_log_report(obj)
    rootlogger = logging.getLogger()
    d['(root logger)'] = get_log_report(rootlogger)
    print(json.dumps(d, sort_keys=True, indent=4, separators=(',', ': ')))

def get_brace_style_log_with_null_handler(name: str) -> BraceStyleAdapter:
    """For use by library functions. Returns a log with the specifed name that
    has a null handler attached, and a :class:`BraceStyleAdapter`."""
    log = logging.getLogger(name)
    log.addHandler(logging.NullHandler())
    return BraceStyleAdapter(log)

def get_table_names(engine: Engine) -> List[str]:
    """Returns a list of database table names from the :class:`Engine`."""
    insp = Inspector.from_engine(engine)
    return insp.get_table_names()

def get_view_names(engine: Engine) -> List[str]:
    """Returns a list of database view names from the :class:`Engine`."""
    insp = Inspector.from_engine(engine)
    return insp.get_view_names()

def gen_columns_info(engine: Engine, tablename: str) -> Generator[SqlaColumnInspectionInfo, None, None]:
    """For the specified table, generate column information as
    :class:`SqlaColumnInspectionInfo` objects."""
    insp = Inspector.from_engine(engine)
    for d in insp.get_columns(tablename):
        yield SqlaColumnInspectionInfo(d)

def get_column_info(engine: Engine, tablename: str, columnname: str) -> Optional[SqlaColumnInspectionInfo]:
    """For the specified column in the specified table, get column information
    as a :class:`SqlaColumnInspectionInfo` object (or ``None`` if such a
    column can't be found)."""
    for info in gen_columns_info(engine, tablename):
        if info.name == columnname:
            return info
    return None

def get_column_type(engine: Engine, tablename: str, columnname: str) -> Optional[TypeEngine]:
    """For the specified column in the specified table, get its type as an
    instance of an SQLAlchemy column type class (or ``None`` if such a column
    can't be found).

    For more on :class:`TypeEngine`, see
    :func:`cardinal_pythonlib.orm_inspect.coltype_as_typeengine`."""
    for info in gen_columns_info(engine, tablename):
        if info.name == columnname:
            return info.type
    return None

def get_column_names(engine: Engine, tablename: str) -> List[str]:
    """Get all the database column names for the specified table."""
    return [info.name for info in gen_columns_info(engine, tablename)]

def get_pk_colnames(table_: Table) -> List[str]:
    """If a table has a PK, this will return its database column name(s);
    otherwise, ``None``."""
    pk_names = []
    for col in table_.columns:
        if col.primary_key:
            pk_names.append(col.name)
    return pk_names

def get_single_int_pk_colname(table_: Table) -> Optional[str]:
    """If a table has a single-field (non-composite) integer PK, this will
    return its database column name; otherwise, None.

    Note that it is legitimate for a database table to have both a composite
    primary key and a separate ``IDENTITY`` (``AUTOINCREMENT``) integer field.
    This function won't find such columns."""
    n_pks = 0
    int_pk_names = []
    for col in table_.columns:
        if col.primary_key:
            n_pks += 1
            if is_sqlatype_integer(col.type):
                int_pk_names.append(col.name)
    if n_pks == 1 and len(int_pk_names) == 1:
        return int_pk_names[0]
    return None

def index_exists(engine: Engine, tablename: str, indexname: str) -> bool:
    """Does the specified index exist for the specified table?"""
    insp = Inspector.from_engine(engine)
    return any((i['name'] == indexname for i in insp.get_indexes(tablename)))

def make_bigint_autoincrement_column(column_name: str, dialect: Dialect) -> Column:
    """Returns an instance of :class:`Column` representing a :class:`BigInteger`
    ``AUTOINCREMENT`` column in the specified :class:`Dialect`."""
    if dialect.name == SqlaDialectName.MSSQL:
        return Column(column_name, BigInteger, Sequence('dummy_name', start=1, increment=1))
    else:
        raise AssertionError("SQLAlchemy doesn't support non-PK autoincrement fields yet for dialect {}".format(repr(dialect.name)))

def is_sqlatype_binary(coltype: Union[TypeEngine, VisitableType]) -> bool:
    """Is the SQLAlchemy column type a binary type?"""
    coltype = _coltype_to_typeengine(coltype)
    return isinstance(coltype, sqltypes._Binary)

def is_sqlatype_date(coltype: TypeEngine) -> bool:
    """Is the SQLAlchemy column type a date type?"""
    coltype = _coltype_to_typeengine(coltype)
    return isinstance(coltype, sqltypes.DateTime) or isinstance(coltype, sqltypes.Date)

def is_sqlatype_integer(coltype: Union[TypeEngine, VisitableType]) -> bool:
    """Is the SQLAlchemy column type an integer type?"""
    coltype = _coltype_to_typeengine(coltype)
    return isinstance(coltype, sqltypes.Integer)

def is_sqlatype_numeric(coltype: Union[TypeEngine, VisitableType]) -> bool:
    """Is the SQLAlchemy column type one that inherits from :class:`Numeric`,
    such as :class:`Float`, :class:`Decimal`?"""
    coltype = _coltype_to_typeengine(coltype)
    return isinstance(coltype, sqltypes.Numeric)

def is_sqlatype_string(coltype: Union[TypeEngine, VisitableType]) -> bool:
    """Is the SQLAlchemy column type a string type?"""
    coltype = _coltype_to_typeengine(coltype)
    return isinstance(coltype, sqltypes.String)

def is_sqlatype_text_of_length_at_least(coltype: Union[TypeEngine, VisitableType], min_length: int=1000) -> bool:
    """Is the SQLAlchemy column type a string type that's at least the specified
    length?"""
    coltype = _coltype_to_typeengine(coltype)
    if not isinstance(coltype, sqltypes.String):
        return False
    if coltype.length is None:
        return True
    return coltype.length >= min_length

def is_sqlatype_text_over_one_char(coltype: Union[TypeEngine, VisitableType]) -> bool:
    """Is the SQLAlchemy column type a string type that's more than one character
    long?"""
    coltype = _coltype_to_typeengine(coltype)
    return is_sqlatype_text_of_length_at_least(coltype, 2)

def does_sqlatype_merit_fulltext_index(coltype: Union[TypeEngine, VisitableType], min_length: int=1000) -> bool:
    """Is the SQLAlchemy column type a type that might merit a ``FULLTEXT``
    index (meaning a string type of at least ``min_length``)?"""
    coltype = _coltype_to_typeengine(coltype)
    return is_sqlatype_text_of_length_at_least(coltype, min_length)

def column_types_equal(a_coltype: TypeEngine, b_coltype: TypeEngine) -> bool:
    """Checks that two SQLAlchemy column types are equal (by comparing ``str()``
    versions of them).

    See http://stackoverflow.com/questions/34787794/sqlalchemy-column-type-comparison.

    IMPERFECT."""
    return str(a_coltype) == str(b_coltype)

def columns_equal(a: Column, b: Column) -> bool:
    """Are two SQLAlchemy columns are equal? Checks based on:

    - column ``name``
    - column ``type`` (see :func:`column_types_equal`)
    - ``nullable``"""
    return a.name == b.name and column_types_equal(a.type, b.type) and (a.nullable == b.nullable)

def column_lists_equal(a: List[Column], b: List[Column]) -> bool:
    """Are all columns in list ``a`` equal to their counterparts in list ``b``,
    as per :func:`columns_equal`?"""
    n = len(a)
    if len(b) != n:
        return False
    for i in range(n):
        if not columns_equal(a[i], b[i]):
            log.debug('Mismatch: {!r} != {!r}', a[i], b[i])
            return False
    return True

def index_lists_equal(a: List[Index], b: List[Index]) -> bool:
    """Are all indexes in list ``a`` equal to their counterparts in list ``b``,
    as per :func:`indexes_equal`?"""
    n = len(a)
    if len(b) != n:
        return False
    for i in range(n):
        if not indexes_equal(a[i], b[i]):
            log.debug('Mismatch: {!r} != {!r}', a[i], b[i])
            return False
    return True

def to_bytes(data: Any) -> bytearray:
    """Convert anything to a ``bytearray``.

    See

    - http://stackoverflow.com/questions/7585435/best-way-to-convert-string-to-bytes-in-python-3
    - http://stackoverflow.com/questions/10459067/how-to-convert-my-bytearrayb-x9e-x18k-x9a-to-something-like-this-x9e-x1"""
    if isinstance(data, int):
        return bytearray([data])
    return bytearray(data, encoding='latin-1')

def pymmh3_hash128(key: Union[bytes, bytearray], seed: int=0, x64arch: bool=True) -> int:
    """Implements 128bit murmur3 hash, as per ``pymmh3``.

    Args:
        key: data to hash
        seed: seed
        x64arch: is a 64-bit architecture available?

    Returns:
        integer hash"""
    if x64arch:
        return pymmh3_hash128_x64(key, seed)
    else:
        return pymmh3_hash128_x86(key, seed)

def pymmh3_hash64(key: Union[bytes, bytearray], seed: int=0, x64arch: bool=True) -> Tuple[int, int]:
    """Implements 64bit murmur3 hash, as per ``pymmh3``. Returns a tuple.

    Args:
        key: data to hash
        seed: seed
        x64arch: is a 64-bit architecture available?

    Returns:
        tuple: tuple of integers, ``(signed_val1, signed_val2)``"""
    hash_128 = pymmh3_hash128(key, seed, x64arch)
    unsigned_val1 = hash_128 & 18446744073709551615
    if unsigned_val1 & 9223372036854775808 == 0:
        signed_val1 = unsigned_val1
    else:
        signed_val1 = -((unsigned_val1 ^ 18446744073709551615) + 1)
    unsigned_val2 = hash_128 >> 64 & 18446744073709551615
    if unsigned_val2 & 9223372036854775808 == 0:
        signed_val2 = unsigned_val2
    else:
        signed_val2 = -((unsigned_val2 ^ 18446744073709551615) + 1)
    return (signed_val1, signed_val2)

def safe_logit(p: Union[float, int]) -> Optional[float]:
    """Returns the logit (log odds) of its input probability

    .. math::

        \\alpha = logit(p) = log(x / (1 - x))

    Args:
        p: :math:`p`

    Returns:
        :math:`\\alpha`, or ``None`` if ``x`` is not in the range [0, 1]."""
    if p > 1 or p < 0:
        return None
    if p == 1:
        return float('inf')
    if p == 0:
        return float('-inf')
    return math.log(p / (1 - p))

def normal_round_int(x: float) -> int:
    """Version of :func:`normal_round_float` but guaranteed to return an `int`."""
    if not math.isfinite(x):
        raise ValueError('Input to normal_round_int() is not finite')
    if x >= 0:
        return math.floor(x + 0.5)
    else:
        return math.ceil(x - 0.5)

def get_dialect(mixed: Union[SQLCompiler, Engine, Dialect]) -> Dialect:
    """Finds the SQLAlchemy dialect in use.

    Args:
        mixed: an SQLAlchemy :class:`SQLCompiler`, :class:`Engine`, or
            :class:`Dialect` object

    Returns: the SQLAlchemy :class:`Dialect` being used"""
    if isinstance(mixed, Dialect):
        return mixed
    elif isinstance(mixed, Engine):
        return mixed.dialect
    elif isinstance(mixed, SQLCompiler):
        return mixed.dialect
    else:
        raise ValueError("get_dialect: 'mixed' parameter of wrong type")

def tsv_escape(x: Any) -> str:
    """Escape data for tab-separated value (TSV) format."""
    if x is None:
        return ''
    x = str(x)
    return x.replace('\t', '\\t').replace('\n', '\\n')

def make_tsv_row(values: List[Any]) -> str:
    """From a list of values, make a TSV line."""
    return '\t'.join([tsv_escape(x) for x in values]) + '\n'

def dictlist_to_tsv(dictlist: List[Dict[str, Any]]) -> str:
    """From a consistent list of dictionaries mapping fieldnames to values,
    make a TSV file."""
    if not dictlist:
        return ''
    fieldnames = dictlist[0].keys()
    tsv = '\t'.join([tsv_escape(f) for f in fieldnames]) + '\n'
    for d in dictlist:
        tsv += '\t'.join([tsv_escape(v) for v in d.values()]) + '\n'
    return tsv

def import_submodules(package: Union[str, ModuleType], base_package_for_relative_import: str=None, recursive: bool=True) -> Dict[str, ModuleType]:
    """Import all submodules of a module, recursively, including subpackages.

    Args:
        package: package (name or actual module)
        base_package_for_relative_import: path to prepend?
        recursive: import submodules too?

    Returns:
        dict: mapping from full module name to module"""
    if isinstance(package, str):
        package = importlib.import_module(package, base_package_for_relative_import)
    results = {}
    for loader, name, is_pkg in pkgutil.walk_packages(package.__path__):
        full_name = package.__name__ + '.' + name
        log.debug('importing: {}', full_name)
        results[full_name] = importlib.import_module(full_name)
        if recursive and is_pkg:
            results.update(import_submodules(full_name))
    return results

def rmglob(pattern: str) -> None:
    """Deletes all files whose filename matches the glob ``pattern`` (via
    :func:`glob.glob`)."""
    for f in glob.glob(pattern):
        os.remove(f)

def purge(path: str, pattern: str) -> None:
    """Deletes all files in ``path`` matching ``pattern`` (via
    :func:`fnmatch.fnmatch`)."""
    for f in find(pattern, path):
        log.info('Deleting {}', f)
        os.remove(f)

def delete_files_within_dir(directory: str, filenames: List[str]) -> None:
    """Delete files within ``directory`` whose filename *exactly* matches one of
    ``filenames``."""
    for dirpath, dirnames, fnames in os.walk(directory):
        for f in fnames:
            if f in filenames:
                fullpath = os.path.join(dirpath, f)
                log.debug('Deleting {!r}', fullpath)
                os.remove(fullpath)

def chown_r(path: str, user: str, group: str) -> None:
    """Performs a recursive ``chown``.

    Args:
        path: path to walk down
        user: user name or ID
        group: group name or ID

    As per http://stackoverflow.com/questions/2853723"""
    for root, dirs, files in os.walk(path):
        for x in dirs:
            shutil.chown(os.path.join(root, x), user, group)
        for x in files:
            shutil.chown(os.path.join(root, x), user, group)

def chmod_r(root: str, permission: int) -> None:
    """Recursive ``chmod``.

    Args:
        root: directory to walk down
        permission: e.g. ``e.g. stat.S_IWUSR``"""
    os.chmod(root, permission)
    for dirpath, dirnames, filenames in os.walk(root):
        for d in dirnames:
            os.chmod(os.path.join(dirpath, d), permission)
        for f in filenames:
            os.chmod(os.path.join(dirpath, f), permission)

def find_first(pattern: str, path: str) -> str:
    """Finds first file in ``path`` whose filename matches ``pattern`` (via
    :func:`fnmatch.fnmatch`), or raises :exc:`IndexError`."""
    try:
        return find(pattern, path)[0]
    except IndexError:
        log.critical('Couldn\'t find "{}" in "{}"', pattern, path)
        raise

def gen_filenames(starting_filenames: List[str], recursive: bool) -> Generator[str, None, None]:
    """From a starting list of files and/or directories, generates filenames of
    all files in the list, and (if ``recursive`` is set) all files within
    directories in the list.

    Args:
        starting_filenames: files and/or directories
        recursive: walk down any directories in the starting list, recursively?

    Yields:
        each filename"""
    for base_filename in starting_filenames:
        if os.path.isfile(base_filename):
            yield os.path.abspath(base_filename)
        elif os.path.isdir(base_filename) and recursive:
            for dirpath, dirnames, filenames in os.walk(base_filename):
                for fname in filenames:
                    yield os.path.abspath(os.path.join(dirpath, fname))

def relative_filename_within_dir(filename: str, directory: str) -> str:
    """Starting with a (typically absolute) ``filename``, returns the part of the
    filename that is relative to the directory ``directory``.
    If the file is *not* within the directory, returns an empty string."""
    filename = os.path.abspath(filename)
    directory = os.path.abspath(directory)
    if os.path.commonpath([directory, filename]) != directory:
        return ''
    return os.path.relpath(filename, start=directory)

def run(args: List[str], get_output: bool=False, encoding: str=sys.getdefaultencoding()) -> Tuple[str, str]:
    """Run an external command +/- return the results.
    Returns a ``(stdout, stderr)`` tuple (both are blank strings if the output
    wasn't wanted)."""
    printable = ' '.join((shlex.quote(x) for x in args)).replace('\n', '\\n')
    log.debug('Running external command: {}', printable)
    if get_output:
        p = subprocess.run(args, stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=True)
        stdout, stderr = (p.stdout.decode(encoding), p.stderr.decode(encoding))
    else:
        subprocess.check_call(args)
        stdout, stderr = ('', '')
    return (stdout, stderr)

def get_page_count(filename: str) -> int:
    """How many pages are in a PDF?"""
    log.debug('Getting page count for {!r}', filename)
    require(PDFTK, HELP_MISSING_PDFTK)
    stdout, _ = run([PDFTK, filename, 'dump_data'], get_output=True)
    regex = re.compile('^NumberOfPages: (\\d+)$', re.MULTILINE)
    m = regex.search(stdout)
    if m:
        return int(m.group(1))
    raise ValueError("Can't get PDF page count for: {!r}".format(filename))

def val_mb(valstr: Union[int, str]) -> str:
    """Converts a value in bytes (in string format) to megabytes."""
    try:
        return '{:.3f}'.format(int(valstr) / (1024 * 1024))
    except (TypeError, ValueError):
        return '?'

def http_response_body_should_be_this_json(context):
    """Parameters:

        .. code-block:: json

            {
                "param1": "value1",
                "param2": "value2",
                "param3": {
                    "param31": "value31"
                }
            }"""
    body_params = json.loads(context.text)
    assert body_params == context.api_response.data, 'Expected: {}; Message: {}'.format(body_params, context.api_response.data)

def dump(cursor):
    """Display the AST represented by the cursor
    """
    def node_children(node):
        return list(node.get_children())
    def print_node(node):
        text = node.spelling or node.displayname
        kind = str(node.kind).split('.')[1]
        return '{} {}'.format(kind, text)
    return draw_tree(cursor, node_children, print_node)

def coerce_to_pendulum(x: PotentialDatetimeType, assume_local: bool=False) -> Optional[DateTime]:
    """Converts something to a :class:`pendulum.DateTime`.

    Args:
        x: something that may be coercible to a datetime
        assume_local: if ``True``, assume local timezone; if ``False``, assume
            UTC

    Returns:
        a :class:`pendulum.DateTime`, or ``None``.

    Raises:
        pendulum.parsing.exceptions.ParserError: if a string fails to parse
        ValueError: if no conversion possible"""
    if not x:
        return None
    if isinstance(x, DateTime):
        return x
    tz = get_tz_local() if assume_local else get_tz_utc()
    if isinstance(x, datetime.datetime):
        return pendulum.instance(x, tz=tz)
    elif isinstance(x, datetime.date):
        midnight = DateTime.min.time()
        dt = DateTime.combine(x, midnight)
        return pendulum.instance(dt, tz=tz)
    elif isinstance(x, str):
        return pendulum.parse(x, tz=tz)
    else:
        raise ValueError("Don't know how to convert to DateTime: {!r}".format(x))

def pendulum_to_datetime(x: DateTime) -> datetime.datetime:
    """Used, for example, where a database backend insists on datetime.datetime.

    Compare code in :meth:`pendulum.datetime.DateTime.int_timestamp`."""
    return datetime.datetime(x.year, x.month, x.day, x.hour, x.minute, x.second, x.microsecond, tzinfo=x.tzinfo)

def pendulum_date_to_datetime_date(x: Date) -> datetime.date:
    """Takes a :class:`pendulum.Date` and returns a :class:`datetime.date`.
    Used, for example, where a database backend insists on
    :class:`datetime.date`."""
    return datetime.date(year=x.year, month=x.month, day=x.day)

def pendulum_time_to_datetime_time(x: Time) -> datetime.time:
    """Takes a :class:`pendulum.Time` and returns a :class:`datetime.time`.
    Used, for example, where a database backend insists on
    :class:`datetime.time`."""
    return datetime.time(hour=x.hour, minute=x.minute, second=x.second, microsecond=x.microsecond, tzinfo=x.tzinfo)

def format_datetime(d: PotentialDatetimeType, fmt: str, default: str=None) -> Optional[str]:
    """Format a datetime with a ``strftime`` format specification string, or
    return ``default`` if the input is ``None``."""
    d = coerce_to_pendulum(d)
    if d is None:
        return default
    return d.strftime(fmt)

def convert_datetime_to_utc(dt: PotentialDatetimeType) -> DateTime:
    """Convert date/time with timezone to UTC (with UTC timezone)."""
    dt = coerce_to_pendulum(dt)
    tz = get_tz_utc()
    return dt.in_tz(tz)

def convert_datetime_to_local(dt: PotentialDatetimeType) -> DateTime:
    """Convert date/time with timezone to local timezone."""
    dt = coerce_to_pendulum(dt)
    tz = get_tz_local()
    return dt.in_tz(tz)

def truncate_date_to_first_of_month(dt: Optional[DateLikeType]) -> Optional[DateLikeType]:
    """Change the day to the first of the month."""
    if dt is None:
        return None
    return dt.replace(day=1)

def get_now_utc_notz_datetime() -> datetime.datetime:
    """Get the UTC time now, but with no timezone information,
    in :class:`datetime.datetime` format."""
    now = datetime.datetime.utcnow()
    return now.replace(tzinfo=None)

def coerce_to_datetime(x: Any) -> Optional[datetime.datetime]:
    """Ensure an object is a :class:`datetime.datetime`, or coerce to one, or
    raise :exc:`ValueError` or :exc:`OverflowError` (as per
    http://dateutil.readthedocs.org/en/latest/parser.html)."""
    if x is None:
        return None
    elif isinstance(x, DateTime):
        return pendulum_to_datetime(x)
    elif isinstance(x, datetime.datetime):
        return x
    elif isinstance(x, datetime.date):
        return datetime.datetime(x.year, x.month, x.day)
    else:
        return dateutil.parser.parse(x)

def generate_random_nhs_number() -> int:
    """Returns a random valid NHS number, as an ``int``."""
    check_digit = 10
    while check_digit == 10:
        digits = [random.randint(1, 9)]
        digits.extend([random.randint(0, 9) for _ in range(8)])
        check_digit = nhs_check_digit(digits)
    digits.append(check_digit)
    return int(''.join([str(d) for d in digits]))

def is_sqlserver_2008_or_later(engine: 'Engine') -> bool:
    """Is the SQLAlchemy :class:`Engine` an instance of Microsoft SQL Server,
    version 2008 or later?"""
    if not is_sqlserver(engine):
        return False
    version_tuple = get_sqlserver_product_version(engine)
    return version_tuple >= (SQLSERVER_MAJOR_VERSION_2008,)

def random_product(*args, repeat=1):
    """Random selection from itertools.product(*args, **kwds)"""
    pools = [tuple(pool) for pool in args] * repeat
    return tuple((random.choice(pool) for pool in pools))

def genrows(cursor: Cursor, arraysize: int=1000) -> Generator[List[Any], None, None]:
    """Generate all rows from a cursor.

    Args:
        cursor: the cursor
        arraysize: split fetches into chunks of this many records

    Yields:
        each row"""
    while True:
        results = cursor.fetchmany(arraysize)
        if not results:
            break
        for result in results:
            yield result

def dictfetchone(cursor: Cursor) -> Optional[Dict[str, Any]]:
    """Return the next row from a cursor as an :class:`OrderedDict`, or ``None``."""
    columns = get_fieldnames_from_cursor(cursor)
    row = cursor.fetchone()
    if not row:
        return None
    return OrderedDict(zip(columns, row))

def fetch_processed_single_clause(element: 'ClauseElement', compiler: 'SQLCompiler') -> str:
    """Takes a clause element that must have a single clause, and converts it
    to raw SQL text."""
    if len(element.clauses) != 1:
        raise TypeError('Only one argument supported; {} were passed'.format(len(element.clauses)))
    clauselist = element.clauses
    first = clauselist.get_children()[0]
    return compiler.process(first)

def clean_int(x) -> int:
    """Returns its parameter as an integer, or raises
    ``django.forms.ValidationError``."""
    try:
        return int(x)
    except ValueError:
        raise forms.ValidationError('Cannot convert to integer: {}'.format(repr(x)))

def clean_nhs_number(x) -> int:
    """Returns its parameter as a valid integer NHS number, or raises
    ``django.forms.ValidationError``."""
    try:
        x = int(x)
        if not is_valid_nhs_number(x):
            raise ValueError
        return x
    except ValueError:
        raise forms.ValidationError('Not a valid NHS number: {}'.format(repr(x)))

def get_orm_columns(cls: Type) -> List[Column]:
    """Gets :class:`Column` objects from an SQLAlchemy ORM class.
    Does not provide their attribute names."""
    mapper = inspect(cls)
    colmap = mapper.columns
    return colmap.values()

def gen_orm_classes_from_base(base: Type) -> Generator[Type, None, None]:
    """From an SQLAlchemy ORM base class, yield all the subclasses (except those
    that are abstract).

    If you begin with the proper :class`Base` class, then this should give all
    ORM classes in use."""
    for cls in gen_all_subclasses(base):
        if _get_immediate_cls_attr(cls, '__abstract__', strict=True):
            continue
        yield cls

def get_orm_classes_by_table_name_from_base(base: Type) -> Dict[str, Type]:
    """Given an SQLAlchemy ORM base class, returns a dictionary whose keys are
    table names and whose values are ORM classes.

    If you begin with the proper :class`Base` class, then this should give all
    tables and ORM classes in use."""
    return {cls.__tablename__: cls for cls in gen_orm_classes_from_base(base)}

def gen_all_subclasses(cls: Type) -> Generator[Type, None, None]:
    """Generates all subclasses of a class.

    Args:
        cls: a class

    Yields:
        all subclasses"""
    for s1 in cls.__subclasses__():
        yield s1
        for s2 in gen_all_subclasses(s1):
            yield s2

def perpendicular_vector(n):
    """Get a random vector perpendicular
    to the given vector"""
    dim = len(n)
    if dim == 2:
        return n[::-1]
    for ix in range(dim):
        _ = N.zeros(dim)
        _[dim - ix - 1] = 1
        v1 = N.cross(n, _)
        if N.linalg.norm(v1) != 0:
            return v1
    raise ValueError('Cannot find perpendicular vector')

def is_openxml_good(filename: str) -> bool:
    """Determines whether an OpenXML file appears to be good (not corrupted)."""
    try:
        log.debug('Trying: {}', filename)
        with ZipFile(filename, 'r') as zip_ref:
            namelist = zip_ref.namelist()
            for mandatory_filename in MANDATORY_FILENAMES:
                if mandatory_filename not in namelist:
                    log.debug('Bad [missing {!r}]: {}', mandatory_filename, filename)
                    return False
            infolist = zip_ref.infolist()
            contains_docx = False
            contains_pptx = False
            contains_xlsx = False
            for info in infolist:
                if not contains_docx and DOCX_CONTENTS_REGEX.search(info.filename):
                    contains_docx = True
                if not contains_pptx and PPTX_CONTENTS_REGEX.search(info.filename):
                    contains_pptx = True
                if not contains_xlsx and XLSX_CONTENTS_REGEX.search(info.filename):
                    contains_xlsx = True
                if sum([contains_docx, contains_pptx, contains_xlsx]) > 1:
                    log.debug('Bad [>1 of DOCX, PPTX, XLSX content]: {}', filename)
                    return False
            return True
    except (BadZipFile, OSError) as e:
        log.debug('Bad [BadZipFile or OSError]: {!r}; error was {!r}', filename, e)
        return False

def get_string_relative(strings: Sequence[str], prefix1: str, delta: int, prefix2: str, ignoreleadingcolon: bool=False, stripwhitespace: bool=True) -> Optional[str]:
    """Finds a line (string) in ``strings`` beginning with ``prefix1``. Moves
    ``delta`` lines (strings) further. Returns the end of the line that
    begins with ``prefix2``, if found.

    Args:
        strings: as above
        prefix1: as above
        delta: as above
        prefix2: as above
        ignoreleadingcolon: restrict the result to the part after its first
            colon?
        stripwhitespace: strip whitespace from the start/end of the result?

    Returns:
        the line fragment"""
    for firstline in range(0, len(strings)):
        if strings[firstline].find(prefix1) == 0:
            secondline = firstline + delta
            if secondline < 0 or secondline >= len(strings):
                continue
            if strings[secondline].find(prefix2) == 0:
                s = strings[secondline][len(prefix2):]
                if stripwhitespace:
                    s = s.strip()
                if ignoreleadingcolon:
                    f = s.find(':')
                    if f != -1:
                        s = s[f + 1:].strip()
                    if stripwhitespace:
                        s = s.strip()
                if len(s) == 0:
                    return None
                return s
    return None

def get_int(strings: Sequence[str], prefix: str, ignoreleadingcolon: bool=False, precedingline: str='') -> Optional[int]:
    """Fetches an integer parameter via :func:`get_string`."""
    return get_int_raw(get_string(strings, prefix, ignoreleadingcolon=ignoreleadingcolon, precedingline=precedingline))

def get_float(strings: Sequence[str], prefix: str, ignoreleadingcolon: bool=False, precedingline: str='') -> Optional[float]:
    """Fetches a float parameter via :func:`get_string`."""
    return get_float_raw(get_string(strings, prefix, ignoreleadingcolon=ignoreleadingcolon, precedingline=precedingline))

def get_bool_raw(s: str) -> Optional[bool]:
    """Maps ``"Y"``, ``"y"`` to ``True`` and ``"N"``, ``"n"`` to ``False``."""
    if s == 'Y' or s == 'y':
        return True
    elif s == 'N' or s == 'n':
        return False
    return None

def get_bool(strings: Sequence[str], prefix: str, ignoreleadingcolon: bool=False, precedingline: str='') -> Optional[bool]:
    """Fetches a boolean parameter via :func:`get_string`."""
    return get_bool_raw(get_string(strings, prefix, ignoreleadingcolon=ignoreleadingcolon, precedingline=precedingline))

def get_bool_relative(strings: Sequence[str], prefix1: str, delta: int, prefix2: str, ignoreleadingcolon: bool=False) -> Optional[bool]:
    """Fetches a boolean parameter via :func:`get_string_relative`."""
    return get_bool_raw(get_string_relative(strings, prefix1, delta, prefix2, ignoreleadingcolon=ignoreleadingcolon))

def get_float_relative(strings: Sequence[str], prefix1: str, delta: int, prefix2: str, ignoreleadingcolon: bool=False) -> Optional[float]:
    """Fetches a float parameter via :func:`get_string_relative`."""
    return get_float_raw(get_string_relative(strings, prefix1, delta, prefix2, ignoreleadingcolon=ignoreleadingcolon))

def get_int_relative(strings: Sequence[str], prefix1: str, delta: int, prefix2: str, ignoreleadingcolon: bool=False) -> Optional[int]:
    """Fetches an int parameter via :func:`get_string_relative`."""
    return get_int_raw(get_string_relative(strings, prefix1, delta, prefix2, ignoreleadingcolon=ignoreleadingcolon))

def find_line_beginning(strings: Sequence[str], linestart: Optional[str]) -> int:
    """Finds the index of the line in ``strings`` that begins with ``linestart``,
    or ``-1`` if none is found.

    If ``linestart is None``, match an empty line."""
    if linestart is None:
        for i in range(len(strings)):
            if is_empty_string(strings[i]):
                return i
        return -1
    for i in range(len(strings)):
        if strings[i].find(linestart) == 0:
            return i
    return -1

def find_line_containing(strings: Sequence[str], contents: str) -> int:
    """Finds the index of the line in ``strings`` that contains ``contents``,
    or ``-1`` if none is found."""
    for i in range(len(strings)):
        if strings[i].find(contents) != -1:
            return i
    return -1

def dictlist_convert_to_string(dict_list: Iterable[Dict], key: str) -> None:
    """Process an iterable of dictionaries. For each dictionary ``d``, convert
    (in place) ``d[key]`` to a string form, ``str(d[key])``. If the result is a
    blank string, convert it to ``None``."""
    for d in dict_list:
        d[key] = str(d[key])
        if d[key] == '':
            d[key] = None

def dictlist_convert_to_int(dict_list: Iterable[Dict], key: str) -> None:
    """Process an iterable of dictionaries. For each dictionary ``d``, convert
    (in place) ``d[key]`` to an integer. If that fails, convert it to ``None``."""
    for d in dict_list:
        try:
            d[key] = int(d[key])
        except ValueError:
            d[key] = None

def dictlist_convert_to_float(dict_list: Iterable[Dict], key: str) -> None:
    """Process an iterable of dictionaries. For each dictionary ``d``, convert
    (in place) ``d[key]`` to a float. If that fails, convert it to ``None``."""
    for d in dict_list:
        try:
            d[key] = float(d[key])
        except ValueError:
            d[key] = None

def dictlist_convert_to_bool(dict_list: Iterable[Dict], key: str) -> None:
    """Process an iterable of dictionaries. For each dictionary ``d``, convert
    (in place) ``d[key]`` to a bool. If that fails, convert it to ``None``."""
    for d in dict_list:
        d[key] = 1 if d[key] == 'Y' else 0

def dictlist_replace(dict_list: Iterable[Dict], key: str, value: Any) -> None:
    """Process an iterable of dictionaries. For each dictionary ``d``, change
    (in place) ``d[key]`` to ``value``."""
    for d in dict_list:
        d[key] = value

def dictlist_wipe_key(dict_list: Iterable[Dict], key: str) -> None:
    """Process an iterable of dictionaries. For each dictionary ``d``, delete
    ``d[key]`` if it exists."""
    for d in dict_list:
        d.pop(key, None)

def get_call_signature(fn: FunctionType, args: ArgsType, kwargs: KwargsType, debug_cache: bool=False) -> str:
    """Takes a function and its args/kwargs, and produces a string description
    of the function call (the call signature) suitable for use indirectly as a
    cache key. The string is a JSON representation. See ``make_cache_key`` for
    a more suitable actual cache key."""
    try:
        call_sig = json_encode((fn.__qualname__, args, kwargs))
    except TypeError:
        log.critical("\nTo decorate using @django_cache_function without specifying cache_key, the decorated function's owning class and its parameters must be JSON-serializable (see jsonfunc.py, django_cache_fn.py).\n")
        raise
    if debug_cache:
        log.debug('Making call signature {!r}', call_sig)
    return call_sig

def _sign_data(secret, data):
    """Sign data.

    :param data: the string to sign
    :return: string base64 encoding of the HMAC-SHA1 hash of the data parameter using {@code secretKey} as cipher key."""
    sha1_hash = hmac.new(secret.encode(), data.encode(), sha1)
    return binascii.b2a_base64(sha1_hash.digest())[:-1].decode('utf8')

def _get_11paths_serialized_headers(x_headers):
    """Prepares and returns a string ready to be signed from the 11-paths specific HTTP headers received.

    :param x_headers: a non necessarily ordered map (array without duplicates) of the HTTP headers to be ordered.
    :return: string The serialized headers, an empty string if no headers are passed, or None if there's a problem such
    as non 11paths specific headers"""
    if x_headers:
        headers = to_key_val_list(x_headers, sort=True, insensitive=True)
        serialized_headers = ''
        for key, value in headers:
            if key.lower().startswith(X_11PATHS_HEADER_PREFIX.lower()) and key.lower() != X_11PATHS_DATE_HEADER_NAME.lower():
                serialized_headers += key.lower() + X_11PATHS_HEADER_SEPARATOR + value.replace('\n', ' ') + ' '
        return serialized_headers.strip()
    else:
        return ''

def rotate_2D(angle):
    """Returns a 2x2 transformation matrix to rotate
    by an angle in two dimensions"""
    return N.array([[N.cos(angle), -N.sin(angle)], [N.sin(angle), N.cos(angle)]])

def sizeof_fmt(num: float, suffix: str='B') -> str:
    """Formats a number of bytes in a human-readable binary format (e.g. ``2048``
    becomes ``'2 KiB'``); from http://stackoverflow.com/questions/1094841."""
    for unit in ('', 'Ki', 'Mi', 'Gi', 'Ti', 'Pi', 'Ei', 'Zi'):
        if abs(num) < 1024.0:
            return '%3.1f%s%s' % (num, unit, suffix)
        num /= 1024.0
    return '%.1f%s%s' % (num, 'Yi', suffix)

def excel_to_bytes(wb: Workbook) -> bytes:
