    """Appends a PDF to a pyPDF writer. Legacy interface."""
    append_memory_pdf_to_writer(input_pdf=input_pdf, writer=output_writer)

def get_concatenated_pdf_from_disk(filenames: Iterable[str], start_recto: bool=True) -> bytes:
    """Concatenates PDFs from disk and returns them as an in-memory binary PDF.

    Args:
        filenames: iterable of filenames of PDFs to concatenate
        start_recto: start a new right-hand page for each new PDF?

    Returns:
        concatenated PDF, as ``bytes``"""
    if start_recto:
        writer = PdfFileWriter()
        for filename in filenames:
            if filename:
                if writer.getNumPages() % 2 != 0:
                    writer.addBlankPage()
                writer.appendPagesFromReader(PdfFileReader(open(filename, 'rb')))
        return pdf_from_writer(writer)
    else:
        merger = PdfFileMerger()
        for filename in filenames:
            if filename:
                merger.append(open(filename, 'rb'))
        return pdf_from_writer(merger)

def trunc_if_integer(n: Any) -> Any:
    """Truncates floats that are integers to their integer representation.
    That is, converts ``1.0`` to ``1``, etc.
    Otherwise, returns the starting value.
    Will raise an exception if the input cannot be converted to ``int``."""
    if n == int(n):
        return int(n)
    return n

def repr_result(obj: Any, elements: List[str], with_addr: bool=False, joiner: str=COMMA_SPACE) -> str:
    """Internal function to make a :func:`repr`-style representation of an object.

    Args:
        obj: object to display
        elements: list of object ``attribute=value`` strings
        with_addr: include the memory address of ``obj``
        joiner: string with which to join the elements

    Returns:
        string: :func:`repr`-style representation"""
    if with_addr:
        return '<{qualname}({elements}) at {addr}>'.format(qualname=obj.__class__.__qualname__, elements=joiner.join(elements), addr=hex(id(obj)))
    else:
        return '{qualname}({elements})'.format(qualname=obj.__class__.__qualname__, elements=joiner.join(elements))

def ordered_repr(obj: object, attrlist: Iterable[str], joiner: str=COMMA_SPACE) -> str:
    """Shortcut to make :func:`repr` functions ordered.
    Define your :func:`__repr__` like this:

    .. code-block:: python

        def __repr__(self):
            return ordered_repr(self, ["field1", "field2", "field3"])

    Args:
        obj: object to display
        attrlist: iterable of attribute names
        joiner: string with which to join the elements

    Returns:
        string: :func:`repr`-style representation"""
    return '<{classname}({kvp})>'.format(classname=type(obj).__name__, kvp=joiner.join(('{}={}'.format(a, repr(getattr(obj, a))) for a in attrlist)))

def timedelta_days(days: int) -> timedelta64:
    """Convert a duration in days to a NumPy ``timedelta64`` object."""
    int_days = int(days)
    if int_days != days:
        raise ValueError('Fractional days passed to timedelta_days: {!r}'.format(days))
    try:
        return timedelta64(int_days, 'D')
    except ValueError as e:
        raise ValueError('Failure in timedelta_days; value was {!r}; original error was: {}'.format(days, e))

def get_filelikeobject(filename: str=None, blob: bytes=None) -> BinaryIO:
    """Open a file-like object.

    Guard the use of this function with ``with``.

    Args:
        filename: for specifying via a filename
        blob: for specifying via an in-memory ``bytes`` object

    Returns:
        a :class:`BinaryIO` object"""
    if not filename and (not blob):
        raise ValueError('no filename and no blob')
    if filename and blob:
        raise ValueError('specify either filename or blob')
    if filename:
        return open(filename, 'rb')
    else:
        return io.BytesIO(blob)

def get_file_contents(filename: str=None, blob: bytes=None) -> bytes:
    """Returns the binary contents of a file, or of a BLOB."""
    if not filename and (not blob):
        raise ValueError('no filename and no blob')
    if filename and blob:
        raise ValueError('specify either filename or blob')
    if blob:
        return blob
    with open(filename, 'rb') as f:
        return f.read()

def get_chardet_encoding(binary_contents: bytes) -> Optional[str]:
    """Guess the character set encoding of the specified ``binary_contents``."""
    if not binary_contents:
        return None
    if chardet is None or UniversalDetector is None:
        log.warning('chardet not installed; limits detection of encodings')
        return None
    detector = UniversalDetector()
    for byte_line in binary_contents.split(b'\n'):
        detector.feed(byte_line)
        if detector.done:
            break
    guess = detector.result
    if 'encoding' not in guess:
        log.warning('Something went wrong within chardet; no encoding')
        return None
    return guess['encoding']

def get_file_contents_text(filename: str=None, blob: bytes=None, config: TextProcessingConfig=_DEFAULT_CONFIG) -> str:
    """Returns the string contents of a file, or of a BLOB."""
    binary_contents = get_file_contents(filename=filename, blob=blob)
    if config.encoding:
        try:
            return binary_contents.decode(config.encoding)
        except ValueError:
            pass
    sysdef = sys.getdefaultencoding()
    if sysdef != config.encoding:
        try:
            return binary_contents.decode(sysdef)
        except ValueError:
            pass
    if chardet:
        guess = chardet.detect(binary_contents)
        if guess['encoding']:
            return binary_contents.decode(guess['encoding'])
    raise ValueError('Unknown encoding ({})'.format('filename={}'.format(repr(filename)) if filename else 'blob'))

def get_cmd_output(*args, encoding: str=SYS_ENCODING) -> str:
    """Returns text output of a command."""
    log.debug('get_cmd_output(): args = {!r}', args)
    p = subprocess.Popen(args, stdout=subprocess.PIPE)
    stdout, stderr = p.communicate()
    return stdout.decode(encoding, errors='ignore')

def get_cmd_output_from_stdin(stdint_content_binary: bytes, *args, encoding: str=SYS_ENCODING) -> str:
    """Returns text output of a command, passing binary data in via stdin."""
    p = subprocess.Popen(args, stdin=subprocess.PIPE, stdout=subprocess.PIPE)
    stdout, stderr = p.communicate(input=stdint_content_binary)
    return stdout.decode(encoding, errors='ignore')

def convert_pdf_to_txt(filename: str=None, blob: bytes=None, config: TextProcessingConfig=_DEFAULT_CONFIG) -> str:
    """Converts a PDF file to text.
    Pass either a filename or a binary object."""
    pdftotext = tools['pdftotext']
    if pdftotext:
        if filename:
            return get_cmd_output(pdftotext, filename, '-')
        else:
            return get_cmd_output_from_stdin(blob, pdftotext, '-', '-')
    elif pdfminer:
        with get_filelikeobject(filename, blob) as fp:
            rsrcmgr = pdfminer.pdfinterp.PDFResourceManager()
            retstr = StringIO()
            codec = ENCODING
            laparams = pdfminer.layout.LAParams()
            device = pdfminer.converter.TextConverter(rsrcmgr, retstr, codec=codec, laparams=laparams)
            interpreter = pdfminer.pdfinterp.PDFPageInterpreter(rsrcmgr, device)
            password = ''
            maxpages = 0
            caching = True
            pagenos = set()
            for page in pdfminer.pdfpage.PDFPage.get_pages(fp, pagenos, maxpages=maxpages, password=password, caching=caching, check_extractable=True):
                interpreter.process_page(page)
            text = retstr.getvalue().decode(ENCODING)
        return text
    else:
        raise AssertionError('No PDF-reading tool available')

def availability_pdf() -> bool:
    """Is a PDF-to-text tool available?"""
    pdftotext = tools['pdftotext']
    if pdftotext:
        return True
    elif pdfminer:
        log.warning('PDF conversion: pdftotext missing; using pdfminer (less efficient)')
        return True
    else:
        return False

def gen_xml_files_from_docx(fp: BinaryIO) -> Iterator[str]:
    """Generate XML files (as strings) from a DOCX file.

    Args:
        fp: :class:`BinaryIO` object for reading the ``.DOCX`` file

    Yields:
        the string contents of each individual XML file within the ``.DOCX``
        file

    Raises:
        zipfile.BadZipFile: if the zip is unreadable (encrypted?)"""
    try:
        z = zipfile.ZipFile(fp)
        filelist = z.namelist()
        for filename in filelist:
            if DOCX_HEADER_FILE_REGEX.match(filename):
                yield z.read(filename).decode('utf8')
        yield z.read(DOCX_DOC_FILE)
        for filename in filelist:
            if DOCX_FOOTER_FILE_REGEX.match(filename):
                yield z.read(filename).decode('utf8')
    except zipfile.BadZipFile:
        raise zipfile.BadZipFile('File is not a zip file - encrypted DOCX?')

def docx_text_from_xml_node(node: ElementTree.Element, level: int, config: TextProcessingConfig) -> str:
    """Returns text from an XML node within a DOCX file.

    Args:
        node: an XML node
        level: current level in XML hierarchy (used for recursion; start level
            is 0)
        config: :class:`TextProcessingConfig` control object

    Returns:
        contents as a string"""
    text = ''
    if node.tag == DOCX_TEXT:
        text += node.text or ''
    elif node.tag == DOCX_TAB:
        text += '\t'
    elif node.tag in DOCX_NEWLINES:
        text += '\n'
    elif node.tag == DOCX_NEWPARA:
        text += '\n\n'
    if node.tag == DOCX_TABLE:
        text += '\n\n' + docx_table_from_xml_node(node, level, config)
    else:
        for child in node:
            text += docx_text_from_xml_node(child, level + 1, config)
    return text

def docx_table_from_xml_node(table_node: ElementTree.Element, level: int, config: TextProcessingConfig) -> str:
    """Converts an XML node representing a DOCX table into a textual
    representation.

    Args:
        table_node: XML node
        level: current level in XML hierarchy (used for recursion; start level
            is 0)
        config: :class:`TextProcessingConfig` control object

    Returns:
        string representation"""
    table = CustomDocxTable()
    for row_node in table_node:
        if row_node.tag != DOCX_TABLE_ROW:
            continue
        table.new_row()
        for cell_node in row_node:
            if cell_node.tag != DOCX_TABLE_CELL:
                continue
            table.new_cell()
            for para_node in cell_node:
                text = docx_text_from_xml_node(para_node, level, config)
                if text:
                    table.add_paragraph(text)
    return docx_process_table(table, config)

def docx_process_simple_text(text: str, width: int) -> str:
    """Word-wraps text.

    Args:
        text: text to process
        width: width to word-wrap to (or 0 to skip word wrapping)

    Returns:
        wrapped text"""
    if width:
        return '\n'.join(textwrap.wrap(text, width=width))
    else:
        return text

def docx_docx_iter_block_items(parent: DOCX_CONTAINER_TYPE) -> Iterator[DOCX_BLOCK_ITEM_TYPE]:
    """Iterate through items of a DOCX file.

    See https://github.com/python-openxml/python-docx/issues/40.

    Yield each paragraph and table child within ``parent``, in document order.
    Each returned value is an instance of either :class:`Table` or
    :class:`Paragraph`. ``parent`` would most commonly be a reference to a main
    :class:`Document` object, but also works for a :class:`_Cell` object, which
    itself can contain paragraphs and tables.

    NOTE: uses internals of the ``python-docx`` (``docx``) library; subject to
    change; this version works with ``docx==0.8.5``."""
    if isinstance(parent, docx.document.Document):
        parent_elm = parent.element.body
    elif isinstance(parent, docx.table._Cell):
        parent_elm = parent._tc
    else:
        raise ValueError("something's not right")
    for child in parent_elm.iterchildren():
        if isinstance(child, docx.oxml.text.paragraph.CT_P):
            yield docx.text.paragraph.Paragraph(child, parent)
        elif isinstance(child, docx.oxml.table.CT_Tbl):
            yield docx.table.Table(child, parent)

def docx_docx_gen_text(doc: DOCX_DOCUMENT_TYPE, config: TextProcessingConfig) -> Iterator[str]:
    """Iterate through a DOCX file and yield text.

    Args:
        doc: DOCX document to process
        config: :class:`TextProcessingConfig` control object

    Yields:
        pieces of text (paragraphs)"""
    if in_order:
        for thing in docx_docx_iter_block_items(doc):
            if isinstance(thing, docx.text.paragraph.Paragraph):
                yield docx_process_simple_text(thing.text, config.width)
            elif isinstance(thing, docx.table.Table):
                yield docx_process_table(thing, config)
    else:
        for paragraph in doc.paragraphs:
            yield docx_process_simple_text(paragraph.text, config.width)
        for table in doc.tables:
            yield docx_process_table(table, config)

def convert_odt_to_text(filename: str=None, blob: bytes=None, config: TextProcessingConfig=_DEFAULT_CONFIG) -> str:
    """Converts an OpenOffice ODT file to text.

    Pass either a filename or a binary object."""
    with get_filelikeobject(filename, blob) as fp:
        z = zipfile.ZipFile(fp)
        tree = ElementTree.fromstring(z.read('content.xml'))
        textlist = []
        for element in tree.iter():
            if element.text:
                textlist.append(element.text.strip())
    return '\n\n'.join(textlist)

def convert_html_to_text(filename: str=None, blob: bytes=None, config: TextProcessingConfig=_DEFAULT_CONFIG) -> str:
    """Converts HTML to text."""
    with get_filelikeobject(filename, blob) as fp:
        soup = bs4.BeautifulSoup(fp)
        return soup.get_text()

def convert_rtf_to_text(filename: str=None, blob: bytes=None, config: TextProcessingConfig=_DEFAULT_CONFIG) -> str:
    """Converts RTF to text."""
    unrtf = tools['unrtf']
    if unrtf:
        args = [unrtf, '--text', '--nopict']
        if UNRTF_SUPPORTS_QUIET:
            args.append('--quiet')
        if filename:
            args.append(filename)
            return get_cmd_output(*args)
        else:
            return get_cmd_output_from_stdin(blob, *args)
    elif pyth:
        with get_filelikeobject(filename, blob) as fp:
            doc = pyth.plugins.rtf15.reader.Rtf15Reader.read(fp)
        return pyth.plugins.plaintext.writer.PlaintextWriter.write(doc).getvalue()
    else:
        raise AssertionError('No RTF-reading tool available')

def availability_rtf() -> bool:
    """Is an RTF processor available?"""
    unrtf = tools['unrtf']
    if unrtf:
        return True
    elif pyth:
        log.warning('RTF conversion: unrtf missing; using pyth (less efficient)')
        return True
    else:
        return False

def convert_doc_to_text(filename: str=None, blob: bytes=None, config: TextProcessingConfig=_DEFAULT_CONFIG) -> str:
    """Converts Microsoft Word DOC files to text."""
    antiword = tools['antiword']
    if antiword:
        if filename:
            return get_cmd_output(antiword, '-w', str(config.width), filename)
        else:
            return get_cmd_output_from_stdin(blob, antiword, '-w', str(config.width), '-')
    else:
        raise AssertionError('No DOC-reading tool available')

def convert_anything_to_text(filename: str=None, blob: bytes=None, config: TextProcessingConfig=_DEFAULT_CONFIG) -> str:
    """Convert arbitrary files to text, using ``strings`` or ``strings2``.
    (``strings`` is a standard Unix command to get text from any old rubbish.)"""
    strings = tools['strings'] or tools['strings2']
    if strings:
        if filename:
            return get_cmd_output(strings, filename)
        else:
            return get_cmd_output_from_stdin(blob, strings)
    else:
        raise AssertionError('No fallback string-reading tool available')

def is_text_extractor_available(extension: str) -> bool:
    """Is a text extractor available for the specified extension?"""
    if extension is not None:
        extension = extension.lower()
    info = ext_map.get(extension)
    if info is None:
        return False
    availability = info[AVAILABILITY]
    if type(availability) == bool:
        return availability
    elif callable(availability):
        return availability()
    else:
        raise ValueError('Bad information object for extension: {}'.format(extension))

def set_verbose_logging(verbose: bool) -> None:
    """Chooses basic or verbose logging."""
    if verbose:
        set_loglevel(logging.DEBUG)
    else:
        set_loglevel(logging.INFO)

def debug_sql(sql: str, *args: Any) -> None:
    """Writes SQL and arguments to the log."""
    log.debug('SQL: %s' % sql)
    if args:
        log.debug('Args: %r' % args)

def delimit(x: str, delims: Tuple[str, str]) -> str:
    """Delimits x, using delims[0] (left) and delims[1] (right)."""
    return delims[0] + x + delims[1]

def get_sql_insert(table: str, fieldlist: Sequence[str], delims: Tuple[str, str]=('', '')) -> str:
    """Returns ?-marked SQL for an INSERT statement."""
    return 'INSERT INTO ' + delimit(table, delims) + ' (' + ','.join([delimit(x, delims) for x in fieldlist]) + ') VALUES (' + ','.join(['?'] * len(fieldlist)) + ')'

def get_sql_insert_without_first_field(table: str, fieldlist: Sequence[str], delims: Tuple[str, str]=('', '')) -> str:
    """Returns ?-marked SQL for an INSERT statement, ignoring the first field
    (typically, the PK)."""
    return get_sql_insert(table, fieldlist[1:], delims)

def sql_dequote_string(s: str) -> str:
    """Reverses sql_quote_string."""
    if len(s) < 2:
        return s
    s = s[1:-1]
    return s.replace("''", "'")

def datetime2literal_rnc(d: datetime.datetime, c: Optional[Dict]) -> str:
    """Format a DateTime object as something MySQL will actually accept."""
    dt = d.isoformat(' ')
    return _mysql.string_literal(dt, c)

def full_datatype_to_mysql(d: str) -> str:
    """Converts a full datatype, e.g. INT, VARCHAR(10), VARCHAR(MAX), to a
    MySQL equivalent."""
    d = d.upper()
    s, length = split_long_sqltype(d)
    if d in ['VARCHAR(MAX)', 'NVARCHAR(MAX)']:
        return 'LONGTEXT'
    elif d in ['VARBINARY(MAX)'] or s in ['IMAGE']:
        return 'LONGBLOB'
    else:
        return d

def debug_object(obj: T) -> str:
    """Prints key/value pairs for an object's dictionary."""
    pairs = []
    for k, v in vars(obj).items():
        pairs.append(u'{}={}'.format(k, v))
    return u', '.join(pairs)

def assign_from_list(obj: T, fieldlist: Sequence[str], valuelist: Sequence[any]) -> None:
    """Within "obj", assigns the values from the value list to the fields in
    the fieldlist."""
    if len(fieldlist) != len(valuelist):
        raise AssertionError('assign_from_list: fieldlist and valuelist of different length')
    for i in range(len(valuelist)):
        setattr(obj, fieldlist[i], valuelist[i])

def debug_query_result(rows: Sequence[Any]) -> None:
    """Writes a query result to the log."""
    log.info('Retrieved {} rows', len(rows))
    for i in range(len(rows)):
        log.info('Row {}: {}', i, rows[i])

def iso_string_to_python_datetime(isostring: str) -> Optional[datetime.datetime]:
    """Takes an ISO-8601 string and returns a ``datetime``."""
    if not isostring:
        return None
    return dateutil.parser.parse(isostring)

def validate_pair(ob: Any) -> bool:
    """Does the object have length 2?"""
    try:
        if len(ob) != 2:
            log.warning('Unexpected result: {!r}', ob)
            raise ValueError()
    except ValueError:
        return False
    return True

def contains_unquoted_target(x: str, quote: str='"', target: str='&') -> bool:
    """Checks if ``target`` exists in ``x`` outside quotes (as defined by
    ``quote``). Principal use: from
    :func:`contains_unquoted_ampersand_dangerous_to_windows`."""
    in_quote = False
    for c in x:
        if c == quote:
            in_quote = not in_quote
        elif c == target:
            if not in_quote:
                return True
    return False

def clean_message(message: Message, topmost: bool=False) -> Message:
    """Clean a message of all its binary parts.

    This guts all binary attachments, and returns the message itself for
    convenience."""
    if message.is_multipart():
        if message.get_content_type() != 'message/external-body':
            parts = message.get_payload()
            parts[:] = map(clean_message, parts)
    elif message_is_binary(message):
        if not topmost:
            message = gut_message(message)
    return message

def is_password_valid(plaintextpw: str, storedhash: str) -> bool:
    """Checks if a plaintext password matches a stored hash.

    Uses ``bcrypt``. The stored hash includes its own incorporated salt."""
    if storedhash is None:
        storedhash = ''
    storedhash = str(storedhash)
    if plaintextpw is None:
        plaintextpw = ''
    plaintextpw = str(plaintextpw)
    try:
        h = bcrypt.hashpw(plaintextpw, storedhash)
    except ValueError:
        return False
    return h == storedhash

def make_grammar(dialect: str) -> SqlGrammar:
    """Factory to make an :class:`.SqlGrammar` from the name of an SQL dialect,
    where the name is one of the members of :class:`.SqlaDialectName`."""
    if dialect == SqlaDialectName.MYSQL:
        return mysql_grammar
    elif dialect == SqlaDialectName.MSSQL:
        return mssql_grammar
    else:
        raise AssertionError('Invalid SQL dialect: {}'.format(repr(dialect)))

def debug_form_contents(form: cgi.FieldStorage, to_stderr: bool=True, to_logger: bool=False) -> None:
    """Writes the keys and values of a CGI form to ``stderr``."""
    for k in form.keys():
        text = '{0} = {1}'.format(k, form.getvalue(k))
        if to_stderr:
            sys.stderr.write(text)
        if to_logger:
            log.info(text)

def cgi_method_is_post(environ: Dict[str, str]) -> bool:
    """Determines if the CGI method was ``POST``, given the CGI environment."""
    method = environ.get('REQUEST_METHOD', None)
    if not method:
        return False
    return method.upper() == 'POST'

def get_cgi_parameter_list(form: cgi.FieldStorage, key: str) -> List[str]:
    """Extracts a list of values, all with the same key, from a CGI form."""
    return form.getlist(key)

def get_cgi_parameter_bool(form: cgi.FieldStorage, key: str) -> bool:
    """Extracts a boolean parameter from a CGI form, on the assumption that
    ``"1"`` is ``True`` and everything else is ``False``."""
    return is_1(get_cgi_parameter_str(form, key))

def get_cgi_parameter_bool_or_default(form: cgi.FieldStorage, key: str, default: bool=None) -> Optional[bool]:
    """Extracts a boolean parameter from a CGI form (``"1"`` = ``True``,
    other string = ``False``, absent/zero-length string = default value)."""
    s = get_cgi_parameter_str(form, key)
    if s is None or len(s) == 0:
        return default
    return is_1(s)

def get_cgi_parameter_bool_or_none(form: cgi.FieldStorage, key: str) -> Optional[bool]:
    """Extracts a boolean parameter from a CGI form (``"1"`` = ``True``,
    other string = False, absent/zero-length string = ``None``)."""
    return get_cgi_parameter_bool_or_default(form, key, default=None)

def get_cgi_parameter_int(form: cgi.FieldStorage, key: str) -> Optional[int]:
    """Extracts an integer parameter from a CGI form, or ``None`` if the key is
    absent or the string value is not convertible to ``int``."""
    return get_int_or_none(get_cgi_parameter_str(form, key))

def get_cgi_parameter_float(form: cgi.FieldStorage, key: str) -> Optional[float]:
    """Extracts a float parameter from a CGI form, or None if the key is
    absent or the string value is not convertible to ``float``."""
    return get_float_or_none(get_cgi_parameter_str(form, key))

def get_cgi_parameter_datetime(form: cgi.FieldStorage, key: str) -> Optional[datetime.datetime]:
    """Extracts a date/time parameter from a CGI form. Applies the LOCAL
    timezone if none specified."""
    try:
        s = get_cgi_parameter_str(form, key)
        if not s:
            return None
        d = dateutil.parser.parse(s)
        if d.tzinfo is None:
            d = d.replace(tzinfo=dateutil.tz.tzlocal())
        return d
    except ValueError:
        return None

def get_cgi_parameter_filename_and_file(form: cgi.FieldStorage, key: str) -> Tuple[Optional[str], Optional[bytes]]:
    """Extracts a file's name and contents from a "file" input in a CGI form.
    Returns ``(name, contents)``, or ``(None, None)`` if no such file was
    uploaded."""
    if not key in form:
        log.warning('get_cgi_parameter_file: form has no key {}', key)
        return (None, None)
    fileitem = form[key]
    if isinstance(fileitem, cgi.MiniFieldStorage):
        log.warning('get_cgi_parameter_file: MiniFieldStorage found - did you forget to set enctype="multipart/form-data" in your form?')
        return (None, None)
    if not isinstance(fileitem, cgi.FieldStorage):
        log.warning('get_cgi_parameter_file: no FieldStorage instance with key {} found', key)
        return (None, None)
    if fileitem.filename and fileitem.file:
        return (fileitem.filename, fileitem.file.read())
    if not fileitem.file:
        log.warning('get_cgi_parameter_file: fileitem has no file')
    elif not fileitem.filename:
        log.warning('get_cgi_parameter_file: fileitem has no filename')
    else:
        log.warning('get_cgi_parameter_file: unknown failure reason')
    return (None, None)

def get_png_data_url(blob: Optional[bytes]) -> str:
