def webify(v: Any, preserve_newlines: bool=True) -> str:
    """Converts a value into an HTML-safe ``str`` (formerly, in Python 2:
    ``unicode``).

    Converts value ``v`` to a string; escapes it to be safe in HTML
    format (escaping ampersands, replacing newlines with ``<br>``, etc.).
    Returns ``""`` for blank input."""
    nl = '<br>' if preserve_newlines else ' '
    if v is None:
        return ''
    if not isinstance(v, str):
        v = str(v)
    return cgi.escape(v).replace('\n', nl).replace('\\n', nl)

def bold_if_not_blank(x: Optional[str]) -> str:
    """HTML-emboldens content, unless blank."""
    if x is None:
        return u'{}'.format(x)
    return u'<b>{}</b>'.format(x)

def html_table_from_query(rows: Iterable[Iterable[Optional[str]]], descriptions: Iterable[Optional[str]]) -> str:
    """Converts rows from an SQL query result to an HTML table.
    Suitable for processing output from the defunct function
    ``rnc_db.fetchall_with_fieldnames(sql)``."""
    html = u'<table>\n'
    html += u'<tr>'
    for x in descriptions:
        if x is None:
            x = u''
        html += u'<th>{}</th>'.format(webify(x))
    html += u'</tr>\n'
    for row in rows:
        html += u'<tr>'
        for x in row:
            if x is None:
                x = u''
            html += u'<td>{}</td>'.format(webify(x))
        html += u'<tr>\n'
    html += u'</table>\n'
    return html

def basic_animation(frames=100, interval=30):
    """Plot a basic sine wave with oscillating amplitude"""
    fig = plt.figure()
    ax = plt.axes(xlim=(0, 10), ylim=(-2, 2))
    line, = ax.plot([], [], lw=2)
    x = np.linspace(0, 10, 1000)
    def init():
        line.set_data([], [])
        return (line,)
    def animate(i):
        y = np.cos(i * 0.02 * np.pi) * np.sin(x - i * 0.02 * np.pi)
        line.set_data(x, y)
        return (line,)
    return animation.FuncAnimation(fig, animate, init_func=init, frames=frames, interval=interval)

def _included_frames(frame_list, frame_format):
    """frame_list should be a list of filenames"""
    return INCLUDED_FRAMES.format(Nframes=len(frame_list), frame_dir=os.path.dirname(frame_list[0]), frame_format=frame_format)

def sort_by_dependencies(exts, retry=None):
    """Calculate the Feature Extractor Resolution Order.

    """
    sorted_ext, features_from_sorted = ([], set())
    pending = [(e, 0) for e in exts]
    retry = len(exts) * 100 if retry is None else retry
    while pending:
        ext, cnt = pending.pop(0)
        if not isinstance(ext, Extractor) and (not issubclass(ext, Extractor)):
            msg = 'Only Extractor instances are allowed. Found {}.'
            raise TypeError(msg.format(type(ext)))
        deps = ext.get_dependencies()
        if deps.difference(features_from_sorted):
            if cnt + 1 > retry:
                msg = 'Maximun retry ({}) to sort achieved from extractor {}.'
                raise RuntimeError(msg.format(retry, type(ext)))
            pending.append((ext, cnt + 1))
        else:
            sorted_ext.append(ext)
            features_from_sorted.update(ext.get_features())
    return tuple(sorted_ext)

def fap_baluev(Z, fmax, t, y, dy, normalization='standard'):
    """Alias-free approximation to false alarm probability

    (Eqn 6 of Baluev 2008)"""
    cdf = cdf_single(Z, len(t), normalization)
    tau = tau_davies(Z, fmax, t, y, dy, normalization=normalization)
    return 1 - cdf * np.exp(-tau)

