def _(obj):
    """ISO 8601 format. Interprets naive datetime as UTC with zulu suffix."""
    tz_offset = obj.utcoffset()
    if not tz_offset or tz_offset == UTC_ZERO:
        iso_datetime = obj.strftime('%Y-%m-%dT%H:%M:%S.%fZ')
    else:
        iso_datetime = obj.isoformat()
    return iso_datetime

def create_key_filter(properties: Dict[str, list]) -> List[Tuple]:
    """Generate combinations of key, value pairs for each key in properties.

    Examples
    --------
    properties = {'ent': ['geo_rev', 'supply_chain'], 'own', 'fi'}
    >> create_key_filter(properties)
      --> [('ent', 'geo_rev'), ('ent', 'supply_chain'), ('own', 'fi')]"""
    combinations = (product([k], v) for k, v in properties.items())
    return chain.from_iterable(combinations)

def create_indexer(indexes: list):
    """Create indexer function to pluck values from list."""
    if len(indexes) == 1:
        index = indexes[0]
        return lambda x: (x[index],)
    else:
        return itemgetter(*indexes)

def get_hash_of_dirs(directory):
    """Recursively hash the contents of the given directory.

    Args:
        directory (str): The root directory we want to hash.

    Returns:
        A hash of all the contents in the directory."""
    import hashlib
    sha = hashlib.sha512()
    if not os.path.exists(directory):
        return -1
    for root, _, files in os.walk(directory):
        for name in files:
            filepath = local.path(root) / name
            if filepath.exists():
                with open(filepath, 'rb') as next_file:
                    for line in next_file:
                        sha.update(line)
    return sha.hexdigest()

def import_name_or_class(name):
    """Import an obect as either a fully qualified, dotted name,"""
    if isinstance(name, str):
        module_name, object_name = name.rsplit('.', 1)
        mod = __import__(module_name)
        components = name.split('.')
        for comp in components[1:]:
            mod = getattr(mod, comp)
        return mod
    else:
        return name

