def get_all_sensor_codes(si, wild_sensor_code):
    """Get all sensor sensor_codes that match a wild sensor code

    :param si: dict, sensor index json dictionary
    :param wild_sensor_code: str, a sensor code with "*" for wildcards (e.g. ACCX-*-L2C-*)
    :return:"""
    mtype_and_ory, x, y, z = wild_sensor_code.split('-')
    if mtype_and_ory == '*':
        mtypes = list(si)
    elif mtype_and_ory[-1] in 'XYZ' and 'ACCX' not in si:
        mtypes = [mtype_and_ory[:-1]]
    else:
        mtypes = [mtype_and_ory]
    all_sensor_codes = []
    for mtype in mtypes:
        for m_number in si[mtype]:
            if x in ['*', si[mtype][m_number]['X-CODE']] and y in ['*', si[mtype][m_number]['Y-CODE']] and (z in ['*', si[mtype][m_number]['Z-CODE']]):
                cc = get_sensor_code_by_number(si, mtype, m_number)
                all_sensor_codes.append(cc)
    return all_sensor_codes

def get_sensor_code_by_number(si, mtype, sensor_number, quiet=False):
    """Given a sensor number, get the full sensor code (e.g. ACCX-UB1-L2C-M)

    :param si: dict, sensor index json dictionary
    :param mtype: str, sensor type
    :param sensor_number: int, number of sensor
    :param quiet: bool, if true then return None if not found
    :return: str or None, sensor_code: a sensor code (e.g. ACCX-UB1-L2C-M)"""
    try:
        if 'Orientation' in si[mtype][sensor_number]:
            orientation = si[mtype][sensor_number]['Orientation']
        else:
            orientation = ''
        return '%s%s-%s-%s-%s' % (mtype, orientation, si[mtype][sensor_number]['X-CODE'], si[mtype][sensor_number]['Y-CODE'], si[mtype][sensor_number]['Z-CODE'])
    except KeyError:
        if quiet:
            return None
        raise

def get_mtype_and_number_from_code(si, sensor_code):
    """Given a sensor sensor_code, get motion type and sensor number

    :param si: dict, sensor index json dictionary
    :param sensor_code: str, a sensor code (e.g. ACCX-UB1-L2C-M)
    :return:"""
    mtype_and_ory, x, y, z = sensor_code.split('-')
    if mtype_and_ory[-1] in 'XYZ' and 'ACCX' not in si:
        mtype = mtype_and_ory[:-1]
    else:
        mtype = mtype_and_ory
    for m_number in si[mtype]:
        cc = get_sensor_code_by_number(si, mtype, m_number)
        if cc == sensor_code:
            return (mtype, m_number)
    return (None, None)

def PCExtension(*args, **kwargs):
    """Parameters
    ==========
    template_regexps: list of 3-tuples
        e.g. [(pattern1, target1, subsd1), ...], used to generate
        templated code
    pass_extra_compile_args: bool
        should ext.extra_compile_args be passed along? default: False"""
    vals = {}
    intercept = {'build_callbacks': (), 'link_ext': True, 'build_files': (), 'dist_files': (), 'template_regexps': [], 'pass_extra_compile_args': False, 'pycompilation_compile_kwargs': {}, 'pycompilation_link_kwargs': {}}
    for k, v in intercept.items():
        vals[k] = kwargs.pop(k, v)
    intercept2 = {'logger': None, 'only_update': True}
    for k, v in intercept2.items():
        vck = kwargs.pop(k, v)
        vck = vals['pycompilation_compile_kwargs'].pop(k, vck)
        vck = vck or vals['pycompilation_link_kwargs'].pop(k, vck)
        vals[k] = vck
    instance = Extension(*args, **kwargs)
    if vals['logger'] is True:
        import logging
        logging.basicConfig(level=logging.DEBUG)
        vals['logger'] = logging.getLogger('PCExtension')
    for k, v in vals.items():
        setattr(instance, k, v)
    return instance

def _copy_or_render_source(ext, f, output_dir, render_callback, skip_copy=False):
    """Tries to do regex match for each (pattern, target, subsd) tuple
    in ext.template_regexps for file f."""
    dirname = os.path.dirname(f)
    filename = os.path.basename(f)
    for pattern, target, subsd in ext.template_regexps:
        if re.match(pattern, filename):
            tgt = os.path.join(dirname, re.sub(pattern, target, filename))
            rw = MetaReaderWriter('.metadata_subsd')
            try:
                prev_subsd = rw.get_from_metadata_file(output_dir, f)
            except (FileNotFoundError, KeyError):
                prev_subsd = None
            render_callback(get_abspath(f), os.path.join(output_dir, tgt), subsd, only_update=ext.only_update, prev_subsd=prev_subsd, create_dest_dirs=True, logger=ext.logger)
            rw.save_to_metadata_file(output_dir, f, subsd)
            return tgt
    else:
        if not skip_copy:
            copy(f, os.path.join(output_dir, os.path.dirname(f)), only_update=ext.only_update, dest_is_dir=True, create_dest_dirs=True, logger=ext.logger)
        return f

def render_python_template_to(src, dest, subsd, only_update=False, prev_subsd=None, create_dest_dirs=True, logger=None):
    """Overload this function if you want to use a template engine such as
    e.g. mako."""
    if only_update:
        if subsd == prev_subsd:
            if not missing_or_other_newer(dest, src):
                if logger:
                    msg = 'Did not re-render {}. (destination newer + same dict)'
                    logger.info(msg.format(src))
                return
    with open(src, 'rt') as ifh:
        data = ifh.read()
    if create_dest_dirs:
        dest_dir = os.path.dirname(dest)
        if not os.path.exists(dest_dir):
            make_dirs(dest_dir)
    with open(dest, 'wt') as ofh:
        ofh.write(data % subsd)

def _set_log_format(color, include_caller):
    """Set log format
    :param color: Log message is colored
    :param include_caller: At the end, put a [caller:line-of-code], e.g. [script:123]
    :return: string of log format"""
    level_name = '* %(levelname)1s'
    time = '%(asctime)s,%(msecs)03d'
    message = '%(message)s'
    color_start = '%(color)s'
    color_end = '%(end_color)s'
    caller = '[%(module)s:%(lineno)d]'
    if color:
        if include_caller:
            return '{}{}{}  {}  {} {}'.format(color_start, level_name, color_end, time, message, caller)
        else:
            return '{}{}{}  {}  {}'.format(color_start, level_name, color_end, time, message)
    elif include_caller:
        return '{}  {}  {} {}'.format(level_name, time, message, caller)
    else:
        return '{}  {}  {}'.format(level_name, time, message)

def format_repr(obj, attributes) -> str:
