def prepend_status(func):
    """Prepends the output of `func` with the status."""
    @ft.wraps(func)
    def wrapper(self, *args, **kwargs):
        """Wrapper stub."""
        res = func(self, *args, **kwargs)
        if self.status is not StepResult.UNSET:
            res = '[{status}]'.format(status=self.status.name) + res
        return res
    return wrapper

def notify_step_begin_end(func):
    """Print the beginning and the end of a `func`."""
    @ft.wraps(func)
    def wrapper(self, *args, **kwargs):
        """Wrapper stub."""
        cls = self.__class__
        on_step_begin = cls.ON_STEP_BEGIN
        on_step_end = cls.ON_STEP_END
        for begin_listener in on_step_begin:
            begin_listener(self)
        res = func(self, *args, **kwargs)
        for end_listener in on_step_end:
            end_listener(self, func)
        return res
    return wrapper

def log_before_after(name: str, desc: str):
    """Log customized stirng before & after running func."""
    def func_decorator(f):
        """Wrapper stub."""
        @ft.wraps(f)
        def wrapper(*args, **kwargs):
            """Wrapper stub."""
            LOG.info('\n%s - %s', name, desc)
            res = f(*args, **kwargs)
            if StepResult.ERROR not in res:
                LOG.info('%s - OK\n', name)
            else:
                LOG.error('%s - ERROR\n', name)
            return res
        return wrapper
    return func_decorator

def euclid(a, b):
    """returns the Greatest Common Divisor of a and b"""
    a = abs(a)
    b = abs(b)
    if a < b:
        a, b = (b, a)
    while b != 0:
        a, b = (b, a % b)
    return a

def coPrime(l):
    """returns 'True' if the values in the list L are all co-prime
    otherwise, it returns 'False'."""
    for i, j in combinations(l, 2):
        if euclid(i, j) != 1:
            return False
    return True

def extendedEuclid(a, b):
    """return a tuple of three values: x, y and z, such that x is
    the GCD of a and b, and x = y * a + z * b"""
    if a == 0:
        return (b, 0, 1)
    else:
        g, y, x = extendedEuclid(b % a, a)
        return (g, x - b // a * y, y)

def modInv(a, m):
    """returns the multiplicative inverse of a in modulo m as a
    positive value between zero and m-1"""
    if coPrime([a, m]):
        linearCombination = extendedEuclid(a, m)
        return linearCombination[1] % m
    else:
        return 0

def extractTwos(m):
    """m is a positive integer. A tuple (s, d) of integers is returned
    such that m = (2 ** s) * d."""
    assert m >= 0
    i = 0
    while m & 2 ** i == 0:
        i += 1
    return (i, m >> i)

def modExp(a, d, n):
    """returns a ** d (mod n)"""
    assert d >= 0
    assert n >= 0
    base2D = int2baseTwo(d)
    base2DLength = len(base2D)
    modArray = []
    result = 1
    for i in range(1, base2DLength + 1):
        if i == 1:
            modArray.append(a % n)
        else:
            modArray.append(modArray[i - 2] ** 2 % n)
    for i in range(0, base2DLength):
        if base2D[i] == 1:
            result *= base2D[i] * modArray[i]
    return result % n

def primeSieve(k):
    """return a list with length k + 1, showing if list[i] == 1, i is a prime
    else if list[i] == 0, i is a composite, if list[i] == -1, not defined"""
    def isPrime(n):
        """return True is given number n is absolutely prime,
        return False is otherwise."""
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True
    result = [-1] * (k + 1)
    for i in range(2, int(k + 1)):
        if isPrime(i):
            result[i] = 1
        else:
            result[i] = 0
    return result

def newKey(a, b, k):
    """Try to find two large pseudo primes roughly between a and b.
    Generate public and private keys for RSA encryption.
    Raises ValueError if it fails to find one"""
    try:
        p = findAPrime(a, b, k)
        while True:
            q = findAPrime(a, b, k)
            if q != p:
                break
    except:
        raise ValueError
    n = p * q
    m = (p - 1) * (q - 1)
    while True:
        e = random.randint(1, m)
        if coPrime([e, m]):
            break
    d = modInv(e, m)
    return (n, e, d)

def decrypt(secret, modN, d, blockSize):
    """reverse function of encrypt"""
    numBlocks = [modExp(blocks, d, modN) for blocks in secret]
    numList = blocks2numList(numBlocks, blockSize)
    return numList2string(numList)

