def output_to_table(obj, olist='inputs', oformat='latex', table_ends=False, prefix=''):
    """Compile the properties to a table.

    :param olist: list, Names of the parameters to be in the output table
    :param oformat: str, The type of table to be output
    :param table_ends: bool, Add ends to the table
    :param prefix: str, A string to be added to the start of each parameter name
    :return: para, str, table as a string"""
    para = ''
    property_list = []
    if olist == 'inputs':
        property_list = obj.inputs
    elif olist == 'all':
        for item in obj.__dict__:
            if '_' != item[0]:
                property_list.append(item)
    for item in property_list:
        if hasattr(obj, item):
            value = getattr(obj, item)
            value_str = format_value(value)
            if oformat == 'latex':
                delimeter = ' & '
            else:
                delimeter = ','
            para += '{0}{1}{2}\\\\\n'.format(prefix + format_name(item), delimeter, value_str)
    if table_ends:
        para = add_table_ends(para, oformat)
    return para

def format_value(value, sf=3):
    """convert a parameter value into a formatted string with certain significant figures

    :param value: the value to be formatted
    :param sf: number of significant figures
    :return: str"""
    if isinstance(value, str):
        return value
    elif isinstance(value, list) or isinstance(value, np.ndarray):
        value = list(value)
        for i in range(len(value)):
            vv = format_value(value[i])
            value[i] = vv
        return '[' + ', '.join(value) + ']'
    elif value is None:
        return 'N/A'
    else:
        fmt_str = '{0:.%ig}' % sf
        return fmt_str.format(value)

def ftp_listing_paths(ftpconn: FTP, root: str) -> Iterable[str]:
    """Generate the full file paths from a root path."""
    for current_path, dirs, files in ftp_walk(ftpconn, root):
        yield from (os.path.join(current_path, file) for file in files)

def ftp_walk(ftpconn: FTP, rootpath=''):
    """Recursively traverse an ftp directory to discovery directory listing."""
    current_directory = rootpath
    try:
        directories, files = directory_listing(ftpconn, current_directory)
    except ftplib.error_perm:
        return
    yield (current_directory, directories, files)
    for name in directories:
        new_path = os.path.join(current_directory, name)
        for entry in ftp_walk(ftpconn, rootpath=new_path):
            yield entry
    else:
        return

def parse_line(line: str, char_index=0) -> Tuple[ListingType, str]:
