def cached(func):
    """Memoize a function result."""
    ret = None
    def call_or_cache(*args, **kwargs):
        nonlocal ret
        if ret is None:
            ret = func(*args, **kwargs)
        return ret
    return call_or_cache

def time_indices(npts, dt, start, end, index):
    """Determine the new start and end indices of the time series.

    :param npts: Number of points in original time series
    :param dt: Time step of original time series
    :param start: int or float, optional, New start point
    :param end: int or float, optional, New end point
    :param index: bool, optional, if False then start and end are considered values in time.
    :return: tuple, start index, end index"""
    if index is False:
        if end != -1:
            e_index = int(end / dt) + 1
        else:
            e_index = end
        s_index = int(start / dt)
    else:
        s_index = start
        e_index = end
    if e_index > npts:
        raise exceptions.ModelWarning('Cut point is greater than time series length')
    return (s_index, e_index)

def in_builddir(sub='.'):
    """Decorate a project phase with a local working directory change.

    Args:
        sub: An optional subdirectory to change into."""
    from functools import wraps
    def wrap_in_builddir(func):
        """Wrap the function for the new build directory."""
        @wraps(func)
        def wrap_in_builddir_func(self, *args, **kwargs):
            """The actual function inside the wrapper for the new builddir."""
            p = local.path(self.builddir) / sub
            if not p.exists():
                LOG.error('%s does not exist.', p)
            if p == local.cwd:
                LOG.debug('CWD already is %s', p)
                return func(self, *args, *kwargs)
            with local.cwd(p):
                return func(self, *args, **kwargs)
        return wrap_in_builddir_func
    return wrap_in_builddir

