    and creates a BehindSubscription entry for them."""
    subscriptions = Subscription.objects.filter(active=True, completed=False, process_status=0).values_list('id', flat=True)
    for subscription_id in subscriptions.iterator():
        calculate_subscription_lifecycle.delay(str(subscription_id))

def internal_only(view_func):
    """A view decorator which blocks access for requests coming through the load balancer."""
    @functools.wraps(view_func)
    def wrapper(request, *args, **kwargs):
        forwards = request.META.get('HTTP_X_FORWARDED_FOR', '').split(',')
        if len(forwards) > 1:
            raise PermissionDenied()
        return view_func(request, *args, **kwargs)
    return wrapper

def as_index(keys, axis=semantics.axis_default, base=False, stable=True, lex_as_struct=False):
    """casting rules for a keys object to an index object

    the preferred semantics is that keys is a sequence of key objects,
    except when keys is an instance of tuple,
    in which case the zipped elements of the tuple are the key objects

    the axis keyword specifies the axis which enumerates the keys
    if axis is None, the keys array is flattened
    if axis is 0, the first axis enumerates the keys
    which of these two is the default depends on whether backwards_compatible == True

    if base==True, the most basic index possible is constructed.
    this avoids an indirect sort; if it isnt required, this has better performance"""
    if isinstance(keys, Index):
        if type(keys) is BaseIndex and base == False:
            keys = keys.keys
        else:
            return keys
    if isinstance(keys, tuple):
        if lex_as_struct:
            keys = as_struct_array(*keys)
        else:
            return LexIndex(keys, stable)
    try:
        keys = np.asarray(keys)
    except:
        raise TypeError('Given object does not form a valid set of keys')
    if axis is None:
        keys = keys.flatten()
    if keys.ndim == 1:
        if base:
            return BaseIndex(keys)
        else:
            return Index(keys, stable=stable)
    else:
        return ObjectIndex(keys, axis, stable=stable)

def incidence(boundary):
    """given an Nxm matrix containing boundary info between simplices,
    compute indidence info matrix
    not very reusable; should probably not be in this lib"""
    return GroupBy(boundary).split(np.arange(boundary.size) // boundary.shape[1])

def any_unique(keys, axis=semantics.axis_default):
    """returns true if any of the keys is unique"""
    index = as_index(keys, axis)
    return np.any(index.count == 1)

def _set_concatenate(sets):
    """concatenate indexable objects.

    Parameters
    ----------
    sets : iterable of indexable objects

    Returns
    -------
    indexable object

    handles both arrays and tuples of arrays"""
    def con(set):
        try:
            return np.concatenate([s for s in sets if len(s)])
        except ValueError:
            return set[0]
    if any((not isinstance(s, tuple) for s in sets)):
        return con(sets)
    else:
        return tuple((con(s) for s in zip(*sets)))

