def get_option_choices(opt_name, opt_value, default_value, all_choices):
    """Generate possible choices for the option `opt_name`
    limited to `opt_value` value with default value
    as `default_value`"""
    choices = []
    if isinstance(opt_value, six.string_types):
        choices = [opt_value]
    elif isinstance(opt_value, (list, tuple)):
        choices = list(opt_value)
    elif opt_value is None:
        choices = default_value
    else:
        raise InvalidOption('Option %s has invalid value: %s' % (opt_name, opt_value))
    if 'all' in choices:
        choices = all_choices
    for item in choices:
        if item not in all_choices:
            raise InvalidOption('Choices of option %s contains invalid item: %s' % (opt_name, item))
    return choices

def more_data(pipe_out):
    """Check if there is more data left on the pipe

    :param pipe_out: The os pipe_out
    :rtype: bool"""
    r, _, _ = select.select([pipe_out], [], [], 0)
    return bool(r)

def read_pipe(pipe_out):
    """Read data on a pipe

    Used to capture stdout data produced by libiperf

    :param pipe_out: The os pipe_out
    :rtype: unicode string"""
    out = b''
    while more_data(pipe_out):
        out += os.read(pipe_out, 1024)
    return out.decode('utf-8')

def load():
    """Read data from a text file on disk."""
    datadir = os.path.dirname(__file__)
    filename = os.path.join(datadir, 'angelier_data.txt')
    data = []
    with open(filename, 'r') as infile:
        for line in infile:
            if line.startswith('#'):
                continue
            strike, dip, rake = line.strip().split()
            if rake[-1].isalpha():
                strike, dip, rake = mplstereonet.parse_rake(strike, dip, rake)
            else:
                strike, dip = mplstereonet.parse_strike_dip(strike, dip)
                azimuth = float(rake)
                rake = mplstereonet.azimuth2rake(strike, dip, azimuth)
            data.append([strike, dip, rake])
    strike, dip, rake = zip(*data)
    return (strike, dip, rake)

def _kamb_count(cos_dist, sigma=3):
    """Original Kamb kernel function (raw count within radius)."""
    n = float(cos_dist.size)
    dist = _kamb_radius(n, sigma)
    count = (cos_dist >= dist).astype(float)
    return (count, _kamb_units(n, dist))

def _schmidt_count(cos_dist, sigma=None):
    """Schmidt (a.k.a. 1%) counting kernel function."""
    radius = 0.01
    count = (1 - cos_dist <= radius).astype(float)
    count = 0.5 / count.size + count
    return (count, cos_dist.size * radius)

