def modify_path():
    """Modify the module search path."""
    if os.name != 'nt':
        return
    path = os.environ.get('PATH')
    if path is None:
        return
    try:
        extra_dll_dir = pkg_resources.resource_filename('bezier', 'extra-dll')
        if os.path.isdir(extra_dll_dir):
            os.environ['PATH'] = path + os.pathsep + extra_dll_dir
    except ImportError:
        pass

def _update_flags(compiler_flags, remove_flags=()):
    """Update a given set of compiler flags.

    Args:
        compiler_flags (List[str]): Existing flags associated with a compiler.
        remove_flags (Optional[Container[str]]): A container of flags to remove
            that will override any of the defaults.

    Returns:
        List[str]: The modified list (i.e. some flags added and some removed)."""
    for flag in GFORTRAN_SHARED_FLAGS:
        if flag not in compiler_flags:
            compiler_flags.append(flag)
    if DEBUG_ENV in os.environ:
        to_add = GFORTRAN_DEBUG_FLAGS
        to_remove = GFORTRAN_OPTIMIZE_FLAGS
    else:
        to_add = GFORTRAN_OPTIMIZE_FLAGS
        if os.environ.get(WHEEL_ENV) is None:
            to_add += (GFORTRAN_NATIVE_FLAG,)
        to_remove = GFORTRAN_DEBUG_FLAGS
    for flag in to_add:
        if flag not in compiler_flags:
            compiler_flags.append(flag)
    return [flag for flag in compiler_flags if not (flag in to_remove or flag in remove_flags)]

def polynomial_norm(coeffs):
    """Computes :math:`L_2` norm of polynomial on :math:`\\left[0, 1\\right]`.

    We have

    .. math::

       \\left\\langle f, f \\right\\rangle = \\sum_{i, j}
           \\int_0^1 c_i c_j x^{i + j} \\, dx = \\sum_{i, j}
           \\frac{c_i c_j}{i + j + 1} = \\sum_{i} \\frac{c_i^2}{2 i + 1}
           + 2 \\sum_{j > i} \\frac{c_i c_j}{i + j + 1}.

    Args:
        coeffs (numpy.ndarray): ``d + 1``-array of coefficients in monomial /
            power basis.

    Returns:
        float: The :math:`L_2` norm of the polynomial."""
    num_coeffs, = coeffs.shape
    result = 0.0
    for i in six.moves.xrange(num_coeffs):
        coeff_i = coeffs[i]
        result += coeff_i * coeff_i / (2.0 * i + 1.0)
        for j in six.moves.xrange(i + 1, num_coeffs):
            coeff_j = coeffs[j]
            result += 2.0 * coeff_i * coeff_j / (i + j + 1.0)
    return np.sqrt(result)

def poly_to_power_basis(bezier_coeffs):
    """Convert a B |eacute| zier curve to polynomial in power basis.

    .. note::

       This assumes, but does not verify, that the "B |eacute| zier
       degree" matches the true degree of the curve. Callers can
       guarantee this by calling :func:`.full_reduce`.

    Args:
        bezier_coeffs (numpy.ndarray): A 1D array of coefficients in
            the Bernstein basis.

    Returns:
        numpy.ndarray: 1D array of coefficients in monomial basis.

    Raises:
        .UnsupportedDegree: If the degree of the curve is not among
            0, 1, 2 or 3."""
    num_coeffs, = bezier_coeffs.shape
    if num_coeffs == 1:
        return bezier_coeffs
    elif num_coeffs == 2:
        coeff0, coeff1 = bezier_coeffs
        return np.asfortranarray([coeff0, coeff1 - coeff0])
    elif num_coeffs == 3:
        coeff0, coeff1, coeff2 = bezier_coeffs
        return np.asfortranarray([coeff0, 2.0 * (coeff1 - coeff0), coeff2 - 2.0 * coeff1 + coeff0])
    elif num_coeffs == 4:
        coeff0, coeff1, coeff2, coeff3 = bezier_coeffs
        return np.asfortranarray([coeff0, 3.0 * (coeff1 - coeff0), 3.0 * (coeff2 - 2.0 * coeff1 + coeff0), coeff3 - 3.0 * coeff2 + 3.0 * coeff1 - coeff0])
    else:
        raise _helpers.UnsupportedDegree(num_coeffs - 1, supported=(0, 1, 2, 3))

def _wiggle_interval(value, wiggle=0.5 ** 44):
    """Check if ``value`` is in :math:`\\left[0, 1\\right]`.

    Allows a little bit of wiggle room outside the interval. Any value
    within ``wiggle`` of ``0.0` will be converted to ``0.0` and similar
    for ``1.0``.

    .. note::

       There is also a Fortran implementation of this function, which
       will be used if it can be built.

    Args:
        value (float): Value to check in interval.
        wiggle (Optional[float]): The amount of wiggle room around the
            the endpoints ``0.0`` and ``1.0``.

    Returns:
        Tuple[float, bool]: Pair of

        * The ``value`` if it's in the interval, or ``0`` or ``1``
          if the value lies slightly outside. If the ``value`` is
          too far outside the unit interval, will be NaN.
        * Boolean indicating if the ``value`` is inside the unit interval."""
    if -wiggle < value < wiggle:
        return (0.0, True)
    elif wiggle <= value <= 1.0 - wiggle:
        return (value, True)
    elif 1.0 - wiggle < value < 1.0 + wiggle:
        return (1.0, True)
    else:
        return (np.nan, False)

def get_desired():
    """Populate ``DESIRED_TEMPLATE`` with public members.

    If there are no members, does nothing.

    Returns:
        str: The "desired" contents of ``bezier.rst``."""
    public_members = get_public_members()
    if public_members:
        members = '\n    :members: {}'.format(', '.join(public_members))
    else:
        members = ''
    return DESIRED_TEMPLATE.format(members=members)

def clean(session):
    """Clean up build files.

    Cleans up all artifacts that might get created during
    other ``nox`` sessions.

    There is no need for the session to create a ``virtualenv``
    here (we are just pretending to be ``make``)."""
    clean_dirs = (get_path('.cache'), get_path('.coverage'), get_path('.pytest_cache'), get_path('__pycache__'), get_path('build'), get_path('dist'), get_path('docs', '__pycache__'), get_path('docs', 'build'), get_path('scripts', 'macos', '__pycache__'), get_path('scripts', 'macos', 'dist_wheels'), get_path('scripts', 'macos', 'fixed_wheels'), get_path('src', 'bezier.egg-info'), get_path('src', 'bezier', '__pycache__'), get_path('src', 'bezier', 'extra-dll'), get_path('src', 'bezier', 'lib'), get_path('tests', '__pycache__'), get_path('tests', 'functional', '__pycache__'), get_path('tests', 'unit', '__pycache__'), get_path('wheelhouse'))
    clean_globs = (get_path('.coverage'), get_path('*.mod'), get_path('*.pyc'), get_path('src', 'bezier', '*.pyc'), get_path('src', 'bezier', '*.pyd'), get_path('src', 'bezier', '*.so'), get_path('src', 'bezier', 'quadpack', '*.o'), get_path('src', 'bezier', '*.o'), get_path('tests', '*.pyc'), get_path('tests', 'functional', '*.pyc'), get_path('tests', 'unit', '*.pyc'))
    for dir_path in clean_dirs:
        session.run(shutil.rmtree, dir_path, ignore_errors=True)
