        _ = load_yaml_configuration(config_path, translator=PipelineTranslator())
    elif os.path.splitext(config_path)[1] == '.py':
        _ = load_python_configuration(config_path)
    else:
        raise ValueError('Unknown configuration extension: %r' % os.path.splitext(config_path)[1])
    yield

def transform_source(text):
    """Replaces instances of

        repeat n:
    by

        for __VAR_i in range(n):

    where __VAR_i is a string that does not appear elsewhere
    in the code sample."""
    loop_keyword = 'repeat'
    nb = text.count(loop_keyword)
    if nb == 0:
        return text
    var_names = get_unique_variable_names(text, nb)
    toks = tokenize.generate_tokens(StringIO(text).readline)
    result = []
    replacing_keyword = False
    for toktype, tokvalue, _, _, _ in toks:
        if toktype == tokenize.NAME and tokvalue == loop_keyword:
            result.extend([(tokenize.NAME, 'for'), (tokenize.NAME, var_names.pop()), (tokenize.NAME, 'in'), (tokenize.NAME, 'range'), (tokenize.OP, '(')])
            replacing_keyword = True
        elif replacing_keyword and tokvalue == ':':
            result.extend([(tokenize.OP, ')'), (tokenize.OP, ':')])
            replacing_keyword = False
        else:
            result.append((toktype, tokvalue))
    return tokenize.untokenize(result)

def is_related_to(item, app_id, app_ver=None):
    """Return True if the item relates to the given app_id (and app_ver, if passed)."""
    versionRange = item.get('versionRange')
    if not versionRange:
        return True
    for vR in versionRange:
        if not vR.get('targetApplication'):
            return True
        if get_related_targetApplication(vR, app_id, app_ver) is not None:
            return True
    return False

def get_related_targetApplication(vR, app_id, app_ver):
    """Return the first matching target application in this version range.
    Returns None if there are no target applications or no matching ones."""
    targetApplication = vR.get('targetApplication')
    if not targetApplication:
        return None
    for tA in targetApplication:
        guid = tA.get('guid')
        if not guid or guid == app_id:
            if not app_ver:
                return tA
            if between(version_int(app_ver), '0', tA.get('maxVersion', '*')):
                return tA
    return None

def write_plugin_items(xml_tree, records, app_id, api_ver=3, app_ver=None):
    """Generate the plugin blocklists.

    <pluginItem blockID="p422">
        <match name="filename" exp="JavaAppletPlugin\\.plugin"/>
        <versionRange minVersion="Java 7 Update 16"
                      maxVersion="Java 7 Update 24"
                      severity="0" vulnerabilitystatus="1">
            <targetApplication id="{ec8030f7-c20a-464f-9b0e-13a3a9e97384}">
                <versionRange minVersion="17.0" maxVersion="*"/>
            </targetApplication>
        </versionRange>
    </pluginItem>"""
    if not records:
        return
    pluginItems = etree.SubElement(xml_tree, 'pluginItems')
    for item in records:
        for versionRange in item.get('versionRange', []):
            if not versionRange.get('targetApplication'):
                add_plugin_item(pluginItems, item, versionRange, app_id=app_id, api_ver=api_ver, app_ver=app_ver)
            else:
                targetApplication = get_related_targetApplication(versionRange, app_id, app_ver)
                if targetApplication is not None:
                    add_plugin_item(pluginItems, item, versionRange, targetApplication, app_id=app_id, api_ver=api_ver, app_ver=app_ver)

def translate(source, dictionary):
    """A dictionary with a one-to-one translation of keywords is used
    to provide the transformation."""
    toks = tokenize.generate_tokens(StringIO(source).readline)
    result = []
    for toktype, tokvalue, _, _, _ in toks:
        if toktype == tokenize.NAME and tokvalue in dictionary:
            result.append((toktype, dictionary[tokvalue]))
        else:
            result.append((toktype, tokvalue))
    return tokenize.untokenize(result)

def __experimental_range(start, stop, var, cond, loc={}):
    """Utility function made to reproduce range() with unit integer step
    but with the added possibility of specifying a condition
    on the looping variable  (e.g. var % 2  == 0)"""
    locals().update(loc)
    if start < stop:
        for __ in range(start, stop):
            locals()[var] = __
            if eval(cond, globals(), locals()):
                yield __
    else:
        for __ in range(start, stop, -1):
            locals()[var] = __
            if eval(cond, globals(), locals()):
                yield __

def create_for(line, search_result):
    """Create a new "for loop" line as a replacement for the original code.
    """
    try:
        return line.format(search_result.group('indented_for'), search_result.group('var'), search_result.group('start'), search_result.group('stop'), search_result.group('cond'))
    except IndexError:
        return line.format(search_result.group('indented_for'), search_result.group('var'), search_result.group('start'), search_result.group('stop'))

def get_auth():
    """Return a tuple for authenticating a user

    If not successful raise ``AgileError``."""
    auth = get_auth_from_env()
    if auth[0] and auth[1]:
        return auth
    home = os.path.expanduser('~')
    config = os.path.join(home, '.gitconfig')
    if not os.path.isfile(config):
        raise GithubException('No .gitconfig available')
    parser = configparser.ConfigParser()
    parser.read(config)
    if 'user' in parser:
        user = parser['user']
        if 'username' not in user:
            raise GithubException('Specify username in %s user section' % config)
        if 'token' not in user:
            raise GithubException('Specify token in %s user section' % config)
        return (user['username'], user['token'])
    else:
        raise GithubException('No user section in %s' % config)

def find_executable(name: str, flags=os.X_OK) -> List[str]:
    """Finds executable `name`.

    Similar to Unix ``which`` command.

    Returns list of zero or more full paths to `name`."""
    result = []
    extensions = [x for x in os.environ.get('PATHEXT', '').split(os.pathsep) if x]
    path = os.environ.get('PATH', None)
    if path is None:
        return []
    for path in os.environ.get('PATH', '').split(os.pathsep):
        path = os.path.join(path, name)
        if os.access(path, flags):
            result.append(path)
        for extension in extensions:
            path_extension = path + extension
            if os.access(path_extension, flags):
                result.append(path_extension)
    return result

def walk(root_path: Union[str, pathlib.Path], top_down: bool=True) -> Generator[Tuple[pathlib.Path, Sequence[pathlib.Path], Sequence[pathlib.Path]], None, None]:
    """Walks a directory tree.

    Like :py:func:`os.walk` but yielding instances of :py:class:`pathlib.Path`
    instead of strings.

    :param root_path: foo
    :param top_down: bar"""
    root_path = pathlib.Path(root_path)
    directory_paths, file_paths = ([], [])
    for path in sorted(root_path.iterdir()):
        if path.is_dir():
            directory_paths.append(path)
        else:
            file_paths.append(path)
    if top_down:
        yield (root_path, directory_paths, file_paths)
    for directory_path in directory_paths:
        yield from walk(directory_path, top_down=top_down)
    if not top_down:
        yield (root_path, directory_paths, file_paths)

def pretty_ref(obj: Any) -> str:
    """Pretty object reference using ``module.path:qual.name`` format"""
    try:
        return obj.__module__ + ':' + obj.__qualname__
    except AttributeError:
        return pretty_ref(type(obj)) + '(...)'

def transform_source(text):
    """Replaces instances of

        switch expression:
    by

        for __case in _Switch(n):

    and replaces

        case expression:

    by

        if __case(expression):

    and

        default:

    by

        if __case():"""
    toks = tokenize.generate_tokens(StringIO(text).readline)
    result = []
    replacing_keyword = False
    for toktype, tokvalue, _, _, _ in toks:
        if toktype == tokenize.NAME and tokvalue == 'switch':
            result.extend([(tokenize.NAME, 'for'), (tokenize.NAME, '__case'), (tokenize.NAME, 'in'), (tokenize.NAME, '_Switch'), (tokenize.OP, '(')])
            replacing_keyword = True
        elif toktype == tokenize.NAME and (tokvalue == 'case' or tokvalue == 'default'):
            result.extend([(tokenize.NAME, 'if'), (tokenize.NAME, '__case'), (tokenize.OP, '(')])
            replacing_keyword = True
        elif replacing_keyword and tokvalue == ':':
            result.extend([(tokenize.OP, ')'), (tokenize.OP, ':')])
            replacing_keyword = False
        else:
            result.append((toktype, tokvalue))
    return tokenize.untokenize(result)

