    s = list()
    if action == 'store':
        if PY2:
            for i in range(len(p)):
                kc = key[i % len(key)]
                ec = chr((ord(p[i]) + ord(kc)) % 256)
                s.append(ec)
            return base64.urlsafe_b64encode(''.join(s))
        else:
            return base64.urlsafe_b64encode(p.encode()).decode()
    elif PY2:
        e = base64.urlsafe_b64decode(p)
        for i in range(len(e)):
            kc = key[i % len(key)]
            dc = chr((256 + ord(e[i]) - ord(kc)) % 256)
            s.append(dc)
        return ''.join(s)
    else:
        e = base64.urlsafe_b64decode(p)
        return e.decode()

def search_packages_info(query):
    """Gather details from installed distributions. Print distribution name,
    version, location, and installed files. Installed files requires a
    pip generated 'installed-files.txt' in the distributions '.egg-info'
    directory."""
    installed = {}
    for p in pkg_resources.working_set:
        installed[canonicalize_name(p.project_name)] = p
    query_names = [canonicalize_name(name) for name in query]
    for dist in [installed[pkg] for pkg in query_names if pkg in installed]:
        package = {'name': dist.project_name, 'version': dist.version, 'location': dist.location, 'requires': [dep.project_name for dep in dist.requires()]}
        file_list = None
        if isinstance(dist, pkg_resources.DistInfoDistribution):
            if dist.has_metadata('RECORD'):
                lines = dist.get_metadata_lines('RECORD')
                paths = [l.split(',')[0] for l in lines]
                paths = [os.path.join(dist.location, p) for p in paths]
                file_list = [os.path.relpath(p, dist.location) for p in paths]
        elif dist.has_metadata('installed-files.txt'):
            paths = dist.get_metadata_lines('installed-files.txt')
            paths = [os.path.join(dist.egg_info, p) for p in paths]
            file_list = [os.path.relpath(p, dist.location) for p in paths]
        if file_list:
            package['files'] = sorted(file_list)
        yield package

def get_job_class(klass_str):
    """Return the job class"""
    mod_name, klass_name = klass_str.rsplit('.', 1)
    try:
        mod = importlib.import_module(mod_name)
    except ImportError as e:
        logger.error("Error importing job module %s: '%s'", mod_name, e)
        return
    try:
        klass = getattr(mod, klass_name)
    except AttributeError:
        logger.error("Module '%s' does not define a '%s' class", mod_name, klass_name)
        return
    return klass

def angle(v1, v2):
    """Return the angle in radians between vectors 'v1' and 'v2'."""
    v1_u = unit_vector(v1)
    v2_u = unit_vector(v2)
    return np.arccos(np.clip(np.dot(v1_u, v2_u), -1.0, 1.0))

def set_contourf_properties(stroke_width, fcolor, fill_opacity, contour_levels, contourf_idx, unit):
    """Set property values for Polygon."""
    return {'stroke': fcolor, 'stroke-width': stroke_width, 'stroke-opacity': 1, 'fill': fcolor, 'fill-opacity': fill_opacity, 'title': '%.2f' % contour_levels[contourf_idx] + ' ' + unit}

def contour_to_geojson(contour, geojson_filepath=None, min_angle_deg=None, ndigits=5, unit='', stroke_width=1, geojson_properties=None, strdump=False, serialize=True):
    """Transform matplotlib.contour to geojson."""
    collections = contour.collections
    contour_index = 0
    line_features = []
    for collection in collections:
        color = collection.get_edgecolor()
        for path in collection.get_paths():
            v = path.vertices
            if len(v) < 3:
                continue
            coordinates = keep_high_angle(v, min_angle_deg)
            if ndigits:
                coordinates = np.around(coordinates, ndigits)
            line = LineString(coordinates.tolist())
            properties = {'stroke-width': stroke_width, 'stroke': rgb2hex(color[0]), 'title': '%.2f' % contour.levels[contour_index] + ' ' + unit, 'level-value': float('%.6f' % contour.levels[contour_index]), 'level-index': contour_index}
            if geojson_properties:
                properties.update(geojson_properties)
            line_features.append(Feature(geometry=line, properties=properties))
        contour_index += 1
    feature_collection = FeatureCollection(line_features)
    return _render_feature_collection(feature_collection, geojson_filepath, strdump, serialize)

def contourf_to_geojson_overlap(contourf, geojson_filepath=None, min_angle_deg=None, ndigits=5, unit='', stroke_width=1, fill_opacity=0.9, geojson_properties=None, strdump=False, serialize=True):
    """Transform matplotlib.contourf to geojson with overlapping filled contours."""
    polygon_features = []
    contourf_idx = 0
    for collection in contourf.collections:
        color = collection.get_facecolor()
        for path in collection.get_paths():
            for coord in path.to_polygons():
                if min_angle_deg:
                    coord = keep_high_angle(coord, min_angle_deg)
                coord = np.around(coord, ndigits) if ndigits else coord
                polygon = Polygon(coordinates=[coord.tolist()])
                fcolor = rgb2hex(color[0])
                properties = set_contourf_properties(stroke_width, fcolor, fill_opacity, contourf.levels, contourf_idx, unit)
                if geojson_properties:
                    properties.update(geojson_properties)
                feature = Feature(geometry=polygon, properties=properties)
                polygon_features.append(feature)
        contourf_idx += 1
    feature_collection = FeatureCollection(polygon_features)
    return _render_feature_collection(feature_collection, geojson_filepath, strdump, serialize)

def guess(filename, fallback='application/octet-stream'):
    """Using the mimetypes library, guess the mimetype and
    encoding for a given *filename*. If the mimetype
    cannot be guessed, *fallback* is assumed instead.

    :param filename: Filename- can be absolute path.
    :param fallback: A fallback mimetype."""
    guessed, encoding = mimetypes.guess_type(filename, strict=False)
    if guessed is None:
        return (fallback, encoding)
    return (guessed, encoding)

def format_addresses(addrs):
    """Given an iterable of addresses or name-address
    tuples *addrs*, return a header value that joins
    all of them together with a space and a comma."""
    return ', '.join((formataddr(item) if isinstance(item, tuple) else item for item in addrs))

def stringify_address(addr, encoding='utf-8'):
    """Given an email address *addr*, try to encode
    it with ASCII. If it's not possible, encode
    the *local-part* with the *encoding* and the
    *domain* with IDNA.

    The result is a unicode string with the domain
    encoded as idna."""
    if isinstance(addr, bytes_type):
        return addr
    try:
        addr = addr.encode('ascii')
    except UnicodeEncodeError:
        if '@' in addr:
            localpart, domain = addr.split('@', 1)
            addr = b'@'.join([localpart.encode(encoding), domain.encode('idna')])
        else:
            addr = addr.encode(encoding)
    return addr.decode('utf-8')

def get_existing_model(model_name):
    """Try to find existing model class named `model_name`.

    :param model_name: String name of the model class."""
    try:
        model_cls = engine.get_document_cls(model_name)
        log.debug('Model `{}` already exists. Using existing one'.format(model_name))
        return model_cls
    except ValueError:
        log.debug('Model `{}` does not exist'.format(model_name))

def prepare_relationship(config, model_name, raml_resource):
    """Create referenced model if it doesn't exist.

    When preparing a relationship, we check to see if the model that will be
    referenced already exists. If not, it is created so that it will be possible
    to use it in a relationship. Thus the first usage of this model in RAML file
    must provide its schema in POST method resource body schema.

    :param model_name: Name of model which should be generated.
    :param raml_resource: Instance of ramlfications.raml.ResourceNode for
        which :model_name: will be defined."""
    if get_existing_model(model_name) is None:
        plural_route = '/' + pluralize(model_name.lower())
        route = '/' + model_name.lower()
        for res in raml_resource.root.resources:
            if res.method.upper() != 'POST':
                continue
            if res.path.endswith(plural_route) or res.path.endswith(route):
                break
        else:
            raise ValueError('Model `{}` used in relationship is not defined'.format(model_name))
        setup_data_model(config, res, model_name)

def setup_data_model(config, raml_resource, model_name):
    """Setup storage/data model and return generated model class.

    Process follows these steps:
      * Resource schema is found and restructured by `resource_schema`.
      * Model class is generated from properties dict using util function
        `generate_model_cls`.

    :param raml_resource: Instance of ramlfications.raml.ResourceNode.
    :param model_name: String representing model name."""
    model_cls = get_existing_model(model_name)
    schema = resource_schema(raml_resource)
    if not schema:
        raise Exception('Missing schema for model `{}`'.format(model_name))
    if model_cls is not None:
        return (model_cls, schema.get('_auth_model', False))
    log.info('Generating model class `{}`'.format(model_name))
    return generate_model_cls(config, schema=schema, model_name=model_name, raml_resource=raml_resource)

def handle_model_generation(config, raml_resource):
    """Generates model name and runs `setup_data_model` to get
    or generate actual model class.

    :param raml_resource: Instance of ramlfications.raml.ResourceNode."""
    model_name = generate_model_name(raml_resource)
    try:
        return setup_data_model(config, raml_resource, model_name)
    except ValueError as ex:
        raise ValueError('{}: {}'.format(model_name, str(ex)))

def setup_model_event_subscribers(config, model_cls, schema):
    """Set up model event subscribers.

    :param config: Pyramid Configurator instance.
    :param model_cls: Model class for which handlers should be connected.
    :param schema: Dict of model JSON schema."""
    events_map = get_events_map()
    model_events = schema.get('_event_handlers', {})
    event_kwargs = {'model': model_cls}
    for event_tag, subscribers in model_events.items():
        type_, action = event_tag.split('_')
        event_objects = events_map[type_][action]
        if not isinstance(event_objects, list):
            event_objects = [event_objects]
        for sub_name in subscribers:
            sub_func = resolve_to_callable(sub_name)
            config.subscribe_to_events(sub_func, event_objects, **event_kwargs)

def setup_fields_processors(config, model_cls, schema):
    """Set up model fields' processors.

    :param config: Pyramid Configurator instance.
    :param model_cls: Model class for field of which processors should be
        set up.
    :param schema: Dict of model JSON schema."""
    properties = schema.get('properties', {})
    for field_name, props in properties.items():
        if not props:
            continue
        processors = props.get('_processors')
        backref_processors = props.get('_backref_processors')
        if processors:
            processors = [resolve_to_callable(val) for val in processors]
            setup_kwargs = {'model': model_cls, 'field': field_name}
            config.add_field_processors(processors, **setup_kwargs)
        if backref_processors:
            db_settings = props.get('_db_settings', {})
            is_relationship = db_settings.get('type') == 'relationship'
            document = db_settings.get('document')
            backref_name = db_settings.get('backref_name')
            if not (is_relationship and document and backref_name):
                continue
            backref_processors = [resolve_to_callable(val) for val in backref_processors]
            setup_kwargs = {'model': engine.get_document_cls(document), 'field': backref_name}
            config.add_field_processors(backref_processors, **setup_kwargs)

def validate_permissions(perms):
    """Validate :perms: contains valid permissions.

    :param perms: List of permission names or ALL_PERMISSIONS."""
    if not isinstance(perms, (list, tuple)):
        perms = [perms]
    valid_perms = set(PERMISSIONS.values())
    if ALL_PERMISSIONS in perms:
        return perms
    if set(perms) - valid_perms:
        raise ValueError('Invalid ACL permission names. Valid permissions are: {}'.format(', '.join(valid_perms)))
    return perms

def parse_permissions(perms):
    """Parse permissions ("perms") which are either exact permission
    names or the keyword 'all'.

    :param perms: List or comma-separated string of nefertari permission
        names, or 'all'"""
    if isinstance(perms, six.string_types):
        perms = perms.split(',')
    perms = [perm.strip().lower() for perm in perms]
    if 'all' in perms:
        return ALL_PERMISSIONS
    return validate_permissions(perms)

def convert_schema(raml_schema, mime_type):
    """Restructure `raml_schema` to a dictionary that has 'properties'
    as well as other schema keys/values.

    The resulting dictionary looks like this::

    {
        "properties": {
            "field1": {
                "required": boolean,
                "type": ...,
                ...more field options
            },
            ...more properties
        },
        "public_fields": [...],
        "auth_fields": [...],
        ...more schema options
    }

    :param raml_schema: RAML request body schema.
    :param mime_type: ContentType of the schema as a string from RAML
        file. Only JSON is currently supported."""
    if mime_type == ContentTypes.JSON:
        if not isinstance(raml_schema, dict):
            raise TypeError('Schema is not a valid JSON. Please check your schema syntax.\n{}...'.format(str(raml_schema)[:60]))
        return raml_schema
    if mime_type == ContentTypes.TEXT_XML:
        pass

def extract_dynamic_part(uri):
    """Extract dynamic url part from :uri: string.

    :param uri: URI string that may contain dynamic part."""
    for part in uri.split('/'):
        part = part.strip()
        if part.startswith('{') and part.endswith('}'):
            return clean_dynamic_uri(part)

def resource_schema(raml_resource):
    """Get schema properties of RAML resource :raml_resource:.

    Must be called with RAML resource that defines body schema. First
    body that defines schema is used. Schema is converted on return using
    'convert_schema'.

    :param raml_resource: Instance of ramlfications.raml.ResourceNode of
        POST method."""
    log.info('Searching for model schema')
    if not raml_resource.body:
        raise ValueError('RAML resource has no body to setup database schema from')
    for body in raml_resource.body:
        if body.schema:
            return convert_schema(body.schema, body.mime_type)
    log.debug('No model schema found.')

def get_static_parent(raml_resource, method=None):
    """Get static parent resource of :raml_resource: with HTTP
    method :method:.

    :param raml_resource:Instance of ramlfications.raml.ResourceNode.
    :param method: HTTP method name which matching static resource
        must have."""
    parent = raml_resource.parent
    while is_dynamic_resource(parent):
        parent = parent.parent
    if parent is None:
        return parent
    match_method = method is not None
    if match_method:
        if parent.method.upper() == method.upper():
            return parent
    else:
        return parent
    for res in parent.root.resources:
        if res.path == parent.path:
            if res.method.upper() == method.upper():
                return res

def attr_subresource(raml_resource, route_name):
    """Determine if :raml_resource: is an attribute subresource.

    :param raml_resource: Instance of ramlfications.raml.ResourceNode.
    :param route_name: Name of the :raml_resource:."""
    static_parent = get_static_parent(raml_resource, method='POST')
    if static_parent is None:
        return False
    schema = resource_schema(static_parent) or {}
    properties = schema.get('properties', {})
    if route_name in properties:
        db_settings = properties[route_name].get('_db_settings', {})
        return db_settings.get('type') in ('dict', 'list')
    return False

def is_callable_tag(tag):
    """Determine whether :tag: is a valid callable string tag.

    String is assumed to be valid callable if it starts with '{{'
    and ends with '}}'.

    :param tag: String name of tag."""
    return isinstance(tag, six.string_types) and tag.strip().startswith('{{') and tag.strip().endswith('}}')

def resolve_to_callable(callable_name):
    """Resolve string :callable_name: to a callable.

    :param callable_name: String representing callable name as registered
        in ramses registry or dotted import path of callable. Can be
        wrapped in double curly brackets, e.g. '{{my_callable}}'."""
    from . import registry
    clean_callable_name = callable_name.replace('{{', '').replace('}}', '').strip()
    try:
        return registry.get(clean_callable_name)
    except KeyError:
        try:
            from zope.dottedname.resolve import resolve
            return resolve(clean_callable_name)
        except ImportError:
            raise ImportError('Failed to load callable `{}`'.format(clean_callable_name))

def generate_server(raml_root, config):
    """Handle server generation process.

    :param raml_root: Instance of ramlfications.raml.RootNode.
    :param config: Pyramid Configurator instance."""
    log.info('Server generation started')
    if not raml_root.resources:
        return
    root_resource = config.get_root_resource()
    generated_resources = {}
    for raml_resource in raml_root.resources:
        if raml_resource.path in generated_resources:
            continue
        parent_resource = _get_nefertari_parent_resource(raml_resource, generated_resources, root_resource)
        new_resource = generate_resource(config, raml_resource, parent_resource)
        if new_resource is not None:
            generated_resources[raml_resource.path] = new_resource

def generate_models(config, raml_resources):
    """Generate model for each resource in :raml_resources:

    The DB model name is generated using singular titled version of current
    resource's url. E.g. for resource under url '/stories', model with
    name 'Story' will be generated.

    :param config: Pyramid Configurator instance.
    :param raml_resources: List of ramlfications.raml.ResourceNode."""
    from .models import handle_model_generation
    if not raml_resources:
        return
    for raml_resource in raml_resources:
        if is_dynamic_uri(raml_resource.path):
            continue
        if raml_resource.method.upper() != 'POST':
            continue
        resource_uri = get_resource_uri(raml_resource)
        route_name = get_route_name(resource_uri)
        if not attr_subresource(raml_resource, route_name):
            log.info('Configuring model for route `{}`'.format(route_name))
            model_cls, is_auth_model = handle_model_generation(config, raml_resource)
            if is_auth_model:
                config.registry.auth_model = model_cls

def _improve_class_docs(app, cls, lines):
    """Improve the documentation of a class."""
    if issubclass(cls, models.Model):
        _add_model_fields_as_params(app, cls, lines)
    elif issubclass(cls, forms.Form):
        _add_form_fields(cls, lines)

def _add_model_fields_as_params(app, obj, lines):
    """Improve the documentation of a Django model subclass.

    This adds all model fields as parameters to the ``__init__()`` method.

    :type app: sphinx.application.Sphinx
    :type lines: list"""
    for field in obj._meta.get_fields():
        try:
            help_text = strip_tags(force_text(field.help_text))
            verbose_name = force_text(field.verbose_name).capitalize()
        except AttributeError:
            continue
        if help_text:
            lines.append(u':param %s: %s' % (field.name, help_text))
        else:
            lines.append(u':param %s: %s' % (field.name, verbose_name))
        lines.append(_get_field_type(field))
    if 'sphinx.ext.inheritance_diagram' in app.extensions and 'sphinx.ext.graphviz' in app.extensions and (not any(('inheritance-diagram::' in line for line in lines))):
        lines.append('.. inheritance-diagram::')

def _improve_method_docs(obj, name, lines):
    """Improve the documentation of various methods.

    :param obj: the instance of the method to document.
    :param name: full dotted path to the object.
    :param lines: expected documentation lines."""
    if not lines:
        if name.endswith('_display'):
            match = RE_GET_FOO_DISPLAY.search(name)
            if match is not None:
                lines.append('**Autogenerated:** Shows the label of the :attr:`{field}`'.format(field=match.group('field')))
        elif '.get_next_by_' in name:
            match = RE_GET_NEXT_BY.search(name)
            if match is not None:
                lines.append('**Autogenerated:** Finds next instance based on :attr:`{field}`.'.format(field=match.group('field')))
        elif '.get_previous_by_' in name:
            match = RE_GET_PREVIOUS_BY.search(name)
            if match is not None:
                lines.append('**Autogenerated:** Finds previous instance based on :attr:`{field}`.'.format(field=match.group('field')))

def _gen_input_mask(mask):
    """Generate input mask from bytemask"""
    return input_mask(shift=bool(mask & MOD_Shift), lock=bool(mask & MOD_Lock), control=bool(mask & MOD_Control), mod1=bool(mask & MOD_Mod1), mod2=bool(mask & MOD_Mod2), mod3=bool(mask & MOD_Mod3), mod4=bool(mask & MOD_Mod4), mod5=bool(mask & MOD_Mod5))

def Timestamp(year, month, day, hour, minute, second):
    """Constructs an object holding a datetime/timestamp value."""
    return datetime.datetime(year, month, day, hour, minute, second)

def compat_serializer_check_is_valid(serializer):
    """http://www.django-rest-framework.org/topics/3.0-announcement/#using-is_validraise_exceptiontrue"""
    if DRFVLIST[0] >= 3:
        serializer.is_valid(raise_exception=True)
    elif not serializer.is_valid():
        serializers.ValidationError('The serializer raises a validation error')

def compat_serializer_attr(serializer, obj):
    """Required only for DRF 3.1, which does not make dynamically added attribute available in obj in serializer.
    This is a quick solution but works without breajing anything."""
    if DRFVLIST[0] == 3 and DRFVLIST[1] == 1:
        for i in serializer.instance:
            if i.id == obj.id:
                return i
    else:
        return obj

def compat_get_paginated_response(view, page):
    """get_paginated_response is unknown to DRF 3.0"""
    if DRFVLIST[0] == 3 and DRFVLIST[1] >= 1:
        from rest_messaging.serializers import ComplexMessageSerializer
        serializer = ComplexMessageSerializer(page, many=True)
        return view.get_paginated_response(serializer.data)
    else:
        serializer = view.get_pagination_serializer(page)
        return Response(serializer.data)

def compat_pagination_messages(cls):
    """For DRF 3.1 and higher, pagination is defined at the paginator level (see http://www.django-rest-framework.org/topics/3.2-announcement/).
    For DRF 3.0 and lower, it can be handled at the view level."""
    if DRFVLIST[0] == 3 and DRFVLIST[1] >= 1:
        setattr(cls, 'pagination_class', MessagePagination)
        return cls
    else:
        setattr(cls, 'paginate_by', getattr(settings, 'DJANGO_REST_MESSAGING_MESSAGES_PAGE_SIZE', 30))
        return cls

def parse(content, *args, **kwargs):
    """Use mecab-python3 by default to parse JP text. Fall back to mecab binary app if needed"""
    global MECAB_PYTHON3
    if 'mecab_loc' not in kwargs and MECAB_PYTHON3 and ('MeCab' in globals()):
        return MeCab.Tagger(*args).parse(content)
    else:
        return run_mecab_process(content, *args, **kwargs)

def _get_cmd(command, arguments):
    """Merge command with arguments."""
    if arguments is None:
        arguments = []
    if command.endswith('.py') or command.endswith('.pyw'):
        return [sys.executable, command] + list(arguments)
    else:
        return [command] + list(arguments)

def dumps(obj, *args, **kwargs):
    """Typeless dump an object to json string"""
    return json.dumps(obj, *args, cls=TypelessSONEncoder, ensure_ascii=False, **kwargs)

def flex_update_obj(source, target, __silent, *fields, **field_map):
    """Pull data from source to target.
    Target's __dict__ (object data) will be used by default. Otherwise, it'll be treated as a dictionary"""
    source_dict = source.__dict__ if hasattr(source, '__dict__') else source
    if not fields:
        fields = source_dict.keys()
    for f in fields:
        if f not in source_dict and __silent:
            continue
        target_f = f if f not in field_map else field_map[f]
        setattr(target, target_f, source_dict[f])

def to_obj(cls, obj_data=None, *fields, **field_map):
    """Use obj_data (dict-like) to construct an object of type cls
    prioritize obj_dict when there are conficts"""
    if not fields:
        fields = obj_data.keys()
    try:
        kwargs = {field(f, field_map): obj_data[f] for f in fields if f in obj_data}
        obj = cls(**kwargs)
    except:
        getLogger().exception("Couldn't use kwargs to construct object")
        obj = cls()
        update_obj(obj_data, obj, *fields, **field_map)
    return obj

def is_kana(text):
    """Check if a text if written in kana only (hiragana & katakana)
    if text is empty then return True"""
    if text is None:
        raise ValueError('text cannot be None')
    for c in text:
        if c not in HIRAGANA and c not in KATAKANA:
            return False
    return True

def txt2mecab(text, **kwargs):
    """Use mecab to parse one sentence"""
    mecab_out = _internal_mecab_parse(text, **kwargs).splitlines()
    tokens = [MeCabToken.parse(x) for x in mecab_out]
    return MeCabSent(text, tokens)

def analyse(content, splitlines=True, format=None, **kwargs):
    """Japanese text > tokenize/txt/html"""
    sents = DekoText.parse(content, splitlines=splitlines, **kwargs)
    doc = []
    final = sents
    if format == 'html':
        for sent in sents:
            doc.append(sent.to_ruby())
        final = '<br/>\n'.join(doc)
    elif format == 'csv':
        for sent in sents:
            doc.append('\n'.join([x.to_csv() for x in sent]) + '\n')
        final = '\n'.join(doc)
    elif format == 'txt':
        final = '\n'.join([str(x) for x in sents])
    return final

def smart_text(s, encoding='utf-8', strings_only=False, errors='strict'):
    """Return a unicode object representing 's'.

    Treats bytes using the 'encoding' codec.

    If strings_only is True, don't convert (some) non-string-like objects."""
    if isinstance(s, six.text_type):
        return s
    if strings_only and (not isinstance(s, six.string_types)):
        return s
    if not isinstance(s, six.string_types):
        if hasattr(s, '__unicode__'):
            s = s.__unicode__()
        elif six.PY3:
            if isinstance(s, six.binary_type):
                s = six.text_type(s, encoding, errors)
            else:
                s = six.text_type(s)
        else:
            s = six.text_type(six.binary_type(s), encoding, errors)
    else:
        s = s.decode(encoding, errors)
    return s

def smart_bytes(s, encoding='utf-8', strings_only=False, errors='strict'):
    """Return a bytes version of 's' encoded as specified in 'encoding'.

    If strings_only is True, don't convert (some) non-string-like objects."""
    if isinstance(s, six.binary_type):
        if encoding == 'utf-8':
            return s
        else:
            return s.decode('utf-8', errors).encode(encoding, errors)
    if strings_only and (not isinstance(s, six.text_type)):
        return s
    if not isinstance(s, six.string_types):
        try:
            if six.PY3:
                return six.text_type(s).encode(encoding)
            else:
                return six.binary_type(s)
        except UnicodeEncodeError:
            return six.text_type(s).encode(encoding, errors)
    else:
        return s.encode(encoding, errors)

def copy(source, destination):
    """Copy file or directory.

    Args:
        source (str): Source file or directory
        destination (str): Destination file or directory (where to copy).

    Returns:
        bool: True if the operation is successful, False otherwise."""
    if os.path.isdir(source):
        return __copytree(source, destination)
    else:
        return __copyfile2(source, destination)

def gremove(pattern):
    """Remove all file found by glob.glob(pattern).

    Args:
        pattern (str): Pattern of files to remove
    Returns:
        bool: True if the operation is successful, False otherwise."""
    for item in glob.glob(pattern):
        if not remove(item):
            return False
    return True

def read(path, encoding='utf-8'):
    """Read the content of the file.

    Args:
        path (str): Path to the file
        encoding (str): File encoding. Default: utf-8

    Returns:
        str: File content or empty string if there was an error"""
    try:
        with io.open(path, encoding=encoding) as f:
            return f.read()
    except Exception as e:
        logger.error('read: %s failed. Error: %s', path, e)
        return ''

def get_exception():
    """Return full formatted traceback as a string."""
    trace = ''
    exception = ''
    exc_list = traceback.format_exception_only(sys.exc_info()[0], sys.exc_info()[1])
    for entry in exc_list:
        exception += entry
    tb_list = traceback.format_tb(sys.exc_info()[2])
    for entry in tb_list:
        trace += entry
    return '%s\n%s' % (exception, trace)

def _product_filter(products) -> str:
    """Calculate the product filter."""
    _filter = 0
    for product in {PRODUCTS[p] for p in products}:
        _filter += product
    return format(_filter, 'b')[::-1]

def process_file(path, processor, encoding='utf-8', mode='rt', *args, **kwargs):
    """Process a text file's content. If the file name ends with .gz, read it as gzip file"""
    if mode not in ('rU', 'rt', 'rb', 'r'):
        raise Exception('Invalid file reading mode')
    with open(path, *args, encoding=encoding, mode=mode, **kwargs) as infile:
        return processor(infile)

def read_file(path, encoding='utf-8', *args, **kwargs):
    """Read text file content. If the file name ends with .gz, read it as gzip file.
    If mode argument is provided as 'rb', content will be read as byte stream.
    By default, content is read as string."""
    if 'mode' in kwargs and kwargs['mode'] == 'rb':
        return process_file(path, *args, processor=lambda x: x.read(), encoding=encoding, **kwargs)
    else:
        return process_file(path, *args, processor=lambda x: to_string(x.read(), encoding), encoding=encoding, **kwargs)

def write_file(path, content, mode=None, encoding='utf-8'):
    """Write content to a file. If the path ends with .gz, gzip will be used."""
    if not mode:
        if isinstance(content, bytes):
            mode = 'wb'
        else:
            mode = 'wt'
    if not path:
        raise ValueError('Output path is invalid')
    else:
        getLogger().debug('Writing content to {}'.format(path))
        if mode in ('w', 'wt') and (not isinstance(content, str)):
            content = to_string(content)
        elif mode == 'wb':
            if not isinstance(content, str):
                content = to_string(content).encode(encoding)
            else:
                content = content.encode(encoding)
        if str(path).endswith('.gz'):
            with gzip.open(path, mode) as outfile:
                outfile.write(content)
        else:
            with open(path, mode=mode) as outfile:
                outfile.write(content)

def iter_csv_stream(input_stream, fieldnames=None, sniff=False, *args, **kwargs):
    """Read CSV content as a table (list of lists) from an input stream"""
    if 'dialect' not in kwargs and sniff:
        kwargs['dialect'] = csv.Sniffer().sniff(input_stream.read(1024))
        input_stream.seek(0)
    if 'quoting' in kwargs and kwargs['quoting'] is None:
        kwargs['quoting'] = csv.QUOTE_MINIMAL
    if fieldnames:
        if isinstance(fieldnames, bool):
            reader = csv.DictReader(input_stream, *args, **kwargs)
        else:
            reader = csv.DictReader(input_stream, *args, fieldnames=fieldnames, **kwargs)
        for row in reader:
            yield row
    else:
        csvreader = csv.reader(input_stream, *args, **kwargs)
        for row in csvreader:
            yield row

def read_csv(path, fieldnames=None, sniff=True, encoding='utf-8', *args, **kwargs):
    """Read CSV rows as table from a file.
    By default, csv.reader() will be used any output will be a list of lists.
    If fieldnames is provided, DictReader will be used and output will be list of OrderedDict instead.
    CSV sniffing (dialect detection) is enabled by default, set sniff=False to switch it off."""
    return list((r for r in read_csv_iter(path, *args, fieldnames=fieldnames, sniff=sniff, encoding=encoding, **kwargs)))

def write_csv(path, rows, dialect='excel', fieldnames=None, quoting=csv.QUOTE_ALL, extrasaction='ignore', *args, **kwargs):
    """Write rows data to a CSV file (with or without fieldnames)"""
    if not quoting:
        quoting = csv.QUOTE_MINIMAL
    if 'lineterminator' not in kwargs:
        kwargs['lineterminator'] = '\n'
    with open(path, mode='wt', newline='') as csvfile:
        if fieldnames:
            writer = csv.DictWriter(csvfile, *args, fieldnames=fieldnames, dialect=dialect, quoting=quoting, extrasaction=extrasaction, **kwargs)
            writer.writeheader()
            for row in rows:
                writer.writerow(row)
        else:
            writer = csv.writer(csvfile, *args, dialect=dialect, quoting=quoting, **kwargs)
            for row in rows:
                writer.writerow(row)

def make_msgid(idstring=None, utc=False):
    """Return a string suitable for RFC 2822 compliant Message-ID.

    E.g: <20020201195627.33539.96671@nightshade.la.mastaler.com>

    Optional idstring if given is a string used to strengthen the
    uniqueness of the message id."""
    if utc:
        timestamp = time.gmtime()
    else:
        timestamp = time.localtime()
    utcdate = time.strftime('%Y%m%d%H%M%S', timestamp)
    try:
        pid = os.getpid()
    except AttributeError:
        pid = 1
    randint = random.randrange(100000)
    if idstring is None:
        idstring = ''
    else:
        idstring = '.' + idstring
    idhost = DNS_NAME
    msgid = '<%s.%s.%s%s@%s>' % (utcdate, pid, randint, idstring, idhost)
    return msgid

def forbid_multi_line_headers(name, val):
    """Forbid multi-line headers, to prevent header injection."""
    val = smart_text(val)
    if '\n' in val or '\r' in val:
        raise BadHeaderError("Header values can't contain newlines (got %r for header %r)" % (val, name))
    try:
        val = val.encode('ascii')
    except UnicodeEncodeError:
        if name.lower() in ('to', 'from', 'cc'):
            result = []
            for item in val.split(', '):
                nm, addr = parseaddr(item)
                nm = str(Header(nm, DEFAULT_CHARSET))
                result.append(formataddr((nm, str(addr))))
            val = ', '.join(result)
        else:
            val = Header(val, DEFAULT_CHARSET)
    else:
        if name.lower() == 'subject':
            val = Header(val)
    return (name, val)

def send_mail(subject, sender, to, message, html_message=None, cc=None, bcc=None, attachments=None, host=None, port=None, auth_user=None, auth_password=None, use_tls=False, fail_silently=False):
    """Send a single email to a recipient list.

    All members of the recipient list will see the other recipients in the 'To'
    field.

    Note: The API for this method is frozen. New code wanting to extend the
    functionality should use the EmailMessage class directly."""
    if message is None and html_message is None:
        raise ValueError('Either message or html_message must be provided')
    if message is None:
        message = strip_tags(html_message)
    connection = SMTPConnection(host=host, port=port, username=auth_user, password=auth_password, use_tls=use_tls, fail_silently=fail_silently)
    if isinstance(to, six.string_types):
        to = [to]
    if html_message is None:
        email = EmailMessage(subject=subject, body=message, sender=sender, to=to, cc=cc, bcc=bcc, attachments=attachments, connection=connection)
    else:
        email = EmailMultiAlternatives(subject=subject, body=message, sender=sender, to=to, cc=cc, bcc=bcc, attachments=attachments, connection=connection)
        email.attach_alternative(html_message, 'text/html')
    return email.send()

def entry_point():
    """Entry-point from setuptools."""
    signal.signal(signal.SIGINT, lambda *_: getattr(os, '_exit')(0))
    config = get_arguments()
    setup_logging(config['verbose'])
    try:
        main(config)
    except HandledError:
        if config['raise']:
            raise
        logging.critical('Failure.')
        sys.exit(0 if config['ignore_errors'] else 1)

def _safe_get(mapping, key, default=None):
    """Helper for accessing style values.

    It exists to avoid checking whether `mapping` is indeed a mapping before
    trying to get a key.  In the context of style dicts, this eliminates "is
    this a mapping" checks in two common situations: 1) a style argument is
    None, and 2) a style key's value (e.g., width) can be either a mapping or a
    plain value."""
    try:
        return mapping.get(key, default)
    except AttributeError:
        return default

def seven_zip(archive, items, self_extracting=False):
