def login_defs():
    """Discover the minimum and maximum UID number."""
    uid_min = None
    uid_max = None
    login_defs_path = '/etc/login.defs'
    if os.path.exists(login_defs_path):
        with io.open(text_type(login_defs_path), encoding=text_type('utf-8')) as log_defs_file:
            login_data = log_defs_file.readlines()
        for line in login_data:
            if PY3:
                line = str(line)
            if PY2:
                line = line.encode(text_type('utf8'))
            if line[:7] == text_type('UID_MIN'):
                uid_min = int(line.split()[1].strip())
            if line[:7] == text_type('UID_MAX'):
                uid_max = int(line.split()[1].strip())
    if not uid_min:
        uid_min = DEFAULT_UID_MIN
    if not uid_max:
        uid_max = DEFAULT_UID_MAX
    return (uid_min, uid_max)

def generate_delete_user_command(username=None, manage_home=None):
    """Generate command to delete a user.

    args:
        username (str): user name
        manage_home (bool): manage home directory

    returns:
        list: The user delete command string split into shell-like syntax"""
    command = None
    remove_home = '-r' if manage_home else ''
    if get_platform() in ('Linux', 'OpenBSD'):
        command = '{0} {1} {2} {3}'.format(sudo_check(), LINUX_CMD_USERDEL, remove_home, username)
    elif get_platform() == 'FreeBSD':
        command = '{0} {1} userdel {2} -n {3}'.format(sudo_check(), FREEBSD_CMD_PW, remove_home, username)
    if command:
        return shlex.split(str(command))

def read(path, mode='tsv'):
    """Helper function to read Document in TTL-TXT format (i.e. ${docname}_*.txt)
    E.g. read('~/data/myfile') is the same as Document('myfile', '~/data/').read()"""
    if mode == 'tsv':
        return TxtReader.from_path(path).read()
    elif mode == 'json':
        return read_json(path)
    else:
        raise Exception('Invalid mode - [{}] was provided'.format(mode))

def write(path, doc, mode=MODE_TSV, **kwargs):
    """Helper function to write doc to TTL-TXT format"""
    if mode == MODE_TSV:
        with TxtWriter.from_path(path) as writer:
            writer.write_doc(doc)
    elif mode == MODE_JSON:
        write_json(path, doc, **kwargs)

def check_background(qpi):
    """Check QPimage background data

    Parameters
    ----------
    qpi: qpimage.core.QPImage

    Raises
    ------
    IntegrityCheckError
        if the check fails"""
    for imdat in [qpi._amp, qpi._pha]:
        try:
            fit, attrs = imdat.get_bg(key='fit', ret_attrs=True)
        except KeyError:
            pass
        else:
            kwargs = dict(attrs)
            binkey = 'estimate_bg_from_mask'
            if binkey in imdat.h5:
                kwargs['from_mask'] = imdat.h5[binkey][:]
            else:
                kwargs['from_mask'] = None
            with h5py.File('check.h5', driver='core', backing_store=False) as h5:
                testimdat = imdat.__class__(h5)
                testimdat['raw'] = imdat.raw
                try:
                    bg = imdat.get_bg('data')
                except KeyError:
                    pass
                else:
                    testimdat.set_bg(bg, key='data')
                testimdat.estimate_bg(**kwargs)
                if not np.allclose(testimdat.get_bg(key='fit'), fit):
                    msg = 'Wrong estimated (fitted) background!'
                    raise IntegrityCheckError(msg)

def git_tags() -> str:
    """Calls ``git tag -l --sort=-v:refname`` (sorts output) and returns the
    output as a UTF-8 encoded string. Raises a NoGitTagsException if the
    repository doesn't contain any Git tags."""
    try:
        subprocess.check_call(['git', 'fetch', '--tags'])
    except CalledProcessError:
        pass
    cmd = ['git', 'tag', '--list', '--sort=-v:refname']
    rv = subprocess.check_output(cmd).decode('utf-8')
    if rv == '':
        raise NoGitTagsException('No Git tags are present in current repo.')
    return rv

def git_tag_to_semver(git_tag: str) -> SemVer:
    """:git_tag: A string representation of a Git tag.

    Searches a Git tag's string representation for a SemVer, and returns that
    as a SemVer object."""
    pattern = re.compile('[0-9]+\\.[0-9]+\\.[0-9]+$')
    match = pattern.search(git_tag)
    if match:
        version = match.group(0)
    else:
        raise InvalidTagFormatException('Tag passed contains no SemVer.')
    return SemVer.from_str(version)

def last_git_release_tag(git_tags: str) -> str:
    """:git_tags: chronos.helpers.git_tags() function output.

    Returns the latest Git tag ending with a SemVer as a string."""
    semver_re = re.compile('[0-9]+\\.[0-9]+\\.[0-9]+$')
    str_ver = []
    for i in git_tags.split():
        if semver_re.search(i):
            str_ver.append(i)
    try:
        return str_ver[0]
    except IndexError:
        raise NoGitTagsException

def git_commits_since_last_tag(last_tag: str) -> dict:
    """:last_tag: The Git tag that should serve as the starting point for the
    commit log lookup.

    Calls ``git log <last_tag>.. --format='%H %s'`` and returns the output as a
    dict of hash-message pairs."""
    try:
        cmd = ['git', 'log', last_tag + '..', "--format='%H %s'"]
        commit_log = subprocess.check_output(cmd).decode('utf-8')
    except CalledProcessError:
        raise GitTagDoesNotExistError('No such tag:', last_tag)
    if not commit_log:
        raise NoGitCommitSinceLastTagException('No commits since last tag.')
    pattern = re.compile('([a-f0-9]{40})\\ (.*)')
    rv = {}
    for line in commit_log.split('\n'):
        match = pattern.search(line)
        if match:
            commit_hash = match.group(1)
            commit_msg = match.group(2)
            rv[commit_hash] = commit_msg
    return rv

def parse_commit_log(commit_log: dict) -> str:
    """:commit_log: chronos.helpers.git_commits_since_last_tag() output.

    Parse Git log and return either 'maj', 'min', or 'pat'."""
    rv = 'pat'
    cc_patterns = patterns()
    for value in commit_log.values():
        if re.search(cc_patterns['feat'], value):
            rv = 'min'
        if re.search(cc_patterns['BREAKING CHANGE'], value):
            rv = 'maj'
    return rv

def poly2o_residual(params, data, mask):
    """lmfit 2nd order polynomial residuals"""
    bg = poly2o_model(params, shape=data.shape)
    res = (data - bg)[mask]
    return res.flatten()

def tilt_residual(params, data, mask):
    """lmfit tilt residuals"""
    bg = tilt_model(params, shape=data.shape)
    res = (data - bg)[mask]
    return res.flatten()

def infer(args: argparse.Namespace) -> None:
    """:args: An argparse.Namespace object.

    This is the function called when the 'infer' sub-command is passed as an
    argument to the CLI."""
    try:
        last_tag = last_git_release_tag(git_tags())
    except NoGitTagsException:
        print(SemVer(0, 1, 0))
        exit(0)
    commit_log = git_commits_since_last_tag(last_tag)
    action = parse_commit_log(commit_log)
    last_ver = git_tag_to_semver(last_tag)
    if action == 'min':
        new_ver = last_ver.bump_minor()
    elif action == 'maj':
        new_ver = last_ver.bump_major()
    else:
        new_ver = last_ver.bump_patch()
    print(new_ver)

def bump(args: argparse.Namespace) -> None:
    """:args: An argparse.Namespace object.

    This function is bound to the 'bump' sub-command. It increments the version
    integer of the user's choice ('major', 'minor', or 'patch')."""
    try:
        last_tag = last_git_release_tag(git_tags())
    except NoGitTagsException:
        print(SemVer(0, 1, 0))
        exit(0)
    last_ver = git_tag_to_semver(last_tag)
    if args.type == 'patch':
        print(last_ver.bump_patch())
    elif args.type == 'minor':
        print(last_ver.bump_minor())
    elif args.type == 'major':
        print(last_ver.bump_major())

def _collapse_invariants(bases: List[type], namespace: MutableMapping[str, Any]) -> None:
    """Collect invariants from the bases and merge them with the invariants in the namespace."""
    invariants = []
    for base in bases:
        if hasattr(base, '__invariants__'):
            invariants.extend(getattr(base, '__invariants__'))
    if '__invariants__' in namespace:
        invariants.extend(namespace['__invariants__'])
    if invariants:
        namespace['__invariants__'] = invariants

def _dbc_decorate_namespace(bases: List[type], namespace: MutableMapping[str, Any]) -> None:
    """Collect invariants, preconditions and postconditions from the bases and decorate all the methods.

    Instance methods are simply replaced with the decorated function/ Properties, class methods and static methods are
    overridden with new instances of ``property``, ``classmethod`` and ``staticmethod``, respectively."""
    _collapse_invariants(bases=bases, namespace=namespace)
    for key, value in namespace.items():
        if inspect.isfunction(value) or isinstance(value, (staticmethod, classmethod)):
            _decorate_namespace_function(bases=bases, namespace=namespace, key=key)
        elif isinstance(value, property):
            _decorate_namespace_property(bases=bases, namespace=namespace, key=key)
        else:
            pass

def _representable(value: Any) -> bool:
    """Check whether we want to represent the value in the error message on contract breach.

    We do not want to represent classes, methods, modules and functions.

    :param value: value related to an AST node
    :return: True if we want to represent it in the violation error"""
    return not inspect.isclass(value) and (not inspect.isfunction(value)) and (not inspect.ismethod(value)) and (not inspect.ismodule(value)) and (not inspect.isbuiltin(value))

def find_lambda_condition(decorator_inspection: DecoratorInspection) -> Optional[ConditionLambdaInspection]:
    """Inspect the decorator and extract the condition as lambda.

    If the condition is not given as a lambda function, return None."""
    call_node = decorator_inspection.node
    lambda_node = None
    if len(call_node.args) > 0:
        assert isinstance(call_node.args[0], ast.Lambda), 'Expected the first argument to the decorator to be a condition as lambda AST node, but got: {}'.format(type(call_node.args[0]))
        lambda_node = call_node.args[0]
    elif len(call_node.keywords) > 0:
        for keyword in call_node.keywords:
            if keyword.arg == 'condition':
                assert isinstance(keyword.value, ast.Lambda), "Expected lambda node as value of the 'condition' argument to the decorator."
                lambda_node = keyword.value
                break
        assert lambda_node is not None, "Expected to find a keyword AST node with 'condition' arg, but found none"
    else:
        raise AssertionError('Expected a call AST node of a decorator to have either args or keywords, but got: {}'.format(ast.dump(call_node)))
    return ConditionLambdaInspection(atok=decorator_inspection.atok, node=lambda_node)

def _walk_decorator_stack(func: CallableT) -> Iterable['CallableT']:
    """Iterate through the stack of decorated functions until the original function.

    Assume that all decorators used functools.update_wrapper."""
    while hasattr(func, '__wrapped__'):
        yield func
        func = getattr(func, '__wrapped__')
    yield func

def find_checker(func: CallableT) -> Optional[CallableT]:
    """Iterate through the decorator stack till we find the contract checker."""
    contract_checker = None
    for a_wrapper in _walk_decorator_stack(func):
        if hasattr(a_wrapper, '__preconditions__') or hasattr(a_wrapper, '__postconditions__'):
            contract_checker = a_wrapper
    return contract_checker

def _assert_invariant(contract: Contract, instance: Any) -> None:
    """Assert that the contract holds as a class invariant given the instance of the class."""
    if 'self' in contract.condition_arg_set:
        check = contract.condition(self=instance)
    else:
        check = contract.condition()
    if not check:
        if contract.error is not None and (inspect.ismethod(contract.error) or inspect.isfunction(contract.error)):
            assert contract.error_arg_set is not None, 'Expected error_arg_set non-None if contract.error a function.'
            assert contract.error_args is not None, 'Expected error_args non-None if contract.error a function.'
            if 'self' in contract.error_arg_set:
                raise contract.error(self=instance)
            else:
                raise contract.error()
        else:
            if 'self' in contract.condition_arg_set:
                msg = icontract._represent.generate_message(contract=contract, condition_kwargs={'self': instance})
            else:
                msg = icontract._represent.generate_message(contract=contract, condition_kwargs=dict())
            if contract.error is None:
                raise ViolationError(msg)
            elif isinstance(contract.error, type):
                raise contract.error(msg)
            else:
                raise NotImplementedError('Unhandled contract.error: {}'.format(contract.error))

def _capture_snapshot(a_snapshot: Snapshot, resolved_kwargs: Mapping[str, Any]) -> Any:
    """Capture the snapshot from the keyword arguments resolved before the function call (including the default values).

    :param a_snapshot: snapshot to be captured
    :param resolved_kwargs: resolved keyword arguments (including the default values)
    :return: captured value"""
    if a_snapshot.arg is not None:
        if a_snapshot.arg not in resolved_kwargs:
            raise TypeError('The argument of the snapshot has not been set: {}. Does the original function define it? Did you supply it in the call?'.format(a_snapshot.arg))
        value = a_snapshot.capture(**{a_snapshot.arg: resolved_kwargs[a_snapshot.arg]})
    else:
        value = a_snapshot.capture()
    return value

def _find_self(param_names: List[str], args: Tuple[Any, ...], kwargs: Dict[str, Any]) -> Any:
    """Find the instance of ``self`` in the arguments."""
    instance_i = param_names.index('self')
    if instance_i < len(args):
        instance = args[instance_i]
    else:
        instance = kwargs['self']
    return instance

def Mixed(*types):
    """Mixed type, used to indicate a field in a schema can be
    one of many types. Use as a last resort only.
    The Mixed type can be used directly as a class to indicate
    any type is permitted for a given field:
    `"my_field": {"type": Mixed}`
    It can also be instantiated with list of specific types the
    field may is allowed to be for more control:
    `"my_field": {"type": Mixed(ObjectId, int)}`"""
    if len(types) < 2:
        raise ValueError('Mixed type requires at least 2 specific types')
    types = set(types)
    class MixedType(type):
        def __instancecheck__(cls, instance):
            """Returns true if the given value is an instance of
            one of the types enclosed by this mixed type."""
            for mtype in types:
                if isinstance(instance, mtype):
                    return True
            return False
    class Mixed(object):
        __metaclass__ = MixedType
    return Mixed

def one_of(*args):
    """Validates that a field value matches one of the values
    given to this validator."""
    if len(args) == 1 and isinstance(args[0], list):
        items = args[0]
    else:
        items = list(args)
    def validate(value):
        if not value in items:
            return e('{} is not in the list {}', value, items)
    return validate

def gte(min_value):
    """Validates that a field value is greater than or equal to the
    value given to this validator."""
    def validate(value):
        if value < min_value:
            return e('{} is not greater than or equal to {}', value, min_value)
    return validate

def lte(max_value):
    """Validates that a field value is less than or equal to the
    value given to this validator."""
    def validate(value):
        if value > max_value:
            return e('{} is not less than or equal to {}', value, max_value)
    return validate

def lt(lt_value):
    """Validates that a field value is less than the
    value given to this validator."""
    def validate(value):
        if value >= lt_value:
            return e('{} is not less than {}', value, lt_value)
    return validate

def between(min_value, max_value):
    """Validates that a field value is between the two values
    given to this validator."""
    def validate(value):
        if value < min_value:
            return e('{} is not greater than or equal to {}', value, min_value)
        if value > max_value:
            return e('{} is not less than or equal to {}', value, max_value)
    return validate

def length(min=None, max=None):
    """Validates that a field value's length is between the bounds given to this
    validator."""
    def validate(value):
        if min and len(value) < min:
            return e('{} does not have a length of at least {}', value, min)
        if max and len(value) > max:
            return e('{} does not have a length of at most {}', value, max)
    return validate

def each_item(*validators):
    """A wrapper which applies the given validators to each item in a field
    value of type `list`.

    Example usage in a Schema:

    "my_list_field": {"type": Array(int), "validates": each_item(lte(10))}"""
    def validate(value):
        for item in value:
            for validator in validators:
                error = validator(item)
                if error:
                    return error
        return None
    return validate

def distinct():
    """Validates that all items in the given field list value are distinct,
    i.e. that the list contains no duplicates."""
    def validate(value):
        for i, item in enumerate(value):
            if item in value[i + 1:]:
                return e('{} is not a distinct set of values', value)
    return validate

def as_dict(config):
    """Converts a ConfigParser object into a dictionary.

    The resulting dictionary has sections as keys which point to a dict of the
    sections options as key => value pairs."""
    settings = defaultdict(lambda: {})
    for section in config.sections():
        for key, val in config.items(section):
            settings[section][key] = val
    return settings

def get_webpack(request, name='DEFAULT'):
    """Get the Webpack object for a given webpack config.

    Called at most once per request per config name."""
    if not hasattr(request, '_webpack_map'):
        request._webpack_map = {}
    wp = request._webpack_map.get(name)
    if wp is None:
        wp = request._webpack_map[name] = Webpack(request, name)
    return wp

def includeme(config):
    """Add pyramid_webpack methods and config to the app"""
    settings = config.registry.settings
    root_package_name = config.root_package.__name__
    config.registry.webpack = {'DEFAULT': WebpackState(settings, root_package_name)}
    for extra_config in aslist(settings.get('webpack.configs', [])):
        state = WebpackState(settings, root_package_name, name=extra_config)
        config.registry.webpack[extra_config] = state
    for state in six.itervalues(config.registry.webpack):
        if state.static_view:
            config.add_static_view(name=state.static_view_name, path=state.static_view_path, cache_max_age=state.cache_max_age)
    config.add_request_method(get_webpack, 'webpack')

def escape_queue(s):
    """Escapes the path to a queue, e.g. preserves ~ at the begining.
    """
    if isinstance(s, PosixPath):
        s = unicode_(s)
    elif isinstance(s, bytes):
        s = s.decode('utf-8')
    if s.startswith('~/'):
        return '~/' + shell_escape(s[2:])
    else:
        return shell_escape(s)

def parse_ssh_destination(destination):
    """Parses the SSH destination argument.
    """
    match = _re_ssh.match(destination)
    if not match:
        raise InvalidDestination('Invalid destination: %s' % destination)
    user, password, host, port = match.groups()
    info = {}
    if user:
        info['username'] = user
    else:
        info['username'] = getpass.getuser()
    if password:
        info['password'] = password
    if port:
        info['port'] = int(port)
    info['hostname'] = host
    return info

def activate(lancet, method, project):
    """Switch to this project."""
    with taskstatus('Looking up project') as ts:
        if method == 'key':
            func = get_project_keys
        elif method == 'dir':
            func = get_project_keys
        for key, project_path in func(lancet):
            if key.lower() == project.lower():
                break
        else:
            ts.abort('Project "{}" not found (using {}-based lookup)', project, method)
    config = load_config(os.path.join(project_path, LOCAL_CONFIG))
    lancet.defer_to_shell('cd', project_path)
    venv = config.get('lancet', 'virtualenv', fallback=None)
    if venv:
        venv_path = os.path.join(project_path, os.path.expanduser(venv))
        activate_script = os.path.join(venv_path, 'bin', 'activate')
        lancet.defer_to_shell('source', activate_script)
    elif 'VIRTUAL_ENV' in os.environ:
        lancet.defer_to_shell('deactivate')

def ssh(lancet, print_cmd, environment):
    """SSH into the given environment, based on the dploi configuration."""
    namespace = {}
    with open(lancet.config.get('dploi', 'deployment_spec')) as fh:
        code = compile(fh.read(), 'deployment.py', 'exec')
        exec(code, {}, namespace)
    config = namespace['settings'][environment]
    host = '{}@{}'.format(config['user'], config['hosts'][0])
    cmd = ['ssh', '-p', str(config.get('port', 22)), host]
    if print_cmd:
        click.echo(' '.join((quote(s) for s in cmd)))
    else:
        lancet.defer_to_shell(*cmd)

def _arguments(ctx, command_name=None):
    """Prints a list of arguments for shell completion hooks.

    If a command name is given, returns the arguments for that subcommand.
    The command name has to refer to a command; aliases are not supported."""
    ctx = ctx.parent
    main = ctx.command
    if command_name:
        command = main.get_command(ctx, command_name)
        if not command:
            return
    else:
        command = main
    types = ['option', 'argument']
    all_params = sorted(command.get_params(ctx), key=lambda p: types.index(p.param_type_name))
    def get_name(param):
        return max(param.opts, key=len)
    for param in all_params:
        if param.param_type_name == 'option':
            option = get_name(param)
            same_dest = [get_name(p) for p in all_params if p.name == param.name]
            if same_dest:
                option = '({})'.format(' '.join(same_dest)) + option
            if param.help:
                option += '[{}]'.format(param.help or '')
            if not param.is_flag:
                option += '=:( )'
            click.echo(option)
        elif param.param_type_name == 'argument':
            option = get_name(param)
            click.echo(':{}'.format(option))

def init_project_env(subject='Automation', proj_path=None, sysencoding='utf-8', debug=False):
    """Set the environment for pyrunner"""
    if not proj_path:
        try:
            executable_file_path = os.path.dirname(os.path.abspath(inspect.stack()[-1][1]))
        except:
            executable_file_path = os.path.dirname(sys.path[0])
        finally:
            proj_path = executable_file_path
    p = os.path.join(proj_path, subject)
    proj_conf = {'sys_coding': sysencoding, 'debug': debug, 'module_name': os.path.splitext(os.path.basename(subject))[0], 'cfg_file': os.path.join(p, 'config.ini'), 'path': {'root': p, 'case': os.path.join(p, 'testcase'), 'data': os.path.join(p, 'data'), 'buffer': os.path.join(p, 'buffer'), 'resource': os.path.join(p, 'resource'), 'tools': os.path.join(p, 'tools'), 'rst': os.path.join(p, 'result'), 'rst_log': os.path.join(p, 'result', 'testcase'), 'rst_shot': os.path.join(p, 'result', 'screenshots')}}
    [FileSystemUtils.mkdirs(v) for v in proj_conf['path'].values()]
    sys.path.append(p) if os.path.isdir(p) else ''
    return proj_conf

def map_function(func_str, fw_action_addtion=None, bw_action_addtion=None, alias_func=None):
    """Sample usage:
    print map_function('set',alias_func = "ini_items");# -> ini_items
    print map_function('set',fw_action_addtion="action_steps_",bw_action_addtion="_for_upd",alias_func = "ini_items"); # -> action_steps_ini_items_for_upd
    print map_function('set(a=1,b=2,c=Test())',"action_steps_","_for_upd","ini_items");# -> action_steps_ini_items_for_upd(a=1,b=2,c=Test())
    print map_function('set("login",a="good",b=Test())',"action_steps_","_for_upd");# -> action_steps_set_for_upd("login",a="good",b=Test())"""
    split_action_value = re.compile('^(\\w+)(\\((.*)\\)$)?')
    matched = split_action_value.match(func_str)
    if matched:
        action = matched.group(1).lower()
        value = matched.group(2)
        if alias_func:
            action = alias_func
        if fw_action_addtion:
            action = fw_action_addtion + action
        if fw_action_addtion:
            action = action + bw_action_addtion
        if value:
            return action + value
        else:
            return action

def shell_escape(s):
    """Given bl"a, returns "bl\\\\"a".
    """
    if isinstance(s, PosixPath):
        s = unicode_(s)
    elif isinstance(s, bytes):
        s = s.decode('utf-8')
    if not s or any((c not in safe_shell_chars for c in s)):
        return '"%s"' % s.replace('\\', '\\\\').replace('"', '\\"').replace('`', '\\`').replace('$', '\\$')
    else:
        return s

