    text_filter = SUPPORTED_LANGUAGES.get(language, None)
    if not text_filter:
        raise ImproperlyConfigured('markup filter does not exist: {0}. Valid options are: {1}'.format(language, ', '.join(list(SUPPORTED_LANGUAGES.keys()))))
