def treenav_save_other_object_handler(sender, instance, created, **kwargs):
    """This signal attempts to update the HREF of any menu items that point to
    another model object, when that objects is saved."""
    from django.contrib.contenttypes.models import ContentType
    from .models import MenuItem
    cache_key = 'django-treenav-menumodels'
    if sender == MenuItem:
        cache.delete(cache_key)
    menu_models = cache.get(cache_key)
    if not menu_models:
        menu_models = []
        for menu_item in MenuItem.objects.exclude(content_type__isnull=True):
            menu_models.append(menu_item.content_type.model_class())
        cache.set(cache_key, menu_models)
    if sender in menu_models:
        ct = ContentType.objects.get_for_model(sender)
        items = MenuItem.objects.filter(content_type=ct, object_id=instance.pk)
        for item in items:
            if item.href != instance.get_absolute_url():
                item.href = instance.get_absolute_url()
                item.save()

def format_exception(exception):
    """Format an exception as diagnostics output.

    exception is the tuple as expected from sys.exc_info."""
    exception_lines = traceback.format_exception(*exception)
    lines = ''.join(exception_lines).splitlines(True)
    return format_as_diagnostics(lines)

def model_node(**kwargs):
    """Decorates a ``schematics.Model`` class to add it as a field
    of type ``schematic.types.ModelType``.

    Keyword arguments are passed to ``schematic.types.ModelType``.

    Example:

    .. code-block:: python
        :emphasize-lines: 8,13

        from schematics import Model, types
        from rafter.contrib.schematics.helpers import model_node


        class MyModel(Model):
            name = types.StringType()

            @model_node()
            class options(Model):
                status = types.IntType()

            # With arguments and another name
            @model_node(serialized_name='extra', required=True)
            class _extra(Model):
                test = types.StringType()"""
    kwargs.setdefault('default', {})
    def decorator(model):
        return types.ModelType(model, **kwargs)
    return decorator

def _write_int(fname, data, append=True):
    """Write data to CSV file with validation."""
    data_ex = pexdoc.exh.addex(ValueError, 'There is no data to save to file')
    fos_ex = pexdoc.exh.addex(OSError, 'File *[fname]* could not be created: *[reason]*')
    data_ex(len(data) == 0 or (len(data) == 1 and len(data[0]) == 0))
    try:
        pmisc.make_dir(fname)
        mode = 'w' if append is False else 'a'
        if sys.hexversion < 50331648:
            with open(fname, mode) as file_handle:
                csv.writer(file_handle, delimiter=',').writerows(data)
        else:
            with open(fname, mode, newline='') as file_handle:
                csv.writer(file_handle, delimiter=',').writerows(data)
    except (IOError, OSError) as eobj:
        fos_ex(True, _MF('fname', fname, 'reason', eobj.strerror))

def get_nearest_by_numeric_key(data: dict, key: int) -> Any:
    """Return the dict element whose numeric key is closest to a target."""
    return data.get(key, data[min(data.keys(), key=lambda k: abs(k - key))])

def get_nearest_by_coordinates(data: list, latitude_key: str, longitude_key: str, target_latitude: float, target_longitude: float) -> Any:
    """Get the closest dict entry based on latitude/longitude."""
    return min(data, key=lambda p: haversine(target_latitude, target_longitude, float(p[latitude_key]), float(p[longitude_key])))

def _doAtomicFileCreation(filePath):
    """Tries to atomically create the requested file."""
    try:
        _os.close(_os.open(filePath, _os.O_CREAT | _os.O_EXCL))
        return True
    except OSError as e:
        if e.errno == _errno.EEXIST:
            return False
        else:
            raise e

def _errstr(value):
    """Returns the value str, truncated to MAX_ERROR_STR_LEN characters. If
    it's truncated, the returned value will have '...' on the end."""
    value = str(value)
    if len(value) > MAX_ERROR_STR_LEN:
        return value[:MAX_ERROR_STR_LEN] + '...'
    else:
        return value

def _getStrippedValue(value, strip):
    """Like the strip() string method, except the strip argument describes
    different behavior:

    If strip is None, whitespace is stripped.

    If strip is a string, the characters in the string are stripped.

    If strip is False, nothing is stripped."""
    if strip is None:
        value = value.strip()
    elif isinstance(strip, str):
        value = value.strip(strip)
    elif strip is False:
        pass
    return value

def _raiseValidationException(standardExcMsg, customExcMsg=None):
    """Raise ValidationException with standardExcMsg, unless customExcMsg is specified."""
    if customExcMsg is None:
        raise ValidationException(str(standardExcMsg))
    else:
        raise ValidationException(str(customExcMsg))

def _validateParamsFor__validateToDateTimeFormat(formats, blank=False, strip=None, allowlistRegexes=None, blocklistRegexes=None, excMsg=None):
    """Raises PySimpleValidateException if the arguments are invalid. This is called by
    the validateTime() function to check its arguments. This code was
    refactored out to a separate function so that the PyInputPlus module (or
    other modules) could check their parameters' arguments for inputTime()."""
    _validateGenericParameters(blank=blank, strip=strip, allowlistRegexes=allowlistRegexes, blocklistRegexes=blocklistRegexes)
    if formats is None:
        raise PySimpleValidateException('formats parameter must be specified')
    if isinstance(formats, str):
        raise PySimpleValidateException('formats argument must be a non-str sequence of strftime format strings')
    try:
        len(formats)
    except:
        raise PySimpleValidateException('formats argument must be a non-str sequence of strftime format strings')
    for format in formats:
        try:
            time.strftime(format)
        except:
            raise PySimpleValidateException('formats argument contains invalid strftime format strings')

def get_commits(repo_dir, old_commit, new_commit, hide_merges=True):
    """Find all commits between two commit SHAs."""
    repo = Repo(repo_dir)
    commits = repo.iter_commits(rev='{0}..{1}'.format(old_commit, new_commit))
    if hide_merges:
        return [x for x in commits if not x.summary.startswith('Merge ')]
    else:
        return list(commits)

def get_commit_url(repo_url):
    """Determine URL to view commits for repo."""
    if 'github.com' in repo_url:
        return repo_url[:-4] if repo_url.endswith('.git') else repo_url
    if 'git.openstack.org' in repo_url:
        uri = '/'.join(repo_url.split('/')[-2:])
        return 'https://github.com/{0}'.format(uri)
    return repo_url

def get_projects(osa_repo_dir, commit):
    """Get all projects from multiple YAML files."""
    repo = Repo(osa_repo_dir)
    checkout(repo, commit)
    yaml_files = glob.glob('{0}/playbooks/defaults/repo_packages/*.yml'.format(osa_repo_dir))
    yaml_parsed = []
    for yaml_file in yaml_files:
        with open(yaml_file, 'r') as f:
            yaml_parsed.append(yaml.load(f))
    merged_dicts = {k: v for d in yaml_parsed for k, v in d.items()}
    return normalize_yaml(merged_dicts)

def make_osa_report(repo_dir, old_commit, new_commit, args):
    """Create initial RST report header for OpenStack-Ansible."""
    update_repo(repo_dir, args.osa_repo_url, args.update)
    validate_commits(repo_dir, [old_commit, new_commit])
    validate_commit_range(repo_dir, old_commit, new_commit)
    commits = get_commits(repo_dir, old_commit, new_commit)
    template_vars = {'args': args, 'repo': 'openstack-ansible', 'commits': commits, 'commit_base_url': get_commit_url(args.osa_repo_url), 'old_sha': old_commit, 'new_sha': new_commit}
    return render_template('offline-header.j2', template_vars)

def make_report(storage_directory, old_pins, new_pins, do_update=False, version_mappings=None):
    """Create RST report from a list of projects/roles."""
    report = ''
    version_mappings = version_mappings or {}
    for new_pin in new_pins:
        repo_name, repo_url, commit_sha = new_pin
        commit_sha = version_mappings.get(repo_name, {}).get(commit_sha, commit_sha)
        repo_dir = '{0}/{1}'.format(storage_directory, repo_name)
        update_repo(repo_dir, repo_url, do_update)
        try:
            commit_sha_old = next((x[2] for x in old_pins if x[0] == repo_name))
        except Exception:
            continue
        else:
            commit_sha_old = version_mappings.get(repo_name, {}).get(commit_sha_old, commit_sha_old)
        validate_commits(repo_dir, [commit_sha_old, commit_sha])
        commits = get_commits(repo_dir, commit_sha_old, commit_sha)
        template_vars = {'repo': repo_name, 'commits': commits, 'commit_base_url': get_commit_url(repo_url), 'old_sha': commit_sha_old, 'new_sha': commit_sha}
        rst = render_template('offline-repo-changes.j2', template_vars)
        report += rst
    return report

def normalize_yaml(yaml):
    """Normalize the YAML from project and role lookups.

    These are returned as a list of tuples."""
    if isinstance(yaml, list):
        normalized_yaml = [(x['name'], x['src'], x.get('version', 'HEAD')) for x in yaml]
    else:
        projects = [x[:-9] for x in yaml.keys() if x.endswith('git_repo')]
        normalized_yaml = []
        for project in projects:
            repo_url = yaml['{0}_git_repo'.format(project)]
            commit_sha = yaml['{0}_git_install_branch'.format(project)]
            normalized_yaml.append((project, repo_url, commit_sha))
    return normalized_yaml

def prepare_storage_dir(storage_directory):
    """Prepare the storage directory."""
    storage_directory = os.path.expanduser(storage_directory)
    if not os.path.exists(storage_directory):
        os.mkdir(storage_directory)
    return storage_directory

def validate_commits(repo_dir, commits):
    """Test if a commit is valid for the repository."""
    log.debug('Validating {c} exist in {r}'.format(c=commits, r=repo_dir))
    repo = Repo(repo_dir)
    for commit in commits:
        try:
            commit = repo.commit(commit)
        except Exception:
            msg = 'Commit {commit} could not be found in repo {repo}. You may need to pass --update to fetch the latest updates to the git repositories stored on your local computer.'.format(repo=repo_dir, commit=commit)
            raise exceptions.InvalidCommitException(msg)
    return True

def validate_commit_range(repo_dir, old_commit, new_commit):
    """Check if commit range is valid. Flip it if needed."""
    try:
        commits = get_commits(repo_dir, old_commit, new_commit)
    except Exception:
        commits = []
    if len(commits) == 0:
        try:
            commits = get_commits(repo_dir, new_commit, old_commit)
        except Exception:
            commits = []
        if len(commits) == 0:
            msg = 'The commit range {0}..{1} is invalid for {2}.You may need to use the --update option to fetch the latest updates to the git repositories stored on your local computer.'.format(old_commit, new_commit, repo_dir)
            raise exceptions.InvalidCommitRangeException(msg)
        else:
            return 'flip'
    return True

def _homogenize_data_filter(dfilter):
    """Make data filter definition consistent.

    Create a tuple where first element is the row filter and the second element
    is the column filter"""
    if isinstance(dfilter, tuple) and len(dfilter) == 1:
        dfilter = (dfilter[0], None)
    if dfilter is None or dfilter == (None, None) or dfilter == (None,):
        dfilter = (None, None)
    elif isinstance(dfilter, dict):
        dfilter = (dfilter, None)
    elif isinstance(dfilter, (list, str)) or (isinstance(dfilter, int) and (not isinstance(dfilter, bool))):
        dfilter = (None, dfilter if isinstance(dfilter, list) else [dfilter])
    elif isinstance(dfilter[0], dict) or (dfilter[0] is None and (not isinstance(dfilter[1], dict))):
        pass
    else:
        dfilter = (dfilter[1], dfilter[0])
    return dfilter

def _tofloat(obj):
    """Convert to float if object is a float string."""
    if 'inf' in obj.lower().strip():
        return obj
    try:
        return int(obj)
    except ValueError:
        try:
            return float(obj)
        except ValueError:
            return obj

def _timeoutDeferred(deferred, timeout):
    """Cancels the given deferred after the given time, if it has not yet callbacked/errbacked it."""
    delayedCall = reactor.callLater(timeout, deferred.cancel)
    def gotResult(result):
        if delayedCall.active():
            delayedCall.cancel()
        return result
    deferred.addBoth(gotResult)

def _get_json(value):
    """Convert the given value to a JSON object."""
    if hasattr(value, 'replace'):
        value = value.replace('\n', ' ')
    try:
        return json.loads(value)
    except json.JSONDecodeError:
        if hasattr(value, 'replace'):
            value = value.replace('"', '\\"')
        return json.loads('"{}"'.format(value))

def save_list(key, *values):
    """Convert the given list of parameters to a JSON object.

    JSON object is of the form:
    { key: [values[0], values[1], ... ] },
    where values represent the given list of parameters."""
    return json.dumps({key: [_get_json(value) for value in values]})

def save_file(key, file_path, *refs):
    """Convert the given parameters to a special JSON object.

    JSON object is of the form:
    { key: {"file": file_path}}, or
    { key: {"file": file_path, "refs": [refs[0], refs[1], ... ]}}"""
    if not os.path.isfile(file_path):
        return error("Output '{}' set to a missing file: '{}'.".format(key, file_path))
    result = {key: {'file': file_path}}
    if refs:
        missing_refs = [ref for ref in refs if not (os.path.isfile(ref) or os.path.isdir(ref))]
        if len(missing_refs) > 0:
            return error("Output '{}' set to missing references: '{}'.".format(key, ', '.join(missing_refs)))
        result[key]['refs'] = refs
    return json.dumps(result)

def save_file_list(key, *files_refs):
    """Convert the given parameters to a special JSON object.

    Each parameter is a file-refs specification of the form:
    <file-path>:<reference1>,<reference2>, ...,
    where the colon ':' and the list of references are optional.

    JSON object is of the form:
    { key: {"file": file_path}}, or
    { key: {"file": file_path, "refs": [refs[0], refs[1], ... ]}}"""
    file_list = []
    for file_refs in files_refs:
        if ':' in file_refs:
            try:
                file_name, refs = file_refs.split(':')
            except ValueError as e:
                return error("Only one colon ':' allowed in file-refs specification.")
        else:
            file_name, refs = (file_refs, None)
        if not os.path.isfile(file_name):
            return error("Output '{}' set to a missing file: '{}'.".format(key, file_name))
        file_obj = {'file': file_name}
        if refs:
            refs = [ref_path.strip() for ref_path in refs.split(',')]
            missing_refs = [ref for ref in refs if not (os.path.isfile(ref) or os.path.isdir(ref))]
            if len(missing_refs) > 0:
                return error("Output '{}' set to missing references: '{}'.".format(key, ', '.join(missing_refs)))
            file_obj['refs'] = refs
        file_list.append(file_obj)
    return json.dumps({key: file_list})

