    return []

def _pinyin_generator(chars, format):
    """Generate pinyin for chars, if char is not chinese character,
    itself will be returned.
    Chars must be unicode list."""
    for char in chars:
        key = '%X' % ord(char)
        pinyin = pinyin_dict.get(key, char)
        tone = pinyin_tone.get(key, 0)
        if tone == 0 or format == 'strip':
            pass
        elif format == 'numerical':
            pinyin += str(tone)
        elif format == 'diacritical':
            vowels = itertools.chain((c for c in pinyin if c in 'aeo'), (c for c in pinyin if c in 'iuv'))
            vowel = pinyin.index(next(vowels)) + 1
            pinyin = pinyin[:vowel] + tonemarks[tone] + pinyin[vowel:]
        else:
            error = 'Format must be one of: numerical/diacritical/strip'
            raise ValueError(error)
        yield unicodedata.normalize('NFC', pinyin)

def get(s, delimiter='', format='diacritical'):
    """Return pinyin of string, the string must be unicode
    """
    return delimiter.join(_pinyin_generator(u(s), format=format))

def get_initial(s, delimiter=' '):
    """Return the 1st char of pinyin of string, the string must be unicode
    """
    initials = (p[0] for p in _pinyin_generator(u(s), format='strip'))
    return delimiter.join(initials)

def translate_word(word, dictionary=['simplified']):
    """Return the set of translations for a single character or word, if
    available."""
    if not dictionaries:
        init()
    for d in dictionary:
        if word in dictionaries[d]:
            return dictionaries[d][word]
    return None

def _words_at_the_beginning(word, tree, prefix=''):
    """We return all portions of the tree corresponding to the beginning
    of `word`. This is used recursively, so we pass the prefix so we
    can return meaningful words+translations."""
    l = []
    if '' in tree:
        l.append([prefix, tree['']])
    if len(word) > 0 and word[0] in tree:
        l.extend(_words_at_the_beginning(word[1:], tree[word[0]], prefix=prefix + word[0]))
    return l

def all_phrase_translations(phrase):
    """Return the set of translations for all possible words in a full
    phrase. Chinese is sometimes ambiguous. We do not attempt to
    disambiguate, or handle unknown letters especially well. Full
    parsing is left to upstream logic."""
    if not trees:
        init()
    phrase = phrase.split(string.whitespace)
    for word in phrase:
        for x in range(len(word)):
            for translation in _words_at_the_beginning(word[x + 1:], trees['simplified'][word[x]], prefix=word[x]):
                yield translation

def token_at_cursor(code, pos=0):
    """Find the token present at the passed position in the code buffer
     :return (tuple): a pair (token, start_position)"""
    l = len(code)
    end = start = pos
    while end < l and code[end].isalpha():
        end += 1
    while start > 0 and code[start - 1].isalpha():
        start -= 1
    if start > 0 and code[start - 1] == '%':
        start -= 1
    return (code[start:end], start)

def escape(x, lb=False):
    """Ensure a string does not contain HTML-reserved characters (including
    double quotes)
    Optionally also insert a linebreak if the string is too long"""
    if lb:
        l = len(x)
        if l >= 10:
            l >>= 1
            s1 = x.find(' ', l)
            s2 = x.rfind(' ', 0, l)
            if s2 > 0:
                s = s2 if s1 < 0 or l - s1 > s2 - l else s1
                x = x[:s] + '\\n' + x[s + 1:]
            elif s1 > 0:
                x = x[:s1] + '\\n' + x[s1 + 1:]
    return x.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;').replace('"', '&quot;')

def div(txt, *args, **kwargs):
    """Create & return an HTML <div> element by wrapping the passed text buffer.
      @param txt (basestring): the text buffer to use
      @param *args (list): if present, \\c txt is considered a Python format
        string, and the arguments are formatted into it
      @param kwargs (dict): the \\c css field can contain the CSS class for the
        <div> element"""
    if args:
        txt = txt.format(*args)
    css = kwargs.get('css', HTML_DIV_CLASS)
    return u'<div class="{}">{!s}</div>'.format(css, txt)

def data_msglist(msglist):
    """Return a Jupyter display_data message, in both HTML & text formats, by
    joining together all passed messages.

      @param msglist (iterable): an iterable containing a list of tuples
        (message, css_style)

    Each message is either a text string, or a list. In the latter case it is
    assumed to be a format string + parameters."""
    txt = html = u''
    for msg, css in msglist:
        if is_collection(msg):
            msg = msg[0].format(*msg[1:])
        html += div(escape(msg).replace('\n', '<br/>'), css=css or 'msg')
        txt += msg + '\n'
    return {'data': {'text/html': div(html), 'text/plain': txt}, 'metadata': {}}

def data_msg(msg, mtype=None):
    """Return a Jupyter display_data message, in both HTML & text formats, by
    formatting a given single message. The passed message may be:
      * An exception (including a KrnlException): will generate an error message
      * A list of messages (with \\c mtype equal to \\c multi)
      * A single message

      @param msg (str,list): a string, or a list of format string + args,
        or an iterable of (msg,mtype)
      @param mtype (str): the message type (used for the CSS class). If
        it's \\c multi, then \\c msg will be treated as a multi-message. If
        not passed, \\c krn-error will be used for exceptions and \\c msg for
        everything else"""
    if isinstance(msg, KrnlException):
        return msg()
    elif isinstance(msg, Exception):
        return KrnlException(msg)()
    elif mtype == 'multi':
        return data_msglist(msg)
    else:
        return data_msglist([(msg, mtype)])

def install_kernel_resources(destdir, resource=PKGNAME, files=None):
    """Copy the resource files to the kernelspec folder."""
    if files is None:
        files = ['logo-64x64.png', 'logo-32x32.png']
    for filename in files:
        try:
            copyresource(resource, filename, destdir)
        except Exception as e:
            sys.stderr.write(str(e))

def remove_custom_css(destdir, resource=PKGNAME):
    """Remove the kernel CSS from custom.css"""
    if not os.path.isdir(destdir):
        return False
    custom = os.path.join(destdir, 'custom.css')
    copy = True
    found = False
    prefix = css_frame_prefix(resource)
    with io.open(custom + '-new', 'wt') as fout:
        with io.open(custom) as fin:
            for line in fin:
                if line.startswith(prefix + 'START'):
                    copy = False
                    found = True
                elif line.startswith(prefix + 'END'):
                    copy = True
                elif copy:
                    fout.write(line)
    if found:
        os.rename(custom + '-new', custom)
    else:
        os.unlink(custom + '-new')
    return found

def html_elem(e, ct, withtype=False):
    """Format a result element as an HTML table cell.
      @param e (list): a pair \\c (value,type)
      @param ct (str): cell type (th or td)
      @param withtype (bool): add an additional cell with the element type"""
    if ct == 'th':
        return '<th>{0}</th><th>{1}</th>'.format(*e) if withtype else '<th>{}</th>'.format(e)
    if e[1] in ('uri', 'URIRef'):
        html = u'<{0} class=val><a href="{1}" target="_other">{2}</a></{0}>'.format(ct, e[0], escape(e[0]))
    else:
        html = u'<{0} class=val>{1}</{0}>'.format(ct, escape(e[0]))
    if withtype:
        html += u'<{0} class=typ>{1}</{0}>'.format(ct, e[1])
    return html

def html_table(data, header=True, limit=None, withtype=False):
    """Return a double iterable as an HTML table
      @param data (iterable): the data to format
      @param header (bool): if the first row is a header row
      @param limit (int): maximum number of rows to render (excluding header)
      @param withtype (bool): if columns are to have an alternating CSS class
        (even/odd) or not.
      @return (int,string): a pair <number-of-rendered-rows>, <html-table>"""
    if header and limit:
        limit += 1
    ct = 'th' if header else 'td'
    rc = 'hdr' if header else 'odd'
    html = u'<table>'
    rn = -1
    for rn, row in enumerate(data):
        html += u'<tr class={}>'.format(rc)
        html += '\n'.join((html_elem(c, ct, withtype) for c in row))
        html += u'</tr>'
        rc = 'even' if rc == 'odd' else 'odd'
        ct = 'td'
        if limit:
            limit -= 1
            if not limit:
                break
    return (0, '') if rn < 0 else (rn + 1 - header, html + u'</table>')

def jtype(c):
    """Return the a string with the data type of a value, for JSON data"""
    ct = c['type']
    return ct if ct != 'literal' else '{}, {}'.format(ct, c.get('xml:lang'))

def gtype(n):
    """Return the a string with the data type of a value, for Graph data"""
    t = type(n).__name__
    return str(t) if t != 'Literal' else 'Literal, {}'.format(n.language)

def lang_match_json(row, hdr, accepted_languages):
    """Find if the JSON row contains acceptable language data"""
    if not accepted_languages:
        return True
    languages = set([row[c].get('xml:lang') for c in hdr if c in row and row[c]['type'] == 'literal'])
    return not languages or languages & accepted_languages

def lang_match_rdf(triple, accepted_languages):
    """Find if the RDF triple contains acceptable language data"""
    if not accepted_languages:
        return True
    languages = set([n.language for n in triple if isinstance(n, Literal)])
    return not languages or languages & accepted_languages

def lang_match_xml(row, accepted_languages):
    """Find if the XML row contains acceptable language data"""
    if not accepted_languages:
        return True
    column_languages = set()
    for elem in row:
        lang = elem[0].attrib.get(XML_LANG, None)
        if lang:
            column_languages.add(lang)
    return not column_languages or column_languages & accepted_languages

def json_iterator(hdr, rowlist, lang, add_vtype=False):
    """Convert a JSON response into a double iterable, by rows and columns
    Optionally add element type, and filter triples by language (on literals)"""
    yield (hdr if not add_vtype else ((h, 'type') for h in hdr))
    for row in rowlist:
        if lang and (not lang_match_json(row, hdr, lang)):
            continue
        yield ((row[c]['value'], jtype(row[c])) if c in row else ('', '') for c in hdr)

def rdf_iterator(graph, lang, add_vtype=False):
    """Convert a Graph response into a double iterable, by triples and elements.
    Optionally add element type, and filter triples by language (on literals)"""
    hdr = ('subject', 'predicate', 'object')
    yield (hdr if not add_vtype else ((h, 'type') for h in hdr))
    for row in graph:
        if lang and (not lang_match_rdf(row, lang)):
            continue
        yield ((unicode(c), gtype(c)) for c in row)

def render_json(result, cfg, **kwargs):
    """Render to output a result in JSON format"""
    result = json.loads(result.decode('utf-8'))
    head = result['head']
    if 'results' not in result:
        if 'boolean' in result:
            r = u'Result: {}'.format(result['boolean'])
        else:
            r = u'Unsupported result: \n' + unicode(result)
        return {'data': {'text/plain': r}, 'metadata': {}}
    vars = head['vars']
    nrow = len(result['results']['bindings'])
    if cfg.dis == 'table':
        j = json_iterator(vars, result['results']['bindings'], set(cfg.lan), add_vtype=cfg.typ)
        n, data = html_table(j, limit=cfg.lmt, withtype=cfg.typ)
        data += div('Total: {}, Shown: {}', nrow, n, css='tinfo')
        data = {'text/html': div(data)}
    else:
        result = json.dumps(result, ensure_ascii=False, indent=2, sort_keys=True)
        data = {'text/plain': unicode(result)}
    return {'data': data, 'metadata': {}}

def xml_row(row, lang):
    """Generator for an XML row"""
    for elem in row:
        name = elem.get('name')
        child = elem[0]
        ftype = re.sub('\\{[^}]+\\}', '', child.tag)
        if ftype == 'literal':
            ftype = '{}, {}'.format(ftype, child.attrib.get(XML_LANG, 'none'))
        yield (name, (child.text, ftype))

def xml_iterator(columns, rowlist, lang, add_vtype=False):
    """Convert an XML response into a double iterable, by rows and columns
    Options are: filter triples by language (on literals), add element type"""
    yield (columns if not add_vtype else ((h, 'type') for h in columns))
    for row in rowlist:
        if not lang_match_xml(row, lang):
            continue
        rowdata = {nam: val for nam, val in xml_row(row, lang)}
        yield (rowdata.get(field, ('', '')) for field in columns)

def label(x, gr, preferred_languages=None):
    """  @param x : graph entity
      @param gr (Graph): RDF graph
      @param preferred_languages (iterable)

    Return the best available label in the graph for the passed entity.
    If a set of preferred languages is given, try them in order. If none is
    found, an arbitrary language will be chosen"""
    labels = {l.language: l for labelProp in LABEL_PROPERTIES for l in gr.objects(x, labelProp)}
    if labels:
        if preferred_languages is not None:
            for l in preferred_languages:
                if l in labels:
                    return labels[l]
        return labels.itervalues().next()
    try:
        return gr.namespace_manager.compute_qname(x)[2].replace('_', ' ')
    except:
        m = re.search('([^/]+)$', x)
        return m.group(1).replace('_', ' ') if m else x

def draw_graph(g, fmt='svg', prg='dot', options={}):
    """Draw an RDF graph as an image"""
    buf = StringIO()
    rdf2dot(g, buf, options)
    gv_options = options.get('graphviz', [])
    if fmt == 'png':
        gv_options += ['-Gdpi=220', '-Gsize=25,10!']
        metadata = {'width': 5500, 'height': 2200, 'unconfined': True}
    image = run_dot(buf.getvalue(), fmt=fmt, options=gv_options, prg=prg)
    if fmt == 'png':
        return ({'image/png': base64.b64encode(image).decode('ascii')}, {'image/png': metadata})
    elif fmt == 'svg':
        return ({'image/svg+xml': image.decode('utf-8').replace('<svg', '<svg class="unconfined"', 1)}, {'unconfined': True})

def orient_averaged_adaptive(tm):
    """Compute the T-matrix using variable orientation scatterers.

    This method uses a very slow adaptive routine and should mainly be used
    for reference purposes. Uses the set particle orientation PDF, ignoring
    the alpha and beta attributes.

    Args:
        tm: TMatrix (or descendant) instance

    Returns:
        The amplitude (S) and phase (Z) matrices."""
    S = np.zeros((2, 2), dtype=complex)
    Z = np.zeros((4, 4))
    def Sfunc(beta, alpha, i, j, real):
        S_ang, Z_ang = tm.get_SZ_single(alpha=alpha, beta=beta)
        s = S_ang[i, j].real if real else S_ang[i, j].imag
        return s * tm.or_pdf(beta)
    ind = range(2)
    for i in ind:
        for j in ind:
            S.real[i, j] = dblquad(Sfunc, 0.0, 360.0, lambda x: 0.0, lambda x: 180.0, (i, j, True))[0] / 360.0
            S.imag[i, j] = dblquad(Sfunc, 0.0, 360.0, lambda x: 0.0, lambda x: 180.0, (i, j, False))[0] / 360.0
    def Zfunc(beta, alpha, i, j):
        S_and, Z_ang = tm.get_SZ_single(alpha=alpha, beta=beta)
        return Z_ang[i, j] * tm.or_pdf(beta)
    ind = range(4)
    for i in ind:
        for j in ind:
            Z[i, j] = dblquad(Zfunc, 0.0, 360.0, lambda x: 0.0, lambda x: 180.0, (i, j))[0] / 360.0
    return (S, Z)

def ldr(scatterer, h_pol=True):
    """Linear depolarizarion ratio (LDR) for the current setup.

    Args:
        scatterer: a Scatterer instance.
        h_pol: If True (default), return LDR_h.
        If False, return LDR_v.

    Returns:
       The LDR."""
    Z = scatterer.get_Z()
    if h_pol:
        return (Z[0, 0] - Z[0, 1] + Z[1, 0] - Z[1, 1]) / (Z[0, 0] - Z[0, 1] - Z[1, 0] + Z[1, 1])
    else:
        return (Z[0, 0] + Z[0, 1] - Z[1, 0] - Z[1, 1]) / (Z[0, 0] + Z[0, 1] + Z[1, 0] + Z[1, 1])

def ext_xsect(scatterer, h_pol=True):
    """Extinction cross section for the current setup, with polarization.

    Args:
        scatterer: a Scatterer instance.
        h_pol: If True (default), use horizontal polarization.
        If False, use vertical polarization.

    Returns:
        The extinction cross section."""
    if scatterer.psd_integrator is not None:
        try:
            return scatterer.psd_integrator.get_angular_integrated(scatterer.psd, scatterer.get_geometry(), 'ext_xsect')
        except AttributeError:
            pass
    old_geom = scatterer.get_geometry()
    thet0, thet, phi0, phi, alpha, beta = old_geom
    try:
        scatterer.set_geometry((thet0, thet0, phi0, phi0, alpha, beta))
        S = scatterer.get_S()
    finally:
        scatterer.set_geometry(old_geom)
    if h_pol:
        return 2 * scatterer.wavelength * S[1, 1].imag
    else:
        return 2 * scatterer.wavelength * S[0, 0].imag

def radar_xsect(scatterer, h_pol=True):
    """Radar cross section for the current setup.

    Args:
        scatterer: a Scatterer instance.
        h_pol: If True (default), use horizontal polarization.
        If False, use vertical polarization.

    Returns:
        The radar cross section."""
    Z = scatterer.get_Z()
    if h_pol:
        return 2 * np.pi * (Z[0, 0] - Z[0, 1] - Z[1, 0] + Z[1, 1])
    else:
        return 2 * np.pi * (Z[0, 0] + Z[0, 1] + Z[1, 0] + Z[1, 1])

def _group_by(data, criteria):
    """Group objects in data using a function or a key"""
    if isinstance(criteria, str):
        criteria_str = criteria
        def criteria(x):
            return x[criteria_str]
    res = defaultdict(list)
    for element in data:
        key = criteria(element)
        res[key].append(element)
    return res

def _get_params_value(params):
    """Given an iterator (k1, k2), returns a function that when called
    with an object obj returns a tuple of the form:
    ((k1, obj.parameters[k1]), (k2, obj.parameters[k2]))"""
    ord_params = sorted(params)
    def fn(obj):
        l = []
        for p in ord_params:
            try:
                l.append((p, obj.parameters[p]))
            except:
                raise ValueError('{} is not a valid parameter'.format(p))
        return tuple(l)
    return fn

def _product(k, v):
    """Perform the product between two objects
    even if they don't support iteration"""
    if not _can_iterate(k):
        k = [k]
    if not _can_iterate(v):
        v = [v]
    return list(product(k, v))

def _mapping_to_tuple_pairs(d):
    """Convert a mapping object (such as a dictionary) to tuple pairs,
    using its keys and values to generate the pairs and then generating
    all possible combinations between those
    e.g. {1: (1,2,3)} -> (((1, 1),), ((1, 2),), ((1, 3),))"""
    t = []
    ord_keys = sorted(d.keys())
    for k in ord_keys:
        t.append(_product(k, d[k]))
    return tuple(product(*t))

def precision_at(y_true, y_score, proportion, ignore_nas=False):
    """Calculates precision at a given proportion.
    Only supports binary classification."""
    scores_sorted = np.sort(y_score)[::-1]
    cutoff_index = max(int(len(y_true) * proportion) - 1, 0)
    cutoff_value = scores_sorted[cutoff_index]
    scores_binary = np.array([int(y >= cutoff_value) for y in y_score])
    if ignore_nas:
        precision = __precision(y_true, scores_binary)
    else:
        precision = precision_score(y_true, scores_binary)
    return (precision, cutoff_value)

def _escape_path(key):
    """Replace '/', '\\' in key"""
    return _tobytes(key).replace(b'$', b'$_').replace(b'/', b'$+').replace(b'\\', b'$$')

def create_option_from_value(tag, value):
    """Set DHCP option with human friendly value"""
    dhcp_option.parser()
    fake_opt = dhcp_option(tag=tag)
    for c in dhcp_option.subclasses:
        if c.criteria(fake_opt):
            if hasattr(c, '_parse_from_value'):
                return c(tag=tag, value=c._parse_from_value(value))
            else:
                raise ValueError('Invalid DHCP option ' + str(tag) + ': ' + repr(value))
    else:
        fake_opt._setextra(_tobytes(value))
        return fake_opt

def create_dhcp_options(input_dict, ignoreError=False, generateNone=False):
    """Try best to create dhcp_options from human friendly values, ignoring
    invalid values"""
    retdict = {}
    for k, v in dict(input_dict).items():
        try:
            if generateNone and v is None:
                retdict[k] = None
            else:
                try:
                    retdict[k] = create_option_from_value(k, v)
                except _EmptyOptionException:
                    if generateNone:
                        retdict[k] = None
        except Exception:
            if ignoreError:
                continue
            else:
                raise
    return retdict

def default_start():
    """Use `sys.argv` for starting parameters. This is the entry-point of `vlcp-start`"""
    config, daemon, pidfile, startup, fork = parsearg()
    if config is None:
        if os.path.isfile('/etc/vlcp.conf'):
            config = '/etc/vlcp.conf'
        else:
            print('/etc/vlcp.conf is not found; start without configurations.')
    elif not config:
        config = None
    main(config, startup, daemon, pidfile, fork)

def createphysicalnetwork(type, create_processor=partial(default_processor, excluding=('id', 'type')), reorder_dict=default_iterate_dict):
    """:param type: physical network type

    :param create_processor: create_processor(physicalnetwork, walk, write, \\*, parameters)"""
    def walker(walk, write, timestamp, parameters_dict):
        for key, parameters in reorder_dict(parameters_dict):
            try:
                value = walk(key)
            except KeyError:
                pass
            else:
                id_ = parameters['id']
                new_network = create_new(PhysicalNetwork, value, id_)
                new_network.type = type
                create_processor(new_network, walk, write, parameters=parameters)
                write(key, new_network)
                new_networkmap = PhysicalNetworkMap.create_instance(id_)
                new_networkmap.network = new_network.create_weakreference()
                write(new_networkmap.getkey(), new_networkmap)
                try:
                    physet = walk(PhysicalNetworkSet.default_key())
                except KeyError:
                    pass
                else:
                    physet.set.dataset().add(new_network.create_weakreference())
                    write(physet.getkey(), physet)
    return walker

def deletephysicalnetwork(check_processor=default_physicalnetwork_delete_check, reorder_dict=default_iterate_dict):
    """:param check_processor: check_processor(physicalnetwork, physicalnetworkmap, walk, write, \\*, parameters)"""
    def walker(walk, write, timestamp, parameters_dict):
        for key, parameters in reorder_dict(parameters_dict):
            try:
                value = walk(key)
            except KeyError:
                pass
            else:
                id_ = parameters['id']
                try:
                    phy_map = walk(PhysicalNetworkMap.default_key(id_))
                except KeyError:
                    pass
                else:
                    check_processor(value, phy_map, walk, write, parameters=parameters)
                    write(phy_map.getkey(), None)
                try:
                    phynetset = walk(PhysicalNetworkSet.default_key())
                except KeyError:
                    pass
                else:
                    phynetset.set.dataset().discard(value.create_weakreference())
                    write(phynetset.getkey(), phynetset)
                write(key, None)
    return walker

def updatephysicalport(update_processor=partial(default_processor, excluding=('vhost', 'systemid', 'bridge', 'name'), disabled=('physicalnetwork',)), reorder_dict=default_iterate_dict):
    """:param update_processor: update_processor(physcialport, walk, write, \\*, parameters)"""
    def walker(walk, write, timestamp, parameters_dict):
        for key, parameters in reorder_dict(parameters_dict):
            try:
                value = walk(key)
            except KeyError:
                pass
            else:
                if update_processor(value, walk, write, parameters=parameters):
                    write(key, value)
    return walker

def deletephysicalport(check_processor=_false_processor, reorder_dict=default_iterate_dict):
    """:param check_processor: check_processor(physicalport, physicalnetwork, physicalnetworkmap,
                            walk, write \\*, parameters)"""
    def walker(walk, write, timestamp, parameters_dict):
        for key, parameters in reorder_dict(parameters_dict):
            try:
                value = walk(key)
            except KeyError:
                pass
            else:
                try:
                    phynet = walk(value.physicalnetwork.getkey())
                except KeyError:
                    pass
                else:
                    try:
                        phymap = walk(PhysicalNetworkMap._network.leftkey(phynet))
                    except KeyError:
                        pass
                    else:
                        check_processor(value, phynet, phymap, walk, write, parameters=parameters)
                        phymap.ports.dataset().discard(value.create_weakreference())
                        write(phymap.getkey(), phymap)
                try:
                    physet = walk(PhysicalPortSet.default_key())
                except KeyError:
                    pass
                else:
                    physet.set.dataset().discard(value.create_weakreference())
                    write(physet.getkey(), physet)
                write(key, None)
    return walker

def syscall_direct(*events):
    """Directly process these events. This should never be used for normal events."""
    def _syscall(scheduler, processor):
        for e in events:
            processor(e)
    return _syscall

def syscall_generator(generator):
    """Directly process events from a generator function. This should never be used for normal events."""
    def _syscall(scheduler, processor):
        for e in generator():
            processor(e)
    return _syscall

def syscall_clearqueue(queue):
    """Clear a queue"""
    def _syscall(scheduler, processor):
        qes, qees = queue.clear()
        events = scheduler.queue.unblockqueue(queue)
        for e in events:
            scheduler.eventtree.remove(e)
        for e in qes:
            processor(e)
        for e in qees:
            processor(e)
    return _syscall

def syscall_removequeue(queue, index):
    """Remove subqueue `queue[index]` from queue."""
    def _syscall(scheduler, processor):
        events = scheduler.queue.unblockqueue(queue[index])
        for e in events:
            scheduler.eventtree.remove(e)
        qes, qees = queue.removeSubQueue(index)
        for e in qes:
            processor(e)
        for e in qees:
            processor(e)
    return _syscall

def syscall_clearremovequeue(queue, index):
    """Clear the subqueue `queue[index]` and remove it from queue."""
    def _syscall(scheduler, processor):
        qes, qees = queue[index].clear()
        events = scheduler.queue.unblockqueue(queue[index])
        for e in events:
            scheduler.eventtree.remove(e)
        qes2, qees2 = queue.removeSubQueue(index)
        for e in qes:
            processor(e)
        for e in qes2:
            processor(e)
        for e in qees:
            processor(e)
        for e in qees2:
            processor(e)
    return _syscall

def return_self_updater(func):
    """Run func, but still return v. Useful for using knowledge.update with operates like append, extend, etc.
    e.g. return_self(lambda k,v: v.append('newobj'))"""
    @functools.wraps(func)
    def decorator(k, v):
        func(k, v)
        return v
    return decorator

def watch_context(keys, result, reqid, container, module='objectdb'):
    """DEPRECATED - use request_context for most use cases"""
    try:
        keys = [k for k, r in zip(keys, result) if r is not None]
        yield result
    finally:
        if keys:
            async def clearup():
                try:
                    await send_api(container, module, 'munwatch', {'keys': keys, 'requestid': reqid})
                except QuitException:
                    pass
            container.subroutine(clearup(), False)

def updater(f):
    """Decorate a function with named arguments into updater for transact"""
    @functools.wraps(f)
    def wrapped_updater(keys, values):
        result = f(*values)
        return (keys[:len(result)], result)
    return wrapped_updater

def create_new(cls, oldvalue, *args):
    """Raise  if the old value already exists"""
    if oldvalue is not None:
        raise AlreadyExistsException('%r already exists' % (oldvalue,))
    return cls.create_instance(*args)

def create_from_key(cls, oldvalue, key):
    """Raise  if the old value already exists"""
    if oldvalue is not None:
        raise AlreadyExistsException('%r already exists' % (oldvalue,))
    return cls.create_from_key(key)

def dump(obj, attributes=True, _refset=None):
    """Show full value of a data object"""
    if _refset is None:
        _refset = set()
    if obj is None:
        return None
    elif isinstance(obj, DataObject):
        if id(obj) in _refset:
            attributes = False
        else:
            _refset.add(id(obj))
        cls = type(obj)
        clsname = getattr(cls, '__module__', '<unknown>') + '.' + getattr(cls, '__name__', '<unknown>')
        baseresult = {'_type': clsname, '_key': obj.getkey()}
        if not attributes:
            return baseresult
        else:
            baseresult.update(((k, dump(v, attributes, _refset)) for k, v in vars(obj).items() if k[:1] != '_'))
            _refset.remove(id(obj))
        return baseresult
    elif isinstance(obj, ReferenceObject):
        if obj._ref is not None:
            return dump(obj._ref, attributes, _refset)
        else:
            return {'_ref': obj.getkey()}
    elif isinstance(obj, WeakReferenceObject):
        return {'_weakref': obj.getkey()}
    elif isinstance(obj, DataObjectSet):
        return dump(list(obj.dataset()))
    elif isinstance(obj, dict):
        return dict(((k, dump(v, attributes, _refset)) for k, v in obj.items()))
    elif isinstance(obj, list) or isinstance(obj, tuple) or isinstance(obj, set):
        return [dump(v, attributes, _refset) for v in obj]
    else:
        return obj

def list_proxy(root_package='vlcp'):
    """Walk through all the sub modules, find subclasses of vlcp.server.module._ProxyModule,
    list their default values"""
    proxy_dict = OrderedDict()
    pkg = __import__(root_package, fromlist=['_'])
    for imp, module, _ in walk_packages(pkg.__path__, root_package + '.'):
        m = __import__(module, fromlist=['_'])
        for _, v in vars(m).items():
            if v is not None and isinstance(v, type) and issubclass(v, _ProxyModule) and (v is not _ProxyModule) and (v.__module__ == module) and hasattr(v, '_default'):
                name = v.__name__.lower()
                if name not in proxy_dict:
                    proxy_dict[name] = {'defaultmodule': v._default.__name__.lower(), 'class': repr(v._default.__module__ + '.' + v._default.__name__)}
    return proxy_dict

def list_modules(root_package='vlcp'):
    """Walk through all the sub modules, find subclasses of vlcp.server.module.Module,
    list their apis through apidefs"""
    pkg = __import__(root_package, fromlist=['_'])
    module_dict = OrderedDict()
    _server = Server()
    for imp, module, _ in walk_packages(pkg.__path__, root_package + '.'):
        m = __import__(module, fromlist=['_'])
        for name, v in vars(m).items():
            if v is not None and isinstance(v, type) and issubclass(v, Module) and (v is not Module) and (not isinstance(v, _ProxyModule)) and hasattr(v, '__dict__') and ('configkey' in v.__dict__) and (v.__module__ == module):
                module_name = v.__name__.lower()
                if module_name not in module_dict:
                    _inst = v(_server)
                    module_info = OrderedDict((('class', v.__module__ + '.' + v.__name__), ('dependencies', [d.__name__.lower() for d in v.depends]), ('classdescription', getdoc(v)), ('apis', [])))
                    if hasattr(_inst, 'apiHandler'):
                        apidefs = _inst.apiHandler.apidefs
                        module_info['apis'] = [(d[0], d[3]) for d in apidefs if len(d) > 3 and (not d[0].startswith('public/'))]
                    module_dict[module_name] = module_info
    return module_dict

def ensure_keys(walk, *keys):
    """Use walk to try to retrieve all keys"""
    all_retrieved = True
    for k in keys:
        try:
            walk(k)
        except WalkKeyNotRetrieved:
            all_retrieved = False
    return all_retrieved

def http(container=None):
    """wrap a WSGI-style class method to a HTTPRequest event handler"""
    def decorator(func):
        @functools.wraps(func)
        def handler(self, event):
            return _handler(self if container is None else container, event, lambda env: func(self, env))
        return handler
    return decorator

def statichttp(container=None):
    """wrap a WSGI-style function to a HTTPRequest event handler"""
    def decorator(func):
        @functools.wraps(func)
        def handler(event):
            return _handler(container, event, func)
        if hasattr(func, '__self__'):
            handler.__self__ = func.__self__
        return handler
    return decorator

def _close_generator(g):
    """PyPy 3 generator has a bug that calling `close` caused
    memory leak. Before it is fixed, use `throw` instead"""
    if isinstance(g, generatorwrapper):
        g.close()
    elif _get_frame(g) is not None:
        try:
            g.throw(GeneratorExit_)
        except (StopIteration, GeneratorExit_):
            return
        else:
            raise RuntimeError('coroutine ignored GeneratorExit')

def depend(*args):
    """Decorator to declare dependencies to other modules. Recommended usage is::

        import other_module

        @depend(other_module.ModuleClass)
        class MyModule(Module):
            ...

    :param \\*args: depended module classes."""
    def decfunc(cls):
        if not 'depends' in cls.__dict__:
            cls.depends = []
        cls.depends.extend(list(args))
        for a in args:
            if not hasattr(a, 'referencedBy'):
                a.referencedBy = []
            a.referencedBy.append(cls)
        return cls
    return decfunc

def configbase(key):
    """Decorator to set this class to configuration base class. A configuration base class
    uses `<parentbase>.key.` for its configuration base, and uses `<parentbase>.key.default` for configuration mapping."""
    def decorator(cls):
        parent = cls.getConfigurableParent()
        if parent is None:
            parentbase = None
        else:
            parentbase = getattr(parent, 'configbase', None)
        if parentbase is None:
            base = key
        else:
            base = parentbase + '.' + key
        cls.configbase = base
        cls.configkey = base + '.default'
        return cls
    return decorator

def config(key):
    """Decorator to map this class directly to a configuration node. It uses `<parentbase>.key` for configuration
    base and configuration mapping."""
    def decorator(cls):
        parent = cls.getConfigurableParent()
        if parent is None:
            parentbase = None
        else:
            parentbase = getattr(parent, 'configbase', None)
        if parentbase is None:
            cls.configkey = key
        else:
            cls.configkey = parentbase + '.' + key
        return cls
    return decorator

def _get_server_certificate(addr, ssl_version=PROTOCOL_SSLv23, ca_certs=None):
    """Retrieve a server certificate

    Retrieve the certificate from the server at the specified address,
    and return it as a PEM-encoded string.
    If 'ca_certs' is specified, validate the server cert against it.
    If 'ssl_version' is specified, use it in the connection attempt."""
    if ssl_version not in (PROTOCOL_DTLS, PROTOCOL_DTLSv1, PROTOCOL_DTLSv1_2):
        return _orig_get_server_certificate(addr, ssl_version, ca_certs)
    if ca_certs is not None:
        cert_reqs = ssl.CERT_REQUIRED
    else:
        cert_reqs = ssl.CERT_NONE
    af = getaddrinfo(addr[0], addr[1])[0][0]
    s = ssl.wrap_socket(socket(af, SOCK_DGRAM), ssl_version=ssl_version, cert_reqs=cert_reqs, ca_certs=ca_certs)
    s.connect(addr)
    dercert = s.getpeercert(True)
    s.close()
    return ssl.DER_cert_to_PEM_cert(dercert)

def _prep_bins():
    """Support for running straight out of a cloned source directory instead
    of an installed distribution"""
    from os import path
    from sys import platform, maxsize
    from shutil import copy
    bit_suffix = '-x86_64' if maxsize > 2 ** 32 else '-x86'
    package_root = path.abspath(path.dirname(__file__))
    prebuilt_path = path.join(package_root, 'prebuilt', platform + bit_suffix)
    config = {'MANIFEST_DIR': prebuilt_path}
    try:
        execfile(path.join(prebuilt_path, 'manifest.pycfg'), config)
    except IOError:
        return
    files = map(lambda x: path.join(prebuilt_path, x), config['FILES'])
    for prebuilt_file in files:
        try:
            copy(path.join(prebuilt_path, prebuilt_file), package_root)
        except IOError:
            pass

