def _checkstatus(status, line):
    """Returns state/status after reading the next line.
    The status codes are::
        LE07_clip_L1TP_039027_20150529_20160902_01_T1_B1.TIF - BEGIN parsing; 1 - ENTER METADATA GROUP, 2 - READ METADATA LINE,
        3 - END METDADATA GROUP, 4 - END PARSING
    Permitted Transitions::
        LE07_clip_L1TP_039027_20150529_20160902_01_T1_B1.TIF --> 1, LE07_clip_L1TP_039027_20150529_20160902_01_T1_B1.TIF --> 4
        1 --> 1, 1 --> 2, 1 --> 3
        2 --> 2, 2 --> 3
        3 --> 1, 1 --> 3, 3 --> 4"""
    newstatus = 0
    if status == 0:
        if _islinetype(line, GRPSTART):
            newstatus = 1
        elif _isfinal(line):
            newstatus = 4
    elif status == 1:
        if _islinetype(line, GRPSTART):
            newstatus = 1
        elif _islinetype(line, GRPEND):
            newstatus = 3
        elif _isassignment(line):
            newstatus = 2
    elif status == 2:
        if _islinetype(line, GRPEND):
            newstatus = 3
        elif _isassignment(line):
            newstatus = 2
    elif status == 3:
        if _islinetype(line, GRPSTART):
            newstatus = 1
        elif _islinetype(line, GRPEND):
            newstatus = 3
        elif _isfinal(line):
            newstatus = 4
    if newstatus != 0:
        return newstatus
    elif status != 4:
        raise MTLParseError('Cannot parse the following line after status ' + "'%s':\n%s" % (STATUSCODE[status], line))

def _transstat(status, grouppath, dictpath, line):
    """Executes processing steps when reading a line"""
    if status == 0:
        raise MTLParseError("Status should not be '%s' after reading line:\n%s" % (STATUSCODE[status], line))
    elif status == 1:
        currentdict = dictpath[-1]
        currentgroup = _getgroupname(line)
        grouppath.append(currentgroup)
        currentdict[currentgroup] = {}
        dictpath.append(currentdict[currentgroup])
    elif status == 2:
        currentdict = dictpath[-1]
        newkey, newval = _getmetadataitem(line)
        if newkey == 'SCENE_CENTER_TIME' and newval.startswith('"') and newval.endswith('"'):
            newval = newval[1:-1]
        currentdict[newkey] = _postprocess(newval)
    elif status == 3:
        oldgroup = _getendgroupname(line)
        if oldgroup != grouppath[-1]:
            raise MTLParseError("Reached line '%s' while reading group '%s'." % (line.strip(), grouppath[-1]))
        del grouppath[-1]
        del dictpath[-1]
        try:
            currentgroup = grouppath[-1]
        except IndexError:
            currentgroup = None
    elif status == 4:
        if grouppath:
            raise MTLParseError("Reached end before end of group '%s'" % grouppath[-1])
    return (grouppath, dictpath)

def _postprocess(valuestr):
    """Takes value as str, returns str, int, float, date, datetime, or time"""
    intpattern = re.compile('^\\-?\\d+$')
    floatpattern = re.compile('^\\-?\\d+\\.\\d+(E[+-]?\\d\\d+)?$')
    datedtpattern = '%Y-%m-%d'
    datedttimepattern = '%Y-%m-%dT%H:%M:%SZ'
    timedtpattern = '%H:%M:%S.%f'
    timepattern = re.compile('^\\d{2}:\\d{2}:\\d{2}(\\.\\d{6})?')
    if valuestr.startswith('"') and valuestr.endswith('"'):
        return valuestr[1:-1]
    elif re.match(intpattern, valuestr):
        return int(valuestr)
    elif re.match(floatpattern, valuestr):
        return float(valuestr)
    try:
        return datetime.datetime.strptime(valuestr, datedtpattern).date()
    except ValueError:
        pass
    try:
        return datetime.datetime.strptime(valuestr, datedttimepattern)
    except ValueError:
        pass
    mat = re.match(timepattern, valuestr)
    if mat:
        test = mat.group(0)
        try:
            return datetime.datetime.strptime(test, timedtpattern).time()
        except ValueError:
            pass
    logging.info("The value %s couldn't be parsed as " % valuestr + 'int, float, date, time, datetime. Returning it as string.')
    return valuestr

def tox_get_python_executable(envconfig):
    """Return a python executable for the given python base name.

    The first plugin/hook which returns an executable path will determine it.

    ``envconfig`` is the testenv configuration which contains
    per-testenv configuration, notably the ``.envname`` and ``.basepython``
    setting."""
    try:
        pyenv = getattr(py.path.local.sysfind('pyenv'), 'strpath', 'pyenv') or 'pyenv'
        cmd = [pyenv, 'which', envconfig.basepython]
        pipe = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, universal_newlines=True)
        out, err = pipe.communicate()
    except OSError:
        err = "'pyenv': command not found"
        LOG.warning("pyenv doesn't seem to be installed, you probably don't want this plugin installed either.")
    else:
        if pipe.poll() == 0:
            return out.strip()
        elif not envconfig.tox_pyenv_fallback:
            raise PyenvWhichFailed(err)
    LOG.debug('`%s` failed thru tox-pyenv plugin, falling back. STDERR: "%s" | To disable this behavior, set tox_pyenv_fallback=False in your tox.ini or use  --tox-pyenv-no-fallback on the command line.', ' '.join([str(x) for x in cmd]), err)

def get_parser_class():
    """Returns the parser according to the system platform"""
    global distro
    if distro == 'Linux':
        Parser = parser.LinuxParser
        if not os.path.exists(Parser.get_command()[0]):
            Parser = parser.UnixIPParser
    elif distro in ['Darwin', 'MacOSX']:
        Parser = parser.MacOSXParser
    elif distro == 'Windows':
        Parser = parser.WindowsParser
    else:
        Parser = parser.NullParser
        Log.error("Unknown distro type '%s'." % distro)
    Log.debug("Distro detected as '%s'" % distro)
    Log.debug("Using '%s'" % Parser)
    return Parser

