def as_string(value):
    """Convert a value to a Unicode object for matching with a query.
    None becomes the empty string. Bytestrings are silently decoded."""
    if six.PY2:
        buffer_types = (buffer, memoryview)
    else:
        buffer_types = memoryview
    if value is None:
        return u''
    elif isinstance(value, buffer_types):
        return bytes(value).decode('utf8', 'ignore')
    elif isinstance(value, bytes):
        return value.decode('utf8', 'ignore')
    else:
        return six.text_type(value)

def displayable_path(path, separator=u'; '):
    """Attempts to decode a bytestring path to a unicode object for the
    purpose of displaying it to the user. If the `path` argument is a
    list or a tuple, the elements are joined with `separator`."""
    if isinstance(path, (list, tuple)):
        return separator.join((displayable_path(p) for p in path))
    elif isinstance(path, six.text_type):
        return path
    elif not isinstance(path, bytes):
        return six.text_type(path)
    try:
        return path.decode(_fsencoding(), 'ignore')
    except (UnicodeError, LookupError):
        return path.decode('utf8', 'ignore')

def syspath(path, prefix=True):
    """Convert a path for use by the operating system. In particular,
    paths on Windows must receive a magic prefix and must be converted
    to Unicode before they are sent to the OS. To disable the magic
    prefix on Windows, set `prefix` to False---but only do this if you
    *really* know what you're doing."""
    if os.path.__name__ != 'ntpath':
        return path
    if not isinstance(path, six.text_type):
        try:
            path = path.decode('utf8')
        except UnicodeError:
            encoding = sys.getfilesystemencoding() or sys.getdefaultencoding()
            path = path.decode(encoding, 'replace')
    if prefix and (not path.startswith(WINDOWS_MAGIC_PREFIX)):
        if path.startswith(u'\\\\'):
            path = u'UNC' + path[1:]
        path = WINDOWS_MAGIC_PREFIX + path
    return path

def admin_log(instances, msg: str, who: User=None, **kw):
    """Logs an entry to admin logs of model(s).
    :param instances: Model instance or list of instances
    :param msg: Message to log
    :param who: Who did the change
    :param kw: Optional key-value attributes to append to message
    :return: None"""
    from django.contrib.admin.models import LogEntry, CHANGE
    from django.contrib.admin.options import get_content_type_for_model
    from django.utils.encoding import force_text
    if not who:
        username = settings.DJANGO_SYSTEM_USER if hasattr(settings, 'DJANGO_SYSTEM_USER') else 'system'
        who, created = User.objects.get_or_create(username=username)
    att_str = ''
    for k, v in kw.items():
        if hasattr(v, 'pk'):
            v = v.pk
        att_str += '{}={}'.format(k, v) if not att_str else ', {}={}'.format(k, v)
    if att_str:
        att_str = ' [{}]'.format(att_str)
    msg = str(msg) + att_str
    if not isinstance(instances, list) and (not isinstance(instances, tuple)):
        instances = [instances]
    for instance in instances:
        if instance:
            LogEntry.objects.log_action(user_id=who.pk, content_type_id=get_content_type_for_model(instance).pk, object_id=instance.pk, object_repr=force_text(instance), action_flag=CHANGE, change_message=msg)

def write(version):
    """Write the given version to the VERSION_FILE"""
    if not is_valid(version):
        raise ValueError('Invalid version: '.format(version))
    storage = get_version_storage()
    storage.write(version)

def get_version_storage():
    """Get version storage for the given version file.

    The storage engine used depends on the extension of the *version_file*."""
    version_file = conf.get_path('version_file', 'VERSION')
    if version_file.endswith('.py'):
        return PyVersionStorage(version_file)
    elif version_file.endswith('package.json'):
        return NodeVersionStorage(version_file)
    else:
        return RawVersionStorage(version_file)

def padd(text, padding='top', size=1):
    """Adds extra new lines to the top, bottom or both of a String

    @text: #str text to pad
    @padding: #str 'top', 'bottom' or 'all'
    @size: #int number of new lines

    -> #str padded @text
    ..
        from vital.debug import *

        padd("Hello world")
        # -> '\\nHello world'

        padd("Hello world", size=5, padding="all")
        # -> '\\n\\n\\n\\n\\nHello world\\n\\n\\n\\n\\n'
    .."""
    if padding:
        padding = padding.lower()
        pad_all = padding == 'all'
        padding_top = ''
        if padding and (padding == 'top' or pad_all):
            padding_top = ''.join(('\n' for x in range(size)))
        padding_bottom = ''
        if padding and (padding == 'bottom' or pad_all):
            padding_bottom = ''.join(('\n' for x in range(size)))
        return '{}{}{}'.format(padding_top, text, padding_bottom)
    return text

def colorize(text, color='BLUE', close=True):
    """Colorizes text for terminal outputs

    @text: #str to colorize
    @color: #str color from :mod:colors
    @close: #bool whether or not to reset the color

    -> #str colorized @text
    ..
        from vital.debug import colorize

        colorize("Hello world", "blue")
        # -> '\x1b[0;34mHello world\x1b[1;m'

        colorize("Hello world", "blue", close=False)
        # -> '\x1b[0;34mHello world'
    .."""
    if color:
        color = getattr(colors, color.upper())
        return color + uncolorize(str(text)) + (colors.RESET if close else '')
    return text

def bold(text, close=True):
    """Bolds text for terminal outputs

    @text: #str to bold
    @close: #bool whether or not to reset the bold flag

    -> #str bolded @text
    ..
        from vital.debug import bold

        bold("Hello world")
        # -> '\x1b[1mHello world\x1b[1;m'

        bold("Hello world", close=False)
        # -> '\x1b[1mHello world'
    .."""
    return getattr(colors, 'BOLD') + str(text) + (colors.RESET if close else '')

def get_class_that_defined_method(meth):
    """Gets the class object which defined a given method

    @meth: a class method

    -> owner class object"""
    if inspect.ismethod(meth):
        for cls in inspect.getmro(meth.__self__.__class__):
            if cls.__dict__.get(meth.__name__) is meth:
                return cls
        meth = meth.__func__
    if inspect.isfunction(meth):
        cls = getattr(inspect.getmodule(meth), meth.__qualname__.split('.<locals>', 1)[0].rsplit('.', 1)[0])
        if isinstance(cls, type):
            return cls
    return None

def async_lru(size=100):
    """An LRU cache for asyncio coroutines in Python 3.5
    ..
        @async_lru(1024)
        async def slow_coroutine(*args, **kwargs):
            return await some_other_slow_coroutine()
    .."""
    cache = collections.OrderedDict()
    def decorator(fn):
        @wraps(fn)
        @asyncio.coroutine
        def memoizer(*args, **kwargs):
            key = str((args, kwargs))
            try:
                result = cache.pop(key)
                cache[key] = result
            except KeyError:
                if len(cache) >= size:
                    cache.popitem(last=False)
                result = cache[key] = (yield from fn(*args, **kwargs))
            return result
        return memoizer
    return decorator

def choices_label(choices: tuple, value) -> str:
    """Iterates (value,label) list and returns label matching the choice
    :param choices: [(choice1, label1), (choice2, label2), ...]
    :param value: Value to find
    :return: label or None"""
    for key, label in choices:
