def parse_bool(v, default=None, exceptions: bool=True) -> bool:
    """Parses boolean value
    :param v: Input string
    :param default: Default value if exceptions=False
    :param exceptions: Raise exception on error or not
    :return: bool"""
    if isinstance(v, bool):
        return v
    s = str(v).lower()
    if s in TRUE_VALUES:
        return True
    elif s in FALSE_VALUES:
        return False
    else:
        if exceptions:
            raise ValidationError('Failed to parse boolean from "{}"'.format(v))
        return default

def parse_datetime(v, default=None, tz=None, exceptions: bool=True) -> datetime:
    """Parses datetime
    :param v: Input string
    :param default: Default value if exceptions=False
    :param tz: Default pytz timezone or None if utc
    :param exceptions: Raise exception on error or not
    :return: datetime"""
    try:
        t = dateutil_parse(v, default=datetime(2000, 1, 1))
        if tz is None:
            tz = pytz.utc
        return t if t.tzinfo else tz.localize(t)
    except Exception:
        if exceptions:
            raise ValidationError('Failed to parse datetime from "{}"'.format(v))
        return default

def mark_experimental(fn):
    """Mark function as experimental.

    Args:
        fn (FunctionType):
            The command function to decorate."""
    @wraps(fn)
    def wrapper(*args, **kw):
        from peltak.core import shell
        if shell.is_tty:
            warnings.warn('This command is has experimental status. The interface is not yet stable and might change without notice within with a patch version update. Use at your own risk')
        return fn(*args, **kw)
    return wrapper

def mark_deprecated(replaced_by):
    """Mark command as deprecated.

    Args:
        replaced_by (str):
            The command that deprecated this command and should be used instead."""
    def decorator(fn):
        @wraps(fn)
        def wrapper(*args, **kw):
            from peltak.core import shell
            if shell.is_tty:
                warnings.warn('This command is has been deprecated. Please use {new} instead.'.format(new=replaced_by))
            return fn(*args, **kw)
        return wrapper
    return decorator

def _sc_decode(soundcheck):
    """Convert a Sound Check bytestring value to a (gain, peak) tuple as
    used by ReplayGain."""
    if isinstance(soundcheck, six.text_type):
        soundcheck = soundcheck.encode('utf-8')
    try:
        soundcheck = codecs.decode(soundcheck.replace(b' ', b''), 'hex')
        soundcheck = struct.unpack('!iiiiiiiiii', soundcheck)
    except (struct.error, TypeError, binascii.Error):
        return (0.0, 0.0)
    maxgain = max(soundcheck[:2])
    if maxgain > 0:
        gain = math.log10(maxgain / 1000.0) * -10
    else:
        gain = 0.0
    peak = max(soundcheck[6:8]) / 32768.0
    return (round(gain, 2), round(peak, 6))

def image_mime_type(data):
    """Return the MIME type of the image data (a bytestring).
    """
    kind = _imghdr_what_wrapper(data)
    if kind in ['gif', 'jpeg', 'png', 'tiff', 'bmp']:
        return 'image/{0}'.format(kind)
    elif kind == 'pgm':
        return 'image/x-portable-graymap'
    elif kind == 'pbm':
        return 'image/x-portable-bitmap'
    elif kind == 'ppm':
        return 'image/x-portable-pixmap'
    elif kind == 'xbm':
        return 'image/x-xbitmap'
    else:
        return 'image/x-{0}'.format(kind)

def update_cached_fields(*args):
    """Calls update_cached_fields() for each object passed in as argument.
    Supports also iterable objects by checking __iter__ attribute.
    :param args: List of objects
    :return: None"""
    for a in args:
        if a is not None:
            if hasattr(a, '__iter__'):
                for e in a:
                    e.update_cached_fields()
            else:
                a.update_cached_fields()

