def graph_from_adjacency_matrix(matrix, node_prefix='', directed=False):
    """Creates a basic graph out of an adjacency matrix.

    The matrix has to be a list of rows of values
    representing an adjacency matrix.
    The values can be anything: bool, int, float, as long
    as they can evaluate to True or False."""
    node_orig = 1
    if directed:
        graph = Dot(graph_type='digraph')
    else:
        graph = Dot(graph_type='graph')
    for row in matrix:
        if not directed:
            skip = matrix.index(row)
            r = row[skip:]
        else:
            skip = 0
            r = row
        node_dest = skip + 1
        for e in r:
            if e:
                graph.add_edge(Edge(node_prefix + node_orig, node_prefix + node_dest))
            node_dest += 1
        node_orig += 1
    return graph

def graph_from_incidence_matrix(matrix, node_prefix='', directed=False):
    """Creates a basic graph out of an incidence matrix.

    The matrix has to be a list of rows of values
    representing an incidence matrix.
    The values can be anything: bool, int, float, as long
    as they can evaluate to True or False."""
    if directed:
        graph = Dot(graph_type='digraph')
    else:
        graph = Dot(graph_type='graph')
    for row in matrix:
        nodes = []
        c = 1
        for node in row:
            if node:
                nodes.append(c * node)
            c += 1
        nodes.sort()
        if len(nodes) == 2:
            graph.add_edge(Edge(node_prefix + abs(nodes[0]), node_prefix + nodes[1]))
    if not directed:
        graph.set_simplify(True)
    return graph

def __find_executables(path):
    """Used by find_graphviz

    path - single directory as a string

    If any of the executables are found, it will return a dictionary
    containing the program names as keys and their paths as values.

    Otherwise returns None"""
    success = False
    progs = {'dot': '', 'twopi': '', 'neato': '', 'circo': '', 'fdp': '', 'sfdp': ''}
    was_quoted = False
    path = path.strip()
    if path.startswith('"') and path.endswith('"'):
        path = path[1:-1]
        was_quoted = True
    if not os.path.isdir(path):
        return None
    for prg in progs:
        if progs[prg]:
            continue
        prg_path = os.path.join(path, prg)
        prg_exe_path = prg_path + '.exe'
        if os.path.exists(prg_path):
            if was_quoted:
                prg_path = '"{}"'.format(prg_path)
            progs[prg] = prg_path
            success = True
        elif os.path.exists(prg_exe_path):
            if was_quoted:
                prg_exe_path = '"{}"'.format(prg_exe_path)
            progs[prg] = prg_exe_path
            success = True
    if success:
        return progs
    return None

def _extract_version(version_string, pattern):
