    Return the version as a string, with leading/trailing whitespace
    stripped."""
    if version_string:
        match = pattern.match(version_string.strip())
        if match:
            return match.group(1)
    return ''

def _bits_to_float(bits, lower=-90.0, middle=0.0, upper=90.0):
    """Convert GeoHash bits to a float."""
    for i in bits:
        if i:
            lower = middle
        else:
            upper = middle
        middle = (upper + lower) / 2
    return middle

def _float_to_bits(value, lower=-90.0, middle=0.0, upper=90.0, length=15):
    """Convert a float to a list of GeoHash bits."""
    ret = []
    for i in range(length):
        if value >= middle:
            lower = middle
            ret.append(1)
        else:
            upper = middle
            ret.append(0)
        middle = (upper + lower) / 2
    return ret

def _bits_to_geohash(value):
    """Convert a list of GeoHash bits to a GeoHash."""
    ret = []
    for i in (value[i:i + 5] for i in xrange(0, len(value), 5)):
        total = sum([bit * 2 ** count for count, bit in enumerate(i[::-1])])
        ret.append(BASE32MAPR[total])
    return ''.join(ret)

def adjacent(geohash, direction):
    """Return the adjacent geohash for a given direction."""
    assert direction in 'nsew', 'Invalid direction: %s' % direction
    assert geohash, 'Invalid geohash: %s' % geohash
    neighbor = {'n': ['p0r21436x8zb9dcf5h7kjnmqesgutwvy', 'bc01fg45238967deuvhjyznpkmstqrwx'], 's': ['14365h7k9dcfesgujnmqp0r2twvyx8zb', '238967debc01fg45kmstqrwxuvhjyznp'], 'e': ['bc01fg45238967deuvhjyznpkmstqrwx', 'p0r21436x8zb9dcf5h7kjnmqesgutwvy'], 'w': ['238967debc01fg45kmstqrwxuvhjyznp', '14365h7k9dcfesgujnmqp0r2twvyx8zb']}
    border = {'n': ['prxz', 'bcfguvyz'], 's': ['028b', '0145hjnp'], 'e': ['bcfguvyz', 'prxz'], 'w': ['0145hjnp', '028b']}
    last = geohash[-1]
    parent = geohash[0:-1]
    t = len(geohash) % 2
    if last in border[direction][t] and parent:
        parent = adjacent(parent, direction)
    return parent + BASESEQUENCE[neighbor[direction][t].index(last)]

def neighbors(geohash):
    """Return all neighboring geohashes."""
    return {'n': adjacent(geohash, 'n'), 'ne': adjacent(adjacent(geohash, 'n'), 'e'), 'e': adjacent(geohash, 'e'), 'se': adjacent(adjacent(geohash, 's'), 'e'), 's': adjacent(geohash, 's'), 'sw': adjacent(adjacent(geohash, 's'), 'w'), 'w': adjacent(geohash, 'w'), 'nw': adjacent(adjacent(geohash, 'n'), 'w'), 'c': geohash}

def smix(B, Bi, r, N, V, X):
    """SMix; a specific case of ROMix. See scrypt.pdf in the links above."""
    X[:32 * r] = B[Bi:Bi + 32 * r]
    for i in xrange(0, N):
        aod = i * 32 * r
        V[aod:aod + 32 * r] = X[:32 * r]
        blockmix_salsa8(X, 32 * r, r)
    for i in xrange(0, N):
        j = X[(2 * r - 1) * 16] & N - 1
        for xi in xrange(0, 32 * r):
            X[xi] ^= V[j * 32 * r + xi]
        blockmix_salsa8(X, 32 * r, r)
    B[Bi:Bi + 32 * r] = X[:32 * r]

