def _strtobool(val):
    """Convert a string representation of truth to true (1) or false (0).

    True values are 'y', 'yes', 't', 'true', 'on', and '1'; false values
    are 'n', 'no', 'f', 'false', 'off', '0' and ''.  Raises ValueError if
    'val' is anything else."""
    val = val.lower()
    if val in ('y', 'yes', 't', 'true', 'on', '1'):
        return 1
    elif val in ('n', 'no', 'f', 'false', 'off', '0', ''):
        return 0
    else:
        raise ValueError('Invalid truth value: {0}'.format(val))

def _str_to_list(value, separator):
    """Convert a string to a list with sanitization."""
    value_list = [item.strip() for item in value.split(separator)]
    value_list_sanitized = builtins.list(filter(None, value_list))
    if len(value_list_sanitized) > 0:
        return value_list_sanitized
    else:
        raise ValueError('Invalid list variable.')

def write(name, value):
    """Write a raw env value.

    A ``None`` value clears the environment variable.

    Args:
        name: The environment variable name
        value: The value to write"""
    if value is not None:
        environ[name] = builtins.str(value)
    elif environ.get(name):
        del environ[name]

def read(name, default=None, allow_none=False, fallback=None):
    """Read the raw env value.

    Read the raw environment variable or use the default. If the value is not
    found and no default is set throw an exception.

    Args:
        name: The environment variable name
        default: The default value to use if no environment variable is found
        allow_none: If the return value can be `None` (i.e. optional)
        fallback: A list of fallback env variables to try and read if the primary environment
                  variable is unavailable."""
    raw_value = environ.get(name)
    if raw_value is None and fallback is not None:
        if not isinstance(fallback, builtins.list) and (not isinstance(fallback, builtins.tuple)):
            fallback = [fallback]
        for fall in fallback:
            raw_value = environ.get(fall)
            if raw_value is not None:
                break
    if raw_value or raw_value == '':
        return raw_value
    elif default is not None or allow_none:
        return default
    else:
        raise KeyError('Set the "{0}" environment variable'.format(name))

def str(name, default=None, allow_none=False, fallback=None):
    """Get a string based environment value or the default.

    Args:
        name: The environment variable name
        default: The default value to use if no environment variable is found
        allow_none: If the return value can be `None` (i.e. optional)"""
    value = read(name, default, allow_none, fallback=fallback)
    if value is None and allow_none:
        return None
    else:
        return builtins.str(value).strip()

def bool(name, default=None, allow_none=False, fallback=None):
    """Get a boolean based environment value or the default.

    Args:
        name: The environment variable name
        default: The default value to use if no environment variable is found
        allow_none: If the return value can be `None` (i.e. optional)"""
    value = read(name, default, allow_none, fallback=fallback)
    if isinstance(value, builtins.bool):
        return value
    elif isinstance(value, builtins.int):
        return True if value > 0 else False
    elif value is None and allow_none:
        return None
    else:
        value_str = builtins.str(value).lower().strip()
        return _strtobool(value_str)

def int(name, default=None, allow_none=False, fallback=None):
    """Get a string environment value or the default.

    Args:
        name: The environment variable name
        default: The default value to use if no environment variable is found
        allow_none: If the return value can be `None` (i.e. optional)"""
    value = read(name, default, allow_none, fallback=fallback)
    if isinstance(value, builtins.str):
        value = value.strip()
    if value is None and allow_none:
        return None
    else:
        return builtins.int(value)

def list(name, default=None, allow_none=False, fallback=None, separator=','):
    """Get a list of strings or the default.

    The individual list elements are whitespace-stripped.

    Args:
        name: The environment variable name
        default: The default value to use if no environment variable is found
        allow_none: If the return value can be `None` (i.e. optional)
        separator: The list item separator character or pattern"""
    value = read(name, default, allow_none, fallback=fallback)
    if isinstance(value, builtins.list):
        return value
    elif isinstance(value, builtins.str):
        return _str_to_list(value, separator)
    elif value is None and allow_none:
        return None
    else:
        return [builtins.str(value)]

def _add_referencer(registry):
    """Gets the Referencer from config and adds it to the registry."""
    referencer = registry.queryUtility(IReferencer)
    if referencer is not None:
        return referencer
    ref = registry.settings['urireferencer.referencer']
    url = registry.settings['urireferencer.registry_url']
    r = DottedNameResolver()
    registry.registerUtility(r.resolve(ref)(url), IReferencer)
    return registry.queryUtility(IReferencer)

def get_referencer(registry):
    """Get the referencer class

    :rtype: pyramid_urireferencer.referencer.AbstractReferencer"""
    regis = getattr(registry, 'registry', None)
    if regis is None:
        regis = registry
    return regis.queryUtility(IReferencer)

def clear_layout(layout: QLayout) -> None:
    """Clear the layout off all its components"""
    if layout is not None:
        while layout.count():
            item = layout.takeAt(0)
            widget = item.widget()
            if widget is not None:
                widget.deleteLater()
            else:
                clear_layout(item.layout())

def _load_hangul_syllable_types():
    """Helper function for parsing the contents of "HangulSyllableType.txt" from the Unicode Character Database (UCD) and
    generating a lookup table for determining whether or not a given Hangul syllable is of type "L", "V", "T", "LV" or
    "LVT".  For more info on the UCD, see the following website: https://www.unicode.org/ucd/"""
    filename = 'HangulSyllableType.txt'
    current_dir = os.path.abspath(os.path.dirname(__file__))
    with codecs.open(os.path.join(current_dir, filename), mode='r', encoding='utf-8') as fp:
        for line in fp:
            if not line.strip() or line.startswith('#'):
                continue
            data = line.strip().split(';')
            syllable_type, _ = map(six.text_type.strip, data[1].split('#'))
            if '..' in data[0]:
                start, end = map(lambda x: int(x, 16), data[0].strip().split('..'))
                for idx in range(start, end + 1):
                    _hangul_syllable_types[idx] = syllable_type
            else:
                _hangul_syllable_types[int(data[0].strip(), 16)] = syllable_type

def _get_hangul_syllable_name(hangul_syllable):
    """Function for taking a Unicode scalar value representing a Hangul syllable and converting it to its syllable name as
    defined by the Unicode naming rule NR1.  See the Unicode Standard, ch. 04, section 4.8, Names, for more information.

    :param hangul_syllable: Unicode scalar value representing the Hangul syllable to convert
    :return: String representing its syllable name as transformed according to naming rule NR1."""
    if not _is_hangul_syllable(hangul_syllable):
        raise ValueError('Value passed in does not represent a Hangul syllable!')
    jamo = decompose_hangul_syllable(hangul_syllable, fully_decompose=True)
    result = ''
    for j in jamo:
        if j is not None:
            result += _get_jamo_short_name(j)
    return result

def generate_client_callers(spec, timeout, error_callback, local, app):
    """Return a dict mapping method names to anonymous functions that
    will call the server's endpoint of the corresponding name as
    described in the api defined by the swagger dict and bravado spec"""
    callers_dict = {}
    def mycallback(endpoint):
        if not endpoint.handler_client:
            return
        callers_dict[endpoint.handler_client] = _generate_client_caller(spec, endpoint, timeout, error_callback, local, app)
    spec.call_on_each_endpoint(mycallback)
    return callers_dict

def apply_T1(word):
    """There is a syllable boundary in front of every CV-sequence."""
    WORD = [w for w in re.split('([ieAyOauo]+)', word) if w]
    count = 0
    for i, v in enumerate(WORD):
        if i == 0 and is_consonant(v[0]):
            continue
        elif is_consonant(v[0]) and i + 1 != len(WORD):
            if is_cluster(v):
                if count % 2 == 0:
                    WORD[i] = v[0] + '.' + v[1:]
                else:
                    WORD[i] = '.' + v
            else:
                WORD[i] = v[:-1] + '.' + v[-1]
            count += 1
    WORD = ''.join(WORD)
    RULE = ' T1' if word != WORD else ''
    return (WORD, RULE)

def stream_to_packet(data):
    """Chop a stream of data into MODBUS packets.

    :param data: stream of data
    :returns: a tuple of the data that is a packet with the remaining
        data, or ``None``"""
    if len(data) < 6:
        return None
    pktlen = struct.unpack('>H', data[4:6])[0] + 6
    if len(data) < pktlen:
        return None
    return (data[:pktlen], data[pktlen:])

def stress(syllabified_simplex_word):
    """Assign primary and secondary stress to 'syllabified_simplex_word'."""
    syllables = syllabified_simplex_word.split('.')
    stressed = "'" + syllables[0]
    try:
        n = 0
        medial = syllables[1:-1]
        for i, syll in enumerate(medial):
            if (i + n) % 2 == 0:
                stressed += '.' + syll
            else:
                try:
                    if is_light(syll) and is_heavy(medial[i + 1]):
                        stressed += '.' + syll
                        n += 1
                        continue
                except IndexError:
                    pass
                stressed += '.`' + syll
    except IndexError:
        pass
    if len(syllables) > 1:
        stressed += '.' + syllables[-1]
    return stressed

def syllabify(word, compound=None):
    """Syllabify the given word, whether simplex or complex."""
    if compound is None:
        compound = bool(re.search('(-| |=)', word))
    syllabify = _syllabify_compound if compound else _syllabify
    syll, rules = syllabify(word)
    yield (syll, rules)
    n = 7
    if 'T4' in rules:
        yield syllabify(word, T4=False)
        n -= 1
    if 'e' in rules:
        yield syllabify(word, T1E=False)
        n -= 1
    if 'e' in rules and 'T4' in rules:
        yield syllabify(word, T4=False, T1E=False)
        n -= 1
    for i in range(n):
        yield ('', '')

def apply_T4(word):
    """An agglutination diphthong that ends in /u, y/ usually contains a
    syllable boundary when -C# or -CCV follow, e.g., [lau.ka.us],
    [va.ka.ut.taa]."""
    WORD = word.split('.')
    for i, v in enumerate(WORD):
        if is_consonant(v[-1]) and i % 2 != 0:
            if i + 1 == len(WORD) or is_consonant(WORD[i + 1][0]):
                vv = u_or_y_final_diphthongs(v)
                if vv and (not is_long(vv.group(1))):
                    I = vv.start(1) + 1
                    WORD[i] = v[:I] + '.' + v[I:]
    WORD = '.'.join(WORD)
    RULE = ' T4' if word != WORD else ''
    return (WORD, RULE)

def open_(filename, mode=None, compresslevel=9):
    """Switch for both open() and gzip.open().

    Determines if the file is normal or gzipped by looking at the file
    extension.

    The filename argument is required; mode defaults to 'rb' for gzip and 'r'
    for normal and compresslevel defaults to 9 for gzip.

    >>> import gzip
    >>> from contextlib import closing
    >>> with open_(filename) as f:
    ...     f.read()"""
    if filename[-3:] == '.gz':
        if mode is None:
            mode = 'rt'
        return closing(gzip.open(filename, mode, compresslevel))
    else:
        if mode is None:
            mode = 'r'
        return open(filename, mode)

def sort2groups(array, gpat=['_R1', '_R2']):
    """Sort an array of strings to groups by patterns"""
    groups = [REGroup(gp) for gp in gpat]
    unmatched = []
    for item in array:
        matched = False
        for m in groups:
            if m.match(item):
                matched = True
                break
        if not matched:
            unmatched.append(item)
    return ([sorted(m.list) for m in groups], sorted(unmatched))

def sort_and_distribute(array, splits=2):
    """Sort an array of strings to groups by alphabetically continuous
    distribution"""
    if not isinstance(array, (list, tuple)):
        raise TypeError('array must be a list')
    if not isinstance(splits, int):
        raise TypeError('splits must be an integer')
    remaining = sorted(array)
    if sys.version_info < (3, 0):
        myrange = xrange(splits)
    else:
        myrange = range(splits)
    groups = [[] for i in myrange]
    while len(remaining) > 0:
        for i in myrange:
            if len(remaining) > 0:
                groups[i].append(remaining.pop(0))
    return groups

def mkpath(filepath, permissions=511):
    """This function executes a mkdir command for filepath and with permissions
    (octal number with leading 0 or string only)
    # eg. mkpath("path/to/file", "0o775")"""
    if isinstance(permissions, str):
        permissions = sum([int(x) * 8 ** i for i, x in enumerate(reversed(permissions))])
    if not os.path.exists(filepath):
        debug.log('Creating Directory %s (permissions: %s)' % (filepath, permissions))
        os.makedirs(filepath, permissions)
    else:
        debug.log('Warning: The directory ' + filepath + ' already exists')
    return filepath

def create_zip_dir(zipfile_path, *file_list):
    """This function creates a zipfile located in zipFilePath with the files in
    the file list
    # fileList can be both a comma separated list or an array"""
    try:
        if isinstance(file_list, (list, tuple)):
            if len(file_list) == 1:
                if isinstance(file_list[0], (list, tuple)):
                    file_list = file_list[0]
        if isinstance(file_list, str):
            file_list = [file_list]
        if file_list:
            with ZipFile(zipfile_path, 'w') as zf:
                for cur_file in file_list:
                    if '/' in cur_file:
                        os.chdir('/'.join(cur_file.split('/')[:-1]))
                    elif '/' in zipfile_path:
                        os.chdir('/'.join(zipfile_path.split('/')[:-1]))
                    zf.write(cur_file.split('/')[-1])
        else:
            debug.log('Error: No Files in list!', zipfile_path + ' was not created!')
    except Exception as e:
        debug.log('Error: Could not create zip dir! argtype: ' + str(type(file_list)), 'FileList: ' + str(file_list), 'Errormessage: ' + str(e))

def copy_dir(src, dst):
    """this function will simply copy the file from the source path to the dest
    path given as input"""
    try:
        debug.log('copy dir from ' + src, 'to ' + dst)
        shutil.copytree(src, dst)
    except Exception as e:
        debug.log('Error: happened while copying!\n%s\n' % e)

def isset(alias_name):
    """Return a boolean if the docker link is set or not and is a valid looking docker link value.

    Args:
        alias_name: The link alias name"""
    warnings.warn('Will be removed in v1.0', DeprecationWarning, stacklevel=2)
    raw_value = read(alias_name, allow_none=True)
    if raw_value:
        if re.compile('.+://.+:\\d+').match(raw_value):
            return True
        else:
            warnings.warn('"{0}_PORT={1}" does not look like a docker link.'.format(alias_name, raw_value), stacklevel=2)
            return False
    return False

def port(alias_name, default=None, allow_none=False):
    """Get the port from the docker link alias or return the default.

    Args:
        alias_name: The docker link alias
        default: The default value if the link isn't available
        allow_none: If the return value can be `None` (i.e. optional)

    Examples:
        Assuming a Docker link was created with ``docker --link postgres:db``
        and the resulting environment variable is ``DB_PORT=tcp://172.17.0.82:5432``.

        >>> envitro.docker.port('DB')
        5432"""
    warnings.warn('Will be removed in v1.0', DeprecationWarning, stacklevel=2)
    try:
        return int(_split_docker_link(alias_name)[2])
    except KeyError as err:
        if default or allow_none:
            return default
        else:
            raise err

def nonalpha_split(string):
    """Split 'string' along any punctuation or whitespace."""
    return re.findall('[%s]+|[^%s]+' % (A, A), string, flags=FLAGS)

def syllable_split(string):
    """Split 'string' into (stressed) syllables and punctuation/whitespace."""
    p = "\\'[%s]+|`[%s]+|[%s]+|[^%s\\'`\\.]+|[^\\.]{1}" % (A, A, A, A)
    return re.findall(p, string, flags=FLAGS)

def extract_words(string):
    """Extract all alphabetic syllabified forms from 'string'."""
    return re.findall('[%s]+[%s\\.]*[%s]+' % (A, A, A), string, flags=FLAGS)

def thread_with_callback(on_error, on_done, requete_with_callback):
    """Return a thread emiting `state_changed` between each sub-requests.

    :param on_error: callback str -> None
    :param on_done: callback object -> None
    :param requete_with_callback: Job to execute. monitor_callable -> None
    :return: Non started thread"""
    class C(THREAD):
        error = SIGNAL(str)
        done = SIGNAL(object)
        state_changed = SIGNAL(int, int)
        def __del__(self):
            self.wait()
        def run(self):
            try:
                r = requete_with_callback(self.state_changed.emit)
            except (ConnexionError, StructureError) as e:
                self.error.emit(str(e))
            else:
                self.done.emit(r)
    th = C()
    th.error.connect(on_error)
    th.done.connect(on_done)
    return th

def key(seq: Sequence, tooth: Callable[[Sequence], str]=lambda seq: str(random.SystemRandom().choice(seq)).strip(), nteeth: int=6, delimiter: str=' ') -> str:
    """Concatenate strings generated by the tooth function."""
    return delimiter.join((tooth(seq) for _ in range(nteeth)))

def main(argv: Sequence[str]=SYS_ARGV) -> int:
    """Execute CLI commands."""
    args = default_parser().parse_args(argv)
    try:
        seq = POPULATIONS[args.population]
    except KeyError:
        try:
            with open(args.population, 'r', encoding=args.encoding) as file_:
                seq = list(file_)
        except (OSError, UnicodeError) as ex:
            print(ex, file=sys.stderr)
            return 1
    main_key = key(seq=seq, nteeth=args.nteeth, delimiter=args.delimiter)
    print(main_key)
    if args.stats:
        print('*', len(main_key), 'characters')
        print('*', args.nteeth, 'samples from a population of', len(seq))
        print('* entropy {sign} {nbits} bits'.format(sign='~' if args.delimiter else '<', nbits=round(math.log(len(seq), 2) * args.nteeth, 2)))
    return 0

def saveDirectory(alias):
    """save a directory to a certain alias/nickname"""
    if not settings.platformCompatible():
        return False
    dataFile = open(settings.getDataFile(), 'wb')
    currentDirectory = os.path.abspath('.')
