def isset(name):
    """Only execute the function if the variable is set.

    Args:
        name: The name of the environment variable

    Returns:
        The function return value or `None` if the function was skipped."""
    def wrapped(func):
        @functools.wraps(func)
        def _decorator(*args, **kwargs):
            if core.isset(name):
                return func(*args, **kwargs)
        return _decorator
    return wrapped

def bool(name, execute_bool=True, default=None):
    """Only execute the function if the boolean variable is set.

    Args:
        name: The name of the environment variable
        execute_bool: The boolean value to execute the function on
        default: The default value if the environment variable is not set (respects `execute_bool`)

    Returns:
        The function return value or `None` if the function was skipped."""
    def wrapped(func):
        @functools.wraps(func)
        def _decorator(*args, **kwargs):
            if core.isset(name) and core.bool(name) == execute_bool:
                return func(*args, **kwargs)
            elif default is not None and default == execute_bool:
                return func(*args, **kwargs)
        return _decorator
    return wrapped

def convert_exception(from_exception, to_exception, *to_args, **to_kw):
    """Decorator: Catch exception ``from_exception`` and instead raise ``to_exception(*to_args, **to_kw)``.

    Useful when modules you're using in a method throw their own errors that you want to
    convert to your own exceptions that you handle higher in the stack.

    Example: ::

        class FooError(Exception):
            pass

        class BarError(Exception):
            def __init__(self, message):
                self.message = message

        @convert_exception(FooError, BarError, message='bar')
        def throw_foo():
            raise FooError('foo')

        try:
            throw_foo()
        except BarError as e:
            assert e.message == 'bar'"""
    def wrapper(fn):
        def fn_new(*args, **kw):
            try:
                return fn(*args, **kw)
            except from_exception:
                new_exception = to_exception(*to_args, **to_kw)
                traceback = sys.exc_info()[2]
                if PY3:
                    value = new_exception
                else:
                    value = None
                reraise(new_exception, value, traceback)
        fn_new.__doc__ = fn.__doc__
        return fn_new
    return wrapper

def iterate_date_values(d, start_date=None, stop_date=None, default=0):
    """Convert (date, value) sorted lists into contiguous value-per-day data sets. Great for sparklines.

    Example::

        [(datetime.date(2011, 1, 1), 1), (datetime.date(2011, 1, 4), 2)] -> [1, 0, 0, 2]"""
    dataiter = iter(d)
    cur_day, cur_val = next(dataiter)
    start_date = start_date or cur_day
    while cur_day < start_date:
        cur_day, cur_val = next(dataiter)
    for d in iterate_date(start_date, stop_date):
        if d != cur_day:
            yield default
            continue
        yield cur_val
        try:
            cur_day, cur_val = next(dataiter)
        except StopIteration:
            if not stop_date:
                raise

def now(timezone=None):
    """Return a naive datetime object for the given ``timezone``. A ``timezone``
    is any pytz- like or datetime.tzinfo-like timezone object. If no timezone
    is given, then UTC is assumed.

    This method is best used with pytz installed::

        pip install pytz"""
    d = datetime.datetime.utcnow()
    if not timezone:
        return d
    return to_timezone(d, timezone).replace(tzinfo=None)

def enumerate_query_by_limit(q, limit=1000):
    """Enumerate over SQLAlchemy query object ``q`` and yield individual results
    fetched in batches of size ``limit`` using SQL LIMIT and OFFSET."""
    for offset in count(0, limit):
        r = q.offset(offset).limit(limit).all()
        for row in r:
            yield row
        if len(r) < limit:
            break

def assert_hashable(*args, **kw):
    """Verify that each argument is hashable.

    Passes silently if successful. Raises descriptive TypeError otherwise.

    Example::

        >>> assert_hashable(1, 'foo', bar='baz')
        >>> assert_hashable(1, [], baz='baz')
        Traceback (most recent call last):
          ...
        TypeError: Argument in position 1 is not hashable: []
        >>> assert_hashable(1, 'foo', bar=[])
        Traceback (most recent call last):
          ...
        TypeError: Keyword argument 'bar' is not hashable: []"""
    try:
        for i, arg in enumerate(args):
            hash(arg)
    except TypeError:
        raise TypeError('Argument in position %d is not hashable: %r' % (i, arg))
    try:
        for key, val in iterate_items(kw):
            hash(val)
    except TypeError:
        raise TypeError('Keyword argument %r is not hashable: %r' % (key, val))

def groupby_count(i, key=None, force_keys=None):
    """Aggregate iterator values into buckets based on how frequently the
    values appear.

    Example::

        >>> list(groupby_count([1, 1, 1, 2, 3]))
        [(1, 3), (2, 1), (3, 1)]"""
    counter = defaultdict(lambda: 0)
    if not key:
        key = lambda o: o
    for k in i:
        counter[key(k)] += 1
    if force_keys:
        for k in force_keys:
            counter[k] += 0
    return counter.items()

def random_string(length=6, alphabet=string.ascii_letters + string.digits):
    """Return a random string of given length and alphabet.

    Default alphabet is url-friendly (base62)."""
    return ''.join([random.choice(alphabet) for i in xrange(length)])

def to_unicode(obj, encoding='utf-8', fallback='latin1', **decode_args):
    """Returns a ``unicode`` of ``obj``, decoding using ``encoding`` if necessary.
    If decoding fails, the ``fallback`` encoding (default ``latin1``) is used.

    Examples::

        >>> r(to_unicode(b'\\xe1\\x88\\xb4'))
        u'\\u1234'
        >>> r(to_unicode(b'\\xff'))
        u'\\xff'
        >>> r(to_unicode(u'\\u1234'))
        u'\\u1234'
        >>> r(to_unicode(Exception(u'\\u1234')))
        u'\\u1234'
        >>> r(to_unicode([42]))
        u'[42]'

    See source code for detailed semantics."""
    if not isinstance(obj, binary_type):
        if isinstance(obj, text_type) or hasattr(obj, text_type_magicmethod):
            return text_type(obj)
        obj_str = binary_type(obj)
    else:
        obj_str = obj
    try:
        return text_type(obj_str, encoding, **decode_args)
    except UnicodeDecodeError:
        return text_type(obj_str, fallback, **decode_args)

def slugify(s, delimiter='-'):
    """Normalize `s` into ASCII and replace non-word characters with `delimiter`."""
    s = unicodedata.normalize('NFKD', to_unicode(s)).encode('ascii', 'ignore').decode('ascii')
    return RE_SLUG.sub(delimiter, s).strip(delimiter).lower()

def _generate_dom_attrs(attrs, allow_no_value=True):
    """Yield compiled DOM attribute key-value strings.

    If the value is `True`, then it is treated as no-value. If `None`, then it
    is skipped."""
    for attr in iterate_items(attrs):
        if isinstance(attr, basestring):
            attr = (attr, True)
        key, value = attr
        if value is None:
            continue
        if value is True and (not allow_no_value):
            value = key
        if value is True:
            yield True
        else:
            yield ('%s="%s"' % (key, value.replace('"', '\\"')))

def build_package(path, requires, virtualenv=None, ignore=None, extra_files=None, zipfile_name=ZIPFILE_NAME, pyexec=None):
    """Builds the zip file and creates the package with it"""
    pkg = Package(path, zipfile_name, pyexec)
    if extra_files:
        for fil in extra_files:
            pkg.extra_file(fil)
    if virtualenv is not None:
        pkg.virtualenv(virtualenv)
    pkg.requirements(requires)
    pkg.build(ignore)
    return pkg

def encode_properties(parameters):
    """Performs encoding of url parameters from dictionary to a string. It does
    not escape backslash because it is not needed.

    See: http://www.jfrog.com/confluence/display/RTF/Artifactory+REST+API#ArtifactoryRESTAPI-SetItemProperties"""
    result = []
    for param in iter(sorted(parameters)):
        if isinstance(parameters[param], (list, tuple)):
            value = ','.join([escape_chars(x) for x in parameters[param]])
        else:
            value = escape_chars(parameters[param])
        result.append('%s=%s' % (param, value))
    return '|'.join(result)

def sub(value, arg):
    """Subtract the arg from the value."""
    try:
        nvalue, narg = handle_float_decimal_combinations(valid_numeric(value), valid_numeric(arg), '-')
        return nvalue - narg
    except (ValueError, TypeError):
        try:
            return value - arg
        except Exception:
            return ''

def absolute(value):
    """Return the absolute value."""
    try:
        return abs(valid_numeric(value))
    except (ValueError, TypeError):
        try:
            return abs(value)
        except Exception:
            return ''

def encode_scopes(scopes, use_quote=False):
    """Creates a string out of a list of scopes.

    :param scopes: A list of scopes
    :param use_quote: Boolean flag indicating whether the string should be quoted
    :return: Scopes as a string"""
    scopes_as_string = Scope.separator.join(scopes)
    if use_quote:
        return quote(scopes_as_string)
    return scopes_as_string

def value_for_keypath(obj, path):
    """Get value from walking key path with start object obj.
    """
    val = obj
    for part in path.split('.'):
        match = re.match(list_index_re, part)
        if match is not None:
            val = _extract(val, match.group(1))
            if not isinstance(val, list) and (not isinstance(val, tuple)):
                raise TypeError('expected list/tuple')
            index = int(match.group(2))
            val = val[index]
        else:
            val = _extract(val, part)
        if val is None:
            return None
    return val

def set_value_for_keypath(obj, path, new_value, preserve_child=False):
    """Set attribute value new_value at key path of start object obj.
    """
    parts = path.split('.')
    last_part = len(parts) - 1
    dst = obj
    for i, part in enumerate(parts):
        match = re.match(list_index_re, part)
        if match is not None:
            dst = _extract(dst, match.group(1))
            if not isinstance(dst, list) and (not isinstance(dst, tuple)):
                raise TypeError('expected list/tuple')
            index = int(match.group(2))
            if i == last_part:
                dst[index] = new_value
            else:
                dst = dst[index]
        elif i != last_part:
            dst = _extract(dst, part)
        elif isinstance(dst, dict):
            dst[part] = new_value
        elif not preserve_child:
            setattr(dst, part, new_value)
        else:
            try:
                v = getattr(dst, part)
            except AttributeError:
                setattr(dst, part, new_value)

