def dateJDN(year, month, day, calendar):
    """Converts date to Julian Day Number."""
    a = (14 - month) // 12
    y = year + 4800 - a
    m = month + 12 * a - 3
    if calendar == GREGORIAN:
        return day + (153 * m + 2) // 5 + 365 * y + y // 4 - y // 100 + y // 400 - 32045
    else:
        return day + (153 * m + 2) // 5 + 365 * y + y // 4 - 32083

def getObject(ID, jd, lat, lon):
    """Returns an object for a specific date and
    location."""
    if ID == const.SOUTH_NODE:
        obj = swe.sweObject(const.NORTH_NODE, jd)
        obj.update({'id': const.SOUTH_NODE, 'lon': angle.norm(obj['lon'] + 180)})
    elif ID == const.PARS_FORTUNA:
        pflon = tools.pfLon(jd, lat, lon)
        obj = {'id': ID, 'lon': pflon, 'lat': 0, 'lonspeed': 0, 'latspeed': 0}
    elif ID == const.SYZYGY:
        szjd = tools.syzygyJD(jd)
        obj = swe.sweObject(const.MOON, szjd)
        obj['id'] = const.SYZYGY
    else:
        obj = swe.sweObject(ID, jd)
    _signInfo(obj)
    return obj

def getHouses(jd, lat, lon, hsys):
    """Returns lists of houses and angles."""
    houses, angles = swe.sweHouses(jd, lat, lon, hsys)
    for house in houses:
        _signInfo(house)
    for angle in angles:
        _signInfo(angle)
    return (houses, angles)

def nextSunrise(jd, lat, lon):
    """Returns the JD of the next sunrise."""
    return swe.sweNextTransit(const.SUN, jd, lat, lon, 'RISE')

def nextSunset(jd, lat, lon):
    """Returns the JD of the next sunset."""
    return swe.sweNextTransit(const.SUN, jd, lat, lon, 'SET')

def pfLon(jd, lat, lon):
    """Returns the ecliptic longitude of Pars Fortuna.
    It considers diurnal or nocturnal conditions."""
    sun = swe.sweObjectLon(const.SUN, jd)
    moon = swe.sweObjectLon(const.MOON, jd)
    asc = swe.sweHousesLon(jd, lat, lon, const.HOUSES_DEFAULT)[1][0]
    if isDiurnal(jd, lat, lon):
        return angle.norm(asc + moon - sun)
    else:
        return angle.norm(asc + sun - moon)

def nextStationJD(ID, jd):
    """Finds the aproximate julian date of the
    next station of a planet."""
    speed = swe.sweObject(ID, jd)['lonspeed']
    for i in range(2000):
        nextjd = jd + i / 2
        nextspeed = swe.sweObject(ID, nextjd)['lonspeed']
        if speed * nextspeed <= 0:
            return nextjd
    return None

def clean_caches(path):
    """Removes all python cache files recursively on a path.

    :param path: the path
    :return: None"""
    for dirname, subdirlist, filelist in os.walk(path):
        for f in filelist:
            if f.endswith('pyc'):
                try:
                    os.remove(os.path.join(dirname, f))
                except FileNotFoundError:
                    pass
        if dirname.endswith('__pycache__'):
            shutil.rmtree(dirname)

def clean_py_files(path):
    """Removes all .py files.

    :param path: the path
    :return: None"""
    for dirname, subdirlist, filelist in os.walk(path):
        for f in filelist:
            if f.endswith('py'):
                os.remove(os.path.join(dirname, f))

def toFloat(value):
    """Converts angle representation to float.
    Accepts angles and strings such as "12W30:00"."""
    if isinstance(value, str):
        value = value.upper()
        for char in ['N', 'S', 'E', 'W']:
            if char in value:
                value = SIGN[char] + value.replace(char, ':')
                break
    return angle.toFloat(value)

def _getActivePassive(obj1, obj2):
    """Returns which is the active and the passive objects."""
    speed1 = abs(obj1.lonspeed) if obj1.isPlanet() else -1.0
    speed2 = abs(obj2.lonspeed) if obj2.isPlanet() else -1.0
    if speed1 > speed2:
        return {'active': obj1, 'passive': obj2}
    else:
        return {'active': obj2, 'passive': obj1}

def isAspecting(obj1, obj2, aspList):
    """Returns if obj1 aspects obj2 within its orb,
    considering a list of possible aspect types."""
    aspDict = _aspectDict(obj1, obj2, aspList)
    if aspDict:
        return aspDict['orb'] < obj1.orb()
    return False

def getAspect(obj1, obj2, aspList):
    """Returns an Aspect object for the aspect between two
    objects considering a list of possible aspect types."""
    ap = _getActivePassive(obj1, obj2)
    aspDict = _aspectDict(ap['active'], ap['passive'], aspList)
    if not aspDict:
        aspDict = {'type': const.NO_ASPECT, 'orb': 0, 'separation': 0}
    aspProp = _aspectProperties(ap['active'], ap['passive'], aspDict)
    return Aspect(aspProp)

def setFaces(variant):
    """Sets the default faces variant"""
    global FACES
    if variant == CHALDEAN_FACES:
        FACES = tables.CHALDEAN_FACES
    else:
        FACES = tables.TRIPLICITY_FACES

def setTerms(variant):
    """Sets the default terms of the Dignities
    table."""
    global TERMS
    if variant == EGYPTIAN_TERMS:
        TERMS = tables.EGYPTIAN_TERMS
    elif variant == TETRABIBLOS_TERMS:
        TERMS = tables.TETRABIBLOS_TERMS
    elif variant == LILLY_TERMS:
        TERMS = tables.LILLY_TERMS

def term(sign, lon):
    """Returns the term for a sign and longitude."""
    terms = TERMS[sign]
    for ID, a, b in terms:
        if a <= lon < b:
            return ID
    return None

def face(sign, lon):
    """Returns the face for a sign and longitude."""
    faces = FACES[sign]
    if lon < 10:
        return faces[0]
    elif lon < 20:
        return faces[1]
    else:
        return faces[2]

def getInfo(sign, lon):
    """Returns the complete essential dignities
    for a sign and longitude."""
    return {'ruler': ruler(sign), 'exalt': exalt(sign), 'dayTrip': dayTrip(sign), 'nightTrip': nightTrip(sign), 'partTrip': partTrip(sign), 'term': term(sign, lon), 'face': face(sign, lon), 'exile': exile(sign), 'fall': fall(sign)}

def isPeregrine(ID, sign, lon):
    """Returns if an object is peregrine
    on a sign and longitude."""
    info = getInfo(sign, lon)
    for dign, objID in info.items():
        if dign not in ['exile', 'fall'] and ID == objID:
            return False
    return True

def score(ID, sign, lon):
    """Returns the score of an object on
    a sign and longitude."""
    info = getInfo(sign, lon)
    dignities = [dign for dign, objID in info.items() if objID == ID]
    return sum([SCORES[dign] for dign in dignities])

def almutem(sign, lon):
    """Returns the almutem for a given
    sign and longitude."""
    planets = const.LIST_SEVEN_PLANETS
    res = [None, 0]
    for ID in planets:
        sc = score(ID, sign, lon)
        if sc > res[1]:
            res = [ID, sc]
    return res[0]

def nextSolarReturn(chart, date):
    """Returns the solar return of a Chart
    after a specific date."""
    sun = chart.getObject(const.SUN)
    srDate = ephem.nextSolarReturn(date, sun.lon)
    return _computeChart(chart, srDate)

def getHourTable(date, pos):
    """Returns an HourTable object."""
    table = hourTable(date, pos)
    return HourTable(table, date)

def is_valid(file_path):
    """Check to see if a file exists or is empty."""
    from os import path, stat
    can_open = False
    try:
        with open(file_path) as fp:
            can_open = True
    except IOError:
        return False
    is_file = path.isfile(file_path)
    return path.exists(file_path) and is_file and (stat(file_path).st_size > 0)

def make_geojson(contents):
    """Return a GeoJSON string from a variety of inputs.
    See the documentation for make_url for the possible contents
    input.

    Returns
    -------
    GeoJSON string"""
    if isinstance(contents, six.string_types):
        return contents
    if hasattr(contents, '__geo_interface__'):
        features = [_geo_to_feature(contents)]
    else:
        try:
            feature_iter = iter(contents)
        except TypeError:
            raise ValueError('Unknown type for input')
        features = []
        for i, f in enumerate(feature_iter):
            if not hasattr(f, '__geo_interface__'):
                raise ValueError('Unknown type at index {0}'.format(i))
            features.append(_geo_to_feature(f))
    data = {'type': 'FeatureCollection', 'features': features}
    return json.dumps(data)

def tree(X, n, alpha=0, symbolic=False):
    """Recurrence coefficients for generalized Laguerre polynomials. Set
    alpha=0 (default) to get classical Laguerre."""
    args = recurrence_coefficients(n, alpha=alpha, symbolic=symbolic)
    return line_tree(X, *args)

def _iget(key, lookup_dict):
    """Case-insensitive search for `key` within keys of `lookup_dict`."""
    for k, v in lookup_dict.items():
        if k.lower() == key.lower():
            return v
    return None

def getlang_by_name(name):
    """Try to lookup a Language object by name, e.g. 'English', in internal language list.
    Returns None if lookup by language name fails in resources/languagelookup.json."""
    direct_match = _iget(name, _LANGUAGE_NAME_LOOKUP)
    if direct_match:
        return direct_match
    else:
        simple_name = name.split(',')[0]
        simple_name = simple_name.split('(')[0].strip()
        return _LANGUAGE_NAME_LOOKUP.get(simple_name, None)

def getlang_by_native_name(native_name):
    """Try to lookup a Language object by native_name, e.g. 'English', in internal language list.
    Returns None if lookup by language name fails in resources/languagelookup.json."""
    direct_match = _iget(native_name, _LANGUAGE_NATIVE_NAME_LOOKUP)
    if direct_match:
        return direct_match
    else:
        simple_native_name = native_name.split(',')[0]
        simple_native_name = simple_native_name.split('(')[0].strip()
        return _LANGUAGE_NATIVE_NAME_LOOKUP.get(simple_native_name, None)

def getlang_by_alpha2(code):
    """Lookup a Language object for language code `code` based on these strategies:
      - Special case rules for Hebrew and Chinese Hans/Hant scripts
      - Using `alpha_2` lookup in `pycountry.languages` followed by lookup for a
        language with the same `name` in the internal representaion
    Returns `None` if no matching language is found."""
    if code == 'iw':
        return getlang('he')
    elif 'zh-Hans' in code:
        return getlang('zh-CN')
    elif 'zh-Hant' in code or re.match('zh(.*)?-HK', code):
        return getlang('zh-TW')
    first_part = code.split('-')[0]
    try:
        pyc_lang = pycountry.languages.get(alpha_2=first_part)
        if pyc_lang:
            if hasattr(pyc_lang, 'inverted_name'):
                lang_name = pyc_lang.inverted_name
            else:
                lang_name = pyc_lang.name
            return getlang_by_name(lang_name)
        else:
            return None
    except KeyError:
        return None

def tree_sph(polar, azimuthal, n, standardization, symbolic=False):
    """Evaluate all spherical harmonics of degree at most `n` at angles `polar`,
    `azimuthal`."""
    cos = numpy.vectorize(sympy.cos) if symbolic else numpy.cos
    config = {'acoustic': ('complex spherical', False), 'quantum mechanic': ('complex spherical', True), 'geodetic': ('complex spherical 1', False), 'schmidt': ('schmidt', False)}
    standard, cs_phase = config[standardization]
    return tree_alp(cos(polar), n, phi=azimuthal, standardization=standard, with_condon_shortley_phase=cs_phase, symbolic=symbolic)

def handle_zeros_in_scale(scale, copy=True):
    """Makes sure that whenever scale is zero, we handle it correctly.
    This happens in most scalers when we have constant features.
    Adapted from sklearn.preprocessing.data"""
    if np.isscalar(scale):
        if scale == 0.0:
            scale = 1.0
        return scale
    elif isinstance(scale, np.ndarray):
        if copy:
            scale = scale.copy()
        scale[scale == 0.0] = 1.0
    return scale

def build_interfaces_by_method(interfaces):
    """Create new dictionary from INTERFACES hashed by method then
    the endpoints name. For use when using the disqusapi by the
    method interface instead of the endpoint interface. For
    instance:

    'blacklists': {
        'add': {
            'formats': ['json', 'jsonp'],
            'method': 'POST',
            'required': ['forum']
        }
    }

    is translated to:

    'POST': {
        'blacklists.add': {
            'formats': ['json', 'jsonp'],
            'method': 'POST',
            'required': ['forum']
    }"""
    def traverse(block, parts):
        try:
            method = block['method'].lower()
        except KeyError:
            for k, v in compat.iteritems(block):
                traverse(v, parts + [k])
        else:
            path = '.'.join(parts)
            try:
                methods[method]
            except KeyError:
                methods[method] = {}
            methods[method][path] = block
    methods = {}
    for key, val in compat.iteritems(interfaces):
        traverse(val, [key])
    return methods

def get_normalized_request_string(method, url, nonce, params, ext='', body_hash=None):
    """Returns a normalized request string as described iN OAuth2 MAC spec.

    http://tools.ietf.org/html/draft-ietf-oauth-v2-http-mac-00#section-3.3.1"""
    urlparts = urlparse.urlparse(url)
    if urlparts.query:
        norm_url = '%s?%s' % (urlparts.path, urlparts.query)
    elif params:
        norm_url = '%s?%s' % (urlparts.path, get_normalized_params(params))
    else:
        norm_url = urlparts.path
    if not body_hash:
        body_hash = get_body_hash(params)
    port = urlparts.port
    if not port:
        assert urlparts.scheme in ('http', 'https')
        if urlparts.scheme == 'http':
            port = 80
        elif urlparts.scheme == 'https':
            port = 443
    output = [nonce, method.upper(), norm_url, urlparts.hostname, port, body_hash, ext, '']
    return '\n'.join(map(str, output))

def overlap(xl1, yl1, nx1, ny1, xl2, yl2, nx2, ny2):
    """Determines whether two windows overlap"""
    return xl2 < xl1 + nx1 and xl2 + nx2 > xl1 and (yl2 < yl1 + ny1) and (yl2 + ny2 > yl1)

def createJSON(g, full=True):
    """Create JSON compatible dictionary from current settings

    Parameters
    ----------
    g :  hcam_drivers.globals.Container
    Container with globals"""
    data = dict()
    if 'gps_attached' not in g.cpars:
        data['gps_attached'] = 1
    else:
        data['gps_attached'] = 1 if g.cpars['gps_attached'] else 0
    data['appdata'] = g.ipars.dumpJSON()
    data['user'] = g.rpars.dumpJSON()
    if full:
        data['hardware'] = g.ccd_hw.dumpJSON()
        data['tcs'] = g.info.dumpJSON()
        if g.cpars['telins_name'].lower() == 'gtc' and has_corba:
            try:
                s = get_telescope_server()
                data['gtc_headers'] = dict(create_header_from_telpars(s.getTelescopeParams()))
            except:
                g.clog.warn('cannot get GTC headers from telescope server')
    return data

def isRunActive(g):
    """Polls the data server to see if a run is active"""
    if g.cpars['hcam_server_on']:
        url = g.cpars['hipercam_server'] + 'summary'
        response = urllib.request.urlopen(url, timeout=2)
        rs = ReadServer(response.read(), status_msg=True)
        if not rs.ok:
            raise DriverError('isRunActive error: ' + str(rs.err))
        if rs.state == 'idle':
            return False
        elif rs.state == 'active':
            return True
        else:
            raise DriverError('isRunActive error, state = ' + rs.state)
    else:
        raise DriverError('isRunActive error: servers are not active')

def getFrameNumber(g):
    """Polls the data server to find the current frame number.

    Throws an exceotion if it cannot determine it."""
    if not g.cpars['hcam_server_on']:
        raise DriverError('getRunNumber error: servers are not active')
    url = g.cpars['hipercam_server'] + 'status/DET.FRAM2.NO'
    response = urllib.request.urlopen(url, timeout=2)
    rs = ReadServer(response.read(), status_msg=False)
    try:
        msg = rs.msg
    except:
        raise DriverError('getFrameNumber error: no message found')
    try:
        frame_no = int(msg.split()[1])
    except:
        raise DriverError('getFrameNumber error: invalid msg ' + msg)
    return frame_no

def getRunNumber(g):
    """Polls the data server to find the current run number. Throws
    exceptions if it can't determine it."""
    if not g.cpars['hcam_server_on']:
        raise DriverError('getRunNumber error: servers are not active')
    url = g.cpars['hipercam_server'] + 'summary'
    response = urllib.request.urlopen(url, timeout=2)
    rs = ReadServer(response.read(), status_msg=True)
    if rs.ok:
        return rs.run
    else:
        raise DriverError('getRunNumber error: ' + str(rs.err))

def rand_str(charset, length=32):
    """Generate random string."""
    return ''.join([random.choice(charset) for _ in range(length)])

def get_root(w):
    """Simple method to access root for a widget"""
    next_level = w
    while next_level.master:
        next_level = next_level.master
    return next_level

def parse_hstring(hs):
    """Parse a single item from the telescope server into name, value, comment."""
    name, value, comment = yield_three([val.strip().strip("'") for val in filter(None, re.split('[=/]+', hs))])
    try:
        len(comment)
    except:
        pass
    else:
        comment = '/'.join(comment)
    return (name, value, comment)

def main(guess_a=1.0, guess_b=0.0, power=3, savetxt='None', verbose=False):
    """Example demonstrating how to solve a system of non-linear equations defined as SymPy expressions.

    The example shows how a non-linear problem can be given a command-line interface which may be
    preferred by end-users who are not familiar with Python."""
    x, sol = solve(guess_a, guess_b, power)
    assert sol.success
    if savetxt != 'None':
        np.savetxt(x, savetxt)
    elif verbose:
        print(sol)
    else:
        print(x)

def clean_readme(fname):
    """Cleanup README.rst for proper PyPI formatting."""
    with codecs.open(fname, 'r', 'utf-8') as f:
        return ''.join((re.sub(':\\w+:`([^`]+?)( <[^<>]+>)?`', '``\\1``', line) for line in f if not (line.startswith('.. currentmodule') or line.startswith('.. toctree'))))

def dearmor(text, verify=True):
    """Given a string in ASCII Armor format, returns the decoded binary data.
    If verify=True (the default), the CRC is decoded and checked against that
    of the decoded data, otherwise it is ignored. If the checksum does not
    match, a BadChecksumError exception is raised."""
    lines = text.strip().split('\n')
    data_lines = []
    check_data = None
    started = False
    in_body = False
    for line in lines:
        if line.startswith('-----BEGIN'):
            started = True
        elif line.startswith('-----END'):
            break
        elif started:
            if in_body:
                if line.startswith('='):
                    check_data = line[1:5].encode('ascii')
                    break
                else:
                    data_lines.append(line)
            elif line.strip():
                pass
            else:
                in_body = True
    b64_str = ''.join(data_lines)
    data = base64.b64decode(b64_str.encode('ascii'))
    if verify and check_data:
        crc = struct.unpack('>L', b'\x00' + base64.b64decode(check_data))[0]
        if crc != crc24(data):
            raise BadChecksumError()
    return data

def unpad(text, block_size):
    """Takes the last character of the text, and if it is less than the block_size,
    assumes the text is padded, and removes any trailing zeros or bytes with the
    value of the pad character. See http://www.di-mgt.com.au/cryptopad.html for
    more information (methods 1, 3, and 4)."""
    end = len(text)
    if end == 0:
        return text
    padch = ord_safe(text[end - 1])
    if padch > block_size:
        return text
    while end > 0 and ord_safe(text[end - 1]) in (0, padch):
        end -= 1
    return text[:end]

def aes_pad_key(key):
    """AES keys must be either 16, 24, or 32 bytes long. If a key is provided that is not
    one of these lengths, pad it with zeroes (this is what pgcrypto does)."""
    if len(key) in (16, 24, 32):
        return key
    if len(key) < 16:
        return pad(key, 16, zero=True)
    elif len(key) < 24:
        return pad(key, 24, zero=True)
    else:
        return pad(key[:32], 32, zero=True)

def browse(ctx):
    """Open documentation in web browser."""
    page_html = Path(ctx.config.sphinx.destdir) / 'html' / 'index.html'
    if not page_html.exists():
        build(ctx, builder='html')
    assert page_html.exists()
    open_cmd = 'open'
    if sys.platform.startswith('win'):
        open_cmd = 'start'
    ctx.run('{open} {page_html}'.format(open=open_cmd, page_html=page_html))

def setup_path(invoke_minversion=None):
    """Setup python search and add ``TASKS_VENDOR_DIR`` (if available)."""
    if not os.path.isdir(TASKS_VENDOR_DIR):
        print('SKIP: TASKS_VENDOR_DIR=%s is missing' % TASKS_VENDOR_DIR)
        return
    elif os.path.abspath(TASKS_VENDOR_DIR) in sys.path:
        pass
    use_vendor_bundles = os.environ.get('INVOKE_TASKS_USE_VENDOR_BUNDLES', 'no')
    if need_vendor_bundles(invoke_minversion):
        use_vendor_bundles = 'yes'
    if use_vendor_bundles == 'yes':
        syspath_insert(0, os.path.abspath(TASKS_VENDOR_DIR))
        if setup_path_for_bundle(INVOKE_BUNDLE, pos=1):
            import invoke
            bundle_path = os.path.relpath(INVOKE_BUNDLE, os.getcwd())
            print('USING: %s (version: %s)' % (bundle_path, invoke.__version__))
    else:
        syspath_append(os.path.abspath(TASKS_VENDOR_DIR))
        setup_path_for_bundle(INVOKE_BUNDLE, pos=len(sys.path))
    if DEBUG_SYSPATH:
        for index, p in enumerate(sys.path):
            print('  %d.  %s' % (index, p))

def matches_section(section_name):
    """Decorator for SectionSchema classes to define the mapping between
    a config section schema class and one or more config sections with
    matching name(s).

    .. sourcecode::

        @matches_section("foo")
        class FooSchema(SectionSchema):
            pass

        @matches_section(["bar", "baz.*"])
        class BarAndBazSchema(SectionSchema):
            pass

    .. sourcecode:: ini

        # -- FILE: *.ini
        [foo]       # USE: FooSchema
        ...

        [bar]       # USE: BarAndBazSchema
        ...

        [baz.alice] # USE: BarAndBazSchema
        ..."""
    section_names = section_name
    if isinstance(section_name, six.string_types):
        section_names = [section_name]
    elif not isinstance(section_name, (list, tuple)):
        raise ValueError('%r (expected: string, strings)' % section_name)
    def decorator(cls):
        class_section_names = getattr(cls, 'section_names', None)
        if class_section_names is None:
            cls.section_names = list(section_names)
        else:
            approved = [name for name in section_names if name not in cls.section_names]
            cls.section_names = approved + cls.section_names
        return cls
    return decorator

def assign_param_names(cls=None, param_class=None):
    '''Class decorator to assign parameter name to instances of :class:`Param`.

    .. sourcecode::

        @assign_param_names
        class ConfigSectionSchema(object):
            alice = Param(type=str)
            bob   = Param(type=str)

        assert ConfigSectionSchema.alice.name == "alice"
        assert ConfigSectionSchema.bob.name == "bob"

    .. sourcecode::

        # -- NESTED ASSIGN: Covers also nested SectionSchema subclasses.
        @assign_param_names
        class ConfigSectionSchema(object):
            class Foo(SectionSchema):
                alice = Param(type=str)
                bob   = Param(type=str)

        assert ConfigSectionSchema.Foo.alice.name == "alice"
        assert ConfigSectionSchema.Foo.bob.name == "bob"'''
    if param_class is None:
        param_class = Param
    def decorate_class(cls):
        for name, value in select_params_from_section_schema(cls, param_class, deep=True):
            if not value.name:
                value.name = name
        return cls
    if cls is None:
        return decorate_class
    else:
        return decorate_class(cls)

def select_params_from_section_schema(section_schema, param_class=Param, deep=False):
    """Selects the parameters of a config section schema.

    :param section_schema:  Configuration file section schema to use.
    :return: Generator of params"""
    for name, value in inspect.getmembers(section_schema):
        if name.startswith('__') or value is None:
            continue
        elif inspect.isclass(value) and deep:
            cls = value
            for name, value in select_params_from_section_schema(cls, param_class=param_class, deep=True):
                yield (name, value)
        elif isinstance(value, param_class):
            yield (name, value)

def generate_configfile_names(config_files, config_searchpath=None):
    """Generates all configuration file name combinations to read.

    .. sourcecode::

        # -- ALGORITHM:
        #    First basenames/directories are prefered and override other files.
        for config_path in reversed(config_searchpath):
            for config_basename in reversed(config_files):
                config_fname = os.path.join(config_path, config_basename)
                if os.path.isfile(config_fname):
                    yield config_fname

    :param config_files:        List of config file basenames.
    :param config_searchpath:   List of directories to look for config files.
    :return: List of available configuration file names (as generator)"""
    if config_searchpath is None:
        config_searchpath = ['.']
    for config_path in reversed(config_searchpath):
        for config_basename in reversed(config_files):
            config_fname = os.path.join(config_path, config_basename)
            if os.path.isfile(config_fname):
                yield config_fname

def select_config_sections(configfile_sections, desired_section_patterns):
    """Select a subset of the sections in a configuration file by using
    a list of section names of list of section name patters
    (supporting :mod:`fnmatch` wildcards).

    :param configfile_sections: List of config section names (as strings).
    :param desired_section_patterns:
    :return: List of selected section names or empty list (as generator)."""
    for section_name in configfile_sections:
        for desired_section_pattern in desired_section_patterns:
            if fnmatch(section_name, desired_section_pattern):
                yield section_name

def clean_python(ctx, dry_run=False):
    """Cleanup python related files/dirs: *.pyc, *.pyo, ..."""
    cleanup_dirs(['build', 'dist', '*.egg-info', '**/__pycache__'], dry_run=dry_run)
    if not dry_run:
        ctx.run('py.cleanup')
    cleanup_files(['**/*.pyc', '**/*.pyo', '**/*$py.class'], dry_run=dry_run)

def cleanup_files(patterns, dry_run=False, workdir='.'):
    """Remove files or files selected by file patterns.
    Skips removal if file does not exist.

    :param patterns:    File patterns, like "**/*.pyc" (as list).
    :param dry_run:     Dry-run mode indicator (as bool).
    :param workdir:     Current work directory (default=".")"""
    current_dir = Path(workdir)
    python_basedir = Path(Path(sys.executable).dirname()).joinpath('..').abspath()
    error_message = None
    error_count = 0
    for file_pattern in patterns:
        for file_ in path_glob(file_pattern, current_dir):
            if file_.abspath().startswith(python_basedir):
                continue
            if dry_run:
                print('REMOVE: %s (dry-run)' % file_)
            else:
                print('REMOVE: %s' % file_)
                try:
                    file_.remove_p()
                except os.error as e:
                    message = '%s: %s' % (e.__class__.__name__, e)
                    print(message + ' basedir: ' + python_basedir)
                    error_count += 1
                    if not error_message:
                        error_message = message
    if False and error_message:
        class CleanupError(RuntimeError):
            pass
        raise CleanupError(error_message)

def path_glob(pattern, current_dir=None):
    """Use pathlib for ant-like patterns, like: "**/*.py"

    :param pattern:      File/directory pattern to use (as string).
    :param current_dir:  Current working directory (as Path, pathlib.Path, str)
    :return Resolved Path (as path.Path)."""
    if not current_dir:
        current_dir = pathlib.Path.cwd()
    elif not isinstance(current_dir, pathlib.Path):
        current_dir = pathlib.Path(str(current_dir))
    for p in current_dir.glob(pattern):
        yield Path(str(p))

def create_url(artist, song):
    """Create the URL in the LyricWikia format"""
    return __BASE_URL__ + '/wiki/{artist}:{song}'.format(artist=urlize(artist), song=urlize(song))

def get_all_lyrics(artist, song, linesep='\n', timeout=None):
    """Retrieve a list of all the lyrics versions of a song."""
    url = create_url(artist, song)
    response = _requests.get(url, timeout=timeout)
    soup = _BeautifulSoup(response.content, 'html.parser')
    lyricboxes = soup.findAll('div', {'class': 'lyricbox'})
    if not lyricboxes:
        raise LyricsNotFound('Cannot download lyrics')
    for lyricbox in lyricboxes:
        for br in lyricbox.findAll('br'):
            br.replace_with(linesep)
    return [lyricbox.text.strip() for lyricbox in lyricboxes]

def remote_pdb_handler(signum, frame):
    """Handler to drop us into a remote debugger upon receiving SIGUSR1"""
    try:
        from remote_pdb import RemotePdb
        rdb = RemotePdb(host='127.0.0.1', port=0)
        rdb.set_trace(frame=frame)
    except ImportError:
        log.warning('remote_pdb unavailable.  Please install remote_pdb to allow remote debugging.')
    signal.signal(signum, remote_pdb_handler)

def _load_data():
    """Load the word and character mapping data into a dictionary.

    In the data files, each line is formatted like this:
        HANZI   PINYIN_READING/PINYIN_READING

    So, lines need to be split by '     ' and then the Pinyin readings need to be
    split by '/'."""
    data = {}
    for name, file_name in (('words', 'hanzi_pinyin_words.tsv'), ('characters', 'hanzi_pinyin_characters.tsv')):
        lines = [line.split('\t') for line in dragonmapper.data.load_data_file(file_name)]
        data[name] = {hanzi: pinyin.split('/') for hanzi, pinyin in lines}
    return data

def _enclose_readings(container, readings):
    """Enclose a reading within a container, e.g. '[]'."""
    container_start, container_end = tuple(container)
    enclosed_readings = '%(container_start)s%(readings)s%(container_end)s' % {'container_start': container_start, 'container_end': container_end, 'readings': readings}
    return enclosed_readings

def _load_data():
    """Load the transcription mapping data into a dictionary."""
    lines = dragonmapper.data.load_data_file('transcriptions.csv')
    pinyin_map, zhuyin_map, ipa_map = ({}, {}, {})
    for line in lines:
        p, z, i = line.split(',')
        pinyin_map[p] = {'Zhuyin': z, 'IPA': i}
        zhuyin_map[z] = {'Pinyin': p, 'IPA': i}
        ipa_map[i] = {'Pinyin': p, 'Zhuyin': z}
    return (pinyin_map, zhuyin_map, ipa_map)

def _numbered_vowel_to_accented(vowel, tone):
    """Convert a numbered Pinyin vowel to an accented Pinyin vowel."""
    if isinstance(tone, int):
        tone = str(tone)
    return _PINYIN_TONES[vowel + tone]

def _accented_vowel_to_numbered(vowel):
    """Convert an accented Pinyin vowel to a numbered Pinyin vowel."""
    for numbered_vowel, accented_vowel in _PINYIN_TONES.items():
        if vowel == accented_vowel:
            return tuple(numbered_vowel)

def _parse_numbered_syllable(unparsed_syllable):
    """Return the syllable and tone of a numbered Pinyin syllable."""
    tone_number = unparsed_syllable[-1]
    if not tone_number.isdigit():
        syllable, tone = (unparsed_syllable, '5')
    elif tone_number == '0':
        syllable, tone = (unparsed_syllable[:-1], '5')
    elif tone_number in '12345':
        syllable, tone = (unparsed_syllable[:-1], tone_number)
    else:
        raise ValueError('Invalid syllable: %s' % unparsed_syllable)
    return (syllable, tone)

def _parse_zhuyin_syllable(unparsed_syllable):
    """Return the syllable and tone of a Zhuyin syllable."""
    zhuyin_tone = unparsed_syllable[-1]
    if zhuyin_tone in zhon.zhuyin.characters:
        syllable, tone = (unparsed_syllable, '1')
    elif zhuyin_tone in zhon.zhuyin.marks:
        for tone_number, tone_mark in _ZHUYIN_TONES.items():
            if zhuyin_tone == tone_mark:
                syllable, tone = (unparsed_syllable[:-1], tone_number)
    else:
        raise ValueError('Invalid syllable: %s' % unparsed_syllable)
    return (syllable, tone)

def _parse_ipa_syllable(unparsed_syllable):
    """Return the syllable and tone of an IPA syllable."""
    ipa_tone = re.search('[%(marks)s]+' % {'marks': _IPA_MARKS}, unparsed_syllable)
    if not ipa_tone:
        syllable, tone = (unparsed_syllable, '5')
    else:
        for tone_number, tone_mark in _IPA_TONES.items():
            if ipa_tone.group() == tone_mark:
                tone = tone_number
                break
        syllable = unparsed_syllable[0:ipa_tone.start()]
    return (syllable, tone)

def _restore_case(s, memory):
    """Restore a lowercase string's characters to their original case."""
    cased_s = []
    for i, c in enumerate(s):
        if i + 1 > len(memory):
            break
        cased_s.append(c if memory[i] else c.upper())
    return ''.join(cased_s)

def pinyin_syllable_to_zhuyin(s):
    """Convert Pinyin syllable *s* to a Zhuyin syllable."""
    pinyin_syllable, tone = _parse_pinyin_syllable(s)
    try:
        zhuyin_syllable = _PINYIN_MAP[pinyin_syllable.lower()]['Zhuyin']
    except KeyError:
        raise ValueError('Not a valid syllable: %s' % s)
    return zhuyin_syllable + _ZHUYIN_TONES[tone]

def pinyin_syllable_to_ipa(s):
    """Convert Pinyin syllable *s* to an IPA syllable."""
    pinyin_syllable, tone = _parse_pinyin_syllable(s)
    try:
        ipa_syllable = _PINYIN_MAP[pinyin_syllable.lower()]['IPA']
    except KeyError:
        raise ValueError('Not a valid syllable: %s' % s)
    return ipa_syllable + _IPA_TONES[tone]

def _zhuyin_syllable_to_numbered(s):
    """Convert Zhuyin syllable *s* to a numbered Pinyin syllable."""
    zhuyin_syllable, tone = _parse_zhuyin_syllable(s)
    try:
        pinyin_syllable = _ZHUYIN_MAP[zhuyin_syllable]['Pinyin']
    except KeyError:
        raise ValueError('Not a valid syllable: %s' % s)
    return pinyin_syllable + tone

def _ipa_syllable_to_numbered(s):
    """Convert IPA syllable *s* to a numbered Pinyin syllable."""
    ipa_syllable, tone = _parse_ipa_syllable(s)
    try:
        pinyin_syllable = _IPA_MAP[ipa_syllable]['Pinyin']
    except KeyError:
        raise ValueError('Not a valid syllable: %s' % s)
    return pinyin_syllable + tone

def _convert(s, re_pattern, syllable_function, add_apostrophes=False, remove_apostrophes=False, separate_syllables=False):
    """Convert a string's syllables to a different transcription system."""
    original = s
    new = ''
    while original:
        match = re.search(re_pattern, original, re.IGNORECASE | re.UNICODE)
        if match is None and original:
            new += original
            break
        match_start, match_end = match.span()
        if match_start > 0:
            if new and remove_apostrophes and (match_start == 1) and (original[0] == "'"):
                pass
                if separate_syllables:
                    new += ' '
            else:
                new += original[0:match_start]
        elif new and separate_syllables:
            new += ' '
        elif new and add_apostrophes and (match.group()[0].lower() in _UNACCENTED_VOWELS):
            new += "'"
        new += syllable_function(match.group())
        original = original[match_end:]
    return new

def numbered_to_accented(s):
    """Convert all numbered Pinyin syllables in *s* to accented Pinyin."""
    return _convert(s, zhon.pinyin.syllable, numbered_syllable_to_accented, add_apostrophes=True)

def pinyin_to_zhuyin(s):
    """Convert all Pinyin syllables in *s* to Zhuyin.

    Spaces are added between connected syllables and syllable-separating
    apostrophes are removed."""
    return _convert(s, zhon.pinyin.syllable, pinyin_syllable_to_zhuyin, remove_apostrophes=True, separate_syllables=True)

def pinyin_to_ipa(s):
    """Convert all Pinyin syllables in *s* to IPA.

    Spaces are added between connected syllables and syllable-separating
    apostrophes are removed."""
    return _convert(s, zhon.pinyin.syllable, pinyin_syllable_to_ipa, remove_apostrophes=True, separate_syllables=True)

def zhuyin_to_pinyin(s, accented=True):
    """Convert all Zhuyin syllables in *s* to Pinyin.

    If *accented* is ``True``, diacritics are added to the Pinyin syllables. If
    it's ``False``, numbers are used to indicate tone."""
    if accented:
        function = _zhuyin_syllable_to_accented
    else:
        function = _zhuyin_syllable_to_numbered
    return _convert(s, zhon.zhuyin.syllable, function)

def ipa_to_pinyin(s, accented=True):
    """Convert all IPA syllables in *s* to Pinyin.

    If *accented* is ``True``, diacritics are added to the Pinyin syllables. If
    it's ``False``, numbers are used to indicate tone."""
    if accented:
        function = _ipa_syllable_to_accented
    else:
        function = _ipa_syllable_to_numbered
    return _convert(s, _IPA_SYLLABLE, function)

def to_pinyin(s, accented=True):
    """Convert *s* to Pinyin.

    If *accented* is ``True``, diacritics are added to the Pinyin syllables. If
    it's ``False``, numbers are used to indicate tone."""
    identity = identify(s)
    if identity == PINYIN:
        if _has_accented_vowels(s):
            return s if accented else accented_to_numbered(s)
        else:
            return numbered_to_accented(s) if accented else s
    elif identity == ZHUYIN:
        return zhuyin_to_pinyin(s, accented=accented)
    elif identity == IPA:
        return ipa_to_pinyin(s, accented=accented)
    else:
        raise ValueError('String is not a valid Chinese transcription.')

def to_zhuyin(s):
    """Convert *s* to Zhuyin."""
    identity = identify(s)
    if identity == ZHUYIN:
        return s
    elif identity == PINYIN:
        return pinyin_to_zhuyin(s)
    elif identity == IPA:
        return ipa_to_zhuyin(s)
    else:
        raise ValueError('String is not a valid Chinese transcription.')

def to_ipa(s):
    """Convert *s* to IPA."""
    identity = identify(s)
    if identity == IPA:
        return s
    elif identity == PINYIN:
        return pinyin_to_ipa(s)
    elif identity == ZHUYIN:
        return zhuyin_to_ipa(s)
    else:
        raise ValueError('String is not a valid Chinese transcription.')

def is_pinyin(s):
    """Check if *s* consists of valid Pinyin."""
    re_pattern = '(?:%(word)s|[ \t%(punctuation)s])+' % {'word': zhon.pinyin.word, 'punctuation': zhon.pinyin.punctuation}
    return _is_pattern_match(re_pattern, s)

def is_ipa(s):
    """Check if *s* consists of valid Chinese IPA."""
    re_pattern = '(?:%(syllable)s|[ \t%(punctuation)s])+' % {'syllable': _IPA_SYLLABLE, 'punctuation': zhon.pinyin.punctuation}
    return _is_pattern_match(re_pattern, s)

def _float_copy_to_out(out, origin):
    """Copy origin to out and return it.

    If ``out`` is None, a new copy (casted to floating point) is used. If
    ``out`` and ``origin`` are the same, we simply return it. Otherwise we
    copy the values."""
    if out is None:
        out = origin / 1
    elif out is not origin:
        np.copyto(out, origin)
    return out

def _af_inv_scaled(x):
    """Scale a random vector for using the affinely invariant measures"""
    x = _transform_to_2d(x)
    cov_matrix = np.atleast_2d(np.cov(x, rowvar=False))
    cov_matrix_power = _mat_sqrt_inv(cov_matrix)
    return x.dot(cov_matrix_power)

def _energy_distance_from_distance_matrices(distance_xx, distance_yy, distance_xy):
    """Compute energy distance with precalculated distance matrices."""
    return 2 * np.mean(distance_xy) - np.mean(distance_xx) - np.mean(distance_yy)

def _distance_correlation_sqr_naive(x, y, exponent=1):
    """Biased distance correlation estimator between two matrices."""
    return _distance_sqr_stats_naive_generic(x, y, matrix_centered=_distance_matrix, product=mean_product, exponent=exponent).correlation_xy

def _u_distance_correlation_sqr_naive(x, y, exponent=1):
    """Bias-corrected distance correlation estimator between two matrices."""
    return _distance_sqr_stats_naive_generic(x, y, matrix_centered=_u_distance_matrix, product=u_product, exponent=exponent).correlation_xy

def _distance_stats_sqr_fast_generic(x, y, dcov_function):
    """Compute the distance stats using the fast algorithm."""
    covariance_xy_sqr = dcov_function(x, y)
    variance_x_sqr = dcov_function(x, x)
    variance_y_sqr = dcov_function(y, y)
    denominator_sqr_signed = variance_x_sqr * variance_y_sqr
    denominator_sqr = np.absolute(denominator_sqr_signed)
    denominator = _sqrt(denominator_sqr)
    if denominator == 0.0:
        correlation_xy_sqr = denominator.dtype.type(0)
    else:
        correlation_xy_sqr = covariance_xy_sqr / denominator
    return Stats(covariance_xy=covariance_xy_sqr, correlation_xy=correlation_xy_sqr, variance_x=variance_x_sqr, variance_y=variance_y_sqr)

def _pairwise_imp(function, x, y=None, pool=None, is_symmetric=None, **kwargs):
    """Real implementation of :func:`pairwise`.

    This function is used to make several parameters keyword-only in
    Python 2."""
    map_function = pool.map if pool else map
    if is_symmetric is None:
        is_symmetric = getattr(function, 'is_symmetric', False)
    pairwise_function = getattr(function, 'pairwise_function', None)
    if pairwise_function:
        return pairwise_function(x, y, pool=pool, is_symmetric=is_symmetric, **kwargs)
    if y is None and is_symmetric:
        partial = functools.partial(_map_aux_func_symmetric, x=x, function=function)
        dependencies = np.array(list(map_function(partial, enumerate(x))))
        for i in range(len(x)):
            for j in range(i, len(x)):
                dependencies[j, i] = dependencies[i, j]
        return dependencies
    else:
        if y is None:
            y = x
        partial = functools.partial(_map_aux_func, y=y, function=function)
        return np.array(list(map_function(partial, x)))

def _sqrt(x):
    """Return square root of an ndarray.

    This sqrt function for ndarrays tries to use the exponentiation operator
    if the objects stored do not supply a sqrt method."""
    x = np.clip(x, a_min=0, a_max=None)
    try:
        return np.sqrt(x)
    except AttributeError:
        exponent = 0.5
        try:
            exponent = np.take(x, 0).from_float(exponent)
        except AttributeError:
            pass
        return x ** exponent

def _can_be_double(x):
    """Return if the array can be safely converted to double.

    That happens when the dtype is a float with the same size of
    a double or narrower, or when is an integer that can be safely
    converted to double (if the roundtrip conversion works)."""
    return np.issubdtype(x.dtype, np.floating) and x.dtype.itemsize <= np.dtype(float).itemsize or (np.issubdtype(x.dtype, np.signedinteger) and np.can_cast(x, float))

def _cdist_naive(x, y, exponent=1):
    """Pairwise distance, custom implementation."""
    squared_norms = ((x[_np.newaxis, :, :] - y[:, _np.newaxis, :]) ** 2).sum(2)
    exponent = exponent / 2
    try:
        exponent = squared_norms.take(0).from_float(exponent)
    except AttributeError:
        pass
    return squared_norms ** exponent

def _pdist_scipy(x, exponent=1):
    """Pairwise distance between points in a set."""
    metric = 'euclidean'
    if exponent != 1:
        metric = 'sqeuclidean'
    distances = _spatial.distance.pdist(x, metric=metric)
    distances = _spatial.distance.squareform(distances)
    if exponent != 1:
        distances **= exponent / 2
    return distances

def _cdist_scipy(x, y, exponent=1):
    """Pairwise distance between the points in two sets."""
    metric = 'euclidean'
    if exponent != 1:
        metric = 'sqeuclidean'
    distances = _spatial.distance.cdist(x, y, metric=metric)
    if exponent != 1:
        distances **= exponent / 2
    return distances

def _pdist(x, exponent=1):
    """Pairwise distance between points in a set.

    As Scipy converts every value to double, this wrapper uses
    a less efficient implementation if the original dtype
    can not be converted to double."""
    if _can_be_double(x):
        return _pdist_scipy(x, exponent)
    else:
        return _cdist_naive(x, x, exponent)

def _cdist(x, y, exponent=1):
    """Pairwise distance between points in two sets.

    As Scipy converts every value to double, this wrapper uses
    a less efficient implementation if the original dtype
    can not be converted to double."""
    if _can_be_double(x) and _can_be_double(y):
        return _cdist_scipy(x, y, exponent)
    else:
        return _cdist_naive(x, y, exponent)

def calculate_mac(mac_type, resource, content_hash):
    """Calculates a message authorization code (MAC)."""
    normalized = normalize_string(mac_type, resource, content_hash)
    log.debug(u'normalized resource for mac calc: {norm}'.format(norm=normalized))
    digestmod = getattr(hashlib, resource.credentials['algorithm'])
    if not isinstance(normalized, six.binary_type):
        normalized = normalized.encode('utf8')
    key = resource.credentials['key']
    if not isinstance(key, six.binary_type):
        key = key.encode('ascii')
    result = hmac.new(key, normalized, digestmod)
    return b64encode(result.digest())

def calculate_ts_mac(ts, credentials):
    """Calculates a message authorization code (MAC) for a timestamp."""
    normalized = 'hawk.{hawk_ver}.ts\n{ts}\n'.format(hawk_ver=HAWK_VER, ts=ts)
    log.debug(u'normalized resource for ts mac calc: {norm}'.format(norm=normalized))
    digestmod = getattr(hashlib, credentials['algorithm'])
    if not isinstance(normalized, six.binary_type):
        normalized = normalized.encode('utf8')
    key = credentials['key']
    if not isinstance(key, six.binary_type):
        key = key.encode('ascii')
    result = hmac.new(key, normalized, digestmod)
    return b64encode(result.digest())

def get_bewit(resource):
    """Returns a bewit identifier for the resource as a string.

    :param resource:
        Resource to generate a bewit for
    :type resource: `mohawk.base.Resource`"""
    if resource.method != 'GET':
        raise ValueError('bewits can only be generated for GET requests')
    if resource.nonce != '':
        raise ValueError('bewits must use an empty nonce')
    mac = calculate_mac('bewit', resource, None)
    if isinstance(mac, six.binary_type):
        mac = mac.decode('ascii')
    if resource.ext is None:
        ext = ''
    else:
        validate_header_attr(resource.ext, name='ext')
        ext = resource.ext
    inner_bewit = u'{id}\\{exp}\\{mac}\\{ext}'.format(id=resource.credentials['id'], exp=resource.timestamp, mac=mac, ext=ext)
    inner_bewit_bytes = inner_bewit.encode('ascii')
    bewit_bytes = urlsafe_b64encode(inner_bewit_bytes)
    return bewit_bytes.decode('ascii')

def jsonapi(f):
    """Declare the view as a JSON API method

    This converts view return value into a :cls:JsonResponse.

    The following return types are supported:
        - tuple: a tuple of (response, status, headers)
        - any other object is converted to JSON"""
    @wraps(f)
    def wrapper(*args, **kwargs):
        rv = f(*args, **kwargs)
        return make_json_response(rv)
    return wrapper

def status(c):
    """Print current release (version, changelog, tag, etc) status.

    Doubles as a subroutine, returning the return values from its inner call to
    ``_converge`` (an ``(actions, state)`` two-tuple of Lexicons)."""
    actions, state = _converge(c)
    table = []
    for component in 'changelog version tag'.split():
        table.append((component.capitalize(), actions[component].value))
    print(tabulate(table))
    return (actions, state)

def prepare(c):
    """Edit changelog & version, git commit, and git tag, to set up for release."""
    actions, state = status(c)
    if not confirm('Take the above actions?'):
        sys.exit('Aborting.')
    if actions.changelog is Changelog.NEEDS_RELEASE:
        cmd = '$EDITOR {0.packaging.changelog_file}'.format(c)
        c.run(cmd, pty=True, hide=False)
    if actions.version == VersionFile.NEEDS_BUMP:
        version_file = os.path.join(_find_package(c), c.packaging.get('version_module', '_version') + '.py')
        cmd = '$EDITOR {0}'.format(version_file)
        c.run(cmd, pty=True, hide=False)
    if actions.tag == Tag.NEEDS_CUTTING:
        cmd = 'git status --porcelain | egrep -v "^\\?"'
        if c.run(cmd, hide=True, warn=True).ok:
            c.run('git commit -am "Cut {0}"'.format(state.expected_version), hide=False)
        c.run('git tag {0}'.format(state.expected_version), hide=False)

def _get_tags(c):
    """Return sorted list of release-style tags as semver objects."""
    tags_ = []
    for tagstr in c.run('git tag', hide=True).stdout.strip().split('\n'):
        try:
            tags_.append(Version(tagstr))
        except ValueError:
            pass
    return sorted(tags_)

def _clean(c):
    """Nuke docs build target directory so next build is clean."""
    if isdir(c.sphinx.target):
        rmtree(c.sphinx.target)

def build(c, clean=False, browse=False, nitpick=False, opts=None, source=None, target=None):
    """Build the project's Sphinx docs."""
    if clean:
        _clean(c)
    if opts is None:
        opts = ''
    if nitpick:
        opts += ' -n -W -T'
    cmd = 'sphinx-build{0} {1} {2}'.format(' ' + opts if opts else '', source or c.sphinx.source, target or c.sphinx.target)
    c.run(cmd, pty=True)
    if browse:
        _browse(c)

def watch_docs(c):
    """Watch both doc trees & rebuild them if files change.

    This includes e.g. rebuilding the API docs if the source code changes;
    rebuilding the WWW docs if the README changes; etc.

    Reuses the configuration values ``packaging.package`` or ``tests.package``
    (the former winning over the latter if both defined) when determining which
    source directory to scan for API doc updates."""
    www_c = Context(config=c.config.clone())
    www_c.update(**www.configuration())
    www_handler = make_handler(ctx=www_c, task_=www['build'], regexes=['\\./README.rst', '\\./sites/www'], ignore_regexes=['.*/\\..*\\.swp', '\\./sites/www/_build'])
    docs_c = Context(config=c.config.clone())
    docs_c.update(**docs.configuration())
    regexes = ['\\./sites/docs']
    package = c.get('packaging', {}).get('package', None)
    if package is None:
        package = c.get('tests', {}).get('package', None)
    if package:
        regexes.append('\\./{}/'.format(package))
    api_handler = make_handler(ctx=docs_c, task_=docs['build'], regexes=regexes, ignore_regexes=['.*/\\..*\\.swp', '\\./sites/docs/_build'])
    observe(www_handler, api_handler)

def normalize_response_value(rv):
    """Normalize the response value into a 3-tuple (rv, status, headers)
    :type rv: tuple|*
    :returns: tuple(rv, status, headers)
    :rtype: tuple(Response|JsonResponse|*, int|None, dict|None)"""
    status = headers = None
    if isinstance(rv, tuple):
        rv, status, headers = rv + (None,) * (3 - len(rv))
    return (rv, status, headers)

def _check_encoding(name, encoding_to_check, alternative_encoding, source=None):
    """Check that ``encoding`` is a valid Python encoding
    :param name: name under which the encoding is known to the user, e.g. 'default encoding'
    :param encoding_to_check: name of the encoding to check, e.g. 'utf-8'
    :param source: source where the encoding has been set, e.g. option name
    :raise pygount.common.OptionError if ``encoding`` is not a valid Python encoding"""
    assert name is not None
    if encoding_to_check not in (alternative_encoding, 'chardet', None):
        try:
            ''.encode(encoding_to_check)
        except LookupError:
            raise pygount.common.OptionError('{0} is "{1}" but must be "{2}" or a known Python encoding'.format(name, encoding_to_check, alternative_encoding), source)

def subprogram_prototype(vo):
    """Generate a canonical prototype string

    Args:
      vo (VhdlFunction, VhdlProcedure): Subprogram object
    Returns:
      Prototype string."""
    plist = '; '.join((str(p) for p in vo.parameters))
    if isinstance(vo, VhdlFunction):
        if len(vo.parameters) > 0:
            proto = 'function {}({}) return {};'.format(vo.name, plist, vo.return_type)
        else:
            proto = 'function {} return {};'.format(vo.name, vo.return_type)
    else:
        proto = 'procedure {}({});'.format(vo.name, plist)
    return proto

def get_package_version(verfile):
    """Scan the script for the version string"""
    version = None
    with open(verfile) as fh:
        try:
            version = [line.split('=')[1].strip().strip("'") for line in fh if line.startswith('__version__')][0]
        except IndexError:
            pass
