    return _parse_urban_json(json)

def has_external_dependency(name):
    """Check that a non-Python dependency is installed."""
    for directory in os.environ['PATH'].split(':'):
        if os.path.exists(os.path.join(directory, name)):
            return True
    return False

def execute(query, data=None):
    """Execute an arbitrary SQL query given by query, returning any
    results as a list of OrderedDicts. A list of values can be supplied as an,
    additional argument, which will be substituted into question marks in the
    query."""
    connection = _State.connection()
    _State.new_transaction()
    if data is None:
        data = []
    result = connection.execute(query, data)
    _State.table = None
    _State.metadata = None
    try:
        del _State.table_pending
    except AttributeError:
        pass
    if not result.returns_rows:
        return {u'data': [], u'keys': []}
    return {u'data': result.fetchall(), u'keys': list(result.keys())}

def _set_table(table_name):
    """Specify the table to work on."""
    _State.connection()
    _State.reflect_metadata()
    _State.table = sqlalchemy.Table(table_name, _State.metadata, extend_existing=True)
    if list(_State.table.columns.keys()) == []:
        _State.table_pending = True
    else:
        _State.table_pending = False

def fit_row(connection, row, unique_keys):
    """Takes a row and checks to make sure it fits in the columns of the
    current table. If it does not fit, adds the required columns."""
    new_columns = []
    for column_name, column_value in list(row.items()):
        new_column = sqlalchemy.Column(column_name, get_column_type(column_value))
        if not column_name in list(_State.table.columns.keys()):
            new_columns.append(new_column)
            _State.table.append_column(new_column)
    if _State.table_pending:
        create_table(unique_keys)
        return
    for new_column in new_columns:
        add_column(connection, new_column)

def pstats2entries(data):
    """Helper to convert serialized pstats back to a list of raw entries.

    Converse operation of cProfile.Profile.snapshot_stats()"""
    entries = {}
    allcallers = {}
    for code_info, call_info in data.stats.items():
        code = Code(*code_info)
        cc, nc, tt, ct, callers = call_info
        entry = Entry(code, callcount=cc, reccallcount=nc - cc, inlinetime=tt, totaltime=ct, calls=[])
        entries[code_info] = entry
        allcallers[code_info] = list(callers.items())
    for entry in entries.values():
        entry_label = cProfile.label(entry.code)
        entry_callers = allcallers.get(entry_label, [])
        for entry_caller, call_info in entry_callers:
            cc, nc, tt, ct = call_info
            subentry = Subentry(entry.code, callcount=cc, reccallcount=nc - cc, inlinetime=tt, totaltime=ct)
            entries[entry_caller].calls.append(subentry)
    return list(entries.values())

def is_installed(prog):
    """Return whether or not a given executable is installed on the machine."""
    with open(os.devnull, 'w') as devnull:
        try:
            if os.name == 'nt':
                retcode = subprocess.call(['where', prog], stdout=devnull)
            else:
                retcode = subprocess.call(['which', prog], stdout=devnull)
        except OSError as e:
            if e.errno != errno.ENOENT:
                raise
            retcode = 1
    return retcode == 0

def _layer_to_path_gen(layer):
    """Generates an SVG path from a given layer.

    Args:
        layer (layer): the layer to convert

    Yields:
        str: the next component of the path"""
    draw = False
    for x, y in zip(*layer):
        if np.isnan(x) or np.isnan(y):
            draw = False
        elif not draw:
            yield 'M {} {}'.format(x, y)
            draw = True
        else:
            yield 'L {} {}'.format(x, y)

def format_timestamp(ts):
    """Format the UTC timestamp for Elasticsearch
    eg. 2014-07-09T08:37:18.000Z
    @see https://docs.python.org/2/library/time.html#time.strftime"""
    tz_info = tz.tzutc()
    return datetime.fromtimestamp(ts, tz=tz_info).strftime('%Y-%m-%dT%H:%M:%S.000Z')

def fetch(url, binary, outfile, noprint, rendered):
    """Fetch a specified URL's content, and output it to the console."""
    with chrome_context.ChromeContext(binary=binary) as cr:
        resp = cr.blocking_navigate_and_get_source(url)
        if rendered:
            resp['content'] = cr.get_rendered_page_source()
            resp['binary'] = False
            resp['mimie'] = 'text/html'
    if not noprint:
        if resp['binary'] is False:
            print(resp['content'])
        else:
            print('Response is a binary file')
            print('Cannot print!')
    if outfile:
        with open(outfile, 'wb') as fp:
            if resp['binary']:
                fp.write(resp['content'])
            else:
                fp.write(resp['content'].encode('UTF-8'))

def on_parent_exit(signame):
    """Return a function to be run in a child process which will trigger SIGNAME
    to be sent when the parent process dies"""
    signum = getattr(signal, signame)
    def set_parent_exit_signal():
        result = cdll['libc.so.6'].prctl(PR_SET_PDEATHSIG, signum)
        if result != 0:
            raise PrCtlError('prctl failed with error code %s' % result)
    return set_parent_exit_signal

def resetLoggingLocks():
    """This function is a HACK!

    Basically, if we fork() while a logging lock is held, the lock
    is /copied/ while in the acquired state. However, since we've
    forked, the thread that acquired the lock no longer exists,
    so it can never unlock the lock, and we end up blocking
    forever.

    Therefore, we manually enter the logging module, and forcefully
    release all the locks it holds.

    THIS IS NOT SAFE (or thread-safe).
    Basically, it MUST be called right after a process
    starts, and no where else."""
    try:
        logging._releaseLock()
    except RuntimeError:
        pass
    for handler in logging.Logger.manager.loggerDict.values():
        if hasattr(handler, 'lock') and handler.lock:
            try:
                handler.lock.release()
            except RuntimeError:
                pass

def requires_private_key(func):
    """Decorator for functions that require the private key to be defined."""
    def func_wrapper(self, *args, **kwargs):
        if hasattr(self, '_DiffieHellman__private_key'):
            func(self, *args, **kwargs)
        else:
            self.generate_private_key()
            func(self, *args, **kwargs)
    return func_wrapper

def requires_public_key(func):
    """Decorator for functions that require the public key to be defined. By definition, this includes the private key, as such, it's enough to use this to effect definition of both public and private key."""
    def func_wrapper(self, *args, **kwargs):
        if hasattr(self, 'public_key'):
            func(self, *args, **kwargs)
        else:
            self.generate_public_key()
            func(self, *args, **kwargs)
    return func_wrapper

def write_files(args, infilenames, outfilename):
    """Write scraped or local file(s) in desired format.

    Keyword arguments:
    args -- program arguments (dict)
    infilenames -- names of user-inputted and/or downloaded files (list)
    outfilename -- name of output file (str)

    Remove PART(#).html files after conversion unless otherwise specified."""
    write_actions = {'print': utils.print_text, 'pdf': utils.write_pdf_files, 'csv': utils.write_csv_files, 'text': utils.write_text_files}
    try:
        for action in iterkeys(write_actions):
            if args[action]:
                write_actions[action](args, infilenames, outfilename)
    finally:
        if args['urls'] and (not args['html']):
            utils.remove_part_files()

def write_single_file(args, base_dir, crawler):
    """Write to a single output file and/or subdirectory."""
    if args['urls'] and args['html']:
        domain = utils.get_domain(args['urls'][0])
        if not args['quiet']:
            print('Storing html files in {0}/'.format(domain))
        utils.mkdir_and_cd(domain)
    infilenames = []
    for query in args['query']:
        if query in args['files']:
            infilenames.append(query)
        elif query.strip('/') in args['urls']:
            if args['crawl'] or args['crawl_all']:
                infilenames += crawler.crawl_links(query)
            else:
                raw_resp = utils.get_raw_resp(query)
                if raw_resp is None:
                    return False
                prev_part_num = utils.get_num_part_files()
                utils.write_part_file(args, query, raw_resp)
                curr_part_num = prev_part_num + 1
                infilenames += utils.get_part_filenames(curr_part_num, prev_part_num)
    if args['html']:
        os.chdir(base_dir)
    elif infilenames:
        if args['out']:
            outfilename = args['out'][0]
        else:
            outfilename = utils.get_single_outfilename(args)
        if outfilename:
            write_files(args, infilenames, outfilename)
    else:
        utils.remove_part_files()
    return True

def split_input(args):
    """Split query input into local files and URLs."""
    args['files'] = []
    args['urls'] = []
    for arg in args['query']:
        if os.path.isfile(arg):
            args['files'].append(arg)
        else:
            args['urls'].append(arg.strip('/'))

def detect_output_type(args):
    """Detect whether to save to a single or multiple files."""
    if not args['single'] and (not args['multiple']):
        if len(args['query']) > 1 or len(args['out']) > 1:
            args['multiple'] = True
        else:
            args['single'] = True

def scrape(args):
    """Scrape webpage content."""
    try:
        base_dir = os.getcwd()
        if args['out'] is None:
            args['out'] = []
        detect_output_type(args)
        split_input(args)
        if args['urls']:
            urls_with_exts = [utils.add_url_suffix(x) for x in args['urls']]
            args['query'] = [utils.add_protocol(x) if x in args['urls'] else x for x in urls_with_exts]
            args['urls'] = [x for x in args['query'] if x not in args['files']]
        if args['files'] and args['html']:
            sys.stderr.write('Cannot convert local files to HTML.\n')
            args['files'] = []
        crawler = None
        if args['crawl'] or args['crawl_all']:
            crawler = Crawler(args)
        if args['single']:
            return write_single_file(args, base_dir, crawler)
        elif args['multiple']:
            return write_multiple_files(args, base_dir, crawler)
    except (KeyboardInterrupt, Exception):
        if args['html']:
            try:
                os.chdir(base_dir)
            except OSError:
                pass
        else:
            utils.remove_part_files()
        raise

def prompt_filetype(args):
    """Prompt user for filetype if none specified."""
    valid_types = ('print', 'text', 'csv', 'pdf', 'html')
    if not any((args[x] for x in valid_types)):
        try:
            filetype = input('Print or save output as ({0}): '.format(', '.join(valid_types))).lower()
            while filetype not in valid_types:
                filetype = input('Invalid entry. Choose from ({0}): '.format(', '.join(valid_types))).lower()
        except (KeyboardInterrupt, EOFError):
            return
        args[filetype] = True

def prompt_save_images(args):
    """Prompt user to save images when crawling (for pdf and HTML formats)."""
    if args['images'] or args['no_images']:
        return
    if (args['pdf'] or args['html']) and (args['crawl'] or args['crawl_all']):
        save_msg = 'Choosing to save images will greatly slow the crawling process.\nSave images anyways? (y/n): '
        try:
            save_images = utils.confirm_input(input(save_msg))
        except (KeyboardInterrupt, EOFError):
            return
        args['images'] = save_images
        args['no_images'] = not save_images

def get_proxies():
    """Get available proxies to use with requests library."""
    proxies = getproxies()
    filtered_proxies = {}
    for key, value in proxies.items():
        if key.startswith('http://'):
            if not value.startswith('http://'):
                filtered_proxies[key] = 'http://{0}'.format(value)
            else:
                filtered_proxies[key] = value
    return filtered_proxies

def get_resp(url):
    """Get webpage response as an lxml.html.HtmlElement object."""
    try:
        headers = {'User-Agent': random.choice(USER_AGENTS)}
        try:
            request = requests.get(url, headers=headers, proxies=get_proxies())
        except MissingSchema:
            url = add_protocol(url)
            request = requests.get(url, headers=headers, proxies=get_proxies())
        return lh.fromstring(request.text.encode('utf-8') if PY2 else request.text)
    except Exception:
        sys.stderr.write('Failed to retrieve {0}.\n'.format(url))
        raise

def enable_cache():
    """Enable requests library cache."""
    try:
        import requests_cache
    except ImportError as err:
        sys.stderr.write('Failed to enable cache: {0}\n'.format(str(err)))
        return
    if not os.path.exists(CACHE_DIR):
        os.makedirs(CACHE_DIR)
    requests_cache.install_cache(CACHE_FILE)

def hash_text(text):
    """Return MD5 hash of a string."""
    md5 = hashlib.md5()
    md5.update(text)
    return md5.hexdigest()

def cache_page(page_cache, page_hash, cache_size):
    """Add a page to the page cache."""
    page_cache.append(page_hash)
    if len(page_cache) > cache_size:
        page_cache.pop(0)

def re_filter(text, regexps):
    """Filter text using regular expressions."""
    if not regexps:
        return text
    matched_text = []
    compiled_regexps = [re.compile(x) for x in regexps]
    for line in text:
        if line in matched_text:
            continue
        for regexp in compiled_regexps:
            found = regexp.search(line)
            if found and found.group():
                matched_text.append(line)
    return matched_text or text

def remove_whitespace(text):
    """Remove unnecessary whitespace while keeping logical structure.

    Keyword arguments:
    text -- text to remove whitespace from (list)

    Retain paragraph structure but remove other whitespace,
    such as between words on a line and at the start and end of the text."""
    clean_text = []
    curr_line = ''
    while text:
        if not curr_line:
            curr_line = text.pop(0)
            while not curr_line.strip() and text:
                curr_line = text.pop(0)
            if curr_line.strip():
                clean_text.append(curr_line)
        else:
            curr_line = text.pop(0)
            if not text:
                if curr_line.strip():
                    clean_text.append(curr_line)
                continue
            if curr_line.strip():
                clean_text.append(curr_line)
            elif not text[0].strip():
                if len(text) > 1 and text[1].strip():
                    clean_text.append(curr_line)
            else:
                clean_text.append(curr_line)
    cleaner_text = []
    for line in clean_text:
        clean_line = ' '.join(line.split())
        if not clean_line.strip():
            clean_line += '\n'
        cleaner_text.append(clean_line)
    return cleaner_text

def get_parsed_text(args, infilename):
    """Parse and return text content of infiles.

    Keyword arguments:
    args -- program arguments (dict)
    infilenames -- name of user-inputted and/or downloaded file (str)

    Return a list of strings of text."""
    parsed_text = []
    if infilename.endswith('.html'):
        html = lh.fromstring(read_files(infilename))
        text = None
    else:
        html = None
        text = read_files(infilename)
    if html is not None:
        parsed_text = parse_text(html, args['xpath'], args['filter'], args['attributes'])
    elif text is not None:
        parsed_text = parse_text(text, args['xpath'], args['filter'])
    elif not args['quiet']:
        sys.stderr.write('Failed to parse text from {0}.\n'.format(infilename))
    return parsed_text

def parse_html(infile, xpath):
    """Filter HTML using XPath."""
    if not isinstance(infile, lh.HtmlElement):
        infile = lh.fromstring(infile)
    infile = infile.xpath(xpath)
    if not infile:
        raise ValueError('XPath {0} returned no results.'.format(xpath))
    return infile

def clean_url(url, base_url=None):
    """Add base netloc and path to internal URLs and remove www, fragments."""
    parsed_url = urlparse(url)
    fragment = '{url.fragment}'.format(url=parsed_url)
    if fragment:
        url = url.split(fragment)[0]
    netloc = '{url.netloc}'.format(url=parsed_url)
    if base_url is not None and (not netloc):
        parsed_base = urlparse(base_url)
        split_base = '{url.scheme}://{url.netloc}{url.path}/'.format(url=parsed_base)
        url = urljoin(split_base, url)
        netloc = '{url.netloc}'.format(url=urlparse(url))
    if 'www.' in netloc:
        url = url.replace(netloc, netloc.replace('www.', ''))
    return url.rstrip(string.punctuation)

def add_url_suffix(url):
    """Add .com suffix to URL if none found."""
    url = url.rstrip('/')
    if not has_suffix(url):
        return '{0}.com'.format(url)
    return url

def get_outfilename(url, domain=None):
    """Construct the output filename from domain and end of path."""
    if domain is None:
        domain = get_domain(url)
    path = '{url.path}'.format(url=urlparse(url))
    if '.' in path:
        tail_url = path.split('.')[-2]
    else:
        tail_url = path
    if tail_url:
        if '/' in tail_url:
            tail_pieces = [x for x in tail_url.split('/') if x]
            tail_url = tail_pieces[-1]
        max_len = 24
        if domain:
            max_len -= len(domain) + 1
        if len(tail_url) > max_len:
            if '-' in tail_url:
                tail_pieces = [x for x in tail_url.split('-') if x]
                tail_url = tail_pieces.pop(0)
                if len(tail_url) > max_len:
                    tail_url = tail_url[:max_len]
                else:
                    tail_len = 0
                    for piece in tail_pieces:
                        tail_len += len(piece)
                        if tail_len <= max_len:
                            tail_url += '-' + piece
                        else:
                            break
            else:
                tail_url = tail_url[:max_len]
        if domain:
            return '{0}-{1}'.format(domain, tail_url).lower()
        return tail_url
    return domain.lower()

def get_single_outfilename(args):
    """Use first possible entry in query as filename."""
    for arg in args['query']:
        if arg in args['files']:
            return '.'.join(arg.split('.')[:-1]).lower()
        for url in args['urls']:
            if arg.strip('/') in url:
                domain = get_domain(url)
                return get_outfilename(url, domain)
    sys.stderr.write('Failed to construct a single out filename.\n')
    return ''

def overwrite_file_check(args, filename):
    """If filename exists, overwrite or modify it to be unique."""
    if not args['overwrite'] and os.path.exists(filename):
        if args['no_overwrite']:
            overwrite = False
        else:
            try:
                overwrite = confirm_input(input('Overwrite {0}? (yes/no): '.format(filename)))
            except (KeyboardInterrupt, EOFError):
                sys.exit()
        if not overwrite:
            new_filename = modify_filename_id(filename)
            while os.path.exists(new_filename):
                new_filename = modify_filename_id(new_filename)
            return new_filename
    return filename

def print_text(args, infilenames, outfilename=None):
    """Print text content of infiles to stdout.

    Keyword arguments:
    args -- program arguments (dict)
    infilenames -- names of user-inputted and/or downloaded files (list)
    outfilename -- only used for interface purposes (None)"""
    for infilename in infilenames:
        parsed_text = get_parsed_text(args, infilename)
        if parsed_text:
            for line in parsed_text:
                print(line)
            print('')

def write_text_files(args, infilenames, outfilename):
    """Write text file(s) to disk.

    Keyword arguments:
    args -- program arguments (dict)
    infilenames -- names of user-inputted and/or downloaded files (list)
    outfilename -- name of output text file (str)"""
    if not outfilename.endswith('.txt'):
        outfilename = outfilename + '.txt'
    outfilename = overwrite_file_check(args, outfilename)
    all_text = []
    for i, infilename in enumerate(infilenames):
        parsed_text = get_parsed_text(args, infilename)
        if parsed_text:
            if args['multiple']:
                if not args['quiet']:
                    print('Attempting to write to {0}.'.format(outfilename))
                write_file(parsed_text, outfilename)
            elif args['single']:
                all_text += parsed_text
                if len(infilenames) > 1 and i < len(infilenames) - 1:
                    all_text.append('\n')
    if args['single'] and all_text:
        if not args['quiet']:
            print('Attempting to write {0} page(s) to {1}.'.format(len(infilenames), outfilename))
        write_file(all_text, outfilename)

def write_file(data, outfilename):
    """Write a single file to disk."""
    if not data:
        return False
    try:
        with open(outfilename, 'w') as outfile:
            for line in data:
                if line:
                    outfile.write(line)
        return True
    except (OSError, IOError) as err:
        sys.stderr.write('An error occurred while writing {0}:\n{1}'.format(outfilename, str(err)))
        return False

def get_num_part_files():
    """Get the number of PART.html files currently saved to disk."""
    num_parts = 0
    for filename in os.listdir(os.getcwd()):
        if filename.startswith('PART') and filename.endswith('.html'):
            num_parts += 1
    return num_parts

def get_part_filenames(num_parts=None, start_num=0):
    """Get numbered PART.html filenames."""
    if num_parts is None:
        num_parts = get_num_part_files()
    return ['PART{0}.html'.format(i) for i in range(start_num + 1, num_parts + 1)]

def read_files(filenames):
    """Read a file into memory."""
    if isinstance(filenames, list):
        for filename in filenames:
            with open(filename, 'r') as infile:
                return infile.read()
    else:
        with open(filenames, 'r') as infile:
            return infile.read()

def remove_part_images(filename):
    """Remove PART(#)_files directory containing images from disk."""
    dirname = '{0}_files'.format(os.path.splitext(filename)[0])
    if os.path.exists(dirname):
        shutil.rmtree(dirname)

def remove_part_files(num_parts=None):
    """Remove PART(#).html files and image directories from disk."""
    filenames = get_part_filenames(num_parts)
    for filename in filenames:
        remove_part_images(filename)
        remove_file(filename)

def confirm_input(user_input):
    """Check user input for yes, no, or an exit signal."""
    if isinstance(user_input, list):
        user_input = ''.join(user_input)
    try:
        u_inp = user_input.lower().strip()
    except AttributeError:
        u_inp = user_input
    if u_inp in ('q', 'quit', 'exit'):
        sys.exit()
    if u_inp in ('y', 'yes'):
        return True
    return False

def mkdir_and_cd(dirname):
    """Change directory and/or create it if necessary."""
    if not os.path.exists(dirname):
        os.makedirs(dirname)
        os.chdir(dirname)
    else:
        os.chdir(dirname)

def generate(data, format='auto'):
    """Converts input chemical formats to json and optimizes structure.

    Args:
        data: A string or file representing a chemical
        format: The format of the `data` variable (default is 'auto')

    The `format` can be any value specified by Open Babel
    (http://openbabel.org/docs/2.3.1/FileFormats/Overview.html). The 'auto'
    option uses the extension for files (ie. my_file.mol -> mol) and defaults
    to SMILES (smi) for strings."""
    try:
        with open(data) as in_file:
            if format == 'auto':
                format = data.split('.')[-1]
            data = in_file.read()
    except:
        if format == 'auto':
            format = 'smi'
    return format_converter.convert(data, format, 'json')

def to_json(data, compress=False):
    """Converts the output of `generate(...)` to formatted json.

    Floats are rounded to three decimals and positional vectors are printed on
    one line with some whitespace buffer."""
    return json.compress(data) if compress else json.dumps(data)

def nearly_eq(valA, valB, maxf=None, minf=None, epsilon=None):
    """implementation based on:

    http://floating-point-gui.de/errors/comparison/"""
    if valA == valB:
        return True
    if maxf is None:
        maxf = float_info.max
    if minf is None:
        minf = float_info.min
    if epsilon is None:
        epsilon = float_info.epsilon
    absA = abs(valA)
    absB = abs(valB)
    delta = abs(valA - valB)
    if valA == 0 or valB == 0 or delta < minf:
        return delta < epsilon * minf
    return delta / min(absA + absB, maxf) < epsilon * 2

def download(url, localFileName=None, localDirName=None):
    """Utility function for downloading files from the web
    and retaining the same filename."""
    localName = url2name(url)
    req = Request(url)
    r = urlopen(req)
    if r.info().has_key('Content-Disposition'):
        localName = r.info()['Content-Disposition'].split('filename=')
        if len(localName) > 1:
            localName = localName[1]
            if localName[0] == '"' or localName[0] == "'":
                localName = localName[1:-1]
        else:
            localName = url2name(r.url)
    elif r.url != url:
        localName = url2name(r.url)
    if localFileName:
        localName = localFileName
    if localDirName:
        if not os.path.exists(localDirName):
            os.makedirs(localDirName)
        localName = os.path.join(localDirName, localName)
    f = open(localName, 'wb')
    f.write(r.read())
    f.close()

def _t(unistr, charset_from, charset_to):
    """This is a unexposed function, is responsibility for translation internal."""
    chars = []
    for c in unistr:
        idx = charset_from.find(c)
        chars.append(charset_to[idx] if idx != -1 else c)
    return u''.join(chars)

def identify(text):
    """Identify whether a string is simplified or traditional Chinese.

    Returns:
        None: if there are no recognizd Chinese characters.
        EITHER: if the test is inconclusive.
        TRAD: if the text is traditional.
        SIMP: if the text is simplified.
        BOTH: the text has characters recognized as being solely traditional
            and other characters recognized as being solely simplified."""
    filtered_text = set(list(text)).intersection(ALL_CHARS)
    if len(filtered_text) is 0:
        return None
    if filtered_text.issubset(SHARED_CHARS):
        return EITHER
    if filtered_text.issubset(TRAD_CHARS):
        return TRAD
    if filtered_text.issubset(SIMP_CHARS):
        return SIMP
    if filtered_text.difference(TRAD_CHARS).issubset(SIMP_CHARS):
        return BOTH

def makeSequenceRelative(absVSequence):
    """Puts every value in a list on a continuum between 0 and 1

    Also returns the min and max values (to reverse the process)"""
    if len(absVSequence) < 2 or len(set(absVSequence)) == 1:
        raise RelativizeSequenceException(absVSequence)
    minV = min(absVSequence)
    maxV = max(absVSequence)
    relativeSeq = [(value - minV) / (maxV - minV) for value in absVSequence]
    return (relativeSeq, minV, maxV)

def makeSequenceAbsolute(relVSequence, minV, maxV):
    """Makes every value in a sequence absolute"""
    return [value * (maxV - minV) + minV for value in relVSequence]

