def is_excluded(root, excludes):
    """Check if the directory is in the exclude list.

    Note: by having trailing slashes, we avoid common prefix issues, like
          e.g. an exlude "foo" also accidentally excluding "foobar"."""
    root = os.path.normpath(root)
    for exclude in excludes:
        if root == exclude:
            return True
    return False

def _isclose(obja, objb, rtol=1e-05, atol=1e-08):
    """Return floating point equality."""
    return abs(obja - objb) <= atol + rtol * abs(objb)

def _isreal(obj):
    """Determine if an object is a real number.

    Both Python standard data types and Numpy data types are supported.

    :param obj: Object
    :type  obj: any

    :rtype: boolean"""
    if obj is None or isinstance(obj, bool):
        return False
    try:
        cond = int(obj) == obj or float(obj) == obj
    except:
        return False
    return cond

def _no_exp(number):
    """Convert a number to a string without using scientific notation.

    :param number: Number to convert
    :type  number: integer or float

    :rtype: string

    :raises: RuntimeError (Argument \\`number\\` is not valid)"""
    if isinstance(number, bool) or not isinstance(number, (int, float)):
        raise RuntimeError('Argument `number` is not valid')
    mant, exp = _to_scientific_tuple(number)
    if not exp:
        return str(number)
    floating_mant = '.' in mant
    mant = mant.replace('.', '')
    if exp < 0:
        return '0.' + '0' * (-exp - 1) + mant
    if not floating_mant:
        return mant + '0' * exp + ('.0' if isinstance(number, float) else '')
    lfpart = len(mant) - 1
    if lfpart < exp:
        return (mant + '0' * (exp - lfpart)).rstrip('.')
    return mant

def pop_first_arg(argv):
    """find first positional arg (does not start with -), take it out of array and return it separately
    returns (arg, array)"""
    for arg in argv:
        if not arg.startswith('-'):
            argv.remove(arg)
            return (arg, argv)
    return (None, argv)

def _ex_type_str(exobj):
    """Return a string corresponding to the exception type."""
    regexp = re.compile("<(?:\\bclass\\b|\\btype\\b)\\s+'?([\\w|\\.]+)'?>")
    exc_type = str(exobj)
    if regexp.match(exc_type):
        exc_type = regexp.match(exc_type).groups()[0]
        exc_type = exc_type[11:] if exc_type.startswith('exceptions.') else exc_type
    if '.' in exc_type:
        exc_type = exc_type.split('.')[-1]
    return exc_type

def _unicode_to_ascii(obj):
    """Convert to ASCII."""
    if isinstance(obj, dict):
        return dict([(_unicode_to_ascii(key), _unicode_to_ascii(value)) for key, value in obj.items()])
    if isinstance(obj, list):
        return [_unicode_to_ascii(element) for element in obj]
    if isinstance(obj, unicode):
        return obj.encode('utf-8')
    return obj

def query_yes_no(question, default='yes'):
    """Ask a yes/no question via raw_input() and return their answer.
    "question" is a string that is presented to the user.
    "default" is the presumed answer if the user just hits <Enter>.
        It must be "yes" (the default), "no" or None (meaning
        an answer is required of the user).
    The "answer" return value is True for "yes" or False for "no"."""
    valid = {'yes': True, 'y': True, 'ye': True, 'no': False, 'n': False}
    if default is None:
        prompt = ' [y/n] '
    elif default == 'yes':
        prompt = ' [Y/n] '
    elif default == 'no':
        prompt = ' [y/N] '
    else:
        raise ValueError("invalid default answer: '%s'" % default)
    while True:
        print(question + prompt)
        choice = input().lower()
        if default is not None and choice == '':
            return valid[default]
        elif choice in valid:
            return valid[choice]
        else:
            print("Please respond with 'yes' or 'no' (or 'y' or 'n').\n")

def _blast(bvname2vals, name_map):
    """Helper function to expand (blast) str -> int map into str ->
    bool map. This is used to send word level inputs to aiger."""
    if len(name_map) == 0:
        return dict()
    return fn.merge(*(dict(zip(names, bvname2vals[bvname])) for bvname, names in name_map))

def _unblast(name2vals, name_map):
    """Helper function to lift str -> bool maps used by aiger
    to the word level. Dual of the `_blast` function."""
    def _collect(names):
        return tuple((name2vals[n] for n in names))
    return {bvname: _collect(names) for bvname, names in name_map}

