def print_full_name(*args, **kwargs):
    """Decorator, print the full name of the decorated function.

    May be invoked as a simple, argument-less decorator (i.e. ``@print_doc1``)
    or with named arguments ``color``, ``bold``, or ``prefix``
    (eg. ``@print_doc1(color=utils.red, bold=True, prefix=' ')``)."""
    color = kwargs.get('color', default_color)
    bold = kwargs.get('bold', False)
    prefix = kwargs.get('prefix', '')
    tail = kwargs.get('tail', '')
    def real_decorator(func):
        """real decorator function"""
        @wraps(func)
        def wrapper(*args, **kwargs):
            """the wrapper function"""
            first_line = ''
            try:
                first_line = func.__module__ + '.' + func.__qualname__
            except AttributeError as exc:
                first_line = func.__name__
            print(color(prefix + first_line + tail, bold))
            return func(*args, **kwargs)
        return wrapper
    invoked = bool(not args or kwargs)
    if not invoked:
        return real_decorator(func=args[0])
    return real_decorator

def update_or_append_line(filename, prefix, new_line, keep_backup=True, append=True):
    """Search in file 'filename' for a line starting with 'prefix' and replace
    the line by 'new_line'.

    If a line starting with 'prefix' not exists 'new_line' will be appended.
    If the file not exists, it will be created.

    Return False if new_line was appended, else True (i.e. if the prefix was
    found within of the file)."""
    same_line_exists, line_updated = (False, False)
    filename = os.path.expanduser(filename)
    if os.path.isfile(filename):
        backup = filename + '~'
        shutil.move(filename, backup)
        with open(filename, 'w') as dest:
            with open(backup, 'r') as source:
                for line in source:
                    if line == new_line:
                        same_line_exists = True
                    if line.startswith(prefix):
                        dest.write(new_line + '\n')
                        line_updated = True
                    else:
                        dest.write(line)
                if not (same_line_exists or line_updated) and append:
                    dest.write(new_line + '\n')
        if not keep_backup:
            os.remove(backup)
    else:
        with open(filename, 'w') as dest:
            dest.write(new_line + '\n')
    return same_line_exists or line_updated

def uncomment_or_update_or_append_line(filename, prefix, new_line, comment='#', keep_backup=True, update_or_append_line=update_or_append_line):
    """Remove the comment of an commented out line and make the line "active".

    If such an commented out line not exists it would be appended."""
    uncommented = update_or_append_line(filename, prefix=comment + prefix, new_line=new_line, keep_backup=keep_backup, append=False)
    if not uncommented:
        update_or_append_line(filename, prefix, new_line, keep_backup=keep_backup, append=True)

def convert_unicode_2_utf8(input):
    """Return a copy of `input` with every str component encoded from unicode to
    utf-8."""
    if isinstance(input, dict):
        try:
            return dict(((convert_unicode_2_utf8(key), convert_unicode_2_utf8(value)) for key, value in input.iteritems()))
        except AttributeError:
            return eval('{convert_unicode_2_utf8(key): convert_unicode_2_utf8(value)\n                           for key, value\n                           in input.items()}')
    elif isinstance(input, list):
        return [convert_unicode_2_utf8(element) for element in input]
    elif isinstance(input, str):
        return input
    else:
        try:
            if eval('isinstance(input, unicode)'):
                return input.encode('utf-8')
        except NameError:
            pass
        return input

def write_json(data, filename, gzip_mode=False):
    """Write the python data structure as a json-Object to filename."""
    open_file = open
    if gzip_mode:
        open_file = gzip.open
    try:
        with open_file(filename, 'wt') as fh:
            json.dump(obj=data, fp=fh, sort_keys=True)
    except AttributeError:
        fh = open_file(filename, 'wt')
        json.dump(obj=data, fp=fh, sort_keys=True)
        fh.close()

def text_with_newlines(text, line_length=78, newline='\n'):
    """Return text with a `newline` inserted after each `line_length` char.

    Return `text` unchanged if line_length == 0."""
    if line_length > 0:
        if len(text) <= line_length:
            return text
        else:
            return newline.join([text[idx:idx + line_length] for idx in range(0, len(text), line_length)])
    else:
        return text

def _readlines(fname, fpointer1=open, fpointer2=open):
    """Read all lines from file."""
    try:
        with fpointer1(fname, 'r') as fobj:
            return fobj.readlines()
    except UnicodeDecodeError:
        with fpointer2(fname, 'r', encoding='utf-8') as fobj:
            return fobj.readlines()

def calc_piece_size(size, min_piece_size=20, max_piece_size=29, max_piece_count=1000):
    """Calculates a good piece size for a size"""
    logger.debug('Calculating piece size for %i' % size)
    for i in range(min_piece_size, max_piece_size):
        if size / 2 ** i < max_piece_count:
            break
    return 2 ** i

def split_pieces(piece_list, segments, num):
    """Prepare a list of all pieces grouped together"""
    piece_groups = []
    pieces = list(piece_list)
    while pieces:
        for i in range(segments):
            p = pieces[i::segments][:num]
            if not p:
                break
            piece_groups.append(p)
        pieces = pieces[num * segments:]
    return piece_groups

def wait_all(futures, timeout=None):
    """Wait for the completion of all futures in a list

    :param list future: a list of :class:`Future`\\s
    :param timeout:
        The maximum time to wait. With ``None``, can block indefinitely.
    :type timeout: float or None

    :raises WaitTimeout: if a timeout is provided and hit"""
    if timeout is not None:
        deadline = time.time() + timeout
        for fut in futures:
            fut.wait(deadline - time.time())
    else:
        for fut in futures:
            fut.wait()

def _clean_tag(t):
    """Fix up some garbage errors."""
    t = _scored_patt.sub(string=t, repl='')
    if t == '_country_' or t.startswith('_country:'):
        t = 'nnp_country'
    elif t == 'vpb':
        t = 'vb'
    elif t == 'nnd':
        t = 'nns'
    elif t == 'nns_root:':
        t = 'nns'
    elif t == 'root:zygote':
        t = 'nn'
    elif t.startswith('root:'):
        t = 'uh'
    elif t in ('abbr_united_states_marine_corps', 'abbr_orange_juice'):
        t = 'abbreviation'
    elif t == '+abbreviation':
        t = 'abbreviation'
    elif t.startswith('fw_misspelling:'):
        t = 'fw'
    return t

def get_json(uri):
    """Handle headers and json for us :3"""
    response = requests.get(API + uri, headers=HEADERS)
    limit = int(response.headers.get('x-ratelimit-remaining'))
    if limit == 0:
        sys.stdout.write('\n')
        message = 'You have run out of GitHub request tokens. '
        if int(response.headers.get('x-ratelimit-limit')) == 60:
            message += 'Set a GITHUB_TOKEN to increase your limit to 5000/hour. '
        wait_seconds = int(response.headers.get('x-ratelimit-reset')) - int(time.time())
        wait_minutes = math.ceil(wait_seconds / 60)
        message += 'Try again in ~%d minutes. ' % wait_minutes
        if '--wait-for-reset' in sys.argv:
            progress_message(message.replace('Try ', 'Trying '))
            time.sleep(wait_seconds + 1)
            progress_message('Resuming')
            return get_json(uri)
        else:
            raise ValueError(message)
    progress()
    return response.json()

def api_walk(uri, per_page=100, key='login'):
    """For a GitHub URI, walk all the pages until there's no more content"""
    page = 1
    result = []
    while True:
        response = get_json(uri + '?page=%d&per_page=%d' % (page, per_page))
        if len(response) == 0:
            break
        else:
            page += 1
            for r in response:
                if key == USER_LOGIN:
                    result.append(user_login(r))
                else:
                    result.append(r[key])
    return list(set(result))

def api_get(uri, key=None):
    """Simple API endpoint get, return only the keys we care about"""
    response = get_json(uri)
    if response:
        if type(response) == list:
            r = response[0]
        elif type(response) == dict:
            r = response
        if type(r) == dict:
            if key == USER_LOGIN:
                return user_login(r)
            if key in r:
                return r[key]

def reducejson(j):
    """Not sure if there's a better way to walk the ... interesting result"""
    authors = []
    for key in j['data']['repository']['commitComments']['edges']:
        authors.append(key['node']['author'])
    for key in j['data']['repository']['issues']['nodes']:
        authors.append(key['author'])
        for c in key['comments']['nodes']:
            authors.append(c['author'])
    for key in j['data']['repository']['pullRequests']['edges']:
        authors.append(key['node']['author'])
        for c in key['node']['comments']['nodes']:
            authors.append(c['author'])
    unique = list({v['login']: v for v in authors if v is not None}.values())
    return unique

def stringify_with_dot_if_path(x):
    """Pathlib never renders a leading './' in front of a local path. That's an
    issue because on POSIX subprocess.py (like bash) won't execute scripts in
    the current directory without it. In the same vein, we also don't want
    Path('echo') to match '/usr/bin/echo' from the $PATH. To work around both
    issues, we explicitly join a leading dot to any relative pathlib path."""
    if isinstance(x, PurePath):
        return os.path.join('.', str(x))
    return x

def prepare_modules(module_paths: list, available: dict) -> dict:
    """Scan all paths for external modules and form key-value dict.
    :param module_paths: list of external modules (either python packages or third-party scripts)
    :param available: dict of all registered python modules (can contain python modules from module_paths)
    :return: dict of external modules, where keys are filenames (same as stepnames) and values are the paths"""
    indexed = {}
    for path in module_paths:
        if not os.path.exists(path) and path not in available:
            err = 'No such path: ' + path
            error(err)
        else:
            for f in os.listdir(path):
                mod_path = join(path, f)
                if f in indexed:
                    warning('Override ' + indexed[f] + ' with ' + mod_path)
                indexed[f] = mod_path
    return indexed

def update_variables(func):
    """Use this decorator on Step.action implementation.

    Your action method should always return variables, or
    both variables and output.

    This decorator will update variables with output."""
    @wraps(func)
    def wrapper(self, *args, **kwargs):
        result = func(self, *args, **kwargs)
        if isinstance(result, tuple):
            return self.process_register(result[0], result[1])
        else:
            return self.process_register(result)
    return wrapper

