def iddtxt2groups(txt):
    """extract the groups from the idd file"""
    try:
        txt = txt.decode('ISO-8859-2')
    except AttributeError as e:
        pass
    txt = nocomment(txt, '!')
    txt = txt.replace('\\group', '!-group')
    txt = nocomment(txt, '\\')
    lines = txt.splitlines()
    lines = [line.strip() for line in lines]
    lines = [line for line in lines if line != '']
    txt = '\n'.join(lines)
    gsplits = txt.split('!')
    gsplits = [gsplit.splitlines() for gsplit in gsplits]
    gsplits[0].insert(0, None)
    gdict = {}
    for gsplit in gsplits:
        gdict.update({gsplit[0]: gsplit[1:]})
    gdict = {k: '\n'.join(v) for k, v in gdict.items()}
    gdict = {k: v.split(';') for k, v in gdict.items()}
    gdict = {k: [i.strip() for i in v] for k, v in gdict.items()}
    gdict = {k: [i.splitlines() for i in v] for k, v in gdict.items()}
    gdict = {k: [i for i in v if len(i) > 0] for k, v in gdict.items()}
    gdict = {k: [i[0] for i in v] for k, v in gdict.items()}
    gdict = {k: [i.split(',')[0] for i in v] for k, v in gdict.items()}
    nvalue = gdict.pop(None)
    gdict = {k[len('-group '):]: v for k, v in gdict.items()}
    gdict.update({None: nvalue})
    return gdict

