def _date_to_datetime(value):
    """Convert a date to a datetime for Cloud Datastore storage.

    Args:
      value: A datetime.date object.

    Returns:
      A datetime object with time set to 0:00."""
    if not isinstance(value, datetime.date):
        raise TypeError('Cannot convert to datetime expected date value; received %s' % value)
    return datetime.datetime(value.year, value.month, value.day)

def _time_to_datetime(value):
    """Convert a time to a datetime for Cloud Datastore storage.

    Args:
      value: A datetime.time object.

    Returns:
      A datetime object with date set to 1970-01-01."""
    if not isinstance(value, datetime.time):
        raise TypeError('Cannot convert to datetime expected time value; received %s' % value)
    return datetime.datetime(1970, 1, 1, value.hour, value.minute, value.second, value.microsecond)

def transactional(func, args, kwds, **options):
    """Decorator to make a function automatically run in a transaction.

    Args:
      **ctx_options: Transaction options (see transaction(), but propagation
        default to TransactionOptions.ALLOWED).

    This supports two forms:

    (1) Vanilla:
        @transactional
        def callback(arg):
          ...

    (2) With options:
        @transactional(retries=1)
        def callback(arg):
          ..."""
    return transactional_async.wrapped_decorator(func, args, kwds, **options).get_result()

def transactional_async(func, args, kwds, **options):
    """The async version of @ndb.transaction."""
    options.setdefault('propagation', datastore_rpc.TransactionOptions.ALLOWED)
    if args or kwds:
        return transaction_async(lambda: func(*args, **kwds), **options)
    return transaction_async(func, **options)

def transactional_tasklet(func, args, kwds, **options):
    """The async version of @ndb.transaction.

    Will return the result of the wrapped function as a Future."""
    from . import tasklets
    func = tasklets.tasklet(func)
    return transactional_async.wrapped_decorator(func, args, kwds, **options)

def _ReferenceFromSerialized(serialized):
    """Construct a Reference from a serialized Reference."""
    if not isinstance(serialized, basestring):
        raise TypeError('serialized must be a string; received %r' % serialized)
    elif isinstance(serialized, unicode):
        serialized = serialized.encode('utf8')
    return entity_pb.Reference(serialized)

def _DecodeUrlSafe(urlsafe):
    """Decode a url-safe base64-encoded string.

    This returns the decoded string."""
    if not isinstance(urlsafe, basestring):
        raise TypeError('urlsafe must be a string; received %r' % urlsafe)
    if isinstance(urlsafe, unicode):
        urlsafe = urlsafe.encode('utf8')
    mod = len(urlsafe) % 4
    if mod:
        urlsafe += '=' * (4 - mod)
    return base64.b64decode(urlsafe.replace('-', '+').replace('_', '/'))

def _init_flow_exceptions():
    """Internal helper to initialize _flow_exceptions.

    This automatically adds webob.exc.HTTPException, if it can be imported."""
    global _flow_exceptions
    _flow_exceptions = ()
    add_flow_exception(datastore_errors.Rollback)
    try:
        from webob import exc
    except ImportError:
        pass
    else:
        add_flow_exception(exc.HTTPException)

def _transfer_result(fut1, fut2):
    """Helper to transfer result or errors from one Future to another."""
    exc = fut1.get_exception()
    if exc is not None:
        tb = fut1.get_traceback()
        fut2.set_exception(exc, tb)
    else:
        val = fut1.get_result()
        fut2.set_result(val)

def synctasklet(func):
    """Decorator to run a function as a tasklet when called.

    Use this to wrap a request handler function that will be called by
    some web application framework (e.g. a Django view function or a
    webapp.RequestHandler.get method)."""
    taskletfunc = tasklet(func)
    @utils.wrapping(func)
    def synctasklet_wrapper(*args, **kwds):
        __ndb_debug__ = utils.func_info(func)
        return taskletfunc(*args, **kwds).get_result()
    return synctasklet_wrapper

def _message_to_entity(msg, modelclass):
    """Recursive helper for _to_base_type() to convert a message to an entity.

    Args:
      msg: A Message instance.
      modelclass: A Model subclass.

    Returns:
      An instance of modelclass."""
    ent = modelclass()
    for prop_name, prop in modelclass._properties.iteritems():
        if prop._code_name == 'blob_':
            continue
        value = getattr(msg, prop_name)
        if value is not None and isinstance(prop, model.StructuredProperty):
            if prop._repeated:
                value = [_message_to_entity(v, prop._modelclass) for v in value]
            else:
                value = _message_to_entity(value, prop._modelclass)
        setattr(ent, prop_name, value)
    return ent

def find_env_paths_in_basedirs(base_dirs):
    """Returns all potential envs in a basedir"""
    env_path = []
    for base_dir in base_dirs:
        env_path.extend(glob.glob(os.path.join(os.path.expanduser(base_dir), '*', '')))
    return env_path

def convert_to_env_data(mgr, env_paths, validator_func, activate_func, name_template, display_name_template, name_prefix):
    """Converts a list of paths to environments to env_data.

    env_data is a structure {name -> (ressourcedir, kernel spec)}"""
    env_data = {}
    for venv_dir in env_paths:
        venv_name = os.path.split(os.path.abspath(venv_dir))[1]
        kernel_name = name_template.format(name_prefix + venv_name)
        kernel_name = kernel_name.lower()
        if kernel_name in env_data:
            mgr.log.debug('Found duplicate env kernel: %s, which would again point to %s. Using the first!', kernel_name, venv_dir)
            continue
        argv, language, resource_dir = validator_func(venv_dir)
        if not argv:
            continue
        display_name = display_name_template.format(kernel_name)
        kspec_dict = {'argv': argv, 'language': language, 'display_name': display_name, 'resource_dir': resource_dir}
        def loader(env_dir=venv_dir, activate_func=activate_func, mgr=mgr):
            mgr.log.debug('Loading env data for %s' % env_dir)
            res = activate_func(mgr, env_dir)
            return res
        kspec = EnvironmentLoadingKernelSpec(loader, **kspec_dict)
        env_data.update({kernel_name: (resource_dir, kspec)})
    return env_data

def validate_IPykernel(venv_dir):
    """Validates that this env contains an IPython kernel and returns info to start it


    Returns: tuple
        (ARGV, language, resource_dir)"""
    python_exe_name = find_exe(venv_dir, 'python')
    if python_exe_name is None:
        python_exe_name = find_exe(venv_dir, 'python2')
    if python_exe_name is None:
        python_exe_name = find_exe(venv_dir, 'python3')
    if python_exe_name is None:
        return ([], None, None)
    if find_exe(venv_dir, 'ipython') is None:
        if find_exe(venv_dir, 'ipython2') is None:
            if find_exe(venv_dir, 'ipython3') is None:
                return ([], None, None)
    import subprocess
    try:
        subprocess.check_call([python_exe_name, '-c', '"import ipykernel"'])
    except:
        return ([], None, None)
    argv = [python_exe_name, '-m', 'ipykernel', '-f', '{connection_file}']
    resources_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'logos', 'python')
    return (argv, 'python', resources_dir)

def validate_IRkernel(venv_dir):
    """Validates that this env contains an IRkernel kernel and returns info to start it


    Returns: tuple
        (ARGV, language, resource_dir)"""
    r_exe_name = find_exe(venv_dir, 'R')
    if r_exe_name is None:
        return ([], None, None)
    import subprocess
    ressources_dir = None
    try:
        print_resources = 'cat(as.character(system.file("kernelspec", package = "IRkernel")))'
        resources_dir_bytes = subprocess.check_output([r_exe_name, '--slave', '-e', print_resources])
        resources_dir = resources_dir_bytes.decode(errors='ignore')
    except:
        return ([], None, None)
    argv = [r_exe_name, '--slave', '-e', 'IRkernel::main()', '--args', '{connection_file}']
    if not os.path.exists(resources_dir.strip()):
        resources_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'logos', 'r')
    return (argv, 'r', resources_dir)

def find_exe(env_dir, name):
    """Finds a exe with that name in the environment path"""
    if platform.system() == 'Windows':
        name = name + '.exe'
    exe_name = os.path.join(env_dir, name)
    if not os.path.exists(exe_name):
        exe_name = os.path.join(env_dir, 'bin', name)
        if not os.path.exists(exe_name):
            exe_name = os.path.join(env_dir, 'Scripts', name)
            if not os.path.exists(exe_name):
                return None
    return exe_name

def get_virtualenv_env_data(mgr):
    """Finds kernel specs from virtualenv environments

    env_data is a structure {name -> (resourcedir, kernel spec)}"""
    if not mgr.find_virtualenv_envs:
        return {}
    mgr.log.debug('Looking for virtualenv environments in %s...', mgr.virtualenv_env_dirs)
    env_paths = find_env_paths_in_basedirs(mgr.virtualenv_env_dirs)
    mgr.log.debug('Scanning virtualenv environments for python kernels...')
    env_data = convert_to_env_data(mgr=mgr, env_paths=env_paths, validator_func=validate_IPykernel, activate_func=_get_env_vars_for_virtualenv_env, name_template=mgr.virtualenv_prefix_template, display_name_template=mgr.display_name_template, name_prefix='')
    return env_data

def source_foreign(args, stdin=None):
    """Sources a file written in a foreign shell language."""
    parser = _ensure_source_foreign_parser()
    ns = parser.parse_args(args)
    if ns.prevcmd is not None:
        pass
    elif os.path.isfile(ns.files_or_code[0]):
        ns.prevcmd = '{} "{}"'.format(ns.sourcer, '" "'.join(ns.files_or_code))
    elif ns.prevcmd is None:
        ns.prevcmd = ' '.join(ns.files_or_code)
    fsenv = foreign_shell_data(shell=ns.shell, login=ns.login, interactive=ns.interactive, envcmd=ns.envcmd, aliascmd=ns.aliascmd, extra_args=ns.extra_args, safe=ns.safe, prevcmd=ns.prevcmd, postcmd=ns.postcmd, funcscmd=ns.funcscmd, sourcer=ns.sourcer, use_tmpfile=ns.use_tmpfile, seterrprevcmd=ns.seterrprevcmd, seterrpostcmd=ns.seterrpostcmd)
    if fsenv is None:
        raise RuntimeError('Source failed: {}\n'.format(ns.prevcmd), 1)
    env = os.environ.copy()
    for k, v in fsenv.items():
        if k in env and v == env[k]:
            continue
        env[k] = v
    for k in os.environ:
        if k not in fsenv:
            env.pop(k, None)
    return env

def to_bool(x):
    """"Converts to a boolean in a semantically meaningful way."""
    if isinstance(x, bool):
        return x
    elif isinstance(x, str):
        return False if x.lower() in _FALSES else True
    else:
        return bool(x)

def parse_env(s):
    """Parses the environment portion of string into a dict."""
    m = ENV_RE.search(s)
    if m is None:
        return {}
    g1 = m.group(1)
    env = dict(ENV_SPLIT_RE.findall(g1))
    return env

def to_latin(string_to_transliterate, lang_code='sr'):
    """Transliterate serbian cyrillic string of characters to latin string of characters.
    :param string_to_transliterate: The cyrillic string to transliterate into latin characters.
    :param lang_code: Indicates the cyrillic language code we are translating from. Defaults to Serbian (sr).
    :return: A string of latin characters transliterated from the given cyrillic string."""
    if lang_code.lower() not in TRANSLIT_DICT:
        return string_to_transliterate
    elif not TRANSLIT_DICT[lang_code.lower()]['tolatin']:
        return string_to_transliterate
    else:
        transliteration_dict = TRANSLIT_DICT[lang_code.lower()]['tolatin']
        latinized_str = ''
        string_to_transliterate = __decode_utf8(string_to_transliterate)
        for c in string_to_transliterate:
            if c in transliteration_dict:
                latinized_str += transliteration_dict[c]
            else:
                latinized_str += c
        return __encode_utf8(latinized_str)

def is_now(s, dt=None):
    """A very simple cron-like parser to determine, if (cron-like) string is valid for this date and time.
    @input:
        s = cron-like string (minute, hour, day of month, month, day of week)
        dt = datetime to use as reference time, defaults to now
    @output: boolean of result"""
    if dt is None:
        dt = datetime.now()
    minute, hour, dom, month, dow = s.split(' ')
    weekday = dt.isoweekday()
    return _parse_arg(minute, dt.minute) and _parse_arg(hour, dt.hour) and _parse_arg(dom, dt.day) and _parse_arg(month, dt.month) and _parse_arg(dow, 0 if weekday == 7 else weekday, True)

def has_been(s, since, dt=None):
    """A parser to check whether a (cron-like) string has been true during a certain time period.
    Useful for applications which cannot check every minute or need to catch up during a restart.
    @input:
        s = cron-like string (minute, hour, day of month, month, day of week)
        since = datetime to use as reference time for start of period
        dt = datetime to use as reference time for end of period, defaults to now
    @output: boolean of result"""
    if dt is None:
        dt = datetime.now(tz=since.tzinfo)
    if dt < since:
        raise ValueError('The since datetime must be before the current datetime.')
    while since <= dt:
        if is_now(s, since):
            return True
        since += timedelta(minutes=1)
    return False

def auprc(y_true, y_pred):
    """Area under the precision-recall curve
    """
    y_true, y_pred = _mask_value_nan(y_true, y_pred)
    return skm.average_precision_score(y_true, y_pred)

def VerifierMiddleware(verifier):
    """Common wrapper for the authentication modules.
        * Parses the request before passing it on to the authentication module.
        * Sets 'pyoidc' cookie if authentication succeeds.
        * Redirects the user to complete the authentication.
        * Allows the user to retry authentication if it fails.
    :param verifier: authentication module"""
    @wraps(verifier.verify)
    def wrapper(environ, start_response):
        data = get_post(environ)
        kwargs = dict(urlparse.parse_qsl(data))
        kwargs['state'] = json.loads(urllib.unquote(kwargs['state']))
        val, completed = verifier.verify(**kwargs)
        if not completed:
            return val(environ, start_response)
        if val:
            set_cookie, cookie_value = verifier.create_cookie(val, 'auth')
            cookie_value += '; path=/'
            url = '{base_url}?{query_string}'.format(base_url='/authorization', query_string=kwargs['state']['query'])
            response = SeeOther(url, headers=[(set_cookie, cookie_value)])
            return response(environ, start_response)
        else:
            url = '{base_url}?{query_string}'.format(base_url='/authorization', query_string=kwargs['state']['query'])
            response = SeeOther(url)
            return response(environ, start_response)
    return wrapper

def resp2flask(resp):
    """Convert an oic.utils.http_util instance to Flask."""
    if isinstance(resp, Redirect) or isinstance(resp, SeeOther):
        code = int(resp.status.split()[0])
        raise cherrypy.HTTPRedirect(resp.message, code)
    return (resp.message, resp.status, resp.headers)

def setup_authentication_methods(authn_config, template_env):
