def parseMalformedBamHeader(headerDict):
    """Parses the (probably) intended values out of the specified
    BAM header dictionary, which is incompletely parsed by pysam.
    This is caused by some tools incorrectly using spaces instead
    of tabs as a seperator."""
    headerString = ' '.join(('{}:{}'.format(k, v) for k, v in headerDict.items() if k != 'CL'))
    ret = {}
    for item in headerString.split():
        key, value = item.split(':', 1)
        ret[key] = type(headerDict.get(key, ''))(value)
    if 'CL' in headerDict:
        ret['CL'] = headerDict['CL']
    return ret

def getFlaskResponse(responseString, httpStatus=200):
    """Returns a Flask response object for the specified data and HTTP status."""
    return flask.Response(responseString, status=httpStatus, mimetype=MIMETYPE)

def handleHttpPost(request, endpoint):
    """Handles the specified HTTP POST request, which maps to the specified
    protocol handler endpoint and protocol request class."""
    if request.mimetype and request.mimetype != MIMETYPE:
        raise exceptions.UnsupportedMediaTypeException()
    request = request.get_data()
    if request == '' or request is None:
        request = '{}'
    responseStr = endpoint(request)
    return getFlaskResponse(responseStr)

def handleException(exception):
    """Handles an exception that occurs somewhere in the process of handling
    a request."""
    serverException = exception
    if not isinstance(exception, exceptions.BaseServerException):
        with app.test_request_context():
            app.log_exception(exception)
        serverException = exceptions.getServerError(exception)
    error = serverException.toProtocolElement()
    if flask.request and 'Accept' in flask.request.headers and (flask.request.headers['Accept'].find('text/html') != -1):
        message = '<h1>Error {}</h1><pre>{}</pre>'.format(serverException.httpStatus, protocol.toJson(error))
        if serverException.httpStatus == 401 or serverException.httpStatus == 403:
            message += 'Please try <a href="/login">logging in</a>.'
        return message
    else:
        responseStr = protocol.toJson(error)
        return getFlaskResponse(responseStr, serverException.httpStatus)

def startLogin():
    """If we are not logged in, this generates the redirect URL to the OIDC
    provider and returns the redirect response
    :return: A redirect response to the OIDC provider"""
    flask.session['state'] = oic.oauth2.rndstr(SECRET_KEY_LENGTH)
    flask.session['nonce'] = oic.oauth2.rndstr(SECRET_KEY_LENGTH)
    args = {'client_id': app.oidcClient.client_id, 'response_type': 'code', 'scope': ['openid', 'profile'], 'nonce': flask.session['nonce'], 'redirect_uri': app.oidcClient.redirect_uris[0], 'state': flask.session['state']}
    result = app.oidcClient.do_authorization_request(request_args=args, state=flask.session['state'])
    return flask.redirect(result.url)

def checkAuthentication():
    """The request will have a parameter 'key' if it came from the command line
    client, or have a session key of 'key' if it's the browser.
    If the token is not found, start the login process.

    If there is no oidcClient, we are running naked and we don't check.
    If we're being redirected to the oidcCallback we don't check.

    :returns None if all is ok (and the request handler continues as usual).
    Otherwise if the key was in the session (therefore we're in a browser)
    then startLogin() will redirect to the OIDC provider. If the key was in
    the request arguments, we're using the command line and just raise an
    exception."""
    if app.oidcClient is None:
        return
    if flask.request.endpoint == 'oidcCallback':
        return
    key = flask.session.get('key') or flask.request.args.get('key')
    if key is None or not app.cache.get(key):
        if 'key' in flask.request.args:
            raise exceptions.NotAuthenticatedException()
        else:
            return startLogin()

def handleFlaskGetRequest(id_, flaskRequest, endpoint):
    """Handles the specified flask request for one of the GET URLs
    Invokes the specified endpoint to generate a response."""
    if flaskRequest.method == 'GET':
        return handleHttpGet(id_, endpoint)
    else:
        raise exceptions.MethodNotAllowedException()

def handleFlaskPostRequest(flaskRequest, endpoint):
    """Handles the specified flask request for one of the POST URLS
    Invokes the specified endpoint to generate a response."""
    if flaskRequest.method == 'POST':
        return handleHttpPost(flaskRequest, endpoint)
    elif flaskRequest.method == 'OPTIONS':
        return handleHttpOptions()
    else:
        raise exceptions.MethodNotAllowedException()

def _decode_header(auth_header, client_id, client_secret):
    """Takes the header and tries to return an active token and decoded
    payload.
    :param auth_header:
    :param client_id:
    :param client_secret:
    :return: (token, profile)"""
    try:
        token = auth_header.split()[1]
        payload = jwt.decode(token, client_secret, audience=client_id)
    except jwt.ExpiredSignature:
        raise exceptions.NotAuthorizedException('Token has expired, please log in again.')
    except jwt.InvalidAudienceError:
        message = 'Incorrect audience, expected: {}'.format(client_id)
        raise exceptions.NotAuthorizedException(message)
    except jwt.DecodeError:
        raise exceptions.NotAuthorizedException('Token signature could not be validated.')
    except Exception as e:
        raise exceptions.NotAuthorizedException('Token signature was malformed. {}'.format(e.message))
    return (token, payload)

def find_txt(xml_tree, path, default=''):
    """Extracts the text value from an XML tree, using XPath.
    In case of error, will return a default value.

    :param xml_tree: the XML Tree object. Assumed is <type 'lxml.etree._Element'>.
    :param path:     XPath to be applied, in order to extract the desired data.
    :param default:  Value to be returned in case of error.
    :return: a str value."""
    value = ''
    try:
        xpath_applied = xml_tree.xpath(path)
        if len(xpath_applied) and xpath_applied[0] is not None:
            xpath_result = xpath_applied[0]
            if isinstance(xpath_result, type(xml_tree)):
                value = xpath_result.text.strip()
            else:
                value = xpath_result
    except Exception:
        value = default
    return py23_compat.text_type(value)

def compare_numeric(src_num, dst_num):
    """Compare numerical values. You can use '<%d','>%d'."""
    dst_num = float(dst_num)
    match = numeric_compare_regex.match(src_num)
    if not match:
        error = 'Failed numeric comparison. Collected: {}. Expected: {}'.format(dst_num, src_num)
        raise ValueError(error)
    operand = {'<': '__lt__', '>': '__gt__', '>=': '__ge__', '<=': '__le__', '==': '__eq__', '!=': '__ne__'}
    return getattr(dst_num, operand[match.group(1)])(float(match.group(2)))

def hyphen_range(string):
    """Expands a string of numbers separated by commas and hyphens into a list of integers.
    For example:  2-3,5-7,20-21,23,100-200"""
    list_numbers = list()
    temporary_list = string.split(',')
    for element in temporary_list:
        sub_element = element.split('-')
        if len(sub_element) == 1:
            list_numbers.append(int(sub_element[0]))
        elif len(sub_element) == 2:
            for x in range(int(sub_element[0]), int(sub_element[1]) + 1):
                list_numbers.append(x)
        else:
            raise Exception('Something went wrong expanding the range'.format(string))
    return list_numbers

def str2cryptofunction(crypto_function_description):
    """Convert an OCRA crypto function description into a CryptoFunction
    instance

    :param crypto_function_description:
    :returns:
        the CryptoFunction object
    :rtype: CryptoFunction"""
    s = crypto_function_description.split('-')
    if len(s) != 3:
        raise ValueError('CryptoFunction description must be triplet separated by -')
    if s[0] != HOTP:
        raise ValueError('Unknown CryptoFunction kind %s' % s[0])
    algo = str2hashalgo(s[1])
    try:
        truncation_length = int(s[2])
        if truncation_length < 0 or truncation_length > 10:
            raise ValueError()
    except ValueError:
        raise ValueError('Invalid truncation length %s' % s[2])
    return CryptoFunction(algo, truncation_length)

def from_b32key(b32_key, state=None):
    """Some phone app directly accept a partial b32 encoding, we try to emulate that"""
    try:
        lenient_b32decode(b32_key)
    except TypeError:
        raise ValueError('invalid base32 value')
    return GoogleAuthenticator('otpauth://totp/xxx?%s' % urlencode({'secret': b32_key}), state=state)

def _revert_caffe2_pad(attr):
    """Removing extra padding from Caffe2."""
    if len(attr) == 4:
        attr = attr[:2]
    elif len(attr) == 2:
        pass
    else:
        raise ValueError('Invalid caffe2 type padding: {}'.format(attr))
    return attr

def _pad_sequence_fix(attr, kernelDim=None):
    """Changing onnx's pads sequence to match with mxnet's pad_width
    mxnet: (x1_begin, x1_end, ... , xn_begin, xn_end)
    onnx: (x1_begin, x2_begin, ... , xn_end, xn_end)"""
    new_attr = ()
    if len(attr) % 2 == 0:
        for index in range(int(len(attr) / 2)):
            new_attr = new_attr + attr[index::int(len(attr) / 2)]
        if kernelDim is not None:
            while len(new_attr) < kernelDim * 2:
                new_attr = new_attr + (0, 0)
    return new_attr

def generate_hash(filepath):
    """Public function that reads a local file and generates a SHA256 hash digest for it"""
