def debug_process(pid):
    """Interrupt a running process and debug it."""
    os.kill(pid, signal.SIGUSR1)
    pipe = NamedPipe(pipename(pid), 1)
    try:
        while pipe.is_open():
            txt = raw_input(pipe.get()) + '\n'
            pipe.put(txt)
    except EOFError:
        pass
    pipe.close()

def is_valid_country_abbrev(abbrev, case_sensitive=False):
    """Given a country code abbreviation, check to see if it matches the
    country table.

    abbrev: (str) Country code to evaluate.
    case_sensitive: (bool) When True, enforce case sensitivity.

    Returns True if valid, False if not."""
    if case_sensitive:
        country_code = abbrev
    else:
        country_code = abbrev.upper()
    for code, full_name in COUNTRY_TUPLES:
        if country_code == code:
            return True
    return False

def get_name_from_abbrev(abbrev, case_sensitive=False):
    """Given a country code abbreviation, get the full name from the table.

    abbrev: (str) Country code to retrieve the full name of.
    case_sensitive: (bool) When True, enforce case sensitivity."""
    if case_sensitive:
        country_code = abbrev
    else:
        country_code = abbrev.upper()
    for code, full_name in COUNTRY_TUPLES:
        if country_code == code:
            return full_name
    raise KeyError('No country with that country code.')

def fraction_digits(n: Literal) -> Optional[int]:
    """5.4.5 XML Schema Numeric Facet Constraints

    for "fractiondigits" constraints, v is less than or equals the number of digits to the right of the decimal place
    in the XML Schema canonical form[xmlschema-2] of the value of n, ignoring trailing zeros."""
    return None if not is_numeric(n) or n.value is None else 0 if is_integer(n) or '.' not in str(n.value) or str(n.value).split('.')[1] == '0' else len(str(int(str(n.value).split('.')[1][::-1])))

def _map_xpath_flags_to_re(expr: str, xpath_flags: str) -> Tuple[int, str]:
    """Map `5.6.2 Flags <https://www.w3.org/TR/xpath-functions-31/#flags>`_  to python

    :param expr: match pattern
    :param xpath_flags: xpath flags
    :returns: python flags / modified match pattern"""
    python_flags: int = 0
    modified_expr = expr
    if xpath_flags is None:
        xpath_flags = ''
    if 's' in xpath_flags:
        python_flags |= re.DOTALL
    if 'm' in xpath_flags:
        python_flags |= re.MULTILINE
    if 'i' in xpath_flags:
        python_flags |= re.IGNORECASE
    if 'x' in xpath_flags:
        modified_expr = re.sub('[\\t\\n\\r ]|\\[[^\\]]*\\]', _char_class_escape, modified_expr)
    if 'q' in xpath_flags:
        modified_expr = re.escape(modified_expr)
    return (python_flags, modified_expr)

def map_object_literal(v: Union[str, jsonasobj.JsonObj]) -> ShExJ.ObjectLiteral:
    """`PyShEx.jsg <https://github.com/hsolbrig/ShExJSG/ShExJSG/ShExJ.jsg>`_ does not add identifying
    types to ObjectLiterals.  This routine re-identifies the types"""
    return v if issubclass(type(v), JSGString) or (isinstance(v, JSGObject) and 'type' in v) else ShExJ.IRIREF(v) if isinstance(v, str) else ShExJ.ObjectLiteral(**v._as_dict)

def do_enable():
    """Uncomment any lines that start with #import in the .pth file"""
    try:
        _lines = []
        with open(vext_pth, mode='r') as f:
            for line in f.readlines():
                if line.startswith('#') and line[1:].lstrip().startswith('import '):
                    _lines.append(line[1:].lstrip())
                else:
                    _lines.append(line)
        try:
            os.unlink('%s.tmp' % vext_pth)
        except:
            pass
        with open('%s.tmp' % vext_pth, mode='w+') as f:
            f.writelines(_lines)
        try:
            os.unlink('%s~' % vext_pth)
        except:
            pass
        os.rename(vext_pth, '%s~' % vext_pth)
        os.rename('%s.tmp' % vext_pth, vext_pth)
    except IOError as e:
        if e.errno == 2:
            create_pth()

def do_disable():
    """Comment any lines that start with import in the .pth file"""
    from vext import vext_pth
    try:
        _lines = []
        with open(vext_pth, mode='r') as f:
            for line in f.readlines():
                if not line.startswith('#') and line.startswith('import '):
                    _lines.append('# %s' % line)
                else:
                    _lines.append(line)
        try:
            os.unlink('%s.tmp' % vext_pth)
        except:
            pass
        with open('%s.tmp' % vext_pth, mode='w+') as f:
            f.writelines(_lines)
        try:
            os.unlink('%s~' % vext_pth)
        except:
            pass
        os.rename(vext_pth, '%s~' % vext_pth)
        os.rename('%s.tmp' % vext_pth, vext_pth)
    except IOError as e:
        if e.errno == 2:
            return

def fixup_paths():
    """Fixup paths added in .pth file that point to the virtualenv
    instead of the system site packages.

    In depth:  .PTH can execute arbitrary code, which might
    manipulate the PATH or sys.path

    :return:"""
    original_paths = os.environ.get('PATH', '').split(os.path.pathsep)
    original_dirs = set(added_dirs)
    yield
    current_paths = os.environ.get('PATH', '').split(os.path.pathsep)
    if original_paths != current_paths:
        changed_paths = set(current_paths).difference(set(original_paths))
        fixed_paths = []
        for path in current_paths:
            if path in changed_paths:
                fixed_paths.append(env_t(fix_path(path)))
            else:
                fixed_paths.append(env_t(path))
        os.environ['PATH'] = os.pathsep.join(fixed_paths)
    if added_dirs != original_dirs:
        for path in set(added_dirs.difference(original_dirs)):
            fixed_path = fix_path(path)
            if fixed_path != path:
                print('Fix %s >> %s' % (path, fixed_path))
                added_dirs.remove(path)
                added_dirs.add(fixed_path)
                i = sys.path.index(path)
                sys.path[i] = fixed_path
                if env_t(fixed_path) not in os.environ['PATH']:
                    os.environ['PATH'].append(os.pathsep + env_t(fixed_path))

def addpackage(sys_sitedir, pthfile, known_dirs):
    """Wrapper for site.addpackage

    Try and work out which directories are added by
    the .pth and add them to the known_dirs set

    :param sys_sitedir: system site-packages directory
    :param pthfile: path file to add
    :param known_dirs: set of known directories"""
    with open(join(sys_sitedir, pthfile)) as f:
        for n, line in enumerate(f):
            if line.startswith('#'):
                continue
            line = line.rstrip()
            if line:
                if line.startswith(('import ', 'import\t')):
                    exec(line, globals(), locals())
                    continue
                else:
                    p_rel = join(sys_sitedir, line)
                    p_abs = abspath(line)
                    if isdir(p_rel):
                        os.environ['PATH'] += env_t(os.pathsep + p_rel)
                        sys.path.append(p_rel)
                        added_dirs.add(p_rel)
                    elif isdir(p_abs):
                        os.environ['PATH'] += env_t(os.pathsep + p_abs)
                        sys.path.append(p_abs)
                        added_dirs.add(p_abs)
    if isfile(pthfile):
        site.addpackage(sys_sitedir, pthfile, known_dirs)
    else:
        logging.debug("pth file '%s' not found")

def init_path():
    """Add any new modules that are directories to the PATH"""
    sitedirs = getsyssitepackages()
    for sitedir in sitedirs:
        env_path = os.environ['PATH'].split(os.pathsep)
        for module in allowed_modules:
            p = join(sitedir, module)
            if isdir(p) and (not p in env_path):
                os.environ['PATH'] += env_t(os.pathsep + p)

def install_importer():
    """If in a virtualenv then load spec files to decide which
    modules can be imported from system site-packages and
    install path hook."""
    logging.debug('install_importer')
    if not in_venv():
        logging.debug('No virtualenv active py:[%s]', sys.executable)
        return False
    if disable_vext:
        logging.debug('Vext disabled by environment variable')
        return False
    if GatekeeperFinder.PATH_TRIGGER not in sys.path:
        try:
            load_specs()
            sys.path.append(GatekeeperFinder.PATH_TRIGGER)
            sys.path_hooks.append(GatekeeperFinder)
        except Exception as e:
            '\n            Dont kill other programmes because of a vext error\n            '
            logger.info(str(e))
            if logger.getEffectiveLevel() == logging.DEBUG:
                raise
        logging.debug('importer installed')
        return True

def extra_paths():
    """:return: extra paths"""
    dirs = {}
    try:
        @vext.env.run_in_syspy
        def run(*args):
            import sipconfig
            config = sipconfig.Configuration()
            dirs = {'sip.default_sip_dir': config.default_sip_dir}
            return dirs
        dirs = run()
        return dirs
    except ImportError:
        return dirs

def evaluate(g: Graph, schema: Union[str, ShExJ.Schema], focus: Optional[Union[str, URIRef, IRIREF]], start: Optional[Union[str, URIRef, IRIREF, START, START_TYPE]]=None, debug_trace: bool=False) -> Tuple[bool, Optional[str]]:
    """Evaluate focus node `focus` in graph `g` against shape `shape` in ShEx schema `schema`

    :param g: Graph containing RDF
    :param schema: ShEx Schema -- if str, it will be parsed
    :param focus: focus node in g. If not specified, all URI subjects in G will be evaluated.
    :param start: Starting shape.  If omitted, the Schema start shape is used
    :param debug_trace: Turn on debug tracing
    :return: None if success or failure reason if failure"""
    if isinstance(schema, str):
        schema = SchemaLoader().loads(schema)
    if schema is None:
        return (False, 'Error parsing schema')
    if not isinstance(focus, URIRef):
        focus = URIRef(str(focus))
    if start is None:
        start = str(schema.start) if schema.start else None
    if start is None:
        return (False, 'No starting shape')
    if not isinstance(start, IRIREF) and start is not START and (start is not START_TYPE):
        start = IRIREF(str(start))
    cntxt = Context(g, schema)
    cntxt.debug_context.debug = debug_trace
    map_ = FixedShapeMap()
    map_.add(ShapeAssociation(focus, start))
    test_result, reasons = isValid(cntxt, map_)
    return (test_result, '\n'.join(reasons))

def check_sysdeps(vext_files):
    """Check that imports in 'test_imports' succeed
    otherwise display message in 'install_hints'"""
    @run_in_syspy
    def run(*modules):
        result = {}
        for m in modules:
            if m:
                try:
                    __import__(m)
                    result[m] = True
                except ImportError:
                    result[m] = False
        return result
    success = True
    for vext_file in vext_files:
        with open(vext_file) as f:
            vext = open_spec(f)
            install_hint = ' '.join(vext.get('install_hints', ['System dependencies not found']))
            modules = vext.get('test_import', '')
            logger.debug('%s test imports of: %s', vext_file, modules)
            result = run(*modules)
            if logging.getLogger().getEffectiveLevel() == logging.DEBUG:
                for k, v in result.items():
                    logger.debug('%s: %s', k, v)
            if not all(result.values()):
                success = False
                print(install_hint)
    return success

def install_vexts(vext_files, verify=True):
    """copy vext_file to sys.prefix + '/share/vext/specs'

    (PIP7 seems to remove data_files so we recreate something similar here)"""
    if verify and (not check_sysdeps(vext_files)):
        return
    spec_dir = join(prefix, 'share/vext/specs')
    try:
        makedirs(spec_dir)
    except OSError as e:
        if not isdir(spec_dir):
            logger.error('Error making spec directory [%s]: %r' % (spec_dir, e))
    for vext_file in vext_files:
        dest = normpath(join(spec_dir, basename(vext_file)))
        try:
            logger.debug('%s > %s' % (vext_file, dest))
            copyfile(vext_file, dest)
            yield (vext_file, dest)
        except IOError as e:
            logger.error('Could not copy %s %r' % (vext_file, e))

def format_collection(g: Graph, subj: Union[URIRef, BNode], max_entries: int=None, nentries: int=0) -> Optional[List[str]]:
    """Return the turtle representation of subj as a collection

    :param g: Graph containing subj
    :param subj: subject of list
    :param max_entries: maximum number of list elements to return, None means all
    :param nentries: used for recursion

    :return: List of formatted entries if subj heads a well formed collection else None"""
    if subj == RDF.nil:
        return [')']
    if max_entries is not None and nentries >= max_entries:
        return ['  ...', ')']
    cadr = cdr = None
    for p, o in g.predicate_objects(subj):
        if p == RDF.first and cadr is None:
            cadr = o
        elif p == RDF.rest and cdr is None:
            cdr = o
        else:
            return None
    if cadr == RDF.nil and cdr is None:
        return []
    elif cadr is not None and cdr is not None:
        return [(' ' if nentries else '(') + cadr.n3(g.namespace_manager)] + format_collection(g, cdr, max_entries, nentries + 1)
    else:
        return None

def upgrade_setuptools():
    """setuptools 12.2 can trigger a really nasty bug
    that eats all memory, so upgrade it to
    18.8, which is known to be good."""
    global MIN_SETUPTOOLS
    r = None
    try:
        r = pkg_resources.require(['setuptools'])[0]
    except DistributionNotFound:
        return
    if StrictVersion(r.version) >= StrictVersion(MIN_SETUPTOOLS):
        return
    else:
        print('Upgrading setuptools...')
        subprocess.call("%s -mpip install 'setuptools>=%s'" % (sys.executable, MIN_SETUPTOOLS), shell=True)

def objectValueMatches(n: Node, vsv: ShExJ.objectValue) -> bool:
    """http://shex.io/shex-semantics/#values

    Implements "n = vsv" where vsv is an objectValue and n is a Node

    Note that IRIREF is a string pattern, so the matching type is str"""
    return isinstance(vsv, IRIREF) and isinstance(n, URIRef) and uriref_matches_iriref(n, vsv) or (isinstance(vsv, ShExJ.ObjectLiteral) and isinstance(n, Literal) and literal_matches_objectliteral(n, vsv))

def uriref_startswith_iriref(v1: URIRef, v2: Union[str, ShExJ.IRIREF]) -> bool:
    """Determine whether a :py:class:`rdflib.URIRef` value starts with the text of a :py:class:`ShExJ.IRIREF` value"""
    return str(v1).startswith(str(v2))

def satisfiesNodeConstraint(cntxt: Context, n: Node, nc: ShExJ.NodeConstraint, _: DebugContext) -> bool:
    """`5.4.1 Semantics <http://shex.io/shex-semantics/#node-constraint-semantics>`_

    For a node n and constraint nc, satisfies2(n, nc) if and only if for every nodeKind, datatype, xsFacet and
    values constraint value v present in nc nodeSatisfies(n, v). The following sections define nodeSatisfies for
    each of these types of constraints:"""
    return nodeSatisfiesNodeKind(cntxt, n, nc) and nodeSatisfiesDataType(cntxt, n, nc) and nodeSatisfiesStringFacet(cntxt, n, nc) and nodeSatisfiesNumericFacet(cntxt, n, nc) and nodeSatisfiesValues(cntxt, n, nc)

def nodeSatisfiesValues(cntxt: Context, n: Node, nc: ShExJ.NodeConstraint, _c: DebugContext) -> bool:
    """`5.4.5 Values Constraint <http://shex.io/shex-semantics/#values>`_

    For a node n and constraint value v, nodeSatisfies(n, v) if n matches some valueSetValue vsv in v."""
    if nc.values is None:
        return True
    elif any((_nodeSatisfiesValue(cntxt, n, vsv) for vsv in nc.values)):
        return True
    else:
        cntxt.fail_reason = f'Node: {cntxt.n3_mapper.n3(n)} not in value set:\n\t {as_json(cntxt.type_last(nc), indent=None)[:60]}...'
        return False

def findsyspy():
    """:return: system python executable"""
    if not in_venv():
        return sys.executable
    python = basename(realpath(sys.executable))
    prefix = None
    if HAS_ORIG_PREFIX_TXT:
        with open(ORIG_PREFIX_TXT) as op:
            prefix = op.read()
    elif HAS_PY_VENV_CFG:
        prefix = getattr(sys, '_home')
    if not prefix:
        return None
    for folder in os.environ['PATH'].split(os.pathsep):
        if folder and normpath(normcase(folder)).startswith(normcase(normpath(prefix))) and isfile(join(folder, python)):
            return join(folder, python)
    if isfile(join(prefix, 'bin', python)):
        return join(prefix, 'bin', python)

def matchesExpr(cntxt: Context, T: RDFGraph, expr: ShExJ.tripleExpr, _: DebugContext) -> bool:
    """Evaluate the expression

    """
    if isinstance(expr, ShExJ.OneOf):
        return matchesOneOf(cntxt, T, expr)
    elif isinstance(expr, ShExJ.EachOf):
        return matchesEachOf(cntxt, T, expr)
    elif isinstance(expr, ShExJ.TripleConstraint):
        return matchesCardinality(cntxt, T, expr)
    elif isinstance_(expr, ShExJ.tripleExprLabel):
        return matchesTripleExprRef(cntxt, T, expr)
    else:
        raise Exception('Unknown expression')

def matchesOneOf(cntxt: Context, T: RDFGraph, expr: ShExJ.OneOf, _: DebugContext) -> bool:
    """expr is a OneOf and there is some shape expression se2 in shapeExprs such that a matches(T, se2, m)."""
    return any((matches(cntxt, T, e) for e in expr.expressions))

def matchesTripleExprRef(cntxt: Context, T: RDFGraph, expr: ShExJ.tripleExprLabel, _: DebugContext) -> bool:
    """expr is an tripleExprRef and satisfies(value, tripleExprWithId(tripleExprRef), G, m).
    The tripleExprWithId function is defined in Triple Expression Reference Requirement below."""
    expr = cntxt.tripleExprFor(expr)
    if expr is None:
        cntxt.fail_reason = '{expr}: Reference not found'
        return False
    return matchesExpr(cntxt, T, expr)

def reference_of(selector: shapeLabel, cntxt: Union[Context, ShExJ.Schema]) -> Optional[ShExJ.shapeExpr]:
    """Return the shape expression in the schema referenced by selector, if any

    :param cntxt: Context node or ShEx Schema
    :param selector: identifier of element to select within the schema
    :return:"""
    schema = cntxt.schema if isinstance(cntxt, Context) else cntxt
    if selector is START:
        return schema.start
    for expr in schema.shapes:
        if not isinstance(expr, ShExJ.ShapeExternal) and expr.id == selector:
            return expr
    return schema.start if schema.start is not None and schema.start.id == selector else None

def triple_reference_of(label: ShExJ.tripleExprLabel, cntxt: Context) -> Optional[ShExJ.tripleExpr]:
    """Search for the label in a Schema"""
    te: Optional[ShExJ.tripleExpr] = None
    if cntxt.schema.start is not None:
        te = triple_in_shape(cntxt.schema.start, label, cntxt)
    if te is None:
        for shapeExpr in cntxt.schema.shapes:
            te = triple_in_shape(shapeExpr, label, cntxt)
            if te:
                break
    return te

def triple_in_shape(expr: ShExJ.shapeExpr, label: ShExJ.tripleExprLabel, cntxt: Context) -> Optional[ShExJ.tripleExpr]:
    """Search for the label in a shape expression"""
    te = None
    if isinstance(expr, (ShExJ.ShapeOr, ShExJ.ShapeAnd)):
        for expr2 in expr.shapeExprs:
            te = triple_in_shape(expr2, label, cntxt)
            if te is not None:
                break
    elif isinstance(expr, ShExJ.ShapeNot):
        te = triple_in_shape(expr.shapeExpr, label, cntxt)
    elif isinstance(expr, ShExJ.shapeExprLabel):
        se = reference_of(expr, cntxt)
        if se is not None:
            te = triple_in_shape(se, label, cntxt)
    return te

def directed_predicates_in_expression(expression: ShExJ.shapeExpr, cntxt: Context) -> Dict[IRIREF, PredDirection]:
    """Directed predicates in expression -- return all predicates in shapeExpr along with which direction(s) they
    evaluate

    :param expression: Expression to scan
    :param cntxt:
    :return:"""
    dir_predicates: Dict[IRIREF, PredDirection] = {}
    def predicate_finder(predicates: Dict[IRIREF, PredDirection], tc: ShExJ.TripleConstraint, _: Context) -> None:
        if isinstance(tc, ShExJ.TripleConstraint):
            predicates.setdefault(tc.predicate, PredDirection()).dir(tc.inverse is None or not tc.inverse)
    def triple_expr_finder(predicates: Dict[IRIREF, PredDirection], expr: ShExJ.shapeExpr, cntxt_: Context) -> None:
        if isinstance(expr, ShExJ.Shape) and expr.expression is not None:
            cntxt_.visit_triple_expressions(expr.expression, predicate_finder, predicates)
    cntxt.visit_shapes(expression, triple_expr_finder, dir_predicates, follow_inner_shapes=False)
    return dir_predicates

def partition_t(T: RDFGraph, nparts: int) -> Iterator[Tuple[RDFGraph, ...]]:
    """Partition T into all possible partitions of T of size nparts
    :param T: Set of RDF triples to be partitioned
    :param nparts: number of partitions (e.g. 2 means return all possible 2 set partitions
    :return: Iterator that returns partitions

    We don't actually partition the triples directly -- instead, we partition a set of integers that
    reference elements in the (ordered) set and return those"""
    def partition_map(partition: List[List[int]]) -> Tuple[RDFGraph, ...]:
        rval: List[RDFGraph, ...] = []
        for part in partition:
            if len(part) == 1 and part[0] >= t_list_len:
                rval.append(RDFGraph())
            else:
                rval.append(RDFGraph([t_list[e] for e in part if e < t_list_len]))
        return tuple(rval)
    t_list = sorted(list(T))
    t_list_len = len(t_list)
    return map(lambda partition: partition_map(partition), filtered_integer_partition(t_list_len, nparts))

def partition_2(T: RDFGraph) -> List[Tuple[RDFGraph, RDFGraph]]:
    """Partition T into all possible combinations of two subsets
    :param T: RDF Graph to partition
    :return:"""
    for p in partition_t(T, 2):
        yield p

def is_strict_numeric(n: Node) -> bool:
    """numeric denotes typed literals with datatypes xsd:integer, xsd:decimal, xsd:float, and xsd:double."""
    return is_typed_literal(n) and cast(Literal, n).datatype in [XSD.integer, XSD.decimal, XSD.float, XSD.double]

def is_simple_literal(n: Node) -> bool:
    """simple literal denotes a plain literal with no language tag."""
    return is_typed_literal(n) and cast(Literal, n).datatype is None and (cast(Literal, n).language is None)

def satisifesShapeOr(cntxt: Context, n: Node, se: ShExJ.ShapeOr, _: DebugContext) -> bool:
    """Se is a ShapeOr and there is some shape expression se2 in shapeExprs such that satisfies(n, se2, G, m)."""
    return any((satisfies(cntxt, n, se2) for se2 in se.shapeExprs))

def satisfiesShapeAnd(cntxt: Context, n: Node, se: ShExJ.ShapeAnd, _: DebugContext) -> bool:
    """Se is a ShapeAnd and for every shape expression se2 in shapeExprs, satisfies(n, se2, G, m)"""
    return all((satisfies(cntxt, n, se2) for se2 in se.shapeExprs))

def satisfiesShapeNot(cntxt: Context, n: Node, se: ShExJ.ShapeNot, _: DebugContext) -> bool:
    """Se is a ShapeNot and for the shape expression se2 at shapeExpr, notSatisfies(n, se2, G, m)"""
    return not satisfies(cntxt, n, se.shapeExpr)

def satisfiesExternal(cntxt: Context, n: Node, se: ShExJ.ShapeExternal, c: DebugContext) -> bool:
    """Se is a ShapeExternal and implementation-specific mechansims not defined in this specification indicate
    success."""
    if c.debug:
        print(f'id: {se.id}')
    extern_shape = cntxt.external_shape_for(se.id)
    if extern_shape:
        return satisfies(cntxt, n, extern_shape)
    cntxt.fail_reason = f'{se.id}: Shape is not in Schema'
    return False

def satisfiesShapeExprRef(cntxt: Context, n: Node, se: ShExJ.shapeExprLabel, c: DebugContext) -> bool:
    """Se is a shapeExprRef and there exists in the schema a shape expression se2 with that id
    and satisfies(n, se2, G, m)."""
    if c.debug:
        print(f'id: {se}')
    for shape in cntxt.schema.shapes:
        if shape.id == se:
            return satisfies(cntxt, n, shape)
    cntxt.fail_reason = f'{se}: Shape is not in Schema'
    return False

def normalize_uri(u: URI) -> URIRef:
    """Return a URIRef for a str or URIRef"""
    return u if isinstance(u, URIRef) else URIRef(str(u))

def normalize_uriparm(p: URIPARM) -> List[URIRef]:
    """Return an optional list of URIRefs for p"""
    return normalize_urilist(p) if isinstance(p, List) else normalize_urilist([p]) if isinstance(p, (str, URIRef)) else p

def normalize_startparm(p: STARTPARM) -> List[Union[type(START), START_TYPE, URIRef]]:
    """Return the startspec for p"""
    if not isinstance(p, list):
        p = [p]
    return [normalize_uri(e) if isinstance(e, str) and e is not START else e for e in p]

def arcsOut(G: Graph, n: Node) -> RDFGraph:
    """arcsOut(G, n) is the set of triples in a graph G with subject n."""
    return RDFGraph(G.triples((n, None, None)))

def predicatesOut(G: Graph, n: Node) -> Set[TriplePredicate]:
    """predicatesOut(G, n) is the set of predicates in arcsOut(G, n)."""
    return {p for p, _ in G.predicate_objects(n)}

def arcsIn(G: Graph, n: Node) -> RDFGraph:
    """arcsIn(G, n) is the set of triples in a graph G with object n."""
    return RDFGraph(G.triples((None, None, n)))

def predicatesIn(G: Graph, n: Node) -> Set[TriplePredicate]:
    """predicatesIn(G, n) is the set of predicates in arcsIn(G, n)."""
    return {p for _, p in G.subject_predicates(n)}

def sanitize(value):
    """Sanitizes strings according to SANITIZER_ALLOWED_TAGS,
    SANITIZER_ALLOWED_ATTRIBUTES and SANITIZER_ALLOWED_STYLES variables in
    settings.

    Example usage:

    {% load sanitizer %}
    {{ post.content|escape_html }}"""
    if isinstance(value, basestring):
        value = bleach.clean(value, tags=ALLOWED_TAGS, attributes=ALLOWED_ATTRIBUTES, styles=ALLOWED_STYLES, strip=False)
    return value

def strip_filter(value):
    """Strips HTML tags from strings according to SANITIZER_ALLOWED_TAGS,
    SANITIZER_ALLOWED_ATTRIBUTES and SANITIZER_ALLOWED_STYLES variables in
    settings.

    Example usage:

    {% load sanitizer %}
    {{ post.content|strip_html }}"""
    if isinstance(value, basestring):
        value = bleach.clean(value, tags=ALLOWED_TAGS, attributes=ALLOWED_ATTRIBUTES, styles=ALLOWED_STYLES, strip=True)
    return value

def sanitize_allow(value, args=''):
    """Strip HTML tags other than provided tags and attributes.
    Example usage:

    {% load sanitizer %}
    {{ post.body|sanitize_allow:'a, strong, img; href, src'}}"""
    if isinstance(value, basestring):
        allowed_tags = []
        allowed_attributes = []
        allowed_styles = []
        args = args.strip().split(';')
        if len(args) > 0:
            allowed_tags = [tag.strip() for tag in args[0].split(',')]
        if len(args) > 1:
            allowed_attributes = [attr.strip() for attr in args[1].split(',')]
        value = bleach.clean(value, tags=allowed_tags, attributes=allowed_attributes, strip=True)
    return value

def escape_html(value, allowed_tags=[], allowed_attributes=[], allowed_styles=[]):
    """Template tag to sanitize string values. It accepts lists of
    allowed tags, attributes or styles in comma separated string or list format.

    For example:

    {% load sanitizer %}
    {% escape_html '<a href="">bar</a> <script>alert('baz')</script>' "a,img' 'href',src' %}

    Will output:

    <a href="">bar</a> &lt;cript&gt;alert('baz')&lt;/script&gt;

    On django 1.4 you could also use keyword arguments:

    {% escape_html '<a href="">bar</a>' allowed_tags="a,img' allowed_attributes='href',src' %}"""
    if isinstance(value, basestring):
        value = bleach.clean(value, tags=allowed_tags, attributes=allowed_attributes, styles=allowed_styles, strip=False)
    return value

def strip_html(value, allowed_tags=[], allowed_attributes=[], allowed_styles=[]):
    """Template tag to strip html from string values. It accepts lists of
    allowed tags, attributes or stylesin comma separated string or list format.

    For example:

    {% load sanitizer %}
    {% strip_html '<a href="">bar</a> <script>alert('baz')</script>' "a,img' 'href',src' %}

    Will output:

    <a href="">bar</a> alert('baz');

    On django 1.4 you could also use keyword arguments:

    {% strip_html '<a href="">bar</a>' allowed_tags="a,img' allowed_attributes='href',src' %}"""
    if isinstance(value, basestring):
        value = bleach.clean(value, tags=allowed_tags, attributes=allowed_attributes, styles=allowed_styles, strip=True)
    return value

def get_word_list_eng(text):
    """A naive function that extracts English words from raw texts.

    :param text: The raw text.
    :return words: A list of strings."""
    words, index = ([''], 0)
    while index < len(text):
        while index < len(text) and ('a' <= text[index] <= 'z' or 'A' <= text[index] <= 'Z'):
            words[-1] += text[index]
            index += 1
        if words[-1]:
            words.append('')
        while index < len(text) and (not ('a' <= text[index] <= 'z' or 'A' <= text[index] <= 'Z')):
            if text[index] != ' ':
                words[-1] += text[index]
            index += 1
        if words[-1]:
            words.append('')
    if not words[-1]:
        words.pop()
    return words

def get_embedding_weights_from_file(word_dict, file_path, ignore_case=False):
    """Load pre-trained embeddings from a text file.

    Each line in the file should look like this:
        word feature_dim_1 feature_dim_2 ... feature_dim_n

    The `feature_dim_i` should be a floating point number.

    :param word_dict: A dict that maps words to indice.
    :param file_path: The location of the text file containing the pre-trained embeddings.
    :param ignore_case: Whether ignoring the case of the words.

    :return weights: A numpy array."""
    pre_trained = {}
    with codecs.open(file_path, 'r', 'utf8') as reader:
        for line in reader:
            line = line.strip()
            if not line:
                continue
            parts = line.split()
            if ignore_case:
                parts[0] = parts[0].lower()
            pre_trained[parts[0]] = list(map(float, parts[1:]))
    embd_dim = len(next(iter(pre_trained.values())))
    weights = [[0.0] * embd_dim for _ in range(max(word_dict.values()) + 1)]
    for word, index in word_dict.items():
        if not word:
            continue
        if ignore_case:
            word = word.lower()
        if word in pre_trained:
            weights[index] = pre_trained[word]
        else:
            weights[index] = numpy.random.random((embd_dim,)).tolist()
    return numpy.asarray(weights)

def format_explanation(explanation, indent='  ', indent_level=0):
    """Return explanation in an easier to read format

    Easier to read for me, at least."""
    if not explanation:
        return ''
    line = '%s%s %2.4f' % (indent * indent_level, explanation['description'], explanation['value'])
    if 'details' in explanation:
        details = '\n'.join([format_explanation(subtree, indent, indent_level + 1) for subtree in explanation['details']])
        return line + '\n' + details
    return line

def _facet_counts(items):
