            yield JSONError("Custom Observable Object type '%s' should start with 'x-'." % obj['type'], instance['id'], 'custom-prefix-lax')

def custom_object_extension_prefix_strict(instance):
    """Ensure custom observable object extensions follow strict naming style
    conventions."""
    for key, obj in instance['objects'].items():
        if not ('extensions' in obj and 'type' in obj and (obj['type'] in enums.OBSERVABLE_EXTENSIONS)):
            continue
        for ext_key in obj['extensions']:
            if ext_key not in enums.OBSERVABLE_EXTENSIONS[obj['type']] and (not CUSTOM_TYPE_PREFIX_RE.match(ext_key)):
