            for opt in options:
                if opt not in enums.SOCKET_OPTIONS:
                    yield JSONError("The 'options' property of object '%s' contains a key ('%s') that is not a valid socket option (SO_*)." % (key, opt), instance['id'], 'socket-options')

def pdf_doc_info(instance):
    """Ensure the keys of the 'document_info_dict' property of the pdf-ext
