    return client.indices.delete(index=index)

def _validate_config(strict=False):
    """Validate settings.SEARCH_SETTINGS."""
    for index in settings.get_index_names():
        _validate_mapping(index, strict=strict)
        for model in settings.get_index_models(index):
            _validate_model(model)
    if settings.get_setting('update_strategy', 'full') not in ['full', 'partial']:
        raise ImproperlyConfigured("Invalid SEARCH_SETTINGS: 'update_strategy' value must be 'full' or 'partial'.")

def _validate_mapping(index, strict=False):
    """Check that an index mapping JSON file exists."""
    try:
        settings.get_index_mapping(index)
    except IOError:
        if strict:
            raise ImproperlyConfigured("Index '%s' has no mapping file." % index)
        else:
            logger.warning("Index '%s' has no mapping, relying on ES instead.", index)

def _validate_model(model):
    """Check that a model configured for an index subclasses the required classes."""
    if not hasattr(model, 'as_search_document'):
        raise ImproperlyConfigured("'%s' must implement `as_search_document`." % model)
    if not hasattr(model.objects, 'get_search_queryset'):
        raise ImproperlyConfigured("'%s.objects must implement `get_search_queryset`." % model)

def _connect_signals():
    """Connect up post_save, post_delete signals for models."""
    for index in settings.get_index_names():
        for model in settings.get_index_models(index):
            _connect_model_signals(model)

def _on_model_save(sender, **kwargs):
    """Update document in search index post_save."""
    instance = kwargs.pop('instance')
    update_fields = kwargs.pop('update_fields')
    for index in instance.search_indexes:
        try:
            _update_search_index(instance=instance, index=index, update_fields=update_fields)
        except Exception:
            logger.exception("Error handling 'on_save' signal for %s", instance)

def _on_model_delete(sender, **kwargs):
    """Remove documents from search indexes post_delete."""
    instance = kwargs.pop('instance')
    for index in instance.search_indexes:
        try:
            _delete_from_search_index(instance=instance, index=index)
        except Exception:
            logger.exception("Error handling 'on_delete' signal for %s", instance)

def _in_search_queryset(*, instance, index) -> bool:
    """Wrapper around the instance manager method."""
    try:
        return instance.__class__.objects.in_search_queryset(instance.id, index=index)
    except Exception:
        logger.exception('Error checking object in_search_queryset.')
        return False

def _update_search_index(*, instance, index, update_fields):
    """Process index / update search index update actions."""
    if not _in_search_queryset(instance=instance, index=index):
        logger.debug('Object (%r) is not in search queryset, ignoring update.', instance)
        return
    try:
        if update_fields:
            pre_update.send(sender=instance.__class__, instance=instance, index=index, update_fields=update_fields)
            if settings.auto_sync(instance):
                instance.update_search_document(index=index, update_fields=update_fields)
        else:
            pre_index.send(sender=instance.__class__, instance=instance, index=index)
            if settings.auto_sync(instance):
                instance.index_search_document(index=index)
    except Exception:
        logger.exception("Error handling 'post_save' signal for %s", instance)

def _delete_from_search_index(*, instance, index):
    """Remove a document from a search index."""
    pre_delete.send(sender=instance.__class__, instance=instance, index=index)
    if settings.auto_sync(instance):
        instance.delete_search_document(index=index)

def get_model_index_properties(instance, index):
    """Return the list of properties specified for a model in an index."""
    mapping = get_index_mapping(index)
    doc_type = instance._meta.model_name.lower()
    return list(mapping['mappings'][doc_type]['properties'].keys())

def auto_sync(instance):
    """Returns bool if auto_sync is on for the model (instance)"""
    if not get_setting('auto_sync'):
        return False
    model_name = '{}.{}'.format(instance._meta.app_label, instance._meta.model_name)
    if model_name in get_setting('never_auto_sync', []):
        return False
    return True

def sizes(count, offset=0, max_chunk=500):
    """Helper to iterate over remote data via count & offset pagination."""
    if count is None:
        chunk = max_chunk
        while True:
            yield (chunk, offset)
            offset += chunk
    else:
        while count:
            chunk = min(count, max_chunk)
            count = max(0, count - max_chunk)
            yield (chunk, offset)
            offset += chunk

def list_to_csv(value):
    """Converts list to string with comma separated values. For string is no-op."""
    if isinstance(value, (list, tuple, set)):
        value = ','.join(value)
    return value

def prepare_attachments(attachment):
    """Converts incoming attachment into dictionary."""
    if isinstance(attachment, tuple):
        result = {'Name': attachment[0], 'Content': attachment[1], 'ContentType': attachment[2]}
        if len(attachment) == 4:
            result['ContentID'] = attachment[3]
    elif isinstance(attachment, MIMEBase):
        payload = attachment.get_payload()
        content_type = attachment.get_content_type()
        if content_type == 'message/rfc822' and (not isinstance(payload, str)):
            payload = b64encode(payload[0].get_payload(decode=True)).decode()
        result = {'Name': attachment.get_filename() or 'attachment.txt', 'Content': payload, 'ContentType': content_type}
        content_id = attachment.get('Content-ID')
        if content_id:
            if content_id.startswith('<') and content_id.endswith('>'):
                content_id = content_id[1:-1]
            if (attachment.get('Content-Disposition') or '').startswith('inline'):
                content_id = 'cid:%s' % content_id
            result['ContentID'] = content_id
    elif isinstance(attachment, str):
        content_type = guess_content_type(attachment)
        filename = os.path.basename(attachment)
        with open(attachment, 'rb') as fd:
            data = fd.read()
        result = {'Name': filename, 'Content': b64encode(data).decode('utf-8'), 'ContentType': content_type}
    else:
        result = attachment
    return result

def rangify(number_list):
    """Assumes the list is sorted."""
    if not number_list:
        return number_list
    ranges = []
    range_start = prev_num = number_list[0]
    for num in number_list[1:]:
        if num != prev_num + 1:
            ranges.append((range_start, prev_num))
            range_start = num
        prev_num = num
    ranges.append((range_start, prev_num))
    return ranges

def nickmask(prefix: str, kwargs: Dict[str, Any]) -> None:
    """store nick, user, host in kwargs if prefix is correct format"""
    if '!' in prefix and '@' in prefix:
        kwargs['nick'], remainder = prefix.split('!', 1)
        kwargs['user'], kwargs['host'] = remainder.split('@', 1)
    else:
        kwargs['host'] = prefix

def split_line(msg: str) -> Tuple[str, str, List[str]]:
    """Parse message according to rfc 2812 for routing"""
    match = RE_IRCLINE.match(msg)
    if not match:
        raise ValueError('Invalid line')
    prefix = match.group('prefix') or ''
    command = match.group('command')
    params = (match.group('params') or '').split()
    message = match.group('message') or ''
    if message:
        params.append(message)
    return (prefix, command, params)

def pack(field: str, kwargs: Dict[str, Any], default: Optional[Any]=None, sep: str=',') -> str:
    """Util for joining multiple fields with commas"""
    if default is not None:
        value = kwargs.get(field, default)
    else:
        value = kwargs[field]
    if isinstance(value, str):
        return value
    elif isinstance(value, collections.abc.Iterable):
        return sep.join((str(f) for f in value))
    else:
        return str(value)

def get_soup(page=''):
    """Returns a bs4 object of the page requested"""
    content = requests.get('%s/%s' % (BASE_URL, page)).text
    return BeautifulSoup(content)

def equate_initial(name1, name2):
    """Evaluates whether names match, or one name is the initial of the other"""
    if len(name1) == 0 or len(name2) == 0:
        return False
    if len(name1) == 1 or len(name2) == 1:
        return name1[0] == name2[0]
    return name1 == name2

def equate_prefix(name1, name2):
    """Evaluates whether names match, or one name prefixes another"""
    if len(name1) == 0 or len(name2) == 0:
        return False
    return name1.startswith(name2) or name2.startswith(name1)

def make_ascii(word):
    """Converts unicode-specific characters to their equivalent ascii"""
    if sys.version_info < (3, 0, 0):
        word = unicode(word)
    else:
        word = str(word)
    normalized = unicodedata.normalize('NFKD', word)
    return normalized.encode('ascii', 'ignore').decode('utf-8')

def seq_ratio(word1, word2):
    """Returns sequence match ratio for two words"""
    raw_ratio = SequenceMatcher(None, word1, word2).ratio()
    return int(round(100 * raw_ratio))

def deep_update_dict(default, options):
    """Updates the values in a nested dict, while unspecified values will remain
    unchanged"""
    for key in options.keys():
        default_setting = default.get(key)
        new_setting = options.get(key)
        if isinstance(default_setting, dict):
            deep_update_dict(default_setting, new_setting)
        else:
            default[key] = new_setting

def template_to_base_path(template, google_songs):
    """Get base output path for a list of songs for download."""
    if template == os.getcwd() or template == '%suggested%':
        base_path = os.getcwd()
    else:
        template = os.path.abspath(template)
        song_paths = [template_to_filepath(template, song) for song in google_songs]
        base_path = os.path.dirname(os.path.commonprefix(song_paths))
    return base_path

def raw_encode(data):
    """Special case serializer."""
    content_type = 'application/data'
    payload = data
    if isinstance(payload, unicode):
        content_encoding = 'utf-8'
        payload = payload.encode(content_encoding)
    else:
        content_encoding = 'binary'
    return (content_type, content_encoding, payload)

def register_yaml():
    """Register a encoder/decoder for YAML serialization.

    It is slower than JSON, but allows for more data types
    to be serialized. Useful if you need to send data such as dates"""
    try:
        import yaml
        registry.register('yaml', yaml.safe_dump, yaml.safe_load, content_type='application/x-yaml', content_encoding='utf-8')
    except ImportError:
        def not_available(*args, **kwargs):
            """In case a client receives a yaml message, but yaml
            isn't installed."""
            raise SerializerNotInstalled('No decoder installed for YAML. Install the PyYAML library')
        registry.register('yaml', None, not_available, 'application/x-yaml')

def register_msgpack():
