def refresh_index(meta, index) -> None:
    """Recalculate the projection, hash_key, and range_key for the given index.

    :param meta: model.Meta to find columns by name
    :param index: The index to refresh"""
    projection_keys = set.union(meta.keys, index.keys)
    proj = index.projection
    mode = proj['mode']
    if mode == 'keys':
        proj['included'] = projection_keys
    elif mode == 'all':
        proj['included'] = meta.columns
    elif mode == 'include':
        if all((isinstance(p, str) for p in proj['included'])):
            proj['included'] = set((meta.columns_by_name[n] for n in proj['included']))
        else:
            proj['included'] = set(proj['included'])
        proj['included'].update(projection_keys)
    if proj['strict']:
        proj['available'] = proj['included']
    else:
        proj['available'] = meta.columns

def is_valid_superset(actual_projection, index):
    """Returns True if the actual index is a valid superset of the expected index"""
    projection_type = actual_projection['ProjectionType']
    if projection_type == 'ALL':
        return True
    meta = index.model.Meta
    provides = set.union(meta.keys, index.keys)
    if projection_type == 'KEYS_ONLY':
        pass
    elif projection_type == 'INCLUDE':
        by_dynamo_name = {column.dynamo_name: column for column in meta.columns}
        provides.update((by_dynamo_name[name] for name in actual_projection['NonKeyAttributes'] if name in by_dynamo_name))
    else:
        logger.info(f"unexpected index ProjectionType '{projection_type}'")
        return False
    expects = index.projection['included']
    return provides.issuperset(expects)

def check_hash_key(query_on, key):
    """Only allows == against query_on.hash_key"""
    return isinstance(key, BaseCondition) and key.operation == '==' and (key.column is query_on.hash_key)

def check_range_key(query_on, key):
    """BeginsWith, Between, or any Comparison except '!=' against query_on.range_key"""
    return isinstance(key, BaseCondition) and key.operation in ('begins_with', 'between', '<', '>', '<=', '>=', '==') and (key.column is query_on.range_key)

def indented(text, level, indent=2):
    """Take a multiline text and indent it as a block"""
    return '\n'.join(('%s%s' % (level * indent * ' ', s) for s in text.splitlines()))

def dumped(text, level, indent=2):
    """Put curly brackets round an indented text"""
    return indented('{
%s
}' % indented(text, level + 1, indent) or 'None', level, indent) + '
'

def scp(args):
    """Transfer files to or from EC2 instance.

    Use "--" to separate scp args from aegea args:

        aegea scp -- -r local_dir instance_name:~/remote_dir"""
    if args.scp_args[0] == '--':
        del args.scp_args[0]
    user_or_hostname_chars = string.ascii_letters + string.digits
    for i, arg in enumerate(args.scp_args):
        if arg[0] in user_or_hostname_chars and ':' in arg:
            hostname, colon, path = arg.partition(':')
            username, at, hostname = hostname.rpartition('@')
            hostname = resolve_instance_public_dns(hostname)
            if not (username or at):
                try:
                    username, at = (get_linux_username(), '@')
                except Exception:
                    logger.info('Unable to determine IAM username, using local username')
            args.scp_args[i] = username + at + hostname + colon + path
    os.execvp('scp', ['scp'] + args.scp_args)

def requires_auth(func):
