def find_unassigned_table_cell(table):
    """Search through a table and return the first [row, column] pair
    who's value is None.

    Parameters
    ----------
    table : list of lists of str

    Returns
    -------
    list of int
        The row column pair of the None type cell"""
    for row in range(len(table)):
        for column in range(len(table[row])):
            if table[row][column] is None:
                return (row, column)
    return (row, column)

def jstimestamp(dte):
    """Convert a date or datetime object into a javsacript timestamp."""
    days = date(dte.year, dte.month, 1).toordinal() - _EPOCH_ORD + dte.day - 1
    hours = days * 24
    if isinstance(dte, datetime):
        hours += dte.hour
        minutes = hours * 60 + dte.minute
        seconds = minutes * 60 + dte.second
        return 1000 * seconds + int(0.001 * dte.microsecond)
    else:
        return 3600000 * hours

def vector_to_symmetric(v):
    """Convert an iterable into a symmetric matrix."""
    np = len(v)
    N = (int(sqrt(1 + 8 * np)) - 1) // 2
    if N * (N + 1) // 2 != np:
        raise ValueError('Cannot convert vector to symmetric matrix')
    sym = ndarray((N, N))
    iterable = iter(v)
    for r in range(N):
        for c in range(r + 1):
            sym[r, c] = sym[c, r] = iterable.next()
    return sym

def calmar(sharpe, T=1.0):
    """Calculate the Calmar ratio for a Weiner process

    @param sharpe:    Annualized Sharpe ratio
    @param T:         Time interval in years"""
    x = 0.5 * T * sharpe * sharpe
    return x / qp(x)

def calmarnorm(sharpe, T, tau=1.0):
    """Multiplicator for normalizing calmar ratio to period tau"""
    return calmar(sharpe, tau) / calmar(sharpe, T)

def smedian(olist, nobs):
    """Generalised media for odd and even number of samples"""
    if nobs:
        rem = nobs % 2
        midpoint = nobs // 2
        me = olist[midpoint]
        if not rem:
            me = 0.5 * (me + olist[midpoint - 1])
        return me
    else:
        return NaN

def asarray(x, dtype=None):
    """Convert ``x`` into a ``numpy.ndarray``."""
    iterable = scalarasiter(x)
    if isinstance(iterable, ndarray):
        return iterable
    else:
        if not hasattr(iterable, '__len__'):
            iterable = list(iterable)
        if dtype == object_type:
            a = ndarray((len(iterable),), dtype=dtype)
            for i, v in enumerate(iterable):
                a[i] = v
            return a
        else:
            return array(iterable, dtype=dtype)

def ascolumn(x, dtype=None):
    """Convert ``x`` into a ``column``-type ``numpy.ndarray``."""
    x = asarray(x, dtype)
    return x if len(x.shape) >= 2 else x.reshape(len(x), 1)

def get_html_row_count(spans):
    """Get the number of rows"""
    if spans == []:
        return 0
    row_counts = {}
    for span in spans:
        span = sorted(span)
        try:
            row_counts[str(span[0][1])] += get_span_row_count(span)
        except KeyError:
            row_counts[str(span[0][1])] = get_span_row_count(span)
    values = list(row_counts.values())
    return max(values)

def better_ts_function(f):
    """Decorator which check if timeseries has a better
    implementation of the function."""
    fname = f.__name__
    def _(ts, *args, **kwargs):
        func = getattr(ts, fname, None)
        if func:
            return func(*args, **kwargs)
        else:
            return f(ts, *args, **kwargs)
    _.__name__ = fname
    return _

def prange(ts, **kwargs):
    """Rolling Percentage range.

    Value between 0 and 1 indicating the position in the rolling range."""
    mi = ts.rollmin(**kwargs)
    ma = ts.rollmax(**kwargs)
    return (ts - mi) / (ma - mi)

def binOp(op, indx, amap, bmap, fill_vec):
    """Combines the values from two map objects using the indx values
    using the op operator. In situations where there is a missing value
    it will use the callable function handle_missing"""
    def op_or_missing(id):
        va = amap.get(id, None)
        vb = bmap.get(id, None)
        if va is None or vb is None:
            result = fill_vec
        else:
            try:
                result = op(va, vb)
            except Exception:
                result = None
            if result is None:
                result = fill_vec
            return result
    seq_arys = map(op_or_missing, indx)
    data = np.vstack(seq_arys)
    return data

def _setup_states(state_definitions, prev=()):
    """Create a StateList object from a 'states' Workflow attribute."""
    states = list(prev)
    for state_def in state_definitions:
        if len(state_def) != 2:
            raise TypeError("The 'state' attribute of a workflow should be a two-tuple of strings; got %r instead." % (state_def,))
        name, title = state_def
        state = State(name, title)
        if any((st.name == name for st in states)):
            states = [state if st.name == name else st for st in states]
        else:
            states.append(state)
    return StateList(states)

def _setup_transitions(tdef, states, prev=()):
    """Create a TransitionList object from a 'transitions' Workflow attribute.

    Args:
        tdef: list of transition definitions
        states (StateList): already parsed state definitions.
        prev (TransitionList): transition definitions from a parent.

    Returns:
        TransitionList: the list of transitions defined in the 'tdef' argument."""
    trs = list(prev)
    for transition in tdef:
        if len(transition) == 3:
            name, source, target = transition
            if is_string(source) or isinstance(source, State):
                source = [source]
            source = [states[src] for src in source]
            target = states[target]
            tr = Transition(name, source, target)
        else:
            raise TypeError("Elements of the 'transition' attribute of a workflow should be three-tuples; got %r instead." % (transition,))
        if any((prev_tr.name == tr.name for prev_tr in trs)):
            trs = [tr if prev_tr.name == tr.name else prev_tr for prev_tr in trs]
        else:
            trs.append(tr)
    return TransitionList(trs)

def transition(trname='', field='', check=None, before=None, after=None):
    """Decorator to declare a function as a transition implementation."""
    if is_callable(trname):
        raise ValueError("The @transition decorator should be called as @transition(['transition_name'], **kwargs)")
    if check or before or after:
        warnings.warn('The use of check=, before= and after= in @transition decorators is deprecated in favor of @transition_check, @before_transition and @after_transition decorators.', DeprecationWarning, stacklevel=2)
    return TransitionWrapper(trname, field=field, check=check, before=before, after=after)

def _make_hook_dict(fun):
    """Ensure the given function has a xworkflows_hook attribute.

    That attribute has the following structure:
    >>> {
    ...     'before': [('state', <TransitionHook>), ...],
    ... }"""
    if not hasattr(fun, 'xworkflows_hook'):
        fun.xworkflows_hook = {HOOK_BEFORE: [], HOOK_AFTER: [], HOOK_CHECK: [], HOOK_ON_ENTER: [], HOOK_ON_LEAVE: []}
    return fun.xworkflows_hook

def tsiterator(ts, dateconverter=None, desc=None, clean=False, start_value=None, **kwargs):
    """An iterator of timeseries as tuples."""
    dateconverter = dateconverter or default_converter
    yield (['Date'] + ts.names())
    if clean == 'full':
        for dt, value in full_clean(ts, dateconverter, desc, start_value):
            yield ((dt,) + tuple(value))
    else:
        if clean:
            ts = ts.clean()
        for dt, value in ts.items(desc=desc, start_value=start_value):
            dt = dateconverter(dt)
            yield ((dt,) + tuple(value))

def get_longest_line_length(text):
    """Get the length longest line in a paragraph"""
    lines = text.split('\n')
    length = 0
    for i in range(len(lines)):
        if len(lines[i]) > length:
            length = len(lines[i])
    return length

def isnumeric(obj):
    """Return true if obj is a numeric value"""
    from decimal import Decimal
    if type(obj) == Decimal:
        return True
    else:
        try:
            float(obj)
        except:
            return False
        return True

def significant_format(number, decimal_sep='.', thousand_sep=',', n=3):
    """Format a number according to a given number of significant figures.
    """
    str_number = significant(number, n)
    if float(number) < 0:
        sign = '-'
    else:
        sign = ''
    if str_number[0] == '-':
        str_number = str_number[1:]
    if '.' in str_number:
        int_part, dec_part = str_number.split('.')
    else:
        int_part, dec_part = (str_number, '')
    if dec_part:
        dec_part = decimal_sep + dec_part
    if thousand_sep:
        int_part_gd = ''
        for cnt, digit in enumerate(int_part[::-1]):
            if cnt and (not cnt % 3):
                int_part_gd += thousand_sep
            int_part_gd += digit
        int_part = int_part_gd[::-1]
    return sign + int_part + dec_part

def to_text_string(obj, encoding=None):
    """Convert `obj` to (unicode) text string"""
    if PY2:
        if encoding is None:
            return unicode(obj)
        else:
            return unicode(obj, encoding)
    elif encoding is None:
        return str(obj)
    elif isinstance(obj, str):
        return obj
    else:
        return str(obj, encoding)

def text_to_qcolor(text):
    """Create a QColor from specified string
    Avoid warning from Qt when an invalid QColor is instantiated"""
    color = QColor()
    if not is_string(text):
        text = str(text)
    if not is_text_string(text):
        return color
    if text.startswith('#') and len(text) == 7:
        correct = '#0123456789abcdef'
        for char in text:
            if char.lower() not in correct:
                return color
    elif text not in list(QColor.colorNames()):
        return color
    color.setNamedColor(text)
    return color

def ts_merge(series):
    """Merge timeseries into a new :class:`~.TimeSeries` instance.

    :parameter series: an iterable over :class:`~.TimeSeries`."""
    series = iter(series)
    ts = next(series)
    return ts.merge(series)

def ts_bin_op(op_name, ts1, ts2, all=True, fill=None, name=None):
    """Entry point for any arithmetic type function performed on a timeseries
    and/or a scalar.
    op_name - name of the function to be performed
    ts1, ts2 - timeseries or scalars that the function is to performed over
    all - whether all dates should be included in the result
    fill - the value that should be used to represent "missing values"
    name - the name of the resulting time series"""
    op = op_get(op_name)
    fill = fill if fill is not None else settings.missing_value
    if hasattr(fill, '__call__'):
        fill_fn = fill
    else:
        fill_fn = lambda: fill
    name = name or '%s(%s,%s)' % (op_name, ts1, ts2)
    if is_timeseries(ts1):
        ts = ts1
        if is_timeseries(ts2):
            dts, data = op_ts_ts(op_name, op, ts1, ts2, all, fill_fn)
        else:
            dts, data = op_ts_scalar(op_name, op, ts1, ts2, fill_fn)
    elif is_timeseries(ts2):
        ts = ts2
        dts, data = op_scalar_ts(op_name, op, ts1, ts2, fill_fn)
    else:
        return op(ts1, ts2)
    return ts.clone(date=dts, data=data, name=name)

def get_html_column_count(html_string):
    """Gets the number of columns in an html table.

    Paramters
    ---------
    html_string : str

    Returns
    -------
    int
        The number of columns in the table"""
    try:
        from bs4 import BeautifulSoup
    except ImportError:
        print('ERROR: You must have BeautifulSoup to use html2data')
        return
    soup = BeautifulSoup(html_string, 'html.parser')
    table = soup.find('table')
    if not table:
        return 0
    column_counts = []
    trs = table.findAll('tr')
    if len(trs) == 0:
        return 0
    for tr in range(len(trs)):
        if tr == 0:
            tds = trs[tr].findAll('th')
            if len(tds) == 0:
                tds = trs[tr].findAll('td')
        else:
            tds = trs[tr].findAll('td')
        count = 0
        for td in tds:
            if td.has_attr('colspan'):
                count += int(td['colspan'])
            else:
                count += 1
        column_counts.append(count)
    return max(column_counts)

def rollsingle(self, func, window=20, name=None, fallback=False, align='right', **kwargs):
    """Efficient rolling window calculation for min, max type functions
    """
    rname = 'roll_{0}'.format(func)
    if fallback:
        rfunc = getattr(lib.fallback, rname)
    else:
        rfunc = getattr(lib, rname, None)
        if not rfunc:
            rfunc = getattr(lib.fallback, rname)
    data = np.array([list(rfunc(serie, window)) for serie in self.series()])
    name = name or self.makename(func, window=window)
    dates = asarray(self.dates())
    desc = settings.desc
    if align == 'right' and (not desc) or desc:
        dates = dates[window - 1:]
    else:
        dates = dates[:-window + 1]
    return self.clone(dates, data.transpose(), name=name)

def polygen(*coefficients):
    """Polynomial generating function"""
    if not coefficients:
        return lambda i: 0
    else:
        c0 = coefficients[0]
        coefficients = coefficients[1:]
        def _(i):
            v = c0
            for c in coefficients:
                v += c * i
                i *= i
            return v
        return _

def get_git_changeset(filename=None):
    """Returns a numeric identifier of the latest git changeset.

    The result is the UTC timestamp of the changeset in YYYYMMDDHHMMSS format.
    This value isn't guaranteed to be unique, but collisions are very unlikely,
    so it's sufficient for generating the development version numbers."""
    dirname = os.path.dirname(filename or __file__)
    git_show = sh('git show --pretty=format:%ct --quiet HEAD', cwd=dirname)
    timestamp = git_show.partition('\n')[0]
    try:
        timestamp = datetime.datetime.utcfromtimestamp(int(timestamp))
    except ValueError:
        return None
    return timestamp.strftime('%Y%m%d%H%M%S')

def translation(first, second):
    """Create an index of mapped letters (zip to dict)."""
    if len(first) != len(second):
        raise WrongLengthException('The lists are not of the same length!')
    return dict(zip(first, second))

def process_tag(node):
    """Recursively go through a tag's children, converting them, then
    convert the tag itself."""
    text = ''
    exceptions = ['table']
    for element in node.children:
        if isinstance(element, NavigableString):
            text += element
        elif not node.name in exceptions:
            text += process_tag(element)
    try:
        convert_fn = globals()['convert_%s' % node.name.lower()]
        text = convert_fn(node, text)
    except KeyError:
        pass
    return text

def laggeddates(ts, step=1):
    """Lagged iterator over dates"""
    if step == 1:
        dates = ts.dates()
        if not hasattr(dates, 'next'):
            dates = dates.__iter__()
        dt0 = next(dates)
        for dt1 in dates:
            yield (dt1, dt0)
            dt0 = dt1
    else:
        while done:
            done += 1
            lag.append(next(dates))
        for dt1 in dates:
            lag.append(dt1)
            yield (dt1, lag.pop(0))

def make_skiplist(*args, use_fallback=False):
    """Create a new skiplist"""
