def _get_valid_indices(shape, ix0, ix1, iy0, iy1):
    """Give array shape and desired indices, return indices that are
    correctly bounded by the shape."""
    ymax, xmax = shape
    if ix0 < 0:
        ix0 = 0
    if ix1 > xmax:
        ix1 = xmax
    if iy0 < 0:
        iy0 = 0
    if iy1 > ymax:
        iy1 = ymax
    if iy1 <= iy0 or ix1 <= ix0:
        raise IndexError('array[{0}:{1},{2}:{3}] is invalid'.format(iy0, iy1, ix0, ix1))
    return list(map(int, [ix0, ix1, iy0, iy1]))

def _satdet_worker(work_queue, done_queue, sigma=2.0, low_thresh=0.1, h_thresh=0.5, small_edge=60, line_len=200, line_gap=75, percentile=(4.5, 93.0), buf=200):
    """Multiprocessing worker."""
    for fil, chip in iter(work_queue.get, 'STOP'):
        try:
            result = _detsat_one(fil, chip, sigma=sigma, low_thresh=low_thresh, h_thresh=h_thresh, small_edge=small_edge, line_len=line_len, line_gap=line_gap, percentile=percentile, buf=buf, plot=False, verbose=False)
        except Exception as e:
            retcode = False
            result = '{0}: {1}'.format(type(e), str(e))
        else:
            retcode = True
        done_queue.put((retcode, fil, chip, result))
    return True

