def get_config():
    """Get the configurations from .tldrrc and return it as a dict."""
    config_path = path.join(os.environ.get('TLDR_CONFIG_DIR') or path.expanduser('~'), '.tldrrc')
    if not path.exists(config_path):
        sys.exit("Can't find config file at: {0}. You may use `tldr init` to init the config file.".format(config_path))
    with io.open(config_path, encoding='utf-8') as f:
        try:
            config = yaml.safe_load(f)
        except yaml.scanner.ScannerError:
            sys.exit('The config file is not a valid YAML file.')
    supported_colors = ['black', 'red', 'green', 'yellow', 'blue', 'magenta', 'cyan', 'white']
    if not set(config['colors'].values()).issubset(set(supported_colors)):
        sys.exit('Unsupported colors in config file: {0}.'.format(', '.join(set(config['colors'].values()) - set(supported_colors))))
    if not path.exists(config['repo_directory']):
        sys.exit("Can't find the tldr repo, check the `repo_directory` setting in config file.")
    return config

def init():
    """Init config file."""
    default_config_path = path.join(os.environ.get('TLDR_CONFIG_DIR') or path.expanduser('~'), '.tldrrc')
    if path.exists(default_config_path):
        click.echo('There is already a config file exists, skip initializing it.')
    else:
        repo_path = click.prompt('Input the tldr repo path(absolute path)')
        if not path.exists(repo_path):
            sys.exit('Repo path not exist, clone it first.')
        platform = click.prompt('Input your platform(linux, osx or sunos)')
        if platform not in ['linux', 'osx', 'sunos']:
            sys.exit('Platform should be in linux, osx or sunos.')
        colors = {'description': 'blue', 'usage': 'green', 'command': 'cyan'}
        config = {'repo_directory': repo_path, 'colors': colors, 'platform': platform}
        with open(default_config_path, 'w') as f:
            f.write(yaml.safe_dump(config, default_flow_style=False))
        click.echo('Initializing the config file at {0}'.format(default_config_path))

def set_table(genome, table, table_name, connection_string, metadata):
    """alter the table to work between different
    dialects"""
    table = Table(table_name, genome._metadata, autoload=True, autoload_with=genome.bind, extend_existing=True)
    for i, idx in enumerate(table.indexes):
        idx.name = table_name + '.' + idx.name + '_ix' + str(i)
    cols = []
    for i, col in enumerate(table.columns):
        if isinstance(col.type, (LONGBLOB, ENUM)):
            if 'sqlite' in connection_string:
                col.type = VARCHAR()
            elif 'postgres' in connection_string:
                if isinstance(col.type, ENUM):
                    col.type = PG_ENUM(*col.type.enums, name=col.name, create_type=True)
                else:
                    col.type = VARCHAR()
        elif str(col.type) == 'VARCHAR' and ('mysql' in connection_string or 'postgres' in connection_string):
            if col.type.length is None:
                col.type.length = 48 if col.name != 'description' else None
        if not 'mysql' in connection_string:
            if str(col.type).lower().startswith('set('):
                col.type = VARCHAR(15)
        cols.append(col)
    table = Table(table_name, genome._metadata, *cols, autoload_replace=True, extend_existing=True)
    return table

def staticfile_node(parser, token, optimize_if_possible=False):
    """For example:
         {% staticfile "/js/foo.js" %}
         or
         {% staticfile "/js/foo.js" as variable_name %}
    Or for multiples:
         {% staticfile "/foo.js; /bar.js" %}
         or
         {% staticfile "/foo.js; /bar.js" as variable_name %}"""
    args = token.split_contents()
    tag = args[0]
    if len(args) == 4 and args[-2] == 'as':
        context_name = args[-1]
        args = args[:-2]
    else:
        context_name = None
    filename = parser.compile_filter(args[1])
    return StaticFileNode(filename, symlink_if_possible=_CAN_SYMLINK, optimize_if_possible=optimize_if_possible, context_name=context_name)

def _mkdir(newdir):
    """works the way a good mkdir should :)
    - already exists, silently complete
    - regular file in the way, raise an exception
    - parent directory(ies) does not exist, make them as well"""
    if os.path.isdir(newdir):
        pass
    elif os.path.isfile(newdir):
        raise OSError("a file with the same name as the desired dir, '%s', already exists." % newdir)
    else:
        head, tail = os.path.split(newdir)
        if head and (not os.path.isdir(head)):
            _mkdir(head)
        if tail:
            os.mkdir(newdir)

def encode_float(encoder, pcm, frame_size, max_data_bytes):
    """Encodes an Opus frame from floating point input"""
    pcm = ctypes.cast(pcm, c_float_pointer)
    data = (ctypes.c_char * max_data_bytes)()
    result = _encode_float(encoder, pcm, frame_size, data, max_data_bytes)
    if result < 0:
        raise OpusError(result)
    return array.array('c', data[:result]).tostring()

def query(request):
    """Query encoder/decoder with a request value"""
    def inner(func, obj):
        result_code = func(obj, request)
        if result_code is not constants.OK:
            raise OpusError(result_code)
        return result_code
    return inner

def get(request, result_type):
    """Get CTL value from a encoder/decoder"""
    def inner(func, obj):
        result = result_type()
        result_code = func(obj, request, ctypes.byref(result))
        if result_code is not constants.OK:
            raise OpusError(result_code)
        return result.value
    return inner

def set(request):
    """Set new CTL value to a encoder/decoder"""
    def inner(func, obj, value):
        result_code = func(obj, request, value)
        if result_code is not constants.OK:
            raise OpusError(result_code)
    return inner

def string_support(py3enc):
    """Create byte-to-string and string-to-byte conversion functions for
    internal use.

    :param py3enc: Encoding used by Python 3 environment.
    :type py3enc: str"""
    if sys.version < '3':
        def bytes2str(b):
            """Identity, returns the argument string (bytes)."""
            return b
        def str2bytes(s):
            """Identity, returns the argument string (bytes)."""
            return s
    else:
        def bytes2str(b):
            """Transforms bytes into string (Unicode)."""
            return b.decode(py3enc)
        def str2bytes(u):
            """Transforms Unicode into string (bytes)."""
            return u.encode(py3enc)
    return (bytes2str, str2bytes)

def split_sig(params):
    """Split a list of parameters/types by commas,
    whilst respecting brackets.

    For example:
      String arg0, int arg2 = 1, List<int> arg3 = [1, 2, 3]
      => ['String arg0', 'int arg2 = 1', 'List<int> arg3 = [1, 2, 3]']"""
    result = []
    current = ''
    level = 0
    for char in params:
        if char in ('<', '{', '['):
            level += 1
        elif char in ('>', '}', ']'):
            level -= 1
        if char != ',' or level > 0:
            current += char
        elif char == ',' and level == 0:
            result.append(current)
            current = ''
    if current.strip() != '':
        result.append(current)
    return result

def parse_method_signature(sig):
    """Parse a method signature of the form: modifier* type name (params)"""
    match = METH_SIG_RE.match(sig.strip())
    if not match:
        raise RuntimeError('Method signature invalid: ' + sig)
    modifiers, return_type, name, generic_types, params = match.groups()
    if params.strip() != '':
        params = split_sig(params)
        params = [parse_param_signature(x) for x in params]
    else:
        params = []
    return (modifiers.split(), return_type, name, generic_types, params)

def parse_property_signature(sig):
    """Parse a property signature of the form:
    modifier* type name { (get;)? (set;)? }"""
    match = PROP_SIG_RE.match(sig.strip())
    if not match:
        raise RuntimeError('Property signature invalid: ' + sig)
    groups = match.groups()
    if groups[0] is not None:
        modifiers = [x.strip() for x in groups[:-4]]
        groups = groups[-4:]
    else:
        modifiers = []
        groups = groups[1:]
    typ, name, getter, setter = groups
    return (modifiers, typ, name, getter is not None, setter is not None)

def parse_indexer_signature(sig):
    """Parse a indexer signature of the form:
    modifier* type this[params] { (get;)? (set;)? }"""
    match = IDXR_SIG_RE.match(sig.strip())
    if not match:
        raise RuntimeError('Indexer signature invalid: ' + sig)
    modifiers, return_type, params, getter, setter = match.groups()
    params = split_sig(params)
    params = [parse_param_signature(x) for x in params]
    return (modifiers.split(), return_type, params, getter is not None, setter is not None)

def parse_param_signature(sig):
    """Parse a parameter signature of the form: type name (= default)?"""
    match = PARAM_SIG_RE.match(sig.strip())
    if not match:
        raise RuntimeError('Parameter signature invalid, got ' + sig)
    groups = match.groups()
    modifiers = groups[0].split()
    typ, name, _, default = groups[-4:]
    return ParamTuple(name=name, typ=typ, default=default, modifiers=modifiers)

def parse_type_signature(sig):
    """Parse a type signature"""
    match = TYPE_SIG_RE.match(sig.strip())
    if not match:
        raise RuntimeError('Type signature invalid, got ' + sig)
    groups = match.groups()
    typ = groups[0]
    generic_types = groups[1]
    if not generic_types:
        generic_types = []
    else:
        generic_types = split_sig(generic_types[1:-1])
    is_array = groups[2] is not None
    return (typ, generic_types, is_array)

def parse_attr_signature(sig):
    """Parse an attribute signature"""
    match = ATTR_SIG_RE.match(sig.strip())
    if not match:
        raise RuntimeError('Attribute signature invalid, got ' + sig)
    name, _, params = match.groups()
    if params is not None and params.strip() != '':
        params = split_sig(params)
        params = [parse_param_signature(x) for x in params]
    else:
        params = []
    return (name, params)

def get_msdn_ref(name):
    """Try and create a reference to a type on MSDN"""
    in_msdn = False
    if name in MSDN_VALUE_TYPES:
        name = MSDN_VALUE_TYPES[name]
        in_msdn = True
    if name.startswith('System.'):
        in_msdn = True
    if in_msdn:
        link = name.split('<')[0]
        if link in MSDN_LINK_MAP:
            link = MSDN_LINK_MAP[link]
        else:
            link = link.lower()
        url = 'https://msdn.microsoft.com/en-us/library/' + link + '.aspx'
        node = nodes.reference(name, shorten_type(name))
        node['refuri'] = url
        node['reftitle'] = name
        return node
    else:
        return None

def shorten_type(typ):
    """Shorten a type. E.g. drops 'System.'"""
    offset = 0
    for prefix in SHORTEN_TYPE_PREFIXES:
        if typ.startswith(prefix):
            if len(prefix) > offset:
                offset = len(prefix)
    return typ[offset:]

def packet_get_nb_frames(data, length=None):
    """Gets the number of frames in an Opus packet"""
    data_pointer = ctypes.c_char_p(data)
    if length is None:
        length = len(data)
    result = _packet_get_nb_frames(data_pointer, ctypes.c_int(length))
    if result < 0:
        raise OpusError(result)
    return result

def diff(old_html, new_html, cutoff=0.0, plaintext=False, pretty=False):
    """Show the differences between the old and new html document, as html.

    Return the document html with extra tags added to show changes. Add <ins>
    tags around newly added sections, and <del> tags to show sections that have
    been deleted."""
    if plaintext:
        old_dom = parse_text(old_html)
        new_dom = parse_text(new_html)
    else:
        old_dom = parse_minidom(old_html)
        new_dom = parse_minidom(new_html)
    if not check_text_similarity(old_dom, new_dom, cutoff):
        return '<h2>The differences from the previous version are too large to show concisely.</h2>'
    dom = dom_diff(old_dom, new_dom)
    if not plaintext:
        fix_lists(dom)
        fix_tables(dom)
    body_elements = dom.getElementsByTagName('body')
    if len(body_elements) == 1:
        dom = body_elements[0]
    return minidom_tostring(dom, pretty=pretty)

def match_indices(match):
    """Yield index tuples (old_index, new_index) for each place in the match."""
    a, b, size = match
    for i in range(size):
        yield (a + i, b + i)

def get_opcodes(matching_blocks):
    """Use difflib to get the opcodes for a set of matching blocks."""
    sm = difflib.SequenceMatcher(a=[], b=[])
    sm.matching_blocks = matching_blocks
    return sm.get_opcodes()

def remove_insignificant_text_nodes(dom):
    """For html elements that should not have text nodes inside them, remove all
    whitespace. For elements that may have text, collapse multiple spaces to a
    single space."""
    nodes_to_remove = []
    for node in walk_dom(dom):
        if is_text(node):
            text = node.nodeValue
            if node.parentNode.tagName in _non_text_node_tags:
                nodes_to_remove.append(node)
            else:
                node.nodeValue = re.sub('\\s+', ' ', text)
    for node in nodes_to_remove:
        remove_node(node)

def get_child(parent, child_index):
    """Get the child at the given index, or return None if it doesn't exist."""
    if child_index < 0 or child_index >= len(parent.childNodes):
        return None
    return parent.childNodes[child_index]

def get_location(dom, location):
    """Get the node at the specified location in the dom.
    Location is a sequence of child indices, starting at the children of the
    root element. If there is no node at this location, raise a ValueError."""
    node = dom.documentElement
    for i in location:
        node = get_child(node, i)
        if not node:
            raise ValueError('Node at location %s does not exist.' % location)
    return node

def tree_words(node):
    """Return all the significant text below the given node as a list of words.
    >>> list(tree_words(parse_minidom('<h1>one</h1> two <div>three<em>four</em></div>')))
    ['one', 'two', 'three', 'four']"""
    for word in split_text(tree_text(node)):
        word = word.strip()
        if word:
            yield word

def tree_text(node):
    """>>> tree_text(parse_minidom('<h1>one</h1>two<div>three<em>four</em></div>'))
    'one two three four'"""
    text = []
    for descendant in walk_dom(node):
        if is_text(descendant):
            text.append(descendant.nodeValue)
    return ' '.join(text)

def insert_or_append(parent, node, next_sibling):
    """Insert the node before next_sibling. If next_sibling is None, append the node last instead."""
    if next_sibling:
        parent.insertBefore(node, next_sibling)
    else:
        parent.appendChild(node)

def unwrap(node):
    """Remove a node, replacing it with its children."""
    for child in list(node.childNodes):
        node.parentNode.insertBefore(child, node)
    remove_node(node)

def remove_nesting(dom, tag_name):
    """Unwrap items in the node list that have ancestors with the same tag."""
    for node in dom.getElementsByTagName(tag_name):
        for ancestor in ancestors(node):
            if ancestor is node:
                continue
            if ancestor is dom.documentElement:
                break
            if ancestor.tagName == tag_name:
                unwrap(node)
                break

def sort_nodes(dom, cmp_func):
    """Sort the nodes of the dom in-place, based on a comparison function."""
    dom.normalize()
    for node in list(walk_dom(dom, elements_only=True)):
        prev_sib = node.previousSibling
        while prev_sib and cmp_func(prev_sib, node) == 1:
            node.parentNode.insertBefore(node, prev_sib)
            prev_sib = node.previousSibling

def merge_adjacent(dom, tag_name):
    """Merge all adjacent tags with the specified tag name.
    Return the number of merges performed."""
    for node in dom.getElementsByTagName(tag_name):
        prev_sib = node.previousSibling
        if prev_sib and prev_sib.nodeName == node.tagName:
            for child in list(node.childNodes):
                prev_sib.appendChild(child)
            remove_node(node)

def validate_python_identifier_attributes(fully_qualified_name: str, spec: Dict[str, Any], *attributes: str) -> List[InvalidIdentifierError]:
    """Validates a set of attributes as identifiers in a spec"""
    errors: List[InvalidIdentifierError] = []
    checks: List[Tuple[Callable, InvalidIdentifierError.Reason]] = [(lambda x: x.startswith('_'), InvalidIdentifierError.Reason.STARTS_WITH_UNDERSCORE), (lambda x: x.startswith('run_'), InvalidIdentifierError.Reason.STARTS_WITH_RUN), (lambda x: not x.isidentifier(), InvalidIdentifierError.Reason.INVALID_PYTHON_IDENTIFIER)]
    for attribute in attributes:
        if attribute not in spec or spec.get(ATTRIBUTE_INTERNAL, False):
            continue
        for check in checks:
            if check[0](spec[attribute]):
                errors.append(InvalidIdentifierError(fully_qualified_name, spec, attribute, check[1]))
                break
    return errors

def validate_required_attributes(fully_qualified_name: str, spec: Dict[str, Any], *attributes: str) -> List[RequiredAttributeError]:
    """Validates to ensure that a set of attributes are present in spec"""
    return [RequiredAttributeError(fully_qualified_name, spec, attribute) for attribute in attributes if attribute not in spec]

def validate_number_attribute(fully_qualified_name: str, spec: Dict[str, Any], attribute: str, value_type: Union[Type[int], Type[float]]=int, minimum: Optional[Union[int, float]]=None, maximum: Optional[Union[int, float]]=None) -> Optional[InvalidNumberError]:
    """Validates to ensure that the value is a number of the specified type, and lies with the specified range"""
    if attribute not in spec:
        return
    try:
        value = value_type(spec[attribute])
        if minimum is not None and value < minimum or (maximum is not None and value > maximum):
            raise None
    except:
        return InvalidNumberError(fully_qualified_name, spec, attribute, value_type, minimum, maximum)

def validate_enum_attribute(fully_qualified_name: str, spec: Dict[str, Any], attribute: str, candidates: Set[Union[str, int, float]]) -> Optional[InvalidValueError]:
    """Validates to ensure that the value of an attribute lies within an allowed set of candidates"""
    if attribute not in spec:
        return
    if spec[attribute] not in candidates:
        return InvalidValueError(fully_qualified_name, spec, attribute, candidates)

def find_executable(executable, path=None):
    """As distutils.spawn.find_executable, but on Windows, look up
    every extension declared in PATHEXT instead of just `.exe`"""
    if sys.platform != 'win32':
        return distutils.spawn.find_executable(executable, path)
    if path is None:
        path = os.environ['PATH']
    paths = path.split(os.pathsep)
    extensions = os.environ.get('PATHEXT', '.exe').split(os.pathsep)
    base, ext = os.path.splitext(executable)
    if not os.path.isfile(executable):
        for p in paths:
            for ext in extensions:
                f = os.path.join(p, base + ext)
                if os.path.isfile(f):
                    return f
        return None
    else:
        return executable

def time_choices():
    """Return digital time choices every half hour from 00:00 to 23:30."""
    hours = list(range(0, 24))
    times = []
    for h in hours:
        hour = str(h).zfill(2)
        times.append(hour + ':00')
        times.append(hour + ':30')
    return list(zip(times, times))

