def get_now():
    """Allows to access global request and read a timestamp from query."""
    if not get_current_request:
        return datetime.datetime.now()
    request = get_current_request()
    if request:
        openinghours_now = request.GET.get('openinghours-now')
        if openinghours_now:
            return datetime.datetime.strptime(openinghours_now, '%Y%m%d%H%M%S')
    return datetime.datetime.now()

def get_closing_rule_for_now(location):
    """Returns QuerySet of ClosingRules that are currently valid"""
    now = get_now()
    if location:
        return ClosingRules.objects.filter(company=location, start__lte=now, end__gte=now)
    return Company.objects.first().closingrules_set.filter(start__lte=now, end__gte=now)

def is_open(location, now=None):
    """Is the company currently open? Pass "now" to test with a specific
    timestamp. Can be used stand-alone or as a helper."""
    if now is None:
        now = get_now()
    if has_closing_rule_for_now(location):
        return False
    now_time = datetime.time(now.hour, now.minute, now.second)
    if location:
        ohs = OpeningHours.objects.filter(company=location)
    else:
        ohs = Company.objects.first().openinghours_set.all()
    for oh in ohs:
        is_open = False
        if oh.weekday == now.isoweekday() and oh.from_hour <= now_time and (now_time <= oh.to_hour):
            is_open = oh
        if oh.weekday == now.isoweekday() and oh.from_hour <= now_time and (oh.to_hour < oh.from_hour and now_time < datetime.time(23, 59, 59)):
            is_open = oh
        if oh.weekday == (now.isoweekday() - 1) % 7 and oh.from_hour >= now_time and (oh.to_hour >= now_time) and (oh.to_hour < oh.from_hour):
            is_open = oh
        if is_open is not False:
            return oh
    return False

def next_time_open(location):
    """Returns the next possible opening hours object, or (False, None)
    if location is currently open or there is no such object
    I.e. when is the company open for the next time?"""
    if not is_open(location):
        now = get_now()
        now_time = datetime.time(now.hour, now.minute, now.second)
        found_opening_hours = False
        for i in range(8):
            l_weekday = (now.isoweekday() + i) % 7
            ohs = OpeningHours.objects.filter(company=location, weekday=l_weekday).order_by('weekday', 'from_hour')
            if ohs.count():
                for oh in ohs:
                    future_now = now + datetime.timedelta(days=i)
                    tmp_now = datetime.datetime(future_now.year, future_now.month, future_now.day, oh.from_hour.hour, oh.from_hour.minute, oh.from_hour.second)
                    if tmp_now < now:
                        tmp_now = now
                    if is_open(location, now=tmp_now):
                        found_opening_hours = oh
                        break
                if found_opening_hours is not False:
                    return (found_opening_hours, tmp_now)
    return (False, None)

def _detect_encoding(data=None):
    """Return the default system encoding. If data is passed, try
    to decode the data with the default system encoding or from a short
    list of encoding types to test.

    Args:
        data - list of lists
    Returns:
        enc - system encoding"""
    import locale
    enc_list = ['utf-8', 'latin-1', 'iso8859-1', 'iso8859-2', 'utf-16', 'cp720']
    code = locale.getpreferredencoding(False)
    if data is None:
        return code
    if code.lower() not in enc_list:
        enc_list.insert(0, code.lower())
    for c in enc_list:
        try:
            for line in data:
                line.decode(c)
        except (UnicodeDecodeError, UnicodeError, AttributeError):
            continue
        return c
    print('Encoding not detected. Please pass encoding value manually')

def iso_day_to_weekday(d):
    """Returns the weekday's name given a ISO weekday number;
    "today" if today is the same weekday."""
    if int(d) == utils.get_now().isoweekday():
        return _('today')
    for w in WEEKDAYS:
        if w[0] == int(d):
            return w[1]

