def zmq_send_data(socket, data, flags=0, copy=True, track=False):
    """Send data, e.g. {key: np.ndarray}, with metadata"""
    header, payload = ([], [])
    for key in sorted(data.keys()):
        arr = data[key]
        if not isinstance(arr, np.ndarray):
            raise DataError('Only ndarray types can be serialized')
        header.append(dict(dtype=str(arr.dtype), shape=arr.shape, key=key, aligned=arr.flags['ALIGNED']))
        payload.append(arr)
    msg = [json.dumps(header).encode('ascii')]
    msg.extend(payload)
    return socket.send_multipart(msg, flags, copy=copy, track=track)

def npz_generator(npz_path):
    """Generate data from an npz file."""
    npz_data = np.load(npz_path)
    X = npz_data['X']
    y = npz_data['Y']
    n = X.shape[0]
    while True:
        i = np.random.randint(0, n)
        yield {'X': X[i], 'Y': y[i]}

def get(key, default=None):
    """Searches os.environ. If a key is found try evaluating its type else;
    return the string.

    returns: k->value (type as defined by ast.literal_eval)"""
    try:
        return ast.literal_eval(os.environ.get(key.upper(), default))
    except (ValueError, SyntaxError):
        return os.environ.get(key.upper(), default)

def load(filepath=None):
    """Reads a .env file into os.environ.

    For a set filepath, open the file and read contents into os.environ.
    If filepath is not set then look in current dir for a .env file."""
    if filepath and os.path.exists(filepath):
        pass
    else:
        if not os.path.exists('.env'):
            return False
        filepath = os.path.join('.env')
    for key, value in _get_line_(filepath):
        os.environ.setdefault(key, str(value))
    return True

def _get_line_(filepath):
    """Gets each line from the file and parse the data.
    Attempt to translate the value into a python type is possible
    (falls back to string)."""
    for line in open(filepath):
        line = line.strip()
        if line.startswith('#') or '=' not in line:
            continue
        key, value = line.split('=', 1)
        key = key.strip().upper()
        value = value.strip()
        if not (key and value):
            continue
        try:
            value = ast.literal_eval(value)
        except (ValueError, SyntaxError):
            pass
        yield (key, value)

def compute_distances_dict(egg):
    """Creates a nested dict of distances"""
    pres, rec, features, dist_funcs = parse_egg(egg)
    pres_list = list(pres)
    features_list = list(features)
    distances = {}
    for idx1, item1 in enumerate(pres_list):
        distances[item1] = {}
        for idx2, item2 in enumerate(pres_list):
            distances[item1][item2] = {}
            for feature in dist_funcs:
                distances[item1][item2][feature] = builtin_dist_funcs[dist_funcs[feature]](features_list[idx1][feature], features_list[idx2][feature])
    return distances

def default_dist_funcs(dist_funcs, feature_example):
    """Fills in default distance metrics for fingerprint analyses"""
    if dist_funcs is None:
        dist_funcs = dict()
    for key in feature_example:
        if key in dist_funcs:
            pass
        if key == 'item':
            pass
        elif isinstance(feature_example[key], (six.string_types, six.binary_type)):
            dist_funcs[key] = 'match'
        elif isinstance(feature_example[key], (int, np.integer, float)) or all([isinstance(i, (int, np.integer, float)) for i in feature_example[key]]):
            dist_funcs[key] = 'euclidean'
    return dist_funcs

def stack_eggs(eggs, meta='concatenate'):
    """Takes a list of eggs, stacks them and reindexes the subject number

    Parameters
    ----------
    eggs : list of Egg data objects
        A list of Eggs that you want to combine
    meta : string
        Determines how the meta data of each Egg combines. Default is 'concatenate'
        'concatenate' concatenates keys in meta data dictionary shared between eggs, and copies non-overlapping keys
        'separate' keeps the Eggs' meta data dictionaries separate, with each as a list index in the stacked meta data


    Returns
    ----------
    new_egg : Egg data object
        A mega egg comprised of the input eggs stacked together"""
    from .egg import Egg
    pres = [egg.pres.loc[sub, :].values.tolist() for egg in eggs for sub in egg.pres.index.levels[0].values.tolist()]
    rec = [egg.rec.loc[sub, :].values.tolist() for egg in eggs for sub in egg.rec.index.levels[0].values.tolist()]
    if meta is 'concatenate':
        new_meta = {}
        for egg in eggs:
            for key in egg.meta:
                if key in new_meta:
                    new_meta[key] = list(new_meta[key])
                    new_meta[key].extend(egg.meta.get(key))
                else:
                    new_meta[key] = egg.meta.get(key)
    elif meta is 'separate':
        new_meta = list((egg.meta for egg in eggs))
    return Egg(pres=pres, rec=rec, meta=new_meta)

def fill_missing(x):
    """Fills in missing lists (assumes end lists are missing)"""
    maxlen = max([len(xi) for xi in x])
    subs = []
    for sub in x:
        if len(sub) < maxlen:
            for i in range(maxlen - len(sub)):
                sub.append([])
            new_sub = sub
        else:
            new_sub = sub
        subs.append(new_sub)
    return subs

def merge_pres_feats(pres, features):
    """Helper function to merge pres and features to support legacy features argument"""
    sub = []
    for psub, fsub in zip(pres, features):
        exp = []
        for pexp, fexp in zip(psub, fsub):
            lst = []
            for p, f in zip(pexp, fexp):
                p.update(f)
                lst.append(p)
            exp.append(lst)
        sub.append(exp)
    return sub

def shuffle_egg(egg):
    """Shuffle an Egg's recalls"""
    from .egg import Egg
    pres, rec, features, dist_funcs = parse_egg(egg)
    if pres.ndim == 1:
        pres = pres.reshape(1, pres.shape[0])
        rec = rec.reshape(1, rec.shape[0])
        features = features.reshape(1, features.shape[0])
    for ilist in range(rec.shape[0]):
        idx = np.random.permutation(rec.shape[1])
        rec[ilist, :] = rec[ilist, idx]
    return Egg(pres=pres, rec=rec, features=features, dist_funcs=dist_funcs)

def correlation(a, b):
    """Returns correlation distance between a and b"""
    if isinstance(a, list):
        a = np.array(a)
    if isinstance(b, list):
        b = np.array(b)
    a = a.reshape(1, -1)
    b = b.reshape(1, -1)
    return cdist(a, b, 'correlation')

def euclidean(a, b):
    """Returns euclidean distance between a and b"""
    return np.linalg.norm(np.subtract(a, b))

