def get_package_release_from_pypi(pkg_name, version, pypi_json_api_url, allowed_classifiers):
    """No classifier-based selection of Python packages is currently implemented: for now we don't fetch any .whl or .egg
    Eventually, we should select the best release available, based on the classifier & PEP 425: https://www.python.org/dev/peps/pep-0425/
    E.g. a wheel when available but NOT for tornado 4.3 for example, where available wheels are only for Windows.
    Note also that some packages don't have .whl distributed, e.g. https://bugs.launchpad.net/lxml/+bug/1176147"""
    matching_releases = get_package_releases_matching_version(pkg_name, version, pypi_json_api_url)
    src_releases = [release for release in matching_releases if release['python_version'] == 'source']
    if src_releases:
        return select_src_release(src_releases, pkg_name, target_classifiers=('py2.py3-none-any',), select_arbitrary_version_if_none_match=True)
    if allowed_classifiers:
        return select_src_release(matching_releases, pkg_name, target_classifiers=allowed_classifiers)
    raise PypiQueryError('No source supported found for package {} version {}'.format(pkg_name, version))

def extract_classifier_and_extension(pkg_name, filename):
    """Returns a PEP425-compliant classifier (or 'py2.py3-none-any' if it cannot be extracted),
    and the file extension
    TODO: return a classifier 3-members namedtuple instead of a single string"""
    basename, _, extension = filename.rpartition('.')
    if extension == 'gz' and filename.endswith('.tar.gz'):
        extension = 'tar.gz'
        basename = filename[:-7]
    if basename == pkg_name or basename[len(pkg_name)] != '-':
        return ('py2.py3-none-any', extension)
    basename = basename[len(pkg_name) + 1:]
    classifier_parts = basename.split('-')
    if len(classifier_parts) < 3:
        return ('py2.py3-none-any', extension)
    if len(classifier_parts) == 3:
        _, _, classifier_parts[0] = classifier_parts[0].rpartition('.')
    return ('-'.join(classifier_parts[-3:]), extension)

def format_doc(fun):
    """Formats the documentation in a nicer way and for notebook cells."""
    SEPARATOR = '============================='
    func = cvloop.functions.__dict__[fun]
    doc_lines = ['{}'.format(l).strip() for l in func.__doc__.split('\n')]
    if hasattr(func, '__init__'):
        doc_lines.append(SEPARATOR)
        doc_lines += ['{}'.format(l).strip() for l in func.__init__.__doc__.split('\n')]
    mod_lines = []
    argblock = False
    returnblock = False
    for line in doc_lines:
        if line == SEPARATOR:
            mod_lines.append('\n#### `{}.__init__(...)`:\n\n'.format(fun))
        elif 'Args:' in line:
            argblock = True
            if GENERATE_ARGS:
                mod_lines.append('**{}**\n'.format(line))
        elif 'Returns:' in line:
            returnblock = True
            mod_lines.append('\n**{}**'.format(line))
        elif not argblock and (not returnblock):
            mod_lines.append('{}\n'.format(line))
        elif argblock and (not returnblock) and (':' in line):
            if GENERATE_ARGS:
                mod_lines.append('- *{}:* {}\n'.format(*line.split(':')))
        elif returnblock:
            mod_lines.append(line)
        else:
            mod_lines.append('{}\n'.format(line))
    return mod_lines

def main():
    """Sanitizes the loaded *.ipynb."""
    with open(sys.argv[1], 'r') as nbfile:
        notebook = json.load(nbfile)
    try:
        del notebook['metadata']['kernelspec']
    except KeyError:
        pass
    for cell in notebook['cells']:
        try:
            if cell['cell_type'] == 'code':
                cell['outputs'] = []
                cell['execution_count'] = None
            cell['metadata'] = {}
        except KeyError:
            pass
    with open(sys.argv[1], 'w') as nbfile:
        json.dump(notebook, nbfile, indent=1)

def _slice_required_len(slice_obj):
    """Calculate how many items must be in the collection to satisfy this slice

    returns `None` for slices may vary based on the length of the underlying collection
    such as `lst[-1]` or `lst[::]`"""
    if slice_obj.step and slice_obj.step != 1:
        return None
    if slice_obj.start is None and slice_obj.stop is None:
        return None
    if slice_obj.start and slice_obj.start < 0:
        return None
    if slice_obj.stop and slice_obj.stop < 0:
        return None
    if slice_obj.stop:
        if slice_obj.start and slice_obj.start > slice_obj.stop:
            return 0
        return slice_obj.stop
    return slice_obj.start + 1

def site_cleanup(sender, action, instance, **kwargs):
    """Make sure there is only a single preferences object per site.
    So remove sites from pre-existing preferences objects."""
    if action == 'post_add':
        if isinstance(instance, Preferences) and hasattr(instance.__class__, 'objects'):
            site_conflicts = instance.__class__.objects.filter(sites__in=instance.sites.all()).only('id').distinct()
            for conflict in site_conflicts:
                if conflict.id != instance.id:
                    for site in instance.sites.all():
                        conflict.sites.remove(site)

def to_bytes(s, encoding=None, errors='strict'):
    """Returns a bytestring version of 's',
    encoded as specified in 'encoding'."""
    encoding = encoding or 'utf-8'
    if isinstance(s, bytes):
        if encoding != 'utf-8':
            return s.decode('utf-8', errors).encode(encoding, errors)
        else:
            return s
    if not is_string(s):
        s = string_type(s)
    return s.encode(encoding, errors)

def to_string(s, encoding=None, errors='strict'):
    """Inverse of to_bytes"""
    encoding = encoding or 'utf-8'
    if isinstance(s, bytes):
        return s.decode(encoding, errors)
    if not is_string(s):
        s = string_type(s)
    return s

def date_decimal_hook(dct):
    """The default JSON decoder hook. It is the inverse of
    :class:`stdnet.utils.jsontools.JSONDateDecimalEncoder`."""
    if '__datetime__' in dct:
        return todatetime(dct['__datetime__'])
    elif '__date__' in dct:
