def prange(*x):
    """Progress bar range with `tqdm`"""
    try:
        root = logging.getLogger()
        if len(root.handlers):
            for h in root.handlers:
                if type(h) is logging.StreamHandler and h.level != logging.CRITICAL:
                    from tqdm import tqdm
                    return tqdm(range(*x))
            return range(*x)
        else:
            from tqdm import tqdm
            return tqdm(range(*x))
    except ImportError:
        return range(*x)

def parse_backend(backend):
    """Converts the "backend" into the database connection parameters.
    It returns a (scheme, host, params) tuple."""
    r = urlparse.urlsplit(backend)
    scheme, host = (r.scheme, r.netloc)
    path, query = (r.path, r.query)
    if path and (not query):
        query, path = (path, '')
        if query:
            if query.find('?'):
                path = query
            else:
                query = query[1:]
    if query:
        params = dict(urlparse.parse_qsl(query))
    else:
        params = {}
    return (scheme, host, params)

def getdb(backend=None, **kwargs):
    """get a :class:`BackendDataServer`."""
    if isinstance(backend, BackendDataServer):
        return backend
    backend = backend or settings.DEFAULT_BACKEND
    if not backend:
        return None
    scheme, address, params = parse_backend(backend)
    params.update(kwargs)
    if 'timeout' in params:
        params['timeout'] = int(params['timeout'])
    return _getdb(scheme, address, params)

def DVS(ID, season=None, mission='k2', clobber=False, cadence='lc', model='nPLD'):
    """Show the data validation summary (DVS) for a given target.

    :param str mission: The mission name. Default `k2`
    :param str cadence: The light curve cadence. Default `lc`
    :param bool clobber: If :py:obj:`True`, download and overwrite            existing files. Default :py:obj:`False`"""
    if season is None:
        season = getattr(missions, mission).Season(ID)
    if hasattr(season, '__len__'):
        raise AttributeError('Please choose a `season` for this target: %s.' % season)
    if model == 'nPLD':
        filename = getattr(missions, mission).DVSFile(ID, season, cadence)
    elif cadence == 'sc':
        filename = model + '.sc.pdf'
    else:
        filename = model + '.pdf'
    file = DownloadFile(ID, season=season, mission=mission, filename=filename, clobber=clobber)
    try:
        if platform.system().lower().startswith('darwin'):
            subprocess.call(['open', file])
        elif os.name == 'nt':
            os.startfile(file)
        elif os.name == 'posix':
            subprocess.call(['xdg-open', file])
        else:
            raise Exception('')
    except:
        log.info('Unable to open the pdf. Try opening it manually:')
