def metaphone_processor(words):
    """Double metaphone word processor."""
    for word in words:
        for w in double_metaphone(word):
            if w:
                w = w.strip()
                if w:
                    yield w

def tolerant_metaphone_processor(words):
    """Double metaphone word processor slightly modified so that when no
    words are returned by the algorithm, the original word is returned."""
    for word in words:
        r = 0
        for w in double_metaphone(word):
            if w:
                w = w.strip()
                if w:
                    r += 1
                    yield w
        if not r:
            yield word

def stemming_processor(words):
    """Porter Stemmer word processor"""
    stem = PorterStemmer().stem
    for word in words:
        word = stem(word, 0, len(word) - 1)
        yield word

def Pool(pool='AnyPool', **kwargs):
    """Chooses between the different pools.
    If ``pool == 'AnyPool'``, chooses based on availability."""
    if pool == 'MPIPool':
        return MPIPool(**kwargs)
    elif pool == 'MultiPool':
        return MultiPool(**kwargs)
    elif pool == 'SerialPool':
        return SerialPool(**kwargs)
    elif pool == 'AnyPool':
        if MPIPool.enabled():
            return MPIPool(**kwargs)
        elif MultiPool.enabled():
            return MultiPool(**kwargs)
        else:
            return SerialPool(**kwargs)
    else:
        raise ValueError('Invalid pool ``%s``.' % pool)

def models_from_model(model, include_related=False, exclude=None):
    """Generator of all model in model."""
    if exclude is None:
        exclude = set()
    if model and model not in exclude:
        exclude.add(model)
        if isinstance(model, ModelType) and (not model._meta.abstract):
            yield model
            if include_related:
                exclude.add(model)
                for field in model._meta.fields:
                    if hasattr(field, 'relmodel'):
                        through = getattr(field, 'through', None)
                        for rmodel in (field.relmodel, field.model, through):
                            for m in models_from_model(rmodel, include_related=include_related, exclude=exclude):
                                yield m
                for manytomany in model._meta.manytomany:
                    related = getattr(model, manytomany)
                    for m in models_from_model(related.model, include_related=include_related, exclude=exclude):
                        yield m
        elif not isinstance(model, ModelType) and isclass(model):
            yield model

def get_version(version):
    """Returns a PEP 386-compliant version number from *version*."""
    assert len(version) == 5
    assert version[3] in ('alpha', 'beta', 'rc', 'final')
    parts = 2 if version[2] == 0 else 3
    main = '.'.join(map(str, version[:parts]))
    sub = ''
    if version[3] == 'alpha' and version[4] == 0:
        git_changeset = get_git_changeset()
        if git_changeset:
            sub = '.dev%s' % git_changeset
    elif version[3] != 'final':
        mapping = {'alpha': 'a', 'beta': 'b', 'rc': 'c'}
        sub = mapping[version[3]] + str(version[4])
    return main + sub

def Get_RpRs(d, **kwargs):
    """Returns the value of the planet radius over the stellar radius
    for a given depth :py:obj:`d`, given
    the :py:class:`everest.pysyzygy` transit :py:obj:`kwargs`."""
    if ps is None:
        raise Exception('Unable to import `pysyzygy`.')
    def Depth(RpRs, **kwargs):
        return 1 - ps.Transit(RpRs=RpRs, **kwargs)([kwargs.get('t0', 0.0)])
    def DiffSq(r):
        return 10000000000.0 * (d - Depth(r, **kwargs)) ** 2
    return fmin(DiffSq, [np.sqrt(d)], disp=False)

def Get_rhos(dur, **kwargs):
    """Returns the value of the stellar density for a given transit
    duration :py:obj:`dur`, given
    the :py:class:`everest.pysyzygy` transit :py:obj:`kwargs`."""
    if ps is None:
        raise Exception('Unable to import `pysyzygy`.')
    assert dur >= 0.01 and dur <= 0.5, 'Invalid value for the duration.'
    def Dur(rhos, **kwargs):
        t0 = kwargs.get('t0', 0.0)
        time = np.linspace(t0 - 0.5, t0 + 0.5, 1000)
        try:
            t = time[np.where(ps.Transit(rhos=rhos, **kwargs)(time) < 1)]
        except:
            return 0.0
        return t[-1] - t[0]
    def DiffSq(rhos):
        return (dur - Dur(rhos, **kwargs)) ** 2
    return fmin(DiffSq, [0.2], disp=False)

def Campaign(EPIC, **kwargs):
    """Returns the campaign number(s) for a given EPIC target. If target
    is not found, returns :py:obj:`None`.

    :param int EPIC: The EPIC number of the target."""
    campaigns = []
    for campaign, stars in GetK2Stars().items():
        if EPIC in [s[0] for s in stars]:
            campaigns.append(campaign)
    if len(campaigns) == 0:
        return None
    elif len(campaigns) == 1:
        return campaigns[0]
    else:
        return campaigns

def Channel(EPIC, campaign=None):
    """Returns the channel number for a given EPIC target."""
    if campaign is None:
        campaign = Campaign(EPIC)
    if hasattr(campaign, '__len__'):
        raise AttributeError('Please choose a campaign/season for this target: %s.' % campaign)
    try:
        stars = GetK2Stars()[campaign]
    except KeyError:
        log.warn('Unknown channel for target. Defaulting to channel 2.')
        return 2
    i = np.argmax([s[0] == EPIC for s in stars])
    return stars[i][2]

def Module(EPIC, campaign=None):
    """Returns the module number for a given EPIC target."""
    channel = Channel(EPIC, campaign=campaign)
    nums = {2: 1, 3: 5, 4: 9, 6: 13, 7: 17, 8: 21, 9: 25, 10: 29, 11: 33, 12: 37, 13: 41, 14: 45, 15: 49, 16: 53, 17: 57, 18: 61, 19: 65, 20: 69, 22: 73, 23: 77, 24: 81}
    for c in [channel, channel - 1, channel - 2, channel - 3]:
        if c in nums.values():
            for mod, chan in nums.items():
                if chan == c:
                    return mod
    return None

def Channels(module):
    """Returns the channels contained in the given K2 module."""
    nums = {2: 1, 3: 5, 4: 9, 6: 13, 7: 17, 8: 21, 9: 25, 10: 29, 11: 33, 12: 37, 13: 41, 14: 45, 15: 49, 16: 53, 17: 57, 18: 61, 19: 65, 20: 69, 22: 73, 23: 77, 24: 81}
    if module in nums:
        return [nums[module], nums[module] + 1, nums[module] + 2, nums[module] + 3]
    else:
        return None

def KepMag(EPIC, campaign=None):
    """Returns the *Kepler* magnitude for a given EPIC target."""
    if campaign is None:
        campaign = Campaign(EPIC)
    if hasattr(campaign, '__len__'):
        raise AttributeError('Please choose a campaign/season for this target: %s.' % campaign)
    stars = GetK2Stars()[campaign]
    i = np.argmax([s[0] == EPIC for s in stars])
    return stars[i][1]

def GetNeighboringChannels(channel):
    """Returns all channels on the same module as :py:obj:`channel`."""
    x = divmod(channel - 1, 4)[1]
    return channel + np.array(range(-x, -x + 4), dtype=int)

def GetChunk(time, breakpoints, b, mask=[]):
    """Returns the indices corresponding to a given light curve chunk.

    :param int b: The index of the chunk to return"""
    M = np.delete(np.arange(len(time)), mask, axis=0)
    if b > 0:
        res = M[(M > breakpoints[b - 1]) & (M <= breakpoints[b])]
    else:
        res = M[M <= breakpoints[b]]
    return res

def parse_info(response):
    """Parse the response of Redis's INFO command into a Python dict.
    In doing so, convert byte data into unicode."""
    info = {}
    response = response.decode('utf-8')
    def get_value(value):
        if ',' and '=' not in value:
            return value
        sub_dict = {}
        for item in value.split(','):
            k, v = item.split('=')
            try:
                sub_dict[k] = int(v)
            except ValueError:
                sub_dict[k] = v
        return sub_dict
    data = info
    for line in response.splitlines():
        keyvalue = line.split(':')
        if len(keyvalue) == 2:
            key, value = keyvalue
            try:
                data[key] = int(value)
            except ValueError:
                data[key] = get_value(value)
        else:
            data = {}
            info[line[2:]] = data
    return info

def lnprior(x):
    """Return the log prior given parameter vector `x`."""
    per, t0, b = x
    if b < -1 or b > 1:
        return -np.inf
    elif per < 7 or per > 10:
        return -np.inf
    elif t0 < 1978 or t0 > 1979:
        return -np.inf
    else:
        return 0.0

def lnlike(x, star):
    """Return the log likelihood given parameter vector `x`."""
    ll = lnprior(x)
    if np.isinf(ll):
        return (ll, (np.nan, np.nan))
    per, t0, b = x
    model = TransitModel('b', per=per, t0=t0, b=b, rhos=10.0)(star.time)
    like, d, vard = star.lnlike(model, full_output=True)
    ll += like
    return (ll, (d,))

def direction(theta, phi):
    """Return the direction vector of a cylinder defined
    by the spherical coordinates theta and phi."""
    return np.array([np.cos(phi) * np.sin(theta), np.sin(phi) * np.sin(theta), np.cos(theta)])

def projection_matrix(w):
    """Return the projection matrix  of a direction w."""
    return np.identity(3) - np.dot(np.reshape(w, (3, 1)), np.reshape(w, (1, 3)))

def calc_A(Ys):
    """Return the matrix A from a list of Y vectors."""
    return sum((np.dot(np.reshape(Y, (3, 1)), np.reshape(Y, (1, 3))) for Y in Ys))

def calc_A_hat(A, S):
    """Return the A_hat matrix of A given the skew matrix S"""
    return np.dot(S, np.dot(A, np.transpose(S)))

def preprocess_data(Xs_raw):
    """Translate the center of mass (COM) of the data to the origin.
    Return the prossed data and the shift of the COM"""
    n = len(Xs_raw)
    Xs_raw_mean = sum((X for X in Xs_raw)) / n
    return ([X - Xs_raw_mean for X in Xs_raw], Xs_raw_mean)

def parse_json(json_string, object_type, mappers):
    """This function will use the custom JsonDecoder and the conventions.mappers to recreate your custom object
    in the parse json string state just call this method with the json_string your complete object_type and with your
    mappers dict.
    the mappers dict must contain in the key the object_type (ex. User) and the value will contain a method that get
    key, value (the key will be the name of the object property we like to parse and the value
    will be the properties of the object)"""
    obj = json.loads(json_string, cls=JsonDecoder, object_mapper=mappers.get(object_type, None))
    if obj is not None:
        try:
            obj = object_type(**obj)
        except TypeError:
            initialize_dict, set_needed = Utils.make_initialize_dict(obj, object_type.__init__)
            o = object_type(**initialize_dict)
            if set_needed:
                for key, value in obj.items():
                    setattr(o, key, value)
            obj = o
    return obj

def fitting_rmsd(w_fit, C_fit, r_fit, Xs):
    """Calculate the RMSD of fitting."""
    return np.sqrt(sum(((geometry.point_line_distance(p, C_fit, w_fit) - r_fit) ** 2 for p in Xs)) / len(Xs))

def normalize(v):
    """Normalize a vector based on its 2 norm."""
    if 0 == np.linalg.norm(v):
        return v
    return v / np.linalg.norm(v)

def point_line_distance(p, l_p, l_v):
    """Calculate the distance between a point and a line defined
    by a point and a direction vector."""
    l_v = normalize(l_v)
    u = p - l_p
    return np.linalg.norm(u - np.dot(u, l_v) * l_v)

def seen_nonce(id, nonce, timestamp):
    """Returns True if the Hawk nonce has been seen already."""
    key = '{id}:{n}:{ts}'.format(id=id, n=nonce, ts=timestamp)
    if cache.get(key):
        log.warning('replay attack? already processed nonce {k}'.format(k=key))
        return True
    else:
        log.debug('caching nonce {k}'.format(k=key))
        cache.set(key, True, timeout=getattr(settings, 'HAWK_MESSAGE_EXPIRATION', default_message_expiration) + 5)
        return False

