def split_calls(func):
    """Decorator to split up server calls for methods using url parameters, due to the lenght
    limitation of the URI in Apache. By default 8190 bytes"""
    def wrapper(*args, **kwargs):
        size_limit = 8000
        encoded_url = urllib.urlencode(kwargs)
        if len(encoded_url) > size_limit:
            for key, value in kwargs.iteritems():
                if key in ('logical_file_name', 'block_name', 'lumi_list', 'run_num') and isinstance(value, list):
                    ret_val = []
                    for splitted_param in list_parameter_splitting(data=dict(kwargs), key=key, size_limit=size_limit):
                        try:
                            ret_val.extend(func(*args, **splitted_param))
                        except (TypeError, AttributeError):
                            ret_val = []
                    return ret_val
            raise dbsClientException('Invalid input', 'The lenght of the urlencoded parameters to API %s                                      is exceeding %s bytes and cannot be splitted.' % (func.__name__, size_limit))
        else:
            return func(*args, **kwargs)
    return wrapper

def linked_form(viewset, form_id=None, link=None, link_id=None, method=None):
    """When having foreign key or m2m relationships between models A and B (B has foreign key to A named parent),
    we want to have a form that sits on A's viewset but creates/edits B and sets it relationship to A
    automatically.

    In order to do so, define linked_forms on A's viewset containing a call to linked_form as follows:

    @linked_forms()
    class AViewSet(AngularFormMixin, ...):
        linked_forms = {
            'new-b': linked_form(BViewSet, link='parent')
        }

    Then, there will be a form definition on <aviewset>/pk/forms/new-b, with POST/PATCH operations pointing
    to an automatically created endpoint <aviewset>/pk/linked-endpoint/new-b and detail-route named "new_b"

    :param viewset:     the foreign viewset
    :param form_id:     id of the form on the foreign viewset. If unset, use the default form
    :param link:        either a field name on the foreign viewset or a callable that will get (foreign_instance, this_instance)
    :return:            an internal definition of a linked form"""
    return {'viewset': viewset, 'form_id': form_id, 'link': link, 'link_id': link_id, 'method': method}

def load_if_not_loaded(widget, filenames, verbose=False, delay=0.1, force=False, local=True, evaluator=None):
    """Load a javascript file to the Jupyter notebook context,
    unless it was already loaded."""
    if evaluator is None:
        evaluator = EVALUATOR
    for filename in filenames:
        loaded = False
        if force or not filename in LOADED_JAVASCRIPT:
            js_text = get_text_from_file_name(filename, local)
            if verbose:
                print('loading javascript file', filename, 'with', evaluator)
            evaluator(widget, js_text)
            LOADED_JAVASCRIPT.add(filename)
            loaded = True
        elif verbose:
            print('not reloading javascript file', filename)
        if loaded and delay > 0:
            if verbose:
                print('delaying to allow JS interpreter to sync.')
            time.sleep(delay)

def strip_outer_tag(text):
    """Strips the outer tag, if text starts with a tag.  Not entity aware;
    designed to quickly strip outer tags from lxml cleaner output.  Only
    checks for <p> and <div> outer tags."""
    if not text or not isinstance(text, basestring):
        return text
    stripped = text.strip()
    if (stripped.startswith('<p>') or stripped.startswith('<div>')) and (stripped.endswith('</p>') or stripped.endswith('</div>')):
        return stripped[stripped.index('>') + 1:stripped.rindex('<')]
    return text

def munge_author(author):
    """If an author contains an email and a name in it, make sure it is in
    the format: "name (email)"."""
    if '@' in author:
        emailmatch = re.search('(([a-zA-Z0-9\\_\\-\\.\\+]+)@((\\[[0-9]{1,3}\\.[0-9]{1,3}\\.[0-9]{1,3}\\.)|(([a-zA-Z0-9\\-]+\\.)+))([a-zA-Z]{2,4}|[0-9]{1,3})(\\]?))(\\?subject=\\S+)?', author, re.UNICODE)
        if emailmatch:
            email = emailmatch.group(0)
            author = author.replace(email, u'')
            author = author.replace(u'()', u'')
            author = author.replace(u'<>', u'')
            author = author.replace(u'&lt;&gt;', u'')
            author = author.strip()
            if author and author[0] == u'(':
                author = author[1:]
            if author and author[-1] == u')':
                author = author[:-1]
            author = author.strip()
            return '%s (%s)' % (author, email)
    return author

def base_url(root):
    """Determine the base url for a root element."""
    for attr, value in root.attrib.iteritems():
        if attr.endswith('base') and 'http' in value:
            return value
    return None

def clean_ns(tag):
    """Return a tag and its namespace separately."""
    if '}' in tag:
        split = tag.split('}')
        return (split[0].strip('{'), split[-1])
    return ('', tag)

def xpath(node, query, namespaces={}):
    """A safe xpath that only uses namespaces if available."""
    if namespaces and 'None' not in namespaces:
        return node.xpath(query, namespaces=namespaces)
    return node.xpath(query)

def innertext(node):
    """Return the inner text of a node.  If a node has no sub elements, this
    is just node.text.  Otherwise, it's node.text + sub-element-text +
    node.tail."""
    if not len(node):
        return node.text
    return (node.text or '') + ''.join([etree.tostring(c) for c in node]) + (node.tail or '')

def _parse_date_onblog(dateString):
    """Parse a string according to the OnBlog 8-bit date format"""
    m = _korean_onblog_date_re.match(dateString)
    if not m:
        return
    w3dtfdate = '%(year)s-%(month)s-%(day)sT%(hour)s:%(minute)s:%(second)s%(zonediff)s' % {'year': m.group(1), 'month': m.group(2), 'day': m.group(3), 'hour': m.group(4), 'minute': m.group(5), 'second': m.group(6), 'zonediff': '+09:00'}
    return _parse_date_w3dtf(w3dtfdate)

def _parse_date_nate(dateString):
    """Parse a string according to the Nate 8-bit date format"""
    m = _korean_nate_date_re.match(dateString)
    if not m:
        return
    hour = int(m.group(5))
    ampm = m.group(4)
    if ampm == _korean_pm:
        hour += 12
    hour = str(hour)
    if len(hour) == 1:
        hour = '0' + hour
    w3dtfdate = '%(year)s-%(month)s-%(day)sT%(hour)s:%(minute)s:%(second)s%(zonediff)s' % {'year': m.group(1), 'month': m.group(2), 'day': m.group(3), 'hour': hour, 'minute': m.group(6), 'second': m.group(7), 'zonediff': '+09:00'}
    return _parse_date_w3dtf(w3dtfdate)

def _parse_date_greek(dateString):
    """Parse a string according to a Greek 8-bit date format."""
    m = _greek_date_format_re.match(dateString)
    if not m:
        return
    wday = _greek_wdays[m.group(1)]
    month = _greek_months[m.group(3)]
    rfc822date = '%(wday)s, %(day)s %(month)s %(year)s %(hour)s:%(minute)s:%(second)s %(zonediff)s' % {'wday': wday, 'day': m.group(2), 'month': month, 'year': m.group(4), 'hour': m.group(5), 'minute': m.group(6), 'second': m.group(7), 'zonediff': m.group(8)}
    return _parse_date_rfc822(rfc822date)

def _parse_date_hungarian(dateString):
    """Parse a string according to a Hungarian 8-bit date format."""
    m = _hungarian_date_format_re.match(dateString)
    if not m or m.group(2) not in _hungarian_months:
        return None
    month = _hungarian_months[m.group(2)]
    day = m.group(3)
    if len(day) == 1:
        day = '0' + day
    hour = m.group(4)
    if len(hour) == 1:
        hour = '0' + hour
    w3dtfdate = '%(year)s-%(month)s-%(day)sT%(hour)s:%(minute)s%(zonediff)s' % {'year': m.group(1), 'month': month, 'day': day, 'hour': hour, 'minute': m.group(5), 'zonediff': m.group(6)}
    return _parse_date_w3dtf(w3dtfdate)

def _parse_date_perforce(aDateString):
    """parse a date in yyyy/mm/dd hh:mm:ss TTT format"""
    _my_date_pattern = re.compile('(\\w{,3}), (\\d{,4})/(\\d{,2})/(\\d{2}) (\\d{,2}):(\\d{2}):(\\d{2}) (\\w{,3})')
    m = _my_date_pattern.search(aDateString)
    if m is None:
        return None
    dow, year, month, day, hour, minute, second, tz = m.groups()
    months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
    dateString = '%s, %s %s %s %s:%s:%s %s' % (dow, day, months[int(month) - 1], year, hour, minute, second, tz)
    tm = rfc822.parsedate_tz(dateString)
    if tm:
        return time.gmtime(rfc822.mktime_tz(tm))

def parse_date(dateString):
    """Parses a variety of date formats into a 9-tuple in GMT"""
    if not dateString:
        return None
    for handler in _date_handlers:
        try:
            date9tuple = handler(dateString)
        except (KeyError, OverflowError, ValueError):
            continue
        if not date9tuple:
            continue
        if len(date9tuple) != 9:
            continue
        return date9tuple
    return None

def defer_entity_syncing(wrapped, instance, args, kwargs):
    """A decorator that can be used to defer the syncing of entities until after the method has been run
    This is being introduced to help avoid deadlocks in the meantime as we attempt to better understand
    why they are happening"""
    sync_entities.defer = True
    try:
        return wrapped(*args, **kwargs)
    finally:
        sync_entities.defer = False
        model_objs = list(sync_entities.buffer.values())
        if None in sync_entities.buffer:
            model_objs = list()
        if len(sync_entities.buffer):
            sync_entities(*model_objs)
        sync_entities.buffer = {}

def _get_super_entities_by_ctype(model_objs_by_ctype, model_ids_to_sync, sync_all):
    """Given model objects organized by content type and a dictionary of all model IDs that need
    to be synced, organize all super entity relationships that need to be synced.

    Ensure that the model_ids_to_sync dict is updated with any new super entities
    that need to be part of the overall entity sync"""
    super_entities_by_ctype = defaultdict(lambda: defaultdict(list))
    for ctype, model_objs_for_ctype in model_objs_by_ctype.items():
        entity_config = entity_registry.entity_registry.get(ctype.model_class())
        super_entities = entity_config.get_super_entities(model_objs_for_ctype, sync_all)
        super_entities_by_ctype[ctype] = {ContentType.objects.get_for_model(model_class, for_concrete_model=False): relationships for model_class, relationships in super_entities.items()}
        for super_entity_ctype, relationships in super_entities_by_ctype[ctype].items():
            for sub_entity_id, super_entity_id in relationships:
                model_ids_to_sync[ctype].add(sub_entity_id)
                model_ids_to_sync[super_entity_ctype].add(super_entity_id)
    return super_entities_by_ctype

def _get_model_objs_to_sync(model_ids_to_sync, model_objs_map, sync_all):
    """Given the model IDs to sync, fetch all model objects to sync"""
    model_objs_to_sync = {}
    for ctype, model_ids_to_sync_for_ctype in model_ids_to_sync.items():
        model_qset = entity_registry.entity_registry.get(ctype.model_class()).queryset
        if not sync_all:
            model_objs_to_sync[ctype] = model_qset.filter(id__in=model_ids_to_sync_for_ctype)
        else:
            model_objs_to_sync[ctype] = [model_objs_map[ctype, model_id] for model_id in model_ids_to_sync_for_ctype]
    return model_objs_to_sync

def sync_entities(*model_objs):
    """Syncs entities

    Args:
        model_objs (List[Model]): The model objects to sync. If empty, all entities will be synced"""
    if sync_entities.defer:
        if not model_objs:
            sync_entities.buffer[None] = None
        else:
            for model_obj in model_objs:
                sync_entities.buffer[model_obj.__class__, model_obj.pk] = model_obj
        return False
    EntitySyncer(*model_objs).sync()

def sync_entities_watching(instance):
    """Syncs entities watching changes of a model instance."""
    for entity_model, entity_model_getter in entity_registry.entity_watching[instance.__class__]:
        model_objs = list(entity_model_getter(instance))
        if model_objs:
            sync_entities(*model_objs)

def recursive_path(pack, path):
    """Find paths recursively"""
    matches = []
    for root, _, filenames in os.walk(os.path.join(pack, path)):
        for filename in filenames:
            matches.append(os.path.join(root, filename)[len(pack) + 1:])
    return matches

def delete_entity_signal_handler(sender, instance, **kwargs):
    """Defines a signal handler for syncing an individual entity. Called when
    an entity is saved or deleted."""
    if instance.__class__ in entity_registry.entity_registry:
        Entity.all_objects.delete_for_obj(instance)

def save_entity_signal_handler(sender, instance, **kwargs):
    """Defines a signal handler for saving an entity. Syncs the entity to
    the entity mirror table."""
    if instance.__class__ in entity_registry.entity_registry:
        sync_entities(instance)
    if instance.__class__ in entity_registry.entity_watching:
        sync_entities_watching(instance)

def m2m_changed_entity_signal_handler(sender, instance, action, **kwargs):
    """Defines a signal handler for a manytomany changed signal. Only listens for the
    post actions so that entities are synced once (rather than twice for a pre and post action)."""
    if action == 'post_add' or action == 'post_remove' or action == 'post_clear':
        save_entity_signal_handler(sender, instance, **kwargs)

def turn_off_syncing(for_post_save=True, for_post_delete=True, for_m2m_changed=True, for_post_bulk_operation=True):
    """Disables all of the signals for syncing entities. By default, everything is turned off. If the user wants
    to turn off everything but one signal, for example the post_save signal, they would do:

    turn_off_sync(for_post_save=False)"""
    if for_post_save:
        post_save.disconnect(save_entity_signal_handler, dispatch_uid='save_entity_signal_handler')
    if for_post_delete:
        post_delete.disconnect(delete_entity_signal_handler, dispatch_uid='delete_entity_signal_handler')
    if for_m2m_changed:
        m2m_changed.disconnect(m2m_changed_entity_signal_handler, dispatch_uid='m2m_changed_entity_signal_handler')
    if for_post_bulk_operation:
        post_bulk_operation.disconnect(bulk_operation_signal_handler, dispatch_uid='bulk_operation_signal_handler')

def turn_on_syncing(for_post_save=True, for_post_delete=True, for_m2m_changed=True, for_post_bulk_operation=False):
    """Enables all of the signals for syncing entities. Everything is True by default, except for the post_bulk_operation
    signal. The reason for this is because when any bulk operation occurs on any mirrored entity model, it will
    result in every single entity being synced again. This is not a desired behavior by the majority of users, and
    should only be turned on explicitly."""
    if for_post_save:
        post_save.connect(save_entity_signal_handler, dispatch_uid='save_entity_signal_handler')
    if for_post_delete:
        post_delete.connect(delete_entity_signal_handler, dispatch_uid='delete_entity_signal_handler')
    if for_m2m_changed:
        m2m_changed.connect(m2m_changed_entity_signal_handler, dispatch_uid='m2m_changed_entity_signal_handler')
    if for_post_bulk_operation:
        post_bulk_operation.connect(bulk_operation_signal_handler, dispatch_uid='bulk_operation_signal_handler')

def generate_slug(value):
    """A copy of spectator.core.models.SluggedModelMixin._generate_slug()"""
    alphabet = 'abcdefghijkmnopqrstuvwxyz23456789'
    salt = 'Django Spectator'
    if hasattr(settings, 'SPECTATOR_SLUG_ALPHABET'):
        alphabet = settings.SPECTATOR_SLUG_ALPHABET
    if hasattr(settings, 'SPECTATOR_SLUG_SALT'):
        salt = settings.SPECTATOR_SLUG_SALT
    hashids = Hashids(alphabet=alphabet, salt=salt, min_length=5)
    return hashids.encode(value)

