def raise_for_status(status: int, headers: MutableMapping, data: MutableMapping) -> None:
    """Check request response status

    Args:
        status: Response status
        headers: Response headers
        data: Response data

    Raises:
        :class:`slack.exceptions.RateLimited`: For 429 status code
        :class:`slack.exceptions:HTTPException`:"""
    if status != 200:
        if status == 429:
            if isinstance(data, str):
                error = data
            else:
                error = data.get('error', 'ratelimited')
            try:
                retry_after = int(headers.get('Retry-After', 1))
            except ValueError:
                retry_after = 1
            raise exceptions.RateLimited(retry_after, error, status, headers, data)
        else:
            raise exceptions.HTTPException(status, headers, data)

def decode_body(headers: MutableMapping, body: bytes) -> dict:
    """Decode the response body

    For 'application/json' content-type load the body as a dictionary

    Args:
        headers: Response headers
        body: Response body

    Returns:
        decoded body"""
    type_, encoding = parse_content_type(headers)
    decoded_body = body.decode(encoding)
    if type_ == 'application/json':
        payload = json.loads(decoded_body)
    elif decoded_body == 'ok':
        payload = {'ok': True}
    else:
        payload = {'ok': False, 'data': decoded_body}
    return payload

def parse_content_type(headers: MutableMapping) -> Tuple[Optional[str], str]:
    """Find content-type and encoding of the response

    Args:
        headers: Response headers

    Returns:
        :py:class:`tuple` (content-type, encoding)"""
    content_type = headers.get('content-type')
    if not content_type:
        return (None, 'utf-8')
    else:
        type_, parameters = cgi.parse_header(content_type)
        encoding = parameters.get('charset', 'utf-8')
        return (type_, encoding)

def prepare_request(url: Union[str, methods], data: Optional[MutableMapping], headers: Optional[MutableMapping], global_headers: MutableMapping, token: str, as_json: Optional[bool]=None) -> Tuple[str, Union[str, MutableMapping], MutableMapping]:
    """Prepare outgoing request

    Create url, headers, add token to the body and if needed json encode it

    Args:
        url: :class:`slack.methods` item or string of url
        data: Outgoing data
        headers: Custom headers
        global_headers: Global headers
        token: Slack API token
        as_json: Post JSON to the slack API
    Returns:
        :py:class:`tuple` (url, body, headers)"""
    if isinstance(url, methods):
        as_json = as_json or url.value[3]
        real_url = url.value[0]
    else:
        real_url = url
        as_json = False
    if not headers:
        headers = {**global_headers}
    else:
        headers = {**global_headers, **headers}
    payload: Optional[Union[str, MutableMapping]] = None
    if real_url.startswith(HOOK_URL) or (real_url.startswith(ROOT_URL) and as_json):
        payload, headers = _prepare_json_request(data, token, headers)
    elif real_url.startswith(ROOT_URL) and (not as_json):
        payload = _prepare_form_encoded_request(data, token)
    else:
        real_url = ROOT_URL + real_url
        payload = _prepare_form_encoded_request(data, token)
    return (real_url, payload, headers)

def find_iteration(url: Union[methods, str], itermode: Optional[str]=None, iterkey: Optional[str]=None) -> Tuple[str, str]:
    """Find iteration mode and iteration key for a given :class:`slack.methods`

    Args:
        url: :class:`slack.methods` or string url
        itermode: Custom iteration mode
        iterkey: Custom iteration key

    Returns:
        :py:class:`tuple` (itermode, iterkey)"""
    if isinstance(url, methods):
        if not itermode:
            itermode = url.value[1]
        if not iterkey:
            iterkey = url.value[2]
    if not iterkey or not itermode:
        raise ValueError('Iteration not supported for: {}'.format(url))
    elif itermode not in ITERMODE:
        raise ValueError('Iteration not supported for: {}'.format(itermode))
    return (itermode, iterkey)

def prepare_iter_request(url: Union[methods, str], data: MutableMapping, *, iterkey: Optional[str]=None, itermode: Optional[str]=None, limit: int=200, itervalue: Optional[Union[str, int]]=None) -> Tuple[MutableMapping, str, str]:
    """Prepare outgoing iteration request

    Args:
        url: :class:`slack.methods` item or string of url
        data: Outgoing data
        limit: Maximum number of results to return per call.
        iterkey: Key in response data to iterate over (required for url string).
        itermode: Iteration mode (required for url string) (one of `cursor`, `page` or `timeline`)
        itervalue: Value for current iteration (cursor hash, page or timestamp depending on the itermode)
    Returns:
        :py:class:`tuple` (data, iterkey, itermode)"""
    itermode, iterkey = find_iteration(url, itermode, iterkey)
    if itermode == 'cursor':
        data['limit'] = limit
        if itervalue:
            data['cursor'] = itervalue
    elif itermode == 'page':
        data['count'] = limit
        if itervalue:
            data['page'] = itervalue
    elif itermode == 'timeline':
        data['count'] = limit
        if itervalue:
            data['latest'] = itervalue
    return (data, iterkey, itermode)

def decode_iter_request(data: dict) -> Optional[Union[str, int]]:
    """Decode incoming response from an iteration request

    Args:
        data: Response data

    Returns:
        Next itervalue"""
    if 'response_metadata' in data:
        return data['response_metadata'].get('next_cursor')
    elif 'paging' in data:
        current_page = int(data['paging'].get('page', 1))
        max_page = int(data['paging'].get('pages', 1))
        if current_page < max_page:
            return current_page + 1
    elif 'has_more' in data and data['has_more'] and ('latest' in data):
        return data['messages'][-1]['ts']
    return None

def mongodump(mongo_user, mongo_password, mongo_dump_directory_path, database=None, silent=False):
    """Runs mongodump using the provided credentials on the running mongod
    process.

    WARNING: This function will delete the contents of the provided
    directory before it runs."""
    if path.exists(mongo_dump_directory_path):
        rmtree(mongo_dump_directory_path)
    if silent:
        dump_command = 'mongodump --quiet -u %s -p %s -o %s' % (mongo_user, mongo_password, mongo_dump_directory_path)
    else:
        dump_command = 'mongodump -u %s -p %s -o %s' % (mongo_user, mongo_password, mongo_dump_directory_path)
    if database:
        dump_command += ' --db %s' % database
    call(dump_command, silent=silent)

def mongorestore(mongo_user, mongo_password, backup_directory_path, drop_database=False, silent=False):
    """Warning: Setting drop_database to True will drop the ENTIRE
    CURRENTLY RUNNING DATABASE before restoring.

    Mongorestore requires a running mongod process, in addition the provided
    user must have restore permissions for the database.  A mongolia superuser
    will have more than adequate permissions, but a regular user may not."""
    if not path.exists(backup_directory_path):
        raise Exception('the provided tar directory %s does not exist.' % backup_directory_path)
    if silent:
        mongorestore_command = 'mongorestore --quiet -u %s -p %s %s' % (mongo_user, mongo_password, backup_directory_path)
    else:
        mongorestore_command = 'mongorestore -v -u %s -p %s %s' % (mongo_user, mongo_password, backup_directory_path)
    if drop_database:
        mongorestore_command = mongorestore_command + ' --drop'
    call(mongorestore_command, silent=silent)

def get_backup_file_time_tag(file_name, custom_prefix='backup'):
    """Returns a datetime object computed from a file name string, with
    formatting based on DATETIME_FORMAT."""
    name_string = file_name[len(custom_prefix):]
    time_tag = name_string.split('.', 1)[0]
    return datetime.strptime(time_tag, DATETIME_FORMAT)

def purge_old_files(date_time, directory_path, custom_prefix='backup'):
    """Takes a datetime object and a directory path, runs through files in the
    directory and deletes those tagged with a date from before the provided
    datetime.
    If your backups have a custom_prefix that is not the default ("backup"),
    provide it with the "custom_prefix" kwarg."""
    for file_name in listdir(directory_path):
        try:
            file_date_time = get_backup_file_time_tag(file_name, custom_prefix=custom_prefix)
        except ValueError as e:
            if 'does not match format' in e.message:
                print('WARNING. file(s) in %s do not match naming convention.' % directory_path)
                continue
            raise e
        if file_date_time < date_time:
            remove(directory_path + file_name)

def get_download_uri(package_name, version, source, index_url=None):
    """Use setuptools to search for a package's URI

    @returns: URI string"""
    tmpdir = None
    force_scan = True
    develop_ok = False
    if not index_url:
        index_url = 'http://cheeseshop.python.org/pypi'
    if version:
        pkg_spec = '%s==%s' % (package_name, version)
    else:
        pkg_spec = package_name
    req = pkg_resources.Requirement.parse(pkg_spec)
    pkg_index = MyPackageIndex(index_url)
    try:
        pkg_index.fetch_distribution(req, tmpdir, force_scan, source, develop_ok)
    except DownloadURI as url:
        clean_url = url.value.split('#')[0]
        if not source and (not clean_url.endswith('.egg')) and (not clean_url.endswith('.EGG')):
            return
        else:
            return clean_url

def get_pkglist():
    """Return list of all installed packages

    Note: It returns one project name per pkg no matter how many versions
    of a particular package is installed

    @returns: list of project name strings for every installed pkg"""
    dists = Distributions()
    projects = []
    for dist, _active in dists.get_distributions('all'):
        if dist.project_name not in projects:
            projects.append(dist.project_name)
    return projects

def call_plugins(plugins, method, *arg, **kw):
    """Call all method on plugins in list, that define it, with provided
    arguments. The first response that is not None is returned."""
    for plug in plugins:
        func = getattr(plug, method, None)
        if func is None:
            continue
        result = func(*arg, **kw)
        if result is not None:
            return result
    return None

def load_plugins(builtin=True, others=True):
    """Load plugins, either builtin, others, or both.
    """
    for entry_point in pkg_resources.iter_entry_points('yolk.plugins'):
        try:
            plugin = entry_point.load()
        except KeyboardInterrupt:
            raise
        except Exception as err_msg:
            warn('Unable to load plugin %s: %s' % (entry_point, err_msg), RuntimeWarning)
            continue
        if plugin.__module__.startswith('yolk.plugins'):
            if builtin:
                yield plugin
        elif others:
            yield plugin

def s3_connect(bucket_name, s3_access_key_id, s3_secret_key):
    """Returns a Boto connection to the provided S3 bucket."""
    conn = connect_s3(s3_access_key_id, s3_secret_key)
    try:
        return conn.get_bucket(bucket_name)
    except S3ResponseError as e:
        if e.status == 403:
            raise Exception('Bad Amazon S3 credentials.')
        raise

def s3_list(s3_bucket, s3_access_key_id, s3_secret_key, prefix=None):
    """Lists the contents of the S3 bucket that end in .tbz and match
    the passed prefix, if any."""
    bucket = s3_connect(s3_bucket, s3_access_key_id, s3_secret_key)
    return sorted([key.name for key in bucket.list() if key.name.endswith('.tbz') and (prefix is None or key.name.startswith(prefix))])

def validate_pypi_opts(opt_parser):
    """Check parse options that require pkg_spec

    @returns: pkg_spec"""
    options, remaining_args = opt_parser.parse_args()
    options_pkg_specs = [options.versions_available, options.query_metadata_pypi, options.show_download_links, options.browse_website, options.fetch, options.show_deps]
    for pkg_spec in options_pkg_specs:
        if pkg_spec:
            return pkg_spec

def run_command(cmd, env=None, max_timeout=None):
    """Run command and return its return status code and its output"""
    arglist = cmd.split()
    output = os.tmpfile()
    try:
        pipe = Popen(arglist, stdout=output, stderr=STDOUT, env=env)
    except Exception as errmsg:
        return (1, errmsg)
    if max_timeout:
        start = time.time()
        while pipe.poll() is None:
            time.sleep(0.1)
            if time.time() - start > max_timeout:
                os.kill(pipe.pid, signal.SIGINT)
                pipe.wait()
                return (1, 'Time exceeded')
    pipe.wait()
    output.seek(0)
    return (pipe.returncode, output.read())

def login(request, template_name='registration/login.html', redirect_field_name=REDIRECT_FIELD_NAME, authentication_form=AuthenticationForm, current_app=None, extra_context=None):
    """Displays the login form and handles the login action."""
    redirect_to = request.POST.get(redirect_field_name, request.GET.get(redirect_field_name, ''))
    if request.method == 'POST':
        form = authentication_form(data=request.POST, request=request)
        if form.is_valid():
            netloc = urlparse(redirect_to)[1]
            if not redirect_to:
                redirect_to = settings.LOGIN_REDIRECT_URL
            elif netloc and netloc != request.get_host():
                redirect_to = settings.LOGIN_REDIRECT_URL
            auth_login(request, form.get_user())
            return redirect(redirect_to)
    else:
        form = authentication_form(request)
    current_site = get_current_site(request)
    context = {'form': form, redirect_field_name: redirect_to, 'site': current_site, 'site_name': current_site.name}
    if extra_context is not None:
        context.update(extra_context)
    request.current_app = current_app
    return TemplateResponse(request, template_name, context)

def filter_url(pkg_type, url):
    """Returns URL of specified file type
    'source', 'egg', or 'all'"""
    bad_stuff = ['?modtime', '#md5=']
    for junk in bad_stuff:
        if junk in url:
            url = url.split(junk)[0]
            break
    if url.endswith('-dev'):
        url = url.split('#egg=')[0]
    if pkg_type == 'all':
        return url
    elif pkg_type == 'source':
        valid_source_types = ['.tgz', '.tar.gz', '.zip', '.tbz2', '.tar.bz2']
        for extension in valid_source_types:
            if url.lower().endswith(extension):
                return url
    elif pkg_type == 'egg':
        if url.lower().endswith('.egg'):
            return url

def get_config(config_file):
    """Get configuration from a file."""
    def load(fp):
        try:
            return yaml.safe_load(fp)
        except yaml.YAMLError as e:
            sys.stderr.write(text_type(e))
            sys.exit(1)
    if config_file == '-':
        return load(sys.stdin)
    if not os.path.exists(config_file):
        sys.stderr.write('ERROR: Must either run next to config.yaml or specify a config file.\n' + __doc__)
        sys.exit(2)
    with open(config_file) as fp:
        return load(fp)

def output_results(results, metric, options):
    """Output the results to stdout.

    TODO: add AMPQ support for efficiency"""
    formatter = options['Formatter']
    context = metric.copy()
    try:
        context['dimension'] = list(metric['Dimensions'].values())[0]
    except AttributeError:
        context['dimension'] = ''
    for result in results:
        stat_keys = metric['Statistics']
        if not isinstance(stat_keys, list):
            stat_keys = [stat_keys]
        for statistic in stat_keys:
            context['statistic'] = statistic
            context['Unit'] = result['Unit']
            metric_name = (formatter % context).replace('/', '.').lower()
            line = '{0} {1} {2}\n'.format(metric_name, result[statistic], timegm(result['Timestamp'].timetuple()))
            sys.stdout.write(line)

def round_float(f, digits, rounding=ROUND_HALF_UP):
    """Accurate float rounding from http://stackoverflow.com/a/15398691."""
    return Decimal(str(f)).quantize(Decimal(10) ** (-1 * digits), rounding=rounding)

def float_str(f, min_digits=2, max_digits=6):
    """Returns a string representing a float, where the number of
    significant digits is min_digits unless it takes more digits
    to hit a non-zero digit (and the number is 0 < x < 1).
    We stop looking for a non-zero digit after max_digits."""
    if f >= 1 or f <= 0:
        return str(round_float(f, min_digits))
    start_str = str(round_float(f, max_digits))
    digits = start_str.split('.')[1]
    non_zero_indices = []
    for i, digit in enumerate(digits):
        if digit != '0':
            non_zero_indices.append(i + 1)
    if len(non_zero_indices) == 0:
        num_digits = min_digits
    else:
        min_non_zero_indices = range(non_zero_indices[0], non_zero_indices[-1] + 1)[:min_digits]
        num_digits = min_non_zero_indices[-1]
    return str(round_float(f, num_digits))

def count_function(func):
    """Decorator for functions that return a collection (technically a dict of collections) that should be
    counted up. Also automatically falls back to the Cohort-default filter_fn and normalized_per_mb if
    not specified."""
    @use_defaults
    @wraps(func)
    def wrapper(row, cohort, filter_fn=None, normalized_per_mb=None, **kwargs):
        per_patient_data = func(row=row, cohort=cohort, filter_fn=filter_fn, normalized_per_mb=normalized_per_mb, **kwargs)
        patient_id = row['patient_id']
        if patient_id in per_patient_data:
            count = len(per_patient_data[patient_id])
            if normalized_per_mb:
                count /= float(get_patient_to_mb(cohort)[patient_id])
            return count
        return np.nan
    return wrapper

def count_variants_function_builder(function_name, filterable_variant_function=None):
    """Creates a function that counts variants that are filtered by the provided filterable_variant_function.
    The filterable_variant_function is a function that takes a filterable_variant and returns True or False.

    Users of this builder need not worry about applying e.g. the Cohort's default `filter_fn`. That will be applied as well."""
    @count_function
    def count(row, cohort, filter_fn, normalized_per_mb, **kwargs):
        def count_filter_fn(filterable_variant, **kwargs):
            assert filter_fn is not None, 'filter_fn should never be None, but it is.'
            return (filterable_variant_function(filterable_variant) if filterable_variant_function is not None else True) and filter_fn(filterable_variant, **kwargs)
        patient_id = row['patient_id']
        return cohort.load_variants(patients=[cohort.patient_from_id(patient_id)], filter_fn=count_filter_fn, **kwargs)
    count.__name__ = function_name
    count.__doc__ = str(''.join(inspect.getsourcelines(filterable_variant_function)[0])) if filterable_variant_function is not None else ''
    return count

def count_effects_function_builder(function_name, only_nonsynonymous, filterable_effect_function=None):
    """Create a function that counts effects that are filtered by the provided filterable_effect_function.
    The filterable_effect_function is a function that takes a filterable_effect and returns True or False.

    Users of this builder need not worry about applying e.g. the Cohort's default `filter_fn`. That will be applied as well."""
    @count_function
    def count(row, cohort, filter_fn, normalized_per_mb, **kwargs):
        def count_filter_fn(filterable_effect, **kwargs):
            assert filter_fn is not None, 'filter_fn should never be None, but it is.'
            return (filterable_effect_function(filterable_effect) if filterable_effect_function is not None else True) and filter_fn(filterable_effect, **kwargs)
        patient_id = row['patient_id']
        return cohort.load_effects(only_nonsynonymous=only_nonsynonymous, patients=[cohort.patient_from_id(patient_id)], filter_fn=count_filter_fn, **kwargs)
    count.__name__ = function_name
    count.__doc__ = 'only_nonsynonymous=%s\n' % only_nonsynonymous + str(''.join(inspect.getsourcelines(filterable_effect_function)[0])) if filterable_effect_function is not None else ''
    count.only_nonsynonymous = only_nonsynonymous
    count.filterable_effect_function = filterable_effect_function
    return count

def median_vaf_purity(row, cohort, **kwargs):
    """Estimate purity based on 2 * median VAF.

    Even if the Cohort has a default filter_fn, ignore it: we want to use all variants for
    this estimate."""
    patient_id = row['patient_id']
    patient = cohort.patient_from_id(patient_id)
    variants = cohort.load_variants(patients=[patient], filter_fn=no_filter)
    if patient_id in variants.keys():
        variants = variants[patient_id]
    else:
        return np.nan
    def grab_vaf(variant):
        filterable_variant = FilterableVariant(variant, variants, patient)
        return variant_stats_from_variant(variant, filterable_variant.variant_metadata).tumor_stats.variant_allele_frequency
    vafs = [grab_vaf(variant) for variant in variants]
    return 2 * pd.Series(vafs).median()

def _vcf_is_strelka(variant_file, variant_metadata):
    """Return True if variant_file given is in strelka format
    """
    if 'strelka' in variant_file.lower():
        return True
    elif 'NORMAL' in variant_metadata['sample_info'].keys():
        return True
    else:
        vcf_reader = vcf.Reader(open(variant_file, 'r'))
        try:
            vcf_type = vcf_reader.metadata['content']
        except KeyError:
            vcf_type = ''
        if 'strelka' in vcf_type.lower():
            return True
    return False

def vertical_percent(plot, percent=0.1):
    """Using the size of the y axis, return a fraction of that size."""
    plot_bottom, plot_top = plot.get_ylim()
    return percent * (plot_top - plot_bottom)

def hide_ticks(plot, min_tick_value=None, max_tick_value=None):
    """Hide tick values that are outside of [min_tick_value, max_tick_value]"""
    for tick, tick_value in zip(plot.get_yticklabels(), plot.get_yticks()):
        tick_label = as_numeric(tick_value)
        if tick_label:
            if min_tick_value is not None and tick_label < min_tick_value or (max_tick_value is not None and tick_label > max_tick_value):
                tick.set_visible(False)

def stripboxplot(x, y, data, ax=None, significant=None, **kwargs):
    """Overlay a stripplot on top of a boxplot."""
    ax = sb.boxplot(x=x, y=y, data=data, ax=ax, fliersize=0, **kwargs)
    plot = sb.stripplot(x=x, y=y, data=data, ax=ax, jitter=kwargs.pop('jitter', 0.05), color=kwargs.pop('color', '0.3'), **kwargs)
    if data[y].min() >= 0:
        hide_negative_y_ticks(plot)
    if significant is not None:
        add_significance_indicator(plot=plot, significant=significant)
    return plot

def get_cache_dir(cache_dir, cache_root_dir=None, *args, **kwargs):
    """Return full cache_dir, according to following logic:
        - if cache_dir is a full path (per path.isabs), return that value
        - if not and if cache_root_dir is not None, join two paths
        - otherwise, log warnings and return None
    Separately, if args or kwargs are given, format cache_dir using kwargs"""
    cache_dir = cache_dir.format(*args, **kwargs)
    if path.isabs(cache_dir):
        if cache_root_dir is not None:
            logger.warning('cache_dir ({}) is a full path; ignoring cache_root_dir'.format(cache_dir))
        return cache_dir
    if cache_root_dir is not None:
        return path.join(cache_root_dir, cache_dir)
    else:
        logger.warning('cache dir is not full path & cache_root_dir not given. Caching may not work as expected!')
    return None

def set_attributes(obj, additional_data):
    """Given an object and a dictionary, give the object new attributes from that dictionary.

    Uses _strip_column_name to git rid of whitespace/uppercase/special characters."""
    for key, value in additional_data.items():
        if hasattr(obj, key):
            raise ValueError('Key %s in additional_data already exists in this object' % key)
        setattr(obj, _strip_column_name(key), value)

def generate_random_missense_variants(num_variants=10, max_search=100000, reference='GRCh37'):
    """Generate a random collection of missense variants by trying random variants repeatedly."""
    variants = []
    for i in range(max_search):
        bases = ['A', 'C', 'T', 'G']
        random_ref = choice(bases)
        bases.remove(random_ref)
        random_alt = choice(bases)
        random_contig = choice(['1', '2', '3', '4', '5'])
        random_variant = Variant(contig=random_contig, start=randint(1, 1000000), ref=random_ref, alt=random_alt, ensembl=reference)
        try:
            effects = random_variant.effects()
            for effect in effects:
                if isinstance(effect, Substitution):
                    variants.append(random_variant)
                    break
        except:
            continue
        if len(variants) == num_variants:
            break
    return VariantCollection(variants)

def view_name_from(path):
    """Resolve a path to the full python module name of the related view function"""
    try:
        return CACHED_VIEWS[path]
    except KeyError:
        view = resolve(path)
        module = path
        name = ''
        if hasattr(view.func, '__module__'):
            module = resolve(path).func.__module__
        if hasattr(view.func, '__name__'):
            name = resolve(path).func.__name__
        view = '%s.%s' % (module, name)
        CACHED_VIEWS[path] = view
        return view

def _parse_header_links(response):
    """Parse the links from a Link: header field.

    ..  todo:: Links with the same relation collide at the moment.

    :param bytes value: The header value.

    :rtype: `dict`
    :return: A dictionary of parsed links, keyed by ``rel`` or ``url``."""
    values = response.headers.getRawHeaders(b'link', [b''])
    value = b','.join(values).decode('ascii')
    with LOG_HTTP_PARSE_LINKS(raw_link=value) as action:
        links = {}
        replace_chars = u' \'"'
        for val in re.split(u', *<', value):
            try:
                url, params = val.split(u';', 1)
            except ValueError:
                url, params = (val, u'')
            link = {}
            link[u'url'] = url.strip(u'<> \'"')
            for param in params.split(u';'):
                try:
                    key, value = param.split(u'=')
                except ValueError:
                    break
                link[key.strip(replace_chars)] = value.strip(replace_chars)
            links[link.get(u'rel') or link.get(u'url')] = link
        action.add_success_fields(parsed_links=links)
        return links

def _defer_to_worker(deliver, worker, work, *args, **kwargs):
    """Run a task in a worker, delivering the result as a ``Deferred`` in the
    reactor thread."""
    deferred = Deferred()
    def wrapped_work():
        try:
            result = work(*args, **kwargs)
        except BaseException:
            f = Failure()
            deliver(lambda: deferred.errback(f))
        else:
            deliver(lambda: deferred.callback(result))
    worker.do(wrapped_work)
    return deferred

def _split_zone(server_name, zone_name):
    """Split the zone portion off from a DNS label.

    :param str server_name: The full DNS label.
    :param str zone_name: The zone name suffix."""
    server_name = server_name.rstrip(u'.')
    zone_name = zone_name.rstrip(u'.')
    if not (server_name == zone_name or server_name.endswith(u'.' + zone_name)):
        raise NotInZone(server_name=server_name, zone_name=zone_name)
    return server_name[:-len(zone_name)].rstrip(u'.')

def _get_existing(driver, zone_name, server_name, validation):
    """Get existing validation records."""
    if zone_name is None:
        zones = sorted((z for z in driver.list_zones() if server_name.rstrip(u'.').endswith(u'.' + z.domain.rstrip(u'.'))), key=lambda z: len(z.domain), reverse=True)
        if len(zones) == 0:
            raise NotInZone(server_name=server_name, zone_name=None)
    else:
        zones = [z for z in driver.list_zones() if z.domain == zone_name]
        if len(zones) == 0:
            raise ZoneNotFound(zone_name=zone_name)
    zone = zones[0]
    subdomain = _split_zone(server_name, zone.domain)
    existing = [record for record in zone.list_records() if record.name == subdomain and record.type == 'TXT' and (record.data == validation)]
    return (zone, existing, subdomain)

def _validation(response):
    """Get the validation value for a challenge response."""
    h = hashlib.sha256(response.key_authorization.encode('utf-8'))
    return b64encode(h.digest()).decode()

def load_or_create_client_key(pem_path):
    """Load the client key from a directory, creating it if it does not exist.

    .. note:: The client key that will be created will be a 2048-bit RSA key.

    :type pem_path: ``twisted.python.filepath.FilePath``
    :param pem_path: The certificate directory
        to use, as with the endpoint."""
    acme_key_file = pem_path.asTextMode().child(u'client.key')
    if acme_key_file.exists():
        key = serialization.load_pem_private_key(acme_key_file.getContent(), password=None, backend=default_backend())
    else:
        key = generate_private_key(u'rsa')
        acme_key_file.setContent(key.private_bytes(encoding=serialization.Encoding.PEM, format=serialization.PrivateFormat.TraditionalOpenSSL, encryption_algorithm=serialization.NoEncryption()))
    return JWKRSA(key=key)

def _parse(reactor, directory, pemdir, *args, **kwargs):
    """Parse a txacme endpoint description.

    :param reactor: The Twisted reactor.
    :param directory: ``twisted.python.url.URL`` for the ACME directory to use
        for issuing certs.
    :param str pemdir: The path to the certificate directory to use."""
    def colon_join(items):
        return ':'.join([item.replace(':', '\\:') for item in items])
    sub = colon_join(list(args) + ['='.join(item) for item in kwargs.items()])
    pem_path = FilePath(pemdir).asTextMode()
    acme_key = load_or_create_client_key(pem_path)
    return AutoTLSEndpoint(reactor=reactor, directory=directory, client_creator=partial(Client.from_url, key=acme_key, alg=RS256), cert_store=DirectoryStore(pem_path), cert_mapping=HostDirectoryMap(pem_path), sub_endpoint=serverFromString(reactor, sub))

def lazyread(f, delimiter):
    """Generator which continually reads ``f`` to the next instance
    of ``delimiter``.

    This allows you to do batch processing on the contents of ``f`` without
    loading the entire file into memory.

    :param f: Any file-like object which has a ``.read()`` method.
    :param delimiter: Delimiter on which to split up the file."""
    try:
        running = f.read(0)
    except Exception as e:
        if e.__class__.__name__ == 'IncompleteReadError':
            running = b''
        else:
            raise
    while True:
        new_data = f.read(1024)
        if not new_data:
            yield running
            return
        running += new_data
        while delimiter in running:
            curr, running = running.split(delimiter, 1)
            yield (curr + delimiter)

def generate_private_key(key_type):
    """Generate a random private key using sensible parameters.

    :param str key_type: The type of key to generate. One of: ``rsa``."""
    if key_type == u'rsa':
        return rsa.generate_private_key(public_exponent=65537, key_size=2048, backend=default_backend())
    raise ValueError(key_type)

def tap(f):
    """"Tap" a Deferred callback chain with a function whose return value is
    ignored."""
    @wraps(f)
    def _cb(res, *a, **kw):
        d = maybeDeferred(f, res, *a, **kw)
        d.addCallback(lambda ignored: res)
        return d
    return _cb

def decode_csr(b64der):
    """Decode JOSE Base-64 DER-encoded CSR.

    :param str b64der: The encoded CSR.

    :rtype: `cryptography.x509.CertificateSigningRequest`
    :return: The decoded CSR."""
    try:
        return x509.load_der_x509_csr(decode_b64jose(b64der), default_backend())
    except ValueError as error:
        raise DeserializationError(error)

def csr_for_names(names, key):
    """Generate a certificate signing request for the given names and private key.

    ..  seealso:: `acme.client.Client.request_issuance`

    ..  seealso:: `generate_private_key`

    :param ``List[str]``: One or more names (subjectAltName) for which to
        request a certificate.
    :param key: A Cryptography private key object.

    :rtype: `cryptography.x509.CertificateSigningRequest`
    :return: The certificate request message."""
    if len(names) == 0:
        raise ValueError('Must have at least one name')
    if len(names[0]) > 64:
        common_name = u'san.too.long.invalid'
    else:
        common_name = names[0]
    return x509.CertificateSigningRequestBuilder().subject_name(x509.Name([x509.NameAttribute(NameOID.COMMON_NAME, common_name)])).add_extension(x509.SubjectAlternativeName(list(map(x509.DNSName, names))), critical=False).sign(key, hashes.SHA256(), default_backend())

def linkcode_resolve(domain, info):
    """Determine the URL corresponding to Python object"""
    if domain != 'py':
        return None
    modname = info['module']
    fullname = info['fullname']
    submod = sys.modules.get(modname)
    if submod is None:
        return None
    obj = submod
    for part in fullname.split('.'):
        try:
            obj = getattr(obj, part)
        except:
            return None
    try:
        fn = inspect.getsourcefile(obj)
    except:
        fn = None
    if not fn:
        return None
    try:
        source, lineno = inspect.findsource(obj)
    except:
        lineno = None
    if lineno:
        linespec = '#L%d' % (lineno + 1)
    else:
        linespec = ''
    fn = relpath(fn, start='..')
    return 'https://github.com/mithrandi/txacme/blob/%s/%s%s' % (txacme_version_info['full-revisionid'], fn, linespec)

def create_layer_from_metadata_xml(resourcetype, xml, monitor=False, service=None, catalog=None):
    """Create a layer / keyword list from a metadata record if it does not already exist."""
    from models import gen_anytext, Layer
    if resourcetype == 'http://www.opengis.net/cat/csw/2.0.2':
        md = CswRecord(etree.fromstring(xml))
    layer = Layer(is_monitored=monitor, name=md.title, title=md.title, abstract=md.abstract, xml=xml, service=service, catalog=catalog, anytext=gen_anytext(md.title, md.abstract, md.subjects))
    if hasattr(md, 'alternative'):
        layer.name = md.alternative
    if md.bbox is not None:
        layer.bbox_x0 = format_float(md.bbox.minx)
        layer.bbox_y0 = format_float(md.bbox.miny)
        layer.bbox_x1 = format_float(md.bbox.maxx)
        layer.bbox_y1 = format_float(md.bbox.maxy)
        layer.wkt_geometry = bbox2wktpolygon([md.bbox.minx, md.bbox.miny, md.bbox.maxx, md.bbox.maxy])
    return (layer, md.subjects)

def create_service_from_endpoint(endpoint, service_type, title=None, abstract=None, catalog=None):
    """Create a service from an endpoint if it does not already exists."""
    from models import Service
    if Service.objects.filter(url=endpoint, catalog=catalog).count() == 0:
        request = requests.get(endpoint)
        if request.status_code == 200:
            LOGGER.debug('Creating a %s service for endpoint=%s catalog=%s' % (service_type, endpoint, catalog))
            service = Service(type=service_type, url=endpoint, title=title, abstract=abstract, csw_type='service', catalog=catalog)
            service.save()
            return service
        else:
            LOGGER.warning('This endpoint is invalid, status code is %s' % request.status_code)
    else:
        LOGGER.warning('A service for this endpoint %s in catalog %s already exists' % (endpoint, catalog))
        return None

def service_url_parse(url):
    """Function that parses from url the service and folder of services."""
    endpoint = get_sanitized_endpoint(url)
    url_split_list = url.split(endpoint + '/')
    if len(url_split_list) != 0:
        url_split_list = url_split_list[1].split('/')
    else:
        raise Exception('Wrong url parsed')
    parsed_url = [s for s in url_split_list if '?' not in s if 'Server' not in s]
    return parsed_url

def inverse_mercator(xy):
    """Given coordinates in spherical mercator, return a lon,lat tuple."""
    lon = xy[0] / 20037508.34 * 180
    lat = xy[1] / 20037508.34 * 180
    lat = 180 / math.pi * (2 * math.atan(math.exp(lat * math.pi / 180)) - math.pi / 2)
    return (lon, lat)

def get_wms_version_negotiate(url, timeout=10):
    """OWSLib wrapper function to perform version negotiation against owslib.wms.WebMapService"""
    try:
        LOGGER.debug('Trying a WMS 1.3.0 GetCapabilities request')
        return WebMapService(url, version='1.3.0', timeout=timeout)
    except Exception as err:
        LOGGER.warning('WMS 1.3.0 support not found: %s', err)
        LOGGER.debug('Trying a WMS 1.1.1 GetCapabilities request instead')
        return WebMapService(url, version='1.1.1', timeout=timeout)

def get_esri_service_name(url):
    """A method to get a service name from an esri endpoint.
    For example: http://example.com/arcgis/rest/services/myservice/mylayer/MapServer/?f=json
    Will return: myservice/mylayer"""
    result = re.search('rest/services/(.*)/[MapServer|ImageServer]', url)
    if result is None:
        return url
    else:
        return result.group(1)

def get_date(layer):
    """Returns a custom date representation. A date can be detected or from metadata.
    It can be a range or a simple date in isoformat."""
    date = None
    sign = '+'
    date_type = 1
    layer_dates = layer.get_layer_dates()
    if layer_dates:
        sign = layer_dates[0][0]
        date = layer_dates[0][1]
        date_type = layer_dates[0][2]
    if date is None:
        date = layer.created
    if date.year > 2300:
        date = None
    if date_type == 0:
        date_type = 'Detected'
    if date_type == 1:
        date_type = 'From Metadata'
    return (get_solr_date(date, sign == '-'), date_type)

def detect_metadata_url_scheme(url):
    """detect whether a url is a Service type that HHypermap supports"""
    scheme = None
    url_lower = url.lower()
    if any((x in url_lower for x in ['wms', 'service=wms'])):
        scheme = 'OGC:WMS'
    if any((x in url_lower for x in ['wmts', 'service=wmts'])):
        scheme = 'OGC:WMTS'
    elif all((x in url for x in ['/MapServer', 'f=json'])):
        scheme = 'ESRI:ArcGIS:MapServer'
    elif all((x in url for x in ['/ImageServer', 'f=json'])):
        scheme = 'ESRI:ArcGIS:ImageServer'
    return scheme

def serialize_checks(check_set):
    """Serialize a check_set for raphael"""
    check_set_list = []
    for check in check_set.all()[:25]:
        check_set_list.append({'datetime': check.checked_datetime.isoformat(), 'value': check.response_time, 'success': 1 if check.success else 0})
    return check_set_list

def layer_mapproxy(request, catalog_slug, layer_uuid, path_info):
    """Get Layer with matching catalog and uuid"""
    layer = get_object_or_404(Layer, uuid=layer_uuid, catalog__slug=catalog_slug)
    if layer.service.type == 'Hypermap:WorldMap':
        layer.service.url = layer.url
    mp, yaml_config = get_mapproxy(layer)
    query = request.META['QUERY_STRING']
    if len(query) > 0:
        path_info = path_info + '?' + query
    params = {}
    headers = {'X-Script-Name': '/registry/{0}/layer/{1}/map/'.format(catalog_slug, layer.id), 'X-Forwarded-Host': request.META['HTTP_HOST'], 'HTTP_HOST': request.META['HTTP_HOST'], 'SERVER_NAME': request.META['SERVER_NAME']}
    if path_info == '/config':
        response = HttpResponse(yaml_config, content_type='text/plain')
        return response
    mp_response = mp.get(path_info, params, headers)
    response = HttpResponse(mp_response.body, status=mp_response.status_int)
    for header, value in mp_response.headers.iteritems():
        response[header] = value
    return response

def parse_datetime(date_str):
    """Parses a date string to date object.
    for BCE dates, only supports the year part."""
    is_common_era = True
    date_str_parts = date_str.split('-')
    if date_str_parts and date_str_parts[0] == '':
        is_common_era = False
        if len(date_str_parts) == 2:
            date_str = date_str + '-01-01T00:00:00Z'
    parsed_datetime = {'is_common_era': is_common_era, 'parsed_datetime': None}
    if is_common_era:
        if date_str == '*':
            return parsed_datetime
        default = datetime.datetime.now().replace(hour=0, minute=0, second=0, microsecond=0, day=1, month=1)
        parsed_datetime['parsed_datetime'] = parse(date_str, default=default)
        return parsed_datetime
    parsed_datetime['parsed_datetime'] = date_str
    return parsed_datetime

def parse_solr_time_range_as_pair(time_filter):
    """:param time_filter: [2013-03-01 TO 2013-05-01T00:00:00]
    :return: (2013-03-01, 2013-05-01T00:00:00)"""
    pattern = '\\[(.*) TO (.*)\\]'
    matcher = re.search(pattern, time_filter)
    if matcher:
        return (matcher.group(1), matcher.group(2))
    else:
        raise Exception("Regex {0} couldn't parse {1}".format(pattern, time_filter))

def parse_ISO8601(time_gap):
    """P1D to (1, ("DAYS", isodate.Duration(days=1)).
    P1Y to (1, ("YEARS", isodate.Duration(years=1)).
    :param time_gap: ISO8601 string.
    :return: tuple with quantity and unit of time."""
    matcher = None
    if time_gap.count('T'):
        units = {'H': ('HOURS', isodate.Duration(hours=1)), 'M': ('MINUTES', isodate.Duration(minutes=1)), 'S': ('SECONDS', isodate.Duration(seconds=1))}
        matcher = re.search('PT(\\d+)([HMS])', time_gap)
        if matcher:
            quantity = int(matcher.group(1))
            unit = matcher.group(2)
            return (quantity, units.get(unit))
        else:
            raise Exception('Does not match the pattern: {}'.format(time_gap))
    else:
        units = {'Y': ('YEARS', isodate.Duration(years=1)), 'M': ('MONTHS', isodate.Duration(months=1)), 'W': ('WEEKS', isodate.Duration(weeks=1)), 'D': ('DAYS', isodate.Duration(days=1))}
        matcher = re.search('P(\\d+)([YMWD])', time_gap)
        if matcher:
            quantity = int(matcher.group(1))
            unit = matcher.group(2)
        else:
            raise Exception('Does not match the pattern: {}'.format(time_gap))
    return (quantity, units.get(unit))

def gap_to_sorl(time_gap):
    """P1D to +1DAY
    :param time_gap:
    :return: solr's format duration."""
    quantity, unit = parse_ISO8601(time_gap)
    if unit[0] == 'WEEKS':
        return '+{0}DAYS'.format(quantity * 7)
    else:
        return '+{0}{1}'.format(quantity, unit[0])

def parse_solr_geo_range_as_pair(geo_box_str):
    """:param geo_box_str: [-90,-180 TO 90,180]
    :return: ("-90,-180", "90,180")"""
    pattern = '\\[(.*) TO (.*)\\]'
    matcher = re.search(pattern, geo_box_str)
    if matcher:
        return (matcher.group(1), matcher.group(2))
    else:
        raise Exception('Regex {0} could not parse {1}'.format(pattern, geo_box_str))

def asterisk_to_min_max(field, time_filter, search_engine_endpoint, actual_params=None):
    """traduce [* TO *] to something like [MIN-INDEXED-DATE TO MAX-INDEXED-DATE]
    :param field: map the stats to this field.
    :param time_filter: this is the value to be translated. think in "[* TO 2000]"
    :param search_engine_endpoint: solr core
    :param actual_params: (not implemented) to merge with other params.
    :return: translated time filter"""
    if actual_params:
        raise NotImplemented('actual_params')
    start, end = parse_solr_time_range_as_pair(time_filter)
    if start == '*' or end == '*':
        params_stats = {'q': '*:*', 'rows': 0, 'stats.field': field, 'stats': 'true', 'wt': 'json'}
        res_stats = requests.get(search_engine_endpoint, params=params_stats)
        if res_stats.ok:
            stats_date_field = res_stats.json()['stats']['stats_fields'][field]
            date_min = stats_date_field['min']
            date_max = stats_date_field['max']
            if start != '*':
                date_min = start
            if end != '*':
                date_max = end
            time_filter = '[{0} TO {1}]'.format(date_min, date_max)
    return time_filter

def register(model, field_name=None, related_name=None, lookup_method_name='get_follows'):
    """This registers any model class to be follow-able."""
    if model in registry:
        return
    registry.append(model)
    if not field_name:
        field_name = 'target_%s' % model._meta.module_name
    if not related_name:
        related_name = 'follow_%s' % model._meta.module_name
    field = ForeignKey(model, related_name=related_name, null=True, blank=True, db_index=True)
    field.contribute_to_class(Follow, field_name)
    setattr(model, lookup_method_name, get_followers_for_object)
    model_map[model] = [related_name, field_name]

def unfollow(user, obj):
    """Make a user unfollow an object"""
    try:
        follow = Follow.objects.get_follows(obj).get(user=user)
        follow.delete()
        return follow
    except Follow.DoesNotExist:
        pass

def toggle(user, obj):
    """Toggles a follow status. Useful function if you don't want to perform follow
    checks but just toggle it on / off."""
    if Follow.objects.is_following(user, obj):
        return unfollow(user, obj)
    return follow(user, obj)

def index_service(self, service_id):
    """Index a service in search engine."""
    from hypermap.aggregator.models import Service
    service = Service.objects.get(id=service_id)
    if not service.is_valid:
        LOGGER.debug('Not indexing service with id %s in search engine as it is not valid' % service.id)
        return
    LOGGER.debug('Indexing service %s' % service.id)
    layer_to_process = service.layer_set.all()
    for layer in layer_to_process:
        if not settings.REGISTRY_SKIP_CELERY:
            index_layer(layer.id, use_cache=True)
        else:
            index_layer(layer.id)

def unindex_layers_with_issues(self, use_cache=False):
    """Remove the index for layers in search backend, which are linked to an issue."""
    from hypermap.aggregator.models import Issue, Layer, Service
    from django.contrib.contenttypes.models import ContentType
    layer_type = ContentType.objects.get_for_model(Layer)
    service_type = ContentType.objects.get_for_model(Service)
    for issue in Issue.objects.filter(content_type__pk=layer_type.id):
        unindex_layer(issue.content_object.id, use_cache)
    for issue in Issue.objects.filter(content_type__pk=service_type.id):
        for layer in issue.content_object.layer_set.all():
            unindex_layer(layer.id, use_cache)

def unindex_layer(self, layer_id, use_cache=False):
    """Remove the index for a layer in the search backend.
    If cache is set, append it to the list of removed layers, if it isn't send the transaction right away."""
    from hypermap.aggregator.models import Layer
    layer = Layer.objects.get(id=layer_id)
    if use_cache:
        LOGGER.debug('Caching layer with id %s for being removed from search engine' % layer.id)
        deleted_layers = cache.get('deleted_layers')
        if deleted_layers is None:
            deleted_layers = set([layer.id])
        else:
            deleted_layers.add(layer.id)
        cache.set('deleted_layers', deleted_layers)
        return
    if SEARCH_TYPE == 'solr':
        from hypermap.aggregator.solr import SolrHypermap
        LOGGER.debug('Removing layer %s from solr' % layer.id)
        try:
            solrobject = SolrHypermap()
            solrobject.remove_layer(layer.uuid)
        except Exception:
            LOGGER.error('Layer NOT correctly removed from Solr')
    elif SEARCH_TYPE == 'elasticsearch':
        pass

def index_all_layers(self):
    """Index all layers in search engine."""
    from hypermap.aggregator.models import Layer
    if not settings.REGISTRY_SKIP_CELERY:
        layers_cache = set(Layer.objects.filter(is_valid=True).values_list('id', flat=True))
        deleted_layers_cache = set(Layer.objects.filter(is_valid=False).values_list('id', flat=True))
        cache.set('layers', layers_cache)
        cache.set('deleted_layers', deleted_layers_cache)
    else:
        for layer in Layer.objects.all():
            index_layer(layer.id)

def update_last_wm_layers(self, service_id, num_layers=10):
    """Update and index the last added and deleted layers (num_layers) in WorldMap service."""
    from hypermap.aggregator.models import Service
    LOGGER.debug('Updating the index the last %s added and %s deleted layers in WorldMap service' % (num_layers, num_layers))
    service = Service.objects.get(id=service_id)
    if service.type == 'Hypermap:WorldMapLegacy':
        from hypermap.aggregator.models import update_layers_wm_legacy as update_layers_wm
    if service.type == 'Hypermap:WorldMap':
        from hypermap.aggregator.models import update_layers_geonode_wm as update_layers_wm
    update_layers_wm(service, num_layers)
    LOGGER.debug('Removing the index for the last %s deleted layers' % num_layers)
    layer_to_unindex = service.layer_set.filter(was_deleted=True).order_by('-last_updated')[0:num_layers]
    for layer in layer_to_unindex:
        if not settings.REGISTRY_SKIP_CELERY:
            unindex_layer(layer.id, use_cache=True)
        else:
            unindex_layer(layer.id)
    LOGGER.debug('Adding/Updating the index for the last %s added layers' % num_layers)
    layer_to_index = service.layer_set.filter(was_deleted=False).order_by('-last_updated')[0:num_layers]
    for layer in layer_to_index:
        if not settings.REGISTRY_SKIP_CELERY:
            index_layer(layer.id, use_cache=True)
        else:
            index_layer(layer.id)

def gen_anytext(*args):
    """Convenience function to create bag of words for anytext property"""
    bag = []
    for term in args:
        if term is not None:
            if isinstance(term, list):
                for term2 in term:
                    if term2 is not None:
                        bag.append(term2)
            else:
                bag.append(term)
    return ' '.join(bag)

def endpointlist_post_save(instance, *args, **kwargs):
    """Used to process the lines of the endpoint list."""
    with open(instance.upload.file.name, mode='rb') as f:
        lines = f.readlines()
    for url in lines:
        if len(url) > 255:
            LOGGER.debug('Skipping this endpoint, as it is more than 255 characters: %s' % url)
        elif Endpoint.objects.filter(url=url, catalog=instance.catalog).count() == 0:
            endpoint = Endpoint(url=url, endpoint_list=instance)
            endpoint.catalog = instance.catalog
            endpoint.save()
    if not settings.REGISTRY_SKIP_CELERY:
        update_endpoints.delay(instance.id)
    else:
        update_endpoints(instance.id)

def service_pre_save(instance, *args, **kwargs):
    """Used to do a service full check when saving it."""
    exists = Service.objects.filter(url=instance.url, type=instance.type, catalog=instance.catalog).count() > 0
    if instance._state.adding and exists:
        raise Exception('There is already such a service. url={0} catalog={1}'.format(instance.url, instance.catalog))

def service_post_save(instance, *args, **kwargs):
    """Used to do a service full check when saving it."""
    if instance.is_monitored and settings.REGISTRY_SKIP_CELERY:
        check_service(instance.id)
    elif instance.is_monitored:
        check_service.delay(instance.id)

def layer_pre_save(instance, *args, **kwargs):
    """Used to check layer validity."""
    is_valid = True
    if not instance.service.type == 'Hypermap:WorldMap':
        if not instance.service.is_valid:
            is_valid = False
            LOGGER.debug('Layer with id %s is marked invalid because its service is invalid' % instance.id)
        if instance.bbox_x0 > -2 and instance.bbox_x1 < 2 and (instance.bbox_y0 > -2) and (instance.bbox_y1 < 2):
            is_valid = False
            LOGGER.debug('Layer with id %s is marked invalid because its extent is within (-2, -2, +2, +2)' % instance.id)
    instance.is_valid = is_valid

def layer_post_save(instance, *args, **kwargs):
    """Used to do a layer full check when saving it."""
    if instance.is_monitored and instance.service.is_monitored:
        if not settings.REGISTRY_SKIP_CELERY:
            check_layer.delay(instance.id)
        else:
            check_layer(instance.id)
    else:
        index_layer(instance.id)

def issue_post_delete(instance, *args, **kwargs):
    """Used to do reindex layers/services when a issue is removed form them."""
    LOGGER.debug('Re-adding layer/service to search engine index')
    if isinstance(instance.content_object, Service):
        if not settings.REGISTRY_SKIP_CELERY:
            index_service.delay(instance.content_object.id)
        else:
            index_service(instance.content_object.id)
    elif not settings.REGISTRY_SKIP_CELERY:
        index_layer.delay(instance.content_object.id)
    else:
        index_layer(instance.content_object.id)

def _input_github_repo(url=None):
    """Grabs input from the user and saves
    it as their trytravis target repo"""
    if url is None:
        url = user_input('Input the URL of the GitHub repository to use as a `trytravis` repository: ')
    url = url.strip()
    http_match = _HTTPS_REGEX.match(url)
    ssh_match = _SSH_REGEX.match(url)
    if not http_match and (not ssh_match):
        raise RuntimeError("That URL doesn't look like a valid GitHub URL. We expect something of the form: `https://github.com/[USERNAME]/[REPOSITORY]` or `ssh://git@github.com/[USERNAME]/[REPOSITORY]")
    if http_match:
        _, name = http_match.groups()
    else:
        _, name = ssh_match.groups()
    if 'trytravis' not in name:
        raise RuntimeError("You must have `trytravis` in the name of your repository. This is a security feature to reduce chances of running git push -f on a repository you don't mean to.")
    accept = user_input('Remember that `trytravis` will make commits on your behalf to `%s`. Are you sure you wish to use this repository? Type `y` or `yes` to accept: ' % url)
    if accept.lower() not in ['y', 'yes']:
        raise RuntimeError('Operation aborted by user.')
    if not os.path.isdir(config_dir):
        os.makedirs(config_dir)
    with open(os.path.join(config_dir, 'repo'), 'w+') as f:
        f.truncate()
        f.write(url)
    print('Repository saved successfully.')

def _load_github_repo():
    """Loads the GitHub repository from the users config."""
    if 'TRAVIS' in os.environ:
        raise RuntimeError('Detected that we are running in Travis. Stopping to prevent infinite loops.')
    try:
        with open(os.path.join(config_dir, 'repo'), 'r') as f:
            return f.read()
    except (OSError, IOError):
        raise RuntimeError('Could not find your repository. Have you ran `trytravis --repo`?')

def _travis_job_state(state):
    """Converts a Travis state into a state character, color,
    and whether it's still running or a stopped state."""
    if state in [None, 'queued', 'created', 'received']:
        return (colorama.Fore.YELLOW, '*', True)
    elif state in ['started', 'running']:
        return (colorama.Fore.LIGHTYELLOW_EX, '*', True)
    elif state == 'passed':
        return (colorama.Fore.LIGHTGREEN_EX, 'P', False)
    elif state == 'failed':
        return (colorama.Fore.LIGHTRED_EX, 'X', False)
    elif state == 'errored':
        return (colorama.Fore.LIGHTRED_EX, '!', False)
    elif state == 'canceled':
        return (colorama.Fore.LIGHTBLACK_EX, 'X', False)
    else:
        raise RuntimeError('unknown state: %s' % str(state))

def _slug_from_url(url):
    """Parses a project slug out of either an HTTPS or SSH URL."""
    http_match = _HTTPS_REGEX.match(url)
    ssh_match = _SSH_REGEX.match(url)
    if not http_match and (not ssh_match):
        raise RuntimeError('Could not parse the URL (`%s`) for your repository.' % url)
    if http_match:
        return '/'.join(http_match.groups())
    else:
        return '/'.join(ssh_match.groups())

def _version_string():
    """Gets the output for `trytravis --version`."""
    platform_system = platform.system()
    if platform_system == 'Linux':
        os_name, os_version, _ = platform.dist()
    else:
        os_name = platform_system
        os_version = platform.version()
    python_version = platform.python_version()
    return 'trytravis %s (%s %s, python %s)' % (__version__, os_name.lower(), os_version, python_version)

def _main(argv):
    """Function that acts just like main() except
    doesn't catch exceptions."""
    repo_input_argv = len(argv) == 2 and argv[0] in ['--repo', '-r', '-R']
    if len(argv) > 1 and (not repo_input_argv):
        _main(['--help'])
    if len(argv) == 1 or repo_input_argv:
        arg = argv[0]
        if arg in ['-h', '--help', '-H']:
            print(_USAGE)
        elif arg in ['-v', '--version', '-V']:
            print(_version_string())
        elif arg in ['-r', '--repo', '-R']:
            if len(argv) == 2:
                url = argv[1]
            else:
                url = None
            _input_github_repo(url)
        elif arg in ['--no-wait', '-nw']:
            url = _load_github_repo()
            commit, committed = _submit_changes_to_github_repo(os.getcwd(), url)
            build_id = _wait_for_travis_build(url, commit, committed)
        else:
            _main(['--help'])
    elif len(argv) == 0:
        url = _load_github_repo()
        commit, committed = _submit_changes_to_github_repo(os.getcwd(), url)
        build_id = _wait_for_travis_build(url, commit, committed)
        _watch_travis_build(build_id)

def main(argv=None):
    """Main entry point when the user runs the `trytravis` command."""
    try:
        colorama.init()
        if argv is None:
            argv = sys.argv[1:]
        _main(argv)
    except RuntimeError as e:
        print(colorama.Fore.RED + 'ERROR: ' + str(e) + colorama.Style.RESET_ALL)
        sys.exit(1)
    else:
        sys.exit(0)

def csw_global_dispatch(request, url=None, catalog_id=None):
    """pycsw wrapper"""
    if request.user.is_authenticated():
        settings.REGISTRY_PYCSW['manager']['transactions'] = 'true'
    env = request.META.copy()
    if request.method == 'POST':
        from StringIO import StringIO
        env['wsgi.input'] = StringIO(request.body)
    env.update({'local.app_root': os.path.dirname(__file__), 'REQUEST_URI': request.build_absolute_uri()})
    if url is not None:
        settings.REGISTRY_PYCSW['server']['url'] = url
    if catalog_id is not None:
        settings.REGISTRY_PYCSW['repository']['filter'] = 'catalog_id = %d' % catalog_id
    csw = server.Csw(settings.REGISTRY_PYCSW, env)
    content = csw.dispatch_wsgi()
    if isinstance(content, list):
        content = content[1]
    response = HttpResponse(content, content_type=csw.contenttype)
    response['Access-Control-Allow-Origin'] = '*'
    return response

