def get_pkg_version():
    """Get version string by parsing PKG-INFO."""
    try:
        with open('PKG-INFO', 'r') as fp:
            rgx = re.compile('Version: (\\d+)')
            for line in fp.readlines():
                match = rgx.match(line)
                if match:
                    return match.group(1)
    except IOError:
        return None

def get_version(dev_version=False):
    """Generates a version string.

    Arguments:
        dev_version: Generate a verbose development version from git commits.

    Examples:
        1.1
        1.1.dev43 # If 'dev_version' was passed."""
    if dev_version:
        version = git_dev_version()
        if not version:
            raise RuntimeError('Could not generate dev version from git.')
        return version
    return '1!%d.%d' % (MAJOR, MINOR)

def _class_dispatch(args, kwargs):
    """See 'class_multimethod'."""
    _ = kwargs
    if not args:
        raise ValueError('Multimethods must be passed at least one positional arg.')
    if not isinstance(args[0], type):
        raise TypeError('class_multimethod must be called with a type, not instance.')
    return args[0]

def to_int_list(values):
    """Converts the given list of vlues into a list of integers. If the
    integer conversion fails (e.g. non-numeric strings or None-values), this
    filter will include a 0 instead."""
    results = []
    for v in values:
        try:
            results.append(int(v))
        except (TypeError, ValueError):
            results.append(0)
    return results

def auto_retry(fun):
    """Decorator for retrying method calls, based on instance parameters."""
    @functools.wraps(fun)
    def decorated(instance, *args, **kwargs):
        """Wrapper around a decorated function."""
        cfg = instance._retry_config
        remaining_tries = cfg.retry_attempts
        current_wait = cfg.retry_wait
        retry_backoff = cfg.retry_backoff
        last_error = None
        while remaining_tries >= 0:
            try:
                return fun(instance, *args, **kwargs)
            except socket.error as e:
                last_error = e
                instance._retry_logger.warning('Connection failed: %s', e)
            remaining_tries -= 1
            if remaining_tries == 0:
                break
            time.sleep(current_wait)
            current_wait *= retry_backoff
        raise last_error
    return decorated

def extract_pattern(fmt):
    """Extracts used strings from a %(foo)s pattern."""
    class FakeDict(object):
        def __init__(self):
            self.seen_keys = set()
        def __getitem__(self, key):
            self.seen_keys.add(key)
            return ''
        def keys(self):
            return self.seen_keys
    fake = FakeDict()
    try:
        fmt % fake
    except TypeError:
        pass
    return set(fake.keys())

def _inject():
    """Inject functions and constants from PyOpenGL but leave out the
    names that are deprecated or that we provide in our API."""
    NS = globals()
    GLNS = _GL.__dict__
    used_names = []
    used_names.extend([names[0] for names in _pyopengl2._functions_to_import])
    used_names.extend([name for name in _pyopengl2._used_functions])
    NS['_used_names'] = used_names
    used_constants = set(_constants.__dict__)
    injected_constants = 0
    injected_functions = 0
    for name in dir(_GL):
        if name.startswith('GL_'):
            if name not in used_constants:
                NS[name] = GLNS[name]
                injected_constants += 1
        elif name.startswith('gl'):
            if name + ',' in _deprecated_functions:
                pass
            elif name in used_names:
                pass
            else:
                NS[name] = GLNS[name]
                injected_functions += 1

def _find_module(name, path=None):
    """Alternative to `imp.find_module` that can also search in subpackages."""
    parts = name.split('.')
    for part in parts:
        if path is not None:
            path = [path]
        fh, path, descr = imp.find_module(part, path)
        if fh is not None and part != parts[-1]:
            fh.close()
    return (fh, path, descr)

