def _vector_or_scalar(x, type='row'):
    """Convert an object to either a scalar or a row or column vector."""
    if isinstance(x, (list, tuple)):
        x = np.array(x)
    if isinstance(x, np.ndarray):
        assert x.ndim == 1
        if type == 'column':
            x = x[:, None]
    return x

def _vector(x, type='row'):
    """Convert an object to a row or column vector."""
    if isinstance(x, (list, tuple)):
        x = np.array(x, dtype=np.float32)
    elif not isinstance(x, np.ndarray):
        x = np.array([x], dtype=np.float32)
    assert x.ndim == 1
    if type == 'column':
        x = x[:, None]
    return x

def _normalize(x, cmin=None, cmax=None, clip=True):
    """Normalize an array from the range [cmin, cmax] to [0,1],
    with optional clipping."""
    if not isinstance(x, np.ndarray):
        x = np.array(x)
    if cmin is None:
        cmin = x.min()
    if cmax is None:
        cmax = x.max()
    if cmin == cmax:
        return 0.5 * np.ones(x.shape)
    else:
        cmin, cmax = (float(cmin), float(cmax))
        y = (x - cmin) * 1.0 / (cmax - cmin)
        if clip:
            y = np.clip(y, 0.0, 1.0)
        return y

def smoothstep(edge0, edge1, x):
    """performs smooth Hermite interpolation
    between 0 and 1 when edge0 < x < edge1."""
    x = np.clip((x - edge0) / (edge1 - edge0), 0.0, 1.0)
    return x * x * (3 - 2 * x)

def _glsl_mix(controls=None):
    """Generate a GLSL template function from a given interpolation patterns
    and control points."""
    assert (controls[0], controls[-1]) == (0.0, 1.0)
    ncolors = len(controls)
    assert ncolors >= 2
    if ncolors == 2:
        s = '    return mix($color_0, $color_1, t);\n'
    else:
        s = ''
        for i in range(ncolors - 1):
            if i == 0:
                ifs = 'if (t < %.6f)' % controls[i + 1]
            elif i == ncolors - 2:
                ifs = 'else'
            else:
                ifs = 'else if (t < %.6f)' % controls[i + 1]
            adj_t = '(t - %s) / %s' % (controls[i], controls[i + 1] - controls[i])
            s += '%s {\n    return mix($color_%d, $color_%d, %s);\n} ' % (ifs, i, i + 1, adj_t)
    return 'vec4 colormap(float t) {\n%s\n}' % s

def strip_html(text):
    """Get rid of ugly twitter html"""
    def reply_to(text):
        replying_to = []
        split_text = text.split()
        for index, token in enumerate(split_text):
            if token.startswith('@'):
                replying_to.append(token[1:])
            else:
                message = split_text[index:]
                break
        rply_msg = ''
        if len(replying_to) > 0:
            rply_msg = 'Replying to '
            for token in replying_to[:-1]:
                rply_msg += token + ','
            if len(replying_to) > 1:
                rply_msg += 'and '
            rply_msg += replying_to[-1] + '. '
        return rply_msg + ' '.join(message)
    text = reply_to(text)
    text = text.replace('@', ' ')
    return ' '.join([token for token in text.split() if 'http:' not in token and 'https:' not in token])

