def set_logging_level(args):
    """Computes and sets the logging level from the parsed arguments."""
    root_logger = logging.getLogger()
    level = logging.INFO
    logging.getLogger('requests.packages.urllib3').setLevel(logging.WARNING)
    if 'verbose' in args and args.verbose is not None:
        logging.getLogger('requests.packages.urllib3').setLevel(0)
        if args.verbose > 1:
            level = 5
        elif args.verbose > 0:
            level = logging.DEBUG
        else:
            logging.critical('verbose is an unexpected value. (%s) exiting.', args.verbose)
            sys.exit(2)
    elif 'quiet' in args and args.quiet is not None:
        if args.quiet > 1:
            level = logging.ERROR
        elif args.quiet > 0:
            level = logging.WARNING
        else:
            logging.critical('quiet is an unexpected value. (%s) exiting.', args.quiet)
    if level is not None:
        root_logger.setLevel(level)
    if args.silence_urllib3:
        requests.packages.urllib3.disable_warnings()

def check_auth(user):
    """Check if the user should or shouldn't be inside the system:
    - If the user is staff or superuser: LOGIN GRANTED
    - If the user has a Person and it is not "disabled": LOGIN GRANTED
    - Elsewhere: LOGIN DENIED"""
    auth = None
    person = None
    if user:
        if user.is_staff or user.is_superuser:
            auth = user
        else:
            person = getattr(user, 'person', None)
            if not person:
                person_related = getattr(user, 'people', None)
                if person_related:
                    if person_related.count() == 1:
                        person = person_related.get()
            if person and (person.disabled is None or person.disabled > timezone.now()):
                auth = user
    return auth

def update_schedule_items(*args, **kw):
    """We save all the schedule items associated with this slot, so
    the last_update time is updated to reflect any changes to the
    timing of the slots"""
    slot = kw.pop('instance', None)
    if not slot:
        return
    for item in slot.scheduleitem_set.all():
        item.save(update_fields=['last_updated'])
    next_slot = slot.slot_set.all()
    if next_slot.count():
        for item in next_slot[0].scheduleitem_set.all():
            item.save(update_fields=['last_updated'])

def make_diff(current, revision):
    """Create the difference between the current revision and a previous version"""
    the_diff = []
    dmp = diff_match_patch()
    for field in set(current.field_dict.keys()) | set(revision.field_dict.keys()):
        if field == 'id' or field.endswith('_rendered'):
            continue
        missing_field = False
        try:
            cur_val = current.field_dict[field] or ''
        except KeyError:
            cur_val = 'No such field in latest version\n'
            missing_field = True
        try:
            old_val = revision.field_dict[field] or ''
        except KeyError:
            old_val = 'No such field in old version\n'
            missing_field = True
        if missing_field:
            diffs = [(dmp.DIFF_DELETE, old_val), (dmp.DIFF_INSERT, cur_val)]
            patch = dmp.diff_prettyHtml(diffs)
        elif isinstance(cur_val, Markup):
            if cur_val.raw == old_val.raw:
                continue
            diffs = dmp.diff_main(old_val.raw, cur_val.raw)
            patch = dmp.diff_prettyHtml(diffs)
        elif cur_val == old_val:
            continue
        else:
            diffs = dmp.diff_main(force_text(old_val), force_text(cur_val))
            patch = dmp.diff_prettyHtml(diffs)
        the_diff.append((field, patch))
    the_diff.sort()
    return the_diff

def grv(struct, position):
    """This function helps to convert date information for showing proper filtering"""
    if position == 'year':
        size = 4
    else:
        size = 2
    if struct[position][2]:
        rightnow = str(struct[position][0]).zfill(size)
    elif position == 'year':
        rightnow = '____'
    else:
        rightnow = '__'
    return rightnow

def flatatt(attrs):
    """Pilfered from `django.forms.utils`:
    Convert a dictionary of attributes to a single string.
    The returned string will contain a leading space followed by key="value",
    XML-style pairs. In the case of a boolean value, the key will appear
    without a value. Otherwise, the value is formatted through its own dict of `attrs`,
    which can be useful to parametrize Angular directives.
    It is assumed that the keys do not need to be
    XML-escaped. If the passed dictionary is empty, then return an empty
    string.

    The result is passed through 'mark_safe' (by way of 'format_html_join')."""
    key_value_attrs = []
    boolean_attrs = []
    for attr, value in attrs.items():
        if isinstance(value, bool):
            if value:
                boolean_attrs.append((attr,))
        else:
            try:
                value = value.format(**attrs)
            except KeyError:
                pass
            key_value_attrs.append((attr, value))
    return format_html_join('', ' {}="{}"', sorted(key_value_attrs)) + format_html_join('', ' {}', sorted(boolean_attrs))

def sso(user, desired_username, name, email, profile_fields=None):
    """Create a user, if the provided `user` is None, from the parameters.
    Then log the user in, and return it."""
    if not user:
        if not settings.REGISTRATION_OPEN:
            raise SSOError('Account registration is closed')
        user = _create_desired_user(desired_username)
        _configure_user(user, name, email, profile_fields)
    if not user.is_active:
        raise SSOError('Account disabled')
    user.backend = settings.AUTHENTICATION_BACKENDS[0]
    return user

def find_overlapping_slots(all_slots):
    """Find any slots that overlap"""
    overlaps = set([])
    for slot in all_slots:
        start = slot.get_start_time()
        end = slot.end_time
        for other_slot in all_slots:
            if other_slot.pk == slot.pk:
                continue
            if other_slot.get_day() != slot.get_day():
                continue
            other_start = other_slot.get_start_time()
            other_end = other_slot.end_time
            if start <= other_start and other_start < end:
                overlaps.add(slot)
                overlaps.add(other_slot)
            elif start < other_end and other_end <= end:
                overlaps.add(slot)
                overlaps.add(other_slot)
    return overlaps

def find_non_contiguous(all_items):
    """Find any items that have slots that aren't contiguous"""
    non_contiguous = []
    for item in all_items:
        if item.slots.count() < 2:
            continue
        last_slot = None
        for slot in item.slots.all().order_by('end_time'):
            if last_slot:
                if last_slot.end_time != slot.get_start_time():
                    non_contiguous.append(item)
                    break
            last_slot = slot
    return non_contiguous

def validate_items(all_items):
    """Find errors in the schedule. Check for:
    - pending / rejected talks in the schedule
    - items with both talks and pages assigned
    - items with neither talks nor pages assigned"""
    validation = []
    for item in all_items:
        if item.talk is not None and item.page is not None:
            validation.append(item)
        elif item.talk is None and item.page is None:
            validation.append(item)
        elif item.talk and item.talk.status not in [ACCEPTED, CANCELLED]:
            validation.append(item)
    return validation

def find_duplicate_schedule_items(all_items):
    """Find talks / pages assigned to mulitple schedule items"""
    duplicates = []
    seen_talks = {}
    for item in all_items:
        if item.talk and item.talk in seen_talks:
            duplicates.append(item)
            if seen_talks[item.talk] not in duplicates:
                duplicates.append(seen_talks[item.talk])
        else:
            seen_talks[item.talk] = item
    return duplicates

def find_clashes(all_items):
    """Find schedule items which clash (common slot and venue)"""
    clashes = {}
    seen_venue_slots = {}
    for item in all_items:
        for slot in item.slots.all():
            pos = (item.venue, slot)
            if pos in seen_venue_slots:
                if seen_venue_slots[pos] not in clashes:
                    clashes[pos] = [seen_venue_slots[pos]]
                clashes[pos].append(item)
            else:
                seen_venue_slots[pos] = item
    return clashes.items()

def find_invalid_venues(all_items):
    """Find venues assigned slots that aren't on the allowed list
    of days."""
    venues = {}
    for item in all_items:
        valid = False
        item_days = list(item.venue.days.all())
        for slot in item.slots.all():
            for day in item_days:
                if day == slot.get_day():
                    valid = True
                    break
        if not valid:
            venues.setdefault(item.venue, [])
            venues[item.venue].append(item)
    return venues.items()

def check_schedule():
    """Helper routine to easily test if the schedule is valid"""
    all_items = prefetch_schedule_items()
    for validator, _type, _msg in SCHEDULE_ITEM_VALIDATORS:
        if validator(all_items):
            return False
    all_slots = prefetch_slots()
    for validator, _type, _msg in SLOT_VALIDATORS:
        if validator(all_slots):
            return False
    return True

