def main(argv=None):
    """Run Nutch command using REST API."""
    global Verbose, Mock
    if argv is None:
        argv = sys.argv
    if len(argv) < 5:
        die('Bad args')
    try:
        opts, argv = getopt.getopt(argv[1:], 'hs:p:mv', ['help', 'server=', 'port=', 'mock', 'verbose'])
    except getopt.GetoptError as err:
        print(err)
        die()
    serverEndpoint = DefaultServerEndpoint
    for opt, val in opts:
        if opt in ('-h', '--help'):
            echo2(USAGE)
            sys.exit()
        elif opt in ('-s', '--server'):
            serverEndpoint = val
        elif opt in ('-p', '--port'):
            serverEndpoint = 'http://localhost:%s' % val
        elif opt in ('-m', '--mock'):
            Mock = 1
        elif opt in ('-v', '--verbose'):
            Verbose = 1
        else:
            die(USAGE)
    cmd = argv[0]
    crawlId = argv[1]
    confId = argv[2]
    urlDir = argv[3]
    args = {}
    if len(argv) > 4:
        args = eval(argv[4])
    nt = Nutch(crawlId, confId, serverEndpoint, urlDir)
    nt.Jobs().create(cmd, **args)

def respond(text=None, ssml=None, attributes=None, reprompt_text=None, reprompt_ssml=None, end_session=True):
    """Build a dict containing a valid response to an Alexa request.

    If speech output is desired, either of `text` or `ssml` should
    be specified.

    :param text: Plain text speech output to be said by Alexa device.
    :param ssml: Speech output in SSML form.
    :param attributes: Dictionary of attributes to store in the session.
    :param end_session: Should the session be terminated after this response?
    :param reprompt_text, reprompt_ssml: Works the same as
        `text`/`ssml`, but instead sets the reprompting speech output."""
    obj = {'version': '1.0', 'response': {'outputSpeech': {'type': 'PlainText', 'text': ''}, 'shouldEndSession': end_session}, 'sessionAttributes': attributes or {}}
    if text:
        obj['response']['outputSpeech'] = {'type': 'PlainText', 'text': text}
    elif ssml:
        obj['response']['outputSpeech'] = {'type': 'SSML', 'ssml': ssml}
    reprompt_output = None
    if reprompt_text:
        reprompt_output = {'type': 'PlainText', 'text': reprompt_text}
    elif reprompt_ssml:
        reprompt_output = {'type': 'SSML', 'ssml': reprompt_ssml}
    if reprompt_output:
        obj['response']['reprompt'] = {'outputSpeech': reprompt_output}
    return obj

def _get_certificate(cert_url):
    """Download and validate a specified Amazon PEM file."""
    global _cache
    if cert_url in _cache:
        cert = _cache[cert_url]
        if cert.has_expired():
            _cache = {}
        else:
            return cert
    url = urlparse(cert_url)
    host = url.netloc.lower()
    path = posixpath.normpath(url.path)
    if url.scheme != 'https' or host not in ['s3.amazonaws.com', 's3.amazonaws.com:443'] or (not path.startswith('/echo.api/')):
        log.error('invalid cert location %s', cert_url)
        return
    resp = urlopen(cert_url)
    if resp.getcode() != 200:
        log.error('failed to download certificate')
        return
    cert = crypto.load_certificate(crypto.FILETYPE_PEM, resp.read())
    if cert.has_expired() or cert.get_subject().CN != 'echo-api.amazon.com':
        log.error('certificate expired or invalid')
        return
    _cache[cert_url] = cert
    return cert

def _default_make_pool(http, proxy_info):
    """Creates a urllib3.PoolManager object that has SSL verification enabled
    and uses the certifi certificates."""
    if not http.ca_certs:
        http.ca_certs = _certifi_where_for_ssl_version()
    ssl_disabled = http.disable_ssl_certificate_validation
    cert_reqs = 'CERT_REQUIRED' if http.ca_certs and (not ssl_disabled) else None
    if isinstance(proxy_info, collections.Callable):
        proxy_info = proxy_info()
    if proxy_info:
        if proxy_info.proxy_user and proxy_info.proxy_pass:
            proxy_url = 'http://{}:{}@{}:{}/'.format(proxy_info.proxy_user, proxy_info.proxy_pass, proxy_info.proxy_host, proxy_info.proxy_port)
            proxy_headers = urllib3.util.request.make_headers(proxy_basic_auth='{}:{}'.format(proxy_info.proxy_user, proxy_info.proxy_pass))
        else:
            proxy_url = 'http://{}:{}/'.format(proxy_info.proxy_host, proxy_info.proxy_port)
            proxy_headers = {}
        return urllib3.ProxyManager(proxy_url=proxy_url, proxy_headers=proxy_headers, ca_certs=http.ca_certs, cert_reqs=cert_reqs)
    return urllib3.PoolManager(ca_certs=http.ca_certs, cert_reqs=cert_reqs)

def _is_ipv6(addr):
    """Checks if a given address is an IPv6 address."""
    try:
        socket.inet_pton(socket.AF_INET6, addr)
        return True
    except socket.error:
        return False

def _certifi_where_for_ssl_version():
    """Gets the right location for certifi certifications for the current SSL
    version.

    Older versions of SSL don't support the stronger set of root certificates."""
    if not ssl:
        return
    if ssl.OPENSSL_VERSION_INFO < (1, 0, 2):
        warnings.warn("You are using an outdated version of OpenSSL that can't use stronger root certificates.")
        return certifi.old_where()
    return certifi.where()

def _map_exception(e):
    """Maps an exception from urlib3 to httplib2."""
    if isinstance(e, urllib3.exceptions.MaxRetryError):
        if not e.reason:
            return e
        e = e.reason
    message = e.args[0] if e.args else ''
    if isinstance(e, urllib3.exceptions.ResponseError):
        if 'too many redirects' in message:
            return httplib2.RedirectLimit(message)
    if isinstance(e, urllib3.exceptions.NewConnectionError):
        if 'Name or service not known' in message or 'nodename nor servname provided, or not known' in message:
            return httplib2.ServerNotFoundError('Unable to find hostname.')
        if 'Connection refused' in message:
            return socket.error((errno.ECONNREFUSED, 'Connection refused'))
    if isinstance(e, urllib3.exceptions.DecodeError):
        return httplib2.FailedToDecompressContent('Content purported as compressed but not uncompressable.', httplib2.Response({'status': 500}), '')
    if isinstance(e, urllib3.exceptions.TimeoutError):
        return socket.timeout('timed out')
    if isinstance(e, urllib3.exceptions.SSLError):
        return ssl.SSLError(*e.args)
    return e

def setup_apiv2():
    """Setup apiv2 when using PyQt4 and Python2."""
    if sys.version_info[0] == 2:
        logging.getLogger(__name__).debug('setting up SIP API to version 2')
        import sip
        try:
            sip.setapi('QString', 2)
            sip.setapi('QVariant', 2)
