            raise ImportError('PyQt4')

def _convert_flux(wavelengths, fluxes, out_flux_unit, area=None, vegaspec=None):
    """Flux conversion for PHOTLAM <-> X."""
    flux_unit_names = (fluxes.unit.to_string(), out_flux_unit.to_string())
    if PHOTLAM.to_string() not in flux_unit_names:
        raise exceptions.SynphotError('PHOTLAM must be one of the conversion units but get {0}.'.format(flux_unit_names))
    if VEGAMAG.to_string() in flux_unit_names:
        from .spectrum import SourceSpectrum
        if not isinstance(vegaspec, SourceSpectrum):
            raise exceptions.SynphotError('Vega spectrum is missing.')
        flux_vega = vegaspec(wavelengths)
        out_flux = fluxes.to(out_flux_unit, equivalencies=spectral_density_vega(wavelengths, flux_vega))
    elif u.count in (fluxes.unit, out_flux_unit) or OBMAG.to_string() in flux_unit_names:
        if area is None:
            raise exceptions.SynphotError('Area is compulsory for conversion involving count or OBMAG.')
        elif not isinstance(area, u.Quantity):
            area = area * AREA
        out_flux = fluxes.to(out_flux_unit, equivalencies=spectral_density_count(wavelengths, area))
    else:
        raise u.UnitsError('{0} and {1} are not convertible'.format(fluxes.unit, out_flux_unit))
    return out_flux

def getsize(path, bestprefix=True, system=NIST):
    """Return a bitmath instance in the best human-readable representation
    of the file size at `path`. Optionally, provide a preferred unit
    system by setting `system` to either `bitmath.NIST` (default) or
    `bitmath.SI`.

    Optionally, set ``bestprefix`` to ``False`` to get ``bitmath.Byte``
    instances back.
    """
    _path = os.path.realpath(path)
    size_bytes = os.path.getsize(_path)
    if bestprefix:
        return Byte(size_bytes).best_prefix(system=system)
    else:
        return Byte(size_bytes)

def parse_string(s):
    """Parse a string with units and try to make a bitmath object out of
    it.

    String inputs may include whitespace characters between the value and
    the unit.
    """
    if not isinstance(s, (str, unicode)):
        raise ValueError('parse_string only accepts string inputs but a %s was given' % type(s))
    try:
        index = list([i.isalpha() for i in s]).index(True)
    except ValueError:
        raise ValueError("No unit detected, can not parse string '%s' into a bitmath object" % s)
    val, unit = (s[:index], s[index:])
    if unit == 'b':
        unit_class = Bit
    elif unit == 'B':
        unit_class = Byte
    else:
        if not (hasattr(sys.modules[__name__], unit) and isinstance(getattr(sys.modules[__name__], unit), type)):
            raise ValueError('The unit %s is not a valid bitmath unit' % unit)
        unit_class = globals()[unit]
    try:
        val = float(val)
    except ValueError:
        raise
    try:
        return unit_class(val)
    except:
        raise ValueError("Can't parse string %s into a bitmath object" % s)

def _get_sampleset(model):
    """Return sampleset of a model or `None` if undefined.
    Model could be a real model or evaluated sampleset."""
    if isinstance(model, Model):
        if hasattr(model, 'sampleset'):
            w = model.sampleset()
        else:
            w = None
    else:
        w = model
    return w

def _merge_sampleset(model1, model2):
    """Simple merge of samplesets."""
    w1 = _get_sampleset(model1)
    w2 = _get_sampleset(model2)
    return merge_wavelengths(w1, w2)

def _shift_wavelengths(model1, model2):
    """One of the models is either ``RedshiftScaleFactor`` or ``Scale``.

    Possible combos::

        RedshiftScaleFactor | Model
        Scale | Model
        Model | Scale"""
    if isinstance(model1, _models.RedshiftScaleFactor):
        val = _get_sampleset(model2)
        if val is None:
            w = val
        else:
            w = model1.inverse(val)
    elif isinstance(model1, _models.Scale):
        w = _get_sampleset(model2)
    else:
        w = _get_sampleset(model1)
    return w

def _get_meta(model):
    """Return metadata of a model.
    Model could be a real model or evaluated metadata."""
    if isinstance(model, Model):
        w = model.meta
    else:
        w = model
    return w

def _merge_meta(model1, model2):
    """Simple merge of samplesets."""
    w1 = _get_meta(model1)
    w2 = _get_meta(model2)
    return metadata.merge(w1, w2, metadata_conflicts='silent')

def get_env_key(obj, key=None):
    """Return environment variable key to use for lookups within a
    namespace represented by the package name.

    For example, any varialbes for predix.security.uaa are stored
    as PREDIX_SECURITY_UAA_KEY"""
    return str.join('_', [obj.__module__.replace('.', '_').upper(), key.upper()])

def get_env_value(obj, attribute):
    """Returns the environment variable value for the attribute of
    the given object.

    For example `get_env_value(predix.security.uaa, 'uri')` will
    return value of environment variable PREDIX_SECURITY_UAA_URI."""
    varname = get_env_key(obj, attribute)
    var = os.environ.get(varname)
    if not var:
        raise ValueError('%s must be set in your environment.' % varname)
    return var

def regex_in_file(regex, filepath, return_match=False):
    """Search for a regex in a file

    If return_match is True, return the found object instead of a boolean"""
    file_content = get_file_content(filepath)
    re_method = funcy.re_find if return_match else funcy.re_test
    return re_method(regex, file_content)

def regex_in_package_file(regex, filename, package_name, return_match=False):
    """Search for a regex in a file contained within the package directory

    If return_match is True, return the found object instead of a boolean"""
    filepath = package_file_path(filename, package_name)
    return regex_in_file(regex, filepath, return_match=return_match)

def nlargest(n, mapping):
    """Takes a mapping and returns the n keys associated with the largest values
    in descending order. If the mapping has fewer than n items, all its keys
    are returned.

    Equivalent to:
        ``next(zip(*heapq.nlargest(mapping.items(), key=lambda x: x[1])))``

    Returns
    -------
    list of up to n keys from the mapping"""
    try:
        it = mapping.iteritems()
    except AttributeError:
        it = iter(mapping.items())
    pq = minpq()
    try:
        for i in range(n):
            pq.additem(*next(it))
    except StopIteration:
        pass
    try:
        while it:
            pq.pushpopitem(*next(it))
    except StopIteration:
        pass
    out = list(pq.popkeys())
    out.reverse()
    return out

def package_has_version_file(package_name):
    """Check to make sure _version.py is contained in the package"""
    version_file_path = helpers.package_file_path('_version.py', package_name)
    return os.path.isfile(version_file_path)

def get_version(package_name, ignore_cache=False):
    """Get the version which is currently configured by the package"""
    if ignore_cache:
        with microcache.temporarily_disabled():
            found = helpers.regex_in_package_file(VERSION_SET_REGEX, '_version.py', package_name, return_match=True)
    else:
        found = helpers.regex_in_package_file(VERSION_SET_REGEX, '_version.py', package_name, return_match=True)
    if found is None:
        raise ProjectError('found {}, but __version__ is not defined')
    current_version = found['version']
    return current_version

def _get_uploaded_versions_warehouse(project_name, index_url, requests_verify=True):
    '''Query the pypi index at index_url using warehouse api to find all of the "releases"'''
    url = '/'.join((index_url, project_name, 'json'))
    response = requests.get(url, verify=requests_verify)
    if response.status_code == 200:
        return response.json()['releases'].keys()
    return None

def _get_uploaded_versions_pypicloud(project_name, index_url, requests_verify=True):
    """Query the pypi index at index_url using pypicloud api to find all versions"""
    api_url = index_url
    for suffix in ('/pypi', '/pypi/', '/simple', '/simple/'):
        if api_url.endswith(suffix):
            api_url = api_url[:len(suffix) * -1] + '/api/package'
            break
    url = '/'.join((api_url, project_name))
    response = requests.get(url, verify=requests_verify)
    if response.status_code == 200:
        return [p['version'] for p in response.json()['packages']]
    return None

def convert_readme_to_rst():
    """Attempt to convert a README.md file into README.rst"""
    project_files = os.listdir('.')
    for filename in project_files:
        if filename.lower() == 'readme':
            raise ProjectError('found {} in project directory...'.format(filename) + 'not sure what to do with it, refusing to convert')
        elif filename.lower() == 'readme.rst':
            raise ProjectError('found {} in project directory...'.format(filename) + 'refusing to overwrite')
    for filename in project_files:
        if filename.lower() == 'readme.md':
            rst_filename = 'README.rst'
            logger.info('converting {} to {}'.format(filename, rst_filename))
            try:
                rst_content = pypandoc.convert(filename, 'rst')
                with open('README.rst', 'w') as rst_file:
                    rst_file.write(rst_content)
                return
            except OSError as e:
                raise ProjectError('could not convert readme to rst due to pypandoc error:' + os.linesep + str(e))
    raise ProjectError('could not find any README.md file to convert')

def get_packaged_files(package_name):
    """Collect relative paths to all files which have already been packaged"""
    if not os.path.isdir('dist'):
        return []
    return [os.path.join('dist', filename) for filename in os.listdir('dist')]

def multiple_packaged_versions(package_name):
    """Look through built package directory and see if there are multiple versions there"""
    dist_files = os.listdir('dist')
    versions = set()
    for filename in dist_files:
        version = funcy.re_find('{}-(.+).tar.gz'.format(package_name), filename)
        if version:
            versions.add(version)
    return len(versions) > 1

def read_geojson(filename):
    """Reads a geojson file containing an STObject and initializes a new STObject from the information in the file.

    Args:
        filename: Name of the geojson file

    Returns:
        an STObject"""
    json_file = open(filename)
    data = json.load(json_file)
    json_file.close()
    times = data['properties']['times']
    main_data = dict(timesteps=[], masks=[], x=[], y=[], i=[], j=[])
    attribute_data = dict()
    for feature in data['features']:
        for main_name in main_data.keys():
            main_data[main_name].append(np.array(feature['properties'][main_name]))
        for k, v in feature['properties']['attributes'].items():
            if k not in attribute_data.keys():
                attribute_data[k] = [np.array(v)]
            else:
                attribute_data[k].append(np.array(v))
    kwargs = {}
    for kw in ['dx', 'step', 'u', 'v']:
        if kw in data['properties'].keys():
            kwargs[kw] = data['properties'][kw]
    sto = STObject(main_data['timesteps'], main_data['masks'], main_data['x'], main_data['y'], main_data['i'], main_data['j'], times[0], times[-1], **kwargs)
    for k, v in attribute_data.items():
        sto.attributes[k] = v
    return sto

def from_yaml():
    """Load configuration from yaml source(s), cached to only run once"""
    default_yaml_str = snippets.get_snippet_content('hatchery.yml')
    ret = yaml.load(default_yaml_str, Loader=yaml.RoundTripLoader)
    for config_path in CONFIG_LOCATIONS:
        config_path = os.path.expanduser(config_path)
        if os.path.isfile(config_path):
            with open(config_path) as config_file:
                config_dict = yaml.load(config_file, Loader=yaml.RoundTripLoader)
                if config_dict is None:
                    continue
                for k, v in config_dict.items():
                    if k not in ret.keys():
                        raise ConfigError('found garbage key "{}" in {}'.format(k, config_path))
                    ret[k] = v
    return ret

def from_pypirc(pypi_repository):
    """Load configuration from .pypirc file, cached to only run once"""
    ret = {}
    pypirc_locations = PYPIRC_LOCATIONS
    for pypirc_path in pypirc_locations:
        pypirc_path = os.path.expanduser(pypirc_path)
        if os.path.isfile(pypirc_path):
            parser = configparser.SafeConfigParser()
            parser.read(pypirc_path)
            if 'distutils' not in parser.sections():
                continue
            if 'index-servers' not in parser.options('distutils'):
                continue
            if pypi_repository not in parser.get('distutils', 'index-servers'):
                continue
            if pypi_repository in parser.sections():
                for option in parser.options(pypi_repository):
                    ret[option] = parser.get(pypi_repository, option)
    if not ret:
        raise ConfigError('repository does not appear to be configured in pypirc ({})'.format(pypi_repository) + ', remember that it needs an entry in [distutils] and its own section')
    return ret

def get_snippet_content(snippet_name, **format_kwargs):
    """Load the content from a snippet file which exists in SNIPPETS_ROOT"""
    filename = snippet_name + '.snippet'
    snippet_file = os.path.join(SNIPPETS_ROOT, filename)
    if not os.path.isfile(snippet_file):
        raise ValueError('could not find snippet with name ' + filename)
    ret = helpers.get_file_content(snippet_file)
    if format_kwargs:
        ret = ret.format(**format_kwargs)
    return ret

