    if plugIn is not None:
        eparOption = plugIn
    elif param.choice is not None:
        eparOption = EnumEparOption
    else:
        eparOption = _eparOptionDict.get(param.type, StringEparOption)
    eo = eparOption(master, statusBar, param, defaultParam, doScroll, fieldWidths, defaultsVerb, bg, indent=indent, helpCallbackObj=helpCallbackObj, mainGuiObj=mainGuiObj)
    eo.setEditedCallbackObj(editedCallbackObj)
