    """Get the task `priority` corresponding to the given `task_priority`.

    If `task_priority` is an integer or 'None', return it.
    If `task_priority` is a str, return the priority of the task it matches.
    Otherwise, raise `ValueError`."""
    if task_priority is None:
        return None
    if is_integer(task_priority):
        return task_priority
    if isinstance(task_priority, basestring):
        if task_priority in tasks:
            return tasks[task_priority].priority
    raise ValueError("Unrecognized task priority '{}'".format(task_priority))

def get_sha(path=None, log=None, short=False, timeout=None):
    """Use `git rev-parse HEAD <REPO>` to get current SHA.
    """
    git_command = ['git', 'rev-parse']
    if short:
        git_command.append('--short')
    git_command.append('HEAD')
    kwargs = {}
    if path is not None:
        kwargs['cwd'] = path
    if timeout is not None:
        kwargs['timeout'] = timeout
    if log is not None:
        log.debug('{} {}'.format(git_command, str(kwargs)))
    sha = subprocess.check_output(git_command, **kwargs)
    try:
        sha = sha.decode('ascii').strip()
    except:
        if log is not None:
            log.debug("decode of '{}' failed".format(sha))
    return sha

def git_clone_all_repos(cat):
    """Perform a 'git clone' for each data repository that doesnt exist.
    """
    log = cat.log
    log.debug('gitter.git_clone_all_repos()')
    all_repos = cat.PATHS.get_all_repo_folders()
    out_repos = cat.PATHS.get_repo_output_folders()
    for repo in all_repos:
        log.info("Repo in: '{}'".format(repo))
        if os.path.isdir(repo):
            log.info('Directory exists.')
        else:
            log.debug('Cloning directory...')
            clone(repo, cat.log, depth=max(cat.args.clone_depth, 1))
        if cat.args.purge_outputs and repo in out_repos:
            for fil in glob(os.path.join(repo, '*.json')):
                os.remove(fil)
        grepo = git.cmd.Git(repo)
        try:
            grepo.status()
        except git.GitCommandError:
            log.error('Repository does not exist!')
            raise
        sha_beg = get_sha(repo)
        log.debug("Current SHA: '{}'".format(sha_beg))
    return

def _call_command_in_repo(comm, repo, log, fail=False, log_flag=True):
    """Use `subprocess` to call a command in a certain (repo) directory.

    Logs the output (both `stderr` and `stdout`) to the log, and checks the
    return codes to make sure they're valid.  Raises error if not.

    Raises
    ------
    exception `subprocess.CalledProcessError`: if the command fails"""
    if log_flag:
        log.debug("Running '{}'.".format(' '.join(comm)))
    process = subprocess.Popen(comm, cwd=repo, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    stdout, stderr = process.communicate()
    if stderr is not None:
        err_msg = stderr.decode('ascii').strip().splitlines()
        for em in err_msg:
            log.error(em)
    if stdout is not None:
        out_msg = stdout.decode('ascii').strip().splitlines()
        for om in out_msg:
            log.warning(om)
    if fail:
        if process.returncode:
            raise subprocess.CalledProcessError
    return

def flow2magang(flow, dtype=uint8):
    """flow dimensions y,x,2  3-D.  flow[...,0] is magnitude, flow[...,1] is angle"""
    fx, fy = (flow[..., 0], flow[..., 1])
    return (hypot(fx, fy).astype(dtype), arctan2(fy, fx) + pi)

def calendar(request, year=None, month=None, template='gnotty/calendar.html'):
    """Show calendar months for the given year/month."""
    try:
        year = int(year)
    except TypeError:
        year = datetime.now().year
    lookup = {'message_time__year': year}
    if month:
        lookup['message_time__month'] = month
    if hide_joins_and_leaves(request):
        lookup['join_or_leave'] = False
    messages = IRCMessage.objects.filter(**lookup)
    try:
        dates = messages.datetimes('message_time', 'day')
    except AttributeError:
        dates = messages.dates('message_time', 'day')
    days = [d.date() for d in dates]
    months = []
    if days:
        min_date, max_date = (days[0], days[-1])
        days = set(days)
        calendar = Calendar(SUNDAY)
        for m in range(1, 13) if not month else [int(month)]:
            lt_max = m <= max_date.month or year < max_date.year
            gt_min = m >= min_date.month or year > min_date.year
            if lt_max and gt_min:
                weeks = calendar.monthdatescalendar(year, m)
                for w, week in enumerate(weeks):
                    for d, day in enumerate(week):
                        weeks[w][d] = {'date': day, 'in_month': day.month == m, 'has_messages': day in days}
                months.append({'month': date(year, m, 1), 'weeks': weeks})
    context = dict(settings)
    context['months'] = months
    return render(request, template, context)

def _prepPointsForSegments(points):
    """Move any off curves at the end of the contour
    to the beginning of the contour. This makes
    segmentation easier."""
    while 1:
        point = points[-1]
        if point.segmentType:
            break
        else:
            point = points.pop()
            points.insert(0, point)
            continue
        break

def _convertPointsToSegments(points, willBeReversed=False):
    """Compile points into InputSegment objects."""
    previousOnCurve = None
    for point in reversed(points):
        if point.segmentType is not None:
            previousOnCurve = point.coordinates
            break
    assert previousOnCurve is not None
    offCurves = []
    segments = []
    for point in points:
        if point.segmentType is None:
            offCurves.append(point)
        else:
            segment = InputSegment(points=offCurves + [point], previousOnCurve=previousOnCurve, willBeReversed=willBeReversed)
            segments.append(segment)
            offCurves = []
            previousOnCurve = point.coordinates
    assert not offCurves
    return segments

def _tValueForPointOnCubicCurve(point, cubicCurve, isHorizontal=0):
    """Finds a t value on a curve from a point.
    The points must be originaly be a point on the curve.
    This will only back trace the t value, needed to split the curve in parts"""
    pt1, pt2, pt3, pt4 = cubicCurve
    a, b, c, d = bezierTools.calcCubicParameters(pt1, pt2, pt3, pt4)
    solutions = bezierTools.solveCubic(a[isHorizontal], b[isHorizontal], c[isHorizontal], d[isHorizontal] - point[isHorizontal])
    solutions = [t for t in solutions if 0 <= t < 1]
    if not solutions and (not isHorizontal):
        return _tValueForPointOnCubicCurve(point, (pt1, pt2, pt3, pt4), isHorizontal=1)
    if len(solutions) > 1:
        intersectionLenghts = {}
        for t in solutions:
            tp = _getCubicPoint(t, pt1, pt2, pt3, pt4)
            dist = _distance(tp, point)
            intersectionLenghts[dist] = t
        minDist = min(intersectionLenghts.keys())
        solutions = [intersectionLenghts[minDist]]
    return solutions

def _scalePoints(points, scale=1, convertToInteger=True):
    """Scale points and optionally convert them to integers."""
    if convertToInteger:
        points = [(int(round(x * scale)), int(round(y * scale))) for x, y in points]
    else:
        points = [(x * scale, y * scale) for x, y in points]
    return points

def _scaleSinglePoint(point, scale=1, convertToInteger=True):
    """Scale a single point"""
    x, y = point
    if convertToInteger:
        return (int(round(x * scale)), int(round(y * scale)))
    else:
        return (x * scale, y * scale)

def _mid(pt1, pt2):
    """(Point, Point) -> Point
    Return the point that lies in between the two input points."""
    (x0, y0), (x1, y1) = (pt1, pt2)
    return (0.5 * (x0 + x1), 0.5 * (y0 + y1))

def kill(pid_file):
    """Attempts to shut down a previously started daemon."""
    try:
        with open(pid_file) as f:
            os.kill(int(f.read()), 9)
        os.remove(pid_file)
    except (IOError, OSError):
        return False
    return True

