def categorize(data, col_name: str=None, new_col_name: str=None, categories: dict=None, max_categories: float=0.15):
    """:param data:
    :param col_name:
    :param new_col_name:
    :param categories:
    :param max_categories: max proportion threshold of categories
    :return: new categories
    :rtype dict:"""
    _categories = {}
    if col_name is None:
        if categories is not None:
            raise Exception('col_name is None when categories was defined.')
        cols = [k for k in data.keys() if data[k].dtype == 'object' and data[k].unique() / data[k].count() <= max_categories]
    else:
        if new_col_name is not None:
            data[new_col_name] = data[col_name]
            col_name = new_col_name
        cols = [col_name]
    for c in cols:
        if categories is not None:
            assert all((type(k) in (int, float) for k in categories.keys()))
            data[c].replace(categories, inplace=True)
            data[c] = data[c].astype('category')
            _categories.update({c: categories})
        else:
            data[c] = data[c].astype('category')
            _categories.update({c: dict(enumerate(data[c].cat.categories))})
    return _categories

