def parse_series(s):
    """Parses things like '1n+2', or 'an+b' generally, returning (a, b)"""
    if isinstance(s, Element):
        s = s._format_element()
    if not s or s == '*':
        return (0, 0)
    if isinstance(s, int):
        return (0, s)
    if s == 'odd':
        return (2, 1)
    elif s == 'even':
        return (2, 0)
    elif s == 'n':
        return (1, 0)
    if 'n' not in s:
        return (0, int(s))
    a, b = s.split('n', 1)
    if not a:
        a = 1
    elif a == '-' or a == '+':
        a = int(a + '1')
    else:
        a = int(a)
    if not b:
        b = 0
    elif b == '-' or b == '+':
        b = int(b + '1')
    else:
        b = int(b)
    return (a, b)

def placeFavicon(context):
    """Gets Favicon-URL for the Model.

    Template Syntax:

        {% placeFavicon %}"""
    fav = Favicon.objects.filter(isFavicon=True).first()
    if not fav:
        return mark_safe('<!-- no favicon -->')
    html = ''
    for rel in config:
        for size in sorted(config[rel], reverse=True):
            n = fav.get_favicon(size=size, rel=rel)
            html += '<link rel="%s" sizes="%sx%s" href="%s"/>' % (n.rel, n.size, n.size, n.faviconImage.url)
    default_fav = fav.get_favicon(size=32, rel='shortcut icon')
    html += '<link rel="%s" sizes="%sx%s" href="%s"/>' % (default_fav.rel, default_fav.size, default_fav.size, default_fav.faviconImage.url)
    return mark_safe(html)

