def chain_tasks(tasks):
    """Chain given tasks. Set each task to run after its previous task.

    :param tasks: Tasks list.

    :return: Given tasks list."""
    if tasks:
        previous_task = None
        for task in tasks:
            if task is not None:
                if previous_task is not None:
                    task.set_run_after(previous_task)
                previous_task = task
    return tasks

