        client = housecanary.ApiClient()
    wrapper = getattr(client, endpoints[0].split('/')[0])
    if len(endpoints) > 1:
        return wrapper.component_mget(identifiers, endpoints)
    else:
        return wrapper.fetch_identifier_component(endpoints[0], identifiers)

