def _guess_name(desc, taken=None):
    """Attempts to guess the menu entry name from the function name."""
    taken = taken or []
    name = ''
    for word in desc.split():
        c = word[0].lower()
        if not c.isalnum():
            continue
        name += c
        if name not in taken:
            break
    count = 2
    while name in taken:
        name = name + str(count)
        count += 1
    return name

def partition_scripts(scripts, start_type1, start_type2):
    """Return two lists of scripts out of the original `scripts` list.

    Scripts that begin with a `start_type1` or `start_type2` blocks
    are returned first. All other scripts are returned second."""
    match, other = ([], [])
    for script in scripts:
        if HairballPlugin.script_start_type(script) == start_type1 or HairballPlugin.script_start_type(script) == start_type2:
            match.append(script)
        else:
            other.append(script)
    return (match, other)

def get_tunneling(handler, registry):
    """Allows all methods to be tunneled via GET for dev/debuging
    purposes."""
    log.info('get_tunneling enabled')
    def get_tunneling(request):
        if request.method == 'GET':
            method = request.GET.pop('_m', 'GET')
            request.method = method
            if method in ['POST', 'PUT', 'PATCH']:
                get_params = request.GET.mixed()
                valid_params = drop_reserved_params(get_params)
                request.body = six.b(json.dumps(valid_params))
                request.content_type = 'application/json'
                request._tunneled_get = True
        return handler(request)
    return get_tunneling

