        combined.update(s)
    return combined

def shared_otuids(groups):
    """Get shared OTUIDs between all unique combinations of groups.

    :type groups: Dict
    :param groups: {Category name: OTUIDs in category}

    :return type: dict
    :return: Dict keyed on group combination and their shared OTUIDs as values."""
    for g in sorted(groups):
        print('Number of OTUs in {0}: {1}'.format(g, len(groups[g].results['otuids'])))
    number_of_categories = len(groups)
    shared = defaultdict()
    for i in range(2, number_of_categories + 1):
        for j in combinations(sorted(groups), i):
            combo_name = ' & '.join(list(j))
            for grp in j:
                shared[combo_name] = groups[j[0]].results['otuids'].copy()
                'iterate through all groups and keep updating combo OTUIDs with set\n                intersection_update'
                for grp in j[1:]:
                    shared[combo_name].intersection_update(groups[grp].results['otuids'])
    return shared

def ensure_dir(d):
    """Check to make sure the supplied directory path does not exist, if so, create it. The
    method catches OSError exceptions and returns a descriptive message instead of
    re-raising the error.

    :type d: str
    :param d: It is the full path to a directory.

    :return: Does not return anything, but creates a directory path if it doesn't exist
             already."""
    if not os.path.exists(d):
        try:
            os.makedirs(d)
        except OSError as oe:
            if os.errno == errno.ENOENT:
                msg = twdd('One or more directories in the path ({}) do not exist. If\n                           you are specifying a new directory for output, please ensure\n                           all other directories in the path currently exist.')
                return msg.format(d)
            else:
                msg = twdd('An error occurred trying to create the output directory\n                           ({}) with message: {}')
                return msg.format(d, oe.strerror)

def parse_unifrac(unifracFN):
    """Parses the unifrac results file into a dictionary

    :type unifracFN: str
    :param unifracFN: The path to the unifrac results file

    :rtype: dict
    :return: A dictionary with keys: 'pcd' (principle coordinates data) which is a
             dictionary of the data keyed by sample ID, 'eigvals' (eigenvalues), and
             'varexp' (variation explained)"""
    with open(unifracFN, 'rU') as uF:
        first = uF.next().split('\t')
        lines = [line.strip() for line in uF]
    unifrac = {'pcd': OrderedDict(), 'eigvals': [], 'varexp': []}
    if first[0] == 'pc vector number':
        return parse_unifrac_v1_8(unifrac, lines)
    elif first[0] == 'Eigvals':
        return parse_unifrac_v1_9(unifrac, lines)
    else:
        raise ValueError('File format not supported/recognized. Please check input unifrac file.')

def rev_c(read):
    """return reverse completment of read"""
    rc = []
    rc_nucs = {'A': 'T', 'T': 'A', 'G': 'C', 'C': 'G', 'N': 'N'}
    for base in read:
        rc.extend(rc_nucs[base.upper()])
    return rc[::-1]

def relative_abundance(biomf, sampleIDs=None):
    """Calculate the relative abundance of each OTUID in a Sample.

    :type biomf: A BIOM file.
    :param biomf: OTU table format.

    :type sampleIDs: list
    :param sampleIDs: A list of sample id's from BIOM format OTU table.

    :rtype: dict
    :return: Returns a keyed on SampleIDs, and the values are dictionaries keyed on
             OTUID's and their values represent the relative abundance of that OTUID in
             that SampleID."""
    if sampleIDs is None:
        sampleIDs = biomf.ids()
    else:
        try:
            for sid in sampleIDs:
                assert sid in biomf.ids()
        except AssertionError:
            raise ValueError('\nError while calculating relative abundances: The sampleIDs provided do not match the sampleIDs in biom file. Please double check the sampleIDs provided.\n')
    otuIDs = biomf.ids(axis='observation')
    norm_biomf = biomf.norm(inplace=False)
    return {sample: {otuID: norm_biomf.get_value_by_ids(otuID, sample) for otuID in otuIDs} for sample in sampleIDs}

def raw_abundance(biomf, sampleIDs=None, sample_abd=True):
    """Calculate the total number of sequences in each OTU or SampleID.

    :type biomf: A BIOM file.
    :param biomf: OTU table format.

    :type sampleIDs: List
    :param sampleIDs: A list of column id's from BIOM format OTU table. By default, the
                      list has been set to None.

    :type sample_abd: Boolean
    :param sample_abd: A boolean operator to provide output for OTUID's or SampleID's. By
                       default, the output will be provided for SampleID's.

    :rtype: dict
    :return: Returns a dictionary keyed on either OTUID's or SampleIDs and their
             respective abundance as values."""
    results = defaultdict(int)
    if sampleIDs is None:
        sampleIDs = biomf.ids()
    else:
        try:
            for sid in sampleIDs:
                assert sid in biomf.ids()
        except AssertionError:
            raise ValueError('\nError while calculating raw total abundances: The sampleIDs provided do not match the sampleIDs in biom file. Please double check the sampleIDs provided.\n')
    otuIDs = biomf.ids(axis='observation')
    for sampleID in sampleIDs:
        for otuID in otuIDs:
            abd = biomf.get_value_by_ids(otuID, sampleID)
            if sample_abd:
                results[sampleID] += abd
            else:
                results[otuID] += abd
    return results

def arcsine_sqrt_transform(rel_abd):
    """Takes the proportion data from relative_abundance() and applies the
    variance stabilizing arcsine square root transformation:

    X = sin^{-1} \\sqrt p"""
    arcsint = lambda p: math.asin(math.sqrt(p))
    return {col_id: {row_id: arcsint(rel_abd[col_id][row_id]) for row_id in rel_abd[col_id]} for col_id in rel_abd}

def write_diversity_metrics(data, sample_ids, fp=None):
