def sort_sam(sam, sort):
    """sort sam file"""
    tempdir = '%s/' % os.path.abspath(sam).rsplit('/', 1)[0]
    if sort is True:
        mapping = '%s.sorted.sam' % sam.rsplit('.', 1)[0]
        if sam != '-':
            if os.path.exists(mapping) is False:
                os.system('                    sort -k1 --buffer-size=%sG -T %s -o %s %s                    ' % (sbuffer, tempdir, mapping, sam))
        else:
            mapping = 'stdin-sam.sorted.sam'
            p = Popen('sort -k1 --buffer-size=%sG -T %s -o %s' % (sbuffer, tempdir, mapping), stdin=sys.stdin, shell=True)
            p.communicate()
        mapping = open(mapping)
    elif sam == '-':
        mapping = sys.stdin
    else:
        mapping = open(sam)
    return mapping

def sub_sam(sam, percent, sort=True, sbuffer=False):
    """randomly subset sam file"""
    mapping = sort_sam(sam, sort)
    pool = [1 for i in range(0, percent)] + [0 for i in range(0, 100 - percent)]
    c = cycle([1, 2])
    for line in mapping:
        line = line.strip().split()
        if line[0].startswith('@'):
            yield line
            continue
        if int(line[1]) <= 20:
            if random.choice(pool) == 1:
                yield line
        else:
            n = next(c)
            if n == 1:
                prev = line
            if n == 2 and random.choice(pool) == 1:
                yield prev
                yield line

def f2lookup(f, lookup):
    """find and replace elements in lookup within file"""
    lookup = {i: r for i, r in [l.strip().split('\t')[0:2] for l in lookup]}
    for line in f:
        line = line.strip()
        for find, replace in list(lookup.items()):
            line = line.replace(find, replace)
        yield line

def change_return_type(f):
    """Converts the returned value of wrapped function to the type of the
    first arg or to the type specified by a kwarg key return_type's value."""
    @wraps(f)
    def wrapper(*args, **kwargs):
        if kwargs.has_key('return_type'):
            return_type = kwargs['return_type']
            kwargs.pop('return_type')
            return return_type(f(*args, **kwargs))
        elif len(args) > 0:
            return_type = type(args[0])
            return return_type(f(*args, **kwargs))
        else:
            return f(*args, **kwargs)
    return wrapper

def convert_args_to_sets(f):
    """Converts all args to 'set' type via self.setify function."""
    @wraps(f)
    def wrapper(*args, **kwargs):
        args = (setify(x) for x in args)
        return f(*args, **kwargs)
    return wrapper

def tokenize(args):
    """Tokenize a string (passed as argument or read from stdin)

    segments [--profile=PATH/TO/PROFILE] tokenize [STRING]"""
    if args.profile and (not Path(args.profile).exists()):
        raise ParserError('--profile must be a path for an existing file')
    _write(args, Tokenizer(profile=args.profile)(_read(args), column=args.mapping))

def promise_method(func):
    """A decorator which ensures that once a method has been marked as resolved
    (via Class.__resolved)) will then propagate the attribute (function) call
    upstream."""
    name = func.__name__
    @wraps(func)
    def wrapped(self, *args, **kwargs):
        cls_name = type(self).__name__
        if getattr(self, '_%s__resolved' % (cls_name,)):
            return getattr(getattr(self, '_%s__wrapped' % (cls_name,)), name)(*args, **kwargs)
        return func(self, *args, **kwargs)
    return wrapped

def bowtiedb(fa, keepDB):
    """make bowtie db"""
    btdir = '%s/bt2' % os.getcwd()
    if not os.path.exists(btdir):
        os.mkdir(btdir)
    btdb = '%s/%s' % (btdir, fa.rsplit('/', 1)[-1])
    if keepDB is True:
        if os.path.exists('%s.1.bt2' % btdb):
            return btdb
    p = subprocess.Popen('bowtie2-build -q %s %s' % (fa, btdb), shell=True)
    p.communicate()
    return btdb

def bowtie(sam, btd, f, r, u, opt, no_shrink, threads):
    """generate bowtie2 command"""
    bt2 = 'bowtie2 -x %s -p %s ' % (btd, threads)
    if f is not False:
        bt2 += '-1 %s -2 %s ' % (f, r)
    if u is not False:
        bt2 += '-U %s ' % u
    bt2 += opt
    if no_shrink is False:
        if f is False:
            bt2 += ' | shrinksam -u -k %s-shrunk.sam ' % sam
        else:
            bt2 += ' | shrinksam -k %s-shrunk.sam ' % sam
    else:
        bt2 += ' > %s.sam' % sam
    return bt2

def crossmap(fas, reads, options, no_shrink, keepDB, threads, cluster, nodes):
    """map all read sets against all fasta files"""
    if cluster is True:
        threads = '48'
    btc = []
    for fa in fas:
        btd = bowtiedb(fa, keepDB)
        F, R, U = reads
        if F is not False:
            if U is False:
                u = False
            for i, f in enumerate(F):
                r = R[i]
                if U is not False:
                    u = U[i]
                sam = '%s/%s-vs-%s' % (os.getcwd(), fa.rsplit('/', 1)[-1], f.rsplit('/', 1)[-1].rsplit('.', 3)[0])
                btc.append(bowtie(sam, btd, f, r, u, options, no_shrink, threads))
        else:
            f = False
            r = False
            for u in U:
                sam = '%s/%s-vs-%s' % (os.getcwd(), fa.rsplit('/', 1)[-1], u.rsplit('/', 1)[-1].rsplit('.', 3)[0])
                btc.append(bowtie(sam, btd, f, r, u, options, no_shrink, threads))
    if cluster is False:
        for i in btc:
            p = subprocess.Popen(i, shell=True)
            p.communicate()
    else:
        ID = ''.join((random.choice([str(i) for i in range(0, 9)]) for _ in range(5)))
        for node, commands in enumerate(chunks(btc, nodes), 1):
            bs = open('%s/crossmap-qsub.%s.%s.sh' % (os.getcwd(), ID, node), 'w')
            print('\n'.join(commands), file=bs)
            bs.close()
            p = subprocess.Popen('qsub -V -N crossmap %s' % bs.name, shell=True)
            p.communicate()

def mask_sequence(seq, gaps):
    """mask (make lower case) regions of sequence found in gaps between model alignments"""
    seq = [i.upper() for i in seq]
    for gap in gaps:
        for i in range(gap[0] - 1, gap[1]):
            seq[i] = seq[i].lower()
    return ''.join(seq)

def run_cmsearch(fastas, threads, cm):
    """run cmsearch: comapre 23S sequences to ssu-align's CM"""
    out = []
