def top_hits(hits, num, column, reverse):
    """get top hits after sorting by column number"""
    hits.sort(key=itemgetter(column), reverse=reverse)
    for hit in hits[0:num]:
        yield hit

def numBlast_sort(blast, numHits, evalueT, bitT):
    """parse b6 output with sorting"""
    header = ['#query', 'target', 'pident', 'alen', 'mismatch', 'gapopen', 'qstart', 'qend', 'tstart', 'tend', 'evalue', 'bitscore']
    yield header
    hmm = {h: [] for h in header}
    for line in blast:
        if line.startswith('#'):
            continue
        line = line.strip().split('\t')
        line[10], line[11] = (float(line[10]), float(line[11]))
        evalue, bit = (line[10], line[11])
        if evalueT is not False and evalue > evalueT:
            continue
        if bitT is not False and bit < bitT:
            continue
        for i, h in zip(line, header):
            hmm[h].append(i)
    hmm = pd.DataFrame(hmm)
    for query, df in hmm.groupby(by=['#query']):
        df = df.sort_values(by=['bitscore'], ascending=False)
        for hit in df[header].values[0:numHits]:
            yield hit

def numBlast(blast, numHits, evalueT=False, bitT=False, sort=False):
    """parse b6 output"""
    if sort is True:
        for hit in numBlast_sort(blast, numHits, evalueT, bitT):
            yield hit
        return
    header = ['#query', 'target', 'pident', 'alen', 'mismatch', 'gapopen', 'qstart', 'qend', 'tstart', 'tend', 'evalue', 'bitscore']
    yield header
    prev, hits = (None, [])
    for line in blast:
        line = line.strip().split('\t')
        ID = line[0]
        line[10], line[11] = (float(line[10]), float(line[11]))
        evalue, bit = (line[10], line[11])
        if ID != prev:
            if len(hits) > 0:
                for hit in top_hits(hits, numHits, 11, True):
                    yield hit
            hits = []
        if evalueT == False and bitT == False:
            hits.append(line)
        elif evalue <= evalueT and bitT == False:
            hits.append(line)
        elif evalue <= evalueT and bit >= bitT:
            hits.append(line)
        elif evalueT == False and bit >= bitT:
            hits.append(line)
        prev = ID
    for hit in top_hits(hits, numHits, 11, True):
        yield hit

def stock2fa(stock):
    """convert stockholm to fasta"""
    seqs = {}
    for line in stock:
        if line.startswith('#') is False and line.startswith(' ') is False and (len(line) > 3):
            id, seq = line.strip().split()
            id = id.rsplit('/', 1)[0]
            id = re.split('[0-9]\\|', id, 1)[-1]
            if id not in seqs:
                seqs[id] = []
            seqs[id].append(seq)
        if line.startswith('//'):
            break
    return seqs

def concat_align(fastas):
    """concatenate alignments"""
    fa2len = {}
    seqs = {}
    IDs = []
    for fasta in fastas:
        seqs[fasta] = {}
        for seq in parse_fasta(fasta):
            ID = seq[0].split('>')[1].split()[0]
            IDs.append(ID)
            seqs[fasta][ID] = seq[1]
        fa2len[fasta] = len(seq[1])
    IDs = set(IDs)
    concat = {}
    for fasta in fastas:
        for ID in IDs:
            if ID not in concat:
                concat[ID] = []
            if ID not in seqs[fasta]:
                concat[ID].append('-' * fa2len[fasta])
            else:
                concat[ID].append(seqs[fasta][ID])
    return concat

def calc_pident_ignore_gaps(a, b):
    """calculate percent identity"""
    m = 0
    mm = 0
    for A, B in zip(list(a), list(b)):
        if A == '-' or A == '.' or B == '-' or (B == '.'):
            continue
        if A == B:
            m += 1
        else:
            mm += 1
    try:
        return float(float(m) / float(m + mm)) * 100
    except:
        return 0

def remove_gaps(A, B):
    """skip column if either is a gap"""
    a_seq, b_seq = ([], [])
    for a, b in zip(list(A), list(B)):
        if a == '-' or a == '.' or b == '-' or (b == '.'):
            continue
        a_seq.append(a)
        b_seq.append(b)
    return (''.join(a_seq), ''.join(b_seq))

def compare_seqs(seqs):
    """compare pairs of sequences"""
    A, B, ignore_gaps = seqs
    a, b = (A[1], B[1])
    if len(a) != len(b):
        print('# reads are not the same length', file=sys.stderr)
        exit()
    if ignore_gaps is True:
        pident = calc_pident_ignore_gaps(a, b)
    else:
        pident = calc_pident(a, b)
    return (A[0], B[0], pident)

def compare_seqs_leven(seqs):
    """calculate Levenshtein ratio of sequences"""
    A, B, ignore_gaps = seqs
    a, b = remove_gaps(A[1], B[1])
    if len(a) != len(b):
        print('# reads are not the same length', file=sys.stderr)
        exit()
    pident = lr(a, b) * 100
    return (A[0], B[0], pident)

def pairwise_compare(afa, leven, threads, print_list, ignore_gaps):
    """make pairwise sequence comparisons between aligned sequences"""
    seqs = {seq[0]: seq for seq in nr_fasta([afa], append_index=True)}
    num_seqs = len(seqs)
    pairs = ((i[0], i[1], ignore_gaps) for i in itertools.combinations(list(seqs.values()), 2))
    pool = multithread(threads)
    if leven is True:
        pident = pool.map(compare_seqs_leven, pairs)
    else:
        compare = pool.imap_unordered(compare_seqs, pairs)
        pident = [i for i in tqdm(compare, total=num_seqs * num_seqs / 2)]
    pool.close()
    pool.terminate()
    pool.join()
    return to_dictionary(pident, print_list)

def to_dictionary(pw, print_list):
    """- convert list of comparisons to dictionary
    - print list of pidents (if requested) to stderr"""
    pairs = {}
    for p in pw:
        a, b, pident = p
        if a not in pairs:
            pairs[a] = {a: '-'}
        if b not in pairs:
            pairs[b] = {b: '-'}
        pairs[a][b] = pident
        pairs[b][a] = pident
        if print_list is True:
            A, B = (a.split('>')[1], b.split('>')[1])
            print('\t'.join([str(i) for i in [A, B, pident]]), file=sys.stderr)
            print('\t'.join([str(i) for i in [B, A, pident]]), file=sys.stderr)
    return pairs

def print_pairwise(pw, median=False):
    """print matrix of pidents to stdout"""
    names = sorted(set([i for i in pw]))
    if len(names) != 0:
        if '>' in names[0]:
            yield (['#'] + [i.split('>')[1] for i in names if '>' in i])
        else:
            yield (['#'] + names)
        for a in names:
            if '>' in a:
                yield ([a.split('>')[1]] + [pw[a][b] for b in names])
            else:
                out = []
                for b in names:
                    if b in pw[a]:
                        if median is False:
                            out.append(max(pw[a][b]))
                        else:
                            out.append(np.median(pw[a][b]))
                    else:
                        out.append('-')
                yield ([a] + out)

def print_comps(comps):
    """print stats for comparisons"""
    if comps == []:
        print('n/a')
    else:
        print('# min: %s, max: %s, mean: %s' % (min(comps), max(comps), np.mean(comps)))

def matrix2dictionary(matrix):
    """convert matrix to dictionary of comparisons"""
    pw = {}
    for line in matrix:
        line = line.strip().split('\t')
        if line[0].startswith('#'):
            names = line[1:]
            continue
        a = line[0]
        for i, pident in enumerate(line[1:]):
            b = names[i]
            if a not in pw:
                pw[a] = {}
            if b not in pw:
                pw[b] = {}
            if pident != '-':
                pident = float(pident)
            pw[a][b] = pident
            pw[b][a] = pident
    return pw

def split_by_category(biom_cols, mapping, category_id):
    """Split up the column data in a biom table by mapping category value."""
    columns = defaultdict(list)
    for i, col in enumerate(biom_cols):
        columns[mapping[col['id']][category_id]].append((i, col))
    return columns

def print_line(l):
    """print line if starts with ..."""
    print_lines = ['# STOCKHOLM', '#=GF', '#=GS', ' ']
    if len(l.split()) == 0:
        return True
    for start in print_lines:
        if l.startswith(start):
            return True
    return False

def stock2one(stock):
    """convert stockholm to single line format"""
    lines = {}
    for line in stock:
        line = line.strip()
        if print_line(line) is True:
            yield line
            continue
        if line.startswith('//'):
            continue
        ID, seq = line.rsplit(' ', 1)
        if ID not in lines:
            lines[ID] = ''
        else:
            seq = seq.strip()
        lines[ID] += seq
    for ID, line in lines.items():
        yield '\t'.join([ID, line])
    yield '\n//'

def math_func(f):
    """Statics the methods. wut."""
    @wraps(f)
    def wrapper(*args, **kwargs):
        if len(args) > 0:
            return_type = type(args[0])
        if kwargs.has_key('return_type'):
            return_type = kwargs['return_type']
            kwargs.pop('return_type')
            return return_type(f(*args, **kwargs))
        args = list((setify(x) for x in args))
        return return_type(f(*args, **kwargs))
    return wrapper

def dump_stats(myStats):
    """Show stats when pings are done"""
    print('\n----%s PYTHON PING Statistics----' % myStats.thisIP)
    if myStats.pktsSent > 0:
        myStats.fracLoss = (myStats.pktsSent - myStats.pktsRcvd) / myStats.pktsSent
    print('%d packets transmitted, %d packets received, %0.1f%% packet loss' % (myStats.pktsSent, myStats.pktsRcvd, 100.0 * myStats.fracLoss))
    if myStats.pktsRcvd > 0:
        print('round-trip (ms)  min/avg/max = %d/%0.1f/%d' % (myStats.minTime, myStats.totTime / myStats.pktsRcvd, myStats.maxTime))
    print('')
    return

def rna_bases(rna_cov, scaffold, bases, line):
    """determine if read overlaps with rna, if so count bases"""
    start = int(line[3])
    stop = start + bases - 1
    if scaffold not in rna_cov:
        return rna_cov
    for pos in rna_cov[scaffold][2]:
        ol = get_overlap([start, stop], pos)
        rna_cov[scaffold][0] += ol
    return rna_cov

def parse_s2bins(s2bins):
    """parse ggKbase scaffold-to-bin mapping
        - scaffolds-to-bins and bins-to-scaffolds"""
    s2b = {}
    b2s = {}
    for line in s2bins:
        line = line.strip().split()
        s, b = (line[0], line[1])
        if 'UNK' in b:
            continue
        if len(line) > 2:
            g = ' '.join(line[2:])
        else:
            g = 'n/a'
        b = '%s\t%s' % (b, g)
        s2b[s] = b
        if b not in b2s:
            b2s[b] = []
        b2s[b].append(s)
    return (s2b, b2s)

def parse_rna(rna, s2bins, min_rna):
    """parse [16,23]SfromHMM.py output
    - rna_cov[scaffold] = [0, 0, []] # [bases, length, ranges]"""
    rna_cov = {}
    for seq in parse_fasta(rna):
        length = len(seq[1])
        if length < min_rna:
            continue
        s = seq[0].split('>')[1].split()[0]
        if s not in s2bins:
            continue
        if s not in rna_cov:
            rna_cov[s] = [0, 0, []]
        position = [int(i) for i in seq[0].rsplit('pos=', 1)[1].split()[0].split('-')]
        rna_cov[s][2].append(position)
        rna_cov[s][1] += length
    return rna_cov

def filter_missing_rna(s2bins, bins2s, rna_cov):
    """remove any bins that don't have 16S"""
    for bin, scaffolds in list(bins2s.items()):
        c = 0
        for s in scaffolds:
            if s in rna_cov:
                c += 1
        if c == 0:
            del bins2s[bin]
    for scaffold, bin in list(s2bins.items()):
        if bin not in bins2s:
            del s2bins[scaffold]
    return (s2bins, bins2s)

def calc_bin_cov(scaffolds, cov):
    """calculate bin coverage"""
    bases = sum([cov[i][0] for i in scaffolds if i in cov])
    length = sum([cov[i][1] for i in scaffolds if i in cov])
    if length == 0:
        return 0
    return float(float(bases) / float(length))

def fq_merge(R1, R2):
    """merge separate fastq files"""
    c = itertools.cycle([1, 2, 3, 4])
    for r1, r2 in zip(R1, R2):
        n = next(c)
        if n == 1:
            pair = [[], []]
        pair[0].append(r1.strip())
        pair[1].append(r2.strip())
        if n == 4:
            yield pair

