def run_LDA(df):
    """Run LinearDiscriminantAnalysis on input dataframe (df) and return
    transformed data, scalings and explained variance by discriminants."""
    X = df.iloc[:, 1:df.shape[1]].values
    y = df['Condition'].values
    sklearn_lda = LDA()
    X_lda_sklearn = sklearn_lda.fit_transform(X, y)
    try:
        exp_var = sklearn_lda.explained_variance_ratio_
    except AttributeError as ae:
        print('\n{}: explained variance cannot be computed.\nPlease check this GitHub PR: https://github.com/scikit-learn/scikit-learn/pull/6027'.format(ae))
        return (X_lda_sklearn, y, 'NA')
    return (X_lda_sklearn, y, exp_var)

def _calc_frames(stats):
    """Compute a DataFrame summary of a Stats object."""
    timings = []
    callers = []
    for key, values in iteritems(stats.stats):
        timings.append(pd.Series(key + values[:-1], index=timing_colnames))
        for caller_key, caller_values in iteritems(values[-1]):
            callers.append(pd.Series(key + caller_key + caller_values, index=caller_columns))
    timings_df = pd.DataFrame(timings)
    callers_df = pd.DataFrame(callers)
    timings_df['filename:funcname'] = timings_df['filename'] + ':' + timings_df['funcname']
    timings_df = timings_df.groupby('filename:funcname').sum()
    return (timings_df, callers_df)

def unmapped(sam, mates):
    """get unmapped reads"""
    for read in sam:
        if read.startswith('@') is True:
            continue
        read = read.strip().split()
        if read[2] == '*' and read[6] == '*':
            yield read
        elif mates is True:
            if read[2] == '*' or read[6] == '*':
                yield read
            for i in read:
                if i == 'YT:Z:UP':
                    yield read

def sugartex_replace_all(string):
    """Replace all with SugarTeX.
    Runs ``sugartex_preprocess`` then iterates via regex and
    replaces each math between '$...$'."""
    string = sugartex_preprocess(string).replace('\\$', SESSION_ID)
    return re.sub('(?<=\\$)[^$]*(?=\\$)', lambda m: sugartex.replace(m.group(0)), string).replace(SESSION_ID, '\\$')

def main():
    """Usage: pre-sugartex [OPTIONS]

      Reads from stdin and writes to stdout.
      When no options: only replace
      U+02CE Modifier Letter Low Grave Accent
      (that looks like low '`') with $

    Options:
      --all    Full SugarTeX replace with regexp,
      --kiwi   Same as above but with kiwi flavor,
      --help   Show this message and exit."""
    if len(sys.argv) > 1:
        arg1 = sys.argv[1]
        if arg1 == '--all' or arg1 == '--kiwi':
            if arg1 == '--kiwi':
                sugartex.mjx_hack()
            sugartex.ready()
            sys.stdout.write(sugartex_replace_all(sys.stdin.read()))
        elif arg1.lower() == '--help':
            print(str(main.__doc__).replace('\n    ', '\n'))
        else:
            raise Exception('Invalid first argument: ' + arg1)
    else:
        sys.stdout.write(sugartex_preprocess(sys.stdin.read()))

def define_log_renderer(fmt, fpath, quiet):
    """the final log processor that structlog requires to render."""
    if fmt:
        return structlog.processors.JSONRenderer()
    if fpath is not None:
        return structlog.processors.JSONRenderer()
    if sys.stderr.isatty() and (not quiet):
        return structlog.dev.ConsoleRenderer()
    return structlog.processors.JSONRenderer()

def _structlog_default_keys_processor(logger_class, log_method, event):
    """Add unique id, type and hostname"""
    global HOSTNAME
    if 'id' not in event:
        event['id'] = '%s_%s' % (datetime.utcnow().strftime('%Y%m%dT%H%M%S'), uuid.uuid1().hex)
    if 'type' not in event:
        event['type'] = 'log'
    event['host'] = HOSTNAME
    return event

def define_log_processors():
    """log processors that structlog executes before final rendering"""
    return [structlog.processors.TimeStamper(fmt='iso'), _structlog_default_keys_processor, structlog.stdlib.PositionalArgumentsFormatter(), structlog.processors.StackInfoRenderer(), structlog.processors.format_exc_info]

def remove_bad(string):
    """remove problem characters from string"""
    remove = [':', ',', '(', ')', ' ', '|', ';', "'"]
    for c in remove:
        string = string.replace(c, '_')
    return string

def get_ids(a):
    """make copy of sequences with short identifier"""
    a_id = '%s.id.fa' % a.rsplit('.', 1)[0]
    a_id_lookup = '%s.id.lookup' % a.rsplit('.', 1)[0]
    if check(a_id) is True:
        return (a_id, a_id_lookup)
    a_id_f = open(a_id, 'w')
    a_id_lookup_f = open(a_id_lookup, 'w')
    ids = []
    for seq in parse_fasta(open(a)):
        id = id_generator()
        while id in ids:
            id = id_generator()
        ids.append(id)
        header = seq[0].split('>')[1]
        name = remove_bad(header)
        seq[0] = '>%s %s' % (id, header)
        print('\n'.join(seq), file=a_id_f)
        print('%s\t%s\t%s' % (id, name, header), file=a_id_lookup_f)
    return (a_id, a_id_lookup)

def run_fast(aligned, threads, cluster, node):
    """run FastTree"""
    tree = '%s.fasttree.nwk' % aligned.rsplit('.', 1)[0]
