def summarize_taxa(biom):
    """Given an abundance table, group the counts by every
    taxonomic level."""
    tamtcounts = defaultdict(int)
    tot_seqs = 0.0
    for row, col, amt in biom['data']:
        tot_seqs += amt
        rtax = biom['rows'][row]['metadata']['taxonomy']
        for i, t in enumerate(rtax):
            t = t.strip()
            if i == len(rtax) - 1 and len(t) > 3 and (len(rtax[-1]) > 3):
                t = 's__' + rtax[i - 1].strip().split('_')[-1] + '_' + t.split('_')[-1]
            tamtcounts[t] += amt
    lvlData = {lvl: levelData(tamtcounts, tot_seqs, lvl) for lvl in ['k', 'p', 'c', 'o', 'f', 'g', 's']}
    return (tot_seqs, lvlData)

def connect_forwarder(forward_host=None, forward_port=None, max_retries=-1, sleep_interval=1.0):
    """connect_forwarder

    :param forward_host: host for receiving forwarded packets
    :param forward_port: port for the forwarded packets
    :param max_retries: retries, -1 = infinite
    :param sleep_interval: how often to retry in this loop"""
    forward_skt = None
    retry_count = 0
    if max_retries == -1:
        retry_count = -2
    if forward_host and forward_port:
        while not forward_skt and retry_count < max_retries:
            try:
                forward_skt = socket.socket()
                log.info('connecting to forward={}:{}'.format(forward_host, forward_port))
                forward_skt.connect((forward_host, forward_port))
                log.debug('connected to forward={}:{}'.format(forward_host, forward_port))
            except Exception as s:
                forward_skt = None
                log.error('Failed to connect forward address={}:{} with ex={}'.format(forward_host, forward_port, s))
                if max_retries == -1:
                    retry_count = -2
                else:
                    retry_count += 1
            time.sleep(sleep_interval)
    return forward_skt

def sam_list(sam):
    """get a list of mapped reads"""
    list = []
    for file in sam:
        for line in file:
            if line.startswith('@') is False:
                line = line.strip().split()
                id, map = (line[0], int(line[1]))
                if map != 4 and map != 8:
                    list.append(id)
    return set(list)

def sam_list_paired(sam):
    """get a list of mapped reads
    require that both pairs are mapped in the sam file in order to remove the reads"""
    list = []
    pair = ['1', '2']
    prev = ''
    for file in sam:
        for line in file:
            if line.startswith('@') is False:
                line = line.strip().split()
                id, map = (line[0], int(line[1]))
                if map != 4 and map != 8:
                    read = id.rsplit('/')[0]
                    if read == prev:
                        list.append(read)
                    prev = read
    return set(list)

def filter_paired(list):
    """require that both pairs are mapped in the sam file in order to remove the reads"""
    pairs = {}
    filtered = []
    for id in list:
        read = id.rsplit('/')[0]
        if read not in pairs:
            pairs[read] = []
        pairs[read].append(id)
    for read in pairs:
        ids = pairs[read]
        if len(ids) == 2:
            filtered.extend(ids)
    return set(filtered)

def filter(fastq, sam, paired=False):
    """filter sequences that are shown to be mapped in the sam file
    reads not in sam file are in *.filtered.fastq
    reads that are in the sam file are in *.matched.fastq"""
    if paired is False:
        list = sam_list(sam)
    else:
        list = sam_list_paired(sam)
    if paired is False:
        filter_fastq(fastq, list)
    else:
        filter_fastq_paired(fastq, list)

def count_mismatches(read):
    """look for NM:i:<N> flag to determine number of mismatches"""
    if read is False:
        return False
    mm = [int(i.split(':')[2]) for i in read[11:] if i.startswith('NM:i:')]
    if len(mm) > 0:
        return sum(mm)
    else:
        return False

def check_mismatches(read, pair, mismatches, mm_option, req_map):
    """- check to see if the read maps with <= threshold number of mismatches
    - mm_option = 'one' or 'both' depending on whether or not one or both reads
       in a pair need to pass the mismatch threshold
    - pair can be False if read does not have a pair
    - make sure alignment score is not 0, which would indicate that the read was not aligned to the reference"""
    if pair is False:
        mm = count_mismatches(read)
        if mm is False:
            return False
        if mismatches is False:
            return True
        if mm <= mismatches:
            return True
    r_mm = count_mismatches(read)
    p_mm = count_mismatches(pair)
    if r_mm is False and p_mm is False:
        return False
    if mismatches is False:
        return True
    if req_map is True:
        if r_mm is False or p_mm is False:
            return False
    if mm_option == 'one':
        if r_mm is not False and r_mm <= mismatches or (p_mm is not False and p_mm <= mismatches):
            return True
    if mm_option == 'both':
        if r_mm is False:
            if p_mm <= mismatches:
                return True
        elif p_mm is False:
            if r_mm <= mismatches:
                return True
        elif (r_mm is not False and r_mm <= mismatches) and (p_mm is not False and p_mm <= mismatches):
            return True
    return False

def check_region(read, pair, region):
    """determine whether or not reads map to specific region of scaffold"""
    if region is False:
        return True
    for mapping in (read, pair):
        if mapping is False:
            continue
        start, length = (int(mapping[3]), len(mapping[9]))
        r = [start, start + length - 1]
        if get_overlap(r, region) > 0:
            return True
    return False

def get_reads(sam, contigs=False, mismatches=False, mm_option=False, sort_sam=True, req_map=False, region=False, sbuffer=False):
    """get mapped reads (and their pairs) from an unsorted sam file"""
    tempdir = '%s/' % os.path.abspath(sam).rsplit('/', 1)[0]
    if sort_sam is True:
        mapping = '%s.sorted.sam' % sam.rsplit('.', 1)[0]
        if sam != '-':
            if os.path.exists(mapping) is False:
                os.system('                    sort -k1 --buffer-size=%sG -T %s -o %s %s                    ' % (sbuffer, tempdir, mapping, sam))
        else:
            mapping = 'stdin-sam.sorted.sam'
            p = Popen('sort -k1 --buffer-size=%sG -T %s -o %s' % (sbuffer, tempdir, mapping), stdin=sys.stdin, shell=True)
            p.communicate()
        mapping = open(mapping)
    elif sam == '-':
        mapping = sys.stdin
    else:
        mapping = open(sam)
    for read in reads_from_mapping(mapping, contigs, mismatches, mm_option, req_map, region):
        yield read

def get_steam():
    """Returns a Steam object representing the current Steam installation on the
    users computer. If the user doesn't have Steam installed, returns None."""
    helper = lambda udd: Steam(udd) if os.path.exists(udd) else None
    plat = platform.system()
    if plat == 'Darwin':
        return helper(paths.default_osx_userdata_path())
    if plat == 'Linux':
        return helper(paths.default_linux_userdata_path())
    if plat == 'Windows':
        possible_dir = winutils.find_userdata_directory()
        return helper(possible_dir) if possible_dir is not None else None
    return None

def zero_to_one(table, option):
    """normalize from zero to one for row or table"""
    if option == 'table':
        m = min(min(table))
        ma = max(max(table))
    t = []
    for row in table:
        t_row = []
        if option != 'table':
            m, ma = (min(row), max(row))
        for i in row:
            if ma == m:
                t_row.append(0)
            else:
                t_row.append((i - m) / (ma - m))
        t.append(t_row)
    return t

def pertotal(table, option):
    """calculate percent of total"""
    if option == 'table':
        total = sum([i for line in table for i in line])
    t = []
    for row in table:
        t_row = []
        if option != 'table':
            total = sum(row)
        for i in row:
            if total == 0:
                t_row.append(0)
            else:
                t_row.append(i / total * 100)
        t.append(t_row)
    return t

def standardize(table, option):
    """standardize
    Z = (X - mean) / (standard deviation)"""
    if option == 'table':
        mean = np.mean(table)
        std = np.std(table)
    t = []
    for row in table:
        t_row = []
        if option != 'table':
            mean = np.mean(row)
            std = np.std(row)
        for i in row:
            if std == 0:
                t_row.append(0)
            else:
                t_row.append((i - mean) / std)
        t.append(t_row)
    return t

def scale(table):
    """scale table based on the column with the largest sum"""
    t = []
    columns = [[] for i in table[0]]
    for row in table:
        for i, v in enumerate(row):
            columns[i].append(v)
    sums = [float(sum(i)) for i in columns]
    scale_to = float(max(sums))
    scale_factor = [scale_to / i for i in sums if i != 0]
    for row in table:
        t.append([a * b for a, b in zip(row, scale_factor)])
    return t

def log_trans(table):
    """log transform each value in table"""
    t = []
    all = [item for sublist in table for item in sublist]
    if min(all) == 0:
        scale = min([i for i in all if i != 0]) * 1e-09
    else:
        scale = 0
    for i in table:
        t.append(np.ndarray.tolist(np.log10([j + scale for j in i])))
    return t

def box_cox(table):
    """box-cox transform table"""
    from scipy.stats import boxcox as bc
    t = []
    for i in table:
        if min(i) == 0:
            scale = min([j for j in i if j != 0]) * 1e-09
        else:
            scale = 0
        t.append(np.ndarray.tolist(bc(np.array([j + scale for j in i]))[0]))
    return t

def inh(table):
    """inverse hyperbolic sine transformation"""
    t = []
    for i in table:
        t.append(np.ndarray.tolist(np.arcsinh(i)))
    return t

def transpose(table):
    """transpose matrix"""
    t = []
    for i in range(0, len(table[0])):
        t.append([row[i] for row in table])
    return t

def open_enc(fn, utf16):
    """Open a file for reading with either the standard built-in open() or the
    open in the codecs module for reading UTF-16 encoded files.

    :param fn: Name of the file to open
    :param utf16: Boolean flag to specify a UTF-16 file"""
    if utf16:
        return codecs.open(fn, encoding='utf-16')
    return open(fn, 'rU')

def generate_barcodes(nIds, codeLen=12):
    """Given a list of sample IDs generate unique n-base barcodes for each.
    Note that only 4^n unique barcodes are possible."""
    def next_code(b, c, i):
        return c[:i] + b + (c[i + 1:] if i < -1 else '')
    def rand_base():
        return random.choice(['A', 'T', 'C', 'G'])
    def rand_seq(n):
        return ''.join([rand_base() for _ in range(n)])
    hpf = re.compile('aaaa|cccc|gggg|tttt', re.IGNORECASE)
    while True:
        codes = [rand_seq(codeLen)]
        if hpf.search(codes[0]) is None:
            break
    idx = 0
    while len(codes) < nIds:
        idx -= 1
        if idx < -codeLen:
            idx = -1
            codes.append(rand_seq(codeLen))
        else:
            nc = next_code(rand_base(), codes[-1], idx)
            if hpf.search(nc) is None:
                codes.append(nc)
        codes = list(set(codes))
    return codes

def handle_packets(pk):
