    return genomes

def calc_custom(custom, genome, scaffold, sequence, scaffold_coverage, total_bases):
    """custom = {(reads mapped to scaffold)/(total reads for sample)}/(length of scaffold)"""
    index = 0
    if scaffold in scaffold_coverage:
        if genome not in custom:
            custom[genome] = [[] for i in scaffold_coverage[scaffold]]
        for cov in scaffold_coverage[scaffold]:
            length = float(len(sequence[1]))
            bases = cov * length
            custom_value = bases / total_bases[index] / length
            custom[genome][index].append(custom_value)
            index += 1
    return custom

def absolute_abundance(coverage, total_bases):
    """absolute abundance = (number of bases mapped to genome / total number of bases in sample) * 100"""
    absolute = {}
    for genome in coverage:
        absolute[genome] = []
        index = 0
        for calc in coverage[genome]:
            bases = calc[0]
            total = total_bases[index]
            absolute[genome].append(bases / total * float(100))
            index += 1
    total_assembled = [0 for i in absolute[genome]]
    for genome in absolute:
        index = 0
        for cov in absolute[genome]:
            total_assembled[index] += cov
            index += 1
    absolute['Unassembled'] = [100 - i for i in total_assembled]
    return absolute

def relative_abundance(coverage):
    """cov = number of bases / length of genome
    relative abundance = [(cov) / sum(cov for all genomes)] * 100"""
    relative = {}
    sums = []
    for genome in coverage:
        for cov in coverage[genome]:
            sums.append(0)
        break
    for genome in coverage:
        index = 0
        for cov in coverage[genome]:
            sums[index] += cov
            index += 1
    for genome in coverage:
        index = 0
        relative[genome] = []
        for cov in coverage[genome]:
            if sums[index] == 0:
                relative[genome].append(0)
            else:
                relative[genome].append(cov / sums[index] * float(100))
            index += 1
    return relative

def genome_coverage(genomes, scaffold_coverage, total_bases):
    """coverage = (number of bases / length of genome) * 100"""
    coverage = {}
    custom = {}
    std = {}
    for genome in genomes:
        for sequence in parse_fasta(genome):
            scaffold = sequence[0].split('>')[1].split()[0]
            coverage, std = sum_coverage(coverage, std, genome, scaffold, sequence, scaffold_coverage)
            custom = calc_custom(custom, genome, scaffold, sequence, scaffold_coverage, total_bases)
    std = calc_std(std)
    custom_std = calc_std(custom)
    custom_av = {}
    for genome in custom:
        custom_av[genome] = []
        for sample in custom[genome]:
            custom_av[genome].append(numpy.mean(sample))
    for genome in coverage:
        print('%s\t%s' % (genome, coverage[genome][0][1]))
    if total_bases is True:
        total_bases = calc_total_mapped_bases(coverage)
    absolute = absolute_abundance(coverage, total_bases)
    for genome in coverage:
        calculated = []
        for calc in coverage[genome]:
            calculated.append(calc[0] / calc[1])
        coverage[genome] = calculated
    relative = relative_abundance(coverage)
    return (coverage, std, absolute, relative, custom_av, custom_std)

def parse_cov(cov_table, scaffold2genome):
    """calculate genome coverage from scaffold coverage table"""
    size = {}
    mapped = {}
    for line in open(cov_table):
        line = line.strip().split('\t')
        if line[0].startswith('#'):
            samples = line[1:]
            samples = [i.rsplit('/', 1)[-1].split('.', 1)[0] for i in samples]
            continue
        scaffold, length = line[0].split(': ')
        length = float(length)
        covs = [float(i) for i in line[1:]]
        bases = [c * length for c in covs]
        if scaffold not in scaffold2genome:
            continue
        genome = scaffold2genome[scaffold]
        if genome not in size:
            size[genome] = 0
            mapped[genome] = {sample: 0 for sample in samples}
        size[genome] += length
        for sample, count in zip(samples, bases):
            mapped[genome][sample] += count
    coverage = {'genome': [], 'genome size (bp)': [], 'sample': [], 'coverage': []}
    for genome, length in size.items():
        for sample in samples:
            cov = mapped[genome][sample] / length
            coverage['genome'].append(genome)
            coverage['genome size (bp)'].append(length)
            coverage['sample'].append(sample)
            coverage['coverage'].append(cov)
    return pd.DataFrame(coverage)

def genome_coverage(covs, s2b):
    """calculate genome coverage from scaffold coverage"""
    COV = []
    for cov in covs:
        COV.append(parse_cov(cov, s2b))
    return pd.concat(COV)

def parse_s2bs(s2bs):
    """convert s2b files to dictionary"""
    s2b = {}
    for s in s2bs:
        for line in open(s):
            line = line.strip().split('\t')
            s, b = (line[0], line[1])
            s2b[s] = b
    return s2b

def fa2s2b(fastas):
    """convert fastas to s2b dictionary"""
    s2b = {}
    for fa in fastas:
        for seq in parse_fasta(fa):
            s = seq[0].split('>', 1)[1].split()[0]
            s2b[s] = fa.rsplit('/', 1)[-1].rsplit('.', 1)[0]
    return s2b

def append_index_id(id, ids):
    """add index to id to make it unique wrt ids"""
    index = 1
    mod = '%s_%s' % (id, index)
    while mod in ids:
        index += 1
        mod = '%s_%s' % (id, index)
    ids.append(mod)
    return (mod, ids)

def de_rep(fastas, append_index, return_original=False):
    """de-replicate fastas based on sequence names"""
    ids = []
    for fasta in fastas:
        for seq in parse_fasta(fasta):
            header = seq[0].split('>')[1].split()
            id = header[0]
            if id not in ids:
                ids.append(id)
                if return_original is True:
                    yield [header, seq]
                else:
                    yield seq
            elif append_index == True:
                new, ids = append_index_id(id, ids)
                if return_original is True:
                    yield [header, ['>%s %s' % (new, ' '.join(header[1:])), seq[1]]]
                else:
                    yield ['>%s %s' % (new, ' '.join(header[1:])), seq[1]]

def insertions_from_masked(seq):
    """get coordinates of insertions from insertion-masked sequence"""
    insertions = []
    prev = True
    for i, base in enumerate(seq):
        if base.isupper() and prev is True:
            insertions.append([])
            prev = False
        elif base.islower():
            insertions[-1].append(i)
            prev = True
    return [[min(i), max(i)] for i in insertions if i != []]

def find_orfs(fa, seqs):
    """find orfs and see if they overlap with insertions
    # seqs[id] = [gene, model, [[i-gene_pos, i-model_pos, i-length, iseq, [orfs], [introns]], ...]]"""
    faa = '%s.prodigal.faa' % fa
    fna = '%s.prodigal.fna' % fa
    gbk = '%s.prodigal.gbk' % fa
    if os.path.exists(faa) is False:
        p = subprocess.Popen('prodigal -q -i %s -a %s -d %s -c -f gbk -m -n -o %s -p meta' % (fa, faa, fna, gbk), shell=True)
        p.communicate()
    for orf in parse_fasta(faa):
        if orf[0] == []:
            continue
        id = orf[0].split('>')[1].split('_', 1)[0]
        pos = sorted([int(i) for i in orf[0].split()[2:5] if i != '#'])
        if id not in seqs:
            continue
        for i, ins in enumerate(seqs[id][2]):
            if check_overlap(pos, ins, 0.9) is True:
                seqs[id][2][i][4].append(orf)
    return (seqs, faa)

def find_introns(fa, seqs, sequences, threads):
    """find introns by searching Rfam intron databse using cmscan
    # seqs[id] = [gene, model, [[i-gene_pos, i-model_pos, i-length, iseq, [orfs], [introns]], ...]]"""
    db = '%s/rfam/Rfam.cm.1_1.introns' % os.environ['databases']
    out = '%s.rfam-introns.cmscan' % fa
    tblout = '%s.rfam-introns.cmscan-tblout' % fa
    if os.path.exists(tblout) is False:
        p = subprocess.Popen('cmscan --cpu %s --tblout %s %s %s > %s' % (threads, tblout, db, fa, out), shell=True)
        p.communicate()
    for line in open(tblout):
        if line.startswith('#'):
            continue
        line = line.strip().split()
        if line[16] == '?':
            continue
        id = line[2]
        type, start, stop, strand = (line[0], int(line[7]), int(line[8]), line[9])
        if 'intron' not in type.lower():
            continue
        pos = sorted([start, stop])
        if id not in seqs:
            continue
        for i, ins in enumerate(seqs[id][2]):
            if check_overlap(pos, ins, 0.25) is True:
                seqs[id][2][i][5].append(['>%s_%s %s %s %s-%s' % (id, i + 1, type, strand, start, stop), sequences[id][1][pos[0] - 1:pos[1]]])
    return seqs

def seqs2bool(seqs):
    """convert orf and intron information to boolean
    # seqs[id] = [gene, model, [[i-gene_pos, i-model_pos, i-length, iseq, [orfs], [introns]], ...]]
    # seqs[id] = [gene, model, [[i-gene_pos, i-model_pos, i-length, iseq, [orfs], [introns], orfs?, introns?], ...]]"""
    for seq in seqs:
        for i, ins in enumerate(seqs[seq][2]):
            if len(ins[4]) > 0:
                ins.append(True)
            else:
                ins.append(False)
            if len(ins[5]) > 0:
                ins.append(True)
            else:
                ins.append(False)
            seqs[seq][2][i] = ins
    return seqs

def max_insertion(seqs, gene, domain):
    """length of largest insertion"""
    seqs = [i[2] for i in list(seqs.values()) if i[2] != [] and i[0] == gene and (i[1] == domain)]
    lengths = []
    for seq in seqs:
        for ins in seq:
            lengths.append(int(ins[2]))
    if lengths == []:
        return 100
    return max(lengths)

def model_length(gene, domain):
    """get length of model"""
    if gene == '16S':
        domain2max = {'E_coli_K12': int(1538), 'bacteria': int(1689), 'archaea': int(1563), 'eukarya': int(2652)}
        return domain2max[domain]
    elif gene == '23S':
        domain2max = {'E_coli_K12': int(2903), 'bacteria': int(3146), 'archaea': int(3774), 'eukarya': int(9079)}
        return domain2max[domain]
    else:
        print(sys.stderr, '# length unknown for gene: %s, domain: %s' % (gene, domain))
        exit()

def setup_markers(seqs):
    """setup unique marker for every orf annotation
    - change size if necessary"""
    family2marker = {}
    markers = cycle(['^', 'p', '*', '+', 'x', 'd', '|', 'v', '>', '<', '8'])
    size = 60
    families = []
    for seq in list(seqs.values()):
        for insertion in seq[2]:
            for family in list(insertion[-1].values()):
                if family not in families:
                    families.append(family)
    for family in families:
        marker = next(markers)
        if marker == '^':
            size = size * 0.5
        family2marker[family] = [marker, size]
    return family2marker

def plot_by_gene_and_domain(name, seqs, tax, id2name):
    """plot insertions for each gene and domain"""
    for gene in set([seq[0] for seq in list(seqs.values())]):
        for domain in set([seq[1] for seq in list(seqs.values())]):
            plot_insertions(name, seqs, gene, domain, tax, id2name)

def get_descriptions(fastas):
    """get the description for each ORF"""
    id2desc = {}
    for fasta in fastas:
        for seq in parse_fasta(fasta):
            header = seq[0].split('>')[1].split(' ')
            id = header[0]
            if len(header) > 1:
                desc = ' '.join(header[1:])
            else:
                desc = 'n/a'
            length = float(len([i for i in seq[1].strip() if i != '*']))
            id2desc[id] = [fasta, desc, length]
    return id2desc

def print_genome_matrix(hits, fastas, id2desc, file_name):
    """optimize later? slow ...
    should combine with calculate_threshold module"""
    out = open(file_name, 'w')
    fastas = sorted(fastas)
    print('## percent identity between genomes', file=out)
    print('# - \t %s' % '\t'.join(fastas), file=out)
    for fasta in fastas:
        line = [fasta]
        for other in fastas:
            if other == fasta:
                average = '-'
            else:
                average = numpy.average([hits[fasta][other][i][3] for i in hits[fasta][other]])
            line.append(str(average))
        print('\t'.join(line), file=out)
    print('', file=out)
    print('## percent of orfs that are orthologous between genomes', file=out)
    print('# - \t %s' % '\t'.join(fastas), file=out)
    for fasta in fastas:
        line = [fasta]
        for other in fastas:
            if other == fasta:
                percent = '-'
            else:
                orthologs = float(len(hits[fasta][other]))
                orfs = float(len([i for i in id2desc if id2desc[i][0] == fasta]))
                percent = float(orthologs / orfs) * 100
            line.append(str(percent))
        print('\t'.join(line), file=out)

def self_compare(fastas, id2desc, algorithm):
    """compare genome to self to get the best possible bit score for each ORF"""
    for fasta in fastas:
        blast = open(search(fasta, fasta, method=algorithm, alignment='local'))
        for hit in best_blast(blast, 1):
            id, bit = (hit[0].split()[0], float(hit[-1]))
            id2desc[id].append(bit)
    return id2desc

def compare_genomes(fastas, id2desc, algorithm):
    """make all pairwise genome comparisons to get rbhs
    rbh = {genome: {other_genome: {rbh_id: [rbh_match, pident, e, bit, norm_bit]]}}"""
    hits = {}
    for pair in itertools.permutations(fastas, 2):
        if pair[0] not in hits:
            hits[pair[0]] = {}
        hits[pair[0]][pair[1]] = {}
    for pair in itertools.combinations(fastas, 2):
        A, B = pair
        blastF = open(search(A, B, method=algorithm, alignment='local'))
        blastR = open(search(B, A, method=algorithm, alignment='local'))
        for compare in ([A, B, blastF], [B, A, blastR]):
            query, ref, blast = compare
            for hit in best_blast(blast, 1):
                a, b, pident, qstart, qend, e, bit = (hit[0].split()[0], hit[1].split()[0], float(hit[2]), float(hit[6]), float(hit[7]), float(hit[-2]), float(hit[-1]))
                alignment_length = abs(qstart - qend + 1)
                norm_bit = normalize_bit(a, b, bit, id2desc)
                length_fraction = float(alignment_length / id2desc[a][2])
                hits[query][ref][a] = ['fbh', a, b, pident, length_fraction, e, bit, norm_bit]
    return hits

def user_specific_data_directory(user_context):
    """Returns the subdirectory in `userdata` which acts as the root of the
    user-specific filesystem in Steam (aka all user-specific files are stored
    under this directory)"""
    return os.path.join(user_context.steam.userdata_directory, user_context.user_id)

def format_xpaths(xpath_map, *args, **kwargs):
    """:return: a copy of xpath_map, but with XPATHs formatted with ordered or keyword values"""
    formatted = {}.fromkeys(xpath_map)
    for key, xpath in iteritems(xpath_map):
        formatted[key] = xpath.format(*args, **kwargs)
    return formatted

def get_xpath_root(xpath):
    """:return: the base of an XPATH: the part preceding any format keys or attribute references"""
    if xpath:
        if xpath.startswith('@'):
            xpath = ''
        else:
            index = xpath.find('/@' if '@' in xpath else '/{')
            xpath = xpath[:index] if index >= 0 else xpath
    return xpath

def get_xpath_branch(xroot, xpath):
    """:return: the relative part of an XPATH: that which extends past the root provided"""
    if xroot and xpath and xpath.startswith(xroot):
        xpath = xpath[len(xroot):]
        xpath = xpath.lstrip(XPATH_DELIM)
    return xpath

def get_xpath_tuple(xpath):
    """:return: a tuple with the base of an XPATH followed by any format key or attribute reference"""
    xroot = get_xpath_root(xpath)
    xattr = None
    if xroot != xpath:
        xattr = get_xpath_branch(xroot, xpath).strip('@')
    return (xroot, xattr)

def get_default_for(prop, value):
    """Ensures complex property types have the correct default values"""
    prop = prop.strip('_')
    val = reduce_value(value)
    if prop in _COMPLEX_LISTS:
        return wrap_value(val)
    elif prop in _COMPLEX_STRUCTS:
        return val or {}
    else:
        return u'' if val is None else val

def has_property(elem_to_parse, xpath):
    """Parse xpath for any attribute reference "path/@attr" and check for root and presence of attribute.
    :return: True if xpath is present in the element along with any attribute referenced, otherwise False"""
    xroot, attr = get_xpath_tuple(xpath)
    if not xroot and (not attr):
        return False
    elif not attr:
        return bool(get_elements_text(elem_to_parse, xroot))
    else:
        return bool(get_elements_attributes(elem_to_parse, xroot, attr))

def parse_complex(tree_to_parse, xpath_root, xpath_map, complex_key):
    """Creates and returns a Dictionary data structure parsed from the metadata.
    :param tree_to_parse: the XML tree compatible with element_utils to be parsed
    :param xpath_root: the XPATH location of the structure inside the parent element
    :param xpath_map: a dict of XPATHs corresponding to a complex definition
    :param complex_key: indicates which complex definition describes the structure"""
    complex_struct = {}
    for prop in _complex_definitions.get(complex_key, xpath_map):
        parsed = parse_property(tree_to_parse, xpath_root, xpath_map, prop)
        parsed = reduce_value(flatten_items((v.split(_COMPLEX_DELIM) for v in wrap_value(parsed))))
        complex_struct[prop] = get_default_for_complex_sub(complex_key, prop, parsed, xpath_map[prop])
    return complex_struct if any(complex_struct.values()) else {}

def parse_dates(tree_to_parse, xpath_map):
    """Creates and returns a Dates Dictionary data structure given the parameters provided
    :param tree_to_parse: the XML tree from which to construct the Dates data structure
    :param xpath_map: a map containing the following type-specific XPATHs:
        multiple, range, range_begin, range_end, and single"""
    values = wrap_value(parse_property(tree_to_parse, None, xpath_map, DATE_TYPE_SINGLE))
    if len(values) == 1:
        return {DATE_TYPE: DATE_TYPE_SINGLE, DATE_VALUES: values}
    elif len(values) > 1:
        return {DATE_TYPE: DATE_TYPE_MULTIPLE, DATE_VALUES: values}
    values = wrap_value(parse_property(tree_to_parse, None, xpath_map, DATE_TYPE_MULTIPLE))
    if len(values) == 1:
        return {DATE_TYPE: DATE_TYPE_SINGLE, DATE_VALUES: values}
    elif len(values) > 1:
        return {DATE_TYPE: DATE_TYPE_MULTIPLE, DATE_VALUES: values}
    values = flatten_items((d for x in (DATE_TYPE_RANGE_BEGIN, DATE_TYPE_RANGE_END) for d in wrap_value(parse_property(tree_to_parse, None, xpath_map, x))))
    if len(values) == 1:
        return {DATE_TYPE: DATE_TYPE_SINGLE, DATE_VALUES: values}
    elif len(values) == 2:
        return {DATE_TYPE: DATE_TYPE_RANGE, DATE_VALUES: values}
    elif len(values) > 2:
        return {DATE_TYPE: DATE_TYPE_MULTIPLE, DATE_VALUES: values}
    return {}

def parse_property(tree_to_parse, xpath_root, xpath_map, prop):
    """Defines the default parsing behavior for metadata values.
    :param tree_to_parse: the XML tree compatible with element_utils to be parsed
    :param xpath_root: used to determine the relative XPATH location within the parent element
    :param xpath_map: a dict of XPATHs that may contain alternate locations for a property
    :param prop: the property to parse: corresponds to a key in xpath_map"""
    xpath = xpath_map[prop]
    if isinstance(xpath, ParserProperty):
        if xpath.xpath is None:
            return xpath.get_prop(prop)
        xpath = xpath.xpath
    if xpath_root:
        xpath = get_xpath_branch(xpath_root, xpath)
    parsed = None
    if not has_property(tree_to_parse, xpath):
        alternate = '_' + prop
        if alternate in xpath_map:
            return parse_property(tree_to_parse, xpath_root, xpath_map, alternate)
    elif '@' not in xpath:
        parsed = get_elements_text(tree_to_parse, xpath)
    else:
        xroot, xattr = get_xpath_tuple(xpath)
        parsed = get_elements_attributes(tree_to_parse, xroot, xattr)
    return get_default_for(prop, parsed)

def update_property(tree_to_update, xpath_root, xpaths, prop, values, supported=None):
    """Either update the tree the default way, or call the custom updater

    Default Way: Existing values in the tree are overwritten. If xpaths contains a single path,
    then each value is written to the tree at that path. If xpaths contains a list of xpaths,
    then the values corresponding to each xpath index are written to their respective locations.
    In either case, empty values are ignored.

    :param tree_to_update: the XML tree compatible with element_utils to be updated
    :param xpath_root: the XPATH location shared by all the xpaths passed in
    :param xpaths: a string or a list of strings representing the XPATH location(s) to which to write values
    :param prop: the name of the property of the parser containing the value(s) with which to update the tree
    :param values: a single value, or a list of values to write to the specified XPATHs

    :see: ParserProperty for more on custom updaters

    :return: a list of all elements updated by this operation"""
    if supported and prop.startswith('_') and (prop.strip('_') in supported):
        values = u''
    else:
        values = get_default_for(prop, values)
    if not xpaths:
        return []
    elif not isinstance(xpaths, ParserProperty):
        return _update_property(tree_to_update, xpath_root, xpaths, values)
    else:
        return xpaths.set_prop(tree_to_update=tree_to_update, prop=prop, values=values)

def validate_any(prop, value, xpath_map=None):
    """Validates any metadata property, complex or simple (string or array)"""
    if value is not None:
        if prop in (ATTRIBUTES, CONTACTS, DIGITAL_FORMS):
            validate_complex_list(prop, value, xpath_map)
        elif prop in (BOUNDING_BOX, LARGER_WORKS, RASTER_INFO):
            validate_complex(prop, value, xpath_map)
        elif prop == DATES:
            validate_dates(prop, value, xpath_map)
        elif prop == PROCESS_STEPS:
            validate_process_steps(prop, value)
        elif prop not in _supported_props and xpath_map is not None:
            validate_complex_list(prop, value, xpath_map)
        else:
            for val in wrap_value(value, include_empty=True):
                validate_type(prop, val, (string_types, list))

def validate_complex(prop, value, xpath_map=None):
    """Default validation for single complex data structure"""
    if value is not None:
        validate_type(prop, value, dict)
        if prop in _complex_definitions:
            complex_keys = _complex_definitions[prop]
        else:
            complex_keys = {} if xpath_map is None else xpath_map
        for complex_prop, complex_val in iteritems(value):
            complex_key = '.'.join((prop, complex_prop))
            if complex_prop not in complex_keys:
                _validation_error(prop, None, value, 'keys: {0}'.format(','.join(complex_keys)))
            validate_type(complex_key, complex_val, (string_types, list))

def validate_complex_list(prop, value, xpath_map=None):
    """Default validation for Attribute Details data structure"""
    if value is not None:
        validate_type(prop, value, (dict, list))
        if prop in _complex_definitions:
            complex_keys = _complex_definitions[prop]
        else:
            complex_keys = {} if xpath_map is None else xpath_map
        for idx, complex_struct in enumerate(wrap_value(value)):
            cs_idx = prop + '[' + str(idx) + ']'
            validate_type(cs_idx, complex_struct, dict)
            for cs_prop, cs_val in iteritems(complex_struct):
                cs_key = '.'.join((cs_idx, cs_prop))
                if cs_prop not in complex_keys:
                    _validation_error(prop, None, value, 'keys: {0}'.format(','.join(complex_keys)))
                if not isinstance(cs_val, list):
                    validate_type(cs_key, cs_val, (string_types, list))
                else:
                    for list_idx, list_val in enumerate(cs_val):
                        list_prop = cs_key + '[' + str(list_idx) + ']'
                        validate_type(list_prop, list_val, string_types)

def validate_process_steps(prop, value):
    """Default validation for Process Steps data structure"""
    if value is not None:
        validate_type(prop, value, (dict, list))
        procstep_keys = set(_complex_definitions[prop])
        for idx, procstep in enumerate(wrap_value(value)):
            ps_idx = prop + '[' + str(idx) + ']'
            validate_type(ps_idx, procstep, dict)
            for ps_prop, ps_val in iteritems(procstep):
                ps_key = '.'.join((ps_idx, ps_prop))
                if ps_prop not in procstep_keys:
                    _validation_error(prop, None, value, 'keys: {0}'.format(','.join(procstep_keys)))
                if ps_prop != 'sources':
                    validate_type(ps_key, ps_val, string_types)
                else:
                    validate_type(ps_key, ps_val, (string_types, list))
                    for src_idx, src_val in enumerate(wrap_value(ps_val)):
                        src_key = ps_key + '[' + str(src_idx) + ']'
                        validate_type(src_key, src_val, string_types)

def validate_type(prop, value, expected):
    """Default validation for all types"""
    if value is not None and (not isinstance(value, expected)):
        _validation_error(prop, type(value).__name__, None, expected)

def _validation_error(prop, prop_type, prop_value, expected):
    """Default validation for updated properties"""
    if prop_type is None:
        attrib = 'value'
        assigned = prop_value
    else:
        attrib = 'type'
        assigned = prop_type
    raise ValidationError('Invalid property {attrib} for {prop}:\n\t{attrib}: {assigned}\n\texpected: {expected}', attrib=attrib, prop=prop, assigned=assigned, expected=expected, invalid={prop: prop_value} if attrib == 'value' else {})

def regroup_commands(commands):
    """Returns a list of tuples:

        [(command_to_run, [list, of, commands])]

    If the list of commands has a single item, the command was not grouped."""
    grouped = []
    pending = []
    def group_pending():
        if not pending:
            return
        new_command = grouped_command(pending)
        result = []
        while pending:
            result.append(pending.pop(0))
        grouped.append((new_command, result))
    for command, next_command in peek(commands):
        if can_group_commands(command, next_command):
            if pending and (not can_group_commands(pending[0], command)):
                group_pending()
            pending.append(command)
        else:
            if pending and can_group_commands(pending[0], command):
                pending.append(command)
            else:
                grouped.append((command.clone(), [command]))
            group_pending()
    group_pending()
    return grouped

def find_databases(databases):
    """define ribosomal proteins and location of curated databases"""
    proteins = ['L15', 'L18', 'L6', 'S8', 'L5', 'L24', 'L14', 'S17', 'L16', 'S3', 'L22', 'S19', 'L2', 'L4', 'L3', 'S10']
    protein_databases = {'L14': 'rpL14_JGI_MDM.filtered.faa', 'L15': 'rpL15_JGI_MDM.filtered.faa', 'L16': 'rpL16_JGI_MDM.filtered.faa', 'L18': 'rpL18_JGI_MDM.filtered.faa', 'L22': 'rpL22_JGI_MDM.filtered.faa', 'L24': 'rpL24_JGI_MDM.filtered.faa', 'L2': 'rpL2_JGI_MDM.filtered.faa', 'L3': 'rpL3_JGI_MDM.filtered.faa', 'L4': 'rpL4_JGI_MDM.filtered.faa', 'L5': 'rpL5_JGI_MDM.filtered.faa', 'L6': 'rpL6_JGI_MDM.filtered.faa', 'S10': 'rpS10_JGI_MDM.filtered.faa', 'S17': 'rpS17_JGI_MDM.filtered.faa', 'S19': 'rpS19_JGI_MDM.filtered.faa', 'S3': 'rpS3_JGI_MDM.filtered.faa', 'S8': 'rpS8_JGI_MDM.filtered.faa'}
    protein_databases = {key: '%s/%s' % (databases, database) for key, database in list(protein_databases.items())}
    return (proteins, protein_databases)

def scaffold_hits(searches, fasta, max_hits):
    """get hits from each search against each RP
    scaffolds[scaffold] = # ORfs
    s2rp[scaffold] = {rp:[hits]}"""
    scaffolds = {}
    for seq in parse_fasta(fasta):
        scaffold = seq[0].split()[0].split('>', 1)[1].rsplit('_', 1)[0]
        if scaffold not in scaffolds:
            scaffolds[scaffold] = 0
        scaffolds[scaffold] += 1
    s2rp = {s: {r[0]: [] for r in searches} for s in scaffolds}
    for search in searches:
        rp, blast = search
        hits = [i for i in numblast(open(blast), max_hits, evalue_thresh, bit_thresh)]
        for hit in hits:
            s = hit[0].split()[0].rsplit('_', 1)[0]
            hit[10], hit[11] = (float(hit[10]), float(hit[11]))
            s2rp[s][rp].append(hit)
    return (scaffolds, s2rp)

def find_next(start, stop, i2hits):
    """which protein has the best hit, the one to the 'right' or to the 'left?'"""
    if start not in i2hits and stop in i2hits:
        index = stop
    elif stop not in i2hits and start in i2hits:
        index = start
    elif start not in i2hits and stop not in i2hits:
        index = choice([start, stop])
        i2hits[index] = [[False]]
    else:
        A, B = (i2hits[start][0], i2hits[stop][0])
        if B[10] <= A[10]:
            index = stop
        else:
            index = start
    if index == start:
        nstart = start - 1
        nstop = stop
    else:
        nstop = stop + 1
        nstart = start
    match = i2hits[index][0]
    rp = match[-1]
    return (index, nstart, nstop, rp, match)

def find_ribosomal(rps, scaffolds, s2rp, min_hits, max_hits_rp, max_errors):
    """determine which hits represent real ribosomal proteins, identify each in syntenic block
    max_hits_rp = maximum number of hits to consider per ribosomal protein per scaffold"""
    for scaffold, proteins in list(s2rp.items()):
        hits = {p: [i for i in sorted(hits, key=itemgetter(10))][0:max_hits_rp] for p, hits in list(proteins.items()) if len(hits) > 0}
        if len(hits) < min_hits:
            continue
        best = sorted([hit[0] + [p] for p, hit in list(hits.items())], key=itemgetter(10))[0]
        block = find_block(rps, scaffolds[scaffold], hits, best, max_errors)
        if len(block) - 1 >= min_hits:
            yield (scaffold, block)

def remodel_run(self, c=None, **global_optargs):
    """Passes a connection from the connection pool so that we can call .run()
    on a query without an explicit connection"""
    if not c:
        with remodel.connection.get_conn() as conn:
            return run(self, conn, **global_optargs)
    else:
        return run(self, c, **global_optargs)

def run(addr, *commands, **kwargs):
    """Non-threaded batch command runner returning output results"""
    results = []
    handler = VarnishHandler(addr, **kwargs)
    for cmd in commands:
        if isinstance(cmd, tuple) and len(cmd) > 1:
            results.extend([getattr(handler, c[0].replace('.', '_'))(*c[1:]) for c in cmd])
        else:
            results.append(getattr(handler, cmd.replace('.', '_'))(*commands[1:]))
            break
    handler.close()
    return results

def notify_items(**kwargs):
    """Signal endpoint that actually sends knocks whenever an instance is created / saved"""
    instance = kwargs.get('instance')
    created = kwargs.get('created', False)
    if hasattr(instance, 'send_knock') and active_knocks(instance):
        try:
            if hasattr(instance, 'get_available_languages'):
                langs = instance.get_available_languages()
            else:
                langs = [get_language()]
            for lang in langs:
                with override(lang):
                    instance.send_knock(created)
            return True
        except AttributeError:
            pass
    return False

def active_knocks(obj):
    """Checks whether knocks are enabled for the model given as argument

    :param obj: model instance
    :return True if knocks are active"""
    if not hasattr(_thread_locals, 'knock_enabled'):
        return True
    return _thread_locals.knock_enabled.get(obj.__class__, True)

def pause_knocks(obj):
    """Context manager to suspend sending knocks for the given model

    :param obj: model instance"""
    if not hasattr(_thread_locals, 'knock_enabled'):
        _thread_locals.knock_enabled = {}
    obj.__class__._disconnect()
    _thread_locals.knock_enabled[obj.__class__] = False
    yield
    _thread_locals.knock_enabled[obj.__class__] = True
    obj.__class__._connect()

def _simpleparsefun(date):
    """Simple date parsing function"""
    if hasattr(date, 'year'):
        return date
    try:
        date = datetime.datetime.strptime(date, '%Y-%m-%d')
    except ValueError:
        date = datetime.datetime.strptime(date, '%Y-%m-%d %H:%M:%S')
    return date

def colorize(printable, color, style='normal', autoreset=True):
    """Colorize some message with ANSI colors specification

    :param printable: interface whose has __str__ or __repr__ method
    :param color: the colors defined in COLOR_MAP to colorize the text
    :style: can be 'normal', 'bold' or 'underline'

    :returns: the 'printable' colorized with style"""
    if not COLORED:
        return printable
    if color not in COLOR_MAP:
        raise RuntimeError('invalid color set, no {}'.format(color))
    return '{color}{printable}{reset}'.format(printable=printable, color=COLOR_MAP[color].format(style=STYLE_MAP[style]), reset=COLOR_MAP['reset'] if autoreset else '')

def P(Document, *fields, **kw):
    """Generate a MongoDB projection dictionary using the Django ORM style."""
    __always__ = kw.pop('__always__', set())
    projected = set()
    omitted = set()
    for field in fields:
        if field[0] in ('-', '!'):
            omitted.add(field[1:])
        elif field[0] == '+':
            projected.add(field[1:])
        else:
            projected.add(field)
    if not projected:
        names = set(getattr(Document, '__projection__', Document.__fields__) or Document.__fields__)
        projected = {name for name in names - omitted}
    projected |= __always__
    if not projected:
        projected = {'_id'}
    return {unicode(traverse(Document, name, name)): True for name in projected}

def F(Document, __raw__=None, **filters):
    """Generate a MongoDB filter document through parameter interpolation.

    Arguments passed by name have their name interpreted as an optional prefix (currently only `not`), a double-
    underscore

    Because this utility is likely going to be used frequently it has been given a single-character name."""
    ops = Filter(__raw__)
    args = _process_arguments(Document, FILTER_PREFIX_MAP, FILTER_OPERATION_MAP, filters)
    for prefix, suffix, field, value in args:
        if suffix:
            op = suffix(field, value)
        else:
            op = DEFAULT_FILTER(field, value)
        if prefix:
            op = prefix(op)
        ops &= op
    return ops

def force_text(s, encoding='utf-8', errors='strict'):
    """Returns a bytestring version of 's', encoded as specified in 'encoding'.

    If strings_only is True, don't convert (some) non-string-like objects.

    Based on the `django.utils.encoding.smart_str' (https://github.com/django/django/blob/master/django/utils/encoding.py)"""
    if not isinstance(s, six.string_types):
        try:
            return str(s)
        except UnicodeEncodeError:
            if isinstance(s, Exception):
                return ' '.join([force_text(arg, encoding, errors) for arg in s])
            return unicode(s).encode(encoding, errors)
    elif isinstance(s, six.text_type):
        return s.encode(encoding, errors)
    elif s and encoding != 'utf-8':
        return s.decode('utf-8', errors).encode(encoding, errors)
    else:
        return s

def adjust_attribute_sequence(*fields):
    """Move marrow.schema fields around to control positional instantiation order."""
    amount = None
    if fields and isinstance(fields[0], int):
        amount, fields = (fields[0], fields[1:])
    def adjust_inner(cls):
        for field in fields:
            if field not in cls.__dict__:
                raise TypeError('Can only override sequence on non-inherited attributes.')
            if amount is None:
                cls.__dict__[field].__sequence__ = ElementMeta.sequence
            else:
                cls.__dict__[field].__sequence__ += amount
        cls.__attributes__ = OrderedDict(((k, v) for k, v in sorted(cls.__attributes__.items(), key=lambda i: i[1].__sequence__)))
        return cls
    return adjust_inner

def get_hashes(path, exclude=None):
    """Get a dictionary of file paths and timestamps.

    Paths matching `exclude` regex will be excluded."""
    out = {}
    for f in Path(path).rglob('*'):
        if f.is_dir():
            continue
        if exclude and re.match(exclude, f.as_posix()):
            retox_log.debug("excluding '{}'".format(f.as_posix()))
            continue
        pytime = f.stat().st_mtime
        out[f.as_posix()] = pytime
    return out

def cut_levels(nodes, start_level):
    """cutting nodes away from menus"""
    final = []
    removed = []
    for node in nodes:
        if not hasattr(node, 'level'):
            remove(node, removed)
            continue
        if node.attr.get('soft_root', False):
            remove(node, removed)
            continue
        if node.level == start_level:
            final.append(node)
            node.parent = None
            if not node.visible and (not node.children):
                remove(node, removed)
        elif node.level == start_level + 1:
            node.children = []
        else:
            remove(node, removed)
        if not node.visible:
            keep_node = False
            for child in node.children:
                keep_node = keep_node or child.visible
            if not keep_node:
                remove(node, removed)
    for node in removed:
        if node in final:
            final.remove(node)
    return final

def U(Document, __raw__=None, **update):
    """Generate a MongoDB update document through paramater interpolation.

    Arguments passed by name have their name interpreted as an optional operation prefix (defaulting to `set`, e.g.
    `push`), a double-underscore separated field reference (e.g. `foo`, or `foo__bar`, or `foo__S__bar`, or
    `foo__27__bar`)

    Because this utility is likely going to be used frequently it has been given a single-character name."""
    ops = Update(__raw__)
    args = _process_arguments(Document, UPDATE_ALIASES, {}, update, UPDATE_PASSTHROUGH)
    for operation, _, field, value in args:
        if not operation:
            operation = DEFAULT_UPDATE
        if isinstance(operation, tuple):
            operation, cast = ('$' + operation[0], operation[1])
            if cast in UPDATE_MAGIC:
                value = cast(value, field)
            else:
                value = cast(value)
            if operation in ops and ~field in ops[operation] and isinstance(value, Mapping):
                ops[operation][~field].update(value)
                continue
        else:
            operation = '$' + operation
        ops &= Update({operation: {~field: value}})
    return ops

def S(Document, *fields):
    """Generate a MongoDB sort order list using the Django ORM style."""
    result = []
    for field in fields:
        if isinstance(field, tuple):
            field, direction = field
            result.append((field, direction))
            continue
        direction = ASCENDING
        if not field.startswith('__'):
            field = field.replace('__', '.')
        if field[0] == '-':
            direction = DESCENDING
        if field[0] in ('+', '-'):
            field = field[1:]
        _field = traverse(Document, field, default=None)
        result.append((~_field if _field else field, direction))
    return result

def write_taxon_info(taxon, include_anc, output):
    """Writes out data from `taxon` to the `output` stream to demonstrate
    the attributes of a taxon object.
    (currently some lines are commented out until the web-services call returns more info. See:
        https://github.com/OpenTreeOfLife/taxomachine/issues/85
    ).
    If `include_anc` is True, then ancestor information was requested (so a None parent is only
        expected at the root of the tree)"""
    output.write(u'Taxon info for OTT ID (ot:ottId) = {}\n'.format(taxon.ott_id))
    output.write(u'    name (ot:ottTaxonName) = "{}"\n'.format(taxon.name))
    if taxon.synonyms:
        output.write(u'    known synonyms: "{}"\n'.format('", "'.join(taxon.synonyms)))
    else:
        output.write(u'    known synonyms: \n')
    output.write(u'    OTT flags for this taxon: {}\n'.format(taxon.flags))
    output.write(u'    The taxonomic rank associated with this name is: {}\n'.format(taxon.rank))
    output.write(u'    The (unstable) node ID in the current taxomachine instance is: {}\n'.format(taxon.taxomachine_node_id))
    if include_anc:
        if taxon.parent is not None:
            output.write(u'Taxon {c} is a child of {p}.\n'.format(c=taxon.ott_id, p=taxon.parent.ott_id))
            write_taxon_info(taxon.parent, True, output)
        else:
            output.write('uTaxon {c} is the root of the taxonomy.'.format(c=taxon.ott_id))

def get_raw_default_config_and_read_file_list():
    """Returns a ConfigParser object and a list of filenames that were parsed to initialize it"""
    global _CONFIG, _READ_DEFAULT_FILES
    if _CONFIG is not None:
        return (_CONFIG, _READ_DEFAULT_FILES)
    with _CONFIG_LOCK:
        if _CONFIG is not None:
            return (_CONFIG, _READ_DEFAULT_FILES)
        try:
            from ConfigParser import SafeConfigParser
        except ImportError:
            from configparser import ConfigParser as SafeConfigParser
        cfg = SafeConfigParser()
        read_files = cfg.read(get_default_config_filename())
        _CONFIG, _READ_DEFAULT_FILES = (cfg, read_files)
        return (_CONFIG, _READ_DEFAULT_FILES)

def _raw_config_setting(config_obj, section, param, default=None, config_filename='', warn_on_none_level=logging.WARN):
    """Read (section, param) from `config_obj`. If not found, return `default`

    If the setting is not found and `default` is None, then an warn-level message is logged.
    `config_filename` can be None, filepath or list of filepaths - it is only used for logging.

    If warn_on_none_level is None (or lower than the logging level) message for falling through to
        a `None` default will be suppressed."""
    try:
        return config_obj.get(section, param)
    except:
        if default is None and warn_on_none_level is not None:
            _warn_missing_setting(section, param, config_filename, warn_on_none_level)
        return default

def _create_overrides_from_config(config):
    """Creates a two-level dictionary of d[section][option] from a config parser object."""
    d = {}
    for s in config.sections():
        d[s] = {}
        for opt in config.options(s):
            d[s][opt] = config.get(s, opt)
    return d

def get_config_object():
    """Thread-safe accessor for the immutable default ConfigWrapper object"""
    global _DEFAULT_CONFIG_WRAPPER
    if _DEFAULT_CONFIG_WRAPPER is not None:
        return _DEFAULT_CONFIG_WRAPPER
    with _DEFAULT_CONFIG_WRAPPER_LOCK:
        if _DEFAULT_CONFIG_WRAPPER is not None:
            return _DEFAULT_CONFIG_WRAPPER
        _DEFAULT_CONFIG_WRAPPER = ConfigWrapper()
        return _DEFAULT_CONFIG_WRAPPER

def parse_id2par_dict(id2par=None, id_list=None, id2par_stream=None, id2par_filepath=None, id_list_stream=None, id_list_filepath=None, _class=TreeWithPathsInEdges):
    """Expecting a dict of id2parent ID or a pickled object (passed in as file object `stream` or `filepath`)
    """
    import pickle
    if id2par is None:
        if id2par_stream is None:
            with open(id2par_filepath, 'rb') as fo:
                id2par = pickle.load(fo)
        else:
            id2par = pickle.load(id2par_stream)
    if id_list is None:
        if id_list_stream is None:
            if id_list_filepath is None:
                ancs = set(id2par.values())
                all_keys = set(id2par.keys())
                id_list = list(all_keys - ancs)
            else:
                with open(id_list_filepath, 'rb') as fo:
                    id_list = pickle.load(fo)
        else:
            id_list = pickle.load(id_list_stream)
    _LOG.debug('num els {}'.format(len(id2par)))
    return create_tree_from_id2par(id2par=id2par, id_list=id_list, _class=_class)

def collection_to_included_trees(collection):
    """Takes a collection object (or a filepath to collection object), returns
    each element of the `decisions` list that has the decision set to included."""
    if is_str_type(collection):
        collection = read_as_json(collection)
    inc = []
    for d in collection.get('decisions', []):
        if d['decision'] == 'INCLUDED':
            inc.append(d)
    return inc

def tree_is_in_collection(collection, study_id=None, tree_id=None):
    """Takes a collection object (or a filepath to collection object), returns
    True if it includes a decision to include the specified tree"""
    included = collection_to_included_trees(collection)
    study_id = study_id.strip()
    tree_id = tree_id.strip()
    for decision in included:
        if decision['studyID'] == study_id and decision['treeID'] == tree_id:
            return True
    return False

def validate_config(key: str, config: dict) -> None:
    """Call jsonschema validation to raise JSONValidation on non-compliance or silently pass.

    :param key: validation schema key of interest
    :param config: configuration dict to validate"""
    try:
        jsonschema.validate(config, CONFIG_JSON_SCHEMA[key])
    except jsonschema.ValidationError as x_validation:
        raise JSONValidation('JSON validation error on {} configuration: {}'.format(key, x_validation.message))
    except jsonschema.SchemaError as x_schema:
        raise JSONValidation('JSON schema error on {} specification: {}'.format(key, x_schema.message))

def __make_id(receiver):
    """Generate an identifier for a callable signal receiver.

    This is used when disconnecting receivers, where we need to correctly
    establish equivalence between the input receiver and the receivers assigned
    to a signal.

    Args:
        receiver: A callable object.

    Returns:
        An identifier for the receiver."""
    if __is_bound_method(receiver):
        return (id(receiver.__func__), id(receiver.__self__))
    return id(receiver)

def IsMetaMetaDict(AST):
    """Checks whether a given AST (abstract syntax tree) object represents a
    metametadata dictionary."""
    isintpair = lambda x: isinstance(x, Tuple) and len(x.asList()) == 2 and isctype(x.asList()[0], int) and isctype(x.asList()[1], int)
    try:
        if len(AST.getChildren()) > 1 and isinstance(AST.getChildren()[1], Stmt):
            if isinstance(AST.getChildren()[1].getChildren()[0], Assign):
                [s, d] = AST.getChildren()[1].getChildren()[0].asList()
    except (TypeError, AttributeError):
        return False
    else:
        if isinstance(s, AssName) and s.name == 'metametadata':
            if isinstance(d, Dict):
                return all([isctype(k, str) and (isctype(v, int) or isintpair(v)) for k, v in d.items])

def dialectfromstring(s):
    """Attempts to convert a string representation of a CSV
    dialect (as would be read from a file header, for instance)
    into an actual csv.Dialect object."""
    try:
        AST = compiler.parse(s)
    except SyntaxError:
        return
    else:
        try:
            if len(AST.getChildren()) > 1:
                ST = AST.getChildren()[1]
                if isinstance(ST, Stmt):
                    if isinstance(ST.getChildren()[0], Discard):
                        d = ST.getChildren()[0].asList()[0]
        except (TypeError, AttributeError):
            pass
        else:
            if isinstance(d, Dict) and len(d.items) > 0:
                if all([isctype(i[0], str) for i in d.items]):
                    testd = csv.Sniffer().sniff('a,b,c')
                    if all([n.value in dir(testd) and isctype(v, type(getattr(testd, n.value))) for n, v in d.items]):
                        D = eval(s)
                        for n in D.keys():
                            setattr(testd, n, D[n])
                        return testd

def coloringfromstring(s):
    """Attempts to convert a string representation of a coloring dictionary (as
    would be read from a file header, for instance) into an actual coloring
    dictionary."""
    try:
        AST = compiler.parse(s)
    except SyntaxError:
        return
    else:
        try:
            if len(AST.getChildren()) > 1:
                ST = AST.getChildren()[1]
                if isinstance(ST, Stmt) and isinstance(ST.getChildren()[0], Discard):
                    d = ST.getChildren()[0].asList()[0]
        except (TypeError, AttributeError):
            pass
        else:
            if isinstance(d, Dict) and len(d.items) > 0:
                if all([isctype(i[0], str) for i in d.items]):
                    if all([isinstance(i[1], List) for i in d.items]):
                        if all([all([isctype(j, str) for j in i[1]]) for i in d.items]):
                            return eval(s)

def ot_find_tree(arg_dict, exact=True, verbose=False, oti_wrapper=None):
    """Uses a peyotl wrapper around an Open Tree web service to get a list of trees including values `value` for a given property to be searched on `porperty`.

    The oti_wrapper can be None (in which case the default wrapper from peyotl.sugar will be used.
    All other arguments correspond to the arguments of the web-service call."""
    if oti_wrapper is None:
        from peyotl.sugar import oti
        oti_wrapper = oti
    return oti_wrapper.find_trees(arg_dict, exact=exact, verbose=verbose, wrap_response=True)

def proc_forward(etype, namespace: Dict[str, Any]):
    """Resolve etype to an actual type if it is a forward reference"""
    return etype._eval_type(namespace, namespace) if type(etype) is _ForwardRef else etype

def is_iterable(etype) -> bool:
    """Determine whether etype is a List or other iterable"""
    return type(etype) is GenericMeta and issubclass(etype.__extra__, Iterable)

def read_filepath(filepath, encoding='utf-8'):
    """Returns the text content of `filepath`"""
    with codecs.open(filepath, 'r', encoding=encoding) as fo:
        return fo.read()

def write_as_json(blob, dest, indent=0, sort_keys=True):
    """Writes `blob` as JSON to the filepath `dest` or the filestream `dest` (if it isn't a string)
    uses utf-8 encoding if the filepath is given (does not change the encoding if dest is already open)."""
    opened_out = False
    if is_str_type(dest):
        out = codecs.open(dest, mode='w', encoding='utf-8')
        opened_out = True
    else:
        out = dest
    try:
        json.dump(blob, out, indent=indent, sort_keys=sort_keys)
        out.write('\n')
    finally:
        out.flush()
        if opened_out:
            out.close()

def pretty_dict_str(d, indent=2):
    """shows JSON indented representation of d"""
    b = StringIO()
    write_pretty_dict_str(b, d, indent=indent)
    return b.getvalue()

def write_pretty_dict_str(out, obj, indent=2):
    """writes JSON indented representation of `obj` to `out`"""
    json.dump(obj, out, indent=indent, sort_keys=True, separators=(',', ': '), ensure_ascii=False, encoding='utf-8')

def iter_trees(nexson, nexson_version=None):
    """generator over all trees in all trees elements.
    yields a tuple of 3 items:
        trees element ID,
        tree ID,
        the tree obj"""
    if nexson_version is None:
        nexson_version = detect_nexson_version(nexson)
    nex = get_nexml_el(nexson)
    if _is_by_id_hbf(nexson_version):
        trees_group_by_id = nex['treesById']
        group_order = nex.get('^ot:treesElementOrder', [])
        if len(group_order) < len(trees_group_by_id):
            group_order = list(trees_group_by_id.keys())
            group_order.sort()
        for trees_group_id in group_order:
            trees_group = trees_group_by_id[trees_group_id]
            tree_by_id = trees_group['treeById']
            ti_order = trees_group.get('^ot:treeElementOrder', [])
            if len(ti_order) < len(tree_by_id):
                ti_order = list(tree_by_id.keys())
                ti_order.sort()
            for tree_id in ti_order:
                tree = tree_by_id[tree_id]
                yield (trees_group_id, tree_id, tree)
    else:
        for trees_group in nex.get('trees', []):
            trees_group_id = trees_group['@id']
            for tree in trees_group.get('tree', []):
                tree_id = tree['@id']
                yield (trees_group_id, tree_id, tree)

def label_to_original_label_otu_by_id(otu_by_id):
    """Takes a v1.2 otuById dict and, for every otu,
    checks if ot:originalLabel exists. If it does not,
    but @label does, then ot:originalLabel is set to
    @label and @label is deleted."""
    for val in otu_by_id.values():
        orig = val.get('^ot:originalLabel')
        if orig is None:
            label = val.get('@label')
            if label:
                del val['@label']
                val['^ot:originalLabel'] = label

def detect_nexson_version(blob):
    """Returns the nexml2json attribute or the default code for badgerfish"""
    n = get_nexml_el(blob)
    assert isinstance(n, dict)
    return n.get('@nexml2json', BADGER_FISH_NEXSON_VERSION)

def _index_list_of_values(d, k):
    """Returns d[k] or [d[k]] if the value is not a list"""
    v = d[k]
    if isinstance(v, list):
        return v
    return [v]

def _get_index_list_of_values(d, k, def_value=None):
    """Like _index_list_of_values, but uses get to access and
    returns an empty list if the key is absent.
    Returns d[k] or [d[k]] if the value is not a list"""
    v = d.get(k, def_value)
    if v is None:
        return []
    if isinstance(v, list):
        return v
    return [v]

def _add_value_to_dict_bf(d, k, v):
    """Adds the `k`->`v` mapping to `d`, but if a previous element exists it changes
    the value of for the key to list.

    This is used in the BadgerFish mapping convention.

    This is a simple multi-dict that is only suitable when you know that you'll never
    store a list or `None` as a value in the dict."""
    prev = d.get(k)
    if prev is None:
        d[k] = v
    elif isinstance(prev, list):
        if isinstance(v, list):
            prev.extend(v)
        else:
            prev.append(v)
    elif isinstance(v, list):
        x = [prev]
        x.extend(v)
        d[k] = x
    else:
        d[k] = [prev, v]

def _add_uniq_value_to_dict_bf(d, k, v):
    """Like _add_value_to_dict_bf but will not add v if another
    element in under key `k` has the same value."""
    prev = d.get(k)
    if prev is None:
        d[k] = v
    elif isinstance(prev, list):
        if not isinstance(v, list):
            v = [v]
        for sel in v:
            found = False
            for el in prev:
                if el == sel:
                    found = True
                    break
            if not found:
                prev.append(sel)
    elif isinstance(v, list):
        prev = [prev]
        for sel in v:
            found = False
            for el in prev:
                if el == sel:
                    found = True
                    break
            if not found:
                prev.append(sel)
        if len(prev) > 1:
            d[k] = prev
    elif prev != v:
        d[k] = [prev, v]

def _debug_dump_dom(el):
    """Debugging helper. Prints out `el` contents."""
    import xml.dom.minidom
    s = [el.nodeName]
    att_container = el.attributes
    for i in range(att_container.length):
        attr = att_container.item(i)
        s.append('  @{a}="{v}"'.format(a=attr.name, v=attr.value))
    for c in el.childNodes:
        if c.nodeType == xml.dom.minidom.Node.TEXT_NODE:
            s.append('  {a} type="TEXT" data="{d}"'.format(a=c.nodeName, d=c.data))
        else:
            s.append('  {a} child'.format(a=c.nodeName))
    return '\n'.join(s)

def _cull_redundant_about(obj):
    """Removes the @about key from the `obj` dict if that value refers to the
    dict's '@id'"""
    about_val = obj.get('@about')
    if about_val:
        id_val = obj.get('@id')
        if id_val and '#' + id_val == about_val:
            del obj['@about']

def _python_instance_to_nexml_meta_datatype(v):
    """Returns 'xsd:string' or a more specific type for a <meta datatype="XYZ"...
    syntax using introspection."""
    if isinstance(v, bool):
        return 'xsd:boolean'
    if is_int_type(v):
        return 'xsd:int'
    if isinstance(v, float):
        return 'xsd:float'
    return 'xsd:string'

def _convert_hbf_meta_val_for_xml(key, val):
    """Convert to a BadgerFish-style dict for addition to a dict suitable for
    addition to XML tree or for v1.0 to v0.0 conversion."""
    if isinstance(val, list):
        return [_convert_hbf_meta_val_for_xml(key, i) for i in val]
    is_literal = True
    content = None
    if isinstance(val, dict):
        ret = val
        if '@href' in val:
            is_literal = False
        else:
            content = val.get('$')
            if isinstance(content, dict) and _contains_hbf_meta_keys(val):
                is_literal = False
    else:
        ret = {}
        content = val
    if is_literal:
        ret.setdefault('@xsi:type', 'nex:LiteralMeta')
        ret.setdefault('@property', key)
        if content is not None:
            ret.setdefault('@datatype', _python_instance_to_nexml_meta_datatype(content))
        if ret is not val:
            ret['$'] = content
    else:
        ret.setdefault('@xsi:type', 'nex:ResourceMeta')
        ret.setdefault('@rel', key)
    return ret

def find_val_for_first_bf_l_meta(d, prop_name):
    """Returns the $ value of the first meta element with
    the @property that matches @prop_name (or None)."""
    m_list = d.get('meta')
    if not m_list:
        return None
    if not isinstance(m_list, list):
        m_list = [m_list]
    for m_el in m_list:
        if m_el.get('@property') == prop_name:
            return extract_meta(m_el)
    return None

def find_nested_meta_first_bf(d, prop_name):
    """Returns the $ value of the first meta element with
    the @property that matches @prop_name (or None)."""
    m_list = d.get('meta')
    if not m_list:
        return None
    if not isinstance(m_list, list):
        m_list = [m_list]
    for m_el in m_list:
        if m_el.get('@property') == prop_name or m_el.get('@rel') == prop_name:
            return m_el
    return None

def find_nested_meta_first(d, prop_name, version):
    """Returns obj. for badgerfish and val for hbf. Appropriate for nested literals"""
    if _is_badgerfish_version(version):
        return find_nested_meta_first_bf(d, prop_name)
    p = '^' + prop_name
    return d.get(p)

def decode(value: str) -> Union[str, None, bool, int, float]:
    """Decode encoded credential attribute value.

    :param value: numeric string to decode
    :return: decoded value, stringified if original was neither str, bool, int, nor float"""
    assert value.isdigit() or (value[0] == '-' and value[1:].isdigit())
    if -I32_BOUND <= int(value) < I32_BOUND:
        return int(value)
    elif int(value) == I32_BOUND:
        return None
    prefix, value = (int(value[0]), int(value[1:]))
    ival = int(value) - I32_BOUND
    if ival == 0:
        return ''
    elif ival == 1:
        return False
    elif ival == 2:
        return True
    blen = ceil(log(ival, 16) / 2)
    ibytes = unhexlify(ival.to_bytes(blen, 'big'))
    return DECODE_PREFIX.get(prefix, str)(ibytes.decode())

def validate_params_match(method, parameters):
    """Validates that the given parameters are exactly the method's declared parameters.

    :param method: The method to be called
    :type method: function
    :param parameters: The parameters to use in the call
    :type parameters: dict[str, object] | list[object]"""
    argspec = inspect.getargspec(method)
    default_length = len(argspec.defaults) if argspec.defaults is not None else 0
    if isinstance(parameters, list):
        if len(parameters) > len(argspec.args) and argspec.varargs is None:
            raise InvalidParamsError('Too many parameters')
        remaining_parameters = len(argspec.args) - len(parameters)
        if remaining_parameters > default_length:
            raise InvalidParamsError('Not enough parameters')
    elif isinstance(parameters, dict):
        missing_parameters = [key for key in argspec.args if key not in parameters]
        default_parameters = set(argspec.args[len(argspec.args) - default_length:])
        for key in missing_parameters:
            if key not in default_parameters:
                raise InvalidParamsError('Parameter {} has not been satisfied'.format(key))
        extra_params = [key for key in parameters if key not in argspec.args]
        if len(extra_params) > 0 and argspec.keywords is None:
            raise InvalidParamsError('Too many parameters')

def check_types(parameters, parameter_types, strict_floats):
    """Checks that the given parameters have the correct types.

    :param parameters: List of (name, value) pairs of the given parameters
    :type parameters: dict[str, object]
    :param parameter_types: Parameter type by name.
    :type parameter_types: dict[str, type]
    :param strict_floats: If False, treat integers as floats
    :type strict_floats: bool"""
    for name, parameter_type in parameter_types.items():
        if name not in parameters:
            raise InvalidParamsError("Parameter '{}' is missing.".format(name))
        if not _is_instance(parameters[name], parameter_type, strict_floats):
            raise InvalidParamsError("Value '{}' for parameter '{}' is not of expected type {}.".format(parameters[name], name, parameter_type))

def check_type_declaration(parameter_names, parameter_types):
    """Checks that exactly the given parameter names have declared types.

    :param parameter_names: The names of the parameters in the method declaration
    :type parameter_names: list[str]
    :param parameter_types: Parameter type by name
    :type parameter_types: dict[str, type]"""
    if len(parameter_names) != len(parameter_types):
        raise Exception('Number of method parameters ({}) does not match number of declared types ({})'.format(len(parameter_names), len(parameter_types)))
    for parameter_name in parameter_names:
        if parameter_name not in parameter_types:
            raise Exception("Parameter '{}' does not have a declared type".format(parameter_name))

def check_return_type(value, expected_type, strict_floats):
    """Checks that the given return value has the correct type.

    :param value: Value returned by the method
    :type value: object
    :param expected_type: Expected return type
    :type expected_type: type
    :param strict_floats: If False, treat integers as floats
    :type strict_floats: bool"""
    if expected_type is None:
        if value is not None:
            raise InvalidReturnTypeError("Returned value is '{}' but None was expected".format(value))
    elif not _is_instance(value, expected_type, strict_floats):
        raise InvalidReturnTypeError("Type of return value '{}' does not match expected type {}".format(value, expected_type))

def get_repos(par_list=None, **kwargs):
    """Returns a dictionary of name -> filepath
    `name` is the repo name based on the dir name (not the get repo). It is not
        terribly useful, but it is nice to have so that any mirrored repo directory can
        use the same naming convention.
    `filepath` will be the full path to the repo directory (it will end in `name`)"""
    _repos = {}
    if par_list is None:
        par_list = _get_phylesystem_parent(**kwargs)
    elif not isinstance(par_list, list):
        par_list = [par_list]
    for p in par_list:
        if not os.path.isdir(p):
            raise ValueError('Phylesystem parent "{p}" is not a directory'.format(p=p))
        for name in os.listdir(p):
            if os.path.isdir(os.path.join(p, name + '/.git')):
                _repos[name] = os.path.abspath(os.path.join(p, name))
    if len(_repos) == 0:
        raise ValueError('No git repos in {parent}'.format(parent=str(par_list)))
    return _repos

def create_id2amendment_info(path, tag):
    """Searches for JSON files in this repo and returns
    a map of amendment id ==> (`tag`, dir, amendment filepath)
    where `tag` is typically the shard name"""
    d = {}
    for triple in os.walk(path):
        root, files = (triple[0], triple[2])
        for filename in files:
            if filename.endswith('.json'):
                amendment_id = n = filename[:-5]
                d[amendment_id] = (tag, root, os.path.join(root, filename))
    return d

def loads_loader(load_module: types.ModuleType, pairs: Dict[str, str]) -> Optional[JSGValidateable]:
    """json loader objecthook

    :param load_module: Module that contains the various types
    :param pairs: key/value tuples (In our case, they are str/str)
    :return:"""
    cntxt = load_module._CONTEXT
    possible_type = pairs[cntxt.TYPE] if cntxt.TYPE in pairs else None
    target_class = getattr(load_module, possible_type, None) if isinstance(possible_type, str) else None
    if target_class:
        return target_class(**pairs)
    for type_exception in cntxt.TYPE_EXCEPTIONS:
        if not hasattr(load_module, type_exception):
            raise ValueError(UNKNOWN_TYPE_EXCEPTION.format(type_exception))
        target_class = getattr(load_module, type_exception)
        target_strict = target_class._strict
        target_class._strict = False
        try:
            rval = target_class(**pairs)
        finally:
            target_class._strict = target_strict
        if is_valid(rval):
            return rval
    if not cntxt.TYPE and cntxt.TYPE_EXCEPTIONS:
        return getattr(load_module, cntxt.TYPE_EXCEPTIONS[0])(**pairs)
    if cntxt.TYPE in pairs:
        raise ValueError(f'Unknown reference type: "{cntxt.TYPE}": "{pairs[cntxt.TYPE]}"')
    else:
        raise ValueError(f'Missing "{cntxt.TYPE}" element')

def load(fp: Union[TextIO, str], load_module: types.ModuleType, **kwargs):
    """Convert a file name or file-like object containing stringified JSON into a JSGObject

    :param fp: file-like object to deserialize
    :param load_module: module that contains declarations for types
    :param kwargs: arguments see: json.load for details
    :return: JSGObject representing the json string"""
    if isinstance(fp, str):
        with open(fp) as f:
            return loads(f.read(), load_module, **kwargs)
    else:
        return loads(fp.read(), load_module, **kwargs)

def isinstance_(x, A_tuple):
    """native isinstance_ with the test for typing.Union overridden"""
    if is_union(A_tuple):
        return any((isinstance_(x, t) for t in A_tuple.__args__))
    elif getattr(A_tuple, '__origin__', None) is not None:
        return isinstance(x, A_tuple.__origin__)
    else:
        return isinstance(x, A_tuple)

def is_valid(obj: JSGValidateable, log: Optional[Union[TextIO, Logger]]=None) -> bool:
    """Determine whether obj is valid

    :param obj: Object to validate
    :param log: Logger to record validation failures.  If absent, no information is recorded"""
    return obj._is_valid(log)

def create_pruned_and_taxonomy_for_tip_ott_ids(tree_proxy, ott, create_monotypic_nodes=False):
    """returns a pair of trees:
    the first is that is a pruned version of tree_proxy created by pruning
        any leaf that has no ott_id and every internal that does not have
        any descendant with an ott_id. Nodes of out-degree 1 are suppressed
        as part of the TreeWithPathsInEdges-style.
    the second is the OTT induced tree for these ott_ids"""
    ott_ids = []
    ott_id_2_otu_par = {}
    for node in tree_proxy:
        if node.is_leaf:
            ott_id = node.ott_id
            if ott_id is not None:
                ott_ids.append(ott_id)
                assert isinstance(ott_id, int)
                parent_id = node.parent._id
                ott_id_2_otu_par[ott_id] = parent_id
        else:
            assert is_str_type(node._id)
            edge = node.edge
            if edge is not None:
                parent_id = node.parent._id
                ott_id_2_otu_par[node._id] = parent_id
            else:
                ott_id_2_otu_par[node._id] = None
    pruned_phylo = create_tree_from_id2par(ott_id_2_otu_par, ott_ids, create_monotypic_nodes=create_monotypic_nodes)
    taxo_tree = ott.induced_tree(ott_ids)
    return (pruned_phylo, taxo_tree)

def arg_tup_to_dict(argument_tuples):
    """Given a set of argument tuples, set their value in a data dictionary if not blank"""
    data = dict()
    for arg_name, arg_val in argument_tuples:
        if arg_val is not None:
            if arg_val is True:
                arg_val = 'true'
            elif arg_val is False:
                arg_val = 'false'
            data[arg_name] = arg_val
    return data

def handle_error(response):
    """Raise appropriate exceptions if necessary."""
    status_code = response.status_code
    if status_code not in A_OK_HTTP_CODES:
        error_explanation = A_ERROR_HTTP_CODES.get(status_code)
        raise_error = '{}: {}'.format(status_code, error_explanation)
        raise Exception(raise_error)
    else:
        return True

def add_schema_attributes(container, nexson_version):
    """Adds several attributes to `container`:
    _using_hbf_meta  - boolean. True for HoneyBadgerFish v1-style meta elements ('^prop': value
                rather than 'meta': {'$':value})
    and the following _SchemaFragment instances:
    _NexmlEl_Schema"""
    if _is_by_id_hbf(nexson_version):
        _add_by_id_nexson_schema_attributes(container)
    elif _is_badgerfish_version(nexson_version):
        _add_badgerfish_nexson_schema_attributes(container)
    elif _is_direct_hbf(nexson_version):
        _add_direct_nexson_schema_attributes(container)
    else:
        raise NotImplementedError('unrecognized nexson variant {}'.format(nexson_version))

def proc_forward(etype, namespace: Dict[str, Any]):
    """Resolve etype to an actual type if it is a forward reference"""
    return etype._evaluate(namespace, namespace) if type(etype) is ForwardRef else etype

def is_union(etype) -> bool:
    """Determine whether etype is a Union"""
    return getattr(etype, '__origin__', None) is not None and getattr(etype.__origin__, '_name', None) and (etype.__origin__._name == 'Union')

def _get_filtered_study_ids(shard, include_aliases=False):
    """Optionally filters out aliases from standard doc-id list"""
    from peyotl.phylesystem.helper import DIGIT_PATTERN
    k = shard.get_doc_ids()
    if shard.has_aliases and (not include_aliases):
        x = []
        for i in k:
            if DIGIT_PATTERN.match(i) or (len(i) > 1 and i[-2] == '_'):
                pass
            else:
                x.append(i)
        return x

def flatten(l: Iterable) -> List:
    """Return a list of all non-list items in l

    :param l: list to be flattened
    :return:"""
    rval = []
    for e in l:
        if not isinstance(e, str) and isinstance(e, Iterable):
            if len(list(e)):
                rval += flatten(e)
        else:
            rval.append(e)
    return rval

def flatten_unique(l: Iterable) -> List:
    """Return a list of UNIQUE non-list items in l"""
    rval = OrderedDict()
    for e in l:
        if not isinstance(e, str) and isinstance(e, Iterable):
            for ev in flatten_unique(e):
                rval[ev] = None
        else:
            rval[e] = None
    return list(rval.keys())

def is_valid_python(tkn: str) -> bool:
    """Determine whether tkn is a valid python identifier

    :param tkn:
    :return:"""
    try:
        root = ast.parse(tkn)
    except SyntaxError:
        return False
    return len(root.body) == 1 and isinstance(root.body[0], ast.Expr) and isinstance(root.body[0].value, ast.Name)

def sets_are_rooted_compat(one_set, other):
    """treats the 2 sets are sets of taxon IDs on the same (unstated)
    universe of taxon ids.
    Returns True clades implied by each are compatible and False otherwise"""
    if one_set.issubset(other) or other.issubset(one_set):
        return True
    return not intersection_not_empty(one_set, other)

def gen_otu_dict(nex_obj, nexson_version=None):
    """Takes a NexSON object and returns a dict of
    otu_id -> otu_obj"""
    if nexson_version is None:
        nexson_version = detect_nexson_version(nex_obj)
    if _is_by_id_hbf(nexson_version):
        otus = nex_obj['nexml']['otusById']
        if len(otus) > 1:
            d = {}
            for v in otus.values():
                d.update(v['otuById'])
            return d
        else:
            return otus.values()[0]['otuById']
    o_dict = {}
    for ob in nex_obj.get('otus', []):
        for o in ob.get('otu', []):
            oid = o['@id']
            o_dict[oid] = o
    return o_dict

def acquire_lock_raise(git_action, fail_msg=''):
    """Adapts LockError to HTTP. If an exception is not thrown, the git_action has the lock (and must release it!)
    """
    try:
        git_action.acquire_lock()
    except LockError as e:
        msg = '{o} Details: {d}'.format(o=fail_msg, d=e.message)
        _LOG.debug(msg)
        raise GitWorkflowError(msg)

def set_country(request):
    """Sets the chosen country in the session or cookie.

    If `next' query param is present, it redirects to a given url."""
    if request.method == 'POST':
        next = request.POST.get('next', request.GET.get('next'))
        if is_safe_url(url=next, host=request.get_host()):
            response = http.HttpResponseRedirect(next)
        else:
            response = http.HttpResponse()
        country_code = request.POST.get('country', '').upper()
        if country_code != geo.get_supported_country(country_code):
            return http.HttpResponseBadRequest()
        if hasattr(request, 'session'):
            request.session[geo.COUNTRY_SESSION_KEY] = country_code
        else:
            response.set_cookie(geo.COUNTRY_COOKIE_NAME, country_code, max_age=geo.COUNTRY_COOKIE_AGE, path=geo.COUNTRY_COOKIE_PATH)
        return response
    else:
        return http.HttpResponseNotAllowed(['POST'])

def create_content_spec(**kwargs):
    """Sugar. factory for a PhyloSchema object.

    Repackages the kwargs to kwargs for PhyloSchema so that our
    PhyloSchema.__init__ does not have to be soo rich"""
    format_str = kwargs.get('format', 'nexson')
    nexson_version = kwargs.get('nexson_version', 'native')
    otu_label = kwargs.get('otu_label')
    if otu_label is None:
        otu_label = kwargs.get('tip_label')
    content = kwargs.get('content')
    if content is not None:
        content_id = kwargs.get('content_id')
        if content_id is None:
            content_id = _get_content_id_from(**kwargs)
    else:
        content, content_id = _sniff_content_from_kwargs(**kwargs)
    if content is None:
        content = 'study'
    return PhyloSchema(content=content, content_id=content_id, format_str=format_str, version=nexson_version, otu_label=otu_label, repo_nexml2json=kwargs.get('repo_nexml2json'), bracket_ingroup=bool(kwargs.get('bracket_ingroup', False)), cull_nonmatching=kwargs.get('cull_nonmatching'))

def sort_arbitrarily_ordered_nexson(blob):
    """Primarily used for testing (getting nice diffs). Calls
    sort_meta_elements and then sorts otu, node and edge list by id"""
    v = detect_nexson_version(blob)
    nex = get_nexml_el(blob)
    if _is_by_id_hbf(v):
        return blob
    sort_meta_elements(blob)
    for ob in _get_index_list_of_values(nex, 'otus'):
        _inplace_sort_by_id(ob.get('otu', []))
    for tb in _get_index_list_of_values(nex, 'trees'):
        for tree in _get_index_list_of_values(tb, 'tree'):
            _inplace_sort_by_id(tree.get('node', []))
            _inplace_sort_by_id(tree.get('edge', []))
    return blob

def cull_nonmatching_trees(nexson, tree_id, curr_version=None):
    """Modifies `nexson` and returns it in version 1.2.1
    with any tree that does not match the ID removed.

    Note that this does not search through the NexSON for
    every node, edge, tree that was deleted. So the resulting
    NexSON may have broken references !"""
    if curr_version is None:
        curr_version = detect_nexson_version(nexson)
    if not _is_by_id_hbf(curr_version):
        nexson = convert_nexson_format(nexson, BY_ID_HONEY_BADGERFISH)
    nexml_el = get_nexml_el(nexson)
    tree_groups = nexml_el['treesById']
    tree_groups_to_del = []
    for tgi, tree_group in tree_groups.items():
        tbi = tree_group['treeById']
        if tree_id in tbi:
            trees_to_del = [i for i in tbi.keys() if i != tree_id]
            for tid in trees_to_del:
                tree_group['^ot:treeElementOrder'].remove(tid)
                del tbi[tid]
        else:
            tree_groups_to_del.append(tgi)
    for tgid in tree_groups_to_del:
        nexml_el['^ot:treesElementOrder'].remove(tgid)
        del tree_groups[tgid]
    return nexson

def extract_tree_nexson(nexson, tree_id, curr_version=None):
    """Returns a list of (id, tree, otus_group) tuples for the
    specified tree_id (all trees if tree_id is None)"""
    if curr_version is None:
        curr_version = detect_nexson_version(nexson)
    if not _is_by_id_hbf(curr_version):
        nexson = convert_nexson_format(nexson, BY_ID_HONEY_BADGERFISH)
    nexml_el = get_nexml_el(nexson)
    tree_groups = nexml_el['treesById']
    tree_obj_otus_group_list = []
    for tree_group in tree_groups.values():
        if tree_id:
            tree_list = [(tree_id, tree_group['treeById'].get(tree_id))]
        else:
            tree_list = tree_group['treeById'].items()
        for tid, tree in tree_list:
            if tree is not None:
                otu_groups = nexml_el['otusById']
                ogi = tree_group['@otus']
                otu_group = otu_groups[ogi]['otuById']
                tree_obj_otus_group_list.append((tid, tree, otu_group))
                if tree_id is not None:
                    return tree_obj_otus_group_list
    return tree_obj_otus_group_list

def otu_iter_nexson_proxy(nexson_proxy, otu_sort=None):
    """otu_sort can be None (not sorted or stable), True (sorted by ID lexigraphically)
    or a key function for a sort function on list of otuIDs

    Note that if there are multiple OTU groups, the NexSON specifies the order of sorting
        of the groups (so the sort argument here only refers to the sorting of OTUs within
        a group)"""
    nexml_el = nexson_proxy._nexml_el
    og_order = nexml_el['^ot:otusElementOrder']
    ogd = nexml_el['otusById']
    for og_id in og_order:
        og = ogd[og_id]
        if otu_sort is None:
            for k, v in og:
                yield nexson_proxy._create_otu_proxy(k, v)
        else:
            key_list = list(og.keys())
            if otu_sort is True:
                key_list.sort()
            else:
                key_list.sort(key=otu_sort)
            for k in key_list:
                v = og[k]
                yield nexson_proxy._create_otu_proxy(k, v)

def validate_and_convert_nexson(nexson, output_version, allow_invalid, **kwargs):
    """Runs the nexson validator and returns a converted 4 object:
        nexson, annotation, validation_log, nexson_adaptor

    `nexson` is the nexson dict.
    `output_version` is the version of nexson syntax to be used after validation.
    if `allow_invalid` is False, and the nexson validation has errors, then
        a GitWorkflowError will be generated before conversion."""
    try:
        if TRACE_FILES:
            _write_to_next_free('input', nexson)
        annotation, validation_log, nexson_adaptor = ot_validate(nexson, **kwargs)
        if TRACE_FILES:
            _write_to_next_free('annotation', annotation)
    except:
        msg = 'exception in ot_validate: ' + traceback.format_exc()
        raise GitWorkflowError(msg)
    if not allow_invalid and validation_log.has_error():
        raise GitWorkflowError('ot_validation failed: ' + json.dumps(annotation))
    nexson = convert_nexson_format(nexson, output_version)
    if TRACE_FILES:
        _write_to_next_free('converted', nexson)
    return (nexson, annotation, validation_log, nexson_adaptor)

