def parse_datetime(value):
    """Attempts to parse `value` into an instance of ``datetime.datetime``. If
    `value` is ``None``, this function will return ``None``.

    Args:
        value: A timestamp. This can be a string or datetime.datetime value."""
    if not value:
        return None
    elif isinstance(value, datetime.datetime):
        return value
    return dateutil.parser.parse(value)

def parse_date(value):
    """Attempts to parse `value` into an instance of ``datetime.date``. If
    `value` is ``None``, this function will return ``None``.

    Args:
        value: A timestamp. This can be a string, datetime.date, or
            datetime.datetime value."""
    if not value:
        return None
    if isinstance(value, datetime.date):
        return value
    return parse_datetime(value).date()

def serialize_date(value):
    """Attempts to convert `value` into an ``xs:date`` string. If `value` is
    ``None``, ``None`` will be returned.

    Args:
        value: A date value. This can be a string, datetime.date, or
            datetime.datetime object.

    Returns:
        An ``xs:date`` formatted timestamp string."""
    if not value:
        return None
    elif isinstance(value, datetime.datetime):
        return value.date().isoformat()
    elif isinstance(value, datetime.date):
        return value.isoformat()
    else:
        return parse_date(value).isoformat()

def underscored2camel_case(v):
    """converts ott_id to ottId."""
    vlist = v.split('_')
    c = []
    for n, el in enumerate(vlist):
        if el:
            if n == 0:
                c.append(el)
            else:
                c.extend([el[0].upper(), el[1:]])
    return ''.join(c)

def tab_colstack(ListOfTabArrays, mode='abort'):
    """"Horizontal stacking" of tabarrays, e.g. adding columns.

    Wrapper for :func:`tabular.spreadsheet.colstack` that deals with the
    coloring and returns the result as a tabarray.

    Method calls::

        data = tabular.spreadsheet.colstack(ListOfTabArrays, mode=mode)"""
    data, naming = spreadsheet.colstack(ListOfTabArrays, mode=mode, returnnaming=True)
    coloring = {}
    for i, a in enumerate(ListOfTabArrays):
        namedict = dict([(x, y) for j, x, y in naming if i == j])
        for k in a.coloring:
            s = [namedict[kk] for kk in a.coloring[k]]
            if k in coloring.keys():
                coloring[k] = utils.uniqify(coloring[k] + s)
            else:
                coloring[k] = s
    for k in coloring.keys():
        s = [x for x in coloring[k] if x in data.dtype.names]
        if len(s) > 0:
            coloring[k] = s
        else:
            coloring.pop(k)
    data = data.view(tabarray)
    data.coloring = coloring
    return data

def tab_rowstack(ListOfTabArrays, mode='nulls'):
    """"Vertical stacking" of tabarrays, e.g. adding rows.

    Wrapper for :func:`tabular.spreadsheet.rowstack` that deals with the
    coloring and returns the result as a tabarray.

    Method calls::

        data = tabular.spreadsheet.rowstack(ListOfTabArrays, mode=mode)"""
    data = spreadsheet.rowstack(ListOfTabArrays, mode=mode)
    coloring = {}
    for a in ListOfTabArrays:
        for k in a.coloring:
            if k in coloring.keys():
                coloring[k] = utils.uniqify(coloring[k] + a.coloring[k])
            else:
                coloring[k] = a.coloring[k]
    for k in coloring.keys():
        s = [x for x in coloring[k] if x in data.dtype.names]
        if len(s) > 0:
            coloring[k] = s
        else:
            coloring.pop(k)
    data = data.view(tabarray)
    data.coloring = coloring
    return data

def tab_join(ToMerge, keycols=None, nullvals=None, renamer=None, returnrenaming=False, Names=None):
    """Database-join for tabular arrays.

    Wrapper for :func:`tabular.spreadsheet.join` that deals with the coloring
    and returns the result as a tabarray.

    Method calls::

            data = tabular.spreadsheet.join"""
    [Result, Renaming] = spreadsheet.join(ToMerge, keycols=keycols, nullvals=nullvals, renamer=renamer, returnrenaming=True, Names=Names)
    if isinstance(ToMerge, dict):
        Names = ToMerge.keys()
    else:
        Names = range(len(ToMerge))
    Colorings = dict([(k, ToMerge[k].coloring) if 'coloring' in dir(ToMerge[k]) else {} for k in Names])
    for k in Names:
        if k in Renaming.keys():
            l = ToMerge[k]
            Colorings[k] = dict([(g, [n if not n in Renaming[k].keys() else Renaming[k][n] for n in l.coloring[g]]) for g in Colorings[k].keys()])
    Coloring = {}
    for k in Colorings.keys():
        for j in Colorings[k].keys():
            if j in Coloring.keys():
                Coloring[j] = utils.uniqify(Coloring[j] + Colorings[k][j])
            else:
                Coloring[j] = utils.uniqify(Colorings[k][j])
    Result = Result.view(tabarray)
    Result.coloring = Coloring
    if returnrenaming:
        return [Result, Renaming]
    else:
        return Result

def get_logger(name='peyotl'):
    """Returns a logger with name set as given. See _read_logging_config for a description of the env var/config
    file cascade that controls configuration of the logger."""
    logger = logging.getLogger(name)
    if len(logger.handlers) == 0:
        log_init_warnings = []
        lc = _read_logging_config(log_init_warnings)
        logger.setLevel(lc['level'])
        if lc['filepath'] is not None:
            log_dir = lc['log_dir']
            if log_dir and (not os.path.exists(log_dir)):
                os.makedirs(log_dir)
            ch = logging.FileHandler(lc['filepath'])
        else:
            ch = logging.StreamHandler()
        ch.setLevel(lc['level'])
        ch.setFormatter(lc['formatter'])
        logger.addHandler(ch)
        if log_init_warnings:
            for w in log_init_warnings:
                logger.warn(w)
    return logger

def warn_from_util_logger(msg):
    """Only to be used in this file and peyotl.utility.get_config"""
    global _LOG
    if _LOG is None and _LOGGING_CONF is None:
        sys.stderr.write('WARNING: (from peyotl before logging is configured) {}\n'.format(msg))
        return
    if _LOG is None:
        _LOG = get_logger('peyotl.utility')
    _LOG.warn(msg)

def count_num_trees(nexson, nexson_version=None):
    """Returns the number of trees summed across all tree
    groups."""
    if nexson_version is None:
        nexson_version = detect_nexson_version(nexson)
    nex = get_nexml_el(nexson)
    num_trees_by_group = []
    if _is_by_id_hbf(nexson_version):
        for tree_group in nex.get('treesById', {}).values():
            nt = len(tree_group.get('treeById', {}))
            num_trees_by_group.append(nt)
    else:
        trees_group = nex.get('trees', [])
        if isinstance(trees_group, dict):
            trees_group = [trees_group]
        for tree_group in trees_group:
            t = tree_group.get('tree')
            if isinstance(t, list):
                nt = len(t)
            else:
                nt = 1
            num_trees_by_group.append(nt)
    return sum(num_trees_by_group)

def discover_roku():
    """Search LAN for available Roku devices. Returns a Roku object."""
    print('Searching for Roku devices within LAN ...')
    rokus = Roku.discover()
    if not rokus:
        print('Unable to discover Roku devices. ' + 'Try again, or manually specify the IP address with ' + "'roku <ipaddr>' (e.g. roku 192.168.1.130)")
        return None
    print('Found the following Roku devices:')
    for i, r in enumerate(rokus):
        dinfo = ''
        print('[' + str(i + 1) + ']   ' + str(r.host) + ':' + str(r.port) + ' (' + dinfo + ')')
    print('')
    if len(rokus) == 1:
        print('Selecting Roku 1 by default')
        return rokus[0]
    else:
        print('Multiple Rokus found. Select the index of the Roku to control:')
        while True:
            try:
                query = 'Select (1 to ' + str(len(rokus)) + ') > '
                sel = int(input(query)) - 1
                if sel >= len(rokus):
                    raise ValueError
                else:
                    break
            except ValueError:
                print('Invalid selection')
        return rokus[sel]

def write_taxon_info(taxon, include_anc, output):
    """Writes out data from `taxon` to the `output` stream to demonstrate
    the attributes of a taxon object.
    (currently some lines are commented out until the web-services call returns more info. See:
        https://github.com/OpenTreeOfLife/taxomachine/issues/85
    ).
    If `include_anc` is True, then ancestor information was requested (so a None parent is only
        expected at the root of the tree)"""
    output.write('Taxon info for OTT ID (ot:ottId) = {}\n'.format(taxon.ott_id))
    output.write('    name (ot:ottTaxonName) = "{}"\n'.format(taxon.name))
    if taxon.synonyms:
        output.write('    known synonyms: "{}"\n'.format('", "'.join(taxon.synonyms)))
    else:
        output.write('    known synonyms: \n')
    output.write('    OTT flags for this taxon: {}\n'.format(taxon.flags))
    output.write('    The taxonomic rank associated with this name is: {}\n'.format(taxon.rank))
    output.write('    The (unstable) node ID in the current taxomachine instance is: {}\n'.format(taxon.taxomachine_node_id))
    if include_anc:
        if taxon.parent is not None:
            output.write('Taxon {c} is a child of {p}.\n'.format(c=taxon.ott_id, p=taxon.parent.ott_id))
            write_taxon_info(taxon.parent, True, output)
        else:
            output.write('Taxon {c} is the root of the taxonomy.'.format(c=taxon.ott_id))

def _objectify(field, value, ns_info):
    """Make `value` suitable for a binding object.

    If `value` is an Entity, call to_obj() on it. Otherwise, pass it
    off to the TypedField for an appropriate value."""
    if getattr(field.type_, '_treat_none_as_empty_list', False) and value is None:
        return []
    if value is None:
        return None
    elif field.type_:
        return value.to_obj(ns_info=ns_info)
    return field.binding_value(value)

def _dictify(field, value):
    """Make `value` suitable for a dictionary.

    * If `value` is an Entity, call to_dict() on it.
    * If value is a timestamp, turn it into a string value.
    * If none of the above are satisfied, return the input value"""
    if value is None:
        return None
    elif field.type_:
        return value.to_dict()
    return field.dict_value(value)

def element_conforms(element, etype) -> bool:
    """Determine whether element conforms to etype"""
    from pyjsg.jsglib import Empty
    if isinstance(element, etype):
        return True
    if (element is None or element is Empty) and issubclass(etype, type(None)):
        return True
    elif element is Empty:
        return False
    elif isinstance(etype, type(type)) and issubclass(etype, type(None)):
        return element is None
    elif element is None:
        return False
    else:
        return isinstance(element, etype)

def conforms(element, etype, namespace: Dict[str, Any]) -> bool:
    """Determine whether element conforms to etype

    :param element: Element to test for conformance
    :param etype: Type to test against
    :param namespace: Namespace to use to resolve forward references
    :return:"""
    etype = proc_forward(etype, namespace)
    if is_union(etype):
        return union_conforms(element, etype, namespace, conforms)
    else:
        return element_conforms(element, etype)

