def create_id2collection_info(path, tag):
    """Searchers for JSON files in this repo and returns
    a map of collection id ==> (`tag`, dir, collection filepath)
    where `tag` is typically the shard name"""
    d = {}
    for triple in os.walk(path):
        root, files = (triple[0], triple[2])
        for filename in files:
            if filename.endswith('.json'):
                collection_id = '{u}/{n}'.format(u=root.split('/')[-1], n=filename[:-5])
                d[collection_id] = (tag, root, os.path.join(root, filename))
    return d

def resolve_class(classref):
    """Attempt to return a Python class for the input class reference.

    If `classref` is a class or None, return it. If `classref` is a
    python classpath (e.g., "foo.bar.MyClass") import the class and return
    it.

    Args:
        classref: A fully-qualified Python path to class, or a Python class.

    Returns:
        A class."""
    if classref is None:
        return None
    elif isinstance(classref, six.class_types):
        return classref
    elif isinstance(classref, six.string_types):
        return import_class(classref)
    else:
        raise ValueError("Unable to resolve class for '%s'" % classref)

def parse(raw_status, strip_units=False):
    """Split the output from get_status() into lines, clean it up and return it as
    an OrderedDict."""
    lines = split(raw_status)
    if strip_units:
        lines = strip_units_from_lines(lines)
    return OrderedDict([[x.strip() for x in x.split(SEP, 1)] for x in lines])

def strip_units_from_lines(lines):
    """Removes all units from the ends of the lines."""
    for line in lines:
        for unit in ALL_UNITS:
            if line.endswith(' %s' % unit):
                line = line[:-1 - len(unit)]
        yield line

def print_status(raw_status, strip_units=False):
    """Print the status to stdout in the same format as the original apcaccess."""
    lines = split(raw_status)
    if strip_units:
        lines = strip_units_from_lines(lines)
    for line in lines:
        print(line)

def cred_def_id(issuer_did: str, schema_seq_no: int) -> str:
    """Return credential definition identifier for input issuer DID and schema sequence number.

    :param issuer_did: DID of credential definition issuer
    :param schema_seq_no: schema sequence number
    :return: credential definition identifier"""
    return '{}:3:CL:{}:{}'.format(issuer_did, schema_seq_no, CD_ID_TAG)

def rev_reg_id2cred_def_id__tag(rr_id: str) -> (str, str):
    """Given a revocation registry identifier, return its corresponding credential definition identifier and
    (stringified int) tag.

    :param rr_id: revocation registry identifier
    :return: credential definition identifier and tag"""
    return (':'.join(rr_id.split(':')[2:-2]), str(rr_id.split(':')[-1]))

def box_ids(creds: dict, cred_ids: list=None) -> dict:
    """Given a credentials structure and an optional list of credential identifiers
    (aka wallet cred-ids, referents; specify None to include all), return dict mapping each
    credential identifier to a box ids structure (i.e., a dict specifying its corresponding
    schema identifier, credential definition identifier, and revocation registry identifier,
    the latter being None if cred def does not support revocation).

    :param creds: creds structure returned by (HolderProver agent) get_creds()
    :param cred_ids: list of credential identifiers for which to find corresponding schema identifiers, None for all
    :return: dict mapping each credential identifier to its corresponding box ids (empty dict if
        no matching credential identifiers present)"""
    rv = {}
    for inner_creds in {**creds.get('attrs', {}), **creds.get('predicates', {})}.values():
        for cred in inner_creds:
            cred_info = cred['cred_info']
            cred_id = cred_info['referent']
            if cred_id not in rv and (not cred_ids or cred_id in cred_ids):
                rv[cred_id] = {'schema_id': cred_info['schema_id'], 'cred_def_id': cred_info['cred_def_id'], 'rev_reg_id': cred_info['rev_reg_id']}
    return rv

def revoc_info(creds: dict, filt: dict=None) -> dict:
    """Given a creds structure, return a dict mapping pairs
    (revocation registry identifier, credential revocation identifier)
    to (decoded) attribute name:value dicts.

    If the caller includes a filter of attribute:value pairs, retain only matching attributes.

    :param creds: creds structure returned by HolderProver.get_creds() as above
    :param filt: dict mapping attributes to values of interest; e.g.,

    ::

        {
            'legalName': 'Flan Nebula',
            'effectiveDate': '2018-01-01',
            'endDate': None
        }

    :return: dict mapping (rev_reg_id, cred_rev_id) pairs to decoded attributes"""
    rv = {}
    for uuid2creds in (creds.get('attrs', {}), creds.get('predicates', {})):
        for inner_creds in uuid2creds.values():
            for cred in inner_creds:
                cred_info = cred['cred_info']
                rr_id, cr_id = (cred_info['rev_reg_id'], cred_info['cred_rev_id'])
                if (rr_id, cr_id) in rv or rr_id is None or cr_id is None:
                    continue
                if not filt:
                    rv[rr_id, cr_id] = cred_info['attrs']
                    continue
                if {attr: str(filt[attr]) for attr in filt}.items() <= cred_info['attrs'].items():
                    rv[rr_id, cr_id] = cred_info['attrs']
    return rv

def revealed_attrs(proof: dict) -> dict:
    """Fetch revealed attributes from input proof and return dict mapping credential definition identifiers
    to dicts, each dict mapping attribute names to (decoded) values, for processing in further creds downstream.

    :param: indy-sdk proof as dict
    :return: dict mapping cred-ids to dicts, each mapping revealed attribute names to (decoded) values"""
    rv = {}
    for sub_index in range(len(proof['identifiers'])):
        cd_id = proof['identifiers'][sub_index]['cred_def_id']
        rv[cd_id] = {attr: decode(proof['proof']['proofs'][sub_index]['primary_proof']['eq_proof']['revealed_attrs'][attr]) for attr in proof['proof']['proofs'][sub_index]['primary_proof']['eq_proof']['revealed_attrs']}
    return rv

def get_country_from_request(request):
    """Analyzes the request to find which country the user wants
    the system to recognize. It checks the following sources
    in the given order:
    * session,
    * cookie,
    * HTTP_ACCEPT_LANGUAGE HTTP header, and
    * IP address if USE_GEOIP is True.

    It returns country code in ISO 3166-1 alpha-2 format."""
    if hasattr(request, 'session'):
        country_code = request.session.get(COUNTRY_SESSION_KEY)
        if country_code:
            return get_supported_country(country_code)
    country_code = request.COOKIES.get(COUNTRY_COOKIE_NAME)
    if country_code:
        return get_supported_country(country_code)
    if USE_GEOIP:
        ip = _extract_ip_address(request.META)
        country_code = _geo.country_code_by_addr(ip)
        if country_code:
            return get_supported_country(country_code)
    if USE_LOCALE:
        accept = request.META.get('HTTP_ACCEPT_LANGUAGE', '')
        for accept_lang, _ in trans_real.parse_accept_lang_header(accept):
            if LANG_COUNTRY_DELIM in accept_lang:
                country_code = accept_lang.split(LANG_COUNTRY_DELIM)[-1]
                if country_code:
                    return get_supported_country(country_code)
    return DEFAULT_COUNTRY_CODE

def _extract_text_and_child_element_list(minidom_node):
    """Returns a pair of the "child" content of minidom_node:
        the first element of the pair is a concatenation of the text content
        the second element is a list of non-text nodes.

    The string concatenation strips leading and trailing whitespace from each
    bit of text found and joins the fragments (with no separator between them)."""
    tl = []
    ntl = []
    for c in minidom_node.childNodes:
        if c.nodeType == xml.dom.minidom.Node.TEXT_NODE:
            tl.append(c)
        else:
            ntl.append(c)
    try:
        tl = [i.data.strip() for i in tl]
        text_content = ''.join(tl)
    except:
        text_content = ''
    return (text_content, ntl)

def find_package_data(packages):
    """For a list of packages, find the package_data

    This function scans the subdirectories of a package and considers all
    non-submodule subdirectories as resources, including them in
    the package_data

    Returns a dictionary suitable for setup(package_data=<result>)"""
    package_data = {}
    for package in packages:
        package_data[package] = []
        for subdir in find_subdirectories(package):
            if '.'.join((package, subdir)) in packages:
                logging.debug('skipping submodule %s/%s' % (package, subdir))
                continue
            if skip_tests and subdir == 'tests':
                logging.debug('skipping tests %s/%s' % (package, subdir))
                continue
            package_data[package] += subdir_findall(package_to_path(package), subdir)
    return package_data

def parse_requirements(file_name):
    """from:
        http://cburgmer.posterous.com/pip-requirementstxt-and-setuppy"""
    requirements = []
    with open(file_name, 'r') as f:
        for line in f:
            if re.match('(\\s*#)|(\\s*$)', line):
                continue
            if re.match('\\s*-e\\s+', line):
                requirements.append(re.sub('\\s*-e\\s+.*#egg=(.*)$', '\\1', line).strip())
            elif re.match('\\s*-f\\s+', line):
                pass
            else:
                requirements.append(line.strip())
    return requirements

def parse_dependency_links(file_name):
    """from:
        http://cburgmer.posterous.com/pip-requirementstxt-and-setuppy"""
    dependency_links = []
    with open(file_name) as f:
        for line in f:
            if re.match('\\s*-[ef]\\s+', line):
                dependency_links.append(re.sub('\\s*-[ef]\\s+', '', line))
    return dependency_links

def get_notebook_name():
    """Return the full path of the jupyter notebook."""
    kernel_id = re.search('kernel-(.*).json', ipykernel.connect.get_connection_file()).group(1)
    servers = list_running_servers()
    for ss in servers:
        response = requests.get(urljoin(ss['url'], 'api/sessions'), params={'token': ss.get('token', '')})
        for nn in json.loads(response.text):
            if nn['kernel']['id'] == kernel_id:
                full_path = nn['notebook']['path']
                return os.path.basename(full_path)
    return f

def split_dae_alg(eqs: SYM, dx: SYM) -> Dict[str, SYM]:
    """Split equations into differential algebraic and algebraic only"""
    dae = []
    alg = []
    for eq in ca.vertsplit(eqs):
        if ca.depends_on(eq, dx):
            dae.append(eq)
        else:
            alg.append(eq)
    return {'dae': ca.vertcat(*dae), 'alg': ca.vertcat(*alg)}

def permute(x: SYM, perm: List[int]) -> SYM:
    """Perumute a vector"""
    x_s = []
    for i in perm:
        x_s.append(x[i])
    return ca.vertcat(*x_s)

def blt(f: List[SYM], x: List[SYM]) -> Dict[str, Any]:
    """Sort equations by dependence"""
    J = ca.jacobian(f, x)
    nblock, rowperm, colperm, rowblock, colblock, coarserow, coarsecol = J.sparsity().btf()
    return {'J': J, 'nblock': nblock, 'rowperm': rowperm, 'colperm': colperm, 'rowblock': rowblock, 'colblock': colblock, 'coarserow': coarserow, 'coarsecol': coarsecol}

def unauth(request):
    """logout and remove all session data"""
    if check_key(request):
        api = get_api(request)
        request.session.clear()
        logout(request)
    return HttpResponseRedirect(reverse('main'))

def check_key(request):
    """Check to see if we already have an access_key stored,
    if we do then we have already gone through
    OAuth. If not then we haven't and we probably need to."""
    try:
        access_key = request.session.get('oauth_token', None)
        if not access_key:
            return False
    except KeyError:
        return False
    return True

def from_config(config):
    """Generate a matrix from a configuration dictionary."""
    matrix = {}
    variables = config.keys()
    for entries in product(*config.values()):
        combination = dict(zip(variables, entries))
        include = True
        for value in combination.values():
            for reducer in value.reducers:
                if reducer.pattern == '-':
                    match = not combination[reducer.variable].value
                else:
                    match = fnmatch(combination[reducer.variable].value, reducer.pattern)
                if match if reducer.is_exclude else not match:
                    include = False
        if include:
            key = '-'.join((entry.alias for entry in entries if entry.alias))
            data = dict(zip(variables, (entry.value for entry in entries)))
            if key in matrix and data != matrix[key]:
                raise DuplicateEnvironment(key, data, matrix[key])
            matrix[key] = data
    return matrix

def from_file(filename, section='matrix'):
    """Generate a matrix from a .ini file. Configuration is expected to be in a ``[matrix]`` section."""
    config = parse_config(open(filename), section=section)
    return from_config(config)

def from_string(string, section='matrix'):
    """Generate a matrix from a .ini file. Configuration is expected to be in a ``[matrix]`` section."""
    config = parse_config(StringIO(string), section=section)
    return from_config(config)

def build_process_tree(ps_rows):
    """Build a tree structure from a list of PsRow objects.
    :param ps_rows: a list of PsRow objects
    :return: a PsTree object"""
    ps_tree = None
    for row in ps_rows:
        if row.ppid == 0:
            if ps_tree is not None:
                raise PsException('Too many process tree roots (ppid=0) found')
            ps_tree = PsTree(row)
    if ps_tree is None:
        raise PsException('No process tree root (ppid=0) found')
    _build_process_subtree(ps_rows, ps_tree, set([ps_tree.row.pid]))
    if ps_tree.count() < len(ps_rows):
        raise PsException('Unreachable processes detected')
    assert ps_tree.count() == len(ps_rows)
    return ps_tree

def extract_diacritic(*diacritics):
    """Given a collection of Unicode diacritics, return a function that takes a
    Unicode character and returns the member of the collection the character
    has (or None)."""
    def _(ch):
        decomposed_form = unicodedata.normalize('NFD', ch)
        for diacritic in diacritics:
            if diacritic in decomposed_form:
                return diacritic
    return _

def add_breathing(ch, breathing):
    """Add the given breathing to the given (possibly accented) character."""
    decomposed = unicodedata.normalize('NFD', ch)
    if len(decomposed) > 1 and decomposed[1] == LONG:
        return unicodedata.normalize('NFC', decomposed[0:2] + breathing + decomposed[2:])
    else:
        return unicodedata.normalize('NFC', decomposed[0] + breathing + decomposed[1:])

def remove_diacritic(*diacritics):
    """Given a collection of Unicode diacritics, return a function that takes a
    string and returns the string without those diacritics."""
    def _(text):
        return unicodedata.normalize('NFC', ''.join((ch for ch in unicodedata.normalize('NFD', text) if ch not in diacritics)))
    return _

def deep_merge(*dicts):
    """Recursively merge all input dicts into a single dict."""
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise Exception('Can only deep_merge dicts, got {}'.format(d))
        for k, v in d.items():
            if isinstance(v, dict):
                v = deep_merge(result.get(k, {}), v)
            result[k] = v
    return result

def verify_notification(data):
    """Function to verify notification came from a trusted source

    Returns True if verfied, False if not verified"""
    pemfile = grab_keyfile(data['SigningCertURL'])
    cert = crypto.load_certificate(crypto.FILETYPE_PEM, pemfile)
    signature = base64.decodestring(six.b(data['Signature']))
    if data['Type'] == 'Notification':
        hash_format = NOTIFICATION_HASH_FORMAT
    else:
        hash_format = SUBSCRIPTION_HASH_FORMAT
    try:
        crypto.verify(cert, signature, six.b(hash_format.format(**data)), 'sha1')
    except crypto.Error:
        return False
    return True

def approve_subscription(data):
    """Function to approve a SNS subscription with Amazon

    We don't do a ton of verification here, past making sure that the endpoint
    we're told to go to to verify the subscription is on the correct host"""
    url = data['SubscribeURL']
    domain = urlparse(url).netloc
    pattern = getattr(settings, 'BOUNCY_SUBSCRIBE_DOMAIN_REGEX', 'sns.[a-z0-9\\-]+.amazonaws.com$')
    if not re.search(pattern, domain):
        logger.error('Invalid Subscription Domain %s', url)
        return HttpResponseBadRequest('Improper Subscription Domain')
    try:
        result = urlopen(url).read()
        logger.info('Subscription Request Sent %s', url)
    except urllib.HTTPError as error:
        result = error.read()
        logger.warning('HTTP Error Creating Subscription %s', str(result))
    signals.subscription.send(sender='bouncy_approve_subscription', result=result, notification=data)
    return HttpResponse(six.u(result))

def clean_time(time_string):
    """Return a datetime from the Amazon-provided datetime string"""
    time = dateutil.parser.parse(time_string)
    if not settings.USE_TZ:
        time = time.astimezone(timezone.utc).replace(tzinfo=None)
    return time

def parse_selectors(model, fields=None, exclude=None, key_map=None, **options):
    """Validates fields are valid and maps pseudo-fields to actual fields
    for a given model class."""
    fields = fields or DEFAULT_SELECTORS
    exclude = exclude or ()
    key_map = key_map or {}
    validated = []
    for alias in fields:
        actual = key_map.get(alias, alias)
        cleaned = resolver.get_field(model, actual)
        if cleaned is None:
            raise AttributeError('The "{0}" attribute could not be found on the model "{1}"'.format(actual, model))
        if type(cleaned) is list:
            validated.extend(cleaned)
        elif alias != actual:
            validated.append(alias)
        else:
            validated.append(cleaned)
    return tuple([x for x in validated if x not in exclude])

def _enable_lock(func):
    """The decorator for ensuring thread-safe when current cache instance is concurrent status."""
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        self = args[0]
        if self.is_concurrent:
            only_read = kwargs.get('only_read')
            if only_read is None or only_read:
                with self._rwlock:
                    return func(*args, **kwargs)
            else:
                self._rwlock.acquire_writer()
                try:
                    return func(*args, **kwargs)
                finally:
                    self._rwlock.release()
        else:
            return func(*args, **kwargs)
    return wrapper

def _enable_cleanup(func):
    """Execute cleanup operation when the decorated function completed."""
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        self = args[0]
        result = func(*args, **kwargs)
        self.cleanup(self)
        return result
    return wrapper

def _enable_thread_pool(func):
    """Use thread pool for executing a task if self.enable_thread_pool is True.

    Return an instance of future when flag is_async is True otherwise will to
    block waiting for the result until timeout then returns the result."""
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        self = args[0]
        if self.enable_thread_pool and hasattr(self, 'thread_pool'):
            future = self.thread_pool.submit(func, *args, **kwargs)
            is_async = kwargs.get('is_async')
            if is_async is None or not is_async:
                timeout = kwargs.get('timeout')
                if timeout is None:
                    timeout = 2
                try:
                    result = future.result(timeout=timeout)
                except TimeoutError as e:
                    self.logger.exception(e)
                    result = None
                return result
            return future
        else:
            return func(*args, **kwargs)
    return wrapper

def _inject_func(func, conn):
    """(internal) injects a function object into a RPyC connection object."""
    name = func.__name__
    if not name in conn.namespace:
        if isbuiltin(func):
            inject_code = '%s = %s' % (name, name)
        elif isfunction(func):
            inject_code = getsource(func)
        conn.execute(inject_code)
    return conn.namespace[name]

def script(inbox, cfg):
    """Execute arbitrary scripts.

    Arguments:

      - cfg(``dict``) script configuartion dictionary"""
    script_name = cfg['id']
    script_id = str(abs(hash((cfg['id'],) + tuple(inbox[0].values()))))[0:8]
    args = {}
    args['params'] = dict(cfg['params'])
    args['in'] = {}
    for in_port in cfg['in']:
        for inin_ports in inbox:
            in_path = inin_ports.get(in_port, None)
            if in_path is not None:
                args['in'][in_port] = in_path
                break
    if len(args['in']) < len(cfg['in']):
        raise Exception('not all in_ports connected, got: %s' % (args['in'],))
    args['out'] = {}
    out = {}
    for i, (out_port, out_ext) in enumerate(cfg['out']):
        if cfg['in'] == tuple((out_port_ for out_port_, _ in cfg['out'])):
            pfx = args['in'][cfg['in'][i]].split('/')[-1].split('.')[0] + '_'
            base = cfg['id']
        else:
            pfx = args['in'][cfg['in'][0]].split('/')[-1].split('.')[0] + '_'
            base = cfg['id'] + '-' + out_port
        if out_ext:
            out_path = cfg['dir'] + '/' + pfx + base + '.' + out_ext
        else:
            out_path = cfg['dir'] + '/' + pfx + base
        args['out'][out_port] = out_path
        out[out_port] = out_path
    ret = _eval_script(cfg['evaluator'], cfg['preamble'], cfg['dir'], cfg['executable'], cfg['script'], args)
    if ret[0] != 0:
        raise Exception(ret[0], cfg['script'], ret[1], ret[2])
    return out

def get_function_signature(func):
    """Return the signature string of the specified function.

    >>> def foo(name): pass
    >>> get_function_signature(foo)
    'foo(name)'
    >>> something = 'Hello'
    >>> get_function_signature(something)
    Traceback (most recent call last):
        ...
    TypeError: The argument must be a function object: None type is <class 'str'>"""
    if func is None:
        return 'Function is None'
    try:
        func_name = func.__name__
    except AttributeError:
        func_name = 'None'
    if not inspect.isfunction(func):
        raise TypeError('The argument must be a function object: %s type is %s' % (func_name, type(func)))
    return func_name + str(inspect.signature(func))

def load_script(browser, url):
    """Ensure that JavaScript at a given URL is available to the browser."""
    if browser.current_url.startswith('file:'):
        url = 'https:' + url
    browser.execute_script('\n    var script_tag = document.createElement("script");\n    script_tag.setAttribute("type", "text/javascript");\n    script_tag.setAttribute("src", arguments[0]);\n    document.getElementsByTagName("head")[0].appendChild(script_tag);\n    ', url)
    sleep(1)

def find_elements_by_jquery(browser, selector):
    """Find HTML elements using jQuery-style selectors.

    Ensures that jQuery is available to the browser; if it gets a
    WebDriverException that looks like jQuery is not available, it attempts to
    include it and reexecute the script."""
    try:
        return browser.execute_script('return ($ || jQuery)(arguments[0]).get();', selector)
    except WebDriverException as e:
        if e.msg.startswith(u'$ is not defined'):
            load_script(browser, '//ajax.googleapis.com/ajax/libs/jquery/1.10.2/jquery.min.js')
            return browser.execute_script('return ($ || jQuery)(arguments[0]).get();', selector)
        else:
            raise

def element_id_by_label(browser, label):
    """Return the id of a label's for attribute"""
    label = XPathSelector(browser, unicode('//label[contains(., "%s")]' % label))
    if not label:
        return False
    return label.get_attribute('for')

def find_field(browser, field, value):
    """Locate an input field of a given value

    This first looks for the value as the id of the element, then
    the name of the element, then a label for the element."""
    return find_field_by_id(browser, field, value) + find_field_by_name(browser, field, value) + find_field_by_label(browser, field, value)

def find_any_field(browser, field_types, field_name):
    """Find a field of any of the specified types."""
    return reduce(operator.add, (find_field(browser, field_type, field_name) for field_type in field_types))

def find_field_by_label(browser, field, label):
    """Locate the control input that has a label pointing to it

    This will first locate the label element that has a label of the given
    name. It then pulls the id out of the 'for' attribute, and uses it to
    locate the element by its id."""
    return XPathSelector(browser, field_xpath(field, 'id', escape=False) % u'//label[contains(., "{0}")]/@for'.format(label))

def option_in_select(browser, select_name, option):
    """Returns the Element specified by @option or None

    Looks at the real <select> not the select2 widget, since that doesn't
    create the DOM until we click on it."""
    select = find_field(browser, 'select', select_name)
    assert select
    try:
        return select.find_element_by_xpath(unicode('.//option[normalize-space(text()) = "%s"]' % option))
    except NoSuchElementException:
        return None

def site_url(url):
    """Determine the server URL."""
    base_url = 'http://%s' % socket.gethostname()
    if server.port is not 80:
        base_url += ':%d' % server.port
    return urlparse.urljoin(base_url, url)

def get_all_keys(reactor, key_type, value_type, etcd_address):
    """Returns all keys from etcd.

    :param reactor: reference to Twisted' reactor.
    :param etcd_address: Address with port number where etcd is
        running.
    :return: An instance of txaioetcd.Range containing all keys and
        their values."""
    etcd = Client(reactor, etcd_address)
    result = (yield etcd.get(b'\x00', range_end=b'\x00'))
    res = {}
    for item in result.kvs:
        if key_type == u'utf8':
            key = item.key.decode('utf8')
        elif key_type == u'binary':
            key = binascii.b2a_base64(item.key).decode().strip()
        else:
            raise Exception('logic error')
        if value_type == u'json':
            value = json.loads(item.value.decode('utf8'))
        elif value_type == u'binary':
            value = binascii.b2a_base64(item.value).decode().strip()
        elif value_type == u'utf8':
            value = item.value.decode('utf8')
        else:
            raise Exception('logic error')
        res[key] = value
    returnValue(res)

def szipper(inbox, s=None):
    """Zips inputs from inbox with indicies in "s". By default zips the whole
    inbox (all indices).

    Arguments:

      - s(sequence) [default: ``None``]"""
    return zip(*[input_ for i, input_ in enumerate(inbox) if i in s])

def load_stream(handle, delimiter=None):
    """Creates a string generator from a stream (file handle) containing data
    delimited by the delimiter strings. This is a stand-alone function and
    should be used to feed external data into a pipeline.

    Arguments:

      - hande(``file``) A file handle open for reading.
      - delimiter(``str``) [default: ``None``] The default means that items will
        be separated by two new-line characters i.e.: ``"\\n\\n"``."""
    delimiter = (delimiter or '') + '\n'
    while True:
        item = []
        while True:
            line = handle.readline()
            if line == '':
                raise StopIteration
            elif line == delimiter:
                if item:
                    break
            elif line != '\n':
                item.append(line)
        yield ''.join(item)

def make_lines(handle, follow=False, wait=0.1):
    """Creates a line generator from a stream (file handle) containing data in
    lines.

    Arguments:

      - follow(``bool``) [default: ``False``] If ``True`` follows the file after
        it finishes like 'tail -f'.
      - wait(``float``) [default: ``0.1``] time to wait in seconds between file
        polls."""
    while True:
        line = handle.readline()
        if line:
            yield line
        elif follow:
            time.sleep(wait)
        else:
            raise StopIteration

def process_message(message, notification):
    """Function to process a JSON message delivered from Amazon"""
    if not set(VITAL_MESSAGE_FIELDS) <= set(message):
        logger.info('JSON Message Missing Vital Fields')
        return HttpResponse('Missing Vital Fields')
    if message['notificationType'] == 'Complaint':
        return process_complaint(message, notification)
    if message['notificationType'] == 'Bounce':
        return process_bounce(message, notification)
    if message['notificationType'] == 'Delivery':
        return process_delivery(message, notification)
    else:
        return HttpResponse('Unknown Notification Type')

def process_bounce(message, notification):
    """Function to process a bounce notification"""
    mail = message['mail']
    bounce = message['bounce']
    bounces = []
    for recipient in bounce['bouncedRecipients']:
        bounces += [Bounce.objects.create(sns_topic=notification['TopicArn'], sns_messageid=notification['MessageId'], mail_timestamp=clean_time(mail['timestamp']), mail_id=mail['messageId'], mail_from=mail['source'], address=recipient['emailAddress'], feedback_id=bounce['feedbackId'], feedback_timestamp=clean_time(bounce['timestamp']), hard=bool(bounce['bounceType'] == 'Permanent'), bounce_type=bounce['bounceType'], bounce_subtype=bounce['bounceSubType'], reporting_mta=bounce.get('reportingMTA'), action=recipient.get('action'), status=recipient.get('status'), diagnostic_code=recipient.get('diagnosticCode'))]
    for bounce in bounces:
        signals.feedback.send(sender=Bounce, instance=bounce, message=message, notification=notification)
    logger.info('Logged %s Bounce(s)', str(len(bounces)))
    return HttpResponse('Bounce Processed')

def process_complaint(message, notification):
    """Function to process a complaint notification"""
    mail = message['mail']
    complaint = message['complaint']
    if 'arrivalDate' in complaint:
        arrival_date = clean_time(complaint['arrivalDate'])
    else:
        arrival_date = None
    complaints = []
    for recipient in complaint['complainedRecipients']:
        complaints += [Complaint.objects.create(sns_topic=notification['TopicArn'], sns_messageid=notification['MessageId'], mail_timestamp=clean_time(mail['timestamp']), mail_id=mail['messageId'], mail_from=mail['source'], address=recipient['emailAddress'], feedback_id=complaint['feedbackId'], feedback_timestamp=clean_time(complaint['timestamp']), useragent=complaint.get('userAgent'), feedback_type=complaint.get('complaintFeedbackType'), arrival_date=arrival_date)]
    for complaint in complaints:
        signals.feedback.send(sender=Complaint, instance=complaint, message=message, notification=notification)
    logger.info('Logged %s Complaint(s)', str(len(complaints)))
    return HttpResponse('Complaint Processed')

def process_delivery(message, notification):
    """Function to process a delivery notification"""
    mail = message['mail']
    delivery = message['delivery']
    if 'timestamp' in delivery:
        delivered_datetime = clean_time(delivery['timestamp'])
    else:
        delivered_datetime = None
    deliveries = []
    for eachrecipient in delivery['recipients']:
        deliveries += [Delivery.objects.create(sns_topic=notification['TopicArn'], sns_messageid=notification['MessageId'], mail_timestamp=clean_time(mail['timestamp']), mail_id=mail['messageId'], mail_from=mail['source'], address=eachrecipient, delivered_time=delivered_datetime, processing_time=int(delivery['processingTimeMillis']), smtp_response=delivery['smtpResponse'])]
    for eachdelivery in deliveries:
        signals.feedback.send(sender=Delivery, instance=eachdelivery, message=message, notification=notification)
    logger.info('Logged %s Deliveries(s)', str(len(deliveries)))
    return HttpResponse('Delivery Processed')

