def filter_variant_sequences(variant_sequences, preferred_sequence_length, min_variant_sequence_coverage=MIN_VARIANT_SEQUENCE_COVERAGE):
    """Drop variant sequences which are shorter than request or don't have
    enough supporting reads."""
    variant_sequences = trim_variant_sequences(variant_sequences, min_variant_sequence_coverage)
    return filter_variant_sequences_by_length(variant_sequences=variant_sequences, preferred_sequence_length=preferred_sequence_length)

def variant_sequences_generator_to_dataframe(variant_sequences_generator):
    """Creates a dataframe from a generator which yields
    (Variant, [VariantSequence]) pairs.

    Returns pandas.DataFrame"""
    return dataframe_from_generator(VariantSequence, variant_sequences_generator, rename_dict={'alt': 'allele'}, extra_column_fns={'gene': lambda variant, _: ';'.join(variant.gene_names)})

def trim_N_nucleotides(prefix, suffix):
    """Drop all occurrences of 'N' from prefix and suffix nucleotide strings
    by trimming."""
    if 'N' in prefix:
        rightmost_index = prefix.rfind('N')
        logger.debug("Trimming %d nucleotides from read prefix '%s'", rightmost_index + 1, prefix)
        prefix = prefix[rightmost_index + 1:]
    if 'N' in suffix:
        leftmost_index = suffix.find('N')
        logger.debug("Trimming %d nucleotides from read suffix '%s'", len(suffix) - leftmost_index, suffix)
        suffix = suffix[:leftmost_index]
    return (prefix, suffix)

def convert_from_bytes_if_necessary(prefix, suffix):
    """Depending on how we extract data from pysam we may end up with either
    a string or a byte array of nucleotides. For consistency and simplicity,
    we want to only use strings in the rest of our code."""
    if isinstance(prefix, bytes):
        prefix = prefix.decode('ascii')
    if isinstance(suffix, bytes):
        suffix = suffix.decode('ascii')
    return (prefix, suffix)

def reads_supporting_variants(variants, samfile, **kwargs):
    """Given a SAM/BAM file and a collection of variants, generates a sequence
    of variants paired with reads which support each variant."""
    for variant, allele_reads in reads_overlapping_variants(variants=variants, samfile=samfile, **kwargs):
        yield (variant, filter_non_alt_reads_for_variant(variant, allele_reads))

def greedy_merge_helper(variant_sequences, min_overlap_size=MIN_VARIANT_SEQUENCE_ASSEMBLY_OVERLAP_SIZE):
    """Returns a list of merged VariantSequence objects, and True if any
    were successfully merged."""
    merged_variant_sequences = {}
    merged_any = False
    unmerged_variant_sequences = set(variant_sequences)
    for i in range(len(variant_sequences)):
        sequence1 = variant_sequences[i]
        for j in range(i + 1, len(variant_sequences)):
            sequence2 = variant_sequences[j]
            combined = sequence1.combine(sequence2)
            if combined is None:
                continue
            if combined.sequence in merged_variant_sequences:
                existing = merged_variant_sequences[combined.sequence]
                combined = combined.add_reads(existing.reads)
            merged_variant_sequences[combined.sequence] = combined
            unmerged_variant_sequences.discard(sequence1)
            unmerged_variant_sequences.discard(sequence2)
            merged_any = True
    result = list(merged_variant_sequences.values()) + list(unmerged_variant_sequences)
    return (result, merged_any)

def collapse_substrings(variant_sequences):
    """Combine shorter sequences which are fully contained in longer sequences.

    Parameters
    ----------
    variant_sequences : list
       List of VariantSequence objects

    Returns a (potentially shorter) list without any contained subsequences."""
    if len(variant_sequences) <= 1:
        return variant_sequences
    extra_reads_from_substrings = defaultdict(set)
    result_list = []
    for short_variant_sequence in sorted(variant_sequences, key=lambda seq: -len(seq)):
        found_superstring = False
        for long_variant_sequence in result_list:
            found_superstring = long_variant_sequence.contains(short_variant_sequence)
            if found_superstring:
                extra_reads_from_substrings[long_variant_sequence].update(short_variant_sequence.reads)
        if not found_superstring:
            result_list.append(short_variant_sequence)
    return [variant_sequence.add_reads(extra_reads_from_substrings[variant_sequence]) for variant_sequence in result_list]

def allele_counts_dataframe(variant_and_allele_reads_generator):
