def check_extension(conn, extension: str) -> bool:
    """Check to see if an extension is installed."""
    query = 'SELECT installed_version FROM pg_available_extensions WHERE name=%s;'
    with conn.cursor() as cursor:
        cursor.execute(query, (extension,))
        result = cursor.fetchone()
    if result is None:
        raise psycopg2.ProgrammingError('Extension is not available for installation.', extension)
    else:
        extension_version = result[0]
        return bool(extension_version)

def _swaplch(LCH):
    """Reverse the order of an LCH numpy dstack or tuple for analysis."""
    try:
        L, C, H = np.dsplit(LCH, 3)
        return np.dstack((H, C, L))
    except:
        L, C, H = LCH
        return (H, C, L)

def iterparse(source, tag, clear=False, events=None):
    """iterparse variant that supports 'tag' parameter (like lxml),
    yields elements and clears nodes after parsing."""
    for event, elem in ElementTree.iterparse(source, events=events):
        if elem.tag == tag:
            yield elem
        if clear:
            elem.clear()

def load_chunk(filename, bounds, encoding='utf8', slow=False):
    """Load a chunk from file using Bounds info.
    Pass 'slow=True' for an alternative loading method based on line numbers."""
    if slow:
        return _load_chunk_slow(filename, bounds, encoding)
    with open(filename, 'rb') as f:
        f.seek(bounds.byte_start)
        size = bounds.byte_end - bounds.byte_start
        return f.read(size).decode(encoding)

def edge_average(a):
    """Return the mean value around the edge of an array."""
    if len(np.ravel(a)) < 2:
        return float(a[0])
    else:
        top_edge = a[0]
        bottom_edge = a[-1]
        left_edge = a[1:-1, 0]
        right_edge = a[1:-1, -1]
        edge_sum = np.sum(top_edge) + np.sum(bottom_edge) + np.sum(left_edge) + np.sum(right_edge)
        num_values = len(top_edge) + len(bottom_edge) + len(left_edge) + len(right_edge)
        return float(edge_sum) / num_values

def variant_matches_reference_sequence(variant, ref_seq_on_transcript, strand):
    """Make sure that reference nucleotides we expect to see on the reference
    transcript from a variant are the same ones we encounter."""
    if strand == '-':
        ref_seq_on_transcript = reverse_complement_dna(ref_seq_on_transcript)
    return ref_seq_on_transcript == variant.ref

def ellipsize(s, max_length=60):
    """>>> print(ellipsize(u'lorem ipsum dolor sit amet', 40))
    lorem ipsum dolor sit amet
    >>> print(ellipsize(u'lorem ipsum dolor sit amet', 20))
    lorem ipsum dolor..."""
    if len(s) > max_length:
        ellipsis = '...'
        return s[:max_length - len(ellipsis)] + ellipsis
    else:
        return s

def wrap(lower, upper, x):
    """Circularly alias the numeric value x into the range [lower,upper).

    Valid for cyclic quantities like orientations or hues."""
    range_ = upper - lower
    return lower + np.fmod(x - lower + 2 * range_ * (1 - np.floor(x / (2 * range_))), range_)

def discover(timeout=DISCOVERY_TIMEOUT):
    """Discover devices on the local network.

    :param timeout: Optional timeout in seconds.
    :returns: Set of discovered host addresses."""
    hosts = {}
    payload = MAGIC + DISCOVERY
    for _ in range(RETRIES):
        _SOCKET.sendto(bytearray(payload), ('255.255.255.255', PORT))
        start = time.time()
        while time.time() < start + timeout:
            for host, data in _BUFFER.copy().items():
                if not _is_discovery_response(data):
                    continue
                if host not in hosts:
                    _LOGGER.debug('Discovered device at %s', host)
                    entry = {}
                    entry['mac'] = data[7:13]
                    entry['imac'] = data[19:25]
                    entry['next'] = 0
                    entry['st'] = int(data[-1])
                    entry['time'] = _device_time(data[37:41])
                    entry['serverTime'] = int(time.time())
                    hosts[host] = entry
    return hosts

def gaussian(x, y, xsigma, ysigma):
    """Two-dimensional oriented Gaussian pattern (i.e., 2D version of a
    bell curve, like a normal distribution but not necessarily summing
    to 1.0)."""
    if xsigma == 0.0 or ysigma == 0.0:
        return x * 0.0
    with float_error_ignore():
        x_w = np.divide(x, xsigma)
        y_h = np.divide(y, ysigma)
        return np.exp(-0.5 * x_w * x_w + -0.5 * y_h * y_h)

def exponential(x, y, xscale, yscale):
    """Two-dimensional oriented exponential decay pattern."""
    if xscale == 0.0 or yscale == 0.0:
        return x * 0.0
    with float_error_ignore():
        x_w = np.divide(x, xscale)
        y_h = np.divide(y, yscale)
        return np.exp(-np.sqrt(x_w * x_w + y_h * y_h))

def gabor(x, y, xsigma, ysigma, frequency, phase):
    """Gabor pattern (sine grating multiplied by a circular Gaussian)."""
    if xsigma == 0.0 or ysigma == 0.0:
        return x * 0.0
    with float_error_ignore():
        x_w = np.divide(x, xsigma)
        y_h = np.divide(y, ysigma)
        p = np.exp(-0.5 * x_w * x_w + -0.5 * y_h * y_h)
    return p * 0.5 * np.cos(2 * pi * frequency * y + phase)

def line(y, thickness, gaussian_width):
    """Infinite-length line with a solid central region, then Gaussian fall-off at the edges."""
    distance_from_line = abs(y)
    gaussian_y_coord = distance_from_line - thickness / 2.0
    sigmasq = gaussian_width * gaussian_width
    if sigmasq == 0.0:
        falloff = y * 0.0
    else:
        with float_error_ignore():
            falloff = np.exp(np.divide(-gaussian_y_coord * gaussian_y_coord, 2 * sigmasq))
    return np.where(gaussian_y_coord <= 0, 1.0, falloff)

def disk(x, y, height, gaussian_width):
    """Circular disk with Gaussian fall-off after the solid central region."""
    disk_radius = height / 2.0
    distance_from_origin = np.sqrt(x ** 2 + y ** 2)
    distance_outside_disk = distance_from_origin - disk_radius
    sigmasq = gaussian_width * gaussian_width
    if sigmasq == 0.0:
        falloff = x * 0.0
    else:
        with float_error_ignore():
            falloff = np.exp(np.divide(-distance_outside_disk * distance_outside_disk, 2 * sigmasq))
    return np.where(distance_outside_disk <= 0, 1.0, falloff)

def arc_by_center(x, y, arc_box, constant_length, thickness, gaussian_width):
    """Arc with Gaussian fall-off after the solid ring-shaped region and specified
    by point of tangency (x and y) and arc width and height.

    This function calculates the start and end radian from the given width and
    height, and then calls arc_by_radian function to draw the curve."""
    arc_w = arc_box[0]
    arc_h = abs(arc_box[1])
    if arc_w == 0.0:
        radius = 0.0
        angles = (0.0, 0.0)
    elif arc_h == 0.0:
        return smooth_rectangle(x, y, arc_w, thickness, 0.0, gaussian_width)
    else:
        if constant_length:
            curvature = arc_h / arc_w
            radius = arc_w / (2 * pi * curvature)
            angle = curvature * (2 * pi) / 2.0
        else:
            radius = arc_h / 2.0 + arc_w ** 2.0 / (8 * arc_h)
            angle = np.arcsin(arc_w / 2.0 / radius)
        if arc_box[1] < 0:
            y = y + radius
            angles = (3.0 / 2.0 * pi - angle, 3.0 / 2.0 * pi + angle)
        else:
            y = y - radius
            angles = (pi / 2.0 - angle, pi / 2.0 + angle)
    return arc_by_radian(x, y, radius * 2.0, angles, thickness, gaussian_width)

def skipPGVersionBefore(*ver):
    """Skip PG versions below specific version i.e. (9, 5)."""
    ver = ver + (0,) * (3 - len(ver))
    def skip_before_postgres_(func):
        @wraps(func)
        def skip_before_postgres__(obj, *args, **kwargs):
            if hasattr(obj.conn, 'server_version'):
                server_version = obj.conn.server_version
            else:
                server_version = obj.conn.connection.connection.server_version
            if server_version < int('%d%02d%02d' % ver):
                return obj.skipTest('Skipped because PostgreSQL {}'.format(server_version))
            else:
                return func(obj, *args, **kwargs)
        return skip_before_postgres__
    return skip_before_postgres_

def guess_external_url(local_host, port):
    """Return a URL that is most likely to route to `local_host` from outside.

    The point is that we may be running on a remote host from the user's
    point of view, so they can't access `local_host` from a Web browser just
    by typing ``http://localhost:12345/``."""
    if local_host in ['0.0.0.0', '::']:
        local_host = socket.getfqdn()
        match = IPV4_REVERSE_DNS.match(local_host)
        if match:
            local_host = '.'.join(reversed(match.groups()))
        else:
            match = IPV6_REVERSE_DNS.match(local_host)
            if match:
                address_as_int = int(''.join(reversed(match.groups())), 16)
                local_host = str(IPv6Address(address_as_int))
    if ':' in local_host:
        local_host = '[%s]' % local_host.rsplit('%', 1)[0]
    return 'http://%s:%d/' % (local_host, port)

def remote_exception(exc, tb):
    """Metaclass that wraps exception type in RemoteException"""
    if type(exc) in exceptions:
        typ = exceptions[type(exc)]
        return typ(exc, tb)
    else:
        try:
            typ = type(exc.__class__.__name__, (RemoteException, type(exc)), {'exception_type': type(exc)})
            exceptions[type(exc)] = typ
            return typ(exc, tb)
        except TypeError:
            return exc

