def iter_(obj):
    """A custom replacement for iter(), dispatching a few custom picklable
    iterators for known types."""
    if six.PY2:
        file_types = (file,)
    if six.PY3:
        file_types = (io.IOBase,)
        dict_items = {}.items().__class__
        dict_values = {}.values().__class__
        dict_keys = {}.keys().__class__
        dict_view = (dict_items, dict_values, dict_keys)
    if isinstance(obj, dict):
        return ordered_sequence_iterator(list(obj.keys()))
    if isinstance(obj, file_types):
        return file_iterator(obj)
    if six.PY2:
        if isinstance(obj, (list, tuple)):
            return ordered_sequence_iterator(obj)
        if isinstance(obj, xrange):
            return range_iterator(obj)
        if NUMPY_AVAILABLE and isinstance(obj, numpy.ndarray):
            return ordered_sequence_iterator(obj)
    if six.PY3 and isinstance(obj, dict_view):
        return ordered_sequence_iterator(list(obj))
    return iter(obj)

def get_single_allele_from_reads(allele_reads):
    """Given a sequence of AlleleRead objects, which are expected to all have
    the same allele, return that allele."""
    allele_reads = list(allele_reads)
    if len(allele_reads) == 0:
        raise ValueError('Expected non-empty list of AlleleRead objects')
    seq = allele_reads[0].allele
    if any((read.allele != seq for read in allele_reads)):
        raise ValueError("Expected all AlleleRead objects to have same allele '%s', got %s" % (seq, allele_reads))
    return seq

def count_unique_sequences(allele_reads, max_prefix_size=None, max_suffix_size=None):
    """Given a list of AlleleRead objects, extracts all unique
    (prefix, allele, suffix) sequences and associate each with the number
    of reads that contain that sequence."""
    groups = group_unique_sequences(allele_reads, max_prefix_size=max_prefix_size, max_suffix_size=max_suffix_size)
    return {seq_tuple: len(read_names) for seq_tuple, read_names in groups.items()}

def execute_transactions(conn, statements: Iterable):
    """Execute several statements each as a single DB transaction."""
    with conn.cursor() as cursor:
        for statement in statements:
            try:
                cursor.execute(statement)
                conn.commit()
            except psycopg2.ProgrammingError:
                conn.rollback()

def execute_closing_transaction(statements: Iterable):
    """Open a connection, commit a transaction, and close it."""
    with closing(connect()) as conn:
        with conn.cursor() as cursor:
            for statement in statements:
                cursor.execute(statement)

