    number of hours."""
    num_seconds = int(num_hours * 60 * 60)
    def decorator(func):
        @wraps(func)
        def inner(request, *args, **kwargs):
            response = func(request, *args, **kwargs)
            patch_response_headers(response, num_seconds)
            return response
        return inner
    return decorator

def start_recv(sockfile=None):
    """Open a server on Unix Domain Socket"""
    if sockfile is not None:
        SOCKFILE = sockfile
    else:
        SOCKFILE = '/tmp/snort_alert'
    if os.path.exists(SOCKFILE):
        os.unlink(SOCKFILE)
    unsock = socket.socket(socket.AF_UNIX, socket.SOCK_DGRAM)
    unsock.bind(SOCKFILE)
    logging.warning('Unix socket start listening...')
    while True:
        data = unsock.recv(BUFSIZE)
        parsed_msg = alert.AlertPkt.parser(data)
        if parsed_msg:
            yield parsed_msg

def dump(obj, fp=None, indent=None, sort_keys=False, **kw):
    """Dump object to a file like object or string.

    :param obj:
    :param fp: Open file like object
    :param int indent: Indent size, default 2
    :param bool sort_keys: Optionally sort dictionary keys.
    :return: Yaml serialized data."""
    if fp:
        iterable = YAMLEncoder(indent=indent, sort_keys=sort_keys, **kw).iterencode(obj)
        for chunk in iterable:
            fp.write(chunk)
    else:
        return dumps(obj, indent=indent, sort_keys=sort_keys, **kw)

def dumps(obj, indent=None, default=None, sort_keys=False, **kw):
    """Dump string."""
    return YAMLEncoder(indent=indent, default=default, sort_keys=sort_keys, **kw).encode(obj)

