def add_settings(mod, allow_extras=True, settings=django_settings):
    """Adds all settings that are part of ``mod`` to the global settings object.

    Special cases ``EXTRA_APPS`` to append the specified applications to the
    list of ``INSTALLED_APPS``."""
    extras = {}
    for setting in dir(mod):
        if setting == setting.upper():
            setting_value = getattr(mod, setting)
            if setting in TUPLE_SETTINGS and type(setting_value) == str:
                setting_value = (setting_value,)
            if setting.startswith('EXTRA_'):
                base_setting = setting.split('EXTRA_', 1)[-1]
                if isinstance(getattr(settings, base_setting), (list, tuple)):
                    extras[base_setting] = setting_value
                    continue
            setattr(settings, setting, setting_value)
    for key, value in extras.items():
        curval = getattr(settings, key)
        setattr(settings, key, curval + type(curval)(value))

def add_form_widget_attr(field, attr_name, attr_value, replace=0):
    """Adds widget attributes to a bound form field.

    This is helpful if you would like to add a certain class to all your forms
    (i.e. `form-control` to all form fields when you are using Bootstrap)::

        {% load libs_tags %}
        {% for field in form.fields %}
            {% add_form_widget_attr field 'class' 'form-control' as field_ %}
            {{ field_ }}
        {% endfor %}

    The tag will check if the attr already exists and only append your value.
    If you would like to replace existing attrs, set `replace=1`::

        {% add_form_widget_attr field 'class' 'form-control' replace=1 as
          field_ %}"""
    if not replace:
        attr = field.field.widget.attrs.get(attr_name, '')
        attr += force_text(attr_value)
        field.field.widget.attrs[attr_name] = attr
        return field
    else:
        field.field.widget.attrs[attr_name] = attr_value
        return field

def block_anyfilter(parser, token):
    """Turn any template filter into a blocktag.

    Usage::

    {% load libs_tags %}
    {% block_anyfilter django.template.defaultfilters.truncatewords_html 15 %}
        // Something complex that generates html output
    {% endblockanyfilter %}"""
    bits = token.contents.split()
    nodelist = parser.parse(('endblockanyfilter',))
    parser.delete_first_token()
    return BlockAnyFilterNode(nodelist, bits[1], *bits[2:])

def calculate_dimensions(image, long_side, short_side):
    """Returns the thumbnail dimensions depending on the images format."""
    if image.width >= image.height:
        return '{0}x{1}'.format(long_side, short_side)
    return '{0}x{1}'.format(short_side, long_side)

def call(obj, method, *args, **kwargs):
    """Allows to call any method of any object with parameters.

    Because come on! It's bloody stupid that Django's templating engine doesn't
    allow that.

    Usage::

        {% call myobj 'mymethod' myvar foobar=myvar2 as result %}
        {% call myobj 'mydict' 'mykey' as result %}
        {% call myobj 'myattribute' as result %}

    :param obj: The object which has the method that you would like to call
    :param method: A string representing the attribute on the object that
      should be called."""
    function_or_dict_or_member = getattr(obj, method)
    if callable(function_or_dict_or_member):
        return function_or_dict_or_member(*args, **kwargs)
    if not len(args):
        return function_or_dict_or_member
    return function_or_dict_or_member[args[0]]

def get_content_type(obj, field_name=False):
    """Returns the content type of an object.

    :param obj: A model instance.
    :param field_name: Field of the object to return."""
    content_type = ContentType.objects.get_for_model(obj)
    if field_name:
        return getattr(content_type, field_name, '')
    return content_type

def get_verbose(obj, field_name=''):
    """Returns the verbose name of an object's field.

    :param obj: A model instance.
    :param field_name: The requested field value in string format."""
    if hasattr(obj, '_meta') and hasattr(obj._meta, 'get_field_by_name'):
        try:
            return obj._meta.get_field(field_name).verbose_name
        except FieldDoesNotExist:
            pass
    return ''

def get_query_params(request, *args):
    """Allows to change one of the URL get parameter while keeping all the others.

    Usage::

      {% load libs_tags %}
      {% get_query_params request "page" page_obj.next_page_number as query %}
      <a href="?{{ query }}">Next</a>

    You can also pass in several pairs of keys and values::

      {% get_query_params request "page" 1 "foobar" 2 as query %}

    You often need this when you have a paginated set of objects with filters.

    Your url would look something like ``/?region=1&gender=m``. Your paginator
    needs to create links with ``&page=2`` in them but you must keep the
    filter values when switching pages.

    :param request: The request instance.
    :param *args: Make sure to always pass in paris of args. One is the key,
      one is the value. If you set the value of a key to "!remove" that
      parameter will not be included in the returned query."""
    query = request.GET.copy()
    index = 1
    key = ''
    for arg in args:
        if index % 2 != 0:
            key = arg
        elif arg == '!remove':
            try:
                query.pop(key)
            except KeyError:
                pass
        else:
            query[key] = arg
        index += 1
    return query.urlencode()

def navactive(request, url, exact=0, use_resolver=1):
    """Returns ``active`` if the given URL is in the url path, otherwise ''.

    Usage::

        {% load libs_tags %}
        ...
        <li class="{% navactive request "/news/" exact=1 %}">

    :param request: A request instance.
    :param url: A string representing a part of the URL that needs to exist
      in order for this method to return ``True``.
    :param exact: If ``1`` then the parameter ``url`` must be equal to
      ``request.path``, otherwise the parameter ``url`` can just be a part of
      ``request.path``.
    :use_resolver: If ``0`` we will not try to compare ``url`` with existing
      view names but we will only compare it with ``request.path``."""
    if use_resolver:
        try:
            if url == resolve(request.path).url_name:
                return 'active'
            elif url == request.path:
                match = request.path
            else:
                return ''
        except Resolver404:
            match = request.path
    else:
        match = request.path
    if exact and url == match:
        return 'active'
    elif not exact and url in request.path:
        return 'active'
    return ''

def verbatim(parser, token):
    """Tag to render x-tmpl templates with Django template code."""
    text = []
    while 1:
        token = parser.tokens.pop(0)
        if token.contents == 'endverbatim':
            break
        if token.token_type == TOKEN_VAR:
            text.append('{{ ')
        elif token.token_type == TOKEN_BLOCK:
            text.append('{%')
        text.append(token.contents)
        if token.token_type == TOKEN_VAR:
            text.append(' }}')
        elif token.token_type == TOKEN_BLOCK:
            if not text[-1].startswith('='):
                text[-1:-1] = [' ']
            text.append(' %}')
    return VerbatimNode(''.join(text))

def append_s(value):
    """Adds the possessive s after a string.

    value = 'Hans' becomes Hans'
    and value = 'Susi' becomes Susi's"""
    if value.endswith('s'):
        return u"{0}'".format(value)
    else:
        return u"{0}'s".format(value)

def parse_args(args):
    """This parses the arguments and returns a tuple containing:

    (args, command, command_args)

    For example, "--config=bar start --with=baz" would return:

    (['--config=bar'], 'start', ['--with=baz'])"""
    index = None
    for arg_i, arg in enumerate(args):
        if not arg.startswith('-'):
            index = arg_i
            break
    if index is None:
        return (args, None, [])
    return (args[:index], args[index], args[index + 1:])

def parse(data):
    """Parses a raw datagram and return the right type of message"""
    data = data.decode('ascii')
    if len(data) == 2 and data == 'A5':
        return AckMessage()
    raw = [data[i:i + 2] for i in range(len(data)) if i % 2 == 0]
    if len(raw) != 7:
        return UnknownMessage(raw)
    if raw[1] == 'B8':
        return StateMessage(raw)
    elif raw[3] == '12':
        return CommandMessage(raw)
    elif raw[3] == '14':
        return ScenarioTriggeredMessage(raw)
    elif raw[3] == '15':
        return RequestStatusMessage(raw)
    else:
        return UnknownMessage(raw)

def checksum_bytes(data):
    """Returns a XOR of all the bytes specified inside of the given list"""
    int_values = [int(x, 16) for x in data]
    int_xor = reduce(lambda x, y: x ^ y, int_values)
    hex_xor = '{:X}'.format(int_xor)
    if len(hex_xor) % 2 != 0:
        hex_xor = '0' + hex_xor
    return str.encode(hex_xor)

def compose_telegram(body):
    """Compose a SCS message

    body: list containing the body of the message.
    returns: full telegram expressed (bytes instance)"""
    msg = [b'A8'] + body + [checksum_bytes(body)] + [b'A3']
    return str.encode(''.join([x.decode() for x in msg]))

def url_is_project(url, default='not_a_func'):
    """Check if URL is part of the current project's URLs.

    Args:
        url (str): URL to check.
        default (callable): used to filter out some URLs attached to function.

    Returns:"""
    try:
        u = resolve(url)
        if u and u.func != default:
            return True
    except Resolver404:
        static_url = settings.STATIC_URL
        static_url_wd = static_url.lstrip('/')
        if url.startswith(static_url):
            url = url[len(static_url):]
        elif url.startswith(static_url_wd):
            url = url[len(static_url_wd):]
        else:
            return False
        if finders.find(url):
            return True
    return False

def url_is(white_list):
    """Function generator.

    Args:
        white_list (dict): dict with PREFIXES and CONSTANTS keys (list values).

    Returns:
        func: a function to check if a URL is..."""
    def func(url):
        prefixes = white_list.get('PREFIXES', ())
        for prefix in prefixes:
            if url.startswith(prefix):
                return True
        constants = white_list.get('CONSTANTS', ())
        for exact_url in constants:
            if url == exact_url:
                return True
        return False
    return func

def get_experiment_kind(root):
    """Read common properties from root of ReSpecTh XML file.

    Args:
        root (`~xml.etree.ElementTree.Element`): Root of ReSpecTh XML file

    Returns:
        properties (`dict`): Dictionary with experiment type and apparatus information."""
    properties = {}
    if root.find('experimentType').text == 'Ignition delay measurement':
        properties['experiment-type'] = 'ignition delay'
    else:
        raise NotImplementedError(root.find('experimentType').text + ' not (yet) supported')
    properties['apparatus'] = {'kind': '', 'institution': '', 'facility': ''}
    kind = getattr(root.find('apparatus/kind'), 'text', False)
    if not kind:
        raise MissingElementError('apparatus/kind')
    elif kind in ['shock tube', 'rapid compression machine']:
        properties['apparatus']['kind'] = kind
    else:
        raise NotImplementedError(kind + ' experiment not (yet) supported')
    return properties

def lockfile(lockfile_name, lock_wait_timeout=-1):
    """Only runs the method if the lockfile is not acquired.

    You should create a setting ``LOCKFILE_PATH`` which points to
    ``/home/username/tmp/``.

    In your management command, use it like so::

        LOCKFILE = os.path.join(
            settings.LOCKFILE_FOLDER, 'command_name')

        class Command(NoArgsCommand):
            @lockfile(LOCKFILE)
            def handle_noargs(self, **options):
                # your command here

    :lockfile_name: A unique name for a lockfile that belongs to the wrapped
      method.
    :lock_wait_timeout: Seconds to wait if lockfile is acquired. If ``-1`` we
      will not wait and just quit."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            lock = FileLock(lockfile_name)
            try:
                lock.acquire(lock_wait_timeout)
            except AlreadyLocked:
                return
            except LockTimeout:
                return
            try:
                result = func(*args, **kwargs)
            finally:
                lock.release()
            return result
        return wrapper
    return decorator

def get_username(identifier):
    """Checks if a string is a email adress or not."""
    pattern = re.compile('.+@\\w+\\..+')
    if pattern.match(identifier):
        try:
            user = User.objects.get(email=identifier)
        except:
            raise Http404
        else:
            return user.username
    else:
        return identifier

def iter_format_modules(lang):
    """Does the heavy lifting of finding format modules."""
    if check_for_language(lang):
        format_locations = []
        for path in CUSTOM_FORMAT_MODULE_PATHS:
            format_locations.append(path + '.%s')
        format_locations.append('django.conf.locale.%s')
        locale = to_locale(lang)
        locales = [locale]
        if '_' in locale:
            locales.append(locale.split('_')[0])
        for location in format_locations:
            for loc in locales:
                try:
                    yield import_module('.formats', location % loc)
                except ImportError:
                    pass

def get_format_modules(lang=None, reverse=False):
    """Returns a list of the format modules found"""
    if lang is None:
        lang = get_language()
    modules = _format_modules_cache.setdefault(lang, list(iter_format_modules(lang)))
    if reverse:
        return list(reversed(modules))
    return modules

def get_format(format_type, lang=None, use_l10n=None):
    """For a specific format type, returns the format for the current
    language (locale), defaults to the format in the settings.
    format_type is the name of the format, e.g. 'DATE_FORMAT'

    If use_l10n is provided and is not None, that will force the value to
    be localized (or not), overriding the value of settings.USE_L10N."""
    format_type = str_encode(format_type)
    if use_l10n or (use_l10n is None and settings.USE_L10N):
        if lang is None:
            lang = get_language()
        cache_key = (format_type, lang)
        try:
            cached = _format_cache[cache_key]
            if cached is not None:
                return cached
            else:
                return getattr(settings, format_type)
        except KeyError:
            for module in get_format_modules(lang):
                try:
                    val = getattr(module, format_type)
                    for iso_input in ISO_INPUT_FORMATS.get(format_type, ()):
                        if iso_input not in val:
                            if isinstance(val, tuple):
                                val = list(val)
                            val.append(iso_input)
                    _format_cache[cache_key] = val
                    return val
                except AttributeError:
                    pass
            _format_cache[cache_key] = None
    return getattr(settings, format_type)

def valid_token(token):
    """Asserts a provided string is a valid duration token representation

    :param  token: duration representation token
    :type   token: string"""
    is_scale = False
    try:
        Scale(token)
        is_scale = True
    except ScaleFormatError:
        pass
    if any([token.isdigit(), token in SEPARATOR_TOKENS, is_scale]):
        return True
    return False

def extract_tokens(representation, separators=SEPARATOR_CHARACTERS):
    """Extracts durations tokens from a duration representation.

    Parses the string representation incrementaly and raises
    on first error met.

    :param  representation: duration representation
    :type   representation: string"""
    buff = ''
    elements = []
    last_index = 0
    last_token = None
    for index, c in enumerate(representation):
        if c in separators:
            if buff:
                if not valid_token(buff):
                    raise InvalidTokenError('Duration representation {0} contains an invalid token: {1}'.format(representation, buff))
                if not buff.strip() in SEPARATOR_TOKENS:
                    elements.append(buff)
            buff = ''
            last_token = None
        else:
            token = compute_char_token(c)
            if token is not None and last_token is not None and (token != last_token):
                elements.append(buff)
                buff = c
            else:
                buff += c
            last_token = token
    elements.append(buff)
    return list(zip(elements[::2], elements[1::2]))

def create_random_string(length=7, chars='ABCDEFGHJKMNPQRSTUVWXYZ23456789', repetitions=False):
    """Returns a random string, based on the provided arguments.

    It returns capital letters and numbers by default.
    Ambiguous characters are left out, repetitions will be avoided."""
    if repetitions:
        return ''.join((random.choice(chars) for _ in range(length)))
    return ''.join(random.sample(chars, length))

def load_member(fqn):
    """Loads and returns a class for a given fully qualified name."""
    modulename, member_name = split_fqn(fqn)
    module = __import__(modulename, globals(), locals(), member_name)
    return getattr(module, member_name)

def split_fqn(fqn):
    """Returns the left and right part of the import.

    ``fqn`` can be either a string of the form ``appname.modulename.ClassName``
    or a function that returns such a string."""
    if hasattr(fqn, '__call__'):
        fqn_string = fqn()
    else:
        fqn_string = fqn
    return fqn_string.rsplit('.', 1)

def read_csv(filename, keys=None, convert_types=False, **kwargs):
    """Read a CSV in canonical form: ::

        <agent_id, t_step, key, value, value_type>"""
    df = pd.read_csv(filename)
    if convert_types:
        df = convert_types_slow(df)
    if keys:
        df = df[df['key'].isin(keys)]
    df = process_one(df)
    return df

def split_df(df):
    """Split a dataframe in two dataframes: one with the history of agents,
    and one with the environment history"""
    envmask = df['agent_id'] == 'env'
    n_env = envmask.sum()
    if n_env == len(df):
        return (df, None)
    elif n_env == 0:
        return (None, df)
    agents, env = [x for _, x in df.groupby(envmask)]
    return (env, agents)

def process(df, **kwargs):
    """Process a dataframe in canonical form ``(t_step, agent_id, key, value, value_type)`` into
    two dataframes with a column per key: one with the history of the agents, and one for the
    history of the environment."""
    env, agents = split_df(df)
    return (process_one(env, **kwargs), process_one(agents, **kwargs))

def process_one(df, *keys, columns=['key', 'agent_id'], values='value', fill=True, index=['t_step'], aggfunc='first', **kwargs):
    """Process a dataframe in canonical form ``(t_step, agent_id, key, value, value_type)`` into
    a dataframe with a column per key"""
    if df is None:
        return df
    if keys:
        df = df[df['key'].isin(keys)]
    df = df.pivot_table(values=values, index=index, columns=columns, aggfunc=aggfunc, **kwargs)
    if fill:
        df = fillna(df)
    return df

def name(value, known_modules=[]):
    """Return a name that can be imported, to serialize/deserialize an object"""
    if value is None:
        return 'None'
    if not isinstance(value, type):
        value = type(value)
    tname = value.__name__
    if hasattr(builtins, tname):
        return tname
    modname = value.__module__
    if modname == '__main__':
        return tname
    if known_modules and modname in known_modules:
        return tname
    for kmod in known_modules:
        if not kmod:
            continue
        module = importlib.import_module(kmod)
        if hasattr(module, tname):
            return tname
    return '{}.{}'.format(modname, tname)

def serialize(v, known_modules=[]):
    """Get a text representation of an object."""
    tname = name(v, known_modules=known_modules)
    func = serializer(tname)
    return (func(v), tname)

def deserialize(type_, value=None, **kwargs):
    """Get an object from a text representation"""
    if not isinstance(type_, str):
        return type_
    des = deserializer(type_, **kwargs)
    if value is None:
        return des
    return des(value)

def calculate_distribution(network_agents=None, agent_type=None):
    """Calculate the threshold values (thresholds for a uniform distribution)
    of an agent distribution given the weights of each agent type.

    The input has this form: ::

            [
            {'agent_type': 'agent_type_1',
                'weight': 0.2,
                'state': {
                    'id': 0
                }
            },
            {'agent_type': 'agent_type_2',
                'weight': 0.8,
                'state': {
                    'id': 1
                }
            }
            ]

    In this example, 20% of the nodes will be marked as type
    'agent_type_1'."""
    if network_agents:
        network_agents = deepcopy(network_agents)
    elif agent_type:
        network_agents = [{'agent_type': agent_type}]
    else:
        raise ValueError('Specify a distribution or a default agent type')
    total = sum((x.get('weight', 1) for x in network_agents))
    acc = 0
    for v in network_agents:
        if 'ids' in v:
            v['threshold'] = STATIC_THRESHOLD
            continue
        upper = acc + v.get('weight', 1) / total
        v['threshold'] = [acc, upper]
        acc = upper
    return network_agents

def serialize_distribution(network_agents, known_modules=[]):
    """When serializing an agent distribution, remove the thresholds, in order
    to avoid cluttering the YAML definition file."""
    d = deepcopy(list(network_agents))
    for v in d:
        if 'threshold' in v:
            del v['threshold']
        v['agent_type'] = serialize_type(v['agent_type'], known_modules=known_modules)
    return d

def _convert_agent_types(ind, to_string=False, **kwargs):
    """Convenience method to allow specifying agents by class or class name."""
    if to_string:
        return serialize_distribution(ind, **kwargs)
    return deserialize_distribution(ind, **kwargs)

def _agent_from_distribution(distribution, value=-1, agent_id=None):
    """Used in the initialization of agents given an agent distribution."""
    if value < 0:
        value = random.random()
    for d in sorted(distribution, key=lambda x: x['threshold']):
        threshold = d['threshold']
        if not (agent_id is not None and threshold == STATIC_THRESHOLD and (agent_id in d['ids']) or (value >= threshold[0] and value < threshold[1])):
            continue
        state = {}
        if 'state' in d:
            state = deepcopy(d['state'])
        return (d['agent_type'], state)
    raise Exception('Distribution for value {} not found in: {}'.format(value, distribution))

def status_codes_by_date_stats():
    """Get stats for status codes by date.

    Returns:
        list: status codes + date grouped by type: 2xx, 3xx, 4xx, 5xx, attacks."""
    def date_counter(queryset):
        return dict(Counter(map(lambda dt: ms_since_epoch(datetime.combine(make_naive(dt), datetime.min.time())), list(queryset.values_list('datetime', flat=True)))))
    codes = {low: date_counter(RequestLog.objects.filter(status_code__gte=low, status_code__lt=high)) for low, high in ((200, 300), (300, 400), (400, 500))}
    codes[500] = date_counter(RequestLog.objects.filter(status_code__gte=500))
    codes['attacks'] = date_counter(RequestLog.objects.filter(status_code__in=(400, 444, 502)))
    stats = {}
    for code in (200, 300, 400, 500, 'attacks'):
        for date, count in codes[code].items():
            if stats.get(date, None) is None:
                stats[date] = {200: 0, 300: 0, 400: 0, 500: 0, 'attacks': 0}
            stats[date][code] += count
    stats = sorted([(k, v) for k, v in stats.items()], key=lambda x: x[0])
    return stats

def random_secret_exponent(curve_order):
    """Generates a random secret exponent."""
    while True:
        random_hex = hexlify(dev_urandom_entropy(32))
        random_int = int(random_hex, 16)
        if random_int >= 1 and random_int < curve_order:
            break
    return random_int

def get_entry_by_filter(filename, filter_function, ignore_fields=None):
    """Get an entry from a BibTeX file.

    .. note ::

        Returns the first matching entry.

    :param filename: The name of the BibTeX file.
    :param filter_function: A function returning ``True`` or ``False``             whether the entry should be included or not.
    :param ignore_fields: An optional list of fields to strip from the BibTeX             file.

    :returns: A ``bibtexparser.BibDatabase`` object representing the             first matching entry. ``None`` if entry was not found."""
    if ignore_fields is None:
        ignore_fields = []
    with open(filename, 'r') as fh:
        bibtex = bibtexparser.load(fh)
    matching_entry = None
    try:
        for entry in bibtex.entries:
            if filter_function(entry):
                matching_entry = entry
    except KeyError:
        return None
    if matching_entry is None:
        return None
    matching_entry = {k: matching_entry[k] for k in matching_entry if k not in ignore_fields}
    bib_db = bibtexparser.bibdatabase.BibDatabase()
    bib_db.entries = [matching_entry]
    return bib_db

def get_entry(filename, identifier, ignore_fields=None):
    """Get an entry from a BibTeX file.

