def gw_get(object_dict, name=None, plugin=None):
    """Getter function to retrieve objects from a given object dictionary.

    Used mainly to provide get() inside patterns.

    :param object_dict: objects, which must have 'name' and 'plugin' as attribute
    :type object_dict: dictionary
    :param name: name of the object
    :type name: str
    :param plugin: plugin name, which registers the object
    :return: None, single object or dict of objects"""
    if plugin is not None:
        if name is None:
            object_list = {}
            for key in object_dict.keys():
                if object_dict[key].plugin == plugin:
                    object_list[key] = object_dict[key]
            return object_list
        elif name in object_dict.keys():
            if object_dict[name].plugin == plugin:
                return object_dict[name]
            else:
                return None
        else:
            return None
    elif name is None:
        return object_dict
    elif name in object_dict.keys():
        return object_dict[name]
    else:
        return None

def cleanup_dirs(patterns, dry_run=False, workdir='.'):
    """Remove directories (and their contents) recursively.
    Skips removal if directories does not exist.

    :param patterns:    Directory name patterns, like "**/tmp*" (as list).
    :param dry_run:     Dry-run mode indicator (as bool).
    :param workdir:     Current work directory (default=".")"""
    current_dir = Path(workdir)
    python_basedir = Path(Path(sys.executable).dirname()).joinpath('..').abspath()
    warn2_counter = 0
    for dir_pattern in patterns:
        for directory in path_glob(dir_pattern, current_dir):
            directory2 = directory.abspath()
            if sys.executable.startswith(directory2):
                print("SKIP-SUICIDE: '%s' contains current python executable" % directory)
                continue
            elif directory2.startswith(python_basedir):
                if warn2_counter <= 4:
                    print("SKIP-SUICIDE: '%s'" % directory)
                warn2_counter += 1
                continue
            if dry_run:
                print('RMTREE: %s (dry-run)' % directory)
            else:
                print('RMTREE: %s' % directory)
                directory.rmtree_p()

