def unescape_json_str(st):
    """Unescape Monero json encoded string
    /monero/external/rapidjson/reader.h

    :param st:
    :return:"""
    c = 0
    ln = len(st)
    escape_chmap = {b'b': b'\x08', b'f': b'\x0c', b'n': b'\n', b'r': b'\r', b't': b'\t', b'\\': b'\\', b'"': b'"', b'/': b'\\/'}
    ret = []
    def at(i):
        return st[i:i + 1]
    while c < ln:
        if at(c) == b'\\':
            if at(c + 1) == b'u':
                ret.append(bytes([int(st[c + 2:c + 6], 16)]))
                c += 6
            else:
                ret.append(escape_chmap[at(c + 1)])
                c += 2
        else:
            ret.append(at(c))
            c += 1
    df = b''.join(ret)
    return df

def escape_string_json(st):
    """Escaping string for json
    /Users/dusanklinec/workspace/monero/external/rapidjson/writer.h
    :param st:
    :return:"""
    ret = []
    c = 0
    ln = len(st)
    escape_chmap = {b'\x08': b'b', b'\x0c': b'f', b'\n': b'n', b'\r': b'r', b'\t': b't', b'\\': b'\\', b'"': b'"', b'\\/': b'/'}
    while c < ln:
        ch = st[c:c + 1]
        if ch in escape_chmap:
            ret.append(b'\\' + escape_chmap[ch])
        elif ord(ch) < 32:
            ret.append(b'\\u%04X' % ord(ch))
        else:
            ret.append(ch)
        c += 1
    return b''.join(ret)

def map_or_apply(function, param):
    """Map the function on ``param``, or apply it, depending whether ``param``             is a list or an item.

    :param function: The function to apply.
    :param param: The parameter to feed the function with (list or item).
    :returns: The computed value or ``None``."""
    try:
        if isinstance(param, list):
            return [next(iter(function(i))) for i in param]
        else:
            return next(iter(function(param)))
    except StopIteration:
        return None

def is_elem_ref(elem_ref):
    """Returns true if the elem_ref is an element reference

    :param elem_ref:
    :return:"""
    return elem_ref and isinstance(elem_ref, tuple) and (len(elem_ref) == 3) and (elem_ref[0] == ElemRefObj or elem_ref[0] == ElemRefArr)

def has_elem(elem_ref):
    """Has element?
    :param elem_ref:
    :return:"""
    if not is_elem_ref(elem_ref):
        return False
    elif elem_ref[0] == ElemRefObj:
        return hasattr(elem_ref[1], elem_ref[2])
    elif elem_ref[0] == ElemRefArr:
        return elem_ref[2] in elem_ref[1]

def get_elem(elem_ref, default=None):
    """Gets the element referenced by elem_ref or returns the elem_ref directly if its not a reference.

    :param elem_ref:
    :param default:
    :return:"""
    if not is_elem_ref(elem_ref):
        return elem_ref
    elif elem_ref[0] == ElemRefObj:
        return getattr(elem_ref[1], elem_ref[2], default)
    elif elem_ref[0] == ElemRefArr:
        return elem_ref[1][elem_ref[2]]

def set_elem(elem_ref, elem):
    """Sets element referenced by the elem_ref. Returns the elem.

    :param elem_ref:
    :param elem:
    :return:"""
    if elem_ref is None or elem_ref == elem or (not is_elem_ref(elem_ref)):
        return elem
    elif elem_ref[0] == ElemRefObj:
        setattr(elem_ref[1], elem_ref[2], elem)
        return elem
    elif elem_ref[0] == ElemRefArr:
        elem_ref[1][elem_ref[2]] = elem
        return elem

def eref(obj, key, is_assoc=None):
    """Returns element reference
    :param obj:
    :param key:
    :param is_assoc:
    :return:"""
    if obj is None:
        return None
    if isinstance(key, int) or (is_assoc is not None and is_assoc):
        return (ElemRefArr, get_elem(obj), key)
    else:
        return (ElemRefObj, get_elem(obj), key)

def _(path):
    """Normalize path to unicode
    :param path: path
    :return: normalize path

    >>> _(None)
    u''
    >>> _(u("test1"))
    u'test1'
    >>> _("test2")
    u'test2'"""
    if path is None:
        return u('')
    if not PY3:
        if type(path) == unicode:
            return path
        try:
            return _decode_utf8(path)
        except UnicodeDecodeError:
            pass
    return path

