def find_identifiers(src):
    """Search for a valid identifier (DOI, ISBN, arXiv, HAL) in a given file.

    .. note::

        This function returns the first matching identifier, that is the most
        likely to be relevant for this file. However, it may fail and return an
        identifier taken from the references or another paper.

    .. note::

        You will need to have ``pdftotext`` and/or ``djvutxt`` installed                 system-wide before processing files with this function.


    :params src: Path to the file to scan.

    :returns: a tuple (type, identifier) or ``(None, None)`` if not found or             an error occurred."""
    if src.endswith('.pdf'):
        totext = subprocess.Popen(['pdftotext', src, '-'], stdout=subprocess.PIPE, stderr=subprocess.PIPE, bufsize=1)
    elif src.endswith('.djvu'):
        totext = subprocess.Popen(['djvutxt', src], stdout=subprocess.PIPE, stderr=subprocess.PIPE, bufsize=1)
    else:
        return (None, None)
    while totext.poll() is None:
        extract_full = ' '.join([i.decode('utf-8').strip() for i in totext.stdout.readlines()])
        for identifier in __valid_identifiers__:
            module = sys.modules.get('libbmc.%s' % (identifier,), None)
            if module is None:
                continue
            found_id = getattr(module, 'extract_from_text')(extract_full)
            if found_id:
                totext.terminate()
                return (identifier, found_id[0])
    return (None, None)

def init(filename=ConfigPath):
    """Loads INI configuration into this module's attributes."""
    section, parts = ('DEFAULT', filename.rsplit(':', 1))
    if len(parts) > 1 and os.path.isfile(parts[0]):
        filename, section = parts
    if not os.path.isfile(filename):
        return
    vardict, parser = (globals(), configparser.RawConfigParser())
    parser.optionxform = str
    try:
        def parse_value(raw):
            try:
                return json.loads(raw)
            except ValueError:
                return raw
        txt = open(filename).read()
        if not re.search('\\[\\w+\\]', txt):
            txt = '[DEFAULT]\n' + txt
        parser.readfp(StringIO.StringIO(txt), filename)
        for k, v in parser.items(section):
            vardict[k] = parse_value(v)
    except Exception:
        logging.warn('Error reading config from %s.', filename, exc_info=True)

def save(filename=ConfigPath):
    """Saves this module's changed attributes to INI configuration."""
    default_values = defaults()
    parser = configparser.RawConfigParser()
    parser.optionxform = str
    try:
        save_types = (basestring, int, float, tuple, list, dict, type(None))
        for k, v in sorted(globals().items()):
            if not isinstance(v, save_types) or k.startswith('_') or default_values.get(k, parser) == v:
                continue
            try:
                parser.set('DEFAULT', k, json.dumps(v))
            except Exception:
                pass
        if parser.defaults():
            with open(filename, 'wb') as f:
                f.write('# %s %s configuration written on %s.\n' % (Title, Version, datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')))
                parser.write(f)
        else:
            try:
                os.unlink(filename)
            except Exception:
                pass
    except Exception:
        logging.warn('Error writing config to %s.', filename, exc_info=True)

def defaults(values={}):
    """Returns a once-assembled dict of this module's storable attributes."""
    if values:
        return values
    save_types = (basestring, int, float, tuple, list, dict, type(None))
    for k, v in globals().items():
        if isinstance(v, save_types) and (not k.startswith('_')):
            values[k] = v
    return values

