def command_mkdir(args):
    """Create a non-existing directory (or more ...).
    If the directory exists, the step is skipped.
    Similar to the UNIX command: 'mkdir -p dir'"""
    errors = 0
    for directory in args.dirs:
        if os.path.exists(directory):
            if not os.path.isdir(directory):
                sys.stdout.write('mkdir: %s\n' % directory)
                sys.stdout.write('ERROR: Exists already, but as file...\n')
                errors += 1
        else:
            assert not os.path.isdir(directory)
            sys.stdout.write('mkdir: %s\n' % directory)
            os.makedirs(directory)
    return errors

def eq_obj_slots(l, r):
    """Compares objects with __slots__ defined
    :param l:
    :param r:
    :return:"""
    for f in l.__slots__:
        if getattr(l, f, None) != getattr(r, f, None):
            return False
    return True

def eq_obj_contents(l, r):
    """Compares object contents, supports slots
    :param l:
    :param r:
    :return:"""
    if l.__class__ is not r.__class__:
        return False
    if hasattr(l, '__slots__'):
        return eq_obj_slots(l, r)
    else:
        return l.__dict__ == r.__dict__

def slot_obj_dict(o):
    """Builds dict for o with __slots__ defined
    :param o:
    :return:"""
    d = {}
    for f in o.__slots__:
        d[f] = getattr(o, f, None)
    return d

