def paths_in_directory(input_directory):
    """Generate a list of all files in input_directory, each as a list containing path components."""
    paths = []
    for base_path, directories, filenames in os.walk(input_directory):
        relative_path = os.path.relpath(base_path, input_directory)
        path_components = relative_path.split(os.sep)
        if path_components[0] == '.':
            path_components = path_components[1:]
        if path_components and path_components[0].startswith('.'):
            continue
        path_components = filter(bool, path_components)
        for filename in filenames:
            if filename.startswith('.'):
                continue
            paths.append(path_components + [filename])
    return paths

def __to_float(val, digits):
    """Convert val into float with digits decimal."""
    try:
        return round(float(val), digits)
    except (ValueError, TypeError):
        return float(0)

def __getBarFCName(pressure):
    """Parse the pressure and return FC (String)."""
    if pressure is None:
        return None
    press = __to_float1(pressure)
    if press < 974:
        return 'Thunderstorms'
    if press < 990:
        return 'Stormy'
    if press < 1002:
        return 'Rain'
    if press < 1010:
        return 'Cloudy'
    if press < 1022:
        return 'Unstable'
    if press < 1035:
        return 'Stable'
    return 'Very dry'

def get_json_data(latitude=52.091579, longitude=5.119734):
    """Get buienradar json data and return results."""
    final_result = {SUCCESS: False, MESSAGE: None, CONTENT: None, RAINCONTENT: None}
