def parse_json_data(content, raincontent, latitude=52.091579, longitude=5.119734, timeframe=60):
    """Parse the raw data and return as data dictionary."""
    result = {SUCCESS: False, MESSAGE: None, DATA: None}
    if timeframe < 5 or timeframe > 120:
        raise ValueError('Timeframe must be >=5 and <=120.')
    if content is not None:
        try:
            json_content = json.loads(content)
        except json.JSONDecodeError as err:
            result[MESSAGE] = 'Unable to parse content as json.'
            log.error('Unable to parse content as json. %s', err)
            return result
        result = __parse_ws_data(json_content, latitude, longitude)
        if result[SUCCESS] and raincontent is not None:
            data = __parse_precipfc_data(raincontent, timeframe)
            result[DATA][PRECIPITATION_FORECAST] = data
    log.debug('Extracted weather-data: %s', result[DATA])
    return result

def __get_url(url):
    """Load json data from url and return result."""
    log.info('Retrieving  weather data (%s)...', url)
    result = {SUCCESS: False, MESSAGE: None}
    try:
        r = requests.get(url)
        result[STATUS_CODE] = r.status_code
        result[HEADERS] = r.headers
        result[CONTENT] = r.text
        if 200 == r.status_code:
            result[SUCCESS] = True
        else:
            result[MESSAGE] = 'Got http statuscode: %d.' % r.status_code
        return result
    except requests.RequestException as ose:
        result[MESSAGE] = 'Error getting url data. %s' % ose
        log.error(result[MESSAGE])
    return result

def __parse_loc_data(loc_data, result):
    """Parse the json data from selected weatherstation."""
    result[DATA] = {ATTRIBUTION: ATTRIBUTION_INFO, FORECAST: [], PRECIPITATION_FORECAST: None}
    for key, [value, func] in SENSOR_TYPES.items():
        result[DATA][key] = None
        try:
            sens_data = loc_data[value]
            if key == CONDITION:
                desc = loc_data[__WEATHERDESCRIPTION]
                result[DATA][CONDITION] = __cond_from_desc(desc)
                result[DATA][CONDITION][IMAGE] = loc_data[__ICONURL]
                continue
            if key == STATIONNAME:
                result[DATA][key] = __getStationName(loc_data[__STATIONNAME], loc_data[__STATIONID])
                continue
            if func is not None:
                result[DATA][key] = func(sens_data)
            else:
                result[DATA][key] = sens_data
        except KeyError:
            if result[MESSAGE] is None:
                result[MESSAGE] = 'Missing key(s) in br data: '
            result[MESSAGE] += '%s ' % value
            log.warning("Data element with key='%s' not loaded from br data!", key)
    result[SUCCESS] = True
    return result

def __parse_fc_data(fc_data):
    """Parse the forecast data from the json section."""
    fc = []
    for day in fc_data:
        fcdata = {CONDITION: __cond_from_desc(__get_str(day, __WEATHERDESCRIPTION)), TEMPERATURE: __get_float(day, __MAXTEMPERATURE), MIN_TEMP: __get_float(day, __MINTEMPERATURE), MAX_TEMP: __get_float(day, __MAXTEMPERATURE), SUN_CHANCE: __get_int(day, __SUNCHANCE), RAIN_CHANCE: __get_int(day, __RAINCHANCE), RAIN: __get_float(day, __MMRAINMAX), MIN_RAIN: __get_float(day, __MMRAINMIN), MAX_RAIN: __get_float(day, __MMRAINMAX), SNOW: 0, WINDFORCE: __get_int(day, __WIND), WINDDIRECTION: __get_str(day, __WINDDIRECTION), DATETIME: __to_localdatetime(__get_str(day, __DAY))}
        fcdata[CONDITION][IMAGE] = day[__ICONURL]
        fc.append(fcdata)
    return fc

def __get_float(section, name):
    """Get the forecasted float from json section."""
    try:
        return float(section[name])
    except (ValueError, TypeError, KeyError):
        return float(0)

def __cond_from_desc(desc):
    """Get the condition name from the condition description."""
    for code, [condition, detailed, exact, exact_nl] in __BRCONDITIONS.items():
        if exact_nl == desc:
            return {CONDCODE: code, CONDITION: condition, DETAILED: detailed, EXACT: exact, EXACTNL: exact_nl}
    return None

def __select_nearest_ws(jsondata, latitude, longitude):
    """Select the nearest weatherstation."""
    log.debug('__select_nearest_ws: latitude: %s, longitude: %s', latitude, longitude)
    dist = 0
    dist2 = 0
    loc_data = None
    try:
        ws_json = jsondata[__ACTUAL]
        ws_json = ws_json[__STATIONMEASUREMENTS]
    except (KeyError, TypeError):
        log.warning('Missing section in Buienradar xmldata (%s).Can happen 00:00-01:00 CE(S)T', __STATIONMEASUREMENTS)
        return None
    for wstation in ws_json:
        dist2 = __get_ws_distance(wstation, latitude, longitude)
        if dist2 is not None:
            if loc_data is None or dist2 < dist:
                dist = dist2
                loc_data = wstation
    if loc_data is None:
        log.warning('No weatherstation selected; aborting...')
        return None
    else:
        try:
            log.debug("Selected weatherstation: code='%s', name='%s', lat='%s', lon='%s'.", loc_data[__STATIONID], loc_data[__STATIONNAME], loc_data[__LAT], loc_data[__LON])
        except KeyError:
            log.debug('Selected weatherstation')
        return loc_data

def __get_ws_distance(wstation, latitude, longitude):
    """Get the distance to the weatherstation from wstation section of json.

    wstation: weerstation section of buienradar json (dict)
    latitude: our latitude
    longitude: our longitude"""
    if wstation:
        try:
            wslat = float(wstation[__LAT])
            wslon = float(wstation[__LON])
            dist = vincenty((latitude, longitude), (wslat, wslon))
            log.debug('calc distance: %s (latitude: %s, longitude: %s, wslat: %s, wslon: %s)', dist, latitude, longitude, wslat, wslon)
            return dist
        except (ValueError, TypeError, KeyError):
            return None
    else:
        return None

def astext(data):
    """Given a unicode/str/bytes always return str.

    We prefer to work with the 'native' string type for the version of python
    we run on, and this gets us that."""
    if isinstance(data, str):
        return data
    elif isinstance(data, text_type):
        return data.encode('utf-8', 'ignore')
    elif isinstance(data, binary_type):
        return data.decode('utf-8', 'ignore')
    raise TypeError('{!r} not a string'.format(data))

def get_store(logger: Logger=None) -> 'Store':
    """Get and configure the storage backend"""
    from trading_bots.conf import settings
    store_settings = settings.storage
    store = store_settings.get('name', 'json')
    if store == 'json':
