def get_pipeline_inputs(job, input_flag, input_file):
    """Get the input file from s3 or disk, untargz if necessary and then write to file job store.
    :param job: job
    :param str input_flag: The name of the flag
    :param str input_file: The value passed in the config file
    :return: The jobstore ID for the file"""
    work_dir = job.fileStore.getLocalTempDir()
    job.fileStore.logToMaster('Obtaining file (%s) to the file job store' % os.path.basename(input_file))
    if input_file.startswith('http'):
        assert input_file.startswith('https://s3'), input_file + ' is not an S3 file'
        input_file = get_file_from_s3(job, input_file, write_to_jobstore=False)
    elif input_file.startswith('S3'):
        input_file = get_file_from_s3(job, input_file, write_to_jobstore=False)
    else:
        assert os.path.exists(input_file), 'Bogus Input : ' + input_file
    if 'tar' not in input_flag:
        input_file = untargz(input_file, work_dir)
    return job.fileStore.writeGlobalFile(input_file)

def most_probable_alleles(allele_list):
    """This module accepts a list of tuples of (allele, p_value) pairs. It returns the 2 most probable
    alleles for that group."""
    all_alleles = defaultdict()
    for allele, pvalue in allele_list:
        allele = re.split(':', allele)
        if len(allele) < 2:
            continue
        allele = ':'.join([allele[0], allele[1]])
        try:
            all_alleles[allele].append(float(pvalue))
        except KeyError:
            all_alleles[allele] = [float(pvalue)]
    if len(all_alleles.keys()) <= 2:
        return all_alleles.keys()
    else:
        return sorted(all_alleles.keys(), key=lambda x: (-len(all_alleles[x]), sum(all_alleles[x])))[0:2]

def is_gzipfile(filename):
    """This function attempts to ascertain the gzip status of a file based on the "magic signatures" of
    the file. This was taken from the stack overflow
    http://stackoverflow.com/questions/13044562/python-mechanism-to-identify-compressed-file-type        -and-uncompress"""
    assert os.path.exists(filename), 'Input {} does not '.format(filename) + 'point to a file.'
    with file(filename, 'rb') as in_f:
        start_of_file = in_f.read(3)
        if start_of_file == '\x1f\x8b\x08':
            try:
                _ = Samfile(filename)
            except ValueError:
                return True
            else:
                return False
        else:
            return False

def parse_phlat_file(phlatfile, mhc_alleles):
    """Parse the input phlat file to pull out the alleles it contains
    :param phlatfile: Open file descriptor for a phlat output sum file
    :param mhc_alleles: dictionary of alleles."""
    for line in phlatfile:
        if line.startswith('Locus'):
            continue
        line = line.strip().split()
        if line[0].startswith('HLA_D'):
            line[0] = line[0][:-1]
        if line[1] == 'no':
            continue
        if line[4] != 'NA':
            split_field = line[1].split(':')
            if len(split_field) >= 2 and (not split_field[1] == 'xx'):
                mhc_alleles[line[0]].append((line[1], line[4]))
        if line[5] != 'NA':
            split_field = line[2].split(':')
            if len(split_field) >= 2 and (not split_field[1] == 'xx'):
                mhc_alleles[line[0]].append((line[2], line[5]))
    return mhc_alleles

def file_xext(filepath):
    """Get the file extension wrt compression from the filename (is it tar or targz)
    :param str filepath: Path to the file
    :return str ext: Compression extension name"""
    ext = os.path.splitext(filepath)[1]
    if ext == '.gz':
        xext = os.path.splitext(os.path.splitext(filepath)[0])[1]
        if xext == '.tar':
            ext = xext + ext
    elif ext == '.tar':
        pass
    else:
        ext = ''
    return ext

def get_iso_time_str(timestamp: Union[int, float, str, datetime]=None) -> str:
    """Get the ISO time string from a timestamp or date obj. Returns current time str if no timestamp is passed"""
    if isinstance(timestamp, (int, float)):
        maya_dt = maya.MayaDT(timestamp)
    elif isinstance(timestamp, str):
        maya_dt = maya.when(timestamp)
    elif timestamp is None:
        maya_dt = maya.now()
    else:
        raise ValueError(f'`{type(timestamp)}` is not supported')
    return maya_dt.iso8601()

def truncate(value: Decimal, n_digits: int) -> Decimal:
    """Truncates a value to a number of decimals places"""
    return Decimal(math.trunc(value * 10 ** n_digits)) / 10 ** n_digits

def truncate_to(value: Decimal, currency: str) -> Decimal:
    """Truncates a value to the number of decimals corresponding to the currency"""
    decimal_places = DECIMALS.get(currency.upper(), 2)
    return truncate(value, decimal_places)

def truncate_money(money: Money) -> Money:
    """Truncates money amount to the number of decimals corresponding to the currency"""
    amount = truncate_to(money.amount, money.currency)
    return Money(amount, money.currency)

def spread_value(value: Decimal, spread_p: Decimal) -> Tuple[Decimal, Decimal]:
    """Returns a lower and upper value separated by a spread percentage"""
    upper = value * (1 + spread_p)
    lower = value / (1 + spread_p)
    return (lower, upper)

def spread_money(money: Money, spread_p: Decimal) -> Tuple[Money, Money]:
    """Returns a lower and upper money amount separated by a spread percentage"""
    upper, lower = spread_value(money.amount, spread_p)
    return (Money(upper, money.currency), Money(lower, money.currency))

def check_valid_ad_range(date):
    """Checks if the english date is in valid range for conversion"""
    if date < values.START_EN_DATE or date > values.END_EN_DATE:
        raise ValueError('Date out of range')
    return True

def check_valid_bs_range(date):
    """Checks if the nepali date is in valid range for conversion"""
    ERR_MSG = '%s out of range' % str(date)
    if date.year < values.START_NP_YEAR or date.year > values.END_NP_YEAR:
        raise ValueError(ERR_MSG)
    if date.month < 1 or date.month > 12:
        raise ValueError(ERR_MSG)
    if date.day < 1 or date.day > values.NEPALI_MONTH_DAY_DATA[date.year][date.month - 1]:
        raise ValueError(ERR_MSG)
    return True

def nepali_number(number):
    """Convert a number to nepali"""
    nepnum = ''
    for n in str(number):
        nepnum += values.NEPDIGITS[int(n)]
    return nepnum

def filter_geometry(queryset, **filters):
    """Helper function for spatial lookups filters.

    Provide spatial lookup types as keywords without underscores instead of the
    usual "geometryfield__lookuptype" format."""
    fieldname = geo_field(queryset).name
    query = {'%s__%s' % (fieldname, k): v for k, v in filters.items()}
    return queryset.filter(**query)

def geo_field(queryset):
    """Returns the GeometryField for a django or spillway GeoQuerySet."""
    for field in queryset.model._meta.fields:
        if isinstance(field, models.GeometryField):
            return field
    raise exceptions.FieldDoesNotExist('No GeometryField found')

def get_srid(queryset):
    """Returns the GeoQuerySet spatial reference identifier."""
    try:
        srid = list(six.viewvalues(queryset.query.annotations))[0].srid
    except (AttributeError, IndexError):
        srid = None
    return srid or geo_field(queryset).srid

def docker_path(filepath, work_dir=None):
    """Given a path, return that files path inside the docker mount directory (/data).

    :param str filepath: The path to a file
    :param str work_dir: The part of the path to replace with /data
    :return: The docker-friendly path for `filepath`
    :rtype: str"""
    if work_dir:
        return re.sub(work_dir, '/data', filepath)
    else:
        return os.path.join('/data', os.path.basename(filepath))

def delete_fastqs(job, patient_dict):
    """Delete the fastqs from the job Store once their purpose has been achieved (i.e. after all
    mapping steps)

    :param dict patient_dict: Dict of list of input fastqs"""
    for key in patient_dict.keys():
        if 'fastq' not in key:
            continue
        job.fileStore.logToMaster('Deleting "%s:%s" ' % (patient_dict['patient_id'], key) + 'from the filestore.')
        job.fileStore.deleteGlobalFile(patient_dict[key])
    return None

def delete_bams(job, bams, patient_id):
    """Delete the bams from the job Store once their purpose has been achieved (i.e. after all
    mutation calling steps). Will also delete the chimeric junction file from Star.

    :param dict bams: Dict of bam and bai files
    :param str patient_id: The ID of the patient for logging purposes."""
    bams = {b: v for b, v in bams.items() if (b.endswith('.bam') or b.endswith('.bai')) and v is not None}
    if bams:
        for key, val in bams.items():
            job.fileStore.logToMaster('Deleting "%s" for patient "%s".' % (key, patient_id))
            job.fileStore.deleteGlobalFile(val)
    elif 'rna_genome' in bams:
        delete_bams(job, bams['rna_genome'], patient_id)
        job.fileStore.logToMaster('Deleting "rna_transcriptome.bam" for patient "%s".' % patient_id)
        job.fileStore.deleteGlobalFile(bams['rna_transcriptome.bam'])
    elif 'rnaChimeric.out.junction' in bams:
        job.fileStore.logToMaster('Deleting "rnaChimeric.out.junction" for patient "%s".' % patient_id)
        job.fileStore.deleteGlobalFile(bams['rnaChimeric.out.junction'])
    else:
        pass

def parse_chromosome_string(job, chromosome_string):
    """Parse a chromosome string into a list.

    :param chromosome_string: Input chromosome string
    :return: list of chromosomes to handle
    :rtype: list"""
    if chromosome_string is None:
        return []
    else:
        assert isinstance(chromosome_string, str)
        chroms = [c.strip() for c in chromosome_string.split(',')]
        if 'canonical' in chroms:
            assert 'canonical_chr' not in chroms, 'Cannot have canonical and canonical_chr'
            chr_prefix = False
            chroms.remove('canonical')
            out_chroms = [str(c) for c in range(1, 23)] + ['X', 'Y']
        elif 'canonical_chr' in chroms:
            assert 'canonical' not in chroms, 'Cannot have canonical and canonical_chr'
            chr_prefix = True
            chroms.remove('canonical_chr')
            out_chroms = ['chr' + str(c) for c in range(1, 23)] + ['chrX', 'chrY']
        else:
            chr_prefix = None
            out_chroms = []
        for chrom in chroms:
            if chr_prefix is not None and chrom.startswith('chr') is not chr_prefix:
                job.fileStore.logToMaster('chromosome %s does not match the rest that %s begin with "chr".' % (chrom, 'all' if chr_prefix else "don't"), level=logging.WARNING)
            out_chroms.append(chrom)
        return chrom_sorted(out_chroms)

def canonical_chrom_sorted(in_chroms):
    """Sort a list of chromosomes in the order 1..22, X, Y, M/MT

    :param list in_chroms: Input chromosomes
    :return: Sorted chromosomes
    :rtype: list[str]"""
    if len(in_chroms) == 0:
        return []
    chr_prefix = False
    mt = False
    if in_chroms[0].startswith('chr'):
        in_chroms = [x.lstrip('chr') for x in in_chroms]
        chr_prefix = True
    if 'MT' in in_chroms:
        in_chroms[in_chroms.index('MT')] = 'M'
        mt = True
    in_chroms = sorted(in_chroms, key=lambda c: int(c) if c not in ('X', 'Y', 'M') else c)
    try:
        m_index = in_chroms.index('M')
    except ValueError:
        pass
    else:
        in_chroms.pop(m_index)
        in_chroms.append('M')
    if mt:
        in_chroms[in_chroms.index('M')] = 'MT'
    if chr_prefix:
        in_chroms = [''.join(['chr', x]) for x in in_chroms]
    return in_chroms

def email_report(job, univ_options):
