def _rest(url, req, data=None):
    """Send a rest rest request to the server."""
    if url.upper().startswith('HTTPS'):
        print('Secure connection required: Please use HTTPS or https')
        return ''
    req = req.upper()
    if req != 'GET' and req != 'PUT' and (req != 'POST') and (req != 'DELETE'):
        return ''
    status, body = _api_action(url, req, data)
    if int(status) >= 200 and int(status) <= 226:
        return body
    else:
        return body

def _api_action(url, req, data=None):
    """Take action based on what kind of request is needed."""
    requisite_headers = {'Accept': 'application/json', 'Content-Type': 'application/json'}
    auth = (user, token)
    if req == 'GET':
        response = requests.get(url, headers=requisite_headers, auth=auth)
    elif req == 'PUT':
        response = requests.put(url, headers=requisite_headers, auth=auth, data=data)
    elif req == 'POST':
        response = requests.post(url, headers=requisite_headers, auth=auth, data=data)
    elif req == 'DELETE':
        response = requests.delete(url, headers=requisite_headers, auth=auth)
    return (response.status_code, response.text)

def delegate(attribute_name, method_names):
    """Pass the call to the attribute called attribute_name for every method listed in method_names."""
    info = {'attribute': attribute_name, 'methods': method_names}
    def decorator(cls):
        """Decorate class."""
        attribute = info['attribute']
        if attribute.startswith('__'):
            attribute = '_' + cls.__name__ + attribute
        for name in info['methods']:
            setattr(cls, name, eval('lambda self, *a, **kw: self.{0}.{1}(*a, **kw)'.format(attribute, name)))
        return cls
    return decorator

def pattern_to_str(pattern):
    """Convert regex pattern to string.

    If pattern is string it returns itself,
    if pattern is SRE_Pattern then return pattern attribute
    :param pattern: pattern object or string
    :return: str: pattern sttring"""
    if isinstance(pattern, str):
        return repr(pattern)
    else:
        return repr(pattern.pattern) if pattern else None

def parse_inventory(inventory_output=None):
    """Parse the inventory text and return udi dict."""
    udi = {'name': '', 'description': '', 'pid': '', 'vid': '', 'sn': ''}
    if inventory_output is None:
        return udi
    capture_next = False
    chassis_udi_text = None
    for line in inventory_output.split('\n'):
        lc_line = line.lower()
        if ('chassis' in lc_line or 'switch system' in lc_line or 'rack' in lc_line) and 'name' in lc_line and 'descr':
            capture_next = True
            chassis_udi_text = line
            continue
        if capture_next:
            inventory_output = chassis_udi_text + '\n' + line
            break
    match = re.search('(?i)NAME: (?P<name>.*?),? (?i)DESCR', inventory_output, re.MULTILINE)
    if match:
        udi['name'] = match.group('name').strip('" ,')
    match = re.search('(?i)DESCR: (?P<description>.*)', inventory_output, re.MULTILINE)
    if match:
        udi['description'] = match.group('description').strip('" ')
    match = re.search('(?i)PID: (?P<pid>.*?),? ', inventory_output, re.MULTILINE)
    if match:
        udi['pid'] = match.group('pid')
    match = re.search('(?i)VID: (?P<vid>.*?),? ', inventory_output, re.MULTILINE)
    if match:
        udi['vid'] = match.group('vid')
    match = re.search('(?i)SN: (?P<sn>.*)', inventory_output, re.MULTILINE)
    if match:
        udi['sn'] = match.group('sn').strip()
    return udi

def normalize_urls(urls):
    """Overload urls and make list of lists of urls."""
    _urls = []
    if isinstance(urls, list):
        if urls:
            if isinstance(urls[0], list):
                _urls = urls
            elif isinstance(urls[0], str):
                _urls = [urls]
        else:
            raise RuntimeError('No target host url provided.')
    elif isinstance(urls, str):
        _urls = [[urls]]
    return _urls

def convert2pstats(stats):
    """Converts the internal stat type of yappi(which is returned by a call to YFuncStats.get())
    as pstats object."""
    if not isinstance(stats, YFuncStats):
        raise YappiError('Source stats must be derived from YFuncStats.')
    import pstats
    class _PStatHolder:
        def __init__(self, d):
            self.stats = d
        def create_stats(self):
            pass
    def pstat_id(fs):
        return (fs.module, fs.lineno, fs.name)
    _pdict = {}
    _callers = {}
    for fs in stats:
        if not fs in _callers:
            _callers[fs] = {}
        for ct in fs.children:
            if not ct in _callers:
                _callers[ct] = {}
            _callers[ct][pstat_id(fs)] = (ct.ncall, ct.nactualcall, ct.tsub, ct.ttot)
    for fs in stats:
        _pdict[pstat_id(fs)] = (fs.ncall, fs.nactualcall, fs.tsub, fs.ttot, _callers[fs])
    return pstats.Stats(_PStatHolder(_pdict))

