def expand_constants(ins: Instruction, *, cf) -> Instruction:
    """Replace CONSTANT_INDEX operands with the literal Constant object from
    the constant pool.

    :param ins: Instruction to potentially modify.
    :param cf: The ClassFile instance used to resolve Constants.
    :return: Potentially modified instruction."""
    for i, operand in enumerate(ins.operands):
        if not isinstance(operand, Operand):
            continue
        if operand.op_type == OperandTypes.CONSTANT_INDEX:
            ins.operands[i] = cf.constants[operand.value]
    return ins

def simple_swap(ins: Instruction) -> Instruction:
    """Replaces one instruction with another based on the transform rules in
    the bytecode definitions. This can help simplify your code as it reduces
    the overall number of instructions. For example, `aload_0` will become
    `aload 0`.

    :param ins: Instruction to potentially modify.
    :return: Potentially modified instruction."""
    try:
        rule = ins.details['transform']['simple_swap']
    except KeyError:
        return ins
    replacement_ins = opcode_table[rule['op']]
    return Instruction(replacement_ins['mnemonic'], replacement_ins['op'], [Operand(replacement_ins['operands'][i][1], r) for i, r in enumerate(rule['operands'])], ins.pos)

def with_user_roles(roles):
    '''with_user_roles(roles)

    It allows to check if a user has access to a view by adding the decorator
    with_user_roles([])

    Requires flask-login

    In your model, you must have a property 'role', which will be invoked to
    be compared to the roles provided.

    If current_user doesn't have a role, it will throw a 403

    If the current_user is not logged in will throw a 401

    * Require Flask-Login
    ---
    Usage

    @app.route('/user')
    @login_require
    @with_user_roles(['admin', 'user'])
    def user_page(self):
        return "You've got permission to access this page."'''
    def wrapper(f):
        @functools.wraps(f)
        def wrapped(*args, **kwargs):
            if current_user.is_authenticated():
                if not hasattr(current_user, 'role'):
                    raise AttributeError("<'role'> doesn't exist in login 'current_user'")
                if current_user.role not in roles:
                    return abort(403)
            else:
                return abort(401)
            return f(*args, **kwargs)
        return wrapped
    return wrapper

def maintenance_view(template=None):
