def load_bytecode_definitions(*, path=None) -> dict:
    """Load bytecode definitions from JSON file.

    If no path is provided the default bytecode.json will be loaded.

    :param path: Either None or a path to a JSON file to load containing
                 bytecode definitions."""
    if path is not None:
        with open(path, 'rb') as file_in:
            j = json.load(file_in)
    else:
        try:
            j = json.loads(pkgutil.get_data('jawa.util', 'bytecode.json'))
        except json.JSONDecodeError:
            return {}
    for definition in j.values():
        operands = definition['operands']
        if operands:
            definition['operands'] = [[getattr(OperandFmts, oo[0]), OperandTypes[oo[1]]] for oo in operands]
    return {**j, **{v['op']: v for v in j.values()}}

def encode_modified_utf8(u: str) -> bytearray:
    """Encodes a unicode string as modified UTF-8 as defined in section 4.4.7
    of the JVM specification.

    :param u: unicode string to be converted.
    :returns: A decoded bytearray."""
    final_string = bytearray()
    for c in [ord(char) for char in u]:
        if c == 0 or 128 < c < 2047:
            final_string.extend([192 | 31 & c >> 6, 128 | 63 & c])
        elif c < 127:
            final_string.append(c)
        elif 2048 < c < 65535:
            final_string.extend([224 | 15 & c >> 12, 128 | 63 & c >> 6, 128 | 63 & c])
    return final_string

def deprecated_name(name):
    """Allow old method names for backwards compatability."""
    def decorator(func):
        """Decorator function."""
        def func_wrapper(self):
            """Wrapper for original function."""
            if hasattr(self, name):
                return getattr(self, name)
            else:
                return func(self)
        return func_wrapper
    return decorator

def _unassigned_ports():
    """Returns a set of all unassigned ports (according to IANA and Wikipedia)"""
    free_ports = ranges_to_set(_parse_ranges(_iana_unassigned_port_ranges()))
    known_ports = ranges_to_set(_wikipedia_known_port_ranges())
    return free_ports.difference(known_ports)

def _iana_unassigned_port_ranges():
    """Returns unassigned port ranges according to IANA."""
    page = urllib2.urlopen(IANA_DOWNLOAD_URL).read()
    xml = ElementTree.fromstring(page)
    records = xml.findall('{%s}record' % IANA_NS)
    for record in records:
        description = record.find('{%s}description' % IANA_NS).text
        if description == 'Unassigned':
            numbers = record.find('{%s}number' % IANA_NS).text
            yield numbers

def _parse_ranges(ranges):
    """Converts a list of string ranges to a list of [low, high] tuples."""
    for txt in ranges:
        if '-' in txt:
            low, high = txt.split('-')
        else:
            low, high = (txt, txt)
        yield (int(low), int(high))

def prompt(message, default=None, strip=True, suffix=' '):
    """Print a message and prompt user for input. Return user input."""
    if default is not None:
        prompt_text = '{0} [{1}]{2}'.format(message, default, suffix)
    else:
        prompt_text = '{0}{1}'.format(message, suffix)
    input_value = get_input(prompt_text)
    if input_value and strip:
        input_value = input_value.strip()
    if not input_value:
        input_value = default
    return input_value

def yesno(message, default='yes', suffix=' '):
    """Prompt user to answer yes or no. Return True if the default is chosen,
    otherwise False."""
    if default == 'yes':
        yesno_prompt = '[Y/n]'
    elif default == 'no':
        yesno_prompt = '[y/N]'
    else:
        raise ValueError("default must be 'yes' or 'no'.")
    if message != '':
        prompt_text = '{0} {1}{2}'.format(message, yesno_prompt, suffix)
    else:
        prompt_text = '{0}{1}'.format(yesno_prompt, suffix)
    while True:
        response = get_input(prompt_text).strip()
        if response == '':
            return True
        elif re.match('^(y)(es)?$', response, re.IGNORECASE):
            if default == 'yes':
                return True
            else:
                return False
        elif re.match('^(n)(o)?$', response, re.IGNORECASE):
            if default == 'no':
                return True
            else:
                return False

