def ranges_to_set(lst):
    """Convert a list of ranges to a set of numbers::

    >>> ranges = [(1,3), (5,6)]
    >>> sorted(list(ranges_to_set(ranges)))
    [1, 2, 3, 5, 6]"""
    return set(itertools.chain(*(range(x[0], x[1] + 1) for x in lst)))

def getattribute(model, item):
    """Chained lookup of item on model

    If item has dots (eg: 'foo.bar.baz'), recursively call getattribute():
    e = getattr(model, 'foo')
    e = getattr(e, 'bar')
    e = getattr(e, 'baz')
    At each step, check if e is a callable, and if so, use e()"""
    elements = item.split('.')
    element = elements.pop(0)
    try:
        attr = getattr(model, element, None)
    except:
        return
    if attr is None:
        return
    if callable(attr):
        try:
            attr = attr()
        except:
            return
    if elements:
        return getattribute(attr, '.'.join(elements))
    return attr

