def escape_query(query):
    """Escapes certain filter characters from an LDAP query."""
    return query.replace('\\', '\\5C').replace('*', '\\2A').replace('(', '\\28').replace(')', '\\29')

def parse_atom(tokens, options):
    """atom ::= '(' expr ')' | '[' expr ']' | 'options'
    | long | shorts | argument | command ;"""
    token = tokens.current()
    result = []
    if token == '(':
        tokens.move()
        result = [Required(*parse_expr(tokens, options))]
        if tokens.move() != ')':
            raise tokens.error("Unmatched '('")
        return result
    elif token == '[':
        tokens.move()
        result = [Optional(*parse_expr(tokens, options))]
        if tokens.move() != ']':
            raise tokens.error("Unmatched '['")
        return result
    elif token == 'options':
        tokens.move()
        return [AnyOptions()]
    elif token.startswith('--') and token != '--':
        return parse_long(tokens, options)
    elif token.startswith('-') and token not in ('-', '--'):
        return parse_shorts(tokens, options)
    elif token.startswith('<') and token.endswith('>') or token.isupper():
        return [Argument(tokens.move())]
    else:
        return [Command(tokens.move())]

def ordinal(value):
    """Converts a number to its ordinal representation.

    :param value: number

    >>> print(ordinal(1))
    1st
    >>> print(ordinal(11))
    11th
    >>> print(ordinal(101))
    101st
    >>> print(ordinal(104))
    104th
    >>> print(ordinal(113))
    113th
    >>> print(ordinal(123))
    123rd"""
    try:
        value = int(value)
    except (TypeError, ValueError):
        raise ValueError
    if value % 100 in (11, 12, 13):
        return '%d%s' % (value, ORDINAL_SUFFIX[0])
    else:
        return '%d%s' % (value, ORDINAL_SUFFIX[value % 10])

def _full_rename(args):
    """Return True only if the arguments passed specify exact namespaces
    and to conduct a rename of every namespace."""
