    return op(coll)

def e164(number):
    """Printable E.164 (The international public telecommunication numbering plan
    from ITU) numbers.

    :param number: string

    >>> print(e164(155542315678))
    +155542315678
    >>> print(e164('+31 20 5423 1567'))
    +312054231567"""
    if isinstance(number, six.integer_types):
        return e164('+%s' % number)
    elif isinstance(number, six.string_types):
        number = strip(number, '-. ()')
        if number.startswith('+'):
            number = number[1:]
        return u'+%s' % number

def meid(number, separator=u' '):
    """Printable Mobile Equipment Identifier (MEID) number.

    >>> print(meid(123456789012345678))
    1B 69B4BA 630F34 6
    >>> print(meid('1B69B4BA630F34'))
    1B 69B4BA 630F34 6"""
    if isinstance(number, six.string_types):
        number = re.sub('[\\s-]', '', number)
        try:
            number = '%014X' % int(number, 16)
        except ValueError:
            if len(number) < 18 and number.isdigit():
                return meid('%014X' % int(number), separator)
            else:
                raise ValueError(_('Invalid MEID, size mismatch'))
        else:
            if len(number) not in (14, 15):
                raise ValueError(_('Invalid MEID, size mismatch'))
    elif isinstance(number, six.integer_types):
        if number > 1152921504606846975:
            raise ValueError(_('Invalid MEID, size mismatch'))
        return meid(('%014X' % number)[:14], separator)
    else:
        raise TypeError(_('Invalid MEID, input type invalid'))
    number = number.upper()
    region = number[:2]
    manufacturer = number[2:8]
    serial_number = number[8:14]
    check_digit = number[14:]
    if check_digit == '':
        check_digit = luhn_calc(number, chars='0123456789ABCDEF')
    groups = (region, manufacturer, serial_number, check_digit)
    return separator.join(list(filter(None, groups)))

def experiment(f=None, local_dependencies=None, start_chiboard=True, default_logdir=''):
    """Decorator that transforms the decorated function into a chi.Experiment
    :param start_chiboard:
    :param f:
    :param local_dependencies:
    :return:"""
    if not f:
        return lambda f: experiment(f, local_dependencies, start_chiboard, default_logdir)
    else:
        if sys.modules[f.__module__].__name__ == '__main__':
            a = Experiment(f, local_dependencies, start_chiboard, default_logdir)
            a.parse_args_and_run()
        return Experiment(f, local_dependencies, start_chiboard, default_logdir).run

def project(*args, **kwargs):
    """Build a projection for MongoDB.

    Due to https://jira.mongodb.org/browse/SERVER-3156, until MongoDB 2.6,
    the values must be integers and not boolean.

    >>> project(a=True) == {'a': 1}
    True

    Once MongoDB 2.6 is released, replace use of this function with a simple
    dict."""
    projection = dict(*args, **kwargs)
    return {key: int(value) for key, value in six.iteritems(projection)}

