def Compare(fromMo, toMo, diff):
    """Internal method to support CompareManagedObject functionality."""
    from UcsBase import UcsUtils
    if fromMo.classId != toMo.classId:
        return CompareStatus.TypesDifferent
    for prop in UcsUtils.GetUcsPropertyMetaAttributeList(str(fromMo.classId)):
        propMeta = UcsUtils.IsPropertyInMetaIgnoreCase(fromMo.classId, prop)
        if propMeta != None:
            if propMeta.access == UcsPropertyMeta.Internal or propMeta.access == UcsPropertyMeta.ReadOnly or prop in toMo._excludePropList:
                continue
            if toMo.__dict__.has_key(prop) and fromMo.getattr(prop) != toMo.getattr(prop):
                diff.append(prop)
    if len(diff) > 0:
        return CompareStatus.PropsDifferent
    return CompareStatus.Equal

def nato(sentence, pad=' ', format='telephony'):
    """Transform a sentence using the NATO spelling alphabet.

    :param sentence: input sentence
    :param pad: default ``' '``
    :param format: default ``telephony``, options ``telephony`` or ``phonetic``

    >>> print(nato('Python'))
    papa yankee tango hotel oscar november

    >>> print(nato('Python', format='phonetic'))
    pah-pah yang-key tang-go hoh-tel oss-cah no-vem-ber"""
    try:
        return '' + ALPHABET['nato'][format](sentence, pad)
    except KeyError:
        raise TypeError('Unsupported NATO alphabet "%s"' % (format,))

def boundary_words(seq):
    """Wraps all word transitions with a boundary token character (\x00).

    Arguments:
    - `seq`:"""
    in_word = None
    for char in seq:
        if char == '\x00' and in_word is not None:
            in_word = not in_word
        elif char in WHITESPACE_CHARS:
            if in_word is not None and in_word:
                yield '\x00'
            in_word = False
        else:
            if in_word is not None and (not in_word):
                yield '\x00'
            in_word = True
        yield char

def get_page_number_from_request(request, querystring_key=PAGE_LABEL, default=1):
    """Retrieve the current page number from *GET* or *POST* data.

    If the page does not exists in *request*, or is not a number,
    then *default* number is returned."""
    try:
        if request.method == 'POST':
            page_number = request.POST[querystring_key]
        else:
            page_number = request.GET[querystring_key]
        return int(page_number)
    except (KeyError, TypeError, ValueError):
        return default

def _to_datetime(t):
    """Internal function that tries whatever to convert ``t`` into a
    :class:`datetime.datetime` object.


    >>> _to_datetime('2013-12-11')
    datetime.datetime(2013, 12, 11, 0, 0)
    >>> _to_datetime('Wed, 11 Dec 2013')
    datetime.datetime(2013, 12, 11, 0, 0)
    >>> _to_datetime('Wed, 11 Dec 13')
    datetime.datetime(2013, 12, 11, 0, 0)
    >>> _to_datetime('2012-06-13T15:24:17')
    datetime.datetime(2012, 6, 13, 15, 24, 17)"""
    if isinstance(t, six.integer_types + (float,)):
        return datetime.datetime.fromtimestamp(t).replace(microsecond=0)
    elif isinstance(t, six.string_types):
        for date_format in ALL_DATETIME_FORMATS:
            try:
                d = datetime.datetime.strptime(t, date_format)
                return d.replace(microsecond=0)
            except ValueError:
                pass
        raise ValueError(_('Format "%s" not supported') % t)
    elif isinstance(t, datetime.datetime):
        return t.replace(microsecond=0)
    elif isinstance(t, datetime.date):
        d = datetime.datetime.combine(t, datetime.time(0, 0))
        return d.replace(microsecond=0)
    else:
        raise TypeError

def _to_date(t):
    """Internal function that tries whatever to convert ``t`` into a
    :class:`datetime.date` object.

    >>> _to_date('2013-12-11')
    datetime.date(2013, 12, 11)
    >>> _to_date('Wed, 11 Dec 2013')
    datetime.date(2013, 12, 11)
    >>> _to_date('Wed, 11 Dec 13')
    datetime.date(2013, 12, 11)"""
    if isinstance(t, six.integer_types + (float,)):
        return datetime.date.fromtimestamp(t)
    elif isinstance(t, six.string_types):
        for date_format in ALL_DATE_FORMATS:
            try:
                return datetime.datetime.strptime(t, date_format).date()
            except ValueError:
                pass
        raise ValueError('Format not supported')
    elif isinstance(t, datetime.datetime):
        return t.date()
    elif isinstance(t, datetime.date):
        return t
    else:
        raise TypeError

def idf(posting, document_count):
    """A function to calculate the inverse document frequency for a posting.
    This is shared between the builder and the index."""
    documents_with_term = 0
    for field_name in posting:
        if field_name == '_index':
            continue
        documents_with_term += len(posting[field_name].keys())
    x = (document_count - documents_with_term + 0.5) / (documents_with_term + 0.5)
    return math.log(1 + abs(x))

def accessed(filename):
    """Retrieve how long ago a file has been accessed.

    :param filename: name of the file

    >>> print accessed(__file__)        # doctest: +SKIP
    just now"""
    if isinstance(filename, file):
        filename = filename.name
    return duration(os.stat(filename)[stat.ST_ATIME])

def created(filename):
    """Retrieve how long ago a file has been created.

    :param filename: name of the file

    >>> print created('/')             # doctest: +SKIP
    8 weeks ago"""
    if isinstance(filename, file):
        filename = filename.name
    return duration(os.stat(filename)[stat.ST_CTIME])

def modified(filename):
    """Retrieve how long ago a file has been modified.

    :param filename: name of the file

    >>> print modified('/')             # doctest: +SKIP
    3 days ago"""
    if isinstance(filename, file):
        filename = filename.name
    return duration(os.stat(filename)[stat.ST_MTIME])

def size(filename, format='decimal'):
    """Retrieve the size of a file.

    :param filename: name of the file

    >>> size('/etc/mime.types')         # doctest: +SKIP
    23.70 kB"""
    if isinstance(filename, file):
