def generate_trimmer(word_characters):
    """Returns a trimmer function from a string of word characters.

    TODO: lunr-languages ships with lists of word characters for each language
    I haven't found an equivalent in Python, we may need to copy it."""
    start_re = '^[^{}]+'.format(word_characters)
    end_re = '[^{}]+$'.format(word_characters)
    def trimmer(token, i=None, tokens=None):
        def trim(s, metadata=None):
            s = re.sub(start_re, '', s)
            s = re.sub(end_re, '', s)
            return s
        return token.update(trim)
    return trimmer

def _add_scheme():
    """urllib.parse doesn't support the mongodb scheme, but it's easy
    to make it so."""
    lists = [urllib.parse.uses_relative, urllib.parse.uses_netloc, urllib.parse.uses_query]
    for l in lists:
        l.append('mongodb')

def _termsize():
    """Get the current terminal size, returns a ``(height, width)`` tuple."""
    try:
        return struct.unpack('hh', fcntl.ioctl(sys.stdout.fileno(), termios.TIOCGWINSZ, '1234'))
    except:
        return (int(os.environ.get('LINES', 25)), int(os.environ.get('COLUMNS', 80)))

def nltk_stemmer(stemmer, token, i=None, tokens=None):
    """Wrapper around a NLTK SnowballStemmer, which includes stop words for
    each language.

    Args:
        stemmer (SnowballStemmer): Stemmer instance that performs the stemming.
        token (lunr.Token): The token to stem.
        i (int): The index of the token in a set.
        tokens (list): A list of tokens representing the set."""
    def wrapped_stem(token, metadata=None):
        return stemmer.stem(token)
    return token.update(wrapped_stem)

def set_log_level(verbose, quiet):
    """Ses the logging level of the script based on command line options.

    Arguments:
    - `verbose`:
    - `quiet`:"""
    if quiet:
        verbose = -1
    if verbose < 0:
        verbose = logging.CRITICAL
    elif verbose == 0:
        verbose = logging.WARNING
    elif verbose == 1:
        verbose = logging.INFO
    elif 1 < verbose:
        verbose = logging.DEBUG
    LOGGER.setLevel(verbose)

def detect_pattern_format(pattern_filename, encoding, on_word_boundaries):
    """Automatically detects the pattern file format, and determines
    whether the Aho-Corasick string matching should pay attention to
    word boundaries or not.

    Arguments:
    - `pattern_filename`:
    - `encoding`:
    - `on_word_boundaries`:"""
    tsv = True
    boundaries = on_word_boundaries
    with open_file(pattern_filename) as input_file:
        for line in input_file:
            line = line.decode(encoding)
            if line.count('\t') != 1:
                tsv = False
            if '\\b' in line:
                boundaries = True
            if boundaries and (not tsv):
                break
    return (tsv, boundaries)

def warn_prefix_values(trie):
    """Prints warning messages for every node that has both a value and a
    longest_prefix."""
    for current, _parent in trie.dfs():
        if current.has_value and current.longest_prefix is not None:
            LOGGER.warn('pattern {} (value {}) is a superstring of pattern {} (value {}) and will never be matched'.format(current.prefix, current.value, current.longest_prefix.prefix, current.longest_prefix.value))

def rewrite_str_with_trie(sval, trie, boundaries=False, slow=False):
    """Rewrites a string using the given trie object.

    Arguments:
    - `sval`:
    - `trie`:
    - `boundaries`:
    - `slow`:"""
    if boundaries:
        sval = fsed.ahocorasick.boundary_transform(sval)
    if slow:
        sval = trie.replace(sval)
    else:
        sval = trie.greedy_replace(sval)
    if boundaries:
        sval = ''.join(fsed.ahocorasick.boundary_untransform(sval))
    return sval

def main(pattern_filename, input_filenames, pattern_format, output_filename, encoding, words, by_line, slow, verbose, quiet):
    """Search and replace on INPUT_FILE(s) (or standard input), with
    matching on fixed strings."""
    set_log_level(verbose, quiet)
    if slow:
        by_line = True
    by_line = True
    LOGGER.info('fsed {} input {} output {}'.format(pattern_filename, input_filenames, output_filename))
    if not input_filenames:
        input_filenames = ('-',)
    if not output_filename:
        output_filename = '-'
    trie, boundaries = build_trie(pattern_filename, pattern_format, encoding, words)
    if not slow:
        warn_prefix_values(trie)
    LOGGER.info('writing to {}'.format(output_filename))
    with open_file(output_filename, 'wb') as output_file:
        for input_filename in input_filenames:
            with open_file(input_filename) as input_file:
                LOGGER.info('reading {}'.format(input_filename))
                if by_line:
                    num_lines = 0
                    for line in input_file:
                        line = line.decode(encoding).rstrip('\n')
                        line = rewrite_str_with_trie(line, trie, boundaries, slow)
                        output_file.write((line + '\n').encode(encoding))
                        num_lines += 1
                    LOGGER.info('{} lines written'.format(num_lines))
                else:
                    raise NotImplementedError

