def cache_for(**timedelta_kw):
    """Set Cache-Control headers and Expires-header.

    Expects a timedelta instance."""
    max_age_timedelta = timedelta(**timedelta_kw)
    def decorate_func(func):
        @wraps(func)
        def decorate_func_call(*a, **kw):
            callback = SetCacheControlHeadersFromTimedeltaCallback(max_age_timedelta)
            registry_provider = AfterThisRequestCallbackRegistryProvider()
            registry = registry_provider.provide()
            registry.add(callback)
            return func(*a, **kw)
        return decorate_func_call
    return decorate_func

def dont_cache():
    """Set Cache-Control headers for no caching

    Will generate proxy-revalidate, no-cache, no-store, must-revalidate,
    max-age=0."""
    def decorate_func(func):
        @wraps(func)
        def decorate_func_call(*a, **kw):
            callback = SetCacheControlHeadersForNoCachingCallback()
            registry_provider = AfterThisRequestCallbackRegistryProvider()
            registry = registry_provider.provide()
            registry.add(callback)
            return func(*a, **kw)
        return decorate_func_call
    return decorate_func

def singleton(klass):
    """Create singleton from class"""
    instances = {}
    def getinstance(*args, **kwargs):
        if klass not in instances:
            instances[klass] = klass(*args, **kwargs)
        return instances[klass]
    return wraps(klass)(getinstance)

def translation_activate_block(function=None, language=None):
    """Activate language only for one method or function"""
    def _translation_activate_block(function):
        def _decorator(*args, **kwargs):
            tmp_language = translation.get_language()
            try:
                translation.activate(language or settings.LANGUAGE_CODE)
                return function(*args, **kwargs)
            finally:
                translation.activate(tmp_language)
        return wraps(function)(_decorator)
    if function:
        return _translation_activate_block(function)
    else:
        return _translation_activate_block

def loadCoeffs(filename):
    """load igrf12 coeffs from file
    :param filename: file which save coeffs (str)
    :return: g and h list one by one (list(float))"""
    gh = []
    gh2arr = []
    with open(filename) as f:
        text = f.readlines()
        for a in text:
            if a[:2] == 'g ' or a[:2] == 'h ':
                b = a.split()[3:]
                b = [float(x) for x in b]
                gh2arr.append(b)
        gh2arr = np.array(gh2arr).transpose()
        N = len(gh2arr)
        for i in range(N):
            if i < 19:
                for j in range(120):
                    gh.append(gh2arr[i][j])
            else:
                for p in gh2arr[i]:
                    gh.append(p)
        gh.append(0)
        return gh

def run(path, tasks):
    """Run a pylpfile."""
    readable_path = make_readable_path(path)
    if not os.path.isfile(path):
        logger.log(logger.red("Can't read pylpfile "), logger.magenta(readable_path))
        sys.exit(-1)
    else:
        logger.log('Using pylpfile ', logger.magenta(readable_path))
    try:
        runpy.run_path(path, None, 'pylpfile')
    except Exception as e:
        traceback.print_exc(file=sys.stdout)
        logger.log(logger.red('\nAn error has occurred during the execution of the pylpfile'))
        sys.exit(-1)
    for name in tasks:
        pylp.start(name)
    loop = asyncio.get_event_loop()
    loop.run_until_complete(wait_and_quit(loop))

def parse_fixed_width(types, lines):
    """Parse a fixed width line."""
    values = []
    line = []
    for width, parser in types:
        if not line:
            line = lines.pop(0).replace('\n', '')
        values.append(parser(line[:width]))
        line = line[width:]
    return values

def _parse_curves(block, **kwargs):
    """Parse nonlinear curves block."""
    count = int(block.pop(0))
    curves = []
    for i in range(count):
        for param in ['mod_reduc', 'damping']:
            length, name = parse_fixed_width([(5, int), (65, to_str)], block)
            curves.append(site.NonlinearProperty(name, parse_fixed_width(length * [(10, float)], block), parse_fixed_width(length * [(10, float)], block), param))
    length = int(block[0][:5])
    soil_types = parse_fixed_width((length + 1) * [(5, int)], block)[1:]
    return {(soil_types[i // 2], c.param): c for i, c in enumerate(curves)}

def _parse_soil_profile(block, units, curves, **kwargs):
    """Parse soil profile block."""
    wt_layer, length, _, name = parse_fixed_width(3 * [(5, int)] + [(55, to_str)], block)
    layers = []
    soil_types = []
    for i in range(length):
        index, soil_idx, thickness, shear_mod, damping, unit_wt, shear_vel = parse_fixed_width([(5, int), (5, int), (15, to_float)] + 4 * [(10, to_float)], block)
        st = site.SoilType(soil_idx, unit_wt, curves[soil_idx, 'mod_reduc'], curves[soil_idx, 'damping'])
        try:
            st = soil_types[soil_types.index(st)]
        except ValueError:
            soil_types.append(st)
        layers.append(site.Layer(st, thickness, shear_vel))
    if units == 'english':
        for st in soil_types:
            st.unit_wt *= 0.00015708746
        for l in layers:
            l.thickness *= 0.3048
            l.shear_vel *= 0.3048
    p = site.Profile(layers)
    p.update_layers()
    p.wt_depth = p[wt_layer - 1].depth
    return p

def _parse_input_loc(block, profile, **kwargs):
    """Parse input location block."""
    layer, wave_field = parse_fixed_width(2 * [(5, int)], block)
    return profile.location(motion.WaveField[wave_field], index=layer - 1)

def _parse_run_control(block):
    """Parse run control block."""
    _, max_iterations, strain_ratio, _, _ = parse_fixed_width(2 * [(5, int)] + [(10, float)] + 2 * [(5, int)], block)
    return propagation.EquivalentLinearCalculation(strain_ratio, max_iterations, tolerance=10.0)

def _make_color_fn(color):
    """Create a function that set the foreground color."""
    def _color(text=''):
        return _color_sep + color + _color_sep2 + text + _color_sep + 'default' + _color_sep2
    return _color

def just_log(*texts, sep=''):
    """Log a text without adding the current time."""
    if config.silent:
        return
    text = _color_sep + 'default' + _color_sep2 + sep.join(texts)
    array = text.split(_color_sep)
    for part in array:
        parts = part.split(_color_sep2, 1)
        if len(parts) != 2 or not parts[1]:
            continue
        if not config.color:
            print(parts[1], end='')
        else:
            colors.foreground(parts[0])
            print(parts[1], end='', flush=colors.is_win32)
    if config.color:
        colors.foreground('default')
    print()

def src(globs, **options):
    """Read some files and return a stream."""
    if isinstance(globs, str):
        globs = [globs]
    files = find_files(globs)
    stream = Stream()
    options['cwd'] = config.cwd
    if 'base' in options:
        options['base'] = os.path.abspath(options['base'])
    for infile in files:
        file = File(infile[2], **options)
        file.relpath = file.path
        file.order = infile[0]
        file.base = options.get('base', infile[1])
        stream.append_file(file)
    stream.end_of_stream()
    if options.get('read', True):
        return stream.pipe(FileReader())
    return stream

