def _yql_query(yql):
    """Fetch data from Yahoo! Return a dict if successfull or None."""
    url = _YAHOO_BASE_URL.format(urlencode({'q': yql}))
    _LOGGER.debug('Send request to url: %s', url)
    try:
        request = urlopen(url)
        rawData = request.read()
        data = json.loads(rawData.decode('utf-8'))
        _LOGGER.debug('Query data from yahoo: %s', str(data))
        return data.get('query', {}).get('results', {})
    except (urllib.error.HTTPError, urllib.error.URLError):
        _LOGGER.info("Can't fetch data from Yahoo!")
    return None

def get_woeid(lat, lon):
    """Ask Yahoo! who is the woeid from GPS position."""
    yql = _YQL_WOEID.format(lat, lon)
    tmpData = _yql_query(yql)
    if tmpData is None:
        _LOGGER.error('No woid is received!')
        return None
    return tmpData.get('place', {}).get('woeid', None)

def task(name, deps=None, fn=None):
    """Define a new task."""
    if callable(deps):
        fn = deps
        deps = None
    if not deps and (not fn):
        logger.log(logger.red("The task '%s' is empty" % name))
    else:
        tasks[name] = [fn, deps]

def start(name, called=None):
    """Start a task."""
    if name not in tasks:
        logger.log(logger.red("Task '%s' not in your pylpfile" % name))
    else:
        task = tasks[name]
        runner = TaskRunner(name, task[0], task[1], called)
        running.append(runner)
        return runner

def pipes(stream, *transformers):
