def _named_tuple_converter(tuple_type):
    """Return an _AggregateConverter for named tuples of the given type."""
    def _from_dict(dict_value):
        if dict_value:
            return tuple_type(**dict_value)
        return None
    def _to_dict(value):
        if value:
            return value._asdict()
        return {}
    converter = _AggregateConverter(from_dict=_from_dict, to_dict=_to_dict)
    return converter

def _parse_boolean(element_text, state):
    """Parse the raw XML string as a boolean value."""
    value = None
    lowered_text = element_text.lower()
    if lowered_text == 'true':
        value = True
    elif lowered_text == 'false':
        value = False
    else:
        state.raise_error(InvalidPrimitiveValue, 'Invalid boolean value "{}"'.format(element_text))
    return value

def _string_parser(strip_whitespace):
    """Return a parser function for parsing string values."""
    def _parse_string_value(element_text, _state):
        if element_text is None:
            value = ''
        elif strip_whitespace:
            value = element_text.strip()
        else:
            value = element_text
        return value
    return _parse_string_value

def _user_object_converter(cls):
    """Return an _AggregateConverter for a user object of the given class."""
    def _from_dict(dict_value):
        try:
            object_value = cls(**dict_value)
        except TypeError:
            object_value = cls()
            for field_name, field_value in dict_value.items():
                setattr(object_value, field_name, field_value)
        return object_value
    def _to_dict(value):
        if value:
            return value.__dict__
        return {}
    return _AggregateConverter(from_dict=_from_dict, to_dict=_to_dict)

def _xml_namespace_strip(root):
    """Strip the XML namespace prefix from all element tags under the given root Element."""
    if '}' not in root.tag:
        return
    for element in root.iter():
        if '}' in element.tag:
            element.tag = element.tag.split('}')[1]
        else:
            pass

def field_init(self, *args, **kwargs):
    """Patches a Django Field's `__init__` method for easier usage of optional `kwargs`. It defines a `humanized` attribute
    on a field for better display of its value."""
    humanize_func = kwargs.pop('humanized', None)
    if humanize_func:
        def humanize(val, inst, *args, **kwargs):
            return humanize_func(val, inst, *args, field=self, **kwargs)
        self.humanized = humanize
    else:
        self.humanized = self.default_humanized
    getattr(self, '_init_chamber_patch_')(*args, **kwargs)

def runm():
    """This is super minimal and pretty hacky, but it counts as a first pass.
    """
    signal.signal(signal.SIGINT, signal_handler)
    count = int(sys.argv.pop(1))
    processes = [Process(target=run, args=()) for x in range(count)]
    try:
        for p in processes:
            p.start()
    except KeyError:
        pass
    finally:
        for p in processes:
            p.join()

def get_fd(file_or_fd, default=None):
    """Helper function for getting a file descriptor."""
    fd = file_or_fd
    if fd is None:
        fd = default
    if hasattr(fd, 'fileno'):
        fd = fd.fileno()
    return fd

def forkexec(argv, env=None):
    """Fork a child process."""
    child_pid = os.fork()
    if child_pid == 0:
        os.closerange(3, MAXFD)
        environ = os.environ.copy()
        if env is not None:
            environ.update(env)
        os.execve(argv[0], argv, environ)
    return child_pid

def forkexec_pty(argv, env=None, size=None):
    """Fork a child process attached to a pty."""
    child_pid, child_fd = pty.fork()
    if child_pid == 0:
        os.closerange(3, MAXFD)
        environ = os.environ.copy()
        if env is not None:
            environ.update(env)
        os.execve(argv[0], argv, environ)
    if size is None:
        try:
            size = get_terminal_size(1)
        except Exception:
            size = (80, 24)
    set_terminal_size(child_fd, size)
    return (child_pid, child_fd)

def find_executable(filename, environ=None):
    """Find an executable by searching the user's $PATH."""
    if environ is None:
        environ = os.environ
    path = environ.get('PATH', '/usr/local/bin:/usr/bin:/bin').split(':')
    for dirpath in path:
        dirpath = os.path.abspath(dirpath.strip())
        filepath = os.path.normpath(os.path.join(dirpath, filename))
        if os.path.exists(filepath):
            return filepath
    return None

def get_ancestor_processes():
    """Get a list of the executables of all ancestor processes."""
    if not _ANCESTOR_PROCESSES and psutil is not None:
        proc = psutil.Process(os.getpid())
        while proc.parent() is not None:
            try:
                _ANCESTOR_PROCESSES.append(proc.parent().exe())
                proc = proc.parent()
            except psutil.Error:
                break
    return _ANCESTOR_PROCESSES

def get_default_shell(environ=None, fallback=_UNSPECIFIED):
    """Get the user's default shell program."""
    if environ is None:
        environ = os.environ
    if 'PIAS_OPT_SHELL' in environ:
        return environ['PIAS_OPT_SHELL']
    shells = []
    for filename in (environ.get('SHELL'), 'bash', 'sh'):
        if filename is not None:
            filepath = find_executable(filename, environ)
            if filepath is not None:
                shells.append(filepath)
    for ancestor in get_ancestor_processes():
        if ancestor in shells:
            return ancestor
    for shell in shells:
        return shell
    if fallback is not _UNSPECIFIED:
        return fallback
    raise ValueError('Could not find a shell')

def get_default_terminal(environ=None, fallback=_UNSPECIFIED):
    """Get the user's default terminal program."""
    if environ is None:
        environ = os.environ
    if 'PIAS_OPT_TERMINAL' in environ:
        return environ['PIAS_OPT_TERMINAL']
    terminals = []
    colorterm = environ.get('COLORTERM')
    for filename in (colorterm, 'gnome-terminal', 'konsole', 'xterm'):
        if filename is not None:
            filepath = find_executable(filename, environ)
            if filepath is not None:
                terminals.append(filepath)
    for ancestor in get_ancestor_processes():
        if ancestor in terminals:
            return ancestor
    for term in terminals:
        return term
    if fallback is not _UNSPECIFIED:
        return fallback
    raise ValueError('Could not find a terminal')

def get_pias_script(environ=None):
    """Get the path to the playitagainsam command-line script."""
    if os.path.basename(sys.argv[0]) == 'pias':
        return sys.argv[0]
    filepath = find_executable('pias', environ)
    if filepath is not None:
        return filepath
    filepath = os.path.join(os.path.dirname(__file__), '__main__.py')
    if os.path.exists(filepath):
        return filepath
    raise RuntimeError('Could not locate the pias script.')

def get_terminal_size(fd):
    """Get the (width, height) size tuple for the given pty fd."""
    sizebuf = array.array('h', [0, 0])
    fcntl.ioctl(fd, termios.TIOCGWINSZ, sizebuf, True)
    return tuple(reversed(sizebuf))

