def utf8(value, encoding=None):
    """Converts a string argument to a byte string.
    """
    if isinstance(value, _UTF8_TYPES):
        return value
    if not isinstance(value, text_type):
        raise TypeError('Expected bytes, unicode, or None; got %r' % type(value))
    if encoding is not None:
        return value.encode(encoding)
    try:
        return value.encode('utf-8')
    except:
        return value.encode('gbk')

def to_unicode(value, encoding=None):
    """Converts a string argument to a unicode string.
    """
    if isinstance(value, text_type):
        return value
    elif isinstance(value, type(None)):
        return text_type(value)
    if not isinstance(value, bytes):
        raise TypeError('Expected bytes, unicode, or None; got %r' % type(value))
    if encoding is not None:
        return value.decode(encoding)
    else:
        try:
            value = value.decode('utf-8')
        except:
            try:
                value = value.decode('gbk')
            except:
                pass
        return value

def dec2str(n):
    """decimal number to string."""
    s = hex(int(n))[2:].rstrip('L')
    if len(s) % 2 != 0:
        s = '0' + s
    return hex2str(s)

def bin2str(b):
    """Binary to string."""
    ret = []
    for pos in range(0, len(b), 8):
        ret.append(chr(int(b[pos:pos + 8], 2)))
    return ''.join(ret)

def n2s(n):
    """Number to string."""
    s = hex(n)[2:].rstrip('L')
    if len(s) % 2 != 0:
        s = '0' + s
    return s.decode('hex')

def colorize(style, msg, resp):
    """Taken and modified from `django.utils.log.ServerFormatter.format`
    to mimic runserver's styling."""
    code = resp.status.split(maxsplit=1)[0]
    if code[0] == '2':
        msg = style.HTTP_SUCCESS(msg)
    elif code[0] == '1':
        msg = style.HTTP_INFO(msg)
    elif code == '304':
        msg = style.HTTP_NOT_MODIFIED(msg)
    elif code[0] == '3':
        msg = style.HTTP_REDIRECT(msg)
    elif code == '404':
        msg = style.HTTP_NOT_FOUND(msg)
    elif code[0] == '4':
        msg = style.HTTP_BAD_REQUEST(msg)
    else:
        msg = style.HTTP_SERVER_ERROR(msg)
    return msg

def discover(service, timeout=5, retries=5):
    """Discovers services on a network using the SSDP Protocol."""
    group = ('239.255.255.250', 1900)
    message = '\r\n'.join(['M-SEARCH * HTTP/1.1', 'HOST: {0}:{1}', 'MAN: "ssdp:discover"', 'ST: {st}', 'MX: 3', '', ''])
    socket.setdefaulttimeout(timeout)
    responses = {}
    for _ in range(retries):
        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM, socket.IPPROTO_UDP)
        sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        sock.setsockopt(socket.IPPROTO_IP, socket.IP_MULTICAST_TTL, 2)
        data = message.format(*group, st=service)
        sock.sendto(data.encode('utf-8'), group)
        while True:
            try:
                response = SSDPResponse(sock.recv(1024))
                responses[response.location] = response
            except socket.timeout:
                break
        if responses:
            break
    return responses.values()

def string_variable_lookup(tb, s):
    """Look up the value of an object in a traceback by a dot-lookup string.
    ie. "self.crashreporter.application_name"

    Returns ValueError if value was not found in the scope of the traceback.

    :param tb: traceback
    :param s: lookup string
    :return: value of the"""
    refs = []
    dot_refs = s.split('.')
    DOT_LOOKUP = 0
    DICT_LOOKUP = 1
    for ii, ref in enumerate(dot_refs):
        dict_refs = dict_lookup_regex.findall(ref)
        if dict_refs:
            bracket = ref.index('[')
            refs.append((DOT_LOOKUP, ref[:bracket]))
            refs.extend([(DICT_LOOKUP, t) for t in dict_refs])
        else:
            refs.append((DOT_LOOKUP, ref))
    scope = tb.tb_frame.f_locals.get(refs[0][1], ValueError)
    if scope is ValueError:
        return scope
    for lookup, ref in refs[1:]:
        try:
            if lookup == DOT_LOOKUP:
                scope = getattr(scope, ref, ValueError)
            else:
                scope = scope.get(ref, ValueError)
        except Exception as e:
            logging.error(e)
            scope = ValueError
        if scope is ValueError:
            return scope
        elif isinstance(scope, (FunctionType, MethodType, ModuleType, BuiltinMethodType, BuiltinFunctionType)):
            return ValueError
    return scope

def get_local_references(tb, max_string_length=1000):
    """Find the values of the local variables within the traceback scope.

    :param tb: traceback
    :return: list of tuples containing (variable name, value)"""
    if 'self' in tb.tb_frame.f_locals:
        _locals = [('self', repr(tb.tb_frame.f_locals['self']))]
    else:
        _locals = []
    for k, v in tb.tb_frame.f_locals.iteritems():
        if k == 'self':
            continue
        try:
            vstr = format_reference(v, max_string_length=max_string_length)
            _locals.append((k, vstr))
        except TypeError:
            pass
    return _locals

def format_reference(ref, max_string_length=1000):
    """Converts an object / value into a string representation to pass along in the payload
    :param ref: object or value
    :param max_string_length: maximum number of characters to represent the object
    :return:"""
    _pass = lambda *args: None
    _numpy_info = ('dtype', 'shape', 'size', 'min', 'max')
    additionals = []
    if _NUMPY_INSTALLED and isinstance(ref, np.ndarray):
        for np_attr in _numpy_info:
            np_value = getattr(ref, np_attr, None)
            if np_value is not None:
                if inspect.isbuiltin(np_value):
                    try:
                        np_value = np_value()
                    except Exception as e:
                        logging.error(e)
                        continue
                additionals.append((np_attr, np_value))
    elif isinstance(ref, (list, tuple, set, dict)):
        length = getattr(ref, '__len__', _pass)()
        if length is not None:
            additionals.append(('length', length))
    if additionals:
        vstr = ', '.join(['%s: %s' % a for a in additionals] + [repr(ref)])
    else:
        vstr = repr(ref)
    if len(vstr) > max_string_length:
        vstr = vstr[:max_string_length] + ' ...'
    return vstr

def cli(action, config_file, debug, verbose):
    """Static asset management in python.

    Called with no arguments grablib will download, then build. You can also choose to only download or build.

