def get_closest_point_to_line(A, B, P):
    """Find the closest point on a line. This point will be reproducible by a Hue
    lamp."""
    AP = XYPoint(P.x - A.x, P.y - A.y)
    AB = XYPoint(B.x - A.x, B.y - A.y)
    ab2 = AB.x * AB.x + AB.y * AB.y
    ap_ab = AP.x * AB.x + AP.y * AB.y
    t = ap_ab / ab2
    if t < 0.0:
        t = 0.0
    elif t > 1.0:
        t = 1.0
    return XYPoint(A.x + AB.x * t, A.y + AB.y * t)

def parse_uri(config_uri):
    """Parse the ``config_uri`` into a :class:`plaster.PlasterURL` object.

    ``config_uri`` can be a relative or absolute file path such as
    ``development.ini`` or ``/path/to/development.ini``. The file must have
    an extension that can be handled by a :class:`plaster.ILoader`
    registered with the system.

    Alternatively, ``config_uri`` may be a :rfc:`1738`-style string."""
    if isinstance(config_uri, PlasterURL):
        return config_uri
    isabs = os.path.isabs(config_uri)
    if isabs:
        config_uri = 'dummy://' + config_uri
    parts = urlparse.urlparse(config_uri)
    path = urlparse.ParseResult(scheme='', netloc=parts.netloc, path=parts.path, params='', query='', fragment='').geturl()
    if path.startswith('//'):
        path = path[2:]
    if parts.scheme and (not isabs):
        scheme = parts.scheme
    else:
        scheme = os.path.splitext(path)[1]
        if scheme.startswith('.'):
            scheme = scheme[1:]
        if scheme:
            scheme = 'file+' + scheme
    query = parts.query if parts.query else None
    options = OrderedDict()
    if query:
        options.update(urlparse.parse_qsl(query))
    fragment = parts.fragment if parts.fragment else None
    if not scheme:
        raise InvalidURI(config_uri, 'Could not determine the loader scheme for the supplied config_uri "{0}"'.format(config_uri))
    return PlasterURL(scheme=scheme, path=path, options=options, fragment=fragment)

def terminal_width():
    """Returns the terminal's width (number of character columns)."""
    try:
        if os.name == 'nt':
            _WindowsCSBI.initialize()
            return _WindowsCSBI.get_info(_WindowsCSBI.HANDLE_STDOUT)['terminal_width']
        return struct.unpack('hhhh', fcntl.ioctl(0, termios.TIOCGWINSZ, '\x00' * 8))[1]
    except IOError:
        return 80

def get_remaining_width(sample_string, max_terminal_width=None):
    """Returns the number of characters available if sample string were to be printed in the terminal.

    Positional arguments:
    sample_string -- gets the length of this string.

    Keyword arguments:
    max_terminal_width -- limit the overall width of everything to these many characters.

    Returns:
    Integer."""
    if max_terminal_width is not None:
        available_width = min(terminal_width(), max_terminal_width)
    else:
        available_width = terminal_width()
    return available_width - len(sample_string)

