def tranz(parser, token, is_transchoice=False):
    """Templatetagish wrapper for Translator.trans()

    :param parser:
    :param token:
    :param is_transchoice:
    :return:"""
    tokens = token.split_contents()
    id = tokens[1]
    number = domain = locale = None
    parameters = {}
    if len(tokens) > 2:
        skip_idx = None
        for idx, token in enumerate(tokens[2:], start=2):
            if idx == skip_idx:
                skip_idx = None
                continue
            if '=' in token:
                k, v = (token[0:token.index('=')], token[token.index('=') + 1:])
                parameters[k] = v
            elif token == 'number':
                number = tokens[idx + 1]
                skip_idx = idx + 1
            elif token == 'from':
                domain = tokens[idx + 1]
                skip_idx = idx + 1
            elif token == 'into':
                locale = tokens[idx + 1]
                skip_idx = idx + 1
            else:
                raise TemplateSyntaxError('Unexpected token {0} in tag tranz'.format(token))
    if is_transchoice and number is None:
        raise TemplateSyntaxError('number parameter expected in tag {tag_name}')
    return TranzNode(id, parameters, domain, locale, number, is_transchoice=is_transchoice)

def tranz_context(parser, token):
    """Templatetagish wrapper for Translator.transchoice()"""
    tokens = token.split_contents()
    parameters = {}
    for idx, token in enumerate(tokens[1:], start=1):
        if '=' in token:
            if token[0:token.index('=')] not in ('domain', 'prefix', 'locale'):
                raise TemplateSyntaxError('Unexpected token {0} in tag {{tag_name}}'.format(token))
            k, v = (token[0:token.index('=')], token[token.index('=') + 1:])
            parameters[k] = v
        else:
            raise TemplateSyntaxError('Unexpected token {0} in tag {{tag_name}}'.format(token))
    return TranzContextNode(parameters.get('prefix', None), parameters.get('domain', None), parameters.get('locale', None))

def prepare_request(node):
    """Prepare request to node's API route

    :param Node node: the RAML node object"""
    if node.resource.method not in AVAILABLE_METHODS:
        raise UnsupportedHTTPMethodError(node.resource.method)
    def request(data=None, json=None, **kwargs):
        """Make request to node's API route with the given keyword arguments"""
        for key, value in kwargs.items():
            param = next((p for p in node.resource.query_params if p.name == key), None)
            if not param:
                raise UnsupportedQueryParameter(node.resource.path, key)
            if not match_type(value, param.type):
                raise TypeError("Resource Query Parameter has type '{0}' but expected type '{1}'".format(value.__class__.__name__, param.type))
        response = requests.request(node.resource.method, node.resource.absolute_uri, params=kwargs, data=data, json=json)
        return response
    return request

def get_transcoder():
    """Return the path to a transcoder (ffmpeg or avconv) with MP3 support."""
    transcoders = ['ffmpeg', 'avconv']
    transcoder_details = {}
    for transcoder in transcoders:
        command_path = shutil.which(transcoder)
        if command_path is None:
            transcoder_details[transcoder] = 'Not installed.'
            continue
        stdout = subprocess.run([command_path, '-codecs'], stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, universal_newlines=True).stdout
        mp3_encoding_support = 'libmp3lame' in stdout and 'disable-libmp3lame' not in stdout
        if mp3_encoding_support:
            transcoder_details[transcoder] = 'MP3 encoding support.'
            break
        else:
            transcoder_details[transcoder] = 'No MP3 encoding support.'
    else:
        raise ValueError(f'ffmpeg or avconv must be in the path and support mp3 encoding.\nDetails: {{transcoder_details}}')
    return command_path

def dictionary(values):
    """This function generates dictionary
    from values parameter.
    For example this:
    example = {
        'streetway': ('street', {'language': 'en'}),
        'first_name': ('first', {'language': 'en'})
    }
    chance.dictionary(example)
    will output something like this:
    {'streetway': 'Jabhuru Point', 'first_name': 'Eunice'}

    :param values: dict
    :return: dict"""
    result = dict()
    for key in values:
        fname = values[key][0]
        if fname not in functions_map:
            result[key] = values[key]
        else:
            params = values[key][1] if len(values[key]) == 2 else {}
            result[key] = functions_map[fname](**params)
    return result

def eventChunk(key, lines):
    """Parse EVENT chunks"""
    KEYWORDS = ('EVENT', 'NRPDS', 'NRGAG', 'COORD', 'GAGES', 'ACCUM', 'RATES', 'RADAR')
    NUM_CARDS = ('NRPDS', 'NRGAG')
    VALUE_CARDS = ('GAGES', 'ACCUM', 'RATES', 'RADAR')
    result = {'description': None, 'nrgag': None, 'nrpds': None, 'coords': [], 'valLines': []}
    chunks = pt.chunk(KEYWORDS, lines)
    for card, chunkList in iteritems(chunks):
        for chunk in chunkList:
            schunk = chunk[0].strip().split()
            if card == 'EVENT':
                schunk = pt.splitLine(chunk[0])
                result['description'] = schunk[1]
            elif card in NUM_CARDS:
                result[card.lower()] = schunk[1]
            elif card == 'COORD':
                schunk = pt.splitLine(chunk[0])
                try:
                    desc = schunk[3]
                except:
                    desc = ''
                coord = {'x': schunk[1], 'y': schunk[2], 'description': desc}
                result['coords'].append(coord)
            elif card in VALUE_CARDS:
                dateTime = datetime(year=int(schunk[1]), month=int(schunk[2]), day=int(schunk[3]), hour=int(schunk[4]), minute=int(schunk[5]))
                values = []
                for index in range(6, len(schunk)):
                    values.append(schunk[index])
                valueLine = {'type': schunk[0], 'dateTime': dateTime, 'values': values}
                result['valLines'].append(valueLine)
    return result

def eta_hms(seconds, always_show_hours=False, always_show_minutes=False, hours_leading_zero=False):
    """Converts seconds remaining into a human readable timestamp (e.g. hh:mm:ss, h:mm:ss, mm:ss, or ss).

    Positional arguments:
    seconds -- integer/float indicating seconds remaining.

    Keyword arguments:
    always_show_hours -- don't hide the 0 hours.
    always_show_minutes -- don't hide the 0 minutes.
    hours_leading_zero -- show 01:00:00 instead of 1:00:00.

    Returns:
    Human readable string."""
    final_hours, final_minutes, final_seconds = (0, 0, seconds)
    if final_seconds >= 3600:
        final_hours = int(final_seconds / 3600.0)
        final_seconds -= final_hours * 3600
    if final_seconds >= 60:
        final_minutes = int(final_seconds / 60.0)
        final_seconds -= final_minutes * 60
    final_seconds = int(ceil(final_seconds))
    if final_hours or always_show_hours:
        if hours_leading_zero:
            template = '{hour:02.0f}:{minute:02.0f}:{second:02.0f}'
        else:
            template = '{hour}:{minute:02.0f}:{second:02.0f}'
    elif final_minutes or always_show_minutes:
        template = '{minute:02.0f}:{second:02.0f}'
    else:
        template = '{second:02.0f}'
    return template.format(hour=final_hours, minute=final_minutes, second=final_seconds)

def datasetHeaderChunk(key, lines):
    """Process the dataset header"""
    KEYWORDS = ('DATASET', 'OBJTYPE', 'VECTYPE', 'BEGSCL', 'BEGVEC', 'OBJID', 'ND', 'NC', 'NAME')
    TYPE_KEYS = ('BEGSCL', 'BEGVEC')
    result = {'type': None, 'numberData': None, 'numberCells': None, 'name': None, 'objectID': None, 'objectType': None, 'vectorType': None}
    chunks = pt.chunk(KEYWORDS, lines)
    for key, chunkList in iteritems(chunks):
        for chunk in chunkList:
            schunk = pt.splitLine(chunk[0])
            if key == 'ND':
                result['numberData'] = int(schunk[1])
            elif key == 'NC':
                result['numberCells'] = int(schunk[1])
            elif key == 'NAME':
                result['name'] = schunk[1]
            elif key == 'OBJID':
                result['objectID'] = int(schunk[1])
            elif key == 'OBJTYPE':
                result['objectType'] = schunk[1]
            elif key == 'VECTYPE':
                result['vectorType'] = schunk[1]
            elif key in TYPE_KEYS:
                result['type'] = schunk[0]
    return result

def chunk(keywords, lines):
    """Divide a file into chunks between
    key words in the list"""
    chunks = dict()
    chunk = []
    for keyword in keywords:
        chunks[keyword] = []
    for line in lines:
        if line.strip():
            token = line.split()[0]
            if token in keywords:
                chunk = [line]
                chunks[token].append(chunk)
            else:
                chunk.append(line)
    return chunks

def valueReadPreprocessor(valueString, replaceParamsFile=None):
    """Apply global pre-processing to values during reading throughout the project.

    Args:
        valueString (str): String representing the value to be preprocessed.
        replaceParamsFile (gsshapy.orm.ReplaceParamFile, optional): Instance of the replace param file. Required if
            replacement variables are included in the project.

    Returns:
        str: Processed value as a string"""
    if type(valueString) is bool:
        log.warning('Only numerical variable types can be handled by the valueReadPreprocessor function.')
        return valueString
    processedValue = valueString
    if replaceParamsFile is not None and valueString is not None:
        if '[' in valueString or ']' in valueString:
            processedValue = '{0}'.format(REPLACE_NO_VALUE)
            for targetParam in replaceParamsFile.targetParameters:
                if targetParam.targetVariable == valueString:
                    processedValue = '{0}'.format(-1 * targetParam.id)
                    break
    return processedValue

def valueWritePreprocessor(valueString, replaceParamsFile=None):
    """Look up variable name in replace param file for the negative id given and return it.

    Args:
        valueString (str): String representing the value to be preprocessed.
        replaceParamsFile (gsshapy.orm.ReplaceParamFile, optional): Instance of the replace param file. Required if
            replacement variables are included in the project.

    Returns:
        str: Processed value as a string"""
    if type(valueString) is bool:
        log.warning('Only numerical variable types can be handled by the valueReadPreprocessor function.')
        return valueString
    variableString = valueString
    if replaceParamsFile is not None:
        if variableString == REPLACE_NO_VALUE:
            variableString = '[NO_VARIABLE]'
        else:
            try:
                number = int(valueString)
                if number < 0:
                    parameterID = number * -1
                    for targetParam in replaceParamsFile.targetParameters:
                        if targetParam.id == parameterID:
                            variableString = targetParam.targetVariable
                            break
            except:
                pass
    return variableString

def cardChunk(key, chunk):
    """Parse Card Chunk Method"""
    for line in chunk:
        values = []
        sline = line.strip().split()
        for idx in range(1, len(sline)):
            values.append(sline[idx])
    return {'card': sline[0], 'values': values}

def connectChunk(key, chunk):
    """Parse Card Chunk Method"""
    upLinks = []
    schunk = chunk[0].strip().split()
    for idx in range(4, len(schunk)):
        upLinks.append(schunk[idx])
    result = {'link': schunk[1], 'downLink': schunk[2], 'numUpLinks': schunk[3], 'upLinks': upLinks}
    return result

def linkChunk(key, chunk):
    """Parse LINK Chunk Method"""
    linkType = chunk[1].strip().split()[0]
    if linkType == 'DX':
        result = xSectionLink(chunk)
    elif linkType == 'STRUCTURE':
        result = structureLink(chunk)
    elif linkType in ('RESERVOIR', 'LAKE'):
        result = reservoirLink(chunk)
    return result

def reservoirLink(lines):
    """Parse RESERVOIR Link Method"""
    KEYWORDS = ('LINK', 'RESERVOIR', 'RES_MINWSE', 'RES_INITWSE', 'RES_MAXWSE', 'RES_NUMPTS', 'LAKE', 'MINWSE', 'INITWSE', 'MAXWSE', 'NUMPTS')
    result = {'header': {'link': None, 'res_minwse': None, 'res_initwse': None, 'res_maxwse': None, 'res_numpts': None, 'minwse': None, 'initwse': None, 'maxwse': None, 'numpts': None}, 'type': None, 'points': []}
    pair = {'i': None, 'j': None}
    chunks = pt.chunk(KEYWORDS, lines)
    for key, chunkList in iteritems(chunks):
        for chunk in chunkList:
            schunk = chunk[0].strip().split()
            if key in ('NUMPTS', 'RES_NUMPTS'):
                result['header'][key.lower()] = schunk[1]
                for idx in range(1, len(chunk)):
                    schunk = chunk[idx].strip().split()
                    for count, ordinate in enumerate(schunk):
                        if count % 2 == 0:
                            pair['i'] = ordinate
                        else:
                            pair['j'] = ordinate
                            result['points'].append(pair)
                            pair = {'i': None, 'j': None}
            elif key in ('LAKE', 'RESERVOIR'):
                result['type'] = schunk[0]
            else:
                result['header'][key.lower()] = schunk[1]
    return result

def nodeChunk(lines):
    """Parse NODE Method"""
    KEYWORDS = ('NODE', 'X_Y', 'ELEV')
    result = {'node': None, 'x': None, 'y': None, 'elev': None}
    chunks = pt.chunk(KEYWORDS, lines)
    for key, chunkList in iteritems(chunks):
        for chunk in chunkList:
            schunk = chunk[0].strip().split()
            if key == 'X_Y':
                result['x'] = schunk[1]
                result['y'] = schunk[2]
            else:
                result[key.lower()] = schunk[1]
    return result

def xSectionChunk(lines):
    """Parse XSEC Method"""
    KEYWORDS = ('MANNINGS_N', 'BOTTOM_WIDTH', 'BANKFULL_DEPTH', 'SIDE_SLOPE', 'NPAIRS', 'NUM_INTERP', 'X1', 'ERODE', 'MAX_EROSION', 'SUBSURFACE', 'M_RIVER', 'K_RIVER')
    result = {'mannings_n': None, 'bottom_width': None, 'bankfull_depth': None, 'side_slope': None, 'npairs': None, 'num_interp': None, 'erode': False, 'subsurface': False, 'max_erosion': None, 'm_river': None, 'k_river': None, 'breakpoints': []}
    chunks = pt.chunk(KEYWORDS, lines)
    for key, chunkList in iteritems(chunks):
        for chunk in chunkList:
            schunk = chunk[0].strip().split()
            if key == 'X1':
                x = schunk[1]
                y = schunk[2]
                result['breakpoints'].append({'x': x, 'y': y})
            if key in ('SUBSURFACE', 'ERODE'):
                result[key.lower()] = True
            else:
                result[key.lower()] = schunk[1]
    return result

def structureChunk(keywords, resultDict, lines):
    """Parse Weir and Culvert Structures Method"""
    chunks = pt.chunk(keywords, lines)
    for key, chunkList in iteritems(chunks):
        for chunk in chunkList:
            schunk = chunk[0].strip().split()
            resultDict[key.lower()] = schunk[1]
    return resultDict

