def _remote_github_url_to_string(remote_url):
    """Parse out the repository identifier from a github URL."""
    match = re.search('git@github\\.com:(.*)\\.git', remote_url)
    if not match:
        raise EnvironmentError('Remote is not a valid github URL')
    identifier = match.group(1)
    return re.sub('\\W', ':', identifier)

def cmd(*args, **kwargs):
    """Decorate a callable to replace it with a manufactured command
    class.

    Extends the interface of ``CommandDecorator``, allowing the same
    ``cmd`` to be used as a decorator or as a decorator factory::

        @cmd(root=True)
        def build():
            ...

        @build.register
        @cmd
        def deploy():
            ...

    Further enables composition of configuration, for example via
    partials, as helpers."""
    try:
        first, *remainder = args
    except ValueError:
        pass
    else:
        if callable(first):
            return CommandDecorator(*remainder, **kwargs)(first)
    return CommandDecorator(*args, **kwargs)

def sum_from(zero: T1=None) -> Callable[[ActualIterable[T1]], T1]:
    """>>> from Redy.Collections import Traversal, Flow
    >>> lst: Iterable[int] = [1, 2, 3]
    >>> x = Flow(lst)[Traversal.sum_from(0)].unbox
    >>> assert x is 6

    >>> x = Flow(lst)[Traversal.sum_from()].unbox
    >>> assert x is 6"""
    def _(collection: Iterable[T1]) -> T1:
        if zero is None:
            collection = iter(collection)
            _zero = next(collection)
            return builtins.sum(collection, _zero)
        return builtins.sum(collection, zero)
    return _

def each_do(action: Callable[[T], None]):
    """>>> from Redy.Collections import Traversal, Flow
    >>> lst: Iterable[int] = [1, 2, 3]
    >>> def action(x: int) -> None: print(x)
    >>> x = Flow(lst)[Traversal.each_do(action)]
    >>> assert x.unbox is None"""
    def inner(collection: ActualIterable[T]):
        for each in collection:
            action(each)
    return inner

def flatten_to(atom: Union[Tuple[Type[T]], Type[T]]):
    """>>> from Redy.Collections import Traversal, Flow
    >>> lst: Iterable[int] = [[1, 2, 3]]
    >>> x = Flow(lst)[Traversal.flatten_to(int)]
    >>> assert isinstance(x.unbox, Generator) and list(x.unbox) == [1, 2, 3]"""
    def inner(nested: ActualIterable[Union[T, ActualIterable[T]]]) -> ActualIterable[T]:
        for each in nested:
            if isinstance(each, atom):
                yield each
            else:
                yield from inner(each)
    return inner

def flatten_if(cond: Callable[[Union[T, ActualIterable[T]]], bool]):
    """>>> from Redy.Collections import Traversal, Flow
    >>> lst: Iterable[int] = [[1, 2, 3]]
    >>> x = Flow(lst)[Traversal.flatten_if(lambda _: isinstance(_, list))]
    >>> assert isinstance(x.unbox, Generator) and list(x.unbox) == [1, 2, 3]"""
    def inner(nested: ActualIterable[Union[T, ActualIterable[T]]]) -> ActualIterable[T]:
        for each in nested:
            if cond(each):
                yield from inner(each)
            else:
                yield each
    return inner

def chunk_by(fn: Callable[[T], object]):
    """>>> from Redy.Collections import Traversal, Flow
    >>> lst: Iterable[int] = [0, 1, 2, 3, 4, 5, 6]
    >>> x = Flow(lst)[Traversal.chunk_by(lambda x: x // 3)]
    >>> assert list(x.unbox) == [[0, 1, 2], [3, 4, 5], [6]]
    >>> x = Flow([])[Traversal.chunk_by(lambda x: x)]
    >>> assert list(x.unbox) == []"""
    def inner(seq: ActualIterable[T]) -> ActualIterable[ActualIterable[T]]:
        seq = iter(seq)
        try:
            head = next(seq)
        except StopIteration:
            return iter(seq)
        current_status = fn(head)
        group = [head]
        for each in seq:
            status = fn(each)
            if status != current_status:
                yield group
                group = [each]
            else:
                group.append(each)
            current_status = status
        if group:
            yield group
    return inner

def chunk(seq: ActualIterable[T]) -> ActualIterable[ActualIterable[T]]:
    """>>> from Redy.Collections import Traversal, Flow
    >>> x = [1, 1, 2]
    >>> assert Flow(x)[Traversal.chunk][list].unbox == [[1, 1], [2]]
    >>> assert Flow([])[Traversal.chunk][list].unbox == []"""
    seq = iter(seq)
    try:
        head = next(seq)
    except StopIteration:
        return iter(seq)
    current_status = head
    group = [head]
    for each in seq:
        status = each
        if status != current_status:
            yield group
            group = [each]
        else:
            group.append(each)
        current_status = status
    if group:
        yield group

def group_by(fn: Callable[[T], TR]):
    """>>> from Redy.Collections import Flow, Traversal
    >>> x = [1, '1', 1.0]
    >>> Flow(x)[Traversal.group_by(type)]"""
    def inner(seq: ActualIterable[T]) -> Dict[TR, List[T]]:
        ret = defaultdict(list)
        for each in seq:
            ret[fn(each)].append(each)
        return ret
    return inner

def get_most_severe_consequence(transcripts):
    """Get the most severe consequence

    Go through all transcripts and get the most severe consequence

    Args:
        transcripts (list): A list of transcripts to evaluate

    Returns:
        most_severe_consequence (str): The most severe consequence"""
    most_severe_consequence = None
    most_severe_score = None
    for transcript in transcripts:
        for consequence in transcript['consequence'].split('&'):
            logger.debug('Checking severity score for consequence: {0}'.format(consequence))
            severity_score = SEVERITY_DICT.get(consequence)
            logger.debug('Severity score found: {0}'.format(severity_score))
            if severity_score != None:
                if most_severe_score:
                    if severity_score < most_severe_score:
                        most_severe_consequence = consequence
                        most_severe_score = severity_score
                else:
                    most_severe_consequence = consequence
                    most_severe_score = severity_score
    return most_severe_consequence

