def get_header(vcf_file_path):
    """Parse the header and return a header object

    Args:
        vcf_file_path(str): Path to vcf

    Returns:
        head: A HeaderParser object"""
    logger.info('Parsing header of file {0}'.format(vcf_file_path))
    head = HeaderParser()
    handle = get_vcf_handle(infile=vcf_file_path)
    for line in handle:
        line = line.rstrip()
        if line.startswith('#'):
            if line.startswith('##'):
                head.parse_meta_data(line)
            else:
                head.parse_header_line(line)
        else:
            break
    handle.close()
    return head

def parse_time_range(start_dt, end_dt):
    """Convert the start/end datetimes specified by the user, specifically:
    - truncate any minutes/seconds
    - for a missing end time, use start + 24 hours
    - for a missing start time, use end - 24 hours
    - for missing start and end, use the last 24 hours"""
    now = datetime.now()
    if start_dt and (not end_dt):
        end_dt = now
    elif end_dt and (not start_dt):
        start_dt = _EARLIEST_DATE
    elif not start_dt and (not end_dt):
        end_dt = now
        start_dt = end_dt - timedelta(days=1)
    return tuple(map(truncate_hour_fraction, (start_dt, end_dt)))

def group(iterable, key):
    """groupby which sorts the input, discards the key and returns the output
    as a sequence of lists."""
    for _, grouped in groupby(sorted(iterable, key=key), key=key):
        yield list(grouped)

def aggregate_count(keyname):
    """Straightforward sum of the given keyname."""
    def inner(docs):
        return sum((doc[keyname] for doc in docs))
    return (keyname, inner)

def aggregate_rate(rate_key, count_key):
    """Compute an aggregate rate for `rate_key` weighted according to
    `count_rate`."""
    def inner(docs):
        total = sum((doc[count_key] for doc in docs))
        weighted_total = sum((doc[rate_key] * doc[count_key] for doc in docs))
        total_rate = weighted_total / total
        return total_rate
    return (rate_key, inner)

