def translate_purposes(f):
    """decorator to translate the purposes field.

    translate the values of the purposes field of the API response into
    translated values."""
    @wraps(f)
    def wr(r, pc):
        tmp = []
        for P in r['purposes']:
            try:
                tmp.append(POSTCODE_API_TYPEDEFS_PURPOSES[P])
            except:
                logger.warning("Warning: {}: cannot translate 'purpose': {}".format(pc, P))
                tmp.append(P)
        r.update({'purposes': tmp})
        return f(r, pc)
    return wr

def quantile(data, num_breaks):
    """Calculate quantile breaks.

    Arguments:
    data -- Array of values to classify.
    num_breaks -- Number of breaks to perform."""
    def scipy_mquantiles(a, prob=list([0.25, 0.5, 0.75]), alphap=0.4, betap=0.4, axis=None, limit=()):
        """function copied from scipy 0.13.3::scipy.stats.mstats.mquantiles"""
        def _quantiles1D(data, m, p):
            x = numpy.sort(data.compressed())
            n = len(x)
            if n == 0:
                return numpy.ma.array(numpy.empty(len(p), dtype=float), mask=True)
            elif n == 1:
                return numpy.ma.array(numpy.resize(x, p.shape), mask=numpy.ma.nomask)
            aleph = n * p + m
            k = numpy.floor(aleph.clip(1, n - 1)).astype(int)
            gamma = (aleph - k).clip(0, 1)
            return (1.0 - gamma) * x[(k - 1).tolist()] + gamma * x[k.tolist()]
        data = numpy.ma.array(a, copy=False)
        if data.ndim > 2:
            raise TypeError('Array should be 2D at most !')
        if limit:
            condition = (limit[0] < data) & (data < limit[1])
            data[~condition.filled(True)] = numpy.ma.masked
        p = numpy.array(prob, copy=False, ndmin=1)
        m = alphap + p * (1.0 - alphap - betap)
        if axis is None:
            return _quantiles1D(data, m, p)
        return numpy.ma.apply_along_axis(_quantiles1D, axis, data, m, p)
    return scipy_mquantiles(data, numpy.linspace(1.0 / num_breaks, 1, num_breaks))

def read(filename, **kwargs):
    """Read a generic input file into a recarray.
    Accepted file formats: [.fits,.fz,.npy,.csv,.txt,.dat]

    Parameters:
    filename : input file name
    kwargs   : keyword arguments for the reader
    Returns:
    recarray : data array"""
    base, ext = os.path.splitext(filename)
    if ext in ('.fits', '.fz'):
        return fitsio.read(filename, **kwargs)
    elif ext in '.npy':
        return np.load(filename, **kwargs)
    elif ext in '.csv':
        return np.recfromcsv(filename, **kwargs)
    elif ext in ('.txt', '.dat'):
        return np.genfromtxt(filename, **kwargs)
    msg = 'Unrecognized file type: %s' % filename
    raise ValueError(msg)

def write(filename, data, **kwargs):
    """Write a recarray to a specific format.
    Accepted file formats: [.fits,.fz,.npy,.csv,.txt,.dat]

    Parameters:
    filename : output file name
    data     : the recarray data
    kwargs   : keyword arguments for the writer
    Returns:
    ret      : writer return (usually None)"""
    base, ext = os.path.splitext(filename)
    if ext in ('.fits', '.fz'):
        return fitsio.write(filename, data, **kwargs)
    elif ext in '.npy':
        return np.save(filename, data, **kwargs)
    elif ext in '.csv':
        return np.savetxt(filename, data, header=','.join(data.dtype.names), delimiter=',', **kwargs)
    elif ext in ('.txt', '.dat'):
        return np.savetxt(filename, data, **kwargs)
    msg = 'Unrecognized file type: %s' % filename
    raise ValueError(msg)

def load_files(filenames, multiproc=False, **kwargs):
    """Load a set of FITS files with kwargs."""
    filenames = np.atleast_1d(filenames)
    logger.debug('Loading %s files...' % len(filenames))
    kwargs = [dict(filename=f, **kwargs) for f in filenames]
    if multiproc:
        from multiprocessing import Pool
        processes = multiproc if multiproc > 0 else None
        p = Pool(processes, maxtasksperchild=1)
        out = p.map(load_file, kwargs)
    else:
        out = [load_file(kw) for kw in kwargs]
    dtype = out[0].dtype
    for i, d in enumerate(out):
        if d.dtype != dtype:
            logger.warn('Casting input data to same type.')
            out[i] = d.astype(dtype, copy=False)
    logger.debug('Concatenating arrays...')
    return np.concatenate(out)

