def valid_address(address):
    """Determines whether the specified address string is valid."""
    if not address:
        return False
    components = str(address).split(':')
    if len(components) > 2 or not valid_hostname(components[0]):
        return False
    if len(components) == 2 and (not valid_port(components[1])):
        return False
    return True

def valid_hostname(host):
    """Returns whether the specified string is a valid hostname."""
    if len(host) > 255:
        return False
    if host[-1:] == '.':
        host = host[:-1]
    return all((_hostname_re.match(c) for c in host.split('.')))

def _count_citations(aux_file):
    """Counts the citations in an aux-file.

    @return: defaultdict(int) - {citation_name: number, ...}"""
    counter = defaultdict(int)
    with open(aux_file) as fobj:
        content = fobj.read()
    for match in CITE_PATTERN.finditer(content):
        name = match.groups()[0]
        counter[name] += 1
    return counter

def rec_append_fields(rec, names, arrs, dtypes=None):
    """Return a new record array with field names populated with data
    from arrays in *arrs*.  If appending a single field, then *names*,
    *arrs* and *dtypes* do not have to be lists. They can just be the
    values themselves."""
    if not isstring(names) and iterable(names) and len(names) and isstring(names[0]):
        if len(names) != len(arrs):
            raise ValueError('number of arrays do not match number of names')
    else:
        names = [names]
        arrs = [arrs]
    arrs = list(map(np.asarray, arrs))
    if dtypes is None:
        dtypes = [a.dtype for a in arrs]
    elif not iterable(dtypes):
        dtypes = [dtypes]
    if len(arrs) != len(dtypes):
        if len(dtypes) == 1:
            dtypes = dtypes * len(arrs)
        else:
            raise ValueError('dtypes must be None, a single dtype or a list')
    old_dtypes = rec.dtype.descr
    if six.PY2:
        old_dtypes = [(name.encode('utf-8'), dt) for name, dt in old_dtypes]
    newdtype = np.dtype(old_dtypes + list(zip(names, dtypes)))
    newrec = np.recarray(rec.shape, dtype=newdtype)
    for field in rec.dtype.fields:
        newrec[field] = rec[field]
    for name, arr in zip(names, arrs):
        newrec[name] = arr
    return newrec

def get_renderer_from_definition(config):
    """Returns a renderer object based on the configuration (as a dictionary)"""
    options = config.get('options', {})
    try:
        renderer_type = config['type']
        renderer_colors = [(float(x[0]), hex_to_color(x[1])) for x in config['colors']]
        fill_value = options.get('fill_value')
        if fill_value is not None:
            fill_value = float(fill_value)
    except KeyError:
        raise ValueError('Missing required keys from renderer configuration')
    renderer_kwargs = {'colormap': renderer_colors, 'fill_value': fill_value}
    if renderer_type == 'stretched':
        color_space = options.get('color_space', 'hsv').lower().strip()
        if not color_space in ('rgb', 'hsv'):
            raise ValueError('Invalid color space: {}'.format(color_space))
        renderer = StretchedRenderer(colorspace=color_space, **renderer_kwargs)
    elif renderer_type == 'classified':
        renderer = ClassifiedRenderer(**renderer_kwargs)
    elif renderer_type == 'unique':
        try:
            labels = [six.text_type(x) for x in options.get('labels', [])]
        except TypeError:
            raise ValueError('Labels option must be an array')
        renderer = UniqueValuesRenderer(labels=labels, **renderer_kwargs)
    return renderer

def get_definition_from_renderer(renderer):
    """Returns a dictionary definition of the given renderer"""
    config = {'colors': [[x[0], x[1].to_hex()] for x in renderer.colormap], 'options': {}}
    if renderer.fill_value:
        config['options']['fill_value'] = renderer.fill_value
    if isinstance(renderer, StretchedRenderer):
        config['type'] = 'stretched'
        config['options']['color_space'] = renderer.colorspace
    elif isinstance(renderer, UniqueValuesRenderer):
        config['type'] = 'unique'
        if renderer.labels:
            config['options']['labels'] = renderer.labels
    elif isinstance(renderer, ClassifiedRenderer):
        config['type'] = 'classified'
    else:
        raise ValueError('{0} is not a valid renderer type'.format(renderer.__class__.__name__))
    return config

def surveyPixel(lon, lat, nside_pix, nside_subpix=None):
    """Return the set of HEALPix pixels that cover the given coordinates at resolution nside.
    Optionally return the set of subpixels within those pixels at resolution nside_subpix"""
    pix = np.unique(ang2pix(nside_pix, lon, lat))
    if nside_subpix is None:
        return pix
    else:
        subpix_array = []
        for ii in range(0, len(pix)):
            subpix = subpixel(pix[ii], nside_pix, nside_subpix)
            subpix_array.append(subpix)
        return (pix, np.array(subpix_array))

