def add_dicts(d1, d2):
    """Merge two dicts of addable values"""
    if d1 is None:
        return d2
    if d2 is None:
        return d1
    keys = set(d1)
    keys.update(set(d2))
    ret = {}
    for key in keys:
        v1 = d1.get(key)
        v2 = d2.get(key)
        if v1 is None:
            ret[key] = v2
        elif v2 is None:
            ret[key] = v1
        else:
            ret[key] = v1 + v2
    return ret

def returned(n):
    """Generate a random walk and return True if the walker has returned to
    the origin after taking `n` steps."""
    for pos in randwalk() >> drop(1) >> takei(xrange(n - 1)):
        if pos == Origin:
            return True
    return False

def seq(start=0, step=1):
    """An arithmetic sequence generator.  Works with any type with + defined.

    >>> seq(1, 0.25) >> item[:10]
    [1, 1.25, 1.5, 1.75, 2.0, 2.25, 2.5, 2.75, 3.0, 3.25]"""
    def seq(a, d):
        while 1:
            yield a
            a += d
    return seq(start, step)

def reduce(function, initval=None):
    """Curried version of the built-in reduce.

    >>> reduce(lambda x,y: x+y)( [1, 2, 3, 4, 5] )
    15"""
    if initval is None:
        return lambda s: __builtin__.reduce(function, s)
    else:
        return lambda s: __builtin__.reduce(function, s, initval)

