def parse_reason(response, content):
    """Google return a JSON document describing the error. We should parse this
    and extract the error reason. See
    https://developers.google.com/analytics/devguides/reporting/core/v3/coreErrors"""
    def first_error(data):
        errors = data['error']['errors']
        if len(errors) > 1:
            logging.info('Received {} errors'.format(len(errors)))
        return errors[0]
    try:
        json_data = json.loads(content)
        return first_error(json_data)['reason']
    except:
        return response.reason

def sum_mags(mags, weights=None):
    """Sum an array of magnitudes in flux space.

    Parameters:
    -----------
    mags    : array of magnitudes
    weights : array of weights for each magnitude (i.e. from a pdf)

    Returns:
    --------
    sum_mag : the summed magnitude of all the stars"""
    flux = 10 ** (-np.asarray(mags) / 2.5)
    if weights is None:
        return -2.5 * np.log10(np.sum(flux))
    else:
        return -2.5 * np.log10(np.sum(weights * flux))

def Gregory(type=float):
    """Return partial sums of the Gregory series converging to atan(1) == pi/4.

    Yield 1 - 1/3 + 1/5 - 1/7 + ... computed with the given type."""
    return seq(type(1), step=2) >> map(lambda x: 1 / x) >> alt_sign >> fold(operator.add)

def Aitken(s):
    """Accelerate the convergence of the a series
    using Aitken's delta-squared process (SCIP calls it Euler)."""
    def accel():
        s0, s1, s2 = s >> item[:3]
        while 1:
            yield (s2 - (s2 - s1) ** 2 / (s0 - 2 * s1 + s2))
            s0, s1, s2 = (s1, s2, next(s))
    return accel()

