        imagefile = app.config.sphinxmark_image
        if app.config.html_static_path:
            staticpath = app.config.html_static_path[0]
        else:
            staticpath = '_static'
        LOG.debug('[sphinxmark] static path: ' + staticpath)
        imagepath = os.path.join(app.confdir, staticpath, imagefile)
        LOG.debug('[sphinxmark] Imagepath: ' + imagepath)
        try:
            copy(imagepath, buildpath)
        except Exception:
            message = "Cannot find '%s'. Put watermark images in the '_static' directory or specify the location using 'html_static_path'." % imagefile
            LOG.warning(message)
            LOG.warning('Failed to add watermark.')
            return
    return (buildpath, imagefile)

def gammalnStirling(z):
    """Uses Stirling's approximation for the log-gamma function suitable for large arguments."""
    return 0.5 * (np.log(2.0 * np.pi) - np.log(z)) + z * (np.log(z + 1.0 / (12.0 * z - 1.0 / (10.0 * z))) - 1.0)

def confidenceInterval(n, k, alpha=0.68, errorbar=False):
    """Given n tests and k successes, return efficiency and confidence interval."""
    try:
        e = float(k) / float(n)
    except ZeroDivisionError:
        return (np.nan, [np.nan, np.nan])
    bins = 1000001
    dx = 1.0 / bins
    efficiency = np.linspace(0, 1, bins)
    if n + 2 > 1000:
        a = gammalnStirling(n + 2)
    else:
        a = scipy.special.gammaln(n + 2)
    if k + 1 > 1000:
        b = gammalnStirling(k + 1)
    else:
        b = scipy.special.gammaln(k + 1)
    if n - k + 1 > 1000:
        c = gammalnStirling(n - k + 1)
    else:
        c = scipy.special.gammaln(n - k + 1)
    if k == 0:
        p = np.concatenate([[np.exp(a - b - c)], np.exp(a - b - c + k * np.log(efficiency[1:-1]) + (n - k) * np.log(1.0 - efficiency[1:-1])), [0.0]])
    elif k == n:
        p = np.concatenate([[0.0], np.exp(a - b - c + k * np.log(efficiency[1:-1]) + (n - k) * np.log(1.0 - efficiency[1:-1])), [np.exp(a - b - c)]])
    else:
        p = np.concatenate([[0.0], np.exp(a - b - c + k * np.log(efficiency[1:-1]) + (n - k) * np.log(1.0 - efficiency[1:-1])), [0.0]])
    i = np.argsort(p)[::-1]
    p_i = np.take(p, i)
    s = i[np.cumsum(p_i * dx) < alpha]
    low = min(np.min(s) * dx, e)
    high = max(np.max(s) * dx, e)
    if not errorbar:
        return (e, [low, high])
    else:
        return (e, [e - low, high - e])

def binomialInterval(n, k, alpha=0.68):
    """Given n tests and k successes, return efficiency and confidence interval."""
    e = float(k) / n
    delta_e = 1 / float(n) * np.sqrt(e * (1 - e) * float(n)) * alpha / 0.68
    return (e, [e - delta_e, e + delta_e])

def satellite(isochrone, kernel, stellar_mass, distance_modulus, **kwargs):
    """Wrapping the isochrone and kernel simulate functions."""
    mag_1, mag_2 = isochrone.simulate(stellar_mass, distance_modulus)
    lon, lat = kernel.simulate(len(mag_1))
    return (mag_1, mag_2, lon, lat)

def asscalar(a):
    """https://github.com/numpy/numpy/issues/4701"""
    try:
        return np.asscalar(a)
    except AttributeError as e:
        return np.asscalar(np.asarray(a))

def best_fit(li, value):
    """For a sorted list li, returns the closest item to value"""
    index = min(bisect_left(li, value), len(li) - 1)
    if index in (0, len(li)):
        return index
    if li[index] - value < value - li[index - 1]:
        return index
    else:
        return index - 1

def proj4_to_epsg(projection):
    """Attempts to convert a PROJ4 projection object to an EPSG code and returns None if conversion fails"""
    def make_definition(value):
        return {x.strip().lower() for x in value.split('+') if x}
    match = EPSG_RE.search(projection.srs)
    if match:
        return int(match.group(1))
    pyproj_data_dir = os.path.join(os.path.dirname(pyproj.__file__), 'data')
    pyproj_epsg_file = os.path.join(pyproj_data_dir, 'epsg')
    if os.path.exists(pyproj_epsg_file):
        definition = make_definition(projection.srs)
        f = open(pyproj_epsg_file, 'r')
        for line in f.readlines():
            match = PYPROJ_EPSG_FILE_RE.search(line)
            if match:
                file_definition = make_definition(match.group(2))
                if definition == file_definition:
                    return int(match.group(1))
    return None

def wkt_to_proj4(wkt):
    """Converts a well-known text string to a pyproj.Proj object"""
    srs = osgeo.osr.SpatialReference()
    srs.ImportFromWkt(wkt)
    return pyproj.Proj(str(srs.ExportToProj4()))

def proj4_to_wkt(projection):
    """Converts a pyproj.Proj object to a well-known text string"""
    srs = osgeo.osr.SpatialReference()
    srs.ImportFromProj4(projection.srs)
    return srs.ExportToWkt()

def superpixel(subpix, nside_subpix, nside_superpix):
    """Return the indices of the super-pixels which contain each of the sub-pixels."""
    if nside_subpix == nside_superpix:
        return subpix
    theta, phi = hp.pix2ang(nside_subpix, subpix)
    return hp.ang2pix(nside_superpix, theta, phi)

def u_grade_ipix(ipix, nside_in, nside_out, nest=False):
    """Return the indices of sub-pixels (resolution nside_subpix) within
    the super-pixel(s) (resolution nside_superpix).

    Parameters:
    -----------
    ipix      : index of the input superpixel(s)
    nside_in  : nside of the input superpixel
    nside_out : nside of the desired subpixels

    Returns:
    --------
    ipix_out : subpixels for each superpixel"""
    if nside_in == nside_out:
        return ipix
    if not nside_in < nside_out:
        raise ValueError('nside_in must be less than nside_out')
    if nest:
        nest_ipix = ipix
    else:
        nest_ipix = hp.ring2nest(nside_in, ipix)
    factor = (nside_out // nside_in) ** 2
    if np.isscalar(ipix):
        nest_ipix_out = factor * nest_ipix + np.arange(factor)
    else:
        nest_ipix_out = factor * np.asarray(nest_ipix)[:, np.newaxis] + np.arange(factor)
    if nest:
        return nest_ipix_out
    else:
        return hp.nest2ring(nside_out, nest_ipix_out)

def pix2ang(nside, pix, nest=False):
    """Return (lon, lat) in degrees instead of (theta, phi) in radians"""
    theta, phi = hp.pix2ang(nside, pix, nest=nest)
    lon = phi2lon(phi)
    lat = theta2lat(theta)
    return (lon, lat)

def ang2pix(nside, lon, lat, nest=False):
    """Input (lon, lat) in degrees instead of (theta, phi) in radians"""
    theta = np.radians(90.0 - lat)
    phi = np.radians(lon)
    return healpy.ang2pix(nside, theta, phi, nest=nest)

def ang2disc(nside, lon, lat, radius, inclusive=False, fact=4, nest=False):
    """Wrap `query_disc` to use lon, lat, and radius in degrees."""
    vec = ang2vec(lon, lat)
    return query_disc(nside, vec, radius, inclusive, fact, nest)

def resolve(path_or_address=None, address=None, *ignored):
    """Returns (path, address) based on consecutive optional arguments,
    [path] [address]."""
    if path_or_address is None or address is not None:
        return (path_or_address, address)
    path = None
    if split_address(path_or_address)[1] is not None:
        address = path_or_address
    else:
        path = path_or_address
    return (path, address)

def split_address(address):
    """Returns (host, port) with an integer port from the specified address
    string. (None, None) is returned if the address is invalid."""
    invalid = (None, None)
    if not address and address != 0:
        return invalid
    components = str(address).split(':')
    if len(components) > 2:
        return invalid
    if components[0] and (not valid_hostname(components[0])):
        return invalid
    if len(components) == 2 and (not valid_port(components[1])):
        return invalid
    if len(components) == 1:
        components.insert(0 if valid_port(components[0]) else 1, None)
    host, port = components
    port = int(port) if port else None
    return (host, port)

def translate_exception(exc, kwargs):
    """Translate a botocore.exceptions.ClientError into a dynamo3 error"""
    error = exc.response['Error']
    error.setdefault('Message', '')
    err_class = EXC.get(error['Code'], DynamoDBError)
    return err_class(exc.response['ResponseMetadata']['HTTPStatusCode'], exc_info=sys.exc_info(), args=pformat(kwargs), **error)

def inFootprint(footprint, ra, dec):
    """Check if set of ra,dec combinations are in footprint.
    Careful, input files must be in celestial coordinates.

    filename : Either healpix map or mangle polygon file
    ra,dec   : Celestial coordinates

    Returns:
    inside   : boolean array of coordinates in footprint"""
    if footprint is None:
        return np.ones(len(ra), dtype=bool)
    try:
        if isinstance(footprint, str) and os.path.exists(footprint):
            filename = footprint
            footprint = read_map(filename)
        nside = hp.npix2nside(len(footprint))
        pix = ang2pix(nside, ra, dec)
        inside = footprint[pix] > 0
    except IOError:
        logger.warning('Failed to load healpix footprint; trying to use mangle...')
        inside = inMangle(filename, ra, dec)
    return inside

def _get_query_params(query):
    """>>> _get_query_params({'query': {'a': 1, 'c': 3, 'b': 5}})
    'a=1 b=5 c=3'"""
    query_params = OrderedDict(sorted(query['query'].items()))
    return ' '.join(['{}={}'.format(k, v) for k, v in query_params.items()])

def make_extra_json_fields(args):
    """From the parsed command-line arguments, generate a dictionary of additional
    fields to be inserted into JSON logs (logstash_formatter module)"""
    extra_json_fields = {'data_group': _get_data_group(args.query), 'data_type': _get_data_type(args.query), 'data_group_data_type': _get_data_group_data_type(args.query), 'query': _get_query_params(args.query)}
    if 'path_to_json_file' in args.query:
        extra_json_fields['path_to_query'] = _get_path_to_json_file(args.query)
    return extra_json_fields

def parse_month_year(date_string):
    """>>> parse_month_year('01/10/2012')
    (10, 2012)"""
    match = re.match('\\d{2}/(?P<month>\\d{2})/(?P<year>\\d{4})$', date_string.lower())
    if not match:
        raise ValueError("Not format 'dd/mm/yyyy': '{}'".format(date_string))
    month = int(match.group('month'))
    year = int(match.group('year'))
    return (month, year)

def file_found(filename, force):
    """Check if a file exists"""
    if os.path.exists(filename) and (not force):
        logger.info('Found %s; skipping...' % filename)
        return True
    else:
        return False

def try_number(value):
    """Attempt to cast the string `value` to an int, and failing that, a float,
    failing that, raise a ValueError."""
    for cast_function in [int, float]:
        try:
            return cast_function(value)
        except ValueError:
            pass
    raise ValueError('Unable to use value as int or float: {0!r}'.format(value))

def convert_durations(metric):
    """Convert session duration metrics from seconds to milliseconds."""
    if metric[0] == 'avgSessionDuration' and metric[1]:
        new_metric = (metric[0], metric[1] * 1000)
    else:
        new_metric = metric
    return new_metric

def read_parameters(request, view_kwargs=None, capture_errors=False):
    """:param request: HttpRequest with attached api_info
    :type request: HttpRequest
    :type view_kwargs: dict[str, object]
    :type capture_errors: bool
    :rtype: dict[str, object]"""
    if view_kwargs is None:
        view_kwargs = {}
    params = {}
    errors = {}
    for param in request.api_info.operation.parameters:
        try:
            value = param.get_value(request, view_kwargs)
            if value is NO_VALUE:
                if param.has_default:
                    params[param.name] = param.default
                elif param.required:
                    errors[param.name] = MissingParameter('parameter %s is required but missing' % param.name)
                continue
            params[param.name] = param.cast(request.api_info.api, value)
        except (NotImplementedError, ImproperlyConfigured):
            raise
        except Exception as e:
            if not capture_errors:
                raise
            errors[param.name] = e
    if errors:
        raise ErroneousParameters(errors, params)
    return params

def float_to_decimal(f):
    """Convert a float to a 38-precision Decimal"""
    n, d = f.as_integer_ratio()
    numerator, denominator = (Decimal(n), Decimal(d))
    return DECIMAL_CONTEXT.divide(numerator, denominator)

def is_dynamo_value(value):
    """Returns True if the value is a Dynamo-formatted value"""
    if not isinstance(value, dict) or len(value) != 1:
        return False
    subkey = six.next(six.iterkeys(value))
    return subkey in TYPES_REV

def encode_set(dynamizer, value):
    """Encode a set for the DynamoDB format"""
    inner_value = next(iter(value))
    inner_type = dynamizer.raw_encode(inner_value)[0]
    return (inner_type + 'S', [dynamizer.raw_encode(v)[1] for v in value])

def encode_dict(dynamizer, value):
    """Encode a dict for the DynamoDB format"""
    encoded_dict = {}
    for k, v in six.iteritems(value):
        encoded_type, encoded_value = dynamizer.raw_encode(v)
        encoded_dict[k] = {encoded_type: encoded_value}
    return ('M', encoded_dict)

def world_to_image(bbox, size):
    """Function generator to create functions for converting from world coordinates to image coordinates"""
    px_per_unit = (float(size[0]) / bbox.width, float(size[1]) / bbox.height)
    return lambda x, y: ((x - bbox.xmin) * px_per_unit[0], size[1] - (y - bbox.ymin) * px_per_unit[1])

def try_get_department(department_or_code):
    """Try to take the first department code, or fall back to string as passed"""
    try:
        value = take_first_department_code(department_or_code)
    except AssertionError:
        value = department_or_code
    if value in DEPARTMENT_MAPPING:
        value = DEPARTMENT_MAPPING[value]
    return value

def _encode_write(dynamizer, data, action, key):
    """Encode an item write command"""
    data = dict(((k, dynamizer.encode(v)) for k, v in six.iteritems(data) if not is_null(v)))
    return {action: {key: data}}

def encode_query_kwargs(dynamizer, kwargs):
    """Encode query constraints in Dynamo format"""
    ret = {}
    for k, v in six.iteritems(kwargs):
        if '__' not in k:
            raise TypeError("Invalid query argument '%s'" % k)
        name, condition_key = k.split('__')
        if condition_key == 'eq' and is_null(v):
            condition_key = 'null'
            v = True
        if condition_key == 'null':
            ret[name] = {'ComparisonOperator': 'NULL' if v else 'NOT_NULL'}
            continue
        elif condition_key not in ('in', 'between'):
            v = (v,)
        ret[name] = {'AttributeValueList': [dynamizer.encode(value) for value in v], 'ComparisonOperator': CONDITIONS[condition_key]}
    return ret

def interval(best, lo=np.nan, hi=np.nan):
    """Pythonized interval for easy output to yaml"""
    return [float(best), [float(lo), float(hi)]]

def mean_interval(data, alpha=_alpha):
    """Interval assuming gaussian posterior."""
    mean = np.mean(data)
    sigma = np.std(data)
    scale = scipy.stats.norm.ppf(1 - alpha / 2.0)
    return interval(mean, mean - scale * sigma, mean + scale * sigma)

def median_interval(data, alpha=_alpha):
    """Median including bayesian credible interval."""
    q = [100 * alpha / 2.0, 50, 100 * (1 - alpha / 2.0)]
    lo, med, hi = np.percentile(data, q)
    return interval(med, lo, hi)

def build_expected(dynamizer, expected):
    """Build the Expected parameters from a dict"""
    ret = {}
    for k, v in six.iteritems(expected):
        if is_null(v):
            ret[k] = {'Exists': False}
        else:
            ret[k] = {'Exists': True, 'Value': dynamizer.encode(v)}
    return ret

def build_expression_values(dynamizer, expr_values, kwargs):
    """Build ExpresionAttributeValues from a value or kwargs"""
    if expr_values:
        values = expr_values
        return dynamizer.encode_keys(values)
    elif kwargs:
        values = dict(((':' + k, v) for k, v in six.iteritems(kwargs)))
        return dynamizer.encode_keys(values)

def letter_scales(counts):
    """Convert letter counts to frequencies, sorted increasing."""
    try:
        scale = 1.0 / sum(counts.values())
    except ZeroDivisionError:
        return []
    freqs = [(aa, cnt * scale) for aa, cnt in counts.iteritems() if cnt]
    freqs.sort(key=lambda pair: pair[1])
    return freqs

def register(func=None, name=None):
    """Expose compiler to factory.

    :param func: the callable to expose
    :type func: callable
    :param name: name of format
    :type name: str

    It can be used as a decorator::

        @register(name='my:validator')
        def my_validator(obj):
            if obj is True:
                return obj
            raise ValidationError('obj is not true')

    or as a function::

        def my_validator(obj):
            if obj is True:
                return obj
            raise ValidationError('obj is not true')

        @register(name='my:validator')"""
    if not name:
        raise CompilationError('Name is required')
    if not func:
        return partial(register, name=name)
    return FormatRegistry.register(name, func)

