def register(compiler=None, spec=None):
    """Expose compiler to factory.

    :param compiler: the callable to expose
    :type compiler: callable
    :param spec: name of the spec
    :type spec: str

    It can be used as a decorator::

        @register(spec='my:first:spec')
        def my_compiler(schema, pointer, context):
            return Validator(schema)

    or as a function::

        def my_compiler(schema, pointer, context):
            return Validator(schema)

        register(my_compiler, 'my:second:spec')"""
    if not spec:
        raise CompilationError('Spec is required')
    if not compiler:
        return partial(register, spec=spec)
    return Factory.register(spec, compiler)

def identity_abs(aseq, bseq):
    """Compute absolute identity (# matching sites) between sequence strings."""
    assert len(aseq) == len(bseq)
    return sum((a == b for a, b in zip(aseq, bseq) if not (a in '-.' and b in '-.')))

def generate_rfc3339(d, local_tz=True):
    """generate rfc3339 time format
    input :
    d = date type
    local_tz = use local time zone if true,
    otherwise mark as utc

    output :
    rfc3339 string date format. ex : `2008-04-02T20:00:00+07:00`"""
    try:
        if local_tz:
            d = datetime.datetime.fromtimestamp(d)
        else:
            d = datetime.datetime.utcfromtimestamp(d)
    except TypeError:
        pass
    if not isinstance(d, datetime.date):
        raise TypeError('Not timestamp or date object. Got %r.' % type(d))
    if not isinstance(d, datetime.datetime):
        d = datetime.datetime(*d.timetuple()[:3])
    return '%04d-%02d-%02dT%02d:%02d:%02d%s' % (d.year, d.month, d.day, d.hour, d.minute, d.second, _generate_timezone(d, local_tz))

def _calculate_offset(date, local_tz):
    """input :
    date : date type
    local_tz : if true, use system timezone, otherwise return 0

    return the date of UTC offset.
    If date does not have any timezone info, we use local timezone,
    otherwise return 0"""
    if local_tz:
        if date.year < 1970:
            t = time.mktime(date.replace(year=1972).timetuple)
        else:
            t = time.mktime(date.timetuple())
        if time.localtime(t).tm_isdst:
            return -time.altzone
        else:
            return -time.timezone
    else:
        return 0

def _generate_timezone(date, local_tz):
    """input :
    date : date type
    local_tz : bool

    offset generated from _calculate_offset
    offset in seconds
    offset = 0 -> +00:00
    offset = 1800 -> +00:30
    offset = -3600 -> -01:00"""
    offset = _calculate_offset(date, local_tz)
    hour = abs(offset) // 3600
    minute = abs(offset) % 3600 // 60
    if offset < 0:
        return '%c%02d:%02d' % ('-', hour, minute)
    else:
        return '%c%02d:%02d' % ('+', hour, minute)

def format_output(func):
    return func
    '\n    Format output.\n    '
    @wraps(func)
    def wrapper(*args, **kwargs):
        try:
            response = func(*args, **kwargs)
        except Exception as error:
            print(colored(error, 'red'), file=sys.stderr)
            sys.exit(1)
        else:
            print(response)
            sys.exit(0)
    return wrapper

def uniqueof20(k, rep=10000):
    """Sample k times out of alphabet, how many different?"""
    alphabet = 'ACDEFGHIKLMNPQRSTVWY'
    reps = [len(set((random.choice(alphabet) for i in range(k)))) for j in range(rep)]
    return sum(reps) / len(reps)

def aa_counts(aln, weights=None, gap_chars='-.'):
    """Calculate the amino acid frequencies in a set of SeqRecords.

    Weights for each sequence in the alignment can be given as a list/tuple,
    usually calculated with the sequence_weights function. For convenience, you
    can also pass "weights=True" and the weights will be calculated with
    sequence_weights here."""
    if weights is None:
        counts = Counter()
        for rec in aln:
            seq_counts = Counter(str(rec.seq))
            counts.update(seq_counts)
    else:
        if weights == True:
            weights = sequence_weights(aln)
        else:
            assert len(weights) == len(aln), 'Length mismatch: weights = %d, alignment = %d' % (len(weights), len(aln))
        counts = defaultdict(float)
        for col in zip(*aln):
            for aa, wt in zip(col, weights):
                counts[aa] += wt
    for gap_char in gap_chars:
        if gap_char in counts:
            del counts[gap_char]
    return counts

def aa_frequencies(aln, weights=None, gap_chars='-.'):
    """Frequency of each residue type in an alignment.

    Alignment is a MultipleSeqAlignment or iterable of SeqRecords."""
    counts = aa_counts(aln, weights, gap_chars)
    scale = 1.0 / sum(counts.values())
    return dict(((aa, cnt * scale) for aa, cnt in counts.iteritems()))

def blocks(aln, threshold=0.5, weights=None):
    """Remove gappy columns from an alignment."""
    assert len(aln)
    if weights == False:
        def pct_nongaps(col):
            return 1 - float(col.count('-')) / len(col)
    else:
        if weights in (None, True):
            weights = sequence_weights(aln, 'avg1')
        def pct_nongaps(col):
            assert len(col) == len(weights)
            ngaps = sum((wt * (c == '-') for wt, c in zip(weights, col)))
            return 1 - ngaps / len(col)
    seqstrs = [str(rec.seq) for rec in aln]
    clean_cols = [col for col in zip(*seqstrs) if pct_nongaps(col) >= threshold]
    alphabet = aln[0].seq.alphabet
    clean_seqs = [Seq(''.join(row), alphabet) for row in zip(*clean_cols)]
    clean_recs = []
    for rec, seq in zip(aln, clean_seqs):
        newrec = deepcopy(rec)
        newrec.seq = seq
        clean_recs.append(newrec)
    return MultipleSeqAlignment(clean_recs, alphabet=alphabet)

def col_counts(col, weights=None, gap_chars='-.'):
    """Absolute counts of each residue type in a single column."""
    cnt = defaultdict(float)
    for aa, wt in zip(col, weights):
        if aa not in gap_chars:
            cnt[aa] += wt
    return cnt

def col_frequencies(col, weights=None, gap_chars='-.'):
    """Frequencies of each residue type (totaling 1.0) in a single column."""
    counts = col_counts(col, weights, gap_chars)
    scale = 1.0 / sum(counts.values())
    return dict(((aa, cnt * scale) for aa, cnt in counts.iteritems()))

def siteblock(parser, token):
    """Two notation types are acceptable:

    1. Two arguments:
       {% siteblock "myblock" %}
       Used to render "myblock" site block.

    2. Four arguments:
       {% siteblock "myblock" as myvar %}
       Used to put "myblock" site block into "myvar" template variable.
    """
    tokens = token.split_contents()
    tokens_num = len(tokens)
    if tokens_num not in (2, 4):
        raise template.TemplateSyntaxError('%r tag requires two or four arguments. E.g.: {%% siteblock "myblock" %%} or {%% siteblock "myblock" as myvar %%}.' % tokens[0])
    block_alias = parser.compile_filter(tokens[1])
    as_var = None
    tokens = tokens[2:]
    if len(tokens) >= 2 and tokens[-2] == 'as':
        as_var = tokens[-1]
    return siteblockNode(block_alias, as_var)

def _is_variable_extends(extend_node):
    """Check whether an ``{% extends variable %}`` is used in the template.

    :type extend_node: ExtendsNode"""
    if django.VERSION < (1, 4):
        return extend_node.parent_name_expr
    else:
        return not isinstance(extend_node.parent_name.var, six.string_types)

def _extend_blocks(extend_node, blocks, context):
    """Extends the dictionary `blocks` with *new* blocks in the parent node (recursive)

    :param extend_node: The ``{% extends .. %}`` node object.
    :type extend_node: ExtendsNode
    :param blocks: dict of all block names found in the template.
    :type blocks: dict"""
    try:
        parent = extend_node.get_parent(_get_extend_context(context))
    except TemplateSyntaxError:
        if _is_variable_extends(extend_node):
            return
        else:
            raise
    for parent_block in parent.nodelist.get_nodes_by_type(BlockNode):
        if not parent_block.name in blocks:
            blocks[parent_block.name] = parent_block
        else:
            block = blocks[parent_block.name]
            seen_supers = []
            while hasattr(block.parent, 'nodelist') and block.parent not in seen_supers:
                seen_supers.append(block.parent)
                block = block.parent
            block.parent = parent_block
    parent_extends = parent.nodelist.get_nodes_by_type(ExtendsNode)
    if parent_extends:
        _extend_blocks(parent_extends[0], blocks, context)

def intersect_keys(keys, reffile, cache=False, clean_accs=False):
    """Extract SeqRecords from the index by matching keys.

    keys - an iterable of sequence identifiers/accessions to select
    reffile - name of a FASTA file to extract the specified sequences from
    cache - save an index of the reference FASTA sequence offsets to disk?
    clean_accs - strip HMMer extensions from sequence accessions?"""
    index = None
    if cache:
        refcache = reffile + '.sqlite'
        if os.path.exists(refcache):
            if os.stat(refcache).st_mtime < os.stat(reffile).st_mtime:
                logging.warn('Outdated cache; rebuilding index')
            else:
                try:
                    index = SeqIO.index_db(refcache, key_function=clean_accession) if clean_accs else SeqIO.index_db(refcache)
                except Exception:
                    logging.warn('Skipping corrupted cache; rebuilding index')
                    index = None
    else:
        refcache = ':memory:'
    if index is None:
        index = SeqIO.index_db(refcache, [reffile], 'fasta', key_function=clean_accession) if clean_accs else SeqIO.index_db(refcache, [reffile], 'fasta')
    if clean_accs:
        keys = (clean_accession(k) for k in keys)
    for key in keys:
        try:
            record = index[key]
        except LookupError:
            logging.info('No match: %s', repr(key))
            continue
        yield record

def aa_frequencies(seq, gap_chars='-.'):
    """Calculate the amino acid frequencies in a sequence set."""
    aa_counts = Counter(seq)
    for gap_char in gap_chars:
        if gap_char in aa_counts:
            del aa_counts[gap_char]
    scale = 1.0 / sum(aa_counts.values())
    return dict(((aa, cnt * scale) for aa, cnt in aa_counts.iteritems()))

def rfc3339_to_datetime(data):
    """convert a rfc3339 date representation into a Python datetime"""
    try:
        ts = time.strptime(data, '%Y-%m-%d')
        return date(*ts[:3])
    except ValueError:
        pass
    try:
        dt, _, tz = data.partition('Z')
        if tz:
            tz = offset(tz)
        else:
            tz = offset('00:00')
        if '.' in dt and dt.rsplit('.', 1)[-1].isdigit():
            ts = time.strptime(dt, '%Y-%m-%dT%H:%M:%S.%f')
        else:
            ts = time.strptime(dt, '%Y-%m-%dT%H:%M:%S')
        return datetime(*ts[:6], tzinfo=tz)
    except ValueError:
        raise ValueError('date-time {!r} is not a valid rfc3339 date representation'.format(data))

def log_config(verbose=1):
    """Set up logging the way I like it."""
    if verbose == 0:
        level = logging.WARNING
        fmt = '%(module)s: %(message)s'
    elif verbose == 1:
        level = logging.INFO
        fmt = '%(module)s [@%(lineno)s]: %(message)s'
    else:
        level = logging.DEBUG
        fmt = '%(module)s [%(lineno)s]: %(levelname)s: %(message)s'
    logging.basicConfig(format=fmt, level=level)

def chunker(l, n):
    """Generates n-sized chunks from the list l"""
    for i in ranger(0, len(l), n):
        yield l[i:i + n]

def val_factory(val, datatypes):
    """return an instance of `val` that is of type `datatype`.
    keep track of exceptions so we can produce meaningful error messages."""
    exceptions = []
    for dt in datatypes:
        try:
            if isinstance(val, dt):
                return val
            return type_handler_object(val, dt)
        except Exception as e:
            exceptions.append(str(e))
    raise ValueError('val_factory: Unable to instantiate {val} from types {types}. Exceptions: {excs}'.format(val=val, types=datatypes, excs=exceptions))

def to_dict(cls, convert_datetime=True):
    """return a dict representation of the Event and its sub-objects
    `convert_datetime` controls whether datetime objects are converted to strings or not
    :rtype: dict"""
    def todict(obj):
        """recurse the objects and represent as a dict
        use the registered handlers if possible"""
        data = {}
        if isinstance(obj, dict):
            for key, val in obj.items():
                data[key] = todict(val)
            return data
        if not convert_datetime and isinstance(obj, datetime):
            return obj
        elif type_handler_value(obj):
            return type_handler_value(obj)
        elif isinstance(obj, collections.Sequence) and (not isinstance(obj, basestring)):
            return [todict(v) for v in obj]
        elif hasattr(obj, '__dict__'):
            for key, value in obj.__dict__.items():
                if not callable(value) and (not key.startswith('_')):
                    data[key] = todict(value)
            return data
        else:
            return obj
    return todict(cls)

def handler_for(obj):
    """return the handler for the object type"""
    for handler_type in handlers:
        if isinstance(obj, handler_type):
            return handlers[handler_type]
    try:
        for handler_type in handlers:
            if issubclass(obj, handler_type):
                return handlers[handler_type]
    except TypeError:
        pass

def type_handler_object(val, objtype):
    """return the deserialized (restored) value from the registered handler for the type"""
    handler = handlers.get(objtype)
    if handler:
        return handler().restore(val)
    else:
        return objtype(val)

def validate_args(f):
    """Ensures that *args consist of a consistent type

    :param f: any client method with *args parameter
    :return: function f"""
    def wrapper(self, args):
        arg_types = set([type(arg) for arg in args])
        if len(arg_types) > 1:
            raise TypeError('Mixed input types are not allowed')
        elif list(arg_types)[0] not in (dict, str):
            raise TypeError('Only dict and str types accepted')
        return f(self, args)
    return wrapper

def truncate_args(f):
    """Ensures that *args do not exceed a set limit or are truncated to meet that limit

    :param f: any Client method with *args parameter
    :return: function f"""
    def wrapper(self, args):
        if len(args) > 100:
            if self.truncate_addresses:
                args = args[:100]
            else:
                raise ValueError('This exceeds 100 address at a time SmartyStreets limit')
        return f(self, args)
    return wrapper

def stringify(data):
    """Ensure all values in the dictionary are strings, except for the value for `candidate` which
    should just be an integer.

    :param data: a list of addresses in dictionary format
    :return: the same list with all values except for `candidate` count as a string"""
    def serialize(k, v):
        if k == 'candidates':
            return int(v)
        if isinstance(v, numbers.Number):
            if k == 'zipcode':
                return str(v).zfill(5)
            return str(v)
        return v
    return [{k: serialize(k, v) for k, v in json_dict.items()} for json_dict in data]

def stage(obj, parent=None, member=None):
    """Prepare obj to be staged.

    This is almost used for relative JSON Pointers."""
    obj = Staged(obj, parent, member)
    if isinstance(obj, Mapping):
        for key, value in obj.items():
            stage(value, obj, key)
    elif isinstance(obj, Sequence) and (not isinstance(obj, string_types)):
        for index, value in enumerate(obj):
            stage(value, obj, index)
    elif isinstance(obj, Set):
        for value in obj:
            stage(value, obj, None)
    return obj

def splitext(filename):
    """Return the filename and extension according to the first dot in the filename.
    This helps date stamping .tar.bz2 or .ext.gz files properly."""
    index = filename.find('.')
    if index == 0:
        index = 1 + filename[1:].find('.')
    if index == -1:
        return (filename, '')
    return (filename[:index], filename[index:])
    return os.path.splitext(filename)

def _read_style(style):
    """Deal with different style format (str, list, tuple)"""
    if isinstance(style, string_types):
        style = [style]
    else:
        style = list(style)
    return style

def supported(aln):
    """Get only the supported consensus residues in each column.

    Meaning:
    - Omit majority-gap columns
    - Omit columns where no residue type appears more than once
    - In case of a tie, return all the top-scoring residue types
      (no prioritization)

    Returns a *list* -- not a string! -- where elements are strings of the
    consensus character(s), potentially a gap ('-') or multiple chars ('KR')."""
    def col_consensus(columns):
        """Calculate the consensus chars for an iterable of columns."""
        for col in columns:
            if col.count('-') >= len(col) / 2 or all((c.islower() for c in col if c not in '.-')):
                yield '-'
                continue
            if any((c.islower() for c in col)):
                logging.warn('Mixed lowercase and uppercase letters in a column: ' + ''.join(col))
                col = map(str.upper, col)
            most_common = Counter([c for c in col if c not in '-']).most_common()
            if not most_common:
                logging.warn('Column is all gaps! How did that happen?')
            if most_common[0][1] == 1:
                yield '-'
            elif len(most_common) > 1 and most_common[0][1] == most_common[1][1]:
                ties = [x[0] for x in most_common if x[1] == most_common[0][1]]
                yield ''.join(ties)
            else:
                yield most_common[0][0]
    return list(col_consensus(zip(*aln)))

def detect_clause(parser, clause_name, tokens, as_filter_expr=True):
    """Helper function detects a certain clause in tag tokens list.
    Returns its value."""
    if clause_name in tokens:
        t_index = tokens.index(clause_name)
        clause_value = tokens[t_index + 1]
        if as_filter_expr:
            clause_value = parser.compile_filter(clause_value)
        del tokens[t_index:t_index + 2]
    else:
        clause_value = None
    return clause_value

def normpath(path):
    """Normalize a path.

    Expands ~'s, resolves relative paths, normalizes and returns
    an absolute path."""
    return os.path.abspath(os.path.normpath(os.path.expanduser(path)))

def splitter(iterable, chunksize=60):
    """Split an iterable that supports indexing into chunks of 'chunksize'."""
    return (iterable[0 + i:chunksize + i] for i in range(0, len(iterable), chunksize))

def chisqprob(x, df):
    """Probability value (1-tail) for the Chi^2 probability distribution.

    Broadcasting rules apply.

    Parameters
    ----------
    x : array_like or float > 0

    df : array_like or float, probably int >= 1

    Returns
    -------
    chisqprob : ndarray
        The area from `chisq` to infinity under the Chi^2 probability
        distribution with degrees of freedom `df`."""
    if x <= 0:
        return 1.0
    if x == 0:
        return 0.0
    if df <= 0:
        raise ValueError('Domain error.')
    if x < 1.0 or x < df:
        return 1.0 - _igam(0.5 * df, 0.5 * x)
    return _igamc(0.5 * df, 0.5 * x)

def shrink(image, apikey):
    """To shrink a PNG image, post the data to the API service.
    The response is a JSON message.
    The initial request must be authorized with HTTP Basic authorization.

    @param image: PNG image bytes sequence
    @param apikey: TinyPNG API key
    @param filename: filename of input file"""
    def _handle_response(response):
        body = json.loads(response.read())
        if response.code == TinyPNGResponse.SUCCESS_CODE:
            body['location'] = response.headers.getheader('Location')
            try:
                body['bytes'] = urlopen(body['location']).read()
            except:
                body['bytes'] = None
        return (response.code, body)
    auth = b64encode(bytes('api:' + apikey)).decode('ascii')
    request = Request(TINYPNG_SHRINK_URL, image)
    request.add_header('Authorization', 'Basic %s' % auth)
    try:
        response = urlopen(request)
        code, response_dict = _handle_response(response)
    except HTTPError as e:
        code, response_dict = _handle_response(e)
    return TinyPNGResponse(code, **response_dict)

def extract_number(text):
    """Extract digit character from text.
    """
    result = list()
    chunk = list()
    valid_char = set('.1234567890')
    for char in text:
        if char in valid_char:
            chunk.append(char)
        else:
            result.append(''.join(chunk))
            chunk = list()
    result.append(''.join(chunk))
    result_new = list()
    for number in result:
        if '.' in number:
            try:
                result_new.append(float(number))
            except:
                pass
        else:
            try:
                result_new.append(int(number))
            except:
                pass
    return result_new

def extract_email(text):
    """Extract email from text.
    """
    result = list()
    for tp in re.findall(_regex_extract_email, text.lower()):
        for email in tp:
            if re.match(_regex_validate_email, email):
                result.append(email)
    return result

def files_with_exts(root='.', suffix=''):
    """Returns generator that contains filenames
    from root directory and ends with suffix"""
    return (os.path.join(rootdir, filename) for rootdir, dirnames, filenames in os.walk(root) for filename in filenames if filename.endswith(suffix))

def find_apikey():
    """Finds TinyPNG API key

    Search for api key in following order:
     - environment variable TINYPNG_APIKEY
     - environment variable TINYPNG_API_KEY
     - file in local directory tinypng.key
     - file in home directory ~/.tinypng.key

    If key not found returns None"""
    env_keys = ['TINYPNG_APIKEY', 'TINYPNG_API_KEY']
    paths = []
    paths.append(os.path.join(os.path.abspath('.'), 'tinypng.key'))
    paths.append(os.path.expanduser('~/.tinypng.key'))
    for env_key in env_keys:
        if os.environ.get(env_key):
            return os.environ.get(env_key)
    for path in paths:
        if os.path.exists(path):
            return open(path, 'rt').read().strip()
    return None

def list_(*, cursor: str=None, exclude_archived: bool=None, exclude_members: bool=None, limit: int=None) -> snug.Query[Page[t.List[Channel]]]:
    """list all channels"""
    kwargs = {'exclude_archived': exclude_archived, 'exclude_members': exclude_members, 'limit': limit}
    response = (yield {'cursor': cursor, **kwargs})
    try:
        next_cursor = response['response_metadata']['next_cursor']
    except KeyError:
        next_query = None
    else:
        next_query = list_(**kwargs, cursor=next_cursor)
    return Page(load_channel_list(response['channels']), next_query=next_query)

