def determine_format(data, extension=None):
    """Determine the format of an audio file.

    Parameters:
            data (bytes-like object, str, os.PathLike, or file-like object):
                    A bytes-like object, filepath, path-like object
                    or file-like object of an audio file.
            extension (str): The file extension of the file.
                    Used as a tie-breaker for formats that can
                    be used in multiple containers (e.g. ID3)."""
    if isinstance(data, (os.PathLike, str)):
        data = open(data, 'rb')
    data_reader = DataReader(data)
    data_reader.seek(0, os.SEEK_SET)
    d = data_reader.read(4)
    if d.startswith((b'ID3', b'\xff\xfb')):
        if extension is None or extension.endswith('.mp3'):
            return MP3
    if d.startswith((b'fLaC', b'ID3')):
        if extension is None or extension.endswith('.flac'):
            return FLAC
    if d.startswith(b'RIFF'):
        if extension is None or extension.endswith('.wav'):
            return WAV
    return None

def load(f):
    """Load audio metadata from filepath or file-like object.

    Parameters:
            f (str, os.PathLike, or file-like object):
                    A filepath, path-like object or file-like object of an audio file.

    Returns:
            Format: An audio format object.

    Raises:
            UnsupportedFormat: If file is not of a supported format.
            ValueError: If filepath/file-like object is not valid or readable."""
    if isinstance(f, (os.PathLike, str)):
        fileobj = open(f, 'rb')
    else:
        try:
            f.read(0)
        except AttributeError:
            raise ValueError('Not a valid file-like object.')
        except Exception:
            raise ValueError("Can't read from file-like object.")
        fileobj = f
    parser_cls = determine_format(fileobj, os.path.splitext(fileobj.name)[1])
    if parser_cls is None:
        raise UnsupportedFormat('Supported format signature not found.')
    else:
        fileobj.seek(0, os.SEEK_SET)
    return parser_cls.load(fileobj)

def _urllib_send(opener, req, **kwargs):
    """Send a request with an :mod:`urllib` opener"""
    if req.content and (not any((h.lower() == 'content-type' for h in req.headers))):
        req = req.with_headers({'Content-Type': 'application/octet-stream'})
    url = req.url + '?' + urlencode(req.params)
    raw_req = urllib_request.Request(url, req.content, headers=req.headers)
    set_urllib_method(raw_req, req.method)
    try:
        res = opener.open(raw_req, **kwargs)
    except urllib_http_error_cls as http_err:
        res = http_err
    return Response(res.getcode(), content=res.read(), headers=res.headers)

def lines_stats(dir_path, file_filter):
    """Lines count of selected files under a directory.

    :return n_files: number of files
    :return n_lines: number of lines"""
    n_files = 0
    n_lines = 0
    for p in Path(dir_path).select_file(file_filter):
        n_files += 1
        n_lines += count_lines(p.abspath)
    return (n_files, n_lines)

def SplitString(value):
    """simple method that puts in spaces every 10 characters"""
    string_length = len(value)
    chunks = int(string_length / 10)
    string_list = list(value)
    lstring = ''
    if chunks > 1:
        lstring = '\\markup { \n\r \\column { '
        for i in range(int(chunks)):
            lstring += '\n\r\r \\line { "'
            index = i * 10
            for i in range(index):
                lstring += string_list[i]
            lstring += '" \r\r}'
        lstring += '\n\r } \n }'
    if lstring == '':
        indexes = [i for i in range(len(string_list)) if string_list[i] == '\r' or string_list[i] == '\n']
        lstring = '\\markup { \n\r \\column { '
        if len(indexes) == 0:
            lstring += '\n\r\r \\line { "' + ''.join(string_list) + '" \n\r\r } \n\r } \n }'
        else:
            rows = []
            row_1 = string_list[:indexes[0]]
            rows.append(row_1)
            for i in range(len(indexes)):
                start = indexes[i]
                if i != len(indexes) - 1:
                    end = indexes[i + 1]
                else:
                    end = len(string_list)
                row = string_list[start:end]
                rows.append(row)
            for row in rows:
                lstring += '\n\r\r \\line { "'
                lstring += ''.join(row)
                lstring += '" \r\r}'
            lstring += '\n\r } \n }'
    return lstring

def GetID(attrs, tag, val):
    """handy method which pulls out a nested id: attrs refers to a dictionary holding the id
    tag refers to the tag we're looking at (e.g measure, part etc)
    val refers to the exact index of the tag we're looking for (e.g number, id etc)
    example case: attrs = self.attribs, tag=measure and val=number would
    return current measure number"""
    if tag in attrs:
        if val in attrs[tag]:
            return attrs[tag][val]

def NumbersToWords(number):
    """little function that converts numbers to words. This could be more efficient,
    and won't work if the number is bigger than 999 but it's for stave names,
    and I doubt any part would have more than 10 staves let alone 999."""
    units = ['one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine']
    tens = ['ten', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety']
    output = ''
    if number != 0:
        str_val = str(number)
        if 4 > len(str_val) > 2:
            output += units[int(str_val[0]) - 1]
            output += 'hundred'
            if str_val[1] != 0:
                output += 'and' + tens[int(str_val[1]) - 1]
                if str_val[2] != 0:
                    output += units[int(str_val[2]) - 1]
        if 3 > len(str_val) > 1:
            output += tens[int(str_val[0]) - 1]
            if str_val[1] != 0:
                output += units[int(str_val[1]) - 1]
        if 2 > len(str_val) == 1:
            output += units[int(str_val[0]) - 1]
    else:
        output = 'zero'
    return output

def BackwardSearch(cls_type, node, index, depth=0, start_index=0):
    """Helper method which backwards-recursively searches for objects
    :param cls_type: class type of the object we are in search of
    :param node: object instance to start at
    :param index: number of the object to look for e.g <cls_type> num 1
    :param depth: current depth in the tree
    :param start_index: index to start with in children
    :return: object <index> of <cls_type>"""
    counter = depth
    if isinstance(node, cls_type):
        counter += 1
        if counter == index:
            return node
    if node is None:
        return None
    else:
        children = node.GetChildrenIndexes()
        if len(children) == 0 and isinstance(node, cls_type):
            return counter
        else:
            children.reverse()
            for child in children:
                result = Search(cls_type, node.GetChild(child), index, depth=counter)
                if isinstance(result, int):
                    counter = result
                    if counter == index:
                        return node.GetChild(child)
                if isinstance(result, cls_type):
                    return result
            if isinstance(node, cls_type):
                if counter == index:
                    return node
                else:
                    return counter

def handle_errors(resp):
    """raise a descriptive exception on a "bad request" response"""
    if resp.status_code == 400:
        raise ApiException(json.loads(resp.content).get('message'))
    return resp

def _process_file(input_file, output_file, apikey):
    """Shrinks input_file to output_file.

    This function should be used only inside process_directory.
    It takes input_file, tries to shrink it and if shrink was successful
    save compressed image to output_file. Otherwise raise exception.

    @return compressed: PNGResponse"""
    bytes_ = read_binary(input_file)
    compressed = shrink(bytes_, apikey)
    if compressed.success and compressed.bytes:
        write_binary(output_file, compressed.bytes)
    elif compressed.errno in FATAL_ERRORS:
        raise StopProcessing(compressed)
    elif compressed.errno == TinyPNGError.InternalServerError:
        raise RetryProcessing(compressed)
    return compressed

def dev_random_entropy(numbytes, fallback_to_urandom=True):
    """Reads random bytes from the /dev/random entropy pool.

    NOTE: /dev/random is a blocking pseudorandom number generator.
    If the entropy pool runs out, this function will block until more
    environmental noise is gathered.
    If entropy re-use is unnacceptable use this over "dev_urandom_entropy".

    If "fallback_to_urandom" is set, this function will fallback to
    /dev/urandom on operating systems without /dev/random."""
    if os.name == 'nt' and fallback_to_urandom:
        return dev_urandom_entropy(numbytes)
    return open('/dev/random', 'rb').read(numbytes)

def secure_randint(min_value, max_value, system_random=None):
    """Return a random integer N such that a <= N <= b.

    Uses SystemRandom for generating random numbers.
    (which uses os.urandom(), which pulls from /dev/urandom)"""
    if not system_random:
        system_random = random.SystemRandom()
    return system_random.randint(min_value, max_value)

