def recursive_dict_to_dict(rdict):
    """Convert a recursive dict to a plain ol' dict.
    """
    d = {}
    for k, v in rdict.items():
        if isinstance(v, defaultdict):
            d[k] = recursive_dict_to_dict(v)
        else:
            d[k] = v
    return d

def scrub_dict(d):
    """Recursively inspect a dictionary and remove all empty values, including
    empty strings, lists, and dictionaries."""
    if type(d) is dict:
        return dict(((k, scrub_dict(v)) for k, v in d.iteritems() if v and scrub_dict(v)))
    elif type(d) is list:
        return [scrub_dict(v) for v in d if v and scrub_dict(v)]
    else:
        return d

def _to_json_type(obj, classkey=None):
    """Recursively convert the object instance into a valid JSON type.
    """
    if isinstance(obj, dict):
        data = {}
        for k, v in obj.items():
            data[k] = _to_json_type(v, classkey)
        return data
    elif hasattr(obj, '_ast'):
        return _to_json_type(obj._ast())
    elif hasattr(obj, '__iter__'):
        return [_to_json_type(v, classkey) for v in obj]
    elif hasattr(obj, '__dict__'):
        data = dict([(key, _to_json_type(value, classkey)) for key, value in obj.__dict__.iteritems() if not callable(value) and (not key.startswith('_'))])
        if classkey is not None and hasattr(obj, '__class__'):
            data[classkey] = obj.__class__.__name__
        return data
    else:
        return obj

def to_dict(obj):
    """Convert an instance of an object into a dict.
    """
    d = _to_json_type(obj)
    if isinstance(d, dict):
        return scrub_dict(d)
    else:
        raise ValueError('The value provided must be an object.')

def format_unix_var(text):
    """Example::

        this_is_very_good"""
    text = text.strip()
    if len(text) == 0:
        raise ValueError('can not be empty string!')
    else:
        if text[0] in string.digits:
            raise ValueError('variable can not start with digits!')
        text = text.lower()
        words = list()
        word = list()
        for char in text:
            if char in ALPHA_DIGITS:
                word.append(char)
            elif len(word):
                words.append(''.join(word))
                word = list()
        if len(word):
            words.append(''.join(word))
        return '_'.join(words)

