def _user_config_file():
    """Returns the path to the settings.cfg file. On Windows the file is
    located in the AppData/Local/envipyengine directory. On Unix, the file
    will be located in the ~/.envipyengine directory.

    :return: String specifying the full path to the settings.cfg file"""
    if sys.platform == 'win32':
        if 'LOCALAPPDATA' in os.environ:
            user_dir = os.getenv('LOCALAPPDATA')
        else:
            user_dir = os.path.join(os.path.expanduser('~'), 'AppData', 'Local')
        config_path = os.path.join(user_dir, _APP_DIRNAME, _CONFIG_FILENAME)
    elif sys.platform.startswith('darwin'):
        user_dir = os.path.expanduser('~')
        config_path = os.path.sep.join([user_dir, 'Library', 'Preferences', _APP_DIRNAME, _CONFIG_FILENAME])
    else:
        user_dir = os.path.expanduser('~')
        config_path = os.path.sep.join([user_dir, '.' + _APP_DIRNAME, _CONFIG_FILENAME])
    return config_path

def _system_config_file():
    """Returns the path to the settings.cfg file. On Windows the file is
    located in the AppData/Local/envipyengine directory. On Unix, the file
    will be located in the ~/.envipyengine directory.

    :return: String specifying the full path to the settings.cfg file"""
    if sys.platform == 'win32':
        config_path = os.path.sep.join([_windows_system_appdata(), _APP_DIRNAME, _CONFIG_FILENAME])
    elif sys.platform.startswith('darwin'):
        config_path = os.path.sep.join([os.path.sep + 'Library', 'Preferences', _APP_DIRNAME, _CONFIG_FILENAME])
    else:
        config_path = os.path.sep.join(['', 'var', 'lib', _APP_DIRNAME, _CONFIG_FILENAME])
    return config_path

def dump_func(serializer_type):
    """A decorator for ``_dump(dumper_func=dumper_func, **kwargs)``
    """
    def outer_wrapper(dumper_func):
        def wrapper(*args, **kwargs):
            return _dump(*args, dumper_func=dumper_func, serializer_type=serializer_type, **kwargs)
        return wrapper
    return outer_wrapper

def load_func(serializer_type):
    """A decorator for ``_load(loader_func=loader_func, **kwargs)``
    """
    def outer_wrapper(loader_func):
        def wrapper(*args, **kwargs):
            return _load(*args, loader_func=loader_func, serializer_type=serializer_type, **kwargs)
        return wrapper
    return outer_wrapper

