    Example:
            css.min('path/to/file.css')
            css.min('path/to/file.css', 'path/to/save/result.css')
            css.min('path/to/file.css', False)
            css.min('path/to/file.css', 'path/to/save/result.css', False)"""
    if dest == '':
        return _css_min_exec(_text(src))
    elif type(dest) is bool:
        return _css_min_exec(_text(src), dest)
    else:
        with open(dest, 'w') as f2:
            return f2.write(_css_min_exec(_text(src), preserve_comments))

def file2abspath(filename, this_file=__file__):
    """generate absolute path for the given file and base dir"""
    return os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(this_file)), filename))

def file2json(filename, encoding='utf-8'):
    """save a line"""
    with codecs.open(filename, 'r', encoding=encoding) as f:
        return json.load(f)

def file2iter(filename, encoding='utf-8', comment_prefix='#', skip_empty_line=True):
    """json stream parsing or line parsing"""
    ret = list()
    visited = set()
    with codecs.open(filename, encoding=encoding) as f:
        for line in f:
            line = line.strip()
            if skip_empty_line and len(line) == 0:
                continue
            if comment_prefix and line.startswith(comment_prefix):
                continue
            yield line

def lines2file(lines, filename, encoding='utf-8'):
    """write json stream, write lines too"""
    with codecs.open(filename, 'w', encoding=encoding) as f:
        for line in lines:
            f.write(line)
            f.write('\n')

def items2file(items, filename, encoding='utf-8', modifier='w'):
    """json array to file, canonical json format"""
    with codecs.open(filename, modifier, encoding=encoding) as f:
        for item in items:
            f.write(u'{}\n'.format(json.dumps(item, ensure_ascii=False, sort_keys=True)))

def json_get(json_object, property_path, default=None):
    """get value of property_path from a json object, e.g. person.father.name
    * invalid path return None
    * valid path (the -1 on path is an object), use default"""
    temp = json_object
    for field in property_path[:-1]:
        if not isinstance(temp, dict):
            return None
        temp = temp.get(field, {})
    if not isinstance(temp, dict):
        return None
    return temp.get(property_path[-1], default)

def json_dict_copy(json_object, property_list, defaultValue=None):
    """property_list = [
        { "name":"name", "alternateName": ["name","title"]},
        { "name":"birthDate", "alternateName": ["dob","dateOfBirth"] },
        { "name":"description" }
    ]"""
    ret = {}
    for prop in property_list:
        p_name = prop['name']
        for alias in prop.get('alternateName', []):
            if json_object.get(alias) is not None:
                ret[p_name] = json_object.get(alias)
                break
        if not p_name in ret:
            if p_name in json_object:
                ret[p_name] = json_object[p_name]
            elif defaultValue is not None:
                ret[p_name] = defaultValue
    return ret

def any2utf8(data):
    """rewrite json object values (unicode) into utf-8 encoded string"""
    if isinstance(data, dict):
        ret = {}
        for k, v in data.items():
            k = any2utf8(k)
            ret[k] = any2utf8(v)
        return ret
    elif isinstance(data, list):
        return [any2utf8(x) for x in data]
    elif isinstance(data, unicode):
        return data.encode('utf-8')
    elif type(data) in [str, basestring]:
        return data
    elif type(data) in [int, float]:
        return data
    else:
        logging.error('unexpected {} {}'.format(type(data), data))
        return data

def any2sha1(text):
    """convert a string into sha1hash. For json object/array, first convert
    it into canonical json string."""
    if type(text) in [dict, list]:
        text = json.dumps(text, sort_keys=True)
    if isinstance(text, unicode):
        text = text.encode('utf-8')
    return hashlib.sha1(text).hexdigest()

def stat_jsonld(data, key=None, counter=None):
    """provide statistics for jsonld, right now only count triples
    see also https://json-ld.org/playground/
    note:  attributes  @id @context do not contribute any triple"""
    if counter is None:
        counter = collections.Counter()
    if isinstance(data, dict):
        ret = {}
        for k, v in data.items():
            stat_jsonld(v, k, counter)
            counter[u'p_{}'.format(k)] += 0
        if key:
            counter['triple'] += 1
            counter[u'p_{}'.format(key)] += 1
    elif isinstance(data, list):
        [stat_jsonld(x, key, counter) for x in data]
        if key in ['tag']:
            for x in data:
                if isinstance(x, dict) and x.get('name'):
                    counter[u'{}_{}'.format(key, x['name'])] += 1
                elif type(x) in [basestring, unicode]:
                    counter[u'{}_{}'.format(key, x)] += 1
    elif key and key not in ['@id', '@context']:
        counter['triple'] += 1
        counter[u'p_{}'.format(key)] += 1
    return counter

def attempt_open_query_permutations(url, orig_file_path, is_header_file):
    """Attempt to open a given mock data file with different permutations of the
    query parameters"""
    directory = dirname(convert_to_platform_safe(orig_file_path)) + '/'
    try:
        filenames = [f for f in os.listdir(directory) if isfile(join(directory, f))]
    except OSError:
        return
    if is_header_file:
        filenames = [f for f in filenames if '.http-headers' in f]
        filenames = [f for f in filenames if _compare_file_name(orig_file_path + '.http-headers', directory, f)]
    else:
        filenames = [f for f in filenames if '.http-headers' not in f]
        filenames = [f for f in filenames if _compare_file_name(orig_file_path, directory, f)]
    url_parts = url.split('/')
    url_parts = url_parts[len(url_parts) - 1].split('?')
    base = url_parts[0]
    params = url_parts[1]
    params = params.split('&')
    filenames = [f for f in filenames if f.startswith(base)]
    params = [convert_to_platform_safe(unquote(p)) for p in params]
    for param in params:
        filenames = [f for f in filenames if param in f]
    if len(filenames) == 1:
        path = join(directory, filenames[0])
        return open_file(path)
    if len(filenames) > 1:
        raise DataFailureException(url, 'Multiple mock data files matched the ' + 'parameters provided!', 404)

