def get_pg_connection(host, user, port, password, database, ssl={}):
    """PostgreSQL connection"""
    return psycopg2.connect(host=host, user=user, port=port, password=password, dbname=database, sslmode=ssl.get('sslmode', None), sslcert=ssl.get('sslcert', None), sslkey=ssl.get('sslkey', None), sslrootcert=ssl.get('sslrootcert', None))

def parse_statements(queries_input, engine):
    """Parse input and return a list of SQL statements"""
    queries = []
    query = ''
    sql_delimiter = ';'
    postgres_func_delimiters = ['$$', '##']
    lines = queries_input.strip().split('\n')
    for k, line in enumerate(lines):
        line = line.strip()
        if not line or line.startswith('--'):
            continue
        if engine == 'mysql' and line.upper().startswith('DELIMITER '):
            sql_delimiter = line.split()[1]
            continue
        elif engine == 'postgresql' and [delimiter for delimiter in postgres_func_delimiters if 'AS ' + delimiter in line.upper()]:
            sql_delimiter = line.split()[-1]
            query += line + '\n'
            continue
        if sql_delimiter not in line and k != len(lines) - 1:
            query += line + '\n'
        else:
            if sql_delimiter != ';' and engine == 'mysql' and line.endswith(sql_delimiter):
                line = line.replace(sql_delimiter, ';')
            queries.append(query + line)
            query = ''
    return queries

def get_migrations_applied(engine, connection):
    """Get list of migrations already applied"""
    try:
        if engine == 'postgresql':
            cursor = connection.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        else:
            cursor = connection.cursor()
        sql = 'SELECT id, name, date FROM migrations_applied'
        cursor.execute(sql)
        rows = cursor.fetchall()
        return rows
    except psycopg2.ProgrammingError:
        raise RuntimeError('The table `migrations_applied` is missing. Please refer to the project documentation at https://github.com/gabfl/dbschema.')
    except pymysql.err.ProgrammingError:
        raise RuntimeError('The table `migrations_applied` is missing. Please refer to the project documentation at https://github.com/gabfl/dbschema.')

def get_ssl(database):
    """Returns SSL options for the selected engine"""
    if database['engine'] == 'postgresql':
        keys = ['sslmode', 'sslcert', 'sslkey', 'sslrootcert', 'sslcrl', 'sslcompression']
    else:
        keys = ['ssl_ca', 'ssl_capath', 'ssl_cert', 'ssl_key', 'ssl_cipher', 'ssl_check_hostname']
    ssl = {}
    for key in keys:
        value = database.get(key, None)
        if value is not None:
            ssl[key] = value
    return ssl

def get_content(pattern, string, tag='content'):
    """Finds the 'content' tag from a 'pattern' in the provided 'string'"""
    output = []
    for match in re.finditer(pattern, string):
        output.append(match.group(tag))
    return output

def extract(pattern, string, *, assert_equal=False, one=False, condense=False, default=None, default_if_multiple=True, default_if_none=True):
    """Used to extract a given regex pattern from a string, given several options"""
    if isinstance(pattern, str):
        output = get_content(pattern, string)
    else:
        output = []
        for p in pattern:
            output += get_content(p, string)
    output = process_output(output, one=one, condense=condense, default=default, default_if_multiple=default_if_multiple, default_if_none=default_if_none)
    if assert_equal:
        assert_output(output, assert_equal)
    else:
        return output

