def get_session(username, password, default_endpoints=clc.defaults, cert=None):
    """Start a session with the given parameters

    Use instead of SetCredentials if you need a session object to avoid the use of global credentials.

    Returns a session object accepted by many v2 objects."""
    if cert is None:
        cert = API._ResourcePath('clc/cacert.pem')
    session = requests.Session()
    request = session.request('POST', '{}/v2/authentication/login'.format(default_endpoints.ENDPOINT_URL_V2), data={'username': username, 'password': password}, verify=cert)
    data = request.json()
    if request.status_code == 200:
        token = data['bearerToken']
        alias = data['accountAlias']
        location = data['locationAlias']
    elif request.status_code == 400:
        raise Exception('Invalid V2 API login. {}'.format(data['message']))
    else:
        raise Exception('Error logging into V2 API.  Response code {}. message {}'.format(request.status_code, data['message']))
    return {'username': username, 'password': password, 'http_session': session, 'token': token, 'alias': alias, 'location': location}

def sliding_window(image, step_size, window_size, mask=None, only_whole=True):
    """Creates generator of sliding windows.
    :param image: input image
    :param step_size: number of pixels we are going to skip in both the (x, y) direction
    :param window_size: the width and height of the window we are going to extract
    :param mask: region of interest, if None it will slide through the whole image
    :param only_whole: if True - produces only windows of the given window_size
    :return: generator that produce upper left corner of the window, center of the window and the sliding window itself"""
    if mask is None:
        mask = np.ones(image.shape, dtype=np.bool)
    for y in xrange(0, image.shape[0], step_size):
        for x in xrange(0, image.shape[1], step_size):
            end_x = x + window_size[0]
            end_y = y + window_size[1]
            if only_whole and (end_x > image.shape[1] or end_y > image.shape[0]):
                continue
            else:
                mask_out = np.zeros(image.shape, dtype=np.bool)
                mask_out[y:end_y, x:end_x] = True
                yield (x, y, mask_out, image[y:end_y, x:end_x])

def getinfo(ee_obj, n=4):
    """Make an exponential back off getInfo call on an Earth Engine object"""
    output = None
    for i in range(1, n):
        try:
            output = ee_obj.getInfo()
        except ee.ee_exception.EEException as e:
            if 'Earth Engine memory capacity exceeded' in str(e):
                logging.info('    Resending query ({}/10)'.format(i))
                logging.debug('    {}'.format(e))
                sleep(i ** 2)
            else:
                raise e
        if output:
            break
    return output

def constant_image_value(image, crs='EPSG:32613', scale=1):
    """Extract the output value from a calculation done with constant images"""
    return getinfo(ee.Image(image).reduceRegion(reducer=ee.Reducer.first(), scale=scale, geometry=ee.Geometry.Rectangle([0, 0, 10, 10], crs, False)))

def point_image_value(image, xy, scale=1):
    """Extract the output value from a calculation at a point"""
    return getinfo(ee.Image(image).reduceRegion(reducer=ee.Reducer.first(), geometry=ee.Geometry.Point(xy), scale=scale))

def point_coll_value(coll, xy, scale=1):
    """Extract the output value from a calculation at a point"""
    output = getinfo(coll.getRegion(ee.Geometry.Point(xy), scale=scale))
    col_dict = {}
    info_dict = {}
    for i, k in enumerate(output[0][4:]):
        col_dict[k] = i + 4
        info_dict[k] = {}
    for row in output[1:]:
        date = datetime.datetime.utcfromtimestamp(row[3] / 1000.0).strftime('%Y-%m-%d')
        for k, v in col_dict.items():
            info_dict[k][date] = row[col_dict[k]]
    return info_dict

def get_version(here_path, default_version=DEFAULT_VERSION):
    """tries to resolve version number

    Args:
        here_path (str): path to project local dir
        default_version (str): what version to return if all else fails

    Returns:
        str: semantic_version information for library"""
    if 'site-packages' in here_path:
        return _version_from_file(here_path)
    if os.environ.get('TRAVIS_TAG'):
        if not TEST_MODE:
            return os.environ.get('TRAVIS_TAG').replace('v', '')
        else:
            warnings.warn('Travis detected, but TEST_MODE enabled', exceptions.ProsperVersionTestModeWarning)
    try:
        current_tag = _read_git_tags(default_version=default_version)
    except Exception:
        return _version_from_file(here_path)
    with open(os.path.join(here_path, 'version.txt'), 'w') as v_fh:
        v_fh.write(current_tag)
    return current_tag

def _read_git_tags(default_version=DEFAULT_VERSION, git_command=('git', 'tag')):
    """tries to find current git tag

    Notes:
        git_command exposed for testing null case

    Args:
        default_version (str): what version to make
        git_command (:obj:`list`): subprocess command

    Retruns:
        str: latest version found, or default

    Warns:
        exceptions.ProsperDefaultVersionWarning: git version not found"""
    try:
        current_tags = check_output(git_command).splitlines()
    except Exception:
        raise
    if not current_tags[0]:
        warnings.warn('Unable to resolve current version', exceptions.ProsperDefaultVersionWarning)
        return default_version
    latest_version = semantic_version.Version(default_version)
    for tag in current_tags:
        tag_str = decode(tag, 'utf-8').replace('v', '')
        try:
            tag_ver = semantic_version.Version(tag_str)
        except Exception:
            continue
        if tag_ver > latest_version:
            latest_version = tag_ver
    return str(latest_version)

def get_variable_from_exception(exception, variable_name):
    """Grab the variable from closest frame in the stack"""
    for frame in reversed(trace()):
        try:
            frame_variable = frame[0].f_locals[variable_name]
        except KeyError:
            pass
        else:
            return frame_variable
    else:
        raise KeyError("Variable '%s' not in any stack frames", variable_name)

