def _node(handler, single=None, multi=None):
    """Return an _AbstractSyntaxTreeNode with some elements defaulted."""
    return _AbstractSyntaxTreeNode(handler=handler, single=single if single else [], multi=multi if multi else [])

def _recurse(node, *args, **kwargs):
    """Recursive print worker - recurses the AST and prints each node."""
    node_name = node.__class__.__name__
    try:
        info_for_node = _NODE_INFO_TABLE[node_name]
    except KeyError:
        return
    action = kwargs[info_for_node.handler]
    depth = kwargs['depth']
    if action is not None:
        action(node_name, node, depth)
    recurse_kwargs = kwargs
    kwargs['depth'] = depth + 1
    for single in info_for_node.single:
        _recurse(getattr(node, single), *args, **recurse_kwargs)
    for multi in info_for_node.multi:
        for statement in getattr(node, multi):
            _recurse(statement, *args, **recurse_kwargs)

def patched_context(*module_names, **kwargs):
    """apply emulation patches only for a specific context

    :param module_names: var-args for the modules to patch, as in :func:`patch`
    :param local:
        if True, unpatching is done on every switch-out, and re-patching on
        every switch-in, so that they are only applied for the one coroutine

    :returns:
        a contextmanager that patches on ``__enter__`` and unpatches on
        ``__exit__``"""
    local = kwargs.pop('local', False)
    if kwargs:
        raise TypeError('patched_context() got an unexpected keyword ' + 'argument %r' % kwargs.keys()[0])
    patch(*module_names)
    if local:
        @scheduler.local_incoming_hook
        @scheduler.local_outgoing_hook
        def hook(direction, target):
            {1: patch, 2: unpatch}[direction](*module_names)
    yield
    unpatch(*module_names)
    if local:
        scheduler.remove_local_incoming_hook(hook)
        scheduler.remove_local_outgoing_hook(hook)

def unpatch(*module_names):
    """undo :func:`patch`\\es to standard library modules

    this function takes one or more module names and puts back their patched
    attributes to the standard library originals.

    valid arguments are the same as for :func:`patch`.

    with no arguments, undoes all monkeypatches that have been applied

    :raises: ``ValueError`` if an unknown module name is provided"""
    if not module_names:
        module_names = _standard.keys()
    log.info('undoing monkey-patches in-place (%d modules)' % len(module_names))
    for module_name in module_names:
        if module_name not in _standard:
            raise ValueError("'%s' is not greenhouse-patchable" % module_name)
    for module_name in module_names:
        module = __import__(module_name, {}, {}, module_name.rsplit('.', 1)[0])
        for attr, value in _standard[module_name].items():
            setattr(module, attr, value)

def furtherArgsProcessing(args):
    """Converts args, and deals with incongruities that argparse couldn't handle"""
    if isinstance(args, str):
        unprocessed = args.strip().split(' ')
        if unprocessed[0] == 'cyther':
            del unprocessed[0]
        args = parser.parse_args(unprocessed).__dict__
    elif isinstance(args, argparse.Namespace):
        args = args.__dict__
    elif isinstance(args, dict):
        pass
    else:
        raise CytherError("Args must be a instance of str or argparse.Namespace, not '{}'".format(str(type(args))))
    if args['watch']:
        args['timestamp'] = True
    args['watch_stats'] = {'counter': 0, 'errors': 0, 'compiles': 0, 'polls': 0}
    args['print_args'] = True
    return args

def SecondsToZuluTS(secs=None):
    """Returns Zulu TS from unix time seconds.

    If secs is not provided will convert the current time."""
    if not secs:
        secs = int(time.time())
    return datetime.utcfromtimestamp(secs).strftime('%Y-%m-%dT%H:%M:%SZ')

def where(cmd, path=None):
    """A function to wrap shutil.which for universal usage"""
    raw_result = shutil.which(cmd, os.X_OK, path)
    if raw_result:
        return os.path.abspath(raw_result)
    else:
        raise ValueError("Could not find '{}' in the path".format(cmd))

def search_file(pattern, file_path):
    """Search a given file's contents for the regex pattern given as 'pattern'"""
    try:
        with open(file_path) as file:
            string = file.read()
    except PermissionError:
        return []
    matches = re.findall(pattern, string)
    return matches

def breadth(dirs):
    """Crawl through directories like os.walk, but use a 'breadth first' approach
    (os.walk uses 'depth first')"""
    while dirs:
        next_dirs = []
        print("Dirs: '{}'".format(dirs))
        for d in dirs:
            next_dirs = []
            try:
                for name in os.listdir(d):
                    p = os.path.join(d, name)
                    if os.path.isdir(p):
                        print(p)
                        next_dirs.append(p)
            except PermissionError as nallowed:
                print(nallowed)
        dirs = next_dirs
        if dirs:
            yield dirs

def _get_encodings():
    """Just a simple function to return the system encoding (defaults to utf-8)"""
    stdout_encoding = sys.stdout.encoding if sys.stdout.encoding else 'utf-8'
    stderr_encoding = sys.stderr.encoding if sys.stderr.encoding else 'utf-8'
    return (stdout_encoding, stderr_encoding)

def call(commands, *, print_result=False, raise_exception=False, print_commands=False):
    """Will call a set of commands and wrangle the output how you choose"""
    if isinstance(commands, str):
        commands = commands.split()
    if not (isinstance(commands, tuple) or isinstance(commands, list)):
        raise ValueError("Function 'call' does not accept a 'commands'argument of type '{}'".format(type(commands)))
    if raise_exception:
        print_result = False
    try:
        process = subprocess.Popen(commands, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if print_commands:
            _print_commands(commands)
    except:
        output = traceback.format_exc()
        result = Result(1, stderr=output)
        if print_result and (not raise_exception):
            print(output, file=sys.stderr)
    else:
        result = _extract_output(process, print_result, raise_exception)
    if raise_exception and result.returncode == 1:
        message = 'An error occurred in an external process:\n\n{}'
        raise Exception(message.format(result.getStderr()))
    return result

def multiCall(*commands, dependent=True, bundle=False, print_result=False, print_commands=False):
    """Calls the function 'call' multiple times, given sets of commands"""
    results = []
    dependent_failed = False
    for command in commands:
        if not dependent_failed:
            response = call(command, print_result=print_result, print_commands=print_commands)
            if response.returncode == 1 and dependent:
                dependent_failed = True
        else:
            response = None
        results.append(response)
    if bundle:
        result = Result()
        for response in results:
            if not response:
                continue
            elif response.returncode == 1:
                result.returncode = 1
            result.extendInformation(response)
        processed_response = result
    else:
        processed_response = results
    return processed_response

def join_ext(name, extension):
    """Joins a given name with an extension. If the extension doesn't have a '.'
    it will add it for you"""
    if extension[0] == EXT:
        ret = name + extension
    else:
        ret = name + EXT + extension
    return ret

def has_ext(path_name, *, multiple=None, if_all_ext=False):
    """Determine if the given path name has an extension"""
    base = os.path.basename(path_name)
    count = base.count(EXT)
    if not if_all_ext and base[0] == EXT and (count != 0):
        count -= 1
    if multiple is None:
        return count >= 1
    elif multiple:
        return count > 1
    else:
        return count == 1

def get_ext(path_name, *, if_all_ext=False):
    """Get an extension from the given path name. If an extension cannot be found,
    it will return an empty string"""
    if has_ext(path_name):
        return os.path.splitext(path_name)[EXTENSION]
    elif if_all_ext and has_ext(path_name, if_all_ext=True):
        return os.path.splitext(path_name)[NAME]
    else:
        return ''

def get_dir(path_name, *, greedy=False, override=None, identity=None):
    """Gets the directory path of the given path name. If the argument 'greedy'
    is specified as True, then if the path name represents a directory itself,
    the function will return the whole path"""
    if identity is None:
        identity = identify(path_name, override=override)
    path_name = os.path.normpath(path_name)
    if greedy and identity == ISDIR:
        return path_name
    else:
        return os.path.dirname(path_name)

def get_name(path_name, *, ext=True, override=None, identity=None):
    """Gets the name par of the path name given. By 'name' I mean the basename of
    a filename's path, such as 'test.o' in the path: 'C:/test/test.o'"""
    if identity is None:
        identity = identify(path_name, override=override)
    if identity == ISFILE:
        if ext:
            r = os.path.basename(path_name)
        else:
            r = os.path.splitext(os.path.basename(path_name))[NAME]
    else:
        r = ''
    return r

def get_system_drives():
    """Get the available drive names on the system. Always returns a list."""
    drives = []
    if os.name == 'nt':
        import ctypes
        bitmask = ctypes.windll.kernel32.GetLogicalDrives()
        letter = ord('A')
        while bitmask > 0:
            if bitmask & 1:
                name = chr(letter) + ':' + os.sep
                if os.path.isdir(name):
                    drives.append(name)
            bitmask >>= 1
            letter += 1
    else:
        current_drive = get_drive(os.getcwd())
        if current_drive:
            drive = current_drive
        else:
            drive = os.sep
        drives.append(drive)
    return drives

def has_suffix(path_name, suffix):
    """Determines if path_name has a suffix of at least 'suffix'"""
    if isinstance(suffix, str):
        suffix = disintegrate(suffix)
    components = disintegrate(path_name)
    for i in range(-1, -(len(suffix) + 1), -1):
        if components[i] != suffix[i]:
            break
    else:
        return True
    return False

def getVersionString():
    """Function return string with version information.
    It is performed by use one of three procedures: git describe,
    file in .git dir and file __VERSION__."""
    version_string = None
    try:
        version_string = subprocess.check_output(['git', 'describe'])
    except:
        logger.warning('Command "git describe" is not working')
    if version_string == None:
        try:
            path_to_version = os.path.join(path_to_script, '../.git/refs/heads/master')
            with file(path_to_version) as f:
                version_string = f.read()
        except:
            logger.warning('Problem with reading file ".git/refs/heads/master"')
    if version_string == None:
        try:
