def main(args=None):
    """Entry point for cyther-script, generated by setup.py on installation"""
    if args is None:
        args = sys.argv[1:]
    if not args:
        args = ['-h']
    namespace = parser.parse_args(args)
    entry_function = namespace.func
    del namespace.func
