def _parse_arguments():
    """Return a parser context result."""
    parser = argparse.ArgumentParser(description='CMake AST Dumper')
    parser.add_argument('filename', nargs=1, metavar='FILE', help='read FILE')
    return parser.parse_args()

def _print_details(extra=None):
    """Return a function that prints node details."""
    def print_node_handler(name, node, depth):
        """Standard printer for a node."""
        line = '{0}{1} {2} ({3}:{4})'.format(depth, ' ' * depth, name, node.line, node.col)
        if extra is not None:
            line += ' [{0}]'.format(extra(node))
        sys.stdout.write(line + '\n')
    return print_node_handler

def wait_callback(connection):
    """callback function suitable for ``psycopg2.set_wait_callback``

    pass this function to ``psycopg2.extensions.set_wait_callack`` to force any
    blocking operations from psycopg2 to only block the current coroutine,
    rather than the entire thread or process

    to undo the change and return to normal blocking operation, use
    `psycopg2.extensions.set_wait_callback(None)``"""
    while 1:
        state = connection.poll()
        if state == extensions.POLL_OK:
            break
        elif state == extensions.POLL_READ:
            descriptor.wait_fds([(connection.fileno(), 1)])
        elif state == extensions.POLL_WRITE:
            descriptor.wait_fds([(connection.fileno(), 2)])
        else:
            raise psycopg2.OperationalError('Bad poll result: %r' % state)

def getDirsToInclude(string):
    """Given a string of module names, it will return the 'include' directories
    essential to their compilation as long as the module has the conventional
    'get_include' function."""
    dirs = []
    a = string.strip()
    obj = a.split('-')
    if len(obj) == 1 and obj[0]:
        for module in obj:
            try:
                exec('import {}'.format(module))
            except ImportError:
                raise FileNotFoundError("The module '{}' does notexist".format(module))
            try:
                dirs.append('-I{}'.format(eval(module).get_include()))
            except AttributeError:
                print(NOT_NEEDED_MESSAGE.format(module))
    return dirs

def purge_configs():
    """These will delete any configs found in either the current directory or the
    user's home directory"""
    user_config = path(CONFIG_FILE_NAME, root=USER)
    inplace_config = path(CONFIG_FILE_NAME)
    if os.path.isfile(user_config):
        os.remove(user_config)
    if os.path.isfile(inplace_config):
        os.remove(inplace_config)

def find_config_file():
    """Returns the path to the config file if found in either the current working
    directory, or the user's home directory. If a config file is not found,
    the function will return None."""
    local_config_name = path(CONFIG_FILE_NAME)
    if os.path.isfile(local_config_name):
        return local_config_name
    else:
        user_config_name = path(CONFIG_FILE_NAME, root=USER)
        if os.path.isfile(user_config_name):
            return user_config_name
        else:
            return None

def get_config():
    """Get the config data structure that is supposed to exist in the form:
        (Status, Data)"""
    config_path = find_config_file()
    if not config_path:
        return (CONFIG_NOT_FOUND, None)
    try:
        config_data = read_config_file(config_path)
    except Exception as error:
        return (CONFIG_NOT_VALID, error)
    return (CONFIG_VALID, config_data)

def _lookup_enum_in_ns(namespace, value):
    """Return the attribute of namespace corresponding to value."""
    for attribute in dir(namespace):
        if getattr(namespace, attribute) == value:
            return attribute

def _is_word_type(token_type):
    """Return true if this is a word-type token."""
    return token_type in [TokenType.Word, TokenType.QuotedLiteral, TokenType.UnquotedLiteral, TokenType.Number, TokenType.Deref]

def _is_in_comment_type(token_type):
    """Return true if this kind of token can be inside a comment."""
    return token_type in [TokenType.Comment, TokenType.Newline, TokenType.Whitespace, TokenType.RST, TokenType.BeginRSTComment, TokenType.BeginInlineRST, TokenType.EndInlineRST]

def _get_string_type_from_token(token_type):
    """Return 'Single' or 'Double' depending on what kind of string this is."""
    return_value = None
    if token_type in [TokenType.BeginSingleQuotedLiteral, TokenType.EndSingleQuotedLiteral]:
        return_value = 'Single'
    elif token_type in [TokenType.BeginDoubleQuotedLiteral, TokenType.EndDoubleQuotedLiteral]:
        return_value = 'Double'
    assert return_value is not None
    return return_value

def _make_header_body_handler(end_body_regex, node_factory, has_footer=True):
    """Utility function to make a handler for header-body node.

    A header-body node is any node which has a single function-call
    header and a body of statements inside of it"""
    def handler(tokens, tokens_len, body_index, function_call):
        """Handler function."""
        def _end_header_body_definition(token_index, tokens):
            """Header body termination function."""
            if end_body_regex.match(tokens[token_index].content):
                try:
                    if tokens[token_index + 1].type == TokenType.LeftParen:
                        return True
                except IndexError:
                    raise RuntimeError('Syntax Error')
            return False
        token_index, body = _ast_worker(tokens, tokens_len, body_index, _end_header_body_definition)
        extra_kwargs = {}
        if has_footer:
            token_index, footer = _handle_function_call(tokens, tokens_len, token_index)
            extra_kwargs = {'footer': footer}
        return (token_index, node_factory(header=function_call, body=body.statements, line=tokens[body_index].line, col=tokens[body_index].col, index=body_index, **extra_kwargs))
    return handler

def _handle_function_call(tokens, tokens_len, index):
    """Handle function calls, which could include a control statement.

    In CMake, all control flow statements are also function calls, so handle
    the function call first and then direct tree construction to the
    appropriate control flow statement constructor found in
    _FUNCTION_CALL_DISAMBIGUATE"""
    def _end_function_call(token_index, tokens):
        """Function call termination detector."""
        return tokens[token_index].type == TokenType.RightParen
    next_index, call_body = _ast_worker(tokens, tokens_len, index + 2, _end_function_call)
    function_call = FunctionCall(name=tokens[index].content, arguments=call_body.arguments, line=tokens[index].line, col=tokens[index].col, index=index)
    try:
        handler = _FUNCTION_CALL_DISAMBIGUATE[tokens[index].content.lower()]
    except KeyError:
        handler = None
    if handler:
        return handler(tokens, tokens_len, next_index, function_call)
    else:
        return (next_index, function_call)

def _ast_worker(tokens, tokens_len, index, term):
    """The main collector for all AST functions.

    This function is called recursively to find both variable use and function
    calls and returns a GenericBody with both those variables and function
    calls hanging off of it. The caller can figure out what to do with both of
    those"""
    statements = []
    arguments = []
    while index < tokens_len:
        if term:
            if term(index, tokens):
                break
        if tokens[index].type == TokenType.Word and index + 1 < tokens_len and (tokens[index + 1].type == TokenType.LeftParen):
            index, statement = _handle_function_call(tokens, tokens_len, index)
            statements.append(statement)
        elif _is_word_type(tokens[index].type):
            arguments.append(Word(type=_word_type(tokens[index].type), contents=tokens[index].content, line=tokens[index].line, col=tokens[index].col, index=index))
        index = index + 1
    return (index, GenericBody(statements=statements, arguments=arguments))

def _is_really_comment(tokens, index):
    """Return true if the token at index is really a comment."""
    if tokens[index].type == TokenType.Comment:
        return True
    try:
        if tokens[index].content.lstrip()[0] == '#':
            return True
    except IndexError:
        return False

def _paste_tokens_line_by_line(tokens, token_type, begin, end):
    """Return lines of tokens pasted together, line by line."""
    block_index = begin
    while block_index < end:
        rst_line = tokens[block_index].line
        line_traversal_index = block_index
        pasted = ''
        try:
            while tokens[line_traversal_index].line == rst_line:
                pasted += tokens[line_traversal_index].content
                line_traversal_index += 1
        except IndexError:
            assert line_traversal_index == end
        last_tokens_len = len(tokens)
        tokens = _replace_token_range(tokens, block_index, line_traversal_index, [Token(type=token_type, content=pasted, line=tokens[block_index].line, col=tokens[block_index].col)])
        end -= last_tokens_len - len(tokens)
        block_index += 1
    return (block_index, len(tokens), tokens)

def _find_recorder(recorder, tokens, index):
    """Given a current recorder and a token index, try to find a recorder."""
    if recorder is None:
        for recorder_factory in _RECORDERS:
            recorder = recorder_factory.maybe_start_recording(tokens, index)
            if recorder is not None:
                return recorder
    return recorder

def parse(contents, tokens=None):
    """Parse a string called contents for an AST and return it."""
    if tokens is None:
        tokens = [t for t in tokenize(contents)]
    token_index, body = _ast_worker(tokens, len(tokens), 0, None)
    assert token_index == len(tokens)
    assert body.arguments == []
    return ToplevelBody(statements=body.statements)

def user_active_directory_deactivate(user, attributes, created, updated):
    """Deactivate user accounts based on Active Directory's
    userAccountControl flags. Requires 'userAccountControl'
    to be included in LDAP_SYNC_USER_EXTRA_ATTRIBUTES."""
    try:
        user_account_control = int(attributes['userAccountControl'][0])
        if user_account_control & 2:
            user.is_active = False
    except KeyError:
        pass

def _check_whitespace(string):
    """Make sure thre is no whitespace in the given string. Will raise a
    ValueError if whitespace is detected"""
    if string.count(' ') + string.count('\t') + string.count('\n') > 0:
        raise ValueError(INSTRUCTION_HAS_WHITESPACE)

def _check_parameters(parameters, symbols):
    """Checks that the parameters given are not empty. Ones with prefix symbols
    can be denoted by including the prefix in symbols"""
    for param in parameters:
        if not param:
            raise ValueError(EMPTY_PARAMETER)
        elif param[0] in symbols and (not param[1:]):
            print(param)
            raise ValueError(EMPTY_KEYWORD_PARAMETER)

def _check_dependencies(string):
    """Checks the dependencies constructor. Looks to make sure that the
    dependencies are the first things defined"""
    opener, closer = ('(', ')')
    _check_enclosing_characters(string, opener, closer)
    if opener in string:
        if string[0] != opener:
            raise ValueError(DEPENDENCIES_NOT_FIRST)
        ret = True
    else:
        ret = False
    return ret

def _check_building_options(string):
    """Checks the building options to make sure that they are defined last,
    after the task name and the dependencies"""
    opener, closer = ('{', '}')
    _check_enclosing_characters(string, opener, closer)
    if opener in string:
        if string[-1] != closer:
            raise ValueError(OPTIONS_NOT_LAST)
        ret = True
    else:
        ret = False
    return ret

def _check_flow_operator(string):
    """Checks the flow operator ('>') to make sure that it:
    1) Is non empty
    2) There is only one of them"""
    greater_than_count = string.count('>')
    if greater_than_count > 1:
        raise ValueError(MULTIPLE_FLOW_OPERATORS)
    elif string[0] == '>' or string[-1] == '>':
        raise ValueError(FLOW_OPERATOR_ON_ENDS)
    elif greater_than_count == 1:
        ret = True
    else:
        ret = False
    return ret

def _parse_dependencies(string):
    """This function actually parses the dependencies are sorts them into
    the buildable and given dependencies"""
    contents = _get_contents_between(string, '(', ')')
    unsorted_dependencies = contents.split(',')
    _check_parameters(unsorted_dependencies, ('?',))
    buildable_dependencies = []
    given_dependencies = []
    for dependency in unsorted_dependencies:
        if dependency[0] == '?':
            given_dependencies.append(dependency[1:])
        else:
            buildable_dependencies.append(dependency)
    string = string[string.index(')') + 1:]
    return (buildable_dependencies, given_dependencies, string)

def _parse_building_options(string):
    """This will parse and sort the building options defined in the '{}'
    constructor. Will only allow one of each argument"""
    contents = _get_contents_between(string, '{', '}')
    unsorted_options = contents.split(',')
    _check_parameters(unsorted_options, ('@', '/', '\\', '^'))
    output_directory = None
    output_format = None
    building_directory = None
    for option in unsorted_options:
        if option[0] == '@':
            if output_format:
                raise ValueError(MULTIPLE_CONFLICTING_BUILD_OPTIONS)
            output_format = option[1:]
        elif option[0] in ('/', '\\'):
            if output_directory:
                raise ValueError(MULTIPLE_CONFLICTING_BUILD_OPTIONS)
            output_directory = option[1:]
        elif option[0] == '^':
            if building_directory:
                raise ValueError(MULTIPLE_CONFLICTING_BUILD_OPTIONS)
            building_directory = option[1:]
    string = string[:string.index('{')]
    return (output_directory, output_format, building_directory, string)

def gen_stochastic_matrix(size, random_state=None):
    """Generate a unfiformly-random stochastic array or matrix"""
    if not type(size) is tuple:
        size = (1, size)
    assert len(size) == 2
    n = random_state.uniform(size=(size[0], size[1] - 1))
    n = np.concatenate([np.zeros((size[0], 1)), n, np.ones((size[0], 1))], axis=1)
    A = np.diff(np.sort(n))
    return A.squeeze()

def steadystate(A, max_iter=100):
    """Empirically determine the steady state probabilities from a stochastic matrix"""
    P = np.linalg.matrix_power(A, max_iter)
    v = []
    for i in range(len(P)):
        if not np.any([np.allclose(P[i], vi) for vi in v]):
            v.append(P[i])
    return normalize(np.sum(v, axis=0))

def addresses_for_key(gpg, key):
    """Takes a key and extracts the email addresses for it."""
    return [address.split('<')[-1].strip('>') for address in gpg.list_keys().key_map[key['fingerprint']]['uids'] if address]

def L(g, i):
    """recursively constructs L line for g; i = len(g)-1"""
    g1 = g & 2 ** i
    if i:
        n = Lwidth(i)
        Ln = L(g, i - 1)
        if g1:
            return Ln << 2 * n | Ln << n | Ln
        else:
            return int('1' * n, 2) << 2 * n | Ln << n | Ln
    elif g1:
        return int('000', 2)
    else:
        return int('100', 2)

def H(g, i):
    """recursively constructs H line for g; i = len(g)-1"""
    g1 = g & 2 ** i
    if i:
        n = Hwidth(i)
        i = i - 1
        Hn = H(g, i)
        if g1:
            return Hn << 2 * n | Hn << n | Hn
        else:
            return int('1' * n, 2) << 2 * n | L(g, i) << n | Hn
    elif g1:
        return int('111', 2)
    else:
        return int('101', 2)

def A(g, i):
    """recursively constructs A line for g; i = len(g)-1"""
    g1 = g & 2 ** i
    if i:
        n = Awidth(i)
        An = A(g, i - 1)
        if g1:
            return An << n | An
        else:
            return int('1' * n, 2) << n | An
    elif g1:
        return int('00', 2)
    else:
        return int('10', 2)

def B(g, i):
    """recursively constructs B line for g; i = len(g)-1"""
    g1 = g & 2 ** i
    if i:
        nA = Awidth(i)
        nB = Bwidth(i)
        i = i - 1
        Bn = B(g, i)
        if g1:
            return Bn << nA + nB | int('1' * nA, 2) << nB | Bn
        else:
            return int('1' * nB, 2) << nA + nB | A(g, i) << nB | Bn
    elif g1:
        return 1
    else:
        return 0

def B012(t, i):
    """Constructs ternary implication coding (0=not there, 2=U, 1=V)
    t is B column position
    i = |M|-1 to 0"""
    if not i:
        return '1'
    nA = Awidth(i)
    nB = Bwidth(i)
    nBB = nB + nA
    if t < nB:
        return '0' + B012(t, i - 1)
    elif t < nBB:
        return '1' + A012(t - nB, i - 1)
    else:
        return '2' + B012(t - nBB, i - 1)

def omega(imps):
    """Calculates a measure for the size of the implication basis: \\sum |U||V|"""
    if isinstance(imps, v_Us_dict):
        return sum([omega(V) for U, V in imps.items()])
    if isinstance(imps, list):
        return sum([omega(x) for x in imps])
    if isinstance(imps, str):
        try:
            U, V = imps.split('->')
            Us = U.split(',') if ',' in U else U.split()
            Vs = V.split(',') if ',' in V else V.split()
            res = len(Us) * len(Vs)
            return res
        except:
            return 0
    if isinstance(imps, int):
        b = bin(imps)[2:]
        res = len([x for x in b if x == '1'])
        return res

def LL(n):
    """constructs the LL context"""
    if n <= 0:
        return Context('0')
    else:
        LL1 = LL(n - 1)
        r1 = C1(3 ** (n - 1), 2 ** (n - 1)) - LL1 - LL1
        r2 = LL1 - LL1 - LL1
        return r1 + r2

def HH(n):
    """constructs the HH context"""
    if n <= 0:
        return Context('1')
    else:
        LL1 = LL(n - 1)
        HH1 = HH(n - 1)
        r1 = C1(3 ** (n - 1), 2 ** (n - 1)) - LL1 - HH1
        r2 = HH1 - HH1 - HH1
        return r1 + r2

def AA(n):
    """constructs the AA context"""
    if n <= 1:
        return Context('10\n00')
    else:
        AA1 = AA(n - 1)
        r1 = C1(2 ** (n - 1), 2 ** (n - 1)) - AA1
        r2 = AA1 - AA1
        return r1 + r2

def BB(n):
    """constructs the BB context"""
    if n <= 1:
        return Context('0\n1')
    else:
        BB1 = BB(n - 1)
        AA1 = AA(n - 1)
        r1 = C1((n - 1) * 2 ** (n - 2), 2 ** (n - 1)) - AA1 - BB1
        r2 = BB1 - C1(2 ** (n - 1), 2 ** (n - 1)) - BB1
        return r1 + r2

def greenlet(func, args=(), kwargs=None):
    """create a new greenlet from a function and arguments

    :param func: the function the new greenlet should run
    :type func: function
    :param args: any positional arguments for the function
    :type args: tuple
    :param kwargs: any keyword arguments for the function
    :type kwargs: dict or None

    the only major difference between this function and that of the basic
    greenlet api is that this one sets the new greenlet's parent to be the
    greenhouse main loop greenlet, which is a requirement for greenlets that
    will wind up in the greenhouse scheduler."""
    if args or kwargs:
        def target():
            return func(*args, **kwargs or {})
    else:
        target = func
    return compat.greenlet(target, state.mainloop)

def end(target):
    """schedule a greenlet to be stopped immediately

    :param target: the greenlet to end
    :type target: greenlet"""
    if not isinstance(target, compat.greenlet):
        raise TypeError('argument must be a greenlet')
    if not target.dead:
        schedule(target)
        state.to_raise[target] = compat.GreenletExit()

def process_output(output, *, condense=False, one=False, default=None, default_if_multiple=True, default_if_none=True):
    """Taking a iterative container (list, tuple), this function will process its
    contents and condense if necessary. It also has functionality to try to
    assure that the output has only one item in it if desired. If this is not
    the case, then it will return a 'default' in place of the output, if
    specified."""
    if condense:
        output = list(set(output))
    if one:
        if len(output) > 1:
            if default and default_if_multiple:
                output = default
            else:
                return MULTIPLE
        elif len(output) == 1:
            output = output[0]
        elif default and default_if_none:
            return default
        else:
            return NONE
    return output

def read_dict_from_file(file_path):
    """Read a dictionary of strings from a file"""
    with open(file_path) as file:
        lines = file.read().splitlines()
    obj = {}
    for line in lines:
        key, value = line.split(':', maxsplit=1)
        obj[key] = eval(value)
    return obj

def get_input(prompt, check, *, redo_prompt=None, repeat_prompt=False):
    """Ask the user to input something on the terminal level, check their response
    and ask again if they didn't answer correctly"""
    if isinstance(check, str):
        check = (check,)
    to_join = []
    for item in check:
        if item:
            to_join.append(str(item))
        else:
            to_join.append("''")
    prompt += ' [{}]: '.format('/'.join(to_join))
    if repeat_prompt:
        redo_prompt = prompt
    elif not redo_prompt:
        redo_prompt = 'Incorrect input, please choose from {}: '.format(str(check))
    if callable(check):
        def _checker(r):
            return check(r)
    elif isinstance(check, tuple):
        def _checker(r):
            return r in check
    else:
        raise ValueError(RESPONSES_ERROR.format(type(check)))
    response = input(prompt)
    while not _checker(response):
        print(response, type(response))
        response = input(redo_prompt if redo_prompt else prompt)
    return response

def generateBatches(tasks, givens):
    """A function to generate a batch of commands to run in a specific order as to
    meet all the dependencies for each command. For example, the commands with
    no dependencies are run first, and the commands with the most deep
    dependencies are run last"""
    _removeGivensFromTasks(tasks, givens)
    batches = []
    while tasks:
        batch = set()
        for task, dependencies in tasks.items():
            if not dependencies:
                batch.add(task)
        if not batch:
            _batchErrorProcessing(tasks)
        for task in batch:
            del tasks[task]
        for task, dependencies in tasks.items():
            for item in batch:
                if item in dependencies:
                    tasks[task].remove(item)
        batches.append(batch)
    return batches

def query_param_string_from_option_args(a2q_dict, args_dict):
    """From a dictionary of arguments to query string parameters, loops through ad arguments list and makes a query string.
    :param a2q_dict: a dictionary containing argument_name > query string parameter name.
    :param args_dict: a dictionary containing the argument_name > argument_value
    :return: a query string."""
    name_value_pairs = dict()
    for ak in a2q_dict.keys():
        value = args_dict[ak]
        if value != None:
            name_value_pairs[a2q_dict[ak]] = str(value)
    return urllib.urlencode(name_value_pairs)

def cueExtractAndRun(args, file):
    """Cues the @cyther code execution procedure"""
    filename = file['file_path']
    if args['execute']:
        holla = run(filename)
    else:
        holla = run(filename, True)
    return holla

def core(args):
    """The heart of Cyther, this function controls the main loop, and can be
    used to perform any Cyther action. You can call if using Cyther
    from the module level"""
    args = furtherArgsProcessing(args)
    numfiles = len(args['filenames'])
    interval = INTERVAL / numfiles
    files = processFiles(args)
    while True:
        for file in files:
            cytherize(args, file)
        if not args['watch']:
            break
        else:
            time.sleep(interval)

def load_input(definition):
    """Load and parse input if needed.

    :param definition: definition to use as an input (file, serialized JSON/YAML or dict)
    :return: loaded input
    :raises json2sql.ParsingInputError: when parsing fails"""
    if isinstance(definition, (str, io.TextIOWrapper)):
        try:
            definition = yaml.safe_load(definition)
        except Exception as exc:
            raise ParsingInputError('Unable to parse input: %s' % str(exc))
    return definition

def any2sql(func, definition_dict=None, **definition_kwargs):
    """Handle general to SQL conversion.

    :param func: function to be called on the given definition
    :param definition_dict: statement definition in dict
    :param definition_kwargs: statement definition as kwargs
    :return: raw SQL statement"""
    if definition_dict and definition_kwargs:
        raise InputError('Cannot process dict and kwargs input at the same time')
    definition = load_input(definition_dict or definition_kwargs)
    if definition.get('returning', '') == '*':
        definition['returning'] = mosql_raw('*')
    try:
        result = func(**definition)
    except (TypeError, AttributeError) as exc:
        raise ClauseError('Clause definition error: %s' % str(exc)) from exc
    except Exception as exc:
        import json2sql.errors as json2sql_errors
        if exc.__class__.__name__ not in json2sql_errors.__dict__.keys():
            raise json2sql_errors.Json2SqlInternalError('Unhandled error: %s' % str(exc)) from exc
        raise
    return result

