def launchctl(subcommand, *args):
    """A minimal wrapper to call the launchctl binary and capture the output
    :param subcommand: string"""
    if not isinstance(subcommand, six.string_types):
        raise ValueError('Argument is invalid: %r' % repr(subcommand))
    if isinstance(subcommand, six.text_type):
        subcommand = subcommand.encode('utf-8')
    cmd = ['launchctl', subcommand]
    for arg in args:
        if isinstance(arg, six.string_types):
            if isinstance(arg, six.text_type):
                cmd.append(arg.encode('utf-8'))
            else:
                cmd.append(arg)
        else:
            raise ValueError('Argument is invalid: %r' % repr(arg))
    return subprocess.check_output(cmd, stdin=None, stderr=subprocess.STDOUT, shell=False)

def parse_intervals(diff_report):
    """Parse a diff into an iterator of Intervals."""
    for patch in diff_report.patch_set:
        try:
            old_pf = diff_report.old_file(patch.source_file)
            new_pf = diff_report.new_file(patch.target_file)
        except InvalidPythonFile:
            continue
        for hunk in patch:
            for line in hunk:
                if line.line_type == LINE_TYPE_ADDED:
                    idx = line.target_line_no
                    yield ContextInterval(new_pf.filename, new_pf.context(idx))
                elif line.line_type == LINE_TYPE_REMOVED:
                    idx = line.source_line_no
                    yield ContextInterval(old_pf.filename, old_pf.context(idx))
                elif line.line_type in (LINE_TYPE_EMPTY, LINE_TYPE_CONTEXT):
                    pass
                else:
                    raise AssertionError('Unexpected line type: %s' % line)

def string_literal(content):
    """Choose a string literal that can wrap our string.

    If your string contains a ``'`` the result will be wrapped in ``"``.
    If your string contains a ``"`` the result will be wrapped in ``'``.

    Cannot currently handle strings which contain both ``"`` and ``'``."""
    if '"' in content and "'" in content:
        raise ValueError('Cannot represent this string in XPath')
    if '"' in content:
        content = "'%s'" % content
    else:
        content = '"%s"' % content
    return content

def element_id_by_label(browser, label):
    """The ID of an element referenced by a `label`s ``for`` attribute. The label
    must be visible.

    :param browser: ``world.browser``
    :param label: label text to return the referenced element for

    Returns: ``for`` attribute value"""
    label = ElementSelector(browser, str('//label[contains(., %s)]' % string_literal(label)))
    if not label:
        return False
    return label.get_attribute('for')

def field_xpath(field, attribute):
    """Field helper functions to locate select, textarea, and the other
    types of input fields (text, checkbox, radio)

    :param field: One of the values 'select', 'textarea', 'option', or
    'button-element' to match a corresponding HTML element (and to
    match a <button> in the case of 'button-element'). Otherwise a
    type to match an <input> element with a type=<field> attribute.

    :param attribute: An attribute to be matched against, or 'value'
    to match against the content within element being matched."""
    if field in ['select', 'textarea']:
        xpath = './/{field}[@{attr}=%s]'
    elif field == 'button-role':
        if attribute == 'value':
            xpath = './/*[@role="button"][contains(., %s)]'
        else:
            xpath = './/*[@role="button"][@{attr}=%s]'
    elif field == 'button-element':
        field = 'button'
        if attribute == 'value':
            xpath = './/{field}[contains(., %s)]'
        else:
            xpath = './/{field}[@{attr}=%s]'
    elif field == 'option':
        xpath = './/{field}[@{attr}=%s]'
    else:
        xpath = './/input[@{attr}=%s][@type="{field}"]'
    return xpath.format(field=field, attr=attribute)

def find_field_by_value(browser, field_type, name):
    """Locate the control input with the given ``value``. Useful for buttons.

    :param browser: ``world.browser``
    :param string field_type: a field type (i.e. `button`)
    :param string name: ``value`` attribute

    Returns: an :class:`ElementSelector`"""
    xpath = field_xpath(field_type, 'value') % string_literal(name)
    elems = ElementSelector(browser, xpath=str(xpath), filter_displayed=True, filter_enabled=True)
    if field_type in ('button-element', 'button-role'):
        elems = sorted(elems, key=lambda elem: len(elem.text))
    else:
        elems = sorted(elems, key=lambda elem: len(elem.get_attribute('value')))
    if elems:
        elems = [elems[0]]
    return ElementSelector(browser, elements=elems)

def option_in_select(browser, select_name, option):
    """Returns the Element specified by @option or None

    Looks at the real <select> not the select2 widget, since that doesn't
    create the DOM until we click on it."""
    select = find_field(browser, 'select', select_name)
    assert select, "Cannot find a '{}' select.".format(select_name)
    try:
        return select.find_element_by_xpath(str('.//option[normalize-space(text())=%s]' % string_literal(option)))
    except NoSuchElementException:
        return None

def wait_for(func):
    """A decorator to invoke a function, retrying on assertion errors for a
    specified time interval.

    Adds a kwarg `timeout` to `func` which is a number of seconds to try
    for (default 15)."""
    @wraps(func)
    def wrapped(*args, **kwargs):
        timeout = kwargs.pop('timeout', TIMEOUT)
        start = None
        while True:
            try:
                return func(*args, **kwargs)
            except AssertionError:
                if not start:
                    start = time()
                if time() - start < timeout:
                    sleep(CHECK_EVERY)
                    continue
                else:
                    raise
    return wrapped

def load_jquery(func):
    """A decorator to ensure a function is run with jQuery available.

    If an exception from a function indicates jQuery is missing, it is loaded
    and the function re-executed.

    The browser to load jQuery into must be the first argument of the function."""
    @wraps(func)
    def wrapped(browser, *args, **kwargs):
        """Run the function, loading jQuery if needed."""
        try:
            return func(browser, *args, **kwargs)
        except WebDriverException as ex:
            if not is_jquery_not_defined_error(ex.msg):
                raise
            load_script(browser, JQUERY)
            @wait_for
            def jquery_available():
                """Assert that jQuery has loaded."""
                try:
                    return browser.execute_script('return $')
                except WebDriverException:
                    raise AssertionError('jQuery is not loaded')
            jquery_available()
            return func(browser, *args, **kwargs)
    return wrapped

def find_element_by_jquery(browser, selector):
    """Find a single HTML element using jQuery-style selectors."""
    elements = find_elements_by_jquery(browser, selector)
    if not elements:
        raise AssertionError('No matching element found.')
    if len(elements) > 1:
        raise AssertionError('Multiple matching elements found.')
    return elements[0]

def check_element_by_selector(self, selector):
    """Assert an element exists matching the given selector."""
    elems = find_elements_by_jquery(world.browser, selector)
    if not elems:
        raise AssertionError('Expected matching elements, none found.')

def check_no_element_by_selector(self, selector):
    """Assert an element does not exist matching the given selector."""
    elems = find_elements_by_jquery(world.browser, selector)
    if elems:
        raise AssertionError('Expected no matching elements, found {}.'.format(len(elems)))

def wait_for_element_by_selector(self, selector, seconds):
    """Assert an element exists matching the given selector within the given time
    period."""
    def assert_element_present():
        """Assert an element matching the given selector exists."""
        if not find_elements_by_jquery(world.browser, selector):
            raise AssertionError('Expected a matching element.')
    wait_for(assert_element_present)(timeout=int(seconds))

def count_elements_exactly_by_selector(self, number, selector):
    """Assert n elements exist matching the given selector."""
    elems = find_elements_by_jquery(world.browser, selector)
    number = int(number)
    if len(elems) != number:
        raise AssertionError('Expected {} elements, found {}'.format(number, len(elems)))

def check_by_selector(self, selector):
    """Check the checkbox matching the CSS selector."""
    elem = find_element_by_jquery(world.browser, selector)
    if not elem.is_selected():
        elem.click()

def is_selected_by_selector(self, selector):
    """Assert the option matching the CSS selector is selected."""
    elem = find_element_by_jquery(world.browser, selector)
    if not elem.is_selected():
        raise AssertionError('Element expected to be selected.')

def get_input_node(cls, value):
    """Return a `Node` of a given class and given value.

    If a `Node` of the given type and value already exists, that will be returned, otherwise a new one will be created,
    stored and returned.

    :param cls: the `Node` class
    :param value: the value of the `Node`"""
    from aiida import orm
    if cls in (orm.Bool, orm.Float, orm.Int, orm.Str):
        result = orm.QueryBuilder().append(cls, filters={'attributes.value': value}).first()
        if result is None:
            node = cls(value).store()
        else:
            node = result[0]
    elif cls is orm.Dict:
        result = orm.QueryBuilder().append(cls, filters={'attributes': {'==': value}}).first()
        if result is None:
            node = cls(dict=value).store()
        else:
            node = result[0]
    else:
        raise NotImplementedError
    return node

