def pw_converter(handler, flt):
    """Convert column name to filter."""
    import peewee as pw
    if isinstance(flt, Filter):
        return flt
    model = handler.model
    field = getattr(model, flt)
    if isinstance(field, pw.BooleanField):
        return PWBoolFilter(flt)
    if field.choices:
        choices = [(Filter.default, '---')] + list(field.choices)
        return PWChoiceFilter(flt, choices=choices)
    return PWFilter(flt)

def export_as_csv(admin_model, request, queryset):
    """Generic csv export admin action.
    based on http://djangosnippets.org/snippets/1697/"""
    if getattr(settings, 'DJANGO_EXPORTS_REQUIRE_PERM', None):
        admin_opts = admin_model.opts
        codename = '%s_%s' % ('csv', admin_opts.object_name.lower())
        has_csv_permission = request.user.has_perm('%s.%s' % (admin_opts.app_label, codename))
    else:
        has_csv_permission = admin_model.has_csv_permission(request) if hasattr(admin_model, 'has_csv_permission') and callable(getattr(admin_model, 'has_csv_permission')) else True
    if has_csv_permission:
        opts = admin_model.model._meta
        if getattr(admin_model, 'csv_fields', None):
            field_names = admin_model.csv_fields
        else:
            field_names = [field.name for field in opts.fields]
            field_names.sort()
        if django.VERSION[0] == 1 and django.VERSION[1] <= 5:
            response = HttpResponse(mimetype='text/csv')
        else:
            response = HttpResponse(content_type='text/csv')
        response['Content-Disposition'] = 'attachment; filename=%s.csv' % text(opts).replace('.', '_')
        queryset = queryset.values_list(*field_names)
        pandas.DataFrame(list(queryset), columns=field_names).to_csv(response, index=False, encoding='utf-8')
        return response
    return HttpResponseForbidden()

def create_datapoint(value, timestamp=None, **tags):
    """Creates a single datapoint dict with a value, timestamp and tags.

    :param value: Value of the datapoint. Type depends on the id's MetricType
    :param timestamp: Optional timestamp of the datapoint. Uses client current time if not set. Millisecond accuracy. Can be datetime instance also.
    :param tags: Optional datapoint tags. Not to be confused with metric definition tags"""
    if timestamp is None:
        timestamp = time_millis()
    if type(timestamp) is datetime:
        timestamp = datetime_to_time_millis(timestamp)
    item = {'timestamp': timestamp, 'value': value}
    if tags is not None:
        item['tags'] = tags
    return item

def create_metric(metric_type, metric_id, data):
    """Create Hawkular-Metrics' submittable structure.

    :param metric_type: MetricType to be matched (required)
    :param metric_id: Exact string matching metric id
    :param data: A datapoint or a list of datapoints created with create_datapoint(value, timestamp, tags)"""
    if not isinstance(data, list):
        data = [data]
    return {'type': metric_type, 'id': metric_id, 'data': data}

def kunc_v(p, v0, k0, k0p, order=5, min_strain=0.01):
    """find volume at given pressure using brenth in scipy.optimize

    :param p: pressure in GPa
    :param v0: unit-cell volume in A^3 at 1 bar
    :param k0: bulk modulus at reference conditions
    :param k0p: pressure derivative of bulk modulus at reference conditions
    :param order: order of Kunc function
    :param min_strain: defining minimum v/v0 value to search volume for
    :return: unit-cell volume at high pressure in GPa
    :note: a wrapper function vectorizing kunc_v_single"""
    if isuncertainties([p, v0, k0, k0p]):
        f_u = np.vectorize(uct.wrap(kunc_v_single), excluded=[1, 2, 3, 4, 5])
        return f_u(p, v0, k0, k0p, order=order, min_strain=min_strain)
    else:
        f_v = np.vectorize(kunc_v_single, excluded=[1, 2, 3, 4, 5])
        return f_v(p, v0, k0, k0p, order=order, min_strain=min_strain)

def kunc_dPdV(v, v0, k0, k0p, order=5, precision=1e-05):
    """calculate dP/dV for numerical calculation of bulk modulus
    according to test this differs from analytical result by 1.e-5

    :param v: unit-cell volume in A^3
    :param v0: unit-cell volume in A^3 at 1 bar
    :param k0: bulk modulus at reference conditions
    :param k0p: pressure derivative of bulk modulus at reference conditions
    :param precision: precision for numerical calc (default = 1.e-5 * v0)
    :return: dP/dV"""
    def f_scalar(v, v0, k0, k0p, order=order, precision=1e-05):
        return derivative(kunc_p, v, args=(v0, k0, k0p, order), dx=v0 * precision)
    f_v = np.vectorize(f_scalar, excluded=[1, 2, 3, 4, 5])
    return f_v(v, v0, k0, k0p, order=order, precision=precision)

def debye_E(x):
    """calculate Debye energy using old fortran routine

    :params x: Debye x value
    :return: Debye energy
