    if isuncertainties([x]):
        f_u = uct.wrap(debye_E_single)
        f_v = np.vectorize(f_u)
    else:
        f_v = np.vectorize(debye_E_single)
    return f_v(x)

def contains_content(browser, content):
    """Search for an element that contains the whole of the text we're looking
    for in it or its subelements, but whose children do NOT contain that
    text - otherwise matches <body> or <html> or other similarly useless
    things."""
    for elem in browser.find_elements_by_xpath(str('//*[contains(normalize-space(.), {content}) and not(./*[contains(normalize-space(.), {content})])]'.format(content=string_literal(content)))):
