        value = property(_get_value, pm._set_value, None, 'Value property')

def persist_revision_once(tokens, revision):
    """This function makes sure that a revision is only marked as persisting
    for a token once.  This is important since some diff algorithms allow
    tokens to be copied more than once in a revision.  The id(token) should
    unique to the in-memory representation of any object, so we use that as
    unique token instance identifier."""
    token_map = {id(token): token for token in tokens}
    for token in token_map.values():
        token.persist(revision)

def registry(attr, base=type):
    """Generates a meta class to index sub classes by their keys."""
    class Registry(base):
        def __init__(cls, name, bases, attrs):
            super(Registry, cls).__init__(name, bases, attrs)
            if not hasattr(cls, '__registry__'):
                cls.__registry__ = {}
            key = getattr(cls, attr)
            if key is not NotImplemented:
                assert key not in cls.__registry__
                cls.__registry__[key] = cls
        def __dispatch__(cls, key):
            try:
                return cls.__registry__[key]
            except KeyError:
                raise ValueError('Unknown %s: %s' % (attr, key))
    return Registry

def gen_repr(cls, template, *args, **kwargs):
    """Generates a string for :func:`repr`."""
    buf = io.StringIO()
    buf.write(u'<')
    buf.write(cls.__module__.decode() if kwargs.pop('full', False) else u'etc')
    buf.write(u'.')
    buf.write(cls.__name__.decode())
    if not kwargs.pop('dense', False):
        buf.write(u' ')
    buf.write(template.format(*args, **kwargs))
    options = kwargs.pop('options', [])
    for attr, value in options:
        if value is not None:
            buf.write(u' %s=%s' % (attr, value))
    buf.write(u'>')
    return buf.getvalue()

def verify_token_record(token_record, public_key_or_address, signing_algorithm='ES256K'):
    """A function for validating an individual token record and extracting
    the decoded token."""
    if 'token' not in token_record:
        raise ValueError('Token record must have a token inside it')
    token = token_record['token']
    decoded_token = verify_token(token, public_key_or_address, signing_algorithm=signing_algorithm)
    token_payload = decoded_token['payload']
    issuer_public_key = token_payload['issuer']['publicKey']
    if 'parentPublicKey' in token_record:
        if issuer_public_key == token_record['parentPublicKey']:
            pass
        else:
            raise ValueError('Verification of tokens signed with keychains is not yet supported')
    return decoded_token

def get_profile_from_tokens(token_records, public_key_or_address, hierarchical_keys=False):
    """A function for extracting a profile from a list of tokens.
    """
    if hierarchical_keys:
        raise NotImplementedError('Hierarchical key support not implemented')
    profile = {}
    for token_record in token_records:
        try:
            decoded_token = verify_token_record(token_record, public_key_or_address)
        except ValueError:
            continue
        else:
            if 'payload' in decoded_token:
                if 'claim' in decoded_token['payload']:
                    claim = decoded_token['payload']['claim']
                    profile.update(claim)
    return profile

def resolve_zone_file_to_profile(zone_file, address_or_public_key):
    """Resolves a zone file to a profile and checks to makes sure the tokens
    are signed with a key that corresponds to the address or public key
    provided."""
    if is_profile_in_legacy_format(zone_file):
        return zone_file
    try:
        token_file_url = get_token_file_url_from_zone_file(zone_file)
    except Exception as e:
        raise Exception('Token file URL could not be extracted from zone file')
    try:
        r = requests.get(token_file_url)
    except Exception as e:
        raise Exception('Token could not be acquired from token file URL')
    try:
        profile_token_records = json.loads(r.text)
    except ValueError:
        raise Exception('Token records could not be extracted from token file')
    try:
        profile = get_profile_from_tokens(profile_token_records, address_or_public_key)
    except Exception as e:
        raise Exception('Profile could not be extracted from token records')
    return profile

