    removed."""
    return '&'.join([q for q in query.split('&') if not (q.startswith('_k=') or q.startswith('_e=') or q.startswith('_s'))])

def fost_hmac_url_signature(key, secret, host, path, query_string, expires):
    """Return a signature that corresponds to the signed URL."""
    if query_string:
        document = '%s%s?%s\n%s' % (host, path, query_string, expires)
    else:
        document = '%s%s\n%s' % (host, path, expires)
    signature = sha1_hmac(secret, document)
    return signature

def fost_hmac_request_signature(secret, method, path, timestamp, headers={}, body=''):
    """Calculate the signature for the given secret and arguments."""
    signed_headers, header_values = ('X-FOST-Headers', [])
    for header, value in headers.items():
        signed_headers += ' ' + header
        header_values.append(value)
    return fost_hmac_request_signature_with_headers(secret, method, path, timestamp, [signed_headers] + header_values, body)

def get_order(membersuite_id, client=None):
