def expand(directory: str) -> str:
    """Apply expanduser and expandvars to directory to expand '~' and env vars."""
    temp1 = os.path.expanduser(directory)
    return os.path.expandvars(temp1)

def generate_downloader(headers: Dict[str, str], args: Any, max_per_hour: int=30) -> Callable[..., None]:
    """Create function to download with rate limiting and text progress."""
    def _downloader(url: str, dest: str) -> None:
        @rate_limited(max_per_hour, args)
        def _rate_limited_download() -> None:
            parent = os.path.dirname(dest)
            if not os.path.exists(parent):
                os.makedirs(parent)
            response = requests.get(url, headers=headers, stream=True)
            LOG.info(f"Downloading from '{url}'.")
            LOG.info(f"Trying to save to '{dest}'.")
            length = response.headers.get('content-length')
            if length is None:
                total_length = 0
            else:
                total_length = int(length)
            expected_size = total_length / CHUNK_SIZE + 1
            chunks = response.iter_content(chunk_size=CHUNK_SIZE)
            open(dest, 'a', encoding=FORCED_ENCODING).close()
            with open(dest, 'wb') as stream:
                for chunk in tui.progress.bar(chunks, expected_size=expected_size):
                    if not chunk:
                        return
                    stream.write(chunk)
                    stream.flush()
        _rate_limited_download()
    return _downloader

def parse_int_string(int_string: str) -> List[int]:
    """Given a string like "1 23 4-8 32 1", return a unique list of those integers in the string and
    the integers in the ranges in the string.
    Non-numbers ignored. Not necessarily sorted"""
    cleaned = ' '.join(int_string.strip().split())
    cleaned = cleaned.replace(' - ', '-')
    cleaned = cleaned.replace(',', ' ')
    tokens = cleaned.split(' ')
    indices: Set[int] = set()
    for token in tokens:
        if '-' in token:
            endpoints = token.split('-')
            if len(endpoints) != 2:
                LOG.info(f"Dropping '{token}' as invalid - weird range.")
                continue
            start = int(endpoints[0])
            end = int(endpoints[1]) + 1
            indices = indices.union(indices, set(range(start, end)))
        else:
            try:
                indices.add(int(token))
            except ValueError:
                LOG.info(f"Dropping '{token}' as invalid - not an int.")
    return list(indices)

def random_line(file_path: str, encoding: str=FORCED_ENCODING) -> str:
    """Get random line from a file."""
    line_num = 0
    selected_line = ''
    with open(file_path, encoding=encoding) as stream:
        while True:
            line = stream.readline()
            if not line:
                break
            line_num += 1
            if random.uniform(0, line_num) < 1:
                selected_line = line
    return selected_line.strip()

def listify(generator_func):
    """Converts generator functions into list returning functions.

    @listify
    def test():
        yield 1
    test()
    # => [1]"""
    def list_func(*args, **kwargs):
        return degenerate(generator_func(*args, **kwargs))
    return list_func

def int_flags(flags, mapper=const.PERM_STRING_MAP):
    """Converts string permission flags into integer permission flags as
    specified in const.PERM_STRING_MAP
    Arguments:
        - flags <str>: one or more flags
            For example: "crud" or "ru" or "r"
        - mapper <list=const.PERM_STRING_MAP>: a list containing tuples mapping
            int permission flag to string permission flag. If not specified will
            default to const.PERM_STRING_MAP.
    Returns:
        - int"""
    r = 0
    if not flags:
        return r
    if isinstance(flags, six.integer_types):
        return flags
    if not isinstance(flags, six.string_types):
        raise TypeError('`flags` needs to be a string or integer type')
    for f in flags:
        for f_i, f_s in mapper:
            if f_s == f:
                r = r | f_i
    return r

def format_account(service_name, data):
    """Given profile data and the name of a
    social media service, format it for
    the zone file.

    @serviceName: name of the service
    @data: legacy profile verification

    Returns the formatted account on success,
    as a dict."""
    if 'username' not in data:
        raise KeyError('Account is missing a username')
    account = {'@type': 'Account', 'service': service_name, 'identifier': data['username'], 'proofType': 'http'}
    if data.has_key(service_name) and data[service_name].has_key('proof') and data[service_name]['proof'].has_key('url'):
        account['proofUrl'] = data[service_name]['proof']['url']
    return account

