def repo_url_to_project_name(url, normalize=True):
    """Extract project title from GIT repository URL, either https or ssh.
    Should work fine with github, bitbucket
    :rtype: str
    :param url: Url of the repository
    :param normalize: Title-case the project name
    :return: Project name"""
    if url.startswith('http'):
        http_url = urlparse(url)
        name = http_url.path.replace('.git', '').lstrip('/').strip()
    else:
        name = url[url.index(':') + 1:].replace('.git', '').strip()
    if normalize:
        return name.replace('/', ' / ').title()
    return name

def get_product(membersuite_id, client=None):
    """Return a Product object by ID.
    """
    if not membersuite_id:
        return None
    client = client or get_new_client(request_session=True)
    object_query = "SELECT Object() FROM PRODUCT WHERE ID = '{}'".format(membersuite_id)
    result = client.execute_object_query(object_query)
    msql_result = result['body']['ExecuteMSQLResult']
    if msql_result['Success']:
        membersuite_object_data = msql_result['ResultValue']['SingleObject']
