def py_doc_trim(docstring):
    """Trim a python doc string.

    This example is nipped from https://www.python.org/dev/peps/pep-0257/,
    which describes how to conventionally format and trim docstrings.

    It has been modified to replace single newlines with a space, but leave
    multiple consecutive newlines in tact."""
    if not docstring:
        return ''
    lines = docstring.expandtabs().splitlines()
    indent = sys.maxint
    for line in lines[1:]:
        stripped = line.lstrip()
        if stripped:
            indent = min(indent, len(line) - len(stripped))
    trimmed = [lines[0].strip()]
    if indent < sys.maxint:
        for line in lines[1:]:
            trimmed.append(line[indent:].rstrip())
    while trimmed and (not trimmed[-1]):
        trimmed.pop()
    while trimmed and (not trimmed[0]):
        trimmed.pop(0)
    joined = '\n'.join(trimmed)
    return newline_substitution_regex.sub(' ', joined)

def generate_doc_dict(module, user):
    """Compile a Pale module's documentation into a python dictionary.

    The returned dictionary is suitable to be rendered by a JSON formatter,
    or passed to a template engine, or manipulated in some other way."""
    from pale import extract_endpoints, extract_resources, is_pale_module
    if not is_pale_module(module):
        raise ValueError('The passed in `module` (%s) is not a pale module. `paledoc`\n                only works on modules with a `_module_type` set to equal\n                `pale.ImplementationModule`.')
    module_endpoints = extract_endpoints(module)
    ep_doc = {ep._route_name: document_endpoint(ep) for ep in module_endpoints}
    ep_doc_filtered = {}
    for endpoint in ep_doc:
        if ep_doc[endpoint].get('requires_permission') != None and user != None and user.is_admin or ep_doc[endpoint].get('requires_permission') == None:
            ep_doc_filtered[endpoint] = ep_doc[endpoint]
    module_resources = extract_resources(module)
    res_doc = {r._value_type: document_resource(r) for r in module_resources}
    return {'endpoints': ep_doc_filtered, 'resources': res_doc}

def document_endpoint(endpoint):
    """Extract the full documentation dictionary from the endpoint."""
    descr = clean_description(py_doc_trim(endpoint.__doc__))
    docs = {'name': endpoint._route_name, 'http_method': endpoint._http_method, 'uri': endpoint._uri, 'description': descr, 'arguments': extract_endpoint_arguments(endpoint), 'returns': format_endpoint_returns_doc(endpoint)}
    if hasattr(endpoint, '_success'):
        docs['success'] = endpoint._success
    if hasattr(endpoint, '_requires_permission'):
        docs['requires_permission'] = endpoint._requires_permission
    return docs

def extract_endpoint_arguments(endpoint):
    """Extract the argument documentation from the endpoint."""
    ep_args = endpoint._arguments
    if ep_args is None:
        return None
    arg_docs = {k: format_endpoint_argument_doc(a) for k, a in ep_args.iteritems()}
    return arg_docs

def format_endpoint_returns_doc(endpoint):
    """Return documentation about the resource that an endpoint returns."""
    description = clean_description(py_doc_trim(endpoint._returns._description))
    return {'description': description, 'resource_name': endpoint._returns._value_type, 'resource_type': endpoint._returns.__class__.__name__}

def safely_decode(unicode_or_str, encoding='utf-8'):
    """Decodes byte <str> into <unicode>. Ignores any non-utf8 chars in <str>s"""
    if isinstance(unicode_or_str, unicode):
        ustr = unicode_or_str
    elif isinstance(unicode_or_str, str):
        ustr = unicode_or_str.decode(encoding, 'ignore')
    else:
        raise Exception(u'Not of type unicode or str')
    return ustr

def safely_encode(unicode_or_str, encoding='utf-8'):
    """Encodes <unicode> into byte <str>. Replaces any non utf8 chars"""
    if isinstance(unicode_or_str, unicode):
        rstr = unicode_or_str.encode(encoding, 'replace')
    elif isinstance(unicode_or_str, str):
        rstr = unicode_or_str
    else:
        raise Exception(u'Not of type unicode or str')
    return rstr

def _get_module_name_from_fname(fname):
    """Get module name from module file name."""
    fname = fname.replace('.pyc', '.py')
    for mobj in sys.modules.values():
        if hasattr(mobj, '__file__') and mobj.__file__ and (mobj.__file__.replace('.pyc', '.py') == fname):
            module_name = mobj.__name__
            return module_name
    raise RuntimeError('Module could not be found')

