def booleanize(truthy):
    """Smartly converts argument to true or false. Strings and variants of
    'true' and 'false' convert to appropriate types, along with normal
    bool() like conversions."""
    if truthy is None:
        return False
    elif isinstance(truthy, basestring):
        if truthy:
            try:
                return bool(distutils.util.strtobool(truthy))
            except ValueError:
                return True
        else:
            return False
    elif is_collection(truthy):
        return not is_empty(truthy)
    else:
        return bool(truthy)

def conv(arg, default=None, func=None):
    """essentially, the generalization of

    arg if arg else default

    or

    func(arg) if arg else default"""
    if func:
        return func(arg) if arg else default
    else:
        return arg if arg else default

def check_vprint(s, vprinter):
    """checked verbose printing"""
    if vprinter is True:
        print(s)
    elif callable(vprinter):
        vprinter(s)

def parse_utuple(s, urx, length=2):
    """parse a string into a list of a uniform type"""
    if type(urx) != str:
        urx = urx.pattern
    if length is not None and length < 1:
        raise ValueError('invalid length: {}'.format(length))
    if length == 1:
        rx = '^ *\\( *{urx} *,? *\\) *$'.format(urx=urx)
    elif length is None:
        rx = '^ *\\( *(?:{urx} *, *)*{urx} *,? *\\) *$'.format(urx=urx)
    else:
        rx = '^ *\\( *(?:{urx} *, *){{{rep1}}}{urx} *,? *\\) *$'.format(rep1=length - 1, urx=urx)
    return re.match(rx, s)

def parse_numtuple(s, intype, length=2, scale=1):
    """parse a string into a list of numbers of a type"""
    if intype == int:
        numrx = intrx_s
    elif intype == float:
        numrx = fltrx_s
    else:
        raise NotImplementedError('Not implemented for type: {}'.format(intype))
    if parse_utuple(s, numrx, length=length) is None:
        raise ValueError('{} is not a valid number tuple.'.format(s))
    return [x * scale for x in evalt(s)]

def parse_ctuple(s, length=2):
    """parse a string of acceptable colors into matplotlib, that is, either
    strings, or three tuples of rgb. Don't quote strings."""
    if parse_utuple(s, colrx_s, length=length) is None:
        raise ValueError('{} is not a valid color tuple.'.format(s))
    s = quote_subs(s, colorfix=True)
    return evalt(s)

def parse_stuple(s, length=2):
    """parse a string of strings. Don't quote strings"""
    if parse_utuple(s, isrx_s, length=length) is None:
        raise ValueError('{} is not a valid string tuple.'.format(s))
    s = quote_subs(s)
    return evalt(s)

def parse_colors(s, length=1):
    """helper for parsing a string that can be either a matplotlib
    color or be a tuple of colors. Returns a tuple of them either
    way."""
    if length and length > 1:
        return parse_ctuple(s, length=length)
    if re.match('^ *{} *$'.format(isrx_s), s):
        return [s]
    elif re.match('^ *{} *$'.format(rgbrx_s), s):
        return [eval(s)]
    else:
        return parse_ctuple(s, length=length)

def parse_qs(s, rx, parsef=None, length=2, quote=False):
    """helper for parsing a string that can both rx or parsef
    which is obstensibly the parsef for rx.

    Use parse colors for color tuples. This won't work with
    those."""
    if type(rx) != str:
        rx = rx.pattern
    if re.match(' *\\(.*\\)', s):
        if not parsef:
            if parse_utuple(s, rx, length=length):
                if quote:
                    s = quote_subs(s)
                return evalt(s)
            else:
                raise ValueError('{} did is not a valid tuple of {}'.format(s, rx))
        else:
            return parsef(s, length=length)
    elif re.match('^ *{} *$'.format(rx), s):
        if quote:
            return eval('["{}"]'.format(s))
        return eval('[{}]'.format(s))
    else:
        raise ValueError("{} does not match '{}' or the passed parsef".format(s, rx))

def destr(d, *l):
    """destructure a dict (like take, but return a list)"""
    if type(l[0]) is not str:
        l = l[0]
    return [d[i] for i in l]

def takef(d, l, val=None):
    """take(f) a list of keys and fill in others with val"""
    return {i: d[i] if i in d else val for i in l}

def mk_getkw(kw, defaults, prefer_passed=False):
    """a helper for generating a function for reading keywords in
    interface functions with a dictionary with defaults

    expects the defaults dictionary to have keywords you request.

    example:
    defaults = dict(a='a',b=3);
    def bigfunc(**kw):
        getkw=mk_getkw(kw,defaults);

        # I want the callers' `a', or the default if s/he doesn't
        # supply it
        a=getkw('a');
        c = [a]*getkw('b');
        return c,c[0];

    Option:
        prefer_passed -- use "l in kw" only, not test."""
    def getkw(*ls):
        r = [kw[l] if test(kw, l) else defaults[l] for l in ls]
        if len(r) == 1:
            return r[0]
        return r
    def getkw_prefer_passed(*ls):
        r = [kw[l] if l in kw else defaults[l] for l in ls]
        if len(r) == 1:
            return r[0]
        return r
    return getkw if not prefer_passed else getkw_prefer_passed

def trace_module(no_print=True):
    """Trace my_module exceptions."""
    pwd = os.path.dirname(__file__)
    script_name = os.path.join(pwd, 'test_my_module.py')
    with pexdoc.ExDocCxt() as exdoc_obj:
        if pytest.main(['-s', '-vv', '-x', '{0}'.format(script_name)]):
            raise RuntimeError('Tracing did not complete successfully')
    if not no_print:
        module_prefix = 'docs.support.my_module.'
        callable_names = ['func', 'MyClass.value']
        for callable_name in callable_names:
            callable_name = module_prefix + callable_name
            print('\nCallable: {0}'.format(callable_name))
            print(exdoc_obj.get_sphinx_doc(callable_name, width=70))
            print('\n')
    return copy.copy(exdoc_obj)

def split_key(key):
    """Splits a node key."""
    if key == KEY_SEP:
        return ()
    key_chunks = tuple(key.strip(KEY_SEP).split(KEY_SEP))
    if key_chunks[0].startswith(KEY_SEP):
        return (key_chunks[0][len(KEY_SEP):],) + key_chunks[1:]
    else:
        return key_chunks

def register_to_sys_with_admin_list(class_inst, admin_list=None, is_normal_admin_needed=False):
    """:param class_inst: model class
    :param admin_list: admin class
    :param is_normal_admin_needed: is normal admin registration needed
    :return:"""
    if admin_list is None:
        admin_class = get_valid_admin_class_with_list([], class_inst)
    else:
        admin_class = get_valid_admin_class_with_list(admin_list, class_inst)
    if is_normal_admin_needed:
        register_all_type_of_admin(admin_class, class_inst)
    else:
        register_admin(admin_class, class_inst)

def register_all_in_module(module_instance, exclude_name_list=[], admin_class_list=None):
    """:param module_instance: mostly the models module
    :param exclude_name_list: class does not need to register or is already registered
    :param admin_class_list:
    :return:"""
    class_list = []
    for name, obj in inspect.getmembers(module_instance):
        if inspect.isclass(obj):
            if obj.__name__ in exclude_name_list:
                continue
            class_list.append(obj)
    register_all(class_list, admin_class_list)

def _create_argument_value_pairs(func, *args, **kwargs):
    """Create dictionary with argument names as keys and their passed values as values.

    An empty dictionary is returned if an error is detected, such as more
    arguments than in the function definition, argument(s) defined by position
    and keyword, etc."""
    try:
        arg_dict = signature(func).bind_partial(*args, **kwargs).arguments
    except TypeError:
        return dict()
    arguments = signature(func).parameters
    for arg_name in arguments:
        if arguments[arg_name].default != Parameter.empty and arguments[arg_name].name not in arg_dict:
            arg_dict[arguments[arg_name].name] = arguments[arg_name].default
    return arg_dict

def _get_contract_exception_dict(contract_msg):
    """Generate message for exception."""
    start_token = '[START CONTRACT MSG: '
    stop_token = '[STOP CONTRACT MSG]'
    if contract_msg.find(start_token) == -1:
        return {'num': 0, 'msg': 'Argument `*[argument_name]*` is not valid', 'type': RuntimeError, 'field': 'argument_name'}
    msg_start = contract_msg.find(start_token) + len(start_token)
    contract_msg = contract_msg[msg_start:]
    contract_name = contract_msg[:contract_msg.find(']')]
    contract_msg = contract_msg[contract_msg.find(']') + 1:contract_msg.find(stop_token)]
    exdict = _CUSTOM_CONTRACTS[contract_name]
    for exvalue in exdict.values():
        if exvalue['msg'] == contract_msg:
            return exvalue

def _get_custom_contract(param_contract):
    """Return True if parameter contract is a custom contract, False otherwise."""
    if not isinstance(param_contract, str):
        return None
    for custom_contract in _CUSTOM_CONTRACTS:
        if re.search('\\b{0}\\b'.format(custom_contract), param_contract):
            return custom_contract
    return None

def _get_num_contracts(contracts_list, param_name):
    """Return the number of simple/default contracts.

    Simple contracts are the ones which raise a RuntimeError with message
    'Argument `*[argument_name]*` is not valid'"""
    msg = 'Argument `*[argument_name]*` is not valid'
    return sum([1 if item['msg'] == msg.replace('*[argument_name]*', param_name) else 0 for item in contracts_list])

def _get_replacement_token(msg):
    """Extract replacement token from exception message."""
    return None if not re.search('\\*\\[[\\w|\\W]+\\]\\*', msg) else re.search('\\*\\[[\\w|\\W]+\\]\\*', msg).group()[2:-2]

def _parse_new_contract_args(*args, **kwargs):
    """Parse argument for new_contract() function."""
    if not args and (not kwargs):
        return [{'name': 'argument_invalid', 'msg': 'Argument `*[argument_name]*` is not valid', 'type': RuntimeError}]
    if len(args) > 1 or (len(args) == 1 and kwargs):
        raise TypeError('Illegal custom contract exception definition')
    if len(args) == 1:
        return [dict([('name', 'default')] + list(_format_arg(args[0]).items()))]
    return [dict([('name', name)] + list(_format_arg(kwargs[name]).items())) for name in sorted(list(kwargs.keys()))]

def _validate_fname(fname, arg_name):
    """Validate that a string is a valid file name."""
    if fname is not None:
        msg = 'Argument `{0}` is not valid'.format(arg_name)
        if not isinstance(fname, str) or (isinstance(fname, str) and '\x00' in fname):
            raise RuntimeError(msg)
        try:
            if not os.path.exists(fname):
                os.access(fname, os.W_OK)
        except (TypeError, ValueError):
            raise RuntimeError(msg)

def apply_dict_default(dictionary, arg, default):
    """Used to avoid generating a defaultdict object, or assigning defaults to a dict-like object

    apply_dict_default({}, 'test', list)
    # => {'test': []}

    apply_dict_default({'test': 'ok'}, 'test', list)
    # => {'test': 'ok'}"""
    if arg not in dictionary:
        if hasattr(default, '__call__'):
            default = restrict_args(default, arg)
        dictionary[arg] = default
    return dictionary

def chain_sub_regexes(phrase, *regex_sub_pairs):
    """Allow for a series of regex substitutions to occur

    chain_sub_regexes('test ok', (' ', '_'), ('k$', 'oo'))
    # => 'test_ooo'"""
    for regex, substitution in regex_sub_pairs:
        if isinstance(regex, basestring):
            regex = re.compile(regex)
        phrase = regex.sub(substitution, phrase)
    return phrase

def extract_endpoints(api_module):
    """Return the endpoints from an API implementation module.

    The results returned by this are used to populate your HTTP layer's
    route handler, as well as by the documentation generator."""
    if not hasattr(api_module, 'endpoints'):
        raise ValueError("pale.extract_endpoints expected the passed in api_module to have an `endpoints` attribute, but it didn't!")
    endpoints = api_module.endpoints
    if isinstance(endpoints, types.ModuleType):
        classes = [v for k, v in inspect.getmembers(endpoints, inspect.isclass)]
    elif isinstance(endpoints, (list, tuple)):
        classes = endpoints
    else:
        raise ValueError('Endpoints is not a module or list type!')
    instances = []
    for cls in classes:
        if cls not in (Endpoint, PatchEndpoint, PutResourceEndpoint) and Endpoint in inspect.getmro(cls):
            source_code = inspect.getsource(cls)
            if '@requires_permission' in source_code:
                permission_match = re.search('@requires_permission\\(\\[?[\\\'\\"]+(\\w+)[\\\'\\"]+', source_code)
                if permission_match != None:
                    cls._requires_permission = permission_match.group(1)
            instances.append(cls())
    return instances

def bind_blueprint(pale_api_module, flask_blueprint):
    """Binds an implemented pale API module to a Flask Blueprint."""
    if not isinstance(flask_blueprint, Blueprint):
        raise TypeError('pale.flask_adapter.bind_blueprint expected the passed in flask_blueprint to be an instance of Blueprint, but it was an instance of %s instead.' % (type(flask_blueprint),))
    if not pale.is_pale_module(pale_api_module):
        raise TypeError('pale.flask_adapter.bind_blueprint expected the passed in pale_api_module to be a module, and to have a _module_type defined to equal pale.ImplementationModule, but it was an instance of %s instead.' % (type(pale_api_module),))
    endpoints = pale.extract_endpoints(pale_api_module)
    for endpoint in endpoints:
        endpoint._set_response_class(RESPONSE_CLASS)
        method = [endpoint._http_method]
        name = endpoint._route_name
        handler = endpoint._execute
        flask_blueprint.add_url_rule(endpoint._uri, name, view_func=ContextualizedHandler(handler), methods=method)

def _build_exclusion_list(exclude):
    """Build file names list of modules to exclude from exception handling."""
    mod_files = []
    if exclude:
        for mod in exclude:
            mdir = None
            mod_file = None
            for token in mod.split('.'):
                try:
                    mfile, mdir, _ = imp.find_module(token, mdir and [mdir])
                    if mfile:
                        mod_file = mfile.name
                        mfile.close()
                except ImportError:
                    msg = 'Source for module {mod_name} could not be found'
                    raise ValueError(msg.format(mod_name=mod))
            if mod_file:
                mod_files.append(mod_file.replace('.pyc', '.py'))
    return mod_files

def _invalid_frame(fobj):
    """Select valid stack frame to process."""
    fin = fobj.f_code.co_filename
    invalid_module = any([fin.endswith(item) for item in _INVALID_MODULES_LIST])
    return invalid_module or not os.path.isfile(fin)

def _merge_cdicts(self, clut, exdict, separator):
    """Merge callable look-up tables from two objects."""
    if not self._full_cname:
        return
    repl_dict = {}
    for key, value in _sorted_keys_items(clut):
        otoken = self._clut.get(key, None)
        if not otoken:
            otoken = str(len(self._clut))
            self._clut[key] = otoken
        repl_dict[value] = otoken
    for fdict in exdict.values():
        for entry in fdict.values():
            olist = []
            for item in entry['function']:
                if item is None:
                    olist.append(None)
                else:
                    itokens = item.split(separator)
                    itokens = [repl_dict.get(itoken) for itoken in itokens]
                    olist.append(separator.join(itokens))
            entry['function'] = olist

def _merge_ex_dicts(sexdict, oexdict):
    """Merge callable look-up tables from two objects."""
    for okey, ovalue in oexdict.items():
        if okey in sexdict:
            svalue = sexdict[okey]
            for fkey, fvalue in ovalue.items():
                if fkey not in svalue:
                    sexdict[okey][fkey] = fvalue
                else:
                    iobj = zip(fvalue['function'], fvalue['raised'])
                    for func, raised in iobj:
                        if func not in sexdict[okey][fkey]['function']:
                            sexdict[okey][fkey]['function'].append(func)
                            sexdict[okey][fkey]['raised'].append(raised)
                        else:
                            idx = sexdict[okey][fkey]['function'].index(func)
                            sraised = sexdict[okey][fkey]['raised'][idx]
                            if sraised or raised:
                                sexdict[okey][fkey]['raised'][idx] = True
        else:
            sexdict[okey] = ovalue

def _sorted_keys_items(dobj):
    """Return dictionary items sorted by key."""
    keys = sorted(dobj.keys())
    for key in keys:
        yield (key, dobj[key])

def degenerate(enumerable):
    """Converts generators to lists

    degenerate(xrange(2))
    # => [0, 1]"""
    if isinstance(enumerable, xrange) or inspect.isgeneratorfunction(enumerable) or inspect.isgenerator(enumerable):
        return list(enumerable)
    return enumerable

def batch(enumerable, batch_size):
    """Breaks enumerable argument into batch size enumerable pieces. The last chunk can
    be of any length up to batch_size.

    batch(xrange(5), 3)
    # => [0, 1, 2], [3, 4]"""
    batch_size = max(int(batch_size), 1)
    try:
        enumerable.__getitem__
        total_size = len(enumerable)
    except (TypeError, AttributeError):
        enumerable = list(enumerable)
        total_size = len(enumerable)
    if total_size == 0:
        yield tuple()
    try:
        for batch_index in xrange(0, total_size, batch_size):
            yield enumerable[batch_index:min(batch_index + batch_size, total_size)]
    except TypeError:
        for batch_start in xrange(0, total_size, batch_size):
            yield tuple(islice(enumerable, batch_start, min(batch_start + batch_size, total_size)))

def options_string_builder(option_mapping, args):
    """Return arguments for CLI invocation of kal."""
    options_string = ''
    for option, flag in option_mapping.items():
        if option in args:
            options_string += str(' %s %s' % (flag, str(args[option])))
    return options_string

def build_kal_scan_band_string(kal_bin, band, args):
    """Return string for CLI invocation of kal, for band scan."""
    option_mapping = {'gain': '-g', 'device': '-d', 'error': '-e'}
    if not sanity.scan_band_is_valid(band):
        err_txt = 'Unsupported band designation: %' % band
        raise ValueError(err_txt)
    base_string = '%s -v -s %s' % (kal_bin, band)
    base_string += options_string_builder(option_mapping, args)
    return base_string

def build_kal_scan_channel_string(kal_bin, channel, args):
    """Return string for CLI invocation of kal, for channel scan."""
    option_mapping = {'gain': '-g', 'device': '-d', 'error': '-e'}
    base_string = '%s -v -c %s' % (kal_bin, channel)
    base_string += options_string_builder(option_mapping, args)
    return base_string

def determine_final_freq(base, direction, modifier):
    """Return integer for frequency."""
    result = 0
    if direction == '+':
        result = base + modifier
    elif direction == '-':
        result = base - modifier
    return result

def determine_device(kal_out):
    """Extract and return device from scan results."""
    device = ''
    while device == '':
        for line in kal_out.splitlines():
            if 'Using device ' in line:
                device = str(line.split(' ', 2)[-1])
        if device == '':
            device = None
    return device

def extract_value_from_output(canary, split_offset, kal_out):
    """Return value parsed from output.

    Args:
        canary(str): This string must exist in the target line.
        split_offset(int): Split offset for target value in string.
        kal_out(int): Output from kal."""
    retval = ''
    while retval == '':
        for line in kal_out.splitlines():
            if canary in line:
                retval = str(line.split()[split_offset])
        if retval == '':
            retval = None
    return retval

def determine_chan_detect_threshold(kal_out):
    """Return channel detect threshold from kal output."""
    channel_detect_threshold = ''
    while channel_detect_threshold == '':
        for line in kal_out.splitlines():
            if 'channel detect threshold: ' in line:
                channel_detect_threshold = str(line.split()[-1])
        if channel_detect_threshold == '':
            print('Unable to parse sample rate')
            channel_detect_threshold = None
    return channel_detect_threshold

def determine_band_channel(kal_out):
    """Return band, channel, target frequency from kal output."""
    band = ''
    channel = ''
    tgt_freq = ''
    while band == '':
        for line in kal_out.splitlines():
            if 'Using ' in line and ' channel ' in line:
                band = str(line.split()[1])
                channel = str(line.split()[3])
                tgt_freq = str(line.split()[4]).replace('(', '').replace(')', '')
        if band == '':
            band = None
    return (band, channel, tgt_freq)

def parse_kal_channel(kal_out):
    """Parse kal channel scan output."""
    scan_band, scan_channel, tgt_freq = determine_band_channel(kal_out)
    kal_data = {'device': determine_device(kal_out), 'sample_rate': determine_sample_rate(kal_out), 'gain': determine_scan_gain(kal_out), 'band': scan_band, 'channel': scan_channel, 'frequency': tgt_freq, 'avg_absolute_error': determine_avg_absolute_error(kal_out), 'measurements': get_measurements_from_kal_scan(kal_out), 'raw_scan_result': kal_out}
    return kal_data

def get_measurements_from_kal_scan(kal_out):
    """Return a list of all measurements from kalibrate channel scan."""
    result = []
    for line in kal_out.splitlines():
        if 'offset ' in line:
            p_line = line.split(' ')
            result.append(p_line[-1])
    return result

def login_to_portal(username, password, client, retries=2, delay=0):
    """Log `username` into the MemberSuite Portal.

    Returns a PortalUser object if successful, raises
    LoginToPortalError if not.

    Will retry logging in if a GeneralException occurs, up to `retries`.
    Will pause `delay` seconds between retries."""
    if not client.session_id:
        client.request_session()
    concierge_request_header = client.construct_concierge_header(url='http://membersuite.com/contracts/IConciergeAPIService/LoginToPortal')
    attempts = 0
    while attempts < retries:
        if attempts:
            time.sleep(delay)
        result = client.client.service.LoginToPortal(_soapheaders=[concierge_request_header], portalUserName=username, portalPassword=password)
        login_to_portal_result = result['body']['LoginToPortalResult']
        if login_to_portal_result['Success']:
            portal_user = login_to_portal_result['ResultValue']['PortalUser']
            session_id = get_session_id(result=result)
            return PortalUser(membersuite_object_data=portal_user, session_id=session_id)
        else:
            attempts += 1
            try:
                error_code = login_to_portal_result['Errors']['ConciergeError'][0]['Code']
            except IndexError:
                continue
            else:
                if attempts < retries and error_code == 'GeneralException':
                    continue
    raise LoginToPortalError(result=result)

def get_user_for_membersuite_entity(membersuite_entity):
    """Returns a User for `membersuite_entity`.

    membersuite_entity is any MemberSuite object that has the fields
    membersuite_id, email_address, first_name, and last_name, e.g.,
    PortalUser or Individual."""
    user = None
    user_created = False
    user_username = generate_username(membersuite_entity)
    try:
        user = User.objects.get(username=user_username)
    except User.DoesNotExist:
        pass
    if not user:
        try:
            user = User.objects.filter(email=membersuite_entity.email_address)[0]
        except IndexError:
            pass
    if not user:
        user = User.objects.create(username=user_username, email=membersuite_entity.email_address, first_name=membersuite_entity.first_name, last_name=membersuite_entity.last_name)
        user_created = True
    return (user, user_created)

def metaclass(*metaclasses):
    """Create the class using all metaclasses.

    Args:
        metaclasses: A tuple of metaclasses that will be used to generate and
            replace a specified class.

    Returns:
        A decorator that will recreate the class using the specified
        metaclasses."""
    def _inner(cls):
        metabases = tuple(collections.OrderedDict(((c, None) for c in metaclasses + (type(cls),))).keys())
        _Meta = metabases[0]
        for base in metabases[1:]:
            class _Meta(base, _Meta):
                pass
        return six.add_metaclass(_Meta)(cls)
    return _inner

def is_dir(path):
    """Determine if a Path or string is a directory on the file system."""
    try:
        return path.expanduser().absolute().is_dir()
    except AttributeError:
        return os.path.isdir(os.path.abspath(os.path.expanduser(str(path))))

def is_file(path):
    """Determine if a Path or string is a file on the file system."""
    try:
        return path.expanduser().absolute().is_file()
    except AttributeError:
        return os.path.isfile(os.path.abspath(os.path.expanduser(str(path))))

def exists(path):
    """Determine if a Path or string is an existing path on the file system."""
    try:
        return path.expanduser().absolute().exists()
    except AttributeError:
        return os.path.exists(os.path.abspath(os.path.expanduser(str(path))))

def add_to_dict_val_set(dict_obj, key, val):
    """Adds the given val to the set mapped by the given key.
    If the key is missing from the dict, the given mapping is added.

    Example
    -------
    >>> dict_obj = {'a': set([1, 2])}
    >>> add_to_dict_val_set(dict_obj, 'a', 2)
    >>> print(dict_obj['a'])
    {1, 2}
    >>> add_to_dict_val_set(dict_obj, 'a', 3)
    >>> print(dict_obj['a'])
    {1, 2, 3}"""
    try:
        dict_obj[key].add(val)
    except KeyError:
        dict_obj[key] = set([val])

def add_many_to_dict_val_set(dict_obj, key, val_list):
    """Adds the given value list to the set mapped by the given key.
    If the key is missing from the dict, the given mapping is added.

    Example
    -------
    >>> dict_obj = {'a': set([1, 2])}
    >>> add_many_to_dict_val_set(dict_obj, 'a', [2, 3])
    >>> print(dict_obj['a'])
    {1, 2, 3}
    >>> add_many_to_dict_val_set(dict_obj, 'b', [2, 3])
    >>> print(dict_obj['b'])
    {2, 3}"""
    try:
        dict_obj[key].update(val_list)
    except KeyError:
        dict_obj[key] = set(val_list)

def get_keys_of_max_n(dict_obj, n):
    """Returns the keys that maps to the top n max values in the given dict.

    Example:
    --------
    >>> dict_obj = {'a':2, 'b':1, 'c':5}
    >>> get_keys_of_max_n(dict_obj, 2)
    ['a', 'c']"""
    return sorted([item[0] for item in sorted(dict_obj.items(), key=lambda item: item[1], reverse=True)[:n]])

def sum_dicts(dicts, normalize=False):
    """Sums the given dicts into a single dict mapping each numberic-valued
    key to the sum of its mappings in all given dicts. Keys mapping to
    non-numeric values retain the last value (by the given order).

    Parameters
    ----------
    dicts : list
        A list of dict objects mapping each key to an numeric value.
    normalize : bool, default False
        Indicated whether to normalize all values by value sum.

    Returns
    -------
    dict
        A dict where each key is mapped to the sum of its mappings in all
        given dicts."""
    sum_dict = {}
    for dicti in dicts:
        for key in dicti:
            val = dicti[key]
            if isinstance(val, numbers.Number):
                sum_dict[key] = sum_dict.get(key, 0) + val
            else:
                sum_dict[key] = val
    if normalize:
        return norm_int_dict(sum_dict)
    return sum_dict

def normalize_weekly(data):
    """Normalization for dining menu data"""
    if 'tblMenu' not in data['result_data']['Document']:
        data['result_data']['Document']['tblMenu'] = []
    if isinstance(data['result_data']['Document']['tblMenu'], dict):
        data['result_data']['Document']['tblMenu'] = [data['result_data']['Document']['tblMenu']]
    for day in data['result_data']['Document']['tblMenu']:
        if 'tblDayPart' not in day:
            continue
        if isinstance(day['tblDayPart'], dict):
            day['tblDayPart'] = [day['tblDayPart']]
        for meal in day['tblDayPart']:
            if isinstance(meal['tblStation'], dict):
                meal['tblStation'] = [meal['tblStation']]
            for station in meal['tblStation']:
                if isinstance(station['tblItem'], dict):
                    station['tblItem'] = [station['tblItem']]
    return data

def parse_to_gvid(v):
    """Parse an ACS Geoid or a GVID to a GVID"""
    from geoid.civick import GVid
    from geoid.acs import AcsGeoid
    m1 = ''
    try:
        return GVid.parse(v)
    except ValueError as e:
        m1 = str(e)
    try:
        return AcsGeoid.parse(v).convert(GVid)
    except ValueError as e:
        raise ValueError('Failed to parse to either ACS or GVid: {}; {}'.format(m1, str(e)))

def augment(module_name, base_class):
    """Call the augment() method for all of the derived classes in the module"""
    for name, cls in inspect.getmembers(sys.modules[module_name], lambda x: inspect.isclass(x) and issubclass(x, base_class)):
        if cls == base_class:
            continue
        cls.augment()

def generate_all(sumlevel, d):
    """Generate a dict that includes all of the available geoid values, with keys
    for the most common names for those values."""
    from geoid.civick import GVid
    from geoid.tiger import TigerGeoid
    from geoid.acs import AcsGeoid
    sumlevel = int(sumlevel)
    d = dict(d.items())
    if 'cousub' in d:
        d['cosub'] = d['cousub']
        del d['cousub']
    if 'blkgrp' in d:
        d['blockgroup'] = d['blkgrp']
        del d['blkgrp']
    if 'zcta5' in d:
        d['zcta'] = d['zcta5']
        del d['zcta5']
    gvid_class = GVid.resolve_summary_level(sumlevel)
    if not gvid_class:
        return {}
    geoidt_class = TigerGeoid.resolve_summary_level(sumlevel)
    geoid_class = AcsGeoid.resolve_summary_level(sumlevel)
    try:
        return dict(gvid=str(gvid_class(**d)), geoid=str(geoid_class(**d)), geoidt=str(geoidt_class(**d)))
    except:
        raise

def _generate_names():
    """Code to generate the state and county names

    >>> python -c 'import geoid; geoid._generate_names()'"""
    from ambry import get_library
    l = get_library()
    counties = l.partition('census.gov-acs-geofile-2009-geofile50-20095-50')
    states = l.partition('census.gov-acs-geofile-2009-geofile40-20095-40')
    names = {}
    for row in counties.remote_datafile.reader:
        names[row.state, row.county] = row.name
    for row in states.remote_datafile.reader:
        if row.component == '00':
            names[row.state, 0] = row.name
    pprint.pprint(names)

def toint(number):
    """Helper to return rounded int for a float or just the int it self."""
    if isinstance(number, float):
        number = round(number, 0)
    return int(number)

def goose_extractor(url):
    """webpage extraction using
    Goose Library"""
    article = Goose().extract(url=url)
    return (article.title, article.meta_description, article.cleaned_text)

def _aggregrate_scores(its, tss, num_sentences):
    """rerank the two vectors by
    min aggregrate rank, reorder"""
    final = []
    for i, el in enumerate(its):
        for j, le in enumerate(tss):
            if el[2] == le[2]:
                assert el[1] == le[1]
                final.append((el[1], i + j, el[2]))
    _final = sorted(final, key=lambda tup: tup[1])[:num_sentences]
    return sorted(_final, key=lambda tup: tup[0])

def _eval_meta_as_summary(meta):
    """some crude heuristics for now
    most are implemented on bot-side
    with domain whitelists"""
    if meta == '':
        return False
    if len(meta) > 500:
        return False
    if 'login' in meta.lower():
        return False
    return True

def summarize_url(url, num_sentences=4, fmt='default'):
    """returns: tuple containing
    * single-line summary candidate
    * key points
    in the format specified."""
    title, meta, full_text = goose_extractor(url)
    if not full_text:
        raise ArticleExtractionFail("Couldn't extract: {}".format(url))
    its = _intertext_score(full_text)
    tss = _title_similarity_score(full_text, title)
    if _eval_meta_as_summary(meta):
        summ = meta
        if tss[0][2].lower() in summ.lower():
            its, tss = _remove_title_from_tuples(its, tss)
        elif summ.lower() in tss[0][2].lower():
            summ = tss[0][2]
            its, tss = _remove_title_from_tuples(its, tss)
    else:
        summ = tss[0][2]
        its, tss = _remove_title_from_tuples(its, tss)
    scores = [score[2] for score in _aggregrate_scores(its, tss, num_sentences)]
    formatted = Formatter(scores, fmt).frmt()
    return (summ, formatted)

