    """DO NOT USE ANY MORE - DEPRECIATED!

    """
    raise Exception('This function is depreciated!')
    print('computing normal-reciprocal differences')
    def norrec_diff(x):
        """compute norrec_diff"""
        if x.shape[0] != 2:
