    """Gets the body for a license based on a license code"""
    req = requests.get('{base_url}/licenses/{license_code}'.format(base_url=BASE_URL, license_code=license_code), headers=_HEADERS)
    if req.status_code == requests.codes.ok:
        s = req.json()['body']
