        search_square = re.search('\\[(.*)\\]', s)
        license = ''
        replace_string = '{year} {name}'.format(year=date.today().year, name=_get_config_name())
        if search_curly:
            license = re.sub('\\{(.+)\\}', replace_string, s)
        elif search_square:
            license = re.sub('\\[(.+)\\]', replace_string, s)
        else:
            license = s
        return license
