def get_feature_info(feature):
    """Returns a dict with feature information"""
    dimensions = feature.findall('position')
    for dim in dimensions:
        if dim.attrib['dim'] == '0':
            rt = dim.text
        elif dim.attrib['dim'] == '1':
            mz = dim.text
    return {'rt': float(rt), 'mz': float(mz), 'charge': int(feature.find('charge').text), 'intensity': float(feature.find('intensity').text)}

def get_quantmap(consfile):
    """Returns map of isobaric quant channel names as keys, channel numbers
    values from consensus XML.
    E.g. {'113': '0',
          '114': '1',}"""
    quantmap = {}
    maplist = basereader.get_element(consfile, 'mapList')
    for mapitem in maplist:
        quantmap[mapitem.attrib['label']] = mapitem.attrib['id']
    return quantmap

def generate_top_psms(psms, protcol):
    """Fed with a psms generator, this returns the 3 PSMs with
    the highest precursor intensities (or areas, or whatever is
    given in the HEADER_PRECURSOR_QUANT"""
    top_ms1_psms = {}
    for psm in psms:
        protacc = psm[protcol]
        precursor_amount = psm[mzidtsvdata.HEADER_PRECURSOR_QUANT]
        if ';' in protacc or precursor_amount == 'NA':
            continue
        precursor_amount = float(precursor_amount)
        psm_seq = psm[mzidtsvdata.HEADER_PEPTIDE]
        try:
            peptide_area = top_ms1_psms[protacc][psm_seq]
        except KeyError:
            try:
                top_ms1_psms[protacc][psm_seq] = precursor_amount
            except KeyError:
                top_ms1_psms[protacc] = {psm_seq: precursor_amount}
        else:
            if precursor_amount > peptide_area:
                top_ms1_psms[protacc][psm_seq] = precursor_amount
    return top_ms1_psms

def add_ms1_quant_from_top3_mzidtsv(proteins, psms, headerfields, protcol):
    """Collects PSMs with the highes precursor quant values,
    adds sum of the top 3 of these to a protein table"""
    if not protcol:
        protcol = mzidtsvdata.HEADER_MASTER_PROT
    top_ms1_psms = generate_top_psms(psms, protcol)
    for protein in proteins:
        prot_acc = protein[prottabledata.HEADER_PROTEIN]
        prec_area = calculate_protein_precursor_quant(top_ms1_psms, prot_acc)
        outprotein = {k: v for k, v in protein.items()}
        outprotein[headerfields['precursorquant'][prottabledata.HEADER_AREA][None]] = str(prec_area)
        yield outprotein

def toc(tt, return_msg=False, write_msg=True, verbose=None):
    """similar to matlab toc

    SeeAlso:
        ut.tic"""
    if verbose is not None:
        write_msg = verbose
    msg, start_time = tt
    ellapsed = default_timer() - start_time
    if not return_msg and write_msg and (msg is not None):
        sys.stdout.write('...toc(%.4fs, ' % ellapsed + '"' + str(msg) + '"' + ')\n')
    if return_msg:
        return msg
    else:
        return ellapsed

def unixtime_to_datetimestr(unixtime, timefmt='%Y/%m/%d %H:%M:%S', isutc=True):
    """TODO: ranme to datetimestr"""
    try:
        if unixtime == -1:
            return 'NA'
        if unixtime is None:
            return None
        if isutc:
            return datetime.datetime.utcfromtimestamp(unixtime).strftime(timefmt)
        else:
            return datetime.datetime.fromtimestamp(unixtime).strftime(timefmt)
    except ValueError:
        raise

def instances(exp='.*'):
    """Filter list of machines matching an expression"""
    expression = re.compile(exp)
    instances = []
    for node in ec2_instances():
        if node.tags and ip(node):
            try:
                if expression.match(node.tags.get('Name')):
                    instances.append(node)
            except TypeError:
                pass
    return instances

def use(node):
    """Set the fabric environment for the specifed node"""
    try:
        role = node.tags.get('Name').split('-')[1]
        env.roledefs[role] += [ip(node)]
    except IndexError:
        pass
    env.nodes += [node]
    env.hosts += [ip(node)]

def tryload_cache(dpath, fname, cfgstr, verbose=None):
    """returns None if cache cannot be loaded"""
    try:
        return load_cache(dpath, fname, cfgstr, verbose=verbose)
    except IOError:
        return None

def tryload_cache_list(dpath, fname, cfgstr_list, verbose=False):
    """loads a list of similar cached datas. Returns flags that needs to be computed"""
    data_list = [tryload_cache(dpath, fname, cfgstr, verbose) for cfgstr in cfgstr_list]
    ismiss_list = [data is None for data in data_list]
    return (data_list, ismiss_list)

def tryload_cache_list_with_compute(use_cache, dpath, fname, cfgstr_list, compute_fn, *args):
    """tries to load data, but computes it if it can't give a compute function"""
    if use_cache is False:
        data_list = [None] * len(cfgstr_list)
        ismiss_list = [True] * len(cfgstr_list)
        data_list = compute_fn(ismiss_list, *args)
        return data_list
    else:
        data_list, ismiss_list = tryload_cache_list(dpath, fname, cfgstr_list, verbose=False)
    num_total = len(cfgstr_list)
    if any(ismiss_list):
        newdata_list = compute_fn(ismiss_list, *args)
        newcfgstr_list = util_list.compress(cfgstr_list, ismiss_list)
        index_list = util_list.list_where(ismiss_list)
        print('[cache] %d/%d cache hits for %s in %s' % (num_total - len(index_list), num_total, fname, util_path.tail(dpath)))
        for newcfgstr, newdata in zip(newcfgstr_list, newdata_list):
            save_cache(dpath, fname, newcfgstr, newdata, verbose=False)
        for index, newdata in zip(index_list, newdata_list):
            data_list[index] = newdata
    else:
        print('[cache] %d/%d cache hits for %s in %s' % (num_total, num_total, fname, util_path.tail(dpath)))
    return data_list

def cachestr_repr(val):
    """Representation of an object as a cache string."""
    try:
        memview = memoryview(val)
        return memview.tobytes()
    except Exception:
        try:
            return to_json(val)
        except Exception:
            if repr(val.__class__) == "<class 'ibeis.control.IBEISControl.IBEISController'>":
                return val.get_dbname()

