def avl_release_kids(node):
    """splits a node from its kids maintaining parent pointers"""
    left, right = (node.left, node.right)
    if left is not None:
        left.parent = None
    if right is not None:
        right.parent = None
    node.balance = 0
    node.left = None
    node.right = None
    return (node, left, right)

def avl_release_parent(node):
    """removes the parent of a child"""
    parent = node.parent
    if parent is not None:
        if parent.right is node:
            parent.right = None
        elif parent.left is node:
            parent.left = None
        else:
            raise AssertionError('impossible state')
        node.parent = None
        parent.balance = max(height(parent.right), height(parent.left)) + 1
    return (node, parent)

def avl_split_last(root):
    """Removes the maximum element from the tree

    Returns:
        tuple: new_root, last_node

    O(log(n)) = O(height(root))"""
    if root is None:
        raise IndexError('Empty tree has no maximum element')
    root, left, right = avl_release_kids(root)
    if right is None:
        new_root, last_node = (left, root)
    else:
        new_right, last_node = avl_split_last(right)
        new_root = avl_join(left, new_right, root)
    return (new_root, last_node)

def avl_split_first(root):
    """Removes the minimum element from the tree

    Returns:
        tuple: new_root, first_node

    O(log(n)) = O(height(root))"""
    if root is None:
        raise IndexError('Empty tree has no maximum element')
    root, left, right = avl_release_kids(root)
    if left is None:
        new_root, first_node = (right, root)
    else:
        new_left, first_node = avl_split_first(left)
        new_root = avl_join(new_left, right, root)
    return (new_root, first_node)

def unixjoin(*args):
    """Like os.path.join, but uses forward slashes on win32"""
    isabs_list = list(map(isabs, args))
    if any(isabs_list):
        poslist = [count for count, flag in enumerate(isabs_list) if flag]
        pos = poslist[-1]
        return '/'.join(args[pos:])
    else:
        return '/'.join(args)

def pick_target_decoy(tfeature, dfeature):
    """Feed it with a target and decoy score and the protein/gene/id names,
    and this will return target/decoy type, the winning ID and the score"""
    tscore, dscore = (get_score(tfeature), get_score(dfeature))
    if tscore == dscore:
        return False
    elif False in [tscore, dscore]:
        return [v for k, v in {tscore: tfeature, dscore: dfeature}.items() if k is not False][0]
    elif tscore > dscore:
        return tfeature
    elif tscore < dscore:
        return dfeature
    else:
        print('WARNING, target score {} and decoy score {} could not be compared'.format(tscore, dscore))
        return False

def create_merge_psm_map(peptides, ns):
    """Loops through peptides, stores sequences mapped to PSM ids."""
    psmmap = {}
    for peptide in peptides:
        seq = reader.get_peptide_seq(peptide, ns)
        psm_ids = reader.get_psm_ids_from_peptide(peptide, ns)
        for psm_id in psm_ids:
            try:
                psmmap[seq][psm_id.text] = 1
            except KeyError:
                psmmap[seq] = {psm_id.text: 2}
    for seq, psm_id_dict in psmmap.items():
        psmmap[seq] = [x for x in psm_id_dict]
    return psmmap

def protein_header_split_generator(elements, headers, ns):
    """Loop through proteins of each PSM/peptide. If a protein does not
    match any of headers, discard PSM/peptide immediately"""
    for el in elements:
        header_not_matching = False
        for protein in el.findall('{%s}protein_id' % ns['xmlns']):
            if not any((re.search(h, protein.text) for h in headers)):
                header_not_matching = True
                break
        if header_not_matching:
            formatting.clear_el(el)
        else:
            yield formatting.string_and_clear(el, ns)

