def get_caller_name(N=0, strict=True):
    """Standalone version of get_caller_name"""
    if isinstance(N, (list, tuple)):
        name_list = []
        for N_ in N:
            try:
                name_list.append(get_caller_name(N_))
            except AssertionError:
                name_list.append('X')
        return '[' + ']['.join(name_list) + ']'
    parent_frame = get_stack_frame(N=N + 2, strict=strict)
    caller_name = parent_frame.f_code.co_name
    if caller_name == '<module>':
        co_filename = parent_frame.f_code.co_filename
        caller_name = splitext(split(co_filename)[1])[0]
    if caller_name == '__init__':
        co_filename = parent_frame.f_code.co_filename
        caller_name = basename(dirname(co_filename)) + '.' + caller_name
    return caller_name

def generate_master_proteins(psms, protcol):
    """Fed with a psms generator, this returns the master proteins present
    in the PSM table. PSMs with multiple master proteins are excluded."""
    master_proteins = {}
    if not protcol:
        protcol = mzidtsvdata.HEADER_MASTER_PROT
    for psm in psms:
        protacc = psm[protcol]
        if ';' in protacc:
            continue
        master_proteins[protacc] = 1
    if 'NA' in master_proteins:
        master_proteins.pop('NA')
    if '' in master_proteins:
        master_proteins.pop('')
    for protacc in master_proteins:
        yield {prottabledata.HEADER_PROTEIN: protacc}

