    else:
        type_ = type(var)
    return type_

def get_homogenous_list_type(list_):
    """Returns the best matching python type even if it is an ndarray assumes all
    items in the list are of the same type. does not check this"""
    if HAVE_NUMPY and isinstance(list_, np.ndarray):
        item = list_
    elif isinstance(list_, list) and len(list_) > 0:
        item = list_[0]
    else:
        item = None
    if item is not None:
        if is_float(item):
            type_ = float
        elif is_int(item):
            type_ = int
        elif is_bool(item):
            type_ = bool
        elif is_str(item):
            type_ = str
        else:
            type_ = get_type(item)
    else:
        type_ = None
    return type_

def lists_eq(list1, list2):
    """recursive"""
    if len(list1) != len(list2):
        return False
    for count, (item1, item2) in enumerate(zip(list1, list2)):
        if isinstance(item1, np.ndarray) or isinstance(item2, np.ndarray):
            failed = not np.all(item1 == item2)
        else:
            failed = item1 != item2
        if failed:
            return False
    return True

