def sort_protein_group(pgroup, sortfunctions, sortfunc_index):
    """Recursive function that sorts protein group by a number of sorting
    functions."""
    pgroup_out = []
    subgroups = sortfunctions[sortfunc_index](pgroup)
    sortfunc_index += 1
    for subgroup in subgroups:
        if len(subgroup) > 1 and sortfunc_index < len(sortfunctions):
            pgroup_out.extend(sort_protein_group(subgroup, sortfunctions, sortfunc_index))
        else:
            pgroup_out.extend(subgroup)
    return pgroup_out

def sort_amounts(proteins, sort_index):
    """Generic function for sorting peptides and psms. Assumes a higher
    number is better for what is passed at sort_index position in protein."""
    amounts = {}
    for protein in proteins:
        amount_x_for_protein = protein[sort_index]
        try:
            amounts[amount_x_for_protein].append(protein)
        except KeyError:
            amounts[amount_x_for_protein] = [protein]
    return [v for k, v in sorted(amounts.items(), reverse=True)]

def lookup_statistic(score, stats):
    """Finds statistics that correspond to PSM/peptide/protein feature's
    score. Loops through list of qvality generated scores until it finds
    values closest to the feature's svm_score."""
    if score in stats:
        return (stats[score]['q'], stats[score]['PEP'], None)
    else:
        lower, warning = (None, None)
        for stat_score in sorted(stats.keys()):
            if score < stat_score:
                break
            lower = stat_score
        if score > stat_score:
            warning = 'WARNING! Values found with higher svm_score than in qvality recalculation!'
        if not lower:
            warning = 'WARNING! Values found with lower svm_score than in qvality recalculation were set to PEP=1, qval=1.'
            return ('1', '1', warning)
        qval = (float(stats[stat_score]['q']) + float(stats[lower]['q'])) / 2
        pep = (float(stats[stat_score]['PEP']) + float(stats[lower]['PEP'])) / 2
    return (str(qval), str(pep), warning)

