    match = re.match('.+twitter\\.com\\/(.+)\\/lists\\/(.+)', list_url)
    if not match:
        print('cannot parse list url %s' % list_url)
        return []
    screen_name, slug = match.groups()
    print('collecting list %s/%s' % (screen_name, slug))
    return twutil.collect.list_members(slug, screen_name)

def _clean_query_string(q):
    """Clean up a query string for searching.

    Removes unmatched parentheses and joining operators.

    Arguments:
        q (str): Query string to be cleaned

    Returns:
        str: The clean query string."""
    q = q.replace('()', '').strip()
    if q.endswith('('):
        q = q[:-1].strip()
    if q[-3:] == 'AND' or q[-3:] == 'NOT':
        q = q[:-3]
    elif q[-2:] == 'OR':
        q = q[:-2]
    while q.count('(') > q.count(')'):
        q += ')'
    while q.count(')') > q.count('('):
        q = '(' + q
    return q.strip()

