def srv_event(token, hits, url=RBA_URL):
    """Serve event to RainbowAlga"""
    if url is None:
        log.error('Please provide a valid RainbowAlga URL.')
        return
    ws_url = url + '/message'
    if isinstance(hits, pd.core.frame.DataFrame):
        pos = [tuple(x) for x in hits[['x', 'y', 'z']].values]
        time = list(hits['time'])
        tot = list(hits['tot'])
