def get_jpp_env(jpp_dir):
    """Return the environment dict of a loaded Jpp env.

    The returned env can be passed to `subprocess.Popen("J...", env=env)`
    to execute Jpp commands."""
    env = {v[0]: ''.join(v[1:]) for v in [l.split('=') for l in os.popen('source {0}/setenv.sh {0} && env'.format(jpp_dir)).read().split('\n') if '=' in l]}
    return env

def most_energetic(df):
    """Grab most energetic particle from mc_tracks dataframe."""
    idx = df.groupby(['event_id'])['energy'].transform(max) == df['energy']
    return df[idx].reindex()

def peak_memory_usage():
    """Return peak memory usage in MB"""
    if sys.platform.startswith('win'):
        p = psutil.Process()
        return p.memory_info().peak_wset / 1024 / 1024
    mem = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss
    factor_mb = 1 / 1024
    if sys.platform == 'darwin':
        factor_mb = 1 / (1024 * 1024)
    return mem * factor_mb

def load_from_args(args):
    """Return a Loci object giving the loci specified on the command line.

    If no loci-related arguments are specified, return None. This makes it
    possible to distinguish an empty set of loci, for example due to filters
    removing all loci, from the case where the user didn't specify any
    arguments."""
    if not args.locus:
        return None
    loci_iterator = (Locus.parse(locus) for locus in args.locus)
    return Loci(loci_iterator)

def import_submodules(context, root_module, path):
    """Import all submodules and register them in the ``context`` namespace.

    >>> import_submodules(locals(), __name__, __path__)"""
    for _, module_name, _ in pkgutil.walk_packages(path, root_module + '.'):
        module = __import__(module_name, globals(), locals(), ['__name__'])
        for k, v in vars(module).items():
            if not k.startswith('_'):
                context[k] = v
        context[module_name] = module

def get_plugins(directory):
    """returns the list of plugins from the specified directory
    :param directory: directory that contains the plugins. Files starting with _ will be ignored."""
    plugins = []
    files = glob.glob(directory + '/*.py')
    for p in files:
        p = p.replace(directory + '/', '').replace('.py', '')
        if not p.startswith('_'):
            plugins.append(p)
    return plugins

def command(func):
    '''A decorator to create a function with docopt arguments. It also generates a help function

    @command
    def do_myfunc(self, args):
        """ docopts text """
        pass

    will create

    def do_myfunc(self, args, arguments):
        """ docopts text """
        ...

    def help_myfunc(self, args, arguments):
        ... prints the docopt text ...

    :param func: the function for the decorator'''
    classname = inspect.getouterframes(inspect.currentframe())[1][3]
    name = func.__name__
    help_name = name.replace('do_', 'help_')
    doc = textwrap.dedent(func.__doc__)
    def new(instance, args):
        try:
            argv = shlex.split(args)
            arguments = docopt(doc, help=True, argv=argv)
            func(instance, args, arguments)
        except SystemExit:
            if args not in ('-h', '--help'):
                Console.error('Could not execute the command.')
            print(doc)
    new.__doc__ = doc
    return new

def create_file(filename):
    """Creates a new file if the file name does not exists
    :param filename: the name of the file"""
    expanded_filename = os.path.expanduser(os.path.expandvars(filename))
    if not os.path.exists(expanded_filename):
        open(expanded_filename, 'a').close()

def get_plugins_from_dir(dir_path, classbase):
    """dir_path/classbase/plugins"""
    if dir_path == 'sys':
        dir_path = os.path.abspath(os.path.join(os.path.dirname(__file__), 'plugins'))
        dir_plugins = get_plugins(dir_path)
        return {'dir': dir_path, 'plugins': dir_plugins, 'class': classbase}
    if dir_path == '.':
        dir_path = os.path.expanduser(os.path.expandvars(os.path.join(os.getcwd(), 'plugins')))
        dir_plugins = get_plugins(dir_path)
        return {'dir': dir_path, 'plugins': dir_plugins, 'class': classbase}
    else:
        dir_path = os.path.expanduser(os.path.expandvars(dir_path))
        prefix = '{0}/{1}'.format(dir_path, classbase)
        user_path = '{0}/plugins'.format(prefix)
        create_dir(user_path)
        create_file('{0}/__init__.py'.format(prefix))
        create_file('{0}/plugins/__init__.py'.format(prefix))
        sys.path.append(os.path.expanduser(dir_path))
        dir_plugins = get_plugins(user_path)
        return {'dir': dir_path, 'plugins': dir_plugins, 'class': classbase}

def new(url):
    """Creates a new Repo class instance at url.

    :param url: URL of new repo

    :return: new Repo class instance."""
    from grit import Repo
    return Repo.new(url=url, bare=True)

def _copy_context_into_mutable(context):
    """Copy a properly formatted context into a mutable data structure.
    """
    def make_mutable(val):
        if isinstance(val, Mapping):
            return dict(val)
        else:
            return val
    if not isinstance(context, (str, Mapping)):
        try:
            return [make_mutable(val) for val in context]
        except TypeError:
            pass
    return make_mutable(context)

def _make_context_immutable(context):
    """Best effort attempt at turning a properly formatted context
    (either a string, dict, or array of strings and dicts) into an
    immutable data structure.

    If we get an array, make it immutable by creating a tuple; if we get
    a dict, copy it into a MappingProxyType. Otherwise, return as-is."""
    def make_immutable(val):
        if isinstance(val, Mapping):
            return MappingProxyType(val)
        else:
            return val
    if not isinstance(context, (str, Mapping)):
        try:
            return tuple([make_immutable(val) for val in context])
        except TypeError:
            pass
    return make_immutable(context)

def get_flattened_bsp_keys_from_schema(schema):
    """Returns the flattened keys of BoundSpatialPoints in a schema

    :param schema: schema
    :return: list"""
    keys = []
    for key in schema.declared_fields.keys():
        field = schema.declared_fields[key]
        if isinstance(field, mm.fields.Nested) and isinstance(field.schema, BoundSpatialPoint):
            keys.append('{}.{}'.format(key, 'position'))
    return keys

def is_callable(instance, attribute, value):
    """Raises a :exc:`TypeError` if the value is not a callable."""
    if not callable(value):
        raise TypeError("'{}' must be callable".format(attribute.name))

def use_model_attr(attr):
    """Use the validator set on a separate attribute on the class."""
    def use_model_validator(instance, attribute, value):
        getattr(instance, attr)(instance, attribute, value)
    return use_model_validator

def does_not_contain(*avoid_keys, error_cls=ValueError):
    """Decorator: value must not contain any of the :attr:`avoid_keys`.
    """
    def decorator(func):
        def not_contains(instance, attribute, value):
            instance_name = instance.__class__.__name__
            num_matched_keys = len(set(avoid_keys) & value.keys())
            if num_matched_keys > 0:
                avoid_keys_str = ', '.join(avoid_keys)
                err_str = "Given keys ({num_matched} of {{avoid_keys}} that must not be given in the '{attr}' of a '{cls}'".format(num_matched=num_matched_keys, avoid_keys=avoid_keys_str, attr=attribute.name, cls=instance_name)
                raise error_cls(err_str)
            return func(instance, attribute, value)
        return not_contains
    return decorator

def is_right_model(instance, attribute, value):
    """Must include at least the ``source`` and ``license`` keys, but
    not a ``rightsOf`` key (``source`` indicates that the Right is
    derived from and allowed by a source Right; it cannot contain the
    full rights to a Creation)."""
    for key in ['source', 'license']:
        key_value = value.get(key)
        if not isinstance(key_value, str):
            instance_name = instance.__class__.__name__
            raise ModelDataError("'{key}' must be given as a string in the '{attr}' parameter of a '{cls}'. Given '{value}'".format(key=key, attr=attribute.name, cls=instance_name, value=key_value))

def add_argument(*args, **kwargs):
    """Define an argument for the function when running in console script
    mode.  The positional and keyword arguments are the same as for
    ArgumentParser.add_argument()."""
    def decorator(func):
        func = ScriptAdaptor._wrap(func)
        func._add_argument(args, kwargs)
        return func
    return decorator

def add_preprocessor(preproc):
    """Define a preprocessor to run after the arguments are parsed and
    before the function is executed, when running in console script
    mode.

    :param preproc: The callable, which will be passed the Namespace
                    object generated by argparse."""
    def decorator(func):
        func = ScriptAdaptor._wrap(func)
        func._add_preprocessor(preproc)
        return func
    return decorator

def make_limit_node(root, limit):
    """Given a Limit object, generate an XML node.

    :param root: The root node of the XML tree being built.
    :param limit: The Limit object to serialize to XML."""
    limit_node = etree.SubElement(root, 'limit', {'class': limit._limit_full_name})
    for attr in sorted(limit.attrs):
        desc = limit.attrs[attr]
        attr_type = desc.get('type', str)
        value = getattr(limit, attr)
        if 'default' in desc:
            default = desc['default']() if callable(desc['default']) else desc['default']
            if value == default:
                continue
        attr_node = etree.SubElement(limit_node, 'attr', name=attr)
        if attr_type == list:
            for val in value:
                val_node = etree.SubElement(attr_node, 'value')
                val_node.text = str(val)
        elif attr_type == dict:
            for key, val in sorted(value.items(), key=lambda x: x[0]):
                val_node = etree.SubElement(attr_node, 'value', key=key)
                val_node.text = str(val)
        else:
            attr_node.text = str(value)

def humanize_timesince(start_time):
    """Creates a string representation of time since the given `start_time`."""
    if not start_time:
        return start_time
    delta = local_now() - start_time
    if delta.total_seconds() < 0:
        return 'a few seconds ago'
    num_years = delta.days // 365
    if num_years > 0:
        return '{} year{} ago'.format(*((num_years, 's') if num_years > 1 else (num_years, '')))
    num_weeks = delta.days // 7
    if num_weeks > 0:
        return '{} week{} ago'.format(*((num_weeks, 's') if num_weeks > 1 else (num_weeks, '')))
    num_days = delta.days
    if num_days > 0:
        return '{} day{} ago'.format(*((num_days, 's') if num_days > 1 else (num_days, '')))
    num_hours = delta.seconds // 3600
    if num_hours > 0:
        return '{} hour{} ago'.format(*((num_hours, 's') if num_hours > 1 else (num_hours, '')))
    num_minutes = delta.seconds // 60
    if num_minutes > 0:
        return '{} minute{} ago'.format(*((num_minutes, 's') if num_minutes > 1 else (num_minutes, '')))
    return 'a few seconds ago'

def humanize_timedelta(seconds):
    """Creates a string representation of timedelta."""
    hours, remainder = divmod(seconds, 3600)
    days, hours = divmod(hours, 24)
    minutes, seconds = divmod(remainder, 60)
    if days:
        result = '{}d'.format(days)
        if hours:
            result += ' {}h'.format(hours)
        if minutes:
            result += ' {}m'.format(minutes)
        return result
    if hours:
        result = '{}h'.format(hours)
        if minutes:
            result += ' {}m'.format(minutes)
        return result
    if minutes:
        result = '{}m'.format(minutes)
        if seconds:
            result += ' {}s'.format(seconds)
        return result
    return '{}s'.format(seconds)

def get_next_token(string):
    """"eats" up the string until it hits an ending character to get valid leaf expressions.
    For example, given \\Phi_{z}(L) = \\sum_{i=1}^{N} \\frac{1}{C_{i} \\times V_{\\rm max, i}},
    this function would pull out \\Phi, stopping at _
    @ string: str
    returns a tuple of (expression [ex: \\Phi], remaining_chars [ex: _{z}(L) = \\sum_{i=1}^{N}...])"""
    STOP_CHARS = '_ {}^ \n ,()='
    UNARY_CHARS = '^_'
    if string[0] in STOP_CHARS:
        return (string[0], string[1:])
    expression = []
    for i, c in enumerate(string):
        if c in STOP_CHARS:
            break
        else:
            expression.append(c)
    return (''.join(expression), string[i:])

def _permutation_correctness(pathway_feature_tuples, original):
    """Determine whether the generated permutation is a valid permutation.
    Used in `permute_pathways_across_features`.
    (Cannot be identical to the original significant pathways list,
    and a feature should map to a distinct set of pathways.)"""
    if pathway_feature_tuples:
        if set(pathway_feature_tuples) == set(original):
            return False
        pathways_in_feature = {}
        for pathway, feature in pathway_feature_tuples:
            if feature not in pathways_in_feature:
                pathways_in_feature[feature] = set()
            if pathway in pathways_in_feature[feature]:
                return False
            else:
                pathways_in_feature[feature].add(pathway)
    return True

def _advanced_acronym_detection(s, i, words, acronyms):
    """Detect acronyms by checking against a list of acronyms.

    Check a run of words represented by the range [s, i].
    Return last index of new word groups."""
    acstr = ''.join(words[s:i])
    range_list = []
    not_range = set(range(len(acstr)))
    for acronym in acronyms:
        rac = regex.compile(unicode(acronym))
        n = 0
        while True:
            m = rac.search(acstr, n)
            if not m:
                break
            a, b = (m.start(), m.end())
            n = b
            ok = True
            for r in range_list:
                if a < r[1] and b > r[0]:
                    ok = False
                    break
            if ok:
                range_list.append((a, b))
                for j in xrange(a, b):
                    not_range.remove(j)
    for nr in not_range:
        range_list.append((nr, nr + 1))
    range_list.sort()
    for _ in xrange(s, i):
        del words[s]
    for j in xrange(len(range_list)):
        r = range_list[j]
        words.insert(s + j, acstr[r[0]:r[1]])
    return s + len(range_list) - 1

def _sanitize_acronyms(unsafe_acronyms):
    """Check acronyms against regex.

    Normalize valid acronyms to upper-case.
    If an invalid acronym is encountered raise InvalidAcronymError."""
    valid_acronym = regex.compile(u'^[\\p{Ll}\\p{Lu}\\p{Nd}]+$')
    acronyms = []
    for a in unsafe_acronyms:
        if valid_acronym.match(a):
            acronyms.append(a.upper())
        else:
            raise InvalidAcronymError(a)
    return acronyms

def _normalize_words(words, acronyms):
    """Normalize case of each word to PascalCase."""
    for i, _ in enumerate(words):
        if words[i].upper() in acronyms:
            words[i] = words[i].upper()
        elif not words[i].isupper():
            words[i] = words[i].capitalize()
    return words

def is_geophysical(ds, variable):
    """Returns true if the dataset's variable is likely a geophysical variable"""
    ncvar = ds.variables[variable]
    standard_name = getattr(ncvar, 'standard_name', '')
    if not standard_name:
        return False
    if standard_name and standard_name not in get_unitless_standard_names():
        units = getattr(ncvar, 'units', '')
        if units == '':
            return False
    if not hasattr(ncvar, 'standard_name') or not hasattr(ncvar, 'units'):
        return False
    if getattr(ncvar, 'standard_name') in ('time', 'latitude', 'longitude', 'height', 'depth', 'altitude'):
        return False
    if len(ncvar.shape) == 0:
        return False
    if 'status_flag' in ncvar.standard_name:
        return False
    if getattr(ncvar, 'cf_role', None):
        return False
    if getattr(ncvar, 'axis', None):
        return False
    return True

def get_lat_variable(nc):
    """Returns the variable for latitude

    :param netcdf4.dataset nc: an open netcdf dataset object"""
    if 'latitude' in nc.variables:
        return 'latitude'
    latitudes = nc.get_variables_by_attributes(standard_name='latitude')
    if latitudes:
        return latitudes[0].name
    return None

def get_lon_variable(nc):
    """Returns the variable for longitude

    :param netCDF4.Dataset nc: netCDF dataset"""
    if 'longitude' in nc.variables:
        return 'longitude'
    longitudes = nc.get_variables_by_attributes(standard_name='longitude')
    if longitudes:
        return longitudes[0].name
    return None

def get_time_variable(ds):
    """Returns the likeliest variable to be the time coordiante variable

    :param netCDF4.Dataset ds: An open netCDF4 Dataset"""
    for var in ds.variables:
        if getattr(ds.variables[var], 'axis', '') == 'T':
            return var
    else:
        candidates = ds.get_variables_by_attributes(standard_name='time')
        if len(candidates) == 1:
            return candidates[0].name
        else:
            for candidate in candidates:
                if candidate.dimensions == (candidate.name,):
                    return candidate.name
    return None

def get_crs_variable(ds):
    """Returns the name of the variable identified by a grid_mapping attribute

    :param netCDF4.Dataset ds: An open netCDF4 Dataset"""
    for var in ds.variables:
        grid_mapping = getattr(ds.variables[var], 'grid_mapping', '')
        if grid_mapping and grid_mapping in ds.variables:
            return grid_mapping
    return None

def is_timeseries(nc, variable):
    """Returns true if the variable is a time series feature type.

    :param netCDF4.Dataset nc: An open netCDF dataset
    :param str variable: name of the variable to check"""
    dims = nc.variables[variable].dimensions
    cmatrix = coordinate_dimension_matrix(nc)
    for req in ('x', 'y', 't'):
        if req not in cmatrix:
            return False
    if len(cmatrix['x']) != 0:
        return False
    if len(cmatrix['y']) != 0:
        return False
    if 'z' in cmatrix and len(cmatrix['z']) != 0:
        return False
    timevar = get_time_variable(nc)
    if cmatrix['t'] != (timevar,):
        return False
    if dims == cmatrix['t']:
        return True
    return False

def is_single_trajectory(nc, variable):
    """Returns true if the variable is a single trajectory feature

    :param netCDF4.Dataset nc: An open netCDF dataset
    :param str variable: name of the variable to check"""
    dims = nc.variables[variable].dimensions
    cmatrix = coordinate_dimension_matrix(nc)
    for req in ('x', 'y', 't'):
        if req not in cmatrix:
            return False
    t = get_time_variable(nc)
    if cmatrix['x'] != (t,):
        return False
    if cmatrix['x'] != cmatrix['y']:
        return False
    if cmatrix['x'] != cmatrix['t']:
        return False
    if 'z' in cmatrix and cmatrix['x'] != cmatrix['z']:
        return False
    if dims == cmatrix['x']:
        return True
    return False

def is_2d_regular_grid(nc, variable):
    """Returns True if the variable is a 2D Regular grid.

    :param netCDF4.Dataset nc: An open netCDF dataset
    :param str variable: name of the variable to check"""
    dims = nc.variables[variable].dimensions
    cmatrix = coordinate_dimension_matrix(nc)
    for req in ('x', 'y', 't'):
        if req not in cmatrix:
            return False
    x = get_lon_variable(nc)
    y = get_lat_variable(nc)
    t = get_time_variable(nc)
    if cmatrix['x'] != (x,):
        return False
    if cmatrix['y'] != (y,):
        return False
    if cmatrix['t'] != (t,):
        return False
    if len(dims) == 3 and x in dims and (y in dims) and (t in dims):
        return True
    return False

def handle_read(repo, **kwargs):
    """handles reading repo information"""
    log.info('read: %s %s' % (repo, kwargs))
    if type(repo) in [unicode, str]:
        return {'name': 'Repo', 'desc': 'Welcome to Grit', 'comment': ''}
    else:
        return repo.serialize()

def handle_branch(repo, **kwargs):
    """:return: Local.create()"""
    log.info('branch: %s %s' % (repo, kwargs))
    if type(repo) in [unicode, str]:
        path = os.path.join(repo, kwargs.get('name', 'Unnamed'))
        desc = kwargs.get('desc')
        branch = Repo.new(path=path, desc=desc, bare=True)
    else:
        name = kwargs.get('name')
        path = kwargs.get('path')
        if path and (not name):
            name = os.path.basename(path)
        desc = kwargs.get('desc')
        branch = repo.branch(name=name, desc=desc)
    return branch.serialize()

def handle_items(repo, **kwargs):
    """:return: repo.files()"""
    log.info('items: %s %s' % (repo, kwargs))
    if not hasattr(repo, 'items'):
        return []
    return [i.serialize() for i in repo.items(**kwargs)]

def handle_versions(repo, **kwargs):
    """:return: repo.versions()"""
    log.info('versions: %s %s' % (repo, kwargs))
    if not hasattr(repo, 'versions'):
        return []
    return [v.serialize() for v in repo.versions(**kwargs)]

def handle_parent(repo, **kwargs):
    """:return: repo.parent()"""
    log.info('parent: %s %s' % (repo, kwargs))
    _parent = repo.parent()
    if _parent:
        return [_parent.serialize()]

def dict_from_object(obj: object):
    """Convert a object into dictionary with all of its readable attributes."""
    return obj if isinstance(obj, dict) else {attr: getattr(obj, attr) for attr in dir(obj) if not attr.startswith('_')}

def xgetattr(obj: object, name: str, default=_sentinel, getitem=False):
    """Get attribute value from object.

    :param obj: object
    :param name: attribute or key name
    :param default: when attribute or key missing, return default; if obj is a
        dict and use getitem, default will not be used.
    :param getitem: when object is a dict, use getitem or get
    :return: attribute or key value, or raise KeyError/AttributeError"""
    if isinstance(obj, dict):
        if getitem:
            return obj[name]
        else:
            val = obj.get(name, default)
            return None if val is _sentinel else val
    else:
        val = getattr(obj, name, default)
        if val is _sentinel:
            msg = '%r object has no attribute %r' % (obj.__class__, name)
            raise AttributeError(msg)
        else:
            return val

def camel_to_snake_case(name):
    """Takes a camelCased string and converts to snake_case."""
    pattern = '[A-Z][a-z]+|[A-Z]+(?![a-z])'
    return '_'.join(map(str.lower, re.findall(pattern, name)))

def is_paired(text, open='(', close=')'):
    """Check if the text only contains:
    1. blackslash escaped parentheses, or
    2. parentheses paired."""
    count = 0
    escape = False
    for c in text:
        if escape:
            escape = False
        elif c == '\\':
            escape = True
        elif c == open:
            count += 1
        elif c == close:
            if count == 0:
                return False
            count -= 1
    return count == 0

def register(name, _callable=None):
    """A decorator used for register custom check.

    :param name: name of check
    :type: str
    :param _callable: check class or a function which return check instance
    :return: _callable or a decorator"""
    def wrapper(_callable):
        registered_checks[name] = _callable
        return _callable
    if _callable:
        return wrapper(_callable)
    return wrapper

def register(name, func=None):
    """Function or decorator which registers a given function as a
    recognized control command."""
    def decorator(func):
        ControlDaemon._register(name, func)
        return func
    if func:
        return decorator(func)
    else:
        return decorator

def enforce_policy(rule):
    """Enforce a policy to a API."""
    def wrapper(func):
        """Decorator used for wrap API."""
        @functools.wraps(func)
        def wrapped(*args, **kwargs):
            if enforcer.enforce(rule, {}, g.cred):
                return func(*args, **kwargs)
        return wrapped
    return wrapper

def _applyMultichan(samples, func):
    """Apply func to each channel of audio data in samples"""
    if len(samples.shape) == 1 or samples.shape[1] == 1:
        newsamples = func(samples)
    else:
        y = np.array([])
        for i in range(samples.shape[1]):
            y = np.concatenate((y, func(samples[:, i])))
        newsamples = y.reshape(samples.shape[1], -1).T
    return newsamples

def get_package_version():
    """return package version without importing it"""
    base = os.path.abspath(os.path.dirname(__file__))
    with open(os.path.join(base, 'policy', '__init__.py'), mode='rt', encoding='utf-8') as initf:
        for line in initf:
            m = version.match(line.strip())
            if not m:
                continue
            return m.groups()[0]

