def to_unit_memory(number):
    """Creates a string representation of memory size given `number`."""
    kb = 1024
    number /= kb
    if number < 100:
        return '{} Kb'.format(round(number, 2))
    number /= kb
    if number < 300:
        return '{} Mb'.format(round(number, 2))
    number /= kb
    return '{} Gb'.format(round(number, 2))

def _unpack_token_compact(token):
    """Unpack a compact-form serialized JWT.
    Returns (header, payload, signature, signing_input) on success
    Raises DecodeError on bad input"""
    if isinstance(token, (str, unicode)):
        token = token.encode('utf-8')
    try:
        signing_input, crypto_segment = token.rsplit(b'.', 1)
        header_segment, payload_segment = signing_input.split(b'.', 1)
    except ValueError:
        raise DecodeError('Not enough segments')
    try:
        header_data = base64url_decode(header_segment)
    except (TypeError, binascii.Error):
        raise DecodeError('Invalid header padding')
    try:
        header = json.loads(header_data.decode('utf-8'))
    except ValueError as e:
        raise DecodeError('Invalid header string: %s' % e)
    if not isinstance(header, Mapping):
        raise DecodeError('Invalid header string: must be a json object')
    try:
        payload_data = base64url_decode(payload_segment)
    except (TypeError, binascii.Error):
        raise DecodeError('Invalid payload padding')
    try:
        payload = json.loads(payload_data.decode('utf-8'))
    except ValueError as e:
        raise DecodeError('Invalid payload string: %s' % e)
    try:
        signature = base64url_decode(crypto_segment)
    except (TypeError, binascii.Error):
        raise DecodeError('Invalid crypto padding')
    return (header, payload, signature, signing_input)

def _unpack_token_json(token):
    """Unpack a JSON-serialized JWT
    Returns (headers, payload, signatures) on success
    Raises DecodeError on bad input"""
    if not isinstance(token, dict):
        raise DecodeError('Not a dict')
    if not token.has_key('payload'):
        raise DecodeError("Missing 'payload' field")
    for k in ['header', 'signature']:
        if not token.has_key(k):
            raise DecodeError("Missing '{}' field".format(k))
        if not isinstance(token[k], list):
            raise DecodeError("Field '{}' is not a string".format(k))
    headers = []
    signatures = []
    signing_inputs = []
    payload = None
    try:
        headers = [base64url_decode(str(h)) for h in token['header']]
    except (TypeError, binascii.Error):
        raise DecodeError('Invalid header padding')
    try:
        payload_data = base64url_decode(str(token['payload']))
    except (TypeError, binascii.Error):
        raise DecodeError('Invalid payload padding')
    try:
        payload = json.loads(payload_data.decode('utf-8'))
    except ValueError as e:
        raise DecodeError('Invalid payload string: {}'.format(e))
    try:
        signatures = [base64url_decode(str(s)) for s in token['signature']]
    except (TypeError, binascii.Error):
        raise DecodeError('Invalid crypto padding')
    for header_b64 in token['header']:
        signing_inputs.append(b'{}.{}'.format(header_b64, token['payload']))
    return (headers, payload, signatures, signing_inputs)

def unpack_token(token):
    """Unpack a JSON-serialized JWT or a compact-serialized JWT
    Returns (header, payload, signature, signing_input) on success
    Raises DecodeError on bad input"""
    if isinstance(token, (unicode, str)):
        return _decode_token_compact(token)
    else:
        return _decode_token_json(token)

def _decode_token_compact(token):
    """Decode a compact-serialized JWT
    Returns {'header': ..., 'payload': ..., 'signature': ...}"""
    header, payload, raw_signature, signing_input = _unpack_token_compact(token)
    token = {'header': header, 'payload': payload, 'signature': base64url_encode(raw_signature)}
    return token

def _decode_token_json(token):
    """Decode a JSON-serialized JWT
    Returns {'header': ..., 'payload': ..., 'signature': ...}"""
    header, payload, raw_signatures, signing_inputs = _unpack_token_json(token)
    token = {'header': header, 'payload': payload, 'signature': [base64url_encode(rs) for rs in raw_signatures]}
    return token

def memoize(func):
    """Provides memoization for methods on a specific instance.
    Results are cached for given parameter list.

    See also: http://en.wikipedia.org/wiki/Memoization

    N.B. The cache object gets added to the instance instead of the global scope.
    Therefore cached results are restricted to that instance.
    The cache dictionary gets a name containing the name of the decorated function to
    avoid clashes.

    Example:

        class MyClass(object):
            @memoize
            def foo(self, a, b):
                return self._do_calculation(a, b)

    HINT: - The decorator does not work with keyword arguments."""
    cache_name = '__CACHED_{}'.format(func.__name__)
    def wrapper(self, *args):
        cache = getattr(self, cache_name, None)
        if cache is None:
            cache = {}
            setattr(self, cache_name, cache)
        if args not in cache:
            cache[args] = func(self, *args)
        return cache[args]
    return wrapper

def _parse_http_header(h):
    """Parses a typical multi-valued and parametrised HTTP header (e.g. Accept headers) and returns a list of values
        and parameters. For non-standard or broken input, this implementation may return partial results.
    :param h: A header string (e.g. ``text/html,text/plain;q=0.9,*/*;q=0.8``)
    :return: List of (value, params) tuples. The second element is a (possibly empty) dict."""
    values = []
    if '"' not in h:
        for value in h.split(','):
            parts = value.split(';')
            values.append((parts[0].strip(), {}))
            for attr in parts[1:]:
                name, value = attr.split('=', 1)
                values[-1][1][name.strip()] = value.strip()
    else:
        lop, key, attrs = (',', None, {})
        for quoted, plain, tok in _hsplit(h):
            value = plain.strip() if plain else quoted.replace('\\"', '"')
            if lop == ',':
                attrs = {}
                values.append((value, attrs))
            elif lop == ';':
                if tok == '=':
                    key = value
                else:
                    attrs[value] = ''
            elif lop == '=' and key:
                attrs[key] = value
                key = None
            lop = tok
    return values

def cookie_decode(data, key, digestmod=None):
    """Verify and decode an encoded string. Return an object or None."""
    depr(0, 13, 'cookie_decode() will be removed soon.', 'Do not use this API directly.')
    data = tob(data)
    if cookie_is_encoded(data):
        sig, msg = data.split(tob('?'), 1)
        digestmod = digestmod or hashlib.sha256
        hashed = hmac.new(tob(key), msg, digestmod=digestmod).digest()
        if _lscmp(sig[1:], base64.b64encode(hashed)):
            return pickle.loads(base64.b64decode(msg))
    return None

def read_key(pysam_alignment_record):
    """Given a `pysam.AlignedSegment` instance, return the attributes identifying
    the *read* it comes from (not the alignment). There may be more than one
    alignment for a read, e.g. chimeric and secondary alignments."""
    return (pysam_alignment_record.query_name, pysam_alignment_record.is_duplicate, pysam_alignment_record.is_read1, pysam_alignment_record.is_read2)

def _make_units(*units):
    """Units map helper.  Each argument is treated as a unit
    descriptor--a tuple where the first element specifies a numerical
    value, and the second element consists of a sequence of names for
    that value.  Returns a dictionary where each name is mapped to the
    numerical value, and the numerical value is mapped to the first
    name."""
    units_map = {}
    for value, names in units:
        units_map[value] = names[0]
        for name in names:
            units_map[name] = value
    return units_map

def drop_prefix(strings):
    """Removes common prefix from a collection of strings"""
    strings_without_extensions = [s.split('.', 2)[0] for s in strings]
    if len(strings_without_extensions) == 1:
        return [os.path.basename(strings_without_extensions[0])]
    prefix_len = len(os.path.commonprefix(strings_without_extensions))
    result = [string[prefix_len:] for string in strings_without_extensions]
    if len(set(result)) != len(strings):
        return strings
    return result

def load_dotenv(dotenv_path, verbose=False):
    """Read a .env file and load into os.environ.

    :param dotenv_path:
    :type dotenv_path: str
    :param verbose: verbosity flag, raise warning if path does not exist
    :return: success flag"""
    if not os.path.exists(dotenv_path):
        if verbose:
            warnings.warn(f"Not loading {dotenv_path}, it doesn't exist.")
        return None
    for k, v in dotenv_values(dotenv_path).items():
        os.environ.setdefault(k, v)
    return True

def unset_key(dotenv_path, key_to_unset, quote_mode='always', verbose=False):
    """Removes a given key from the given .env

    If the .env path given doesn't exist, fails
    If the given key doesn't exist in the .env, fails

    :param dotenv_path: env path
    :param key_to_unset: value
    :param quote_mode: quote value in .env file
    :param verbose: verbosity flag, raise warning if path does not exist
    :return: tuple (fail/win, key)"""
    key_to_unset = str(key_to_unset)
    if not os.path.exists(dotenv_path):
        if verbose:
            warnings.warn(f"Can't delete from {dotenv_path}, it doesn't exist.")
        return (None, key_to_unset)
    dotenv_as_dict = dotenv_values(dotenv_path)
    if key_to_unset in dotenv_as_dict:
        dotenv_as_dict.pop(key_to_unset, None)
    else:
        if verbose:
            warnings.warn(f"Key {key_to_unset} not removed from {dotenv_path}, key doesn't exist.")
        return (None, key_to_unset)
    success = flatten_and_write(dotenv_path, dotenv_as_dict, quote_mode)
    return (success, key_to_unset)

def _get_format(value, quote_mode='always'):
    """Returns the quote format depending on the quote_mode.
    This determines if the key value will be quoted when written to
    the env file.

    :param value:
    :param quote_mode:
    :return: str
    :raises: KeyError if the quote_mode is unknown"""
    formats = {'always': '{key}="{value}"\n', 'auto': '{key}={value}\n'}
    if quote_mode not in formats.keys():
        return KeyError(f'quote_mode {quote_mode} is invalid')
    _mode = quote_mode
    if quote_mode == 'auto' and ' ' in value:
        _mode = 'always'
    return formats.get(_mode)

def find_dotenv(filename='.env', raise_error_if_not_found=False, usecwd=False):
    """Search in increasingly higher folders for the given file

    Returns path to the file if found, or an empty string otherwise"""
    if usecwd or '__file__' not in globals():
        path = os.getcwd()
    else:
        frame_filename = sys._getframe().f_back.f_code.co_filename
        path = os.path.dirname(os.path.abspath(frame_filename))
    for dirname in _walk_to_root(path):
        check_path = os.path.join(dirname, filename)
        if os.path.exists(check_path):
            return check_path
    if raise_error_if_not_found:
        raise IOError('File not found')
    return ''

def reducer(*tokens):
