def load_signing_key(signing_key, crypto_backend=default_backend()):
    """Optional: crypto backend object from the "cryptography" python library
    """
    if isinstance(signing_key, EllipticCurvePrivateKey):
        return signing_key
    elif isinstance(signing_key, (str, unicode)):
        invalid_strings = [b'-----BEGIN PUBLIC KEY-----']
        invalid_string_matches = [string_value in signing_key for string_value in invalid_strings]
        if any(invalid_string_matches):
            raise ValueError('Signing key must be a private key, not a public key.')
        if is_hex(signing_key):
            try:
                private_key_pem = ECPrivateKey(signing_key).to_pem()
            except:
                pass
            else:
                try:
                    return load_pem_private_key(private_key_pem, password=None, backend=crypto_backend)
                except:
                    raise InvalidPrivateKeyError()
            try:
                return load_der_private_key(signing_key, password=None, backend=crypto_backend)
            except Exception as e:
                traceback.print_exc()
                raise InvalidPrivateKeyError()
        else:
            try:
                return load_pem_private_key(signing_key, password=None, backend=crypto_backend)
            except:
                raise InvalidPrivateKeyError()
    else:
        raise ValueError('Signing key must be in string or unicode format.')

def load_verifying_key(verifying_key, crypto_backend=default_backend()):
    """Optional: crypto backend object from the "cryptography" python library
    """
    if isinstance(verifying_key, EllipticCurvePublicKey):
        return verifying_key
    elif isinstance(verifying_key, (str, unicode)):
        if is_hex(verifying_key):
            try:
                public_key_pem = ECPublicKey(verifying_key).to_pem()
            except:
                pass
            else:
                try:
                    return load_pem_public_key(public_key_pem, backend=crypto_backend)
                except Exception as e:
                    traceback.print_exc()
                    raise InvalidPublicKeyError()
            try:
                return load_der_public_key(verifying_key, backend=crypto_backend)
            except:
                raise InvalidPublicKeyError()
        else:
            try:
                return load_pem_public_key(verifying_key, backend=crypto_backend)
            except Exception as e:
                raise InvalidPublicKeyError()
    else:
        raise ValueError('Verifying key must be in string or unicode format.')

def read_headers(rfile, hdict=None):
    """Read headers from the given stream into the given header dict.

    If hdict is None, a new header dict is created. Returns the populated
    header dict.

    Headers which are repeated are folded together using a comma if their
    specification so dictates.

    This function raises ValueError when the read bytes violate the HTTP spec.
    You should probably return "400 Bad Request" if this happens."""
    if hdict is None:
        hdict = {}
    while True:
        line = rfile.readline()
        if not line:
            raise ValueError('Illegal end of headers.')
        if line == CRLF:
            break
        if not line.endswith(CRLF):
            raise ValueError('HTTP requires CRLF terminators')
        if line[0] in ' \t':
            v = line.strip()
        else:
            try:
                k, v = line.split(':', 1)
            except ValueError:
                raise ValueError('Illegal header line.')
            k = k.strip().title()
            v = v.strip()
            hname = k
        if k in comma_separated_headers:
            existing = hdict.get(hname)
            if existing:
                v = ', '.join((existing, v))
        hdict[hname] = v
    return hdict

def format_exc(limit=None):
    """Like print_exc() but return a string. Backport for Python 2.3."""
    try:
        etype, value, tb = sys.exc_info()
        return ''.join(traceback.format_exception(etype, value, tb, limit))
    finally:
        etype = value = tb = None

def safe_request(url, method=None, params=None, data=None, json=None, headers=None, allow_redirects=False, timeout=30, verify_ssl=True):
    """A slightly safer version of `request`."""
    session = requests.Session()
    kwargs = {}
    if json:
        kwargs['json'] = json
        if not headers:
            headers = {}
        headers.setdefault('Content-Type', 'application/json')
    if data:
        kwargs['data'] = data
    if params:
        kwargs['params'] = params
    if headers:
        kwargs['headers'] = headers
    if method is None:
        method = 'POST' if data or json else 'GET'
    response = session.request(method=method, url=url, allow_redirects=allow_redirects, timeout=timeout, verify=verify_ssl, **kwargs)
    return response

def remote(func):
    """Decorator to mark a function as invoking a remote procedure call.
    When invoked in server mode, the function will be called; when
    invoked in client mode, an RPC will be initiated."""
    @functools.wraps(func)
    def wrapper(self, *args, **kwargs):
        if self.mode == 'server':
            return func(self, *args, **kwargs)
        if not self.conn:
            self.connect()
        self.conn.send('CALL', func.__name__, args, kwargs)
        cmd, payload = self.conn.recv()
        if cmd == 'ERR':
            self.close()
            raise Exception('Catastrophic error from server: %s' % payload[0])
        elif cmd == 'EXC':
            exc_type = utils.find_entrypoint(None, payload[0])
            raise exc_type(payload[1])
        elif cmd != 'RES':
            self.close()
            raise Exception('Invalid command response from server: %s' % cmd)
        return payload[0]
    wrapper._remote = True
    return wrapper

def get_repos(path):
    """Returns list of found branches.

    :return: List of grit.Local objects"""
    p = str(path)
    ret = []
    if not os.path.exists(p):
        return ret
    for d in os.listdir(p):
        pd = os.path.join(p, d)
        if os.path.exists(pd) and is_repo(pd):
            ret.append(Local(pd))
    return ret

def get_repo_parent(path):
    """Returns parent repo or input path if none found.

    :return: grit.Local or path"""
    if is_repo(path):
        return Local(path)
    elif not os.path.isdir(path):
        _rel = ''
        while path and path != '/':
            if is_repo(path):
                return Local(path)
            else:
                _rel = os.path.join(os.path.basename(path), _rel)
                path = os.path.dirname(path)
        return path

def _get_sockets(bots):
    """Connects and gathers sockets for all chatrooms"""
    sockets = {}
    for bot in bots:
        bot.connect()
        sockets[bot.client.Connection._sock] = bot
    return sockets

def _listen(sockets):
    """Main server loop. Listens for incoming events and dispatches them to appropriate chatroom"""
    while True:
        i, o, e = select.select(sockets.keys(), [], [], 1)
        for socket in i:
            if isinstance(sockets[socket], Chatroom):
                data_len = sockets[socket].client.Process(1)
                if data_len is None or data_len == 0:
                    raise Exception('Disconnected from server')
            else:
                raise Exception('Unknown socket type: %s' % repr(sockets[socket]))

def add_args(parser, positional=False):
    """Extends a commandline argument parser with arguments for specifying
    read sources."""
    group = parser.add_argument_group('read loading')
    group.add_argument('reads' if positional else '--reads', nargs='+', default=[], help='Paths to bam files. Any number of paths may be specified.')
    group.add_argument('--read-source-name', nargs='+', help='Names for each read source. The number of names specified must match the number of bam files. If not specified, filenames are used for names.')
    group = parser.add_argument_group('read filtering', 'A number of read filters are available. See the pysam documentation (http://pysam.readthedocs.org/en/latest/api.html) for details on what these fields mean. When multiple filter options are specified, reads must match *all* filters.')
    for name, (kind, message, function) in READ_FILTERS.items():
        extra = {}
        if kind is bool:
            extra['action'] = 'store_true'
            extra['default'] = None
        elif kind is int:
            extra['type'] = int
            extra['metavar'] = 'N'
        elif kind is str:
            extra['metavar'] = 'STRING'
        group.add_argument('--' + name.replace('_', '-'), help=message, **extra)

def load_from_args(args):
    """Given parsed commandline arguments, returns a list of ReadSource objects"""
    if not args.reads:
        return None
    if args.read_source_name:
        read_source_names = util.expand(args.read_source_name, 'read_source_name', 'read source', len(args.reads))
    else:
        read_source_names = util.drop_prefix(args.reads)
    filters = []
    for name, info in READ_FILTERS.items():
        value = getattr(args, name)
        if value is not None:
            filters.append(functools.partial(info[-1], value))
    return [load_bam(filename, name, filters) for filename, name in zip(args.reads, read_source_names)]

def parse(text, elements, fallback):
    """Parse given text and produce a list of inline elements.

    :param text: the text to be parsed.
    :param elements: the element types to be included in parsing
    :param fallback: fallback class when no other element type is matched."""
    tokens = []
    for etype in elements:
        for match in etype.find(text):
            tokens.append(Token(etype, match, text, fallback))
    tokens.sort()
    tokens = _resolve_overlap(tokens)
    return make_elements(tokens, text, fallback=fallback)

def find_links_or_emphs(text, root_node):
    """Fink links/images or emphasis from text.

    :param text: the original text.
    :param root_node: a reference to the root node of the AST.
    :returns: an iterable of match object."""
    delimiters_re = re.compile('(?:!?\\[|\\*+|_+)')
    i = 0
    delimiters = []
    escape = False
    matches = []
    code_pattern = re.compile('(?<!`)(`+)(?!`)([\\s\\S]+?)(?<!`)\\1(?!`)')
    while i < len(text):
        if escape:
            escape = False
            i += 1
        elif text[i] == '\\':
            escape = True
            i += 1
        elif code_pattern.match(text, i):
            i = code_pattern.match(text, i).end()
        elif text[i] == ']':
            node = look_for_image_or_link(text, delimiters, i, root_node, matches)
            if node:
                i = node.end()
                matches.append(node)
            else:
                i += 1
        else:
            m = delimiters_re.match(text, i)
            if m:
                delimiters.append(Delimiter(m, text))
                i = m.end()
            else:
                i += 1
    process_emphasis(text, delimiters, None, matches)
    return matches

def numchannels(samples: np.ndarray) -> int:
    """return the number of channels present in samples

    samples: a numpy array as returned by sndread

    for multichannel audio, samples is always interleaved,
    meaning that samples[n] returns always a frame, which
    is either a single scalar for mono audio, or an array
    for multichannel audio."""
    if len(samples.shape) == 1:
        return 1
    else:
        return samples.shape[1]

def turnstile_filter(global_conf, **local_conf):
    """Factory function for turnstile.

    Returns a function which, when passed the application, returns an
    instance of the TurnstileMiddleware."""
    klass = TurnstileMiddleware
    if 'turnstile' in local_conf:
        klass = utils.find_entrypoint('turnstile.middleware', local_conf['turnstile'], required=True)
    def wrapper(app):
        return klass(app, local_conf)
    return wrapper

def find_entrypoint(group, name, compat=True, required=False):
    """Finds the first available entrypoint with the given name in the
    given group.

    :param group: The entrypoint group the name can be found in.  If
                  None, the name is not presumed to be an entrypoint.
    :param name: The name of the entrypoint.
    :param compat: If True, and if the name parameter contains a ':',
                   the name will be interpreted as a module name and
                   an object name, separated by a colon.  This is
                   provided for compatibility.
    :param required: If True, and no corresponding entrypoint can be
                     found, an ImportError will be raised.  If False
                     (the default), None will be returned instead.

    :returns: The entrypoint object, or None if one could not be
              loaded."""
    if group is None or (compat and ':' in name):
        try:
            return pkg_resources.EntryPoint.parse('x=' + name).load(False)
        except (ImportError, pkg_resources.UnknownExtra) as exc:
            pass
    else:
        for ep in pkg_resources.iter_entry_points(group, name):
            try:
                return ep.load()
            except (ImportError, pkg_resources.UnknownExtra):
                continue
    if required:
        raise ImportError('Cannot import %r entrypoint %r' % (group, name))
    return None

