                print('Skipping %s' % str_arcfile)

def base64_process(**kwargs):
    """Process base64 file io"""
    str_fileToSave = ''
    str_fileToRead = ''
    str_action = 'encode'
    data = None
    for k, v in kwargs.items():
        if k == 'action':
            str_action = v
        if k == 'payloadBytes':
            data = v
        if k == 'payloadFile':
            str_fileToRead = v
        if k == 'saveToFile':
            str_fileToSave = v
    if str_action == 'encode':
        if len(str_fileToRead):
            with open(str_fileToRead, 'rb') as f:
                data = f.read()
                f.close()
        data_b64 = base64.b64encode(data)
        with open(str_fileToSave, 'wb') as f:
            f.write(data_b64)
            f.close()
        return {'msg': 'Encode successful', 'fileProcessed': str_fileToSave, 'status': True}
    if str_action == 'decode':
        bytes_decoded = base64.b64decode(data + '===')
        with open(str_fileToSave, 'wb') as f:
            f.write(bytes_decoded)
            f.close()
        return {'msg': 'Decode successful', 'fileProcessed': str_fileToSave, 'status': True}

