def declassify(to_remove, *args, **kwargs):
    """flatten the return values of the mite api.
    """
    def argdecorate(fn):
        """enable the to_remove argument to the decorator."""
        @wraps(fn)
        def declassed(*args, **kwargs):
            ret = fn(*args, **kwargs)
            try:
                if type(ret) is list:
                    return [r[to_remove] for r in ret]
                return ret[to_remove]
            except KeyError:
                return ret
        return declassed
    return argdecorate

def clean_dict(d):
    """remove the keys with None values."""
    ktd = list()
    for k, v in d.items():
        if not v:
            ktd.append(k)
        elif type(v) is dict:
            d[k] = clean_dict(v)
    for k in ktd:
        d.pop(k)
    return d

def sha256(content):
    """Finds the sha256 hash of the content."""
    if isinstance(content, str):
        content = content.encode('utf-8')
    return hashlib.sha256(content).hexdigest()

def is_binary(filename):
    """Returns True if the file is binary

    """
    with open(filename, 'rb') as fp:
        data = fp.read(1024)
        if not data:
            return False
        if b'\x00' in data:
            return True
        return False

def walk_files(args, root, directory, action):
    """Recusively go do the subdirectories of the directory,
    calling the action on each file"""
    for entry in os.listdir(directory):
        if is_hidden(args, entry):
            continue
        if is_excluded_directory(args, entry):
            continue
        if is_in_default_excludes(entry):
            continue
        if not is_included(args, entry):
            continue
        if is_excluded(args, entry, directory):
            continue
        entry = os.path.join(directory, entry)
        if os.path.isdir(entry):
            walk_files(args, root, entry, action)
        if os.path.isfile(entry):
            if is_binary(entry):
                continue
            action(entry)

def replace_in_file(args, in_file, regexp, repl):
    """Perfoms re.sub(regexp, repl, line) for each line in
    in_file"""
    in_lines = []
    try:
        with open(in_file, 'r') as in_fd:
            in_lines = in_fd.readlines()
    except (OSError, UnicodeDecodeError) as error:
        print('Cant open file:', in_file, error)
        return
    out_lines = in_lines[:]
    out_lines = [re.sub(regexp, repl, l) for l in in_lines]
    if in_lines == out_lines:
        return
    if not args.quiet:
        display_diff(in_file, regexp, repl, in_lines, out_lines)
    if not args.go:
        return
    if args.backup:
        backup(in_file, in_lines)
    with open(in_file, 'w') as fd:
        fd.writelines(out_lines)

def get_version(module):
    """Attempts to read a version attribute from the given module that
    could be specified via several different names and formats."""
    version_names = ['__version__', 'get_version', 'version']
    version_names.extend([name.upper() for name in version_names])
    for name in version_names:
        try:
            version = getattr(module, name)
        except AttributeError:
            continue
        if callable(version):
            version = version()
        try:
            version = '.'.join([str(i) for i in version.__iter__()])
        except AttributeError:
            pass
        return version

