def duration_to_timedelta(obj):
    """Converts duration to timedelta

    >>> duration_to_timedelta("10m")
    >>> datetime.timedelta(0, 600)"""
    matches = DURATION_PATTERN.search(obj)
    matches = matches.groupdict(default='0')
    matches = {k: int(v) for k, v in matches.items()}
    return timedelta(**matches)

def timedelta_to_duration(obj):
    '''Converts timedelta to duration

    >>> timedelta_to_duration(datetime.timedelta(0, 600))
    >>> "10m"'''
    minutes, hours, days = (0, 0, 0)
    seconds = int(obj.total_seconds())
    if seconds > 59:
        minutes = seconds // 60
        seconds = seconds % 60
    if minutes > 59:
        hours = minutes // 60
        minutes = minutes % 60
    if hours > 23:
        days = hours // 24
        hours = hours % 24
    response = []
    if days:
        response.append('%sd' % days)
    if hours:
        response.append('%sh' % hours)
    if minutes:
        response.append('%sm' % minutes)
    if seconds or not response:
        response.append('%ss' % seconds)
    return ''.join(response)

def dict_update(d, u):
    """Recursive dict update

    :param d: goal dict
    :param u: updates for d
    :return: new dict"""
    for k, v in six.iteritems(u):
        if isinstance(v, collections.Mapping):
            r = dict_update(d.get(k, {}), v)
            d[k] = r
        else:
            d[k] = u[k]
    return d

def parse_addr(addr, *, proto=None, host=None):
    """Parses an address

    Returns:
        Address: the parsed address"""
    port = None
    if isinstance(addr, Address):
        return addr
    elif isinstance(addr, str):
        if addr.startswith('http://'):
            proto, addr = ('http', addr[7:])
        if addr.startswith('udp://'):
            proto, addr = ('udp', addr[6:])
        elif addr.startswith('tcp://'):
            proto, addr = ('tcp', addr[6:])
        elif addr.startswith('unix://'):
            proto, addr = ('unix', addr[7:])
        a, _, b = addr.partition(':')
        host = a or host
        port = b or port
    elif isinstance(addr, (tuple, list)):
        a, b = addr
        host = a or host
        port = b or port
    elif isinstance(addr, int):
        port = addr
    else:
        raise ValueError('bad value')
    if port is not None:
        port = int(port)
    return Address(proto, host, port)

def get_data(param, data):
    """Retrieve weather parameter."""
    try:
        for _, selected_time_entry in data:
            loc_data = selected_time_entry['location']
            if param not in loc_data:
                continue
            if param == 'precipitation':
                new_state = loc_data[param]['@value']
            elif param == 'symbol':
                new_state = int(float(loc_data[param]['@number']))
            elif param in ('temperature', 'pressure', 'humidity', 'dewpointTemperature'):
                new_state = round(float(loc_data[param]['@value']), 1)
            elif param in ('windSpeed', 'windGust'):
                new_state = round(float(loc_data[param]['@mps']) * 3.6, 1)
            elif param == 'windDirection':
                new_state = round(float(loc_data[param]['@deg']), 1)
            elif param in ('fog', 'cloudiness', 'lowClouds', 'mediumClouds', 'highClouds'):
                new_state = round(float(loc_data[param]['@percent']), 1)
            return new_state
    except (ValueError, IndexError, KeyError):
        return None

def parse_datetime(dt_str):
    """Parse datetime."""
    date_format = '%Y-%m-%dT%H:%M:%S %z'
    dt_str = dt_str.replace('Z', ' +0000')
    return datetime.datetime.strptime(dt_str, date_format)

def prepare_node(data):
    """Prepare node for catalog endpoint

    Parameters:
        data (Union[str, dict]): Node ID or node definition
    Returns:
        Tuple[str, dict]: where first is ID and second is node definition

    Extract from /v1/health/service/<service>::

        {
            "Node": {
                "Node": "foobar",
                "Address": "10.1.10.12",
                "TaggedAddresses": {
                    "lan": "10.1.10.12",
                    "wan": "10.1.10.12"
                }
            },
            "Service": {...},
            "Checks": [...]
        }"""
    if not data:
        return (None, {})
    if isinstance(data, str):
        return (data, {})
    if all((field in data for field in ('Node', 'Service', 'Checks'))):
        return (data['Node']['Node'], data['Node'])
    result = {}
    if 'ID' in data:
        result['Node'] = data['ID']
    for k in ('Datacenter', 'Node', 'Address', 'TaggedAddresses', 'Service', 'Check', 'Checks'):
        if k in data:
            result[k] = data[k]
    if list(result) == ['Node']:
        return (result['Node'], {})
    return (result.get('Node'), result)

def prepare_check(data):
    """Prepare check for catalog endpoint

    Parameters:
        data (Object or ObjectID): Check ID or check definition
    Returns:
        Tuple[str, dict]: where first is ID and second is check definition"""
    if not data:
        return (None, {})
    if isinstance(data, str):
        return (data, {})
    result = {}
    if 'ID' in data:
        result['CheckID'] = data['ID']
    for k in ('Node', 'CheckID', 'Name', 'Notes', 'Status', 'ServiceID'):
        if k in data:
            result[k] = data[k]
    if list(result) == ['CheckID']:
        return (result['CheckID'], {})
    return (result.get('CheckID'), result)

def _create_http_client():
