    if auth_username and auth_password:
        defaults['auth_username'] = auth_username
        defaults['auth_password'] = auth_password
    _http_client = httpclient.AsyncHTTPClient(force_instance=True, defaults=defaults, max_clients=_max_clients)

def _maybe_warn_about_buffer_size():
    """Check the buffer size and issue a warning if it's too large and
    a warning has not been issued for more than 60 seconds."""
    global _last_warning
    if not _last_warning:
        _last_warning = time.time()
    if _buffer_size > _warn_threshold and time.time() - _last_warning > 120:
        LOGGER.warning('InfluxDB measurement buffer has %i entries', _buffer_size)

def _on_timeout():
    """Invoked periodically to ensure that metrics that have been collected
    are submitted to InfluxDB.

    :rtype: tornado.concurrent.Future or None"""
    global _buffer_size
    LOGGER.debug('No metrics submitted in the last %.2f seconds', _timeout_interval / 1000.0)
    _buffer_size = _pending_measurements()
    if _buffer_size:
        return _trigger_batch_write()
    _start_timeout()

def _sample_batch():
    """Determine if a batch should be processed and if not, pop off all of
    the pending metrics for that batch.

    :rtype: bool"""
    if _sample_probability == 1.0 or random.random() < _sample_probability:
        return True
    for database in _measurements:
        _measurements[database] = _measurements[database][_max_batch_size:]
    return False

def _uri_split(uri):
    """Splits up an URI or IRI."""
    scheme, netloc, path, query, fragment = _safe_urlsplit(uri)
    auth = None
    port = None
    if '@' in netloc:
        auth, netloc = netloc.split('@', 1)
    if netloc.startswith('['):
        host, port_part = netloc[1:].split(']', 1)
        if port_part.startswith(':'):
            port = port_part[1:]
    elif ':' in netloc:
        host, port = netloc.split(':', 1)
    else:
        host = netloc
    return (scheme, auth, host, port, path, query, fragment)

def url_quote(s, charset='utf-8', safe='/:'):
    """URL encode a single string with a given encoding.

    :param s: the string to quote.
    :param charset: the charset to be used.
    :param safe: an optional sequence of safe characters."""
    if isinstance(s, unicode):
        s = s.encode(charset)
    elif not isinstance(s, str):
        s = str(s)
    return _quote(s, safe=safe)

def url_quote_plus(s, charset='utf-8', safe=''):
    """URL encode a single string with the given encoding and convert
    whitespace to "+".

    :param s: the string to quote.
    :param charset: the charset to be used.
    :param safe: an optional sequence of safe characters."""
    if isinstance(s, unicode):
        s = s.encode(charset)
    elif not isinstance(s, str):
        s = str(s)
    return _quote_plus(s, safe=safe)

def nametonum(name):
    """Returns a color code number given the color name."""
    code = colorcodes.get(name)
    if code is None:
        raise ValueError('%s is not a valid color name.' % name)
    else:
        return code

def fgseq(code):
    """Returns the forground color terminal escape sequence for the given color code number or color name."""
    if isinstance(code, str):
        code = nametonum(code)
    if code == -1:
        return ''
    s = termcap.get('setaf', code) or termcap.get('setf', code)
    return s

def bgseq(code):
    """Returns the background color terminal escape sequence for the given color code number."""
    if isinstance(code, str):
        code = nametonum(code)
    if code == -1:
        return ''
    s = termcap.get('setab', code) or termcap.get('setb', code)
    return s

def make_limited_stream(stream, limit):
    """Makes a stream limited."""
    if not isinstance(stream, LimitedStream):
        if limit is None:
            raise TypeError('stream not limited and no limit provided.')
        stream = LimitedStream(stream, limit)
    return stream

