def get(cap, *args, **kwargs):
    """Get a terminal capability exposes through the `curses` module."""
    if 'READTHEDOCS' in os.environ:
        return ''
    if kwargs != {}:
        raise TypeError('get(): No such argument %r' % kwargs.popitem()[0])
    if _cache == {}:
        try:
            curses.setupterm()
        except:
            pass
    s = _cache.get(cap)
    if not s:
        s = curses.tigetstr(cap)
        if s == None:
            s = curses.tigetnum(cap)
            if s == -2:
                s = curses.tigetflag(cap)
                if s == -1:
                    s = ''
                else:
                    s = bool(s)
        _cache[cap] = s
    if args and s:
        r = curses.tparm(s, *args)
        return r.decode('utf-8')
    elif isinstance(s, bytes):
        return s.decode('utf-8')
    else:
        return s

def y_score(estimator, X):
    """Score examples from a new matrix X
    Args:
        estimator: an sklearn estimator object
        X: design matrix with the same features that the estimator was trained on

    Returns: a vector of scores of the same length as X

    Note that estimator.predict_proba is preferred but when unavailable
    (e.g. SVM without probability calibration) decision_function is used."""
    try:
        y = estimator.predict_proba(X)
        return y[:, 1]
    except AttributeError:
        return estimator.decision_function(X)

