        return True
    return type(t1) == type(t2)

def read_json(path, default=None, fatal=True, logger=None):
    """:param str|None path: Path to file to deserialize
    :param dict|list|None default: Default if file is not present, or if it's not json
    :param bool|None fatal: Abort execution on failure if True
    :param callable|None logger: Logger to use
    :return dict|list: Deserialized data from file"""
    path = resolved_path(path)
    if not path or not os.path.exists(path):
        if default is None:
            return abort('No file %s', short(path), fatal=(fatal, default))
        return default
    try:
        with io.open(path, 'rt') as fh:
            data = json.load(fh)
            if default is not None and type(data) != type(default):
                return abort('Wrong type %s for %s, expecting %s', type(data), short(path), type(default), fatal=(fatal, default))
            if logger:
                logger('Read %s', short(path))
            return data
    except Exception as e:
        return abort("Couldn't read %s: %s", short(path), e, fatal=(fatal, default))

def save_json(data, path, fatal=True, logger=None, sort_keys=True, indent=2, **kwargs):
    """Args:
        data (object | None): Data to serialize and save
        path (str | None): Path to file where to save
        fatal (bool | None): Abort execution on failure if True
        logger (callable | None): Logger to use
        sort_keys (bool): Save json with sorted keys
        indent (int): Indentation to use
        **kwargs: Passed through to `json.dump()`

    Returns:
        (int): 1 if saved, -1 if failed (when `fatal` is False)"""
    if data is None or not path:
        return abort('No file %s', short(path), fatal=fatal)
    try:
        path = resolved_path(path)
        ensure_folder(path, fatal=fatal, logger=None)
        if is_dryrun():
            LOG.info('Would save %s', short(path))
            return 1
        if hasattr(data, 'to_dict'):
            data = data.to_dict()
        if indent:
            kwargs.setdefault('separators', (',', ': '))
        with open(path, 'wt') as fh:
            json.dump(data, fh, sort_keys=sort_keys, indent=indent, **kwargs)
            fh.write('\n')
        if logger:
            logger('Saved %s', short(path))
        return 1
    except Exception as e:
        return abort("Couldn't save %s: %s", short(path), e, fatal=(fatal, -1))

def _print_unhashable(df, columns=None):
    """Replace unhashable values in a DataFrame with their string repr
    Args:
        df: DataFrame
        columns: columns to replace, if necessary. Default None replaces all columns."""
    for c in df.columns if columns is None else columns:
        if df.dtypes[c] == object:
            try:
                df[c].apply(hash)
            except TypeError:
                df[c] = df[c].dropna().apply(pformat).ix[df.index]
    return df

def read_git_branch():
    """Obtain the current branch name from the Git repository. If on Travis CI,
    use the ``TRAVIS_BRANCH`` environment variable."""
    if os.getenv('TRAVIS'):
        return os.getenv('TRAVIS_BRANCH')
    else:
        try:
            repo = git.repo.base.Repo(search_parent_directories=True)
            return repo.active_branch.name
        except Exception:
            return ''

def _argtop(y_score, k=None):
    """Returns the indexes of the top k scores (not necessarily sorted)"""
    if k is None:
        return slice(0, len(y_score))
    else:
        return _argsort(y_score, k)

def count_series(y_true, y_score, countna=False):
    """Returns series whose i-th entry is the number of examples in the top i"""
    y_true, y_score = to_float(y_true, y_score)
    top = _argsort(y_score)
    if not countna:
        a = (~np.isnan(y_true[top])).cumsum()
    else:
        a = range(1, len(y_true) + 1)
    return pd.Series(a, index=range(1, len(a) + 1))

def baseline(y_true, y_score=None):
    """Number of positive labels divided by number of labels,
        or zero if there are no labels"""
    if len(y_true) > 0:
        return np.nansum(y_true) / count(y_true, countna=False)
    else:
        return 0.0

def roc_auc(y_true, y_score):
    """Returns are under the ROC curve"""
    notnull = ~np.isnan(y_true)
    fpr, tpr, thresholds = sklearn.metrics.roc_curve(y_true[notnull], y_score[notnull])
    return sklearn.metrics.auc(fpr, tpr)

def recall_series(y_true, y_score, k=None, value=True):
    """Returns series of length k whose i-th entry is the recall in the top i"""
    y_true, y_score = to_float(y_true, y_score)
    top = _argsort(y_score, k)
    if not value:
        y_true = 1 - y_true
    a = np.nan_to_num(y_true[top]).cumsum()
    return pd.Series(a, index=np.arange(1, len(a) + 1))

def autorotate(image, orientation=None):
    """Rotate and return an image according to its Exif information.

    ROTATION_NEEDED = {
        1: 0,
        2: 0 (Mirrored),
        3: 180,
        4: 180 (Mirrored),
        5: -90 (Mirrored),
        6: -90,
        7: 90 (Mirrored),
        8: 90,
    }

    Args:
        image (PIL.Image.Image): PIL image to rotate
        orientation (): Optional orientation value in [1, 8]

    Returns:
        A :py:class:`~PIL.Image.Image` image."""
    orientation_value = orientation if orientation else image._getexif().get(EXIF_KEYS.get('Orientation'))
    if orientation_value is None:
        raise ImDirectException('No orientation available in Exif tag or given explicitly.')
    if orientation_value in (1, 2):
        i = image
    elif orientation_value in (3, 4):
        i = image.transpose(Image.ROTATE_180)
    elif orientation_value in (5, 6):
        i = image.transpose(Image.ROTATE_270)
    elif orientation_value in (7, 8):
        i = image.transpose(Image.ROTATE_90)
    else:
        i = image
    if orientation_value in (2, 4, 5, 7):
        i = i.transpose(Image.FLIP_LEFT_RIGHT)
    return i

