def ensure_folder(path, folder=False, fatal=True, logger=LOG.debug, dryrun=None):
    """:param str|None path: Path to file or folder
    :param bool folder: If True, 'path' refers to a folder (file otherwise)
    :param bool|None fatal: Abort execution on failure if True
    :param callable|None logger: Logger to use
    :param bool|None dryrun: If specified, override global is_dryrun()
    :return int: 1 if effectively done, 0 if no-op, -1 on failure"""
    if not path:
        return 0
    if folder:
        folder = resolved_path(path)
    else:
        folder = parent_folder(path)
    if os.path.isdir(folder):
        if not os.access(folder, os.W_OK):
            return abort('Folder %s is not writable', folder, fatal=(fatal, -1), logger=logger)
        return 0
    if dryrun is None:
        dryrun = is_dryrun()
    if dryrun:
        LOG.debug('Would create %s', short(folder))
        return 1
    try:
        os.makedirs(folder)
        if logger:
            logger('Created folder %s', short(folder))
        return 1
    except Exception as e:
        return abort("Can't create folder %s: %s", short(folder), e, fatal=(fatal, -1), logger=logger)

def parent_folder(path, base=None):
    """:param str|None path: Path to file or folder
    :param str|None base: Base folder to use for relative paths (default: current working dir)
    :return str: Absolute path of parent folder of 'path'"""
    return path and os.path.dirname(resolved_path(path, base=base))

def follow(id, edges, directed=False, _visited=None):
    """Follow the a graph to find the nodes connected to a given node.
    Args:
        id: the id of the starting node
        edges: a pandas DataFrame of edges. Each row is an edge with two columns containing
            the ids of the vertices.
        directed: If True, edges are directed from first column to second column.
              Otherwise edges are undirected.
        _visited: used internally for recursion
    Returns: the set of all nodes connected to the starting node."""
    if _visited is None:
        _visited = set()
    _visited.add(id)
    for row in edges[edges.ix[:, 0] == id].values:
        if row[1] not in _visited:
            follow(row[1], edges, directed, _visited)
    if not directed:
        for row in edges[edges.ix[:, 1] == id].values:
            if row[0] not in _visited:
                follow(row[0], edges, directed, _visited)
    return _visited

def parse_pkg_info(fn):
    """:param str fn:
    :rtype: dict[str,str]"""
    res = {}
    for ln in open(fn).read().splitlines():
        if not ln or not ln[:1].strip():
            continue
        key, value = ln.split(': ', 1)
        res[key] = value
    return res

def grep_full_py_identifiers(tokens):
    """:param typing.Iterable[(str,str)] tokens:
    :rtype: typing.Iterator[str]"""
    global py_keywords
    tokens = list(tokens)
    i = 0
    while i < len(tokens):
        token_type, token = tokens[i]
        i += 1
        if token_type != 'id':
            continue
        while i + 1 < len(tokens) and tokens[i] == ('op', '.') and (tokens[i + 1][0] == 'id'):
            token += '.' + tokens[i + 1][1]
            i += 2
        if token == '':
            continue
        if token in py_keywords:
            continue
        if token[0] in '.0123456789':
            continue
        yield token

def simple_debug_shell(globals, locals):
    """:param dict[str] globals:
    :param dict[str] locals:
    :return: nothing"""
    try:
        import readline
    except ImportError:
        pass
    compile_string_fn = '<simple_debug_shell input>'
    while True:
        try:
            s = raw_input('> ')
        except (KeyboardInterrupt, EOFError):
            print('breaked debug shell: ' + sys.exc_info()[0].__name__)
            break
        if s.strip() == '':
            continue
        try:
            c = compile(s, compile_string_fn, 'single')
        except Exception as e:
            print('%s : %s in %r' % (e.__class__.__name__, str(e), s))
        else:
            set_linecache(compile_string_fn, s)
            try:
                ret = eval(c, globals, locals)
            except (KeyboardInterrupt, SystemExit):
                print('debug shell exit: ' + sys.exc_info()[0].__name__)
                break
            except Exception:
                print('Error executing %r' % s)
                better_exchook(*sys.exc_info(), autodebugshell=False)
            else:
                try:
                    if ret is not None:
                        print(ret)
                except Exception:
                    print('Error printing return value of %r' % s)
                    better_exchook(*sys.exc_info(), autodebugshell=False)

def fallback_findfile(filename):
    """:param str filename:
    :return: try to find the full filename, e.g. in modules, etc
    :rtype: str|None"""
    mods = [m for m in sys.modules.values() if m and hasattr(m, '__file__') and (filename in m.__file__)]
    if len(mods) == 0:
        return None
    alt_fn = mods[0].__file__
    if alt_fn[-4:-1] == '.py':
        alt_fn = alt_fn[:-1]
    if not os.path.exists(alt_fn) and alt_fn.startswith('./'):
        alt_fn2 = _cur_pwd + alt_fn[1:]
        if os.path.exists(alt_fn2):
            return alt_fn2
        for m in ['__main__', 'better_exchook']:
            if hasattr(sys.modules.get(m), '__file__'):
                alt_fn2 = os.path.dirname(sys.modules[m].__file__) + alt_fn[1:]
                if os.path.exists(alt_fn2):
                    return alt_fn2
    return alt_fn

def is_source_code_missing_open_brackets(source_code):
    """:param str source_code:
    :return: whether this source code snippet (e.g. one line) is complete/even w.r.t. opening/closing brackets
    :rtype: bool"""
    open_brackets = '[{('
    close_brackets = ']})'
    last_close_bracket = [-1]
    counters = [0] * len(open_brackets)
    for t_type, t_content in reversed(list(parse_py_statements(source_code))):
        if t_type != 'op':
            continue
        if t_content in open_brackets:
            idx = open_brackets.index(t_content)
            if last_close_bracket[-1] == idx:
                counters[idx] -= 1
                del last_close_bracket[-1]
        elif t_content in close_brackets:
            idx = close_brackets.index(t_content)
            counters[idx] += 1
            last_close_bracket += [idx]
    return not all([c == 0 for c in counters])

def add_indent_lines(prefix, s):
    """:param str prefix:
    :param str s:
    :return: s with prefix indent added to all lines
    :rtype: str"""
    if not s:
        return prefix
    prefix_len = str_visible_len(prefix)
    lines = s.splitlines(True)
    return ''.join([prefix + lines[0]] + [' ' * prefix_len + l for l in lines[1:]])

def remove_indent_lines(s):
    """:param str s:
    :return: remove as much indentation as possible
    :rtype: str"""
    if not s:
        return ''
    lines = s.splitlines(True)
    prefix = get_same_indent_prefix(lines)
    if prefix is None:
        return ''.join([l.lstrip() for l in lines])
    return ''.join([l[len(prefix):] for l in lines])

def replace_tab_indents(s, replace='    '):
    """:param str s: multi-line string with tabs
    :param str replace: e.g. 4 spaces
    :rtype: str"""
    lines = s.splitlines(True)
    return ''.join([replace_tab_indent(l, replace) for l in lines])

def to_bool(s, fallback=None):
    """:param str s: str to be converted to bool, e.g. "1", "0", "true", "false"
    :param T fallback: if s is not recognized as a bool
    :return: boolean value, or fallback
    :rtype: bool|T"""
    if not s:
        return fallback
    s = s.lower()
    if s in ['1', 'true', 'yes', 'y']:
        return True
    if s in ['0', 'false', 'no', 'n']:
        return False
    return fallback

def is_at_exit():
    """Some heuristics to figure out whether this is called at a stage where the Python interpreter is shutting down.

    :return: whether the Python interpreter is currently in the process of shutting down
    :rtype: bool"""
    if _threading_main_thread is not None:
        if not hasattr(threading, 'main_thread'):
            return True
        if threading.main_thread() != _threading_main_thread:
            return True
        if not _threading_main_thread.is_alive():
            return True
    return False

def print_tb(tb, file=None, **kwargs):
    """:param types.TracebackType|types.FrameType|StackSummary tb:
    :param io.TextIOBase|io.StringIO|None file: stderr by default
    :return: nothing, prints to ``file``"""
    if file is None:
        file = sys.stderr
    for l in format_tb(tb=tb, **kwargs):
        file.write(l)
    file.flush()

def dump_all_thread_tracebacks(exclude_thread_ids=None, file=None):
    """Prints the traceback of all threads.

    :param set[int]|list[int]|None exclude_thread_ids: threads to exclude
    :param io.TextIOBase|io.StringIO file: output stream"""
    if exclude_thread_ids is None:
        exclude_thread_ids = []
    if not file:
        file = sys.stdout
    import threading
    if hasattr(sys, '_current_frames'):
        print('', file=file)
        threads = {t.ident: t for t in threading.enumerate()}
        for tid, stack in sys._current_frames().items():
            if tid in exclude_thread_ids:
                continue
            if tid not in threads:
                continue
            tags = []
            thread = threads.get(tid)
            if thread:
                assert isinstance(thread, threading.Thread)
                if thread is threading.currentThread():
                    tags += ['current']
                if isinstance(thread, threading._MainThread):
                    tags += ['main']
                tags += [str(thread)]
            else:
                tags += ['unknown with id %i' % tid]
            print('Thread %s:' % ', '.join(tags), file=file)
            print_tb(stack, file=file)
            print('', file=file)
        print('That were all threads.', file=file)
    else:
        print('Does not have sys._current_frames, cannot get thread tracebacks.', file=file)

def get_current_frame():
    """:return: current frame object (excluding this function call)
    :rtype: types.FrameType

    Uses sys._getframe if available, otherwise some trickery with sys.exc_info and a dummy exception."""
    if hasattr(sys, '_getframe'):
        return sys._getframe(1)
    try:
        raise ZeroDivisionError
    except ZeroDivisionError:
        return sys.exc_info()[2].tb_frame.f_back

def load(steps, reload=False):
    """safely load steps in place, excluding those that fail
    Args:
        steps: the steps to load"""
    if reload:
        _STEP_CACHE.clear()
    if callable(steps):
        steps = steps()
    if not isinstance(steps, collections.Iterable):
        return load([steps])[0]
    loaded = []
    for s in steps:
        digest = s._digest
        if digest in _STEP_CACHE:
            loaded.append(_STEP_CACHE[digest])
        else:
            try:
                s.load()
                _STEP_CACHE[digest] = s
                loaded.append(s)
            except Exception:
                logging.warn('Error during step load:\n%s' % util.indent(traceback.format_exc()))
    return loaded

def _simplify_arguments(arguments):
    """If positional or keyword arguments are empty return only one or the other."""
    if len(arguments.args) == 0:
        return arguments.kwargs
    elif len(arguments.kwargs) == 0:
        return arguments.args
    else:
        return arguments

def _expand_inputs(step, steps=None):
    """Returns the set of this step and all steps passed to the constructor (recursively)."""
    if steps is None:
        steps = set()
    for arg in step._kwargs.values():
        if isinstance(arg, Step):
            _expand_inputs(arg, steps=steps)
        elif util.is_instance_collection(arg, Step):
            for s in util.get_collection_values(arg):
                _expand_inputs(s, steps=steps)
    steps.add(step)
    return steps

def _collect_kwargs(step, drop_duplicate_names=True):
    """Collect the kwargs of this step and inputs passed to the constructor (recursively)
    Returns: dictionary of name: kwargs pairs where name is the name of
        a step and kwargs is its kwargs minus inputs. If the step doesn't have
        a name __class__.__name__ is used."""
    dicts = {}
    duplicates = set()
    for s in _expand_inputs(step):
        name = s.name if s.name is not None else s.__class__.__name__
        if name in dicts.keys():
            if drop_duplicate_names:
                duplicates.add(name)
            else:
                raise ValueError('Duplicate step names: %s' % name)
        d = dict(s._kwargs)
        d = {k: v for k, v in d.items() if not (isinstance(v, Step) or util.is_instance_collection(v, Step))}
        dicts[name] = d
    dicts = {k: v for k, v in dicts.items() if k not in duplicates}
    return dicts

def _output_dirnames(workflow=None, leaf=False):
    """Args:
        workflow: optional collection of steps
        leaf: only include leaves of the workflow

    Returns: If workflow is specified, returns output directories for all target
        steps in the workflow. If no workflow specified, returns all extant
        output directories in drain.PATH."""
    if workflow is None:
        dirs = set()
        for cls in os.listdir(drain.PATH):
            for step in os.listdir(os.path.join(drain.PATH, cls)):
                dirs.add(os.path.join(drain.PATH, cls, step))
        return dirs
    else:
        if leaf:
            steps = [step for step in workflow if step.target]
        else:
            steps = util.union((step.get_inputs() for step in workflow if step.target))
        return set((step._output_dirname for step in steps))

def days(date1, date2):
    """returns a lambda that determines the number of days between the two dates
    the dates can be strings (column names) or actual dates
    e.g. Aggregate(days('date', today), ['min','max'], 'days_since')
    TODO: should there be a Days(AggregateBase) for this? handle naming"""
    return lambda df, date1=date1, date2=date2: _days(df, date1, date2)

def _replace_and_pad(fmt, marker, replacement):
    """Args:
        fmt (str | unicode): Format to tweak
        marker (str | unicode): Marker to replace
        replacement (str | unicode): What to replace marker with

    Returns:
        (str): Resulting format, with marker replaced"""
    if marker not in fmt:
        return fmt
    if replacement:
        return fmt.replace(marker, replacement)
    fmt = fmt.replace('%s ' % marker, marker)
    return fmt.replace(marker, '')

def decode(value, strip=False):
    """Python 2/3 friendly decoding of output.

    Args:
        value (str | unicode | bytes | None): The value to decode.
        strip (bool): If True, `strip()` the returned string. (Default value = False)

    Returns:
        str: Decoded value, if applicable."""
    if value is None:
        return None
    if isinstance(value, bytes) and (not isinstance(value, unicode)):
        value = value.decode('utf-8')
    if strip:
        return unicode(value).strip()
    return unicode(value)

def validate_clabe(clabe: str) -> bool:
    """Validate CLABE according to
    https://es.wikipedia.org/wiki/CLABE#D.C3.ADgito_control"""
    return clabe.isdigit() and len(clabe) == CLABE_LENGTH and (clabe[:3] in BANKS.keys()) and (clabe[-1] == compute_control_digit(clabe))

def header(text, border='--'):
    """Args:
        text (str | unicode): Text to turn into a header
        border (str | unicode): Characters to use to decorate header

    Returns:
        (str): Decorated"""
    if not text or not border:
        return text
    if border.endswith(' '):
        decorated = '%s%s' % (border, text)
        fmt = '{decorated}\n{hr}'
    else:
        decorated = '%s %s %s' % (border, text, border)
        fmt = '{hr}\n{decorated}\n{hr}'
    return fmt.format(decorated=decorated, hr=border[0] * len(decorated))

def execute(path, arguments):
    """Wrapper around execv():

    * fork()s before exec()ing (in order to run the command in a subprocess)
    * wait for the subprocess to finish before returning (blocks the parent
      process)

    This is **hyper** simplistic. This *does not* handle **many** edge cases.

    *DO NOT DO THIS*: subprocess.check_call() does it better, and handle edge
    cases."""
    pid = os.fork()
    if pid == 0:
        try:
            os.execv(path, arguments)
        finally:
            sys.exit(1)
    else:
        try:
            os.waitpid(pid, NORMAL_PIDWAIT)
        except OSError:
            pass
        return

