def to_boolean(value):
    """Args:
        value (str | unicode | None): Value to convert to bool

    Returns:
        (bool): Deduced boolean value"""
    if value is not None:
        if str(value).lower() in TRUE_TOKENS:
            return True
        vfloat = to_number(float, value)
        if vfloat is not None:
            return bool(vfloat)
    return False

def to_bytesize(value, default_unit=None, base=DEFAULT_BASE):
    """Convert `value` to bytes, accepts notations such as "4k" to mean 4096 bytes

    Args:
        value (str | unicode | int | None): Number of bytes optionally suffixed by a char from UNITS
        default_unit (str | unicode | None): Default unit to use for unqualified values
        base (int): Base to use (usually 1024)

    Returns:
        (int | None): Deduced bytesize value, if possible"""
    if isinstance(value, (int, float)):
        return unitized(value, default_unit, base)
    if value is None:
        return None
    try:
        if value[-1].lower() == 'b':
            value = value[:-1]
        unit = value[-1:].lower()
        if unit.isdigit():
            unit = default_unit
        else:
            value = value[:-1]
        return unitized(to_number(float, value), unit, base)
    except (IndexError, TypeError, ValueError):
        return None

def to_dict(value, prefix=None, separators='=,'):
    """Args:
        value: Value to turn into a dict
        prefix (str | unicode | None): Optional prefix for keys (if provided, `prefix.` is added to all keys)
        separators (str | unicode): 2 chars: 1st is assignment separator, 2nd is key-value pair separator

    Returns:
        (dict): Parse key/values"""
    if not value or isinstance(value, dict):
        return value or {}
    result = {}
    for val in flattened(value, split=(separators[1], SANITIZED)):
        if not val:
            continue
        if hasattr(val, 'partition'):
            k, _, v = val.partition(separators[0])
            k = k.strip()
            if k:
                v = v.strip()
                if prefix and (not k.startswith(prefix)):
                    k = '%s.%s' % (prefix, k)
                result[k] = v
    return result

def get_user_name(user, full_name=True):
    """Return the user's name as a string.

    :param user: `models.User` object. The user to get the name of.
    :param full_name: (optional) Whether to return full user name, or just first name.
    :return: The user's name."""
    try:
        if full_name:
            name = ' '.join([user.first_name, user.last_name])
        else:
            name = user.first_name
    except AttributeError:
        name = None
    return name

def sign_in(user, user_type=None, date=None, time_in=None):
    """Add a new entry to the timesheet.

    :param user: `models.User` object. The user to sign in.
    :param user_type: (optional) Specify whether user is signing in as a `'student'` or `'tutor'`.
    :param date: (optional) `datetime.date` object. Specify the entry date.
    :param time_in: (optional) `datetime.time` object. Specify the sign in time.
    :return: The new entry."""
    now = datetime.today()
    if date is None:
        date = now.date()
    if time_in is None:
        time_in = now.time()
    if user_type is None:
        if user.is_student and user.is_tutor:
            raise AmbiguousUserType('User is both a student and a tutor.')
        elif user.is_student:
            user_type = 'student'
        elif user.is_tutor:
            user_type = 'tutor'
        else:
            raise ValueError('Unknown user type.')
    new_entry = Entry(uuid=str(uuid.uuid4()), date=date, time_in=time_in, time_out=None, user_id=user.user_id, user_type=user_type, user=user)
    logger.info('{} ({}) signed in.'.format(new_entry.user_id, new_entry.user_type))
    return new_entry

def _createunbound(kls, **info):
    """Create a new UnboundNode representing a given class."""
    if issubclass(kls, Bitfield):
        nodetype = UnboundBitfieldNode
    elif hasattr(kls, '_fields_'):
        nodetype = UnboundStructureNode
    elif issubclass(kls, ctypes.Array):
        nodetype = UnboundArrayNode
    else:
        nodetype = UnboundSimpleNode
    return nodetype(type=kls, **info)

def _createbound(obj):
    """Create a new BoundNode representing a given object."""
    try:
        kls = obj._unboundreference_()
    except AttributeError:
        kls = type(obj)
    unbound = _createunbound(kls)
    def valueget():
        return obj
    for t in (BoundBitfieldNode, BoundStructureNode, BoundArrayNode):
        if isinstance(unbound, t._unboundtype):
            kls = t
            break
    else:
        kls = BoundSimpleNode
    child = kls(unbound, valueget)
    return child

def findnode(obj, path=''):
    """Returns a Node pointing to obj.

    If obj is a ctypes-derived class, an UnboundNode is returned.  If obj is
    an instance of such a class, then a BoundNode will be returned.

    If the optional path is provided, it is a string to look up searching
    down the original source node, such as '.overhead.window[2].page'"""
    if isclass(obj):
        node = _createunbound(obj)
    else:
        node = _createbound(obj)
    pathparts = re.split('\\]?(?:[[.]|$)', path)
    for part in pathparts:
        if not part:
            continue
        try:
            idx = int(part)
            node = node[idx]
        except ValueError:
            node = node[part]
    return node

def walknode(top, skiphidden=True):
    """Returns a recursive iterator over all Nodes under top.

    If skiphidden is True (the default) then structure branches starting with
    an underscore will be ignored."""
    if skiphidden and top.name.startswith('._'):
        return
    yield top
    for child in top:
        for c in walknode(child):
            yield c

def load_post_webhook(request):
    """Webhook to insert/update a WordPress.com post on the local Django site.
    Call this after making changes to the post in WP Admin.
    The post is processed asynchronously so that a response can be returned to WordPress.com immediately.

    :param request: Should contain the WordPress post ID, named "ID", in POST form data
    :return: JsonResponse indicated the refresh is in progress."""
    try:
        wp_post_id = int(request.POST['ID'])
    except:
        raise Http404('Post does not exist')
    load_post.after_response(wp_post_id)
    return JsonResponse({'status': 'Refreshing wp_post_id: {}'.format(wp_post_id)})

