        raise SourceNotFound(source_path)
    with open(source_path, 'r') as f:
        content = f.read()
    block_map = BlockMap()
    all_block = convert_lines_to_block(content.splitlines(), block_map, LinkStack(source_path), source_path)
    return (all_block, block_map.get_variables())

def get_block_dict(top_level_block):
    """Returns a dictionary of block names (str) to block contents (str) for all child blocks, as
    well as the original block itself.

    The block_dict argument is only used for recursive calls and should not"""
    block_stack = [top_level_block]
    block_dict = {}
    while block_stack:
        block = block_stack.pop()
        block_dict[block.name] = str(block)
        for segment in block.segments:
            if isinstance(segment, Block):
                block_stack.append(segment)
    return block_dict

def xavier_init(fan_in, fan_out, constant=1):
    """Xavier initialization of network weights"""
    low = -constant * np.sqrt(6.0 / (fan_in + fan_out))
    high = constant * np.sqrt(6.0 / (fan_in + fan_out))
    return tf.random_uniform((fan_in, fan_out), minval=low, maxval=high, dtype=tf.float32)

def get_ajd_bound(mesh):
    """Determine triangular elements adjacend to the boundary elements"""
    print('Get elements adjacent to boundaries')
    boundary_elements = []
    str_adj_boundaries = ''
    boundaries = mesh['boundaries']['12'] + mesh['boundaries']['11']
    for boundary in boundaries:
        indices = [nr if boundary[0] in x and boundary[1] in x else np.nan for nr, x in enumerate(mesh['elements']['2'])]
        indices = np.array(indices)[~np.isnan(indices)]
        if len(indices) != 1:
            print('More than one neighbour found!')
        elif len(indices) == 0:
            print('No neighbour found!')
        boundary_elements.append(indices[0])
        str_adj_boundaries += '{0}\n'.format(int(indices[0]) + 1)
    return (str_adj_boundaries, boundary_elements)

