def delete(stack_ref: List[str], region: str, dry_run: bool, force: bool, remote: str):
    """Delete Cloud Formation stacks"""
    lizzy = setup_lizzy_client(remote)
    stack_refs = get_stack_refs(stack_ref)
    all_with_version = all((stack.version is not None for stack in stack_refs))
    if not all_with_version and (not dry_run) and (not force):
        fatal_error('Error: {} matching stacks found. '.format(len(stack_refs)) + 'Please use the "--force" flag if you really want to delete multiple stacks.')
    output = ''
    for stack in stack_refs:
        if stack.version is not None:
            stack_id = '{stack.name}-{stack.version}'.format(stack=stack)
        else:
            stack_id = stack.name
        with Action("Requesting stack '{stack_id}' deletion..", stack_id=stack_id):
            output = lizzy.delete(stack_id, region=region, dry_run=dry_run)
    print(output)

def py2dict(elements):
    """Convert a Python object into a Python dictionary."""
    metadata_dict = {}
    for element in elements.children:
        if element.tag not in metadata_dict:
            metadata_dict[element.tag] = []
        element_dict = {}
        if hasattr(element, 'qualifier') and element.qualifier is not None:
            element_dict['qualifier'] = element.qualifier
        if len(element.children) > 0:
            child_dict = {}
            for child in element.children:
                if child.content is not None:
                    child_dict[child.tag] = child.content
            element_dict['content'] = child_dict
        elif element.content is not None:
            if element.content.strip() != '':
                element_dict['content'] = element.content
        if element_dict.get('content', False):
            metadata_dict[element.tag].append(element_dict)
    return metadata_dict

