def create_dict_subelement(root, subelement, content, **kwargs):
    """Create a XML subelement from a Python dictionary."""
    attribs = kwargs.get('attribs', None)
    namespace = kwargs.get('namespace', None)
    key = subelement
    if namespace and attribs:
        subelement = SubElement(root, namespace + subelement, attribs)
    elif namespace:
        subelement = SubElement(root, namespace + subelement)
    elif attribs:
        subelement = SubElement(root, subelement, attribs)
    else:
        subelement = SubElement(root, subelement)
    if not isinstance(content, dict):
        subelement.text = content
    elif key == 'degree':
        for degree_order_key in DEGREE_ORDER:
            for descriptor, value in content.items():
                if descriptor == degree_order_key:
                    sub_descriptors = SubElement(subelement, descriptor)
                    sub_descriptors.text = value
    else:
        for descriptor, value in content.items():
            sub_descriptors = SubElement(subelement, descriptor)
            sub_descriptors.text = value

def highwiredict2xmlstring(highwire_elements, ordering=HIGHWIRE_ORDER):
    """Create an XML string from the highwire data dictionary."""
    highwire_elements.sort(key=lambda obj: ordering.index(obj.name))
    root = Element('metadata')
    for element in highwire_elements:
        attribs = {'name': element.name, 'content': element.content}
        SubElement(root, 'meta', attribs)
    return '<?xml version="1.0" encoding="UTF-8"?>\n' + tostring(root, pretty_print=True)

def writeANVLString(ANVLDict, ordering=UNTL_XML_ORDER):
    """Take a dictionary and write out the key/value pairs
    in ANVL format."""
    lines = []
    for key in ordering:
        if key in ANVLDict:
            element_list = ANVLDict[key]
            for element in element_list:
                value = element.get('content', '')
                offset = len(key) + 1
                line = '%s: %s' % (key, breakString(value, 79, offset))
                lines.append(line)
    return '\n'.join(lines)

def hash_inline_links(text, hashes, markdown_obj):
    """Hashes an <a> link or an <img> link.

    This function only converts inline link styles:

        [text here](path/to/resource "optional title")
        ![alt text here](path/to/resource "optional title")

    For reference style links, see hash_reference_links"""
    def sub(match):
        is_img = match.group(1) != ''
        content = match.group(2)
        link = match.group(3)
        title = match.group(5)
        if title:
            title = ' title="{0}"'.format(title.strip())
        else:
            title = ''
        if is_img:
            result = '<img src="{0}" alt="{1}"{2}>'.format(link, content, title)
        else:
            result = '<a href="{0}"{2}>{1}</a>'.format(link, markdown_obj.convert(content).replace('<p>', '').replace('</p>', ''), title)
        hashed = hash_text(result, 'link')
        hashes[hashed] = result
        return hashed
    return re_inline_link.sub(sub, text)

def emphasis_sub(match):
    """Substitutes <strong>, <em>, and <strong><em> tags."""
    level = len(match.group(1))
    content = match.group(2)
    if level == 3:
        return '<strong><em>{0}</em></strong>'.format(content)
    elif level == 2:
        return '<strong>{0}</strong>'.format(content)
    elif level == 1:
        return '<em>{0}</em>'.format(content)

def atx_header_sub(match):
    """Substitutes atx headers (headers defined using #'s)."""
    level = len(match.group(1))
    title = match.group(2)
    id_class = ''
    ids = match.group(3) if match.group(3) else ''
    id_match = re.search('#([\\w-]+)', ids)
    if id_match:
        id_class += ' id="' + id_match.group(1) + '"'
    classes = ' '.join(re.findall('\\.([\\w-]+)', ids))
    if classes:
        id_class += ' class="' + classes + '"'
    return '\n<h{0}{2}>{1}</h{0}>\n'.format(level, title, id_class)

def paragraph_sub(match):
    """Captures paragraphs."""
    text = re.sub('  \\n', '\\n<br/>\\n', match.group(0).strip())
    return '<p>{}</p>'.format(text)

def slug_sub(match):
    """Assigns id-less headers a slug that is derived from their
    titles. Slugs are generated by lower-casing the titles, stripping
    all punctuation, and converting spaces to hyphens (-)."""
    level = match.group(1)
    title = match.group(2)
    slug = title.lower()
    slug = re.sub('<.+?>|[^\\w-]', ' ', slug)
    slug = re.sub('[ \\t]+', ' ', slug).strip()
    slug = slug.replace(' ', '-')
    if slug:
        return '<{0} id="{1}">{2}</{0}>'.format(level, slug, title)
    return match.group(0)

def log_response(handler):
    """Acturally, logging response is not a server's responsibility,
    you should use http tools like Chrome Developer Tools to analyse the response.

    Although this function and its setting(LOG_RESPONSE) is not recommended to use,
    if you are laze as I was and working in development, nothing could stop you."""
    content_type = handler._headers.get('Content-Type', None)
    headers_str = handler._generate_headers()
    block = 'Response Infomations:\n' + headers_str.strip()
    if content_type and ('text' in content_type or 'json' in content_type):
        limit = 0
        if 'LOG_RESPONSE_LINE_LIMIT' in settings:
            limit = settings['LOG_RESPONSE_LINE_LIMIT']
        def cut(s):
            if limit and len(s) > limit:
                return [s[:limit]] + cut(s[limit:])
            else:
                return [s]
        body = ''.join(handler._write_buffer)
        lines = []
        for i in body.split('\n'):
            lines += ['| ' + j for j in cut(i)]
        block += '\nBody:\n' + '\n'.join(lines)
    app_log.info(block)

def log_request(handler):
    """Logging request is opposite to response, sometime its necessary,
    feel free to enable it."""
    block = 'Request Infomations:\n' + _format_headers_log(handler.request.headers)
    if handler.request.arguments:
        block += '+----Arguments----+\n'
        for k, v in handler.request.arguments.items():
            block += '| {0:<15} | {1:<15} \n'.format(repr(k), repr(v))
    app_log.info(block)

def executed_block_set(trace):
    """Given an execution trace, returns a python set object containing the names of each block for which the user code
    was executed. Block names can be set via set_debug_name()."""
    executed_set = set()
    for entry in trace:
        if entry[0] == 'execute':
            executed_set.add(entry[get_trace_index('execute', 'BLOCK_NAME')])
    return executed_set

