def mbcs_work_around():
    """work around for mbcs codec to make "bdist_wininst" work
    https://mail.python.org/pipermail/python-list/2012-February/620326.html"""
    import codecs
    try:
        codecs.lookup('mbcs')
    except LookupError:
        ascii = codecs.lookup('ascii')
        codecs.register(lambda name: {True: ascii}.get(name == 'mbcs'))

def get_stack_refs(refs: list):
    """Returns a list of stack references with name and version."""
    refs = list(refs)
    refs.reverse()
    stack_refs = []
    last_stack = None
    while refs:
        ref = refs.pop()
        if last_stack is not None and re.compile('v[0-9][a-zA-Z0-9-]*$').match(ref):
            stack_refs.append(StackReference(last_stack, ref))
        else:
            try:
                with open(ref) as fd:
                    data = yaml.safe_load(fd)
                ref = data['SenzaInfo']['StackName']
            except (OSError, IOError):
                pass
            if refs:
                version = refs.pop()
            else:
                version = None
            stack_refs.append(StackReference(ref, version))
            last_stack = ref
    return stack_refs

def push(config, force=False):
    """Create push the current branch."""
    repo = config.repo
    active_branch = repo.active_branch
    if active_branch.name == 'master':
        error_out("Can't commit when on the master branch. You really ought to do work in branches.")
    state = read(config.configfile)
    if not state.get('FORK_NAME'):
        info_out("Can't help you push the commit. Please run: gg config --help")
        return 0
    try:
        repo.remotes[state['FORK_NAME']]
    except IndexError:
        error_out("There is no remote called '{}'".format(state['FORK_NAME']))
    destination = repo.remotes[state['FORK_NAME']]
    if force:
        pushed, = destination.push(force=True)
        info_out(pushed.summary)
    else:
        pushed, = destination.push()
        if pushed.flags & git.remote.PushInfo.REJECTED or pushed.flags & git.remote.PushInfo.REMOTE_REJECTED:
            error_out('The push was rejected ("{}")'.format(pushed.summary), False)
            try_force_push = input('Try to force push? [Y/n] ').lower().strip()
            if try_force_push not in ('no', 'n'):
                pushed, = destination.push(force=True)
                info_out(pushed.summary)
            else:
                return 0

