def print_tb(tb, limit=None, file=None):
    """Print up to 'limit' stack trace entries from the traceback 'tb'.

    If 'limit' is omitted or None, all entries are printed.  If 'file'
    is omitted or None, the output goes to sys.stderr; otherwise
    'file' should be an open file or file-like object with a write()
    method."""
    if file is None:
        file = sys.stderr
    if limit is None:
        if hasattr(sys, 'tracebacklimit'):
            limit = sys.tracebacklimit
    file.write('\n'.join(format_tb(tb, limit)) + '\n')

def get_imports(filename, source=None):
    """Returns a list of #ImportInfo tuples for all module imports in the specified
    Python source file or the *source* string."""
    if source is None:
        with open(filename, 'rb') as fp:
            source = fp.read()
    module = ast.parse(source, filename)
    result = []
    for node in _find_nodes(module, lambda x: isinstance(x, ast.Import)):
        for alias in node.names:
            result.append(ImportInfo(alias.name, filename, node.lineno))
    for node in _find_nodes(module, lambda x: isinstance(x, ast.ImportFrom)):
        import_name = '.' * node.level + (node.module or '')
        result.append(ImportInfo(import_name, filename, node.lineno))
    result.sort(key=lambda x: x.lineno)
    return result

def pluggable(method):
    """Mark a class method as extendable with plugins."""
    def wrapped(self, *args, **kwargs):
        if hasattr(self, '_plugins'):
            return getattr(self._plugins[-1], method.__name__)(*args, **kwargs)
        else:
            return method(self, *args, **kwargs)
    wrapped.original = method
    return wrapped

def register_plugin(host, plugin):
    """Register a plugin with a host object. Some @pluggable methods in the host
    will have their behaviour altered by the plugin."""
    class OriginalMethods(object):
        def __getattr__(self, name):
            return lambda *args, **kwargs: getattr(host, name).original(host, *args, **kwargs)
    if not hasattr(host, '_plugins'):
        host._plugins = [OriginalMethods()]
    plugin.parent = host._plugins[-1]
    plugin.host = host
    host._plugins.append(plugin)

def redirect_std():
    """Connect stdin/stdout to controlling terminal even if the scripts input and output
    were redirected. This is useful in utilities based on termenu."""
    stdin = sys.stdin
    stdout = sys.stdout
    if not sys.stdin.isatty():
        sys.stdin = open_raw('/dev/tty', 'r', 0)
    if not sys.stdout.isatty():
        sys.stdout = open_raw('/dev/tty', 'w', 0)
    return (stdin, stdout)

def set_logger(name, level='INFO', fmt=None, datefmt=None, propagate=1, remove_handlers=False):
    """This function will clear the previous handlers and set only one handler,
    which will only be StreamHandler for the logger.

    This function is designed to be able to called multiple times in a context.

    Note that if a logger has no handlers, it will be added a handler automatically when it is used."""
    logger = logging.getLogger(name)
    logger.setLevel(getattr(logging, level))
    logger.propagate = propagate
    if remove_handlers:
        logger.handlers = []
        return
    handler = None
    for h in logger.handlers:
        if isinstance(h, logging.StreamHandler):
            handler = h
            break
    if not handler:
        handler = logging.StreamHandler()
        logger.addHandler(handler)
    formatter_kwgs = {}
    for i in ('fmt', 'datefmt'):
        if locals()[i] is not None:
            formatter_kwgs[i] = locals()[i]
    handler.setFormatter(BaseFormatter(**formatter_kwgs))

def convert_jsonld_cdr(doc):
    """converts json ld output of etk to cdr object
    :param doc: the input Knowledge graph in json ld format
    :return: a cdr object with embedded knowledge graph and doc_id.
    # TODO DIG UI needs a @timestamp_crawl(?) add this too"""
    new_docs = list()
    new_doc = dict()
    kg = dict()
    for key in list(doc):
        if key == '@id':
            new_doc['doc_id'] = doc['@id']
        elif key == '@context':
            new_doc[key] = doc[key]
        elif key == '@type':
            kg['type'] = list()
            types = doc['@type']
            if not isinstance(types, list):
                types = [types]
            for type in types:
                kg['type'].append({'value': type, 'key': create_key_from_value(type, 'type')})
        else:
            kg[key] = list()
            objs = doc[key]
            if not isinstance(objs, list):
                objs = [objs]
            for obj in objs:
                if '@id' in obj and '@context' in obj:
                    new_docs.extend(convert_jsonld_cdr(obj))
                if '@id' in obj:
                    kg[key].append({'value': obj['@id'], 'key': obj['@id']})
                elif '@value' in obj:
                    val = obj['@value']
                    k_val = create_key_from_value(val, key)
                    kg[key].append({'value': val, 'key': k_val})
    new_doc['knowledge_graph'] = kg
    new_docs.append(new_doc)
    return new_docs

