def reduceUselessAssignments(root: LNode):
    """Remove assignments if it is only a direct connection and can be replaced with direct link"""
    for n in root.children:
        if n.children:
            reduceUselessAssignments(n)
    do_update = False
    for n in root.children:
        if isinstance(n.originObj, Assignment) and (not n.originObj.indexes) and (len(n.west) == 1):
            src = n.originObj.src
            if isinstance(src, RtlSignalBase) and src.hidden:
                continue
            if not do_update:
                nodes = set(root.children)
                do_update = True
            nodes.remove(n)
            srcPorts = []
            dstPorts = []
            edgesToRemove = []
            inP = getSinglePort(n.west)
            outP = getSinglePort(n.east)
            for e in inP.incomingEdges:
                sPort = e.src
                srcPorts.append((sPort, e.originObj))
                edgesToRemove.append(e)
            for e in outP.outgoingEdges:
                dPort = e.dst
                dstPorts.append(dPort)
                edgesToRemove.append(e)
            for e in edgesToRemove:
                e.remove()
            for srcPort, originObj in srcPorts:
                for dstPort in dstPorts:
                    root.addEdge(srcPort, dstPort, originObj=originObj)
    if do_update:
        root.children = list(nodes)

def _ImageDimensions(images, dynamic_shape=False):
    """Returns the dimensions of an image tensor.
    Args:
      images: 4-D Tensor of shape [batch, height, width, channels]
      dynamic_shape: Whether the input image has undertermined shape. If set to
        `True`, shape information will be retrieved at run time. Default to
        `False`.

    Returns:
      list of integers [batch, height, width, channels]"""
    if dynamic_shape:
        return array_ops.unpack(array_ops.shape(images))
    else:
        return images.get_shape().as_list()

def _Check3DImage(image, require_static=True):
    """Assert that we are working with properly shaped image.
    Args:
      image: 3-D Tensor of shape [height, width, channels]
      require_static: If `True`, requires that all dimensions of `image` are
        known and non-zero.

    Raises:
      ValueError: if image.shape is not a [3] vector."""
    try:
        image_shape = image.get_shape().with_rank(3)
    except ValueError:
        raise ValueError("'image' must be three-dimensional.")
    if require_static and (not image_shape.is_fully_defined()):
        raise ValueError("'image' must be fully defined.")
    if any((x == 0 for x in image_shape)):
        raise ValueError("all dims of 'image.shape' must be > 0: %s" % image_shape)

def flattenPort(port: LPort):
    """Flatten hierarchical ports"""
    yield port
    if port.children:
        for ch in port.children:
            yield from flattenPort(ch)
        port.children.clear()

def _flattenPortsSide(side: List[LNode]) -> List[LNode]:
    """Flatten hierarchical ports on node side"""
    new_side = []
    for i in side:
        for new_p in flattenPort(i):
            new_side.append(new_p)
    return new_side

