def _nargs(f) -> Optional[int]:
    """number of positional arguments values. Dynamically computed from the arguments attribute."""
    if isinstance(f, Function):
        return f.nargs
    spec = inspect.getfullargspec(f)
    if spec.varargs is not None:
        return None
    return len(spec.args)

def _ndefs(f):
    """number of any default values for positional or keyword parameters"""
    if isinstance(f, Function):
        return f.ndefs
    spec = inspect.getfullargspec(f)
    if spec.defaults is None:
        return 0
    return len(spec.defaults)

def multidispatch(*, nargs=None, nouts=None):
    """multidispatch decorate of both functools.singledispatch and func"""
    def wrapper(f):
        return wraps(f)(MultiDispatchFunction(f, nargs=nargs, nouts=nouts))
    return wrapper

def flip(f: Callable) -> Function:
    """flip order of first two arguments to function."""
    nargs_, nouts_, ndefs_ = (nargs(f), nouts(f), ndefs(f))
    return WrappedFunction(lambda *args, **kwargs: f(args[1], args[0], *args[2:], **kwargs), nargs=nargs_, nouts=nouts_, ndefs=ndefs_)

def tagfunc(nargs=None, ndefs=None, nouts=None):
    """decorate of tagged function"""
    def wrapper(f):
        return wraps(f)(FunctionWithTag(f, nargs=nargs, nouts=nouts, ndefs=ndefs))
    return wrapper

def _(f, x):
    """fmap for dict like, not `f` should have signature `f::key->value->(key, value)`"""
    result = {}
    for k, v in x.items():
        k_, v_ = f(k, v)
        result[k_] = v_
    return result

def pass_key(f):
    """helper function for fmap of dict to concern only on values.
    `pass_key(f)` would return a function which shadow input `key` and combine it
    with return of `f(value)` to `(key, f(value))`."""
    @func(nargs=1, nouts=1)
    def wrapper(k, v):
        return (k, f(v))
    return wrapper

def filter_(f, x):
    """function version of filter, when `x` is a Functor of Monoid, it will call:
    `reduce(lambda e: e.extend, x.fmap(f))`"""
    return reduce(lambda e, v: e.extend(v), x.fmap(f))

def _(f, x):
    """filter for dict, note `f` should have signature: `f::key->value->bool`"""
    return {k: v for k, v in x.items() if f(k, v)}

def get_ranks(values):
    """Converts raw values into ranks for rank correlation coefficients
    :param values: list of values (int/float)
    :return: a dict mapping value -> rank"""
    ranks = {}
    sorted_values = sorted(values)
    for i in range(len(sorted_values)):
        value = sorted_values[i]
        if value not in ranks:
            ranks[value] = i + 1
    return ranks

def gamma(ranks_list1, ranks_list2):
    """Goodman and Kruskal's gamma correlation coefficient
    :param ranks_list1: a list of ranks (integers)
    :param ranks_list2: a second list of ranks (integers) of equal length with corresponding entries
    :return: Gamma correlation coefficient (rank correlation ignoring ties)"""
    num_concordant_pairs = 0
    num_discordant_pairs = 0
    num_tied_x = 0
    num_tied_y = 0
    num_tied_xy = 0
    num_items = len(ranks_list1)
    for i in range(num_items):
        rank_1 = ranks_list1[i]
        rank_2 = ranks_list2[i]
        for j in range(i + 1, num_items):
            diff1 = ranks_list1[j] - rank_1
            diff2 = ranks_list2[j] - rank_2
            if diff1 > 0 and diff2 > 0 or (diff1 < 0 and diff2 < 0):
                num_concordant_pairs += 1
            elif diff1 > 0 and diff2 < 0 or (diff1 < 0 and diff2 > 0):
                num_discordant_pairs += 1
            elif diff1 == 0 and diff2 == 0:
                num_tied_xy += 1
            elif diff1 == 0:
                num_tied_x += 1
            elif diff2 == 0:
                num_tied_y += 1
    try:
        gamma_corr_coeff = float(num_concordant_pairs - num_discordant_pairs) / float(num_concordant_pairs + num_discordant_pairs)
    except:
        gamma_corr_coeff = 'n/a'
    return [num_tied_x, num_tied_y, num_tied_xy, gamma_corr_coeff]

def copytree(src, dst, symlinks=False, ignore=None):
    """Function recursively copies from directory to directory.

    Args
    ----
    src (string): the full path of source directory
    dst (string): the full path of destination directory
    symlinks (boolean): the switch for tracking symlinks
    ignore (list): the ignore list"""
    if not os.path.exists(dst):
        os.mkdir(dst)
    try:
        for item in os.listdir(src):
            s = os.path.join(src, item)
            d = os.path.join(dst, item)
            if os.path.isdir(s):
                shutil.copytree(s, d, symlinks, ignore)
            else:
                shutil.copy2(s, d)
    except Exception as e:
        raise FolderExistsError('Folder already exists in %s' % dst)

