def _build_response(data, renderer=None):
    """Build a response using the renderer from the data
    :return:"""
    if isinstance(data, Response) or isinstance(data, BaseResponse):
        return data
    if not renderer:
        raise AttributeError(' Renderer is required')
    if isinstance(data, dict) or data is None:
        data = {} if data is None else data
        for _ in __view_parsers:
            data = _(data)
        return (renderer(data), 200)
    elif isinstance(data, tuple):
        data, status, headers = _normalize_response_tuple(data)
        for _ in __view_parsers:
            data = _(data)
        return (renderer(data or {}), status, headers)
    return data

def json(func):
    """Decorator to render as JSON
    :param func:
    :return:"""
    if inspect.isclass(func):
        apply_function_to_members(func, json)
        return func
    else:
        @functools.wraps(func)
        def decorated_view(*args, **kwargs):
            data = func(*args, **kwargs)
            return _build_response(data, jsonify)
        return decorated_view

def xml(func):
    """Decorator to render as XML
    :param func:
    :return:"""
    if inspect.isclass(func):
        apply_function_to_members(func, xml)
        return func
    else:
        @functools.wraps(func)
        def decorated_view(*args, **kwargs):
            data = func(*args, **kwargs)
            return _build_response(data, dicttoxml)
        return decorated_view

def jsonp(func):
    """Wraps JSONified output for JSONP requests.
    http://flask.pocoo.org/snippets/79/"""
    @functools.wraps(func)
    def decorated_view(*args, **kwargs):
        callback = request.args.get('callback', None)
        if callback:
            data = str(func(*args, **kwargs))
            content = str(callback) + '(' + data + ')'
            mimetype = 'application/javascript'
            return current_app.response_class(content, mimetype=mimetype)
        else:
            return func(*args, **kwargs)
    return decorated_view

def cors(*args, **kwargs):
    """A wrapper around flask-cors cross_origin, to also act on classes

    **An extra note about cors, a response must be available before the
    cors is applied. Dynamic return is applied after the fact, so use the
    decorators, json, xml, or return self.render() for txt/html
    ie:
    @cors()
    class Index(Mocha):
        def index(self):
            return self.render()

        @json
        def json(self):
            return {}

    class Index2(Mocha):
        def index(self):
            return self.render()

        @cors()
        @json
        def json(self):
            return {}


    :return:"""
    def decorator(fn):
        cors_fn = flask_cors.cross_origin(*args, automatic_options=False, **kwargs)
        if inspect.isclass(fn):
            apply_function_to_members(fn, cors_fn)
        else:
            return cors_fn(fn)
        return fn
    return decorator

def headers(params={}):
    """This decorator adds the headers passed in to the response
    http://flask.pocoo.org/snippets/100/"""
    def decorator(f):
        if inspect.isclass(f):
            h = headers(params)
            apply_function_to_members(f, h)
            return f
        @functools.wraps(f)
        def decorated_function(*args, **kwargs):
            resp = make_response(f(*args, **kwargs))
            h = resp.headers
            for header, value in params.items():
                h[header] = value
            return resp
        return decorated_function
    return decorator

def is_valid_fragment(original_residue_id, mapping, frag_sizes):
    """A function which determines whether a residue ID (original_residue_id) should be included in the nmer files generated by the mapping."""
    for r in mapping['segment_list']:
        r = sorted(r)
        if r[0] - frag_sizes + 1 <= original_residue_id <= r[1] + frag_sizes - 1:
            return True
    return False

def get_mapping_from_db3_file(db_path):
    """Does the work of reading the Rosetta SQLite3 .db3 file to retrieve the mapping"""
    import sqlite3
    conn = sqlite3.connect(db_path)
    results = conn.cursor().execute('\n    SELECT chain_id, pdb_residue_number, insertion_code, residues.struct_id, residues.resNum, residues.name3, residues.res_type\n    FROM residue_pdb_identification\n    INNER JOIN residues ON residue_pdb_identification.struct_id=residues.struct_id AND residue_pdb_identification.residue_number=residues.resNum\n    ')
    rosetta_residue_ids = []
    mapping = {}
    for r in results:
        mapping['%s%s%s' % (r[0], str(r[1]).rjust(4), r[2])] = {'pose_residue_id': r[4], 'name3': r[5], 'res_type': r[6]}
        rosetta_residue_ids.append(r[4])
    raw_residue_list = [r for r in conn.cursor().execute('SELECT resNum, name3 FROM residues ORDER BY resNum')]
    assert sorted([r[0] for r in raw_residue_list]) == sorted(rosetta_residue_ids)
    return mapping

def strip_pdb(pdb_path, chains=[], strip_hetatms=False):
    """Takes a PDB file and strips all lines except ATOM and HETATM records. If chains is specified, only those chains are kept. If strip_hetatms is True then HETATM lines are also stripped.
    Returns (True, a path to the stripped PDB file) on success and (False, a list of errors) on failure."""
    chains = set(chains)
    contents = open(pdb_path).read().split('\n')
    if strip_hetatms:
        if chains:
            atom_lines = [l for l in contents if l.startswith('ATOM  ') and l[21] in chains]
        else:
            atom_lines = [l for l in contents if l.startswith('ATOM  ')]
    elif chains:
        atom_lines = [l for l in contents if (l.startswith('ATOM  ') or l.startswith('HETATM')) and l[21] in chains]
    else:
        atom_lines = [l for l in contents if l.startswith('ATOM  ') or l.startswith('HETATM')]
    existing_chains = set([l[21] for l in atom_lines])
    if chains.difference(existing_chains):
        return (False, ['Error: The following chains do not exist in the PDB file - %s' % ', '.join(list(chains.difference(existing_chains)))])
    F, temp_pdb_path = tempfile.mkstemp(dir='.')
    temp_pdb_handle = os.fdopen(F, 'w')
    temp_pdb_handle.write('\n'.join(atom_lines))
    temp_pdb_handle.close()
    return (True, temp_pdb_path)

def get_stripped_pdb_to_pose_residue_map(input_pdb_path, rosetta_scripts_path, rosetta_database_path, chains=[], strip_hetatms=False):
    """Takes a path to an input PDB file, the path to the RosettaScripts executable and Rosetta database, an optional list of chains to strip the PDB down to, and an optional flag specifying whether HETATM lines should be stripped from the PDB.
    On success, a pair (True, mapping between PDB and pose residues) is returned. On failure, a pair (False, a list of errors) is returned."""
    success, result = strip_pdb(input_pdb_path, chains=chains, strip_hetatms=strip_hetatms)
    if success:
        assert os.path.exists(result)
        success, mapping = get_pdb_to_pose_residue_map(result, rosetta_scripts_path, rosetta_database_path)
        os.remove(result)
        if success:
            return (True, mapping)
        else:
            return (False, mapping)
    return (False, result)

