def parse_device(lines):
    """Parse all the lines of a device block.

    A device block is composed of a header line with the name of the device and
    at least one extra line describing the device and its status.  The extra
    lines have a varying format depending on the status and personality of the
    device (e.g. RAID1 vs RAID5, healthy vs recovery/resync)."""
    name, status_line, device = parse_device_header(lines.pop(0))
    if not status_line:
        status_line = lines.pop(0)
    status = parse_device_status(status_line, device['personality'])
    bitmap = None
    resync = None
    for line in lines:
        if line.startswith('      bitmap:'):
            bitmap = parse_device_bitmap(line)
        elif line.startswith('      ['):
            resync = parse_device_resync_progress(line)
        elif line.startswith('      \tresync='):
            resync = parse_device_resync_standby(line)
        else:
            raise NotImplementedError('unknown device line: {0}'.format(line))
    device.update({'status': status, 'bitmap': bitmap, 'resync': resync})
    return (name, device)

def match_etag(etag, header, weak=False):
    """Try to match an ETag against a header value.

    If `weak` is True, uses the weak comparison function."""
    if etag is None:
        return False
    m = etag_re.match(etag)
    if not m:
        raise ValueError("Not a well-formed ETag: '%s'" % etag)
    is_weak, etag = m.groups()
    parsed_header = parse_etag_header(header)
    if parsed_header == '*':
        return True
    if is_weak and (not weak):
        return False
    if weak:
        return etag in [t[1] for t in parsed_header]
    else:
        return etag in [t[1] for t in parsed_header if not t[0]]

def datetime_to_httpdate(dt):
    """Convert datetime.datetime or Unix timestamp to HTTP date."""
    if isinstance(dt, (int, float)):
        return format_date_time(dt)
    elif isinstance(dt, datetime):
        return format_date_time(datetime_to_timestamp(dt))
    else:
        raise TypeError("expected datetime.datetime or timestamp (int/float), got '%s'" % dt)

def timedelta_to_httpdate(td):
    """Convert datetime.timedelta or number of seconds to HTTP date.

    Returns an HTTP date in the future."""
    if isinstance(td, (int, float)):
        return format_date_time(time.time() + td)
    elif isinstance(td, timedelta):
        return format_date_time(time.time() + total_seconds(td))
    else:
        raise TypeError("expected datetime.timedelta or number of seconds(int/float), got '%s'" % td)

def cache_control(max_age=None, private=False, public=False, s_maxage=None, must_revalidate=False, proxy_revalidate=False, no_cache=False, no_store=False):
    """Generate the value for a Cache-Control header.

    Example:

        >>> from rhino.http import cache_control as cc
        >>> from datetime import timedelta
        >>> cc(public=1, max_age=3600)
        'public, max-age=3600'
        >>> cc(public=1, max_age=timedelta(hours=1))
        'public, max-age=3600'
        >>> cc(private=True, no_cache=True, no_store=True)
        'private, no-cache, no-store'"""
    if all([private, public]):
        raise ValueError("'private' and 'public' are mutually exclusive")
    if isinstance(max_age, timedelta):
        max_age = int(total_seconds(max_age))
    if isinstance(s_maxage, timedelta):
        s_maxage = int(total_seconds(s_maxage))
    directives = []
    if public:
        directives.append('public')
    if private:
        directives.append('private')
    if max_age is not None:
        directives.append('max-age=%d' % max_age)
    if s_maxage is not None:
        directives.append('s-maxage=%d' % s_maxage)
    if no_cache:
        directives.append('no-cache')
    if no_store:
        directives.append('no-store')
    if must_revalidate:
        directives.append('must-revalidate')
    if proxy_revalidate:
        directives.append('proxy-revalidate')
    return ', '.join(directives)

