def negotiate_accept(accept, handlers):
    """Filter handlers that provide an acceptable mime-type.

    Finds the best match among handlers given an Accept header, and returns
    those handlers that provide the matching mime-type."""
    provided = [h.provides for h in handlers]
    if None in provided:
        return [h for h in handlers if h.provides is None]
    else:
        best_match = mimeparse.best_match(reversed(provided), accept)
        return [h for h in handlers if h.provides == best_match]

def synchronized(lock):
    """Synchronization decorator; provide thread-safe locking on a function
    http://code.activestate.com/recipes/465057/"""
    def wrap(f):
        def synchronize(*args, **kw):
            lock.acquire()
            try:
                return f(*args, **kw)
            finally:
                lock.release()
        return synchronize
    return wrap

def call_repeatedly(func, interval, *args, **kwargs):
    """Call a function at interval
    Returns both the thread object and the loop stopper Event."""
    main_thead = threading.current_thread()
    stopped = threading.Event()
    def loop():
        while not stopped.wait(interval) and main_thead.is_alive():
            func(*args, **kwargs)
        return
    timer_thread = threading.Thread(target=loop, daemon=True)
    timer_thread.start()
    atexit.register(stopped.set)
    return (timer_thread, stopped.set)

def synchronized_limit(lock):
    """Synchronization decorator; provide thread-safe locking on a function
    http://code.activestate.com/recipes/465057/"""
    def wrap(f):
        def synchronize(*args, **kw):
            if lock[1] < 10:
                lock[1] += 1
                lock[0].acquire()
                try:
                    return f(*args, **kw)
                finally:
                    lock[1] -= 1
                    lock[0].release()
            else:
                raise Exception('Too busy')
        return synchronize
    return wrap

def daemonize(umask=0, work_dir='/', max_fd=1024, redirect='/dev/null'):
    """When this function is called, the process is daemonized (by forking + killing its parent).
    It becomes a background task.
    It is useful to release the console."""
    if not redirect:
        redirect = '/dev/null'
    if hasattr(os, 'devnull'):
        redirect = os.devnull
    try:
        pid = os.fork()
    except OSError as e:
        raise Exception('%s [%d]' % (e.strerror, e.errno))
    if pid == 0:
        os.setsid()
        try:
            pid = os.fork()
        except OSError as e:
            raise Exception('%s [%d]' % (e.strerror, e.errno))
        if pid == 0:
            os.chdir(work_dir)
            os.umask(umask)
        else:
            os._exit(0)
    else:
        os._exit(0)
    import resource
    maxfd = resource.getrlimit(resource.RLIMIT_NOFILE)[1]
    if maxfd == resource.RLIM_INFINITY:
        maxfd = max_fd
    for fd in range(0, maxfd):
        try:
            os.close(fd)
        except OSError:
            pass
    os.open(redirect, os.O_RDWR)
    os.dup2(0, 1)
    os.dup2(0, 2)
    return os.getpid()

def ensure_session(engine_or_session):
    """If it is an engine, then create a session from it. And indicate that
    this session should be closed after the job done.

    :type engine_or_session: Union[Engine, Session]
    :rtype: Tuple[Session, bool]"""
    if isinstance(engine_or_session, Engine):
        engine_id = id(engine_or_session)
        if id(engine_id) in session_klass_cache:
            SessionClass = session_klass_cache[engine_id]
        else:
            SessionClass = sessionmaker(bind=engine_or_session)
        ses = SessionClass()
        auto_close = True
        return (ses, auto_close)
    elif isinstance(engine_or_session, Session):
        ses = engine_or_session
        auto_close = False
        return (ses, auto_close)

def project(v, n):
    """Project Vector v onto plane with normal vector n."""
    return v - matmul(v, n) * n / norm(n) ** 2.0

