def get_obsolete_acc_to_uniparc(acc):
    """Tries to determine the UniParc ID for obsolete ACCs which are not returned using uniprot_map.

    :param acc: The UniProt accession number.
    :return: The corresponding UniParc ID.

    Warning: This is a fragile function as the underlying website generation or URL could change."""
    contents = http_get('www.uniprot.org/uniparc/?query={0}'.format(acc))
    mtchs = re.findall('"UPI[A-Z0-9]+?"', contents, re.DOTALL)
    uniparc_id = set([m[1:-1] for m in mtchs])
    if len(uniparc_id) == 1:
        return uniparc_id.pop()
    elif len(uniparc_id) > 1:
        raise Exception('Multiple UPI identifiers found.')
    return None

def get_common_PDB_IDs(pdb_id, cache_dir=None, exception_on_failure=True):
    """This function takes a PDB ID, maps it to UniProt ACCs, then returns the common set of PDB IDs related to those ACCs.
    The purpose is to find any PDB files related to pdb_id, particularly for complexes, such that the other PDB files
    contain identical sequences or mutant complexes."""
    m = pdb_to_uniparc([pdb_id], cache_dir=cache_dir)
    UniProtACs = []
    if pdb_id in m:
        for entry in m[pdb_id]:
            if entry.UniProtACs:
                UniProtACs.extend(entry.UniProtACs)
            elif exception_on_failure:
                raise Exception('No UniProtAC for one entry.Lookup failed.')
    elif exception_on_failure:
        raise Exception('Lookup failed.')
    if not UniProtACs:
        if exception_on_failure:
            raise Exception('Lookup failed.')
        else:
            return None
    common_set = set(uniprot_map('ACC', 'PDB_ID', [UniProtACs[0]], cache_dir=cache_dir).get(UniProtACs[0], []))
    for acc in UniProtACs[1:]:
        common_set = common_set.intersection(set(uniprot_map('ACC', 'PDB_ID', [acc], cache_dir=cache_dir).get(acc, [])))
    return sorted(common_set)

def cool_paginate(context, **kwargs) -> dict:
    """Main function for pagination process."""
    names = ('size', 'next_name', 'previous_name', 'elastic', 'page_obj')
    return_dict = {name: value for name, value in zip(names, map(kwargs.get, names))}
    if context.get('request'):
        return_dict['request'] = context['request']
    else:
        raise RequestNotExists('Unable to find request in your template context,please make sure that you have the request context processor enabled')
    if not return_dict.get('page_obj'):
        if context.get('page_obj'):
            return_dict['page_obj'] = context['page_obj']
        else:
            raise PageNotSpecified("You customized paginator standard name, but haven't specified it in {% cool_paginate %} tag.")
    if not return_dict.get('elastic'):
        return_dict['elastic'] = getattr(settings, 'COOL_PAGINATOR_ELASTIC', 10)
    return return_dict

def from_everything(everything, engine_or_session, limit=None, **kwargs):
    """Construct a Prettytable from any kinds of sqlalchemy query.

    :type engine_or_session: Union[Engine, Session]

    :rtype: PrettyTable

    Usage::

        from sqlalchemy import select

        sql = select([t_user])
        print(from_everything(sql, engine))

        query = session.query(User)
        print(from_everything(query, session))

        session.query(User)"""
    if isinstance(everything, TextClause):
        return from_stmt(everything, engine_or_session, **kwargs)
    if isinstance(everything, Table):
        return from_table(everything, engine_or_session, limit=limit, **kwargs)
    if type(everything) is DeclarativeMeta:
        return from_object(everything, engine_or_session, limit=limit, **kwargs)
    if isinstance(everything, Query):
        return from_query(everything, engine_or_session, limit=limit, **kwargs)
    if isinstance(everything, Select):
        return from_sql(everything, engine_or_session, limit=limit, **kwargs)
    if isinstance(everything, ResultProxy):
        return from_resultproxy(everything, **kwargs)
    if isinstance(everything, list):
        return from_data(everything, **kwargs)

