def sm_dict2lha(d):
    """Convert a a dictionary of SM parameters into
    a dictionary that pylha can convert into a DSixTools SM output file."""
    blocks = OrderedDict([('GAUGE', {'values': [[1, d['g'].real], [2, d['gp'].real], [3, d['gs'].real]]}), ('SCALAR', {'values': [[1, d['Lambda'].real], [2, d['m2'].real]]}), ('GU', {'values': matrix2lha(d['Gu'].real)}), ('IMGU', {'values': matrix2lha(d['Gu'].imag)}), ('GD', {'values': matrix2lha(d['Gd'].real)}), ('IMGD', {'values': matrix2lha(d['Gd'].imag)}), ('GE', {'values': matrix2lha(d['Ge'].real)}), ('IMGE', {'values': matrix2lha(d['Ge'].imag)}), ('THETA', {'values': [[1, d['Theta'].real], [2, d['Thetap'].real], [3, d['Thetas'].real]]})])
    return {'BLOCK': blocks}

def wc_lha2dict(lha):
    """Convert a dictionary returned by pylha from a DSixTools WC input file
    into a dictionary of Wilson coefficients."""
    C = OrderedDict()
    for k, (block, i) in WC_dict_0f.items():
        try:
            C[k] = dict(lha['BLOCK'][block]['values'])[i]
        except KeyError:
            C[k] = 0
    for k in definitions.WC_keys_2f:
        try:
            C[k] = lha2matrix(lha['BLOCK']['WC' + k.upper()]['values'], (3, 3)).real
        except KeyError:
            C[k] = np.zeros((3, 3))
        try:
            C[k] = C[k] + 1j * lha2matrix(lha['BLOCK']['IMWC' + k.upper()]['values'], (3, 3))
        except KeyError:
            pass
    for k in definitions.WC_keys_4f:
        try:
            C[k] = lha2matrix(lha['BLOCK']['WC' + k.upper()]['values'], (3, 3, 3, 3))
        except KeyError:
            C[k] = np.zeros((3, 3, 3, 3))
        try:
            C[k] = C[k] + 1j * lha2matrix(lha['BLOCK']['IMWC' + k.upper()]['values'], (3, 3, 3, 3))
        except KeyError:
            pass
    return C

def compute_rmsd_by_matrix(dataframe_1, dataframe_2, use_assertion=False):
    """Computes the RMSD of two pandas dataframes. The dataframes are expected to be of equal dimensions and use_assertion
    can be set to assert that the row indices match."""
    if use_assertion:
        assert [i for i in dataframe_1.index] == [i for i in dataframe_2.index]
    num_points = dataframe_1.shape[0]
    return numpy.linalg.norm(dataframe_1 - dataframe_2) / numpy.sqrt(num_points)

def parse_stream(response):
    """take stream from docker-py lib and display it to the user.

    this also builds a stream list and returns it."""
    stream_data = []
    stream = stdout
    for data in response:
        if data:
            try:
                data = data.decode('utf-8')
            except AttributeError as e:
                logger.exception('Unable to parse stream, Attribute Error Raised: {0}'.format(e))
                stream.write(data)
                continue
            try:
                normalized_data = normalize_keys(json.loads(data))
            except ValueError:
                stream.write(data)
                continue
            except TypeError:
                stream.write(data)
                continue
            if 'progress' in normalized_data:
                stream_data.append(normalized_data)
                _display_progress(normalized_data, stream)
            elif 'error' in normalized_data:
                _display_error(normalized_data, stream)
            elif 'status' in normalized_data:
                stream_data.append(normalized_data)
                _display_status(normalized_data, stream)
            elif 'stream' in normalized_data:
                stream_data.append(normalized_data)
                _display_stream(normalized_data, stream)
            else:
                stream.write(data)
    stream.flush()
    return stream_data

def normalize_keys(suspect, snake_case=True):
    """take a dict and turn all of its type string keys into snake_case"""
    if not isinstance(suspect, dict):
        raise TypeError('you must pass a dict.')
    for key in list(suspect):
        if not isinstance(key, six.string_types):
            continue
        if snake_case:
            s1 = first_cap_re.sub('\\1_\\2', key)
            new_key = all_cap_re.sub('\\1_\\2', s1).lower()
        else:
            new_key = key.lower()
        value = suspect.pop(key)
        if isinstance(value, dict):
            suspect[new_key] = normalize_keys(value, snake_case)
        elif isinstance(value, list):
            for i in range(0, len(value)):
                if isinstance(value[i], dict):
                    normalize_keys(value[i], snake_case)
            suspect[new_key] = value
        else:
            suspect[new_key] = value
    return suspect

def normalize_value(value, snake_case=True):
    """:param value:
    :return value:"""
    if not isinstance(value, six.string_types):
        raise TypeError('the value passed to value must be a string')
    if snake_case:
        s1 = first_cap_re.sub('\\1_\\2', value)
        new_value = all_cap_re.sub('\\1_\\2', s1).lower()
    else:
        new_value = value.lower()
    return new_value

def capitalize_keys(suspect):
    """:param suspect:
    :return new dict with capitalized keys:"""
    if not isinstance(suspect, dict):
        raise TypeError('you must pass a dict.')
    converted = {}
    for key in list(suspect):
        if not isinstance(key, six.string_types):
            continue
        if key[0].isupper():
            continue
        if '_' in key:
            new_key = ''.join([chunk.capitalize() for index, chunk in enumerate(key.split('_'))])
        else:
            new_key = key.capitalize()
        value = suspect.get(key)
        if type(value) is dict:
            converted[new_key] = capitalize_keys(value)
        elif type(value) is list:
            converted[new_key] = [capitalize_keys(x) if isinstance(x, dict) else x for x in value]
        else:
            converted[new_key] = value
    return converted

def _display_progress(data, stream):
    """expecting the following data scheme:
        {
            u'status': u'Pushing',
            u'progressDetail': {
                                    u'current': 655337,
                                    u'start': 1413994898,
                                    u'total': 20412416
                                },
            u'id': u'51783549ce98',
            u'progress': u'[=>                                                 ] 655.3 kB/20.41 MB 30s'
        }

        {
            u'status': u'Buffering to disk',
            u'progressDetail': {
                                    u'current': 13369344,
                                    u'start': 1413994898
                               },
            u'id': u'51783549ce98',
            u'progress': u'13.37 MB'
        }"""
    if type(data) is not dict:
        raise TypeError('data should be of type dict. the following was passed: {0}'.format(data))
    stream.write('\r%s %s' % (data['status'], data['progress']))
    if 'Pushing' in data['status']:
        if data['progress_detail']['current'] == data['progress_detail'].get('total'):
            stream.write('\n')
    stream.flush()

def _display_error(normalized_data, stream):
