def slugify(text, delim='-'):
    """Generates an slightly worse ASCII-only slug."""
    punctuation_re = re.compile('[\\t !"#$%&\\\'()*\\-/<=>?@\\[\\\\\\]^_`{|},.:]+')
    result = []
    for word in punctuation_re.split(text.lower()):
        word = normalize_text(word)
        if word:
            result.append(word)
    return delim.join(result)

def javascript_escape(s, quote_double_quotes=True):
    """Escape characters for javascript strings."""
    ustring_re = re.compile(u'([\x80-\uffff])')
    def fix(match):
        return '\\u%04x' % ord(match.group(1))
    if type(s) == str:
        s = s.decode('utf-8')
    elif type(s) != six.text_type:
        raise TypeError(s)
    s = s.replace('\\', '\\\\')
    s = s.replace('\r', '\\r')
    s = s.replace('\n', '\\n')
    s = s.replace('\t', '\\t')
    s = s.replace("'", "\\'")
    if quote_double_quotes:
        s = s.replace('"', '&quot;')
    return str(ustring_re.sub(fix, s))

def seconds_to_hms_verbose(t):
    """Converts seconds float to 'H hours 8 minutes, 30 seconds' format"""
    hours = int(t / 3600)
    mins = int(t / 60 % 60)
    secs = int(t % 60)
    return ' '.join([hours + ' hour' + ('s' if hours > 1 else '') if hours > 0 else '', mins + ' minute' + ('s' if mins > 1 else '') if mins > 0 else '', secs + ' second' + ('s' if secs > 1 else '') if secs > 0 else ''])

def seconds_to_hms(seconds):
    """Converts seconds float to 'hh:mm:ss.ssssss' format."""
    hours = int(seconds / 3600.0)
    minutes = int(seconds / 60.0 % 60.0)
    secs = float(seconds % 60.0)
    return '{0:02d}:{1:02d}:{2:02.6f}'.format(hours, minutes, secs)

