            continue
        model.add(s, p, o, a)
    return

def vMh2_to_m2Lambda(v, Mh2, C, scale_high):
    """Function to numerically determine the parameters of the Higgs potential
    given the physical Higgs VEV and mass."""
    if C['phi'] == 0 and C['phiBox'] == 0 and (C['phiD'] == 0):
        return _vMh2_to_m2Lambda_SM(v, Mh2)
    else:
        def f0(x):
            m2, Lambda = x
            d = m2Lambda_to_vMh2(m2=m2.real, Lambda=Lambda.real, C=C, scale_high=scale_high)
            return np.array([d['v'] - v, d['Mh2'] - Mh2])
        dSM = _vMh2_to_m2Lambda_SM(v, Mh2)
        x0 = np.array([dSM['m2'], dSM['Lambda']])
        try:
            xres = scipy.optimize.newton_krylov(f0, x0)
        except scipy.optimize.nonlin.NoConvergence:
            raise ValueError('No solution for m^2 and Lambda found')
        return {'m2': xres[0], 'Lambda': xres[1]}

def get_gpbar(ebar, gbar, v, C, scale_high):
    """Function to numerically determine the hypercharge gauge coupling
    in terms of $\\bar e$, $\\bar g$, v, and the Wilson coefficients."""
    if C['phiWB'] == 0:
        gpbar = ebar * gbar / sqrt(gbar ** 2 - ebar ** 2)
    else:
        def f0(x):
            gpb = x
            gb = gbar
            eps = C['phiWB'] * (v ** 2 / scale_high ** 2)
            ebar_calc = gb * gpb / sqrt(gb ** 2 + gpb ** 2) * (1 - eps * gb * gpb / (gb ** 2 + gpb ** 2))
            return (ebar_calc - ebar).real
        gpbar = scipy.optimize.brentq(f0, 0, 3)
    return gpbar * (1 - C['phiB'] * (v ** 2 / scale_high ** 2))

def full_file_list(scan_path):
    """Returns a list of all files in a folder and its subfolders (only files)."""
    file_list = []
    path = os.path.abspath(scan_path)
    for root, dirs, files in os.walk(path):
        if len(files) != 0 and (not '.svn' in root) and (not '.git' in root):
            for f in files:
                file_list.append(os.path.join(root, f))
    return file_list

def list_files(scan_path, contains=None):
    """Returns a list of all files in a folder, without subfolders (only files)."""
    file_list = []
    path = os.path.abspath(scan_path)
    for f in sorted(os.listdir(path)):
        if contains and f.find(contains) < 0:
            continue
        filepath = os.path.join(path, f)
        if os.path.isfile(filepath):
            file_list.append(filepath)
    return file_list

def full_file_list_with_sequence(scan_path):
    """Returns a list of all files in a folder and its subfolders (only files)."""
    file_list = []
    path = os.path.abspath(scan_path)
    for root, dirs, files in os.walk(path):
        if len(files) != 0 and (not '.svn' in root) and (not '.git' in root):
            try:
                sc = sequential.SequentialFolder(str(root))
                if sc.sequence:
                    file_list.append(sc)
                    continue
            except Exception as e:
                pass
            for f in files:
                file_list.append(os.path.join(root, f))
