def saturateHexColor(hexcolor, adjustment=1.0):
    """Takes in an RGB color in 6-character hexadecimal with an optional preceding hash character.
    Returns the RGB color in the same format adjusted by saturation by the second parameter."""
    assert adjustment >= 0 and len(hexcolor) >= 1
    prefix = ''
    if hexcolor[0] == '#':
        hexcolor = hexcolor[1:]
        prefix = '#'
    assert len(hexcolor) == 6
    if adjustment == 1.0:
        return '%s%s' % (prefix, hexcolor)
    else:
        hsvColor = list(colorsys.rgb_to_hsv(int(hexcolor[0:2], 16) / 255.0, int(hexcolor[2:4], 16) / 255.0, int(hexcolor[4:6], 16) / 255.0))
        hsvColor[1] = min(1.0, hsvColor[1] * adjustment)
        rgbColor = [min(255, 255 * v) for v in colorsys.hsv_to_rgb(hsvColor[0], hsvColor[1], hsvColor[2])]
        return '%s%.2x%.2x%.2x' % (prefix, rgbColor[0], rgbColor[1], rgbColor[2])

def search_relative_field(model_class, fields, term):
    """Searches a ReferenceField's fields, returning ID's to be used in __in

    There is no JOIN, so no Assignment.objects.filter(course__title='My Course'). To
    get around this, we return a list of ID's.

    Since this is an internal tool, we allow multiple fields to AND/OR group."""
    offset = 0
    limit = 500
    query = model_class.objects
    criteria = None
    if re.match(RE_OBJECTID, term):
        q = query.filter(id=bson.ObjectId(term)).only('id')
        if q.count() == 1:
            return q
    for field in fields:
        flt = {u'%s__icontains' % field: term}
        if not criteria:
            criteria = mongoengine.Q(**flt)
        else:
            criteria |= mongoengine.Q(**flt)
    query = query.filter(criteria)
    if offset:
        query = query.skip(offset)
    return query.limit(limit).only('id').all()

