def run_r_script(r_script_filename, cwd='.'):
    """This function was adapted from the covariation benchmark."""
    p = subprocess.Popen(['R', 'CMD', 'BATCH', r_script_filename], cwd=cwd)
    while True:
        time.sleep(0.3)
        errcode = p.poll()
        if errcode != None:
            break
    rout = '{0}out'.format(r_script_filename)
    rout_contents = None
    if os.path.exists(rout):
        rout_contents = read_file(rout)
        os.remove(rout)
    rdata_file = os.path.join(os.path.split(r_script_filename)[0], '.RData')
    if os.path.exists(rdata_file):
        os.remove(rdata_file)
    if errcode != 0:
        print(rout_contents)
        raise Exception('The R script failed with error code %d.' % errcode)
    return rout_contents

def sse_event(event=None, data=None, id=None, retry=None, comment=None, encoding='utf-8'):
    """Encode a Server-Sent Event (SSE).

    At least one field must be present. All fields are strings, except retry,
    which must be an integer. The event and id fields can not contain newlines."""
    if all((x is None for x in [event, data, id, retry, comment])):
        raise TypeError('Event must have at least one field')
    if event and any((c in event for c in '\r\n')):
        raise ValueError("'event' can not contain newlines: '%s'" % event)
    if id and any((c in id for c in '\r\n')):
        raise ValueError("'id' can not contain newlines: '%s'" % id)
    return ''.join([_sse_encode('', comment) if comment is not None else '', _sse_encode('id', id) if id is not None else '', _sse_encode('event', event) if event is not None else '', _sse_encode('retry', str(int(retry))) if retry is not None else '', _sse_encode('data', data) if data is not None else '', '\n']).encode(encoding)

def dual_use_decorator(fn):
    """Turn a function into a decorator that can be called with or without
    arguments."""
    @functools.wraps(fn)
    def decorator(*args, **kw):
        if len(args) == 1 and (not kw) and callable(args[0]):
            return fn()(args[0])
        else:
            return fn(*args, **kw)
    return decorator

def get_args(obj):
    """Get a list of argument names for a callable."""
    if inspect.isfunction(obj):
        return inspect.getargspec(obj).args
    elif inspect.ismethod(obj):
        return inspect.getargspec(obj).args[1:]
    elif inspect.isclass(obj):
        return inspect.getargspec(obj.__init__).args[1:]
    elif hasattr(obj, '__call__'):
        return inspect.getargspec(obj.__call__).args[1:]
    else:
        raise TypeError("Can't inspect signature of '%s' object." % obj)

def apply_ctx(fn, ctx):
    """Return fn with ctx partially applied, if requested.

    If the `fn` callable accepts an argument named "ctx", returns a
    functools.partial object with ctx=ctx applied, else returns `fn` unchanged.

    For this to work, the 'ctx' argument must come after any arguments that are
    passed as positional arguments. For example, 'ctx' must be the 2nd argument
    for request handlers, serializers and deserializers, that are always called
    with one positional argument (the request, object to serialize, and input
    filehandle, respectively)."""
    if 'ctx' in get_args(fn):
        return functools.partial(fn, ctx=ctx)
    else:
        return fn

def make_codon_list(protein_seq, template_dna=None, include_stop=True):
    """Return a list of codons that would be translated to the given protein
    sequence.  Codons are picked first to minimize the mutations relative to a
    template DNA sequence and second to prefer "optimal" codons."""
    codon_list = []
    if template_dna is None:
        template_dna = []
    for i, res in enumerate(protein_seq.upper()):
        try:
            template_codon = template_dna[3 * i:3 * i + 3]
        except IndexError:
            template_codon = '---'
        possible_codons = dna.ecoli_reverse_translate[res]
        possible_codons.sort(key=lambda x: dna.num_mutations(x, template_codon))
        codon_list.append(possible_codons[0])
    last_codon = codon_list[-1]
    stop_codons = dna.ecoli_reverse_translate['.']
    if include_stop and last_codon not in stop_codons:
        codon_list.append(stop_codons[0])
    return codon_list

def problem_with_codon(codon_index, codon_list, bad_seqs):
    """Return true if the given codon overlaps with a bad sequence."""
    base_1 = 3 * codon_index
    base_3 = 3 * codon_index + 2
    gene_seq = ''.join(codon_list)
    for bad_seq in bad_seqs:
        problem = bad_seq.search(gene_seq)
        if problem and problem.start() < base_3 and (problem.end() > base_1):
            return True
    return False

def sequences_from_fasta(path):
