def json_url_error_handler(urls=()):
    """Closure: Json URL error handler
    Checks if request matches provided url prefix and returns json response if
    it does. Otherwise falls back to template error handler. This is usefull
    if you want to return json errors for a subset of your routes.

    Register this by calling a closure:
        register_error_handler(app, json_url_handler([
            '/url/path/one/',
            '/some/other/relative/url/',
        ]))

    :param urls: iterable or string, list of url prefixes
    :return:"""
    if type(urls) is str:
        urls = [urls]
    def handler(exception):
        http_exception = isinstance(exception, exceptions.HTTPException)
        code = exception.code if http_exception else 500
        if code == 500:
            current_app.logger.error(exception)
        if has_app_context() and has_request_context():
            for prefix in urls:
                prefix = prefix.strip('/')
                prefix = '/' + prefix + '/' if len(prefix) else '/'
                if request.path.startswith(prefix):
                    return json_error_handler(exception)
        return template_error_handler(exception)
    return handler

def tuple_type_compare(types0, types1):
    """doufo.tuple_type_compare: compare two types
        if `types0` is 'bigger' than `types1`, return negative (<0);
        otherwise, return positive (>0). Here 'bigger' is defined by
        whether they are 'parent and child', or ituitively bigger
    Args:
        types0 (`type`): types0
        types1 (`type`): types1
    Returns:
        return (`int`): comparison results
    Raises:"""
    compares = [single_type_compare(types0[0], types1[0]), single_type_compare(types0[1], types1[1])]
    if compares[0] != 0:
        return compares[0]
    if compares[1] != 0:
        return compares[1]
    if types0[0] is types1[0] and types0[1] is types1[1]:
        return 0
    return hash(types1) - hash(types0)

def fetch(method, uri, params_prefix=None, **params):
    """Fetch the given uri and return the contents of the response."""
    params = _prepare_params(params, params_prefix)
    if method == 'POST' or method == 'PUT':
        r_data = {'data': params}
    else:
        r_data = {'params': params}
    url = 'https://%s/%s.json' % (CHALLONGE_API_URL, uri)
    try:
        response = request(method, url, auth=get_credentials(), **r_data)
        response.raise_for_status()
    except HTTPError:
        if response.status_code != 422:
            response.raise_for_status()
        doc = response.json()
        if doc.get('errors'):
            raise ChallongeException(*doc['errors'])
    return response

def fetch_and_parse(method, uri, params_prefix=None, **params):
    """Fetch the given uri and return python dictionary with parsed data-types."""
    response = fetch(method, uri, params_prefix, **params)
    return _parse(json.loads(response.text))

def _parse(data):
    """Recursively convert a json into python data types"""
    if not data:
        return []
    elif isinstance(data, (tuple, list)):
        return [_parse(subdata) for subdata in data]
    d = {ik: v for k in data.keys() for ik, v in data[k].items()}
    to_parse = dict(d)
    for k, v in to_parse.items():
        if k in {'name', 'display_name', 'display_name_with_invitation_email_address', 'username', 'challonge_username'}:
            continue
        if isinstance(v, TEXT_TYPE):
            try:
                dt = iso8601.parse_date(v)
                d[k] = dt.astimezone(tz)
            except iso8601.ParseError:
                try:
                    d[k] = float(v)
                except ValueError:
                    pass
    return d

def _prepare_params(dirty_params, prefix=None):
    """Prepares parameters to be sent to challonge.com.

    The `prefix` can be used to convert parameters with keys that
    look like ("name", "url", "tournament_type") into something like
    ("tournament[name]", "tournament[url]", "tournament[tournament_type]"),
    which is how challonge.com expects parameters describing specific
    objects."""
    if prefix and prefix.endswith('[]'):
        keys = []
        values = []
        for k, v in dirty_params.items():
            if isinstance(v, (tuple, list)):
                keys.append(k)
                values.append(v)
        firstiter = ((k, v) for vals in zip(*values) for k, v in zip(keys, vals))
        lastiter = ((k, v) for k, v in dirty_params.items() if k not in keys)
        dpiter = itertools.chain(firstiter, lastiter)
    else:
        dpiter = dirty_params.items()
    params = []
    for k, v in dpiter:
        if isinstance(v, (tuple, list)):
            for val in v:
                val = _prepare_value(val)
                if prefix:
                    params.append(('%s[%s][]' % (prefix, k), val))
                else:
                    params.append((k + '[]', val))
        else:
            v = _prepare_value(v)
            if prefix:
                params.append(('%s[%s]' % (prefix, k), v))
            else:
                params.append((k, v))
    return params

