def omap(m):
    """Create a nested mapping from origin to property to values/attributes covering an entire Versa model"""
    om = {}
    for s, p, o, a in m.match():
        om.setdefault(s, {})
        om[s].setdefault(p, []).append((o, a))
    return om

def write(models, csvout, rulelist, write_header, base=None, logger=logging):
    """models - one or more input Versa models from which output is generated."""
    properties = [k for k, v in rulelist]
    numprops = len(properties)
    headers = [v for k, v in rulelist]
    if write_header:
        csvout.writerow(['id', 'type'] + headers)
    rules = {k: v for k, v in rulelist}
    if not isinstance(models, list):
        models = [models]
    for m in models:
        mapped = omap(m)
        for o, props in mapped.items():
            rtypes = list(map(operator.itemgetter(0), props.get(RDF_TYPE_REL, [])))
            if not rtypes:
                continue
            row = [o, fromlist(rtypes)] + [None] * numprops
            for ix, p in enumerate(properties):
                v = list(map(operator.itemgetter(0), props.get(p, [])))
                if v:
                    row[ix + 2] = fromlist(v)
                    csvout.writerow(row)
    return

def dumb_relative_half_prime(n, divisor=None):
    """A dumb brute-force algorithm to find a relative prime for n which is approximately n/2 through n/5.
    It is used for generating spaced colors.
    Written on a Friday evening. Do not judge!"""
    if n < 1 or not isinstance(n, int):
        raise Exception('n must be a positive non-zero integer.')
    elif n < 7:
        return dumb_relative_prime_const[n]
    elif n < 10:
        divisor = 2.0
    if not divisor:
        if n <= 20:
            divisor = 3.0
        elif n <= 30:
            divisor = 4.0
        else:
            divisor = 5.0
    m = int(n / divisor)
    while m > 1:
        if fractions.gcd(n, m) == 1:
            return m
        m -= 1
    if divisor > 2.0:
        return dumb_relative_half_prime(n, divisor - 1.0)

