def wrap_star_digger(item, type_str, data_name='Value'):
    """code used to extract data from Bing's wrap star
    :param item: wrap star obj
    :param type_str: target type string
    :param data_name: target data label, might be "Entities", "Properties", 'Value'
    :return: list of all matched target, arranged in occurance"""
    ret = []
    if type(item) == dict:
        if 'Type' in item and item['Type'] == type_str and (data_name in item):
            if len(item[data_name]) > 1:
                pass
            return item[data_name]
        else:
            for k in item:
                sub_ret = wrap_star_digger(item[k], type_str, data_name)
                if sub_ret:
                    ret.extend(sub_ret)
    elif type(item) == list:
        for i in item:
            sub_ret = wrap_star_digger(i, type_str, data_name)
            if sub_ret:
                ret.extend(sub_ret)
    return ret

def parse_sws_date(date_string):
    """Takes a date from the SWS response object
    and attempts to parse it using one of the several
    datetime formats used by the SWS
    :param date_string:
    :return: date object"""
    if date_string is None:
        return None
    date_formats = ['%m/%d/%Y', '%Y-%m-%d', '%Y%m%d']
    datetime_obj = None
    for fmt in date_formats:
        try:
            datetime_obj = datetime.strptime(date_string, fmt)
        except ValueError:
            continue
        break
    if datetime_obj is None:
        raise ValueError('Unknown SWS date format')
    return datetime_obj

def get_resource(url):
    """Issue a GET request to SWS with the given url
    and return a response in json format.
    :returns: http response with content in json"""
    response = DAO.getURL(url, {'Accept': 'application/json', 'Connection': 'keep-alive'})
    if response.status != 200:
        raise DataFailureException(url, response.status, response.data)
    return json.loads(response.data)

def enable_request_loader():
    """Enable request loader
    Optional user loader based on incomin request object. This is useful to
    enable on top of default user loader if you want to authenticate API
    requests via bearer token header.
    :return:"""
    @login_manager.request_loader
    def load_user_from_request(request):
        user = None
        auth = request.headers.get('Authorization')
        if auth and auth.startswith('Bearer'):
            try:
                token = auth[7:]
                user = user_service.get_user_by_token(token)
            except x.UserException as exception:
                msg = 'JWT token login failed for [{ip}] with message: [{msg}]'
                msg = msg.format(ip=request.environ['REMOTE_ADDR'], msg=str(exception))
                current_app.logger.log(msg=msg, level=logging.INFO)
                abort(401, description=str(exception))
        return user

def ticks_format(value, index):
    """get the value and returns the value as:
       integer: [0,99]
       1 digit float: [0.1, 0.99]
       n*10^m: otherwise
    To have all the number of the same size they are all returned as latex strings

    http://stackoverflow.com/questions/17165435/matplotlib-show-labels-for-minor-ticks-also"""
    exp = np.floor(np.log10(value))
    base = value / 10 ** exp
    if exp == 0 or exp == 1:
        return '${0:d}$'.format(int(value))
    if exp == -1:
        return '${0:.1f}$'.format(value)
    else:
        return '${0:d}\\times10^{{{1:d}}}$'.format(int(base), int(exp))

def set_cors_config(app):
    """Flask-Cors (3.x.x) extension set the config as CORS_*,
     But we'll hold the config in CORS key.
     This function will convert them to CORS_* values
    :param app:
    :return:"""
    if 'CORS' in app.config:
        for k, v in app.config['CORS'].items():
            _ = 'CORS_' + k.upper()
            if _ not in app.config:
                app.config[_] = v

def upload_file(_props_key, file, **kw):
    """Wrapper around storage.upload to upload a file conveniently by using set
    properties, so no need to keep rewriting the same code.
    config file must have STORAGE_UPLOAD_FILE_PROPS where it contains k/v, ie:

    STORAGE_UPLOAD_FILE_PROPS = {
        "profile-image": {
            "extensions": ["jpg", "jpeg", "gif", "png"],
            "prefix": "/profile-image/",
            "public": True
        },
        ...
    }

    upload_file("profile-image", my_file)
    :param _props_key: (str) a key available in config.STORAGE_UPLOAD_FILE_PROPS
    :param file: FileStorage object or string location
    :param kw: extra **kw for
    :return: Storage object"""
    kwargs = {}
    if _props_key is not None:
        conf = config('STORAGE_UPLOAD_FILE_PROPS')
        if not conf:
            raise ValueError('Missing STORAGE_UPLOAD_FILE_PROPS in config')
        if _props_key not in conf:
            raise ValueError("Missing '%s' in config STORAGE_UPLOAD_FILE_PROPS" % _props_key)
        kwargs.update(conf.get(_props_key))
    kwargs.update(kw)
    return signals.upload_file(lambda: storage.upload(file, **kwargs))

def delete_file(fileobj):
