def package_theme(app_name, build_dir, excludes=None, includes=None, path_prefix=None, template_dirs=None):
    """Package resources and templates for a multi-tier environment
    into a zip file.

    Templates are pre-compiled into ``*build_dir*/*app_name*/templates``.
    Compilation means {% assets '*path*' %} and {% static '*path*' %} tags
    are replaced by their compiled expression."""
    templates_dest = os.path.join(build_dir, 'templates')
    orig_static_url = django_settings.STATIC_URL
    if app_name != settings.APP_NAME and (not django_settings.STATIC_URL.startswith('/' + app_name)):
        django_settings.STATIC_URL = '/' + app_name + orig_static_url
    if not os.path.exists(templates_dest):
        os.makedirs(templates_dest)
    if template_dirs is None:
        template_dirs = get_template_search_path(app_name)
    for template_dir in template_dirs:
        if templates_dest and (not os.path.samefile(template_dir, templates_dest)):
            install_templates(template_dir, templates_dest, excludes=excludes, includes=includes, path_prefix=path_prefix)

def _insert_url(request, redirect_field_name=REDIRECT_FIELD_NAME, inserted_url=None):
    """Redirects to the *inserted_url* before going to the orginal
    request path."""
    path = request.build_absolute_uri()
    login_scheme, login_netloc = six.moves.urllib.parse.urlparse(inserted_url)[:2]
    current_scheme, current_netloc = six.moves.urllib.parse.urlparse(path)[:2]
    if (not login_scheme or login_scheme == current_scheme) and (not login_netloc or login_netloc == current_netloc):
        path = request.get_full_path()
    from django.contrib.auth.views import redirect_to_login
    return redirect_to_login(path, inserted_url, redirect_field_name)

def random_init_map(interface, state, label, inp):
    """Assign datapoint `e` randomly to one of the `k` clusters."""
    import random
    out = interface.output(0)
    centers = {}
    for row in inp:
        row = row.strip().split(state['delimiter'])
        if len(row) > 1:
            x = [0 if row[i] in state['missing_vals'] else float(row[i]) for i in state['X_indices']]
            cluster = random.randint(0, state['k'] - 1)
            vertex = state['create'](x, 1.0)
            centers[cluster] = vertex if cluster not in centers else state['update'](centers[cluster], vertex)
    for cluster, values in centers.iteritems():
        out.add(cluster, values)

def estimate_map(interface, state, label, inp):
    """Find the cluster `i` that is closest to the datapoint `e`."""
    out = interface.output(0)
    centers = {}
    for row in inp:
        row = row.strip().split(state['delimiter'])
        if len(row) > 1:
            x = [0 if row[i] in state['missing_vals'] else float(row[i]) for i in state['X_indices']]
            cluster = min(((state['dist'](c, x), i) for i, c in state['centers']))[1]
            vertex = state['create'](x, 1.0)
            centers[cluster] = vertex if cluster not in centers else state['update'](centers[cluster], vertex)
    for cluster, values in centers.iteritems():
        out.add(cluster, values)

def estimate_reduce(interface, state, label, inp):
    """Estimate the cluster centers for each cluster."""
    centers = {}
    for i, c in inp:
        centers[i] = c if i not in centers else state['update'](centers[i], c)
    out = interface.output(0)
    for i, c in centers.items():
        out.add(i, state['finalize'](c))

def predict_map(interface, state, label, inp):
    """Determine the closest cluster for the datapoint `e`."""
    out = interface.output(0)
    for row in inp:
        if len(row) > 1:
            row = row.strip().split(state['delimiter'])
            x_id = '' if state['id_index'] == -1 else row[state['id_index']]
            x = [0 if row[i] in state['missing_vals'] else float(row[i]) for i in state['X_indices']]
            out.add(x_id, min([(i, state['dist'](c, x)) for i, c in state['centers']], key=lambda t: t[1]))

def load_stdlib():
    """Scans sys.path for standard library modules.
    """
    if _stdlib:
        return _stdlib
    prefixes = tuple({os.path.abspath(p) for p in (sys.prefix, getattr(sys, 'real_prefix', sys.prefix), getattr(sys, 'base_prefix', sys.prefix))})
    for sp in sys.path:
        if not sp:
            continue
        _import_paths.append(os.path.abspath(sp))
    stdpaths = tuple({p for p in _import_paths if p.startswith(prefixes) and 'site-packages' not in p})
    _stdlib.update(sys.builtin_module_names)
    for stdpath in stdpaths:
        if not os.path.isdir(stdpath):
            continue
        for item in os.listdir(stdpath):
            if item.startswith('.') or item == 'site-packages':
                continue
            p = os.path.join(stdpath, item)
            if not os.path.isdir(p) and (not item.endswith(('.py', '.so'))):
                continue
            _stdlib.add(item.split('.', 1)[0])
    return _stdlib

def import_path_from_file(filename, as_list=False):
    """Returns a tuple of the import path and root module directory for the
    supplied file."""
    module_path = []
    basename = os.path.splitext(os.path.basename(filename))[0]
    if basename != '__init__':
        module_path.append(basename)
    dirname = os.path.dirname(filename)
    while os.path.isfile(os.path.join(dirname, '__init__.py')):
        dirname, tail = os.path.split(dirname)
        module_path.insert(0, tail)
    if as_list:
        return (module_path, dirname)
    return ('.'.join(module_path), dirname)

def file_containing_import(import_path, import_root):
    """Finds the file that might contain the import_path.
    """
    if not _import_paths:
        load_stdlib()
    if os.path.isfile(import_root):
        import_root = os.path.dirname(import_root)
    search_paths = [import_root] + _import_paths
    module_parts = import_path.split('.')
    for i in range(len(module_parts), 0, -1):
        module_path = os.path.join(*module_parts[:i])
        for sp in search_paths:
            p = os.path.join(sp, module_path)
            if os.path.isdir(p):
                return os.path.join(p, '__init__.py')
            elif os.path.isfile(p + '.py'):
                return p + '.py'
    return None

def resolve_import(import_path, from_module):
    """Resolves relative imports from a module.
    """
    if not import_path or not import_path.startswith('.'):
        return import_path
    from_module = from_module.split('.')
    dots = 0
    for c in import_path:
        if c == '.':
            dots += 1
        else:
            break
    if dots:
        from_module = from_module[:-dots]
        import_path = import_path[dots:]
    if import_path:
        from_module.append(import_path)
    return '.'.join(from_module)

def find_package(name, installed, package=False):
    """Finds a package in the installed list.

    If `package` is true, match package names, otherwise, match import paths."""
    if package:
        name = name.lower()
        tests = (lambda x: x.user and name == x.name.lower(), lambda x: x.local and name == x.name.lower(), lambda x: name == x.name.lower())
    else:
        tests = (lambda x: x.user and name in x.import_names, lambda x: x.local and name in x.import_names, lambda x: name in x.import_names)
    for t in tests:
        try:
            found = list(filter(t, installed))
            if found and (not found[0].is_scan):
                return found[0]
        except StopIteration:
            pass
    return None

def is_script(filename):
    """Checks if a file has a hashbang.
    """
    if not os.path.isfile(filename):
        return False
    try:
        with open(filename, 'rb') as fp:
            return fp.read(2) == b'#!'
    except IOError:
        pass
    return False

def is_python_script(filename):
    """Checks a file to see if it's a python script of some sort.
    """
    if filename.lower().endswith('.py'):
        return True
    if not os.path.isfile(filename):
        return False
    try:
        with open(filename, 'rb') as fp:
            if fp.read(2) != b'#!':
                return False
            return re.match('.*python', str_(fp.readline()))
    except IOError:
        pass
    return False

