def fit(sim_mat, D_len, cidx):
    """Algorithm maximizes energy between clusters, which is distinction in this algorithm. Distance matrix contains mostly 0, which are overlooked due to search of maximal distances. Algorithm does not try to retain k clusters.

    D: numpy array - Symmetric distance matrix
    k: int - number of clusters"""
    min_energy = np.inf
    for j in range(3):
        inds = [np.argmin([sim_mat[idy].get(idx, 0) for idx in cidx]) for idy in range(D_len) if idy in sim_mat]
        cidx = []
        energy = 0
        for i in np.unique(inds):
            indsi = np.where(inds == i)[0]
            minind, min_value = (0, 0)
            for index, idy in enumerate(indsi):
                if idy in sim_mat:
                    value = 0
                    for idx in indsi:
                        value += sim_mat[idy].get(idx, 0)
                    if value < min_value:
                        minind, min_value = (index, value)
            energy += min_value
            cidx.append(indsi[minind])
        if energy < min_energy:
            min_energy, inds_min, cidx_min = (energy, inds, cidx)
    return (inds_min, cidx_min)

def numval(token):
    """Return the numerical value of token.value if it is a number"""
    if token.type == 'INTEGER':
        return int(token.value)
    elif token.type == 'FLOAT':
        return float(token.value)
    else:
        return token.value

def parse(tokens):
    """Parse the token list into a hierarchical data structure"""
    d = collections.OrderedDict()
    prev_line = 0
    blockname = None
    blockline = None
    for token in tokens:
        if token.type == 'COMMENT':
            continue
        elif token.type == 'BLOCK':
            block = token
            blockline = token.line
            blocktype = token.value.upper()
            blockname = None
            if blocktype not in d:
                d[blocktype] = collections.OrderedDict()
        elif token.line == blockline:
            if blockname is None:
                blockname = token.value
                d[blocktype][blockname] = collections.defaultdict(list)
            else:
                d[blocktype][blockname]['info'].append(numval(token))
        elif token.line != prev_line:
            if blockname is None:
                raise ParseError('Found value outside block!')
            d[blocktype][blockname]['values'].append([numval(token)])
        else:
            if blockname is None:
                raise ParseError('Found value outside block!')
            d[blocktype][blockname]['values'][-1].append(numval(token))
        prev_line = token.line
    return d

def load(stream):
    """Parse the LHA document and produce the corresponding Python object.
    Accepts a string or a file-like object."""
    if isinstance(stream, str):
        string = stream
    else:
        string = stream.read()
    tokens = tokenize(string)
    return parse(tokens)

def filter_subcommand_args(func, options):
    """Filter out all options which are not part of the function *func*
    prototype and returns a set that can be used as kwargs for calling func."""
    kwargs = {}
    argspec = inspect.getargspec(func)
    for arg in argspec.args:
        if arg in options:
            kwargs.update({arg: getattr(options, arg)})
    return kwargs

