def get_dem(bounds, out_file='dem.tif', src_crs='EPSG:3005', dst_crs='EPSG:3005', resolution=25):
    """Get 25m DEM for provided bounds, write to GeoTIFF
    """
    bbox = ','.join([str(b) for b in bounds])
    payload = {'service': 'WCS', 'version': '1.0.0', 'request': 'GetCoverage', 'coverage': 'pub:bc_elevation_25m_bcalb', 'Format': 'GeoTIFF', 'bbox': bbox, 'CRS': src_crs, 'RESPONSE_CRS': dst_crs, 'resx': str(resolution), 'resy': str(resolution)}
    r = requests.get(bcdata.WCS_URL, params=payload)
    if r.status_code == 200:
        with open(out_file, 'wb') as file:
            file.write(r.content)
        return out_file
    else:
        raise RuntimeError('WCS request failed with status code {}'.format(str(r.status_code)))

def handle_exception(logger, **kw_decorator):
    """:param logger: logging, a logging object
    :return: decorator, wraps exception loggers"""
    def decorator(query_func):
        @functools.wraps(query_func)
        def wrapper(*args, **kwargs):
            try:
                return query_func(*args, **kwargs)
            except Exception as e:
                logger.info('Exception in function {0} -- {1}'.format(query_func.__name__, e))
                if valid_dict(kw_decorator, ['subject', 'sender', 'username', 'password', 'host', 'receiver']):
                    logger.info('Now is sending the email with exception message')
                    t = time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(time.time()))
                    msg = t + ' ' + 'Exception in function {0} -- {1}'.format(query_func.__name__, e)
                    _send(subject=kw_decorator['subject'], text=msg, sender=kw_decorator['sender'], username=kw_decorator['username'], password=kw_decorator['password'], host=kw_decorator['host'], receiver=kw_decorator['receiver'])
                    logger.info('Email is sent')
        return wrapper
    return decorator

def clock(logger):
    """:param logger: logging, a logging object
    :return: decorator, wraps time"""
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            _start = time.time()
            retval = func(*args, **kwargs)
            _end = time.time()
            logger.info('function {0} used : {1} s'.format(func.__name__, _end - _start))
            return retval
        return wrapper
    return decorator

