def mktree(newdir):
    """works the way a good mkdir should :)
    - already exists, silently complete
    - regular file in the way, raise an exception
    - parent directory(ies) does not exist, make them as well"""
    if os.path.isdir(newdir):
        pass
    elif os.path.isfile(newdir):
        raise OSError("a file with the same name as the desired dir, '%s', already exists." % newdir)
    else:
        os.makedirs(newdir)

def reduce_fit(interface, state, label, inp):
    """Function joins all partially calculated matrices ETE and ETDe, aggregates them and it calculates final parameters."""
    import numpy as np
    out = interface.output(0)
    sum_etde = 0
    sum_ete = [0 for _ in range(len(state['X_indices']) + 1)]
    for key, value in inp:
        if key == 'etde':
            sum_etde += value
        else:
            sum_ete[key] += value
    sum_ete += np.true_divide(np.eye(len(sum_ete)), state['nu'])
    out.add('params', np.linalg.lstsq(sum_ete, sum_etde)[0])

def fingerprint(dirnames, prefix=None, previous=[]):
    """Returns a list of paths available from *dirname*. When previous
    is specified, returns a list of additional files only.

    Example:
    [{ "Key": "abc.txt",
       "LastModified": "Mon, 05 Jan 2015 12:00:00 UTC"},
     { "Key": "def.txt",
       "LastModified": "Mon, 05 Jan 2015 12:00:001 UTC"},
    ]"""
    results = []
    for dirname in dirnames:
        for filename in os.listdir(dirname):
            fullpath = os.path.join(dirname, filename)
            if os.path.isdir(fullpath):
                results += fingerprint([fullpath], prefix=filename, previous=previous)
            else:
                fullname = fullpath
                if prefix and fullname.startswith(prefix):
                    fullname = fullname[len(prefix):]
                found = False
                for prevpath in previous:
                    if fullname == prevpath['Key']:
                        found = True
                        break
                if not found:
                    mtime = datetime.datetime.fromtimestamp(os.path.getmtime(fullpath), tz=utc)
                    results += [{'Key': fullname, 'LastModified': mtime.strftime('%a, %d %b %Y %H:%M:%S %Z')}]
    return results

def list_local(paths, prefix=None):
    """Returns a list of all files (recursively) present in a directory
    with their timestamp.

    Example:
    [{ "Key": "abc.txt",
       "LastModified": "Mon, 05 Jan 2015 12:00:00 UTC"},
     { "Key": "def.txt",
       "LastModified": "Mon, 05 Jan 2015 12:00:001 UTC"},
    ]"""
    results = []
    for path in paths:
        if os.path.isdir(path):
            for filename in os.listdir(path):
                fullpath = os.path.join(path, filename)
                if os.path.isdir(fullpath):
                    results += list_local([fullpath], prefix)
                else:
                    fullname = fullpath
                    if prefix and fullname.startswith(prefix):
                        fullname = fullname[len(prefix):]
                    mtime = datetime.datetime.fromtimestamp(os.path.getmtime(fullpath), tz=utc)
                    results += [{'Key': fullname, 'LastModified': mtime.strftime('%a, %d %b %Y %H:%M:%S %Z')}]
        else:
            fullpath = path
            fullname = fullpath
            if prefix and fullname.startswith(prefix):
                fullname = fullname[len(prefix):]
            mtime = datetime.datetime.fromtimestamp(os.path.getmtime(fullpath), tz=utc)
            results += [{'Key': fullname, 'LastModified': mtime.strftime('%a, %d %b %Y %H:%M:%S %Z')}]
    return results

def convert_currency(amount, from_currency, to_currency):
    """Converts currencies.

    Example:
    {% convert_currency 2 'EUR' 'SGD' as amount %}"""
    try:
        rate = CurrencyRate.objects.get(from_currency__iso_code=from_currency, to_currency__iso_code=to_currency)
    except CurrencyRate.DoesNotExist:
        return _('n/a')
    try:
        history = rate.history.all()[0]
    except IndexError:
        return _('n/a')
    return amount * history.value

