def assembla_filter(func):
    """Filters :data for the objects in it which possess attributes equal in
    name/value to a key/value in kwargs.

    Each key/value combination in kwargs is compared against the object, so
    multiple keyword arguments can be passed in to constrain the filtering."""
    @wraps(func)
    def wrapper(class_instance, **kwargs):
        extra_params = kwargs.get('extra_params', None)
        if extra_params:
            del kwargs['extra_params']
        results = func(class_instance, extra_params)
        if kwargs:
            results = filter(lambda obj: len(kwargs) == len(filter(lambda boolean: boolean, [obj.get(attr_name) == value for attr_name, value in kwargs.iteritems()])), results)
        return results
    return wrapper

def locate_config(confname, app_name, location=None, prefix='etc', verbose=False):
    """Returns absolute path on the filesystem to a config file named *confname*."""
    candidates = []
    if location:
        candidate = os.path.normpath(os.path.join(location, confname))
        if os.path.isfile(candidate):
            candidates += [candidate]
    candidate = os.path.normpath(os.path.join(os.path.dirname(os.path.dirname(sys.executable)), prefix, app_name, confname))
    if os.path.isfile(candidate):
        candidates += [candidate]
    candidate = os.path.normpath('/%s/%s/%s' % (prefix, app_name, confname))
    if os.path.isfile(candidate):
        candidates += [candidate]
    candidate = os.path.normpath(os.path.join(os.getcwd(), confname))
    if os.path.isfile(candidate):
        candidates += [candidate]
    if candidates:
        if verbose:
            LOGGER.info("config loaded from '%s'", candidates[0])
        return candidates[0]
    else:
        LOGGER.warning("config '%s' was not found.", confname)
    return None

def _openssl_key_iv(passphrase, salt):
    """Returns a (key, iv) tuple that can be used in AES symmetric encryption
    from a *passphrase* (a byte or unicode string) and *salt* (a byte array)."""
    def _openssl_kdf(req):
        if hasattr(passphrase, 'encode'):
            passwd = passphrase.encode('ascii', 'ignore')
        else:
            passwd = passphrase
        prev = b''
        while req > 0:
            digest = hashes.Hash(hashes.MD5(), backend=default_backend())
            digest.update(prev + passwd + salt)
            prev = digest.finalize()
            req -= IV_BLOCK_SIZE
            yield prev
    assert passphrase is not None
    assert salt is not None
    mat = b''.join([x for x in _openssl_kdf(32 + IV_BLOCK_SIZE)])
    return (mat[0:32], mat[32:32 + IV_BLOCK_SIZE])

def find_and_parse_config(config, default_config='default.yaml'):
    """Finds the service configuration file and parses it.
    Checks also a directory called default, to check for default configuration values,
    that will be overwritten by the actual configuration found on given path."""
    def load_config(path):
        if os.path.isfile(path):
            with open(path, 'r') as f:
                config_dict_ = yaml.load(f)
            return config_dict_
    config_path = find_file(config)
    default_path = find_file(default_config)
    config = load_config(config_path)
    default_config = load_config(default_path)
    if config is None and default_config is None:
        raise ValueError('Both config and default_config return None')
    if config is None:
        config_dict = default_config
    elif default_config is None:
        config_dict = config
    else:
        config_dict = merge(default_config, config)
    return config_dict

def full_name_natural_split(full_name):
    """This function splits a full name into a natural first name, last name
    and middle initials."""
    parts = full_name.strip().split(' ')
    first_name = ''
    if parts:
        first_name = parts.pop(0)
    if first_name.lower() == 'el' and parts:
        first_name += ' ' + parts.pop(0)
    last_name = ''
    if parts:
        last_name = parts.pop()
    if last_name.lower() == 'i' or last_name.lower() == 'ii' or (last_name.lower() == 'iii' and parts):
        last_name = parts.pop() + ' ' + last_name
    middle_initials = ''
    for middle_name in parts:
        if middle_name:
            middle_initials += middle_name[0]
    return (first_name, middle_initials, last_name)

