def process_inlines(parser, token):
    """Searches through the provided content and applies inlines where ever they
    are found.

    Syntax::

        {% process_inlines entry.body [in template_dir] [as varname] }

    Examples::

        {% process_inlines entry.body %}

        {% process_inlines entry.body as body %}

        {% process_inlines entry.body in 'inlines/sidebar' %}

        {% process_inlines entry.body in 'inlines/sidebar' as body %}"""
    args = token.split_contents()
    if not len(args) in (2, 4, 6):
        raise template.TemplateSyntaxError('%r tag requires either 1, 3 or 5 arguments.' % args[0])
    var_name = args[1]
    ALLOWED_ARGS = ['as', 'in']
    kwargs = {'template_directory': None}
    if len(args) > 2:
        tuples = zip(*[args[2:][i::2] for i in range(2)])
        for k, v in tuples:
            if not k in ALLOWED_ARGS:
                raise template.TemplateSyntaxError('%r tag options arguments must be one of %s.' % (args[0], ', '.join(ALLOWED_ARGS)))
            if k == 'in':
                kwargs['template_directory'] = v
            if k == 'as':
                kwargs['asvar'] = v
    return InlinesNode(var_name, **kwargs)

def build_current_graph():
    """Read current state of SQL items from the current project state.

    Returns:
        (SQLStateGraph) Current project state graph."""
    graph = SQLStateGraph()
    for app_name, config in apps.app_configs.items():
        try:
            module = import_module('.'.join((config.module.__name__, SQL_CONFIG_MODULE)))
            sql_items = module.sql_items
        except (ImportError, AttributeError):
            continue
        for sql_item in sql_items:
            graph.add_node((app_name, sql_item.name), sql_item)
            for dep in sql_item.dependencies:
                graph.add_lazy_dependency((app_name, sql_item.name), dep)
    graph.build_graph()
    return graph

def _sql_params(sql):
    """Identify `sql` as either SQL string or 2-tuple of SQL and params.
    Same format as supported by Django's RunSQL operation for sql/reverse_sql."""
    params = None
    if isinstance(sql, (list, tuple)):
        elements = len(sql)
        if elements == 2:
            sql, params = sql
        else:
            raise ValueError('Expected a 2-tuple but got %d' % elements)
    return (sql, params)

def map_fit(interface, state, label, inp):
    """Function counts occurrences of feature values for every row in given data chunk. For continuous features it returns
    number of values and it calculates mean and variance for every feature.
    For discrete features it counts occurrences of labels and values for every feature. It returns occurrences of pairs:
    label, feature index, feature values."""
    import numpy as np
    combiner = {}
    out = interface.output(0)
    for row in inp:
        row = row.strip().split(state['delimiter'])
        if len(row) > 1:
            for i, j in enumerate(state['X_indices']):
                if row[j] not in state['missing_vals']:
                    pair = row[state['y_index']] + state['delimiter'] + str(j)
                    if state['X_meta'][i] == 'c':
                        if pair in combiner:
                            combiner[pair].append(np.float32(row[j]))
                        else:
                            combiner[pair] = [np.float32(row[j])]
                    else:
                        pair += state['delimiter'] + row[j]
                        combiner[pair] = combiner.get(pair, 0) + 1
                    combiner[row[state['y_index']]] = combiner.get(row[state['y_index']], 0) + 1
    for k, v in combiner.iteritems():
        if len(k.split(state['delimiter'])) == 2:
            out.add(k, (np.size(v), np.mean(v, dtype=np.float32), np.var(v, dtype=np.float32)))
        else:
            out.add(k, v)

