def define_request(dataset, query=None, crs='epsg:4326', bounds=None, sortby=None, pagesize=10000):
    """Define the getfeature request parameters required to download a dataset

    References:
    - http://www.opengeospatial.org/standards/wfs
    - http://docs.geoserver.org/stable/en/user/services/wfs/vendor.html
    - http://docs.geoserver.org/latest/en/user/tutorials/cql/cql_tutorial.html"""
    table = validate_name(dataset)
    n = bcdata.get_count(table, query=query)
    chunks = math.ceil(n / pagesize)
    if chunks > 1 and (not sortby):
        sortby = get_sortkey(table)
    param_dicts = []
    for i in range(chunks):
        request = {'service': 'WFS', 'version': '2.0.0', 'request': 'GetFeature', 'typeName': table, 'outputFormat': 'json', 'SRSNAME': crs}
        if sortby:
            request['sortby'] = sortby
        if query:
            request['CQL_FILTER'] = query
        if bounds:
            request['bbox'] = ','.join([str(b) for b in bounds])
        if chunks > 1:
            request['startIndex'] = i * pagesize
            request['count'] = pagesize
        param_dicts.append(request)
    return param_dicts

def get_features(dataset, query=None, crs='epsg:4326', bounds=None, sortby=None, pagesize=10000, max_workers=5):
    """Yield features from DataBC WFS
    """
    param_dicts = define_request(dataset, query, crs, bounds, sortby, pagesize)
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        for result in executor.map(make_request, param_dicts):
            for feature in result:
                yield feature

def total_amount(qs) -> Total:
    """Sums the amounts of the objects in the queryset, keeping each currency separate.
    :param qs: A querystring containing objects that have an amount field of type Money.
    :return: A Total object."""
    aggregate = qs.values('amount_currency').annotate(sum=Sum('amount'))
    return Total((Money(amount=r['sum'], currency=r['amount_currency']) for r in aggregate))

