def polish(commit_indexes=None, urls=None):
    """Apply certain behaviors to commits or URLs that need polishing before they are ready for screenshots

    For example, if you have 10 commits in a row where static file links were broken, you could re-write the html
    in memory as it is interpreted.

    Keyword arguments:
    commit_indexes -- A list of indexes to apply the wrapped function to
    url -- A list of URLs to apply the wrapped function to"""
    def decorator(f):
        if commit_indexes:
            f.polish_commit_indexes = commit_indexes
        if urls:
            f.polish_urls = urls
        @wraps(f)
        def wrappee(*args, **kwargs):
            return f(*args, **kwargs)
        return wrappee
    return decorator

def _scan_file(filename, sentinel, source_type='import'):
    """Generator that performs the actual scanning of files.

    Yeilds a tuple containing import type, import path, and an extra file
    that should be scanned. Extra file scans should be the file or directory
    that relates to the import name."""
    filename = os.path.abspath(filename)
    real_filename = os.path.realpath(filename)
    if os.path.getsize(filename) <= max_file_size:
        if real_filename not in sentinel and os.path.isfile(filename):
            sentinel.add(real_filename)
            basename = os.path.basename(filename)
            scope, imports = ast_scan_file(filename)
            if scope is not None and imports is not None:
                for imp in imports:
                    yield (source_type, imp.module, None)
                if 'INSTALLED_APPS' in scope and basename == 'settings.py':
                    log.info('Found Django settings: %s', filename)
                    for item in django.handle_django_settings(filename):
                        yield item
            else:
                log.warn('Could not scan imports from: %s', filename)
    else:
        log.warn('File size too large: %s', filename)

def _scan_directory(directory, sentinel, depth=0):
    """Basically os.listdir with some filtering.
    """
    directory = os.path.abspath(directory)
    real_directory = os.path.realpath(directory)
    if depth < max_directory_depth and real_directory not in sentinel and os.path.isdir(directory):
        sentinel.add(real_directory)
        for item in os.listdir(directory):
            if item in ('.', '..'):
                continue
            p = os.path.abspath(os.path.join(directory, item))
            if os.path.isdir(p) and _dir_ignore.search(p) or (os.path.isfile(p) and _ext_ignore.search(p)):
                continue
            yield p

def scan_file(pym, filename, sentinel, installed):
    """Entry point scan that creates a PyModule instance if needed.
    """
    if not utils.is_python_script(filename):
        return
    if not pym:
        module = os.path.basename(filename)
        pym = utils.find_package(module, installed)
        if not pym:
            pym = PyModule(module, 'SCRIPT', os.path.abspath(filename))
            installed.insert(0, pym)
        else:
            pym.is_scan = True
    for imp_type, import_path, extra_file_scan in _scan_file(filename, sentinel):
        dep = utils.find_package(import_path, installed)
        if dep:
            dep.add_dependant(pym)
            pym.add_dependency(dep)
            if imp_type != 'import':
                pym.add_framework(imp_type)
        if extra_file_scan:
            scan_filename = utils.file_containing_import(import_path, extra_file_scan)
            log.info('Related scan: %s - %s', import_path, scan_filename)
            if scan_filename.endswith('__init__.py'):
                scan_directory(pym, os.path.dirname(scan_filename), sentinel, installed)
            else:
                scan_file(pym, scan_filename, sentinel, installed)
    return pym

def scan_directory(pym, directory, sentinel, installed, depth=0):
    """Entry point scan that creates a PyModule instance if needed.
    """
    if not pym:
        d = os.path.abspath(directory)
        basename = os.path.basename(d)
        pym = utils.find_package(basename, installed)
        if not pym:
            version = 'DIRECTORY'
            if os.path.isfile(os.path.join(d, '__init__.py')):
                version = 'MODULE'
            pym = PyModule(basename, version, d)
            installed.insert(0, pym)
        else:
            pym.is_scan = True
    bad_scans = 0
    for item in _scan_directory(directory, sentinel, depth):
        if os.path.isfile(item):
            if bad_scans > 100:
                log.debug('Stopping scan of directory since it looks like a data dump: %s', directory)
                break
            if not scan_file(pym, item, sentinel, installed):
                bad_scans += 1
            else:
                bad_scans = 0
        elif os.path.isdir(item):
            scan_directory(pym, item, sentinel, installed, depth + 1)
    return pym

def verify_predictions(predictions):
    """Ensures that predictions is stored as a numpy array and checks that
    all values are either 0 or 1."""
    predictions = np.array(predictions, copy=False)
    if not np.array_equal(predictions, predictions.astype(bool)):
        raise ValueError('predictions contains invalid values. ' + 'The only permitted values are 0 or 1.')
    if predictions.ndim == 1:
        predictions = predictions[:, np.newaxis]
    return predictions

def verify_scores(scores):
    """Ensures that scores is stored as a numpy array and checks that all
    values are finite."""
    scores = np.array(scores, copy=False)
    if np.any(~np.isfinite(scores)):
        raise ValueError('scores contains invalid values. ' + 'Please check that all values are finite.')
    if scores.ndim == 1:
        scores = scores[:, np.newaxis]
    return scores

def verify_consistency(predictions, scores, proba, opt_class):
    """Verifies that all arrays have consistent dimensions. Also verifies
    that the scores are consistent with proba.

    Returns
    -------
    proba, opt_class"""
    if predictions.shape != scores.shape:
        raise ValueError('predictions and scores arrays have inconsistent ' + 'dimensions.')
    n_class = scores.shape[1] if scores.ndim > 1 else 1
    if proba is None:
        proba = np.repeat(False, n_class)
    if opt_class is None:
        opt_class = np.repeat(True, n_class)
    proba = np.array(proba, dtype=bool, ndmin=1)
    opt_class = np.array(opt_class, dtype=bool, ndmin=1)
    if np.sum(opt_class) < 1:
        raise ValueError('opt_class should contain at least one True value.')
    if predictions.shape[1] != len(proba):
        raise ValueError('mismatch in shape of proba and predictions.')
    if predictions.shape[1] != len(opt_class):
        raise ValueError('mismatch in shape of opt_class and predictions.')
    for m in range(n_class):
        if np.any(np.logical_or(scores[:, m] < 0, scores[:, m] > 1)) and proba[m]:
            warnings.warn('scores fall outside the [0,1] interval for ' + 'classifier {}. Setting proba[m]=False.'.format(m))
            proba[m] = False
    return (proba, opt_class)

def verify_identifiers(identifiers, n_items):
    """Ensure that identifiers has a compatible length and that its elements
    are unique"""
    if identifiers is None:
        return identifiers
    identifiers = np.array(identifiers, copy=False)
    if len(identifiers) != n_items:
        raise ValueError('identifiers has inconsistent dimension.')
    if len(np.unique(identifiers)) != n_items:
        raise ValueError('identifiers contains duplicate values.')
    return identifiers

def scores_to_probs(scores, proba, eps=0.01):
    """Transforms scores to probabilities by applying the logistic function"""
    if np.any(~proba):
        probs = copy.deepcopy(scores)
        n_class = len(proba)
        for m in range(n_class):
            if not proba[m]:
                max_extreme_score = max(np.abs(np.min(scores[:, m])), np.abs(np.max(scores[:, m])))
                k = np.log((1 - eps) / eps) / max_extreme_score
                self._probs[:, m] = expit(k * self.scores[:, m])
        return probs
    else:
        return scores

