def path(append=None, prepend=None, replace=None, on=os):
    """Update the PATH environment variable.

    Can append, prepend, or replace the path.  Each of these expects a string
    or a list of strings (for multiple path elements) and can operate on remote
    connections that offer an @environ@ attribute using the @on@ argument."""
    original = on.environ['PATH']
    if replace and (append or prepend):
        raise ValueError('You can not combine append or prepend with replace.')
    if replace:
        if not isinstance(replace, list):
            replace = list(replace)
        on.environ['PATH'] = ':'.join(replace)
    else:
        if append:
            if not isinstance(append, list):
                append = list(append)
            append.insert(0, on.environ['PATH'])
            on.environ['PATH'] = ':'.join(append)
        if prepend:
            if not isinstance(prepend, list):
                prepend = list(prepend)
            prepend.append(on.environ['PATH'])
            on.environ['PATH'] = ':'.join(prepend)
    yield
    on.environ['PATH'] = original

def environ(on=os, **kw):
    """Update one or more environment variables.

    Preserves the previous environment variable (if available) and can be
    applied to remote connections that offer an @environ@ attribute using the
    @on@ argument."""
    originals = list()
    for key in kw:
        originals.append((key, on.environ.get(key, None)))
        on.environ[key] = kw[key]
    yield
    for key, value in originals:
        if not value:
            del on.environ[key]
            continue
        on.environ[key] = value

def _wrap_decorator(decorator, targets, is_valid_target):
    """Wraps given decorator in order to provide additional functionality:
    optional arguments and verification of decorator's target type.

    :param decorator: Decorator callable
    :param targets: Name of the decorator targets, as plural
                    (used in error messages)
    :param is_valid_target: Callable for checking
                            whether decorator's target is valid

    :return: Wrapped ``decorator``"""
    @functools.wraps(decorator)
    def wrapper(*args, **kwargs):
        one_arg = len(args) == 1 and (not kwargs)
        if one_arg and is_valid_target(args[0]):
            actual_decorator = decorator()
            return actual_decorator(args[0])
        actual_decorator = decorator(*args, **kwargs)
        def decorator_wrapper(target):
            if not is_valid_target(target):
                raise TypeError('@%s can only be applied to %s: got %r instead' % (decorator.__name__, targets, type(target)))
            return actual_decorator(target)
        return decorator_wrapper
    return wrapper

def camel_case(arg, capitalize=None):
    '''Converts given text with whitespaces between words
    into equivalent camel-cased one.

    :param capitalize: Whether result will have first letter upper case (True),
                       lower case (False), or left as is (None, default).

    :return: String turned into camel-case "equivalent"'''
    ensure_string(arg)
    if not arg:
        return arg
    words = split(arg)
    first_word = words[0] if len(words) > 0 else None
    words = [word.capitalize() for word in words]
    if first_word is not None:
        if capitalize is True:
            first_word = first_word.capitalize()
        elif capitalize is False:
            first_word = first_word[0].lower() + first_word[1:]
        words[0] = first_word
    return join(arg.__class__(), words)

def random(length, chars=None):
    """Generates a random string.

    :param length: Length of the string to generate.
                   This can be a numbe or a pair: ``(min_length, max_length)``
    :param chars: String of characters to choose from"""
    if chars is None:
        chars = string.ascii_letters + string.digits
    else:
        ensure_string(chars)
        if not chars:
            raise ValueError('character set must not be empty')
    if is_pair(length):
        length = randint(*length)
    elif isinstance(length, Integral):
        if not length > 0:
            raise ValueError('random string length must be positive (got %r)' % (length,))
    else:
        raise TypeError("random string length must be an integer; got '%s'" % type(length).__name__)
    return join(chars.__class__(), (choice(chars) for _ in xrange(length)))

def transformation(func):
    """Function decorator to turn another function into a transformation."""
    @wraps(func)
    def func_as_transformation(*args, **kwargs):
        if hasattr(args[0], 'history'):
            history = args[0].history
        else:
            history = []
        image = func(*args, **kwargs)
        image = Image.from_array(image, log_in_history=False)
        image.history = history
        image.history.append('Applied {} transform'.format(func.__name__))
        if AutoWrite.on:
            fpath = AutoName.name(func)
            try:
                if AutoWrite.auto_safe_dtype:
                    safe_range_im = 255 * normalise(image)
                    pil_im = PIL.Image.fromarray(safe_range_im.astype(np.uint8))
                else:
                    pil_im = PIL.Image.fromarray(image)
            except TypeError:
                raise TypeError('Cannot handle this data type: {}'.format(image.dtype))
            pil_im.save(fpath)
        return image
    return func_as_transformation

def smooth_gaussian(image, sigma=1):
