def lookupSpatialReferenceID(wellKnownText):
    """This function can be used to look up the EPSG spatial reference system using the web service available at:
    http://prj2epsg.org

    Args:
        wellKnownText (str): The Well Known Text definition of the spatial reference system.

    Returns:
        int: Spatial Reference ID"""
    payload = {'mode': 'wkt', 'terms': wellKnownText}
    try:
        r = requests.get('http://prj2epsg.org/search.json', params=payload)
    except requests.exceptions.ConnectionError:
        print('SRID Lookup Error: Could not automatically determine spatial reference ID, because there is no internet connection. Please check connection and try again.')
        exit(1)
    if r.status_code == 200:
        json = r.json()
        for code in json['codes']:
            return code['code']

def palette(fg, bg=-1):
    """Since curses only supports a finite amount of initialised colour pairs
    we memoise any selections you've made as an attribute on this function"""
    if not hasattr(palette, 'counter'):
        palette.counter = 1
    if not hasattr(palette, 'selections'):
        palette.selections = {}
    selection = '%s%s' % (str(fg), str(bg))
    if not selection in palette.selections:
        palette.selections[selection] = palette.counter
        palette.counter += 1
    colors = [c for c in dir(_curses) if c.startswith('COLOR')]
    if isinstance(fg, str):
        if not 'COLOR_' + fg.upper() in colors:
            fg = -1
        else:
            fg = getattr(_curses, 'COLOR_' + fg.upper())
    if isinstance(bg, str):
        if not 'COLOR_' + bg.upper() in colors:
            bg = -1
        else:
            bg = getattr(_curses, 'COLOR_' + bg.upper())
    _curses.init_pair(palette.selections[selection], fg, bg)
    return _curses.color_pair(palette.selections[selection])

def validate_rows_length(data, length, message=None, exception=MatrixError):
    """Validate that all rows have the same length."""
    if message is None:
        message = 'All rows must have the same length (same number of columns)'
    for row in data:
        if len(row) != length:
            raise exception(message)

def validate_square(data, message=None, exception=MatrixError):
    """Validate that the matrix has equal number of rows and columns."""
    rows, columns = (len(data), len(data[0]) if data else 0)
    if message is None:
        message = 'Number of rows: %s != number of columns: %s in matrix' % (rows, columns)
    if rows != columns:
        raise exception(message)

def validate_categories_equal_entities(categories, entities, message=None, exception=MatrixError):
    """Validate that the matrix has equal number of entities and categories."""
    nb_categories = len(categories)
    nb_entities = len(entities)
    if message is None:
        message = 'Number of categories: %s != number of entities: %s' % (nb_categories, nb_entities)
    if categories and nb_categories != nb_entities:
        raise exception(message)

def eye(root=None, zodb_uri=None, port=8080):
    """Serves a WSGI app to browse objects based on a root object or ZODB URI.
    """
    if root is not None:
        root_factory = lambda request: Node(root)
    elif zodb_uri is not None:
        if '://' not in zodb_uri:
            zodb_uri = 'file://' + os.path.abspath(zodb_uri)
        from repoze.zodbconn.finder import PersistentApplicationFinder
        finder = PersistentApplicationFinder(zodb_uri, appmaker=lambda root: Node(root))
        root_factory = lambda request: finder(request.environ)
    else:
        raise RuntimeError('Must specify root object or ZODB URI.')
    app = Eye(root_factory)
    if 'DEBUG' in os.environ:
        from repoze.debug.pdbpm import PostMortemDebug
        app = PostMortemDebug(app)
    serve(app, host='127.0.0.1', port=port)

