def iterqueue(queue, expected):
    """Iterate all value from the queue until the ``expected`` number of EXIT elements is
    received"""
    while expected > 0:
        for item in iter(queue.get, EXIT):
            yield item
        expected -= 1

def r12_serial_port(port):
    """Create a serial connect to the arm."""
    return serial.Serial(port, baudrate=BAUD_RATE, parity=PARITY, stopbits=STOP_BITS, bytesize=BYTE_SIZE)

def search_for_port(port_glob, req, expected_res):
    """Find the serial port the arm is connected to."""
    if usb.core.find(idVendor=1027, idProduct=24577) is None:
        return None
    ports = glob.glob(port_glob)
    if len(ports) == 0:
        return None
    for port in ports:
        with r12_serial_port(port) as ser:
            if not ser.isOpen():
                ser.open()
            if sys.version_info[0] == 2:
                ser.write(str(req).encode('utf-8'))
            else:
                ser.write(bytes(req, 'utf-8'))
            time.sleep(0.1)
            res = ser.read(ser.in_waiting).decode(OUTPUT_ENCODING)
            if expected_res in res:
                return port
    raise ArmException('ST Robotics connection found, but is not responsive.' + ' Is the arm powered on?')
    return None

def is_tuple(obj, len_=None):
    """Checks whether given object is a tuple.

    :param len_: Optional expected length of the tuple

    :return: ``True`` if argument is a tuple (of given length, if any),
             ``False`` otherwise"""
    if not isinstance(obj, tuple):
        return False
    if len_ is None:
        return True
    if not isinstance(len_, Integral):
        raise TypeError('length must be a number (got %s instead)' % type(len_).__name__)
    if len_ < 0:
        raise ValueError('length must be positive (got %s instead)' % len_)
    return len(obj) == len_

def select(indices, from_, strict=False):
    """Selects a subsequence of given tuple, including only specified indices.

    :param indices: Iterable of indices to include
    :param strict: Whether ``indices`` are required to exist in the tuple.

    :return: Tuple with selected elements, in the order corresponding
             to the order of ``indices``.

    :raise IndexError: If ``strict`` is True and one of ``indices``
                       is out of range."""
    ensure_iterable(indices)
    ensure_sequence(from_)
    if strict:
        return from_.__class__((from_[index] for index in indices))
    else:
        len_ = len(from_)
        return from_.__class__((from_[index] for index in indices if 0 <= index < len_))

def omit(indices, from_, strict=False):
    """Returns a subsequence from given tuple, omitting specified indices.

    :param indices: Iterable of indices to exclude
    :param strict: Whether ``indices`` are required to exist in the tuple

    :return: Tuple without elements of specified indices

    :raise IndexError: If ``strict`` is True and one of ``indices``
                       is out of range.

    .. versionadded:: 0.0.3"""
    from taipan.collections.sets import remove_subset
    ensure_iterable(indices)
    ensure_sequence(from_)
    if strict:
        remaining_indices = set(xrange(len(from_)))
        try:
            remove_subset(remaining_indices, indices)
        except KeyError as e:
            raise IndexError(int(str(e)))
    else:
        remaining_indices = set(xrange(len(from_))) - set(indices)
    return from_.__class__((from_[index] for index in remaining_indices))

def _describe_type(arg):
    """Describe given argument, including length if it's a tuple.

    The purpose is to prevent nonsensical exception messages such as::

        expected a tuple of length 2, got tuple
        expected a tuple, got tuple

    by turning them into::

        expected a tuple of length 3, got tuple of length 2"""
    if isinstance(arg, tuple):
        return 'tuple of length %s' % len(arg)
    else:
        return type(arg).__name__

def sample_following_dist(handle_iter, n, totalf):
    """Samples n passwords following the distribution from the handle
    @handle_iter is an iterator that gives (pw,f) @n is the total
    number of samle asked for @totalf is the total number of users,
    which is euqal to sum(f for pw,f in handle_iter)
    As, handle_iterator is an iterator and can only traverse once.

    @totalf needs to be supplied to the funciton.
    @handle_iter must be sorted in decreasing order

    Returns, an array of @n tuples (id, pw) sampled from @handle_iter."""
    multiplier = 1.0
    if totalf == 1.0:
        multiplier = 100000000.0
    totalf = totalf * multiplier
    A = gen_n_random_num(n, totalf, unique=False)
    A.sort(reverse=True)
    assert len(A) == n, 'Not enough randomnumbers generatedRequried {}, generated only {}'.format(n, len(A))
    j, sampled = (0, 0)
    val = A.pop()
    for w, f in handle_iter:
        j += f * multiplier
        while val < j:
            sampled += 1
            if sampled % 5000 == 0:
                print('Sampled:', sampled)
            yield (val, w)
            if A:
                val = A.pop()
            else:
                val = -1
                break
        if not A and val == -1:
            break
    while A and val < j:
        yield (val, w)
        if A:
            i, val = A.pop()
        else:
            break

def getallgroups(arr, k=-1):
    """returns all the subset of @arr of size less than equalto @k
    the return array will be of size \\sum_{i=1}^k nCi, n = len(arr)"""
    if k < 0:
        k = len(arr)
    return itertools.chain.from_iterable((itertools.combinations(set(arr), j) for j in range(1, k + 1)))

