def find_best_question(X, y, criterion):
    """Find the best question to ask by iterating over every feature / value
    and calculating the information gain."""
    measure_impurity = gini_impurity if criterion == 'gini' else entropy
    current_impurity = measure_impurity(y)
    best_info_gain = 0
    best_question = None
    for feature_n in range(X.shape[1]):
        for value in set(X[:, feature_n]):
            q = Question(feature_n, value)
            _, _, true_y, false_y = split(X, y, q)
            current_info_gain = info_gain(current_impurity, true_y, false_y, criterion)
            if current_info_gain >= best_info_gain:
                best_info_gain = current_info_gain
                best_question = q
    return (best_info_gain, best_question)

def build_tree(X, y, criterion, max_depth, current_depth=1):
    """Builds the decision tree.
    """
    if max_depth >= 0 and current_depth >= max_depth:
        return Leaf(y)
    gain, question = find_best_question(X, y, criterion)
    if gain == 0:
        return Leaf(y)
    true_X, false_X, true_y, false_y = split(X, y, question)
    true_branch = build_tree(true_X, true_y, criterion, max_depth, current_depth=current_depth + 1)
    false_branch = build_tree(false_X, false_y, criterion, max_depth, current_depth=current_depth + 1)
    return Node(question=question, true_branch=true_branch, false_branch=false_branch)

def tree_predict(x, root, proba=False, regression=False):
    """Predicts a probabilities/value/label for the sample x.
    """
    if isinstance(root, Leaf):
        if proba:
            return root.probabilities
        elif regression:
            return root.mean
        else:
            return root.most_frequent
    if root.question.match(x):
        return tree_predict(x, root.true_branch, proba=proba, regression=regression)
    else:
        return tree_predict(x, root.false_branch, proba=proba, regression=regression)

def evaluations(ty, pv, useScipy=True):
    """evaluations(ty, pv, useScipy) -> (ACC, MSE, SCC)
    ty, pv: list, tuple or ndarray
    useScipy: convert ty, pv to ndarray, and use scipy functions for the evaluation

    Calculate accuracy, mean squared error and squared correlation coefficient
    using the true values (ty) and predicted values (pv)."""
    if scipy != None and useScipy:
        return evaluations_scipy(scipy.asarray(ty), scipy.asarray(pv))
    if len(ty) != len(pv):
        raise ValueError('len(ty) must be equal to len(pv)')
    total_correct = total_error = 0
    sumv = sumy = sumvv = sumyy = sumvy = 0
    for v, y in zip(pv, ty):
        if y == v:
            total_correct += 1
        total_error += (v - y) * (v - y)
        sumv += v
        sumy += y
        sumvv += v * v
        sumyy += y * y
        sumvy += v * y
    l = len(ty)
    ACC = 100.0 * total_correct / l
    MSE = total_error / l
    try:
        SCC = (l * sumvy - sumv * sumy) * (l * sumvy - sumv * sumy) / ((l * sumvv - sumv * sumv) * (l * sumyy - sumy * sumy))
    except:
        SCC = float('nan')
    return (float(ACC), float(MSE), float(SCC))

