def _catch(f, exception_type):
    """Decorator to drop into the debugger if a function throws an exception."""
    if not (inspect.isclass(exception_type) and issubclass(exception_type, Exception)):
        exception_type = Exception
    @functools.wraps(f)
    def wrap(*args, **kw):
        try:
            return f(*args, **kw)
        except exception_type as e:
            qj(e, 'Caught an exception in %s' % f, d=1, _depth=2)
    return wrap

def _stack_effect(op_code, oparg):
    """Compute the effect an op_code and oparg have on the stack.  See python/compile.c."""
    n_args = lambda o: o % 256 + 2 * (o // 256)
    if op_code == 'DUP_TOPX':
        return oparg
    elif op_code == 'UNPACK_SEQUENCE':
        return oparg - 1
    elif op_code == 'BUILD_TUPLE':
        return -oparg
    elif op_code == 'BUILD_LIST':
        return -oparg
    elif op_code == 'BUILD_SET':
        return -oparg
    elif op_code == 'RAISE_VARARGS':
        return -oparg
    elif op_code == 'CALL_FUNCTION':
        return -n_args(oparg)
    elif op_code == 'CALL_FUNCTION_VAR':
        return -n_args(oparg) - 1
    elif op_code == 'CALL_FUNCTION_KW':
        return -n_args(oparg) - 1
    elif op_code == 'CALL_FUNCTION_VAR_KW':
        return -n_args(oparg) - 2
    elif op_code == 'MAKE_FUNCTION':
        return -oparg
    elif op_code == 'BUILD_SLICE':
        if oparg == 3:
            return -2
        else:
            return -1
    elif op_code == 'MAKE_CLOSURE':
        return -oparg - 1
    return _STACK_EFFECTS[op_code]

def abstract(class_):
    """Mark the class as _abstract_ base class, forbidding its instantiation.

    .. note::

        Unlike other modifiers, ``@abstract`` can be applied
        to all Python classes, not just subclasses of :class:`Object`.

    .. versionadded:: 0.0.3"""
    if not inspect.isclass(class_):
        raise TypeError('@abstract can only be applied to classes')
    abc_meta = None
    class_meta = type(class_)
    if class_meta not in (_ABCMetaclass, _ABCObjectMetaclass):
        if class_meta is type:
            abc_meta = _ABCMetaclass
        elif class_meta is ObjectMetaclass:
            abc_meta = _ABCObjectMetaclass
        else:
            raise ValueError('@abstract cannot be applied to classes with custom metaclass')
    class_.__abstract__ = True
    return metaclass(abc_meta)(class_) if abc_meta else class_

def override(base=ABSENT):
    """Mark a method as overriding a corresponding method from superclass.

    :param base:

        Optional base class from which this method is being overridden.
        If provided, it can be a class itself, or its (qualified) name.

    .. note::

        When overriding a :class:`classmethod`, remember to place ``@override``
        above the ``@classmethod`` decorator::

            class Foo(Bar):
                @override
                @classmethod
                def florb(cls):
                    pass"""
    arg = base
    if inspect.isfunction(arg) or isinstance(arg, NonInstanceMethod):
        _OverrideDecorator.maybe_signal_classmethod(arg)
        decorator = _OverrideDecorator(None)
        return decorator(arg)
    if arg is ABSENT:
        return _OverrideDecorator(None)
    if is_class(arg) or is_string(arg):
        return _OverrideDecorator(arg)
    raise TypeError('explicit base class for @override must be either a string or a class object')

def _index(*args, **kwargs):
    """Implementation of list searching.

    :param of: Element to search for
    :param where: Predicate to search for
    :param in_: List to search in
    :param start: Start index for the lookup
    :param step: Counter step (i.e. in/decrement) for each iteration

    :return: Pair of ``(list, index)``,
             where ``list`` is the list we searched in
             and ``index`` is the index of the first element found, or -1"""
    start = kwargs.pop('start', 0)
    step = kwargs.pop('step', 1)
    if len(args) == 2:
        elem, list_ = args
        ensure_sequence(list_)
        predicate = lambda item: item == elem
    else:
        ensure_keyword_args(kwargs, mandatory=('in_',), optional=('of', 'where'))
        if 'of' in kwargs and 'where' in kwargs:
            raise TypeError('either an item or predicate must be supplied, not both')
        if not ('of' in kwargs or 'where' in kwargs):
            raise TypeError('an item or predicate must be supplied')
        list_ = ensure_sequence(kwargs['in_'])
        if 'where' in kwargs:
            predicate = ensure_callable(kwargs['where'])
        else:
            elem = kwargs['of']
            predicate = lambda item: item == elem
    len_ = len(list_)
    start = max(0, min(len_ - 1, start))
    i = start
    while 0 <= i < len_:
        if predicate(list_[i]):
            return (list_, i)
        i += step
    else:
        return (list_, -1)

def describe_delta(delta):
    """Describe this timedelta in human-readable terms.

    :param delta: datetime.timedelta object
    :returns: str, describing this delta"""
    s = delta.total_seconds()
    s = abs(s)
    hours, remainder = divmod(s, 3600)
    minutes, seconds = divmod(remainder, 60)
    if hours:
        return '%d hr %d min' % (hours, minutes)
    if minutes:
        return '%d min %d secs' % (minutes, seconds)
    return '%d secs' % seconds

def log_est_complete(est_complete):
    """Log the relative time remaining for this est_complete datetime object."""
    if not est_complete:
        print('could not determine an estimated completion time')
        return
    remaining = est_complete - datetime.utcnow()
    message = 'this task should be complete in %s'
    if remaining.total_seconds() < 0:
        message = 'this task exceeds estimate by %s'
    log_delta(message, remaining)

def patched_normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded."""
    if output is None:
        output = []
    if Broken in getattr(sequence, '__bases__', ()):
        return [sequence]
    cls = sequence.__class__
    if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
        output.append(sequence)
    else:
        for v in sequence:
            patched_normalizeargs(v, output)
    return output

