    :param predicate: Predicate taking key and value, or None

    .. versionchanged:: 0.0.2
       Renamed ``starfilteritems`` for consistency with :func:`starmapitems`."""
    ensure_mapping(dict_)
    if predicate is None:
        predicate = lambda k, v: all((k, v))
    else:
        ensure_callable(predicate)
    return dict_.__class__(((k, v) for k, v in iteritems(dict_) if predicate(k, v)))

def _nary_dict_update(dicts, **kwargs):
    """Implementation of n-argument ``dict.update``,
    with flags controlling the exact strategy."""
    copy = kwargs['copy']
    res = dicts[0].copy() if copy else dicts[0]
    if len(dicts) == 1:
        return res
    deep = kwargs['deep']
    overwrite = kwargs['overwrite']
    if deep:
        dict_update = curry(_recursive_dict_update, overwrite=overwrite)
    elif overwrite:
        dict_update = res.__class__.update
    else:
        def dict_update(dict_, other):
            for k, v in iteritems(other):
                dict_.setdefault(k, v)
    for d in dicts[1:]:
        dict_update(res, d)
    return res

def _recursive_dict_update(dict_, other, **kwargs):
    """Deep/recursive version of ``dict.update``.

    If a key is present in both dictionaries, and points to
    "child" dictionaries, those will be appropriately merged.

    :param overwrite: Whether to overwrite exisiting dictionary values"""
    overwrite = kwargs['overwrite']
    for key, other_value in iteritems(other):
        if key in dict_:
            value = dict_[key]
            if is_mapping(value) and is_mapping(other_value):
                _recursive_dict_update(value, other_value, overwrite=overwrite)
                continue
        if overwrite:
            dict_[key] = other_value
        else:
            dict_.setdefault(key, other_value)

def k_subsets(set_, k):
    """Return subsets of given set with given cardinality.
    :param k: Cardinality of subsets to return
    :return: Iterable containing all ``k``-subsets of given set"""
    ensure_countable(set_)
    if not isinstance(k, Integral):
        raise TypeError('subset cardinality must be a number')
    if not k >= 0:
        raise ValueError('subset cardinality must be positive')
    if not k <= len(set_):
        raise ValueError('subset cardinality must not exceed set cardinality')
    result = combinations(set_, k)
    return _harmonize_subset_types(set_, result)

def _harmonize_subset_types(set_, subset_tuples):
    """Possibly convert an iterable of tuples with subsets of given "set",
    to an iterable of :class:`set` objects if original "set" was so too."""
    if is_tuple(set_):
        return subset_tuples
    else:
        subset_class = set_.__class__ if is_set(set_) else tuple
        return imap(subset_class, subset_tuples)

def cast(type_, value, default=ABSENT):
    """Cast a value to given type, optionally returning a default, if provided.

    :param type_: Type to cast the ``value`` into
    :param value: Value to cast into ``type_``

    :return: ``value`` casted to ``type_``.
             If cast was unsuccessful and ``default`` was provided,
             it is returned instead.

    :raise AssertionError: When ``type_`` is not actually a Python type
    :raise TypeError: When cast was unsuccessful and no ``default`` was given"""
    assert isinstance(type_, type)
    to_number = issubclass(type_, Number)
    exception = ValueError if to_number else TypeError
    try:
        return type_(value)
    except exception as e:
        if default is ABSENT:
            if to_number:
                msg = 'cannot convert %r to %r' % (value, type_) if IS_PY3 else str(e)
                raise TypeError(msg)
            else:
                raise
        return type_(default)

def is_magic(s):
    """Check whether given string is a __magic__ Python identifier.
    :return: Whether ``s`` is a __magic__ Python identifier"""
    if not is_identifier(s):
        return False
    return len(s) > 4 and s.startswith('__') and s.endswith('__')

def normalize(pw):
    """Lower case, and change the symbols to closest characters"""
    pw_lower = pw.lower()
    return ''.join((helper.L33T.get(c, c) for c in pw_lower))

def normalise(array):
    """Return array normalised such that all values are between 0 and 1.

    If all the values in the array are the same the function will return:
    - np.zeros(array.shape, dtype=np.float) if the value is 0 or less
    - np.ones(array.shape, dtype=np.float) if the value is greater than 0

    :param array: numpy.array
    :returns: numpy.array.astype(numpy.float)"""
    min_val = array.min()
    max_val = array.max()
    array_range = max_val - min_val
    if array_range == 0:
        if min_val > 0:
            return np.ones(array.shape, dtype=np.float)
        return np.zeros(array.shape, dtype=np.float)
    return (array.astype(np.float) - min_val) / array_range

def map_stack(array3D, z_function):
    """Return 3D array where each z-slice has had the function applied to it.

    :param array3D: 3D numpy.array
    :param z_function: function to be mapped to each z-slice"""
    _, _, zdim = array3D.shape
    return np.dstack([z_function(array3D[:, :, z]) for z in range(zdim)])

def check_dtype(array, allowed):
    """Raises TypeError if the array is not of an allowed dtype.

    :param array: array whose dtype is to be checked
    :param allowed: instance or list of allowed dtypes"""
    if not hasattr(allowed, '__iter__'):
        allowed = [allowed]
    if array.dtype not in allowed:
        raise TypeError('Invalid dtype {}. Allowed dtype(s): {}'.format(array.dtype, allowed))

def dtype_contract(input_dtype=None, output_dtype=None):
    """Function decorator for specifying input and/or output array dtypes."""
    def wrap(function):
        @wraps(function)
        def wrapped_function(*args, **kwargs):
            if input_dtype is not None:
                check_dtype(args[0], input_dtype)
            array = function(*args, **kwargs)
            if output_dtype is not None:
                check_dtype(array, output_dtype)
            return array
        return wrapped_function
    return wrap

def compose(*fs):
    """Creates composition of the functions passed in.

    :param fs: One-argument functions, with the possible exception of last one
               that can accept arbitrary arguments

    :return: Function returning a result of functions from ``fs``
             applied consecutively to the argument(s), in reverse order"""
    ensure_argcount(fs, min_=1)
    fs = list(imap(ensure_callable, fs))
    if len(fs) == 1:
        return fs[0]
    if len(fs) == 2:
        f1, f2 = fs
        return lambda *args, **kwargs: f1(f2(*args, **kwargs))
    if len(fs) == 3:
        f1, f2, f3 = fs
        return lambda *args, **kwargs: f1(f2(f3(*args, **kwargs)))
    fs.reverse()
    def g(*args, **kwargs):
        x = fs[0](*args, **kwargs)
        for f in fs[1:]:
            x = f(x)
        return x
    return g

def and_(*fs):
    """Creates a function that returns true for given arguments
    iff every given function evalutes to true for those arguments.

    :param fs: Functions to combine

    :return: Short-circuiting function performing logical conjunction
             on results of ``fs`` applied to its arguments"""
    ensure_argcount(fs, min_=1)
    fs = list(imap(ensure_callable, fs))
    if len(fs) == 1:
        return fs[0]
    if len(fs) == 2:
        f1, f2 = fs
        return lambda *args, **kwargs: f1(*args, **kwargs) and f2(*args, **kwargs)
    if len(fs) == 3:
        f1, f2, f3 = fs
        return lambda *args, **kwargs: f1(*args, **kwargs) and f2(*args, **kwargs) and f3(*args, **kwargs)
    def g(*args, **kwargs):
        for f in fs:
            if not f(*args, **kwargs):
                return False
        return True
    return g

def gini_impurity(s):
    """Calculate the Gini Impurity for a list of samples.

    See:
    https://en.wikipedia.org/wiki/Decision_tree_learning#Gini_impurity"""
    return 1 - sum((prop(s[i], s) ** 2 for i in range(len(s))))

def entropy(s):
    """Calculate the Entropy Impurity for a list of samples.
    """
    return -sum((p * np.log(p) for i in range(len(s)) for p in [prop(s[i], s)]))

def pad_zeroes(addr, n_zeroes):
    """Padds the address with zeroes"""
    if len(addr) < n_zeroes:
        return pad_zeroes('0' + addr, n_zeroes)
    return addr

def _soap_client_call(method_name, *args):
    """Wrapper to call SoapClient method"""
    soap_client = _build_soap_client()
    soap_args = _convert_soap_method_args(*args)
    if PYSIMPLESOAP_1_16_2:
        return getattr(soap_client, method_name)(*soap_args)
    else:
        return getattr(soap_client, method_name)(soap_client, *soap_args)

def _parse_string_el(el):
    """read a string element, maybe encoded in base64"""
    value = str(el)
    el_type = el.attributes().get('xsi:type')
    if el_type and el_type.value == 'xsd:base64Binary':
        value = base64.b64decode(value)
        if not PY2:
            value = value.decode('utf-8', errors='replace')
    value = _uc(value)
    return value

def native(s, encoding='utf-8', fallback='iso-8859-1'):
    """Convert a given string into a native string."""
    if isinstance(s, str):
        return s
    if str is unicode:
        return unicodestr(s, encoding, fallback)
    return bytestring(s, encoding, fallback)

def unicodestr(s, encoding='utf-8', fallback='iso-8859-1'):
    """Convert a string to unicode if it isn't already."""
    if isinstance(s, unicode):
        return s
    try:
        return s.decode(encoding)
    except UnicodeError:
        return s.decode(fallback)

def uvalues(a, encoding='utf-8', fallback='iso-8859-1'):
    """Return a list of decoded values from an iterator.

    If any of the values fail to decode, re-decode all values using the
    fallback."""
    try:
        return (encoding, [s.decode(encoding) for s in a])
    except UnicodeError:
        return (fallback, [s.decode(fallback) for s in a])

def main(argv=None):
    """Command line entry point"""
    if not argv:
        argv = sys.argv[1:]
    parser = argparse.ArgumentParser(description=_HELP_TEXT)
    parser.add_argument('input', nargs='?', default=None)
    parser.add_argument('output', nargs='?', default=None)
    parser.add_argument('--version', action='version', version='%(prog)s ' + get_version())
    args = parser.parse_args(argv)
    if not args.input:
        print('No file specified', file=sys.stderr)
        sys.exit(1)
    try:
        with open(args.input, 'r') as f:
            res = mangle(f.read())
            if not args.output:
                print(res, end='')
            else:
                with open(args.output, 'w') as o:
                    o.write(res)
    except Exception as ex:
        print('Error mangling {}: {!s}'.format(args.input, ex), file=sys.stderr)
        sys.exit(1)

def _retrieve_object(output_dict: Dict[str, Any], obj: Any) -> None:
    """Function to recursively retrieve histograms from a list in a ROOT file.

    ``SetDirectory(True)`` is applied to TH1 derived hists and python is explicitly given
    ownership of the retrieved objects.

    Args:
        output_dict (dict): Dict under which hists should be stored.
        obj (ROOT.TObject derived): Object(s) to be stored. If it is a collection,
            it will be recursed through.
    Returns:
        None: Changes in the dict are reflected in the output_dict which was passed."""
    import ROOT
    if isinstance(obj, ROOT.TH1) or isinstance(obj, ROOT.THnBase):
        if isinstance(obj, ROOT.TH1):
            obj.SetDirectory(0)
        ROOT.SetOwnership(obj, False)
        output_dict[obj.GetName()] = obj
    if isinstance(obj, ROOT.TCollection):
        output_dict[obj.GetName()] = {}
        for obj_temp in list(obj):
            _retrieve_object(output_dict[obj.GetName()], obj_temp)

def import_string(import_name, silent=False):
    """Imports an object based on a string.  This is useful if you want to
    use import paths as endpoints or something similar.  An import path can
    be specified either in dotted notation (``xml.sax.saxutils.escape``)
    or with a colon as object delimiter (``xml.sax.saxutils:escape``).

    If `silent` is True the return value will be `None` if the import fails.

    :param import_name: the dotted name for the object to import.
    :param silent: if set to `True` import errors are ignored and
                   `None` is returned instead.
    :return: imported object"""
    import_name = str(import_name).replace(':', '.')
    try:
        try:
            __import__(import_name)
        except ImportError:
            if '.' not in import_name:
                raise
        else:
            return sys.modules[import_name]
        module_name, obj_name = import_name.rsplit('.', 1)
        try:
            module = __import__(module_name, None, None, [obj_name])
        except ImportError:
            module = import_string(module_name)
        try:
            return getattr(module, obj_name)
        except AttributeError as e:
            raise ImportError(e)
    except ImportError as e:
        if not silent:
            raise e

def logtrace(logger, msg, *args, **kwargs):
    """If esgfpid.defaults.LOG_TRACE_TO_DEBUG, messages are treated
    like debug messages (with an added [trace]).
    Otherwise, they are ignored."""
    if esgfpid.defaults.LOG_TRACE_TO_DEBUG:
        logdebug(logger, '[trace] %s' % msg, *args, **kwargs)
    else:
        pass

def logdebug(logger, msg, *args, **kwargs):
    """Logs messages as DEBUG,
    unless show=True and esgfpid.defaults.LOG_SHOW_TO_INFO=True,
    (then it logs messages as INFO)."""
    if esgfpid.defaults.LOG_DEBUG_TO_INFO:
        logger.info('DEBUG %s ' % msg, *args, **kwargs)
    else:
        logger.debug(msg, *args, **kwargs)

def loginfo(logger, msg, *args, **kwargs):
    """Logs messages as INFO,
    unless esgfpid.defaults.LOG_INFO_TO_DEBUG,
    (then it logs messages as DEBUG)."""
    if esgfpid.defaults.LOG_INFO_TO_DEBUG:
        logger.debug(msg, *args, **kwargs)
    else:
        logger.info(msg, *args, **kwargs)

def log_every_x_times(logger, counter, x, msg, *args, **kwargs):
    """Works like logdebug, but only prints first and
    and every xth message."""
    if counter == 1 or counter % x == 0:
        logdebug(logger, msg, *args, **kwargs)

def maybe_open(infile, mode='r'):
    """Take a file name or a handle, and return a handle.

    Simplifies creating functions that automagically accept either a file name
    or an already opened file handle."""
    if isinstance(infile, basestring):
        handle = open(infile, mode)
        do_close = True
    else:
        handle = infile
        do_close = False
    yield handle
    if do_close:
        handle.close()

def delete_module(modname):
    """Delete module and sub-modules from `sys.module`"""
    try:
        _ = sys.modules[modname]
    except KeyError:
        raise ValueError("Module not found in sys.modules: '{}'".format(modname))
    for module in list(sys.modules.keys()):
        if module and module.startswith(modname):
            del sys.modules[module]

def reload_module(module):
    """Reload the Python module"""
    try:
        reload(module)
    except (ImportError, NameError):
        import imp
        imp.reload(module)
    except (ImportError, NameError):
        import importlib
        importlib.reload(module)

def lazy_load_modules(*modules):
    """Decorator to load module to perform related operation for specific function
    and delete the  module from imports once the task is done. GC frees the memory
    related to module during clean-up."""
    def decorator(function):
        def wrapper(*args, **kwargs):
            module_dict = {}
            for module_string in modules:
                module = __import__(module_string)
                sys.modules[module.__package__] = module
                reload_module(module)
                module_dict[module_string] = module
            func_response = function(*args, **kwargs)
            for module_string, module in module_dict.items():
                delete_module(module_string)
                del module
            return func_response
        return wrapper
    return decorator

def authorized(route):
    """Wrap a flask route. Ensure that the user has authorized via OAuth or
    redirect the user to the authorization endpoint with a delayed redirect
    back to the originating endpoint."""
    @wraps(route)
    def authorized_route(*args, **kwargs):
        if 'mwoauth_access_token' in flask.session:
            return route(*args, **kwargs)
        else:
            return flask.redirect(flask.url_for('mwoauth.mwoauth_initiate') + '?next=' + flask.request.endpoint)
    return authorized_route

def update(connection, silent, hgnc_file_path, hcop_file_path, low_memory):
    """Update the database"""
    database.update(connection=connection, silent=silent, hgnc_file_path=hgnc_file_path, hcop_file_path=hcop_file_path, low_memory=low_memory)

def get_prime(bits):
    """Creates (probable) prime number of given size

    :param bits: size of number to generate
    :return: prime number of given size"""
    while True:
        num = random.randrange(2 ** (bits - 1), 2 ** bits)
        if Integer(str(num)).is_probably_prime():
            return num

def simple_time(value):
    """Format a datetime or timedelta object to a string of format HH:MM"""
    if isinstance(value, timedelta):
        return ':'.join(str(value).split(':')[:2])
    return datetime_to_string(value, '%H:%M')

def is_dst(zonename):
    """Find out whether it's Daylight Saving Time in this timezone"""
    tz = pytz.timezone(zonename)
    now = pytz.utc.localize(datetime.utcnow())
    return now.astimezone(tz).dst() != timedelta(0)

def load_datetime(value, dt_format):
    """Create timezone-aware datetime object"""
    if dt_format.endswith('%z'):
        dt_format = dt_format[:-2]
        offset = value[-5:]
        value = value[:-5]
        if offset != offset.replace(':', ''):
            offset = '+' + offset.replace(':', '')
            value = value[:-1]
        return OffsetTime(offset).localize(datetime.strptime(value, dt_format))
    return datetime.strptime(value, dt_format)

def list_to_json(source_list):
    """Serialise all the items in source_list to json"""
    result = []
    for item in source_list:
        result.append(item.to_json())
    return result

def list_from_json(source_list_json):
    """Deserialise all the items in source_list from json"""
    result = []
    if source_list_json == [] or source_list_json == None:
        return result
    for list_item in source_list_json:
        item = json.loads(list_item)
        try:
            if item['class_name'] == 'Departure':
                temp = Departure()
            elif item['class_name'] == 'Disruption':
                temp = Disruption()
            elif item['class_name'] == 'Station':
                temp = Station()
            elif item['class_name'] == 'Trip':
                temp = Trip()
            elif item['class_name'] == 'TripRemark':
                temp = TripRemark()
            elif item['class_name'] == 'TripStop':
                temp = TripStop()
            elif item['class_name'] == 'TripSubpart':
                temp = TripSubpart()
            else:
                print('Unrecognised Class ' + item['class_name'] + ', skipping')
                continue
            temp.from_json(list_item)
            result.append(temp)
        except KeyError:
            print('Unrecognised item with no class_name, skipping')
            continue
    return result

def list_diff(list_a, list_b):
    """Return the items from list_b that differ from list_a"""
    result = []
    for item in list_b:
        if not item in list_a:
            result.append(item)
    return result

def list_same(list_a, list_b):
    """Return the items from list_b that are also on list_a"""
    result = []
    for item in list_b:
        if item in list_a:
            result.append(item)
    return result

def list_merge(list_a, list_b):
    """Merge two lists without duplicating items

    Args:
      list_a: list
      list_b: list
    Returns:
      New list with deduplicated items from list_a and list_b"""
    result = []
    for item in list_a:
        if not item in result:
            result.append(item)
    for item in list_b:
        if not item in result:
            result.append(item)
    return result

def flatten(dictionary, separator='.', prefix=''):
    """Flatten the dictionary keys are separated by separator

    Arguments:
        dictionary {dict} -- The dictionary to be flattened.

    Keyword Arguments:
        separator {str} -- The separator to use (default is '.'). It will
        crush items with key conflicts.
        prefix {str} -- Used for recursive calls.

    Returns:
        dict -- The flattened dictionary."""
    new_dict = {}
    for key, value in dictionary.items():
        new_key = prefix + separator + key if prefix else key
        if isinstance(value, collections.MutableMapping):
            new_dict.update(flatten(value, separator, new_key))
        elif isinstance(value, list):
            new_value = []
            for item in value:
                if isinstance(item, collections.MutableMapping):
                    new_value.append(flatten(item, separator, new_key))
                else:
                    new_value.append(item)
            new_dict[new_key] = new_value
        else:
            new_dict[new_key] = value
    return new_dict

def adapt_array(arr):
    """http://stackoverflow.com/a/31312102/190597 (SoulNibbler)"""
    out = io.BytesIO()
    np.save(out, arr)
    out.seek(0)
    return sqlite3.Binary(out.read())

def get_files(file_tokens, cwd=None):
    """Given a list of parser file tokens, return a list of input objects
    for them."""
    if not file_tokens:
        return []
    token = file_tokens.pop()
    try:
        filename = token.filename
    except AttributeError:
        filename = ''
    if cwd:
        input = Input(token.alias, filename, cwd=cwd)
    else:
        input = Input(token.alias, filename)
    return [input] + get_files(file_tokens)

def get_paths(path_tokens):
    """Given a list of parser path tokens, return a list of path objects
    for them."""
    if len(path_tokens) == 0:
        return []
    token = path_tokens.pop()
    path = PathToken(token.alias, token.path)
    return [path] + get_paths(path_tokens)

def _get_command_templates(command_tokens, files=[], paths=[], job_options=[], count=1):
    """Reversivly create command templates."""
    if not command_tokens:
        return []
    comment_tokens, command_token = command_tokens.pop()
    parts = []
    parts += job_options + _get_comments(comment_tokens)
    for part in command_token[0]:
        try:
            parts.append(_get_file_by_alias(part, files))
            continue
        except (AttributeError, ValueError):
            pass
        for cut in part.split():
            try:
                parts.append(_get_path_by_name(cut, paths))
                continue
            except ValueError:
                pass
            parts.append(cut)
    command_template = CommandTemplate(alias=str(count), parts=parts)
    [setattr(p, 'alias', command_template.alias) for p in command_template.output_parts]
    return [command_template] + _get_command_templates(command_tokens, files, paths, job_options, count + 1)

def _get_prelim_dependencies(command_template, all_templates):
    """Given a command_template determine which other templates it
    depends on. This should not be used as the be-all end-all of
    dependencies and before calling each command, ensure that it's
    requirements are  met."""
    deps = []
    for input in command_template.input_parts:
        if '.' not in input.alias:
            continue
        for template in all_templates:
            for output in template.output_parts:
                if input.fuzzy_match(output):
                    deps.append(template)
                    break
    return list(set(deps))

def _get_file_by_alias(part, files):
    """Given a command part, find the file it represents. If not found,
    then returns a new token representing that file.
    :throws ValueError: if the value is not a command file alias."""
    if _is_output(part):
        return Output.from_string(part.pop())
    else:
        inputs = [[]]
        if part.magic_or:
            and_or = 'or'
        else:
            and_or = 'and'
        for cut in part.asList():
            if cut == OR_TOKEN:
                inputs.append([])
                continue
            if cut == AND_TOKEN:
                continue
            input = Input(cut, filename=cut, and_or=and_or)
            for file in files:
                if file.alias == cut:
                    input.filename = file.filename
                    inputs[-1].append(input)
                    break
            else:
                inputs[-1].append(input)
        return [input for input in inputs if input]

def _get_path_by_name(part, paths):
    """Given a command part, find the path it represents.
    :throws ValueError: if no valid file is found."""
    for path in paths:
        if path.alias == part:
            return path
    raise ValueError

def _is_output(part):
    """Returns whether the given part represents an output variable."""
    if part[0].lower() == 'o':
        return True
    elif part[0][:2].lower() == 'o:':
        return True
    elif part[0][:2].lower() == 'o.':
        return True
    else:
        return False

def wrap_maya_ui(mayaname):
    """Given the name of a Maya UI element of any type,
    return the corresponding QWidget or QAction.
    If the object does not exist, returns None

    :param mayaname: the maya ui element
    :type mayaname: str
    :returns: the wraped object
    :rtype: QObject | None
    :raises: None"""
    ptr = apiUI.MQtUtil.findControl(mayaname)
    if ptr is None:
        ptr = apiUI.MQtUtil.findLayout(mayaname)
    if ptr is None:
        ptr = apiUI.MQtUtil.findMenuItem(mayaname)
    if ptr is not None:
        return wrap(long(ptr))

def get_now_utc():
    """date in UTC, ISO format"""
    ZERO = datetime.timedelta(0)
    class UTC(datetime.tzinfo):
        """UTC"""
        def utcoffset(self, dt):
            return ZERO
        def tzname(self, dt):
            return 'UTC'
        def dst(self, dt):
            return ZERO
    now = datetime.datetime.now(UTC())
    return now

def sketch(*args, output_sketch='sketch.msh', threads=1, returncmd=False, **kwargs):
    """Wrapper for mash sketch.
    :param args: Files you want to sketch. Any number can be passed in, file patterns (i.e. *fasta) can be used.
    :param output_sketch: Output file for your sketch. Default sketch.msh.
    :param threads: Number of threads to run analysis on.
    :param kwargs: Other arguments, in parameter='argument' format. If parameter is just a switch, do parameter=''
    :param returncmd: If true, will return the command used to call mash as well as out and err.
    :return: stdout and stderr from mash sketch"""
    options = kwargs_to_string(kwargs)
    if len(args) == 0:
        raise ValueError('At least one file to sketch must be specified. You specified 0 files.')
    cmd = 'mash sketch '
    for arg in args:
        cmd += arg + ' '
    cmd += '-o {} -p {} {}'.format(output_sketch, str(threads), options)
    out, err = accessoryfunctions.run_subprocess(cmd)
    if returncmd:
        return (out, err, cmd)
    else:
        return (out, err)

def apply_formatting_dict(obj: Any, formatting: Dict[str, Any]) -> Any:
    """Recursively apply a formatting dict to all strings in a configuration.

    Note that it skips applying the formatting if the string appears to contain latex (specifically,
    if it contains an "$"), since the formatting fails on nested brackets.

    Args:
        obj: Some configuration object to recursively applying the formatting to.
        formatting (dict): String formatting options to apply to each configuration field.
    Returns:
        dict: Configuration with formatting applied to every field."""
    new_obj = obj
    if isinstance(obj, str):
        if '$' not in obj:
            new_obj = string.Formatter().vformat(obj, (), formatting_dict(**formatting))
    elif isinstance(obj, dict):
        new_obj = {}
        for k, v in obj.items():
            new_obj[k] = apply_formatting_dict(v, formatting)
    elif isinstance(obj, list):
        new_obj = []
        for i, el in enumerate(obj):
            new_obj.append(apply_formatting_dict(el, formatting))
    elif isinstance(obj, int) or isinstance(obj, float) or obj is None:
        pass
    elif isinstance(obj, enum.Enum):
        pass
    else:
        logger.debug(f"Unrecognized obj '{obj}' of type '{type(obj)}'")
    return new_obj

def parse_wait_time(text: str) -> int:
    """Parse the waiting time from the exception"""
    val = RATELIMIT.findall(text)
    if len(val) > 0:
        try:
            res = val[0]
            if res[1] == 'minutes':
                return int(res[0]) * 60
            if res[1] == 'seconds':
                return int(res[0])
        except Exception as e:
            util_logger.warning('Could not parse ratelimit: ' + str(e))
    return 1 * 60

def handle_rate_limit(func: Callable[[Any], Any], *args, **kwargs) -> Any:
    """Calls :code:`func` with given arguments and handle rate limit exceptions.

    :param func: Function to call
    :param args: Argument list for :code:`func`
    :param kwargs: Dict arguments for `func`
    :returns: :code:`func` result"""
    error_count = 0
    while True:
        try:
            return func(*args, **kwargs)
        except Exception as e:
            if error_count > 3:
                util_logger.error('Retried to call <{}> 3 times without success. Continuing without calling it.'.format(func.__name__))
                break
            if 'DELETED_COMMENT' in str(e):
                util_logger.warning('The comment has been deleted. Function <{}> was not executed.'.format(func.__name__))
                break
            wait = parse_wait_time(str(e))
            util_logger.error(e)
            util_logger.warning('Waiting ~{} minutes'.format(round(float(wait + 30) / 60)))
            time.sleep(wait + 30)
            error_count += 1

def insert_trie(trie, value):
    """Insert a value into the trie if it is not already contained in the trie.
    Return the subtree for the value regardless of whether it is a new value
    or not."""
    if value in trie:
        return trie[value]
    multi_check = False
    for key in tuple(trie.keys()):
        if len(value) > len(key) and value.startswith(key):
            return insert_trie(trie[key], value)
        elif key.startswith(value):
            if not multi_check:
                trie[value] = {}
                multi_check = True
            dict_ = trie.pop(key)
            trie[value][key] = dict_
    if value not in trie:
        trie[value] = {}
    return trie[value]

