def request(method='GET'):
    """send restful post http request decorator

    Provide a brief way to manipulate restful api,

    :param method: :class:`str`,

    :return: :class:`func`"""
    def decorator(func):
        @functools.wraps(func)
        def action(self, *args, **kwargs):
            f = furl(self.server)
            path, body = func(self, *args, **kwargs)
            query = dict()
            if isinstance(path, tuple):
                path, query = path
            f.path.add(path)
            f.query.set(query)
            status_code, result = send_rest(f.url, method=method.upper(), body=body, session=self.session, headers=self.headers)
            if status_code != httplib.OK:
                self.logger.error('{impl} {url} headers: {headers}, code: {code}'.format(impl=method, url=f.url, headers=self.headers, code=status_code))
            return (status_code, result)
        return action
    return decorator

def parse_image_name(name):
    """parse the image name into three element tuple, like below:
    (repository, name, version)
    :param name: `class`:`str`, name
    :return: (repository, name, version)"""
    name = name or ''
    if '/' in name:
        repository, other = name.split('/')
    else:
        repository, other = (None, name)
    if ':' in other:
        name, version = other.split(':')
    else:
        name, version = (other, 'latest')
    return (repository, name, version)

def _remove_outliers_from_hist(hist: Hist, outliers_start_index: int, outliers_removal_axis: OutliersRemovalAxis) -> None:
    """Remove outliers from a given histogram.

    Args:
        hist: Histogram to check for outliers.
        outliers_start_index: Index in the truth axis where outliers begin.
        outliers_removal_axis: Axis along which outliers removal will be performed. Usually
            the particle level aixs.
    Returns:
        None. The histogram is modified in place."""
    if outliers_start_index > 0:
        x = ctypes.c_int(0)
        y = ctypes.c_int(0)
        z = ctypes.c_int(0)
        outliers_removal_axis_values: Dict[OutliersRemovalAxis, ctypes.c_int] = {projectors.TH1AxisType.x_axis: x, projectors.TH1AxisType.y_axis: y, projectors.TH1AxisType.z_axis: z}
        for index in range(0, hist.GetNcells()):
            hist.GetBinXYZ(index, x, y, z)
            if hist.GetBinContent(index) < hist.GetBinError(index):
                logger.warning(f'Bin content < error. Name: {hist.GetName()}, Bin content: {hist.GetBinContent(index)}, Bin error: {hist.GetBinError(index)}, index: {index}, ({x.value}, {y.value})')
            if outliers_removal_axis_values[outliers_removal_axis].value >= outliers_start_index:
                hist.SetBinContent(index, 0)
                hist.SetBinError(index, 0)
    else:
        logger.info(f'Hist {hist.GetName()} did not have any outliers to cut')

