def ordered_async_call(func_list):
    """Runs the list of function asynchronously, returns the response maintaining the order

    :param func_list: Expects list of lists to be of format
        [[func1, args1, kwargs1], [func2, args2, kwargs2], ...]
    :return: List of output of the functions
        [output1, output2, ...]"""
    def worker(function, f_args, f_kwargs, queue, index):
        """Runs the function and appends the output to list, and the Exception in the case of error"""
        response = {'index': index, 'data': None, 'error': None}
        try:
            response['data'] = function(*f_args, **f_kwargs)
        except Exception as e:
            response['error'] = e
        queue.put(response)
    queue = Queue()
    processes = [Process(target=worker, args=(func, args, kwargs, queue, i)) for i, (func, args, kwargs) in enumerate(func_list)]
    for process in processes:
        process.start()
    response_list = []
    for process in processes:
        process.join()
        response = queue.get()
        if response['error']:
            raise response['error']
        response_list.append(response)
    return [content['data'] for content in sorted(response_list, key=lambda x: x['index'])]

def editheaders():
    """Edits the headers of SAM files to remove 'secondary alignments'"""
    for line in fileinput.input():
        try:
            columns = line.split('\t')
            flag = int(columns[1])
            columns[1] = str(flag - 256 if flag & 256 else flag)
            sys.stdout.write('\t'.join(columns))
        except (IOError, ValueError):
            sys.stdout.write(line)
            pass
    try:
        sys.stdout.flush()
        sys.stdout.close()
    except:
        pass
    try:
        sys.stderr.close()
    except:
        pass

def hist_axis_func(axis_type: enum.Enum) -> Callable[[Hist], Axis]:
    """Wrapper to retrieve the axis of a given histogram.

    This can be convenient outside of just projections, so it's made available in the API.

    Args:
        axis_type: The type of axis to retrieve.
    Returns:
        Callable to retrieve the specified axis when given a hist."""
    def axis_func(hist: Hist) -> Axis:
        """Retrieve the axis associated with the ``HistAxisRange`` object for a given hist.

        Args:
            hist: Histogram from which the selected axis should be retrieved.
            axis_type: Enumeration corresponding to the axis to be restricted. The numerical
                value of the enum should be axis number (for a THnBase).
        Returns:
            ROOT.TAxis: The axis associated with the ``HistAxisRange`` object."""
        try:
            hist_axis_type = axis_type.value
        except AttributeError:
            hist_axis_type = axis_type
        if hasattr(hist, 'ProjectionND') and hasattr(hist, 'Projection'):
            return hist.GetAxis(hist_axis_type)
        else:
            axis_function_map = {TH1AxisType.x_axis.value: hist.GetXaxis, TH1AxisType.y_axis.value: hist.GetYaxis, TH1AxisType.z_axis.value: hist.GetZaxis}
            return_func = axis_function_map[hist_axis_type]
            return return_func()
    return axis_func

def getTzid(tzid, smart=True):
    """Return the tzid if it exists, or None."""
    tz = __tzidMap.get(toUnicode(tzid), None)
    if smart and tzid and (not tz):
        try:
            from pytz import timezone, UnknownTimeZoneError
            try:
                tz = timezone(tzid)
                registerTzid(toUnicode(tzid), tz)
            except UnknownTimeZoneError:
                pass
        except ImportError:
            pass
    return tz

def dateTimeToString(dateTime, convertToUTC=False):
    """Ignore tzinfo unless convertToUTC.  Output string."""
    if dateTime.tzinfo and convertToUTC:
        dateTime = dateTime.astimezone(utc)
    datestr = '{}{}{}T{}{}{}'.format(numToDigits(dateTime.year, 4), numToDigits(dateTime.month, 2), numToDigits(dateTime.day, 2), numToDigits(dateTime.hour, 2), numToDigits(dateTime.minute, 2), numToDigits(dateTime.second, 2))
    if tzinfo_eq(dateTime.tzinfo, utc):
        datestr += 'Z'
    return datestr

def stringToDateTime(s, tzinfo=None):
    """Returns datetime.datetime object."""
    try:
        year = int(s[0:4])
        month = int(s[4:6])
        day = int(s[6:8])
        hour = int(s[9:11])
        minute = int(s[11:13])
        second = int(s[13:15])
        if len(s) > 15:
            if s[15] == 'Z':
                tzinfo = utc
    except:
        raise ParseError("'%s' is not a valid DATE-TIME" % s)
    year = year and year or 2000
    return datetime.datetime(year, month, day, hour, minute, second, 0, tzinfo)

def mangleIR(data, ignore_errors=False):
    """Mangle a raw Kira data packet into shorthand"""
    try:
        if isinstance(data, bytes):
            data = data.decode('ascii')
        data = data.strip()
        times = [int(x, 16) for x in data.split()[2:]]
        minTime = min(times[2:-1])
        maxTime = max(times[2:-1])
        margin = (maxTime - minTime) / 2 + minTime
        return ''.join([x < margin and 'S' or 'L' for x in times])
    except:
        if not ignore_errors:
            raise

def mangleNec(code, freq=40):
    """Convert NEC code to shorthand notation"""
    timings = []
    for octet in binascii.unhexlify(code.replace(' ', '')):
        burst = lambda x: x and '0226 06AD' or '0226 0258'
        for bit in reversed('%08d' % int(bin(ord(octet))[2:])):
            bit = int(bit)
            timings.append(burst(bit))
    return mangleIR('K %0X22 214d 10b3 ' % freq + ' '.join(timings) + ' 0226 2000')

def authenticated(function):
    """Re-authenticate if session expired."""
    def wrapped(*args):
        """Wrap function."""
        try:
            return function(*args)
        except UPSError:
            _login(*args)
            return function(*args)
    return wrapped

def get_session(username, password, locale=DEFAULT_LOCALE, cookie_path=COOKIE_PATH):
    """Get UPS HTTP session."""
    class UPSAuth(AuthBase):
        """UPS authorization storage."""
        def __init__(self, username, password, locale, cookie_path):
            """Init."""
            self.username = username
            self.password = password
            self.locale = locale
            self.cookie_path = cookie_path
        def __call__(self, r):
            """Call is no-op."""
            return r
    session = requests.session()
    session.auth = UPSAuth(username, password, locale, cookie_path)
    if os.path.exists(cookie_path):
        session.cookies = _load_cookies(cookie_path)
    else:
        _login(session)
    return session

