def _next_rotation_id(rotated_files):
    """Given the hanoi_rotator generated files in the output directory,
    returns the rotation_id that will be given to the current file. If there
    are no existing rotated files, return 0."""
    if not rotated_files:
        return 0
    else:
        highest_rotated_file = max(rotated_files, key=lambda x: x[1])
        return highest_rotated_file[1] + 1

def _locate_files_to_delete(algorithm, rotated_files, next_rotation_id):
    """Looks for hanoi_rotator generated files that occupy the same slot
    that will be given to rotation_id."""
    rotation_slot = algorithm.id_to_slot(next_rotation_id)
    for a_path, a_rotation_id in rotated_files:
        if rotation_slot == algorithm.id_to_slot(a_rotation_id):
            yield a_path

def transmogrify(l):
    """Fit a flat list into a treeable object."""
    d = {l[0]: {}}
    tmp = d
    for c in l:
        tmp[c] = {}
        tmp = tmp[c]
    return d

def get_commands_in_namespace(namespace=None, level=1):
    """Get commands in namespace.

    Args:
        namespace (dict|module): Typically a module. If not passed, the
            globals from the call site will be used.
        level (int): If not called from the global scope, set this
            appropriately to account for the call stack.

    Returns:
        OrderedDict: The commands found in the namespace, ordered by
            name.

    Can be used to create ``__all__`` lists::

        __all__ = list(get_commands_in_namespace())"""
    from ..command import Command
    commands = {}
    if namespace is None:
        frame = inspect.stack()[level][0]
        namespace = frame.f_globals
    elif inspect.ismodule(namespace):
        namespace = vars(namespace)
    for name in namespace:
        obj = namespace[name]
        if isinstance(obj, Command):
            commands[name] = obj
    return OrderedDict(((name, commands[name]) for name in sorted(commands)))

def read_http_header(sock):
    """Read HTTP header from socket, return header and rest of data."""
    buf = []
    hdr_end = '\r\n\r\n'
    while True:
        buf.append(sock.recv(bufsize).decode('utf-8'))
        data = ''.join(buf)
        i = data.find(hdr_end)
        if i == -1:
            continue
        return (data[:i], data[i + len(hdr_end):])

def header_status(header):
    """Parse HTTP status line, return status (int) and reason."""
    status_line = header[:header.find('\r')]
    fields = status_line.split(None, 2)
    return (int(fields[1]), fields[2])

def connect(url):
    """Connect to UNIX or TCP socket.

    url can be either tcp://<host>:port or ipc://<path>"""
    url = urlparse(url)
    if url.scheme == 'tcp':
        sock = socket()
        netloc = tuple(url.netloc.rsplit(':', 1))
        hostname = socket.gethostname()
    elif url.scheme == 'ipc':
        sock = socket(AF_UNIX)
        netloc = url.path
        hostname = 'localhost'
    else:
        raise ValueError('unknown socket type: %s' % url.scheme)
    sock.connect(netloc)
    return (sock, hostname)

def isqrt(n):
    """given a non-negative integer n, return a pair (a,b) such that n = a * a * b
    where b is a square-free integer.

    If n is a perfect square, then a is its square root and b is one."""
    if n == 0:
        return (n, 1)
    if n < 0:
        raise ValueError('math domain error')
    a, b, c = (1, n, 1)
    def divisors():
        yield 2
        yield 3
        k = 5
        while k * k <= b:
            yield k
            k += 2
            yield k
            k += 4
    for k in divisors():
        d, m = divmod(b, k * k)
        while m == 0:
            a *= k
            b = d
            d, m = divmod(b, k * k)
        if b % k == 0:
            b //= k
            c *= k
        k += 1
    return (a, b * c)

def fsqrt(q):
    """given a non-negative fraction q, return a pair (a,b) such that q = a * a * b
    where b is a square-free integer.

    if q is a perfect square, a is its square root and b is one."""
    if q == 0:
        return (q, 1)
    if q < 0:
        raise ValueError('math domain error %s' % q)
    a, b = isqrt(q.numerator)
    c, d = isqrt(q.denominator)
    return (Fraction(a, c * d), b * d)

def sqrt(n):
    """return the square root of n in an exact representation"""
    if isinstance(n, Rational):
        n = Constructible(n)
    elif not isinstance(n, Constructible):
        raise ValueError('the square root is not implemented for the type %s' % type(n))
    r = n._try_sqrt()
    if r is not None:
        return r
    return Constructible(Constructible.lift_rational_field(0, n.field), Constructible.lift_rational_field(1, n.field), (n, n.field))

