def check_tags(repos, tags, ignore_existing=False, fail_fast=False):
    """check if tags already exist in repos"""
    debug('looking for {n} tag(s):'.format(n=len(tags)))
    [debug('  {t}'.format(t=t)) for t in tags]
    debug('in {n} repo(s):'.format(n=len(repos)))
    [debug('  {r}'.format(r=r.full_name)) for r in repos]
    present_tags = {}
    absent_tags = {}
    problems = []
    for r in repos:
        has_tags = find_tags_in_repo(r, tags)
        if has_tags:
            if not ignore_existing:
                yikes = GitTagExistsError('tag(s) {tag} already exists in repos {r}'.format(tag=list(has_tags.keys()), r=r.full_name))
                if fail_fast:
                    raise yikes
                problems.append(yikes)
                error(yikes)
            present_tags[r.full_name] = {'repo': r, 'tags': list(has_tags.values())}
        missing_tags = [x for x in tags if x not in has_tags]
        if missing_tags:
            absent_tags[r.full_name] = {'repo': r, 'need_tags': missing_tags}
    debug(textwrap.dedent('        found:\n          {n_with:>4} repos with tag(s)\n          {n_none:>4} repos with no tag(s)\n          {errors:>4} repos with error(s)        ').format(n_with=len(present_tags), n_none=len(absent_tags), errors=len(problems)))
    return (present_tags, absent_tags, problems)

def import_all_references(arg, kwargs=None):
    """Import all references in the currently open scene

    :param arg: this argument is ignored. But thisway you can use this function in an ActionUnit more easily.
    :param kwargs: keyword arguments for the command maya.cmds file.
                   defaultflags that are always used:

                     :importReference: ``True``

    :type kwargs: dict|None
    :returns: An action status. The returnvalue of the actionstatus are the imported references.
    :rtype: :class:`ActionStatus`
    :raises: None"""
    defaultkwargs = {'importReference': True}
    if kwargs is None:
        kwargs = {}
    kwargs.update(defaultkwargs)
    imported = []
    refs = cmds.file(query=True, reference=True)
    while refs:
        for rfile in refs:
            cmds.file(rfile, **kwargs)
            imported.append(rfile)
        refs = cmds.file(query=True, reference=True)
    msg = 'Successfully imported references %s with arguments: %s' % (imported, kwargs)
    return ActionStatus(ActionStatus.SUCCESS, msg, returnvalue=imported)

def call(args, stdout=PIPE, stderr=PIPE):
    """Calls the given arguments in a seperate process
    and returns the contents of standard out."""
    p = Popen(args, stdout=stdout, stderr=stderr)
    out, err = p.communicate()
    try:
        return (out.decode(sys.stdout.encoding), err.decode(sys.stdout.encoding))
    except Exception:
        return (out, err)

def how_similar_dicts(dict1, dict2):
    """Calculates similarity

    :param dict1: Dictionary
    :param dict2: Dictionary
    :return: measure of how much similar values of dictionaries are"""
    values = []
    for k in dict1:
        if k in dict2 and dict1[k] and dict2[k]:
            values.append(how_similar_are(str(dict1[k]), str(dict2[k])))
    return np.mean(values)

def get_inner_data(dictionary):
    """Gets 2nd-level data into 1st-level dictionary

    :param dictionary: dict
    :return: with 2nd-level data"""
    out = {}
    for key in dictionary.keys():
        inner_keys = dictionary[key].keys()
        for inner_key in inner_keys:
            new_key = key + ' ' + inner_key
            out[new_key] = dictionary[key][inner_key]
    return out

def paths_to_str(paths, format_kwargs={}, delimiter=os.pathsep, asset_paths=False, check_paths=False):
    """Convert ``paths`` to a single string.

    Args:
        paths (str|list): A string like "/a/path:/another/path" or
            a list of paths; may include absolute paths and/or asset
            paths; paths that are relative will be left relative
        format_kwargs (dict): Will be injected into each path
        delimiter (str): The string used to separate paths
        asset_paths (bool): Whether paths that look like asset paths
            will be converted to absolute paths
        check_paths (bool): Whether paths should be checked to ensure
            they exist"""
    if not paths:
        return ''
    if isinstance(paths, str):
        paths = paths.split(delimiter)
    processed_paths = []
    for path in paths:
        original = path
        path = path.format_map(format_kwargs)
        if not os.path.isabs(path):
            if asset_paths and ':' in path:
                try:
                    path = asset_path(path)
                except ValueError:
                    path = None
        if path is not None and os.path.isdir(path):
            processed_paths.append(path)
        elif check_paths:
            f = locals()
            printer.warning('Path does not exist: {path} (from {original})'.format_map(f))
    return delimiter.join(processed_paths)

