def _load_variable(func, program_id, index):
    """Loads the meta data for a uniform or attribute"""
    n = 64
    bufsize = GLsizei(n)
    length = pointer(GLsizei(0))
    size = pointer(GLint(0))
    type = pointer(GLenum(0))
    uname = create_string_buffer(n)
    func(program_id, index, bufsize, length, size, type, uname)
    return (size[0], type[0], uname.value.decode('utf8'))

def get_args(request_args, allowed_int_args=(), allowed_str_args=(), allowed_bool_args=()):
    """Check allowed argument names and return is as dictionary"""
    args = {}
    for allowed_int_arg in allowed_int_args:
        int_value = request_args.get(allowed_int_arg, default=None, type=None)
        if int_value:
            args[allowed_int_arg] = int(int_value)
    for allowed_str_arg in allowed_str_args:
        str_value = request_args.get(allowed_str_arg, default=None, type=None)
        if str_value:
            args[allowed_str_arg] = str_value
    for allowed_bool_arg in allowed_bool_args:
        str_value = request_args.get(allowed_bool_arg, default=None, type=None)
        if str_value == 'true':
            args[allowed_bool_arg] = True
        elif str_value == 'false':
            args[allowed_bool_arg] = False
    return args

def _parse_blocks(instream):
    """Parse an alignment block from the given file handle.

    Block looks like:
    [0_(1)=fa2cma(8){go=10000,gx=2000,pn=1000.0,lf=0,rf=0}:
    (209)***********************************************...

    ... sequences, numbered 1-8 ...

    _0]."""
    ilines = sugar.unblank(instream)
    for line in ilines:
        if line.startswith('['):
            level, one, name, seqcount, params = _parse_block_header(line)
            qlen, qchars = _parse_block_postheader(next(ilines))
            sequences = list(_parse_sequences(ilines, qlen))
            if not len(sequences) == seqcount:
                logging.warn('Expected %d sequences in block %s, found %d', seqcount, name, len(sequences))
            yield {'level': level, 'one': one, 'name': name, 'params': params, 'query_length': qlen, 'query_chars': qchars, 'sequences': sequences}

def _parse_block_postheader(line):
    """(209)**************!*****************!!*************..."""
    parts = line[1:].split(')', 1)
    qlen = int(parts[0])
    if not len(parts[1]) == qlen:
        logging.warn('postheader expected %d-long query, found %d', qlen, len(parts[1]))
    return (qlen, parts[1])

def _parse_seq_preheader(line):
    """$3=227(209):"""
    match = re.match('\\$ (\\d+) = (\\d+) \\( (\\d+) \\):', line, re.VERBOSE)
    if not match:
        raise ValueError('Unparseable header: ' + line)
    index, this_len, query_len = match.groups()
    return map(int, (index, this_len, query_len))

def consensus2block(record, level=0, name=None):
    """Convert a Biopython SeqRecord to a esbglib.cma block.

    Ungapping is handled here."""
    cons_ungap = str(record.seq).replace('-', '').replace('.', '').upper()
    record.seq = cons_ungap
    return dict(level=level, one=1, name=name or record.id, params='go=10000,gx=2000,pn=1000.0,lf=0,rf=0', query_length=len(cons_ungap), query_chars='*' * len(cons_ungap), sequences=[seqrecord2sequence(record, len(cons_ungap), 1)])

def seqrecord2sequence(record, qlen, index):
    """Convert a Biopython SeqRecord to a esbglib.cma block.

    Indels (gaps, casing) must have already been handled in the record."""
    description = record.description.split(' ', 1)[1] if ' ' in record.description else ' '
    return dict(index=index, id=record.id, description=description, dbxrefs={}, phylum='', taxchar='', head_len=None, tail_len=None, head_seq='', tail_seq='', length=len(record.seq) - record.seq.count('-'), seq=str(record.seq))

def get_github_content(repo, path, auth=None):
    """Retrieve text files from a github repo"""
    request = requests.get(file_url.format(repo=repo, path=path), auth=auth)
    if not request.ok:
        print('There is a problem with the request')
        print(file_url.format(repo=repo, path=path))
        print(request.json())
        exit(1)
    if not request.json()['encoding'] == 'base64':
        raise RuntimeError('Unknown Encoding encountered when fetching {} from repo {}: {}'.format(path, repo, request.json()['encoding']))
    return request.json()['content'].decode('base64').decode('utf8')

def collect_reponames():
    """Try to figure out a list of repos to consider by default from the contents of the working directory."""
    reponames = []
    try:
        with open(os.devnull) as devnull:
            remote_data = subprocess.check_output(['git', 'remote', '-v', 'show'], stderr=devnull)
        branches = {}
        for line in remote_data.decode('utf-8').split('\n'):
            if line.strip() == '':
                continue
            remote_match = re_mote.match(line)
            if not remote_match is None:
                branches[remote_match.group(1)] = remote_match.group(5)
        if len(branches) > 0:
            if 'origin' in branches:
                reponames.append(branches['origin'])
            else:
                reponames.append(branches.values()[0])
    except OSError:
        pass
    except subprocess.CalledProcessError:
        pass
    for fname in glob.iglob('*.html'):
        fid = open(fname, 'r', 'utf8')
        fid.readline()
        line = fid.readline()
        match = re.match(repo_marker_re, line)
        if not match is None:
            reponames.append(match.group(1))
        reponames = list(set(reponames))
    return reponames

