def run():
    """List repos and teams"""
    args = parse_args()
    codetools.setup_logging(args.debug)
    global g
    g = pygithub.login_github(token_path=args.token_path, token=args.token)
    if not args.hide:
        args.hide = []
    org = g.get_organization(args.organization)
    try:
        repos = list(org.get_repos())
    except github.RateLimitExceededException:
        raise
    except github.GithubException as e:
        msg = 'error getting repos'
        raise pygithub.CaughtOrganizationError(org, e, msg) from None
    for r in repos:
        try:
            teamnames = [t.name for t in r.get_teams() if t.name not in args.hide]
        except github.RateLimitExceededException:
            raise
        except github.GithubException as e:
            msg = 'error getting teams'
            raise pygithub.CaughtRepositoryError(r, e, msg) from None
        maxt = args.maxt if args.maxt is not None and args.maxt >= 0 else len(teamnames)
        if args.debug:
            print('MAXT=', maxt)
        if args.mint <= len(teamnames) <= maxt:
            print(r.name.ljust(40) + args.delimiter.join(teamnames))

def list_from_args(args):
    """Flatten list of args
    So as to accept either an array
    Or as many arguments
    For example:
    func(['x', 'y'])
    func('x', 'y')"""
    if not args:
        return []
    arg_type = type(args[0])
    is_list = arg_type in LIST_TYPES
    same_type = all([isinstance(arg, arg_type) for arg in args])
    if not same_type:
        raise Exception('Expected uniform arguments of same type !')
    if is_list:
        args_lists = map(list, args)
        flattened_args = sum(args_lists, [])
        return flattened_args
    return list(args)

def subkey(dct, keys):
    """Get an entry from a dict of dicts by the list of keys to 'follow'
    """
    key = keys[0]
    if len(keys) == 1:
        return dct[key]
    return subkey(dct[key], keys[1:])

def find_seq_rec(block, name, case_sensitive=True):
    """Given part of a sequence ID, find the first matching record."""
    if case_sensitive:
        def test(name, rec):
            return name in rec['id']
    else:
        def test(name, rec):
            return name.upper() in rec['id'].upper()
    for rec in block['sequences']:
        if test(name, rec):
            return rec
    raise ValueError('No sequence ID matches %s' % repr(name))

def get_conservation(block):
    """Calculate conservation levels at each consensus position.

    Return a dict of {position: float conservation}"""
    consensus = block['sequences'][0]['seq']
    assert all((c.isupper() for c in consensus)), 'So-called consensus contains indels!'
    cleaned = [[c for c in s['seq'] if not c.islower()] for s in block['sequences'][1:]]
    height = float(len(cleaned))
    for row in cleaned:
        if len(row) != len(consensus):
            raise ValueError("Aligned sequence length (%s) doesn't match consensus (%s)" % (len(row), len(consensus)))
    columns = zip(*cleaned)
    return dict(((idx + 1, columns[idx].count(cons_char) / height) for idx, cons_char in enumerate(consensus)))

def get_inserts(block):
    """Identify the inserts in sequence in a block.

    Inserts are relative to the consensus (theoretically), and identified by
    lowercase letters in the sequence. The returned integer pairs represent the
    insert start and end positions in the full-length sequence, using one-based
    numbering.

    The first sequence of the CMA block is included, though it may just be the
    consensus sequence, which shouldn't have any inserts.

    Output:
        {id1: [(start, end), (start, end), ...], id2: ..., ...}"""
    def find_inserts(seq, head_len):
        """Locate the lowercase regions in a character sequence.

        Yield the insert ranges as tuples using 1-based numbering, shifted by
        head_len."""
        in_insert = False
        curr_start = None
        deletions = 0
        for idx, is_lower in enumerate(map(str.islower, seq)):
            if is_lower:
                if not in_insert:
                    curr_start = head_len + idx + 1 - deletions
                    in_insert = True
            else:
                if in_insert:
                    yield (curr_start, head_len + idx - deletions)
                    in_insert = False
                if seq[idx] == '-':
                    deletions += 1
    return dict(((record['id'], list(find_inserts(record['seq'], record['head_len']))) for record in block['sequences']))

def number_letters(block_or_record, key=None):
    """Return a dict of {posn: restype} for each letter in the sequence."""
    if key:
        logging.warn('DEPRECATED: Pass a record instead')
        assert 'sequences' in block_or_record, 'Expected a block and a key'
        record = find_seq_rec(block_or_record, key)
    else:
        assert 'id' in block_or_record, 'Expected argument to be a record'
        record = block_or_record
    seq = record['seq'].replace('-', '').replace('.', '')
    shift = record['head_len'] + 1
    return dict(((idx + shift, letter) for idx, letter in enumerate(seq)))

def remove_path_segments(segments, removes):
    """Removes the removes from the tail of segments.

    Examples::
        >>> # '/a/b/c' - 'b/c' == '/a/'
        >>> assert remove_path_segments(['', 'a', 'b', 'c'], ['b', 'c']) == ['', 'a', '']
        >>> # '/a/b/c' - '/b/c' == '/a
        >>> assert remove_path_segments(['', 'a', 'b', 'c'], ['', 'b', 'c']) == ['', 'a']

    :param segments:  :class:`list`, a list of the path segment
    :param removes:  :class:`list`, a list of the path segment
    :return:  :class:`list`, The list of all remaining path segments after all segments
        in ``removes`` have been removed from the end of ``segments``. If no segment
        from ``removes`` were removed from the ``segments``, the ``segments`` is
        return unmodified."""
    if segments == ['']:
        segments.append('')
    if removes == ['']:
        removes.append('')
    if segments == removes:
        ret = []
    elif len(removes) > len(segments):
        ret = segments
    else:
        removes2 = list(removes)
        if len(removes) > 1 and removes[0] == '':
            removes2.pop(0)
        if removes2 and removes2 == segments[-1 * len(removes2):]:
            ret = segments[:len(segments) - len(removes2)]
            if removes[0] != '' and ret:
                ret.append('')
        else:
            ret = segments
    return ret

def _get_parts_list(to_go, so_far=[[]], ticker=None):
    """Iterates over to_go, building the list of parts. To provide
    items for the beginning, use so_far."""
    try:
        part = to_go.pop(0)
    except IndexError:
        return (so_far, ticker)
    if isinstance(part, list) and any((isinstance(e, list) for e in part)):
        while len(part) > 0:
            so_far, ticker = _get_parts_list(part, so_far, ticker)
            ticker.tick()
    elif isinstance(part, list) and any((isinstance(e, Input) for e in part)):
        while len(part) > 0:
            so_far, ticker = _get_parts_list(part, so_far, ticker)
    elif isinstance(part, Input) and part.is_magic:
        inputs = part.eval()
        while len(inputs) > 0:
            so_far, ticker = _get_parts_list(inputs, so_far, ticker)
            ticker.tick()
    elif isinstance(part, Input) and (not part.is_magic):
        so_far[ticker.value].append(part)
    else:
        so_far = _append(so_far, part)
    return (so_far, ticker)

def _get_max_size(parts, size=1):
    """Given a list of parts, find the maximum number of commands
    contained in it."""
    max_group_size = 0
    for part in parts:
        if isinstance(part, list):
            group_size = 0
            for input_group in part:
                group_size += 1
            if group_size > max_group_size:
                max_group_size = group_size
    magic_size = _get_magic_size(parts)
    return max_group_size * magic_size

def _search_for_files(parts):
    """Given a list of parts, return all of the nested file parts."""
    file_parts = []
    for part in parts:
        if isinstance(part, list):
            file_parts.extend(_search_for_files(part))
        elif isinstance(part, FileToken):
            file_parts.append(part)
    return file_parts

