def true_false_returns(func):
    """Executes function, if error returns False, else True

    :param func: function to call
    :return: True iff ok, else False"""
    @functools.wraps(func)
    def _execute(*args, **kwargs):
        """Executes function, if error returns False, else True

        :param args: args of function
        :param kwargs: extra args of function
        :param *args: args
        :param **kwargs: extra args
        :return: True iff ok, else False"""
        try:
            func(*args, **kwargs)
            return True
        except:
            return False
    return _execute

def none_returns(func):
    """Executes function, if error returns None else value of function

    :param func: function to call
    :return: None else value of function"""
    @functools.wraps(func)
    def _execute(*args, **kwargs):
        """Executes function, if error returns None else value of function

        :param args: args of function
        :param kwargs: extra args of function
        :param *args: args
        :param **kwargs: extra args
        :return: None else value of function"""
        try:
            return func(*args, **kwargs)
        except:
            return None
    return _execute

def assert_variable_type(variable, expected_type, raise_exception=True):
    """Return True if a variable is of a certain type or types.
    Otherwise raise a ValueError exception.

    Positional arguments:
    variable -- the variable to be checked
    expected_type -- the expected type or types of the variable
    raise_exception -- whether to raise an exception or just return
                        False on failure, with error message"""
    if not isinstance(expected_type, list):
        expected_type = [expected_type]
    for t in expected_type:
        if not isinstance(t, type):
            raise ValueError('expected_type argument "%s" is not a type' % str(t))
    if not isinstance(raise_exception, bool):
        raise ValueError('raise_exception argument "%s" is not a bool' % str(raise_exception))
    if not len([t for t in expected_type if isinstance(variable, t)]):
        error_message = '"%s" is not an instance of type %s. It is of type %s' % (str(variable), ' or '.join([str(t) for t in expected_type]), str(type(variable)))
        if raise_exception:
            raise ValueError(error_message)
        else:
            return (False, error_message)
    return (True, None)

def load_object(obj) -> object:
    """Load an object.

    Args:
        obj (str|object): Load the indicated object if this is a string;
            otherwise, return the object as is.

            To load a module, pass a dotted path like 'package.module';
            to load an an object from a module pass a path like
            'package.module:name'.

    Returns:
        object"""
    if isinstance(obj, str):
        if ':' in obj:
            module_name, obj_name = obj.split(':')
            if not module_name:
                module_name = '.'
        else:
            module_name = obj
        obj = importlib.import_module(module_name)
        if obj_name:
            attrs = obj_name.split('.')
            for attr in attrs:
                obj = getattr(obj, attr)
    return obj

def fix_raw_path(path):
    """Prettify name of path

    :param path: path to fix
    :return: Good name for path"""
    double_path_separator = PATH_SEPARATOR + PATH_SEPARATOR
    while path.find(double_path_separator) >= 0:
        path = path.replace(double_path_separator, PATH_SEPARATOR)
    if is_folder(path) and (not path.endswith('/')):
        path = path + '/'
    return path

def remove_year(name):
    """Removes year from input

    :param name: path to edit
    :return: inputs with no years"""
    for i in range(len(name) - 3):
        if name[i:i + 4].isdigit():
            name = name[:i] + name[i + 4:]
            return remove_year(name)
    return name

def prettify(name, blank=' '):
    """Prettify name of path

    :param name: path Name: to edit
    :param blank: default blanks in name
    :return: Prettier name from given one: replace bad chars with good ones"""
    if name.startswith('.'):
        name = name[1:]
    for bad_char in BAD_CHARS:
        name = name.replace(bad_char, blank)
    name = String(name).remove_all(blank)
    for i in range(1, len(name) - 2):
        try:
            are_blanks = name[i - 1] == blank and name[i + 1] == blank
            if are_blanks and name[i] in BAD_CHARS:
                name = name[:i - 1] + name[i + 2:]
        except:
            pass
    if name.startswith(blank):
        name = name[1:]
    if name.endswith(blank):
        name = name[:-1]
    return name

def ls_dir(path, include_hidden=False):
    """Finds content of folder

    :param path: directory to get list of files and folders
    :param include_hidden: True iff include hidden files in list
    :return: List of paths in given directory"""
    lst = []
    for file in os.listdir(path):
        hidden_file = FileSystem(file).is_hidden()
        if hidden_file and include_hidden or not hidden_file:
            lst.append(os.path.join(path, file))
    return list(set(lst))

def ls_recurse(path, include_hidden=False):
    """Finds content of folder recursively

    :param path: directory to get list of files and folders
    :param include_hidden: True iff include hidden files in list
    :return: List of paths in given directory recursively"""
    lst = []
    for file in os.listdir(path):
        hidden_file = FileSystem(file).is_hidden()
        if hidden_file and include_hidden or not hidden_file:
            lst.append(os.path.join(path, file))
            if is_folder(os.path.join(path, file)):
                lst += ls_recurse(os.path.join(path, file), include_hidden=include_hidden)
    return list(set(lst))

def list_content(path, recurse, include_hidden=False):
    """Finds content of folder (recursively)

    :param path: directory to get list of files and folders
    :param recurse: True iff recurse into subdirectories or not
    :param include_hidden: True iff include hidden files in list
    :return: List of paths in given directory recursively"""
    if recurse:
        return ls_recurse(path, include_hidden=include_hidden)
    return ls_dir(path, include_hidden=include_hidden)

def _get_modules(path):
    """Finds modules in folder recursively

    :param path: directory
    :return: list of modules"""
    lst = []
    folder_contents = os.listdir(path)
    is_python_module = '__init__.py' in folder_contents
    if is_python_module:
        for file in folder_contents:
            full_path = os.path.join(path, file)
            if is_file(full_path):
                lst.append(full_path)
            if is_folder(full_path):
                lst += _get_modules(full_path)
    return list(set(lst))

