def autorun(func, _depth=1):
    """Runs the function if the module in which it is declared is being run
    directly from the commandline. Putting the following after the function
    definition would be similar:

    if __name__ == '__main__':
        func()

    NOTE: This will work most expectedly as the outermost decorator, as it
    will call the function before any more outwards decorators have been
    applied."""
    frame_local = sys._getframe(_depth).f_locals
    if '__name__' in frame_local and frame_local['__name__'] == '__main__':
        func(argv=sys.argv[1:])
    return func

def quote(text):
    """Handle quote characters"""
    if not isinstance(text, unicode):
        text = text.decode('utf-8')
    for qp in QUOTEPAIRS:
        if text[0] == qp[0] and text[-1] == qp[-1] and (len(text) >= 2):
            return text
    for qp in QUOTEPAIRS:
        if qp[1] not in text:
            return qp[0] + text + qp[1]
    raise ValueError(u'The value "%s" is not quoted and contains too many quote characters to quote' % text)

def _auto_init(self, *args, **kwrds):
    """Our decorator will add this as __init__ to target classes."""
    for fld in getattr(self, '__fields__', []):
        val = kwrds.get(fld.name, _NO_VAL)
        if val is _NO_VAL:
            val = fld.get_default_val()
        setattr(self, fld.name, val)
    if callable(getattr(self, 'setup', None)):
        self.setup(*args, **kwrds)

def ctor_overridable(cls):
    """Return true if cls has on overridable __init__."""
    prev_init = getattr(cls, '__init__', None)
    if not callable(prev_init):
        return True
    if prev_init in [object.__init__, _auto_init]:
        return True
    if getattr(prev_init, '_clobber_ok', False):
        return True
    print(cls, prev_init, getattr(prev_init, '_clobber_ok', 'missing'))
    return False

def raise_error(error):
    """Intakes a dict of remote error information and raises a DashiError
    """
    exc_type = error.get('exc_type')
    if exc_type and exc_type.startswith(ERROR_PREFIX):
        exc_type = exc_type[len(ERROR_PREFIX):]
        exc_cls = ERROR_TYPE_MAP.get(exc_type, DashiError)
    else:
        exc_cls = DashiError
    raise exc_cls(**error)

def re_tab(s):
    """Return a tabbed string from an expanded one."""
    l = []
    p = 0
    for i in range(8, len(s), 8):
        if s[i - 2:i] == '  ':
            l.append(s[p:i].rstrip() + '\t')
            p = i
    if p == 0:
        return s
    else:
        l.append(s[p:])
        return ''.join(l)

