def item_lister(command, _connection, page_size, page_number, sort_by, sort_order, item_class, result_set, **kwargs):
    """A generator function for listing Video and Playlist objects."""
    page = page_number
    while True:
        item_collection = _connection.get_list(command, page_size=page_size, page_number=page, sort_by=sort_by, sort_order=sort_order, item_class=item_class, **kwargs)
        result_set.total_count = item_collection.total_count
        result_set.page_number = page
        for item in item_collection.items:
            yield item
        if item_collection.total_count < 0 or item_collection.page_size == 0:
            break
        if len(item_collection.items) > 0:
            page += 1
        else:
            break

def parse_now_field(s):
    """Return a datetime instance from a string generated by now_field.
    IMPORTANT: the datetime will be in UTC"""
    if not s.startswith('UTC:'):
        return None
    s = s[4:]
    try:
        dt = datetime.datetime.strptime(s, '%Y-%m-%dT%H:%M:%S.%f')
    except ValueError:
        dt = datetime.datetime.strptime(s, '%Y-%m-%dT%H:%M:%S')
    return dt

def hook(name=None, *args, **kwargs):
