def try_parse_num_and_booleans(num_str):
    """Tries to parse the provided string as a number or boolean
    :param num_str:
    :return:"""
    if isinstance(num_str, str):
        if num_str.lower() == 'true':
            return True
        elif num_str.lower() == 'false':
            return False
        if num_str.isdigit():
            return int(num_str)
        try:
            return float(num_str)
        except ValueError:
            return num_str
    else:
        return num_str

def read_dict_from_properties(desired_type: Type[dict], file_object: TextIOBase, logger: Logger, conversion_finder: ConversionFinder, **kwargs) -> Dict[str, Any]:
    """Helper method to read a dictionary from a .properties file (java-style) using jprops.
    Since jprops does not provide automatic handling for boolean and numbers, this tries to add the feature.

    :param file_object:
    :return:"""
    class Unicoder:
        def __init__(self, file_object):
            self.f = file_object
        def __iter__(self):
            return self
        def __next__(self):
            line = self.f.__next__()
            return line.encode(encoding='utf-8')
    res = jprops.load_properties(Unicoder(file_object))
    res = {key: try_parse_num_and_booleans(val) for key, val in res.items()}
    return ConversionFinder.convert_collection_values_according_to_pep(res, desired_type, conversion_finder, logger, **kwargs)

