            penStore.createNote(major, minor)
            penStore.openNote(major, minor)
    else:
        puts('No list of that name.')

def restclient_admin_required(view_func):
    """View decorator that checks whether the user is permitted to view proxy
    restclients. Calls login_required in case the user is not authenticated."""
    def wrapper(request, *args, **kwargs):
        template = 'access_denied.html'
        if hasattr(settings, 'RESTCLIENTS_ADMIN_AUTH_MODULE'):
            auth_func = import_string(settings.RESTCLIENTS_ADMIN_AUTH_MODULE)
        else:
            context = {'error_msg': 'Your application must define an authorization function as RESTCLIENTS_ADMIN_AUTH_MODULE in settings.py.'}
            return render(request, template, context=context, status=401)
        service = args[0] if len(args) > 0 else None
        url = args[1] if len(args) > 1 else None
        if auth_func(request, service, url):
            return view_func(request, *args, **kwargs)
        return render(request, template, status=401)
    return login_required(function=wrapper)

def open_file(filepath):
    """Open file with the default system app.
    Copied from https://stackoverflow.com/a/435669/1224456"""
    if sys.platform.startswith('darwin'):
        subprocess.Popen(('open', filepath))
    elif os.name == 'nt':
        os.startfile(filepath)
    elif os.name == 'posix':
        subprocess.Popen(('xdg-open', filepath))

def destination_heuristic(data):
    """A heuristic to get the folder with all other files from bib, using majority
    vote."""
    counter = collections.Counter()
    for entry in data:
        file_field = entry['fields'].get('file')
        if not file_field:
            continue
        path = os.path.dirname(file_field)
        counter[path] += 1
    if not counter:
        raise click.ClickException('Path finding heuristics failed: no paths in the database')
    sorted_paths = sorted(counter, reverse=True)
    groupby = itertools.groupby(sorted_paths, key=len)
    _, group = next(groupby)
    candidate = next(group)
    try:
        next(group)
    except StopIteration:
        return candidate
    else:
        raise click.ClickException('Path finding heuristics failed: there are multiple equally valid paths in the database')

def remove_entry(data, entry):
    """Remove an entry in place."""
    file_field = entry['fields'].get('file')
    if file_field:
        try:
            os.remove(file_field)
        except IOError:
            click.echo("This entry's file was missing")
    data.remove(entry)

def string_to_basename(s):
    """Converts to lowercase, removes non-alpha characters,
    and converts spaces to hyphens."""
    s = s.strip().lower()
    s = re.sub('[^\\w\\s-]', '', s)
    return re.sub('[\\s-]+', '-', s)

def _parse_argv(argv=copy(sys.argv)):
    """return argv as a parsed dictionary, looks like the following:

    app --option1 likethis --option2 likethat --flag

    ->

    {'option1': 'likethis', 'option2': 'likethat', 'flag': True}"""
    cfg = DotDict()
    cfg_files = []
    argv = argv[1:]
    while argv:
        arg = argv.pop(0)
        key_val = re.split('=| ', arg)
        arg = key_val[0]
        try:
            val = key_val[1]
        except IndexError:
            if len(argv) > 0 and argv[0][0] != '-':
                val = argv.pop(0)
            else:
                val = None
        if arg[0] == '-':
            key = arg.lstrip('-')
            if not val:
                val = True
            new_cfg = _dict_from_dotted(key, val)
            cfg = dict_merge(cfg, new_cfg)
        elif arg.endswith('.yml'):
            cfg_files.append(arg)
    return (cfg, cfg_files)

def get_logger(name, CFG=None):
    """set up logging for a service using the py 2.7 dictConfig
    """
    logger = logging.getLogger(name)
    if CFG:
        for handler in CFG.get('handlers', {}).itervalues():
            if 'filename' in handler:
                log_dir = os.path.dirname(handler['filename'])
                if not os.path.exists(log_dir):
                    os.makedirs(log_dir)
        try:
            logging.config.dictConfig(CFG)
        except AttributeError:
            (print >> sys.stderr, '"logging.config.dictConfig" doesn\'t seem to be supported in your python')
            raise
    return logger

def exec_before_request_actions(actions, **kwargs):
    """Execute actions in the "before" and "before_METHOD" groups
    """
    groups = ('before', 'before_' + flask.request.method.lower())
    return execute_actions(actions, limit_groups=groups, **kwargs)

def exec_after_request_actions(actions, response, **kwargs):
    """Executes actions of the "after" and "after_METHOD" groups.
    A "response" var will be injected in the current context."""
    current_context['response'] = response
    groups = ('after_' + flask.request.method.lower(), 'after')
    try:
        rv = execute_actions(actions, limit_groups=groups, **kwargs)
    except ReturnValueException as e:
        rv = e.value
    if rv:
        return rv
    return response

def full_exec_request_actions(actions, func=None, render_func=None):
    """Full process to execute before, during and after actions.
    If func is specified, it will be called after exec_request_actions()
    unless a ContextExitException was raised. If render_func is specified,
    it will be called after exec_request_actions() only if there is no
    response. exec_after_request_actions() is always called."""
    response = None
    try:
        exec_before_request_actions(actions, catch_context_exit=False)
        exec_request_actions(actions, catch_context_exit=False)
        if func:
            response = func()
    except ContextExitException as e:
        response = e.result
    except ReturnValueException as e:
        response = e.value
    if render_func and response is None:
        response = render_func()
    return exec_after_request_actions(actions, response)

def as_view(url=None, methods=None, view_class=ActionsView, name=None, url_rules=None, **kwargs):
    """Decorator to transform a function into a view class. Be warned that this will replace
    the function with the view class."""
    def decorator(f):
        if url is not None:
            f = expose(url, methods=methods)(f)
        clsdict = {'name': name or f.__name__, 'actions': getattr(f, 'actions', None), 'url_rules': url_rules or getattr(f, 'urls', None)}
        if isinstance(f, WithActionsDecorator):
            f = f.func
        clsdict['func'] = f
        def constructor(self, **ctorkwargs):
            for k, v in kwargs.items():
                if k not in ctorkwargs or ctorkwargs[k] is None:
                    ctorkwargs[k] = v
            view_class.__init__(self, func=f, **ctorkwargs)
        clsdict['__init__'] = constructor
        return type(f.__name__, (view_class,), clsdict)
    return decorator

def read_df_or_series_from_csv(desired_type: Type[pd.DataFrame], file_path: str, encoding: str, logger: Logger, **kwargs) -> pd.DataFrame:
    """Helper method to read a dataframe from a csv file. By default this is well suited for a dataframe with
    headers in the first row, for example a parameter dataframe.

    :param desired_type:
    :param file_path:
    :param encoding:
    :param logger:
    :param kwargs:
    :return:"""
    if desired_type is pd.Series:
        if 'index_col' not in kwargs.keys():
            one_col_df = pd.read_csv(file_path, encoding=encoding, index_col=0, **kwargs)
        else:
            one_col_df = pd.read_csv(file_path, encoding=encoding, **kwargs)
        if one_col_df.shape[1] == 1:
            return one_col_df[one_col_df.columns[0]]
        else:
            raise Exception('Cannot build a series from this csv: it has more than two columns (one index + one value). Probably the parsing chain $read_df_or_series_from_csv => single_row_or_col_df_to_series$will work, though.')
    else:
        return pd.read_csv(file_path, encoding=encoding, **kwargs)

def single_row_or_col_df_to_dict(desired_type: Type[T], single_rowcol_df: pd.DataFrame, logger: Logger, **kwargs) -> Dict[str, str]:
    """Helper method to convert a dataframe with one row or one or two columns into a dictionary

    :param desired_type:
    :param single_rowcol_df:
    :param logger:
    :param kwargs:
    :return:"""
    if single_rowcol_df.shape[0] == 1:
        return single_rowcol_df.transpose()[0].to_dict()
    elif single_rowcol_df.shape[1] == 2 and isinstance(single_rowcol_df.index, pd.RangeIndex):
        d = single_rowcol_df.set_index(single_rowcol_df.columns[0])
        return d[d.columns[0]].to_dict()
    elif single_rowcol_df.shape[1] == 1:
        d = single_rowcol_df
        return d[d.columns[0]].to_dict()
    else:
        raise ValueError('Unable to convert provided dataframe to a parameters dictionary : expected exactly 1 row or 1 column, found : ' + str(single_rowcol_df.shape) + '')

def clacks_overhead(fn):
    """A Django view decorator that will add the `X-Clacks-Overhead` header.

    Usage:

        @clacks_overhead
        def my_view(request):
            return my_response"""
    @wraps(fn)
    def _wrapped(*args, **kw):
        response = fn(*args, **kw)
        response['X-Clacks-Overhead'] = 'GNU Terry Pratchett'
        return response
    return _wrapped

def objects_reachable_from(obj):
    """Return graph of objects reachable from *obj* via ``gc.get_referrers``.

    Returns an :class:`~refcycle.object_graph.ObjectGraph` object holding all
    objects reachable from the given one by following the output of
    ``gc.get_referrers``.  Note that unlike the
    :func:`~refcycle.creators.snapshot` function, the output graph may
    include non-gc-tracked objects."""
    found = ObjectGraph.vertex_set()
    to_process = [obj]
    while to_process:
        obj = to_process.pop()
        found.add(obj)
        for referent in gc.get_referents(obj):
            if referent not in found:
                to_process.append(referent)
    return ObjectGraph(found)

def run(paths, output=_I_STILL_HATE_EVERYTHING, recurse=core.flat, sort_by=None, ls=core.ls, stdout=stdout):
    """Project-oriented directory and file information lister."""
    if output is _I_STILL_HATE_EVERYTHING:
        output = core.columnized if stdout.isatty() else core.one_per_line
    if sort_by is None:
        if output == core.as_tree:
            def sort_by(thing):
                return (thing.parent(), thing.basename().lstrip(string.punctuation).lower())
        else:
            def sort_by(thing):
                return thing
    def _sort_by(thing):
        return (not getattr(thing, '_always_sorts_first', False), sort_by(thing))
    contents = [path_and_children for path in paths or (project.from_path(FilePath('.')),) for path_and_children in recurse(path=path, ls=ls)]
    for line in output(contents, sort_by=_sort_by):
        stdout.write(line)
        stdout.write('\n')

