def listens_to(name, sender=None, weak=True):
    """Listens to a named signal
    """
    def decorator(f):
        if sender:
            return signal(name).connect(f, sender=sender, weak=weak)
        return signal(name).connect(f, weak=weak)
    return decorator

def prompt(prompt_string, default=None, secret=False, boolean=False, bool_type=None):
    """Prompt user for a string, with a default value

    * secret converts to password prompt
    * boolean converts return value to boolean, checking for starting with a Y"""
    if boolean or bool_type in BOOLEAN_DEFAULTS:
        if bool_type is None:
            bool_type = 'y_n'
        default_msg = BOOLEAN_DEFAULTS[bool_type][is_affirmative(default)]
    else:
        default_msg = ' (default {val}): '
    prompt_string += default_msg.format(val=default) if default else ': '
    if secret:
        val = getpass(prompt_string)
    else:
        val = input(prompt_string)
    val = val if val else default
    if boolean:
        val = val.lower().startswith('y')
    return val

def jtosparse(j):
    """Generate sparse matrix coordinates from 3-D Jacobian."""
    data = j.flatten().tolist()
    nobs, nf, nargs = j.shape
    indices = zip(*[(r, c) for n in xrange(nobs) for r in xrange(n * nf, (n + 1) * nf) for c in xrange(n * nargs, (n + 1) * nargs)])
    return csr_matrix((data, indices), shape=(nobs * nf, nobs * nargs))

def parse_datetime(time_str):
    """Wraps dateutil's parser function to set an explicit UTC timezone, and
    to make sure microseconds are 0. Unified Uploader format and EMK format
    bother don't use microseconds at all.

    :param str time_str: The date/time str to parse.
    :rtype: datetime.datetime
    :returns: A parsed, UTC datetime."""
    try:
        return dateutil.parser.parse(time_str).replace(microsecond=0).astimezone(UTC_TZINFO)
    except ValueError:
        raise ParseError('Invalid time string: %s' % time_str)

def desc(t=None, reg=True):
    """Describe Class Dependency

    :param reg: should we register this class as well
    :param t: custom type as well
    :return:"""
    def decorated_fn(cls):
        if not inspect.isclass(cls):
            return NotImplemented('For now we can only describe classes')
        name = t or camel_case_to_underscore(cls.__name__)[0]
        if reg:
            di.injector.register(name, cls)
        else:
            di.injector.describe(name, cls)
        return cls
    return decorated_fn

def raise_status(response):
    """Raise an exception if the request did not return a status code of 200.

    :param response: Request response body"""
    if response.status != 200:
        if response.status == 401:
            raise StrawPollException('Unauthorized', response)
        elif response.status == 403:
            raise StrawPollException('Forbidden', response)
        elif response.status == 404:
            raise StrawPollException('Not Found', response)
        else:
            response.raise_for_status()

