def _extractFastaHeader(fastaHeader, parser=None, forceId=False):
    """Parses a fasta header and returns extracted information in a dictionary.

    Unless a custom parser is specified, a ``Pyteomics`` function is used, which
    provides parsers for the formats of UniProtKB, UniRef, UniParc and  UniMES
    (UniProt Metagenomic and Environmental Sequences), described at
    `www.uniprot.org <http://www.uniprot.org/help/fasta-headers>_`.

    :param fastaHeader: str, protein entry header from a fasta file
    :param parser: is a function that takes a fastaHeader string and returns a
        dictionary, containing at least the key "id". If None the parser
        function from pyteomics ``pyteomics.fasta.parse()`` is used.
    :param forceId: bool, if True and no id can be extracted from the fasta
        header the whole header sequence is used as a protein id instead of
        raising an exception.

    :returns: dict, describing a fasta header"""
    if parser is None:
        try:
            headerInfo = pyteomics.fasta.parse(fastaHeader)
        except pyteomics.auxiliary.PyteomicsError as pyteomicsError:
            if forceId:
                headerInfo = {'id': fastaHeader}
            else:
                raise pyteomicsError
    else:
        headerInfo = parser(fastaHeader)
    return headerInfo

def fetch_keywords(codedata):
    """Fetch keywords by shaman.KeywordFetcher
    Get average probabilities of keyword and language"""
    tmp = {}
    language_counts = {}
    for index, (language, code) in enumerate(codedata):
        if language not in shaman.SUPPORTING_LANGUAGES:
            continue
        if language not in tmp:
            tmp[language] = {}
            language_counts[language] = 0
        language_counts[language] += 1
        for keyword in shaman.KeywordFetcher.fetch(code):
            tmp[language][keyword] = tmp[language].get(keyword, 0) + 1
        print('Fetch keyword %d/%d    ' % (index, len(codedata)), end='\r')
    ret = {}
    for language in tmp:
        for keyword, count in tmp[language].items():
            if keyword not in ret:
                ret[keyword] = {}
            ret[keyword][language] = count / language_counts[language]
    print('Fetch keyword completed        ')
    return ret

def match_patterns(codedata):
    """Match patterns by shaman.PatternMatcher
    Get average ratio of pattern and language"""
    ret = {}
    for index1, pattern in enumerate(shaman.PatternMatcher.PATTERNS):
        print('Matching pattern %d "%s"' % (index1 + 1, pattern))
        matcher = shaman.PatternMatcher(pattern)
        tmp = {}
        for index2, (language, code) in enumerate(codedata):
            if language not in shaman.SUPPORTING_LANGUAGES:
                continue
            if len(code) <= 20 or len(code) > 100000:
                continue
            if language not in tmp:
                tmp[language] = []
            ratio = matcher.getratio(code)
            tmp[language].append(ratio)
            print('Matching patterns %d/%d    ' % (index2, len(codedata)), end='\r')
        ret[pattern] = {}
        for language, data in tmp.items():
            ret[pattern][language] = sum(tmp[language]) / max(len(tmp[language]), 1)
    print('Matching patterns completed          ')
    return ret

def call(function):
    """decorator that collect function call count."""
    message = 'call:%s.%s' % (function.__module__, function.__name__)
    @functools.wraps(function)
    def wrapper(*args, **kwargs):
        _collect(message)
        return function(*args, **kwargs)
    return wrapper

def forceutc(t: Union[str, datetime.datetime, datetime.date, np.datetime64]) -> Union[datetime.datetime, datetime.date]:
    """Add UTC to datetime-naive and convert to UTC for datetime aware

    input: python datetime (naive, utc, non-utc) or Numpy datetime64  #FIXME add Pandas and AstroPy time classes
    output: utc datetime"""
    if isinstance(t, str):
        t = parse(t)
    elif isinstance(t, np.datetime64):
        t = t.astype(datetime.datetime)
    elif isinstance(t, datetime.datetime):
        pass
    elif isinstance(t, datetime.date):
        return t
    elif isinstance(t, (np.ndarray, list, tuple)):
        return np.asarray([forceutc(T) for T in t])
    else:
        raise TypeError('datetime only input')
    if t.tzinfo is None:
        t = t.replace(tzinfo=UTC)
    else:
        t = t.astimezone(UTC)
    return t

def get_file_list(path, max_depth=1, cur_depth=0):
    """Recursively returns a list of all files up to ``max_depth``
    in a directory."""
    if os.path.exists(path):
        for name in os.listdir(path):
            if name.startswith('.'):
                continue
            full_path = os.path.join(path, name)
            if os.path.isdir(full_path):
                if cur_depth == max_depth:
                    continue
                file_list = get_file_list(full_path, max_depth, cur_depth + 1)
                for result in file_list:
                    yield result
            else:
                yield full_path

def get_applied_migrations(databases=None):
    """Returns a dictionary containing lists of all applied migrations
    where the key is the database alias."""
    if not databases:
        databases = get_capable_databases()
    else:
        all_databases = list(get_capable_databases())
        databases = list(itertools.ifilter(lambda x: x in all_databases, databases))
    results = defaultdict(list)
    for db in databases:
        for x in Migration.objects.using(db).order_by('migration_label'):
            results[db].append(x.migration_label)
    return results

def get_pending_migrations(path, databases=None, stop_at=None):
    """Returns a dictionary of database => [migrations] representing all pending
    migrations."""
    if stop_at is None:
        stop_at = float('inf')
    possible_migrations = get_all_migrations(path, databases)
    applied_migrations = get_applied_migrations(databases)
    to_execute = defaultdict(list)
    for database, scripts in possible_migrations.iteritems():
        applied = applied_migrations[database]
        pending = to_execute[database]
        for number, migration in scripts:
            path, script = os.path.split(migration)
            if script not in applied and number <= stop_at:
                pending.append(script)
    return dict(((k, v) for k, v in to_execute.iteritems() if v))

def updateFgiAnnotationFromFi(fgiContainer, fiContainer, largerBetter):
    """#TODO: docstring

    :param fgiContainer:
    :param fiContainer:
    :param largerBetter:"""
    for fgi in listvalues(fgiContainer.container):
        annotations = list()
        for specfile, fiId in zip(fgi.specfiles, fgi.featureIds):
            fi = fiContainer.getItem(specfile, fiId)
            if not fi.isAnnotated:
                continue
            annotations.append([fi.score, fi.peptide, fi.sequence])
        annotations.sort(reverse=largerBetter)
        if len(annotations) > 0:
            fgi.isAnnotated = True
            fgi.score = annotations[0][0]
            fgi.peptide = annotations[0][1]
            fgi.sequence = annotations[0][2]
        else:
            fgi.isAnnotated = False

def command(argv, scope):
    """Looks up a particular command from the inputted arguments for the given     scope.

    :param      argv    | [<str>, ..]
                scope   | <dict>

    :return     <climethod> || None"""
    if inspect.ismodule(scope):
        scope = vars(scope)
    for cmd in scope.values():
        if not isinstance(cmd, climethod):
            continue
        if cmd.__name__ in argv:
            return cmd
    return None

def commands(scope):
    """Looks up all climethod instances from the inputted scope.

    :return     [<climethod>, ..]"""
    if inspect.ismodule(scope):
        scope = vars(scope)
    return [cmd for cmd in scope.values() if isinstance(cmd, climethod)]

def plural(formatter, value, name, option, format):
    """Chooses different textension for locale-specific pluralization rules.

    Spec: `{:[p[lural]][(locale)]:msgstr0|msgstr1|...}`

    Example::

       >>> smart.format(u'There {num:is an item|are {} items}.', num=1}
       There is an item.
       >>> smart.format(u'There {num:is an item|are {} items}.', num=10}
       There are 10 items."""
    words = format.split('|')
    if not name and len(words) == 1:
        return
    try:
        number = decimal.Decimal(value)
    except (ValueError, decimal.InvalidOperation):
        return
    locale = Locale.parse(option) if option else formatter.locale
    index = get_plural_tag_index(number, locale)
    return formatter.format(words[index], value)

def get_choice(value):
    """Gets a key to choose a choice from any value."""
    if value is None:
        return 'null'
    for attr in ['__name__', 'name']:
        if hasattr(value, attr):
            return getattr(value, attr)
    return str(value)

def _floor_to(dt, hour, minute, second):
    """Route the given datetime to the latest time with the hour, minute, second
    before it."""
    new_dt = dt.replace(hour=hour, minute=minute, second=second)
    if new_dt <= dt:
        return new_dt
    else:
        return new_dt - timedelta(days=1)

def _round_to(dt, hour, minute, second):
    """Route the given datetime to the latest time with the hour, minute, second
    before it."""
    new_dt = dt.replace(hour=hour, minute=minute, second=second)
    if new_dt == dt:
        return new_dt
    elif new_dt < dt:
        before = new_dt
        after = new_dt + timedelta(days=1)
    elif new_dt > dt:
        before = new_dt - timedelta(days=1)
        after = new_dt
    d1 = dt - before
    d2 = after - dt
    if d1 < d2:
        return before
    elif d1 > d2:
        return after
    else:
        return before

def join_css_class(css_class, *additional_css_classes):
    """Returns the union of one or more CSS classes as a space-separated string.
    Note that the order will not be preserved."""
    css_set = set(chain.from_iterable((c.split(' ') for c in [css_class, *additional_css_classes] if c)))
    return ' '.join(css_set)

def return_primitive(fn):
    """Decorator which wraps a single argument function to ignore any
    arguments of primitive type (simply returning them unmodified)."""
    @wraps(fn)
    def wrapped_fn(x):
        if isinstance(x, PRIMITIVE_TYPES):
            return x
        return fn(x)
    return wrapped_fn

def build(path, query=None, fragment=''):
    """Generates a URL based on the inputted path and given query options and
    fragment.  The query should be a dictionary of terms that will be
    generated into the URL, while the fragment is the anchor point within the
    target path that will be navigated to.  If there are any wildcards within
    the path that are found within the query, they will be inserted into the
    path itself and removed from the query string.

    :example    |>>> import skyline.gui
                |>>> skyline.gui.build_url('sky://projects/%(project)s',
                |                          {'project': 'Test', 'asset': 'Bob'})
                |'sky://projects/Test/?asset=Bob'

    :param      path        | <str>
                query       | <dict> || None
                fragment    | <str> || None

    :return     <str> | url"""
    url = nstr(path)
    keys = projex.text.findkeys(path)
    if keys:
        if query is None:
            query = {}
        opts = {}
        for key in keys:
            opts[key] = query.pop(key, '%({})s'.format(key))
        url %= opts
    if query:
        if type(query) is dict:
            mapped_query = {}
            for key, value in query.items():
                mapped_query[nstr(key)] = nstr(value)
            query_str = urllib.urlencode(mapped_query)
        else:
            query_str = nstr(query)
        url += '?' + query_str
    if fragment:
        url += '#' + fragment
    return url

def parse(url):
    """Parses out the information for this url, returning its components
    expanded out to Python objects.

    :param      url | <str>

    :return     (<str> path, <dict> query, <str> fragment)"""
    result = urlparse.urlparse(nstr(url))
    path = result.scheme + '://' + result.netloc
    if result.path:
        path += result.path
    query = {}
    if result.query:
        url_query = urlparse.parse_qs(result.query)
        for key, value in url_query.items():
            if type(value) == list and len(value) == 1:
                value = value[0]
            query[key] = value
    return (path, query, result.fragment)

def _param_deprecation_warning(schema, deprecated, context):
    """Raises warning about using the 'old' names for some parameters.

    The new naming scheme just has two underscores on each end of the word for consistency"""
    for i in deprecated:
        if i in schema:
            msg = 'When matching {ctx}, parameter {word} is deprecated, use __{word}__ instead'
            msg = msg.format(ctx=context, word=i)
            warnings.warn(msg, Warning)

