    """Validate that :func:`auto_decode_and_soupify` is applicable to this
    function. If not applicable, a ``NotImplmentedError`` will be raised."""
    arg_spec = inspect.getargspec(func)
    for arg in ['response', 'html', 'soup']:
        if arg not in arg_spec.args:
            raise NotImplementedError('{func} method has to take the keyword syntax input: {arg}'.format(func=func, arg=arg))

def generateKey(password, bits=32):
    """Generates a new encryption key based on the inputted password.

    :param      password    | <str>
                bits        | <int>  | 16 or 32 bits

    :return     <str>"""
    if bits == 32:
        hasher = hashlib.sha256
    elif bits == 16:
        hasher = hashlib.md5
    else:
        raise StandardError('Invalid hash type')
    return hasher(password).digest()

def generateToken(bits=32):
    """Generates a random token based on the given parameters.

    :return     <str>"""
    if bits == 64:
        hasher = hashlib.sha256
    elif bits == 32:
        hasher = hashlib.md5
    else:
        raise StandardError('Unknown bit level.')
    return hasher(nstr(random.getrandbits(256))).hexdigest()

def get_validator(filter_data):
    """ask every matcher whether it can serve such filter data

    :param filter_data:
    :return:"""
    for matcher_type, m in matchers.items():
        if hasattr(m, 'can_handle') and m.can_handle(filter_data):
            filter_data = m.handle(filter_data)
    return filter_data

def parse_querystring(msg):
