def string_to_general_float(s: str) -> float:
    """Convert a string to corresponding single or double precision scientific number.

    :param s: a string could be '0.1', '1e-5', '1.0D-5', or any other validated number
    :return: a float or raise an error

    .. doctest::

        >>> string_to_general_float('1.0D-5')
        1e-05
        >>> string_to_general_float('1Dx')
        Traceback (most recent call last):
            ...
        ValueError: The string '1Dx' does not corresponds to a double precision number!
        >>> string_to_general_float('.8d234')
        8e+233
        >>> string_to_general_float('0.1')
        0.1"""
    if 'D' in s.upper():
        try:
            return string_to_double_precision_float(s)
        except ValueError:
            raise ValueError("The string '{0}' does not corresponds to a double precision number!".format(s))
    else:
        return float(s)

def _findSubsetProteins(proteins, protToPeps, pepToProts):
    """Find proteins which peptides are a sub-set, but not a same-set to other
    proteins.

    :param proteins: iterable, proteins that are tested for being a subset
    :param pepToProts: dict, for each peptide (=key) contains a set of parent
        proteins (=value). For Example {peptide: {protein, ...}, ...}
    :param protToPeps: dict, for each protein (=key) contains a set of
        associated peptides (=value). For Example {protein: {peptide, ...}, ...}
    :returns: a list of pairs of protein and their superset proteins.
        [(protein, {superset protein, ...}), ...]"""
    proteinsEqual = lambda prot1, prot2: protToPeps[prot1] == protToPeps[prot2]
    subGroups = list()
    for protein in proteins:
        peptideCounts = Counter()
        for peptide in protToPeps[protein]:
            proteins = pepToProts[peptide]
            peptideCounts.update(proteins)
        peptideCount = peptideCounts.pop(protein)
        superGroups = set()
        for sharingProtein, sharedPeptides in peptideCounts.most_common():
            if peptideCount == sharedPeptides:
                if not proteinsEqual(protein, sharingProtein):
                    superGroups.add(sharingProtein)
            else:
                break
        if superGroups:
            subGroups.append((protein, superGroups))
    return subGroups

def _reducedProtToPeps(protToPeps, proteins):
    '''Returns a new, reduced "protToPeps" dictionary that does not contain
    entries present in "proteins".

    :param protToPeps: dict, for each protein (=key) contains a set of
        associated peptides (=value). For Example {protein: {peptide, ...}, ...}
    :param proteins: a list of proteinSet
    :returns: dict, protToPeps not containing entries from "proteins"'''
    return {k: v for k, v in viewitems(protToPeps) if k not in proteins}

def _findUniqueMappingKeys(mapping):
    """Find mapping keys that only have one entry (value length of 1.

    :param mapping: dict, for each key contains a set of entries
    :returns: a set of unique mapping keys"""
    uniqueMappingKeys = set()
    for key, entries in viewitems(mapping):
        if len(entries) == 1:
            uniqueMappingKeys.add(key)
    return uniqueMappingKeys

def _invertMapping(mapping):
    """Converts a protein to peptide or peptide to protein mapping.

    :param mapping: dict, for each key contains a set of entries

    :returns: an inverted mapping that each entry of the values points to a set
        of initial keys."""
    invertedMapping = ddict(set)
    for key, values in viewitems(mapping):
        for value in values:
            invertedMapping[value].add(key)
    return invertedMapping

def _getValueCounts(mapping):
    """Returns a counter object; contains for each key of the mapping the counts
    of the respective value element (= set length).

    :param mapping: dict, for each key contains a set of entries.
    :returns: a counter"""
    return Counter({k: len(v) for k, v in viewitems(mapping)})

def _flattenMergedProteins(proteins):
    """Return a set where merged protein entries in proteins are flattened.

    :param proteins: an iterable of proteins, can contain merged protein entries
        in the form of tuple([protein1, protein2]).
    returns a set of protein entries, where all entries are strings"""
    proteinSet = set()
    for protein in proteins:
        if isinstance(protein, tuple):
            proteinSet.update(protein)
        else:
            proteinSet.add(protein)
    return proteinSet

def recClearTag(element):
    """Applies maspy.xml.clearTag() to the tag attribute of the "element" and
    recursively to all child elements.

    :param element: an :instance:`xml.etree.Element`"""
    children = element.getchildren()
    if len(children) > 0:
        for child in children:
            recClearTag(child)
    element.tag = clearTag(element.tag)

def recRemoveTreeFormating(element):
    """Removes whitespace characters, which are leftovers from previous xml
    formatting.

    :param element: an instance of lxml.etree._Element

    str.strip() is applied to the "text" and the "tail" attribute of the
    element and recursively to all child elements."""
    children = element.getchildren()
    if len(children) > 0:
        for child in children:
            recRemoveTreeFormating(child)
    if element.text is not None:
        if len(element.text.strip()) == 0:
            element.text = None
        else:
            element.text = element.text.strip()
    if element.tail is not None:
        if len(element.tail.strip()) == 0:
            element.tail = None
        else:
            element.tail = element.tail.strip()

def getParam(xmlelement):
    """Converts an mzML xml element to a param tuple.

    :param xmlelement: #TODO docstring

    :returns: a param tuple or False if the xmlelement is not a parameter
        ('userParam', 'cvParam' or 'referenceableParamGroupRef')"""
    elementTag = clearTag(xmlelement.tag)
    if elementTag in ['userParam', 'cvParam', 'referenceableParamGroupRef']:
        if elementTag == 'cvParam':
            param = cvParamFromDict(xmlelement.attrib)
        elif elementTag == 'userParam':
            param = userParamFromDict(xmlelement.attrib)
        else:
            param = refParamGroupFromDict(xmlelement.attrib)
    else:
        param = False
    return param

def extractParams(xmlelement):
    """#TODO docstring

    :param xmlelement: #TODO docstring

    :returns: #TODO docstring"""
    params = list()
    children = list()
    for child in xmlelement.getchildren():
        param = getParam(child)
        if param:
            params.append(param)
        else:
            children.append(child)
    return (params, children)

def interpretBitEncoding(bitEncoding):
    """Returns a floattype string and a numpy array type.

    :param bitEncoding: Must be either '64' or '32'

    :returns: (floattype, numpyType)"""
    if bitEncoding == '64':
        floattype = 'd'
        numpyType = numpy.float64
    elif bitEncoding == '32':
        floattype = 'f'
        numpyType = numpy.float32
    else:
        errorText = ''.join(["bitEncoding '", bitEncoding, "' not defined. ", "Must be '64' or '32'"])
        raise TypeError(errorText)
    return (floattype, numpyType)

def extractBinaries(binaryDataArrayList, arrayLength):
    """#TODO: docstring

    :param binaryDataArrayList: #TODO: docstring
    :param arrayLength: #TODO: docstring

    :returns: #TODO: docstring"""
    extractedArrays = dict()
    arrayInfo = dict()
    for binaryData in binaryDataArrayList:
        if findParam(binaryData['params'], 'MS:1000523') is not None:
