def run_task(task, workspace):
    """Runs the task and updates the workspace with results.

    Parameters
    ----------
    task - dict
        Task Description

    Examples:
    {'task': task_func, 'inputs': ['a', 'b'], 'outputs': 'c'}
    {'task': task_func, 'inputs': '*', 'outputs': '*'}
    {'task': task_func, 'inputs': ['*','a'], 'outputs': 'b'}

    Returns a new workspace with results"""
    data = copy.copy(workspace)
    task = validate_task(task)
    inputs = [input_parser(key, data) for key in task.inputs]
    if inspect.isgeneratorfunction(task.fn):
        data.update(zip(task.outputs, task.fn(*inputs)))
    else:
        results = task.fn(*inputs)
        if task.outputs[0] != '*':
            results = {task.outputs[0]: results}
        elif not isinstance(results, dict):
            raise TypeError('Result should be a dict for output type *')
        data.update(results)
    return data

def oboTermParser(filepath):
    """Read a obo file and yield '[Term]' entries.

    :param filepath: file path of the .obo file

    :yields: lists containing all lines from a obo '[Term]' entry. Lines are not
        processed and still contain the newline character."""
    with io.open(filepath) as openfile:
        lineIter = iter([i.rstrip() for i in openfile.readlines()])
    try:
        line = next(lineIter)
        while line != '[Term]':
            line = next(lineIter)
        header = line
        entryLines = list()
    except StopIteration:
        errorText = 'File does not contain obo "[Term]" entries.'
        raise maspy.errors.FileFormatError(errorText)
    for line in lineIter:
        if not line:
            continue
        if line == '[Term]':
            yield entryLines
            header = line
            entryLines = list()
        else:
            entryLines.append(line)
    if entryLines:
        yield entryLines

