def findmodules(path, recurse=False):
    """Looks up the modules for the given path and returns a list of the
    packages.  If the recurse flag is set to True, then it will look
    through the package recursively.

    :param      path    | <str>
                recurse | <bool>

    :return     ([<str>, ..] modules, [<str>, ..] paths)"""
    output = set()
    roots = set()
    for root, folders, files in os.walk(path):
        for folder in folders:
            pkgpath = os.path.join(root, folder, '__init__.py')
            if os.path.exists(pkgpath):
                output.add(packageFromPath(pkgpath))
        rootpth = packageRootPath(root)
        rootpkg = packageFromPath(root)
        roots.add(rootpth)
        for file_ in files:
            name, ext = os.path.splitext(file_)
            if ext not in ('.py', '.pyo', '.pyc'):
                continue
            if name in ('__init__', '__plugins__'):
                continue
            if rootpkg:
                output.add(rootpkg + '.' + name)
            else:
                output.add(name)
        if not recurse:
            break
    return (list(output), list(roots))

def packageRootPath(path):
    """Returns the root file path that defines a Python package from the inputted
    path.

    :param      path | <str>

    :return     <str>"""
    path = nstr(path)
    if os.path.isfile(path):
        path = os.path.dirname(path)
    parts = os.path.normpath(path).split(os.path.sep)
    package_parts = []
    for i in range(len(parts), 0, -1):
        filename = os.path.sep.join(parts[:i] + ['__init__.py'])
        if not os.path.isfile(filename):
            break
        package_parts.insert(0, parts[i - 1])
    if not package_parts:
        return path
    return os.path.abspath(os.path.sep.join(parts[:-len(package_parts)]))

def packageFromPath(path, includeModule=False):
    """Determines the python package path based on the inputted path.

    :param      path | <str>

    :return     <str>"""
    path = nstr(path)
    module = ''
    if os.path.isfile(path):
        path, fname = os.path.split(path)
        if fname.endswith('.py') and fname != '__init__.py':
            module = fname.split('.')[0]
    parts = os.path.normpath(path).split(os.path.sep)
    package_parts = []
    for i in range(len(parts), 0, -1):
        filename = os.path.sep.join(parts[:i] + ['__init__.py'])
        if not os.path.isfile(filename):
            break
        package_parts.insert(0, parts[i - 1])
    if includeModule and module:
        package_parts.append(module)
    return '.'.join(package_parts)

def _check_values(in_values):
    """Check if values need to be converted before they get mogrify'd
    """
    out_values = []
    for value in in_values:
        out_values.append(value)
    return tuple(out_values)

def probe(path):
    """Probe a repository for its type.

    :param str path: The path of the repository
    :raises UnknownVCSType: if the repository type couldn't be inferred
    :returns str: either ``git``, ``hg``, or ``svn``

    This function employs some heuristics to guess the type of the repository."""
    import os
    from .common import UnknownVCSType
    if os.path.isdir(os.path.join(path, '.git')):
        return 'git'
    elif os.path.isdir(os.path.join(path, '.hg')):
        return 'hg'
    elif os.path.isfile(os.path.join(path, 'config')) and os.path.isdir(os.path.join(path, 'objects')) and os.path.isdir(os.path.join(path, 'refs')) and os.path.isdir(os.path.join(path, 'branches')):
        return 'git'
    elif os.path.isfile(os.path.join(path, 'format')) and os.path.isdir(os.path.join(path, 'conf')) and os.path.isdir(os.path.join(path, 'db')) and os.path.isdir(os.path.join(path, 'locks')):
        return 'svn'
    else:
        raise UnknownVCSType(path)

def addYears(date, years):
    """Returns the new date based on the inputted number of years.

    :param      date  | <datetime.date>
                years | <int>

    :return     <datetime.date>"""
    if type(date).__name__ in ('QDate', 'QDateTime', 'QTime'):
        date = date.toPython()
    return datetime.date(date.year + years, date.month, date.day)

def daysInMonth(date):
    """Returns the number of the days in the month for the given date.  This will
    take into account leap years based on the inputted date's year.

    :param      date | <datetime.date>

    :return     <int>"""
    if type(date).__name__ in ('QDate', 'QDateTime', 'QTime'):
        date = date.toPython()
    month = date.month
    if month == 2 and (not date.year % 4):
        return 29
    return DaysInMonth.get(month, -1)

def daysInYear(date):
    """Returns the number of days in the year for the given date.

    :param      date | <datetime.date> || <int>

    :return     <int>"""
    if type(date).__name__ in ('QDate', 'QDateTime', 'QTime'):
        date = date.toPython()
    if type(date) != int:
        year = date.year
    else:
        year = date
    if not year % 4:
        return 366
    return 365

def displayName(date, options=None, format='%b %d, %Y'):
    """Returns the display name for the inputted date, given the list of options.

    :param      date    | <datetime.date>
                options | <projex.dates.Names>
                format  | <str>

    :return     <str>"""
    if type(date).__name__ in ('QDate', 'QDateTime', 'QTime'):
        date = date.toPython()
    if isinstance(date, datetime.datetime):
        time = ' @ ' + date.strftime('%I:%M%p').strip('0M').lower()
        date = date.date()
    else:
        time = ''
    today = datetime.date.today()
    delta = date - today
    if delta.days == 0:
        return 'Today' + time
    elif delta.days == -1:
        return 'Yesterday' + time
    elif delta.days == 1:
        return 'Tomorrow' + time
    elif abs(delta.days) < 8:
        if date.isocalendar()[1] != today.isocalendar()[1]:
            qualifier = 'Last ' if delta.days < 0 else 'Next '
        else:
            qualifier = ''
        return qualifier + date.strftime('%A') + time
    else:
        return date.strftime(format)

def weekdays(start, end):
    """Returns the number of weekdays between the inputted start and end dates.
    This would be the equivalent of doing (end - start) to get the number of
    calendar days between the two dates.

    :param      start | <datetime.date>
                end   | <datetime.date>

    :return     <int>"""
    if start == end:
        return int(start.isoweekday() not in (6, 7))
    elif end < start:
        return -weekdays(end, start)
    else:
        strt_weekday = start.isoweekday()
        end_weekday = end.isoweekday()
        if end < start:
            return -weekdays(end, start)
        if 5 < strt_weekday:
            start = start + datetime.timedelta(days=8 - strt_weekday)
        if 5 < end_weekday:
            end = end - datetime.timedelta(days=end_weekday - 5)
        remainder = end.isoweekday() - start.isoweekday()
        end = end - datetime.timedelta(days=remainder)
        if end < start:
            return 0
        elif end == start:
            return remainder + 1
        days = (end - start).days + 1
        total_days = abs(days)
        multiplier = days / total_days
        weekends = int(round(total_days / 7.0) * 2)
        week_days = (total_days - weekends + remainder) * multiplier
        return week_days

def _get_minidom_tag_value(station, tag_name):
    """get a value from a tag (if it exists)"""
    tag = station.getElementsByTagName(tag_name)[0].firstChild
    if tag:
        return tag.nodeValue
    return None

def _parse(data, obj_name, attr_map):
    """parse xml data into a python map"""
    parsed_xml = minidom.parseString(data)
    parsed_objects = []
    for obj in parsed_xml.getElementsByTagName(obj_name):
        parsed_obj = {}
        for py_name, xml_name in attr_map.items():
            parsed_obj[py_name] = _get_minidom_tag_value(obj, xml_name)
        parsed_objects.append(parsed_obj)
    return parsed_objects

def instance_of(cls):
    """Create an invariant requiring the value is an instance of ``cls``."""
    def check(value):
        return (isinstance(value, cls), u'{value!r} is instance of {actual!s}, required {required!s}'.format(value=value, actual=fullyQualifiedName(type(value)), required=fullyQualifiedName(cls)))
    return check

def provider_of(iface):
    """Create an invariant requiring the value provides the zope.interface
    ``iface``."""
    def check(value):
        return (iface.providedBy(value), u'{value!r} does not provide {interface!s}'.format(value=value, interface=fullyQualifiedName(iface)))
    return check

def _isFileAccessible(filepath):
    """Returns True if the specified filepath is writable."""
    directory = os.path.dirname(filepath)
    if not os.access(directory, os.W_OK):
        return False
    if os.path.exists(filepath):
        if not os.access(filepath, os.W_OK):
            return False
        try:
            openfile = os.open(filepath, os.O_WRONLY)
            os.close(openfile)
        except IOError:
            return False
    return True

def searchFileLocation(targetFileName, targetFileExtension, rootDirectory, recursive=True):
    """Search for a filename with a specified file extension in all subfolders
    of specified rootDirectory, returns first matching instance.

    :param targetFileName: #TODO: docstring
    :type targetFileName: str
    :param rootDirectory: #TODO: docstring
    :type rootDirectory: str
    :param targetFileExtension: #TODO: docstring
    :type targetFileExtension: str
    :param recursive: bool, specify whether subdirectories should be searched

    :returns: a filepath (str) or None"""
    expectedFileName = targetFileName.split('.')[0] + '.' + targetFileExtension
    targetFilePath = None
    if recursive:
        for dirpath, dirnames, filenames in os.walk(rootDirectory):
            for filename in filenames:
                if filename == expectedFileName:
                    targetFilePath = joinpath(dirpath, filename)
                    break
            if targetFilePath is not None:
                break
    else:
        for filename in os.listdir(rootDirectory):
            filePath = joinpath(rootDirectory, filename)
            if not os.path.isfile(filePath):
                continue
            if filename == expectedFileName:
                targetFilePath = filePath
                break
    return targetFilePath

def toList(variable, types=(basestring, int, float)):
    """Converts a variable of type string, int, float to a list, containing the
    variable as the only element.

    :param variable: any python object
    :type variable: (str, int, float, others)

    :returns: [variable] or variable"""
    if isinstance(variable, types):
        return [variable]
    else:
        return variable

def persistent_menu(menu):
    """more: https://developers.facebook.com/docs/messenger-platform/thread-settings/persistent-menu

    :param menu:
    :return:"""
    if len(menu) > 3:
        raise Invalid('menu should not exceed 3 call to actions')
    if any((len(item['call_to_actions']) > 5 for item in menu if item['type'] == 'nested')):
        raise Invalid('call_to_actions is limited to 5 for sub-levels')
    for item in menu:
        if len(item['title']) > 30:
            raise Invalid('menu item title should not exceed 30 characters')
        if item['type'] == 'postback' and len(item['payload']) > 1000:
            raise Invalid('menu item payload should not exceed 1000 characters')

def send_text_message(text, quick_replies):
    """more:
    https://developers.facebook.com/docs/messenger-platform/send-api-reference/text-message
     and
    https://developers.facebook.com/docs/messenger-platform/send-api-reference/quick-replies

    :param text:
    :param quick_replies:
    :return:"""
    if len(text) > 640:
        raise ExceedLengthException('send message text should not exceed 640 character limit', limit=640)
    if isinstance(quick_replies, list):
        if len(quick_replies) > 10:
            raise Invalid('send message quick replies should not exceed 10 limit')
        for item in quick_replies:
            if 'content_type' not in item:
                raise Invalid('send message quick replies should have content_type')
            if item['content_type'] == 'text':
                if len(item['title']) > 20:
                    raise Invalid('send message quick replies title should not exceed 20 character limit')
                if len(item['payload']) > 1000:
                    raise Invalid('send message quick replies payload should not exceed 1000 character limit')

def append_request_id(req, resp, resource, params):
    """Append request id which got from response
    header to resource.req_ids list."""
    def get_headers(resp):
        if hasattr(resp, 'headers'):
            return resp.headers
        if hasattr(resp, '_headers'):
            return resp._headers
        return None
    if isinstance(resp, Response) or get_headers(resp) is not None:
        request_id = get_headers(resp).get('x-request-id')
    else:
        request_id = resp
    if resource.req_ids is None:
        resource.req_ids = []
    if request_id not in resource.req_ids:
        resource.req_ids.append(request_id)

