def index_to_coords(index, shape):
    """convert index to coordinates given the shape"""
    coords = []
    for i in xrange(1, len(shape)):
        divisor = int(np.product(shape[i:]))
        value = index // divisor
        coords.append(value)
        index -= value * divisor
    coords.append(index)
    return tuple(coords)

def stdout_encode(u, default='utf-8'):
    """Encodes a given string with the proper standard out encoding
    If sys.stdout.encoding isn't specified, it this defaults to @default

    @default: default encoding

    -> #str with standard out encoding"""
    encoding = sys.stdout.encoding or default
    return u.encode(encoding, 'replace').decode(encoding, 'replace')

def get_terminal_width():
    """-> #int width of the terminal window"""
    command = ['tput', 'cols']
    try:
        width = int(subprocess.check_output(command))
    except OSError as e:
        print("Invalid Command '{0}': exit status ({1})".format(command[0], e.errno))
    except subprocess.CalledProcessError as e:
        print("'{0}' returned non-zero exit status: ({1})".format(command, e.returncode))
