def parse_parent(docname):
    """Given a docname path, pick apart and return name of parent"""
    lineage = docname.split('/')
    lineage_count = len(lineage)
    if docname == 'index':
        parent = None
    elif lineage_count == 1:
        parent = 'index'
    elif lineage_count == 2 and lineage[-1] == 'index':
        parent = 'index'
    elif lineage_count == 2:
        parent = lineage[0] + '/index'
    elif lineage[-1] == 'index':
        parent = '/'.join(lineage[:-2]) + '/index'
    else:
        parent = '/'.join(lineage[:-1]) + '/index'
    return parent

def parse_connection_string_psycopg2(connection_string):
    """parses psycopg2 consumable connection string
    :param connection_string:
    :return: return dictionary with connection string parts"""
    conn_prepared = {}
    conn_parsed = urlparse(connection_string)
    if not conn_parsed.hostname:
        _re_dbstr = re.compile('\\bhost=(?P<host>[0-9a-zA-Z_.!@#$%^&*()~]+)|dbname=(?P<dbname>[0-9a-zA-Z_.!@#$%^&*()~]+)|port=(?P<port>[0-9a-zA-Z_.!@#$%^&*()~]+)|user=(?P<user>[0-9a-zA-Z_.!@#$%^&*()~]+)|password=(?P<password>[0-9a-zA-Z_.!@#$%^&*()~]+)\\b', re.IGNORECASE)
        for match in _re_dbstr.finditer(connection_string):
            match_dict = match.groupdict()
            if match_dict['host']:
                conn_prepared['host'] = match_dict['host']
            if match_dict['port']:
                conn_prepared['port'] = match_dict['port']
            if match_dict['dbname']:
                conn_prepared['dbname'] = match_dict['dbname']
            if match_dict['user']:
                conn_prepared['user'] = match_dict['user']
            if match_dict['password']:
                conn_prepared['password'] = match_dict['password']
    else:
        conn_prepared = {'host': conn_parsed.hostname, 'port': conn_parsed.port, 'dbname': conn_parsed.path, 'user': conn_parsed.username, 'password': conn_parsed.password}
    return conn_prepared

def token_auto_auth(func):
    """Wrap class methods with automatic token re-authentication.

    This wrapper will detect authentication failures coming from its wrapped method. When one is
    caught, it will request a new token, and simply replay the original request.

    The one constraint that this wrapper has is that the wrapped method's class must have the
    :py:class:`objectrocket.client.Client` object embedded in it as the property ``_client``. Such
    is the design of all current client operations layers."""
    @functools.wraps(func)
    def wrapper(self, *args, **kwargs):
        try:
            response = func(self, *args, **kwargs)
        except errors.AuthFailure:
            self._client.auth._refresh()
            response = func(self, *args, **kwargs)
        return response
    return wrapper

