def find_potential_match_regions(template, transformed_array, method='correlation', raw_tolerance=0.666):
    """To prevent prohibitively slow calculation of normalisation coefficient at each point in image
    find potential match points, and normalise these only these.
    This function uses the definitions of the matching functions to calculate the expected match value
    and finds positions in the transformed array matching these- normalisation will then eliminate false positives"""
    if method == 'correlation':
        match_value = np.sum(template ** 2)
    elif method == 'squared difference':
        match_value = 0
    elif method == 'correlation coefficient':
        temp_minus_mean = template - np.mean(template)
        match_value = np.sum(temp_minus_mean ** 2)
    else:
        raise ValueError('Matching method not implemented')
    condition = (np.round(transformed_array, decimals=3) >= match_value * raw_tolerance) & (np.round(transformed_array, decimals=3) <= match_value * (1.0 / raw_tolerance))
    return np.transpose(condition.nonzero())

def normalise_correlation(image_tile_dict, transformed_array, template, normed_tolerance=1):
    """Calculates the normalisation coefficients of potential match positions
    Then normalises the correlation at these positions, and returns them
    if they do indeed constitute a match"""
    template_norm = np.linalg.norm(template)
    image_norms = {(x, y): np.linalg.norm(image_tile_dict[x, y]) * template_norm for x, y in image_tile_dict.keys()}
    match_points = image_tile_dict.keys()
    h, w = template.shape
    image_matches_normalised = {match_points[i]: transformed_array[match_points[i][0], match_points[i][1]] / image_norms[match_points[i]] for i in range(len(match_points))}
    result = {key: value for key, value in image_matches_normalised.items() if np.round(value, decimals=3) >= normed_tolerance}
    return result.keys()

def normalise_correlation_coefficient(image_tile_dict, transformed_array, template, normed_tolerance=1):
    """As above, but for when the correlation coefficient matching method is used
    """
    template_mean = np.mean(template)
    template_minus_mean = template - template_mean
    template_norm = np.linalg.norm(template_minus_mean)
    image_norms = {(x, y): np.linalg.norm(image_tile_dict[x, y] - np.mean(image_tile_dict[x, y])) * template_norm for x, y in image_tile_dict.keys()}
    match_points = image_tile_dict.keys()
    h, w = template.shape
    image_matches_normalised = {match_points[i]: transformed_array[match_points[i][0], match_points[i][1]] / image_norms[match_points[i]] for i in range(len(match_points))}
    normalised_matches = {key: value for key, value in image_matches_normalised.items() if np.round(value, decimals=3) >= normed_tolerance}
    return normalised_matches.keys()

def calculate_squared_differences(image_tile_dict, transformed_array, template, sq_diff_tolerance=0.1):
    """As above, but for when the squared differences matching method is used
    """
    template_norm_squared = np.sum(template ** 2)
    image_norms_squared = {(x, y): np.sum(image_tile_dict[x, y] ** 2) for x, y in image_tile_dict.keys()}
    match_points = image_tile_dict.keys()
    h, w = template.shape
    image_matches_normalised = {match_points[i]: -2 * transformed_array[match_points[i][0], match_points[i][1]] + image_norms_squared[match_points[i]] + template_norm_squared for i in range(len(match_points))}
    cutoff = h * w * 255 ** 2 * sq_diff_tolerance
    normalised_matches = {key: value for key, value in image_matches_normalised.items() if np.round(value, decimals=3) <= cutoff}
    return normalised_matches.keys()

def is_number(num, if_bool=False):
    """:return: True if num is either an actual number, or an object that converts to one"""
    if isinstance(num, bool):
        return if_bool
    elif isinstance(num, int):
        return True
    try:
        number = float(num)
        return not (isnan(number) or isinf(number))
    except (TypeError, ValueError):
        return False

def _VarintDecoder(mask):
    """Return an encoder for a basic varint value (does not include tag).

    Decoded values will be bitwise-anded with the given mask before being
    returned, e.g. to limit them to 32 bits.  The returned decoder does not
    take the usual "end" parameter -- the caller is expected to do bounds checking
    after the fact (often the caller can defer such checking until later).  The
    decoder returns a (value, new_pos) pair."""
    def DecodeVarint(buffer, pos):
        result = 0
        shift = 0
        while 1:
            if pos > len(buffer) - 1:
                raise NotEnoughDataException('Not enough data to decode varint')
            b = buffer[pos]
            result |= (b & 127) << shift
            pos += 1
            if not b & 128:
                result &= mask
                return (result, pos)
            shift += 7
            if shift >= 64:
                raise _DecodeError('Too many bytes when decoding varint.')
    return DecodeVarint

def _SignedVarintDecoder(mask):
    """Like _VarintDecoder() but decodes signed values."""
    def DecodeVarint(buffer, pos):
        result = 0
        shift = 0
        while 1:
            if pos > len(buffer) - 1:
                raise NotEnoughDataException('Not enough data to decode varint')
            b = local_ord(buffer[pos])
            result |= (b & 127) << shift
            pos += 1
            if not b & 128:
                if result > 9223372036854775807:
                    result -= 1 << 64
                    result |= ~mask
                else:
                    result &= mask
                return (result, pos)
            shift += 7
            if shift >= 64:
                raise _DecodeError('Too many bytes when decoding varint.')
    return DecodeVarint

def varintSize(value):
    """Compute the size of a varint value."""
    if value <= 127:
        return 1
    if value <= 16383:
        return 2
    if value <= 2097151:
        return 3
    if value <= 268435455:
        return 4
    if value <= 34359738367:
        return 5
    if value <= 4398046511103:
        return 6
    if value <= 562949953421311:
        return 7
    if value <= 72057594037927935:
        return 8
    if value <= 9223372036854775807:
        return 9
    return 10

def signedVarintSize(value):
    """Compute the size of a signed varint value."""
    if value < 0:
        return 10
    if value <= 127:
        return 1
    if value <= 16383:
        return 2
    if value <= 2097151:
        return 3
    if value <= 268435455:
        return 4
    if value <= 34359738367:
        return 5
    if value <= 4398046511103:
        return 6
    if value <= 562949953421311:
        return 7
    if value <= 72057594037927935:
        return 8
    if value <= 9223372036854775807:
        return 9
    return 10

def _VarintEncoder():
    """Return an encoder for a basic varint value."""
    local_chr = chr
    def EncodeVarint(write, value):
        bits = value & 127
        value >>= 7
        while value:
            write(128 | bits)
            bits = value & 127
            value >>= 7
        return write(bits)
    return EncodeVarint

def _SignedVarintEncoder():
    """Return an encoder for a basic signed varint value."""
    local_chr = chr
    def EncodeSignedVarint(write, value):
        if value < 0:
            value += 1 << 64
        bits = value & 127
        value >>= 7
        while value:
            write(128 | bits)
            bits = value & 127
            value >>= 7
        return write(bits)
    return EncodeSignedVarint

def features_properties_null_remove(obj):
    """Remove any properties of features in the collection that have
    entries mapping to a null (i.e., None) value"""
    features = obj['features']
    for i in tqdm(range(len(features))):
        if 'properties' in features[i]:
            properties = features[i]['properties']
            features[i]['properties'] = {p: properties[p] for p in properties if properties[p] is not None}
    return obj

def features_tags_parse_str_to_dict(obj):
    """Parse tag strings of all features in the collection into a Python
    dictionary, if possible."""
    features = obj['features']
    for i in tqdm(range(len(features))):
        tags = features[i]['properties'].get('tags')
        if tags is not None:
            try:
                tags = json.loads('{' + tags.replace('=>', ':') + '}')
            except:
                try:
                    tags = eval('{' + tags.replace('=>', ':') + '}')
                except:
                    tags = None
        if type(tags) == dict:
            features[i]['properties']['tags'] = {k: tags[k] for k in tags}
        elif tags is None and 'tags' in features[i]['properties']:
            del features[i]['properties']['tags']
    return obj

def features_keep_by_property(obj, query):
    """Filter all features in a collection by retaining only those that
    satisfy the provided query."""
    features_keep = []
    for feature in tqdm(obj['features']):
        if all([match(feature['properties'].get(prop), qry) for prop, qry in query.items()]):
            features_keep.append(feature)
    obj['features'] = features_keep
    return obj

def features_keep_within_radius(obj, center, radius, units):
    """Filter all features in a collection by retaining only those that
    fall within the specified radius."""
    features_keep = []
    for feature in tqdm(obj['features']):
        if all([getattr(geopy.distance.vincenty((lat, lon), center), units) < radius for lon, lat in geojson.utils.coords(feature)]):
            features_keep.append(feature)
    obj['features'] = features_keep
    return obj

def features_node_edge_graph(obj):
    """Transform the features into a more graph-like structure by
    appropriately splitting LineString features into two-point
    "edges" that connect Point "nodes"."""
    points = {}
    features = obj['features']
    for feature in tqdm(obj['features']):
        for lon, lat in geojson.utils.coords(feature):
            points.setdefault((lon, lat), 0)
            points[lon, lat] += 1
    points = [p for p, c in points.items() if c > 1]
    features = [geojson.Point(p) for p in points]
    for f in tqdm(obj['features']):
        seqs = []
        seq = []
        for point in geojson.utils.coords(f):
            if len(seq) > 0:
                seq.append(point)
            if point in points:
                seq.append(point)
                if len(seq) > 1 and seq[0] in points:
                    seqs.append(seq)
                    seq = [point]
        for seq in seqs:
            features.append(geojson.Feature(geometry={'coordinates': seq, 'type': f['geometry']['type']}, properties=f['properties'], type=f['type']))
    obj['features'] = features
    return obj

def parse_duration(duration):
    """Attepmts to parse an ISO8601 formatted ``duration``.

    Returns a ``datetime.timedelta`` object."""
    duration = str(duration).upper().strip()
    elements = ELEMENTS.copy()
    for pattern in (SIMPLE_DURATION, COMBINED_DURATION):
        if pattern.match(duration):
            found = pattern.match(duration).groupdict()
            del found['time']
            elements.update(dict(((k, int(v or 0)) for k, v in found.items())))
            return datetime.timedelta(days=elements['days'] + _months_to_days(elements['months']) + _years_to_days(elements['years']), hours=elements['hours'], minutes=elements['minutes'], seconds=elements['seconds'])
    return ParseError()

def uniq(pipe):
    """this works like bash's uniq command where the generator only iterates
    if the next value is not the previous"""
    pipe = iter(pipe)
    previous = next(pipe)
    yield previous
    for i in pipe:
        if i is not previous:
            previous = i
            yield i

def separate(text):
    """Takes text and separates it into a list of words"""
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    words = text.split()
    standardwords = []
    for word in words:
        newstr = ''
        for char in word:
            if char in alphabet or char in alphabet.upper():
                newstr += char
        if newstr != '':
            standardwords.append(newstr)
    return map(lambda x: x.lower(), standardwords)

def eliminate_repeats(text):
    """Returns a list of words that occur in the text. Eliminates stopwords."""
    bannedwords = read_file('stopwords.txt')
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    words = text.split()
    standardwords = []
    for word in words:
        newstr = ''
        for char in word:
            if char in alphabet or char in alphabet.upper():
                newstr += char
        if newstr not in standardwords and newstr != '' and (newstr not in bannedwords):
            standardwords.append(newstr)
    return map(lambda x: x.lower(), standardwords)

def wordcount(text):
    """Returns the count of the words in a file."""
    bannedwords = read_file('stopwords.txt')
    wordcount = {}
    separated = separate(text)
    for word in separated:
        if word not in bannedwords:
            if not wordcount.has_key(word):
                wordcount[word] = 1
            else:
                wordcount[word] += 1
    return wordcount

def copy_resource(src, dest):
    """To copy package data to destination"""
    package_name = 'yass'
    dest = (dest + '/' + os.path.basename(src)).rstrip('/')
    if pkg_resources.resource_isdir(package_name, src):
        if not os.path.isdir(dest):
            os.makedirs(dest)
        for res in pkg_resources.resource_listdir(__name__, src):
            copy_resource(src + '/' + res, dest)
    elif not os.path.isfile(dest) and os.path.splitext(src)[1] not in ['.pyc']:
        with open(dest, 'wb') as f:
            f.write(pkg_resources.resource_string(__name__, src))
    else:
        print('File exists: %s ' % dest)

def serve(port, no_livereload, open_url):
    """Serve the site"""
    engine = Yass(CWD)
    if not port:
        port = engine.config.get('local_server.port', 8000)
    if no_livereload is None:
        no_livereload = True if engine.config.get('local_server.livereload') is False else False
    if open_url is None:
        open_url = False if engine.config.get('local_server.open_url') is False else True
    print('Serving at %s' % port)
    print('Livereload is %s' % ('OFF' if no_livereload else 'ON'))
    def build_static():
        engine.build_static()
    def build_pages():
        engine.build_pages()
    engine.build()
    server = Server()
    if no_livereload is False:
        server.watch(engine.static_dir + '/', build_static)
        server.watch(engine.pages_dir + '/', build_pages)
        server.watch(engine.templates_dir + '/', build_pages)
        server.watch(engine.data_dir + '/', build_pages)
    server.serve(open_url_delay=open_url, port=port, root=engine.build_dir)

def note_adapter(obj, request):
    """Adapter for rendering a :class:`skosprovider.skos.Note` to json.

    :param skosprovider.skos.Note obj: The note to be rendered.
    :rtype: :class:`dict`"""
    return {'note': obj.note, 'type': obj.type, 'language': obj.language, 'markup': obj.markup}

def parse_email_url(url):
    """Parses an email URL."""
    conf = {}
    url = urlparse.urlparse(url)
    path = url.path[1:]
    path = path.split('?', 2)[0]
    conf.update({'EMAIL_FILE_PATH': path, 'EMAIL_HOST_USER': url.username, 'EMAIL_HOST_PASSWORD': url.password, 'EMAIL_HOST': url.hostname, 'EMAIL_PORT': url.port})
    if url.scheme in EMAIL_SCHEMES:
        conf['EMAIL_BACKEND'] = EMAIL_SCHEMES[url.scheme]
    if url.scheme == 'smtps':
        conf['EMAIL_USE_TLS'] = True
    else:
        conf['EMAIL_USE_TLS'] = False
    return conf

def config(name='EMAIL_URL', default='console://'):
    """Returns a dictionary with EMAIL_* settings from EMAIL_URL."""
    conf = {}
    s = env(name, default)
    if s:
        conf = parse_email_url(s)
    return conf

def read_relative_file(filename, relative_to=None):
    """Returns contents of the given file, which path is supposed relative
    to this package."""
    if relative_to is None:
        relative_to = os.path.dirname(__file__)
    with open(os.path.join(os.path.dirname(relative_to), filename)) as f:
        return f.read()

def create_quali_api_instance(context, logger):
    """Get needed attributes from context and create instance of QualiApiHelper
    :param context:
    :param logger:
    :return:"""
    if hasattr(context, 'reservation') and context.reservation:
        domain = context.reservation.domain
    elif hasattr(context, 'remote_reservation') and context.remote_reservation:
        domain = context.remote_reservation.domain
    else:
        domain = None
    address = context.connectivity.server_address
    token = context.connectivity.admin_auth_token
    if token:
        instance = QualiAPIHelper(address, logger, token=token, domain=domain)
    else:
        instance = QualiAPIHelper(address, logger, username='admin', password='admin', domain=domain)
    return instance

def alternator(*pipes):
    """a lot like zip, just instead of:
        (a,b),(a,b),(a,b)
    it works more like:
        a,b,a,b,a,b,a
    until one of the pipes ends"""
    try:
        for p in cycle(map(iter, pipes)):
            yield next(p)
    except StopIteration:
        pass

def _make_connect(module, args, kwargs):
    """Returns a function capable of making connections with a particular
    driver given the supplied credentials."""
    return functools.partial(module.connect, *args, **kwargs)

def connect(module, *args, **kwargs):
    """Connect to a database using the given DB-API driver module. Returns
    a database context representing that connection. Any arguments or
    keyword arguments are passed the module's :py:func:`connect` function."""
    mdr = SingleConnectionMediator(module, _make_connect(module, args, kwargs))
    return Context(module, mdr)

def create_pool(module, max_conns, *args, **kwargs):
    """Create a connection pool appropriate to the driver module's capabilities."""
    if not hasattr(module, 'threadsafety'):
        raise NotSupported('Cannot determine driver threadsafety.')
    if max_conns < 1:
        raise ValueError('Minimum number of connections is 1.')
    if module.threadsafety >= 2:
        return Pool(module, max_conns, *args, **kwargs)
    if module.threadsafety >= 1:
        return DummyPool(module, *args, **kwargs)
    raise ValueError('Bad threadsafety level: %d' % module.threadsafety)

def query(stmt, args=(), factory=None):
    """Execute a query. This returns an iterator of the result set."""
    ctx = Context.current()
    factory = ctx.default_factory if factory is None else factory
    with ctx.mdr:
        return factory(ctx.execute(stmt, args), ctx.mdr)

def query_row(stmt, args=(), factory=None):
    """Execute a query. Returns the first row of the result set, or `None`."""
    for row in query(stmt, args, factory):
        return row
    return None

def query_proc(procname, args=(), factory=None):
    """Execute a stored procedure. This returns an iterator of the result set."""
    ctx = Context.current()
    factory = ctx.default_factory if factory is None else factory
    with ctx.mdr:
        return factory(ctx.execute_proc(procname, args), ctx.mdr)

def query_proc_row(procname, args=(), factory=None):
    """Execute a stored procedure. Returns the first row of the result set,
    or `None`."""
    for row in query_proc(procname, args, factory):
        return row
    return None

def make_placeholders(seq, start=1):
    """Generate placeholders for the given sequence."""
    if len(seq) == 0:
        raise ValueError('Sequence must have at least one element.')
    param_style = Context.current().param_style
    placeholders = None
    if isinstance(seq, dict):
        if param_style in ('named', 'pyformat'):
            template = ':%s' if param_style == 'named' else '%%(%s)s'
            placeholders = (template % key for key in six.iterkeys(seq))
    elif isinstance(seq, (list, tuple)):
        if param_style == 'numeric':
            placeholders = (':%d' % i for i in xrange(start, start + len(seq)))
        elif param_style in ('qmark', 'format', 'pyformat'):
            placeholders = itertools.repeat('?' if param_style == 'qmark' else '%s', len(seq))
    if placeholders is None:
        raise NotSupported("Param style '%s' does not support sequence type '%s'" % (param_style, seq.__class__.__name__))
    return ', '.join(placeholders)

def function_arg_count(fn):
    """returns how many arguments a funciton has"""
    assert callable(fn), 'function_arg_count needed a callable function, not {0}'.format(repr(fn))
    if hasattr(fn, '__code__') and hasattr(fn.__code__, 'co_argcount'):
        return fn.__code__.co_argcount
    else:
        return 1

def map(*args):
    """this map works just like the builtin.map, except, this one you can also:
    - give it multiple functions to map over an iterable
    - give it a single function with multiple arguments to run a window
      based map operation over an iterable"""
    functions_to_apply = [i for i in args if callable(i)]
    iterables_to_run = [i for i in args if not callable(i)]
    assert len(functions_to_apply) > 0, 'at least one function needs to be given to map'
    assert len(iterables_to_run) > 0, 'no iterables were given to map'
    if len(functions_to_apply) == 1 and len(iterables_to_run) >= 1 and (function_arg_count(*functions_to_apply) == 1):
        if hasattr(iter([]), '__next__'):
            return __builtins__.map(functions_to_apply[0], *iterables_to_run)
        else:
            return iter(__builtins__.map(functions_to_apply[0], *iterables_to_run))
    elif len(functions_to_apply) == 1:
        fn = functions_to_apply[0]
        if len(iterables_to_run) == 1:
            return (fn(*i) for i in window(iterables_to_run[0], function_arg_count(functions_to_apply[0])))
    elif len(functions_to_apply) > 1 and len(iterables_to_run) == 1:
        return multi_ops(*iterables_to_run + functions_to_apply)
    else:
        raise ValueError('invalid usage of map()')

def join(left, right, how='inner', key=None, left_key=None, right_key=None, join_fn=tuple_join):
    """:param left: left iterable to be joined
    :param right: right iterable to be joined
    :param str | function key: either an attr name, dict key, or function that produces hashable value
    :param how: 'inner', 'left', 'right', or 'outer'
    :param join_fn: function called on joined left and right iterable items to complete join
    :rtype: list"""
    if key is None and (left_key is None or right_key is None):
        raise ValueError('Must provide either key param or both left_key and right_key')
    if key is not None:
        lkey = rkey = key if callable(key) else make_key_fn(key)
    else:
        lkey = left_key if callable(left_key) else make_key_fn(left_key)
        rkey = right_key if callable(right_key) else make_key_fn(right_key)
    try:
        join_impl = {'left': _left_join, 'right': _right_join, 'inner': _inner_join, 'outer': _outer_join}[how]
    except KeyError:
        raise ValueError('Invalid value for how: {}, must be left, right, inner, or outer.'.format(str(how)))
    else:
        return join_impl(left, right, lkey, rkey, join_fn)

def _right_join(left, right, left_key_fn, right_key_fn, join_fn=union_join):
    """:param left: left iterable to be joined
    :param right: right iterable to be joined
    :param function left_key_fn: function that produces hashable value from left objects
    :param function right_key_fn: function that produces hashable value from right objects
    :param join_fn: function called on joined left and right iterable items to complete join
    :rtype: list"""
    def reversed_join_fn(left_ele, right_ele):
        return join_fn(right_ele, left_ele)
    return _left_join(right, left, right_key_fn, left_key_fn, reversed_join_fn)

def _outer_join(left, right, left_key_fn, right_key_fn, join_fn=union_join):
    """:param left: left iterable to be joined
    :param right: right iterable to be joined
    :param function left_key_fn: function that produces hashable value from left objects
    :param function right_key_fn: function that produces hashable value from right objects
    :param join_fn: function called on joined left and right iterable items to complete join
    :rtype: list"""
    left_joiner = defaultdict(list)
    for ele in left:
        left_joiner[left_key_fn(ele)].append(ele)
    right_joiner = defaultdict(list)
    for ele in right:
        right_joiner[right_key_fn(ele)].append(ele)
    keys = set(left_joiner.keys()).union(set(right_joiner.keys()))
    def iter_join(l, r, join_keys):
        for join_key in join_keys:
            for ele in l.get(join_key, [None]):
                for other in r.get(join_key, [None]):
                    yield join_fn(ele, other)
    return list(iter_join(left_joiner, right_joiner, keys))

def group(iterable, key=lambda ele: ele):
    """Groups an iterable by a specified attribute, or using a specified key access function.  Returns tuples of grouped elements.

    >>> dogs = [Dog('gatsby', 'Rruff!', 15), Dog('william', 'roof', 12), Dog('edward', 'hi', 15)]
    >>> groupby(dogs, 'weight')
    [(Dog('gatsby', 'Rruff!', 15), Dog('edward', 'hi', 15)), (Dog('william', 'roof', 12), )]

    :param iterable: iterable to be grouped
    :param key: a key-access function or attr name to be used as a group key"""
    if callable(key):
        return _group(iterable, key)
    else:
        return _group(iterable, make_key_fn(key))

def task(arg=None):
    """Task decorator"""
    if not hasattr(sys.stdout, 'indent_level'):
        sys.stdout = IndentedFile(sys.stdout)
    def decorator(base):
        info = ': ' + arg if type(arg) is str else ''
        header = fore.green('** ' + fore.cyan(base.__name__) + info)
        def func(*args, **kwargs):
            sys.stdout.indent_level += 1
            puts(header)
            base(*args, **kwargs)
            sys.stdout.indent_level -= 1
        params = inspect.formatargspec(*inspect.getargspec(base))[1:-1]
        specformat = fore.cyan('%s') + ' ' + fore.white('%s')
        func._task = True
        func._spec = specformat % (base.__name__, params)
        func._desc = re.sub('\\s+', ' ', inspect.getdoc(base) or '')
        return func
    if type(arg) == types.FunctionType:
        return decorator(arg)
    else:
        return decorator

def recurse_up(directory, filename):
    """Recursive walk a directory up to root until it contains `filename`"""
    directory = osp.abspath(directory)
    while True:
        searchfile = osp.join(directory, filename)
        if osp.isfile(searchfile):
            return directory
        if directory == '/':
            break
        else:
            directory = osp.dirname(directory)
    return False

def multi_ops(data_stream, *funcs):
    """fork a generator with multiple operations/functions

    data_stream  -  an iterable data structure (ie: list/generator/tuple)
    funcs        -  every function that will be applied to the data_stream"""
    assert all((callable(func) for func in funcs)), 'multi_ops can only apply functions to the first argument'
    assert len(funcs), 'multi_ops needs at least one function to apply to data_stream'
    for i in data_stream:
        if len(funcs) > 1:
            yield tuple((func(i) for func in funcs))
        elif len(funcs) == 1:
            yield funcs[0](i)

def read_environment_file(envfile=None):
    """Read a .env file into os.environ.

    If not given a path to a envfile path, does filthy magic stack backtracking
    to find manage.py and then find the envfile."""
    if envfile is None:
        frame = sys._getframe()
        envfile = os.path.join(os.path.dirname(frame.f_back.f_code.co_filename), '.env')
        if not os.path.exists(envfile):
            warnings.warn("not reading %s - it doesn't exist." % envfile)
            return
    for k, v in parse_environment_file(envfile):
        os.environ.setdefault(k, v)

def remove_unreachable_symbols(grammar, inplace=False):
    """Remove unreachable symbols from the gramar
    :param grammar: Grammar where to symbols remove
    :param inplace: True if transformation should be performed in place. False by default.
    :return: Grammar without unreachable symbols."""
    if inplace is False:
        grammar = copy(grammar)
    if grammar.start is None:
        raise StartSymbolNotSetException()
    reachable = {grammar.start}
    rules = grammar.rules.copy()
    while True:
        active = reachable.copy()
        for rule in rules.copy():
            if rule.fromSymbol in reachable:
                for symbol in rule.right:
                    active.add(symbol)
                rules.remove(rule)
        if active == reachable:
            break
        reachable = active
    nonterminals_to_remove = grammar.nonterminals.difference(reachable)
    terminals_to_remove = grammar.terminals.difference(reachable)
    grammar.nonterminals.remove(*nonterminals_to_remove)
    grammar.terminals.remove(*terminals_to_remove)
    return grammar

