def requires_indieauth(f):
    """Wraps a Flask handler to require a valid IndieAuth access token.
    """
    @wraps(f)
    def decorated(*args, **kwargs):
        access_token = get_access_token()
        resp = check_auth(access_token)
        if isinstance(resp, Response):
            return resp
        return f(*args, **kwargs)
    return decorated

def check_auth(access_token):
    """This function contacts the configured IndieAuth Token Endpoint
    to see if the given token is a valid token and for whom."""
    if not access_token:
        current_app.logger.error('No access token.')
        return deny('No access token found.')
    request = Request(current_app.config['TOKEN_ENDPOINT'], headers={'Authorization': 'Bearer %s' % access_token})
    contents = urlopen(request).read().decode('utf-8')
    token_data = parse_qs(contents)
    me = token_data['me'][0]
    client_id = token_data['client_id'][0]
    if me is None or client_id is None:
        current_app.logger.error('Invalid token [%s]' % contents)
        return deny('Invalid token')
    me, me_error = check_me(me)
    if me is None:
        current_app.logger.error('Invalid `me` value [%s]' % me_error)
        return deny(me_error)
    scope = token_data['scope']
    if not isinstance(scope, str):
        scope = scope[0]
    valid_scopes = ('post', 'create')
    scope_ = scope.split()
    scope_valid = any((val in scope_ for val in valid_scopes))
    if not scope_valid:
        current_app.logger.error("Scope '%s' does not contain 'post' or 'create'." % scope)
        return deny("Scope '%s' does not contain 'post' or 'create'." % scope)
    g.user = {'me': me, 'client_id': client_id, 'scope': scope, 'access_token': access_token}

def parse_range_header(range):
    """Parse a range header as used by the dojo Json Rest store.

    :param str range: The content of the range header to be parsed.
        eg. `items=0-9`
    :returns: A dict with keys start, finish and number or `False` if the
        range is invalid."""
    match = re.match('^items=([0-9]+)-([0-9]+)$', range)
    if match:
        start = int(match.group(1))
        finish = int(match.group(2))
        if finish < start:
            finish = start
        return {'start': start, 'finish': finish, 'number': finish - start + 1}
    else:
        return False

def method_delegate(**methods):
    """Construct a renderer that delegates based on the request's HTTP method."""
    methods = {k.upper(): v for k, v in iteritems(methods)}
    if PY3:
        methods = {k.encode('utf-8'): v for k, v in iteritems(methods)}
    def render(request):
        renderer = methods.get(request.method)
        if renderer is None:
            return Response(code=405)
        return renderer(request)
    return render

def traverse(path, request, resource):
    """Traverse a root resource, retrieving the appropriate child for the request."""
    path = path.lstrip(b'/')
    for component in path and path.split(b'/'):
        if getattr(resource, 'is_leaf', False):
            break
        resource = resource.get_child(name=component, request=request)
    return resource

def every_other(pipe, how_many=1):
    """feeding this function a pipe yields every other (or how ever many)
    objects you want at a time."""
    for i, x in zip(pipe, cycle(repeater([True, False], how_many))):
        if x:
            yield i

def get_declared_fields(bases, attrs, cls_filter, with_base_fields=True, extra_attr_name='base_fields'):
    """Create a list of form field instances from the passed in 'attrs', plus any
    similar fields on the base classes (in 'bases'). This is used by both the
    Form and ModelForm metclasses.

    If 'with_base_fields' is True, all fields from the bases are used.
    Otherwise, only fields in the 'declared_fields' attribute on the bases are
    used. The distinction is useful in ModelForm subclassing.
    Also integrates any additional media definitions"""
    fields = [(field_name, attrs.pop(field_name)) for field_name, obj in attrs.items() if isinstance(obj, cls_filter)]
    fields.sort(key=lambda x: x[1].creation_counter)
    if with_base_fields:
        for base in reversed(bases):
            if hasattr(base, extra_attr_name):
                fields = getattr(base, extra_attr_name).items() + fields
    else:
        for base in reversed(bases):
            if hasattr(base, 'declared_fields'):
                fields = base.declared_fields.items() + fields
    return SortedDict(fields)

def declarative_fields(cls_filter, meta_base=type, extra_attr_name='base_fields'):
    """Metaclass that converts Field attributes to a dictionary called
    'base_fields', taking into account parent class 'cls_filter'."""
    def __new__(cls, name, bases, attrs):
        attrs[extra_attr_name] = fields = get_declared_fields(bases, attrs, cls_filter, extra_attr_name=extra_attr_name)
        attrs[extra_attr_name + '_names'] = set(fields.keys())
        new_class = meta_base.__new__(cls, name, bases, attrs)
        return new_class
    return type('', (meta_base,), {'__new__': __new__})

