def load_params(filepath):
    """Load your hyper parameters from a json file.
    :param filepath: Path to the json file.
    :return: A hyper parameters object."""
    with open(filepath) as file:
        content = file.read()
    q = [m.start() for m in re.finditer('%', content)]
    env_vars = []
    for i in range(0, len(q), 2):
        env_var = content[q[i] + 1:q[i + 1]]
        if env_var not in env_vars:
            if env_var in os.environ:
                env_vars.append(env_var)
            else:
                print('WARNING: Detected an environment variable which is not set.')
    for env_var in env_vars:
        s = '%' + env_var + '%'
        content = content.replace(s, os.environ[env_var].replace('\\', '/'))
    for env_var in list(os.environ.keys()):
        s = '$' + env_var
        content = content.replace(s, os.environ[env_var].replace('\\', '/'))
    return HyperParams(json.loads(jsmin(content)))

def shell_source(script):
    """Sometime you want to emulate the action of "source" in bash,
    settings some environment variables. Here is a way to do it."""
    pipe = subprocess.Popen('. %s; env' % script, stdout=subprocess.PIPE, shell=True)
    output = pipe.communicate()[0].decode()
    env = {}
    for line in output.splitlines():
        try:
            keyval = line.split('=', 1)
            env[keyval[0]] = keyval[1]
        except:
            pass
    os.environ.update(env)

def update_url_params(url, replace_all=False, **url_params):
    """:return: url with its query updated from url_query (non-matching params are retained)"""
    if not (replace_all is True or replace_all is False):
        url_params['replace_all'] = replace_all
    if not url or not url_params:
        return url or None
    scheme, netloc, url_path, url_query, fragment = _urlsplit(url)
    if replace_all is True:
        url_query = url_params
    else:
        url_query = _parse_qs(url_query)
        url_query.update(url_params)
    return _urlunsplit((scheme, netloc, url_path, _unquote(_urlencode(url_query, doseq=True)), fragment))

def url_to_parts(url):
    """Split url urlsplit style, but return path as a list and query as a dict"""
    if not url:
        return None
    scheme, netloc, path, query, fragment = _urlsplit(url)
    if not path or path == '/':
        path = []
    else:
        path = path.strip('/').split('/')
    if not query:
        query = {}
    else:
        query = _parse_qs(query)
    return _urllib_parse.SplitResult(scheme, netloc, path, query, fragment)

def parts_to_url(parts=None, scheme=None, netloc=None, path=None, query=None, fragment=None):
    """Build url urlunsplit style, but optionally handle path as a list and/or query as a dict"""
    if isinstance(parts, _urllib_parse.SplitResult):
        scheme, netloc, path, query, fragment = parts
    elif parts and isinstance(parts, dict):
        scheme = parts.get('scheme', 'http')
        netloc = parts.get('netloc', '')
        path = parts.get('path', [])
        query = parts.get('query', {})
        fragment = parts.get('fragment', '')
    if isinstance(path, (list, tuple)):
        path = '/' + '/'.join(path).strip('/')
    if isinstance(query, (dict, tuple)):
        query = _unquote(_urlencode(query, doseq=True))
    return _urlunsplit((scheme, netloc, path, query, fragment)) or None

def _create_mapping(grammar):
    """Create mapping between symbols and rules rewritable to these symbols.
    :param grammar: Grammar to use.
    :return: Tuple of two dictionaries.
    First dictionary maps rule to terminal hash.
    Second dictionary maps rule to nonterminals hash."""
    termmap = dict()
    rulemap = dict()
    for r in grammar.rules:
        if len(r.right) == 1:
            h = hash(r.toSymbol)
            if h not in termmap:
                termmap[h] = set()
            termmap[h].add(r)
        else:
            key = hash(tuple(r.right))
            if key not in rulemap:
                rulemap[key] = set()
            rulemap[key].add(r)
    return (termmap, rulemap)

def ScreenGenerator(nfft, r0, nx, ny):
    """Generate an infinite series of rectangular phase screens
    Uses an FFT screen generator to make a large screen and then
    returns non-overlapping subsections of it"""
    while 1:
        layers = GenerateTwoScreens(nfft, r0)
        for iLayer in range(2):
            for iy in range(int(nfft / ny)):
                for ix in range(int(nfft / nx)):
                    yield layers[iLayer][iy * ny:iy * ny + ny, ix * nx:ix * nx + nx]

def parse_dates(d, default='today'):
    """Parses one or more dates from d"""
    if default == 'today':
        default = datetime.datetime.today()
    if d is None:
        return default
    elif isinstance(d, _parsed_date_types):
        return d
    elif is_number(d):
        d = d if isinstance(d, float) else float(d)
        return datetime.datetime.utcfromtimestamp(d)
    elif not isinstance(d, STRING_TYPES):
        if hasattr(d, '__iter__'):
            return [parse_dates(s, default) for s in d]
        else:
            return default
    elif len(d) == 0:
        return default
    else:
        try:
            return parser.parse(d)
        except (AttributeError, ValueError):
            return default

def remove_unit_rules(grammar, inplace=False):
    """Remove unit rules from the grammar.
    :param grammar: Grammar where remove the rules.
    :param inplace: True if transformation should be performed in place. False by default.
    :return: Grammar without unit rules."""
    if inplace is False:
        grammar = copy(grammar)
    res = find_nonterminals_reachable_by_unit_rules(grammar)
    for rule in grammar.rules.copy():
        if _is_unit(rule):
            grammar.rules.remove(rule)
            continue
        for nonterm in grammar.nonterminals:
            path = res.path_rules(nonterm, rule.fromSymbol)
            if len(path) > 0 and path[0].fromSymbol != path[-1].toSymbol:
                created = _create_rule(path, rule)
                grammar.rules.add(created)
    return grammar

def make_store(name, min_length=4, **kwargs):
    """Creates a store with a reasonable keygen.

    .. deprecated:: 2.0.0
       Instantiate stores directly e.g. ``shorten.MemoryStore(min_length=4)``"""
    if name not in stores:
        raise ValueError('valid stores are {0}'.format(', '.join(stores)))
    if name == 'memcache':
        store = MemcacheStore
    elif name == 'memory':
        store = MemoryStore
    elif name == 'redis':
        store = RedisStore
    return store(min_length=min_length, **kwargs)

def nb_to_html_cells(nb) -> list:
    """Converts notebook to an iterable of BS4 HTML nodes. Images are inline."""
    html_exporter = HTMLExporter()
