def pad_pdf_pages(pdf_name, pages_per_q) -> None:
    """Checks if PDF has the correct number of pages. If it has too many, warns
    the user. If it has too few, adds blank pages until the right length is
    reached."""
    pdf = PyPDF2.PdfFileReader(pdf_name)
    output = PyPDF2.PdfFileWriter()
    num_pages = pdf.getNumPages()
    if num_pages > pages_per_q:
        logging.warning('{} has {} pages. Only the first {} pages will get output.'.format(pdf_name, num_pages, pages_per_q))
    for page in range(min(num_pages, pages_per_q)):
        output.addPage(pdf.getPage(page))
    if num_pages < pages_per_q:
        for page in range(pages_per_q - num_pages):
            output.addBlankPage()
    with open(pdf_name, 'wb') as out_file:
        output.write(out_file)

def chunk_on(pipeline, new_chunk_signal, output_type=tuple):
    """split the stream into seperate chunks based on a new chunk signal"""
    assert iterable(pipeline), 'chunks needs pipeline to be iterable'
    assert callable(new_chunk_signal), 'chunks needs new_chunk_signal to be callable'
    assert callable(output_type), 'chunks needs output_type to be callable'
    out = deque()
    for i in pipeline:
        if new_chunk_signal(i) and len(out):
            yield output_type(out)
            out.clear()
        out.append(i)
    if len(out):
        yield output_type(out)

def _thread_excepthook():
    """Make threads use sys.excepthook from parent process
    http://bugs.python.org/issue1230540"""
    init_old = thread.Thread.__init__
    def init(self, *args, **kwargs):
        init_old(self, *args, **kwargs)
        run_old = self.run
        def run_with_except_hook(*args, **kw):
            try:
                run_old(*args, **kw)
            except (KeyboardInterrupt, SystemExit):
                raise
            except:
                sys.excepthook(*sys.exc_info())
        self.run = run_with_except_hook
    thread.Thread.__init__ = init

def _split_mod_var_names(resource_name):
    """Return (module_name, class_name) pair from given string."""
    try:
        dot_index = resource_name.rindex('.')
