def find_nonterminals_reachable_by_unit_rules(grammar):
    """Get nonterminal for which exist unit rule
    :param grammar: Grammar where to search
    :return: Instance of UnitSymbolReachability."""
    nonterminals = list(grammar.nonterminals)
    count_of_nonterms = len(nonterminals)
    nonterm_to_index = dict()
    for i in range(count_of_nonterms):
        nonterm_to_index[nonterminals[i]] = i
    field = [[None for _ in nonterminals] for _ in nonterminals]
    for rule in grammar.rules:
        if _is_unit(rule):
            field[nonterm_to_index[rule.fromSymbol]][nonterm_to_index[rule.toSymbol]] = [rule]
    f = field
    for k in range(count_of_nonterms):
        for i in range(count_of_nonterms):
            for j in range(count_of_nonterms):
                if f[i][k] is not None and f[k][j] is not None:
                    if f[i][j] is None or len(f[i][j]) > len(f[i][k]) + len(f[k][j]):
                        f[i][j] = f[i][k] + f[k][j]
    return UnitSymbolReachability(f, nonterm_to_index)

def all_subslices(itr):
    """generates every possible slice that can be generated from an iterable"""
    assert iterable(itr), 'generators.all_subslices only accepts iterable arguments, not {}'.format(itr)
    if not hasattr(itr, '__len__'):
        itr = deque(itr)
    len_itr = len(itr)
    for start, _ in enumerate(itr):
        d = deque()
        for i in islice(itr, start, len_itr):
            d.append(i)
            yield tuple(d)

def just(*args):
    """this works as an infinite loop that yields
    the given argument(s) over and over"""
    assert len(args) >= 1, 'generators.just needs at least one arg'
    if len(args) == 1:
        try:
            return cycle(set(args))
        except:
            return cycle(args)
    else:
        return cycle({args})

def get_binary_path(executable):
    """Gets the software name and returns the path of the binary."""
    if sys.platform == 'win32':
        if executable == 'start':
            return executable
        executable = executable + '.exe'
        if executable in os.listdir('.'):
            binary = os.path.join(os.getcwd(), executable)
        else:
            binary = next((os.path.join(path, executable) for path in os.environ['PATH'].split(os.pathsep) if os.path.isfile(os.path.join(path, executable))), None)
    else:
        binary = Popen(['which', executable], stdout=PIPE).stdout.read().strip().decode('utf-8')
    return binary if binary else None

def chunks(stream, chunk_size, output_type=tuple):
    """returns chunks of a stream"""
    assert iterable(stream), 'chunks needs stream to be iterable'
    assert isinstance(chunk_size, int) and chunk_size > 0 or callable(chunk_size), 'chunks needs chunk_size to be a positive int or callable'
    assert callable(output_type), 'chunks needs output_type to be callable'
    if callable(chunk_size):
        ' chunk_size is acting as a separator function '
        for chunk in chunk_on(stream, chunk_size, output_type):
            yield chunk
    else:
        it = iter(stream)
        marker = object()
        iters = [it] * chunk_size
        pipeline = apply_to_last(zip_longest(*iters, fillvalue=marker), lambda last_chunk: tuple((i for i in last_chunk if i is not marker)))
        if output_type is not tuple:
            pipeline = map(output_type, pipeline)
        for chunk in pipeline:
            yield chunk

def camelcase_to_slash(name):
    """Converts CamelCase to camel/case

    code ripped from http://stackoverflow.com/questions/1175208/does-the-python-standard-library-have-function-to-convert-camelcase-to-camel-cas"""
    s1 = re.sub('(.)([A-Z][a-z]+)', '\\1/\\2', name)
    return re.sub('([a-z0-9])([A-Z])', '\\1/\\2', s1).lower()

