    for line in read(path):
        if 'import' in line or len(line.strip()) == 0 or line.startswith('#'):
            continue
        if '__name__' in line and '__main__' in line:
            break
        else:
            yield line

def bool_set(operation, *sets):
    """combine ``sets`` with ``operation``

    :and:       combine sets with AND
    :or:        combine sets with OR
    :not:       NOT sets versus the last given set"""
    if len(sets) <= 1:
        return sets
    if operation == 'and':
        return and_sets(*sets)
    if operation == 'or':
        return or_sets(*sets)
    if operation == 'not':
        return not_sets(*sets)

def _is_unit(rule):
    """Check if parameter is unit rule.
    :param rule: Object to check.
    :return: True if is parameter unit rule, false otherwise."""
    return len(rule.left) == 1 and len(rule.right) == 1 and isclass(rule.fromSymbol) and isclass(rule.toSymbol) and issubclass(rule.fromSymbol, Nonterminal) and issubclass(rule.toSymbol, Nonterminal)

def remove_rules_with_epsilon(grammar, inplace=False):
    """Remove epsilon rules.
    :param grammar: Grammar where rules remove
    :param inplace: True if transformation should be performed in place, false otherwise.
    False by default.
    :return: Grammar without epsilon rules."""
    if inplace is False:
        grammar = copy(grammar)
    rewritable = find_nonterminals_rewritable_to_epsilon(grammar)
    rules = Queue()
    for r in grammar.rules:
        rules.put(r)
    while not rules.empty():
        rule = rules.get()
        right = rule.right
        if right == [EPSILON]:
            if rule.fromSymbol != grammar.start:
                grammar.rules.discard(rule)
            continue
        for rule_index in range(len(right)):
            symbol = right[rule_index]
            if symbol in rewritable:
                new_rule = _create_rule(rule, rule_index, rewritable)
                grammar.rules.add(new_rule)
                rules.put(new_rule)
    return grammar

def get_db_distinct(queryset, field, func, **params):
    """Checks if a field / value pair exists in database
    and continues generating values until it finds
    a one that does not exist

    func is the function that generates values and
    params is the parameters that function takes"""
    while True:
        try:
            value = func(**params)
            queryset.get(**{field: value})
        except ObjectDoesNotExist:
            break
    return value

def html_to_text(html_string):
    """returns a plain text string when given a html string text
    handles a, p, h1 to h6 and br, inserts newline chars to
    create space in the string
    @todo handle images"""
    html_tree = html.document_fromstring(html_string)
    for h in html_tree.cssselect('h1, h2, h3, h4, h5, h6'):
        h.text = h.text + '\n\n'
    for a in html_tree.xpath('//a'):
        href = a.attrib['href']
        a.text = a.text + ' (' + href + ')'
    for p in html_tree.xpath('//p'):
        p.tail = p.tail if p.tail else '\n\n'
    for br in html_tree.xpath('//br'):
        br.tail = '\n' + br.tail if br.tail else '\n'
    return html_tree.text_content()

def clear_path(path):
    """    This will move a path to the Trash folder
    :param path: str of the path to remove
