def get_relationship_bundle(manager, relationship_id=None, legacy=True):
    """:param manager: Neo4jDBSessionManager
    :param relationship_id: Internal Neo4j id
    :param legacy: Backwards compatibility

    :type relationship_id: int
    :type legacy: bool

    :rtype: dictionary"""
    q = '\n        MATCH (start)-[r]->(end)\n        WHERE ID(r) = {relationship_id}\n        RETURN start, r, end\n        '
    with manager.session as s:
        record = s.run(q, {'relationship_id': int(relationship_id)}).single()
    if record is None:
        raise exceptions.RelationshipNotFound(manager, int(relationship_id))
    if legacy:
        bundle = {'type': record['r'].type, 'id': int(relationship_id), 'data': record['r'].properties, 'start': record['start'].properties['handle_id'], 'end': record['end'].properties['handle_id']}
    else:
        bundle = {'type': record['r'].type, 'id': int(relationship_id), 'data': record['r'].properties, 'start': record['start'], 'end': record['end']}
    return bundle

def get_node_meta_type(manager, handle_id):
    """Returns the meta type of the supplied node as a string.

    :param manager: Neo4jDBSessionManager
    :param handle_id: Unique id
    :return: string"""
    node = get_node(manager=manager, handle_id=handle_id, legacy=False)
    for label in node.labels:
        if label in META_TYPES:
            return label
    raise exceptions.NoMetaLabelFound(handle_id)

def create_location_relationship(manager, location_handle_id, other_handle_id, rel_type):
    """Makes relationship between the two nodes and returns the relationship.
    If a relationship is not possible NoRelationshipPossible exception is
    raised."""
    other_meta_type = get_node_meta_type(manager, other_handle_id)
    if other_meta_type == 'Location' and rel_type == 'Has':
        return _create_relationship(manager, location_handle_id, other_handle_id, rel_type)
    raise exceptions.NoRelationshipPossible(location_handle_id, 'Location', other_handle_id, other_meta_type, rel_type)

def create_logical_relationship(manager, logical_handle_id, other_handle_id, rel_type):
    """Makes relationship between the two nodes and returns the relationship.
    If a relationship is not possible NoRelationshipPossible exception is
    raised."""
    other_meta_type = get_node_meta_type(manager, other_handle_id)
    if rel_type == 'Depends_on':
        if other_meta_type == 'Logical' or other_meta_type == 'Physical':
            return _create_relationship(manager, logical_handle_id, other_handle_id, rel_type)
    elif rel_type == 'Part_of':
        if other_meta_type == 'Physical':
            return _create_relationship(manager, logical_handle_id, other_handle_id, rel_type)
    raise exceptions.NoRelationshipPossible(logical_handle_id, 'Logical', other_handle_id, other_meta_type, rel_type)

def create_relation_relationship(manager, relation_handle_id, other_handle_id, rel_type):
    """Makes relationship between the two nodes and returns the relationship.
    If a relationship is not possible NoRelationshipPossible exception is
    raised."""
    other_meta_type = get_node_meta_type(manager, other_handle_id)
    if other_meta_type == 'Logical':
        if rel_type in ['Uses', 'Provides']:
            return _create_relationship(manager, relation_handle_id, other_handle_id, rel_type)
    elif other_meta_type == 'Location' and rel_type == 'Responsible_for':
        return _create_relationship(manager, relation_handle_id, other_handle_id, rel_type)
    elif other_meta_type == 'Physical':
        if rel_type in ['Owns', 'Provides']:
            return _create_relationship(manager, relation_handle_id, other_handle_id, rel_type)
    raise exceptions.NoRelationshipPossible(relation_handle_id, 'Relation', other_handle_id, other_meta_type, rel_type)

def create_physical_relationship(manager, physical_handle_id, other_handle_id, rel_type):
    """Makes relationship between the two nodes and returns the relationship.
    If a relationship is not possible NoRelationshipPossible exception is
    raised."""
    other_meta_type = get_node_meta_type(manager, other_handle_id)
    if other_meta_type == 'Physical':
        if rel_type == 'Has' or rel_type == 'Connected_to':
            return _create_relationship(manager, physical_handle_id, other_handle_id, rel_type)
    elif other_meta_type == 'Location' and rel_type == 'Located_in':
        return _create_relationship(manager, physical_handle_id, other_handle_id, rel_type)
    raise exceptions.NoRelationshipPossible(physical_handle_id, 'Physical', other_handle_id, other_meta_type, rel_type)

def create_relationship(manager, handle_id, other_handle_id, rel_type):
    """Makes a relationship from node to other_node depending on which
    meta_type the nodes are. Returns the relationship or raises
    NoRelationshipPossible exception."""
    meta_type = get_node_meta_type(manager, handle_id)
    if meta_type == 'Location':
        return create_location_relationship(manager, handle_id, other_handle_id, rel_type)
    elif meta_type == 'Logical':
        return create_logical_relationship(manager, handle_id, other_handle_id, rel_type)
    elif meta_type == 'Relation':
        return create_relation_relationship(manager, handle_id, other_handle_id, rel_type)
    elif meta_type == 'Physical':
        return create_physical_relationship(manager, handle_id, other_handle_id, rel_type)
    other_meta_type = get_node_meta_type(manager, other_handle_id)
    raise exceptions.NoRelationshipPossible(handle_id, meta_type, other_handle_id, other_meta_type, rel_type)

def get_relationships(manager, handle_id1, handle_id2, rel_type=None, legacy=True):
    """Takes a start and an end node with an optional relationship
    type.
    Returns the relationships between the nodes or an empty list."""
    if rel_type:
        q = '\n        MATCH (a:Node {{handle_id: {{handle_id1}}}})-[r:{rel_type}]-(b:Node {{handle_id: {{handle_id2}}}})\n        RETURN collect(r) as relationships\n        '.format(rel_type=rel_type)
    else:
        q = '\n            MATCH (a:Node {handle_id: {handle_id1}})-[r]-(b:Node {handle_id: {handle_id2}})\n            RETURN collect(r) as relationships\n            '
    with manager.session as s:
        if legacy:
            relationships = s.run(q, {'handle_id1': handle_id1, 'handle_id2': handle_id2}).single()['relationships']
            return [relationship.id for relationship in relationships]
        return s.run(q, {'handle_id1': handle_id1, 'handle_id2': handle_id2}).single()['relationships']

def get_node_model(manager, handle_id=None, node=None):
    """:param manager: Context manager to handle transactions
    :type manager: Neo4jDBSessionManager
    :param handle_id: Nodes handle id
    :type handle_id: str|unicode
    :param node: Node object
    :type node: neo4j.v1.types.Node
    :return: Node model
    :rtype: models.BaseNodeModel or sub class of models.BaseNodeModel"""
    bundle = get_node_bundle(manager, handle_id, node)
    for label in bundle.get('labels'):
        try:
            classname = '{meta_type}{base}Model'.format(meta_type=bundle.get('meta_type'), base=label).replace('_', '')
            return getattr(models, classname)(manager).load(bundle)
        except AttributeError:
            pass
    for label in bundle.get('labels'):
        try:
            classname = '{base}Model'.format(base=label).replace('_', '')
            return getattr(models, classname)(manager).load(bundle)
        except AttributeError:
            pass
    try:
        classname = '{base}Model'.format(base=bundle.get('meta_type'))
        return getattr(models, classname)(manager).load(bundle)
    except AttributeError:
        return models.BaseNodeModel(manager).load(bundle)

def vi_pos_matching(line, index=0):
    """find matching <([{}])>"""
    anchor = None
    target = None
    delta = 1
    count = 0
    try:
        while 1:
            if anchor is None:
                try:
                    target, delta = _vi_dct_matching[line[index]]
                    anchor = line[index]
                    count = 1
                except KeyError:
                    index += 1
                    continue
            else:
                if index < 0:
                    return -1
                if line[index] == anchor:
                    count += 1
                elif line[index] == target:
                    count -= 1
                    if count == 0:
                        return index
            index += delta
    except IndexError:
        return -1

def get_attribute_cardinality(attribute):
    """Returns the cardinality of the given resource attribute.

    :returns: One of the constants defined in
      :class:`evererst.constants.CARDINALITY_CONSTANTS`.
    :raises ValueError: If the given attribute is not a relation attribute
      (i.e., if it is a terminal attribute)."""
    if attribute.kind == RESOURCE_ATTRIBUTE_KINDS.MEMBER:
        card = CARDINALITY_CONSTANTS.ONE
    elif attribute.kind == RESOURCE_ATTRIBUTE_KINDS.COLLECTION:
        card = CARDINALITY_CONSTANTS.MANY
    else:
        raise ValueError('Can not determine cardinality for non-terminal attributes.')
    return card

def image_get_format(f):
    """Return image format for file-object f. (jpeg, png, gif etc.)
    All formats: http://pillow.readthedocs.org/en/latest/handbook/image-file-formats.html
    Example:
        if image_get_format(request.FILES['image']) == 'jpeg':
            print 'Image is JPEG'

        if image_get_format(open('/tmp/image.png', 'rb')) == 'png':
            print 'File is PNG'"""
    f.seek(0)
    try:
        img = Image.open(f)
        t = img.format.lower()
    except IOError:
        t = None
    return t

def is_image(f, types=('png', 'jpeg', 'gif'), set_content_type=True):
    """Return True if file f is image (types type) and set its correct content_type and filename extension.
    Example:
        if is_image(request.FILES['file']):
            print 'File is image'

        if is_image(open('/tmp/image.jpeg', 'rb')):
            print 'File is image'"""
    assert isinstance(types, (list, tuple))
    t = image_get_format(f)
    if t not in [t.lower() for t in types]:
        return False
    if set_content_type:
        set_uploaded_file_content_type_and_file_ext(f, t)
    return True

def optimize_png_file(f, o=None):
    """Use pngquant for optimize PNG-image.
    f - path to input image file or file-object.
    o - path to output image file or file-object for save result.
    NOTICE: f and o can not be of different type"""
    if isinstance(f, basestring):
        if o is None:
            o = f
        else:
            assert isinstance(o, basestring)
        try:
            subprocess.check_call(['pngquant', '--force', '--output', o, f])
        except subprocess.CalledProcessError:
            return False
        return True
    if not hasattr(f, 'read'):
        raise RuntimeError
    if o is None:
        o = f
    elif not hasattr(f, 'write'):
        raise RuntimeError
    f.seek(0)
    try:
        p = subprocess.Popen(['pngquant', '-'], stdin=subprocess.PIPE, stdout=subprocess.PIPE)
        r = p.communicate(f.read())[0]
    except IOError:
        r = None
    if r:
        truncate_file(o)
        o.write(r)
        return True
    return False

def extract_bag_of_words_from_corpus_parallel(corpus, lemmatizing='wordnet'):
    """This extracts one bag-of-words from a list of strings. The documents are mapped to parallel processes.

    Inputs: - corpus: A list of strings.
            - lemmatizing: A string containing one of the following: "porter", "snowball" or "wordnet".

    Output: - bag_of_words: This is a bag-of-words in python dictionary format.
            - lemma_to_keywordbag_total: Aggregated python dictionary that maps stems/lemmas to original topic keywords."""
    pool = Pool(processes=get_threads_number() * 2)
    partitioned_corpus = chunks(corpus, len(corpus) / get_threads_number())
    list_of_bags_of_words, list_of_lemma_to_keywordset_maps = pool.map(partial(clean_corpus_serial, lemmatizing=lemmatizing), partitioned_corpus)
    bag_of_words = reduce_list_of_bags_of_words(list_of_bags_of_words)
    lemma_to_keywordbag_total = defaultdict(lambda: defaultdict(int))
    for lemma_to_keywordbag in list_of_lemma_to_keywordset_maps:
        for lemma, keywordbag in lemma_to_keywordbag.items():
            for keyword, multiplicity in keywordbag.items():
                lemma_to_keywordbag_total[lemma][keyword] += multiplicity
    return (bag_of_words, lemma_to_keywordbag_total)

def middleware(func):
    """Executes routes.py route middleware"""
    @wraps(func)
    def parse(*args, **kwargs):
        """get middleware from route, execute middleware in order"""
        middleware = copy.deepcopy(kwargs['middleware'])
        kwargs.pop('middleware')
        if request.method == 'OPTIONS':
            return JsonResponse(200)
        if middleware is None:
            return func(*args, **kwargs)
        for mware in middleware:
            ware = mware()
            if ware.status is False:
                return ware.response
            return func(*args, **kwargs)
    return parse

def proto_refactor_files(dest_dir, namespace, namespace_path):
    """This method runs the refactoring on all the Protobuf files in the
    Dropsonde repo.

    Args:
        dest_dir (str): directory where the Protobuf files lives.
        namespace (str): the desired package name (i.e. "dropsonde.py2")
        namespace_path (str): the desired path corresponding to the package
                              name (i.e. "dropsonde/py2")"""
    for dn, dns, fns in os.walk(dest_dir):
        for fn in fns:
            fn = os.path.join(dn, fn)
            if fnmatch.fnmatch(fn, '*.proto'):
                data = proto_refactor(fn, namespace, namespace_path)
                with open(fn, 'w') as f:
                    f.write(data)

