def compute_distance(a, b):
    """Computes a modified Levenshtein distance between two strings, comparing the
    lowercase versions of each string and accounting for QWERTY distance.

    Arguments:
        - a (str) String to compare to 'b'
        - b (str) String to compare to 'a'

    Returns:
        - (int) Number representing closeness of 'a' and 'b' (lower is better)"""
    if not a:
        return len(b)
    if not b:
        return len(a)
    if a == b or str.lower(a) == str.lower(b):
        return 0
    a = str.lower(a)
    b = str.lower(b)
    vector_1 = [-1] * (len(b) + 1)
    vector_2 = [-1] * (len(b) + 1)
    for i in range(len(vector_1)):
        vector_1[i] = i
    for i in range(len(a)):
        vector_2[0] = i + 1
        for j in range(len(b)):
            penalty = 0 if a[i] == b[j] else compute_qwerty_distance(a[i], b[j])
            vector_2[j + 1] = min(vector_2[j] + 1, vector_1[j + 1] + 1, vector_1[j] + penalty)
        for j in range(len(vector_1)):
            vector_1[j] = vector_2[j]
    return vector_2[len(b)]

def get_defaults(path):
    """Reads file for configuration defaults.

    Arguments:
        - path (str) Absolute filepath (usually ~/.licenser)

    Returns:
        - (dict) Defaults for name, email, license, .txt extension"""
    defaults = {}
    if os.path.isfile(path):
        with open(path) as f:
            for line in f:
                line = line.strip()
                if '=' not in line or line.startswith('#'):
                    continue
                k, v = line.split('=', 1)
                v = v.strip('"').strip("'")
                defaults[k] = v
        return defaults
    else:
        return {}

def fmt_datetime(d, fmt='', local=True):
    """format date with local support
    ``d``: datetime to format
    ``fmt``: format, default is '%Y-%m-%d %H-%M'
    ``local``: format as local time"""
    if not d:
        return ''
    if local:
        from django.templatetags.tz import localtime
        d = localtime(d)
    if not fmt:
        fmt = '%Y-%m-%d %H-%M'
    return d.strftime(fmt)

def getversion(package):
    """Obtain the ``__version__`` for ``package``, looking at the egg information
    or the source repository's version control if necessary."""
    distribution = get_distribution(package)
    if distribution is None:
        raise RuntimeError("Can't find distribution {0}".format(package))
    repo_type = get_repo_type(distribution.location)
    if repo_type is None:
        return distribution.version
    return repo_type.get_version(distribution.location)

def version_from_frame(frame):
    """Given a ``frame``, obtain the version number of the module running there."""
    module = getmodule(frame)
    if module is None:
        s = '<unknown from {0}:{1}>'
        return s.format(frame.f_code.co_filename, frame.f_lineno)
    module_name = module.__name__
    variable = 'AUTOVERSION_{}'.format(module_name.upper())
    override = os.environ.get(variable, None)
    if override is not None:
        return override
    while True:
        try:
            get_distribution(module_name)
        except DistributionNotFound:
            module_name, dot, _ = module_name.partition('.')
            if dot == '':
                break
        else:
            return getversion(module_name)
    return None

def try_fix_num(n):
    """Return ``n`` as an integer if it is numeric, otherwise return the input"""
    if not n.isdigit():
        return n
    if n.startswith('0'):
        n = n.lstrip('0')
    if not n:
        n = '0'
    return int(n)

def tupleize_version(version):
    """Split ``version`` into a lexicographically comparable tuple.

    "1.0.3" -> ((1, 0, 3),)
    "1.0.3-dev" -> ((1, 0, 3), ("dev",))
    "1.0.3-rc-5" -> ((1, 0, 3), ("rc",), (5,))"""
    if version is None:
        return (('unknown',),)
    if version.startswith('<unknown'):
        return (('unknown',),)
    split = re.split('(?:\\.|(-))', version)
    parsed = tuple((try_fix_num(x) for x in split if x))
    def is_dash(s):
        return s == '-'
    grouped = groupby(parsed, is_dash)
    return tuple((tuple(group) for dash, group in grouped if not dash))

def _sort_modules(mods):
    """Always sort `index` or `README` as first filename in list."""
    def compare(x, y):
        x = x[1]
        y = y[1]
        if x == y:
            return 0
        if y.stem == '__init__.py':
            return 1
        if x.stem == '__init__.py' or x < y:
            return -1
        return 1
    return sorted(mods, key=cmp_to_key(compare))

def get_signature(name, thing):
    """Get the signature for a function or class, formatted nicely if possible.

    Parameters
    ----------
    name : str
        Name of the thing, used as the first part of the signature
    thing : class or function
        Thing to get the signature of"""
    if inspect.ismodule(thing):
        return ''
    if isinstance(thing, property):
        func_sig = name
    else:
        try:
            sig = inspect.signature(thing)
        except TypeError:
            sig = inspect.signature(thing.fget)
        except ValueError:
            return ''
        func_sig = f'{name}{sig}'
        try:
            mode = black.FileMode(line_length=80)
            func_sig = black.format_str(func_sig, mode=mode).strip()
        except (ValueError, TypeError):
            pass
    return f'```python\n{func_sig}\n```\n'

def _get_names(names, types):
    """Get names, bearing in mind that there might be no name,
    no type, and that the `:` separator might be wrongly used."""
    if types == '':
        try:
            names, types = names.split(':')
        except:
            pass
    return (names.split(','), types)

def _split_props(thing, doc):
    """Separate properties from other kinds of member."""
    props = inspect.getmembers(thing, lambda o: isinstance(o, property))
    ps = []
    docs = [(*_get_names(names, types), names, types, desc) for names, types, desc in doc]
    for prop_name, prop in props:
        in_doc = [d for d in enumerate(docs) if prop_name in d[0]]
        for d in in_doc:
            docs.remove(d)
        ps.append(prop_name)
    if len(docs) > 0:
        _, _, names, types, descs = zip(*docs)
        return (ps, zip(names, types, descs))
    return (ps, [])

