def egg_info_writer(cmd, basename, filename):
    """Read rcli configuration and write it out to the egg info.

    Args:
        cmd: An egg info command instance to use for writing.
        basename: The basename of the file to write.
        filename: The full path of the file to write into the egg info."""
    setupcfg = next((f for f in setuptools.findall() if os.path.basename(f) == 'setup.cfg'), None)
    if not setupcfg:
        return
    parser = six.moves.configparser.ConfigParser()
    parser.read(setupcfg)
    if not parser.has_section('rcli') or not parser.items('rcli'):
        return
    config = dict(parser.items('rcli'))
    for k, v in six.iteritems(config):
        if v.lower() in ('y', 'yes', 'true'):
            config[k] = True
        elif v.lower() in ('n', 'no', 'false'):
            config[k] = False
        else:
            try:
                config[k] = json.loads(v)
            except ValueError:
                pass
    cmd.write_file(basename, filename, json.dumps(config))

def calc(path):
    """Takes a path as an argument and returns the total size in bytes of the file
    or directory. If the path is a directory the size will be calculated
    recursively."""
    total = 0
    err = None
    if os.path.isdir(path):
        try:
            for entry in os.scandir(path):
                try:
                    is_dir = entry.is_dir(follow_symlinks=False)
                except (PermissionError, FileNotFoundError):
                    err = '!'
                    return (total, err)
                if is_dir:
                    result = calc(entry.path)
                    total += result[0]
                    err = result[1]
                    if err:
                        return (total, err)
                else:
                    try:
                        total += entry.stat(follow_symlinks=False).st_size
                    except (PermissionError, FileNotFoundError):
                        err = '!'
                        return (total, err)
        except (PermissionError, FileNotFoundError):
            err = '!'
            return (total, err)
    else:
        total += os.path.getsize(path)
    return (total, err)

def clean_dir(root):
    """remove .* and _* files and directories under root"""
    for x in root.walkdirs('.*', errors='ignore'):
        x.rmtree()
    for x in root.walkdirs('_*', errors='ignore'):
        x.rmtree()
    for x in root.walkfiles('.*', errors='ignore'):
        x.remove()
    for x in root.walkfiles('_*', errors='ignore'):
        x.remove()

def Deserializer(stream_or_string, **options):
    """Deserialize a stream or string of JSON data."""
    if isinstance(stream_or_string, (bytes, six.string_types)):
        stream_or_string = BytesIO(stream_or_string)
    try:
        def line_generator():
            for line in stream_or_string:
                yield json.loads(line.strip())
        for obj in PythonDeserializer(line_generator(), **options):
            yield obj
    except GeneratorExit:
        raise
    except Exception as e:
        six.reraise(DeserializationError, DeserializationError(e), sys.exc_info()[2])

def write_color_old(text, attr=None):
    u"""write text at current cursor position and interpret color escapes.

    return the number of characters written."""
    res = []
    chunks = terminal_escape.split(text)
    n = 0
    if attr is None:
        attr = 15
    for chunk in chunks:
        m = escape_parts.match(chunk)
        if m:
            for part in m.group(1).split(u';'):
                if part == u'0':
                    attr = 0
                elif part == u'7':
                    attr |= 16384
                if part == u'1':
                    attr |= 8
                elif len(part) == 2 and u'30' <= part <= u'37':
                    part = int(part) - 30
                    attr = attr & ~7 | (part & 1) << 2 | part & 2 | (part & 4) >> 2
                elif len(part) == 2 and u'40' <= part <= u'47':
                    part = int(part) - 40
                    attr = attr & ~112 | (part & 1) << 6 | (part & 2) << 4 | (part & 4) << 2
            continue
        n += len(chunk)
        if chunk:
            res.append((u'0x%x' % attr, chunk))
    return res

def import_settings_class(setting_name):
    """Return the class pointed to be an app setting variable."""
    config_value = getattr(settings, setting_name)
    if config_value is None:
        raise ImproperlyConfigured('Required setting not found: {0}'.format(setting_name))
    return import_class(config_value, setting_name)

def import_class(import_path, setting_name=None):
    """Import a class by name."""
    mod_name, class_name = import_path.rsplit('.', 1)
    mod = import_module_or_none(mod_name)
    if mod is not None:
        try:
            return getattr(mod, class_name)
        except AttributeError:
            pass
    if setting_name:
        raise ImproperlyConfigured('{0} does not point to an existing class: {1}'.format(setting_name, import_path))
    else:
        raise ImproperlyConfigured('Class not found: {0}'.format(import_path))

def import_apps_submodule(submodule):
    """Look for a submodule is a series of packages, e.g. ".pagetype_plugins" in all INSTALLED_APPS."""
    found_apps = []
    for appconfig in apps.get_app_configs():
        app = appconfig.name
        if import_module_or_none('{0}.{1}'.format(app, submodule)) is not None:
            found_apps.append(app)
    return found_apps

def import_module_or_none(module_label):
    """Imports the module with the given name.

    Returns None if the module doesn't exist,
    but it does propagates import errors in deeper modules."""
    try:
        return importlib.import_module(module_label)
    except ImportError:
        __, __, exc_traceback = sys.exc_info()
        frames = traceback.extract_tb(exc_traceback)
        frames = [f for f in frames if f[0] != '<frozen importlib._bootstrap>' and f[0] != IMPORT_PATH_IMPORTLIB and (not f[0].endswith(IMPORT_PATH_GEVENT)) and (not IMPORT_PATH_PYDEV in f[0])]
        if len(frames) > 1:
            raise
    return None

