def hdfFromKwargs(hdf=None, **kwargs):
    """If given an instance that has toHDF() method that method is invoked to get that object's HDF representation"""
    if not hdf:
        hdf = HDF()
    for key, value in kwargs.iteritems():
        if isinstance(value, dict):
            for k, v in value.iteritems():
                dkey = '%s.%s' % (key, k)
                args = {dkey: v}
                hdfFromKwargs(hdf=hdf, **args)
        elif isinstance(value, (list, tuple)):
            for i, item in enumerate(value):
                ikey = '%s.%s' % (key, i)
                if isinstance(item, (list, tuple)):
                    args = {ikey: item}
                    hdfFromKwargs(hdf=hdf, **args)
                elif isinstance(item, dict):
                    args = {ikey: item}
                    hdfFromKwargs(hdf=hdf, **args)
                elif getattr(item, 'HDF_ATTRIBUTES', False):
                    attrs = {}
                    for attr in item.HDF_ATTRIBUTES:
                        attrs[attr] = getattr(item, attr, '')
                    hdfFromKwargs(hdf=hdf, **{ikey: attrs})
                else:
                    hdf.setValue(ikey, str(item))
        elif getattr(value, 'HDF_ATTRIBUTES', False):
            attrs = {}
            for attr in value.HDF_ATTRIBUTES:
                attrs[attr] = getattr(value, attr, '')
            hdfFromKwargs(hdf=hdf, **{key: attrs})
        else:
            hdf.setValue(key, str(value))
    return hdf

def inherit_docstrings(cls):
    """Class decorator for inheriting docstrings.

    Automatically inherits base class doc-strings if not present in the
    derived class."""
    @functools.wraps(cls)
    def _inherit_docstrings(cls):
        if not isinstance(cls, (type, colorise.compat.ClassType)):
            raise RuntimeError('Type is not a class')
        for name, value in colorise.compat.iteritems(vars(cls)):
            if isinstance(getattr(cls, name), types.MethodType):
                if not getattr(value, '__doc__', None):
                    for base in cls.__bases__:
                        basemethod = getattr(base, name, None)
                        if basemethod and getattr(base, '__doc__', None):
                            value.__doc__ = basemethod.__doc__
        return cls
    return _inherit_docstrings(cls)

def memoize(func):
    """Cache forever."""
    cache = {}
    def memoizer():
        if 0 not in cache:
            cache[0] = func()
        return cache[0]
    return functools.wraps(func)(memoizer)

def getpreferredencoding():
