def decode(string, encoding=None, errors=None):
    """Decode from specified encoding.

    ``encoding`` defaults to the preferred encoding.
    ``errors`` defaults to the preferred error handler."""
    if encoding is None:
        encoding = getpreferredencoding()
    if errors is None:
        errors = getpreferrederrors()
    return string.decode(encoding, errors)

def traversal(root):
    """Tree traversal function that generates nodes. For each subtree, the
    deepest node is evaluated first. Then, the next-deepest nodes are
    evaluated until all the nodes in the subtree are generated."""
    stack = [root]
    while len(stack) > 0:
        node = stack.pop()
        if hasattr(node, 'children'):
            if node.children == set():
                try:
                    stack[-1].children.remove(node)
                except:
                    pass
                yield (node, stack)
            else:
                childnode = node.children.pop()
                stack += [node, childnode]
        else:
            children = [x for x in ast.iter_child_nodes(node)]
            node.children = set(children)
            stack.append(node)

def firstPass(ASTs, verbose):
    """Return a dictionary of function definition nodes, a dictionary of
    imported object names and a dictionary of imported module names. All three
    dictionaries use source file paths as keys."""
    fdefs = dict()
    cdefs = dict()
    imp_obj_strs = dict()
    imp_mods = dict()
    for root, path in ASTs:
        fdefs[path] = []
        fdefs[path].append(formatBodyNode(root, path))
        imp_obj_strs[path] = []
        imp_mods[path] = []
        cdefs[path] = []
        for node, stack in traversal(root):
            if isinstance(node, ast.FunctionDef):
                fdefs[path].append(formatFunctionNode(node, path, stack))
            elif isinstance(node, ast.ImportFrom):
                module = ia.getImportFromModule(node, path, verbose)
                if module:
                    fn_names = ia.getImportFromObjects(node)
                    for fn_name in fn_names:
                        imp_obj_strs[path].append((module, fn_name))
                elif verbose:
                    print('No module found ' + ast.dump(node))
            elif isinstance(node, ast.Import):
                module = ia.getImportModule(node, path, verbose)
                imp_mods[path].append(module)
            elif isinstance(node, ast.ClassDef):
                node.path = path
                cdefs[path].append(node)
    return (fdefs, imp_obj_strs, imp_mods, cdefs)

def getSourceFnDef(stack, fdefs, path):
    """VERY VERY SLOW"""
    found = False
    for x in stack:
        if isinstance(x, ast.FunctionDef):
            for y in fdefs[path]:
                if ast.dump(x) == ast.dump(y):
                    found = True
                    return y
            raise
    if not found:
        for y in fdefs[path]:
            if y.name == 'body':
                return y
    raise

def matchImpObjStrs(fdefs, imp_obj_strs, cdefs):
    """returns imp_funcs, a dictionary with filepath keys that contains
    lists of function definition nodes that were imported using
     from __ import __ style syntax. also returns imp_classes, which
    is the same for class definition nodes."""
    imp_funcs = dict()
    imp_classes = dict()
    for source in imp_obj_strs:
        if not imp_obj_strs[source]:
            continue
        imp_funcs[source] = []
        imp_classes[source] = []
        for mod, func in imp_obj_strs[source]:
            if mod not in fdefs:
                continue
            if func == '*':
                all_fns = [x for x in fdefs[mod] if x.name != 'body']
                imp_funcs[source] += all_fns
                all_cls = [x for x in cdefs[mod]]
                imp_classes[source] += all_cls
            else:
                fn_node = [x for x in fdefs[mod] if x.name == func]
                cls_node = [x for x in cdefs[mod] if x.name == func]
                if cls_node:
                    imp_classes[source] += cls_node
                if fn_node:
                    imp_funcs[source] += fn_node
                if not fn_node and (not cls_node):
                    pass
    return (imp_funcs, imp_classes)

def require_valid_type(value, *classes):
    """Checks that the specified object reference is instance of classes and
    throws a :py:class:`TypeError` if it is not.

    :param value: The object.
    :type value: object
    :param classes: The classes.
    :type classes: list(class)"""
    if value is not None:
        valid = False
        for auxiliar_class in classes:
            if isinstance(value, auxiliar_class):
                valid = True
                break
        if not valid:
            raise TypeError()

def parse_n_jobs(s):
    """This function parses a "math"-like string as a function of CPU count.
    It is useful for specifying the number of jobs.

    For example, on an 8-core machine::

        assert parse_n_jobs('0.5 * n') == 4
        assert parse_n_jobs('2n') == 16
        assert parse_n_jobs('n') == 8
        assert parse_n_jobs('4') == 4

    :param str s: string to parse for number of CPUs"""
    n_jobs = None
    N = cpu_count()
    if isinstance(s, int):
        n_jobs = s
    elif isinstance(s, float):
        n_jobs = int(s)
    elif isinstance(s, str):
        m = re.match('(\\d*(?:\\.\\d*)?)?(\\s*\\*?\\s*n)?$', s.strip())
        if m is None:
            raise ValueError('Unable to parse n_jobs="{}"'.format(s))
        k = float(m.group(1)) if m.group(1) else 1
        if m.group(2):
            n_jobs = k * N
        elif k < 1:
            n_jobs = k * N
        else:
            n_jobs = int(k)
    else:
        raise TypeError('n_jobs argument must be of type str, int, or float.')
    n_jobs = int(n_jobs)
    if n_jobs <= 0:
        warnings.warn('n_jobs={} is invalid. Setting n_jobs=1.'.format(n_jobs))
        n_jobs = 1
    return int(n_jobs)

def join_and(value):
    """Given a list of strings, format them with commas and spaces, but
    with 'and' at the end.

    >>> join_and(['apples', 'oranges', 'pears'])
    "apples, oranges, and pears"

    There is surely a better home for this"""
    value = [str(item) for item in value]
    if len(value) == 1:
        return value[0]
    if len(value) == 2:
        return '%s and %s' % (value[0], value[1])
    all_but_last = ', '.join(value[:-1])
    return '%s and %s' % (all_but_last, value[-1])

