def is_img_id_valid(img_id):
    """Checks if img_id is valid."""
    t = re.sub('[^a-z0-9_:\\-\\.]', '', img_id, re.IGNORECASE)
    t = re.sub('\\.+', '.', t)
    if img_id != t or img_id.count(':') != 1:
        return False
    profile, base_name = img_id.split(':', 1)
