def app_name_from_ini_parser(ini_parser):
    """Returns the name of the main application from the given ini file parser.
    The name is found as follows:
     * If the ini file contains only one app:<app name> section,
       return this app name;
     * Else, if the ini file contains a pipeline:main section, use
       the name of the innermost app;
     * Else raise ValueError.

    :param ini_parser: :class:`configparser.SafeConfigParser` instance with
        an ini file read."""
    app_names = [sect.split(':')[-1] for sect in ini_parser.sections() if sect[:4] == 'app:']
    if len(app_names) == 1:
        app_name = app_names[0]
    else:
        pp_sect_name = 'pipeline:main'
        if ini_parser.has_section(pp_sect_name):
            pipeline_apps = ini_parser.get(pp_sect_name, 'pipeline').split()
            app_name = pipeline_apps[-1]
        else:
            raise ValueError('Could not determine application name. You need to either define exactly one app:<app name> section or a pipeline:main section in your ini file.')
    return app_name

def generative(func):
    """Marks an instance method as generative."""
    def wrap(inst, *args, **kw):
        clone = type(inst).__new__(type(inst))
        clone.__dict__ = inst.__dict__.copy()
        return func(clone, *args, **kw)
    return update_wrapper(wrap, func)

def truncate(message, limit=500):
    """Truncates the message to the given limit length. The beginning and the
    end of the message are left untouched."""
    if len(message) > limit:
        trc_msg = ''.join([message[:limit // 2 - 2], ' .. ', message[len(message) - limit // 2 + 2:]])
    else:
        trc_msg = message
    return trc_msg

def form_lemma_tokeyword_map(annotated_nodes, node_to_lemma_tokeywordbag):
    """Forms the aggregated dictionary that maps lemmas/stems to the most popular topic keyword.

    Inputs: - annotated_nodes: A numpy array of anonymized nodes that are annotated.
            - node_to_lemma_tokeywordbag: A map from nodes to maps from lemmas to bags of keywords.

    Output: - lemma_to_keyword: A dictionary that maps lemmas to keywords."""
    lemma_to_keywordbag = defaultdict(lambda: defaultdict(int))
    for node in annotated_nodes:
        for lemma, keywordbag in node_to_lemma_tokeywordbag[node].items():
            for keyword, multiplicity in keywordbag.items():
                lemma_to_keywordbag[lemma][keyword] += multiplicity
    lemma_to_keyword = dict()
    for lemma, keywordbag in lemma_to_keywordbag.items():
        lemma_to_keyword[lemma] = max(keywordbag.items(), key=itemgetter(1))[0]
    return lemma_to_keyword

