            raise RuntimeError('Invalid host API')
        assert info.structVersion == 1
        return {'name': ffi.string(info.name).decode(errors='ignore'), 'default_input_device': info.defaultInputDevice, 'default_output_device': info.defaultOutputDevice}

def device_info(index=None):
    """Return a generator with information about each device.

    If index is given, only one dictionary for the given device is
    returned."""
    if index is None:
        return (device_info(i) for i in range(_pa.Pa_GetDeviceCount()))
    else:
        info = _pa.Pa_GetDeviceInfo(index)
        if not info:
            raise RuntimeError('Invalid device')
        assert info.structVersion == 2
        if 'DirectSound' in hostapi_info(info.hostApi)['name']:
            enc = 'mbcs'
        else:
            enc = 'utf-8'
        return {'name': ffi.string(info.name).decode(encoding=enc, errors='ignore'), 'hostapi': info.hostApi, 'max_input_channels': info.maxInputChannels, 'max_output_channels': info.maxOutputChannels, 'default_low_input_latency': info.defaultLowInputLatency, 'default_low_output_latency': info.defaultLowOutputLatency, 'default_high_input_latency': info.defaultHighInputLatency, 'default_high_output_latency': info.defaultHighOutputLatency, 'default_samplerate': info.defaultSampleRate}

def _get_stream_parameters(kind, device, channels, dtype, latency, samplerate):
    """Generate PaStreamParameters struct."""
    if device is None:
        if kind == 'input':
            device = _pa.Pa_GetDefaultInputDevice()
        elif kind == 'output':
            device = _pa.Pa_GetDefaultOutputDevice()
    info = device_info(device)
    if channels is None:
        channels = info['max_' + kind + '_channels']
    dtype = np.dtype(dtype)
    try:
        sample_format = _np2pa[dtype]
    except KeyError:
        raise ValueError('Invalid ' + kind + ' sample format')
    if samplerate is None:
        samplerate = info['default_samplerate']
    parameters = ffi.new('PaStreamParameters*', (device, channels, sample_format, latency, ffi.NULL))
    return (parameters, dtype, samplerate)

def _split(value):
    """Split input/output value into two values."""
    if isinstance(value, str):
        return (value, value)
    try:
        invalue, outvalue = value
    except TypeError:
        invalue = outvalue = value
    except ValueError:
        raise ValueError('Only single values and pairs are allowed')
    return (invalue, outvalue)

def get_config_from_options(**options):
    """Get config file fragment reflecting command-line options."""
    data = []
    data.append('[supervisord]\n')
    if options.get('daemonize', False):
        data.append('nodaemon=false\n')
    else:
        data.append('nodaemon=true\n')
    if options.get('pidfile', None):
        data.append('pidfile=%s\n' % (options['pidfile'],))
    if options.get('logfile', None):
        data.append('logfile=%s\n' % (options['logfile'],))
    for progname in options.get('launch', None) or []:
        data.append('[program:%s]\nautostart=true\n' % (progname,))
    for progname in options.get('nolaunch', None) or []:
        data.append('[program:%s]\nautostart=false\n' % (progname,))
    for progname in options.get('include', None) or []:
        data.append('[program:%s]\nexclude=false\n' % (progname,))
    for progname in options.get('exclude', None) or []:
        data.append('[program:%s]\nexclude=true\n' % (progname,))
    if options.get('autoreload', None):
        data.append('[program:autoreload]\nexclude=false\nautostart=true\n')
        data.append('[program:__defaults__]\nautoreload=false\n')
        for progname in options['autoreload']:
            data.append('[program:%s]\nautoreload=true\n' % (progname,))
    if options.get('noreload', False):
        data.append('[program:autoreload]\nexclude=true\n')
    return ''.join(data)

def set_if_missing(cfg, section, option, value):
    """If the given option is missing, set to the given value."""
    try:
        cfg.get(section, option)
    except NoSectionError:
        cfg.add_section(section)
        cfg.set(section, option, value)
    except NoOptionError:
        cfg.set(section, option, value)

def rerender_options(options):
    """Helper function to re-render command-line options.

    This assumes that command-line options use the same name as their
    key in the options dictionary."""
    args = []
    for name, value in options.iteritems():
        name = name.replace('_', '-')
        if value is None:
            pass
        elif isinstance(value, bool):
            if value:
                args.append('--%s' % (name,))
        elif isinstance(value, list):
            for item in value:
                args.append('--%s=%s' % (name, item))
        else:
            args.append('--%s=%s' % (name, value))
    return ' '.join(args)

def get_class_that_defined_method(fun):
    """Tries to find the class that defined the specified method. Will not work for nested classes
    (locals).

    Args:
        fun: Function / Method

    Returns:
        Returns the class which defines the given method / function."""
    if inspect.ismethod(fun):
        for cls in inspect.getmro(fun.__self__.__class__):
            if cls.__dict__.get(fun.__name__) is fun:
                return cls
        fun = fun.__func__
    if inspect.isfunction(fun):
        cls = getattr(inspect.getmodule(fun), fun.__qualname__.split('.<locals>', 1)[0].rsplit('.', 1)[0], None)
        if isinstance(cls, type):
            return cls
    return getattr(fun, '__objclass__', None)

def get_field_mro(cls, field_name):
    """Goes up the mro and looks for the specified field."""
    res = set()
    if hasattr(cls, '__mro__'):
        for _class in inspect.getmro(cls):
            values_ = getattr(_class, field_name, None)
            if values_ is not None:
                res = res.union(set(make_list(values_)))
    return res

def raise_on_major_version_mismatch(work_request, local_version):
    """Raises error if major version is different. Other wise logs the difference.
    :param work_request: WorkRequest: request that had a different version
    :param local_version: str: our version string that does not match message.version"""
    request_major_version = get_major_version(work_request.version)
    local_major_version = get_major_version(local_version)
    if request_major_version != local_major_version:
        raise ValueError('Received major version mismatch. request:{} local:{}'.format(work_request.version, local_version))
    else:
        logging.info('Ignoring non-major version mismatch request:{} local:{}'.format(work_request.version, local_version))

def get_related_galleries(gallery, count=5):
    """Gets latest related galleries from same section as originating gallery.

    Count defaults to five but can be overridden.

    Usage: {% get_related_galleries gallery <10> %}"""
    try:
        cat = gallery.sections.all()[0]
        related = cat.gallery_categories.filter(published=True).exclude(id=gallery.id).order_by('-id')[:count]
    except:
        related = None
    return {'related': related, 'MEDIA_URL': settings.MEDIA_URL}

