    return actual_decorator

def more_than_one_index(s, brackets=2):
    """Search for two sets of [] []
    @param s: string to search"""
    start = 0
    brackets_num = 0
    while start != -1 and brackets_num < brackets:
        start = s.find('[', start)
        if start == -1:
            break
        start = s.find(']', start)
        brackets_num += 1
    if start != -1:
        return True
    return False

def parser_helper(key, val):
    """Helper for parser function
    @param key:
    @param val:"""
    start_bracket = key.find('[')
    end_bracket = key.find(']')
    pdict = {}
    if has_variable_name(key):
        pdict[key[:key.find('[')]] = parser_helper(key[start_bracket:], val)
    elif more_than_one_index(key):
        newkey = get_key(key)
        newkey = int(newkey) if is_number(newkey) else newkey
        pdict[newkey] = parser_helper(key[end_bracket + 1:], val)
    else:
        newkey = key
        if start_bracket != -1:
            newkey = get_key(key)
            if newkey is None:
                raise MalformedQueryStringError
        newkey = int(newkey) if is_number(newkey) else newkey
        if key == u'[]':
            val = int(val) if is_number(val) else val
        pdict[newkey] = val
    return pdict

def _normalize(d):
    """The above parse function generates output of list in dict form
    i.e. {'abc' : {0: 'xyz', 1: 'pqr'}}. This function normalize it and turn
    them into proper data type, i.e. {'abc': ['xyz', 'pqr']}

    Note: if dict has element starts with 10, 11 etc.. this function won't fill
    blanks.
    for eg: {'abc': {10: 'xyz', 12: 'pqr'}} will convert to
    {'abc': ['xyz', 'pqr']}"""
    newd = {}
    if isinstance(d, dict) == False:
        return d
    for k, v in six.iteritems(d):
        if isinstance(v, dict):
            first_key = next(iter(six.viewkeys(v)))
            if isinstance(first_key, int):
                temp_new = []
                for k1, v1 in v.items():
                    temp_new.append(_normalize(v1))
                newd[k] = temp_new
            elif first_key == '':
                newd[k] = v.values()[0]
            else:
                newd[k] = _normalize(v)
        else:
            newd[k] = v
    return newd

def includeme(config):
    """:type config: :class:`pyramid.config.Configurator`"""
    settings = config.registry.settings
    swagger_versions = get_swagger_versions(settings)
    config.add_renderer('yaml', 'pyramid_swagger.api.YamlRendererFactory')
    settings['pyramid_swagger.schema12'] = None
    settings['pyramid_swagger.schema20'] = None
    if SWAGGER_12 in swagger_versions:
        settings['pyramid_swagger.schema12'] = get_swagger_schema(settings)
    if SWAGGER_20 in swagger_versions:
        settings['pyramid_swagger.schema20'] = get_swagger_spec(settings)
    config.add_tween('pyramid_swagger.tween.validation_tween_factory', under=pyramid.tweens.EXCVIEW)
    config.add_renderer('pyramid_swagger', PyramidSwaggerRendererFactory())
    if settings.get('pyramid_swagger.enable_api_doc_views', True):
        if SWAGGER_12 in swagger_versions:
            register_api_doc_endpoints(config, settings['pyramid_swagger.schema12'].get_api_doc_endpoints())
        if SWAGGER_20 in swagger_versions:
            register_api_doc_endpoints(config, build_swagger_20_swagger_schema_views(config), base_path=settings.get('pyramid_swagger.base_path_api_docs', ''))

def build_param_schema(schema, param_type):
    """Turn a swagger endpoint schema into an equivalent one to validate our
    request.

    As an example, this would take this swagger schema:
        {
            "paramType": "query",
            "name": "query",
            "description": "Location to query",
            "type": "string",
            "required": true
        }
    To this jsonschema:
        {
            "type": "object",
            "additionalProperties": "False",
            "properties:": {
                "description": "Location to query",
                "type": "string",
                "required": true
            }
        }
    Which we can then validate against a JSON object we construct from the
    pyramid request."""
    properties = filter_params_by_type(schema, param_type)
    if not properties:
        return
    return {'type': 'object', 'properties': dict(((p['name'], p) for p in properties)), 'additionalProperties': param_type == 'header'}

def type_validator(validator, types, instance, schema):
    """Swagger 1.2 supports parameters of 'type': 'File'. Skip validation of
    the 'type' field in this case."""
    if schema.get('type') == 'File':
        return []
    return _validators.type_draft3(validator, types, instance, schema)

def required_validator(validator, req, instance, schema):
    """Swagger 1.2 expects `required` to be a bool in the Parameter object, but
    a list of properties in a Model object."""
    if schema.get('paramType'):
        if req is True and (not instance):
            return [ValidationError('%s is required' % schema['name'])]
        return []
    return _validators.required_draft4(validator, req, instance, schema)

def build_request_to_validator_map(schema, resolver):
    """Build a mapping from :class:`RequestMatcher` to :class:`ValidatorMap`
    for each operation in the API spec. This mapping may be used to retrieve
    the appropriate validators for a request."""
    schema_models = schema.get('models', {})
    return dict(((RequestMatcher(api['path'], operation['method']), ValidatorMap.from_operation(operation, schema_models, resolver)) for api in schema['apis'] for operation in api['operations']))

def get_swagger_objects(settings, route_info, registry):
    """Returns appropriate swagger handler and swagger spec schema.

    Swagger Handler contains callables that isolate implementation differences
    in the tween to handle both Swagger 1.2 and Swagger 2.0.

    Exception is made when `settings.prefer_20_routes` are non-empty and
    ['1.2', '2.0'] both are present in available swagger versions. In this
    special scenario, '2.0' spec is chosen only for requests which are listed
    in the `prefer_20_routes`. This helps in incremental migration of
    routes from v1.2 to v2.0 by making moving to v2.0 opt-in.

    :rtype: (:class:`SwaggerHandler`,
             :class:`pyramid_swagger.model.SwaggerSchema` OR
                :class:`bravado_core.spec.Spec`)"""
    enabled_swagger_versions = get_swagger_versions(registry.settings)
    schema12 = registry.settings['pyramid_swagger.schema12']
    schema20 = registry.settings['pyramid_swagger.schema20']
    fallback_to_swagger12_route = SWAGGER_20 in enabled_swagger_versions and SWAGGER_12 in enabled_swagger_versions and settings.prefer_20_routes and route_info.get('route') and (route_info['route'].name not in settings.prefer_20_routes)
    if fallback_to_swagger12_route:
        return (settings.swagger12_handler, schema12)
    if SWAGGER_20 in enabled_swagger_versions:
        return (settings.swagger20_handler, schema20)
    if SWAGGER_12 in enabled_swagger_versions:
        return (settings.swagger12_handler, schema12)

def build_swagger12_handler(schema):
    """Builds a swagger12 handler or returns None if no schema is present.

    :type schema: :class:`pyramid_swagger.model.SwaggerSchema`
    :rtype: :class:`SwaggerHandler` or None"""
    if schema:
        return SwaggerHandler(op_for_request=schema.validators_for_request, handle_request=handle_request, handle_response=validate_response)

def get_swagger_versions(settings):
    """Validates and returns the versions of the Swagger Spec that this pyramid
    application supports.

    :type settings: dict
    :return: list of strings. eg ['1.2', '2.0']
    :raises: ValueError when an unsupported Swagger version is encountered."""
    swagger_versions = set(aslist(settings.get('pyramid_swagger.swagger_versions', DEFAULT_SWAGGER_VERSIONS)))
    if len(swagger_versions) == 0:
        raise ValueError('pyramid_swagger.swagger_versions is empty')
    for swagger_version in swagger_versions:
        if swagger_version not in SUPPORTED_SWAGGER_VERSIONS:
            raise ValueError('Swagger version {0} is not supported.'.format(swagger_version))
    return swagger_versions

def build_swagger_12_resource_listing(resource_listing):
    """:param resource_listing: JSON representing a Swagger 1.2 resource listing
    :type resource_listing: dict
    :rtype: :class:`pyramid_swagger.model.PyramidEndpoint`"""
    def view_for_resource_listing(request):
        return resource_listing
    return PyramidEndpoint(path='', route_name='pyramid_swagger.swagger12.api_docs', view=view_for_resource_listing, renderer='json')

def build_swagger_12_api_declaration_view(api_declaration_json):
    """Thanks to the magic of closures, this means we gracefully return JSON
    without file IO at request time."""
    def view_for_api_declaration(request):
        return dict(api_declaration_json, basePath=str(request.application_url))
    return view_for_api_declaration

def find_resource_paths(schema_dir):
    """The inverse of :func:`find_resource_names` used to generate
    a resource listing from a directory of swagger api docs."""
    def not_api_doc_file(filename):
        return not filename.endswith(API_DOCS_FILENAME)
    def not_swagger_dot_json(filename):
        return not os.path.basename(filename) == 'swagger.json'
    def filename_to_path(filename):
        filename, _ext = os.path.splitext(os.path.basename(filename))
        return '/' + filename
    filenames = glob.glob('{0}/*.json'.format(schema_dir))
    return map(filename_to_path, filter(not_swagger_dot_json, filter(not_api_doc_file, sorted(filenames))))

def build_schema_mapping(schema_dir, resource_listing):
    """Discovers schema file locations and relations.

    :param schema_dir: the directory schema files live inside
    :type schema_dir: string
    :param resource_listing: A swagger resource listing
    :type  resource_listing: dict
    :returns: a mapping from resource name to file path
    :rtype: dict"""
    def resource_name_to_filepath(name):
        return os.path.join(schema_dir, '{0}.json'.format(name))
    return dict(((resource, resource_name_to_filepath(resource)) for resource in find_resource_names(resource_listing)))

def _load_resource_listing(resource_listing):
    """Load the resource listing from file, handling errors.

    :param resource_listing: path to the api-docs resource listing file
    :type  resource_listing: string
    :returns: contents of the resource listing file
    :rtype: dict"""
    try:
        with open(resource_listing) as resource_listing_file:
            return simplejson.load(resource_listing_file)
    except IOError:
        raise ResourceListingNotFoundError('No resource listing found at {0}. Note that your json file must be named {1}'.format(resource_listing, API_DOCS_FILENAME))

def export_obj(vertices, triangles, filename):
    """Exports a mesh in the (.obj) format."""
    with open(filename, 'w') as fh:
        for v in vertices:
            fh.write('v {} {} {}\n'.format(*v))
        for f in triangles:
            fh.write('f {} {} {}\n'.format(*f + 1))

def export_off(vertices, triangles, filename):
    """Exports a mesh in the (.off) format."""
    with open(filename, 'w') as fh:
        fh.write('OFF\n')
        fh.write('{} {} 0\n'.format(len(vertices), len(triangles)))
        for v in vertices:
            fh.write('{} {} {}\n'.format(*v))
        for f in triangles:
            fh.write('3 {} {} {}\n'.format(*f))

def auto_doc(tool, nco_self):
    """Generate the __doc__ string of the decorated function by calling the nco help command

    :param tool:
    :param nco_self:
    :return:"""
    def desc(func):
        func.__doc__ = nco_self.call([tool, '--help']).get('stdout')
        return func
    return desc

def seed(data, entropy=None):
    """Seeds random generator with data.
    If entropy is not None, it should be floating point(double)
    value estimating amount of entropy  in the data (in bytes)."""
    if not isinstance(data, bintype):
        raise TypeError('A string is expected')
    ptr = c_char_p(data)
    size = len(data)
    if entropy is None:
        libcrypto.RAND_seed(ptr, size)
    else:
        libcrypto.RAND_add(ptr, size, entropy)

def create(dotted, shortname, longname):
    """Creates new OID in the database

    @param dotted - dotted-decimal representation of new OID
    @param shortname - short name for new OID
    @param longname - long name for new OID

    @returns Oid object corresponding to new OID

    This function should be used with exreme care. Whenever
    possible, it is better to add new OIDs via OpenSSL configuration
    file

    Results of calling this function twice for same OIDor for
    Oid alredy in database are undefined"""
    if pyver > 2:
        dotted = dotted.encode('ascii')
        shortname = shortname.encode('utf-8')
        longname = longname.encode('utf-8')
    nid = libcrypto.OBJ_create(dotted, shortname, longname)
    if nid == 0:
        raise LibCryptoError('Problem adding new OID to the  database')
    return Oid(nid)

def _password_callback(c):
    """Converts given user function or string to C password callback
    function, passable to openssl.

    IF function is passed, it would be called upon reading or writing
    PEM format private key with one argument which is True if we are
    writing key and should verify passphrase and false if we are reading"""
    if c is None:
        return PW_CALLBACK_FUNC(0)
    if callable(c):
        if pyver == 2:
            def __cb(buf, length, rwflag, userdata):
                pwd = c(rwflag)
                cnt = min(len(pwd), length)
                memmove(buf, pwd, cnt)
                return cnt
        else:
            def __cb(buf, length, rwflag, userdata):
                pwd = c(rwflag).encode('utf-8')
                cnt = min(len(pwd), length)
                memmove(buf, pwd, cnt)
                return cnt
    else:
        if pyver > 2:
            c = c.encode('utf-8')
        def __cb(buf, length, rwflag, userdata):
            cnt = min(len(c), length)
            memmove(buf, c, cnt)
            return cnt
    return PW_CALLBACK_FUNC(__cb)

def CMS(data, format='PEM'):
    """Factory function to create CMS objects from received messages.

    Parses CMS data and returns either SignedData or EnvelopedData
    object. format argument can be either "PEM" or "DER".

    It determines object type from the contents of received CMS
    structure."""
    bio = Membio(data)
    if format == 'PEM':
        ptr = libcrypto.PEM_read_bio_CMS(bio.bio, None, None, None)
    else:
        ptr = libcrypto.d2i_CMS_bio(bio.bio, None)
    if ptr is None:
        raise CMSError('Error parsing CMS data')
    typeoid = Oid(libcrypto.OBJ_obj2nid(libcrypto.CMS_get0_type(ptr)))
    if typeoid.shortname() == 'pkcs7-signedData':
        return SignedData(ptr)
    elif typeoid.shortname() == 'pkcs7-envelopedData':
        return EnvelopedData(ptr)
    elif typeoid.shortname() == 'pkcs7-encryptedData':
        return EncryptedData(ptr)
    else:
        raise NotImplementedError('cannot handle ' + typeoid.shortname())

def _X509__asn1date_to_datetime(asn1date):
    """Converts openssl ASN1_TIME object to python datetime.datetime"""
    bio = Membio()
    libcrypto.ASN1_TIME_print(bio.bio, asn1date)
    pydate = datetime.strptime(str(bio), '%b %d %H:%M:%S %Y %Z')
    return pydate.replace(tzinfo=utc)

def pbkdf2(password, salt, outlen, digesttype='sha1', iterations=2000):
    """Interface to PKCS5_PBKDF2_HMAC function
    Parameters:

    @param password - password to derive key from
    @param salt - random salt to use for key derivation
    @param outlen - number of bytes to derive
    @param digesttype - name of digest to use to use (default sha1)
    @param iterations - number of iterations to use

    @returns outlen bytes of key material derived from password and salt"""
    dgst = DigestType(digesttype)
    out = create_string_buffer(outlen)
    if isinstance(password, chartype):
        pwd = password.encode('utf-8')
    else:
        pwd = password
    res = libcrypto.PKCS5_PBKDF2_HMAC(pwd, len(pwd), salt, len(salt), iterations, dgst.digest, outlen, out)
    if res <= 0:
        raise LibCryptoError('error computing PBKDF2')
    return out.raw

def new(algname, key, encrypt=True, iv=None):
    """Returns new cipher object ready to encrypt-decrypt data

    @param algname - string algorithm name like in opemssl command
                     line
    @param key - binary string representing ciher key
    @param encrypt - if True (default) cipher would be initialized
                    for encryption, otherwise - for decrypton
    @param iv - initialization vector"""
    ciph_type = CipherType(algname)
    return Cipher(ciph_type, key, iv, encrypt)

def get_user_password(env, param, force=False):
    """Allows the user to print the credential for a particular keyring entry
    to the screen"""
    username = utils.assemble_username(env, param)
    if not utils.confirm_credential_display(force):
        return
    password = password_get(username)
    if password:
        return (username, password)
    else:
        return False

def pull_env_credential(env, param, value):
    """Dissects a keyring credential lookup string from the supernova config file
    and returns the username/password combo"""
    rex = 'USE_KEYRING\\[([\'"])(.*)\\1\\]'
    if value == 'USE_KEYRING':
        username = utils.assemble_username(env, param)
    else:
        global_identifier = re.match(rex, value).group(2)
        username = utils.assemble_username('global', global_identifier)
    return (username, password_get(username))

def password_get(username=None):
    """Retrieves a password from the keychain based on the environment and
    configuration parameter pair.

    If this fails, None is returned."""
    password = keyring.get_password('supernova', username)
    if password is None:
        split_username = tuple(username.split(':'))
        msg = "Couldn't find a credential for {0}:{1}. You need to set one with: supernova-keyring -s {0} {1}".format(*split_username)
        raise LookupError(msg)
    else:
        return password.encode('ascii')

def set_user_password(environment, parameter, password):
    """Sets a user's password in the keyring storage"""
    username = '%s:%s' % (environment, parameter)
    return password_set(username, password)

def password_set(username=None, password=None):
    """Stores a password in a keychain for a particular environment and
    configuration parameter pair."""
    result = keyring.set_password('supernova', username, password)
    if result is None:
        return True
    else:
        return False

def prep_shell_environment(nova_env, nova_creds):
    """Appends new variables to the current shell environment temporarily."""
    new_env = {}
    for key, value in prep_nova_creds(nova_env, nova_creds):
        if type(value) == six.binary_type:
            value = value.decode()
        new_env[key] = value
    return new_env

def prep_nova_creds(nova_env, nova_creds):
    """Finds relevant config options in the supernova config and cleans them
    up for novaclient."""
    try:
        raw_creds = dict(nova_creds.get('DEFAULT', {}), **nova_creds[nova_env])
    except KeyError:
        msg = '{0} was not found in your supernova configuration file'.format(nova_env)
        raise KeyError(msg)
    proxy_re = re.compile('(^http_proxy|^https_proxy)')
    creds = []
    for param, value in raw_creds.items():
        if not proxy_re.match(param):
            param = param.upper()
        if not hasattr(value, 'startswith'):
            continue
        if value.startswith('USE_KEYRING'):
            username, credential = pull_env_credential(nova_env, param, value)
        else:
            credential = value.strip('"\'')
        if not credential:
            raise LookupError('No matching credentials found in keyring')
        creds.append((param, credential))
    return creds

def load_config(config_file_override=False):
    """Pulls the supernova configuration file and reads it"""
    supernova_config = get_config_file(config_file_override)
    supernova_config_dir = get_config_directory(config_file_override)
    if not supernova_config and (not supernova_config_dir):
        raise Exception("Couldn't find a valid configuration file to parse")
    nova_creds = ConfigObj()
    if supernova_config:
        try:
            nova_creds.merge(ConfigObj(supernova_config))
        except:
            raise "There's an error in your configuration file"
    if supernova_config_dir:
        for dir_file in os.listdir(supernova_config_dir):
            full_path = ''.join((supernova_config_dir, dir_file))
            try:
                nova_creds.merge(ConfigObj(full_path))
            except:
                msg = "Skipping '%s', Parsing Error.".format(full_path)
                print(msg)
    create_dynamic_configs(nova_creds)
    return nova_creds

def get_config_file(override_files=False):
    """Looks for the most specific configuration file available.  An override
    can be provided as a string if needed."""
    if override_files:
        if isinstance(override_files, six.string_types):
            possible_configs = [override_files]
        else:
            raise Exception('Config file override must be a string')
    else:
        xdg_config_home = os.environ.get('XDG_CONFIG_HOME') or os.path.expanduser('~/.config')
        possible_configs = [os.path.join(xdg_config_home, 'supernova'), os.path.expanduser('~/.supernova'), '.supernova']
    for config_file in reversed(possible_configs):
        if os.path.isfile(config_file):
            return config_file
    return False

def get_config_directory(override_files=False):
    """Looks for the most specific configuration directory possible, in order to
    load individual configuration files."""
    if override_files:
        possible_dirs = [override_files]
    else:
        xdg_config_home = os.environ.get('XDG_CONFIG_HOME') or os.path.expanduser('~/.config')
        possible_dirs = [os.path.join(xdg_config_home, 'supernova.d/'), os.path.expanduser('~/.supernova.d/'), '.supernova.d/']
    for config_dir in reversed(possible_dirs):
        if os.path.isdir(config_dir):
            return config_dir
    return False

def check_for_debug(supernova_args, nova_args):
    """If the user wanted to run the executable with debugging enabled, we need
    to apply the correct arguments to the executable.

    Heat is a corner case since it uses -d instead of --debug."""
    if supernova_args['debug'] and supernova_args['executable'] == 'heat':
        nova_args.insert(0, '-d ')
    elif supernova_args['debug']:
        nova_args.insert(0, '--debug ')
    return nova_args

def check_for_bypass_url(raw_creds, nova_args):
    """Return a list of extra args that need to be passed on cmdline to nova."""
    if 'BYPASS_URL' in raw_creds.keys():
        bypass_args = ['--bypass-url', raw_creds['BYPASS_URL']]
        nova_args = bypass_args + nova_args
    return nova_args

def check_environment_presets():
    """Checks for environment variables that can cause problems with supernova"""
    presets = [x for x in os.environ.copy().keys() if x.startswith('NOVA_') or x.startswith('OS_')]
    if len(presets) < 1:
        return True
    else:
        click.echo('_' * 80)
        click.echo('*WARNING* Found existing environment variables that may cause conflicts:')
        for preset in presets:
            click.echo('  - %s' % preset)
        click.echo('_' * 80)
        return False

def get_envs_in_group(group_name, nova_creds):
    """Takes a group_name and finds any environments that have a SUPERNOVA_GROUP
    configuration line that matches the group_name."""
    envs = []
    for key, value in nova_creds.items():
        supernova_groups = value.get('SUPERNOVA_GROUP', [])
        if hasattr(supernova_groups, 'startswith'):
            supernova_groups = [supernova_groups]
        if group_name in supernova_groups:
            envs.append(key)
        elif group_name == 'all':
            envs.append(key)
    return envs

def is_valid_group(group_name, nova_creds):
    """Checks to see if the configuration file contains a SUPERNOVA_GROUP
    configuration option."""
    valid_groups = []
    for key, value in nova_creds.items():
        supernova_groups = value.get('SUPERNOVA_GROUP', [])
        if hasattr(supernova_groups, 'startswith'):
            supernova_groups = [supernova_groups]
        valid_groups.extend(supernova_groups)
    valid_groups.append('all')
    if group_name in valid_groups:
        return True
    else:
        return False

def rm_prefix(name):
    """Removes nova_ os_ novaclient_ prefix from string."""
    if name.startswith('nova_'):
        return name[5:]
    elif name.startswith('novaclient_'):
        return name[11:]
    elif name.startswith('os_'):
        return name[3:]
    else:
        return name

def __pad(strdata):
    """Pads `strdata` with a Request's callback argument, if specified, or does
    nothing."""
    if request.args.get('callback'):
        return '%s(%s);' % (request.args.get('callback'), strdata)
    else:
        return strdata

def __dumps(*args, **kwargs):
    """Serializes `args` and `kwargs` as JSON. Supports serializing an array
    as the top-level object, if it is the only argument."""
    indent = None
    if current_app.config.get('JSONIFY_PRETTYPRINT_REGULAR', False) and (not request.is_xhr):
        indent = 2
    return json.dumps(args[0] if len(args) is 1 else dict(*args, **kwargs), indent=indent)

def convert_attribute_to_string(value):
    """Convert an attribute value to a string.

    Converts the attribute value to a string if possible (get ``None``
    if isn't a string type).

    .. versionadded:: 0.2

    Parameters
    ----------
    value :
        The Attribute value.

    Returns
    -------
    s : str or None
        The ``str`` value of the attribute if the conversion is
        possible, or ``None`` if not."""
    if value is None:
        return value
    elif sys.hexversion >= 50331648 and isinstance(value, str) or (sys.hexversion < 50331648 and isinstance(value, unicode)):
        return value
    elif isinstance(value, bytes):
        return value.decode()
    elif isinstance(value, np.unicode_):
        return str(value)
    elif isinstance(value, np.bytes_):
        return value.decode()
    else:
        return None

def __get_cycle(graph, ordering, parent_lookup):
    """Gets the main cycle of the dfs tree."""
    root_node = ordering[0]
    for i in range(2, len(ordering)):
        current_node = ordering[i]
        if graph.adjacent(current_node, root_node):
            path = []
            while current_node != root_node:
                path.append(current_node)
                current_node = parent_lookup[current_node]
            path.append(root_node)
            path.reverse()
            return path

def __get_segments_from_cycle(graph, cycle_path):
    """Calculates the segments that emanate from the main cycle."""
    list_of_segments = []
    for n in cycle_path[::-1]:
        segments = __get_segments_from_node(n, graph)
        if segments:
            list_of_segments.append(segments)
    return list_of_segments

def make_subgraph(graph, vertices, edges):
    """Converts a subgraph given by a list of vertices and edges into a graph object."""
    local_graph = copy.deepcopy(graph)
    edges_to_delete = [x for x in local_graph.get_all_edge_ids() if x not in edges]
    for e in edges_to_delete:
        local_graph.delete_edge_by_id(e)
    nodes_to_delete = [x for x in local_graph.get_all_node_ids() if x not in vertices]
    for n in nodes_to_delete:
        local_graph.delete_node(n)
    return local_graph

def remove_duplicate_edges_directed(dg):
    """Removes duplicate edges from a directed graph."""
    lookup = {}
    edges = sorted(dg.get_all_edge_ids())
    for edge_id in edges:
        e = dg.get_edge(edge_id)
        tpl = e['vertices']
        if tpl in lookup:
            dg.delete_edge_by_id(edge_id)
        else:
            lookup[tpl] = edge_id

def remove_duplicate_edges_undirected(udg):
    """Removes duplicate edges from an undirected graph."""
    lookup = {}
    edges = sorted(udg.get_all_edge_ids())
    for edge_id in edges:
        e = udg.get_edge(edge_id)
        tpl_a = e['vertices']
        tpl_b = (tpl_a[1], tpl_a[0])
        if tpl_a in lookup or tpl_b in lookup:
            udg.delete_edge_by_id(edge_id)
        else:
            lookup[tpl_a] = edge_id
            lookup[tpl_b] = edge_id

def get_vertices_from_edge_list(graph, edge_list):
    """Transforms a list of edges into a list of the nodes those edges connect.
    Returns a list of nodes, or an empty list if given an empty list."""
    node_set = set()
    for edge_id in edge_list:
        edge = graph.get_edge(edge_id)
        a, b = edge['vertices']
        node_set.add(a)
        node_set.add(b)
    return list(node_set)

def merge_graphs(main_graph, addition_graph):
    """Merges an ''addition_graph'' into the ''main_graph''.
    Returns a tuple of dictionaries, mapping old node ids and edge ids to new ids."""
    node_mapping = {}
    edge_mapping = {}
    for node in addition_graph.get_all_node_objects():
        node_id = node['id']
        new_id = main_graph.new_node()
        node_mapping[node_id] = new_id
    for edge in addition_graph.get_all_edge_objects():
        edge_id = edge['id']
        old_vertex_a_id, old_vertex_b_id = edge['vertices']
        new_vertex_a_id = node_mapping[old_vertex_a_id]
        new_vertex_b_id = node_mapping[old_vertex_b_id]
        new_edge_id = main_graph.new_edge(new_vertex_a_id, new_vertex_b_id)
        edge_mapping[edge_id] = new_edge_id
    return (node_mapping, edge_mapping)

def create_graph_from_adjacency_matrix(adjacency_matrix):
    """Generates a graph from an adjacency matrix specification.
    Returns a tuple containing the graph and a list-mapping of node ids to matrix column indices.

    The graph will be an UndirectedGraph if the provided adjacency matrix is symmetric.
    The graph will be a DirectedGraph if the provided adjacency matrix is not symmetric.
    Ref: http://mathworld.wolfram.com/AdjacencyMatrix.html"""
    if is_adjacency_matrix_symmetric(adjacency_matrix):
        graph = UndirectedGraph()
    else:
        graph = DirectedGraph()
    node_column_mapping = []
    num_columns = len(adjacency_matrix)
    for _ in range(num_columns):
        node_id = graph.new_node()
        node_column_mapping.append(node_id)
    for j in range(num_columns):
        for i in range(num_columns):
            if adjacency_matrix[j][i]:
                jnode_id = node_column_mapping[j]
                inode_id = node_column_mapping[i]
                graph.new_edge(inode_id, jnode_id)
    return (graph, node_column_mapping)

def is_adjacency_matrix_symmetric(adjacency_matrix):
    """Determines if an adjacency matrix is symmetric.
    Ref: http://mathworld.wolfram.com/SymmetricMatrix.html"""
    num_columns = len(adjacency_matrix)
    for column in adjacency_matrix:
        if len(column) != num_columns:
            return False
    max_i = 0
    for j in range(num_columns):
        for i in range(max_i):
            if i == j:
                continue
            if adjacency_matrix[j][i] != adjacency_matrix[i][j]:
                return False
        max_i += 1
    return True

def a_star_search(graph, start, goal):
    """Runs an A* search on the specified graph to find a path from the ''start'' node to the ''goal'' node.
    Returns a list of nodes specifying a minimal path between the two nodes.
    If no path exists (disconnected components), returns an empty list."""
    all_nodes = graph.get_all_node_ids()
    if start not in all_nodes:
        raise NonexistentNodeError(start)
    if goal not in all_nodes:
        raise NonexistentNodeError(goal)
    came_from, cost_so_far, goal_reached = _a_star_search_internal(graph, start, goal)
    if goal_reached:
        path = reconstruct_path(came_from, start, goal)
        path.reverse()
        return path
    else:
        return []

def _a_star_search_internal(graph, start, goal):
    """Performs an A* search, returning information about whether the goal node was reached
    and path cost information that can be used to reconstruct the path."""
    frontier = PriorityQueue()
    frontier.put(start, 0)
    came_from = {start: None}
    cost_so_far = {start: 0}
    goal_reached = False
    while not frontier.empty():
        current = frontier.get()
        if current == goal:
            goal_reached = True
            break
        for next_node in graph.neighbors(current):
            new_cost = cost_so_far[current] + graph.edge_cost(current, next_node)
            if next_node not in cost_so_far or new_cost < cost_so_far[next_node]:
                cost_so_far[next_node] = new_cost
                priority = new_cost + heuristic(goal, next_node)
                frontier.put(next_node, priority)
                came_from[next_node] = current
    return (came_from, cost_so_far, goal_reached)

def is_planar(graph):
    """Determines whether a graph is planar or not."""
    connected_components = get_connected_components_as_subgraphs(graph)
    for component in connected_components:
        biconnected_components = find_biconnected_components_as_subgraphs(component)
        for bi_component in biconnected_components:
            planarity = __is_subgraph_planar(bi_component)
            if not planarity:
                return False
    return True

def __is_subgraph_planar(graph):
    """Internal function to determine if a subgraph is planar."""
    num_nodes = graph.num_nodes()
    num_edges = graph.num_edges()
    if num_nodes < 5:
        return True
    if num_edges > 3 * (num_nodes - 2):
        return False
    return kocay_planarity_test(graph)

def __calculate_edge_weights(dfs_data):
    """Calculates the weight of each edge, for embedding-order sorting."""
    graph = dfs_data['graph']
    weights = {}
    for edge_id in graph.get_all_edge_ids():
        edge_weight = __edge_weight(edge_id, dfs_data)
        weights[edge_id] = edge_weight
    return weights

def __sort_adjacency_lists(dfs_data):
    """Sorts the adjacency list representation by the edge weights."""
    new_adjacency_lists = {}
    adjacency_lists = dfs_data['adj']
    edge_weights = dfs_data['edge_weights']
    edge_lookup = dfs_data['edge_lookup']
    for node_id, adj_list in list(adjacency_lists.items()):
        node_weight_lookup = {}
        frond_lookup = {}
        for node_b in adj_list:
            edge_id = dfs_data['graph'].get_first_edge_id_by_node_ids(node_id, node_b)
            node_weight_lookup[node_b] = edge_weights[edge_id]
            frond_lookup[node_b] = 1 if edge_lookup[edge_id] == 'backedge' else 2
        new_list = sorted(adj_list, key=lambda n: frond_lookup[n])
        new_list.sort(key=lambda n: node_weight_lookup[n])
        new_adjacency_lists[node_id] = new_list
    return new_adjacency_lists

def __branch_point_dfs(dfs_data):
    """DFS that calculates the b(u) and N(u) lookups, and also reorders the adjacency lists."""
    u = dfs_data['ordering'][0]
    large_n = {}
    large_n[u] = 0
    stem = {}
    stem[u] = u
    b = {}
    b[u] = 1
    __branch_point_dfs_recursive(u, large_n, b, stem, dfs_data)
    dfs_data['N_u_lookup'] = large_n
    dfs_data['b_u_lookup'] = b
    return

def __embed_branch_recursive(u, dfs_data):
    """A recursive implementation of the EmbedBranch function, as defined on pages 8 and 22 of the paper."""
    for v in dfs_data['adj'][u]:
        nonplanar = True
        if a(v, dfs_data) == u:
            if b(v, dfs_data) == u:
                successful = __insert_branch(u, v, dfs_data)
                if not successful:
                    nonplanar = True
                    return nonplanar
            nonplanar = __embed_branch_recursive(v, dfs_data)
            if nonplanar:
                return nonplanar
        elif is_frond(u, v, dfs_data):
            successful = __embed_frond(u, v, dfs_data)
            if not successful:
                nonplanar = True
                return nonplanar
        else:
            pass
    nonplanar = False
    return nonplanar

def merge_Fm(dfs_data):
    """Merges Fm-1 and Fm, as defined on page 19 of the paper."""
    FG = dfs_data['FG']
    m = FG['m']
    FGm = FG[m]
    FGm1 = FG[m - 1]
    if FGm[0]['u'] < FGm1[0]['u']:
        FGm1[0]['u'] = FGm[0]['u']
    if FGm[0]['v'] > FGm1[0]['v']:
        FGm1[0]['v'] = FGm[0]['v']
    if FGm[1]['x'] < FGm1[1]['x']:
        FGm1[1]['x'] = FGm[1]['x']
    if FGm[1]['y'] > FGm1[1]['y']:
        FGm1[1]['y'] = FGm[1]['y']
    del FG[m]
    FG['m'] -= 1

def __check_left_side_conflict(x, y, dfs_data):
    """Checks to see if the frond xy will conflict with a frond on the left side of the embedding."""
    l = dfs_data['FG']['l']
    w, z = dfs_data['LF'][l]
    return __check_conflict_fronds(x, y, w, z, dfs_data)

def __check_right_side_conflict(x, y, dfs_data):
    """Checks to see if the frond xy will conflict with a frond on the right side of the embedding."""
    r = dfs_data['FG']['r']
    w, z = dfs_data['RF'][r]
    return __check_conflict_fronds(x, y, w, z, dfs_data)

def __check_conflict_fronds(x, y, w, z, dfs_data):
    """Checks a pair of fronds to see if they conflict. Returns True if a conflict was found, False otherwise."""
    if x < 0 and w < 0 and (x == y or w == z):
        if x == w:
            return True
        return False
    if b(x, dfs_data) == b(w, dfs_data) and x > w and (w > y) and (y > z):
        return False
    if x < 0 or w < 0:
        if x < 0:
            u = abs(x)
            t = y
            x = w
            y = z
        else:
            u = abs(w)
            t = z
        if b(x, dfs_data) == u and y < u and ((x, y) in __dfsify_branch_uv(u, t, dfs_data)):
            return True
        return False
    return False

def __calculate_adjacency_lists(graph):
    """Builds an adjacency list representation for the graph, since we can't guarantee that the
    internal representation of the graph is stored that way."""
    adj = {}
    for node in graph.get_all_node_ids():
        neighbors = graph.neighbors(node)
        adj[node] = neighbors
    return adj

def __get_all_lowpoints(dfs_data):
    """Calculates the lowpoints for each node in a graph."""
    lowpoint_1_lookup = {}
    lowpoint_2_lookup = {}
    ordering = dfs_data['ordering']
    for node in ordering:
        low_1, low_2 = __get_lowpoints(node, dfs_data)
        lowpoint_1_lookup[node] = low_1
        lowpoint_2_lookup[node] = low_2
    return (lowpoint_1_lookup, lowpoint_2_lookup)

def __calculate_bu_dfs_recursively(u, b, dfs_data):
    """Calculates the b(u) lookup table with a recursive DFS."""
    first_time = True
    for v in dfs_data['adj'][u]:
        if a(v, dfs_data) == u:
            if first_time:
                b[v] = b[u]
            else:
                b[v] = D(u, dfs_data)
            __calculate_bu_dfs_recursively(v, b, dfs_data)
        first_time = False

def is_type_I_branch(u, v, dfs_data):
    """Determines whether a branch uv is a type I branch."""
    if u != a(v, dfs_data):
        return False
    if u == L2(v, dfs_data):
        return True
    return False

def is_type_II_branch(u, v, dfs_data):
    """Determines whether a branch uv is a type II branch."""
    if u != a(v, dfs_data):
        return False
    if u < L2(v, dfs_data):
        return True
    return False

def S_star(u, dfs_data):
    """The set of all descendants of u, with u added."""
    s_u = S(u, dfs_data)
    if u not in s_u:
        s_u.append(u)
    return s_u

def T(u, dfs_data):
    """T(u) consists of all vertices adjacent to u or any descendant of u."""
    return list(set([w for v in S_star(u, dfs_data) for w in A(v, dfs_data)]))

def B(u, v, dfs_data):
    """The branch at u containing v is the set of all edges incident on v or any descendant of v, if a(v) == u."""
    'Bu(v) = {wx | w is in S*(v)}'
    if a(v, dfs_data) != u:
        return None
    return list(set([edge_id for w in S_star(v, dfs_data) for edge_id in dfs_data['graph'].get_node(w)['edges']]))

def stem(u, v, dfs_data):
    """The stem of Bu(v) is the edge uv in Bu(v)."""
    uv_edges = dfs_data['graph'].get_edge_ids_by_node_ids(u, v)
    buv_edges = B(u, v, dfs_data)
    for edge_id in uv_edges:
        if edge_id in buv_edges:
            return edge_id
    return None

def _L(dfs_data):
    """L(T) contains leaves and branch points for the DFS-tree T."""
    'L(T) = {v | the first w in Adj[v] corresponds to a frond vw}.'
    node_set = set()
    for v, adj in list(dfs_data['adj'].items()):
        w = adj[0]
        if is_frond(v, w, dfs_data):
            node_set.add(v)
    return list(node_set)

def fn_x(i, dfs_data):
    """The minimum vertex (DFS-number) in a frond contained in Ri."""
    try:
        return R(i, dfs_data)['x']
    except Exception as e:
