def prepare_table(table):
    """Make the table 'symmetric' where the lower left part of the matrix is
    the reverse probability"""
    n = len(table)
    for i, row in enumerate(table):
        assert len(row) == n
        for j, el in enumerate(row):
            if i == j:
                table[i][i] = 0.0
            elif i > j:
                table[i][j] = 1 - table[j][i]
    return table

def clusters(l, K):
    """Partition list ``l`` in ``K`` partitions.
    >>> l = [0, 1, 2]
    >>> list(clusters(l, K=3))
    [[[0], [1], [2]], [[], [0, 1], [2]], [[], [1], [0, 2]], [[0], [], [1, 2]], [[], [0], [1, 2]], [[], [], [0, 1, 2]]]
    >>> list(clusters(l, K=2))
    [[[0, 1], [2]], [[1], [0, 2]], [[0], [1, 2]], [[], [0, 1, 2]]]
    >>> list(clusters(l, K=1))
    [[[0, 1, 2]]]"""
    if l:
        prev = None
        for t in clusters(l[1:], K):
            tup = sorted(t)
            if tup != prev:
                prev = tup
                for i in range(K):
                    yield (tup[:i] + [[l[0]] + tup[i]] + tup[i + 1:])
    else:
        yield [[] for _ in range(K)]

def neclusters(l, K):
    """Partition list ``l`` in ``K`` partitions, without empty parts.

    >>> l = [0, 1, 2]
    >>> list(neclusters(l, 2))
    [[[0, 1], [2]], [[1], [0, 2]], [[0], [1, 2]]]
    >>> list(neclusters(l, 1))
    [[[0, 1, 2]]]"""
    for c in clusters(l, K):
        if all((x for x in c)):
            yield c

def all_segmentations(l):
    """Get all segmentations of a list ``l``.

    This gets bigger fast. See https://oeis.org/A000110
    For len(l) = 14 it is 190,899,322

    >>> list(all_segmentations([0, 1, 2]))
    [[[0, 1, 2]], [[0, 1], [2]], [[1], [0, 2]], [[0], [1, 2]], [[0], [1], [2]]]"""
    for K in range(1, len(l) + 1):
        gen = neclusters(l, K)
        for el in gen:
            yield el

def score_segmentation(segmentation, table):
    """Get the score of a segmentation."""
    stroke_nr = sum((1 for symbol in segmentation for stroke in symbol))
    score = 1
    for i in range(stroke_nr):
        for j in range(i + 1, stroke_nr):
            qval = q(segmentation, i, j)
            if qval:
                score *= table[i][j]
            else:
                score *= table[j][i]
    return score

def _array2cstr(arr):
    """Serializes a numpy array to a compressed base64 string"""
    out = StringIO()
    np.save(out, arr)
    return b64encode(out.getvalue())

def _str2array(d):
    """Reconstructs a numpy array from a plain-text string"""
    if type(d) == list:
        return np.asarray([_str2array(s) for s in d])
    ins = StringIO(d)
    return np.loadtxt(ins)

def elementtree_to_dict(element):
    """Convert an xml ElementTree to a dictionary."""
    d = dict()
    if hasattr(element, 'text') and element.text is not None:
        d['text'] = element.text
    d.update(element.items())
    for c in list(element):
        if c.tag not in d:
            d[c.tag] = elementtree_to_dict(c)
        elif not isinstance(d[c.tag], list):
            d[c.tag] = [d[c.tag], elementtree_to_dict(c)]
        else:
            d[c.tag].append(elementtree_to_dict(c))
    return d

def strip_end(text, suffix):
    """Strip `suffix` from the end of `text` if `text` has that suffix."""
    if not text.endswith(suffix):
        return text
    return text[:len(text) - len(suffix)]

