def apply_zappa_settings(zappa_obj, zappa_settings, environment):
    """Load Zappa settings, set defaults if needed, and apply to the Zappa object"""
    settings_all = json.load(zappa_settings)
    settings = settings_all[environment]
    for key, value in DEFAULT_SETTINGS.items():
        settings[key] = settings.get(key, value)
    if '~' in settings['settings_file']:
        settings['settings_file'] = settings['settings_file'].replace('~', os.path.expanduser('~'))
    if not os.path.isfile(settings['settings_file']):
        raise SettingsError('Please make sure your settings_file is properly defined in {0}.'.format(zappa_settings))
    for setting in CUSTOM_SETTINGS:
        if setting in settings:
            setattr(zappa_obj, setting, settings[setting])
    return settings

def tail(environment, zappa_settings):
    """Stolen verbatim from django-zappa:
    https://github.com/Miserlou/django-zappa/blob/master/django_zappa/management/commands/tail.py"""
    def print_logs(logs):
        for log in logs:
            timestamp = log['timestamp']
            message = log['message']
            if 'START RequestId' in message:
                continue
            if 'REPORT RequestId' in message:
                continue
            if 'END RequestId' in message:
                continue
            print('[' + str(timestamp) + '] ' + message.strip())
    zappa, settings, _, lambda_name = _init(environment, zappa_settings)
    try:
        all_logs = zappa.fetch_logs(lambda_name)
        print_logs(all_logs)
        while True:
            all_logs_again = zappa.fetch_logs(lambda_name)
            new_logs = []
            for log in all_logs_again:
                if log not in all_logs:
                    new_logs.append(log)
            print_logs(new_logs)
            all_logs = all_logs + new_logs
    except KeyboardInterrupt:
        try:
            sys.exit(0)
        except SystemExit:
            os._exit(0)

def discover(source):
    """Given a JavaScript file, find the sourceMappingURL line"""
    source = source.splitlines()
    if len(source) > 10:
        possibilities = source[:5] + source[-5:]
    else:
        possibilities = source
    for line in set(possibilities):
        pragma = line[:21]
        if pragma == '//# sourceMappingURL=' or pragma == '//@ sourceMappingURL=':
            return line[21:].rstrip()
    return None

def _validate_example(rh, method, example_type):
    """Validates example against schema

    :returns: Formatted example if example exists and validates, otherwise None
    :raises ValidationError: If example does not validate against the schema"""
    example = getattr(method, example_type + '_example')
    schema = getattr(method, example_type + '_schema')
    if example is None:
        return None
    try:
        validate(example, schema)
    except ValidationError as e:
        raise ValidationError('{}_example for {}.{} could not be validated.\n{}'.format(example_type, rh.__name__, method.__name__, str(e)))
    return json.dumps(example, indent=4, sort_keys=True)

def _get_rh_methods(rh):
    """Yield all HTTP methods in ``rh`` that are decorated
    with schema.validate"""
    for k, v in vars(rh).items():
        if all([k in HTTP_METHODS, is_method(v), hasattr(v, 'input_schema')]):
            yield (k, v)

def _get_tuple_from_route(route):
    """Return (pattern, handler_class, methods) tuple from ``route``

    :type route: tuple|tornado.web.URLSpec
    :rtype: tuple
    :raises TypeError: If ``route`` is not a tuple or URLSpec"""
    if isinstance(route, tuple):
        assert len(route) >= 2
        pattern, handler_class = route[:2]
    elif isinstance(route, tornado.web.URLSpec):
        pattern, handler_class = (route.regex.pattern, route.handler_class)
    else:
        raise TypeError("Unknown route type '{}'".format(type(route).__name__))
    methods = []
    route_re = re.compile(pattern)
    route_params = set(list(route_re.groupindex.keys()) + ['self'])
    for http_method in HTTP_METHODS:
        method = getattr(handler_class, http_method, None)
        if method:
            method = extract_method(method)
            method_params = set(getattr(method, '__argspec_args', inspect.getargspec(method).args))
            if route_params.issubset(method_params) and method_params.issubset(route_params):
                methods.append(http_method)
    return (pattern, handler_class, methods)

def get_object_defaults(object_schema):
    """Extracts default values dict (nested) from an type object schema.

    :param object_schema: Schema type object
    :type  object_schema: dict
    :returns: Nested dict with defaults values"""
    default = {}
    for k, schema in object_schema.get('properties', {}).items():
        if schema.get('type') == 'object':
            if 'default' in schema:
                default[k] = schema['default']
            try:
                object_defaults = get_object_defaults(schema)
            except NoObjectDefaults:
                if 'default' not in schema:
                    raise NoObjectDefaults
            else:
                if 'default' not in schema:
                    default[k] = {}
                default[k].update(object_defaults)
        elif 'default' in schema:
            default[k] = schema['default']
    if default:
        return default
    raise NoObjectDefaults

def input_schema_clean(input_, input_schema):
    """Updates schema default values with input data.

    :param input_: Input data
    :type  input_: dict
    :param input_schema: Input schema
    :type  input_schema: dict
    :returns: Nested dict with data (defaul values updated with input data)
    :rtype: dict"""
    if input_schema.get('type') == 'object':
        try:
            defaults = get_object_defaults(input_schema)
        except NoObjectDefaults:
            pass
        else:
            return deep_update(defaults, input_)
    return input_

