def deep_update(source, overrides):
    """Update a nested dictionary or similar mapping.

    Modify ``source`` in place.

    :type source: collections.Mapping
    :type overrides: collections.Mapping
    :rtype: collections.Mapping"""
    for key, value in overrides.items():
        if isinstance(value, collections.Mapping) and value:
            returned = deep_update(source.get(key, {}), value)
            source[key] = returned
        else:
            source[key] = overrides[key]
    return source

def is_handler_subclass(cls, classnames=('ViewHandler', 'APIHandler')):
    """Determines if ``cls`` is indeed a subclass of ``classnames``"""
    if isinstance(cls, list):
        return any((is_handler_subclass(c) for c in cls))
    elif isinstance(cls, type):
        return any((c.__name__ in classnames for c in inspect.getmro(cls)))
    else:
        raise TypeError('Unexpected type `{}` for class `{}`'.format(type(cls), cls))

def coroutine(func, replace_callback=True):
    """Tornado-JSON compatible wrapper for ``tornado.gen.coroutine``

    Annotates original argspec.args of ``func`` as attribute ``__argspec_args``"""
    if TORNADO_MAJOR != 4:
        wrapper = gen.coroutine(func)
    else:
        wrapper = gen.coroutine(func, replace_callback)
    wrapper.__argspec_args = inspect.getargspec(func).args
    return wrapper

def key_dict(from_dict):
    """Returns dict from_dict['unicode_save_field'] = 'original key with unicode'"""
    new_dict = {}
    old2new = {}
    new2old = {}
    for key in from_dict:
        k = normalizeUnicode(key, 'identifier')
        if k != key:
            i = ''
            while new_dict.has_key('%s%s' % (k, i)):
                if not i:
                    i = 1
                else:
                    i += 1
            k = '%s%s' % (k, i)
            old2new[key] = k
            new2old[k] = key
        new_dict[k] = from_dict[key]
    return (new_dict.keys(), new_dict, old2new, new2old)

