def create_error(msg, cause=None):
    """Creates a ``GaxError`` or subclass.

    Attributes:
        msg (string): describes the error that occurred.
        cause (Exception, optional): the exception raised by a lower
            layer of the RPC stack (for example, gRPC) that caused this
            exception, or None if this exception originated in GAX.

    Returns:
        .GaxError: The exception that wraps ``cause``."""
    status_code = config.exc_to_code(cause)
    status_name = config.NAME_STATUS_CODES.get(status_code)
    if status_name == 'INVALID_ARGUMENT':
        return InvalidArgumentError(msg, cause=cause)
    else:
        return GaxError(msg, cause=cause)

def _page_streamable(page_descriptor):
    """Creates a function that yields an iterable to performs page-streaming.

    Args:
        page_descriptor (:class:`PageDescriptor`): indicates the structure
          of page streaming to be performed.

    Returns:
        Callable: A function that returns an iterator."""
    def inner(a_func, settings, request, **kwargs):
        """Actual page-streaming based on the settings."""
        page_iterator = gax.PageIterator(a_func, page_descriptor, settings.page_token, request, **kwargs)
        if settings.flatten_pages:
            return gax.ResourceIterator(page_iterator)
        else:
            return page_iterator
    return inner

def _catch_errors(a_func, to_catch):
    """Updates a_func to wrap exceptions with GaxError

    Args:
        a_func (callable): A callable.
        to_catch (list[Exception]): Configures the exceptions to wrap.

    Returns:
        Callable: A function that will wrap certain exceptions with GaxError"""
    def inner(*args, **kwargs):
        """Wraps specified exceptions"""
        try:
            return a_func(*args, **kwargs)
        except tuple(to_catch) as exception:
            utils.raise_with_traceback(gax.errors.create_error('RPC failed', cause=exception))
    return inner

def _merge_options_metadata(options, settings):
    """Merge metadata list (add all missing tuples)"""
    if not options:
        return options
    kwargs = options.kwargs
    if kwargs == gax.OPTION_INHERIT or 'metadata' not in kwargs:
        return options
    kwarg_meta_dict = {}
    merged_kwargs = options.kwargs.copy()
    for kwarg_meta in merged_kwargs['metadata']:
        kwarg_meta_dict[kwarg_meta[0].lower()] = kwarg_meta
    for kwarg_meta in settings.kwargs['metadata']:
        if kwarg_meta[0].lower() not in kwarg_meta_dict:
            merged_kwargs['metadata'].append(kwarg_meta)
    return gax.CallOptions(timeout=options.timeout, retry=options.retry, page_token=options.page_token, is_bundling=options.is_bundling, **merged_kwargs)

def value_for_keypath(dict, keypath):
    """Returns the value of a keypath in a dictionary
    if the keypath exists or None if the keypath
    does not exist."""
    if len(keypath) == 0:
        return dict
    keys = keypath.split('.')
    value = dict
    for key in keys:
        if key in value:
            value = value[key]
        else:
            return None
    return value

def set_value_for_keypath(item, keypath, value, create_if_needed=False, delimeter='.'):
    """Sets the value for a keypath in a dictionary
    if the keypath exists. This modifies the
    original dictionary."""
    if len(keypath) == 0:
        return None
    keys = keypath.split(delimeter)
    if len(keys) > 1:
        key = keys[0]
        if create_if_needed:
            item[key] = item.get(key, {})
        if key in item:
            if set_value_for_keypath(item[key], delimeter.join(keys[1:]), value, create_if_needed=create_if_needed, delimeter=delimeter):
                return item
        return None
    if create_if_needed:
        item[keypath] = item.get(keypath, {})
    if keypath in item:
        item[keypath] = value
        return item
    else:
        return None

def _deprecated_kwargs(kwargs, arg_newarg):
    """arg_newarg is a list of tuples, where each tuple has a pair of strings.
    ('old_arg', 'new_arg')
    A DeprecationWarning is raised for the arguments that need to be
    replaced."""
    warn_for = []
    for arg, new_kw in arg_newarg:
        if arg in kwargs.keys():
            val = kwargs.pop(arg)
            kwargs[new_kw] = val
            warn_for.append((arg, new_kw))
    if len(warn_for) > 0:
        if len(warn_for) == 1:
            warnings.warn("Argument '{}' is deprecated. Use {} instead".format(warn_for[0][0], warn_for[0][1]), DeprecationWarning, stacklevel=4)
        else:
            args = ', '.join([x[0] for x in warn_for])
            repl = ', '.join([x[1] for x in warn_for])
            warnings.warn("Arguments '{}' are deprecated. Use '{}' instead respectively".format(args, repl), DeprecationWarning, stacklevel=4)
    return kwargs

def _map_or_starmap_async(function, iterable, args, kwargs, map_or_starmap):
    """Shared function between parmap.map_async and parmap.starmap_async.
    Refer to those functions for details."""
    arg_newarg = (('parallel', 'pm_parallel'), ('chunksize', 'pm_chunksize'), ('pool', 'pm_pool'), ('processes', 'pm_processes'), ('callback', 'pm_callback'), ('error_callback', 'pm_error_callback'))
    kwargs = _deprecated_kwargs(kwargs, arg_newarg)
    chunksize = kwargs.pop('pm_chunksize', None)
    callback = kwargs.pop('pm_callback', None)
    error_callback = kwargs.pop('pm_error_callback', None)
    parallel, pool, close_pool = _create_pool(kwargs)
    if parallel:
        func_star = _get_helper_func(map_or_starmap)
        try:
            if sys.version_info[0] == 2:
                result = pool.map_async(func_star, izip(repeat(function), iterable, repeat(list(args)), repeat(kwargs)), chunksize, callback)
            else:
                result = pool.map_async(func_star, izip(repeat(function), iterable, repeat(list(args)), repeat(kwargs)), chunksize, callback, error_callback)
        finally:
            if close_pool:
                pool.close()
                result = _ParallelAsyncResult(result, pool)
            else:
                result = _ParallelAsyncResult(result)
    else:
        values = _serial_map_or_starmap(function, iterable, args, kwargs, False, map_or_starmap)
        result = _DummyAsyncResult(values)
    return result

