def ok(prompt='OK ', loc={}, glo={}, cmd=''):
    """Invoke the peforth interpreter.
    An statement: peforth.ok(prompt='OK ', loc=locals(), glo=globals(), cmd="")
    is like a breakpoint. The prompt indicates which breakpoint it is if there are
    many. Arguments loc (locals) and glo (globals) along with the prompt are the
    debuggee's informations that is packed as a tuple (loc,glo,prompt) left on TOS
    of the FORTH vm when the breakpoint is called. Replace the loc=locals() with
    loc=dict(locals()) to get a snapshot copy instead of a reference, as well as
    the glo. 'exit' command to stop debugging."""
    if loc or glo:
        vm.push((loc, glo, prompt))
    while True:
        if cmd == '':
            if vm.tick('accept') and (not vm.multiple):
                vm.execute('accept')
                cmd = vm.pop().strip()
            elif vm.tick('<accept>') and vm.multiple:
                vm.execute('<accept>')
                cmd = vm.pop().strip()
            else:
                cmd = input('').strip()
        if cmd == '':
            print(prompt, end='')
            continue
        elif cmd == chr(4):
            vm.multiple = not vm.multiple
            if not vm.multiple:
                print(prompt, end='')
        else:
            vm.dictate(cmd)
            if vm.multiple:
                vm.multiple = False
            print(prompt, end='')
        cmd = ''
        if vm.exit:
            vm.exit = False
            break
    return vm

def _main():
    """A simple demo to be used from command line."""
    import sys
    def log(message):
        print(message)
    def print_usage():
        log('usage: %s <application key> <application secret> send <number> <message> <from_number>' % sys.argv[0])
        log('       %s <application key> <application secret> status <message_id>' % sys.argv[0])
    if len(sys.argv) > 4 and sys.argv[3] == 'send':
        key, secret, number, message = (sys.argv[1], sys.argv[2], sys.argv[4], sys.argv[5])
        client = SinchSMS(key, secret)
        if len(sys.argv) > 6:
            log(client.send_message(number, message, sys.argv[6]))
        else:
            log(client.send_message(number, message))
    elif len(sys.argv) > 3 and sys.argv[3] == 'status':
        key, secret, message_id = (sys.argv[1], sys.argv[2], sys.argv[4])
        client = SinchSMS(key, secret)
        log(client.check_status(message_id))
    else:
        print_usage()
        sys.exit(1)
    sys.exit(0)

