def _get_response(**kwargs):
    """Get a template response

    Use kwargs to add things to the dictionary"""
    if 'code' not in kwargs:
        kwargs['code'] = 200
    if 'headers' not in kwargs:
        kwargs['headers'] = dict()
    if 'version' not in kwargs:
        kwargs['version'] = 'HTTP/1.1'
    return dict(**kwargs)

def find_source_files(input_path, excludes):
    """Get a list of filenames for all Java source files within the given
    directory."""
    java_files = []
    input_path = os.path.normpath(os.path.abspath(input_path))
    for dirpath, dirnames, filenames in os.walk(input_path):
        if is_excluded(dirpath, excludes):
            del dirnames[:]
            continue
        for filename in filenames:
            if filename.endswith('.java'):
                java_files.append(os.path.join(dirpath, filename))
    return java_files

def javadoc_role(name, rawtext, text, lineno, inliner, options={}, content=[]):
    """Role for linking to external Javadoc"""
    has_explicit_title, title, target = split_explicit_title(text)
    title = utils.unescape(title)
    target = utils.unescape(target)
    if not has_explicit_title:
        target = target.lstrip('~')
        if title[0] == '~':
            title = title[1:].rpartition('.')[2]
    app = inliner.document.settings.env.app
    ref = get_javadoc_ref(app, rawtext, target)
    if not ref:
        raise ValueError('no Javadoc source found for %s in javadoc_url_map' % (target,))
    ref.append(nodes.Text(title, title))
    return ([ref], [])

def match_hostname(cert, hostname):
    """This is a backport of the match_hostname() function from Python 3.2,
    essential when using SSL.
    Verifies that *cert* (in decoded format as returned by
    SSLSocket.getpeercert()) matches the *hostname*.  RFC 2818 rules
    are mostly followed, but IP addresses are not accepted for *hostname*.

    CertificateError is raised on failure. On success, the function
    returns nothing."""
    if not cert:
        raise ValueError('empty or no certificate')
    dnsnames = []
    san = cert.get('subjectAltName', ())
    for key, value in san:
        if key == 'DNS':
            if _dnsname_to_pat(value).match(hostname):
                return
            dnsnames.append(value)
    if not san:
        for sub in cert.get('subject', ()):
            for key, value in sub:
                if key == 'commonName':
                    if _dnsname_to_pat(value).match(hostname):
                        return
                    dnsnames.append(value)
    if len(dnsnames) > 1:
        raise CertificateError("hostname %r doesn't match either of %s" % (hostname, ', '.join(map(repr, dnsnames))))
    elif len(dnsnames) == 1:
        raise CertificateError("hostname %r doesn't match %r" % (hostname, dnsnames[0]))
    else:
        raise CertificateError('no appropriate commonName or subjectAltName fields were found')

def render_form(form, exclude=None, **kwargs):
    """Render an entire form with Semantic UI wrappers for each field

    Args:
            form (form): Django Form
            exclude (string): exclude fields by name, separated by commas
            kwargs (dict): other attributes will be passed to fields

    Returns:
            string: HTML of Django Form fields with Semantic UI wrappers"""
    if hasattr(form, 'Meta') and hasattr(form.Meta, 'layout'):
        return render_layout_form(form, getattr(form.Meta, 'layout'), **kwargs)
    if exclude:
        exclude = exclude.split(',')
        for field in exclude:
            form.fields.pop(field)
    return mark_safe(''.join([render_field(field, **kwargs) for field in form]))

def render_layout_form(form, layout=None, **kwargs):
    """Render an entire form with Semantic UI wrappers for each field with
    a layout provided in the template or in the form class

    Args:
            form (form): Django Form
            layout (tuple): layout design
            kwargs (dict): other attributes will be passed to fields

    Returns:
            string: HTML of Django Form fields with Semantic UI wrappers"""
    def make_component(type_, *args):
        """Loop through tuples to make field wrappers for fields.
        """
        if type_ == 'Text':
            return ''.join(args)
        elif type_ == 'Field':
            result = ''
            for c in args:
                if isinstance(c, tuple):
                    result += make_component(*c)
                elif isinstance(c, str):
                    result += render_field(form.__getitem__(c), **kwargs)
            return result
        else:
            if len(args) < 2:
                return ''
            result = ''.join([make_component(*c) for c in args])
            if type_:
                return '<div class="%s">%s</div>' % (type_.lower(), result)
            else:
                return result
    return mark_safe(''.join([make_component(*component) for component in layout]))

def render_booleanfield(field, attrs):
    """Render BooleanField with label next to instead of above."""
    attrs.setdefault('_no_label', True)
    attrs.setdefault('_inline', True)
    field.field.widget.attrs['style'] = 'display:hidden'
    return wrappers.CHECKBOX_WRAPPER % {'style': pad(attrs.get('_style', '')), 'field': field, 'label': format_html(wrappers.LABEL_TEMPLATE, field.html_name, mark_safe(field.label))}

def render_choicefield(field, attrs, choices=None):
    """Render ChoiceField as 'div' dropdown rather than select for more
    customization."""
    if not choices:
        choices = format_html_join('', wrappers.CHOICE_TEMPLATE, get_choices(field))
    field.field.widget.attrs['value'] = field.value() or attrs.get('value', '')
    return wrappers.DROPDOWN_WRAPPER % {'name': field.html_name, 'attrs': pad(flatatt(field.field.widget.attrs)), 'placeholder': attrs.get('placeholder') or get_placeholder_text(), 'style': pad(attrs.get('_style', '')), 'icon': format_html(wrappers.ICON_TEMPLATE, attrs.get('_dropdown_icon') or 'dropdown'), 'choices': choices}

def render_iconchoicefield(field, attrs):
    """Render a ChoiceField with icon support; where the value is split by a pipe
    (|): first element being the value, last element is the icon."""
    choices = ''
    for choice in field.field._choices:
        value = choice[1].split('|')
        choices += format_html(wrappers.ICON_CHOICE_TEMPLATE, choice[0], mark_safe(wrappers.ICON_TEMPLATE.format(value[-1])), value[0])
    return render_choicefield(field, attrs, choices)

def render_countryfield(field, attrs):
    """Render a custom ChoiceField specific for CountryFields."""
    choices = ((k, k.lower(), v) for k, v in field.field._choices[1:])
    return render_choicefield(field, attrs, format_html_join('', wrappers.COUNTRY_TEMPLATE, choices))

def render_multiplechoicefield(field, attrs, choices=None):
