def bootstrap_ts(y, func, B=1000, b=3):
    """Bootstrap a timeseries using a window size:b."""
    beta_star = np.empty(B)
    z = y
    z_star = np.empty(len(z))
    for boot_i in range(B):
        for block_i, start in enumerate(np.random.randint(len(z) - b + 1, size=len(z) / b)):
            z_star[block_i * b:(block_i + 1) * b] = z[start:start + b]
            beta_star[boot_i] = func(z_star)
    return beta_star

def extract_relevant_tb(tb, exctype, is_test_failure):
    """Return extracted traceback frame 4-tuples that aren't unittest ones.

    This used to be _exc_info_to_string()."""
    while tb and _is_unittest_frame(tb):
        tb = tb.tb_next
    if is_test_failure:
        length = _count_relevant_tb_levels(tb)
        return extract_tb(tb, length)
    return extract_tb(tb)

def _unicode_decode_extracted_tb(extracted_tb):
    """Return a traceback with the string elements translated into Unicode."""
    return [(_decode(file), line_number, _decode(function), _decode(text)) for file, line_number, function, text in extracted_tb]

def nose_selector(test):
    """Return the string you can pass to nose to run `test`, including argument
    values if the test was made by a test generator.

    Return "Unknown test" if it can't construct a decent path."""
    address = test_address(test)
    if address:
        file, module, rest = address
        if module:
            if rest:
                try:
                    return '%s:%s%s' % (module, rest, test.test.arg or '')
                except AttributeError:
                    return '%s:%s' % (module, rest)
            else:
                return module
    return 'Unknown test'

def AppConfigFlagHandler(feature=None):
    """This is the default handler. It checks for feature flags in the current app's configuration.

    For example, to have 'unfinished_feature' hidden in production but active in development:

    config.py

    class ProductionConfig(Config):

      FEATURE_FLAGS = {
        'unfinished_feature' : False,
      }


    class DevelopmentConfig(Config):

      FEATURE_FLAGS = {
        'unfinished_feature' : True,
      }

    """
    if not current_app:
        log.warn(u"Got a request to check for {feature} but we're outside the request context. Returning False".format(feature=feature))
        return False
    try:
        return current_app.config[FEATURE_FLAGS_CONFIG][feature]
    except (AttributeError, KeyError):
        raise NoFeatureFlagFound()

def is_active(feature):
    """Check if a feature is active"""
    if current_app:
        feature_flagger = current_app.extensions.get(EXTENSION_NAME)
        if feature_flagger:
            return feature_flagger.check(feature)
        else:
            raise AssertionError("Oops. This application doesn't have the Flask-FeatureFlag extention installed.")
    else:
        log.warn(u"Got a request to check for {feature} but we're running outside the request context. Check your setup. Returning False".format(feature=feature))
        return False

def is_active_feature(feature, redirect_to=None, redirect=None):
    """Decorator for Flask views. If a feature is off, it can either return a 404 or redirect to a URL if you'd rather."""
    def _is_active_feature(func):
        @wraps(func)
        def wrapped(*args, **kwargs):
            if not is_active(feature):
                url = redirect_to
                if redirect:
                    url = url_for(redirect)
                if url:
                    log.debug(u'Feature {feature} is off, redirecting to {url}'.format(feature=feature, url=url))
                    return _redirect(url, code=302)
                else:
                    log.debug(u'Feature {feature} is off, aborting request'.format(feature=feature))
                    abort(404)
            return func(*args, **kwargs)
        return wrapped
    return _is_active_feature

def get_attr(attr_list, global_attrs):
    """Parameters
    ----------
    attr_list : list
        A list of (keyword, value) tuple pairs
    global_attrs : tuple(list, dict)
        Global attributes which update the local attributes"""
    local_attr = ([], {})
    for kv in attr_list:
        keyword = kv[0]
        if len(kv) == 1:
            local_attr[0].append(keyword)
            continue
        elif len(kv) == 2:
            value = kv[1]
        elif len(kv) > 2:
            value = kv[1:]
        if keyword == 'tag':
            local_attr[1].setdefault(keyword, set()).add(value)
        else:
            local_attr[1][keyword] = value
    attr0 = copy.copy(global_attrs[0])
    attr1 = copy.copy(global_attrs[1])
    if local_attr[0]:
        attr0.extend(local_attr[0])
    if local_attr[1]:
        attr1.update(local_attr[1])
    return (attr0, attr1)

def process_affinity(affinity=None):
    """Get or set the CPU affinity set for the current process.

    This will affect all future threads spawned by this process.  It is
    implementation-defined whether it will also affect previously-spawned
    threads."""
    if affinity is not None:
        affinity = CPUSet(affinity)
        if not affinity.issubset(system_affinity()):
            raise ValueError('unknown cpus: %s' % affinity)
    return system_affinity()

def _priority_range(policy=None):
    """Determine the priority range (min,max) for the given scheduler policy.

    If no policy is specified, the current default policy is used."""
    if policy is None:
        policy = libc.sched_getscheduler(0)
        if policy < 0:
            raise OSError(get_errno(), 'sched_getscheduler')
    max = libc.sched_get_priority_max(policy)
    if max < 0:
        raise OSError(get_errno(), 'sched_get_priority_max')
    min = libc.sched_get_priority_min(policy)
    if min < 0:
        raise OSError(get_errno(), 'sched_get_priority_min')
    return (min, max)

def build_rrule_from_recurrences_rrule(rule):
    """Build rrule dictionary for vRecur class from a django_recurrences rrule.

    django_recurrences is a popular implementation for recurrences in django.
    https://pypi.org/project/django-recurrence/
    this is a shortcut to interface between recurrences and icalendar."""
    from recurrence import serialize
    line = serialize(rule)
    if line.startswith('RRULE:'):
        line = line[6:]
    return build_rrule_from_text(line)

def build_rrule_from_dateutil_rrule(rule):
    """Build rrule dictionary for vRecur class from a dateutil rrule.

    Dateutils rrule is a popular implementation of rrule in python.
    https://pypi.org/project/python-dateutil/
    this is a shortcut to interface between dateutil and icalendar."""
    lines = str(rule).splitlines()
    for line in lines:
        if line.startswith('DTSTART:'):
            continue
        if line.startswith('RRULE:'):
            line = line[6:]
        return build_rrule_from_text(line)

def _run_lambda_function(event, context, app, config):
    """Run the function. This is the default when no plugins (such as wsgi)
    define an alternative run function."""
    args = event.get('args', [])
    kwargs = event.get('kwargs', {})
    try:
        ret = app(*args, event=event, context=context, **kwargs)
    except TypeError:
        ret = app(*args, **kwargs)
    return ret

