def _prepare_key(key, *args, **kwargs):
    """if arguments are given, adds a hash of the args to the key."""
    if not args and (not kwargs):
        return key
    items = sorted(kwargs.items())
    hashable_args = (args, tuple(items))
    args_key = hashlib.md5(pickle.dumps(hashable_args)).hexdigest()
    return '%s/args:%s' % (key, args_key)

def get_version_with_beta(version_info: FileVersionResult) -> str:
    """Get the project's version string *with* a beta build label based on UTC.

    :param version_info: The current version_info of the project.
    :return: The project's version string, with a beta build number."""
    if not version_info:
        raise TypeError("version_info cannot be 'None'!")
    if not version_info.uniform:
        raise ValueError('version_info is not uniform!')
    utc_datetime = datetime.datetime.utcnow()
    beta_flag = '.123.'
    build_number = utc_datetime.strftime('%Y%m%d.%H%M%S')
    cleaned_version = get_version_without_beta(version_info)
    return '{base}{flag}{build}'.format(base=cleaned_version, flag=beta_flag, build=build_number)

def remote_property(name, get_command, set_command, field_name, doc=None):
    """Property decorator that facilitates writing properties for values from a remote device.

    Arguments:
      name: The field name to use on the local object to store the cached property.
      get_command: A function that returns the remote value of the property.
      set_command: A function that accepts a new value for the property and sets it remotely.
      field_name: The name of the field to retrieve from the response message to get operations."""
    def getter(self):
        try:
            return getattr(self, name)
        except AttributeError:
            value = getattr(self.sendCommand(get_command()), field_name)
            setattr(self, name, value)
            return value
    def setter(self, value):
        setattr(self, name, value)
        self.sendCommand(set_command(value))
    return property(getter, setter, doc=doc)

def quantity_string(name, quantity_dict):
    """Takes in an abbreviation for a quantity and a quantity dictionary,
    and returns a more descriptive string of the quantity as "name (units)."
    Raises ValueError if the name is not in quantity_dict"""
    if name not in quantity_dict.keys():
        raise ValueError('{0} is not present in quantity_dict'.format(name))
    return '{0} ({1})'.format(quantity_dict[name]['name'], quantity_dict[name]['units'])

def strings_to_list_string(strings):
    """Takes a list of strings presumably containing words and phrases,
    and returns a "list" form of those strings, like:

    >>> strings_to_list_string(('cats', 'dogs'))
    >>> 'cats and dogs'

    or

    >>> strings_to_list_string(('pizza', 'pop', 'chips'))
    >>> 'pizza, pop, and chips'

    Raises ValueError if strings is empty."""
    if isinstance(strings, six.string_types):
        raise TypeError('strings must be an iterable of strings, not a string itself')
    if len(strings) == 0:
        raise ValueError('strings may not be empty')
    elif len(strings) == 1:
        return strings[0]
    elif len(strings) == 2:
        return ' and '.join(strings)
    else:
        return '{0}, and {1}'.format(', '.join(strings[:-1]), strings[-1])

def assumption_list_string(assumptions, assumption_dict):
    """Takes in a list of short forms of assumptions and an assumption
    dictionary, and returns a "list" form of the long form of the
    assumptions.

    Raises
    ------
    ValueError
        if one of the assumptions is not in assumption_dict.
    """
    if isinstance(assumptions, six.string_types):
        raise TypeError('assumptions must be an iterable of strings, not a string itself')
    for a in assumptions:
        if a not in assumption_dict.keys():
            raise ValueError('{} not present in assumption_dict'.format(a))
    assumption_strings = [assumption_dict[a] for a in assumptions]
    return strings_to_list_string(assumption_strings)

def parse_derivative_string(string, quantity_dict):
    """Assuming the string is of the form d(var1)d(var2), returns var1, var2.
    Raises ValueError if the string is not of this form, or if the vars
    are not keys in the quantity_dict, or if var2 is not a coordinate-like
    variable."""
    match = derivative_prog.match(string)
    if match is None:
        raise ValueError('string is not in the form of a derivative')
    varname = match.group(1)
    coordname = match.group(2)
    if varname not in quantity_dict.keys() or coordname not in quantity_dict.keys():
        raise ValueError('variable in string not a valid quantity')
    return (varname, coordname)

def get_calculatable_quantities(inputs, methods):
    """Given an interable of input quantity names and a methods dictionary,
    returns a list of output quantities that can be calculated."""
    output_quantities = []
    updated = True
    while updated:
        updated = False
        for output in methods.keys():
            if output in output_quantities or output in inputs:
                continue
            for args, func in methods[output].items():
                if all([arg in inputs or arg in output_quantities for arg in args]):
                    output_quantities.append(output)
                    updated = True
                    break
    return tuple(output_quantities) + tuple(inputs)

def _get_calculatable_methods_dict(inputs, methods):
    """Given an iterable of input variable names and a methods dictionary,
    returns the subset of that methods dictionary that can be calculated and
    which doesn't calculate something we already have. Additionally it may
    only contain one method for any given output variable, which is the one
    with the fewest possible arguments."""
    calculatable_methods = {}
    for var in methods.keys():
        if var in inputs:
            continue
        else:
            var_dict = {}
            for args, func in methods[var].items():
                if all([arg in inputs for arg in args]):
                    var_dict[args] = func
            if len(var_dict) == 0:
                continue
            elif len(var_dict) == 1:
                calculatable_methods[var] = var_dict
            else:
                min_args = min(var_dict.keys(), key=lambda x: len(x))
                calculatable_methods[var] = {min_args: var_dict[min_args]}
    return calculatable_methods

def _get_module_methods(module):
    """Returns a methods list corresponding to the equations in the given
    module. Each entry is a dictionary with keys 'output', 'args', and
    'func' corresponding to the output, arguments, and function of the
    method. The entries may optionally include 'assumptions' and
    'overridden_by_assumptions' as keys, stating which assumptions are
    required to use the method, and which assumptions mean the method
    should not be used because it is overridden."""
    methods = []
    funcs = []
    for item in inspect.getmembers(equations):
        if item[0][0] != '_' and '_from_' in item[0]:
            func = item[1]
            output = item[0][:item[0].find('_from_')]
        if func in funcs:
            continue
        else:
            funcs.append(func)
        args = tuple(getfullargspec(func).args)
        try:
            assumptions = tuple(func.assumptions)
        except AttributeError:
            raise NotImplementedError('function {0} in equations module has no assumption definition'.format(func.__name__))
        try:
            overridden_by_assumptions = func.overridden_by_assumptions
        except AttributeError:
            overridden_by_assumptions = ()
        methods.append({'func': func, 'args': args, 'output': output, 'assumptions': assumptions, 'overridden_by_assumptions': overridden_by_assumptions})
    return methods

def _check_scalar(value):
    """If value is a 0-dimensional array, returns the contents of value.
    Otherwise, returns value."""
    if isinstance(value, np.ndarray):
        if value.ndim == 0:
            return value[None][0]
    return value

