def generate_cumulative_dist(island_expectations_d, total_length):
    """Generate cumulative distribution: a list of tuples (bins, hist)."""
    cumulative = [0.0] * (total_length + 1)
    partial_sum = 0.0
    island_expectations = []
    for i in range(len(cumulative)):
        if i in island_expectations_d:
            island_expectations.append(island_expectations_d[i])
        else:
            island_expectations.append(0)
    for index in range(1, len(island_expectations) + 1):
        complimentary = len(island_expectations) - index
        partial_sum += island_expectations[complimentary]
        cumulative[complimentary] = partial_sum
    for index in range(len(cumulative)):
        if cumulative[index] <= E_VALUE:
            score_threshold = index * BIN_SIZE
            break
    return score_threshold

def py2round(value):
    """Round values as in Python 2, for Python 3 compatibility.

    All x.5 values are rounded away from zero.

    In Python 3, this has changed to avoid bias: when x is even,
    rounding is towards zero, when x is odd, rounding is away
    from zero. Thus, in Python 3, round(2.5) results in 2,
    round(3.5) is 4.

    Python 3 also returns an int; Python 2 returns a float."""
    if value > 0:
        return float(floor(float(value) + 0.5))
    else:
        return float(ceil(float(value) - 0.5))

def canonicalize(interval, lower_inc=True, upper_inc=False):
    """Convert equivalent discrete intervals to different representations."""
    if not interval.discrete:
        raise TypeError('Only discrete ranges can be canonicalized')
    if interval.empty:
        return interval
    lower, lower_inc = canonicalize_lower(interval, lower_inc)
    upper, upper_inc = canonicalize_upper(interval, upper_inc)
    return interval.__class__([lower, upper], lower_inc=lower_inc, upper_inc=upper_inc)

def compute_enriched_threshold(average_window_readcount):
    """Computes the minimum number of tags required in window for an island to be enriched."""
    current_threshold, survival_function = (0, 1)
    for current_threshold in count(start=0, step=1):
        survival_function -= poisson.pmf(current_threshold, average_window_readcount)
        if survival_function <= WINDOW_P_VALUE:
            break
    island_enriched_threshold = current_threshold + 1
    return island_enriched_threshold

def _factln(num):
    """Computes logfactorial regularly for tractable numbers, uses Ramanujans approximation otherwise."""
    if num < 20:
        log_factorial = log(factorial(num))
    else:
        log_factorial = num * log(num) - num + log(num * (1 + 4 * num * (1 + 2 * num))) / 6.0 + log(pi) / 2
    return log_factorial

def merge_chromosome_dfs(df_tuple):
    """Merges data from the two strands into strand-agnostic counts."""
    plus_df, minus_df = df_tuple
    index_cols = 'Chromosome Bin'.split()
    count_column = plus_df.columns[0]
    if plus_df.empty:
        return return_other(minus_df, count_column, index_cols)
    if minus_df.empty:
        return return_other(plus_df, count_column, index_cols)
    plus_df = plus_df.groupby(index_cols).sum()
    minus_df = minus_df.groupby(index_cols).sum()
    df = pd.concat([plus_df, minus_df], axis=1).fillna(0).sum(axis=1)
    df = df.reset_index().sort_values(by='Bin')
    df.columns = ['Chromosome', 'Bin', count_column]
    df = df.sort_values(['Chromosome', 'Bin'])
    df[['Bin', count_column]] = df[['Bin', count_column]].astype(int32)
    df = df[[count_column, 'Chromosome', 'Bin']]
    return df.reset_index(drop=True)

def remove_out_of_bounds_bins(df, chromosome_size):
    """Remove all reads that were shifted outside of the genome endpoints."""
    if 'Bin' not in df:
        return df
    df = df.drop(df[df.Bin > chromosome_size].index)
    return df.drop(df[df.Bin < 0].index)

def get_island_bins(df, window_size, genome, args):
    """Finds the enriched bins in a df."""
    chromosomes = natsorted(list(args.chromosome_sizes))
    chromosome_island_bins = {}
    df_copy = df.reset_index(drop=False)
    for chromosome in chromosomes:
        cdf = df_copy.loc[df_copy.Chromosome == chromosome]
        if cdf.empty:
            chromosome_island_bins[chromosome] = set()
        else:
            island_starts_ends = zip(cdf.Start.values.tolist(), cdf.End.values.tolist())
            island_bins = chain(*[range(int(start), int(end), window_size) for start, end in island_starts_ends])
            chromosome_island_bins[chromosome] = set(island_bins)
    return chromosome_island_bins

def create_genome_size_dict(genome):
    """Creates genome size dict from string containing data."""
    size_file = get_genome_size_file(genome)
    size_lines = open(size_file).readlines()
    size_dict = {}
    for line in size_lines:
        genome, length = line.split()
        size_dict[genome] = int(length)
    return size_dict

def _set_up_pool_config(self):
    """Helper to configure pool options during DatabaseWrapper initialization."""
    self._max_conns = self.settings_dict['OPTIONS'].get('MAX_CONNS', pool_config_defaults['MAX_CONNS'])
    self._min_conns = self.settings_dict['OPTIONS'].get('MIN_CONNS', self._max_conns)
    self._test_on_borrow = self.settings_dict['OPTIONS'].get('TEST_ON_BORROW', pool_config_defaults['TEST_ON_BORROW'])
    if self._test_on_borrow:
        self._test_on_borrow_query = self.settings_dict['OPTIONS'].get('TEST_ON_BORROW_QUERY', pool_config_defaults['TEST_ON_BORROW_QUERY'])
    else:
        self._test_on_borrow_query = None

def _create_connection_pool(self, conn_params):
    """Helper to initialize the connection pool."""
    connection_pools_lock.acquire()
    try:
        if self.alias not in connection_pools or connection_pools[self.alias]['settings'] != self.settings_dict:
            logger.info('Creating connection pool for db alias %s' % self.alias)
            logger.info('  using MIN_CONNS = %s, MAX_CONNS = %s, TEST_ON_BORROW = %s' % (self._min_conns, self._max_conns, self._test_on_borrow))
            from psycopg2 import pool
            connection_pools[self.alias] = {'pool': pool.ThreadedConnectionPool(self._min_conns, self._max_conns, **conn_params), 'settings': dict(self.settings_dict)}
    finally:
        connection_pools_lock.release()

def b58encode_int(i, default_one=True):
    """Encode an integer using Base58"""
    if not i and default_one:
        return alphabet[0]
    string = ''
    while i:
        i, idx = divmod(i, 58)
        string = alphabet[idx] + string
    return string

def b58decode_int(v):
    """Decode a Base58 encoded string as an integer"""
    if not isinstance(v, str):
        v = v.decode('ascii')
    decimal = 0
    for char in v:
        decimal = decimal * 58 + alphabet.index(char)
    return decimal

def b58decode(v):
    """Decode a Base58 encoded string"""
    if not isinstance(v, str):
        v = v.decode('ascii')
    origlen = len(v)
    v = v.lstrip(alphabet[0])
    newlen = len(v)
    acc = b58decode_int(v)
    result = []
    while acc > 0:
        acc, mod = divmod(acc, 256)
        result.append(mod)
    return b'\x00' * (origlen - newlen) + bseq(reversed(result))

def render_breadcrumbs(context, *args):
    """Render breadcrumbs html using bootstrap css classes."""
    try:
        template_path = args[0]
    except IndexError:
        template_path = getattr(settings, 'BREADCRUMBS_TEMPLATE', 'django_bootstrap_breadcrumbs/bootstrap2.html')
    links = []
    for label, viewname, view_args, view_kwargs in context['request'].META.get(CONTEXT_KEY, []):
        if isinstance(viewname, Model) and hasattr(viewname, 'get_absolute_url') and ismethod(viewname.get_absolute_url):
            url = viewname.get_absolute_url(*view_args, **view_kwargs)
        else:
            try:
                try:
                    current_app = context['request'].resolver_match.namespace
                except AttributeError:
                    try:
                        resolver_match = resolve(context['request'].path)
                        current_app = resolver_match.namespace
                    except Resolver404:
                        current_app = None
                url = reverse(viewname=viewname, args=view_args, kwargs=view_kwargs, current_app=current_app)
            except NoReverseMatch:
                url = viewname
        links.append((url, smart_text(label) if label else label))
    if not links:
        return ''
    if VERSION > (1, 8):
        context = context.flatten()
    context['breadcrumbs'] = links
    context['breadcrumbs_total'] = len(links)
    return mark_safe(template.loader.render_to_string(template_path, context))

def parse_kraken_report(kdata, max_rank, min_rank):
    """Parse a single output file from the kraken-report tool. Return a list
    of counts at each of the acceptable taxonomic levels, and a list of
    NCBI IDs and a formatted string representing their taxonomic hierarchies.

    :type kdata: str
    :param kdata: Contents of the kraken report file."""
    taxa = OrderedDict()
    counts = OrderedDict()
    r = 0
    max_rank_idx = ranks.index(max_rank)
    min_rank_idx = ranks.index(min_rank)
    for entry in kdata:
        erank = entry['rank'].strip()
        if erank in ranks:
            r = ranks.index(erank)
        tax_lvl = parse_tax_lvl(entry)
        if erank in ranks and min_rank_idx >= ranks.index(entry['rank']) >= max_rank_idx:
            taxon_reads = int(entry['taxon_reads'])
            clade_reads = int(entry['clade_reads'])
            if taxon_reads > 0 or (clade_reads > 0 and entry['rank'] == min_rank):
                taxa[entry['ncbi_tax']] = tax_fmt(tax_lvl, r)
                if entry['rank'] == min_rank:
                    counts[entry['ncbi_tax']] = clade_reads
                else:
                    counts[entry['ncbi_tax']] = taxon_reads
    return (counts, taxa)

def process_samples(kraken_reports_fp, max_rank, min_rank):
    """Parse all kraken-report data files into sample counts dict
    and store global taxon id -> taxonomy data"""
    taxa = OrderedDict()
    sample_counts = OrderedDict()
    for krep_fp in kraken_reports_fp:
        if not osp.isfile(krep_fp):
            raise RuntimeError("ERROR: File '{}' not found.".format(krep_fp))
        sample_id = osp.splitext(osp.split(krep_fp)[1])[0]
        with open(krep_fp, 'rt') as kf:
            try:
                kdr = csv.DictReader(kf, fieldnames=field_names, delimiter='\t')
                kdata = [entry for entry in kdr][1:]
            except OSError as oe:
                raise RuntimeError('ERROR: {}'.format(oe))
        scounts, staxa = parse_kraken_report(kdata, max_rank=max_rank, min_rank=min_rank)
        taxa.update(staxa)
        sample_counts[sample_id] = scounts
    return (sample_counts, taxa)

