def do_get_metadata(parser, token):
    """Retrieve an object which can produce (and format) metadata.

    {% get_metadata [for my_path] [in my_language] [on my_site]
    [as my_variable] %}

    or if you have multiple metadata classes:

    {% get_metadata MyClass [for my_path] [in my_language] [on my_site]
    [as my_variable] %}"""
    bits = list(token.split_contents())
    tag_name = bits[0]
    bits = bits[1:]
    metadata_name = None
    args = {'as': None, 'for': None, 'in': None, 'on': None}
    if len(bits) % 2:
        metadata_name = bits[0]
        bits = bits[1:]
    while len(bits):
        if len(bits) < 2 or bits[0] not in args:
            raise template.TemplateSyntaxError("expected format is '%r [as <variable_name>]'" % tag_name)
        key, value, bits = (bits[0], bits[1], bits[2:])
        args[key] = value
    return MetadataNode(metadata_name, variable_name=args['as'], target=args['for'], site=args['on'], language=args['in'])

def _get_metadata_model(name=None):
    """Find registered Metadata object."""
    if name is not None:
        try:
            return registry[name]
        except KeyError:
            if len(registry) == 1:
                valid_names = 'Try using the name "%s" or simply leaving it out altogether.' % list(registry)[0]
            else:
                valid_names = 'Valid names are ' + ', '.join(('"%s"' % k for k in list(registry)))
            raise Exception('Metadata definition with name "%s" does not exist.\n%s' % (name, valid_names))
    else:
        assert len(registry) == 1, "You must have exactly one Metadata class, if using get_metadata() without a 'name' parameter."
        return list(registry.values())[0]

def jsmin(js, **kwargs):
    """returns a minified version of the javascript string"""
    if not is_3:
        if cStringIO and (not isinstance(js, unicode)):
            klass = cStringIO.StringIO
        else:
            klass = StringIO.StringIO
    else:
        klass = io.StringIO
    ins = klass(js)
    outs = klass()
    JavascriptMinify(ins, outs, **kwargs).minify()
    return outs.getvalue()

def VR(VR=None, description=None):
    """Value Representation (VR) <-> Description lookup.

    :param VR: Takes the VR and returns its description
    :param description: Take the description of a VR and returns the VR"""
    value_repr = {'AE': 'Application Entity', 'AS': 'Age String', 'AT': 'Attribute Tag', 'CS': 'Code String', 'DA': 'Date', 'DS': 'Decimal String', 'DT': 'Date/Time', 'FL': 'Floating Point Single (4 bytes)', 'FD': 'Floating Point Double (8 bytes)', 'IS': 'Integer String', 'LO': 'Long String', 'LT': 'Long Text', 'OB': 'Other Byte', 'OF': 'Other Float', 'OW': 'Other Word', 'PN': 'Person Name', 'SH': 'Short String', 'SL': 'Signed Long', 'SQ': 'Sequence of Items', 'SS': 'Signed Short', 'ST': 'Short Text', 'TM': 'Time', 'UI': 'Unique Identifier', 'UL': 'Unsigned Long', 'UN': 'Unknown', 'US': 'Unsigned Short', 'UT': 'Unlimited Text'}
    assert VR or description, 'Either VR or description required to map VR'
    if VR is not None:
        VR = VR.upper()
        if VR in value_repr:
            return value_repr[VR]
    for key, value in value_repr.iteritems():
        if description == value:
            return key
    return None

def default_listener(col_attr, default):
    """Establish a default-setting listener."""
    @event.listens_for(col_attr, 'init_scalar', retval=True, propagate=True)
    def init_scalar(target, value, dict_):
        if default.is_callable:
            value = default.arg(None)
        elif default.is_scalar:
            value = default.arg
        else:
            raise NotImplementedError("Can't invoke pre-default for a SQL-level column default")
        dict_[col_attr.key] = value
        return value

def read_bytes(fd, byte_order, dtype, count):
    """Read tag data from file and return as byte string."""
    return numpy.fromfile(fd, byte_order + dtype[-1], count).tostring()

def read_numpy(fd, byte_order, dtype, count):
    """Read tag data from file and return as numpy array."""
    return numpy.fromfile(fd, byte_order + dtype[-1], count)

def read_nih_image_header(fd, byte_order, dtype, count):
    """Read NIH_IMAGE_HEADER tag from file and return as dictionary."""
    fd.seek(12, 1)
    return {'version': struct.unpack(byte_order + 'H', fd.read(2))[0]}

def read_mm_header(fd, byte_order, dtype, count):
    """Read MM_HEADER tag from file and return as numpy.rec.array."""
    return numpy.rec.fromfile(fd, MM_HEADER, 1, byteorder=byte_order)[0]

def read_mm_uic1(fd, byte_order, dtype, count):
    """Read MM_UIC1 tag from file and return as dictionary."""
    t = fd.read(8 * count)
    t = struct.unpack('%s%iI' % (byte_order, 2 * count), t)
    return dict(((MM_TAG_IDS[k], v) for k, v in zip(t[::2], t[1::2]) if k in MM_TAG_IDS))

def read_mm_uic2(fd, byte_order, dtype, count):
    """Read MM_UIC2 tag from file and return as dictionary."""
    result = {'number_planes': count}
    values = numpy.fromfile(fd, byte_order + 'I', 6 * count)
    result['z_distance'] = values[0::6] // values[1::6]
    return result

def read_mm_uic3(fd, byte_order, dtype, count):
    """Read MM_UIC3 tag from file and return as dictionary."""
    t = numpy.fromfile(fd, byte_order + 'I', 2 * count)
    return {'wavelengths': t[0::2] // t[1::2]}

def read_cz_lsm_time_stamps(fd, byte_order):
    """Read LSM time stamps from file and return as list."""
    size, count = struct.unpack(byte_order + 'II', fd.read(8))
    if size != 8 + 8 * count:
        raise ValueError('lsm_time_stamps block is too short')
    return struct.unpack('%s%dd' % (byte_order, count), fd.read(8 * count))

def read_cz_lsm_scan_info(fd, byte_order):
    """Read LSM scan information from file and return as Record."""
    block = Record()
    blocks = [block]
    unpack = struct.unpack
    if 268435456 != struct.unpack(byte_order + 'I', fd.read(4))[0]:
        raise ValueError('not a lsm_scan_info structure')
    fd.read(8)
    while True:
        entry, dtype, size = unpack(byte_order + 'III', fd.read(12))
        if dtype == 2:
            value = stripnull(fd.read(size))
        elif dtype == 4:
            value = unpack(byte_order + 'i', fd.read(4))[0]
        elif dtype == 5:
            value = unpack(byte_order + 'd', fd.read(8))[0]
        else:
            value = 0
        if entry in CZ_LSM_SCAN_INFO_ARRAYS:
            blocks.append(block)
            name = CZ_LSM_SCAN_INFO_ARRAYS[entry]
            newobj = []
            setattr(block, name, newobj)
            block = newobj
        elif entry in CZ_LSM_SCAN_INFO_STRUCTS:
            blocks.append(block)
            newobj = Record()
            block.append(newobj)
            block = newobj
        elif entry in CZ_LSM_SCAN_INFO_ATTRIBUTES:
            name = CZ_LSM_SCAN_INFO_ATTRIBUTES[entry]
            setattr(block, name, value)
        elif entry == 4294967295:
            block = blocks.pop()
        else:
            setattr(block, 'unknown_%x' % entry, value)
        if not blocks:
            break
    return block

def _replace_by(module_function, warn=False):
    """Try replace decorated function by module.function."""
    def decorate(func, module_function=module_function, warn=warn):
        sys.path.append(os.path.dirname(__file__))
        try:
            module, function = module_function.split('.')
            func, oldfunc = (getattr(__import__(module), function), func)
            globals()['__old_' + func.__name__] = oldfunc
        except Exception:
            if warn:
                warnings.warn('failed to import %s' % module_function)
        sys.path.pop()
        return func
    return decorate

def decodepackbits(encoded):
    """Decompress PackBits encoded byte string.

    PackBits is a simple byte-oriented run-length compression scheme."""
    func = ord if sys.version[0] == '2' else lambda x: x
    result = []
    i = 0
    try:
        while True:
            n = func(encoded[i]) + 1
            i += 1
            if n < 129:
                result.extend(encoded[i:i + n])
                i += n
            elif n > 129:
                result.extend(encoded[i:i + 1] * (258 - n))
                i += 1
    except IndexError:
        pass
    return b''.join(result) if sys.version[0] == '2' else bytes(result)

def reorient(image, orientation):
    """Return reoriented view of image array.

    Parameters
    ----------
    image : numpy array
        Non-squeezed output of asarray() functions.
        Axes -3 and -2 must be image length and width respectively.
    orientation : int or str
        One of TIFF_ORIENTATIONS keys or values."""
    o = TIFF_ORIENTATIONS.get(orientation, orientation)
    if o == 'top_left':
        return image
    elif o == 'top_right':
        return image[..., ::-1, :]
    elif o == 'bottom_left':
        return image[..., ::-1, :, :]
    elif o == 'bottom_right':
        return image[..., ::-1, ::-1, :]
    elif o == 'left_top':
        return numpy.swapaxes(image, -3, -2)
    elif o == 'right_top':
        return numpy.swapaxes(image, -3, -2)[..., ::-1, :]
    elif o == 'left_bottom':
        return numpy.swapaxes(image, -3, -2)[..., ::-1, :, :]
    elif o == 'right_bottom':
        return numpy.swapaxes(image, -3, -2)[..., ::-1, ::-1, :]

def clean_texmath(txt):
    """    clean tex math string, preserving control sequences
        (incluing
    , so also '
    u') inside $ $, while allowing

     and     to be meaningful in the text string
    """
    s = '%s ' % txt
    out = []
    i = 0
    while i < len(s) - 1:
        if s[i] == '\\' and s[i + 1] in ('n', 't'):
            if s[i + 1] == 'n':
                out.append('\n')
            elif s[i + 1] == 't':
                out.append('\t')
            i += 1
        elif s[i] == '$':
            j = s[i + 1:].find('$')
            if j < 0:
                j = len(s)
            out.append(s[i:j + 2])
            i += j + 2
        else:
            out.append(s[i])
        i += 1
        if i > 5000:
            break
    return ''.join(out).strip()

def rgb(color, default=(0, 0, 0)):
    """return rgb tuple for named color in rgb.txt or a hex color"""
    c = color.lower()
    if c[0:1] == '#' and len(c) == 7:
        r, g, b = (c[1:3], c[3:5], c[5:])
        r, g, b = [int(n, 16) for n in (r, g, b)]
        return (r, g, b)
    if c.find(' ') > -1:
        c = c.replace(' ', '')
    if c.find('gray') > -1:
        c = c.replace('gray', 'grey')
    if c in x11_colors.keys():
        return x11_colors[c]
    return default

def hexcolor(color):
    """returns hex color given a tuple, wx.Color, or X11 named color"""
    if isinstance(color, six.string_types):
        if color[0] == '#' and len(color) == 7:
            return color.lower()
    rgb = (0, 0, 0)
    if isinstance(color, tuple):
        rgb = color
    elif isinstance(color, list):
        rgb = tuple(color)
    elif isinstance(color, six.string_types):
        c = color.lower()
        if c.find(' ') > -1:
            c = c.replace(' ', '')
        if c.find('gray') > -1:
            c = c.replace('gray', 'grey')
        if c in x11_colors:
            rgb = x11_colors[c]
    else:
        try:
            rgb = (color.Red(), color.Green(), color.Blue())
        except:
            pass
    col = '#%02x%02x%02x' % rgb
    return col.lower()

def register_custom_colormaps():
    """registers custom color maps"""
    if not HAS_MPL:
        return ()
    makemap = LinearSegmentedColormap.from_list
    for name, val in custom_colormap_data.items():
        cm1 = np.array(val).transpose().astype('f8') / 256.0
        cm2 = cm1[::-1]
        nam1 = name
        nam2 = '%s_r' % name
        register_cmap(name=nam1, cmap=makemap(nam1, cm1, 256), lut=256)
        register_cmap(name=nam2, cmap=makemap(nam2, cm2, 256), lut=256)
    return ('stdgamma', 'red', 'green', 'blue', 'red_heat', 'green_heat', 'blue_heat', 'magenta', 'yellow', 'cyan')

