def _create_permissions(**kwargs):
    """Almost exactly the same as django.contrib.auth.management.__init__.py"""
    from django.contrib.contenttypes.models import ContentType
    object_tools.autodiscover()
    tools = object_tools.tools._registry
    searched_perms = list()
    ctypes = set()
    for model, tools in tools.items():
        ctype = ContentType.objects.get_for_model(model)
        ctypes.add(ctype)
        for perm in _get_all_permissions(model._meta, tools):
            searched_perms.append((ctype, perm))
    all_perms = set(auth_app.Permission.objects.filter(content_type__in=ctypes).values_list('content_type', 'codename'))
    for ctype, (codename, name) in searched_perms:
        if (ctype.pk, codename) in all_perms:
            continue
        p = auth_app.Permission.objects.create(codename=codename, name=name, content_type=ctype)
        if kwargs.get('verbosity', 2) >= 2:
            print("Adding permission '%s'" % p)

def random_string(random_length=None):
    """A generator for creating random string data of letters plus ' ' (whitespace)

    :params random_length: how many characters of random string data. if not provided, will be between 1 - 30
    :returns: String"""
    choices = string.letters + ' '
    text = []
    if not random_length:
        random_length = random.randint(1, 30)
    for x in range(random_length):
        text.append(random.choice(choices))
    return ''.join(text)

def check_node_attributes(pattern, node, *attributes):
    """Searches match in attributes against given pattern and if
    finds the match against any of them returns True."""
    for attribute_name in attributes:
        attribute = node.get(attribute_name)
        if attribute is not None and pattern.search(attribute):
            return True
    return False

def generate_hash_id(node):
    """Generates a hash_id for the node in question.

    :param node: lxml etree node"""
    try:
        content = tostring(node)
    except Exception:
        logger.exception('Generating of hash failed')
        content = to_bytes(repr(node))
    hash_id = md5(content).hexdigest()
    return hash_id[:8]

def get_class_weight(node):
    """Computes weight of element according to its class/id.

    We're using sets to help efficiently check for existence of matches."""
    weight = 0
    if check_node_attributes(CLS_WEIGHT_NEGATIVE, node, 'class'):
        weight -= 25
    if check_node_attributes(CLS_WEIGHT_POSITIVE, node, 'class'):
        weight += 25
    if check_node_attributes(CLS_WEIGHT_NEGATIVE, node, 'id'):
        weight -= 25
    if check_node_attributes(CLS_WEIGHT_POSITIVE, node, 'id'):
        weight += 25
    return weight

def cached_property(getter):
    """Decorator that converts a method into memoized property.
    The decorator works as expected only for classes with
    attribute '__dict__' and immutable properties."""
    def decorator(self):
        key = '_cached_property_' + getter.__name__
        if not hasattr(self, key):
            setattr(self, key, getter(self))
        return getattr(self, key)
    decorator.__name__ = getter.__name__
    decorator.__module__ = getter.__module__
    decorator.__doc__ = getter.__doc__
    return property(decorator)

def decompressBWT(inputDir, outputDir, numProcs, logger):
    """This is called for taking a BWT and decompressing it back out to it's original form.  While unusual to do,
    it's included in this package for completion purposes.
    @param inputDir - the directory of the compressed BWT we plan on decompressing
    @param outputFN - the directory for the output decompressed BWT, it can be the same, we don't care
    @param numProcs - number of processes we're allowed to use
    @param logger - log all the things!"""
    msbwt = MultiStringBWT.CompressedMSBWT()
    msbwt.loadMsbwt(inputDir, logger)
    outputFile = np.lib.format.open_memmap(outputDir + '/msbwt.npy', 'w+', '<u1', (msbwt.getTotalSize(),))
    del outputFile
    worksize = 1000000
    tups = [None] * (msbwt.getTotalSize() / worksize + 1)
    x = 0
    if msbwt.getTotalSize() > worksize:
        for x in xrange(0, msbwt.getTotalSize() / worksize):
            tups[x] = (inputDir, outputDir, x * worksize, (x + 1) * worksize)
        tups[-1] = (inputDir, outputDir, (x + 1) * worksize, msbwt.getTotalSize())
    else:
        tups[0] = (inputDir, outputDir, 0, msbwt.getTotalSize())
    if numProcs > 1:
        myPool = multiprocessing.Pool(numProcs)
        rets = myPool.map(decompressBWTPoolProcess, tups)
    else:
        rets = []
        for tup in tups:
            rets.append(decompressBWTPoolProcess(tup))

