    :param session: requests Session instance
    :param name: str, package name
    :param data: dict, meta data
    :param find_changelogs_fn: function, find_changelogs
    :return: tuple, (set(changelog URLs), set(repo URLs))"""
    if 'versions' in data:
        candidates = set()
        for version, item in data['versions'].items():
            if 'homepage' in item and item['homepage'] is not None:
                if isinstance(item['homepage'], list):
                    candidates.add(*item['homepage'])
                else:
                    candidates.add(item['homepage'])
            if 'repository' in item and item['repository'] is not None:
                if 'url' in item['repository']:
                    repo = item['repository']['url']
                elif 'path' in item['repository']:
                    repo = item['repository']['path']
                else:
                    continue
                repo = repo.replace('git://', 'https://').replace('.git', '')
                candidates.add(repo)
        return find_changelogs_fn(session=session, name=name, candidates=candidates)
    return (set(), set())

def check_for_launchpad(old_vendor, name, urls):
    """Check if the project is hosted on launchpad.

    :param name: str, name of the project
    :param urls: set, urls to check.
    :return: the name of the project on launchpad, or an empty string."""
    if old_vendor != 'pypi':
        return ''
    for url in urls:
        try:
            return re.match('https?://launchpad.net/([\\w.\\-]+)', url).groups()[0]
        except AttributeError:
            continue
    return ''

def check_switch_vendor(old_vendor, name, urls, _depth=0):
    """Check if the project should switch vendors. E.g
    project pushed on pypi, but changelog on launchpad.

    :param name: str, name of the project
    :param urls: set, urls to check.
    :return: tuple, (str(new vendor name), str(new project name))"""
    if _depth > 3:
        return ''
    new_name = check_for_launchpad(old_vendor, name, urls)
    if new_name:
        return ('launchpad', new_name)
    return ('', '')

def get_commit_log(name, vendor='pypi', functions={}, _depth=0):
    """Tries to parse a changelog from the raw commit log.
    :param name: str, package name
    :param vendor: str, vendor
    :param functions: dict, custom functions
    :return: tuple, (dict -> commit log, str -> raw git log)"""
    if 'find_changelogs' not in functions:
        from .finder import find_git_repo
        functions['find_changelogs'] = find_git_repo
    if 'get_content' not in functions:
        functions['get_content'] = clone_repo
    if 'parse' not in functions:
        from .parser import parse_commit_log
        functions['parse'] = parse_commit_log
    return get(name=name, vendor=vendor, functions=functions)

def get_content(session, urls):
    """Loads the content from URLs, ignoring connection errors.
    :param session: requests Session instance
    :param urls: list, str URLs
    :return: str, content"""
    content = ''
    for url in urls:
        try:
            logger.debug('GET changelog from {url}'.format(url=url))
            if 'https://api.github.com' in url and url.endswith('releases'):
                if not GITHUB_API_TOKEN:
                    logger.warning('Fetching release pages requires CHANGELOGS_GITHUB_API_TOKEN to be set')
                    continue
                resp = session.get(url, headers={'Authorization': 'token {}'.format(GITHUB_API_TOKEN)})
                if resp.status_code == 200:
                    for item in resp.json():
                        content += '\n\n{}\n{}'.format(item['tag_name'], item['body'])
            else:
                resp = session.get(url)
                if resp.status_code == 200:
                    content += '\n\n' + resp.text
        except requests.ConnectionError:
            pass
    return content

def get_metadata(session, name):
    """Gets meta data from launchpad for the given package.
    :param session: requests Session instance
    :param name: str, package
    :return: dict, meta data"""
    resp = session.get('https://api.launchpad.net/1.0/{}/releases'.format(name))
    if resp.status_code == 200:
        return resp.json()
    return {}

def get_content(session, urls):
    """Loads the content from URLs, ignoring connection errors.
    :param session: requests Session instance
    :param urls: list, str URLs
    :return: str, content"""
    for url in urls:
        resp = session.get(url)
        if resp.ok:
            return resp.json()
    return {}

def parse(name, content, releases, get_head_fn):
    """Parses the given content for a valid changelog
    :param name: str, package name
    :param content: str, content
    :param releases: list, releases
    :param get_head_fn: function
    :return: dict, changelog"""
    try:
        return {e['version']: e['changelog'] for e in content['entries'] if e['changelog']}
    except KeyError:
        return {}

def validate_url(url):
    """Validates the URL
    :param url:
    :return:"""
    if validators.url(url):
        return url
    elif validators.domain(url):
        return 'http://{}'.format(url)
    return ''

def validate_repo_url(url):
    """Validates and formats `url` to be valid URL pointing to a repo on bitbucket.org or github.com
    :param url: str, URL
    :return: str, valid URL if valid repo, emptry string otherwise"""
    try:
        if 'github.com' in url:
            return re.findall('https?://w?w?w?.?github.com/[\\w\\-]+/[\\w.-]+', url)[0]
        elif 'bitbucket.org' in url:
            return re.findall('https?://bitbucket.org/[\\w.-]+/[\\w.-]+', url)[0] + '/src/'
        elif 'launchpad.net' in url:
            return re.findall('https?://launchpad.net/[\\w.-]+', url)[0]
        elif 'sourceforge.net' in url:
            mo = re.match('https?://sourceforge.net/projects/([\\w.-]+)/', url, re.I)
            template = 'https://sourceforge.net/p/{}/code/HEAD/tree/trunk/src/'
            return template.format(mo.groups()[0])
    except (IndexError, AttributeError):
        pass
    return ''

def contains_project_name(name, link):
    """Checks if the given link `somewhat` contains the project name.
    :param name: str, project name
    :param link: str, link
    :return: bool, True if the link contains the project name"""
    def unclutter(string):
        string = string.lower().replace('_', '-').replace('.', '-')
        for replace in ['python-', 'py-', '-py', '-python']:
            string = string.replace(replace, '')
        return re.sub('[^0123456789 a-zA-Z]', '', string).strip()
    return unclutter(name) in unclutter(link)

def find_repo_urls(session, name, candidates):
    """Visits the given URL candidates and searches the page for valid links to a repository.
    :param session: requests Session instance
    :param name: str, project name
    :param candidates: list, list of URL candidates
    :return: str, URL to a repo"""
    for _url in candidates:
        if validate_url(_url):
            try:
                resp = session.get(_url)
                if resp.status_code == 200:
                    tree = etree.HTML(resp.content)
                    if tree:
                        for link in frozenset([str(l) for l in tree.xpath('//a/@href')]):
                            if ('github.com' in link or 'bitbucket.org' in link or 'sourceforge.net' in link) and contains_project_name(name, link):
                                link = validate_url(validate_repo_url(url=link))
                                if link:
                                    logger.debug('Found repo URL {}'.format(link))
                                    yield link
            except ConnectionError:
                pass
            except etree.XMLSyntaxError:
                pass
            except UnicodeEncodeError:
                pass

def find_changelogs(session, name, candidates):
    """Tries to find changelogs on the given URL candidates
    :param session: requests Session instance
    :param name: str, project name
    :param candidates: list, URL candidates
    :return: tuple, (set(changelog URLs), set(repo URLs))"""
    repos = filter_repo_urls(candidates=candidates)
    if not repos:
        logger.info('No repo found, trying to find one on related sites {}'.format(candidates))
        repos = set(find_repo_urls(session, name, candidates))
    urls = []
    for repo in repos:
        for url in find_changelog(session, repo):
            if not contains_project_name(name, url):
                logger.debug('Found changelog on {url}, but it does not contain the project name {name}, aborting'.format(name=name, url=url))
                continue
            urls.append(url)
    if not urls:
        logger.debug('No plain changelog urls found, trying release page')
        for repo in repos:
            if contains_project_name(name, repo):
                for url in find_release_page(session, repo):
                    urls.append(url)
    return (set(urls), repos)

def find_git_repo(session, name, candidates):
    """Tries to find git repos on the given URL candidates
    :param session: requests Session instance
    :param name: str, project name
    :param candidates: list, URL candidates
    :return: tuple, (set(git URLs), set(repo URLs))"""
    repos = filter_repo_urls(candidates=candidates)
    if not repos:
        logger.info('No repo found, trying to find one on related sites {}'.format(candidates))
        repos = set(find_repo_urls(session, name, candidates))
    urls = []
    for repo in repos:
        username, reponame = repo.split('/')[3:5]
        if 'github.com' in repo:
            urls.append('https://github.com/{username}/{reponame}.git'.format(username=username, reponame=reponame))
        elif 'bitbucket.org' in repo:
            urls.append('https://bitbucket.org/{username}/{reponame}'.format(username=username, reponame=reponame))
    return (set(urls), repos)

def get_url_map():
    """Loads custom/pypi/map.txt and builds a dict where map[package_name] = url
    :return: dict, urls"""
    map = {}
    path = os.path.join(os.path.dirname(os.path.realpath(__file__)), 'custom', 'pypi', 'map.txt')
    with open(path) as f:
        for line in f.readlines():
            package, url = line.strip().split(': ')
            map[package] = url
    return map

def get_urls(session, name, data, find_changelogs_fn, **kwargs):
    """Gets URLs to changelogs.
    :param session: requests Session instance
    :param name: str, package name
    :param data: dict, meta data
    :param find_changelogs_fn: function, find_changelogs
    :return: tuple, (set(changelog URLs), set(repo URLs))"""
    map = get_url_map()
    if name.lower().replace('_', '-') in map:
        logger.info("Package {name}'s URL is in pypi/map.txt, returning".format(name=name))
        return ([map[name.lower().replace('_', '-')]], set())
    if 'info' in data:
        candidates = [url for url in [data['info'].get(attr) for attr in ('home_page', 'docs_url', 'bugtrack_url')] if url]
        candidates.append('https://pypi.python.org/pypi/{name}/{latest_release}'.format(name=name, latest_release=next(iter(get_releases(data)))))
        if 'download_url' in data:
            candidates.append(data['download_url'])
        if data['info']['description']:
            candidates.extend(changelogs.url_re.findall(data['info']['description']))
        return find_changelogs_fn(session=session, name=name, candidates=candidates)
    return (set(), set())

def validate_meta(meta):
    """Validates Linguist Meta attribute."""
    if not isinstance(meta, (dict,)):
        raise TypeError('Model Meta "linguist" must be a dict')
    required_keys = ('identifier', 'fields')
    for key in required_keys:
        if key not in meta:
            raise KeyError('Model Meta "linguist" dict requires %s to be defined', key)
    if not isinstance(meta['fields'], (list, tuple)):
        raise ImproperlyConfigured("Linguist Meta's fields attribute must be a list or tuple")

def default_value_getter(field):
    """When accessing to the name of the field itself, the value
    in the current language will be returned. Unless it's set,
    the value in the default language will be returned."""
    def default_value_func_getter(self):
        localized_field = utils.build_localized_field_name(field, self._linguist.active_language)
        value = getattr(self, localized_field)
        if value:
            return value
        default_field = utils.build_localized_field_name(field, self.default_language)
        return getattr(self, default_field)
    return default_value_func_getter

def create_translation_field(translated_field, language):
    """Takes the original field, a given language, a decider model and return a
    Field class for model."""
    cls_name = translated_field.__class__.__name__
    if not isinstance(translated_field, tuple(SUPPORTED_FIELDS.keys())):
        raise ImproperlyConfigured('%s is not supported by Linguist.' % cls_name)
    translation_class = field_factory(translated_field.__class__)
    kwargs = get_translation_class_kwargs(translated_field.__class__)
    return translation_class(translated_field=translated_field, language=language, **kwargs)

def delete_translations(sender, instance, **kwargs):
    """Deletes related instance's translations when instance is deleted."""
    if issubclass(sender, (ModelMixin,)):
        instance._linguist.decider.objects.filter(identifier=instance.linguist_identifier, object_id=instance.pk).delete()

def draw_tree(node, child_iter=lambda n: n.children, text_str=str):
    """Support asciitree 0.2 API.

    This function solely exist to not break old code (using asciitree 0.2).
    Its use is deprecated."""
    return LeftAligned(traverse=Traversal(get_text=text_str, get_children=child_iter), draw=LegacyStyle())(node)

def get_language():
    """Returns an active language code that is guaranteed to be in
    settings.SUPPORTED_LANGUAGES."""
    lang = _get_language()
    if not lang:
        return get_fallback_language()
    langs = [l[0] for l in settings.SUPPORTED_LANGUAGES]
    if lang not in langs and '-' in lang:
        lang = lang.split('-')[0]
    if lang in langs:
        return lang
    return settings.DEFAULT_LANGUAGE

def activate_language(instances, language):
    """Activates the given language for the given instances."""
    language = language if language in get_supported_languages() else get_fallback_language()
    for instance in instances:
        instance.activate_language(language)

def get_model_string(model_name):
    """Returns the model string notation Django uses for lazily loaded ForeignKeys
    (eg 'auth.User') to prevent circular imports.
    This is needed to allow our crazy custom model usage."""
    setting_name = 'LINGUIST_%s_MODEL' % model_name.upper().replace('_', '')
    class_path = getattr(settings, setting_name, None)
    if not class_path:
        return 'linguist.%s' % model_name
    elif isinstance(class_path, basestring):
        parts = class_path.split('.')
        try:
            index = parts.index('models') - 1
        except ValueError:
            raise exceptions.ImproperlyConfigured(CLASS_PATH_ERROR % (setting_name, setting_name))
        app_label, model_name = (parts[index], parts[-1])
    else:
        try:
            class_path, app_label = class_path
            model_name = class_path.split('.')[-1]
        except:
            raise exceptions.ImproperlyConfigured(CLASS_PATH_ERROR % (setting_name, setting_name))
    return '%s.%s' % (app_label, model_name)

def prefetch_translations(instances, **kwargs):
    """Prefetches translations for the given instances.
    Can be useful for a list of instances."""
    from .mixins import ModelMixin
    if not isinstance(instances, collections.Iterable):
        instances = [instances]
    populate_missing = kwargs.get('populate_missing', True)
    grouped_translations = utils.get_grouped_translations(instances, **kwargs)
    if not grouped_translations and populate_missing:
        for instance in instances:
            instance.populate_missing_translations()
    for instance in instances:
        if issubclass(instance.__class__, ModelMixin) and instance.pk in grouped_translations:
            for translation in grouped_translations[instance.pk]:
                instance._linguist.set_cache(instance=instance, translation=translation)
            if populate_missing:
                instance.populate_missing_translations()

def _build_block_context(template, context):
    """Populate the block context with BlockNodes from parent templates."""
    if BLOCK_CONTEXT_KEY not in context.render_context:
        context.render_context[BLOCK_CONTEXT_KEY] = BlockContext()
    block_context = context.render_context[BLOCK_CONTEXT_KEY]
    for node in template.nodelist:
        if isinstance(node, ExtendsNode):
            compiled_parent = node.get_parent(context)
            block_context.add_blocks({n.name: n for n in compiled_parent.nodelist.get_nodes_by_type(BlockNode)})
            _build_block_context(compiled_parent, context)
            return compiled_parent
        if not isinstance(node, TextNode):
            break

def _render_template_block_nodelist(nodelist, block_name, context):
    """Recursively iterate over a node to find the wanted block."""
    for node in nodelist:
        if isinstance(node, BlockNode):
            context.render_context[BLOCK_CONTEXT_KEY].push(node.name, node)
            if node.name == block_name:
                return node.render(context)
        for attr in node.child_nodelists:
            try:
                new_nodelist = getattr(node, attr)
            except AttributeError:
                continue
            try:
                return _render_template_block_nodelist(new_nodelist, block_name, context)
            except BlockNotFound:
                continue
    raise BlockNotFound("block with name '%s' does not exist" % block_name)

def render_block_to_string(template_name, block_name, context=None):
    """Loads the given template_name and renders the given block with the given
    dictionary as context. Returns a string.

        template_name
            The name of the template to load and render. If it's a list of
            template names, Django uses select_template() instead of
            get_template() to find the template."""
    if isinstance(template_name, (tuple, list)):
        t = loader.select_template(template_name)
    else:
        t = loader.get_template(template_name)
    context = context or {}
    if isinstance(t, DjangoTemplate):
        return django_render_block(t, block_name, context)
    elif isinstance(t, Jinja2Template):
        from render_block.jinja2 import jinja2_render_block
        return jinja2_render_block(t, block_name, context)
    else:
        raise UnsupportedEngine('Can only render blocks from the Django template backend.')

def format_command(cmd, shell=False):
    """Converts a command line to the notation as used in a Dockerfile ``CMD`` and ``ENTRYPOINT`` command. In shell
    notation, this returns a simple string, whereas by default it returns a JSON-list format with the command and
    arguments.

    :param cmd: Command line as a string or tuple.
    :type cmd: unicode | str | tuple | list
    :param shell: Use the notation so that Docker runs the command in a shell. Default is ``False``.
    :type shell: bool
    :return: The command string.
    :rtype: unicode | str"""
    def _split_cmd():
        line = None
        for part in cmd.split(' '):
            line = part if line is None else '{0} {1}'.format(line, part)
            if part[-1] != '\\':
                yield line
                line = None
        if line is not None:
            yield line
    if cmd in ([], ''):
        return '[]'
    if shell:
        if isinstance(cmd, (list, tuple)):
            return ' '.join(cmd)
        elif isinstance(cmd, six.string_types):
            return cmd
    elif isinstance(cmd, (list, tuple)):
        return json.dumps(map(six.text_type, cmd))
    elif isinstance(cmd, six.string_types):
        return json.dumps(list(_split_cmd()))
    raise ValueError('Invalid type of command string or sequence: {0}'.format(cmd))

def format_expose(expose):
    """Converts a port number or multiple port numbers, as used in the Dockerfile ``EXPOSE`` command, to a tuple.

    :param: Port numbers, can be as integer, string, or a list/tuple of those.
    :type expose: int | unicode | str | list | tuple
    :return: A tuple, to be separated by spaces before inserting in a Dockerfile.
    :rtype: tuple"""
    if isinstance(expose, six.string_types):
        return (expose,)
    elif isinstance(expose, collections.Iterable):
        return map(six.text_type, expose)
    return (six.text_type(expose),)

def rest(f):
    """Decorator for simple REST endpoints.

    Functions must return one of these values:
    - a dict to jsonify
    - nothing for an empty 204 response
    - a tuple containing a status code and a dict to jsonify"""
    @wraps(f)
    def wrapper(*args, **kwargs):
        ret = f(*args, **kwargs)
        if ret is None:
            response = ('', 204)
        elif isinstance(ret, current_app.response_class):
            response = ret
        elif isinstance(ret, tuple):
            if isinstance(ret[1], basestring):
                response = jsonify(msg=ret[1])
            else:
                response = jsonify(**ret[1])
            response.status_code = ret[0]
        else:
            response = jsonify(**ret)
        return response
    return wrapper

def parse_networks_output(out):
    """Parses the output of the Docker CLI 'docker network ls' and returns it in the format similar to the Docker API.

    :param out: CLI output.
    :type out: unicode | str
    :return: Parsed result.
    :rtype: list[dict]"""
    if not out:
        return []
    line_iter = islice(out.splitlines(), 1, None)
    return list(map(_network_info, line_iter))

def parse_volumes_output(out):
    """Parses the output of the Docker CLI 'docker volume ls' and returns it in the format similar to the Docker API.

    :param out: CLI output.
    :type out: unicode | str
    :return: Parsed result.
    :rtype: list[dict]"""
    if not out:
        return []
    line_iter = islice(out.splitlines(), 1, None)
    return list(map(_volume_info, line_iter))

def parse_version_output(out):
    """Parses the output of 'docker version --format="{{json .}}"'. Essentially just returns the parsed JSON string,
    like the Docker API does. Fields are slightly different however.

    :param out: CLI output.
    :type out: unicode | str
    :return: Parsed result.
    :rtype: dict"""
    parsed = json.loads(out, encoding='utf-8')
    if parsed:
        return parsed.get('Client', {})
    return {}

def parse_response(response):
    """Decodes the JSON response, simply ignoring syntax errors. Therefore it should be used for filtering visible output
    only.

    :param response: Server response as a JSON string.
    :type response: unicode | str
    :return: Decoded object from the JSON string. Returns an empty dictionary if input was invalid.
    :rtype: dict"""
    if isinstance(response, six.binary_type):
        response = response.decode('utf-8')
    try:
        obj = json.loads(response)
    except ValueError:
        return {}
    return obj

def tag_check_function(tags):
    """Generates a function that checks whether the given image has any of the listed tags.

    :param tags: Tags to check for.
    :type tags: list[unicode | str] | set[unicode | str]
    :return: Function that returns ``True`` if any of the given tags apply to the image, ``False`` otherwise.
    :rtype: (unicode | str) -> bool"""
    suffixes = [':{0}'.format(t) for t in tags]
    def _check_image(image):
        repo_tags = image['RepoTags']
        if not repo_tags:
            return False
        return any((r_tag.endswith(s) for s in suffixes for r_tag in repo_tags))
    return _check_image

def resolve_value(value, types=type_registry):
    """Returns the actual value for the given object, if it is a late-resolving object type.
    If not, the value itself is simply returned.

    :param value: Lazy object, registered type in :attr:`type_registry`, or a simple value. In the
     latter case, the value is returned as-is.
    :type value: str | unicode | int | AbstractLazyObject | unknown
    :return: Resolved value."""
    if value is None:
        return None
    elif isinstance(value, lazy_type):
        return value.get()
    elif types:
        resolve_func = types.get(expand_type_name(type(value)))
        if resolve_func:
            return resolve_func(value)
    return value

def resolve_deep(values, max_depth=5, types=None):
    """Resolves all late-resolving types into their current values to a certain depth in a dictionary or list.

    :param values: Values to resolve of any type.
    :param max_depth: Maximum depth to recurse into nested lists, tuples and dictionaries. Below that depth values are
     returned as they are.
    :type max_depth: int
    :param: Dictionary of types and functions to resolve, that are not registered in ``type_registry``.
    :type: dict[unicode | str, function]
    :return: Resolved values."""
    def _resolve_sub(v, level):
        l1 = level + 1
        res_val = resolve_value(v, all_types)
        if l1 < max_depth:
            if isinstance(res_val, (list, tuple)):
                return [_resolve_sub(item, l1) for item in res_val]
            elif isinstance(res_val, dict):
                return {resolve_value(rk, all_types): _resolve_sub(rv, l1) for rk, rv in iteritems(res_val)}
        return res_val
    if types:
        all_types = type_registry.copy()
        all_types.update(types)
    else:
        all_types = type_registry
    return _resolve_sub(values, -1)

def merge_dependency_paths(item_paths):
    """Utility function that merges multiple dependency paths, as far as they share dependencies. Paths are evaluated
    and merged in the incoming order. Later paths that are independent, but share some dependencies, are shortened
    by these dependencies. Paths that are contained in another entirely are discarded.

    :param item_paths: List or tuple of items along with their dependency path.
    :type item_paths: collections.Iterable[(Any, list[Any])]
    :return: List of merged or independent paths.
    :rtype: list[(Any, list[Any])]"""
    merged_paths = []
    for item, path in item_paths:
        sub_path_idx = []
        path_set = set(path)
        for index, (merged_item, merged_path, merged_set) in enumerate(merged_paths):
            if item in merged_set:
                path = None
                break
            elif merged_item in path_set:
                sub_path_idx.append(index)
            elif merged_set & path_set:
                path = [p for p in path if p not in merged_set]
                path_set = set(path)
                if not path:
                    break
        for spi in reversed(sub_path_idx):
            merged_paths.pop(spi)
        if path is not None:
            merged_paths.append((item, path, path_set))
    return [(i[0], i[1]) for i in merged_paths]

def get_instance_volumes(instance_detail, check_names):
    """Extracts the mount points and mapped directories or names of a Docker container.

    :param instance_detail: Result from a container inspection.
    :type instance_detail: dict
    :param check_names: Whether to check for named volumes.
    :type check_names: bool
    :return: Dictionary of volumes, with the destination (inside the container) as a key, and the source (external to
     the container) as values. If ``check_names`` is ``True``, the value contains the mounted volume name instead.
    :rtype: dict[unicode | str, unicode | str]"""
    if 'Mounts' in instance_detail:
        if check_names:
            return {m['Destination']: m.get('Name') or m['Source'] for m in instance_detail['Mounts']}
        return {m['Destination']: m['Source'] for m in instance_detail['Mounts']}
    return instance_detail.get('Volumes') or {}

def get_list(value):
    """Wraps the given value in a list. ``None`` returns an empty list. Lists and tuples are returned as lists. Single
    strings and registered types are wrapped in a list.

    :param value: Value to return as a list.
    :return: List with the provided value(s).
    :rtype: list"""
    if value is None:
        return []
    elif value is NotSet:
        return NotSet
    elif isinstance(value, (list, tuple)):
        return list(value)
    elif isinstance(value, six.string_types + (lazy_type,)) or uses_type_registry(value):
        return [value]
    raise ValueError('Invalid type; expected a list, tuple, or string type, found {0}.'.format(type(value).__name__))

def get_network_mode(value):
    """Generates input for the ``network_mode`` of a Docker host configuration. If it points at a container, the
    configuration of the container is returned.

    :param value: Network mode input.
    :type value: unicode | str | tuple | list | NoneType
    :return: Network mode or container to re-use the network stack of.
    :rtype: unicode | str | tuple | NoneType"""
    if not value or value == 'disabled':
        return 'none'
    if isinstance(value, (tuple, list)):
        if len(value) == 2:
            return tuple(value)
        return ValueError('Tuples or lists need to have length 2 for container network references.')
    if value in DEFAULT_PRESET_NETWORKS:
        return value
    if value.startswith('container:'):
        return value
    if value.startswith('/'):
        return 'container:{0}'.format(value[1:])
    ref_name, __, ref_instance = value.partition('.')
    return (ref_name, ref_instance or None)

def get_healthcheck(value):
    """Converts input into a :class:`HealthCheck` tuple. Input can be passed as string, tuple, list, or a dictionary. If
    set to ``None``, the health check will be set to ``NONE``, i.e. override an existing configuration from the image.

    :param value: Health check input.
    :type value: unicode | str | tuple | list | NoneType
    :return: HealthCheck tuple
    :rtype: HealthCheck"""
    if isinstance(value, HealthCheck):
        return value
    elif isinstance(value, six.string_types + (lazy_type,)) or uses_type_registry(value):
        return HealthCheck(value)
    elif isinstance(value, (tuple, list)):
        return HealthCheck(*value)
    elif isinstance(value, dict):
        return HealthCheck(**value)
    raise ValueError('Invalid type; expected a list, tuple, dict, or string type, found {0}.'.format(type(value).__name__))

def expand_instances(config_ids, ext_maps):
    """Iterates over a list of input configuration ids, expanding configured instances if ``None`` is specified. Otherwise
    where instance names are specified as a tuple, they are expanded.

    :param config_ids: Iterable of container configuration ids or (map, config, instance names) tuples.
    :type config_ids: collections.Iterable[dockermap.map.input.InputConfigId] | collections.Iterable[tuple[unicode | str, unicode | str, unicode | str]]
    :param ext_maps: Dictionary of extended ContainerMap instances for looking up container configurations.
    :type ext_maps: dict[unicode | str, ContainerMap]
    :return: MapConfigId tuples.
    :rtype: collections.Iterable[dockermap.map.input.MapConfigId]"""
    for type_map_config, items in itertools.groupby(sorted(config_ids, key=get_map_config), get_map_config):
        config_type, map_name, config_name = type_map_config
        instances = _get_nested_instances(items)
        c_map = ext_maps[map_name]
        try:
            c_instances = _get_config_instances(config_type, c_map, config_name)
        except KeyError:
            raise KeyError('Configuration not found.', type_map_config)
        if c_instances and None in instances:
            for i in c_instances:
                yield MapConfigId(config_type, map_name, config_name, i)
        else:
            for i in instances:
                yield MapConfigId(config_type, map_name, config_name, i)

def get_user_group(user_group):
    """Formats a user and group in the format ``user:group``, as needed for `chown`. If user_group is a tuple, this is used
    for the fomatting. If a string or integer is given, it will be formatted as ``user:user``. Otherwise the input is
    returned - this method does not perform any more checks.

    :param user_group: User name, user id, user and group in format ``user:group``, ``user_id:group_id``, or tuple of
      ``(user, group)``.
    :type user_group: unicode | str | int | tuple
    :return: Formatted string with in the format ``user:group``.
    :rtype: unicode | str"""
    if isinstance(user_group, tuple):
        return '{0}:{1}'.format(*user_group)
    elif isinstance(user_group, six.integer_types) or ':' not in user_group:
        return '{0}:{0}'.format(user_group)
    return user_group

def create_translated_fields_serializer(shared_model, meta=None, related_name=None, **fields):
    """Create a Rest Framework serializer class for a translated fields model.

    :param shared_model: The shared model.
    :type shared_model: :class:`parler.models.TranslatableModel`"""
    if not related_name:
        translated_model = shared_model._parler_meta.root_model
    else:
        translated_model = shared_model._parler_meta[related_name].model
    if not meta:
        meta = {}
    meta['model'] = translated_model
    meta.setdefault('fields', ['language_code'] + translated_model.get_translated_fields())
    attrs = {}
    attrs.update(fields)
    attrs['Meta'] = type('Meta', (), meta)
    return type('{0}Serializer'.format(translated_model.__name__), (serializers.ModelSerializer,), attrs)

