def prepend_path(orig, text, pathsep=os.pathsep):
    """Returns a $PATH-like environment variable with `text` prepended. `orig` is
    the original variable value, or None. `pathsep` is the character
    separating path elements, defaulting to `os.pathsep`.

    Example:

    newpath = cli.prepend_path(oldpath, '/mypackage/bin')

    See also `prepend_environ_path`."""
    if orig is None:
        orig = ''
    if not len(orig):
        return text
    return ''.join([text, pathsep, orig])

def try_open(*args, **kwargs):
    """Simply a wrapper for io.open(), unless an IOError with errno=2 (ENOENT) is
    raised, in which case None is retured."""
    try:
        return io.open(*args, **kwargs)
    except IOError as e:
        if e.errno == 2:
            return None
        raise

def make_path_func(*baseparts):
    """Return a function that joins paths onto some base directory."""
    from os.path import join
    base = join(*baseparts)
    def path_func(*args):
        return join(base, *args)
    return path_func

def djoin(*args):
    """'dotless' join, for nicer paths."""
    from os.path import join
    i = 0
    alen = len(args)
    while i < alen and (args[i] == '' or args[i] == '.'):
        i += 1
    if i == alen:
        return '.'
    return join(*args[i:])

def rellink(source, dest):
    """Create a symbolic link to path *source* from path *dest*. If either
    *source* or *dest* is an absolute path, the link from *dest* will point to
    the absolute path of *source*. Otherwise, the link to *source* from *dest*
    will be a relative link."""
    from os.path import isabs, dirname, relpath, abspath
    if isabs(source):
        os.symlink(source, dest)
    elif isabs(dest):
        os.symlink(abspath(source), dest)
    else:
        os.symlink(relpath(source, dirname(dest)), dest)

def ensure_dir(path, parents=False):
    """Returns a boolean indicating whether the directory already existed. Will
    attempt to create parent directories if *parents* is True."""
    if parents:
        from os.path import dirname
        parent = dirname(path)
        if len(parent) and parent != path:
            ensure_dir(parent, True)
    try:
        os.mkdir(path)
    except OSError as e:
        if e.errno == 17:
            return True
        raise
    return False

def ensure_symlink(src, dst):
    """Ensure the existence of a symbolic link pointing to src named dst. Returns
    a boolean indicating whether the symlink already existed."""
    try:
        os.symlink(src, dst)
    except OSError as e:
        if e.errno == 17:
            return True
        raise
    return False

def enumeration(cls):
    """A very simple decorator for creating enumerations. Unlike Python 3.4
    enumerations, this just gives a way to use a class declaration to create
    an immutable object containing only the values specified in the class.

    If the attribute ``__pickle_compat__`` is set to True in the decorated
    class, the resulting enumeration value will be callable such that
    ``EnumClass(x) = x``. This is needed to unpickle enumeration values that
    were previously implemented using :class:`enum.Enum`."""
    from pwkit import unicode_to_str
    name = cls.__name__
    pickle_compat = getattr(cls, '__pickle_compat__', False)
    def __unicode__(self):
        return '<enumeration holder %s>' % name
    def getattr_error(self, attr):
        raise AttributeError('enumeration %s does not contain attribute %s' % (name, attr))
    def modattr_error(self, *args, **kwargs):
        raise AttributeError('modification of %s enumeration not allowed' % name)
    clsdict = {'__doc__': cls.__doc__, '__slots__': (), '__unicode__': __unicode__, '__str__': unicode_to_str, '__repr__': unicode_to_str, '__getattr__': getattr_error, '__setattr__': modattr_error, '__delattr__': modattr_error}
    for key in dir(cls):
        if not key.startswith('_'):
            clsdict[key] = getattr(cls, key)
    if pickle_compat:
        clsdict['__call__'] = lambda self, x: x
    enumcls = type(name, (object,), clsdict)
    return enumcls()

def weighted_variance(x, weights):
    """Return the variance of a weighted sample.

    The weighted sample mean is calculated and subtracted off, so the returned
    variance is upweighted by ``n / (n - 1)``. If the sample mean is known to
    be zero, you should just compute ``np.average (x**2, weights=weights)``."""
    n = len(x)
    if n < 3:
        raise ValueError('cannot calculate meaningful variance of fewer than three samples')
    wt_mean = np.average(x, weights=weights)
    return np.average(np.square(x - wt_mean), weights=weights) * n / (n - 1)

def unit_tophat_ee(x):
    """Tophat function on the unit interval, left-exclusive and right-exclusive.
    Returns 1 if 0 < x < 1, 0 otherwise."""
    x = np.asarray(x)
    x1 = np.atleast_1d(x)
    r = ((0 < x1) & (x1 < 1)).astype(x.dtype)
    if x.ndim == 0:
        return np.asscalar(r)
    return r

def make_tophat_ee(lower, upper):
    """Return a ufunc-like tophat function on the defined range, left-exclusive
    and right-exclusive. Returns 1 if lower < x < upper, 0 otherwise."""
    if not np.isfinite(lower):
        raise ValueError('"lower" argument must be finite number; got %r' % lower)
    if not np.isfinite(upper):
        raise ValueError('"upper" argument must be finite number; got %r' % upper)
    def range_tophat_ee(x):
        x = np.asarray(x)
        x1 = np.atleast_1d(x)
        r = ((lower < x1) & (x1 < upper)).astype(x.dtype)
        if x.ndim == 0:
            return np.asscalar(r)
        return r
    range_tophat_ee.__doc__ = 'Ranged tophat function, left-exclusive and right-exclusive. Returns 1 if %g < x < %g, 0 otherwise.' % (lower, upper)
    return range_tophat_ee

