def bp_to_aap(bp):
    """Converts a basepol into a tuple of (ant1, ant2, pol)."""
    ap1, ap2 = bp
    if ap1 < 0:
        raise ValueError('first antpol %d is negative' % ap1)
    if ap2 < 0:
        raise ValueError('second antpol %d is negative' % ap2)
    pol = _fpol_to_pol[((ap1 & 7) << 4) + (ap2 & 7)]
    if pol == 255:
        raise ValueError('no CASA polarization code for pairing %c-%c' % (fpol_names[ap1 & 7], fpol_names[ap2 & 7]))
    return (ap1 >> 3, ap2 >> 3, pol)

def aap_to_bp(ant1, ant2, pol):
    """Create a basepol from antenna numbers and a CASA polarization code."""
    if ant1 < 0:
        raise ValueError('first antenna is below 0: %s' % ant1)
    if ant2 < ant1:
        raise ValueError('second antenna is below first: %s' % ant2)
    if pol < 1 or pol > 12:
        raise ValueError('illegal polarization code %s' % pol)
    fps = _pol_to_fpol[pol]
    ap1 = (ant1 << 3) + (fps >> 4 & 7)
    ap2 = (ant2 << 3) + (fps & 7)
    return (ap1, ap2)

def multiprocessing_ppmap_worker(in_queue, out_queue, func, fixed_arg):
    """Worker for the :mod:`multiprocessing` ppmap implementation. Strongly
    derived from code posted on StackExchange by "klaus se":
    `<http://stackoverflow.com/a/16071616/3760486>`_."""
    while True:
        i, var_arg = in_queue.get()
        if i is None:
            break
        out_queue.put((i, func(i, fixed_arg, var_arg)))

def calc_freefree_kappa(ne, t, hz):
    """Dulk (1985) eq 20, assuming pure hydrogen."""
    return 0.00978 * ne ** 2 * hz ** (-2) * t ** (-1.5) * (24.5 + np.log(t) - np.log(hz))

def listobs(vis):
    """Textually describe the contents of a measurement set.

    vis (str)
      The path to the dataset.
    Returns
      A generator of lines of human-readable output

    Errors can only be detected by looking at the output. Example::

      from pwkit.environments.casa import tasks

      for line in tasks.listobs('mydataset.ms'):
        print(line)"""
    def inner_list(sink):
        try:
            ms = util.tools.ms()
            ms.open(vis)
            ms.summary(verbose=True)
            ms.close()
        except Exception as e:
            sink.post(b'listobs failed: %s' % e, priority=b'SEVERE')
    for line in util.forkandlog(inner_list):
        info = line.rstrip().split('\t', 3)
        if len(info) > 3:
            yield info[3]
        else:
            yield ''

def latexify(obj, **kwargs):
    """Render an object in LaTeX appropriately.

    """
    if hasattr(obj, '__pk_latex__'):
        return obj.__pk_latex__(**kwargs)
    if isinstance(obj, text_type):
        from .unicode_to_latex import unicode_to_latex
        return unicode_to_latex(obj)
    if isinstance(obj, bool):
        raise ValueError('no well-defined LaTeXification of bool %r' % obj)
    if isinstance(obj, float):
        nplaces = kwargs.get('nplaces')
        if nplaces is None:
            return '$%f$' % obj
        return '$%.*f$' % (nplaces, obj)
    if isinstance(obj, int):
        return '$%d$' % obj
    if isinstance(obj, binary_type):
        if all((c in _printable_ascii for c in obj)):
            return obj.decode('ascii')
        raise ValueError('no safe LaTeXification of binary string %r' % obj)
    raise ValueError("can't LaTeXify %r" % obj)

def latexify_n2col(x, nplaces=None, **kwargs):
    """Render a number into LaTeX in a 2-column format, where the columns split
    immediately to the left of the decimal point. This gives nice alignment of
    numbers in a table."""
    if nplaces is not None:
        t = '%.*f' % (nplaces, x)
    else:
        t = '%f' % x
    if '.' not in t:
        return '$%s$ &' % t
    left, right = t.split('.')
    return '$%s$ & $.%s$' % (left, right)

def latexify_l3col(obj, **kwargs):
    """Convert an object to special LaTeX for limit tables.

    This conversion is meant for limit values in a table. The return value
    should span three columns. The first column is the limit indicator: <, >,
    ~, etc. The second column is the whole part of the value, up until just
    before the decimal point. The third column is the decimal point and the
    fractional part of the value, if present. If the item being formatted does
    not fit this schema, it can be wrapped in something like
    '\\multicolumn{3}{c}{...}'."""
    if hasattr(obj, '__pk_latex_l3col__'):
        return obj.__pk_latex_l3col__(**kwargs)
    if isinstance(obj, bool):
        raise ValueError('no well-defined l3col LaTeXification of bool %r' % obj)
    if isinstance(obj, float):
        return '&' + latexify_n2col(obj, **kwargs)
    if isinstance(obj, int):
        return '& $%d$ &' % obj
    raise ValueError("can't LaTeXify %r in 3-column limit format" % obj)

def _broadcast_shapes(s1, s2):
    """Given array shapes `s1` and `s2`, compute the shape of the array that would
    result from broadcasting them together."""
    n1 = len(s1)
    n2 = len(s2)
    n = max(n1, n2)
    res = [1] * n
    for i in range(n):
        if i >= n1:
            c1 = 1
        else:
            c1 = s1[n1 - 1 - i]
        if i >= n2:
            c2 = 1
        else:
            c2 = s2[n2 - 1 - i]
        if c1 == 1:
            rc = c2
        elif c2 == 1 or c1 == c2:
            rc = c1
        else:
            raise ValueError('array shapes %r and %r are not compatible' % (s1, s2))
        res[n - 1 - i] = rc
    return tuple(res)

def basic(args=None):
    """Parse the string list *args* as a set of keyword arguments in a very
    simple-minded way, splitting on equals signs. Returns a
    :class:`pwkit.Holder` instance with attributes set to strings. The form
    ``+foo`` is mapped to setting ``foo = True`` on the :class:`pwkit.Holder`
    instance. If *args* is ``None``, ``sys.argv[1:]`` is used. Raises
    :exc:`KwargvError` on invalid arguments (i.e., ones without an equals sign
    or a leading plus sign)."""
    if args is None:
        import sys
        args = sys.argv[1:]
    parsed = Holder()
    for arg in args:
        if arg[0] == '+':
            for kw in arg[1:].split(','):
                parsed.set_one(kw, True)
        else:
            t = arg.split('=', 1)
            if len(t) < 2:
                raise KwargvError('don\'t know what to do with argument "%s"', arg)
            if not len(t[1]):
                raise KwargvError('empty value for keyword argument "%s"', t[0])
            parsed.set_one(t[0], t[1])
    return parsed

def find_common_dtype(*args):
    """Returns common dtype of numpy and scipy objects.

    Recognizes ndarray, spmatrix and LinearOperator. All other objects are
    ignored (most notably None)."""
    dtypes = []
    for arg in args:
        if type(arg) is numpy.ndarray or isspmatrix(arg) or isinstance(arg, LinearOperator):
            if hasattr(arg, 'dtype'):
                dtypes.append(arg.dtype)
            else:
                warnings.warn('object %s does not have a dtype.' % arg.__repr__)
    return numpy.find_common_type(dtypes, [])

def shape_vecs(*args):
    """Reshape all ndarrays with ``shape==(n,)`` to ``shape==(n,1)``.

    Recognizes ndarrays and ignores all others."""
    ret_args = []
    flat_vecs = True
    for arg in args:
        if type(arg) is numpy.ndarray:
            if len(arg.shape) == 1:
                arg = shape_vec(arg)
            else:
                flat_vecs = False
        ret_args.append(arg)
    return (flat_vecs, ret_args)

def inner(X, Y, ip_B=None):
    """Euclidean and non-Euclidean inner product.

    numpy.vdot only works for vectors and numpy.dot does not use the conjugate
    transpose.

    :param X: numpy array with ``shape==(N,m)``
    :param Y: numpy array with ``shape==(N,n)``
    :param ip_B: (optional) May be one of the following

        * ``None``: Euclidean inner product.
        * a self-adjoint and positive definite operator :math:`B` (as
          ``numpy.array`` or ``LinearOperator``). Then :math:`X^*B Y` is
          returned.
        * a callable which takes 2 arguments X and Y and returns
          :math:`\\langle X,Y\\rangle`.

    **Caution:** a callable should only be used if necessary. The choice
    potentially has an impact on the round-off behavior, e.g. of projections.

    :return: numpy array :math:`\\langle X,Y\\rangle` with ``shape==(m,n)``."""
    if ip_B is None or isinstance(ip_B, IdentityLinearOperator):
        return numpy.dot(X.T.conj(), Y)
    N, m = X.shape
    _, n = Y.shape
    try:
        B = get_linearoperator((N, N), ip_B)
    except TypeError:
        return ip_B(X, Y)
    if m > n:
        return numpy.dot((B * X).T.conj(), Y)
    else:
        return numpy.dot(X.T.conj(), B * Y)

def norm_squared(x, Mx=None, inner_product=ip_euclid):
    """Compute the norm^2 w.r.t. to a given scalar product."""
    assert len(x.shape) == 2
    if Mx is None:
        rho = inner_product(x, x)
    else:
        assert len(Mx.shape) == 2
        rho = inner_product(x, Mx)
    if rho.shape == (1, 1):
        if abs(rho[0, 0].imag) > abs(rho[0, 0]) * 1e-10 or rho[0, 0].real < 0.0:
            raise InnerProductError('<x,Mx> = %g. Is the inner product indefinite?' % rho[0, 0])
    return numpy.linalg.norm(rho, 2)

def norm(x, y=None, ip_B=None):
    """Compute norm (Euclidean and non-Euclidean).

    :param x: a 2-dimensional ``numpy.array``.
    :param y: a 2-dimensional ``numpy.array``.
    :param ip_B: see :py:meth:`inner`.

    Compute :math:`\\sqrt{\\langle x,y\\rangle}` where the inner product is
    defined via ``ip_B``."""
    if y is None and (ip_B is None or isinstance(ip_B, IdentityLinearOperator)):
        return numpy.linalg.norm(x, 2)
    if y is None:
        y = x
    ip = inner(x, y, ip_B=ip_B)
    nrm_diag = numpy.linalg.norm(numpy.diag(ip), 2)
    nrm_diag_imag = numpy.linalg.norm(numpy.imag(numpy.diag(ip)), 2)
    if nrm_diag_imag > nrm_diag * 1e-10:
        raise InnerProductError('inner product defined by ip_B not positive definite? ||diag(ip).imag||/||diag(ip)||={0}'.format(nrm_diag_imag / nrm_diag))
    return numpy.sqrt(numpy.linalg.norm(ip, 2))

def get_linearoperator(shape, A, timer=None):
    """Enhances aslinearoperator if A is None."""
    ret = None
    import scipy.sparse.linalg as scipylinalg
    if isinstance(A, LinearOperator):
        ret = A
    elif A is None:
        ret = IdentityLinearOperator(shape)
    elif isinstance(A, numpy.ndarray) or isspmatrix(A):
        ret = MatrixLinearOperator(A)
    elif isinstance(A, numpy.matrix):
        ret = MatrixLinearOperator(numpy.atleast_2d(numpy.asarray(A)))
    elif isinstance(A, scipylinalg.LinearOperator):
        if not hasattr(A, 'dtype'):
            raise ArgumentError('scipy LinearOperator has no dtype.')
        ret = LinearOperator(A.shape, dot=A.matvec, dot_adj=A.rmatvec, dtype=A.dtype)
    else:
        raise TypeError('type not understood')
    if A is not None and (not isinstance(A, IdentityLinearOperator)) and (timer is not None):
        ret = TimedLinearOperator(ret, timer)
    if shape != ret.shape:
        raise LinearOperatorError('shape mismatch')
    return ret

def orthonormality(V, ip_B=None):
    """Measure orthonormality of given basis.

    :param V: a matrix :math:`V=[v_1,\\ldots,v_n]` with ``shape==(N,n)``.
    :param ip_B: (optional) the inner product to use, see :py:meth:`inner`.

    :return: :math:`\\| I_n - \\langle V,V \\rangle \\|_2`."""
    return norm(numpy.eye(V.shape[1]) - inner(V, V, ip_B=ip_B))

def qr(X, ip_B=None, reorthos=1):
    """QR factorization with customizable inner product.

    :param X: array with ``shape==(N,k)``
    :param ip_B: (optional) inner product, see :py:meth:`inner`.
    :param reorthos: (optional) numer of reorthogonalizations. Defaults to
      1 (i.e. 2 runs of modified Gram-Schmidt) which should be enough in most
      cases (TODO: add reference).

    :return: Q, R where :math:`X=QR` with :math:`\\langle Q,Q \\rangle=I_k` and
      R upper triangular."""
    if ip_B is None and X.shape[1] > 0:
        return scipy.linalg.qr(X, mode='economic')
    else:
        N, k = X.shape
        Q = X.copy()
        R = numpy.zeros((k, k), dtype=X.dtype)
        for i in range(k):
            for reortho in range(reorthos + 1):
                for j in range(i):
                    alpha = inner(Q[:, [j]], Q[:, [i]], ip_B=ip_B)[0, 0]
                    R[j, i] += alpha
                    Q[:, [i]] -= alpha * Q[:, [j]]
            R[i, i] = norm(Q[:, [i]], ip_B=ip_B)
            if R[i, i] >= 1e-15:
                Q[:, [i]] /= R[i, i]
        return (Q, R)

def get_residual_norms(H, self_adjoint=False):
    """Compute relative residual norms from Hessenberg matrix.

    It is assumed that the initial guess is chosen as zero."""
    H = H.copy()
    n_, n = H.shape
    y = numpy.eye(n_, 1, dtype=H.dtype)
    resnorms = [1.0]
    for i in range(n_ - 1):
        G = Givens(H[i:i + 2, [i]])
        if self_adjoint:
            H[i:i + 2, i:i + 3] = G.apply(H[i:i + 2, i:i + 3])
        else:
            H[i:i + 2, i:] = G.apply(H[i:i + 2, i:])
        y[i:i + 2] = G.apply(y[i:i + 2])
        resnorms.append(numpy.abs(y[i + 1, 0]))
    if n_ == n:
        resnorms.append(0.0)
    return numpy.array(resnorms)

def compute_hash(func, string):
    """compute hash of string using given hash function"""
    h = func()
    h.update(string)
    return h.hexdigest()

