def validate_gps(value):
    """Validate GPS value."""
    try:
        latitude, longitude, altitude = value.split(',')
        vol.Coerce(float)(latitude)
        vol.Coerce(float)(longitude)
        vol.Coerce(float)(altitude)
    except (TypeError, ValueError, vol.Invalid):
        raise vol.Invalid('GPS value should be of format "latitude,longitude,altitude"')
    return value

def validate_hex(value):
    """Validate that value has hex format."""
    try:
        binascii.unhexlify(value)
    except Exception:
        raise vol.Invalid('{} is not of hex format'.format(value))
    return value

def validate_v_rgb(value):
    """Validate a V_RGB value."""
    if len(value) != 6:
        raise vol.Invalid('{} is not six characters long'.format(value))
    return validate_hex(value)

def validate_v_rgbw(value):
    """Validate a V_RGBW value."""
    if len(value) != 8:
        raise vol.Invalid('{} is not eight characters long'.format(value))
    return validate_hex(value)

def get_const(protocol_version):
    """Return the const module for the protocol_version."""
    path = next((CONST_VERSIONS[const_version] for const_version in sorted(CONST_VERSIONS, reverse=True) if parse_ver(protocol_version) >= parse_ver(const_version)), 'mysensors.const_14')
    if path in LOADED_CONST:
        return LOADED_CONST[path]
    const = import_module(path)
    LOADED_CONST[path] = const
    return const

def fw_hex_to_int(hex_str, words):
    """Unpack hex string into integers.

    Use little-endian and unsigned int format. Specify number of words to
    unpack with argument words."""
    return struct.unpack('<{}H'.format(words), binascii.unhexlify(hex_str))

def fw_int_to_hex(*args):
    """Pack integers into hex string.

    Use little-endian and unsigned int format."""
    return binascii.hexlify(struct.pack('<{}H'.format(len(args)), *args)).decode('utf-8')

def compute_crc(data):
    """Compute CRC16 of data and return an int."""
    crc16 = crcmod.predefined.Crc('modbus')
    crc16.update(data)
    return int(crc16.hexdigest(), 16)

def load_fw(path):
    """Open firmware file and return a binary string."""
    fname = os.path.realpath(path)
    exists = os.path.isfile(fname)
    if not exists or not os.access(fname, os.R_OK):
        _LOGGER.error('Firmware path %s does not exist or is not readable', path)
        return None
    try:
        intel_hex = IntelHex()
        with open(path, 'r') as file_handle:
            intel_hex.fromfile(file_handle, format='hex')
        return intel_hex.tobinstr()
    except (IntelHexError, TypeError, ValueError) as exc:
        _LOGGER.error('Firmware not valid, check the hex file at %s: %s', path, exc)
        return None

def prepare_fw(bin_string):
    """Check that firmware is valid and return dict with binary data."""
    pads = len(bin_string) % 128
    for _ in range(128 - pads):
        bin_string += b'\xff'
    fware = {'blocks': int(len(bin_string) / FIRMWARE_BLOCK_SIZE), 'crc': compute_crc(bin_string), 'data': bin_string}
    return fware

def handle_smartsleep(msg):
    """Process a message before going back to smartsleep."""
    while msg.gateway.sensors[msg.node_id].queue:
        msg.gateway.add_job(str, msg.gateway.sensors[msg.node_id].queue.popleft())
    for child in msg.gateway.sensors[msg.node_id].children.values():
        new_child = msg.gateway.sensors[msg.node_id].new_state.get(child.id, ChildSensor(child.id, child.type, child.description))
        msg.gateway.sensors[msg.node_id].new_state[child.id] = new_child
        for value_type, value in child.values.items():
            new_value = new_child.values.get(value_type)
            if new_value is not None and new_value != value:
                msg.gateway.add_job(msg.gateway.sensors[msg.node_id].set_child_value, child.id, value_type, new_value)

def handle_set(msg):
    """Process a set message."""
    if not msg.gateway.is_sensor(msg.node_id, msg.child_id):
        return None
    msg.gateway.sensors[msg.node_id].set_child_value(msg.child_id, msg.sub_type, msg.payload)
    if msg.gateway.sensors[msg.node_id].new_state:
        msg.gateway.sensors[msg.node_id].set_child_value(msg.child_id, msg.sub_type, msg.payload, children=msg.gateway.sensors[msg.node_id].new_state)
    msg.gateway.alert(msg)
    if msg.gateway.sensors[msg.node_id].reboot:
        return msg.copy(child_id=SYSTEM_CHILD_ID, type=msg.gateway.const.MessageType.internal, ack=0, sub_type=msg.gateway.const.Internal.I_REBOOT, payload='')
    return None

def handle_req(msg):
    """Process a req message.

    This will return the value if it exists. If no value exists,
    nothing is returned."""
    if not msg.gateway.is_sensor(msg.node_id, msg.child_id):
        return None
    value = msg.gateway.sensors[msg.node_id].children[msg.child_id].values.get(msg.sub_type)
    if value is not None:
        return msg.copy(type=msg.gateway.const.MessageType.set, payload=value)
    return None

def handle_internal(msg):
    """Process an internal message."""
    internal = msg.gateway.const.Internal(msg.sub_type)
    handler = internal.get_handler(msg.gateway.handlers)
    if handler is None:
        return None
    return handler(msg)

def handle_stream(msg):
    """Process a stream type message."""
    if not msg.gateway.is_sensor(msg.node_id):
        return None
    stream = msg.gateway.const.Stream(msg.sub_type)
    handler = stream.get_handler(msg.gateway.handlers)
    if handler is None:
        return None
    return handler(msg)

def handle_time(msg):
    """Process an internal time request message."""
    return msg.copy(ack=0, payload=calendar.timegm(time.localtime()))

def handle_gateway_ready_20(msg):
    """Process an internal gateway ready message."""
    _LOGGER.info('n:%s c:%s t:%s s:%s p:%s', msg.node_id, msg.child_id, msg.type, msg.sub_type, msg.payload)
    msg.gateway.alert(msg)
    return msg.copy(node_id=255, ack=0, sub_type=msg.gateway.const.Internal.I_DISCOVER, payload='')

