def authenticated(function):
    """Re-authenticate if session expired."""
    def wrapped(*args):
        """Wrap function."""
        try:
            return function(*args)
        except USPSError:
            _LOGGER.info('attempted to access page before login')
            _login(args[0])
            return function(*args)
    return wrapped

def get_profile(session):
    """Get profile data."""
    response = session.get(PROFILE_URL, allow_redirects=False)
    if response.status_code == 302:
        raise USPSError('expired session')
    parsed = BeautifulSoup(response.text, HTML_PARSER)
    profile = parsed.find('div', {'class': 'atg_store_myProfileInfo'})
    data = {}
    for row in profile.find_all('tr'):
        cells = row.find_all('td')
        if len(cells) == 2:
            key = ' '.join(cells[0].find_all(text=True)).strip().lower().replace(' ', '_')
            value = ' '.join(cells[1].find_all(text=True)).strip()
            data[key] = value
    return data

def rc4(data, key):
    """RC4 encryption and decryption method."""
    S, j, out = (list(range(256)), 0, [])
    for i in range(256):
        j = (j + S[i] + ord(key[i % len(key)])) % 256
        S[i], S[j] = (S[j], S[i])
    i = j = 0
    for ch in data:
        i = (i + 1) % 256
        j = (j + S[i]) % 256
        S[i], S[j] = (S[j], S[i])
        out.append(chr(ord(ch) ^ S[(S[i] + S[j]) % 256]))
    return ''.join(out)

def setup_domain_socket(location):
    """Setup Domain Socket

    Setup a connection to a Unix Domain Socket

    --
    @param  location:str    The path to the Unix Domain Socket to connect to.
    @return <class 'socket._socketobject'>"""
    clientsocket = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    clientsocket.settimeout(timeout)
    clientsocket.connect(location)
    return clientsocket

def setup_tcp_socket(location, port):
    """Setup TCP Socket

    Setup a connection to a TCP Socket

    --
    @param  location:str    The Hostname / IP Address of the remote TCP Socket.
    @param  port:int        The TCP Port the remote Socket is listening on.
    @return <class 'socket._socketobject'>"""
    clientsocket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    clientsocket.settimeout(timeout)
    clientsocket.connect((location, port))
    return clientsocket

def dumpf(obj, path, encoding=None):
    """Serialize obj to path in ARPA format (.arpa, .gz)."""
    path = str(path)
    if path.endswith('.gz'):
        with gzip.open(path, mode='wt', encoding=encoding) as f:
            return dump(obj, f)
    else:
        with open(path, mode='wt', encoding=encoding) as f:
            dump(obj, f)

def load(fp, model=None, parser=None):
    """Deserialize fp (a file-like object) to a Python object."""
    if not model:
        model = 'simple'
    if not parser:
        parser = 'quick'
    if model not in ['simple']:
        raise ValueError
    if parser not in ['quick']:
        raise ValueError
    if model == 'simple' and parser == 'quick':
        return ARPAParserQuick(ARPAModelSimple).parse(fp)
    else:
        raise ValueError

def loadf(path, encoding=None, model=None, parser=None):
    """Deserialize path (.arpa, .gz) to a Python object."""
    path = str(path)
    if path.endswith('.gz'):
        with gzip.open(path, mode='rt', encoding=encoding) as f:
            return load(f, model=model, parser=parser)
    else:
        with open(path, mode='rt', encoding=encoding) as f:
            return load(f, model=model, parser=parser)

def loads(s, model=None, parser=None):
    """Deserialize s (a str) to a Python object."""
    with StringIO(s) as f:
        return load(f, model=model, parser=parser)

def factor_coeff(cls, ops, kwargs):
    """Factor out coefficients of all factors."""
    coeffs, nops = zip(*map(_coeff_term, ops))
    coeff = 1
    for c in coeffs:
        coeff *= c
    if coeff == 1:
        return (nops, coeffs)
    else:
        return coeff * cls.create(*nops, **kwargs)

def _attrprint(d, delimiter=', '):
    """Print a dictionary of attributes in the DOT format"""
    return delimiter.join(('"%s"="%s"' % item for item in sorted(d.items())))

def _styleof(expr, styles):
    """Merge style dictionaries in order"""
    style = dict()
    for expr_filter, sty in styles:
        if expr_filter(expr):
            style.update(sty)
    return style

def expr_labelfunc(leaf_renderer=str, fallback=str):
    """Factory for function ``labelfunc(expr, is_leaf)``

    It has the following behavior:

    * If ``is_leaf`` is True, return ``leaf_renderer(expr)``.

    * Otherwise,

      - if `expr` is an Expression, return a custom string similar to
        :func:`~qnet.printing.srepr`, but with an ellipsis for ``args``
      - otherwise, return ``fallback(expr)``"""
    def _labelfunc(expr, is_leaf):
        if is_leaf:
            label = leaf_renderer(expr)
        elif isinstance(expr, Expression):
            if len(expr.kwargs) == 0:
                label = expr.__class__.__name__
            else:
                label = '%s(..., %s)' % (expr.__class__.__name__, ', '.join(['%s=%s' % (key, val) for key, val in expr.kwargs.items()]))
        else:
            label = fallback(expr)
        return label
    return _labelfunc

def _git_version():
    """If installed with 'pip installe -e .' from inside a git repo, the
    current git revision as a string"""
    import subprocess
    import os
    def _minimal_ext_cmd(cmd):
        env = {}
        for k in ['SYSTEMROOT', 'PATH']:
            v = os.environ.get(k)
            if v is not None:
                env[k] = v
        env['LANGUAGE'] = 'C'
        env['LANG'] = 'C'
        env['LC_ALL'] = 'C'
        FNULL = open(os.devnull, 'w')
        cwd = os.path.dirname(os.path.realpath(__file__))
        proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=FNULL, env=env, cwd=cwd)
        out = proc.communicate()[0]
        return out
    try:
        out = _minimal_ext_cmd(['git', 'rev-parse', 'HEAD'])
        return out.strip().decode('ascii')
    except OSError:
        return 'unknown'

def FB(circuit, *, out_port=None, in_port=None):
    """Wrapper for :class:`.Feedback`, defaulting to last channel

    Args:
        circuit (Circuit): The circuit that undergoes self-feedback
        out_port (int): The output port index, default = None --> last port
        in_port (int): The input port index, default = None --> last port

    Returns:
        Circuit: The circuit with applied feedback operation."""
    if out_port is None:
        out_port = circuit.cdim - 1
    if in_port is None:
        in_port = circuit.cdim - 1
    return Feedback.create(circuit, out_port=out_port, in_port=in_port)

def map_channels(mapping, cdim):
    """Create a :class:`CPermuation` based on a dict of channel mappings

    For a given mapping in form of a dictionary, generate the channel
    permutating circuit that achieves the specified mapping while leaving the
    relative order of all non-specified channels intact.

    Args:
        mapping (dict): Input-output mapping of indices (zero-based)
            ``{in1:out1, in2:out2,...}``
        cdim (int): The circuit dimension (number of channels)

    Returns:
        CPermutation: Circuit mapping the channels as specified"""
    n = cdim
    free_values = list(range(n))
    for v in mapping.values():
        if v >= n:
            raise ValueError('the mapping cannot take on values larger than cdim - 1')
        free_values.remove(v)
    for k in mapping:
        if k >= n:
            raise ValueError('the mapping cannot map keys larger than cdim - 1')
    permutation = []
    for k in range(n):
        if k in mapping:
            permutation.append(mapping[k])
        else:
            permutation.append(free_values.pop(0))
    return CPermutation.create(tuple(permutation))

def _unicode_sub_super(string, mapping, max_len=None):
    """Try to render a subscript or superscript string in unicode, fall back on
    ascii if this is not possible"""
    string = str(string)
    if string.startswith('(') and string.endswith(')'):
        len_string = len(string) - 2
    else:
        len_string = len(string)
    if max_len is not None:
        if len_string > max_len:
            raise KeyError('max_len exceeded')
    unicode_letters = []
    for letter in string:
        unicode_letters.append(mapping[letter])
    return ''.join(unicode_letters)

def _translate_symbols(string):
    """Given a description of a Greek letter or other special character,
    return the appropriate unicode letter."""
    res = []
    string = str(string)
    for s in re.split('(\\W+)', string, flags=re.UNICODE):
        tex_str = _GREEK_DICTIONARY.get(s)
        if tex_str:
            res.append(tex_str)
        elif s.lower() in _GREEK_DICTIONARY:
            res.append(_GREEK_DICTIONARY[s])
        else:
            res.append(s)
    return ''.join(res)

def _translate_symbols(string):
    """Given a description of a Greek letter or other special character,
    return the appropriate latex."""
    res = []
    for s in re.split('([,.:\\s=]+)', string):
        tex_str = _TEX_GREEK_DICTIONARY.get(s)
        if tex_str:
            res.append(tex_str)
        elif s.lower() in greek_letters_set:
            res.append('\\' + s.lower())
        elif s in other_symbols:
            res.append('\\' + s)
        elif re.match('^[a-zA-Z]{4,}$', s):
            res.append('\\text{' + s + '}')
        else:
            res.append(s)
    return ''.join(res)

def is_symbol(string):
    """Return true if the string is a mathematical symbol."""
    return is_int(string) or is_float(string) or is_constant(string) or is_unary(string) or is_binary(string) or (string == '(') or (string == ')')

def to_postfix(tokens):
    """Convert a list of evaluatable tokens to postfix format."""
    precedence = {'/': 4, '*': 4, '+': 3, '-': 3, '^': 2, '(': 1}
    postfix = []
    opstack = []
    for token in tokens:
        if is_int(token):
            postfix.append(int(token))
        elif is_float(token):
            postfix.append(float(token))
        elif token in mathwords.CONSTANTS:
            postfix.append(mathwords.CONSTANTS[token])
        elif is_unary(token):
            opstack.append(token)
        elif token == '(':
            opstack.append(token)
        elif token == ')':
            top_token = opstack.pop()
            while top_token != '(':
                postfix.append(top_token)
                top_token = opstack.pop()
        else:
            while opstack != [] and precedence[opstack[-1]] >= precedence[token]:
                postfix.append(opstack.pop())
            opstack.append(token)
    while opstack != []:
        postfix.append(opstack.pop())
    return postfix

def evaluate_postfix(tokens):
    """Given a list of evaluatable tokens in postfix format,
    calculate a solution."""
    stack = []
    for token in tokens:
        total = None
        if is_int(token) or is_float(token) or is_constant(token):
            stack.append(token)
        elif is_unary(token):
            a = stack.pop()
            total = mathwords.UNARY_FUNCTIONS[token](a)
        elif len(stack):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                total = a + b
            elif token == '-':
                total = a - b
            elif token == '*':
                total = a * b
            elif token == '^':
                total = a ** b
            elif token == '/':
                if Decimal(str(b)) == 0:
                    total = 'undefined'
                else:
                    total = Decimal(str(a)) / Decimal(str(b))
            else:
                raise PostfixTokenEvaluationException('Unknown token {}'.format(token))
        if total is not None:
            stack.append(total)
    if not stack:
        raise PostfixTokenEvaluationException('The postfix expression resulted in an empty stack')
    return stack.pop()

def parse(string, language=None):
    """Return a solution to the equation in the input string."""
    if language:
        string = replace_word_tokens(string, language)
    tokens = tokenize(string)
    postfix = to_postfix(tokens)
    return evaluate_postfix(postfix)

def extract_expression(dirty_string, language):
    '''Give a string such as: "What is 4 + 4?"
    Return the string "4 + 4"'''
    tokens = tokenize(dirty_string, language)
    start_index = 0
    end_index = len(tokens)
    for part in tokens:
        if is_symbol(part) or is_word(part, language):
            break
        else:
            start_index += 1
    for part in reversed(tokens):
        if is_symbol(part) or is_word(part, language):
            break
        else:
            end_index -= 1
    return ' '.join(tokens[start_index:end_index])

def expr_order_key(expr):
    """A default order key for arbitrary expressions"""
    if hasattr(expr, '_order_key'):
        return expr._order_key
    try:
        if isinstance(expr.kwargs, OrderedDict):
            key_vals = expr.kwargs.values()
        else:
            key_vals = [expr.kwargs[key] for key in sorted(expr.kwargs)]
        return KeyTuple((expr.__class__.__name__,) + tuple(map(expr_order_key, expr.args)) + tuple(map(expr_order_key, key_vals)))
    except AttributeError:
        return str(expr)

def _series_expand_combine_prod(c1, c2, order):
    """Given the result of the ``c1._series_expand(...)`` and
    ``c2._series_expand(...)``, construct the result of
    ``(c1*c2)._series_expand(...)``"""
    from qnet.algebra.core.scalar_algebra import Zero
    res = []
    c1 = list(c1)
    c2 = list(c2)
    for n in range(order + 1):
        summands = []
        for k in range(n + 1):
            if c1[k].is_zero or c2[n - k].is_zero:
                summands.append(Zero)
            else:
                summands.append(c1[k] * c2[n - k])
        sum = summands[0]
        for summand in summands[1:]:
            if summand != 0:
                sum += summand
        res.append(sum)
    return tuple(res)

def Jzjmcoeff(ls, m, shift) -> sympy.Expr:
    """Eigenvalue of the $\\Op{J}_z$ (:class:`Jz`) operator

    .. math::

        \\Op{J}_{z} \\ket{s, m} = m \\ket{s, m}

    See also :func:`Jpjmcoeff`."""
    assert isinstance(ls, SpinSpace)
    n = ls.dimension
    s = sympify(n - 1) / 2
    assert n == int(2 * s + 1)
    if isinstance(m, str):
        return ls.basis.index(m) - s
    elif isinstance(m, int):
        if shift:
            assert 0 <= m < n
            return m - s
    else:
        return sympify(m)

def try_import(objname):
    """Import a object or module using *name* and *currentmodule*.
    *name* should be a relative name from *currentmodule* or
    a fully-qualified name.

    Returns imported object or module.  If failed, returns None value."""
    try:
        __import__(objname)
        return sys.modules.get(objname)
    except (ImportError, ValueError):
        matched = module_sig_re.match(objname)
        if not matched:
            return None
        modname, attrname = matched.groups()
        if modname is None:
            return None
        try:
            __import__(modname)
            return getattr(sys.modules.get(modname), attrname, None)
        except (ImportError, ValueError):
            return None

def import_classes(name, currmodule):
    """Import a class using its fully-qualified *name*."""
    target = None
    if currmodule:
        target = try_import(currmodule + '.' + name)
    if target is None:
        target = try_import(name)
    if target is None:
        raise InheritanceException('Could not import class or module %r specified for inheritance diagram' % name)
    if inspect.isclass(target):
        return [target]
    elif inspect.ismodule(target):
        classes = []
        for cls in target.__dict__.values():
            if inspect.isclass(cls) and cls_is_in_module(cls, mod=target):
                classes.append(cls)
        return classes
    raise InheritanceException('%r specified for inheritance diagram is not a class or module' % name)

def html_visit_inheritance_diagram(self, node):
    """Output the graph for HTML.  This will insert a PNG with clickable
    image map."""
    graph = node['graph']
    graph_hash = get_graph_hash(node)
    name = 'inheritance%s' % graph_hash
    graphviz_output_format = self.builder.env.config.graphviz_output_format.upper()
    current_filename = self.builder.current_docname + self.builder.out_suffix
    urls = {}
    for child in node:
        if child.get('refuri') is not None:
            if graphviz_output_format == 'SVG':
                urls[child['reftitle']] = os.path.join('..', child.get('refuri'))
            else:
                urls[child['reftitle']] = child.get('refuri')
        elif child.get('refid') is not None:
            if graphviz_output_format == 'SVG':
                urls[child['reftitle']] = os.path.join('..', current_filename + '#' + child.get('refid'))
            else:
                urls[child['reftitle']] = '#' + child.get('refid')
    dotcode = graph.generate_dot(name, urls, env=self.builder.env)
    render_dot_html(self, node, dotcode, {}, 'inheritance', 'inheritance', alt='Inheritance diagram of ' + node['content'], link_to_svg='<i class="fa fa-external-link" aria-hidden="true"></i> SVG')
    raise nodes.SkipNode

def temporary_instance_cache(*classes):
    """Use a temporary cache for instances in :meth:`~.Expression.create`

    The instance cache used by :meth:`~.Expression.create` for any of the given
    `classes` will be cleared upon entering the managed context, and restored
    on leaving it.  That is, no cached instances from outside of the managed
    context will be used within the managed context, and vice versa"""
    orig_instances = []
    for cls in classes:
        orig_instances.append(cls._instances)
        cls._instances = {}
    try:
        yield
    finally:
        for i, cls in enumerate(classes):
            cls._instances = orig_instances[i]

def _curve(x1, y1, x2, y2, hunit=HUNIT, vunit=VUNIT):
    """Return a PyX curved path from (x1, y1) to (x2, y2),
    such that the slope at either end is zero."""
    ax1, ax2, axm = (x1 * hunit, x2 * hunit, (x1 + x2) * hunit / 2)
    ay1, ay2 = (y1 * vunit, y2 * vunit)
    return pyx.path.curve(ax1, ay1, axm, ay1, axm, ay2, ax2, ay2)

def precedence(item):
    """Returns the precedence of a given object."""
    try:
        mro = item.__class__.__mro__
    except AttributeError:
        return PRECEDENCE['Atom']
    for i in mro:
        n = i.__name__
        if n in PRECEDENCE_FUNCTIONS:
            return PRECEDENCE_FUNCTIONS[n](item)
        elif n in PRECEDENCE_VALUES:
            return PRECEDENCE_VALUES[n]
    return PRECEDENCE['Atom']

def PauliY(local_space, states=None):
    """Pauli-type Y-operator

    .. math::

        \\hat{\\sigma}_x = \\begin{pmatrix}
            0 & -i \\\\
            i & 0
        \\end{pmatrix}

    on an arbitrary two-level system.


    See :func:`PauliX`"""
    local_space, states = _get_pauli_args(local_space, states)
    g, e = states
    return I * (-LocalSigma.create(g, e, hs=local_space) + LocalSigma.create(e, g, hs=local_space))

def PauliZ(local_space, states=None):
    """Pauli-type Z-operator

    .. math::

        \\hat{\\sigma}_x = \\begin{pmatrix}
            1 & 0 \\\\
            0 & -1
        \\end{pmatrix}

    on an arbitrary two-level system.

    See :func:`PauliX`"""
    local_space, states = _get_pauli_args(local_space, states)
    g, e = states
    return LocalProjector(g, hs=local_space) - LocalProjector(e, hs=local_space)

def get_version(filename):
    """Extract the package version"""
    with open(filename) as in_fh:
        for line in in_fh:
            if line.startswith('__version__'):
                return line.split('=')[1].strip()[1:-1]
    raise ValueError('Cannot extract version from %s' % filename)

def blogurl(parser, token):
    """Compatibility tag to allow django-fluent-blogs to operate stand-alone.
    Either the app can be hooked in the URLconf directly, or it can be added as a pagetype of django-fluent-pages.
    For the former, URL resolving works via the normal '{% url "viewname" arg1 arg2 %}' syntax.
    For the latter, the URL resolving works via '{% appurl "viewname" arg1 arg2 %}' syntax."""
    if HAS_APP_URLS:
        from fluent_pages.templatetags.appurl_tags import appurl
        return appurl(parser, token)
    else:
        from django.template.defaulttags import url
        return url(parser, token)

def format_year(year):
    """Format the year value of the ``YearArchiveView``,
    which can be a integer or date object.

    This tag is no longer needed, but exists for template compatibility.
    It was a compatibility tag for Django 1.4."""
    if isinstance(year, (date, datetime)):
        return unicode(year.year)
    else:
        return unicode(year)

