    This is a compatibility function to allow django-fluent-blogs to operate stand-alone.
    Either the app can be hooked in the URLconf directly, or it can be added as a pagetype of *django-fluent-pages*."""
    return mixed_reverse(viewname, args=args, kwargs=kwargs, current_app=current_app, **page_kwargs)

def assoc_indexed(cls, ops, kwargs):
    """Flatten nested indexed structures while pulling out possible prefactors

    For example, for an :class:`.IndexedSum`:

    .. math::

        \\sum_j \\left( a \\sum_i \\dots \\right) = a \\sum_{j, i} \\dots"""
    from qnet.algebra.core.abstract_quantum_algebra import ScalarTimesQuantumExpression
    term, *ranges = ops
    if isinstance(term, cls):
        coeff = 1
    elif isinstance(term, ScalarTimesQuantumExpression):
        coeff = term.coeff
        term = term.term
        if not isinstance(term, cls):
            return (ops, kwargs)
    else:
        return (ops, kwargs)
    term = term.make_disjunct_indices(*ranges)
    combined_ranges = tuple(ranges) + term.ranges
    if coeff == 1:
        return cls.create(term.term, *combined_ranges)
    else:
        bound_symbols = set([r.index_symbol for r in combined_ranges])
        if len(coeff.free_symbols.intersection(bound_symbols)) == 0:
            return coeff * cls.create(term.term, *combined_ranges)
        else:
            return cls.create(coeff * term.term, *combined_ranges)

def filter_neutral(cls, ops, kwargs):
    """Remove occurrences of a neutral element from the argument/operand list,
    if that list has at least two elements.  To use this, one must also specify
    a neutral element, which can be anything that allows for an equality check
    with each argument.  E.g.::

        >>> class X(Operation):
        ...     _neutral_element = 1
        ...     simplifications = [filter_neutral, ]
        >>> X.create(2,1,3,1)
        X(2, 3)"""
    c_n = cls._neutral_element
    if len(ops) == 0:
        return c_n
    fops = [op for op in ops if c_n != op]
    if len(fops) > 1:
        return (fops, kwargs)
    elif len(fops) == 1:
        return fops[0]
    else:
        return ops[0]

def collect_summands(cls, ops, kwargs):
    """Collect summands that occur multiple times into a single summand

    Also filters out zero-summands.

    Example:
        >>> A, B, C = (OperatorSymbol(s, hs=0) for s in ('A', 'B', 'C'))
        >>> collect_summands(
        ...     OperatorPlus, (A, B, C, ZeroOperator, 2 * A, B, -C) , {})
        ((3 * A^(0), 2 * B^(0)), {})
        >>> collect_summands(OperatorPlus, (A, -A), {})
        ZeroOperator
        >>> collect_summands(OperatorPlus, (B, A, -B), {})
        A^(0)"""
    from qnet.algebra.core.abstract_quantum_algebra import ScalarTimesQuantumExpression
    coeff_map = OrderedDict()
    for op in ops:
        if isinstance(op, ScalarTimesQuantumExpression):
            coeff, term = (op.coeff, op.term)
        else:
            coeff, term = (1, op)
        if term in coeff_map:
            coeff_map[term] += coeff
        else:
            coeff_map[term] = coeff
    fops = []
    for term, coeff in coeff_map.items():
        op = coeff * term
        if not op.is_zero:
            fops.append(op)
    if len(fops) == 0:
        return cls._zero
    elif len(fops) == 1:
        return fops[0]
    else:
        return (tuple(fops), kwargs)

def _get_binary_replacement(first, second, cls):
    """Helper function for match_replace_binary"""
    expr = ProtoExpr([first, second], {})
    if LOG:
        logger = logging.getLogger('QNET.create')
    for key, rule in cls._binary_rules.items():
        pat, replacement = rule
        match_dict = match_pattern(pat, expr)
        if match_dict:
            try:
                replaced = replacement(**match_dict)
                if LOG:
                    logger.debug('%sRule %s.%s: (%s, %s) -> %s', '  ' * LEVEL, cls.__name__, key, expr.args, expr.kwargs, replaced)
                return replaced
            except CannotSimplify:
                if LOG_NO_MATCH:
                    logger.debug('%sRule %s.%s: no match: CannotSimplify', '  ' * LEVEL, cls.__name__, key)
                continue
        elif LOG_NO_MATCH:
            logger.debug('%sRule %s.%s: no match: %s', '  ' * LEVEL, cls.__name__, key, match_dict.reason)
    return None

def _match_replace_binary(cls, ops: list) -> list:
    """Reduce list of `ops`"""
    n = len(ops)
    if n <= 1:
        return ops
    ops_left = ops[:n // 2]
    ops_right = ops[n // 2:]
    return _match_replace_binary_combine(cls, _match_replace_binary(cls, ops_left), _match_replace_binary(cls, ops_right))

def _match_replace_binary_combine(cls, a: list, b: list) -> list:
    """combine two fully reduced lists a, b"""
    if len(a) == 0 or len(b) == 0:
        return a + b
    r = _get_binary_replacement(a[-1], b[0], cls)
    if r is None:
        return a + b
    if r == cls._neutral_element:
        return _match_replace_binary_combine(cls, a[:-1], b[1:])
    if isinstance(r, cls):
        r = list(r.args)
    else:
        r = [r]
    return _match_replace_binary_combine(cls, _match_replace_binary_combine(cls, a[:-1], r), b[1:])

def check_cdims(cls, ops, kwargs):
    """Check that all operands (`ops`) have equal channel dimension."""
    if not len({o.cdim for o in ops}) == 1:
        raise ValueError('Not all operands have the same cdim:' + str(ops))
    return (ops, kwargs)

def filter_cid(cls, ops, kwargs):
    """Remove occurrences of the :func:`.circuit_identity` ``cid(n)`` for any
    ``n``. Cf. :func:`filter_neutral`"""
    from qnet.algebra.core.circuit_algebra import CircuitZero, circuit_identity
    if len(ops) == 0:
        return CircuitZero
    fops = [op for op in ops if op != circuit_identity(op.cdim)]
    if len(fops) > 1:
        return (fops, kwargs)
    elif len(fops) == 1:
        return fops[0]
    else:
        return ops[0]

def empty_trivial(cls, ops, kwargs):
    """A ProductSpace of zero Hilbert spaces should yield the TrivialSpace"""
    from qnet.algebra.core.hilbert_space_algebra import TrivialSpace
    if len(ops) == 0:
        return TrivialSpace
    else:
        return (ops, kwargs)

def delegate_to_method(mtd):
    """Create a simplification rule that delegates the instantiation to the
    method `mtd` of the operand (if defined)"""
    def _delegate_to_method(cls, ops, kwargs):
        assert len(ops) == 1
        op, = ops
        if hasattr(op, mtd):
            return getattr(op, mtd)()
        else:
            return (ops, kwargs)
    return _delegate_to_method

def scalars_to_op(cls, ops, kwargs):
    """Convert any scalar $\\alpha$ in `ops` into an operator $\\alpha
    \\identity$"""
    from qnet.algebra.core.scalar_algebra import is_scalar
    op_ops = []
    for op in ops:
        if is_scalar(op):
            op_ops.append(op * cls._one)
        else:
            op_ops.append(op)
    return (op_ops, kwargs)

def convert_to_scalars(cls, ops, kwargs):
    """Convert any entry in `ops` that is not a :class:`.Scalar` instance into
    a :class:`.ScalarValue` instance"""
    from qnet.algebra.core.scalar_algebra import Scalar, ScalarValue
    scalar_ops = []
    for op in ops:
        if not isinstance(op, Scalar):
            scalar_ops.append(ScalarValue(op))
        else:
            scalar_ops.append(op)
    return (scalar_ops, kwargs)

def disjunct_hs_zero(cls, ops, kwargs):
    """Return ZeroOperator if all the operators in `ops` have a disjunct
    Hilbert space, or an unchanged `ops`, `kwargs` otherwise"""
    from qnet.algebra.core.hilbert_space_algebra import TrivialSpace
    from qnet.algebra.core.operator_algebra import ZeroOperator
    hilbert_spaces = []
    for op in ops:
        try:
            hs = op.space
        except AttributeError:
            hs = TrivialSpace
        for hs_prev in hilbert_spaces:
            if not hs.isdisjoint(hs_prev):
                return (ops, kwargs)
        hilbert_spaces.append(hs)
    return ZeroOperator

def commutator_order(cls, ops, kwargs):
    """Apply anti-commutative property of the commutator to apply a standard
    ordering of the commutator arguments"""
    from qnet.algebra.core.operator_algebra import Commutator
    assert len(ops) == 2
    if cls.order_key(ops[1]) < cls.order_key(ops[0]):
        return -1 * Commutator.create(ops[1], ops[0])
    else:
        return (ops, kwargs)

def accept_bras(cls, ops, kwargs):
    """Accept operands that are all bras, and turn that into to bra of the
    operation applied to all corresponding kets"""
    from qnet.algebra.core.state_algebra import Bra
    kets = []
    for bra in ops:
        if isinstance(bra, Bra):
            kets.append(bra.ket)
        else:
            return (ops, kwargs)
    return Bra.create(cls.create(*kets, **kwargs))

def basis_ket_zero_outside_hs(cls, ops, kwargs):
    """For ``BasisKet.create(ind, hs)`` with an integer label `ind`, return a
    :class:`ZeroKet` if `ind` is outside of the range of the underlying Hilbert
    space"""
    from qnet.algebra.core.state_algebra import ZeroKet
    ind, = ops
    hs = kwargs['hs']
    if isinstance(ind, int):
        if ind < 0 or (hs._dimension is not None and ind >= hs._dimension):
            return ZeroKet
    return (ops, kwargs)

def _ranges_key(r, delta_indices):
    """Sorting key for ranges.

    When used with ``reverse=True``, this can be used to sort index ranges into
    the order we would prefer to eliminate them by evaluating KroneckerDeltas:
    First, eliminate primed indices, then indices names higher in the alphabet."""
    idx = r.index_symbol
    if idx in delta_indices:
        return (r.index_symbol.primed, r.index_symbol.name)
    else:
        return (0, ' ')

def _factors_for_expand_delta(expr):
    """Yield factors from expr, mixing sympy and QNET

    Auxiliary routine for :func:`_expand_delta`."""
    from qnet.algebra.core.scalar_algebra import ScalarValue
    from qnet.algebra.core.abstract_quantum_algebra import ScalarTimesQuantumExpression
    if isinstance(expr, ScalarTimesQuantumExpression):
        yield from _factors_for_expand_delta(expr.coeff)
        yield expr.term
    elif isinstance(expr, ScalarValue):
        yield from _factors_for_expand_delta(expr.val)
    elif isinstance(expr, sympy.Basic) and expr.is_Mul:
        yield from expr.args
    else:
        yield expr

def _expand_delta(expr, idx):
    """Expand the first :class:`sympy.Add` containing a simple
    :class:`sympy.KroneckerDelta`.

    Auxiliary routine for :func:`_deltasummation`. Adapted from SymPy. The
    input `expr` may be a :class:`.QuantumExpression` or a
    `:class:`sympy.Basic` instance.

    Returns a list of summands. The elements of the list may be
    :class:`.QuantumExpression` or a `:class:`sympy.Basic` instances. There is
    no guarantee of type stability: an input :class:`.QuantumExpression` may
    result in a :class:`sympy.Basic` instance in the `summands`."""
    found_first_delta = False
    summands = None
    for factor in _factors_for_expand_delta(expr):
        need_to_expand = False
        if not found_first_delta and isinstance(factor, sympy.Basic):
            if factor.is_Add and _has_simple_delta(factor, idx):
                need_to_expand = True
        if need_to_expand:
            found_first_delta = True
            if summands is None:
                summands = list(factor.args)
            else:
                summands = [summands[0] * t for t in factor.args]
        elif summands is None:
            summands = [factor]
        else:
            summands = [t * factor for t in summands]
    return summands

def derivative_via_diff(cls, ops, kwargs):
    """Implementation of the :meth:`QuantumDerivative.create` interface via the
    use of :meth:`QuantumExpression._diff`.

    Thus, by having :meth:`.QuantumExpression.diff` delegate to
    :meth:`.QuantumDerivative.create`, instead of
    :meth:`.QuantumExpression._diff` directly, we get automatic caching of
    derivatives"""
    assert len(ops) == 1
    op = ops[0]
    derivs = kwargs['derivs']
    vals = kwargs['vals']
    for sym, n in derivs:
        if sym.free_symbols.issubset(op.free_symbols):
            for k in range(n):
                op = op._diff(sym)
        else:
            return op.__class__._zero
    if vals is not None:
        try:
            return op.evaluate_at(vals)
        except AttributeError:
            return op.substitute(vals)
    else:
        return op

def invert_permutation(permutation):
    """Compute the image tuple of the inverse permutation.

    :param permutation: A valid (cf. :py:func:check_permutation) permutation.
    :return: The inverse permutation tuple
    :rtype: tuple"""
    return tuple([permutation.index(p) for p in range(len(permutation))])

def permute(sequence, permutation):
    """Apply a permutation sigma({j}) to an arbitrary sequence.

    :param sequence: Any finite length sequence ``[l_1,l_2,...l_n]``. If it is a list, tuple or str, the return type will be the same.
    :param permutation: permutation image tuple
    :type permutation: tuple
    :return: The permuted sequence ``[l_sigma(1), l_sigma(2), ..., l_sigma(n)]``
    :raise: BadPermutationError or ValueError"""
    if len(sequence) != len(permutation):
        raise ValueError((sequence, permutation))
    if not check_permutation(permutation):
        raise BadPermutationError(str(permutation))
    if type(sequence) in (list, tuple, str):
        constructor = type(sequence)
    else:
        constructor = list
    return constructor((sequence[p] for p in permutation))

def _check_kets(*ops, same_space=False, disjunct_space=False):
    """Check that all operands are Kets from the same Hilbert space."""
    if not all([isinstance(o, State) and o.isket for o in ops]):
        raise TypeError('All operands must be Kets')
    if same_space:
        if not len({o.space for o in ops if o is not ZeroKet}) == 1:
            raise UnequalSpaces(str(ops))
    if disjunct_space:
        spc = TrivialSpace
        for o in ops:
            if o.space & spc > TrivialSpace:
                raise OverlappingSpaces(str(ops))
            spc *= o.space

def _get_common_block_structure(lhs_bs, rhs_bs):
    """For two block structures ``aa = (a1, a2, ..., an)``, ``bb = (b1, b2,
    ..., bm)`` generate the maximal common block structure so that every block
    from aa and bb is contained in exactly one block of the resulting
    structure.  This is useful for determining how to apply the distributive
    law when feeding two concatenated Circuit objects into each other.

    Examples:
        ``(1, 1, 1), (2, 1) -> (2, 1)``
        ``(1, 1, 2, 1), (2, 1, 2) -> (2, 3)``

    Args:
        lhs_bs (tuple): first block structure
        rhs_bs (tuple): second block structure"""
    if isinstance(lhs_bs, Circuit):
        lhs_bs = lhs_bs.block_structure
    if isinstance(rhs_bs, Circuit):
        rhs_bs = rhs_bs.block_structure
    if sum(lhs_bs) != sum(rhs_bs):
        raise IncompatibleBlockStructures('Blockstructures have different total channel numbers.')
    if len(lhs_bs) == len(rhs_bs) == 0:
        return ()
    i = j = 1
    lsum = 0
    while True:
        lsum = sum(lhs_bs[:i])
        rsum = sum(rhs_bs[:j])
        if lsum < rsum:
            i += 1
        elif rsum < lsum:
            j += 1
        else:
            break
    return (lsum,) + _get_common_block_structure(lhs_bs[i:], rhs_bs[j:])

def _factor_permutation_for_blocks(cperm, rhs):
    """Simplification method for cperm << rhs.
    Decompose a series product of a channel permutation and a reducible circuit
    with appropriate block structure by decomposing the permutation into a
    permutation within each block of rhs and a block permutation and a residual
    part.  This allows for achieving something close to a normal form for
    circuit expression."""
    rbs = rhs.block_structure
    if rhs == cid(rhs.cdim):
        return cperm
    if len(rbs) > 1:
        residual_lhs, transformed_rhs, carried_through_lhs = cperm._factorize_for_rhs(rhs)
        if residual_lhs == cperm:
            raise CannotSimplify()
        return SeriesProduct.create(residual_lhs, transformed_rhs, carried_through_lhs)
    raise CannotSimplify()

def _series_feedback(series, out_port, in_port):
    """Invert a series self-feedback twice to get rid of unnecessary
    permutations."""
    series_s = series.series_inverse().series_inverse()
    if series_s == series:
        raise CannotSimplify()
    return series_s.feedback(out_port=out_port, in_port=in_port)

def substitute(expr, var_map):
    """Substitute symbols or (sub-)expressions with the given replacements and
    re-evalute the result

    Args:
        expr: The expression in which to perform the substitution
        var_map (dict): The substitution dictionary."""
    try:
        if isinstance(expr, SympyBasic):
            sympy_var_map = {k: v for k, v in var_map.items() if isinstance(k, SympyBasic)}
            return expr.subs(sympy_var_map)
        else:
            return expr.substitute(var_map)
    except AttributeError:
        if expr in var_map:
            return var_map[expr]
        return expr

def _apply_rules_no_recurse(expr, rules):
    """Non-recursively match expr again all rules"""
    try:
        items = rules.items()
    except AttributeError:
        items = enumerate(rules)
    for key, (pat, replacement) in items:
        matched = pat.match(expr)
        if matched:
            try:
                return replacement(**matched)
            except CannotSimplify:
                pass
    return expr

def requirements_check():
    """Ensure we have programs needed to download/manipulate the data"""
    required_programs = [('samtools', 'http://samtools.sourceforge.net/'), ('bedtools', 'http://bedtools.readthedocs.org/en/latest/'), ('bigWigToBedGraph', 'http://hgdownload.cse.ucsc.edu/admin/exe/linux.x86_64/'), ('bedGraphToBigWig', 'http://hgdownload.cse.ucsc.edu/admin/exe/linux.x86_64/')]
    for req, url in required_programs:
        try:
            p = subprocess.Popen([req], stderr=subprocess.PIPE, stdout=subprocess.PIPE)
            stdout, stderr = p.communicate()
