def cufflinks_conversion():
    """convert Cufflinks output GTF files into tables of score and FPKM."""
    for size, md5, fn in cufflinks_tables:
        fn = os.path.join(args.data_dir, fn)
        table = fn.replace('.gtf.gz', '.table')
        if not _up_to_date(md5, table):
            logger.info('Converting Cufflinks GTF %s to table' % fn)
            fout = open(table, 'w')
            fout.write('id\tscore\tfpkm\n')
            x = pybedtools.BedTool(fn)
            seen = set()
            for i in x:
                accession = i['transcript_id'].split('.')[0]
                if accession not in seen:
                    seen.update([accession])
                    fout.write('\t'.join([accession, i.score, i['FPKM']]) + '\n')
            fout.close()

def tree():
    """Example showing tree progress view"""
    leaf_values = [Value(0) for i in range(6)]
    bd_defaults = dict(type=Bar, kwargs=dict(max_value=10))
    test_d = {'Warp Jump': {'1) Prepare fuel': {'Load Tanks': {'Tank 1': BarDescriptor(value=leaf_values[0], **bd_defaults), 'Tank 2': BarDescriptor(value=leaf_values[1], **bd_defaults)}, 'Refine tylium ore': BarDescriptor(value=leaf_values[2], **bd_defaults)}, '2) Calculate jump co-ordinates': {'Resolve common name to co-ordinates': {'Querying resolution from baseship': BarDescriptor(value=leaf_values[3], **bd_defaults)}}, '3) Perform jump': {'Check FTL drive readiness': BarDescriptor(value=leaf_values[4], **bd_defaults), 'Juuuuuump!': BarDescriptor(value=leaf_values[5], **bd_defaults)}}}
    def incr_value(obj):
        for val in leaf_values:
            if val.value < 10:
                val.value += 1
                break
    def are_we_done(obj):
        return all((val.value == 10 for val in leaf_values))
    t = Terminal()
    n = ProgressTree(term=t)
    n.make_room(test_d)
    while not are_we_done(test_d):
        sleep(0.2 * random.random())
        n.cursor.restore()
        incr_value(test_d)
        n.draw(test_d, BarDescriptor(bd_defaults))

def _updatecopy(orig, update_with, keys=None, override=False):
    """Update a copy of dest with source.  If `keys` is a list, then only update
    with those keys."""
    d = orig.copy()
    if keys is None:
        keys = update_with.keys()
    for k in keys:
        if k in update_with:
            if k in d and (not override):
                continue
            d[k] = update_with[k]
    return d

def chunker(f, n):
    """Utility function to split iterable `f` into `n` chunks"""
    f = iter(f)
    x = []
    while 1:
        if len(x) < n:
            try:
                x.append(f.next())
            except StopIteration:
                if len(x) > 0:
                    yield tuple(x)
                break
        else:
            yield tuple(x)
            x = []

def example_filename(fn):
    """Return a bed file from the pybedtools examples directory.  Use
    :func:`list_example_files` to see a list of files that are included."""
    fn = os.path.join(data_dir(), fn)
    if not os.path.exists(fn):
        raise ValueError('%s does not exist' % fn)
    return fn

def tointerval(s):
    """If string, then convert to an interval; otherwise just return the input"""
    if isinstance(s, basestring):
        m = coord_re.search(s)
        if m.group('strand'):
            return pybedtools.create_interval_from_list([m.group('chrom'), m.group('start'), m.group('stop'), '.', '0', m.group('strand')])
        else:
            return pybedtools.create_interval_from_list([m.group('chrom'), m.group('start'), m.group('stop')])
    return s

def get_text(nodelist):
    """Get the value from a text node."""
    value = []
    for node in nodelist:
        if node.nodeType == node.TEXT_NODE:
            value.append(node.data)
    return ''.join(value)

def cmap_powerlaw_adjust(cmap, a):
    """Returns a new colormap based on the one given
    but adjusted via power-law, `newcmap = oldcmap**a`.

    :param cmap: colormap instance (e.g., cm.jet)
    :param a: power"""
    if a < 0.0:
        return cmap
    cdict = copy.copy(cmap._segmentdata)
    fn = lambda x: (x[0] ** a, x[1], x[2])
    for key in ('red', 'green', 'blue'):
        cdict[key] = map(fn, cdict[key])
        cdict[key].sort()
        assert cdict[key][0] < 0 or cdict[key][-1] > 1, 'Resulting indices extend out of the [0, 1] segment.'
    return colors.LinearSegmentedColormap('colormap', cdict, 1024)

def cmap_center_adjust(cmap, center_ratio):
    """Returns a new colormap based on the one given
    but adjusted so that the old center point higher
    (>0.5) or lower (<0.5)

    :param cmap: colormap instance (e.g., cm.jet)
    :param center_ratio:"""
    if not (0.0 < center_ratio) & (center_ratio < 1.0):
        return cmap
    a = math.log(center_ratio) / math.log(0.5)
    return cmap_powerlaw_adjust(cmap, a)

def cmap_center_point_adjust(cmap, range, center):
    """Converts center to a ratio between 0 and 1 of the
    range given and calls cmap_center_adjust(). returns
    a new adjusted colormap accordingly

    :param cmap: colormap instance
    :param range: Tuple of (min, max)
    :param center: New cmap center"""
    if not (range[0] < center and center < range[1]):
        return cmap
    return cmap_center_adjust(cmap, abs(center - range[0]) / abs(range[1] - range[0]))

def _local_count(reader, feature, stranded=False):
    """The count of genomic signal (typcially BED features) found within an
    interval.

    Usually this only makes sense for BED or BAM (not bigWig) files.

    :param feature: pybedtools.Interval object
    :param stranded: If `stranded=True`, then only counts signal on the same
        strand as `feature`."""
    if isinstance(feature, basestring):
        feature = helpers.tointerval(feature)
    if stranded:
        strand = feature.strand
    else:
        strand = '.'
    count = 0
    for al in reader[feature]:
        if stranded and al.strand != strand:
            continue
        count += 1
    return count

def _array_star(args):
    """Unpacks the tuple `args` and calls _array.  Needed to pass multiple args to
    a pool.map-ed function"""
    fn, cls, genelist, kwargs = args
    return _array(fn, cls, genelist, **kwargs)

def _array(fn, cls, genelist, **kwargs):
    """Returns a "meta-feature" array, with len(genelist) rows and `bins`
    cols.  Each row contains the number of reads falling in each bin of
    that row's modified feature."""
    reader = cls(fn)
    _local_coverage_func = cls.local_coverage
    biglist = []
    if 'bins' in kwargs:
        if isinstance(kwargs['bins'], int):
            kwargs['bins'] = [kwargs['bins']]
    for gene in genelist:
        if not isinstance(gene, (list, tuple)):
            gene = [gene]
        coverage_x, coverage_y = _local_coverage_func(reader, gene, **kwargs)
        biglist.append(coverage_y)
    return biglist

def find_spelling(n):
    """Finds d, r s.t. n-1 = 2^r * d"""
    r = 0
    d = n - 1
    quotient, remainder = divmod(d, 2)
    while remainder != 1:
        r += 1
        d = quotient
        quotient, remainder = divmod(d, 2)
    return (r, d)

def probably_prime(n, k=10):
    """Miller-Rabin primality test
    Input: n > 3
    k: accuracy of test
    Output: True if n is "probably prime", False if it is composite

    From psuedocode at https://en.wikipedia.org/wiki/Miller%E2%80%93Rabin_primality_test"""
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    r, d = find_spelling(n)
    for check in range(k):
        a = random.randint(2, n - 1)
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            continue
        for i in range(r):
            x = pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False
    return True

def _find_next_prime(N):
    """Find next prime >= N"""
    def is_prime(n):
        if n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i:
                i += 2
            else:
                return False
        return True
    if N < 3:
        return 2
    if N % 2 == 0:
        N += 1
    for n in range(N, 2 * N, 2):
        if is_prime(n):
            return n
    raise AssertionError('Failed to find a prime number between {0} and {1}...'.format(N, 2 * N))

