def songname(song_name):
    """Improves file name by removing crap words"""
    try:
        song_name = splitext(song_name)[0]
    except IndexError:
        pass
    chars_filter = '()[]{}-:_/=+"\''
    words_filter = ('official', 'lyrics', 'audio', 'remixed', 'remix', 'video', 'full', 'version', 'music', 'mp3', 'hd', 'hq', 'uploaded')
    song_name = ''.join(map(lambda c: ' ' if c in chars_filter else c, song_name))
    song_name = re.sub('|'.join((re.escape(key) for key in words_filter)), '', song_name, flags=re.IGNORECASE)
    song_name = re.sub(' +', ' ', song_name)
    return song_name.strip()

