def _embedding_nonmetric_mds(matrix, dimensions=3, initial_coords=None):
    """Private method to calculate NMMDS embedding
    :param dimensions: (int)
    :return: coordinate matrix (np.array)"""
    mds = sklearn.manifold.MDS(n_components=dimensions, dissimilarity='precomputed', metric=False)
    if initial_coords is not None:
        mds.fit(matrix, init=initial_coords)
    else:
        mds.fit(matrix)
    return mds.embedding_

def _embedding_kernel_pca(matrix, dimensions=3, affinity_matrix=None, sigma=1):
    """Private method to calculate KPCA embedding
    :param dimensions: (int)
    :return: coordinate matrix (np.array)"""
    if affinity_matrix is None:
        aff = rbf(matrix, sigma)
    else:
        aff = affinity_matrix
    kpca = sklearn.decomposition.KernelPCA(kernel='precomputed', n_components=dimensions)
    return kpca.fit_transform(aff)

def extract_value(mapping, bind, data):
    """Given a mapping and JSON schema spec, extract a value from ``data``
    and apply certain transformations to normalize the value."""
    columns = mapping.get('columns', [mapping.get('column')])
    values = [data.get(c) for c in columns]
    for transform in mapping.get('transforms', []):
        values = list(TRANSFORMS[transform](mapping, bind, values))
    format_str = mapping.get('format')
    value = values[0] if len(values) else None
    if not is_empty(format_str):
        value = format_str % tuple(('' if v is None else v for v in values))
    empty = is_empty(value)
    if empty:
        value = mapping.get('default') or bind.schema.get('default')
    return (empty, convert_value(bind, value))

def get_type(bind):
    """Detect the ideal type for the data, either using the explicit type
    definition or the format (for date, date-time, not supported by JSON)."""
    types = bind.types + [bind.schema.get('format')]
    for type_name in ('date-time', 'date', 'decimal', 'integer', 'boolean', 'number', 'string'):
        if type_name in types:
            return type_name
    return 'string'

def convert_value(bind, value):
    """Type casting."""
    type_name = get_type(bind)
    try:
        return typecast.cast(type_name, value)
    except typecast.ConverterError:
        return value

def threadpool_map(task, args, message, concurrency, batchsize=1, nargs=None):
    """Helper to map a function over a range of inputs, using a threadpool, with a progress meter"""
    import concurrent.futures
    njobs = get_njobs(nargs, args)
    show_progress = bool(message)
    batches = grouper(batchsize, tupleise(args))
    batched_task = lambda batch: [task(*job) for job in batch]
    if show_progress:
        message += ' (TP:{}w:{}b)'.format(concurrency, batchsize)
        pbar = setup_progressbar(message, njobs, simple_progress=True)
        pbar.start()
    with concurrent.futures.ThreadPoolExecutor(max_workers=concurrency) as executor:
        futures = []
        completed_count = 0
        for batch in batches:
            futures.append(executor.submit(batched_task, batch))
        if show_progress:
            for i, fut in enumerate(concurrent.futures.as_completed(futures), start=1):
                completed_count += len(fut.result())
                pbar.update(completed_count)
        else:
            concurrent.futures.wait(futures)
    if show_progress:
        pbar.finish()
    return flatten_list([fut.result() for fut in futures])

def grouper(n, iterable):
    """>>> list(grouper(3, 'ABCDEFG'))
    [['A', 'B', 'C'], ['D', 'E', 'F'], ['G']]"""
    iterable = iter(iterable)
    return iter(lambda: list(itertools.islice(iterable, n)), [])

def insort_no_dup(lst, item):
    """If item is not in lst, add item to list at its sorted position"""
    import bisect
    ix = bisect.bisect_left(lst, item)
    if lst[ix] != item:
        lst[ix:ix] = [item]

def alignment_to_partials(alignment, missing_data=None):
    """Generate a partials dictionary from a treeCl.Alignment"""
    partials_dict = {}
    for name, sequence in alignment.get_sequences():
        datatype = 'dna' if alignment.is_dna() else 'protein'
        partials_dict[name] = seq_to_partials(sequence, datatype)
    if missing_data is not None:
        l = len(alignment)
        for name in missing_data:
            if name not in partials_dict:
                partials_dict[name] = seq_to_partials('-' * l, datatype)
    return partials_dict

def biopython_to_partials(alignment, datatype):
    """Generate a partials dictionary from a treeCl.Alignment"""
    partials_dict = {}
    for seq in alignment:
        partials_dict[seq.name] = seq_to_partials(seq, datatype)
    return partials_dict

def sample_wr(lst):
    """Sample from lst, with replacement"""
    arr = np.array(lst)
    indices = np.random.randint(len(lst), size=len(lst))
    sample = np.empty(arr.shape, dtype=arr.dtype)
    for i, ix in enumerate(indices):
        sample[i] = arr[ix]
    return list(sample)

def _preprocess_inputs(x, weights):
    """Coerce inputs into compatible format"""
    if weights is None:
        w_arr = np.ones(len(x))
    else:
        w_arr = np.array(weights)
    x_arr = np.array(x)
    if x_arr.ndim == 2:
        if w_arr.ndim == 1:
            w_arr = w_arr[:, np.newaxis]
    return (x_arr, w_arr)

def amean(x, weights=None):
    """Return the weighted arithmetic mean of x"""
    w_arr, x_arr = _preprocess_inputs(x, weights)
    return (w_arr * x_arr).sum(axis=0) / w_arr.sum(axis=0)

def gmean(x, weights=None):
    """Return the weighted geometric mean of x"""
    w_arr, x_arr = _preprocess_inputs(x, weights)
    return np.exp((w_arr * np.log(x_arr)).sum(axis=0) / w_arr.sum(axis=0))

def hmean(x, weights=None):
    """Return the weighted harmonic mean of x"""
    w_arr, x_arr = _preprocess_inputs(x, weights)
    return w_arr.sum(axis=0) / (w_arr / x_arr).sum(axis=0)

def jac(x, a):
    """Jacobian matrix given Christophe's suggestion of f"""
    return (x - a) / np.sqrt(((x - a) ** 2).sum(1))[:, np.newaxis]

def gradient(x, a, c):
    """J'.G"""
    return jac(x, a).T.dot(g(x, a, c))

def hessian(x, a):
    """J'.J"""
    j = jac(x, a)
    return j.T.dot(j)

def grad_desc_update(x, a, c, step=0.01):
    """Given a value of x, return a better x
    using gradient descent"""
    return x - step * gradient(x, a, c)

def newton_update(x, a, c, step=1.0):
    """Given a value of x, return a better x
    using newton-gauss"""
    return x - step * np.linalg.inv(hessian(x, a)).dot(gradient(x, a, c))

def levenberg_marquardt_update(x, a, c, damping=0.001):
    """Given a value of x, return a better x
    using newton-gauss"""
    hess = hessian(x, a)
    return x - np.linalg.inv(hess + damping * np.diag(hess)).dot(gradient(x, a, c))

def stress(ref_cds, est_cds):
    """Kruskal's stress"""
    ref_dists = pdist(ref_cds)
    est_dists = pdist(est_cds)
    return np.sqrt(((ref_dists - est_dists) ** 2).sum() / (ref_dists ** 2).sum())

def rmsd(ref_cds, est_cds):
    """Root-mean-squared-difference"""
    ref_dists = pdist(ref_cds)
    est_dists = pdist(est_cds)
    return np.sqrt(((ref_dists - est_dists) ** 2).mean())

def generate_schema_mapping(resolver, schema_uri, depth=1):
    """Try and recursively iterate a JSON schema and to generate an ES mapping
    that encasulates it."""
