def clean(func):
    """This decorator removes the temp file from disk. This is the case where
    you want to analyze from a payload."""
    def wrapper(*args, **kwargs):
        out, given_path, path = func(*args, **kwargs)
        try:
            if not given_path:
                os.remove(path)
        except OSError:
            pass
        return out
    return wrapper

def freader(filename, gz=False, bz=False):
    """Returns a filereader object that can handle gzipped input"""
    filecheck(filename)
    if filename.endswith('.gz'):
        gz = True
    elif filename.endswith('.bz2'):
        bz = True
    if gz:
        return gzip.open(filename, 'rb')
    elif bz:
        return bz2.BZ2File(filename, 'rb')
    else:
        return io.open(filename, 'rb')

def fwriter(filename, gz=False, bz=False):
    """Returns a filewriter object that can write plain or gzipped output.
    If gzip or bzip2 compression is asked for then the usual filename extension will be added."""
    if filename.endswith('.gz'):
        gz = True
    elif filename.endswith('.bz2'):
        bz = True
    if gz:
        if not filename.endswith('.gz'):
            filename += '.gz'
        return gzip.open(filename, 'wb')
    elif bz:
        if not filename.endswith('.bz2'):
            filename += '.bz2'
        return bz2.BZ2File(filename, 'w')
    else:
        return open(filename, 'w')

def head(filename, n=10):
    """prints the top `n` lines of a file"""
    with freader(filename) as fr:
        for _ in range(n):
            print(fr.readline().strip())

def edge_length_check(length, edge):
    """Raises error if length is not in interval [0, edge.length]"""
    try:
        assert 0 <= length <= edge.length
    except AssertionError:
        if length < 0:
            raise TreeError('Negative edge-lengths are disallowed')
        raise TreeError("This edge isn't long enough to prune at length {0}\n(Edge length = {1})".format(length, edge.length))

def MD5Hash(password):
    """Returns md5 hash of a string.

    @param password (string) - String to be hashed.

    @return (string) - Md5 hash of password."""
    md5_password = md5.new(password)
    password_md5 = md5_password.hexdigest()
    return password_md5

def _next_regular(target):
    """Find the next regular number greater than or equal to target.
    Regular numbers are composites of the prime factors 2, 3, and 5.
    Also known as 5-smooth numbers or Hamming numbers, these are the optimal
    size for inputs to FFTPACK.
    Target must be a positive integer."""
    if target <= 6:
        return target
    if not target & target - 1:
        return target
    match = float('inf')
    p5 = 1
    while p5 < target:
        p35 = p5
        while p35 < target:
            quotient = -(-target // p35)
            try:
                p2 = 2 ** (quotient - 1).bit_length()
            except AttributeError:
                p2 = 2 ** _bit_length_26(quotient - 1)
            N = p2 * p35
            if N == target:
                return N
            elif N < match:
                match = N
            p35 *= 3
            if p35 == target:
                return p35
        if p35 < match:
            match = p35
        p5 *= 5
        if p5 == target:
            return p5
    if p5 < match:
        match = p5
    return match

def module_getmtime(filename):
    """Get the mtime associated with a module.  If this is a .pyc or .pyo file and
    a corresponding .py file exists, the time of the .py file is returned.

    :param filename: filename of the module.
    :returns: mtime or None if the file doesn"t exist."""
    if os.path.splitext(filename)[1].lower() in ('.pyc', '.pyo') and os.path.exists(filename[:-1]):
        return os.path.getmtime(filename[:-1])
    if os.path.exists(filename):
        return os.path.getmtime(filename)
    return None

def module_reload_changed(key):
    """Reload a module if it has changed since we last imported it.  This is
    necessary if module a imports script b, script b is changed, and then
    module c asks to import script b.

    :param key: our key used in the WatchList.
    :returns: True if reloaded."""
    imp.acquire_lock()
    try:
        modkey = module_sys_modules_key(key)
        if not modkey:
            return False
        found = None
        if modkey:
            for second in WatchList:
                secmodkey = module_sys_modules_key(second)
                if secmodkey and sys.modules[modkey] == sys.modules[secmodkey]:
                    found = second
                    foundmodkey = secmodkey
                    break
        if not found:
            return
        filemtime = module_getmtime(WatchList[found]['file'])
        filemtime = latest_submodule_time(found, filemtime)
        if filemtime > WatchList[found]['time']:
            tangelo.log('Reloaded %s' % found)
            reload_including_local(sys.modules[foundmodkey])
            for second in WatchList:
                if WatchList[second]['file'] == WatchList[found]['file']:
                    WatchList[second]['time'] = filemtime
    finally:
        imp.release_lock()
    return True

def reload_including_local(module):
    """Reload a module.  If it isn"t found, try to include the local service
    directory.  This must be called from a thread that has acquired the import
    lock.

    :param module: the module to reload."""
    try:
        reload(module)
    except ImportError:
        if not hasattr(cherrypy.thread_data, 'modulepath'):
            raise
        path = os.path.abspath(cherrypy.thread_data.modulepath)
        root = os.path.abspath(cherrypy.config.get('webroot'))
        if path not in sys.path and (path == root or path.startswith(root + os.path.sep)):
            oldpath = sys.path
            try:
                sys.path = [path] + sys.path
                reload(module)
            finally:
                sys.path = oldpath
        else:
            raise

def watch_import(name, globals=None, *args, **kwargs):
    """When a module is asked to be imported, check if we have previously imported
    it.  If so, check if the time stamp of it, a companion yaml file, or any
    modules it imports have changed.  If so, reimport the module.

    :params: see __builtin__.__import__"""
    monitor = not imp.is_builtin(name) and name not in ('types',)
    monitor = monitor and isinstance(globals, dict) and globals.get('__name__')
    if not monitor:
        return builtin_import(name, globals, *args, **kwargs)
    parent = globals['__name__']
    key = parent + '.' + name
    module_reload_changed(key)
    try:
        module = builtin_import(name, globals, *args, **kwargs)
    except ImportError:
        raise
    if getattr(module, '__file__', None):
        if key not in WatchList:
            tangelo.log_info('WATCH', 'Monitoring import %s from %s' % (name, parent))
        imp.acquire_lock()
        try:
            if key not in WatchList:
                filemtime = module_getmtime(module.__file__) or 0
                filemtime = latest_submodule_time(key, filemtime)
                WatchList[key] = {'time': filemtime}
            WatchList[key].update({'parent': parent, 'name': name, 'file': module.__file__})
        finally:
            imp.release_lock()
    return module

def return_type(rettype):
    """Decorate a function to automatically convert its return type to a string
    using a custom function.

    Web-based service functions must return text to the client.  Tangelo
    contains default logic to convert many kinds of values into string, but this
    decorator allows the service writer to specify custom behavior falling
    outside of the default.  If the conversion fails, an appropriate server
    error will be raised."""
    def wrap(f):
        @functools.wraps(f)
        def converter(*pargs, **kwargs):
            result = f(*pargs, **kwargs)
            try:
                result = rettype(result)
            except ValueError as e:
                http_status(500, 'Return Value Conversion Failed')
                content_type('application/json')
                return {'error': str(e)}
            return result
        return converter
    return wrap

def list_snapshots_days(path, cam_id):
    """Returns a list of (date, dir) in which snapshopts are present"""
    screenshoots_path = path + '/' + str(cam_id)
    if os.path.exists(screenshoots_path):
        days = []
        for day_dir in os.listdir(screenshoots_path):
            date = datetime.datetime.strptime(day_dir, '%d%m%Y').strftime('%d/%m/%y')
            days.append((date, day_dir))
        return days
    else:
        return []

def list_snapshots_hours(path, cam_id, day):
    """Returns a list of hour/min in which snapshopts are present"""
    screenshoots_path = path + '/' + str(cam_id) + '/' + day
    if os.path.exists(screenshoots_path):
        hours = []
        for hour_dir in sorted(os.listdir(screenshoots_path)):
            hrm = datetime.datetime.strptime(hour_dir, '%H%M').strftime('%H:%M')
            hours.append((hrm, hour_dir))
        return hours
    else:
        return []

def list_snapshots_for_a_minute(path, cam_id, day, hourm):
    """Returns a list of screenshots"""
    screenshoots_path = path + '/' + str(cam_id) + '/' + day + '/' + hourm
    if os.path.exists(screenshoots_path):
        screenshots = [scr for scr in sorted(os.listdir(screenshoots_path))]
        return screenshots
    else:
        return []

def table_output(data):
    """Get a table representation of a dictionary."""
    if type(data) == DictType:
        data = data.items()
    headings = [item[0] for item in data]
    rows = [item[1] for item in data]
    columns = zip(*rows)
    if len(columns):
        widths = [max([len(str(y)) for y in row]) for row in rows]
    else:
        widths = [0 for c in headings]
    for c, heading in enumerate(headings):
        widths[c] = max(widths[c], len(heading))
    column_count = range(len(rows))
    table = [' '.join([headings[c].ljust(widths[c]) for c in column_count])]
    table.append(' '.join(['=' * widths[c] for c in column_count]))
    for column in columns:
        table.append(' '.join([str(column[c]).ljust(widths[c]) for c in column_count]))
    return '\n'.join(table)

def to_datetime(time):
    """Convert `time` to a datetime."""
    if type(time) == IntType or type(time) == LongType:
        time = datetime.fromtimestamp(time // 1000)
    return time

def spellCheckTextgrid(tg, targetTierName, newTierName, isleDict, printEntries=False):
    """Spell check words by using the praatio spellcheck function

    Incorrect items are noted in a new tier and optionally
        printed to the screen"""
    def checkFunc(word):
        try:
            isleDict.lookup(word)
        except isletool.WordNotInISLE:
            returnVal = False
        else:
            returnVal = True
        return returnVal
    tg = praatio_scripts.spellCheckEntries(tg, targetTierName, newTierName, checkFunc, printEntries)
    return tg

def findOODWords(isleDict, wordList):
    """Returns all of the out-of-dictionary words found in a list of utterances"""
    oodList = []
    for word in wordList:
        try:
            isleDict.lookup(word)
        except WordNotInISLE:
            oodList.append(word)
    oodList = list(set(oodList))
    oodList.sort()
    return oodList

def _getSyllableNucleus(phoneList):
    """Given the phones in a syllable, retrieves the vowel index"""
    cvList = ['V' if isletool.isVowel(phone) else 'C' for phone in phoneList]
    vowelCount = cvList.count('V')
    if vowelCount > 1:
        raise TooManyVowelsInSyllable(phoneList, cvList)
    if vowelCount == 1:
        stressI = cvList.index('V')
    else:
        stressI = None
    return stressI

