def find_keys(args):
    """Get keys specified in arguments

    returns list of keys or None"""
    key = args['--key']
    if key:
        return [key]
    keyfile = args['--apikeys']
    if keyfile:
        return read_keyfile(keyfile)
    envkey = os.environ.get('TINYPNG_API_KEY', None)
    if envkey:
        return [envkey]
    local_keys = join(abspath('.'), 'tinypng.keys')
    if isfile(local_keys):
        return read_keyfile(local_keys)
    home_keys = join(expanduser('~/.tinypng.keys'))
    if isfile(home_keys):
        return read_keyfile(home_keys)
    return []

def get_shrink_data_info(in_data, api_key=None):
    """Shrink binary data of a png

    returns api_info"""
    if api_key:
        return _shrink_info(in_data, api_key)
    api_keys = find_keys()
    for key in api_keys:
        try:
            return _shrink_info(in_data, key)
        except ValueError:
            pass
    raise ValueError('No valid api key found')

def get_shrunk_data(shrink_info):
    """Read shrunk file from tinypng.org api."""
    out_url = shrink_info['output']['url']
    try:
        return requests.get(out_url).content
    except HTTPError as err:
        if err.code != 404:
            raise
        exc = ValueError('Unable to read png file "{0}"'.format(out_url))
        exc.__cause__ = err
        raise exc

def shrink_data(in_data, api_key=None):
    """Shrink binary data of a png

    returns (api_info, shrunk_data)"""
    info = get_shrink_data_info(in_data, api_key)
    return (info, get_shrunk_data(info))

def verify_telesign_callback_signature(api_key, signature, json_str):
    """Verify that a callback was made by TeleSign and was not sent by a malicious client by verifying the signature.

    :param api_key: the TeleSign API api_key associated with your account.
    :param signature: the TeleSign Authorization header value supplied in the callback, as a string.
    :param json_str: the POST body text, that is, the JSON string sent by TeleSign describing the transaction status."""
    your_signature = b64encode(HMAC(b64decode(api_key), json_str.encode('utf-8'), sha256).digest()).decode('utf-8')
    if len(signature) != len(your_signature):
        return False
    signatures_equal = True
    for x, y in zip(signature, your_signature):
        if not x == y:
            signatures_equal = False
    return signatures_equal

def markdown(text, renderer=None, **options):
    """Parses the provided Markdown-formatted text into valid HTML, and returns
    it as a :class:`flask.Markup` instance.

    :param text: Markdown-formatted text to be rendered into HTML
    :param renderer: A custom misaka renderer to be used instead of the default one
    :param options: Additional options for customizing the default renderer
    :return: A :class:`flask.Markup` instance representing the rendered text"""
    ext, rndr = make_flags(**options)
    if renderer:
        md = misaka.Markdown(renderer, ext)
        result = md(text)
    else:
        result = misaka.html(text, extensions=ext, render_flags=rndr)
    if options.get('smartypants'):
        result = misaka.smartypants(result)
    return Markup(result)

def get_side_attr(attr, invert, player):
    """Get a player attribute that depends on which side the player is on.
    A creep kill for a radiant hero is a badguy_kill, while a creep kill
    for a dire hero is a goodguy_kill."""
    t = player.team
    if invert:
        t = not player.team
    return getattr(player, '%s_%s' % ('goodguy' if t else 'badguy', attr))

def _maybe_print(something_to_print, end=None, min_=1, max_=99, verbose=0):
    """Print if verbose is within min_ and max_."""
    if min_ <= verbose <= max_:
        import sys
        print(something_to_print, end=end)
        sys.stdout.flush()

def version():
    """Return version string."""
    with open(os.path.join(os.path.abspath(os.path.dirname(__file__)), 'pep8radius', 'main.py')) as input_file:
        for line in input_file:
            if line.startswith('__version__'):
                return parse(line).body[0].value.s

def url_map(base, params):
    """Return a URL with get parameters based on the params passed in
    This is more forgiving than urllib.urlencode and will attempt to coerce
    non-string objects into strings and automatically UTF-8 encode strings.

    @param params: HTTP GET parameters"""
    url = base
    if not params:
        url.rstrip('?&')
    elif '?' not in url:
        url += '?'
    entries = []
    for key, value in params.items():
        if value is not None:
            value = str(value)
            entries.append('%s=%s' % (quote_plus(key.encode('utf-8')), quote_plus(value.encode('utf-8'))))
    url += '&'.join(entries)
    return str(url)

def make_request(name, params=None, version='V001', key=None, api_type='web', fetcher=get_page, base=None, language='en_us'):
    """Make an API request"""
    params = params or {}
    params['key'] = key or API_KEY
    params['language'] = language
    if not params['key']:
        raise ValueError('API key not set, please set DOTA2_API_KEY')
    url = url_map('%s%s/%s/' % (base or BASE_URL, name, version), params)
    return fetcher(url)

def json_request_response(f):
    """Parse the JSON from an API response. We do this in a decorator so that our
    Twisted library can reuse the underlying functions"""
    @wraps(f)
    def wrapper(*args, **kwargs):
        response = f(*args, **kwargs)
        response.raise_for_status()
        return json.loads(response.content.decode('utf-8'))
    API_FUNCTIONS[f.__name__] = f
    return wrapper

