def dumps(*args, **kwargs):
    """Wrapper for json.dumps that uses the JSONArgonautsEncoder."""
    import json
    from django.conf import settings
    from argonauts.serializers import JSONArgonautsEncoder
    kwargs.setdefault('cls', JSONArgonautsEncoder)
    if settings.DEBUG:
        kwargs.setdefault('indent', 4)
        kwargs.setdefault('separators', (',', ': '))
    else:
        kwargs.setdefault('separators', (',', ':'))
    return json.dumps(*args, **kwargs)

def variables(template):
    """Returns the set of keywords in a uri template"""
    vars = set()
    for varlist in TEMPLATE.findall(template):
        if varlist[0] in OPERATOR:
            varlist = varlist[1:]
        varspecs = varlist.split(',')
        for var in varspecs:
            var = var.split(':')[0]
            if var.endswith('*'):
                var = var[:-1]
            vars.add(var)
    return vars

def _discover_bounds(cdf, tol=1e-07):
    """Uses scipy's general continuous distribution methods
    which compute the ppf from the cdf, then use the ppf
    to find the lower and upper limits of the distribution."""
    class DistFromCDF(stats.distributions.rv_continuous):
        def cdf(self, x):
            return cdf(x)
    dist = DistFromCDF()
    lower = dist.ppf(tol)
    upper = dist.ppf(1.0 - tol)
    return (lower, upper)

def _crps_cdf_single(x, cdf_or_dist, xmin=None, xmax=None, tol=1e-06):
    """See crps_cdf for docs."""
    cdf = getattr(cdf_or_dist, 'cdf', cdf_or_dist)
    assert callable(cdf)
    if xmin is None or xmax is None:
        xmin, xmax = _discover_bounds(cdf)
    if tol is not None and cdf(xmin) >= tol or cdf(xmax) <= 1.0 - tol:
        raise ValueError('CDF does not meet tolerance requirements at %s extreme(s)! Consider using function defaults or using infinities at the bounds. ' % ('lower' if cdf(xmin) >= tol else 'upper'))
    def lhs(y):
        return np.square(cdf(y))
    lhs_int, lhs_tol = integrate.quad(lhs, xmin, x)
    if tol is not None and lhs_tol >= 0.5 * tol:
        raise ValueError('Lower integral did not evaluate to within tolerance! Tolerance achieved: %f , Value of integral: %f \nConsider setting the lower bound to -np.inf.' % (lhs_tol, lhs_int))
    def rhs(y):
        return np.square(1.0 - cdf(y))
    rhs_int, rhs_tol = integrate.quad(rhs, x, xmax)
    if tol is not None and rhs_tol >= 0.5 * tol:
        raise ValueError('Upper integral did not evaluate to within tolerance! \nTolerance achieved: %f , Value of integral: %f \nConsider setting the upper bound to np.inf or if you already have, set warn_level to `ignore`.' % (rhs_tol, rhs_int))
    return lhs_int + rhs_int

def shell_out(cmd, stderr=STDOUT, cwd=None):
    """Friendlier version of check_output."""
    if cwd is None:
        from os import getcwd
        cwd = getcwd()
    out = check_output(cmd, cwd=cwd, stderr=stderr, universal_newlines=True)
    return _clean_output(out)

def shell_out_ignore_exitcode(cmd, stderr=STDOUT, cwd=None):
    """Same as shell_out but doesn't raise if the cmd exits badly."""
    try:
        return shell_out(cmd, stderr=stderr, cwd=cwd)
    except CalledProcessError as c:
        return _clean_output(c.output)

