def dfromdm(dm):
    """Returns distance given distance modulus.
    """
    if np.size(dm) > 1:
        dm = np.atleast_1d(dm)
    return 10 ** (1 + dm / 5)

def distancemodulus(d):
    """Returns distance modulus given d in parsec.
    """
    if type(d) == Quantity:
        x = d.to('pc').value
    else:
        x = d
    if np.size(x) > 1:
        d = np.atleast_1d(x)
    return 5 * np.log10(x / 10)

def kdeconf(kde, conf=0.683, xmin=None, xmax=None, npts=500, shortest=True, conftol=0.001, return_max=False):
    """Returns desired confidence interval for provided KDE object"""
    if xmin is None:
        xmin = kde.dataset.min()
    if xmax is None:
        xmax = kde.dataset.max()
    x = np.linspace(xmin, xmax, npts)
    return conf_interval(x, kde(x), shortest=shortest, conf=conf, conftol=conftol, return_max=return_max)

def qstd(x, quant=0.05, top=False, bottom=False):
    """returns std, ignoring outer 'quant' pctiles
    """
    s = np.sort(x)
    n = np.size(x)
    lo = s[int(n * quant)]
    hi = s[int(n * (1 - quant))]
    if top:
        w = np.where(x >= lo)
    elif bottom:
        w = np.where(x <= hi)
    else:
        w = np.where((x >= lo) & (x <= hi))
    return np.std(x[w])

def impact_parameter(a, R, inc, ecc=0, w=0, return_occ=False):
    """a in AU, R in Rsun, inc & w in radians
    """
    b_tra = a * AU * np.cos(inc) / (R * RSUN) * (1 - ecc ** 2) / (1 + ecc * np.sin(w))
    if return_occ:
        b_tra = a * AU * np.cos(inc) / (R * RSUN) * (1 - ecc ** 2) / (1 - ecc * np.sin(w))
        return (b_tra, b_occ)
    else:
        return b_tra

def a_over_Rs(P, R2, M2, M1=1, R1=1, planet=True):
    """Returns a/Rs for given parameters."""
    if planet:
        M2 *= REARTH / RSUN
        R2 *= MEARTH / MSUN
    return semimajor(P, M1 + M2) * AU / (R1 * RSUN)

def fit_traptransit(ts, fs, p0):
    """Fits trapezoid model to provided ts,fs"""
    pfit, success = leastsq(traptransit_resid, p0, args=(ts, fs))
    if success not in [1, 2, 3, 4]:
        raise NoFitError
    return pfit

def traptransit_lhood(pars, ts, fs, sigs, maxslope=MAXSLOPE):
    """Params: depth, duration, slope, t0"""
    if pars[0] < 0 or pars[1] < 0 or pars[2] < 2 or (pars[2] > maxslope):
        return -np.inf
    fmod = traptransit(ts, pars)
    tot = 0
    for i in range(len(ts)):
        tot += -0.5 * (fmod[i] - fs[i]) * (fmod[i] - fs[i]) / (sigs[i] * sigs[i])
    return tot

def write_results(self, folder=None, filename='results.txt', to_file=True):
    """Writes text file of calculation summary.

    :param folder: (optional)
        Folder to which to write ``results.txt``.

    :param filename:
        Filename to write.  Default=``results.txt``.

    :param to_file:
        If True, then writes file.  Otherwise just return header, line.

    :returns:
        Header string, line"""
    if folder is None:
        folder = self.folder
    if to_file:
        fout = open(os.path.join(folder, filename), 'w')
    header = ''
    for m in self.popset.shortmodelnames:
        header += 'lhood_{0} L_{0} pr_{0} '.format(m)
    header += 'fpV fp FPP'
    if to_file:
        fout.write('{} \n'.format(header))
    Ls = {}
    Ltot = 0
    lhoods = {}
    for model in self.popset.modelnames:
        lhoods[model] = self.lhood(model)
        Ls[model] = self.prior(model) * lhoods[model]
        Ltot += Ls[model]
    line = ''
    for model in self.popset.modelnames:
        line += '%.2e %.2e %.2e ' % (lhoods[model], Ls[model], Ls[model] / Ltot)
    line += '%.3g %.3f %.2e' % (self.fpV(), self.priorfactors['fp_specific'], self.FPP())
    if to_file:
        fout.write(line + '\n')
        fout.close()
    return (header, line)

