            config['Teff'] = (teff, e_teff)
    if use_property(kepid, 'logg'):
        logg, e_logg = (kicu.DATA.ix[kepid, 'logg'], kicu.DATA.ix[kepid, 'logg_err1'])
        if not any(np.isnan([logg, e_logg])):
