    ```

    :param message: Validation error message
    :type message: unicode
    :param expected: Expected value string representation, or `None` to get it from the wrapped callable
    :type expected: None|str|unicode
    :return: decorator
    :rtype: callable"""
    def decorator(func):
        return update_wrapper(Check(func, message, expected), func)
    return decorator

def stringmethod(func):
    """Validator factory which call a single method on the string."""
    method_name = func()
    @wraps(func)
    def factory():
        def validator(v):
            if not isinstance(v, six.string_types):
                raise Invalid(_(u'Not a string'), get_type_name(six.text_type), get_type_name(type(v)))
            return getattr(v, method_name)()
        return validator
    return factory

def generate_random_type(valid):
    """Generate a random type and samples for it.

    :param valid: Generate valid samples?
    :type valid: bool
    :return: type, sample-generator
    :rtype: type, generator"""
    type = choice(['int', 'str'])
    r = lambda: randrange(-1000000000, 1000000000)
    if type == 'int':
        return (int, (r() if valid else str(r()) for i in itertools.count()))
    elif type == 'str':
        return (str, (str(r()) if valid else r() for i in itertools.count()))
    else:
        raise AssertionError('!')

def generate_random_schema(valid):
    """Generate a random plain schema, and a sample generation function.

    :param valid: Generate valid samples?
    :type valid: bool
    :returns: schema, sample-generator
    :rtype: *, generator"""
    schema_type = choice(['literal', 'type'])
    if schema_type == 'literal':
        type, gen = generate_random_type(valid)
        value = next(gen)
        return (value, (value if valid else None for i in itertools.count()))
    elif schema_type == 'type':
        return generate_random_type(valid)
    else:
        raise AssertionError('!')

def ignore_patterns(*patterns):
    """Function that can be used as copytree() ignore parameter.

    Patterns is a sequence of glob-style patterns
    that are used to exclude files"""
    import fnmatch
    def _ignore_patterns(path, names):
        ignored_names = []
        for pattern in patterns:
            ignored_names.extend(fnmatch.filter(names, pattern))
        return set(ignored_names)
    return _ignore_patterns

def _construct_var_eqns(data, p, delta=None):
    """Construct VAR equation system (optionally with RLS constraint).
    """
    t, m, l = np.shape(data)
    n = (l - p) * t
    rows = n if delta is None else n + m * p
    x = np.zeros((rows, m * p))
    for i in range(m):
        for k in range(1, p + 1):
            x[:n, i * p + k - 1] = np.reshape(data[:, i, p - k:-k].T, n)
    if delta is not None:
        np.fill_diagonal(x[n:, :], delta)
    y = np.zeros((rows, m))
    for i in range(m):
        y[:n, i] = np.reshape(data[:, i, p:].T, n)
    return (x, y)

def _todict(matobj):
    """a recursive function which constructs from matobjects nested dictionaries"""
    dictionary = {}
    for strg in matobj._fieldnames:
        elem = matobj.__dict__[strg]
        if isinstance(elem, matlab.mio5_params.mat_struct):
            dictionary[strg] = _todict(elem)
        else:
            dictionary[strg] = elem
    return dictionary

def _get_msge_with_gradient_func(shape, p):
    """Select which function to use for MSGE calculation (over- or
    underdetermined)."""
    t, m, l = shape
    n = (l - p) * t
    underdetermined = n < m * p
    if underdetermined:
        return _msge_with_gradient_underdetermined
    else:
        return _msge_with_gradient_overdetermined

def _get_msge_with_gradient(data, delta, xvschema, skipstep, p):
    """Calculate mean squared generalization error and its gradient,
    automatically selecting the best function."""
    t, m, l = data.shape
    n = (l - p) * t
    underdetermined = n < m * p
    if underdetermined:
        return _msge_with_gradient_underdetermined(data, delta, xvschema, skipstep, p)
    else:
        return _msge_with_gradient_overdetermined(data, delta, xvschema, skipstep, p)

def get_type_name(t):
    """Get a human-friendly name for the given type.

    :type t: type|None
    :rtype: unicode"""
    try:
        return __type_names[t]
    except KeyError:
        if issubclass(t, six.integer_types):
            return _(u'Integer number')
        return six.text_type(t.__name__).capitalize()

def get_callable_name(c):
    """Get a human-friendly name for the given callable.

    :param c: The callable to get the name for
    :type c: callable
    :rtype: unicode"""
    if hasattr(c, 'name'):
        return six.text_type(c.name)
    elif hasattr(c, '__name__'):
        return six.text_type(c.__name__) + u'()'
    else:
        return six.text_type(c)

def get_primitive_name(schema):
    """Get a human-friendly name for the given primitive.

    :param schema: Schema
    :type schema: *
    :rtype: unicode"""
    try:
        return {const.COMPILED_TYPE.LITERAL: six.text_type, const.COMPILED_TYPE.TYPE: get_type_name, const.COMPILED_TYPE.ENUM: get_type_name, const.COMPILED_TYPE.CALLABLE: get_callable_name, const.COMPILED_TYPE.ITERABLE: lambda x: _(u'{type}[{content}]').format(type=get_type_name(list), content=_(u'...') if x else _(u'-')), const.COMPILED_TYPE.MAPPING: lambda x: _(u'{type}[{content}]').format(type=get_type_name(dict), content=_(u'...') if x else _(u'-'))}[primitive_type(schema)](schema)
    except KeyError:
        return six.text_type(repr(schema))

def primitive_type(schema):
    """Get schema type for the primitive argument.

    Note: it does treats markers & schemas as callables!

    :param schema: Value of a primitive type
    :type schema: *
    :return: const.COMPILED_TYPE.*
    :rtype: str|None"""
    schema_type = type(schema)
    if schema_type in const.literal_types:
        return const.COMPILED_TYPE.LITERAL
    elif Enum is not None and isinstance(schema, (EnumMeta, Enum)):
        return const.COMPILED_TYPE.ENUM
    elif issubclass(schema_type, six.class_types):
        return const.COMPILED_TYPE.TYPE
    elif isinstance(schema, collections.Mapping):
        return const.COMPILED_TYPE.MAPPING
    elif isinstance(schema, collections.Iterable):
        return const.COMPILED_TYPE.ITERABLE
    elif callable(schema):
        return const.COMPILED_TYPE.CALLABLE
    else:
        return None

def commajoin_as_strings(iterable):
    """Join the given iterable with ','"""
    return _(u',').join((six.text_type(i) for i in iterable))

def parallel_loop(func, n_jobs=1, verbose=1):
    """run loops in parallel, if joblib is available.

    Parameters
    ----------
    func : function
        function to be executed in parallel
    n_jobs : int | None
        Number of jobs. If set to None, do not attempt to use joblib.
    verbose : int
        verbosity level

    Notes
    -----
    Execution of the main script must be guarded with `if __name__ == '__main__':` when using parallelization."""
    if n_jobs:
        try:
            from joblib import Parallel, delayed
        except ImportError:
            try:
                from sklearn.externals.joblib import Parallel, delayed
            except ImportError:
                n_jobs = None
    if not n_jobs:
        if verbose:
            print('running ', func, ' serially')
        par = lambda x: list(x)
    else:
        if verbose:
            print('running ', func, ' in parallel')
        func = delayed(func)
        par = Parallel(n_jobs=n_jobs, verbose=verbose)
    return (par, func)

def _convert_errors(func):
    """Decorator to convert throws errors to Voluptuous format."""
    cast_Invalid = lambda e: Invalid(u'{message}, expected {expected}'.format(message=e.message, expected=e.expected) if e.expected != u'-none-' else e.message, e.path, six.text_type(e))
    @wraps(func)
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except good.SchemaError as e:
            raise SchemaError(six.text_type(e))
        except good.MultipleInvalid as ee:
            raise MultipleInvalid([cast_Invalid(e) for e in ee])
        except good.Invalid as e:
            raise MultipleInvalid([cast_Invalid(e)])
    return wrapper

def smart_init_mapping(candidate_mapping, instance1, instance2):
    """Initialize mapping based on the concept mapping (smart initialization)
    Arguments:
        candidate_mapping: candidate node match list
        instance1: instance triples of AMR 1
        instance2: instance triples of AMR 2
    Returns:
        initialized node mapping between two AMRs"""
    random.seed()
    matched_dict = {}
    result = []
    no_word_match = []
    for i, candidates in enumerate(candidate_mapping):
        if not candidates:
            result.append(-1)
            continue
        value1 = instance1[i][2]
        for node_index in candidates:
            value2 = instance2[node_index][2]
            if value1 == value2:
                if node_index not in matched_dict:
                    result.append(node_index)
                    matched_dict[node_index] = 1
                    break
        if len(result) == i:
            no_word_match.append(i)
            result.append(-1)
    for i in no_word_match:
        candidates = list(candidate_mapping[i])
        while candidates:
            rid = random.randint(0, len(candidates) - 1)
            candidate = candidates[rid]
            if candidate in matched_dict:
                candidates.pop(rid)
            else:
                matched_dict[candidate] = 1
                result[i] = candidate
                break
    return result

def move_gain(mapping, node_id, old_id, new_id, weight_dict, match_num):
    """Compute the triple match number gain from the move operation
    Arguments:
        mapping: current node mapping
        node_id: remapped node in AMR 1
        old_id: original node id in AMR 2 to which node_id is mapped
        new_id: new node in to which node_id is mapped
        weight_dict: weight dictionary
        match_num: the original triple matching number
    Returns:
        the triple match gain number (might be negative)"""
    new_mapping = (node_id, new_id)
    old_mapping = (node_id, old_id)
    new_mapping_list = mapping[:]
    new_mapping_list[node_id] = new_id
    if tuple(new_mapping_list) in match_triple_dict:
        return match_triple_dict[tuple(new_mapping_list)] - match_num
    gain = 0
    if new_mapping in weight_dict:
        for key in weight_dict[new_mapping]:
            if key == -1:
                gain += weight_dict[new_mapping][-1]
            elif new_mapping_list[key[0]] == key[1]:
                gain += weight_dict[new_mapping][key]
    if old_mapping in weight_dict:
        for k in weight_dict[old_mapping]:
            if k == -1:
                gain -= weight_dict[old_mapping][-1]
            elif mapping[k[0]] == k[1]:
                gain -= weight_dict[old_mapping][k]
    match_triple_dict[tuple(new_mapping_list)] = match_num + gain
    return gain

def print_alignment(mapping, instance1, instance2):
    """print the alignment based on a node mapping
    Args:
        mapping: current node mapping list
        instance1: nodes of AMR 1
        instance2: nodes of AMR 2"""
    result = []
    for instance1_item, m in zip(instance1, mapping):
        r = instance1_item[1] + '(' + instance1_item[2] + ')'
        if m == -1:
            r += '-Null'
        else:
            instance2_item = instance2[m]
            r += '-' + instance2_item[1] + '(' + instance2_item[2] + ')'
        result.append(r)
    return ' '.join(result)

def compute_f(match_num, test_num, gold_num):
    """Compute the f-score based on the matching triple number,
                                 triple number of AMR set 1,
                                 triple number of AMR set 2
    Args:
        match_num: matching triple number
        test_num:  triple number of AMR 1 (test file)
        gold_num:  triple number of AMR 2 (gold file)
    Returns:
        precision: match_num/test_num
        recall: match_num/gold_num
        f_score: 2*precision*recall/(precision+recall)"""
    if test_num == 0 or gold_num == 0:
        return (0.0, 0.0, 0.0)
    precision = float(match_num) / float(test_num)
    recall = float(match_num) / float(gold_num)
    if precision + recall != 0:
        f_score = 2 * precision * recall / (precision + recall)
        if veryVerbose:
            print('F-score:', f_score, file=DEBUG_LOG)
        return (precision, recall, f_score)
    else:
        if veryVerbose:
            print('F-score:', '0.0', file=DEBUG_LOG)
        return (precision, recall, 0.0)

def generate_amr_lines(f1, f2):
    """Read one AMR line at a time from each file handle
    :param f1: file handle (or any iterable of strings) to read AMR 1 lines from
    :param f2: file handle (or any iterable of strings) to read AMR 2 lines from
    :return: generator of cur_amr1, cur_amr2 pairs: one-line AMR strings"""
    while True:
        cur_amr1 = amr.AMR.get_amr_line(f1)
        cur_amr2 = amr.AMR.get_amr_line(f2)
        if not cur_amr1 and (not cur_amr2):
            pass
        elif not cur_amr1:
            print('Error: File 1 has less AMRs than file 2', file=ERROR_LOG)
            print('Ignoring remaining AMRs', file=ERROR_LOG)
        elif not cur_amr2:
            print('Error: File 2 has less AMRs than file 1', file=ERROR_LOG)
            print('Ignoring remaining AMRs', file=ERROR_LOG)
        else:
            yield (cur_amr1, cur_amr2)
            continue
        break

def _get_string(data, position, obj_end, dummy):
    """Decode a BSON string to python unicode string."""
    length = _UNPACK_INT(data[position:position + 4])[0]
    position += 4
    if length < 1 or obj_end - position < length:
        raise InvalidBSON('invalid string length')
    end = position + length - 1
    if data[end:end + 1] != b'\x00':
        raise InvalidBSON('invalid end of string')
    return (_utf_8_decode(data[position:end], None, True)[0], end + 1)

def _get_object(data, position, obj_end, opts):
    """Decode a BSON subdocument to opts.document_class or bson.dbref.DBRef."""
    obj_size = _UNPACK_INT(data[position:position + 4])[0]
    end = position + obj_size - 1
    if data[end:position + obj_size] != b'\x00':
        raise InvalidBSON('bad eoo')
    if end >= obj_end:
        raise InvalidBSON('invalid object length')
    obj = _elements_to_dict(data, position + 4, end, opts, subdocument=True)
    position += obj_size
    if '$ref' in obj:
        return (DBRef(obj.pop('$ref'), obj.pop('$id', None), obj.pop('$db', None), obj), position)
    return (obj, position)

def _get_boolean(data, position, dummy0, dummy1):
    """Decode a BSON true/false to python True/False."""
    end = position + 1
    return (data[position:end] == b'\x01', end)

def _get_date(data, position, dummy, opts):
    """Decode a BSON datetime to python datetime.datetime."""
    end = position + 8
    millis = _UNPACK_LONG(data[position:end])[0]
    diff = (millis % 1000 + 1000) % 1000
    seconds = (millis - diff) / 1000
    micros = diff * 1000
    if opts.tz_aware:
        return (EPOCH_AWARE + datetime.timedelta(seconds=seconds, microseconds=micros), end)
    else:
        return (EPOCH_NAIVE + datetime.timedelta(seconds=seconds, microseconds=micros), end)

def _get_regex(data, position, dummy0, dummy1):
    """Decode a BSON regex to bson.regex.Regex or a python pattern object."""
    pattern, position = _get_c_string(data, position)
    bson_flags, position = _get_c_string(data, position)
    bson_re = Regex(pattern, bson_flags)
    return (bson_re, position)

def _elements_to_dict(data, position, obj_end, opts, subdocument=None):
    """Decode a BSON document."""
    if type(opts.document_class) == tuple:
        result = opts.document_class[0](**opts.document_class[1]) if not subdocument else dict()
    else:
        result = opts.document_class() if not subdocument else dict()
    end = obj_end - 1
    while position < end:
        key, value, position = _element_to_dict(data, position, obj_end, opts)
        result[key] = value
    return result

def _bson_to_dict(data, opts):
    """Decode a BSON string to document_class."""
    try:
        obj_size = _UNPACK_INT(data[:4])[0]
    except struct.error as exc:
        raise InvalidBSON(str(exc))
    if obj_size != len(data):
        raise InvalidBSON('invalid object size')
    if data[obj_size - 1:obj_size] != b'\x00':
        raise InvalidBSON('bad eoo')
    try:
        return _elements_to_dict(data, 4, obj_size - 1, opts)
    except InvalidBSON:
        raise
    except Exception:
        _, exc_value, exc_tb = sys.exc_info()
        reraise(InvalidBSON, exc_value, exc_tb)

def _encode_datetime(name, value, dummy0, dummy1):
    """Encode datetime.datetime."""
    if value.utcoffset() is not None:
        value = value - value.utcoffset()
    millis = int(calendar.timegm(value.timetuple()) * 1000 + value.microsecond / 1000)
    return b'\t' + name + _PACK_LONG(millis)

def _param_fields(kwargs, fields):
    """Normalize the "fields" argument to most find methods"""
    if fields is None:
        return
    if type(fields) in [list, set, frozenset, tuple]:
        fields = {x: True for x in fields}
    if type(fields) == dict:
        fields.setdefault('_id', False)
    kwargs['projection'] = fields

def find_method(func):
    """Decorator that manages smart defaults or transforms for common find methods:

     - fields/projection: list of fields to be returned. Contrary to pymongo, _id won't be added automatically
     - json: performs a json_clone on the results. Beware of performance!
     - timeout
     - return_document"""
    def wrapped(*args, **kwargs):
        if len(args) == 3 and func.__name__ in ('find', 'find_one', 'find_by_id', 'find_by_ids'):
            _param_fields(kwargs, args[2])
            args = (args[0], args[1])
        elif 'fields' in kwargs:
            _param_fields(kwargs, kwargs['fields'])
            del kwargs['fields']
        elif 'projection' in kwargs:
            _param_fields(kwargs, kwargs['projection'])
        if 'timeout' in kwargs:
            kwargs['no_cursor_timeout'] = not bool(kwargs['timeout'])
            del kwargs['timeout']
        if 'spec' in kwargs:
            kwargs['filter'] = kwargs['spec']
            del kwargs['spec']
        if kwargs.get('return_document') == 'after':
            kwargs['return_document'] = ReturnDocument.AFTER
        elif kwargs.get('return_document') == 'before':
            kwargs['return_document'] = ReturnDocument.BEFORE
        ret = func(*args, **kwargs)
        if kwargs.get('json'):
            ret = json_clone(ret)
        return ret
    return wrapped

def patch_cursor(cursor, batch_size=None, limit=None, skip=None, sort=None, **kwargs):
    """Adds batch_size, limit, sort parameters to a DB cursor"""
    if type(batch_size) == int:
        cursor.batch_size(batch_size)
    if limit is not None:
        cursor.limit(limit)
    if sort is not None:
        cursor.sort(sort)
    if skip is not None:
        cursor.skip(skip)

def get_names(file_dir, files):
    """ Get the annotator name list based on a list of files
     Args:
     file_dir: AMR file folder
     files: a list of AMR names, e.g. nw_wsj_0001_1

     Returns:
    a list of user names who annotate all the files
    """
    total_list = []
    name_list = []
    get_sub = False
    for path, subdir, dir_files in os.walk(file_dir):
        if not get_sub:
            total_list = subdir[:]
            get_sub = True
        else:
            break
    for user in total_list:
        has_file = True
        for f in files:
            file_path = file_dir + user + '/' + f + '.txt'
            if not os.path.exists(file_path):
                has_file = False
                break
        if has_file:
            name_list.append(user)
    if len(name_list) == 0:
        print('********Error: Cannot find any user who completes the files*************', file=ERROR_LOG)
    return name_list

def pprint_table(table):
    """Print a table in pretty format"""
    col_paddings = []
    for i in range(len(table[0])):
        col_paddings.append(get_max_width(table, i))
    for row in table:
        print(row[0].ljust(col_paddings[0] + 1), end='')
        for i in range(1, len(row)):
            col = str(row[i]).rjust(col_paddings[i] + 2)
            print(col, end='')
        print('\n')

def cb(option, value, parser):
    """Callback function to handle variable number of arguments in optparse"""
    arguments = [value]
    for arg in parser.rargs:
        if arg[0] != '-':
            arguments.append(arg)
        else:
            del parser.rargs[:len(arguments)]
            break
    if getattr(parser.values, option.dest):
        arguments.extend(getattr(parser.values, option.dest))
    setattr(parser.values, option.dest, arguments)

def _flatten_fetched_fields(fields_arg):
    """this method takes either a kwargs 'fields', which can be a dict :
    {"_id": False, "store": 1, "url": 1} or a list : ["store", "flag", "url"]
    and returns a tuple : ("store", "flag").
    it HAS to be a tuple, so that it is not updated by the different instances"""
    if fields_arg is None:
        return None
    if isinstance(fields_arg, dict):
        return tuple(sorted([k for k in list(fields_arg.keys()) if fields_arg[k]]))
    else:
        return tuple(sorted(fields_arg))

def safe_import_module(path, default=None):
    """Try to import the specified module from the given Python path

    @path is a string containing a Python path to the wanted module, @default is
    an object to return if import fails, it can be None, a callable or whatever you need.

    Return a object or None"""
    if path is None:
        return default
    dot = path.rindex('.')
    module_name = path[:dot]
    class_name = path[dot + 1:]
    try:
        _class = getattr(import_module(module_name), class_name)
        return _class
    except (ImportError, AttributeError) as e:
        raise FeedparserError('{}: {}'.format(e.__class__.__name__, e.message))
    return default

def undecorated(o):
    """Remove all decorators from a function, method or class"""
    if type(o) is type:
        return o
    try:
        closure = o.func_closure
    except AttributeError:
        pass
    try:
        closure = o.__closure__
    except AttributeError:
        return
    if closure:
        for cell in closure:
            if cell.cell_contents is o:
                continue
            if looks_like_a_decorator(cell.cell_contents):
                undecd = undecorated(cell.cell_contents)
                if undecd:
                    return undecd
        else:
            return o
    else:
        return o

def _make_destination_callable(dest):
    """Creates a callable out of the destination. If it's already callable,
    the destination is returned. Instead, if the object is a string or a
    writable object, it's wrapped in a closure to be used later."""
    if callable(dest):
        return dest
    elif hasattr(dest, 'write') or isinstance(dest, string_types):
        return _use_filehandle_to_save(dest)
    else:
        raise TypeError('Destination must be a string, writable or callable object.')

