def retry(f, exc_classes=DEFAULT_EXC_CLASSES, logger=None, retry_log_level=logging.INFO, retry_log_message="Connection broken in '{f}' (error: '{e}'); retrying with new connection.", max_failures=None, interval=0, max_failure_log_level=logging.ERROR, max_failure_log_message="Max retries reached for '{f}'. Aborting."):
    """Decorator to automatically reexecute a function if the connection is
    broken for any reason."""
    exc_classes = tuple(exc_classes)
    @wraps(f)
    def deco(*args, **kwargs):
        failures = 0
        while True:
            try:
                return f(*args, **kwargs)
            except exc_classes as e:
                if logger is not None:
                    logger.log(retry_log_level, retry_log_message.format(f=f.func_name, e=e))
                gevent.sleep(interval)
                failures += 1
                if max_failures is not None and failures > max_failures:
                    if logger is not None:
                        logger.log(max_failure_log_level, max_failure_log_message.format(f=f.func_name, e=e))
                    raise
    return deco

def eff_default_transformer(fills=EFF_DEFAULT_FILLS):
    """Return a simple transformer function for parsing EFF annotations. N.B.,
    ignores all but the first effect."""
    def _transformer(vals):
        if len(vals) == 0:
            return fills
        else:
            match_eff_main = _prog_eff_main.match(vals[0])
            if match_eff_main is None:
                logging.warning('match_eff_main is None: vals={}'.format(str(vals[0])))
                return fills
            eff = [match_eff_main.group(1)] + match_eff_main.group(2).split(b'|')
            result = tuple((fill if v == b'' else int(v) if i == 5 or i == 10 else (1 if v == b'CODING' else 0) if i == 8 else v for i, (v, fill) in enumerate(list(zip(eff, fills))[:11])))
            return result
    return _transformer

def ann_default_transformer(fills=ANN_DEFAULT_FILLS):
    """Return a simple transformer function for parsing ANN annotations. N.B.,
    ignores all but the first effect."""
    def _transformer(vals):
        if len(vals) == 0:
            return fills
        else:
            ann = vals[0].split(b'|')
            ann = ann[:11] + _ann_split2(ann[11]) + _ann_split2(ann[12]) + _ann_split2(ann[13]) + ann[14:]
            result = tuple((fill if v == b'' else int(v.partition(b'/')[0]) if i == 8 else int(v) if 11 <= i < 18 else v for i, (v, fill) in enumerate(list(zip(ann, fills))[:18])))
            return result
    return _transformer

def overload(func):
    """May be used as a shortcut for ``overloaded`` and ``overloads(f)``
    when the overloaded function `f` can be automatically identified."""
    if sys.version_info < (3, 3):
        raise OverloadingError("The 'overload' syntax requires Python version 3.3 or higher.")
    fn = unwrap(func)
    ensure_function(fn)
    fname = get_full_name(fn)
    if fname.find('<locals>') >= 0:
        raise OverloadingError("The 'overload' syntax cannot be used with nested functions. Decorators must use functools.wraps().")
    try:
        return register(__registry[fname], func)
    except KeyError:
        __registry[fname] = overloaded(func)
        return __registry[fname]

def normalize_type(type_, level=0):
    """Reduces an arbitrarily complex type declaration into something manageable."""
    if not typing or not isinstance(type_, typing.TypingMeta) or type_ is AnyType:
        return type_
    if isinstance(type_, typing.TypeVar):
        if type_.__constraints__ or type_.__bound__:
            return type_
        else:
            return AnyType
    if issubclass(type_, typing.Union):
        if not type_.__union_params__:
            raise OverloadingError('typing.Union must be parameterized')
        return typing.Union[tuple((normalize_type(t, level) for t in type_.__union_params__))]
    if issubclass(type_, typing.Tuple):
        params = type_.__tuple_params__
        if level > 0 or params is None:
            return typing.Tuple
        elif type_.__tuple_use_ellipsis__:
            return typing.Tuple[normalize_type(params[0], level + 1), ...]
        else:
            return typing.Tuple[tuple((normalize_type(t, level + 1) for t in params))]
    if issubclass(type_, typing.Callable):
        return typing.Callable
    if isinstance(type_, typing.GenericMeta):
        base = find_base_generic(type_)
        if base is typing.Generic:
            return type_
        else:
            return GenericWrapper(type_, base, level > 0)
    raise OverloadingError('%r not supported yet' % type_)

def type_complexity(type_):
    """Computes an indicator for the complexity of `type_`.

    If the return value is 0, the supplied type is not parameterizable.
    Otherwise, set bits in the return value denote the following features:
    - bit 0: The type could be parameterized but is not.
    - bit 1: The type represents an iterable container with 1 constrained type parameter.
    - bit 2: The type represents a mapping with a constrained value type (2 parameters).
    - bit 3: The type represents an n-tuple (n parameters).
    Since these features are mutually exclusive, only a `Union` can have more than one bit set."""
    if not typing or not isinstance(type_, (typing.TypingMeta, GenericWrapperMeta)) or type_ is AnyType:
        return 0
    if issubclass(type_, typing.Union):
        return reduce(operator.or_, map(type_complexity, type_.__union_params__))
    if issubclass(type_, typing.Tuple):
        if type_.__tuple_params__ is None:
            return 1
        elif type_.__tuple_use_ellipsis__:
            return 2
        else:
            return 8
    if isinstance(type_, GenericWrapperMeta):
        type_count = 0
        for p in reversed(type_.parameters):
            if type_count > 0:
                type_count += 1
            if p is AnyType:
                continue
            if not isinstance(p, typing.TypeVar) or p.__constraints__ or p.__bound__:
                type_count += 1
        return 1 << min(type_count, 2)
    return 0

def find_base_generic(type_):
    """Locates the underlying generic whose structure and behavior are known.

    For example, the base generic of a type that inherits from `typing.Mapping[T, int]`
    is `typing.Mapping`."""
    for t in type_.__mro__:
        if t.__module__ == typing.__name__:
            return first_origin(t)

def sig_cmp(sig1, sig2):
    """Compares two normalized type signatures for validation purposes."""
    types1 = sig1.required
    types2 = sig2.required
    if len(types1) != len(types2):
        return False
    dup_pos = []
    dup_kw = {}
    for t1, t2 in zip(types1, types2):
        match = type_cmp(t1, t2)
        if match:
            dup_pos.append(match)
        else:
            break
    else:
        return tuple(dup_pos)
    kw_range = slice(len(dup_pos), len(types1))
    kwds1 = sig1.parameters[kw_range]
    kwds2 = sig2.parameters[kw_range]
    if set(kwds1) != set(kwds2):
        return False
    kwtypes1 = dict(zip(sig1.parameters, types1))
    kwtypes2 = dict(zip(sig2.parameters, types2))
    for kw in kwds1:
        match = type_cmp(kwtypes1[kw], kwtypes2[kw])
        if match:
            dup_kw[kw] = match
        else:
            break
    else:
        return (tuple(dup_pos), dup_kw)
    return False

def is_void(func):
    """Determines if a function is a void function, i.e., one whose body contains
    nothing but a docstring or an ellipsis. A void function can be used to introduce
    an overloaded function without actually registering an implementation."""
    try:
        source = dedent(inspect.getsource(func))
    except (OSError, IOError):
        return False
    fdef = next(ast.iter_child_nodes(ast.parse(source)))
    return type(fdef) is ast.FunctionDef and len(fdef.body) == 1 and (type(fdef.body[0]) is ast.Expr) and (type(fdef.body[0].value) in {ast.Str, ast.Ellipsis})

def update_docstring(dispatcher, func=None):
    """Inserts a call signature at the beginning of the docstring on `dispatcher`.
    The signature is taken from `func` if provided; otherwise `(...)` is used."""
    doc = dispatcher.__doc__ or ''
    if inspect.cleandoc(doc).startswith('%s(' % dispatcher.__name__):
        return
    sig = '(...)'
    if func and func.__code__.co_argcount:
        argspec = inspect.getfullargspec(func)
        if argspec.args and argspec.args[0] in {'self', 'cls'}:
            argspec.args.pop(0)
        if any(argspec):
            sig = inspect.formatargspec(*argspec)
            sig = re.sub(' at 0x[0-9a-f]{8,16}(?=>)', '', sig)
    sep = '\n' if doc.startswith('\n') else '\n\n'
    dispatcher.__doc__ = dispatcher.__name__ + sig + sep + doc

def _filenames_from_arg(filename):
    """Utility function to deal with polymorphic filenames argument."""
    if isinstance(filename, string_types):
        filenames = [filename]
    elif isinstance(filename, (list, tuple)):
        filenames = filename
    else:
        raise Exception('filename argument must be string, list or tuple')
    for fn in filenames:
        if not os.path.exists(fn):
            raise ValueError('file not found: %s' % fn)
        if not os.path.isfile(fn):
            raise ValueError('not a file: %s' % fn)
    return filenames

def _mk_cache_fn(vcf_fn, array_type, region=None, cachedir=None, compress=False):
    """Utility function to construct a filename for a cache file, given a VCF
    file name (where the original data came from) and other parameters."""
    if cachedir is None:
        cachedir = vcf_fn + config.CACHEDIR_SUFFIX
    if not os.path.exists(cachedir):
        os.makedirs(cachedir)
    else:
        assert os.path.isdir(cachedir), 'unexpected error, cache directory is not a directory: %r' % cachedir
    if compress:
        suffix = 'npz'
    else:
        suffix = 'npy'
    if region is None:
        cache_fn = os.path.join(cachedir, '%s.%s' % (array_type, suffix))
    else:
        region = region.replace(':', '__').replace('-', '_')
        cache_fn = os.path.join(cachedir, '%s.%s.%s' % (array_type, region, suffix))
    return cache_fn

def _get_cache(vcf_fn, array_type, region, cachedir, compress, log):
    """Utility function to obtain a cache file name and determine whether or
    not a fresh cache file is available."""
    if isinstance(vcf_fn, (list, tuple)):
        raise Exception('caching only supported when loading from a single VCF file')
    cache_fn = _mk_cache_fn(vcf_fn, array_type=array_type, region=region, cachedir=cachedir, compress=compress)
    if not os.path.exists(cache_fn):
        log('no cache file found')
        is_cached = False
    elif os.path.getmtime(vcf_fn) > os.path.getmtime(cache_fn):
        is_cached = False
        log('cache file out of date')
    else:
        is_cached = True
        log('cache file available')
    return (cache_fn, is_cached)

def _variants_fields(fields, exclude_fields, info_ids):
    """Utility function to determine which fields to extract when loading
    variants."""
    if fields is None:
        fields = config.STANDARD_VARIANT_FIELDS + info_ids
    else:
        for f in fields:
            if f not in config.STANDARD_VARIANT_FIELDS and f not in info_ids:
                print('WARNING: no INFO definition found for field %s' % f, file=sys.stderr)
    if exclude_fields is not None:
        fields = [f for f in fields if f not in exclude_fields]
    return tuple((f for f in fields))

def _variants_arities(fields, arities, info_counts):
    """Utility function to determine arities (i.e., number of values to
    expect) for variants fields."""
    if arities is None:
        arities = dict()
    for f, vcf_count in zip(fields, info_counts):
        if f == 'FILTER':
            arities[f] = 1
        elif f not in arities:
            if f in config.STANDARD_VARIANT_FIELDS:
                arities[f] = config.DEFAULT_VARIANT_ARITY[f]
            elif vcf_count == NUMBER_ALLELE:
                arities[f] = 1
            elif vcf_count <= 0:
                arities[f] = 1
            else:
                arities[f] = vcf_count
    arities = tuple((arities[f] for f in fields))
    return arities

def _variants_fills(fields, fills, info_types):
    """Utility function to determine fill values for variants fields with
    missing values."""
    if fills is None:
        fills = dict()
    for f, vcf_type in zip(fields, info_types):
        if f == 'FILTER':
            fills[f] = False
        elif f not in fills:
            if f in config.STANDARD_VARIANT_FIELDS:
                fills[f] = config.DEFAULT_VARIANT_FILL[f]
            else:
                fills[f] = config.DEFAULT_FILL_MAP[vcf_type]
    fills = tuple((fills[f] for f in fields))
    return fills

def _info_transformers(fields, transformers):
    """Utility function to determine transformer functions for variants
    fields."""
    if transformers is None:
        transformers = dict()
    for f in fields:
        if f not in transformers:
            transformers[f] = config.DEFAULT_TRANSFORMER.get(f, None)
    return tuple((transformers[f] for f in fields))

def _variants_dtype(fields, dtypes, arities, filter_ids, flatten_filter, info_types):
    """Utility function to build a numpy dtype for a variants array,
    given user arguments and information available from VCF header."""
    dtype = list()
    for f, n, vcf_type in zip(fields, arities, info_types):
        if f == 'FILTER' and flatten_filter:
            for flt in filter_ids:
                nm = 'FILTER_' + flt
                dtype.append((nm, 'b1'))
        elif f == 'FILTER' and (not flatten_filter):
            t = [(flt, 'b1') for flt in filter_ids]
            dtype.append((f, t))
        else:
            if dtypes is not None and f in dtypes:
                t = dtypes[f]
            elif f in config.STANDARD_VARIANT_FIELDS:
                t = config.DEFAULT_VARIANT_DTYPE[f]
            elif f in config.DEFAULT_INFO_DTYPE:
                t = config.DEFAULT_INFO_DTYPE[f]
            else:
                t = config.DEFAULT_TYPE_MAP[vcf_type]
            if n == 1:
                dtype.append((f, t))
            else:
                dtype.append((f, t, (n,)))
    return dtype

def _fromiter(it, dtype, count, progress, log):
    """Utility function to load an array from an iterator."""
    if progress > 0:
        it = _iter_withprogress(it, progress, log)
    if count is not None:
        a = np.fromiter(it, dtype=dtype, count=count)
    else:
        a = np.fromiter(it, dtype=dtype)
    return a

def _calldata_fields(fields, exclude_fields, format_ids):
    """Utility function to determine which calldata (i.e., FORMAT) fields to
    extract."""
    if fields is None:
        fields = config.STANDARD_CALLDATA_FIELDS + format_ids
    else:
        for f in fields:
            if f not in config.STANDARD_CALLDATA_FIELDS and f not in format_ids:
                print('WARNING: no definition found for field %s' % f, file=sys.stderr)
    if exclude_fields is not None:
        fields = [f for f in fields if f not in exclude_fields]
    return tuple(fields)

def __replace_all(repls: dict, input: str) -> str:
    """Replaces from a string **input** all the occurrences of some
    symbols according to mapping **repls**.

    :param dict repls: where #key is the old character and
    #value is the one to substitute with;
    :param str input: original string where to apply the
    replacements;
    :return: *(str)* the string with the desired characters replaced"""
    return re.sub('|'.join((re.escape(key) for key in repls.keys())), lambda k: repls[k.group(0)], input)

def dfa_json_importer(input_file: str) -> dict:
    """Imports a DFA from a JSON file.

    :param str input_file: path + filename to json file;
    :return: *(dict)* representing a DFA."""
    file = open(input_file)
    json_file = json.load(file)
    transitions = {}
    for origin, action, destination in json_file['transitions']:
        transitions[origin, action] = destination
    dfa = {'alphabet': set(json_file['alphabet']), 'states': set(json_file['states']), 'initial_state': json_file['initial_state'], 'accepting_states': set(json_file['accepting_states']), 'transitions': transitions}
    return dfa

def dfa_to_json(dfa: dict, name: str, path: str='./'):
    """Exports a DFA to a JSON file.

    If *path* do not exists, it will be created.

    :param dict dfa: DFA to export;
    :param str name: name of the output file;
    :param str path: path where to save the JSON file (default:
                     working directory)"""
    out = {'alphabet': list(dfa['alphabet']), 'states': list(dfa['states']), 'initial_state': dfa['initial_state'], 'accepting_states': list(dfa['accepting_states']), 'transitions': list()}
    for t in dfa['transitions']:
        out['transitions'].append([t[0], t[1], dfa['transitions'][t]])
    if not os.path.exists(path):
        os.makedirs(path)
    file = open(os.path.join(path, name + '.json'), 'w')
    json.dump(out, file, sort_keys=True, indent=4)
    file.close()

def dfa_to_dot(dfa: dict, name: str, path: str='./'):
    """Generates a DOT file and a relative SVG image in **path**
    folder of the input DFA using graphviz library.

    :param dict dfa: DFA to export;
    :param str name: name of the output file;
    :param str path: path where to save the DOT/SVG files (default:
                     working directory)"""
    g = graphviz.Digraph(format='svg')
    g.node('fake', style='invisible')
    for state in dfa['states']:
        if state == dfa['initial_state']:
            if state in dfa['accepting_states']:
                g.node(str(state), root='true', shape='doublecircle')
            else:
                g.node(str(state), root='true')
        elif state in dfa['accepting_states']:
            g.node(str(state), shape='doublecircle')
        else:
            g.node(str(state))
    g.edge('fake', str(dfa['initial_state']), style='bold')
    for transition in dfa['transitions']:
        g.edge(str(transition[0]), str(dfa['transitions'][transition]), label=transition[1])
    if not os.path.exists(path):
        os.makedirs(path)
    g.render(filename=os.path.join(path, name + '.dot'))

def nfa_json_importer(input_file: str) -> dict:
    """Imports a NFA from a JSON file.

    :param str input_file: path+filename to JSON file;
    :return: *(dict)* representing a NFA."""
    file = open(input_file)
    json_file = json.load(file)
    transitions = {}
    for p in json_file['transitions']:
        transitions.setdefault((p[0], p[1]), set()).add(p[2])
    nfa = {'alphabet': set(json_file['alphabet']), 'states': set(json_file['states']), 'initial_states': set(json_file['initial_states']), 'accepting_states': set(json_file['accepting_states']), 'transitions': transitions}
