                     working directory)."""
    transitions = list()
    for p in nfa['transitions']:
        for dest in nfa['transitions'][p]:
            transitions.append([p[0], p[1], dest])
    out = {'alphabet': list(nfa['alphabet']), 'states': list(nfa['states']), 'initial_states': list(nfa['initial_states']), 'accepting_states': list(nfa['accepting_states']), 'transitions': transitions}
