def get_forwarders(resolv='resolv.conf'):
    """Find the forwarders in /etc/resolv.conf, default to 8.8.8.8 and
    8.8.4.4"""
    ns = []
    if os.path.exists(resolv):
        for l in open(resolv):
            if l.startswith('nameserver'):
                address = l.strip().split(' ', 2)[1]
                if not address.startswith('127'):
                    ns.append(address)
    if not ns:
        ns = ['8.8.8.8', '8.8.4.4']
    return ns

def format_code(source, preferred_quote="'"):
    """Return source code with quotes unified."""
    try:
        return _format_code(source, preferred_quote)
    except (tokenize.TokenError, IndentationError):
        return source

def _format_code(source, preferred_quote):
    """Return source code with quotes unified."""
    if not source:
        return source
    modified_tokens = []
    sio = io.StringIO(source)
    for token_type, token_string, start, end, line in tokenize.generate_tokens(sio.readline):
        if token_type == tokenize.STRING:
            token_string = unify_quotes(token_string, preferred_quote=preferred_quote)
        modified_tokens.append((token_type, token_string, start, end, line))
    return untokenize.untokenize(modified_tokens)

def unify_quotes(token_string, preferred_quote):
    """Return string with quotes changed to preferred_quote if possible."""
    bad_quote = {'"': "'", "'": '"'}[preferred_quote]
    allowed_starts = {'': bad_quote, 'f': 'f' + bad_quote, 'b': 'b' + bad_quote}
    if not any((token_string.startswith(start) for start in allowed_starts.values())):
        return token_string
    if token_string.count(bad_quote) != 2:
        return token_string
    if preferred_quote in token_string:
        return token_string
    assert token_string.endswith(bad_quote)
    assert len(token_string) >= 2
    for prefix, start in allowed_starts.items():
        if token_string.startswith(start):
            chars_to_strip_from_front = len(start)
            return '{prefix}{preferred_quote}{token}{preferred_quote}'.format(prefix=prefix, preferred_quote=preferred_quote, token=token_string[chars_to_strip_from_front:-1])

def open_with_encoding(filename, encoding, mode='r'):
    """Return opened file with a specific encoding."""
