def run(command, **kw):
    """Run `command`, catch any exception, and return lines of output."""
    if sys.platform == 'win32':
        _cwd = kw.get('cwd', None)
        if _cwd is not None:
            kw['cwd'] = _cwd.decode()
    try:
        return check_output(command, **kw).splitlines()
    except CalledProcessError:
        return ()
    except FileNotFoundError:
        print('The {} binary was not found. Skipping directory {}.\n'.format(command[0], kw['cwd'].decode('UTF-8')))
        return ()

def find_repositories_with_locate(path):
    """Use locate to return a sequence of (directory, dotdir) pairs."""
    command = [b'locate', b'-0']
    for dotdir in DOTDIRS:
        command.append(b'%s\\/%s' % (escape(path), escape(dotdir)))
        command.append(b'%s\\/*/%s' % (escape(path), escape(dotdir)))
    try:
        paths = check_output(command).strip(b'\x00').split(b'\x00')
    except CalledProcessError:
        return []
    return [os.path.split(p) for p in paths if not os.path.islink(p) and os.path.isdir(p)]

def find_repositories_by_walking_without_following_symlinks(path):
    """Walk a tree and return a sequence of (directory, dotdir) pairs."""
    repos = []
    for dirpath, dirnames, filenames in os.walk(path, followlinks=False):
        for dotdir in set(dirnames) & DOTDIRS:
            repos.append((dirpath, dotdir))
    return repos

def find_repositories_by_walking_and_following_symlinks(path):
    """Walk a tree and return a sequence of (directory, dotdir) pairs."""
    repos = []
    def inode(path):
        stats = os.stat(path)
        return (stats.st_dev, stats.st_ino)
    seen_inodes = {inode(path)}
    for dirpath, dirnames, filenames in os.walk(path, followlinks=True):
        inodes = [inode(os.path.join(dirpath, p)) for p in dirnames]
        dirnames[:] = [p for p, i in zip(dirnames, inodes) if not i in seen_inodes]
        seen_inodes.update(inodes)
        for dotdir in set(dirnames) & DOTDIRS:
            repos.append((dirpath, dotdir))
    return repos

def status_git(path, ignore_set, options):
    """Run git status.

    Returns a 2-element tuple:
    * Text lines describing the status of the repository.
    * List of subrepository paths, relative to the repository itself."""
    lines = [l for l in run(('git', 'status', '-s', '-b'), cwd=path) if (options.untracked or not l.startswith(b'?')) and (not l.startswith(b'##'))]
    lines += [l for l in run(('git', 'branch', '-v'), cwd=path) if b' [ahead ' in l]
    if options.non_tracking:
        lines += [l for l in run(('git', 'for-each-ref', '--format=[%(refname:short)]%(upstream)', 'refs/heads'), cwd=path) if l.endswith(b']')]
    if options.stash:
        lines += [l for l in run(('git', 'stash', 'list'), cwd=path)]
    discovered_submodules = []
    for l in run(('git', 'submodule', 'status'), cwd=path):
        match = git_submodule.search(l)
        if match:
            discovered_submodules.append(match.group(1))
    return (lines, discovered_submodules)

def status_subversion(path, ignore_set, options):
    """Run svn status.

    Returns a 2-element tuple:
    * Text lines describing the status of the repository.
    * Empty sequence of subrepos, since svn does not support them."""
    subrepos = ()
    if path in ignore_set:
        return (None, subrepos)
    keepers = []
    for line in run(['svn', 'st', '-v'], cwd=path):
        if not line.strip():
            continue
        if line.startswith(b'Performing') or line[0] in b'X?':
            continue
        status = line[:8]
        ignored_states = options.ignore_svn_states
        if ignored_states and status.strip() in ignored_states:
            continue
        filename = line[8:].split(None, 3)[-1]
        ignore_set.add(os.path.join(path, filename))
        if status.strip():
            keepers.append(b' ' + status + filename)
    return (keepers, subrepos)

def scan(repos, options):
    """Given a repository list [(path, vcsname), ...], scan each of them."""
    ignore_set = set()
    repos = repos[::-1]
    while repos:
        directory, dotdir = repos.pop()
        ignore_this = any((pat in directory for pat in options.ignore_patterns))
        if ignore_this:
            if options.verbose:
                output(b'Ignoring repo: %s' % directory)
                output(b'')
            continue
        vcsname, get_status = SYSTEMS[dotdir]
        lines, subrepos = get_status(directory, ignore_set, options)
        subrepos = [(os.path.join(directory, r), dotdir) for r in subrepos]
        repos.extend(reversed(subrepos))
        if lines is None:
            continue
        if lines or options.verbose:
            output(b'%s - %s' % (directory, vcsname))
            for line in lines:
                output(line)
            output(b'')

def putty_ignore_code(options, code):
    """Implement pep8 'ignore_code' hook."""
    reporter, line_number, offset, text, check = get_reporter_state()
    try:
        line = reporter.lines[line_number - 1]
    except IndexError:
        line = ''
    options.ignore = options._orig_ignore
    options.select = options._orig_select
    for rule in options.putty_ignore:
        if rule.match(reporter.filename, line, list(reporter.counters) + [code]):
            if rule._append_codes:
                options.ignore = options.ignore + rule.codes
            else:
                options.ignore = rule.codes
    for rule in options.putty_select:
        if rule.match(reporter.filename, line, list(reporter.counters) + [code]):
            if rule._append_codes:
                options.select = options.select + rule.codes
            else:
                options.select = rule.codes
    return ignore_code(options, code)

def _raise_on_error(data):
    """Check response for error message."""
    if isinstance(data, list):
        data = data[0]
    if isinstance(data, dict) and 'error' in data:
        raise_error(data['error'])

def get_unpaid_invoices_with_transactions(branch=None):
    """Returns all invoices that are unpaid on freckle but have transactions.

    This means, that the invoice is either partially paid and can be left as
    unpaid in freckle, or the invoice has been fully paid and should be set to
    paid in freckle as well."""
    if not client:
        return None
    result = {}
    try:
        unpaid_invoices = client.fetch_json('invoices', query_params={'state': 'unpaid'})
    except (ConnectionError, HTTPError):
        result.update({'error': _("Wasn't able to connect to Freckle.")})
    else:
        invoices = []
        for invoice in unpaid_invoices:
            invoice_with_transactions = models.Invoice.objects.filter(invoice_number=invoice['reference'], transactions__isnull=False)
            if branch:
                invoice_with_transactions = invoice_with_transactions.filter(branch=branch)
            if invoice_with_transactions:
                invoices.append(invoice)
        result.update({'invoices': invoices})
    return result

def sanitize_command_options(options):
    """Sanitizes command options."""
