def _pvi_path(granule):
    """Determine the PreView Image (PVI) path inside the SAFE pkg."""
    pvi_name = granule._metadata.iter('PVI_FILENAME').next().text
    pvi_name = pvi_name.split('/')
    pvi_path = os.path.join(granule.granule_path, pvi_name[len(pvi_name) - 2], pvi_name[len(pvi_name) - 1])
    try:
        assert os.path.isfile(pvi_path) or pvi_path in granule.dataset._zipfile.namelist()
    except (AssertionError, AttributeError):
        return None
    return pvi_path

def _polygon_from_coords(coords, fix_geom=False, swap=True, dims=2):
    """Return Shapely Polygon from coordinates.

    - coords: list of alterating latitude / longitude coordinates
    - fix_geom: automatically fix geometry"""
    assert len(coords) % dims == 0
    number_of_points = len(coords) / dims
    coords_as_array = np.array(coords)
    reshaped = coords_as_array.reshape(number_of_points, dims)
    points = [(float(i[1]), float(i[0])) if swap else (float(i[0]), float(i[1])) for i in reshaped.tolist()]
    polygon = Polygon(points).buffer(0)
    try:
        assert polygon.is_valid
        return polygon
    except AssertionError:
        if fix_geom:
            return polygon.buffer(0)
        else:
            raise RuntimeError('Geometry is not valid.')

def check_error(response, expect_status=200):
    """Youku error should return in json form, like:
    HTTP 400
    {
        "error":{
            "code":120010223,
            "type":"UploadsException",
            "description":"Expired upload token"
        }
    }

    But error also maybe in response url params or response booy.

    Content-Type maybe application/json or text/plain, so
    don't relay on it.

    Args:
        expect_status: normally is 200 or 201"""
    json = None
    try:
        json = response.json()
    except:
        pass
    if response.status_code != expect_status or response.status_code == 400 or 'error' in json:
        if json:
            error = json['error']
            raise YoukuError(error['code'], error['type'], error['description'], response.status_code)
        else:
            error = parse_qs(response.text)
            raise YoukuError(error.get('code', [None])[0], error.get('type', [None])[0], error.get('description', [None])[0], response.status_code)

