        return 0
    subparsers = {}
    subparser_factory = parser.add_subparsers()
    subparsers['help'] = subparser_factory.add_parser('help', help='Display help for a subcommand')
    subparsers['help'].add_argument('command', nargs='?')
    subparsers['help'].set_defaults(subcommand='help')
    for name, subcommand in ep_map.items():
        subparsers[name] = subparser_factory.add_parser(name, help=subcommand.__doc__)
        subparsers[name].set_defaults(subcommand=subcommand)
        for args, kwargs in getattr(subcommand, '_subcommand_args', []):
            subparsers[name].add_argument(*args, **kwargs)
        for argset in getattr(subcommand, '_subcommand_argsets', {}).values():
            group = subparsers[name].add_mutually_exclusive_group(required=True)
            for args, kwargs in argset:
                group.add_argument(*args, **kwargs)
    opts = parser.parse_args(argv)
    if opts.subcommand == 'help':
        if opts.command:
            subparsers[opts.command].print_help()
        else:
            parser.print_help()
    else:
        return _exit(opts.subcommand(opts) or 0)

def fetch(opts):
    """Create a local mirror of one or more resources."""
    resources = _load(opts.resources, opts.output_dir)
    if opts.all:
        opts.resource_names = ALL
    reporthook = None if opts.quiet else lambda name: print('Fetching {}...'.format(name))
    if opts.verbose:
        backend.VERBOSE = True
    _fetch(resources, opts.resource_names, opts.mirror_url, opts.force, reporthook)
    return verify(opts)

def verify(opts):
    """Verify that one or more resources were downloaded successfully."""
    resources = _load(opts.resources, opts.output_dir)
    if opts.all:
        opts.resource_names = ALL
    invalid = _invalid(resources, opts.resource_names)
    if not invalid:
        if not opts.quiet:
            print('All resources successfully downloaded')
        return 0
    else:
        if not opts.quiet:
            print('Invalid or missing resources: {}'.format(', '.join(invalid)))
        return 1

def install(opts):
    """Install one or more resources."""
    resources = _load(opts.resources, opts.output_dir)
    if opts.all:
        opts.resource_names = ALL
    success = _install(resources, opts.resource_names, opts.mirror_url, opts.destination, opts.skip_top_level)
    if success:
        if not opts.quiet:
            print('All resources successfully installed')
        return 0
    else:
        if not opts.quiet:
            invalid = _invalid(resources, opts.resource_names)
            print('Unable to install some resources: {}'.format(', '.join(invalid)))
        return 1

def decode(in_bytes):
    """Decode a string using Consistent Overhead Byte Stuffing (COBS).

    Input should be a byte string that has been COBS encoded. Output
    is also a byte string.

    A cobs.DecodeError exception will be raised if the encoded data
    is invalid."""
    if isinstance(in_bytes, str):
        raise TypeError('Unicode-objects are not supported; byte buffer objects only')
    in_bytes_mv = _get_buffer_view(in_bytes)
    out_bytes = bytearray()
    idx = 0
    if len(in_bytes_mv) > 0:
        while True:
            length = ord(in_bytes_mv[idx])
            if length == 0:
                raise DecodeError('zero byte found in input')
            idx += 1
            end = idx + length - 1
            copy_mv = in_bytes_mv[idx:end]
            if b'\x00' in copy_mv:
                raise DecodeError('zero byte found in input')
            out_bytes += copy_mv
            idx = end
            if idx > len(in_bytes_mv):
                raise DecodeError('not enough input bytes for length code')
            if idx < len(in_bytes_mv):
                if length < 255:
                    out_bytes.append(0)
            else:
                break
    return bytes(out_bytes)

def int_to_array(i, length=2):
    """Convert an length byte integer to an array of bytes."""
    res = []
    for dummy in range(0, length):
        res.append(i & 255)
        i = i >> 8
    return reversed(res)

def correct_output(luminosity):
    """:param luminosity: Input luminosity
    :return: Luminosity limited to the 0 <= l <= 255 range."""
    if luminosity < 0:
        val = 0
    elif luminosity > 255:
        val = 255
    else:
        val = luminosity
    return round(val)

def kelvin_to_rgb(kelvin):
    """Convert a color temperature given in kelvin to an approximate RGB value.

    :param kelvin: Color temp in K
    :return: Tuple of (r, g, b), equivalent color for the temperature"""
    temp = kelvin / 100.0
    if temp <= 66:
        red = 255
    else:
        red = 329.698727446 * (temp - 60) ** (-0.1332047592)
    if temp <= 66:
        green = 99.4708025861 * math.log(temp) - 161.1195681661
    else:
        green = 288.1221695283 * (temp - 60) ** (-0.0755148492)
    if temp > 66:
        blue = 255
    elif temp <= 19:
        blue = 0
    else:
        blue = 138.5177312231 * math.log(temp - 10) - 305.0447927307
    return tuple((correct_output(c) for c in (red, green, blue)))

def parent_dir(path):
