def group_factory(bridge, number, name, led_type):
    """Make a group.

    :param bridge: Member of this bridge.
    :param number: Group number (1-4).
    :param name: Name of group.
    :param led_type: Either `RGBW`, `WRGB`, `RGBWW`, `WHITE`, `DIMMER` or `BRIDGE_LED`.
    :returns: New group."""
    if led_type in [RGBW, BRIDGE_LED]:
        return RgbwGroup(bridge, number, name, led_type)
    elif led_type == RGBWW:
        return RgbwwGroup(bridge, number, name)
    elif led_type == WHITE:
        return WhiteGroup(bridge, number, name)
    elif led_type == DIMMER:
        return DimmerGroup(bridge, number, name)
    elif led_type == WRGB:
        return WrgbGroup(bridge, number, name)
    else:
        raise ValueError('Invalid LED type: %s', led_type)

def float_to_knx2(floatval):
    """Convert a float to a 2 byte KNX float value"""
    if floatval < -671088.64 or floatval > 670760.96:
        raise KNXException('float {} out of valid range'.format(floatval))
    floatval = floatval * 100
    i = 0
    for i in range(0, 15):
        exp = pow(2, i)
        if floatval / exp >= -2048 and floatval / exp < 2047:
            break
    if floatval < 0:
        sign = 1
        mantisse = int(2048 + floatval / exp)
    else:
        sign = 0
        mantisse = int(floatval / exp)
    return [(sign << 7) + (i << 3) + (mantisse >> 8), mantisse & 255]

def date_to_knx(dateval):
    """Convert a date to a 3 byte KNX data array"""
    if dateval.year < 1990 or dateval.year > 2089:
        raise KNXException('Year has to be between 1990 and 2089')
    if dateval.year < 2000:
        year = dateval.year - 1900
    else:
        year = dateval.year - 2000
    return [dateval.day, dateval.month, year]

def knx_to_date(knxdata):
    """Convert a 3 byte KNX data object to a date"""
    if len(knxdata) != 3:
        raise KNXException('Can only convert a 3 Byte object to date')
    year = knxdata[2]
    if year >= 90:
        year += 1900
    else:
        year += 2000
    return date(year, knxdata[1], knxdata[0])

def normalize_outputdir(outputdir=None):
    """if output dir is None try using the ./drivers directory
    if it already exists, otherwise use the current working directory"""
    normalized = ''
    cwd = os.getcwd()
    if not outputdir:
        outputdir_drivers = os.path.join(cwd, 'drivers')
        if os.path.isdir(outputdir_drivers):
            normalized = outputdir_drivers
        else:
            normalized = cwd
    else:
        normalized = os.path.join(cwd, os.path.normpath(outputdir))
    return normalized

def get_platform():
    """Get the current platform data.
    Returns a dictionary with keys: `os_name`, `os_bits`"""
    platform_data = {'os_name': None, 'os_bits': None}
    os_name = platform.system()
    normalize_os = {'Windows': 'windows', 'Linux': 'linux', 'Darwin': 'mac'}
    if os_name in normalize_os.keys():
        platform_data['os_name'] = normalize_os[os_name]
    else:
        raise Exception('Could not normalize os name {}'.format(os_name))
    maxsize = sys.maxsize
    if maxsize == EXPECTED_MAXSIZE_32:
        platform_data['os_bits'] = '32'
    elif maxsize == EXPECTED_MAXSIZE_64:
        platform_data['os_bits'] = '64'
    else:
        platform_data['os_bits'] = '64'
        logger.warning('could not determine os bits, setting default to 64')
    return platform_data

def extract_file_from_zip(bytes_io, expected_file):
    """Extracts a file from a bytes_io zip. Returns bytes"""
    zipf = zipfile.ZipFile(bytes_io)
    return zipf.read(expected_file)

def clean(outputdir, drivers=None):
    """Remove driver executables from the specified outputdir.

    drivers can be a list of drivers to filter which executables
    to remove. Specify a version using an equal sign i.e.: 'chrome=2.2'"""
    if drivers:
        drivers_split = [helpers.split_driver_name_and_version(x) for x in drivers]
        file_data = [(helpers.normalize_driver_name(x[0]), x[1]) for x in drivers_split]
    else:
        file_data = [(x, None) for x in config.ALL_DRIVERS]
    files = [file for file in os.listdir(outputdir) if os.path.isfile(os.path.join(outputdir, file))]
    for file in files:
        for data in file_data:
            prefix, version = data
            starts_with = file.startswith(prefix)
            version_match = 'N/A'
            if version is not None:
                file_version = helpers.extract_version_from_filename(file)
                if file_version == version:
                    version_match = True
                else:
                    version_match = False
            if starts_with and version_match in [True, 'N/A']:
                filepath = os.path.join(outputdir, file)
                try:
                    os.remove(filepath)
                except OSError:
                    pass
                finally:
                    logger.info('removed {}'.format(file))
                    break

def decode(in_bytes):
    """Decode a string using Consistent Overhead Byte Stuffing (COBS).

    Input should be a byte string that has been COBS encoded. Output
    is also a byte string.

    A cobs.DecodeError exception will be raised if the encoded data
    is invalid."""
    out_bytes = []
    idx = 0
    if len(in_bytes) > 0:
        while True:
            length = ord(in_bytes[idx])
            if length == 0:
                raise DecodeError('zero byte found in input')
            idx += 1
            end = idx + length - 1
            copy_bytes = in_bytes[idx:end]
            if '\x00' in copy_bytes:
                raise DecodeError('zero byte found in input')
            out_bytes.append(copy_bytes)
            idx = end
            if idx > len(in_bytes):
                raise DecodeError('not enough input bytes for length code')
            if idx < len(in_bytes):
                if length < 255:
                    out_bytes.append('\x00')
            else:
                break
    return ''.join(out_bytes)

def steps(current, target, max_steps):
    """Steps between two values.

    :param current: Current value (0.0-1.0).
    :param target: Target value (0.0-1.0).
    :param max_steps: Maximum number of steps."""
    if current < 0 or current > 1.0:
        raise ValueError('current value %s is out of bounds (0.0-1.0)', current)
    if target < 0 or target > 1.0:
        raise ValueError('target value %s is out of bounds (0.0-1.0)', target)
    return int(abs(current * max_steps - target * max_steps))

def wrap_response(resp, api_call):
    """Wrap the requests response in an `ApiResponse` object

    :param object resp: response object provided by the `requests` library.
    :param object api_call: Api Call
    :return: An `ApiResponse` object that wraps the content of the response.
    :rtype: object, list or dict"""
    try:
        js_resp = resp.json()
        if resp.ok:
            if 'items' in js_resp.keys():
                r = ApiListResponse(js_resp['items'])
            else:
                r = ApiDictResponse(js_resp)
            if 'paging' in js_resp.keys():
                cursors = js_resp.get('paging', {}).get('cursors', {})
                if 'after' in cursors.keys():
                    r.next = api_call(after=cursors['after'])
                if 'before' in cursors.keys():
                    r.previous = api_call(after=cursors['before'])
        else:
            r = ApiDictResponse(js_resp)
            if 'error' in js_resp.keys():
                r.error = js_resp['error']
            elif 'message' in js_resp.keys():
                r.error = js_resp['message']
        r.status_code = resp.status_code
        r.headers = resp.headers
        return r
    except:
        return resp

def run(cmd):
    """Run the given command.

    Raises OSError is the command returns a non-zero exit status."""
    log.debug("running '%s'", cmd)
    fixed_cmd = cmd
    if sys.platform == 'win32' and cmd.count('"') > 2:
        fixed_cmd = '"' + cmd + '"'
    retval = os.system(fixed_cmd)
    if hasattr(os, 'WEXITSTATUS'):
        status = os.WEXITSTATUS(retval)
    else:
        status = retval
    if status:
        raise OSError(status, "error running '%s'" % cmd)

def authenticated(function):
    """Re-authenticate if session expired."""
    def wrapped(*args):
        """Wrap function."""
        try:
            return function(*args)
        except FedexError:
            _login(*args)
            return function(*args)
    return wrapped

def get_packages(session):
    """Get packages."""
    resp = session.post(TRACKING_URL, {'data': json.dumps(SHIPMENT_LIST_REQUEST), 'action': SHIPMENT_LIST_ACTION, 'format': SHIPMENT_LIST_FORMAT, 'locale': session.auth.locale, 'version': 1})
    data = resp.json().get('ShipmentListLightResponse')
    if not data.get('successful'):
        err = 'failed to get shipment list: {}'.format(data.get('errorList')[0].get('message'))
