        packages.append({'weight': package['dispPkgLbsWgt'], 'dimensions': package['pkgDimIn'], 'tracking_number': package['trkNbr'], 'from': package['shpBy'], 'shipped_from': '{} {} {} {}'.format(package['shprAddr1'], package['shprCity'], package['shprStCD'], package['shprCntryCD']), 'primary_status': package['keyStat'], 'secondary_status': package['mainStat'], 'estimated_delivery_date': str(parse(package['estDelTs']).date()) if package['estDelTs'] else '', 'delivery_date': str(parse(package['delTs']).date()) if package['delTs'] else ''})
    return packages

def validate_settings(settings):
    """Ensure all user-supplied settings exist, or throw a useful error message.

    :param obj settings: The Django settings object."""
    if not (settings.STORMPATH_ID and settings.STORMPATH_SECRET):
        raise ImproperlyConfigured('Both STORMPATH_ID and STORMPATH_SECRET must be specified in settings.py.')
    if not settings.STORMPATH_APPLICATION:
