    parser.add_argument('length', type=int, help='the cycle length to generate')
    args = parser.parse_args(args)
    return cycle(args.length, args.width)

def filtany(entities, **kw):
    """Filter a set of entities based on method return. Use keyword arguments.

    Example:
      filtmeth(entities, id='123')
      filtmeth(entities, name='bart')

    Multiple filters are 'OR'."""
    ret = set()
    for k, v in kw.items():
        for entity in entities:
            if getattr(entity, k)() == v:
                ret.add(entity)
    return ret

def filtfirst(entities, **kw):
    """Return the first matching entity, sorted by id()."""
    ret = sorted(filtany(entities, **kw), key=lambda x: x.id())
    if not ret:
        raise ValueError('No result')
    return ret[0]

def _get_bits(bits=None, target=None):
    """Determine the number of bits to pack/unpack."""
    if bits is not None:
        bits = int(bits)
        if bits in (8, 16, 32, 64):
            return bits
        else:
            raise ValueError('bits needs to be 8, 16, 32 or 64')
    else:
        return int((target if target is not None else pwnypack.target.target).bits)

def to_utf8(obj):
    """Walks a simple data structure, converting unicode to byte string.

    Supports lists, tuples, and dictionaries."""
    if isinstance(obj, unicode_type):
        return _utf8(obj)
    elif isinstance(obj, dict):
        return dict(((to_utf8(k), to_utf8(v)) for k, v in obj.items()))
    elif isinstance(obj, list):
        return list((to_utf8(i) for i in obj))
    elif isinstance(obj, tuple):
        return tuple((to_utf8(i) for i in obj))
    return obj

def nasm_mutable_data_finalizer(env, code, data):
    """Simple data allocation strategy that expects the code to be in a writable
    segment. We just append the data to the end of the code."""
    if env.target.bits == 32:
        get_pc = ['\tcall __getpc0', '__getpc0:', '\tpop %s' % env.OFFSET_REG, '\tadd %s, __data - __getpc0' % env.OFFSET_REG, '__realstart:']
    else:
        get_pc = ['\tlea %s, [rel __data]' % env.OFFSET_REG]
    if data or env.buffers:
        return get_pc + code + _pack_data(data)
    else:
        return code

def binary_value_or_stdin(value):
    """Return fsencoded value or read raw data from stdin if value is None."""
    if value is None:
        reader = io.open(sys.stdin.fileno(), mode='rb', closefd=False)
        return reader.read()
    elif six.PY3:
        return os.fsencode(value)
    else:
        return value

def symlink(parser, cmd, args):
    """Set up symlinks for (a subset of) the pwny apps."""
    parser.add_argument('apps', nargs=argparse.REMAINDER, help='Which apps to create symlinks for.')
    args = parser.parse_args(args)
    base_dir, pwny_main = os.path.split(sys.argv[0])
    for app_name, config in MAIN_FUNCTIONS.items():
        if not config['symlink'] or (args.apps and app_name not in args.apps):
            continue
        dest = os.path.join(base_dir, app_name)
        if not os.path.exists(dest):
            print('Creating symlink %s' % dest)
            os.symlink(pwny_main, dest)
        else:
            print('Not creating symlink %s (file already exists)' % dest)

def __from_format(jd: float, fmt: str) -> (int, float):
    """Converts a Julian Day format into the "standard" Julian
    day format.
    Parameters
    ----------
    jd
    fmt

    Returns
    -------
    (jd, fractional): (int, float)
         A tuple representing a Julian day.  The first number is the
         Julian Day Number, and the second is the fractional component of the
         day.  A fractional component of 0.5 represents noon.  Therefore
         the standard julian day would be (jd + fractional + 0.5)"""
    if fmt.lower() == 'jd':
        return (math.floor(jd + 0.5), jd + 0.5 - math.floor(jd + 0.5))
    elif fmt.lower() == 'mjd':
        return __from_format(jd + 2400000.5, 'jd')
    elif fmt.lower() == 'rjd':
        return __from_format(jd + 2400000, 'jd')
    else:
        raise ValueError('Invalid Format')

def xor_app(parser, cmd, args):
    """Xor a value with a key."""
    parser.add_argument('-d', '--dec', help='interpret the key as a decimal integer', dest='type', action='store_const', const=int)
    parser.add_argument('-x', '--hex', help='interpret the key as an hexadecimal integer', dest='type', action='store_const', const=lambda v: int(v, 16))
    parser.add_argument('key', help='the key to xor the value with')
    parser.add_argument('value', help='the value to xor, read from stdin if omitted', nargs='?')
