def get_py_internals(version=None, default=None):
    """Given a version specification. It can be any dict which is returned
    verbatim, an index into :data:`PY_INTERNALS` or ``None``.

    Arguments:
        version: The python version to return the internals of.
        default: The python version that will be looked up if ``version`` is
            None.

    Returns:
        dict: The python internals for the requested version."""
    if version is None:
        version = default
    if isinstance(version, dict):
        return version
    elif version in PY_INTERNALS:
        return PY_INTERNALS[version]
    else:
        return ValueError('Unsupported python version %r requested.' % version)

def getGestureAndSegments(points):
    """Returns a list of tuples. The first item in the tuple is the directional
    integer, and the second item is a tuple of integers for the start and end
    indexes of the points that make up the stroke."""
    strokes, strokeSegments = _identifyStrokes(points)
    return list(zip(strokes, strokeSegments))

def findClosestMatchingGesture(strokes, gestureList, maxDifference=None):
    """Returns the gesture(s) in `gestureList` that closest matches the gesture in
    `strokes`. The `maxDifference` is how many differences there can be and still
    be considered a match."""
    if len(gestureList) == 0:
        return None
    gestureList = frozenset([tuple(gesture) for gesture in gestureList])
    distances = {}
    for g in gestureList:
        levDist = levenshteinDistance(strokes, g)
        if maxDifference is None or levDist <= maxDifference:
            distances.setdefault(levDist, [])
            distances[levDist].append(g)
    if not distances:
        return None
    return tuple(distances[min(distances.keys())])

def _distance(coord1, coord2):
    """Return the distance between two points, `coord1` and `coord2`. These
    parameters are assumed to be (x, y) tuples."""
    xdist = coord1[0] - coord2[0]
    ydist = coord1[1] - coord2[1]
    return sqrt(xdist * xdist + ydist * ydist)

def get_node_size(node):
    """Get size of memory on C{node}.

    @param node: node idx
    @type node: C{int}
    @return: free memory/total memory
    @rtype: C{tuple}(C{int}, C{int})"""
    free = c_longlong()
    if node < 0 or node > get_max_node():
        raise ValueError(node)
    size = libnuma.numa_node_size64(node, byref(free))
    return (free.value, size)

def node_to_cpus(node):
    """Get CPUs available on C{node}.

    @return: set of CPU ids
    @rtype: C{set}"""
    result = set()
    if node < 0 or node > get_max_node():
        raise ValueError(node)
    mask = bitmask_t()
    mask.maskp = (c_ulong * (NUMA_NUM_NODES / (sizeof(c_ulong) * 8)))()
    mask.size = NUMA_NUM_NODES
    if libnuma.numa_node_to_cpus(node, byref(mask)) < 0:
        raise RuntimeError(node)
    for i in range(0, NUMA_NUM_NODES / (sizeof(c_ulong) * 8)):
        for j in range(0, sizeof(c_ulong) * 8):
            if mask.maskp[i] & 1 << j == 1 << j:
                result.add(i * sizeof(c_ulong) * 8 + j)
    return result

def numa_nodemask_to_set(mask):
    """Convert NUMA nodemask to Python set."""
    result = set()
    for i in range(0, get_max_node() + 1):
        if __nodemask_isset(mask, i):
            result.add(i)
    return result

def set_to_numa_nodemask(mask):
    """Conver Python set to NUMA nodemask."""
    result = nodemask_t()
    __nodemask_zero(result)
    for i in range(0, get_max_node() + 1):
        if i in mask:
            __nodemask_set(result, i)
    return result

def set_interleave_mask(nodemask):
    """Sets the memory interleave mask for the current thread to C{nodemask}.

    @param nodemask: node mask
    @type nodemask: C{set}"""
    mask = set_to_numa_nodemask(nodemask)
    tmp = bitmask_t()
    tmp.maskp = cast(byref(mask), POINTER(c_ulong))
    tmp.size = sizeof(nodemask_t) * 8
    libnuma.numa_set_interleave_mask(byref(tmp))

def get_interleave_mask():
    """Get interleave mask for current thread.

    @return: node mask
    @rtype: C{set}"""
    nodemask = nodemask_t()
    bitmask = libnuma.numa_get_interleave_mask()
    libnuma.copy_bitmask_to_nodemask(bitmask, byref(nodemask))
    libnuma.numa_bitmask_free(bitmask)
    return numa_nodemask_to_set(nodemask)

def bind(nodemask):
    """Binds the current thread and its children to the nodes specified in nodemask.
    They will only run on the CPUs of the specified nodes and only be able to allocate memory from them.

    @param nodemask: node mask
    @type nodemask: C{set}"""
    mask = set_to_numa_nodemask(nodemask)
    bitmask = libnuma.numa_allocate_nodemask()
    libnuma.copy_nodemask_to_bitmask(byref(mask), bitmask)
    libnuma.numa_bind(bitmask)
    libnuma.numa_bitmask_free(bitmask)

def set_preferred(node):
    """Sets  the preferred node for the current thread to node.

    The preferred node is the node on which memory is preferably allocated before falling back to other
    nodes. The default is to use the node on which the process is currently running (local policy).

    @param node: node idx
    @type node: C{int}"""
    if node < 0 or node > get_max_node():
        raise ValueError(node)
    libnuma.numa_set_preferred(node)

def set_membind(nodemask):
    """Sets the memory allocation mask.

    The thread will only allocate memory from the nodes set in nodemask.

    @param nodemask: node mask
    @type nodemask: C{set}"""
    mask = set_to_numa_nodemask(nodemask)
    tmp = bitmask_t()
    tmp.maskp = cast(byref(mask), POINTER(c_ulong))
    tmp.size = sizeof(nodemask_t) * 8
    libnuma.numa_set_membind(byref(tmp))

def get_membind():
    """Returns  the  mask of nodes from which memory can currently be allocated.

    @return: node mask
    @rtype: C{set}"""
    bitmask = libnuma.numa_get_membind()
    nodemask = nodemask_t()
    libnuma.copy_bitmask_to_nodemask(bitmask, byref(nodemask))
    libnuma.numa_bitmask_free(bitmask)
    return numa_nodemask_to_set(nodemask)

def set_run_on_node_mask(nodemask):
    """Runs the  current thread and its children only on nodes specified in nodemask.

    They will not migrate to CPUs of other nodes until the node affinity is
    reset with a new call to L{set_run_on_node_mask}.

    @param nodemask: node mask
    @type nodemask: C{set}"""
    mask = set_to_numa_nodemask(nodemask)
    tmp = bitmask_t()
    tmp.maskp = cast(byref(mask), POINTER(c_ulong))
    tmp.size = sizeof(nodemask_t) * 8
    if libnuma.numa_run_on_node_mask(byref(tmp)) < 0:
        raise RuntimeError()

def get_run_on_node_mask():
    """Returns the mask of nodes that the current thread is allowed to run on.

    @return: node mask
    @rtype: C{set}"""
    bitmask = libnuma.numa_get_run_node_mask()
    nodemask = nodemask_t()
    libnuma.copy_bitmask_to_nodemask(bitmask, byref(nodemask))
    libnuma.numa_bitmask_free(bitmask)
    return numa_nodemask_to_set(nodemask)

def get_affinity(pid):
    """Returns the affinity mask of the process whose ID is pid.

    @param pid: process PID (0 == current process)
    @type pid: C{int}
    @return: set of CPU ids
    @rtype: C{set}"""
    cpuset = cpu_set_t()
    result = set()
    libnuma.sched_getaffinity(pid, sizeof(cpu_set_t), byref(cpuset))
    for i in range(0, sizeof(cpu_set_t) * 8):
        if __CPU_ISSET(i, cpuset):
            result.add(i)
    return result

def set_affinity(pid, cpuset):
    """Sets  the  CPU  affinity  mask of the process whose ID is pid to the value specified by mask.

    If pid is zero, then the calling process is used.

    @param pid: process PID (0 == current process)
    @type pid: C{int}
    @param cpuset: set of CPU ids
    @type cpuset: C{set}"""
    _cpuset = cpu_set_t()
    __CPU_ZERO(_cpuset)
    for i in cpuset:
        if i in range(0, sizeof(cpu_set_t) * 8):
            __CPU_SET(i, _cpuset)
    if libnuma.sched_setaffinity(pid, sizeof(cpu_set_t), byref(_cpuset)) < 0:
        raise RuntimeError()

def read_route_spec_config(fname):
    """Read, parse and sanity check the route spec config file.

    The config file needs to be in this format:

    {
        "<CIDR-1>" : [ "host-1-ip", "host-2-ip", "host-3-ip" ],
        "<CIDR-2>" : [ "host-4-ip", "host-5-ip" ],
        "<CIDR-3>" : [ "host-6-ip", "host-7-ip", "host-8-ip", "host-9-ip" ]
    }

    Returns the validated route config."""
    try:
        try:
            f = open(fname, 'r')
        except IOError as e:
            raise ValueError('Cannot open file: ' + str(e))
        data = json.loads(f.read())
        f.close()
        data = common.parse_route_spec_config(data)
    except ValueError as e:
        logging.error('Config ignored: %s' % str(e))
        data = None
    return data

def chunkiter(objs, n=100):
    """Chunk an iterator of unknown size. The optional
    keyword 'n' sets the chunk size (default 100)."""
    objs = iter(objs)
    try:
        while 1:
            chunk = []
            while len(chunk) < n:
                chunk.append(six.next(objs))
            yield chunk
    except StopIteration:
        pass
    if len(chunk):
        yield chunk

def parse_route_spec_config(data):
    """Parse and sanity check the route spec config.

    The config data is a blob of JSON that needs to be in this format:

    {
        "<CIDR-1>" : [ "host-1-ip", "host-2-ip", "host-3-ip" ],
        "<CIDR-2>" : [ "host-4-ip", "host-5-ip" ],
        "<CIDR-3>" : [ "host-6-ip", "host-7-ip", "host-8-ip", "host-9-ip" ]
    }

    Returns the validated route config. This validation is performed on any
    route-spec pushed out by the config watcher plugin.

    Duplicate hosts in the host lists are removed.

    Raises ValueError exception in case of problems."""
    if type(data) is not dict:
        raise ValueError('Expected dictionary at top level')
    try:
        for k, v in data.items():
            utils.ip_check(k, netmask_expected=True)
            if type(v) is not list:
                raise ValueError('Expect list of IPs as values in dict')
            hosts = set(v)
            for ip in hosts:
                utils.ip_check(ip)
            clean_host_list = sorted(list(hosts))
            data[k] = clean_host_list
    except ArgsError as e:
        raise ValueError(e.message)
    return data

def pretty_date(the_datetime):
    """Attempt to return a human-readable time delta string."""
    diff = datetime.utcnow() - the_datetime
    if diff.days > 7 or diff.days < 0:
        return the_datetime.strftime('%A %B %d, %Y')
    elif diff.days == 1:
        return '1 day ago'
    elif diff.days > 1:
        return '{0} days ago'.format(diff.days)
    elif diff.seconds <= 1:
        return 'just now'
    elif diff.seconds < 60:
        return '{0} seconds ago'.format(diff.seconds)
    elif diff.seconds < 120:
        return '1 minute ago'
    elif diff.seconds < 3600:
        return '{0} minutes ago'.format(int(round(diff.seconds / 60)))
    elif diff.seconds < 7200:
        return '1 hour ago'
    else:
        return '{0} hours ago'.format(int(round(diff.seconds / 3600)))

def log_to_logger(fn):
    """Wrap a Bottle request so that a log line is emitted after it's handled."""
    @wraps(fn)
    def _log_to_logger(*args, **kwargs):
        actual_response = fn(*args, **kwargs)
        logger.info('%s %s %s %s' % (bottle.request.remote_addr, bottle.request.method, bottle.request.url, bottle.response.status))
        return actual_response
    return _log_to_logger

def handle_request(path):
    """Return the current status."""
    accept = bottle.request.get_header('accept', default='text/plain')
    bottle.response.status = 200
    try:
        if 'text/html' in accept:
            ret = CURRENT_STATE.as_html(path=path)
            bottle.response.content_type = 'text/html'
        elif 'application/json' in accept:
            ret = CURRENT_STATE.as_json(path=path)
            bottle.response.content_type = 'application/json'
        elif 'text/' in accept or '*/*' in accept:
            ret = CURRENT_STATE.as_json(path=path, with_indent=True)
            bottle.response.content_type = 'text/plain'
        else:
            bottle.response.status = 407
            ret = 'Cannot render data in acceptable content type'
    except StateError:
        bottle.response.status = 404
        ret = 'Requested state component not found'
    return ret

def ip_check(ip, netmask_expected=False):
    """Sanity check that the specified string is indeed an IP address or mask."""
    try:
        if netmask_expected:
            if '/' not in ip:
                raise netaddr.core.AddrFormatError()
            netaddr.IPNetwork(ip)
        else:
            netaddr.IPAddress(ip)
    except netaddr.core.AddrFormatError:
        if netmask_expected:
            raise ArgsError('Not a valid CIDR (%s)' % ip)
        else:
            raise ArgsError('Not a valid IP address (%s)' % ip)
    except Exception as e:
        raise ArgsError('Invalid format: %s' % str(e))

def check_valid_ip_or_cidr(val, return_as_cidr=False):
    """Checks that the value is a valid IP address or a valid CIDR.

    Returns the specified value.

    If 'return_as_cidr' is set then the return value will always be in the form
    of a CIDR, even if a plain IP address was specified."""
    is_ip = True
    if '/' in val:
        ip_check(val, netmask_expected=True)
        is_ip = False
    else:
        ip_check(val, netmask_expected=False)
    if return_as_cidr and is_ip:
        if val == '0.0.0.0':
            val = '0.0.0.0/0'
        else:
            val = '%s/32' % val
    try:
        ipaddress.IPv4Network(unicode(val))
    except Exception as e:
        raise ArgsError('Not a valid network: %s' % str(e))
    return val

def is_cidr_in_cidr(small_cidr, big_cidr):
    """Return True if the small CIDR is contained in the big CIDR."""
    if small_cidr == '0.0.0.0/0':
        return big_cidr == '0.0.0.0/0'
    elif big_cidr == '0.0.0.0/0':
        return False
    s = ipaddress.IPv4Network(unicode(small_cidr))
    b = ipaddress.IPv4Network(unicode(big_cidr))
    return s.subnet_of(b)

def read_last_msg_from_queue(q):
    """Read all messages from a queue and return the last one.

    This is useful in many cases where all messages are always the complete
    state of things. Therefore, intermittent messages can be ignored.

    Doesn't block, returns None if there is no message waiting in the queue."""
    msg = None
    while True:
        try:
            msg = q.get_nowait()
            q.task_done()
        except Queue.Empty:
            return msg

def param_extract(args, short_form, long_form, default=None):
    """Quick extraction of a parameter from the command line argument list.

    In some cases we need to parse a few arguments before the official
    arg-parser starts.

    Returns parameter value, or None if not present."""
    val = default
    for i, a in enumerate(args):
        elems = a.split('=', 1)
        if elems[0] in [short_form, long_form]:
            if len(elems) == 1:
                if i + 1 < len(args) and (not args[i + 1].startswith('-')):
                    val = args[i + 1]
                else:
                    val = ''
            else:
                val = elems[1]
            break
    return val

def base10_integer_to_basek_string(k, x):
    """Convert an integer into a base k string."""
    if not 2 <= k <= max_k_labeled:
        raise ValueError('k must be in range [2, %d]: %s' % (max_k_labeled, k))
    return x == 0 and numerals[0] or base10_integer_to_basek_string(k, x // k).lstrip(numerals[0]) + numerals[x % k]

def basek_string_to_base10_integer(k, x):
    """Convert a base k string into an integer."""
    assert 1 < k <= max_k_labeled
    return sum((numeral_index[c] * k ** i for i, c in enumerate(reversed(x))))

def calculate_bucket_level(k, b):
    """Calculate the level in which a 0-based bucket
    lives inside of a k-ary heap."""
    assert k >= 2
    if k == 2:
        return log2floor(b + 1)
    v = (k - 1) * (b + 1) + 1
    h = 0
    while k ** (h + 1) < v:
        h += 1
    return h

def validate_sample_frame(sample_frame):
    """Makes sure that `sample_frame` has the columns we expect.

    :param DataFrame sample_frame: A sample data frame.
    :return: True (or raises an exception)
    :raises TypeError: if sample_frame is not a pandas DataFrame
    :raises ValueError: if columns are missing or the wrong type"""
    if not isinstance(sample_frame, pd.core.frame.DataFrame):
        raise TypeError('Expected a pandas DataFrame, received {}'.format(type(sample_frame)))
    for col in ['Sample', 'Target', 'Cq']:
        if col not in sample_frame:
            raise ValueError('Missing column {} in sample frame'.format(col))
    if sample_frame['Cq'].dtype.kind != 'f':
        raise ValueError('Expected Cq column to have float type; has type {} instead'.format(str(sample_frame['Cq'].dtype)))
    return True

def calculate_v(nfs):
    """Calculates V(n+1/n) values. Useful for establishing the quality of
    your normalization regime. See Vandesompele 2002 for advice on
    interpretation.

    :param DataFrame nfs: A matrix of all normalization factors, produced by
       `calculate_all_nfs`.
    :return: a Series of values [V(2/1), V(3/2), V(4/3), ...]."""
    v = []
    if (nfs.columns != range(1, nfs.columns[-1] + 1)).any():
        raise ValueError('Column names invalid in nf_v_frame')
    for i in nfs.columns[:-1]:
        v.append(std(log2(nfs[i] / nfs[i + 1]), ddof=1))
    return pd.Series(v, index=nfs.columns[:-1])

def get_ec2_meta_data():
    """Get meta data about ourselves, if we are on an EC2 instance.

    In particular, this returns the VPC ID and region of this instance.

    If we are not on an EC2 instance it returns an empty dict."""
    try:
        md = boto.utils.get_instance_metadata(timeout=2, num_retries=2)
        vpc_id = md['network']['interfaces']['macs'].values()[0]['vpc-id']
        region = md['placement']['availability-zone'][:-1]
        return {'vpc_id': vpc_id, 'region_name': region}
    except:
        return {}

def _make_ip_subnet_lookup(vpc_info):
    """Updates the vpc-info object with a lookup for IP -> subnet."""
    vpc_info['ip_subnet_lookup'] = {}
    for instance in vpc_info['instances']:
        for interface in instance.interfaces:
            subnet_id = interface.subnet_id
            for priv_addr in interface.private_ip_addresses:
                vpc_info['ip_subnet_lookup'][priv_addr.private_ip_address] = subnet_id

def find_instance_and_eni_by_ip(vpc_info, ip):
    """Given a specific IP address, find the EC2 instance and ENI.

    We need this information for setting the route.

    Returns instance and emi in a tuple."""
    for instance in vpc_info['instances']:
        for eni in instance.interfaces:
            for pa in eni.private_ip_addresses:
                if pa.private_ip_address == ip:
                    return (instance, eni)
    raise VpcRouteSetError("Could not find instance/eni for '%s' in VPC '%s'." % (ip, vpc_info['vpc'].id))

def get_instance_private_ip_from_route(instance, route):
    """Find the private IP and ENI of an instance that's pointed to in a route.

    Returns (ipaddr, eni) tuple."""
    ipaddr = None
    for eni in instance.interfaces:
        if eni.id == route.interface_id:
            ipaddr = eni.private_ip_address
            break
    return (ipaddr, eni if ipaddr else None)

def _choose_different_host(old_ip, ip_list, failed_ips, questionable_ips):
    """Randomly choose a different host from a list of hosts.

    Pick from fully healthy IPs first (neither failed nor questionable).
    If we don't have any of those, pick from questionable ones next.

    If no suitable hosts can be found in the list (if it's empty or all hosts
    are in the failed_ips list) it will return None.

    The old IP (if any) is passed in. We will try to avoid returning this same
    old IP under the right circumstances. If no old IP is known, None can be
    passed in for it instead."""
    if not ip_list:
        return None
    ip_set = set(ip_list)
    failed_set = set(failed_ips)
    questionable_set = set(questionable_ips).intersection(ip_set).difference(failed_set)
    healthy_ips = list(ip_set.difference(failed_set, questionable_set))
    if healthy_ips:
        return random.choice(healthy_ips)
    if questionable_set:
        if old_ip not in questionable_set:
            return random.choice(list(questionable_set))
    return None

def _update_route(dcidr, router_ip, old_router_ip, vpc_info, con, route_table_id, update_reason):
    """Update an existing route entry in the route table."""
    instance = eni = None
    try:
        instance, eni = find_instance_and_eni_by_ip(vpc_info, router_ip)
        logging.info("--- updating existing route in RT '%s' %s -> %s (%s, %s) (old IP: %s, reason: %s)" % (route_table_id, dcidr, router_ip, instance.id, eni.id, old_router_ip, update_reason))
        try:
            con.replace_route(route_table_id=route_table_id, destination_cidr_block=dcidr, instance_id=instance.id, interface_id=eni.id)
        except Exception as e:
            raise Exception('replace_route failed: %s' % str(e))
        CURRENT_STATE.routes[dcidr] = (router_ip, str(instance.id), str(eni.id))
    except Exception as e:
        msg = "*** failed to update route in RT '%s' %s -> %s (%s)" % (route_table_id, dcidr, old_router_ip, e.message)
        update_reason += ' [ERROR update route: %s]' % e.message
        logging.error(msg)
    _rt_state_update(route_table_id, dcidr, router_ip, instance.id if instance else '(none)', eni.id if eni else '(none)', old_router_ip, update_reason)

def _add_missing_routes(route_spec, failed_ips, questionable_ips, chosen_routers, vpc_info, con, routes_in_rts):
    """Iterate over route spec and add all the routes we haven't set yet.

    This relies on being told what routes we HAVE already. This is passed
    in via the routes_in_rts dict.

    Furthermore, some routes may be set in some RTs, but not in others. In that
    case, we may already have seen which router was chosen for a certain route.
    This information is passed in via the chosen_routers dict. We should choose
    routers that were used before."""
    for dcidr, hosts in route_spec.items():
        new_router_ip = chosen_routers.get(dcidr)
        for rt_id, dcidr_list in routes_in_rts.items():
            if dcidr not in dcidr_list:
                if not new_router_ip:
                    new_router_ip = _choose_different_host(None, hosts, failed_ips, questionable_ips)
                    if not new_router_ip:
                        logging.warning('--- cannot find available target for route addition %s! Nothing I can do...' % dcidr)
                        break
                _add_new_route(dcidr, new_router_ip, vpc_info, con, rt_id)

def make_cluster_node_subnet_list(vpc_info, route_spec):
    """Create a list of subnets, which are associated with nodes in the current
    route spec (cluster).

    This is needed when later on we set routes, but only want to set routes in
    those route tables, which are associated with a subnet that in turn is
    associated with a cluster node (to avoid having to set the routes in all
    RTs). We can check whether the RT's subnet is in this list here.

    Returns list of subnet IDs."""
    subnets = set()
    for cidr_ignore, hosts in route_spec.items():
        for host_addr in hosts:
            subnet_id = vpc_info['ip_subnet_lookup'].get(host_addr)
            if not subnet_id:
                logging.warning("Did not find subnet associated with host address '%s'!" % host_addr)
            else:
                subnets.add(subnet_id)
    return list(subnets)

def handle_spec(region_name, vpc_id, route_spec, failed_ips, questionable_ips):
    """Connect to region and update routes according to route spec."""
    if CURRENT_STATE._stop_all:
        logging.debug('handle_spec: Stop requested, abort operation')
        return
    if not route_spec:
        logging.debug('handle_spec: No route spec provided')
        return
    logging.debug('Handle route spec')
    try:
        con = connect_to_region(region_name)
        vpc_info = get_vpc_overview(con, vpc_id, region_name)
        vpc_info['cluster_node_subnets'] = make_cluster_node_subnet_list(vpc_info, route_spec)
        process_route_spec_config(con, vpc_info, route_spec, failed_ips, questionable_ips)
        con.close()
    except boto.exception.StandardError as e:
        logging.warning('vpc-router could not set route: %s - %s' % (e.message, e.args))
        raise
    except boto.exception.NoAuthHandlerFound:
        logging.error('vpc-router could not authenticate')

def merkleroot(hashes):
    """Args:
        hashes: reversed binary form of transactions hashes, e.g.:
            ``binascii.unhexlify(h)[::-1] for h in block['tx']]``
    Returns:
        merkle root in hexadecimal form"""
    if len(hashes) == 1:
        return binascii.hexlify(bytearray(reversed(hashes[0])))
    if len(hashes) % 2 == 1:
        hashes.append(hashes[-1])
    parent_hashes = []
    for i in range(0, len(hashes) - 1, 2):
        first_round_hash = hashlib.sha256(hashes[i] + hashes[i + 1]).digest()
        second_round_hash = hashlib.sha256(first_round_hash).digest()
        parent_hashes.append(second_round_hash)
    return merkleroot(parent_hashes)

def colorize(bg, base, fg, *text):
    """colorize(bg, base, fg, *text)
    """
    rtext = [str(f) for f in text]
    return COLORIZE_FORMAT.format(_to_int(bg), _to_int(base), _to_int(fg), ''.join(rtext))

def uncolorize(text):
    """uncolorize(text)
    """
    match = re.match('(.*)\x1b\\[[0-9;]+m(.+?)\x1b\\[0m(.*)', text)
    try:
        return ''.join(match.groups())
    except:
        return text

def tr(text, kword, color):
    """tr(text, keyword, color)
    """
    return re.sub(kword, colorize(BgColor.Null, Base.Null, color, kword), text)

def tr_iter(text, kword, color):
    """tr_iter(text, kword, color)
    """
    s = ''
    for _t in text:
        if _t in kword:
            s += colorize(BgColor.Null, Base.Null, color, _t)
        else:
            s += _t
    return s

def normpath(path, keep_trailing=False):
    """Really normalize the path by adding a missing leading slash."""
    new_path = k_paths.normpath(path)
    if keep_trailing and path.endswith('/') and (not new_path.endswith('/')):
        new_path = new_path + '/'
    if not new_path.startswith('/'):
        return '/' + new_path
    return new_path

def read(*filenames, **kwargs):
    """Read file contents into string.

    Used by setup.py to concatenate long_description.

    :param string filenames: Files to be read and concatenated.
    :rtype: string"""
    encoding = kwargs.get('encoding', 'utf-8')
    sep = kwargs.get('sep', '\n')
    buf = []
    for filename in filenames:
        if path.splitext(filename)[1] == '.md':
            try:
                import pypandoc
                buf.append(pypandoc.convert_file(filename, 'rst'))
                continue
            except:
                with io.open(filename, encoding=encoding) as f:
                    buf.append(f.read())
        with io.open(filename, encoding=encoding) as f:
            buf.append(f.read())
    return sep.join(buf)

def prune_clusters(clusters, index, n=3):
    """Delete clusters with fewer than n elements."""
    torem = set((c for c in clusters if c.size < n))
    pruned_clusters = [c for c in clusters if c.size >= n]
    terms_torem = []
    for term, clusters in index.items():
        index[term] = clusters - torem
        if len(index[term]) == 0:
            terms_torem.append(term)
    for t in terms_torem:
        del index[t]
    return (pruned_clusters, index)

def filter_pages(pages, pagenum, pagename):
    """Choices pages by pagenum and pagename"""
    if pagenum:
        try:
            pages = [list(pages)[pagenum - 1]]
        except IndexError:
            raise IndexError('Invalid page number: %d' % pagenum)
    if pagename:
        pages = [page for page in pages if page.name == pagename]
        if pages == []:
            raise IndexError('Page not found: pagename=%s' % pagename)
    return pages

def export_img(visio_filename, image_filename, pagenum=None, pagename=None):
    """Exports images from visio file"""
    image_pathname = os.path.abspath(image_filename)
    if not os.path.isdir(os.path.dirname(image_pathname)):
        msg = 'Could not write image file: %s' % image_filename
        raise IOError(msg)
    with VisioFile.Open(visio_filename) as visio:
        pages = filter_pages(visio.pages, pagenum, pagename)
        try:
            if len(pages) == 1:
                pages[0].Export(image_pathname)
            else:
                digits = int(log(len(pages), 10)) + 1
                basename, ext = os.path.splitext(image_pathname)
                filename_format = '%s%%0%dd%s' % (basename, digits, ext)
                for i, page in enumerate(pages):
                    filename = filename_format % (i + 1)
                    page.Export(filename)
        except Exception:
            raise IOError('Could not write image: %s' % image_pathname)

def parse_options(args):
    """Parses command line options"""
    usage = 'usage: %prog [options] visio_filename image_filename'
    parser = OptionParser(usage=usage)
    parser.add_option('-p', '--page', action='store', type='int', dest='pagenum', help='pick a page by page number')
    parser.add_option('-n', '--name', action='store', type='string', dest='pagename', help='pick a page by page name')
    options, argv = parser.parse_args(args)
    if options.pagenum and options.pagename:
        parser.error('options --page and --name are mutually exclusive')
    if len(argv) != 2:
        parser.print_usage(sys.stderr)
        parser.exit()
    output_ext = os.path.splitext(argv[1])[1].lower()
    if output_ext not in ('.gif', '.jpg', '.png'):
        parser.error('Unsupported image format: %s' % argv[1])
    return (options, argv)

def main(args=sys.argv[1:]):
    """main funcion of visio2img"""
    if not is_pywin32_available():
        sys.stderr.write('win32com module not found')
        return -1
    try:
        options, argv = parse_options(args)
        export_img(argv[0], argv[1], options.pagenum, options.pagename)
        return 0
    except (IOError, OSError, IndexError) as err:
        sys.stderr.write('error: %s' % err)
        return -1

def nice_classname(obj):
    """Returns a nice name for class object or class instance.

    >>> nice_classname(Exception()) # doctest: +ELLIPSIS
    '...Exception'
    >>> nice_classname(Exception) # doctest: +ELLIPSIS
    '...Exception'"""
    if inspect.isclass(obj):
        cls_name = obj.__name__
    else:
        cls_name = obj.__class__.__name__
    mod = inspect.getmodule(obj)
    if mod:
        name = mod.__name__
        if name.startswith('org.python.core.'):
            name = name[len('org.python.core.'):]
        return '%s.%s' % (name, cls_name)
    else:
        return cls_name

def exc_message(exc_info):
    """Return the exception's message."""
    exc = exc_info[1]
    if exc is None:
        result = exc_info[0]
    else:
        try:
            result = str(exc)
        except UnicodeEncodeError:
            try:
                result = unicode(exc)
            except UnicodeError:
                result = exc.args[0]
    return result

def silence_ibapi_logging(levels=['DEBUG', 'INFO']):
    """Silences the excessive ibapi logging to the root logger."""
    levels = levels or ['DEBUG', 'INFO']
    for level in levels:
        if level not in ('DEBUG', 'INFO', 'WARNING', 'ERROR', 'CRITICAL'):
            raise ValueError('unknown log level: {0}'.format(level))
    for _, module_name, _ in pkgutil.iter_modules(ibapi.__path__):
        module = __import__('ibapi.{0}'.format(module_name), fromlist='ibapi')
        if not hasattr(module, 'logging'):
            continue
        for level in levels:
            setattr(module.logging, level.lower(), noop)

