def make_span(parented_tree):
    """create a 'span' or 'leaf' subtree for dis/lisp/RST-DT-formatted trees.

    Examples:
           span     (a subtree that covers the leaves 1 to 7)
         ___|____
        1        7

        leaf        (a subtree that only covers leaf 7)
         |
         7"""
    all_leaves = all_leaf_positions(parented_tree)
    if is_root(parented_tree):
        return t('span', ['1', str(len(all_leaves))])
    subtree_leaves = subtree_leaf_positions(parented_tree)
    if len(subtree_leaves) == 1:
        edu_id = all_leaves.index(subtree_leaves[0]) + 1
        return t('leaf', [str(edu_id)])
    elif len(subtree_leaves) > 1:
        first_edu_id = all_leaves.index(subtree_leaves[0]) + 1
        last_edu_id = all_leaves.index(subtree_leaves[-1]) + 1
        return t('span', [str(first_edu_id), str(last_edu_id)])
    else:
        raise NotImplementedError('Subtree has no leaves')

def get_nucsat_subtrees(parented_tree):
    """Return all direct children of the given tree, that are either
    a nucleus, satellite or a leaf node (i.e. all children except
    for relation nodes.)"""
    if is_leaf(parented_tree):
        return [parented_tree]
    nucsat_children = []
    for child in parented_tree:
        if is_leaf(child) or child.label() in ('N', 'S'):
            nucsat_children.append(child)
        else:
            nucsat_children.extend(get_nucsat_subtrees(child))
    return nucsat_children

def get_node_type(dgtree):
    """Returns the type of the root node of a DGParentedTree."""
    if is_leaf(dgtree):
        return TreeNodeTypes.leaf_node
    root_label = dgtree.label()
    if root_label == '':
        assert dgtree == DGParentedTree('', []), "The tree has no root label, but isn't empty: {}".format(dgtree)
        return TreeNodeTypes.empty_tree
    elif root_label in NUCLEARITY_LABELS:
        return TreeNodeTypes.nuclearity_node
    else:
        assert isinstance(dgtree, (RSTTree, DGParentedTree)), type(dgtree)
        return TreeNodeTypes.relation_node

def ensure_unicode(str_or_unicode):
    """tests, if the input is ``str`` or ``unicode``. if it is ``str``, it
    will be decoded from ``UTF-8`` to unicode."""
    if isinstance(str_or_unicode, str):
        return str_or_unicode.decode('utf-8')
    elif isinstance(str_or_unicode, unicode):
        return str_or_unicode
    else:
        raise ValueError("Input '{0}' should be a string or unicode, but its of type {1}".format(str_or_unicode, type(str_or_unicode)))

def ensure_utf8(str_or_unicode):
    """tests, if the input is ``str`` or ``unicode``. if it is ``unicode``,
    it will be encoded from ``unicode`` to ``utf-8``. otherwise, the
    input string is returned."""
    if isinstance(str_or_unicode, str):
        return str_or_unicode
    elif isinstance(str_or_unicode, unicode):
        return str_or_unicode.encode('utf-8')
    else:
        raise ValueError("Input '{0}' should be a string or unicode, but it is of type {1}".format(str_or_unicode, type(str_or_unicode)))

def create_dir(path):
    """Creates a directory. Warns, if the directory can't be accessed. Passes,
    if the directory already exists.

    modified from http://stackoverflow.com/a/600612

    Parameters
    ----------
    path : str
        path to the directory to be created"""
    import sys
    import errno
    try:
        os.makedirs(path)
    except OSError as exc:
        if exc.errno == errno.EEXIST:
            if os.path.isdir(path):
                pass
            else:
                raise
        elif exc.errno == errno.EACCES:
            sys.stderr.write('Cannot create [{0}]! Check Permissions'.format(path))
            raise
        else:
            raise

def find_files(dir_or_filelist, pattern='*'):
    """If given a path to a directory, finds files recursively,
    e.g. all *.txt files in a given directory (or its subdirectories).
    If given a list of files, yields all of the files that match the given
    pattern.

    adapted from: http://stackoverflow.com/a/2186673"""
    import os
    import fnmatch
    if isinstance(dir_or_filelist, str):
        directory = dir_or_filelist
        abspath = os.path.abspath(os.path.expanduser(directory))
        for root, dirs, files in os.walk(abspath):
            for basename in files:
                if fnmatch.fnmatch(basename, pattern):
                    filename = os.path.join(root, basename)
                    yield filename
    else:
        filelist = dir_or_filelist
        for filepath in filelist:
            if fnmatch.fnmatch(filepath, pattern):
                yield filepath

def sanitize_string(string_or_unicode):
    """remove leading/trailing whitespace and always return unicode."""
    if isinstance(string_or_unicode, unicode):
        return string_or_unicode.strip()
    elif isinstance(string_or_unicode, str):
        return string_or_unicode.decode('utf-8').strip()
    else:
        return u''

def make_labels_explicit(docgraph):
    """Appends the node ID to each node label and appends the edge type to each
    edge label in the given document graph. This can be used to debug a
    graph visually with ``write_dot``.

    Parameters
    ----------
    docgraph : DiscourseDocumentGraph
        document graph from which the nodes will be extracted

    Returns
    -------
    explicit_docgraph : DiscourseDocumentGraph
        document graph with explicit node and edge labels"""
    def make_nodelabels_explicit(docgraph):
        for node_id, node_attribs in docgraph.nodes(data=True):
            if 'label' in docgraph.node[node_id]:
                docgraph.node[node_id]['label'] = u'{0}_{1}'.format(node_attribs['label'], node_id)
        return docgraph
    def make_edgelabels_explicit(docgraph):
        for from_id, to_id, edge_attribs in docgraph.edges(data=True):
            for edge_num in docgraph.edge[from_id][to_id]:
                if 'label' in docgraph.edge[from_id][to_id][edge_num]:
                    docgraph.edge[from_id][to_id][edge_num]['label'] = u'{0}_{1}'.format(edge_attribs['label'], edge_attribs['edge_type'])
                else:
                    docgraph.edge[from_id][to_id][edge_num]['label'] = edge_attribs['edge_type']
        return docgraph
    return make_edgelabels_explicit(make_nodelabels_explicit(docgraph))

def get_connective(docgraph, unit_id):
    """returns the lowercased string of the connective used in the given Conano unit."""
    unit_index, _unit_type = unit_id.split(':')
    connective_id = unit_index + ':connective'
    return ' '.join((docgraph.get_token(tok_id).lower() for tok_id in get_span(docgraph, connective_id)))

def quote_for_pydot(string):
    """takes a string (or int) and encloses it with "-chars. if the string
    contains "-chars itself, they will be escaped."""
    if isinstance(string, int):
        string = str(string)
    escaped_str = QUOTE_RE.sub('\\\\"', string)
    return u'"{}"'.format(escaped_str)

def _preprocess_nodes_for_pydot(nodes_with_data):
    """throw away all node attributes, except for 'label'"""
    for node_id, attrs in nodes_with_data:
        if 'label' in attrs:
            yield (quote_for_pydot(node_id), {'label': quote_for_pydot(attrs['label'])})
        else:
            yield (quote_for_pydot(node_id), {})

def _preprocess_edges_for_pydot(edges_with_data):
    """throw away all edge attributes, except for 'label'"""
    for source, target, attrs in edges_with_data:
        if 'label' in attrs:
            yield (quote_for_pydot(source), quote_for_pydot(target), {'label': quote_for_pydot(attrs['label'])})
        else:
            yield (quote_for_pydot(source), quote_for_pydot(target), {})

