def get_span_offsets(docgraph, node_id):
    """returns the character start and end position of the span of text that
    the given node spans or dominates.

    Returns
    -------
    offsets : tuple(int, int)
        character onset and offset of the span"""
    try:
        span = get_span(docgraph, node_id)
        onsets, offsets = zip(*[docgraph.get_offsets(tok_node) for tok_node in span])
        return (min(onsets), max(offsets))
    except KeyError as _:
        raise KeyError("Node '{}' doesn't span any tokens.".format(node_id))

def get_span(docgraph, node_id, debug=False):
    """returns all the tokens that are dominated or in a span relation with
    the given node. If debug is set to True, you'll get a warning if the
    graph is cyclic.

    Returns
    -------
    span : list of str
        sorted list of token nodes (token node IDs)"""
    if debug is True and is_directed_acyclic_graph(docgraph) is False:
        warnings.warn("Can't reliably extract span '{0}' from cyclical graph'{1}'.Maximum recursion depth may be exceeded.".format(node_id, docgraph))
    span = []
    if docgraph.ns + ':token' in docgraph.node[node_id]:
        span.append(node_id)
    for src_id, target_id, edge_attribs in docgraph.out_edges_iter(node_id, data=True):
        if src_id == target_id:
            continue
        if edge_attribs['edge_type'] != EdgeTypes.pointing_relation:
            span.extend(get_span(docgraph, target_id))
    return sorted(span, key=natural_sort_key)

def get_text(docgraph, node_id=None):
    """returns the text (joined token strings) that the given node dominates
    or spans. If no node ID is given, returns the complete text of the
    document"""
    if node_id:
        tokens = (docgraph.node[node_id][docgraph.ns + ':token'] for node_id in get_span(docgraph, node_id))
    else:
        tokens = (docgraph.node[token_id][docgraph.ns + ':token'] for token_id in docgraph.tokens)
    return ' '.join(tokens)

def tokens2text(docgraph, token_ids):
    """given a list of token node IDs, returns a their string representation
    (concatenated token strings)."""
    return ' '.join((docgraph.node[token_id][docgraph.ns + ':token'] for token_id in token_ids))

def is_continuous(docgraph, dominating_node):
    """return True, if the tokens dominated by the given node are all adjacent"""
    first_onset, last_offset = get_span_offsets(docgraph, dominating_node)
    span_range = xrange(first_onset, last_offset + 1)
    token_offsets = (docgraph.get_offsets(tok) for tok in get_span(docgraph, dominating_node))
    char_positions = set(itertools.chain.from_iterable((xrange(on, off + 1) for on, off in token_offsets)))
    for item in span_range:
        if item not in char_positions:
            return False
    return True

def select_neighbors_by_edge_attribute(docgraph, source, attribute=None, value=None, data=False):
    """Get all neighbors with the given edge attribute value(s)."""
    assert isinstance(docgraph, MultiGraph)
    for neighbor_id in docgraph.neighbors_iter(source):
        edges = docgraph[source][neighbor_id].values()
        if attribute is None:
            has_attrib = True
        else:
            has_attrib = any((attribute in edge for edge in edges))
        if has_attrib:
            if value is None:
                has_value = True
            elif isinstance(value, basestring):
                has_value = any((edge.get(attribute) == value for edge in edges))
            else:
                has_value = any((edge.get(attribute) == v for edge in edges for v in value))
            if has_value:
                if data:
                    yield (neighbor_id, docgraph.node[neighbor_id])
                else:
                    yield neighbor_id

def select_edges(docgraph, conditions, data):
    """yields all edges that meet the conditions given as eval strings"""
    for src_id, target_id, edge_attribs in docgraph.edges(data=True):
        if all((eval(cond, {'edge_attribs': edge_attribs}) for cond in conditions)):
            if data:
                yield (src_id, target_id, edge_attribs)
            else:
                yield (src_id, target_id)

def select_edges_by(docgraph, layer=None, edge_type=None, data=False):
    """get all edges with the given edge type and layer.

    Parameters
    ----------
    docgraph : DiscourseDocumentGraph
        document graph from which the nodes will be extracted
    layer : str
        name of the layer
    edge_type : str
        Type of the edges to be extracted (Edge types are defined in the
        Enum ``EdgeTypes``).
    data : bool
        If True, results will include edge attributes.

    Returns
    -------
    edges : generator of str
        a container/list of edges (represented as (source node ID, target
        node ID) tuples). If data is True, edges are represented as
        (source node ID, target node ID, edge attribute dict) tuples."""
    edge_type_eval = "edge_attribs['edge_type'] == '{}'".format(edge_type)
    layer_eval = "'{}' in edge_attribs['layers']".format(layer)
    if layer is not None:
        if edge_type is not None:
            return select_edges(docgraph, data=data, conditions=[edge_type_eval, layer_eval])
        else:
            return select_edges(docgraph, conditions=[layer_eval], data=data)
    elif edge_type is not None:
        return select_edges(docgraph, data=data, conditions=[edge_type_eval])
    else:
        return docgraph.edges_iter(data=data)

def paula_etree_to_string(tree, dtd_filename):
    """convert a PAULA etree into an XML string."""
    return etree.tostring(tree, pretty_print=True, xml_declaration=True, encoding='UTF-8', standalone='no', doctype='<!DOCTYPE paula SYSTEM "{0}">'.format(dtd_filename))

def gen_paula_etree(paula_id):
    """creates an element tree representation of an empty PAULA XML file."""
    E = ElementMaker(nsmap=NSMAP)
    tree = E('paula', version='1.1')
    tree.append(E('header', paula_id=paula_id))
    return (E, tree)

def get_choices(timezones, grouped=False):
    """Retrieves timezone choices from any iterable (normally pytz)."""
    TZOffset = namedtuple('TZOffset', 'value offset_string')
    choices_dict = defaultdict(list)
    for tz in iter(timezones):
        now = datetime.now(pytz.timezone(tz))
        offset = now.strftime('%z')
        timezone_offset_string = 'GMT{plus_minus}{hours}:{minutes}'.format(**TIMEZONE_OFFSET_REGEX.match(offset).groupdict())
        if not grouped:
            display_string = '({timezone_offset_string}) {tz}'.format(timezone_offset_string=timezone_offset_string, tz=tz)
        else:
            display_string = tz
        choices_dict[TZOffset(value=int(offset), offset_string=timezone_offset_string)].append((tz, display_string))
    choices = []
    for tz_offset in sorted(choices_dict, key=attrgetter('value')):
        if not grouped:
            choices.extend(tuple(choices_dict[tz_offset]))
        else:
            choices.append((tz_offset.offset_string, tuple(choices_dict[tz_offset])))
    return tuple(choices)

def get_capitalized_relname(tree, subtree_index):
    """Returns the capitalized relation name from a tree's satellite
    subtree label, e.g. 'satellite:contrast' becomes 'Contrast'."""
    match = HS2015_REL_RE.match(tree[subtree_index].label())
    relname = match.group('relname')
    return relname.capitalize()

def get_edu_text(text_subtree):
    """return the text of the given EDU subtree"""
    assert text_subtree.label() == SubtreeType.text
    return u' '.join((word.decode('utf-8') for word in text_subtree.leaves()))

def get_nuclearity_type(child_types):
    """Returns the nuclearity type of an RST relation (i.e. 'multinuc',
    'nucsat' or 'multisat') or 'edu' if the node is below the relation
    level."""
    if 'text' in child_types and len(child_types) == 1:
        return NucType.edu
    assert 'nucleus' in child_types, 'This is not a relational node. child_types: {}'.format(child_types)
    if 'satellite' not in child_types:
        assert len(child_types['nucleus']) > 1
        return NucType.multinuc
    else:
        assert len(child_types['nucleus']) == 1
        if len(child_types['satellite']) == 1:
            return NucType.nucsat
        else:
            assert len(child_types['satellite']) > 1
            return NucType.multisat

def get_segment_label(segment, segment_type, segment_text, ns, tokenized):
    """generates an appropriate node label for a segment (useful for dot
    visualization)."""
    segment_prefix = segment_type[0] if segment_type else '_'
    if tokenized:
        segment_label = u'[{0}]:{1}:segment:{2}'.format(segment_prefix, ns, segment.attrib['id'])
    else:
        segment_label = u'[{0}]:{1}: {2}...'.format(segment_prefix, segment.attrib['id'], segment_text[:20])
    return segment_label

def terraform_external_data(function):
    """Query data is received on stdin as a JSON object.
    Result data must be returned on stdout as a JSON object.

    The wrapped function must expect its first positional argument to be a dictionary of the query data."""
    @wraps(function)
    def wrapper(*args, **kwargs):
        query = json.loads(sys.stdin.read())
        validate(query)
        try:
            result = function(query, *args, **kwargs)
        except Exception as e:
            error('{}: {}'.format(type(e).__name__, e))
        validate(result)
        sys.stdout.write(json.dumps(result))
    return wrapper

def extract_relations(dgtree, relations=None):
    """Extracts relations from a DGParentedTree.

    Given a DGParentedTree, returns a (relation name, relation type) dict
    of all the RST relations occurring in that tree."""
    if hasattr(dgtree, 'reltypes'):
        return dgtree.reltypes
    if relations is None:
        relations = {}
    if is_leaf(dgtree):
        return relations
    root_label = dgtree.label()
    if root_label == '':
        assert dgtree == DGParentedTree('', []), "The tree has no root label, but isn't empty: {}".format(dgtree)
        return relations
    elif root_label in NUCLEARITY_LABELS:
        for child in dgtree:
            relations.update(extract_relations(child, relations))
    else:
        child_labels = [child.label() for child in dgtree]
        assert all((label in NUCLEARITY_LABELS for label in child_labels))
        if 'S' in child_labels:
            relations[root_label] = 'rst'
        else:
            relations[root_label] = 'multinuc'
        for child in dgtree:
            relations.update(extract_relations(child, relations))
    return relations

def get_xsi_type(element):
    """returns the type of an element of the XML tree (incl. its namespace),
    i.e. nodes, edges, layers etc.), raises an exception if the element has no
    'xsi:type' attribute."""
    nsdict = NAMESPACES
    try:
        return element.xpath('@xsi:type', namespaces=nsdict)[0]
    except IndexError:
        raise ValueError("The '{0}' element has no 'xsi:type' but has these attribs:\n{1}").format(element.tag, element.attrib)

def get_node_type(tree):
    """Returns the type of the root node of the given RST tree
    (one of 'N', 'S', 'relation' or 'edu'.)"""
    if isinstance(tree, (RSTTree, nltk.tree.Tree)):
        if tree.label() in ('N', 'S'):
            return tree.label()
        else:
            return 'relation'
    elif isinstance(tree, basestring):
        return 'edu'
    else:
        raise ValueError('Unknown tree/node type: {}'.format(type(tree)))

def make_nucsat(relname, nuc_types, elements):
    """Creates a rst.sty Latex string representation of a standard RST relation
    (one nucleus, one satellite)."""
    assert len(elements) == 2 and len(nuc_types) == 2, 'A nucsat relation must have two elements.'
    assert set(nuc_types) == set(['N', 'S']), 'A nucsat relation must consist of one nucleus and one satellite.'
    result = '\\dirrel'
    for i, nuc_type in enumerate(nuc_types):
        if nuc_type == 'N':
            result += '\n\t' + NUC_TEMPLATE.substitute(nucleus=elements[i])
        else:
            result += '\n\t' + SAT_TEMPLATE.substitute(satellite=elements[i], relation=relname)
    return result

def make_multinuc(relname, nucleii):
    """Creates a rst.sty Latex string representation of a multi-nuclear RST relation."""
    nuc_strings = []
    for nucleus in nucleii:
        nuc_strings.append(MULTINUC_ELEMENT_TEMPLATE.substitute(nucleus=nucleus))
    nucleii_string = '\n\t' + '\n\t'.join(nuc_strings)
    return MULTINUC_TEMPLATE.substitute(relation=relname, nucleus_segments=nucleii_string)

def make_multisat(nucsat_tuples):
    """Creates a rst.sty Latex string representation of a multi-satellite RST subtree
    (i.e. a set of nucleus-satellite relations that share the same nucleus."""
    nucsat_tuples = [tup for tup in nucsat_tuples]
    assert len(nucsat_tuples) > 1, 'A multisat relation bundle must contain more than one relation'
    result = '\\dirrel\n\t'
    first_relation, remaining_relations = (nucsat_tuples[0], nucsat_tuples[1:])
    relname, nuc_types, elements = first_relation
    first_nucleus_pos = current_nucleus_pos = nuc_types.index('N')
    result_segments = []
    for i, nuc_type in enumerate(nuc_types):
        if nuc_type == 'N':
            result_segments.append(NUC_TEMPLATE.substitute(nucleus=elements[i]))
        else:
            result_segments.append(SAT_TEMPLATE.substitute(satellite=elements[i], relation=relname))
    for relname, nuc_types, elements in remaining_relations:
        for i, nuc_type in enumerate(nuc_types):
            if nuc_type == 'N':
                continue
            else:
                result_segment = SAT_TEMPLATE.substitute(satellite=elements[i], relation=relname)
                if i < first_nucleus_pos:
                    result_segments.insert(current_nucleus_pos, result_segment)
                    current_nucleus_pos += 1
                else:
                    result_segments.append(result_segment)
    return result + '\n\t'.join(result_segments)

def indent(text, amount, ch=' '):
    """Indents a string by the given amount of characters."""
    padding = amount * ch
    return ''.join((padding + line for line in text.splitlines(True)))

def maybe_render_markdown(string: str) -> Any:
    """Render a string as Markdown only if in an IPython interpreter."""
    if is_ipython_interpreter():
        from IPython.display import Markdown
        return Markdown(string)
    else:
        return string

def layerset2list(discoursegraph):
    """typecasts all `layers` sets to lists to make the graph
    exportable (e.g. into the `geoff` format).

    Parameters
    ----------
    discoursegraph : DiscourseDocumentGraph"""
    for node_id in discoursegraph:
        discoursegraph.node[node_id]['layers'] = list(discoursegraph.node[node_id]['layers'])
    for from_id, to_id in discoursegraph.edges_iter():
        edge_dict = discoursegraph.edge[from_id][to_id]
        for edge_id in edge_dict:
            edge_dict[edge_id]['layers'] = list(edge_dict[edge_id]['layers'])

def layerset2str(discoursegraph):
    """typecasts all `layers` from sets of strings into a single string to make
    the graph exportable (e.g. into the `gexf` and `graphml` formats).

    Parameters
    ----------
    discoursegraph : DiscourseDocumentGraph"""
    for node_id in discoursegraph:
        discoursegraph.node[node_id]['layers'] = str(discoursegraph.node[node_id]['layers'])
    for from_id, to_id in discoursegraph.edges_iter():
        edge_dict = discoursegraph.edge[from_id][to_id]
        for edge_id in edge_dict:
            edge_dict[edge_id]['layers'] = str(edge_dict[edge_id]['layers'])

def attriblist2str(discoursegraph):
    """converts all node/edge attributes whose values are lists into string
    values (e.g. to export them into the `gexf` and `graphml` formats).

    WARNING: This function iterates over all nodes and edges! You can speed up
    conversion by writing a custom function that only fixes those attributes
    that have lists (of strings) as values.

    Parameters
    ----------
    discoursegraph : DiscourseDocumentGraph"""
    for node_id in discoursegraph:
        node_dict = discoursegraph.node[node_id]
        for attrib in node_dict:
            if isinstance(node_dict[attrib], list):
                node_dict[attrib] = str(node_dict[attrib])
    for from_id, to_id in discoursegraph.edges_iter():
        edge_dict = discoursegraph.edge[from_id][to_id]
        for edge_id in edge_dict:
            for attrib in edge_dict[edge_id]:
                if isinstance(edge_dict[edge_id][attrib], list):
                    edge_dict[edge_id][attrib] = str(edge_dict[edge_id][attrib])

def remove_root_metadata(docgraph):
    """removes the ``metadata`` attribute of the root node of a document graph.
    this is necessary for some exporters, as the attribute may contain
    (nested) dictionaries."""
    docgraph.node[docgraph.root].pop('metadata', None)
    if 'discoursegraph:root_node' in docgraph.node:
        docgraph.node['discoursegraph:root_node'].pop('metadata', None)
    if hasattr(docgraph, 'merged_rootnodes'):
        for merged_rootnode in docgraph.merged_rootnodes:
            try:
                docgraph.node[merged_rootnode].pop('metadata', None)
            except KeyError as e:
                pass

def extract_segment_types(urml_document_element, namespace):
    """Return a map from segment node IDs to their segment type
    ('nucleus', 'satellite' or 'isolated')."""
    segment_types = {namespace + ':' + seg.attrib['id']: seg.tag for seg in urml_document_element.iter('nucleus', 'satellite')}
    for seg in urml_document_element.iter('segment'):
        seg_id = namespace + ':' + seg.attrib['id']
        if seg_id not in segment_types:
            segment_types[seg_id] = 'isolated'
    return segment_types

def sudo_required(func):
    """Enforces a view to have elevated privileges.
    Should likely be paired with ``@login_required``.

    >>> @sudo_required
    >>> def secure_page(request):
    >>>     ..."""
    @wraps(func)
    def inner(request, *args, **kwargs):
        if not request.is_sudo():
            return redirect_to_sudo(request.get_full_path())
        return func(request, *args, **kwargs)
    return inner

def spanstring2text(docgraph, span_string):
    """converts a span of tokens (str, e.g. 'word_88..word_91') into a string
    that contains the tokens itself."""
    token_node_ids = spanstring2tokens(docgraph, span_string)
    return u' '.join((docgraph.node[tok_node_id][docgraph.ns + ':token'] for tok_node_id in token_node_ids))

def get_edu_text(text_subtree):
    """return the text of the given EDU subtree, with '_!'-delimiters removed."""
    assert text_subtree.label() == 'text', 'text_subtree: {}'.format(text_subtree)
    edu_str = u' '.join((word for word in text_subtree.leaves()))
    return re.sub('_!(.*?)_!', '\\g<1>', edu_str)

def get_node_id(nuc_or_sat, namespace=None):
    """return the node ID of the given nucleus or satellite"""
    node_type = get_node_type(nuc_or_sat)
    if node_type == 'leaf':
        leaf_id = nuc_or_sat[0].leaves()[0]
        if namespace is not None:
            return '{0}:{1}'.format(namespace, leaf_id)
        else:
            return string(leaf_id)
    span_start = nuc_or_sat[0].leaves()[0]
    span_end = nuc_or_sat[0].leaves()[1]
    if namespace is not None:
        return '{0}:span:{1}-{2}'.format(namespace, span_start, span_end)
    else:
        return 'span:{0}-{1}'.format(span_start, span_end)

def convert_parens_in_rst_tree_str(rst_tree_str):
    """This converts '(' and ')' brackets the EDUs of the RST into PTB-style
    tokens (e.g., -LRB-) to escape them for nltk."""
    def replace_brackets(matchobj):
        edu = matchobj.group(0)
        for br, br_repl in DIS_ESCAPES:
            edu = re.sub('\\{}'.format(br), br_repl, edu)
        return edu
    return re.sub('_!(.*?)_!', replace_brackets, rst_tree_str)

def get_node_id(edge, node_type):
    """returns the source or target node id of an edge, depending on the
    node_type given."""
    assert node_type in ('source', 'target')
    _, node_id_str = edge.attrib[node_type].split('.')
    return int(node_id_str)

def get_string_onset(edge):
    """return the onset (int) of a string"""
    onset_label = edge.find('labels[@name="SSTART"]')
    onset_str = onset_label.xpath('@valueString')[0]
    return int(onset_str)

def get_string_offset(edge):
    """return the offset (int) of a string"""
    onset_label = edge.find('labels[@name="SEND"]')
    onset_str = onset_label.xpath('@valueString')[0]
    return int(onset_str)

def traverse_dependencies_up(docgraph, node_id, node_attr=None):
    """starting from the given node, traverse ingoing edges up to the root element
    of the sentence. return the given node attribute from all the nodes visited
    along the way."""
    source, target = docgraph.in_edges(node_id)[0]
    traverse_attr = node_attr if node_attr else docgraph.lemma_attr
    attrib_value = docgraph.node[source].get(traverse_attr)
    if attrib_value:
        yield attrib_value
    if istoken(docgraph, source) is True:
        for attrib_value in traverse_dependencies_up(docgraph, source, traverse_attr):
            yield attrib_value

def write_conll(docgraph, output_file, coreference_layer=None, markable_layer=None):
    """converts a DiscourseDocumentGraph into a tab-separated CoNLL 2009 file and
    writes it to the given file (or file path)."""
    if markable_layer is None:
        markable_layer = docgraph.ns + ':markable'
    conll_file = Conll2009File(docgraph, coreference_layer=coreference_layer, markable_layer=markable_layer)
    assert isinstance(output_file, (str, file))
    if isinstance(output_file, str):
        path_to_file = os.path.dirname(output_file)
        if not os.path.isdir(path_to_file):
            create_dir(path_to_file)
        conll_file.write(output_file)
    else:
        output_file.write(conll_file.__str__())

def extract_sentences(nodes, token_node_indices):
    """given a list of ``SaltNode``\\s, returns a list of lists, where each list
    contains the indices of the nodes belonging to that sentence."""
    sents = []
    tokens = []
    for i, node in enumerate(nodes):
        if i in token_node_indices:
            if node.features['tiger.pos'] != '$.':
                tokens.append(i)
            else:
                tokens.append(i)
                sents.append(tokens)
                tokens = []
    return sents

def t(root, children=None, debug=False, root_id=None):
    """Create (DGParented)Tree from a root (str) and a list of (str, list) tuples."""
    if isinstance(root, Tree):
        if children is None:
            return root
        return root.__class__(root, children, root_id)
    elif isinstance(root, basestring):
        root = debug_root_label(root, debug, root_id)
        if isinstance(children, Tree):
            child_trees = [children]
        elif isinstance(children, list):
            child_trees = []
            for child in children:
                if isinstance(child, Tree):
                    child_trees.append(child)
                elif isinstance(child, list):
                    child_trees.extend(child)
                elif isinstance(child, tuple):
                    child_trees.append(t(*child))
                elif isinstance(child, basestring):
                    child_trees.append(child)
                else:
                    raise NotImplementedError
        elif isinstance(children, basestring):
            child_trees = [Tree(children, [])]
        else:
            assert children is None
            child_trees = []
        return DGParentedTree(root, child_trees, root_id)
    else:
        raise NotImplementedError

def get_child_nodes(docgraph, parent_node_id, data=False):
    """Yield all nodes that the given node dominates or spans."""
    return select_neighbors_by_edge_attribute(docgraph=docgraph, source=parent_node_id, attribute='edge_type', value=[EdgeTypes.dominance_relation], data=data)

def horizontal_positions(docgraph, sentence_root=None):
    """return map: node ID -> first token index (int) it covers"""
    root_cond = sentence_root is None or sentence_root == docgraph.root
    if root_cond or 'tokens' not in docgraph.node[sentence_root]:
        sentence_root = docgraph.root
        token_nodes = docgraph.tokens
        path = {}
    else:
        token_nodes = docgraph.node[sentence_root]['tokens']
        path = {sentence_root: 0}
    for i, token_node in enumerate(token_nodes):
        start_node = token_node
        while get_parents(docgraph, start_node, strict=True):
            if start_node not in path:
                path[start_node] = i
            start_node = get_parents(docgraph, start_node, strict=True)[0]
    return path

def node2bracket(docgraph, node_id, child_str=''):
    """convert a docgraph node into a PTB-style string."""
    node_attrs = docgraph.node[node_id]
    if istoken(docgraph, node_id):
        pos_str = node_attrs.get(docgraph.ns + ':pos', '')
        token_str = node_attrs[docgraph.ns + ':token']
        return u'({pos}{space1}{token}{space2}{child})'.format(pos=pos_str, space1=bool(pos_str) * ' ', token=token_str, space2=bool(child_str) * ' ', child=child_str)
    label_str = node_attrs.get('label', '')
    return u'({label}{space}{child})'.format(label=label_str, space=bool(label_str and child_str) * ' ', child=child_str)

def tree2bracket(docgraph, root=None, successors=None):
    """convert a docgraph into a PTB-style string.

    If root (a node ID) is given, only convert the subgraph that this
    node domintes/spans into a PTB-style string."""
    if root is None:
        root = docgraph.root
    if successors is None:
        successors = sorted_bfs_successors(docgraph, root)
    if root in successors:
        embed_str = u' '.join((tree2bracket(docgraph, child, successors) for child in successors[root]))
        return node2bracket(docgraph, root, embed_str)
    return node2bracket(docgraph, root)

def word_wrap_tree(parented_tree, width=0):
    """line-wrap an NLTK ParentedTree for pretty-printing"""
    if width != 0:
        for i, leaf_text in enumerate(parented_tree.leaves()):
            dedented_text = textwrap.dedent(leaf_text).strip()
            parented_tree[parented_tree.leaf_treeposition(i)] = textwrap.fill(dedented_text, width=width)
    return parented_tree

def node2freqt(docgraph, node_id, child_str='', include_pos=False, escape_func=FREQT_ESCAPE_FUNC):
    """convert a docgraph node into a FREQT string."""
    node_attrs = docgraph.node[node_id]
    if istoken(docgraph, node_id):
        token_str = escape_func(node_attrs[docgraph.ns + ':token'])
        if include_pos:
            pos_str = escape_func(node_attrs.get(docgraph.ns + ':pos', ''))
            return u'({pos}({token}){child})'.format(pos=pos_str, token=token_str, child=child_str)
        else:
            return u'({token}{child})'.format(token=token_str, child=child_str)
    else:
        label_str = escape_func(node_attrs.get('label', node_id))
        return u'({label}{child})'.format(label=label_str, child=child_str)

def sentence2freqt(docgraph, root, successors=None, include_pos=False, escape_func=FREQT_ESCAPE_FUNC):
    """convert a sentence subgraph into a FREQT string."""
    if successors is None:
        successors = sorted_bfs_successors(docgraph, root)
    if root in successors:
        embed_str = u''.join((sentence2freqt(docgraph, child, successors, include_pos=include_pos, escape_func=escape_func) for child in successors[root]))
        return node2freqt(docgraph, root, embed_str, include_pos=include_pos, escape_func=escape_func)
    else:
        return node2freqt(docgraph, root, include_pos=include_pos, escape_func=escape_func)

def docgraph2freqt(docgraph, root=None, include_pos=False, escape_func=FREQT_ESCAPE_FUNC):
    """convert a docgraph into a FREQT string."""
    if root is None:
        return u'\n'.join((sentence2freqt(docgraph, sentence, include_pos=include_pos, escape_func=escape_func) for sentence in docgraph.sentences))
    else:
        return sentence2freqt(docgraph, root, include_pos=include_pos, escape_func=escape_func)

def write_freqt(docgraph, output_filepath, include_pos=False):
    """convert a docgraph into a FREQT input file (one sentence per line)."""
    path_to_file = os.path.dirname(output_filepath)
    if not os.path.isdir(path_to_file):
        create_dir(path_to_file)
    with codecs.open(output_filepath, 'w', 'utf-8') as output_file:
        for sentence in docgraph.sentences:
            output_file.write(docgraph2freqt(docgraph, sentence, include_pos=include_pos) + '\n')

