def revoke_sudo_privileges(request):
    """Revoke sudo privileges from a request explicitly"""
    request._sudo = False
    if COOKIE_NAME in request.session:
        del request.session[COOKIE_NAME]

def has_sudo_privileges(request):
    """Check if a request is allowed to perform sudo actions"""
    if getattr(request, '_sudo', None) is None:
        try:
            request._sudo = request.user.is_authenticated() and constant_time_compare(request.get_signed_cookie(COOKIE_NAME, salt=COOKIE_SALT, max_age=COOKIE_AGE), request.session[COOKIE_NAME])
        except (KeyError, BadSignature):
            request._sudo = False
    return request._sudo

def is_safe_url(url, host=None):
    """Return ``True`` if the url is a safe redirection (i.e. it doesn't point to
    a different host and uses a safe scheme).
    Always returns ``False`` on an empty url."""
    if url is not None:
        url = url.strip()
    if not url:
        return False
    if six.PY2:
        try:
            url = force_text(url)
        except UnicodeDecodeError:
            return False
    return _is_safe_url(url, host) and _is_safe_url(url.replace('\\', '/'), host)

def set_theme(request):
    """Redirect to a given url while setting the chosen theme in the session or cookie. The url and the theme identifier
    need to be specified in the request parameters.

    Since this view changes how the user will see the rest of the site, it must only be accessed as a POST request. If
    called as a GET request, it will redirect to the page in the request (the 'next' parameter) without changing any
    state."""
    next = request.POST.get('next', request.GET.get('next'))
    if not is_safe_url(url=next, host=request.get_host()):
        next = request.META.get('HTTP_REFERER')
        if not is_safe_url(url=next, host=request.get_host()):
            next = '/'
    response = http.HttpResponseRedirect(next)
    if request.method == 'POST':
        theme = request.POST.get('theme', None)
        if theme:
            if hasattr(request, 'session'):
                request.session['DJANGO_BOOTSTRAP_UI_THEME'] = theme
            else:
                response.set_cookie('DJANGO_BOOTSTRAP_UI_THEME', theme)
    return response

def slice_transform(func, self, X, *vargs, **kwargs):
    """Decorator for implementing partial application.

    This must decorate the ``transform`` and ``grad`` methods of basis objects
    if the ``slice_init`` decorator was used."""
    X = X if self.apply_ind is None else X[:, self.apply_ind]
    return func(self, X, *vargs, **kwargs)

def is_visa(n):
    """Checks if credit card number fits the visa format."""
    n, length = (str(n), len(str(n)))
    if length >= 13 and length <= 16:
        if n[0] == '4':
            return True
    return False

def is_visa_electron(n):
    """Checks if credit card number fits the visa electron format."""
    n, length = (str(n), len(str(n)))
    form = ['026', '508', '844', '913', '917']
    if length == 16:
        if n[0] == '4':
            if ''.join(n[1:4]) in form or ''.join(n[1:6]) == '17500':
                return True
    return False

def is_mastercard(n):
    """Checks if credit card number fits the mastercard format."""
    n, length = (str(n), len(str(n)))
    if length >= 16 and length <= 19:
        if ''.join(n[:2]) in strings_between(51, 56):
            return True
    return False

def is_amex(n):
    """Checks if credit card number fits the american express format."""
    n, length = (str(n), len(str(n)))
    if length == 15:
        if n[0] == '3' and (n[1] == '4' or n[1] == '7'):
            return True
    return False

def is_discover(n):
    """Checks if credit card number fits the discover card format."""
    n, length = (str(n), len(str(n)))
    if length == 16:
        if n[0] == '6':
            if ''.join(n[1:4]) == '011' or n[1] == '5':
                return True
            elif n[1] == '4' and n[2] in strings_between(4, 10):
                return True
            elif ''.join(n[1:6]) in strings_between(22126, 22926):
                return True
    return False

def get_format(n):
    """Gets a list of the formats a credit card number fits."""
    formats = []
    if is_visa(n):
        formats.append('visa')
    if is_visa_electron(n):
        formats.append('visa electron')
    if is_mastercard(n):
        formats.append('mastercard')
    if is_amex(n):
        formats.append('amex')
    if is_maestro(n):
        formats.append('maestro')
    if is_discover(n):
        formats.append('discover')
    return formats

def detect_keep_boundary(start, end, namespaces):
    """a helper to inspect a link and see if we should keep the link boundary
    """
    result_start, result_end = (False, False)
    parent_start = start.getparent()
    parent_end = end.getparent()
    if parent_start.tag == '{%s}p' % namespaces['text']:
        result_start = len(parent_start.getchildren()) > 1
    if parent_end.tag == '{%s}p' % namespaces['text']:
        result_end = len(parent_end.getchildren()) > 1
    return (result_start, result_end)

def move_siblings(start, end, new_, keep_start_boundary=False, keep_end_boundary=False):
    """a helper function that will replace a start/end node pair
    by a new containing element, effectively moving all in-between siblings
    This is particularly helpful to replace for /for loops in tables
    with the content resulting from the iteration

    This function call returns None. The parent xml tree is modified in place

    @param start: the starting xml node
    @type start: lxml.etree.Element

    @param end: the ending xml node
    @type end: lxml.etree.Element

    @param new_: the new xml element that will replace the start/end pair
    @type new_: lxlm.etree.Element

    @param keep_start_boundary: Flag to let the function know if it copies
    your start tag to the new_ node or not, Default value is False
    @type keep_start_boundary: bool

    @param keep_end_boundary: Flag to let the function know if it copies
    your end tag to the new_ node or not, Default value is False
    @type keep_end_boundary: bool

    @returns: None"""
    old_ = start.getparent()
    if keep_start_boundary:
        new_.append(copy(start))
    elif start.tail:
        new_.text = start.tail
    for node in start.itersiblings():
        if node is not end:
            new_.append(node)
        elif node is end:
            if keep_end_boundary:
                new_.append(copy(node))
            break
    old_.replace(start, new_)
    old_.remove(end)

def cmd_generate(args):
    """Generate text.

    Parameters
    ----------
    args : `argparse.Namespace`
        Command arguments."""
    if args.start:
        if args.end or args.reply:
            raise ValueError('multiple input arguments')
        args.reply_to = args.start
        args.reply_mode = ReplyMode.END
    elif args.end:
        if args.reply:
            raise ValueError('multiple input arguments')
        args.reply_to = args.end
        args.reply_mode = ReplyMode.START
    elif args.reply:
        args.reply_to = args.reply
        args.reply_mode = ReplyMode.REPLY
    else:
        args.reply_to = None
        args.reply_mode = ReplyMode.END
    markov = load(MarkovText, args.state, args)
    ss = range(args.count)
    if args.progress:
        title = truncate(args.output.name, BAR_DESC_SIZE - 1, False)
        ss = tqdm(ss, desc=title, bar_format=BAR_FORMAT, dynamic_ncols=True)
    if not args.format:
        markov.formatter = lambda x: x
    for _ in ss:
        data = markov(args.words, state_size=args.state_size, reply_to=args.reply_to, reply_mode=args.reply_mode)
        if data:
            print(data)

def is_valid(number):
    """determines whether the card number is valid."""
    n = str(number)
    if not n.isdigit():
        return False
    return int(n[-1]) == get_check_digit(n[:-1])

def generate(length):
    """Generates random and valid card number which is returned as a string."""
    if not isinstance(length, int) or length < 2:
        raise TypeError('length must be a positive integer greater than 1.')
    digits = [random.randint(1, 9)]
    for i in range(length - 2):
        digits.append(random.randint(0, 9))
    digits.append(get_check_digit(''.join(map(str, digits))))
    return ''.join(map(str, digits))

