def linewrap(chunks, width=None, sep=' ', preamble='', line_prefix=''):
    """Takes an iterator of strings, and attempts to wrap them in whole chunks
    to fit within width. Takes an optional preamble which is prepended before
    the first line, and an optional per-line prefix (which is appended to every
    line but the first). If return_gen is true, this function returns a
    generator that will produce the lines of output as needed, otherwise it
    returns a single joined string"""
    sep_len = len(sep)
    if isinstance(chunks, basestring):
        chunks = chunks.split()
    if preamble:
        chunks[0] = preamble + chunks[0]
    def line_len(line):
        """Gets the full length of a line passed a list of strings"""
        word_len = sum((len(l) for l in line))
        seps_len = sep_len * (len(line) - 1)
        return word_len + seps_len if seps_len >= 0 else 0
    def gen():
        """The generator to incrementally create lines from the input"""
        sep_len = len(sep)
        line = []
        for chunk in chunks:
            if line_len(line) + len(chunk) + sep_len > width:
                yield sep.join(line)
                line = [line_prefix + chunk]
            else:
                line.append(chunk)
        if line:
            yield sep.join(line)
    return gen()

def save(markov, fname, args):
    """Save a generator.

    Parameters
    ----------
    markov : `markovchain.Markov`
        Generator to save.
    fname : `str`
        Output file path.
    args : `argparse.Namespace`
        Command arguments."""
    if isinstance(markov.storage, JsonStorage):
        if fname is None:
            markov.save(sys.stdout)
        else:
            if fname.endswith('.bz2'):
                open_ = bz2.open
            else:
                open_ = open
            if args.progress:
                print('Saving JSON data...')
            with open_(fname, 'wt') as fp:
                markov.save(fp)
    else:
        markov.save()

def virtual(cls, **options):
    """Allows for defining virtual columns and collectors on models -- these
    are objects that are defined in code and not directly in a data store.

    :param cls:
    :param options:
    :return:"""
    def wrapped(func):
        param_name = inflection.underscore(func.__name__)
        options.setdefault('name', param_name)
        if 'flags' in options:
            if isinstance(options['flags'], set):
                options['flags'].add('Virtual')
                options['flags'].add('ReadOnly')
            else:
                options['flags'] |= cls.Flags.Virtual | cls.Flags.ReadOnly
        else:
            options['flags'] = {'Virtual', 'ReadOnly'}
        def define_setter():
            def setter_wrapped(setter_func):
                func.__orb__.setFlags(func.__orb__.flags() & ~cls.Flags.ReadOnly)
                func.__orb__.setter()(setter_func)
                return setter_func
            return setter_wrapped
        def define_query_filter():
            def shortcut_wrapped(shortcut_func):
                func.__orb__.queryFilter(shortcut_func)
                return shortcut_func
            return shortcut_wrapped
        func.__orb__ = cls(**options)
        func.__orb__.getter()(func)
        func.setter = define_setter
        func.queryFilter = define_query_filter
        return func
    return wrapped

def dict_factory(cursor, row):
    """Converts the cursor information from a SQLite query to a dictionary.

    :param      cursor | <sqlite3.Cursor>
                row    | <sqlite3.Row>

    :return     {<str> column: <variant> value, ..}"""
    out = {}
    for i, col in enumerate(cursor.description):
        out[col[0]] = row[i]
    return out

def basic_register(username, password, password2):
    """Register a user and session, and then return the session_key and user."""
    if password != password2:
        raise InvalidInput(password={'message': 'Passwords do not match'}, username={'value': username})
    user = User.objects.create_user(username, password)
    return create_session(user.username, password)

def create_session(username, password):
    """Create a session for the user, and then return the key."""
    user = User.objects.get_user_by_password(username, password)
    auth_session_engine = get_config('auth_session_engine')
    if not user:
        raise InvalidInput('Username or password incorrect')
    session_key = random_string(15)
    while auth_session_engine.get(session_key):
        session_key = random_string(15)
    auth_session_engine.set(session_key, user.username, get_config('auth_session_expire'))
    return {'session_key': session_key, 'user': user}

