def AuthenticatedOrRedirect(invocation):
    """Middleware class factory that redirects if the user is not logged in.
    Otherwise, nothing is effected."""
    class AuthenticatedOrRedirect(GiottoInputMiddleware):
        def http(self, request):
            if request.user:
                return request
            return Redirection(invocation)
        def cmd(self, request):
            if request.user:
                return request
            return Redirection(invocation)
    return AuthenticatedOrRedirect

def make_url(invocation, args=[], kwargs={}):
    """>>> make_url('some/path/program', ['arg1', 'arg2'], {'arg3': 4})
    '/some/path/program/arg1/arg2?arg3=4'"""
    if not invocation.endswith('/'):
        invocation += '/'
    if not invocation.startswith('/'):
        invocation = '/' + invocation
    url = invocation
    for arg in args:
        url += str(arg) + '/'
    if kwargs:
        url = url[:-1]
        url += '?' + urlencode(kwargs)
    return url

def fancy_error_template_middleware(app):
    """WGSI middleware for catching errors and rendering the error page."""
    def application(environ, start_response):
        try:
            return app(environ, start_response)
        except Exception as exc:
            sio = StringIO()
            traceback.print_exc(file=sio)
            sio.seek(0)
            response = Response(status=500, body=render_error_page(500, exc, traceback=sio.read()), content_type='text/html')
            return response(environ, start_response)
    return application

def make_cmd_invocation(invocation, args, kwargs):
    """>>> make_cmd_invocation('path/program', ['arg1', 'arg2'], {'darg': 4})
    ['./giotto-cmd', '/path/program/arg1/arg2/', '--darg=4']"""
    if not invocation.endswith('/'):
        invocation += '/'
    if not invocation.startswith('/'):
        invocation = '/' + invocation
    cmd = invocation
    for arg in args:
        cmd += str(arg) + '/'
    rendered_kwargs = []
    for k, v in kwargs.items():
        rendered_kwargs.append('--%s=%s' % (k, v))
    return ['./giotto-cmd', cmd] + rendered_kwargs

def create_module(module, target):
    """Create a module directory structure into the target directory."""
    module_x = module.split('.')
    cur_path = ''
    for path in module_x:
        cur_path = os.path.join(cur_path, path)
        if not os.path.isdir(os.path.join(target, cur_path)):
            os.mkdir(os.path.join(target, cur_path))
        if not os.path.exists(os.path.join(target, cur_path, '__init__.py')):
            touch(os.path.join(target, cur_path, '__init__.py'))
    return cur_path

def get_file_extension(filename):
    """Return the extension if the filename has it. None if not.

    :param filename: The filename.
    :return: Extension or None."""
    filename_x = filename.split('.')
    if len(filename_x) > 1:
        if filename_x[-1].strip() is not '':
            return filename_x[-1]
    return None

def monitor(seconds_frozen, test_interval):
    """Monitoring thread function.

    Checks if thread is hanging for time defined by
    ``seconds_frozen`` parameter every ``test_interval`` milliseconds."""
    current_thread = threading.current_thread()
    hanging_threads = set()
    old_threads = {}
    while not current_thread.is_stopped():
        new_threads = get_current_frames()
        for thread_id in old_threads.keys():
            if thread_id not in new_threads and thread_id in hanging_threads:
                log_died_thread(thread_id)
        time.sleep(test_interval / 1000.0)
        now = time.time()
        then = now - seconds_frozen
        for thread_id, thread_data in new_threads.items():
            if thread_id == current_thread.ident:
                continue
            frame = thread_data['frame']
            if thread_id not in old_threads or frame != old_threads[thread_id]['frame']:
                thread_data['time'] = now
                if thread_id in hanging_threads:
                    hanging_threads.remove(thread_id)
                    log_awaked_thread(thread_id)
            else:
                last_change_time = old_threads[thread_id]['time']
                thread_data['time'] = last_change_time
                if thread_id not in hanging_threads and last_change_time < then:
                    hanging_threads.add(thread_id)
                    log_hanged_thread(thread_id, frame)
        old_threads = new_threads

def get_current_frames():
    """Return current threads prepared for
    further processing."""
    return dict(((thread_id, {'frame': thread2list(frame), 'time': None}) for thread_id, frame in sys._current_frames().items()))

def write_log(title, message=''):
    """Write formatted log message to stderr."""
    sys.stderr.write(''.join([title.center(40).center(60, '-'), '\n', message]))

def parse_kwargs(kwargs):
    """Convert a list of kwargs into a dictionary. Duplicates of the same keyword
    get added to an list within the dictionary.

    >>> parse_kwargs(['--var1=1', '--var2=2', '--var1=3']
    {'var1': [1, 3], 'var2': 2}"""
    d = defaultdict(list)
    for k, v in ((k.lstrip('-'), v) for k, v in (a.split('=') for a in kwargs)):
        d[k].append(v)
    ret = {}
    for k, v in d.items():
        if len(v) == 1 and type(v) is list:
            ret[k] = v[0]
        else:
            ret[k] = v
    return ret

def htmlize_list(items):
    """Turn a python list into an html list."""
    out = ['<ul>']
    for item in items:
        out.append('<li>' + htmlize(item) + '</li>')
    out.append('</ul>')
    return '\n'.join(out)

def pre_process_json(obj):
    """Preprocess items in a dictionary or list and prepare them to be json serialized."""
    if type(obj) is dict:
        new_dict = {}
        for key, value in obj.items():
            new_dict[key] = pre_process_json(value)
        return new_dict
    elif type(obj) is list:
        new_list = []
        for item in obj:
            new_list.append(pre_process_json(item))
        return new_list
    elif hasattr(obj, 'todict'):
        return dict(obj.todict())
    else:
        try:
            json.dumps(obj)
        except TypeError:
            try:
                json.dumps(obj.__dict__)
            except TypeError:
                return str(obj)
            else:
                return obj.__dict__
        else:
            return obj

def render_error_page(code, exc, mimetype='text/html', traceback=''):
    """Render the error page"""
    from giotto.views import get_jinja_template
    if 'json' in mimetype:
        return json.dumps({'code': code, 'exception': exc.__class__.__name__, 'message': str(exc)})
    et = get_config('error_template')
    if not et:
        return '%s %s\n%s' % (code, str(exc), traceback)
    template = get_jinja_template(et)
    return template.render(code=code, exception=exc.__class__.__name__, message=str(exc), traceback=traceback)

def slugify(value):
    """Converts to lowercase, removes non-word characters (alphanumerics and
    underscores) and converts spaces to hyphens. Also strips leading and
    trailing whitespace."""
    if six.PY3:
        value = str(value)
    else:
        value = unicode(value)
    value = unicodedata.normalize('NFKD', value).encode('ascii', 'ignore').decode('ascii')
    value = to_remove.sub('', value).strip().lower()
    return remove_dup.sub('-', value)

def log_level_from_string(str_level):
    """Returns the proper log level core based on a given string

    :param str_level: Log level string
    :return: The log level code"""
    levels = {'CRITICAL': logging.CRITICAL, 'ERROR': logging.ERROR, 'WARNING': logging.WARNING, 'INFO': logging.INFO, 'DEBUG': logging.DEBUG}
    try:
        return levels[str_level.upper()]
    except KeyError:
        pass
    except AttributeError:
        if str_level in [logging.DEBUG, logging.INFO, logging.WARNING, logging.ERROR, logging.CRITICAL]:
            return str_level
    return logging.NOTSET

def process_config(config, config_data):
    """Populates config with data from the configuration data dict. It handles
    components, data, log, management and session sections from the
    configuration data.

    :param config: The config reference of the object that will hold the
    configuration data from the config_data.
    :param config_data: The configuration data loaded from a configuration
    file."""
    if 'components' in config_data:
        process_components_config_section(config, config_data['components'])
    if 'data' in config_data:
        process_data_config_section(config, config_data['data'])
    if 'log' in config_data:
        process_log_config_section(config, config_data['log'])
    if 'management' in config_data:
        process_management_config_section(config, config_data['management'])
    if 'session' in config_data:
        process_session_config_section(config, config_data['session'])

def process_components_config_section(config, components_config):
    """Processes the components section from a configuration data dict.

    :param config: The config reference of the object that will hold the
    configuration data from the config_data.
    :param components_config: Data section from a config data dict."""
    for component_config in components_config:
        if 'id' not in component_config:
            raise Exception('The component %s was defined without an id.' % component_config)
        component_id = component_config['id']
        if component_id not in config.components:
            config.components[component_id] = {}
            config.components[component_id]['enabled'] = False
            config.components[component_id]['config'] = {}
        if 'class' in component_config:
            class_config_x = component_config['class'].split('.')
            config.components[component_id]['class'] = class_config_x[-1]
            config.components[component_id]['module'] = '.'.join(class_config_x[:-1])
        if 'enabled' in component_config:
            config.components[component_id]['enabled'] = bool(component_config['enabled'])

def process_data_config_section(config, data_config):
    """Processes the data configuration section from the configuration
    data dict.

    :param config: The config reference of the object that will hold the
    configuration data from the config_data.
    :param data_config: Data configuration section from a config data dict."""
    if 'connectors' in data_config:
        for connector in data_config['connectors']:
            config.data['connectors'][connector['name']] = get_config_from_package(connector['class'])
    if 'sources' in data_config:
        if data_config['sources']:
            for source in data_config['sources']:
                config.data['sources'][source['name']] = source
                del config.data['sources'][source['name']]['name']

def process_log_config_section(config, log_config):
    """Processes the log section from a configuration  data dict.

    :param config: The config reference of the object that will hold the
    configuration data from the config_data.
    :param log_config: Log section from a config data dict."""
    if 'format' in log_config:
        config.log['format'] = log_config['format']
    if 'level' in log_config:
        config.log['level'] = log_level_from_string(log_config['level'])

def run_from_command_line():
    """Run Firenado's management commands from a command line
    """
    for commands_conf in firenado.conf.management['commands']:
        logger.debug('Loading %s commands from %s.' % (commands_conf['name'], commands_conf['module']))
        exec('import %s' % commands_conf['module'])
    command_index = 1
    for arg in sys.argv[1:]:
        command_index += 1
        if arg[0] != '-':
            break
    parser = FirenadoArgumentParser(prog=os.path.split(sys.argv[0])[1], add_help=False)
    parser.add_argument('-h', '--help', default=argparse.SUPPRESS)
    parser.add_argument('command', default='help', help='Command to executed')
    try:
        namespace = parser.parse_args(sys.argv[1:command_index])
        if not command_exists(namespace.command):
            show_command_line_usage(parser)
        else:
            run_command(namespace.command, sys.argv[command_index - 1:])
    except FirenadoArgumentError:
        show_command_line_usage(parser, True)

def command_exists(command):
    """Check if the given command was registered. In another words if it
    exists."""
    for category, commands in iteritems(command_categories):
        for existing_command in commands:
            if existing_command.match(command):
                return True
    return False

def run_command(command, args):
    """Run all tasks registered in a command.
    """
    for category, commands in iteritems(command_categories):
        for existing_command in commands:
            if existing_command.match(command):
                existing_command.run(args)

def LoginView(http_redirect=None):
    """After logging in, redirect the user to the ``http_redirect`` program.
    This is a meta program, a function that returns a program.
    ``http_redirect`` can be either a string, or a three item tuple with M objects:
    http_redirect=('/blog', [m.id], {}) | http_redirect=('/blog', [], {'name': M['name']})"""
    class LoginView(GiottoView):
        """``result`` is the session that was newly created. consult the
        ``create_session`` model for reference."""
        @renders('text/html')
        def html(self, result):
            ty = type(http_redirect)
            if ty == list or ty == tuple:
                assert len(http_redirect) == 3, 'http_redirect must be three items'
                return Redirection(http_redirect[0], args=http_redirect[1], kwargs=http_redirect[2])
            else:
                return Redirection(http_redirect)
    return LoginView

def read_requirements_file(path):
    """reads requirements.txt file and handles PyPI index URLs
    :param path: (str) path to requirements.txt file
    :return: (tuple of lists)"""
    last_pypi_url = None
    with open(path) as f:
        requires = []
        pypi_urls = []
        for line in f.readlines():
            if not line:
                continue
            if '--' in line:
                match = re.match('--index-url\\s+([\\w\\d:/.-]+)\\s', line)
                if match:
                    last_pypi_url = match.group(1)
                    if not last_pypi_url.endswith('/'):
                        last_pypi_url += '/'
            else:
                if last_pypi_url:
                    pypi_urls.append(last_pypi_url + line.strip().lower())
                requires.append(line)
    return (requires, pypi_urls)

def jinja_template(template_name, name='data', mimetype='text/html'):
    """Meta-renderer for rendering jinja templates"""
    def jinja_renderer(result, errors):
        template = get_jinja_template(template_name)
        context = {name: result or Mock(), 'errors': errors, 'enumerate': enumerate}
        rendered = template.render(**context)
        return {'body': rendered, 'mimetype': mimetype}
    return jinja_renderer

def lazy_jinja_template(template_name, name='data', mimetype='text/html'):
    """Jinja template renderer that does not render the template at all.
    Instead of returns the context and template object blended together.
    Make sure to add ``giotto.middleware.RenderLazytemplate`` to the output
    middleware stread of any program that uses this renderer."""
    def lazy_jinja_renderer(result, errors):
        template = get_jinja_template(template_name)
        context = {name: result or Mock(), 'errors': errors}
        data = ('jinja2', template, context)
        return {'body': data, 'mimetype': mimetype}
    return lazy_jinja_renderer

def emit(signal, *args, **kwargs):
    """Emits a single signal to call callbacks registered to respond to that signal.
    Optionally accepts args and kwargs that are passed directly to callbacks.

    :param signal: Signal to send"""
    for callback in set(receivers[signal]):
        _call(callback, args=args, kwargs=kwargs)

def _emit_twisted(signal, *args, **kwargs):
    """Emits a single signal to call callbacks registered to respond to that signal.
    Optionally accepts args and kwargs that are passed directly to callbacks.

    :param signal: Signal to send"""
    errback = kwargs.pop('errback', lambda f: f)
    dl = []
    for callback in set(receivers[signal]):
        d = _call(callback, args=args, kwargs=kwargs)
        if d is not None:
            dl.append(d.addErrback(errback))
    def simplify(results):
        return [x[1] for x in results]
    from twisted.internet.defer import DeferredList
    return DeferredList(dl).addCallback(simplify)

def _call(callback, args=[], kwargs={}):
    """Calls a callback with optional args and keyword args lists. This method exists so
    we can inspect the `_max_calls` attribute that's set by `_on`. If this value is None,
    the callback is considered to have no limit. Otherwise, an integer value is expected
    and decremented until there are no remaining calls"""
    if not hasattr(callback, '_max_calls'):
        callback._max_calls = None
    if callback._max_calls is None:
        return _call_partial(callback, *args, **kwargs)
    if callback._max_calls <= 0:
        return disconnect(callback)
    callback._max_calls -= 1
    return _call_partial(callback, *args, **kwargs)

def on(signals, callback=None, max_calls=None):
    """Registers a single callback for receiving an event (or event list). Optionally,
    can specify a maximum number of times the callback should receive a signal. This
    method works as both a function and a decorator::

        smokesignal.on('foo', my_callback)

        @smokesignal.on('foo')
        def my_callback():
            pass

    :param signals: A single signal or list/tuple of signals that callback should respond to
    :param callback: A callable that should repond to supplied signal(s)
    :param max_calls: Integer maximum calls for callback. None for no limit."""
    if isinstance(callback, int) or callback is None:
        if isinstance(callback, int):
            callback, max_calls = (max_calls, callback)
        return partial(_on, signals, max_calls=max_calls)
    elif isinstance(callback, types.MethodType):
        def _callback(*args, **kwargs):
            return callback(*args, **kwargs)
        return _on(signals, _callback, max_calls=max_calls)
    else:
        return _on(signals, callback, max_calls=max_calls)

def _on(on_signals, callback, max_calls=None):
    """Proxy for `smokesignal.on`, which is compatible as both a function call and
    a decorator. This method cannot be used as a decorator

    :param signals: A single signal or list/tuple of signals that callback should respond to
    :param callback: A callable that should repond to supplied signal(s)
    :param max_calls: Integer maximum calls for callback. None for no limit."""
    if not callable(callback):
        raise AssertionError('Signal callbacks must be callable')
    if not isinstance(on_signals, (list, tuple)):
        on_signals = [on_signals]
    callback._max_calls = max_calls
    for signal in on_signals:
        receivers[signal].add(callback)
    if not hasattr(callback, 'responds_to'):
        callback.responds_to = partial(responds_to, callback)
    if not hasattr(callback, 'signals'):
        callback.signals = partial(signals, callback)
    if not hasattr(callback, 'disconnect'):
        callback.disconnect = partial(disconnect, callback)
    if not hasattr(callback, 'disconnect_from'):
        callback.disconnect_from = partial(disconnect_from, callback)
    return callback

def disconnect_from(callback, signals):
    """Removes a callback from specified signal registries and prevents it from responding
    to any emitted signal.

    :param callback: A callable registered with smokesignal
    :param signals: A single signal or list/tuple of signals"""
    if not isinstance(signals, (list, tuple)):
        signals = [signals]
    for signal in signals:
        if responds_to(callback, signal):
            receivers[signal].remove(callback)

def clear(*signals):
    """Clears all callbacks for a particular signal or signals"""
    signals = signals if signals else receivers.keys()
    for signal in signals:
        receivers[signal].clear()

def StaticServe(base_path='/views/static/'):
