def index(request, template_name='tagging_ext/index.html', min_size=0, limit=10):
    """min_size: Smallest size count accepted for a tag
    order_by: asc or desc by count
    limit: maximum number of tags to display

    TODO: convert the hand-written query to an ORM call. Right now I know
            this works with Sqlite3 and PostGreSQL."""
    query = '\n        SELECT tag_item.tag_id as tag_id, COUNT(tag_item.tag_id) as counter \n        FROM tagging_taggeditem as tag_item \n        GROUP BY tag_id\n        HAVING COUNT(tag_item.tag_id) > %s\n        ORDER BY counter desc\n        LIMIT %s\n    '
    cursor = connection.cursor()
    cursor.execute(query, [min_size, limit])
    results = []
    for row in cursor.fetchall():
        try:
            tag = Tag.objects.get(id=row[0])
        except ObjectDoesNotExist:
            continue
        if ' ' in tag.name:
            continue
        record = dict(tag=tag, count=row[1])
        results.append(record)
    dictionary = {'tags': results}
    return render_to_response(template_name, dictionary, context_instance=RequestContext(request))

def patch_ui_functions(wrapper):
    """Wrap all termui functions with a custom decorator."""
    NONE = object()
    import click
    saved = []
    for name, info in sorted(_ui_functions.items()):
        f = getattr(click, name, NONE)
        if f is NONE:
            continue
        new_f = wrapper(_copy_fn(f), info)
        argspec = getargspec(f)
        signature = inspect.formatargspec(*argspec).lstrip('(').rstrip(')')
        args = ', '.join((arg.split('=')[0].split(':')[0].strip() for arg in signature.split(',')))
        stub_f = eval('lambda {s}: {n}._real_click_fn({a})'.format(n=f.__name__, s=signature, a=args))
        if PY2:
            saved.append((f, f.func_code))
            f.func_code = stub_f.func_code
        else:
            saved.append((f, f.__code__))
            f.__code__ = stub_f.__code__
        f._real_click_fn = new_f
    try:
        yield
    finally:
        for f, code in saved:
            if PY2:
                f.func_code = code
            else:
                f.__code__ = code
            del f._real_click_fn

def swf2png(swf_path, png_path, swfrender_path='swfrender'):
    """Convert SWF slides into a PNG image

    Raises:
        OSError is raised if swfrender is not available.
        ConversionError is raised if image cannot be created."""
    try:
        cmd = [swfrender_path, swf_path, '-o', png_path]
        subprocess.check_output(cmd, stderr=subprocess.STDOUT)
    except subprocess.CalledProcessError as e:
        raise ConversionError('Failed to convert SWF file %s.\n\tCommand: %s\n\tExit status: %s.\n\tOutput:\n%s' % (swf_path, ' '.join(cmd), e.returncode, e.output))

def proxy_it(request, port):
    """Proxy HTTP request to upstream IPython Notebook Tornado server."""
    websocket_proxy = request.registry.settings.get('pyramid_notebook.websocket_proxy', '')
    if websocket_proxy.strip():
        r = DottedNameResolver()
        websocket_proxy = r.maybe_resolve(websocket_proxy)
    if 'upgrade' in request.headers.get('connection', '').lower():
        if websocket_proxy:
            return websocket_proxy(request, port)
        else:
            raise RuntimeError('Websocket proxy support is not configured.')
    proxy_app = WSGIProxyApplication(port)
    return request.get_response(proxy_app)

def prepare_notebook_context(request, notebook_context):
    """Fill in notebook context with default values."""
    if not notebook_context:
        notebook_context = {}
    if 'extra_template_paths' not in notebook_context:
        notebook_context['extra_template_paths'] = [os.path.join(os.path.dirname(__file__), 'server', 'templates')]
    assert type(notebook_context['extra_template_paths']) == list, 'Got bad extra_template_paths {}'.format(notebook_context['extra_template_paths'])
    notebook_context['jinja_environment_options'] = notebook_context.get('jinja_environment_options', {})
    assert type(notebook_context['jinja_environment_options']) == dict
    notebook_context['allow_origin'] = route_to_alt_domain(request, request.host_url)
    notebook_context['notebook_path'] = request.route_path('notebook_proxy', remainder='')
    if 'context_hash' not in notebook_context:
        notebook_context['context_hash'] = make_dict_hash(notebook_context)
    print(notebook_context)

def notebook_proxy(request, username):
    """Renders a IPython Notebook frame wrapper.

    Starts or reattachs ot an existing Notebook session."""
    security_check(request, username)
    manager = get_notebook_manager(request)
    notebook_info = manager.get_context(username)
    if not notebook_info:
        raise HTTPInternalServerError('Apparently IPython Notebook daemon process is not running for {}'.format(username))
    if 'http_port' not in notebook_info:
        raise RuntimeError('Notebook terminated prematurely before managed to tell us its HTTP port')
    return proxy_it(request, notebook_info['http_port'])

def make_dict_hash(o):
    """Make a hash from a dictionary, list, tuple or set to any level, containing
    only other hashable types (including any lists, tuples, sets, and dictionaries)."""
    if isinstance(o, (set, tuple, list)):
        return tuple([make_dict_hash(e) for e in o])
    elif not isinstance(o, dict):
        return hash(o)
    new_o = copy.deepcopy(o)
    for k, v in new_o.items():
        new_o[k] = make_dict_hash(v)
    return hash(tuple(frozenset(sorted(new_o.items()))))

def _generic_mixer(slice1, slice2, mixer_name, **kwargs):
    """Generic mixer to process two slices with appropriate mixer
        and return the composite to be displayed."""
    mixer_name = mixer_name.lower()
    if mixer_name in ['color_mix', 'rgb']:
        mixed = _mix_color(slice1, slice2, **kwargs)
        cmap = None
    elif mixer_name in ['checkerboard', 'checker', 'cb', 'checker_board']:
        checkers = _get_checkers(slice1.shape, **kwargs)
        mixed = _checker_mixer(slice1, slice2, checkers)
        cmap = 'gray'
    elif mixer_name in ['diff', 'voxelwise_diff', 'vdiff']:
        mixed, cmap = _diff_image(slice1, slice2, **kwargs)
    else:
        raise ValueError('Invalid mixer name chosen.')
    disp_params = dict(cmap=cmap)
    return (mixed, disp_params)

def check_rescaling(img1, img2, rescale_method):
    """Estimates the intensity range to clip the visualizations to"""
    if rescale_method is None:
        rescale_images = False
        min_value = None
        max_value = None
        norm_image = None
    elif isinstance(rescale_method, str):
        if rescale_method.lower() in ['global']:
            combined_distr = np.concatenate((img1.flatten(), img2.flatten()))
            min_value = combined_distr.min()
            max_value = combined_distr.max()
        elif rescale_method.lower() in ['each']:
            img1 = scale_0to1(img1)
            img2 = scale_0to1(img2)
            min_value = 0.0
            max_value = 1.0
        else:
            raise ValueError('rescaling method can only be "global" or "each"')
        rescale_images = True
        norm_image = mpl.colors.Normalize
    elif len(rescale_method) == 2:
        min_value = min(rescale_method)
        max_value = max(rescale_method)
        rescale_images = True
        norm_image = mpl.colors.Normalize
    else:
        raise ValueError('Invalid intensity range!. It must be either : 1) a list/tuple of two distinct values or2) "global" indicating rescaling based on min/max values derived from both images or3) None, no rescaling or norming altogether. ')
    return (rescale_images, img1, img2, min_value, max_value)

def check_images(img_spec1, img_spec2, bkground_thresh=0.05):
    """Reads the two images and assers identical shape."""
    img1 = read_image(img_spec1, bkground_thresh)
    img2 = read_image(img_spec2, bkground_thresh)
    if img1.shape != img2.shape:
        raise ValueError('size mismatch! First image: {} Second image: {}\nTwo images to be compared must be of the same size in all dimensions.'.format(img1.shape, img2.shape))
    return (img1, img2)

def _get_checkers(slice_shape, patch_size):
    """Creates checkerboard of a given tile size, filling a given slice."""
    if patch_size is not None:
        patch_size = check_patch_size(patch_size)
    else:
        patch_size = np.round(np.array(slice_shape) / 7).astype('int16')
        patch_size = np.maximum(patch_size, np.array([3, 3]))
    black = np.zeros(patch_size)
    white = np.ones(patch_size)
    tile = np.vstack((np.hstack([black, white]), np.hstack([white, black])))
    num_tiles = np.ceil(np.divide(slice_shape, tile.shape)).astype(int)
    checkers = np.tile(tile, num_tiles)
    if any(np.greater(checkers.shape, slice_shape)):
        if checkers.shape[0] > slice_shape[0]:
            checkers = np.delete(checkers, np.s_[slice_shape[0]:], axis=0)
        if checkers.shape[1] > slice_shape[1]:
            checkers = np.delete(checkers, np.s_[slice_shape[1]:], axis=1)
    return checkers

def prettify(elem):
    """Return a pretty-printed XML string for the Element."""
    rough_string = E.tostring(elem, 'utf-8')
    reparsed = minidom.parseString(rough_string)
    return reparsed.toprettyxml(indent='  ').strip()

def verify_email(request, code, redirect_to=None):
    """Verifies an account activation code a user received by e-mail.

    Requires Messages Django Contrib.

    :param Requset request:
    :param str code:
    :param str redirect_to:
    :return:"""
    success = False
    valid_code = EmailConfirmation.is_valid(code)
    if valid_code:
        valid_code.activate()
        success = True
    if success:
        messages.success(request, SIGNUP_VERIFY_EMAIL_SUCCESS_TEXT, 'success')
    else:
        messages.error(request, SIGNUP_VERIFY_EMAIL_ERROR_TEXT, 'danger error')
    if redirect_to is None:
        redirect_to = '/'
    return redirect(redirect_to)

def log_path(scraper):
    """Determine the file name for the JSON log."""
    return os.path.join(scraper.config.data_path, '%s.jsonlog' % scraper.name)

def _diff_image(slice1, slice2, abs_value=True, cmap='gray', **kwargs):
    """Computes the difference image"""
    diff = slice1 - slice2
    if abs_value:
        diff = np.abs(diff)
    return (diff, cmap)

def check_bounding_rect(rect_pos):
    """Ensure the rect spec is valid."""
    if not isinstance(rect_pos, Iterable):
        raise ValueError('rectangle spect must be a tuple of floats specifying (left, right, width, height)')
    left, bottom, width, height = rect_pos
    for val, name in zip((left, bottom, width, height), ('left', 'bottom', 'width', 'height')):
        if val < 0.0 or val > 1.0:
            raise ValueError("{}'s value must be >=0 and <= 1.0. It is now {}".format(name, val))
    if left + width > 1.0:
        print('rect would extend beyond the width of figure/axis by {}'.format(left + width - 1.0))
    if bottom + height > 1.0:
        print('rect would extend beyond the height of figure/axis by {}'.format(bottom + height - 1.0))
    return rect_pos

def check_views(view_set, max_views=3):
    """Ensures valid view/dimensions are selected."""
    if not isinstance(view_set, Iterable):
        view_set = tuple([view_set])
    if len(view_set) > max_views:
        raise ValueError('Can only have {} views'.format(max_views))
    return [check_int(view, 'view', min_value=0, max_value=max_views - 1) for view in view_set]

def check_num_slices(num_slices, img_shape=None, num_dims=3):
    """Ensures requested number of slices is valid.

    Atleast 1 and atmost the image size, if available"""
    if not isinstance(num_slices, Iterable) or len(num_slices) == 1:
        num_slices = np.repeat(num_slices, num_dims)
    if img_shape is not None:
        if len(num_slices) != len(img_shape):
            raise ValueError('The number of dimensions requested is different from image. Must be either 1 or equal to {}'.format(len(img_shape) + 1))
        num_slices = np.minimum(img_shape, num_slices)
    return np.maximum(1, num_slices)

def check_int(num, num_descr='number', min_value=0, max_value=np.Inf):
    """Validation and typecasting."""
    if not np.isfinite(num) or num < min_value or num > max_value:
        raise ValueError('{}={} is not finite or is not >= {} or is not < {}'.format(num_descr, num, min_value, max_value))
    return int(num)

def check_patch_size(patch_size):
    """Validation and typcasting"""
    patch_size = np.array(patch_size)
    if patch_size.size == 1:
        patch_size = np.repeat(patch_size, 2).astype('int16')
    return patch_size

def check_params(num_rows, num_cols, padding):
    """Validation and typcasting"""
    num_rows = check_int(num_rows, 'num_rows', min_value=1)
    num_cols = check_int(num_cols, 'num_cols', min_value=1)
    padding = check_int(padding, 'padding', min_value=0)
    return (num_rows, num_cols, padding)

def read_image(img_spec, bkground_thresh, ensure_num_dim=3):
    """Image reader, with additional checks on size.

    Can optionally remove stray values close to zero (smaller than 5 %ile)."""
    img = load_image_from_disk(img_spec)
    if not np.issubdtype(img.dtype, np.floating):
        img = img.astype('float32')
    if ensure_num_dim == 3:
        img = check_image_is_3d(img)
    elif ensure_num_dim == 4:
        img = check_image_is_4d(img)
    return threshold_image(img, bkground_thresh)

def load_image_from_disk(img_spec):
    """Vanilla image loader."""
    if isinstance(img_spec, str):
        if pexists(realpath(img_spec)):
            hdr = nib.load(img_spec)
            hdr = nib.as_closest_canonical(hdr)
            img = hdr.get_data()
        else:
            raise IOError('Given path to image does not exist!')
    elif isinstance(img_spec, np.ndarray):
        img = img_spec
    else:
        raise ValueError('Invalid input specified! Input either a path to image data, or provide 3d Matrix directly.')
    return img

def check_image_is_3d(img):
    """Ensures the image loaded is 3d and nothing else."""
    if len(img.shape) < 3:
        raise ValueError('Input volume must be atleast 3D!')
    elif len(img.shape) == 3:
        for dim_size in img.shape:
            if dim_size < 1:
                raise ValueError('Atleast one slice must exist in each dimension')
    elif len(img.shape) == 4:
        if img.shape[3] != 1:
            raise ValueError('Input volume is 4D with more than one volume!')
        else:
            img = np.squeeze(img, axis=3)
    elif len(img.shape) > 4:
        raise ValueError('Invalid shape of image : {}'.format(img.shape))
    return img

def check_image_is_4d(img, min_num_volumes=2):
    """Ensures the image loaded is 3d and nothing else."""
    if len(img.shape) < 4:
        raise ValueError('Input volume must be 4D!')
    elif len(img.shape) == 4:
        for dim_size in img.shape[:3]:
            if dim_size < 1:
                raise ValueError('Atleast one slice must exist in each dimension')
        if img.shape[3] < min_num_volumes:
            raise ValueError('Input volume is 4D with less than {} volumes!'.format(min_num_volumes))
    elif len(img.shape) > 4:
        raise ValueError('Too many dimensions : more than 4.\nInvalid shape of image : {}'.format(img.shape))
    return img

def crop_to_seg_extents(img, seg, padding):
    """Crop the image (usually MRI) to fit within the bounding box of a segmentation (or set of seg)"""
    beg_coords, end_coords = crop_coords(seg, padding)
    img = crop_3dimage(img, beg_coords, end_coords)
    seg = crop_3dimage(seg, beg_coords, end_coords)
    return (img, seg)

def crop_image(img, padding=5):
    """Crops an image or slice to its extents"""
    if padding < 1:
        return img
    beg_coords, end_coords = crop_coords(img, padding)
    if len(img.shape) == 3:
        img = crop_3dimage(img, beg_coords, end_coords)
    elif len(img.shape) == 2:
        img = crop_2dimage(img, beg_coords, end_coords)
    else:
        raise ValueError('Can only crop 2D or 3D images!')
    return img

def crop_coords(img, padding):
    """Find coordinates describing extent of non-zero portion of image, padded"""
    coords = np.nonzero(img)
    empty_axis_exists = np.any([len(arr) == 0 for arr in coords])
    if empty_axis_exists:
        end_coords = img.shape
        beg_coords = np.zeros((1, img.ndim)).astype(int).flatten()
    else:
        min_coords = np.array([arr.min() for arr in coords])
        max_coords = np.array([arr.max() for arr in coords])
        beg_coords = np.fmax(0, min_coords - padding)
        end_coords = np.fmin(img.shape, max_coords + padding)
    return (beg_coords, end_coords)

def verify_sampler(sampler, image, image_shape, view_set, num_slices):
    """verifies the sampler requested is valid."""
    if isinstance(sampler, str):
        sampler = sampler.lower()
        if sampler not in ['linear']:
            raise ValueError('Sampling strategy: {} not implemented.'.format(sampler))
        out_sampler = sampler
        out_sampling_method = 'linear'
    elif isinstance(sampler, Iterable):
        if any([index < 0 or index > 100 for index in sampler]):
            raise ValueError('sampling percentages must be in  [0-100]% range')
        if len(sampler) > min(num_slices):
            num_slices = np.maximum(num_slices, len(sampler))
        out_sampler = np.array(sampler)
        out_sampling_method = 'percentage'
    elif callable(sampler):
        for view in view_set:
            middle_slice = int(image_shape[view] / 2)
            if not isinstance(sampler(get_axis(image, view, middle_slice)), bool):
                raise ValueError('sampler callable must return a boolean value (True/False)')
        out_sampler = sampler
        out_sampling_method = 'callable'
    else:
        raise NotImplementedError('Invalid choice for sampler! Choose one of: linear, percentage or callable')
    return (out_sampler, out_sampling_method, num_slices)

def get_username_max_len():
    """Returns username maximum length as supported by Django.

    :rtype: int"""
    fields = [field for field in USER._meta.fields if field.name == 'username']
    try:
        length = fields[0].max_length
    except IndexError:
        length = 30
    return length

def tag_builder(parser, token, cls, flow_type):
    """Helper function handling flow form tags."""
    tokens = token.split_contents()
    tokens_num = len(tokens)
    if tokens_num == 1 or (tokens_num == 3 and tokens[1] == 'for'):
        flow_name = None
        if tokens_num == 3:
            flow_name = tokens[2]
        return cls(flow_name)
    else:
        raise template.TemplateSyntaxError('"sitegate_%(type)s_form" tag requires zero or two arguments. E.g. {%% sitegate_%(type)s_form %%} or {%% sitegate_%(type)s_form for ClassicSignup %%}.' % {'type': flow_type})

def sitegate_view(*args_dec, **kwargs_dec):
    """Decorator to mark views used both for signup & sign in."""
    if len(args_dec):
        return signup_view(signin_view(redirect_signedin(*args_dec, **kwargs_dec)))
    signin = signin_view(**kwargs_dec)
    signup = signup_view(**kwargs_dec)
    return lambda *args, **kwargs: signup(signin(redirect_signedin(*args, **kwargs)))

def decode_ulid_base32(encoded):
    """Decode a 26-character long base32 string into the original 16 bytes.
    :param encoded: 26-character long string
    :return: 16 bytes"""
    if len(encoded) != 26:
        raise InvalidULID('base32 ulid is %d characters long, expected 26' % len(encoded))
    if not all((c in _symbols for c in encoded)):
        raise InvalidULID('invalid characters in base32 ulid')
    b = [ord(c) for c in encoded]
    if b[0] < 48 or b[0] > 55:
        raise InvalidULID('base32 ulid is out of range (starts with %s; accepted are 01234567)' % encoded[0])
    tab = _decode_table
    binary = [c & 255 for c in [tab[b[0]] << 5 | tab[b[1]], tab[b[2]] << 3 | tab[b[3]] >> 2, tab[b[3]] << 6 | tab[b[4]] << 1 | tab[b[5]] >> 4, tab[b[5]] << 4 | tab[b[6]] >> 1, tab[b[6]] << 7 | tab[b[7]] << 2 | tab[b[8]] >> 3, tab[b[8]] << 5 | tab[b[9]], tab[b[10]] << 3 | tab[b[11]] >> 2, tab[b[11]] << 6 | tab[b[12]] << 1 | tab[b[13]] >> 4, tab[b[13]] << 4 | tab[b[14]] >> 1, tab[b[14]] << 7 | tab[b[15]] << 2 | tab[b[16]] >> 3, tab[b[16]] << 5 | tab[b[17]], tab[b[18]] << 3 | tab[b[19]] >> 2, tab[b[19]] << 6 | tab[b[20]] << 1 | tab[b[21]] >> 4, tab[b[21]] << 4 | tab[b[22]] >> 1, tab[b[22]] << 7 | tab[b[23]] << 2 | tab[b[24]] >> 3, tab[b[24]] << 5 | tab[b[25]]]]
    return _to_binary(binary)

def ulid_to_binary(ulid):
    """Convert an ULID to its binary representation.

    :param ulid: An ULID (either as UUID, base32 ULID or binary)
    :return: Bytestring of length 16
    :rtype: bytes"""
    if isinstance(ulid, uuid.UUID):
        return ulid.bytes
    if isinstance(ulid, (text_type, bytes)) and len(ulid) == 26:
        return decode_ulid_base32(ulid)
    if isinstance(ulid, (bytes, bytearray)) and len(ulid) == 16:
        return ulid
    raise InvalidULID('can not convert ulid %r to binary' % ulid)

def collapse_whitespace(text):
    """Collapse all consecutive whitespace, newlines and tabs
    in a string into single whitespaces, and strip the outer
    whitespace. This will also accept an ``lxml`` element and
    extract all text."""
    if text is None:
        return None
    if hasattr(text, 'xpath'):
        text = text.xpath('string()')
    text = re.sub('\\s+', ' ', text)
    return text.strip()

def dbg(message, *args):
    """Looks at the stack, to see if a debug message should be printed."""
    if debug_function and enable_notice:
        frm = inspect.stack()[1]
        mod = inspect.getmodule(frm[0])
        if not mod.__name__ in ignored_modules:
            i = ' ' * _debug_indent
            debug_function(NOTICE, i + 'dbg: ' + message % args)

def print_to_stdout(level, str_out):
    """The default debug function"""
    if level == NOTICE:
        col = Fore.GREEN
    elif level == WARNING:
        col = Fore.RED
    else:
        col = Fore.YELLOW
    if not is_py3:
        str_out = str_out.encode(encoding, 'replace')
    print(col + str_out + Fore.RESET)

def count_dimensions(entry):
    """Counts the number of dimensions from a nested list of dimension assignments
    that may include function calls."""
    result = 0
    for e in entry:
        if isinstance(e, str):
            sliced = e.strip(',').split(',')
            result += 0 if len(sliced) == 1 and sliced[0] == '' else len(sliced)
    return result

def _field_lookups(model, status=None):
    """Abstraction of field lookups for managers.

    Returns a dictionary of field lookups for a queryset. The lookups
    will always filter by site. Optionally, if ``status`` is passed to
    the function the objects will also be filtered by the given status.

    This function saves from having to make two different on-site and
    published Managers each for `Topic` and `Question`, and having to move
    Managers out of the `FAQBase` model and into each of the `Topic`
    and `Question` models."""
    from faq.models import Topic, Question
    field_lookups = {}
    if model == Topic:
        field_lookups['sites__pk'] = settings.SITE_ID
    if model == Question:
        field_lookups['topic__sites__pk'] = settings.SITE_ID
        if status:
            field_lookups['topic__status'] = status
    if status:
        field_lookups['status'] = status
    return field_lookups

def static_symbol(module, method, lib, bindc=False):
    """Returns the symbol for the specified *fortran* module and subroutine/function
    that has been compiled into a shared library.

    :arg lib: the full path to the shared library *.so file."""
    from os import path
    from numpy.ctypeslib import load_library
    libpath = path.abspath(lib)
    libkey = libpath.lower()
    if libkey not in compilers:
        compilers[libkey] = detect_compiler(libpath)
        if compilers[libkey] == False:
            raise ValueError("Couldn't auto-detect the compiler for {}".format(libpath))
    compiler = compilers[libkey]
    if libkey not in libs:
        libs[libkey] = load_library(libpath, '')
        if not libs[libkey]:
            raise ValueError("Couldn't auto-load the shared library with ctypes.")
    slib = libs[libkey]
    identifier = '{}.{}'.format(module, method)
    if bindc:
        symbol = method
    elif compiler == 'gfortran':
        symbol = '__' + identifier.lower().replace('.', '_MOD_')
    else:
        symbol = identifier.lower().replace('.', '_mp_') + '_'
    if hasattr(slib, symbol):
        return getattr(slib, symbol)
    else:
        return None

def load_python_object(name):
    """Loads a python module from string"""
    logger = getLoggerWithNullHandler('commando.load_python_object')
    module_name, _, object_name = name.rpartition('.')
    if module_name == '':
        module_name, object_name = (object_name, module_name)
    try:
        logger.debug('Loading module [%s]' % module_name)
        module = __import__(module_name)
    except ImportError:
        raise CommandoLoaderException('Module [%s] cannot be loaded.' % module_name)
    if object_name == '':
        return module
    try:
        module = sys.modules[module_name]
    except KeyError:
        raise CommandoLoaderException('Error occured when loading module [%s]' % module_name)
    try:
        logger.debug('Getting object [%s] from module [%s]' % (object_name, module_name))
        return getattr(module, object_name)
    except AttributeError:
        raise CommandoLoaderException('Cannot load object [%s]. Module [%s] does not contain object [%s]. Please fix the configuration or ensure that the module is installed properly' % (name, module_name, object_name))

def getLoggerWithConsoleHandler(logger_name=None):
    """Gets a logger object with a pre-initialized console handler."""
    logger = logging.getLogger(logger_name)
    logger.setLevel(logging.INFO)
    if not logger.handlers:
        handler = logging.StreamHandler(sys.stdout)
        if sys.platform == 'win32':
            formatter = logging.Formatter(fmt='%(asctime)s %(name)s %(message)s', datefmt='%H:%M:%S')
        else:
            formatter = ColorFormatter(fmt='$RESET %(asctime)s $BOLD$COLOR%(name)s$RESET %(message)s', datefmt='%H:%M:%S')
        handler.setFormatter(formatter)
        logger.addHandler(handler)
    return logger

def tag(request, tag_id=None):
    """The view used to render a tag after the page has loaded."""
    html = get_tag_html(tag_id)
    t = template.Template(html)
    c = template.RequestContext(request)
    return HttpResponse(t.render(c))

def _isense_builtin_symbol(symbol):
    """Returns the symbol with modifications according to settings in the
    <isense> configuration section."""
    if 'builtin' in config.isense and 'uppercase' in config.isense['builtin']:
        if config.isense['builtin']['uppercase'] == 'true':
            return symbol.upper()
        else:
            return symbol.lower()
    else:
        return symbol.lower()

def _load_builtin_xml(xmlpath, parser):
    """Loads the builtin function specifications from the builtin.xml file.

    :arg parser: the DocParser instance for parsing the XML tags."""
    result = {}
    el = ET.parse(xmlpath).getroot()
    if el.tag == 'builtin':
        for child in el:
            anexec = _parse_xml(child, parser)
            result[anexec.name.lower()] = anexec
    return result

def _parse_xml(child, parser):
    """Parses the specified child XML tag and creates a Subroutine or
    Function object out of it."""
    name, modifiers, dtype, kind = _parse_common(child)
    name = _isense_builtin_symbol(name)
    if child.tag == 'subroutine':
        parent = Subroutine(name, modifiers, None)
    elif child.tag == 'function':
        parent = Function(name, modifiers, dtype, kind, None)
    if parent is not None:
        for kid in child:
            if kid.tag == 'parameter':
                _parse_parameter(kid, parser, parent)
            elif kid.tag == 'summary':
                _parse_summary(kid, parser, parent)
            elif kid.tag == 'usage':
                _parse_usage(kid, parser, parent)
    return parent

def _parse_parameter(tag, parser, parent):
    """Creates a ValueElement instance from the specified <parameter> XML tag."""
    name, modifiers, dtype, kind = _parse_common(tag)
    if 'default' in tag.attrib:
        default = tag.attrib['default']
    else:
        default = None
    if 'dimension' in tag.attrib:
        dimension = tag.attrib['dimension']
    else:
        dimension = None
    result = ValueElement(name, modifiers, dtype, kind, default, dimension, parent)
    doc = DocElement(tag, parser, result)
    result.docstring.append(doc)
    parent.add_parameter(result)

def _parse_common(tag):
    """Returns a tuple of (name, modifiers, dtype, kind)
    for the specified tag. Any missing attributes will have values of None."""
    if 'modifiers' in tag.attrib:
        modifiers = re.split(',\\s*', tag.attrib['modifiers'].strip())
        if '' in modifiers:
            modifiers.remove('')
    else:
        modifiers = None
    if 'name' in tag.attrib:
        name = tag.attrib['name']
    if 'type' in tag.attrib:
        dtype = tag.attrib['type']
    else:
        dtype = None
    if 'kind' in tag.attrib:
        kind = tag.attrib['kind']
    else:
        kind = None
    return (name, modifiers, dtype, kind)

def _parse():
    """Parses the specified Fortran source file from which the wrappers will
    be constructed for ctypes."""
    if not args['reparse']:
        settings.use_filesystem_cache = False
    c = CodeParser()
    if args['verbose']:
        c.verbose = True
    if args['reparse']:
        c.reparse(args['source'])
    else:
        c.parse(args['source'])
    return c

def printer(text, color=None, **kwargs):
    """Prints using color or standard print() depending on the value
    of 'nocolor'."""
    if nocolor:
        print(text, **kwargs)
    elif color is None:
        cprint(text, **kwargs)
    else:
        cprint(text, color, **kwargs)

def arb(text, cols, split):
    """Prints a line of text in arbitrary colors specified by the numeric
    values contained in msg.cenum dictionary."""
    stext = text if text[-1] != split else text[0:-1]
    words = stext.split(split)
    for i, word in enumerate(words):
        col = icols[cols[i]]
        printer(word, col, end='')
        if i < len(words) - 1:
            printer(split, end='')
        else:
            printer(split)

def will_print(level=1):
    """Returns True if the current global status of messaging would print a
    message using any of the printing functions in this module."""
    if level == 1:
        return quiet is None or quiet == False
    else:
        return isinstance(verbosity, int) and level <= verbosity or (isinstance(verbosity, bool) and verbosity == True)

def warn(msg, level=0, prefix=True):
    """Prints the specified message as a warning; prepends "WARNING" to
    the message, so that can be left off."""
    if will_print(level):
        printer(('WARNING: ' if prefix else '') + msg, 'yellow')

def err(msg, level=-1, prefix=True):
    """Prints the specified message as an error; prepends "ERROR" to
    the message, so that can be left off."""
    if will_print(level) or verbosity is None:
        printer(('ERROR: ' if prefix else '') + msg, 'red')

def symlink(source, target, isfile=True):
    """Creates a symlink at target *file* pointing to source.

    :arg isfile: when True, if symlinking is disabled in the global config, the file
      is copied instead with fortpy.utility.copyfile; otherwise fortpy.utility.copy
      is used and the target is considered a directory."""
    from fortpy.code import config
    from os import path
    if config.symlink:
        from os import symlink, remove
        if path.isfile(target) or path.islink(target):
            remove(target)
        elif path.isdir(target):
            msg.warn("Cannot auto-delete directory '{}' for symlinking.".format(target))
            return
        symlink(source, target)
    else:
        msg.info('   COPY: {}'.format(source))
        if isfile:
            copyfile(source, target)
        else:
            copy(source, target)

def get_fortpy_templates_dir():
    """Gets the templates directory from the fortpy package."""
    import fortpy
    from os import path
    fortdir = path.dirname(fortpy.__file__)
    return path.join(fortdir, 'templates')

def set_fortpy_templates(obj, fortpy_templates=None):
    """Sets the directory path for the fortpy templates. If no directory
    is specified, use the default one that shipped with the package."""
    from os import path
    if fortpy_templates is not None:
        obj.fortpy_templates = path.abspath(path.expanduser(fortpy_templates))
    else:
        from fortpy.utility import get_fortpy_templates_dir
        obj.fortpy_templates = get_fortpy_templates_dir()

def get_dir_relpath(base, relpath):
    """Returns the absolute path to the 'relpath' taken relative to the base
    directory.

    :arg base: the base directory to take the path relative to.
    :arg relpath: the path relative to 'base' in terms of '.' and '..'."""
    from os import path
    xbase = path.abspath(path.expanduser(base))
    if not path.isdir(xbase):
        return path.join(xbase, relpath)
    if relpath[0:2] == './':
        return path.join(xbase, relpath[2:])
    else:
        from os import chdir, getcwd
        cd = getcwd()
        chdir(xbase)
        result = path.abspath(relpath)
        chdir(cd)
        return result

def wrap_line(line, limit=None, chars=80):
    """Wraps the specified line of text on whitespace to make sure that none of the
    lines' lengths exceeds 'chars' characters."""
    result = []
    builder = []
    length = 0
    if limit is not None:
        sline = line[0:limit]
    else:
        sline = line
    for word in sline.split():
        if length <= chars:
            builder.append(word)
            length += len(word) + 1
        else:
            result.append(' '.join(builder))
            builder = [word]
            length = 0
    result.append(' '.join(builder))
    return result

def XML(content, source=None):
    """Parses the XML text using the ET.XML function, but handling the ParseError in
    a user-friendly way."""
    try:
        tree = ET.XML(content)
    except ET.ParseError as err:
        x_parse_error(err, content, source)
    return tree

def XML_fromstring(content, source=None):
    """Parses the XML string into a node tree. If an ParseError exception is raised,
    the error message is formatted nicely to show the badly formed XML to the user."""
    try:
        tree = ET.fromstring(content)
    except ET.ParseError as err:
        x_parse_error(err, content, source)
    return tree

def format(element):
    """Formats all of the docstrings in the specified element and its
    children into a user-friendly paragraph format for printing.

    :arg element: an instance of fortpy.element.CodeElement."""
    result = []
    if type(element).__name__ in ['Subroutine', 'Function']:
        _format_executable(result, element)
    elif type(element).__name__ == 'CustomType':
        _format_type(result, element)
    elif isinstance(element, ValueElement):
        _format_value_element(result, element)
    return '\n'.join(result)

def _format_type(lines, element, spacer=''):
    """Formats a derived type for full documentation output."""
    rlines = []
    rlines.append(element.signature)
    _format_summary(rlines, element)
    rlines.append('')
    _format_generic(rlines, element, ['summary'])
    if len(element.executables) > 0:
        rlines.append('\nEMBEDDED PROCEDURES')
        for key, value in list(element.executables.items()):
            rlines.append('  {}'.format(value.__str__()))
            target = value.target
            if target is not None:
                _format_executable(rlines, target, '  ')
    if len(element.members) > 0:
        rlines.append('\nEMBEDDED MEMBERS')
        for key, value in list(element.members.items()):
            _format_value_element(rlines, value, '  ')
    lines.extend([spacer + l for l in rlines])

def _format_summary(lines, element, spacer='  '):
    """Adds the element's summary tag to the lines if it exists."""
    summary = spacer + element.summary
    if element.summary == '':
        summary = spacer + 'No description given in XML documentation for this element.'
    lines.append(summary)

def _format_generic(lines, element, printed, spacer=''):
    """Generically formats all remaining docstrings and custom XML
    tags that don't appear in the list of already printed documentation.

    :arg printed: a list of XML tags for the element that have already
      been handled by a higher method."""
    for doc in element.docstring:
        if doc.doctype.lower() not in printed:
            lines.append(spacer + doc.__str__())

def _py_ex_argtype(executable):
    """Returns the code to create the argtype to assign to the methods argtypes
    attribute."""
    result = []
    for p in executable.ordered_parameters:
        atypes = p.argtypes
        if atypes is not None:
            result.extend(p.argtypes)
        else:
            print('No argtypes for: {}'.format(p.definition()))
    if type(executable).__name__ == 'Function':
        result.extend(executable.argtypes)
    return result

def _py_ctype(parameter):
    """Returns the ctypes type name for the specified fortran parameter.
    """
    ctype = parameter.ctype
    if ctype is None:
        raise ValueError("Can't bind ctypes py_parameter for parameter {}".format(parameter.definition()))
    return ctype.lower()

def _py_code_clean(lines, tab, executable):
    """Appends all the code lines needed to create the result class instance and populate
    its keys with all output variables."""
    count = 0
    allparams = executable.ordered_parameters
    if type(executable).__name__ == 'Function':
        allparams = allparams + [executable]
    for p in allparams:
        value = _py_clean(p, tab)
        if value is not None:
            count += 1
            lines.append(value)
    return count

def _py_ftype(parameter, tab):
    """Returns the code to declare an Ftype object that handles memory
    deallocation for Fortran return arrays that were allocated by the
    method called in ctypes."""
    splice = ', '.join(['{0}_{1:d}'.format(parameter.lname, i) for i in range(parameter.D)])
    return '{2}{0}_ft = Ftype({0}_o, [{1}], libpath)'.format(parameter.lname, splice, tab)

def _py_clean(parameter, tab):
    """Returns the code line to clean the output value of the specified parameter.
    """
    if 'out' in parameter.direction:
        if parameter.D > 0:
            if ':' in parameter.dimension and ('allocatable' in parameter.modifiers or 'pointer' in parameter.modifiers):
                if parameter.D == 1:
                    clarray = 'as_array({0}_o, ({0}_0.value,))'.format(parameter.lname)
                else:
                    splice = ', '.join(reversed(['{0}_{1:d}.value'.format(parameter.lname, i) for i in range(parameter.D)]))
                    clarray = 'as_array({0}_o, ({1}))'.format(parameter.lname, splice)
                assign = '{0}result.add("{1}", {2}, {1}_ft)'.format(tab, parameter.lname, clarray)
                fstr = _py_ftype(parameter, tab)
                return _py_check_optional(parameter, tab, [fstr, assign])
            else:
                return '{1}result.add("{0}", {0}_a)'.format(parameter.lname, tab)
        else:
            return '{1}result.add("{0}", {0}_c.value)'.format(parameter.lname, tab)

def _py_check_optional(parameter, tab, assign):
    """Returns the code to check for actual values when an out parameter is pure
    out/optional and doesn't have anything changed.

    :arg assign: the actual variable assignment value if the conditions pass."""
    if parameter.direction == '(out)':
        result = []
        checks = ['{0}_{1:d}.value==0'.format(parameter.lname, i) for i in range(parameter.D)]
        spacing = len(tab) + 2 + 3 + 3 + 2
        result.append('{}if not all([{}]):'.format(tab, present_params(checks, spacing, linecont=', ')))
        for line in assign:
            if assign is not None:
                result.append('{0}{1}'.format(tab, line))
        result.append('{}else:'.format(tab))
        result.append('{0}{0}result.add("{1}", None)'.format(tab, parameter.lname))
        return '\n'.join(result)
    else:
        return '\n'.join(assign)

def _py_code_variables(lines, executable, lparams, tab):
    """Adds the variable code lines for all the parameters in the executable.

    :arg lparams: a list of the local variable declarations made so far that need to be passed
      to the executable when it is called."""
    allparams = executable.ordered_parameters
    if type(executable).__name__ == 'Function':
        allparams = allparams + [executable]
    for p in allparams:
        _py_code_parameter(lines, p, 'invar', lparams, tab)
        if p.direction == '(out)':
            _py_code_parameter(lines, p, 'outvar', lparams, tab)
            _py_code_parameter(lines, p, 'indices', lparams, tab)
        else:
            _py_code_parameter(lines, p, 'indices', lparams, tab)
            _py_code_parameter(lines, p, 'outvar', lparams, tab)

def _py_code_parameter(lines, parameter, position, lparams, tab):
    """Appends the code to produce the parameter at the specified position in the executable.

    :arg position: one of ['invar', 'outvar', 'indices'].
    :arg lparams: a list of the local variable declarations made so far that need to be passed
      to the executable when it is called."""
    mdict = {'invar': _py_invar, 'outvar': _py_outvar, 'indices': _py_indices}
    line = mdict[position](parameter, lparams, tab)
    if line is not None:
        value, blank = line
        lines.append(tab + value)
        if blank:
            lines.append('')

def _py_invar(parameter, lparams, tab):
    """Returns the code to create the local input parameter that is coerced to have the
    correct type for ctypes interaction."""
    if 'in' in parameter.direction and parameter.D > 0:
        if parameter.direction == '(inout)' and ':' not in parameter.dimension:
            wstr = ', writeable'
        else:
            wstr = ''
        pytype = _py_pytype(parameter)
        lparams.append('{}_a'.format(parameter.lname))
        return ('{0}_a = require({0}, {1}, "F{2}")'.format(parameter.lname, pytype, wstr), False)
    elif parameter.D == 0:
        lparams.append('byref({}_c)'.format(parameter.lname))
        if parameter.direction == '(out)':
            initval = parameter.py_initval
            return ('{0}_c = {1}({2})'.format(parameter.lname, _py_ctype(parameter), initval), False)
        else:
            return ('{0}_c = {1}({0})'.format(parameter.lname, _py_ctype(parameter)), False)

def _py_outvar(parameter, lparams, tab):
    """Returns the code to produce a ctypes output variable for interacting with fortran.
    """
    if 'out' in parameter.direction and parameter.D > 0 and (':' in parameter.dimension) and ('allocatable' in parameter.modifiers or 'pointer' in parameter.modifiers):
        lparams.append('byref({}_o)'.format(parameter.lname))
        blank = True if parameter.direction == '(inout)' else False
        return ('{0}_o = POINTER({1})()'.format(parameter.lname, _py_ctype(parameter)), blank)

def _py_indices(parameter, lparams, tab):
    """Returns the code to produce py ctypes for the indices of the specified parameter
    that has D > 0."""
    if parameter.D > 0 and ':' in parameter.dimension:
        if 'in' in parameter.direction:
            indexstr = '{0}_{1:d} = c_int({0}_a.shape[{1:d}])'
        else:
            indexstr = '{0}_{1:d} = c_int(0)'
        lparams.extend(['byref({}_{})'.format(parameter.lname, i) for i in range(parameter.D)])
        joinstr = '\n' + tab
        blank = True if parameter.direction == '(out)' else False
        return (joinstr.join([indexstr.format(parameter.lname, i) for i in range(parameter.D)]), blank)

def _ctypes_code_parameter(lines, parameter, position):
    """Returns the code for the specified parameter being written into a subroutine wrapper.

    :arg position: one of ['indices', 'variable', 'out', 'regular', 'saved', 'assign', 'clean']"""
    mdict = {'indices': _ctypes_indices, 'variable': _ctypes_variables, 'out': _ctypes_out, 'regular': _ctypes_regular, 'saved': _ctypes_saved, 'assign': _ctypes_assign, 'clean': _ctypes_clean}
    line = mdict[position](parameter)
    if line is not None:
        value, blank = line
        lines.append(value)
        if blank:
            lines.append('')

def _ctypes_dtype(parameter):
    """Determines the ISO_C data type to use for describing the specified parameter.
    """
    ctype = parameter.ctype
    if ctype is None:
        if parameter.kind is not None:
            return '{}({})'.format(parameter.dtype, parameter.kind)
        else:
            return parameter.dtype
    else:
        return '{}({})'.format(parameter.dtype, ctype)

def _ctypes_splice(parameter):
    """Returns a list of variable names that define the size of each dimension.
    """
    params = parameter.ctypes_parameter()
    if parameter.direction == '(inout)' and ('allocatable' in parameter.modifiers or 'pointer' in parameter.modifiers):
        return ', '.join(params[1:-1])
    else:
        return ', '.join(params[1:])

def _ctypes_indices(parameter):
    """Returns code for parameter variable declarations specifying the size of each
    dimension in the specified parameter."""
    if parameter.dimension is not None and ':' in parameter.dimension:
        splice = _ctypes_splice(parameter)
        if 'out' in parameter.direction:
            return ('integer, intent(inout) :: {}'.format(splice), False)
        else:
            return ('integer, intent(in) :: {}'.format(splice), False)

def _ctypes_variables(parameter):
    """Returns the local parameter definition for implementing a Fortran wrapper subroutine
    for this parameter's parent executable."""
    if parameter.dimension is not None and ':' in parameter.dimension:
        if 'in' in parameter.direction or parameter.direction == '':
            splice = _ctypes_splice(parameter)
            name = parameter.ctypes_parameter()[0]
            if parameter.direction == '(inout)' and (not ('allocatable' in parameter.modifiers or 'pointer' in parameter.modifiers)):
                return (parameter.definition(optionals=False, customdim=splice), False)
            else:
                return ('{}, intent(in) :: {}({})'.format(parameter.strtype, name, splice), False)
    else:
        if parameter.dtype == 'logical':
            stype = _ctypes_dtype(parameter)
            suffix = '_c'
            modifiers = None
        elif hasattr(parameter, 'parameters'):
            stype = None
            suffix = '_f'
            modifiers = ['intent(out)']
        else:
            stype = None
            suffix = ''
            modifiers = None
        return (parameter.definition(ctype=stype, optionals=False, suffix=suffix, modifiers=modifiers), False)

def _ctypes_out(parameter):
    """Returns a parameter variable declaration for an output variable for the specified
    parameter."""
    if parameter.dimension is not None and ':' in parameter.dimension and ('out' in parameter.direction) and ('allocatable' in parameter.modifiers or 'pointer' in parameter.modifiers):
        if parameter.direction == '(inout)':
            return ('type(C_PTR), intent(inout) :: {}_o'.format(parameter.name), True)
        else:
            return ('type(C_PTR), intent(inout) :: {}_c'.format(parameter.name), True)

def _ctypes_regular(parameter):
    """Returns the code lines to define a *local* variable with the fortran types
    that has a matching signature to the wrapped executable."""
    if 'pointer' in parameter.modifiers or 'allocatable' in parameter.modifiers or 'target' in parameter.modifiers or (parameter.dtype == 'logical'):
        return (parameter.definition(local=True), False)

def _ctypes_saved(parameter):
    """Returns local variable declarations that create allocatable variables that can persist
    long enough to return their value through ctypes."""
    if 'out' in parameter.direction and parameter.dimension is not None and (':' in parameter.dimension) and ('allocatable' in parameter.modifiers or 'pointer' in parameter.modifiers):
        stype = _ctypes_dtype(parameter)
        name = '{}_t({})'.format(parameter.name, parameter.dimension)
        return ('{}, allocatable, target, save :: {}'.format(stype, name), True)

def _ctypes_assign(parameter):
    """Returns the Fortran code lines to allocate and assign values to the *original*
    parameter ValueElement that exists now only as a local variable so that the
    signatures match for the compiler."""
    if parameter.direction != '(out)' and ('allocate' in parameter.modifiers or 'pointer' in parameter.modifiers or 'target' in parameter.modifiers):
        if 'in' in parameter.direction:
            splice = _ctypes_splice(parameter)
            result = []
            result.append('    allocate({}({}))'.format(parameter.name, splice))
            result.append('    {0} = {0}_c'.format(parameter.name))
            return ('\n'.join(result), True)
    elif parameter.dtype == 'logical' and 'in' in parameter.direction:
        return ('    {0} = {0}_c'.format(parameter.name), False)

def _ctypes_ex_parameters(executable):
    """Returns a list of the parameters to form the wrapper executable to interact
    with ctypes."""
    result = []
    for p in executable.ordered_parameters:
        result.extend(p.ctypes_parameter())
    if type(executable).__name__ == 'Function':
        result.extend(executable.ctypes_parameter())
    return result

def _ctypes_ex_assign(executable):
    """Return a list of code lines to allocate and assign the local parameter definitions
    that match those in the signature of the wrapped executable."""
    result = []
    for p in executable.ordered_parameters:
        _ctypes_code_parameter(result, p, 'assign')
    if type(executable).__name__ == 'Function':
        _ctypes_code_parameter(result, executable, 'assign')
    return result

def _ctypes_ex_clean(executable):
    """Return a list of code lines to take care of assigning pointers for output variables
    interacting with ctypes."""
    result = []
    for p in executable.ordered_parameters:
        _ctypes_code_parameter(result, p, 'clean')
    if type(executable).__name__ == 'Function':
        _ctypes_code_parameter(result, executable, 'clean')
    return result

def _get_xml_version(element):
    """Extracts a list of versions that an xml element references. Returns
    a [ 1 ] list if there isn't a versions attribute."""
    if 'versions' in element.attrib:
        result = [int(v) for v in re.split(',\\s*', element.attrib['versions'])]
    else:
        result = [1]
    return result

def _char2int(char):
    """translate characters to integer values (upper and lower case)"""
    if char.isdigit():
        return int(float(char))
    if char.isupper():
        return int(char, 36)
    else:
        return 26 + int(char, 36)

def conv_units(val, meta):
    """Format and convert units to be more human readable

    @return new val with converted units"""
    if not val or not meta:
        return val
    try:
        val = float(val)
    except ValueError:
        logging.error('unable to apply convert units for %s' % val)
        return val
    suf = 0
    while val > 1024 and suf < 4:
        val /= 1024
        suf += 1
    return '%.2f%s' % (val, UNITS_SUFFIX[suf])

def order_module_dependencies(modules, parser):
    """Orders the specified list of modules based on their inter-dependencies."""
    result = []
    for modk in modules:
        if modk not in result:
            result.append(modk)
    recursed = list(result)
    for i in range(len(result)):
        module = result[i]
        _process_module_order(parser, module, i, recursed)
    return recursed

def _process_module_order(parser, module, i, result):
    """Adds the module and its dependencies to the result list."""
    if module == 'fortpy' or module == 'fpy_auxiliary':
        return
    if module not in parser.modules:
        parser.load_dependency(module, True, True, False)
    if module in parser.modules:
        modneeds = parser.modules[module].needs
        for modn in modneeds:
            if modn not in result:
                result.insert(i, modn)
            else:
                x = result.index(modn)
                if x > i:
                    result.remove(modn)
                    result.insert(i, modn)
            newi = result.index(modn)
            _process_module_order(parser, modn, newi, result)
    else:
        raise ValueError('unable to find module {}.'.format(module))

def parse():
    """Parses all the modules in the library specified by the script args.
    """
    from fortpy.code import CodeParser
    c = CodeParser()
    if args['verbose']:
        c.verbose = True
    f90files = {}
    c.scan_path(args['source'], f90files)
    for fname, fpath in f90files.items():
        if fname not in c._modulefiles:
            c._modulefiles[fname] = []
        c._parse_from_file(fpath, fname, args['recursive'], args['recursive'], False)
    return c

def _add_explicit_includes(lines, dependencies=None, extralinks=None):
    """Adds any relevant libraries that need to be explicitly included according
    to the fortpy configuration file. Libraries are appended to the specified
    collection of lines. Returns true if relevant libraries were added."""
    from fortpy import config
    import sys
    from os import path
    includes = sys.modules['config'].includes
    linklibs = False
    if extralinks is not None and len(extralinks) > 0:
        for i, link in enumerate(extralinks):
            lines.append('LBD{0:d} \t\t= {1}'.format(i, link))
        lines.append('')
    if len(includes) > 0:
        lines.append('LIBS\t\t= \\')
        for library in includes:
            addlib = False
            if 'modules' in library:
                for libmod in library['modules']:
                    if dependencies is None or libmod.lower() in dependencies:
                        addlib = True
                        break
            else:
                addlib = True
            if addlib:
                linklibs = True
                lines.append('\t\t{} \\'.format(library['path']))
        if extralinks is not None:
            for i in range(len(extralinks)):
                if path.isfile(extralinks[i]):
                    lines.append('\t\t$(LBD{0:d}) \\'.format(i))
    return linklibs or (extralinks is not None and len(extralinks) > 0)

def _make_compiler_include(precompile, extralinks):
    """Returns the include statement for the compiler to use."""
    base = 'ifeq ($(FAM),ifort)\n  include {2}/Makefile.ifort{0}{3}\nelse\nifeq ($(FAM),gfortran)\n  include {2}/Makefile.gfortran{1}{3}\nelse\n  include Makefile.error\nendif\nendif'
    if extralinks is not None and len(extralinks) > 0:
        from os import path
        libs = []
        for i, link in enumerate(extralinks):
            if path.isdir(link):
                libs.append('-I$(LBD{0:d})'.format(i))
        exlinks = '\n  FFLAGS += {}'.format(' '.join(libs))
    else:
        exlinks = ''
    if precompile:
        insert = ['\n  FFLAGS += -fpp -save-temps -heap-arrays', '\n  FFLAGS += -cpp', get_fortpy_templates(), exlinks]
        return base.format(*insert)
    else:
        return base.format('', '', get_fortpy_templates(), exlinks)

def _get_mapping(parser, mapped):
    """Gets the original file name for a module that was mapped
    when the module name does not coincide with the file name
    that the module was defined in."""
    if mapped in parser.mappings:
        return parser.mappings[mapped]
    else:
        return mapped + '.f90'

def get_lib_and_tag_name(tag):
    '''Takes a tag string and returns the tag library and tag name. For example,
    "app_tags.tag_name" is returned as "app_tags", "tag_name" and
    "app_tags.sub.tag_name" is returned as "app_tags.sub", "tag_name"'''
    if '.' not in tag:
        raise ValueError('Tag string must be in the format "tag_lib.tag_name"')
    lib = tag.rpartition('.')[0]
    tag_name = tag.rpartition('.')[-1]
    return (lib, tag_name)

def get_tag_html(tag_id):
    """Returns the Django HTML to load the tag library and render the tag.

    Args:
        tag_id (str): The tag id for the to return the HTML for."""
    tag_data = get_lazy_tag_data(tag_id)
    tag = tag_data['tag']
    args = tag_data['args']
    kwargs = tag_data['kwargs']
    lib, tag_name = get_lib_and_tag_name(tag)
    args_str = ''
    if args:
        for arg in args:
            if isinstance(arg, six.string_types):
                args_str += "'{0}' ".format(arg)
            else:
                args_str += '{0} '.format(arg)
    kwargs_str = ''
    if kwargs:
        for name, value in kwargs.items():
            if isinstance(value, six.string_types):
                kwargs_str += "{0}='{1}' ".format(name, value)
            else:
                kwargs_str += '{0}={1} '.format(name, value)
    html = '{{% load {lib} %}}{{% {tag_name} {args}{kwargs}%}}'.format(lib=lib, tag_name=tag_name, args=args_str, kwargs=kwargs_str)
    return html

def _update_globals(kids, xmlglobals):
    """Updates the specified 'xmlglobals' dictionary with the specific
    *and* supported global tag definitions."""
    for child in kids:
        key = child.tag.lower()
        if key != 'defaults':
            if key not in xmlglobals:
                xmlglobals[key] = {}
            if 'identifier' in child.attrib:
                xmlglobals[key][child.attrib['identifier']] = child
            elif 'name' in child.attrib:
                xmlglobals[key][child.attrib['name'].lower()] = child
        else:
            if 'defaults' not in xmlglobals:
                xmlglobals['defaults'] = {}
            xmlglobals['defaults'].update(child.attrib)

def _set_global_defaults(xmlglobals):
    """Sets the default attributes on tags that were specified in <global>
    tags in the XML file."""
    for key, val in xmlglobals.items():
        if key != 'defaults':
            for name, tag in val.items():
                _update_from_globals(tag, xmlglobals, None)

def _handle_ignores(testtag):
    """Checks if the specified test tag has attribute "ignores"; if it
    does, a <global ignore="true" /> tag is created for each variable
    name in the list."""
    if 'ignores' in testtag.attrib:
        from xml.etree.ElementTree import Element
        for varname in re.split('[\\s,]+', testtag.attrib['ignores']):
            if varname[0] == '^':
                varname = varname[1:]
            e = Element('global', {'name': varname, 'ignore': 'true'})
            testtag.append(e)

def _expand_autotag(atag, container):
    """Expands the contents of the specified auto tag within its parent container.
    """
    if atag.tag != 'auto':
        return
    if 'names' in atag.attrib:
        i = -1
        for name in re.split('[\\s,]+', atag.attrib['names']):
            if name[0] == '^':
                name = name[1:]
                insert = True
                i += 1
            else:
                insert = False
            for child in atag:
                dupe = child.copy()
                for attr, value in dupe.items():
                    dupe.attrib[attr] = value.replace('$', name)
                if insert:
                    container.insert(i, dupe)
                else:
                    container.append(dupe)
    else:
        from fortpy.msg import warn
        warn("'names' is a required attribute of the <auto> tag.")

def parser(key='default'):
    """Returns the parser for the given key, (e.g. 'ssh')"""
    if key not in _parsers:
        if key == 'ssh':
            _parsers['ssh'] = CodeParser(True, False)
        else:
            key = 'default'
    return _parsers[key]

def clear_caches(delete_all=False):
    """Fortpy caches many things, that should be completed after each completion
    finishes.

    :param delete_all: Deletes also the cache that is normally not deleted,
        like parser cache, which is important for faster parsing."""
    global _time_caches
    if delete_all:
        _time_caches = []
        _parser = {'default': CodeParser()}
    else:
        for tc in _time_caches:
            for key, (t, value) in list(tc.items()):
                if t < time.time():
                    del tc[key]

def time_cache(time_add_setting):
    """This decorator works as follows: Call it with a setting and after that
    use the function with a callable that returns the key.
    But: This function is only called if the key is not available. After a
    certain amount of time (`time_add_setting`) the cache is invalid."""
    def _temp(key_func):
        dct = {}
        _time_caches.append(dct)
        def wrapper(optional_callable, *args, **kwargs):
            key = key_func(*args, **kwargs)
            value = None
            if key in dct:
                expiry, value = dct[key]
                if expiry > time.time():
                    return value
            value = optional_callable()
            time_add = getattr(settings, time_add_setting)
            if key is not None:
                dct[key] = (time.time() + time_add, value)
            return value
        return wrapper
    return _temp

def _type_check_pointers(utype):
    """Checks the user-derived type for non-nullified pointer array declarations
    in its base definition.

    Returns (list of offending members)."""
    result = []
    for mname, member in utype.members.items():
        if 'pointer' in member.modifiers and member.D > 0 and (member.default is None or 'null' not in member.default):
            result.append(member)
    return result

