def collection(iterable=None, mutable=True, ordered=False, unique=False):
    """Return a :class:`Collection` with the specified properties.

    Args:
            iterable (Iterable): collection to instantiate new collection from.
            mutable (bool): Whether or not the new collection is mutable.
            ordered (bool): Whether or not the new collection is ordered.
            unique (bool): Whether or not the new collection contains only unique values."""
    if iterable is None:
        iterable = tuple()
    if unique:
        if ordered:
            if mutable:
                return setlist(iterable)
            else:
                return frozensetlist(iterable)
        elif mutable:
            return set(iterable)
        else:
            return frozenset(iterable)
    elif ordered:
        if mutable:
            return list(iterable)
        else:
            return tuple(iterable)
    elif mutable:
        return bag(iterable)
    else:
        return frozenbag(iterable)

def _rows_event_to_dict(e, stream):
    """Convert RowsEvent to a dict

    Args:
        e (pymysqlreplication.row_event.RowsEvent): the event
        stream (pymysqlreplication.BinLogStreamReader):
            the stream that yields event

    Returns:
        dict: event's data as a dict"""
    pk_cols = e.primary_key if isinstance(e.primary_key, (list, tuple)) else (e.primary_key,)
    if isinstance(e, row_event.UpdateRowsEvent):
        sig = signals.rows_updated
        action = 'update'
        row_converter = _convert_update_row
    elif isinstance(e, row_event.WriteRowsEvent):
        sig = signals.rows_inserted
        action = 'insert'
        row_converter = _convert_write_row
    elif isinstance(e, row_event.DeleteRowsEvent):
        sig = signals.rows_deleted
        action = 'delete'
        row_converter = _convert_write_row
    else:
        assert False, 'Invalid binlog event'
    meta = {'time': e.timestamp, 'log_pos': stream.log_pos, 'log_file': stream.log_file, 'schema': e.schema, 'table': e.table, 'action': action}
    rows = list(map(row_converter, e.rows))
    for row in rows:
        row['keys'] = {k: row['values'][k] for k in pk_cols}
    return (rows, meta)

def deprecated(msg, dep_version):
    """Decorate a function, method or class to mark as deprecated.

    Raise DeprecationWarning and add a deprecation notice to the docstring."""
    def wrapper(func):
        docstring = func.__doc__ or ''
        docstring_msg = '.. deprecated:: {version} {msg}'.format(version=dep_version, msg=msg)
        if docstring:
            string_list = docstring.splitlines()
            first_line = string_list[0]
            remaining = textwrap.dedent(''.join(string_list[1:]))
            docstring = '\n'.join([first_line, remaining, '', docstring_msg])
        else:
            docstring = docstring_msg
        func.__doc__ = docstring
        @wraps(func)
        def inner(*args, **kwargs):
            warnings.warn(msg, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return inner
    return wrapper

def get_tools(whitelist, known_plugins):
    """Filter all known plugins by a whitelist specified. If the whitelist is
    empty, default to all plugins."""
    def getpath(c):
        return '%s:%s' % (c.__module__, c.__class__.__name__)
    tools = [x for x in known_plugins if getpath(x) in whitelist]
    if not tools:
        if whitelist:
            raise UnknownTools(map(getpath, known_plugins))
        tools = known_plugins
    return tools

