def socket_recvall(socket, length, bufsize=4096):
    """A helper method to read of bytes from a socket to a maximum length"""
    data = b''
    while len(data) < length:
        data += socket.recv(bufsize)
    return data

def check_tag_data(data):
    """Raise a ValueError if DATA doesn't seem to be a well-formed ID3 tag."""
    if len(data) < 10:
        raise ValueError('Tag too short')
    if data[0:3] != b'ID3':
        raise ValueError('Missing ID3 identifier')
    if data[3] >= 5 or data[4] != 0:
        raise ValueError('Unknown ID3 version')
    length = stagger.conversion.Syncsafe.decode(data[6:10]) + 10
    if len(data) != length:
        raise ValueError('Tag size mismatch')

def get_raw_tag_data(filename):
    """Return the ID3 tag in FILENAME as a raw byte string."""
    with open(filename, 'rb') as file:
        try:
            cls, offset, length = stagger.tags.detect_tag(file)
        except stagger.NoTagError:
            return bytes()
        file.seek(offset)
        return file.read(length)

def set_raw_tag_data(filename, data, act=True, verbose=False):
    """Replace the ID3 tag in FILENAME with DATA."""
    check_tag_data(data)
    with open(filename, 'rb+') as file:
        try:
            cls, offset, length = stagger.tags.detect_tag(file)
        except stagger.NoTagError:
            offset, length = (0, 0)
        if length > 0:
            verb(verbose, '{0}: replaced tag with {1} bytes of data'.format(filename, len(data)))
        else:
            verb(verbose, '{0}: created tag with {1} bytes of data'.format(filename, len(data)))
        if act:
            stagger.fileutil.replace_chunk(file, offset, length, data)

def resp_json(resp):
    """Get JSON from response if success, raise requests.HTTPError otherwise.

    Args:
        resp: requests.Response or flask.Response
    Retuens:
        JSON value"""
    if isinstance(resp, flask.Response):
        if 400 <= resp.status_code < 600:
            msg = resp.status
            try:
                result = loads(resp.data.decode('utf-8'))
                if isinstance(result, str):
                    msg = '%s, %s' % (resp.status, result)
                else:
                    msg = '%s %s, %s' % (resp.status_code, result['error'], result['message'])
            except Exception:
                pass
            raise requests.HTTPError(msg, response=resp)
        else:
            return loads(resp.data.decode('utf-8'))
    else:
        try:
            resp.raise_for_status()
        except requests.HTTPError as ex:
            try:
                result = resp.json()
                ex.args += (result['error'], result['message'])
            except (ValueError, KeyError):
                pass
            raise
        return resp.json()

def res_to_url(resource, action):
    """Convert resource.action to (url, HTTP_METHOD)"""
    i = action.find('_')
    if i < 0:
        url = '/' + resource
        httpmethod = action
    else:
        url = '/%s/%s' % (resource, action[i + 1:])
        httpmethod = action[:i]
    return (url, httpmethod.upper())

def abort(code, error=None, message=None):
    """Abort with suitable error response

    Args:
        code (int): status code
        error (str): error symbol or flask.Response
        message (str): error message"""
    if error is None:
        flask_abort(code)
    elif isinstance(error, Response):
        error.status_code = code
        flask_abort(code, response=error)
    else:
        body = {'status': code, 'error': error, 'message': message}
        flask_abort(code, response=export(body, code))

def unpack(rv):
    """Convert rv to tuple(data, code, headers)

    Args:
        rv: data or tuple that contain code and headers
    Returns:
        tuple (rv, status, headers)"""
    status = headers = None
    if isinstance(rv, tuple):
        rv, status, headers = rv + (None,) * (3 - len(rv))
    if isinstance(status, (dict, list)):
        headers, status = (status, headers)
    return (rv, status, headers)

def export(rv, code=None, headers=None):
    """Create a suitable response

    Args:
        rv: return value of action
        code: status code
        headers: response headers
    Returns:
        flask.Response"""
    if isinstance(rv, ResponseBase):
        return make_response(rv, code, headers)
    else:
        if code is None:
            code = 200
        mediatype = request.accept_mimetypes.best_match(exporters.keys(), default='application/json')
        return exporters[mediatype](rv, code, headers)

def parse_docs(docs, marks):
    """Parse YAML syntax content from docs

    If docs is None, return {}
    If docs has no YAML content, return {"$desc": docs}
    Else, parse YAML content, return {"$desc": docs, YAML}

    Args:
        docs (str): docs to be parsed
        marks (list): list of which indicate YAML content starts
    Returns:
        A dict contains information of docs"""
    if docs is None:
        return {}
    indexs = []
    for mark in marks:
        i = docs.find(mark)
        if i >= 0:
            indexs.append(i)
    if not indexs:
        return {'$desc': textwrap.dedent(docs).strip()}
    start = min(indexs)
    start = docs.rfind('\n', 0, start)
    yamltext = textwrap.dedent(docs[start + 1:])
    meta = yaml.load(yamltext)
    meta['$desc'] = textwrap.dedent(docs[:start]).strip()
    return meta

def get_request_data():
    """Get request data based on request.method

    If method is GET or DELETE, get data from request.args
    If method is POST, PATCH or PUT, get data from request.form or request.json"""
    method = request.method.lower()
    if method in ['get', 'delete']:
        return request.args
    elif method in ['post', 'put', 'patch']:
        if request.mimetype == 'application/json':
            try:
                return request.get_json()
            except:
                abort(400, 'InvalidData', 'invalid json content')
        else:
            return request.form
    else:
        return None

