def main(ctx, host, port, transport_type, timeout, ca_certs):
    """Connects to a Riemann server to send events or query the index

    By default, will attempt to contact Riemann on localhost:5555 over TCP. The
    RIEMANN_HOST and RIEMANN_PORT environment variables can be used to
    configure the host and port used. Command line parameters will override the
    environment variables.

    Use `-T none` to test commands without actually connecting to a server."""
    if transport_type == 'udp':
        if timeout is not None:
            ctx.fail('--timeout cannot be used with the UDP transport')
        transport = riemann_client.transport.UDPTransport(host, port)
    elif transport_type == 'tcp':
        transport = riemann_client.transport.TCPTransport(host, port, timeout)
    elif transport_type == 'tls':
        if ca_certs is None:
            ctx.fail('--ca-certs must be set when using the TLS transport')
        transport = riemann_client.transport.TLSTransport(host, port, timeout, ca_certs)
    elif transport_type == 'none':
        transport = riemann_client.transport.BlankTransport()
    ctx.obj = transport

def parse_meta(meta):
    """Parse metadata of API

    Args:
        meta: metadata of API
    Returns:
        tuple(url_prefix, auth_header, resources)"""
    resources = {}
    for name in meta:
        if name.startswith('$'):
            continue
        resources[name] = resource = {}
        for action in meta[name]:
            if action.startswith('$'):
                continue
            url, httpmethod = res_to_url(name, action)
            resource[action] = {'url': url, 'method': httpmethod}
    url_prefix = meta.get('$url_prefix', '').rstrip('/')
    return (url_prefix, meta['$auth']['header'].lower(), resources)

def render_core(url_prefix, auth_header, resources):
    """Generate res.core.js"""
    code = ''
    code += 'function(root, init) {\n'
    code += "  var q = init('%(auth_header)s', '%(url_prefix)s');\n" % {'url_prefix': url_prefix, 'auth_header': auth_header}
    code += '  var r = null;\n'
    for key in resources:
        code += '  r = root.%(key)s = {};\n' % {'key': key}
        for action, item in resources[key].items():
            code += "    r.%(action)s = q('%(url)s', '%(method)s');\n" % {'action': action, 'url': item['url'], 'method': item['method']}
    code += '}'
    return code

def generate_code(meta, prefix=None, node=False, min=False):
    """Generate res.js

    Args:
        meta: tuple(url_prefix, auth_header, resources) or metadata of API
    Returns:
        res.js source code"""
    if isinstance(meta, dict):
        url_prefix, auth_header, resources = parse_meta(meta)
    else:
        url_prefix, auth_header, resources = meta
    if prefix is not None:
        url_prefix = prefix
    core = render_core(url_prefix, auth_header, resources)
    if min:
        filename = 'res.web.min.js'
    else:
        filename = 'res.web.js'
    if node:
        filename = 'res.node.js'
    base = read_file(filename)
    return base.replace('"#res.core.js#"', core)

def get_cur_file_size(fp, position_to_eof=False):
    """Returns size of file, optionally leaving fp positioned at EOF."""
    if not position_to_eof:
        cur_pos = fp.tell()
    fp.seek(0, os.SEEK_END)
    cur_file_size = fp.tell()
    if not position_to_eof:
        fp.seek(cur_pos, os.SEEK_SET)
    return cur_file_size

def bucket_lister(bucket, prefix='', delimiter='', marker='', headers=None):
    """A generator function for listing keys in a bucket."""
    more_results = True
    k = None
    while more_results:
        rs = bucket.get_all_keys(prefix=prefix, marker=marker, delimiter=delimiter, headers=headers)
        for k in rs:
            yield k
        if k:
            marker = rs.next_marker or k.name
        more_results = rs.is_truncated

def part_lister(mpupload, part_number_marker=None):
    """A generator function for listing parts of a multipart upload."""
    more_results = True
    part = None
    while more_results:
        parts = mpupload.get_all_parts(None, part_number_marker)
        for part in parts:
            yield part
        part_number_marker = mpupload.next_part_number_marker
        more_results = mpupload.is_truncated

def frameclass(cls):
    """Register cls as a class representing an ID3 frame.

    Sets cls.frameid and cls._version if not present, and registers the
    new frame in Tag's known_frames dictionary.

    To be used as a decorator on the class definition:

    @frameclass
    class UFID(Frame):
        _framespec = (NullTerminatedStringSpec("owner"), BinaryDataSpec("data"))"""
    assert issubclass(cls, Frames.Frame)
    if len(cls.__name__) == 3:
        base = cls.__bases__[0]
        if issubclass(base, Frames.Frame) and base._in_version(3, 4):
            assert not hasattr(base, '_v2_frame')
            base._v2_frame = cls
            if base.frameid == cls.frameid:
                cls.frameid = cls.__name__
    if not hasattr(cls, 'frameid'):
        cls.frameid = cls.__name__
    assert Tag._is_frame_id(cls.frameid)
    if len(cls.frameid) == 3:
        cls._version = 2
    if len(cls.frameid) == 4 and (not cls._version):
        cls._version = (3, 4)
    assert cls.frameid not in Tag.known_frames
    Tag.known_frames[cls.frameid] = cls
    return cls

def find_best_instruction(addr, cpu_name, meta=None):
    """Given an instruction and meta information this attempts to find
    the best instruction for the frame.  In some circumstances we can
    fix it up a bit to improve the accuracy.  For more information see
    `symbolize_frame`."""
    addr = rv = parse_addr(addr)
    if not meta or meta.get('frame_number') != 0:
        rv = get_previous_instruction(addr, cpu_name)
    else:
        regs = meta.get('registers')
        ip = get_ip_register(regs, cpu_name)
        if ip is not None and ip != addr and (meta.get('signal') in (SIGILL, SIGBUS, SIGSEGV)):
            rv = get_previous_instruction(addr, cpu_name)
    return round_to_instruction_end(rv, cpu_name)

def get_enabled_browsers():
    """Check the ADMINFILES_BROWSER_VIEWS setting and return a list of
    instantiated browser views that have the necessary
    dependencies/configuration to run."""
    global _enabled_browsers_cache
    if _enabled_browsers_cache is not None:
        return _enabled_browsers_cache
    enabled = []
    for browser_path in settings.ADMINFILES_BROWSER_VIEWS:
        try:
            view_class = import_browser(browser_path)
        except ImportError:
            continue
        if not issubclass(view_class, BaseView):
            continue
        browser = view_class
        try:
            browser.check()
        except DisableView:
            continue
        enabled.append(browser)
    _enabled_browsers_cache = enabled
    return enabled

