def mutator(*cache_names):
    """Decorator for ``Document`` methods that change the document.

    This decorator ensures that the object's caches are kept in sync
    when changes are made."""
    def deco(fn):
        @wraps(fn)
        def _fn(self, *args, **kwargs):
            try:
                return fn(self, *args, **kwargs)
            finally:
                for cache_name in cache_names:
                    setattr(self, cache_name, None)
        return _fn
    return deco

def dispatch(t):
    """Given an auth tuple, return an expanded version."""
    if not t:
        return t
    else:
        t = list(t)
    assert len(t) >= 2
    if len(t) == 2:
        t.insert(0, 'basic')
    if isinstance(t[0], basestring):
        if t[0] in ('basic', 'forced_basic'):
            t[0] = http_basic
        elif t[0] in ('digest',):
            t[0] = http_digest
    return (t[0], tuple(t[1:]))

def _ensure_5args(func):
    """Conditionally wrap function to ensure 5 input arguments

    Parameters
    ----------
    func: callable
        with four or five positional arguments

    Returns
    -------
    callable which possibly ignores 0 or 1 positional arguments"""
    if func is None:
        return None
    self_arg = 1 if inspect.ismethod(func) else 0
    if len(inspect.getargspec(func)[0]) == 5 + self_arg:
        return func
    if len(inspect.getargspec(func)[0]) == 4 + self_arg:
        return lambda t, y, J, dfdt, fy=None: func(t, y, J, dfdt)
    else:
        raise ValueError('Incorrect numer of arguments')

