    @param file_path_name: absolute path and file name of an image.


    @return: ``True`` if the image file is valid, ``False`` if the file is
        truncated or does not correspond to a supported image."""
    try:
        with Image.open(file_path_name) as image:
            image.load()
    except IOError:
        return False
    return True

def __build_author_name_expr(author_name, author_email_address):
    """Build the name of the author of a message as described in the Internet
    Message Format specification: https://tools.ietf.org/html/rfc5322#section-3.6.2


    @param author_name: complete name of the originator of the message.

    @param author_email_address: address of the mailbox to which the author
        of the message suggests that replies be sent.


    @return: a string representing the author of the message, that is, the
        mailbox of the person or system responsible for the writing of the
        message.  This string is intended to be used as the "From:" field
        of the message."""
    assert author_name or author_email_address, 'Both arguments MUST NOT be bull'
    author_name_expr = author_name or author_email_address[:author_email_address.find('@')]
    if ' ' in author_name_expr:
        author_name_expr = '"%s"' % author_name_expr
    if author_email_address:
        author_name_expr = '%s <%s>' % (author_name_expr, author_email_address)
    return author_name_expr

def content_item(path1, path2, path_sep='/'):
    """if path1 is subpart of path2, get the next path item.
    example:
    path1 = '/foo'
    path2 = '/foo/bar/foo'
    -> 'bar'"""
    p1_parts = path1.split(path_sep)
    p2_parts = path2.split(path_sep)
    if path1 == path_sep and len(p2_parts) >= 2:
        return p2_parts[1]
    if len(p2_parts) <= len(p1_parts):
        return ''
    for i, item in enumerate(p1_parts):
        if item != p2_parts[i]:
            return ''
    return p2_parts[i + 1]

def compare_path_strings(path1, path2, path_sep='/'):
    """find out, if path1 is a file, or a directory (or unknown)."""
    if len(path2) < len(path1):
        return 0
    if path1 == path2:
        return ISFILE
    else:
        p1_parts = path1.split(path_sep)
        p2_parts = path2.split(path_sep)
        if len(p2_parts) < len(p1_parts):
            return 0
        else:
            return compare_parts(p1_parts, p2_parts)

def compare_parts(list1, list2):
    """if list2 does not start with list1, we can't really check and return 0"""
    for i, item in enumerate(list1):
        if item != list2[i]:
            return 0
    if len(list2) > len(list1):
        return ISDIR
    else:
        return ISFILE

