def ex_literal(val):
    """An int, float, long, bool, string, or None literal with the given
    value."""
    if val is None:
        return ast.Name('None', ast.Load())
    elif isinstance(val, int):
        return ast.Num(val)
    elif isinstance(val, bool):
        return ast.Name(bytes(val), ast.Load())
    elif isinstance(val, str):
        return ast.Str(val)
    raise TypeError(u'no literal for {0}'.format(type(val)))

def ex_varassign(name, expr):
    """Assign an expression into a single variable. The expression may
    either be an `ast.expr` object or a value to be used as a literal."""
    if not isinstance(expr, ast.expr):
        expr = ex_literal(expr)
    return ast.Assign([ex_lvalue(name)], expr)

def ex_call(func, args):
    """A function-call expression with only positional parameters. The
    function may be an expression or the name of a function. Each
    argument may be an expression or a value to be used as a literal."""
    if isinstance(func, str):
        func = ex_rvalue(func)
    args = list(args)
    for i in range(len(args)):
        if not isinstance(args[i], ast.expr):
            args[i] = ex_literal(args[i])
    if sys.version_info[:2] < (3, 5):
        return ast.Call(func, args, [], None, None)
    else:
        return ast.Call(func, args, [])

def compile_func(arg_names, statements, name='_the_func', debug=False):
    """Compile a list of statements as the body of a function and return
    the resulting Python function. If `debug`, then print out the
    bytecode of the compiled function."""
    func_def = ast.FunctionDef(name=name, args=ast.arguments(args=[ast.arg(arg=n, annotation=None) for n in arg_names], kwonlyargs=[], kw_defaults=[], defaults=[ex_literal(None) for _ in arg_names]), body=statements, decorator_list=[])
    mod = ast.Module([func_def])
    ast.fix_missing_locations(mod)
    prog = compile(mod, '<generated>', 'exec')
    if debug:
        dis.dis(prog)
        for const in prog.co_consts:
            if isinstance(const, types.CodeType):
                dis.dis(const)
    the_locals = {}
    exec(prog, {}, the_locals)
    return the_locals[name]

def _parse(template):
    """Parse a top-level template string Expression. Any extraneous text
    is considered literal text."""
    parser = Parser(template)
    parser.parse_expression()
    parts = parser.parts
    remainder = parser.string[parser.pos:]
    if remainder:
        parts.append(remainder)
    return Expression(parts)

def caller_folder():
    """Returns the folder where the code of the caller's caller lives"""
    import inspect
    caller_file = inspect.stack()[2][1]
    if os.path.exists(caller_file):
        return os.path.abspath(os.path.dirname(caller_file))
    else:
        return os.path.abspath(os.getcwd())

def types(*return_type, **arg_types):
    """Assert types of the function arguments and return value.
    :param return_type: expected type of the return value
    :param arg_types: expected types of the arguments

    :example:
    @types(float, x=int, y=float, z=ListOf(int))
    def f(x, y, z):
        return x * y + sum(z)"""
    assert len(return_type) <= 1, 'You can specify at most one return type.'
    arg_msg = '%s must be %s, not %s.'
    return_msg = 'must return %s, not %s.'
    def f(func):
        import functools
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            call_args = getcallargs(func, *args, **kwargs)
            for arg_name, expect in arg_types.items():
                assert arg_name in call_args, 'Not found argument: %s' % arg_name
                actual = call_args[arg_name]
                if not _check_type(actual, expect):
                    raise TypeError(arg_msg % (arg_name, _get_name(expect), type(actual).__name__))
            ret = func(*args, **kwargs)
            if return_type:
                if not _check_type(ret, return_type[0]):
                    raise TypeError(return_msg % (_get_name(return_type[0]), type(ret).__name__))
            return ret
        return wrapper
    return f

def _comparator(func):
    """Decorator for EnumValue rich comparison methods."""
    def comparator_wrapper(self, other):
        try:
            result = func(self.key, other.key)
        except (AssertionError, AttributeError):
            result = NotImplemented
        return result
    comparator_wrapper.__name__ = func.__name__
    comparator_wrapper.__doc__ = getattr(float, func.__name__).__doc__
    return comparator_wrapper

