def group_singles2array(input, **params):
    """Creates array of strings or ints from objects' fields
    :param input: list of objects
    :param params:
    :return: list"""
    PARAM_FIELD_KEY = 'field.key'
    PARAM_FIELD_ARRAY = 'field.array'
    PARAM_FIELD_SINGLE = 'field.single'
    field_key = params.get(PARAM_FIELD_KEY) if PARAM_FIELD_KEY in params else None
    field_array = params.get(PARAM_FIELD_ARRAY)
    field_single = params.get(PARAM_FIELD_SINGLE)
    if not field_key:
        res = []
        for item in input:
            res.append(item[field_single])
        return {field_array: res}
    else:
        tdict = {}
        for row in input:
            if not row[field_key] in tdict:
                tdict.update({row[field_key]: [row[field_single]]})
            else:
                tdict[row[field_key]].append(row[field_single])
        res = []
        for key, value in tdict.items():
            res.append({field_key: key, field_array: value})
        return res

def copy(input, **params):
    """Copies input or input's selected fields
    :param input:
    :param params:
    :return: input"""
    PARAM_FIELDS = 'fields'
    def filter_fields(obj, fields):
        return {k: v for k, v in obj.items() if k in fields}
    if PARAM_FIELDS in params:
        fields = params.get(PARAM_FIELDS)
        if isinstance(input, list):
            res = []
            for row in input:
                res.append(filter_fields(row, fields))
            return res
        elif isinstance(input, dict):
            return filter_fields(input, fields)
        else:
            raise NotImplementedError('{} is not supported'.format(type(input)))
    else:
        return input

def special_mode(v):
    """decode Olympus SpecialMode tag in MakerNote"""
    mode1 = {0: 'Normal', 1: 'Unknown', 2: 'Fast', 3: 'Panorama'}
    mode2 = {0: 'Non-panoramic', 1: 'Left to right', 2: 'Right to left', 3: 'Bottom to top', 4: 'Top to bottom'}
    if not v or (v[0] not in mode1 or v[2] not in mode2):
        return v
    return '%s - sequence %d - %s' % (mode1[v[0]], v[1], mode2[v[2]])

def _safe_call(obj, methname, *args, **kwargs):
    """Safely calls the method with the given methname on the given
    object.  Remaining positional and keyword arguments are passed to
    the method.  The return value is None, if the method is not
    available, or the return value of the method."""
    meth = getattr(obj, methname, None)
    if meth is None or not callable(meth):
        return
    return meth(*args, **kwargs)

def find_config():
    """Find a build cache somewhere in a parent directory."""
    previous = ''
    current = os.getcwd()
    while previous != current:
        check_path = os.path.join(current, 'build.cache')
        if os.path.isfile(check_path):
            return check_path
        else:
            previous = current
            current = os.path.dirname(current)
    raise Exception("Can't find build cache")

def LastOf(*subcons):
    """Create an adapter which uses only the last construct.

    If first argument is a string it will be the name."""
    name = 'seq'
    if isinstance(subcons[0], six.string_types):
        name = subcons[0]
        subcons = subcons[1:]
    return IndexingAdapter(Sequence(name, *subcons), -1)

