def find_module_egg_path(module_path):
    """Find the path of the deployed egg package that may contain the
    specified module path.


    @param module_path: the path of a Python module.


    @return: the absolute path of the deployed egg package that contains
        the specified module path, or ``None`` if no deployed egg
        package contains this module path."""
    if module_path.find('.egg') == -1:
        return None
    _module_absolute_path = os.path.abspath(module_path)
    egg_paths = [os.path.relpath(_module_absolute_path, egg_path) for egg_path in [egg_path for egg_path in sys.path if REGEX_EGG_PACKAGE_PATH.match(egg_path) and _module_absolute_path.startswith(egg_path)]]
    return None if len(egg_paths) == 0 else egg_paths[0]

def log(ltype, method, page, user_agent):
    """Writes to the log a message in the following format::

    "<datetime>: <exception> method <HTTP method> page <path> user agent <user_agent>"
    """
    try:
        f = open(settings.DJANGOSPAM_LOG, 'a')
        f.write('%s: %s method %s page %s user agent %s\n' % (datetime.datetime.now(), ltype, method, page, user_agent))
        f.close()
    except:
        if settings.DJANGOSPAM_FAIL_ON_LOG:
            exc_type, exc_value = sys.exc_info()[:2]
            raise LogError(exc_type, exc_value)

def remove_binaries(package_dir=False):
    """Remove all binaries for the current platform

    Parameters
    ----------
    package_dir: bool
        If True, remove all binaries from the `resources`
        directory of the qpsphere package. If False,
        remove all binaries from the user's cache directory."""
    paths = []
    if package_dir:
        pdir = RESCR_PATH
    else:
        pdir = CACHE_PATH
    for pp in pdir.iterdir():
        if pp.name != 'shipped_resources_go_here':
            paths.append(pp)
    for pp in paths:
