def elapsed(func):
    """A decorator for calculating time elapsed when execute function"""
    @functools.wraps(func)
    def wrapper(*args, **kw):
        start = time.time()
        print('Running `%s()` ...' % func.__name__)
        res = func(*args, **kw)
        end = time.time()
        print('Function `%s()` running elapsed %.2f s' % (func.__name__, end - start))
        return res
    return wrapper

def autocommit(f):
    """A decorator to commit to the storage if autocommit is set to True."""
    @wraps(f)
    def wrapper(self, *args, **kwargs):
        result = f(self, *args, **kwargs)
        if self._meta.commit_ready():
            self.commit()
        return result
    return wrapper

def intersect(d1, d2):
    """Intersect dictionaries d1 and d2 by key *and* value."""
    return dict(((k, d1[k]) for k in d1 if k in d2 and d1[k] == d2[k]))

def execute_command(command, args):
    """Runs the provided command with the given args.

    Exceptions, if any, are propogated to the caller.

    Arguments:
    command - something that extends the Command class
    args - A list of command line arguments.  If args is None, sys.argv
           (without the first argument--assumed to be the command name) will
           be used."""
    if args is None:
        args = sys.argv[1:]
    try:
        command.execute(args)
    except IOError as failure:
        if failure.errno == errno.EPIPE:
            pass
    except _PartialFailureException as failed:
        for failure, skipped, message in failed.failed:
            print('\nTask {} failed'.format(failure), file=sys.stderr)
            print('\tError: {}'.format(message), file=sys.stderr)
            print('\tSkipped: {}'.format(skipped), file=sys.stderr)
        sys.exit(1)
    except Exception as failure:
        print('Error: {}'.format(str(failure)), file=sys.stderr)
        sys.exit(1)

def _user_input() -> str:
    """A helper function which waits for user multi-line input.

    :return: A string input by user, separated by ``'\\n'``."""
    lines = []
    try:
        while True:
            line = input()
            if line != '':
                lines.append(line)
            else:
                break
    except (EOFError, KeyboardInterrupt):
        return '\n'.join(lines)

def getLogLevelNo(level):
    """Return numerical log level or raise ValueError.

    A valid level is either an integer or a string such as WARNING etc."""
    if isinstance(level, (int, long)):
        return level
    try:
        return int(logging.getLevelName(level.upper()))
    except:
        raise ValueError('illegal loglevel %s' % level)

def cmdLine(useBasename=False):
    """Return full command line with any necessary quoting."""
    qargv = []
    cmdwords = list(sys.argv)
    if useBasename:
        cmdwords[0] = os.path.basename(cmdwords[0])
    for s in cmdwords:
        if re.search('\\s|\\*|\\?', s):
            if "'" in s:
                qargv.append('"%s"' % re.sub('"', "'", s))
            else:
                qargv.append("'%s'" % re.sub("'", '"', s))
        else:
            qargv.append(s)
    cmd = ' '.join(qargv)
    return cmd

def handleError(exception, debugFlag=False, abortFlag=True):
    """Error handling utility. Print more or less error information
    depending on debug flag. Unless abort is set False, exits with
    error code 1."""
    if isinstance(exception, CmdError) or not debugFlag:
        error(str(exception))
    else:
        import traceback
        traceback.print_exc()
        error(str(exception))
    if abortFlag:
        sys.exit(1)

def make_string(seq):
    """Don't throw an exception when given an out of range character."""
    string = ''
    for c in seq:
        try:
            if 32 <= c and c < 256:
                string += chr(c)
        except TypeError:
            pass
    if not string:
        return str(seq)
    return string

def s2n_motorola(string):
    """Extract multi-byte integer in Motorola format (little endian)."""
    x = 0
    for c in string:
        x = x << 8 | ord_(c)
    return x

def read_file(file_path_name):
