def legitimize(text):
    """Converts a string to a valid filename.
    """
    import platform
    os_ = platform.system()
    text = text.translate({0: None, ord('/'): '-', ord('|'): '-'})
    if os_ == 'Windows':
        text = text.translate({ord(':'): '-', ord('*'): '-', ord('?'): '-', ord('\\'): '-', ord('"'): "'", ord('+'): '-', ord('<'): '-', ord('>'): '-', ord('['): '(', ord(']'): ')'})
    else:
        if os_ == 'Darwin':
            text = text.translate({ord(':'): '-'})
        if text.startswith('.'):
            text = text[1:]
    text = text[:82]
    return text

def capture(board):
    """Try to solve the board described by board_string.

    Return sequence of summaries that describe how to get to the solution."""
    game = Game()
    v = (0, 0)
    stub_actor = base.Actor('capture', v, v, v, v, v, v, v, v, v)
    root = base.State(board, stub_actor, stub_actor, turn=1, actions_remaining=1)
    solution_node = None
    for eot in game.all_ends_of_turn(root):
        if eot.is_mana_drain:
            if eot.parent.board.is_empty():
                solution_node = eot
                break
    solution_sequence = list()
    if solution_node:
        node = solution_node
        while node:
            if not isinstance(node, base.Swap):
                node = node.parent
                continue
            summary = base.Summary(node.parent.board, node.position_pair, None, None, None)
            solution_sequence.append(summary)
            node = node.parent
    return tuple(reversed(solution_sequence))

def copytree(src, dst, overwrite=False, ignore_list=None, debug=False):
    """Copy a tree of files over.

    Ignores a file if it already exists at the destination."""
    if ignore_list is None:
        ignore_list = []
    if debug:
        print('copytree {} to {}'.format(src, dst))
    for child in Path(src).iterdir():
        if debug:
            print('  on file {}'.format(child))
        if child.name not in ignore_list:
            if child.is_dir():
                new_dir = Path(dst) / child.relative_to(src)
                new_dir.mkdir(exist_ok=True)
                copytree(child, new_dir, overwrite, ignore_list, debug)
            elif child.is_file():
                new_file = new_dir = Path(dst) / child.relative_to(src)
                if debug:
                    print('    to file {}'.format(new_file))
                if new_file.exists():
                    if overwrite:
                        new_file.unlink()
                        shutil.copy2(child, new_file)
                else:
                    shutil.copy2(child, new_file)
        elif debug:
            print('  Skipping copy of {}'.format(child))

def read_requirements(*parts):
    """Given a requirements.txt (or similar style file), returns a list of requirements.

    Assumes anything after a single '#' on a line is a comment, and ignores
    empty lines."""
    requirements = []
    for line in read(*parts).splitlines():
        new_line = re.sub('(\\s*)?#.*$', '', line)
        if new_line:
            requirements.append(new_line)
    return requirements

def find_files(args):
    """Return list of spec files. `args` may be filenames which are passed right
    through, or directories in which case they are searched recursively for
    *._spec.py"""
