def raise_error(subject, error_class):
    """Call function `subject` and expect the function to raise an exception.
    >>> expect = Expector([])
    >>> expect(lambda: 1 / 0).to(raise_error, ZeroDivisionError)
    (True, 'Expect ZeroDivisionError to be raised')"""
    description = 'Expect {} to be raised'.format(error_class.__name__)
    try:
        subject()
        return (False, description)
    except error_class:
        return (True, description)

def check_configuration(ctx, base_key, needed_keys):
    """Confrim a valid configuration.

    Args:
        ctx (invoke.context):
        base_key (str): the base configuration key everything is under.
        needed_keys (list): sub-keys of the base key that are checked to make
            sure they exist."""
    if base_key not in ctx.keys():
        exit("[{}ERROR{}] missing configuration for '{}'".format(ERROR_COLOR, RESET_COLOR, base_key))
    if ctx.releaser is None:
        exit("[{}ERROR{}] empty configuration for '{}' found".format(ERROR_COLOR, RESET_COLOR, base_key))
    for my_key in needed_keys:
        if my_key not in ctx[base_key].keys():
            exit("[{}ERROR{}] missing configuration key '{}.{}'".format(ERROR_COLOR, RESET_COLOR, base_key, my_key))

def check_existence(to_check, name, config_key=None, relative_to=None, allow_undefined=False, allow_not_existing=False, base_key='releaser'):
    """Determine whether a file or folder actually exists."""
    if allow_undefined and (to_check is None or to_check.lower() == 'none'):
        print('{: <14} -> {}UNDEFINED{}'.format(name, WARNING_COLOR, RESET_COLOR))
        return
    else:
        if config_key is None:
            config_key = '{}.{}'.format(base_key, name)
        my_check = Path(to_check).resolve()
        if my_check.exists() and relative_to is not None:
            printed_path = str(my_check.relative_to(relative_to))
            if printed_path != '.':
                printed_path = '.' + os.sep + printed_path
        else:
            printed_path = str(my_check)
        if my_check.exists() or allow_not_existing:
            print('{: <14} -> {}'.format(name, printed_path))
            return
        else:
            raise FileNotFoundError("[{}ERROR{}] '{}', as given, doesn't exist. For configuration key '{}', was given: {}".format(ERROR_COLOR, RESET_COLOR, name, config_key, to_check))

def _child(details):
    """Child

    A private function to figure out the child node type

    Arguments:
            details {dict} -- A dictionary describing a data point

    Returns:
            _NodeInterface"""
    if isinstance(details, list):
        return OptionsNode(details)
    elif isinstance(details, dict):
        if '__array__' in details:
            return ArrayNode(details)
        elif '__hash__' in details:
            return HashNode(details)
        elif '__type__' in details:
            if isinstance(details['__type__'], (dict, list)):
                return _child(details['__type__'])
            else:
                return Node(details)
        else:
            return Parent(details)
    elif isinstance(details, basestring):
        return Node(details)
    else:
        raise TypeError('details')

