def public_dict(d):
    """if type(d) is dict:
        return dict((k, public_dict(v)) for k, v in d.items() if not k.startswith('_'))
    elif type(d) is list:
        return [public_dict(v) for v in d]
    else:
        return d"""
    if isinstance(d, dict):
        safe_dict = dict(((key, public_dict(value)) for key, value in d.items() if not key.startswith('_')))
        if '_cls' in d:
            safe_dict['type'] = d['_cls']
        return safe_dict
    if isinstance(d, list):
        return [public_dict(l) for l in d]
    return d

def change_keys(obj, convert):
    """Recursively goes through the dictionary obj and replaces keys with the convert function."""
    if isinstance(obj, (str, int, float)):
        return obj
    if isinstance(obj, dict):
        new = obj.__class__()
        for k, v in obj.items():
            new[convert(k)] = change_keys(v, convert)
    elif isinstance(obj, (list, set, tuple)):
        new = obj.__class__((change_keys(v, convert) for v in obj))
    else:
        return obj
    return new

def csrf(request):
    """Context processor that provides a CSRF token, or the string 'NOTPROVIDED'
    if it has not been provided by either a view decorator or the middleware"""
    def _get_val():
        token = get_token(request)
        if token is None:
            return 'NOTPROVIDED'
        else:
            token = force_bytes(token, encoding='latin-1')
            key = force_bytes(get_random_string(len(token)), encoding='latin-1')
            value = b64_encode(xor(token, key))
            return force_text(b'$'.join((key, value)), encoding='latin-1')
    _get_val = lazy(_get_val, text_type)
    return {'csrf_token': _get_val()}

def regex_validation_sealer(fields, defaults, RegexType=type(re.compile(''))):
    """Example sealer that just does regex-based validation."""
    required = set(fields) - set(defaults)
    if required:
        raise TypeError("regex_validation_sealer doesn't support required arguments. Fields that need fixing: %s" % required)
    klass = None
    kwarg_validators = dict(((key, val if isinstance(val, RegexType) else re.compile(val)) for key, val in defaults.items()))
    arg_validators = list((kwarg_validators[key] for key in fields))
    def __init__(self, *args, **kwargs):
        for pos, (value, validator) in enumerate(zip(args, arg_validators)):
            if not validator.match(value):
                raise ValidationError("Positional argument %s failed validation. %r doesn't match regex %r" % (pos, value, validator.pattern))
        for key, value in kwargs.items():
            if key in kwarg_validators:
                validator = kwarg_validators[key]
                if not validator.match(value):
                    raise ValidationError("Keyword argument %r failed validation. %r doesn't match regex %r" % (key, value, validator.pattern))
        super(klass, self).__init__(*args, **kwargs)
    klass = type('RegexValidateBase', (__base__,), dict(__init__=__init__))
    return klass

def slots_class_sealer(fields, defaults):
    """This sealer makes a container class that uses ``__slots__`` (it uses :func:`class_sealer` internally).

    The resulting class has a metaclass that forcibly sets ``__slots__`` on subclasses."""
    class __slots_meta__(type):
        def __new__(mcs, name, bases, namespace):
            if '__slots__' not in namespace:
                namespace['__slots__'] = fields
            return type.__new__(mcs, name, bases, namespace)
    class __slots_base__(_with_metaclass(__slots_meta__, object)):
        __slots__ = ()
        def __init__(self, *args, **kwargs):
            pass
    return class_sealer(fields, defaults, base=__slots_base__)

def tuple_sealer(fields, defaults):
    """This sealer returns an equivalent of a ``namedtuple``."""
    baseclass_name = 'FieldsBase_for__{0}'.format('__'.join(fields))
    global_namespace, local_namespace = make_init_func(fields, defaults, baseclass_name, header_name='__new__', header_start='def {func_name}(cls', header_end='):\n', super_call_start='return tuple.__new__(cls, (', super_call_end='))\n', super_call_pass_kwargs=False, set_attributes=False)
    def __getnewargs__(self):
        return tuple(self)
    def __repr__(self):
        return '{0}({1})'.format(self.__class__.__name__, ', '.join((a + '=' + repr(getattr(self, a)) for a in fields)))
    return type(baseclass_name, (tuple,), dict([(name, property(itemgetter(i))) for i, name in enumerate(fields)], __new__=local_namespace['__new__'], __getnewargs__=__getnewargs__, __repr__=__repr__, __slots__=()))

def lpr_kurtosis(frame, lpcorder=10):
    """frame: windowed signal
    return kurtosis of linear prediction residual from input signal"""
    c = lpc(frame, lpcorder)
    coef = c[1:][::-1] * -1
    residuals = []
    for i in xrange(frame.size - 10):
        residuals.append(frame[i + 10] - np.sum(frame[i:i + 10] * coef))
    residuals = np.array(residuals)
    return calc_kurtosis(residuals)

def xor(s, pad):
    """XOR a given string ``s`` with the one-time-pad ``pad``"""
    from itertools import cycle
    s = bytearray(force_bytes(s, encoding='latin-1'))
    pad = bytearray(force_bytes(pad, encoding='latin-1'))
    return binary_type(bytearray((x ^ y for x, y in zip(s, cycle(pad)))))

def apply_lens(df, lens='pca', dist='euclidean', n_dim=2, **kwargs):
    """input: N x F dataframe of observations
    output: N x n_dim image of input data under lens function"""
    if n_dim != 2:
        raise 'error: image of data set must be two-dimensional'
    if dist not in ['euclidean', 'correlation']:
        raise 'error: only euclidean and correlation distance metrics are supported'
    if lens == 'pca' and dist != 'euclidean':
        raise 'error: PCA requires the use of euclidean distance metric'
    if lens == 'pca':
        df_lens = pd.DataFrame(decomposition.PCA(n_components=n_dim, **kwargs).fit_transform(df), df.index)
    elif lens == 'mds':
        D = metrics.pairwise.pairwise_distances(df, metric=dist)
        df_lens = pd.DataFrame(manifold.MDS(n_components=n_dim, **kwargs).fit_transform(D), df.index)
    elif lens == 'neighbor':
        D = metrics.pairwise.pairwise_distances(df, metric=dist)
        df_lens = pd.DataFrame(manifold.SpectralEmbedding(n_components=n_dim, **kwargs).fit_transform(D), df.index)
    else:
        raise 'error: only PCA, MDS, neighborhood lenses are supported'
    return df_lens

def _render_iteratable(iteratable, level):
    """Renders iteratable sequence of HTML elements."""
    if isinstance(iteratable, basestring):
        return unicode(iteratable)
    return ''.join([render(element, level) for element in iteratable])

def _serialize_attributes(attributes):
    """Serializes HTML element attributes in a name="value" pair form."""
    result = ''
    for name, value in attributes.items():
        if not value:
            continue
        result += ' ' + _unmangle_attribute_name(name)
        result += '="' + escape(value, True) + '"'
    return result

def escape(string, quote=False):
    """Standard HTML text escaping, but protecting against the agressive
    behavior of Jinja 2 `Markup` and the like."""
    if string is None:
        return ''
    elif hasattr(string, '__html__'):
        return unicode(string)
    string = string.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')
    if quote:
        string = string.replace('"', '&quot;')
    return string

def expand_user(path):
    """Expands ~/path to /home/<current_user>/path

    On POSIX systems does it by getting the home directory for the
    current effective user from the passwd database. On other systems
    do it by using :func:`os.path.expanduser`

    Args:
        path (str): A path to expand to a user's home folder

    Returns:
        str: expanded path"""
    if not path.startswith('~'):
        return path
    if os.name == 'posix':
        user = pwd.getpwuid(os.geteuid())
        return path.replace('~', user.pw_dir, 1)
    else:
        return os.path.expanduser(path)

def format_arguments(*args):
    """Converts a list of arguments from the command line into a list of
    positional arguments and a dictionary of keyword arguments.

    Handled formats for keyword arguments are:
    * --argument=value
    * --argument value

    Args:
      *args (list): a list of arguments

    Returns:
      ([positional_args], {kwargs})"""
    positional_args = []
    kwargs = {}
    split_key = None
    for arg in args:
        if arg.startswith('--'):
            arg = arg[2:]
            if '=' in arg:
                key, value = arg.split('=', 1)
                kwargs[key.replace('-', '_')] = value
            else:
                split_key = arg.replace('-', '_')
        elif split_key:
            kwargs[split_key] = arg
            split_key = None
        else:
            positional_args.append(arg)
    return (positional_args, kwargs)

def _prompt(pre_prompt, items, post_prompt, default, indexed, stream):
    """Prompt once.
    If you want the default displayed, put a format {} into the
    post_prompt string (like 'select one [{}]: ')"""
    if default is not None:
        if '{}' in pre_prompt:
            pre_prompt = pre_prompt.format(default)
        if '{}' in post_prompt:
            post_prompt = post_prompt.format(default)
    item_format = '{indent}{item}'
    if indexed:
        item_format = '{indent}[{index}] {item}'
    item_text_list = []
    indent = '  '
    for index, item in enumerate(items):
        item_text = ''
        components = {'indent': indent, 'item': item}
        if indexed:
            components['index'] = index
        item_text = item_format.format(**components)
        item_text_list.append(item_text)
    menu_parts = [pre_prompt] + item_text_list
    full_menu = '\n'.join(menu_parts) + '\n'
    stream.write(full_menu)
    stream.flush()
    get_input = input
    try:
        get_input = raw_input
    except NameError:
        pass
    response = get_input(post_prompt)
    return response

def _fuzzily_matches(response, candidate):
    """return True if response fuzzily matches candidate"""
    r_words = response.split()
    c_words = candidate.split()
    for word in r_words:
        if word in c_words:
            r_words.remove(word)
            c_words.remove(word)
    match_pairs = []
    for partial in sorted(r_words, key=lambda p: len(p), reverse=True):
        matches = [w for w in c_words if partial in w]
        match_pairs.append((partial, matches))
    while len(match_pairs):
        min_pair = min(match_pairs, key=lambda x: len(x[1]))
        if len(min_pair[1]) == 0:
            return False
        partials_left = [p[0] for p in match_pairs]
        min_option = min(min_pair[1], key=lambda x: len([p for p in partials_left if x in p]))
        match_pairs.remove(min_pair)
        for pair in match_pairs:
            pair_options = pair[1]
            if min_option in pair_options:
                pair_options.remove(min_option)
    return True

def _exact_fuzzy_match(response, match, insensitive):
    """Return True if the response matches fuzzily exactly.
    Insensitivity is taken into account."""
    if insensitive:
        response = response.lower()
        match = match.lower()
    r_words = response.split()
    m_words = match.split()
    for word in r_words:
        if word in m_words:
            r_words.remove(word)
            m_words.remove(word)
    return len(r_words) == 0 and len(m_words) == 0

def _exact_match(response, matches, insensitive, fuzzy):
    """returns an exact match, if it exists, given parameters
    for the match"""
    for match in matches:
        if response == match:
            return match
        elif insensitive and response.lower() == match.lower():
            return match
        elif fuzzy and _exact_fuzzy_match(response, match, insensitive):
            return match
    else:
        return None

