def delete():
    """Delete a post."""
    form = DeleteForm()
    path = request.form['path']
    post = find_post(path)
    if post is None:
        return error('No such post or page.', 404)
    if not form.validate():
        return error('Bad Request', 400)
    current_auid = int(post.meta('author.uid') or current_user.uid)
    if not current_user.can_edit_all_posts and current_auid != current_user.uid:
        return error('Cannot edit posts of other users.', 401)
    os.unlink(path)
    if post.is_two_file:
        meta_path = os.path.splitext(path)[0] + '.meta'
        os.unlink(meta_path)
    scan_site()
    if db is not None:
        db.set('site:needs_rebuild', '1')
    else:
        site.coil_needs_rebuild = '1'
    return redirect(url_for('index'))

def rebuild(mode=''):
    """Rebuild the site with a nice UI."""
    scan_site()
    if not current_user.can_rebuild_site:
        return error('You are not permitted to rebuild the site.</p><p class="lead">Contact an administartor for more information.', 401)
    if db is not None:
        db.set('site:needs_rebuild', '-1')
        if not q.fetch_job('build') and (not q.fetch_job('orphans')):
            b = q.enqueue_call(func=coil.tasks.build, args=(app.config['REDIS_URL'], app.config['NIKOLA_ROOT'], mode), job_id='build')
            q.enqueue_call(func=coil.tasks.orphans, args=(app.config['REDIS_URL'], app.config['NIKOLA_ROOT']), job_id='orphans', depends_on=b)
        return render('coil_rebuild.tmpl', {'title': 'Rebuild'})
    else:
        status, outputb = coil.tasks.build_single(mode)
        _, outputo = coil.tasks.orphans_single()
        site.coil_needs_rebuild = '0'
        return render('coil_rebuild_single.tmpl', {'title': 'Rebuild', 'status': '1' if status else '0', 'outputb': outputb, 'outputo': outputo})

