def is_installed():
    """Returns whether the C extension is installed correctly."""
    try:
        from ccurl import Curl as CCurl
    except ImportError:
        return False
    else:
        from iota.crypto import Curl
        return issubclass(Curl, CCurl)

def make_compare(key, value, obj):
    """Map a key name to a specific comparison function"""
    if '__' not in key:
        key, comp = (key, 'exact')
    else:
        key, comp = key.rsplit('__', 1)
    if hasattr(Compare, comp):
        return getattr(Compare, comp)(key, value, obj)
    raise AttributeError("No comparison '%s'" % comp)

def ask(query, default=None):
    """Ask a question."""
    if default:
        default_q = ' [{0}]'.format(default)
    else:
        default_q = ''
    if sys.version_info[0] == 3:
        inp = input('{query}{default_q}: '.format(query=query, default_q=default_q)).strip()
    else:
        inp = raw_input('{query}{default_q}: '.format(query=query, default_q=default_q).encode('utf-8')).strip()
    if inp or default is None:
        return inp
    else:
        return default

def ask_yesno(query, default=None):
    """Ask a yes/no question."""
    if default is None:
        default_q = ' [y/n]'
    elif default is True:
        default_q = ' [Y/n]'
    elif default is False:
        default_q = ' [y/N]'
    if sys.version_info[0] == 3:
        inp = raw_input('{query}{default_q} '.format(query=query, default_q=default_q)).strip()
    else:
        inp = raw_input('{query}{default_q} '.format(query=query, default_q=default_q).encode('utf-8')).strip()
    if inp:
        return inp.lower().startswith('y')
    elif default is not None:
        return default
    else:
        return ask_yesno(query, default)

def get_m2m_value(session, request, obj):
    """Set m2m value for model obj from request params like "group[]"

    :Parameters:

        - `session`: SQLAlchemy DBSession
        - `request`: request as dict
        - `obj`: model instance"""
    params = {}
    ' m2m_request:\n\n        {u\'company[]\': [u\'["id", 1]\'],\n         u\'professions[]\': [u\'["id", 2]\', u\'["id", 3]\']}\n    '
    m2m_request = {k: v for k, v in list(request.items()) if k.endswith('[]')}
    for k, v in list(m2m_request.items()):
        key = k[:-2]
        relation = getattr(obj.__class__, key, False)
        if not relation:
            relation = getattr(obj, key, False)
        if not relation:
            continue
        value = get_m2m_objs(session, relation, v)
        if value is None:
            continue
        if relation.property.uselist is False:
            if value:
                value = value[0]
            else:
                value = None
        params[key] = value
    return params

def dumps(number):
    """Dumps an integer into a base36 string.

    :param number: the 10-based integer.
    :returns: the base36 string."""
    if not isinstance(number, integer_types):
        raise TypeError('number must be an integer')
    if number < 0:
        return '-' + dumps(-number)
    value = ''
    while number != 0:
        number, index = divmod(number, len(alphabet))
        value = alphabet[index] + value
    return value or '0'

def opls_notation(atom_key):
    """Return element for OPLS forcefield atom key."""
    conflicts = ['ne', 'he', 'na']
    if atom_key in conflicts:
        raise _AtomKeyConflict("One of the OPLS conflicting atom_keys has occured '{0}'. For how to solve this issue see the manual or MolecularSystem._atom_key_swap() doc string.".format(atom_key))
    for element in opls_atom_keys:
        if atom_key in opls_atom_keys[element]:
            return element
    raise _AtomKeyError('OPLS atom key {0} was not found in OPLS keys dictionary.'.format(atom_key))

def pore_diameter(elements, coordinates, com=None):
    """Return pore diameter of a molecule."""
    if com is None:
        com = center_of_mass(elements, coordinates)
    atom_vdw = np.array([[atomic_vdw_radius[x.upper()]] for x in elements])
    dist_matrix = euclidean_distances(coordinates, com.reshape(1, -1))
    re_dist_matrix = dist_matrix - atom_vdw
    index = np.argmin(re_dist_matrix)
    pored = re_dist_matrix[index][0] * 2
    return (pored, index)

def opt_pore_diameter(elements, coordinates, bounds=None, com=None, **kwargs):
    """Return optimised pore diameter and it's COM."""
    args = (elements, coordinates)
    if com is not None:
        pass
    else:
        com = center_of_mass(elements, coordinates)
    if bounds is None:
        pore_r = pore_diameter(elements, coordinates, com=com)[0] / 2
        bounds = ((com[0] - pore_r, com[0] + pore_r), (com[1] - pore_r, com[1] + pore_r), (com[2] - pore_r, com[2] + pore_r))
    minimisation = minimize(correct_pore_diameter, x0=com, args=args, bounds=bounds)
    pored = pore_diameter(elements, coordinates, com=minimisation.x)
    return (pored[0], pored[1], minimisation.x)

def fractional_from_cartesian(coordinate, lattice_array):
    """Return a fractional coordinate from a cartesian one."""
    deorthogonalisation_M = np.matrix(np.linalg.inv(lattice_array))
    fractional = deorthogonalisation_M * coordinate.reshape(-1, 1)
    return np.array(fractional.reshape(1, -1))

def cartisian_from_fractional(coordinate, lattice_array):
    """Return cartesian coordinate from a fractional one."""
    orthogonalisation_M = np.matrix(lattice_array)
    orthogonal = orthogonalisation_M * coordinate.reshape(-1, 1)
    return np.array(orthogonal.reshape(1, -1))

def cart2frac_all(coordinates, lattice_array):
    """Convert all cartesian coordinates to fractional."""
    frac_coordinates = deepcopy(coordinates)
    for coord in range(frac_coordinates.shape[0]):
        frac_coordinates[coord] = fractional_from_cartesian(frac_coordinates[coord], lattice_array)
    return frac_coordinates

def frac2cart_all(frac_coordinates, lattice_array):
    """Convert all fractional coordinates to cartesian."""
    coordinates = deepcopy(frac_coordinates)
    for coord in range(coordinates.shape[0]):
        coordinates[coord] = cartisian_from_fractional(coordinates[coord], lattice_array)
    return coordinates

def vector_analysis(vector, coordinates, elements_vdw, increment=1.0):
    """Analyse a sampling vector's path for window analysis purpose."""
    chunks = int(np.linalg.norm(vector) // increment)
    chunk = vector / chunks
    vector_pathway = np.array([chunk * i for i in range(chunks + 1)])
    analysed_vector = np.array([np.amin(euclidean_distances(coordinates, i.reshape(1, -1)) - elements_vdw) for i in vector_pathway])
    if all((i > 0 for i in analysed_vector)):
        pos = np.argmin(analysed_vector)
        dist = np.linalg.norm(chunk * pos)
        return np.array([dist, analysed_vector[pos] * 2, *chunk * pos, *vector])

def debounce(wait):
    """Decorator that will postpone a functions
    execution until after wait seconds
    have elapsed since the last time it was invoked."""
    def decorator(fn):
        def debounced(*args, **kwargs):
            def call_it():
                fn(*args, **kwargs)
            try:
                debounced.t.cancel()
            except AttributeError:
                pass
            debounced.t = threading.Timer(wait, call_it)
            debounced.t.start()
        return debounced
    return decorator

def check_version_2(dataset):
    """Checks if json-stat version attribute exists and is equal or greater        than 2.0 for a given dataset.

    Args:
      dataset (OrderedDict): data in JSON-stat format, previously                                    deserialized to a python object by                                    json.load() or json.loads(),

    Returns:
      bool: True if version exists and is equal or greater than 2.0,                False otherwise. For datasets without the version attribute,                always return False."""
    if float(dataset.get('version')) >= 2.0 if dataset.get('version') else False:
        return True
    else:
        return False

def unnest_collection(collection, df_list):
    """Unnest collection structure extracting all its datasets and converting        them to Pandas Dataframes.

    Args:
      collection (OrderedDict): data in JSON-stat format, previously                                       deserialized to a python object by                                       json.load() or json.loads(),
      df_list (list): list variable which will contain the converted                             datasets.

    Returns:
      Nothing."""
    for item in collection['link']['item']:
        if item['class'] == 'dataset':
            df_list.append(Dataset.read(item['href']).write('dataframe'))
        elif item['class'] == 'collection':
            nested_collection = request(item['href'])
            unnest_collection(nested_collection, df_list)

def get_dim_index(js_dict, dim):
    """Get index from a given dimension.

    Args:
      js_dict (dict): dictionary containing dataset data and metadata.
      dim (string): dimension name obtained from JSON file.

    Returns:
      dim_index (pandas.DataFrame): DataFrame with index-based dimension data."""
    try:
        dim_index = js_dict['dimension'][dim]['category']['index']
    except KeyError:
        dim_label = get_dim_label(js_dict, dim)
        dim_index = pd.DataFrame(list(zip([dim_label['id'][0]], [0])), index=[0], columns=['id', 'index'])
    else:
        if type(dim_index) is list:
            dim_index = pd.DataFrame(list(zip(dim_index, range(0, len(dim_index)))), index=dim_index, columns=['id', 'index'])
        else:
            dim_index = pd.DataFrame(list(zip(dim_index.keys(), dim_index.values())), index=dim_index.keys(), columns=['id', 'index'])
    dim_index = dim_index.sort_index(by='index')
    return dim_index

def get_values(js_dict, value='value'):
    """Get values from input data.

    Args:
      js_dict (dict): dictionary containing dataset data and metadata.
      value (string, optional): name of the value column. Defaults to 'value'.

    Returns:
      values (list): list of dataset values."""
    values = js_dict[value]
    if type(values) is list:
        if type(values[0]) is not dict or tuple:
            return values
    values = {int(key): value for key, value in values.items()}
    if js_dict.get('size'):
        max_val = np.prod(np.array(js_dict['size']))
    else:
        max_val = np.prod(np.array(js_dict['dimension']['size']))
    vals = max_val * [None]
    for key, value in values.items():
        vals[key] = value
    values = vals
    return values

def get_df_row(dimensions, naming='label', i=0, record=None):
    """Generate row dimension values for a pandas dataframe.

    Args:
      dimensions (list): list of pandas dataframes with dimension labels                          generated by get_dim_label or get_dim_index methods.
      naming (string, optional): dimension naming. Possible values: 'label'                                  or 'id'.
      i (int): dimension list iteration index. Default is 0, it's used in the                          recursive calls to the method.
      record (list): list of values representing a pandas dataframe row,                      except for the value column. Default is empty, it's used                      in the recursive calls to the method.

    Yields:
      list: list with pandas dataframe column values except for value column"""
    check_input(naming)
    if i == 0 or record is None:
        record = []
    for dimension in dimensions[i][naming]:
        record.append(dimension)
        if len(record) == len(dimensions):
            yield record
        if i + 1 < len(dimensions):
            for row in get_df_row(dimensions, naming, i + 1, record):
                yield row
        if len(record) == i + 1:
            record.pop()

def auth_required(func):
    """Utility decorator that checks if a user has been authenticated for this
    request.

    Allows views to be decorated like:

        @auth_required
        def view_func(request):
            pass

    providing a simple means to ensure that whoever is calling the function has
    the correct authentication details.

    Args:
        func: Function object being decorated and raises HTTPForbidden if not

    Returns:
        A function object that will raise web.HTTPForbidden() if the passed
        request does not have the correct permissions to access the view."""
    @wraps(func)
    async def wrapper(*args):
        if await get_auth(args[-1]) is None:
            raise web.HTTPForbidden()
        return await func(*args)
    return wrapper

def render_partial(parser, token):
    """Inserts the output of a view, using fully qualified view name,
    or view name from urls.py.

      {% render_partial view_name arg[ arg2] k=v [k2=v2...] %}

    IMPORTANT: the calling template must receive a context variable called
    'request' containing the original HttpRequest. This means you should be OK
    with permissions and other session state.

    (Note that every argument will be evaluated against context except for the
    names of any keyword arguments.)"""
    args = []
    kwargs = {}
    tokens = token.split_contents()
    if len(tokens) < 2:
        raise TemplateSyntaxError('%r tag requires one or more arguments' % token.contents.split()[0])
    tokens.pop(0)
    view_name = tokens.pop(0)
    for token in tokens:
        equals = token.find('=')
        if equals == -1:
            args.append(token)
        else:
            kwargs[str(token[:equals])] = token[equals + 1:]
    return ViewNode(view_name, args, kwargs)

def render_wavedrom(self, node, outpath, bname, format):
    """Render a wavedrom image"""
    try:
        svgout = WaveDrom().renderWaveForm(0, json.loads(node['code']))
    except JSONDecodeError as e:
        raise SphinxError('Cannot render the following json code: \n{} \n\nError: {}'.format(node['code'], e))
    if not os.path.exists(outpath):
        os.makedirs(outpath)
    if format == 'image/svg+xml':
        fname = '{}.{}'.format(bname, 'svg')
        fpath = os.path.join(outpath, fname)
        svgout.saveas(fpath)
        return fname
    try:
        import cairosvg
    except:
        raise SphinxError(__("Cannot import 'cairosvg'. In Python 2 wavedrom figures other than svg are not supported, in Python 3 ensure 'cairosvg' is installed."))
    if format == 'application/pdf':
        fname = '{}.{}'.format(bname, 'pdf')
        fpath = os.path.join(outpath, fname)
        cairosvg.svg2pdf(svgout.tostring(), write_to=fpath)
        return fname
    if format == 'image/png':
        fname = '{}.{}'.format(bname, 'png')
        fpath = os.path.join(outpath, fname)
        cairosvg.svg2png(svgout.tostring(), write_to=fpath)
        return fname
    raise SphinxError('No valid wavedrom conversion supplied')

def builder_inited(app):
    """Sets wavedrom_html_jsinline to False for all non-html builders for
    convenience (use ifconf etc.)

    We instruct sphinx to include some javascript files in the output html.
    Depending on the settings provided in the configuration, we take either
    the online files from the wavedrom server, or the locally provided wavedrom
    javascript files"""
    if app.config.wavedrom_html_jsinline and app.builder.name not in ('html', 'dirhtml', 'singlehtml'):
        app.config.wavedrom_html_jsinline = False
    if not app.env.config.wavedrom_html_jsinline:
        return
    if app.config.offline_skin_js_path is not None:
        app.add_javascript(path.basename(app.config.offline_skin_js_path))
    else:
        app.add_javascript(ONLINE_SKIN_JS)
    if app.config.offline_wavedrom_js_path is not None:
        app.add_javascript(path.basename(app.config.offline_wavedrom_js_path))
    else:
        app.add_javascript(ONLINE_WAVEDROM_JS)

