def skip_read_line(fd, no_eof=False):
    """Read the first non-empty line (if any) from the given file
    object. Return an empty string at EOF, if `no_eof` is False. If it
    is True, raise the EOFError instead."""
    ls = ''
    while 1:
        try:
            line = fd.readline()
        except EOFError:
            break
        if not line:
            if no_eof:
                raise EOFError
            else:
                break
        ls = line.strip()
        if ls and ls[0] != '#':
            break
    return ls

def read_token(fd):
    """Read a single token (sequence of non-whitespace characters) from the
    given file object.

    Notes
    -----
    Consumes the first whitespace character after the token."""
    out = ''
    while 1:
        ch = fd.read(1)
        if ch.isspace():
            continue
        elif len(ch) == 0:
            return out
        else:
            break
    while not ch.isspace():
        out = out + ch
        ch = fd.read(1)
        if len(ch) == 0:
            break
    return out

def override(settings, yaml=None, env=None):
    """:param dict settings: settings dict to be updated; usually it's ``globals()``
    :param yaml: path to YAML file
    :type yaml: str or FileIO
    :param str env: prefix for environment variables"""
    if yaml is not None:
        if hasattr(yaml, 'read'):
            settings.update(load_yaml(yaml.read()))
        elif os.path.exists(yaml):
            with open(yaml) as f:
                settings.update(load_yaml(f.read()))
    if env is not None:
        for k, v in os.environ.items():
            if k.startswith(env):
                settings[k[len(env):]] = load_yaml(v)

