def luhn(candidate):
    """Checks a candidate number for validity according to the Luhn
    algorithm (used in validation of, for example, credit cards).
    Both numeric and string candidates are accepted."""
    if not isinstance(candidate, six.string_types):
        candidate = str(candidate)
    try:
        evens = sum((int(c) for c in candidate[-1::-2]))
        odds = sum((LUHN_ODD_LOOKUP[int(c)] for c in candidate[-2::-2]))
        return (evens + odds) % 10 == 0
    except ValueError:
        return False

def get_debug():
    """Utility function providing ``debug()`` function."""
    try:
        import IPython
    except ImportError:
        debug = None
    else:
        old_excepthook = sys.excepthook
        def debug(frame=None):
            if IPython.__version__ >= '0.11':
                from IPython.core.debugger import Pdb
                try:
                    ip = get_ipython()
                except NameError:
                    from IPython.frontend.terminal.embed import InteractiveShellEmbed
                    ip = InteractiveShellEmbed()
                colors = ip.colors
            else:
                from IPython.Debugger import Pdb
                from IPython.Shell import IPShell
                from IPython import ipapi
                ip = ipapi.get()
                if ip is None:
                    IPShell(argv=[''])
                    ip = ipapi.get()
                colors = ip.options.colors
            sys.excepthook = old_excepthook
            if frame is None:
                frame = sys._getframe().f_back
            Pdb(colors).set_trace(frame)
    if debug is None:
        import pdb
        debug = pdb.set_trace
    debug.__doc__ = '\n    Start debugger on line where it is called, roughly equivalent to::\n\n        import pdb; pdb.set_trace()\n\n    First, this function tries to start an `IPython`-enabled\n    debugger using the `IPython` API.\n\n    When this fails, the plain old `pdb` is used instead.\n    '
    return debug

def import_file(filename, package_name=None):
    """Import a file as a module. The module is explicitly reloaded to
    prevent undesirable interactions."""
    path = os.path.dirname(filename)
    if not path in sys.path:
        sys.path.append(path)
        remove_path = True
    else:
        remove_path = False
    name = os.path.splitext(os.path.basename(filename))[0]
    if name in sys.modules:
        force_reload = True
    else:
        force_reload = False
    if package_name is not None:
        mod = __import__('.'.join((package_name, name)), fromlist=[name])
    else:
        mod = __import__(name)
    if force_reload:
        reload(mod)
    if remove_path:
        sys.path.pop(-1)
    return mod

def add_metaclass(metaclass):
    """Class decorator for creating a class with a metaclass.

    Adapted from the six project:

    https://pythonhosted.org/six/"""
    vars_to_skip = ('__dict__', '__weakref__')
    def wrapper(cls):
        copied_dict = {key: value for key, value in cls.__dict__.items() if key not in vars_to_skip}
        return metaclass(cls.__name__, cls.__bases__, copied_dict)
    return wrapper

def drain(iterable):
    """Helper method that empties an iterable as it is iterated over.

    Works for:

    * ``dict``
    * ``collections.deque``
    * ``list``
    * ``set``"""
    if getattr(iterable, 'popleft', False):
        def next_item(coll):
            return coll.popleft()
    elif getattr(iterable, 'popitem', False):
        def next_item(coll):
            return coll.popitem()
    else:
        def next_item(coll):
            return coll.pop()
    while True:
        try:
            yield next_item(iterable)
        except (IndexError, KeyError):
            raise StopIteration

def spread(nodes, n):
    """Distrubute master instances in different nodes

    {
        "192.168.0.1": [node1, node2],
        "192.168.0.2": [node3, node4],
        "192.168.0.3": [node5, node6]
    } => [node1, node3, node5]"""
    target = []
    while len(target) < n and nodes:
        for ip, node_group in list(nodes.items()):
            if not node_group:
                nodes.pop(ip)
                continue
            target.append(node_group.pop(0))
            if len(target) >= n:
                break
    return target

def expand_folder(files):
    """Return a clone of file list files where all directories are recursively replaced with their contents."""
    expfiles = []
    for file in files:
        if os.path.isdir(file):
            for dirpath, dirnames, filenames in os.walk(file):
                for filename in filenames:
                    expfiles.append(os.path.join(dirpath, filename))
        else:
            expfiles.append(file)
    for path in expfiles:
        if not os.path.exists(path):
            sys.stderr.write('%s: No such file or directory\n' % path)
    return expfiles

