def _positive_int(integer_string, strict=False, cutoff=None):
    """Cast a string to a strictly positive integer."""
    ret = int(integer_string)
    if ret < 0 or (ret == 0 and strict):
        raise ValueError()
    if cutoff:
        ret = min(ret, cutoff)
    return ret

def inject(fun: Callable) -> Callable:
    """A decorator for injection dependencies into functions/methods, based
    on their type annotations.

    .. code-block:: python

        class SomeClass:
            @inject
            def __init__(self, my_dep: DepType) -> None:
                self.my_dep = my_dep

    .. important::

        On the opposite to :class:`~haps.Inject`, dependency is injected
        at the moment of method invocation. In case of decorating `__init__`,
        dependency is injected when `SomeClass` instance is created.

    :param fun: callable with annotated parameters
    :return: decorated callable"""
    sig = inspect.signature(fun)
    injectables: Dict[str, Any] = {}
    for name, param in sig.parameters.items():
        type_ = param.annotation
        if name == 'self':
            continue
        else:
            injectables[name] = type_
    @wraps(fun)
    def _inner(*args, **kwargs):
        container = Container()
        for n, t in injectables.items():
            if n not in kwargs:
                kwargs[n] = container.get_object(t)
        return fun(*args, **kwargs)
    return _inner

def scope(scope_type: str) -> Callable:
    """A function that returns decorator that set scopes to some class/function

    .. code-block:: python

        @egg()
        @scopes(SINGLETON_SCOPE)
        class DepImpl:
            pass

    :param scope_type: Which scope should be used
    :return:"""
    def dec(egg_: T) -> T:
        egg_.__haps_custom_scope = scope_type
        return egg_
    return dec

def render_article(request, article, current_language, slug):
    """Renders an article"""
    context = {}
    context['article'] = article
    context['lang'] = current_language
    context['current_article'] = article
    context['has_change_permissions'] = article.has_change_permission(request)
    response = TemplateResponse(request, article.template, context)
    response.add_post_render_callback(set_page_cache)
    xframe_options = article.tree.get_xframe_options()
    if xframe_options == Page.X_FRAME_OPTIONS_INHERIT or xframe_options is None:
        return response
    response.xframe_options_exempt = True
    if xframe_options == Page.X_FRAME_OPTIONS_ALLOW:
        return response
    elif xframe_options == Page.X_FRAME_OPTIONS_SAMEORIGIN:
        response['X-Frame-Options'] = 'SAMEORIGIN'
    elif xframe_options == Page.X_FRAME_OPTIONS_DENY:
        response['X-Frame-Options'] = 'DENY'
    return response

