def build_preauth_str(preauth_key, account_name, timestamp, expires, admin=False):
    """Builds the preauth string and hmac it, following the zimbra spec.

    Spec and examples are here http://wiki.zimbra.com/wiki/Preauth"""
    if admin:
        s = '{0}|1|name|{1}|{2}'.format(account_name, expires, timestamp)
    else:
        s = '{0}|name|{1}|{2}'.format(account_name, expires, timestamp)
    return hmac.new(preauth_key.encode('utf-8'), s.encode('utf-8'), hashlib.sha1).hexdigest()

def auto_type(s):
    """Get a XML response and tries to convert it to Python base object
    """
    if isinstance(s, bool):
        return s
    elif s is None:
        return ''
    elif s == 'TRUE':
        return True
    elif s == 'FALSE':
        return False
    else:
        try:
            try:
                if s.startswith('+'):
                    return s
                else:
                    return int(s)
            except ValueError:
                return float(s)
        except ValueError:
            return s

def do_macro(parser, token):
    """the function taking the parsed tag and returning
    a DefineMacroNode object."""
    try:
        bits = token.split_contents()
        tag_name, macro_name, arguments = (bits[0], bits[1], bits[2:])
    except IndexError:
        raise template.TemplateSyntaxError("'{0}' tag requires at least one argument (macro name)".format(token.contents.split()[0]))
    arg_regex = '^([A-Za-z_][\\w_]*)$'
    kwarg_regex = '^([A-Za-z_][\\w_]*)=(".*"|{0}.*{0}|[A-Za-z_][\\w_]*)$'.format("'")
    args = []
    kwargs = {}
    for argument in arguments:
        arg_match = regex_match(arg_regex, argument)
        if arg_match:
            args.append(arg_match.groups()[0])
        else:
            kwarg_match = regex_match(kwarg_regex, argument)
            if kwarg_match:
                kwargs[kwarg_match.groups()[0]] = template.Variable(kwarg_match.groups()[1])
            else:
                raise template.TemplateSyntaxError('Malformed arguments to the {0} tag.'.format(tag_name))
    nodelist = parser.parse(('endmacro',))
    parser.delete_first_token()
    _setup_macros_dict(parser)
    parser._macros[macro_name] = DefineMacroNode(macro_name, nodelist, args, kwargs)
    return parser._macros[macro_name]

def do_loadmacros(parser, token):
    """The function taking a parsed tag and returning
    a LoadMacrosNode object, while also loading the macros
    into the page."""
    try:
        tag_name, filename = token.split_contents()
    except ValueError:
        raise template.TemplateSyntaxError("'{0}' tag requires exactly one argument (filename)".format(token.contents.split()[0]))
    if filename[0] in ('"', "'") and filename[-1] == filename[0]:
        filename = filename[1:-1]
    else:
        raise template.TemplateSyntaxError('Malformed argument to the {0} template tag. Argument must be in quotes.'.format(tag_name))
    t = get_template(filename)
    try:
        nodelist = t.template.nodelist
    except AttributeError:
        nodelist = t.nodelist
    macros = nodelist.get_nodes_by_type(DefineMacroNode)
    _setup_macros_dict(parser)
    for macro in macros:
        parser._macros[macro.name] = macro
    return LoadMacrosNode(macros)

def parse_macro_params(token):
    """Common parsing logic for both use_macro and macro_block"""
    try:
        bits = token.split_contents()
        tag_name, macro_name, values = (bits[0], bits[1], bits[2:])
    except IndexError:
        raise template.TemplateSyntaxError('{0} tag requires at least one argument (macro name)'.format(token.contents.split()[0]))
    args = []
    kwargs = {}
    kwarg_regex = '^([A-Za-z_][\\w_]*)=(".*"|{0}.*{0}|[A-Za-z_][\\w_]*)$'.format("'")
    arg_regex = '^([A-Za-z_][\\w_]*|".*"|{0}.*{0}|(\\d+))$'.format("'")
    for value in values:
        kwarg_match = regex_match(kwarg_regex, value)
        if kwarg_match:
            kwargs[kwarg_match.groups()[0]] = template.Variable(kwarg_match.groups()[1])
        else:
            arg_match = regex_match(arg_regex, value)
            if arg_match:
                args.append(template.Variable(arg_match.groups()[0]))
            else:
                raise template.TemplateSyntaxError('Malformed arguments to the {0} tag.'.format(tag_name))
    return (tag_name, macro_name, args, kwargs)

def do_usemacro(parser, token):
    """The function taking a parsed template tag
    and returning a UseMacroNode."""
    tag_name, macro_name, args, kwargs = parse_macro_params(token)
    try:
        macro = parser._macros[macro_name]
    except (AttributeError, KeyError):
        raise template.TemplateSyntaxError("Macro '{0}' is not defined previously to the {1} tag".format(macro_name, tag_name))
    macro.parser = parser
    return UseMacroNode(macro, args, kwargs)

def do_macro_block(parser, token):
    """Function taking parsed template tag
    to a MacroBlockNode."""
    tag_name, macro_name, args, kwargs = parse_macro_params(token)
    try:
        macro = parser._macros[macro_name]
    except (AttributeError, KeyError):
        raise template.TemplateSyntaxError("Macro '{0}' is not defined ".format(macro_name) + 'previously to the {0} tag'.format(tag_name))
    nodelist = parser.parse(('endmacro_block',))
    parser.delete_first_token()
    for node in nodelist:
        if isinstance(node, MacroArgNode) and (not isinstance(node, MacroKwargNode)):
            args.append(node)
        elif isinstance(node, MacroKwargNode):
            if node.keyword in macro.kwargs:
                if node.keyword not in kwargs:
                    kwargs[node.keyword] = node
                else:
                    raise template.TemplateSyntaxError('{0} template tag was supplied the same keyword argument multiple times.'.format(tag_name))
            else:
                raise template.TemplateSyntaxError('{0} template tag was supplied with a keyword argument not defined by the {1} macro.'.format(tag_name, macro_name))
    if len(args) > len(macro.args):
        raise template.TemplateSyntaxError('{0} template tag was supplied too many arg block tags.'.format(tag_name))
    macro.parser = parser
    return MacroBlockNode(macro, nodelist, args, kwargs)

def do_macro_arg(parser, token):
    """Function taking a parsed template tag
    to a MacroArgNode."""
    nodelist = parser.parse(('endmacro_arg',))
    parser.delete_first_token()
    return MacroArgNode(nodelist)

def do_macro_kwarg(parser, token):
    """Function taking a parsed template tag
    to a MacroKwargNode."""
    try:
        tag_name, keyword = token.split_contents()
    except ValueError:
        raise template.TemplateSyntaxError('{0} tag requires exactly one argument, a keyword'.format(token.contents.split()[0]))
    nodelist = parser.parse(('endmacro_kwarg',))
    parser.delete_first_token()
    return MacroKwargNode(keyword, nodelist)

def get_modules(folder):
    """Find all valid modules in the given folder which must be in
    in the same directory as this loader.py module. A valid module
    has a .py extension, and is importable.
    @return: all loaded valid modules
    @rtype: iterator of module"""
    if is_frozen():
        zipname = os.path.dirname(os.path.dirname(__file__))
        parentmodule = os.path.basename(os.path.dirname(__file__))
        with zipfile.ZipFile(zipname, 'r') as f:
            prefix = '%s/%s/' % (parentmodule, folder)
            modnames = [os.path.splitext(n[len(prefix):])[0] for n in f.namelist() if n.startswith(prefix) and '__init__' not in n]
    else:
        dirname = os.path.join(os.path.dirname(__file__), folder)
        modnames = get_importable_modules(dirname)
    for modname in modnames:
        try:
            name = '..%s.%s' % (folder, modname)
            yield importlib.import_module(name, __name__)
        except ImportError as msg:
            out.error('could not load module %s: %s' % (modname, msg))

def get_importable_modules(folder):
    """Find all module files in the given folder that end with '.py' and
    don't start with an underscore.
    @return module names
    @rtype: iterator of string"""
    for fname in os.listdir(folder):
        if fname.endswith('.py') and (not fname.startswith('_')):
            yield fname[:-3]

def get_plugins(modules, classobj):
    """Find all class objects in all modules.
    @param modules: the modules to search
    @ptype modules: iterator of modules
    @return: found classes
    @rytpe: iterator of class objects"""
    for module in modules:
        for plugin in get_module_plugins(module, classobj):
            yield plugin

def get_module_plugins(module, classobj):
    """Return all subclasses of a class in the module.
    If the module defines __all__, only those entries will be searched,
    otherwise all objects not starting with '_' will be searched."""
    try:
        names = module.__all__
    except AttributeError:
        names = [x for x in vars(module) if not x.startswith('_')]
    for name in names:
        try:
            obj = getattr(module, name)
        except AttributeError:
            continue
        try:
            if issubclass(obj, classobj):
                yield obj
        except TypeError:
            continue

def get_online_version():
    """Download update info and parse it."""
    session = requests.session()
    page = urlopen(UPDATE_URL, session)
    version, url = (None, None)
    for line in page.text.splitlines():
        if line.startswith(VERSION_TAG):
            version = line.split(':', 1)[1].strip()
        elif line.startswith(URL_TAG):
            url = line.split(':', 1)[1].strip()
            url = url.replace('${version}', version)
    return (version, url)

def handle_url(url, session, res):
    """Parse one search result page."""
    print('Parsing', url, file=sys.stderr)
    try:
        data = getPageContent(url, session)
    except IOError as msg:
        print('ERROR:', msg, file=sys.stderr)
        return
    for match in url_matcher.finditer(data):
        comicurl = match.group(1)
        name = format_name(comicurl.split('.', 1)[0][7:])
        if name in exclude_comics:
            continue
        if contains_case_insensitive(res, name):
            print('INFO: skipping possible duplicate', repr(name), file=sys.stderr)
            continue
        end = match.end()
        mo = num_matcher.search(data[end:])
        if not mo:
            print('ERROR matching number:', repr(data[end:end + 300]), file=sys.stderr)
            continue
        num = int(mo.group(1))
        mo = activity_matcher.search(data[end:])
        if not mo:
            print('ERROR matching activity:', repr(data[end:end + 300]), file=sys.stderr)
            continue
        active = mo.group(1).lower() == 'active'
        res[name] = [comicurl, num, active]
    if not res:
        print('ERROR:', 'did not match any comics', file=sys.stderr)

