def lookup(instruction, instructions=None):
    """Looks up instruction, which can either be a function or a string.
    If it's a string, returns the corresponding method.
    If it's a function, returns the corresponding name."""
    if instructions is None:
        instructions = default_instructions
    if isinstance(instruction, str):
        return instructions[instruction]
    elif hasattr(instruction, '__call__'):
        rev = dict(((v, k) for k, v in instructions.items()))
        return rev[instruction]
    else:
        raise errors.MachineError(KeyError('Unknown instruction: %s' % str(instruction)))

def has_comic(name):
    """Check if comic name already exists."""
    names = [('Creators/%s' % name).lower(), ('DrunkDuck/%s' % name).lower(), ('GoComics/%s' % name).lower(), ('KeenSpot/%s' % name).lower(), ('ComicGenesis/%s' % name).lower(), ('SmackJeeves/%s' % name).lower()]
    for scraperclass in get_scraperclasses():
        lname = scraperclass.getName().lower()
        if lname in names or lname == name.lower():
            return True
    return False

