        instance.article.save(no_signals=True)

def digest_auth(realm, auth_func):
    """A decorator used to protect methods with HTTP Digest authentication.

    """
    def digest_auth_decorator(func):
        def func_replacement(self, *args, **kwargs):
            if self.get_authenticated_user(auth_func, realm):
                return func(self, *args, **kwargs)
        return func_replacement
    return digest_auth_decorator

def rnow(format='%Y-%m-%d %H:%M:%S', in_utc=False):
    """rnow

    Get right now as a string formatted datetime

    :param format: string output format for datetime
    :param in_utc: bool timezone in utc or local time"""
    if in_utc:
        return datetime.datetime.utcnow().strftime(format)
    else:
        return datetime.datetime.now().strftime(format)

def is_image(filename):
