def decorator(caller, func=None):
    """decorator(caller) converts a caller function into a decorator;
    decorator(caller, func) decorates a function using a caller."""
    if func is None:
        fun = FunctionMaker(caller)
        first_arg = inspect.getargspec(caller)[0][0]
        src = 'def %s(%s): return _call_(caller, %s)' % (caller.__name__, first_arg, first_arg)
        return fun.make(src, dict(caller=caller, _call_=decorator), undecorated=caller)
    else:
        fun = FunctionMaker(func)
        src = 'def %(name)s(%(signature)s):\n    return _call_(_func_, %(signature)s)'
        return fun.make(src, dict(_func_=func, _call_=caller), undecorated=func)

def calcinds(data, threshold, ignoret=None):
    """Find indexes for data above (or below) given threshold."""
    inds = []
    for i in range(len(data['time'])):
        snr = data['snrs'][i]
        time = data['time'][i]
        if threshold >= 0 and snr > threshold:
            if ignoret:
                incl = [t0 for t0, t1 in ignoret if np.round(time).astype(int) in range(t0, t1)]
                logger.debug('{} {} {} {}'.format(np.round(time).astype(int), t0, t1, incl))
                if not incl:
                    inds.append(i)
            else:
                inds.append(i)
        elif threshold < 0 and snr < threshold:
            if ignoret:
                incl = [t0 for t0, t1 in ignoret if np.round(time).astype(int) in range(t0, t1)]
                logger.debug('{} {} {} {}'.format(np.round(time).astype(int), t0, t1, incl))
                if not incl:
                    inds.append(i)
            else:
                inds.append(i)
    return inds

