def calc_lm(d, im=[], pix=(), minmax='max'):
    """Helper function to calculate location of image pixel in (l,m) coords.
    Assumes peak pixel, but input can be provided in pixel units.
    minmax defines whether to look for image maximum or minimum."""
    if len(pix) == 0:
        if minmax == 'max':
            peakl, peakm = n.where(im == im.max())
        elif minmax == 'min':
            peakl, peakm = n.where(im == im.min())
        peakl = peakl[0]
        peakm = peakm[0]
    elif len(pix) == 2:
        peakl, peakm = pix
    if len(im):
        npixx, npixy = im.shape
    else:
        npixx = d['npixx']
        npixy = d['npixy']
    l1 = (npixx / 2.0 - peakl) / (npixx * d['uvres'])
    m1 = (npixy / 2.0 - peakm) / (npixy * d['uvres'])
    return (l1, m1)

def sample_image(d, data, u, v, w, i=-1, verbose=0, imager='xy', wres=100):
    """Samples one integration and returns image
    i is integration to image. Default is mid int."""
    if i == -1:
        i = len(data) / 2
    if imager == 'xy':
        image = rtlib.imgonefullxy(n.outer(u, d['freq'] / d['freq_orig'][0]), n.outer(v, d['freq'] / d['freq_orig'][0]), data[i], d['npixx'], d['npixy'], d['uvres'], verbose=verbose)
    elif imager == 'w':
        npix = max(d['npixx'], d['npixy'])
        bls, uvkers = rtlib.genuvkernels(w, wres, npix, d['uvres'], ksize=21, oversample=1)
        image = rtlib.imgonefullw(n.outer(u, d['freq'] / d['freq_orig'][0]), n.outer(v, d['freq'] / d['freq_orig'][0]), data[i], npix, d['uvres'], bls, uvkers, verbose=verbose)
    return image

def get_logger(process_name, append_to_console=None, redirect_stdstream=None):
    """method returns initiated logger"""
    if append_to_console is None:
        append_to_console = settings.settings['under_test']
    if redirect_stdstream is None:
        redirect_stdstream = not settings.settings['under_test']
    if process_name not in logger_pool:
        file_name = get_log_filename(process_name)
        log_tag = get_log_tag(process_name)
        logger_pool[process_name] = Logger(file_name, log_tag, append_to_console=append_to_console, redirect_stdstream=redirect_stdstream)
    return logger_pool[process_name].get_logger()

def get_log_tag(process_name):
    """method returns tag that all messages will be preceded with"""
    process_obj = context.process_context[process_name]
    if isinstance(process_obj, FreerunProcessEntry):
        return str(process_obj.token)
    elif isinstance(process_obj, ManagedProcessEntry):
        return str(process_obj.token) + str(process_obj.time_qualifier)
    elif isinstance(process_obj, DaemonProcessEntry):
        return str(process_obj.token)
    else:
        raise ValueError('Unknown process type: {0}'.format(process_obj.__class__.__name__))

def _fix(interval):
    """Helper function for ``GenomeIntervalTree.from_bed and ``.from_table``.

    Data tables may contain intervals with begin >= end. Such intervals lead to infinite recursions and
    other unpleasant behaviour, so something has to be done about them. We 'fix' them by simply setting end = begin+1."""
    if interval.begin >= interval.end:
        warnings.warn('Interval with reversed coordinates (begin >= end) detected when reading data. Interval was automatically fixed to point interval [begin, begin+1).')
        return Interval(interval.begin, interval.begin + 1, interval.data)
    else:
        return interval

def validate_key(func):
    """Decorator to validate a key for zookeeper."""
    @wraps(func)
    def wrapper(self, key, *args, **kwargs):
        if posixpath.sep in key:
            raise ValueError('Keys cannot contains slashes')
        return func(self, key, *args, **kwargs)
    return wrapper

def error_for(response):
    """Return the appropriate initialized exception class for a response."""
    klass = error_classes.get(response.status)
    if klass is None:
        if 400 <= response.status < 500:
            klass = ClientError
        if 500 <= response.status < 600:
            klass = ServerError
    return klass(response)

