def byteswap(data, word_size=4):
    """Swap the byte-ordering in a packet with N=4 bytes per word
    """
    return reduce(lambda x, y: x + ''.join(reversed(y)), chunks(data, word_size), '')

def encode_datetime(o):
    """Encodes a Python datetime.datetime object as an ECMA-262 compliant
    datetime string."""
    r = o.isoformat()
    if o.microsecond:
        r = r[:23] + r[26:]
    if r.endswith('+00:00'):
        r = r[:-6] + 'Z'
    return r

def encode_time(o):
    """Encodes a Python datetime.time object as an ECMA-262 compliant
    time string."""
    r = o.isoformat()
    if o.microsecond:
        r = r[:12]
    if r.endswith('+00:00'):
        r = r[:-6] + 'Z'
    return r

def is_color_supported():
    """Find out if your terminal environment supports color."""
    if not hasattr(sys.stdout, 'isatty'):
        return False
    if not sys.stdout.isatty() and 'TERMINAL-COLOR' not in os.environ:
        return False
    if sys.platform == 'win32':
        try:
            import colorama
            colorama.init()
            return True
        except ImportError:
            return False
    if 'COLORTERM' in os.environ:
        return True
    term = os.environ.get('TERM', 'dumb').lower()
    return term in ('xterm', 'linux') or 'color' in term

def rgb2ansi(r, g, b):
    """Convert an RGB color to 256 ansi graphics."""
    grayscale = False
    poss = True
    step = 2.5
    while poss:
        if min(r, g, b) < step:
            grayscale = max(r, g, b) < step
            poss = False
        step += 42.5
    if grayscale:
        return 232 + int(float(sum((r, g, b)) / 33.0))
    m = ((r, 36), (g, 6), (b, 1))
    return 16 + sum((int(6 * float(val) / 256) * mod for val, mod in m))

def hex2ansi(code):
    """Convert hex code to ansi."""
    if code.startswith('#'):
        code = code[1:]
    if len(code) == 3:
        return rgb2ansi(*map(lambda o: int(o * 2, 16), code))
    if len(code) != 6:
        raise ValueError('invalid color code')
    rgb = (code[:2], code[2:4], code[4:])
    return rgb2ansi(*map(lambda o: int(o, 16), rgb))

