def prompt(name, default=None):
    """Grab user input from command line.

    :param name: prompt text
    :param default: default value if no input provided."""
    prompt = name + (default and ' [%s]' % default or '')
    prompt += name.endswith('?') and ' ' or ': '
    while True:
        try:
            rv = raw_input(prompt)
        except NameError:
            rv = input(prompt)
        if rv:
            return rv
        if default is not None:
            return default

def password(name, default=None):
    """Grabs hidden (password) input from command line.

    :param name: prompt text
    :param default: default value if no input provided."""
    prompt = name + (default and ' [%s]' % default or '')
    prompt += name.endswith('?') and ' ' or ': '
    while True:
        rv = getpass.getpass(prompt)
        if rv:
            return rv
        if default is not None:
            return default

def choose(name, choices, default=None, resolve=None, no_choice=('none',)):
    '''Grabs user input from command line from set of provided choices.

    :param name: prompt text
    :param choices: list or tuple of available choices. Choices may be
                    single strings or (key, value) tuples.
    :param default: default value if no input provided.
    :param no_choice: acceptable list of strings for "null choice"'''
    if not resolve:
        resolve = lambda o: o.lower()
    _choices = []
    options = []
    for choice in choices:
        if isinstance(choice, string_type):
            options.append(choice)
        else:
            options.append('%s [%s]' % (choice[1], choice[0]))
            choice = choice[0]
        _choices.append(choice)
    while True:
        rv = prompt(name + '? - (%s)' % ', '.join(options), default)
        if not rv:
            return default
        rv = resolve(rv)
        if rv in no_choice:
            return None
        if rv in _choices:
            return rv

def command(*args, **kwargs):
    """Decorator to define a command.

    The arguments to this decorator are those of the
    `ArgumentParser <https://docs.python.org/3/library/argparse.html#argumentparser-objects>`_
    object constructor."""
    def decorator(f):
        if 'description' not in kwargs:
            kwargs['description'] = f.__doc__
        if 'parents' in kwargs:
            if not hasattr(f, '_argnames'):
                f._argnames = []
            for p in kwargs['parents']:
                f._argnames += p._argnames if hasattr(p, '_argnames') else []
            kwargs['parents'] = [p.parser for p in kwargs['parents']]
        f.parser = argparse.ArgumentParser(*args, **kwargs)
        f.climax = True
        for arg in getattr(f, '_arguments', []):
            f.parser.add_argument(*arg[0], **arg[1])
        @wraps(f)
        def wrapper(args=None):
            kwargs = f.parser.parse_args(args)
            return f(**vars(kwargs))
        wrapper.func = f
        return wrapper
    return decorator

def _subcommand(group, *args, **kwargs):
    """Decorator to define a subcommand.

    This decorator is used for the group's @command decorator."""
    def decorator(f):
        if 'help' not in kwargs:
            kwargs['help'] = f.__doc__
        _parser_class = group._subparsers._parser_class
        if 'parser' in kwargs:
            group._subparsers._parser_class = _CopiedArgumentParser
        if 'parents' in kwargs:
            if not hasattr(f, '_argnames'):
                f._argnames = []
            for p in kwargs['parents']:
                f._argnames += p._argnames if hasattr(p, '_argnames') else []
            kwargs['parents'] = [p.parser for p in kwargs['parents']]
        if args == ():
            f.parser = group._subparsers.add_parser(f.__name__, **kwargs)
        else:
            f.parser = group._subparsers.add_parser(*args, **kwargs)
        f.parser.set_defaults(**{'_func_' + group.__name__: f})
        f.climax = 'parser' not in kwargs
        group._subparsers._parser_class = _parser_class
        for arg in getattr(f, '_arguments', []):
            f.parser.add_argument(*arg[0], **arg[1])
        return f
    return decorator

def _subgroup(group, *args, **kwargs):
    """Decorator to define a subgroup.

    This decorator is used for the group's @group decorator."""
    def decorator(f):
        f.required = kwargs.pop('required', True)
        if 'parents' in kwargs:
            if not hasattr(f, '_argnames'):
                f._argnames = []
            for p in kwargs['parents']:
                f._argnames += p._argnames if hasattr(p, '_argnames') else []
            kwargs['parents'] = [p.parser for p in kwargs['parents']]
        if 'help' not in kwargs:
            kwargs['help'] = f.__doc__
        if args == ():
            f.parser = group._subparsers.add_parser(f.__name__, **kwargs)
        else:
            f.parser = group._subparsers.add_parser(*args, **kwargs)
        f.parser.set_defaults(**{'_func_' + group.__name__: f})
        f.climax = True
        for arg in getattr(f, '_arguments', []):
            f.parser.add_argument(*arg[0], **arg[1])
        f._subparsers = f.parser.add_subparsers()
        f.command = partial(_subcommand, f)
        f.group = partial(_subgroup, f)
        return f
    return decorator

def _get_dest(*args, **kwargs):
    """Duplicate argument names processing logic from argparse.

    argparse stores the variable in the namespace using the provided dest name,
    the first long option string, or the first short option string"""
    prefix_chars = kwargs.get('prefix_chars', '-')
    option_strings = []
    long_option_strings = []
    for option_string in args:
        option_strings.append(option_string)
        if option_string[0] in prefix_chars:
            if len(option_string) > 1:
                if option_string[1] in prefix_chars:
                    long_option_strings.append(option_string)
    dest = kwargs.get('dest', None)
    if dest is None:
        if long_option_strings:
            dest_option_string = long_option_strings[0]
        else:
            dest_option_string = option_strings[0]
        dest = dest_option_string.lstrip(prefix_chars)
        if not dest:
            msg = _('dest= is required for options like %r')
            raise ValueError(msg % option_string)
        dest = dest.replace('-', '_')
    return dest

def run_once(func):
    """Decorator for making sure a method can only be executed once"""
    def wrapper(*args, **kwargs):
        if not wrapper.has_run:
            wrapper.has_run = True
            return func(*args, **kwargs)
    wrapper.has_run = False
    return wrapper

def gfm(text):
    """Processes Markdown according to GitHub Flavored Markdown spec."""
    extractions = {}
    def extract_pre_block(matchobj):
        match = matchobj.group(0)
        hashed_match = hashlib.md5(match.encode('utf-8')).hexdigest()
        extractions[hashed_match] = match
        result = '{gfm-extraction-%s}' % hashed_match
        return result
    def escape_underscore(matchobj):
        match = matchobj.group(0)
        if match.count('_') > 1:
            return re.sub('_', '\\_', match)
        else:
            return match
    def newlines_to_brs(matchobj):
        match = matchobj.group(0)
        if re.search('\n{2}', match):
            return match
        else:
            match = match.strip()
            return match + '  \n'
    def insert_pre_block(matchobj):
        string = '\n\n' + extractions[matchobj.group(1)]
        return string
    text = re.sub('(?s)<pre>.*?<\\/pre>', extract_pre_block, text)
    text = re.sub('(^(?! {4}|\t)\\w+_\\w+_\\w[\\w_]*)', escape_underscore, text)
    text = re.sub('(?m)^[\\w\\<][^\n]*\n+', newlines_to_brs, text)
    text = re.sub('\\{gfm-extraction-([0-9a-f]{32})\\}', insert_pre_block, text)
    return text

def merge_xml(first_doc, second_doc):
    """Merges two XML documents.

    Args:
        first_doc (str): First XML document.  `second_doc` is merged into this
            document.
        second_doc (str): Second XML document.  It is merged into the first.

    Returns:
        XML Document: The merged document.

    Raises:
        None

    Example:
        >>> import pynos.utilities
        >>> import lxml
        >>> import xml
        >>> x = xml.etree.ElementTree.fromstring('<config />')
        >>> y = lxml.etree.fromstring('<config><hello /></config>')
        >>> x = pynos.utilities.merge_xml(x, y)"""
    if isinstance(first_doc, lxml.etree._Element):
        first_doc = ET.fromstring(lxml.etree.tostring(first_doc))
    if isinstance(second_doc, lxml.etree._Element):
        second_doc = ET.fromstring(lxml.etree.tostring(second_doc))
    mapping = {element.tag: element for element in first_doc}
    for element in second_doc:
        if not len(element):
            try:
                mapping[element.tag].text = element.text
            except KeyError:
                mapping[element.tag] = element
                first_doc.append(element)
        else:
            try:
                merge_xml(mapping[element.tag], element)
            except KeyError:
                mapping[element.tag] = element
                first_doc.append(element)
    return lxml.etree.fromstring(ET.tostring(first_doc))

def pare(text, size, etc='...'):
    """Pare text to have maximum size and add etc to the end if it's
    changed"""
    size = int(size)
    text = text.strip()
    if len(text) > size:
        to_be_stripped = not whitespace_re.findall(text[size - 1:size + 2])
        text = text[:size]
        if to_be_stripped:
            half = size // 2
            last = None
            for mo in whitespace_re.finditer(text[half:]):
                last = mo
            if last is not None:
                text = text[:half + last.start() + 1]
        return text.rstrip() + etc
    else:
        return text

def deduplicate(s, ch):
    """From http://stackoverflow.com/q/42216559/610569

        s = 'this is   an   irritating string with  random spacing  .'
        deduplicate(s)
        'this is an irritating string with random spacing .'"""
    return ch.join([substring for substring in s.strip().split(ch) if substring])

def remove_text_inside_brackets(s, brackets='()[]'):
    """From http://stackoverflow.com/a/14603508/610569"""
    count = [0] * (len(brackets) // 2)
    saved_chars = []
    for character in s:
        for i, b in enumerate(brackets):
            if character == b:
                kind, is_close = divmod(i, 2)
                count[kind] += (-1) ** is_close
                if count[kind] < 0:
                    count[kind] = 0
                break
        else:
            if not any(count):
                saved_chars.append(character)
    return ''.join(saved_chars)

def color_print(s, color=None, highlight=None, end='\n', file=sys.stdout, **kwargs):
    """From http://stackoverflow.com/a/287944/610569
    See also https://gist.github.com/Sheljohn/68ca3be74139f66dbc6127784f638920"""
    if color in palette and color != 'default':
        s = palette[color] + s
    if highlight and highlight in highlighter:
        s = highlighter[highlight] + s
    for name, value in kwargs.items():
        if name in formatter and value == True:
            s = formatter[name] + s
    print(s + palette['default'], end=end, file=file)

def _set_value(instance_to_path_map, path_to_instance_map, prop_tree, config_instance):
    """Finds appropriate term in the prop_tree and sets its value from config_instance.

    Args:
        configs_map (dict): key is id of the config, value is Config instance (AKA cache of the configs)
        prop_tree (PropertyDictTree): poperty tree to populate.
        config_instance (Config):"""
    path = instance_to_path_map[config_instance]
    group = prop_tree
    for elem in path[:-1]:
        group = getattr(group, elem)
    assert group._key == config_instance.parent.key
    setattr(group, config_instance.key, config_instance.value)
    term = getattr(group, config_instance.key)
    try:
        if hasattr(term, '_term'):
            term._term._config = config_instance
            return
    except KeyError:
        pass
    try:
        if hasattr(term, '_config'):
            term._config = config_instance
            return
    except KeyError:
        pass
    else:
        pass

def get_or_create(session, model, **kwargs):
    """Get or create sqlalchemy instance.

    Args:
        session (Sqlalchemy session):
        model (sqlalchemy model):
        kwargs (dict): kwargs to lookup or create instance.

    Returns:
        Tuple: first element is found or created instance, second is boolean - True if instance created,
            False if instance found."""
    instance = session.query(model).filter_by(**kwargs).first()
    if instance:
        return (instance, False)
    else:
        instance = model(**kwargs)
        if 'dataset' in kwargs:
            instance.update_sequence_id(session, kwargs['dataset'])
        session.add(instance)
        session.commit()
        return (instance, True)

def quoteattrs(data):
    """Takes dict of attributes and returns their HTML representation"""
    items = []
    for key, value in data.items():
        items.append('{}={}'.format(key, quoteattr(value)))
    return ' '.join(items)

def evaluate_stop_condition(errdata, stop_condition):
    """Call the user-defined function: stop_condition(errdata)
    If the function returns -1, do nothing.  Otherwise, sys.exit."""
    if stop_condition:
        return_code = stop_condition(list(errdata))
        if return_code != -1:
            log.info('Stop condition triggered!  Relay is terminating.', extra=dict(return_code=return_code))
            sys.exit(return_code)

def find_files(dir_path, extension='*'):
    """From https://stackoverflow.com/a/2186565/610569"""
    if sys.version_info.major == 3 and sys.version_info.minor >= 5:
        pattern = '/'.join([dir_path, '**', extension])
        for filename in glob.iglob(pattern, recursive=True):
            yield filename
    else:
        for root, dirnames, filenames in os.walk(dir_path):
            for filename in fnmatch.filter(filenames, extension):
                yield os.path.join(root, filename)

def getTicker(pair, connection=None, info=None):
    """Retrieve the ticker for the given pair.  Returns a Ticker instance."""
    if info is not None:
        info.validate_pair(pair)
    if connection is None:
        connection = common.BTCEConnection()
    response = connection.makeJSONRequest('/api/3/ticker/%s' % pair)
    if type(response) is not dict:
        raise TypeError('The response is a %r, not a dict.' % type(response))
    elif u'error' in response:
        print('There is a error "%s" while obtaining ticker %s' % (response['error'], pair))
        ticker = None
    else:
        ticker = Ticker(**response[pair])
    return ticker

def getDepth(pair, connection=None, info=None):
    """Retrieve the depth for the given pair.  Returns a tuple (asks, bids);
    each of these is a list of (price, volume) tuples."""
    if info is not None:
        info.validate_pair(pair)
    if connection is None:
        connection = common.BTCEConnection()
    response = connection.makeJSONRequest('/api/3/depth/%s' % pair)
    if type(response) is not dict:
        raise TypeError('The response is not a dict.')
    depth = response.get(pair)
    if type(depth) is not dict:
        raise TypeError('The pair depth is not a dict.')
    asks = depth.get(u'asks')
    if type(asks) is not list:
        raise TypeError('The response does not contain an asks list.')
    bids = depth.get(u'bids')
    if type(bids) is not list:
        raise TypeError('The response does not contain a bids list.')
    return (asks, bids)

def getTradeHistory(pair, connection=None, info=None, count=None):
    """Retrieve the trade history for the given pair.  Returns a list of
    Trade instances.  If count is not None, it should be an integer, and
    specifies the number of items from the trade history that will be
    processed and returned."""
    if info is not None:
        info.validate_pair(pair)
    if connection is None:
        connection = common.BTCEConnection()
    response = connection.makeJSONRequest('/api/3/trades/%s' % pair)
    if type(response) is not dict:
        raise TypeError('The response is not a dict.')
    history = response.get(pair)
    if type(history) is not list:
        raise TypeError('The response is a %r, not a list.' % type(history))
    result = []
    if count is not None:
        history = history[:count]
    for h in history:
        h['pair'] = pair
        t = Trade(**h)
        result.append(t)
    return result

def root_sync(args, l, config):
    """Sync with the remote. For more options, use library sync
    """
    from requests.exceptions import ConnectionError
    all_remote_names = [r.short_name for r in l.remotes]
    if args.all:
        remotes = all_remote_names
    else:
        remotes = args.refs
    prt('Sync with {} remotes or bundles '.format(len(remotes)))
    if not remotes:
        return
    for ref in remotes:
        l.commit()
        try:
            if ref in all_remote_names:
                l.sync_remote(l.remote(ref))
            else:
                l.checkin_remote_bundle(ref)
        except NotFoundError as e:
            warn(e)
            continue
        except ConnectionError as e:
            warn(e)
            continue

def _CaptureException(f, *args, **kwargs):
    """Decorator implementation for capturing exceptions."""
    from ambry.dbexceptions import LoggedException
    b = args[0]
    try:
        return f(*args, **kwargs)
    except Exception as e:
        raise
        try:
            b.set_error_state()
            b.commit()
        except Exception as e2:
            b.log('Failed to set bundle error state: {}'.format(e))
            raise e
        if b.capture_exceptions:
            b.logged_exception(e)
            raise LoggedException(e, b)
        else:
            b.exception(e)
            raise

def exclude(prop):
    """Don't replicate property that is normally replicated: ordering column,
    many-to-one relation that is marked for replication from other side."""
    if isinstance(prop, QueryableAttribute):
        prop = prop.property
    assert isinstance(prop, (Column, ColumnProperty, RelationshipProperty))
    _excluded.add(prop)
    if isinstance(prop, RelationshipProperty):
        for local in prop.local_columns:
            _excluded.add(local)

def reflect(source, model, cache=None):
    """Finds an object of class `model` with the same identifier as the
    `source` object"""
    if source is None:
        return None
    if cache and source in cache:
        return cache[source]
    db = object_session(source)
    ident = identity_key(instance=source)[1]
    assert ident is not None
    return db.query(model).get(ident)

def replicate_no_merge(source, model, cache=None):
    """Replicates the `source` object to `model` class and returns its
    reflection."""
    if source is None:
        return None
    if cache is None:
        cache = {}
    elif source in cache:
        return cache[source]
    db = object_session(source)
    cls, ident = identity_key(instance=source)
    target = db.query(model).get(ident)
    if target is None:
        target = model()
    cache[source] = target
    try:
        replicate_attributes(source, target, cache=cache)
    except _PrimaryKeyIsNull:
        return None
    else:
        return target

