def copy_file_or_flo(input_, output, buffer_size=64 * 1024, cb=None):
    """Copy a file name or file-like-object to another
    file name or file-like object"""
    assert bool(input_)
    assert bool(output)
    input_opened = False
    output_opened = False
    try:
        if isinstance(input_, string_types):
            if not os.path.isdir(os.path.dirname(input_)):
                os.makedirs(os.path.dirname(input_))
            input_ = open(input_, 'r')
            input_opened = True
        if isinstance(output, string_types):
            if not os.path.isdir(os.path.dirname(output)):
                os.makedirs(os.path.dirname(output))
            output = open(output, 'wb')
            output_opened = True
        def copyfileobj(fsrc, fdst, length=buffer_size):
            cumulative = 0
            while True:
                buf = fsrc.read(length)
                if not buf:
                    break
                fdst.write(buf)
                if cb:
                    cumulative += len(buf)
                    cb(len(buf), cumulative)
        copyfileobj(input_, output)
    finally:
        if input_opened:
            input_.close()
        if output_opened:
            output.close()

def trace(fn):
    """Prints parameteters and return values of the each call of the wrapped function.

    Usage:
        decorate appropriate function or method:
            @trace
            def myf():
                ..."""
    def wrapped(*args, **kwargs):
        msg = []
        msg.append('Enter {}('.format(fn.__name__))
        if args:
            msg.append(', '.join([str(x) for x in args]))
        if kwargs:
            kwargs_str = ', '.join(['{}={}'.format(k, v) for k, v in list(kwargs.items())])
            if args:
                msg.append(', ')
            msg.append(kwargs_str)
        msg.append(')')
        print(''.join(msg))
        ret = fn(*args, **kwargs)
        print('Return {}'.format(ret))
        return ret
    return wrapped

def patch_file_open():
    """A Monkey patch to log opening and closing of files, which is useful for
    debugging file descriptor exhaustion."""
    openfiles = set()
    oldfile = builtins.file
    class newfile(oldfile):
        def __init__(self, *args, **kwargs):
            self.x = args[0]
            all_fds = count_open_fds()
            print('### {} OPENING {} ( {} total )###'.format(len(openfiles), str(self.x), all_fds))
            oldfile.__init__(self, *args, **kwargs)
            openfiles.add(self)
        def close(self):
            print('### {} CLOSING {} ###'.format(len(openfiles), str(self.x)))
            oldfile.close(self)
            openfiles.remove(self)
    def newopen(*args, **kwargs):
        return newfile(*args, **kwargs)
    builtins.file = newfile
    builtins.open = newopen

def login(client, credentials):
    """Authenticate using the given L{AMP} instance.  The protocol must be
    connected to a server with responders for L{PasswordLogin} and
    L{PasswordChallengeResponse}.

    @param client: A connected L{AMP} instance which will be used to issue
        authentication commands.

    @param credentials: An object providing L{IUsernamePassword} which will
        be used to authenticate this connection to the server.

    @return: A L{Deferred} which fires when authentication has succeeded or
        which fails with L{UnauthorizedLogin} if the server rejects the
        authentication attempt."""
    if not IUsernamePassword.providedBy(credentials):
        raise UnhandledCredentials()
    d = client.callRemote(PasswordLogin, username=credentials.username)
    def cbChallenge(response):
        args = PasswordChallengeResponse.determineFrom(response['challenge'], credentials.password)
        d = client.callRemote(PasswordChallengeResponse, **args)
        return d.addCallback(lambda ignored: client)
    d.addCallback(cbChallenge)
    return d

def _timedeltaToSignHrMin(offset):
    """Return a (sign, hour, minute) triple for the offset described by timedelta.

    sign is a string, either "+" or "-". In the case of 0 offset, sign is "+"."""
    minutes = round((offset.days * 3600000000 * 24 + offset.seconds * 1000000 + offset.microseconds) / 60000000.0)
    if minutes < 0:
        sign = '-'
        minutes = -minutes
    else:
        sign = '+'
    return (sign, minutes // 60, minutes % 60)

def expiring_memoize(obj):
    """Like memoize, but forgets after 10 seconds."""
    cache = obj.cache = {}
    last_access = obj.last_access = defaultdict(int)
    @wraps(obj)
    def memoizer(*args, **kwargs):
        key = str(args) + str(kwargs)
        if last_access[key] and last_access[key] + 10 < time():
            if key in cache:
                del cache[key]
        last_access[key] = time()
        if key not in cache:
            cache[key] = obj(*args, **kwargs)
        return cache[key]
    return memoizer

