def pretty_time(s, granularity=3):
    """Pretty print time in seconds. COnverts the input time in seconds into a string with
    interval names, such as days, hours and minutes

    From:
    http://stackoverflow.com/a/24542445/1144479"""
    intervals = (('weeks', 604800), ('days', 86400), ('hours', 3600), ('minutes', 60), ('seconds', 1))
    def display_time(seconds, granularity=granularity):
        result = []
        for name, count in intervals:
            value = seconds // count
            if value:
                seconds -= value * count
                if value == 1:
                    name = name.rstrip('s')
                result.append('{} {}'.format(int(value), name))
        return ', '.join(result[:granularity])
    return display_time(s, granularity)

def delete_module(modname, paranoid=None):
    """Delete a module.http://stackoverflow.com/a/1668289
    :param modname:
    :param paranoid:
    :return:"""
    from sys import modules
    try:
        thismod = modules[modname]
    except KeyError:
        raise ValueError(modname)
    these_symbols = dir(thismod)
    if paranoid:
        try:
            paranoid[:]
        except:
            raise ValueError('must supply a finite list for paranoid')
        else:
            these_symbols = paranoid[:]
    del modules[modname]
    for mod in modules.values():
        try:
            delattr(mod, modname)
        except AttributeError:
            pass
        if paranoid:
            for symbol in these_symbols:
                if symbol[:2] == '__':
                    continue
                try:
                    delattr(mod, symbol)
                except AttributeError:
                    pass

def repercent_broken_unicode(path):
    """As per section 3.2 of RFC 3987, step three of converting a URI into an IRI,
    we need to re-percent-encode any octet produced that is not part of a
    strictly legal UTF-8 octet sequence."""
    while True:
        try:
            return path.decode('utf-8')
        except UnicodeDecodeError as e:
            repercent = quote(path[e.start:e.end], safe=b"/#%[]=:;$&()+,!?*@'~")
            path = path[:e.start] + repercent.encode('ascii') + path[e.end:]

