def failUnlessWarns(self, category, message, filename, f, *args, **kwargs):
    """Fail if the given function doesn't generate the specified warning when
    called. It calls the function, checks the warning, and forwards the
    result of the function if everything is fine.

    @param category: the category of the warning to check.
    @param message: the output message of the warning to check.
    @param filename: the filename where the warning should come from.
    @param f: the function which is supposed to generate the warning.
    @type f: any callable.
    @param args: the arguments to C{f}.
    @param kwargs: the keywords arguments to C{f}.

    @return: the result of the original function C{f}."""
    warningsShown = []
    def warnExplicit(*args):
        warningsShown.append(args)
    origExplicit = warnings.warn_explicit
    try:
        warnings.warn_explicit = warnExplicit
        result = f(*args, **kwargs)
    finally:
        warnings.warn_explicit = origExplicit
    if not warningsShown:
        self.fail('No warnings emitted')
    first = warningsShown[0]
    for other in warningsShown[1:]:
        if other[:2] != first[:2]:
            self.fail("Can't handle different warnings")
    gotMessage, gotCategory, gotFilename, lineno = first[:4]
    self.assertEqual(gotMessage, message)
    self.assertIdentical(gotCategory, category)
    self.failUnless(filename.startswith(gotFilename), 'Warning in %r, expected %r' % (gotFilename, filename))
    return result

def create_win32tz_map(windows_zones_xml):
    """Creates a map between Windows and Olson timezone names.

    Args:
      windows_zones_xml: The CLDR XML mapping.

    Yields:
      (win32_name, olson_name, comment)"""
    coming_comment = None
    win32_name = None
    territory = None
    parser = genshi.input.XMLParser(StringIO(windows_zones_xml))
    map_zones = {}
    zone_comments = {}
    for kind, data, _ in parser:
        if kind == genshi.core.START and str(data[0]) == 'mapZone':
            attrs = data[1]
            win32_name, territory, olson_name = (attrs.get('other'), attrs.get('territory'), attrs.get('type').split(' ')[0])
            map_zones[win32_name, territory] = olson_name
        elif kind == genshi.core.END and str(data) == 'mapZone' and win32_name:
            if coming_comment:
                zone_comments[win32_name, territory] = coming_comment
                coming_comment = None
            win32_name = None
        elif kind == genshi.core.COMMENT:
            coming_comment = data.strip()
        elif kind in (genshi.core.START, genshi.core.END, genshi.core.COMMENT):
            coming_comment = None
    for win32_name, territory in sorted(map_zones):
        yield (win32_name, territory, map_zones[win32_name, territory], zone_comments.get((win32_name, territory), None))

