def _contextualize(contextFactory, contextReceiver):
    """Invoke a callable with an argument derived from the current execution
    context (L{twisted.python.context}), or automatically created if none is
    yet present in the current context.

    This function, with a better name and documentation, should probably be
    somewhere in L{twisted.python.context}.  Calling context.get() and
    context.call() individually is perilous because you always have to handle
    the case where the value you're looking for isn't present; this idiom
    forces you to supply some behavior for that case.

    @param contextFactory: An object which is both a 0-arg callable and
    hashable; used to look up the value in the context, set the value in the
    context, and create the value (by being called).

    @param contextReceiver: A function that receives the value created or
    identified by contextFactory.  It is a 1-arg callable object, called with
    the result of calling the contextFactory, or retrieving the contextFactory
    from the context."""
    value = context.get(contextFactory, _NOT_SPECIFIED)
    if value is not _NOT_SPECIFIED:
        return contextReceiver(value)
    else:
        return context.call({contextFactory: contextFactory()}, _contextualize, contextFactory, contextReceiver)

def get_stored_version(connection):
    """Returns database version.

    Args:
        connection (sqlalchemy connection):

    Raises: Assuming user_version pragma (sqlite case) and user_version table (postgresql case)
        exist because they created with the database creation.

    Returns:
        int: version of the database."""
    if connection.engine.name == 'sqlite':
        version = connection.execute('PRAGMA user_version').fetchone()[0]
        if version == 0:
            raise VersionIsNotStored
        return version
    elif connection.engine.name == 'postgresql':
        try:
            r = connection.execute('SELECT version FROM {}.user_version;'.format(POSTGRES_SCHEMA_NAME)).fetchone()
            if not r:
                raise VersionIsNotStored
            version = r[0]
        except ProgrammingError:
            raise VersionIsNotStored
        return version
    else:
        raise DatabaseError('Do not know how to get version from {} engine.'.format(connection.engine.name))

def _validate_version(connection, dsn):
    """Performs on-the-fly schema updates based on the models version.

    Raises:
        DatabaseError: if user uses old sqlite database."""
    try:
        version = get_stored_version(connection)
    except VersionIsNotStored:
        logger.debug('Version not stored in the db: assuming new database creation.')
        version = SCHEMA_VERSION
        _update_version(connection, version)
    assert isinstance(version, int)
    if version > 10 and version < 100:
        raise DatabaseError('You are trying to open an old SQLite database.')
    if _migration_required(connection):
        migrate(connection, dsn)

def _update_version(connection, version):
    """Updates version in the db to the given version.

    Args:
        connection (sqlalchemy connection): sqlalchemy session where to update version.
        version (int): version of the migration."""
    if connection.engine.name == 'sqlite':
        connection.execute('PRAGMA user_version = {}'.format(version))
    elif connection.engine.name == 'postgresql':
        connection.execute(DDL('CREATE SCHEMA IF NOT EXISTS {};'.format(POSTGRES_SCHEMA_NAME)))
        connection.execute(DDL('CREATE SCHEMA IF NOT EXISTS {};'.format(POSTGRES_PARTITION_SCHEMA_NAME)))
        connection.execute('CREATE TABLE IF NOT EXISTS {}.user_version(version INTEGER NOT NULL);'.format(POSTGRES_SCHEMA_NAME))
        if connection.execute('SELECT * FROM {}.user_version;'.format(POSTGRES_SCHEMA_NAME)).fetchone():
            connection.execute('UPDATE {}.user_version SET version = {};'.format(POSTGRES_SCHEMA_NAME, version))
        else:
            connection.execute('INSERT INTO {}.user_version (version) VALUES ({})'.format(POSTGRES_SCHEMA_NAME, version))
    else:
        raise DatabaseMissingError('Do not know how to migrate {} engine.'.format(connection.engine.driver))

def _deferGenerator(g, deferred=None):
    """See L{waitForDeferred}."""
    result = None
    while 1:
        if deferred is None:
            deferred = defer.Deferred()
        try:
            result = g.next()
        except StopIteration:
            deferred.callback(result)
            return deferred
        except:
            deferred.errback()
            return deferred
        if isinstance(result, defer.Deferred):
            return defer.fail(TypeError('Yield waitForDeferred(d), not d!'))
        if isinstance(result, defer.waitForDeferred):
            waiting = [True, None]
            def gotResult(r, waiting=waiting, result=result):
                result.result = r
                if waiting[0]:
                    waiting[0] = False
                    waiting[1] = r
                else:
                    _deferGenerator(g, deferred)
            result.d.addBoth(gotResult)
            if waiting[0]:
                waiting[0] = False
                return deferred
            result = None

def return_locals(func):
    """Modifies decorated function to return its locals"""
    @functools.wraps(func)
    def wrap(*args, **kwargs):
        frames = []
        def tracer(frame, event, arg):
            frames.append(frame)
            sys.settrace(old_tracer)
            if old_tracer is not None:
                return old_tracer(frame, event, arg)
        old_tracer = sys.gettrace()
        sys.settrace(tracer)
        try:
            func(*args, **kwargs)
        finally:
            sys.settrace(old_tracer)
        assert len(frames) == 1
        argspec = inspect.getargspec(func)
        argnames = list(argspec.args)
        if argspec.varargs is not None:
            argnames.append(argspec.varargs)
        if argspec.keywords is not None:
            argnames.append(argspec.keywords)
        return {name: value for name, value in frames.pop(0).f_locals.items() if name not in argnames}
    return wrap

def multidb_binds(databases, package=None, engine_params=None):
    """Creates dictionary to be passed as `binds` parameter to
    `sqlalchemy.orm.sessionmaker()` from dictionary mapping models module name
    to connection URI that should be used for these models. Models module must
    have `metadata` attribute. `package` when set must be a package or package
    name for all models modules."""
    engine_params = engine_params or {}
    if not (package is None or isinstance(package, six.string_types)):
        package = getattr(package, '__package__', None) or package.__name__
    binds = {}
    for ref, uri in databases.items():
        md_ref = '.'.join(filter(None, [package, ref]))
        md_module = import_module(md_ref)
        try:
            metadata = md_module.metadata
        except AttributeError:
            raise ImportError('Cannot import name metadata from module {}'.format(md_ref))
        engine = create_engine(uri, **engine_params)
        engine.logger = logging.getLogger('sqlalchemy.engine.[%s]' % ref)
        for table in metadata.sorted_tables:
            binds[table] = engine
    return binds

def terminate(pid, sig, timeout):
    """Terminates process with PID `pid` and returns True if process finished
    during `timeout`. Current user must have permission to access process
    information."""
    os.kill(pid, sig)
    start = time.time()
    while True:
        try:
            _, status = os.waitpid(pid, os.WNOHANG)
        except OSError as exc:
            if exc.errno != errno.ECHILD:
                raise
        else:
            if status:
                return True
        if not is_running(pid):
            return True
        if time.time() - start >= timeout:
            return False
        time.sleep(0.1)

def doublefork(pidfile, logfile, cwd, umask):
    """Daemonize current process.
    After first fork we return to the shell and removing our self from
    controling terminal via `setsid`.
    After second fork we are not session leader any more and cant get
    controlling terminal when opening files."""
    try:
        if os.fork():
            os._exit(os.EX_OK)
    except OSError as e:
        sys.exit('fork #1 failed: ({}) {}'.format(e.errno, e.strerror))
    os.setsid()
    os.chdir(cwd)
    os.umask(umask)
    try:
        if os.fork():
            os._exit(os.EX_OK)
    except OSError as e:
        sys.exit('fork #2 failed: ({}) {}'.format(e.errno, e.strerror))
    if logfile is not None:
        si = open('/dev/null')
        if six.PY2:
            so = open(logfile, 'a+', 0)
        else:
            so = io.open(logfile, 'ab+', 0)
            so = io.TextIOWrapper(so, write_through=True, encoding='utf-8')
        os.dup2(si.fileno(), 0)
        os.dup2(so.fileno(), 1)
        os.dup2(so.fileno(), 2)
        sys.stdin = si
        sys.stdout = sys.stderr = so
    with open(pidfile, 'w') as f:
        f.write(str(os.getpid()))

def transform_generator(fn):
    """A decorator that marks transform pipes that should be called to create the real transform"""
    if six.PY2:
        fn.func_dict['is_transform_generator'] = True
    else:
        fn.__dict__['is_transform_generator'] = True
    return fn

def is_transform_generator(fn):
    """Return true of the function has been marked with @transform_generator"""
    try:
        if six.PY2:
            fn.func_dict['is_transform_generator'] = True
        else:
            return fn.__dict__.get('is_transform_generator', False)
    except AttributeError:
        return False

def nullify(v):
    """Convert empty strings and strings with only spaces to None values."""
    if isinstance(v, six.string_types):
        v = v.strip()
    if v is None or v == '':
        return None
    else:
        return v

def clean_float(v):
    """Remove commas from a float"""
    if v is None or not str(v).strip():
        return None
    return float(str(v).replace(',', ''))

def clean_int(v):
    """Remove commas from a float"""
    if v is None or not str(v).strip():
        return None
    return int(str(v).replace(',', ''))

def parse_int(v, header_d):
    """Parse as an integer, or a subclass of Int."""
    v = nullify(v)
    if v is None:
        return None
    try:
        return int(round(float(v), 0))
    except (TypeError, ValueError) as e:
        raise CastingError(int, header_d, v, 'Failed to cast to integer')

def _parse_text(v, header_d):
    """Parses unicode.

    Note:
        unicode types for py2 and str types for py3."""
    v = nullify(v)
    if v is None:
        return None
    try:
        return six.text_type(v).strip()
    except Exception as e:
        raise CastingError(six.text_type, header_d, v, str(e))

def _parse_binary(v, header_d):
    """Parses binary string.

    Note:
        <str> for py2 and <binary> for py3."""
    v = nullify(v)
    if v is None:
        return None
    if six.PY2:
        try:
            return six.binary_type(v).strip()
        except UnicodeEncodeError:
            return six.text_type(v).strip()
    else:
        try:
            return six.binary_type(v, 'utf-8').strip()
        except UnicodeEncodeError:
            return six.text_type(v).strip()

def parseJuiceHeaders(lines):
    """Create a JuiceBox from a list of header lines.

    @param lines: a list of lines."""
    b = JuiceBox()
    bodylen = 0
    key = None
    for L in lines:
        if L[0] == ' ':
            assert key is not None
            b[key] += '\r\n' + L[1:]
            continue
        parts = L.split(': ', 1)
        if len(parts) != 2:
            raise MalformedJuiceBox('Wrong number of parts: %r' % (L,))
        key, value = parts
        key = normalizeKey(key)
        b[key] = value
    return (int(b.pop(LENGTH, 0)), b)

def check_chain(chain):
    """Verify a merkle chain to see if the Merkle root can be reproduced.
    """
    link = chain[0][0]
    for i in range(1, len(chain) - 1):
        if chain[i][1] == 'R':
            link = hash_function(link + chain[i][0]).digest()
        elif chain[i][1] == 'L':
            link = hash_function(chain[i][0] + link).digest()
        else:
            raise MerkleError('Link %s has no side value: %s' % (str(i), str(codecs.encode(chain[i][0], 'hex_codec'))))
    if link == chain[-1][0]:
        return link
    else:
        raise MerkleError('The Merkle Chain is not valid.')

def check_hex_chain(chain):
    """Verify a merkle chain, with hashes hex encoded, to see if the Merkle root can be reproduced.
    """
    return codecs.encode(check_chain([(codecs.decode(i[0], 'hex_codec'), i[1]) for i in chain]), 'hex_codec')

def rom(addr, dout, CONTENT):
    """CONTENT == tuple of non-sparse values"""
    @always_comb
    def read():
        dout.next = CONTENT[int(addr)]
    return read

def ram_sp_ar(clk, we, addr, di, do):
    """RAM: Single-Port, Asynchronous Read"""
    memL = [Signal(intbv(0)[len(di):]) for _ in range(2 ** len(addr))]
    @always(clk.posedge)
    def write():
        if we:
            memL[int(addr)].next = di
    @always_comb
    def read():
        do.next = memL[int(addr)]
    return (write, read)

def ram_sdp_rf(clk, we, addrw, addrr, di, do):
    """RAM: Simple-Dual-Port, Read-First"""
    memL = [Signal(intbv(0)[len(di):]) for _ in range(2 ** len(addrr))]
    @always(clk.posedge)
    def write():
        if we:
            memL[int(addrw)].next = di
        do.next = memL[int(addrr)]
    return write

def NCBISequenceLinkURL(title, default=None):
    """Given a sequence title, like "gi|42768646|gb|AY516849.1| Homo sapiens",
    return the URL of a link to the info page at NCBI.

    title: the sequence title to produce a link URL for.
    default: the value to return if the title cannot be parsed."""
    try:
        ref = title.split('|')[3].split('.')[0]
    except IndexError:
        return default
    else:
        return 'http://www.ncbi.nlm.nih.gov/nuccore/%s' % (ref,)

def NCBISequenceLink(title, default=None):
    """Given a sequence title, like "gi|42768646|gb|AY516849.1| Homo sapiens",
    return an HTML A tag dispalying a link to the info page at NCBI.

    title: the sequence title to produce an HTML link for.
    default: the value to return if the title cannot be parsed."""
    url = NCBISequenceLinkURL(title)
    if url is None:
        return default
    else:
        return '<a href="%s" target="_blank">%s</a>' % (url, title)

def _sortHTML(titlesAlignments, by, limit=None):
    """Return an C{IPython.display.HTML} object with the alignments sorted by the
    given attribute.

    @param titlesAlignments: A L{dark.titles.TitlesAlignments} instance.
    @param by: A C{str}, one of 'length', 'maxScore', 'medianScore',
        'readCount', or 'title'.
    @param limit: An C{int} limit on the number of results to show.
    @return: An HTML instance with sorted titles and information about
        hit read count, length, and e-values."""
    out = []
    for i, title in enumerate(titlesAlignments.sortTitles(by), start=1):
        if limit is not None and i > limit:
            break
        titleAlignments = titlesAlignments[title]
        link = NCBISequenceLink(title, title)
        out.append('%3d: reads=%d, len=%d, max=%s median=%s<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;%s' % (i, titleAlignments.readCount(), titleAlignments.subjectLength, titleAlignments.bestHsp().score.score, titleAlignments.medianScore(), link))
    return HTML('<pre>' + '<br/>'.join(out) + '</pre>')

def bitScoreToEValue(bitScore, dbSize, dbSequenceCount, queryLength, lengthAdjustment):
    """Convert a bit score to an e-value.

    @param bitScore: The C{float} bit score to convert.
    @param dbSize: The C{int} total size of the database (i.e., the sum of
        the lengths of all sequences in the BLAST database).
    @param dbSequenceCount: The C{int} number of sequences in the database.
    @param queryLength: The C{int} length of the query.
    @param lengthAdjustment: The C{int} length adjustment (BLAST XML output
        calls this the Statistics_hsp-len).
    @return: A C{float} e-value."""
    effectiveDbSize = (dbSize - dbSequenceCount * lengthAdjustment) * (queryLength - lengthAdjustment)
    return effectiveDbSize * 2.0 ** (-1.0 * bitScore)

def eValueToBitScore(eValue, dbSize, dbSequenceCount, queryLength, lengthAdjustment):
    """Convert an e-value to a bit score.

    @param eValue: The C{float} e-value to convert.
    @param dbSize: The C{int} total size of the database (i.e., the sum of
        the lengths of all sequences in the BLAST database).
    @param dbSequenceCount: The C{int} number of sequences in the database.
    @param queryLength: The C{int} length of the query.
    @param lengthAdjustment: The C{int} length adjustment (BLAST XML output
        calls this the Statistics_hsp-len).
    @return: A C{float} bit score."""
    effectiveDbSize = (dbSize - dbSequenceCount * lengthAdjustment) * (queryLength - lengthAdjustment)
    return -1.0 * (log(eValue / effectiveDbSize) / _LOG2)

def countGaps(btopString):
    """Count the query and subject gaps in a BTOP string.

    @param btopString: A C{str} BTOP sequence.
    @raise ValueError: If L{parseBtop} finds an error in the BTOP string
        C{btopString}.
    @return: A 2-tuple of C{int}s, with the (query, subject) gaps counts as
        found in C{btopString}."""
    queryGaps = subjectGaps = 0
    for countOrMismatch in parseBtop(btopString):
        if isinstance(countOrMismatch, tuple):
            queryChar, subjectChar = countOrMismatch
            queryGaps += int(queryChar == '-')
            subjectGaps += int(subjectChar == '-')
    return (queryGaps, subjectGaps)

def findKozakConsensus(read):
    """In a given DNA sequence, search for a Kozak consensus: (gcc)gccRccATGG.
    The upper case bases in that pattern are required, and the lower case
    bases are the ones most frequently found at the given positions. The
    initial 'gcc' sequence (in parentheses) is of uncertain significance
    and is not taken into account here.

    @param read: A C{DNARead} instance to be checked for Kozak consensi.
    @return: A generator that yields C{DNAKozakRead} instances."""
    readLen = len(read)
    if readLen > 9:
        offset = 6
        readSeq = read.sequence
        while offset < readLen - 3:
            triplet = readSeq[offset:offset + 3]
            if triplet == 'ATG':
                if readSeq[offset + 3] == 'G':
                    if readSeq[offset - 3] in 'GA':
                        kozakQualityCount = sum((readSeq[offset - 1] == 'C', readSeq[offset - 2] == 'C', readSeq[offset - 4] == 'C', readSeq[offset - 5] == 'C', readSeq[offset - 6] == 'G'))
                        kozakQualityPercent = kozakQualityCount / 5.0 * 100
                        yield DNAKozakRead(read, offset - 6, offset + 4, kozakQualityPercent)
            offset += 1

def thresholdForIdentity(identity, colors):
    """Get the best identity threshold for a specific identity value.

    @param identity: A C{float} nucleotide identity.
    @param colors: A C{list} of (threshold, color) tuples, where threshold is a
        C{float} and color is a C{str} to be used as a cell background. This
        is as returned by C{parseColors}.
    @return: The first C{float} threshold that the given identity is at least
        as big as."""
    for threshold, _ in colors:
        if identity >= threshold:
            return threshold
    raise ValueError('This should never happen! Last threshold is not 0.0?')

def getReadLengths(reads, gapChars):
    """Get all read lengths, excluding gap characters.

    @param reads: A C{Reads} instance.
    @param gapChars: A C{str} of sequence characters considered to be gaps.
    @return: A C{dict} keyed by read id, with C{int} length values."""
    gapChars = set(gapChars)
    result = {}
    for read in reads:
        result[read.id] = len(read) - sum((character in gapChars for character in read.sequence))
    return result

def collectData(reads1, reads2, square, matchAmbiguous):
    """Get pairwise matching statistics for two sets of reads.

    @param reads1: An C{OrderedDict} of C{str} read ids whose values are
        C{Read} instances. These will be the rows of the table.
    @param reads2: An C{OrderedDict} of C{str} read ids whose values are
        C{Read} instances. These will be the columns of the table.
    @param square: If C{True} we are making a square table of a set of
        sequences against themselves (in which case we show nothing on the
        diagonal).
    @param matchAmbiguous: If C{True}, count ambiguous nucleotides that are
        possibly correct as actually being correct. Otherwise, we are strict
        and insist that only non-ambiguous nucleotides can contribute to the
        matching nucleotide count."""
    result = defaultdict(dict)
    for id1, read1 in reads1.items():
        for id2, read2 in reads2.items():
            if id1 != id2 or not square:
                match = compareDNAReads(read1, read2, matchAmbiguous=matchAmbiguous)['match']
                if not matchAmbiguous:
                    assert match['ambiguousMatchCount'] == 0
                result[id1][id2] = result[id2][id1] = match
    return result

def create_task(function, *args, **kwargs):
    """Create a task object
    name: The name of the task.
    function: The actual task function. It should take no arguments,
        and return a False-y value if it fails.
    dependencies: (optional, ()) Any dependencies that this task relies
        on."""
    name = '{}'.format(uuid4())
    handler = None
    deps = set()
    if 'name' in kwargs:
        name = kwargs['name']
        del kwargs['name']
    elif function is not None:
        name = '{}-{}'.format(function.__name__, name)
    if 'handler' in kwargs:
        handler = kwargs['handler']
        del kwargs['handler']
    if 'dependencies' in kwargs:
        for dep in kwargs['dependencies']:
            deps.add(dep)
        del kwargs['dependencies']
    for arg in args:
        if isinstance(arg, Task):
            deps.add(arg.name)
    for key in kwargs:
        if isinstance(kwargs[key], Task):
            deps.add(kwargs[key].name)
    return Task(name, function, handler, frozenset(deps), args, kwargs)

def update(taxids, conn, force_download, silent):
    """Update local UniProt database"""
    if not silent:
        click.secho('WARNING: Update is very time consuming and can take several hours depending which organisms you are importing!', fg='yellow')
        if not taxids:
            click.echo('Please note that you can restrict import to organisms by NCBI taxonomy IDs')
            click.echo('Example (human, mouse, rat):\n')
