def arbiter(rst, clk, req_vec, gnt_vec=None, gnt_idx=None, gnt_vld=None, gnt_rdy=None, ARBITER_TYPE='priority'):
    """Wrapper that provides common interface to all arbiters"""
    if ARBITER_TYPE == 'priority':
        _arb = arbiter_priority(req_vec, gnt_vec, gnt_idx, gnt_vld)
    elif ARBITER_TYPE == 'roundrobin':
        _arb = arbiter_roundrobin(rst, clk, req_vec, gnt_vec, gnt_idx, gnt_vld, gnt_rdy)
    else:
        assert 'Arbiter: Unknown arbiter type: {}'.format(ARBITER_TYPE)
    return _arb

def arbiter_priority(req_vec, gnt_vec=None, gnt_idx=None, gnt_vld=None):
    """Static priority arbiter: grants the request with highest priority, which is the lower index
    req_vec - (i) vector of request signals, req_vec[0] is with the highest priority
    gnt_vec - (o) optional, vector of grants, one grant per request, only one grant can be active at at time
    gnt_idx - (o) optional, grant index, index of the granted request
    gnt_vld - (o) optional, grant valid, indicate that there is a granted request"""
    REQ_NUM = len(req_vec)
    gnt_vec_s = Signal(intbv(0)[REQ_NUM:])
    gnt_idx_s = Signal(intbv(0, min=0, max=REQ_NUM))
    gnt_vld_s = Signal(bool(0))
    @always_comb
    def prioroty_encoder():
        gnt_vec_s.next = 0
        gnt_idx_s.next = 0
        gnt_vld_s.next = 0
        for i in range(REQ_NUM):
            if req_vec[i] == 1:
                gnt_vec_s.next[i] = 1
                gnt_idx_s.next = i
                gnt_vld_s.next = 1
                break
    if gnt_vec != None:
        _vec = assign(gnt_vec, gnt_vec_s)
    if gnt_idx != None:
        _idx = assign(gnt_idx, gnt_idx_s)
    if gnt_vld != None:
        _vld = assign(gnt_vld, gnt_vld_s)
    return instances()

def dedupFasta(reads):
    """Remove sequence duplicates (based on sequence) from FASTA.

    @param reads: a C{dark.reads.Reads} instance.
    @return: a generator of C{dark.reads.Read} instances with no duplicates."""
    seen = set()
    add = seen.add
    for read in reads:
        hash_ = md5(read.sequence.encode('UTF-8')).digest()
        if hash_ not in seen:
            add(hash_)
            yield read

def fastaSubtract(fastaFiles):
    """Given a list of open file descriptors, each with FASTA content,
    remove the reads found in the 2nd, 3rd, etc files from the first file
    in the list.

    @param fastaFiles: a C{list} of FASTA filenames.
    @raises IndexError: if passed an empty list.
    @return: An iterator producing C{Bio.SeqRecord} instances suitable for
        writing to a file using C{Bio.SeqIO.write}."""
    reads = {}
    firstFile = fastaFiles.pop(0)
    for seq in SeqIO.parse(firstFile, 'fasta'):
        reads[seq.id] = seq
    for fastaFile in fastaFiles:
        for seq in SeqIO.parse(fastaFile, 'fasta'):
            if seq.id in reads:
                assert str(seq.seq) == str(reads[seq.id].seq)
            reads.pop(seq.id, None)
    return iter(reads.values())

def printBlastRecordForDerek(record):
    """This is a hacked version of printBlastRecord that I wrote in
    Addenbrookes hospital so Derek could try hacking on the reads
    that had low e values.  It's called by bin/print-blast-xml-for-derek.py"""
    if len(record.alignments) == 0:
        return 0
    if record.descriptions[0].e > 1e-120:
        return 0
    print(record.query, end=' ')
    for i, alignment in enumerate(record.alignments):
        print(record.descriptions[i].e, end=' ')
        for hspIndex, hsp in enumerate(alignment.hsps, start=1):
            if hsp.sbjct_start < hsp.sbjct_end:
                sense = 1
                if hsp.sbjct_start < 2200:
                    side = 'left'
                else:
                    side = 'right'
            else:
                sense = -1
                if hsp.sbjct_end < 2200:
                    side = 'left'
                else:
                    side = 'right'
            print(sense, side)
            break
    return 1

def splitNames(names):
    """Split a sequence id string like "Protein name [pathogen name]" into two
    pieces using the final square brackets to delimit the pathogen name.

    @param names: A C{str} "protein name [pathogen name]" string.
    @return: A 2-C{tuple} giving the C{str} protein name and C{str} pathogen
        name. If C{names} cannot be split on square brackets, it is
        returned as the first tuple element, followed by _NO_PATHOGEN_NAME."""
    match = _PATHOGEN_RE.match(names)
    if match:
        proteinName = match.group(1).strip()
        pathogenName = match.group(2).strip()
    else:
        proteinName = names
        pathogenName = _NO_PATHOGEN_NAME
    return (proteinName, pathogenName)

def getPathogenProteinCounts(filenames):
    """Get the number of proteins for each pathogen in C{filenames}.

    @param filenames: Either C{None} or a C{list} of C{str} FASTA file names.
        If C{None} an empty C{Counter} is returned. If FASTA file names are
        given, their sequence ids should have the format used in the NCBI
        bacterial and viral protein reference sequence files, in which the
        protein name is followed by the pathogen name in square brackets.
    @return: A C{Counter} keyed by C{str} pathogen name, whose values are
        C{int}s with the count of the number of proteins for the pathogen."""
    result = Counter()
    if filenames:
        for filename in filenames:
            for protein in FastaReads(filename):
                _, pathogenName = splitNames(protein.id)
                if pathogenName != _NO_PATHOGEN_NAME:
                    result[pathogenName] += 1
    return result

def get_args(request_args, allowed_int_args=[], allowed_str_args=[]):
    """Check allowed argument names and return is as dictionary"""
    args = {}
    for allowed_int_arg in allowed_int_args:
        int_value = request_args.get(allowed_int_arg, default=None, type=None)
        if int_value:
            args[allowed_int_arg] = int(int_value)
    for allowed_str_arg in allowed_str_args:
        str_value = request_args.get(allowed_str_arg, default=None, type=None)
        if str_value:
            args[allowed_str_arg] = str_value
    return args

def npartial(func, *args, **kwargs):
    """Returns a partial node visitor function"""
