        if form.is_valid():
            unverified = form.save()
            body = 'Please confirm your email address to subscribe to status updates from %(name)s:\n\n%(link)s' % dict(name=conf.NAME, link=urlparse.urljoin(conf.BASE_URL, reverse('overseer:verify_subscription', args=[unverified.ident])))
            from_mail = conf.FROM_EMAIL
