def getSequence(title, db='nucleotide'):
    """Get information about a sequence from Genbank.

    @param title: A C{str} sequence title from a BLAST hit. Of the form
        'gi|63148399|gb|DQ011818.1| Description...'.
    @param db: The C{str} name of the Entrez database to consult.

    NOTE: this uses the network!  Also, there is a 3 requests/second limit
    imposed by NCBI on these requests so be careful or your IP will be banned."""
    titleId = title.split(' ', 1)[0]
    try:
        gi = titleId.split('|')[1]
    except IndexError:
        gi = str(titleId)
    try:
        client = Entrez.efetch(db=db, rettype='gb', retmode='text', id=gi)
    except URLError:
        return None
    else:
        record = SeqIO.read(client, 'gb')
        client.close()
        return record

def main(gi, ranges):
    """Print the features of the genbank entry given by gi. If ranges is
    non-emtpy, only print features that include the ranges.

    gi: either a hit from a BLAST record, in the form
        'gi|63148399|gb|DQ011818.1|' or a gi number (63148399 in this example).
    ranges: a possibly empty list of ranges to print information for. Each
        range is a non-descending (start, end) pair of integers."""
    record = getSequence(gi)
    if record is None:
        print("Looks like you're offline.")
        sys.exit(3)
    else:
        printed = set()
        if ranges:
            for start, end in ranges:
                for index, feature in enumerate(record.features):
                    if start < int(feature.location.end) and end > int(feature.location.start) and (index not in printed):
                        print(feature)
                        printed.add(index)
        else:
            for feature in record.features:
                print(feature)

def samReferencesToStr(filenameOrSamfile, indent=0):
    """List SAM/BAM file reference names and lengths.

    @param filenameOrSamfile: Either a C{str} SAM/BAM file name or an
        instance of C{pysam.AlignmentFile}.
    @param indent: An C{int} number of spaces to indent each line.
    @return: A C{str} describing known reference names and their lengths."""
    indent = ' ' * indent
    def _references(sam):
        result = []
        for i in range(sam.nreferences):
            result.append('%s%s (length %d)' % (indent, sam.get_reference_name(i), sam.lengths[i]))
        return '\n'.join(result)
    if isinstance(filenameOrSamfile, six.string_types):
        with samfile(filenameOrSamfile) as sam:
            return _references(sam)
    else:
        return _references(sam)

def mux(sel, ls_di, do):
    """Multiplexes a list of input signals to an output signal
    do = sl_di[sel]

    sel - select index
    ls_di - list of input signals
    do - output signals"""
    N = len(ls_di)
    @always_comb
    def _mux():
        do.next = 0
        for i in range(N):
            if i == sel:
                do.next = ls_di[i]
    return _mux

def demux(sel, di, ls_do):
    """Demultiplexes an input signal to a list of output signals
    ls_do[sel] =  di

    sel - select index
    di - input signal
    ls_do - list of output signals"""
    N = len(ls_do)
    @always_comb
    def _demux():
        for i in range(N):
            ls_do[i].next = 0
            if i == sel:
                ls_do[i].next = di
    return _demux

def bitslice_select(offset, bv_di, bv_do):
    """Selects a bit-slice from a bit-vector
    offset - (i) bit offset of the slice
    bv_di  - (i) bit vector where the slice is taken from
    bv_do  - (o) selected slice; the length of this bit-vector defines the number of bit in the slice

    bv_do = bv_di[len(bv_do)+offset:offset]"""
    LEN_I = len(bv_di)
    LEN_O = len(bv_do)
    assert LEN_I >= LEN_O, 'bitslice_select: expects len(bv_di) >= len(bv_do), but len(bv_di)={}, len(bv_do)'.format(LEN_I, LEN_O)
    OFFSET_MAX = LEN_I - LEN_O + 1
    @always_comb
    def _slice():
        bv_do.next = 0
        for i in range(OFFSET_MAX):
            if i == offset:
                for b in range(LEN_O):
                    bv_do.next[b] = bv_di[i + b]
    return _slice

def byteorder(bv_di, bv_do, REVERSE=True):
    """Reverses the byte order of an input bit-vector
    bv_di - (i) input bit-vector
    bv_do - (o) output bit-vector"""
    BITS = len(bv_di)
    assert BITS % 8 == 0, 'byteorder: expects len(bv_in)=8*x, but len(bv_in)={}'.format(BITS)
    if REVERSE:
        BYTES = BITS // 8
        y = ConcatSignal(*[bv_di(8 * (b + 1), 8 * b) for b in range(BYTES)])
        @always_comb
        def _reverse():
            bv_do.next = y
    else:
        @always_comb
        def _pass():
            bv_do.next = bv_di
    return instances()

def findOrDie(s):
    """Look up an amino acid.

    @param s: A C{str} amino acid specifier. This may be a full name,
        a 3-letter abbreviation or a 1-letter abbreviation. Case is ignored.
    @return: An C{AminoAcid} instance, if one can be found. Else exit."""
    aa = find(s)
    if aa:
        return aa
    else:
        print('Unknown amino acid or codon: %s' % s, file=sys.stderr)
        print('Valid arguments are: %s.' % list(CODONS.keys()), file=sys.stderr)
        sys.exit(1)

def printBlastRecord(record):
    """Print a BLAST record.

    @param record: A BioPython C{Bio.Blast.Record.Blast} instance."""
    for key in sorted(record.__dict__.keys()):
        if key not in ['alignments', 'descriptions', 'reference']:
            print('%s: %r' % (key, record.__dict__[key]))
    print('alignments: (%d in total):' % len(record.alignments))
    for i, alignment in enumerate(record.alignments):
        print('  description %d:' % (i + 1))
        for attr in ['accession', 'bits', 'e', 'num_alignments', 'score']:
            print('    %s: %s' % (attr, getattr(record.descriptions[i], attr)))
        print('  alignment %d:' % (i + 1))
        for attr in ('accession', 'hit_def', 'hit_id', 'length', 'title'):
            print('    %s: %s' % (attr, getattr(alignment, attr)))
        print('    HSPs (%d in total):' % len(alignment.hsps))
        for hspIndex, hsp in enumerate(alignment.hsps, start=1):
            print('      hsp %d:' % hspIndex)
            printHSP(hsp, '        ')

def _stage_ctrl(rst, clk, rx_rdy, rx_vld, tx_rdy, tx_vld, stage_en, stop_rx=None, stop_tx=None, BC=False):
    """Single stage control
    BC - enable bubble compression"""
    if stop_rx == None:
        stop_rx = False
    if stop_tx == None:
        stop_tx = False
    state = Signal(bool(0))
    a = Signal(bool(0))
    b = Signal(bool(0))
    bc_link = state if BC else True
    @always_comb
    def _comb1():
        a.next = tx_rdy or stop_tx or (not bc_link)
        b.next = rx_vld or stop_rx
    @always_comb
    def _comb2():
        rx_rdy.next = a and (not stop_rx)
        tx_vld.next = state and (not stop_tx)
        stage_en.next = a and b
    @always_seq(clk.posedge, reset=rst)
    def _state():
        if a:
            state.next = b
    return (_comb1, _comb2, _state)

def _debugPrint(hsp, queryLen, localDict, msg=''):
    """Print debugging information showing the local variables used during
    a call to normalizeHSP and the hsp and then raise an C{AssertionError}.

    @param hsp: The HSP C{dict} passed to normalizeHSP.
    @param queryLen: the length of the query sequence.
    @param localDict: A C{dict} of local variables (as produced by locals()).
    @param msg: A C{str} message to raise C{AssertionError} with.
    @raise AssertionError: unconditionally."""
    print('normalizeHSP error:', file=sys.stderr)
    print('  queryLen: %d' % queryLen, file=sys.stderr)
    print('  Original HSP:', file=sys.stderr)
    for attr in ['bits', 'btop', 'expect', 'frame', 'query_end', 'query_start', 'sbjct', 'query', 'sbjct_end', 'sbjct_start']:
        print('    %s: %r' % (attr, hsp[attr]), file=sys.stderr)
    print('  Local variables:', file=sys.stderr)
    for var in sorted(localDict):
        if var != 'hsp':
            print('    %s: %s' % (var, localDict[var]), file=sys.stderr)
    raise AssertionError(msg)

def titleCounts(readsAlignments):
    """Count the number of times each title in a readsAlignments instance is
    matched. This is useful for rapidly discovering what titles were matched
    and with what frequency.

    @param readsAlignments: A L{dark.alignments.ReadsAlignments} instance.
    @return: A C{dict} whose keys are titles and whose values are the integer
        counts of the number of reads that matched that title."""
    titles = defaultdict(int)
    for readAlignments in readsAlignments:
        for alignment in readAlignments:
            titles[alignment.subjectTitle] += 1
    return titles

