def exact_ratio(x):
    """Convert Real number x exactly to (numerator, denominator) pair.

    x is expected to be an int, Fraction, Decimal or float."""
    try:
        try:
            return (x.numerator, x.denominator)
        except AttributeError:
            try:
                return x.as_integer_ratio()
            except AttributeError:
                try:
                    return decimal_to_ratio(x)
                except AttributeError:
                    msg = "can't convert type '{}' to numerator/denominator"
                    raise TypeError(msg.format(type(x).__name__))
    except (OverflowError, ValueError):
        return (x, None)

def decimal_to_ratio(d):
    """Convert Decimal d to exact integer ratio (numerator, denominator).
    """
    sign, digits, exp = d.as_tuple()
    if exp in ('F', 'n', 'N'):
        assert not d.is_finite()
        raise ValueError
    num = 0
    for digit in digits:
        num = num * 10 + digit
    if sign:
        num = -num
    den = 10 ** (-exp)
    return (num, den)

def counts(data):
    """Generate a table of sorted (value, frequency) pairs."""
    if data is None:
        raise TypeError('None is not iterable')
    table = collections.Counter(data).most_common()
    if not table:
        return table
    maxfreq = table[0][1]
    for i in range(1, len(table)):
        if table[i][1] != maxfreq:
            table = table[:i]
            break
    return table

def mean(data):
    """Return the sample arithmetic mean of data.

    If ``data`` is empty, StatisticsError will be raised."""
    if iter(data) is data:
        data = list(data)
    n = len(data)
    if n < 1:
        raise StatisticsError('mean requires at least one data point')
    return sum(data) / n

def median_low(data):
    """Return the low median of numeric data.

    When the number of data points is odd, the middle value is returned.
    When it is even, the smaller of the two middle values is returned."""
    data = sorted(data)
    n = len(data)
    if n == 0:
        raise StatisticsError('no median for empty data')
    if n % 2 == 1:
        return data[n // 2]
    else:
        return data[n // 2 - 1]

def mode(data):
    """Return the most common data point from discrete or nominal data.

    ``mode`` assumes discrete data, and returns a single value. This is the
    standard treatment of the mode as commonly taught in schools:

    If there is not exactly one most common value, ``mode`` will raise
    StatisticsError."""
    table = counts(data)
    if len(table) == 1:
        return table[0][0]
    elif table:
        raise StatisticsError('no unique mode; found %d equally common values' % len(table))
    else:
        raise StatisticsError('no mode for empty data')

def stdev(data, xbar=None):
    """Return the square root of the sample variance.

    See ``variance`` for arguments and other details."""
    var = variance(data, xbar)
    try:
        return var.sqrt()
    except AttributeError:
        return math.sqrt(var)

def pstdev(data, mu=None):
    """Return the square root of the population variance.

    See ``pvariance`` for arguments and other details."""
    var = pvariance(data, mu)
    try:
        return var.sqrt()
    except AttributeError:
        return math.sqrt(var)

def geometric_mean(data):
    """Return the geometric mean of data
    """
    if not data:
        raise StatisticsError('geometric_mean requires at least one data point')
    data = [x if x > 0 else math.e if x == 0 else 1.0 for x in data]
    return math.pow(math.fabs(functools.reduce(operator.mul, data)), 1.0 / len(data))

def get_histogram(data):
    """Return the histogram relative to the given data

    Assume that the data are already sorted"""
    count = len(data)
    if count < 2:
        raise StatisticsError('Too few data points ({}) for get_histogram'.format(count))
    min_ = data[0]
    max_ = data[-1]
    std = stdev(data)
    bins = get_histogram_bins(min_, max_, std, count)
    res = {x: 0 for x in bins}
    for value in data:
        for bin_ in bins:
            if value <= bin_:
                res[bin_] += 1
                break
    return sorted(iteritems(res))

def get_histogram_bins(min_, max_, std, count):
    """Return optimal bins given the input parameters"""
    width = _get_bin_width(std, count)
    count = int(round((max_ - min_) / width) + 1)
    if count:
        bins = [i * width + min_ for i in xrange(1, count + 1)]
    else:
        bins = [min_]
    return bins

def _get_bin_width(stdev, count):
    """Return the histogram's optimal bin width based on Sturges

    http://www.jstor.org/pss/2965501"""
    w = int(round(3.5 * stdev / count ** (1.0 / 3)))
    if w:
        return w
    else:
        return 1

def __process_line(line, strip_eol, strip):
    """process a single line value."""
    if strip:
        line = line.strip()
    elif strip_eol and line.endswith('\n'):
        line = line[:-1]
    return line

def parse_json_structure(string_item):
    """Given a raw representation of a json structure, returns the parsed corresponding data
    structure (``JsonRpcRequest`` or ``JsonRpcRequestBatch``)

    :param string_item:
    :return:"""
    if not isinstance(string_item, str):
        raise TypeError('Expected str but got {} instead'.format(type(string_item).__name__))
    try:
        item = json.loads(string_item)
    except json.JSONDecodeError:
        raise JsonRpcParseError()
    if isinstance(item, dict):
        return JsonRpcRequest.from_dict(item)
    elif isinstance(item, list):
        if len(item) == 0:
            raise JsonRpcInvalidRequestError()
        request_batch = JsonRpcRequestBatch([])
        for d in item:
            try:
                if not isinstance(d, dict):
                    raise JsonRpcInvalidRequestError()
                parsed_entry = JsonRpcRequest.from_dict(d)
            except JsonRpcInvalidRequestError:
                parsed_entry = GenericResponse.INVALID_REQUEST
            request_batch.add_item(parsed_entry)
        return request_batch

def expand_includes(text, path='.'):
    """Recursively expands includes in given text."""
    def read_and_expand(match):
        filename = match.group('filename')
        filename = join(path, filename)
        text = read(filename)
        return expand_includes(text, path=join(path, dirname(filename)))
    return re.sub('^\\.\\. include:: (?P<filename>.*)$', read_and_expand, text, flags=re.MULTILINE)

def parse_file(infile, exit_on_error=True):
    """Parse a comma-separated file with columns "ra,dec,magnitude".
    """
    try:
        a, b, mag = np.atleast_2d(np.genfromtxt(infile, usecols=[0, 1, 2], delimiter=',')).T
    except IOError as e:
        if exit_on_error:
            logger.error('There seems to be a problem with the input file, the format should be: RA_degrees (J2000), Dec_degrees (J2000), Magnitude. There should be no header, columns should be separated by a comma')
            sys.exit(1)
        else:
            raise e
    return (a, b, mag)

