def absl_flags():
    """Extracts absl-py flags that the user has specified and outputs their
    key-value mapping.

    By default, extracts only those flags in the current __package__
    and mainfile.

    Useful to put into a trial's param_map."""
    flags_dict = flags.FLAGS.flags_by_module_dict()
    def _relevant_module(module_name):
        if __package__ and __package__ in module_name:
            return True
        if module_name == sys.argv[0]:
            return True
        return False
    return {flag.name: flag.value for module, flags in flags_dict.items() for flag in flags if _relevant_module(module)}

def deepcopy(value):
    """The default copy.deepcopy seems to copy all objects and some are not
    `copy-able`.

    We only need to make sure the provided data is a copy per key, object does
    not need to be copied."""
    if not isinstance(value, (dict, list, tuple)):
        return value
    if isinstance(value, dict):
        copy = {}
        for k, v in value.items():
            copy[k] = deepcopy(v)
    if isinstance(value, tuple):
        copy = list(range(len(value)))
        for k in get_keys(list(value)):
            copy[k] = deepcopy(value[k])
        copy = tuple(copy)
    if isinstance(value, list):
        copy = list(range(len(value)))
        for k in get_keys(value):
            copy[k] = deepcopy(value[k])
    return copy

def usernameFromRequest(request):
    """Take an HTTP request and return a username of the form <user>@<domain>.

    @type request: L{inevow.IRequest}
    @param request: A HTTP request

    @return: A C{str}"""
    username = request.args.get('username', [''])[0]
    if '@' not in username:
        username = '%s@%s' % (username, request.getHeader('host').split(':')[0])
