def _createLocalRouter(siteStore):
    """Create an L{IMessageRouter} provider for the default case, where no
    L{IMessageRouter} powerup is installed on the top-level store.

    It wraps a L{LocalMessageRouter} around the L{LoginSystem} installed on the
    given site store.

    If no L{LoginSystem} is present, this returns a null router which will
    simply log an error but not deliver the message anywhere, until this
    configuration error can be corrected.

    @rtype: L{IMessageRouter}"""
    ls = siteStore.findUnique(LoginSystem, default=None)
    if ls is None:
        try:
            raise UnsatisfiedRequirement()
        except UnsatisfiedRequirement:
            log.err(Failure(), 'You have opened a substore from a site store with no LoginSystem.  Message routing is disabled.')
        return _NullRouter()
    return LocalMessageRouter(ls)

def _webTranslator(store, fallback):
    """Discover a web translator based on an Axiom store and a specified default.
    Prefer the specified default.

    This is an implementation detail of various initializers in this module
    which require an L{IWebTranslator} provider.  Some of those initializers
    did not previously require a webTranslator, so this function will issue a
    L{UserWarning} if no L{IWebTranslator} powerup exists for the given store
    and no fallback is provided.

    @param store: an L{axiom.store.Store}
    @param fallback: a provider of L{IWebTranslator}, or None

    @return: 'fallback', if it is provided, or the L{IWebTranslator} powerup on
    'store'."""
    if fallback is None:
        fallback = IWebTranslator(store, None)
        if fallback is None:
            warnings.warn('No IWebTranslator plugin when creating Scrolltable - broken configuration, now deprecated!  Try passing webTranslator keyword argument.', category=DeprecationWarning, stacklevel=4)
    return fallback

