def mock_import(do_not_mock=None, **mock_kwargs):
    """Mocks import statements by ignoring ImportErrors
    and replacing the missing module with a Mock.

    :param str|unicode|list[str|unicode] do_not_mock: names of modules
        that should exists, and an ImportError could be raised for.
    :param mock_kwargs: kwargs for MagicMock object.
    :return: patch object"""
    do_not_mock = _to_list(do_not_mock)
    def try_import(module_name, *args, **kwargs):
        try:
            return _builtins_import(module_name, *args, **kwargs)
        except:
            if any((_match(module_name, prefix) for prefix in do_not_mock)):
                raise
            return mock.MagicMock(**mock_kwargs)
    return mock.patch('six.moves.builtins.__import__', try_import)

def min_tasks_per_node(queue_id):
    """This function is used when requesting non exclusive use
    as the parallel environment might enforce a minimum number
    of tasks"""
    parallel_env = queue_id.split(':')[0]
    queue_name = queue_id.split(':')[1]
    tasks = 1
    pe_tasks = tasks
    with os.popen('qconf -sp ' + parallel_env) as f:
        try:
            for line in f:
                if line.split(' ')[0] == 'allocation_rule':
                    pe_tasks = int(re.split('\\W+', line)[1])
        except:
            pass
    return max(tasks, pe_tasks)

def check_shape(meth):
    """Decorator for larray magic methods, to ensure that the operand has
    the same shape as the array."""
    @wraps(meth)
    def wrapped_meth(self, val):
        if isinstance(val, (larray, numpy.ndarray)):
            if val.shape != self._shape:
                raise ValueError('shape mismatch: objects cannot be broadcast to a single shape')
        return meth(self, val)
    return wrapped_meth

def partial_shape(addr, full_shape):
    """Calculate the size of the sub-array represented by `addr`"""
    def size(x, max):
        if isinstance(x, (int, long, numpy.integer)):
            return None
        elif isinstance(x, slice):
            y = min(max, x.stop or max)
            return 1 + (y - (x.start or 0) - 1) // (x.step or 1)
        elif isinstance(x, collections.Sized):
            if hasattr(x, 'dtype') and x.dtype == bool:
                return x.sum()
            else:
                return len(x)
        else:
            raise TypeError('Unsupported index type %s' % type(x))
    addr = full_address(addr, full_shape)
    if isinstance(addr, numpy.ndarray) and addr.dtype == bool:
        return (addr.sum(),)
    elif all((isinstance(x, collections.Sized) for x in addr)):
        return (len(addr[0]),)
    else:
        shape = [size(x, max) for x, max in zip(addr, full_shape)]
        return tuple([x for x in shape if x is not None])

def reverse(func):
    """Given a function f(a, b), returns f(b, a)"""
    @wraps(func)
    def reversed_func(a, b):
        return func(b, a)
    reversed_func.__doc__ = 'Reversed argument form of %s' % func.__doc__
    reversed_func.__name__ = 'reversed %s' % func.__name__
    return reversed_func

def _build_ufunc(func):
    """Return a ufunc that works with lazy arrays"""
    def larray_compatible_ufunc(x):
        if isinstance(x, larray):
            y = deepcopy(x)
            y.apply(func)
            return y
        else:
            return func(x)
    return larray_compatible_ufunc

