def extract_emails(results: str, domain: str, fuzzy: bool) -> List[str]:
    """Grab email addresses from raw text data."""
    pattern: Pattern = re.compile('([\\w.-]+@[\\w.-]+)')
    hits: List[str] = pattern.findall(results)
    if fuzzy:
        seed = domain.split('.')[0]
        emails: List[str] = [x.lower() for x in hits if x.split('@')[1].__contains__(seed)]
    else:
        emails: List[str] = [x.lower() for x in hits if x.endswith(domain)]
    return list(set(emails))

def fasta_cmd_get_seqs(acc_list, blast_db=None, is_protein=None, out_filename=None, params={}, WorkingDir=tempfile.gettempdir(), SuppressStderr=None, SuppressStdout=None):
    """Retrieve sequences for list of accessions"""
    if is_protein is None:
        params['-p'] = 'G'
    elif is_protein:
        params['-p'] = 'T'
    else:
        params['-p'] = 'F'
    if blast_db:
        params['-d'] = blast_db
    if out_filename:
        params['-o'] = out_filename
    params['-a'] = 'F'
    fasta_cmd = FastaCmd(params=params, InputHandler='_input_as_string', WorkingDir=WorkingDir, SuppressStderr=SuppressStderr, SuppressStdout=SuppressStdout)
    return fasta_cmd('"%s"' % ','.join(acc_list))

def seqs_from_fastacmd(acc_list, blast_db, is_protein=True):
    """Get dict of description:seq from fastacmd."""
    fasta_cmd_res = fasta_cmd_get_seqs(acc_list, blast_db=blast_db, is_protein=is_protein)
    recs = FastaCmdFinder(fasta_cmd_res['StdOut'])
    result = {}
    for rec in recs:
        try:
            result[rec[0][1:].strip()] = ''.join(map(strip, rec[1:]))
        except IndexError:
            pass
    fasta_cmd_res.cleanUp()
    return result

