    params = {'-M': 'BLOSUM62', '-a': '1', '-e': e_value, '-b': max_hits, '-v': max_hits, '-p': 'blastp'}
    params.update(extra_params)
    blast_res = blast_seqs(seqs, Blastall, blast_mat_root=blast_mat_root, blast_db=blast_db, params=params, add_seq_names=False, WorkingDir=working_dir)
