def woa_track_from_file(d, lat, lon, filename, varnames=None):
    """Temporary solution: WOA for surface track
    """
    d = np.asanyarray(d)
    lat = np.asanyarray(lat)
    lon = np.asanyarray(lon)
    lon[lon < 0] += 360
    doy = np.array([int(dd.strftime('%j')) for dd in d])
    nc = netCDF4.Dataset(expanduser(filename), 'r')
    if varnames is None:
        varnames = {}
        for v in nc.variables.keys():
            if nc.variables[v].dimensions == (u'time', u'depth', u'lat', u'lon'):
                varnames[v] = v
    output = {}
    for v in varnames:
        output[v] = []
    for d_n, lat_n, lon_n in zip(doy, lat, lon):
        n_d = np.abs(d_n - nc.variables['time'][:]).argmin()
        n_x = np.abs(lon_n - nc.variables['lon'][:]).argmin()
        n_y = np.abs(lat_n - nc.variables['lat'][:]).argmin()
        for v in varnames:
            output[v].append(nc.variables[varnames[v]][n_d, 0, n_y, n_x])
    for v in varnames:
        output[v] = ma.fix_invalid(output[v])
    return output

def pair_hmm_align_unaligned_seqs(seqs, moltype=DNA_cogent, params={}):
    """Checks parameters for pairwise alignment, returns alignment.

    Code from Greg Caporaso."""
    seqs = LoadSeqs(data=seqs, moltype=moltype, aligned=False)
    try:
        s1, s2 = seqs.values()
    except ValueError:
        raise ValueError('Pairwise aligning of seqs requires exactly two seqs.')
    try:
        gap_open = params['gap_open']
    except KeyError:
        gap_open = 5
    try:
        gap_extend = params['gap_extend']
    except KeyError:
        gap_extend = 2
    try:
        score_matrix = params['score_matrix']
    except KeyError:
        score_matrix = make_dna_scoring_dict(match=1, transition=-1, transversion=-1)
    return local_pairwise(s1, s2, score_matrix, gap_open, gap_extend)

def sumaclust_denovo_cluster(seq_path=None, result_path=None, shortest_len=True, similarity=0.97, threads=1, exact=False, HALT_EXEC=False):
    """Function  : launch SumaClust de novo OTU picker

    Parameters: seq_path, filepath to reads;
                result_path, filepath to output OTU map;
                shortest_len, boolean;
                similarity, the similarity threshold (between (0,1]);
                threads, number of threads to use;
                exact, boolean to perform exact matching

    Return    : clusters, list of lists"""
    if seq_path is None or not exists(seq_path):
        raise ValueError('Error: FASTA query sequence filepath is mandatory input.')
    if result_path is None or not isdir(dirname(realpath(result_path))):
        raise ValueError('Error: output directory is mandatory input.')
    sumaclust = Sumaclust(HALT_EXEC=HALT_EXEC)
    sumaclust.Parameters['-O'].on(result_path)
    if similarity is not None:
        sumaclust.Parameters['-t'].on(similarity)
    if exact:
        sumaclust.Parameters['-e'].on()
    if not shortest_len:
        sumaclust.Parameters['-l'].off()
    if threads > 0:
        sumaclust.Parameters['-p'].on(threads)
    else:
        raise ValueError('Number of threads must be positive.')
    app_result = sumaclust(seq_path)
    f_otumap = app_result['OtuMap']
    clusters = [line.strip().split('\t')[1:] for line in f_otumap]
    return clusters

def uclust_search_and_align_from_fasta_filepath(query_fasta_filepath, subject_fasta_filepath, percent_ID=0.75, enable_rev_strand_matching=True, max_accepts=8, max_rejects=32, tmp_dir=gettempdir(), HALT_EXEC=False):
    """query seqs against subject fasta using uclust,

    return global pw alignment of best match"""
    params = {'--id': percent_ID, '--maxaccepts': max_accepts, '--maxrejects': max_rejects, '--libonly': True, '--lib': subject_fasta_filepath, '--tmpdir': tmp_dir}
    if enable_rev_strand_matching:
        params['--rev'] = True
    app = Uclust(params, TmpDir=tmp_dir, HALT_EXEC=HALT_EXEC)
    _, alignment_filepath = mkstemp(dir=tmp_dir, prefix='uclust_alignments', suffix='.fasta')
    _, uc_filepath = mkstemp(dir=tmp_dir, prefix='uclust_results', suffix='.uc')
    input_data = {'--input': query_fasta_filepath, '--fastapairs': alignment_filepath, '--uc': uc_filepath}
    app_result = app(input_data)
    for result in process_uclust_pw_alignment_results(app_result['PairwiseAlignments'], app_result['ClusterFile']):
        try:
            yield result
        except GeneratorExit:
            break
    app_result.cleanUp()
    return

def uclust_cluster_from_sorted_fasta_filepath(fasta_filepath, uc_save_filepath=None, percent_ID=0.97, max_accepts=1, max_rejects=8, stepwords=8, word_length=8, optimal=False, exact=False, suppress_sort=False, enable_rev_strand_matching=False, subject_fasta_filepath=None, suppress_new_clusters=False, stable_sort=False, tmp_dir=gettempdir(), HALT_EXEC=False):
    """Returns clustered uclust file from sorted fasta"""
    output_filepath = uc_save_filepath
    if not output_filepath:
        _, output_filepath = mkstemp(dir=tmp_dir, prefix='uclust_clusters', suffix='.uc')
    params = {'--id': percent_ID, '--maxaccepts': max_accepts, '--maxrejects': max_rejects, '--stepwords': stepwords, '--w': word_length, '--tmpdir': tmp_dir}
    app = Uclust(params, TmpDir=tmp_dir, HALT_EXEC=HALT_EXEC)
    if enable_rev_strand_matching:
        app.Parameters['--rev'].on()
    if optimal:
        app.Parameters['--optimal'].on()
    if exact:
        app.Parameters['--exact'].on()
    if suppress_sort:
        app.Parameters['--usersort'].on()
    if subject_fasta_filepath:
        app.Parameters['--lib'].on(subject_fasta_filepath)
    if suppress_new_clusters:
        app.Parameters['--libonly'].on()
    if stable_sort:
        app.Parameters['--stable_sort'].on()
    app_result = app({'--input': fasta_filepath, '--uc': output_filepath})
    return app_result

def chi_squared(*choices):
    """Calculates the chi squared"""
    term = lambda expected, observed: float((expected - observed) ** 2) / max(expected, 1)
    mean_success_rate = float(sum([c.rewards for c in choices])) / max(sum([c.plays for c in choices]), 1)
    mean_failure_rate = 1 - mean_success_rate
    return sum([term(mean_success_rate * c.plays, c.rewards) + term(mean_failure_rate * c.plays, c.plays - c.rewards) for c in choices])

def add_experiment(redis, name):
    """Adds a new experiment"""
    if not ALLOWED_NAMES.match(name):
        raise ExperimentException(name, 'Illegal name')
    if redis.exists(EXPERIMENT_REDIS_KEY_TEMPLATE % name):
        raise ExperimentException(name, 'Already exists')
    json = dict(creation_date=util.unicode_type(datetime.datetime.now()))
    pipe = redis.pipeline(transaction=True)
    pipe.sadd(ACTIVE_EXPERIMENTS_REDIS_KEY, name)
    pipe.hset(EXPERIMENT_REDIS_KEY_TEMPLATE % name, 'metadata', escape.json_encode(json))
    pipe.execute()
    return Experiment(redis, name)

def _get_matchable_segments(segments):
    """Performs a depth-first search of the segment tree to get all matchable
    segments."""
    for subsegment in segments:
        if isinstance(subsegment, Token):
            break
        if isinstance(subsegment, Segment):
            if isinstance(subsegment, MatchableSegment):
                yield subsegment
            for matchable_subsegment in _get_matchable_segments(subsegment):
                yield matchable_subsegment

def get_example():
    """Make an example for training and testing.  Outputs a tuple
    (label, features) where label is +1 if capital letters are the majority,
    and -1 otherwise; and features is a list of letters."""
    features = random.sample(string.ascii_letters, NUM_SAMPLES)
    num_capitalized = len([letter for letter in features if letter in string.ascii_uppercase])
    num_lowercase = len([letter for letter in features if letter in string.ascii_lowercase])
    if num_capitalized > num_lowercase:
        label = 1
    else:
        label = -1
    return (label, features)

