def _matrix_input_from_dict2d(matrix):
    """makes input for running clearcut on a matrix from a dict2D object"""
    int_keys = dict([('env_' + str(i), k) for i, k in enumerate(sorted(matrix.keys()))])
    int_map = {}
    for i in int_keys:
        int_map[int_keys[i]] = i
    new_dists = []
    for env1 in matrix:
        for env2 in matrix[env1]:
            new_dists.append((int_map[env1], int_map[env2], matrix[env1][env2]))
    int_map_dists = Dict2D(new_dists)
    names = sorted(int_map_dists.keys())
    rows = []
    for index, key1 in enumerate(names):
        row = []
        for key2 in names:
            row.append(str(int_map_dists[key1][key2]))
        rows.append(row)
    input_matrix = phylipMatrix(rows, names)
    input_matrix += '\n'
    return (input_matrix, int_keys)

def _unbytes(bytestr):
    """Returns a bytestring from the human-friendly string returned by `_bytes`.

    >>> _unbytes('123456')
    '\x124V'"""
    return ''.join((chr(int(bytestr[k:k + 2], 16)) for k in range(0, len(bytestr), 2)))

def hex_from(val):
    """Returns hex string representation for a given value.

    :param bytes|str|unicode|int|long val:
    :rtype: bytes|str"""
    if isinstance(val, integer_types):
        hex_str = '%x' % val
        if len(hex_str) % 2:
            hex_str = '0' + hex_str
        return hex_str
    return hexlify(val)

def b64_from(val):
    """Returns base64 encoded bytes for a given int/long/bytes value.

    :param int|long|bytes val:
    :rtype: bytes|str"""
    if isinstance(val, integer_types):
        val = int_to_bytes(val)
    return b64encode(val).decode('ascii')

def fields(iterable, fields=None):
    """Add a set of fields to each item in ``iterable``. The set of fields have a
    key=value format. '@' are added to the front of each key."""
    if not fields:
        for item in iterable:
            yield item
    prepared_fields = _prepare_fields(fields)
    for item in iterable:
        yield _process_fields(item, prepared_fields)

def tag(iterable, tags=None, key='@tags'):
    """Add tags to each dict or dict-like object in ``iterable``. Tags are added
    to each dict with a key set by ``key``. If a key already exists under the
    key given by ``key``, this function will attempt to ``.extend()``` it, but
    will fall back to replacing it in the event of error."""
    if not tags:
        for item in iterable:
            yield item
    else:
        for item in iterable:
            yield _tag(item, tags, key)

def parse(url):
    """Parses a search URL."""
    config = {}
    url = urlparse.urlparse(url)
    path = url.path[1:]
    path = path.split('?', 2)[0]
    if url.scheme in SCHEMES:
        config['ENGINE'] = SCHEMES[url.scheme]
    if url.scheme in USES_URL:
        config['URL'] = urlparse.urlunparse(('http',) + url[1:])
    if url.scheme in USES_INDEX:
        if path.endswith('/'):
            path = path[:-1]
        split = path.rsplit('/', 1)
        if len(split) > 1:
            path = split[:-1]
            index = split[-1]
        else:
            path = ''
            index = split[0]
        config.update({'URL': urlparse.urlunparse(('http',) + url[1:2] + (path,) + url[3:]), 'INDEX_NAME': index})
    if url.scheme in USES_PATH:
        config.update({'PATH': path})
    return config

