def action(route, template='', methods=['GET']):
    """Decorator to create an action"""
    def real_decorator(function):
        function.pi_api_action = True
        function.pi_api_route = route
        function.pi_api_template = template
        function.pi_api_methods = methods
        if hasattr(function, 'pi_api_crossdomain'):
            if not function.pi_api_crossdomain_data['methods']:
                function.pi_api_crossdomain_data['methods'] = methods
            if 'OPTIONS' not in function.pi_api_methods:
                function.pi_api_methods += ['OPTIONS']
        return function
    return real_decorator

def add_unique_postfix(fn):
    """__source__ = 'http://code.activestate.com/recipes/577200-make-unique-file-name/'"""
    if not os.path.exists(fn):
        return fn
    path, name = os.path.split(fn)
    name, ext = os.path.splitext(name)
    make_fn = lambda i: os.path.join(path, '%s(%d)%s' % (name, i, ext))
    for i in xrange(2, sys.maxint):
        uni_fn = make_fn(i)
        if not os.path.exists(uni_fn):
            return uni_fn

def messages(fp, key='@message'):
    """Read lines of UTF-8 from the file-like object given in ``fp``, with the
    same fault-tolerance as :function:`tagalog.io.lines`, but instead yield
    dicts with the line data stored in the key given by ``key`` (default:
    "@message")."""
    for line in lines(fp):
        txt = line.rstrip('\n')
        yield {key: txt}

def lines(fp):
    """Read lines of UTF-8 from the file-like object given in ``fp``, making sure
    that when reading from STDIN, reads are at most line-buffered.

    UTF-8 decoding errors are handled silently. Invalid characters are
    replaced by U+FFFD REPLACEMENT CHARACTER.

    Line endings are normalised to newlines by Python's universal newlines
    feature.

    Returns an iterator yielding lines."""
    if fp.fileno() == sys.stdin.fileno():
        close = True
        try:
            fp = open(fp.fileno(), mode='r', buffering=BUF_LINEBUFFERED, errors='replace')
            decode = False
        except TypeError:
            fp = os.fdopen(fp.fileno(), 'rU', BUF_LINEBUFFERED)
            decode = True
    else:
        close = False
        try:
            decode = fp.encoding != UTF8
        except AttributeError:
            decode = True
    try:
        while 1:
            l = fp.readline()
            if l:
                if decode:
                    l = l.decode(UTF8, 'replace')
                yield l
            else:
                break
    finally:
        if close:
            fp.close()

def plugitInclude(parser, token):
    """Load and render a template, using the same context of a specific action.

    Example: {% plugitInclude "/menuBar" %}"""
    bits = token.split_contents()
    if len(bits) != 2:
        raise TemplateSyntaxError("'plugitInclude' tag takes one argument: the tempalte's action to use")
    action = parser.compile_filter(bits[1])
    return PlugItIncludeNode(action)

def get_changelog_file_for_database(database=DEFAULT_DB_ALIAS):
    """get changelog filename for given `database` DB alias"""
    from django.conf import settings
    try:
        return settings.LIQUIMIGRATE_CHANGELOG_FILES[database]
    except AttributeError:
        if database == DEFAULT_DB_ALIAS:
            try:
                return settings.LIQUIMIGRATE_CHANGELOG_FILE
            except AttributeError:
                raise ImproperlyConfigured('Please set LIQUIMIGRATE_CHANGELOG_FILE or LIQUIMIGRATE_CHANGELOG_FILES in your project settings')
        else:
            raise ImproperlyConfigured('LIQUIMIGRATE_CHANGELOG_FILES dictionary setting is required for multiple databases support')
    except KeyError:
        raise ImproperlyConfigured('Liquibase changelog file is not set for database: %s' % database)

def find_target_migration_file(database=DEFAULT_DB_ALIAS, changelog_file=None):
    """Finds best matching target migration file"""
    if not database:
        database = DEFAULT_DB_ALIAS
    if not changelog_file:
        changelog_file = get_changelog_file_for_database(database)
    try:
        doc = minidom.parse(changelog_file)
    except ExpatError as ex:
        raise InvalidChangelogFile('Could not parse XML file %s: %s' % (changelog_file, ex))
    try:
        dbchglog = doc.getElementsByTagName('databaseChangeLog')[0]
    except IndexError:
        raise InvalidChangelogFile('Missing <databaseChangeLog> node in file %s' % changelog_file)
    else:
        nodes = list(filter(lambda x: x.nodeType is x.ELEMENT_NODE, dbchglog.childNodes))
        if not nodes:
            return changelog_file
        last_node = nodes[-1]
        if last_node.tagName == 'include':
            last_file = last_node.attributes.get('file').firstChild.data
            return find_target_migration_file(database=database, changelog_file=last_file)
        else:
            return changelog_file

def home(request):
    """Show the home page. Send the list of polls"""
    polls = []
    for row in curDB.execute('SELECT id, title FROM Poll ORDER BY title'):
        polls.append({'id': row[0], 'name': row[1]})
    return {'polls': polls}

def show(request, pollId):
    """Show a poll. We send informations about votes only if the user is an administrator"""
    curDB.execute('SELECT id, title, description FROM Poll WHERE id = ? ORDER BY title', (pollId,))
    poll = curDB.fetchone()
    if poll is None:
        return {}
    responses = []
    totalVotes = 0
    votedFor = 0
    curDB.execute('SELECT id, title FROM Response WHERE pollId = ? ORDER BY title ', (poll[0],))
    resps = curDB.fetchall()
    for rowRep in resps:
        votes = []
        nbVotes = 0
        for rowVote in curDB.execute('SELECT username FROM Vote WHERE responseId = ?', (rowRep[0],)):
            nbVotes += 1
            if request.args.get('ebuio_u_ebuio_admin') == 'True':
                votes.append(rowVote[0])
            if request.args.get('ebuio_u_username') == rowVote[0]:
                votedFor = rowRep[0]
        totalVotes += nbVotes
        responses.append({'id': rowRep[0], 'title': rowRep[1], 'nbVotes': nbVotes, 'votes': votes})
    return {'id': poll[0], 'name': poll[1], 'description': poll[2], 'responses': responses, 'totalVotes': totalVotes, 'votedFor': votedFor}

def vote(request, pollId, responseId):
    """Vote for a poll"""
    username = request.args.get('ebuio_u_username')
    curDB.execute('DELETE FROM Vote WHERE username = ?  AND responseId IN (SELECT id FROM Response WHERE pollId = ?) ', (username, pollId))
    curDB.execute('INSERT INTO Vote (username, responseID) VALUES (?, ?) ', (username, responseId))
    coxDB.commit()
    return PlugItRedirect('show/' + str(pollId))
    return {'id': pollId}

def create(request):
    """Create a new poll"""
    errors = []
    success = False
    listOfResponses = ['', '', '']
    title = ''
    description = ''
    id = ''
    if request.method == 'POST':
        title = request.form.get('title')
        description = request.form.get('description')
        listOfResponses = []
        for rep in request.form.getlist('rep[]'):
            if rep != '':
                listOfResponses.append(rep)
        if title == '':
            errors.append('Please set a title !')
        if len(listOfResponses) == 0:
            errors.append('Please set at least one response !')
        if len(errors) == 0:
            curDB.execute('INSERT INTO Poll (title, description) VALUES (?, ?)', (title, description))
            id = curDB.lastrowid
            for rep in listOfResponses:
                curDB.execute('INSERT INTO Response (pollId, title) VALUES (?, ?)', (id, rep))
            coxDB.commit()
            success = True
        while len(listOfResponses) < 3:
            listOfResponses.append('')
    return {'errors': errors, 'success': success, 'listOfResponses': listOfResponses, 'title': title, 'description': description, 'id': id}

