def _manageTags(tagList, guids, add=True):
    """Adds or Removes Guids from Tags"""
    objects = getObjectsFromGuids(guids)
    tags = []
    for tag in tagList:
        try:
            t = Tag.objects.get(pk=int(tag))
        except ValueError:
            t = Tag.objects.get_or_create(name=tag.lower())[0]
        tags.append(t)
    if add:
        return _addTags(tags, objects)
    else:
        return _removeTags(tags, objects)

def _addTags(tags, objects):
    """Adds tags to objects"""
    for t in tags:
        for o in objects:
            o.tags.add(t)
    return True

def _removeTags(tags, objects):
    """Removes tags from objects"""
    for t in tags:
        for o in objects:
            o.tags.remove(t)
    return True

def _short_ts_regexp():
    """Generates regexp for parsing of
    shortened relative timestamps, as shown in the table."""
    ts_re = ['^']
    for k in it.chain(_short_ts_days, _short_ts_s):
        ts_re.append('(?P<{0}>\\d+{0}\\s*)?'.format(k))
    return re.compile(''.join(ts_re), re.I | re.U)

def get_by_string(cls, fields, query):
    """Get object by numeric id or exact
    and unique part of specified attrs (name, title, etc)."""
    try:
        pk = int(query)
    except ValueError:
        pass
    else:
        return cls.objects.get(pk=pk)
    obj = list(cls.objects.filter(reduce(op.or_, list((Q(**{'{}__icontains'.format(f): query}) for f in fields)))))
    if len(obj) > 1:
        raise cls.MultipleObjectsReturned(u'Unable to uniquely identify {} by provided criteria: {!r} (candidates: {})'.format(cls.__name__, query, ', '.join(it.imap(unicode, obj))))
    elif not len(obj):
        raise cls.DoesNotExist(u'Unable to find site by provided criteria: {!r}'.format(query))
    return obj[0]

def display(result, stream):
    """Intelligently print the result (or pass if result is None).

    :param result:
    :return: None"""
    if result is None:
        return
    elif isinstance(result, basestring):
        pass
    elif isinstance(result, collections.Mapping):
        result = u'\n'.join((u'%s=%s' % (k, v) for k, v in result.iteritems() if v is not None))
    elif isinstance(result, collections.Iterable):
        result = u'\n'.join((unicode(x) for x in result if x is not None))
    else:
        result = unicode(result)
    stream.write(result.encode('utf8'))
    stream.write('\n')

def safe_evaluate(command, glob, local):
    """Continue to attempt to execute the given command, importing objects which
    cause a NameError in the command

    :param command: command for eval
    :param glob: globals dict for eval
    :param local: locals dict for eval
    :return: command result"""
    while True:
        try:
            return eval(command, glob, local)
        except NameError as e:
            match = re.match("name '(.*)' is not defined", e.message)
            if not match:
                raise e
            try:
                exec('import %s' % (match.group(1),)) in glob
            except ImportError:
                raise e

def safe_int(value):
    """Tries to convert a value to int; returns 0 if conversion failed"""
    try:
        result = int(value)
        if result < 0:
            raise NegativeDurationError('Negative values in duration strings are not allowed!')
    except NegativeDurationError as exc:
        raise exc
    except (TypeError, ValueError):
        result = 0
    return result

def to_seconds(value, strict=True, force_int=True):
    """converts duration value to integer seconds

    strict=True (by default) raises StrictnessError if either hours,
    minutes or seconds in duration value exceed allowed values"""
    if isinstance(value, int):
        return value
    elif isinstance(value, timedelta):
        seconds = value.total_seconds()
        if force_int:
            seconds = int(round(seconds))
        return seconds
    elif isinstance(value, str):
        hours, minutes, seconds = _parse(value, strict)
    elif isinstance(value, tuple):
        check_tuple(value, strict)
        hours, minutes, seconds = value
    else:
        raise TypeError('Value %s (type %s) not supported' % (value, type(value).__name__))
    if not (hours or minutes or seconds):
        raise ValueError('No hours, minutes or seconds found')
    result = hours * 3600 + minutes * 60 + seconds
    return result

def to_timedelta(value, strict=True):
    """converts duration string to timedelta

    strict=True (by default) raises StrictnessError if either hours,
    minutes or seconds in duration string exceed allowed values"""
    if isinstance(value, int):
        return timedelta(seconds=value)
    elif isinstance(value, timedelta):
        return value
    elif isinstance(value, str):
        hours, minutes, seconds = _parse(value, strict)
    elif isinstance(value, tuple):
        check_tuple(value, strict)
        hours, minutes, seconds = value
    else:
        raise TypeError('Value %s (type %s) not supported' % (value, type(value).__name__))
    return timedelta(hours=hours, minutes=minutes, seconds=seconds)

def to_tuple(value, strict=True, force_int=True):
    """converts duration value to tuple of integers

    strict=True (by default) raises StrictnessError if either hours,
    minutes or seconds in duration value exceed allowed values"""
    if isinstance(value, int):
        seconds = value
        minutes, seconds = divmod(seconds, 60)
        hours, minutes = divmod(minutes, 60)
    elif isinstance(value, str):
        hours, minutes, seconds = _fix_tuple(_parse(value, strict))
    elif isinstance(value, tuple):
        check_tuple(value, strict)
        hours, minutes, seconds = _fix_tuple(value)
    elif isinstance(value, timedelta):
        seconds = value.total_seconds()
        if force_int:
            seconds = int(round(seconds))
        minutes, seconds = divmod(seconds, 60)
        hours, minutes = divmod(minutes, 60)
    return (hours, minutes, seconds)

def name_url(provider, cloud, method_name):
    """Get a URL for a method in a driver"""
    snake_parts = method_name.split('_')
    if len(snake_parts) <= 1:
        return False
    if snake_parts[0] == 'ex':
        extra = True
        method_name = method_name.replace('ex_', '', 1)
    else:
        extra = False
    snake_parts = method_name.split('_')
    if snake_parts[0] in get_sem_verbs:
        method = 'GET'
        for verb in get_sem_verbs:
            method_name = method_name.replace('%s_' % verb, '', 1)
    elif snake_parts[0] in delete_sem_verbs:
        method = 'DELETE'
    elif snake_parts[0] in put_sem_verbs:
        method = 'PUT'
    else:
        method = 'POST'
    uri = '/%s/%s/%s%s' % (provider, cloud, 'extensions/' if extra else '', method_name)
    return (method, uri)

def contains_frame(data):
    """Read the frame length from the start of `data` and check if the data is
    long enough to contain the entire frame."""
    if len(data) < 2:
        return False
    b2 = struct.unpack('!B', data[1])[0]
    payload_len = b2 & 127
    payload_start = 2
    if payload_len == 126:
        if len(data) > 4:
            payload_len = struct.unpack('!H', data[2:4])[0]
        payload_start = 4
    elif payload_len == 127:
        if len(data) > 12:
            payload_len = struct.unpack('!Q', data[4:12])[0]
        payload_start = 12
    return len(data) >= payload_len + payload_start

def mask(key, original):
    """Mask an octet string using the given masking key.
    The following masking algorithm is used, as defined in RFC 6455:

    for each octet:
        j = i MOD 4
        transformed-octet-i = original-octet-i XOR masking-key-octet-j"""
    if len(key) != 4:
        raise ValueError('invalid masking key "%s"' % key)
    key = map(ord, key)
    masked = bytearray(original)
    for i in xrange(len(masked)):
        masked[i] ^= key[i % 4]
    return masked

def _mic_required(target_info):
    """Checks the MsvAvFlags field of the supplied TargetInfo structure to determine in the MIC flags is set
    :param target_info: The TargetInfo structure to check
    :return: a boolean value indicating that the MIC flag is set"""
    if target_info is not None and target_info[TargetInfo.NTLMSSP_AV_FLAGS] is not None:
        flags = struct.unpack('<I', target_info[TargetInfo.NTLMSSP_AV_FLAGS][1])[0]
        return bool(flags & 2)

def prettyhtml(value, autoescape=None):
    """Clean (and optionally escape) passed html of unsafe tags and attributes."""
    value = html_cleaner(value)
    return escape(value) if autoescape and (not isinstance(value, SafeData)) else mark_safe(value)

def hash(value, chars=None):
    """Get N chars (default: all) of secure hash hexdigest of value."""
    value = hash_func(value).hexdigest()
    if chars:
        value = value[:chars]
    return mark_safe(value)

def _split_out_of_braces(s):
    """Generator to split comma seperated string, but not split commas inside
    curly braces.

    >>> list(_split_out_of_braces("py{26, 27}-django{15, 16}, py32"))
    >>>['py{26, 27}-django{15, 16}, py32']"""
    prev = 0
    for m in re.finditer('{[^{}]*}|\\s*,\\s*', s):
        if not m.group().startswith('{'):
            part = s[prev:m.start()]
            if part:
                yield s[prev:m.start()]
            prev = m.end()
    part = s[prev:]
    if part:
        yield part

def matches_factor_conditions(s, env):
    """"Returns True if py{33, 34} expanded is contained in env.name."""
    env_labels = set(env.name.split('-'))
    labels = set(bash_expand(s))
    return bool(labels & env_labels)

def _replace_match(m, env):
    """Given a match object, having matched something inside curly braces,
    replace the contents if matches one of the supported tox-substitutions."""
    s = m.group()[1:-1].strip()
    try:
        return getattr(env, s)
    except AttributeError:
        pass
    for r in [_replace_envvar, _replace_config, _replace_posargs]:
        try:
            return r(s, env)
        except ValueError:
            pass
    raise NotImplementedError('{%s} not understood in tox.ini file.' % s)

def _replace_envvar(s, _):
    """env:KEY or env:KEY:DEFAULT"""
    e = s.split(':')
    if len(e) > 3 or len(e) == 1 or e[0] != 'env':
        raise ValueError()
    elif len(e) == 2:
        return os.environ[e[1]]
    else:
        return os.environ.get(e[1], e[2])

def _replace_config(s, env):
    """[sectionname]optionname"""
    m = re.match('\\[(.*?)\\](.*)', s)
    if m:
        section, option = m.groups()
        expanded = env.config.get(section, option)
        return '\n'.join([expand_factor_conditions(e, env) for e in expanded.split('\n')])
    else:
        raise ValueError()

def _replace_posargs(s, env):
    """posargs:DEFAULT"""
    e = re.split('\\s*\\:\\s*', s)
    if e and e[0] == 'posargs':
        from ctox.main import positional_args
        return ' '.join(positional_args(env.options)) or (e[1] if len(e) > 1 else '')
    else:
        raise ValueError()

def vei_CoR_veX(X, C=None, R=None):
    """Args:
        X:  NxPxS tensor
        C:  CxC row covariance (if None: C set to I_PP)
        R:  NxN row covariance (if None: R set to I_NN)
    Returns:
        NxPxS tensor obtained as ve^{-1}((C \\kron R) ve(X))
        where ve(X) reshapes X as a NPxS matrix."""
    _X = X.transpose((0, 2, 1))
    if R is not None:
        RV = sp.tensordot(R, _X, (1, 0))
    else:
        RV = _X
    if C is not None:
        RV = sp.dot(RV, C.T)
    return RV.transpose((0, 2, 1))

def absolutify(url):
    """Takes a URL and prepends the SITE_URL"""
    site_url = getattr(settings, 'SITE_URL', False)
    if not site_url:
        protocol = settings.PROTOCOL
        hostname = settings.DOMAIN
        port = settings.PORT
        if (protocol, port) in (('https://', 443), ('http://', 80)):
            site_url = ''.join(map(str, (protocol, hostname)))
        else:
            site_url = ''.join(map(str, (protocol, hostname, ':', port)))
    return site_url + url

def check_array_or_list(input):
    """Return 1D ndarray, if input can be converted and elements are
    non-negative."""
    if type(input) != np.ndarray:
        if type(input) == list:
            output = np.array(input)
        else:
            raise TypeError('Expecting input type as ndarray or list.')
    else:
        output = input
    if output.ndim != 1:
        raise ValueError('Input array must have 1 dimension.')
    if np.sum(output < 0.0) > 0:
        raise ValueError('Input array values cannot be negative.')
    return output

def optimize_layout_handler(rule, handler):
    """Produce an "optimized" version of handler for the dispatcher to
    limit reference lookups."""
    def runner(walk, dispatcher, node):
        yield LayoutChunk(rule, handler, node)
    return runner

def t_NUMBER(t):
    """[0-9]+[KkMmGg]?"""
    exponents = {'G': 30, 'g': 30, 'M': 20, 'm': 20, 'K': 10, 'k': 10}
    if t.value[-1] in exponents:
        t.value = math.ldexp(int(t.value[:-1]), exponents[t.value[-1]])
    else:
        t.value = int(t.value)
    return t

def _missingExtraCheck(given, required, extraException, missingException):
    """If the L{sets<set>} C{required} and C{given} do not contain the same
    elements raise an exception describing how they are different.

    @param given: The L{set} of elements that was actually given.
    @param required: The L{set} of elements that must be given.

    @param extraException: An exception to raise if there are elements in
        C{given} that are not in C{required}.
    @param missingException: An exception to raise if there are elements in
        C{required} that are not in C{given}.

    @return: C{None}"""
    extra = given - required
    if extra:
        raise extraException(extra)
    missing = required - given
    if missing:
        raise missingException(missing)

def trivialInput(symbol):
    """Create a new L{IRichInput} implementation for the given input symbol.

    This creates a new type object and is intended to be used at module scope
    to define rich input types.  Generally, only one use per symbol should be
    required.  For example::

        Apple = trivialInput(Fruit.apple)

    @param symbol: A symbol from some state machine's input alphabet.

    @return: A new type object usable as a rich input for the given symbol.
    @rtype: L{type}"""
    return implementer(IRichInput)(type(symbol.name.title(), (FancyStrMixin, object), {'symbol': _symbol(symbol)}))

def minify(drop_semi=True):
    """Rules for minifying output.

    Arguments:

    drop_semi
        Drop semicolons whenever possible.  Note that if Dedent and
        OptionalNewline has a handler defined, it will stop final break
        statements from being resolved due to reliance on normalized
        resolution."""
    layout_handlers = {OpenBlock: layout_handler_openbrace, CloseBlock: layout_handler_closebrace, EndStatement: layout_handler_semicolon, Space: layout_handler_space_minimum, OptionalSpace: layout_handler_space_minimum, RequiredSpace: layout_handler_space_imply, (Space, OpenBlock): layout_handler_openbrace, (Space, EndStatement): layout_handler_semicolon, (OptionalSpace, EndStatement): layout_handler_semicolon}
    if drop_semi:
        layout_handlers.update({EndStatement: layout_handler_semicolon_optional, (OptionalSpace, EndStatement): layout_handler_semicolon_optional, (EndStatement, CloseBlock): layout_handler_closebrace, (EndStatement, Dedent): rule_handler_noop, ((OptionalSpace, EndStatement), CloseBlock): layout_handler_closebrace})
    def minify_rule():
        return {'layout_handlers': layout_handlers, 'deferrable_handlers': {Literal: deferrable_handler_literal_continuation}}
    return minify_rule

def indent(indent_str=None):
    """A complete, standalone indent ruleset.

    Arguments:

    indent_str
        The string used for indentation.  Defaults to None, which will
        defer the value used to the one provided by the Dispatcher."""
    def indentation_rule():
        inst = Indentator(indent_str)
        return {'layout_handlers': {OpenBlock: layout_handler_openbrace, CloseBlock: layout_handler_closebrace, EndStatement: layout_handler_semicolon, Space: layout_handler_space_imply, OptionalSpace: layout_handler_space_optional_pretty, RequiredSpace: layout_handler_space_imply, Indent: inst.layout_handler_indent, Dedent: inst.layout_handler_dedent, Newline: inst.layout_handler_newline, OptionalNewline: inst.layout_handler_newline_optional, (Space, OpenBlock): NotImplemented, (Space, EndStatement): layout_handler_semicolon, (OptionalSpace, EndStatement): layout_handler_semicolon, (Indent, Newline, Dedent): rule_handler_noop}}
    return indentation_rule

def getPyroleLikeAtoms(cycle):
    """cycle->return a dictionary of pyrole nitrogen-like atoms in
    a cycle or a molecule  The dictionary is keyed on the atom.handle"""
    result = {}
    for atom in cycle.atoms:
        lookup = (atom.symbol, atom.charge, atom.hcount, len(atom.bonds))
        if PyroleTable.get(lookup, 0):
            result[atom.handle] = atom
    return result

def addHydrogens(molecule, usedPyroles=None):
    """(molecule) -> add implicit hydrogens to a molecule.
    If the atom has specified valences and the atom must be
    charged then a Valence Error is raised"""
    for atom in molecule.atoms:
        if atom.has_explicit_hcount:
            atom.hcount = atom.explicit_hcount
            continue
        if atom.valences:
            for valence in atom.valences:
                hcount = max(0, int(valence - atom.sumBondOrders() + atom.charge))
                if hcount >= 0:
                    break
            else:
                if usedPyroles and (not usedPyroles.has_key(atom.handle)):
                    raise PinkyError('Valence error in atom %s' % molecule.atoms.index(atom))
                pass
            atom.hcount = hcount
    return molecule

def aromatize(molecule, usedPyroles=None):
    """(molecule, usedPyroles=None)->aromatize a molecular graph
    usedPyroles is a dictionary that holds the pyrole like
    atoms that are used in the conversion process.
    The following valence checker may need this information"""
    pyroleLike = getPyroleLikeAtoms(molecule)
    if usedPyroles is None:
        usedPyroles = {}
    cyclesToCheck = []
    for cycle in molecule.cycles:
        for atom in cycle.atoms:
            if not atom.aromatic:
                cyclesToCheck.append(cycle)
                break
        else:
            if not convert(cycle, pyroleLike, usedPyroles):
                raise PinkyError('Bad initial aromaticity')
    while 1:
        needToCheckAgain = 0
        _cyclesToCheck = []
        for cycle in cyclesToCheck:
            canAromatic = canBeAromatic(cycle, pyroleLike)
            if canAromatic == NEVER:
                pass
            elif canAromatic and convert(cycle, pyroleLike, usedPyroles):
                needToCheckAgain = 1
            else:
                _cyclesToCheck.append(cycle)
        cyclesToCheck = _cyclesToCheck
        if not needToCheckAgain:
            break
    molecule = fixBonds(molecule, pyroleLike)
    return addHydrogens(molecule, usedPyroles)

def safe_shell_out(cmd, verbose=False, **kwargs):
    """run cmd and return True if it went ok, False if something went wrong.

    Suppress all output."""
    try:
        with open(os.devnull, 'w') as fnull:
            with captured_output():
                check_output(cmd, stderr=fnull, **kwargs)
        return True
    except (CalledProcessError, OSError) as e:
        if verbose:
            cprint('    Error running command %s' % ' '.join(cmd), 'err')
            print(e.output)
        return False
    except Exception as e:
        return False

def prev_deps(env):
    """Naively gets the dependancies from the last time ctox was run."""
    if not os.path.isfile(env.envctoxfile):
        return []
    with open(env.envctoxfile) as f:
        return f.read().split()

def make_dist(toxinidir, toxdir, package):
    """zip up the package into the toxdir."""
    dist = os.path.join(toxdir, 'dist')
    success = safe_shell_out(['python', 'setup.py', 'sdist', '--quiet', '--formats=zip', '--dist-dir', dist], cwd=toxinidir)
    if success:
        return os.path.join(dist, package + '.zip')

def print_pretty_command(env, command):
    """This is a hack for prettier printing.

    Rather than "{envpython} foo.py" we print "python foo.py"."""
    cmd = abbr_cmd = command[0]
    if cmd.startswith(env.envbindir):
        abbr_cmd = os.path.relpath(cmd, env.envbindir)
        if abbr_cmd == '.':
            abbr_cmd = cmd
    command[0] = abbr_cmd
    print('(%s)$ %s' % (env.name, ' '.join(['"%s"' % c if ' ' in c else c for c in command])))
    command[0] = cmd
    return (abbr_cmd, cmd, command)

def _check_inputs(z, m):
    """Check inputs are arrays of same length or array and a scalar."""
    try:
        nz = len(z)
        z = np.array(z)
    except TypeError:
        z = np.array([z])
        nz = len(z)
    try:
        nm = len(m)
        m = np.array(m)
    except TypeError:
        m = np.array([m])
        nm = len(m)
    if (z < 0).any() or (m < 0).any():
        raise ValueError('z and m must be positive')
    if nz != nm and nz > 1 and (nm > 1):
        raise ValueError('z and m arrays must be either equal in length,                           OR of different length with one of length 1.')
    else:
        if type(z) != np.ndarray:
            z = np.array(z)
        if type(m) != np.ndarray:
            m = np.array(m)
        return (z, m)

def RawParserUnparserFactory(parser_name, parse_callable, *unparse_callables):
    """Produces a callable object that also has callable attributes that
    passes its first argument to the parent callable."""
    def build_unparse(f):
        @wraps(f)
        def unparse(self, source, *a, **kw):
            node = parse_callable(source)
            return f(node, *a, **kw)
        unparse.__doc__ = f.__doc__.replace('ast\n        The AST ', 'source\n        The source ')
        return unparse
    def build_parse(f):
        @wraps(f)
        def parse(self, source):
            return f(source)
        parse.__name__ = parser_name
        parse.__qualname__ = parser_name
        return parse
    callables = {f.__name__: build_unparse(f) for f in unparse_callables}
    callables['__call__'] = build_parse(parse_callable)
    callables['__module__'] = PKGNAME
    return type(parser_name, (object,), callables)()

def ParserUnparserFactory(module_name, *unparser_names):
    """Produce a new parser/unparser object from the names provided."""
    parse_callable = import_module(PKGNAME + '.parsers.' + module_name).parse
    unparser_module = import_module(PKGNAME + '.unparsers.' + module_name)
    return RawParserUnparserFactory(module_name, parse_callable, *[getattr(unparser_module, name) for name in unparser_names])

def fuzzy_c_means(points, num_centers, m=2.0, tol=0.0001, max_iter=100, verbose=False):
    """Uses Fuzzy C-Means to downsample `points`.
    m : aggregation parameter >1, larger implies smoother clusters
    Returns indices of downsampled points."""
    num_points = points.shape[0]
    if num_centers >= num_points:
        return np.arange(num_points)
    assn = np.random.random((points.shape[0], num_centers))
    for i in range(max_iter):
        w = assn ** m
        w /= w.sum(axis=0)
        centers = w.T.dot(points)
        d = pairwise_distances(points, centers)
        d **= 2.0 / (m - 1)
        np.maximum(d, 1e-10, out=d)
        new_assn = 1.0 / np.einsum('ik,ij->ik', d, 1.0 / d)
        change = np.linalg.norm(new_assn - assn)
        if verbose:
            print('At iteration %d: change = %g' % (i + 1, change))
        if change < tol:
            break
        assn = new_assn
    else:
        warnings.warn("fuzzy_c_means didn't converge in %d iterations" % max_iter)
    return d.argmin(axis=0)

def neighbor_graph(X, metric='euclidean', k=None, epsilon=None, weighting='none', precomputed=False):
    """Build a neighbor graph from pairwise distance information.

    X : two-dimensional array-like
        Shape must either be (num_pts, num_dims) or (num_pts, num_pts).
    k : int, maximum number of nearest neighbors
    epsilon : float, maximum distance to a neighbor
    metric : str, type of distance metric (see sklearn.metrics)
        When metric='precomputed', X is a symmetric distance matrix.
    weighting : str, one of {'binary', 'none'}
        When weighting='binary', all edge weights == 1."""
    if k is None and epsilon is None:
        raise ValueError('Must provide `k` or `epsilon`.')
    if weighting not in ('binary', 'none'):
        raise ValueError('Invalid weighting param: %r' % weighting)
    precomputed = precomputed or metric == 'precomputed'
    binary = weighting == 'binary'
    if not precomputed and epsilon is None:
        return _sparse_neighbor_graph(X, k, binary, metric)
    if precomputed:
        D = X
    else:
        D = pairwise_distances(X, metric=metric)
    return _slow_neighbor_graph(D, k, epsilon, binary)

def _sparse_neighbor_graph(X, k, binary=False, metric='l2'):
    """Construct a sparse adj matrix from a matrix of points (one per row).
    Non-zeros are unweighted/binary distance values, depending on the binary arg.
    Doesn't include self-edges."""
    knn = NearestNeighbors(n_neighbors=k, metric=metric).fit(X)
    mode = 'connectivity' if binary else 'distance'
    try:
        adj = knn.kneighbors_graph(None, mode=mode)
    except IndexError:
        if binary:
            adj = knn.kneighbors_graph(X, k + 1, mode=mode)
            adj.setdiag(0)
        else:
            adj = knn.kneighbors_graph(X, k, mode=mode)
    return Graph.from_adj_matrix(adj)

def show(db, encoding, no_limit, zip, case_insensitive):
    """Show .dbf file contents (rows)."""
    limit = 15
    if no_limit:
        limit = float('inf')
    with open_db(db, zip, encoding=encoding, case_sensitive=not case_insensitive) as dbf:
        for idx, row in enumerate(dbf, 1):
            click.secho('')
            for key, val in row._asdict().items():
                click.secho('  %s: %s' % (key, val))
            if idx == limit:
                click.secho('Note: Output is limited to %s rows. Use --no-limit option to bypass.' % limit, fg='red')
                break

def clone_repo(pkg, dest, repo, repo_dest, branch):
    """Clone the Playdoh repo into a custom path."""
    git(['clone', '--recursive', '-b', branch, repo, repo_dest])

def create_virtualenv(pkg, repo_dest, python):
    """Creates a virtualenv within which to install your new application."""
    workon_home = os.environ.get('WORKON_HOME')
    venv_cmd = find_executable('virtualenv')
    python_bin = find_executable(python)
    if not python_bin:
        raise EnvironmentError('%s is not installed or not available on your $PATH' % python)
    if workon_home:
        venv = os.path.join(workon_home, pkg)
    else:
        venv = os.path.join(repo_dest, '.virtualenv')
    if venv_cmd:
        if not verbose:
            log.info('Creating virtual environment in %r' % venv)
        args = ['--python', python_bin, venv]
        if not verbose:
            args.insert(0, '-q')
        subprocess.check_call([venv_cmd] + args)
    else:
        raise EnvironmentError('Could not locate the virtualenv. Install with pip install virtualenv.')
    return venv

def find_executable(name):
    """Finds the actual path to a named command.

    The first one on $PATH wins."""
    for pt in os.environ.get('PATH', '').split(':'):
        candidate = os.path.join(pt, name)
        if os.path.exists(candidate):
            return candidate

def log_cef(name, severity=logging.INFO, env=None, username='none', signature=None, **kwargs):
    """Wraps cef logging function so we don't need to pass in the config
    dictionary every time. See bug 707060. ``env`` can be either a request
    object or just the request.META dictionary."""
    cef_logger = commonware.log.getLogger('cef')
    c = {'product': settings.CEF_PRODUCT, 'vendor': settings.CEF_VENDOR, 'version': settings.CEF_VERSION, 'device_version': settings.CEF_DEVICE_VERSION}
    if isinstance(env, HttpRequest):
        r = env.META.copy()
    elif isinstance(env, dict):
        r = env
    else:
        r = {}
    c['environ'] = r
    c.update({'username': username, 'signature': signature, 'data': kwargs})
    cef_logger.log(severity, name, c)

def get_changedir(env):
    """changedir = {envdir}"""
    from ctox.subst import replace_braces
    changedir = _get_env_maybe(env, 'testenv', 'changedir')
    if changedir:
        return replace_braces(changedir, env)
    else:
        return env.toxinidir

def url(viewname, *args, **kwargs):
    """Helper for Django's ``reverse`` in templates."""
    return reverse(viewname, args=args, kwargs=kwargs)

def _urlencode(items):
    """A Unicode-safe URLencoder."""
    try:
        return urllib.urlencode(items)
    except UnicodeEncodeError:
        return urllib.urlencode([(k, smart_str(v)) for k, v in items])

def urlencode(txt):
    """Url encode a path."""
    if isinstance(txt, unicode):
        txt = txt.encode('utf-8')
    return urllib.quote_plus(txt)

def token_handler_str_default(token, dispatcher, node, subnode, sourcepath_stack=(None,)):
    """Standard token handler that will return the value, ignoring any
    tokens or strings that have been remapped."""
    if isinstance(token.pos, int):
        _, lineno, colno = node.getpos(subnode, token.pos)
    else:
        lineno, colno = (None, None)
    yield StreamFragment(subnode, lineno, colno, None, sourcepath_stack[-1])

def token_handler_unobfuscate(token, dispatcher, node, subnode, sourcepath_stack=(None,)):
    """A token handler that will resolve and return the original identifier
    value."""
    original = node.value if isinstance(node, Identifier) and node.value != subnode else None
    if isinstance(token.pos, int):
        _, lineno, colno = node.getpos(original or subnode, token.pos)
    else:
        lineno, colno = (None, None)
    yield StreamFragment(subnode, lineno, colno, original, sourcepath_stack[-1])

def p_commands_list(p):
    """commands : commands command"""
    p[0] = p[1]
    if p[2].RULE_IDENTIFIER == 'REQUIRE':
        if any((command.RULE_IDENTIFIER != 'REQUIRE' for command in p[0].commands)):
            print('REQUIRE command on line %d must come before any other non-REQUIRE commands' % p.lineno(2))
            raise SyntaxError
    elif p[2].RULE_IDENTIFIER in ('ELSIF', 'ELSE'):
        if p[0].commands[-1].RULE_IDENTIFIER not in ('IF', 'ELSIF'):
            print('ELSIF/ELSE command on line %d must follow an IF/ELSIF command' % p.lineno(2))
            raise SyntaxError
    p[0].commands.append(p[2])

def p_block(p):
    """block : '{' commands '}'"""
    if any((command.RULE_IDENTIFIER == 'REQUIRE' for command in p[2].commands)):
        print('REQUIRE command not allowed inside of a block (line %d)' % p.lineno(2))
        raise SyntaxError
    p[0] = p[2]

def p_arguments(p):
    """arguments : argumentlist
    | argumentlist test
    | argumentlist '(' testlist ')'"""
    p[0] = {'args': p[1]}
    if len(p) > 2:
        if p[2] == '(':
            p[0]['tests'] = p[3]
        else:
            p[0]['tests'] = [p[2]]

def encode_vlq(i):
    """Encode integer `i` into a VLQ encoded string."""
    raw = (-i << 1) + 1 if i < 0 else i << 1
    if raw < VLQ_MULTI_CHAR:
        return INT_B64[raw]
    result = []
    while raw:
        result.append(raw & VLQ_BASE_MASK | VLQ_CONT)
        raw = raw >> VLQ_SHIFT
    result[-1] &= VLQ_BASE_MASK
    return ''.join((INT_B64[i] for i in result))

def indent(indent_str=None):
    """An example indentation ruleset."""
    def indentation_rule():
        inst = Indentator(indent_str)
        return {'layout_handlers': {Indent: inst.layout_handler_indent, Dedent: inst.layout_handler_dedent, Newline: inst.layout_handler_newline, OptionalNewline: inst.layout_handler_newline_optional, OpenBlock: layout_handler_openbrace, CloseBlock: layout_handler_closebrace, EndStatement: layout_handler_semicolon}}
    return indentation_rule

def parse_input(s):
    """Parse the given input and intelligently transform it into an absolute,
    non-naive, timezone-aware datetime object for the UTC timezone.

    The input can be specified as a millisecond-precision UTC timestamp (or
    delta against Epoch), with or without a terminating 'L'. Alternatively, the
    input can be specified as a human-readable delta string with unit-separated
    segments, like '24d6h4m500' (24 days, 6 hours, 4 minutes and 500ms), as
    long as the segments are in descending unit span order."""
    if isinstance(s, six.integer_types):
        s = str(s)
    elif not isinstance(s, six.string_types):
        raise ValueError(s)
    original = s
    if s[-1:] == 'L':
        s = s[:-1]
    sign = {'-': -1, '=': 0, '+': 1}.get(s[0], None)
    if sign is not None:
        s = s[1:]
    ts = 0
    for unit in _SORTED_UNITS:
        pos = s.find(unit[0])
        if pos == 0:
            raise ValueError(original)
        elif pos > 0:
            if sign is None:
                sign = 1
            ts += int(s[:pos]) * __timedelta_millis(unit[1])
            s = s[min(len(s), pos + 1):]
    if s:
        ts += int(s)
    return date_from_utc_ts(ts) if not sign else utc() + sign * delta(milliseconds=ts)

def render_delta(d):
    """Render the given delta (in milliseconds) as a human-readable delta."""
    s = '' if d >= 0 else '-'
    d = abs(d)
    for unit in _SORTED_UNITS:
        span = __timedelta_millis(unit[1])
        if d >= span:
            count = int(d // span)
            s += '{0}{1}'.format(count, unit[0])
            d -= count * span
    if d or not s:
        s += str(d)
    return s

def render_date(date, tz=pytz.utc, fmt=_FULL_OUTPUT_FORMAT):
    """Format the given date for output. The local time render of the given
    date is done using the given timezone."""
    local = date.astimezone(tz)
    ts = __date_to_millisecond_ts(date)
    return fmt.format(ts=ts, utc=date.strftime(_DATE_FORMAT), millis=ts % 1000, utc_tz=date.strftime(_TZ_FORMAT), local=local.strftime(_DATE_FORMAT), local_tz=local.strftime(_TZ_FORMAT), delta=render_delta_from_now(date))

def smilin(smiles, transforms=[figueras.sssr, aromaticity.aromatize]):
    """(smiles)->molecule
    Convert a smiles string into a molecule representation"""
    builder = BuildMol()
    tokenize(smiles, builder)
    mol = builder.mol
    for transform in transforms:
        mol = transform(mol)
    for atom in mol.atoms:
        if not atom.has_explicit_hcount:
            atom.imp_hcount = atom.hcount - atom.explicit_hcount
    return mol

def reverse(viewname, urlconf=None, args=None, kwargs=None, prefix=None):
    """Wraps Django's reverse to prepend the correct locale."""
    prefixer = get_url_prefix()
    if prefixer:
        prefix = prefix or '/'
    url = django_reverse(viewname, urlconf, args, kwargs, prefix)
    if prefixer:
        url = prefixer.fix(url)
    return iri_to_uri(url)

def split_path(path_):
    """Split the requested path into (locale, path).

    locale will be empty if it isn't found."""
    path = path_.lstrip('/')
    first, _, rest = path.partition('/')
    lang = first.lower()
    if lang in settings.LANGUAGE_URL_MAP:
        return (settings.LANGUAGE_URL_MAP[lang], rest)
    else:
        supported = find_supported(first)
        if len(supported):
            return (supported[0], rest)
        else:
            return ('', path)

def regressOut(Y, X, return_b=False):
    """regresses out X from Y"""
    Xd = la.pinv(X)
    b = Xd.dot(Y)
    Y_out = Y - X.dot(b)
    if return_b:
        return (Y_out, b)
    else:
        return Y_out

def remove_dependent_cols(M, tol=1e-06, display=False):
    """Returns a matrix where dependent columsn have been removed"""
    R = la.qr(M, mode='r')[0][:M.shape[1], :]
    I = abs(R.diagonal()) > tol
    if sp.any(~I) and display:
        print('cols ' + str(sp.where(~I)[0]) + ' have been removed because linearly dependent on the others')
        R = M[:, I]
    else:
        R = M.copy()
    return R

def directed_graph(trajectories, k=5, verbose=False, pruning_thresh=0, return_coords=False):
    """Directed graph construction alg. from Johns & Mahadevan, ICML '07.
    trajectories: list of NxD arrays of ordered states"""
    X = np.vstack(trajectories)
    G = neighbor_graph(X, k=k)
    if pruning_thresh > 0:
        traj_len = map(len, trajectories)
        G = _prune_edges(G, X, traj_len, pruning_thresh, verbose=verbose)
    if return_coords:
        return (G, X)
    return G

def validate_settings(settings):
    """Raise an error in prod if we see any insecure settings.

    This used to warn during development but that was changed in
    71718bec324c2561da6cc3990c927ee87362f0f7"""
    from django.core.exceptions import ImproperlyConfigured
    if settings.SECRET_KEY == '':
        msg = 'settings.SECRET_KEY cannot be blank! Check your local settings'
        if not settings.DEBUG:
            raise ImproperlyConfigured(msg)
    if getattr(settings, 'SESSION_COOKIE_SECURE', None) is None:
        msg = 'settings.SESSION_COOKIE_SECURE should be set to True; otherwise, your session ids can be intercepted over HTTP!'
        if not settings.DEBUG:
            raise ImproperlyConfigured(msg)
    hmac = getattr(settings, 'HMAC_KEYS', {})
    if not len(hmac.keys()):
        msg = 'settings.HMAC_KEYS cannot be empty! Check your local settings'
        if not settings.DEBUG:
            raise ImproperlyConfigured(msg)

def cached(method):
    """this function is used as a decorator for caching"""
    _cache_attr_name = '_cache_' + method.__name__
    _bool_attr_name = '_cached_' + method.__name__
    def method_wrapper(self, *args, **kwargs):
        is_cached = getattr(self, _bool_attr_name)
        if not is_cached:
            result = method(self, *args, **kwargs)
            setattr(self, _cache_attr_name, result)
            setattr(self, _bool_attr_name, True)
        return getattr(self, '_cache_' + method.__name__)
    return method_wrapper

def cached_idxs(method):
    """this function is used as a decorator for caching"""
    def method_wrapper(self, *args, **kwargs):
        tail = '_'.join((str(idx) for idx in args))
        _cache_attr_name = '_cache_' + method.__name__ + '_' + tail
        _bool_attr_name = '_cached_' + method.__name__ + '_' + tail
        is_cached = getattr(self, _bool_attr_name)
        if not is_cached:
            result = method(self, *args, **kwargs)
            setattr(self, _cache_attr_name, result)
            setattr(self, _bool_attr_name, True)
        return getattr(self, _cache_attr_name)
    return method_wrapper

def validate_config(conf_dict):
    """Validate configuration.

    :param conf_dict: test configuration.
    :type conf_dict: {}
    :raise InvalidConfigurationError:"""
    if APPLICATIONS not in conf_dict.keys():
        raise InvalidConfigurationError('Missing application configuration.')
    if SEED_FILES not in conf_dict.keys():
        raise InvalidConfigurationError('Missing seed file configuration.')
    if RUNS not in conf_dict.keys():
        conf_dict[RUNS] = DEFAULT_RUNS
    if PROCESSES not in conf_dict.keys():
        conf_dict[PROCESSES] = DEFAULT_PROCESSES
    if PROCESSORS not in conf_dict.keys():
        conf_dict[PROCESSORS] = DEFAULT_PROCESSORS
    return

def main(arguments, toxinidir=None):
    """ctox: tox with conda."""
    try:
        import signal
        signal.signal(signal.SIGPIPE, signal.SIG_DFL)
    except AttributeError:
        pass
    try:
        import sys
        sys.exit(ctox(arguments, toxinidir))
    except CalledProcessError as c:
        print(c.output)
        return 1
    except NotImplementedError as e:
        gh = 'https://github.com/hayd/ctox/issues'
        from colorama import Style
        cprint(Style.BRIGHT + str(e), 'err')
        cprint('If this is a valid tox.ini substitution, please open an issue on\ngithub and request support: %s.' % gh, 'warn')
        return 1
    except KeyboardInterrupt:
        return 1

def positional_args(arguments):
    """"Generator for position arguments.

    Example
    -------
    >>> list(positional_args(["arg1", "arg2", "--kwarg"]))
    ["arg1", "arg2"]
    >>> list(positional_args(["--", "arg1", "--kwarg"]))
    ["arg1", "kwarg"]"""
    if arguments and arguments[0] == '--':
        for a in arguments[1:]:
            yield a
    else:
        for a in arguments:
            if a.startswith('-'):
                break
            yield a

def _main():
    """ctox: tox with conda"""
    from sys import argv
    arguments = argv[1:]
    toxinidir = os.getcwd()
    return main(arguments, toxinidir)

def jitEigh(A, maxTries=10, warning=True):
    """Do a Eigenvalue Decomposition with Jitter,

    works as jitChol"""
    warning = True
    jitter = 0
    i = 0
    while True:
        if jitter == 0:
            jitter = abs(SP.trace(A)) / A.shape[0] * 1e-06
            S, U = linalg.eigh(A)
        else:
            if warning:
                logging.error('Adding jitter of %f in jitEigh().' % jitter)
            S, U = linalg.eigh(A + jitter * SP.eye(A.shape[0]))
        if S.min() > 1e-10:
            return (S, U)
        if i < maxTries:
            jitter = jitter * 10
        i += 1
    raise linalg.LinAlgError('Matrix non positive definite, jitter of ' + str(jitter) + ' added but failed after ' + str(i) + ' trials.')

def _parse_fmt(fmt, color_key='colors', ls_key='linestyles', marker_key='marker'):
    """Modified from matplotlib's _process_plot_format function."""
    try:
        color = mcolors.colorConverter.to_rgb(fmt)
    except ValueError:
        pass
    else:
        if fmt not in mlines.lineMarkers:
            return {color_key: color}
    result = dict()
    if fmt.find('--') >= 0:
        result[ls_key] = '--'
        fmt = fmt.replace('--', '')
    if fmt.find('-.') >= 0:
        result[ls_key] = '-.'
        fmt = fmt.replace('-.', '')
    if fmt.find(' ') >= 0:
        result[ls_key] = 'None'
        fmt = fmt.replace(' ', '')
    for c in list(fmt):
        if c in mlines.lineStyles:
            if ls_key in result:
                raise ValueError('Illegal format string; two linestyle symbols')
            result[ls_key] = c
        elif c in mlines.lineMarkers:
            if marker_key in result:
                raise ValueError('Illegal format string; two marker symbols')
            result[marker_key] = c
        elif c in mcolors.colorConverter.colors:
            if color_key in result:
                raise ValueError('Illegal format string; two color symbols')
            result[color_key] = c
        else:
            raise ValueError('Unrecognized character %c in format string' % c)
    return result

def normalize_mapping_line(mapping_line, previous_source_column=0):
    """Often times the position will remain stable, such that the naive
    process will end up with many redundant values; this function will
    iterate through the line and remove all extra values."""
    if not mapping_line:
        return ([], previous_source_column)
    def regenerate(segment):
        if len(segment) == 5:
            result = (record[0], segment[1], segment[2], record[3], segment[4])
        else:
            result = (record[0], segment[1], segment[2], record[3])
        record[:] = [0, 0, 0, 0]
        return result
    record = [0, 0, 0, previous_source_column]
    result = []
    regen_next = True
    for segment in mapping_line:
        if not segment:
            continue
        record[0] += segment[0]
        if len(segment) == 1:
            if result and len(result[-1]) != 1:
                result.append((record[0],))
                record[0] = 0
                regen_next = True
            continue
        record[3] += segment[3]
        if len(segment) == 5 or regen_next or segment[1] or segment[2] or (record[0] != record[3]):
            result.append(regenerate(segment))
            regen_next = len(segment) == 5
    return (result, record[3])

def repr_compat(s):
    """Since Python 2 is annoying with unicode literals, and that we are
    enforcing the usage of unicode, this ensures the repr doesn't spew
    out the unicode literal prefix."""
    if unicode and isinstance(s, unicode):
        return repr(s)[1:]
    else:
        return repr(s)

def normrelpath(base, target):
    """This function takes the base and target arguments as paths, and
    returns an equivalent relative path from base to the target, if both
    provided paths are absolute."""
    if not all(map(isabs, [base, target])):
        return target
    return relpath(normpath(target), dirname(normpath(base)))

def permute_graph(G, order):
    """Reorder the graph's vertices, returning a copy of the input graph.
    order : integer array-like, some permutation of range(G.num_vertices())."""
    adj = G.matrix('dense')
    adj = adj[np.ix_(order, order)]
    return Graph.from_adj_matrix(adj)

def node_centroid_hill_climbing(G, relax=1, num_centerings=20, verbose=False):
    """Iterative reordering method based on alternating rounds of node-centering
    and hill-climbing search."""
    order = _breadth_first_order(G)
    for it in range(num_centerings):
        B = permute_graph(G, order).bandwidth()
        nc_order = _node_center(G, order, relax=relax)
        nc_B = permute_graph(G, nc_order).bandwidth()
        if nc_B < B:
            if verbose:
                print('post-center', B, nc_B)
            order = nc_order
        order = _hill_climbing(G, order, verbose=verbose)
    return permute_graph(G, order)

def annotate(*args, **kwargs):
    """Set function annotations (on Python2 and 3)."""
    def decorator(f):
        if not hasattr(f, '__annotations__'):
            f.__annotations__ = kwargs.copy()
        else:
            f.__annotations__.update(kwargs)
        if args:
            if len(args) != 1:
                raise ValueError('annotate supports only a single argument.')
            f.__annotations__['return'] = args[0]
        return f
    return decorator

def data(*argnames):
    """Designate an argument as a :class:`~data.Data` argument.

    Works by combining calls to :func:`~data.decorators.auto_instantiate` and
    :func:~data.decorators.annotate` on the named arguments.

    Example:

    .. code-block:: python

       class Foo(object):
           @data('bar')
           def meth(self, foo, bar):
               pass

    Inside ``meth``, ``bar`` will always be a :class:`~data.Data` instance
    constructed from the original value passed as ``bar``.

    :param argnames: List of parameter names that should be data arguments.
    :return: A decorator that converts the named arguments to
             :class:`~data.Data` instances."""
    if len(argnames) == 1 and callable(argnames[0]):
        return data()(argnames[0])
    def decorator(f):
        f = annotate(**dict(((argname, Data) for argname in argnames)))(f)
        f = auto_instantiate(Data)(f)
        return f
    return decorator

def _createAbsMagEstimationDict():
    """loads magnitude_estimation.dat which is from
    http://xoomer.virgilio.it/hrtrace/Sk.htm on 24/01/2014 and based on
    Schmid-Kaler (1982)

    creates a dict in the form [Classletter][ClassNumber][List of values for
    each L Class]"""
    magnitude_estimation_filepath = resource_filename(__name__, 'data/magnitude_estimation.dat')
    raw_table = np.loadtxt(magnitude_estimation_filepath, '|S5')
    absMagDict = {'O': {}, 'B': {}, 'A': {}, 'F': {}, 'G': {}, 'K': {}, 'M': {}}
    for row in raw_table:
        if sys.hexversion >= 50331648:
            starClass = row[0].decode('utf-8')
            absMagDict[starClass[0]][int(starClass[1])] = [float(x) for x in row[1:]]
        else:
            absMagDict[row[0][0]][int(row[0][1])] = [float(x) for x in row[1:]]
    LClassRef = {'V': 0, 'IV': 1, 'III': 2, 'II': 3, 'Ib': 4, 'Iab': 5, 'Ia': 6, 'Ia0': 7}
    return (absMagDict, LClassRef)

def estimateAbsoluteMagnitude(spectralType):
    """Uses the spectral type to lookup an approximate absolute magnitude for
    the star."""
    from .astroclasses import SpectralType
    specType = SpectralType(spectralType)
    if specType.classLetter == '':
        return np.nan
    elif specType.classNumber == '':
        specType.classNumber = 5
    if specType.lumType == '':
        specType.lumType = 'V'
    LNum = LClassRef[specType.lumType]
    classNum = specType.classNumber
    classLet = specType.classLetter
    try:
        return absMagDict[classLet][classNum][LNum]
    except (KeyError, IndexError):
        try:
            classLookup = absMagDict[classLet]
            values = np.array(list(classLookup.values()))[:, LNum]
            return np.interp(classNum, list(classLookup.keys()), values)
        except (KeyError, ValueError):
            return np.nan

def is_remote_allowed(remote):
    """Check if `remote` is allowed to make a CORS request."""
    if settings.debug:
        return True
    if not remote:
        return False
    for domain_pattern in settings.node['cors_whitelist_domains']:
        if domain_pattern.match(remote):
            return True
    return False

def fft(ts):
    """Perform a fast-fourier transform on a Trace"""
    t_step = ts.index[1] - ts.index[0]
    oc = np.abs(np.fft.fftshift(np.fft.fft(ts.values))) / len(ts.values)
    t = np.fft.fftshift(np.fft.fftfreq(len(oc), d=t_step))
    return Trace(oc, t)

def movingaverage(arr, window):
    """Calculates the moving average ("rolling mean") of an array
    of a certain window size."""
    m = np.ones(int(window)) / int(window)
    return scipy.ndimage.convolve1d(arr, m, axis=0, mode='reflect')

def dumps(asts):
    """Create a compressed string from an Trace."""
    d = asts.values.tostring()
    t = asts.index.values.astype(float).tostring()
    lt = struct.pack('<L', len(t))
    i = asts.name.encode('utf-8')
    li = struct.pack('<L', len(i))
    try:
        return buffer(zlib.compress(li + lt + i + t + d))
    except NameError:
        return zlib.compress(li + lt + i + t + d)

def ts_func(f):
    """This wraps a function that would normally only accept an array
    and allows it to operate on a DataFrame. Useful for applying
    numpy functions to DataFrames."""
    def wrap_func(df, *args):
        return Chromatogram(f(df.values, *args), df.index, df.columns)
    return wrap_func

def find_spectrum_match(spec, spec_lib, method='euclidian'):
    """Find spectrum in spec_lib most similar to spec."""
    spec = spec / np.max(spec)
    if method == 'dot':
        d1 = (spec_lib * lil_matrix(spec).T).sum(axis=1).A ** 2
        d2 = np.sum(spec ** 2) * spec_lib.multiply(spec_lib).sum(axis=1).A
        dist = d1 / d2
    elif method == 'euclidian':
        st_spc = dia_matrix((spec, [0]), shape=(len(spec), len(spec)))
        dist_sp = spec_lib.multiply(spec_lib) - 2 * spec_lib.dot(st_spc)
        dist = dist_sp.sum(axis=1).A + np.sum(spec ** 2)
    return (dist.argmin(), dist.min())

def get_seconds(value, scale):
    """Convert time scale dict to seconds

    Given a dictionary with keys for scale and value, convert
    value into seconds based on scale."""
    scales = {'seconds': lambda x: x, 'minutes': lambda x: x * 60, 'hours': lambda x: x * 60 * 60, 'days': lambda x: x * 60 * 60 * 24, 'weeks': lambda x: x * 60 * 60 * 24 * 7, 'months': lambda x: x * 60 * 60 * 24 * 30, 'years': lambda x: x * 60 * 60 * 24 * 365}
    return scales[scale](value)

