def read_multireg_file(f, title=None):
    """Some REG files have multiple "sections" with different data.
    This parses each chunk out of such a file (e.g. LCDIAG.REG)"""
    f.seek(38)
    nparts = struct.unpack('<H', f.read(2))[0]
    foff = 45
    if title is None:
        data = []
        for _ in range(nparts):
            d = read_reg_file(f, foff)
            data.append(d)
            foff = f.tell() + 1
    else:
        for _ in range(nparts):
            d = read_reg_file(f, foff)
            if d.get('Title') == title:
                data = d
                break
            foff = f.tell() + 1
        else:
            data = {}
    return data

def t_to_min(x):
    """Convert XML 'xs: duration type' to decimal minutes, e.g.:
    t_to_min('PT1H2M30S') == 62.5"""
    g = re.match('PT(?:(.*)H)?(?:(.*)M)?(?:(.*)S)?', x).groups()
    return sum((0 if g[i] is None else float(g[i]) * 60.0 ** (1 - i) for i in range(3)))

def dynamic(name: str, expression: Union[type, Callable[[Type[Any]], type]]) -> Callable[[Callable[..., Any]], Callable[..., Any]]:
    """:param name:
    :param expression: a subclass of ``type`` or a callable in the format ``(owner: Type[Any]) -> type``.
    :return:"""
    def decorator(func):
        if not hasattr(func, '__dynamic__'):
            func.__dynamic__ = {name: expression}
        else:
            func.__dynamic__[name] = expression
        return func
    return decorator

def _slice_idxs(df, twin=None):
    """Returns a slice of the incoming array filtered between
    the two times specified. Assumes the array is the same
    length as self.data. Acts in the time() and trace() functions."""
    if twin is None:
        return (0, df.shape[0])
    tme = df.index
    if twin[0] is None:
        st_idx = 0
    else:
        st_idx = np.abs(tme - twin[0]).argmin()
    if twin[1] is None:
        en_idx = df.shape[0]
    else:
        en_idx = np.abs(tme - twin[1]).argmin() + 1
    return (st_idx, en_idx)

def index(environment, start_response, headers):
    """Return the status of this Kronos instance + its backends>
    Doesn't expect any URL parameters."""
    response = {'service': 'kronosd', 'version': kronos.__version__, 'id': settings.node['id'], 'storage': {}, SUCCESS_FIELD: True}
    for name, backend in router.get_backends():
        response['storage'][name] = {'alive': backend.is_alive(), 'backend': settings.storage[name]['backend']}
    start_response('200 OK', headers)
    return response

def get_streams(environment, start_response, headers):
    """List all streams that can be read from Kronos right now.
    POST body should contain a JSON encoded version of:
      { namespace: namespace_name (optional)
      }"""
    start_response('200 OK', headers)
    streams_seen_so_far = set()
    namespace = environment['json'].get('namespace', settings.default_namespace)
    for prefix, backend in router.get_read_backends(namespace):
        for stream in backend.streams(namespace):
            if stream.startswith(prefix) and stream not in streams_seen_so_far:
                streams_seen_so_far.add(stream)
                yield '{0}\r\n'.format(stream)
    yield ''

def infer_schema(environment, start_response, headers):
    """Return the inferred schema of the requested stream.
    POST body should contain a JSON encoded version of:
      { stream: stream_name,
        namespace: namespace_name (optional)
      }"""
    stream = environment['json']['stream']
    namespace = environment['json'].get('namespace') or settings.default_namespace
    start_response('200 OK', headers)
    schema = _infer_schema(namespace, stream)
    response = {'stream': stream, 'namespace': namespace, 'schema': schema, SUCCESS_FIELD: True}
    return response

def istr_type(istr):
    """Given an "ion" specification, determine its "type", e.g. 1D, Events, etc."""
    data = set((i.rstrip('0123456789') for i in tokens(istr)))
    has_events = not data.isdisjoint(istr_type_evts)
    has_2d = not data.isdisjoint(istr_type_2d)
    has_1d = data.difference(istr_type_evts).difference(istr_type_2d) != set()
    if has_events and (not (has_1d or has_2d)):
        return 'events'
    elif has_1d and (not has_events):
        return '1d'
    elif has_2d and (not (has_events or has_1d)):
        return '2d'
    else:
        return None

def is_parans_exp(istr):
    '''Determines if an expression is a valid function "call"'''
    fxn = istr.split('(')[0]
    if not fxn.isalnum() and fxn != '(' or istr[-1] != ')':
        return False
    plevel = 1
    for c in '('.join(istr[:-1].split('(')[1:]):
        if c == '(':
            plevel += 1
        elif c == ')':
            plevel -= 1
        if plevel == 0:
            return False
    return True

def _validate_and_get_value(options, options_name, key, _type):
    """Check that `options` has a value for `key` with type
    `_type`. Return that value. `options_name` is a string representing a
    human-readable name for `options` to be used when printing errors."""
    if isinstance(options, dict):
        has = lambda k: k in options
        get = lambda k: options[k]
    elif isinstance(options, object):
        has = lambda k: hasattr(options, k)
        get = lambda k: getattr(options, k)
    else:
        raise ImproperlyConfigured('`{}` must be a dictionary-like object.'.format(options_name))
    if not has(key):
        raise ImproperlyConfigured('`{}` must be specified in `{}`'.format(key, options_name))
    value = get(key)
    if not isinstance(value, _type):
        raise ImproperlyConfigured('`{}` in `{}` must be a {}'.format(key, options_name, repr(_type)))
    return value

def validate_event_and_assign_id(event):
    """Ensure that the event has a valid time. Assign a random UUID based on the
    event time."""
    event_time = event.get(TIMESTAMP_FIELD)
    if event_time is None:
        event[TIMESTAMP_FIELD] = event_time = epoch_time_to_kronos_time(time.time())
    elif type(event_time) not in (int, long):
        raise InvalidEventTime(event_time)
    _id = uuid_from_kronos_time(event_time)
    event[ID_FIELD] = str(_id)
    return (_id, event)

def validate_stream(stream):
    """Check that the stream name is well-formed."""
    if not STREAM_REGEX.match(stream) or len(stream) > MAX_STREAM_LENGTH:
        raise InvalidStreamName(stream)

def validate_storage_settings(storage_class, settings):
    """Given a `storage_class` and a dictionary of `settings` to initialize it,
    this method verifies that all the settings are valid."""
    if not isinstance(settings, dict):
        raise ImproperlyConfigured('{}: storage class settings must be a dict'.format(storage_class))
    if not hasattr(storage_class, 'SETTINGS_VALIDATORS'):
        raise NotImplementedError('{}: storage class must define `SETTINGS_VALIDATORS`'.format(storage_class))
    settings_validators = getattr(storage_class, 'SETTINGS_VALIDATORS')
    settings = settings.copy()
    settings.pop('backend', None)
    invalid_settings = set(settings.keys()) - set(settings_validators.keys())
    if invalid_settings:
        raise ImproperlyConfigured('{}: invalid settings: {}'.format(storage_class, invalid_settings))
    for setting, value in settings.iteritems():
        if not settings_validators[setting](value):
            raise ImproperlyConfigured('{}: invalid value for {}'.format(storage_class, setting))

def planetMassType(mass):
    """Returns the planet masstype given the mass and using planetAssumptions['massType']
    """
    if mass is np.nan:
        return None
    for massLimit, massType in planetAssumptions['massType']:
        if mass < massLimit:
            return massType

def planetRadiusType(radius):
    """Returns the planet radiustype given the mass and using planetAssumptions['radiusType']
    """
    if radius is np.nan:
        return None
    for radiusLimit, radiusType in planetAssumptions['radiusType']:
        if radius < radiusLimit:
            return radiusType

def planetType(temperature, mass, radius):
    """Returns the planet type as 'temperatureType massType'
    """
    if mass is not np.nan:
        sizeType = planetMassType(mass)
    elif radius is not np.nan:
        sizeType = planetRadiusType(radius)
    else:
        return None
    return '{0} {1}'.format(planetTempType(temperature), sizeType)

def is_equal_strings_ignore_case(first, second):
    """The function compares strings ignoring case"""
    if first and second:
        return first.upper() == second.upper()
    else:
        return not (first or second)

def parse_c_serialized(f):
    """Reads in a binary file created by a C++ serializer (prob. MFC?)
    and returns tuples of (header name, data following the header).
    These are used by Thermo for *.CF and *.DXF files and by Agilent
    for new-style *.REG files."""
    f.seek(0)
    try:
        p_rec_type = None
        while True:
            rec_off = f.tell()
            while True:
                if f.read(2) == b'\xff\xff':
                    h = struct.unpack('<HH', f.read(4))
                    if h[1] < 64 and h[1] != 0:
                        rec_type = f.read(h[1])
                        if rec_type[0] == 67:
                            break
                if f.read(1) == b'':
                    raise EOFError
                f.seek(f.tell() - 2)
            if p_rec_type is not None:
                rec_len = f.tell() - 6 - len(rec_type) - rec_off
                f.seek(rec_off)
                yield (p_rec_type, f.read(rec_len))
                f.seek(f.tell() + 6 + len(rec_type))
            p_rec_type = rec_type
    except EOFError:
        rec_len = f.tell() - 6 - len(rec_type) - rec_off
        f.seek(rec_off)
        yield (p_rec_type, f.read(rec_len))

def peak_model(f):
    """Given a function that models a peak, add scale and location arguments to

    For all functions, v is vertical offset, h is height
    x is horizontal offset (1st moment), w is width (2nd moment),
    s is skewness (3rd moment), e is excess (4th moment)"""
    @wraps(f)
    def wrapped_f(t, **kw):
        def_vals = {'v': 0.0, 'h': 1.0, 'x': 0.0, 'w': 1.0, 's': 1.1, 'e': 1.0}
        for v in def_vals:
            if v not in kw:
                kw[v] = def_vals[v]
        anames, _, _, _ = inspect.getargspec(f)
        fkw = dict([(arg, kw[arg]) for arg in anames if arg in kw])
        ta = t
        if 'x' not in anames:
            ta = ta - kw['x']
        if 'w' not in anames:
            ta = ta / kw['w']
        mod = f(ta, **fkw)
        mod = f(ta + ta[mod.argmax()], **fkw)
        return kw['v'] + kw['h'] / max(mod) * mod
    args = set(['v', 'h', 'x', 'w'])
    anames, _, _, _ = inspect.getargspec(f)
    wrapped_f._peakargs = list(args.union([a for a in anames if a not in ('t', 'r')]))
    return wrapped_f

def _createMagConversionDict():
    """loads magnitude_conversion.dat which is table A% 1995ApJS..101..117K
    """
    magnitude_conversion_filepath = resource_stream(__name__, 'data/magnitude_conversion.dat')
    raw_table = np.loadtxt(magnitude_conversion_filepath, '|S5')
    magDict = {}
    for row in raw_table:
        if sys.hexversion >= 50331648:
            starClass = row[1].decode('utf-8')
            tableData = [x.decode('utf-8') for x in row[3:]]
        else:
            starClass = row[1]
            tableData = row[3:]
        magDict[starClass] = tableData
    return magDict

