def find_build_dir(path, build='_build'):
    """try to guess the build folder's location"""
    path = os.path.abspath(os.path.expanduser(path))
    contents = os.listdir(path)
    filtered_contents = [directory for directory in contents if os.path.isdir(os.path.join(path, directory))]
    if build in filtered_contents:
        return os.path.join(path, build)
    elif path == os.path.realpath('/'):
        return None
    else:
        return find_build_dir('{0}/..'.format(path), build)

def _get_windows(peak_list):
    """Given a list of peaks, bin them into windows."""
    win_list = []
    for t0, t1, hints in peak_list:
        p_w = (t0, t1)
        for w in win_list:
            if p_w[0] <= w[0][1] and p_w[1] >= w[0][0]:
                w[0] = (min(p_w[0], w[0][0]), max(p_w[1], w[0][1]))
                w[1].append((t0, t1, hints))
                break
        else:
            win_list.append([p_w, [(t0, t1, hints)]])
    return win_list

def _date_trunc(value, timeframe):
    """A date flooring function.

    Returns the closest datetime to the current one that aligns to timeframe.
    For example, _date_trunc('2014-08-13 05:00:00', DateTrunc.Unit.MONTH)
    will return a Kronos time representing 2014-08-01 00:00:00."""
    if isinstance(value, types.StringTypes):
        value = parse(value)
        return_as_str = True
    else:
        value = kronos_time_to_datetime(value)
        return_as_str = False
    timeframes = {DateTrunc.Unit.SECOND: lambda dt: dt - timedelta(microseconds=dt.microsecond), DateTrunc.Unit.MINUTE: lambda dt: dt - timedelta(seconds=dt.second, microseconds=dt.microsecond), DateTrunc.Unit.HOUR: lambda dt: dt - timedelta(minutes=dt.minute, seconds=dt.second, microseconds=dt.microsecond), DateTrunc.Unit.DAY: lambda dt: dt.date(), DateTrunc.Unit.WEEK: lambda dt: dt.date() - timedelta(days=dt.weekday()), DateTrunc.Unit.MONTH: lambda dt: datetime(dt.year, dt.month, 1), DateTrunc.Unit.YEAR: lambda dt: datetime(dt.year, 1, 1)}
    value = timeframes[timeframe](value)
    if return_as_str:
        return value.isoformat()
    return datetime_to_kronos_time(value)

def _date_part(value, part):
    """Returns a portion of a datetime.

    Returns the portion of a datetime represented by timeframe.
    For example, _date_part('2014-08-13 05:00:00', DatePart.Unit.WEEK_DAY)
    will return 2, for Wednesday."""
    if isinstance(value, types.StringTypes):
        value = parse(value)
    else:
        value = kronos_time_to_datetime(value)
    parts = {DatePart.Unit.SECOND: lambda dt: dt.second, DatePart.Unit.MINUTE: lambda dt: dt.minute, DatePart.Unit.HOUR: lambda dt: dt.hour, DatePart.Unit.DAY: lambda dt: dt.day, DatePart.Unit.MONTH: lambda dt: dt.month, DatePart.Unit.YEAR: lambda dt: dt.year, DatePart.Unit.WEEK_DAY: lambda dt: dt.weekday()}
    result = parts[part](value)
    return result

def cancel():
    """HTTP endpoint for canceling tasks

    If an active task is cancelled, an inactive task with the same code and the
    smallest interval will be activated if it exists."""
    task_id = request.form['id']
    task = Task.query.get(task_id)
    if not task:
        return json.dumps({'status': 'success', 'id': None})
    task.delete()
    if task.active:
        current_app.scheduler.cancel(task_id)
        code = task.code
        other_task = Task.query.filter_by(code=code).order_by('interval').first()
        if other_task:
            other_task.active = True
            other_task.save()
            current_app.scheduler.schedule({'id': other_task.id, 'code': other_task.code, 'interval': other_task.interval})
    return json.dumps({'status': 'success', 'id': task_id})

def leagues_by_summoner_ids(summoner_ids, queue=Queue.RANKED_SOLO_5x5):
    """Takes in a list of players ids and divide them by league tiers.
    :param summoner_ids: a list containing the ids of players
    :param queue: the queue to consider
    :return: a dictionary tier -> set of ids"""
    summoners_league = defaultdict(set)
    for start, end in _slice(0, len(summoner_ids), 10):
        for id, leagues in get_league_entries_by_summoner(summoner_ids[start:end]).items():
            for league in leagues:
                if Queue[league.queue] == queue:
                    summoners_league[Tier.parse(league.tier)].add(int(id))
    return summoners_league

