def _sortValueIntoGroup(groupKeys, groupLimits, value):
    """returns the Key of the group a value belongs to
    :param groupKeys: a list/tuple of keys ie ['1-3', '3-5', '5-8', '8-10', '10+']
    :param groupLimits: a list of the limits for the group [1,3,5,8,10,float('inf')] note the first value is an absolute
    minimum and the last an absolute maximum. You can therefore use float('inf')
    :param value:
    :return:"""
    if not len(groupKeys) == len(groupLimits) - 1:
        raise ValueError('len(groupKeys) must equal len(grouplimits)-1 got \nkeys:{0} \nlimits:{1}'.format(groupKeys, groupLimits))
    if math.isnan(value):
        return 'Uncertain'
    keyIndex = None
    if value == groupLimits[0]:
        keyIndex = 1
    elif value == groupLimits[-1]:
        keyIndex = len(groupLimits) - 1
    else:
        for i, limit in enumerate(groupLimits):
            if value < limit:
                keyIndex = i
                break
    if keyIndex == 0:
        raise BelowLimitsError('Value {0} below limit {1}'.format(value, groupLimits[0]))
    if keyIndex is None:
        raise AboveLimitsError('Value {0} above limit {1}'.format(value, groupLimits[-1]))
    return groupKeys[keyIndex - 1]

def defaults(f, self, *args, **kwargs):
    """For ``PARAMETERS`` keys, replace None ``kwargs`` with ``self`` attr values.

    Should be applied on the top of any decorator stack so other decorators see
    the "right" kwargs.

    Will also apply transformations found in ``TRANSFORMS``."""
    for name, data in PARAMETERS.iteritems():
        kwargs[name] = kwargs.get(name) or getattr(self, name)
        if 'transform' in data:
            kwargs[name] = data['transform'](kwargs[name])
    return f(self, *args, **kwargs)

def requires(*params):
    """Raise ValueError if any ``params`` are omitted from the decorated kwargs.

    None values are considered omissions.

    Example usage on an AWS() method:

        @requires('zone', 'security_groups')
        def my_aws_method(self, custom_args, **kwargs):
            # We'll only get here if 'kwargs' contained non-None values for
            # both 'zone' and 'security_groups'."""
    def requires(f, self, *args, **kwargs):
        missing = filter(lambda x: kwargs.get(x) is None, params)
        if missing:
            msgs = ', '.join([PARAMETERS[x]['msg'] for x in missing])
            raise ValueError('Missing the following parameters: %s' % msgs)
        return f(self, *args, **kwargs)
    return decorator(requires)

def get_system_config_directory():
    """Return platform specific config directory."""
    if platform.system().lower() == 'windows':
        _cfg_directory = Path(os.getenv('APPDATA') or '~')
    elif platform.system().lower() == 'darwin':
        _cfg_directory = Path('~', 'Library', 'Preferences')
    else:
        _cfg_directory = Path(os.getenv('XDG_CONFIG_HOME') or '~/.config')
    logger.debug('Fetching configt directory for {}.'.format(platform.system()))
    return _cfg_directory.joinpath(Path('mayalauncher/.config'))

def get_version_exec_mapping_from_path(path):
    """Find valid application version from given path object and return
    a mapping of version, executable."""
    version_executable = {}
    logger.debug('Getting exes from path: {}'.format(path))
    for sub_dir in path.iterdir():
        if not sub_dir.name.startswith(APPLICATION_NAME):
            continue
        release = sub_dir.name.split(APPLICATION_NAME)[-1]
        executable = Path(sub_dir, 'bin').glob('maya.exe').next()
        version_executable[release] = str(executable)
    logger.debug('Found exes for: {}'.format(version_executable.keys()))
    return version_executable

def find_applications_on_system():
    """Collect maya version from Autodesk PATH if exists, else try looking
    for custom executable paths from config file."""
    path_env = os.getenv('PATH').split(os.pathsep)
    versions = {}
    for each in path_env:
        path = Path(os.path.expandvars(each))
        if not path.exists():
            continue
        if path.name.endswith(DEVELOPER_NAME):
            if not path.exists():
                continue
            versions.update(get_version_exec_mapping_from_path(path))
    return versions

def build_config(config_file=get_system_config_directory()):
    """Construct the config object from necessary elements."""
    config = Config(config_file, allow_no_value=True)
    application_versions = find_applications_on_system()
    for item in application_versions.iteritems():
        if not config.has_option(Config.EXECUTABLES, item[0]):
            config.set(Config.EXECUTABLES, item[0], item[1])
    return config

def get_environment_paths(config, env):
    """Get environment paths from given environment variable."""
    if env is None:
        return config.get(Config.DEFAULTS, 'environment')
    if config.has_option(Config.ENVIRONMENTS, env):
        env = config.get(Config.ENVIRONMENTS, env).replace(' ', '').split(';')
    else:
        env = os.getenv(env)
        if env:
            env = env.split(os.pathsep)
    return [i for i in env if i]

def build_maya_environment(config, env=None, arg_paths=None):
    """Construct maya environment."""
    maya_env = MayaEnvironment()
    maya_env.exclude_pattern = config.get_list(Config.PATTERNS, 'exclude')
    maya_env.icon_extensions = config.get_list(Config.PATTERNS, 'icon_ext')
    env = get_environment_paths(config, env)
    if not env and arg_paths is None:
        return logger.info('Using maya factory environment setup.')
    logger.debug('Launching with addon paths: {}'.format(arg_paths))
    logger.debug('Launching with environment paths: {}'.format(env))
    if arg_paths:
        arg_paths = arg_paths.split(' ')
    for directory in flatten_combine_lists(env, arg_paths or ''):
        maya_env.traverse_path_for_valid_application_paths(directory)
    return maya_env

def launch(exec_, args):
    """Launches application."""
    if not exec_:
        raise RuntimeError('Mayalauncher could not find a maya executable, please specifya path in the config file (-e) or add the {} directory locationto your PATH system environment.'.format(DEVELOPER_NAME))
    if args.debug:
        return
    watched = WatchFile()
    cmd = [exec_] if args.file is None else [exec_, args.file]
    cmd.extend(['-hideConsole', '-log', watched.path])
    if args.debug:
        cmd.append('-noAutoloadPlugins')
    maya = subprocess.Popen(cmd)
    while True:
        time.sleep(1)
        maya.poll()
        watched.check()
        if maya.returncode is not None:
            if not maya.returncode == 0:
                maya = subprocess.Popen(cmd)
            else:
                watched.stop()
                break

def token_protected_endpoint(function):
    """Requires valid auth_token in POST to access

    An auth_token is built by sending a dictionary built from a
    Werkzeug.Request.form to the scheduler.auth.create_token function."""
    @wraps(function)
    def decorated(*args, **kwargs):
        auth_token = request.form.get('auth_token')
        if not auth_token:
            return json.dumps({'status': 'fail', 'reason': 'You must provide an auth_token'})
        data = dict(request.form)
        del data['auth_token']
        correct_token = create_token(current_app.config['SECRET_KEY'], data)
        if _compare_digest(auth_token, correct_token):
            return function(*args, **kwargs)
        else:
            return json.dumps({'status': 'fail', 'reason': 'Incorrect auth_token'})
    return decorated

def molmz(df, noise=10000):
    """The mz of the molecular ion."""
    d = ((df.values > noise) * df.columns).max(axis=1)
    return Trace(d, df.index, name='molmz')

def basemz(df):
    """The mz of the most abundant ion."""
    d = np.array(df.columns)[df.values.argmax(axis=1)]
    return Trace(d, df.index, name='basemz')

def tfclasses():
    """A mapping of mimetypes to every class for reading data files."""
    classes = {}
    mydir = op.dirname(op.abspath(inspect.getfile(get_mimetype)))
    tfcls = {"<class 'aston.tracefile.TraceFile'>", "<class 'aston.tracefile.ScanListFile'>"}
    for filename in glob(op.join(mydir, '*.py')):
        name = op.splitext(op.basename(filename))[0]
        module = import_module('aston.tracefile.' + name)
        for clsname in dir(module):
            cls = getattr(module, clsname)
            if hasattr(cls, '__base__'):
                if str(cls.__base__) in tfcls:
                    classes[cls.mime] = cls
    return classes

def guess_initc(ts, f, rts=[]):
    """ts - An AstonSeries that's being fitted with peaks
    f - The functional form of the peaks (e.g. gaussian)
    rts - peak maxima to fit; each number corresponds to one peak"""
    def find_side(y, loc=None):
        if loc is None:
            loc = y.argmax()
        ddy = np.diff(np.diff(y))
        lft_loc, rgt_loc = (loc - 2, loc + 1)
        while rgt_loc >= 0 and rgt_loc < len(ddy):
            if ddy[rgt_loc] < ddy[rgt_loc - 1]:
                break
            rgt_loc += 1
        while lft_loc >= 0 and lft_loc < len(ddy):
            if ddy[lft_loc] < ddy[lft_loc + 1]:
                break
            lft_loc -= 1
        return (lft_loc + 1, rgt_loc + 1)
    all_params = []
    for rt in rts:
        peak_params = {'x': rt}
        top_idx = np.abs(ts.index - rt).argmin()
        side_idx = find_side(ts.values, top_idx)
        peak_params['h'] = ts.values[top_idx]
        peak_params['w'] = ts.index[side_idx[1]] - ts.index[side_idx[0]]
        peak_params['s'] = 1.1
        peak_params['e'] = 1.0
        peak_params['a'] = 1.0
        all_params.append(peak_params)
    return all_params

def execute_greenlet_async(func, *args, **kwargs):
    """Executes `func` in a separate greenlet in the same process. Memory and other
    resources are available (e.g. TCP connections etc.) `args` and `kwargs` are
    passed to `func`."""
    global _GREENLET_EXECUTOR
    if _GREENLET_EXECUTOR is None:
        _GREENLET_EXECUTOR = GreenletExecutor(num_greenlets=settings.node.greenlet_pool_size)
    return _GREENLET_EXECUTOR.submit(func, *args, **kwargs)

def execute_process_async(func, *args, **kwargs):
    """Executes `func` in a separate process. Memory and other resources are not
    available. This gives true concurrency at the cost of losing access to
    these resources. `args` and `kwargs` are"""
    global _GIPC_EXECUTOR
    if _GIPC_EXECUTOR is None:
        _GIPC_EXECUTOR = GIPCExecutor(num_procs=settings.node.gipc_pool_size, num_greenlets=settings.node.greenlet_pool_size)
    return _GIPC_EXECUTOR.submit(func, *args, **kwargs)

def hook(name=None, priority=-1):
    """Decorator"""
    def _hook(hook_func):
        return register_hook(name, hook_func=hook_func, priority=priority)
    return _hook

def _doc2vec_doc_stream(paths, n, tokenizer=word_tokenize, sentences=True):
    """Generator to feed sentences to the dov2vec model."""
    i = 0
    p = Progress()
    for path in paths:
        with open(path, 'r') as f:
            for line in f:
                i += 1
                p.print_progress(i / n)
                line = line.lower()
                if sentences:
                    for sent in sent_tokenize(line):
                        tokens = tokenizer(sent)
                        yield LabeledSentence(tokens, ['SENT_{}'.format(i)])
                else:
                    tokens = tokenizer(line)
                    yield LabeledSentence(tokens, ['SENT_{}'.format(i)])

def not_completed(f):
    """Decorator function to check if user is loged in.

    :raises: :class:`FMBaseError` if not logged in"""
    @wraps(f)
    def check_if_complete(cls, *args, **kwargs):
        if cls.is_complete:
            raise FMBaseError('Transfer already completed.')
        return f(cls, *args, **kwargs)
    return check_if_complete

def _get_default_letters(model_admin=None):
    """Returns the set of letters defined in the configuration variable
    DEFAULT_ALPHABET. DEFAULT_ALPHABET can be a callable, string, tuple, or
    list and returns a set.

    If a ModelAdmin class is passed, it will look for a DEFAULT_ALPHABET
    attribute and use it instead."""
    from django.conf import settings
    import string
    default_ltrs = string.digits + string.ascii_uppercase
    default_letters = getattr(settings, 'DEFAULT_ALPHABET', default_ltrs)
    if model_admin and hasattr(model_admin, 'DEFAULT_ALPHABET'):
        default_letters = model_admin.DEFAULT_ALPHABET
    if callable(default_letters):
        return set(default_letters())
    elif isinstance(default_letters, str):
        return set([x for x in default_letters])
    elif isinstance(default_letters, str):
        return set([x for x in default_letters.decode('utf8')])
    elif isinstance(default_letters, (tuple, list)):
        return set(default_letters)

def _get_available_letters(field_name, queryset):
    """Makes a query to the database to return the first character of each
    value of the field and table passed in.

    Returns a set that represents the letters that exist in the database."""
    if django.VERSION[1] <= 4:
        result = queryset.values(field_name).annotate(fl=FirstLetter(field_name)).values('fl').distinct()
        return set([res['fl'] for res in result if res['fl'] is not None])
    else:
        from django.db import connection
        qn = connection.ops.quote_name
        db_table = queryset.model._meta.db_table
        sql = 'SELECT DISTINCT UPPER(SUBSTR(%s, 1, 1)) as letter FROM %s' % (qn(field_name), qn(db_table))
        cursor = connection.cursor()
        cursor.execute(sql)
        rows = cursor.fetchall() or ()
        return set([row[0] for row in rows if row[0] is not None])

def qs_alphabet_filter(parser, token):
    """The parser/tokenizer for the queryset alphabet filter.

    {% qs_alphabet_filter <queryset> <field name> [<template name>] [strip_params=comma,delim,list] %}

    {% qs_alphabet_filter objects lastname myapp/template.html %}

    The template name is optional and uses alphafilter/alphabet.html if not
    specified"""
    bits = token.split_contents()
    if len(bits) == 3:
        return AlphabetFilterNode(bits[1], bits[2])
    elif len(bits) == 4:
        if '=' in bits[3]:
            key, val = bits[3].split('=')
            return AlphabetFilterNode(bits[1], bits[2], strip_params=val)
        else:
            return AlphabetFilterNode(bits[1], bits[2], template_name=bits[3])
    elif len(bits) == 5:
        key, val = bits[4].split('=')
        return AlphabetFilterNode(bits[1], bits[2], bits[3], bits[4])
    else:
        raise TemplateSyntaxError('%s is called with a queryset and field name, and optionally a template.' % bits[0])

def _count(dicts):
    """Merge a list of dicts, summing their values."""
    counts = defaultdict(int)
    for d in dicts:
        for k, v in d.items():
            counts[k] += v
    return counts

def _chunks(iterable, n):
    """Splits an iterable into chunks of size n."""
    iterable = iter(iterable)
    while True:
        yield chain([next(iterable)], islice(iterable, n - 1))

def doc_stream(path):
    """Generator to feed tokenized documents (treating each line as a document)."""
    with open(path, 'r') as f:
        for line in f:
            if line.strip():
                yield line

def load_stop_words(stop_word_file):
    """Utility function to load stop words from a file and return as a list of words
    @param stop_word_file Path and file name of a file containing stop words.
    @return list A list of stop words."""
    stop_words = []
    for line in open(stop_word_file):
        if line.strip()[0:1] != '#':
            for word in line.split():
                stop_words.append(word)
    return stop_words

def separate_words(text, min_word_return_size):
    """Utility function to return a list of all words that are have a length greater than a specified number of characters.
    @param text The text that must be split in to words.
    @param min_word_return_size The minimum no of characters a word must have to be included."""
    splitter = re.compile('[^a-zA-Z0-9_\\+\\-/]')
    words = []
    for single_word in splitter.split(text):
        current_word = single_word.strip().lower()
        if len(current_word) > min_word_return_size and current_word != '' and (not is_number(current_word)):
            words.append(current_word)
    return words

def param_redirect(request, viewname, *args):
    """Redirect and keep URL parameters if any."""
    url = reverse(viewname, PARAMS_URL_CONF, args)
    params = request.GET.urlencode().split('&')
    if hasattr(request, 'cparam'):
        for k, v in request.cparam.items():
            params.append('{0}={1}'.format(k, v))
    new_params = '&'.join((x for x in params if x != ''))
    if len(new_params) > 0:
        return HttpResponseRedirect('{0}?{1}'.format(url, new_params))
    return HttpResponseRedirect(url)

def get_response(sock, buffer_size=4096):
    """Helper method for retrieving a response from a given socket.

    Returns two values in a tuple, the first is the reponse line and the second
    is any extra data after the newline."""
    response = ''
    extra = ''
    while True:
        try:
            chunk = sock.recv(buffer_size)
            if chunk:
                response += chunk
        except socket.error as e:
            if e.errno not in [errno.EAGAIN, errno.EINTR]:
                raise
        if not response:
            break
        if '\n' in response:
            response, extra = response.split('\n', 1)
            break
    return (response, extra)

def init_tasks():
    """Performs basic setup before any of the tasks are run. All tasks needs to
    run this before continuing. It only fires once."""
    if 'exists' not in env:
        env.exists = exists
    if 'run' not in env:
        env.run = run
    if 'cd' not in env:
        env.cd = cd
    if 'max_releases' not in env:
        env.max_releases = 5
    if 'public_path' in env:
        public_path = env.public_path.rstrip('/')
        env.public_path = public_path
    run_hook('init_tasks')

def deploy():
    """Performs a deploy by invoking copy, then generating next release name and
    invoking necessary hooks."""
    init_tasks()
    if not has_hook('copy'):
        return report('No copy method has been defined')
    if not env.exists(paths.get_shared_path()):
        return report('You need to run setup before running deploy')
    run_hook('before_deploy')
    release_name = int(time.time() * 1000)
    release_path = paths.get_releases_path(release_name)
    env.current_release = release_path
    try:
        run_hook('copy')
    except Exception as e:
        return report('Error occurred on copy. Aborting deploy', err=e)
    if not env.exists(paths.get_source_path(release_name)):
        return report("Source path not found '%s'" % paths.get_source_path(release_name))
    try:
        run_hook('deploy')
    except Exception as e:
        message = 'Error occurred on deploy, starting rollback...'
        logger.error(message)
        logger.error(e)
        run_task('rollback')
        return report('Error occurred on deploy')
    paths.symlink(paths.get_source_path(release_name), paths.get_current_path())
    if 'max_releases' in env:
        cleanup_releases(int(env.max_releases))
    run_hook('after_deploy')
    if 'public_path' in env:
        paths.symlink(paths.get_source_path(release_name), env.public_path)
    logger.info('Deploy complete')

def pipe_shell_cmds(shell_CMDs):
    '''shell_CMDs = {}
    shell_CMDs[1] = 'netstat -n'
    shell_CMDs[2] = "awk {'print $6'}"'''
    len = shell_CMDs.__len__()
    p = {}
    p[1] = subprocess.Popen(shlex.split(shell_CMDs[1]), stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    for i in range(2, len):
        p[i] = subprocess.Popen(shlex.split(shell_CMDs[i]), stdin=p[i - 1].stdout, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if len > 1:
        p[len] = subprocess.Popen(shlex.split(shell_CMDs[len]), stdin=p[len - 1].stdout, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    result = p[len].communicate()
    if len > 1:
        for i in range(2, len + 1):
            returncode = p[i].wait()
    else:
        returncode = p[len].wait()
    return result

def prune(tdocs):
    """Prune terms which are totally subsumed by a phrase

    This could be better if it just removes the individual keywords
    that occur in a phrase for each time that phrase occurs."""
    all_terms = set([t for toks in tdocs for t in toks])
    terms = set()
    phrases = set()
    for t in all_terms:
        if gram_size(t) > 1:
            phrases.add(t)
        else:
            terms.add(t)
    redundant = set()
    for t in terms:
        if any((t in ph for ph in phrases)):
            redundant.add(t)
    cleared = set()
    for t in redundant:
        if any((check_term(d, term=t) for d in tdocs)):
            cleared.add(t)
    redundant = redundant.difference(cleared)
    pruned_tdocs = []
    for doc in tdocs:
        pruned_tdocs.append([t for t in doc if t not in redundant])
    return pruned_tdocs

def generate_pagination(total_page_num, current_page_num):
    """>>> PAGE_SIZE = 10
    >>> generate_pagination(total_page_num=9, current_page_num=1)
    {'start': 1, 'end': 9, 'current': 1}
    >>> generate_pagination(total_page_num=20, current_page_num=12)
    {'start': 8, 'end': 17, 'current': 12}
    >>> generate_pagination(total_page_num=20, current_page_num=4)
    {'start': 1, 'end': 10, 'current': 4}
    >>> generate_pagination(total_page_num=16, current_page_num=14)
    {'start': 7, 'end': 16, 'current': 14}"""
    pagination = {'start': 1, 'end': PAGE_SIZE, 'current': current_page_num}
    if total_page_num <= PAGE_SIZE:
        pagination['end'] = total_page_num
    else:
        pagination['start'] = current_page_num - 4
        pagination['end'] = current_page_num + 5
        if pagination['start'] < 1:
            pagination['start'] = 1
            pagination['end'] = PAGE_SIZE
        if pagination['end'] > total_page_num:
            pagination['end'] = total_page_num
            pagination['start'] = total_page_num - 9
    return pagination

def count_tf(tokens_stream):
    """Count term frequencies for a single file."""
    tf = defaultdict(int)
    for tokens in tokens_stream:
        for token in tokens:
            tf[token] += 1
