def _default_tokenizer_func(content, keyword_weight_pair):
    """Default tokenizer function that uses jieba tokenizer.

    :param keyword_weight_pair: maximum pair number of the keyword-weight list.
    :return: return keyword-weight list. Example: [('Example',0.4511233019962264),('Hello',0.25548051420382073),...]."""
    seg_list = jieba.lcut_for_search(content)
    return jieba.analyse.extract_tags(''.join(seg_list), topK=keyword_weight_pair, withWeight=True)

def _validate_date_str(str_):
    """Validate str as a date and return string version of date"""
    if not str_:
        return None
    try:
        date = datetime.strptime(str_, DATE_FMT)
    except ValueError:
        msg = 'Invalid date format, should be YYYY-MM-DD'
        raise argparse.ArgumentTypeError(msg)
    return date.strftime(DATE_FMT)

def get_tag_context(name, state):
    """Given a tag name, return its associated value as defined in the current
    context stack."""
    new_contexts = 0
    ctm = None
    while True:
        try:
            ctx_key, name = name.split('.', 1)
            ctm = state.context.get(ctx_key)
        except ValueError:
            break
        if not ctm:
            break
        else:
            state.context.push(ctm)
            new_contexts += 1
    ctm = state.context.get(name)
    return (new_contexts, ctm)

def section_end_info(template, tag_key, state, index):
    """Given the tag key of an opening section tag, find the corresponding closing
    tag (if it exists) and return information about that match."""
    state.section.push(tag_key)
    match = None
    matchinfo = None
    search_index = index
    while state.section:
        match = state.tag_re.search(template, search_index)
        if not match:
            raise Exception('Open section %s never closed' % tag_key)
        matchinfo = get_match_info(template, match, state)
        if matchinfo['tag_type'] in ('#', '^'):
            state.section.push(matchinfo['tag_key'])
        elif matchinfo['tag_type'] == '/':
            if matchinfo['tag_key'] == state.section():
                state.section.pop()
            else:
                raise Exception('Unexpected section end: received %s, expected {{/%s}}' % (repr(match.group(0)), tag_key))
        search_index = matchinfo['tag_end']
    return matchinfo

def render(template, context, partials={}, state=None):
    """Renders a given mustache template, with sane defaults."""
    state = state or State()
    if isinstance(context, Context):
        state.context = context
    else:
        state.context = Context(context)
    if partials:
        state.partials.push(partials)
    return __render(make_unicode(template), state)

def __render_tag(info, state):
    """Render an individual tag by making the appropriate replacement within
    the current context (if any)."""
    new_contexts, context_match = get_tag_context(info['tag_key'], state)
    replacement = ''
    if context_match or context_match == 0:
        replacement = context_match
    elif info['tag_key'] == '.':
        replacement = state.context()
    else:
        replacement = ''
    if replacement and callable(replacement):
        replacement = make_unicode(replacement())
        state.push_tags(state.default_tags)
        replacement = __render(template=replacement, state=state)
        state.pop_tags()
    for i in xrange(new_contexts):
        state.context.pop()
    if state.escape():
        return html_escape(replacement)
    return replacement

def list_to_str(list, separator=','):
    """>>> list = [0, 0, 7]
    >>> list_to_str(list)
    '0,0,7'"""
    list = [str(x) for x in list]
    return separator.join(list)

def unite_dict(a, b):
    """>>> a = {'name': 'Sylvanas'}
    >>> b = {'gender': 'Man'}
    >>> unite_dict(a, b)
    {'name': 'Sylvanas', 'gender': 'Man'}"""
    c = {}
    c.update(a)
    c.update(b)
    return c

def check_validity_for_dict(keys, dict):
    """>>> dict = {'a': 0, 'b': 1, 'c': 2}
    >>> keys = ['a', 'd', 'e']
    >>> check_validity_for_dict(keys, dict) == False
    True
    >>> keys = ['a', 'b', 'c']
    >>> check_validity_for_dict(keys, dict) == False
    False"""
    for key in keys:
        if key not in dict or dict[key] is '' or dict[key] is None:
            return False
    return True

def parallel(func, inputs, n_jobs, expand_args=False):
    """Convenience wrapper around joblib's parallelization."""
    if expand_args:
        return Parallel(n_jobs=n_jobs)((delayed(func)(*args) for args in inputs))
    else:
        return Parallel(n_jobs=n_jobs)((delayed(func)(arg) for arg in inputs))

