def wait_on_any(*events, **kwargs):
    """Helper method for waiting for any of the given threading events to be
    set.

    The standard threading lib doesn't include any mechanism for waiting on
    more than one event at a time so we have to monkey patch the events
    so that their `set()` and `clear()` methods fire a callback we can use
    to determine how a composite event should react."""
    timeout = kwargs.get('timeout')
    composite_event = threading.Event()
    if any([event.is_set() for event in events]):
        return
    def on_change():
        if any([event.is_set() for event in events]):
            composite_event.set()
        else:
            composite_event.clear()
    def patch(original):
        def patched():
            original()
            on_change()
        return patched
    for event in events:
        event.set = patch(event.set)
        event.clear = patch(event.clear)
    wait_on_event(composite_event, timeout=timeout)

def wait_on_event(event, timeout=None):
    """Waits on a single threading Event, with an optional timeout.

    This is here for compatibility reasons as python 2 can't reliably wait
    on an event without a timeout and python 3 doesn't define a `maxint`."""
    if timeout is not None:
        event.wait(timeout)
        return
    if six.PY2:
        while not event.is_set():
            event.wait(sys.maxint)
    else:
        event.wait()

def make_unicode(s, encoding='utf-8', encoding_errors='strict'):
    """Return the unicode version of an input."""
    if not isinstance(s, unicode):
        if not isinstance(s, basestring):
            return unicode(str(s), encoding, encoding_errors)
        return unicode(s, encoding, encoding_errors)
    return s

def html_escape(s, encoding='utf-8', encoding_errors='strict'):
    """Return the HTML-escaped version of an input."""
    return escape(make_unicode(s, encoding, encoding_errors), quote=True)

def filter_support(candidates, transactions, min_sup):
    """Filter candidates to a frequent set by some minimum support."""
    counts = defaultdict(lambda: 0)
    for transaction in transactions:
        for c in (c for c in candidates if set(c).issubset(transaction)):
            counts[c] += 1
    return {i for i in candidates if counts[i] / len(transactions) >= min_sup}

def generate_candidates(freq_set, k):
    """Generate candidates for an iteration.
    Use this only for k >= 2."""
    single_set = {(i,) for i in set(flatten(freq_set))}
    cands = [flatten(f) for f in combinations(single_set, k)]
    return [cand for cand in cands if validate_candidate(cand, freq_set, k)]

def validate_candidate(candidate, freq_set, k):
    """Checks if we should keep a candidate.
    We keep a candidate if all its k-1-sized subsets
    are present in the frequent sets."""
    for subcand in combinations(candidate, k - 1):
        if subcand not in freq_set:
            return False
    return True

