    rvmat = elel.prepend(rvmat, [])
    return rvmat

def get_vndmat_attr(d, keypath, attr, **kwargs):
    """get_vndmat_attr(d,['x'],'lsib_path',path2keypath=True)
    get_vndmat_attr(d,['t'],'lsib_path',path2keypath=True)
    get_vndmat_attr(d,['u'],'lsib_path',path2keypath=True)
    get_vndmat_attr(d,['y'],'lsib_path',path2keypath=True)"""
    kt, vn = _d2kvmatrix(d)
    kdmat = _scankm(kt)
    ltree = elel.ListTree(vn)
    vndmat = ltree.desc
    loc = get_kdmat_loc(kdmat, keypath)
    rslt = vndmat[loc[0]][loc[1]][attr]
    if rslt == None:
        pass
    elif elel.is_matrix(rslt, mode='loose'):
        if 'path2loc' in kwargs:
            rslt = elel.array_map(rslt, ltree.path2loc)
        else:
            pass
        if 'path2keypath' in kwargs:
            nlocs = elel.array_map(rslt, ltree.path2loc)
            def cond_func(ele, kdmat):
                return kdmat[ele[0]][ele[1]]['path']
            rslt = elel.array_map(nlocs, cond_func, kdmat)
        else:
            pass
    else:
        if 'path2loc' in kwargs:
            rslt = ltree.path2loc(rslt)
        else:
            pass
        if 'path2keypath' in kwargs:
            nloc = ltree.path2loc(rslt)
            rslt = kdmat[nloc[0]][nloc[1]]['path']
        else:
            pass
    return rslt

def color_string(color, string):
    """Colorizes a given string, if coloring is available."""
    if not color_available:
        return string
    return color + string + colorama.Fore.RESET

def color_for_level(level):
    """Returns the colorama Fore color for a given log level.

    If color is not available, returns None."""
    if not color_available:
        return None
    return {logging.DEBUG: colorama.Fore.WHITE, logging.INFO: colorama.Fore.BLUE, logging.WARNING: colorama.Fore.YELLOW, logging.ERROR: colorama.Fore.RED, logging.CRITICAL: colorama.Fore.MAGENTA}.get(level, colorama.Fore.WHITE)

def create_thread_color_cycle():
    """Generates a never-ending cycle of colors to choose from for individual
    threads.

    If color is not available, a cycle that repeats None every time is
    returned instead."""
    if not color_available:
        return itertools.cycle([None])
    return itertools.cycle((colorama.Fore.CYAN, colorama.Fore.BLUE, colorama.Fore.MAGENTA, colorama.Fore.GREEN))

def color_for_thread(thread_id):
    """Associates the thread ID with the next color in the `thread_colors` cycle,
    so that thread-specific parts of a log have a consistent separate color."""
    if thread_id not in seen_thread_colors:
        seen_thread_colors[thread_id] = next(thread_colors)
    return seen_thread_colors[thread_id]

def read_unicode(path, encoding, encoding_errors):
    """Return the contents of a file as a unicode string."""
    try:
        f = open(path, 'rb')
        return make_unicode(f.read(), encoding, encoding_errors)
    finally:
        f.close()

def get_abs_template_path(template_name, directory, extension):
    """Given a template name, a directory, and an extension, return the
    absolute path to the template."""
    relative_path = join(directory, template_name)
    file_with_ext = template_name
    if extension:
        file_name, file_ext = splitext(file_with_ext)
        if not file_ext:
            file_with_ext = extsep.join((file_name, extension.replace(extsep, '')))
            relative_path = join(directory, file_with_ext)
    return abspath(relative_path)

def load_file(path, encoding, encoding_errors):
    """Given an existing path, attempt to load it as a unicode string."""
    abs_path = abspath(path)
    if exists(abs_path):
        return read_unicode(abs_path, encoding, encoding_errors)
    raise IOError('File %s does not exist' % abs_path)

def load_template(name, directory, extension, encoding, encoding_errors):
    """Load a template and return its contents as a unicode string."""
    abs_path = get_abs_template_path(name, directory, extension)
    return load_file(abs_path, encoding, encoding_errors)

def getPrimeFactors(n):
    """Get all the prime factor of given integer
    @param n integer
    @return list [1, ..., n]"""
    lo = [1]
    n2 = n // 2
    k = 2
    for k in range(2, n2 + 1):
        if n // k * k == n:
            lo.append(k)
    return lo + [n]

def get_setting(setting):
    """Get the specified django setting, or it's default value"""
    defaults = {'TEMPLATE_FIELD_CONTEXT': {}, 'TEMPLATE_FIELD_RENDER': True}
    try:
        return getattr(settings, setting, defaults[setting])
    except KeyError:
        msg = '{0} is not specified in your settings'.format(setting)
        raise ImproperlyConfigured(msg)

def configure(ctx, helper, edit):
    """Update configuration"""
    ctx.obj.config = ConfigFile(ctx.obj.config_file)
    if edit:
        ctx.obj.config.edit_config_file()
        return
    if os.path.isfile(ctx.obj.config.config_file):
        ctx.obj.config.read_config()
    if ctx.obj.profile is None:
        ctx.obj.profile = ctx.obj.config.default_profile
    args, kwargs = _parse_args_and_kwargs(ctx.args)
    assert len(args) == 0, 'Unrecognized arguments: "{}"'.format(args)
    if ctx.obj.profile not in ctx.obj.config.config['profiles']:
        ctx.obj.config.config['profiles'][ctx.obj.profile] = {'api': {'user_config': {}}, 'manager': {}, 'authorities': {}}
    profile_config = ctx.obj.config.config['profiles'][ctx.obj.profile]
    profile_config['api']['user_config'].update(kwargs)
    ctx.obj.config.write_config(ctx.obj.config_file)
    _generate_api(ctx)
    if ctx.obj.api.manager is not None:
        check_requirements(to_populate=profile_config['api']['user_config'], prompts=ctx.obj.api.manager.required_user_config, helper=helper)
    ctx.obj.config.write_config(ctx.obj.config_file)

def update(ctx, archive_name, bumpversion='patch', prerelease=None, dependency=None, message=None, string=False, file=None):
    """Update an archive with new contents"""
    _generate_api(ctx)
    args, kwargs = _parse_args_and_kwargs(ctx.args)
    assert len(args) == 0, 'Unrecognized arguments: "{}"'.format(args)
    dependencies_dict = _parse_dependencies(dependency)
    var = ctx.obj.api.get_archive(archive_name)
    latest_version = var.get_latest_version()
    if string:
        with var.open('w+', bumpversion=bumpversion, prerelease=prerelease, dependencies=dependencies_dict, metadata=kwargs, message=message) as f:
            if file is None:
                for line in sys.stdin:
                    f.write(u(line))
            else:
                f.write(u(file))
    else:
        if file is None:
            file = click.prompt('enter filepath')
        var.update(file, bumpversion=bumpversion, prerelease=prerelease, dependencies=dependencies_dict, metadata=kwargs, message=message)
    new_version = var.get_latest_version()
    if latest_version is None and new_version is not None:
        bumpmsg = ' new version {} created.'.format(new_version)
    elif new_version != latest_version:
        bumpmsg = ' version bumped {} --> {}.'.format(latest_version, new_version)
    elif var.versioned:
        bumpmsg = ' version remains {}.'.format(latest_version)
    else:
        bumpmsg = ''
    click.echo('uploaded data to {}.{}'.format(var, bumpmsg))

