def import_i2c_addr(bus, opt='sensors'):
    """import_i2c_addresses will return a list of the
        currently connected I2C devices.

    This can be used a means to automatically detect
        the number of connected sensor modules.
    Modules are between int(112) and int(119)

    By default, the method will return a list
        of sensor addresses."""
    i2c_list = []
    for device in range(128):
        try:
            bus.read_byte(device)
            i2c_list.append(device)
        except IOError:
            pass
    if opt == 'sensors':
        sensor_list = []
        for module in range(112, 120):
            try:
                indx = i2c_list.index(module)
                sensor_list.append(module)
            except ValueError:
                pass
        return sensor_list
    else:
        return i2c_list

def Group(params, name=None, type=None):
    """Groups together Params for adding under the 'What' section.

    Args:
        params(list of :func:`Param`): Parameter elements to go in this group.
        name(str): Group name. NB ``None`` is valid, since the group may be
            best identified by its type.
        type(str): Type of group, e.g. 'complex' (for real and imaginary)."""
    atts = {}
    if name:
        atts['name'] = name
    if type:
        atts['type'] = type
    g = objectify.Element('Group', attrib=atts)
    for p in params:
        g.append(p)
    return g

def Reference(uri, meaning=None):
    """Represents external information, typically original obs data and metadata.

    Args:
        uri(str): Uniform resource identifier for external data, e.g. FITS file.
        meaning(str): The nature of the document referenced, e.g. what
            instrument and filter was used to create the data?"""
    attrib = {'uri': uri}
    if meaning is not None:
        attrib['meaning'] = meaning
    return objectify.Element('Reference', attrib)

def Inference(probability=None, relation=None, name=None, concept=None):
    """Represents a probable cause / relation between this event and some prior.

    Args:
        probability(float): Value 0.0 to 1.0.
        relation(str): e.g. 'associated' or 'identified' (see Voevent spec)
        name(str): e.g. name of identified progenitor.
        concept(str): One of a 'formal UCD-like vocabulary of astronomical
            concepts', e.g. http://ivoat.ivoa.net/stars.supernova.Ia - see
            VOEvent spec."""
    atts = {}
    if probability is not None:
        atts['probability'] = str(probability)
    if relation is not None:
        atts['relation'] = relation
    inf = objectify.Element('Inference', attrib=atts)
    if name is not None:
        inf.Name = name
    if concept is not None:
        inf.Concept = concept
    return inf

