def via_scan():
    """IP scan - now implemented"""
    import socket
    import ipaddress
    import httpfind
    bridges_from_scan = []
    hosts = socket.gethostbyname_ex(socket.gethostname())[2]
    for host in hosts:
        bridges_from_scan += httpfind.survey(ipaddress.ip_interface(host + '/24').network, path='description.xml', pattern='(P|p)hilips')
        logger.info('Scan on %s', host)
    logger.info('Scan returned %d Hue bridges(s).', len(bridges_from_scan))
    found_bridges = {}
    for bridge in bridges_from_scan:
        serial, bridge_info = parse_description_xml(bridge)
        if serial:
            found_bridges[serial] = bridge_info
    logger.debug('%s', found_bridges)
    if found_bridges:
        return found_bridges
    else:
        raise DiscoveryError('Scan returned nothing')

def mset(m_dict, keys, value, delimiter=':'):
    """:param m_dict: A dictionary to set the value inside of
    :type m_dict: dict
    :param keys: A list of keys
    :type keys: str
    :param value: The value to set inside of the dictionary
    :param delimiter: The delimiter used in the keys list
    :type delimiter: str"""
    val = m_dict
    keys = keys.split(delimiter)
    for i, key in enumerate(keys):
        try:
            if i == len(keys) - 1:
                val[key] = value
                return
            else:
                val = val[key]
        except KeyError:
            if i == len(keys) - 1:
                val[key] = value
                return
            else:
                val[key] = {}
                val = val[key]

