    p = []
    k = []
    for param in params:
        name = fix_param_name(param['name'])
        if 'required' in param and param['required'] is True:
            p.append(name)
        elif 'default' in param:
            k.append('{name}={default}'.format(name=name, default=param['default']))
        else:
