def watch(directory=None, auto_clear=False, extensions=[]):
    """Starts a server to render the specified file or directory containing a README."""
    if directory and (not os.path.isdir(directory)):
        raise ValueError('Directory not found: ' + directory)
    directory = os.path.abspath(directory)
    event_handler = ChangeHandler(directory, auto_clear, extensions)
    event_handler.run()
    observer = Observer()
    observer.schedule(event_handler, path=directory, recursive=True)
    observer.start()
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        observer.stop()
    observer.join()

def dict_get_path(data, path, default=None):
    """Returns the value inside nested structure of data located
    at period delimited path

    When traversing a list, as long as that list is containing objects of
    type dict, items in that list will have their "name" and "type" values
    tested against the current key in the path.

    Args:
        data (dict or list): data to traverse
        path (str): '.' delimited string

    Kwargs:
        default: value to return if path does not exist"""
    keys = path.split('.')
    for k in keys:
        if type(data) == list:
            found = False
            for item in data:
                name = item.get('name', item.get('type'))
                if name == k:
                    found = True
                    data = item
                    break
            if not found:
                return default
        elif type(data) == dict:
            if k in data:
                data = data[k]
            else:
                return default
        else:
            return default
    return data

def _process_worker(call_queue, result_queue, shutdown):
    """Evaluates calls from call_queue and places the results in result_queue.

    This worker is run in a seperate process.

    Args:
        call_queue: A multiprocessing.Queue of _CallItems that will be read and
            evaluated by the worker.
        result_queue: A multiprocessing.Queue of _ResultItems that will written
            to by the worker.
        shutdown: A multiprocessing.Event that will be set as a signal to the
            worker that it should exit when call_queue is empty."""
    while True:
        try:
            call_item = call_queue.get(block=True, timeout=0.1)
        except queue.Empty:
            if shutdown.is_set():
                return
        else:
            try:
                r = call_item()
            except BaseException as e:
                result_queue.put(_ResultItem(call_item.work_id, exception=e))
            else:
                result_queue.put(_ResultItem(call_item.work_id, result=r))

