def Route(resource=None, methods=['get', 'post', 'put', 'delete'], schema=None):
    """route"""
    def _route(func):
        def wrapper(self, *args, **kwargs):
            if kwargs.get('test', False):
                kwargs.pop('test')
                func(self, *args, **kwargs)
            _methods = methods
            if isinstance(methods, str):
                _methods = [methods]
            route = self.router.route(resource)
            for method in _methods:
                getattr(route, method)(func, schema)
        f_locals = sys._getframe(1).f_locals
        _order = len([v for v in f_locals.itervalues() if hasattr(v, '__call__') and hasattr(v, '__name__') and (v.__name__ == 'wrapper')])
        wrapper.__dict__['_order'] = _order
        return wrapper
    return _route

def url_split(s3_url):
    """Split S3 URL and return a tuple of (bucket, key).

    S3 URL is expected to be of "s3://<bucket>/<key>" format."""
    assert isinstance(s3_url, str)
    match = re_s3_url.match(s3_url)
    if not match:
        raise UrlParseError('Error parsing S3 URL: "%s"' % s3_url)
    parts = match.groupdict()
    return (parts['bucket'], parts['key'])

def ibatch(iterable, size):
    """Yield a series of batches from iterable, each size elements long."""
    source = iter(iterable)
    while True:
        batch = itertools.islice(source, size)
        yield itertools.chain([next(batch)], batch)

