def validate_word_size(word_size, BLAST_SETS):
    """Validate word size in blast/tblastn form."""
    blast_min_int_word_size = BLAST_SETS.min_word_size
    blast_max_int_word_size = BLAST_SETS.max_word_size
    blast_word_size_error = BLAST_SETS.get_word_size_error()
    try:
        if len(word_size) <= 0:
            raise forms.ValidationError(blast_word_size_error)
        int_word_size = int(word_size)
        if int_word_size < blast_min_int_word_size:
            raise forms.ValidationError(blast_word_size_error)
        if int_word_size >= blast_max_int_word_size:
            raise forms.ValidationError(blast_word_size_error)
    except:
        raise forms.ValidationError(blast_word_size_error)
    return int_word_size

def validate_sequence(sequence: str, sequence_is_as_nucleotide=True):
    """Validate sequence in blast/tblastn form."""
    tmp_seq = tempfile.NamedTemporaryFile(mode='wb+', delete=False)
    if len(str(sequence).strip()) == 0:
        raise forms.ValidationError(blast_settings.BLAST_CORRECT_SEQ_ERROR_MSG)
    if str(sequence).strip()[0] != '>':
        tmp_seq.write('>seq1\n'.encode())
    tmp_seq.write(sequence.encode())
    tmp_seq.close()
    records = SeqIO.index(tmp_seq.name, 'fasta')
    record_count = len(records)
    if record_count == 0:
        raise forms.ValidationError(blast_settings.BLAST_CORRECT_SEQ_ERROR_MSG)
    if record_count > blast_settings.BLAST_MAX_NUMBER_SEQ_IN_INPUT:
        raise forms.ValidationError(blast_settings.BLAST_CORRECT_SEQ_MAX_SEQ_NUMB_ERROR_MSG)
    first_sequence_list_in_file = SeqIO.parse(tmp_seq.name, 'fasta')
    for sequence in first_sequence_list_in_file:
        if len(sequence.seq) <= 10:
            raise forms.ValidationError(blast_settings.BLAST_CORRECT_SEQ_TOO_SHORT_ERROR_MSG)
        if sequence_is_as_nucleotide:
            check_allowed_letters(str(sequence.seq), ALLOWED_NUCL)
        else:
            check_allowed_letters(str(sequence.seq), ALLOWED_AMINOACIDS)
    return tmp_seq

def check_allowed_letters(seq, allowed_letters_as_set):
    """Validate sequence: Rise an error if sequence contains undesirable letters."""
    seq_set = set(seq)
    not_allowed_letters_in_seq = [x for x in seq_set if str(x).upper() not in allowed_letters_as_set]
    if len(not_allowed_letters_in_seq) > 0:
        raise forms.ValidationError('This sequence type cannot contain letters: ' + ', '.join(not_allowed_letters_in_seq))

def blast_records_to_object(blast_records):
    """Transforms biopython's blast record into blast object defined in django-blastplus app."""
    blast_objects_list = []
    for blast_record in blast_records:
        br = BlastRecord(**{'query': blast_record.query, 'version': blast_record.version, 'expect': blast_record.expect, 'application': blast_record.application, 'reference': blast_record.reference})
        for alignment in blast_record.alignments:
            al = Alignment(**{'hit_def': alignment.hit_def, 'title': alignment.title, 'length': alignment.length})
            for hsp in alignment.hsps:
                h = Hsp(**{'align_length': hsp.align_length, 'bits': hsp.bits, 'expect': hsp.expect, 'frame': hsp.frame, 'gaps': hsp.gaps, 'identities': hsp.identities, 'match': hsp.match, 'num_alignments': hsp.num_alignments, 'positives': hsp.positives, 'query': hsp.query, 'query_end': hsp.query_end, 'query_start': hsp.query_start, 'sbjct': hsp.sbjct, 'sbjct_end': hsp.sbjct_end, 'sbjct_start': hsp.sbjct_start, 'score': hsp.score, 'strand': hsp.strand, 'str': str(hsp)})
                al.hsp_list.append(h)
            br.alignments.append(al)
        blast_objects_list.append(br)
    return blast_objects_list

def find_usbserial(vendor, product):
    """Find the tty device for a given usbserial devices identifiers.

    Args:
       vendor: (int) something like 0x0000
       product: (int) something like 0x0000

    Returns:
       String, like /dev/ttyACM0 or /dev/tty.usb..."""
    if platform.system() == 'Linux':
        vendor, product = [('%04x' % x).strip() for x in (vendor, product)]
        return linux_find_usbserial(vendor, product)
    elif platform.system() == 'Darwin':
        return osx_find_usbserial(vendor, product)
    else:
        raise NotImplementedError('Cannot find serial ports on %s' % platform.system())

def bytes_iter(obj):
    """Turn a complex object into an iterator of byte strings.
    The resulting iterator can be used for caching."""
    if obj is None:
        return
    elif isinstance(obj, six.binary_type):
        yield obj
    elif isinstance(obj, six.string_types):
        yield obj
    elif isinstance(obj, (date, datetime)):
        yield obj.isoformat()
    elif is_mapping(obj):
        for key in sorted(obj.keys()):
            for out in chain(bytes_iter(key), bytes_iter(obj[key])):
                yield out
    elif is_sequence(obj):
        if isinstance(obj, (list, set)):
            try:
                obj = sorted(obj)
            except Exception:
                pass
        for item in obj:
            for out in bytes_iter(item):
                yield out
    elif isinstance(obj, (types.FunctionType, types.BuiltinFunctionType, types.MethodType, types.BuiltinMethodType)):
        yield getattr(obj, 'func_name', '')
    else:
        yield six.text_type(obj)

def hash_data(obj):
    """Generate a SHA1 from a complex object."""
    collect = sha1()
    for text in bytes_iter(obj):
        if isinstance(text, six.text_type):
            text = text.encode('utf-8')
        collect.update(text)
    return collect.hexdigest()

