def rgb(red, green, blue):
    """Calculate the palette index of a color in the 6x6x6 color cube.

    The red, green and blue arguments may range from 0 to 5."""
    for value in (red, green, blue):
        if value not in range(6):
            raise ColorError('Value must be within 0-5, was {}.'.format(value))
    return 16 + red * 36 + green * 6 + blue

def code_to_unicode(code):
    u"""Convert character code(hex) to unicode"""
    def utf32chr(n):
        """utf32char for narrow build python"""
        return eval("u'\\U%08X'" % n)
    def lazy_unichr(n):
        try:
            return unichr(n)
        except ValueError:
            warnings.warn("Your python it built as narrow python. Make with '--enable-unicode=ucs4' configure option to build wide python")
            return utf32chr(n)
    if code and isinstance(code, basestring):
        clean_code = code.replace('>', '')
        if clean_code:
            return u''.join([lazy_unichr(int(code_char, 16)) for code_char in clean_code.split('+') if code_char])
    return None

def code_to_sjis(code):
    u"""Convert character code(hex) to string"""
    if code and isinstance(code, basestring):
        clean_code = code.replace('>', '')
        if clean_code:
            _code_to_sjis_char = lambda c: ''.join([chr(int('%c%c' % (a, b), 16)) for a, b in izip(c[0::2], c[1::2])])
            return ''.join([_code_to_sjis_char(code_char) for code_char in clean_code.split('+') if code_char])
    return None

def vtquery(apikey, checksums):
    """Performs the query dealing with errors and throttling requests."""
    data = {'apikey': apikey, 'resource': isinstance(checksums, str) and checksums or ', '.join(checksums)}
    while 1:
        response = requests.post(VT_REPORT_URL, data=data)
        response.raise_for_status()
        if response.status_code == 200:
            return response.json()
        elif response.status_code == 204:
            logging.debug('API key request rate limit reached, throttling.')
            time.sleep(VT_THROTTLE)
        else:
            raise RuntimeError('Response status code %s' % response.status_code)

def chunks(iterable, size=1):
    """Splits iterator in chunks."""
    iterator = iter(iterable)
    for element in iterator:
        yield chain([element], islice(iterator, size - 1))

def compute_training_sizes(train_perc, class_sizes, stratified=True):
    """Computes the maximum training size that the smallest class can provide"""
    size_per_class = np.int64(np.around(train_perc * class_sizes))
    if stratified:
        print('Different classes in training set are stratified to match smallest class!')
        size_per_class = np.minimum(np.min(size_per_class), size_per_class)
        reduced_sizes = np.unique(size_per_class)
        if len(reduced_sizes) != 1:
            raise ValueError('Error in stratification of training set based on smallest class!')
    total_test_samples = np.int64(np.sum(class_sizes) - sum(size_per_class))
    return (size_per_class, total_test_samples)

def file_comparison(files0, files1):
    """Compares two dictionaries of files returning their difference.

    {'created_files': [<files in files1 and not in files0>],
     'deleted_files': [<files in files0 and not in files1>],
     'modified_files': [<files in both files0 and files1 but different>]}"""
    comparison = {'created_files': [], 'deleted_files': [], 'modified_files': []}
    for path, sha1 in files1.items():
        if path in files0:
            if sha1 != files0[path]:
                comparison['modified_files'].append({'path': path, 'original_sha1': files0[path], 'sha1': sha1})
        else:
            comparison['created_files'].append({'path': path, 'sha1': sha1})
    for path, sha1 in files0.items():
        if path not in files1:
            comparison['deleted_files'].append({'path': path, 'original_sha1': files0[path]})
    return comparison

def extract_files(filesystem, files, path):
    """Extracts requested files.

    files must be a list of files in the format

        {"C:\\Windows\\System32\\NTUSER.DAT": "sha1_hash"} for windows
        {"/home/user/text.txt": "sha1_hash"} for other FS.

    files will be extracted into path which must exist beforehand.

    Returns two dictionaries:

        {"sha1": "/local/path/sha1"} files successfully extracted
        {"sha1": "C:\\..\\text.txt"} files which could not be extracted windows
        {"sha1": "/../text.txt"} files which could not be extracted linux"""
    extracted_files = {}
    failed_extractions = {}
    for file_to_extract in files:
        source = file_to_extract['path']
        destination = Path(path, file_to_extract['sha1'])
        if not destination.exists():
            destination = str(destination)
            try:
                filesystem.download(source, destination)
                extracted_files[file_to_extract['sha1']] = destination
            except RuntimeError:
                failed_extractions[file_to_extract['sha1']] = source
        else:
            extracted_files[file_to_extract['sha1']] = destination
    return (extracted_files, failed_extractions)

def registry_comparison(registry0, registry1):
    """Compares two dictionaries of registry keys returning their difference."""
    comparison = {'created_keys': {}, 'deleted_keys': [], 'created_values': {}, 'deleted_values': {}, 'modified_values': {}}
    for key, info in registry1.items():
        if key in registry0:
            if info[1] != registry0[key][1]:
                created, deleted, modified = compare_values(registry0[key][1], info[1])
                if created:
                    comparison['created_values'][key] = (info[0], created)
                if deleted:
                    comparison['deleted_values'][key] = (info[0], deleted)
                if modified:
                    comparison['modified_values'][key] = (info[0], modified)
        else:
            comparison['created_keys'][key] = info
    for key in registry0.keys():
        if key not in registry1:
            comparison['deleted_keys'].append(key)
    return comparison

def compare_values(values0, values1):
    """Compares all the values of a single registry key."""
    values0 = {v[0]: v[1:] for v in values0}
    values1 = {v[0]: v[1:] for v in values1}
    created = [(k, v[0], v[1]) for k, v in values1.items() if k not in values0]
    deleted = [(k, v[0], v[1]) for k, v in values0.items() if k not in values1]
    modified = [(k, v[0], v[1]) for k, v in values0.items() if v != values1.get(k, None)]
    return (created, deleted, modified)

def compare_hives(fs0, fs1):
    """Compares all the windows registry hive files
    returning those which differ."""
    registries = []
    for path in chain(registries_path(fs0.fsroot), user_registries(fs0, fs1)):
        if fs0.checksum(path) != fs1.checksum(path):
            registries.append(path)
    return registries

def user_registries(fs0, fs1):
    """Returns the list of user registries present on both FileSystems."""
    for user in fs0.ls('{}Users'.format(fs0.fsroot)):
        for path in user_registries_path(fs0.fsroot, user):
            if fs1.exists(path):
                yield path

def files_type(fs0, fs1, files):
    """Inspects the file type of the given files."""
    for file_meta in files['deleted_files']:
        file_meta['type'] = fs0.file(file_meta['path'])
    for file_meta in files['created_files'] + files['modified_files']:
        file_meta['type'] = fs1.file(file_meta['path'])
    return files

def files_size(fs0, fs1, files):
    """Gets the file size of the given files."""
    for file_meta in files['deleted_files']:
        file_meta['size'] = fs0.stat(file_meta['path'])['size']
    for file_meta in files['created_files'] + files['modified_files']:
        file_meta['size'] = fs1.stat(file_meta['path'])['size']
    return files

def makedirs(path):
