        path.mkdir(parents=True)

def parse_journal_file(journal_file):
    """Iterates over the journal's file taking care of paddings."""
    counter = count()
    for block in read_next_block(journal_file):
        block = remove_nullchars(block)
        while len(block) > MIN_RECORD_SIZE:
            header = RECORD_HEADER.unpack_from(block)
            size = header[0]
            try:
                yield parse_record(header, block[:size])
                next(counter)
            except RuntimeError:
                yield CorruptedUsnRecord(next(counter))
            finally:
                block = remove_nullchars(block[size:])
        journal_file.seek(-len(block), 1)

def parse_record(header, record):
    """Parses a record according to its version."""
    major_version = header[1]
    try:
        return RECORD_PARSER[major_version](header, record)
    except (KeyError, struct.error) as error:
        raise RuntimeError('Corrupted USN Record') from error

def unpack_flags(value, flags):
    """Multiple flags might be packed in the same field."""
    try:
        return [flags[value]]
    except KeyError:
        return [flags[k] for k in sorted(flags.keys()) if k & value > 0]

def read_next_block(infile, block_size=io.DEFAULT_BUFFER_SIZE):
    """Iterates over the file in blocks."""
    chunk = infile.read(block_size)
    while chunk:
        yield chunk
        chunk = infile.read(block_size)

def make_random_MLdataset(max_num_classes=20, min_class_size=20, max_class_size=50, max_dim=100, stratified=True):
    """Generates a random MLDataset for use in testing."""
    smallest = min(min_class_size, max_class_size)
    max_class_size = max(min_class_size, max_class_size)
    largest = max(50, max_class_size)
    largest = max(smallest + 3, largest)
    if max_num_classes != 2:
        num_classes = np.random.randint(2, max_num_classes, 1)
    else:
        num_classes = 2
    if type(num_classes) == np.ndarray:
        num_classes = num_classes[0]
    if not stratified:
        class_sizes = np.random.random_integers(smallest, largest, num_classes)
    else:
        class_sizes = np.repeat(np.random.randint(smallest, largest), num_classes)
    num_features = np.random.randint(min(3, max_dim), max(3, max_dim), 1)[0]
    class_ids = list()
    labels = list()
    for cl in range(num_classes):
        class_ids.append('class-{}'.format(cl))
        labels.append(int(cl))
    ds = MLDataset()
    for cc, class_ in enumerate(class_ids):
        subids = ['s{}-c{}'.format(ix, cc) for ix in range(class_sizes[cc])]
        for sid in subids:
            ds.add_sample(sid, feat_generator(num_features), int(cc), class_)
    return ds

