def _get_formatted_feature_dependencies(data):
    """Takes the format of the feature_order.json in featuremodel pool.
    Creates a list of conditions in the following format:
    ]
        dict(
            name='django_productline.features.admin',
            subject='django_productline',
            ctype='after'
        )
    ]
    :param data:
    :return: list"""
    conditions = list()
    for k, v in data.items():
        for feature in v.get('after', list()):
            conditions.append(dict(name=k, subject=feature, ctype='after'))
        if v.get('first', False):
            conditions.append(dict(name=k, subject=None, ctype='first'))
        if v.get('last', False):
            conditions.append(dict(name=k, subject=None, ctype='last'))
    return conditions

def fisher(x, k):
    """Fisher distribution
    """
    return k / (2 * np.sinh(k)) * np.exp(k * np.cos(x)) * np.sin(x)

def sin_fisher(y, k):
    """pdf for y=sin(x) if x is fisher-distributed with parameter k.  Support is [0,1).
    """
    return 1 / np.sqrt(1 - y ** 2) * (k / np.sinh(k) * y * np.cosh(k * np.sqrt(1 - y ** 2)))

def generate_veq(R=1.3, dR=0.1, Prot=6, dProt=0.1, nsamples=10000.0, plot=False, R_samples=None, Prot_samples=None):
    """Returns the mean and std equatorial velocity given R,dR,Prot,dProt

    Assumes all distributions are normal.  This will be used mainly for
    testing purposes; I can use MC-generated v_eq distributions when we go for real."""
    if R_samples is None:
        R_samples = R * (1 + rand.normal(size=nsamples) * dR)
    else:
        inds = rand.randint(len(R_samples), size=nsamples)
        R_samples = R_samples[inds]
    if Prot_samples is None:
        Prot_samples = Prot * (1 + rand.normal(size=nsamples) * dProt)
    else:
        inds = rand.randint(len(Prot_samples), size=nsamples)
        Prot_samples = Prot_samples[inds]
    veq_samples = 2 * np.pi * R_samples * RSUN / (Prot_samples * DAY) / 100000.0
    if plot:
        plt.hist(veq_samples, histtype='step', color='k', bins=50, normed=True)
        d = stats.norm(scale=veq_samples.std(), loc=veq_samples.mean())
        vs = np.linspace(veq_samples.min(), veq_samples.max(), 10000.0)
        plt.plot(vs, d.pdf(vs), 'r')
    return (veq_samples.mean(), veq_samples.std())

def like_cosi(cosi, vsini_dist, veq_dist, vgrid=None):
    """likelihood of Data (vsini_dist, veq_dist) given cosi
    """
    sini = np.sqrt(1 - cosi ** 2)
    def integrand(v):
        return vsini_dist(v * sini) * veq_dist(v)
    if vgrid is None:
        return quad(integrand, 0, np.inf)[0]
    else:
        return np.trapz(integrand(vgrid), vgrid)

def cosi_posterior(vsini_dist, veq_dist, vgrid=None, npts=100, vgrid_pts=1000):
    """returns posterior of cosI given dists for vsini and veq (incorporates unc. in vsini)
    """
    if vgrid is None:
        vgrid = np.linspace(min(veq_dist.ppf(0.001), vsini_dist.ppf(0.001)), max(veq_dist.ppf(0.999), vsini_dist.ppf(0.999)), vgrid_pts)
        logging.debug('vgrid: {} pts, {} to {}'.format(vgrid_pts, vgrid[0], vgrid[-1]))
    cs = np.linspace(0, 1, npts)
    Ls = cs * 0
    for i, c in enumerate(cs):
        Ls[i] = like_cosi(c, vsini_dist, veq_dist, vgrid=vgrid)
    if np.isnan(Ls[-1]):
        Ls[-1] = Ls[-2]
    Ls /= np.trapz(Ls, cs)
    return (cs, Ls)

def v_posts_from_dataframe(df, N=10000.0, alpha=0.23, l0=20, sigl=20):
    """names: Prot, e_Prot, R, e_R, vsini, e_vsini
    """
    vsini_posts = []
    veq_posts = []
    if 'ep_R' in df:
        for R, dR_p, dR_m, P, dP, v, dv in zip(df['R'], df['ep_R'], df['em_R'], df['Prot'], df['e_Prot'], df['vsini'], df['e_vsini']):
            vsini_posts.append(stats.norm(v, dv))
            if dR_p == dR_m:
                veq_posts.append(Veq_Posterior(R, dR_p, P, dP))
            else:
                R_dist = dists.fit_doublegauss(R, dR_m, dR_p)
                Prot_dist = stats.norm(P, dP)
                veq_posts.append(Veq_Posterior_General(R_dist, Prot_dist, N=N, l0=l0, sigl=sigl))
    else:
        for R, dR, P, dP, v, dv in zip(df['R'], df['e_R'], df['Prot'], df['e_Prot'], df['vsini'], df['e_vsini']):
            vsini_posts.append(stats.norm(v, dv))
            veq_posts.append(Veq_Posterior(R, dR, P, dP))
    return (vsini_posts, veq_posts)

def get_locals(f):
    """returns a formatted view of the local variables in a frame"""
    return pformat({i: f.f_locals[i] for i in f.f_locals if not i.startswith('__')})

def default_profiler(f, _type, _value):
    """inspects an input frame and pretty prints the following:

    <src-path>:<src-line> -> <function-name>
    <source-code>
    <local-variables>
    ----------------------------------------"""
    try:
        profile_print('\n'.join([get_frame_src(f), get_locals(f), '----------------------------------------']))
    except:
        pass

