        p[0] = [ast.ArrayElement(p[1], p[3], False, lineno=p.lineno(2))]

def p_function_call_parameter(p):
    """function_call_parameter : expr
    | AND variable"""
    if len(p) == 2:
        p[0] = ast.Parameter(p[1], False, lineno=p.lineno(1))
    else:
        p[0] = ast.Parameter(p[2], True, lineno=p.lineno(1))

def p_expr_function(p):
    """expr : FUNCTION is_reference LPAREN parameter_list RPAREN lexical_vars LBRACE inner_statement_list RBRACE"""
    p[0] = ast.Closure(p[4], p[6], p[8], p[2], lineno=p.lineno(1))

def p_lexical_var_list(p):
    """lexical_var_list : lexical_var_list COMMA AND VARIABLE
    | lexical_var_list COMMA VARIABLE
    | AND VARIABLE
    | VARIABLE"""
    if len(p) == 5:
        p[0] = p[1] + [ast.LexicalVariable(p[4], True, lineno=p.lineno(2))]
    elif len(p) == 4:
        p[0] = p[1] + [ast.LexicalVariable(p[3], False, lineno=p.lineno(2))]
    elif len(p) == 3:
        p[0] = [ast.LexicalVariable(p[2], True, lineno=p.lineno(1))]
    else:
        p[0] = [ast.LexicalVariable(p[1], False, lineno=p.lineno(1))]

def p_expr_ternary_op(p):
    """expr : expr QUESTION expr COLON expr"""
    p[0] = ast.TernaryOp(p[1], p[3], p[5], lineno=p.lineno(2))

def p_expr_include(p):
    """expr : INCLUDE expr"""
    p[0] = ast.Include(p[2], False, lineno=p.lineno(1))

def p_expr_include_once(p):
    """expr : INCLUDE_ONCE expr"""
    p[0] = ast.Include(p[2], True, lineno=p.lineno(1))

def p_expr_require(p):
    """expr : REQUIRE expr"""
    p[0] = ast.Require(p[2], False, lineno=p.lineno(1))

def p_expr_require_once(p):
    """expr : REQUIRE_ONCE expr"""
    p[0] = ast.Require(p[2], True, lineno=p.lineno(1))

def p_expr_exit(p):
    """expr : EXIT
    | EXIT LPAREN RPAREN
    | EXIT LPAREN expr RPAREN"""
    if len(p) == 5:
        p[0] = ast.Exit(p[3], lineno=p.lineno(1))
    else:
        p[0] = ast.Exit(None, lineno=p.lineno(1))

def p_scalar_namespace_name(p):
    """scalar : namespace_name
    | NS_SEPARATOR namespace_name
    | NAMESPACE NS_SEPARATOR namespace_name"""
    if len(p) == 2:
        p[0] = ast.Constant(p[1], lineno=p.lineno(1))
    elif len(p) == 3:
        p[0] = ast.Constant(p[1] + p[2], lineno=p.lineno(1))
    else:
        p[0] = ast.Constant(p[1] + p[2] + p[3], lineno=p.lineno(1))

def p_common_scalar_lnumber(p):
    """common_scalar : LNUMBER"""
    if p[1].startswith('0x'):
        p[0] = int(p[1], 16)
    elif p[1].startswith('0'):
        p[0] = int(p[1], 8)
    else:
        p[0] = int(p[1])

def p_common_scalar_magic_line(p):
    """common_scalar : LINE"""
    p[0] = ast.MagicConstant(p[1].upper(), p.lineno(1), lineno=p.lineno(1))

def p_common_scalar_magic_dir(p):
    """common_scalar : DIR"""
    value = getattr(p.lexer, 'filename', None)
    if value is not None:
        value = os.path.dirname(value)
    p[0] = ast.MagicConstant(p[1].upper(), value, lineno=p.lineno(1))

def p_common_scalar_magic_class(p):
    """common_scalar : CLASS_C"""
    p[0] = ast.MagicConstant(p[1].upper(), None, lineno=p.lineno(1))

def p_static_scalar(p):
    """static_scalar : common_scalar
    | QUOTE QUOTE
    | QUOTE ENCAPSED_AND_WHITESPACE QUOTE"""
    if len(p) == 2:
        p[0] = p[1]
    elif len(p) == 3:
        p[0] = ''
    else:
        p[0] = p[2].decode('string_escape')

def p_static_non_empty_array_pair_list_item(p):
    """static_non_empty_array_pair_list : static_non_empty_array_pair_list COMMA static_scalar
    | static_scalar"""
    if len(p) == 4:
        p[0] = p[1] + [ast.ArrayElement(None, p[3], False, lineno=p.lineno(2))]
    else:
        p[0] = [ast.ArrayElement(None, p[1], False, lineno=p.lineno(1))]

def p_static_non_empty_array_pair_list_pair(p):
    """static_non_empty_array_pair_list : static_non_empty_array_pair_list COMMA static_scalar DOUBLE_ARROW static_scalar
    | static_scalar DOUBLE_ARROW static_scalar"""
    if len(p) == 6:
        p[0] = p[1] + [ast.ArrayElement(p[3], p[5], False, lineno=p.lineno(2))]
    else:
        p[0] = [ast.ArrayElement(p[1], p[3], False, lineno=p.lineno(2))]

def p_namespace_name(p):
    """namespace_name : namespace_name NS_SEPARATOR STRING
    | STRING"""
    if len(p) == 4:
        p[0] = p[1] + p[2] + p[3]
    else:
        p[0] = p[1]

def p_encaps_list(p):
    """encaps_list : encaps_list encaps_var
    | empty"""
    if len(p) == 3:
        if p[1] == '':
            p[0] = p[2]
        else:
            p[0] = ast.BinaryOp('.', p[1], p[2], lineno=p.lineno(2))
    else:
        p[0] = ''

def p_encaps_list_string(p):
    """encaps_list : encaps_list ENCAPSED_AND_WHITESPACE"""
    if p[1] == '':
        p[0] = p[2].decode('string_escape')
    else:
        p[0] = ast.BinaryOp('.', p[1], p[2].decode('string_escape'), lineno=p.lineno(2))

def p_encaps_var_array_offset(p):
    """encaps_var : VARIABLE LBRACKET encaps_var_offset RBRACKET"""
    p[0] = ast.ArrayOffset(ast.Variable(p[1], lineno=p.lineno(1)), p[3], lineno=p.lineno(2))

def p_encaps_var_object_property(p):
    """encaps_var : VARIABLE OBJECT_OPERATOR STRING"""
    p[0] = ast.ObjectProperty(ast.Variable(p[1], lineno=p.lineno(1)), p[3], lineno=p.lineno(2))

def p_encaps_var_dollar_curly_array_offset(p):
    """encaps_var : DOLLAR_OPEN_CURLY_BRACES STRING_VARNAME LBRACKET expr RBRACKET RBRACE"""
    p[0] = ast.ArrayOffset(ast.Variable('$' + p[2], lineno=p.lineno(2)), p[4], lineno=p.lineno(3))

def validate_format_iso8601(validator, fieldname, value, format_option):
    '''validates the iso8601 format
    raises value error if the value for fieldname does not match the format
    is iso8601 eg #"2007-06-20T12:34:40+03:00"'''
    try:
        iso8601.parse_date(value)
    except ValueError:
        raise ValidationError("Value %(value)r of field '%(fieldname)s' is not in 'iso8601 YYYY-MM-DDThh:mm:ss(+/-)hh:mm' format" % locals())

def get_signature(name, func):
    """Helper to generate a readable signature for a function
    :param name:
    :param func:
    :return:"""
    args, varargs, keywords, defaults = inspect.getargspec(func)
    defaults = defaults or []
    posargslen = len(args) - len(defaults)
    if varargs is None and keywords is None:
        sig = name + '('
        sigargs = []
        for idx, arg in enumerate(args):
            if idx < posargslen:
                sigargs.append(arg)
            else:
                default = repr(defaults[idx - posargslen])
                sigargs.append(arg + '=' + default)
        sig += ', '.join(sigargs) + ')'
        return sig
    elif not args and varargs and (not keywords) and (not defaults):
        return name + '(*' + varargs + ')'
    else:
        raise InvalidTask('ape tasks may not use **kwargs')

def get_numbers(s):
    """Extracts all integers from a string an return them in a list"""
    result = map(int, re.findall('[0-9]+', unicode(s)))
    return result + [1] * (2 - len(result))

def to_etree(source, root_tag=None):
    """Convert various representations of an XML structure to a etree Element

        Args:
            source -- The source object to be converted - ET.Element\\ElementTree, dict or string.

        Keyword args:
            root_tag -- A optional parent tag in which to wrap the xml tree if no root in dict representation.
                    See dict_to_etree()

        Returns:
            A etree Element matching the source object.

    >>> to_etree("<content/>")  #doctest: +ELLIPSIS
    <Element content at 0x...>

    >>> to_etree({'document': {'title': 'foo', 'list': [{'li':1}, {'li':2}]}})  #doctest: +ELLIPSIS
    <Element document at 0x...>

    >>> to_etree(ET.Element('root'))  #doctest: +ELLIPSIS
    <Element root at 0x...>"""
    if hasattr(source, 'get_root'):
        return source.get_root()
    elif isinstance(source, type(ET.Element('x'))):
        return source
    elif isinstance(source, basestring):
        try:
            return ET.fromstring(source)
        except:
            raise XMLError(source)
    elif hasattr(source, 'keys'):
        return dict_to_etree(source, root_tag)
    else:
        raise XMLError(source)

def to_raw_xml(source):
    """Convert various representations of an XML structure to a normal XML string.

        Args:
            source -- The source object to be converted - ET.Element, dict or string.

        Returns:
            A rew xml string matching the source object.

    >>> to_raw_xml("<content/>")
    '<content/>'

    >>> to_raw_xml({'document': {'title': 'foo', 'list': [{'li':1}, {'li':2}]}})
    '<document><list><li>1</li><li>2</li></list><title>foo</title></document>'

    >>> to_raw_xml(ET.Element('root'))
    '<root/>'"""
    if isinstance(source, basestring):
        return source
    elif hasattr(source, 'getiterator'):
        return ET.tostring(source, encoding='utf-8')
    elif hasattr(source, 'keys'):
        xml_root = dict_to_etree(source)
        return ET.tostring(xml_root, encoding='utf-8')
    else:
        raise TypeError('Accepted representations of a document are string, dict and etree')

def cached(func):
    """A decorator function to cache values. It uses the decorated
    function's arguments as the keys to determine if the function
    has been called previously."""
    cache = {}
    @f.wraps(func)
    def wrapper(*args, **kwargs):
        key = func.__name__ + str(sorted(args)) + str(sorted(kwargs.items()))
        if key not in cache:
            cache[key] = func(*args, **kwargs)
        return cache[key]
    return wrapper

def retry_ex(callback, times=3, cap=120000):
    """Retry a callback function if any exception is raised.

    :param function callback: The function to call
    :keyword int times: Number of times to retry on initial failure
    :keyword int cap: Maximum wait time in milliseconds
    :returns: The return value of the callback
    :raises Exception: If the callback raises an exception after
      exhausting all retries"""
    for attempt in range(times + 1):
        if attempt > 0:
            time.sleep(retry_wait_time(attempt, cap) / 1000.0)
        try:
            return callback()
        except:
            if attempt == times:
                raise

def retryable(retryer=retry_ex, times=3, cap=120000):
    """A decorator to make a function retry. By default the retry
    occurs when an exception is thrown, but this may be changed
    by modifying the ``retryer`` argument.

    See also :py:func:`retry_ex` and :py:func:`retry_bool`. By
    default :py:func:`retry_ex` is used as the retry function.

    Note that the decorator must be called even if not given
    keyword arguments.

    :param function retryer: A function to handle retries
    :param int times: Number of times to retry on initial failure
    :param int cap: Maximum wait time in milliseconds

    :Example:

    ::

      @retryable()
      def can_fail():
          ....

      @retryable(retryer=retry_bool, times=10)
      def can_fail_bool():
          ...."""
    def _retryable(func):
        @f.wraps(func)
        def wrapper(*args, **kwargs):
            return retryer(lambda: func(*args, **kwargs), times, cap)
        return wrapper
    return _retryable

def parse_docstring(docstring):
    """Parse a PEP-257 docstring.

    SHORT -> blank line -> LONG"""
    short_desc = long_desc = ''
    if docstring:
        docstring = trim(docstring.lstrip('\n'))
        lines = docstring.split('\n\n', 1)
        short_desc = lines[0].strip().replace('\n', ' ')
        if len(lines) > 1:
            long_desc = lines[1].strip()
    return (short_desc, long_desc)

def remove_small_objects(image, min_size=50, connectivity=1):
