def ac3(space):
    """AC-3 algorithm. This reduces the domains of the variables by
    propagating constraints to ensure arc consistency.

    :param Space space: The space to reduce"""
    arcs = {}
    for name in space.variables:
        arcs[name] = set([])
    for const in space.constraints:
        for vname1, vname2 in product(const.vnames, const.vnames):
            if vname1 != vname2:
                arcs[vname1].add(vname2)
    for vname in space.variables:
        for const in space.constraints:
            _unary(space, const, vname)
    worklist = set([])
    for v1 in space.variables:
        for v2 in space.variables:
            for const in space.constraints:
                if _binary(space, const, v1, v2):
                    for name in arcs[v1]:
                        worklist.add((v1, name))
    while worklist:
        v1, v2 = worklist.pop()
        for const in space.constraints:
            if _binary(space, const, v1, v2):
                for vname in arcs[v1]:
                    worklist.add((v1, vname))

def _unary(space, const, name):
    """Reduce the domain of variable name to be node-consistent with this
    constraint, i.e. remove those values for the variable that are not
    consistent with the constraint.

    returns True if the domain of name was modified"""
    if not name in const.vnames:
        return False
    if space.variables[name].discrete:
        values = const.domains[name]
    else:
        values = const.domains[name]
    space.domains[name] = space.domains[name].intersection(values)
    return True

def _binary(space, const, name1, name2):
    """reduce the domain of variable name1 to be two-consistent (arc-consistent)
    with this constraint, i.e. remove those values for the variable name1,
    for which no values for name2 exist such that this pair is consistent
    with the constraint

    returns True if the domain of name1 was modified"""
    if not (name1 in const.vnames and name2 in const.vnames):
        return False
    remove = set([])
    for v1 in space.domains[name1].iter_members():
        for v2 in space.domains[name2].iter_members():
            if const.consistent({name1: v1, name2: v2}):
                break
        else:
            remove.add(v1)
    if len(remove) > 0:
        if space.variables[name1].discrete:
            remove = DiscreteSet(remove)
        else:
            remove = IntervalSet.from_values(remove)
        space.domains[name1] = space.domains[name1].difference(remove)
        return True
    else:
        return False

def get_task_parser(task):
    """Construct an ArgumentParser for the given task.

    This function returns a tuple (parser, proxy_args).
    If task accepts varargs only, proxy_args is True.
    If task accepts only positional and explicit keyword args,
    proxy args is False."""
    args, varargs, keywords, defaults = inspect.getargspec(task)
    defaults = defaults or []
    parser = argparse.ArgumentParser(prog='ape ' + task.__name__, add_help=False, description=task.__doc__, formatter_class=argparse.ArgumentDefaultsHelpFormatter)
    posargslen = len(args) - len(defaults)
    if varargs is None and keywords is None:
        for idx, arg in enumerate(args):
            if idx < posargslen:
                parser.add_argument(arg)
            else:
                default = defaults[idx - posargslen]
                parser.add_argument('--' + arg, default=default)
        return (parser, False)
    elif not args and varargs and (not keywords) and (not defaults):
        return (parser, True)
    else:
        raise InvalidTask(ERRMSG_UNSUPPORTED_SIG % task.__name__)

def invoke_task(task, args):
    """Parse args and invoke task function.

    :param task: task function to invoke
    :param args: arguments to the task (list of str)
    :return: result of task function
    :rtype: object"""
    parser, proxy_args = get_task_parser(task)
    if proxy_args:
        return task(*args)
    else:
        pargs = parser.parse_args(args)
        return task(**vars(pargs))

def run(args, features=None):
    """Run an ape task.

    Composes task modules out of the selected features and calls the
    task with arguments.

    :param args: list comprised of task name followed by arguments
    :param features: list of features to compose before invoking the task"""
    features = features or []
    for feature in features:
        tasks_module = get_task_module(feature)
        if tasks_module:
            tasks.superimpose(tasks_module)
    if len(args) < 2 or (len(args) == 2 and args[1] == 'help'):
        tasks.help()
    else:
        taskname = args[1]
        try:
            task = tasks.get_task(taskname, include_helpers=False)
        except TaskNotFound:
            print('Task "%s" not found! Use "ape help" to get usage information.' % taskname)
        else:
            remaining_args = args[2:] if len(args) > 2 else []
            invoke_task(task, remaining_args)

def download(url, file=None):
    """Pass file as a filename, open file object, or None to return the request bytes

    Args:
        url (str): URL of file to download
        file (Union[str, io, None]): One of the following:
             - Filename of output file
             - File opened in binary write mode
             - None: Return raw bytes instead

    Returns:
        Union[bytes, None]: Bytes of file if file is None"""
    import urllib.request
    import shutil
    if isinstance(file, str):
        file = open(file, 'wb')
    try:
        with urllib.request.urlopen(url) as response:
            if file:
                shutil.copyfileobj(response, file)
            else:
                return response.read()
    finally:
        if file:
            file.close()

def download_extract_tar(tar_url, folder, tar_filename=''):
    """Download and extract the tar at the url to the given folder

    Args:
        tar_url (str): URL of tar file to download
        folder (str): Location of parent directory to extract to. Doesn't have to exist
        tar_filename (str): Location to download tar. Default is to a temp file"""
    try:
        makedirs(folder)
    except OSError:
        if not isdir(folder):
            raise
    data_file = tar_filename
    if not data_file:
        fd, data_file = mkstemp('.tar.gz')
        download(tar_url, os.fdopen(fd, 'wb'))
    else:
        download(tar_url, data_file)
    with tarfile.open(data_file) as tar:
        tar.extractall(path=folder)

def html_to_text(html, base_url='', bodywidth=CONFIG_DEFAULT):
    """Convert a HTML mesasge to plain text."""
    def _patched_handle_charref(c):
        self = h
        charref = self.charref(c)
        if self.code or self.pre:
            charref = cgi.escape(charref)
        self.o(charref, 1)
    def _patched_handle_entityref(c):
        self = h
        entityref = self.entityref(c)
        if self.code or self.pre:
            entityref = cgi.escape(entityref)
        self.o(entityref, 1)
    h = HTML2Text(baseurl=base_url, bodywidth=config.BODY_WIDTH if bodywidth is CONFIG_DEFAULT else bodywidth)
    h.handle_entityref = _patched_handle_entityref
    h.handle_charref = _patched_handle_charref
    return h.handle(html).rstrip()

def _make_links_absolute(html, base_url):
    """Make all links absolute."""
    url_changes = []
    soup = BeautifulSoup(html)
    for tag in soup.find_all('a', href=True):
        old = tag['href']
        fixed = urljoin(base_url, old)
        if old != fixed:
            url_changes.append((old, fixed))
            tag['href'] = fixed
    for tag in soup.find_all('img', src=True):
        old = tag['src']
        fixed = urljoin(base_url, old)
        if old != fixed:
            url_changes.append((old, fixed))
            tag['src'] = fixed
    return (mark_safe(six.text_type(soup)), url_changes)

def add_to_gitignore(line: str):
    """Adds a line to the .gitignore file of the repo

    Args:
        line: line to add"""
    if not line.endswith('\n'):
        line = f'{line}\n'
    if GIT_IGNORE.exists():
        if line in GIT_IGNORE.read_text(encoding='utf8'):
            return
        previous_content = GIT_IGNORE.read_text(encoding='utf8')
    else:
        previous_content = ''
    GIT_IGNORE.write_text(previous_content + line, encoding='utf8')

def hardware_info():
    """Returns basic hardware information about the computer.

    Gives actual number of CPU's in the machine, even when hyperthreading is
    turned on.

    Returns
    -------
    info : dict
        Dictionary containing cpu and memory information."""
    try:
        if sys.platform == 'darwin':
            out = _mac_hardware_info()
        elif sys.platform == 'win32':
            out = _win_hardware_info()
        elif sys.platform in ['linux', 'linux2']:
            out = _linux_hardware_info()
        else:
            out = {}
    except:
        return {}
    else:
        return out

def shell_exec(command, **kwargs):
    """Excecutes the given command silently.
    """
    proc = Popen(shlex.split(command), stdout=PIPE, stderr=PIPE, **kwargs)
    out, err = [x.decode('utf-8') for x in proc.communicate()]
    return {'out': out, 'err': err, 'code': proc.returncode}

