def hexdump(src, length=16, sep='.'):
    """Returns src in hex dump.
    From https://gist.github.com/ImmortalPC/c340564823f283fe530b

    :param length: Nb Bytes by row.
    :param sep: For the text part, sep will be used for non ASCII char.
    :return: The hexdump"""
    result = []
    for i in range(0, len(src), length):
        sub_src = src[i:i + length]
        hexa = ''
        for h in range(0, len(sub_src)):
            if h == length / 2:
                hexa += ' '
            h = sub_src[h]
            if not isinstance(h, int):
                h = ord(h)
            h = hex(h).replace('0x', '')
            if len(h) == 1:
                h = '0' + h
            hexa += h + ' '
        hexa = hexa.strip(' ')
        text = ''
        for c in sub_src:
            if not isinstance(c, int):
                c = ord(c)
            if 32 <= c < 127:
                text += chr(c)
            else:
                text += sep
        result.append(('%08X:  %-' + str(length * (2 + 1) + 1) + 's  |%s|') % (i, hexa, text))
    return '\n'.join(result)

def main(argv=None):
    """Entry point

    :param argv: Program arguments"""
    parser = argparse.ArgumentParser(description='Multicast packets spy')
    parser.add_argument('-g', '--group', dest='group', default='239.0.0.1', help='Multicast target group (address)')
    parser.add_argument('-p', '--port', type=int, dest='port', default=42000, help='Multicast target port')
    parser.add_argument('-d', '--debug', action='store_true', dest='debug', help='Set logger to DEBUG level')
    parser.add_argument('-v', '--verbose', action='store_true', dest='verbose', help='Verbose output')
    args = parser.parse_args(argv)
    if args.debug:
        logging.basicConfig(level=logging.DEBUG)
    else:
        logging.basicConfig(level=logging.WARNING)
    try:
        return run_spy(args.group, args.port, args.verbose)
    except Exception as ex:
        logging.exception('Error running spy: %s', ex)
    return 1

def read_csv_arg_preprocess(abspath, memory_usage=100 * 1000 * 1000):
    """Automatically decide if we need to use iterator mode to read a csv file.

    :param abspath: csv file absolute path.
    :param memory_usage: max memory will be used for pandas.read_csv()."""
    if memory_usage < 1000 * 1000:
        raise ValueError('Please specify a valid memory usage for read_csv, the value should larger than 1MB and less than your available memory.')
    size = os.path.getsize(abspath)
    n_time = math.ceil(size * 1.0 / memory_usage)
    lines = count_lines(abspath)
    chunksize = math.ceil(lines / n_time)
    if chunksize >= lines:
        iterator = False
        chunksize = None
    else:
        iterator = True
    return (iterator, chunksize)

