def stashed(func):
    """Simple decorator to stash changed files between a destructive repo operation"""
    @functools.wraps(func)
    def _wrapper(*args, **kwargs):
        if CTX.stash and (not CTX.repo.stashed):
            CTX.repo.stash(func.__name__)
            try:
                func(*args, **kwargs)
            finally:
                CTX.repo.unstash()
        else:
            func(*args, **kwargs)
    return _wrapper

def list_to_rows(src, size):
    """A generator that takes a enumerable item and returns a series of
    slices. Useful for turning a list into a series of rows.

    >>> list(list_to_rows([1, 2, 3, 4, 5, 6, 7], 3))
    [[1, 2, 3], [4, 5, 6], [7, ]]"""
    row = []
    for item in src:
        row.append(item)
        if len(row) == size:
            yield row
            row = []
    if row:
        yield row

def head_tail_middle(src):
    """Returns a tuple consisting of the head of a enumerable, the middle
    as a list and the tail of the enumerable. If the enumerable is 1 item, the
    middle will be empty and the tail will be None.

    >>> head_tail_middle([1, 2, 3, 4])
    1, [2, 3], 4"""
    if len(src) == 0:
        return (None, [], None)
    if len(src) == 1:
        return (src[0], [], None)
    if len(src) == 2:
        return (src[0], [], src[1])
    return (src[0], src[1:-1], src[-1])

def uconf(**kwargs):
    """Function to set a default namespace/include.
    It returns a decorator with the namespace/include argument already set.
    Arguments:
        - include: A custom URL list, previously
                   set on the module's urls.py;
        - namespace: the URL's namespace."""
    if len(kwargs) != 1:
        raise TypeError('uconf() takes exactly 1 argument. ({} given)'.format(len(kwargs)))
    arg_name = list(kwargs.keys()).pop(0)
    if arg_name not in ['include', 'namespace']:
        raise TypeError('Invalid argument: {}'.format(arg_name))
    return partial(umap, **kwargs)

def rmtree_errorhandler(func, path, exc_info):
    """On Windows, the files in .svn are read-only, so when rmtree() tries to
    remove them, an exception is thrown.  We catch that here, remove the
    read-only attribute, and hopefully continue without problems."""
    exctype, value = exc_info[:2]
    if not (exctype is WindowsError and value.args[0] == 5 or (exctype is OSError and value.args[0] == 13)):
        raise
    if os.stat(path).st_mode & stat.S_IREAD != stat.S_IREAD:
        raise
    os.chmod(path, stat.S_IWRITE)
    func(path)

