    return False

def __compact_notification_addresses(addresses_):
    """Input::

        {
            'default': 'http://domain/notice',
            'event1': 'http://domain/notice',
            'event2': 'http://domain/notice',
            'event3': 'http://domain/notice3',
            'event4': 'http://domain/notice3'
        }

    Output::

        {
            'default': 'http://domain/notice',
            'event1,event2': 'http://domain/notice',
            'event3,event4': 'http://domain/notice3'
        }"""
    result = {}
    addresses = dict(addresses_)
    default = addresses.pop('default', None)
    for key, value in __reverse_group_dict(addresses).items():
        result[','.join(value)] = key
    if default:
        result['default'] = default
    return result

def makeRetweetNetwork(tweets):
    """Receives tweets, returns directed retweet networks.

    Without and with isolated nodes."""
    G = x.DiGraph()
    G_ = x.DiGraph()
    for tweet in tweets:
        text = tweet['text']
        us = tweet['user']['screen_name']
        if text.startswith('RT @'):
            prev_us = text.split(':')[0].split('@')[1]
            if G.has_edge(prev_us, us):
                G[prev_us][us]['weight'] += 1
                G_[prev_us][us]['weight'] += 1
            else:
                G.add_edge(prev_us, us, weight=1.0)
                G_.add_edge(prev_us, us, weight=1.0)
        if us not in G_.nodes():
            G_.add_node(us)
    return (G, G_)

