def begin_commit():
    """Allow a client to begin a commit and acquire the write lock"""
    session_token = request.headers['session_token']
    repository = request.headers['repository']
    current_user = have_authenticated_user(request.environ['REMOTE_ADDR'], repository, session_token)
    if current_user is False:
        return fail(user_auth_fail_msg)
    repository_path = config['repositories'][repository]['path']
    def with_exclusive_lock():
        if not can_aquire_user_lock(repository_path, session_token):
            return fail(lock_fail_msg)
        data_store = versioned_storage(repository_path)
        if data_store.get_head() != request.headers['previous_revision']:
            return fail(need_to_update_msg)
        if data_store.have_active_commit():
            data_store.rollback()
        data_store.begin()
        update_user_lock(repository_path, session_token)
        return success()
    return lock_access(repository_path, with_exclusive_lock)

def push_file():
    """Push a file to the server"""
    session_token = request.headers['session_token']
    repository = request.headers['repository']
    current_user = have_authenticated_user(request.environ['REMOTE_ADDR'], repository, session_token)
    if current_user is False:
        return fail(user_auth_fail_msg)
    repository_path = config['repositories'][repository]['path']
    def with_exclusive_lock():
        if not varify_user_lock(repository_path, session_token):
            return fail(lock_fail_msg)
        data_store = versioned_storage(repository_path)
        if not data_store.have_active_commit():
            return fail(no_active_commit_msg)
        file_path = request.headers['path']
        if any((True for item in re.split('\\\\|/', file_path) if item in ['..', '.'])):
            return fail()
        tmp_path = cpjoin(repository_path, 'tmp_file')
        with open(tmp_path, 'wb') as f:
            while True:
                chunk = request.stream.read(1000 * 1000)
                if chunk == b'':
                    break
                f.write(chunk)
        data_store.fs_put_from_file(tmp_path, {'path': file_path})
        update_user_lock(repository_path, session_token)
        return success()
    return lock_access(repository_path, with_exclusive_lock)

def delete_files():
    """Delete one or more files from the server"""
    session_token = request.headers['session_token']
    repository = request.headers['repository']
    current_user = have_authenticated_user(request.environ['REMOTE_ADDR'], repository, session_token)
    if current_user is False:
        return fail(user_auth_fail_msg)
    repository_path = config['repositories'][repository]['path']
    body_data = request.get_json()
    def with_exclusive_lock():
        if not varify_user_lock(repository_path, session_token):
            return fail(lock_fail_msg)
        try:
            data_store = versioned_storage(repository_path)
            if not data_store.have_active_commit():
                return fail(no_active_commit_msg)
            for fle in json.loads(body_data['files']):
                data_store.fs_delete(fle)
            update_user_lock(repository_path, session_token)
            return success()
        except Exception:
            return fail()
    return lock_access(repository_path, with_exclusive_lock)

def commit():
    """Commit changes and release the write lock"""
    session_token = request.headers['session_token']
    repository = request.headers['repository']
    current_user = have_authenticated_user(request.environ['REMOTE_ADDR'], repository, session_token)
    if current_user is False:
        return fail(user_auth_fail_msg)
    repository_path = config['repositories'][repository]['path']
    def with_exclusive_lock():
        if not varify_user_lock(repository_path, session_token):
            return fail(lock_fail_msg)
        data_store = versioned_storage(repository_path)
        if not data_store.have_active_commit():
            return fail(no_active_commit_msg)
        result = {}
        if request.headers['mode'] == 'commit':
            new_head = data_store.commit(request.headers['commit_message'], current_user['username'])
            result = {'head': new_head}
        else:
            data_store.rollback()
        update_user_lock(repository_path, None)
        return success(result)
    return lock_access(repository_path, with_exclusive_lock)

def is_same_dict(d1, d2):
    """Test two dictionary is equal on values. (ignore order)
    """
    for k, v in d1.items():
        if isinstance(v, dict):
            is_same_dict(v, d2[k])
        else:
            assert d1[k] == d2[k]
    for k, v in d2.items():
        if isinstance(v, dict):
            is_same_dict(v, d1[k])
        else:
            assert d1[k] == d2[k]

def user_homedir(username=None):
    """Returns a user's home directory.

    If no username is specified, returns the current user's homedir."""
    if username:
        return os.path.expanduser('~%s/' % username)
    elif 'HOME' in os.environ:
        return os.environ['HOME']
    elif os.name == 'posix':
        return os.path.expanduser('~/')
    else:
        raise RuntimeError('This function has failed at life.')

def glob(*args):
    """Returns list of paths matching one or more wildcard patterns.

    Args:
      include_dirs: Include directories in the output"""
    if len(args) is 1 and isinstance(args[0], list):
        args = args[0]
    matches = []
    for pattern in args:
        for item in glob2.glob(pattern):
            if not os.path.isdir(item):
                matches.append(item)
    return matches

def linkorcopy(src, dst):
    """Hardlink src file to dst if possible, otherwise copy."""
    if not os.path.isfile(src):
        raise error.ButcherError('linkorcopy called with non-file source. (src: %s  dst: %s)' % src, dst)
    elif os.path.isdir(dst):
        dst = os.path.join(dst, os.path.basename(src))
    elif os.path.exists(dst):
        os.unlink(dst)
    elif not os.path.exists(os.path.dirname(dst)):
        os.makedirs(os.path.dirname(dst))
    try:
        os.link(src, dst)
        log.debug('Hardlinked: %s -> %s', src, dst)
    except OSError:
        shutil.copy2(src, dst)
        log.debug("Couldn't hardlink. Copied: %s -> %s", src, dst)

