def is_rhyme(d, w1, w2):
    """check if words rhyme"""
    for p1 in d[w1]:
        p1 = p1.split("'")[-1]
        m = VOWELS_RE.search(p1)
        if not m:
            print(p1)
        p1 = p1[m.start():]
        for p2 in d[w2]:
            p2 = p2.split("'")[-1]
            m = VOWELS_RE.search(p2)
            if not m:
                print(w2, p2)
            p2 = p2[m.start():]
            if p1 == p2:
                return True
    return False

def init_perfect_ttable(words):
    """initialize (normalized) theta according to whether words rhyme"""
    d = read_celex()
    not_in_dict = 0
    n = len(words)
    t_table = numpy.zeros((n, n + 1))
    for r, w in enumerate(words):
        if w not in d:
            not_in_dict += 1
        for c, v in enumerate(words):
            if c < r:
                t_table[r, c] = t_table[c, r]
            elif w in d and v in d:
                t_table[r, c] = int(is_rhyme(d, w, v)) + 0.001
            else:
                t_table[r, c] = random.random()
        t_table[r, n] = random.random()
    print(not_in_dict, 'of', n, ' words are not in CELEX')
    for c in range(n + 1):
        tot = sum(t_table[:, c])
        for r in range(n):
            t_table[r, c] = t_table[r, c] / tot
    return t_table

def shell(database='default'):
    """Runs the command-line client for the specified database.
    """
    target = engine[database]
    dialect = engine[database].dialect.name
    if dialect == 'mysql':
        args = ['mysql']
        if target.url.username:
            args += ['--user=%s' % target.url.username]
        if target.url.password:
            args += ['--password=%s' % target.url.password]
        if 'unix_socket' in target.url.query:
            args += ['--socket=%s' % target.url.query['unix_socket']]
        elif target.url.host:
            args += ['--host=%s' % target.url.host]
            if target.url.port:
                args += ['--port=%s' % target.url.port]
        if target.url.database:
            args += [target.url.database]
    elif dialect == 'sqlite':
        args = ['sqlite3', target.url.database]
    else:
        raise RuntimeError('Database shell not available for the dialect %r' % dialect)
    os.execvp(args[0], args)

def strip_encoding_cookie(filelike):
    """Generator to pull lines from a text-mode file, skipping the encoding
    cookie if it is found in the first two lines."""
    it = iter(filelike)
    try:
        first = next(it)
        if not cookie_comment_re.match(first):
            yield first
        second = next(it)
        if not cookie_comment_re.match(second):
            yield second
    except StopIteration:
        return
    for line in it:
        yield line

def source_to_unicode(txt, errors='replace', skip_encoding_cookie=True):
    """Converts a bytes string with python source code to unicode.
    Unicode strings are passed through unchanged. Byte strings are checked
    for the python source file encoding cookie to determine encoding.
    txt can be either a bytes buffer or a string containing the source
    code."""
    if isinstance(txt, six.text_type):
        return txt
    if isinstance(txt, six.binary_type):
        buffer = io.BytesIO(txt)
    else:
        buffer = txt
    try:
        encoding, _ = detect_encoding(buffer.readline)
    except SyntaxError:
        encoding = 'ascii'
    buffer.seek(0)
    newline_decoder = io.IncrementalNewlineDecoder(None, True)
    text = io.TextIOWrapper(buffer, encoding, errors=errors, line_buffering=True)
    text.mode = 'r'
    if skip_encoding_cookie:
        return u''.join(strip_encoding_cookie(text))
    else:
        return text.read()

def decode_source(source_bytes):
    """Decode bytes representing source code and return the string.
    Universal newline support is used in the decoding."""
    newline_decoder = io.IncrementalNewlineDecoder(None, True)
    return newline_decoder.decode(source_to_unicode(source_bytes))

def requires_subrepo(func: Callable) -> Callable:
    """Decorator that requires the `git subrepo` command to be accessible before calling the given function.
    :param func: the function to wrap
    :return: the wrapped function"""
    def decorated(*args, **kwargs):
        try:
            run([GIT_COMMAND, _GIT_SUBREPO_COMMAND, '--version'])
        except RunException as e:
            raise RuntimeError('`git subrepo` does not appear to be working') from e
        return func(*args, **kwargs)
    return decorated

def status(directory: str) -> Tuple[RepositoryLocation, Branch, Commit]:
    """Gets the status of the subrepo that has been cloned into the given directory.
    :param directory: the directory containing the subrepo
    :return: a tuple consisting of the URL the subrepo is tracking, the branch that has been checked out and the commit
    reference"""
    if not os.path.exists(directory):
        raise ValueError(f'No subrepo found in "{directory}"')
    try:
        result = run([GIT_COMMAND, _GIT_SUBREPO_COMMAND, _GIT_SUBREPO_STATUS_COMMAND, _GIT_SUBREPO_VERBOSE_FLAG, get_directory_relative_to_git_root(directory)], execution_directory=get_git_root_directory(directory))
    except RunException as e:
        if "Command failed: 'git rev-parse --verify HEAD'" in e.stderr:
            raise NotAGitSubrepoException(directory) from e
        raise e
    if re.search('is not a subrepo$', result):
        raise NotAGitSubrepoException(directory)
    url = re.search('Remote URL:\\s*(.*)', result).group(1)
    branch = re.search('Tracking Branch:\\s*(.*)', result).group(1)
    commit = re.search('Pulled Commit:\\s*(.*)', result).group(1)
    return (url, branch, commit)

def pull(directory: str) -> Commit:
    """Pulls the subrepo that has been cloned into the given directory.
    :param directory: the directory containing the subrepo
    :return: the commit the subrepo is on"""
    if not os.path.exists(directory):
        raise ValueError(f'No subrepo found in "{directory}"')
    try:
        result = run([GIT_COMMAND, _GIT_SUBREPO_COMMAND, _GIT_SUBREPO_PULL_COMMAND, _GIT_SUBREPO_VERBOSE_FLAG, get_directory_relative_to_git_root(directory)], execution_directory=get_git_root_directory(directory))
    except RunException as e:
        if "Can't pull subrepo. Working tree has changes" in e.stderr:
            raise UnstagedChangeException() from e
    return status(directory)[2]

def translate(client, event, channel, nick, rest):
    """Translate a phrase using Google Translate. First argument should be
    the language[s]. It is a 2 letter abbreviation. It will auto detect
    the orig lang if you only give one; or two languages joined by a |,
    for example 'en|de' to trans from English to German. Follow this by
    the phrase you want to translate."""
    try:
        set_key()
    except Exception:
        return "No API key configured. Google charges for translation. Please register for an API key at https://code.google.com/apis/console/?api=translate&promo=tr and set the 'Google API key' config variable to a valid key"
    rest = rest.strip()
