def match_classes(allowed_classes):
    """Creates a matcher that matches a list/tuple of allowed classes."""
    cleaned_allowed_classes = [utils.cls_to_cls_name(tmp_cls) for tmp_cls in allowed_classes]
    def matcher(cause):
        cause_cls = None
        cause_type_name = cause.exception_type_names[0]
        try:
            cause_cls_idx = cleaned_allowed_classes.index(cause_type_name)
        except ValueError:
            pass
        else:
            cause_cls = allowed_classes[cause_cls_idx]
            if not isinstance(cause_cls, type):
                cause_cls = importutils.import_class(cause_cls)
            cause_cls = ensure_base_exception(cause_type_name, cause_cls)
        return cause_cls
    return matcher

def combine_or(matcher, *more_matchers):
    """Combines more than one matcher together (first that matches wins)."""
    def matcher(cause):
        for sub_matcher in itertools.chain([matcher], more_matchers):
            cause_cls = sub_matcher(cause)
            if cause_cls is not None:
                return cause_cls
        return None
    return matcher

def run_cmd(cmd, log='log.log', cwd='.', stdout=sys.stdout, bufsize=1, encode='utf-8'):
    """Runs a command in the backround by creating a new process and writes the output to a specified log file.

    :param log(str) - log filename to be used
    :param cwd(str) - basedir to write/create the log file
    :param stdout(pipe) - stdout process pipe (can be default stdout, a file, etc)
    :param bufsize(int) - set the output buffering, default is 1 (per line)
    :param encode(str) - string encoding to decode the logged content, default is utf-8

    Returns:
      The process object"""
    logfile = '%s/%s' % (cwd, log)
    if os.path.exists(logfile):
        os.remove(logfile)
    proc_args = {'stdout': subprocess.PIPE, 'stderr': subprocess.PIPE, 'cwd': cwd, 'universal_newlines': True}
    proc = subprocess.Popen(cmd, **proc_args)
    while True:
        line = proc.stdout.readline()
        if proc.poll() is None:
            stdout.write(line)
        else:
            break
    out, err = proc.communicate()
    with open(logfile, 'w') as f:
        if out:
            f.write(out)
        else:
            f.write(err)

