    if default:
        legend = '[y]/n'
    else:
        legend = 'y/[n]'
    res = ''
    while res != 'y' and res != 'n':
        res = raw_input(text + ' ({}): '.format(legend)).lower()
        if not res and default:
            res = 'y'
        elif not res and (not default):
            res = 'n'
