def make_basic_daemon(workspace=None):
    """Make basic daemon.
    """
    workspace = workspace or os.getcwd()
    if os.fork():
        os._exit(0)
    os.chdir(workspace)
    os.setsid()
    os.umask(18)
    if os.fork():
        os._exit(0)
    null = os.open('/dev/null', os.O_RDWR)
    try:
        for i in range(0, 3):
            try:
                os.dup2(null, i)
            except OSError as error:
                if error.errno != errno.EBADF:
                    raise
    finally:
        os.close(null)

