def base64url_decode(msg):
    '''Decode a base64 message based on JWT spec, Appendix B.
    "Notes on implementing base64url encoding without padding"'''
    rem = len(msg) % 4
    if rem:
        msg += b'=' * (4 - rem)
    return base64.urlsafe_b64decode(msg)

def _jws_header(keyid, algorithm):
    """Produce a base64-encoded JWS header."""
    data = {'typ': 'JWT', 'alg': algorithm.name, 'kid': keyid}
    datajson = json.dumps(data, sort_keys=True).encode('utf8')
    return base64url_encode(datajson)

def _jws_signature(signdata, privkey, algorithm):
    """Produce a base64-encoded JWS signature based on the signdata
    specified, the privkey instance, and the algorithm passed."""
    signature = algorithm.sign(privkey, signdata)
    return base64url_encode(signature)

def class_in_progress(stack=None):
    """True if currently inside a class definition, else False."""
    if stack is None:
        stack = inspect.stack()
    for frame in stack:
        statement_list = frame[4]
        if statement_list is None:
            continue
        if statement_list[0].strip().startswith('class '):
            return True
    return False

def execCommand(Argv, collect_missing):
    """Executes the given task with parameters.
    """
    try:
        return _execCommand(Argv, collect_missing)
    except Exception as e:
        if Settings['errorHandler']:
            Settings['errorHandler'](e)
        if Settings['debug']:
            import pdb
            pdb.post_mortem(sys.exc_info()[2])
        if not Settings['silent']:
            import traceback
            etype, value, tb = sys.exc_info()
            tb = tb.tb_next.tb_next
            message = ''.join(traceback.format_exception(etype, value, tb))[:-1]
        else:
            if isinstance(e, HandledException):
                raise e
            message = str(e)
        raise HandledException(message)

def getDescendant(Ancestor, RouteParts):
    """Resolves a descendant, of the given Ancestor, as pointed by the RouteParts.
    """
    if not RouteParts:
        return Ancestor
    Resolved = Ancestor.Members.get(RouteParts.pop(0))
    if isinstance(Resolved, Group):
        return getDescendant(Resolved, RouteParts)
    else:
        return Resolved

def _execCommand(Argv, collect_missing):
    """Worker of execCommand.
    """
    if not Argv:
        raise HandledException('Please specify a command!')
    RouteParts = Argv[0].split('/')
    Args, KwArgs = getDigestableArgs(Argv[1:])
    ResolvedMember = getDescendant(BaseGroup, RouteParts[:])
    if isinstance(ResolvedMember, Group):
        raise HandledException('Please specify a task.', Member=ResolvedMember)
    if not isinstance(ResolvedMember, Task):
        raise HandledException('No such task.', Member=BaseGroup)
    return ResolvedMember.__collect_n_call__(*Args, **KwArgs) if collect_missing else ResolvedMember(*Args, **KwArgs)

def memoize(fn):
    """Cache the results of a function that only takes positional arguments."""
    cache = {}
    @wraps(fn)
    def wrapped_function(*args):
        if args in cache:
            return cache[args]
        else:
            result = fn(*args)
            cache[args] = result
            return result
    return wrapped_function

def get_supported_file_loaders_2(force=False):
    """Returns a list of file-based module loaders.
    Each item is a tuple (loader, suffixes)."""
    if force or (2, 7) <= sys.version_info < (3, 4):
        import imp
        loaders = []
        for suffix, mode, type in imp.get_suffixes():
            if type == imp.PY_SOURCE:
                loaders.append((SourceFileLoader2, [suffix]))
            else:
                loaders.append((ImpFileLoader2, [suffix]))
        return loaders
    elif sys.version_info >= (3, 4):
        from importlib.machinery import SOURCE_SUFFIXES, SourceFileLoader, BYTECODE_SUFFIXES, SourcelessFileLoader, EXTENSION_SUFFIXES, ExtensionFileLoader
        extensions = (ExtensionFileLoader, EXTENSION_SUFFIXES)
        source = (SourceFileLoader, SOURCE_SUFFIXES)
        bytecode = (SourcelessFileLoader, BYTECODE_SUFFIXES)
        return [extensions, source, bytecode]

def filehandles(path, openers_list=openers, pattern='', verbose=False):
    """Main function that iterates over list of openers and decides which opener to use.

    :param str path: Path.
    :param list openers_list: List of openers.
    :param str pattern: Regular expression pattern.
    :param verbose: Print additional information.
    :type verbose: :py:obj:`True` or :py:obj:`False`
    :return: Filehandle(s)."""
    if not verbose:
        logging.disable(logging.VERBOSE)
    for opener in openers_list:
        try:
            for filehandle in opener(path=path, pattern=pattern, verbose=verbose):
                with closing(filehandle):
                    yield filehandle
            break
        except (zipfile.BadZipfile, tarfile.ReadError, GZValidationError, BZ2ValidationError, IOError, NotADirectoryError):
            continue
        else:
            logger.verbose('No opener found for path: "{}"'.format(path))
            yield None

def directory_opener(path, pattern='', verbose=False):
    """Directory opener.

    :param str path: Path.
    :param str pattern: Regular expression pattern.
    :return: Filehandle(s)."""
    if not os.path.isdir(path):
        raise NotADirectoryError
    else:
        openers_list = [opener for opener in openers if not opener.__name__.startswith('directory')]
        for root, dirlist, filelist in os.walk(path):
            for filename in filelist:
                if pattern and (not re.match(pattern, filename)):
                    logger.verbose('Skipping file: {}, did not match regex pattern "{}"'.format(os.path.abspath(filename), pattern))
                    continue
                filename_path = os.path.abspath(os.path.join(root, filename))
                for filehandle in filehandles(filename_path, openers_list=openers_list, pattern=pattern, verbose=verbose):
                    yield filehandle

def format_obj_keys(obj, formatter):
    """Take a dictionary with string keys and recursively convert
    all keys from one form to another using the formatting function.

    The dictionary may contain lists as values, and any nested
    dictionaries within those lists will also be converted.

    :param object obj: The object to convert
    :param function formatter: The formatting function
      for keys, which takes and returns a string
    :returns: A new object with keys converted
    :rtype: object

    :Example:

    ::

      >>> obj = {
      ...     'dict-list': [
      ...         {'one-key': 123, 'two-key': 456},
      ...         {'threeKey': 789, 'four-key': 456},
      ...     ],
      ...     'some-other-key': 'some-unconverted-value'
      ... }
      >>> format_obj_keys(obj, lambda s: s.upper())
      {
          'DICT-LIST': [
              {'ONE-KEY': 123, 'TWO-KEY': 456},
              {'FOUR-KEY': 456, 'THREE-KEY': 789}
          ],
          'SOME-OTHER-KEY': 'some-unconverted-value'
      }"""
    if type(obj) == list:
        return [format_obj_keys(o, formatter) for o in obj]
    elif type(obj) == dict:
        return {formatter(k): format_obj_keys(v, formatter) for k, v in obj.items()}
    else:
        return obj

