def get_product_version(path: typing.Union[str, Path]) -> VersionInfo:
    """Get version info from executable

    Args:
        path: path to the executable

    Returns: VersionInfo"""
    path = Path(path).absolute()
    pe_info = pefile.PE(str(path))
    try:
        for file_info in pe_info.FileInfo:
            if isinstance(file_info, list):
                result = _parse_file_info(file_info)
                if result:
                    return result
            else:
                result = _parse_file_info(pe_info.FileInfo)
                if result:
                    return result
        raise RuntimeError(f'unable to obtain version from {path}')
    except (KeyError, AttributeError) as exc:
        traceback.print_exc()
        raise RuntimeError(f'unable to obtain version from {path}') from exc

def patch(module, external=(), internal=()):
    """Temporarily monkey-patch dependencies which can be external to, or internal
    to the supplied module.

    :param module: Module object
    :param external: External dependencies to patch (full paths as strings)
    :param internal: Internal dependencies to patch (short names as strings)
    :return:"""
    external = tuple(external)
    internal = tuple(internal)
    def decorator(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            master_mock = mock.MagicMock()
            def get_mock(name):
                return getattr(master_mock, __patch_name(name))
            def patch_external(name):
                return mock.patch(name, get_mock(name))
            def patch_internal(name):
                return mock.patch(module.__name__ + '.' + name, get_mock(name))
            try:
                with __nested((patch_external(n) for n in external)):
                    if external:
                        reload_module(module)
                    with __nested((patch_internal(n) for n in internal)):
                        return fn(master_mock, *args, **kwargs)
            finally:
                if external:
                    reload_module(module)
        return wrapper
    return decorator

def open_filezip(file_path, find_str):
    """Open the wrapped file.
    Read directly from the zip without extracting its content."""
    if zipfile.is_zipfile(file_path):
        zipf = zipfile.ZipFile(file_path)
        interesting_files = [f for f in zipf.infolist() if find_str in f]
        for inside_file in interesting_files:
            yield zipf.open(inside_file)

