def _dfs_cycle_detect(graph, node, path, visited_nodes):
    """search graph for cycle using DFS continuing from node
    path contains the list of visited nodes currently on the stack
    visited_nodes is the set of already visited nodes
    :param graph:
    :param node:
    :param path:
    :param visited_nodes:
    :return:"""
    visited_nodes.add(node)
    for target in graph[node]:
        if target in path:
            return path + [target]
        else:
            return _dfs_cycle_detect(graph, target, path + [target], visited_nodes)
    return None

def detect_cycle(graph):
    """search the given directed graph for cycles

    returns None if the given graph is cycle free
    otherwise it returns a path through the graph that contains a cycle
    :param graph:
    :return:"""
    visited_nodes = set()
    for node in list(graph):
        if node not in visited_nodes:
            cycle = _dfs_cycle_detect(graph, node, [node], visited_nodes)
            if cycle:
                return cycle
    return None

def _before_flush_handler(session, _flush_context, _instances):
    """Update version ID for all dirty, modified rows"""
    dialect = get_dialect(session)
    for row in session.dirty:
        if isinstance(row, SavageModelMixin) and is_modified(row, dialect):
            row.update_version_id()

def _after_flush_handler(session, _flush_context):
    """Archive all new/updated/deleted data"""
    dialect = get_dialect(session)
    handlers = [(_versioned_delete, session.deleted), (_versioned_insert, session.new), (_versioned_update, session.dirty)]
    for handler, rows in handlers:
        for row in rows:
            if not isinstance(row, SavageModelMixin):
                continue
            if not hasattr(row, 'ArchiveTable'):
                raise LogTableCreationError('Need to register Savage tables!!')
            user_id = getattr(row, '_updated_by', None)
            handler(row, session, user_id, dialect)

def run_command(command):
    """Utility function for run command with subprocess. Return a tuple, with
    return code and if python >= 2.7 command's output or None if python <= 2.6"""
    try:
        check_ouput = getattr(subprocess, 'check_output', subprocess.check_call)
        result = check_ouput(command, stderr=subprocess.STDOUT, shell=True)
        if check_ouput.__name__ == 'check_output':
            return (0, result)
        else:
            return (result, None)
    except subprocess.CalledProcessError as e:
        return (e.returncode, getattr(e, 'output', None))

def parse_env(config_schema, env):
    """Parse the values from a given environment against a given config schema

    Args:
        config_schema: A dict which maps the variable name to a Schema object
            that describes the requested value.
        env: A dict which represents the value of each variable in the
            environment."""
    try:
        return {key: item_schema.parse(key, env.get(key)) for key, item_schema in config_schema.items()}
    except KeyError as error:
        raise MissingConfigError('Required config not set: {}'.format(error.args[0]))

