def check_args(func):
    """A decorator that performs type checking using type hints at runtime::
    @check_args
    def fun(a: int):
        print(f'fun is being called with parameter {a}')
    # this will raise a TypeError describing the issue without the function being called
    fun('not an int')"""
    @wraps(func)
    def check(*args, **kwargs):
        sig = inspect.signature(func)
        found_errors = []
        binding = None
        try:
            binding = sig.bind(*args, **kwargs)
        except TypeError as te:
            for name, metadata in sig.parameters.items():
                if metadata.default == inspect.Parameter.empty:
                    error_in_case = 'missing a required argument: {arg!r}'.format(arg=name)
                    if str(te) == error_in_case:
                        found_errors.append(IssueDescription(name, sig.parameters[name].annotation, None, True))
            if not found_errors:
                raise DetailedTypeError([IssueDescription(None, None, None, None, str(te))])
            raise DetailedTypeError(found_errors)
        for name, value in binding.arguments.items():
            if not check_type(value, sig.parameters[name].annotation):
                found_errors.append(IssueDescription(name, sig.parameters[name].annotation, value, False))
        if found_errors:
            raise DetailedTypeError(found_errors)
        return func(*args, **kwargs)
    return check

def t_IDENTIFIER(t):
    """[A-Z_a-z][0-9A-Z_a-z]*"""
    if t.value in keywords:
        t.type = t.value
    return t

def register_deregister(notifier, event_type, callback=None, args=None, kwargs=None, details_filter=None, weak=False):
    """Context manager that registers a callback, then deregisters on exit.

    NOTE(harlowja): if the callback is none, then this registers nothing, which
                    is different from the behavior of the ``register`` method
                    which will *not* accept none as it is not callable..."""
    if callback is None:
        yield
    else:
        notifier.register(event_type, callback, args=args, kwargs=kwargs, details_filter=details_filter, weak=weak)
        try:
            yield
        finally:
            notifier.deregister(event_type, callback, details_filter=details_filter)

def read_local_files(*file_paths: str) -> str:
    """Reads one or more text files and returns them joined together.
    A title is automatically created based on the file name.

    Args:
        *file_paths: list of files to aggregate

    Returns: content of files"""
    def _read_single_file(file_path):
        with open(file_path) as f:
            filename = os.path.splitext(file_path)[0]
            title = f"{filename}\n{'=' * len(filename)}"
            return '\n\n'.join((title, f.read()))
    return '\n' + '\n\n'.join(map(_read_single_file, file_paths))

def raise_from(exc, cause):
    """Does the same as ``raise LALALA from BLABLABLA`` does in Python 3.
    But works in Python 2 also!

    Please checkout README on https://github.com/9seconds/pep3134
    to get an idea about possible pitfals. But short story is: please
    be pretty carefull with tracebacks. If it is possible, use sys.exc_info
    instead. But in most cases it will work as you expect."""
    context_tb = sys.exc_info()[2]
    incorrect_cause = not (isinstance(cause, type) and issubclass(cause, Exception) or isinstance(cause, BaseException) or cause is None)
    if incorrect_cause:
        raise TypeError('exception causes must derive from BaseException')
    if cause is not None:
        if not getattr(cause, '__pep3134__', False):
            try:
                raise_(cause)
            except:
                cause = sys.exc_info()[1]
        cause.__fixed_traceback__ = context_tb
    try:
        raise_(exc)
    except:
        exc = sys.exc_info()[1]
    exc.__original_exception__.__suppress_context__ = True
    exc.__original_exception__.__cause__ = cause
    exc.__original_exception__.__context__ = None
    raise exc

