def decorator(func):
    """Makes the passed decorators to support optional args.
    """
    def wrapper(__decorated__=None, *Args, **KwArgs):
        if __decorated__ is None:
            return lambda _func: func(_func, *Args, **KwArgs)
        else:
            return func(__decorated__, *Args, **KwArgs)
    return wrap(wrapper, func)

def _arg(__decorated__, **Config):
    """The worker for the arg decorator.
    """
    if isinstance(__decorated__, tuple):
        __decorated__[1].insert(0, Config)
        return __decorated__
    else:
        return (__decorated__, [Config])

def naive(gold_schemes):
    """find naive baseline (most common scheme of a given length)?"""
    scheme_path = os.path.join(os.path.dirname(os.path.realpath(__file__)), 'data', 'schemes.json')
    with open(scheme_path, 'r') as f:
        dist = json.loads(f.read())
    best_schemes = {}
    for i in dist.keys():
        if not dist[i]:
            continue
        best_schemes[int(i)] = tuple((int(j) for j in max(dist[i], key=lambda x: x[1])[0].split()))
    naive_schemes = []
    for g in gold_schemes:
        naive_schemes.append(best_schemes[len(g)])
    return naive_schemes

def less_naive(gold_schemes):
    """find 'less naive' baseline (most common scheme of a given length in subcorpus)"""
    best_schemes = defaultdict(lambda: defaultdict(int))
    for g in gold_schemes:
        best_schemes[len(g)][tuple(g)] += 1
    for i in best_schemes:
        best_schemes[i] = tuple(max(best_schemes[i].items(), key=lambda x: x[1])[0])
    naive_schemes = []
    for g in gold_schemes:
        naive_schemes.append(best_schemes[len(g)])
    return naive_schemes

def requires_git(func: Callable) -> Callable:
    """Decorator to ensure `git` is accessible before calling a function.
    :param func: the function to wrap
    :return: the wrapped function"""
    def decorated(*args, **kwargs):
        try:
            run([GIT_COMMAND, '--version'])
        except RunException as e:
            raise RuntimeError('`git` does not appear to be working') from e
        return func(*args, **kwargs)
    return decorated

def get_git_root_directory(directory: str):
    """Gets the path of the git project root directory from the given directory.
    :param directory: the directory within a git repository
    :return: the root directory of the git repository
    :exception NotAGitRepositoryException: raised if the given directory is not within a git repository"""
    try:
        return run([GIT_COMMAND, 'rev-parse', '--show-toplevel'], directory)
    except RunException as e:
        if ' Not a git repository' in e.stderr:
            raise NotAGitRepositoryException(directory) from e

def get_directory_relative_to_git_root(directory: str):
    """Gets the path to the given directory relative to the git repository root in which it is a subdirectory.
    :param directory: the directory within a git repository
    :return: the path to the directory relative to the git repository root"""
    return os.path.relpath(os.path.realpath(directory), get_git_root_directory(directory))

def install_gem(gemname, version=None, conservative=True, ri=False, rdoc=False, development=False, format_executable=False, force=False, gem_source=None):
    """Install a ruby gem."""
    cmdline = ['gem', 'install']
    if conservative:
        cmdline.append('--conservative')
    if ri:
        cmdline.append('--ri')
    else:
        cmdline.append('--no-ri')
    if rdoc:
        cmdline.append('--rdoc')
    else:
        cmdline.append('--no-rdoc')
    if development:
        cmdline.append('--development')
    if format_executable:
        cmdline.append('--format-executable')
    if force:
        cmdline.append('--force')
    if version:
        cmdline.extend(['--version', version])
    cmdline.extend(['--clear-sources', '--source', gem_source or RubyGems().gem_source])
    cmdline.append(gemname)
    msg = 'Installing ruby gem: %s' % gemname
    if version:
        msg += ' Version requested: %s' % version
    log.debug(msg)
    try:
        subprocess.check_output(cmdline, shell=False)
    except (OSError, subprocess.CalledProcessError) as err:
        raise error.ButcherError('Gem install failed. Error was: %s. Output: %s' % (err, err.output))

def is_installed(gemname, version=None):
    """Check if a gem is installed."""
    cmdline = ['gem', 'list', '-i', gemname]
    if version:
        cmdline.extend(['-v', version])
    try:
        subprocess.check_output(cmdline, shell=False)
        return True
    except (OSError, subprocess.CalledProcessError) as err:
        if err.returncode == 1:
            return False
        else:
            raise error.ButcherError('Failure running gem. Error was: %s. Output: %s', err, err.output)

def check_arg_types(funcname, *args):
    """Raise TypeError if not all items of `args` are same string type."""
    hasstr = hasbytes = False
    for arg in args:
        if isinstance(arg, str):
            hasstr = True
        elif isinstance(arg, bytes):
            hasbytes = True
        else:
            raise TypeError('{0}() argument must be str or bytes, not {1}'.format(funcname, arg.__class__.__name__))
    if hasstr and hasbytes:
        raise TypeError("Can't mix strings and bytes in path components")

def posix_commonpath(paths):
    """Given a sequence of POSIX path names,
    return the longest common sub-path."""
    if not paths:
        raise ValueError('commonpath() arg is an empty sequence')
    check_arg_types('commonpath', *paths)
    if isinstance(paths[0], bytes):
        sep = b'/'
        curdir = b'.'
    else:
        sep = '/'
        curdir = '.'
    split_paths = [path.split(sep) for path in paths]
    try:
        isabs, = set((p[:1] == sep for p in paths))
    except ValueError:
        raise ValueError("Can't mix absolute and relative paths")
    split_paths = [[c for c in s if c and c != curdir] for s in split_paths]
    s_min = min(split_paths)
    s_max = max(split_paths)
    common = s_min
    for i, run_c in enumerate(s_min):
        if run_c != s_max[i]:
            common = s_min[:i]
            break
    prefix = sep if isabs else sep[:0]
    return prefix + sep.join(common)

def kompile(src, raw=False, filename='<compiler>', loader=None, **kwargs):
    """Creates a new class based on the supplied template, and returnsit.

    class Template(object):
        def __call__(self, context):
            return ''.join(self._iterator(context))

        def _iterator(self, context):
            return map(str, self._root(context)

        def _root(self, context):
            yield ''
            yield ...
            yield from self.head(context)

    Blocks create new methods, and add a 'yield from self.{block}(context)' to
    the current function"""
    parser = Parser(src, loader=loader)
    parser.load_library('knights.tags')
    parser.load_library('knights.helpers')
    parser.build_method('_root')
    if parser.parent:
        parser.methods = [method for method in parser.methods if method.name != '_root']
    klass = parser.build_class()
    inst = ast.Module(body=[klass])
    ast.fix_missing_locations(inst)
    if kwargs.get('astor', False):
        import astor
        print(astor.to_source(inst))
    code = compile(inst, filename=filename, mode='exec', optimize=2)
    g = {'_': Helpers(parser.helpers), 'parent': parser.parent, 'ContextScope': ContextScope}
    eval(code, g)
    klass = g['Template']
    if raw:
        return klass
    return klass()

def getDigestableArgs(Argv):
    """Splits the given Argv into *Args and **KwArgs.
    """
    first_kwarg_pos = 0
    for arg in Argv:
        if KWARG_VALIDATOR.search(arg):
            break
        else:
            first_kwarg_pos += 1
    for arg in Argv[first_kwarg_pos:]:
        if not KWARG_VALIDATOR.search(arg):
            raise HandledException('Could not parse the arg "%s".' % arg)
    return (Argv[:first_kwarg_pos], list2dict(Argv[first_kwarg_pos:]))

