def getPackages(plist):
    """Cleans up input from the command line tool and returns a list of package
    names"""
    nlist = plist.split('\n')
    pkgs = []
    for i in nlist:
        if i.find('===') > 0:
            continue
        pkg = i.split()[0]
        if pkg == 'Warning:':
            continue
        elif pkg == 'Could':
            continue
        elif pkg == 'Some':
            continue
        elif pkg == 'You':
            continue
        elif not pkg:
            continue
        pkgs.append(pkg)
    print('  >> Found', len(pkgs), 'packages')
    return pkgs

def pip(usr_pswd=None):
    """This updates one package at a time.

    Could do all at once:
            pip list --outdated | cut -d' ' -f1 | xargs pip install --upgrade"""
    try:
        cmd('which pip')
    except:
        return
    print('-[pip]----------')
    p = cmd('pip list --outdated')
    if not p:
        return
    pkgs = getPackages(p)
    for i, p in enumerate(pkgs):
        if p in ['pip', 'setuptools']:
            cmd('pip install -U ' + p, usr_pwd=usr_pswd, run=global_run)
            pkgs.pop(i)
    for p in pkgs:
        cmd('pip install -U ' + p, usr_pwd=usr_pswd, run=global_run)

def brew(clean=False):
    """Handle homebrew on macOS"""
    try:
        cmd('which brew')
    except:
        return
    print('-[brew]----------')
    cmd('brew update')
    p = cmd('brew outdated')
    if not p:
        return
    pkgs = getPackages(p)
    for p in pkgs:
        cmd('brew upgrade {}'.format(p), run=global_run)
    if clean:
        print(' > brew prune old sym links and cleanup')
        cmd('brew prune')
        cmd('brew cleanup')

def npm(usr_pwd=None, clean=False):
