def umap(path, name=None, include=None, namespace=None, priority=None):
    """Maps a given URL path, name and namespace to a view.
    Arguments:
        - path: the URL regex, e.g.: '^teste/(?P<pk>[0-9])/$'.

    Optional arguments:
        - name: the URL name, which Django uses to identify the URL;
        - include: A custom URL list, previously
                   set on the module's urls.py;
        - namespace: the URL's namespace;
        - priority: the URL's priority;"""
    def url_wrapper(view):
        module = _find_urls_module(view)
        fn = view.as_view() if hasattr(view, 'as_view') else view
        if namespace and include:
            raise TypeError("You can't use 'namespace' and 'include' at the same time!")
        if namespace:
            base = import_string('{}.urls.urlpatterns'.format(module))
            urlpatterns_list = [x for x in base if getattr(x, 'namespace', None) == namespace]
            if len(urlpatterns_list) != 1:
                raise ValueError("Namespace '{}' not in list.".format(namespace))
            urlpatterns = urlpatterns_list.pop(0).url_patterns
        else:
            urlpatterns = import_string('{}.urls.{}'.format(module, include or 'urlpatterns'))
        call = urlpatterns.append if priority is None else partial(urlpatterns.insert, priority)
        call(url(path, fn, name=name))
        return view
    return url_wrapper

def result_to_dict(raw_result):
    """Parse raw result from fetcher into readable dictionary

    Args:
        raw_result (dict) - raw data from `fetcher`

    Returns:
        dict - readable dictionary"""
    result = {}
    for channel_index, channel in enumerate(raw_result):
        channel_id, channel_name = (channel[0], channel[1])
        channel_result = {'id': channel_id, 'name': channel_name, 'movies': []}
        for movie in channel[2]:
            channel_result['movies'].append({'title': movie[1], 'start_time': datetime.fromtimestamp(movie[2]), 'end_time': datetime.fromtimestamp(movie[2] + movie[3]), 'inf': True if movie[3] else False})
        result[channel_id] = channel_result
    return result

def cd(doi):
    """cd to directory of interest(doi)

    a doi can be:

    herbert - the container named "herbert"
    sdox:dev - product "website" located in container "herbert"
    :param doi:
    :return:"""
    parts = doi.split(':')
    if len(parts) == 2:
        container_name, product_name = (parts[0], parts[1])
    elif len(parts) == 1 and os.environ.get('CONTAINER_NAME'):
        product_name = parts[0]
        container_name = os.environ.get('CONTAINER_NAME')
    else:
        print('unable to parse context - format: <container_name>:<product_name>')
        sys.exit(1)
    if container_name not in tasks.get_containers():
        print('No such container')
    elif product_name:
        if product_name not in tasks.get_products(container_name):
            print('No such product')
        else:
            print(tasks.conf.SOURCE_HEADER)
            print('cd ' + tasks.get_product_dir(container_name, product_name))
    else:
        print(tasks.conf.SOURCE_HEADER)
        print('cd ' + tasks.get_container_dir(container_name))

def install_container(container_name):
    """Installs the container specified by container_name
    :param container_name: string, name of the container"""
    container_dir = os.path.join(os.environ['APE_ROOT_DIR'], container_name)
    if os.path.exists(container_dir):
        os.environ['CONTAINER_DIR'] = container_dir
    else:
        raise ContainerNotFound('ERROR: container directory not found: %s' % container_dir)
    install_script = os.path.join(container_dir, 'install.py')
    if os.path.exists(install_script):
        print('... running install.py for %s' % container_name)
        subprocess.check_call(['python', install_script])
    else:
        raise ContainerError('ERROR: this container does not provide an install.py!')

def get_poi_tuple(poi=None):
    """Takes the poi or None and returns the container_dir and the product name either of the passed poi
    (<container_name>: <product_name>) or from os.environ-
    :param poi: optional; <container_name>: <product_name>
    :return: tuple of the container directory and the product name"""
    if poi:
        parts = poi.split(':')
        if len(parts) == 2:
            container_name, product_name = parts
            if container_name not in tasks.get_containers():
                print('No such container')
                sys.exit(1)
            elif product_name not in tasks.get_products(container_name):
                print('No such product')
                sys.exit(1)
            else:
                container_dir = tasks.get_container_dir(container_name)
        else:
            print('Please check your arguments: --poi <container>:<product>')
            sys.exit(1)
    else:
        container_dir = os.environ.get('CONTAINER_DIR')
        product_name = os.environ.get('PRODUCT_NAME')
    return (container_dir, product_name)

def _dump(db):
    """Dump :class:`mongomock.database.Database` to dict data."""
    db_data = {'name': db.name, '_collections': dict()}
    for col_name, collection in iteritems(db._collections):
        if col_name != 'system.indexes':
            col_data = {'_documents': collection._documents, '_uniques': collection._uniques}
