def dump_element(element):
    """Dumps the content of the given ElementBase object to a string

    :param element: An ElementBase object
    :return: A full description of its content
    :raise TypeError: Invalid object"""
    try:
        assert isinstance(element, sleekxmpp.ElementBase)
    except AssertionError:
        raise TypeError('Not an ElementBase: {0}'.format(type(element)))
    output = StringIO()
    output.write('ElementBase : {0}\n'.format(type(element)))
    output.write('- name......: {0}\n'.format(element.name))
    output.write('- namespace.: {0}\n'.format(element.namespace))
    output.write('- interfaces:\n')
    for itf in sorted(element.interfaces):
        output.write('\t- {0}: {1}\n'.format(itf, element[itf]))
    if element.sub_interfaces:
        output.write('- sub-interfaces:\n')
        for itf in sorted(element.sub_interfaces):
            output.write('\t- {0}: {1}\n'.format(itf, element[itf]))
    return output.getvalue()

def do_super(parser, token):
    """Access the parent templates block.

    {% super name %}"""
    name = token.strip()
    return ast.YieldFrom(value=_a.Call(_a.Attribute(_a.Call(_a.Name('super')), name), [_a.Name('context')]))

def _create_with_scope(body, kwargs):
    """Helper function to wrap a block in a scope stack:

    with ContextScope(context, **kwargs) as context:
        ... body ..."""
    return ast.With(items=[ast.withitem(context_expr=_a.Call(_a.Name('ContextScope'), [_a.Name('context')], keywords=kwargs), optional_vars=_a.Name('context', ctx=ast.Store()))], body=body)

def do_for(parser, token):
    """{% for a, b, c in iterable %}

    {% endfor %}

    We create the structure:

    with ContextWrapper(context) as context:
        for a, b, c in iterable:
            context.update(a=a, b=b, c=c)
            ...

    If there is a {% empty %} clause, we create:

    if iterable:
        { above code }
    else:
        { empty clause }"""
    code = ast.parse('for %s: pass' % token, mode='exec')
    loop = code.body[0]
    loop.iter = visitor.visit(loop.iter)
    body, end = parser.parse_nodes_until('endfor', 'empty')
    if isinstance(loop.target, ast.Tuple):
        targets = [elt.id for elt in loop.target.elts]
    else:
        targets = [loop.target.id]
    kwargs = [ast.keyword(arg=elt, value=_a.Name(elt)) for elt in targets]
    body.insert(0, ast.Expr(value=_a.Call(_a.Attribute(_a.Name('context'), 'update'), keywords=kwargs)))
    loop.body = body
    node = _create_with_scope([loop], [])
    if end == 'empty':
        empty, _ = parser.parse_nodes_until('endfor')
        node = ast.If(test=loop.iter, body=[node], orelse=empty)
    return node

def macro(parser, token):
    """Works just like block, but does not render."""
    name = token.strip()
    parser.build_method(name, endnodes=['endmacro'])
    return ast.Yield(value=ast.Str(s=''))

def use(parser, token):
    """Counterpart to `macro`, lets you render any block/macro in place."""
    args, kwargs = parser.parse_args(token)
    assert isinstance(args[0], ast.Str), 'First argument to "include" tag must be a string'
    name = args[0].s
    action = ast.YieldFrom(value=_a.Call(_a.Attribute(_a.Name('self'), name), [_a.Name('context')]))
    if kwargs:
        kwargs = _wrap_kwargs(kwargs)
        return _create_with_scope([ast.Expr(value=action)], kwargs)
    return action

def resolve_composed_functions(data, recursive=True):
    """Calls `ComposedFunction`s and returns its return value. By default, this
    function will recursively iterate dicts, lists, tuples, and sets and
    replace all `ComposedFunction`s with their return value."""
    if isinstance(data, ComposedFunction):
        data = data()
    if recursive:
        if isinstance(data, dict):
            for key, value in data.items():
                data[key] = resolve_composed_functions(value, recursive=recursive)
        elif isinstance(data, (list, tuple, set)):
            for index, value in enumerate(data):
                data[index] = resolve_composed_functions(value, recursive=recursive)
    return data

