def acceptable(value, capitalize=False):
    """Convert a string into something that can be used as a valid python variable name"""
    name = regexes['punctuation'].sub('', regexes['joins'].sub('_', value))
    name = regexes['repeated_underscore'].sub('_', name.strip('_'))
    if capitalize:
        name_parts = []
        for word in name.split('_'):
            name_parts.append(word[0].upper())
            if len(word) > 1:
                name_parts.append(word[1:])
        name = ''.join(name_parts)
    return name

def get_context_hints_per_source(context_renderers):
    """Given a list of context renderers, return a dictionary of context hints per source."""
    context_hints_per_source = defaultdict(lambda: defaultdict(lambda: {'app_name': None, 'model_name': None, 'select_related': set(), 'prefetch_related': set()}))
    for cr in context_renderers:
        for key, hints in cr.context_hints.items() if cr.context_hints else []:
            for source in cr.get_sources():
                context_hints_per_source[source][key]['app_name'] = hints['app_name']
                context_hints_per_source[source][key]['model_name'] = hints['model_name']
                context_hints_per_source[source][key]['select_related'].update(hints.get('select_related', []))
                context_hints_per_source[source][key]['prefetch_related'].update(hints.get('prefetch_related', []))
    return context_hints_per_source

def get_querysets_for_context_hints(context_hints_per_source):
    """Given a list of context hint dictionaries, return a dictionary
    of querysets for efficient context loading. The return value
    is structured as follows:

    {
        model: queryset,
        ...
    }"""
    model_select_relateds = defaultdict(set)
    model_prefetch_relateds = defaultdict(set)
    model_querysets = {}
    for context_hints in context_hints_per_source.values():
        for hints in context_hints.values():
            model = get_model(hints['app_name'], hints['model_name'])
            model_querysets[model] = model.objects
            model_select_relateds[model].update(hints.get('select_related', []))
            model_prefetch_relateds[model].update(hints.get('prefetch_related', []))
    for model, queryset in model_querysets.items():
        if model_select_relateds[model]:
            queryset = queryset.select_related(*model_select_relateds[model])
        if model_prefetch_relateds[model]:
            queryset = queryset.prefetch_related(*model_prefetch_relateds[model])
        model_querysets[model] = queryset
    return model_querysets

def dict_find(d, which_key):
    """Finds key values in a nested dictionary. Returns a tuple of the dictionary in which
    the key was found along with the value"""
    if isinstance(d, (list, tuple)):
        for i in d:
            for result in dict_find(i, which_key):
                yield result
    elif isinstance(d, dict):
        for k, v in d.items():
            if k == which_key:
                yield (d, v)
            for result in dict_find(v, which_key):
                yield result

def get_model_ids_to_fetch(events, context_hints_per_source):
    """Obtains the ids of all models that need to be fetched. Returns a dictionary of models that
    point to sets of ids that need to be fetched. Return output is as follows:

    {
        model: [id1, id2, ...],
        ...
    }"""
    number_types = (complex, float) + six.integer_types
    model_ids_to_fetch = defaultdict(set)
    for event in events:
        context_hints = context_hints_per_source.get(event.source, {})
        for context_key, hints in context_hints.items():
            for d, value in dict_find(event.context, context_key):
                values = value if isinstance(value, list) else [value]
                model_ids_to_fetch[get_model(hints['app_name'], hints['model_name'])].update((v for v in values if isinstance(v, number_types)))
    return model_ids_to_fetch

def fetch_model_data(model_querysets, model_ids_to_fetch):
    """Given a dictionary of models to querysets and model IDs to models, fetch the IDs
    for every model and return the objects in the following structure.

    {
        model: {
            id: obj,
            ...
        },
        ...
    }"""
    return {model: id_dict(model_querysets[model].filter(id__in=ids_to_fetch)) for model, ids_to_fetch in model_ids_to_fetch.items()}

def load_fetched_objects_into_contexts(events, model_data, context_hints_per_source):
    """Given the fetched model data and the context hints for each source, go through each
    event and populate the contexts with the loaded information."""
    for event in events:
        context_hints = context_hints_per_source.get(event.source, {})
        for context_key, hints in context_hints.items():
            model = get_model(hints['app_name'], hints['model_name'])
            for d, value in dict_find(event.context, context_key):
                if isinstance(value, list):
                    for i, model_id in enumerate(d[context_key]):
                        d[context_key][i] = model_data[model].get(model_id)
                else:
                    d[context_key] = model_data[model].get(value)

def load_renderers_into_events(events, mediums, context_renderers, default_rendering_style):
    """Given the events and the context renderers, load the renderers into the event objects
    so that they may be able to call the 'render' method later on."""
    source_group_style_to_renderer = {(cr.source_group_id, cr.rendering_style_id): cr for cr in context_renderers if cr.source_group_id}
    source_style_to_renderer = {(cr.source_id, cr.rendering_style_id): cr for cr in context_renderers if cr.source_id}
    for e in events:
        for m in mediums:
            cr = source_group_style_to_renderer.get((e.source.group_id, m.rendering_style_id))
            if not cr:
                cr = source_style_to_renderer.get((e.source_id, m.rendering_style_id))
            if not cr and default_rendering_style:
                cr = source_group_style_to_renderer.get((e.source.group_id, default_rendering_style.id))
            if not cr and default_rendering_style:
                cr = source_style_to_renderer.get((e.source_id, default_rendering_style.id))
            if cr:
                e._context_renderers[m] = cr

def _in_qtconsole() -> bool:
    """A small utility function which determines if we're running in QTConsole's context."""
    try:
        from IPython import get_ipython
        try:
            from ipykernel.zmqshell import ZMQInteractiveShell
            shell_object = ZMQInteractiveShell
        except ImportError:
            from IPython.kernel.zmq import zmqshell
            shell_object = zmqshell.ZMQInteractiveShell
        return isinstance(get_ipython(), shell_object)
    except Exception:
        return False

def execute_by_options(args):
    """execute by argument dictionary

    Args:
        args (dict): command line argument dictionary"""
    if args['subcommand'] == 'sphinx':
        s = Sphinx(proj_info)
        if args['quickstart']:
            s.quickstart()
        elif args['gen_code_api']:
            s.gen_code_api()
        elif args['rst2html']:
            s.rst2html()
        pass
    elif args['subcommand'] == 'offline_dist':
        pod = PyOfflineDist()
        if args['freeze_deps']:
            pod.freeze_deps()
        elif args['download_deps']:
            pod.download_deps()
        elif args['install_deps']:
            pod.install_deps()
        elif args['clean_deps']:
            pod.clean_deps()
        elif args['mkbinary']:
            pod.pyinstaller_mkbinary(args['mkbinary'])
        elif args['clean_binary']:
            pod.clean_binary()
    pass

def assign_operation_ids(spec, operids):
    """used to assign caller provided operationId values into a spec"""
    empty_dict = {}
    for path_name, path_data in six.iteritems(spec['paths']):
        for method, method_data in six.iteritems(path_data):
            oper_id = operids.get(path_name, empty_dict).get(method)
            if oper_id:
                method_data['operationId'] = oper_id

def extract_options_dict(template, options):
    """Extract options from a dictionary against the template"""
    for option, val in template.items():
        if options and option in options:
            yield (option, options[option])
        else:
            yield (option, Default(template[option]['default'](os.environ)))

def is_module_function(obj, prop):
    """Checking and setting type to MODULE_FUNCTION
    Args:
        obj: ModuleType
        prop: FunctionType
    Return:
        Boolean
    Raise:
        prop_type_error: When the type of prop is not valid
        prop_in_obj_error: When prop is not in the obj(module/class)
        prop_is_func_error: When prop is not a callable stuff"""
    python_version = sys.version_info[0]
    if python_version == 3:
        unicode = str
    if prop and (isinstance(prop, str) or isinstance(prop, unicode)):
        if prop in dir(obj):
            if isinstance(getattr(obj, prop), FunctionType) or isinstance(getattr(obj, prop), BuiltinFunctionType) or inspect.ismethod(getattr(obj, prop)):
                return True
            else:
                ErrorHandler.prop_is_func_error(obj, prop)
        else:
            ErrorHandler.prop_in_obj_error(obj, prop)
    elif prop:
        ErrorHandler.prop_type_error(prop)
    return False

def from_env():
    """Get host/port settings from the environment."""
    if 'MICROMONGO_URI' in os.environ:
        return (os.environ['MICROMONGO_URI'],)
    host = os.environ.get('MICROMONGO_HOST', 'localhost')
    port = int(os.environ.get('MICROMONGO_PORT', 27017))
    return (host, port)

def _strip_dollars_fast(text):
    """Replace `$$`\xa0with `$`. raise immediately
    if `$` starting an interpolated expression is found.
    @param text: the source text
    @return: the text with dollars replaced, or raise
        HasExprException if there are interpolated expressions"""
    def _sub(m):
        if m.group(0) == '$$':
            return '$'
        raise HasExprException()
    return _dollar_strip_re.sub(_sub, text)

def adjust_locations(ast_node, first_lineno, first_offset):
    """Adjust the locations of the ast nodes, offsetting them
    to the new lineno and column offset"""
    line_delta = first_lineno - 1
    def _fix(node):
        if 'lineno' in node._attributes:
            lineno = node.lineno
            col = node.col_offset
            if lineno == 1:
                col += first_offset
            lineno += line_delta
            node.lineno = lineno
            node.col_offset = col
        for child in iter_child_nodes(node):
            _fix(child)
    _fix(ast_node)

def remove_locations(node):
    """Removes locations from the given AST tree completely"""
    def fix(node):
        if 'lineno' in node._attributes and hasattr(node, 'lineno'):
            del node.lineno
        if 'col_offset' in node._attributes and hasattr(node, 'col_offset'):
            del node.col_offset
        for child in iter_child_nodes(node):
            fix(child)
    fix(node)

def bind(context, block=False):
    """Given the context, returns a decorator wrapper;
    the binder replaces the wrapped func with the
    value from the context OR puts this function in
    the context with the name."""
    if block:
        def decorate(func):
            name = func.__name__.replace('__TK__block__', '')
            if name not in context:
                context[name] = func
            return context[name]
        return decorate
    def decorate(func):
        name = func.__name__
        if name not in context:
            context[name] = func
        return context[name]
    return decorate

def fullsplit(path, result=None, base_path=None):
    """Split a pathname into components (the opposite of os.path.join) in a
    platform-neutral way."""
    if base_path:
        path = path.replace(base_path, '')
    if result is None:
        result = []
    head, tail = os.path.split(path)
    if head == '':
        return [tail] + result
    if head == path:
        return result
    return fullsplit(head, [tail] + result)

def _flatten(l):
    """helper to flatten a list of lists
    """
    res = []
    for sublist in l:
        if isinstance(sublist, whaaaaat.Separator):
            res.append(sublist)
        else:
            for item in sublist:
                res.append(item)
    return res

def insert_load_command(target_path, library_install_name):
    """Inserts a new LC_LOAD_DYLIB load command into the target Mach-O header.

    Note: the target file will be overwritten. Consider backing it up first before calling this function.
    Returns True if everything is OK. Otherwise rises an exception."""
    def patchHeader(t):
        load_command = generate_dylib_load_command(t, library_install_name)
        return insert_load_command_into_header(t, load_command)
    return modify_macho_file_headers(target_path, patchHeader)

def getPathOfExecutable(executable):
    """Returns the full path of the executable, or None if the executable
    can not be found."""
    exe_paths = os.environ['PATH'].split(':')
    for exe_path in exe_paths:
        exe_file = os.path.join(exe_path, executable)
        if os.path.isfile(exe_file) and os.access(exe_file, os.X_OK):
            return exe_file
    return None

def requireExecutables(executables):
    """Check that all of the given executables are on the path.
    If at least one of them is not, exit the script and inform
    the user of the missing requirement(s)."""
    missingExecutables = []
    for executable in executables:
        if getPathOfExecutable(executable) is None:
            missingExecutables.append(executable)
    if len(missingExecutables) > 0:
        log('In order to run this script, the following executables need to be on the path:')
        for missingExecutable in missingExecutables:
            log(missingExecutable)
        exit(1)

def runCommandReturnOutput(cmd):
    """Runs a shell command and return the stdout and stderr"""
    splits = shlex.split(cmd)
    proc = subprocess.Popen(splits, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    stdout, stderr = proc.communicate()
    if proc.returncode != 0:
        raise subprocess.CalledProcessError(stdout, stderr)
    return (stdout, stderr)

def zipLists(*lists):
    """Checks to see if all of the lists are the same length, and throws
    an AssertionError otherwise.  Returns the zipped lists."""
    length = len(lists[0])
    for i, list_ in enumerate(lists[1:]):
        if len(list_) != length:
            msg = 'List at index {} has length {} != {}'.format(i + 1, len(list_), length)
            raise AssertionError(msg)
    return zip(*lists)

def getFilePathsWithExtensionsInDirectory(dirTree, patterns, sort=True):
    """Returns all file paths that match any one of patterns in a
    file tree with its root at dirTree.  Sorts the paths by default."""
    filePaths = []
    for root, dirs, files in os.walk(dirTree):
        for filePath in files:
            for pattern in patterns:
                if fnmatch.fnmatch(filePath, pattern):
                    fullPath = os.path.join(root, filePath)
                    filePaths.append(fullPath)
                    break
    if sort:
        filePaths.sort()
    return filePaths

def cell_strings(term):
    """Return the strings that represent each possible living cell state.

    Return the most colorful ones the terminal supports."""
    num_colors = term.number_of_colors
    if num_colors >= 16:
        funcs = (term.on_bright_red, term.on_bright_green, term.on_bright_cyan)
    elif num_colors >= 8:
        funcs = (term.on_red, term.on_green, term.on_blue)
    else:
        return (term.reverse(' '), term.smacs + term.reverse('a') + term.rmacs, term.smacs + 'a' + term.rmacs)
    return [f(' ') for f in funcs]

def random_board(max_x, max_y, load_factor):
    """Return a random board with given max x and y coords."""
    return dict((((randint(0, max_x), randint(0, max_y)), 0) for _ in xrange(int(max_x * max_y / load_factor))))

def next_board(board, wrap):
    """Given a board, return the board one interation later.

    Adapted from Jack Diedrich's implementation from his 2012 PyCon talk "Stop
    Writing Classes"

    :arg wrap: A callable which takes a point and transforms it, for example
        to wrap to the other edge of the screen. Return None to remove a point."""
    new_board = {}
    points_to_recalc = set(board.iterkeys()) | set(chain(*map(neighbors, board)))
    for point in points_to_recalc:
        count = sum((neigh in board for neigh in (wrap(n) for n in neighbors(point) if n)))
        if count == 3:
            state = 0 if point in board else 1
        elif count == 2 and point in board:
            state = 2
        else:
            state = None
        if state is not None:
            wrapped = wrap(point)
            if wrapped:
                new_board[wrapped] = state
    return new_board

def get_social_share_link(context, share_link, object_url, object_title):
    """Construct the social share link for the request object."""
    request = context['request']
    url = unicode(object_url)
    if 'http' not in object_url.lower():
        full_path = ''.join(('http', ('', 's')[request.is_secure()], '://', request.META['HTTP_HOST'], url))
    else:
        full_path = url
    return share_link.get_share_url(full_path, object_title)

def literals(choices, prefix='', suffix=''):
    """Create a regex from a space-separated list of literal `choices`.

    If provided, `prefix` and `suffix` will be attached to each choice
    individually."""
    return '|'.join((prefix + re.escape(c) + suffix for c in choices.split()))

def normalize_dictionary(data_dict):
    """Converts all the keys in "data_dict" to strings. The keys must be
    convertible using str()."""
    for key, value in data_dict.items():
        if not isinstance(key, str):
            del data_dict[key]
            data_dict[str(key)] = value
    return data_dict

def get_sort_field(attr, model):
    """Get's the field to sort on for the given
    attr.

    Currently returns attr if it is a field on
    the given model.

    If the models has an attribute matching that name
    and that value has an attribute 'sort_field' than
    that value is used.

    TODO: Provide a way to sort based on a non field
    attribute."""
    try:
        if model._meta.get_field(attr):
            return attr
    except FieldDoesNotExist:
        if isinstance(attr, basestring):
            val = getattr(model, attr, None)
            if val and hasattr(val, 'sort_field'):
                return getattr(model, attr).sort_field
        return None

