def resource_of_node(resources, node):
    """Returns resource of node.
    """
    for resource in resources:
        model = getattr(resource, 'model', None)
        if type(node) == model:
            return resource
    return BasePageResource

def resources_of_config(config):
    """Returns all resources and models from config.
    """
    return set(sum([list(value) if hasattr(value, '__iter__') else [value] for value in config.values()], []))

def models_of_config(config):
    """Return list of models from all resources in config.
    """
    resources = resources_of_config(config)
    models = []
    for resource in resources:
        if not hasattr(resource, '__table__') and hasattr(resource, 'model'):
            models.append(resource.model)
        else:
            models.append(resource)
    return models

def dict_partial_cmp(target_dict, dict_list, ducktype):
    """Whether partial dict are in dict_list or not"""
    for called_dict in dict_list:
        if len(target_dict) > len(called_dict):
            continue
        intersection = {}
        for item in target_dict:
            dtype = ducktype(target_dict[item])
            if hasattr(dtype, 'mtest'):
                if item in called_dict and dtype.mtest(called_dict[item]):
                    intersection[item] = target_dict[item]
            elif item in called_dict and dtype == called_dict[item]:
                intersection[item] = target_dict[item]
        if intersection == target_dict:
            return True
    return False

def dict_partial_cmp_always(target_dict, dict_list, ducktype):
    """Whether partial dict are always in dict_list or not"""
    res = []
    for called_dict in dict_list:
        if len(target_dict) > len(called_dict):
            continue
        intersection = {}
        for item in target_dict:
            dtype = ducktype(target_dict[item])
            if hasattr(dtype, 'mtest'):
                if item in called_dict and dtype.mtest(called_dict[item]):
                    intersection[item] = target_dict[item]
            elif item in called_dict and dtype == called_dict[item]:
                intersection[item] = target_dict[item]
        ret = True if intersection == target_dict else False
        res.append(ret)
    return True if res and False not in res else False

def tuple_partial_cmp(target_tuple, tuple_list, ducktype):
    """Whether partial target_tuple are in tuple_list or not"""
    for called_tuple in tuple_list:
        if len(target_tuple) > len(called_tuple):
            continue
        dst = len(target_tuple)
        for idx, part_target_tuple in enumerate(target_tuple):
            dtype = ducktype(part_target_tuple)
            if hasattr(dtype, 'mtest'):
                if dtype.mtest(called_tuple[idx]):
                    dst = dst - 1
            elif dtype == called_tuple[idx]:
                dst = dst - 1
        if not dst:
            return True
    return False

def tuple_partial_cmp_always(target_tuple, tuple_list, ducktype):
    """Whether partial target_tuple are always in tuple_list or not"""
    res = []
    for called_tuple in tuple_list:
        if len(target_tuple) > len(called_tuple):
            continue
        dst = len(target_tuple)
        for idx, part_target_tuple in enumerate(target_tuple):
            dtype = ducktype(part_target_tuple)
            if hasattr(dtype, 'mtest'):
                if dtype.mtest(called_tuple[idx]):
                    dst = dst - 1
            elif dtype == called_tuple[idx]:
                dst = dst - 1
        ret = True if not dst else False
        res.append(ret)
    return True if res and False not in res else False

def deactivate():
    """Deactivate a state in this thread."""
    if hasattr(_mode, 'current_state'):
        del _mode.current_state
    if hasattr(_mode, 'schema'):
        del _mode.schema
    for k in connections:
        con = connections[k]
        if hasattr(con, 'reset_schema'):
            con.reset_schema()

def search_form(*fields, **kwargs):
    """Construct a search form filter form using the fields
    provided as arguments to this function.

    By default a field will be created for each field passed
    and hidden field will be created for search. If you pass
    the key work argument `search_only` then only a visible
    search field will be created on the form.

    Passing `status_filter` will include a version status filter
    on this form."""
    fdict = {'search_fields': set(fields)}
    if kwargs.get('search_only'):
        fdict['search'] = forms.CharField(max_length=255, required=False)
    else:
        fdict['search'] = forms.CharField(max_length=255, required=False, widget=forms.HiddenInput)
        for f in fields:
            fdict[f] = forms.CharField(max_length=255, required=False)
    if kwargs.get('status_filter', False):
        return type('filterform', (VersionFilterForm,), fdict)
    else:
        return type('filterform', (BaseFilterForm,), fdict)

def switch_state(request):
    """Switch the default version state in
    the session."""
    if request.session.get(SESSION_KEY):
        request.session[SESSION_KEY] = False
    else:
        request.session[SESSION_KEY] = True
    url = request.GET.get('redirect_to', '/')
    if url.startswith('http'):
        url = '/'
    return redirect(url)

def cibaseglob(pat, base):
    """Case insensitive baseglob.  Note that it's not *actually* case
    insensitive, since glob is insensitive or not based on local semantics.
    Instead, it tries the original version, an upper() version, a lower()
    version, and a swapcase() version of the glob."""
    results = []
    for func in (str, str.upper, str.lower, str.swapcase):
        results += baseglob(func(pat), base)
    return list(sorted(set(results)))

def dircolorize(path, name_only=True):
    """Use user dircolors settings to colorize a string which is a path.
    If name_only is True, it does this by the name rules (*.x) only; it
    will not check the filesystem to colorize things like pipes, block devs,
    doors, etc."""
    if not name_only:
        raise NotImplemented('Filesystem checking not implemented.')
    for k, regex in colorremap.iteritems():
        if regex.match(path):
            return '\x1b[%(color)sm%(path)s\x1b[00m' % {'color': k, 'path': path}
    return path

def build_dot_value(key, value):
    """Build new dictionaries based off of the dot notation key.

    For example, if a key were 'x.y.z' and the value was 'foo',
    we would expect a return value of: ('x', {'y': {'z': 'foo'}})

    Args:
        key (str): The key to build a dictionary off of.
        value: The value associated with the dot notation key.

    Returns:
        tuple: A 2-tuple where the first element is the key of
            the outermost scope (e.g. left-most in the dot
            notation key) and the value is the constructed value
            for that key (e.g. a dictionary)"""
    if key.count('.') == 0:
        return (key, value)
    final_value = value
    reverse_split = key.split('.')[::-1]
    end = len(reverse_split) - 1
    for idx, k in enumerate(reverse_split):
        if idx == end:
            return (k, final_value)
        final_value = {k: final_value}

def _merge(d, u):
    """Merge two dictionaries (or DotDicts) together.

    Args:
          d: The dictionary/DotDict to merge into.
          u: The source of the data to merge."""
    for k, v in u.items():
        if isinstance(v, collections.Mapping):
            d[k] = _merge(d.get(k, {}), v)
        elif isinstance(d, collections.MutableMapping):
            d[k] = v
        else:
            d = {k: v}
    return d

def make_extractor(non_default):
    """Return us a function to extract options
    Anything not in non_default is wrapped in a "Default" object"""
    def extract_options(template, options):
        for option, val in normalise_options(template):
            name = option.replace('-', '_')
            value = getattr(options, name)
            if option not in non_default:
                value = Default(value)
            yield (name, value)
    return extract_options

def translate_exception(exc_info, initial_skip=0):
    """If passed an exc_info it will automatically rewrite the exceptions
    all the way down to the correct line numbers and frames."""
    tb = exc_info[2]
    frames = []
    for x in range(initial_skip):
        if tb is not None:
            tb = tb.tb_next
    initial_tb = tb
    while tb is not None:
        if tb.tb_frame.f_code in internal_code:
            tb = tb.tb_next
            continue
        next = tb.tb_next
        template = tb.tb_frame.f_globals.get('__TK_template_info__')
        if template is not None:
            lineno = template.get_corresponding_lineno(tb.tb_lineno)
            tb = fake_exc_info(exc_info[:2] + (tb,), template.filename, lineno)[2]
        frames.append(make_frame_proxy(tb))
        tb = next
    if not frames:
        reraise(exc_info[0], exc_info[1], exc_info[2])
    return ProcessedTraceback(exc_info[0], exc_info[1], frames)

def create_store_prompt(name):
    """Create a prompt which implements the `store` feature.

    :param name: name of the generator
    :return: prompt"""
    def _prompt(questions, answers=None, **kwargs):
        stored_answers = _read_stored_answers(name)
        to_store = []
        for q in questions:
            if 'store' in q:
                if q.pop('store'):
                    to_store.append(q['name'])
                    if q['name'] in stored_answers:
                        q['default'] = stored_answers[q['name']]
        answers = prompt(questions, answers, **kwargs)
        if to_store:
            for s in to_store:
                if s in answers:
                    stored_answers[s] = answers[s]
            _store_answers(name, stored_answers)
        return answers
    return _prompt

def memoize(function):
    """Memoizing function.  Potentially not thread-safe, since it will return
    resuts across threads.  Make sure this is okay with callers."""
    _cache = {}
    @wraps(function)
    def wrapper(*args, **kwargs):
        key = str(args) + str(kwargs)
        if key not in _cache:
            _cache[key] = function(*args, **kwargs)
        return _cache[key]
    return wrapper

def _get_query_sets_for_object(o):
    """Determines the correct query set based on the object.

    If the object is a literal, it will return a query set over LiteralStatements.
    If the object is a URIRef or BNode, it will return a query set over Statements.
    If the object is unknown, it will return both the LiteralStatement and Statement query sets.

    This method always returns a list of size at least one."""
    if o:
        if isinstance(o, Literal):
            query_sets = [models.LiteralStatement.objects]
        else:
            query_sets = [models.URIStatement.objects]
    else:
        query_sets = [models.URIStatement.objects, models.LiteralStatement.objects]
    return query_sets

