def pygmentify(value, **kwargs):
    """Return a highlighted code block with Pygments."""
    soup = BeautifulSoup(value, 'html.parser')
    for pre in soup.find_all('pre'):
        code = ''.join([to_string(item) for item in pre.contents])
        code = code.replace('&lt;', '<')
        code = code.replace('&gt;', '>')
        code = code.replace('&#39;', "'")
        code = code.replace('&quot;', '"')
        code = code.replace('&amp;', '&')
        class_list = pre.get('class', [])
        lexers = []
        options = {'stripall': True}
        for c in class_list:
            try:
                lexers.append(get_lexer_by_name(c, **options))
            except ClassNotFound:
                pass
        try:
            lexer = lexers[0]
        except IndexError:
            lexer = None
        if lexer is None:
            try:
                lexer = guess_lexer(pre.text, **options)
                class_list += [alias for alias in lexer.aliases]
            except ClassNotFound:
                pass
        if lexer is not None:
            formatter = HtmlFormatter(**kwargs)
            highlighted = highlight(code, lexer, formatter)
            class_string = ' '.join([c for c in class_list])
            highlighted = highlighted.replace('<div class="%s"><pre>' % kwargs['cssclass'], '<div class="%s"><pre class="%s">' % (kwargs['cssclass'], class_string))
            pre.replace_with(highlighted)
    return soup.decode(formatter=None).strip()

def get_analyzer_for(language_code, default='snowball'):
    """Get the available language analyzer for the given language code or else the default.
    :param language_code: Django language code
    :param default: The analyzer to return if no language analyzer has been found.
                    Defaults to 'snowball'.
    :return: The Haystack language name. E.g. 'german' or the default analyzer"""
    languages = {'ar': 'arabic', 'eu': 'basque', 'pt-br': 'brazilian', 'bg': 'bulgarian', 'ca': 'catalan', 'zh-hans': 'chinese', 'zh-hant': 'chinese', 'cs': 'czech', 'da': 'danish', 'nl': 'dutch', 'en': 'english', 'fi': 'finnish', 'fr': 'french', 'gl': 'galician', 'de': 'german', 'el': 'greek', 'hi': 'hindi', 'hu': 'hungarian', 'id': 'indonesian', 'ga': 'irish', 'it': 'italian', 'lv': 'latvian', 'no': 'norwegian', 'fa': 'persian', 'pt': 'portuguese', 'ro': 'romanian', 'ru': 'russian', 'es': 'spanish', 'sv': 'swedish', 'tr': 'turkish', 'th': 'thai'}
