    if 'bdist_wheel' not in sys.argv:
        if sys.version_info[0] == 2:
            install_requires.append('bzr >= 2.6.0')
        if sys.version_info[2:] == (2, 6):
            install_requires.append('mercurial >= 2.9, < 4.3')
