def quote(text, ws=plain):
    """Quote special characters in shell command arguments.

    E.g ``--foo bar>=10.1`` becomes "--foo bar\\>\\=10\\.1``."""
    return ''.join((chr in ws and chr or '\\' + chr for chr in text))

def unpack(rv):
    """Unpack the response from a view.

    :param rv: the view response
    :type rv: either a :class:`werkzeug.wrappers.Response` or a
        tuple of (data, status_code, headers)"""
    if isinstance(rv, ResponseBase):
        return rv
    status = headers = None
    if isinstance(rv, tuple):
        rv, status, headers = rv + (None,) * (3 - len(rv))
    if rv is None:
        raise ValueError('View function did not return a response')
    if status is None:
        status = 200
    return (rv, status, headers or {})

def save_positions(post_data, queryset=None):
    """Function to update a queryset of position objects with a post data dict.

    :post_data: Typical post data dictionary like ``request.POST``, which
      contains the keys of the position inputs.
    :queryset: Queryset of the model ``ObjectPosition``."""
    if not queryset:
        queryset = ObjectPosition.objects.all()
    for key in post_data:
        if key.startswith('position-'):
            try:
                obj_id = int(key.replace('position-', ''))
            except ValueError:
                continue
            queryset.filter(pk=obj_id).update(position=post_data[key])

