def sam_readline(sock, partial=None):
    """read a line from a sam control socket"""
    response = b''
    exception = None
    while True:
        try:
            c = sock.recv(1)
            if not c:
                raise EOFError('SAM connection died. Partial response %r %r' % (partial, response))
            elif c == b'\n':
                break
            else:
                response += c
        except (BlockingIOError, pysocket.timeout) as e:
            if partial is None:
                raise e
            else:
                exception = e
                break
    if partial is None:
        return response.decode('ascii')
    else:
        return (partial + response.decode('ascii'), exception)

def sam_parse_reply(line):
    """parse a reply line into a dict"""
    parts = line.split(' ')
    opts = {k: v for k, v in split_kv(parts[2:])}
    return SAMReply(parts[0], opts)

def sam_send(sock, line_and_data):
    """Send a line to the SAM controller, but don't read it"""
    if isinstance(line_and_data, tuple):
        line, data = line_and_data
    else:
        line, data = (line_and_data, b'')
    line = bytes(line, encoding='ascii') + b' \n'
    sock.sendall(line + data)

def sam_cmd(sock, line, parse=True):
    """Send a line to the SAM controller, returning the parsed response"""
    sam_send(sock, line)
    reply_line = sam_readline(sock)
    if parse:
        return sam_parse_reply(reply_line)
    else:
        return reply_line

def handshake(timeout, sam_api, max_version):
    """handshake with sam via a socket.socket instance"""
    sock = controller_connect(sam_api, timeout=timeout)
    response = sam_cmd(sock, greet(max_version))
    if response.ok:
        return sock
    else:
        raise HandshakeError('Failed to handshake with SAM: %s' % repr(response))

def lookup(sock, domain, cache=None):
    """lookup an I2P domain name, returning a Destination instance"""
    domain = normalize_domain(domain)
    reply = sam_cmd(sock, 'NAMING LOOKUP NAME=%s' % domain)
    b64_dest = reply.get('VALUE')
    if b64_dest:
        dest = Dest(b64_dest, encoding='base64')
        if cache:
            cache[dest.base32 + '.b32.i2p'] = dest
        return dest
    else:
        raise NSError('Domain name %r not resolved because %r' % (domain, reply))

def read_file(filename):
    """Read a file into a string"""
    p = path.abspath(path.dirname(__file__))
    filepath = path.join(p, filename)
    try:
        return open(filepath).read()
    except IOError:
        return ''

def _format_as_url(path):
    """Make sure ``path`` takes the form of ``/some/url/``."""
    path = sub('\\.html$', '', path)
    if not path.startswith('/'):
        path = '/{0}'.format(path)
    if not path.endswith('/'):
        path = '{0}/'.format(path)
    return path

def urls_from_file_tree(template_dir):
    """Generates a list of URL strings that would match each staticflatpage."""
    urls = []
    root_dir = join(template_dir, 'staticflatpages')
    for root, dirs, files in walk(template_dir):
        if 'staticflatpages' in root:
            root = root.replace(root_dir, '')
            for f in files:
                path = join(root, f)
                path = _format_as_url(path)
                urls.append(path)
    return urls

def get_terminal_size(defaultw=80):
    """Checks various methods to determine the terminal size


    Methods:
    - shutil.get_terminal_size (only Python3)
    - fcntl.ioctl
    - subprocess.check_output
    - os.environ

    Parameters
    ----------
    defaultw : int
        Default width of terminal.


    Returns
    -------
    width, height : int
        Width and height of the terminal. If one of them could not be
        found, None is return in its place."""
    if hasattr(shutil_get_terminal_size, '__call__'):
        return shutil_get_terminal_size()
    else:
        try:
            import fcntl, termios, struct
            fd = 0
            hw = struct.unpack('hh', fcntl.ioctl(fd, termios.TIOCGWINSZ, '1234'))
            return (hw[1], hw[0])
        except:
            try:
                out = sp.check_output(['tput', 'cols'])
                width = int(out.decode('utf-8').strip())
                return (width, None)
            except:
                try:
                    hw = (os.environ['LINES'], os.environ['COLUMNS'])
                    return (hw[1], hw[0])
                except:
                    return (defaultw, None)

def terminal_unreserve(progress_obj, terminal_obj=None, verbose=0, identifier=None):
    """Unregisters the terminal (stdout) for printing.

    an instance (progress_obj) can only unreserve the tty (terminal_obj) when it also reserved it

    see terminal_reserved for more information

    Returns
    -------
    None"""
    if terminal_obj is None:
        terminal_obj = sys.stdout
    if identifier is None:
        identifier = ''
    else:
        identifier = identifier + ': '
    po = TERMINAL_RESERVATION.get(terminal_obj)
    if po is None:
        log.debug('terminal %s was not reserved, nothing happens', terminal_obj)
    elif po is progress_obj:
        log.debug('terminal %s now unreserned', terminal_obj)
        del TERMINAL_RESERVATION[terminal_obj]
    else:
        log.debug('you %s can NOT unreserve terminal %s be cause it was reserved by %s', progress_obj, terminal_obj, po)

def include(context, bundle_name, version):
    """Include a bundle of files into the internal space.

    Use bundle name if you simply want to inlcude the latest version."""
    store = Store(context.obj['database'], context.obj['root'])
    if version:
        version_obj = store.Version.get(version)
        if version_obj is None:
            click.echo(click.style('version not found', fg='red'))
    else:
        bundle_obj = store.bundle(bundle_name)
        if bundle_obj is None:
            click.echo(click.style('bundle not found', fg='red'))
        version_obj = bundle_obj.versions[0]
    try:
        include_version(context.obj['root'], version_obj)
    except VersionIncludedError as error:
        click.echo(click.style(error.message, fg='red'))
        context.abort()
    version_obj.included_at = dt.datetime.now()
    store.commit()
    click.echo(click.style('included all files!', fg='green'))

