def get_lines_from_file(filename, lineno, context_lines, loader=None, module_name=None):
    """Returns context_lines before and after lineno from file.
    Returns (pre_context_lineno, pre_context, context_line, post_context)."""
    source = None
    if loader is not None and hasattr(loader, 'get_source'):
        try:
            source = loader.get_source(module_name)
        except ImportError:
            source = None
        if source is not None:
            source = source.splitlines()
    if source is None:
        try:
            f = open(filename)
            try:
                source = f.readlines()
            finally:
                f.close()
        except (OSError, IOError):
            pass
    if source is None:
        return []
    encoding = 'ascii'
    for line in source[:2]:
        match = _coding_re.search(line)
        if match:
            encoding = match.group(1)
            break
    source = [unicode(sline, encoding, 'replace') for sline in source]
    lower_bound = max(0, lineno - context_lines)
    upper_bound = min(lineno + context_lines + 1, len(source))
    try:
        return [(lineno + 1, source[lineno].strip('\n')) for lineno in xrange(lower_bound, upper_bound)]
    except IndexError:
        return []

def crossplat_loop_run(coro) -> Any:
    """Cross-platform method for running a subprocess-spawning coroutine."""
    if sys.platform == 'win32':
        signal.signal(signal.SIGINT, signal.SIG_DFL)
        loop = asyncio.ProactorEventLoop()
    else:
        loop = asyncio.new_event_loop()
    asyncio.set_event_loop(loop)
    with contextlib.closing(loop):
        return loop.run_until_complete(coro)

def json_numpy_obj_hook(dct):
    """Decodes a previously encoded numpy ndarray with proper shape and dtype.
    And decompresses the data with blosc

    :param dct: (dict) json encoded ndarray
    :return: (ndarray) if input was an encoded ndarray"""
    if isinstance(dct, dict) and '__ndarray__' in dct:
        array = dct['__ndarray__']
        if sys.version_info >= (3, 0):
            array = array.encode('utf-8')
        data = base64.b64decode(array)
        if has_blosc:
            data = blosc.decompress(data)
        try:
            dtype = np.dtype(ast.literal_eval(dct['dtype']))
        except ValueError:
            dtype = dct['dtype']
        return np.frombuffer(data, dtype).reshape(dct['shape'])
    return dct

def extract(query_dict, prefix=''):
    """Extract the *order_by*, *per_page*, and *page* parameters from
    `query_dict` (a Django QueryDict), and return a dict suitable for
    instantiating a preconfigured Table object."""
    strs = ['order_by']
    ints = ['per_page', 'page']
    extracted = {}
    for key in strs + ints:
        if prefix + key in query_dict:
            val = query_dict.get(prefix + key)
            extracted[key] = val if not key in ints else int(val)
    return extracted

def _copy(query_dict):
    """Return a mutable copy of `query_dict`. This is a workaround to
    Django bug #13572, which prevents QueryDict.copy from working."""
    memo = {}
    result = query_dict.__class__('', encoding=query_dict.encoding, mutable=True)
    memo[id(query_dict)] = result
    for key, value in dict.items(query_dict):
        dict.__setitem__(result, copy.deepcopy(key, memo), copy.deepcopy(value, memo))
    return result

