        - decoded string as type str for python2 and type byte for python3."""
    if isinstance(byte_str, str) and (not PYTHON2):
        byte_str = bytes(byte_str, 'utf-8')
    return base64.b64decode(byte_str)

def recursive_iterator(func):
    """Decorates a function by optimizing it for iterator recursion.
    Requires function arguments to be pickleable."""
    tee_store = {}
    @_coconut.functools.wraps(func)
    def recursive_iterator_func(*args, **kwargs):
        hashable_args_kwargs = _coconut.pickle.dumps((args, kwargs), _coconut.pickle.HIGHEST_PROTOCOL)
        try:
            to_tee = tee_store[hashable_args_kwargs]
        except _coconut.KeyError:
            to_tee = func(*args, **kwargs)
        tee_store[hashable_args_kwargs], to_return = _coconut_tee(to_tee)
        return to_return
    return recursive_iterator_func

def addpattern(base_func):
    """Decorator to add a new case to a pattern-matching function, where the new case is checked last."""
    def pattern_adder(func):
        @_coconut.functools.wraps(func)
        @_coconut_tco
        def add_pattern_func(*args, **kwargs):
            try:
                return base_func(*args, **kwargs)
            except _coconut_MatchError:
                raise _coconut_tail_call(func, *args, **kwargs)
        return add_pattern_func
    return pattern_adder

def fmap(func, obj):
    """Creates a copy of obj with func applied to its contents."""
    if _coconut.hasattr(obj, '__fmap__'):
        return obj.__fmap__(func)
    args = _coconut_map(func, obj)
    if _coconut.isinstance(obj, _coconut.dict):
        args = _coconut_zip(args, obj.values())
    if _coconut.isinstance(obj, _coconut.tuple) and _coconut.hasattr(obj, '_make'):
        return obj._make(args)
    if _coconut.isinstance(obj, (_coconut.map, _coconut.range)):
        return args
    if _coconut.isinstance(obj, _coconut.str):
        return ''.join(args)
    return obj.__class__(args)

def get_canonical_uri_path(uri_path):
    """get_canonical_uri_path(uri_path) -> str

    Normalizes the specified URI path component, removing redundant slashes
    and relative path components.

    A ValueError exception is raised if:
    * The URI path is not empty and not absolute (does not start with '/').
    * A parent relative path element ('..') attempts to go beyond the top.
    * An invalid percent-encoding is encountered."""
    if uri_path == '' or uri_path == '/':
        return '/'
    if not uri_path.startswith('/'):
        raise ValueError('URI path is not absolute.')
    uri_path = _multislash.sub('/', uri_path)
    components = uri_path.split('/')[1:]
    i = 0
    while i < len(components):
        component = normalize_uri_path_component(components[i])
        components[i] = component
        if components[i] == '.':
            del components[i]
        elif components[i] == '..':
            if i == 0:
                raise ValueError('URI path attempts to go beyond root')
            del components[i - 1:i + 1]
            i -= 1
        else:
            i += 1
    return '/' + '/'.join(components)

def normalize_query_parameters(query_string):
    """normalize_query_parameters(query_string) -> dict

    Converts a query string into a dictionary mapping parameter names to a
    list of the sorted values.  This ensurses that the query string follows
    % encoding rules according to RFC 3986 and checks for duplicate keys.

    A ValueError exception is raised if a percent encoding is invalid."""
    if query_string == '':
        return {}
    components = query_string.split('&')
    result = {}
    for component in components:
        try:
            key, value = component.split('=', 1)
        except ValueError:
            key = component
            value = ''
        if component == '':
            continue
        key = normalize_uri_path_component(key)
        value = normalize_uri_path_component(value)
        if key in result:
            result[key].append(value)
        else:
            result[key] = [value]
    return dict([(key, sorted(values)) for key, values in iteritems(result)])

