def getCountKwargs(func):
    """Returns a list ["count kwarg", "count_max kwarg"] for a
    given function. Valid combinations are defined in
    `progress.validCountKwargs`.

    Returns None if no keyword arguments are found."""
    if hasattr(func, '__code__'):
        func_args = func.__code__.co_varnames[:func.__code__.co_argcount]
        for pair in validCountKwargs:
            if pair[0] in func_args and pair[1] in func_args:
                return pair
    return None

def humanize_speed(c_per_sec):
    """convert a speed in counts per second to counts per [s, min, h, d], choosing the smallest value greater zero.
    """
    scales = [60, 60, 24]
    units = ['c/s', 'c/min', 'c/h', 'c/d']
    speed = c_per_sec
    i = 0
    if speed > 0:
        while speed < 1 and i < len(scales):
            speed *= scales[i]
            i += 1
    return '{:.1f}{}'.format(speed, units[i])

def humanize_time(secs):
    """convert second in to hh:mm:ss format
    """
    if secs is None:
        return '--'
    if secs < 1:
        return '{:.2f}ms'.format(secs * 1000)
    elif secs < 10:
        return '{:.2f}s'.format(secs)
    else:
        mins, secs = divmod(secs, 60)
        hours, mins = divmod(mins, 60)
        return '{:02d}:{:02d}:{:02d}'.format(int(hours), int(mins), int(secs))

def get_vcf_header(source):
    """Get the header lines of a vcf file

    Args:
        source(iterable): A vcf file

    Returns:
        head (HeaderParser): A headerparser object"""
    head = HeaderParser()
    for line in source:
        line = line.rstrip()
        if line.startswith('#'):
            if line.startswith('##'):
                logger.debug('Found metadata line {0}'.format(line))
                head.parse_meta_data(line)
            else:
                logger.debug('Found header line {0}'.format(line))
                head.parse_header_line(line)
        else:
            break
    return head

def _create():
    """Globally called function for creating the isotope/element API."""
    def creator(group):
        """Helper function applied to each symbol group of the raw isotope table."""
        symbol = group['symbol'].values[0]
        try:
            mass = (group['mass'] * group['af']).sum()
            afm = group['af'].sum()
            if afm > 0.0:
                mass /= afm
        except ZeroDivisionError:
            mass = group['mass'].mean()
        znum = group['Z'].max()
        cov_radius = group['cov_radius'].mean()
        van_radius = group['van_radius'].mean()
        try:
            color = group.loc[group['af'].idxmax(), 'color']
        except TypeError:
            color = group['color'].values[0]
        name = group['name'].values[0]
        ele = Element(symbol, name, mass, znum, cov_radius, van_radius, color)
        for tope in group.apply(lambda s: Isotope(*s.tolist()), axis=1):
            setattr(ele, '_' + str(tope.A), tope)
        return ele
    iso = _rj(_E(_path).to_stream())
    iso.columns = _columns
    setattr(_this, 'iso', iso)
    for element in iso.groupby('symbol').apply(creator):
        setattr(_this, element.symbol, element)

def as_df():
    """Return a dataframe of isotopes."""
    records = []
    for sym, ele in vars(_this).items():
        if sym not in ['Element', 'Isotope'] and (not sym.startswith('_')):
            for k, v in vars(ele).items():
                if k.startswith('_') and k[1].isdigit():
                    records.append({kk: vv for kk, vv in vars(v).items() if not kk.startswith('_')})
    return _DF.from_records(records)

