def exception_to_warning(description, category, always_raise=False):
    """Catches any exceptions that happen in the corresponding with block
    and instead emits a warning of the given category,
    unless always_raise is True or the environment variable
    OUTDATED_RAISE_EXCEPTION is set to 1, in which caise the exception
    will not be caught."""
    try:
        yield
    except Exception:
        if always_raise or (os and os.environ and (os.environ.get('OUTDATED_RAISE_EXCEPTION') == '1')):
            raise
        if warn_with_ignore:
            warn_with_ignore('Failed to %s.\nSet the environment variable OUTDATED_RAISE_EXCEPTION=1 for a full traceback.' % description, category)

def read_tarball(path, shortkey=False, classes=Editor):
    """Read a (possibly compressed) tarball archive and return a dictionary of
    editors.

    .. code-block:: python

        eds = read_tarball(path, classes=MyEditor)    # All files read as type MyEditor
        # Only read the special file as type MyEditor (default to Editor)
        eds = read_tarball(path.bz2, classes={'specialfile': MyEditor})
        eds = read_tarball(path, classes=myfunc)      # Complex function that returns classes

    Args:
        path (str): Path to tarball archive
        keypath (bool): Full member path as key (true, default); file name as key (false)
        classes: Class, dictionary of classes, or callable to return class"""
    editors = {}
    with tarfile.open(path) as tar:
        for member in tar.getmembers():
            f = tar.extractfile(member)
            if f is None:
                continue
            if shortkey:
                name = os.path.basename(member.name)
            else:
                name = member.name
            if isinstance(classes, type):
                cls = classes
            elif isinstance(classes, dict):
                cls = classes.get(name, Editor)
            elif callable(classes):
                cls = classes(name)
            else:
                raise TypeError('Wrong type for classes argument (with type {})'.format(type(classes)))
            editors[name] = cls(f, name=name)
    return editors

def parsemsg(s):
    """Breaks a message from an IRC server into its prefix, command, and arguments.
    """
    prefix = ''
    trailing = []
    if not s:
        raise Exception('Empty line.')
    if s[0] == ':':
        prefix, s = s[1:].split(' ', 1)
    if s.find(' :') != -1:
        s, trailing = s.split(' :', 1)
        args = s.split()
        args.append(trailing)
    else:
        args = s.split()
    command = args.pop(0)
    return (prefix, command, args)

def calendar(format, *args, **kwargs):
    """Creates a formatted ``HTMLCalendar``.
    Argument ``format`` can be one of ``month``, ``year``, or ``yearpage``
    Keyword arguments are collected and passed into ``HTMLCalendar.formatmonth``,
    ``HTMLCalendar.formatyear``, and ``HTMLCalendar.formatyearpage``

        Syntax::

            {% calendar month [year] [month] %}
            {% calendar year [year] %}
            {% calendar yearpage [year] %}

        Example::

            {% calendr month 2009 10 %}"""
    cal = HTMLCalendar(kwargs.pop('firstweekday', 0))
    return getattr(cal, 'format%s' % format)(*args, **kwargs)

