def profile(name='stats', _stats=stats):
    """Calculates a duration (wall clock time, not the CPU time) and a memory size."""
    def _profile(function):
        def __profile(*args, **kw):
            start_time = timer()
            start_memory = _get_memory_usage()
            try:
                return function(*args, **kw)
            finally:
                total = timer() - start_time
                kstones = _seconds_to_kpystones(total)
                memory = _get_memory_usage() - start_memory
                _stats[name] = {'time': total, 'kstones': kstones, 'memory': memory}
        return __profile
    return _profile

def retrieve_object(model, *args, **kwargs):
    """Retrieves a specific object from a given model by primary-key
    lookup, and stores it in a context variable.

    Syntax::

        {% retrieve_object [app_name].[model_name] [lookup kwargs] as [varname] %}

    Example::

        {% retrieve_object flatpages.flatpage pk=12 as my_flat_page %}"""
    if len(args) == 1:
        kwargs.update({'pk': args[0]})
    _model = _get_model(model)
    try:
        return _model._default_manager.get(**kwargs)
    except _model.DoesNotExist:
        return ''

