def tvdb_search_series(token, series=None, id_imdb=None, id_zap2it=None, lang='en', cache=True):
    """Allows the user to search for a series based on the following parameters

    Online docs: https://api.thetvdb.com/swagger#!/Search/get_search_series
    Note: results a maximum of 100 entries per page, no option for pagination="""
    if lang not in TVDB_LANGUAGE_CODES:
        raise MapiProviderException("'lang' must be one of %s" % ','.join(TVDB_LANGUAGE_CODES))
    url = 'https://api.thetvdb.com/search/series'
    parameters = {'name': series, 'imdbId': id_imdb, 'zap2itId': id_zap2it}
    headers = {'Accept-Language': lang, 'Authorization': 'Bearer %s' % token}
    status, content = _request_json(url, parameters, headers=headers, cache=cache)
    if status == 401:
        raise MapiProviderException('invalid token')
    elif status == 405:
        raise MapiProviderException('series, id_imdb, id_zap2it parameters are mutually exclusive')
    elif status == 404:
        raise MapiNotFoundException
    elif status != 200 or not content.get('data'):
        raise MapiNetworkException('TVDb down or unavailable?')
    return content

def get_vcf_handle(fsock=None, infile=None):
    """Open the vcf file and return a handle"""
    vcf = None
    if fsock or infile:
        if fsock:
            logger.info('Reading vcf form stdin')
            if sys.version_info < (3, 0):
                logger.info('Using codecs to read stdin')
                sys.stdin = getreader('utf-8')(fsock)
            vcf = sys.stdin
        else:
            logger.info('Reading vcf from file {0}'.format(infile))
            file_name, file_extension = os.path.splitext(infile)
            if file_extension == '.gz':
                logger.debug('Vcf is zipped')
                vcf = getreader('utf-8')(gzip.open(infile), errors='replace')
            elif file_extension == '.vcf':
                vcf = open(infile, mode='r', encoding='utf-8', errors='replace')
            else:
                raise IOError('File is not in a supported format!\n Or use correct ending(.vcf or .vcf.gz)')
    else:
        raise IOError('Please provide a fsock or infile')
    return vcf

def filter_none(list_of_points):
    """:param list_of_points:
    :return: list_of_points with None's removed"""
    remove_elementnone = filter(lambda p: p is not None, list_of_points)
    remove_sublistnone = filter(lambda p: not contains_none(p), remove_elementnone)
    return list(remove_sublistnone)

def routing(routes, request):
    """Definition for route matching : helper"""
    path = request.path.strip('/')
    args = {}
    for name, route in routes.items():
        if route['path'] == '^':
            if path == '':
                match = [True]
            else:
                match = []
        else:
            match = re.findall(route['path'], path)
        if match:
            if not request.method in route['method']:
                raise TornMethodNotAllowed
            values = match[0]
            if type(values) != bool:
                for i in range(len(route['variables'])):
                    if type(values) == str:
                        args[route['variables'][i]] = values
                    else:
                        if not values[i] and route['variables'][i] in route['defaults']:
                            values[i] = route['defaults'][route['variables'][i]]
                        args[route['variables'][i]] = values[i]
            return {'kwargs': args, 'controller': route['controller']}
    raise TornNotFoundError

def get_entries(path):
    """Return sorted lists of directories and files in the given path."""
    dirs, files = ([], [])
    for entry in os.listdir(path):
        if os.path.isdir(os.path.join(path, entry)):
            dirs.append(entry)
        else:
            files.append(entry)
    dirs.sort()
    files.sort()
    return (dirs, files)

def _typed_from_items(items):
    """Construct strongly typed attributes (properties) from a dictionary of
    name and :class:`~exa.typed.Typed` object pairs.

    See Also:
        :func:`~exa.typed.typed`"""
    dct = {}
    for name, attr in items:
        if isinstance(attr, Typed):
            dct[name] = attr(name)
    return dct

def reconcile(constraint):
    """Returns an assignment of type variable names to
    types that makes this constraint satisfiable, or a Refutation"""
    if isinstance(constraint.subtype, NamedType):
        if isinstance(constraint.supertype, NamedType):
            if constraint.subtype.name == constraint.supertype.name:
                return {}
            else:
                return Refutation('Cannot reconcile different atomic types: %s' % constraint)
        elif isinstance(constraint.supertype, Variable):
            return {constraint.supertype.name: constraint.subtype}
        else:
            return Refutation('Cannot reconcile atomic type with non-atomic type: %s' % constraint)
    elif isinstance(constraint.supertype, NamedType):
        if isinstance(constraint.subtype, NamedType):
            if constraint.subtype.name == constraint.supertype.name:
                return {}
            else:
                return Refutation('Cannot reconcile different atomic types: %s' % constraint)
        elif isinstance(constraint.subtype, Variable):
            return {constraint.subtype.name: constraint.supertype}
        else:
            return Refutation('Cannot reconcile non-atomic type with atomic type: %s' % constraint)
    elif isinstance(constraint.supertype, Union):
        if constraint.subtype in constraint.supertype.types:
            return {}
    return Stumper(constraint)

def cli(ctx, vcf, verbose, outfile, silent):
    """Simple vcf operations"""
    loglevel = LEVELS.get(min(verbose, 3))
    configure_stream(level=loglevel)
    if vcf == '-':
        handle = get_vcf_handle(fsock=sys.stdin)
    else:
        handle = get_vcf_handle(infile=vcf)
    head = HeaderParser()
    for line in handle:
        line = line.rstrip()
        if line.startswith('#'):
            if line.startswith('##'):
                head.parse_meta_data(line)
            else:
                head.parse_header_line(line)
        else:
            break
    ctx.head = head
    ctx.handle = itertools.chain([line], handle)
    ctx.outfile = outfile
    ctx.silent = silent

def do_map(func_name, *sequence):
    """Return a list of the results of applying the function to the items of
    the argument sequence(s).

    Functions may be registered with ``native_tags``
    or can be ``builtins`` or from the ``operator`` module

    If more than one sequence is given, the
    function is called with an argument list consisting of the corresponding
    item of each sequence, substituting None for missing values when not all
    sequences have the same length.  If the function is None, return a list of
    the items of the sequence (or a list of tuples if more than one sequence).

    Syntax::

        {% map [function] [sequence] %}
        {% map [function] [item1 item2 ...] %}

    For example::

        {% map sha1 hello world %}

    calculates::

        [sha1(hello), sha1(world)]"""
    if len(sequence) == 1:
        sequence = sequence[0]
    return map(get_func(func_name, False), sequence)

def do_reduce(func_name, *sequence):
    """Apply a function of two arguments cumulatively to the items of a sequence,
    from left to right, so as to reduce the sequence to a single value.

    Functions may be registered with ``native_tags``
    or can be ``builtins`` or from the ``operator`` module

    Syntax::

        {% reduce [function] [sequence] %}
        {% reduce [function] [item1 item2 ...] %}

    For example::

        {% reduce add 1 2 3 4 5 %}

    calculates::

        ((((1+2)+3)+4)+5) = 15"""
    if len(sequence) == 1:
        sequence = sequence[0]
    return reduce(get_func(func_name), sequence)

def authenticated(function):
    """Re-authenticate if session expired."""
    def wrapped(*args):
        """Wrap function."""
        try:
            return function(*args)
        except MoparError:
            _LOGGER.info('attempted to access page before login')
            _login(args[0])
            return function(*args)
    return wrapped

def token(function):
    """Attach a CSRF token for POST requests."""
    def wrapped(session, *args):
        """Wrap function."""
        resp = session.get(TOKEN_URL).json()
        session.headers.update({'mopar-csrf-salt': resp['token']})
        return function(session, *args)
    return wrapped

def get_profile(session):
    """Get complete profile."""
    try:
        profile = session.get(PROFILE_URL).json()
        if 'errorCode' in profile and profile['errorCode'] == '403':
            raise MoparError('not logged in')
        return profile
    except JSONDecodeError:
        raise MoparError('not logged in')

def get_report(session, vehicle_index):
    """Get vehicle health report summary."""
    vhr = get_vehicle_health_report(session, vehicle_index)
    if 'reportCard' not in vhr:
        raise MoparError('no vhr found')
    return _traverse_report(vhr['reportCard'])

def _traverse_report(data):
    """Recursively traverse vehicle health report."""
    if 'items' not in data:
        return {}
    out = {}
    for item in data['items']:
        skip = item['severity'] == 'NonDisplay' or item['itemKey'] == 'categoryDesc' or item['value'] in [None, 'Null', 'N/A', 'NULL']
        if skip:
            continue
        value = 'Ok' if item['value'] == '0.0' else item['value']
        out[item['itemKey']] = value
        out.update(_traverse_report(item))
    return out

