def _remote_status(session, service_id, uuid, url, interval=3):
    """Poll for remote command status."""
    _LOGGER.info('polling for status')
    resp = session.get(url, params={'remoteServiceRequestID': service_id, 'uuid': uuid}).json()
    if resp['status'] == 'SUCCESS':
        return 'completed'
    time.sleep(interval)
    return _remote_status(session, service_id, uuid, url)

def remote_command(session, command, vehicle_index, poll=True):
    """Send a remote command."""
    if command not in SUPPORTED_COMMANDS:
        raise MoparError('unsupported command: ' + command)
    profile = get_profile(session)
    _validate_vehicle(vehicle_index, profile)
    if command in [COMMAND_LOCK, COMMAND_UNLOCK]:
        url = REMOTE_LOCK_COMMAND_URL
    elif command in [COMMAND_ENGINE_ON, COMMAND_ENGINE_OFF]:
        url = REMOTE_ENGINE_COMMAND_URL
    elif command == COMMAND_HORN:
        url = REMOTE_ALARM_COMMAND_URL
    resp = session.post(url, {'pin': session.auth.pin, 'uuid': profile['vehicles'][vehicle_index]['uuid'], 'action': command}).json()
    if poll:
        uuid = profile['vehicles'][vehicle_index]['uuid']
        service_id = resp['serviceRequestId']
        return _remote_status(session, service_id, uuid, url)
    return 'submitted'

def django_admin(request):
    """Adds additional information to the context:

    ``django_admin`` - boolean variable indicating whether the current
    page is part of the django admin or not.
    ``ADMIN_URL`` - normalized version of settings.ADMIN_URL; starts with a slash, ends without a slash

    NOTE: do not set ADMIN_URL='/' in case your application provides functionality
    outside of django admin as all incoming urls are interpreted as admin urls."""
    if settings.ADMIN_URL.endswith('/'):
        admin_url = settings.ADMIN_URL[:-1]
    if not settings.ADMIN_URL.startswith('/'):
        admin_url = '/' + settings.ADMIN_URL
    if request.META['PATH_INFO'].startswith(admin_url):
        return {'ADMIN_URL': admin_url, 'django_admin': True}
    else:
        return {'django_admin': False}

