def _convert_timedelta_to_seconds(timedelta):
    """Returns the total seconds calculated from the supplied timedelta.

    (Function provided to enable running on Python 2.6 which lacks timedelta.total_seconds())."""
    days_in_seconds = timedelta.days * 24 * 3600
    return int((timedelta.microseconds + (timedelta.seconds + days_in_seconds) * 10 ** 6) / 10 ** 6)

def get_cache_key(bucket, name, args, kwargs):
    """Gets a unique SHA1 cache key for any call to a native tag.
    Use args and kwargs in hash so that the same arguments use the same key"""
    u = ''.join(map(str, (bucket, name, args, kwargs)))
    return 'native_tags.%s' % sha_constructor(u).hexdigest()

def get_signature(token, contextable=False, comparison=False):
    """Gets the signature tuple for any native tag
    contextable searchs for ``as`` variable to update context
    comparison if true uses ``negate`` (p) to ``not`` the result (~p)
    returns (``tag_name``, ``args``, ``kwargs``)"""
    bits = split(token.contents)
    args, kwargs = ((), {})
    if comparison and bits[-1] == 'negate':
        kwargs['negate'] = True
        bits = bits[:-1]
    if contextable and len(bits) > 2 and (bits[-2] == 'as'):
        kwargs['varname'] = bits[-1]
        bits = bits[:-2]
    kwarg_re = re.compile('^([-\\w]+)\\=(.*)$')
    for bit in bits[1:]:
        match = kwarg_re.match(bit)
        if match:
            kwargs[str(match.group(1))] = force_unicode(match.group(2))
        else:
            args += (bit,)
    return (bits[0], args, kwargs)

def do_function(parser, token):
    """Performs a defined function on the passed arguments.
    Normally this returns the output of the function into the template.
    If the second to last argument is ``as``, the result of the function is stored in the context and is named whatever the last argument is.

    Syntax::

        {% [function] [var args...] [name=value kwargs...] [as varname] %}

    Examples::

        {% search '^(\\d{3})$' 800 as match %}

        {% map sha1 hello world %}"""
    name, args, kwargs = get_signature(token, True, True)
    return FunctionNode(parser, name, *args, **kwargs)

def do_block(parser, token):
    """Process several nodes inside a single block
    Block functions take ``context``, ``nodelist`` as first arguments
    If the second to last argument is ``as``, the rendered result is stored in the context and is named whatever the last argument is.

    Syntax::

        {% [block] [var args...] [name=value kwargs...] [as varname] %}
            ... nodelist ...
        {% end[block] %}

    Examples::

        {% render_block as rendered_output %}
            {{ request.path }}/blog/{{ blog.slug }}
        {% endrender_block %}

        {% highlight_block python %}
            import this
        {% endhighlight_block %}"""
    name, args, kwargs = get_signature(token, contextable=True)
    kwargs['nodelist'] = parser.parse(('end%s' % name,))
    parser.delete_first_token()
    return BlockNode(parser, name, *args, **kwargs)

def wrapped_sendfile(act, offset, length):
    """Calls the sendfile system call or simulate with file read and socket send if
    unavailable."""
    if sendfile:
        offset, sent = sendfile.sendfile(act.sock.fileno(), act.file_handle.fileno(), offset, length)
    else:
        act.file_handle.seek(offset)
        sent = act.sock._fd.send(act.file_handle.read(length))
    return sent

def add_to_dumper(dumper: Type, classes: List[Type]) -> None:
    """Register user-defined classes with the Dumper.

    This enables the Dumper to write objects of your classes to a     YAML file. Note that all the arguments are types, not instances!

    Args:
        dumper: Your dumper class(!), derived from yatiml.Dumper
        classes: One or more classes to add."""
    if not isinstance(classes, list):
        classes = [classes]
    for class_ in classes:
        if issubclass(class_, enum.Enum):
            dumper.add_representer(class_, EnumRepresenter(class_))
        elif issubclass(class_, str) or issubclass(class_, UserString):
            dumper.add_representer(class_, UserStringRepresenter(class_))
        else:
            dumper.add_representer(class_, Representer(class_))

def highlight(code, lexer, **kwargs):
    """Returns highlighted code ``div`` tag from ``HtmlFormatter``
    Lexer is guessed by ``lexer`` name
    arguments are passed into the formatter

        Syntax::

            {% highlight [source code] [lexer name] [formatter options] %}

        Example::

            {% highlight 'print "Hello World"' python linenos=true %}"""
    if highlighter is None:
        return '<pre>%s</pre>' % code
    return highlighter(code or '', get_lexer_by_name(lexer), HtmlFormatter(**kwargs))

def highlight_block(context, nodelist, lexer, **kwargs):
    """Code is nodelist ``rendered`` in ``context``
    Returns highlighted code ``div`` tag from ``HtmlFormatter``
    Lexer is guessed by ``lexer`` name
    arguments are passed into the formatter

        Syntax::

            {% highlight_block [lexer name] [formatter options] %}
                ... source code ..
            {% endhighlight_block %}

        Example::

            {% highlight_block python linenos=true %}
                print '{{ request.path }}'
            {% endhighlight_block %}"""
    if highlighter is None:
        return '<pre>%s</pre>' % str(nodelist.render(context) or '')
    return highlighter(nodelist.render(context) or '', get_lexer_by_name(lexer), HtmlFormatter(**kwargs))

def wait_until(time_label):
    """Calculates the number of seconds that the process needs to sleep"""
    if time_label == 'next_minute':
        gevent.sleep(60 - int(time.time()) % 60)
    elif time_label == 'next_hour':
        gevent.sleep(3600 - int(time.time()) % 3600)
    elif time_label == 'tomorrow':
        gevent.sleep(86400 - int(time.time()) % 86400)

def create_or_append_to_zip(file_handle, zip_path, arc_name=None):
    """Append file_handle to given zip_path with name arc_name if given, else file_handle. zip_path will be created.
    :param file_handle: path to file or file-like object
    :param zip_path: path to zip archive
    :param arc_name: optional filename in archive"""
    with zipfile.ZipFile(zip_path, 'a') as my_zip:
        if arc_name:
            my_zip.write(file_handle, arc_name)
        else:
            my_zip.write(file_handle)

def compare_version(version1, version2):
    """Compares two versions."""
    def normalize(v):
        return [int(x) for x in re.sub('(\\.0+)*$', '', v).split('.')]
    return (normalize(version1) > normalize(version2)) - (normalize(version1) < normalize(version2))

def getmembers(object, predicate=None):
    """Return all members of an object as (name, value) pairs sorted by name.
    Optionally, only return members that satisfy a given predicate."""
    if inspect.isclass(object):
        mro = (object,) + inspect.getmro(object)
    else:
        mro = ()
    results = []
    processed = set()
    names = dir(object)
    try:
        for base in object.__bases__:
            for k, v in base.__dict__.items():
                if isinstance(v, types.DynamicClassAttribute):
                    names.append(k)
    except AttributeError:
        pass
    for key in names:
        try:
            value = getattr(object, key)
            if key in processed:
                raise AttributeError
        except AttributeError:
            for base in mro:
                if key in base.__dict__:
                    value = base.__dict__[key]
                    break
            else:
                continue
        except Exception as e:
            value = (RAISES_EXCEPTION, e)
        if not predicate or predicate(value):
            results.append((key, value))
        processed.add(key)
    results.sort(key=lambda pair: pair[0])
    return results

def maximum_variation(arr):
    """return np.max(arr, axis=0) - np.min(arr, axis=0)

    If `arr` is a 1D array, a scalar is returned.

    If `arr` is a 2D array (N x M), an array of length M is returned."""
    return np.max(arr, axis=0) - np.min(arr, axis=0)

def refine_get_urls(original):
    """serve static files (and media files also)

    in production the webserver should serve requested
    static files itself and never let requests to /static/*
    and /media/* get to the django application."""
    def get_urls():
        from django.conf.urls import url
        from django.conf import settings
        from django.contrib.staticfiles.urls import staticfiles_urlpatterns
        from django.views.static import serve
        if settings.DEBUG:
            return staticfiles_urlpatterns() + [url('^media/(?P<path>.*)$', serve, {'document_root': settings.MEDIA_ROOT})] + original()
        else:
            return original()
    return get_urls

def substitute(search, replace, text):
    """Regex substitution function. Replaces regex ``search`` with ``replace`` in ``text``"""
    return re.sub(re.compile(str(search)), replace, text)

def check_key(data_object, key, cardinal=False):
    """Update the value of an index key by matching values or getting positionals."""
    itype = (int, np.int32, np.int64)
    if not isinstance(key, itype + (slice, tuple, list, np.ndarray)):
        raise KeyError('Unknown key type {} for key {}'.format(type(key), key))
    keys = data_object.index.values
    if cardinal and data_object._cardinal is not None:
        keys = data_object[data_object._cardinal[0]].unique()
    elif isinstance(key, itype) and key in keys:
        key = list(sorted(data_object.index.values[key]))
    elif isinstance(key, itype) and key < 0:
        key = list(sorted(data_object.index.values[key]))
    elif isinstance(key, itype):
        key = [key]
    elif isinstance(key, slice):
        key = list(sorted(data_object.index.values[key]))
    elif isinstance(key, (tuple, list, pd.Index)) and (not np.all((k in keys for k in key))):
        key = list(sorted(data_object.index.values[key]))
    return key

def cached(namespace=None, service='memory', debug=False):
    """Wrapper for tornado requests. Example

    ```
    class MainHandler(tornado.web.RequestHandler):
        @debris.tornado.cached("home-page")
        def get(self):
            self.write("Hello, world")

    ```"""
    _service = getattr(debris.services, service)
    def wrapper(_f):
        @functools.wraps(_f)
        def _stash(self, *a, **k):
            if debug is False:
                try:
                    self.finish(_service.get(namespace))
                except LookupError:
                    _replace_finish(self, namespace, _service)
                    _f(self, *a, **k)
                return
            _f(self, *a, **k)
        return _stash
    return wrapper

def which(program, environ=None):
    """Find out if an executable exists in the supplied PATH.
    If so, the absolute path to the executable is returned.
    If not, an exception is raised.

    :type string
    :param program: Executable to be checked for

    :param dict
    :param environ: Any additional ENV variables required, specifically PATH

    :return string|:class:`command.CommandException` Returns the location if found, otherwise raises exception"""
    def is_exe(path):
        """Helper method to check if a file exists and is executable"""
        return isfile(path) and os.access(path, os.X_OK)
    if program is None:
        raise CommandException('Invalid program name passed')
    fpath, fname = split(program)
    if fpath:
        if is_exe(program):
            return program
    else:
        if environ is None:
            environ = os.environ
        for path in environ['PATH'].split(os.pathsep):
            exe_file = join(path, program)
            if is_exe(exe_file):
                return exe_file
    raise CommandException('Could not find %s' % program)

def bind_settings():
    """Put DJANGO_TEMPLATE_* under the right settings.* name according to django-version
    :return:"""
    from django_productline import settings
    if settings.TEMPLATE_LOADER_CACHED_ENABLED:
        loaders = [['django.template.loaders.cached.Loader', settings.DJANGO_TEMPLATE_LOADERS]]
    else:
        loaders = settings.DJANGO_TEMPLATE_LOADERS
    if compare_version(django.get_version(), '1.9') >= 0:
        TEMPLATES = [{'BACKEND': settings.DJANGO_TEMPLATE_BACKEND, 'DIRS': settings.DJANGO_TEMPLATE_DIRS, 'OPTIONS': {'builtins': settings.DJANGO_TEMPLATE_BUILTINS, 'context_processors': settings.DJANGO_TEMPLATE_CONTEXT_PROCESSORS, 'loaders': loaders, 'debug': settings.DJANGO_TEMPLATE_DEBUG}}]
        setattr(settings, 'TEMPLATES', TEMPLATES)
    else:
        setattr(settings, 'TEMPLATE_DEBUG', settings.DJANGO_TEMPLATE_DEBUG)
        setattr(settings, 'TEMPLATE_DIRS', settings.DJANGO_TEMPLATE_DIRS)
        setattr(settings, 'TEMPLATE_CONTEXT_PROCESSORS', settings.DJANGO_TEMPLATE_CONTEXT_PROCESSORS)
        setattr(settings, 'TEMPLATE_LOADERS', loaders)

def time_bins(header):
    """Returns the time-axis lower bin edge values for the spectrogram."""
    return np.arange(header['number_of_half_frames'], dtype=np.float64) * constants.bins_per_half_frame * (1.0 - header['over_sampling']) / header['subband_spacing_hz']

def frequency_bins(header):
    """Returnes the frequency-axis lower bin edge values for the spectrogram."""
    center_frequency = 1000000.0 * header['rf_center_frequency']
    if header['number_of_subbands'] > 1:
        center_frequency += header['subband_spacing_hz'] * (header['number_of_subbands'] / 2.0 - 0.5)
    return np.fft.fftshift(np.fft.fftfreq(int(header['number_of_subbands'] * constants.bins_per_half_frame * (1.0 - header['over_sampling'])), 1.0 / (header['number_of_subbands'] * header['subband_spacing_hz'])) + center_frequency)

def reshape_to_2d(arr):
    """Assumes a 3D Numpy array, and reshapes like

    arr.reshape((arr.shape[0], arr.shape[1]*arr.shape[2]))

    This is useful for converting processed data from `complex_to_power`
    and from `autocorrelation` into a 2D array for image analysis and display."""
    return arr.reshape((arr.shape[0], arr.shape[1] * arr.shape[2]))

def has_provider_support(provider, media_type):
    """Verifies if API provider has support for requested media type
    """
    if provider.lower() not in API_ALL:
        return False
    provider_const = 'API_' + media_type.upper()
    return provider in globals().get(provider_const, {})

def provider_factory(provider, **options):
    """Factory function for DB Provider Concrete Classes
    """
    try:
        return {'tmdb': TMDb, 'tvdb': TVDb}[provider.lower()](**options)
    except KeyError:
        msg = 'Attempted to initialize non-existing DB Provider'
        log.error(msg)
        raise MapiException(msg)

def _mkdirs(d):
    """Make all directories up to d.

    No exception is raised if d exists."""
    try:
        os.makedirs(d)
    except OSError as e:
        if e.errno != errno.EEXIST:
            raise

def _templated(fn):
    """Return a function which applies ``str.format(**ctl)`` to all results of
    ``fn(ctl)``."""
    @functools.wraps(fn)
    def inner(ctl):
        return [i.format(**ctl) for i in fn(ctl)]
    return inner

def lines_from_stream(f, as_interned=False):
    """Create a list of file lines from a given file stream.

    Args:
        f (io.TextIOWrapper): File stream
        as_interned (bool): List of "interned" strings (default False)

    Returns:
        strings (list): File line list"""
    if as_interned:
        return [sys.intern(line) for line in f.read().splitlines()]
    return f.read().splitlines()

def lines_from_string(string, as_interned=False):
    """Create a list of file lines from a given string.

    Args:
        string (str): File string
        as_interned (bool): List of "interned" strings (default False)

    Returns:
        strings (list): File line list"""
    if as_interned:
        return [sys.intern(line) for line in string.splitlines()]
    return string.splitlines()

def is_generic_union(type_: Type) -> bool:
    """Determines whether a type is a Union[...].

    How to do this varies for different Python versions, due to the
    typing library not having a stable API. This functions smooths
    over the differences.

    Args:
        type_: The type to check.

    Returns:
        True iff it's a Union[...something...]."""
    if hasattr(typing, '_GenericAlias'):
        return isinstance(type_, typing._GenericAlias) and type_.__origin__ is Union
    elif hasattr(typing, '_Union'):
        return isinstance(type_, typing._Union)
    else:
        return isinstance(type_, typing.UnionMeta)
    raise RuntimeError('Could not determine whether type is a Union. Is this a YAtiML-supported Python version?')

def staticdir():
    """Return the location of the static data directory."""
    root = os.path.abspath(os.path.dirname(__file__))
    return os.path.join(root, 'static')

def resource(name):
    """Return the full path of a named resource in the static directory.

    If multiple files with the same name exist, **name** should contain
    the first directory as well.

    .. code-block:: python

        resource("myfile")
        resource("test01/test.txt")
        resource("test02/test.txt")"""
    for path, _, files in os.walk(staticdir()):
        if name in files:
            return os.path.abspath(os.path.join(path, name))

def add_to_loader(loader_cls: Type, classes: List[Type]) -> None:
    """Registers one or more classes with a YAtiML loader.

    Once a class has been registered, it can be recognized and     constructed when reading a YAML text.

    Args:
        loader_cls: The loader to register the classes with.
        classes: The class(es) to register, a plain Python class or a                 list of them."""
    if not isinstance(classes, list):
        classes = [classes]
    for class_ in classes:
        tag = '!{}'.format(class_.__name__)
        if issubclass(class_, enum.Enum):
            loader_cls.add_constructor(tag, EnumConstructor(class_))
        elif issubclass(class_, str) or issubclass(class_, UserString):
            loader_cls.add_constructor(tag, UserStringConstructor(class_))
        else:
            loader_cls.add_constructor(tag, Constructor(class_))
        if not hasattr(loader_cls, '_registered_classes'):
            loader_cls._registered_classes = dict()
        loader_cls._registered_classes[tag] = class_

def set_cell_value(cell, value):
    """Convenience method for setting the value of an openpyxl cell

    This is necessary since the value property changed from internal_value
    to value between version 1.* and 2.*."""
    if OPENPYXL_MAJOR_VERSION > 1:
        cell.value = value
    else:
        cell.internal_value = value

def _backward_delete_char(text, pos):
    """Delete the character behind pos."""
    if pos == 0:
        return (text, pos)
    return (text[:pos - 1] + text[pos:], pos - 1)

def _backward_kill_word(text, pos):
    """"
    Kill the word behind pos. Word boundaries are the same as those
    used by _backward_word."""
    text, new_pos = _backward_word(text, pos)
    return (text[:new_pos] + text[pos:], new_pos)

def _backward_word(text, pos):
    """Move pos back to the start of the current or previous word. Words
    are composed of alphanumeric characters (letters and digits)."""
    while pos > 0 and (not text[pos - 1].isalnum()):
        pos -= 1
    while pos > 0 and text[pos - 1].isalnum():
        pos -= 1
    return (text, pos)

def _capitalize_word(text, pos):
    """Capitalize the current (or following) word."""
    while pos < len(text) and (not text[pos].isalnum()):
        pos += 1
    if pos < len(text):
        text = text[:pos] + text[pos].upper() + text[pos + 1:]
    while pos < len(text) and text[pos].isalnum():
        pos += 1
    return (text, pos)

def _delete_horizontal_space(text, pos):
    """Delete all spaces and tabs around pos."""
    while pos > 0 and text[pos - 1].isspace():
        pos -= 1
    end_pos = pos
    while end_pos < len(text) and text[end_pos].isspace():
        end_pos += 1
    return (text[:pos] + text[end_pos:], pos)

def _downcase_word(text, pos):
    """Lowercase the current (or following) word."""
    text, new_pos = _forward_word(text, pos)
    return (text[:pos] + text[pos:new_pos].lower() + text[new_pos:], new_pos)

def _forward_word(text, pos):
    """Move pos forward to the end of the next word. Words are composed of
    alphanumeric characters (letters and digits)."""
    while pos < len(text) and (not text[pos].isalnum()):
        pos += 1
    while pos < len(text) and text[pos].isalnum():
        pos += 1
    return (text, pos)

def _kill_word(text, pos):
    """Kill from pos to the end of the current word, or if between words,
    to the end of the next word. Word boundaries are the same as those
    used by _forward_word."""
    text, end_pos = _forward_word(text, pos)
    return (text[:pos] + text[end_pos:], pos)

def _transpose_chars(text, pos):
    """Drag the character before pos forward over the character at pos,
    moving pos forward as well. If pos is at the end of text, then this
    transposes the two characters before pos."""
    if len(text) < 2 or pos == 0:
        return (text, pos)
    if pos == len(text):
        return (text[:pos - 2] + text[pos - 1] + text[pos - 2], pos)
    return (text[:pos - 1] + text[pos] + text[pos - 1] + text[pos + 1:], pos + 1)

def _transpose_words(text, pos):
    """Drag the word before pos past the word after pos, moving pos over
    that word as well. If pos is at the end of text, this transposes the
    last two words in text."""
    text, end2 = _forward_word(text, pos)
    text, start2 = _backward_word(text, end2)
    text, start1 = _backward_word(text, start2)
    text, end1 = _forward_word(text, start1)
    if start1 == start2:
        return (text, pos)
    return (text[:start1] + text[start2:end2] + text[end1:start2] + text[start1:end1] + text[end2:], end2)

def _unix_word_rubout(text, pos):
    """Kill the word behind pos, using white space as a word boundary."""
    words = text[:pos].rsplit(None, 1)
    if len(words) < 2:
        return (text[pos:], 0)
    else:
        index = text.rfind(words[1], 0, pos)
        return (text[:index] + text[pos:], index)

def _upcase_word(text, pos):
    """Uppercase the current (or following) word."""
    text, new_pos = _forward_word(text, pos)
    return (text[:pos] + text[pos:new_pos].upper() + text[new_pos:], new_pos)

def edit(text, pos, key):
    """Process a key input in the context of a line, and return the
    resulting text and cursor position.

    `text' and `key' must be of type str or unicode, and `pos' must be
    an int in the range [0, len(text)].

    If `key' is in keys(), the corresponding command is executed on the
    line. Otherwise, if `key' is a single character, that character is
    inserted at the cursor position. If neither condition is met, `text'
    and `pos' are returned unmodified."""
    if key in _key_bindings:
        return _key_bindings[key](text, pos)
    elif len(key) == 1:
        return (text[:pos] + key + text[pos:], pos + 1)
    else:
        return (text, pos)

def a_temp_file():
    """Yield the name of a temporary file and ensure it's removed after use"""
    filename = None
    try:
        tmpfile = tempfile.NamedTemporaryFile(delete=False)
        filename = tmpfile.name
        yield tmpfile
    finally:
        if filename and os.path.exists(filename):
            os.remove(filename)

def until(timeout=10, step=0.5, action=None, silent=False):
    """Yield until timeout"""
    yield
    started = time.time()
    while True:
        if action and (not silent):
            log.info(action)
        if time.time() - started > timeout:
            if action and (not silent):
                log.error('Timedout %s', action)
            return
        else:
            time.sleep(step)
            yield

def write_to(output, txt):
    """Write some text to some output"""
    if (isinstance(txt, six.binary_type) or (six.PY3 and isinstance(output, StringIO))) or isinstance(output, TextIOWrapper):
        output.write(txt)
    else:
        output.write(txt.encode('utf-8', 'replace'))

def pad_ranges(inranges, padding, chr_ranges=None):
    """Add the specfied amount onto the edges the transcripts

    :param inranges: List of genomic ranges in Bed o GenomicRange format.
    :param padding: how much to add on
    :param chr_ranges: looks like the list of ranges within which to pad
    :type inranges: GenomicRange[]
    :type padding: int
    :type chr_ranges:"""
    if not inranges:
        return
    outranges = []
    if len(inranges) == 0:
        return outranges
    chr = {}
    if chr_ranges:
        for b in chr_ranges:
            chr[b.chr] = b
    for rng in inranges:
        newstart = rng.start - padding
        newend = rng.end + padding
        if rng.chr in chr:
            if newstart < chr[rng.chr].start:
                newstart = chr[rng.chr].start
            if newend > chr[rng.chr].end:
                endstart = chr[rng.chr].end
        nrng = rng.copy()
        nrng.start = newstart
        nrng.end = newend
        outranges.append(nrng)
    return sort_ranges(outranges)

def intersect_range_array(bed1, beds2, payload=None, is_sorted=False):
    """Does not do a merge if the payload has been set

    :param bed1:
    :param bed2:
    :param payload: payload=1 return the payload of bed1 on each of the intersect set, payload=2 return the payload of bed2 on each of the union set, payload=3 return the payload of bed1 and bed2 on each of the union set
    :param is_sorted:
    :type bed1: GenomicRange
    :type bed2: GenomicRange
    :type payload: int
    :type is_sorted: bool"""
    if not is_sorted:
        beds2 = sort_ranges(beds2)
    output = []
    for bed2 in beds2:
        cval = bed2.cmp(bed1)
        if cval == -1:
            continue
        elif cval == 0:
            output.append(bed1.intersect(bed2))
            if payload == 1:
                output[-1].set_payload(bed1.payload)
            if payload == 2:
                output[-1].set_payload(bed2.payload)
        elif cval == 1:
            break
    if payload:
        return sort_ranges(output)
    return merge_ranges(output)

def string_to_genomic_range(rstring):
    """Convert a string to a genomic range

    :param rstring: string representing a genomic range chr1:801-900
    :type rstring:
    :returns: object representing the string
    :rtype: GenomicRange"""
    m = re.match('([^:]+):(\\d+)-(\\d+)', rstring)
    if not m:
        sys.stderr.write('ERROR: problem with range string ' + rstring + '\n')
    return GenomicRange(m.group(1), int(m.group(2)), int(m.group(3)))

def sort_genomic_ranges(rngs):
    """sort multiple ranges"""
    return sorted(rngs, key=lambda x: (x.chr, x.start, x.end))

def security(name, *permissions):
    """Decorator to add security definition."""
    def inner(c):
        c.security = Security(name, *permissions)
        return c
    return inner

def action(callback=None, name=None, path=None, methods=Method.GET, resource=None, tags=None, summary=None, middleware=None):
    """Decorator to apply an action to a resource. An action is applied to a `detail` operation."""
    path = path or '{key_field}'
    if name:
        path += name
    def inner(c):
        return Operation(c, path, methods, resource, tags, summary, middleware)
    return inner(callback) if callback else inner

def range_return(request, items):
    """Determine what range of objects to return.

    Will check fot both `Range` and `X-Range` headers in the request and
    set both `Content-Range` and 'X-Content-Range' headers.

    :rtype: list"""
    if 'Range' in request.headers:
        range = parse_range_header(request.headers['Range'])
    elif 'X-Range' in request.headers:
        range = parse_range_header(request.headers['X-Range'])
    else:
        range = {'start': 0, 'finish': MAX_NUMBER_ITEMS - 1, 'count': MAX_NUMBER_ITEMS}
    filtered = items[range['start']:range['finish'] + 1]
    if len(filtered) < range['count']:
        range['count'] = len(filtered)
        range['finish'] = range['start'] + range['count'] - 1
    if range['finish'] - range['start'] + 1 >= MAX_NUMBER_ITEMS:
        range['finish'] = range['start'] + MAX_NUMBER_ITEMS - 1
        filtered = items[range['start']:range['finish'] + 1]
    request.response.headers['Content-Range'] = 'items %d-%d/%d' % (range['start'], range['finish'], len(items))
    request.response.headers['X-Content-Range'] = request.response.headers['Content-Range']
    return filtered

def _double_encoding_factory(encoder, byte_encoder, byte_encoding):
    """Send the transliterated output to another codec."""
    def dbl_encode(input, errors='strict'):
        uni, length = encoder(input, errors)
        return (byte_encoder(uni, errors)[0], length)
    dbl_encode.__name__ = '%s_%s' % (encoder.__name__, byte_encoding)
    return dbl_encode

def trans_search(encoding):
    """Lookup transliterating codecs."""
    if encoding == 'transliterate':
        return codecs.CodecInfo(long_encode, no_decode)
    if encoding.startswith('translit/'):
        parts = encoding.split('/')
        if parts[1] == 'long':
            encoder = long_encode
        elif parts[1] == 'short':
            encoder = short_encode
        elif parts[1] == 'one':
            encoder = single_encode
        else:
            return None
        if len(parts) == 2:
            pass
        elif len(parts) == 3:
            byte_enc = parts[2]
            byte_encoder = codecs.lookup(byte_enc).encode
            encoder = _double_encoding_factory(encoder, byte_encoder, byte_enc)
        else:
            return None
        return codecs.CodecInfo(encoder, no_decode)
    return None

def getLogger(name):
    """Return a logger from a given name.

    If the name does not have a log handler, this will create one for it based
    on the module name which will log everything to a log file in a location
    the executing user will have access to.

    :param name: ``str``
    :return: ``object``"""
    log = logging.getLogger(name=name)
    for handler in log.handlers:
        if name == handler.name:
            return log
    else:
        return LogSetup().default_logger(name=name.split('.')[0])

def parse(requirements):
    """Parses given requirements line-by-line."""
    transformer = RTransformer()
    return map(transformer.transform, filter(None, map(_parse, requirements.splitlines())))

def make_random_histogram(center=0.0, stdev=default_stdev, length=default_feature_dim, num_bins=default_num_bins):
    """Returns a sequence of histogram density values that sum to 1.0"""
    hist, bin_edges = np.histogram(get_distr(center, stdev, length), range=edge_range, bins=num_bins, density=True)
    hist = hist / sum(hist)
    if len(hist) < 2:
        raise ValueError('Invalid histogram')
    return (hist, bin_edges)

def push(collector, image, **kwargs):
    """Push an image"""
    if not image.image_index:
        raise BadOption('The chosen image does not have a image_index configuration', wanted=image.name)
    tag = kwargs['artifact']
    if tag is NotSpecified:
        tag = collector.configuration['harpoon'].tag
    if tag is not NotSpecified:
        image.tag = tag
    Builder().make_image(image, collector.configuration['images'], pushing=True)
    Syncer().push(image)

def pull_arbitrary(collector, image, **kwargs):
    """Pull an arbitrary image"""
    image_index_of = lambda image: urlparse('https://{0}'.format(image)).netloc
    if image.startswith('file://'):
        parsed = urlparse(image)
        filename = parsed.netloc + parsed.path
        if not os.path.exists(filename):
            raise HarpoonError("Provided file doesn't exist!", wanted=image)
        with open(filename) as fle:
            image_indexes = [(line.strip(), image_index_of(line.strip())) for line in fle]
    else:
        image_indexes = [(image, image_index_of(image))]
    authentication = collector.configuration.get('authentication', NotSpecified)
    for index, (image, image_index) in enumerate(image_indexes):
        tag = sb.NotSpecified
        if ':' in image:
            image, tag = image.split(':', 1)
        image = {'image_name': image, 'tag': tag, 'harpoon': collector.configuration['harpoon'], 'commands': ['FROM scratch'], 'image_index': image_index, 'assume_role': NotSpecified, 'authentication': authentication}
        meta = Meta(collector.configuration, []).at('images').at('__arbitrary_{0}__'.format(index))
        image = HarpoonSpec().image_spec.normalise(meta, image)
        Syncer().pull(image)

def pull(collector, image, **kwargs):
    """Pull an image"""
    if not image.image_index:
        raise BadOption('The chosen image does not have a image_index configuration', wanted=image.name)
    tag = kwargs['artifact']
    if tag is NotSpecified:
        collector.configuration['harpoon'].tag
    if tag is not NotSpecified:
        image.tag = tag
        log.info('Pulling tag: %s', tag)
    Syncer().pull(image, ignore_missing=image.harpoon.ignore_missing)

def pull_dependencies(collector, image, **kwargs):
    """Pull an image's dependent images"""
    for dep in image.commands.dependent_images:
        kwargs['image'] = dep
        pull_arbitrary(collector, **kwargs)

def pull_all(collector, image, **kwargs):
    """Pull all the images"""
    images = collector.configuration['images']
    for layer in Builder().layered(images, only_pushable=True):
        for image_name, image in layer:
            log.info('Pulling %s', image_name)
            pull(collector, image, **kwargs)

def pull_all_external(collector, **kwargs):
    """Pull all the external dependencies of all the images"""
    deps = set()
    images = collector.configuration['images']
    for layer in Builder().layered(images):
        for image_name, image in layer:
            for dep in image.commands.external_dependencies:
                deps.add(dep)
    for dep in sorted(deps):
        kwargs['image'] = dep
        pull_arbitrary(collector, **kwargs)

def make(collector, image, **kwargs):
    """Just create an image"""
    tag = kwargs.get('artifact', NotSpecified)
    if tag is NotSpecified:
        tag = collector.configuration['harpoon'].tag
    if tag is not NotSpecified:
        image.tag = tag
    Builder().make_image(image, collector.configuration['images'])
    print('Created image {0}'.format(image.image_name))

def make_all(collector, **kwargs):
    """Creates all the images in layered order"""
    configuration = collector.configuration
    push = configuration['harpoon'].do_push
    only_pushable = configuration['harpoon'].only_pushable
    if push:
        only_pushable = True
    tag = kwargs.get('artifact', NotSpecified)
    if tag is NotSpecified:
        tag = configuration['harpoon'].tag
    images = configuration['images']
    for layer in Builder().layered(images, only_pushable=only_pushable):
        for _, image in layer:
            if tag is not NotSpecified:
                image.tag = tag
            Builder().make_image(image, images, ignore_deps=True, ignore_parent=True)
            print('Created image {0}'.format(image.image_name))
            if push and image.image_index:
                Syncer().push(image)

def delete_untagged(collector, **kwargs):
    """Find the untagged images and remove them"""
    configuration = collector.configuration
    docker_api = configuration['harpoon'].docker_api
    images = docker_api.images()
    found = False
    for image in images:
        if image['RepoTags'] == ['<none>:<none>']:
            found = True
            image_id = image['Id']
            log.info('Deleting untagged image\thash=%s', image_id)
            try:
                docker_api.remove_image(image['Id'])
            except DockerAPIError as error:
                log.error('Failed to delete image\thash=%s\terror=%s', image_id, error)
    if not found:
        log.info("Didn't find any untagged images to delete!")

def show(collector, **kwargs):
    """Show what images we have"""
    configuration = collector.configuration
    flat = configuration.get('harpoon.flat', False)
    only_pushable = configuration.get('harpoon.only_pushable', False)
    for index, layer in enumerate(Builder().layered(configuration['images'], only_pushable=only_pushable)):
        if flat:
            for _, image in layer:
                print(image.image_name)
        else:
            print('Layer {0}'.format(index))
            for _, image in layer:
                print('    {0}'.format(image.display_line()))
            print('')

def untag(collector, image, artifact, **kwargs):
    """Tag an image!"""
    if artifact in (None, '', NotSpecified):
        artifact = collector.configuration['harpoon'].tag
    if artifact is NotSpecified:
        raise BadOption('Please specify a tag using the artifact or tag options')
    image.tag = artifact
    image_name = image.image_name_with_tag
    log.info('Removing image\timage={0}'.format(image_name))
    try:
        image.harpoon.docker_api.remove_image(image_name)
    except docker.errors.ImageNotFound:
        log.warning('No image was found to remove')

def tag(collector, image, artifact, **kwargs):
    """Tag an image!"""
    if artifact in (None, '', NotSpecified):
        raise BadOption('Please specify a tag using the artifact option')
    if image.image_index in (None, '', NotSpecified):
        raise BadOption('Please specify an image with an image_index option')
    tag = image.image_name
    if collector.configuration['harpoon'].tag is not NotSpecified:
        tag = '{0}:{1}'.format(tag, collector.configuration['harpoon'].tag)
    else:
        tag = '{0}:latest'.format(tag)
    images = image.harpoon.docker_api.images()
    current_tags = chain.from_iterable((image_conf['RepoTags'] for image_conf in images if image_conf['RepoTags'] is not None))
    if tag not in current_tags:
        raise BadOption('Please build or pull the image down to your local cache before tagging it')
    for image_conf in images:
        if image_conf['RepoTags'] is not None:
            if tag in image_conf['RepoTags']:
                image_id = image_conf['Id']
                break
    log.info('Tagging {0} ({1}) as {2}'.format(image_id, image.image_name, artifact))
    image.harpoon.docker_api.tag(image_id, repository=image.image_name, tag=artifact, force=True)
    image.tag = artifact
    Syncer().push(image)

def retrieve(collector, image, artifact, **kwargs):
    """Retrieve a file/folder from an image"""
    if artifact in (None, '', NotSpecified):
        raise BadOption('Please specify what to retrieve using the artifact option')
