def resource_definition(resource):
    """Generate a `Swagger Definitions Object <http://swagger.io/specification/#definitionsObject>`_
    from a resource."""
    meta = getmeta(resource)
    definition = {'type': 'object', 'properties': {}}
    for field in meta.all_fields:
        field_definition = {}
        type_def = map_field_to_type(field)
        if type_def:
            field_definition['type'] = str(type_def)
            if type_def.format:
                field_definition['format'] = type_def.format
        if field.doc_text:
            field_definition['description'] = field.doc_text
        if isinstance(field, VirtualField) or field in meta.readonly_fields:
            field_definition['readOnly'] = True
        if getattr(field, 'choices', None):
            field_definition['enum'] = [c[0] for c in field.choices]
        definition['properties'][field.name] = field_definition
    return definition

def profile(message=None, verbose=False):
    """Decorator for profiling a function.

    TODO: Support `@profile` syntax (without parens). This would involve
    inspecting the args. In this case `profile` would receive a single
    argument, which is the function to be decorated."""
    import functools
    from harrison.registered_timer import RegisteredTimer
    class DecoratorTimer(RegisteredTimer):
        _CALLER_STACK_INDEX = 2
    def wrapper(fn):
        desc = message or fn.__name__
        @functools.wraps(fn)
        def wrapped_fn(*args, **kwargs):
            with DecoratorTimer(desc=desc, verbose=verbose):
                return fn(*args, **kwargs)
        return wrapped_fn
    return wrapper

def gather_repositories():
    """Collects all of the repositories. The current implementation
    searches for them in the current working directory."""
    for root, dirs, files in os.walk('.', topdown=True):
        if '.git' not in dirs:
            continue
        for dir in list(dirs):
            dirs.remove(dir)
        path = os.path.split(root)[1]
        repo = os.path.basename(path)
        yield (repo, root)

def run(command, exit, silent, check):
    """Runs given command on all repos and checks status

        $ maintain repo run -- git checkout master"""
    status = 0
    for repo, path in gather_repositories():
        if check and (not check_repo(repo, path)):
            status = 1
            if exit:
                break
            continue
        with chdir(path):
            result = subprocess.run(command, shell=True, capture_output=silent)
            if result.returncode != 0:
                status = result.returncode
                print('Command failed: {}'.format(repo))
                if exit:
                    break
    sys.exit(status)

def _do_serialize(struct, fmt, encoding):
    """Actually serialize input.

    Args:
        struct: structure to serialize to
        fmt: format to serialize to
        encoding: encoding to use while serializing
    Returns:
        encoded serialized structure
    Raises:
        various sorts of errors raised by libraries while serializing"""
    res = None
    _check_lib_installed(fmt, 'serialize')
    if fmt == 'ini':
        config = configobj.ConfigObj(encoding=encoding)
        for k, v in struct.items():
            config[k] = v
        res = b'\n'.join(config.write())
    elif fmt in ['json', 'json5']:
        res = (json if fmt == 'json' else json5).dumps(struct, indent=2, separators=(',', ': '), ensure_ascii=False).encode(encoding)
    elif fmt == 'toml':
        if not _is_utf8(encoding):
            raise AnyMarkupError('toml must always be utf-8 encoded according to specification')
        res = toml.dumps(struct).encode(encoding)
    elif fmt == 'xml':
        res = xmltodict.unparse(struct, pretty=True, encoding='utf-8').encode('utf-8')
    elif fmt == 'yaml':
        res = yaml.safe_dump(struct, encoding='utf-8', default_flow_style=False)
    else:
        raise
    return res

def _recognize_basic_types(s):
    """If value of given string `s` is an integer (or long), float or boolean, convert it
    to a proper type and return it."""
    tps = [int, float]
    if not six.PY3:
        tps.append(long)
    for tp in tps:
        try:
            return tp(s)
        except ValueError:
            pass
    if s.lower() == 'true':
        return True
    if s.lower() == 'false':
        return False
    if s.lower() in ['none', 'null']:
        return None
    return s

def _get_format(format, fname, inp=None):
    """Try to guess markup format of given input.

    Args:
        format: explicit format override to use
        fname: name of file, if a file was used to read `inp`
        inp: optional bytestring to guess format of (can be None, if markup
            format is to be guessed only from `format` and `fname`)
    Returns:
        guessed format (a key of fmt_to_exts dict)
    Raises:
        AnyMarkupError if explicit format override has unsupported value
            or if it's impossible to guess the format"""
    fmt = None
    err = True
    if format is not None:
        if format in fmt_to_exts:
            fmt = format
            err = False
    elif fname:
        file_ext = os.path.splitext(fname)[1][len(os.path.extsep):]
        for fmt_name, exts in fmt_to_exts.items():
            if file_ext in exts:
                fmt = fmt_name
                err = False
    if fmt is None:
        if inp is not None:
            fmt = _guess_fmt_from_bytes(inp)
            err = False
    if err:
        err_string = 'Failed to guess markup format based on: '
        what = []
        for k, v in {format: 'specified format argument', fname: 'filename', inp: 'input string'}.items():
            if k:
                what.append(v)
        if not what:
            what.append('nothing to guess format from!')
        err_string += ', '.join(what)
        raise AnyMarkupError(err_string)
    return fmt

def _guess_fmt_from_bytes(inp):
    """Try to guess format of given bytestring.

    Args:
        inp: byte string to guess format of
    Returns:
        guessed format"""
    stripped = inp.strip()
    fmt = None
    ini_section_header_re = re.compile(b'^\\[([\\w-]+)\\]')
    if len(stripped) == 0:
        fmt = 'yaml'
    elif stripped.startswith(b'<'):
        fmt = 'xml'
    else:
        for l in stripped.splitlines():
            line = l.strip()
            if not line.startswith(b'#') and line:
                break
        if ini_section_header_re.match(line):
            fmt = 'ini'
        else:
            fmt = 'yaml'
    return fmt

def errors(request, *args, **kwargs):
    """A dummy view that will throw errors.

    It'll throw any HTTP error that is contained in the search query."""
    search_term = request.GET.get('q', None)
    if '400' in search_term:
        return HttpResponseBadRequest(MESSAGE_400)
    elif '403' in search_term:
        return HttpResponseForbidden(MESSAGE_403)
    elif '404' in search_term:
        return HttpResponseNotFound(MESSAGE_404)
    elif '405' in search_term:
        return HttpResponseNotAllowed(['PATCH'], MESSAGE_405)
    return HttpResponseServerError(MESSAGE_500)

def parser(*events):
    """Decorator for convenience - adds a function as a parser for event(s)."""
