def check_read_lengths(ribo_file, read_lengths):
    """Check if read lengths are valid (positive)."""
    valid_lengths = list(set(read_lengths))
    if len(valid_lengths) == 1 and valid_lengths[0] == 0:
        return
    for read_length in valid_lengths:
        if read_length < 0:
            msg = 'Read length must be a positive value'
            log.error(msg)
            raise ArgumentError(msg)

def check_read_offsets(read_offsets):
    """Check if read offsets are valid (positive)."""
    for read_offset in read_offsets:
        if read_offset < 0:
            msg = 'Read offset must be 0 or greater'
            log.error(msg)
            raise ArgumentError(msg)

def is_header(line):
    """true if we are in a header"""
    if re.match('^@', line):
        f = line.rstrip().split('\t')
        if len(f) > 9:
            return False
        return True
    return False

def sort_header(header_text):
    """sort the chromosomes in a header text"""
    lines = header_text.rstrip().split('\n')
    rlens = {}
    for ln in lines:
        m = re.match('@SQ\tSN:(\\S+)\tLN:(\\S+)', ln)
        if m:
            rlens[m.group(1)] = m.group(2)
    output = ''
    done_lens = False
    for ln in lines:
        if re.match('@SQ\tSN:', ln):
            if not done_lens:
                done_lens = True
                for chr in sorted(rlens.keys()):
                    output += '@SQ\tSN:' + chr + '\tLN:' + str(rlens[chr]) + '\n'
        else:
            output += ln.rstrip('\n') + '\n'
    return output

def allow_create(function):
    """Decorate the `form_valid` method in a Create/Update class to create new
    values if necessary.

    .. warning::

        Make sure that this decorator **only** decorates the ``form_valid()``
        method and **only** this one."""
    @wraps(function)
    def _wrapped_func(*args, **kwargs):
        form = args[0]
        if isinstance(form, (Form, ModelForm)):
            if not form.is_valid():
                return function(*args, **kwargs)
            for k, field in form.fields.items():
                if getattr(field, 'create', False) and getattr(field, '_new_values', None):
                    new_values = field.create_new_values()
                    form.cleaned_data[k] = form.cleaned_data[k] | new_values
        return function(*args, **kwargs)
    return _wrapped_func

def is_valid_package_module_name(name):
    """Test whether it's a valid package or module name.

    - a-z, 0-9, and underline
    - starts with underline or alpha letter

    valid:

    - ``a``
    - ``a.b.c``
    - ``_a``
    - ``_a._b._c``

    invalid:

    - ``A``
    - ``0``
    - ``.a``
    - ``a#b``"""
    if '.' in name:
        for part in name.split('.'):
            if not is_valid_package_module_name(part):
                return False
    elif len(name):
        if name[0] not in _first_letter_for_valid_name:
            return False
        if len(set(name).difference(_char_set_for_valid_name)):
            return False
    else:
        return False
    return True

def _generate_signature(url_path, secret_key, query_args, digest=None, encoder=None):
    """Generate signature from pre-parsed URL."""
    digest = digest or DEFAULT_DIGEST
    encoder = encoder or DEFAULT_ENCODER
    msg = '%s?%s' % (url_path, '&'.join(('%s=%s' % i for i in query_args.sorteditems(multi=True))))
    if _compat.text_type:
        msg = msg.encode('UTF8')
    signature = hmac.new(secret_key, msg, digestmod=digest).digest()
    if _compat.PY2:
        return encoder(signature).rstrip('=')
    else:
        return encoder(signature).decode().rstrip('=')

def b64_hmac_md5(key, data):
    """return base64-encoded HMAC-MD5 for key and data, with trailing '='
    stripped."""
    bdigest = base64.b64encode(hmac.new(key, data, _md5).digest()).strip().decode('utf-8')
    return re.sub('=+$', '', bdigest)

def generate(password, uri):
    """generate the pwdhash password for master password and uri or
    domain name."""
    realm = extract_domain(uri)
    if password.startswith(_password_prefix):
        password = password[len(_password_prefix):]
    password_hash = b64_hmac_md5(password.encode('utf-8'), realm.encode('utf-8'))
    size = len(password) + len(_password_prefix)
    nonalphanumeric = len(re.findall('\\W', password)) != 0
    return apply_constraints(password_hash, size, nonalphanumeric)

def apply_constraints(phash, size, nonalphanumeric):
    """Fiddle with the password a bit after hashing it so that it will
    get through most website filters. We require one upper and lower
    case, one digit, and we look at the user's password to determine
    if there should be at least one alphanumeric or not."""
    starting_size = max(0, size - 4)
    result = phash[:starting_size]
    extras = itertools.chain((ord(ch) for ch in phash[starting_size:]), itertools.repeat(0))
    extra_chars = (chr(ch) for ch in extras)
    nonword = re.compile('\\W')
    def next_between(start, end):
        interval = ord(end) - ord(start) + 1
        offset = next(extras) % interval
        return chr(ord(start) + offset)
    for elt, repl in ((re.compile('[A-Z]'), lambda: next_between('A', 'Z')), (re.compile('[a-z]'), lambda: next_between('a', 'z')), (re.compile('[0-9]'), lambda: next_between('0', '9'))):
        if len(elt.findall(result)) != 0:
            result += next(extra_chars)
        else:
            result += repl()
    if len(nonword.findall(result)) != 0 and nonalphanumeric:
        result += next(extra_chars)
    else:
        result += '+'
    while len(nonword.findall(result)) != 0 and (not nonalphanumeric):
        result = nonword.sub(next_between('A', 'Z'), result, 1)
    amount = next(extras) % len(result)
    result = result[amount:] + result[0:amount]
    return result

