def GenomicRangeFromString(range_string, payload=None, dir=None):
    """Constructor for a GenomicRange object that takes a string"""
    m = re.match('^(.+):(\\d+)-(\\d+)$', range_string)
    if not m:
        sys.stderr.write('ERROR bad genomic range string\n' + range_string + '\n')
        sys.exit()
    chr = m.group(1)
    start = int(m.group(2))
    end = int(m.group(3))
    return GenomicRange(chr, start, end, payload, dir)

def parse_log_entry(text):
    """This function does all real job on log line parsing.
    it setup two cases for restart parsing if a line
    with wrong format was found.

    Restarts:
    - use_value: just retuns an object it was passed. This can
      be any value.
    - reparse: calls `parse_log_entry` again with other text value.
      Beware, this call can lead to infinite recursion."""
    text = text.strip()
    if well_formed_log_entry_p(text):
        return LogEntry(text)
    else:
        def use_value(obj):
            return obj
        def reparse(text):
            return parse_log_entry(text)
        with restarts(use_value, reparse) as call:
            return call(signal, MalformedLogEntryError(text))

def parse_prototype(prototype):
    """Returns a :attr:`FunctionSpec` instance from the input.
    """
    val = ' '.join(prototype.splitlines())
    f = match(func_pat, val)
    if f is None:
        raise Exception('Cannot parse function prototype "{}"'.format(val))
    ftp, pointer, name, arg = [v.strip() for v in f.groups()]
    args = []
    if arg.strip():
        for item in split(arg_split_pat, arg):
            m = match(variable_pat, item.strip())
            if m is None:
                raise Exception('Cannot parse function prototype "{}"'.format(val))
            tp, star, nm, count = [v.strip() if v else '' for v in m.groups()]
            args.append(VariableSpec(tp, star, nm, count))
    return FunctionSpec('FLYCAPTURE2_C_API', ftp, pointer, name, args)

def parse_struct(type_name, body, name):
    """Returns a :attr:`StructSpec` instance from the input.
    """
    type_name, name = (type_name.strip(), name.strip())
    lines = [l.strip() for l in body.splitlines() if l.strip()]
    members = []
    for line in lines:
        m = match(variable_pat, line)
        if m is None:
            raise Exception('Cannot parse "{}" for "{}"'.format(line, name))
        tp, star, nm, count = [v.strip() if v else '' for v in m.groups()]
        members.append(VariableSpec(tp, star, nm, count))
    return StructSpec(type_name, [n.strip() for n in name.split(',')], members)

def parse_enum(type_name, body, name):
    """Returns a :attr:`EnumSpec` instance from the input.
    """
    type_name, name = (type_name.strip(), name.strip())
    lines = [l.strip(' ,') for l in body.splitlines() if l.strip(', ')]
    members = []
    for line in lines:
        vals = [v.strip() for v in line.split('=')]
        if len(vals) == 1:
            members.append(EnumMemberSpec(vals[0], ''))
        else:
            members.append(EnumMemberSpec(*vals))
    return EnumSpec(type_name, [n.strip() for n in name.split(',')], members)

def format_enum(enum_def):
    """Returns a cython enum from a :attr:`EnumSpec` instance.
    """
    text = []
    text.append('cdef enum {}:'.format(enum_def.tp_name))
    for member in enum_def.values:
        if member.value:
            text.append('{}{} = {}'.format(tab, *member))
        else:
            text.append('{}{}'.format(tab, member.name))
    for name in enum_def.names:
        text.append('ctypedef {} {}'.format(enum_def.tp_name, name))
    return text

def memoize(f):
    """Cache value returned by the function."""
    @wraps(f)
    def w(*args, **kw):
        memoize.mem[f] = v = f(*args, **kw)
        return v
    return w

def project2module(project):
    """Convert project name into a module name."""
    project = project.lower().replace('-', '_')
    if project.startswith('python_'):
        project = project[7:]
    return project

def ffprobe(input_file, verbose=False):
    """Runs ffprobe on file and returns python dict with result"""
    if isinstance(input_file, FileObject):
        exists = input_file.exists
        path = input_file.path
    elif type(input_file) in string_types:
        exists = os.path.exists(input_file)
        path = input_file
    else:
        raise TypeError('input_path must be of string or FileObject type')
    if not exists:
        logging.error('ffprobe: file does not exist ({})'.format(input_file))
        return False
    cmd = ['ffprobe', '-show_format', '-show_streams', '-print_format', 'json', path]
    FNULL = open(os.devnull, 'w')
    if verbose:
        logging.debug('Executing {}'.format(' '.join(cmd)))
    proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    res = decode_if_py3(proc.stdout.read())
    proc.wait()
    if proc.returncode:
        if verbose:
            logging.error('Unable to read media file {}\n\n{}\n\n'.format(input_file, indent(proc.stderr.read())))
        else:
            logging.warning('Unable to read media file {}'.format(input_file))
        return False
    return json.loads(res)

def class_check_para(**kw):
    """force check accept and return,
    decorator, @class_check_para(accept=, returns=, mail=)
    :param kw:
    :return:"""
    try:
        def decorator(f):
            def new_f(*args):
                if 'accepts' in kw:
                    assert len(args) == len(kw['accepts']) + 1
                    arg_types = tuple(map(type, args[1:]))
                    if arg_types != kw['accepts']:
                        msg = decorator_info(f.__name__, kw['accepts'], arg_types, 0)
                        print('TypeWarning: ', msg)
                        raise TypeError(msg)
                result = f(*args)
                if 'returns' in kw:
                    res_type = type(result)
                    if res_type != kw['returns']:
                        msg = decorator_info(f.__name__, (kw['returns'],), (res_type,), 1)
                        print('TypeWarning: ', msg)
                        raise TypeError(msg)
                return result
            new_f.__name__ = f.__name__
            return new_f
        return decorator
    except KeyError as ke:
        raise KeyError(ke.message + 'is not a valid keyword argument')
    except TypeError as te:
        raise TypeError(te.message)

def read_tgf(filename):
    """Reads a file in Trivial Graph Format."""
    g = Graph()
    with open(filename) as file:
        states = {}
        for line in file:
            line = line.strip()
            if line == '':
                continue
            elif line == '#':
                break
            i, q = line.split(None, 1)
            q, attrs = syntax.string_to_state(q)
            states[i] = q
            g.add_node(q, attrs)
        for line in file:
            line = line.strip()
            if line == '':
                continue
            i, j, t = line.split(None, 2)
            q, r = (states[i], states[j])
            t = syntax.string_to_transition(t)
            g.add_edge(q, r, {'label': t})
    return from_graph(g)

def run(m, w, trace=False, steps=1000, show_stack=3):
    """Runs an automaton, automatically selecting a search method."""
    is_pda = True
    stack = None
    if not m.oneway:
        is_pda = False
    for s in range(m.num_stores):
        if s == m.input:
            pass
        elif m.has_cell(s):
            pass
        elif m.has_stack(s):
            if stack is None:
                stack = s
            else:
                is_pda = False
        else:
            is_pda = False
    if is_pda and stack is not None:
        if trace:
            print('using modified Lang algorithm')
        return run_pda(m, w, stack=stack, trace=trace, show_stack=show_stack)
    else:
        if trace:
            print('using breadth-first search')
        return run_bfs(m, w, trace=trace, steps=steps)

def fmt_bytes(bytes, precision=2):
    """Reduce a large number of `bytes` down to a humanised SI
    equivalent and return the result as a string with trailing unit
    abbreviation."""
    UNITS = ['bytes', 'KB', 'MB', 'GB', 'TB', 'PB']
    if bytes == 0:
        return '0 bytes'
    log = math.floor(math.log(bytes, 1000))
    return '%.*f %s' % (precision, bytes / math.pow(1000, log), UNITS[int(log)])

def average(arr):
    """average of the values, must have more than 0 entries.

    :param arr: list of numbers
    :type arr: number[] a number array
    :return: average
    :rtype: float"""
    if len(arr) == 0:
        sys.stderr.write('ERROR: no content in array to take average\n')
        sys.exit()
    if len(arr) == 1:
        return arr[0]
    return float(sum(arr)) / float(len(arr))

def is_uuid4(instr):
    """A validator to confirm a string is indeed a UUID4

    :param instr: input string that may be uuid4
    :type instr: String
    :return: true if it is in UUID4 format
    :rtype: bool"""
    v = instr.strip().replace('-', '').lower()
    if len(v) != 32:
        return False
    if not re.match('^[0-9a-f]+$', v):
        return False
    if v[12] != '4':
        return False
    if not re.match('[89ab]', v[16]):
        return False
    return True

def filter_arc(w, h, aspect):
    """Aspect ratio convertor. you must specify output size and source aspect ratio (as float)"""
    taspect = float(w) / h
    if abs(taspect - aspect) < 0.01:
        return 'scale=%s:%s' % (w, h)
    if taspect > aspect:
        pt = 0
        ph = h
        pw = int(h * aspect)
        pl = int((w - pw) / 2.0)
    else:
        pl = 0
        pw = w
        ph = int(w * (1 / aspect))
        pt = int((h - ph) / 2.0)
    return 'scale=%s:%s[out];[out]pad=%s:%s:%s:%s:black' % (pw, ph, w, h, pl, pt)

def docker_context():
