def ast_to_headings(node):
    """Walks AST and returns a list of headings"""
    Heading = namedtuple('Heading', ['level', 'title'])
    level = None
    walker = node.walker()
    headings = []
    event = walker.nxt()
    while event is not None:
        entering = event['entering']
        node = event['node']
        if node.t == 'Heading':
            if entering:
                level = node.level
            else:
                level = None
        elif level:
            if node.t != 'Text':
                raise Exception('Unexpected node {}, only text may be within a heading.'.format(node.t))
            headings.append(Heading(level=level, title=node.literal))
        event = walker.nxt()
    return headings

def confirm(prompt, default=None, show_default=True, abort=False, input_function=None):
    """Prompts for confirmation from the user.
    """
    valid = {'yes': True, 'y': True, 'no': False, 'n': False}
    input_function = get_input_fn(input_function)
    if default not in ['yes', 'no', None]:
        default = None
    if show_default:
        prompt = '{} [{}/{}]: '.format(prompt, 'Y' if default == 'yes' else 'y', 'N' if default == 'no' else 'n')
    while True:
        choice = prompt_fn(input_function, prompt, default).lower()
        if choice in valid:
            if valid[choice] == False and abort:
                raise_abort()
            return valid[choice]
        else:
            echo('Please respond with "yes" or "no" (or "y" or "n").')

def prompt(text, default=None, show_default=True, invisible=False, confirm=False, skip=False, type=None, input_function=None):
    """Prompts for input from the user.
    """
    t = determine_type(type, default)
    input_function = get_input_fn(input_function, invisible)
    if default is not None and show_default:
        text = '{} [{}]: '.format(text, default)
    while True:
        val = prompt_fn(input_function, text, default, t, skip, repeat=True)
        if not confirm or (skip and val is None):
            return val
        if val == prompt_fn(input_function, 'Confirm: ', default, t, repeat=True):
            return val
        echo('Error: The two values you entered do not match', True)

def f2tc(f, base=25):
    """Converts frames to timecode"""
    try:
        f = int(f)
    except:
        return '--:--:--:--'
    hh = int(f / base / 3600)
    mm = int(f / base / 60 - hh * 60)
    ss = int(f / base - hh * 3600 - mm * 60)
    ff = int(f - hh * 3600 * base - mm * 60 * base - ss * base)
    return '{:02d}:{:02d}:{:02d}:{:02d}'.format(hh, mm, ss, ff)

def s2tc(s, base=25):
    """Converts seconds to timecode"""
    try:
        f = int(s * base)
    except:
        return '--:--:--:--'
    hh = int(f / base / 3600)
    hhd = int(hh % 24)
    mm = int(f / base / 60 - hh * 60)
    ss = int(f / base - hh * 3600 - mm * 60)
    ff = int(f - hh * 3600 * base - mm * 60 * base - ss * base)
    return '{:02d}:{:02d}:{:02d}:{:02d}'.format(hhd, mm, ss, ff)

def format_time(timestamp, time_format='%Y-%m-%d %H:%M:%S', never_placeholder='never', gmt=False):
    """strftime/localtime shortcut"""
    if not timestamp:
        return never_placeholder
    return time.strftime(time_format, time.gmtime(timestamp) if gmt else time.localtime(timestamp))

def out(*args):
    """Outputs its parameters to users stdout."""
