def unaccent(string, encoding='utf-8'):
    """not just unaccent, but full to-ascii transliteration"""
    string = to_unicode(string)
    if has_unidecode:
        return unidecode.unidecode(string)
    if PYTHON_VERSION < 3:
        if type(string) == str:
            string = unicode(string, encoding)
        nfkd_form = unicodedata.normalize('NFKD', string)
        return u''.join([c for c in nfkd_form if not unicodedata.combining(c)]).encode('ascii', 'ignore')
    else:
        return string

def get_error(exc):
    """Return the appropriate HTTP status code according to the Exception/Error."""
    if isinstance(exc, HTTPError):
        return (exc.response.status_code, text(exc.response.content))
    if isinstance(exc, Timeout):
        return (408, exc)
    if isinstance(exc, Http404):
        return (404, exc)
    if isinstance(exc, PermissionDenied):
        return (403, exc)
    if isinstance(exc, SuspiciousOperation):
        return (400, exc)
    return (500, exc)

