def get_start_stops(transcript_sequence, start_codons=None, stop_codons=None):
    """Return start and stop positions for all frames in the given
    transcript."""
    transcript_sequence = transcript_sequence.upper()
    if not start_codons:
        start_codons = ['ATG']
    if not stop_codons:
        stop_codons = ['TAA', 'TAG', 'TGA']
    seq_frames = {1: {'starts': [], 'stops': []}, 2: {'starts': [], 'stops': []}, 3: {'starts': [], 'stops': []}}
    for codons, positions in ((start_codons, 'starts'), (stop_codons, 'stops')):
        if len(codons) > 1:
            pat = re.compile('|'.join(codons))
        else:
            pat = re.compile(codons[0])
        for m in re.finditer(pat, transcript_sequence):
            start = m.start() + 1
            rem = start % 3
            if rem == 1:
                seq_frames[1][positions].append(start)
            elif rem == 2:
                seq_frames[2][positions].append(start)
            elif rem == 0:
                seq_frames[3][positions].append(start)
    return seq_frames

def get_rna_counts(rna_file, transcript_name):
    """Get coverage for a given RNA BAM file, return read counts."""
    if not os.path.exists(rna_file):
        msg = 'RNA-Seq BAM file "{}" does not exist'.format(rna_file)
        logging.error(msg)
        raise OSError(msg)
    rna_counts = {}
    cov_file = tempfile.NamedTemporaryFile(delete=False)
    try:
        subprocess.check_call(['bedtools', 'genomecov', '-ibam', rna_file, '-bg'], stdout=cov_file)
    except subprocess.CalledProcessError as e:
        raise ribocore.RNACountsError('Could not generate coverage for RNA BAM file. \n{}\n'.format(e))
    for line in open(cov_file.name):
        line = line.split()
        if line[0] == transcript_name:
            position, count = (int(line[1]) + 1, int(line[3]))
            rna_counts[position] = count
    cov_file.close()
    os.unlink(cov_file.name)
    return rna_counts

def set_axis_color(axis, color, alpha=None):
    """Sets the spine color of all sides of an axis (top, right, bottom, left)."""
    for side in ('top', 'right', 'bottom', 'left'):
        spine = axis.spines[side]
        spine.set_color(color)
        if alpha is not None:
            spine.set_alpha(alpha)

def get_color_palette(scheme):
    """Return colors for a given scheme. Default colors are returned for an item
    if undefined in scheme."""
    color_schemes = {'default': {'frames': ['tomato', 'limegreen', 'deepskyblue'], 'background': '#ffffff', 'color': '#616161', 'ticks': '#757575', 'start': '#ffffff', 'stop': '#909090', 'rna': '#eaeaea', 'axis': '#e0e0e0', 'grey': '#bdbdbd'}, 'colorbrewer': {'frames': ['#fc8d62', '#66c2a5', '#8da0cb']}, 'rgb': {'frames': ['red', 'green', 'blue']}, 'greyorfs': {}}
    colors = {}
    for k, v in color_schemes['default'].items():
        try:
            vals = color_schemes[scheme][k]
        except KeyError:
            vals = v
        colors[k] = vals
    return colors

def read_version():
    """Read version from the first line starting with digit
    """
    regex = re.compile('^(?P<number>\\d.*?) .*$')
    with open('../CHANGELOG.rst') as f:
        for line in f:
            match = regex.match(line)
            if match:
                return match.group('number')

def catch_no_credentials(message, **info):
    """Turn a NoCredentialsError into a BadAmazon"""
    try:
        yield
    except NoCredentialsError as error:
        if hasattr(error, 'response'):
            info['error_code'] = error.response['ResponseMetadata']['HTTPStatusCode']
            info['error_message'] = error.response['Error']['Message']
        else:
            info['error_message'] = error.fmt
        raise BadAmazon(message, **info)

def catch_boto_400(message, **info):
    """Turn a BotoServerError 400 into a BadAmazon"""
    try:
        yield
    except ClientError as error:
        if str(error.response['ResponseMetadata']['HTTPStatusCode']).startswith('4'):
            error_message = error.response['Error']['Message']
            raise BadAmazon(message, error_message=error_message, error_code=error.response['ResponseMetadata']['HTTPStatusCode'], **info)
        else:
            raise

