def _to_swagger(base=None, description=None, resource=None, options=None):
    """Common to swagger definition.

    :param base: The base dict.
    :param description: An optional description.
    :param resource: An optional resource.
    :param options: Any additional options"""
    definition = dict_filter(base or {}, options or {})
    if description:
        definition['description'] = description.format(name=getmeta(resource).name if resource else 'UNKNOWN')
    if resource:
        definition['schema'] = {'$ref': '#/definitions/{}'.format(getmeta(resource).resource_name)}
    return definition

def _toDict(datastorage_obj, recursive=True):
    """this is the recursive part of the toDict (otherwise it fails when converting to DataStorage"""
    if 'items' not in dir(datastorage_obj):
        return datastorage_obj
    d = dict()
    for k, v in datastorage_obj.items():
        try:
            d[k] = _toDict(v)
        except Exception as e:
            log.info('In toDict, could not convert key %s to dict, error was %s' % (k, e))
            d[k] = v
    return d

def toDict(datastorage_obj, recursive=True):
    """convert a DataStorage object to a dictionary (useful for saving); it should work for other objects too
    """
    if 'items' not in dir(datastorage_obj):
        datastorage_obj = DataStorage(datastorage_obj)
    return _toDict(datastorage_obj)

def save(fname, d, link_copy=True, raiseError=False):
    """link_copy is used by hdf5 saving only, it allows to creat link of identical arrays (saving space)"""
    fname = pathlib.Path(fname)
    d = toDict(d, recursive=True)
    d['filename'] = str(fname)
    extension = fname.suffix
    log.info('Saving storage file %s' % fname)
    try:
        if extension == '.npz':
            return dictToNpz(fname, d)
        elif extension == '.h5':
            return dictToH5(fname, d, link_copy=link_copy)
        elif extension == '.npy':
            return dictToNpy(fname, d)
        else:
            raise ValueError('Extension must be h5, npy or npz, it was %s' % extension)
    except Exception as e:
        log.exception('Could not save %s' % fname)
        if raiseError:
            raise e

def dfs(node, expand=expansion_all, callback=None, silent=True):
    """Perform a depth-first search on the node graph
    :param node: GraphNode
    :param expand: Returns the list of Nodes to explore from a Node
    :param callback: Callback to run in each node
    :param silent: Don't throw exception on circular dependency
    :return:"""
    nodes = deque()
    for n in expand(node):
        nodes.append(n)
    while nodes:
        n = nodes.pop()
        n.visits += 1
        if callback:
            callback(n)
        for k in expand(n):
            if k.visits < 1:
                nodes.append(k)
            elif not silent:
                raise CircularDependency('Circular Dependency')

