def parse_multiple(s, f, values=None):
    """Parse multiple comma-separated elements, each of which is parsed
    using function f."""
    if values is None:
        values = []
    values.append(f(s))
    if s.pos < len(s) and s.cur == ',':
        s.pos += 1
        return parse_multiple(s, f, values)
    else:
        return values

def string_to_state(s):
    """s is a string possibly preceded by > or @."""
    s = lexer(s)
    attrs = {}
    while True:
        if s.cur == '>':
            attrs['start'] = True
            s.pos += 1
        elif s.cur == '@':
            attrs['accept'] = True
            s.pos += 1
        else:
            break
    x = parse_symbol(s)
    parse_end(s)
    return (x, attrs)

def string_to_configs(s):
    """s is a string in one of the following formats:
    - x,y
    - (x,y)
    - {x,y}
    - {(w,x),(y,z)}
    In any case, returns a set of tuples of stores."""
    s = lexer(s)
    value = None
    if s.pos == len(s):
        value = set()
    elif s.cur == '{':
        value = parse_set(s)
    elif s.cur == '(':
        value = {parse_tuple(s)}
    else:
        value = {tuple(parse_multiple(s, parse_store))}
    parse_end(s)
    return value

def string_to_transition(s):
    """s is a string of the form a,b or a,b->c,d"""
    from .machines import Transition
    s = lexer(s)
    lhs = parse_multiple(s, parse_store)
    if s.pos < len(s) and s.cur == '->':
        s.pos += 1
        rhs = parse_multiple(s, parse_store)
    else:
        rhs = ()
    parse_end(s)
    return Transition(lhs, rhs)

def ensure_string(obj):
    """Return String and if Unicode convert to string.

    :param obj: ``str`` || ``unicode``
    :return: ``str``"""
    if sys.version_info < (3, 2, 0) and isinstance(obj, unicode):
        return str(obj.encode('utf8'))
    else:
        return obj

def resolve_content_type(type_resolvers, request):
    """Resolve content types from a request."""
    for resolver in type_resolvers:
        content_type = parse_content_type(resolver(request))
        if content_type:
            return content_type

def get_resource(request, resource, allow_multiple=False, full_clean=True, default_to_not_supplied=False):
    """Get a resource instance from ``request.body``.

    Note error code 98 is returned in multiple places, this is to prevent leakage of details of defined resources."""
    body = request.body
    if isinstance(body, bytes):
        try:
            body = body.decode('UTF8')
        except UnicodeDecodeError as ude:
            raise HttpError(HTTPStatus.BAD_REQUEST, 99, 'Unable to decode request body.', str(ude))
    try:
        instance = request.request_codec.loads(body, resource=resource, full_clean=full_clean, default_to_not_supplied=default_to_not_supplied)
    except ResourceException:
        raise HttpError(HTTPStatus.BAD_REQUEST, 98, 'Invalid resource type.')
    except CodecDecodeError as cde:
        raise HttpError(HTTPStatus.BAD_REQUEST, 96, 'Unable to decode body.', str(cde))
    if isinstance(instance, list):
        if any((not isinstance(i, resource) for i in instance)):
            raise HttpError(HTTPStatus.BAD_REQUEST, 98, 'Invalid resource type.')
        if not allow_multiple:
            raise HttpError(HTTPStatus.BAD_REQUEST, 97, 'Expected a single resource not a list.')
    elif not isinstance(instance, resource):
        raise HttpError(HTTPStatus.BAD_REQUEST, 98, 'Invalid resource type.')
    return instance

def create_response(request, body=None, status=None, headers=None):
    """Generate a HttpResponse.

    :param request: Request object
    :param body: Body of the response
    :param status: HTTP status code
    :param headers: Any headers."""
    if body is None:
        return HttpResponse(None, status or HTTPStatus.NO_CONTENT, headers)
    else:
        body = request.response_codec.dumps(body)
        response = HttpResponse(body, status or HTTPStatus.OK, headers)
        response.set_content_type(request.response_codec.CONTENT_TYPE)
        return response

def register_filter(filter_cls):
    """Adds the ``filter_cls`` to our registry."""
    if filter_cls.name is None:
        return
    elif filter_cls.name in FILTER_REGISTRY:
        raise RuntimeError('Filter class already registered: {}'.format(filter_cls.name))
    else:
        FILTER_REGISTRY[filter_cls.name] = filter_cls

def build_filter(filter_or_string, *args, **kwargs):
    """Overloaded filter construction. If ``filter_or_string`` is a string
    we look up it's corresponding class in the filter registry and return it.
    Otherwise, assume ``filter_or_string`` is an instance of a filter.

    :return: :class:`~es_fluent.filters.Filter`"""
    if isinstance(filter_or_string, basestring):
        if filter_or_string.startswith('~'):
            filter_name = filter_or_string[1:]
            return ~FILTER_REGISTRY[filter_name](*args, **kwargs)
        else:
            filter_name = filter_or_string
            return FILTER_REGISTRY[filter_name](*args, **kwargs)
    else:
        return filter_or_string

def exception_handler(exctype, value, traceback):
    """This exception handler catches KeyboardInterrupt to cancel the Runner and
    also stops the Runner in case of an error."""
    if exctype == KeyboardInterrupt:
        pypro.console.out('')
        pypro.console.err('Canceled')
    elif exctype == PyproException:
        pypro.console.err('[Error] ', value.message)
        exit()
    else:
        sys.__excepthook__(exctype, value, traceback)

def to_file(data, filename_or_file_object):
    """Write ``data`` to a file specified by either filename of the file or an opened :class:`file` buffer.

    :param data: Object to write to file
    :param filename_or_file_object: filename/or opened file buffer to write to
    :type filename_or_file_object: basestring|file"""
    if isinstance(filename_or_file_object, basestring):
        file_ = open(filename_or_file_object, 'w')
        we_opened = True
    else:
        file_ = filename_or_file_object
        we_opened = False
    try:
        file_.write(dump(data))
    finally:
        if we_opened:
            file_.close()

