def parse_config():
    """Parse the configuration and create required services.

    Note:
      Either takes the configuration from the environment (a variable
      named ``FLASH_CONFIG``) or a file at the module root (named
      ``config.json``). Either way, it will attempt to parse it as
      JSON, expecting the following format::

          {
            "name": <Project Name>,
            "services": [
              {
                "name": <Service Name>,
                <Service Settings>
              }
            ]
          }"""
    env = getenv('FLASH_CONFIG')
    if env:
        logger.info('loading configuration from environment')
        data = json.loads(env)
    else:
        data = _parse_file()
    data['project_name'] = data.get('project_name', 'unnamed')
    data['services'] = define_services(data.get('services', []))
    data['style'] = data.get('style', 'default')
    if data.get('project_end'):
        data['project_end'] = repr(data['project_end'])
    return data

def _parse_file():
    """Parse the config from a file.

    Note:
      Assumes any value that ``"$LOOKS_LIKE_THIS"`` in a service
      definition refers to an environment variable, and attempts to get
      it accordingly."""
    file_name = path.join(path.abspath(path.dirname(path.dirname(__file__))), 'config.json')
    logger.info('loading configuration from file: %r', file_name)
    try:
        data = _read_file(file_name)
    except FileNotFoundError:
        logger.error('no configuration available, set FLASH_CONFIG or provide config.json')
        exit()
    for service in data.get('services', []):
        for key, val in service.items():
            if isinstance(val, str) and re.match('^\\$[A-Z_]+$', val):
                env_val = getenv(val[1:])
                if env_val is None:
                    logger.warning('environment variable %r not found', val[1:])
                service[key] = env_val or val
    return data

def launch_modules_with_names(modules_with_names, module_args={}, kill_before_launch=True):
    """launch module.main functions in another process"""
    processes = []
    if kill_before_launch:
        for module_name, name in modules_with_names:
            kill_module(name)
    for module_name, name in modules_with_names:
        m = importlib.import_module(module_name)
        args = {}
        if module_name in module_args:
            args = module_args[module_name]
        p1 = Process(target=m.main, args=args)
        p1.daemon = True
        p1.start()
        processes.append(p1)
        with open(get_launched_module_pid_file(name), 'w') as f:
            f.write('{}'.format(p1.pid))
    return processes

def _getsetting(setting, default):
    """Get `setting` if set, fallback to `default` if not

    This method tries to return the value of the specified setting from Django's
    settings module, after prefixing the name with _DJANGO_SETTING_PREFIX. If
    this fails for any reason, the value supplied in `default` will be returned
    instead."""
    setting = _DJANGO_SETTING_PREFIX + setting
    try:
        return getattr(settings, setting)
    except:
        return default

def raw(func, **func_args):
    """Decorator for eager functions checking input array
    and stripping away the weld_type.

    Stripping the weld_type is required to keep the same code in Series.apply and because
    Numpy functions don't (all) have kwargs. Passing weld_type to NumPy functions is unexpected
    and raises ValueError.

    Parameters
    ----------
    func : function
        Function to execute eagerly over raw data.
    func_args : kwargs
        Arguments to pass to func, if any.

    Returns
    -------
    function"""
    if len(func_args) == 0:
        @wraps(func)
        def wrapper(array, **kwargs):
            if isinstance(array, WeldObject):
                raise TypeError('Can only perform operation on raw data')
            if 'weld_type' in kwargs:
                del kwargs['weld_type']
            return func(array, **kwargs)
        return wrapper
    else:
        @wraps(func)
        def wrapper(array, **kwargs):
            if isinstance(array, WeldObject):
                raise TypeError('Can only perform operation on raw data')
            return func(array, **func_args)
        return wrapper

def insert_import_path_to_sys_modules(import_path):
    """When importing a module, Python references the directories in sys.path.
    The default value of sys.path varies depending on the system, But:
    When you start Python with a script, the directory of the script is inserted into sys.path[0].

    So we have to replace sys.path to import object in specified scripts."""
    abspath = os.path.abspath(import_path)
    if os.path.isdir(abspath):
        sys.path.insert(0, abspath)
    else:
        sys.path.insert(0, os.path.dirname(abspath))

def shell(filepath, wsgiapp, interpreter, models):
    """Runs a python shell.

    Usage:

        $ wsgicli shell app.py app -i ipython"""
    model_base_classes = get_model_base_classes()
    imported_objects = {}
    if models and model_base_classes:
        insert_import_path_to_sys_modules(filepath)
        for module in find_modules_from_path(filepath):
            for name in dir(module):
                if name.startswith('_'):
                    continue
                obj = getattr(module, name)
                if isinstance(obj, model_base_classes):
                    key = name.split('.')[-1] if '.' in name else name
                    if key in imported_objects:
                        continue
                    imported_objects[key] = obj
    module = SourceFileLoader('module', filepath).load_module()
    imported_objects['app'] = getattr(module, wsgiapp)
    for key in imported_objects.keys():
        click.secho('import {}'.format(key), fg='green')
    run_python(interpreter, imported_objects)

def extract_files(params):
    """Extract filenames from the "photo" parameter so they can be uploaded,
    returning (updated_params, files).
    Uses the same technique as the Trovebox PHP commandline tool:
      * Filename can only be in the "photo" parameter
      * Filename must be prefixed with "@"
      * Filename must exist
    ...otherwise the parameter is not extracted"""
    files = {}
    updated_params = {}
    for name in params:
        if name == 'photo' and params[name].startswith('@'):
            filename = params[name][1:]
            if isinstance(filename, bytes):
                filename = filename.decode(sys.getfilesystemencoding())
            files[name] = open(os.path.expanduser(filename), 'rb')
        else:
            updated_params[name] = params[name]
    return (updated_params, files)

