def find_ctx(elt):
    """Find a Pointcut ctx which is a class/instance related to input
    function/method.

    :param elt: elt from where find a ctx.
    :return: elt ctx. None if no ctx available or if elt is a None method."""
    result = None
    if ismethod(elt):
        result = elt.__self__
        if result is None and PY2:
            result = elt.im_class
    elif isclass(elt):
        result = elt
    return result

def base_ctx(ctx):
    """Get base ctx.

    :param ctx: initial ctx.
    :return: base ctx."""
    result = None
    if isclass(ctx):
        result = getattr(ctx, '__base__', None)
        if result is None:
            mro = getmro(ctx)
            if len(mro) > 1:
                result = mro[1]
    else:
        result = ctx.__class__
    return result

def vars_(object=None):
    """Clean all of the property starts with "_" then
    return result of vars(object)."""
    filtered_vars = {}
    vars_dict = vars(object)
    for key, value in six.iteritems(vars_dict):
        if key.startswith('_'):
            continue
        filtered_vars[_normalize_arg_name(key)] = value
    return filtered_vars

