def pick_master_slide(master_slides_path: Path) -> Path:
    """Returns path to a master slide. If argument is a directory,
    returns a randomly chosen file in the directory and if argument
    is a file, returns the argument itself

    :return: path to chosen master slide"""
    if master_slides_path.is_file():
        return master_slides_path
    master_slides = [f.name for f in master_slides_path.iterdir() if f.suffix == '.pptx' if not f.name.startswith('archived')]
    if master_slides:
        return Path(master_slides_path, random.choice(master_slides))
    raise ValueError(f'Unable to find any valid pptx template file in {master_slides_path}')

def generate_form(model, only=None, meta=None):
    """Generate WTForm based on SQLAlchemy table
    :param model: SQLAlchemy sa.Table
    :param only: list or set of columns that should be used in final form
    :param meta: Meta class with settings for form
    :return: WTForm object"""
    fields = OrderedDict()
    if meta:
        fields['Meta'] = meta
    for name, column in model.__dict__['columns'].items():
        if only:
            if not name in only:
                continue
        if not isinstance(column, Column):
            continue
        fields[name] = TYPE_MAP[column.type.__class__](name, render_kw={'placeholder': name})
    form = type('Add{}Form'.format(model.name.capitalize()), (Form,), fields)
    return form

