def intcomma(value):
    """Borrowed from django.contrib.humanize

    Converts an integer to a string containing commas every three digits.
    For example, 3000 becomes '3,000' and 45000 becomes '45,000'."""
    orig = str(value)
    new = re.sub('^(-?\\d+)(\\d{3})', '\\g<1>,\\g<2>', orig)
    if orig == new:
        return new
    else:
        return intcomma(new)

def percent_change(value, decimal_places=1, multiply=True, failure_string='N/A'):
    """Converts a floating point value into a percentage change value.

    Number of decimal places set by the `precision` kwarg. Default is one.

    Non-floats are assumed to be zero division errors and are presented as
    'N/A' in the output.

    By default the number is multiplied by 100. You can prevent it from doing
    that by setting the `multiply` keyword argument to False."""
    try:
        f = float(value)
        if multiply:
            f = f * 100
    except ValueError:
        return failure_string
    s = _saferound(f, decimal_places)
    if f > 0:
        return '+' + s + '%'
    else:
        return s + '%'

def ratio(value, decimal_places=0, failure_string='N/A'):
    """Converts a floating point value a X:1 ratio.

    Number of decimal places set by the `precision` kwarg. Default is one."""
    try:
        f = float(value)
    except ValueError:
        return failure_string
    return _saferound(f, decimal_places) + ':1'

def title(value, failure_string='N/A'):
    """Converts a string into titlecase.

    Lifted from Django."""
    try:
        value = value.lower()
        t = re.sub("([a-z])'([A-Z])", lambda m: m.group(0).lower(), value.title())
        result = re.sub('\\d([A-Z])', lambda m: m.group(0).lower(), t)
        if not result:
            return failure_string
        return result
    except:
        return failure_string

def admin_tagify(short_description=None, allow_tags=True):
    """Decorator that add short_description and allow_tags to ModelAdmin list_display function.

    Example:

        class AlbumAdmin(admin.ModelAdmin):
            list_display = ['title', 'year', 'artist', 'total_tacks', 'view_track']

            @admin_tagify("View track")
            def view_songs(self, obj):
                return "<a href="%s?album=%d">%d tracks</a>" % (reverse("admin:music_track_changelist"), obj.id, obj.tracks.count())"""
    def tagify(func):
        func.allow_tags = bool(allow_tags)
        if short_description:
            func.short_description = short_description
        return func
    return tagify

def foreign_field_func(field_name, short_description=None, admin_order_field=None):
    """Allow to use ForeignKey field attributes at list_display in a simple way.

    Example:

        from misc.admin import foreign_field_func as ff

        class SongAdmin(admin.ModelAdmin):
            list_display = ['name', 'time', 'artist', 'album', ff('track__num', "Track number"), ff('album__total_tracks')]"""
    def accessor(obj):
        val = obj
        for part in field_name.split('__'):
            val = getattr(val, part)
        return val
    if short_description:
        accessor.short_description = short_description
    else:
        accessor.__name__ = field_name
    if admin_order_field:
        accessor.admin_order_field = admin_order_field
    else:
        accessor.admin_order_field = (field_name,)
    return accessor

def handle_response(response):
    """Handle a response from the newton API"""
    response = json.loads(response.read())
    if 'error' in response:
        raise ValueError(response['error'])
    else:
        try:
            return json.loads(response['result'])
        except (TypeError, json.decoder.JSONDecodeError):
            if response['result'] == 'NaN':
                return float('nan')
            else:
                return response['result']

