def _take(d, key, default=None):
    """If the key is present in dictionary, remove it and return it's
    value. If it is not present, return None."""
    if key in d:
        cmd = d[key]
        del d[key]
        return cmd
    else:
        return default

def _get_cmds_id(*cmds):
    """Returns an identifier for a group of partially tagged commands.
    If there are no tagged commands, returns None."""
    tags = [cmd[2] if len(cmd) == 3 else None for cmd in cmds]
    if [tag for tag in tags if tag != None]:
        return tuple(tags)
    else:
        return None

def CopyRecord(record, **field_overrides):
    """Copies a record and its fields, recurses for any field that is a Record.

    For records that have nested mutable fields, use copy.deepcopy.

    Args:
      record: A Record instance to be copied.
      **field_overrides: Fields and their values to override in the new copy.

    Returns: A copy of the given record with any fields overridden."""
    fields = field_overrides
    for field in record.__slots__:
        if field in field_overrides:
            continue
        value = getattr(record, field)
        if isinstance(value, RecordClass):
            new_value = CopyRecord(value)
        else:
            new_value = copy.copy(value)
        fields[field] = new_value
    return type(record)(**fields)

def _remove_advices(target, advices, ctx):
    """Remove advices from input target.

    :param advices: advices to remove. If None, remove all advices."""
    if ctx is not None:
        _, intercepted_ctx = get_intercepted(target)
        if intercepted_ctx is None or intercepted_ctx is not ctx:
            return
    interception_fn = _get_function(target)
    target_advices = getattr(interception_fn, _ADVICES, None)
    if target_advices is not None:
        if advices is None:
            target_advices = []
        else:
            target_advices = [advice for advice in target_advices if advice not in advices]
        if target_advices:
            setattr(interception_fn, _ADVICES, target_advices)
        else:
            delattr(interception_fn, _ADVICES)
            _unapply_interception(target, ctx=ctx)

def _unweave(target, advices, pointcut, ctx, depth, depth_predicate):
    """Unweave deeply advices in target."""
    if pointcut is None or pointcut(target):
        if is_intercepted(target):
            _remove_advices(target=target, advices=advices, ctx=ctx)
    if depth > 0:
        _base_ctx = None
        if ctx is not None:
            _base_ctx = base_ctx(ctx)
        for _, member in getmembers(target, depth_predicate):
            _unweave(target=member, advices=advices, pointcut=pointcut, depth=depth - 1, depth_predicate=depth_predicate, ctx=_base_ctx)

def find_for_x_in_y_keys(node):
    """Finds looping against dictionary keys"""
    return isinstance(node, ast.For) and h.call_name_is(node.iter, 'keys')

def find_if_x_retbool_else_retbool(node):
    """Finds simplifiable if condition"""
    return isinstance(node, ast.If) and isinstance(node.body[0], ast.Return) and h.is_boolean(node.body[0].value) and h.has_else(node) and isinstance(node.orelse[0], ast.Return) and h.is_boolean(node.orelse[0].value)

def find_path_join_using_plus(node):
    """Finds joining path with plus"""
    return isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add) and isinstance(node.left, ast.BinOp) and isinstance(node.left.op, ast.Add) and isinstance(node.left.right, ast.Str) and (node.left.right.s in ['/', '\\'])

def find_silent_exception(node):
    """Finds silent generic exceptions"""
    return isinstance(node, ast.ExceptHandler) and node.type is None and (len(node.body) == 1) and isinstance(node.body[0], ast.Pass)

def find_import_star(node):
    """Finds import stars"""
    return isinstance(node, ast.ImportFrom) and '*' in h.importfrom_names(node.names)

def find_equals_true_or_false(node):
    """Finds equals true or false"""
    return isinstance(node, ast.Compare) and len(node.ops) == 1 and isinstance(node.ops[0], ast.Eq) and any((h.is_boolean(n) for n in node.comparators))

def find_poor_default_arg(node):
    """Finds poor default args"""
    poor_defaults = [ast.Call, ast.Dict, ast.DictComp, ast.GeneratorExp, ast.List, ast.ListComp, ast.Set, ast.SetComp]
    return isinstance(node, ast.FunctionDef) and any((n for n in node.args.defaults if type(n) in poor_defaults))

def find_if_expression_as_statement(node):
    """Finds an "if" expression as a statement"""
    return isinstance(node, ast.Expr) and isinstance(node.value, ast.IfExp)

def find_comprehension_as_statement(node):
    """Finds a comprehension as a statement"""
    return isinstance(node, ast.Expr) and isinstance(node.value, (ast.ListComp, ast.DictComp, ast.SetComp))

def find_generator_as_statement(node):
    """Finds a generator as a statement"""
    return isinstance(node, ast.Expr) and isinstance(node.value, ast.GeneratorExp)

def series2df(Series, layer=2, split_sign='_'):
    """expect pass a series that each row is string formated Json data with the same structure"""
    try:
        Series.columns
