def bootstrap_alert(visitor, items):
    """Format:

        [[alert(class=error)]]:
            message"""
    txt = []
    for x in items:
        cls = x['kwargs'].get('class', '')
        if cls:
            cls = 'alert-%s' % cls
        txt.append('<div class="alert %s">' % cls)
        if 'close' in x['kwargs']:
            txt.append('<button class="close" data-dismiss="alert">&times;</button>')
        text = visitor.parse_text(x['body'], 'article')
        txt.append(text)
        txt.append('</div>')
    return '\n'.join(txt)

def new_bootstrap_alert(visitor, block):
    """Format:

        {% alert class=error %}
        message
        {% endalert %}"""
    if 'new' in block:
        txt = []
        cls = block['kwargs'].get('class', '')
        if cls:
            cls = 'alert-%s' % cls
        txt.append('<div class="alert %s">' % cls)
        if 'close' in block['kwargs']:
            txt.append('<button class="close" data-dismiss="alert">&times;</button>')
        text = visitor.parse_text(block['body'], 'article')
        txt.append(text)
        txt.append('</div>')
        return '\n'.join(txt)
    else:
        return bootstrap_alert(visitor, block)

def idaunpack(buf):
    """Special data packing format, used in struct definitions, and .id2 files

    sdk functions: pack_dd etc."""
    buf = bytearray(buf)
    def nextval(o):
        val = buf[o]
        o += 1
        if val == 255:
            val, = struct.unpack_from('>L', buf, o)
            o += 4
            return (val, o)
        if val < 128:
            return (val, o)
        val <<= 8
        val |= buf[o]
        o += 1
        if val < 49152:
            return (val & 16383, o)
        val <<= 8
        val |= buf[o]
        o += 1
        val <<= 8
        val |= buf[o]
        o += 1
        return (val & 536870911, o)
    values = []
    o = 0
    while o < len(buf):
        val, o = nextval(o)
        values.append(val)
    return values

def replace_ext(filename, ext):
