def find_datafile(name, search_path='.', codecs=get_codecs()):
    """find all matching data files in search_path
    search_path: path of directories to load from
    codecs: allow to override from list of installed
    returns array of tuples (codec_object, filename)"""
    rv = []
    if isinstance(search_path, basestring):
        search_path = (search_path,)
    ext = os.path.splitext(name)[1][1:]
    cls = get_codec(ext)
    if cls:
        for each in search_path:
            fq_filename = os.path.join(each, name)
            if os.path.exists(fq_filename):
                rv.append((cls, fq_filename))
    for exts, obj in list(codecs.items()):
        for ext in exts:
            filename = '%s.%s' % (name, ext)
            for each in search_path:
                fq_filename = os.path.join(each, filename)
                if os.path.exists(fq_filename):
                    rv.append((obj, fq_filename))
    return rv

def load_datafile(name, search_path='.', codecs=get_codecs(), **kwargs):
    """find datafile and load them from codec
    TODO only does the first one
    kwargs:
    default = if passed will return that on failure instead of throwing"""
    mod = find_datafile(name, search_path, codecs)
    if not mod:
        if 'default' in kwargs:
            return kwargs['default']
        raise IOError('file %s not found in search path %s' % (name, str(search_path)))
    codec, datafile = mod[0]
    return codec().load(open(datafile))

def legion_create_handler(obj):
    """Signal handlers can't be standard class methods because the signal
    callback does not include the object reference (self).  To work
    around this we use a closure the carry the object reference."""
    def _handler(sig, frame):
        obj._sig_handler(sig, frame)
    if '_sig_handler' not in dir(obj):
        raise Excecption('Object instance has no _sig_handler method')
    return _handler

def _fmt_context(arg_list, context):
    """Iterate on performing a format operation until the formatting makes no
    further changes.  This allows for the substitution of context values that
    themselves have context values.  To prevent infinite loops due to direct
    or indirect self-reference, the total number of attempts is limited.

    On any error, the string formatted so far is returned.

    For convenience, if passed a list, each element will be formatted and
    the resulting list will be returned"""
    if arg_list is None:
        return arg_list
    just_one = False
    if not isinstance(arg_list, list):
        arg_list = [arg_list]
        just_one = True
    ans = []
    for arg in arg_list:
        if arg is None:
            continue
        for attempt in range(0, 10):
            res = None
            try:
                m = _fmt_context_isvar.match(arg)
                if m and m.group(1) in context and (context[m.group(1)] is None):
                    break
                else:
                    res = arg.format(**context)
                    if res == arg:
                        break
                arg = res
            except:
                if res is None:
                    res = arg
                break
        ans.append(res)
    return ans[0] if just_one else ans

def stringify(data):
