def create_and_push_expression(token, expressions):
    """Creates an expression from the given token and adds it
    to the stack of the given expression.

    In the case of "and" and "or" expressions the last expression
    is poped from the expression stack to link it to the new
    created one."""
    if token == 'and':
        right_expr = expressions.pop()
        expressions.append(And(expressions.pop(), right_expr))
    elif token == 'or':
        right_expr = expressions.pop()
        expressions.append(Or(expressions.pop(), right_expr))
    elif token == 'not':
        expressions.append(Not(expressions.pop()))
    else:
        expressions.append(Literal(token))

def rate_to_mcs(rate, bw=20, long_gi=True):
    """Convert bit rate to MCS index.

    Args:
        rate (float): bit rate in Mbps
        bw (int): bandwidth, 20, 40, 80, ...
        long_gi (bool): True if long GI is used.

    Returns:
        mcs (int): MCS index

    >>> rate_to_mcs(120, bw=40, long_gi=False)
    5"""
    if bw not in [20, 40, 80, 160]:
        raise Exception('Unknown bandwidth: %d MHz' % bw)
    idx = int((math.log(bw / 10, 2) - 1) * 2)
    if not long_gi:
        idx += 1
    for mcs, rates in MCS_TABLE.items():
        if abs(rates[idx] - rate) < 0.001:
            return mcs
    for idx, r in enumerate(DOT11A_RATES):
        if abs(r - rate) < 0.001:
            return idx
    raise Exception('MCS not found: rate=%f, bw=%d, long_gi=%s' % (rate, bw, long_gi))

