    backup_base = '/var/local/woven-backup'
    backup_path = ''.join([backup_base, path])
    if exists(backup_path):
        if delete_backup:
            sudo('mv -f %s %s' % (backup_path, path))
        else:
            sudo('cp -f %s %s' % (backup_path, path))

def _get_local_files(local_dir, pattern=''):
    """Returns a dictionary with directories as keys, and filenames as values
    for filenames matching the glob ``pattern`` under the ``local_dir``
    ``pattern can contain the Boolean OR | to evaluated multiple patterns into
    a combined set."""
    local_files = {}
    if pattern:
        cwd = os.getcwd()
        os.chdir(local_dir)
        patterns = pattern.split('|')
        local_list = set([])
        for p in patterns:
            local_list = local_list | set(glob(p))
        for path in local_list:
            dir, file = os.path.split(path)
            if os.path.isfile(path):
                local_files[dir] = local_files.get(dir, []) + [file]
            elif os.path.isdir(path):
                local_files[file] = local_files.get(dir, [])
        os.chdir(cwd)
    return local_files

def _stage_local_files(local_dir, local_files={}):
    """Either ``local_files`` and/or ``context`` should be supplied.

    Will stage a ``local_files`` dictionary of path:filename pairs where path
    is relative to ``local_dir`` into a local tmp staging directory.

    Returns a path to the temporary local staging directory"""
    staging_dir = os.path.join(tempfile.mkdtemp(), os.path.basename(local_dir))
    os.mkdir(staging_dir)
    for root, dirs, files in os.walk(local_dir):
        relative_tree = root.replace(local_dir, '')
        if relative_tree:
            relative_tree = relative_tree[1:]
        if local_files:
            files = local_files.get(relative_tree, [])
        for file in files:
            if relative_tree:
                filepath = os.path.join(relative_tree, file)
                if not os.path.exists(os.path.join(staging_dir, relative_tree)):
                    os.mkdir(os.path.join(staging_dir, relative_tree))
            else:
                filepath = file
            shutil.copy2(os.path.join(root, file), os.path.join(staging_dir, filepath))
    return staging_dir

def make_close_message(code=1000, message=b''):
    """Close the websocket, sending the specified code and message."""
    return _make_frame(struct.pack('!H%ds' % len(message), code, message), opcode=OPCODE_CLOSE)

def make_message(message, binary=False):
    """Make text message."""
    if isinstance(message, str):
        message = message.encode('utf-8')
    if binary:
        return _make_frame(message, OPCODE_BINARY)
    else:
        return _make_frame(message, OPCODE_TEXT)

def assert_200(response, max_len=500):
    """Check that a HTTP response returned 200."""
    if response.status_code == 200:
        return
    raise ValueError('Response was {}, not 200:\n{}\n{}'.format(response.status_code, json.dumps(dict(response.headers), indent=2), response.content[:max_len]))

def ensure_future(fut, *, loop=None):
    """Wraps asyncio.async()/asyncio.ensure_future() depending on the python version
    :param fut: The awaitable, future, or coroutine to wrap
    :param loop: The loop to run in
    :return: The wrapped future"""
    if sys.version_info < (3, 4, 4):
        func = getattr(asyncio, 'async')
    else:
        func = asyncio.ensure_future
    return func(fut, loop=loop)

def _proximity_to_association(proximity):
    """SLH algorithm for increasing orthogonality of a matrix."""
    if proximity.shape[0] == 0 or proximity.shape[1] == 0:
        return proximity
    U, sing_vals, Vh = np.linalg.svd(proximity)
    nsv = np.count_nonzero(sing_vals)
    U, Vh = (U[:, :nsv], Vh[:nsv, :])
    return U.dot(Vh)

def parse_arguments():
    """Parse commandline arguments."""
    parser = argparse.ArgumentParser()
    parser.add_argument('-n', '--number', action='store', default=1000000, type=int, help='number of items')
    parser.add_argument('-p', '--pause', action='store_true', help='pause after execution')
    return (parser.parse_args(), parser)

def timeout(duration):
    """A decorator to force a time limit on the execution of an external function.

    :param int duration: the timeout duration

    :raises: TypeError, if duration is anything other than integer

    :raises: ValueError, if duration is a negative integer

    :raises TimeoutError, if the external function execution crosses 'duration' time"""
    if not isinstance(duration, int):
        raise TypeError('timeout duration should be a positive integer')
    if duration <= 0:
        raise ValueError('timeoutDuration should be a positive integer')
    def decorator(func):
        def wrapped_func(*args, **kwargs):
            try:
                def alarm_handler(signum, stack):
                    raise TimeoutError()
                signal.signal(signal.SIGALRM, alarm_handler)
                signal.alarm(duration)
                reply = func(*args, **kwargs)
            except TimeoutError as e:
                raise e
            return reply
        return wrapped_func
    return decorator

def sleep():
    """Sleeps for a dynamic duration of time as determined by set_rate() and true().

    :raises: BeatError: if this function is called before calling set_rate() or             before calling true()"""
    if loop_duration == 0:
        raise BeatError('call beat.set_rate() before calling sleep')
    if loop_start_time == None:
        raise BeatError('call beat.true() before calling sleep')
    td = datetime.datetime.now() - loop_start_time
    duration_to_sleep = loop_duration - td.total_seconds()
    if duration_to_sleep < 0:
        raise BeatError('skipping sleep. Too much work!')
    time.sleep(duration_to_sleep)

def _root_domain():
    """Deduce the root domain name - usually a 'naked' domain.

    This only needs to be done prior to the first deployment"""
    if not hasattr(env, 'root_domain'):
        cwd = os.getcwd().split(os.sep)
        domain = ''
        username, host, port = normalize(env.hosts[0])
        if host[-1] in string.ascii_letters:
            domain_parts = env.host.split('.')
            length = len(domain_parts)
            if length == 2:
                domain = host
            elif length == 3 and len(domain_parts[-1]) == 2:
                domain = host
            elif length >= 3:
                domain = '.'.join(domain[1:])
        else:
            for d in cwd:
                if '.' in d:
                    domain = d
        if not domain and env.INTERACTIVE:
            domain = prompt('Enter the root domain for this project ', default='example.com')
        else:
            domain = 'example.com'
        env.root_domain = domain
    return env.root_domain

def post_install_package():
    """Run any functions post install a matching package.
    Hook functions are in the form post_install_[package name] and are
    defined in a deploy.py file

    Will be executed post install_packages and upload_etc"""
    module_name = '.'.join([env.project_package_name, 'deploy'])
    funcs_run = []
    try:
        imported = import_module(module_name)
        funcs = vars(imported)
        for f in env.installed_packages[env.host]:
            func = funcs.get(''.join(['post_install_', f.replace('.', '_').replace('-', '_')]))
            if func:
                func()
                funcs_run.append(func)
    except ImportError:
        pass
    for app in env.INSTALLED_APPS:
        if app == 'woven':
            continue
        module_name = '.'.join([app, 'deploy'])
        try:
            imported = import_module(module_name)
            funcs = vars(imported)
            for f in env.installed_packages[env.host]:
                func = funcs.get(''.join(['post_install_', f.replace('.', '_').replace('-', '_')]))
                if func and func not in funcs_run:
                    func()
                    funcs_run.append(func)
        except ImportError:
            pass
    import woven.deploy
    funcs = vars(woven.deploy)
    for f in env.installed_packages[env.host]:
        func = funcs.get(''.join(['post_install_', f.replace('.', '_').replace('-', '_')]))
        if func and func not in funcs_run:
            func()

def post_exec_hook(hook):
    """Runs a hook function defined in a deploy.py file"""
    module_name = '.'.join([env.project_package_name, 'deploy'])
    funcs_run = []
    try:
        imported = import_module(module_name)
        func = vars(imported).get(hook)
        if func:
            func()
            funcs_run.append(func)
    except ImportError:
        return
    for app in env.INSTALLED_APPS:
        if app == 'woven':
            continue
        module_name = '.'.join([app, 'deploy'])
        try:
            imported = import_module(module_name)
            func = vars(imported).get(hook)
            if func and func not in funcs_run:
                func()
                funcs_run.append(func)
        except ImportError:
            pass
    import woven.deploy
    func = vars(woven.deploy).get(hook)
    if func and func not in funcs_run:
        func()

