def version_state(name, prefix=False, no_content=False):
    """If the server state exists return parsed json as a python object or True
    prefix=True returns True if any files exist with ls [prefix]*"""
    if env.project_fullname:
        full_name = '-'.join([env.project_fullname, name])
    else:
        full_name = name
    current_state = False
    state = State(full_name)
    state_path = '/var/local/woven/%s' % full_name
    if not prefix and (not no_content) and exists(state_path):
        content = int(sudo('ls -s %s' % state_path).split()[0])
        if content:
            fd, file_path = tempfile.mkstemp()
            os.close(fd)
            get(state_path, file_path)
            with open(file_path, 'r') as f:
                content = f.read()
                object = json.loads(content)
                current_state = object
        else:
            current_state = True
    elif not prefix and no_content and exists(state_path):
        current_state = True
    elif prefix:
        with fab_settings(warn_only=True):
            current_state = sudo('ls /var/local/woven/*%s' % name)
        if not current_state.failed:
            current_state = True
    return current_state

def normpath(path):
    """Normalize given path in various different forms.

    >>> normpath("/tmp/../etc/hosts")
    '/etc/hosts'
    >>> normpath("~root/t")
    '/root/t'"""
    funcs = [os.path.normpath, os.path.abspath]
    if '~' in path:
        funcs = [os.path.expanduser] + funcs
    return chaincalls(funcs, path)

def load_context(ctx_path, ctx_type, scm=None):
    """:param ctx_path: context file path or '-' (read from stdin)
    :param ctx_type: context file type
    :param scm: JSON schema file in any formats anyconfig supports, to
        validate given context files"""
    if ctx_path == '-':
        return loads(sys.stdin.read(), ac_parser=ctx_type, ac_schema=scm)
    return load(ctx_path, ac_parser=ctx_type, ac_schema=scm)

def parse_and_load_contexts(contexts, schema=None, werr=False):
    """:param contexts: list of context file specs
    :param schema: JSON schema file in any formats anyconfig supports, to
        validate given context files
    :param werr: Exit immediately if True and any errors occurrs
        while loading context files"""
    ctx = dict()
    diff = None
    if contexts:
        for ctx_path, ctx_type in concat((parse_filespec(c) for c in contexts)):
            try:
                diff = load_context(ctx_path, ctx_type, scm=schema)
                if diff is not None:
                    merge(ctx, diff)
            except (IOError, OSError, AttributeError):
                if werr:
                    raise
    return ctx

def write_to_output(content, output=None, encoding=anytemplate.compat.ENCODING):
    """:param content: Content string to write to
    :param output: Output destination
    :param encoding: Character set encoding of outputs"""
    if anytemplate.compat.IS_PYTHON_3 and isinstance(content, bytes):
        content = str(content, encoding)
    if output and (not output == '-'):
        _write_to_filepath(content, output)
    elif anytemplate.compat.IS_PYTHON_3:
        print(content)
    else:
        print(content.encode(encoding.lower()), file=get_output_stream())

def find_template_from_path(filepath, paths=None):
    """Return resolved path of given template file

    :param filepath: (Base) filepath of template file
    :param paths: A list of template search paths"""
    if paths is None or not paths:
        paths = [os.path.dirname(filepath), os.curdir]
    for path in paths:
        candidate = os.path.join(path, filepath)
        if os.path.exists(candidate):
            return candidate
    LOGGER.warning('Could not find template=%s in paths=%s', filepath, paths)
    return None

def find_engine(filepath=None, name=None):
    """:param filepath: Template file path
    :param name: Specify the name of template engine to use explicitly or
        None; it will be selected automatically anyhow.

    :return: Template engine class found"""
    if name is None:
        engines = anytemplate.engine.find_by_filename(filepath)
        if not engines:
            raise TemplateEngineNotFound('filename=%s' % str(filepath))
        return engines[0]
    else:
        engine = anytemplate.engine.find_by_name(name)
        if engine is None:
            raise TemplateEngineNotFound('(template) name=%s' % name)
        return engine

def _fetch_url(url):
    """Returns the content of the provided URL.
    """
    try:
        resp = urllib2.urlopen(_Request(url))
    except urllib2.URLError:
        if 'wikileaks.org' in url:
            resp = urllib2.urlopen(_Request(url.replace('wikileaks.org', 'wikileaks.ch')))
        else:
            raise
    if resp.info().get('Content-Encoding') == 'gzip':
        return gzip.GzipFile(fileobj=StringIO(resp.read())).read().decode('utf-8')
    return resp.read().decode('utf-8')

def cable_page_by_id(reference_id):
    """Experimental: Returns the HTML page of the cable identified by `reference_id`.

    >>> cable_page_by_id('09BERLIN1167') is not None
    True
    >>> cable_page_by_id('22BERLIN1167') is None
    True
    >>> cable_page_by_id('09MOSCOW3010') is not None
    True
    >>> cable_page_by_id('10MADRID87') is not None
    True
    >>> cable_page_by_id('10MUSCAT103') is not None
    True"""
    global _CABLEID2MONTH
    def wikileaks_id(reference_id):
        if reference_id in consts.INVALID_CABLE_IDS.values():
            for k, v in consts.INVALID_CABLE_IDS.iteritems():
                if v == reference_id:
                    return k
        return reference_id
    def wikileaks_url(wl_id):
        m = _CABLEID2MONTH.get(wl_id)
        if m is None:
            return None
        y = wl_id[:2]
        y = u'19' + y if int(y) > 10 else u'20' + y
        return u'https://wikileaks.org/cable/%s/%s/%s' % (y, m.zfill(2), wl_id)
    if _CABLEID2MONTH is None:
        with gzip.open(os.path.join(os.path.dirname(__file__), 'cable2month.csv.gz'), 'r') as f:
            reader = csv.reader(f)
            _CABLEID2MONTH = dict(reader)
    wl_id = wikileaks_id(reference_id)
    wl_url = wikileaks_url(wl_id)
    if wl_url is None:
        html = _fetch_url(_CGSN_BASE + wl_id)
        m = _CGSN_WL_SOURCE_SEARCH(html)
        wl_url = m.group(1) if m else None
    if wl_url is None:
        return None
    return _fetch_url(wl_url)

def reference_id_parts(reference_id):
    """Returns a tuple from the provided `reference_id`::

        (YEAR, ORIGIN, S/N)

    `reference_id`
        Cable reference identifier or canonical identifier."""
    m = consts.REFERENCE_ID_PATTERN.match(reference_id)
    if m:
        return m.groups()
    raise ValueError('Illegal reference identifier: "%s"' % reference_id)

def tag_kind(tag, default=consts.TAG_KIND_UNKNOWN):
    """Returns the TAG kind.

    `tag`
        A string.
    `default`
        A value to return if the TAG kind is unknown
        (set to ``constants.TAG_KIND_UNKNOWN`` by default)"""
    if len(tag) == 2:
        return consts.TAG_KIND_GEO
    if u',' in tag:
        return consts.TAG_KIND_PERSON
    if tag[0] in u'Kk' and len(tag) == 4:
        return consts.TAG_KIND_PROGRAM
    t = tag.upper()
    if t in _TAGS_SUBJECT:
        return consts.TAG_KIND_SUBJECT
    if t in _TAGS_ORG:
        return consts.TAG_KIND_ORG
    return default

def titlefy(subject):
    """Titlecases the provided subject but respects common abbreviations.

    This function returns ``None`` if the provided `subject` is ``None``. It
    returns an empty string if the provided subject is empty.

    `subject
        A cable's subject."""
    def clean_word(word):
        return _APOS_PATTERN.sub(lambda m: u'%s%s%s' % (m.group(1), m.group(2) if not m.group(2) == ',' else u"'", m.group(3).lower()), word)
    def titlefy_word(word):
        if _is_number(word):
            return word.lower()
        if _TITLEFY_BIG_PATTERN.match(word):
            return clean_word(word.upper())
        return clean_word(_SPECIAL_WORDS.get(word, word.title()))
    if not subject:
        return None if subject is None else u''
    res = []
    append = res.append
    wl = subject.strip().split()
    append(titlefy_word(wl[0]))
    for word in wl[1:]:
        if _TITLEFY_SMALL_PATTERN.match(word):
            if res[-1][-1] not in ':-':
                if word == u'A' and res[-1] == u'and' and (res[-2] == 'Q'):
                    append(word.upper())
                else:
                    append(word.lower())
            else:
                append(titlefy_word(word))
        else:
            append(titlefy_word(word))
    return u' '.join(res)

def _unicode(p):
    """Used when force_unicode is True (default), the tags and values in the dict
    will be coerced as 'str' (or 'unicode' with Python2).   In Python3 they can
    otherwise end up as a mixtures of 'str' and 'bytes'."""
    q = {}
    for tag in p:
        vals = []
        for v in p[tag]:
            if type(v) is not str:
                v = v.decode('utf-8')
            vals.append(v)
        if type(tag) is not str:
            tag = tag.decode('utf-8')
        q[tag] = vals
    return q

def get_query(path, force_unicode=True):
    """Convert the query path of the URL to a dict.
    See _unicode regarding force_unicode."""
    u = urlparse(path)
    if not u.query:
        return {}
    p = parse_qs(u.query)
    if force_unicode:
        p = _unicode(p)
    return p

def merge_query(path, postmap, force_unicode=True):
    """Merges params parsed from the URI into the mapping from the POST body and
    returns a new dict with the values.

    This is a convenience function that gives use a dict a bit like PHP's $_REQUEST
    array.  The original 'postmap' is preserved so the caller can identify a
    param's source if necessary."""
    if postmap:
        p = postmap.copy()
    else:
        p = {}
    p.update(get_query(path, force_unicode=False))
    if force_unicode:
        p = _unicode(p)
    return p

def truthy(value):
    """Evaluates True if "value" looks like it is intended to be true.  This translates
    to an integer value greater than 0 or the first character starting with 'y'
    or 't' (case independent)."""
    if value is None or value == '':
        return False
    value = str(value)
    try:
        return int(value) != 0
    except:
        pass
    return truthy_true_yes.match(value) is not None

def get(**kwargs):
    """Safe sensor wrapper"""
    sensor = None
    tick = 0
    driver = DHTReader(**kwargs)
    while not sensor and tick < TIME_LIMIT:
        try:
            sensor = driver.receive_data()
        except DHTException:
            tick += 1
    return sensor

def parse_url(url, extra_schemes={}):
    """parse a munge url

    type:URL
    URL.type

    examples:
        file.yaml
        yaml:file.txt
        http://example.com/file.yaml
        yaml:http://example.com/file.txt

        mysql://user:password@localhost/database/table
        django:///home/user/project/settings_dir.settings/app_name/model"""
    if not url:
        raise ValueError('url cannot be empty')
    cls = None
    res = urlsplit(url)
    if res.scheme in extra_schemes:
        addr = extra_schemes[res.scheme]
        if 'type' in addr:
            cls = find_cls(res.scheme, extra_schemes)
        if 'url' in addr:
            url = addr['url']
            if cls:
                res = urlsplit(url)
                return MungeURL(cls, res)
            return parse_url(url)
    if res.scheme:
        cls = find_cls(res.scheme, extra_schemes)
    if not cls:
        rest, sep, ext = url.rpartition('.')
        cls = find_cls(ext, extra_schemes)
        if not cls:
            raise ValueError('unable to find codec for %s' % url)
    return MungeURL(cls, res)

def extract_irc_colours(msg):
    """Extract the IRC colours from the start of the string.

    Extracts the colours from the start, and returns the colour code in our
    format, and then the rest of the message."""
    fore, msg = _extract_irc_colour_code(msg)
    if not fore:
        return ('[]', msg)
    if not len(msg) or msg[0] != ',':
        return ('[{}]'.format(_ctos(fore)), msg)
    msg = msg[1:]
    back, msg = _extract_irc_colour_code(msg)
    if back:
        return ('[{},{}]'.format(_ctos(fore), _ctos(back)), msg)
    else:
        return ('[{}]'.format(_ctos(fore)), ',' + msg)

def extract_girc_colours(msg, fill_last):
    """Extract the girc-formatted colours from the start of the string.

    Extracts the colours from the start, and returns the colour code in IRC
    format, and then the rest of the message.

    If `fill_last`, last number must be zero-padded."""
    if not len(msg):
        return ('', '')
    if ']' not in msg or not msg.startswith('['):
        return ('', msg)
    original_msg = msg
    colours, msg = msg.split(']', 1)
    colours = colours.lstrip('[')
    if ',' in colours:
        fore, back = colours.split(',')
        if fore not in colour_name_to_code or back not in colour_name_to_code:
            return ('', original_msg)
        fore = colour_name_to_code[fore]
        back = colour_name_to_code[back]
        return ('{},{}'.format(fore, back.zfill(2) if fill_last else back), msg)
    else:
        if colours not in colour_name_to_code:
            return ('', original_msg)
        fore = colour_name_to_code[colours]
        return ('{}'.format(fore.zfill(2) if fill_last else fore), msg)

def escape(msg):
    """Takes a raw IRC message and returns a girc-escaped message."""
    msg = msg.replace(escape_character, 'girc-escaped-character')
    for escape_key, irc_char in format_dict.items():
        msg = msg.replace(irc_char, escape_character + escape_key)
    new_msg = ''
    while len(msg):
        if msg.startswith(escape_character + 'c'):
            new_msg += msg[:2]
            msg = msg[2:]
            if not len(msg):
                new_msg += '[]'
                continue
            colours, msg = extract_irc_colours(msg)
            new_msg += colours
        else:
            new_msg += msg[0]
            msg = msg[1:]
    new_msg = new_msg.replace('girc-escaped-character', escape_character + escape_character)
    return new_msg

def _get_from_format_dict(format_dict, key):
    """Return a value from our format dict."""
    if isinstance(format_dict[key], str):
        return format_dict[key]
    elif isinstance(format_dict[key], (list, tuple)):
        fn_list = list(format_dict[key])
        function = fn_list.pop(0)
        if len(fn_list):
            args = fn_list.pop(0)
        else:
            args = []
        if len(fn_list):
            kwargs = fn_list.pop(0)
        else:
            kwargs = {}
        return function(*args, **kwargs)

def unescape(msg, extra_format_dict={}):
    """Takes a girc-escaped message and returns a raw IRC message"""
    new_msg = ''
    extra_format_dict.update(format_dict)
    while len(msg):
        char = msg[0]
        msg = msg[1:]
        if char == escape_character:
            escape_key = msg[0]
            msg = msg[1:]
            if escape_key == escape_character:
                new_msg += escape_character
            elif escape_key == '{':
                buf = ''
                new_char = ''
                while True:
                    new_char = msg[0]
                    msg = msg[1:]
                    if new_char == '}':
                        break
                    else:
                        buf += new_char
                new_msg += _get_from_format_dict(extra_format_dict, buf)
            else:
                new_msg += _get_from_format_dict(extra_format_dict, escape_key)
            if escape_key == 'c':
                fill_last = len(msg) and msg[0] in digits
                colours, msg = extract_girc_colours(msg, fill_last)
                new_msg += colours
        else:
            new_msg += char
    return new_msg

