def recursive_update(a, b, **kwargs):
    """recursive dict a.update(b), merges dicts and lists
    Note: will clobber non dict keys if b has a dict with same key
    options:
        copy: deepcopy instead of reference (default False)
        merge_lists: merge lists as well (default True)"""
    copy = kwargs.get('copy', False)
    merge_lists = kwargs.get('merge_lists', True)
    for k, v in b.items():
        if isinstance(v, collections.Mapping):
            if isinstance(a.get(k, None), collections.Mapping):
                recursive_update(a[k], v, **kwargs)
                continue
        elif merge_lists and type(v) is list:
            if type(a.get(k, None)) is list:
                if copy:
                    a[k].extend(deepcopy(v))
                else:
                    a[k].extend(v)
                continue
        if copy:
            a[k] = deepcopy(v)
        else:
            a[k] = v
    return a

def download_file(url, file_name):
    """Helper for downloading a remote file to disk."""
    logger.info('Downloading URL: %s', url)
    file_size = 0
    if not os.path.isfile(file_name):
        response = requests.get(url, stream=True)
        with open(file_name, 'wb') as fp:
            if not response.ok:
                raise Exception('Download exception. Will fail.')
            for block in response.iter_content(1024):
                if not block:
                    break
                fp.write(block)
                file_size += len(block)
        logger.info('Download finished, size is %d bytes.', file_size)
    return file_size

def bytes2iec(size, compact=False):
    """Convert a size value in bytes to its equivalent in IEC notation.

    See `<http://physics.nist.gov/cuu/Units/binary.html>`_.

    Parameters:
        size (int): Number of bytes.
        compact (bool): If ``True``, the result contains no spaces.

    Return:
        String representation of ``size``.

    Raises:
        ValueError: Negative or out of bounds value for ``size``."""
    postfn = lambda text: text.replace(' ', '') if compact else text
    if size < 0:
        raise ValueError('Negative byte size value {}'.format(size))
    if size < 1024:
        return postfn('{:4d} bytes'.format(size))
    scaled = size
    for iec_unit in IEC_UNITS[1:]:
        scaled /= 1024.0
        if scaled < 1024:
            return postfn('{:6.1f} {}'.format(scaled, iec_unit))
    raise ValueError('Byte size value {} out of bounds'.format(size))

def inurl(needles, haystack, position='any'):
    """convenience function to make string.find return bool"""
    count = 0
    haystack2 = haystack.lower()
    for needle in needles:
        needle2 = needle.lower()
        if position == 'any':
            if haystack2.find(needle2) > -1:
                count += 1
        elif position == 'end':
            if haystack2.endswith(needle2):
                count += 1
        elif position == 'begin':
            if haystack2.startswith(needle2):
                count += 1
    if count > 0:
        return True
    return False

def find_executable(executable, path=None):
    """Tries to find 'executable' in the directories listed in 'path'.

    A string listing directories separated by 'os.pathsep'; defaults to
    os.environ['PATH'].  Returns the complete filename or None if not found."""
    if path is None:
        path = os.environ['PATH']
    paths = path.split(os.pathsep)
    base, ext = os.path.splitext(executable)
    if (sys.platform == 'win32' or os.name == 'os2') and ext != '.exe':
        executable = executable + '.exe'
    if not os.path.isfile(executable):
        for p in paths:
            f = os.path.join(p, executable)
            if os.path.isfile(f):
                return f
        return None
    else:
        return executable

def psycopg2_wait_callback(conn):
    """A wait callback to allow greenlet to work with Psycopg.
    The caller must be from a greenlet other than the main one.

    :param conn: psycopg2 connection or file number

    This function must be invoked from a coroutine with parent, therefore
    invoking it from the main greenlet will raise an exception."""
    while True:
        state = conn.poll()
        if state == extensions.POLL_OK:
            break
        elif state == extensions.POLL_READ:
            _wait_fd(conn)
        elif state == extensions.POLL_WRITE:
            _wait_fd(conn, read=False)
        else:
            raise OperationalError('Bad result from poll: %r' % state)

