def execute(script, *args, **kwargs):
    """Executes a command through the shell. Spaces should breakup the args. Usage: execute('grep', 'TODO', '*')
    NOTE: Any kwargs will be converted to args in the destination command.
    E.g. execute('grep', 'TODO', '*', **{'--before-context': 5}) will be $grep todo * --before-context=5"""
    popen_args = [script] + list(args)
    if kwargs:
        popen_args.extend(_kwargs_to_execute_args(kwargs))
    try:
        return check_call(popen_args, shell=False)
    except CalledProcessError as ex:
        _print(ex)
        sys.exit(ex.returncode)
    except Exception as ex:
        _print('Error: {} with script: {} and args {}'.format(ex, script, args))
        sys.exit(1)

def url_for_s3(endpoint, bucket_name, bucket_domain=None, scheme='', url_style='host', cdn_domain=None, filename=None):
    """Generates an S3 URL to the given endpoint, using the
    given bucket config.

    Example:
    url_for_s3('static', bucket_name='my-cool-foobar-bucket',
               scheme='https', filename='pics/logo.png')

    Will return:
    https://my-cool-foobar-bucket.s3.amazonaws.com/static/pics/logo.png

    Note: this function assumes that the given resource exists on S3
    and is publicly accessible.

    Based loosely on Flask-S3's url_for()."""
    if not bucket_name:
        raise ValueError('Bucket name is required when calling url_for_s3().')
    if url_style == 'host':
        url_format = '%(bucket_name)s.%(bucket_domain)s'
    elif url_style == 'path':
        url_format = '%(bucket_domain)s/%(bucket_name)s'
    else:
        raise ValueError('Invalid S3 URL style: "%s"' % url_style)
    if bucket_domain == None:
        bucket_domain = u's3.amazonaws.com'
    bucket_path = url_format % {'bucket_name': bucket_name, 'bucket_domain': bucket_domain}
    if cdn_domain:
        bucket_path = '%s' % cdn_domain
    return str('%s//%s/%s%s' % (scheme + (':' if scheme else ''), bucket_path, endpoint + ('/' if endpoint else ''), filename.lstrip('/')))

def ucast_ip_mask(ip_addr_and_mask, return_tuple=True):
    """Function to check if a address is unicast and that the CIDR mask is good
    Args:
        ip_addr_and_mask: Unicast IP address and mask in the following format 192.168.1.1/24
        return_tuple: Set to True it returns a IP and mask in a tuple, set to False returns True or False

    Returns: see return_tuple for return options"""
    regex_ucast_ip_and_mask = __re.compile('^((22[0-3])|(2[0-1][0-9])|(1[0-9][0-9])|([1-9]?[0-9]))\\.((25[0-5])|(2[0-4][0-9])|(1[0-9][0-9])|([1-9]?[0-9]))\\.((25[0-5])|(2[0-4][0-9])|(1[0-9][0-9])|([1-9]?[0-9]))\\.((25[0-5])|(2[0-4][0-9])|(1[0-9][0-9])|([1-9]?[0-9]))/((3[0-2])|([1-2]?[0-9]))$')
    if return_tuple:
        while not regex_ucast_ip_and_mask.match(ip_addr_and_mask):
            print('Not a good unicast IP and CIDR mask combo.')
            print('Please try again.')
            ip_addr_and_mask = input('Please enter a unicast IP address and mask in the follwing format x.x.x.x/x: ')
        ip_cidr_split = ip_addr_and_mask.split('/')
        ip_addr = ip_cidr_split[0]
        cidr = ip_cidr_split[1]
        return (ip_addr, cidr)
    elif not return_tuple:
        if not regex_ucast_ip_and_mask.match(ip_addr_and_mask):
            return False
        else:
            return True

