def parse_line(line):
    """Parses a byte string like:

       PROXY TCP4 192.168.0.1 192.168.0.11 56324 443


    to a `ProxyInfo`."""
    if not line.startswith(b'PROXY'):
        raise exc.InvalidLine('Missing "PROXY" prefix', line)
    if not line.endswith(CRLF):
        raise exc.InvalidLine('Missing "\\r\\n" terminal', line)
    parts = line[:-len(CRLF)].split(b' ')
    if len(parts) != 6:
        raise exc.InvalidLine('Expected 6 " " delimited parts', line)
    inet, src_addr, dst_addr = parts[1:4]
    if inet == b'TCP4':
        try:
            socket.inet_pton(socket.AF_INET, src_addr)
            socket.inet_pton(socket.AF_INET, dst_addr)
        except socket.error:
            raise exc.InvalidLine('Invalid INET {0} address(es)'.format(inet), line)
    elif inet == b'TCP6':
        try:
            socket.inet_pton(socket.AF_INET6, src_addr)
            socket.inet_pton(socket.AF_INET6, dst_addr)
        except socket.error:
            raise exc.InvalidLine('Invalid INET {0} address(es)'.format(inet), line)
    else:
        raise exc.InvalidLine('Unsupported INET "{0}"'.format(inet), line)
    try:
        src_port = int(parts[4])
        dst_port = int(parts[5])
    except (TypeError, ValueError):
        raise exc.InvalidLine(line, 'Invalid port')
    return ProxyInfo(source_address=src_addr, source_port=src_port, destination_address=dst_addr, destination_port=dst_port)

def lexically_parse_tweet(tweet, phrase_tree):
    """Returns list of LexicalTokens found in tweet. The list contains all the words in original tweet, but are
    optimally grouped up to form largest matching n-grams from lexicon. If no match is found, token is added as
    singleton.

    @param tweet      Tweet to lexically parse
    @param phrase_tree Token tree that contains all the lexical n-grams
    @return List of LexicalTokens"""
    lexical_tokens = []
    prev = 0
    while True:
        match = RegexFilters.SENTENCE_END_PUNCTUATION.search(tweet[prev:])
        if match is None:
            break
        span = match.span()
        sentence = tweet[prev:prev + span[0]]
        punctuation = match.group(0)
        prev += span[1]
        lexical_tokens.extend(parse_sentence(sentence, punctuation, phrase_tree))
    lexical_tokens.extend(parse_sentence(tweet[prev:], None, phrase_tree))
    return lexical_tokens

def estimate_tau_exp(chains, **kwargs):
    """Estimate the exponential auto-correlation time for all parameters in a chain."""
    rho = np.nan * np.ones(chains.shape[1:])
    for i in range(chains.shape[2]):
        try:
            rho[:, i] = autocorr.function(np.mean(chains[:, :, i], axis=0), **kwargs)
        except:
            continue
    rho_max = np.max(rho, axis=1)
    x = np.arange(rho_max.size)
    func = lambda tau_exp: np.exp(-x / tau_exp)
    chi = lambda tau_exp: func(tau_exp[0]) - rho_max
    tau_exp, ier = leastsq(chi, [chains.shape[1] / 2.0])
    return (tau_exp, rho, func(tau_exp))

def estimate_tau_int(chains, **kwargs):
    """Estimate the integrated auto-correlation time for all parameters in a chain."""
    return autocorr.integrated_time(np.mean(chains, axis=0), **kwargs)

