def _get_task(name):
    """Look up a task by name."""
    matches = [x for x in TASKS if x.match(name)]
    if matches:
        return matches[0]

def _opts_to_dict(*opts):
    """Convert a tuple of options returned from getopt into a dictionary."""
    ret = {}
    for key, val in opts:
        if key[:2] == '--':
            key = key[2:]
        elif key[:1] == '-':
            key = key[1:]
        if val == '':
            val = True
        ret[key.replace('-', '_')] = val
    return ret

def _highlight(string, color):
    """Return a string highlighted for a terminal."""
    if CONFIG['color']:
        if color < 8:
            return '\x1b[{color}m{string}\x1b[0m'.format(string=string, color=color + 30)
        else:
            return '\x1b[{color}m{string}\x1b[0m'.format(string=string, color=color + 82)
    else:
        return string

def _taskify(func):
    """Convert a function into a task."""
    if not isinstance(func, _Task):
        func = _Task(func)
        spec = inspect.getargspec(func.func)
        if spec.args:
            num_args = len(spec.args)
            num_kwargs = len(spec.defaults or [])
            isflag = lambda x, y: '' if x.defaults[y] is False else '='
            func.args = spec.args[:num_args - num_kwargs]
            func.defaults = {spec.args[i - num_kwargs]: spec.defaults[i] for i in range(num_kwargs)}
            func.kwargs = [key.replace('_', '-') + isflag(func, key) for key in func.defaults]
        if not func.name.startswith('_'):
            TASKS.append(func)
    return func

def task(*args, **kwargs):
    """Register a function as a task, as well as applying any attributes."""
    if args and hasattr(args[0], '__call__'):
        return _taskify(args[0])
    else:
        def wrapper(func):
            global DEFAULT, SETUP, TEARDOWN
            func = _taskify(func)
            if 'default' in args:
                DEFAULT = func
            if 'setup' in args:
                SETUP = func
            if 'teardown' in args:
                TEARDOWN = func
            if 'private' in args:
                TASKS.remove(func)
            if 'method' in args:
                func.method = True
                func.args = func.args[1:]
            if 'consume' in args:
                func.consume = True
            if 'reqs' in kwargs:
                func.reqs = _tuplify(kwargs['reqs'])
                func.file_reqs = [req for req in func.reqs if type(req) is str]
                func.task_reqs = [req for req in func.reqs if type(req) is not str]
            if 'gens' in kwargs:
                func.gens = kwargs['gens']
                GENERATES[kwargs['gens']] = func
            if 'alias' in kwargs:
                func.aliases = _tuplify(kwargs['alias'])
            if 'namespace' in kwargs:
                func.ns = kwargs['namespace'] + '.' if kwargs['namespace'] else ''
            return func
        return wrapper

def require(*reqs):
    """Require tasks or files at runtime."""
    for req in reqs:
        if type(req) is str:
            if not os.path.exists(req) and req not in GENERATES:
                abort(LOCALE['abort_bad_file'].format(req))
            if req not in GENERATES:
                return
            if req in GENERATES:
                req = GENERATES[req]
        if req.valid is None:
            if len(req.args):
                abort(LOCALE['abort_bad_args'], req, len(req.args))
            req()
        if req.valid is False:
            abort(LOCALE['abort_bad_task'], req)

def valid(*things):
    """Return True if all tasks or files are valid.
    Valid tasks have been completed already. Valid files exist on the disk."""
    for thing in things:
        if type(thing) is str and (not os.path.exists(thing)):
            return False
        if thing.valid is None:
            return False
    return True

def age(*paths):
    """Return the minimum age of a set of files.
    Returns 0 if no paths are given.
    Returns time.time() if a path does not exist."""
    if not paths:
        return 0
    for path in paths:
        if not os.path.exists(path):
            return time.time()
    return min([time.time() - os.path.getmtime(path) for path in paths])

def abort(message, *args):
    """Raise an AbortException, halting task execution and exiting."""
    if args:
        raise _AbortException(message.format(*args))
    raise _AbortException(message)

def _invoke(task, args):
    """Invoke a task with the appropriate args; return the remaining args."""
    kwargs = task.defaults.copy()
    if task.kwargs:
        temp_kwargs, args = getopt.getopt(args, '', task.kwargs)
        temp_kwargs = _opts_to_dict(*temp_kwargs)
        kwargs.update(temp_kwargs)
    if task.args:
        for arg in task.args:
            if not len(args):
                abort(LOCALE['error_wrong_args'], task, len(task.args))
            kwargs.update({arg: args[0]})
            args = args[1:]
    if task.consume:
        task(*args, **kwargs)
        return []
    else:
        task(**kwargs)
        return args

def main(args):
    """Do everything awesome."""
    if SETUP:
        args = _invoke(SETUP, args)
    if not args and DEFAULT:
        DEFAULT()
    else:
        while args:
            task = _get_task(args[0])
            if task is None:
                abort(LOCALE['error_no_task'], args[0])
            args = _invoke(task, args[1:])
    if TEARDOWN:
        TEARDOWN()

def match_item(key, value, item):
    """Check if some item matches criteria."""
    if isinstance(value, (list, tuple)):
        return any((match_item(key, sub_value, item) for sub_value in value))
    else:
        return key not in item or str(item.get(key)).lower() == str(value).lower()

def with_color_stripped(f):
    """A function decorator for applying to `len` or imitators thereof that strips
    ANSI color sequences from a string before passing it on.  If any color
    sequences are not followed by a reset sequence, an `UnterminatedColorError`
    is raised."""
    @wraps(f)
    def colored_len(s):
        s2 = re.sub(COLOR_BEGIN_RGX + '(.*?)' + COLOR_END_RGX, lambda m: re.sub(COLOR_BEGIN_RGX, '', m.group(1)), s)
        if re.search(COLOR_BEGIN_RGX, s2):
            raise UnterminatedColorError(s)
        return f(re.sub(COLOR_END_RGX, '', s2))
    return colored_len

def breakable_units(s):
    """Break a string into a list of substrings, breaking at each point that it is
    permissible for `wrap(..., break_long_words=True)` to break; i.e., _not_
    breaking in the middle of ANSI color escape sequences."""
    units = []
    for run, color in zip(re.split('(' + COLOR_BEGIN_RGX + '|' + COLOR_END_RGX + ')', s), cycle([False, True])):
        if color:
            units.append(run)
        else:
            units.extend(run)
    return units

def _delegate_or(smethname, func):
    """Produce a method that calls either the existing method of the wrapped
    object with the same name or a special invocation if it's missing
    (see SPECIAL_METHODS in special_methods.py).

    Usage: OnAccessMutant(initial_object, callable_mutator)
    where: callable_mutator(wrapped_object) -> new_wrapped_object"""
    def delegated(self, *a, **kwa):
        wrapped = object.__getattribute__(self, '__wrapped_object__')
        mutator = object.__getattribute__(self, '__wrapped_mutator__')
        wrapped = mutator(wrapped)
        object.__setattr__(self, '__wrapped_object__', wrapped)
        try:
            meth = getattr(wrapped, smethname)
        except AttributeError:
            return func(wrapped, *a, **kwa)
        if not isinstance(wrapped, type):
            return meth(*a, **kwa)
        else:
            meth = getattr(type(wrapped), smethname)
            return meth(wrapped, *a, **kwa)
    return delegated

def json_or_jsonp(func):
    """Wrap response in JSON or JSONP style"""
    @wraps(func)
    def _(*args, **kwargs):
        mimetype = 'application/javascript'
        callback = request.args.get('callback', None)
        if callback is None:
            content = func(*args, **kwargs)
        else:
            content = '%s(%s)' % (callback, func(*args, **kwargs))
        return current_app.response_class(content, mimetype=mimetype)
    return _

def add_response_headers(headers):
    '''Add headers passed in to the response

    Usage:

    .. code::py

        @app.route('/')
        @add_response_headers({'X-Robots-Tag': 'noindex'})
        def not_indexed():
            # This will set ``X-Robots-Tag: noindex`` in the response headers
            return "Check my headers!"'''
    def decorator(func):
        @wraps(func)
        def _(*args, **kwargs):
            rsp = make_response(func(*args, **kwargs))
            rsp_headers = rsp.headers
            for header, value in headers.items():
                rsp_headers[header] = value
            return rsp
        return _
    return decorator

def gen(mimetype):
    """``gen`` is a decorator factory function, you just need to set
    a mimetype before using::

        @app.route('/')
        @gen('')
        def index():
            pass

    A full demo for creating a image stream is available on
    `GitHub <https://github.com/kxxoling/flask-video-streaming>`__ ."""
    def streaming(func, *args, **kwargs):
        @wraps(func)
        def _():
            return Response(func(*args, **kwargs), mimetype=mimetype)
        return _
    return streaming

def wrap_ptr_class(struct, constructor, destructor, classname=None):
    """Creates wrapper class for pointer to struct class which appropriately
    acquires and releases memory"""
    class WrapperClass(ctypes.c_void_p):
        def __init__(self, val=None):
            if val:
                super(WrapperClass, self).__init__(val)
            else:
                super(WrapperClass, self).__init__(constructor())
        def __del__(self):
            destructor(self)
            self.value = None
        def __getattr__(self, name):
            return getattr(ctypes.cast(self.value, ctypes.POINTER(struct)).contents, name)
        def __setattr__(self, name, value):
            if name == 'value' or name.startswith('_'):
                super(WrapperClass, self).__setattr__(name, value)
            else:
                cont = ctypes.cast(self.value, ctypes.POINTER(struct)).contents
                if isinstance(value, str):
                    value = value.encode('utf-8')
                setattr(cont, name, value)
    WrapperClass.__name__ = classname or struct.__name__.lstrip('_')
    return WrapperClass

def make_dirs_for_file_path(file_path, mode=509):
