def wait_for_service(host, port, timeout=DEFAULT_TIMEOUT):
    """Return True if connection to the host and port is successful within the timeout.

    @param host: str: hostname of the server
    @param port: int: TCP port to which to connect
    @param timeout: int: length of time in seconds to try to connect before giving up
    @return: bool"""
    service = ServiceURL('tcp://{}:{}'.format(host, port), timeout)
    return service.wait()

def wait_for_url(url, timeout=DEFAULT_TIMEOUT):
    """Return True if connection to the host and port specified in url
    is successful within the timeout.

    @param url: str: connection url for a TCP service
    @param timeout: int: length of time in seconds to try to connect before giving up
    @raise RuntimeError: if no port is given or can't be guessed via the scheme
    @return: bool"""
    service = ServiceURL(url, timeout)
    return service.wait()

def get_memcached_usage(socket=None):
    """Returns memcached statistics.

    :param socket: Path to memcached's socket file."""
    cmd = "echo 'stats' | nc -U {0}".format(socket)
    output = getoutput(cmd)
    curr_items = None
    bytes_ = None
    rows = output.split('\n')[:-1]
    for row in rows:
        row = row.split()
        if row[1] == 'curr_items':
            curr_items = int(row[2])
        if row[1] == 'bytes':
            bytes_ = int(row[2])
    return (bytes_, curr_items)

def channel_parameters(parameter_prefix, channel_names, configuration_entry):
    """Return parameters specific to a channel for a model."""
    if configuration_entry in (True, False):
        return ([], [parameter_prefix])[configuration_entry]
    parameters = []
    if isinstance(configuration_entry, dict):
        for name in set(channel_names).intersection(configuration_entry):
            if configuration_entry[name] is True:
                parameters.append(parameter_prefix + '_' + name)
    else:
        raise TypeError('incorrect type')
    return parameters

def file_md5(f, size=8192):
    """Calculates the MD5 of a file."""
    md5 = hashlib.md5()
    while True:
        data = f.read(size)
        if not data:
            break
        md5.update(data)
    return md5.hexdigest()

def require_backup_exists(func):
    """Requires that the file referred to by `backup_file` exists in the file
    system before running the decorated function."""
    def new_func(*args, **kwargs):
        backup_file = kwargs['backup_file']
        if not os.path.exists(backup_file):
            raise RestoreError("Could not find file '{0}'".format(backup_file))
        return func(*args, **kwargs)
    return new_func

def ecdsa_recover_raw(rawhash, vrs):
    """Takes a rawhash message of length 32 bytes and a (v, r, s) tuple
    Returns a public key for the private key used in the sign function"""
    assert len(vrs) == 3
    assert len(rawhash) == 32
    return ecdsa_recover_compact(rawhash, _encode_sig(*vrs))

def ecdsa_verify_raw(msg32, vrs, pub):
    """Takes a message, the signature being verified and a pubkey
    Returns 1 if signature is valid with given pubkey"""
    if len(vrs) == 3:
        return ecdsa_verify_compact(msg32, _encode_sig(*vrs), pub)
    else:
        return ecdsa_verify_compact(msg32, vrs, pub)

def auto_zip_open(filepath, mode):
    """Convenience function for opening potentially-compressed files."""
    if filepath.endswith('.gz'):
        outfile = gzip.open(filepath, mode)
    elif filepath.endswith('.bz2'):
        outfile = bz2.BZ2File(filepath, mode)
    else:
        outfile = open(filepath, mode)
    return outfile

def process_allele(allele_data, dbsnp_data, header, reference):
    """Combine data from multiple lines refering to a single allele.

    Returns three items in this order:
        (string) concatenated variant sequence (ie allele the genome has)
        (string) concatenated reference sequence
        (string) start position (1-based)"""
    start = str(int(allele_data[0][header['begin']]))
    var_allele = ''
    ref_allele = ''
    filters = []
    for data in allele_data:
        if 'varQuality' in header:
            if 'VQLOW' in data[header['varQuality']]:
                filters.append('VQLOW')
        else:
            var_filter = data[header['varFilter']]
            if var_filter and (not var_filter == 'PASS'):
                filters = filters + var_filter.split(';')
        if data[header['varType']] == 'no-call':
            filters = ['NOCALL']
            ref_allele = ref_allele + data[header['reference']]
            continue
        var_allele = var_allele + data[header['alleleSeq']]
        ref_allele = ref_allele + data[header['reference']]
        if data[header['xRef']]:
            for dbsnp_item in data[header['xRef']].split(';'):
                dbsnp_data.append(dbsnp_item.split(':')[1])
    if 'NOCALL' in filters:
        filters = ['NOCALL']
        var_allele = '?'
    return (var_allele, ref_allele, start, filters)

def convert_to_file(cgi_input, output_file, twobit_ref, twobit_name, var_only=False):
    """Convert a CGI var file and output VCF-formatted data to file"""
    if isinstance(output_file, str):
        output_file = auto_zip_open(output_file, 'w')
    conversion = convert(cgi_input=cgi_input, twobit_ref=twobit_ref, twobit_name=twobit_name, var_only=var_only)
    for line in conversion:
        output_file.write(line + '\n')
    output_file.close()

def get_reference_genome_file(refseqdir, build):
    """Convenience fxn to get reference genome from target dir, download if needed"""
    if not os.path.exists(refseqdir) or not os.path.isdir(refseqdir):
        raise ValueError('No directory at {}'.format(refseqdir))
    twobit_name = ''
    if build in ['b37', 'build 37', 'build37', '37', 'hg19']:
        twobit_name = 'hg19.2bit'
        build = 'build37'
    if not twobit_name:
        raise ValueError('Genome bulid "{}" not supported.'.format(build))
    twobit_path = os.path.join(refseqdir, twobit_name)
    if not os.path.exists(twobit_path):
        twobitdownload.save_genome('hg19', destdir=refseqdir)
    return (twobit_path, twobit_name)

def from_command_line():
    """Run CGI var to gVCF conversion from the command line."""
    parser = argparse.ArgumentParser(description='Convert Complete Genomics var files to gVCF format.')
    parser.add_argument('-d', '--refseqdir', metavar='REFSEQDIR', required=True, dest='refseqdir', help='Directory twobit reference genomes files are stored.')
    parser.add_argument('-i', '--input', metavar='INPUTVARFILE', dest='cgivarfile', help='Path to Complete Genomics var file to convert. If omitted, data  also be piped in as standard input.')
    parser.add_argument('-o', '--output', metavar='OUTPUTVCFFILE', dest='vcfoutfile', help='Path to where to save output VCF file.')
    parser.add_argument('-D', '--download', action='store_true', dest='downloadrefseq', help='Download the 2bit file from UCSC to REFSEQDIR, if needed.')
    parser.add_argument('-v', '--var-only', action='store_true', dest='varonly', help='Only report variant lines (i.e. VCF, but not gVCF)')
    args = parser.parse_args()
    twobit_path, twobit_name = get_reference_genome_file(args.refseqdir, build='b37')
    if sys.stdin.isatty():
        var_input = args.cgivarfile
    else:
        var_input = sys.stdin
    if args.vcfoutfile:
        convert_to_file(var_input, args.vcfoutfile, twobit_path, twobit_name, args.varonly)
    else:
        for line in convert(cgi_input=var_input, twobit_ref=twobit_path, twobit_name=twobit_name, var_only=args.varonly):
            print(line)

def job(func_or_queue=None, connection=None, *args, **kwargs):
    """The same as RQ's job decorator, but it works automatically works out
    the ``connection`` argument from RQ_QUEUES.

    And also, it allows simplified ``@job`` syntax to put job into
    default queue."""
    if callable(func_or_queue):
        func = func_or_queue
        queue = 'default'
    else:
        func = None
        queue = func_or_queue or 'default'
    if not isinstance(queue, basestring):
        queue = unicode(queue)
    try:
        queue = get_queue(queue)
        if connection is None:
            connection = queue.connection
    except KeyError:
        pass
    decorator = _job(queue, *args, connection=connection, **kwargs)
    if func:
        return decorator(func)
    return decorator

