def action_handler_adapter(handler_cls: type, action_name: str) -> Callable:
    """wraps class to wsgi application dispathing action"""
    if not hasattr(handler_cls(), action_name):
        message = "{0} does'nt have attr:{1}".format(handler_cls, action_name)
        raise ValueError(message)
    def wsgiapp(environ, start_response):
        """inner app"""
        handler = handler_cls()
        return getattr(handler, action_name)(environ, start_response)
    return wsgiapp

def form_adverb_from_adjective(adjective):
    """Forms an adverb from the input adjective, f.ex. "happy" => "happily".
    Adverbs are generated using rules from: http://www.edufind.com/english-grammar/forming-adverbs-adjectives/

    :param adjective: adjective
    :return: adverb form of the input adjective"""
    if adjective.endswith('able') or adjective.endswith('ible') or adjective.endswith('le'):
        return adjective[:-1] + 'y'
    elif adjective.endswith('y'):
        return adjective[:-1] + 'ily'
    elif adjective.endswith('ic'):
        return adjective[:-2] + 'ally'
    return adjective + 'ly'

def batch_stream(buff, stream, size=DEFAULT_BATCH_SIZE):
    """Writes a batch of `size` lines to `buff`.

    Returns boolean of whether the stream has been exhausted."""
    buff.truncate(0)
    for _ in xrange(size):
        if hasattr(stream, 'readline'):
            line = stream.readline()
        else:
            try:
                line = next(stream)
            except StopIteration:
                line = ''
        if line == '':
            buff.seek(0)
            return True
        buff.write(line)
    buff.seek(0)
    return False

def resolve_url_ext(to, params_=None, anchor_=None, args=None, kwargs=None):
    """Advanced resolve_url which can includes GET-parameters and anchor."""
    url = resolve_url(to, *(args or ()), **kwargs or {})
    if params_:
        url += '?' + urllib.urlencode(encode_url_query_params(params_))
    if anchor_:
        url += '#' + anchor_
    return url

def redirect_ext(to, params_=None, anchor_=None, permanent_=False, args=None, kwargs=None):
    """Advanced redirect which can includes GET-parameters and anchor."""
    if permanent_:
        redirect_class = HttpResponsePermanentRedirect
    else:
        redirect_class = HttpResponseRedirect
    return redirect_class(resolve_url_ext(to, params_, anchor_, args, kwargs))

def add_response_headers(h):
    """Add HTTP-headers to response.
    Example:
        @add_response_headers({'Refresh': '10', 'X-Powered-By': 'Django'})
        def view(request):
            ...."""
    def headers_wrapper(fun):
        def wrapped_function(*args, **kwargs):
            response = fun(*args, **kwargs)
            for k, v in h.iteritems():
                response[k] = v
            return response
        return wrapped_function
    return headers_wrapper

