    """Manages adding/removing samples from autocreated cohorts."""
    lookup = {'batch': None, 'project': None, 'autocreated': True, 'name': 'World'}
    try:
        world_cohort = Cohort.objects.get(**lookup)
    except Cohort.DoesNotExist:
        if getattr(settings, 'VARIFY_AUTO_CREATE_COHORT', True):
            world_cohort = Cohort(**lookup)
            world_cohort.save()
        else:
            log.info('World cohort was not found and was not created because VARIFY_AUTO_CREATE_COHORT setting is False.')
