def luhn(base, num_only=False, allow_lower_case=False):
    """Return the Luhn check digit for the given string.

    Args:
        base(str): string for which to calculate the check digit
        num_only(bool): allow only digits in `base` (default: False)
        allow_lower_case(bool): allow lower case letters in `base`
            (default: False)

    Returns:
        int: Luhn check digit

    Raises:
        ValueError: given `base` contains an unallowed character"""
    if num_only:
        alphabet = _ALPHABET[:10]
    else:
        alphabet = _ALPHABET
    if allow_lower_case:
        base = base.upper()
    try:
        pre_calc = (_PRE_CALC[alphabet.index(c)] for c in reversed(base))
        cum = 0
        parity = 1
        for elem in pre_calc:
            val, parity = elem[parity]
            cum += val
    except ValueError:
        pass
    else:
        return 10 - cum % 10
    if num_only:
        msg = 'The string given must only contain digits.'
    elif allow_lower_case:
        msg = 'The string given must only contain digits and ascii letters.'
    else:
        msg = 'The string given must only contain digits and upper case ascii letters.'
    raise ValueError(msg)

def unmarshal_dict(obj, cls, allow_extra_keys=True, ctor=None):
    """Unmarshal @obj into @cls

    Args:
        obj:              dict, The dict to unmarshal into @cls
        cls:              type, The class to unmarshal into
        allow_extra_keys: bool, False to raise an exception when extra
                          keys are present, True to ignore
    Returns:
        instance of @cls
    Raises:
        ExtraKeysError: If allow_extra_keys == False, and extra keys
                        are present in @obj and not in @cls.__init__
        ValueError:     If @cls.__init__ does not contain a self argument"""
    if not ctor:
        ctor = cls
    args = init_args(ctor)
    obj = key_swap(obj, cls, False)
    kwargs = {k: v for k, v in obj.items() if k in args}
    allow_extra_keys = getattr(cls, '_unmarshal_allow_extra_keys', True) and allow_extra_keys
    if not allow_extra_keys and len(obj) > len(kwargs):
        diff = {k: v for k, v in obj.items() if k not in args}
        raise ExtraKeysError(cls, diff)
    try:
        return ctor(**kwargs)
    except ExtraKeysError as ex:
        raise ex
    except Exception as ex:
        raise InitArgsError(cls, args, kwargs, ex)

def _FormatTypeCheck(type_):
    """Pretty format of type check."""
    if isinstance(type_, tuple):
        items = [_FormatTypeCheck(t) for t in type_]
        return '(%s)' % ', '.join(items)
    elif hasattr(type_, '__name__'):
        return type_.__name__
    else:
        return repr(type_)

def _ValidateValue(value, type_check):
    """Validate a single value with type_check."""
    if inspect.isclass(type_check):
        return isinstance(value, type_check)
    if isinstance(type_check, tuple):
        return _ValidateTuple(value, type_check)
    elif callable(type_check):
        return type_check(value)
    else:
        raise TypeError("Invalid type check '%s'" % repr(type_check))

def _ParseDocstring(function):
    """Parses the functions docstring into a dictionary of type checks."""
    if not function.__doc__:
        return {}
    type_check_dict = {}
    for match in param_regexp.finditer(function.__doc__):
        param_str = match.group(1).strip()
        param_splitted = param_str.split(' ')
        if len(param_splitted) >= 2:
            type_str = ' '.join(param_splitted[:-1])
            name = param_splitted[-1]
            type_check_dict[name] = type_str
    for match in returns_regexp.finditer(function.__doc__):
        type_check_dict['returns'] = match.group(1)
    for match in type_regexp.finditer(function.__doc__):
        name = match.group(1)
        type_str = match.group(2)
        type_check_dict[name] = type_str
    for match in rtype_regexp.finditer(function.__doc__):
        type_check_dict['returns'] = match.group(1)
    return type_check_dict

def _CollectArguments(function, args, kwargs):
    """Merges positional and keyword arguments into a single dict."""
    all_args = dict(kwargs)
    arg_names = inspect.getargspec(function)[0]
    for position, arg in enumerate(args):
        if position < len(arg_names):
            all_args[arg_names[position]] = arg
    return all_args

def _CollectTypeChecks(function, parent_type_check_dict, stack_location, self_name):
    """Collect all type checks for this function."""
    type_check_dict = dict(parent_type_check_dict)
    type_check_dict.update(_ParseDocstring(function))
    for key, value in type_check_dict.items():
        if isinstance(value, str):
            type_check_dict[key] = _ParseTypeCheckString(value, stack_location + 1, self_name)
    return type_check_dict

def _ValidateArguments(arg_dict, type_check_dict):
    """Validate dictionary of arguments and return list of errors messages."""
    messages = []
    for arg_name, arg_value in arg_dict.items():
        if arg_name in type_check_dict:
            type_check = type_check_dict[arg_name]
            res = _ValidateValue(arg_value, type_check)
            if not res:
                message = "Invalid value '%s' for argument %s. Expected %s" % (arg_value, arg_name, _FormatTypeCheck(type_check))
                messages.append(message)
    return messages

def _ValidateReturnValue(return_value, type_check_dict):
    """Validate return value and return list of errors messages."""
    return_check = type_check_dict.get('returns', None)
    if not return_check:
        return []
    messages = []
    if not _ValidateValue(return_value, return_check):
        message = "Invalid return value '%s'. Expected %s" % (return_value, _FormatTypeCheck(return_check))
        messages.append(message)
    return messages

def _TypecheckDecorator(subject=None, **kwargs):
    """Dispatches type checks based on what the subject is.

    Functions or methods are annotated directly. If this method is called
    with keyword arguments only, return a decorator."""
    if subject is None:
        return _TypecheckDecoratorFactory(kwargs)
    elif inspect.isfunction(subject) or inspect.ismethod(subject):
        return _TypecheckFunction(subject, {}, 2, None)
    else:
        raise TypeError()

