def mt_modelform_register_clean_method(form_self, field_name, func, nomaster=False):
    """You can add clean_<field_name> for each translated field. For example:

    class MyModelForm(models.ModelForm):
        class Meta:
            model = MyModel
            _mt_fields = mt_fields(('title', 'description'), nomaster=True)
            fields = _mt_fields

        def __init__(self, *args, **kwargs):
            super(ItemCategoryEditForm, self).__init__(*args, **kwargs)

            mt_modelform_register_clean_method(self, 'title', self.mt_clean_title, nomaster=True)

        def mt_clean_title(self, field_name, lang):
            value = self.cleaned_data[field_name]
            # validation here
            return value"""
    args_list = [('{}_{}'.format(field_name, lang), lang) for lang in AVAILABLE_LANGUAGES]
    if not nomaster:
        args_list.append((field_name, None))
    def _get_mt_clean_method(args):
        def _mt_clean_method():
            return func(*args)
        return _mt_clean_method
    for item_args in args_list:
        method_name = 'clean_{}'.format(item_args[0])
        setattr(form_self, method_name, _get_mt_clean_method(item_args))

def floor(start, resolution):
    """Floor a datetime by a resolution.

    >>> now = datetime(2012, 7, 6, 20, 33, 16, 573225)
    >>> floor(now, STEP_1_HOUR)
    datetime.datetime(2012, 7, 6, 20, 0)"""
    if resolution == STEP_10_SEC:
        return datetime(start.year, start.month, start.day, start.hour, start.minute, start.second - start.second % 10)
    elif resolution == STEP_1_MIN:
        return datetime(start.year, start.month, start.day, start.hour, start.minute)
    elif resolution == STEP_5_MIN:
        return datetime(start.year, start.month, start.day, start.hour, start.minute - start.minute % 5)
    elif resolution == STEP_1_HOUR:
        return datetime(start.year, start.month, start.day, start.hour)
    elif resolution == STEP_1_DAY:
        return datetime(start.year, start.month, start.day)
    raise ValueError('{resolution} is not a valid resolution. Valid choices are {choices}'.format(resolution=resolution, choices=STEP_CHOICES))

def _timedelta_total_seconds(td):
    """Python 2.6 backward compatibility function for timedelta.total_seconds.

    :type td: timedelta object
    :param td: timedelta object

    :rtype: float
    :return: The total number of seconds for the given timedelta object."""
    if hasattr(timedelta, 'total_seconds'):
        return getattr(td, 'total_seconds')()
    return (td.microseconds + (td.seconds + td.days * 24 * 3600) * 10 ** 6) / float(10 ** 6)

def json_to_csv(json_input):
    """Convert simple JSON to CSV
    Accepts a JSON string or JSON object"""
    try:
        json_input = json.loads(json_input)
    except:
        pass
    headers = set()
    for json_row in json_input:
        headers.update(json_row.keys())
    csv_io = StringIO.StringIO()
    csv_out = csv.DictWriter(csv_io, headers)
    csv_out.writeheader()
    for json_row in json_input:
        csv_out.writerow(json_row)
    csv_io.seek(0)
    return csv_io.read()

def pattern_to_regex(pattern: str) -> str:
    """convert url patten to regex"""
    if pattern and pattern[-1] == '*':
        pattern = pattern[:-1]
        end = ''
    else:
        end = '$'
    for metac in META_CHARS:
        pattern = pattern.replace(metac, '\\' + metac)
    return '^' + VARS_PT.sub(regex_replacer, pattern) + end

def detect_converters(pattern: str, converter_dict: Dict[str, Callable], default: Callable=str):
    """detect pairs of varname and converter from pattern"""
    converters = {}
    for matched in VARS_PT.finditer(pattern):
        matchdict = matched.groupdict()
        varname = matchdict['varname']
        converter = matchdict['converter']
        converters[varname] = converter_dict.get(converter, default)
    return converters

def get_database_size(db_user, db_name, localhost=False):
    """Returns the total size for the given database role and name.

    :param db_user: String representing the database role.
    :param db_name: String representing the database name."""
    localhost_part = ''
    if localhost:
        localhost_part = '-h localhost '
    cmd = 'psql {0}-U {1} -c "select pg_database_size(\'{2}\');"'.format(localhost_part, db_user, db_name)
    total = getoutput(cmd).split()[2]
    return int(total)

def to_json(data, pretty):
    """Converts object to JSON formatted string with typeToken adapter
    :param data: A dictionary to convert to JSON string
    :param pretty: A boolean deciding whether or not to pretty format the JSON string
    :return: The JSON string"""
    if pretty:
        return json.dumps(data, sort_keys=True, indent=4, separators=(',', ': '))
    return json.dumps(data)

def simple_round_factory(tol):
    """helper function for simple_round (a factory for simple_round functions)"""
    def simple_round(*args, **kwds):
        argstype = type(args)
        _args = list(args)
        _kwds = kwds.copy()
        for i, j in enumerate(args):
            if isinstance(j, float):
                _args[i] = round(j, tol[i - 1] if isinstance(tol, (list, tuple)) else tol)
        for k, (i, j) in enumerate(kwds.items()):
            if isinstance(j, float):
                _kwds[i] = round(j, tol[k] if isinstance(tol, (list, tuple)) else tol)
        return (argstype(_args), _kwds)
    return simple_round

def CreatedField(name='created', tz_aware=False, **kwargs):
    """A shortcut field for creation time.  It sets the current date and time
    when it enters the database and then doesn't update on further saves.

    If you've used the Django ORM, this is the equivalent of auto_now_add

    :param tz_aware: If this is True, the value will be returned in the
                     local time of the session.  It is always saved in UTC"""
    @computed_field(DateTimeField(), one_time=True, **kwargs)
    def created(obj):
        if tz_aware:
            import pytz
            return pytz.utc.localize(datetime.utcnow())
        return datetime.utcnow()
    created.__name__ = name
    return created

def event_doctree_read(app, doctree):
    """Called by Sphinx during phase 1 (reading).

    * Add new Imgur IDs to the cache.

    :param sphinx.application.Sphinx app: Sphinx application object.
    :param docutils.nodes.document doctree: Tree of docutils nodes."""
    albums, images = (set(), set())
    for node in (n for c in (ImgurTextNode, ImgurImageNode) for n in doctree.traverse(c)):
        if node.album:
            albums.add(node.imgur_id)
        else:
            images.add(node.imgur_id)
    initialize(app.builder.env.imgur_album_cache, app.builder.env.imgur_image_cache, albums, images)

def event_env_updated(app, env):
    """Called by Sphinx during phase 3 (resolving).

    * Find Imgur IDs that need to be queried.
    * Query the Imgur API for new/outdated albums/images.

    :param sphinx.application.Sphinx app: Sphinx application object.
    :param sphinx.environment.BuildEnvironment env: Sphinx build environment."""
    client_id = app.config['imgur_client_id']
    ttl = app.config['imgur_api_cache_ttl']
    album_cache = app.builder.env.imgur_album_cache
    image_cache = app.builder.env.imgur_image_cache
    album_whitelist = {v.imgur_id for v in album_cache.values() if v.mod_time == 0}
    image_whitelist = {v.imgur_id for v in image_cache.values() if v.mod_time == 0}
    for doctree in (env.get_doctree(n) for n in app.builder.get_outdated_docs()):
        for node in (n for c in (ImgurTextNode, ImgurImageNode) for n in doctree.traverse(c)):
            if node.album:
                album_whitelist.add(node.imgur_id)
            else:
                image_whitelist.add(node.imgur_id)
    if album_whitelist or image_whitelist:
        update_cache(album_cache, image_cache, app, client_id, ttl, album_whitelist, image_whitelist)
        prune_cache(album_cache, image_cache, app)

def event_doctree_resolved(app, doctree, _):
    """Called by Sphinx after phase 3 (resolving).

    * Replace Imgur text nodes with data from the Sphinx cache.
    * Call finalizer for ImgurImageNode nodes.

    :param sphinx.application.Sphinx app: Sphinx application object.
    :param docutils.nodes.document doctree: Tree of docutils nodes.
    :param _: Not used."""
    album_cache = app.builder.env.imgur_album_cache
    image_cache = app.builder.env.imgur_image_cache
    for node in doctree.traverse(ImgurTextNode):
        cache = album_cache if node.album else image_cache
        if node.name == 'imgur-description':
            text = cache[node.imgur_id].description
        else:
            text = cache[node.imgur_id].title
        node.replace_self([docutils.nodes.Text(text)])
    for node in doctree.traverse(ImgurImageNode):
        if node.album and (not album_cache[node.imgur_id].cover_id):
            app.warn('Album cover Imgur ID for {} not available in local cache.'.format(node.imgur_id))
            node.replace_self([docutils.nodes.Text('')])
        else:
            node.finalize(album_cache, image_cache, lambda m: app.builder.env.warn_node(m, node))

def sorted_chain(*ranges: Iterable[Tuple[int, int]]) -> List[Tuple[int, int]]:
    """Chain & sort ranges."""
    return sorted(itertools.chain(*ranges))

def normalize_cjk_fullwidth_ascii(seq: str) -> str:
    """Conver fullwith ASCII to halfwidth ASCII.
    See https://en.wikipedia.org/wiki/Halfwidth_and_fullwidth_forms"""
    def convert(char: str) -> str:
        code_point = ord(char)
        if not 65281 <= code_point <= 65374:
            return char
        return chr(code_point - 65248)
    return ''.join(map(convert, seq))

def calculate_priority(ratios=None, **kwargs):
    """Calculates a priority score based on a number of attributes."""
    if not ratios:
        ratios = PRIORITY_FEATURE_WEIGHTS
    scores = [DEFAULT_PRIORITY_SCORE]
    for key, value in kwargs.items():
        if key not in PRIORITY_FEATURE_WEIGHTS:
            raise KeyError('The following keyword arguments are supported: {keys}'.format(keys=PRIORITY_FEATURES))
        if value is True:
            scores.append(PRIORITY_FEATURE_WEIGHTS[key])
    return float(sum(scores)) / len(scores)

def record_is_valid(record):
    """Checks if a record is valid for processing."""
    if record.CHROM.startswith('GL'):
        return False
    if 'DP' in record.INFO and record.INFO['DP'] < 5:
        return False
    return True

def get_env_str(env):
    """Gets a string representation of a dict as though it contained environment
    variable values."""
    return ' '.join(("{0}='{1}'".format(k, v) for k, v in env.items()))

def pipe_commands(cmds, extra_env=None, show_stderr=False, show_last_stdout=False):
    """Executes the list of commands piping each one into the next."""
    env = extend_env(extra_env) if extra_env else None
    env_str = get_env_str(extra_env) + ' ' if extra_env else ''
    cmd_strs = [env_str + ' '.join(cmd) for cmd in cmds]
    logger.info('Running `{0}`'.format(' | '.join(cmd_strs)))
    with open('/dev/null', 'w') as NULL:
        processes = []
        last_i = len(cmds) - 1
        for i, (cmd_str, cmd) in enumerate(zip(cmd_strs, cmds)):
            if i == last_i:
                p_stdout = None if show_last_stdout else NULL
            else:
                p_stdout = PIPE
            p_stdin = processes[-1][1].stdout if processes else None
            p_stderr = None if show_stderr else NULL
            p = Popen(cmd, env=env, stdout=p_stdout, stdin=p_stdin, stderr=p_stderr)
            processes.append((cmd_str, p))
        error = False
        for cmd_str, p in processes:
            if p.stdout:
                p.stdout.close()
            if p.wait() != 0:
                error = True
        if error:
            raise CalledProcessError(cmd=cmd_str, returncode=p.returncode)

def for_all(*generators):
    """Takes a list of generators and returns a closure which takes a property,
    then tests the property against arbitrary instances of the generators."""
    n = 100
    def test_property(property_function):
        """A closure which takes a property and tests it against arbitrary
        instances of the generators in the closure."""
        for generator in generators:
            assert issubclass(generator, ArbitraryInterface) or generator in arbitrary
        def test_once():
            """Tests the property against a single set of instances of the
            generators."""
            instances = [arbitrary(generator) for generator in generators]
            try:
                assert property_function(*instances)
            except AssertionError:
                generator_names = ', '.join((generator.__name__ for generator in generators))
                stringed_instances = ', '.join((str(instance) for instance in instances))
                error_message = ' '.join(['Instances <', stringed_instances, '> of <', generator_names, '> do not satisfy a property.'])
                raise AssertionError(error_message)
        for _ in range(n):
            test_once()
    return test_property

def maybe_a(generator):
    """Generates either an arbitrary value of the specified generator or None.
    This is a class factory, it makes a class which is a closure around the
    specified generator."""
    class MaybeAGenerator(ArbitraryInterface):
        """A closure class around the generator specified above, which generates
        either that generator or None."""
        @classmethod
        def arbitrary(cls):
            """Generate either the enclosed generator or None."""
            return arbitrary(one_of(None, generator))
    MaybeAGenerator.__name__ = ''.join(['maybe_a(', generator.__name__, ')'])
    return MaybeAGenerator

def one_of(*generators):
    """Generates an arbitrary value of one of the specified generators.
    This is a class factory, it makes a class which is a closure around the
    specified generators."""
    class OneOfGenerators(ArbitraryInterface):
        """A closure class around the generators specified above, which
        generates one of the generators."""
        @classmethod
        def arbitrary(cls):
            """Generate one of the enclosed generators."""
            return arbitrary(random.choice(generators))
    OneOfGenerators.__name__ = ''.join(['one_of(', ', '.join((generator.__name__ for generator in generators)), ')'])
    return OneOfGenerators

def tuple_of(*generators):
    """Generates a tuple by generating values for each of the specified
    generators.
    This is a class factory, it makes a class which is a closure around the
    specified generators."""
    class TupleOfGenerators(ArbitraryInterface):
        """A closure class around the generators specified above, which
        generates a tuple of the generators."""
        @classmethod
        def arbitrary(cls):
            """Generate a tuple of the enclosed generators."""
            return tuple([arbitrary(generator) for generator in generators if generator is not tuple])
    TupleOfGenerators.__name__ = ''.join(['tuple_of(', ', '.join((generator.__name__ for generator in generators)), ')'])
    return TupleOfGenerators

def set_of(*generators):
    """Generates a set consisting solely of the specified generators.
    This is a class factory, it makes a class which is a closure around the
    specified generators."""
    class SetOfGenerators(ArbitraryInterface):
        """A closure class around the generators specified above, which
        generates a set of the generators."""
        @classmethod
        def arbitrary(cls):
            """Generate a set of the enclosed generators."""
            arbitrary_set = set()
            for generator in generators:
                arbitrary_set |= {arbitrary(generator) for _ in range(arbitrary(int) % 100)}
            return arbitrary_set
    SetOfGenerators.__name__ = ''.join(['set_of(', ', '.join((generator.__name__ for generator in generators)), ')'])
    return SetOfGenerators

def list_of(*generators):
    """Generates a list consisting solely of the specified generators.
    This is a class factory, it makes a class which is a closure around the
    specified generators."""
    class ListOfGenerators(ArbitraryInterface):
        """A closure class around the generators specified above, which
        generates a list of the generators."""
        @classmethod
        def arbitrary(cls):
            """Generate a list of the enclosed generators."""
            arbitrary_list = []
            for generator in generators:
                arbitrary_list += [arbitrary(generator) for _ in range(arbitrary(int) % 100)]
            return arbitrary_list
    ListOfGenerators.__name__ = ''.join(['list_of(', ', '.join((generator.__name__ for generator in generators)), ')'])
    return ListOfGenerators

def dict_of(**kwargs):
    """Generates a homogeneous dict of the specified generators using kwargs.
    You can generate non-homogeneous dicts using `dict`.
    This is a class factory, it makes a class which is a closure around the
    specified keys and generators."""
    class DictOfKeyGenerators(ArbitraryInterface):
        """A closure class around the keys and generators specified above, which
        generates a dict of the keys and generators."""
        @classmethod
        def arbitrary(cls):
            """Generate a dict of the enclosed keys and generators."""
            return {key: arbitrary(generator) for key, generator in kwargs.iteritems()}
    DictOfKeyGenerators.__name__ = ''.join(['dict_of(', ', '.join([key + '=' + generator.__name__ for key, generator in kwargs.iteritems()]), ')'])
    return DictOfKeyGenerators

def cache_invalidate_by_tags(tags, cache=None):
    """Clear cache by tags."""
    if isinstance(tags, basestring):
        tags = [tags]
    tag_keys = [CACHE_TAG_KEY % tag for tag in tags if tag]
    if not tag_keys:
        raise ValueError('Attr tags invalid')
    if cache is None:
        cache = default_cache
    tag_keys_for_delete = []
    if cache.__class__.__name__ == 'RedisCache':
        from django_redis.exceptions import ConnectionInterrupted
        try:
            redis_client = cache.client.get_client()
            for tag_key in tag_keys:
                keys = redis_client.smembers(tag_key)
                if keys:
                    cache.delete_many(keys)
                    tag_keys_for_delete.append(tag_key)
        except ConnectionInterrupted:
            pass
    else:
        for tag_key in tag_keys:
            keys = cache.get(tag_key)
            if keys:
                cache.delete_many(keys)
                tag_keys_for_delete.append(tag_key)
    if tag_keys_for_delete:
        cache.delete_many(tag_keys_for_delete)

