def get_memory_usage(user=None):
    """Returns a three-tupel with memory usage for the given user.

    The result contains::

        (total memory, largest process' memory, largest process name)

    :param user: String representing the user. If `None`, the total size of
      all processes for all users will be returned."""
    total = 0
    largest_process = 0
    largest_process_name = None
    for p in psutil.process_iter():
        p_user = p.username()
        if user is None or p_user == user:
            try:
                process_memory = p.memory_info()[0]
            except psutil.AccessDenied:
                continue
            total += process_memory
            if process_memory > largest_process:
                largest_process = process_memory
                largest_process_name = p.name()
    return (total, largest_process, largest_process_name)

def ClassHopperMutant(initial_object, class_returning_callable, copy=True):
    """ClassHopper: a wrapper that reevaluates the class of the wrapped instance
    on every access attempt.
    It's like obj.__class__ = callable_returning_a_class(),
    but magically happening before every manipulation with the object.

    Usage: mutant.ClassHopper(initial_object, callable_returning_a_class)"""
    from copy import copy as _copy
    def class_mutator(obj):
        obj.__class__ = class_returning_callable(obj)
        return obj
    if copy:
        initial_object = _copy(initial_object)
    return OnAccessMutant(initial_object, class_mutator)

def filter_object(obj, marks, presumption=DELETE):
    """Filter down obj based on marks, presuming keys should be kept/deleted.

    Args:
        obj: The object to be filtered. Filtering is done in-place.
        marks: An object mapping id(obj) --> {DELETE,KEEP}
               These values apply to the entire subtree, unless inverted.
        presumption: The default action to take on all keys."""
    if isinstance(obj, list):
        keys = reversed(range(0, len(obj)))
    else:
        keys = obj.keys()
    for k in keys:
        v = obj[k]
        m = marks.get(id(v), UNSPECIFIED)
        if m == DELETE:
            del obj[k]
        elif m == KEEP or presumption == KEEP:
            if isinstance(v, list) or isinstance(v, dict):
                filter_object(v, marks, presumption=KEEP)
        elif m == UNSPECIFIED:
            if isinstance(v, list) or isinstance(v, dict):
                filter_object(v, marks, presumption=DELETE)
                if len(v) == 0:
                    del obj[k]
            else:
                del obj[k]

def _announce_theta(theta):
    """Announce theta values to the log."""
    c = 299792.458
    is_a_redshift = lambda p: p == 'z' or p[:2] == 'z_'
    for parameter, value in theta.items():
        try:
            value[0]
        except (IndexError, TypeError):
            message = '\t{0}: {1:.3f}'.format(parameter, value)
            if is_a_redshift(parameter):
                message += ' [{0:.1f} km/s]'.format(value * c)
        else:
            message = '\t{0}: {1:.3f} ({2:+.3f}, {3:+.3f})'.format(parameter, value[0], value[1], value[2])
            if is_a_redshift(parameter):
                message += ' [{0:.1f} ({1:+.1f}, {2:+.1f}) km/s]'.format(value[0] * c, value[1] * c, value[2] * c)
        logger.info(message)

def estimate(args, **kwargs):
    """Return a point estimate of the model parameters theta given the data."""
    expected_output_files = kwargs.pop('expected_output_files', None)
    if not expected_output_files:
        expected_output_files = ['estimate.pkl']
        if args.plotting:
            expected_output_files.extend(['projection-estimate.{}'.format(args.plot_format)])
    model, data, metadata = _pre_solving(args, expected_output_files)
    try:
        theta, chisq, dof, model_fluxes = model.estimate(data, full_output=True, debug=args.debug)
    except:
        logger.exception('Failed to estimate model parameters')
        raise
    logger.info('Estimated model parameters are:')
    _announce_theta(theta)
    logger.info('With a chi-sq value of {0:.1f} (reduced {1:.1f}; DOF {2:.1f})'.format(chisq, chisq / dof, dof))
    metadata['estimated'] = {'theta': theta, 'chi_sq': chisq, 'dof': dof, 'r_chi_sq': chisq / dof}
    if args.plotting:
        fig = sick.plot.spectrum(data, model_flux=model_fluxes)
        filename = _prefix(args, 'projection-estimate.{}'.format(args.plot_format))
        fig.savefig(filename)
        logger.info('Created figure {}'.format(filename))
    if kwargs.pop('__return_result', False):
        return (model, data, metadata, theta)
    _write_output(_prefix(args, 'estimate.pkl'), metadata)
    return None

def load_file_or_directory(path):
    """given a path, determine if the path is a file or directory, and
    yield a list of absolute file paths"""
    assert os.path.exists(path), '{0} does not exist!'.format(path)
    absolute_path = os.path.abspath(path)
    if not os.path.isdir(path):
        yield absolute_path
    else:
        for root, dirs, file_paths in os.walk(path):
            for file_path in file_paths:
                yield os.path.join(root, file_path)

def retrieve_data(file_paths):
    """passed an iterable list of file_paths, loop through all of them and
    generate a dictionary containing all the context"""
    data_dict = {}
    for file_path in file_paths:
        with open(file_path) as fh:
            try:
                content = yaml.load(fh.read())
            except yaml.YAMLError as e:
                raise MiuraException('Unable to parse yaml at {0}: \n {1}'.format(file_path, str(e)))
            if not isinstance(content, dict):
                raise MiuraException('{0} is does not translate to a dictionary!'.format(file_path))
            data_dict.update(content)
    return data_dict

def tcache(parser, token):
    """This will cache the contents of a template fragment for a given amount
    of time with support tags.

    Usage::
        {% tcache [expire_time] [fragment_name] [tags='tag1,tag2'] %}
            .. some expensive processing ..
        {% endtcache %}

    This tag also supports varying by a list of arguments:
        {% tcache [expire_time] [fragment_name] [var1] [var2] .. [tags=tags] %}
            .. some expensive processing ..
        {% endtcache %}

    Each unique set of arguments will result in a unique cache entry."""
    nodelist = parser.parse(('endtcache',))
    parser.delete_first_token()
    tokens = token.split_contents()
    if len(tokens) < 3:
        raise template.TemplateSyntaxError("'%r' tag requires at least 2 arguments." % tokens[0])
    tags = None
    if len(tokens) > 3 and 'tags=' in tokens[-1]:
        tags = parser.compile_filter(tokens[-1][5:])
        del tokens[-1]
    return CacheNode(nodelist, parser.compile_filter(tokens[1]), tokens[2], [parser.compile_filter(token) for token in tokens[3:]], tags)

def create(args):
    """Create a model from wavelength and flux files."""
    from sick.models.create import create
    return create(os.path.join(args.output_dir, args.model_name), args.grid_points_filename, args.wavelength_filenames, clobber=args.clobber)

def initialize(album_cache, image_cache, albums, images):
    """Instantiate Album or Image instances not already in cache.

    :param dict album_cache: Cache of Imgur albums to update. Keys are Imgur IDs, values are Album instances.
    :param dict image_cache: Cache of Imgur images to update. Keys are Imgur IDs, values are Image instances.
    :param iter albums: List of album Imgur IDs.
    :param iter images: List of image Imgur IDs.

    :return: Same album and image cache dictionaries from parameters.
    :rtype: tuple"""
    if not hasattr(album_cache, 'setdefault'):
        album_cache = dict()
    if not hasattr(image_cache, 'setdefault'):
        image_cache = dict()
    for imgur_id in albums:
        album_cache.setdefault(imgur_id, Album(imgur_id))
    for imgur_id in images:
        image_cache.setdefault(imgur_id, Image(imgur_id))
    return (album_cache, image_cache)

