def seal(mock):
    """Disable the automatic generation of "submocks"

    Given an input Mock, seals it to ensure no further mocks will be generated
    when accessing an attribute that was not already defined.

    Submocks are defined as all mocks which were created DIRECTLY from the
    parent. If a mock is assigned to an attribute of an existing mock,
    it is not considered a submock."""
    _frankeinstainize(mock)
    for attr in dir(mock):
        try:
            m = getattr(mock, attr)
        except AttributeError:
            continue
        if not isinstance(m, NonCallableMock):
            continue
        if m._mock_new_parent is mock:
            seal(m)

def each_fields(for_fields, fields):
    """select_related(
        'field__related_field1__text1', 'field__related_field1__text2',
        'field__related_field2__text1', 'field__related_field2__text2',
    )
    select_related(*each_fields(['field__related_field1', 'field__related_field2'], ['text1', 'text2']))
    each_fields('field__related_field1', ['text1', 'text2'])"""
    if isinstance(for_fields, basestring):
        for_fields = (for_fields,)
    r = set()
    for ff in for_fields:
        for f in fields:
            r.add(ff + '__' + f)
    return list(r)

def _remove_none(data):
    """Go thru `data` (dict / list) and remove ``None`` values."""
    if isinstance(data, list) or isinstance(data, tuple):
        return [x for x in data if x is not None]
    out = OrderedDict()
    for key, val in data.iteritems():
        if val is not None:
            out[key] = val
    return out

def to_dc(data):
    """Convert WA-KAT `data` to Dublin core XML.

    Args:
        data (dict): Nested WA-KAT data. See tests for example.

    Returns:
        unicode: XML with dublin core."""
    root = odict['metadata':odict['@xmlns:xsi':'http://www.w3.org/2001/XMLSchema-instance', '@xmlns:dc':'http://purl.org/dc/elements/1.1/', '@xmlns:dcterms':'http://purl.org/dc/terms/', '@xmlns:rdf':'http://www.w3.org/1999/02/22-rdf-syntax-ns#']]
    for key, val in _convert_metadata(_remove_none(data)).iteritems():
        if val is None:
            continue
        if isinstance(val, basestring) and (not val.strip()):
            continue
        if isinstance(val, str):
            val = val.decode('utf-8')
        root['metadata'][key] = val
    return unparse(root, pretty=True, indent='    ')

def track_model(model):
    """Perform designated transformations on model, when it saves.

    Calls :py:func:`~simpleimages.utils.perform_transformation`
    on every model saves using
    :py:data:`django.db.models.signals.post_save`.

    It uses the ``update_fields`` kwarg to tell what fields it should
    transform."""
    @receiver(post_save, sender=model, weak=False, dispatch_uid='simpleimages')
    def transform_signal(sender, **kwargs):
        simpleimages.utils.perform_transformation(kwargs['instance'], kwargs['update_fields'])
    def disconnect():
        post_save.disconnect(sender=model, dispatch_uid='simpleimages')
    return disconnect

def filter_req_paths(paths, func):
    """Return list of filtered libs."""
    if not isinstance(paths, list):
        raise ValueError('Paths must be a list of paths.')
    libs = set()
    junk = set(['\n'])
    for p in paths:
        with p.open(mode='r') as reqs:
            lines = set([line for line in reqs if func(line)])
            libs.update(lines)
    return list(libs - junk)

def urlopen(url, method=None, params=None, data=None, json=None, headers=None, allow_redirects=False, timeout=30, verify_ssl=True, user_agent=None):
    """A slightly safer version of ``urlib2.urlopen`` which prevents redirection
    and ensures the URL isn't attempting to hit a blacklisted IP range."""
    if user_agent is not None:
        warnings.warn('user_agent is no longer used with safe_urlopen')
    session = build_session()
    kwargs = {}
    if json:
        kwargs['json'] = json
        if not headers:
            headers = {}
        headers.setdefault('Content-Type', 'application/json')
    if data:
        kwargs['data'] = data
    if params:
        kwargs['params'] = params
    if headers:
        kwargs['headers'] = headers
    if method is None:
        method = 'POST' if data or json else 'GET'
    try:
        response = session.request(method=method, url=url, allow_redirects=allow_redirects, timeout=timeout, verify=verify_ssl, **kwargs)
    except ZeroReturnError as exc:
        import sys
        exc_tb = sys.exc_info()[2]
        six.reraise(SSLError, exc, exc_tb)
        del exc_tb
    if not response.encoding:
        response.encoding = 'utf-8'
    return response

def extract_response(raw_response):
    """Extract requests response object.

    only extract those status_code in [200, 300).

    :param raw_response: a requests.Resposne object.
    :return: content of response."""
    data = urlread(raw_response)
    if is_success_response(raw_response):
        return data
    elif is_failure_response(raw_response):
        raise RemoteExecuteError(data)
    elif is_invalid_response(raw_response):
        raise InvalidResponseError(data)
    else:
        raise UnknownStatusError(data)

def dispatch_webhook_request(url=None, method='GET', params=None, json=None, data=None, headers=None, timeout=5):
    """Task dispatching to an URL.

    :param url: The URL location of the HTTP callback task.
    :param method: Method to use when dispatching the callback. Usually
        `GET` or `POST`.
    :param params: Keyword arguments to pass on to the HTTP callback.
    :param json: JSON as body to pass on to the POST HTTP callback.
    :param headers: HTTP headers applied to callback."""
    if method == 'GET':
        resp = urlopen(url, method, params=params, headers=headers)
    elif method in ('POST', 'DELETE', 'PUT'):
        resp = urlopen(url, method, json=json, data=data, headers=headers)
    else:
        raise NotImplementedError
    return extract_response(resp)

