def delete_element_when_value_none(data_structure):
    """This method remove all entries in a Python dict when its value is None.
    :param data_structure: Python dict (lists are supported). e.i:
            [{"element1": "e1",
              "element2": {"element2.1": "e2",
                        "element2.2": None},
              "element3": "e3"},
            {"elementA": "eA",
             "elementB": {"elementB.1": None,
             "elementB2": ["a", "b"]}}]
    :return: None. The data_structure is modified"""
    if isinstance(data_structure, list):
        for element in data_structure:
            delete_element_when_value_none(element)
    elif isinstance(data_structure, dict):
        for element in data_structure.keys():
            if data_structure[element] is None:
                del data_structure[element]
            else:
                delete_element_when_value_none(data_structure[element])
                if len(data_structure[element]) == 0:
                    del data_structure[element]

def backup_file(*, file, host):
    """Backup a file on S3

    :param file: full path to the file to be backed up
    :param host: this will be used to locate the file on S3
    :raises TypeError: if an argument in kwargs does not have the type expected
    :raises ValueError: if an argument within kwargs has an invalid value"""
    if not _has_init:
        raise RuntimeError('This driver has not been properly initialised!')
    try:
        if not _dry_run:
            bucket = _boto_conn.get_bucket(_bucket_name)
    except boto.exception.S3ResponseError:
        log.msg_warn("Bucket '{bucket_name}' does not exist!, creating it...".format(bucket_name=_bucket_name))
        if not _dry_run:
            bucket = _boto_conn.create_bucket(_bucket_name)
        log.msg("Created bucket '{bucket}'".format(bucket=_bucket_name))
    key_path = '{key}/{file}'.format(key=host, file=ntpath.basename(file))
    if not _dry_run:
        k = boto.s3.key.Key(bucket)
        k.key = key_path
    log.msg("Uploading '{key_path}' to bucket '{bucket_name}' ...".format(key_path=key_path, bucket_name=_bucket_name))
    if not _dry_run:
        k.set_contents_from_filename(file, encrypt_key=True)
    log.msg("The file '{key_path}' has been successfully uploaded to S3!".format(key_path=key_path))

def _get_from_c_api():
    """dictproxy does exist in previous versions, but the Python constructor
    refuses to create new objects, so we must be underhanded and sneaky with
    ctypes."""
    from ctypes import pythonapi, py_object
    PyDictProxy_New = pythonapi.PyDictProxy_New
    PyDictProxy_New.argtypes = (py_object,)
    PyDictProxy_New.restype = py_object
    class dictproxy(object):
        """Read-only proxy for a dict, using the same mechanism Python uses for
        the __dict__ attribute on objects.

        Create with dictproxy(some_dict).  The original dict is still
        read/write, and changes to the original dict are reflected in real time
        via the proxy, but the proxy cannot be edited in any way."""
        def __new__(cls, d):
            if not isinstance(d, dict):
                raise TypeError('dictproxy can only proxy to a real dict')
            return PyDictProxy_New(d)
    dictproxy(dict())
    return _add_isinstance_tomfoolery(dictproxy)

def cache_hash(*a, **kw):
    """Try to hash an arbitrary object for caching."""
    def cache_str(o):
        if isinstance(o, (types.FunctionType, types.BuiltinFunctionType, types.MethodType, types.BuiltinMethodType, types.UnboundMethodType)):
            return getattr(o, 'func_name', 'func')
        if isinstance(o, dict):
            o = [k + ':' + cache_str(v) for k, v in o.items()]
        if isinstance(o, (list, tuple, set)):
            o = sorted(map(cache_str, o))
            o = '|'.join(o)
        if isinstance(o, basestring):
            return o
        if hasattr(o, 'updated_at'):
            return cache_str((repr(o), o.updated_at))
        return repr(o)
    hash = cache_str((a, kw)).encode('utf-8')
    return sha1(hash).hexdigest()

