def hmac(key, message, tag=None, alg=hashlib.sha256):
    """Generates a hashed message authentication code (HMAC) by prepending the
    specified @tag string to a @message, then hashing with to HMAC
    using a cryptographic @key and hashing @alg -orithm."""
    return HMAC.new(str(key), str(tag) + str(message), digestmod=alg).digest()

def minmax(low, high):
    """Test that the data items fall within range: low <= x <= high."""
    def decorator(function):
        """Decorate a function with args."""
        @functools.wraps(function)
        def wrapper(*args, **kwargs):
            """Wrap the function."""
            series = function(*args, **kwargs)
            lo_pass = low <= series
            hi_pass = series <= high
            return lo_pass & hi_pass
        return wrapper
    return decorator

def choice(choices):
    """Test that the data items are members of the set `choices`."""
    def decorator(function):
        """Decorate a function with args."""
        @functools.wraps(function)
        def wrapper(*args, **kwargs):
            """Wrap the function."""
            series = function(*args, **kwargs)
            return series.isin(set(choices))
        return wrapper
    return decorator

def bounded_length(low, high=None):
    """Test that the length of the data items fall within range: low <= x <= high.

    If high is None, treat as exact length."""
    def decorator(function):
        """Decorate a function with args."""
        @functools.wraps(function)
        def wrapper(*args, **kwargs):
            """Wrap the function."""
            series = function(*args, **kwargs)
            if high is None:
                return series.apply(lambda x: len(x) == low)
            else:
                lo_pass = series.apply(lambda x: low <= len(x))
                hi_pass = series.apply(lambda x: len(x) <= high)
                return lo_pass & hi_pass
        return wrapper
    return decorator

