def get_implemented_interfaces(cls):
    """Returns a set of :term:`interfaces <interface>` declared as implemented by
    class `cls`."""
    if hasattr(cls, '__interfaces__'):
        return cls.__interfaces__
    return six.moves.reduce(lambda x, y: x.union(y), map(get_implemented_interfaces, inspect.getmro(cls)[1:]), set())

def isimplementation(obj, interfaces):
    """Returns `True` if `obj` is a class implementing all of `interfaces` or an
    instance of such class.

    `interfaces` can be a single :term:`interface` class or an iterable of
    interface classes."""
    if not inspect.isclass(obj):
        isimplementation(obj.__class__, interfaces)
    if not isinstance(interfaces, collections.Iterable):
        interfaces = [interfaces]
    return frozenset(interfaces).issubset(get_implemented_interfaces(obj))

def mrc_to_marc(mrc):
    """Convert MRC data format to MARC XML.

    Args:
        mrc (str): MRC as string.

    Returns:
        str: XML with MARC."""
    lines = [line for line in mrc.splitlines() if line.strip()]
    def split_to_parts(lines):
        for line in lines:
            first_part, second_part = line.split(' L ', 1)
            yield (line, first_part, second_part.lstrip())
    control_lines = []
    data_lines = []
    for line, first_part, second_part in split_to_parts(lines):
        if second_part.startswith('$'):
            data_lines.append(line)
        else:
            control_lines.append(line)
    record = MARCXMLRecord()
    record.oai_marc = True
    for line, descr, content in split_to_parts(control_lines):
        record.controlfields[descr.strip()[:3]] = content
    def get_subfield_dict(line):
        fields = ((field[0], field[1:]) for field in line.split('$$')[1:])
        fields_dict = defaultdict(list)
        for key, val in fields:
            fields_dict[key].append(val)
        return fields_dict
    for line, descr, content_line in split_to_parts(data_lines):
        name = descr[:3]
        i1 = descr[3]
        i2 = descr[4]
        record.add_data_field(name, i1, i2, get_subfield_dict(content_line))
    return record.to_XML()

def item_to_mrc(code, val):
