def load_toolbar_item(import_path, *args, **kwargs):
    """Load an item in the toolbar
    :param import_path: the dotted python path to class or function.
    :param args: For classes, any arguments to pass to the constructor.
    :param kwargs: For classes, any keyword arguments to pass to the constructor."""
    if isinstance(import_path, (tuple, list)):
        children = [load_toolbar_item(path) for path in import_path]
        return Group(*children)
    elif isinstance(import_path, basestring):
        symbol = _import_symbol(import_path, 'STAFF_TOOLBAR_ITEMS')
    else:
        symbol = import_path
    if inspect.isclass(symbol):
        symbol = symbol(*args, **kwargs)
    if not callable(symbol):
        raise ImproperlyConfigured('The {0} in {1} is not callable!'.format(import_path, 'STAFF_TOOLBAR_ITEMS'))
    return symbol

def _import_symbol(import_path, setting_name):
    """Import a class or function by name."""
    mod_name, class_name = import_path.rsplit('.', 1)
    try:
        mod = import_module(mod_name)
        cls = getattr(mod, class_name)
    except ImportError as e:
        __, __, exc_traceback = sys.exc_info()
        frames = traceback.extract_tb(exc_traceback)
        if len(frames) > 1:
            raise
        raise ImproperlyConfigured('{0} does not point to an existing class: {1}'.format(setting_name, import_path))
    except AttributeError:
        raise ImproperlyConfigured('{0} does not point to an existing class: {1}'.format(setting_name, import_path))
    return cls

def construct(args):
    """Construct a queue-name from a set of arguments and a delimiter"""
    name = u''
    delimiter, encodeseq = delimiter_encodeseq(_c.FSQ_DELIMITER, _c.FSQ_ENCODE, _c.FSQ_CHARSET)
    if len(args) == 0:
        return delimiter
    for arg in args:
        name = delimiter.join([name, encode(coerce_unicode(arg, _c.FSQ_CHARSET), delimiter=delimiter, encodeseq=encodeseq)])
    return name

def deconstruct(name):
    """Deconstruct a queue-name to a set of arguments"""
    name = coerce_unicode(name, _c.FSQ_CHARSET)
    new_arg = sep = u''
    args = []
    if 1 > len(name):
        raise FSQMalformedEntryError(errno.EINVAL, u'cannot derive delimiterfrom: {0}'.format(name))
    delimiter, encodeseq = delimiter_encodeseq(name[0], _c.FSQ_ENCODE, _c.FSQ_CHARSET)
    if 1 == len(name):
        return (delimiter, args)
    encoding_trg = sep
    for c in name[1:]:
        if 3 == len(encoding_trg):
            encoding_trg = sep
        if c == encodeseq or len(encoding_trg):
            encoding_trg = sep.join([encoding_trg, c])
        elif c == delimiter:
            args.append(decode(new_arg, delimiter=delimiter, encodeseq=encodeseq))
            new_arg = sep
            continue
        new_arg = sep.join([new_arg, c])
    args.append(decode(new_arg, delimiter=delimiter, encodeseq=encodeseq))
    return (delimiter, args)

def tabulate_body(obj, level_keys, v_level_indexes, h_level_indexes, v_level_sort_keys=None, h_level_sort_keys=None):
    """Args:
        v_level_indexes: A sequence of level indexes.
        h_level_indexes: A sequence of level indexes."""
    v_key_sorted = make_sorter(v_level_sort_keys, v_level_indexes)
    h_key_sorted = make_sorter(h_level_sort_keys, h_level_indexes)
    h_level_keys = [level_keys[level] for level in h_level_indexes]
    v_level_keys = [level_keys[level] for level in v_level_indexes]
    h_key_tuples = h_key_sorted(product(*h_level_keys))
    v_key_tuples = v_key_sorted(product(*v_level_keys))
    h_size = len(h_key_tuples)
    v_size = len(v_key_tuples)
    table = [[MISSING for _ in range(h_size)] for _ in range(v_size)]
    for h_index, h_keys in enumerate(h_key_tuples):
        for v_index, v_keys in enumerate(v_key_tuples):
            key_path = [None] * len(level_keys)
            merge_into_by_index(key_path, h_level_indexes, h_keys)
            merge_into_by_index(key_path, v_level_indexes, v_keys)
            for v_level, v_key in zip(v_level_indexes, v_keys):
                key_path[v_level] = v_key
            item = obj
            for key in key_path:
                try:
                    item = item[key]
                except (IndexError, KeyError):
                    break
            else:
                table[v_index][h_index] = item
    return (table, v_key_tuples, h_key_tuples)

