def formatPoint(point, affine):
    """Retrieves a string representation of @point"""
    if affine:
        fmt = '\tx:{}\n\ty:{}'
        coords = [point.x, point.y]
    else:
        fmt = '\tx:{}\n\ty:{}\n\tz:{}'
        coords = [point.x, point.y, point.z]
    coordText = map(hexString, coords)
    return fmt.format(*coordText)

def serializeEc(P, compress=True):
    """Generates a compact binary version of this point."""
    return _serialize(P, compress, librelic.ec_size_bin_abi, librelic.ec_write_bin_abi)

def find_templates():
    """Load python modules from templates directory and get templates list

    :return: list of tuples (pairs):
             [(compiled regex, lambda regex_match: return message_data)]"""
    templates = []
    templates_directory = inspect.getsourcefile(lambda: 0).rstrip('__init__.py') + 'templates'
    template_files = os.listdir(templates_directory)
    for template_file in template_files:
        if template_file.startswith('.') or not template_file.endswith('.py'):
            continue
        try:
            template_module = importlib.import_module('templates.{}'.format(template_file.rstrip('.py')))
        except ImportError:
            template_module = importlib.import_module('ross.templates.{}'.format(template_file.rstrip('.py')))
        for name, content in template_module.__dict__.items():
            if name.endswith('templates'):
                for regex_text, data_func in content:
                    templates.append((re.compile(regex_text, re.IGNORECASE), data_func))
    return templates

def find_divisors(n):
    """Find all the positive divisors of the given integer n.

    Args:
        n (int): strictly positive integer

    Returns:
        A generator of all the positive divisors of n

    Raises:
        TypeError: if n is not an integer
        ValueError: if n is negative"""
    if not isinstance(n, int):
        raise TypeError('Expecting a strictly positive integer')
    if n <= 0:
        raise ValueError('Expecting a strictly positive integer')
    for i in range(1, int(n ** 0.5) + 1):
        if n % i == 0:
            divisors = {i, n // i}
            for divisor in divisors:
                yield divisor

def sieve_of_eratosthenes(p_min=2, p_max=None):
    """Generator of prime numbers using the sieve of Eratosthenes.

    Note:
        Adapted from http://code.activestate.com/recipes/117119/

    Args:
        p_min (int): prime numbers lower than p_min will not be in the resulting primes
        p_max (int): the generator will stop when this value is reached, it means that there
            will be no prime bigger than this number in the resulting primes. If p_max
            is None, there will not be any upper limit

    Returns:
        A generator of all the consecutive primes between p_min and p_max

    Raises:
        TypeError: if p_min or p_max is not an integer"""
    if not isinstance(p_min, int):
        raise TypeError('Expecting an integer')
    if p_max is not None and (not isinstance(p_max, int)):
        raise TypeError('Expecting an integer')
    sieve = {}
    q = 2
    while p_max is None or q <= p_max:
        if q not in sieve:
            if q >= p_min:
                yield q
            sieve[q * q] = [q]
        else:
            for p in sieve[q]:
                sieve.setdefault(p + q, []).append(p)
            del sieve[q]
        q += 1

def eulers_totient(n):
    """Calculate the value of Euler's totient for a given integer

    Args:
        n (int): strictly positive integer

    Returns:
        The value of Euler's totient for n

    Raises:
        TypeError: If either n or k is not an integer
        ValueError: If either n or k is negative, or if k is strictly greater than n"""
    if not isinstance(n, int):
        raise TypeError('Expecting a strictly positive integer')
    if n <= 0:
        raise ValueError('Expecting a strictly positive integer')
    if n == 1:
        return 1
    result = 0
    for i in range(1, n):
        if gcd(i, n) == 1:
            result += 1
    return result

