def format_config(data, env):
    """Format data with given env.

    :param data: a string/integer/float/boolean/list/dict object.
    :param env: a dictionary.
    :return: return formatted data.

    `format_config` will try to format strings contained env placeholder `{{ ENV_KEY }}`.

    If `ENV_KEY` does not exist in env, then this function will trhow assertion error."""
    if isinstance(data, list):
        return [format_config(datum, env) for datum in data]
    elif isinstance(data, dict):
        return {format_config(key, env): format_config(value, env) for key, value in data.items()}
    elif isinstance(data, str):
        def replace(match):
            var_name = match.group(1)
            var = env.get(var_name)
            assert var, 'Variable %s undefined.' % var_name
            return var
        return ENV_PLACEHODLER.sub(replace, data)
    else:
        return data

def execute_side_effect(side_effect=UNDEFINED, args=UNDEFINED, kwargs=UNDEFINED):
    """Executes a side effect if one is defined.

    :param side_effect: The side effect to execute
    :type side_effect: Mixed. If it's an exception it's raised. If it's callable it's called with teh parameters.
    :param tuple args: The arguments passed to the stubbed out method
    :param dict kwargs: The kwargs passed to the subbed out method.

    :rtype: mixed
    :returns: Whatever the passed side_effect returns
    :raises: Whatever error is defined as the side_effect"""
    if args == UNDEFINED:
        args = tuple()
    if kwargs == UNDEFINED:
        kwargs = {}
    if isinstance(side_effect, (BaseException, Exception, StandardError)):
        raise side_effect
    elif hasattr(side_effect, '__call__'):
        return side_effect(*args, **kwargs)
    else:
        raise Exception("Caliendo doesn't know what to do with your side effect. {0}".format(side_effect))

def get_context(method):
    """Gets a context for a target function.

    :rtype: caliendo.hooks.Context
    :returns: The context for the call. Patches are applied and removed within a context."""
    if Context.exists(method):
        return Context.increment(method)
    else:
        return Context(method)

def replay(import_path):
    """Replays calls to a method located at import_path. These calls must occur after the start of a method for which there is a cache hit. E.g. after a method patched with patch() or cached with cache()

    :param str import_path: The absolute import path for the method to monitor and replay as a string.

    :rtype: function
    :returns: The decorated method with all existing references to the target replaced with a recorder to replay it"""
    def patch_method(unpatched_method):
        context = get_context(unpatched_method)
        recorder = get_recorder(import_path, context)
        @patch(import_path, side_effect=recorder, ctxt=context)
        def patched_method(*args, **kwargs):
            try:
                return unpatched_method(*args, **kwargs)
            finally:
                context.exit()
        patched_method.__context = context
        return patched_method
    return patch_method

def start_in_oneshot_processes(obj, nb_process):
    """Start nb_process processes to do the job. Then process finish the job they die."""
    processes = []
    for i in range(nb_process):
        p = Process(target=oneshot_in_process, args=(obj,))
        p.start()
        processes.append(p)
    for process in processes:
        process.join()

def start_in_keepedalive_processes(obj, nb_process):
    """Start nb_process and keep them alive. Send job to them multiple times, then close thems."""
    processes = []
    readers_pipes = []
    writers_pipes = []
    for i in range(nb_process):
        local_read_pipe, local_write_pipe = Pipe(duplex=False)
        process_read_pipe, process_write_pipe = Pipe(duplex=False)
        readers_pipes.append(local_read_pipe)
        writers_pipes.append(process_write_pipe)
        p = Process(target=run_keepedalive_process, args=(local_write_pipe, process_read_pipe, obj))
        p.start()
        processes.append(p)
    for job in range(3):
        print('send new job to processes:')
        for process_number in range(nb_process):
            writers_pipes[process_number].send(obj)
            reader_useds = []
        while readers_pipes:
            for r in wait(readers_pipes):
                try:
                    r.recv()
                except EOFError:
                    pass
                finally:
                    reader_useds.append(r)
                    readers_pipes.remove(r)
        readers_pipes = reader_useds
    for writer_pipe in writers_pipes:
        writer_pipe.send('stop')

def run_keepedalive_process(main_write_pipe, process_read_pipe, obj):
    """Procees who don't finish while job to do"""
    while obj != 'stop':
        oneshot_in_process(obj)
        main_write_pipe.send('job is done')
        readers = [process_read_pipe]
        while readers:
            for r in wait(readers):
                try:
                    obj = r.recv()
                except EOFError:
                    pass
                finally:
                    readers.remove(r)

def subn_filter(s, find, replace, count=0):
