def delimiter_encodeseq(delimiter, encodeseq, charset):
    """Coerce delimiter and encodeseq to unicode and verify that they are not
    the same"""
    delimiter = coerce_unicode(delimiter, charset)
    encodeseq = coerce_unicode(encodeseq, charset)
    if 1 != len(encodeseq):
        raise FSQEncodeError(errno.EINVAL, u'encode sequence must be 1 character, not {0}'.format(len(encodeseq)))
    if 1 != len(delimiter):
        raise FSQEncodeError(errno.EINVAL, u'delimiter must be 1 character, not {0}'.format(len(delimiter)))
    if delimiter == encodeseq:
        raise FSQEncodeError(errno.EINVAL, u'delimiter and encoding may not be the same: both: {0}'.format(encodeseq))
    try:
        delimiter.encode('ascii')
    except UnicodeEncodeError:
        raise FSQEncodeError(errno.EINVAL, u'delimiter must be ascii')
    try:
        encodeseq.encode('ascii')
    except UnicodeEncodeError:
        raise FSQEncodeError(errno.EINVAL, u'encodeseq must be ascii')
    return (delimiter, encodeseq)

def uid_gid(user, group, fd=None, path=None):
    """Get uid and gid from either uid/gid, user name/group name, or from the
    environment of the calling process, or optionally from an fd, or
    optionally from a path"""
    type_msg = u'{0} must be a string or integer, not: {1}'
    nosuch_msg = u'no such {0}: {1}'
    if fd is not None and path is not None:
        raise ValueError(u'received path and fd arguments, need one or neither, not both.')
    user = -1 if user is None else user
    group = -1 if group is None else group
    try:
        user = int(user)
    except (TypeError, ValueError):
        try:
            user = pwd.getpwnam(user).pw_uid
        except TypeError:
            raise TypeError(type_msg.format(u'user', user.__class__.__name__))
        except KeyError:
            raise FSQEnvError(errno.EINVAL, nosuch_msg.format(u'user', user))
    except TypeError:
        raise TypeError(type_msg.format(u'group', group.__class__.__name__))
    try:
        group = int(group)
    except ValueError:
        try:
            group = grp.getgrnam(group).gr_gid
        except TypeError:
            raise TypeError(type_msg.format(u'group', group.__class__.__name__))
        except KeyError:
            raise FSQEnvError(errno.EINVAL, nosuch_msg.format(u'group', group))
    except TypeError:
        raise TypeError(type_msg.format(u'group', group.__class__.__name__))
    return (user, group)

def wrap_io_os_err(e):
    """Formats IO and OS error messages for wrapping in FSQExceptions"""
    msg = ''
    if e.strerror:
        msg = e.strerror
    if e.message:
        msg = ' '.join([e.message, msg])
    if e.filename:
        msg = ': '.join([msg, e.filename])
    return msg

def check_ttl_max_tries(tries, enqueued_at, max_tries, ttl):
    """Check that the ttl for an item has not expired, and that the item has
    not exceeded it's maximum allotted tries"""
    if max_tries > 0 and tries >= max_tries:
        raise FSQMaxTriesError(errno.EINTR, u'Max tries exceded: {0} ({1})'.format(max_tries, tries))
    if ttl > 0 and datetime.datetime.now() < enqueued_at + datetime.timedelta(seconds=ttl):
        raise FSQTTLExpiredError(errno.EINTR, u'TTL Expired: {0}'.format(ttl))

def datetime_from_iso8601(date):
    """Small helper that parses ISO-8601 date dates.

    >>> datetime_from_iso8601("2013-04-10T12:52:39")
    datetime.datetime(2013, 4, 10, 12, 52, 39)
    >>> datetime_from_iso8601("2013-01-07T12:55:19.257")
    datetime.datetime(2013, 1, 7, 12, 55, 19, 257000)"""
    format = ISO8610_FORMAT
    if date.endswith('Z'):
        date = date[:-1]
    if re.match('.*\\.\\d+', date):
        format = ISO8610_FORMAT_MICROSECONDS
    return datetime.datetime.strptime(date, format)

def get(url, last_modified=None):
    """Performs a get request to a given url. Returns an empty str on error.
    """
    try:
        with closing(urllib2.urlopen(url)) as page:
            if last_modified is not None:
                last_mod = dateutil.parser.parse(dict(page.info())['last-modified'])
                if last_mod <= last_modified:
                    return ''
            return page.read()
    except urllib2.URLError:
        return ''

