def filter_macro(func, *args, **kwargs):
    """Promotes a function that returns a filter into its own filter type.

    Example::

        @filter_macro
        def String():
            return Unicode | Strip | NotEmpty

        # You can now use `String` anywhere you would use a regular Filter:
        (String | Split(':')).apply('...')

    You can also use ``filter_macro`` to create partials, allowing you to
    preset one or more initialization arguments::

        Minor = filter_macro(Max, max_value=18, inclusive=False)
        Minor(inclusive=True).apply(18)"""
    filter_partial = partial(func, *args, **kwargs)
    class FilterMacroMeta(FilterMeta):
        @staticmethod
        def __new__(mcs, name, bases, attrs):
            for attr in WRAPPER_ASSIGNMENTS:
                if hasattr(func, attr):
                    attrs[attr] = getattr(func, attr)
            return super(FilterMacroMeta, mcs).__new__(mcs, func.__name__, bases, attrs)
        def __call__(cls, *runtime_args, **runtime_kwargs):
            return filter_partial(*runtime_args, **runtime_kwargs)
    class FilterMacro(with_metaclass(FilterMacroMeta, FilterMacroType)):
        def _apply(self, value):
            return self.__class__()._apply(value)
    return FilterMacro

def verify(info, directory_path):
    """Return True if the checksum values in the torrent file match the
    computed checksum values of downloaded file(s) in the directory and if
    each file has the correct length as specified in the torrent file."""
    base_path = os.path.join(directory_path, info['name'])
    if 'length' in info:
        if os.stat(base_path).st_size != info['length']:
            return False
        getfile = lambda: open(base_path, 'rb')
    else:
        assert 'files' in info, 'invalid torrent file'
        for f in info['files']:
            p = os.path.join(base_path, *f['path'])
            if os.stat(p).st_size != f['length']:
                return False
        getfile = lambda: ConcatenatedFile(base_path, info['files'])
    with getfile() as f:
        return compare_checksum(info, f)

def compare_checksum(info, f):
    """Return True if the checksum values in the info dictionary match the
    computed checksum values of file content."""
    pieces = info['pieces']
    def getchunks(f, size):
        while True:
            chunk = f.read(size)
            if chunk == '':
                break
            yield hashlib.sha1(chunk).digest()
    calc = getchunks(f, info['piece length'])
    ref = (pieces[i:i + 20] for i in xrange(0, len(pieces), 20))
    for expected, actual in itertools.izip(calc, ref):
        if expected != actual:
            return False
    return ensure_empty(calc) and ensure_empty(ref)

def configure_logging(level):
    """Configure global log level to given one
    :param level: Level (INFO | DEBUG | WARN | ERROR)
    :return:"""
    global logging_level
    logging_level = logging.ERROR
    if 'info' == level.lower():
        logging_level = logging.INFO
    elif 'warn' == level.lower():
        logging_level = logging.WARNING
    elif 'debug' == level.lower():
        logging_level = logging.DEBUG

def _get_pretty_body(headers, body):
    """Return a pretty printed body using the Content-Type header information
    :param headers: Headers for the request/response (dict)
    :param body: Body to pretty print (string)
    :return: Body pretty printed (string)"""
    if HEADER_CONTENT_TYPE in headers:
        if HEADER_REPRESENTATION_XML == headers[HEADER_CONTENT_TYPE]:
            xml_parsed = parseString(body)
            pretty_xml_as_string = xml_parsed.toprettyxml()
            return pretty_xml_as_string
        elif HEADER_REPRESENTATION_JSON in headers[HEADER_CONTENT_TYPE]:
            parsed = json.loads(body)
            return json.dumps(parsed, sort_keys=True, indent=4)
        else:
            return body
    else:
        return body

