def replace_each(text, items, count=None, strip=False):
    """Like ``replace``, where each occurrence in ``items`` is a 2-tuple of
    ``(old, new)`` pair."""
    for a, b in items:
        text = replace(text, a, b, count=count, strip=strip)
    return text

def remove_each(text, items, count=None, strip=False):
    """Like ``remove``, where each occurrence in ``items`` is ``what`` to remove."""
    for item in items:
        text = remove(text, item, count=count, strip=strip)
    return text

def matches(text, what):
    """Check if ``what`` occurs in ``text``"""
    return text.find(what) > -1 if is_string(what) else what.match(text)

def find_first(data, what):
    """Search for ``what`` in the iterable ``data`` and return the index of the
    first match. Return ``None`` if no match found."""
    for i, line in enumerate(data):
        if contains(line, what):
            return i
    return None

def progbar(iterable, *a, verbose=True, **kw):
    """Prints a progress bar as the iterable is iterated over

    :param iterable: The iterator to iterate over
    :param a: Arguments to get passed to tqdm (or tqdm_notebook, if in a Jupyter notebook)
    :param verbose: Whether or not to print the progress bar at all
    :param kw: Keyword arguments to get passed to tqdm
    :return: The iterable that will report a progress bar"""
    iterable = range(iterable) if isinstance(iterable, int) else iterable
    if verbose:
        return _tqdm(iterable, *a, **kw)
    else:
        return iterable

def xdg_compose(to, subject, body=None, cc=None, bcc=None):
    """Use xdg-email to compose in an X environment.

    Needs xdg-utils and a running X session. Works with GNOME, KDE,
    MATE, XFCE, ..."""
    command = ['xdg-email', '--utf8', '--subject', subject]
    if body:
        command += ['--body', body]
    if cc:
        if type(cc) is list:
            cc = ', '.join(cc)
        command += ['--cc', cc]
    if bcc:
        if type(bcc) is list:
            bcc = ', '.join(bcc)
        command += ['--bcc', bcc]
    if type(to) is list:
        to = ', '.join(to)
    command.append(to)
    return subprocess.call(command)

def safe_size_check(checked_path, error_detail, max_bytes=500000000):
    """Determines if a particular path is larger than expected. Useful before any recursive remove."""
    actual_size = 0
    for dirpath, dirnames, filenames in os.walk(checked_path):
        for f in filenames:
            fp = os.path.join(dirpath, f)
            actual_size += os.path.getsize(fp)
    assert actual_size <= max_bytes, 'Path {} size of {} >= {} bytes. {}'.format(checked_path, actual_size, max_bytes, error_detail)

