def _season_overflow(season, moved_year, now):
    """Pushes illegal seasons ints into the next/previous year."""
    if season > 4:
        while season > 4:
            if moved_year is None:
                moved_year = now.year + 1
            else:
                moved_year += 1
            season -= 5
    elif season < 0:
        while season < 0:
            if moved_year is None:
                moved_year = now.year - 1
            else:
                moved_year -= 1
            season += 5
    return (season, moved_year)

