def coerceBigInt(x):
    """Retrieves a BigInt from @x or returns None if @x is not a type that can be
    converted."""
    if isinstance(x, BigInt):
        return x
    elif isinstance(x, (long, int)):
        return BigInt(x)
    else:
        return None

def inverse(x, p, errorOnFail=False):
    """Find the inverse of BigInt @x in a field of (prime) order @p."""
    assertType(x, BigInt)
    gcd = BigInt()
    inv = BigInt()
    librelic.bn_gcd_ext_lehme(byref(gcd), byref(inv), None, byref(x), byref(p))
    if gcd != 1:
        if errorOnFail:
            raise Exception('Cannot find an inverse. gcd(x,p) == {}, but we need gcd(x,p) == 1 to find an inverse.'.format(long(gcd)))
        else:
            return None
    return inv

def randomZ(maximum=None, bits=256):
    """Retrieve a random BigInt.
    @maximum: If specified, the value will be no larger than this modulus.
    @bits: If no maximum is specified, the value will have @bits."""
    result = BigInt()
    if maximum:
        maximum = coerceBigInt(maximum)
        librelic.bn_rand_mod(byref(result), byref(maximum))
    else:
        librelic.bn_rand_abi(byref(result), BigInt.POSITIVE_FLAG, c_int(bits))
    return result

def emit_event(project_slug, action_slug):
    """Publish message to action.

    Rio will trigger all registered webhooks related to this action and
    trace running process."""
    if request.headers.get('Content-Type') == 'application/json':
        payload = request.get_json()
    elif request.method == 'POST':
        payload = request.form.to_dict()
    else:
        payload = request.args.to_dict()
    if not request.authorization:
        return (jsonify({'message': 'unauthorized'}), 401)
    sender_name = request.authorization.username
    sender_secret = request.authorization.password
    event_uuid = request.headers.get('X-Rio-Event-UUID') or request.headers.get('X-B3-TraceId')
    data = _emit_event(project_slug, action_slug, payload, sender_name, sender_secret, event_uuid=event_uuid)
    data['message'] = 'ok'
    event_received.send(None, project_slug=project_slug, data=data)
    return jsonify(data)

def strict_resolve(self, context, ignore_failures=False):
    """Resolves a ``FilterExpression`` within the context of the template.

    This patched method acts as a proxy to the original, but forces
    ``ignore_failures`` to False so that an exception is always raised when a
    variable is accessed out of scope/context."""
    return __orig_resolve(self, context, ignore_failures=False)

def debug_variable_node_render(self, context):
    """Like DebugVariableNode.render, but doesn't catch UnicodeDecodeError."""
    try:
        output = self.filter_expression.resolve(context)
        output = template_localtime(output, use_tz=context.use_tz)
        output = localize(output, use_l10n=context.use_l10n)
        output = force_text(output)
    except Exception as e:
        if not hasattr(e, 'django_template_source'):
            e.django_template_source = self.source
        raise
    if context.autoescape and (not isinstance(output, SafeData)) or isinstance(output, EscapeData):
        return escape(output)
    else:
        return output

def variable_node_render(self, context):
    """Like VariableNode.render, but doesn't catch UnicodeDecodeError."""
    output = self.filter_expression.resolve(context)
    return render_value_in_context(output, context)

def _log_unicode_errors(logger, log_level):
    """Catches/logs UnicodeDecodeError."""
    def log_debug_render(*args, **kwargs):
        try:
            return debug_variable_node_render(*args, **kwargs)
        except UnicodeDecodeError:
            logger.log(log_level, 'UnicodeDecodeError in template rendering', exc_info=True)
        return ''
    def log_render(*args, **kwargs):
        try:
            return variable_node_render(*args, **kwargs)
        except UnicodeDecodeError:
            logger.log(log_level, 'UnicodeDecodeError in template rendering', exc_info=True)
        return ''
    patch_base = patch.object(VariableNode, 'render', log_render)
    patch_all = patch_base
    if django.VERSION < (1, 9):
        from django.template.debug import DebugVariableNode
        patch_debug = patch.object(DebugVariableNode, 'render', log_debug_render)
        patch_all = _compose(patch_all, patch_debug)
    return lambda f: patch_all(f)

def fail_on_template_errors(f, *args, **kwargs):
    """Decorator that causes templates to fail on template errors."""
    decorators = [_fail_template_string_if_invalid, _always_strict_resolve, _disallow_catching_UnicodeDecodeError]
    if django.VERSION < (1, 8):
        decorators.append(_patch_invalid_var_format_string)
    return reduce(__apply, decorators, f)(*args, **kwargs)

def log_template_errors(logger, log_level=logging.ERROR):
    """Decorator to log template errors to the specified logger.

    @log_template_errors(logging.getLogger('mylogger'), logging.INFO)
    def my_view(*args):
        pass

    Will log template errors at INFO.  The default log level is ERROR."""
    if not (isinstance(log_level, int) and log_level in logging._levelNames):
        raise ValueError('Invalid log level %s' % log_level)
    decorators = [_log_template_string_if_invalid(logger, log_level), _log_unicode_errors(logger, log_level), _always_strict_resolve]
    if django.VERSION < (1, 8):
        decorators.append(_patch_invalid_var_format_string)
    @decorator
    def function(f, *args, **kwargs):
        return reduce(__apply, decorators, f)(*args, **kwargs)
    return function

