def mementoweb_api_tags(url):
    """Parse list of :class:`TimeResource` objects based on the mementoweb.org.

    Args:
        url (str): Any url.

    Returns:
        list: :class:`TimeResource` objects."""
    memento_url = 'http://labs.mementoweb.org/timemap/json/'
    r = requests.get(memento_url + url)
    if r.status_code != 200:
        return []
    data = r.json().get('mementos', {}).get('list', [])
    if not data:
        return []
    resources = (TimeResource(url=item.get('uri', ''), date=item.get('datetime', ''), val=item.get('datetime', '').split('-')[0], source='MementoWeb.org') for item in data)
    resource_dict = {res.val: res for res in resources}
    return sorted(resource_dict.values(), key=lambda x: x.val)

def get_Name(name, short=False):
    """Return the distinguished name of an X509 Certificate

    :param name: Name object to return the DN from
    :param short: Use short form (Default: False)

    :type name: :class:`cryptography.x509.Name`
    :type short: Boolean

    :rtype: str"""
    sf = {'countryName': 'C', 'stateOrProvinceName': 'ST', 'localityName': 'L', 'organizationalUnitName': 'OU', 'organizationName': 'O', 'commonName': 'CN', 'emailAddress': 'E'}
    return ', '.join(['{}={}'.format(attr.oid._name if not short or attr.oid._name not in sf else sf[attr.oid._name], attr.value) for attr in name])

def extract_view(view, decorators=None):
    """Extract a view object out of any wrapping decorators."""
    if decorators is None:
        decorators = []
    if getattr(view, 'func_closure', None) is not None:
        decorators.append(view)
        for closure in view.func_closure:
            if callable(closure.cell_contents):
                return extract_view(closure.cell_contents, decorators)
    if inspect.isfunction(view) or inspect.ismethod(view):
        pass
    elif inspect.isclass(view):
        pass
    else:
        view = view.__class__
    return (view, decorators)

def get_decorators(func):
    """Return a list of decorator names for this function."""
    decorators = []
    tree = ast.parse(inspect.getsource(func))
    for node in ast.iter_child_nodes(tree):
        for dnode in node.decorator_list:
            if isinstance(dnode, ast.Name):
                decorator = func.func_globals[dnode.id]
            elif isinstance(dnode, ast.Attribute):
                module = func.func_globals[dnode.value.id]
                decorator = getattr(module, dnode.attr)
            else:
                raise Exception('Unable to handle decorator node: %s' % dnode)
            decorators.append(decorator)
    return decorators

