def tree(path, depth=2, topdown=True, followlinks=False, showhidden=False):
    """A generator return a tuple with three elements (root, dirs, files)."""
    rt = []
    for root, dirs, files in os.walk(path, topdown=topdown, followlinks=followlinks):
        if not showhidden and File.is_hidden(root):
            continue
        current_depth = len(os.path.relpath(root, path).split(os.sep))
        if current_depth > depth:
            continue
        if showhidden:
            _tuple = (root, [File(os.path.join(root, _dir)) for _dir in dirs], [File(os.path.join(root, _file)) for _file in files])
        else:
            _tuple = (root, [File(os.path.join(root, _dir)) for _dir in dirs if _dir[0] != '.'], [File(os.path.join(root, _file)) for _file in files if _file[0] != '.'])
        rt.append(_tuple)
    return rt

def done(item, done_type=None, max_tries=None, ttl=None):
    """Wrapper for any type of finish, successful, permanant failure or
    temporary failure"""
    if done_type is None or done_type == _c.FSQ_SUCCESS:
        return success(item)
    return fail(item, fail_type=done_type, max_tries=max_tries, ttl=ttl)

def fail(item, fail_type=None, max_tries=None, ttl=None):
    """Fail a work item, either temporarily or permanently"""
    if fail_type is not None and fail_type == _c.FSQ_FAIL_TMP:
        return fail_tmp(item, max_tries=max_tries, ttl=ttl)
    return fail_perm(item)

def main(argv=None):
    """Main entry point for the cdstar CLI."""
    args = docopt(__doc__, version=pycdstar.__version__, argv=argv, options_first=True)
    subargs = [args['<command>']] + args['<args>']
    if args['<command>'] in ['help', None]:
        cmd = None
        if len(subargs) > 1:
            cmd = COMMANDS.get(subargs[1])
        if cmd:
            print(cmd.__doc__)
        else:
            print(__doc__)
        return 0
    cmd = COMMANDS.get(args['<command>'])
    if not cmd:
        print('unknown command')
        print(__doc__)
        return 0
    cfg = Config(**dict(cfg=args.pop('--cfg', None), url=args.pop('--service', None), user=args.pop('--user', None), password=args.pop('--password', None)))
    try:
        res = cmd(Cdstar(cfg=cfg), docopt(cmd.__doc__, argv=subargs), verbose=args.get('--verbose'))
        if isinstance(res, types.GeneratorType):
            res = list(res)
        if isinstance(res, list):
            for line in res:
                print(line)
            res = 0
        return res or 0
    except:
        return 256

def jsonload(path, **kw):
