def const(const):
    """Convenience wrapper to yield the value of a constant"""
    try:
        return getattr(_c, const)
    except AttributeError:
        raise FSQEnvError(errno.EINVAL, u'No such constant: {0}'.format(const))
    except TypeError:
        raise TypeError(errno.EINVAL, u'const name must be a string or unicode object, not: {0}'.format(const.__class__.__name__))

def set_const(const, val):
    """Convenience wrapper to reliably set the value of a constant from
    outside of package scope"""
    try:
        cur = getattr(_c, const)
    except AttributeError:
        raise FSQEnvError(errno.ENOENT, u'no such constant: {0}'.format(const))
    except TypeError:
        raise TypeError(errno.EINVAL, u'const name must be a string or unicode object, not: {0}'.format(const.__class__.__name__))
    should_be = cur.__class__
    try:
        if not isinstance(val, should_be):
            if should_be is unicode or cur is None:
                val = coerce_unicode(val, _c.FSQ_CHARSET)
            elif should_be is int and const.endswith('MODE'):
                val = int(val, 8)
            elif isinstance(cur, numbers.Integral):
                val = int(val)
            else:
                should_be(val)
    except (TypeError, ValueError):
        raise FSQEnvError(errno.EINVAL, u'invalid type for constant {0}, should be {1}, not: {2}'.format(const, should_be.__name__, val.__class__.__name__))
    setattr(_c, const, val)
    return val

def func_on_enter(func):
    """Register the `func` as a callback reacting only to ENTER.

    Note:
        This function doesn't bind the key to the element, just creates sort of
        filter, which ignores all other events."""
    def function_after_enter_pressed(ev):
        ev.stopPropagation()
        if ev.keyCode == 13:
            func(ev)
    return function_after_enter_pressed

def clone(item, exclude=None, update=None):
    """Return a clone of the SQLA object.

    :param item: The SQLA object to copy the attributes from.
    :param exclude: If provided, should be an iterable that contains the names
        attributes to exclude from the copy. The attributes `created_at` and
        `id` are always excluded.
    :param update: If provided, should be a mapping of attribute name, to the
        value that should be set."""
    if not exclude:
        exclude = set()
    if not isinstance(exclude, set):
        exclude = set(exclude)
    exclude.update(('created_at', 'id'))
    attrs = {x: getattr(item, x) for x in item.__mapper__.columns.keys() if x not in exclude}
    if update:
        attrs.update(update)
    return item.__class__(**attrs)

