def long2str(l):
    """Convert an integer to a string."""
    if type(l) not in (types.IntType, types.LongType):
        raise ValueError('the input must be an integer')
    if l < 0:
        raise ValueError('the input must be greater than 0')
    s = ''
    while l:
        s = s + chr(l & 255)
        l >>= 8
    return s

def str2long(s):
    """Convert a string to a long integer."""
    if type(s) not in (types.StringType, types.UnicodeType):
        raise ValueError('the input must be a string')
    l = 0
    for i in s:
        l <<= 8
        l |= ord(i)
    return l

def is_android(filename):
    """Return the type of the file

    @param filename : the filename
    @rtype : "APK", "DEX", None"""
    if not filename:
        return None
    with open(filename, 'rb') as fd:
        f_bytes = fd.read()
        return is_android_raw(f_bytes)
    return None

def is_android_raw(raw):
    """Returns a string that describes the type of file, for common Android
    specific formats"""
    val = None
    if raw[0:2] == b'PK' and b'META-INF/MANIFEST.MF' in raw:
        val = 'APK'
    elif raw[0:3] == b'dex':
        val = 'DEX'
    elif raw[0:3] == b'dey':
        val = 'DEY'
    elif raw[0:4] == b'\x03\x00\x08\x00':
        val = 'AXML'
    elif raw[0:4] == b'\x02\x00\x0c\x00':
        val = b'ARSC'
    return val

def is_py_script(filename):
    """Returns True if a file is a python executable."""
    if not os.path.exists(filename) and os.path.isfile(filename):
        return False
    elif filename.endswith('.py'):
        return True
    elif not os.access(filename, os.X_OK):
        return False
    else:
        try:
            with open(filename, 'r') as fp:
                first_line = fp.readline().strip()
            return '#!' in first_line and 'python' in first_line
        except StopIteration:
            return False

def clean_bytecode_extension(filename):
    """Replaces Python bytecode extensions (``.pyc``) with their source extension."""
    path, extension = os.path.splitext(filename)
    if extension == '.pyc':
        filename = '%s.py' % path
    return filename

def catch_exception(exception, message=None):
    """A decorator that gracefully handles exceptions, exiting
    with :py:obj:`exit_codes.OTHER_FAILURE`."""
    def decorator(f):
        @click.pass_context
        def new_func(ctx, *args, **kwargs):
            try:
                return ctx.invoke(f, *args, **kwargs)
            except exception as e:
                message1 = message if message is not None else '{}'.format(e)
                click.echo(message1)
                ctx.exit(code=exit_codes.OTHER_FAILURE)
        return update_wrapper(new_func, f)
    return decorator

def ensure_obj(f):
    """A decorator that ensures context.obj exists. If it doesn't,
    a new dict() is created and stored as obj."""
    @click.pass_context
    def new_func(ctx, *args, **kwargs):
        if ctx.obj is None:
            ctx.obj = {}
        return ctx.invoke(f, *args, **kwargs)
    return update_wrapper(new_func, f)

def openfile(filename, mode='rt', *args, expanduser=False, expandvars=False, makedirs=False, **kwargs):
    """Open filename and return a corresponding file object."""
    if filename in ('-', None):
        return sys.stdin if 'r' in mode else sys.stdout
    if expanduser:
        filename = os.path.expanduser(filename)
    if expandvars:
        filename = os.path.expandvars(filename)
    if makedirs and ('a' in mode or 'w' in mode):
        parentdir = os.path.dirname(filename)
        if not os.path.isdir(parentdir):
            os.makedirs(parentdir)
    if filename.endswith('.gz'):
        if gzip is None:
            raise NotImplementedError
        _open = gzip.open
    elif filename.endswith('.bz2'):
        if bz2 is None:
            raise NotImplementedError
        _open = bz2.open
    elif filename.endswith('.xz') or filename.endswith('.lzma'):
        if lzma is None:
            raise NotImplementedError
        _open = lzma.open
    else:
        _open = open
    return _open(filename, mode, *args, **kwargs)

def process_analyses(analysis_system_instance, analysis_method, sleep_time):
    """Process all analyses which are scheduled for the analysis system instance.

    This function does not terminate on its own, give it a SIGINT or Ctrl+C to stop.

    :param analysis_system_instance: The analysis system instance for which the analyses are scheduled.
    :param analysis_method: A function or method which analyses a scheduled analysis. The function must not take further arguments.
    :param sleep_time: Time to wait between polls to the MASS server"""
    try:
        while True:
            for analysis_request in analysis_system_instance.get_scheduled_analyses():
                analysis_method(analysis_request)
            time.sleep(sleep_time)
    except KeyboardInterrupt:
        logging.debug('Shutting down.')
        return

def verifyGt(x, tTilde, y, pi, errorOnFail=True):
    """Verifies a zero-knowledge proof.
    @x: Blinded message, G1Element, x = HG1(m)*r
    @tTilde: hashed tweak, G2Element, t~ = HG2(t)
    @y: server response (intermediate result), GtElement
    @pi:  pi = (p, c, u), zero-knowledge proof from server,
      p = g^kw, GtElement; c,u integer values
    @errorOnFail: Rasise an exception if the proof does not hold."""
    p, c, u = pi
    assertType(x, G1Element)
    assertType(tTilde, G2Element)
    assertType(y, GtElement)
    assertType(p, GtElement)
    g = generatorGt()
    beta = pair(x, tTilde)
    t1 = g ** u * p ** c
    t2 = beta ** u * y ** c
    cPrime = hashZ(g, p, beta, y, t1, t2)
    if cPrime == c:
        return True
    if errorOnFail:
        raise Exception('zero-knowledge proof failed verification.')
    else:
        return False

def blind(m, hashfunc=hashG1):
    """Blinds an arbitrary string or byte array @m using an ephemeral key @r
    that can be used to deblind. Computes: x = H(x)^r
    @returns (1/r,x)"""
    rInv = None
    while not rInv:
        r = randomZ()
        rInv = inverse(r, orderGt())
    return (rInv, hashfunc(m) * r)

def _unwrap(x, deserializeFunc, decodeFunc=base64.urlsafe_b64decode, compress=True):
    """Unwraps an element @x by decoding and then deserializing"""
    return deserializeFunc(decodeFunc(x), compress)

def find_permission(permissions, permission_type, object_id=None, namespace=None):
    """Given a queryset of permissions, filters depending on the permission
    type, and optionally an object id and namespace."""
    if object_id is not None:
        return permissions.filter(type=permission_type, object_id=object_id, namespace=namespace)
    return permissions.filter(type=permission_type)

def decode(arg, delimiter=None, encodeseq=None):
    """Decode a single argument from the file-system"""
    arg = coerce_unicode(arg, _c.FSQ_CHARSET)
    new_arg = sep = u''
    delimiter, encodeseq = delimiter_encodeseq(_c.FSQ_DELIMITER if delimiter is None else delimiter, _c.FSQ_ENCODE if encodeseq is None else encodeseq, _c.FSQ_CHARSET)
    encoding_trg = sep
    for c in arg:
        if len(encoding_trg):
            encoding_trg = sep.join([encoding_trg, c])
            if 4 != len(encoding_trg):
                continue
            try:
                c = chr(int(encoding_trg, 16))
            except ValueError:
                raise FSQEncodeError(errno.EINVAL, u'invalid decode target: {0}'.format(encoding_trg))
            c = coerce_unicode(c, _c.FSQ_CHARSET)
            encoding_trg = sep
        elif c == encodeseq:
            encoding_trg = u'0x'
            continue
        new_arg = sep.join([new_arg, c])
    if len(encoding_trg):
        raise FSQEncodeError(errno.EINVAL, u'truncated encoding at end of argument: {0}'.format(encoding_trg))
    return new_arg

def is_node_destroyable(name, prefixes=DESTROYABLE_PREFIXES):
    """Return True if name starts with a destroyable prefix"""
    return any([name.startswith(p) for p in prefixes])

def handle_errors(callback, parsed=None, out=sys.stderr):
    """Execute the callback, optionally passing it parsed, and return
    its return value.  If an exception occurs, determine which kind it
    is, output an appropriate message, and return the corresponding
    error code."""
    try:
        if parsed:
            return callback(parsed)
        else:
            return callback()
    except DeploymentError as e:
        traceback.print_exc(file=out)
        print(e, file=out)
        if hasattr(e, 'value') and hasattr(e.value, 'args') and (len(e.value.args) > 0) and ('open_sftp_client' in e.value.args[0]):
            print('Timeout', file=out)
            return TIMEOUT
        return DEPLOYMENT_ERROR
    except MalformedResponseError as e:
        traceback.print_exc(file=out)
        print(e, file=out)
        if 'Service Unavailable' in e.body:
            return SERVICE_UNAVAILABLE
        return MALFORMED_RESPONSE
    except SystemExit:
        pass
    except:
        traceback.print_exc(file=out)
        return EXCEPTION

def makemap(filenames, sourcedir, targetdir=None):
    """Return an OrderedDict (to preserve script run order) which maps
    filenames coming from a single local source directory to a single
    target directory.  Most useful for scripts, whose location when
    run is often unimportant, and so can all be placed in common
    directory."""
    if targetdir is None:
        targetdir = DEFAULT_TARGETDIR
    return OrderedDict(((join(targetdir, f), join(sourcedir, f)) for f in filenames))

def new_bundle(name, scriptmap, filemap=None):
    """Create a bundle and add to available bundles"""
