def _list_merge(src, dest):
    """Merge the contents coming from src into dest

    :param src: source dictionary
    :param dest: destination dictionary"""
    for k in src:
        if type(src[k]) != dict:
            dest[k] = src[k]
        else:
            if k not in dest:
                dest[k] = {}
            _list_merge(src[k], dest[k])

def extract_keywords_from_text(index_page, no_items=5):
    """Try to process text on the `index_page` deduce the keywords and then try
    to match them on the Aleph's dataset.

    Function returns maximally `no_items` items, to prevent spamming the user.

    Args:
        index_page (str): Content of the page as UTF-8 string
        no_items (int, default 5): Number of items to return.

    Returns:
        list: List of :class:`.SourceString` objects."""
    index_page = MLStripper.strip_tags(index_page)
    tokenized_index = TextBlob(index_page).lower()
    def to_str(key):
        if isinstance(key, unicode):
            return key.encode('utf-8')
        return key
    present_keywords = [KEYWORDS_LOWER[key] for key in KEYWORDS_LOWER.keys() if len(key) > 3 and key in tokenized_index]
    def to_source_string(key):
        source = 'Keyword analysis'
        try:
            return SourceString(key, source)
        except UnicodeEncodeError:
            return SourceString(key.encode('utf-8'), source)
    multi_keywords = [to_source_string(key) for key in present_keywords if tokenized_index.words.count(key) >= 1]
    multi_keywords = sorted(multi_keywords, key=lambda x: len(x), reverse=True)
    if len(multi_keywords) > no_items:
        return multi_keywords[:no_items]
    return multi_keywords

def fetch(hash):
    """Fetches CallDescriptor from the local database given a hash key representing the call. If it doesn't exist returns None.

    :param str hash: The sha1 hexdigest to look the CallDescriptor up by.

    :rtype: CallDescriptor corresponding to the hash passed or None if it wasn't found."""
    res = select_io(hash)
    if res:
        p = {'methodname': '', 'returnval': '', 'args': '', 'stack': ''}
        for packet in res:
            hash, stack, methodname, returnval, args, packet_num = packet
            p['methodname'] = p['methodname'] + methodname
            p['returnval'] = p['returnval'] + returnval
            p['args'] = p['args'] + args
            p['stack'] = p['stack'] + stack
        return CallDescriptor(hash=hash, stack=p['stack'], method=p['methodname'], returnval=pickle.loads(str(p['returnval'])), args=pickle.loads(str(p['args'])))
    return None

def get_object(context):
    """Get an object from the context or view."""
    object = None
    view = context.get('view')
    if view:
        object = getattr(view, 'object', None)
    if object is None:
        object = context.get('object', None)
    return object

