def parameters_present(options, **kwargs):
    """Analysis function
    Check whether all calls contain a given parameters or their synonyms"""
    synonyms = options['synonyms']
    call_graph = options['call_graph']
    result = _Result()
    for node, edges in call_graph:
        for edge in edges:
            call_config = edge.settings
            for req_param, req_value in kwargs.items():
                found = False
                for param, value in call_config.items():
                    if synonyms.are_synonyms(param, req_param):
                        found = True
                        break
                if not found:
                    result.add(node, edge, req_param)
    return result

def gzipped(fn):
    """Decorator used to pack data returned from the Bottle function to GZIP.

    The decorator adds GZIP compression only if the browser accepts GZIP in
    it's ``Accept-Encoding`` headers. In that case, also the correct
    ``Content-Encoding`` is used."""
    def gzipped_wrapper(*args, **kwargs):
        accepted_encoding = request.get_header('Accept-Encoding')
        if not accepted_encoding or 'gzip' not in accepted_encoding:
            return fn(*args, **kwargs)
        response.set_header('Content-Encoding', 'gzip')
        return to_gzipped_file(fn(*args, **kwargs))
    return gzipped_wrapper

def getcolor(spec):
    """Turn optional color string spec into an array."""
    if isinstance(spec, str):
        from matplotlib import colors
        return asarray(colors.hex2color(colors.cnames[spec]))
    else:
        return spec

def getcolors(spec, n, cmap=None, value=None):
    """Turn list of color specs into list of arrays."""
    if cmap is not None and spec is not None:
        from matplotlib.colors import LinearSegmentedColormap
        from matplotlib.cm import get_cmap
        if isinstance(cmap, LinearSegmentedColormap):
            return cmap(value)[:, 0:3]
        if isinstance(cmap, str):
            return get_cmap(cmap, n)(value)[:, 0:3]
    if isinstance(spec, str):
        return [getcolor(spec) for i in range(n)]
    elif isinstance(spec, list) and isinstance(spec[0], str):
        return [getcolor(s) for s in spec]
    elif (isinstance(spec, list) or isinstance(spec, ndarray)) and asarray(spec).shape == (3,):
        return [spec for i in range(n)]
    else:
        return spec

def getbase(base=None, dims=None, extent=None, background=None):
    """Construct a base array from optional arguments."""
    if dims is not None:
        extent = dims
    if base is None and background is None:
        return ones(tuple(extent) + (3,))
    elif base is None and background is not None:
        base = zeros(tuple(extent) + (3,))
        for channel in range(3):
            base[:, :, channel] = background[channel]
        return base
    elif base is not None and base.ndim < 3:
        return tile(expand_dims(base, 2), [1, 1, 3])
    else:
        return base

def simple_getter(queryset, object_regex=None, lookup_field=None):
    """Returns simple object_getter function for use with PluggableSite.
    It takes 'queryset' with QuerySet or Model instance, 'object_regex' with
    url regex and 'lookup_field' with lookup field."""
    object_regex = object_regex or '\\d+'
    lookup_field = lookup_field or 'pk'
    if isinstance(queryset, models.Model):
        qs = queryset._default_manager.all()
    elif isinstance(queryset, QuerySet) or isinstance(queryset, models.Manager):
        qs = queryset
    def object_getter(object_id):
        return qs.get(**{lookup_field: object_id})
    object_getter.regex = '(?P<object_id>%s)' % object_regex
    return object_getter

def join_path(base, *parts: str):
    """Creates urls from base path and additional parts."""
    _parts = '/'.join((_part.strip('/') for _part in parts))
    if base.endswith('/'):
        url = base + _parts
    else:
        url = base + '/' + _parts
    return url

def pyobj_role(make_node, name, rawtext, text, lineno, inliner, options=None, content=None):
    """Include Python object value, rendering it to text using str.

    Returns 2 part tuple containing list of nodes to insert into the
    document and a list of system messages.  Both are allowed to be
    empty.

    :param make_node: A callable which accepts (rawtext, app, prefixed_name, obj, parent, modname, options) and which returns a node
    :param name: The role name used in the document.
    :param rawtext: The entire markup snippet, with role.
    :param text: The text marked with the role.
    :param lineno: The line number where rawtext appears in the input.
    :param inliner: The inliner instance that called us.
    :param options: Directive options for customization.
    :param content: The directive content for customization."""
    if options is None:
        options = {}
    if content is None:
        content = []
    try:
        prefixed_name, obj, parent, modname = import_by_name(text)
    except ImportError:
        msg = inliner.reporter.error('Could not locate Python object {}'.format(text), line=lineno)
        prb = inliner.problematic(rawtext, rawtext, msg)
        return ([prb], [msg])
    app = inliner.document.settings.env.app
    node = make_node(rawtext, app, prefixed_name, obj, parent, modname, options)
    return ([node], [])

def _pick_keywords(db):
    """Go thru downloaded data stored in `db` and filter keywords, which are
    parsed and then yielded.

    Shows nice progress bar.

    Args:
        db (obj): Opened database connection.

    Yields:
        obj: :class:`KeywordInfo` instances for yeach keyword."""
    for key, val in tqdm(db.iteritems(), total=len(db)):
        if key == 'last_id':
            continue
        piece = val[:500] if len(val) > 500 else val
        if '<fixfield id="001">ph' not in piece.lower():
            continue
        parsed = MARCXMLRecord(val)
        code = parsed.get('001')
        if not code:
            continue
        if parsed['682i']:
            continue
        if code.lower().startswith('ph'):
            yield KeywordInfo.from_marc(sysno=int(key.split('_')[-1]), marc=parsed)

