    rets = []
    for argument in arguments:
        args = argument.split(argument_splitter)
        func_name = args[0]
        func_args = {}
        for arg in args[1:]:
            key, value = parse_arg(arg)
            func_args[key] = value
        rets.append(FunctionArguments(function=func_name, arguments=func_args))
    return rets

def singleton(cls):
    """See <Singleton> design pattern for detail: http://www.oodesign.com/singleton-pattern.html
    Python <Singleton> reference: http://stackoverflow.com/questions/6760685/creating-a-singleton-in-python
    Recommend use Singleton as a metaclass

    Usage:
        @singleton
        class MyClass(object):
            pass"""
    instances = {}
    def get_instance(*args, **kwargs):
        if cls not in instances:
            instances[cls] = cls(*args, **kwargs)
        return instances[cls]
    return get_instance

