def human_size(s, factor):
    """:s: size
    :factor: 1000 or 1024"""
    unit = 'B'
    if s > factor:
        s /= factor
        unit = 'KB'
    if s > factor:
        s /= factor
        unit = 'MB'
    if s > factor:
        s /= factor
        unit = 'GB'
    if s > factor:
        s /= factor
        unit = 'TB'
    return '%.2f %s' % (s, unit)

def provides(*specification):
    """Decorator marking wrapped :py:class:`Module` method as :term:`provider` for
    given :term:`specification`.

    For example::

        class ApplicationModule(Module):

            @provides('db_connection')
            def provide_db_connection(self):
                return DBConnection(host='localhost')"""
    if len(specification) == 1:
        specification = specification[0]
    else:
        specification = tuple(specification)
    def decorator(function):
        function.__provides__ = specification
        return function
    return decorator

def optional_argument_decorator(_decorator):
    """Decorate your decorator with this to allow it to always receive *args and **kwargs, making @deco equivalent to
    @deco()"""
    @functools.wraps(_decorator)
    def inner_decorator_make(*args, **kwargs):
        if len(args) == 1 and len(kwargs) == 0 and callable(args[0]):
            func = args[0]
            args = tuple()
            kwargs = dict()
        else:
            func = None
        decorator = _decorator(*args, **kwargs)
        if func:
            return decorator(func)
        else:
            return decorator
    return inner_decorator_make

def getattr_in_cls_list(cls_list, attr, default):
    """Search for an attribute (attr) in class list (cls_list). Returns
    attribute value if exists or None if not."""
    for cls in cls_list:
        if hasattr(cls, attr):
            return getattr(cls, attr)
    return default

