def sanitize_word(word):
    """sanitize a word by removing its accents, special characters, etc"""
    if type(word) == str:
        try:
            word = word.decode()
        except AttributeError:
            pass
    word = word.strip()
    word = re.sub('\\([^)]*\\)', '', word)
    word = re.sub('[ "\\\'-;.]+', '', unidecode(word))
    return word.lower()

