def waitForURL(url, max_seconds=None):
    """Give it a URL.  Keep trying to get a HEAD request from it until it works.
    If it doesn't work, wait a while and try again"""
    startTime = datetime.now()
    while True:
        response = None
        try:
            response = urllib2.urlopen(HEADREQUEST(url))
        except urllib2.URLError:
            pass
        if response is not None and isinstance(response, urllib2.addinfourl):
            if response.getcode() == 200:
                return
        timeNow = datetime.now()
        timePassed = timeNow - startTime
        if max_seconds and max_seconds < timePassed.seconds:
            return
        print('Waiting on URL %s for %s so far' % (url, timePassed))
        time.sleep(30)

def doWaitWebRequest(url, method='GET', data=None, headers={}):
    """Same as doWebRequest, but with built in wait-looping"""
    completed = False
    while not completed:
        completed = True
        try:
            response, content = doWebRequest(url, method, data, headers)
        except urllib2.URLError:
            completed = False
            waitForURL(url)
    return (response, content)

def doWebRequest(url, method='GET', data=None, headers={}):
    """A urllib2 wrapper to mimic the functionality of http2lib, but with timeout support"""
    response = None
    content = None
    if method == 'HEAD':
        request = HEADREQUEST(url, data=data, headers=headers)
    elif method == 'PUT':
        request = PUTREQUEST(url, data=data, headers=headers)
    elif method == 'DELETE':
        request = DELETEREQUEST(url, headers=headers)
    elif method == 'GET':
        request = urllib2.Request(url, headers=headers)
    else:
        request = urllib2.Request(url, data=data, headers=headers)
    response = urllib2.urlopen(request)
    if response:
        content = response.read()
    return (response, content)

def deleteQueue(destinationRoot, queueArk, debug=False):
    """Delete an entry from the queue"""
    url = urlparse.urljoin(destinationRoot, 'APP/queue/' + queueArk + '/')
    response, content = doWaitWebRequest(url, 'DELETE')
    if response.getcode() != 200:
        raise Exception('Error updating queue %s to url %s.  Response code is %s\n%s' % (queueArk, url, response.getcode(), content))

def sorter(expr):
    """This is a sorting function generator that takes an expression optionally
    prefixed with a "+" (ascending, the default) or "-" (descending) character.

    >>> sorted([{'a': 12}, {'a': 1}, {'a': 4}], sorter("+a"))
    [{'a': 1}, {'a': 4}, {'a': 12}]
    >>> sorted([{'a': 24}, {'a': 16}, {'a': 32}], sorter("-a"))
    [{'a': 32}, {'a': 24}, {'a': 16}]"""
    order = ascending
    if not callable(expr):
        if ',' in expr:
            sorts = map(sorter, expr.split(','))
            return multisorter(*sorts)
        if expr[0] == '-':
            order = descending
            expr = expr[1:]
        elif expr[0] == '+':
            expr = expr[1:]
        expr = expression(expr)
    def _sort(a, b):
        return order(expr(a), expr(b))
    return _sort

def organize(data, key):
    """Iterate over a collection and group its values by the provided key
    function. If the key is not callable (a function), then we wrap it in
    templategetter(), so that you can simply do:

    >>> organize([{'foo': 1}, {'foo': 2}, {'foo': 1}], "{foo}")
    {'1': [{'foo': 1}, {'foo': 1}], '2': [{'foo': 2}]}"""
    groups = {}
    if not callable(key):
        key = templategetter(key)
    for row in data:
        k = key(row)
        if groups.has_key(k):
            groups[k].append(row)
        else:
            groups[k] = [row]
    return groups

def map_expression(expr):
    """Returns a function that maps a dict to a new dict with unique keys and
    values, kind of like a SQL SELECT clause, e.g.:

    >>> map_expression("foo=bar")({'bar': 1})
    {'foo': 1}
    >>> map_expression("foo=bar+1")({'bar': 1})
    {'foo': 2}"""
    if callable(expr):
        return expr
    bits = expr.split(',')
    exprs = [(bit[0].strip(), len(bit) > 1 and bit[1].strip() or '') for bit in [bit.split('=') for bit in bits]]
    keys = [(k[0], k[1] and expression(k[1]) or None) for k in exprs]
    key_dict = dict(keys)
    def _expr(data, **kwargs):
        vals = {}
        for key, expr in key_dict.items():
            if key == '*':
                vals.update(data)
                continue
            elif not expr:
                vals[key] = data.get(key)
                continue
            else:
                vals[key] = expr(data, **kwargs)
        return vals
    _expr.__doc__ = expr
    _expr.keys = map(lambda k: k[0], keys)
    return _expr

def remote(fn, name=None, types=None):
    """Decorator that adds a remote attribute to a function.

    fn -- function being decorated
    name -- aliased name of the function, used for remote proxies
    types -- a argument type specifier, can be used to ensure
             arguments are of the correct type"""
    if not name:
        name = fn.__name__
    fn.remote = {'name': name, 'types': types}
    return fn

