    patcher = _get_mongopatcher()
    if dry_run:
        patcher.discover_and_apply(directory=patches, dry_run=dry_run)
    elif yes or prompt_bool('Are you sure you want to alter %s' % green(patcher.db)):
        patcher.discover_and_apply(patches)
