def log_formatter(request=None):
    """Log formatter used in our syslog

    :param request: a request object
    :returns: logging.Formatter"""
    if request:
        format_str = '%(asctime)s {ip} {name}:  ENV={env} REMOTE_IP=%(remote_ip)s REQUEST_ID=%(request_id)s %(message)s'
    else:
        format_str = '%(asctime)s {ip} {name}:  ENV={env} %(message)s'
    try:
        hostname = socket.gethostname()
    except socket.gaierror:
        hostname = 'localhost'
    try:
        ip = socket.gethostbyname(hostname)
    except socket.gaierror:
        ip = '127.0.0.1'
    formatter = logging.Formatter(format_str.format(ip=ip, name=options.name, env=options.env), datefmt='%Y-%m-%dT%H:%M:%S')
    logging.Formatter.converter = time.gmtime
    return formatter

def scrub(data):
    """Verify and clean data. Raise error if input fails."""
    if not data:
        return data
    if isinstance(data, (int, float)):
        return data
    if isinstance(data, list):
        return [scrub(entry) for entry in data]
    if isinstance(data, dict):
        return {scrub(key): scrub(value) for key, value in data.items()}
    try:
        return json.encoder.encode_basestring(data)[1:-1]
    except TypeError as exc:
        raise ValidationError("Input '%s' is not a permitted type: %s" % (data, exc))
    except Exception as exc:
        raise ValidationError("Input '%s' not permitted: %s" % (data, exc))

def database(connection_string, db_class=SimplDB):
    """Return database singleton instance.

    This function will always return the same database instance for the same
    connection_string. It stores instances in a dict saved as an attribute of
    this function."""
    if not hasattr(database, 'singletons'):
        database.singletons = {}
    if connection_string not in database.singletons:
        instance = db_class(connection_string)
        database.singletons[connection_string] = instance
    return database.singletons[connection_string]

def params_to_mongo(query_params):
    """Convert HTTP query params to mongodb query syntax.

    Converts the parse query params into a mongodb spec.

    :param dict query_params: return of func:`rest.process_params`"""
    if not query_params:
        return {}
    for key, value in query_params.items():
        if isinstance(value, list):
            query_params[key] = {'$in': value}
    return query_params

def load_module(filename):
    """Loads a module from anywhere in the system.

    Does not depend on or modify sys.path."""
    path, name = os.path.split(filename)
    name, ext = os.path.splitext(name)
    file, filename, desc = imp.find_module(name, [path])
    try:
        return imp.load_module(name, file, filename, desc)
    finally:
        if file:
            file.close()

def get_template(template_name, using=None):
    """Loads and returns a template for the given name.
    Raises TemplateDoesNotExist if no such template exists."""
    engines = _engine_list(using)
    for engine in engines:
        try:
            return engine.get_template(template_name)
        except TemplateDoesNotExist as e:
            pass
    raise TemplateDoesNotExist(template_name)

def select_template(template_name_list, using=None):
    """Loads and returns a template for one of the given names.
    Tries names in order and returns the first template found.
    Raises TemplateDoesNotExist if no such template exists."""
    if isinstance(template_name_list, six.string_types):
        raise TypeError('select_template() takes an iterable of template names but got a string: %r. Use get_template() if you want to load a single template by name.' % template_name_list)
    engines = _engine_list(using)
    for template_name in template_name_list:
        for engine in engines:
            try:
                return engine.get_template(template_name)
            except TemplateDoesNotExist as e:
                pass
    if template_name_list:
        raise TemplateDoesNotExist(', '.join(template_name_list))
    else:
        raise TemplateDoesNotExist('No template names provided')

def render_to_string(template_name, context=None, request=None, using=None):
    """Loads a template and renders it with a context. Returns a string.
    template_name may be a string or a list of strings."""
    if isinstance(template_name, (list, tuple)):
        template = select_template(template_name, using=using)
    else:
        template = get_template(template_name, using=using)
    return template.render(context, request)

def adapt(obj, to_cls):
    """Will adapt `obj` to an instance of `to_cls`.

    First sees if `obj` has an `__adapt__` method and uses it to adapt. If that fails
    it checks if `to_cls` has an `__adapt__` classmethod and uses it to adapt. IF that
    fails, MRO is used. If that
    fails, a `TypeError` is raised."""
    if obj is None:
        return obj
    elif isinstance(obj, to_cls):
        return obj
    errors = []
    if hasattr(obj, '__adapt__') and obj.__adapt__:
        try:
            return obj.__adapt__(to_cls)
        except (AdaptError, TypeError) as e:
            ex_type, ex, tb = sys.exc_info()
            errors.append((obj.__adapt__, ex_type, ex, tb))
    if hasattr(to_cls, '__adapt__') and to_cls.__adapt__:
        try:
            return to_cls.__adapt__(obj)
        except (AdaptError, TypeError) as e:
            ex_type, ex, tb = sys.exc_info()
            errors.append((to_cls.__adapt__, ex_type, ex, tb))
    for k in get_adapter_path(obj, to_cls):
        if k in __adapters__:
            try:
                return __adapters__[k](obj, to_cls)
            except (AdaptError, TypeError) as e:
                ex_type, ex, tb = sys.exc_info()
                errors.append((__adapters__[k], ex_type, ex, tb))
                break
    raise AdaptErrors('Could not adapt %r to %r' % (obj, to_cls), errors=errors)

def register_adapter(from_classes, to_classes, func):
    """Register a function that can handle adapting from `from_classes` to `to_classes`."""
    assert from_classes, 'Must supply classes to adapt from'
    assert to_classes, 'Must supply classes to adapt to'
    assert func, 'Must supply adapter function'
    if not isinstance(from_classes, (tuple, list)):
        from_classes = [from_classes]
    if not isinstance(to_classes, (tuple, list)):
        to_classes = [to_classes]
    for key in itertools.product(from_classes, to_classes):
        if key in __adapters__:
            raise AdapterExists('%r to %r already exists.' % key)
        __adapters__[key] = func

def _get_corenlp_version():
    """Return the corenlp version pointed at by CORENLP_HOME, or None"""
    corenlp_home = os.environ.get('CORENLP_HOME')
    if corenlp_home:
        for fn in os.listdir(corenlp_home):
            m = re.match('stanford-corenlp-([\\d.]+)-models.jar', fn)
            if m:
                return m.group(1)

def get_command(annotators=None, memory=None):
    """Return the system (shell) call to run corenlp"""
    corenlp_home = os.environ.get('CORENLP_HOME')
    if not corenlp_home:
        raise Exception('CORENLP_HOME not set')
    cmd = 'java'
    if memory:
        cmd += ' -Xmx{memory}'.format(**locals())
    cmd += ' -cp "{}"'.format(os.path.join(corenlp_home, '*'))
    cmd += ' edu.stanford.nlp.pipeline.StanfordCoreNLP -outputFormat xml'
    if annotators:
        cmd += ' -annotators {}'.format(','.join(annotators))
    return cmd

def getQRArray(text, errorCorrection):
    """Takes in text and errorCorrection (letter), returns 2D array of the QR code"""
    qr = pyqrcode.create(text, error=errorCorrection)
    plainOut = qr.terminal().split('\n')[5:-5]
    out = []
    for line in plainOut:
        thisOut = []
        for char in line:
            if char == u'7':
                thisOut.append(1)
            elif char == u'4':
                thisOut.append(0)
        out.append(thisOut[4:-4])
    return out

