def funTransEdgeX(theta, rho):
    """Fringe matrix in X

    :param theta: fringe angle, in [rad]
    :param rho: bend radius, in [m]
    :return: 2x2 numpy array"""
    return np.matrix([[1, 0], [np.tan(theta) / rho, 1]], dtype=np.double)

def funTransEdgeY(theta, rho):
    """Fringe matrix in Y

    :param theta: fringe angle, in [rad]
    :param rho: bend radius, in [m]
    :return: 2x2 numpy array"""
    return np.matrix([[1, 0], [-np.tan(theta) / rho, 1]], dtype=np.double)

def funTransSectX(theta, rho):
    """Sector matrix in X

    :param theta: bend angle, in [rad]
    :param rho: bend radius, in [m]
    :return: 2x2 numpy array"""
    return np.matrix([[np.cos(theta), rho * np.sin(theta)], [-np.sin(theta) / rho, np.cos(theta)]], dtype=np.double)

def funTransSectY(theta, rho):
    """Sector matrix in Y

    :param theta: bend angle, in [rad]
    :param rho: bend radius, in [m]
    :return: 2x2 numpy array"""
    return np.matrix([[1, rho * theta], [0, 1]], dtype=np.double)

def _is_valid_extension(extension):
    """Checks if the file extension is blacklisted in valid_extensions.

    :param str extension: a file extension to check
    :returns: flag indicating if the extension is valid based on list of
              valid extensions.
    :rtype: bool"""
    if not cfg.CONF.valid_extensions:
        return True
    valid = False
    for cext in cfg.CONF.valid_extensions:
        if not cext.startswith('.'):
            cext = '.%s' % cext
        if extension == cext:
            valid = True
            break
    return valid

def retrieve_files():
    """Get list of files found in provided locations.

    Search through the paths provided to find files for processing.

    :returns: absolute path of filename
    :rtype: list"""
    all_files = []
    for location in cfg.CONF.locations or []:
        if not location.startswith('\\'):
            location = os.path.abspath(os.path.expanduser(location))
        LOG.debug('searching [%s]', location)
        for root, _, files in os.walk(location):
            LOG.debug('found file(s) %s', files)
            for name in files:
                filepath = os.path.join(root, name)
                if os.access(filepath, os.R_OK) and (not _is_blacklisted_filename(filepath)) and _is_valid_extension(os.path.splitext(name)[1]):
                    all_files.append(filepath)
    return all_files

