def mean(array):
    """Return the mean value of a list of divisible numbers."""
    n = len(array)
    if n < 1:
        return 0
    elif n == 1:
        return array[0]
    return sum(array) / n

def geomean(array):
    """Return the mean value of a list of divisible numbers."""
    n = len(array)
    if n < 1:
        return 0
    elif n == 1:
        return array[0]
    return stats.mstats.gmean(array)

def variance(array):
    """Return the variance of a list of divisible numbers."""
    if len(array) < 2:
        return 0
    u = mean(array)
    return sum([(x - u) ** 2 for x in array]) / (len(array) - 1)

def merge_dicts(*dict_list):
    """Extract all of the dictionaries from this list, then merge them together"""
    all_dicts = []
    for ag in dict_list:
        if isinstance(ag, dict):
            all_dicts.append(ag)
    try:
        qitem = {k: v for d in all_dicts for k, v in d.items()}
        return qitem
    except Exception:
        return {}

def filter_query(filter_dict, required_keys):
    """Ensure that the dict has all of the information available. If not, return what does"""
    if not isinstance(filter_dict, dict):
        raise TypeError('dict_list is not a list. Please try again')
    if not isinstance(required_keys, list):
        raise TypeError('dict_list is not a list. Please try again')
    available = []
    for k, v in filter_dict.items():
        if k in required_keys:
            available.append(k)
    return available

def price_query_filter(price_query_dict):
    """Ensure that certain keys are available.
        - exchange
        - period"""
    if not isinstance(price_query_dict, dict):
        raise TypeError('dict_list is not a list. Please try again')
    required = ['period', 'exchange']
    pkeys = price_query_dict.keys()
    for r in required:
        if r not in pkeys:
            raise KeyError('An important key is not available {}'.format(r))
    return True

def pbkdf2_hex(data, salt, iterations=1000, keylen=24, hashfunc=None):
    """Like :func:`pbkdf2_bin` but returns a hex encoded string."""
    return hexlify_(pbkdf2_bin(data, salt, iterations, keylen, hashfunc))

def pbkdf2_bin(data, salt, iterations=1000, keylen=24, hashfunc=None):
    """Returns a binary digest for the PBKDF2 hash algorithm of `data`
    with the given `salt`.  It iterates `iterations` time and produces a
    key of `keylen` bytes.  By default SHA-1 is used as hash function,
    a different hashlib `hashfunc` can be provided."""
    hashfunc = hashfunc or hashlib.sha1
    mac = hmac.new(bytes_(data), None, hashfunc)
    def _pseudorandom(x, mac=mac):
        h = mac.copy()
        h.update(bytes_(x))
        if not PY2:
            return [x for x in h.digest()]
        else:
            return map(ord, h.digest())
    buf = []
    for block in range_(1, -(-keylen // mac.digest_size) + 1):
        rv = u = _pseudorandom(bytes_(salt) + _pack_int(block))
        for i in range_(iterations - 1):
            if not PY2:
                u = _pseudorandom(bytes(u))
            else:
                u = _pseudorandom(''.join(map(chr, u)))
            rv = starmap(xor, zip(rv, u))
        buf.extend(rv)
    if not PY2:
        return bytes(buf)[:keylen]
    else:
        return ''.join(map(chr, buf))[:keylen]

def main(filepath, in_debug_mode):
    """Gibica Interpreter."""
    with open(filepath) as file:
        try:
            lexer = Lexer(file.read())
            parser = Parser(lexer)
            tree = parser.parse()
            symtab_builder = SymbolTableBuilder(tree)
            symtab_builder.build()
            interpreter = Interpreter(tree)
            interpreter.interpret()
            if in_debug_mode:
                print(f'SYMBOL TABLE: {symtab_builder.table}')
                print(f'GLOBAL MEMORY: {interpreter.memory}')
        except Exception as gibica_exception:
            if in_debug_mode:
                raise
            else:
                print(f'{gibica_exception.__class__.__name__}: {gibica_exception}')

def create(name, image, bare):
    """Create a new project."""
    if bool(bare) == bool(image):
        raise click.UsageError('Specify either --bare or image using --image.')
    path = get_project_path(name)
    print('Creating %s...' % path)
    try:
        os.mkdir(path)
    except FileExistsError:
        die('%s already exists.' % path)
    if not bare:
        print('Creating container with image %s...' % image)
        client = docker.Client()
        try:
            client.create_container(image=image, name=get_container_name(name), hostname=name, working_dir='/code/', command='tail -f /dev/null', tty=True, volumes=['/code/'], host_config=client.create_host_config(binds={path: {'bind': '/code/', 'mode': 'rw'}}))
        except docker.errors.APIError as error:
            die(error.explanation.decode())
    enter_project(name)

def stop(name):
    """Stop project's container."""
    container_name = get_container_name(name)
    client = docker.Client()
    try:
        client.stop(container_name)
    except docker.errors.NotFound:
        pass
    except docker.errors.APIError as error:
        die(error.explanation.decode())

def _manage_commands():
    """Build COMMAND_MAPPER and COMMAND_ALIASES dictionaries using COMMANDS

    @return:None"""
    for name, (command, *aliases) in COMMANDS.items():
        COMMAND_MAPPER[name] = command
        for alias in aliases:
            COMMAND_MAPPER[alias] = command
        COMMAND_ALIASES[name] = aliases

def find_candidate_splays(splays, azm, inc, delta=LRUD_DELTA):
    """Given a list of splay shots, find candidate LEFT or RIGHT given target AZM and INC"""
    return [splay for splay in splays if angle_delta(splay['AZM'], azm) <= delta / 2 and angle_delta(splay['INC'], inc) <= delta / 2]

def find_candidate_vert_splays(splays, inc, delta=LRUD_DELTA):
    """Given a list of splay shots, find candidate UP or DOWN given target INC (90, or -90)"""
    if inc == 90:
        return [splay for splay in splays if splay['INC'] >= 30]
    elif inc == -90:
        return [splay for splay in splays if splay['INC'] <= -30]

def encode_df(df, data_types={}):
    """Encode columns so their values are usable in vector operations. Making a few
    assumptions here, like that datetime should be an integer, and that it's
    acceptable to fill NaNs with 0."""
    numbers = []
    categories = []
    datetimes = []
    for column, series in df.iteritems():
        if column in data_types:
            dtypes = data_types[column]
        else:
            dtypes = {}
        if 'datetime' in dtypes:
            index = pd.DatetimeIndex(pd.to_datetime(series.values))
            df[column] = index.astype(np.int64).astype(float)
            datetimes.append(column)
        elif any([dtype in dtypes for dtype in ['category', 'label']]):
            df = pd.get_dummies(df, columns=[column])
            categories.append(column)
        elif 'numeric' in dtypes:
            df[column] = clean_numbers(df[column].values)
            df[column] = df[column].astype(float)
            numbers.append(column)
        else:
            df.drop(column, 1, inplace=True)
    scaler = MinMaxScaler()
    df[numbers + datetimes] = scaler.fit_transform(df[numbers + datetimes])
    return (df, categories, numbers, datetimes)

def get_time_string(time_gmt=None):
    """The canonical time string format (in UTC).

    :keyword time_gmt: this is a time_struct, datetime class, or None. If None,
        the current time is used. Its name, time_gmt, is for legacy support for
        functions that called it before it supported multiple values.

    Changing this function will change all times that projects using simpl
        return in their APIs."""
    if isinstance(time_gmt, datetime.datetime):
        time_gmt = time_gmt.timetuple()
    if time_gmt is None:
        time_gmt = time.gmtime()
    if isinstance(time_gmt, time.struct_time):
        return time.strftime(API_FORMAT, time_gmt)
    raise TypeError('time_gmt must be a time_struct, datetime, or None. A %s was passed.' % type(time_gmt))

def replace_env_vars(conf):
    """Fill `conf` with environment variables, where appropriate.

    Any value of the from $VAR will be replaced with the environment variable
    VAR. If there are sub dictionaries, this function will recurse.

    This will preserve the original dictionary, and return a copy."""
    d = deepcopy(conf)
    for key, value in d.items():
        if type(value) == dict:
            d[key] = replace_env_vars(value)
        elif type(value) == str:
            if value[0] == '$':
                var_name = value[1:]
                d[key] = os.environ[var_name]
    return d

def fmt_second(time_total):
    """>>> fmt_second(100)
    '00:01:40'"""
    def _ck(t):
        return t < 10 and '0%s' % t or t
    times = int(time_total)
    h = times / 3600
    m = times % 3600 / 60
    s = times % 3600 % 60
    return '%s:%s:%s' % (_ck(h), _ck(m), _ck(s))

def convert_filename(txtfilename, outdir='.'):
    """Convert a .TXT filename to a Therion .TH filename"""
    return os.path.join(outdir, os.path.basename(txtfilename)).rsplit('.', 1)[0] + '.th'

def dict_merge_pair(d1, d2):
    """Recursively merges values from d2 into d1."""
    for key in d2:
        if key in d1 and isinstance(d1[key], dict) and isinstance(d2[key], dict):
            dict_merge_pair(d1[key], d2[key])
        else:
            d1[key] = d2[key]
    return d1

