def follow(*args):
    """Start following changes to one or more FILENAME(s)."""
    parser = argparse.ArgumentParser(prog='%s %s' % (__package__, follow.__name__), description=follow.__doc__)
    parser.add_argument('FILENAME', help='files to follow', nargs='+')
    args = parser.parse_args(args)
    config = FragmentsConfig()
    for s, filename in _iterate_over_files(args.FILENAME, config, statuses='?'):
        fullpath = os.path.realpath(filename)
        if fullpath.startswith(config.root):
            key = os.path.relpath(fullpath, config.root)
            if key in config['files']:
                yield ("'%s' is already being followed" % os.path.relpath(filename))
                continue
            if os.access(fullpath, os.W_OK | os.R_OK):
                file_sha = _file_key(key)
                config['files'][key] = file_sha
                yield ("'%s' is now being followed (SHA-256: '%s')" % (os.path.relpath(filename), file_sha))
            else:
                yield ("Could not access '%s' to follow it" % os.path.relpath(filename))
        else:
            yield ("Could not follow '%s'; it is outside the repository" % os.path.relpath(filename))
    config.dump()

def normalize_hex(hex_color):
    """Transform a xxx hex color to xxxxxx.
    """
    hex_color = hex_color.replace('#', '').lower()
    length = len(hex_color)
    if length in (6, 8):
        return '#' + hex_color
    if length not in (3, 4):
        return None
    strhex = u'#%s%s%s' % (hex_color[0] * 2, hex_color[1] * 2, hex_color[2] * 2)
    if length == 4:
        strhex += hex_color[3] * 2
    return strhex

def _add_namespace(marc_xml):
    """Add proper XML namespace to the `marc_xml` record.

    Args:
        marc_xml (str): String representation of the XML record.

    Returns:
        str: XML with namespace."""
    dom = marc_xml
    if isinstance(dom, basestring):
        dom = dhtmlparser.parseString(marc_xml)
    root = dom.find('root')
    if root:
        root[0].params = {}
    for record in dom.find('record'):
        record.params = {}
    collections = dom.find('collection')
    if not collections:
        record = dom.find('record')[0]
        return XML_TEMPLATE.replace('$CONTENT', str(record))
    for col in collections:
        col.params['xmlns'] = 'http://www.loc.gov/MARC21/slim'
        col.params['xmlns:xsi'] = 'http://www.w3.org/2001/XMLSchema-instance'
        col.params['xsi:schemaLocation'] = 'http://www.loc.gov/MARC21/slim ' + 'http://www.loc.gov/standards/marcxml/schema/MARC21slim.xsd'
    return str(dom)

def value_check(arg_name, pos, allowed_values):
    """allows value checking at runtime for args or kwargs"""
    def decorator(fn):
        def logic(*args, **kwargs):
            arg_count = len(args)
            if arg_count:
                if pos < arg_count:
                    if args[pos] in allowed_values:
                        return fn(*args, **kwargs)
                    else:
                        raise ValueError("'{0}' at position {1} not in allowed values {2}".format(args[pos], pos, allowed_values))
                elif arg_name in kwargs:
                    value = kwargs[arg_name]
                    if value in allowed_values:
                        return fn(*args, **kwargs)
                    else:
                        raise ValueError("'{0}' is not an allowed kwarg".format(arg_name))
                else:
                    return fn(*args, **kwargs)
            elif arg_name in kwargs:
                value = kwargs[arg_name]
                if value in allowed_values:
                    return fn(*args, **kwargs)
            else:
                raise ValueError("'{0}' is not an allowed kwarg".format(arg_name))
        return logic
    return decorator

def type_check(arg_name, pos, reqd_type):
    """allows type checking at runtime for args or kwargs"""
    def decorator(fn):
        def logic(*args, **kwargs):
            arg_count = len(args)
            if arg_count:
                if pos < arg_count:
                    if isinstance(args[pos], reqd_type):
                        return fn(*args, **kwargs)
                    else:
                        raise TypeError("'{0}' at position {1} not of type {2}".format(args[pos], pos, reqd_type))
                elif arg_name in kwargs:
                    value = kwargs[arg_name]
                    if isinstance(value, reqd_type):
                        return fn(*args, **kwargs)
                    else:
                        raise TypeError("'{0}' is not of type {1}".format(arg_name, reqd_type))
                else:
                    return fn(*args, **kwargs)
            elif arg_name in kwargs:
                value = kwargs[arg_name]
                if isinstance(value, reqd_type):
                    return fn(*args, **kwargs)
            else:
                raise TypeError("'{0}' is not of type {1}".format(arg_name, reqd_type))
        return logic
    return decorator

def t_INDENTIFIER(t):
    """(\\$?[_a-zA-Z][_a-zA-Z0-9]*)|(__[A-Z_]+__)"""
    if t.value in reserved:
        t.type = t.value.upper()
        if t.value in reservedMap:
            t.value = reservedMap[t.value]
    elif t.value in strStatment:
        t.type = 'STATEMENT'
