            yield (mapping, offset, absolute)

def decorator(target):
    """A signature-matching decorator factory."""
    def decorate(fn):
        spec = inspect.getargspec(fn)
        names = tuple(spec[0]) + spec[1:3] + (fn.__name__,)
        targ_name, fn_name = unique_symbols(names, 'target', 'fn')
        metadata = dict(target=targ_name, fn=fn_name)
        metadata.update(format_argspec_plus(spec, grouped=False))
        code = 'lambda %(args)s: %(target)s(%(fn)s, %(apply_kw)s)' % metadata
        decorated = eval(code, {targ_name: target, fn_name: fn})
        decorated.__defaults__ = getattr(fn, 'im_func', fn).__defaults__
        return update_wrapper(decorated, fn)
    return update_wrapper(decorate, target)

def exc_emailer(send_mail_func, logger=None, catch=Exception, print_to_stderr=True):
    """Catch exceptions and email them using `send_mail_func` which should
    accept a single string argument which will be the traceback to be
    emailed. Will re-raise original exception if calling `send_mail_func`
    raises an exception.

    Provide a logging.Logger instance for `logger` if desired (recommended).

    The exceptions this decorator handled can be adjusted by setting `catch`
    to an Exception class or tuple of exception classes that should be
    handled."""
    if logger is None:
        logger = log
    @decorator
    def decorate(fn, *args, **kwargs):
        exc_info = None
        try:
            return fn(*args, **kwargs)
        except catch as e:
            body = format_exc()
            exc_info = sys.exc_info()
            error_msg = 'exc_mailer() caught an exception, email will be sent.'
            logger.exception(error_msg)
            if print_to_stderr:
                print(error_msg + '  ' + str(e), file=sys.stderr)
            try:
                send_mail_func(body)
            except Exception:
                logger.exception('exc_mailer(): send_mail_func() threw an exception, logging it & then re-raising original exception')
                six.reraise(exc_info[0], exc_info[1], exc_info[2])
        finally:
            if exc_info is not None:
                del exc_info
    return decorate

def memoize(method_to_wrap):
    """Currently only works on instance methods.  Designed for use with SQLAlchemy entities.  Could
    be updated in the future to be more flexible.

    class User(Base):
        __tablename__ = 'users'

        id = Column(Integer, primary_key=True)
        addresses = relationship("Address", backref="user")

        @memoize
        def address_count(self):
            return len(self.addresses)


    sqlalchemy.event.listen(User, 'expire', User.address_count.reset_memoize)"""
    memoize_key = '_memoize_cache_{0}'.format(id(method_to_wrap))
    @wrapt.decorator
    def inner_memoize(wrapped, instance, args, kwargs):
        if instance is None and inspect.isclass(wrapped):
            return wrapped(*args, **kwargs)
        cache = instance.__dict__.setdefault(memoize_key, {})
        try:
            key = (args, frozenset(kwargs.items()))
            return cache[key]
        except KeyError:
            result = cache[key] = wrapped(*args, **kwargs)
            return result
    def reset_memoize(target, *args):
        target.__dict__[memoize_key] = {}
    decorated = inner_memoize(method_to_wrap)
    decorated.reset_memoize = reset_memoize
    return decorated

def verify(password, hash):
    """Verify a password against a passed hash"""
    _, algorithm, cost, salt, password_hash = hash.split('$')
    password = pbkdf2.pbkdf2_hex(password, salt, int(cost) * 500)
    return _safe_str_cmp(password, password_hash)

def queryset_to_dict(qs, key='pk', singular=True):
    """Given a queryset will transform it into a dictionary based on ``key``."""
    if singular:
        result = {}
        for u in qs:
            result.setdefault(getattr(u, key), u)
    else:
        result = defaultdict(list)
        for u in qs:
            result[getattr(u, key)].append(u)
    return result

def attach_foreignkey(objects, field, related=[], database=None):
    """Shortcut method which handles a pythonic LEFT OUTER JOIN.

    ``attach_foreignkey(posts, Post.thread)``

    Works with both ForeignKey and OneToOne (reverse) lookups."""
    if not objects:
        return
    if database is None:
        database = list(objects)[0]._state.db
    is_foreignkey = isinstance(field, SingleRelatedObjectDescriptor)
    if not is_foreignkey:
        field = field.field
        accessor = '_%s_cache' % field.name
        model = field.rel.to
        lookup = 'pk'
        column = field.column
        key = lookup
    else:
        accessor = field.cache_name
        field = field.related.field
        model = field.model
        lookup = field.name
        column = 'pk'
        key = field.column
    objects = [o for o in objects if related or getattr(o, accessor, False) is False]
    if not objects:
        return
    values = distinct(filter(None, (getattr(o, column) for o in objects)))
    if values:
        qs = model.objects.filter(**{'%s__in' % lookup: values})
        if database:
            qs = qs.using(database)
        if related:
            qs = qs.select_related(*related)
        queryset = queryset_to_dict(qs, key=key)
    else:
        queryset = {}
    for o in objects:
        setattr(o, accessor, queryset.get(getattr(o, column)))

