    @wraps(func)
    def wrapped_func(*args, **kwargs):
        start = timer()
        result = func(*args, **kwargs)
        cost = timer() - start
        logger.debug('<method: %s> finished in %2.2f sec' % (func.__name__, cost))
        return result
    return wrapped_func

