def base64_encode(data):
    """Base 64 encoder"""
    total = len(data)
    result = []
    mod = 0
    for i in range(total):
        cur = ord(data[i])
        mod = i % 3
        if mod == 0:
            result.append(__enc64__[cur >> 2])
        elif mod == 1:
            prev = ord(data[i - 1])
            result.append(__enc64__[(prev & 3) << 4 | cur >> 4])
        elif mod == 2:
            prev = ord(data[i - 1])
            result.append(__enc64__[(prev & 15) << 2 | cur >> 6])
            result.append(__enc64__[cur & 63])
    if mod == 0:
        result.append(__enc64__[(cur & 3) << 4])
        result.append(__enc64__[64] * 2)
    elif mod == 1:
        result.append(__enc64__[(cur & 15) << 2])
        result.append(__enc64__[64])
    return ''.join(result)

def base64_decode(data):
    """Base 64 decoder"""
    data = data.replace(__enc64__[64], '')
    total = len(data)
    result = []
    mod = 0
    for i in range(total):
        mod = i % 4
        cur = __enc64__.index(data[i])
        if mod == 0:
            continue
        elif mod == 1:
            prev = __enc64__.index(data[i - 1])
            result.append(chr(prev << 2 | cur >> 4))
        elif mod == 2:
            prev = __enc64__.index(data[i - 1])
            result.append(chr((prev & 15) << 4 | cur >> 2))
        elif mod == 3:
            prev = __enc64__.index(data[i - 1])
            result.append(chr((prev & 3) << 6 | cur))
    return ''.join(result)

def calculate_rates(base_currency, counter_currency, forward_rate=None, fwd_points=None, spot_reference=None):
    """Calculate rates for Fx Forward based on others."""
    if base_currency not in DIVISOR_TABLE:
        divisor = DIVISOR_TABLE.get(counter_currency, DEFAULT_DIVISOR)
        if forward_rate is None and fwd_points is not None and (spot_reference is not None):
            forward_rate = spot_reference + fwd_points / divisor
        elif forward_rate is not None and fwd_points is None and (spot_reference is not None):
            fwd_points = (forward_rate - spot_reference) * divisor
        elif forward_rate is not None and fwd_points is not None and (spot_reference is None):
            spot_reference = forward_rate - fwd_points / divisor
    rates = {}
    if forward_rate is not None:
        rates['forward_rate'] = forward_rate
    if fwd_points is not None:
        rates['fwd_points'] = fwd_points
    if spot_reference is not None:
        rates['spot_reference'] = spot_reference
    return rates

def interpolate_using_previous(pointlist):
    """Throw
        InterpolationError
            if a key has no non-null values

    Return
        pointlist without gaps"""
    pl = pointlist
    npl = []
    if len(pl) < 1:
        raise InterpolationError('Empty list cannot be interpolated')
    first_nonnull = [None, None]
    for i in [0, 1]:
        for p in pl:
            if p[i] is not None:
                first_nonnull[i] = p[i]
                break
    if first_nonnull[0] == None or first_nonnull[1] == None:
        raise InterpolationError('No non-null values to interpolate against: ' + str(first_nonnull))
    prev_nonnull = first_nonnull
    for p in pl:
        np = list(p)
        for k in [0, 1]:
            if np[k] is None:
                np[k] = prev_nonnull[k]
            else:
                prev_nonnull[k] = np[k]
        npl.append(np)
    return npl

