def line_cont_after_delim(ctx, s, line_len=40, delim=(',',), line_cont_token='&'):
    """Insert newline (with preceeding `line_cont_token`) afer
    passing over a delimiter after traversing at least `line_len`
    number of characters

    Mako convenience function. E.g. fortran does not
    accpet lines of arbitrary length."""
    last = -1
    s = str(s)
    for i, t in enumerate(s):
        if t in delim:
            if i > line_len:
                if last == -1:
                    raise ValueError('No delimiter until already past line_len')
                i = last
                return s[:i + 1] + line_cont_token + '\n ' + line_cont_after_delim(ctx, s[i + 1:], line_len, delim)
            last = i
    return s

def write_path(target, path, value, separator='/'):
    """Write a value deep into a dict building any intermediate keys.

    :param target: a dict to write data to
    :param path: a key or path to a key (path is delimited by `separator`)
    :param value: the value to write to the key
    :keyword separator: the separator used in the path (ex. Could be "." for a
        json/mongodb type of value)"""
    parts = path.split(separator)
    current = target
    for part in parts[:-1]:
        if part not in current:
            current[part] = current = {}
        else:
            current = current[part]
    current[parts[-1]] = value

def read_path(source, path, separator='/'):
    """Read a value from a dict supporting a deep path as a key.

    :param source: a dict to read data from
    :param path: a key or path to a key (path is delimited by `separator`)
    :keyword separator: the separator used in the path (ex. Could be "." for a
        json/mongodb type of value)"""
    parts = path.strip(separator).split(separator)
    current = source
    for part in parts[:-1]:
        if part not in current:
            return
        current = current[part]
        if not isinstance(current, dict):
            return
    return current.get(parts[-1])

def path_exists(source, path, separator='/'):
    """Check a dict for the existence of a value given a path to it.

    :param source: a dict to read data from
    :param path: a key or path to a key (path is delimited by `separator`)
    :keyword separator: the separator used in the path (ex. Could be "." for a
        json/mongodb type of value)"""
    if path == separator and isinstance(source, dict):
        return True
    parts = path.strip(separator).split(separator)
    if not parts:
        return False
    current = source
    for part in parts:
        if not isinstance(current, dict):
            return False
        if part not in current:
            return False
        current = current[part]
    return True

def merge_dictionary(dst, src, extend_lists=False):
    """Recursively merge two dicts.

    Hashes at the root level are NOT overwritten. This can be used to merge two
    dicts using deep key evaluation (with support for merging lists as well).

    There is also logic to handle placeholders (`None`) in lists as documented
    in split_dicts.

    :keyword extend_lists: if true, just extends lists instead of merging them.

    Note: This updates dst."""
    stack = [(dst, src)]
    while stack:
        current_dst, current_src = stack.pop()
        for key in current_src:
            source = current_src[key]
            if key not in current_dst:
                current_dst[key] = source
            else:
                dest = current_dst[key]
                if isinstance(source, dict) and isinstance(dest, dict):
                    stack.append((dest, source))
                elif isinstance(source, list) and isinstance(dest, list):
                    merge_lists(dest, source, extend_lists=extend_lists)
                else:
                    current_dst[key] = source
    return dst

def merge_lists(dest, source, extend_lists=False):
    """Recursively merge two lists.

    :keyword extend_lists: if true, just extends lists instead of merging them.

    This applies merge_dictionary if any of the entries are dicts.
    Note: This updates dest and returns it."""
    if not source:
        return
    if not extend_lists:
        left = dest
        right = source[:]
        if len(dest) > len(source):
            right.extend([None] * (len(dest) - len(source)))
        elif len(dest) < len(source):
            left.extend([None] * (len(source) - len(dest)))
        for index, value in enumerate(left):
            if value is None and right[index] is not None:
                dest[index] = right[index]
            elif isinstance(value, dict) and isinstance(right[index], dict):
                merge_dictionary(dest[index], source[index], extend_lists=extend_lists)
            elif isinstance(value, list):
                merge_lists(value, right[index])
            elif right[index] is not None:
                dest[index] = right[index]
    else:
        dest.extend([src for src in source if src not in dest])
    return dest

def kwarg(string, separator='='):
    """Return a dict from a delimited string."""
    if separator not in string:
        raise ValueError("Separator '%s' not in value '%s'" % (separator, string))
    if string.strip().startswith(separator):
        raise ValueError("Value '%s' starts with separator '%s'" % (string, separator))
    if string.strip().endswith(separator):
        raise ValueError("Value '%s' ends with separator '%s'" % (string, separator))
    if string.count(separator) != 1:
        raise ValueError("Value '%s' should only have one '%s' separator" % (string, separator))
    key, value = string.split(separator)
    return {key: value}

def install_gitflow():
    """Install git-flow if not found"""
    if not run('which git-flow', hide=True, warn=True).ok:
        run('wget --no-check-certificate -q -O /tmp/gitflow-installer.sh  https://raw.github.com/petervanderdoes/gitflow/develop/contrib/gitflow-installer.sh')
        run('sudo bash /tmp/gitflow-installer.sh install stable')
        run('rm /tmp/gitflow-installer.sh')

def next_release(major=False, minor=False, patch=True):
    """Get next release version (by major, minor or patch)"""
    import semantic_version
    prev = run('git describe --abbrev=0 --tags', warn=True, hide=True).stdout or '0.0.0'
    ver = semantic_version.Version.coerce(prev.strip())
    print('current version:', ver)
    if major:
        print('next major release:', ver.next_major())
        return ver.next_major()
    if minor:
        print('next minor release:', ver.next_minor())
        return ver.next_minor()
    if patch:
        print('next patch release:', ver.next_patch())
        return ver.next_patch()
    print('next release <undefined>')
    return None

def _iter_changelog(changelog):
    """Convert a oneline log iterator to formatted strings.

    :param changelog: An iterator of one line log entries like
        that given by _iter_log_oneline.
    :return: An iterator over (release, formatted changelog) tuples."""
    first_line = True
    current_release = None
    prev_msg = None
    yield (current_release, 'Changelog\n=========\n\n')
    for hash, tags, msg in changelog:
        if prev_msg is None:
            prev_msg = msg
        elif prev_msg.lower() == msg.lower():
            continue
        else:
            prev_msg = msg
        if tags:
            current_release = max(tags, key=pkg_resources.parse_version)
            underline = len(current_release) * '-'
            if not first_line:
                yield (current_release, '\n')
            yield (current_release, '%(tag)s\n%(underline)s\n\n' % dict(tag=current_release, underline=underline))
        if not msg.startswith('Merge '):
            if msg.endswith('.'):
                msg = msg[:-1]
            yield (current_release, '* %(msg)s\n' % dict(msg=msg))
        first_line = False

def _iter_log_inner(debug):
    """Iterate over --oneline log entries.

    This parses the output intro a structured form but does not apply
    presentation logic to the output - making it suitable for different
    uses.

    :return: An iterator of (hash, tags_set, 1st_line) tuples."""
    if debug:
        print('Generating ChangeLog')
    changelog = run('git log --oneline --decorate', hide=True).stdout.strip().decode('utf-8', 'replace')
    for line in changelog.split('\n'):
        line_parts = line.split()
        if len(line_parts) < 2:
            continue
        if line_parts[1].startswith('(') and ')' in line:
            msg = line.split(')')[1].strip()
        else:
            msg = ' '.join(line_parts[1:])
        if 'tag:' in line:
            tags = set([tag.split(',')[0] for tag in line.split(')')[0].split('tag: ')[1:]])
        else:
            tags = set()
        yield (line_parts[0], tags, msg)

def write_changelog(debug=False):
    """Write a changelog based on the git changelog."""
    changelog = _iter_log_oneline(debug)
    if changelog:
        changelog = _iter_changelog(changelog)
    if not changelog:
        return
    if debug:
        print('Writing ChangeLog')
    new_changelog = os.path.join(os.path.curdir, 'ChangeLog')
    if os.path.exists(new_changelog) and (not os.access(new_changelog, os.W_OK)):
        return
    with io.open(new_changelog, 'w', encoding='utf-8') as changelog_file:
        for release, content in changelog:
            changelog_file.write(content)

def publish(idx=None):
    """Publish packaged distributions to pypi index"""
    if idx is None:
        idx = ''
    else:
        idx = '-r ' + idx
    run('python setup.py register {}'.format(idx))
    run('twine upload {} dist/*.whl dist/*.egg dist/*.tar.gz'.format(idx))

def clean(all=False, docs=False, dist=False, extra=None):
    """Clean up build files"""
    run('find . -type f -name "*.py[co]" -delete')
    run('find . -type d -name "__pycache__" -delete')
    patterns = ['build', '*.egg-info/']
    if all or docs:
        patterns.append('doc/build/*')
    if all or dist:
        patterns.append('dist')
    if extra:
        patterns.append(extra)
    for pattern in patterns:
        run('rm -rf {}'.format(pattern))

def iteritems(d, **kw):
    """Return an iterator over the (key, value) pairs of a dictionary."""
    if not PY2:
        return iter(d.items(**kw))
    return d.iteritems(**kw)

def itervalues(d, **kw):
    """Return an iterator over the values of a dictionary."""
    if not PY2:
        return iter(d.values(**kw))
    return d.itervalues(**kw)

def cursor():
    """Database cursor generator. Commit on context exit."""
    try:
        cur = conn.cursor()
        yield cur
    except (db.Error, Exception) as e:
        cur.close()
        if conn:
            conn.rollback()
        print(e.message)
        raise
    else:
        conn.commit()
        cur.close()

def execute_git_command(command, repo_dir=None):
    """Execute a git command and return the output.

    Catches CalledProcessErrors and OSErrors, wrapping them
    in a more useful :class:`~simpl.exceptions.SimplGitCommandError`.

    Raises :class:`~simpl.exceptions.SimplGitCommandError` if the command
    fails. Returncode and output from the attempt can be found in the
    SimplGitCommandError attributes."""
    try:
        output = shell.execute(command, cwd=repo_dir)
    except exceptions.SimplCalledProcessError as err:
        raise exceptions.SimplGitCommandError(err.returncode, err.cmd, output=err.output)
    except OSError as err:
        raise exceptions.SimplGitCommandError(127, command, output=repr(err), oserror=err)
    else:
        return output

def git_clone(target_dir, repo_location, branch_or_tag=None, verbose=True):
    """Clone repo at repo_location to target_dir and checkout branch_or_tag.

    If branch_or_tag is not specified, the HEAD of the primary
    branch of the cloned repo is checked out."""
    target_dir = pipes.quote(target_dir)
    command = ['git', 'clone']
    if verbose:
        command.append('--verbose')
    if os.path.isdir(repo_location):
        command.append('--no-hardlinks')
    command.extend([pipes.quote(repo_location), target_dir])
    if branch_or_tag:
        command.extend(['--branch', branch_or_tag])
    return execute_git_command(command)

def git_tag(repo_dir, tagname, message=None, force=True):
    """Create an annotated tag at the current head."""
    message = message or '%s' % tagname
    command = ['git', 'tag', '--annotate', '--message', message]
    if force:
        command.append('--force')
    command.append(tagname)
    return execute_git_command(command, repo_dir=repo_dir)

def git_list_config(repo_dir):
    """Return a list of the git configuration."""
    command = ['git', 'config', '--list']
    raw = execute_git_command(command, repo_dir=repo_dir).splitlines()
    output = {key: val for key, val in [cfg.split('=', 1) for cfg in raw]}
    return output

def git_list_tags(repo_dir, with_messages=False):
    """Return a list of git tags for the git repo in `repo_dir`."""
    command = ['git', 'tag', '-l']
    if with_messages:
        command.append('-n1')
    raw = execute_git_command(command, repo_dir=repo_dir).splitlines()
    output = [l.strip() for l in raw if l.strip()]
    if with_messages:
        output = [tuple((j.strip() for j in line.split(None, 1))) for line in output]
    return output

def git_ls_remote(repo_dir, remote='origin', refs=None):
    """Run git ls-remote.

    'remote' can be a remote ref in a local repo, e.g. origin,
    or url of a remote repository.

    Return format:

    .. code-block:: python

        {<ref1>: <commit_hash1>,
         <ref2>: <commit_hash2>,
         ...,
         <refN>: <commit_hashN>,
        }"""
    command = ['git', 'ls-remote', pipes.quote(remote)]
    if refs:
        if isinstance(refs, list):
            command.extend(refs)
        else:
            command.append(refs)
    raw = execute_git_command(command, repo_dir=repo_dir).splitlines()
    output = [l.strip() for l in raw if l.strip() and (not l.strip().lower().startswith('from '))]
    return {ref: commit_hash for commit_hash, ref in [l.split(None, 1) for l in output]}

def git_branch(repo_dir, branch_name, start_point='HEAD', force=True, verbose=True, checkout=False):
    """Create a new branch like `git branch <branch_name> <start_point>`."""
    command = ['git', 'branch']
    if verbose:
        command.append('--verbose')
    if force:
        command.append('--force')
    command.extend([branch_name, start_point])
    branch_output = execute_git_command(command, repo_dir=repo_dir)
    if checkout:
        return git_checkout(repo_dir, branch_name)
    else:
        return branch_output

def git_checkout(repo_dir, ref, branch=None):
    """Do a git checkout of `ref` in `repo_dir`.

    If branch is specified it should be the name of the new branch."""
    command = ['git', 'checkout', '--force']
    if branch:
        command.extend(['-B', '{}'.format(branch)])
    command.append(ref)
    return execute_git_command(command, repo_dir=repo_dir)

def git_fetch(repo_dir, remote=None, refspec=None, verbose=False, tags=True):
    """Do a git fetch of `refspec` in `repo_dir`.

    If 'remote' is None, all remotes will be fetched."""
    command = ['git', 'fetch']
    if not remote:
        command.append('--all')
    else:
        remote = pipes.quote(remote)
    command.extend(['--update-head-ok'])
    if tags:
        command.append('--tags')
    if verbose:
        command.append('--verbose')
    if remote:
        command.append(remote)
    if refspec:
        command.append(refspec)
    return execute_git_command(command, repo_dir=repo_dir)

def git_pull(repo_dir, remote='origin', ref=None, update_head_ok=False):
    """Do a git pull of `ref` from `remote`."""
    command = ['git', 'pull']
    if update_head_ok:
        command.append('--update-head-ok')
    command.append(pipes.quote(remote))
    if ref:
        command.append(ref)
    return execute_git_command(command, repo_dir=repo_dir)

def git_commit(repo_dir, message=None, amend=False, stage=True):
    """Commit any changes, optionally staging all changes beforehand."""
    if stage:
        git_add_all(repo_dir)
    command = ['git', 'commit', '--allow-empty']
    if amend:
        command.append('--amend')
        if not message:
            command.append('--no-edit')
    if message:
        command.extend(['--message', pipes.quote(message)])
    elif not amend:
        command.extend(['--message=', '--allow-empty-message'])
    return execute_git_command(command, repo_dir=repo_dir)

def is_git_repo(repo_dir):
    """Return True if the directory is inside a git repo."""
    command = ['git', 'rev-parse']
    try:
        execute_git_command(command, repo_dir=repo_dir)
    except exceptions.SimplGitCommandError:
        return False
    else:
        return True

def git_remote_resolve_reference(repo_dir, ref, remote='origin'):
    """Try to find a revision (commit hash) for the ref at 'remote' repo.

    Once you have the revision (commit hash), you can check it out. Of
    course, you may have to fetch it first.

    Note: Borrowed these ideas from Chef

        https://github.com/chef/chef/blob/master/lib/chef/provider/git.rb

    Returns None if no revision is found."""
    ls_refs = git_ls_remote(repo_dir, remote=remote, refs='%s*' % ref)
    if ref == 'HEAD':
        return ls_refs['HEAD']
    else:
        matching_refs = ['refs/tags/%s^{}' % ref, 'refs/heads/%s^{}' % ref, '%s^{}' % ref, 'refs/tags/%s' % ref, 'refs/heads/%s' % ref, ref]
        for _ref in matching_refs:
            if _ref in ls_refs:
                return ls_refs[_ref]

def _cleanup_tempdir(tempdir):
    """Clean up temp directory ignoring ENOENT errors."""
    try:
        shutil.rmtree(tempdir)
    except OSError as err:
        if err.errno != errno.ENOENT:
            raise

def _get_config():
    """Get user docker configuration

    Return: dict"""
    cfg = os.path.expanduser('~/.dockercfg')
    try:
        fic = open(cfg)
        try:
            config = json.loads(fic.read())
        finally:
            fic.close()
    except Exception:
        config = {'rootPath': '/dev/null'}
    if not 'Configs' in config:
        config['Configs'] = {}
    return config

def _get_client(config, url=None, version=None, timeout=None):
    """Get a connection to a docker API (socket or URL)

    By default it will use the base docker-py defaults which
    at the time of writing are using the local socket and
    the 1.4 API

    Set those keys in your configuration tree somehow:

        - docker.url: URL to the docker service
        - docker.version: API version to use

    Return: docker client"""
    if config.get('docker_sock'):
        url = config['docker_sock']
    client = docker.Client(base_url=url)
    if not version:
        if client._version == '1.4':
            client._version = '1.5'
    if getattr(client, '_cfg', None) is None:
        client._cfg = {'Configs': {}, 'rootPath': '/dev/null'}
    client._cfg.update(_get_config())
    return client

def _set_id(infos):
    """ID compatibility hack

    return: dict"""
    if infos:
        cid = None
        if infos.get('Id'):
            cid = infos['Id']
        elif infos.get('ID'):
            cid = infos['ID']
        elif infos.get('id'):
            cid = infos['id']
        if 'Id' not in infos:
            infos['Id'] = cid
        infos.pop('id', None)
        infos.pop('ID', None)
    return infos

def is_running(config, container, *args, **kwargs):
    """Is this container running

    container
        Container id

    Return container"""
    try:
        infos = _get_container_infos(config, container)
        return infos if infos.get('State', {}).get('Running') else None
    except Exception:
        return None

def _parse_image_multilogs_string(config, ret, repo):
    """Parse image log strings into grokable data"""
    image_logs, infos = ([], None)
    if ret and ret.strip().startswith('{') and ret.strip().endswith('}'):
        pushd = 0
        buf = ''
        for char in ret:
            buf += char
            if char == '{':
                pushd += 1
            if char == '}':
                pushd -= 1
            if pushd == 0:
                try:
                    buf = json.loads(buf)
                except Exception:
                    pass
                image_logs.append(buf)
                buf = ''
        image_logs.reverse()
        for l in image_logs:
            if isinstance(l, dict):
                if l.get('status') == 'Download complete' and l.get('id'):
                    infos = _get_image_infos(config, repo)
                    break
    return (image_logs, infos)

def _pull_assemble_error_status(logs):
    """Given input in this form::

        u'{"status":"Pulling repository foo/ubuntubox"}:
        "image (latest) from foo/  ...
         rogress":"complete","id":"2c80228370c9"}'

    construct something like that (load JSON data is possible)::

        [u'{"status":"Pulling repository foo/ubuntubox"',
         {"status":"Download","progress":"complete","id":"2c80228370c9"}]"""
    comment = 'An error occurred pulling your image'
    try:
        for err_log in logs:
            if isinstance(err_log, dict):
                if 'errorDetail' in err_log:
                    if 'code' in err_log['errorDetail']:
                        msg = '\n{0}\n{1}: {2}'.format(err_log['error'], err_log['errorDetail']['code'], err_log['errorDetail']['message'])
                    else:
                        msg = '\n{0}\n{1}'.format(err_log['error'], err_log['errorDetail']['message'])
                    comment += msg
    except Exception as e:
        comment += '%s' % e
    return comment

def remove_container(config, container=None, force=True, v=False, *args, **kwargs):
    """Removes a container from a docker installation

    container
        Container id to remove
    force
        By default, remove a running container, set this
        to notremove it unconditionally
    v
        verbose mode

    Return boolean"""
    err = 'Unknown'
    client = _get_client(config)
    dcontainer = None
    try:
        try:
            dcontainer = _get_container_infos(config, container)['Id']
        except Exception:
            return True
        else:
            if not dcontainer:
                return True
            if is_running(config, dcontainer):
                if not force:
                    utils.error("Container running, won't remove it.")
                    return False
                else:
                    kill(config, dcontainer)
            client.remove_container(dcontainer, v=v)
            try:
                infos = _get_container_infos(config, dcontainer)
                if not infos:
                    return True
            except Exception:
                return True
    except Exception as e:
        err = e
    utils.error('Unable to remove container: %s' % err)
    return False

def generate_hosts(config, app):
    """app: {
        "container id": continer details
        ...
    }"""
    hosts = {}
    for container in app:
        hosts[app[container]['NetworkSettings']['IPAddress']] = [app[container]['Name'].replace('/', '')]
    for container in app:
        path = app[container]['HostsPath'] if boot2docker.has() is not True else os.path.join(config['config_path'], 'docker', 'containers', app[container]['Id'], 'hosts')
        try:
            with open(path, 'r+') as f:
                for host in hosts:
                    f.write('%s\t%s\n' % (host, ' '.join(hosts[host])))
        except Exception as e:
            utils.error(e)

def p_Body(p):
    """Body : Line
         | Body Line"""
    if not isinstance(p[1], Body):
        p[0] = Body(None, p[1])
    else:
        p[0] = Body(p[1], p[2])

def p_Statement(p):
    """Statement : StatementWithoutTerminator Terminator"""
    if len(p) < 3:
        term = Terminator('')
    else:
        term = p[2]
    p[0] = Statement(p[1], term)

def p_AccessObj(p):
    """AccessObj : Expression DOT INDENTIFIER
              | Expression LBRACKET Expression RBRACKET
              | Expression LBRACKET RBRACKET"""
    if len(p) <= 4:
        if p[2] == '.':
            p[0] = AccessObj(p[1], p[3], None)
        else:
            p[0] = AccessObj(p[1], None, None)
    else:
        p[0] = AccessObj(p[1], None, p[3])

def p_ArrayLiteralContentList(p):
    """ArrayLiteralContentList : ArrayLiteralContent
                            | ArrayLiteralContentList COMMA ArrayLiteralContent"""
    if len(p) < 3:
        p[0] = ArrayLiteralContentList(None, p[1])
    else:
        p[0] = ArrayLiteralContentList(p[1], p[3])

def p_Varible(p):
    """Varible : NsContentName
            | NsContentName SCOPEOP INDENTIFIER
            | NsContentName SCOPEOP CLASS
            | STATIC SCOPEOP INDENTIFIER"""
    if len(p) < 3:
        p[0] = Varible(None, p[1])
    else:
        p[0] = Varible(p[1], p[3])

def p_ArgList(p):
    """ArgList :
            | Arg
            | ArgList COMMA Arg"""
    if len(p) == 1:
        p[0] = ArgList(None, None)
    elif len(p) == 2:
        p[0] = ArgList(None, p[1])
    else:
        p[0] = ArgList(p[1], p[3])

def p_Arg(p):
    """Arg : Expression ThreeDotModifier"""
    if len(p) <= 2:
        p[0] = Arg(p[1], None)
    else:
        p[0] = Arg(p[1], p[2])

def p_ParamList(p):
    """ParamList :
              | Param
              | ParamList COMMA Param"""
    if len(p) == 1:
        p[0] = ParamList(None, None)
    elif len(p) == 2:
        p[0] = ParamList(None, p[1])
    else:
        p[0] = ParamList(p[1], p[3])

def p_Callable(p):
    """Callable : NsContentName LPARENT
             | NsContentName SCOPEOP INDENTIFIER LPARENT
             | Expression LPARENT
             | STATIC SCOPEOP INDENTIFIER LPARENT"""
    if len(p) <= 3:
        p[0] = Callable(p[1], None)
    else:
        p[0] = Callable(p[1], p[3])

def p_NsContentName(p):
    """NsContentName : INDENTIFIER
                  | NAMESPACEBEFORESLASH
                  | SLASH INDENTIFIER
                  | NsContentName SLASH INDENTIFIER"""
    if len(p) == 2:
        p[0] = NsContentName(None, p[1])
    elif len(p) == 3:
        p[0] = NsContentName(None, p[1] + p[2])
    else:
        p[0] = NsContentName(p[1], p[2] + p[3])

def p_NsContentNameList(p):
    """NsContentNameList : NsContentName
                      | NsContentNameList COMMA NsContentName"""
    if len(p) == 2:
        p[0] = NsContentNameList(None, p[1])
    else:
        p[0] = NsContentNameList(p[1], p[3])

def p_NsContentNameAsId(p):
    """NsContentNameAsId : DefOrConstModifier NsContentName
                      | DefOrConstModifier NsContentName AS INDENTIFIER"""
    if len(p) <= 3:
        p[0] = NsContentNameAsId(p[1], p[2], None)
    else:
        p[0] = NsContentNameAsId(p[1], p[2], p[4])

def p_NsContentNameAsIdList(p):
    """NsContentNameAsIdList : NsContentNameAsId
                          | NsContentNameAsIdList COMMA NsContentNameAsId"""
    if len(p) == 2:
