def log_level(conf):
    """Get debug settings from arguments.

    --debug: turn on additional debug code/inspection (implies
             logging.DEBUG)

    --verbose: turn up logging output (logging.DEBUG)

    --quiet: turn down logging output (logging.WARNING)

    Default is logging.INFO"""
    if conf.debug is True:
        return logging.DEBUG
    elif conf.verbose is True:
        return logging.DEBUG
    elif conf.quiet is True:
        return logging.WARNING
    else:
        return logging.INFO

def configure(conf, default_config=None):
    """Configure logging based on log config file.

    Turn on console logging if no logging files found

    :param conf: object with configuration namespace (argparse parser)"""
    if conf.logconfig and os.path.isfile(conf.logconfig):
        logging.config.fileConfig(conf.logconfig, disable_existing_loggers=False)
    elif default_config and os.path.isfile(default_config):
        logging.config.fileConfig(default_config, disable_existing_loggers=False)
    else:
        init_console_logging(conf)

def _get_debug_formatter(conf):
    """Get debug formatter based on configuration.

    :param conf: configurtration namespace (ex. argparser)

    --debug: log line numbers, file data
    --verbose: standard log format at a DEBUG loglevel
    --quiet: turn down logging output (logging.WARNING)
    default is logging.INFO"""
    if conf.debug is True:
        return DebugFormatter('%(pathname)s:%(lineno)d: %(levelname)-8s %(message)s')
    elif conf.verbose is True:
        return logging.Formatter('%(name)-30s: %(levelname)-8s %(message)s')
    elif conf.quiet is True:
        return logging.Formatter('%(message)s')
    else:
        return logging.Formatter(logging.BASIC_FORMAT)

def mem(data):
    """Total memory used by data

    Parameters
    ----------
    data : dict of pandas.DataFrames or pandas.DataFrame

    Returns
    -------
    str : str
        Human readable amount of memory used with unit (like KB, MB, GB etc.)."""
    if type(data) == dict:
        num = sum([data[k].memory_usage(index=True).sum() for k in data])
    else:
        num = data.memory_usage(index=True).sum()
    for x in ['bytes', 'KB', 'MB', 'GB', 'TB']:
        if num < 1024.0:
            return '%3.1f %s' % (num, x)
        num /= 1024.0
    return '%3.1f %s' % (num, 'PB')

def _find_key_cols(df):
    """Identify columns in a DataFrame that could be a unique key"""
    keys = []
    for col in df:
        if len(df[col].unique()) == len(df[col]):
            keys.append(col)
    return keys

def parse_request(api_secret, reqbody, dec_func=False):
    """>>> parse_request("123456",'{"nonce": 1451122677, "msg": "helllo", "code": 0, "sign": "DB30F4D1112C20DFA736F65458F89C64"}')
    <Storage {u'nonce': 1451122677, u'msg': u'helllo', u'code': 0, u'sign': u'DB30F4D1112C20DFA736F65458F89C64'}>"""
    try:
        if type(reqbody) == type(dict):
            return self.parse_form_request(reqbody)
        if callable(dec_func):
            req_msg = json.loads(dec_func(reqbody))
        else:
            req_msg = json.loads(reqbody)
    except Exception as err:
        raise ParseError(u'parse params error')
    if not check_sign(api_secret, req_msg):
        raise SignError(u'message sign error')
    return Storage(req_msg)

def parse_form_request(api_secret, request):
    """>>> parse_form_request("123456",{"nonce": 1451122677, "msg": "helllo", "code": 0, "sign": "DB30F4D1112C20DFA736F65458F89C64"})
    <Storage {'nonce': 1451122677, 'msg': 'helllo', 'code': 0, 'sign': 'DB30F4D1112C20DFA736F65458F89C64'}>"""
    if not check_sign(api_secret, request):
        raise SignError(u'message sign error')
    return Storage(request)

def jshint():
    """Runs jshint checks."""
    with fab_settings(warn_only=True):
        needs_to_abort = False
        if 2 not in env.ok_ret_codes:
            env.ok_ret_codes.append(2)
        output = local('find -name "{}" -print'.format('*.js'), capture=True)
        files = output.split()
        jshint_installed = local('command -v jshint', capture=True)
        if not jshint_installed.succeeded:
            warn(red('To enable an extended check of your js files, please install jshint by entering:\n\n    npm install -g jshint'))
        else:
            for file in files:
                if hasattr(settings, 'JSHINT_CHECK_EXCLUDES'):
                    excludes = settings.JSHINT_CHECK_EXCLUDES
                else:
                    excludes = settings.SYNTAX_CHECK_EXCLUDES
                if any((s in file for s in excludes)):
                    continue
                jshint_result = local('jshint {0}'.format(file), capture=True)
                if jshint_result:
                    warn(red('JS errors detected in file {0}'.format(file)))
                    puts(jshint_result)
                    needs_to_abort = True
        if needs_to_abort:
            abort(red('There have been errors. Please fix them and run the check again.'))
        else:
            puts(green('jshint found no errors. Very good!'))

def syntax_check():
    """Runs flake8 against the codebase."""
    with fab_settings(warn_only=True):
        for file_type in settings.SYNTAX_CHECK:
            needs_to_abort = False
            if 1 not in env.ok_ret_codes:
                env.ok_ret_codes.append(1)
            output = local('find -name "{}" -print'.format(file_type), capture=True)
            files = output.split()
            for file in files:
                if any((s in file for s in settings.SYNTAX_CHECK_EXCLUDES)):
                    continue
                result = local('egrep -i -n "{0}" {1}'.format(settings.SYNTAX_CHECK[file_type], file), capture=True)
                if result:
                    warn(red("Syntax check found in '{0}': {1}".format(file, result)))
                    needs_to_abort = True
            if needs_to_abort:
                abort(red('There have been errors. Please fix them and run the check again.'))
            else:
                puts(green('Syntax check found no errors. Very good!'))

