def read_output(filename):
    """Reads in a Tarquin txt results file and returns a dict of the information

    :param filename: The filename to read from
    :return:"""
    with open(filename) as fin:
        data = fin.read()
        metabolite_fits = {}
        sections = data.split('\n\n')
        metabolite_lines = sections[0].splitlines()[2:]
        for line in metabolite_lines:
            name, concentration, pc_sd, sd = line.split()
            metabolite_fits[name] = {'concentration': concentration, 'sd': pc_sd}
        return {'metabolite_fits': metabolite_fits}

def update_timestampable_model(sender, instance, *args, **kwargs):
    """Using signals guarantees that timestamps are set no matter what:
    loading fixtures, bulk inserts, bulk updates, etc.
    Indeed, the `save()` method is *not* called when using fixtures."""
    if not isinstance(instance, TimestampableModel):
        return
    if not instance.pk:
        instance.created_at = now()
    instance.updated_at = now()

def elem_to_internal(elem, strip_ns=1, strip=1):
    """Convert an Element into an internal dictionary (not JSON!)."""
    d = {}
    elem_tag = elem.tag
    if strip_ns:
        elem_tag = strip_tag(elem.tag)
    else:
        for key, value in list(elem.attrib.items()):
            d['@' + key] = value
    for subelem in elem:
        v = elem_to_internal(subelem, strip_ns=strip_ns, strip=strip)
        tag = subelem.tag
        if strip_ns:
            tag = strip_tag(subelem.tag)
        value = v[tag]
        try:
            d[tag].append(value)
        except AttributeError:
            d[tag] = [d[tag], value]
        except KeyError:
            d[tag] = value
    text = elem.text
    tail = elem.tail
    if strip:
        if text:
            text = text.strip()
        if tail:
            tail = tail.strip()
    if tail:
        d['#tail'] = tail
    if d:
        if text:
            d['#text'] = text
    else:
        d = text or None
    return {elem_tag: d}

def internal_to_elem(pfsh, factory=ET.Element):
    """Convert an internal dictionary (not JSON!) into an Element.

    Whatever Element implementation we could import will be
    used by default; if you want to use something else, pass the
    Element class as the factory parameter."""
    attribs = {}
    text = None
    tail = None
    sublist = []
    tag = list(pfsh.keys())
    if len(tag) != 1:
        raise ValueError('Illegal structure with multiple tags: %s' % tag)
    tag = tag[0]
    value = pfsh[tag]
    if isinstance(value, dict):
        for k, v in list(value.items()):
            if k[:1] == '@':
                attribs[k[1:]] = v
            elif k == '#text':
                text = v
            elif k == '#tail':
                tail = v
            elif isinstance(v, list):
                for v2 in v:
                    sublist.append(internal_to_elem({k: v2}, factory=factory))
            else:
                sublist.append(internal_to_elem({k: v}, factory=factory))
    else:
        text = value
    e = factory(tag, attribs)
    for sub in sublist:
        e.append(sub)
    e.text = text
    e.tail = tail
    return e

def elem2json(elem, options, strip_ns=1, strip=1):
    """Convert an ElementTree or Element into a JSON string."""
    if hasattr(elem, 'getroot'):
        elem = elem.getroot()
    if options.pretty:
        return json.dumps(elem_to_internal(elem, strip_ns=strip_ns, strip=strip), sort_keys=True, indent=4, separators=(',', ': '))
    else:
        return json.dumps(elem_to_internal(elem, strip_ns=strip_ns, strip=strip))

def json2elem(json_data, factory=ET.Element):
    """Convert a JSON string into an Element.

    Whatever Element implementation we could import will be used by
    default; if you want to use something else, pass the Element class
    as the factory parameter."""
    return internal_to_elem(json.loads(json_data), factory)

def xml2json(xmlstring, options, strip_ns=1, strip=1):
    """Convert an XML string into a JSON string."""
    elem = ET.fromstring(xmlstring)
    return elem2json(elem, options, strip_ns=strip_ns, strip=strip)

def json2xml(json_data, factory=ET.Element):
    """Convert a JSON string into an XML string.

    Whatever Element implementation we could import will be used by
    default; if you want to use something else, pass the Element class
    as the factory parameter."""
    if not isinstance(json_data, dict):
        json_data = json.loads(json_data)
    elem = internal_to_elem(json_data, factory)
    return ET.tostring(elem)

def wrap_object(func, before, after):
    """before/after call will encapsulate callable object"""
    def _wrapper(*args, **kwargs):
        before()
        try:
            return func(*args, **kwargs)
        except Exception as e:
            raise e
        finally:
            after()
    return _wrapper

def natural_sort(item):
    '''Sort strings that contain numbers correctly.

    >>> l = ['v1.3.12', 'v1.3.3', 'v1.2.5', 'v1.2.15', 'v1.2.3', 'v1.2.1']
    >>> l.sort(key=natural_sort)
    >>> print l
    "['v1.2.1', 'v1.2.3', 'v1.2.5', 'v1.2.15', 'v1.3.3', 'v1.3.12']"'''
    if item is None:
        return 0
    def try_int(s):
        try:
            return int(s)
        except ValueError:
            return s
    return tuple(map(try_int, re.findall('(\\d+|\\D+)', item)))

def propagate_defaults(config_doc):
    """Propagate default values to sections of the doc."""
    for group_name, group_doc in config_doc.items():
        if isinstance(group_doc, dict):
            defaults = group_doc.get('defaults', {})
            for item_name, item_doc in group_doc.items():
                if item_name == 'defaults':
                    continue
                if isinstance(item_doc, dict):
                    group_doc[item_name] = dict_merge_pair(copy.deepcopy(defaults), item_doc)
    return config_doc

def validipaddr(address):
    """Returns True if `address` is a valid IPv4 address.

        >>> validipaddr('192.168.1.1')
        True
        >>> validipaddr('192.168.1.800')
        False
        >>> validipaddr('192.168.1')
        False"""
    try:
        octets = address.split('.')
        if len(octets) != 4:
            return False
        for x in octets:
            if not 0 <= int(x) <= 255:
                return False
    except ValueError:
        return False
    return True

def parsehttpdate(string_):
    """Parses an HTTP date into a datetime object.

        >>> parsehttpdate('Thu, 01 Jan 1970 01:01:01 GMT')
        datetime.datetime(1970, 1, 1, 1, 1, 1)"""
    try:
        t = time.strptime(string_, '%a, %d %b %Y %H:%M:%S %Z')
    except ValueError:
        return None
    return datetime.datetime(*t[:6])

def strip_non_ascii(string):
    """Returns the string without non ASCII characters"""
    if type(string) == datetime:
        return str(string)
    stripped = (c for c in string if 0 < ord(c) < 127)
    return ''.join(stripped)

