def vd(inc, sd):
    """Calculate vertical distance.

    :param inc: (float) inclination angle in degrees
    :param sd:  (float) slope distance in any units"""
    return abs(sd * math.sin(math.radians(inc)))

def get_week_start_end_day():
    """Get the week start date and end date"""
    t = date.today()
    wd = t.weekday()
    return (t - timedelta(wd), t + timedelta(6 - wd))

