def build_application(conf):
    """Do some setup and return the wsgi app."""
    if isinstance(conf.adapter_options, list):
        conf['adapter_options'] = {key: val for _dict in conf.adapter_options for key, val in _dict.items()}
    elif conf.adapter_options is None:
        conf['adapter_options'] = {}
    else:
        conf['adapter_options'] = copy.copy(conf.adapter_options)
    conf['app'] = conf.app or bottle.default_app()
    if isinstance(conf.app, six.string_types):
        conf['app'] = bottle.load_app(conf.app)
    def _find_bottle_app(_app):
        """Lookup the underlying Bottle() instance."""
        while hasattr(_app, 'app'):
            if isinstance(_app, bottle.Bottle):
                break
            _app = _app.app
        assert isinstance(_app, bottle.Bottle), 'Could not find Bottle app.'
        return _app
    bottle_app = _find_bottle_app(conf.app)
    bottle_app.route(path='/_simpl', method='GET', callback=_version_callback)
    def _show_routes():
        """Conditionally print the app's routes."""
        if conf.app and (not conf.quiet):
            if conf.reloader and os.getenv('BOTTLE_CHILD'):
                LOG.info('Running bottle server with reloader.')
            elif not conf.reloader:
                pass
            else:
                return
            routes = fmt_routes(bottle_app)
            if routes:
                print('\n{}'.format(routes), end='\n\n')
    _show_routes()
    return conf.app

def run(conf, build_app=True):
    """Run server based on this configuration.

    If build_app is True, simpl will use your config to build
    and configure your wsgi application. If you have built and
    configured your application (conf.app) already, set build_app
    to false.

    Expects configuration options defined in server.OPTIONS"""
    if build_app:
        build_application(conf)
    if conf.app and os.getcwd() not in sys.path:
        sys.path.append(os.getcwd())
    return bottle.run(app=conf.app, server=conf.server, host=conf.host, port=conf.port, interval=conf.interval, reloader=conf.reloader, quiet=conf.quiet, debug=conf.debug, **conf.adapter_options)

def transform_q(q, query):
    """Replaces (lookup, value) children of Q with equivalent WhereNode objects.

    This is a pre-prep of our Q object, ready for later rendering into SQL.
    Modifies in place, no need to return.

    (We could do this in render_q, but then we'd have to pass the Query object
    from ConditionalAggregate down into SQLConditionalAggregate, which Django
    avoids to do in their API so we try and follow their lead here)"""
    for i, child in enumerate(q.children):
        if isinstance(child, Q):
            transform_q(child, query)
        else:
            where_node = query.build_filter(child)
            q.children[i] = where_node

def render_q(q, qn, connection):
    """Renders the Q object into SQL for the WHEN clause.

    Uses as much as possible the Django ORM machinery for SQL generation,
    handling table aliases, field quoting, parameter escaping etc.

    :param q: Q object representing the filter condition
    :param qn: db specific 'quote names' function that was passed into
        SQLAggregate.as_sql method by Django
    :param connection: Django db connection object that was passed into
        SQLAggregate.as_sql method by Django

    :returns:  (SQL template str, params list) tuple"""
    joinstr = u' {} '.format(q.connector)
    conditions = []
    params = []
    if DJANGO_MAJOR == 1 and DJANGO_MINOR == 7:
        try:
            qn = qn.__self__
        except AttributeError:
            pass
    for child in q.children:
        if isinstance(child, Q):
            condition, child_params = render_q(child, qn, connection)
            conditions.append(u'({})'.format(condition))
            params.extend(child_params)
        else:
            try:
                child, joins_used = child
            except TypeError:
                pass
            condition, child_params = child.as_sql(qn, connection)
            params.extend(child_params)
            conditions.append(condition)
    rendered = u'({})'.format(joinstr.join(conditions))
    if q.negated:
        rendered = u'NOT {}'.format(rendered)
    return (rendered, params)

def timethis(label, receiver_fn=None):
    """Times a block of code
    Inspired from David Beazley talk - Generators: The Final Frontier"""
    start = time.time()
    try:
        yield
    finally:
        end = time.time()
        if receiver_fn:
            receiver_fn(label, start, end)
        else:
            print('{}: {} to {} -> {} seconds'.format(label, start, end, end - start))

def assert_or_raise(stmt: bool, exception: Exception, *exception_args, **exception_kwargs) -> None:
    """If the statement is false, raise the given exception."""
    if not stmt:
        raise exception(*exception_args, **exception_kwargs)

