def add_xml_declaration(fn):
    """Decorator to add header with XML version declaration to output from FN."""
    @wraps(fn)
    def add_xml_declaration_decorator(*args, **kwargs):
        return '<?xml version="1.0" encoding="UTF-8"?>\n\n' + fn(*args, **kwargs)
    return add_xml_declaration_decorator

def fix_missing_lang_tags(marc_xml, dom):
    """If the lang tags are missing, add them to the MODS. Lang tags are parsed
    from `marc_xml`."""
    def get_lang_tag(lang):
        lang_str = '\n  <mods:language>\n'
        lang_str += '    <mods:languageTerm authority="iso639-2b" type="code">'
        lang_str += lang
        lang_str += '</mods:languageTerm>\n'
        lang_str += '  </mods:language>\n\n'
        lang_dom = dhtmlparser.parseString(lang_str)
        return first(lang_dom.find('mods:language'))
    for lang in reversed(marc_xml['041a0 ']):
        lang_tag = dom.find('mods:languageTerm', fn=lambda x: x.getContent().strip().lower() == lang.lower())
        if not lang_tag:
            insert_tag(get_lang_tag(lang), dom.find('mods:language'), get_mods_tag(dom))

def add_suffix(string, suffix):
    """Adds a suffix to a string, if the string does not already have that suffix.

    :param string: the string that should have a suffix added to it
    :param suffix: the suffix to be added to the string
    :return: the string with the suffix added, if it does not already end in
        the suffix. Otherwise, it returns the original string."""
    if string[-len(suffix):] != suffix:
        return string + suffix
    else:
        return string

def tuplify(*args):
    """Convert args to a tuple, unless there's one arg and it's a
    function, then acts a decorator."""
    if len(args) == 1 and callable(args[0]):
        func = args[0]
        @wraps(func)
        def _inner(*args, **kwargs):
            return tuple(func(*args, **kwargs))
        return _inner
    else:
        return tuple(args)

def listify(*args):
    """Convert args to a list, unless there's one arg and it's a
    function, then acts a decorator."""
    if len(args) == 1 and callable(args[0]):
        func = args[0]
        @wraps(func)
        def _inner(*args, **kwargs):
            return list(func(*args, **kwargs))
        return _inner
    else:
        return list(args)

def stringify(*args):
    """Joins args to build a string, unless there's one arg and it's a
    function, then acts a decorator."""
    if len(args) == 1 and callable(args[0]):
        func = args[0]
        @wraps(func)
        def _inner(*args, **kwargs):
            return ''.join([str(i) for i in func(*args, **kwargs)])
        return _inner
    else:
        return ''.join([str(i) for i in args])

def add_path_part(url, regex=PATH_PART):
    """replace the variables in a url template with regex named groups
    :param url: string of a url template
    :param regex: regex of the named group
    :returns: regex"""
    formatter = string.Formatter()
    url_var_template = '(?P<{var_name}>{regex})'
    for part in formatter.parse(url):
        string_part, var_name, _, _ = part
        if string_part:
            yield string_part
        if var_name:
            yield url_var_template.format(var_name=var_name, regex=regex)

def make_endpoints(version, name, endpoints, kwargs=None):
    """Returns a redirect handler and all endpoints with a version prefix added.

    :param version: the application version
    :param name: the application name
    :param endpoints: a list of application endpoints
    :param kwargs: an optional dictionary to populate placeholders in endpoints
    :returns:list of endpoints"""
    if kwargs is None:
        kwargs = {}
    version_url_prefix = '/v{}/{}'.format(version.split('.')[0], name)
    yield ('/', RedirectHandler, {'url': '{}'.format(version_url_prefix)})
    for endpoint in add_prefix(endpoints, version_url_prefix, kwargs):
        yield endpoint

def sanitise_capabilities(capabilities):
    """Makes sure dictionary of capabilities includes required options, and does not include protected ones.
    :param capabilities:
    :return: dict"""
    for c in REQUIRED_CAPABILITIES:
        capabilities[c] = options[c]
    for c in PROTECTED_CAPABILITIES:
        if c in capabilities:
            del capabilities['client_secret']
    return capabilities

def split_obj(obj, prefix=None):
    """Split the object, returning a 3-tuple with the flat object, optionally
    followed by the key for the subobjects and a list of those subobjects."""
    new = obj.copy() if prefix is None else {'{}_{}'.format(prefix, k): v for k, v in obj.items()}
    for k, v in new.items():
        if isinstance(v, list):
            if not isinstance(v[0], dict):
                new[k] = ','.join(v)
                return (new, None, None)
            del new[k]
            return (new, k, v)
        elif isinstance(v, dict):
            del new[k]
            return (new, k, [v])
    return (new, None, None)

def flatten_json(data, prefix=None):
    """Flatten the data, optionally with each key prefixed."""
    for item in data:
        flat, key, subs = split_obj(item, prefix)
        if key is None:
            yield flat
            continue
        for sub in flatten_json(subs, key):
            sub.update(flat)
            yield sub

def create_table(dbcon, name, columns):
    """Create a table in the database.
    :param dbcon: database
    :return: True if a new table was created"""
    try:
        colString = ', '.join(['{} {}'.format(colName, colType) for colName, colType in columns])
        dbcon.execute("CREATE TABLE '{name}'({args})".format(name=name, args=colString))
        return True
    except sqlite3.OperationalError as e:
        return False

def get_table_list(dbconn):
    """Get a list of tables that exist in dbconn
    :param dbconn: database connection
    :return: List of table names"""
    cur = dbconn.cursor()
    cur.execute("SELECT name FROM sqlite_master WHERE type='table';")
    try:
        return [item[0] for item in cur.fetchall()]
    except IndexError:
        return get_table_list(dbconn)

def get_number_of_rows(dbcon, tablename, uuid=None):
    """Return the number of rows in a table
    :param dbcon: database connection
    :param tablename: table name
    :return: Boolean"""
    dbcur = dbcon.cursor()
    if check_table_exists(dbcon, tablename):
        if uuid:
            dbcur.execute("SELECT COUNT(*) FROM '{name}' WHERE UUID='{uuid}'".format(name=tablename, uuid=uuid))
        else:
            dbcur.execute("SELECT COUNT(*) FROM '{name}'".format(name=tablename))
        try:
            result = dbcur.fetchone()[0]
        except (TypeError, IndexError) as e:
            logger.error(e)
            result = 0
        dbcur.close()
        return result if isinstance(result, (int, long, float)) else 0
    else:
        return 0

def check_table_exists(dbcon, tablename):
    """Check if a table exists in the database.
    :param dbcon: database connection
    :param tablename: table name
    :return: Boolean"""
    dbcur = dbcon.cursor()
    dbcur.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='%s';" % tablename)
    result = dbcur.fetchone()
    dbcur.close()
    if result is None:
        return False
    else:
        try:
            return result[0] == tablename
        except IndexError as e:
            return check_table_exists(dbcon, tablename)

def fetch(dbconn, tablename, n=1, uuid=None, end=True):
    """Returns `n` rows from the table's start or end
    :param dbconn: database connection
    :param tablename: name of the table
    :param n: number of rows to return from the end of the table
    :param uuid: Optional UUID to select from
    :return: If n > 1, a list of rows. If n=1, a single row"""
    cur = dbconn.cursor()
    order = 'DESC' if end else 'ASC'
    try:
        if uuid:
            cur.execute("SELECT * FROM '{}' WHERE UUID='{}' ORDER BY ROWID {} LIMIT {};".format(tablename, uuid, order, n))
        else:
            cur.execute("SELECT * FROM '{}' ORDER BY ROWID {} LIMIT {};".format(tablename, order, n))
    except sqlite3.OperationalError as e:
        if 'no such table' not in getattr(e, 'message', ''):
            logger.error(e)
        return []
    rows = cur.fetchall()
    return rows

def get_last_row(dbconn, tablename, n=1, uuid=None):
    """Returns the last `n` rows in the table"""
    return fetch(dbconn, tablename, n, uuid, end=True)

def get_first_row(dbconn, tablename, n=1, uuid=None):
    """Returns the first `n` rows in the table"""
    return fetch(dbconn, tablename, n, uuid, end=False)

def best_charset(text):
    """Find the most human-readable and/or conventional encoding for unicode text.

    Prefers `us-ascii` or `iso-8859-1` and falls back to `utf-8`."""
    if isinstance(text, bytes):
        text = text.decode('ascii')
    for charset in ('us-ascii', 'iso-8859-1', 'utf-8'):
        try:
            encoded = text.encode(charset)
        except UnicodeError:
            pass
        else:
            return (charset, encoded)

def is_seq(obj):
    """Check if an object is a sequence."""
    return not is_str(obj) and (not is_dict(obj)) and (hasattr(obj, '__getitem__') or hasattr(obj, '__iter__'))

def dict_values(src):
    """Recursively get values in dict.

    Unlike the builtin dict.values() function, this method will descend into
    nested dicts, returning all nested values.

    Arguments:
        src (dict): Source dict.

    Returns:
        list: List of values."""
    for v in src.values():
        if isinstance(v, dict):
            for v in dict_values(v):
                yield v
        else:
            yield v

def import_split(import_name):
    """takes a dotted string path and returns the components:
    import_split('path') == 'path', None, None
    import_split('path.part.object') == 'path.part', 'object', None
    import_split('path.part:object') == 'path.part', 'object', None
    import_split('path.part:object.attribute')
        == 'path.part', 'object', 'attribute'"""
    obj = None
    attr = None
    if ':' in import_name:
        module, obj = import_name.split(':', 1)
        if '.' in obj:
            obj, attr = obj.rsplit('.', 1)
    elif '.' in import_name:
        module, obj = import_name.rsplit('.', 1)
    else:
        module = import_name
    return (module, obj, attr)

def find_path_package(thepath):
    """Takes a file system path and returns the module object of the python
    package the said path belongs to. If the said path can not be
    determined, it returns None."""
    pname = find_path_package_name(thepath)
    if not pname:
        return None
    fromlist = b'' if six.PY2 else ''
    return __import__(pname, globals(), locals(), [fromlist])

def find_path_package_name(thepath):
    """Takes a file system path and returns the name of the python package
    the said path belongs to.  If the said path can not be determined, it
    returns None."""
    module_found = False
    last_module_found = None
    continue_ = True
    while continue_:
        module_found = is_path_python_module(thepath)
        next_path = path.dirname(thepath)
        if next_path == thepath:
            continue_ = False
        if module_found:
            init_names = ['__init__%s' % suffix.lower() for suffix in _py_suffixes]
            if path.basename(thepath).lower() in init_names:
                last_module_found = path.basename(path.dirname(thepath))
            else:
                last_module_found = path.basename(thepath)
        if last_module_found and (not module_found):
            continue_ = False
        thepath = next_path
    return last_module_found

def is_path_python_module(thepath):
    """Given a path, find out of the path is a python module or is inside
    a python module."""
    thepath = path.normpath(thepath)
    if path.isfile(thepath):
        base, ext = path.splitext(thepath)
        if ext in _py_suffixes:
            return True
        return False
    if path.isdir(thepath):
        for suffix in _py_suffixes:
            if path.isfile(path.join(thepath, '__init__%s' % suffix)):
                return True
    return False

def import_string(import_name, silent=False):
    """Imports an object based on a string.  This is useful if you want to
    use import paths as endpoints or something similar.  An import path can
    be specified either in dotted notation (``xml.sax.saxutils.escape``)
    or with a colon as object delimiter (``xml.sax.saxutils:escape``).

    If `silent` is True the return value will be `None` if the import fails.

    :param import_name: the dotted name for the object to import.
    :param silent: if set to `True` import errors are ignored and
                   `None` is returned instead.
    :return: imported object"""
    try:
        if ':' in import_name:
            module, obj_name = import_name.split(':', 1)
        elif '.' in import_name:
            module, obj_name = import_name.rsplit('.', 1)
        else:
            return __import__(import_name)
        return getattr(__import__(module, None, None, [obj_name]), obj_name)
    except (ImportError, AttributeError):
        if not silent:
            raise

def posargs_limiter(func, *args):
    """takes a function a positional arguments and sends only the number of
    positional arguments the function is expecting"""
    posargs = inspect.getargspec(func)[0]
    length = len(posargs)
    if inspect.ismethod(func):
        length -= 1
    if length == 0:
        return func()
    return func(*args[0:length])

def compose(*functions):
    """Function composition on a series of functions.

    Remember that function composition runs right-to-left: `f . g . h = f(g(h(x)))`. As a unix
    pipeline, it would be written: `h | g | f`.

    From https://mathieularose.com/function-composition-in-python/."""
    return functools.reduce(lambda f, g: lambda x: f(g(x)), functions, identity)

def first_where(pred, iterable, default=None):
    """Returns the first element in an iterable that meets the given predicate.

    :param default: is the default value to use if the predicate matches none of the elements."""
    return next(six.moves.filter(pred, iterable), default)

def partition_iter(pred, iterable):
    """Partitions an iterable with a predicate into two iterables, one with elements satisfying
    the predicate and one with elements that do not satisfy it.

    :returns: a tuple (satisfiers, unsatisfiers)."""
    left, right = itertools.tee(iterable, 2)
    return ((x for x in left if pred(x)), (y for y in right if not pred(y)))

def unzip(iterable):
    """Unzip/transpose an iterable of tuples into a tuple of lists.

    WARNING: When given an empty iterable, this returns an empty list instead of a tuple. If you
    need a consistent interface then do something like this:

        left, right = unzip(two_columned_list) or ([], [])"""
    return list(map(list, list(six.moves.zip(*iterable))))

def split_every(n, iterable):
    """Returns a generator that spits an iteratable into n-sized chunks. The last chunk may have
    less than n elements.

    See http://stackoverflow.com/a/22919323/503377."""
    items = iter(iterable)
    return itertools.takewhile(bool, (list(itertools.islice(items, n)) for _ in itertools.count()))

def _format_output(selected_number, raw_data):
