def slugify(value):
    """Normalizes string, converts to lowercase, removes non-alpha characters,
    and converts spaces to hyphens.

    Took from django sources."""
    value = Markup(value).striptags()
    if type(value) == unicode:
        value = unicode(unidecode(value))
        value = unicodedata.normalize('NFKD', value).encode('ascii', 'ignore')
    value = unicode(re.sub('[^\\w\\s-]', '', value).strip().lower())
    return re.sub('[-\\s]+', '-', value)

def override_params(opening_char='{', closing_char='}', separator_char='|'):
    """Override some character settings

    @type opening_char: str
    @param opening_char: Opening character. Default: '{'
    @type closing_char: str
    @param closing_char: Closing character. Default: '}'
    @type separator_char: str
    @param separator_char: Separator char. Default: '|'"""
    global char_separator, char_opening, char_closing
    char_separator = separator_char
    char_opening = opening_char
    char_closing = closing_char

def _choices(text, randomized=True):
    """Return all the possible choices from the following format: {a|b|c}

    @type text: str
    @param text: Text written used spin syntax

    @type randomized: bool
    @param text: Specifies if the choices will be given in random order or not.

    @return: A generator that yields all the possible choices"""
    if text:
        pattern = '{0}|{1}|{2}'.format(re.escape(char_opening), re.escape(char_closing), re.escape(char_separator))
        choices = [x for x in re.split(pattern, text) if x]
        if randomized:
            random.shuffle(choices)
        for x in choices:
            yield x

def _all_unique_texts(text, final):
    """Compute all the possible unique texts

    @type text: str
    @param text: Text written used spin syntax

    @type final: list
    @param final: An empty list where all the unique texts will be stored
    @return: Nothing. The result will be in the 'final' list"""
    if not char_opening in text:
        if not text in final:
            final.append(text)
        return
    stack = []
    indexes = []
    for i, c in enumerate(text):
        if c == char_closing:
            if stack[-1] == char_opening:
                start_index = indexes.pop()
                substring = '' if i == start_index + 1 else text[start_index:i + 1]
                combination = next(_choices(substring))
                new_text = text.replace(substring, combination)
                _all_unique_texts(new_text, final)
                return
        elif c == char_opening:
            stack.append(c)
            indexes.append(i)

def _is_correct(text):
    """Check if the specified text has a correct spin syntax

    @type text: str
    @param text: Text written used spin syntax

    @rtype: tuple
    @return: A tuple: (is_correct, error). First position contains the result, and second one the error if not correct."""
    error = ''
    stack = []
    for i, c in enumerate(text):
        if c == char_opening:
            stack.append(c)
        elif c == char_closing:
            if stack.count == 0:
                error = 'Syntax incorrect. Found "}" before "{"'
                break
            last_char = stack.pop()
            if last_char != char_opening:
                error = 'Syntax incorrect. Found "}" before "{"'
                break
    if len(stack) > 0:
        error = 'Syntax incorrect. Some "{" were not closed'
    return (not error, error)

def stop(name, file=sys.stderr):
    """Stop a profiling timer.

    Arguments:

        name (str): The name of the timer to stop. If no name is given, stop
            the global anonymous timer.

    Returns:

        bool: Whether or not profiling is enabled.

    Raises:

        KeyError: If the named timer does not exist."""
    if is_enabled():
        elapsed = time() - __TIMERS[name]
        if elapsed > 60:
            elapsed_str = '{:.1f} m'.format(elapsed / 60)
        elif elapsed > 1:
            elapsed_str = '{:.1f} s'.format(elapsed)
        else:
            elapsed_str = '{:.1f} ms'.format(elapsed * 1000)
        del __TIMERS[name]
        print('[prof]', name, elapsed_str, file=file)
    return is_enabled()

def function(fname):
    """Make a function to Function class"""
    def _f(func):
        class WrapFunction(Function):
            name = fname
            def __call__(self, *args, **kwargs):
                return func(*args, **kwargs)
        return WrapFunction
    return _f

def parse_cookie(header, charset='utf-8', errors='ignore'):
    """Parse a cookie.

    :param header: the header to be used to parse the cookie.
    :param charset: the charset for the cookie values.
    :param errors: the error behavior for the charset decoding."""
    cookie = _ExtendedCookie()
    if header:
        cookie.load(header)
    result = {}
    for key, value in cookie.iteritems():
        if value.value is not None:
            result[key] = unquote_header_value(value.value).decode(charset, errors)
    return result

def enable_site(site_name):
    """Enable an available Nginx site."""
    site_available = u'/etc/nginx/sites-available/%s' % site_name
    site_enabled = u'/etc/nginx/sites-enabled/%s' % site_name
    if files.exists(site_available):
        sudo(u'ln -s -f %s %s' % (site_available, site_enabled))
        restart_service(u'nginx')
    else:
        abort(u'%s site configuration is not available' % site_name)

def disable_site(site_name):
    """Disables Nginx site configuration."""
    site = u'/etc/nginx/sites-enabled/%s' % site_name
    if files.exists(site):
        sudo(u'rm %s' % site)
        restart_service(u'nginx')

def suppressConsoleOut(meth):
    """Disable console output during the method is run."""
    @wraps(meth)
    def decorate(*args, **kwargs):
        """Decorate"""
        _stdout = sys.stdout
        fptr = open(os.devnull, 'w')
        sys.stdout = fptr
        try:
            return meth(*args, **kwargs)
        except Exception as e:
            raise e
        finally:
            sys.stdout = _stdout
    return decorate

def registration(uri):
    """httpretty handler registration.

    registers a handler for a given uri with httpretty
    so that it can be intercepted and handed to
    stack-in-a-box.

    :param uri: uri used for the base of the http requests

    :returns: n/a"""
    status_data = {595: 'StackInABoxService - Unknown Route', 596: 'StackInABox - Exception in Service Handler', 597: 'StackInABox - Unknown Service'}
    for k, v in six.iteritems(status_data):
        if k not in httpretty.http.STATUSES:
            httpretty.http.STATUSES[k] = v
    logger.debug('Registering Stack-In-A-Box at {0} under Python HTTPretty'.format(uri))
    StackInABox.update_uri(uri)
    regex = re.compile('(http)?s?(://)?{0}:?(\\d+)?/'.format(uri), re.I)
    for method in HttpBaseClass.METHODS:
        register_uri(method, regex, body=httpretty_callback)

