def find_best_ensemble(results, options):
    """Return the best performing ensemble. If the user hasn't specified a FPF, the default behavior sorts ensembles by
    largest enrichment factor at the smallest FPF (1 / n, where n is the total number of decoys). If the user supplied
    a FPF, ensembles are sorted by the largest enrichment factor at the input FPF. If the user supplied a FPF = 1,
    ensembles are sorted by AUC. Ties are broken by considering enrichment factors at the smallest FPF not already
    considered.
    :param results: {ensemble_storage_object1, ensemble_storage_object2, ..., ensemble_storage_objectn}
    :param options: options object, contains user-specified arguments as attributes.
    :return: ensemble_storage_object (classification.EnsembleStorage) that contains the best performing ensemble"""
    n = sorted(list(list(results.items())[0][1].ef.keys()), reverse=True)[0]
    if not options.fpf:
        ndecoys = 1
    else:
        ndecoys = int(round(n * options.fpf))
    if ndecoys == n:
        prop_key = 'auc'
        sorted_list = sorted(results.items(), key=lambda x: x[1].get_prop(prop_key), reverse=True)
    else:
        prop_key = 'ef'
        sorted_list = sorted(results.items(), key=lambda x: x[1].get_prop(ndecoys, prop_key), reverse=True)
    if len(sorted_list) > 1:
        sorted_list = tie_break(sorted_list, results, prop_key, ndecoys)
    return sorted_list[0][0]

def add_site_list(dir_list):
    """Add a list of pseudo site-packages to :data:`python:sys.path`.

    This centers the list on ``sys.path`` around the current environment.
    I.e. if this environment is in the list, then directories before it in the
    list will be prepended to ``sys.path``, and directories after it will
    be appended to ``sys.path``."""
    our_site_packages = os.path.abspath(os.path.join(sys.prefix, site_package_postfix))
    dir_list = [os.path.abspath(x) for x in dir_list]
    prepend = SysPathInserter(0)
    append = SysPathInserter()
    try:
        our_index = dir_list.index(our_site_packages)
    except ValueError:
        our_index = None
    for i, dir_name in enumerate(dir_list):
        if our_index is None or i < our_index:
            add_site_dir(dir_name, _path=prepend)
        else:
            add_site_dir(dir_name, _path=append)

def add_site_dir(dir_name, before=None, _path=None):
    """Add a pseudo site-packages directory to :data:`python:sys.path`.

    :param str dir_name: The directory to add.
    :param str before: A directory on :data:`sys.path` that new paths should be
    inserted before.

    Looks for ``.pth`` files at the top-level and ``__site__.pth`` files within
    top-level directories."""
    log.log(5, 'add_site_dir(%r, before=%r)', dir_name, before)
    if not os.path.exists(dir_name):
        return
    path = _path or SysPathInserter(index=before)
    path.add(dir_name)
    for file_name in os.listdir(dir_name):
        if file_name.startswith('.'):
            continue
        if file_name.endswith('.pth'):
            _process_pth(path, dir_name, file_name)
        if os.path.exists(os.path.join(dir_name, file_name, '__site__.pth')):
            _process_pth(path, os.path.join(dir_name, file_name), '__site__.pth')

def get_pub_abbreviation(pubstring, numBest=5, exact=None):
    """Get ADS journal abbreviation ("bibstem") candidates for a given publication name.
    * 'exact': if True results will only be returned if an exact match was found
    * 'numBest': maximum number of guesses to return
    A list of tuples will be returned, each tuple consisting of a score and a bibstem"""
    if exact:
        bibstems = _defaultSourcematcher.getExactMatch(string.upper(pubstring))
    else:
        bibstems = _defaultSourcematcher.getBestMatches(string.upper(pubstring), numBest)
        if re.search('L(ett(ers)?)?$', pubstring):
            addit = _defaultSourcematcher.getBestMatches(re.sub('(?i)\\s*L(ett(ers)?)?$', '', pubstring.upper()), 2)
            if addit:
                bibstems.extend(addit)
                bibstems.sort()
    try:
        bibstems = list(set(bibstems))
    except:
        bibstems = []
    bibstems.sort(key=lambda tup: tup[0], reverse=True)
    return bibstems

def _indexOfEndTag(istack):
    """Go through `istack` and search endtag. Element at first index is considered
    as opening tag.

    Args:
        istack (list): List of :class:`.HTMLElement` objects.

    Returns:
        int: Index of end tag or 0 if not found."""
    if len(istack) <= 0:
        return 0
    if not istack[0].isOpeningTag():
        return 0
    cnt = 0
    opener = istack[0]
    for index, el in enumerate(istack[1:]):
        if el.isOpeningTag() and el.getTagName().lower() == opener.getTagName().lower():
            cnt += 1
        elif el.isEndTagTo(opener):
            if cnt == 0:
                return index + 1
            cnt -= 1
    return 0

def removeTags(dom):
    """Remove all tags from `dom` and obtain plaintext representation.

    Args:
        dom (str, obj, array): str, HTMLElement instance or array of elements.

    Returns:
        str: Plain string without tags."""
    try:
        string_type = basestring
    except NameError:
        string_type = str
    element_stack = None
    if type(dom) in [list, tuple]:
        element_stack = dom
    elif isinstance(dom, HTMLElement):
        element_stack = dom.childs if dom.isTag() else [dom]
    elif isinstance(dom, string_type):
        element_stack = parseString(dom).childs
    else:
        element_stack = dom
    output = ''
    while element_stack:
        el = element_stack.pop(0)
        if not (el.isTag() or el.isComment() or (not el.getTagName())):
            output += el.__str__()
        if el.childs:
            element_stack = el.childs + element_stack
    return output

def send_to_kinesis_stream(events, stream_name, partition_key=None, packer=None, serializer=json.dumps):
    """Sends events to a Kinesis stream."""
    if not events:
        logger.info('No events provided: nothing delivered to Firehose')
        return
    records = []
    for event in events:
        if not partition_key:
            partition_key_value = str(uuid.uuid4())
        elif hasattr(partition_key, '__call__'):
            partition_key_value = partition_key(event)
        else:
            partition_key_value = partition_key
        if not isinstance(event, str):
            event = serializer(event)
        if packer:
            event = packer(event)
        record = {'Data': event, 'PartitionKey': partition_key_value}
        records.append(record)
    kinesis = boto3.client('kinesis')
    resp = kinesis.put_records(StreamName=stream_name, Records=records)
    return resp

def crc7(data):
    """Compute CRC of a whole message."""
    crc = 0
    for c in data:
        crc = CRC7_TABLE[crc ^ c]
    return crc

