def get_state_batch(keys, namespace=None, consistent=True):
    """Get a batch of items from the state store."""
    ukeys = set(keys)
    if namespace:
        ns_keys = ['{}:{}'.format(namespace, key) for key in ukeys]
    uvalues = {k: v for k, v in zip(ukeys, get_item_batch(ns_keys, consistent=consistent))}
    return list(zip(keys, (uvalues[k] for k in keys)))

def set_state_batch(keys, values, namespace=None, ttl=3600 * 24 * 365):
    """Set a batch of items in the state store."""
    keys, values = zip(*{k: v for k, v in zip(keys, values)}.items())
    if namespace:
        keys = ['{}:{}'.format(namespace, key) for key in keys]
    return set_item_batch(keys, values, ttl)

def delete_state(key, namespace=None, table_name=None, environment=None, layer=None, stage=None, shard_id=None, consistent=True, wait_exponential_multiplier=500, wait_exponential_max=5000, stop_max_delay=10000):
    """Delete Lambda state value."""
    if table_name is None:
        table_name = _state_table_name(environment=environment, layer=layer, stage=stage)
    if not table_name:
        msg = "Can't produce state table name: unable to set state item '{}'".format(key)
        logger.error(msg)
        raise StateTableError(msg)
        return
    dynamodb = boto3.resource('dynamodb')
    table = dynamodb.Table(table_name)
    logger.info('Deleting {} in DynamoDB table {}'.format(key, table_name))
    if namespace:
        key = '{}:{}'.format(namespace, key)
    if shard_id:
        key = '{}:{}'.format(shard_id, key)
    @retry(retry_on_exception=_is_critical_exception, wait_exponential_multiplier=500, wait_exponential_max=5000, stop_max_delay=10000)
    def delete_item():
        try:
            return table.delete_item(Key={'id': key})
        except Exception as err:
            if _is_dynamodb_critical_exception(err):
                raise CriticalError(err)
            else:
                raise
    resp = delete_item()
    logger.info("Response from DynamoDB: '{}'".format(resp))
    return resp

def produce_context(namespace, context_id, max_delay=None):
    """Produce event context."""
    try:
        context_obj = get_context(namespace, context_id)
        logger.info("Found context '%s:%s'", namespace, context_id)
    except ContextError:
        logger.info("Context '%s:%s' not found", namespace, context_id)
        if max_delay is not None:
            max_delay = float(max_delay)
        logger.info('Context error handled with max_delay=%s', max_delay)
        if not max_delay or arrival_delay_greater_than(context_id, max_delay):
            context_obj = {}
            logger.info("Timeout: waited %s seconds for context '%s'", max_delay, context_id)
        else:
            msg = "Context '{}' not found: resorting".format(context_id)
            raise OutOfOrderError(msg)
    return context_obj

def get_context(namespace, context_id):
    """Get stored context object."""
    context_obj = get_state(context_id, namespace=namespace)
    if not context_obj:
        raise ContextError("Context '{}' not found in namespace '{}'".format(context_id, namespace))
    return context_obj

def str_to_num(i, exact_match=True):
    """Attempts to convert a str to either an int or float"""
    if not isinstance(i, str):
        return i
    try:
        if not exact_match:
            return int(i)
        elif str(int(i)) == i:
            return int(i)
        elif str(float(i)) == i:
            return float(i)
        else:
            pass
    except ValueError:
        pass
    return i

