        else:
            f = open(csv_file, 'rU')
    except IOError:
        print(" \n '{f}' could not be opened\n".format(f=os.path.basename(csv_file)))
        sys.exit(1)
    csv_reader = csv.reader(f)
    molList = []
    line_number = 1
    for line in csv_reader:
        if line_number == 1:
            if ensemble_list:
                prop_indices = read_header(line, options, ensemble_list)
            else:
                prop_indices = read_header(line, options)
        else:
            mol = Molecule()
            if ensemble_list:
                mol = read_line(line, options, prop_indices, mol, ensemble_list)
            else:
                mol = read_line(line, options, prop_indices, mol)
            if mol == 1:
                print(' skipping molecule {m}\n'.format(m=line_number - 1))
            else:
                molList.append(mol)
        line_number += 1
    return molList

def read_line(csv_contents, options, prop_indices, mol, ensemble_list=None):
    """read csv line"""
    if not ensemble_list:
        score_field = options.score_field
    status_field = options.status_field
    active_label = options.active_label
    decoy_label = options.decoy_label
    active_value_matcher = re.compile(active_label)
    decoy_value_matcher = re.compile(decoy_label)
    status_label_index = prop_indices[status_field]
    if not active_value_matcher.match(csv_contents[status_label_index]) and (not decoy_value_matcher.match(csv_contents[status_label_index])):
        print('\n molecule lacks appropriate status label')
        return 1
    score_field_indices = []
    if ensemble_list:
        queryList = ensemble_list
    else:
        queryList = [x for x in prop_indices.keys() if score_field in x]
    for query in queryList:
        score_field_indices.append(prop_indices[query])
    for value in [csv_contents[x] for x in score_field_indices]:
        if value in ('', 'n/a', 'N/A', None):
            print('\n molecule lacks appropriate score field value')
            return 1
    for label in prop_indices.keys():
        value_index = prop_indices[label]
        value = csv_contents[value_index]
        if label in queryList:
            mol.SetProp(label, value, 'score')
        else:
            mol.SetProp(label, value)
    return mol

def _build_rules(specs):
    """Adapts the list of anillo urlmapping specs into
    a list of werkzeug rules or rules subclasses.

    :param list specs: A list of anillo url mapping specs.
    :return: generator"""
    for spec in specs:
        if 'context' in spec:
            yield Context(spec['context'], list(_build_rules(spec.get('routes', []))))
        else:
            rulespec = spec.copy()
            match = rulespec.pop('match')
            name = rulespec.pop('name')
            yield Rule(match, endpoint=name, **rulespec)

def default_match_error_handler(exc):
    """Default implementation for match error handling."""
    if isinstance(exc, NotFound):
        return http.NotFound()
    elif isinstance(exc, MethodNotAllowed):
        return http.MethodNotAllowed()
    elif isinstance(exc, RequestRedirect):
        return redirect(exc.new_url)
    else:
        raise exc

def run_simple(app, *, host='127.0.0.1', port=500, debug=True, autoreload=True, **kwargs):
    """Start a WSGI application.
    Optional features include a reloader, multithreading and fork support."""
