    return serving.run_simple(host, port, app, use_debugger=debug, use_reloader=autoreload, **kwargs)

def wrap_form_params(func):
    """A middleware that parses the url-encoded body and attach
    the result to the request `form_params` attribute.

    This middleware also merges the parsed value with the existing
    `params` attribute in same way as `wrap_query_params` is doing."""
    @functools.wraps(func)
    def wrapper(request, *args, **kwargs):
        ctype, pdict = parse_header(request.headers.get('Content-Type', ''))
        if ctype == 'application/x-www-form-urlencoded':
            params = {}
            for key, value in parse_qs(request.body.decode('utf-8')).items():
                if len(value) == 1:
                    params[key] = value[0]
                else:
                    params[key] = value
            request.params = merge_dicts(getattr(request, 'params', None), params)
            request.form_params = params
        return func(request, *args, **kwargs)
    return wrapper

def wrap_query_params(func):
    """A middleware that parses the urlencoded params from the querystring
    and attach it to the request `query_params` attribute.

    This middleware also merges the parsed value with the existing
    `params` attribute in same way as `wrap_form_params` is doing."""
    @functools.wraps(func)
    def wrapper(request, *args, **kwargs):
        params = {}
        for key, value in parse_qs(request.query_string.decode('utf-8')).items():
            if len(value) == 1:
                params[key] = value[0]
            else:
                params[key] = value
        request.params = merge_dicts(getattr(request, 'params', None), params)
        request.query_params = params
        return func(request, *args, **kwargs)
    return wrapper

def init_node(cls, *args, **kwargs):
    """Initializes an ast node with the provided attributes.

    Python 2.6+ supports this in the node class initializers, but Python 2.5
    does not, so this is intended to be an equivalent."""
    node = cls()
    for name, value in zip(cls._fields, args):
        setattr(node, name, value)
    for name, value in kwargs:
        setattr(node, name, value)
    return node

def infer_ast(src):
    """Attempts to infer an abstract syntax tree from the provided value.

    - Python ast.AST instances are passed through.
    - Strings are parsed. A SyntaxError is raised if invalid.
    - Functions are sent through cypy.fn_get_source to get a source
      string, then parsed. If the source can't be a found, an exception is
      raised by fn_get_source.

    .. WARNING:: Functions defined on the iPython command line do not have
                 their source saved. A bug has been filed:

                 http://github.com/ipython/ipython/issues/issue/120"""
    if isinstance(src, _ast.AST):
        return src
    elif isinstance(src, str):
        return _ast.parse(src)
    else:
        src = cypy.fn_get_source(src)
        return _ast.parse(src)

def extract_the(node, node_type):
    """Extracts the node of type node_type from the provided node.

    - If the node is itself of node_type, returns node.
    - If the node is a suite, it must contain exactly one node of the provided
      type in its body."""
    if isinstance(node, node_type):
        return node
    try:
        body = node.body
    except AttributeError:
        raise cypy.Error('Expecting suite containing a single %s, or a %s, but got %s.' % (node_type.__name__, node_type.__name__, type(node).__name__))
    if len(body) != 1 or not isinstance(body[0], node_type):
        raise cypy.Error('The body must contain exactly one node of type %s.' % node_type.__name__)
    return body[0]

