def paragraph_generator(sentences=None):
    """Creates a generator for generating paragraphs.

    :arg sentences: list or tuple of sentences you want to use;
        defaults to LOREM

    :returns: generator

    Example::

        from eadred.helpers import paragraph_generator

        gen = paragraph_generator()
        for i in range(50):
            mymodel = SomeModel(description=gen.next())
            mymodel.save()"""
    if sentences is None:
        sentences = LOREM
    while True:
        paragraph = [random.choice(sentences) for num in range(random.randint(1, 7))]
        yield u' '.join(paragraph)

def import_dotted_path(path):
    """Takes a dotted path to a member name in a module, and returns
    the member after importing it."""
    try:
        module_path, member_name = path.rsplit('.', 1)
        module = import_module(module_path)
        return getattr(module, member_name)
    except (ValueError, ImportError, AttributeError) as e:
        raise ImportError('Could not import the name: {}: {}'.format(path, e))

def validateAuthCode(code, redirect_uri, client_id, state=None, validationEndpoint='https://indieauth.com/auth', headers={}):
    """Call authorization endpoint to validate given auth code.

    :param code: the auth code to validate
    :param redirect_uri: redirect_uri for the given auth code
    :param client_id: where to find the auth endpoint for the given auth code
    :param state: state for the given auth code
    :param validationEndpoint: URL to make the validation request at
    :param headers: optional headers to send with any request
    :rtype: True if auth code is valid"""
    payload = {'code': code, 'redirect_uri': redirect_uri, 'client_id': client_id}
    if state is not None:
        payload['state'] = state
    authURL = None
    authEndpoints = discoverAuthEndpoints(client_id, headers=headers)
    for url in authEndpoints['authorization_endpoint']:
        authURL = url
        break
    if authURL is not None:
        validationEndpoint = ParseResult(authURL.scheme, authURL.netloc, authURL.path, '', '', '').geturl()
    r = requests.post(validationEndpoint, verify=True, data=payload, headers=headers)
    result = {'status': r.status_code, 'headers': r.headers}
    if 'charset' in r.headers.get('content-type', ''):
        result['content'] = r.text
    else:
        result['content'] = r.content
    if r.status_code == requests.codes.ok:
        result['response'] = parse_qs(result['content'])
    return result

def get(url, max_backoff=32, verbose=False, **kwargs):
    """Adding retries to requests.get with exponential backoff.

    Args:
        url (str): The URL to fetch
        max_backoff (int): The number of seconds to sleep at maximums
        verbose (bool): Whether to print exceptions.

    Returns:
        Response: For successful requests return requests' response. `None` otherwise."""
    sleep_seconds = 1
    while sleep_seconds <= max_backoff:
        try:
            response = requests.get(url, **{**{'timeout': 30}, **kwargs})
            if 400 <= response.status_code < 500:
                return None
            if 200 <= response.status_code < 400:
                return response
        except RequestException as e:
            if verbose:
                print(str(e))
        time.sleep(sleep_seconds)
        sleep_seconds *= 2
    return None

def drawPoints(points, bg=','):
    """A small debug function that takes an iterable of (x, y) integer tuples
    and draws them to the screen."""
    import sys
    points = list(points)
    try:
        points = [(int(x), int(y)) for x, y in points]
    except:
        raise PyBresenhamException('points must only contains (x, y) numeric tuples')
    minx = min([x for x, y in points])
    maxx = max([x for x, y in points])
    miny = min([y for x, y in points])
    maxy = max([y for x, y in points])
    charGrid = [[' '] * (maxy - miny + 1) for i in range(maxx - minx + 1)]
    for x, y in points:
        charGrid[x - minx][y - miny] = 'O'
    for y in range(len(charGrid[0])):
        for x in range(len(charGrid)):
            if charGrid[x][y] in (None, ' '):
                charToDraw = bg
            else:
                charToDraw = charGrid[x][y]
            sys.stdout.write(charToDraw)
        print()

