def calculate_ef_var(tpf, fpf):
    """determine variance due to actives (efvar_a) decoys (efvar_d) and s2, the slope of the ROC curve tangent to the
    fpf @ which the enrichment factor was calculated
    :param tpf: float tpf @ which the enrichment factor was calculated
    :param fpf: float fpf @ which the enrichment factor was calculated
    :return efvara, efvard, s2: tuple"""
    efvara = tpf * (1 - tpf)
    efvard = fpf * (1 - fpf)
    ef = tpf / fpf
    if fpf == 1:
        return (0, 0, 0)
    else:
        s = ef * (1 + np.log(ef) / np.log(fpf))
        s2 = s * s
        return (efvara, efvard, s2)

def calculate_auc(auc_structure, sort_order, diff=None):
    """TO DO: Add logit bounds
    determine AUC and 95% confidence intervals (CI)
    :param roc_structure: auc_structure: list [(id, best_score, best_query, status, fpf, tpf), ..., ]
    :param sort_order: either 'asc' (binding free energy estimates) or 'dsc' (probabilities)
    :return (AUC, AUC - CI, AUC + CI): tuple"""
    if sort_order == 'asc':
        auc_structure.sort(key=lambda x: float(x[1]))
    elif sort_order == 'dsc':
        auc_structure.sort(key=lambda x: float(x[1]), reverse=True)
    auc = 0.0
    n = 0
    for mol in auc_structure:
        status = mol[3]
        if status == '0':
            tpf = mol[5]
            n += 1
            auc += tpf
    if n == 0:
        auc = 0
    else:
        auc = 1.0 / n * auc
    if diff:
        return auc
    else:
        n = len([x for x in auc_structure if x[3] == '0'])
        p = len([x for x in auc_structure if x[3] == '1'])
        aucvar_a, aucvar_d = calculate_auc_var(auc_structure)
        se = (aucvar_a / p + aucvar_d / n) ** 0.5
        ci = se * stats.t.ppf(1 - 0.025, n + p - 1)
        lower = auc - ci
        upper = auc + ci
        if lower < 0:
            lower = 0.0
        if upper > 1:
            upper = 1.0
        return (auc, lower, upper)

def make_ef_structure(score_structure, fpf, sort_order):
    """Description
    :param score_structure: list [(id, best_score, best_query, status, net decoy count, net active count), ..., ]
    :param fpf: float. False positive fraction at which the enrichment factor will be calculated.
    :param sort_order: string. 'asc' (binding free energy estimate) 'dsc' (probability)
    :return: ef_structure: list [(id, best_score, best_query, status, gamma), ..., ]
    gamma is 1 if the score of the molecule is better than the false positive threshold and 0 otherwise"""
    n = len([x[4] for x in score_structure if x[3] == '0'])
    if not fpf:
        fpf = float(1) / n
    if n < int(round(1 / fpf)):
        return None
    decoy_threshold = int(round(n * fpf))
    active_list_at_threshold = [x for x in score_structure if x[4] == decoy_threshold]
    active_list_at_threshold.sort(key=lambda x: x[5], reverse=True)
    score_threshold = float(active_list_at_threshold[0][1])
    ef_structure = []
    for mol in score_structure:
        score = float(mol[1])
        if sort_order == 'asc':
            if score <= score_threshold:
                gamma = 1
            elif score > score_threshold:
                gamma = 0
        elif sort_order == 'dsc':
            if score >= score_threshold:
                gamma = 1
            elif score < score_threshold:
                gamma = 0
        tup = mol[0:4] + (gamma,)
        ef_structure.append(tup)
    return ef_structure

def make_auc_structure(score_structure):
    """calculates ROC data points and returns roc_structure, a modified form of the score_structure format
    :param score_structure: list [(id, best_score, best_query, status, net decoy count, net active count), ..., ]
    :return auc_structure: list [(id, best_score, best_query, status, fpf, tpf), ..., ]"""
    n = len([x for x in score_structure if x[3] == '0'])
    p = len([x for x in score_structure if x[3] == '1'])
    auc_structure = []
    for mol in score_structure:
        if n == 0:
            fpf = 0
        else:
            fpf = float(mol[4]) / n
        if p == 0:
            tpf = 0
        else:
            tpf = float(mol[5]) / p
        tup = mol[0:4] + (fpf, tpf)
        auc_structure.append(tup)
    return auc_structure

def _connectWithContextFactory(ctxFactory, workbench):
    """Connect using the given context factory. Notifications go to the
    given workbench."""
    endpoint = SSL4ClientEndpoint(reactor, 'localhost', 4430, ctxFactory)
    splash = _Splash(u'Connecting', u'Connecting...')
    workbench.display(splash)
    d = endpoint.connect(Factory(workbench))
    @d.addBoth
    def closeSplash(returnValue):
        workbench.undisplay()
        return returnValue
    @d.addErrback
    def notifyFailure(f):
        f.trap(ConnectError)
        d = alert(workbench, u"Couldn't connect", u'Connection failed! Check internet connection, or try again later.\nError: {!r}'.format(f.value))
        return d.addCallback(lambda _result: reactor.stop())
    return d

def _getContextFactory(path, workbench):
    """Get a context factory.

    If the client already has a credentials at path, use them.
    Otherwise, generate them at path. Notifications are reported to
    the given workbench."""
    try:
        return succeed(getContextFactory(path))
    except IOError:
        d = prompt(workbench, u'E-mail entry', u'Enter e-mail:')
        d.addCallback(_makeCredentials, path, workbench)
        d.addCallback(lambda _result: getContextFactory(path))
        return d

def optional_args_func(func) -> callable:
    """Given a function or generator `func`, return a function/generator
    that takes any number of kwargs and calls `func` with only the args/kwargs
    that `func` expects."""
    if getattr(func, '_optional_args_func', False):
        return func
    is_generator = inspect.isgeneratorfunction(func)
    func_sig = inspect.signature(func)
    expects_nothing = not func_sig.parameters
    if is_generator:
        @functools.wraps(func)
        def wrapped(*args, **kwargs):
            if expects_nothing:
                yield from func()
            else:
                bound_arguments = func_sig.bind(*args, **{k: v for k, v in kwargs.items() if k in func_sig.parameters})
                yield from func(*bound_arguments.args, **bound_arguments.kwargs)
    else:
        @functools.wraps(func)
        def wrapped(*args, **kwargs):
            if expects_nothing:
                return func()
            else:
                bound_arguments = func_sig.bind(*args, **{k: v for k, v in kwargs.items() if k in func_sig.parameters})
                return func(*bound_arguments.args, **bound_arguments.kwargs)
    setattr(wrapped, '_optional_args_func', True)
    return wrapped

def gradient_line(xs, ys, colormap_name='jet', ax=None):
    """Plot a 2-d line with a gradient representing ordering.
    See http://stackoverflow.com/q/8500700/10601 for details."""
    if ax is None:
        ax = plt.gca()
    cm = plt.get_cmap(colormap_name)
    npts = len(xs) - 1
    colors = cm(np.linspace(0, 1, num=npts))
    if hasattr(ax, 'set_prop_cycle'):
        ax.set_prop_cycle(color=colors)
    else:
        ax.set_color_cycle(colors)
    for i in range(npts):
        ax.plot(xs[i:i + 2], ys[i:i + 2])
    return plt.show

def jitterplot(data, positions=None, ax=None, vert=True, scale=0.1, **scatter_kwargs):
    """Plots jittered points as a distribution visualizer.

    Scatter plot arguments default to: marker='.', c='k', alpha=0.75
    Also known as a stripplot.
    See also: boxplot, violinplot, beeswarm"""
    if ax is None:
        ax = plt.gca()
    if positions is None:
        positions = range(len(data))
    kwargs = dict(marker='.', c='k', alpha=0.75)
    kwargs.update(scatter_kwargs)
    for pos, y in zip(positions, data):
        if scale > 0:
            x = np.random.normal(loc=pos, scale=scale, size=len(y))
        else:
            x = np.zeros_like(y) + pos
        if not vert:
            x, y = (y, x)
        ax.scatter(x, y, **kwargs)
    return plt.show

def wrap_multipart_params(func):
    """A middleware that parses the multipart request body and adds the
    parsed content to the `multipart_params` attribute.

    This middleware also merges the parsed value with the existing
    `params` attribute in same way as `wrap_form_params` is doing."""
    def wrapper(request, *args, **kwargs):
        ctype, pdict = parse_header(request.headers.get('Content-Type', ''))
        if ctype == 'multipart/form-data':
            if isinstance(pdict['boundary'], str):
                pdict['boundary'] = pdict['boundary'].encode()
            params = {}
            mp = MultipartParser(BytesIO(request.body), pdict['boundary'])
            for part in mp:
                params[part.name] = {'filename': part.filename, 'file': part.file}
            request.params = merge_dicts(getattr(request, 'params', None), params)
            request.multipart_params = params
        return func(request, *args, **kwargs)
    return wrapper

def get_optional_env(key):
    """Return the value of an optional environment variable, and use
    the provided default if it's not set."""
    environment_variable_value = os.environ.get(key)
    if environment_variable_value:
        return environment_variable_value
    elif key in CONSTANTS:
        return CONSTANTS[key]
    else:
        raise Exception('The variable {1} is not set'.format(key))

def run_netsh_command(netsh_args):
    """Execute a netsh command and return the output."""
    devnull = open(os.devnull, 'w')
    command_raw = 'netsh interface ipv4 ' + netsh_args
    return int(subprocess.call(command_raw, stdout=devnull))

def parse_array(raw_array):
    """Parse a WMIC array."""
    array_strip_brackets = raw_array.replace('{', '').replace('}', '')
    array_strip_spaces = array_strip_brackets.replace('"', '').replace(' ', '')
    return array_strip_spaces.split(',')

def lcsr(s1, s2):
    """longest common sequence ratio

    >>> lcsr('ab', 'abcd')
    0.5"""
    if s1 == s2:
        return 1.0
    return llcs(s1, s2) / max(1, len(s1), len(s2))

def lcp(s1, s2):
    """longest common prefix

    >>> lcp('abcdx', 'abcdy'), lcp('', 'a'), lcp('x', 'yz')
    (4, 0, 0)"""
    i = 0
    for i, (c1, c2) in enumerate(zip(s1, s2)):
        if c1 != c2:
            return i
    return min(len(s1), len(s2))

def bucket_to_dataframe(name, buckets, append_name=None):
    """A function that turns elasticsearch aggregation buckets into dataframes

    :param name: The name of the bucket (will be a column in the dataframe)
    :type name: str
    :param bucket: a bucket from elasticsearch results
    :type bucket: list[dict]
    :returns: pandas.DataFrame"""
    expanded_buckets = []
    for item in buckets:
        if type(item) is dict:
            single_dict = item
        else:
            single_dict = item.to_dict()
        single_dict[name] = single_dict.pop('doc_count')
        if append_name:
            persistance_dict = single_dict.copy()
            for key in persistance_dict.keys():
                single_dict[append_name + '.' + key] = single_dict.pop(key)
        expanded_buckets.append(single_dict)
    return pd.DataFrame(expanded_buckets)

def write_diff_summary(stats, options):
    """writes contents of stats to outname_diff_stats.csv
    :param stats:
    :param options:"""
    out_name = '%s_diff_stats.csv' % options.outname
    filename = os.path.join(os.getcwd(), out_name)
    f = open(filename, 'w')
    statswriter = csv.writer(f)
    statswriter.writerow(stats['header'])
    line = ['AUC']
    for metric_tup in stats['AUC']:
        try:
            len(metric_tup)
            line.append('[%0.2f, %0.2f]' % (metric_tup[0], metric_tup[1]))
        except:
            line.append('%0.6f' % metric_tup)
    statswriter.writerow(line)
    for title in [x for x in sorted(stats.keys()) if 'E' in x]:
        line = [title]
        for metric_tup in stats[title]:
            try:
                len(metric_tup)
                line.append('[%0.2f, %0.2f]' % (metric_tup[0], metric_tup[1]))
            except:
                line.append('%0.12f' % metric_tup)
        statswriter.writerow(line)

def sshagent_run(cmd):
    """Helper function.
    Runs a command with SSH agent forwarding enabled.

    Note:: Fabric (and paramiko) can't forward your SSH agent.
    This helper uses your system's ssh to do so."""
    wrapped_cmd = _prefix_commands(_prefix_env_vars(cmd), 'remote')
    try:
        host, port = env.host_string.split(':')
        return local(u"ssh -p %s -A -o StrictHostKeyChecking=no %s@%s '%s'" % (port, env.user, host, wrapped_cmd))
    except ValueError:
        return local(u"ssh -A -o StrictHostKeyChecking=no %s@%s '%s'" % (env.user, env.host_string, wrapped_cmd))

def as_object(obj):
    """Return a JSON serializable type for ``o``.

    Args:
        obj (:py:class:`object`): the object to be serialized.

    Raises:
        :py:class:`AttributeError`:
            when ``o`` is not a Python object.

    Returns:
        (dict): JSON serializable type for the given object."""
    LOGGER.debug('as_object(%s)', obj)
    if isinstance(obj, datetime.date):
        return as_date(obj)
    elif hasattr(obj, '__dict__'):
        out = {k: obj.__dict__[k] for k in obj.__dict__ if not k.startswith('_')}
        for k, v in ((p, getattr(obj, p)) for p, _ in inspect.getmembers(obj.__class__, lambda x: isinstance(x, property))):
            out[k] = v
        return out

def dict_chunks(dictionary, chunk):
    """Return a list of dictionary with n-keys (chunk) per list."""
    return [{k: v for k, v in dictionary.items() if k in i} for i in chunks(list(dictionary.keys()), chunk)]

def socket_reader(connection: socket, buffer_size: int=1024):
    """read data from adb socket"""
    while connection is not None:
        try:
            buffer = connection.recv(buffer_size)
            if not len(buffer):
                raise ConnectionAbortedError
        except ConnectionAbortedError:
            print('connection aborted')
            connection.close()
            yield None
        except OSError:
            print('socket closed')
            connection.close()
            yield None
        else:
            yield buffer

def decode_response(content: bytes) -> set:
    """adb response text -> device set"""
    content = content[4:].decode(config.ENCODING)
    if '\t' not in content and '\n' not in content:
        return set()
    connected_devices = set()
    device_list = [i for i in content.split('\n') if i]
    for each_device in device_list:
        device_id, device_status = each_device.split('\t')
        if device_status == 'device':
            connected_devices.add(device_id)
    return connected_devices

