def no_history_check(func):
    """Decorator function to setup a check to see if history has been turned off,
    because if it has then the decorated function needs to throw an exception
    :param func: function to decorate
    :return: original results or exception"""
    def no_history_check_decorator(self, *args, **kwargs):
        if ConnectionBasic.max_history is 0:
            raise IndexError('ConnectionBasic.max_history is set to 0, therefore this functionality is disabled')
        return func(self, *args, **kwargs)
    return no_history_check_decorator

def guard(params, guardian, error_class=GuardError, message=''):
    """A guard function - check parameters
    with guardian function on decorated function

    :param tuple or string params: guarded function parameter/s
    :param function guardian: verifying the conditions for the selected parameter
    :param Exception error_class: raised class when guardian return false
    :param string message: error message"""
    params = [params] if isinstance(params, string_types) else params
    def guard_decorate(f):
        @wraps(f)
        def _guard_decorate(*args, **kwargs):
            if guardian(**_params(f, args, kwargs, params)):
                return f(*args, **kwargs)
            else:
                raise error_class(message)
        return _guard_decorate
    return guard_decorate

def encode_request(from_pid, to_pid, method, body=None, content_type=None, legacy=False):
    """Encode a request into a raw HTTP request. This function returns a string
    of bytes that represent a valid HTTP/1.0 request, including any libprocess
    headers required for communication.

    Use the `legacy` option (set to True) to use the legacy User-Agent based
    libprocess identification."""
    if body is None:
        body = b''
    if not isinstance(body, (bytes, bytearray)):
        raise TypeError('Body must be a sequence of bytes.')
    headers = ['POST /{process}/{method} HTTP/1.0'.format(process=to_pid.id, method=method), 'Connection: Keep-Alive', 'Content-Length: %d' % len(body)]
    if legacy:
        headers.append('User-Agent: libprocess/{pid}'.format(pid=from_pid))
    else:
        headers.append('Libprocess-From: {pid}'.format(pid=from_pid))
    if content_type is not None:
        headers.append('Content-Type: {content_type}'.format(content_type=content_type))
    headers = [header.encode('utf8') for header in headers]
    def iter_fragments():
        for fragment in headers:
            yield fragment
            yield CRLF
        yield CRLF
        if body:
            yield body
    return b''.join(iter_fragments())

