def get_sort_order(molecules):
    """Count up the total number of scores whose values are positve and negative.
    If a greater number are negative, then sort in ascending order (e.g. for binding energy estimates)
    Otherwise, sort in descending order (e.g. for similarity values)"""
    neg_count = 0
    pos_count = 0
    for index in range(len(molecules)):
        scoreList = molecules[index].GetProp('scores')
        for element in scoreList:
            if float(element) > 0:
                pos_count += 1
            elif float(element) < 0:
                neg_count += 1
    if pos_count > neg_count:
        sort_order = 'dsc'
    else:
        sort_order = 'asc'
    return sort_order

def metric_calculator(tpf, fpf, P, N, metric_list, anal=True):
    """Calculates VS metrics & (optionally) their 95% conficdence limits"""
    metrics = {}
    for vs_metric in [float(x) for x in metric_list if '.' in x]:
        if N >= 1 / vs_metric:
            metrics[round(vs_metric * N)] = [vs_metric, 0]
    for vs_metric in [x for x in metric_list if '.' not in x]:
        metrics[vs_metric] = [vs_metric, 0, 0, 0]
    metrics['AUC'][1] = 0
    for index in range(len(tpf)):
        if N * fpf[index] in metrics.keys() and N * fpf[index] > 0:
            ef = tpf[index] / fpf[index]
            metrics[N * fpf[index]][1] = ef
        if fpf[index] != fpf[index - 1]:
            metrics['AUC'][1] = tpf[index] + metrics['AUC'][1]
    metrics['AUC'][1] = metrics['AUC'][1] / N
    reshaped = {}
    for k, v in metrics.iteritems():
        if type(v) is float or type(v) is int:
            reshaped[k] = v
        else:
            reshaped[v[0]] = v[1:]
    return reshaped

def remove_comments(text):
    """Remove C and Javascript style comments like // [...] and /* [...] */ from
    the given text."""
    def _replacer(match):
        if match.group(2) is not None:
            return ''
        else:
            return match.group(1)
    return COMMENT_PATTERN.sub(_replacer, text)

def wrap_json_body(func=None, *, preserve_raw_body=False):
    """A middleware that parses the body of json requests and
    add it to the request under the `body` attribute (replacing
    the previous value). Can preserve the original value in
    a new attribute `raw_body` if you give preserve_raw_body=True."""
    if func is None:
        return functools.partial(wrap_json_body, preserve_raw_body=preserve_raw_body)
    @functools.wraps(func)
    def wrapper(request, *args, **kwargs):
        ctype, pdict = parse_header(request.headers.get('Content-Type', ''))
        if preserve_raw_body:
            request.raw_body = request.body
        if ctype == 'application/json':
            request.body = json.loads(request.body.decode('utf-8')) if request.body else None
        return func(request, *args, **kwargs)
    return wrapper

def wrap_json_params(func):
    """A middleware that parses the body of json requests and
    add it to the request under the `params` key."""
    @functools.wraps(func)
    def wrapper(request, *args, **kwargs):
        ctype, pdict = parse_header(request.headers.get('Content-Type', ''))
        if ctype == 'application/json':
            request.params = json.loads(request.body.decode('utf-8')) if request.body else None
        return func(request, *args, **kwargs)
    return wrapper

def wrap_json_response(func=None, *, encoder=json.JSONEncoder):
    """A middleware that encodes in json the response body in case
    of that the "Content-Type" header is "application/json".

    This middlware accepts and optional `encoder` parameter, that
    allow to the user specify its own json encoder class."""
    if func is None:
        return functools.partial(wrap_json_response, encoder=encoder)
    @functools.wraps(func)
    def wrapper(request, *args, **kwargs):
        response = func(request, *args, **kwargs)
        if 'Content-Type' in response.headers and response.headers['Content-Type'] is not None:
            ctype, pdict = parse_header(response.headers.get('Content-Type', ''))
            if ctype == 'application/json' and (isinstance(response.body, dict) or isinstance(response.body, list)):
                response.body = json.dumps(response.body, cls=encoder)
        return response
    return wrapper

def partition(molList, options):
    """Partition molList into activeList and decoyList"""
    status_field = options.status_field
    active_label = options.active_label
    decoy_label = options.decoy_label
    activeList = []
    decoyList = []
    for mol in molList:
        if mol.GetProp(status_field) == active_label:
            activeList.append(mol)
        elif mol.GetProp(status_field) == decoy_label:
            decoyList.append(mol)
    return (activeList, decoyList)

def read_csv(csvfile, options):
    """Read csv and return molList, a list of mol objects"""
    name, ext = os.path.splitext(csvfile)
    try:
        if ext == '.gz':
            f = gzip.open(csvfile, 'rb')
        else:
            f = open(csvfile, 'rU')
    except IOError:
        print(" \n '{f}' could not be opened\n".format(f=os.path.basename(csvfile)))
        sys.exit(1)
    csv_reader = csv.reader(f)
    molList = []
    linenumber = 1
    for line in csv_reader:
        if linenumber == 1:
            prop_indices = read_header(line, options)
        else:
            mol = Molecule()
            mol = read_line(line, options, prop_indices, mol)
            if mol == 1:
                print(" skipping molecule 'm'\n".format(m=linenumber - 1))
            else:
                molList.append(mol)
        linenumber += 1
    return molList

def read_header(headerlabels, options):
    """read csv header, returns prop_indices dictionary, {'label' : index}
    where label is the csv column label, and index the column index"""
    status_field = options.status_field
    status_field_matcher = re.compile(status_field)
    if not any((x for x in headerlabels if status_field_matcher.match(x))):
        print("\n The status_field column '{s}' doesn't exist\n".format(s=status_field))
        sys.exit(1)
    prop_indices = {}
    index = 0
    for label in headerlabels:
        prop_indices[label] = index
        index += 1
    return prop_indices

def _lower_if_str(item):
    """Try to convert item to lowercase, if it is string.

    Args:
        item (obj): Str, unicode or any other object.

    Returns:
        obj: ``item.lower()`` if `item` is ``str`` or ``unicode``, else just              `item` itself."""
    try:
        string_type = basestring
    except NameError:
        string_type = str
    if isinstance(item, string_type):
        return item.lower()
    return item

def get_repo_relpath(repo, relpath):
    """Returns the absolute path to the 'relpath' taken relative to the base
    directory of the repository."""
    from os import path
    if relpath[0:2] == './':
        return path.join(repo, relpath[2:])
    else:
        from os import chdir, getcwd
        cd = getcwd()
        chdir(path.expanduser(repo))
        result = path.abspath(relpath)
        chdir(cd)
        return result

def load_with_datetime(pairs):
