def hookable(cls):
    """Initialise hookery in a class that declares hooks by decorating it with this decorator.

    This replaces the class with another one which has the same name, but also inherits Hookable
    which has HookableMeta set as metaclass so that sub-classes of cls will have hook descriptors
    initialised properly.

    When you say:
        @hookable
        class My:
            before = Hook()

    then @hookable changes My.before to be a HookDescriptor which is then
    changed into Hook if anyone accesses it.

    There is no need to decorate sub-classes of cls with @hookable."""
    assert isinstance(cls, type)
    hook_definitions = []
    if not issubclass(cls, Hookable):
        for k, v in list(cls.__dict__.items()):
            if isinstance(v, (ClassHook, InstanceHook)):
                delattr(cls, k)
                if v.name is None:
                    v.name = k
                hook_definitions.append((k, v))
    hookable_cls = type(cls.__name__, (cls, Hookable), {})
    for k, v in hook_definitions:
        setattr(hookable_cls, k, HookDescriptor(defining_hook=v, defining_class=hookable_cls))
    return hookable_cls

def setup_logging(fail_silently=False):
    """Setup logging configuration

    Finds the most user-facing log config on disk and uses it"""
    config = None
    paths = list(get_config_paths(filename='logconfig.yml', reversed=True))
    for path in paths:
        if not os.path.exists(path):
            continue
        with open(path, 'rt') as f:
            config = yaml.safe_load(f.read())
        LOG_LEVEL = os.environ.get('LOG_LEVEL')
        if LOG_LEVEL:
            config['root']['level'] = LOG_LEVEL.upper()
            config['handlers']['console']['level'] = LOG_LEVEL.upper()
        logging.config.dictConfig(config)
        break
    else:
        if not fail_silently:
            raise LogconfigError('Unable to find logconfig in {}'.format(paths))
    return config

def initialize(**kwargs):
    """Loads the globally shared YAML configuration"""
    global config
    config_opts = kwargs.setdefault('config', {})
    if isinstance(config_opts, basestring):
        config_opts = {'config_filename': config_opts}
        kwargs['config'] = config_opts
    if 'environment' in kwargs:
        config_opts['environment'] = kwargs['environment']
    config.load_config(**config_opts)
    if kwargs.get('name'):
        subconfig = config.get(kwargs.get('name'), {})
        config.overlay_add(subconfig)
    config.overlay_add(app_config)

def execute_interactive_code(elem, doc):
    """Executes code blocks for a python shell.

    Parses the code in `elem.text` into blocks and
    executes them.

    Args:
        elem The AST element.
        doc  The document.

    Return:
        The code with inline results."""
    code_lines = [l[4:] for l in elem.text.split('\n')]
    code_blocks = [[code_lines[0]]]
    for line in code_lines[1:]:
        if line.startswith(' ') or line == '':
            code_blocks[-1].append(line)
        else:
            code_blocks.append([line])
    final_code = []
    try:
        child = replwrap.REPLWrapper('python', '>>> ', None)
    except NameError:
        pf.debug('Can not run interactive session. No output produced ' + '(Code was:\n{!s}\n)'.format(elem))
        pf.debug('Please pip install pexpect.')
        return ''
    for code_block in code_blocks:
        result = child.run_command('\n'.join(code_block) + '\n').rstrip('\r\n')
        final_code += [('>>> ' if i == 0 else '... ') + l for i, l in enumerate(code_block)]
        if result:
            final_code += [r for r in result.split('\n') if r.strip() not in code_block]
    return '\n'.join(final_code)

def remove_import_statements(code):
    """Removes lines with import statements from the code.

    Args:
        code: The code to be stripped.

    Returns:
        The code without import statements."""
    new_code = []
    for line in code.splitlines():
        if not line.lstrip().startswith('import ') and (not line.lstrip().startswith('from ')):
            new_code.append(line)
    while new_code and new_code[0] == '':
        new_code.pop(0)
    while new_code and new_code[-1] == '':
        new_code.pop()
    return '\n'.join(new_code)

def save_plot(code, elem):
    """Converts matplotlib plots to tikz code.

    If elem has either the plt attribute (format: plt=width,height) or the
    attributes width=width and/or height=height, the figurewidth and -height
    are set accordingly. If none are given, a height of 4cm and a width of 6cm
    is used as default.

    Args:
        code: The matplotlib code.
        elem: The element.

    Returns:
        The code and some code to invoke matplotlib2tikz."""
    if 'plt' in elem.attributes:
        figurewidth, figureheight = elem.attributes['plt'].split(',')
    else:
        try:
            figureheight = elem.attributes['height']
        except KeyError:
            figureheight = '4cm'
        try:
            figurewidth = elem.attributes['width']
        except KeyError:
            figurewidth = '6cm'
    return f"import matplotlib\nmatplotlib.use('TkAgg')\n{code}\nfrom matplotlib2tikz import get_tikz_code\ntikz = get_tikz_code(figureheight='{figureheight}', figurewidth='{figurewidth}')  # noqa\nprint(tikz)"

def trimpath(attributes):
    """Simplifies the given path.

    If pathdepth is in attributes, the last pathdepth elements will be
    returned. If pathdepth is "full", the full path will be returned.
    Otherwise the filename only will be returned.

    Args:
        attributes: The element attributes.

    Returns:
        The trimmed path."""
    if 'pathdepth' in attributes:
        if attributes['pathdepth'] != 'full':
            pathelements = []
            remainder = attributes['file']
            limit = int(attributes['pathdepth'])
            while len(pathelements) < limit and remainder:
                remainder, pe = os.path.split(remainder)
                pathelements.insert(0, pe)
            return os.path.join(*pathelements)
        return attributes['file']
    return os.path.basename(attributes['file'])

def rescue(f, on_success, on_error=reraise, on_complete=nop):
    """Functional try-except-finally

    :param function f: guarded function
    :param function on_succes: called when f is executed without error
    :param function on_error: called with `error` parameter when f failed
    :param function on_complete: called as finally block
    :returns function: call signature is equal f signature"""
    def _rescue(*args, **kwargs):
        try:
            return on_success(f(*args, **kwargs))
        except Exception as e:
            return on_error(e)
        finally:
            on_complete()
    return _rescue

def _trigger_job(job):
    """trigger a job"""
    if job.api_instance().is_running():
        return '{0}, {1} is already running'.format(job.host, job.name)
    else:
        requests.get(job.api_instance().get_build_triggerurl())
        return 'triggering {0}, {1}...'.format(job.host, job.name)

def register_blueprints(app, application_package_name=None, blueprint_directory=None):
    """Register Flask blueprints on app object"""
    if not application_package_name:
        application_package_name = 'app'
    if not blueprint_directory:
        blueprint_directory = os.path.join(os.getcwd(), application_package_name)
    blueprint_directories = get_child_directories(blueprint_directory)
    for directory in blueprint_directories:
        abs_package = '{}.{}'.format(application_package_name, directory)
        service = importlib.import_module(abs_package)
        app.register_blueprint(service.blueprint_api, url_prefix='')

def get_child_directories(path):
    """Return names of immediate child directories"""
    if not _is_valid_directory(path):
        raise exceptions.InvalidDirectory
    entries = os.listdir(path)
    directory_names = []
    for entry in entries:
        abs_entry_path = os.path.join(path, entry)
        if _is_valid_directory(abs_entry_path):
            directory_names.append(entry)
    return directory_names

def normalize_excludes(rootpath, excludes):
    """Normalize the excluded directory list."""
    return [path.normpath(path.abspath(exclude)) for exclude in excludes]

def get_kwargs(grid, kwargs, phenotypes=False):
    """Helper function to figure out what denom and palette to use, based on the
    kwargs and the grid being plotted. The optional (default: false) argument
    indicates whether the grid contains phenotypes, as opposed to resources."""
    denom = None
    if 'denom' in kwargs:
        denom = kwargs['denom']
    if 'palette' in kwargs:
        palette = kwargs['palette']
        if denom is None:
            denom = len(palette)
    elif 'environment' in kwargs or isinstance(grid, EnvironmentFile):
        if 'environment' in kwargs:
            env = kwargs['environment']
        else:
            env = grid
        if phenotypes:
            palette = env.task_palette
            if denom is None:
                denom = len(env.tasks)
        else:
            palette = env.resource_palette
            if denom is None:
                denom = len(env.resources)
    else:
        length = get_pallete_length(grid)
        palette = sns.hls_palette(length, s=1)
        denom = length
    return (denom, palette)

def slice_3d_grid(grid, n):
    """Takes a three dimensional array and an integer (n) and returns a 2d array
    containing the Nth value from the 3rd dimension at each location in the
    grid."""
    phen_grid = initialize_grid((len(grid[0]), len(grid)), 0)
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            phen_grid[i][j] = grid[i][j][n]
    return phen_grid

def squared_toroidal_dist(p1, p2, world_size=(60, 60)):
    """Separated out because sqrt has a lot of overhead"""
    halfx = world_size[0] / 2.0
    if world_size[0] == world_size[1]:
        halfy = halfx
    else:
        halfy = world_size[1] / 2.0
    deltax = p1[0] - p2[0]
    if deltax < -halfx:
        deltax += world_size[0]
    elif deltax > halfx:
        deltax -= world_size[0]
    deltay = p1[1] - p2[1]
    if deltay < -halfy:
        deltay += world_size[1]
    elif deltay > halfy:
        deltay -= world_size[1]
    return deltax * deltax + deltay * deltay

def weighted_hamming(b1, b2):
    """Hamming distance that emphasizes differences earlier in strings."""
    assert len(b1) == len(b2)
    hamming = 0
    for i in range(len(b1)):
        if b1[i] != b2[i]:
            if i > 0:
                hamming += 1 + 1.0 / i
    return hamming

def n_tasks(dec_num):
    """Takes a decimal number as input and returns the number of ones in the
    binary representation.
    This translates to the number of tasks being done by an organism with a
    phenotype represented as a decimal number."""
    bitstring = ''
    try:
        bitstring = dec_num[2:]
    except:
        bitstring = bin(int(dec_num))[2:]
    return bitstring.count('1')

def string_avg(strings, binary=True):
    """Takes a list of strings of equal length and returns a string containing
    the most common value from each index in the string.

    Optional argument: binary - a boolean indicating whether or not to treat
    strings as binary numbers (fill in leading zeros if lengths differ)."""
    if binary:
        strings = deepcopy(strings)
        longest = len(max(strings, key=len))
        for i in range(len(strings)):
            while len(strings[i]) < longest:
                split_string = strings[i].split('b')
                strings[i] = '0b0' + split_string[1]
    avg = ''
    for i in range(len(strings[0])):
        opts = []
        for s in strings:
            opts.append(s[i])
        avg += max(set(opts), key=opts.count)
    return avg

def initialize_grid(world_size, inner):
    """Creates an empty grid (2d list) with the dimensions specified in
    world_size. Each element is initialized to the inner argument."""
    data = []
    for i in range(world_size[1]):
        data.append([])
        for j in range(world_size[0]):
            data[i].append(deepcopy(inner))
    return data

def to_pascal_case(s):
    """Transform underscore separated string to pascal case

    """
    return re.sub('(?!^)_([a-zA-Z])', lambda m: m.group(1).upper(), s.capitalize())

def to_underscore(s):
    """Transform camel or pascal case to underscore separated string

    """
    return re.sub('(?!^)([A-Z]+)', lambda m: '_{0}'.format(m.group(1).lower()), re.sub('(?!^)([A-Z]{1}[a-z]{1})', lambda m: '_{0}'.format(m.group(1).lower()), s)).lower()

def entropy(dictionary):
    """Helper function for entropy calculations.
    Takes a frequency dictionary and calculates entropy of the keys."""
    total = 0.0
    entropy = 0
    for key in dictionary.keys():
        total += dictionary[key]
    for key in dictionary.keys():
        entropy += dictionary[key] / total * log(1.0 / (dictionary[key] / total), 2)
    return entropy

def sqrt_shannon_entropy(filename):
    """Calculates Shannon entropy based on square root of phenotype count.
    This might account for relationship between population size and
    evolvability."""
    data = load_grid_data(filename, 'int')
    data = agg_grid(data, mode)
    phenotypes = {}
    for r in data:
        for c in r:
            if c in phenotypes:
                phenotypes[c] += 1
            else:
                phenotypes[c] = 1
    for key in phenotypes.keys():
        phenotypes[key] = sqrt(phenotypes[key])
    return entropy(phenotypes)

def _composed_doc(fs):
    """Generate a docstring for the composition of fs."""
    if not fs:
        return 'n'
    return '{f}({g})'.format(f=fs[0].__name__, g=_composed_doc(fs[1:]))

def compose(*fs):
    """Compose functions together in order:

    compose(f, g, h) = lambda n: f(g(h(n)))"""
    rs = tuple(reversed(fs))
    def composed(n):
        return reduce(lambda a, b: b(a), rs, n)
    try:
        composed.__doc__ = 'lambda n: ' + _composed_doc(fs)
    except AttributeError:
        pass
    else:
        composed.__name__ = '_of_'.join((f.__name__ for f in fs))
    return composed

def match_entry_line(str_to_match, regex_obj=MAIN_REGEX_OBJ):
    """Does a regex match of the mount entry string"""
    match_obj = regex_obj.match(str_to_match)
    if not match_obj:
        error_message = 'Line "%s" is unrecognized by overlay4u. This is only meant for use with Ubuntu Linux.'
        raise UnrecognizedMountEntry(error_message % str_to_match)
    return match_obj.groupdict()

def raster(times, indices, max_time=None, max_index=None, x_label='Timestep', y_label='Index', **kwargs):
    """Plots a raster plot given times and indices of events."""
    if 's' not in kwargs:
        kwargs['s'] = 1
    scatter(times, indices, **kwargs)
    if max_time is None:
        max_time = max(times)
    if max_index is None:
        max_index = max(indices)
    axis((0, max_time, 0, max_index))
    if x_label is not None:
        xlabel(x_label)
    if y_label is not None:
        ylabel(y_label)

def find_next_character(code, position, char):
    """Find next char and return its first and last positions"""
    end = LineCol(code, *position)
    while not end.eof and end.char() in WHITESPACE:
        end.inc()
    if not end.eof and end.char() == char:
        return (end.tuple(), inc_tuple(end.tuple()))
    return (None, None)

def execute_catch(c, sql, vars=None):
    """Run a query, but ignore any errors. For error recovery paths where the error handler should not raise another."""
    try:
        c.execute(sql, vars)
    except Exception as err:
        cmd = sql.split(' ', 1)[0]
        log.error('Error executing %s: %s', cmd, err)

def get_via_name_list(src, name_parts):
    """Util to get name sequence from a dict. For instance, `("location","query")`
    would return src["location"]["query"]."""
    if len(name_parts) > 1:
        for part in name_parts[:-1]:
            if part not in src:
                return None
            src = src[part]
    return src.get(name_parts[-1])

def save_to_name_list(dest, name_parts, value):
    """Util to save some name sequence to a dict. For instance, `("location","query")` would save
    to dest["location"]["query"]."""
    if len(name_parts) > 1:
        for part in name_parts[:-1]:
            if part not in dest:
                dest[part] = {}
            dest = dest[part]
    dest[name_parts[-1]] = value

def escape_string(value):
    """Converts a string to its S-expression representation, adding quotes
    and escaping funny characters."""
    res = StringIO()
    res.write('"')
    for c in value:
        if c in CHAR_TO_ESCAPE:
            res.write(f'\\{CHAR_TO_ESCAPE[c]}')
        elif c.isprintable():
            res.write(c)
        elif ord(c) < 256:
            res.write(f'\\x{ord(c):02x}')
        elif ord(c) < 65536:
            res.write(f'\\u{ord(c):04x}')
        else:
            res.write(f'\\U{ord(c):06x}')
    res.write('"')
    return res.getvalue()

def expand_user(path, user=None):
    """Roughly the same as os.path.expanduser, but you can pass a default user."""
    def _replace(m):
        m_user = m.group(1) or user
        return pwd.getpwnam(m_user).pw_dir if m_user else pwd.getpwuid(os.getuid()).pw_dir
    return re.sub('~(\\w*)', _replace, path)

def unique_list(input_, key=lambda x: x):
    """Return the unique elements from the input, in order."""
    seen = set()
    output = []
    for x in input_:
        keyx = key(x)
        if keyx not in seen:
            seen.add(keyx)
            output.append(x)
    return output

def get_environ_list(name, default=None):
    """Return the split colon-delimited list from an environment variable.

    Returns an empty list if the variable didn't exist."""
    packed = os.environ.get(name)
    if packed is not None:
        return packed.split(':')
    elif default is not None:
        return default
    else:
        return []

def is_indel(reference_bases, alternate_bases):
    """Return whether or not the variant is an INDEL"""
    if len(reference_bases) > 1:
        return True
    for alt in alternate_bases:
        if alt is None:
            return True
        elif len(alt) != len(reference_bases):
            return True
    return False

def is_snp(reference_bases, alternate_bases):
    """Return whether or not the variant is a SNP"""
    if len(reference_bases) > 1:
        return False
    for alt in alternate_bases:
        if alt is None:
            return False
        if alt not in ['A', 'C', 'G', 'T', 'N', '*']:
            return False
    return True

def is_deletion(reference_bases, alternate_bases):
    """Return whether or not the INDEL is a deletion"""
    if len(alternate_bases) > 1:
        return False
    if is_indel(reference_bases, alternate_bases):
        alt_allele = alternate_bases[0]
        if alt_allele is None:
            return True
        if len(reference_bases) > len(alt_allele):
            return True
        else:
            return False
    else:
        return False

def get_input(prompt, default=None, choices=None, option_value=None):
    """If option_value is not None, then return it. Otherwise get the result from
    input."""
    if option_value is not None:
        return option_value
    choices = choices or []
    while 1:
        r = input(prompt + ' ').strip()
        if not r and default is not None:
            return default
        if choices:
            if r not in choices:
                r = None
            else:
                break
        else:
            break
    return r

def _error_repr(error):
    """A compact unique representation of an error."""
    error_repr = repr(error)
    if len(error_repr) > 200:
        error_repr = hash(type(error))
    return error_repr

def annotation_has_expired(event, key, timeout):
    """Check if an event error has expired."""
    anns = get_annotations(event, key)
    if anns:
        return time.time() - anns[0]['ts'] > timeout
    else:
        return False

def replace_event_annotations(event, newanns):
    """Replace event annotations with the provided ones."""
    _humilis = event.get('_humilis', {})
    if not _humilis:
        event['_humilis'] = {'annotation': newanns}
    else:
        event['_humilis']['annotation'] = newanns

def annotate_event(ev, key, ts=None, namespace=None, **kwargs):
    """Add an annotation to an event."""
    ann = {}
    if ts is None:
        ts = time.time()
    ann['ts'] = ts
    ann['key'] = key
    if namespace is None and 'HUMILIS_ENVIRONMENT' in os.environ:
        namespace = '{}:{}:{}'.format(os.environ.get('HUMILIS_ENVIRONMENT'), os.environ.get('HUMILIS_LAYER'), os.environ.get('HUMILIS_STAGE'))
    if namespace is not None:
        ann['namespace'] = namespace
    ann.update(kwargs)
    _humilis = ev.get('_humilis', {})
    if not _humilis:
        ev['_humilis'] = {'annotation': [ann]}
    else:
        ev['_humilis']['annotation'] = _humilis.get('annotation', [])
        delete_annotations(ev, key)
        ev['_humilis']['annotation'].append(ann)
    return ev

def get_annotations(event, key, namespace=None, matchfunc=None):
    """Produce the list of annotations for a given key."""
    if matchfunc is None:
        matchfunc = _is_equal
    if isinstance(key, Exception):
        key = _error_repr(key)
    return [ann for ann in event.get('_humilis', {}).get('annotation', []) if matchfunc(key, ann['key']) and (namespace is None or ann.get('namespace') == namespace)]

def delete_annotations(event, key, namespace=None, matchfunc=None):
    """Delete all event annotations with a matching key."""
    if matchfunc is None:
        matchfunc = _is_equal
    if isinstance(key, Exception):
        key = _error_repr(key)
    newanns = [ann for ann in event.get('_humilis', {}).get('annotation', []) if not (matchfunc(key, ann['key']) and (namespace is None or ann.get('namespace') == namespace))]
    replace_event_annotations(event, newanns)

def get_function_annotations(event, funcname, type=None, namespace=None):
    """Produce a list of function annotations in in this event."""
    if type:
        postfix = '|' + type
    else:
        postfix = '|.+'
    def matchfunc(key, annkey):
        """Check if the provider regex matches an annotation key."""
        return re.match(key, annkey) is not None
    return get_annotations(event, funcname + postfix, namespace=namespace, matchfunc=matchfunc)

def native_decode_source(text):
    """Use codec specified in file to decode to unicode
    Then, encode unicode to native str:
        Python 2: bytes
        Python 3: unicode"""
    if only_python3 and isinstance(text, bytes) or (only_python2 and isinstance(text, str)):
        text = decode_source_to_unicode(text)
    if only_python2:
        return text.encode('ascii', 'replace')
    return text

def url_content(url, cache_duration=None, from_cache_on_error=False):
    """Get content for the given URL

    :param str url: The URL to get content from
    :param int cache_duration: Optionally cache the content for the given duration to avoid downloading too often.
    :param bool from_cache_on_error: Return cached content on any HTTP request error if available."""
    cache_file = _url_content_cache_file(url)
    if cache_duration:
        if os.path.exists(cache_file):
            stat = os.stat(cache_file)
            cached_time = stat.st_mtime
            if time.time() - cached_time < cache_duration:
                with open(cache_file) as fp:
                    return fp.read()
    try:
        response = requests.get(url, timeout=5)
        response.raise_for_status()
        content = response.text
    except Exception as e:
        if from_cache_on_error and os.path.exists(cache_file):
            with open(cache_file) as fp:
                return fp.read()
        else:
            raise e.__class__('An error occurred when getting content for %s: %s' % (url, e))
    if cache_duration or from_cache_on_error:
        with open(cache_file, 'w') as fp:
            fp.write(content)
    return content

def route(**kwargs):
    """Route a request to different views based on http verb.

    Kwargs should be 'GET', 'POST', 'PUT', 'DELETE' or 'ELSE',
    where the first four map to a view to route to for that type of
    request method/verb, and 'ELSE' maps to a view to pass the request
    to if the given request method/verb was not specified."""
    def routed(request, *args2, **kwargs2):
        method = request.method
        if method in kwargs:
            req_method = kwargs[method]
            return req_method(request, *args2, **kwargs2)
        elif 'ELSE' in kwargs:
            return kwargs['ELSE'](request, *args2, **kwargs2)
        else:
            raise Http404()
    return routed

def render_template(template):
    """takes a template to render to and returns a function that
    takes an object to render the data for this template.

    If callable_or_dict is callable, it will be called with
    the request and any additional arguments to produce the
    template paramaters. This is useful for a view-like function
    that returns a dict-like object instead of an HttpResponse.

    Otherwise, callable_or_dict is used as the parameters for
    the rendered response."""
    def outer_wrapper(callable_or_dict=None, statuscode=None, **kwargs):
        def wrapper(request, *args, **wrapper_kwargs):
            if callable(callable_or_dict):
                params = callable_or_dict(request, *args, **wrapper_kwargs)
            else:
                params = callable_or_dict
            if params is None or isinstance(params, dict):
                resp = render(request, template, params, **kwargs)
            else:
                resp = params
            if statuscode:
                resp.status_code = statuscode
            return resp
        return wrapper
    return outer_wrapper

def json_api_call(req_function):
    """Wrap a view-like function that returns an object that
    is convertable from json"""
    @wraps(req_function)
    def newreq(request, *args, **kwargs):
        outp = req_function(request, *args, **kwargs)
        if issubclass(outp.__class__, HttpResponse):
            return outp
        else:
            return '%s' % json.dumps(outp, cls=LazyEncoder)
    return string_to_response('application/json')(newreq)

def string_to_response(content_type):
    """Wrap a view-like function that returns a string and marshalls it into an
    HttpResponse with the given Content-Type
    If the view raises an HttpBadRequestException, it will be converted into
    an HttpResponseBadRequest."""
    def outer_wrapper(req_function):
        @wraps(req_function)
        def newreq(request, *args, **kwargs):
            try:
                outp = req_function(request, *args, **kwargs)
                if issubclass(outp.__class__, HttpResponse):
                    response = outp
                else:
                    response = HttpResponse()
                    response.write(outp)
                    response['Content-Length'] = str(len(response.content))
                response['Content-Type'] = content_type
            except HttpBadRequestException as bad_request:
                response = HttpResponseBadRequest(bad_request.message)
            return response
        return newreq
    return outer_wrapper

def username_matches_request_user(view_fn):
    """Checks if the username matches the request user, and if so replaces
    username with the actual user object.
    Returns 404 if the username does not exist, and 403 if it doesn't match."""
    @wraps(view_fn)
    def wrapper(request, username, *args, **kwargs):
        User = get_user_model()
        user = get_object_or_404(User, username=username)
        if user != request.user:
            return HttpResponseForbidden()
        else:
            return view_fn(request, user, *args, **kwargs)
    return wrapper

