def queue_exc(*arg, **kw):
    """Queue undefined variable exception"""
    _self = arg[0]
    if not isinstance(_self, AnsibleUndefinedVariable):
        return
    _rslt_q = None
    for stack_trace in inspect.stack():
        if stack_trace[3] in SKIP_METHODS:
            continue
        _frame = stack_trace[0]
        _locals = inspect.getargvalues(_frame).locals
        if 'self' not in _locals:
            continue
        if isinstance(_locals['self'], WorkerProcess):
            _rslt_q = getattr(_locals['self'], '_rslt_q')
    if not _rslt_q:
        raise ValueError('No Queue found.')
    _rslt_q.put(arg[3].message, interceptor=True)

def extract_worker_exc(*arg, **kw):
    """Get exception added by worker"""
    _self = arg[0]
    if not isinstance(_self, StrategyBase):
        return
    for _worker_prc, _main_q, _rslt_q in _self._workers:
        _task = _worker_prc._task
        if _task.action == 'setup':
            continue
        while True:
            try:
                _exc = _rslt_q.get(block=False, interceptor=True)
                RESULT[_task.name].add(_exc)
            except Empty:
                break

def int_attribute(element, attribute, default=0):
    """Returns the int value of an attribute, or a default if it's not defined
    :param element: The XML Element object
    :type  element: etree._Element

    :param attribute: The name of the attribute to evaluate
    :type  attribute: basestring

    :param default: The default value to return if the attribute is not defined
    :type  default: int

    :rtype: int"""
    attribute_value = element.get(attribute)
    if attribute_value:
        try:
            return int(attribute_value)
        except (TypeError, ValueError):
            return default
    return default

def int_element(element, name, default=0):
    """Returns the int value of an element, or a default if it's not defined
    :param element: The XML Element object
    :type  element: etree._Element

    :param name: The name of the element to evaluate
    :type  name: str

    :param default: The default value to return if the element is not defined
    :type  default: int

    :rtype: int"""
    element_value = element.find(name)
    if element_value is not None:
        try:
            return int(element_value.text)
        except (TypeError, ValueError):
            return default
    return default

