def _make_rewritten_pyc(state, fn, pyc, co):
    """Try to dump rewritten code to *pyc*."""
    if sys.platform.startswith('win'):
        _write_pyc(state, co, fn, pyc)
    else:
        proc_pyc = pyc + '.' + str(os.getpid())
        if _write_pyc(state, co, fn, proc_pyc):
            os.rename(proc_pyc, pyc)

def _read_pyc(source, pyc):
    """Possibly read a pytest pyc containing rewritten code.

    Return rewritten code if successful or None if not."""
    try:
        fp = open(pyc, 'rb')
    except IOError:
        return None
    try:
        try:
            mtime = int(os.stat(source).st_mtime)
            data = fp.read(8)
        except EnvironmentError:
            return None
        if len(data) != 8 or data[:4] != imp.get_magic() or struct.unpack('<l', data[4:])[0] != mtime:
            return None
        co = marshal.load(fp)
        if not isinstance(co, types.CodeType):
            return None
        return co
    finally:
        fp.close()

def set_location(node, lineno, col_offset):
    """Set node location information recursively."""
    def _fix(node, lineno, col_offset):
        if 'lineno' in node._attributes:
            node.lineno = lineno
        if 'col_offset' in node._attributes:
            node.col_offset = col_offset
        for child in ast.iter_child_nodes(node):
            _fix(child, lineno, col_offset)
    _fix(node, lineno, col_offset)
    return node

