def get_version(svn=False, limit=3):
    """Returns the version as a human-format string."""
    v = '.'.join([str(i) for i in VERSION[:limit]])
    if svn and limit >= 3:
        from django.utils.version import get_svn_revision
        import os
        svn_rev = get_svn_revision(os.path.dirname(__file__))
        if svn_rev:
            v = '%s.%s' % (v, svn_rev)
    return v

def sometimes(fn):
    """They've done studies, you know. 50% of the time,
    it works every time."""
    def wrapped(*args, **kwargs):
        wrapped.x += 1
        if wrapped.x % 2 == 1:
            return fn(*args, **kwargs)
    wrapped.x = 0
    return wrapped

def percent_of_the_time(p):
    """Function has a X percentage chance of running"""
    def decorator(fn):
        def wrapped(*args, **kwargs):
            if in_percentage(p):
                fn(*args, **kwargs)
        return wrapped
    return decorator

def rarely(fn):
    """Only 5% chance of happening"""
    def wrapped(*args, **kwargs):
        if in_percentage(5):
            fn(*args, **kwargs)
    return wrapped

def mostly(fn):
    """95% chance of happening"""
    def wrapped(*args, **kwargs):
        if in_percentage(95):
            fn(*args, **kwargs)
    return wrapped

def times(x, y):
    """Do something a random amount of times
    between x & y"""
    def decorator(fn):
        def wrapped(*args, **kwargs):
            n = random.randint(x, y)
            for z in range(1, n):
                fn(*args, **kwargs)
        return wrapped
    return decorator

def sha1(s):
    """Returns a sha1 of the given string
    """
    h = hashlib.new('sha1')
    h.update(s)
    return h.hexdigest()

