def _diff_text(left, right, verbose=False):
    """Return the explanation for the diff between text or bytes

    Unless --verbose is used this will skip leading and trailing
    characters which are identical to keep the diff minimal.

    If the input are bytes they will be safely converted to text."""
    from difflib import ndiff
    explanation = []
    if isinstance(left, py.builtin.bytes):
        left = u(repr(left)[1:-1]).replace('\\n', '\n')
    if isinstance(right, py.builtin.bytes):
        right = u(repr(right)[1:-1]).replace('\\n', '\n')
    if not verbose:
        i = 0
        for i in range(min(len(left), len(right))):
            if left[i] != right[i]:
                break
        if i > 42:
            i -= 10
            explanation = [u('Skipping %s identical leading characters in diff, use -v to show') % i]
            left = left[i:]
            right = right[i:]
        if len(left) == len(right):
            for i in range(len(left)):
                if left[-i] != right[-i]:
                    break
            if i > 42:
                i -= 10
                explanation += [u('Skipping %s identical trailing characters in diff, use -v to show') % i]
                left = left[:-i]
                right = right[:-i]
    keepends = True
    explanation += [line.strip('\n') for line in ndiff(left.splitlines(keepends), right.splitlines(keepends))]
    return explanation

def wrap_cors(func=None, *, allow_origin='*', allow_headers=DEFAULT_HEADERS):
    """A middleware that allow CORS calls, by adding the
    headers Access-Control-Allow-Origin and Access-Control-Allow-Headers.
    This middlware accepts two optional parameters `allow_origin` and
    `allow_headers` for customization of the headers values. By default
    will be `*` and a set of `[Origin, X-Requested-With, Content-Type, Accept]`
    respectively."""
    if func is None:
        return functools.partial(wrap_cors, allow_origin=allow_origin, allow_headers=allow_headers)
    _allow_headers = ', '.join(allow_headers)
    @functools.wraps(func)
    def wrapper(request, *args, **kwargs):
        response = func(request, *args, **kwargs)
        if not response.headers:
            response.headers = {}
        response.headers['Access-Control-Allow-Origin'] = allow_origin
        response.headers['Access-Control-Allow-Headers'] = _allow_headers
        return response
    return wrapper

