def clef_error_check(func_to_decorate):
    """Return JSON decoded response from API call. Handle errors when bad response encountered."""
    def wrapper(*args, **kwargs):
        try:
            response = func_to_decorate(*args, **kwargs)
        except requests.exceptions.RequestException:
            raise ConnectionError('Clef encountered a network connectivity problem. Are you sure you are connected to the Internet?')
        else:
            raise_right_error(response)
        return response.json()
    return wrapper

def raise_right_error(response):
    """Raise appropriate error when bad response received."""
    if response.status_code == 200:
        return
    if response.status_code == 500:
        raise ServerError('Clef servers are down.')
    if response.status_code == 403:
        message = response.json().get('error')
        error_class = MESSAGE_TO_ERROR_MAP[message]
        if error_class == InvalidOAuthTokenError:
            message = 'Something went wrong at Clef. Unable to retrieve user information with this token.'
        raise error_class(message)
    if response.status_code == 400:
        message = response.json().get('error')
        error_class = MESSAGE_TO_ERROR_MAP[message]
        if error_class:
            raise error_class(message)
        else:
            raise InvalidLogoutTokenError(message)
    if response.status_code == 404:
        raise NotFoundError('Unable to retrieve the page. Are you sure the Clef API endpoint is configured right?')
    raise APIError

def assign_ranks_to_grid(grid, ranks):
    """Takes a 2D array of binary numbers represented as strings and a dictionary
    mapping binary strings to integers representing the rank of the cluster
    they belong to, and returns a grid in which each binary number has been
    replaced with the rank of its cluster."""
    assignments = deepcopy(grid)
    ranks['0b0'] = 0
    ranks['-0b1'] = -1
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if type(grid[i][j]) is list:
                for k in range(len(grid[i][j])):
                    assignments[i][j][k] = ranks[grid[i][j][k]]
            else:
                assignments[i][j] = ranks[grid[i][j]]
    return assignments

def cluster_types(types, max_clust=12):
    """Generates a dictionary mapping each binary number in types to an integer
    from 0 to max_clust. Hierarchical clustering is used to determine which
    which binary numbers should map to the same integer."""
    if len(types) < max_clust:
        max_clust = len(types)
    cluster_dict = do_clustering(types, max_clust)
    cluster_ranks = rank_clusters(cluster_dict)
    ranks = {}
    for key in cluster_dict:
        for typ in cluster_dict[key]:
            ranks[typ] = cluster_ranks[key]
    return ranks

def make_count_grid(data):
    """Takes a 2 or 3d grid of strings representing binary numbers.

    Returns a grid of the same dimensions in which each binary number has been
    replaced by an integer indicating the number of ones that were in that
    number."""
    data = deepcopy(data)
    for i in range(len(data)):
        for j in range(len(data[i])):
            for k in range(len(data[i][j])):
                if type(data[i][j][k]) is list:
                    for l in range(len(data[i][j][k])):
                        try:
                            data[i][j][k] = data[i][j][k][l].count('1')
                        except:
                            data[i][j][k] = len(data[i][j][k][l])
                else:
                    try:
                        data[i][j][k] = data[i][j][k].count('1')
                    except:
                        data[i][j][k] = len(data[i][j][k])
    return data

def from_status(status, message=None, extra=None):
    """Try to create an error from status code

    :param int status: HTTP status
    :param str message: Body content
    :param dict extra: Additional info
    :return: An error
    :rtype: cdumay_rest_client.errors.Error"""
    if status in HTTP_STATUS_CODES:
        return HTTP_STATUS_CODES[status](message=message, extra=extra)
    else:
        return Error(code=status, message=message if message else 'Unknown Error', extra=extra)

def from_response(response, url):
    """Try to create an error from a HTTP response

    :param request.Response response: HTTP response
    :param str url: URL attained
    :return: An error
    :rtype: cdumay_rest_client.errors.Error"""
    try:
        data = response.json()
        if not isinstance(data, dict):
            return from_status(response.status_code, response.text, extra=dict(url=url, response=response.text))
        code = data.get('code', response.status_code)
        if code in HTTP_STATUS_CODES:
            return HTTP_STATUS_CODES[code](**ErrorSchema().load(data))
        else:
            return Error(**ErrorSchema().load(data))
    except Exception:
        return from_status(response.status_code, response.text, extra=dict(url=url, response=response.text))

def verify_directory(directory_name, directory_location, directory_create=False):
    """Function to verify if a directory exists
    Args:
        directory_name: The name of directory to check
        directory_location: The location of the directory, derive from the os module
        directory_create: If you want to create the directory

    Returns: returns boolean True or False, but if you set directory_create to True it will create the directory"""
    if not directory_create:
        return __os.path.exists(__os.path.join(directory_location, directory_name))
    elif directory_create:
        good = __os.path.exists(__os.path.join(directory_location, directory_name))
        if not good:
            __os.mkdir(__os.path.join(directory_location, directory_name))

