def hone_cache(maxsize=128, maxage=None, refineby='startswith', store_partials=False):
    """A caching decorator that follows after the style of lru_cache. Calls
    that are sharper than previous requests are returned from the cache after
    honing in on the requested results using the `refineby` technique.

    The `refineby` technique can be `startswith`, `container` or a user
    defined function used to provide a subset of results.

    Eg.
        @hone_cache()
        def completer(prefix):
            print("MISS")
            return set(x for x in {'foo', 'foobar', 'baz'}
                       if x.startswith(prefix))
        completer('f')    # -> {'foo', 'foobar'}
        MISS
        completer('fo')   # -> {'foo', 'foobar'}
        completer('foob') # -> {'foobar'}
        completer('')     # -> {'foo', 'foobar', 'baz'}
        MISS
        completer('ba')   # -> {'baz'}

    If while trying to hone a cache hit there is an exception the wrapped
    function will be called as if it was a full miss.

    The `maxage` argument is an option time-to-live in seconds for each cache
    result.  Any cache entries over the maxage are lazily replaced."""
    if not callable(refineby):
        finder = hone_cache_finders[refineby]
    else:
        finder = refineby
    def decorator(inner_func):
        wrapper = make_hone_cache_wrapper(inner_func, maxsize, maxage, finder, store_partials)
        return functools.update_wrapper(wrapper, inner_func)
    return decorator

def ttl_cache(maxage, maxsize=128):
    """A time-to-live caching decorator that follows after the style of
    lru_cache.  The `maxage` argument is time-to-live in seconds for each
    cache result.  Any cache entries over the maxage are lazily replaced."""
    def decorator(inner_func):
        wrapper = make_ttl_cache_wrapper(inner_func, maxage, maxsize)
        return functools.update_wrapper(wrapper, inner_func)
    return decorator

def make_ttl_cache_wrapper(inner_func, maxage, maxsize, typed=False):
    """Use the function signature as a key for a ttl mapping.  Any misses
    will defer to the wrapped function and its result is stored for future
    calls."""
    hits = misses = 0
    cache = TTLMapping(maxsize, maxage)
    def wrapper(*args, **kwargs):
        nonlocal hits, misses
        key = functools._make_key(args, kwargs, typed)
        try:
            result = cache[key]
        except KeyError:
            misses += 1
            result = cache[key] = inner_func(*args, **kwargs)
        else:
            hits += 1
        return result
    def cache_info():
        """Emulate lru_cache so this is a low touch replacement."""
        return TTLCacheInfo(hits, misses, maxsize, len(cache), maxage)
    def cache_clear():
        """Clear cache and stats."""
        nonlocal hits, misses
        hits = misses = 0
        cache.clear()
    wrapper.cache_info = cache_info
    wrapper.cache_clear = cache_clear
    return functools.update_wrapper(wrapper, inner_func)

def get_programs():
    """Returns a generator that yields the available executable programs

    :returns: a generator that yields the programs available after a refresh_listing()
    :rtype: generator"""
    programs = []
    os.environ['PATH'] += os.pathsep + os.getcwd()
    for p in os.environ['PATH'].split(os.pathsep):
        if path.isdir(p):
            for f in os.listdir(p):
                if _is_executable(path.join(p, f)):
                    yield f

def _underscore_run_program(name, *args, **kwargs):
    """Runs the 'name' program, use this if there are illegal python method characters in the program name

    >>> _underscore_run_program("echo", "Hello")
    'Hello'
    >>> _underscore_run_program("echo", "Hello", return_object=True).stdout
    'Hello'
    >>> _underscore_run_program("echo", "Hello", ro=True).stdout
    'Hello'"""
    if name in get_programs() or kwargs.get('shell', False):
        return _run_program(name, *args, **kwargs)
    else:
        raise ProgramNotFoundException()

def refresh_listing():
    """Refreshes the list of programs attached to the perform module from
    the path"""
    for program in get_programs():
        if re.match('^[a-zA-Z_][a-zA-Z_0-9]*$', program) is not None:
            globals()[program] = partial(_run_program, program)
    globals()['_'] = _underscore_run_program

def combine_dicts(*args, **kwargs):
    """Combines all arguments (if they are dictionaries) and kwargs to a final dict

    :param args: dict, any dictionaries the user wants combined
    :param kwargs: dict, kwargs.
    :return: dict, compiled dictionary"""
    dicts = [arg for arg in args if isinstance(arg, dict)]
    dicts.append(kwargs)
    super_dict = collections.defaultdict(dict)
    for d in dicts:
        for k, v in iteritems(d):
            if k:
                super_dict[k] = v
    return dict(super_dict)

def get_keys_containing(search_string, input_dict, default=None, first_found=True):
    """Searches a dictionary for all keys containing the search string (as long as the keys are not functions) and
        returns a filtered dictionary of only those keys

    :param search_string: str, string we are looking for
    :param input_dict: dict, dictionary to search through
    :param default: object, if we find nothing, return this as the default
    :param first_found: bool, return the first found key
    :return: dict, dictionary filled with any matching keys"""
    output = {}
    for k, v in iteritems(input_dict):
        if search_string in k and (not callable(k)):
            output[k] = v
    if first_found:
        try:
            output = output[next(iter(output))]
        except StopIteration:
            pass
    return output or default

def gen_dict_key_matches(key, dictionary, _path=None, full_path=False):
    """Generates a list of sets of (path, value) where path is a list of keys to access the given value in the given
        nested dictionary

    :param key: object, given dictionary key we are looking for
    :param dictionary: dict, query dictionary
    :param _path: list(str), internal use for the current path to output in case of match.
    :param full_path: bool, return value or (path, value))
    :return: Generator[object] or Generator[(list(str), object)], generator of (path, value) or just value"""
    if _path is None:
        _path = []
    for k, v in iteritems(dictionary):
        _path.append(k)
        if k == key:
            yield ((_path, v) if full_path else v)
        elif isinstance(v, dict):
            for result in gen_dict_key_matches(key, v, _path):
                yield result

def flatten(it):
    """Flattens any iterable
        From:
        http://stackoverflow.com/questions/11503065/python-function-to-flatten-generator-containing-another-generator

    :param it: Iterator, iterator to flatten
    :return: Generator, A generator of the flattened values"""
    for x in it:
        if isinstance(x, collections.Iterable) and (not isinstance(x, str)):
            for y in flatten(x):
                yield y
        else:
            yield x

