def to_bytes(x, blocksize=0):
    """Converts input to a byte string.
    Typically used in PyCrypto as an argument (e.g., key, iv)

    :param x: string (does nothing), bytearray, array with numbers
    :return:"""
    if isinstance(x, bytearray):
        return left_zero_pad(bytes(x), blocksize)
    elif isinstance(x, basestring):
        return left_zero_pad(x, blocksize)
    elif isinstance(x, (list, tuple)):
        return left_zero_pad(bytes(bytearray(x)), blocksize)
    elif isinstance(x, (long, int)):
        return long_to_bytes(x, blocksize)
    else:
        raise ValueError('Unknown input argument type')

def to_long(x):
    """Converts input to a long number (arbitrary precision python long)
    :param x:
    :return:"""
    if isinstance(x, long):
        return x
    elif isinstance(x, int):
        return long(x)
    else:
        return bytes_to_long(to_bytes(x))

def to_hex(x):
    """Converts input to the hex string
    :param x:
    :return:"""
    if isinstance(x, bytearray):
        x = bytes(x)
    elif isinstance(x, (list, tuple)):
        x = bytes(bytearray(x))
    if isinstance(x, basestring):
        return base64.b16encode(x).decode('ascii')
    else:
        raise ValueError('Unknown input argument type')

def aes(encrypt, key, data):
    """One-pass AES-256-CBC used in ProcessData. Zero IV (don't panic, IV-like random nonce is included in plaintext in the
    first block in ProcessData).

    Does not use padding (data has to be already padded).

    :param encrypt:
    :param key:
    :param data:
    :return:"""
    cipher = AES.new(key, AES.MODE_CBC, get_zero_vector(16))
    if encrypt:
        return cipher.encrypt(data)
    else:
        return cipher.decrypt(data)

def pager_redirect(desc, *, pagercmd=None, istty=None, file=None, substitutions=None):
    """Redirect output to file/stdout to a pager process.  Care is taken to
    restore the controlling tty stdio files to their original state."""
    global _pager_active
    if file is None:
        file = sys.stdout
    if not pagercmd or not file.isatty() or _pager_active:
        yield
        return
    subs = {'desc': desc}
    if substitutions is not None:
        subs.update(substitutions)
    pagercmd = pagercmd.format(**subs)
    with tty_restoration():
        p = pager_process(pagercmd)
        if istty is None:
            p.stdin.isatty = file.isatty
        else:
            p.stdin.isatty = lambda: istty
        stdout_save = sys.stdout
        sys.stdout = p.stdin
        _pager_active = True
        try:
            yield
        finally:
            _pager_active = False
            sys.stdout = stdout_save
            try:
                p.stdin.close()
            except BrokenPipeError:
                pass
            while p.poll() is None:
                try:
                    p.wait()
                except KeyboardInterrupt:
                    pass

