def _is_kpoint(line):
    """Is this line the start of a new k-point block"""
    toks = line.split()
    if len(toks) != 4:
        return False
    try:
        xs = [float(x) for x in toks[:3]]
        w = float(toks[3])
        return all((abs(x) <= 0.5 for x in xs)) and w >= 0.0 and (w <= 1.0)
    except ValueError:
        return False

