def restrict(d, restrict):
    """Restrict data by indices.

    Parameters:
    ----------

    d         -- the flds/sclr data
    restrict  -- a tuple of [xmin,xmax,...] etx"""
    notqs = ['t', 'xs', 'ys', 'zs', 'fd', 'sd']
    keys = [k for k in d if k not in notqs]
    if len(restrict) == 2:
        for k in keys:
            d[k] = d[k][restrict[0]:restrict[1]]
    elif len(restrict) == 4:
        for k in keys:
            d[k] = d[k][restrict[0]:restrict[1], restrict[2]:restrict[3]]
    elif len(restrict) == 6:
        for k in keys:
            d[k] = d[k][restrict[0]:restrict[1], restrict[2]:restrict[3], restrict[4]:restrict[5]]
    else:
        raise ValueError('restrict of length {} is not valid'.format(len(restrict)))

