def process_exists(pid=None):
    """Evaluates a Pid Value defaults to the currently foucsed window
    against the current open programs,
    if there is a match returns the process name and pid
    otherwise returns None, None"""
    if not pid:
        pid = current_pid()
    elif callable(pid):
        pid = pid()
    if pid and psutil.pid_exists(pid):
        pname = psutil.Process(pid).name()
        if os.name == 'nt':
            return (os.path.splitext(pname)[0], pid)
        return (pname, pid)
    return (None, None)

def listpid(toggle='basic'):
    """list pids"""
    proc = psutil.process_iter()
    if toggle == 'basic':
        host = gethostname()
        host2 = os.getenv('HOME').split(sep='/')[-1]
        for row in proc:
            if row.username() in host or row.username() in host2:
                yield (row.name(), row.ppid())
    elif toggle == 'all':
        for row in proc:
            yield (row.name(), row.ppid())
    elif toggle == 'windows-basic':
        for row in proc:
            try:
                pname = psutil.Process(row.pid).name()
                pname = pname[:-4]
                yield (pname, row.pid)
            except:
                pass

