def transpose_mat44(src_mat, transpose_mat=None):
    """Create a transpose of a matrix."""
    if not transpose_mat:
        transpose_mat = Matrix44()
    for i in range(4):
        for j in range(4):
            transpose_mat.data[i][j] = src_mat.data[j][i]
    return transpose_mat

def is_affine_mat44(mat):
    """Return True if only tranlsate, rotate, and uniform scale components."""
    if not mat.data[0][0] == mat.data[1][1] == mat.data[2][2]:
        return False
    return mat.data[0][3] == 0 and mat.data[1][3] == 0 and (mat.data[2][3] == 0) and (mat.data[3][3] == 1)

def invert_affine_mat44(mat):
    """Assumes there is only rotate, translate, and uniform scale componenets
    to the matrix."""
    inverted = Matrix44()
    for i in range(3):
        for j in range(3):
            inverted.data[i][j] = mat.data[j][i]
    for row in range(3):
        inverted.data[3][row] = -inverted.data[0][row] * mat.data[3][0] + -inverted.data[1][row] * mat.data[3][1] + -inverted.data[2][row] * mat.data[3][2]
    return inverted

def to_timestamp(dt):
    """Convert a datetime object to a unix timestamp.

    Note that unlike a typical unix timestamp, this is seconds since 1970
    *local time*, not UTC.

    If the passed in object is already a timestamp, then that value is
    simply returned unmodified."""
    if isinstance(dt, int):
        return dt
    return int(total_seconds(dt.replace(tzinfo=None) - datetime.datetime(1970, 1, 1)))

def as_session(name_or_func):
    """print start/title/end info before and after the function call

    Args:
        title: title will show after the start, if has any"""
    if callable(name_or_func):
        func = name_or_func
        name = func.__name__
        name = ''.join([' ' + x if x.isupper() else x for x in name])
        name = name.replace('_', ' ')
        return as_session(name)(func)
    else:
        name = name_or_func
    def get_func(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            start()
            title(name)
            result = func(*args, **kwargs)
            end()
            return result
        return wrapper
    return get_func

