def install():
    """Install your package to all Python version you have installed on Windows.
    """
    import os, shutil
    _ROOT = os.getcwd()
    _PACKAGE_NAME = os.path.basename(_ROOT)
    print('Installing [%s] to all python version...' % _PACKAGE_NAME)
    installed_python_version = list()
    for root, folder_list, _ in os.walk('C:\\\\'):
        for folder in folder_list:
            if folder.startswith('Python'):
                if os.path.exists(os.path.join(root, folder, 'pythonw.exe')):
                    installed_python_version.append(folder)
        break
    print('\tYou have installed: {0}'.format(', '.join(installed_python_version)))
    print('\tRemoving *.pyc file ...')
    pyc_folder_list = list()
    for root, folder_list, _ in os.walk(_ROOT):
        if os.path.basename(root) == '__pycache__':
            pyc_folder_list.append(root)
    for folder in pyc_folder_list:
        shutil.rmtree(folder)
    print('\t\tall *.pyc file has been removed.')
    for py_root in installed_python_version:
        dst = os.path.join('C:\\\\', py_root, 'Lib\\site-packages', _PACKAGE_NAME)
        try:
            shutil.rmtree(dst)
        except:
            pass
        print('\tRemoved %s.' % dst)
        shutil.copytree(_ROOT, dst)
        print('\tInstalled %s.' % dst)
    print('Complete!')

def namedtuple_asdict(obj):
    """Serializing a nested namedtuple into a Python dict"""
    if obj is None:
        return obj
    if hasattr(obj, '_asdict'):
        return OrderedDict(zip(obj._fields, (namedtuple_asdict(item) for item in obj)))
    if isinstance(obj, str):
        return obj
    if hasattr(obj, 'keys'):
        return OrderedDict(zip(obj.keys(), (namedtuple_asdict(item) for item in obj.values())))
    if hasattr(obj, '__iter__'):
        return type(obj)((namedtuple_asdict(item) for item in obj))
    return obj

def _unpack_from(buf, format_s, count=None, little_endian=True):
    """Read a binary format from the buffer."""
    if count is not None:
        assert count > 0
        format_s = '%i%s' % (count, format_s)
    if little_endian is True:
        format_s = '<' + format_s
    else:
        format_s = '>' + format_s
    size = struct.calcsize(format_s)
    res = struct.unpack_from(format_s, buf.read(size))
    if count is not None:
        return res
    else:
        return res[0]

def make_octal_permissions_mode(user=(False, False, False), group=(False, False, False), other=(False, False, False)):
    """Create a permissions bit in absolute notation (octal).

    The user, group and other parameters are tuples representing Read, Write and Execute values.
    All are set disallowed (set to false) by default and can be individually permitted.

    :param user: User permissions
    :param group: Group permissions
    :param other: Other permissions
    :return: Permissions bit"""
    mode = ''
    for name in (user, group, other):
        read, write, execute = name
        if execute and (not all((i for i in (read, write)))):
            code = 1
        elif write and (not all((i for i in (read, execute)))):
            code = 2
        elif all((i for i in (write, execute))) and (not read):
            code = 3
        elif read and (not all((i for i in (write, execute)))):
            code = 4
        elif all((i for i in (read, execute))) and (not write):
            code = 5
        elif all((i for i in (read, write))) and (not execute):
            code = 6
        elif all((i for i in (read, write, execute))):
            code = 7
        else:
            code = 0
        mode += str(code)
    return int(mode)

