def render(obj):
    """Convienently render strings with the fabric context"""
    def get_v(v):
        return v % env if isinstance(v, basestring) else v
    if isinstance(obj, types.StringType):
        return obj % env
    elif isinstance(obj, types.TupleType) or isinstance(obj, types.ListType):
        rv = []
        for v in obj:
            rv.append(get_v(v))
    elif isinstance(obj, types.DictType):
        rv = {}
        for k, v in obj.items():
            rv[k] = get_v(v)
    return rv

def parse_args(add_args, docstring):
    """Parse out command line arguments"""
    def run_args():
        """Run any global methods eponymous with args"""
        valuable_args = {k for k, v in args.__dict__.items() if v}
        arg_methods = {globals()[a] for a in valuable_args if a in globals()}
        if not arg_methods:
            return
        for method in arg_methods:
            method()
        raise SystemExit(_exit_ok)
    parser = argparse.ArgumentParser(description=docstring and docstring.splitlines()[0] or 'No docstring')
    result = add_args(parser)
    parser = result if result else parser
    parser.add_argument('-v', '--version', action='store_true', help='Show version [default: %s]' % __version__)
    global args
    args = parser.parse_args()
    run_args()
    return args

def main(method, add_args, version=None, docstring=None, error_stream=sys.stderr):
    """Run the method as a script

    Add a '--version' argument
    Call add_args(parser) to add any more

    Parse sys.argv
    call method(args)
    Catch any exceptions
        exit on SystemExit or KeyboardError
        Others:
            If version is less then 1, reraise them
            Else print them to the error stream"""
    if version:
        _versions.append(version)
    try:
        args = parse_args(add_args, docstring and docstring or '%s()' % method.__name__)
        return _exit_ok if method(args) else _exit_fail
    except KeyboardInterrupt as e:
        ctrl_c = 3
        return ctrl_c
    except SystemExit as e:
        return e.code
    except DebugExit:
        return _exit_fail
    except Exception as e:
        if int(latest_version().split('.')[0]) < 1:
            raise
        if error_stream:
            print(e, file=error_stream)
        return _exit_fail
    return _exit_ok

def existing_path(string):
    """"Convert" a string to a string that is a path to an existing file."""
    if not os.path.exists(string):
        msg = 'path {0!r} does not exist'.format(string)
        raise argparse.ArgumentTypeError(msg)
    return string

def absolute_path(string):
    """"Convert" a string to a string that is an absolute existing path."""
    if not os.path.isabs(string):
        msg = '{0!r} is not an absolute path'.format(string)
        raise argparse.ArgumentTypeError(msg)
    if not os.path.exists(os.path.dirname(string)):
        msg = 'path {0!r} does not exist'.format(string)
        raise argparse.ArgumentTypeError(msg)
    return string

def wsgi_handler(func):
    """Set a instance method to be call as a wsgi application, adding common
    behavior and using webob.Request for practical use.


    @wsgi_handler
    def handle_verify_token(self, request):
        pass

    :param func:
    :return:"""
    @wraps(func)
    def inner(*args):
        self, environ, start_response, *args = args
        request = Request(environ)
        try:
            response = func(self, request)
        except Exception as err:
            raise
        else:
            return response(environ, start_response)
    return inner

def matchall(r, s, flags=0):
    """Returns the list of contiguous string matches of r in s,
    or None if r does not successively match the entire s."""
    try:
        return [m.group(0) for m in matchiter(r, s, flags)]
    except ValueError:
        return None

