def angle_v2_rad(vec_a, vec_b):
    """Returns angle between vec_a and vec_b in range [0, PI].  This does not
    distinguish if a is left of or right of b."""
    return math.acos(vec_a.dot(vec_b) / (vec_a.length() * vec_b.length()))

def rot_rads_v2(vec_a, rads):
    """Rotate vector by angle in radians."""
    x = vec_a.x * math.cos(rads) - vec_a.y * math.sin(rads)
    y = vec_a.x * math.sin(rads) + vec_a.y * math.cos(rads)
    return Vec2(x, y)

def scale_v2(vec, amount):
    """Return a new Vec2 with x and y from vec and multiplied by amount."""
    return Vec2(vec.x * amount, vec.y * amount)

def sub_v2(v, w):
    """Subtract: v - w.  Assume the first arg v is a Vec2.
    The second arg w can be a vec2 or a number."""
    if type(w) is float or type(w) is int:
        return Vec2(v.x - w, v.y - w)
    else:
        return Vec2(v.x - w.x, v.y - w.y)

def data2schemacls(_data, **kwargs):
    """Convert a data to a schema cls.

    :param data: object or dictionary from where get a schema cls.
    :return: schema class.
    :rtype: type"""
    content = {}
    for key in list(kwargs):
        kwargs[key] = data2schema(kwargs[key])
    if isinstance(_data, dict):
        datacontent = iteritems(_data)
    else:
        datacontent = getmembers(_data)
    for name, value in datacontent:
        if name[0] == '_':
            continue
        if isinstance(value, dict):
            schema = data2schemacls(value)()
        else:
            schema = data2schema(value)
        content[name] = schema
    content.update(kwargs)
    result = type('GeneratedSchema', (Schema,), content)
    return result

def dump(schema):
    """Get a serialized value of input schema.

    :param Schema schema: schema to serialize.
    :rtype: dict"""
    result = {}
    for name, _ in iteritems(schema.getschemas()):
        if hasattr(schema, name):
            val = getattr(schema, name)
            if isinstance(val, DynamicValue):
                val = val()
            if isinstance(val, Schema):
                val = dump(val)
            result[name] = val
    return result

def build(_resource, _cache=True, **kwargs):
    """Build a schema from input _resource.

    :param _resource: object from where get the right schema.
    :param bool _cache: use cache system.
    :rtype: Schema."""
    return _SCHEMAFACTORY.build(_resource=_resource, _cache=True, **kwargs)

def getresource(self, schemacls, name):
    """Get a resource from a builder name.

    :param type schemacls: waited schema class.
    :param str name: builder name to use.
    :return: resource returned by the right builder.getresource(schema)."""
    return _SCHEMAFACTORY.getresource(schemacls=schemacls, name=name)

def s(command, verbose=False, fail_fast=True, interactive=False):
    """Run a shell command."""
    completed_process = None
    output = None
    if interactive:
        completed_process = subprocess.run(command, shell=True, stdin=sys.stdin, stdout=sys.stdout, stderr=sys.stderr)
        output = {'exit_code': completed_process.returncode}
    else:
        completed_process = subprocess.run(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        output = {'exit_code': completed_process.returncode, 'out': completed_process.stdout.decode('utf-8'), 'err': completed_process.stderr.decode('utf-8')}
    result = None
    if completed_process.returncode == 0:
        result = cmn.OkResult(output)
    else:
        result = cmn.ErrorResult(output)
    fail = fail_fast and (not result.ok)
    if verbose or fail:
        cmn.logger.log("Executed shell command '{command}'\nexit code was: {exit_code}\n".format(command=command, **result.value))
    if (verbose or fail) and (not interactive):
        cmn.logger.log('stdout was:\n{out}\nstderr was:\n{err}'.format(**result.value))
    if fail:
        cmn.fail("Failed executing shell command '{command}'".format(command=command))
    return result

def _restart():
    """Schedule the restart; returning True if cancelled, False otherwise."""
    if _restart_cb:
        if _restart_cb() is not None:
            return True
    def down_watchdog():
        _observer.stop()
        _observer.join()
        if _close_fds:
            _util.close_fds()
        if _restart_func:
            _restart_func()
            _deactivate()
        else:
            _util.do_over()
    _util.defer(down_watchdog)
    return False

def api_auth(func):
    """If the user is not logged in, this decorator looks for basic HTTP auth
    data in the request header."""
    @wraps(func)
    def _decorator(request, *args, **kwargs):
        authentication = APIAuthentication(request)
        if authentication.authenticate():
            return func(request, *args, **kwargs)
        raise Http404
    return _decorator

