def recur(obj, type_func_tuple_list=()):
    """recuring dealing an object"""
    for obj_type, func in type_func_tuple_list:
        if type(obj) == type(obj_type):
            return func(obj)
    if isinstance(obj, list) or isinstance(obj, tuple):
        n_obj = []
        for i in obj:
            n_obj.append(recur(i))
        return n_obj if isinstance(obj, list) else tuple(obj)
    elif isinstance(obj, dict):
        n_obj = {}
        for k, v in obj.items():
            n_obj[k] = recur(v)
        return n_obj
    return obj

def browser_cache(seconds):
    """Decorator for browser cache. Only for webpy
    @browser_cache( seconds ) before GET/POST function."""
    import web
    def wrap(f):
        def wrapped_f(*args):
            last_time_str = web.ctx.env.get('HTTP_IF_MODIFIED_SINCE', '')
            last_time = web.net.parsehttpdate(last_time_str)
            now = datetime.datetime.now()
            if last_time and last_time + datetime.timedelta(seconds=seconds) > now:
                web.notmodified()
            else:
                web.lastmodified(now)
                web.header('Cache-Control', 'max-age=' + str(seconds))
            yield f(*args)
        return wrapped_f
    return wrap

def join(items, separator=None):
    """Join the items into a string using the separator

    Converts items to strings if needed

    >>> join([1, 2, 3])
    '1,2,3'"""
    if not items:
        return ''
    if separator is None:
        separator = _default_separator()
    return separator.join([str(item) for item in items])

def split_and_strip(string, separator_regexp=None, maxsplit=0):
    """Split a string into items and trim any excess spaces from the items

    >>> split_and_strip('fred, was, here  ')
    ['fred', 'was', 'here']"""
    if not string:
        return ['']
    if separator_regexp is None:
        separator_regexp = _default_separator()
    if not separator_regexp:
        return string.split()
    return [item.strip() for item in re.split(separator_regexp, string, maxsplit)]

def rejoin(string, separator_regexp=None, spaced=False):
    """Split a string and then rejoin it

    Spaces are interspersed between items only if spaced is True

    >>> rejoin('fred, was, here  ')
    'fred,was,here'"""
    strings = split_and_strip(string)
    if separator_regexp is None:
        separator_regexp = _default_separator()
    joiner = spaced and '%s ' % separator_regexp or separator_regexp
    return joiner.join(strings)

def to_even_columns(data, headers=None):
    """Nicely format the 2-dimensional list into evenly spaced columns"""
    result = ''
    col_width = max((len(word) for row in data for word in row)) + 2
    if headers:
        header_width = max((len(word) for row in headers for word in row)) + 2
        if header_width > col_width:
            col_width = header_width
        result += ''.join((word.ljust(col_width) for word in headers)) + '\n'
        result += '-' * col_width * len(headers) + '\n'
    for row in data:
        result += ''.join((word.ljust(col_width) for word in row)) + '\n'
    return result

def to_smart_columns(data, headers=None, padding=2):
    """Nicely format the 2-dimensional list into columns"""
    result = ''
    col_widths = []
    for row in data:
        col_counter = 0
        for word in row:
            try:
                col_widths[col_counter] = max(len(word), col_widths[col_counter])
            except IndexError:
                col_widths.append(len(word))
            col_counter += 1
    if headers:
        col_counter = 0
        for word in headers:
            try:
                col_widths[col_counter] = max(len(word), col_widths[col_counter])
            except IndexError:
                col_widths.append(len(word))
            col_counter += 1
    col_widths = [width + padding for width in col_widths]
    total_width = sum(col_widths)
    if headers:
        col_counter = 0
        for word in headers:
            result += ''.join(word.ljust(col_widths[col_counter]))
            col_counter += 1
        result += '\n'
        result += '-' * total_width + '\n'
    for row in data:
        col_counter = 0
        for word in row:
            result += ''.join(word.ljust(col_widths[col_counter]))
            col_counter += 1
        result += '\n'
    return result

def merge_x_y(collection_x, collection_y, filter_none=False):
    """Merge two lists, creating a dictionary with key `label` and a set x and y"""
    data = {}
    for item in collection_x:
        label = datetimeutil.tuple_to_string(item[0:-1])
        if filter_none and label == 'None-None':
            continue
        data[label] = {'label': label, 'x': item[-1], 'y': 0}
    for item in collection_y:
        label = datetimeutil.tuple_to_string(item[0:-1])
        if filter_none and label == 'None-None':
            continue
        try:
            data[label]['y'] = item[-1]
        except KeyError:
            data[label] = {'label': label, 'x': 0, 'y': item[-1]}
    return data

def _get_matching_dist_in_location(dist, location):
    """Check if `locations` contain only the one intended dist.
    Return the dist with metadata in the new location."""
    import pkg_resources
    env = pkg_resources.Environment([location])
    dists = [d for project_name in env for d in env[project_name]]
    dist_infos = [(d.project_name, d.version) for d in dists]
    if dist_infos == [(dist.project_name, dist.version)]:
        return dists.pop()
    if dist_infos == [(dist.project_name.lower(), dist.version)]:
        return dists.pop()

def find_commands(management_dir):
    """Given a path to a management directory, returns a list of all the command
    names that are available.

    Returns an empty list if no commands are defined."""
    command_dir = os.path.join(management_dir, 'commands')
    try:
        return [f[:-3] for f in os.listdir(command_dir) if not f.startswith('_') and f.endswith('.py')]
    except OSError:
        return []

def call_command(name, *args, **options):
    """Calls the given command, with the given options and args/kwargs.

    This is the primary API you should use for calling specific commands.

    Some examples:
        call_command('syncdb')
        call_command('shell', plain=True)
        call_command('sqlall', 'myapp')"""
    try:
        app_name = get_commands()[name]
    except KeyError:
        raise CommandError('Unknown command: %r' % name)
    if isinstance(app_name, BaseCommand):
        command = app_name
    else:
        command = load_command_class(app_name, name)
    parser = command.create_parser('', name)
    if command.use_argparse:
        defaults = parser.parse_args(args=args)
        defaults = dict(defaults._get_kwargs(), **options)
    else:
        defaults, _ = parser.parse_args(args=[])
        defaults = dict(defaults.__dict__, **options)
    return command.execute(*args, **defaults)

def genkeyhex():
    """Generate new random Bitcoin private key, using os.urandom and
    double-sha256.  Hex format."""
    while True:
        key = hash256(hexlify(os.urandom(40) + str(datetime.datetime.now()).encode('utf-8')))
        if int(key, 16) > 1 and int(key, 16) < N:
            break
    return key

def genkey(outcompressed=True, prefix='80'):
    """Generate new random Bitcoin private key, using os.urandom and
    double-sha256."""
    key = prefix + genkeyhex()
    if outcompressed:
        key = key + '01'
    return b58e(key)

def inttoLEB128(intinput):
    """Convert int/long to unsigned LEB128 format hex"""
    binstr = str(bin(intinput)).lstrip('0b').replace('b', '').replace('L', '').replace("'", '').replace('"', '')
    if len(binstr) % 7:
        binstr = binstr.zfill(len(binstr) + 7 - len(binstr) % 7)
    bytelist = ''
    for i in range(len(binstr) // 7):
        if i < len(binstr) // 7 - 1:
            pad = '1'
        else:
            pad = '0'
        currbyte = binstr[len(binstr) - (7 * i + 7):len(binstr) - 7 * i]
        currbyte = pad + currbyte
        currbyte = dechex(int(currbyte, 2))
        bytelist = bytelist + currbyte
    return bytelist

def LEB128toint(LEBinput):
    """Convert unsigned LEB128 hex to integer"""
    reversedbytes = hexreverse(LEBinput)
    binstr = ''
    for i in range(len(LEBinput) // 2):
        if i == 0:
            assert int(reversedbytes[2 * i:2 * i + 2], 16) < 128
        else:
            assert int(reversedbytes[2 * i:2 * i + 2], 16) >= 128
        tempbin = str(bin(int(reversedbytes[2 * i:2 * i + 2], 16))).lstrip('0b').replace('b', '').replace('L', '').replace("'", '').replace('"', '').zfill(8)
        binstr += tempbin[1:]
    return int(binstr, 2)

def chunks(l, n):
    """Yield successive n-sized chunks from l."""
    if n:
        for i in xrange(0, len(l), n):
            yield l[i:i + n]

def required(wrapping_functions, patterns_rslt):
    """USAGE:

    from django.contrib.auth.decorators import login_required
    from django.contrib.admin.views.decorators import staff_member_required

    mypage_patterns = required(
        login_required,
        [
            ... url patterns ...
        ]
    )

    staff_patterns = required(
        staff_member_required,
        [
            ... url patterns ...
        ]
    )

    urlpatterns += [
        url(r'^staff/', include(staff_patterns, namespace='staff')),
        url(r'^mypage/', include(mypage_patterns, namespace='mypage')),
    ]"""
    if not hasattr(wrapping_functions, '__iter__'):
        wrapping_functions = (wrapping_functions,)
    return [_wrap_instance__resolve(wrapping_functions, instance) for instance in patterns_rslt]

