def hold(*keys, hold_time=0, hold_while=None):
    """Simulates the holding of all the keys passed to the function
    These keys are held down for a default period of 0 seconds before release

    :param keys: list of keys to be held
    :param hold_time: length of time to hold keys
    :param hold_while: hold keys while hold_while returns True
    :return: None"""
    for key in keys:
        win32api.keybd_event(codes[key], 0, 0, 0)
    if callable(hold_while):
        while hold_while():
            pass
    else:
        time.sleep(hold_time)
    release(*keys)

def release(*keys):
    """Simulates the release of all the keys passed to this function

    :param keys: list of keys to be released
    :return: None"""
    for key in keys:
        win32api.keybd_event(codes[key], 0, win32con.KEYEVENTF_KEYUP, 0)

def write(s=''):
    """Automates the process of typing by converting a string into a set of press() and hold() calls

    :param s: string to be written
    :return: None"""
    for char in s:
        if char.isupper():
            hold('shift', char.lower())
        elif char == ' ':
            press('spacebar')
        elif char == '\n':
            press('enter')
        elif char in (')', '!', '@', '#', '$', '%', '^', '&', '*', '('):
            hold('shift', str((')', '!', '@', '#', '$', '%', '^', '&', '*', '(').index(char)))
        elif char in ('{', '}', '<', '>', '?', ':', '"', '_', '+', '~'):
            hold('shift', ('[', ']', ',', '.', '/', ';', "'", '-', '=', '`')[('{', '}', '<', '>', '?', ':', '"', '_', '+', '~').index(char)])
        else:
            press(char)

def handle_api_error(resp):
    """Stolen straight from the Stripe Python source."""
    content = (yield resp.json())
    headers = HeaderWrapper(resp.headers)
    try:
        err = content['error']
    except (KeyError, TypeError):
        raise error.APIError('Invalid response object from API: %r (HTTP response code was %d)' % (content, resp.code), resp, resp.code, content, headers)
    if resp.code in [400, 404]:
        raise error.InvalidRequestError(err.get('message'), err.get('param'), resp, resp.code, content, headers)
    elif resp.code == 401:
        raise error.AuthenticationError(err.get('message'), resp, resp.code, content, headers)
    elif resp.code == 402:
        raise error.CardError(err.get('message'), err.get('param'), err.get('code'), content, resp.code, resp, headers)
    else:
        raise error.APIError(err.get('message'), content, resp.code, resp, headers)

