def is_vimball(fd):
    """Test for vimball archive format compliance.

    Simple check to see if the first line of the file starts with standard
    vimball archive header."""
    fd.seek(0)
    try:
        header = fd.readline()
    except UnicodeDecodeError:
        return False
    if re.match('^" Vimball Archiver', header) is not None:
        return True
    return False

def ini_dump_hook(cfg, text: bool=False):
    """Dumps all the data into a INI file.

    This will automatically kill anything with a '_' in the keyname, replacing it with a dot. You have been warned."""
    data = cfg.config.dump()
    ndict = {}
    for key, item in data.items():
        key = key.replace('_', '.')
        ndict[key] = item
    cfg.tmpini = configparser.ConfigParser()
    cfg.tmpini.read_dict(data)
    if not text:
        cfg.tmpini.write(cfg.fd)
    else:
        return
    cfg.reload()

