def Any(*validators):
    """Combines all the given validator callables into one, running the given
    value through them in sequence until a valid result is given."""
    @wraps(Any)
    def built(value):
        error = None
        for validator in validators:
            try:
                return validator(value)
            except Error as e:
                error = e
        raise error
    return built

def Maybe(validator):
    """Wraps the given validator callable, only using it for the given value if it
    is not ``None``."""
    @wraps(Maybe)
    def built(value):
        if value != None:
            return validator(value)
    return built

def Msg(validator, message):
    """Wraps the given validator callable, replacing any error messages raised."""
    @wraps(Msg)
    def built(value):
        try:
            return validator(value)
        except Error as e:
            e.message = message
            raise e
    return built

def Eq(value, message='Not equal to {!s}'):
    """Creates a validator that compares the equality of the given value to
    ``value``.

    A custom message can be specified with ``message``. It will be formatted
    with ``value``."""
    @wraps(Eq)
    def built(_value):
        if _value != value:
            raise Error(message.format(value))
        return _value
    return built

def Type(expected, message='Not of type {}'):
    """Creates a validator that compares the type of the given value to
    ``expected``. This is a direct type() equality check. Also see
    ``Instance``, which is an isinstance() check.

    A custom message can be specified with ``message``."""
    @wraps(Type)
    def built(value):
        if type(value) != expected:
            raise Error(message.format(expected.__name__))
        return value
    return built

def Instance(expected, message='Not an instance of {}'):
    """Creates a validator that checks if the given value is an instance of
    ``expected``.

    A custom message can be specified with ``message``."""
    @wraps(Instance)
    def built(value):
        if not isinstance(value, expected):
            raise Error(message.format(expected.__name__))
        return value
    return built

def Coerce(type, message='Not a valid {} value'):
    """Creates a validator that attempts to coerce the given value to the
    specified ``type``. Will raise an error if the coercion fails.

    A custom message can be specified with ``message``."""
    @wraps(Coerce)
    def built(value):
        try:
            return type(value)
        except (TypeError, ValueError) as e:
            raise Error(message.format(type.__name__))
    return built

def List(validator):
    """Creates a validator that runs the given validator on every item in a list
    or other collection. The validator can mutate the values.

    Any raised errors will be collected into a single ``Invalid`` error. Their
    paths will be replaced with the index of the item. Will raise an error if
    the input value is not iterable."""
    @wraps(List)
    def built(value):
        if not hasattr(value, '__iter__'):
            raise Error('Must be a list')
        invalid = Invalid()
        for i, item in enumerate(value):
            try:
                value[i] = validator(item)
            except Invalid as e:
                for error in e:
                    error.path.insert(0, i)
                    invalid.append(error)
            except Error as e:
                e.path.insert(0, i)
                invalid.append(e)
        if len(invalid):
            raise invalid
        return value
    return built

def Boolean():
    """Creates a validator that attempts to convert the given value to a boolean
    or raises an error. The following rules are used:

    ``None`` is converted to ``False``.

    ``int`` values are ``True`` except for ``0``.

    ``str`` values converted in lower- and uppercase:

    * ``y, yes, t, true``
    * ``n, no, f, false``"""
    @wraps(Boolean)
    def built(value):
        if isinstance(value, bool):
            return value
        if value == None:
            return False
        if isinstance(value, int):
            return not value == 0
        if isinstance(value, str):
            if value.lower() in {'y', 'yes', 't', 'true'}:
                return True
            elif value.lower() in {'n', 'no', 'f', 'false'}:
                return False
        raise Error('Not a boolean value.')
    return built

def Range(min=None, max=None, min_message='Must be at least {min}', max_message='Must be at most {max}'):
    """Creates a validator that checks if the given numeric value is in the
    specified range, inclusive.

    Accepts values specified by ``numbers.Number`` only, excluding booleans.

    The error messages raised can be customized with ``min_message`` and
    ``max_message``. The ``min`` and ``max`` arguments are formatted."""
    @wraps(Range)
    def built(value):
        if not isinstance(value, numbers.Number) or isinstance(value, bool):
            raise Error('Not a number')
        if min is not None and min > value:
            raise Error(min_message.format(min=min, max=max))
        if max is not None and value > max:
            raise Error(max_message.format(min=min, max=max))
        return value
    return built

def Length(min=None, max=None, min_message='Must have a length of at least {min}', max_message='Must have a length of at most {max}'):
    """Creates a validator that checks if the given value's length is in the
    specified range, inclusive. (Returns the original value.)

    See :func:`.Range`."""
    validator = Range(min, max, min_message, max_message)
    @wraps(Length)
    def built(value):
        if not hasattr(value, '__len__'):
            raise Error('Does not have a length')
        validator(len(value))
        return value
    return built

def NotEmpty():
    """Creates a validator that validates the given string is not empty. Will
    raise an error for non-string types."""
    @wraps(NotEmpty)
    def built(value):
        if not isinstance(value, six.string_types) or not value:
            raise Error('Must not be empty')
        return value
    return built

def Uuid(to_uuid=True):
    """Creates a UUID validator. Will raise an error for non-string types and
    non-UUID values.

    The given value will be converted to an instance of ``uuid.UUID`` unless
    ``to_uuid`` is ``False``."""
    @wraps(Uuid)
    def built(value):
        invalid = Error('Not a valid UUID')
        if isinstance(value, uuid.UUID):
            return value
        elif not isinstance(value, six.string_types):
            raise invalid
        try:
            as_uuid = uuid.UUID(value)
        except (ValueError, AttributeError) as e:
            raise invalid
        if to_uuid:
            return as_uuid
        return value
    return built

def optimally_align_text(x, y, texts, expand, renderer=None, ax=None, direction='xy'):
    """For all text objects find alignment that causes the least overlap with
    points and other texts and apply it"""
    if ax is None:
        ax = plt.gca()
    if renderer is None:
        r = ax.get_figure().canvas.get_renderer()
    else:
        r = renderer
    bboxes = get_bboxes(texts, r, expand)
    if 'x' not in direction:
        ha = ['']
    else:
        ha = ['left', 'right', 'center']
    if 'y' not in direction:
        va = ['']
    else:
        va = ['bottom', 'top', 'center']
    alignment = list(product(ha, va))
    for i, text in enumerate(texts):
        counts = []
        for h, v in alignment:
            if h:
                text.set_ha(h)
            if v:
                text.set_va(v)
            bbox = text.get_window_extent(r).expanded(*expand).transformed(ax.transData.inverted())
            c = get_points_inside_bbox(x, y, bbox)
            counts.append(len(c) + bbox.count_overlaps(bboxes) - 1)
        a = np.argmin(counts)
        if 'x' in direction:
            text.set_ha(alignment[a][0])
        if 'y' in direction:
            text.set_va(alignment[a][1])
        bboxes[i] = text.get_window_extent(r).expanded(*expand).transformed(ax.transData.inverted())
    return texts

def write_quota(outbytes: int, outfn: Path) -> Union[None, int]:
    """aborts writing if not enough space on drive to write"""
    if not outfn:
        return None
    anch = Path(outfn).resolve().anchor
    freeout = shutil.disk_usage(anch).free
    if freeout < 10 * outbytes:
        raise IOError(f'out of disk space on {anch}.{{freeout/1e9}} GB free, wanting to write {{outbytes/1e9}} GB.')
    return freeout

def req2frame(req, N: int=0):
    """output has to be numpy.arange for > comparison"""
    if req is None:
        frame = np.arange(N, dtype=np.int64)
    elif isinstance(req, int):
        frame = np.arange(0, N, req, dtype=np.int64)
    elif len(req) == 1:
        frame = np.arange(0, N, req[0], dtype=np.int64)
    elif len(req) == 2:
        frame = np.arange(req[0], req[1], dtype=np.int64)
    elif len(req) == 3:
        frame = np.arange(req[0], req[1], req[2], dtype=np.int64) - 1
    else:
        frame = np.arange(N, dtype=np.int64)
    return frame

def dir2fn(ofn, ifn, suffix) -> Union[None, Path]:
    """ofn = filename or output directory, to create filename based on ifn
    ifn = input filename (don't overwrite!)
    suffix = desired file extension e.g. .h5"""
    if not ofn:
        return None
    ofn = Path(ofn).expanduser()
    ifn = Path(ifn).expanduser()
    assert ifn.is_file()
    if ofn.suffix == suffix:
        pass
    else:
        assert ofn.is_dir(), f'create directory {ofn}'
        ofn = ofn / ifn.with_suffix(suffix).name
    try:
        assert not ofn.samefile(ifn), f'do not overwrite input file! {ifn}'
    except FileNotFoundError:
        pass
    return ofn

def imgwriteincr(fn: Path, imgs, imgslice):
    """writes HDF5 huge image files in increments"""
    if isinstance(imgslice, int):
        if imgslice and (not imgslice % 2000):
            print(f'appending images {imgslice} to {fn}')
    if isinstance(fn, Path):
        assert fn.suffix == '.h5', 'Expecting to write .h5 file'
        with h5py.File(fn, 'r+') as f:
            f['/rawimg'][imgslice, :, :] = imgs
    elif isinstance(fn, h5py.File):
        f['/rawimg'][imgslice, :, :] = imgs
    else:
        raise TypeError(f'{fn} must be Path or h5py.File instead of {type(fn)}')

def load_args(args):
    """Load a config file. Merges CLI args and validates."""
    config = kaptan.Kaptan(handler='yaml')
    conf_parent = os.path.expanduser('~')
    conf_app = '.clancy'
    conf_filename = 'config.yaml'
    conf_dir = os.path.join(conf_parent, conf_app)
    for loc in [os.curdir, conf_dir]:
        configpath = os.path.join(loc, conf_filename)
        try:
            if os.path.isfile(configpath):
                config.import_config(configpath)
                break
        except (ValueError, ParserError, ScannerError):
            warn('Ignoring invalid valid yaml file {}'.format(configpath))
    config = config.configuration_data if config.configuration_data is not None else {}
    for key, val in config.items():
        config['--' + key] = val
        del config[key]
    return validate(merge(args, config))

def debug(method):
    """Decorator to debug the given method"""
    def new_method(*args, **kwargs):
        import pdb
        try:
            import pudb
        except ImportError:
            pudb = pdb
        try:
            pudb.runcall(method, *args, **kwargs)
        except pdb.bdb.BdbQuit:
            sys.exit('Normal quit from debugger')
    new_method.__doc__ = method.__doc__
    new_method.__name__ = 'debug(%s)' % method.__name__
    return new_method

