def file_hash(content):
    """Generate hash for file or string and avoid strings starting with "ad"
    to workaround ad blocks being over aggressiv.

    The current implementation is based on sha256.

    :param str|FileIO content: The content to hash, either as string or as file-like object"""
    h = hashlib.sha256()
    if isinstance(content, bytes_type):
        h.update(content)
    else:
        data = True
        while data:
            data = content.read(1024 * 1024)
            h.update(data)
    h_digest = h.digest()
    result = base64.b64encode(h_digest, altchars=b'-_')
    result = result.decode('ascii')
    result = result.rstrip('=')
    if result[:2].lower() == 'ad':
        if result[1] == 'd':
            result = result[0] + '~' + result[2:]
        else:
            result = result[0] + '.' + result[2:]
    return result

def humanized_join(value, add_links=False):
    '''Given a list of strings, format them with commas and spaces,
    but with 'and' at the end.

    >>> humanized_join(['apples', 'oranges', 'pears'])
    "apples, oranges, and pears"

    In a template, if mylist = ['apples', 'oranges', 'pears']
    then {{ mylist|humanized_join }}
    will output "apples, oranges, and pears"

    Passing the add_links option will wrap each item in a link.
    Note this requires that anything being passed has get_absolute_url() defined.

    then {{ mylist|humanized_join:'add_links' }}
    will output "<a href="...">apples</a>, <a href="...">oranges</a>, and <a href="...">pears</a>"'''
    if add_links:
        try:
            value = ['<a href="%s">%s</a>' % (item.get_absolute_url(), item) for item in value]
        except AttributeError:
            print('You did not pass objects with get_absolute_url() method.')
            return
    else:
        value = [six.u(item) for item in value]
    if len(value) == 1:
        return mark_safe(value[0])
    if len(value) == 2:
        return mark_safe('%s and %s' % (value[0], value[1]))
    all_but_last = ', '.join(value[:-1])
    return mark_safe('%s, and %s' % (all_but_last, value[-1]))

def specialRound(number, rounding):
    """A method used to round a number in the way that UsefulUtils rounds."""
    temp = 0
    if rounding == 0:
        temp = number
    else:
        temp = round(number, rounding)
    if temp % 1 == 0:
        return int(temp)
    else:
        return float(temp)

def Where_filter_gen(*data):
    """Generate an sqlite "LIKE" filter generator based on the given data.
    This functions arguments should be a N length series of field and data
    tuples."""
    where = []
    def Fwhere(field, pattern):
        """Add where filter for the given field with the given pattern."""
        where.append("WHERE {0} LIKE '{1}'".format(field, pattern))
    def Fstring(field, string):
        """Add a where filter based on a string."""
        Fwhere(field, '%{0}%'.format(string if not isinstance(string, str) else str(string)))
    def Fdict(field, data):
        """Add where filters to search for dict keys and values."""
        for key, value in data.items():
            if value == '*':
                Fstring(field, key)
            else:
                Fstring(field, '{0}:%{1}'.format(key, value if not isinstance(value, str) else str(value)))
    def Flist(field, data):
        """Add where filters to search for elements of a list."""
        for elem in data:
            Fstring(field, elem if not isinstance(elem, str) else str(elem))
    for field, data in data:
        if isinstance(data, str):
            Fstring(field, data)
        elif isinstance(data, dict):
            Fdict(field, data)
        elif isinstance(data, list):
            Flist(field, data)
    return ' AND '.join(where)

