def trycatch(*args, **kwargs):
    """Wraps a function in a try/catch block. Can be used as a function
    decorator or as a function that accepts another function.

    **Params**:
      - func (func) - Function to call. Only available when used as a function.
      - oncatch (str) [kwargs] - Function to call if an exception is caught.
      - rethrow (str) [kwargs] - If true, exception will be re-thrown.

    **Examples**:
    ::

        trycatch(myfunc)(myarg1, myarg2, kwarg=mykwarg)
        trycatch(myfunc, oncatch=mycatchfunc)(myarg1, myarg2, kwarg=mykwarg)
        trycatch(myfunc, rethrow=True)(myarg1, myarg2, kwarg=mykwarg)"""
    rethrow = kwargs.get('rethrow', False)
    oncatch = kwargs.get('oncatch', None)
    def decor(func):
        def wrapper(*fargs, **fkrgs):
            try:
                return func(*fargs, **fkrgs)
            except:
                if oncatch != None:
                    oncatch()
                if rethrow:
                    raise
        return wrapper
    if len(args) > 0 and callable(args[0]):
        func = args[0]
        return decor(func)
    return decor

def callstop(*args, **kwargs):
    """Limits the number of times a function can be called. Can be used as a
    function decorator or as a function that accepts another function. If used
    as a function, it returns a new function that will be call limited.

    **Params**:
      - func (func) - Function to call. Only available when used as a function.

    **Examples**:
    ::

        call = callstop(myfunc, limit=3)
        call(myarg1, myarg2)"""
    limit = kwargs.get('limit', 1)
    def decor(func):
        def wrapper(*args, **kwargs):
            if wrapper.calls < limit:
                wrapper.calls += 1
                return func(*args, **kwargs)
        wrapper.calls = 0
        return wrapper
    if len(args) > 0 and callable(args[0]):
        func = args[0]
        return decor(func)
    return decor

def wait_for_instance(instance):
    """wait for instance status to be 'running' in which case return True, False otherwise"""
    status = None
    print('getting status for instance {} ...'.format(instance.id))
    while status is None:
        try:
            status = instance.update()
            if status is None:
                time.sleep(2)
        except EC2ResponseError:
            time.sleep(2)
    print('waiting for instance {} ...'.format(instance.id))
    while status == 'pending':
        time.sleep(2)
        status = instance.update()
    if status != 'running':
        print('Invalid status when starting instance {}: {}'.format(instance.id, status))
        return False
    print('New instance {} started: {}'.format(instance.id, instance.ip_address))
    return True

def move_files_to_folders(directory):
    """Loops through a parent directory and nests files within folders that already exists and have matching prefixs
    :param directory: Starting directory"""
    files, folders, files_to_move = ([], [], [])
    for path in os.listdir(directory):
        if os.path.isdir(path):
            folders.append(path)
        elif os.path.isfile(path):
            files.append(path)
    for path in folders:
        child_files = [f for f in files if f.startswith(path)]
        files_to_move.append((path, child_files))
    for each in files_to_move:
        folder, files = each
        for f in files:
            shutil.move(f, folder)

def env(var_name, default=False):
    """Get the environment variable. If not found use a default or False, but print to stderr a warning about the missing env variable."""
    try:
        value = os.environ[var_name]
        if str(value).strip().lower() in ['false', 'f', 'no', 'off0', 'none', 'null', '']:
            return None
        return value
    except:
        from traceback import format_exc
        msg = 'Unable to find the %s environment variable.\nUsing the value %s (the default) instead.\n' % (var_name, default)
        sys.stderr.write(format_exc())
        sys.stderr.write(msg)
        return default

def digest(dirname, glob=None):
    """Returns the md5 digest of all interesting files (or glob) in `dirname`.
    """
    md5 = hashlib.md5()
    if glob is None:
        fnames = [fname for _, fname in list_files(Path(dirname))]
        for fname in sorted(fnames):
            fname = os.path.join(dirname, fname)
            md5.update(open(fname, 'rb').read())
    else:
        fnames = Path(dirname).glob(glob)
        for fname in sorted(fnames):
            md5.update(fname.open('rb').read())
    return md5.hexdigest()

def version_keyword(dist, attr, value):
    """Implements the actual version setup() keyword."""
    if value == 'PBR':
        from pbr.util import setup_cfg_to_setup_kwargs
        path = 'setup.cfg'
        parser = ConfigParser()
        if not os.path.exists(path):
            raise ValueError("file '%s' does not exist" % os.path.abspath(path))
        parser.read(path)
        config = {}
        for section in parser.sections():
            config[section] = dict(parser.items(section))
        attrs = setup_cfg_to_setup_kwargs(config)
        version = str(Version(attrs['name']))
        os.environ['PBR_VERSION'] = version
    else:
        version = str(Version(dist.metadata.get_name()))
    dist.metadata.version = version

