def clize(*args, **kwargs):
    """Decorator has 2 usages:
    @clize
    def decorated(params):
       ...
    optional parameters aliases are autogenerated, conflicts are silently ignored.

    @clize(aliases)
    def decorated(params)
       ...
    where aliases is a dictionary, key=python parameter of decorated function,
    value=tuple of aliases or single alias."""
    kwargs = dict(((k.lower(), v) for k, v in iteritems(kwargs)))
    class mycli(Clizer):
        options_aliases = kwargs
    mycli.check_deco_parameters(*args, **kwargs)
    def runner(function):
        return mycli(function) if DELAY_EXECUTION else mycli(function)()
    if args:
        return runner(args[0])
    else:
        return runner

def close_fds():
    """Close extraneous file descriptors.

    On Linux, close everything but stdin, stdout, and stderr. On Mac, close
    stdin, stdout, and stderr and everything owned by our user id."""
    def close(fd):
        with ignored(OSError):
            os.close(fd)
    if sys.platform == 'linux':
        fd_dir = '/proc/self/fd'
        fds = set(map(int, os.listdir(fd_dir)))
        for x in fds - {0, 1, 2}:
            close(x)
    elif sys.platform == 'darwin':
        uid = os.getuid()
        fd_dir = '/dev/fd'
        fds = set(map(int, os.listdir(fd_dir)))
        for x in fds - {0, 1, 2}:
            path = '/dev/fd/' + str(x)
            if not os.access(path, os.R_OK):
                continue
            stat = os.fstat(x)
            if stat.st_uid != uid:
                continue
            close(x)

