def entrypoint(method, depth=1, cls=None):
    """Run a method as your __main__ via decorator.

    Example::

      @shrew.cli.entrypoint
      def main(cli):
        ...

    Shorthand for::

      def main():

        cli = shrew.cli.CLI()

        ...

      if __name__ == '__main__':
        method()"""
    current_frame = inspect.currentframe(depth).f_locals
    if '__name__' in current_frame and current_frame['__name__'] == '__main__':
        if cls is None:
            cls = CLI
        method(cls())
    return method

def find_first_regex_match(key, regex_candidates):
    """find the first regex that match with the key
    :param key: a key to try to match against multiple regex
    :param match_candidates: a list of regexes to check if they match the key
    :return: the first candidate found"""
    for cand in regex_candidates:
        try:
            pattern = re.compile(cap_match_string(cand))
            if pattern.match(key):
                return cand
        except:
            logging.warn('[ros_interface] Ignoring invalid regex string "{0!s}"!'.format(cand))
    return None

def import_module(path):
    """Import a module given a dotted *path* in the
    form of ``.name(.name)*``, and returns the
    last module (unlike ``__import__`` which just
    returns the first module).

    :param path: The dotted path to the module."""
    mod = __import__(path, locals={}, globals={})
    for item in path.split('.')[1:]:
        try:
            mod = getattr(mod, item)
        except AttributeError:
            raise ImportError('No module named %s' % path)
    return mod

def sqldelete(table, where):
