    """Returns the key of a single element dict."""
    if len(d) > 1 and (not type(d) == dict()):
        raise ValueError('key_of(d) may only except single element dict')
    else:
        return keys_of(d)[0]

def build_app_loggers(log_level, apps, handlers=None):
    """Return a logger dict for app packages with the given log level and no
    propogation since the apps list is parsed/normalized to be the set of top-
    level apps.  The optional handlers argument is provided so that this pattern
    of app loggers can be used independently of the configure_logger method
    below, if desired."""
    if handlers is None:
        handlers = ['default']
    if not isinstance(handlers, list):
        handlers = list(handlers)
    app_loggers = {}
    for app in apps:
        app_loggers[app] = {'level': log_level, 'handlers': handlers, 'propagate': False}
    return app_loggers

def datetime2unix(T):
    """converts datetime to UT1 unix epoch time"""
    T = atleast_1d(T)
    ut1_unix = empty(T.shape, dtype=float)
    for i, t in enumerate(T):
        if isinstance(t, (datetime, datetime64)):
            pass
        elif isinstance(t, str):
            try:
                ut1_unix[i] = float(t)
                continue
            except ValueError:
                t = parse(t)
        elif isinstance(t, (float, int)):
            return T
        else:
            raise TypeError('I only accept datetime or parseable date string')
        ut1_unix[i] = forceutc(t).timestamp()
    return ut1_unix

