def privtopub(priv, outcompressed=True):
    """Input must be 64-char hex string"""
    x, y = ecmultiply(Gx, Gy, int(priv, 16))
    x = dechex(x, 32)
    y = dechex(y, 32)
    o = '04' + x + y
    if outcompressed:
