        return o

def subtractprivkeys(p1, p2):
    """Input must be 64-char hex string"""
    return dechex((int(p1, 16) + (N - int(p2, 16))) % N, 32)

def addpubs(p1, p2, outcompressed=True):
    """Pubkey inputs can be compressed or uncompressed, as long as
    they're valid keys and hex strings. Use the validatepubkey()
    function to validate them first. The compression of the input
    keys does not do anything or matter in any way. Only the
    outcompressed bool dictates the compression of the output."""
    if len(p1) == 66:
        p1 = uncompress(p1)
    if len(p2) == 66:
        p2 = uncompress(p2)
    x, y = ecadd(int(p1[2:66], 16), int(p1[66:], 16), int(p2[2:66], 16), int(p2[66:], 16))
    x = dechex(x, 32)
    y = dechex(y, 32)
    o = '04' + x + y
    if outcompressed:
        return compress(o)
    else:
        return o

def subtractpubs(p1, p2, outcompressed=True):
    """Pubkey inputs can be compressed or uncompressed, as long as
    they're valid keys and hex strings. Use the validatepubkey()
    function to validate them first. The compression of the input
    keys does not do anything or matter in any way. Only the
    outcompressed bool dictates the compression of the output."""
    if len(p1) == 66:
        p1 = uncompress(p1)
    if len(p2) == 66:
        p2 = uncompress(p2)
    x, y = ecsubtract(int(p1[2:66], 16), int(p1[66:], 16), int(p2[2:66], 16), int(p2[66:], 16))
    x = dechex(x, 32)
    y = dechex(y, 32)
    o = '04' + x + y
    if outcompressed:
        return compress(o)
    else:
        return o

def validatepubkey(pub):
    """Returns input key if it's a valid hex public key, or False
    otherwise.

    Input must be hex string, not bytes or integer/long or anything
    else."""
    try:
        pub = hexstrlify(unhexlify(pub))
    except:
        return False
    if len(pub) == 130:
        if pub[:2] != '04':
            return False
        if uncompress(compress(pub)) != pub:
            return False
    elif len(pub) == 66:
        if pub[:2] != '02' and pub[:2] != '03':
            return False
    else:
        return False
    return pub

def privtohex(key):
    """Used for getting unknown input type into a private key.

    For example, if you ask a user to input a private key, and they
    may input hex, WIF, integer, etc. Run it through this function to
    get a standardized format.

    Function either outputs private key hex string or raises an
    exception. It's really going to try to make any input into
    a private key, so make sure that whatever you import is indeed
    supposed to be a private key. For example, if you put an int in,
    it will turn that into a key. Make sure you want a key when you
    use this function!!!"""
    if isitint(key):
        key = dechex(key, 32)
    else:
        try:
            key, z, zz = wiftohex(key)
            assert len(key) == 64
        except:
            try:
                key = unhexlify(key)
            except:
                try:
                    key1 = hexstrlify(key)
                    assert len(key1) == 64 or len(key1) == 66 or len(key1) == 68
                    if len(key1) == 68:
                        assert key1[-2:] == '01'
                    key = key1
                except:
                    raise Exception('Cannot interpret input key.')
            else:
                key = hexstrlify(key)
    if len(key) == 68:
        assert key[-2:] == '01'
        key = key[:-2]
    if len(key) == 66:
        key = key[2:]
    assert len(key) == 64
    return key

def conjugate_quat(quat):
    """Negate the vector part of the quaternion."""
    return Quat(-quat.x, -quat.y, -quat.z, quat.w)

def lerp_quat(from_quat, to_quat, percent):
    """Return linear interpolation of two quaternions."""
    if dot_quat(from_quat, to_quat) < 0.0:
        to_sign = -1
    else:
        to_sign = 1
    percent_from = 1.0 - percent
    percent_to = percent
    result = Quat(percent_from * from_quat.x + to_sign * percent_to * to_quat.x, percent_from * from_quat.y + to_sign * percent_to * to_quat.y, percent_from * from_quat.z + to_sign * percent_to * to_quat.z, percent_from * from_quat.w + to_sign * percent_to * to_quat.w)
    return result

