def version(modfile):
    """Parse version from module without importing or evaluating the code.
    The module should define a __version__ variable like __version__ = '2.0.1'."""
    import re
    with open(modfile) as fh:
        for line in fh:
            m = re.search("^__version__ = '([^']+)'$", line)
            if m:
                return m.group(1)
    raise Exception('No __version__ string found in {fn}'.format(fn=modfile))

def printer(data, depth=0):
    """Prepare data for printing.

    :param data: a data value that will be processed by method
    :param int depth: recurrency indicator, to maintain proper indent

    :returns: string with formatted config
    :rtype: str"""
    indent = _INDENT * depth
    config_string = '' if not depth else ':\n'
    if isinstance(data, dict):
        for key, val in data.items():
            line = '{0}{1}'.format(indent, key)
            values = printer(val, depth + 1)
            if not values.count('\n'):
                values = ': {0}'.format(values.lstrip())
            line = '{line}{values}'.format(line=line, values=values)
            config_string += '{0}\n'.format(line)
    elif isinstance(data, list):
        for elem in data:
            config_string += '{0} - {1}\n'.format(indent, elem)
    else:
        config_string = '{0}{1} ({2})'.format(indent, data, data.__class__.__name__)
    return config_string.rstrip('\n')

def split_size(size):
    """Split the file size into several chunks."""
    rem = size % CHUNK_SIZE
    if rem == 0:
        cnt = size // CHUNK_SIZE
    else:
        cnt = size // CHUNK_SIZE + 1
    chunks = []
    for i in range(cnt):
        pos = i * CHUNK_SIZE
        if i == cnt - 1:
            disp = size - pos
        else:
            disp = CHUNK_SIZE
        chunks.append((pos, disp))
    return chunks

def main():
    """Script entry point."""
    import getopt
    try:
        opts, args = getopt.getopt(sys.argv[1:], 'hv', ['help', 'version'])
    except getopt.GetoptError as err:
        sys.stderr.write('Error: %s\n' % err)
        exit(2)
    for opt, _ in opts:
        if opt in ['-h', '--help']:
            show_usage()
            exit()
        elif opt in ['-v', '--version']:
            show_version()
            exit()
    if len(args) != 2:
        show_usage()
        exit(1)
    infile, outfile = args
    if infile == outfile:
        sys.stderr.write('Error: outfile must differ from infile\n')
        exit(3)
    reverse_file(infile, outfile)
    sys.stdout.write('Successfully written to %s\n' % outfile)

def match_keys(inp, p=False):
    """Takes a comma-separated string of key ids or fingerprints and returns a list of key ids"""
    _keys = []
    ssh_keys = DO.get_ssh_keys()
    for k in inp.split(','):
        done = False
        if k.isdigit():
            for _ in [s for s in ssh_keys if s['id'] == int(k)]:
                done = True
                _keys.append(_['fingerprint'])
        else:
            for _ in [s for s in ssh_keys if s['fingerprint'] == k]:
                done = True
                _keys.append(_['fingerprint'])
        if p and (not done):
            print("Could not find a match for '{}', skipping".format(k), file=sys.stderr)
    return _keys

def cd_to(path, mkdir=False):
    """make a generator like cd, but use it for function

    Usage::

        >>> @cd_to("/")
        ... def say_where():
        ...     print(os.getcwd())
        ...
        >>> say_where()
        /"""
    def cd_to_decorator(func):
        @functools.wraps(func)
        def _cd_and_exec(*args, **kwargs):
            with cd(path, mkdir):
                return func(*args, **kwargs)
        return _cd_and_exec
    return cd_to_decorator

