        anchor_tags = html.cssselect('a')
        for a in anchor_tags:
            if not 'href' in a.attrib or a.attrib['href'] == '':
                BROKEN_URLS.append(('None', file_name, a.sourceline))
            url = clean_url(a.attrib['href'])
