def before(f, chain=False):
    """Runs f before the decorated function."""
    def decorator(g):
        @wraps(g)
        def h(*args, **kargs):
            if chain:
                return g(f(*args, **kargs))
            else:
                f(*args, **kargs)
                return g(*args, **kargs)
        return h
    return decorator

def after(f, chain=False):
    """Runs f with the result of the decorated function."""
    def decorator(g):
        @wraps(g)
        def h(*args, **kargs):
            if chain:
                return f(g(*args, **kargs))
            else:
                r = g(*args, **kargs)
                f(*args, **kargs)
                return r
        return h
    return decorator

def during(f):
    """Runs f during the decorated function's execution in a separate thread."""
    def decorator(g):
        @wraps(g)
        def h(*args, **kargs):
            tf = Thread(target=f, args=args, kwargs=kargs)
            tf.start()
            r = g(*args, **kargs)
            tf.join()
            return r
        return h
    return decorator

def _check_typecode_list(ofwhat, tcname):
    """Check a list of typecodes for compliance with Struct
    requirements."""
    for o in ofwhat:
        if callable(o):
            continue
        if not isinstance(o, TypeCode):
            raise TypeError(tcname + ' ofwhat outside the TypeCode hierarchy, ' + str(o.__class__))
        if o.pname is None and (not isinstance(o, AnyElement)):
            raise TypeError(tcname + ' element ' + str(o) + ' has no name')

def _get_type_or_substitute(typecode, pyobj, sw, elt):
    """return typecode or substitute type for wildcard or
    derived type.  For serialization only."""
    sub = getattr(pyobj, 'typecode', typecode)
    if sub is typecode or sub is None:
        return typecode
    if isinstance(typecode, AnyElement):
        return sub
    if isinstance(sub, ElementDeclaration):
        if (typecode.nspname, typecode.pname) == (sub.nspname, sub.pname):
            raise TypeError('bad usage, failed to serialize element reference (%s, %s), in: %s' % (typecode.nspname, typecode.pname, sw.Backtrace(elt)))
        if _is_substitute_element(typecode, sub):
            return sub
        raise TypeError('failed to serialize (%s, %s) illegal sub GED (%s,%s): %s' % (typecode.nspname, typecode.pname, sub.nspname, sub.pname, sw.Backtrace(elt)))
    if not isinstance(typecode, AnyType) and (not isinstance(sub, typecode.__class__)):
        raise TypeError('failed to serialize substitute %s for %s,  not derivation: %s' % (sub, typecode, sw.Backtrace(elt)))
    sub = _copy(sub)
    sub.nspname = typecode.nspname
    sub.pname = typecode.pname
    sub.aname = typecode.aname
    sub.minOccurs = sub.maxOccurs = 1
    return sub

def template_render(template, context=None, request=None):
    """Passing Context or RequestContext to Template.render is deprecated in 1.9+,
    see https://github.com/django/django/pull/3883 and
    https://github.com/django/django/blob/1.9rc1/django/template/backends/django.py#L82-L84

    :param template: Template instance
    :param context: dict
    :param request: Request instance
    :return: rendered template as SafeText instance"""
    if django.VERSION < (1, 8) or isinstance(template, Template):
        if request:
            context = RequestContext(request, context)
        else:
            context = Context(context)
        return template.render(context)
    else:
        return template.render(context, request=request)

