    return ret

def elog(exc, func, args=None, kwargs=None, str=str, pretty=True, name=''):
    """For logging exception-raising function invocations during randomized unit tests.
    """
    from .str import safe_str
    args = args if args else ()
    kwargs = kwargs if kwargs else {}
    name = '{}.{}'.format(get_mod(func), name) if name else full_funcname(func)
    if pretty:
        invocation = ', '.join([safe_str(arg) for arg in args])
        if kwargs:
            invocation += ', '
            invocation += ', '.join(['{}={}'.format(key, safe_str(value)) for key, value in sorted(kwargs.items())])
    else:
        invocation = 'args={}, kwargs={}'.format(safe_str(args), safe_str(kwargs))
    msg = '***{}***: "{}" --- {}({})'.format(get_typename(exc), message(exc), name, invocation)
    elogger.error(msg)

def SpacesInsideBrackets(logical_line, tokens):
    """Require spaces inside parentheses, square brackets, and braces for
    non-empty content."""
    for index in range(len(tokens)):
        _, prev_text, _, prev_end, _ = tokens[index - 1] if index - 1 >= 0 else (None, None, None, None, None)
        token_type, text, start, end, _ = tokens[index]
        next_token_type, next_text, next_start, _, _ = tokens[index + 1] if index + 1 < len(tokens) else (None, None, None, None, None)
        if text in LEFT_BRACKETS:
            if next_text == CORRESPONDING_BRACKET[text] and next_start != end:
                code = 'YCM204'
                message = ' no spaces between {} and {} for empty content'.format(text, next_text)
                yield (end, code + message)
            if next_token_type not in [tokenize.NL, tokenize.NEWLINE] and next_text != CORRESPONDING_BRACKET[text] and next_start and (next_start[0] == start[0]) and (next_start[1] - start[1] != 2):
                code = 'YCM201'
                message = ' exactly one space required after {}'.format(text)
                yield (end, code + message)
        if text in RIGHT_BRACKETS:
            if prev_text != CORRESPONDING_BRACKET[text] and prev_end and (prev_end[0] == end[0]) and (end[1] - prev_end[1] != 2):
                code = 'YCM202'
                message = ' exactly one space required before {}'.format(text)
                yield (start, code + message)

def logger(ref=0):
    """Finds a module logger.

    If the argument passed is a module, find the logger for that module using
    the modules' name; if it's a string, finds a logger of that name; if an
    integer, walks the stack to the module at that height.

    The logger is always extended with a ``.configure()`` method allowing
    its log levels for syslog and stderr to be adjusted or automatically
    initialized as per the documentation for `configure()` below."""
    if inspect.ismodule(ref):
        return extend(logging.getLogger(ref.__name__))
    if isinstance(ref, basestring):
        return extend(logging.getLogger(ref))
    return extend(logging.getLogger(stackclimber(ref + 1)))

