def constant_time_compare(val1, val2):
    """**This code was taken from the django 1.4.x codebase along with the test code**
    Returns True if the two strings are equal, False otherwise.

    The time taken is independent of the number of characters that match."""
    if len(val1) != len(val2):
        return False
    if isinstance(val1, bytes):
        val1 = val1.decode('ascii')
    if isinstance(val2, bytes):
        val2 = val2.decode('ascii')
    result = 0
    for x, y in zip(val1, val2):
        result |= ord(x) ^ ord(y)
    return result == 0

def _parse_param(key):
    """Parse the query param looking for filters

    Determine the field to filter on & the operator to
    be used when filtering.

    :param key:
        The query parameter to the left of the equal sign
    :return:
        tuple of string field name & string operator"""
    regex = re.compile('filter\\[([A-Za-z0-9_./]+)\\]')
    match = regex.match(key)
    if match:
        field_and_oper = match.groups()[0].split('__')
        if len(field_and_oper) == 1:
            return (field_and_oper[0], 'eq')
        elif len(field_and_oper) == 2:
            return tuple(field_and_oper)
        else:
            raise InvalidQueryParams(**{'detail': 'The filter query param of "%s" is not supported. Multiple filter operators are not allowed in a single expression.' % key, 'links': LINK, 'parameter': PARAM})

def _validate_field(param, fields):
    """Ensure the field exists on the model"""
    if '/' not in param.field and param.field not in fields:
        raise InvalidQueryParams(**{'detail': 'The filter query param of "%s" is not possible. The resource requested does not have a "%s" field. Please modify your request & retry.' % (param, param.field), 'links': LINK, 'parameter': PARAM})

def _validate_rel(param, rels):
    """Validate relationship based filters

    We don't support nested filters currently.

    FIX: Ensure the relationship filter field exists on the
         relationships model!"""
    if param.field.count('/') > 1:
        raise InvalidQueryParams(**{'detail': 'The filter query param of "%s" is attempting to filter on a nested relationship which is not currently supported.' % param, 'links': LINK, 'parameter': PARAM})
    elif '/' in param.field:
        model_field = param.field.split('/')[0]
        if model_field not in rels:
            raise InvalidQueryParams(**{'detail': 'The filter query param of "%s" is attempting to filter on a relationship but the "%s" field is NOT a relationship field.' % (param, model_field), 'links': LINK, 'parameter': PARAM})

def cleanup():
    """Saves all the open databases to JSON so that the kernel can be shut down
    without losing in-memory collections."""
    failed = {}
    success = []
    for dbname, db in dbs.items():
        try:
            db.save(True)
            success.append(dbname)
        except:
            import sys, traceback
            xcls, xerr = sys.exc_info()[0:2]
            failed[dbname] = traceback.format_tb(sys.exc_info()[2])
    for sdb in success:
        if writeable:
            msg.okay('Project {0}.{1} saved successfully.'.format(*sdb), 0)
    for fdb, tb in failed.items():
        msg.err('Project {1}.{2} save failed:\n{0}'.format(tb, *fdb), prefix=False)

def _dbdir():
    """Returns the path to the directory where acorn DBs are stored.
    """
    global dbdir
    from os import mkdir, path, getcwd, chdir
    if dbdir is None:
        from acorn.config import settings
        config = settings('acorn')
        if config.has_section('database') and config.has_option('database', 'folder'):
            dbdir = config.get('database', 'folder')
        else:
            raise ValueError("The folder to save DBs in must be configured  in 'acorn.cfg'")
    from acorn.utility import abspath
    if not path.isabs(dbdir):
        dbdir = abspath(dbdir)
    if not path.isdir(dbdir):
        mkdir(dbdir)
    return dbdir

def _json_clean(d):
    """Cleans the specified python `dict` by converting any tuple keys to
    strings so that they can be serialized by JSON.

    Args:
        d (dict): python dictionary to clean up.

    Returns:
        dict: cleaned-up dictionary."""
    result = {}
    compkeys = {}
    for k, v in d.items():
        if not isinstance(k, tuple):
            result[k] = v
        else:
            key = 'c.{}'.format(id(k))
            result[key] = v
            compkeys[key] = k
    return (result, compkeys)

def load_module(name, filename):
    """Load a module into name given its filename"""
    if sys.version_info < (3, 5):
        import imp
        import warnings
        with warnings.catch_warnings():
            warnings.simplefilter('ignore', RuntimeWarning)
            return imp.load_source(name, filename)
    else:
        from importlib.machinery import SourceFileLoader
        loader = SourceFileLoader(name, filename)
        return loader.load_module()

def function_arguments(func):
    """This returns a list of all arguments
    :param func: callable object
    :return: list of str of the arguments for the function"""
    if getattr(inspect, 'signature', None) is None:
        return list(inspect.getargspec(func).args)
    else:
        return list(inspect.signature(func).parameters.keys())

def function_defaults(func):
    """This returns a list of the default arguments
    :param func: callable object
    :return:     list of obj of default parameters"""
    if getattr(inspect, 'signature', None) is None:
        return inspect.getargspec(func)[-1] or []
    else:
        return [v.default for k, v in list(inspect.signature(func).parameters.items()) if v.default is not inspect._empty]

def function_doc(function_index=1, function_name=None):
    """    This will return the doc of the calling function
    :param function_index: int of how many frames back the program should look
    :param function_name: str of what function to look for
    :return: str of the doc from the target function"""
    frm = func_frame(function_index + 1, function_name)
    try:
        func = getattr(frm.f_locals['self'], frm.f_code.co_name)
    except:
        func = frm.f_globals[frm.f_code.co_name]
    return func.__doc__

def function_path(func):
    """This will return the path to the calling function
    :param func:
    :return:"""
    if getattr(func, 'func_code', None):
        return func.__code__.co_filename.replace('\\', '/')
    else:
        return func.__code__.co_filename.replace('\\', '/')

def function_history():
    """This will return a list of all function calls going back to the beginning
    :return: list of str of function name"""
    ret = []
    frm = inspect.currentframe()
    for i in range(100):
        try:
            if frm.f_code.co_name != 'run_code':
                ret.append(frm.f_code.co_name)
            frm = frm.f_back
        except Exception as e:
            break
    return ret

def func_frame(function_index, function_name=None):
    """This will return the class_name and function_name of the
    function traced back two functions.

    :param function_index: int of how many frames back the program
                           should look (2 will give the parent of the caller)
    :param function_name: str of what function to look for (should
                           not be used with function_index
    :return frame: this will return the frame of the calling function"""
    frm = inspect.currentframe()
    if function_name is not None:
        function_name = function_name.split('*')[0]
        for i in range(1000):
            if frm.f_code.co_name.startswith(function_name):
                break
            frm = frm.f_back
    else:
        for i in range(function_index):
            frm = frm.f_back
    try:
        if frm.f_code.co_name == 'run_code':
            frm = frm.f_back
    except:
        pass
    return frm

def trace_error(function_index=2):
    """This will return the line number and line text of the last error
    :param function_index: int to tell what frame to look from
    :return: int, str of the line number and line text"""
    info = function_info(function_index)
    traces = traceback.format_stack(limit=10)
    for trace in traces:
        file_, line_number, line_text = trace.split(',', 2)
        if file_ == '  File "%s"' % info['file'] and line_number != 'line %s' % info['line_number']:
            return (line_number.split()[-1], line_text.strip())
    return (None, None)

def rx_int_extra(rxmatch):
    """We didn't just match an int but the int is what we need."""
    rxmatch = re.search('\\d+', rxmatch.group(0))
    return int(rxmatch.group(0))

def smart_query_string(parser, token):
    """Outputs current GET query string with additions appended.
    Additions are provided in token pairs."""
    args = token.split_contents()
    additions = args[1:]
    addition_pairs = []
    while additions:
        addition_pairs.append(additions[0:2])
        additions = additions[2:]
    return SmartQueryStringNode(addition_pairs)

def list_projects(folders, folder=None, user=None):
    """List all folders or all subfolders of a folder.

    If folder is provided, this method will output a list of subfolders
    contained by it.  Otherwise, a list of all top-level folders is produced.

    :param folders: reference to folder.Folders instance
    :param folder: folder name or None
    :param user: optional user name"""
    fid = None if folder is None else Folders.name_to_id(folder)
    if fid is None:
        for f in folders.folders(user):
            print(Folders.id_to_name(f))
        return
    try:
