    if len(argl) > 1:
        if yP is None:
            Xt = argl[1]
            key = id(Xt)
            if key in _splits:
                yP = _splits[key][3]
        if yP is not None:
            import math
            out['%'] = round(1.0 - sum(abs(yP - result)) / float(len(result)), 3)

