def _to_camelcase(input_string):
    """a helper method to convert python to camelcase"""
    camel_string = ''
    for i in range(len(input_string)):
        if input_string[i] == '_':
            pass
        elif not camel_string:
            camel_string += input_string[i].upper()
        elif input_string[i - 1] == '_':
            camel_string += input_string[i].upper()
        else:
            camel_string += input_string[i]
    return camel_string

def _to_python(input_string):
    """a helper method to convert camelcase to python"""
    python_string = ''
    for i in range(len(input_string)):
        if not python_string:
            python_string += input_string[i].lower()
        elif input_string[i].isupper():
            python_string += '_%s' % input_string[i].lower()
        else:
            python_string += input_string[i]
    return python_string

def camelcase_to_lowercase(camelcase_input, python_input=None):
    """    a function to recursively convert data with camelcase key names into lowercase keys

    :param camelcase_input: list or dictionary with camelcase keys
    :param python_input: [optional] list or dictionary with default lowercase keys in output
    :return: dictionary with lowercase key names"""
    if python_input:
        if camelcase_input.__class__ != python_input.__class__:
            raise ValueError('python_input type %s does not match camelcase_input type %s' % (python_input.__class__, camelcase_input.__class__))
    if isinstance(camelcase_input, dict):
        return _to_python_dict(camelcase_input, python_input)
    elif isinstance(camelcase_input, list):
        return _ingest_list(camelcase_input, _to_python_dict, python_input)
    else:
        return camelcase_input

def lowercase_to_camelcase(python_input, camelcase_input=None):
    """    a function to recursively convert data with lowercase key names into camelcase keys

    :param camelcase_input: list or dictionary with lowercase keys
    :param python_input: [optional] list or dictionary with default camelcase keys in output
    :return: dictionary with camelcase key names"""
    if camelcase_input:
        if python_input.__class__ != camelcase_input.__class__:
            raise ValueError('camelcase_input type %s does not match python_input type %s' % (camelcase_input.__class__, python_input.__class__))
    if isinstance(python_input, dict):
        return _to_camelcase_dict(python_input, camelcase_input)
    elif isinstance(python_input, list):
        return _ingest_list(python_input, _to_camelcase_dict, camelcase_input)
    else:
        return python_input

def downloads_per_year(collection, code, raw=False):
    """This method retrieve the total of downloads per year.

    arguments
    collection: SciELO 3 letters Acronym
    code: (Journal ISSN, Issue PID, Article PID)

    return
    [
        ("2017", "20101"),
        ("2016", "11201"),
        ("2015", "12311"),
        ...
    ]"""
    tc = ThriftClient()
    body = {'query': {'filtered': {}}}
    fltr = {}
    query = {'query': {'bool': {'must': [{'match': {'collection': collection}}]}}}
    aggs = {'aggs': {'access_year': {'terms': {'field': 'access_year', 'size': 0, 'order': {'_term': 'asc'}}, 'aggs': {'access_total': {'sum': {'field': 'access_total'}}}}}}
    body['query']['filtered'].update(fltr)
    body['query']['filtered'].update(query)
    body.update(aggs)
    code_type = _code_type(code)
    if code_type:
        query['query']['bool']['must'].append({'match': {code_type: code}})
    query_parameters = [('size', '0')]
    query_result = tc.search(json.dumps(body), query_parameters)
    return query_result if raw is True else _compute_downloads_per_year(query_result)

def _build_return_code_enum():
    """Creates an IntEnum containing all the XTT return codes.

    Finds all return codes by scanning the FFI for items whose names match
    the pattern "XTT_RETURN_<X>".  The name of the result enum value is the
    suffix "<X>"."""
    prefix = 'XTT_RETURN_'
    codes = {k[len(prefix):]: v for k, v in vars(_lib).items() if k.startswith(prefix)}
    return IntEnum('ReturnCode', codes)

def Client(engine='couchbase', host='', auth='', database='', logger=None, verbose=True):
    """Return new database client

    Arguments

    engine <str> defines which engine to use, currently supports "couchdb" and "couchbase"
    host <str|couchdb.Server> host url, when using couchdb this can also be a server instance
    auth <str> bucket_auth for couchbase, auth for couchdb
    database <str> database name for couchdb
    logger <Logger> python logger instance"""
    if engine == 'couchbase':
        from twentyc.database.couchbase.client import CouchbaseClient
        return CouchbaseClient(host, bucket_auth=auth, logger=logger)
    elif engine == 'couchdb':
        from twentyc.database.couchdb.client import CouchDBClient
        return CouchDBClient(host, database, auth=auth, logger=logger, verbose=verbose)
    elif engine == 'dummydb':
        from twentyc.database.dummydb.client import DummyDBClient
        return DummyDBClient()
    else:
        raise InvalidEngineException(engine)

def ClientFromConfig(engine, config, database, logger=None, verbose=True):
    """Return new database client from valid [couchdb] or [couchbase]
    config section.

    engine <str> defines which engine to use, currently supports "couchdb" and "couchbase"
    config <dict> [couchdb] or [couchbase] section from config
    database <str> token to use with bucket_%s or db_%s config property"""
    if type(config) == list:
        config = dict(config)
    if engine == 'couchbase':
        return Client(engine=engine, host=config.get('host'), auth=config.get('bucket_%s' % database), logger=logger, verbose=verbose)
    elif engine == 'couchdb':
        if config.get('admin_user') and config.get('admin_password'):
            auth = '%s:%s' % (config.get('admin_user'), config.get('admin_password'))
        elif config.get('user') and config.get('password'):
            auth = '%s:%s' % (config.get('user'), config.get('password'))
        else:
            auth = None
        return Client(engine=engine, host=config.get('host'), auth=auth, database=config.get('db_%s' % database), logger=logger, verbose=verbose)
    elif engine == 'dummydb':
        return Client(engine=engine)
    else:
        raise InvalidEngineException(engine)

