def wind(direction: Number, speed: Number, gust: Number, vardir: typing.List[Number]=None, unit: str='kt', cardinals: bool=True, spoken: bool=False) -> str:
    """Format wind elements into a readable sentence

    Returns the translation string

    Ex: NNE-020 (variable 010 to 040) at 14kt gusting to 20kt"""
    ret = ''
    target = 'spoken' if spoken else 'repr'
    if direction:
        if direction.repr in WIND_DIR_REPR:
            ret += WIND_DIR_REPR[direction.repr]
        elif direction.value is None:
            ret += direction.repr
        else:
            if cardinals:
                ret += get_cardinal_direction(direction.value) + '-'
            ret += getattr(direction, target)
    if vardir and isinstance(vardir, list):
        vardir = [getattr(var, target) for var in vardir]
        ret += ' (variable {} to {})'.format(*vardir)
    if speed and speed.value:
        ret += f' at {speed.value}{unit}'
    if gust and gust.value:
        ret += f' gusting to {gust.value}{unit}'
    return ret

def clouds(clds: [Cloud], unit: str='ft') -> str:
    """Format cloud list into a readable sentence

    Returns the translation string

    Ex: Broken layer at 2200ft (Cumulonimbus), Overcast layer at 3600ft - Reported AGL"""
    if clds is None:
        return ''
    ret = []
    for cloud in clds:
        if cloud.altitude is None:
            continue
        cloud_str = CLOUD_TRANSLATIONS[cloud.type]
        if cloud.modifier:
            cloud_str += f' ({CLOUD_TRANSLATIONS[cloud.modifier]})'
        ret.append(cloud_str.format(cloud.altitude * 100, unit))
    if ret:
        return ', '.join(ret) + ' - Reported AGL'
    return 'Sky clear'

def wxcode(code: str) -> str:
    """Translates weather codes into readable strings

    Returns translated string of variable length"""
    if not code:
        return ''
    ret = ''
    if code[0] == '+':
        ret = 'Heavy '
        code = code[1:]
    elif code[0] == '-':
        ret = 'Light '
        code = code[1:]
    if len(code) not in [2, 4, 6]:
        return code
    for _ in range(len(code) // 2):
        if code[:2] in WX_TRANSLATIONS:
            ret += WX_TRANSLATIONS[code[:2]] + ' '
        else:
            ret += code[:2]
        code = code[2:]
    return ret.strip()

def turb_ice(turbice: [str], unit: str='ft') -> str:
    """Translate the list of turbulance or icing into a readable sentence

    Ex: Occasional moderate turbulence in clouds from 3000ft to 14000ft"""
    if not turbice:
        return ''
    if turbice[0][0] == '5':
        conditions = TURBULANCE_CONDITIONS
    elif turbice[0][0] == '6':
        conditions = ICING_CONDITIONS
    else:
        return ''
    split = []
    for item in turbice:
        if len(item) == 6:
            split.append([item[1:2], item[2:5], item[5]])
    for i in reversed(range(len(split) - 1)):
        if split[i][2] == '9' and split[i][0] == split[i + 1][0] and (int(split[i + 1][1]) == int(split[i][1]) + int(split[i][2]) * 10):
            split[i][2] = str(int(split[i][2]) + int(split[i + 1][2]))
            split.pop(i + 1)
    return ', '.join(['{conditions} from {low_alt}{unit} to {high_alt}{unit}'.format(conditions=conditions[item[0]], low_alt=int(item[1]) * 100, high_alt=int(item[1]) * 100 + int(item[2]) * 1000, unit=unit) for item in split])

def _get_substitute_element(head, elt, ps):
    """if elt matches a member of the head substitutionGroup, return
    the GED typecode.

    head -- ElementDeclaration typecode,
    elt -- the DOM element being parsed
    ps -- ParsedSoap Instance"""
    if not isinstance(head, ElementDeclaration):
        return None
    return ElementDeclaration.getSubstitutionElement(head, elt, ps)

def _is_substitute_element(head, sub):
    """if head and sub are both GEDs, and sub declares
    head as its substitutionGroup then return True.

    head -- Typecode instance
    sub  -- Typecode instance"""
    if not isinstance(head, ElementDeclaration) or not isinstance(sub, ElementDeclaration):
        return False
    try:
        group = sub.substitutionGroup
    except (AttributeError, TypeError):
        return False
    ged = GED(*group)
    print(head.nspname == ged.nspname and head.pname == ged.pname)
    if head is ged or not (head.nspname == ged.nspname and head.pname == ged.pname):
        return False
    return True

def make_dataset_header(data, file_format, aminoacids):
    """Creates the dataset header for NEXUS files from ``#NEXUS`` to ``MATRIX``.

    Parameters:
        data (namedtuple):    with necessary info for dataset creation.
        file_format (str):    TNT, PHYLIP, NEXUS, FASTA
        aminoacids (boolean): If ``aminoacids is True`` the header will show
                              ``DATATYPE=PROTEIN`` otherwise it will be ``DNA``."""
    if aminoacids:
        datatype = 'PROTEIN'
    else:
        datatype = 'DNA'
    if file_format in ['NEXUS', 'PHYLIP', 'FASTA']:
        header = '\n#NEXUS\n\nBEGIN DATA;\nDIMENSIONS NTAX={0} NCHAR={1};\nFORMAT INTERLEAVE DATATYPE={2} MISSING=? GAP=-;\nMATRIX\n'.format(data.number_taxa, data.number_chars, datatype)
    elif file_format == 'MEGA':
        return '#MEGA\n!TITLE title;'
    else:
        if aminoacids:
            molecule_type = 'prot'
        else:
            molecule_type = 'dna'
        header = '\nnstates {0};\nxread\n{1} {2}'.format(molecule_type, data.number_chars, data.number_taxa)
    return header.strip()

def timedelta_to_str(value, with_microseconds=False):
    """String representation of datetime.timedelta
    :param value: timedelta to convert
    :type value: datetime.timedelta
    :param with_microseconds:
    :type with_microseconds: bool
    :return: String representation of datetime.timedelta or None if val is None
    :rtype: string/None
    :raise: TypeError when val is not timedelta"""
    if value is None:
        return None
    if not isinstance(value, timedelta):
        raise TypeError('value must be a datetime.timedelta object')
    hours, remainder = divmod(value.seconds, SECONDS_IN_HOUR)
    hours += value.days * HOURS_IN_DAY
    minutes, seconds = divmod(remainder, SECONDS_IN_MINUTE)
    if with_microseconds:
        return '%02d:%02d:%02d.%06d' % (hours, minutes, seconds, value.microseconds)
    else:
        return '%02d:%02d:%02d' % (hours, minutes, seconds)

def parse_timedelta(value):
    """Parses a string and return a datetime.timedelta.
    :param value: string to parse
    :type value: str
    :return: timedelta object or None if value is None
    :rtype: timedelta/None
    :raise: TypeError when value is not string
    :raise: ValueError when value is not proper timedelta string"""
    if value is None:
        return None
    if not isinstance(value, six.string_types):
        raise TypeError('value must be a string type')
    match = INTERVAL_REGEX.search(value)
    if match:
        data = match.groupdict()
        return timedelta(**dict(((key, int(data[key] or 0)) for key in data)))
    else:
        raise ValueError("Value '%s' doesn't appear to be a valid timedelta string" % value)

def find_by_ast(line, version_token='__version__'):
    """Safer way to 'execute' python code to get a simple value
    :param line:
    :param version_token:
    :return:"""
    if not line:
        return ''
    simplified_line = simplify_line(line)
    if simplified_line.startswith(version_token):
        try:
            tree = ast.parse(simplified_line)
            if hasattr(tree.body[0].value, 's'):
                return unicode(tree.body[0].value.s)
            if hasattr(tree.body[0].value, 'elts'):
                version_parts = []
                for elt in tree.body[0].value.elts:
                    if hasattr(elt, 'n'):
                        version_parts.append(unicode(elt.n))
                    else:
                        version_parts.append(unicode(elt.s))
                return '.'.join(version_parts)
            if hasattr(tree.body[0].value, 'n'):
                return unicode(tree.body[0].value.n)
        except Exception:
            return None
    return None

def simplify_line(line, keep_comma=False):
    """Change ' to "
    Remove tabs and spaces (assume no significant whitespace inside a version string!)"""
    if not line:
        return ''
    if '#' in line:
        parts = line.split('#')
        simplified_line = parts[0]
    else:
        simplified_line = line
    simplified_line = simplified_line.replace(' ', '').replace("'", '"').replace('\t', '').replace('\n', '').replace("'''", '"').replace('"""', '"')
    if not keep_comma:
        simplified_line = simplified_line.strip(' ,')
    return simplified_line

def find_version_by_regex(file_source, version_token='__version__'):
    """Regex for dunder version"""
    if not file_source:
        return None
    version_match = re.search('^' + version_token + ' = [\'\\"]([^\'\\"]*)[\'\\"]', file_source, re.M)
    if version_match:
        candidate = version_match.group(1)
        if candidate == '' or candidate == '.':
            return None
        return candidate
    return None

def find_version_by_string_lib(line, version_token='__version__'):
    """No regex parsing. Or at least, mostly, not regex."""
    if not line:
        return None
    simplified_line = simplify_line(line)
    version = None
    if simplified_line.strip().startswith(version_token):
        if '"' not in simplified_line:
            pass
        elif '=' in simplified_line:
            post_equals = simplified_line.split('=')[1]
            if post_equals.startswith('"'):
                parts = post_equals.split('"')
                version = parts[0]
            if not version:
                version = None
    return version

def find_in_line(line):
    """Use three strategies to parse version string
    :param line:
    :return:"""
    if not line:
        return (None, None)
    for version_token in version_tokens:
        by_ast = find_by_ast(line, version_token)
        by_ast = validate_string(by_ast)
        if by_ast:
            return (by_ast, version_token)
        by_string_lib = find_version_by_string_lib(line, version_token)
        by_string_lib = validate_string(by_string_lib)
        if by_string_lib:
            return (by_string_lib, version_token)
        by_regex = find_version_by_regex(line, version_token)
        by_regex = validate_string(by_regex)
        if by_regex:
            return (by_regex, version_token)
    return (None, None)

def GetWSAActionInput(operation):
    """Find wsa:Action attribute, and return value or the default."""
    attr = operation.input.action
    if attr is not None:
        return attr
    portType = operation.getPortType()
    targetNamespace = portType.getTargetNamespace()
    ptName = portType.name
    msgName = operation.input.name
    if not msgName:
        msgName = operation.name + 'Request'
    if targetNamespace.endswith('/'):
        return '%s%s/%s' % (targetNamespace, ptName, msgName)
    return '%s/%s/%s' % (targetNamespace, ptName, msgName)

def GetWSAActionOutput(operation):
    """Find wsa:Action attribute, and return value or the default."""
    attr = operation.output.action
    if attr is not None:
        return attr
    targetNamespace = operation.getPortType().getTargetNamespace()
    ptName = operation.getPortType().name
    msgName = operation.output.name
    if not msgName:
        msgName = operation.name + 'Response'
    if targetNamespace.endswith('/'):
        return '%s%s/%s' % (targetNamespace, ptName, msgName)
    return '%s/%s/%s' % (targetNamespace, ptName, msgName)

def assert_bool(dist, attr, value):
    """Verify that value is True, False, 0, or 1"""
    if bool(value) != value:
        raise DistutilsSetupError('%r must be a boolean value (got %r)' % (attr, value))

