        list(pkg_resources.parse_requirements(value))
    except (TypeError, ValueError):
        raise DistutilsSetupError('%r must be a string or list of strings containing valid project/version requirement specifiers' % (attr,))

def _get_env(key, default=None, coerce=lambda x: x, required=False):
    """Return env var coerced into a type other than string.

    This function extends the standard os.getenv function to enable
    the coercion of values into data types other than string (all env
    vars are strings by default).

    Args:
        key: string, the name of the env var to look up

    Kwargs:
        default: the default value to return if the env var does not exist. NB the
            default value is **not** coerced, and is assumed to be of the correct type.
        coerce: a function that is used to coerce the value returned into
            another type
        required: bool, if True, then a RequiredSettingMissing error is raised
            if the env var does not exist.

    Returns the env var, passed through the coerce function"""
    try:
        value = os.environ[key]
    except KeyError:
        if required is True:
            raise RequiredSettingMissing(key)
        else:
            return default
    try:
        return coerce(value)
    except Exception:
        raise CoercianError(key, value, coerce)

def get_list(key, *default, **kwargs):
    """Return env var as a list."""
    separator = kwargs.get('separator', ' ')
    return get_env(key, *default, coerce=lambda x: x.split(separator))

def row_to_content_obj(key_row):
    """Returns ``FeatureCollection`` given an HBase artifact row.

    Note that the FC returned has a Unicode feature ``artifact_id``
    set to the row's key."""
    key, row = key_row
    cid = mk_content_id(key.encode('utf-8'))
    response = row.get('response', {})
    other_bows = defaultdict(StringCounter)
    for attr, val in row.get('indices', []):
        other_bows[attr][val] += 1
    try:
        artifact_id = key
        if isinstance(artifact_id, str):
            artifact_id = unicode(artifact_id, 'utf-8')
        fc = html_to_fc(response.get('body', ''), url=row.get('url'), timestamp=row.get('timestamp'), other_features=dict(other_bows, **{'artifact_id': artifact_id}))
    except:
        fc = None
        print('Could not create FC for %s:' % cid, file=sys.stderr)
        print(traceback.format_exc(), file=sys.stderr)
    return (cid, fc)

def _dict_to_tuple(d):
    """Convert a dictionary to a time tuple.  Depends on key values in the
    regexp pattern!"""
    retval = _niltime[:]
    for k, i in (('Y', 0), ('M', 1), ('D', 2), ('h', 3), ('m', 4)):
        v = d.get(k)
        if v:
            retval[i] = int(v)
    v = d.get('s')
    if v:
        msec, sec = _modf(float(v))
        retval[6], retval[5] = (int(round(msec * 1000)), int(sec))
    v = d.get('tz')
    if v and v != 'Z':
        h, m = map(int, v.split(':'))
        offset = _localtimezone().utcoffset(_datetime.now())
        local_offset_hour = offset.seconds / 3600
        local_offset_min = offset.seconds % 3600 % 60
        if local_offset_hour > 12:
            local_offset_hour -= 24
        if local_offset_hour != h or local_offset_min != m:
            if h < 0:
                foff = _fixedoffset(-(abs(h) * 60 + m))
            else:
                foff = _fixedoffset(abs(h) * 60 + m)
            dt = _datetime(retval[0], retval[1], retval[2], retval[3], retval[4], retval[5], 0, foff)
            localdt = dt.astimezone(_localtimezone())
            retval[0] = localdt.year
            retval[1] = localdt.month
            retval[2] = localdt.day
            retval[3] = localdt.hour
            retval[4] = localdt.minute
            retval[5] = localdt.second
    if d.get('neg', 0):
        retval[0:5] = map(operator.__neg__, retval[0:5])
    return tuple(retval)

def callback_property(getter):
    """A decorator to build a CallbackProperty.

    This is used by wrapping a getter method, similar to the use of @property::

        class Foo(object):
            @callback_property
            def x(self):
                 return self._x

            @x.setter
            def x(self, value):
                self._x = value

    In simple cases with no getter or setter logic, it's easier to create a
    :class:`~echo.CallbackProperty` directly::

        class Foo(object);
            x = CallbackProperty(initial_value)"""
    cb = CallbackProperty(getter=getter)
    cb.__doc__ = getter.__doc__
    return cb

