def transform_data(function, input_data):
    """a function to apply a function to each value in a nested dictionary

    :param function: callable function with a single input of any datatype
    :param input_data: dictionary or list with nested data to transform
    :return: dictionary or list with data transformed by function"""
    try:
        from copy import deepcopy
        output_data = deepcopy(input_data)
    except:
        raise ValueError('transform_data() input_data argument cannot contain module datatypes.')
    for dot_path, value in walk_data(input_data):
        current_endpoint = output_data
        segment_list = segment_path(dot_path)
        segment = None
        if segment_list:
            for i in range(len(segment_list)):
                try:
                    segment = int(segment_list[i])
                except:
                    segment = segment_list[i]
                if i + 1 == len(segment_list):
                    pass
                else:
                    current_endpoint = current_endpoint[segment]
            current_endpoint[segment] = function(value)
    return output_data

def clean_data(input_value):
    """a function to transform a value into a json or yaml valid datatype

    :param input_value: object of any datatype
    :return: object with json valid datatype"""
    if input_value.__class__.__name__ in ['bool', 'str', 'float', 'int', 'NoneType']:
        pass
    elif isinstance(input_value, bytes):
        from base64 import b64encode
        input_value = b64encode(input_value).decode()
    elif isinstance(input_value, tuple) or isinstance(input_value, set):
        new_list = []
        new_list.extend(input_value)
        input_value = transform_data(clean_data, new_list)
    elif isinstance(input_value, dict) or isinstance(input_value, list):
        input_value = transform_data(clean_data, input_value)
    else:
        input_value = str(input_value)
    return input_value

def _force_text_recursive(data):
    """Descend into a nested data structure, forcing any
    lazy translation strings into plain text."""
    if isinstance(data, list):
        ret = [_force_text_recursive(item) for item in data]
        if isinstance(data, ReturnList):
            return ReturnList(ret, serializer=data.serializer)
        return data
    elif isinstance(data, dict):
        ret = {key: _force_text_recursive(value) for key, value in data.items()}
        if isinstance(data, ReturnDict):
            return ReturnDict(ret, serializer=data.serializer)
        return data
    return force_text(data)

def animation(frame_function: types.FrameFunction) -> types.Animation:
    """Turn a FrameFunction into an Animation.

    Args:
        frame_function: A function that returns a FrameGenerator.

    Returns:
        an Animation decorator function."""
    animation_ = core.Animation(frame_function)
    @functools.wraps(frame_function)
    def wrapper(*args, **kwargs):
        return animation_(*args, **kwargs)
    return wrapper

def animate(func: types.AnyFunction=None, *, animation: types.AnimationGenerator=_default_animation(), step: float=0.1) -> types.AnyFunction:
    """Wrapper function for the _Animate wrapper class.

    Args:
        func: A function to run while animation is showing.
        animation: An AnimationGenerator that yields animation frames.
        step: Approximate timestep (in seconds) between frames.
    Returns:
        An animated version of func if func is not None. Otherwise, a function
        that takes a function and returns an animated version of that."""
    if callable(func):
        return _animate_no_kwargs(func, animation, step)
    elif func is None:
        return _animate_with_kwargs(animation_gen=animation, step=step)
    else:
        raise TypeError("argument 'func' must either be None or callable")

def annotate(*, start_msg: Optional[str]=None, end_msg: Optional[str]=None, start_no_nl: bool=False) -> types.AnyFunction:
    """A decorator meant for decorating functions that are decorated with the
    `animate` decorator. It prints a message to stdout before and/or after the
    function has finished.

    .. DANGER::

        This decorator can also be used standalone, but you should NOT decorate a
        function that is decorated with `annotate` with `animate`. That is to say,
        the decorator order must be like this:

        .. code-block:: python

            @annotate
            @animate
            def some_function()
                pass"""
    return core.Annotate(start_msg=start_msg, end_msg=end_msg, start_no_nl=start_no_nl)

def copy_tree(src, dst):
    """Copy directory tree"""
    for root, subdirs, files in os.walk(src):
        current_dest = root.replace(src, dst)
        if not os.path.exists(current_dest):
            os.makedirs(current_dest)
        for f in files:
            shutil.copy(os.path.join(root, f), os.path.join(current_dest, f))

