def class_parameters(decorator):
    """To wrap all class methods with static_parameters decorator"""
    def decorate(the_class):
        if not isclass(the_class):
            raise TypeError('class_parameters(the_class=%s) you must pass a class' % the_class)
        for attr in the_class.__dict__:
            if callable(getattr(the_class, attr)):
                setattr(the_class, attr, decorator(getattr(the_class, attr)))
        return the_class
    return decorate

def lazy_send(chainlet, chunks):
    """Canonical version of `chainlet_send` that always takes and returns an iterable

    :param chainlet: the chainlet to receive and return data
    :type chainlet: chainlink.ChainLink
    :param chunks: the stream slice of data to pass to ``chainlet``
    :type chunks: iterable
    :return: the resulting stream slice of data returned by ``chainlet``
    :rtype: iterable"""
    fork, join = (chainlet.chain_fork, chainlet.chain_join)
    if fork and join:
        return _send_n_get_m(chainlet, chunks)
    elif fork:
        return _lazy_send_1_get_m(chainlet, chunks)
    elif join:
        return _lazy_send_n_get_1(chainlet, chunks)
    else:
        return _lazy_send_1_get_1(chainlet, chunks)

def eager_send(chainlet, chunks):
    """Eager version of `lazy_send` evaluating the return value immediately

    :note: The return value by an ``n`` to ``m`` link is considered fully evaluated.

    :param chainlet: the chainlet to receive and return data
    :type chainlet: chainlink.ChainLink
    :param chunks: the stream slice of data to pass to ``chainlet``
    :type chunks: iterable
    :return: the resulting stream slice of data returned by ``chainlet``
    :rtype: iterable"""
    fork, join = (chainlet.chain_fork, chainlet.chain_join)
    if fork and join:
        return _send_n_get_m(chainlet, chunks)
    elif fork:
        return tuple(_lazy_send_1_get_m(chainlet, chunks))
    elif join:
        return tuple(_lazy_send_n_get_1(chainlet, chunks))
    else:
        return tuple(_lazy_send_1_get_1(chainlet, chunks))

def parse_arg_types(text=None, is_return_included=False):
    """:param text:               str of the text to parse, by default
                               uses calling function doc
    :param is_return_included: bool if True return will be return as well
    :return:                   dict of args and variable types"""
    text = text or function_doc(2)
    if is_return_included:
        text = text.replace(':return:', ':param return:')
    ret = {}
    def evl(text_):
        try:
            return eval(text_)
        except Exception as e:
            return text_
    if ':param' in text:
        for param in text.split(':param ')[1:]:
            name, desc = param.split(':', 1)
            name = name.strip()
            if desc.strip().startswith('list of '):
                ret[name] = (list, evl(desc.split()[2].replace('str', STR)))
            elif desc.strip().startswith('str timestamp'):
                ret[name] = datetime
            else:
                ret[name] = evl(desc.split(None, 1)[0].replace('str', STR))
    return ret

