def find_exe(name):
    """Find an executable with the given name.
    :param name:
    :return:"""
    for path in os.getenv('PATH').split(os.pathsep):
        for ext in ('', '.exe', '.cmd', '.bat', '.sh'):
            full_path = os.path.join(path, name + ext)
            if os.path.isfile(full_path) and os.access(full_path, os.X_OK):
                return full_path
    return None

def covered_interval(bin):
    """Given a bin number `bin`, return the interval covered by this bin.

    :arg int bin: Bin number.

    :return: Tuple of `start, stop` being the zero-based, open-ended interval
      covered by `bin`.
    :rtype: tuple(int)

    :raise OutOfRangeError: If bin number `bin` exceeds the maximum bin
      number."""
    if bin < 0 or bin > MAX_BIN:
        raise OutOfRangeError('Invalid bin number %d (maximum bin number is %d)' % (bin, MAX_BIN))
    shift = SHIFT_FIRST
    for offset in BIN_OFFSETS:
        if offset <= bin:
            return (bin - offset << shift, bin + 1 - offset << shift)
        shift += SHIFT_NEXT

def get_user_root_directory():
    """Get user root directory (application user configuration root directory)

    Returns
    -------
    string
        A full path"""
    uname = platform.system()
    if uname == 'Windows':
        root = os.path.join(os.environ['APPDATA'], APP_NAME)
        root = os.path.abspath(root)
    elif uname == 'Linux':
        if os.path.exists(os.path.expanduser('~/.config')):
            root = os.path.join(os.path.expanduser('~/.config'), APP_NAME)
        else:
            root = os.path.join(os.path.expanduser('~'), '.%s' % APP_NAME)
        root = os.path.abspath(root)
    elif uname in ('Linux', 'Darwin'):
        root = os.path.join(os.path.expanduser('~'), '.%s' % APP_NAME)
        root = os.path.abspath(root)
    else:
        root = os.path.join(os.path.expanduser('~'), APP_NAME)
        root = os.path.abspath(root)
    return root

def execute_get_text(command):
    """Execute shell command and return stdout txt
    :param command:
    :return:"""
    try:
        _ = subprocess.run
        try:
            completed = subprocess.run(command, check=True, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        except subprocess.CalledProcessError as cpe:
            raise
        else:
            return completed.stdout.decode('utf-8') + completed.stderr.decode('utf-8')
    except AttributeError:
        try:
            p = subprocess.Popen(command.split(' '), stdout=subprocess.PIPE)
            out, err = p.communicate()
        except subprocess.CalledProcessError as cpe:
            raise
        else:
            return str(out) + str(err)

def get_query_type(query):
    """Gets the type of query in use (email or url).

    In order to provide a proper API endpoint it is necessary to first
    determine the type of query the client is using. There are only two
    options currently: 1) domain or 2) email.

    :param query: Search query provided by client."""
    if URL_RE.match(query):
        query_type = 'domain'
    elif EMAIL_RE.match(query):
        query_type = 'email'
    else:
        query_type = ''
    return query_type

def get_endpoint(api_key, query, offset, type):
    """Return endpoint URL for the relevant search type.

    The base API endpoint only varies by type of search requested, of
    which there are two: 1) domain search and 2) email search. Each
    search type requires different parameters, though api_key is common
    between them.

    Note: if both a url and email address are provided the endpoint
    returned will default to the domain search as it is considered to
    be the primary function of the API and thus takes precedent.

    :param api_key: Secret client API key.
    :param query: URL or email address on which to search.
    :param offset: Specifies the number of emails to skip.
    :param type: Specifies email type (i.e. generic or personal)."""
    query_type = get_query_type(query)
    if query_type not in ('domain', 'email'):
        raise ex.InvalidQueryStringException('Invalid query string')
    if query_type == 'domain':
        return DOMAIN_URL.format(query, api_key, offset, type)
    else:
        return EMAIL_URL.format(query, api_key)

