def watch_login(func):
    """Decorator @watch_login
    :param func:
    :return:"""
    @wraps(func)
    def decorated_login(request, *args, **kwargs):
        response = func(request, *args, **kwargs)
        lockout = AccessAttempt(request, response)
        user_access = lockout.check_failed_login()
        if user_access.is_locked or lockout.is_ip_banned:
            return lockout.get_lockout_response()
        return response
    return decorated_login

def _get_acorn(self, method, *items):
    """Gets either a slice or an item from an array. Used for the __getitem__
    and __getslice__ special methods of the sub-classed array.

    Args:
        method (str): on of ['slice', 'item']."""
    if method == 'slice':
        r = np.ndarray.__acornext__.__getslice__(self, *items)
    else:
        r = np.ndarray.__acornext__.__getitem__(self, *items)
    if not (decorating or streamlining):
        from acorn.logging.decoration import pre, post, _fqdn
        if method == 'slice':
            fqdn = 'numpy.ndarray.__getslice__'
        else:
            fqdn = 'numpy.ndarray.__getitem__'
        preres = pre(fqdn, np.ndarray, 5, self, *items)
        entry, bound, ekey = preres
        post(fqdn, 'numpy', r, entry, np.ndarray, ekey)
    return r

def _run_configure(subcmd, args):
    """Runs the configuration step for the specified sub-command.
    """
    maps = {'packages': _conf_packages}
    if subcmd in maps:
        maps[subcmd](args)
    else:
        msg.warn("'configure' sub-command {} is not supported.".format(subcmd))

def run(args):
    """Runs the acorn setup/configuration commands.
    """
    if args is None:
        return
    cmd = args['commands'][0]
    if cmd == 'configure':
        if len(args['commands']) < 2:
            msg.err("'configure' command requires a second, sub-command parameter. E.g., `acorn.py configure packages`.")
            exit(0)
        subcmd = args['commands'][1]
        _run_configure(subcmd, args)

def _convert(value, tzto, defaulttz):
    """Convert datetime.datetime object between timezones"""
    if not isinstance(value, datetime):
        raise ValueError('value must be a datetime.datetime object')
    if value.tzinfo is None:
        value = value.replace(tzinfo=defaulttz)
    return value.astimezone(tzto)

def to_local(value, defaulttz=None):
    """Convert datetime.datetime time to local time zone

    If value doesn't have tzinfo, then defaulttz is set.
    Default value of defaulttz is UTC."""
    if defaulttz is None:
        defaulttz = tzutc()
    return _convert(value, tzlocal(), defaulttz)

def to_utc(value, defaulttz=None):
    """Convert datetime.datetime time to UTC

    If value doesn't have tzinfo, then defaulttz is set.
    Default value of defaulttz is local time zone."""
    if defaulttz is None:
        defaulttz = tzlocal()
