def chainCerts(data):
    """Matches and returns any certificates found except the first match.

    Regex code copied from L{twisted.internet.endpoints._parseSSL}.
    Related ticket: https://twistedmatrix.com/trac/ticket/7732

    @type path: L{bytes}
    @param data: PEM-encoded data containing the certificates.

    @rtype: L{list} containing L{Certificate}s."""
    matches = re.findall('(-----BEGIN CERTIFICATE-----\\n.+?\\n-----END CERTIFICATE-----)', data, flags=re.DOTALL)
    chainCertificates = [Certificate.loadPEM(chainCertPEM).original for chainCertPEM in matches]
    return chainCertificates[1:]

def extract_session_details(request_headers, session_header, secret_key):
    """    a method to extract and validate jwt session token from request headers

    :param request_headers: dictionary with header fields from request
    :param session_header: string with name of session token header key
    :param secret_key: string with secret key to json web token encryption
    :return: dictionary with request details with session details or error coding"""
    session_details = {'error': '', 'code': 200, 'session': {}}
    if not session_header in request_headers.keys():
        session_details['error'] = '%s is missing.' % session_header
        session_details['code'] = 400
    else:
        import jwt
        session_token = request_headers[session_header]
        try:
            session_details['session'] = jwt.decode(session_token, secret_key)
        except jwt.DecodeError as err:
            session_details['error'] = 'Session token decoding error.'
            session_details['code'] = 400
        except jwt.ExpiredSignatureError as err:
            session_details['error'] = 'Session token has expired.'
            session_details['code'] = 400
        except Exception:
            session_details['error'] = 'Session token is invalid.'
            session_details['code'] = 400
    return session_details

def make_xpath_ranges(html, phrase):
    """Given a HTML string and a `phrase`, build a regex to find offsets
    for the phrase, and then build a list of `XPathRange` objects for
    it.  If this fails, return empty list."""
    if not html:
        return []
    if not isinstance(phrase, unicode):
        try:
            phrase = phrase.decode('utf8')
        except:
            logger.info('failed %r.decode("utf8")', exc_info=True)
            return []
    phrase_re = re.compile(phrase, flags=re.UNICODE | re.IGNORECASE | re.MULTILINE)
    spans = []
    for match in phrase_re.finditer(html, overlapped=False):
        spans.append(match.span())
    try:
        xpath_ranges = list(char_offsets_to_xpaths(html, spans))
    except:
        logger.info('failed to get xpaths', exc_info=True)
        return []
    ranges = []
    for xpath_range in filter(None, xpath_ranges):
        ranges.append(dict(start=dict(node=xpath_range.start_xpath, idx=xpath_range.start_offset), end=dict(node=xpath_range.end_xpath, idx=xpath_range.end_offset)))
    return ranges

def _model_columns(ins):
    """Get columns info

    :type ins: sqlalchemy.orm.mapper.Mapper
    :rtype: list[SaColumnDoc]"""
    columns = []
    for c in ins.column_attrs:
        if c.key.startswith('_'):
            continue
        columns.append(SaColumnDoc(key=c.key, doc=c.doc or '', type=str(c.columns[0].type), null=c.columns[0].nullable))
    return columns

def _model_unique(ins):
    """Get unique constraints info

    :type ins: sqlalchemy.orm.mapper.Mapper
    :rtype: list[tuple[str]]"""
    unique = []
    for t in ins.tables:
        for c in t.constraints:
            if isinstance(c, UniqueConstraint):
                unique.append(tuple((col.key for col in c.columns)))
    return unique

def _model_relations(ins):
    """Get relationships info

    :type ins: sqlalchemy.orm.mapper.Mapper
    :rtype: list[SaRelationshipDoc]"""
    relations = []
    for r in ins.relationships:
        if isinstance(r.argument, Mapper):
            model_name = r.argument.class_.__name__
        elif hasattr(r.argument, 'arg'):
            model_name = r.argument.arg
        else:
            model_name = r.argument.__name__
        relations.append(SaRelationshipDoc(key=r.key, doc=r.doc or '', model=model_name, pairs=map(lambda a_b_tuple: a_b_tuple[0].key if a_b_tuple[0].key == a_b_tuple[1].key else '{}={}'.format(a_b_tuple[0].key, a_b_tuple[1].key), r.local_remote_pairs), uselist=r.uselist))
    return relations

