def allowed(name, collection='all'):
    """Return true if this name is allowed (e.g. not in the forbidden list,
    indicated by 'collection'), false otherwise."""
    if not valid(name):
        return False
    blacklist = names()
    for forbidden in blacklist[collection]:
        if name.lower() == forbidden.lower():
            return False
        if forbidden.endswith('*'):
            if name.lower().startswith(forbidden[:-1].lower()):
                return False
        if forbidden.startswith('/'):
            if not allowed(name, collection=forbidden[1:]):
                return False
    return True

def get_signer_by_version(digest, ver):
    """Returns a new signer object for a digest and version combination.

    Keyword arguments:
    digest -- a callable that may be passed to the initializer of any Signer object in this library.
        The callable must return a hasher object when called with no arguments.
    ver -- the version of the signature. This may be any value convertible to an int."""
    if int(ver) == 1:
        return V1Signer(digest)
    elif int(ver) == 2:
        return V2Signer(digest)
    else:
        return None

def date_tuple(ovls):
    """We should have a list of overlays from which to extract day month
    year."""
    day = month = year = 0
    for o in ovls:
        if 'day' in o.props:
            day = o.value
        if 'month' in o.props:
            month = o.value
        if 'year' in o.props:
            year = o.value
        if 'date' in o.props:
            day, month, year = [o or n for o, n in zip((day, month, year), o.value)]
    return (day, month, year)

def longest_overlap(ovls):
    """From a list of overlays if any overlap keep the longest."""
    ovls = sorted(ovls)
    for i, s in enumerate(ovls):
        passing = True
        for l in ovls[i + 1:]:
            if s.start in Rng(l.start, l.end, rng=(True, True)) or s.end in Rng(l.start, l.end, rng=(True, True)):
                passing = False
                break
        if passing:
            yield s

def render_title_tag(context, is_og=False):
    """Returns the title as string or a complete open graph meta tag."""
    request = context['request']
    content = ''
    if context.get('object'):
        try:
            content = context['object'].get_meta_title()
        except AttributeError:
            pass
    elif context.get('meta_tagger'):
        content = context['meta_tagger'].get('title')
    if not content:
        try:
            content = request.current_page.get_page_title()
            if not content:
                content = request.current_page.get_title()
        except (AttributeError, NoReverseMatch):
            pass
    if not is_og:
        return content
    else:
        return mark_safe('<meta property="og:title" content="{content}">'.format(content=content))

