def _validate_param(rtype, fields):
    """Ensure the sparse fields exists on the models"""
    try:
        model = rtype_to_model(rtype)
        model_fields = model.all_fields
    except ValueError:
        raise InvalidQueryParams(**{'detail': 'The fields query param provided with a field type of "%s" is unknown.' % rtype, 'links': LINK, 'parameter': PARAM})
    for field in fields:
        if field not in model_fields:
            raise InvalidQueryParams(**{'detail': 'The fields query param "TYPE" of "%s" is not possible. It does not have a field by the name of "%s".' % (rtype, field), 'links': LINK, 'parameter': PARAM})

def init(req, model):
    """Determine the sparse fields to limit the response to

    Return a dict where the key is the resource type (rtype) &
    the value is an array of string fields names to whitelist
    against.

    :return:
        dict"""
    params = {}
    for key, val in req.params.items():
        try:
            rtype, fields = _parse_param(key, val)
            params[rtype] = fields
        except TypeError:
            continue
    if params:
        _validate_req(req)
        for rtype, fields in params.items():
            _validate_param(rtype, fields)
    return params

def consume(iter, N=None):
    """Consumes N items from iter.  If N is None (or not given), consumes all.
    """
    i = iter
    if N is not None:
        i = islice(iter, N)
    for x in i:
        pass

def iteration_length(N, start=0, step=1):
    """Return the number of iteration steps over a list of length N,
    starting at index start, proceeding step elements at a time.
    """
    if N < 0:
        raise ValueError('N cannot be negative')
    if start < 0:
        start += N
        if start < 0:
            raise ValueError('Invalid start value')
    if step < 0:
        step = -step
        new_N = start + 1
        if new_N > N:
            raise ValueError('Invalid parameters')
        N = new_N
        start = 0
    ret = int(math.ceil((N - start) / float(step)))
    return max(0, ret)

def _get_forward_relationships(opts):
    """Returns an `OrderedDict` of field names to `RelationInfo`."""
    forward_relations = OrderedDict()
    for field in [field for field in opts.fields if field.serialize and field.rel]:
        forward_relations[field.name] = RelationInfo(model_field=field, related_model=_resolve_model(field.rel.to), to_many=False, to_field=_get_to_field(field), has_through_model=False)
    for field in [field for field in opts.many_to_many if field.serialize]:
        forward_relations[field.name] = RelationInfo(model_field=field, related_model=_resolve_model(field.rel.to), to_many=True, to_field=None, has_through_model=not field.rel.through._meta.auto_created)
    return forward_relations

def is_abstract_model(model):
    """Given a model class, returns a boolean True if it is abstract and False if it is not."""
    return hasattr(model, '_meta') and hasattr(model._meta, 'abstract') and model._meta.abstract

def canonicalize_header(key):
    """Returns the canonicalized header name for the header name provided as an argument.
    The canonicalized header name according to the HTTP RFC is Kebab-Camel-Case.

    Keyword arguments:
    key -- the name of the header"""
    bits = key.split('-')
    for idx, b in enumerate(bits):
        bits[idx] = b.capitalize()
    return '-'.join(bits)

def slim_stem(token):
    """A very simple stemmer, for entity of GO stemming.

    >>> token = 'interaction'
    >>> slim_stem(token)
    'interact'"""
    target_sulfixs = ['ic', 'tic', 'e', 'ive', 'ing', 'ical', 'nal', 'al', 'ism', 'ion', 'ation', 'ar', 'sis', 'us', 'ment']
    for sulfix in sorted(target_sulfixs, key=len, reverse=True):
        if token.endswith(sulfix):
            token = token[0:-len(sulfix)]
            break
    if token.endswith('ll'):
        token = token[:-1]
    return token

def ngram(n, iter_tokens):
    """Return a generator of n-gram from an iterable"""
    z = len(iter_tokens)
    return (iter_tokens[i:i + n] for i in range(z - n + 1))

def power_ngram(iter_tokens):
    """Generate unigram, bigram, trigram ... and the max-gram,
    different from powerset(), this function will not generate skipped combinations such as (1,3)"""
    return chain.from_iterable((ngram(j, iter_tokens) for j in range(1, len(iter_tokens) + 1)))

def preserve_attr_data(A, B):
    """Preserve attr data for combining B into A.
    """
    for attr, B_data in B.items():
        if getattr(B_data, 'override_parent', True):
            continue
        if attr in A:
            A_data = A[attr]
            for _attr in getattr(A_data, '_attrs', []):
                if hasattr(A_data, _attr):
                    if getattr(B_data, _attr, None) is not None:
                        if _attr in getattr(B_data, '_set_by_default', []):
                            setattr(B_data, _attr, getattr(A_data, _attr))
                    else:
                        setattr(B_data, _attr, getattr(A_data, _attr))

def metaclasses(bases):
    """Returns 'proper' metaclasses for the classes in bases
    """
    ret = []
    metas = [type(base) for base in bases]
    for k, meta in enumerate(metas):
        if not any((issubclass(m, meta) for m in metas[k + 1:])):
            ret.append(meta)
    if type in ret:
        ret.remove(type)
    return ret

def sorted_bases(bases):
    """If a class subclasses each class in bases (in that order), then
    this function returns the would-be python mro for the created class,
    minus <object>."""
    ret = []
    for base in bases:
        lst = _bases(base)
        if not ret:
            ret = lst
        elif not any((b in ret for b in lst)):
            ret += lst
        else:
            buf = []
            for b in lst:
                if b in ret:
                    if buf:
                        ret = graft(ret, buf, ret.index(b))
                        buf = []
                else:
                    buf.append(b)
            if buf:
                ret += buf
    return ret

