def resolve_dependencies(nodes):
    """Figure out which order the nodes in the graph can be executed
    in to satisfy all requirements."""
    done = set()
    while True:
        if len(done) == len(nodes):
            break
        for node in nodes:
            if node.name not in done:
                match = done.intersection(node.requires)
                if len(match) == len(node.requires):
                    done.add(node.name)
                    yield node
                    break
        else:
            raise ConfigException('Invalid requirements in pipeline!')

def getDataPath(_system=thisSystem, _FilePath=FilePath):
    """Gets an appropriate path for storing some local data, such as TLS
    credentials.

    If the path doesn't exist, it is created."""
    if _system == 'Windows':
        pathName = '~/Crypto101/'
    else:
        pathName = '~/.crypto101/'
    path = _FilePath(expanduser(pathName))
    if not path.exists():
        path.makedirs()
    return path

def FaultFromZSIException(ex, actor=None):
    """Return a Fault object created from a ZSI exception object.
    """
    mystr = getattr(ex, 'str', None) or str(ex)
    mytrace = getattr(ex, 'trace', '')
    elt = '<ZSI:ParseFaultDetail>\n<ZSI:string>%s</ZSI:string>\n<ZSI:trace>%s</ZSI:trace>\n</ZSI:ParseFaultDetail>\n' % (mystr, mytrace)
    if getattr(ex, 'inheader', 0):
        detail, headerdetail = (None, elt)
    else:
        detail, headerdetail = (elt, None)
    return Fault(Fault.Client, 'Unparseable message', actor, detail, headerdetail)

def FaultFromException(ex, inheader, tb=None, actor=None):
    """Return a Fault object created from a Python exception.

    <SOAP-ENV:Fault>
      <faultcode>SOAP-ENV:Server</faultcode>
      <faultstring>Processing Failure</faultstring>
      <detail>
        <ZSI:FaultDetail>
          <ZSI:string></ZSI:string>
          <ZSI:trace></ZSI:trace>
        </ZSI:FaultDetail>
      </detail>
    </SOAP-ENV:Fault>"""
    tracetext = None
    if tb:
        try:
            lines = '\n'.join(['%s:%d:%s' % (name, line, func) for name, line, func, text in traceback.extract_tb(tb)])
        except:
            pass
        else:
            tracetext = lines
    exceptionName = ''
    try:
        exceptionName = ':'.join([ex.__module__, ex.__class__.__name__])
    except:
        pass
    elt = ZSIFaultDetail(string=exceptionName + '\n' + str(ex), trace=tracetext)
    if inheader:
        detail, headerdetail = (None, elt)
    else:
        detail, headerdetail = (elt, None)
    return Fault(Fault.Server, 'Processing Failure', actor, detail, headerdetail)

def FaultFromFaultMessage(ps):
    """Parse the message as a fault.
    """
    pyobj = ps.Parse(FaultType.typecode)
    if pyobj.detail == None:
        detailany = None
    else:
        detailany = pyobj.detail.any
    return Fault(pyobj.faultcode, pyobj.faultstring, pyobj.faultactor, detailany)

def _remove_settings(_file_path, _retry_count=10, _remove_dir=False):
    """    a helper method for removing settings file

    :param _file_path: string with path to file to remove
    :param _retry_count: integer with number of attempts before error is raised
    :param _remove_dir: [optional] boolean to remove empty parent directories
    :return: None"""
    import os
    from time import sleep
    count = 0
    while True:
        try:
            os.remove(_file_path)
            if _remove_dir:
                path_segments = os.path.split(_file_path)
                if len(path_segments) > 1:
                    file_folders = path_segments[0]
                    try:
                        os.removedirs(file_folders)
                    except:
                        pass
            break
        except PermissionError:
            sleep(0.05)
            count += 1
            if count > _retry_count:
                raise
    os._exit(0)

def connect_combo_data(instance, prop, widget):
    """Connect a callback property with a QComboBox widget based on the userData.

    Parameters
    ----------
    instance : object
        The class instance that the callback property is attached to
    prop : str
        The name of the callback property
    widget : QComboBox
        The combo box to connect.

    See Also
    --------
    connect_combo_text: connect a callback property with a QComboBox widget based on the text."""
    def update_widget(value):
        try:
            idx = _find_combo_data(widget, value)
        except ValueError:
            if value is None:
                idx = -1
            else:
                raise
        widget.setCurrentIndex(idx)
    def update_prop(idx):
        if idx == -1:
            setattr(instance, prop, None)
        else:
            setattr(instance, prop, widget.itemData(idx))
    add_callback(instance, prop, update_widget)
    widget.currentIndexChanged.connect(update_prop)
    update_widget(getattr(instance, prop))

