def normalize_args(f, *args, **kwargs):
    """Normalize call arguments into keyword form and varargs.

    args can only be non-empty if there is *args in the argument specification."""
    callargs = inspect.getcallargs(f, *args, **kwargs)
    original_callargs = callargs.copy()
    try:
        argspec = inspect.getargspec(f)
    except ValueError:
        argspec = inspect.getfullargspec(f)
    else:
        argspec = fullargspec_from_argspec(argspec)
    if hasattr(argspec, 'varkw'):
        if argspec.varkw:
            kwargs = callargs.pop(argspec.varkw, {})
            callargs.update(kwargs)
    if argspec.varargs:
        varargs = callargs.pop(argspec.varargs, ())
    else:
        varargs = ()
    return NormalizedArgs(varargs=varargs, normargs=callargs, callargs=original_callargs)

def ga_context(context_func):
    """A decorator for Cornice views that allows one to set extra parameters
    for Google Analytics tracking::

        @ga_context(lambda context: {'dt': context['category'].title, })
        @view_config(route_name='page')
        def view(request):
            return {
                'category': self.workspace.S(Category).filter(title='foo')[0],
            }

    :param func context_func:
        A function which takes one argument, a context dictionary made
        available to the template.
    :returns:
        A dict containing the extra variables for Google Analytics
        tracking."""
    def decorator(func):
        @wraps(func)
        def wrapper(self, *args, **kwargs):
            context = func(self, *args, **kwargs)
            self.request.google_analytics.update(context_func(context))
            return context
        return wrapper
    return decorator

def cst_now():
    """    This will return a datetime of utcnow - 6 hours for
        Central Standard Time
    :return: Datetime"""
    try:
        ret = datetime.utcnow() + timedelta(hours=DEFAULT_TIMEZONE)
        if DEFAULT_TIMEZONE_AWARE:
            ret = ret.replace(tzinfo=psycopg2.tz.FixedOffsetTimezone(name=None, offset=DEFAULT_TIMEZONE * 60))
        return ret
    except Exception as ex:
        return datetime.utcnow() + timedelta(hours=DEFAULT_TIMEZONE)

def today(date_time=None):
    """    This will return a datetime of cst_now - 5 hours with only
        Year, Month, and Day
    :return:  Datetime"""
    ret = date_time or cst_now()
    try:
        ret = datetime(year=ret.year, month=ret.month, day=ret.day)
        if DEFAULT_TIMEZONE_AWARE:
            ret = ret.replace(tzinfo=psycopg2.tz.FixedOffsetTimezone(name=None, offset=DEFAULT_TIMEZONE * 60))
    except Exception as ex:
        pass
    return ret

def str_to_datetime(timestamp, str_format='%Y-%m-%d_%H:%M:%S.fff'):
    """:param str_format:
    :param timestamp: str of the timestamp
    :return:          datetime"""
    date_time = datetime.strptime(timestamp.split('.')[0], str_format.split('.')[0])
    if '.' in timestamp:
        date_time += timedelta(seconds=eval('0.%s' % timestamp.split('.')[1]))
    if DEFAULT_TIMEZONE_AWARE:
        date_time = date_time.replace(tzinfo=psycopg2.tz.FixedOffsetTimezone(offset=DEFAULT_TIMEZONE * 60, name=None))
    return date_time

