def add_to_path(p):
    """Adds a path to python paths and removes it after the 'with' block ends"""
    old_path = sys.path
    if p not in sys.path:
        sys.path = sys.path[:]
        sys.path.insert(0, p)
    try:
        yield
    finally:
        sys.path = old_path

def find_file_regex(root_dir, re_expression, return_abs_path=True, search_sub_directories=True):
    """Finds all the files with the specified root directory with the name matching the regex expression.
    Args    :
        root_dir                : The root directory.
        re_expression           : The regex expression.
        return_abs_path         : If set to true, returns the absolute path of the files, else returns the name of the files.
        search_sub_directories  : If set to true, searches sub directories recursivly."""
    compiled = re.compile(re_expression)
    result = []
    for dirpath, dirnames, files in os.walk(root_dir):
        for file in files:
            if compiled.match(file):
                result.append(os.path.join(dirpath, file) if return_abs_path else file)
        if not search_sub_directories:
            break
    return result

def nested_join(array, o_str='{', c_str='}'):
    """Builds a string out of a given nested list.
    Args    :
        array   : An array retruned by pyparsing nestedExpr.
        o_str   : Opening str.
        c_str   : Closing str."""
    result = ''
    for x in array:
        if type(x) == type([]):
            result += o_str + nested_join(x) + c_str
        else:
            result += x
    return result

def createRepoObjects():
