def resolved_row(objs, geomatcher):
    """Temporarily insert ``RoW`` into ``geomatcher.topology``, defined by the topo faces not used in ``objs``.

    Will overwrite any existing ``RoW``.

    On exiting the context manager, ``RoW`` is deleted."""
    def get_locations(lst):
        for elem in lst:
            try:
                yield elem['location']
            except TypeError:
                yield elem
    geomatcher['RoW'] = geomatcher.faces.difference(reduce(set.union, [geomatcher[obj] for obj in get_locations(objs)]))
    yield geomatcher
    del geomatcher['RoW']

def body_class_tag(context):
    """Return CSS "class" attributes for <body>.

    Allows to provide a CSS namespace using urlpatterns namespace (as ``.ns-*``) and view name (as ``.vw-*``).

    Usage: ``{% body_class %}``
    Example: ``ns-my-app vw-my-view`` or ``ns-contacts vw-list``
    Requires: ``apps.core.middlewares.CoreMiddleware``."""
    request = context.get('request')
    if not hasattr(request, 'ROUTE'):
        return ''
    css_classes = []
    namespace = request.ROUTE['namespace']
    if namespace:
        namespace = RE_CLEAN_CSS_NAME.sub('-', namespace.lower())
        css_classes.append('ns-{}'.format(namespace))
    view = request.ROUTE['url_name']
    if view:
        view = RE_CLEAN_CSS_NAME.sub('-', view.lower())
        css_classes.append('vw-{}'.format(view))
    return ' '.join(css_classes)

def static_absolute_tag(context, path):
