def get_value(row, field_name):
    """Returns the value found in the field_name attribute of the row dictionary."""
    result = None
    dict_row = convert_to_dict(row)
    if detect_list(field_name):
        temp = row
        for field in field_name:
            dict_temp = convert_to_dict(temp)
            temp = dict_temp.get(field, None)
        result = temp
    else:
        result = dict_row.get(field_name, None)
    return result

def select(table, index_track, field_name, op, value, includeMissing):
    """Modifies the table and index_track lists based on the comparison.
    """
    result = []
    result_index = []
    counter = 0
    for row in table:
        if detect_fields(field_name, convert_to_dict(row)):
            final_value = get_value(row, field_name)
            if do_op(final_value, op, value):
                result.append(row)
                result_index.append(index_track[counter])
        elif includeMissing:
            result.append(row)
            result_index.append(index_track[counter])
        counter += 1
    return (result, result_index)

def load(package, prefix, offset=0, limit=1000):
    """Load lines from the log file with pagination support."""
    logs = package.all(LogFile, unicode(prefix))
    logs = sorted(logs, key=lambda l: l.name, reverse=True)
    seen = 0
    record = None
    tmp = tempfile.NamedTemporaryFile(suffix='.log')
    for log in logs:
        shutil.copyfileobj(log.fh(), tmp)
        tmp.seek(0)
        for line in reversed(list(tmp)):
            seen += 1
            if seen < offset:
                continue
            if seen > limit:
                tmp.close()
                return
            try:
                d, mo, l, m = line.split(' %s ' % SEP, 4)
                if record is not None:
                    yield record
                record = {'time': d, 'module': mo, 'level': l, 'message': m}
            except ValueError:
                if record is not None:
                    record['message'] += '\n' + line
        tmp.seek(0)
    tmp.close()
    if record is not None:
        yield record

def _get_type(stype):
    """Get the python type for a given string describtion for a type.

    @param stype: The string representing the type to return
    @return: The python type if available"""
    stype = stype.lower()
    if stype == 'str':
        return str
    if stype == 'unicode':
        if PY2:
            return unicode
        else:
            return str
    if stype == 'int':
        return int
    if stype == 'float':
        return float
    if stype == 'bool':
        return bool
    raise AppConfigValueException('Unsuported type given: {0}'.format(stype))

def _format_message(value, line_length, indent='', first_indent=None):
    """Return a string with newlines so that the given string fits into this
    line length. At the start of the line the indent is added. This can
    be used for commenting the message out within a file or to indent your
    text.

    All \\t will be replaced with 4 spaces.

    @param value: The string to get as a commented multiline comment.
    @param line_length: The length of the line to fill.
    @param indent: The indent to use for printing or charcter to put in
            front
    @param first_indent: The first indent might be shorter. If None then
            the first line uses the normal indent as the rest of the
            string.

    @return: The string with newlines"""
    if indent.find('\t'):
        indent = indent.replace('\t', '    ')
    result = []
    if first_indent is None:
        first_indent = indent
    cindent = first_indent
    tmp = '*' * line_length
    for ele in value.split(' '):
        if ele.find('\t') >= 0:
            ele = ele.replace('\t', '    ')
        if len(ele) + len(tmp) >= line_length:
            result.append(tmp)
            tmp = '{0}{1}'.format(cindent, ele)
            cindent = indent
        else:
            tmp = '{0} {1}'.format(tmp, ele)
    result.append(tmp)
    result = result[1:]
    return '\n'.join(result)

def surround_previous_word(input_str):
    """Surround last word in string with parentheses. If last non-whitespace character
    is delimiter, do nothing"""
    start = None
    end = None
    for i, char in enumerate(reversed(input_str)):
        if start is None:
            if char in '{}()[]<>?|':
                return input_str
            elif char != ' ':
                start = i
        elif char in '{}()[]<>?| ':
            end = i
            break
    if start is None:
        return input_str
    if end is None:
        end = len(input_str)
    new_str = ''
    for i, char in enumerate(reversed(input_str)):
        if char == ' ' and i + 1 == start:
            continue
        if i == start:
            new_str += ') '
        elif i == end:
            new_str += '('
        new_str += char
    if end == len(input_str):
        new_str += '('
    return new_str[::-1]

