def get_number(message, limit=4):
    """convert Chinese to pinyin and extract useful numbers

    attention:
        1. only for integer
        2. before apply this method, the message should be preprocessed

    input:
        message: the message you want to extract numbers from.
        limit: limit the length of number sequence"""
    words = pinyin.get_pinyin(message).split('-')
    numbers = []
    tmp = ''
    count = 0
    for w in words:
        if re.search('\\W', w, re.A):
            for s in list(w):
                if s in special_char.keys():
                    count += 1
                    tmp += special_char[s]
                else:
                    if count >= limit:
                        numbers.append(tmp)
                    count = 0
                    tmp = ''
        elif w in pinyin2number.keys():
            count += 1
            tmp += pinyin2number[w]
        else:
            if count >= limit:
                numbers.append(tmp)
            count = 0
            tmp = ''
    if count >= limit:
        numbers.append(tmp)
    return numbers

def is_allowed(func):
    """Check user password, when is correct, then run decorated function.

    :returns: decorated function"""
    @wraps(func)
    def _is_allowed(user, *args, **kwargs):
        password = kwargs.pop('password', None)
        if user.check_password(password):
            return func(user, *args, **kwargs)
        else:
            raise NotAllowedError()
    sig = inspect.signature(func)
    parms = list(sig.parameters.values())
    parms.append(inspect.Parameter('password', inspect.Parameter.KEYWORD_ONLY, default=None))
    _is_allowed.__signature__ = sig.replace(parameters=parms)
    return _is_allowed

def globlookup(pattern, root):
    """globlookup finds filesystem objects whose relative path matches the
    given pattern.

    :param pattern: The pattern to wish to match relative filepaths to.
    :param root: The root director to search within."""
    for subdir, dirnames, filenames in os.walk(root):
        d = subdir[len(root) + 1:]
        files = (os.path.join(d, f) for f in filenames)
        for f in fnmatch.filter(files, pattern):
            yield f

def getname(obj):
    """Return the most qualified name of an object

    :param obj: object to fetch name
    :return: name of ``obj``"""
    for name_attribute in ('__qualname__', '__name__'):
        try:
            return getattr(obj, name_attribute, getattr(obj.__class__, name_attribute))
        except AttributeError:
            pass
    raise TypeError('object of type %r does not define a canonical name' % type(obj))

