def add_facets(engine_result, facet_features=None):
    """Adds facets to search results.

    Construct a new result payload with `facets` added as a new
    top-level property that carries a mapping from unicode strings to
    lists of content_ids.  The `facet_features` lists the names of
    :class:`~dossier.fc.StringCounter` features in each result
    :class:`~dossier.fc.FeatureCollection` to harvest phrases for the
    facets list.  If not specified, `facet_features` defaults to
    `bowNP_sip`.

    The remainder of the facet logic is handled in the UI."""
    if facet_features is None:
        facet_features = ['bowNP_sip']
    phrases = collections.defaultdict(list)
    for r in engine_result['results']:
        cid = r[0]
        fc = r[1]
        for fname in facet_features:
            for phrase in fc.get(u'bowNP_sip', []):
                phrases[phrase].append(cid)
    return dict(engine_result, **{'facets': dict(phrases)})

def labels_to_indexed_coref_values(content_objs, labels):
    """[(content_id, FeatureCollection)] -> [Label] -> [({-1,1}, i, j)]

    where 0 <= i, j < len(content_objs)."""
    cids_to_idx = {}
    for i, (content_id, _) in enumerate(content_objs):
        cids_to_idx[content_id] = i
    idx = lambda cid: cids_to_idx[cid]
    labs = []
    for lab in labels:
        if lab.content_id1 in cids_to_idx and lab.content_id2 in cids_to_idx:
            labs.append((lab.value.value, idx(lab.content_id1), idx(lab.content_id2)))
    return labs

def noun_phrases(text, included_unnormalized=False):
    """applies normalization to the terms found by noun_phrases_as_tokens
    and joins on '_'.

    :rtype: list of phrase strings with spaces replaced by ``_``."""
    lemmatizer = nltk.WordNetLemmatizer()
    stemmer = nltk.stem.porter.PorterStemmer()
    def normalize(word):
        """Normalises words to lowercase and stems and lemmatizes it."""
        word = word.lower()
        try:
            word = stemmer.stem_word(word)
            word = lemmatizer.lemmatize(word)
        except:
            pass
        return word
    normalizations = defaultdict(list)
    for terms in noun_phrases_as_tokens(text):
        key = u'_'.join(map(normalize, terms))
        normalizations[key].append(u' '.join(terms))
    if included_unnormalized:
        return (normalizations.keys(), normalizations)
    else:
        return normalizations.keys()

def schedule(demand: dict, alterations: set, looped: set=None, altered: set=None):
    """Prioritizes Triggers called from outside."""
    if looped is not None and len(demand) != len(looped):
        for func in looped:
            del demand[func]
    if keep_temp in demand:
        demand.pop(increase_temp, None)
        demand.pop(lower_temp, None)
    elif lower_temp in demand:
        demand.pop(increase_temp, None)
    return (demand, alterations)

def _load_types(root):
    """Returns {name: Type}"""
    def text(t):
        if t.tag == 'name':
            return '{name}'
        elif t.tag == 'apientry':
            return '{apientry}'
        out = []
        if t.text:
            out.append(_escape_tpl_str(t.text))
        for x in t:
            out.append(text(x))
            if x.tail:
                out.append(_escape_tpl_str(x.tail))
        return ''.join(out)
    out_dict = collections.OrderedDict()
    for elem in root.findall('types/type'):
        name = elem.get('name') or elem.find('name').text
        template = text(elem)
        api = elem.get('api')
        if 'requires' in elem.attrib:
            required_types = set((elem.attrib['requires'],))
        else:
            required_types = set()
        comment = elem.get('comment')
        if api:
            k = (name, api)
        else:
            k = (name, None)
        out_dict[k] = Type(name, template, required_types, api, comment)
    return out_dict

def _load_commands(root):
    """Returns {name: Command}"""
    def proto_text(t):
        if t.tag == 'name':
            return '{name}'
        elif t.tag == 'ptype':
            return '{type}'
        out = []
        if t.text:
            out.append(_escape_tpl_str(t.text))
        for x in t:
            out.append(proto_text(x))
            if x.tail:
                out.append(_escape_tpl_str(x.tail))
        return ''.join(out)
    out = collections.OrderedDict()
    for elem in root.findall('commands/command'):
        type_elem = elem.find('proto/ptype')
        name = elem.get('name') or elem.find('proto/name').text
        type = type_elem.text if type_elem is not None else None
        proto_template = proto_text(elem.find('proto'))
        params = [_load_param(x) for x in elem.findall('param')]
        comment = elem.get('comment')
        out[name] = Command(name, type, proto_template, params, comment)
    return out

def import_extension(dest, src, name, api=None, profile=None, filter_symbol=None):
    """Imports Extension `name`, and all its dependencies.

    :param Registry dest: Destination Registry
    :param Registry src: Source Registry
    :param str name: Name of Extension to import
    :param str api: Prefer to import types with API name `api`,
                or None to prefer Types with no API name.
    :type api: str
    :param filter_symbol: Optional symbol filter callable
    :type filter_symbol: Callable with signature
                         ``(symbol_type:str, symbol_name:str) -> bool``"""
    if filter_symbol is None:
        filter_symbol = _default_filter_symbol
    ext = src.extensions[name] if isinstance(name, str) else name
    for req in ext.get_requires(api, profile):
        for x in req.types:
            if not filter_symbol('type', x):
                continue
            import_type(dest, src, x, api, filter_symbol)
        for x in req.enums:
            if not filter_symbol('enum', x):
                continue
            import_enum(dest, src, x)
        for x in req.commands:
            if not filter_symbol('command', x):
                continue
            import_command(dest, src, x, api, filter_symbol)
    dest.extensions[name] = ext

def get_open_window_names():
    """Return a dict with open program names and their corresponding decimal ids"""
    raw_names = subprocess.check_output(['wmctrl', '-l']).decode('utf8').split('\n')
    split_names = [name.split() for name in raw_names if name]
    name_dict = {}
    for name in split_names:
        if not int(name[1]):
            name_dict[' '.join(name[3:]).lower()] = name[0]
    return name_dict

def generate_field_spec(row):
    """Generate a set of metadata for each field/column in
    the data. This is loosely based on jsontableschema."""
    names = set()
    fields = []
    for cell in row:
        name = column_alias(cell, names)
        field = {'name': name, 'title': cell.column, 'type': unicode(cell.type).lower(), 'has_nulls': False, 'has_empty': False, 'samples': []}
        if hasattr(cell.type, 'format'):
            field['type'] = 'date'
            field['format'] = cell.type.format
        fields.append(field)
    return fields

def random_sample(value, field, row, num=10):
    """Collect a random sample of the values in a particular
    field based on the reservoir sampling technique."""
    if value is None:
        field['has_nulls'] = True
        return
    if value in field['samples']:
        return
    if isinstance(value, basestring) and (not len(value.strip())):
        field['has_empty'] = True
        return
    if len(field['samples']) < num:
        field['samples'].append(value)
        return
    j = random.randint(0, row)
    if j < num - 1:
        field['samples'][j] = value

def make_unique_ngrams(s, n):
    """Make a set of unique n-grams from a string."""
    return set((s[i:i + n] for i in range(len(s) - n + 1)))

def analyze(fqdn, result, argl, argd):
    """Analyzes the result from calling the method with the specified FQDN.

    Args:
        fqdn (str): full-qualified name of the method that was called.
        result: result of calling the method with `fqdn`.
        argl (tuple): positional arguments passed to the method call.
        argd (dict): keyword arguments passed to the method call."""
    package = fqdn.split('.')[0]
    if package not in _methods:
        _load_methods(package)
    if _methods[package] is not None and fqdn in _methods[package]:
        return _methods[package][fqdn](fqdn, result, *argl, **argd)

def typed_subtopic_data(fc, subid):
    """Returns typed subtopic data from an FC."""
    ty = subtopic_type(subid)
    data = get_unicode_feature(fc, subid)
    assert isinstance(data, unicode), 'data should be `unicode` but is %r' % type(data)
    if ty == 'image':
        img_data = get_unicode_feature(fc, subid + '|data')
        img = re.sub('^data:image/[a-zA-Z]+;base64,', '', img_data)
        img = base64.b64decode(img.encode('utf-8'))
        return (data, img)
    elif ty in ('text', 'manual'):
        return data
    raise ValueError('unrecognized subtopic type "%s"' % ty)

def text(el, strip=True):
    """Return the text of a ``BeautifulSoup`` element"""
    if not el:
        return ''
    text = el.text
    if strip:
        text = text.strip()
    return text

def coursecode(el):
    """Return the text of a ``BeautifulSoup`` element, assuming it's a course code
    (it strips any square-brackets-surrounded number at its end)."""
    txt = text(el)
    return re.sub('\\s*\\[\\d+\\]$', '', txt, re.UNICODE)

def parse(el, typ):
    """Parse a ``BeautifulSoup`` element as the given type."""
    if not el:
        return typ()
    txt = text(el)
    if not txt:
        return typ()
    return typ(txt)

def parsebool(el):
    """Parse a ``BeautifulSoup`` element as a bool"""
    txt = text(el)
    up = txt.upper()
    if up == 'OUI':
        return True
    if up == 'NON':
        return False
    return bool(parseint(el))

def parse_options(arguments=None):
    """Reads command-line arguments

    >>> parse_options('--indent-comments')"""
    if arguments is None:
        arguments = sys.argv[1:]
    if isinstance(arguments, str):
        arguments = arguments.split()
    if isinstance(arguments, argparse.Namespace):
        return arguments
    parser = create_args_parser()
    args = parser.parse_args(arguments)
    args.dialect = args.dialect.lower()
    if args.dialect not in ['lisp', 'newlisp', 'clojure', 'scheme', 'all', '']:
        parser.error("`{0}' is not a recognized dialect".format(args.dialect))
    args.backup_dir = os.path.expanduser(args.backup_dir)
    if not os.path.exists(args.backup_dir):
        parser.error("Directory `{0}' does not exist".format(args.backup_dir))
    if len(args.files) > 1 and args.output_file:
        parser.error('Cannot use the -o flag when more than one file is specified')
    if not args.files:
        if args.modify and (not args.output_file):
            args.modify = False
        args.backup = False
        args.warning = False
    if args.output_diff:
        args.modify = False
    return args

def is_macro_name(func_name, dialect):
    """is_macro_name(func_name : str, dialect : str) -> bool

    >>> is_macro_name('yacc:define-parser')
    True

    Tests if a word is a macro using the language's/dialect's convention,
    e.g macros in Lisp usually start with 'def' and 'with' in Scheme. Saves
    the effort of finding all the macros in Lisp/Scheme/Clojure/newLISP and storing
    them in a list."""
    if not func_name:
        return False
    if dialect == 'lisp':
        return re.search('^(macro|def|do|with-)', func_name, re.I)
    if dialect == 'scheme':
        return re.search('^(call-|def|with-)', func_name)
    if dialect == 'clojure':
        return re.search('^(def|with)', func_name)
    if dialect == 'newlisp':
        return re.search('^(macro|def)', func_name)
    else:
        return False

def detabify(text, options):
    """tabify(text : str, options : argparse.Namespace|str) -> str

    Expands tabs"""
    opts = parse_options(options)
    if opts.tab_size < 1:
        return text.expandtabs(4)
    else:
        return text.expandtabs(options.tab_size)

def tabify(text, options):
    """tabify(text : str, options : argparse.Namespace|str) -> str

    >>> tabify('        (println "hello world")', '--tab=3')
     '            (println "hello world")'

    Replace spaces with tabs"""
    opts = parse_options(options)
    if opts.tab_size < 1:
        return text
    else:
        tab_equiv = ' ' * opts.tab_size
        return text.replace(tab_equiv, '\t')

def indent_line(zerolevel, bracket_list, line, in_comment, in_symbol_region, options=None):
    """indent_line(zerolevel : int, bracket_list : list, line : str, in_comment : bool,
                    in_symbol_region : bool, options : string|list)

    Most important function in the indentation process. It uses the bracket
    locations stored in the list to indent the line."""
    opts = parse_options(options)
    comment_line = re.search('^[ \t]*;', line, re.M)
    if opts.indent_comments:
        comment_line = False
    if not opts.compact and bracket_list == [] and (not in_comment):
        _line = detabify(line, opts)
        leading_spaces = re.search('^[ \t]+[^; )\n\r]', _line)
        if leading_spaces:
            zerolevel = leading_spaces.end() - 1
        else:
            zerolevel = 0
    if in_symbol_region:
        return (zerolevel, line, 0)
    elif not comment_line and (not all_whitespace(line)):
        curr_line, current_level = pad_leading_whitespace(line, zerolevel, bracket_list, opts)
        return (zerolevel, curr_line, current_level)
    else:
        return (zerolevel, line, 0)

def parse_rc_json():
    """Reads the json configuration file(.yasirc.json), parses it and returns the
    dictionary"""
    fname = '.yasirc.json'
    path = os.path.expanduser('~/' + fname)
    if os.path.exists(fname):
        path = os.path.abspath(fname)
    elif not os.path.exists(path):
        path = ''
    content = ''
    if path:
        with open(path) as f:
            content = f.read()
    ret = {}
    if content:
        ret = json.loads(content)
    return collections.defaultdict(dict, ret)

