        dic[i] = inum
    return dic

def _pop_from_list(bracket, lst, line, real_pos, offset, msg_stack):
    """_pop_from_list(char : str, lst : [str], line : str,
                        real_pos : int, offset : int)

    The function is called when a closing bracket is encountered. The function
    simply pops the last pushed item and issues a warning if an error is
    encountered."""
    if bracket == ']':
        correct_closer = '['
    elif bracket == ')':
        correct_closer = '('
    else:
        correct_closer = '{'
    if lst != []:
        popped = lst.pop()
        popped_char = popped['character']
        popped_pos = popped['line_number']
        popped_offset = popped['bracket_pos']
        if popped_char is not correct_closer:
            message = "Bracket `%s' does not match `%s' at (%d, %d)"
            message = message % (bracket, popped_char, popped_pos, popped_offset)
            warning_info = {'msg': message, 'line': line, 'column': real_pos}
            msg_stack.append(warning_info)
    else:
        message = "Unmatched closing bracket `%s'" % bracket
        warning_info = {'msg': message, 'line': line, 'column': offset + 1}
        msg_stack.append(warning_info)
    return lst

def colour_diff(diff_lines):
    """colour_diff(diff_lines : lst)

    Print diff text to terminal in color"""
    try:
        import colorama
    except ImportError:
        print(''.join(list(diff_lines)))
        return
    colorama.init()
    def p_green(text):
        """Print added line in green"""
        print(colorama.Fore.GREEN + text + colorama.Fore.WHITE, end='')
    def p_yellow(text):
        """Print diff section header in yellow"""
        print(colorama.Fore.YELLOW + text + colorama.Fore.WHITE, end='')
    def p_red(text):
        """Print removed line in red"""
        print(colorama.Fore.RED + text + colorama.Fore.WHITE, end='')
    section = re.compile('@@\\s+-\\d\\d,\\d\\d\\s\\+\\d\\d,\\d\\d\\s+@@')
    for line in diff_lines:
        if line.startswith('-'):
            p_red(line)
        elif line.startswith('+'):
            p_green(line)
        elif section.search(line):
            p_yellow(line)
        else:
            print(line, end='')

def indent_files(arguments):
    """indent_files(fname : str)

    1. Creates a backup of the source file(backup_source_file())
    2. Reads the files contents(read_file())
    3. Indents the code(indent_code())
    4. Writes the file or print the indented code(_after_indentation())"""
    opts = parse_options(arguments)
    if not opts.files:
        code = sys.stdin.read()
        indent_result = indent_code(code, opts)
        _after_indentation(indent_result)
    for fname in opts.files:
        code = read_file(fname)
        if not opts.dialect:
            if fname.endswith('.lisp'):
                opts.dialect = 'lisp'
            elif fname.endswith('.lsp'):
                opts.dialect = 'newlisp'
            elif re.search('.clj[sc]{0,1}$', fname):
                opts.dialect = 'clojure'
            elif fname.endswith('.ss') or fname.endswith('.scm'):
                opts.dialect = 'scheme'
            else:
                opts.dialect = 'all'
        indent_result = indent_code(code, opts)
        if opts.backup:
            backup_source_file(fname, opts)
        _after_indentation(indent_result, fpath=fname)

def preserve_builtin_query_params(url, request=None):
    """Given an incoming request, and an outgoing URL representation,
    append the value of any built-in query parameters."""
    if request is None:
        return url
    overrides = [api_settings.URL_FORMAT_OVERRIDE]
    for param in overrides:
        if param and param in request.GET:
            value = request.GET[param]
            url = replace_query_param(url, param, value)
    return url

def reverse(viewname, args=None, kwargs=None, request=None, format=None, **extra):
    """If versioning is being used then we pass any `reverse` calls through
    to the versioning scheme instance, so that the resulting URL
    can be modified if needed."""
    scheme = getattr(request, 'versioning_scheme', None)
    if scheme is not None:
        try:
            url = scheme.reverse(viewname, args, kwargs, request, format, **extra)
        except NoReverseMatch:
            url = _reverse(viewname, args, kwargs, request, format, **extra)
    else:
        url = _reverse(viewname, args, kwargs, request, format, **extra)
    return preserve_builtin_query_params(url, request)

def _reverse(viewname, args=None, kwargs=None, request=None, format=None, **extra):
    """Same as `django.core.urlresolvers.reverse`, but optionally takes a request
    and returns a fully qualified URL, using the request to get the base URL."""
    if format is not None:
        kwargs = kwargs or {}
        kwargs['format'] = format
    url = django_reverse(viewname, args=args, kwargs=kwargs, **extra)
    if request:
        return request.build_absolute_uri(url)
    return url

def getBindings(varList, startLevel=0):
    """Given a list of identifiers as strings, construct the dictonary of the identifiers as keys and the evaluated values of
    the ientifiers as the values. Ie something like {id:full_lookup(id) for id in identifiers}. full_lookup here is looking
    up the value of an identifier by looking at all the bindings at every level in the call stack.
    Return (bindings,unbound) where the bindings is the dictionary of found bindings and the set of unbound identifiers."""
    varsToFind = set(varList)
    bindings = {}
    frame = inspect.currentframe()
    try:
        for i in xrange(startLevel + 1):
            frame = frame.f_back
    except:
        raise Exception('bindings: startLevel {} is too high\n'.format(startLevel))
    while frame:
        frameLocals = frame.f_locals
        localKeys = set(varsToFind).intersection(frameLocals)
        for v in localKeys:
            bindings[v] = frameLocals[v]
        varsToFind -= localKeys
        if not varsToFind:
            return (bindings, varsToFind)
        frameGlobals = frame.f_globals
        globalKeys = set(varsToFind).intersection(frameGlobals)
        for v in globalKeys:
            bindings[v] = frameGlobals[v]
        varsToFind -= localKeys
        if not varsToFind:
            return (bindings, varsToFind)
        frame = frame.f_back
    return (bindings, varsToFind)

def _sorter(n1, n2):
    """_sorter(n1,n2) -> int
    Sorting predicate for non-NS attributes."""
    i = cmp(n1.namespaceURI, n2.namespaceURI)
    if i:
        return i
    return cmp(n1.localName, n2.localName)

def _utilized(n, node, other_attrs, unsuppressedPrefixes):
    """_utilized(n, node, other_attrs, unsuppressedPrefixes) -> boolean
    Return true if that nodespace is utilized within the node"""
    if n.startswith('xmlns:'):
        n = n[6:]
    elif n.startswith('xmlns'):
        n = n[5:]
    if n == '' and node.prefix in ['#default', None] or n == node.prefix or n in unsuppressedPrefixes:
        return 1
    for attr in other_attrs:
        if n == attr.prefix:
            return 1
    if unsuppressedPrefixes is not None:
        for attr in _attrs(node):
            if n == attr.prefix:
                return 1
    return 0

def _inclusiveNamespacePrefixes(node, context, unsuppressedPrefixes):
    """http://www.w3.org/TR/xml-exc-c14n/
    InclusiveNamespaces PrefixList parameter, which lists namespace prefixes that
    are handled in the manner described by the Canonical XML Recommendation"""
    inclusive = []
    if node.prefix:
        usedPrefixes = ['xmlns:%s' % node.prefix]
    else:
        usedPrefixes = ['xmlns']
    for a in _attrs(node):
        if a.nodeName.startswith('xmlns') or not a.prefix:
            continue
        usedPrefixes.append('xmlns:%s' % a.prefix)
    unused_namespace_dict = {}
    for attr in context:
        n = attr.nodeName
        if n in unsuppressedPrefixes:
            inclusive.append(attr)
        elif n.startswith('xmlns:') and n[6:] in unsuppressedPrefixes:
            inclusive.append(attr)
        elif n.startswith('xmlns') and n[5:] in unsuppressedPrefixes:
            inclusive.append(attr)
        elif attr.nodeName in usedPrefixes:
            inclusive.append(attr)
        elif n.startswith('xmlns:'):
            unused_namespace_dict[n] = attr.value
    return (inclusive, unused_namespace_dict)

def str_to_bool(val):
    """Return a boolean if the string value represents one

    :param val: str
    :return: bool
    :raise: ValueError"""
    if isinstance(val, bool):
        return val
    elif val.lower() == 'true':
        return True
    elif val.lower() == 'false':
        return False
    else:
        raise ValueError

def str_to_dt(val):
    """Return a datetime object if the string value represents one

    Epoch integer or an ISO 8601 compatible string is
    supported.

    :param val: str
    :return: datetime
    :raise: ValueError"""
    if isinstance(val, dt):
        return val
    try:
        if val.isdigit():
            return dt.utcfromtimestamp(float(val))
        else:
            return dt.strptime(val, '%Y-%m-%dT%H:%M:%S.%f')
    except (AttributeError, TypeError):
        raise ValueError

def check_ipv4(ip_str):
    """Return True if is a valid IP v4"""
    try:
        socket.inet_pton(socket.AF_INET, ip_str)
    except AttributeError:
        try:
            socket.inet_aton(ip_str)
        except socket.error:
            return False
        return ip_str.count('.') == 3
    except socket.error:
        return False
    return True

def get_old_options(cli, image):
    """Returns Dockerfile values for CMD and Entrypoint
    """
    return {'cmd': dockerapi.inspect_config(cli, image, 'Cmd'), 'entrypoint': dockerapi.inspect_config(cli, image, 'Entrypoint')}

def run_code_in_container(cli, image, code, mount, entrypoint):
    """Run `code` in a container, returning its ID
    """
    kwargs = {'image': image}
    if entrypoint:
        kwargs['entrypoint'] = '/bin/bash'
        kwargs['command'] = '-c {}'.format(quote(code))
    else:
        kwargs['command'] = '/bin/bash -c {}'.format(quote(code))
    if mount:
        binds = []
        volumes = []
        for m in mount:
            part = m.split(':')
            if len(part) == 3:
                pass
            elif len(part) == 2:
                part.append('rw')
            else:
                raise
            src, target, mode = part
            src = os.path.abspath(os.path.expanduser(src))
            binds.append('{}:{}:{}'.format(src, target, mode))
            volumes.append(target)
        kwargs['host_config'] = cli.create_host_config(binds=binds)
        kwargs['volumes'] = volumes
    container = cli.create_container(**kwargs)
    container_id = container['Id']
    cli.start(container=container_id)
    return container_id

def defer_reduce(func, items, test, accum=None):
    """Recursively reduce items by func, but only the items that do not cause test(items, accum) to return False.  Returns the reduced list (accum) and the list of remaining deferred items.
    """
    removals = []
    for k, item in enumerate(items):
        if test(item, accum):
            removals.append(k)
            if accum is None:
                accum = item
            else:
                accum = func(accum, item)
    deferred = indices_removed(items, removals)
    if deferred == items or not deferred:
        return (accum, deferred)
    return defer_reduce(func, deferred, test, accum)

def build_authorization_arg(authdict):
    """Create an "Authorization" header value from an authdict (created by generate_response())."""
    vallist = []
    for k in authdict.keys():
        vallist += ['%s=%s' % (k, authdict[k])]
    return 'Digest ' + ', '.join(vallist)

def multi_iter(iterable, count=2):
    """Return `count` independent, thread-safe iterators for `iterable`"""
    if not isinstance(iterable, (list, tuple, set, FutureChainResults, collections.Sequence, collections.Set, collections.Mapping, collections.MappingView)):
        iterable = SafeTee(iterable, n=count)
    return (iter(iterable) for _ in range(count))

