def make_path(*path_or_str_or_segments):
    """:param path_or_str_or_segments:
    :return:
    :rtype: cifparser.path.Path"""
    if len(path_or_str_or_segments) == 0:
        return ROOT_PATH
    elif len(path_or_str_or_segments) == 1:
        single_item = path_or_str_or_segments[0]
        if isinstance(single_item, Path):
            return single_item
        if isinstance(single_item, str):
            try:
                return path_parser.parseString(single_item, True).asList()[0]
            except:
                raise ValueError()
        raise TypeError()
    else:
        segments = path_or_str_or_segments
        return sum(map(lambda x: make_path(x), segments), ROOT_PATH)

def _import_packages(packages, optional=None):
    """Get actual package references from an iterable of package names
    :param packages: iterable of package names
    :type packages: iter of basestr
    :return: set of package references
    :rtype: set"""
    if not optional:
        optional = []
    package_references = set()
    failures = set()
    for package_name in packages:
        try:
            package_reference = __import__(package_name, globals(), locals(), [], 0)
            package_references.add(package_reference)
        except ImportError:
            failures.add(package_name)
    if failures:
        raise ImportError(u'Unable to find required packages: {0}'.format(u', '.join(failures)))
    failures = set()
    for package_name in optional:
        try:
            package_reference = __import__(package_name, globals(), locals(), [], 0)
            package_references.add(package_reference)
        except ImportError:
            failures.add(package_name)
    for failure in failures:
        warn(ImportWarning(u'Unable to import {0}'.format(failure)))
    return package_references

