def color(string, name, style='normal', when='auto'):
    """Change the color of the given string."""
    if name not in colors:
        from .text import oxford_comma
        raise ValueError("unknown color '{}'.\nknown colors are: {}".format(name, oxford_comma(["'{}'".format(x) for x in sorted(colors)])))
    if style not in styles:
        from .text import oxford_comma
        raise ValueError("unknown style '{}'.\nknown styles are: {}".format(style, oxford_comma(["'{}'".format(x) for x in sorted(styles)])))
    prefix = '\x1b[%d;%dm' % (styles[style], colors[name])
    suffix = '\x1b[%d;%dm' % (styles['normal'], colors['normal'])
    color_string = prefix + string + suffix
    if when == 'always':
        return color_string
    elif when == 'auto':
        return color_string if sys.stdout.isatty() else string
    elif when == 'never':
        return string
    else:
        raise ValueError("when must be one of: 'always', 'auto', 'never'")

def _import_modules(dir_path):
    """Attempts to import modules in the specified directory path.

    `dir_path`
        Base directory path to attempt to import modules."""
    def _import_module(module):
        """Imports the specified module.
        """
        if module in mods_loaded:
            return False
        __import__(module)
        mods_loaded.append(module)
    mods_loaded = []
    if not os.path.isdir(dir_path):
        return
    try:
        sys.path.insert(0, dir_path)
        for entry in os.listdir(dir_path):
            path = os.path.join(dir_path, entry)
            if os.path.isdir(path):
                _import_module(entry)
            elif _RE_PY_EXT.search(entry):
                if not _RE_INIT_PY.match(entry):
                    name = _RE_PY_EXT.sub('', entry)
                    _import_module(name)
    finally:
        sys.path.pop(0)

