    if s == '':
        return None
    startswith = [x for x in possibilities if x.lower().startswith(s.lower())]
    if len(startswith) == 1:
        return startswith[0]
    contained = [x for x in possibilities if s.lower() in x.lower()]
    if len(contained) == 1:
        return contained[0]
    best = max([(x, Levenshtein.jaro_winkler(s, x, 0.05)) for x in possibilities], key=itemgetter(1))
    if best[1] < threshold:
        return None
    return best[0]

def retry(exception_to_check, tries=5, delay=5, multiplier=2):
    """Tries to call the wrapped function again, after an incremental delay

    :param exception_to_check: Exception(s) to check for, before retrying.
    :type exception_to_check: Exception
    :param tries: Number of time to retry before failling.
    :type tries: int
    :param delay: time in second to sleep before retrying.
    :type delay: int
    :param multiplier: multiply the delay each time the exception_to_check
        occurs.
    :type multiplier: int"""
    def deco_retry(func):
        """Creates the retry decorator"""
        @wraps(func)
        def func_retry(*args, **kwargs):
            """Actual wrapped function"""
            if multiplier >= 1 is not True:
                raise ValueError('multiplier = {}. It has to be superior to 1.'.format(multiplier))
            mtries, mdelay = (tries, delay)
            while mtries > 1:
                try:
                    return func(*args, **kwargs)
                except exception_to_check as err:
                    message = '%s, retrying in %d seconds...' % (str(err), mdelay)
                    print(message)
                    sleep(mdelay)
                    mtries -= 1
                    mdelay *= multiplier
            return func(*args, **kwargs)
        return func_retry
    return deco_retry

def _mk_imp_override(srcname, replacement):
    """Create a simple one for one replacement for a module
    :param srcname: The source module name to replace
    :param replacement: The object which should act as the replacement"""
    class DummyImporter(object):
        def find_module(self, fullname, path):
            if fullname == srcname:
                return self
            return None
        def load_module(self, fullname):
            if fullname != srcname:
                raise ImportError
            sys.modules[fullname] = replacement
            return replacement
    obj = DummyImporter()
    sys.meta_path.append(obj)

def successfuly_encodes(msg, raise_err=False):
    """boolean response if a message contains correct information to serialize

    :param msg: <proto object>
    :param raise_err: <bool>
    :return: <bool>"""
    result = True
    try:
        msg.SerializeToString()
    except EncodeError as encode_error:
        if raise_err:
            raise encode_error
        result = False
    return result

def find_files(directory, pattern):
    """Recusively finds files in a directory re
    :param directory: base directory
    :param pattern: wildcard pattern
    :return: generator with filenames matching pattern"""
    for root, __, files in os.walk(directory):
        for basename in files:
            if fnmatch.fnmatch(basename, pattern):
                filename = os.path.join(root, basename)
                yield filename

def discover(url, options={}):
    """Retrieve the API definition from the given URL and construct
    a Patchboard to interface with it."""
    try:
        resp = requests.get(url, headers=Patchboard.default_headers)
    except Exception as e:
        raise PatchboardError('Problem discovering API: {0}'.format(e))
    try:
        api_spec = resp.json()
    except ValueError as e:
        raise PatchboardError('Unparseable API description: {0}'.format(e))
    return Patchboard(api_spec, options)

def load_value_from_schema(v):
    """Load a value from a schema defined string."""
    x = urllib.parse.urlparse(v)
    if x.scheme.lower() == 'decimal':
        v = Decimal(x.netloc)
    elif x.scheme.lower() in ['int', 'integer']:
        v = int(x.netloc)
    elif x.scheme.lower() == 'float':
        v = float(x.netloc)
    elif x.scheme.lower() in ['s', 'str', 'string']:
        v = str(x.netloc)
    elif x.scheme.lower() in ['u', 'unicode']:
        v = six.u(x.netloc)
    elif x.scheme.lower() == 'email':
        v = six.u(x.netloc)
    elif x.scheme.lower() == 'bool':
        v = bool(x.netloc)
    elif x.scheme.lower() in ['b', 'bytes']:
        v = six.b(x.netloc)
    elif x.scheme.lower() in ['ts.iso8601', 'timestamp.iso8601']:
        v = MayaDT.from_iso8601(x.netloc).datetime()
    elif x.scheme.lower() in ['ts.rfc2822', 'timestamp.rfc2822']:
        v = MayaDT.from_rfc2822(x.netloc).datetime()
    elif x.scheme.lower() in ['ts.rfc3339', 'timestamp.rfx3339']:
        v = MayaDT.from_rfc3339(x.netloc).datetime()
    elif x.scheme.lower() in ['ts', 'timestamp']:
        v = maya.parse(x.netloc).datetime()
    elif x.scheme.lower() == 'date':
        v = datetime.date.fromtimestamp(float(x.netloc))
    elif x.scheme.lower() == 'time':
        v = time.gmtime(float(x.netloc))
    else:
        v = None
    return v

def parse_value(v, parser, config, description):
    """Convert a string received on the command-line into
    a value or None.

    :param str v:
        The value to parse.
    :param parser:
        The fallback callable to load the value if loading
        from scheme fails.
    :param dict config:
        The config to use.
    :param str description:
        Description (for debugging)
    :return:
        The parsed value
    :rtype:
        object"""
    val = None
    if v == '':
        return
    if v is not None:
        try:
            val = load_value_from_schema(v)
        except Exception as e:
            six.raise_from(CertifierTypeError(message='{kind}'.format(description=description, kind=type(v).__name__), required=config['required'], value=v), e)
        else:
            if val is None:
                try:
                    return parser(v)
                except CertifierTypeError:
                    raise
                except CertifierValueError:
                    raise
                except TypeError as e:
                    six.raise_from(CertifierTypeError(message='{kind}'.format(description=description, kind=type(v).__name__), required=config['required'], value=v), e)
                except ValueError as e:
                    six.raise_from(CertifierValueError(message='{value}'.format(description=description, value=v), required=config['required'], value=v), e)
    return val

def _remove_unicode_keys(dictobj):
    """Convert keys from 'unicode' to 'str' type.

    workaround for <http://bugs.python.org/issue2646>"""
    if sys.version_info[:2] >= (3, 0):
        return dictobj
    assert isinstance(dictobj, dict)
    newdict = {}
    for key, value in dictobj.items():
        if type(key) is unicode:
            key = key.encode('utf-8')
        newdict[key] = value
    return newdict

def detect_circle(nodes):
    """Wrapper for recursive _detect_circle function"""
    if not isinstance(nodes, dict):
        raise TypeError('"nodes" must be a dictionary')
    dependencies = set(nodes.keys())
    traveled = []
    heads = _detect_circle(nodes, dependencies, traveled)
    return DependencyTree(heads)

def _detect_circle(nodes=None, dependencies=None, traveled=None, path=None):
    """Recursively iterate over nodes checking
    if we've traveled to that node before."""
    if nodes is None:
        nodes = {}
    elif not isinstance(nodes, dict):
        raise TypeError('"nodes" must be a dictionary')
    if dependencies is None:
        return
    elif not isinstance(dependencies, set):
        raise TypeError('"dependencies" must be a set')
    if traveled is None:
        traveled = []
    elif not isinstance(traveled, list):
        raise TypeError('"traveled" must be a list')
    if path is None:
        path = []
    if not dependencies:
        return []
    children = []
    for name in dependencies:
        new_path = list(path)
        new_path.append(name)
        if name in traveled:
            raise CircularDependencyException(new_path)
        node_children = _detect_circle(nodes=nodes, dependencies=nodes[name], traveled=traveled + list(name), path=new_path)
        node = DependencyNode(name)
        for child in node_children:
            child.parent = node
            node.add_child(child)
        children.append(node)
    return children

def next_redirect(request, fallback, **get_kwargs):
    """Handle the "where should I go next?" part of comment views.

    The next value could be a
    ``?next=...`` GET arg or the URL of a given view (``fallback``). See
    the view modules for examples.

    Returns an ``HttpResponseRedirect``."""
    next = request.POST.get('next')
    if not is_safe_url(url=next, allowed_hosts=request.get_host()):
        next = resolve_url(fallback)
    if get_kwargs:
        if '#' in next:
            tmp = next.rsplit('#', 1)
            next = tmp[0]
            anchor = '#' + tmp[1]
        else:
            anchor = ''
        joiner = '?' in next and '&' or '?'
        next += joiner + urlencode(get_kwargs) + anchor
    return HttpResponseRedirect(next)

