def generate_datasets_list(settings, argv):
    """generate datasets list to activate

    args:
        settings: dictionary
            from settings file
        argv: list
            from sys.argv"""
    datasets_string_list = settings['DATASETS_LIST']
    datasets_list = []
    if len(argv) == 2:
        try:
            datasets_items = datasets_string_list.iteritems()
        except AttributeError:
            datasets_items = datasets_string_list.items()
        for key, val in datasets_items:
            key_module = importlib.import_module(settings['PYTHON_MODULE'] + '.' + key)
            for element in val:
                datasets_list.append((key, element, getattr(key_module, element)()))
    elif len(argv) > 2:
        arguments = argv[2:]
        for argument in arguments:
            argument_list = argument.split('.')
            key = '.'.join(argument_list[:-1])
            key_module = importlib.import_module(settings['PYTHON_MODULE'] + '.' + key)
            datasets_list.append((key, argument_list[-1], getattr(key_module, argument_list[-1])()))
    else:
        print_help()
    return datasets_list

