def is_pathname_valid(pathname: str) -> bool:
    """Checks if the given path name is valid.

    Returns
    -------
    `True` if the passed pathname is a valid pathname for the current OS;
    `False` otherwise."""
    try:
        if not isinstance(pathname, str) or not pathname:
            return False
        _, pathname = os.path.splitdrive(pathname)
        root_dirname = os.environ.get('HOMEDRIVE', 'C:') if sys.platform == 'win32' else os.path.sep
        assert os.path.isdir(root_dirname)
        root_dirname = root_dirname.rstrip(os.path.sep) + os.path.sep
        for pathname_part in pathname.split(os.path.sep):
            try:
                os.lstat(root_dirname + pathname_part)
            except OSError as exc:
                if hasattr(exc, 'winerror'):
                    if exc.winerror == ERROR_INVALID_NAME:
                        return False
                elif exc.errno in {errno.ENAMETOOLONG, errno.ERANGE}:
                    return False
    except TypeError as exc:
        return False
    else:
        return True

def path_exists_or_creatable(pathname: str) -> bool:
    """Checks whether the given path exists or is creatable.

    This function is guaranteed to _never_ raise exceptions.

    Returns
    -------
    `True` if the passed pathname is a valid pathname for the current OS _and_
    either currently exists or is hypothetically creatable; `False` otherwise."""
    try:
        return is_pathname_valid(pathname) and (os.path.exists(pathname) or is_path_creatable(pathname))
    except OSError:
        return False

def path_exists_or_creatable_portable(pathname: str) -> bool:
    """OS-portable check for whether current path exists or is creatable.

    This function is guaranteed to _never_ raise exceptions.

    Returns
    ------
    `True` if the passed pathname is a valid pathname on the current OS _and_
    either currently exists or is hypothetically creatable in a cross-platform
    manner optimized for POSIX-unfriendly filesystems; `False` otherwise."""
    try:
        return is_pathname_valid(pathname) and (os.path.exists(pathname) or is_path_sibling_creatable(pathname))
    except OSError:
        return False

