def build_fault(cls, e, tb, include_traceback=False):
    """Builds a L{ErrorFault<pyamf.remoting.ErrorFault>} object based on the last
    exception raised.

    If include_traceback is C{False} then the traceback will not be added to
    the L{remoting.ErrorFault}."""
    if hasattr(cls, '_amf_code'):
        code = cls._amf_code
    else:
        code = cls.__name__
    details = None
    if include_traceback:
        details = traceback.format_exception(cls, e, tb)
    return remoting.ErrorFault(code=code, description=unicode(e), details=details)

def find_all_paths(G, start, end, path=[]):
    """Find all paths between vertices start and end in graph."""
    path = path + [start]
    if start == end:
        return [path]
    if start not in G.vertices:
        raise GraphInsertError("Vertex %s doesn't exist." % (start,))
    if end not in G.vertices:
        raise GraphInsertError("Vertex %s doesn't exist." % (end,))
    paths = []
    for vertex in G.vertices[start]:
        if vertex not in path:
            newpaths = find_all_paths(G, vertex, end, path)
            for newpath in newpaths:
                paths.append(newpath)
    return paths

def system_call(command):
    """Run a command and return stdout.

    Would be better to use subprocess.check_output, but this works on 2.6,
    which is still the system Python on CentOS 7."""
    p = subprocess.Popen([command], stdout=subprocess.PIPE, shell=True)
    return p.stdout.read()

def getattribute(value, arg):
    """Gets an attribute of an object dynamically from a string name"""
    if callable(getattr(value, arg)):
        return str(getattr(value, arg)())
    elif hasattr(value, str(arg)):
        return getattr(value, arg)
    elif hasattr(value, 'has_key') and value.has_key(arg):
        return value[arg]
    elif numeric_test.match(str(arg)) and len(value) > int(arg):
        return value[int(arg)]
    elif arg in dir(value):
        return getattr(value, arg)()
    else:
        return settings.TEMPLATE_STRING_IF_INVALID

def check_auth():
    """Check are we authorised
    :return: True if we authorised
        False if no auth provided
        exception if provided auth is wrong"""
    if get_oauth_token():
        auth_info = get_auth_info()
        if not auth_info:
            raise MissingTokenInfoException('Could not get token info')
        if datetime.now() >= auth_info['expires_at']:
            msg = ('Token is expired. Now %s but valid until %s', datetime.now(), auth_info['expires_at'])
            log.warn(msg[0], *msg[1:])
            raise TokenIsExpired(msg[0] % msg[1:])
    else:
        raise MissingTokenException()

def cidr_notation(ip_address, netmask):
    """Retrieve the cidr notation given an ip address and netmask.

    For example:

        cidr_notation('12.34.56.78', '255.255.255.248')

    Would return: 12.34.56.72/29

    @see http://terminalmage.net/2012/06/10/how-to-find-out-the-cidr-notation-for-a-subne-given-an-ip-and-netmask/
    @see http://www.aelius.com/njh/subnet_sheet.html"""
    try:
        inet_aton(ip_address)
    except:
        raise Exception("Invalid ip address '%s'" % ip_address)
    try:
        inet_aton(netmask)
    except:
        raise Exception("Invalid netmask '%s'" % netmask)
    ip_address_split = ip_address.split('.')
    netmask_split = netmask.split('.')
    net_start = [str(int(ip_address_split[x]) & int(netmask_split[x])) for x in range(0, 4)]
    return '.'.join(net_start) + '/' + get_net_size(netmask_split)

def unpack_archive(archive_format, archive_path, source_path):
    """Extract a .zip/.tar.gz archive to a folder."""
    if archive_format not in ('zip', 'tar'):
        raise ValueError('Unknown archive format "%s".' % archive_format)
    if archive_format == 'zip':
        with zipfile.ZipFile(archive_path) as archive:
            archive.extractall(source_path)
    if archive_format == 'tar':
        with tarfile.open(archive_path) as archive:
            archive.extractall(source_path)

def parse_netloc(scheme, netloc):
    """Parse netloc string."""
    auth, _netloc = netloc.split('@')
    sender, token = auth.split(':')
    if ':' in _netloc:
        domain, port = _netloc.split(':')
        port = int(port)
    else:
        domain = _netloc
        if scheme == 'https':
            port = 443
        else:
            port = 80
    return dict(sender=sender, token=token, domain=domain, port=port)

