def job(func_or_queue, connection=None, *args, **kwargs):
    """This decorator does all what django_rq's one, plus
    it group all logged messages using uuid and sets
    job_name field as well."""
    decorated_func = _job(func_or_queue, *args, connection=connection, **kwargs)
    if callable(func_or_queue):
        @wraps(decorated_func)
        def wrapper(*args, **kwargs):
            with log.fields(uuid=uuid.uuid4(), job_name=decorated_func.__name__):
                return decorated_func(*args, **kwargs)
        return wrapper
    else:
        def decorator(func):
            @decorated_func
            @wraps(func)
            def wrapper(*args, **kwargs):
                with log.fields(uuid=uuid.uuid4(), job_name=func.__name__):
                    return func(*args, **kwargs)
            return wrapper
        return decorator

def do_truncate(parser, token):
    """Truncates given text (html-aware)
    Sample usage::

        {% truncate 60 %}
             {{ some_text }}
        {% more %}
             <a href="asdasd">Read more..</a>
        {% endtruncate %}"""
    _, count = token.split_contents()
    nodelist = parser.parse(('more', 'endtruncate'))
    token = parser.next_token()
    if token.contents == 'more':
        nodelist_more = parser.parse(('endtruncate',))
        parser.delete_first_token()
    else:
        nodelist_more = None
    return TruncateNode(count, nodelist, nodelist_more)

