def decompose_select(selectx):
    """return [(parent,setter) for scalar_subquery], wherex_including_on, NameIndexer. helper for run_select"""
    nix = NameIndexer.ctor_fromlist(selectx.tables)
    where = []
    for fromx in selectx.tables:
        if isinstance(fromx, sqparse2.JoinX) and fromx.on_stmt is not None:
            where.append(fromx.on_stmt)
    if selectx.where:
        where.append(selectx.where)
    return (nix, where)

def eval_where(where_list, composite_row, nix, tables_dict):
    """join-friendly whereclause evaluator. composite_row is a list or tuple of row lists. where_list is the thing from decompose_select."""
    evaluator = Evaluator(composite_row, nix, tables_dict)
    return all((evaluator.eval(w) for w in where_list))

def replace_subqueries(ex, tables, table_ctor):
    """this mutates passed in ex (any BaseX), replacing nested selects with their (flattened) output"""
    if isinstance(ex, sqparse2.SelectX):
        old_tables, ex.tables = (ex.tables, [])
    for path in treepath.sub_slots(ex, lambda x: isinstance(x, sqparse2.SelectX)):
        ex[path] = sqparse2.Literal(flatten_scalar(run_select(ex[path], tables, table_ctor)))
    if isinstance(ex, sqparse2.SelectX):
        ex.tables = old_tables
    return ex

def collapse_group_expr(groupx, cols, ret_row):
    """collapses columns matching the group expression. I'm sure this is buggy; look at a real DB's imp of this."""
    for i, col in enumerate(cols.children):
        if col == groupx:
            ret_row[i] = ret_row[i][0]
    return ret_row

def starlike(x):
    """weird things happen to cardinality when working with * in comma-lists. this detects when to do that."""
    return isinstance(x, sqparse2.AsterX) or (isinstance(x, sqparse2.AttrX) and isinstance(x.attr, sqparse2.AsterX))

def depth_first_sub(expr, values):
    """replace SubLit with literals in expr. (expr is mutated)."""
    arr = treepath.sub_slots(expr, lambda elt: elt is sqparse2.SubLit)
    if len(arr) != len(values):
        raise ValueError('len', len(arr), len(values))
    for path, val in zip(arr, values):
        if isinstance(val, (basestring, int, float, type(None), dict)):
            expr[path] = sqparse2.Literal(val)
        elif isinstance(val, (list, tuple)):
            expr[path] = sqparse2.ArrayLit(val)
        else:
            raise TypeError('unk_sub_type', type(val), val)
    return expr

def redirect_to_handler(error, location):
    """Cause a requset with an error to internally redirect to a URI path.

    This is generally for internal use, but can be called from within a Pecan
    controller to trigger a validation failure from *within* the controller
    itself, e.g.::

        @expose()
        @validate(some_schema, '/some/handler')
        def some_controller(self, **kw):
            if some_bad_condition():
                error_exception = ...
                redirect_to_handler(error_exception, '/some/handler')"""
    if callable(location):
        location = location()
    request.environ['REQUEST_METHOD'] = 'GET'
    redirect(location, internal=True)

def _parse(fileobj):
    """Parse fileobj for a shebang."""
    fileobj.seek(0)
    try:
        part = fileobj.read(2)
    except UnicodeDecodeError:
        part = ''
    if part == '#!':
        shebang = shlex.split(fileobj.readline().strip())
        if platform.system() == 'Windows' and len(shebang) and (os.path.basename(shebang[0]) == 'env'):
            return shebang[1:]
        return shebang
    return []

def parse(file_to_parse):
    """Check file_to_parse for a shebang and return its components.

    :file_to_parse: can be either a filename or an open file object.

    If file_to_parse's extension exists in PATHEXT then an empty list
    will be returned, as it is assumed that the operating system knows
    how to handle files of this type. All other files will be opened
    and read."""
    if hasattr(file_to_parse, 'read'):
        return _parse(file_to_parse)
    elif isinstance(file_to_parse, six.string_types):
        if 'PATHEXT' in os.environ:
            path_ext = os.environ['PATHEXT'].split(os.pathsep)
        else:
            path_ext = ()
        if os.path.splitext(file_to_parse)[1] in path_ext:
            return []
        with open(file_to_parse, 'r') as fileobj:
            return _parse(fileobj)
    raise RuntimeError('{} was not a file-like object.'.format(repr(file_to_parse)))

