def _normalize_params(image, width, height, crop):
    """Normalize params and calculate aspect."""
    if width is None and height is None:
        raise ValueError('Either width or height must be set. Otherwise resizing is useless.')
    if width is None or height is None:
        aspect = float(image.width) / float(image.height)
        if crop:
            raise ValueError('Cropping the image would be useless since only one dimention is give to resize along.')
        if width is None:
            width = int(round(height * aspect))
        else:
            height = int(round(width / aspect))
    return (width, height, crop)

def _get_resized_name(image, width, height, crop, namespace):
    """Get the name of the resized file when assumed it exists."""
    path, name = os.path.split(image.name)
    name_part = '%s/%ix%i' % (namespace, width, height)
    if crop:
        name_part += '_cropped'
    return os.path.join(path, name_part, name)

def resize(image, width=None, height=None, crop=False):
    """Resize an image and return the resized file."""
    width, height, crop = _normalize_params(image, width, height, crop)
    try:
        is_closed = image.closed
        if is_closed:
            image.open()
        resized_image = _resize(image, width, height, crop)
    finally:
        if is_closed:
            image.close()
    return ImageFile(resized_image)

def resize_lazy(image, width=None, height=None, crop=False, force=False, namespace='resized', storage=default_storage, as_url=False):
    """Returns the name of the resized file. Returns the url if as_url is True"""
    width, height, crop = _normalize_params(image, width, height, crop)
    name = _get_resized_name(image, width, height, crop, namespace)
    try:
        storage = image.storage
    except AttributeError:
        pass
    if force or not storage.exists(name):
        resized_image = None
        try:
            resized_image = resize(image, width, height, crop)
            name = storage.save(name, resized_image)
        finally:
            if resized_image is not None:
                resized_image.close()
    if as_url:
        return storage.url(name)
    return name

def resized(*args, **kwargs):
    """Auto file closing resize function"""
    resized_image = None
    try:
        resized_image = resize(*args, **kwargs)
        yield resized_image
    finally:
        if resized_image is not None:
            resized_image.close()

def get_package(repo_url, pkg_name, timeout=1):
    """Retrieve package information from a Bower registry at repo_url.

    Returns a dict of package data."""
    url = repo_url + '/packages/' + pkg_name
    headers = {'accept': 'application/json'}
    resp = requests.get(url, headers=headers, timeout=timeout)
    if resp.status_code == 404:
        return None
    return resp.json()

def filter_factory(global_conf, **local_conf):
    """Returns a WSGI filter app for use with paste.deploy."""
    conf = global_conf.copy()
    conf.update(local_conf)
    def block_resource(app):
        return DefaultIPPolicy(app, conf)
    return block_resource

def _comment_type_from_line(line):
    """Return the "comment header" (' * ', '# ', 'rem ', '// ', '/* ').

    This header goes before the content of a start of the
    line in a replacement."""
    regex = re.compile('^{0}'.format(_ALL_COMMENT))
    match = regex.match(line)
    if match:
        return '{0} '.format(line[match.start():match.end()])
    raise RuntimeError('Unable to find comment header for {0}'.format(line))

def _line_is_shebang(line):
    """Return true if line is a shebang."""
    regex = re.compile('^(#!|@echo off).*$')
    if regex.match(line):
        return True
    return False

def _filename_in_headerblock(relative_path, contents, linter_options):
    """Check for a filename in a header block.

    like such:
    # /path/to/filename"""
    del linter_options
    check_index = 0
    if len(contents) > 0:
        if _line_is_shebang(contents[0]):
            check_index = 1
    if len(contents) < check_index + 1:
        description = 'Document cannot have less than {0} lines'.format(check_index + 1)
        return LinterFailure(description, 1, replacement=None)
    header_path = relative_path.replace('\\', '/')
    regex = re.compile('^{0} \\/{1}$'.format(_HDR_COMMENT, re.escape(header_path)))
    if not regex.match(contents[check_index]):
        description = 'The filename /{0} must be the first line of the header'
        return LinterFailure(description.format(header_path), check_index + 1, _comment_type_from_line(contents[check_index]) + '/{0}\n'.format(header_path))

def _match_space_at_line(line):
    """Return a re.match object if an empty comment was found on line."""
    regex = re.compile('^{0}$'.format(_MDL_COMMENT))
    return regex.match(line)

def _space_in_headerblock(relative_path, contents, linter_options):
    """Check for space between the filename in a header block and description.

    like such:
    # /path/to/filename
    #
    # Description"""
    del relative_path
    del linter_options
    check_index = 1
    if len(contents) > 0:
        if _line_is_shebang(contents[0]):
            check_index = 2
    if len(contents) < check_index + 1:
        description = 'Document cannot have less than {0} lines'.format(check_index + 1)
        return LinterFailure(description, 1, replacement=None)
    candidate = contents[check_index]
    if not _match_space_at_line(candidate):
        description = 'The second line must be an empty comment'
        return LinterFailure(description, check_index + 1, _comment_type_from_line(candidate)[:-1] + '\n' + candidate)

def _find_last_line_index(contents):
    """Find the last line of the headerblock in contents."""
    lineno = 0
    headerblock = re.compile('^{0}.*$'.format(_ALL_COMMENT))
    if not len(contents):
        raise RuntimeError('File does not not have any contents')
    while headerblock.match(contents[lineno]):
        if lineno + 1 == len(contents):
            raise RuntimeError('No end of headerblock in file')
        lineno = lineno + 1
    if lineno < 2:
        raise RuntimeError('Headerblock must have at least two lines')
    return lineno - 1

def _no_trailing_whitespace(relative_path, contents, linter_options):
    """Check that every file ends with a single \\n."""
    del relative_path
    del linter_options
    trailing_whitespace = re.compile('(?<![ \\t\\r\\n])[ \\t]+$')
    for index, line in enumerate(contents):
        for space in trailing_whitespace.finditer(line):
            assert space.end() == len(line) - 1
            return LinterFailure('Trailing whitespace', index + 1, line[:space.start()] + line[space.end():])

def _populate_spelling_error(word, suggestions, contents, line_offset, column_offset, message_start):
    """Create a LinterFailure for word.

    This function takes suggestions from :suggestions: and uses it to
    populate the message and candidate replacement. The replacement will
    be a line in :contents:, as determined by :line_offset: and
    :column_offset:."""
    error_line = contents[line_offset]
    if len(suggestions):
        char_word_offset = column_offset + len(word)
        replacement = error_line[:column_offset] + suggestions[0] + error_line[char_word_offset:]
    else:
        replacement = None
    if len(suggestions):
        suggestions_text = ', perhaps you meant ' + ' '.join(suggestions)
    else:
        suggestions_text = ''
    format_desc = message_start + suggestions_text
    return LinterFailure(format_desc, line_offset + 1, replacement)

def _find_spelling_errors_in_chunks(chunks, contents, valid_words_dictionary=None, technical_words_dictionary=None, user_dictionary_words=None):
    """For each chunk and a set of valid and technical words, find errors."""
    for chunk in chunks:
        for error in spellcheck_region(chunk.data, valid_words_dictionary, technical_words_dictionary, user_dictionary_words):
            col_offset = _determine_character_offset(error.line_offset, error.column_offset, chunk.column)
            msg = _SPELLCHECK_MESSAGES[error.error_type].format(error.word)
            yield _populate_spelling_error(error.word, error.suggestions, contents, error.line_offset + chunk.line, col_offset, msg)

def _maybe_log_technical_terms(global_options, tool_options):
    """Log technical terms as appropriate if the user requested it.

    As a side effect, if --log-technical-terms-to is passed to the linter
    then open up the file specified (or create it) and then merge the set
    of technical words that we have now with the technical words already
    in it."""
    log_technical_terms_to_path = global_options.get('log_technical_terms_to', None)
    log_technical_terms_to_queue = tool_options.get('log_technical_terms_to', None)
    if log_technical_terms_to_path:
        assert log_technical_terms_to_queue is not None
        try:
            os.makedirs(os.path.dirname(log_technical_terms_to_path))
        except OSError as error:
            if error.errno != errno.EEXIST:
                raise error
        if not log_technical_terms_to_queue.empty():
            with closing(os.fdopen(os.open(log_technical_terms_to_path, os.O_RDWR | os.O_CREAT), 'r+')) as terms_file:
                terms = set(terms_file.read().splitlines())
                new_terms = set(freduce(lambda x, y: x | y, _drain(log_technical_terms_to_queue)))
                if not terms.issuperset(new_terms):
                    terms_file.seek(0)
                    terms_file.truncate(0)
                    terms_file.write('\n'.join(list(terms | set(new_terms))))

def _error_is_suppressed(error, code, contents):
    """Return true if error is suppressed by an inline suppression."""
    if len(contents) == 0:
        return False
    if error.line > 1:
        above = contents[error.line - 2].split('#')
        if len(above) and _line_suppresses_error_code(above[-1].strip(), code):
            return True
    aside = contents[error.line - 1].split('#')
    if len(aside) and _line_suppresses_error_code(aside[-1].strip(), code):
        return True
    return False

def lint(relative_path_to_file, contents, linter_functions, **kwargs):
    """Actually lints some file contents.

    relative_path_to_file should contain the relative path to the file being
    linted from the root source directory. Contents should be a raw string
    with \\n's."""
    lines = contents.splitlines(True)
    errors = list()
    for code, info in linter_functions.items():
        error = info.function(relative_path_to_file, lines, kwargs)
        if error:
            if isinstance(error, list):
                errors.extend([(code, e) for e in error])
            else:
                errors.append((code, error))
    errors = [e for e in errors if not _error_is_suppressed(e[1], e[0], lines)]
    return sorted(errors, key=lambda e: e[1].line)

def linter_functions_from_filters(whitelist=None, blacklist=None):
    """Yield tuples of _LinterFunction matching whitelist but not blacklist."""
    def _keyvalue_pair_if(dictionary, condition):
        """Return a key-value pair in dictionary if condition matched."""
        return {k: v for k, v in dictionary.items() if condition(k)}
    def _check_list(check_list, cond):
        """Return function testing against a list if the list exists."""
        def _check_against_list(key):
            """Return true if list exists and condition passes."""
            return cond(check_list, key) if check_list is not None else True
        return _check_against_list
    linter_functions = LINTER_FUNCTIONS
    linter_functions = _keyvalue_pair_if(linter_functions, _check_list(whitelist, lambda l, k: k in l))
    linter_functions = _keyvalue_pair_if(linter_functions, _check_list(blacklist, lambda l, k: k not in l))
    for code, linter_function in linter_functions.items():
        yield (code, linter_function)

def _obtain_queue(num_jobs):
    """Return queue type most appropriate for runtime model.

    If we are using multiprocessing, that should be
    multiprocessing.Manager().Queue. If we are just using a
    single process, then use a normal queue type."""
    if _should_use_multiprocessing(num_jobs):
        return ReprQueue(multiprocessing.Manager().Queue())
    return ReprQueue(Queue())

def tool_options_from_global(global_options, num_jobs):
    """From an argparse namespace, get a dict of options for the tools."""
    internal_opt = ['whitelist', 'blacklist', 'fix_what_you_can']
    queue_object = _obtain_queue(num_jobs)
    translate = defaultdict(lambda: lambda x: x, log_technical_terms_to=lambda _: queue_object)
    tool_options = OrderedDict()
    for key in sorted(global_options.keys()):
        if key not in internal_opt and global_options[key] is not None:
            tool_options[key] = translate[key](global_options[key])
    return tool_options

def _run_lint_on_file(file_path, linter_functions, tool_options, fix_what_you_can):
    """Run each function in linter_functions on filename.

    If fix_what_you_can is specified, then the first error that has a
    possible replacement will be automatically fixed on this file."""
    with io.open(file_path, 'r+', encoding='utf-8') as found_file:
        file_contents = found_file.read()
        file_lines = file_contents.splitlines(True)
        try:
            errors = lint(file_path[len(os.getcwd()) + 1:], file_contents, linter_functions, **tool_options)
        except RuntimeError as err:
            msg = 'RuntimeError in processing {0} - {1}'.format(file_path, str(err))
            errors = [('polysquarelinter/failure', LinterFailure(msg, 0, None))]
        if fix_what_you_can:
            for error_index, error in enumerate(errors):
                if error[1].replacement is not None:
                    _apply_replacement(error, found_file, file_lines)
                    errors[error_index] = (error[0], LinterFailure(error[1].description + ' ... FIXED', error[1].line, error[1].replacement))
                    break
        return [FileLinterFailure(file_path, e) for e in errors]

def _run_lint_on_file_stamped_args(file_path, stamp_file_path, log_technical_terms_to, linter_functions, tool_options, fix_what_you_can):
    """Return tuple of args and kwargs that function would be called with."""
    dictionary_path = os.path.abspath('DICTIONARY')
    dependencies = [file_path]
    if os.path.exists(dictionary_path):
        dependencies.append(dictionary_path)
    kwargs = OrderedDict()
    kwargs['jobstamps_dependencies'] = dependencies
    kwargs['jobstamps_cache_output_directory'] = stamp_file_path
    if log_technical_terms_to:
        kwargs['jobstamps_output_files'] = [log_technical_terms_to]
    return ((file_path, linter_functions, tool_options, fix_what_you_can), kwargs)

def _run_lint_on_file_stamped(*args):
    """Run linter functions on file_path, stamping in stamp_file_path."""
    stamp_args, stamp_kwargs = _run_lint_on_file_stamped_args(*args, **{})
    return jobstamp.run(_run_lint_on_file_exceptions, *stamp_args, **stamp_kwargs)

def _ordered(generator, *args, **kwargs):
    """Sort keys of unordered_dict and store in OrderedDict."""
    unordered_dict = {k: v for k, v in generator(*args, **kwargs)}
    keys = sorted(list(dict(unordered_dict).keys()))
    result = OrderedDict()
    for key in keys:
        result[key] = unordered_dict[key]
    return result

def _any_would_run(func, filenames, *args):
    """True if a linter function would be called on any of filenames."""
    if os.environ.get('_POLYSQUARE_GENERIC_FILE_LINTER_NO_STAMPING', None):
        return True
    for filename in filenames:
        stamp_args, stamp_kwargs = _run_lint_on_file_stamped_args(filename, *args, **{})
        dependency = jobstamp.out_of_date(func, *stamp_args, **stamp_kwargs)
        if dependency:
            return True
    return False

def main(arguments=None):
    """Entry point for the linter."""
    result = _parse_arguments(arguments)
    linter_funcs = _ordered(linter_functions_from_filters, result.whitelist, result.blacklist)
    global_options = vars(result)
    tool_options = tool_options_from_global(global_options, len(result.files))
    any_would_run = _any_would_run(_run_lint_on_file_exceptions, result.files, result.stamp_file_path, result.log_technical_terms_to, linter_funcs, tool_options, result.fix_what_you_can)
    if any_would_run:
        for linter_function in linter_funcs.values():
            if linter_function.before_all:
                linter_function.before_all(global_options, tool_options)
        use_multiprocessing = _should_use_multiprocessing(len(result.files))
    else:
        use_multiprocessing = False
    if use_multiprocessing:
        mapper = parmap.map
    else:
        mapper = lambda f, i, *a: [f(*(x,) + a) for x in i]
    errors = list(itertools.chain(*mapper(_run_lint_on_file_stamped, result.files, result.stamp_file_path, result.log_technical_terms_to, linter_funcs, tool_options, result.fix_what_you_can)))
    for error in sorted(errors):
        _report_lint_error(error.failure, os.path.relpath(error.absolute_path))
    if any_would_run:
        for linter_funcs in linter_funcs.values():
            if linter_funcs.after_all:
                linter_funcs.after_all(global_options, tool_options)
    return len(errors)

def morph_dict(d, convert_function):
    """Convert a nested dictionary from one convention to another.
    Args:
        d (dict): dictionary (nested or not) to be converted.
        convert_function (func): function that takes the string in one
        convention and returns it in the other one.
    Returns:
        Dictionary with the new keys."""
    new = {}
    for k, v in six.iteritems(d):
        new_v = v
        if isinstance(v, dict):
            new_v = morph_dict(v, convert_function)
        elif isinstance(v, list):
            new_v = list()
            for x in v:
                new_v.append(morph_dict(x, convert_function))
        new[convert_function(k)] = new_v
    return new

def _translate(unistr, table):
    """Replace characters using a table."""
    if type(unistr) is str:
        try:
            unistr = unistr.decode('utf-8')
        except AttributeError:
            pass
    try:
        if type(unistr) is not unicode:
            return unistr
    except NameError:
        pass
    chars = []
    for c in unistr:
        replacement = table.get(c)
        chars.append(replacement if replacement else c)
    return u''.join(chars)

def sub_slots(x, match_fn, path=(), arr=None, match=False, recurse_into_matches=True):
    """given a BaseX in x, explore its ATTRS (doing the right thing for VARLEN).
    return a list of tree-paths (i.e. tuples) for tree children that match match_fn. The root elt won't match."""
    if arr is None:
        arr = []
    if match and match_fn(x):
        arr.append(path)
        if not recurse_into_matches:
            return arr
    if isinstance(x, PathTree):
        for attr in x.ATTRS:
            val = getattr(x, attr)
            if attr in x.VARLEN:
                for i, elt in enumerate(val or ()):
                    nextpath = path + ((attr, i),)
                    sub_slots(elt, match_fn, nextpath, arr, True, recurse_into_matches)
            else:
                nextpath = path + (attr,)
                sub_slots(val, match_fn, nextpath, arr, True, recurse_into_matches)
    return arr

def signup(request, **kwargs):
    """Overrides allauth.account.views.signup"""
    if not ALLAUTH:
        return http.HttpResponse(_('allauth not installed...'))
    if request.method == 'POST' and 'login' in request.POST:
        form_class = LoginForm
        form = form_class(request.POST)
        redirect_field_name = 'next'
        success_url = get_default_redirect(request, redirect_field_name)
        if form.is_valid():
            return form.login(request, redirect_url=success_url)
    response = allauth_signup(request, **kwargs)
    return response

def format_multiline(text, params={}, **kwargs):
    """Takes a list or multline text string and formats it.
        * multiline text strings get converted to a single line
        * list entries are joined by a carriage return
        * params are passed into the sting with a python format call

    args:
        text: list or string to format
        params: argments for formating the text

    kwargs:
        prepend: string to prepend to each line
        max_width: int of max width for a line
        indent: number of spaces to indent"""
    def format_kwargs(text, params={}, **kwargs):
        if params:
            if isinstance(params, dict):
                kwargs.update(params)
            else:
                kwargs = params
        try:
            return text.format(**kwargs)
        except (TypeError, IndexError):
            if isinstance(kwargs, str):
                return text.format(kwargs)
            else:
                return text.format(*kwargs)
    if isinstance(text, list):
        new_text = '\n'.join([format_max_width(format_kwargs(reduce_multiline(item), params, **kwargs), **kwargs) for item in text])
    else:
        new_text = format_max_width(format_kwargs(reduce_multiline(text), params, **kwargs), **kwargs)
    return new_text

def get_details(app_url=defaults.APP_URL):
    """returns environment details for the app url specified"""
    url = '%s/environment' % app_url
    response = requests.get(url)
    if response.status_code == 200:
        return response.json()
    else:
        raise JutException('Unable to retrieve environment details from %s, got %s: %s' % (url, response.status_code, response.text))

def make_wsgi_app(matching, not_found_app=not_found_app):
    """Making a WSGI application from Matching object
    registered other WSGI applications on each 'case' argument."""
    def wsgi_app(environ, start_response):
        environ['matcha.matching'] = matching
        try:
            matched_case, matched_dict = matching(environ)
        except NotMatched:
            return not_found_app(environ, start_response)
        else:
            environ['matcha.matched_dict'] = matched_dict
            return matched_case(environ, start_response)
    return wsgi_app

def nextversion(current_version):
    """Returns incremented module version number.

    :param current_version: version string to increment
    :returns:               Next version string (PEP 386 compatible) if possible.
                            If impossible (since `current_version` is too far from PEP 386),
                            `None` is returned."""
    norm_ver = verlib.suggest_normalized_version(current_version)
    if norm_ver is None:
        return None
    norm_ver = verlib.NormalizedVersion(norm_ver)
    parts = norm_ver.parts
    assert len(parts) == 3
    if len(parts[2]) > 1:
        if parts[2][-1] == 'f':
            parts = _mk_incremented_parts(parts, part_idx=2, in_part_idx=-2, incval=1)
        else:
            parts = _mk_incremented_parts(parts, part_idx=2, in_part_idx=-1, incval=1)
    elif len(parts[1]) > 1:
        parts = _mk_incremented_parts(parts, part_idx=1, in_part_idx=-1, incval=1)
    else:
        parts = _mk_incremented_parts(parts, part_idx=0, in_part_idx=-1, incval=1)
    norm_ver.parts = parts
    return str(norm_ver)

def normalize(url, strip=False):
    """RFC3986 normalize URL & Optionally removing url-query/fragment string"""
    if strip:
        p = _urltools.parse(url)
        url = p.scheme + '://' + p.subdomain + p.domain + p.path
    return _urltools.normalize(url)

def find_date(url):
    """Extract date from URL page if exists."""
    def _clean_split(div_str):
        sl = []
        for div in div_str.split('/'):
            div = div.strip().lower()
            if div != '':
                sl.append(div)
        return sl
    url_path = find_path(url)
    url_path_parts = _clean_split(url_path)
    date_parts = []
    for part in url_path_parts:
        try:
            _dateparse(part)
            date_parts.append(part)
        except ValueError:
            continue
    if len(date_parts) == 0:
        return
    date_str = '/'.join(date_parts)
    return _dateparse(date_str)

def method(value, arg):
    """Method attempts to see if the value has a specified method.

    Usage:

        {% load custom_filters %}
        {% if foo|method:"has_access" %}"""
    if hasattr(value, str(arg)):
        return getattr(value, str(arg))
    return '[%s has no method %s]' % (value, arg)

def read_yaml(file_path, Loader=yaml.Loader, object_pairs_hook=OrderedDict):
    """Read YAML file and return as python dictionary"""
    class OrderedLoader(Loader):
        pass
    def construct_mapping(loader, node):
        loader.flatten_mapping(node)
        return object_pairs_hook(loader.construct_pairs(node))
    OrderedLoader.add_constructor(yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG, construct_mapping)
    with open(file_path, 'r') as f:
        return yaml.load(f, OrderedLoader)

def write_yaml(data, out_path, Dumper=yaml.Dumper, **kwds):
    """Write python dictionary to YAML"""
    import errno
    import os
    class OrderedDumper(Dumper):
        pass
    def _dict_representer(dumper, data):
        return dumper.represent_mapping(yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG, data.items())
    OrderedDumper.add_representer(OrderedDict, _dict_representer)
    base_path, file_name = os.path.split(out_path)
    try:
        os.makedirs(base_path)
    except OSError as exc:
        if exc.errno == errno.EEXIST and os.path.isdir(base_path):
            pass
        else:
            raise
    with open(out_path, 'w') as f:
        return yaml.dump(data, f, OrderedDumper, default_flow_style=False, **kwds)

def join_state_collections(collection_a, collection_b):
    """Warning: This is a very naive join. Only use it when measures and groups will remain entirely within each subcollection.

    For example: if each collection has states grouped by date and both include the same date, then the new collection
        would have both of those groups, likely causing problems for group measures and potentially breaking many things."""
    return StateCollection(collection_a.states + collection_b.states, {grouping_name: _combined_grouping_values(grouping_name, collection_a, collection_b) for grouping_name in set(list(collection_a.groupings.keys()) + list(collection_b.groupings.keys()))})

def add_grouping(state_collection, grouping_name, loaded_processes, overriding_parameters=None):
    """Adds a grouping to a state collection by using the process selected by the grouping name

    Does not override existing groupings"""
    if grouping_name not in state_collection.groupings and loaded_processes != None and (loaded_processes['grouping_selector'].get(grouping_name) != None):
        state_collection = loaded_processes['grouping_selector'][grouping_name].process_function(state_collection, overriding_parameters)
    return state_collection

def add_group_to_grouping(state_collection, grouping_name, group, group_key=None):
    """Adds a group to the named grouping, with a given group key

    If no group key is given, the lowest available integer becomes the group key

    If no grouping exists by the given name a new one will be created

    Replaces any group with the same grouping_name and the same group_key"""
    if state_collection.groupings.get(grouping_name) is None:
        state_collection.groupings[grouping_name] = {}
    if group_key is None:
        group_key = _next_lowest_integer(state_collection.groupings[grouping_name].keys())
    state_collection.groupings[grouping_name][group_key] = group
    return state_collection

def _next_lowest_integer(group_keys):
    """returns the lowest available integer in a set of dict keys"""
    try:
        largest_int = max([int(val) for val in group_keys if _is_int(val)])
    except:
        largest_int = 0
    return largest_int + 1

