def parse_serialdiff(sd_dict):
    """helper for translate_check"""
    if isinstance(sd_dict, list):
        if len(sd_dict) != 2 or sd_dict[0] != 'checkstale':
            raise NotImplementedError(sd_dict[0], len(sd_dict))
        return CheckStale(sd_dict[1])
    if isinstance(sd_dict['deltas'], list):
        sd_dict['deltas'] = [diff.Delta(d['slice']['a'], d['slice']['b'], d['replace']) for d in sd_dict['deltas']]
    return SerialDiff(**sd_dict)

def translate_update(blob):
    """converts JSON parse output to self-aware objects"""
    return {translate_key(k): parse_serialdiff(v) for k, v in blob.items()}

def do_update(pool, request, models):
    """unlike *_check() below, update doesn't worry about missing children"""
    return {k: fkapply(models, pool, process_update, missing_update, k, v) for k, v in request.items()}

def process_check(pool, model, field, version):
    """helper for do_check. version is an integer or null. returns ..."""
    try:
        syncable = model[field]
    except pg.FieldError:
        return ['?field']
    if not isinstance(syncable, syncschema.Syncable):
        return ['here', None, syncable]
    if syncable.version() > version:
        return ['here', syncable.version(), syncable.generate()]
    elif syncable.version() == version:
        return ['ok', version]
    elif syncable.version() < version:
        return ['upload', syncable.version()]
    else:
        raise RuntimeError("shouldn't get here")

def merge_null_missing(request, name, field, pkeys):
    """helper for add_missing_children. sets k:None for the field for pkeys not already in request."""
    request.update({rk: None for rk in [FieldKey(name, pkey, field) for pkey in pkeys] if rk not in request})

def add_missing_children(models, request, include_children_for, modelgb):
    """helper for do_check. mutates request"""
    for (nombre, pkey), model in models.items():
        for modelclass, pkeys in model.refkeys(include_children_for.get(nombre, ())).items():
            childname = modelgb['row', modelclass].name
            for childfield, cftype in modelclass.FIELDS:
                if not isinstance(cftype, basestring) and inspect.isclass(cftype) and issubclass(cftype, syncschema.Syncable):
                    merge_null_missing(request, childname, childfield, pkeys)
                elif childfield in modelclass.SENDRAW:
                    merge_null_missing(request, childname, childfield, pkeys)
                else:
                    pass
    return request

def do_check(pool, request, models, include_children_for, modelgb):
    """request is the output of translate_check. models a dict of {(model_name,pkey_tuple):model}.  ICF is a {model_name:fields_list} for which we want to add nulls in request for missing children. see AMC for how it's used.  The caller should have gone through the same ICF logic when looking up models so the arg has all the refs the DB knows.  modelgb is misc.GetterBy<ModelInfo>, used by AMC for resolution."""
    add_missing_children(models, request, include_children_for, modelgb)
    return {k: fkapply(models, pool, process_check, None, k, v) for k, v in request.items()}

def R_rot(th):
    """Return a rotation matrix.

    Parameters
    ----------
    th: array, shape (n, m)
        Angles by which to rotate about each m rotational degree of freedom
        (m=1 in 2 dimensions, m=3 in 3 dimensions).

    Returns
    -------
    R: array, shape (n, m, m)"""
    try:
        dof = th.shape[-1]
    except AttributeError:
        dof = 1
        th = np.array([th])
    except IndexError:
        dof = 1
        th = np.array([th])
    if dof == 1:
        return R_rot_2d(th)
    elif dof == 3:
        return R_rot_3d(th)
    else:
        raise Exception('Rotation matrix not implemented in this dimension')

def as_multi_dict(d):
    """Coerce a dictionary to a bottle.MultiDict"""
    if isinstance(d, bottle.MultiDict):
        return d
    md = bottle.MultiDict()
    for k, v in d.iteritems():
        if isinstance(v, list):
            for x in v:
                md[k] = x
        else:
            md[k] = v
    return md

