def __get_resource(dao, url):
    """Issue a GET request to IASystem with the given url
    and return a response in Collection+json format.
    :returns: http response with content in json"""
    headers = {'Accept': 'application/vnd.collection+json'}
    response = dao.getURL(url, headers)
    status = response.status
    logger.debug('{} ==status==> {}'.format(url, status))
    if status != 200:
        message = str(response.data)
        if status == 404:
            return None
        if status == 400:
            if 'Term is out of range' in message:
                raise TermEvalNotCreated(url, status, message)
        raise DataFailureException(url, status, message)
    return json.loads(response.data)

def expr_to_str(n, l=None):
    """construct SQL string from expression node"""
    op = n[0]
    if op.startswith('_') and op.endswith('_'):
        op = op.strip('_')
        if op == 'var':
            return n[1]
        elif op == 'literal':
            if isinstance(n[1], basestring):
                return "'%s'" % n[1]
            return str(n[1])
        elif op == 'cast':
            return '(%s)::%s' % (expr_to_str(n[1]), n[2])
    elif op in '+-*/':
        return '(%s) %s (%s)' % (expr_to_str(n[1]), op, expr_to_str(n[2]))
    elif op == 'extract':
        return 'extract( %s from %s )' % (n[1], expr_to_str(n[2]))
    else:
        arg = ','.join(map(expr_to_str, n[1:]))
        return '%s(%s)' % (op, arg)

def get_vars(n):
    """extract variables from expression node
    defined by tuple-pair: (_var_, [variable name])"""
    op = n[0]
    if op.startswith('_') and op.endswith('_'):
        op = op.strip('_')
        if op == 'var':
            return [n[1]]
        return []
    else:
        ret = []
        for c in n[1:]:
            vs = get_vars(c)
            if vs:
                ret.extend(vs)
        return ret

def construct_func_expr(n):
    """construct the function expression"""
    op = n[0]
    if op.startswith('_') and op.endswith('_'):
        op = op.strip('_')
        if op == 'var':
            return Var(str(n[1]))
        elif op == 'literal':
            if isinstance(n[1], basestring):
                raise 'not implemented'
            return Constant(n[1])
        elif op == 'cast':
            raise 'not implemented'
    elif op in '+-/*':
        return ArithErrFunc(op, *map(construct_func_expr, n[1:]))
    else:
        klass = __agg2f__.get(op, None)
        if klass:
            return klass(map(construct_func_expr, n[1:]))
        raise 'no klass'

