def prim(G, start, weight='weight'):
    """Algorithm for finding a minimum spanning
    tree for a weighted undirected graph."""
    if len(connected_components(G)) != 1:
        raise GraphInsertError('Prim algorithm work with connected graph only')
    if start not in G.vertices:
        raise GraphInsertError("Vertex %s doesn't exist." % (start,))
    pred = {}
    key = {}
    pqueue = {}
    lowest = 0
    for edge in G.edges:
        if G.edges[edge][weight] > lowest:
            lowest = G.edges[edge][weight]
    for vertex in G.vertices:
        pred[vertex] = None
        key[vertex] = 2 * lowest
    key[start] = 0
    for vertex in G.vertices:
        pqueue[vertex] = key[vertex]
    while pqueue:
        current = popmin(pqueue, lowest)
        for neighbor in G.vertices[current]:
            if neighbor in pqueue and G.edges[current, neighbor][weight] < key[neighbor]:
                pred[neighbor] = current
                key[neighbor] = G.edges[current, neighbor][weight]
                pqueue[neighbor] = G.edges[current, neighbor][weight]
    return pred

def resolver(*for_resolve, attr_package='__package_for_resolve_deco__'):
    """Resolve dotted names in function arguments

    Usage:

        >>> @resolver('obj')
        >>> def func(param, obj):
        >>>     assert isinstance(param, str)
        >>>     assert not isinstance(obj, str)
        >>>
        >>> func('os.path', 'sys.exit')"""
    def decorator(func):
        spec = inspect.getargspec(func).args
        if set(for_resolve) - set(spec):
            raise ValueError('bad arguments')
        @wraps(func)
        def wrapper(*args, **kwargs):
            args = list(args)
            if args and attr_package:
                package = getattr(args[0], attr_package, None)
            else:
                package = None
            for item in for_resolve:
                n = spec.index(item)
                if n >= len(args):
                    continue
                if n is not None and isinstance(args[n], str):
                    args[n] = resolve(args[n], package)
            for kw, value in kwargs.copy().items():
                if kw in for_resolve and isinstance(value, str):
                    kwargs[kw] = resolve(value, package)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def register_view(design_doc, full_set=True):
    """Model document decorator to register its design document view::

        @register_view('dev_books')
        class Book(Document):
            __bucket_name__ = 'mybucket'
            doc_type = 'book'
            structure = {
                # snip snip
            }

    :param design_doc: The name of the design document.
    :type design_doc: basestring
    :param full_set: Attach full_set param to development views.
    :type full_set: bool"""
    def _injector(doc):
        if not isinstance(doc, type) or not issubclass(doc, Document):
            raise TypeError("Class must be a cbwrapper 'Document' subclass.")
        doc.__view_name__ = design_doc
        doc.full_set = full_set
        ViewSync._documents.add(doc)
        return doc
    return _injector

def relateObjectLocs(obj, entities, selectF):
    """calculate the minimum distance to reach any iterable of entities with a loc"""
    try:
        obj = obj.loc
    except AttributeError:
        pass
    try:
        func = obj.direct2dDistance
    except AttributeError:
        raise ValueError('object %s (%s) does not possess and is not a %s' % (obj, type(obj), MapPoint))
    try:
        return selectF([(func(b.loc), b) for b in entities])
    except AttributeError:
        return selectF([(func(b), b) for b in entities])

def gridSnap(point, grid=1.0):
    """cause the given point to snap to nearest X/Y grid point"""
    def snapFunc(value):
        value += 1e-06
        remainder = value % grid
        value -= remainder
        newAdd = round(remainder / grid) * grid
        return value + newAdd
    return MapPoint(snapFunc(point.x), snapFunc(point.y))

def convertToMapPic(byteString, mapWidth):
    """convert a bytestring into a 2D row x column array, representing an existing map of fog-of-war, creep, etc."""
    data = []
    line = ''
    for idx, char in enumerate(byteString):
        line += str(ord(char))
        if (idx + 1) % mapWidth == 0:
            data.append(line)
            line = ''
    return data

def Dumper(obj, indent=0, increase=4, encoding='utf-8'):
    """appropriately view a given dict/list/tuple/object data structure"""
    def p(given):
        """ensure proper decoding from unicode, if necessary"""
        if isinstance(given, str):
            return given.encode(encoding)
        else:
            return given
    try:
        if isinstance(obj, dict):
            for k, v in obj.items():
                if hasattr(v, '__iter__'):
                    print('%s%s' % (' ' * indent, p(k)))
                    Dumper(v, indent=indent + increase, increase=increase)
                else:
                    print('%s%s=%s' % (' ' * indent, p(k), p(v)))
        elif isinstance(obj, list):
            for o in obj:
                Dumper(o, indent=indent, increase=increase)
        elif isinstance(obj, tuple):
            print('%s%s' % (' ' * indent, p(obj[0])))
            next = list(obj)[1:]
            if len(next) == 1:
                next = next[0]
            else:
                next = tuple(next)
            Dumper(next, indent=indent + increase, increase=increase)
        elif isinstance(obj, str):
            print('%s%s' % (' ' * indent, p(obj)))
        elif obj != None:
            print('%s%s' % (' ' * indent, p(obj)))
    except Exception:
        print(type(obj), obj)

def quadraticEval(a, b, c, x):
    """given all params return the result of quadratic equation a*x^2 + b*x + c"""
    return a * x ** 2 + b * x + c

def quadraticSolver(a, b, c):
    """return solution(s) for x, to the quadratic equation a*x^2 + b*x + c
    when it equals zero using the quadratic formula"""
    if a == 0:
        if b == 0:
            return []
        else:
            return [-c / float(b)]
    else:
        d = b ** 2.0 - 4 * a * c
        if d < 0:
            return []
        solvedPart0 = 1 / (2.0 * a)
        solvedPart1 = -b * solvedPart0
        if d == 0:
            return [solvedPart1]
        else:
            solvedPart2 = math.sqrt(d) * solvedPart0
            return [solvedPart1 + solvedPart2, solvedPart1 - solvedPart2]

def get_version(*file_paths):
    """Retrieves the version from path"""
    filename = os.path.join(os.path.dirname(__file__), *file_paths)
    print('Looking for version in: {}'.format(filename))
    version_file = open(filename).read()
    version_match = re.search('^__version__ = [\'\\"]([^\'\\"]*)[\'\\"]', version_file, re.M)
    if version_match:
        return version_match.group(1)
    raise RuntimeError('Unable to find version string.')

def resolve_str(name_or_func, module, default):
    """Resolve and return object from dotted name
    """
    assert isinstance(name_or_func, str)
    resolved = resolve(name_or_func, module=module)
    if isinstance(resolved, ModuleType):
        if not hasattr(resolved, default):
            raise ImportError('{}.{}'.format(resolved.__name__, default))
        resolved = getattr(resolved, default)
    if not callable(resolved):
        raise TypeError('{!r} is not callable'.format(resolved))
    return resolved

def include(_name_or_func, *args, _module=None, _default='includeme', **kwargs):
    """Resolve and call functions
    """
    if callable(_name_or_func):
        resolved = _name_or_func
    else:
        resolved = resolve_str(_name_or_func, _module, _default)
    resolved(*args, **kwargs)

