def open_conn(host, db, user, password, retries=0, sleep=0.5):
    """Return an open mysql db connection using the given credentials.  Use
    `retries` and `sleep` to be robust to the occassional transient connection
    failure.

    retries: if an exception when getting the connection, try again at most this many times.
    sleep: pause between retries for this many seconds.  a float >= 0."""
    assert retries >= 0
    try:
        return MySQLdb.connect(host=host, user=user, passwd=password, db=db)
    except Exception:
        if retries > 0:
            time.sleep(sleep)
            return open_conn(host, db, user, password, retries - 1, sleep)
        else:
            raise

def open_url(url, retries=0, sleep=0.5):
    '''Open a mysql connection to a url.  Note that if your password has
    punctuation characters, it might break the parsing of url.

    url: A string in the form "mysql://username:password@host.domain/database"'''
    return open_conn(retries=retries, sleep=sleep, **parse_url(url))

def doTransaction(conn, start=True, startSQL='START TRANSACTION'):
    """wrap a connection in a transaction.  starts a transaction, yields the conn, and then if an exception occurs, calls rollback().  otherwise calls commit().
    start: if True, executes 'START TRANSACTION' sql before yielding conn.  Useful for connections that are autocommit by default.
    startSQL: override if 'START TRANSACTION' does not work for your db server."""
    try:
        if start:
            executeSQL(conn, startSQL)
        yield conn
    except:
        if conn is not None:
            conn.rollback()
        raise
    else:
        conn.commit()

def job_details(job_id, connection=None):
    """Returns the job data with its scheduled timestamp.

    :param job_id: the ID of the job to retrieve."""
    if connection is None:
        connection = r
    data = connection.hgetall(job_key(job_id))
    job_data = {'id': job_id, 'schedule_at': int(connection.zscore(REDIS_KEY, job_id))}
    for key, value in data.items():
        try:
            decoded = value.decode('utf-8')
        except UnicodeDecodeError:
            decoded = value
        if decoded.isdigit():
            decoded = int(decoded)
        job_data[key.decode('utf-8')] = decoded
    return job_data

def schedule_job(job_id, schedule_in, connection=None, **kwargs):
    """Schedules a job.

    :param job_id: unique identifier for this job
    :param schedule_in: number of seconds from now in which to schedule the
    job or timedelta object.

    :param **kwargs: parameters to attach to the job, key-value structure.

    >>> schedule_job('http://example.com/test', schedule_in=10, num_retries=10)"""
    if not isinstance(schedule_in, int):
        schedule_in = schedule_in.days * 3600 * 24 + schedule_in.seconds
    schedule_at = int(time.time()) + schedule_in
    if connection is None:
        connection = r
    if 'id' in kwargs:
        raise RuntimeError("'id' is a reserved key for the job ID")
    with connection.pipeline() as pipe:
        if schedule_at is not None:
            args = (schedule_at, job_id)
            if isinstance(connection, redis.Redis):
                args = (job_id, schedule_at)
            pipe.zadd(REDIS_KEY, *args)
        delete = []
        hmset = {}
        for key, value in kwargs.items():
            if value is None:
                delete.append(key)
            else:
                hmset[key] = value
        if hmset:
            pipe.hmset(job_key(job_id), hmset)
        if len(delete) > 0:
            pipe.hdel(job_key(job_id), *delete)
        pipe.execute()

def scheduled_jobs(with_times=False, connection=None):
    """Gets all jobs in the scheduler.

    :param with_times: whether to return tuples with (job_id, timestamp) or
    just job_id as a list of strings."""
    if connection is None:
        connection = r
    jobs = connection.zrangebyscore(REDIS_KEY, 0, sys.maxsize, withscores=with_times)
    for job in jobs:
        if with_times:
            yield (job[0].decode('utf-8'), job[1])
        else:
            yield job.decode('utf-8')

def app(environ, start_response):
    """Simple WSGI application. Returns 200 OK response with 'Hellow world!' in
    the body for GET requests. Returns 405 Method Not Allowed for all other
    methods.

    Returns 500 Internal Server Error if an exception is thrown. The response
    body will not include the error or any information about it. The error and
    its stack trace will be reported to FogBugz via BugzScout, though.

    :param environ: WSGI environ
    :param start_response: function that accepts status string and headers"""
    try:
        if environ['REQUEST_METHOD'] == 'GET':
            start_response('200 OK', [('content-type', 'text/html')])
            return ['Hellow world!']
        else:
            start_response('405 Method Not Allowed', [('content-type', 'text/html')])
            return ['']
    except Exception as ex:
        start_response('500 Internal Server Error', [('content-type', 'text/html')], sys.exc_info())
        return _handle_exc(ex)

def register_adapter(mod, func):
    """Registers a callable to be executed when a module is imported. If the
    module already exists then the callable will be executed immediately.
    You can register the same module multiple times, the callables will be
    executed in the order they were registered. The root module must exist
    (i.e. be importable) otherwise an `ImportError` will be thrown.

    @param mod: The fully qualified module string, as used in the imports
        statement. E.g. 'foo.bar.baz'. The string must map to a module
        otherwise the callable will not fire.
    @param func: The function to call when C{mod} is imported. This function
        must take one arg, the newly imported C{module} object.
    @type func: callable
    @raise TypeError: C{func} must be callable"""
    if not hasattr(func, '__call__'):
        raise TypeError('func must be callable')
    imports.when_imported(mod, func)

def render_field_errors(field):
    """Render field errors as html."""
    if field.errors:
        html = '<p class="help-block">Error: {errors}</p>'.format(errors='. '.join(field.errors))
