def download_file(fName, time, dire=pDir()):
    """download the required subtitle"""
    gen_hash = get_hash(fName, 64, dire)
    if gen_hash == -1:
        return -1
    user_agent = {'User-agent': 'SubDB/1.0 (sub/0.1; http://github.com/leosartaj/sub)'}
    param = {'action': 'download', 'hash': gen_hash, 'language': 'en'}
    try:
        r = requests.get('http://api.thesubdb.com/', headers=user_agent, params=param, timeout=time)
    except (requests.exceptions.Timeout, socket.error):
        return 'Timeout Error'
    if r.status_code != 200:
        return r.status_code
    fName, fExt = os.path.splitext(fName)
    fName += '.srt'
    fName = os.path.join(dire, fName)
    with open(fName, 'wb') as f:
        f.write(r.text.encode('ascii', 'ignore'))
    return r.status_code

def download(name, options):
    """download a file or all files in a directory"""
    dire = os.path.dirname(name)
    fName = os.path.basename(name)
    fNameOnly, fExt = os.path.splitext(fName)
    dwn = 0
    if fileExists(fName, dire) and (not fileExists(fNameOnly + '.srt', dire)):
        if file_downloaded(download_file(fName, options.timeout, dire), fName, options.verbose):
            dwn += 1
    elif dirExists(name):
        for filename in os.listdir(name):
            if options.recursive:
                dwn += download(os.path.join(name, filename), options)
            elif file_downloaded(download_file(filename, options.timeout, name), filename, options.verbose):
                dwn += 1
    return dwn

def NAND(*args, **kwargs):
    """ALL args must raise an exception when called overall.
    Raise the specified exception on failure OR the first exception.

    :params iterable[Certifier] args:
        The certifiers to call
    :param callable kwargs['exc']:
        Callable that excepts the unexpectedly raised exception as argument and return an
        exception to raise."""
    errors = []
    for arg in args:
        try:
            arg()
        except CertifierError as e:
            errors.append(e)
    if len(errors) != len(args) and len(args) > 1:
        exc = kwargs.get('exc', CertifierValueError('Expecting no certified values'))
        if exc is not None:
            raise exc

def XOR(a, b, exc=CertifierValueError('Expected at least one certified value')):
    """Only one arg must not raise a Certifier exception when called overall.
    Raise the specified exception on failure.

    :params Certifier a:
        The first certifiers to call
    :params Certifier b:
        The second certifiers to call
    :param Exception exc:
        Callable that is raised if XOR fails."""
    errors = []
    for certifier in [a, b]:
        try:
            certifier()
        except CertifierError as e:
            errors.append(e)
    if len(errors) != 1:
        if exc is not None:
            raise exc

def _patched_pep257():
    """Monkey-patch pep257 after imports to avoid info logging."""
    import pep257
    if getattr(pep257, 'log', None):
        def _dummy(*args, **kwargs):
            del args
            del kwargs
        old_log_info = pep257.log.info
        pep257.log.info = _dummy
    try:
        yield
    finally:
        if getattr(pep257, 'log', None):
            pep257.log.info = old_log_info

