def optional_arg_class_decorator(fn):
    """Based on:
    https://stackoverflow.com/questions/3888158/python-making-decorators-with-optional-arguments"""
    @functools.wraps(fn)
    def wrapped_decorator(*args, **kwargs):
        if len(args) == 1 and isinstance(args[0], type) and (not kwargs):
            return fn(args[0])
        else:
            def real_decorator(decoratee):
                return fn(decoratee, *args, **kwargs)
            return real_decorator
    return wrapped_decorator

def extant_item(arg, arg_type):
    """Determine if parser argument is an existing file or directory.

    This technique comes from http://stackoverflow.com/a/11541450/95592
    and from http://stackoverflow.com/a/11541495/95592

    Args:
        arg: parser argument containing filename to be checked
        arg_type: string of either "file" or "directory"

    Returns:
        If the file exists, return the filename or directory.

    Raises:
        If the file does not exist, raise a parser error."""
    if arg_type == 'file':
        if not os.path.isfile(arg):
            raise argparse.ArgumentError(None, 'The file {arg} does not exist.'.format(arg=arg))
        else:
            return arg
    elif arg_type == 'directory':
        if not os.path.isdir(arg):
            raise argparse.ArgumentError(None, 'The directory {arg} does not exist.'.format(arg=arg))
        else:
            return arg

def format_json(item, **kwargs):
    """formats a datatype object to a json value"""
    try:
        json.dumps(item.value)
        return item.value
    except TypeError:
        if 'time' in item.class_type.lower() or 'date' in item.class_type.lower():
            return item.value.isoformat()
        raise

def format_sparql(item, dt_format='turtle', **kwargs):
    """Formats a datatype value to a SPARQL representation

    args:
        item: the datatype object
        dt_format: the return format ['turtle', 'uri']"""
    try:
        rtn_val = json.dumps(item.value)
        rtn_val = item.value
    except:
        if 'time' in item.class_type.lower() or 'date' in item.class_type.lower():
            rtn_val = item.value.isoformat()
        else:
            rtn_val = str(item.value)
    if hasattr(item, 'datatype'):
        if hasattr(item, 'lang') and item.lang:
            rtn_val = '%s@%s' % (json.dumps(rtn_val), item.lang)
        else:
            dt = item.datatype
            if dt_format == 'uri':
                dt = item.datatype.sparql_uri
            if item.datatype in ['xsd_string', 'xsd_dateTime', 'xsd_time', 'xsd_date']:
                rtn_val = json.dumps(rtn_val)
            else:
                rtn_val = '"%s"' % json.dumps(rtn_val)
            rtn_val = '%s^^%s' % (rtn_val, dt.sparql)
    return rtn_val

def _get_stack_frame(stacklevel):
    """utility functions to get a stackframe, skipping internal frames."""
    stacklevel = stacklevel + 1
    if stacklevel <= 1 or _is_internal_frame(sys._getframe(1)):
        frame = sys._getframe(stacklevel)
    else:
        frame = sys._getframe(1)
        for x in range(stacklevel - 1):
            frame = _next_external_frame(frame)
            if frame is None:
                raise ValueError
    return frame

