def string_value(node):
    """Compute the string-value of a node."""
    if node.nodeType == node.DOCUMENT_NODE or node.nodeType == node.ELEMENT_NODE:
        s = u''
        for n in axes['descendant'](node):
            if n.nodeType == n.TEXT_NODE:
                s += n.data
        return s
    elif node.nodeType == node.ATTRIBUTE_NODE:
        return node.value
    elif node.nodeType == node.PROCESSING_INSTRUCTION_NODE or node.nodeType == node.COMMENT_NODE or node.nodeType == node.TEXT_NODE:
        return node.data

def string(v):
    """Convert a value to a string."""
    if nodesetp(v):
        if not v:
            return u''
        return string_value(v[0])
    elif numberp(v):
        if v == float('inf'):
            return u'Infinity'
        elif v == float('-inf'):
            return u'-Infinity'
        elif str(v) == 'nan':
            return u'NaN'
        elif int(v) == v and v <= 4294967295:
            v = int(v)
        return unicode(v)
    elif booleanp(v):
        return u'true' if v else u'false'
    return v

def boolean(v):
    """Convert a value to a boolean."""
    if nodesetp(v):
        return len(v) > 0
    elif numberp(v):
        if v == 0 or v != v:
            return False
        return True
    elif stringp(v):
        return v != ''
    return v

def number(v):
    """Convert a value to a number."""
    if nodesetp(v):
        v = string(v)
    try:
        return float(v)
    except ValueError:
        return float('NaN')

def numberp(v):
    """Return true iff 'v' is a number."""
    return not isinstance(v, bool) and (isinstance(v, int) or isinstance(v, float))

def make_url_args(params):
    """Utility function for constructing a URL query string from a dictionary
    of parameters.  The dictionary's values can be of various types: lists,
    tuples, dictionaries, strings, or None.

    :param dict params: the key-value pairs to construct a query string from
    :rtype: string"""
    p = []
    for key, value in params.iteritems():
        if isinstance(value, (list, tuple)):
            for v in value:
                p.append((key, v))
        elif isinstance(value, dict):
            for k, v in value.items():
                p.append(('%s[%s]' % (key, k), v))
        elif isinstance(value, bool):
            p.append((key, str(value).lower()))
        elif value is None:
            continue
        else:
            p.append((key, str(value)))
    return urllib.urlencode(p).encode('UTF-8')

def info(data, cols):
    """Compute min/max for all registered columns.

    Parameters
    ----------
    data : list
        List of points from tile.
    cols : list
        List of columns from tile header.

    Returns
    -------
    dict
        {
            column: {
                min: value,
                max: value
            }
        }"""
    stats = {c['name']: [] for c in cols}
    for point in data:
        for c, v in point.items():
            stats[c].append(v)
    return {n: {'min': min(v), 'max': max(v)} for n, v in stats.items()}

def main():
    """Get an info report for a tile.  Format is same as input tile but with
    min/max values for values under 'data'."""
    arguments = docopt(__doc__, version='tileinfo 0.1')
    src_name = arguments['SOURCE']
    src_format = arguments['--srcformat']
    indent = arguments['--indent']
    if isinstance(indent, str) and indent.lower() == 'none':
        indent = None
    elif isinstance(indent, str):
        indent = int(indent)
    else:
        indent = 4
    with sys.stdin if src_name in ('-', None) else open(src_name, 'rb') as f:
        if src_format is None:
            if '.json' == f.name[-5:]:
                src_format = 'json'
            else:
                src_format = 'tile'
        if src_format == 'tile':
            header, data = Tile(f.read()).unpack()
        else:
            header = json.loads(f.read())
            data = header.pop('data')
        report = info(data, header['cols'])
        out = {k: v for k, v in header.items() if k != 'data'}
        out['data'] = {}
        for field, vals in report.items():
            out['data'][field + '_min'] = vals['min']
            out['data'][field + '_max'] = vals['max']
        print(json.dumps(out, indent=indent, sort_keys=True))

def log_env_gte(desired):
    """Boolean check if the current environment LOGLEVEL is
    at least as verbose as a desired LOGLEVEL

    :param desired: <str> one of 9 keys in <brain.environment.stage>
    :return: <bool>"""
    return LOGLEVELS.get(check_log_env()) >= LOGLEVELS.get(desired, LOGLEVELS[TEST])

def copytree(src, dst, symlinks=False, ignore=None):
    """Copy from source directory to destination"""
    if not osp.exists(dst):
        os.makedirs(dst)
    for item in os.listdir(src):
        s = osp.join(src, item)
        d = osp.join(dst, item)
        if osp.isdir(s):
            shutil.copytree(s, d, symlinks, ignore)
        else:
            shutil.copy2(s, d)

def listdir_nohidden(path):
    """List not hidden files or directories under path"""
    for f in os.listdir(path):
        if isinstance(f, str):
            f = unicode(f, 'utf-8')
        if not f.startswith('.'):
            yield f

def fullqualname_py3(obj):
    """Fully qualified name for objects in Python 3."""
    if type(obj).__name__ == 'builtin_function_or_method':
        return _fullqualname_builtin_py3(obj)
    elif type(obj).__name__ == 'function':
        return _fullqualname_function_py3(obj)
    elif type(obj).__name__ in ['member_descriptor', 'method_descriptor', 'wrapper_descriptor']:
        return obj.__objclass__.__module__ + '.' + obj.__qualname__
    elif type(obj).__name__ == 'method':
        return _fullqualname_method_py3(obj)
    elif type(obj).__name__ == 'method-wrapper':
        return fullqualname_py3(obj.__self__) + '.' + obj.__name__
    elif type(obj).__name__ == 'module':
        return obj.__name__
    elif type(obj).__name__ == 'property':
        return obj.fget.__module__ + '.' + obj.fget.__qualname__
    elif inspect.isclass(obj):
        return obj.__module__ + '.' + obj.__qualname__
    return obj.__class__.__module__ + '.' + obj.__class__.__qualname__

def _fullqualname_builtin_py3(obj):
    """Fully qualified name for 'builtin_function_or_method' objects in
    Python 3."""
    if obj.__module__ is not None:
        module = obj.__module__
    elif inspect.isclass(obj.__self__):
        module = obj.__self__.__module__
    else:
        module = obj.__self__.__class__.__module__
    return module + '.' + obj.__qualname__

def _fullqualname_function_py3(obj):
    """Fully qualified name for 'function' objects in Python 3.
    """
    if hasattr(obj, '__wrapped__'):
        qualname = obj.__wrapped__.__qualname__
    else:
        qualname = obj.__qualname__
    return obj.__module__ + '.' + qualname

def _fullqualname_method_py3(obj):
    """Fully qualified name for 'method' objects in Python 3.
    """
    if inspect.isclass(obj.__self__):
        cls = obj.__self__.__qualname__
    else:
        cls = obj.__self__.__class__.__qualname__
    return obj.__self__.__module__ + '.' + cls + '.' + obj.__name__

def fullqualname_py2(obj):
    """Fully qualified name for objects in Python 2."""
    if type(obj).__name__ == 'builtin_function_or_method':
        return _fullqualname_builtin_py2(obj)
    elif type(obj).__name__ == 'function':
        return obj.__module__ + '.' + obj.__name__
    elif type(obj).__name__ in ['member_descriptor', 'method_descriptor', 'wrapper_descriptor']:
        return obj.__objclass__.__module__ + '.' + obj.__objclass__.__name__ + '.' + obj.__name__
    elif type(obj).__name__ == 'instancemethod':
        return _fullqualname_method_py2(obj)
    elif type(obj).__name__ == 'method-wrapper':
        return fullqualname_py2(obj.__self__) + '.' + obj.__name__
    elif type(obj).__name__ == 'module':
        return obj.__name__
    elif inspect.isclass(obj):
        return obj.__module__ + '.' + obj.__name__
    return obj.__class__.__module__ + '.' + obj.__class__.__name__

def _fullqualname_builtin_py2(obj):
    """Fully qualified name for 'builtin_function_or_method' objects
    in Python 2."""
    if obj.__self__ is None:
        module = obj.__module__
        qualname = obj.__name__
    else:
        if inspect.isclass(obj.__self__):
            cls = obj.__self__
        else:
            cls = obj.__self__.__class__
        module = cls.__module__
        qualname = cls.__name__ + '.' + obj.__name__
    return module + '.' + qualname

def _fullqualname_method_py2(obj):
    """Fully qualified name for 'instancemethod' objects in Python 2.
    """
    if obj.__self__ is None:
        module = obj.im_class.__module__
        cls = obj.im_class.__name__
    elif inspect.isclass(obj.__self__):
        module = obj.__self__.__module__
        cls = obj.__self__.__name__
    else:
        module = obj.__self__.__class__.__module__
        cls = obj.__self__.__class__.__name__
    return module + '.' + cls + '.' + obj.__func__.__name__

def find_packages(path: str) -> List[str]:
    """A better version of find_packages than what setuptools offers
    This function needs to be deterministic.
    :param path:
    :return:"""
    ret = []
    for root, _dir, files in os.walk(path):
        if '__init__.py' in files:
            ret.append(root.replace('/', '.'))
    return sorted(ret)

def login_required(method):
    """A decorator that control if a user is logged."""
    def wrapper(self, *arg, **karg):
        if not self.user:
            if self.request.method == 'GET':
                self.redirect(settings.LOGIN_PATH)
            else:
                self.error(403)
        else:
            method(self, *arg, **karg)
    return wrapper

