def group(merge_func, tokens):
    """Group together those of the tokens for which the merge function returns
    true. The merge function should accept two arguments/tokens and should
    return a boolean indicating whether the strings should be merged or not.

    Helper for tokenise(string, ..)."""
    output = []
    if tokens:
        output.append(tokens[0])
        for token in tokens[1:]:
            prev_token = output[-1]
            if merge_func(prev_token, token):
                output[-1] += token
            else:
                output.append(token)
    return output

def encode_value_using_ma(message_attribute: int, value: Optional[Union[int, float]]) -> int:
    """Encode special sensor value using the message attribute."""
    if message_attribute == MA_TX3AC_100A:
        if value is None:
            return 254
        return int(value)
    elif message_attribute == MA_TX3AC_10A:
        if value is None:
            return 254
        return int(value * 10)
    else:
        if value is None:
            return 128
        elif value < 0:
            return 256 + int(value)
        return int(value)

def find_libs():
    """Run through L{ETREE_MODULES} and find C{ElementTree} implementations so
    that any type can be encoded.

    We work through the C implementations first, then the pure Python versions.
    The downside to this is that B{all} libraries will be imported but I{only}
    one is ever used. The libs are small (relatively) and the flexibility that
    this gives seems to outweigh the cost. Time will tell."""
    from pyamf.util import get_module
    types = []
    mapping = {}
    for mod in ETREE_MODULES:
        try:
            etree = get_module(mod)
        except ImportError:
            continue
        t = _get_etree_type(etree)
        types.append(t)
        mapping[t] = etree
    return (tuple(types), mapping)

def tostring(element, *args, **kwargs):
    """Helper func to provide easy access to the (possibly) moving target that is
    C{ET}."""
    global modules
    _bootstrap()
    t = _get_type(element)
    etree = modules.get(t, None)
    if not etree:
        raise RuntimeError('Unable to find the etree implementation related to %r (type %r)' % (element, t))
    return etree.tostring(element, *args, **kwargs)

def partial_schema(schema, filtered_fields):
    """Validator for part of a schema, ignoring some fields

    :param schema: the Schema
    :param filtered_fields: fields to filter out"""
    return Schema({k: v for k, v in schema.schema.items() if getattr(k, 'schema', k) not in filtered_fields}, extra=ALLOW_EXTRA)

def validate_url(url):
    """Validate URL is valid

    NOTE: only support http & https"""
    schemes = ['http', 'https']
    netloc_re = re.compile('^(?:\\S+(?::\\S*)?@)?(?:[a-z0-9]|[a-z0-9][a-z0-9\\-]{0,61}[a-z0-9])(?:\\.(?:[a-z0-9]|[a-z0-9][a-z0-9\\-]{0,61}[a-z0-9]))*(?::[0-9]{2,5})?$', re.IGNORECASE)
    try:
        scheme, netloc, path, query, fragment = urlsplit(url)
    except ValueError:
        raise Invalid('Invalid URL')
    if scheme not in schemes:
        raise Invalid('Missing URL scheme')
    if not netloc_re.search(netloc):
        raise Invalid('Invalid URL')
    return url

def validate_reference_links(reference_links):
    """Vaidate reference links data structure

    Expected data structure:
        {
            "links": {
                id_type1: url1,
                id_type2: url2
            },
            "redirect_id_type": id_type1 | id1_type2
        }

    where links is an optional key but must be a dictionary with id types to
    URLs if it exists, and redirect_id_type is optional but if it exists,
    it must point to one of the existing id types in the links object. It is
    used to set a default redirect URL that is used by the resolution service."""
    allowed_keys = ['links', 'redirect_id_type']
    if not isinstance(reference_links, dict):
        raise Invalid('Expected reference_links to be an object')
    if 'links' in reference_links and (not isinstance(reference_links['links'], dict)):
        raise Invalid('Expected links in reference_links to be an object')
    links = reference_links.get('links', {})
    redirect_id_type = reference_links.get('redirect_id_type')
    for key in reference_links:
        if key not in allowed_keys:
            raise Invalid('Key {} is not allowed'.format(key))
    if redirect_id_type and redirect_id_type not in links:
        raise Invalid("Redirect ID type must point to one of the links' ID types")
    [validate_url(url) for url in links.values()]
    return reference_links

def _validate_state(state, valid_states):
    """Validate a state string"""
    if state in State:
        return state.name
    elif state in valid_states:
        return state
    else:
        raise Invalid('Invalid state')

