def make_path_properties(file_or_path, prefix=''):
    """Build useful properties from a file path."""
    is_std = file_or_path in (sys.stdin, sys.stdout, sys.stderr)
    if is_std:
        path = '-'
    elif is_filelike(file_or_path):
        try:
            path = str(file_or_path.name)
        except AttributeError:
            path = None
    else:
        path = str(file_or_path)
    if is_std or not path:
        abspath = dirname = basename = stem = ext = None
        realpath = realdrive = realdir = realbase = realstem = realext = None
        numbers = num = None
    else:
        abspath = os.path.abspath(path)
        dirname, basename = os.path.split(path)
        stem, ext = os.path.splitext(basename)
        if not dirname:
            dirname = os.curdir
        realpath = os.path.realpath(path)
        realdrive, tail = os.path.splitdrive(realpath)
        realdir, realbase = os.path.split(tail)
        realstem, realext = os.path.splitext(realbase)
        numbers = [int(s) for s in re.findall('\\d+', basename)]
        num = numbers[-1] if numbers else None
    return {prefix + 'path': path, prefix + 'abspath': abspath, prefix + 'dirname': dirname, prefix + 'basename': basename, prefix + 'stem': stem, prefix + 'ext': ext, prefix + 'realpath': realpath, prefix + 'realdrive': realdrive, prefix + 'realdir': realdir, prefix + 'realbase': realbase, prefix + 'realstem': realstem, prefix + 'realext': realext, prefix + 'numbers': numbers, prefix + 'num': num}

def constant_outfile_iterator(outfiles, infiles, arggroups):
    """Iterate over all output files."""
    assert len(infiles) == 1
    assert len(arggroups) == 1
    return ((outfile, infiles[0], arggroups[0]) for outfile in outfiles)

def variable_outfile_iterator(outfiles, infiles, arggroups, engine):
    """Iterate over variable output file name template."""
    assert len(outfiles) == 1
    template = engine(outfiles[0], tolerant=False)
    for infile in infiles:
        properties = make_path_properties(infile, prefix='')
        for arggroup in arggroups:
            outfile = template.apply(dict(arggroup, **properties))
            yield (outfile, infile, arggroup)

def process_combinations(combinations, engine, tolerant=False, read_old=False, delete_empty=False):
    """Process outfile-infile-arggroup combinations."""
    outfiles = set()
    templatereader = CachedTemplateReader(engine, tolerant=tolerant)
    for outfile, infile, arggroup in combinations:
        template = templatereader.read(infile)
        properties = make_path_properties(outfile, prefix='ez_')
        if read_old:
            if is_filelike(outfile):
                raise Exception('cannot read already open output streams')
            try:
                with open(outfile, 'r') as f:
                    properties['ez_content'] = f.read()
            except IOError:
                properties['ez_content'] = None
        result = template.apply(dict(arggroup, **properties))
        if is_filelike(outfile):
            if result:
                outfile.write(result)
        elif result or not delete_empty:
            if outfile in outfiles:
                raise IOError('trying to write twice to the same file')
            outfiles.add(outfile)
            with open(outfile, 'w') as f:
                f.write(result)
        else:
            try:
                os.remove(outfile)
            except OSError as e:
                if e.errno != errno.ENOENT:
                    raise

def perform_templating(args):
    """Perform templating according to the given arguments."""
    engine = engines.engines[args.engine]
    if args.vary:
        it = variable_outfile_iterator(args.outfiles, args.infiles, args.args, engine)
    else:
        it = constant_outfile_iterator(args.outfiles, args.infiles, args.args)
    process_combinations(it, engine, tolerant=args.tolerant, read_old=args.read_old, delete_empty=args.delete_empty)

def parse_interval(interval):
    """Attepmt to parse an ISO8601 formatted ``interval``.

    Returns a tuple of ``datetime.datetime`` and ``datetime.timedelta``
    objects, order dependent on ``interval``."""
    a, b = str(interval).upper().strip().split('/')
    if a[0] is 'P' and b[0] is 'P':
        raise ParseError()
    if a[0] != 'P' and b[0] != 'P':
        return (parse_date(a), parse_date(b))
    if a[0] is 'P':
        a = parse_duration(a)
    else:
        a = parse_date(a)
    if b[0] is 'P':
        b = parse_duration(b)
    else:
        b = parse_date(b)
    return (a, b)

def register_class(klass, alias=None):
    """Registers a class to be used in the data streaming. This is the equivalent
    to the C{[RemoteClass(alias="foobar")]} AS3 metatag.

    @return: The registered L{ClassAlias} instance.
    @see: L{unregister_class}"""
    meta = util.get_class_meta(klass)
    if alias is not None:
        meta['alias'] = alias
    alias_klass = util.get_class_alias(klass) or ClassAlias
    x = alias_klass(klass, defer=True, **meta)
    if not x.anonymous:
        CLASS_CACHE[x.alias] = x
    CLASS_CACHE[klass] = x
    return x

def unregister_class(alias):
    """Opposite of L{register_class}.

    @raise UnknownClassAlias: Unknown alias."""
    try:
        x = CLASS_CACHE[alias]
    except KeyError:
        raise UnknownClassAlias('Unknown alias %r' % (alias,))
    if not x.anonymous:
        del CLASS_CACHE[x.alias]
    del CLASS_CACHE[x.klass]
    return x

def get_class_alias(klass_or_alias):
    """Finds the L{ClassAlias} that is registered to C{klass_or_alias}.

    If a string is supplied and no related L{ClassAlias} is found, the alias is
    loaded via L{load_class}.

    @raise UnknownClassAlias: Unknown alias"""
    if isinstance(klass_or_alias, python.str_types):
        try:
            return CLASS_CACHE[klass_or_alias]
        except KeyError:
            return load_class(klass_or_alias)
    try:
        return CLASS_CACHE[klass_or_alias]
    except KeyError:
        raise UnknownClassAlias('Unknown alias for %r' % (klass_or_alias,))

def decode(stream, *args, **kwargs):
    """A generator function to decode a datastream.

    @param stream: AMF data to be decoded.
    @type stream: byte data.
    @kwarg encoding: AMF encoding type. One of L{ENCODING_TYPES}.
    @return: A generator that will decode each element in the stream."""
    encoding = kwargs.pop('encoding', DEFAULT_ENCODING)
    decoder = get_decoder(encoding, stream, *args, **kwargs)
    return decoder

def get_decoder(encoding, *args, **kwargs):
    """Returns a L{codec.Decoder} capable of decoding AMF[C{encoding}] streams.

    @raise ValueError: Unknown C{encoding}."""
    def _get_decoder_class():
        if encoding == AMF0:
            try:
                from cpyamf import amf0
            except ImportError:
                from pyamf import amf0
            return amf0.Decoder
        elif encoding == AMF3:
            try:
                from cpyamf import amf3
            except ImportError:
                from pyamf import amf3
            return amf3.Decoder
        raise ValueError('Unknown encoding %r' % (encoding,))
    return _get_decoder_class()(*args, **kwargs)

def get_encoder(encoding, *args, **kwargs):
    """Returns a L{codec.Encoder} capable of encoding AMF[C{encoding}] streams.

    @raise ValueError: Unknown C{encoding}."""
    def _get_encoder_class():
        if encoding == AMF0:
            try:
                from cpyamf import amf0
            except ImportError:
                from pyamf import amf0
            return amf0.Encoder
        elif encoding == AMF3:
            try:
                from cpyamf import amf3
            except ImportError:
                from pyamf import amf3
            return amf3.Encoder
        raise ValueError('Unknown encoding %r' % (encoding,))
    return _get_encoder_class()(*args, **kwargs)

def flex_loader(alias):
    """Loader for L{Flex<pyamf.flex>} framework compatibility classes.

    @raise UnknownClassAlias: Trying to load an unknown Flex compatibility class."""
    if not alias.startswith('flex.'):
        return
    try:
        if alias.startswith('flex.messaging.messages'):
            import pyamf.flex.messaging
        elif alias.startswith('flex.messaging.io'):
            import pyamf.flex
        elif alias.startswith('flex.data.messages'):
            import pyamf.flex.data
        return CLASS_CACHE[alias]
    except KeyError:
        raise UnknownClassAlias(alias)

def add_type(type_, func=None):
    """Adds a custom type to L{TYPE_MAP}. A custom type allows fine grain control
    of what to encode to an AMF data stream.

    @raise TypeError: Unable to add as a custom type (expected a class or callable).
    @raise KeyError: Type already exists.
    @see: L{get_type} and L{remove_type}"""
    def _check_type(type_):
        if not (isinstance(type_, python.class_types) or hasattr(type_, '__call__')):
            raise TypeError('Unable to add ' % ' as a custom type (expected a class or callable)' % (type_,))
    if isinstance(type_, list):
        type_ = tuple(type_)
    if type_ in TYPE_MAP:
        raise KeyError('Type %r already exists' % (type_,))
    if isinstance(type_, types.TupleType):
        for x in type_:
            _check_type(x)
    else:
        _check_type(type_)
    TYPE_MAP[type_] = func

def get_type(type_):
    """Gets the declaration for the corresponding custom type.

    @raise KeyError: Unknown type.
    @see: L{add_type} and L{remove_type}"""
    if isinstance(type_, list):
        type_ = tuple(type_)
    for k, v in TYPE_MAP.iteritems():
        if k == type_:
            return v
    raise KeyError('Unknown type %r' % (type_,))

def add_error_class(klass, code):
    """Maps an exception class to a string code. Used to map remoting C{onStatus}
    objects to an exception class so that an exception can be built to
    represent that error.

    An example::

        >>> class AuthenticationError(Exception):
        ...     pass
        ...
        >>> pyamf.add_error_class(AuthenticationError, 'Auth.Failed')
        >>> print pyamf.ERROR_CLASS_MAP
        {'TypeError': <type 'exceptions.TypeError'>, 'IndexError': <type 'exceptions.IndexError'>,
        'Auth.Failed': <class '__main__.AuthenticationError'>, 'KeyError': <type 'exceptions.KeyError'>,
        'NameError': <type 'exceptions.NameError'>, 'LookupError': <type 'exceptions.LookupError'>}

    @param klass: Exception class
    @param code: Exception code
    @type code: C{str}
    @see: L{remove_error_class}"""
    if not isinstance(code, python.str_types):
        code = code.decode('utf-8')
    if not isinstance(klass, python.class_types):
        raise TypeError('klass must be a class type')
    mro = inspect.getmro(klass)
    if not Exception in mro:
        raise TypeError('Error classes must subclass the __builtin__.Exception class')
    if code in ERROR_CLASS_MAP:
        raise ValueError('Code %s is already registered' % (code,))
    ERROR_CLASS_MAP[code] = klass

def remove_error_class(klass):
    """Removes a class from the L{ERROR_CLASS_MAP}.

    An example::

       >>> class AuthenticationError(Exception):
       ...     pass
       ...
       >>> pyamf.add_error_class(AuthenticationError, 'Auth.Failed')
       >>> pyamf.remove_error_class(AuthenticationError)

    @see: L{add_error_class}"""
    if isinstance(klass, python.str_types):
        if klass not in ERROR_CLASS_MAP:
            raise ValueError('Code %s is not registered' % (klass,))
    elif isinstance(klass, python.class_types):
        classes = ERROR_CLASS_MAP.values()
        if klass not in classes:
            raise ValueError('Class %s is not registered' % (klass,))
        klass = ERROR_CLASS_MAP.keys()[classes.index(klass)]
    else:
        raise TypeError('Invalid type, expected class or string')
    del ERROR_CLASS_MAP[klass]

def _parse_title_url(html_chunk):
    """Parse title/name of the book and URL of the book.

    Args:
        html_chunk (obj): HTMLElement containing slice of the page with details.

    Returns:
        tuple: (title, url), both as strings."""
    title = html_chunk.find('div', {'class': 'comment'})
    if not title:
        return (_parse_alt_title(html_chunk), None)
    title = title[0].find('h2')
    if not title:
        return (_parse_alt_title(html_chunk), None)
    url = None
    url_tag = title[0].find('a')
    if url_tag:
        url = url_tag[0].params.get('href', None)
        title = url_tag
    return (title[0].getContent(), normalize_url(BASE_URL, url))

def open_only(f):
    """decorator"""
    @functools.wraps(f)
    def f2(self, *args, **kwargs):
        if self.closed:
            raise NotSupportedError('connection is closed')
        return f(self, *args, **kwargs)
    return f2

def call_cur(f):
    """decorator for opening a connection and passing a cursor to the function"""
    @functools.wraps(f)
    def f2(self, *args, **kwargs):
        with self.withcur() as cur:
            return f(self, cur, *args, **kwargs)
    return f2

def _iter_full_paths(path_list):
    """Iterates over all paths that are in a directory and its subdirectory, returning
    fully-specified paths."""
    for path in path_list:
        if not os.path.isdir(path):
            full_path = os.path.realpath(path)
            yield path
        else:
            for root, dirs, filenames in os.walk(path):
                for filename in filenames:
                    full_path = os.path.realpath(os.path.join(root, filename))
                    yield full_path

def verify_config_container(object_):
    """Verify object is a valid config container

    Valid config containers provide zope.interface.common.mapping.IEnumerableMapping
    or an iterable of zope.interface.common.mapping.IEnumerableMapping.

    verification is performed by checking required interfaces attributes
    against those provided by object_

    Raises: zope.interface.exceptions.BrokenImplementation if object_ does not
            fully implement zope.interface.common.mapping.IEnumerableMapping"""
    try:
        _verify_map(object_)
    except BrokenImplementation as e:
        try:
            for m in object_:
                _verify_map(m)
        except BrokenImplementation:
            raise e

def ensure_exists(p, assume_dirs=False):
    """Ensures a given path *p* exists.

    If a path to a file is passed in, then the path to the file will be checked. This can be overridden by passing a
    value of ``True`` to ``assume_dirs``, in which case the paths will be assumed to be to directories, not files."""
    if Path(p).ext and (not assume_dirs):
        Path(p).dirname().makedirs_p()
    else:
        Path(p).makedirs_p()
    return p

def has_files(the_path):
    """Given a path, returns whether the path has any files in it or any subfolders. Works recursively."""
    the_path = Path(the_path)
    try:
        for _ in the_path.walkfiles():
            return True
        return False
    except OSError as ex:
        if ex.errno == errno.ENOENT:
            return False
        else:
            raise

def convert_results(data, **kwargs):
    """converts the results of a query to RdfDatatype instances

    args:
        data: a list of triples"""
    if kwargs.get('multiprocessing', False):
        manager = SharedManager()
        manager.register('BaseRdfDataType', BaseRdfDataType)
        manager.register('Uri', Uri)
        data_l = len(data)
        group_size = data_l // pool_size
        if data_l % pool_size:
            group_size += 1
        split_data = [data[i:i + group_size] for i in range(0, data_l, group_size)]
        output = manager.Queue()
        workers = [mp.Process(target=convert_batch, args=(item, output)) for item in split_data]
        for worker in workers:
            worker.start()
        results = []
        while True:
            running = any((p.is_alive() for p in workers))
            while not output.empty():
                results += output.get()
            if not running:
                break
        print('Finished - workers not stoped')
        for worker in workers:
            worker.join()
        for i in range(output.qsize()):
            results += output.get()
        return results
    else:
        return [{key: pyrdf(value) for key, value in row.items()} for row in data]

def dump(values):
    """Dump a ValueTree instance, returning its dict representation.

    :param values:
    :type values: ValueTree
    :return:
    :rtype: dict"""
    root = {}
    def _dump(_values, container):
        for name, value in _values._values.items():
            if isinstance(value, ValueTree):
                container[name] = _dump(value, {})
            elif isinstance(value, list):
                items = []
                for item in value:
                    if not isinstance(item, str):
                        raise ValueError()
                    items.append(item)
                container[name] = items
            elif isinstance(value, str):
                container[name] = value
            else:
                raise ValueError()
        return container
    return _dump(values, root)

def load(obj):
    """Load a ValueTree instance from its dict representation.

    :param obj:
    :type obj: dict
    :return:
    :rtype: ValueTree"""
    values = ValueTree()
    def _load(_obj, container):
        for name, value in _obj.items():
            if isinstance(value, dict):
                path = make_path(name)
                container.put_container(path)
                _load(value, container.get_container(path))
            elif isinstance(value, list):
                for item in value:
                    container.append_field(ROOT_PATH, name, item)
            elif isinstance(value, str):
                container.put_field(ROOT_PATH, name, value)
            else:
                raise ValueError()
    _load(obj, values)
    return values

