def _freezer_lookup(freezer_string):
    """Translate a string that may be a freezer name into the internal freezer constant

    :param freezer_string
    :return:"""
    sanitized = freezer_string.lower().strip()
    for freezer in FREEZER.ALL:
        freezer_instance = freezer()
        freezer_name = six.text_type(freezer_instance)
        if freezer_name == six.text_type(sanitized):
            return freezer
    else:
        if sanitized != freezer_string:
            raise ValueError(u'Unsupported freezer type "{0}". (Sanitized to "{1}")'.format(freezer_string, sanitized))
        else:
            raise ValueError(u'Unsupported freezer type "{0}".'.format(freezer_string))

def resolve_freezer(freezer):
    """Locate the appropriate freezer given FREEZER or string input from the programmer.

    :param freezer: FREEZER constant or string for the freezer that is requested.  (None = FREEZER.DEFAULT)
    :return:"""
    if not freezer:
        return _Default()
    if isinstance(freezer, six.string_types):
        cls = _freezer_lookup(freezer)
        return cls()
    if freezer.__class__ == type.__class__:
        return freezer()
    if freezer not in FREEZER.ALL:
        warn(u'Using custom freezer implelmentation: {0}'.format(freezer))
    return freezer

def parse_json_qry(qry_str):
    """Parses a json query string into its parts

    args:
        qry_str: query string
        params: variables passed into the string"""
    def param_analyzer(param_list):
        rtn_list = []
        for param in param_list:
            parts = param.strip().split('=')
            try:
                rtn_list.append(JsonQryProcessor[parts[0].strip().lower()](parts[1]))
            except IndexError:
                rtn_list.append(JsonQryProcessor[parts[0].strip().lower()]())
        return rtn_list
    def part_analyzer(part, idx):
        nonlocal dallor, asterick, question_mark
        if part == '$':
            dallor = idx
            return part
        elif part == '*':
            asterick = idx
            return part
        elif part == '?':
            question_mark = idx
            return part
        elif part.startswith('='):
            return part
        return cssparse(part)[0]
    main_parts = qry_str.split('|')
    or_parts = main_parts.pop(0).strip()
    params = param_analyzer(main_parts)
    rtn_list = []
    for or_part in [item.strip() for item in or_parts.split(',') if item.strip()]:
        dallor, asterick, question_mark = (None, None, None)
        dot_parts = or_part.split('.')
        rtn_list.append(([part_analyzer(part, i) for i, part in enumerate(dot_parts)], dallor, asterick, question_mark))
    return {'qry_parts': rtn_list, 'params': params}

def _check_for_int(x):
    """This is a compatibility function that takes a C{float} and converts it to an
    C{int} if the values are equal."""
    try:
        y = int(x)
    except (OverflowError, ValueError):
        pass
    else:
        if x == x and y == x:
            return y
    return x

def _dbus_get_interface(bus_name, object_name, interface_name):
    """Fetches DBUS interface proxy object given the specified parameters.

    `bus_name`
        Name of the bus interface.
    `object_name`
        Object path related to the interface.
    `interface_name`
        Name of the interface.

    Returns object or ``None``."""
    try:
        obj = _dbus_get_object(bus_name, object_name)
        if not obj:
            raise NameError
        return dbus.Interface(obj, interface_name)
    except (NameError, dbus.exceptions.DBusException):
        return None

def _empathy_status(status, message):
    """Updates status and message for Empathy IM application.

    `status`
        Status type.
    `message`
        Status message."""
    ACCT_IFACE = 'org.freedesktop.Telepathy.Account'
    DBUS_PROP_IFACE = 'org.freedesktop.DBus.Properties'
    ACCT_MAN_IFACE = 'org.freedesktop.Telepathy.AccountManager'
    ACCT_MAN_PATH = '/org/freedesktop/Telepathy/AccountManager'
    SP_IFACE = 'org.freedesktop.Telepathy.Connection.Interface.SimplePresence'
    am_iface = _dbus_get_interface(ACCT_MAN_IFACE, ACCT_MAN_PATH, DBUS_PROP_IFACE)
    if am_iface:
        account_paths = am_iface.Get(ACCT_MAN_IFACE, 'ValidAccounts')
        for account_path in account_paths:
            try:
                account = _dbus_get_object(ACCT_MAN_IFACE, account_path)
                if account.Get(ACCT_IFACE, 'ConnectionStatus') != 0:
                    continue
                conn_path = account.Get(ACCT_IFACE, 'Connection')
                conn_iface = conn_path.replace('/', '.')[1:]
                sp_iface = _dbus_get_interface(conn_iface, conn_path, SP_IFACE)
            except dbus.exceptions.DBusException:
                continue
            for code in EMPATHY_CODE_MAP[status]:
                try:
                    sp_iface.SetPresence(code, message)
                except dbus.exceptions.DBusException:
                    pass
                else:
                    break

def prompt_autocomplete(prompt, complete, default=None, contains_spaces=True, show_default=True, prompt_suffix=': ', color=None):
    """Prompt a string with autocompletion

    :param complete: A function that returns a list of possible strings that
        should be completed on a given text.
        def complete(text: str) -> List[str]: ..."""
    def real_completer(text, state):
        possibilities = complete(text) + [None]
        if possibilities:
            return possibilities[state]
        return None
    readline.set_completer_delims('\t\n' + ' ' * (not contains_spaces))
    readline.parse_and_bind('tab: complete')
    readline.set_completer(real_completer)
    if default is not None and show_default:
        prompt += ' [%s]' % default
    prompt += prompt_suffix
    colors = {'red': Fore.RED, 'blue': Fore.BLUE, 'green': Fore.GREEN, 'cyan': Fore.CYAN, 'magenta': Fore.MAGENTA, 'yellow': Fore.YELLOW, 'white': Fore.WHITE, 'black': Fore.LIGHTBLACK_EX}
    if color:
        prompt = colors[color.lower()] + prompt + Fore.RESET
    if default is not None:
        r = input(prompt)
    else:
        while True:
            r = input(prompt)
            if r:
                break
    r = r or default
    readline.parse_and_bind('tab: self-insert')
    readline.set_completer(None)
    return r

def prompt_file(prompt, default=None, must_exist=True, is_dir=False, show_default=True, prompt_suffix=': ', color=None):
    """Prompt a filename using using glob for autocompetion.

    If must_exist is True (default) then you can be sure that the value returned
    is an existing filename or directory name.
    If is_dir is True, this will show only the directories for the completion."""
    if must_exist:
        while True:
            r = prompt_autocomplete(prompt, path_complete(is_dir), default, show_default=show_default, prompt_suffix=prompt_suffix, color=color)
            if os.path.exists(r):
                break
            print('This path does not exist.')
    else:
        r = prompt_autocomplete(prompt, path_complete(is_dir), default, show_default=show_default, prompt_suffix=prompt_suffix, color=color)
    return r

