def sign(xml, private, public):
    """Return xmldsig XML string from xml_string of XML.
    @param xml: str of bytestring xml to sign
    @param private: publicKey Private key
    @param public: publicKey Public key
    @return str: signed XML byte string"""
    xml = xml.encode('utf-8', 'xmlcharrefreplace')
    signed_info_xml = _generate_signed_info(xml)
    signer = PKCS1_v1_5.PKCS115_SigScheme(private)
    signature_value = signer.sign(SHA.new(c14n(signed_info_xml)))
    signature_xml = PTN_SIGNATURE_XML % {'signed_info_xml': signed_info_xml, 'signature_value': binascii.b2a_base64(signature_value)[:-1], 'key_info_xml': _generate_key_info_xml_rsa(public.key.n, public.key.e)}
    position = xml.rfind('</')
    return xml[0:position] + signature_xml + xml[position:]

def autodiscover():
    """Perform an autodiscover of an api.py file in the installed apps to
    generate the routes of the registered viewsets."""
    for app in settings.INSTALLED_APPS:
        try:
            import_module('.'.join((app, 'api')))
        except ImportError as e:
            if e.msg != "No module named '{0}.api'".format(app):
                print(e.msg)

def identify_modules(*args, **kwargs):
    """Find the disk locations of the given named modules, printing the
    discovered paths to stdout and errors discovering paths to stderr.

    Any provided keyword arguments are passed to `identify_filepath()`."""
    if len(args) == 1:
        path_template = '%(file)s'
        error_template = "Module '%(mod)s' not found (%(error)s)"
    else:
        path_template = '%(mod)s: %(file)s'
        error_template = '%(mod)s: not found (%(error)s)'
    for modulename in args:
        try:
            filepath = identify_filepath(modulename, **kwargs)
        except ModuleNotFound:
            exc = sys.exc_info()[1]
            sys.stderr.write(error_template % {'mod': modulename, 'error': str(exc)})
            sys.stderr.write('\n')
        else:
            print(path_template % {'mod': modulename, 'file': filepath})

def find_version(*args):
    """Find the versions of the given named modules, printing the discovered
    versions to stdout and errors discovering versions to stderr."""
    if len(args) == 1:
        ver_template = '%(version)s'
        error_template = "Distribution/module '%(mod)s' not found (%(error)s)"
    else:
        ver_template = '%(mod)s: %(version)s'
        error_template = '%(mod)s: not found (%(error)s)'
    import pkg_resources
    for modulename in args:
        try:
            try:
                dist = pkg_resources.get_distribution(modulename)
            except pkg_resources.DistributionNotFound:
                mod = identify_module(modulename)
                if not hasattr(mod, '__version__'):
                    raise ModuleNotFound('module has no __version__')
                version = mod.__version__
            else:
                version = dist.version
        except ModuleNotFound:
            exc = sys.exc_info()[1]
            sys.stderr.write(error_template % {'mod': modulename, 'error': str(exc)})
            sys.stderr.write('\n')
        else:
            print(ver_template % {'mod': modulename, 'version': version})

