        errors = SourceReporter(content)
        if errors:
            raise ValidationError(map(map_parsing_errors, errors))
    return content

def accepts(*checkers_args, **checkers_kws):
    """Create a decorator for validating function parameters.

    Parameters
    ----------
    checkers_args: positional args
        Functions to apply to the inputs of the decorated function. The position of the argument
        is assumed to match the position of the function in the decorator.
    checkers_kws: keyword args
        Keyword pairs in the form (arg: function) to apply to the inputs of the decorated function.

    Example
    -------
    @accepts(df=df_checker)
    def do_something_with_df(df, args*, kw**):
        print(df.head())"""
    @decorator
    def run_checkers(func, *args, **kwargs):
        all_args = inspect.getcallargs(func, *args, **kwargs)
        if checkers_args:
            for idx, checker_function in enumerate(checkers_args):
                if callable(checker_function):
                    result = checker_function(args[idx])
        if checkers_kws:
            for key in checkers_kws.keys():
                if key not in all_args:
                    raise ValueError('Argument specified in @accepts is not found in decorated function')
                else:
                    df = all_args[key]
                    result = checkers_kws[key](df)
        return func(*args, **kwargs)
    return run_checkers

def returns(*checkers_args):
    """Create a decorator for validating function return values.

    Parameters
    ----------
    checkers_args: positional arguments
        A single functions to apply to the output of the decorated function. If a tuple is returned
        by the decorated function, multiple function can be listed and are assumed to match by
        possition to the elements in the returned tuple.

    Examples
    --------
    @returns(df_checker)
    def do_something_with_df(df, args*, kw**):
        print(df.head())
        return df

    @returns(df_checker1, df_checker2)
    def do_something_with_dfs(df1, df2, args*, kw**):
        # Do somethign with both dfs
        return (df1, df2)"""
    @decorator
    def run_checkers(func, *args, **kwargs):
        ret = func(*args, **kwargs)
        if type(ret) != tuple:
            ret = (ret,)
        assert len(ret) == len(checkers_args)
        if checkers_args:
            for idx, checker_function in enumerate(checkers_args):
                if callable(checker_function):
                    result = checker_function(ret[idx])
        return ret
    return run_checkers

def get_field_lookups(field_type, nullable):
    """Return lookup table value and append isnull if
    this is a nullable field"""
    return LOOKUP_TABLE.get(field_type) + ['isnull'] if nullable else LOOKUP_TABLE.get(field_type)

def match_field(field_class):
    """Iterates the field_classes and
    returns the first match"""
    for cls in field_class.mro():
        if cls in list(LOOKUP_TABLE.keys()):
            return cls
    raise Exception('{0} None Found '.format(field_class))

def class_lookups(model_field):
    """Return list of available lookups for
    the passed in (model) field type"""
    field_class = type(model_field)
    field_type = match_field(field_class)
    return get_field_lookups(field_type, model_field.null)

def contains_shebang(f):
    """Returns true if any shebang line is present in the first line of the file."""
    first_line = f.readline()
    if first_line in shebangs.values():
        return True
    return False

def update_req(name, old_req, config={}):
    """Takes a requirement and updates it based on a specific attribute key

    args:
        name: the name of the attribute
        old_req: the requirement definition"""
    if not name:
        return old_req
    new_req = copy.deepcopy(old_req)
    del_idxs = []
    if 'req_items' in old_req:
        req_key = get_req_key(old_req['req_items'])
        for i, item in enumerate(old_req['req_items']):
            if name == item[req_key] and item.get('dict_params'):
                for param, value in item['dict_params'].items():
                    new_req['item_dict'][param].update(value)
            if item.get('remove_if'):
                test_val = get_attr(config, item['remove_if']['attr'])
                if test_val == item['remove_if']['value']:
                    del_idxs.append(i)
        for idx in sorted(del_idxs, reverse=True):
            del new_req['req_items'][idx]
    return new_req

def get_options_from_str(obj_str, **kwargs):
    """Returns a list of options from a python object string

    args:
        obj_str: python list of options or a python object path
                  Example: "rdfframework.connections.ConnManager[{param1}]"

    kwargs:
        * kwargs used to format the 'obj_str'"""
    if isinstance(obj_str, list):
        return obj_str
    try:
        obj = get_obj_frm_str(obj_str, **kwargs)
        if obj:
            return list(obj)
    except AttributeError:
        pass
    return []

def strip_errors(obj):
    """Reads through and error object and replaces the error dict with the
    value

    args:
        obj: the error object/dictionary"""
    rtn_obj = copy.deepcopy(obj)
    try:
        del rtn_obj['__error_keys__']
    except KeyError:
        pass
    for key in obj.get('__error_keys__', []):
        rtn_obj[key] = rtn_obj[key]['value']
    return rtn_obj

def is_days_ago(adatetime, days):
    """:param days: a positive integer.
    Return true if the adatetime is on the specified days ago"""
    if days == 1:
        end_time = last_midnight()
        start_time = end_time - timedelta(days=1)
    else:
        start_time = last_midnight() - timedelta(days=days)
        end_time = start_time + timedelta(days=1)
    return start_time <= adatetime <= end_time

def last_midnight():
    """return a datetime of last mid-night"""
    now = datetime.now()
    return datetime(now.year, now.month, now.day)

def _read_header(stream, decoder, strict=False):
    """Read AMF L{Message} header from the stream.

    @type stream: L{BufferedByteStream<pyamf.util.BufferedByteStream>}
    @param decoder: An AMF0 decoder.
    @param strict: Use strict decoding policy. Default is C{False}. Will raise a
        L{pyamf.DecodeError} if the data that was read from the stream does not
        match the header length.
    @return: A C{tuple} containing the name of the header, a C{bool}
        determining if understanding this header is required and the decoded
        data.
    @note: Quite what understanding required headers actually means is unknown."""
    name_len = stream.read_ushort()
    name = stream.read_utf8_string(name_len)
    required = bool(stream.read_uchar())
    data_len = stream.read_ulong()
    pos = stream.tell()
    data = decoder.readElement()
    if strict and pos + data_len != stream.tell():
        raise pyamf.DecodeError('Data read from stream does not match header length')
    return (name, required, data)

def _write_header(name, header, required, stream, encoder, strict=False):
    """Write AMF message header.

    @param name: Name of the header.
    @param header: Header value.
    @param required: Whether understanding this header is required (?).
    @param stream: L{BufferedByteStream<pyamf.util.BufferedByteStream>} that
        will receive the encoded header.
    @param encoder: An encoder capable of encoding C{AMF0}.
    @param strict: Use strict encoding policy. Default is C{False}. Will write
        the correct header length after writing the header."""
    stream.write_ushort(len(name))
    stream.write_utf8_string(name)
    stream.write_uchar(required)
    write_pos = stream.tell()
    stream.write_ulong(0)
    old_pos = stream.tell()
    encoder.writeElement(header)
    new_pos = stream.tell()
    if strict:
        stream.seek(write_pos)
        stream.write_ulong(new_pos - old_pos)
        stream.seek(new_pos)

def coauthor_likelihoods(p1, p2):
    """returns the likelihoods of observing the actual number coauthors shared
    by c{p1} and c{p2}, conditioned on whether or not p1 and p2 are a match"""
    def get_coauthors(p):
        ret = set()
        for m in p.mentions:
            for co_m in article_to_mentions[m.article_id]:
                if m != co_m:
                    co_p = Agglomerator.MENTION_TO_CLUSTER[co_m]
                    ret.add(co_p)
        return ret
    def num_common_coauthors(p1, p2):
        return len(set.intersection(get_coauthors(p1), get_coauthors(p2)))
    num_common = num_common_coauthors(p1, p2)
    if num_common >= len(config.p_coauthor[0]):
        num_common = len(config.p_coauthor[0]) - 1
    likelihood0 = config.p_coauthor[0][num_common]
    likelihood1 = config.p_coauthor[1][num_common]
    return (likelihood1, likelihood0)

def filelist(folderpath, ext=None):
    """Returns a list of all the files contained in the folder specified by `folderpath`.
    To filter the files by extension simply add a list containing all the extension with `.` as the second argument.
    If `flat` is False, then the Path objects are returned."""
    if not ext:
        ext = []
    if os.path.exists(folderpath) and os.path.isdir(folderpath):
        return [os.path.join(folderpath, f) for f in os.listdir(folderpath) if os.path.isfile(os.path.join(folderpath, f)) and os.path.splitext(f)[1] in ext]
    else:
        log.warn('"{}" does not exist or is not a directory'.format(folderpath))

def particles(category=None):
    """Returns a dict containing old greek particles grouped by category."""
    filepath = os.path.join(os.path.dirname(__file__), './particles.json')
    with open(filepath) as f:
        try:
            particles = json.load(f)
        except ValueError as e:
            log.error('Bad json format in "{}"'.format(filepath))
        else:
            if category:
                if category in particles:
                    return particles[category]
                else:
                    log.warn('Category "{}" not contained in particle dictionary!'.format(category))
            return particles

