def dbsafe_encode(value, compress_object=False):
    """We use deepcopy() here to avoid a problem with cPickle, where dumps
    can generate different character streams for same lookup value if
    they are referenced differently.

    The reason this is important is because we do all of our lookups as
    simple string matches, thus the character streams must be the same
    for the lookups to work properly. See tests.py for more information."""
    if not compress_object:
        value = b64encode(dumps(deepcopy(value)))
    else:
        value = b64encode(compress(dumps(deepcopy(value))))
    return PickledObject(value)

def each_cons(sequence, size):
    """Iterates lazily through a sequence looking at a sliding window
    with given size, for each time.

    each_cons([1, 2, 3, 4], 2) --> [(0, 1), (1, 2), (2, 3), (3, 4)]"""
    return zip(*(islice(it, start, None) for start, it in enumerate(tee(sequence, size))))

def slice_before(predicate, iterable):
    """Returns groups of elements from iterable,
    slicing just before predicate(elem) is True"""
    if isinstance(predicate, string_type):
        predicate = re.compile(predicate)
    if hasattr(predicate, 'match'):
        predicate = predicate.match
    record = []
    for i, item in enumerate(iterable):
        if i == 0:
            record = [item]
            continue
        if predicate(item):
            yield tuple(record)
            record = [item]
        else:
            record.append(item)
    if record:
        yield tuple(record)

def slice_after(predicate, iterable):
    """Returns groups of elements from iterable,
    slicing just after predicate(elem) is True"""
    record = []
    for i, item in enumerate(iterable):
        record.append(item)
        if predicate(item):
            yield tuple(record)
            record = []
    if record:
        yield tuple(record)

def load_configuration(app_name):
    """creates a new configuration and loads the appropriate
    files."""
    if sys.prefix == '/usr':
        conf_dir = '/etc'
        share_dir = '/usr/share'
    else:
        conf_dir = os.path.join(sys.prefix, 'etc')
        share_dir = os.path.join(sys.prefix, 'share')
    yml_config = {}
    for fname in ['%s.yml' % (app_name,), os.path.expanduser('~/.%s.yml' % (app_name,)), os.path.join(conf_dir, '%s.yml' % (app_name,))]:
        if os.path.exists(fname):
            yml_config = yaml.load(open(fname))
            break
    try:
        data_dir = yml_config['paths']['data_dir']
    except KeyError:
        try:
            data_dir = os.environ[app_name.upper()]
        except KeyError:
            data_dir = os.path.join(share_dir, app_name)
    return AppContext(yml_config, data_dir)

def preserve_view(*predicates):
    """Raising ViewNotMatched when applied request was not apposite.

    preserve_view calls all Predicates and when return values of them was
    all True it will call a wrapped view.
    It raises ViewNotMatched if this is not the case.

    Predicates:
    This decorator takes Predicates one or more, Predicate is callable
    to return True or False in response to inputted request.
    If the request was apposite it should return True."""
    def wrapper(view_callable):
        def _wrapped(self, request, context, *args, **kwargs):
            if all([predicate(request, context) for predicate in predicates]):
                return view_callable(self, request, context, *args, **kwargs)
            else:
                raise ViewNotMatched
        return _wrapped
    return wrapper

def render_template(template_name, template_getter=get_app_template):
    """Decorator to specify which template to use for Wrapped Views.

    It will return string rendered by specified template and
    returned dictionary from wrapped views as a context for template.
    The returned value was not dictionary, it does nothing,
    just returns the result."""
    def wrapper(func):
        template = template_getter(template_name)
        def _wraped(self, request, context, *args, **kwargs):
            res = func(self, request, context, *args, **kwargs)
            if isinstance(res, dict):
                return template.render(**res)
            else:
                return res
        return _wraped
    return wrapper

def convert_to(target, amount, date=None, percent=0, valid_days_max=None):
    """will convert the amount in CZK into given currency (target)
    you can calculate with regard to (given) date
    you can add additional margin with percent parameter
    valid_days_max: see rate()"""
    if target.upper() == 'CZK':
        result = amount
    else:
        result = amount / rate(target, date, valid_days_max=valid_days_max)
    return modified(result, percent)

def worse(src_amount, src_currency, target_amount_obtained, target_currency, date=None, valid_days_max=None):
    """will calculate a difference between the calculated target amount and the amount you give as src_amount
      if you will obtain target_amount_obtained instead
    valid_days_max: see rate()
    returns a tuple: (percent, difference_src_currency, difference_target_currency)"""
    calculated = convert(src_amount, src_currency, target=target_currency, date=date, valid_days_max=valid_days_max)
    worse = calculated - target_amount_obtained
    worse_src = convert(worse, target_currency, target=src_currency, date=date, valid_days_max=valid_days_max)
    if src_amount:
        return (worse_src / src_amount * 100.0, worse_src, worse)
    elif not target_amount_obtained:
        return (0.0, worse_src, worse)
    else:
        return (float('inf') if target_amount_obtained < 0 else float('-inf'), worse_src, worse)

def config_conf(obj):
    """Extracts the configuration of the underlying ConfigParser from obj"""
    cfg = {}
    for name in dir(obj):
        if name in CONFIG_PARSER_CFG:
            cfg[name] = getattr(obj, name)
    return cfg

def add_gnu_argument(self, *args, **kwargs):
    """Prevent the addition of any single hyphen, multiple letter args"""
    gnu_args = []
    for arg in args:
        if len(arg) > 3 and arg[0] == '-' and (arg[1] != '-'):
            gnu_args.append('-' + arg)
        else:
            gnu_args.append(arg)
    argparse.ArgumentParser.add_argument(self, *gnu_args, **kwargs)

