def identify_vcs(repo_url, guess=False, repo_aliases=REPO_ALIASES):
    """Determines the type of repo that `repo_url` represents.
    :param repo_url: Repo URL of unknown type.
    :returns: VCS type (git, hg, etc) or raises UnknownVCS exception."""
    repo_url = unicode(repo_url)
    vcs = identify_vcs_vs_alias(repo_url, guess=guess, repo_aliases=repo_aliases)
    if vcs:
        return vcs
    no_prefix = ''.join(repo_url.split('//')[1:])
    vcs = identify_vcs_vs_alias(no_prefix, guess=guess, repo_aliases=repo_aliases)
    if vcs:
        return vcs
    if guess:
        if 'bitbucket' in repo_url:
            return 'hg'
    raise UnknownVCS

def identify_hosting_service(repo_url, hosting_services=HOSTING_SERVICES):
    """Determines the hosting service of `repo_url`.
    :param repo_url: Repo URL of unknown type.
    :returns: Hosting service or raises UnknownHostingService exception."""
    repo_url = unicode(repo_url)
    for service in hosting_services:
        if service in repo_url:
            return service
    raise UnknownHostingService

def watdarepo(repo_url, mode='d', guess=False, repo_aliases=REPO_ALIASES, hosting_services=HOSTING_SERVICES):
    """Gets vcs and hosting service for repo_urls
    :param repo_url: Repo URL of unknown type.
    :param mode: Return dictionary (default) or object
    :param guess: Whether or not to make guesses
    :returns: Hosting service or raises UnknownHostingService exception."""
    repo_url = unicode(repo_url)
    repo_data = {'repo_url': repo_url}
    try:
        repo_data['vcs'] = identify_vcs(repo_url, repo_aliases=repo_aliases)
    except UnknownVCS:
        repo_data['vcs'] = None
    try:
        repo_data['hosting_service'] = identify_hosting_service(repo_url, hosting_services=hosting_services)
    except UnknownHostingService:
        repo_data['hosting_service'] = None
    if mode in ('c', 'o'):
        Repo = type(str('Repo'), (object,), repo_data)
        return Repo()
    return repo_data

def truncatechars(value, arg=50):
    """Takes a string and truncates it to the requested amount, by inserting an ellipses into the middle."""
    arg = int(arg)
    if arg < len(value):
        half = (arg - 3) / 2
        return '%s...%s' % (value[:half], value[-half:])
    return value

def __extend_uri(prefixes, short):
    """Extend a prefixed uri with the help of a specific dictionary of prefixes
    :param prefixes: Dictionary of prefixes
    :param short: Prefixed uri to be extended
    :return:"""
    for prefix in prefixes:
        if short.startswith(prefix):
            return short.replace(prefix + ':', prefixes[prefix])
    return short

def anonymous_required(function):
    """Redirect to user profile if user is already logged-in"""
    def wrapper(*args, **kwargs):
        if args[0].user.is_authenticated():
            url = settings.ANONYMOUS_REQUIRED_REDIRECT_URL
            return HttpResponseRedirect(reverse(url))
        return function(*args, **kwargs)
    return wrapper

def discover_yaml(bank=None, **meta):
    """Discovers the YAML format and registers it if available.

    Install YAML support via PIP::

        pip install PyYAML

    :param bank: The format bank to register the format in
    :param meta: Extra information associated with the format"""
    try:
        import yaml
        if bank is None:
            bank = default_bank
        bank.register('yaml', yaml.load, yaml.dump, **meta)
    except ImportError:
        pass

def filter_factory(global_conf, **local_conf):
    """Returns a WSGI filter app for use with paste.deploy."""
    conf = global_conf.copy()
    conf.update(local_conf)
    def trusted_shared_nets(app):
        return TrustedSharedNetwork(app, conf)
    return trusted_shared_nets

def load_design_docs():
    """Load design docs for registered views"""
    url = ':'.join([options.url_registry_db, str(options.db_port)])
    client = partial(couch.BlockingCouch, couch_url=url)
    for name, docs in _views.items():
        db = client(db_name=name)
        views = []
        for doc in docs:
            try:
                current_doc = db.get_doc(doc['_id'])
                if '_rev' not in doc:
                    doc['_rev'] = current_doc['_rev']
            except couch.NotFound:
                pass
            views.append(doc)
        db.save_docs(views)

def active_user_organisations_resource(doc):
    """Get user.organisations subresouces"""
    if doc.get('type') == 'user' and doc.get('state') != 'deactivated':
        for org_id, resource in doc.get('organisations', {}).items():
            if resource['state'] != 'deactivated':
                resource['id'] = org_id
                resource['user_id'] = doc['_id']
                yield ([doc['_id'], org_id], resource)

