def filter(filter_creator):
    """Creates a decorator that can be used as a filter.

    .. warning::
        This is currently not compatible with most other decorators, if
        you are using a decorator that isn't part of `hurler` you should
        take caution."""
    filter_func = [None]
    def function_getter(function):
        if isinstance(function, Filter):
            function.add_filter(filter)
            return function
        else:
            return Filter(filter=filter_func[0], callback=function)
    def filter_decorator(*args, **kwargs):
        filter_function = filter_creator(*args, **kwargs)
        filter_func[0] = filter_function
        return function_getter
    return filter_decorator

def bin_priority(op, left, right):
    """I don't know how to handle order of operations in the LR grammar, so here it is"""
    if isinstance(left, BinX) and left.op < op:
        return bin_priority(left.op, left.left, bin_priority(op, left.right, right))
    elif isinstance(left, UnX) and left.op < op:
        return un_priority(left.op, BinX(op, left.val, right))
    elif isinstance(right, BinX) and right.op < op:
        return bin_priority(right.op, bin_priority(op, left, right.left), right.right)
    else:
        return BinX(op, left, right)

def un_priority(op, val):
    """unary expression order-of-operations helper"""
    if isinstance(val, BinX) and val.op < op:
        return bin_priority(val.op, UnX(op, val.left), val.right)
    else:
        return UnX(op, val)

