def ajax_login_required(view_func):
    """Handle non-authenticated users differently if it is an AJAX request."""
    @wraps(view_func, assigned=available_attrs(view_func))
    def _wrapped_view(request, *args, **kwargs):
        if request.is_ajax():
            if request.user.is_authenticated():
                return view_func(request, *args, **kwargs)
            else:
                response = http.HttpResponse()
                response['X-Django-Requires-Auth'] = True
                response['X-Django-Login-Url'] = settings.LOGIN_URL
                return response
        else:
            return login_required(view_func)(request, *args, **kwargs)
    return _wrapped_view

def ajax_only(view_func):
    """Required the view is only accessed via AJAX."""
    @wraps(view_func, assigned=available_attrs(view_func))
    def _wrapped_view(request, *args, **kwargs):
        if request.is_ajax():
            return view_func(request, *args, **kwargs)
        else:
            return http.HttpResponseBadRequest()
    return _wrapped_view

def anonymous_required(func=None, url=None):
    """Required that the user is not logged in."""
    url = url or '/'
    def _dec(view_func):
        @wraps(view_func, assigned=available_attrs(view_func))
        def _wrapped_view(request, *args, **kwargs):
            if request.user.is_authenticated():
                return redirect(url)
            else:
                return view_func(request, *args, **kwargs)
        return _wrapped_view
    if func is None:
        return _dec
    else:
        return _dec(func)

def secure(view_func):
    """Handles SSL redirect on the view level."""
    @wraps(view_func, assigned=available_attrs(view_func))
    def _wrapped_view(request, *args, **kwargs):
        if not request.is_secure():
            redirect = _redirect(request, True)
            if redirect:
                return redirect
        return view_func(request, *args, **kwargs)
    return _wrapped_view

def encode_int(n):
    """Encodes an int as a variable length signed 29-bit integer as defined by
    the spec.

    @param n: The integer to be encoded
    @return: The encoded string
    @rtype: C{str}
    @raise OverflowError: Out of range."""
    global ENCODED_INT_CACHE
    try:
        return ENCODED_INT_CACHE[n]
    except KeyError:
        pass
    if n < MIN_29B_INT or n > MAX_29B_INT:
        raise OverflowError('Out of range')
    if n < 0:
        n += 536870912
    bytes = ''
    real_value = None
    if n > 2097151:
        real_value = n
        n >>= 1
        bytes += chr(128 | n >> 21 & 255)
    if n > 16383:
        bytes += chr(128 | n >> 14 & 255)
    if n > 127:
        bytes += chr(128 | n >> 7 & 255)
    if real_value is not None:
        n = real_value
    if n > 2097151:
        bytes += chr(n & 255)
    else:
        bytes += chr(n & 127)
    ENCODED_INT_CACHE[n] = bytes
    return bytes

def decode_int(stream, signed=False):
    """Decode C{int}."""
    n = result = 0
    b = stream.read_uchar()
    while b & 128 != 0 and n < 3:
        result <<= 7
        result |= b & 127
        b = stream.read_uchar()
        n += 1
    if n < 3:
        result <<= 7
        result |= b
    else:
        result <<= 8
        result |= b
        if result & 268435456 != 0:
            if signed:
                result -= 536870912
            else:
                result <<= 1
                result += 1
    return result

def v1_tag_list(tags, tag=''):
