def get_site_metas(with_static=False, with_media=False, is_secure=False, extra={}):
    """Return metas from the current *Site* and settings

    Added Site metas will be callable in templates like this
    ``SITE.themetaname``

    This can be used in code out of a Django requests (like in management
    commands) or in a context processor to get the *Site* urls.

    Default metas returned :

    * SITE.name: Current *Site* entry name;
    * SITE.domain: Current *Site* entry domain;
    * SITE.web_url: The Current *Site* entry domain prefixed with the http
      protocol like ``http://mydomain.com``. If HTTPS is enabled 'https' will be used instead of 'http';

    Optionally it can also return ``STATIC_URL`` and ``MEDIA_URL`` if needed
    (like out of Django requests)."""
    site_current = Site.objects.get_current()
    metas = {'SITE': {'name': site_current.name, 'domain': site_current.domain, 'web_url': 'http://%s' % site_current.domain}}
    if is_secure:
        metas['web_url'] = 'https://%s' % site_current.domain
    if with_media:
        metas['MEDIA_URL'] = getattr(settings, 'MEDIA_URL', '')
    if with_static:
        metas['STATIC_URL'] = getattr(settings, 'STATIC_URL', '')
    metas.update(extra)
    return metas

def _alephResultToDict(dom):
    """Convert part of non-nested XML to :py:class:`dict`.

    Args:
        dom (HTMLElement tree): pre-parsed XML (see dhtmlparser).

    Returns:
        dict: with python data"""
    result = {}
    for i in dom.childs:
        if not i.isOpeningTag():
            continue
        keyword = i.getTagName().strip()
        value = _tryConvertToInt(i.getContent().strip())
        if keyword in result:
            if isinstance(result[keyword], list):
                result[keyword].append(value)
            else:
                result[keyword] = [result[keyword], value]
        else:
            result[keyword] = value
    return result

def attr(object, attr):
    """Lookup attributes in django templates dynamically
    From http://stackoverflow.com/a/3466349/594269

    Allows lookups such as {{ user|attr:item }} where item is a
    template variable"""
    pseudo_context = {'object': object}
    try:
        value = Variable('object.%s' % attr).resolve(pseudo_context)
    except VariableDoesNotExist:
        value = None
    return value

def to_cartesian(r, theta, theta_units='radians'):
    """Converts polar r, theta to cartesian x, y."""
    assert theta_units in ['radians', 'degrees'], 'kwarg theta_units must specified in radians or degrees'
    if theta_units == 'degrees':
        theta = to_radians(theta)
    theta = to_proper_radians(theta)
    x = r * cos(theta)
    y = r * sin(theta)
    return (x, y)

