    else:
        return wrap(one_string, len(one_string) / line_count)

def jsonify(data, pretty=False, **kwargs):
    """Serialize Python objects to JSON with optional 'pretty' formatting

    Raises:
        TypeError: from :mod:`json` lib
        ValueError: from :mod:`json` lib
        JSONDecodeError: from :mod:`json` lib"""
    isod = isinstance(data, OrderedDict)
    params = {'for_json': True, 'default': _complex_encode}
    if pretty:
        params['indent'] = 2
        params['sort_keys'] = False if isod else True
    params.update(kwargs)
    try:
        return json.dumps(data, ensure_ascii=False, **params)
    except UnicodeDecodeError:
        return json.dumps(data, **params)

def serialize(data, format: str='json', pretty: bool=False):
    """Serialize a stellata object to a string format."""
    def encode(obj):
        if isinstance(obj, stellata.model.Model):
            return obj.to_dict()
        elif isinstance(obj, datetime.datetime):
            return int(obj.timestamp())
        elif isinstance(obj, datetime.date):
            return obj.isoformat()
        elif isinstance(obj, decimal.Decimal):
            return float(obj)
        elif hasattr(obj, 'serialize'):
            return obj.serialize()
        return obj
    if format == 'msgpack':
        return msgpack.packb(data, default=encode)
    if format == 'json':
        if pretty:
            return json.dumps(data, default=encode, indent=4)
        return json.dumps(data, default=encode)
    return data

def process_form(request, form_class, form_dict=None, save_kwargs=None, *a, **kw):
    """Optional:
    =========

    You can pass kwargs to the form save function in a 'save_kwargs' dict.


    Example Usage:
    ==============

    success, form = process_form(request, DiscussionForm, initial={
        'category':Category.objects.all()[0].id,
    })
    if success:
        return form # this is the return from the forms save method.

    return template(request, 'talk/create_discussion.html', {
        'categories': Category.objects.all(),
        'form': form
    })"""
    form = form_class(form_dict or request.POST or None, *a, **kw)
    if request.method == 'POST':
        if form.is_valid():
            if not save_kwargs:
                save_kwargs = {}
            results = form.save(request=request, **save_kwargs)
            return (True, results)
    return (False, form)

def atomic_symlink(src, dst):
    """Create or update a symbolic link atomically.

    This function is similar to :py:func:`os.symlink` but will update a symlink atomically."""
    dst_dir = os.path.dirname(dst)
    tmp = None
    max_tries = getattr(os, 'TMP_MAX', 10000)
    try:
        if not os.path.exists(dst_dir):
            os.makedirs(dst_dir)
        for n in range(max_tries):
            try:
                tmp = tempfile.mktemp(dir=dst_dir)
                os.symlink(src, tmp)
                logger.debug('created symlink %s', tmp)
            except OSError as e:
                if e.errno == errno.EEXIST:
                    continue
                else:
                    raise
            logger.debug('renaming %s to %s', tmp, dst)
            os.rename(tmp, dst)
            return
    except:
        if tmp and os.path.exists(tmp):
            os.remove(tmp)
        raise
    raise IOError(errno.EEXIST, 'No usable temporary file name found')

