def parsePyLintWarnings(warnings):
    """Turns pyLint/TwistedChecker output into something more useful.

    @param warnings: The warnings to process. Needs to be in pyLint's
        'parseable' format.

    @return: L{dict} of L{list}s"""
    warningsDict = {}
    for line in warnings:
        match = re.search(P_PYLINT_ERROR, line)
        if match:
            matchDict = match.groupdict()
            if not warningsDict.get(matchDict['file']):
                warningsDict[matchDict['file']] = []
            warningEntry = {'line': matchDict.get('file'), 'warning_id': matchDict.get('type') + matchDict.get('errno')}
            if matchDict.get('msg'):
                warningEntry['warning_message'] = matchDict.get('msg')
            warningsDict[matchDict['file']].append(warningEntry)
    return warningsDict

def get_page_object_by_name(context, name):
    """**Arguments**

    ``name`
        name for object selection

    :return selected object"""
    selected_object = None
    try:
        for obj_type in context['page']['content']:
            for obj in context['page']['content'][obj_type]:
                if obj.name == name:
                    selected_object = obj
                    break
        if selected_object is None:
            for obj_type in context['page']['content']:
                for obj in context['page']['ext_content'][obj_type]:
                    if obj.name == name:
                        selected_object = obj
                        break
    except TypeError:
        pass
    return selected_object

def get_page_object_by_id(context, object_type, oid):
    """**Arguments**

    ``object_type``
        object type

    ``oid``
        id for object selection

    :return selected object"""
    if type(oid) != int:
        raise template.TemplateSyntaxError('page_object_by_id tag requires a integer argument')
    selected_object = None
    try:
        try:
            for obj in context['page']['content'][object_type]:
                sid = '{0:>s}:{1:>s}:{2:>s}:{3:>d}'.format(obj.language, context['page']['page'].name, obj.type, oid)
                if obj.sid == sid:
                    selected_object = obj
                    break
        except TypeError:
            pass
    except KeyError:
        try:
            try:
                for obj in context['page']['ext_content'][object_type]:
                    sid = '{0:>s}:{1:>s}:{2:>s}:{3:>d}'.format(obj.language, context['page']['page'].name, obj.type, oid)
                    if obj.sid == sid:
                        selected_object = obj
                        break
            except TypeError:
                pass
        except KeyError:
            raise template.TemplateSyntaxError('wrong content type: {0:>s}'.format(object_type))
    return selected_object

