def validate_config(raise_=True):
    """Verifies that all configuration values have a valid setting"""
    ELIBConfig.check()
    known_paths = set()
    duplicate_values = set()
    missing_values = set()
    for config_value in ConfigValue.config_values:
        if config_value.path not in known_paths:
            known_paths.add(config_value.path)
        else:
            duplicate_values.add(config_value.name)
        try:
            config_value()
        except MissingValueError:
            missing_values.add(config_value.name)
    if raise_ and duplicate_values:
        raise DuplicateConfigValueError(str(duplicate_values))
    if raise_ and missing_values:
        raise MissingValueError(str(missing_values), 'missing config value(s)')
    return (duplicate_values, missing_values)

def openAPIDoc(**kwargs):
    """Update a function's docstring to include the OpenAPI Yaml generated by running the openAPIGraph object"""
    s = yaml.dump(kwargs, default_flow_style=False)
    def deco(routeHandler):
        ret = functools.wraps(routeHandler)(routeHandler)
        if not ret.__doc__:
            ret.__doc__ = ''
        ret.__doc__ = cleandoc(ret.__doc__) + '\n---\n' + s
        return ret
    return deco

def is_valid_timestamp(date, unit='millis'):
    """Checks that a number that represents a date as milliseconds is correct."""
    assert isinstance(date, int), 'Input is not instance of int'
    if unit is 'millis':
        return is_positive(date) and len(str(date)) == 13
    elif unit is 'seconds':
        return is_positive(date) and len(str(date)) == 10
    else:
        raise ValueError('Unknown unit "%s"' % unit)

def singleton(cls):
    """Decorator function that turns a class into a singleton."""
    import inspect
    instances = {}
    if cls.__init__ is not object.__init__:
        argspec = inspect.getfullargspec(cls.__init__)
        if len(argspec.args) != 1 or argspec.varargs or argspec.varkw:
            raise TypeError('Singleton classes cannot accept arguments to the constructor.')
    def get_instance():
        """Creates and returns the singleton object.  This function is what
        gets returned by this decorator."""
        if cls not in instances:
            instances[cls] = cls()
        return instances[cls]
    return get_instance

def transaction_manager(fn):
    """Decorator which wraps whole function into ``with transaction.manager:``."""
    @wraps(fn)
    def transaction_manager_decorator(*args, **kwargs):
        with transaction.manager:
            return fn(*args, **kwargs)
    return transaction_manager_decorator

def stringer(x):
    """Takes an object and makes it stringy
    >>> print(stringer({'a': 1, 2: 3, 'b': [1, 'c', 2.5]}))
    {'b': ['1', 'c', '2.5'], 'a': '1', '2': '3'}"""
    if isinstance(x, string_types):
        return x
    if isinstance(x, (list, tuple)):
        return [stringer(y) for y in x]
    if isinstance(x, dict):
        return dict(((stringer(a), stringer(b)) for a, b in x.items()))
    return text_type(x)

def diff_analysis(using):
    """Returns a diff string comparing the analysis defined in ES, with
    the analysis defined in Python land for the connection `using`"""
    python_analysis = collect_analysis(using)
    es_analysis = existing_analysis(using)
    return compare_dicts(es_analysis, python_analysis)

def collect_analysis(using):
    """generate the analysis settings from Python land"""
    python_analysis = defaultdict(dict)
    for index in registry.indexes_for_connection(using):
        python_analysis.update(index._doc_type.mapping._collect_analysis())
    return stringer(python_analysis)

def existing_analysis(using):
    """Get the existing analysis for the `using` Elasticsearch connection"""
    es = connections.get_connection(using)
    index_name = settings.ELASTICSEARCH_CONNECTIONS[using]['index_name']
    if es.indices.exists(index=index_name):
        return stringer(es.indices.get_settings(index=index_name)[index_name]['settings']['index'].get('analysis', {}))
    return DOES_NOT_EXIST

def is_analysis_compatible(using):
    """Returns True if the analysis defined in Python land and ES for the connection `using` are compatible"""
    python_analysis = collect_analysis(using)
    es_analysis = existing_analysis(using)
    if es_analysis == DOES_NOT_EXIST:
        return True
    for section in python_analysis:
        if section not in es_analysis:
            return False
        subdict_python = python_analysis[section]
        subdict_es = es_analysis[section]
        for name in subdict_python:
            if name not in subdict_es:
                return False
            if subdict_python[name] != subdict_es[name]:
                return False
    return True

def combined_analysis(using):
    """Combine the analysis in ES with the analysis defined in Python. The one in
    Python takes precedence"""
    python_analysis = collect_analysis(using)
    es_analysis = existing_analysis(using)
    if es_analysis == DOES_NOT_EXIST:
        return python_analysis
    for section in python_analysis:
        if section not in es_analysis:
            es_analysis[section] = python_analysis[section]
        subdict_python = python_analysis[section]
        subdict_es = es_analysis[section]
        for name in subdict_python:
            subdict_es[name] = subdict_python[name]
    return es_analysis

def parse_timezone(tzstring, default_timezone=UTC):
    """Parses ISO 8601 time zone specs into tzinfo offsets

    """
    if tzstring == 'Z':
        return default_timezone
    if tzstring is None:
        return default_timezone
    m = TIMEZONE_REGEX.match(tzstring)
    prefix, hours, minutes = m.groups()
    hours, minutes = (int(hours), int(minutes))
    if prefix == '-':
        hours = -hours
        minutes = -minutes
    return FixedOffset(hours, minutes, tzstring)

def parse_date(datestring, default_timezone=UTC):
    """Parses ISO 8601 dates into datetime objects

    The timezone is parsed from the date string. However it is quite common to
    have dates without a timezone (not strictly correct). In this case the
    default timezone specified in default_timezone is used. This is UTC by
    default."""
    if not isinstance(datestring, basestring):
        raise ParseError('Expecting a string %r' % datestring)
    m = ISO8601_REGEX.match(datestring)
    if not m:
        raise ParseError('Unable to parse date string %r' % datestring)
    groups = m.groupdict()
    tz = parse_timezone(groups['timezone'], default_timezone=default_timezone)
    if groups['fraction'] is None:
        groups['fraction'] = 0
    else:
        groups['fraction'] = int(float('0.%s' % groups['fraction']) * 1000000.0)
    if groups['hour'] == None and groups['minute'] == None and (groups['second'] == None):
        return datetime(int(groups['year']), int(groups['month']), int(groups['day']), tzinfo=tz)
    else:
        return datetime(int(groups['year']), int(groups['month']), int(groups['day']), int(groups['hour']), int(groups['minute']), int(groups['second']), int(groups['fraction']), tz)

