def this(obj, **kwargs):
    """Prints series of debugging steps to user.

    Runs through pipeline of functions and print results of each."""
    verbose = kwargs.get('verbose', True)
    if verbose:
        print('{:=^30}'.format(' whatis.this? '))
    for func in pipeline:
        s = func(obj, **kwargs)
        if s is not None:
            print(s)
