def _exprparser(expr, scope, lang=None, conf=None, configurable=None, safe=DEFAULT_SAFE, besteffort=DEFAULT_BESTEFFORT, tostr=False):
    """In charge of parsing an expression and return a python object."""
    if scope is None:
        scope = {}
    scope.update({'configurable': configurable, 'conf': conf})
    expr = REGEX_EXPR_R.sub(_refrepl(configurable=configurable, conf=conf, safe=safe, scope=scope, besteffort=besteffort), expr)
    result = resolve(expr=expr, name=lang, safe=safe, scope=scope, tostr=tostr, besteffort=besteffort)
    return result

def _ref(pname, conf=None, configurable=None, cname=None, path=None, history=0):
    """Resolve a parameter value.

    :param Configuration conf: configuration to use.
    :param str pname: parameter name.
    :param Configurable configurable: configurable.
    :param str cname: category name.
    :param str path: conf path.
    :param int history: parameter history research.
    :return: parameter.
    :raises: ParserError if conf and configurable are None."""
    result = None
    if configurable is not None:
        kwargs = {}
        if conf is not None:
            kwargs['conf'] = conf
        if path is not None:
            kwargs['paths'] = path
        if conf is None:
            conf = configurable.getconf(**kwargs)
    if conf is None:
        raise ParserError('Wrong ref parameters. Conf and configurable are both None.')
    result = conf.param(pname=pname, cname=cname, history=history)
    return result

def api(func):
    """Wraps JSONified output for JSONP requests."""
    @wraps(func)
    def decorated_function(*args, **kwargs):
        try:
            value = func(*args, **kwargs)
        except BaseException as e:
            value = {'status': 'failed', 'error': 'Unkonwn error!'}
            flask.current_app.logger.error('Unkonwn error: %s' % str(e))
            flask.current_app.logger.exception(e)
        status = 200
        mimetype = 'application/json'
        content = json.dumps(value)
        callback = flask.request.args.get('callback', False)
        if callback:
            content = str(callback) + '(' + content + ')'
            mimetype = 'application/javascript'
        return flask.current_app.response_class(content, status=status, mimetype=mimetype)
    return decorated_function

def parse_name(name):
    """Split a query name into field name, operator and whether it is
    inverted."""
    inverted, op = (False, OP_EQ)
    if name is not None:
        for op_ in (OP_NIN, OP_IN, OP_NOT, OP_LIKE):
            if name.endswith(op_):
                op = op_
                name = name[:len(name) - len(op)]
                break
        if name.startswith('!'):
            inverted = True
            name = name[1:]
    return (name, inverted, op)

