def dict2obj(d):
    """A helper function which convert a dict to an object.
    """
    if isinstance(d, (list, tuple)):
        d = [dict2obj(x) for x in d]
    if not isinstance(d, dict):
        return d
    class ObjectFromDict(object):
        pass
    o = ObjectFromDict()
    for k in d:
        o.__dict__[k] = dict2obj(d[k])
    return o

def cleanup(args):
    """cdstarcat cleanup

    Deletes objects with no bitstreams from CDSTAR and the catalog."""
    with _catalog(args) as cat:
        n, d, r = (len(cat), [], [])
        for obj in cat:
            if not obj.bitstreams:
                if obj.is_special:
                    print('removing {0} from catalog'.format(obj.id))
                    r.append(obj)
                else:
                    print('deleting {0} from CDSTAR'.format(obj.id))
                    d.append(obj)
        for obj in d:
            cat.delete(obj)
        for obj in r:
            cat.remove(obj)
        args.log.info('{0} objects deleted'.format(n - len(cat)))
        return n - len(cat)

def create(args):
    """cdstarcat create PATH

    Create objects in CDSTAR specified by PATH.
    When PATH is a file, a single object (possibly with multiple bitstreams) is created;
    When PATH is a directory, an object will be created for each file in the directory
    (recursing into subdirectories)."""
    with _catalog(args) as cat:
        for fname, created, obj in cat.create(args.args[0], {}):
            args.log.info('{0} -> {1} object {2.id}'.format(fname, 'new' if created else 'existing', obj))

def sanitize_qualifiers(repos=None, followers=None, language=None):
    """qualifiers = c repos:+42 followers:+1000 language:
    params = {'q': 'tom repos:>42 followers:>1000'}"""
    qualifiers = ''
    if repos:
        qualifiers += 'repos:{0} '.format(repos)
        qualifiers = re.sub('([+])([=a-zA-Z0-9]+)', '>\\2', qualifiers)
        qualifiers = re.sub('([-])([=a-zA-Z0-9]+)', '<\\2', qualifiers)
    if followers:
        qualifiers += 'followers:{0} '.format(followers)
        qualifiers = re.sub('([+])([=a-zA-Z0-9]+)', '>\\2', qualifiers)
        qualifiers = re.sub('([-])([=a-zA-Z0-9]+)', '<\\2', qualifiers)
    try:
        if language in ALLOWED_LANGUAGES and (not language == ''):
            qualifiers += 'language:{0} '.format(language)
        elif language == '':
            qualifiers += ''
        else:
            raise AllowedLanguagesException
    except AllowedLanguagesException as e:
        print(e)
    return qualifiers

def is_fasta(filename):
    """Check if filename is FASTA based on extension

    Return:
       Boolean"""
    if re.search('\\.fa*s[ta]*$', filename, flags=re.I):
        return True
    elif re.search('\\.fa$', filename, flags=re.I):
        return True
    else:
        return False

def rescale(img, size, mode=None):
    """Rescale an image to given size, crop if mode specified
     * img: a PIL image object
     * size: a 2-tuple of (width, height); at least one must be specified
     * mode: CROP_TL keep the top left part, CROP_BR the bottom right part"""
    assert size[0] or size[1], 'Must provide a width or a height'
    size = list(size)
    crop = size[0] and size[1]
    if not size[0]:
        size[0] = int(img.size[0] * size[1] / float(img.size[1]))
    if not size[1]:
        size[1] = int(img.size[1] * size[0] / float(img.size[0]))
    if crop:
        b = img.size[0] > img.size[1]
        crop_size = (img.size[b], int(img.size[b] * size[0] / float(size[1])))
        if mode == CROP_TL:
            img = img.crop((0, 0, crop_size[0], crop_size[1]))
        elif mode == CROP_BR:
            img = img.crop((img.size[0] - crop_size[0], img.size[1] - crop_size[1], img.size[0], img.size[1]))
    return img.resize(size, Image.ANTIALIAS)

