def make_property(prop_defs, prop_name, cls_names=[], hierarchy=[]):
    """Generates a property class from the defintion dictionary

    args:
        prop_defs: the dictionary defining the property
        prop_name: the base name of the property
        cls_name: the name of the rdf_class with which the property is
                  associated"""
    register = False
    try:
        cls_names.remove('RdfClassBase')
    except ValueError:
        pass
    if cls_names:
        new_name = '%s_%s' % (prop_name.pyuri, '_'.join(cls_names))
        prop_defs['kds_appliesToClass'] = cls_names
    elif not cls_names:
        cls_names = [Uri('kdr_AllClasses')]
        register = True
        new_name = prop_name
    else:
        new_name = prop_name
    new_prop = types.new_class(new_name, (RdfPropertyBase, list), {'metaclass': RdfPropertyMeta, 'prop_defs': prop_defs, 'class_names': cls_names, 'prop_name': prop_name, 'hierarchy': hierarchy})
    if register:
        global properties
        global domain_props
        properties[new_name] = new_prop
        for domain in new_prop.rdfs_domain:
            try:
                domain_props[domain][prop_name] = prop_defs
            except KeyError:
                domain_props[domain] = {}
                domain_props[domain][prop_name] = prop_defs
            except TypeError:
                pass
    return new_prop

def get_properties(cls_def):
    """cycles through the class definiton and returns all properties"""
    prop_list = {prop: value for prop, value in cls_def.items() if 'rdf_Property' in value.get('rdf_type', '') or value.get('rdfs_domain')}
    return prop_list

def filter_prop_defs(prop_defs, hierarchy, cls_names):
    """Reads through the prop_defs and returns a dictionary filtered by the
        current class

    args:
        prop_defs: the defintions from the rdf vocabulary defintion
        cls_object: the class object to tie the property
        cls_names: the name of the classes"""
    def _is_valid(test_list, valid_list):
        """reads the list of classes in appliesToClass and returns whether
            the test_list matches

        args:
            test_list: the list of clasees to test against
            valid_list: list of possible matches"""
        for test in test_list:
            if test in valid_list:
                return True
        return False
    new_dict = {}
    valid_classes = [Uri('kdr_AllClasses')] + cls_names + hierarchy
    for def_name, value in prop_defs.items():
        new_dict[def_name] = []
        empty_def = []
        try:
            for item in value:
                if item.get('kds_appliesToClass'):
                    if _is_valid(item['kds_appliesToClass'], valid_classes):
                        new_dict[def_name].append(item)
                else:
                    empty_def.append(item)
            if not new_dict[def_name]:
                new_dict[def_name] = empty_def
        except AttributeError:
            new_dict[def_name] = value
    return new_dict

def unique_append(self, value):
    """function for only appending unique items to a list.
    #! consider the possibility of item using this to a set"""
    if value not in self:
        try:
            super(self.__class__, self).append(Uri(value))
        except AttributeError as err:
            if isinstance(value, MODULE.rdfclass.RdfClassBase):
                super(self.__class__, self).append(value)
            else:
                raise err

def certify_iterable_schema(value, schema=None, required=True):
    """Certify an iterable against a schema.

    :param iterable value:
        The iterable to certify against the schema.
    :param iterable schema:
        The schema to use
    :param bool required:
        Whether the value can't be `None`. Defaults to True.
    :return:
        The validated iterable.
    :rtype:
        iterable"""
    if schema is not None:
        if len(schema) != len(value):
            raise CertifierValueError('encountered {extra} extra items'.format(extra=len(value) - len(schema)), value=value, required=required)
        for index, certifier in enumerate(schema):
            try:
                certifier(value=value[index])
            except CertifierError as exc:
                six.raise_from(CertifierValueError(message='invalid value {value!r} for item {index}'.format(index=index, value=value[index]), value=value, required=required), exc)

def get_es_action_item(data_item, action_settings, es_type, id_field=None):
    """This method will return an item formated and ready to append
    to the action list"""
    action_item = dict.copy(action_settings)
    if id_field is not None:
        id_val = first(list(get_dict_key(data_item, id_field)))
        if id_val is not None:
            action_item['_id'] = id_val
    elif data_item.get('id'):
        if data_item['id'].startswith('%s/' % action_settings['_index']):
            action_item['_id'] = '/'.join(data_item['id'].split('/')[2:])
        else:
            action_item['_id'] = data_item['id']
    if data_item.get('data'):
        action_item['_source'] = data_item['data']
    else:
        action_item['_source'] = data_item
    action_item['_type'] = es_type
    return action_item

def main():
    """if lk.py is run as a script, this function will run"""
    parser = build_parser()
    args = parser.parse_args()
    flags = re.LOCALE
    if args.dot_all:
        flags |= re.DOTALL
    if args.ignorecase:
        flags |= re.IGNORECASE
    if args.unicode:
        flags |= re.UNICODE
    if args.multiline:
        flags |= re.MULTILINE
    exclude_path_flags = re.UNICODE | re.LOCALE
    exclude_path_regexes = [re.compile(pattern, exclude_path_flags) for pattern in args.exclude_path_patterns]
    pattern = re.escape(args.pattern) if args.escape else args.pattern
    try:
        search_manager = SearchManager(regex=re.compile(pattern, flags), number_processes=args.number_processes, search_hidden=args.search_hidden, follow_links=args.follow_links, search_binary=args.search_binary, use_ansi_colors=args.use_ansi_colors, print_stats=args.print_stats, exclude_path_regexes=exclude_path_regexes, command_strings=args.command_strings)
        search_manager.enqueue_directory(args.directory)
        search_manager.process_queue()
    except (KeyboardInterruptError, KeyboardInterrupt):
        sys.stdout.write('\n')
        exit(1)

def _is_plugin_disabled(plugin):
    """Determines if provided plugin is disabled from running for the
    active task."""
    item = _registered.get(plugin.name)
    if not item:
        return False
    _, props = item
    return bool(props.get('disabled'))

def _setup_events(plugin):
    """Handles setup or teardown of event hook registration for the provided
    plugin.

    `plugin`
        ``Plugin`` class."""
    events = plugin.events
    if events and isinstance(events, (list, tuple)):
        for event in [e for e in events if e in _EVENT_VALS]:
            register('event', event, plugin)

def _setup_options(plugin):
    """Handles setup or teardown of option hook registration for the provided
    plugin.

    `plugin`
        ``Plugin`` class."""
    options = plugin.options
    if options and isinstance(options, (list, tuple)):
        for props in options:
            if isinstance(props, dict):
                if 'block' in props and 'options' in props:
                    block = props['block']
                    option_list = props['options']
                    for props in option_list:
                        if isinstance(props, dict):
                            name = props.pop('name', None)
                            if name:
                                key = '{0}_{1}'.format(block, name)
                                register('option', key, plugin, props)
                else:
                    name = props.pop('name', None)
                    if name:
                        register('option', name, plugin, props)

def get_registered(option_hooks=None, event_hooks=None, command_hooks=None, root_access=None, task_active=True):
    """Returns a generator of registered plugins matching filters.

    `option_hooks`
        Boolean to include or exclude plugins using option hooks.
    `event_hooks`
        Boolean to include or exclude task event plugins.
    `command_hooks`
        Boolean to include or exclude command plugins.
    `root_access`
        Boolean to include or exclude root plugins.
    `task_active`
        Set to ``False`` to not filter by task-based plugins.

    Returns list of ``Plugin`` instances."""
    plugins = []
    for _, item in _registered:
        plugin, type_info = item
        if task_active:
            if type_info.get('disabled'):
                continue
        elif plugin.options or plugin.task_only:
            continue
        if not option_hooks is None:
            if option_hooks != bool(type_info.get('option')):
                continue
        if not event_hooks is None:
            if event_hooks != bool(type_info.get('event')):
                continue
        if not command_hooks is None:
            if command_hooks != bool(type_info.get('command')):
                continue
        if not root_access is None:
            if root_access != plugin.needs_root:
                continue
        plugins.append(plugin)
    return plugins

def run_event_hooks(event, task):
    """Executes registered task event plugins for the provided event and task.

    `event`
        Name of the event to trigger for the plugin:
            ('task_start', 'task_run', 'task_end')
    `task`
        ``Task`` instance."""
    call_chain = _event_hooks.get(event)
    if call_chain:
        event_methods = {'task_start': 'on_taskstart', 'task_run': 'on_taskrun', 'task_end': 'on_taskend'}
        method = event_methods.get(event)
        if method:
            for _, get_plugin in call_chain:
                plugin_obj = get_plugin()
                if not _is_plugin_disabled(plugin_obj):
                    try:
                        getattr(plugin_obj, method)(task)
                    except Exception:
                        pass

def _recursive_merge(dct, merge_dct, raise_on_missing):
    """Recursive dict merge

    This modifies `dct` in place. Use `copy.deepcopy` if this behavior is not desired."""
    for k, v in merge_dct.items():
        if k in dct:
            if isinstance(dct[k], dict) and isinstance(merge_dct[k], BaseMapping):
                dct[k] = _recursive_merge(dct[k], merge_dct[k], raise_on_missing)
            else:
                dct[k] = merge_dct[k]
        elif isinstance(dct, Extensible):
            dct[k] = merge_dct[k]
        else:
            message = "Unknown configuration key: '{k}'".format(k=k)
            if raise_on_missing:
                raise KeyError(message)
            else:
                logging.getLogger(__name__).warning(message)
    return dct

def _create_flat_pointers(dct, key_stack=()):
    """Create a flattened dictionary of "key stacks" -> (value container, key)
    """
    for k in dct.keys():
        current_key = key_stack + (k,)
        if isinstance(dct[k], BaseMapping):
            for flat_ptr in _create_flat_pointers(dct[k], current_key):
                yield flat_ptr
        else:
            yield (current_key, dct, k)

def cross(environment, book, row, sheet_source, column_source, column_key):
    """Returns a single value from a column from a different dataset, matching by the key."""
    a = book.sheets[sheet_source]
    return environment.copy(a.get(**{column_key: row[column_key]})[column_source])

def column(environment, book, sheet_name, sheet_source, column_source, column_key):
    """Returns an array of values from column from a different dataset, ordered as the key."""
    a = book.sheets[sheet_source]
    b = book.sheets[sheet_name]
    return environment.copy([a.get(**{column_key: row[column_key]})[column_source] for row in b.all()])

