def resolvepy(expr, safe=DEFAULT_SAFE, tostr=DEFAULT_TOSTR, scope=DEFAULT_SCOPE, besteffort=DEFAULT_BESTEFFORT):
    """Resolve input expression.

    :param str expr: configuration expression to resolve in this language.
    :param bool safe: safe run execution context (True by default).
    :param bool tostr: format the result.
    :param dict scope: execution scope (contains references to expression
        objects).
    :param bool besteffort: try to resolve unknown variable name with execution
        runtime."""
    result = None
    _eval = safe_eval if safe else eval
    _expr = expr
    scope = {} if scope is None else scope.copy()
    while True:
        try:
            result = _eval(_expr, scope)
        except (AttributeError, NameError) as nex:
            if not besteffort:
                raise
            arg = nex.args[0]
            missing = MISSING_NAME_REGEX.findall(arg)[-1]
            try:
                _expr = sub(MISSING_VARIABLE.format(missing), genrepl(scope=scope), _expr)
            except ImportError:
                raise nex
        else:
            break
    if tostr:
        result = str(result)
    return result

def round_to_5_minutes(moment):
    """Round datetime to 5 minutes boundary:

    - if moment.minute < 5 -> moment.minute = 0
    - if moment.minute >= 5 -> moment.minute = 0

    :param moment: a :class:`datetime.datetime` instance."""
    return moment - timedelta(minutes=moment.minute % 5, seconds=moment.second)

def image(radar, at=None):
    """Retrieve a radar image.

    :param radar: radar station no.
    :param at: stat datetime, defaults to now."""
    at = round_to_5_minutes(at or datetime.utcnow())
    return ''.join(['http://image.nmc.cn/product', '/{0}'.format(at.year), '/{0}'.format(at.strftime('%Y%m')), '/{0}'.format(at.strftime('%Y%m%d')), '/RDCP/medium/SEVP_AOC_RDCP_SLDAS_EBREF_', '{0}_L88_PI_'.format(radar), '{0}00000.GIF'.format(at.strftime('%Y%m%d%H%M'))])

def get_devicelist(home_hub_ip='192.168.1.254'):
    """Retrieve data from BT Home Hub 5 and return parsed result.
    """
    url = 'http://{}/'.format(home_hub_ip)
    try:
        response = requests.get(url, timeout=5)
    except requests.exceptions.Timeout:
        _LOGGER.exception('Connection to the router timed out')
        return
    if response.status_code == 200:
        return parse_devicelist(response.text)
    else:
        _LOGGER.error('Invalid response from Home Hub: %s', response)

def parse_devicelist(data_str):
    """Parse the BT Home Hub 5 data format."""
    p = HTMLTableParser()
    p.feed(data_str)
    known_devices = p.tables[9]
    devices = {}
    for device in known_devices:
        if len(device) == 5 and device[2] != '':
            devices[device[2]] = device[1]
    return devices

def log_level(level):
    """Attempt to convert the given argument into a log level.

    Log levels are represented as integers, where higher values are more
    severe.  If the given level is already an integer, it is simply returned.
    If the given level is a string that can be converted into an integer, it is
    converted and that value is returned.  Finally, if the given level is a
    string naming one of the levels defined in the logging module, return that
    level.  If none of those conditions are met, raise a ValueError."""
    from six import string_types
    if isinstance(level, int):
        return level
    if isinstance(level, string_types):
        try:
            return int(level)
        except ValueError:
            pass
        try:
            return getattr(logging, level.upper())
        except AttributeError:
            pass
    raise ValueError("cannot convert '{}' into a log level".format(level))

def verbosity(verbosity):
    """Convert the number of times the user specified '-v' on the command-line
    into a log level."""
    verbosity = int(verbosity)
    if verbosity == 0:
        return logging.WARNING
    if verbosity == 1:
        return logging.INFO
    if verbosity == 2:
        return logging.DEBUG
    if verbosity >= 3:
        return 0
    else:
        raise ValueError

def ingest_csv(csv_data, message_set):
    """Expecting data in the following format:
    message_id,en,safe,af,safe,zu,safe,xh,safe,ve,safe,tn,safe,ts,safe,ss,safe,st,safe,nso,safe,nr,safe"""
    records = csv.DictReader(csv_data)
    for line in records:
        for key in line:
            if key not in ['message_id', 'safe'] and line[key] != '':
                try:
                    with transaction.atomic():
                        message = Message()
                        message.message_set = message_set
                        message.sequence_number = line['message_id']
                        message.lang = key
                        message.content = line[key]
                        message.save()
                except (IntegrityError, ValueError) as e:
                    message = None
                    standard_logger.error(e)

def handle_encodnig(html):
    """Look for encoding in given `html`. Try to convert `html` to utf-8.

    Args:
        html (str): HTML code as string.

    Returns:
        str: HTML code encoded in UTF."""
    encoding = _get_encoding(dhtmlparser.parseString(html.split('</head>')[0]))
    if encoding == 'utf-8':
        return html
    return html.decode(encoding).encode('utf-8')

def _stage2_bootstrap():
    """This is the second bootstrap stage. It should be called
    _immediately_ after importing this module the first time. The
    reason behind this process is to allow this module to be inserted
    as a replacement for 'couchbase._libcouchbase' while not loading
    dependencies which depend on that name. The stage2 loads these
    dependencies which ultimately depend on ourselves :)"""
    from couchbase_ffi.result import Item, Result, ObserveInfo, MultiResult, ValueResult, OperationResult, HttpResult, AsyncResult
    from couchbase_ffi.n1ql import _N1QLParams
    globals().update(locals())
    from couchbase_ffi.bucket import Bucket
    globals()['Bucket'] = Bucket
    from couchbase import _bootstrap
    globals()['Transcoder'] = None
    import couchbase.transcoder
    class _Transcoder(couchbase.transcoder.TranscoderPP):
        def _do_json_encode(self, value):
            return PyCBC.json_encode(value)
        def _do_json_decode(self, value):
            return PyCBC.json_decode(value)
        def _do_pickle_encode(self, value):
