    globals()['Transcoder'] = _Transcoder
    couchbase.transcoder.Transcoder = _Transcoder

def convert_Decimal(x, encoder):
    """Called when an instance of U{decimal.Decimal<http://
    docs.python.org/library/decimal.html#decimal-objects>} is about to be
    encoded to an AMF stream.

    @return: If the encoder is in 'strict' mode then C{x} will be converted to
        a float. Otherwise an L{pyamf.EncodeError} with a friendly message is
        raised."""
    if encoder.strict is False:
        return float(x)
    raise pyamf.EncodeError('Unable to encode decimal.Decimal instances as there is no way to guarantee exact conversion. Use strict=False to convert to a float.')

def _parse_pages_binding(details):
    """Parse number of pages and binding of the book.

    Args:
        details (obj): HTMLElement containing slice of the page with details.

    Returns:
        (pages, binding): Tuple with two string or two None."""
    pages = _get_td_or_none(details, 'ctl00_ContentPlaceHolder1_tblRowRozsahVazba')
    if not pages:
        return (None, None)
    binding = None
    if '/' in pages:
        binding = pages.split('/')[1].strip()
        pages = pages.split('/')[0].strip()
    if not pages:
        pages = None
    return (pages, binding)

def _parse_ISBN_EAN(details):
    """Parse ISBN and EAN.

    Args:
        details (obj): HTMLElement containing slice of the page with details.

    Returns:
        (ISBN, EAN): Tuple with two string or two None."""
    isbn_ean = _get_td_or_none(details, 'ctl00_ContentPlaceHolder1_tblRowIsbnEan')
    if not isbn_ean:
        return (None, None)
    ean = None
    isbn = None
    if '/' in isbn_ean:
        isbn, ean = isbn_ean.split('/')
        isbn = isbn.strip()
        ean = ean.strip()
    else:
        isbn = isbn_ean.strip()
    if not isbn:
        isbn = None
    return (isbn, ean)

def norm_page_cnt(page, max_number=None):
    """Normalize a integer (page).

    * Ensure that it is greater than Zero, and is not None.
        - If less than 1, or None, set it to 1

    * if max_number is None, then do not check for max_number
        * if greater than max_number, reset it to be max_number"""
    if page == None or page < 1:
        page = 1
    if max_number != None:
        if page > max_number:
            page = max_number
    return page

