def is_default(name=None, index=None):
    """returns True if the specified configuration is the default one"""
    if not is_configured():
        raise JutException('No configurations available, please run `jut config add`')
    count = 1
    for configuration in _CONFIG.sections():
        if index != None:
            if _CONFIG.has_option(configuration, 'default') and count == index:
                return True
        if name != None:
            if _CONFIG.has_option(configuration, 'default') and configuration == name:
                return True
        count += 1
    return False

def key_event_to_name(event):
    """Converts a keystroke event into a corresponding key name.
    """
    key_code = event.key()
    modifiers = event.modifiers()
    if modifiers & QtCore.Qt.KeypadModifier:
        key = keypad_map.get(key_code)
    else:
        key = None
    if key is None:
        key = key_map.get(key_code)
    name = ''
    if modifiers & QtCore.Qt.ControlModifier:
        name += 'Ctrl'
    if modifiers & QtCore.Qt.AltModifier:
        name += '-Alt' if name else 'Alt'
    if modifiers & QtCore.Qt.MetaModifier:
        name += '-Meta' if name else 'Meta'
    if modifiers & QtCore.Qt.ShiftModifier and (name != '' or (key is not None and len(key) > 1)):
        name += '-Shift' if name else 'Shift'
    if key:
        if name:
            name += '-'
        name += key
    return name

def _basic_field_data(field, obj):
    """Returns ``obj.field`` data as a dict"""
    value = field.value_from_object(obj)
    return {Field.TYPE: FieldType.VAL, Field.VALUE: value}

def dump_model(obj):
    """Returns ``obj`` as a dict.

    Returnded dic has a form of:
    {
        'field_name': {
            'type': `FieldType`,
            'value': field value,
            # if field is a relation, it also has:
            'rel': {
                'db_table': model db table,
                'app_label': model app label,
                'model_name': model name
            }
        }
    }"""
    data = {}
    for field in obj._meta.fields:
        if isinstance(field, RELATED_FIELDS):
            field_data = _related_field_data(field, obj)
        else:
            field_data = _basic_field_data(field, obj)
        data[field.name] = field_data
    if obj.pk:
        for m2m in obj._meta.many_to_many:
            field_data = _m2m_field_data(m2m, obj)
            data[m2m.name] = field_data
    return data

def get_view_model(cls):
    """Get the model to use in the filter_class by inspecting
    the queryset or by using a declared auto_filters_model"""
    msg = 'When using get_queryset you must set a auto_filters_model field in the viewset'
    if cls.queryset is not None:
        return cls.queryset.model
    else:
        assert hasattr(cls, 'auto_filters_model'), msg
        return cls.auto_filters_model

def auto_filters(cls):
    """Adds a dynamic filterclass to a viewset
    with all auto filters available for the field type
    that are declared in a tuple auto_filter_fields

    @auto_filters
    def class(...):
        ...
        auto_filters_fields('id', 'location', 'category')"""
    msg = 'Viewset must have auto_filters_fields or auto_filters_exclude attribute when using auto_filters decorator'
    if not hasattr(cls, 'auto_filters_fields') and (not hasattr(cls, 'auto_filters_exclude')):
        raise AssertionError(msg)
    dict_ = {}
    view_model = get_view_model(cls)
    auto_filters_fields = get_auto_filters_fields(cls, view_model)
    for auto_filter in auto_filters_fields:
        dict_[auto_filter] = AutoFilters(name=auto_filter)
    dict_['Meta'] = type('Meta', (object,), {'model': view_model, 'fields': ()})
    filter_class = type('DynamicFilterClass', (FilterSet,), dict_)
    cls.filter_class = filter_class
    return cls

def _map_generator(f, generator):
    """Apply ``f`` to the results of the given bi-directional generator.

    Unfortunately, generator comprehension (``f(x) for x in gen``) does not
    work for as expected for bi-directional generators. It won't send
    exceptions and results back.

    This function implements a map function for generators that sends values
    and exceptions back and forth as expected."""
    item = next(generator)
    while True:
        try:
            result = (yield f(item))
        except Exception:
            item = generator.throw(*sys.exc_info())
        else:
            item = generator.send(result)

