def calc_sha(obj):
    """Calculates the base64-encoded SHA hash of a file."""
    try:
        pathfile = Path(obj)
    except UnicodeDecodeError:
        pathfile = None
    sha = hashlib.sha256()
    try:
        if pathfile and pathfile.exists():
            return base64.b64encode(pathfile.read_hash('SHA256'))
    except TypeError:
        if isinstance(obj, string_types):
            pass
        else:
            raise
    if isinstance(obj, string_types):
        sha.update(obj)
    elif hasattr(obj, 'read'):
        while True:
            d = obj.read(8192)
            if not d:
                break
            sha.update(d)
    else:
        return None
    r = sha.digest()
    r = base64.b64encode(r)
    return r

def mro(*bases):
    """Calculate the Method Resolution Order of bases using the C3 algorithm.

    Suppose you intended creating a class K with the given base classes. This
    function returns the MRO which K would have, *excluding* K itself (since
    it doesn't yet exist), as if you had actually created the class.

    Another way of looking at this, if you pass a single class K, this will
    return the linearization of K (the MRO of K, *including* itself).

    Found at:
    http://code.activestate.com/recipes/577748-calculate-the-mro-of-a-class/"""
    seqs = [list(C.__mro__) for C in bases] + [list(bases)]
    res = []
    while True:
        non_empty = list(filter(None, seqs))
        if not non_empty:
            return tuple(res)
        for seq in non_empty:
            candidate = seq[0]
            not_head = [s for s in non_empty if candidate in s[1:]]
            if not_head:
                candidate = None
            else:
                break
        if not candidate:
            raise TypeError('inconsistent hierarchy, no C3 MRO is possible')
        res.append(candidate)
        for seq in non_empty:
            if seq[0] == candidate:
                del seq[0]

def _copy_ancestor_docstring(mro_list, func):
    """Decorator to set docstring for *func* from *mro*"""
    if func.__doc__ is not None:
        raise RuntimeError('Function already has docstring')
    for cls in mro_list:
        super_fn = getattr(cls, func.__name__, None)
        if super_fn is None:
            continue
        func.__doc__ = super_fn.__doc__
        break
    else:
        raise RuntimeError("Can't inherit docstring for %s: method does not exist in superclass" % func.__name__)
    return func

def define_constrained_subtype(prefix, base, blockednames, clsdict=None):
    """Define a subtype which blocks a list of methods.

    @param prefix: The subtype name prefix.  This is prepended to the
                   base type name.  This convention is baked in for
                   API consistency.

    @param base: The base type to derive from.

    @param blockednames: A list of method name strings.  All of these
                         will be blocked.

    @param clsdict: None or a dict which will be modified to become the
                    subtype class dict.

    @return: The new subtype.

    @raise: OverwriteError - If clsdict contains an entry in blockednames."""
    name = prefix + base.__name__
    clsdict = clsdict or {}
    doc = clsdict.get('__doc__', '')
    doc = 'An {} extension of {}.\n{}'.format(prefix, base.__name__, doc)
    clsdict['__doc__'] = doc
    setitem_without_overwrite(clsdict, 'get_blocked_method_names', lambda self: iter(blockednames))
    for bname in blockednames:
        setitem_without_overwrite(clsdict, bname, ConstraintError.block(getattr(base, bname)))
    return type(name, (base,), clsdict)

def setitem_without_overwrite(d, key, value):
    """@param d: An instance of dict, that is: isinstance(d, dict)
    @param key: a key
    @param value: a value to associate with the key

    @return: None

    @raise: OverwriteError if the key is already present in d."""
    if key in d:
        raise OverwriteError(key, value, d[key])
    else:
        dict.__setitem__(d, key, value)

