def smart_content_type_for_model(model):
    """Returns the Django ContentType for a given model. If model is a proxy model, the proxy model's ContentType will
    be returned. This differs from Django's standard behavior - the default behavior is to return the parent
    ContentType for proxy models."""
    try:
        from django.contrib.contenttypes.models import ContentType
    except ImportError:
        print('Django is required but cannot be imported.')
        raise
    if model._meta.proxy:
        return ContentType.objects.get(app_label=model._meta.app_label, model=model._meta.object_name.lower())
    else:
        return ContentType.objects.get_for_model(model)

def normalize_url(base_url, rel_url):
    """Normalize the `url` - from relative, create absolute URL.

    Args:
        base_url (str): Domain with ``protocol://`` string
        rel_url (str): Relative or absolute url.

    Returns:
        str/None: Normalized URL or None if `url` is blank."""
    if not rel_url:
        return None
    if not is_absolute_url(rel_url):
        rel_url = rel_url.replace('../', '/')
        if not base_url.endswith('/') and (not rel_url.startswith('/')):
            return base_url + '/' + rel_url.replace('../', '/')
        return base_url + rel_url.replace('../', '/')
    return rel_url

def has_param(param):
    """Generate function, which will check `param` is in html element.

    This function can be used as parameter for .find() method in HTMLElement."""
    def has_param_closure(element):
        """Look for `param` in `element`."""
        if element.params.get(param, '').strip():
            return True
        return False
    return has_param_closure

def must_contain(tag_name, tag_content, container_tag_name):
    """Generate function, which checks if given element contains `tag_name` with
    string content `tag_content` and also another tag named
    `container_tag_name`.

    This function can be used as parameter for .find() method in HTMLElement."""
    def must_contain_closure(element):
        matching_tags = element.match(tag_name, absolute=True)
        if not matching_tags:
            return False
        if matching_tags[0].getContent() != tag_content:
            return False
        if container_tag_name and (not element.match(container_tag_name, absolute=True)):
            return False
        return True
    return must_contain_closure

def get_line(s, bold=False, underline=False, blinking=False, color=None, bgcolor=None, update_line=False):
    """Returns a string with the given formatting."""
    parts = []
    if update_line:
        parts.append(_UPDATE_LINE)
    for val in [color, bgcolor]:
        if val:
            parts.append(val)
    if bold:
        parts.append(_TURN_BOLD_MODE_ON)
    if underline:
        parts.append(_TURN_UNDERLINE_MODE_ON)
    if blinking:
        parts.append(_TURN_BLINKING_MODE_ON)
    parts.append(s)
    parts.append(_TURN_OFF_CHARACTER_ATTS)
    result = ''.join(parts)
    return result

