    args:
        namespace: RdfNamespace or tuple in the format of (prefix, uri,)
        value: end value to attach to the namespace"""
    if namespace[0]:
        return '%s_%s' % (namespace[0], value)
    else:
        return 'pyuri_%s_%s' % (base64.b64encode(bytes(namespace[1], 'utf-8')).decode(), value)

def get_relation_by_type_list(parser, token):
    """Gets list of relations from object identified by a content type.

    Syntax::

        {% get_relation_list [content_type_app_label.content_type_model] for [object] as [varname] [direction] %}"""
    tokens = token.contents.split()
    if len(tokens) not in (6, 7):
        raise template.TemplateSyntaxError('%r tag requires 6 arguments' % tokens[0])
    if tokens[2] != 'for':
        raise template.TemplateSyntaxError("Third argument in %r tag must be 'for'" % tokens[0])
    if tokens[4] != 'as':
        raise template.TemplateSyntaxError("Fifth argument in %r tag must be 'as'" % tokens[0])
    direction = 'forward'
    if len(tokens) == 7:
        direction = tokens[6]
    return RelationByTypeListNode(name=tokens[1], obj=tokens[3], as_var=tokens[5], direction=direction)

def timemeter(msg=None):
    """Timer meter

        Use this annotation method can calculate the execute time.
    :param msg: custom message output
    :return: fn values"""
    def _time_meter(fn):
        @functools.wraps(fn)
        def _wrapper(*args, **kwargs):
            mark = timeit.default_timer()
            result = fn(*args, **kwargs)
            cost = timeit.default_timer() - mark
            if msg:
                logger.info(msg, cost)
            else:
                logger.info('Execute <%s.%s> method cost %s seconds.', fn.__module__, fn.__name__, cost)
            return result
        return _wrapper
    return _time_meter

def dict_camel_to_snake_case(camel_dict, convert_keys=True, convert_subkeys=False):
    """Recursively convert camelCased keys for a camelCased dict into snake_cased keys

    :param camel_dict: Dictionary to convert
    :param convert_keys: Whether the key should be converted
    :param convert_subkeys: Whether to also convert the subkeys, in case they are named properties of the dict
    :return:"""
    converted = {}
    for key, value in camel_dict.items():
        if isinstance(value, dict):
            new_value = dict_camel_to_snake_case(value, convert_keys=convert_subkeys, convert_subkeys=True)
        elif isinstance(value, list):
            new_value = []
            for subvalue in value:
                new_subvalue = dict_camel_to_snake_case(subvalue, convert_keys=convert_subkeys, convert_subkeys=True) if isinstance(subvalue, dict) else subvalue
                new_value.append(new_subvalue)
        else:
            new_value = value
        new_key = to_snake_case(key) if convert_keys else key
        converted[new_key] = new_value
    return converted

def dict_snake_to_camel_case(snake_dict, convert_keys=True, convert_subkeys=False):
    """Recursively convert a snake_cased dict into a camelCased dict

    :param snake_dict: Dictionary to convert
    :param convert_keys: Whether the key should be converted
    :param convert_subkeys: Whether to also convert the subkeys, in case they are named properties of the dict
    :return:"""
    converted = {}
    for key, value in snake_dict.items():
        if isinstance(value, dict):
            new_value = dict_snake_to_camel_case(value, convert_keys=convert_subkeys, convert_subkeys=True)
        elif isinstance(value, list):
            new_value = []
            for subvalue in value:
                new_subvalue = dict_snake_to_camel_case(subvalue, convert_keys=convert_subkeys, convert_subkeys=True) if isinstance(subvalue, dict) else subvalue
                new_value.append(new_subvalue)
        else:
            new_value = value
        new_key = to_camel_case(key) if convert_keys else key
        converted[new_key] = new_value
    return converted

def dubstep(client, channel, nick, message, matches):
    """Dubstep can be described as a rapid succession of wub wubs, wow wows, and yep yep yep yeps"""
    now = time.time()
    if dubstep._last and now - dubstep._last > WUB_TIMEOUT:
        dubstep._counts[channel] = 0
    dubstep._last = now
    if dubstep._counts[channel] >= MAX_WUBS:
        dubstep._counts[channel] = 0
        return u'STOP! MY HEAD IS VIBRATING'
    else:
        dubstep._counts[channel] += 1
        return u'wubwub' * dubstep._counts[channel] * random.randint(1, 4)

