def copyFile(src, dest):
    """Copies a source file to a destination whose path may not yet exist.

    Keyword arguments:
    src -- Source path to a file (string)
    dest -- Path for destination file (also a string)"""
    try:
        if os.path.isfile(src):
            dpath, dfile = os.path.split(dest)
            if not os.path.isdir(dpath):
                os.makedirs(dpath)
            if not os.path.exists(dest):
                touch(dest)
            try:
                shutil.copy2(src, dest)
            except shutil.Error as e:
                logging.exception('Error: %s' % e)
            except IOError as e:
                logging.exception('Error: %s' % e.strerror)
    except:
        logging.exception('Error: src to copy does not exist.')

def _dbus_notify(title, message):
    """Shows system notification message via dbus.

    `title`
        Notification title.
    `message`
        Notification message."""
    try:
        bus = dbus.SessionBus()
        obj = bus.get_object('org.freedesktop.Notifications', '/org/freedesktop/Notifications')
        if obj:
            iface = dbus.Interface(obj, 'org.freedesktop.Notifications')
            if iface:
                iface.Notify('Focus', 0, '', title, message, [], {}, 5)
    except dbus.exceptions.DBusException:
        pass

