    return {'type': typ, 'value': num, 'line': line}

def transform(src, dst, converter, overwrite=False, stream=True, chunksize=1024 ** 2, **kwargs):
    """A file stream transform IO utility function.

    :param src: original file path
    :param dst: destination file path
    :param converter: binary content converter function
    :param overwrite: default False,
    :param stream: default True, if True, use stream IO mode, chunksize has to
      be specified.
    :param chunksize: default 1MB"""
    if not overwrite:
        if Path(dst).exists():
            raise EnvironmentError("'%s' already exists!" % dst)
    with open(src, 'rb') as f_input:
        with open(dst, 'wb') as f_output:
            if stream:
                if chunksize > 1024 ** 2 * 10:
                    chunksize = 1024 ** 2 * 10
                elif chunksize < 1024 ** 2:
                    chunksize = 1024 ** 2
                while 1:
                    content = f_input.read(chunksize)
                    if content:
                        f_output.write(converter(content, **kwargs))
                    else:
                        break
            else:
                f_output.write(converter(f_input.read(), **kwargs))

def usetz_now():
    """Determine current time depending on USE_TZ setting.

    Affects Django 1.4 and above only. if `USE_TZ = True`, then returns
    current time according to timezone, else returns current UTC time."""
    USE_TZ = getattr(settings, 'USE_TZ', False)
    if USE_TZ and DJANGO_VERSION >= '1.4':
        return now()
    else:
        return datetime.utcnow()

def only_for(theme, redirect_to='/', raise_error=None):
    """Decorator for restrict access to views according by list of themes.

    Params:

        * ``theme`` - string or list of themes where decorated view must be
        * ``redirect_to`` - url or name of url pattern for redirect
            if CURRENT_THEME not in themes
        * ``raise_error`` - error class for raising

    Example:

    .. code:: python

        # views.py

        from django_vest import only_for

        @only_for('black_theme')
        def my_view(request):
            ..."""
    def check_theme(*args, **kwargs):
        if isinstance(theme, six.string_types):
            themes = (theme,)
        else:
            themes = theme
        if settings.CURRENT_THEME is None:
            return True
        result = settings.CURRENT_THEME in themes
        if not result and raise_error is not None:
            raise raise_error
        return result
    return user_passes_test(check_theme, login_url=redirect_to)

