def choice(opts, default=1, text='Please make a choice.'):
    """Prompt the user to select an option
    @param  opts:   List of tuples containing options in (key, value) format - value is optional
    @type   opts:   list of tuple
    @param  text:   Prompt text
    @type   text:   str"""
    opts_len = len(opts)
    opts_enum = enumerate(opts, 1)
    opts = list(opts)
    for key, opt in opts_enum:
        click.echo('[{k}] {o}'.format(k=key, o=opt[1] if isinstance(opt, tuple) else opt))
    click.echo('-' * 12)
    opt = click.prompt(text, default, type=click.IntRange(1, opts_len))
    opt = opts[opt - 1]
    return opt[0] if isinstance(opt, tuple) else opt

def domain_parse(url):
    """urlparse wrapper for user input
    @type   url:    str
    @rtype: urlparse.ParseResult"""
    url = url.lower()
    if not url.startswith('http://') and (not url.startswith('https://')):
        url = '{schema}{host}'.format(schema='http://', host=url)
    url = urlparse(url)
    if not url.hostname:
        raise ValueError('Invalid domain provided')
    url = urlparse('{scheme}://{host}'.format(scheme=url.scheme, host=url.hostname.lstrip('www.')))
    return url

def http_session(cookies=None):
    """Generate a Requests session
    @param  cookies:    Cookies to load. None loads the app default CookieJar. False disables cookie loading.
    @type   cookies:    dict, cookielib.LWPCookieJar, None or False
    @rtype  requests.Session"""
    session = requests.Session()
    if cookies is not False:
        session.cookies.update(cookies or cookiejar())
    session.headers.update({'User-Agent': 'ipsv/{v}'.format(v=ips_vagrant.__version__)})
    return session

def cookiejar(name='session'):
    """Ready the CookieJar, loading a saved session if available
    @rtype: cookielib.LWPCookieJar"""
    log = logging.getLogger('ipsv.common.cookiejar')
    spath = os.path.join(config().get('Paths', 'Data'), '{n}.txt'.format(n=name))
    cj = cookielib.LWPCookieJar(spath)
    log.debug('Attempting to load session file: %s', spath)
    if os.path.exists(spath):
        try:
            cj.load()
            log.info('Successfully loaded a saved session / cookie file')
        except cookielib.LoadError as e:
            log.warn('Session / cookie file exists, but could not be loaded', exc_info=e)
    return cj

def parse_version(vstring):
    """StrictVersion / LooseVersion decorator method
    @type   vstring:    str
    @return:    StrictVersion if possible, otherwise LooseVersion
    @rtype:     StrictVersion or LooseVersion"""
    try:
        version = StrictVersion(vstring)
    except ValueError:
        logging.getLogger('ipvs.common.debug').info('Strict parsing failed, falling back to LooseVersion instead')
        version = LooseVersion(vstring)
        version.version = tuple(version.version)
    return version

def find_config(fname='.rdo.conf', start=None):
    """Go up until you find an rdo config.
    """
    start = start or os.getcwd()
    config_file = os.path.join(start, fname)
    if os.path.isfile(config_file):
        return config_file
    parent, _ = os.path.split(start)
    if parent == start:
        raise Exception('Config file not found')
    return find_config(fname, parent)

def authenticated_redirect(view_func=None, path=None):
    """Decorator for an already authenticated user that we don't want to serve a
    view to. Instead we send them to the dashboard by default or a specified
    path.

    Usage:

        @authenticated_redirect
        @authenticated_redirect()
        @authenticated_redirect(path='home')"""
    default_path = getattr(settings, 'DEFAULT_AUTHENTICATED_PATH', 'dashboard')
    if view_func is None:
        return functools.partial(authenticated_redirect, path=path)
    @functools.wraps(view_func)
    def _wrapped_view(request, *args, **kwargs):
        if path == request.path.replace('/', ''):
            return redirect(default_path)
        if request.user.is_authenticated():
            return redirect(path or default_path)
        return view_func(request, *args, **kwargs)
    return _wrapped_view

def infer_compression(url):
    """Given a URL or filename, infer the compression code for tar."""
    compression_indicator = url[-2:]
    mapping = dict(gz='z', bz='j', xz='J')
    return mapping.get(compression_indicator, 'z')

def default_config(level=logging.INFO, auto_init=True, new_formatter=False, **kwargs):
    """Returns the default config dictionary and inits the logging system if requested

    Keyword arguments:
    level -- loglevel of the console handler (Default: logging.INFO)
    auto_init -- initialize the logging system with the provided config (Default: True)
    **kwargs -- additional options for the logging system"""
    formatters = {'color': {'()': __name__ + '.ColorFormatter', 'format': '[%(levelname)s] %(message)s'}}
    if new_formatter:
        formatters = {'color': {'()': __name__ + '.NewColorFormatter', 'format': '[{levelname}] {message}'}}
    options = {'version': 1, 'disable_existing_loggers': False, 'formatters': formatters, 'filters': {}, 'handlers': {'console': {'class': 'logging.StreamHandler', 'formatter': 'color', 'level': level, 'stream': 'ext://sys.stderr'}}, 'loggers': {}, 'root': {'level': 'NOTSET', 'filters': [], 'handlers': ['console']}}
    options.update(kwargs)
    if auto_init:
        logging.config.dictConfig(options)
    return options

def _parse_ip(addr):
    """Helper function to convert an address into an IPAddress object.
    Canonicalizes IPv6-mapped (or compatible) IPv4 addresses into IPv4
    addresses.  Returns None if the address cannot be parsed."""
    try:
        address = netaddr.IPAddress(addr.strip())
    except (ValueError, netaddr.AddrFormatError):
        return None
    if address.version == 6:
        try:
            return address.ipv4()
        except netaddr.AddrConversionError:
            pass
    return address

def requires_auth(func):
    """Handle authentication checks.

    .. py:decorator:: requires_auth

        Checks if the token has expired and performs authentication if needed."""
    @six.wraps(func)
    def wrapper(self, *args, **kwargs):
        if self.token_expired:
            self.authenticate()
        return func(self, *args, **kwargs)
    return wrapper

def compute_hash(attributes, ignored_attributes=None):
    """Computes a hash code for the given dictionary that is safe for persistence round trips"""
    ignored_attributes = list(ignored_attributes) if ignored_attributes else []
    tuple_attributes = _convert(attributes.copy(), ignored_attributes)
    hasher = hashlib.sha256(str(tuple_attributes).encode('utf-8', errors='ignore'))
    return hasher.hexdigest()

def SimpleRowColumn(field, *args, **kwargs):
    """Shortcut for simple row with only a full column"""
    if isinstance(field, basestring):
        field = Field(field, *args, **kwargs)
    return Row(Column(field))

def make_request(request, method, default_headers=None, **kwargs):
    """convert parameters into relevant parts
    of the an http request
    :param request: either url or an HTTPRequest object
    :param method: http request method
    :param default_headers: default headers
    :param kwargs: headers, query string params for GET and DELETE,
    data for POST and PUT"""
    kwargs = convert(kwargs)
    if not default_headers:
        headers = dict(DEFAULT_HEADERS)
    else:
        headers = default_headers.copy()
    if isinstance(request, HTTPRequest):
        headers.update(request.headers)
    if 'headers' in kwargs:
        headers.update(kwargs.pop('headers'))
    if isinstance(request, HTTPRequest):
        request.method = method
        request.headers.update(headers)
    else:
        request = HTTPRequest(request, method, headers)
    if kwargs:
        if method in ['GET', 'DELETE']:
            request.url = '{}?{}'.format(request.url, urllib.urlencode(kwargs))
        elif method in ['POST', 'PUT']:
            if request.headers['Content-Type'] == JSON_TYPE:
                request.body = json.dumps(kwargs)
            elif 'body' in kwargs:
                request.body = kwargs['body']
    return request

def parse_response(response):
    """parse response and return a dictionary if the content type.
    is json/application.
    :param response: HTTPRequest
    :return dictionary for json content type otherwise response body"""
    if response.headers.get('Content-Type', JSON_TYPE).startswith(JSON_TYPE):
        return ResponseObject(json.loads(response.body))
    else:
        return response.body

def sync_fetch(request, method, default_headers=None, httpclient=None, **kwargs):
    """fetch resource using the synchronous HTTPClient
    :param request: HTTPRequest object or a url
    :param method: HTTP method in string format, e.g. GET, POST
    :param kwargs: query string entities or POST data"""
    updated_request = make_request(request, method, default_headers, **kwargs)
    if not httpclient:
        httpclient = HTTPClient()
    rsp = httpclient.fetch(updated_request)
    return parse_response(rsp)

def register(filetypes):
    """Decorator to register a class as a checker for extensions."""
    def decorator(clazz):
        for ext in filetypes:
            checkers.setdefault(ext, []).append(clazz)
        return clazz
    return decorator

def start_of_month(dt, d_years=0, d_months=0):
    """Given a date, return a date first day of the month.

    @param dt: The date to base the return value upon.
    @param d_years: Specify a delta in years to apply to date.
    @param d_months: Specify a delta in months to apply to date.

    @see http://code.activestate.com/recipes/476197-first-last-day-of-the-month/"""
    y, m = (dt.year + d_years, dt.month + d_months)
    a, m = divmod(m - 1, 12)
    return datetime(y + a, m + 1, 1)

def quarter(dt):
    """Return start/stop datetime for the quarter as defined by dt."""
    quarters = rrule.rrule(rrule.MONTHLY, bymonth=(1, 4, 7, 10), bysetpos=-1, dtstart=datetime(dt.year, 1, 1), count=8)
    first_day = quarters.before(dt, True)
    last_day = quarters.after(dt) - relativedelta.relativedelta(days=1)
    return (first_day, last_day)

def operator_same_class(method):
    """Intended to wrap operator methods, this decorator ensures the `other`
    parameter is of the same type as the `self` parameter.

    :param method: The method being decorated.
    :return: The wrapper to replace the method with."""
    def wrapper(self, other):
        if not isinstance(other, self.__class__):
            raise TypeError("unsupported operand types: '{0}' and '{1}'".format(self.__class__.__name__, other.__class__.__name__))
        return method(self, other)
    return wrapper

def operator_numeric_type(method):
    """Intended to wrap operator methods, this decorator ensures a numeric type
    was passed.

    :param method: The method being decorated.
    :return: The wrapper to replace the method with."""
    def wrapper(self, other):
        if not isinstance(other, _NUMERIC_TYPES):
            raise TypeError("unsupported operand types: '{0}' and '{1}'".format(self.__class__.__name__, other.__class__.__name__))
        return method(self, other)
    return wrapper

def python_2_format_compatible(method):
    """Handles bytestring and unicode inputs for the `__format__()` method in
    Python 2. This function has no effect in Python 3.

    :param method: The `__format__()` method to wrap.
    :return: The wrapped method."""
    if six.PY3:
        return method
    def wrapper(self, format_spec):
        formatted = method(self, format_spec)
        if isinstance(format_spec, str):
            return formatted.encode('utf-8')
        return formatted
    return wrapper

def python_2_nonzero_compatible(klass):
    """Adds a `__nonzero__()` method to classes that define a `__bool__()` method,
    so boolean conversion works in Python 2. Has no effect in Python 3.

    :param klass: The class to modify. Must define `__bool__()`.
    :return: The possibly patched class."""
    if six.PY2:
        if '__bool__' not in klass.__dict__:
            raise ValueError("@python_2_nonzero_compatible cannot be applied to {0} because it doesn't define __bool__().".format(klass.__name__))
        klass.__nonzero__ = klass.__bool__
    return klass

def python_2_div_compatible(klass):
    """Adds a `__div__()` method to classes that define a `__floordiv__()` method,
    so division works in Python 2. Has no effect in Python 3.

    :param klass: The class to modify. Must define `__floordiv__()`.
    :return: The possibly patched class."""
    if six.PY2:
        if '__floordiv__' not in klass.__dict__:
            raise ValueError("@python_2_div_compatible cannot be applied to {0} because it doesn't define __floordiv__().".format(klass.__name__))
        klass.__div__ = klass.__floordiv__
    return klass

def elemgetter(path: str) -> t.Callable[[Element], Element]:
    """shortcut making an XML element getter"""
    return compose(partial(_raise_if_none, exc=LookupError(path)), methodcaller('find', path))

def textgetter(path: str, *, default: T=NO_DEFAULT, strip: bool=False) -> t.Callable[[Element], t.Union[str, T]]:
    """shortcut for making an XML element text getter"""
    find = compose(str.strip if strip else identity, partial(_raise_if_none, exc=LookupError(path)), methodcaller('findtext', path))
    return find if default is NO_DEFAULT else lookup_defaults(find, default)

def julian_day(year, n):
    """Return the Julian day n(1 <= n <= 365).

    Leap days are not counted; that is, in all years -- including leap years --
    February 28 is day 59 and March 1 is day 60. It is impossible to explicitly
    refer to the occasional February 29."""
    if n > 59 and isleap(year):
        n += 1
    return datetime(year, 1, 1) + timedelta(n - 1)

def _parse_alt_title(html_chunk):
    """Parse title from alternative location if not found where it should be.

    Args:
        html_chunk (obj): HTMLElement containing slice of the page with details.

    Returns:
        str: Book's title."""
    title = html_chunk.find('img', fn=has_param('alt'))
    if not title:
        raise UserWarning("Can't find alternative title source!")
    return title[0].params['alt'].strip()

def _parse_title_url(html_chunk):
    """Parse title/name of the book and URL of the book.

    Args:
        html_chunk (obj): HTMLElement containing slice of the page with details.

    Returns:
        tuple: (title, url), both as strings."""
    url = None
    title_tags = html_chunk.match(['div', {'class': 'polozka_nazev'}], ['a', None, has_param('href')])
    if not title_tags:
        return (_parse_alt_title(html_chunk), _parse_alt_url(html_chunk))
    title = title_tags[0]
    url = normalize_url(BASE_URL, title.params['href'])
    title = title.getContent()
    if not title:
        title = _parse_alt_title(html_chunk)
    return (title, url)

def _parse_from_table(html_chunk, what):
    """Go thru table data in `html_chunk` and try to locate content of the
    neighbor cell of the cell containing `what`.

    Returns:
        str: Table data or None."""
    ean_tag = html_chunk.find('tr', fn=must_contain('th', what, 'td'))
    if not ean_tag:
        return None
    return get_first_content(ean_tag[0].find('td'))

def get_data_url(deployment_name, endpoint_type='juttle', token_manager=None, app_url=defaults.APP_URL):
    """get the data url for a specified endpoint_type, currently supported types
    are:

     * http-import: for importing data points
     * juttle: for running juttle programs"""
    deployment_details = deployments.get_deployment_details(deployment_name, token_manager=token_manager, app_url=app_url)
    endpoints = []
    for endpoint in deployment_details['endpoints']:
        if endpoint_type in endpoint['type']:
            endpoints.append(endpoint)
    if len(endpoints) == 0:
        raise JutException('No data engine currently configured for deployment "%s"' % deployment_name)
    return random.choice(endpoints)['uri']

def get_data_urls(deployment_name, endpoint_type='juttle', token_manager=None, app_url=defaults.APP_URL):
    """get all of the data urls for a specified endpoint_type, currently supported types
    are:

     * http-import: for importing data points
     * juttle: for running juttle programs"""
    deployment_details = deployments.get_deployment_details(deployment_name, token_manager=token_manager, app_url=app_url)
    data_urls = []
    for endpoint in deployment_details['endpoints']:
        if endpoint_type in endpoint['type']:
            data_urls.append(endpoint['uri'])
    if len(data_urls) == 0:
        raise JutException('No data engine currently configured for deployment "%s"' % deployment_name)
    return data_urls

def get_juttle_data_url(deployment_name, token_manager=None, app_url=defaults.APP_URL):
    """return the juttle data url"""
    return get_data_url(deployment_name, endpoint_type='juttle', app_url=app_url, token_manager=token_manager)

def get_import_data_url(deployment_name, token_manager=None, app_url=defaults.APP_URL):
    """return the import data url"""
    return get_data_url(deployment_name, endpoint_type='http-import', app_url=app_url, token_manager=token_manager)

def get_jobs(deployment_name, token_manager=None, app_url=defaults.APP_URL):
    """return list of currently running jobs"""
    headers = token_manager.get_access_token_headers()
    data_urls = get_data_urls(deployment_name, app_url=app_url, token_manager=token_manager)
    jobs = []
    for data_url in data_urls:
        url = '%s/api/v1/jobs' % data_url
        response = requests.get(url, headers=headers)
        if response.status_code == 200:
            these_jobs = response.json()['jobs']
            for job in these_jobs:
                job['data_url'] = data_url
            jobs += these_jobs
        else:
            raise JutException('Error %s: %s' % (response.status_code, response.text))
    return jobs

def get_job_details(job_id, deployment_name, token_manager=None, app_url=defaults.APP_URL):
    """return job details for a specific job id"""
    jobs = get_jobs(deployment_name, token_manager=token_manager, app_url=app_url)
    for job in jobs:
        if job['id'] == job_id:
            return job
    raise JutException('Unable to find job with id "%s"' % job_id)

def prettify(root, encoding='utf-8'):
    """Return a pretty-printed XML string for the Element.

    @see: http://www.doughellmann.com/PyMOTW/xml/etree/ElementTree/create.html"""
    if isinstance(root, ElementTree.Element):
        node = ElementTree.tostring(root, 'utf-8')
    else:
        node = root
    return etree.tostring(etree.fromstring(node), pretty_print=True, xml_declaration=True, encoding='utf-8')

def lines(input):
    """Remove comments and empty lines"""
    for raw_line in input:
        line = raw_line.strip()
        if line and (not line.startswith('#')):
            yield strip_comments(line)

def read(url, **args):
    """Loads an object from a data URI."""
    info, data = url.path.split(',')
    info = data_re.search(info).groupdict()
    mediatype = info.setdefault('mediatype', 'text/plain;charset=US-ASCII')
    if ';' in mediatype:
        mimetype, params = mediatype.split(';', 1)
        params = [p.split('=') for p in params.split(';')]
        params = dict(((k.strip(), v.strip()) for k, v in params))
    else:
        mimetype, params = (mediatype, dict())
    data = base64.b64decode(data) if info['base64'] else urllib.unquote(data)
    return content_types.get(mimetype).parse(data, **params)

def blockgen(bytes, block_size=16):
    """a block generator for pprp"""
    for i in range(0, len(bytes), block_size):
        block = bytes[i:i + block_size]
        block_len = len(block)
        if block_len > 0:
            yield block
        if block_len < block_size:
            break

def get_element_types(obj, **kwargs):
    """Get element types as a set."""
    max_iterable_length = kwargs.get('max_iterable_length', 10000)
    consume_generator = kwargs.get('consume_generator', False)
    if not isiterable(obj):
        return None
    if isgenerator(obj) and (not consume_generator):
        return None
    t = get_types(obj, **kwargs)
    if not t['too_big']:
        if t['types']:
            return 'Element types: {}'.format(', '.join([extract_type(t) for t in t['types']]))
        else:
            return None
    else:
        return 'Element types: {}'.format(', '.join([extract_type(t) for t in t['types']])) + ' (based on first {} elements.)'.format(max_iterable_length)

def parseArgs(args):
    """Parse Arguments

    Used to parse the arguments passed to the script

    Args:
            args (list): A list of strings representing arguments to a script

    Returns:
            dict: Returns a dictionary with args as keys and the values sent with
                    them or True for valueless arguments

    Raises:
            ValueError: If args is not a list or tuple"""
    if not isinstance(args, (list, tuple)):
        raise ValueError('args is not a list or tuple')
    dRet = {}
    for s in args:
        oRes = re.match(u'^--([^=]+)(?:=(.+))?$', s)
        if oRes:
            mGroup2 = oRes.group(2)
            dRet[oRes.group(1)] = not mGroup2 and True or mGroup2
        else:
            try:
                dRet['?'].append(s)
            except KeyError:
                dRet['?'] = [s]
    return dRet

def readfile(filename, binary=False):
    """Reads the contents of the specified file.

    `filename`
        Filename to read.
    `binary`
        Set to ``True`` to indicate a binary file.

    Returns string or ``None``."""
    if not os.path.isfile(filename):
        return None
    try:
        flags = 'r' if not binary else 'rb'
        with open(filename, flags) as _file:
            return _file.read()
    except (OSError, IOError):
        return None

def which(name):
    """Returns the full path to executable in path matching provided name.

    `name`
        String value.

    Returns string or ``None``."""
    if os.path.dirname(name) != '':
        if not os.path.isdir(name) and os.access(name, os.X_OK):
            return name
        else:
            return None
    path_val = os.environ.get('PATH', None) or os.defpath
    for path in path_val.split(os.pathsep):
        filename = os.path.join(path, name)
        if os.access(filename, os.X_OK):
            return filename
    return None

def from_utf8(buf, errors='replace'):
    """Decodes a UTF-8 compatible, ASCII string into a unicode object.

    `buf`
        string or unicode string to convert.

    Returns unicode` string.

    * Raises a ``UnicodeDecodeError`` exception if encoding failed and
      `errors` isn't set to 'replace'."""
    if isinstance(buf, unicode):
        return buf
    else:
        return unicode(buf, 'utf-8', errors)

def get_indices():
    """Return a list of 3 integers representing EU indices for yesterday, today
    and tomorrow."""
    doc = BeautifulSoup(urlopen(BASEURL))
    divs = doc.select('.indices_txt')
    if not divs:
        return None
    sibling = divs[1].nextSibling
    if not sibling:
        return None
    data = sibling.nextSibling
    if not data:
        return None
    data = BeautifulSoup(data)
    divs = data.select('.selected')
    return map(lambda d: int(d.text), divs)

def _css_select(soup, css_selector):
    """Returns the content of the element pointed by the CSS selector,
    or an empty string if not found"""
    selection = soup.select(css_selector)
    if len(selection) > 0:
        if hasattr(selection[0], 'text'):
            retour = selection[0].text.strip()
        else:
            retour = ''
    else:
        retour = ''
    return retour

def itemat(iterable, index):
    """Try to get the item at index position in iterable after iterate on
    iterable items.

    :param iterable: object which provides the method __getitem__ or __iter__.
    :param int index: item position to get."""
    result = None
    handleindex = True
    if isinstance(iterable, dict):
        handleindex = False
    else:
        try:
            result = iterable[index]
        except TypeError:
            handleindex = False
    if not handleindex:
        iterator = iter(iterable)
        if index < 0:
            index += len(iterable)
        while index >= 0:
            try:
                value = next(iterator)
            except StopIteration:
                raise IndexError('{0} index {1} out of range'.format(iterable.__class__, index))
            else:
                if index == 0:
                    result = value
                    break
                index -= 1
    return result

def sliceit(iterable, lower=0, upper=None):
    """Apply a slice on input iterable.

    :param iterable: object which provides the method __getitem__ or __iter__.
    :param int lower: lower bound from where start to get items.
    :param int upper: upper bound from where finish to get items.
    :return: sliced object of the same type of iterable if not dict, or specific
        object. otherwise, simple list of sliced items.
    :rtype: Iterable"""
    if upper is None:
        upper = len(iterable)
    try:
        result = iterable[lower:upper]
    except TypeError:
        result = []
        if lower < 0:
            lower += len(iterable)
        if upper < 0:
            upper += len(iterable)
        if upper > lower:
            iterator = iter(iterable)
            for index in range(upper):
                try:
                    value = next(iterator)
                except StopIteration:
                    break
                else:
                    if index >= lower:
                        result.append(value)
    iterablecls = iterable.__class__
    if not (isinstance(result, iterablecls) or issubclass(iterablecls, dict)):
        try:
            result = iterablecls(result)
        except TypeError:
            pass
    return result

