def quoted_split(string, sep, quotes='"'):
    """Split a string on the given separation character, but respecting
    double-quoted sections of the string.  Returns an iterator.

    :param string: The string to split.
    :param sep: The character separating sections of the string.
    :param quotes: A string specifying all legal quote characters.

    :returns: An iterator which will iterate over each element of the
              string separated by the designated separator."""
    start = None
    escape = False
    quote = False
    for i, c in enumerate(string):
        if start is None:
            start = i
        if escape:
            escape = False
        elif quote:
            if c == '\\':
                escape = True
            elif c == quote:
                quote = False
        elif c == sep:
            yield string[start:i]
            start = None
        elif c in quotes:
            quote = c
    if start is not None:
        yield string[start:]

def parse_ctype(ctype):
    """Parse a content type.

    :param ctype: The content type, with corresponding parameters.

    :returns: A tuple of the content type and a dictionary containing
              the content type parameters.  The content type will
              additionally be available in the dictionary as the '_'
              key."""
    result_ctype = None
    result = {}
    for part in quoted_split(ctype, ';'):
        if result_ctype is None:
            result_ctype = part
            result['_'] = part
            continue
        equal = part.find('=')
        if equal > 0 and part.find('"', 0, equal) < 0:
            result[part[:equal]] = unquote(part[equal + 1:])
        else:
            result[part] = True
    if result_ctype is None:
        result_ctype = ''
    return (result_ctype, result)

def best_match(requested, allowed):
    """Determine the best content type to use for the request.

    :param ctypes: A list of the available content types.

    :returns: A tuple of the best match content type and the
              parameters for that content type."""
    requested = [parse_ctype(ctype) for ctype in quoted_split(requested, ',')]
    best_q = -1
    best_ctype = ''
    best_params = {}
    best_match = '*/*'
    for ctype in allowed:
        for ctype_mask, params in requested:
            try:
                q = float(params.get('q', 1.0))
            except ValueError:
                continue
            if q < best_q:
                continue
            elif best_q == q:
                if best_match.count('*') <= ctype_mask.count('*'):
                    continue
            if _match_mask(ctype_mask, ctype):
                best_q = q
                best_ctype = ctype
                best_params = params
                best_match = ctype_mask
    return (best_ctype, best_params)

def get_available_hashes():
    """Returns a tuple of the available hashes"""
    if sys.version_info >= (3, 2):
        return hashlib.algorithms_available
    elif sys.version_info >= (2, 7) and sys.version_info < (3, 0):
        return hashlib.algorithms
    else:
        return ('md5', 'sha1', 'sha224', 'sha256', 'sha384', 'sha512')

def delist(target):
    """for any "list" found, replace with a single entry if the list has exactly one entry"""
    result = target
    if type(target) is dict:
        for key in target:
            target[key] = delist(target[key])
    if type(target) is list:
        if len(target) == 0:
            result = None
        elif len(target) == 1:
            result = delist(target[0])
        else:
            result = [delist(e) for e in target]
    return result

def value_output(value, quote_method='all', none_handle='strict'):
    """Format types:
    'all'.
       (default) everything is embraced with quotes
    'needed'.
       Quote only if needed. Values are on placed in quotes if:
       a. the value contains a quote
       b. there is whitespace at the beginning or end of string
    'none'.
       Quote nothing."""
    p = str(value)
    if value is None:
        if none_handle == 'strict':
            return ''
        elif none_handle == 'empty':
            return ' ""'
        elif none_handle == 'None':
            p = 'None'
        else:
            raise 'none handler ' + str(none_handle) + ' not recognized'
    if quote_method == 'all':
        return ' "' + p + '"'
    elif quote_method == 'by_need':
        if len(p) != len(p.strip()):
            return ' "' + p + '"'
        if '"' in p:
            return ' "' + p + '"'
        return ' ' + p
    elif quote_method == 'none':
        return ' ' + p
    else:
        raise 'quote method ' + str(quote_method) + ' not recognized'
    return

def sub_schema_raises(doc, schema):
    '''Look for "raise_error", "raise_warning", and "raise_log"'''
    error_list = []
    temp_schema = schema_match_up(doc, schema)
    for msg in temp_schema.list_values('raise_error'):
        error_list.append(('[error]', 'doc', doc.seq, "'{}'".format(msg)))
    for msg in temp_schema.list_values('raise_warning'):
        error_list.append(('[warning]', 'doc', doc.seq, "'{}'".format(msg)))
    for msg in temp_schema.list_values('raise_log'):
        error_list.append(('[log]', 'doc', doc.seq, "'{}'".format(msg)))
    for entry in doc:
        if temp_schema.has(('name', entry.name)):
            el = sub_schema_raises(entry, temp_schema['name', entry.name])
            error_list.extend(el)
    return error_list

def _process_function_list(self, routines):
    """Chain function which returns a function.

    :param routines: routines to process."""
    def processing(*args, **kwargs):
        """Execute routines with input args and kwargs and add result in
        chaining.___.

        :param tuple args: routines varargs.
        :param dict kwargs: routines kwargs.
        :return: chaining chaining.
        :rtype: Chaining"""
        results = [None] * len(routines)
        for index, routine in enumerate(routines):
            if isinstance(routine, Exception):
                result = routine
            else:
                try:
                    result = routine(*args, **kwargs)
                except AttributeError as excp:
                    result = excp
            results[index] = result
        self.___.append(results)
        return self
    return processing

