def require_login(func):
    """Function wrapper to signalize that a login is required."""
    @wraps(func)
    def decorated(*args, **kwargs):
        auth = request.authorization
        if not auth:
            return authenticate()
        user = session.query(User).filter(User.name == auth.username).first()
        if user and user.check(auth.password):
            g.user = user
            return func(*args, **kwargs)
        else:
            return authenticate()
    return decorated

def require_admin(func):
    """Requires an admin user to access this resource."""
    @wraps(func)
    @require_login
    def decorated(*args, **kwargs):
        user = current_user()
        if user and user.is_admin:
            return func(*args, **kwargs)
        else:
            return Response('Forbidden', 403)
    return decorated

def detect_change_mode(text, change):
    """returns 'add' 'delete' or 'internal'. see comments to update_changes for more details."""
    if len(change.deltas) > 1:
        return 'internal'
    elif not change.deltas:
        return 'add'
    delta, = change.deltas
    if delta.a == delta.b and delta.a == len(text):
        return 'add'
    elif delta.b == len(text) and len(delta.text) == 0:
        return 'delete'
    else:
        return 'internal'

def mkchange(text0, text1, version, mtime):
    """return a Change diffing the two strings"""
    return Change(version, mtime, ucrc(text1), diff.word_diff(text0, text1))

def update_changes(changes, newtext, change):
    """decide whether to compact the newest change into the old last; return new change list. assumes changes is safe to mutate.  note: newtext MUST be the result of applying change to changes, and is only passed to save doing the computation again."""
    if not changes:
        return [change]
    if change.utc - changes[-1].utc > COMPACTION_TIME_THRESH:
        changes.append(change)
        return changes
    base = reduce(apply_change, changes[:-1], '')
    final = apply_change(base, changes[-1])
    prev_mode = detect_change_mode(base, changes[-1])
    cur_mode = detect_change_mode(final, change)
    if prev_mode == cur_mode and abs(len(newtext) - len(final) < COMPACTION_LEN_THRESH):
        changes[-1] = mkchange(base, newtext, change.version, change.utc)
    else:
        changes.append(change)
    return changes

def calculate_indent(text):
    """:param text:
    :type text: str
    :return:"""
    indent = 0
    for c in text:
        if c is '\t':
            raise ValueError()
        if c is not ' ':
            return (indent, text[indent:])
        indent += 1
    return (indent, '')

def iter_lines(f):
    """:param f:
    :type f: file
    :return:"""
    linenum = 1
    try:
        for text in f.readlines():
            if text.isspace():
                continue
            indent, value = parse_line(text)
            yield (linenum, indent, value)
            linenum += 1
    except:
        raise ParserError(linenum, 0, '', 'failed to parse line')

def package_to_directory(package_path: str) -> str:
    """Translate a package/path specification into a real file system pathname.

    :param package_path: a package name or a package/path specification like
        ``package.subpackage/directory/subdirectory``
    :return: the translated path name
    :raises ImportError: if the package cannot be imported
    :raises LookupError: if the directory does not exist"""
    if '/' in package_path:
        pkgname, subpath = package_path.split('/', 1)
    else:
        pkgname, subpath = (package_path, '')
    module = import_module(pkgname)
    path = Path(module.__spec__.origin).parent / subpath
    if path.exists():
        if path.is_dir():
            return str(path)
        else:
            raise LookupError('{} is not a directory'.format(path))
    else:
        raise LookupError('{} does not exist'.format(path))

def Kargs2Attr():
    """This Decorator Will:
     Read **kwargs key and add it to current Object-class ClassTinyDecl under current
     name readed from **kwargs key name.
    """
    def decorator(func):
        def inner(**kwargs):
            for ItemName in kwargs.keys():
                setattr(__builtins__, ItemName, kwargs[ItemName])
            func(**kwargs)
        return inner
    return decorator

def generate_error(request, cls, e, tb, include_traceback=False):
    """Builds an L{ErrorMessage<pyamf.flex.messaging.ErrorMessage>} based on the
    last traceback and the request that was sent."""
    import traceback
    if hasattr(cls, '_amf_code'):
        code = cls._amf_code
    else:
        code = cls.__name__
    details = None
    rootCause = None
    if include_traceback:
        details = traceback.format_exception(cls, e, tb)
        rootCause = e
    faultDetail = None
    faultString = None
    if hasattr(e, 'message'):
        faultString = unicode(e.message)
    elif hasattr(e, 'args') and e.args:
        if isinstance(e.args[0], pyamf.python.str_types):
            faultString = unicode(e.args[0])
    if details:
        faultDetail = unicode(details)
    return messaging.ErrorMessage(messageId=generate_random_id(), clientId=generate_random_id(), timestamp=calendar.timegm(time.gmtime()), correlationId=request.messageId, faultCode=code, faultString=faultString, faultDetail=faultDetail, extendedData=details, rootCause=rootCause)

