def check_time_param(t):
    """Check whether a string sent in matches the ISO8601 format.  If a
    Datetime object is passed instead, it will be converted into an ISO8601
    compliant string.

    :param t: the datetime to check
    :type t: string or Datetime
    :rtype: string"""
    if type(t) is str:
        if not ISO.match(t):
            raise ValueError('Date string "%s" does not match ISO8601 format' % t)
        return t
    else:
        return t.isoformat()

def next_weekday(weekday):
    """Returns the name of the weekday after the given weekday name."""
    ix = WEEKDAYS.index(weekday)
    if ix == len(WEEKDAYS) - 1:
        return WEEKDAYS[0]
    return WEEKDAYS[ix + 1]

def prev_weekday(weekday):
    """Returns the name of the weekday before the given weekday name."""
    ix = WEEKDAYS.index(weekday)
    if ix == 0:
        return WEEKDAYS[len(WEEKDAYS) - 1]
    return WEEKDAYS[ix - 1]

def get_class_by_path(class_path: str, is_module: Optional[bool]=False) -> type:
    """Get class by its name within a package structure.

    :param class_path: E.g. brandt.some.module.ClassName
    :param is_module: Whether last item is module rather than class name
    :return: Class ready to be instantiated."""
    if is_module:
        try:
            backend_module = importlib.import_module(class_path)
        except ImportError:
            logger.warning("Can't import backend with name `%s`", class_path)
            raise
        else:
            return backend_module
    module_name, class_name = class_path.rsplit('.', 1)
    try:
        backend_module = importlib.import_module(module_name)
    except ImportError:
        logger.error("Can't import backend with name `%s`", module_name)
        raise
    try:
        backend_class = getattr(backend_module, class_name)
    except AttributeError:
        logger.error("Can't get backend class `%s` from `%s`", class_name, module_name)
        raise
    return backend_class

def start_of_month(d, d_years=0, d_months=0):
    """Given a date, return a date first day of the month.

    @param d: The date to base the return value upon.
    @param d_years: Specify a delta in years to apply to date.
    @param d_months: Specify a delta in months to apply to date.

    @see http://code.activestate.com/recipes/476197-first-last-day-of-the-month/"""
    y, m = (d.year + d_years, d.month + d_months)
    a, m = divmod(m - 1, 12)
    return date(y + a, m + 1, 1)

def business_days(start, stop):
    """Return business days between two inclusive dates - ignoring public holidays.

    Note that start must be less than stop or else 0 is returned.

    @param start: Start date
    @param stop: Stop date
    @return int"""
    dates = rrule.rruleset()
    dates.rrule(rrule.rrule(rrule.DAILY, dtstart=start, until=stop))
    dates.exrule(rrule.rrule(rrule.DAILY, byweekday=(rrule.SA, rrule.SU), dtstart=start))
    return dates.count()

def days(start, stop):
    """Return days between start & stop (inclusive)

    Note that start must be less than stop or else 0 is returned.

    @param start: Start date
    @param stop: Stop date
    @return int"""
    dates = rrule.rruleset()
    dates.rrule(rrule.rrule(rrule.DAILY, dtstart=start, until=stop))
    return dates.count()

def date_period(frequency, anniversary, now=None):
    """Retrieve a date period given a day of month.

    For example, if the period is month:15 and now is equal
    to 2012-11-22 then this method will return the following:

        (date(2012, 11, 15), date(2012, 12, 14))

    Other examples:
        monthly:1 with now 2012-12-1 would return: (date(2012, 11, 1), date(2012, 12, 1))

    @param now: A date used to determine some point within a date period.
    @return tuple with date start and stop dates.
    @raise MaxAnniversaryDayError
    @raise DateFrequencyError"""
    if frequency != DATE_FREQUENCY_MONTHLY:
        raise DateFrequencyError("Only monthly date frequency is supported - not '%s'" % frequency)
    if anniversary > 28:
        raise MaxAnniversaryDayError("'%s' is greater than maximum allowed anniversary day 28." % anniversary)
    if not now:
        now = date.now()
    if now.day >= anniversary:
        start = date(now.year, now.month, anniversary)
        stop = start + relativedelta(months=+1) + relativedelta(days=-1)
    else:
        stop = date(now.year, now.month, anniversary)
        start = stop + relativedelta(months=-1)
        stop = stop + relativedelta(days=-1)
    return (start, stop)

def exact_anniversaries(frequency, anniversary, start, finish):
    """Returns the number of exact anniversaries if start and finish represent an anniversary.

    ie..

    exact_anniversaries(DATE_FREQUENCY_MONTHLY, 10, date(2012, 2, 10), date(2012, 3, 9)) returns 1
    exact_anniversaries(DATE_FREQUENCY_MONTHLY, 10, date(2012, 2, 10), date(2012, 4, 9)) returns 2"""
    if frequency != DATE_FREQUENCY_MONTHLY:
        raise DateFrequencyError("Only monthly date frequency is supported - not '%s'" % frequency)
    if start.day != anniversary:
        return False
    periods = 0
    current = start
    while current <= finish:
        period_end = current + relativedelta(months=+1, days=-1)
        if period_end <= finish:
            periods += 1
        else:
            return False
        current = current + relativedelta(months=+1)
    return periods

def quarter(d):
    """Return start/stop datetime for the quarter as defined by dt."""
    from django_toolkit.datetime_util import quarter as datetime_quarter
    first_date, last_date = datetime_quarter(datetime(d.year, d.month, d.day))
    return (first_date.date(), last_date.date())

def previous_quarter(d):
    """Retrieve the previous quarter for dt"""
    from django_toolkit.datetime_util import quarter as datetime_quarter
    return quarter((datetime_quarter(datetime(d.year, d.month, d.day))[0] + timedelta(days=-1)).date())

def _load_calendar(campus, resp_fragment, calendar_dict, parent):
    """:return: a dictionary of {calenderid, TrumbaCalendar}
             None if error, {} if not exists"""
    for record in resp_fragment:
        if re.match('Internal Event Actions', record['Name']) or re.match('Migrated .*', record['Name']):
            continue
        trumba_cal = TrumbaCalendar()
        trumba_cal.calendarid = record['ID']
        trumba_cal.campus = campus
        if parent is None:
            trumba_cal.name = record['Name']
        else:
            trumba_cal.name = '%s >> %s' % (parent, record['Name'])
        if not _is_valid_calendarid(record['ID']):
            logger.warn('InvalidCalendarId %s, entry skipped!' % trumba_cal)
            continue
        calendar_dict[trumba_cal.calendarid] = trumba_cal
        if record['ChildCalendars'] is not None and len(record['ChildCalendars']) > 0:
            _load_calendar(campus, record['ChildCalendars'], calendar_dict, trumba_cal.name)

def splitpreserve(s, redelim='\\s'):
    """split, but preserves the delimiter so the string can be reassembled with double-spaces (etc) intact"""
    pattern = '[^%s]*%s*' % (redelim, redelim)
    return re.findall(pattern, s)

def seqingroups(groups, seq):
    """helper for contigsub. takes the list of lists returned by groupelts and an array to check.  returns (groupindex,indexingroup,matchlen) of longest match or None if no match"""
    if not (groups and seq):
        return None
    bestmatch = (None, None, 0)
    if any((len(g) < 2 for g in groups)):
        raise ValueError('some subgroups have length < 2')
    for i, g in filter(lambda x: x[1][0], enumerate(groups)):
        begin = 0
        while 1:
            try:
                begin = g.index(seq[0], begin + 1)
            except ValueError:
                break
            jmax = min(len(g) - begin, len(seq))
            for j in range(jmax):
                if g[begin + j] != seq[j]:
                    break
            else:
                j += 1
            matchlen = min(j, jmax)
            if matchlen < bestmatch[2]:
                continue
            bestmatch = [i, begin, matchlen]
    return bestmatch if bestmatch[2] else None

def contigsub(a, b):
    """find longest common substring. return its slice coordinates (in a and b; see last line) or None if not found"""
    'a and b are token lists'
    common = commonelts(a, b)
    groupsa = groupelts(a, common)
    groupsb = groupelts(b, common)
    bestmatch = [None, None, 0]
    bslice = None
    for i in range(len(groupsb)):
        if not groupsb[i][0]:
            continue
        if len(groupsb[i]) - 1 <= bestmatch[2]:
            continue
        for j in range(len(groupsb[i])):
            match = seqingroups(groupsa, groupsb[i][j:])
            if match and match[2] > bestmatch[2]:
                bestmatch = match
                bslice = [i, j, match[2]]
            if match and match[2] >= len(groupsb[i]) / 2.0:
                break
    return None if not bestmatch[2] else (ungroupslice(groupsa, bestmatch), ungroupslice(groupsb, bslice))

def subslice(inner, outer, section):
    """helper for rediff  outer is a slice (2-tuple, not an official python slice) in global coordinates  inner is a slice (2-tuple) on that slice  returns the result of sub-slicing outer by inner"""
    if section == 'head':
        return (outer[0], outer[0] + inner[0])
    elif section == 'tail':
        return (outer[0] + inner[1], outer[1])
    elif section == 'middle':
        return (outer[0] + inner[0], outer[0] + inner[1])
    else:
        raise ValueError('section val %s not one of (head,middle,tail)' % section)

def rediff(a, b, global_a_slice=None):
    """recursive diff (splits around longest substring and runs diff on head and tail remnants).  global_a_slice is used for recursion and should be left undefined in outer call.  returns a list of Delta tuples."""
    if not (a or b):
        return []
    global_a_slice = global_a_slice or (0, len(a))
    csresult = contigsub(a, b)
    if not csresult:
        return (Delta(global_a_slice[0], global_a_slice[1], b),)
    slicea, sliceb = csresult
    if slicea[0] == 0 and sliceb[0] == 0 and (slicea[1] == len(a)) and (sliceb[1] == len(b)):
        return []
    head = rediff(a[:slicea[0]], b[:sliceb[0]], subslice(slicea, global_a_slice, 'head'))
    tail = rediff(a[slicea[1]:], b[sliceb[1]:], subslice(slicea, global_a_slice, 'tail'))
    return list(head) + list(tail)

def word_diff(a, b):
    """do diff on words but return character offsets"""
    return translate_diff(a, rediff(splitpreserve(a), splitpreserve(b)))

def checkdiff(a, b, sp=True):
    """take diff of a to b, apply to a, return the applied diff so external code can check it against b"""
    if sp:
        a = splitpreserve(a)
        b = splitpreserve(b)
    res = applydiff(a, rediff(a, b))
    if sp:
        res = ''.join(res)
    return res

def _remove_broken_links():
    """Remove broken links in `<conda prefix>/etc/microdrop/plugins/enabled/`.

    Returns
    -------
    list
        List of links removed (if any)."""
    enabled_dir = MICRODROP_CONDA_PLUGINS.joinpath('enabled')
    if not enabled_dir.isdir():
        return []
    broken_links = []
    for dir_i in enabled_dir.walkdirs(errors='ignore'):
        if platform.system() == 'Windows':
            if dir_i.isjunction() and (not dir_i.readlink().isdir()):
                broken_links.append(dir_i)
        else:
            raise NotImplementedError('Unsupported platform')
    removed_links = []
    for link_i in broken_links:
        try:
            link_i.unlink()
        except:
            pass
        else:
            removed_links.append(link_i)
    return removed_links

def tempfilename(**kwargs):
    """Reserve a temporary file for future use.

    This is useful if you want to get a temporary file name, write to it in the
    future and ensure that if an exception is thrown the temporary file is removed."""
    kwargs.update(delete=False)
    try:
        f = NamedTemporaryFile(**kwargs)
        f.close()
        yield f.name
    except Exception:
        if os.path.exists(f.name):
            os.unlink(f.name)
        raise

def makedirs(p):
    """A makedirs that avoids a race conditions for multiple processes attempting to create the same directory."""
    try:
        os.makedirs(p, settings.FILE_UPLOAD_PERMISSIONS)
    except OSError:
        if not os.path.isdir(p):
            raise

def get_dataset(corpora):
    """Return a dictionary of subjectID -> [path_to_resource]."""
    def make_posix_path(dirpath, filename):
        dirpath = posixpath.sep.join(dirpath.split(os.sep))
        return posixpath.join(dirpath, filename)
    wav_files_in_corpora = filter(lambda x: x.endswith('.wav'), sum([list(map(lambda x: make_posix_path(corpus, x), os.listdir(corpus))) for corpus in corpora], []))
    dataset = {}
    for wav_file in wav_files_in_corpora:
        subjectID = os.path.split(wav_file)[-1].split('.')[0].split('_')[0]
        if subjectID in dataset:
            dataset[subjectID].append(wav_file)
        else:
            dataset[subjectID] = [wav_file]
    return dataset

def load_user_config(vcs):
    """Load the user config

    Args:
        vcs (easyci.vcs.base.Vcs) - the vcs object for the current project

    Returns:
        dict - the config

    Raises:
        ConfigFormatError
        ConfigNotFoundError"""
    config_path = os.path.join(vcs.path, 'eci.yaml')
    if not os.path.exists(config_path):
        raise ConfigNotFoundError
    with open(config_path, 'r') as f:
        try:
            config = yaml.safe_load(f)
        except yaml.YAMLError:
            raise ConfigFormatError
    if not isinstance(config, dict):
        raise ConfigFormatError
    for k, v in _default_config.iteritems():
        config.setdefault(k, v)
    for k, v in _config_types.iteritems():
        if not isinstance(config[k], v):
            raise ConfigFormatError
    return config

def authenticate(func, c, expose_request=False):
    """A decorator that facilitates authentication per method. Setting
    C{expose_request} to C{True} will set the underlying request object (if
    there is one), usually HTTP and set it to the first argument of the
    authenticating callable. If there is no request object, the default is
    C{None}.

    @raise TypeError: C{func} and authenticator must be callable."""
    if not python.callable(func):
        raise TypeError('func must be callable')
    if not python.callable(c):
        raise TypeError('Authenticator must be callable')
    attr = func
    if isinstance(func, types.UnboundMethodType):
        attr = func.im_func
    if expose_request is True:
        c = globals()['expose_request'](c)
    setattr(attr, '_pyamf_authenticator', c)
    return func

def expose_request(func):
    """A decorator that adds an expose_request flag to the underlying callable.

    @raise TypeError: C{func} must be callable."""
    if not python.callable(func):
        raise TypeError('func must be callable')
    if isinstance(func, types.UnboundMethodType):
        setattr(func.im_func, '_pyamf_expose_request', True)
    else:
        setattr(func, '_pyamf_expose_request', True)
    return func

def execute_function(function_request):
    """Given a request created by
    `beanstalk_dispatch.common.create_request_body`, executes the
    request.  This function is to be run on a beanstalk worker."""
    dispatch_table = getattr(settings, 'BEANSTALK_DISPATCH_TABLE', None)
    if dispatch_table is None:
        raise BeanstalkDispatchError('No beanstalk dispatch table configured')
    for key in (FUNCTION, ARGS, KWARGS):
        if key not in function_request.keys():
            raise BeanstalkDispatchError('Please provide a {} argument'.format(key))
    function_path = dispatch_table.get(function_request[FUNCTION], '')
    if function_path:
        runnable = locate(function_path)
        if not runnable:
            raise BeanstalkDispatchError('Unable to locate function: {}'.format(function_path))
        args = function_request[ARGS]
        kwargs = function_request[KWARGS]
        if inspect.isclass(runnable):
            if issubclass(runnable, SafeTask):
                task = runnable()
            else:
                raise BeanstalkDispatchError('Requested task is not a SafeTask subclass: {}'.format(function_request[FUNCTION]))
        else:
            task = SafeTask()
            task.run = runnable
        task.process(*args, **kwargs)
    else:
        raise BeanstalkDispatchError('Requested function not found: {}'.format(function_request[FUNCTION]))

def safe_service(attr, default_value=None):
    """A **method** decorator for creating safe services.

    Given an attribute name, this returns a decorator for creating
    safe services. Namely, if a service that is not yet available is
    requested (like a database connection), then ``safe_service`` will
    log any errors and set the given attribute to ``default_value``.

    :param str attr: attribute name
    :param object default_value: default value to set
    :rtype: decorator"""
    def _(fun):
        @functools.wraps(fun)
        def run(self):
            try:
                return fun(self)
            except:
                logger.error(traceback.format_exc())
                setattr(self, attr, default_value)
        return run
    return _

def thread_local_property(name):
    """Creates a thread local ``property``."""
    name = '_thread_local_' + name
    def fget(self):
        try:
            return getattr(self, name).value
        except AttributeError:
            return None
    def fset(self, value):
        getattr(self, name).value = value
    return property(fget=fget, fset=fset)

def _orderedCleanDict(attrsObj):
    """-> dict with false-values removed

    Also evaluates attr-instances for false-ness by looking at the values of their properties"""
    def _filt(k, v):
        if attr.has(v):
            return not not any(attr.astuple(v))
        return not not v
    return attr.asdict(attrsObj, dict_factory=OrderedDict, recurse=False, filter=_filt)

def representCleanOpenAPIOperation(dumper, data):
    """Unpack nonstandard attributes while representing an OpenAPIOperation"""
    dct = _orderedCleanDict(data)
    if '_extended' in dct:
        for k, ext in list(data._extended.items()):
            dct[k] = ext
        del dct['_extended']
    return dumper.yaml_representers[type(dct)](dumper, dct)

def representCleanOpenAPIPathItem(dumper, data):
    """Unpack operation key/values before representing an OpenAPIPathItem"""
    dct = _orderedCleanDict(data)
    if '_operations' in dct:
        items = sorted(data._operations.items())
        for k, op in items:
            dct[k] = op
        del dct['_operations']
    return dumper.yaml_representers[type(dct)](dumper, dct)

def representCleanOpenAPIParameter(dumper, data):
    """Rename python reserved keyword fields before representing an OpenAPIParameter"""
    dct = _orderedCleanDict(data)
    d2 = OrderedDict()
    for k, v in dct.copy().items():
        if k == 'in_':
            d2['in'] = v
        else:
            d2[k] = v
    return dumper.yaml_representers[type(d2)](dumper, d2)

def representCleanOpenAPIObjects(dumper, data):
    """Produce a representation of an OpenAPI object, removing empty attributes"""
    dct = _orderedCleanDict(data)
    return dumper.yaml_representers[type(dct)](dumper, dct)

def mediaTypeHelper(mediaType):
    """Return a function that creates a Responses object;"""
    def _innerHelper(data=None):
        """Create a Responses object that contains a MediaType entry of the specified mediaType

        Convenience function for the most common cases where you need an instance of Responses"""
        ret = OpenAPIResponses()
        if data is None:
            data = {}
        ret.default.content[mediaType] = data
        return ret
    return _innerHelper

