def _split_chglog(path, title):
    """Split a RST file text in two parts. The title argument determine the
    split point. The given title goes in the bottom part. If the title is not
    found everything goes in the top part.

    Return a tuple with the top and bottom parts."""
    with path.open() as f:
        doc = f.readlines()
    has_title = False
    for idx, curr_line in enumerate(doc):
        if title in curr_line:
            prev_line = doc[idx - 1] if idx - 1 < len(doc) else '\n'
            next_line = doc[idx + 1] if idx + 1 < len(doc) else None
            if is_title(prev_line, curr_line, next_line):
                idx = idx if prev_line == '\n' else idx - 1
                has_title = True
                break
    if has_title:
        top, bottom = (doc[:idx], doc[idx:])
    else:
        top, bottom = (doc, [])
    return (''.join(top), ''.join(bottom))

def loads(content):
    """Load a Procfile from a string."""
    lines = _group_lines((line for line in content.split('\n')))
    lines = [(i, _parse_procfile_line(line)) for i, line in lines if line.strip()]
    errors = []
    duplicates = _find_duplicates(((i, line[0]) for i, line in lines))
    for i, process_type, j in duplicates:
        errors.append(''.join(['Line %d: duplicate process type "%s": ', 'already appears on line %d.']) % (i + 1, process_type, j + 1))
    for i, line in lines:
        process_type, env = (line[0], line[2])
        duplicates = _find_duplicates(((0, var[0]) for var in env))
        for _, variable, _ in duplicates:
            errors.append(''.join(['Line %d: duplicate variable "%s" ', 'for process type "%s".']) % (i + 1, variable, process_type))
    if errors:
        raise ValueError(errors)
    return {k: {'cmd': cmd, 'env': dict(env)} for _, (k, cmd, env) in lines}

def expect(*exprs):
    """Tests given sequence of conditions and stores results.

    Parameters
    ----------
    exprs: bool or tuple of (bool, str)
        Variable number of expressions evaluated. If a tuple first element is
        expression evaluated, second is the message displayed on failure in the report."""
    if len(exprs) == 2 and (isinstance(exprs[0], (bool, np.bool_)) and isinstance(exprs[1], str)):
        if not exprs[0]:
            _log_failure(arg_num=0, msg=exprs[1])
    else:
        for i, arg in enumerate(exprs):
            if isinstance(arg, (bool, np.bool_)):
                if not arg:
                    _log_failure(arg_num=i)
            elif isinstance(arg, (list, tuple)):
                if len(arg) != 2:
                    raise ValueError('Arguments to "expect" are invalid. They must be either an expression, or a tuple of length two as (expression, error_message)')
                expr, msg = arg
                if not expr:
                    _log_failure(arg_num=i, msg=msg)

def dispatk(keyer):
    """This is the decorator for the generic function and it accepts
    only one argument *keyer*, it'll be called with the same arguments
    of the function call and it must return an hashable object
    (int, tuple, etc.).

    Rhe generic function has a *register* method used to decorate the
    function for some specific keys.
    *register* accepts one or more keys and returns the decorated
    function."""
    calls = {}
    def _dispatk(main):
        def register(*keys):
            def _register(spec):
                for key in keys:
                    if key in calls:
                        raise ValueError('function already registered for %r' % (main.__name__, key))
                    calls[key] = spec
                return spec
            return _register
        @wraps(main)
        def run(*args, **kwargs):
            return calls.get(keyer(*args, **kwargs), main)(*args, **kwargs)
        run.register = register
        return run
    return _dispatk

def installer(cv, ctx, site, force=False):
    """Installer factory
    @param  cv:     Current version (The version of IPS we are installing)
    @type   cv:     ips_vagrant.common.version.Version
    @type   ctx:    ips_vagrant.cli.Context
    @param  site:   The IPS Site we are installing
    @type   site:   ips_vagrant.models.sites.Site
    @param  force:  Overwrite existing files / databases
    @type   force:  bool
    @return:    Installer instance
    @rtype:     ips_vagrant.installer.latest.Installer"""
    log = logging.getLogger('ipsv.installer')
    log.info('Loading installer for IPS %s', cv)
    iv = None
    for v in versions:
        vstring = '.'.join(map(str, v)) if v else 'latest'
        log.debug('Checking if version %s >= %s', vstring, cv.vstring)
        if v is None or v >= cv.vtuple:
            log.debug('Changing installer version to %s', vstring)
            iv = v
    log.info('Returning installer version %s', '.'.join(map(str, iv)) if iv else 'latest')
    return versions[iv](ctx, site, force)

def check_error(context: RunContext) -> int:
    """Runs after a sub-process exits

    Checks the return code; if it is different than 0, then a few things happen:

        - if the process was muted ("mute" is True), the process output is printed anyway
        - if "failure_ok" is True (default), then a SystemExist exception is raised

    :param context: run context
    :type context: _RunContext
    :return: process return code
    :rtype: int"""
    if context.return_code != 0:
        if context.mute:
            context.result_buffer += f': command failed: {context.return_code}'
        else:
            context.result_buffer += f'{context.cmd_as_string}: command failed: {context.return_code}'
        _LOGGER_PROCESS.error(context.result_buffer)
        _LOGGER_PROCESS.error(repr(context))
        if not context.failure_ok:
            _exit(context)
    else:
        if context.mute:
            context.result_buffer += f': success: {context.return_code}'
        else:
            context.result_buffer += f'{context.cmd_as_string}: success: {context.return_code}'
        _LOGGER_PROCESS.info(context.result_buffer)
    return context.return_code

def safe_import_module(path, default=None):
    """Try to import the specified module from the given Python path

    @path is a string containing a Python path to the wanted module, @default is
    an object to return if import fails, it can be None, a callable or whatever you need.

    Return a object or None"""
    if path is None:
        return default
    dot = path.rindex('.')
    module_name = path[:dot]
    class_name = path[dot + 1:]
    try:
        _class = getattr(import_module(module_name), class_name)
        return _class
    except (ImportError, AttributeError):
        warnings.warn('%s cannot be imported' % path, RuntimeWarning)
    return default

def querystring_update(request, **kwargs):
    """Output a URL-encoded querystring, updated with key:values from `kwargs`.

    From http://stackoverflow.com/a/24658162."""
    updated = request.GET.copy()
    for k, v in kwargs.items():
        updated[k] = v
    return updated.urlencode()

