def get_hints(code_list, k=10, hint_folder=HINT_FOLDER, current_tokens=None):
    """Fetch first k hints for given code_list"""
    def hint_score(v, size):
        """The formula for hint score"""
        return 1.0 - abs(v / (size + 1) - 0.5)
    if len(code_list) <= 1:
        return ([], [])
    if current_tokens is None:
        current_tokens = []
    size = min(len(code_list), MAX_HINT_SMAPLING_SIZE)
    sample = random.sample(code_list, size)
    hint_list = []
    capital_dict = {}
    for code in sample:
        path = gen_path(hint_folder, code)
        fp = os.path.join(path, code)
        try:
            with open(fp) as f:
                hints = set(f.read().strip().split('\n'))
                hint_list.extend([h.lower() for h in hints])
                capital_dict.update({hint.lower(): hint for hint in hints})
        except FileNotFoundError:
            logging.warning('FileNotFoundError: No such file: %r' % fp)
    document_freq = Counter(hint_list)
    score = [(capital_dict[k], hint_score(v, size)) for k, v in document_freq.items() if k not in current_tokens]
    if len(score) == 0:
        return ([], [])
    score.sort(key=lambda x: x[1], reverse=True)
    hints, scores = tuple(list(zip(*score[:k])))
    return (hints, scores)

def fetch(index, tokens):
    """Fetch the codes from given tokens"""
    if len(tokens) == 0:
        return set()
    return set.intersection(*[set(index.get(token, [])) for token in tokens])

def get_snippets(code_list, base=SNIPPET_FOLDER):
    """Get the snippets"""
    output = []
    for code in code_list:
        path = gen_path(base, code)
        fp = os.path.join(path, code)
        try:
            with open(fp) as f:
                output.append(f.read())
        except FileNotFoundError:
            output.append('')
            logging.warning('FileNotFoundError: No such file: %r' % fp)
    return output

def _ed1(token):
    """Return tokens the edit distance of which is one from the given token"""
    insertion = {letter.join([token[:i], token[i:]]) for letter in string.ascii_lowercase for i in range(1, len(token) + 1)}
    deletion = {''.join([token[:i], token[i + 1:]]) for i in range(1, len(token) + 1)}
    substitution = {letter.join([token[:i], token[i + 1:]]) for letter in string.ascii_lowercase for i in range(1, len(token) + 1)}
    transposition = {''.join([token[:i], token[i + 1:i + 2], token[i:i + 1], token[i + 2:]]) for i in range(1, len(token) - 1)}
    return set.union(insertion, deletion, substitution, transposition)

def _correct(token, term_freq):
    """Correct a single token according to the term_freq"""
    if token.lower() in term_freq:
        return token
    e1 = [t for t in _ed1(token) if t in term_freq]
    if len(e1) > 0:
        e1.sort(key=term_freq.get)
        return e1[0]
    e2 = [t for t in _ed2(token) if t in term_freq]
    if len(e2) > 0:
        e2.sort(key=term_freq.get)
        return e2[0]
    return token

def correct(tokens, term_freq):
    """Correct a list of tokens, according to the term_freq"""
    log = []
    output = []
    for token in tokens:
        corrected = _correct(token, term_freq)
        if corrected != token:
            log.append((token, corrected))
        output.append(corrected)
    return (output, log)

def _iterClass(cls, prefix=''):
    """Descend a Klein()'s url_map, and generate ConvertedRule() for each one"""
    iterableRules = [(prefix, cls, cls.app.url_map.iter_rules())]
    for prefix, currentClass, i in iter(iterableRules):
        for rule in i:
            converted = dumpRule(currentClass, rule, prefix)
            if converted.branch:
                continue
            if converted.subKlein:
                clsDown = namedAny(converted.subKlein)
                iterableRules.append((converted.rulePath, clsDown, clsDown.app.url_map.iter_rules()))
            yield converted

def urltool(classqname, filt, reverse):
    """Dump all urls branching from a class as OpenAPI 3 documentation

    The class must be given as a FQPN which points to a Klein() instance.

    Apply optional [FILT] as a regular expression searching within urls. For
    example, to match all urls beginning with api, you might use '^/api'"""
    filt = re.compile(filt or '.*')
    rootCls = namedAny(classqname)
    rules = list(_iterClass(rootCls))
    arr = []
    for item in sorted(rules):
        if item.subKlein:
            continue
        matched = filt.search(item.rulePath)
        matched = not matched if reverse else matched
        if matched:
            arr.append(tuple(item.toOpenAPIPath()))
    openapi3 = openapi.OpenAPI()
    for pathPath, pathItem in arr:
        if pathPath in openapi3.paths:
            openapi3.paths[pathPath].merge(pathItem)
        else:
            openapi3.paths[pathPath] = pathItem
    print(yaml.dump(openapi3, default_flow_style=False))

def literal_unicode_representer(dumper, data):
    """Use |- literal syntax for long strings"""
    if '\n' in data:
        return dumper.represent_scalar(u'tag:yaml.org,2002:str', data, style='|')
    else:
        return dumper.represent_scalar(u'tag:yaml.org,2002:str', data)

def wrap_rethink_errors(func_, *args, **kwargs):
    """Wraps rethinkdb specific errors as builtin/Brain errors

    :param func_: <function> to call
    :param args:  <tuple> positional arguments
    :param kwargs: <dict> keyword arguments
    :return: inherits from the called function"""
    try:
        return func_(*args, **kwargs)
    except WRAP_RETHINK_ERRORS as reql_err:
        raise ValueError(str(reql_err))

def qurl(url, add=None, exclude=None, remove=None):
    """Returns the url with changed parameters"""
    urlp = list(urlparse(url))
    qp = parse_qsl(urlp[4])
    add = add if add else {}
    for name, value in add.items():
        if isinstance(value, (list, tuple)):
            value = [smart_str(v) for v in value]
            qp = [p for p in qp if p[0] != name or p[1] not in value]
            qp.extend([(name, smart_str(val)) for val in value])
        else:
            qp = [p for p in qp if p[0] != name]
            qp.append((name, smart_str(value)))
    exclude = exclude if exclude else {}
    for name, value in exclude.items():
        if not isinstance(value, (list, tuple)):
            value = [value]
        value = [smart_str(v) for v in value]
        qp = [p for p in qp if p[0] != name or p[1] not in value]
    remove = remove if remove else []
    for name in remove:
        qp = [p for p in qp if p[0] != name]
    urlp[4] = urlencode(qp, True)
    return urlunparse(urlp)
